INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4, 'وَاحِدٌ', 'واحد', 'اسم فاعل', 'وحد', 'واحد', 'حد', '', '', 'Ta', 'مفرد', 'DnT', '', '', '"ون:ات:وُحْدَانٌ"', '', '', '', '', '', '', '', '', '". 1.""رَقْمٌ وَاحِـدٌ"" : أَوَّلُ العَدَدِ. 2.""حَضَرَ رَجُلٌ وَاحِدٌ"" : فَرْدٌ. 3.""هُوَ الوَاحِدُ الصَّمَدُ"" : مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى، أَيِ الْمُنْفَرِدُ الَّذِي لاَ نَظِيرَ لَهُ. 4.""حَضَرَ فِي السَّاعَةِ الوَاحِدَةِ"" : أَيْ بَعْدَ السَّاعَةِ الثَّانِيَةَ عَشْرَةَ زَوَالاً. 5.""هُم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5, 'وُحْدَانٌ', 'وحدان', 'اسم فاعل', '', 'وحدان', 'حدن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6, 'بَارٌّ', 'بار', 'اسم فاعل', 'برر', 'بار', 'بر', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":أَبْرَارٌ:بَرَرَةٌ"', '', '', '', '', '', '', '', '', '". ""تَرَكَ ابْناً بَارّاً"" : صَادِقاً وَصَالِحاً وَمُحْسِناً. ""اِبْنُكَ البارُّ يُحِبُّكَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7, 'أَبْرَارٌ', 'أبرار', 'اسم فاعل', '', 'ءبرار', 'برر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
