INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9, 'عَامِلٌ', 'عامل', 'اسم فاعل', 'عمل', 'عامل', 'عمل', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":عَوَامِلُ:عُمَّالٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '". 1.""عَامِلٌ فَعَّالٌ"" : الشَّيْءُ الَّذِي لَهُ فَعَالِيَّةٌ. 2.""الْعَامِلُ فِي النَّحْوِ"" : مَا يَقْتَضِي أَثَراً إِعْرَابِيّاً فِي الْكَلاَمِ. 3.""هُوَ عُضْوٌ عَامِلٌ فِي الْجَمْعِيَّةِ"" : لَهُ اشْتِرَاكٌ فِعْلِيٌّ وَمُسَاهَمَةٌ عَمَلِيَّةٌ فِيهَا. 4.""جَيْشٌ عَامِلٌ فِي الْمِنْطَقَةِ الْجَبَلِيَّةِ"" : الْجَيْشُ الَّذِي يَشْتَغِلُ فِي وَقْتِ السِّلْمِ. 5.""عَامِلُ الإِنْتَاجِ"" : العُنْصُرُ الَّذِي يُسْهِمُ فِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10, 'عَوَامِلُ', 'عوامل', 'اسم فاعل', '', 'عوامل', 'عمل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
