INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12, 'طَاحِنٌ', 'طاحن', 'اسم فاعل', 'طحن', 'طاحن', 'طحن', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":طَوَاحِنُمُؤَنَّثُالطَّاحِن"', '', '', 'ـو', '', '', '', '', 'Cv', '". 1.""فَقَدَ طَاحِنَةً مِنْ طَوَاحِنِهِ"" : ضِرْسٌ مِنْ اثْنَيْ عَشَرَ ضِرْساً تَلِي الضَّوَاحِكَ. 2.""دَارَتْ بَيْنَهُمْ حَرْبٌ طَاحِنَةٌ"" : حَرْبٌ شَدِيدَةٌ."', '');
