INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18, 'كَالٌّ', 'كال', 'اسم فاعل', 'كلل', 'كال', 'كل', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"كَالٌّ-كَالٌّ [ك ل ل]. ""صَارَ كَالاًّ مِنْ عَمَلِهِ الْمُرْهِقِ"" : تَعِباً، مُرْهَقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19, 'مُضِيفٌ', 'مضيف', 'اسم فاعل', 'ضيف', 'مضيف', 'مضف', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ـو:"', '', '', 'ـو', '', '', '', '', 'Cv', '". ""مُضِيفَةُ الطَّائِرَةِ"" : الفَتَاةُ العَامِلَةُ فِي شَرِكَةِ الطَّيَرَانِ، تَسْتَقْبِلُ الْمُسَافِرِينَ عَلَى مَتْنِ الطَّائِرَةِ وَتَعْتَنِي بِهِمْ أَثْنَاءَ السَّفَرِ وَتَمُدُّهُمْ بِمَا يَحْتَاجُونَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20, 'حارٌّ', 'حار', 'اسم فاعل', 'حرر', 'حار', 'حر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حارٌّ-حارٌّ، ةٌ [ح ر ر]. ""كانَ الجَوُّ حارّاً"" : شَديدَ الحَرارَةِ. ""عَادَ مِنْ بِلاَدٍ كَانَتْ شَمْسُهَا حَارَّةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21, 'خَرْخَار', 'خرخار', 'اسم فاعل', 'خرخر', 'خرخار', 'خرخر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"خَرْخَارٌ - [خ ر خ ر]. ""مَاءٌ خَرْخَارٌ"" : الْمَاءُ الْجَارِي جَرْياً شَدِيداً. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22, 'مطفف', 'مطفف', 'اسم فاعل', 'طفف', 'مطفف', 'مطف', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُطَفِّفونَ-مُطَفِّفونَ [ط ف ف].المطففين آية 1 وَيْلٌ لِلْمُطَفِّفِينَ (قرآن) : الَّذِينَ يَنْقُصُونَ الكَيْلَ: سُورَةٌ مِنْ سُوَرِ القُرْآنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23, 'مُخَصِّبٌ', 'مخصب', 'اسم فاعل', 'خصب', 'مخصب', 'مخصب', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُخَصِّبٌ-مُخَصِّبٌ [خ ص ب] (فا. مِنْ خَصَّبَ). ""مُخَصِّبُ التُّرْبَةِ"" : مَادَّة طَبيعِيَّةُ الأَصْلِ أَوْ صِنَاعِيَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24, 'مُبَيِّضٌ', 'مبيض', 'اسم فاعل', 'بيض', 'مبيض', 'مبض', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُبَيِّضٌ-مُبَيِّضٌ [ب ي ض] (فَا. مِنْ بَيَّضَ). 1.""مُبَيِّضُ النُّحَاسِ"" : العَامِلُ الَّذِي يَطْلِي النُّحَاسَ بِمَادَّةٍ صَاقِلَةٍ. 2.""مُبَيِّضُ الوَرَقِ"" : النَّاسِخُ. 3.""مُبَيِّضُ الأَقْمِشَةِ، الثِّيَابِ"" : مَنْ يُنَظِّفُهَا وَيَكْوِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25, 'باهِتٌ', 'باهت', 'اسم فاعل', 'بهت', 'باهت', 'بهت', 'فا. من بَهَتَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"باهِتٌ-باهِتٌ [ب هـ ت] (فا. من بَهَتَ). ""كَانَ بَاهِتَ اللَّوْنِ"" : شَاحِبَ اللَّوْنِ. ""أنْوَارٌ باهِتَةٌ"" ""اِبْتِسِامَةٌ باهِتَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26, 'بَارِي', 'باري', 'اسم فاعل', 'برأ', 'باري', 'بر', '', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"بَارٍ-بَارٍ، الباري [ب ر أ]. 1.""هُوَ اللَّهُ البَارِي"" : الخَالِقُ. 2.""بَارِي السَّهْمِ"" : نَاحِتُها. 3.""أَعْطِ القَوْسَ بَارِيَهَا"" : أي مَنْ يُحْسِنُ اسْتِعْمَالَهَا، وَتُقَالُ مَجَازاً فِي الأمُورِ العَامَّةِ، أَيْ فَوِّضْ شُغْلَكَ إلَى مَنْ يُتْقِنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27, 'براة', 'براة', 'اسم فاعل', '', 'براة', 'برة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
