INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(29, 'وَالِدٌ', 'والد', 'اسم فاعل', 'ولد', 'والد', 'لد', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '". ""هَذَا مَا قَرَّرَهُ الوَالِدُ بِاتِّفَاقٍ مَعَ الوَالِدَةِ"" : الأَبُ مَعَ الأُمِّ. وَمُثَنَّاهُمَا الوَالِدَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(30, 'مُكَارِي', 'مكاري', 'اسم فاعل', 'كري', 'مكاري', 'مكر', '', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '".: مَنْ يُكْرِي الدَّوَابَّ لِلْمُسَافِرِ أَوْ مَنْ يُصَاحِبُهُ،كَمَا يَغْلِبُ عَلَى الْحَمَّارِ والبَغَّالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(31, 'مُطَوِّفٌ', 'مطوف', 'اسم فاعل', 'طوف', 'مطوف', 'مطف', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '". ""مُطَوِّفُ الحُجَّاجِ"" : مَنْ يَقُومُ أَثْنَاءَ مَرَاسِمِ الْحَجِّ بِإِرْشَادِ الحُجَّاجِ إِلَى كُلِّ مَا يَتَعَلَّقُ بِمَنَاسِكِ الْحَجِّ."', '');
