INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(38, 'مُدِيرٌ', 'مدير', 'اسم فاعل', 'دور', 'مدير', 'مدر', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مُدَرَاءُ"', '', 'R', 'ـو', '', '', '', '', 'Cv', '".: مَسْؤُولٌ عَنْ إِدَارَةِ أَعْمَالِ مُؤَسَّسَةٍ أَوْ مَدْرَسَةٍ أَوْ قِسْمٍ مِنْ أَقْسَامِ وِزَارَةٍ مِنَ الوِزَارَاتِ."', '');
