INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(41, 'ثَاكِلٌ', 'ثاكل', 'اسم فاعل', 'ثكل', 'ثاكل', 'ثكل', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":ثَوَاكِلُ"', '', '', '', '', '', '', '', '', '". يَسْتَوِي فِيهِ الْمُذَكَّرُ وَالْمُؤَنَّثُ. ""رَجُلٌ ثَاكِلٌ"" : مَنْ فَقَدَ وَلَدَهُ. ""اِمْرَأةٌ ثَاكِلٌ"" ""لَوْ تَفَكَّرَ الأَبُ الثَّاكِلُ أنَّ ثَكْلَهُ جَزَاءُ ذَنْبٍ اِقْتَرَفَهُ"".(ن. محفوظ). "', '');
