INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(46, 'وَاكِلٌ', 'واكل', 'اسم فاعل', 'وكل', 'واكل', 'كل', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '". ""وَاكِلٌ أَمْرَهُ لِغَيْرِهِ"" : مُفَوِّضٌ، مُسَلِّمٌ بِهِ لِغَيْرِهِ."', '');
