INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(49, 'مُهَنْدِسٌ', 'مهندس', 'اسم فاعل', 'هندس', 'مهندس', 'مهندس', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '". : الْمُتَخَصِّصُ فِي عَمَلٍ مَّا حَسَبَ قَوَاعِدَ عِلْمِيَّةٍ، فَإِذَا كَانَ فِي المِعْمَارِ فَهُوَ: مُهَنْدِسٌ مِعْمَارٍيٌّ، وَإِذَا كَانَ فِي الزِّرَاعَةِ فَهُوَ: مُهَنْدِسٌ زِرَاعِيٌّ، وَإِذَا كَانَ فِي الكَهْرَبَاءِ فَهُوَ: مُهَنْدِسٌ كَهْرَبَائِيٌّ، وَإِذَا كَانَ فِي شَقِّ الطُّرُقِ وَهَنْدَسَتِهَا فَهُوَ: مُهَنْدِسُ الْجُسُورِ وَالطُّرُقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(50, 'نَاعِبٌ', 'ناعب', 'اسم فاعل', 'نعب', 'ناعب', 'نعب', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":نُعَّبٌ:نَوَاعِبُ"', '', '', '', '', '', '', '', '', '". ""نَاقَةٌ نَاعِبَةٌ"": سَرِيعَةٌ فِي سَيْرِهَا. ""بَعِيرٌ نَاعِبٌ""."', '');
