INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(53, 'مَارٌّ', 'مار', 'اسم فاعل', 'مرر', 'مار', 'مر', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". ""رَآهُ مَارّاً تَحْتَ الجِسْرِ"" : مُجْتَازاً، سَائِراً، عَابِراً. ""أَيُّهَا الْمَارُّونَ بَيْنَ الكَلِمَاتِ العَابِرَةِ آنَ لَكُمْ أَنْ تَنْصَرِفُوا"". (محمود درويش)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(54, 'مُتَشَائِلٌ', 'متشائل', 'اسم فاعل', '', 'متشاءل', 'متشل', '', '', 'Ta', 'جمع تكسير', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"ج: ـون، ـات. : هَذِهِ الكَلِمَةُ مَنْحُوتَةٌ مِنْ كَلِمَتَيْنِ هُمَا: الْمُتَشَائِمُ وَالْمُتَفَائِلُ. ""هَذِهِ شِيمَةُ عَائِلَتِنَا وَلِذَلِكَ سُمِّيَتْ بِعَائِلَةِ الْمُتَشَائِلِ"". (إميل حبيبي)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(55, 'مَارِدٌ', 'مارد', 'اسم فاعل', '', 'مارد', 'مرد', '', '', 'Ta', 'جمع تكسير', 'DnT', 'Pm', 'Pf', '":مَرَدَةٌ"', '', '', '', '', '', '', '', '', '"ج: ون، ات، مَرَدَةٌ. 1.""إِنَّهُ لَشَيْطَانٌ مَارِدٌ"" : العَاتِي، الطّاغِيَةُ، مَنْ يُجَاوِزُ بِطُغْيَانِهِ الْحَدَّ. 2.""بِنَاءٌ مَارِدٌ"" : مُرْتَفِعٌ، عَالٍ. ""وَالثَّوْرَةُ فِي نَفْسِهِ مَارِدٌ خَرَجَ مِنْ قُمْقُمٍ"" (ع. غلاب)."', ':لا جذر:لا مفرد');
