INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(83, 'طَائِلٌ', 'طائل', 'اسم فاعل', 'طول', 'طاءل', 'طل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":طَوَائِلُ"', '', '', '', '', '', '', '', '', '". 1.""رِبْحٌ طَائِلٌ"" : كَثِيرٌ. ""أَمْوَالٌ طَائِلَةٌ"" ""ثَرْوَةٌ طَائِلَةٌ"". 2.""يَقُومُ بِعَمَلٍ لاَ طَائِلَ فِيهِ"": لاَ فَائِدَةَ مِنْهُ، لاَ نَفْعَ يُرْجَى مِنْهُ. ""لَمْ أَفُزْ بِطَائِلٍ"" ""مَا هُوَ بِطَائِلٍ"" ""لاَ طَائِلَ تَحْتَهُ"" ""دُونَ طَائِلٍ"". 3.""لَمْ يَظْفَرْ بِطَائِلٍ"":"', '');
