INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(85, 'طَالِقٌ', 'طالق', 'اسم فاعل', 'طلق', 'طالق', 'طلق', '', '', 'Ta', 'مفرد', 'DnT', '', '', '"طُلَّقٌوطَوَالِقُ"', '', '', '', '', '', '', '', '', '". ""اِمْرَأَةٌ طَالِقٌ"" : مُطَلَّقَةٌ، أَيْ مُنْفَصِلَةٌ عَنْ زَوْجِهَا شَرْعاً. ""أَنْتِ طَالِقٌ"" ""اِمْرَأَةٌ طَالِقَةٌ""."', '');
