INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(127, 'سَابِقٌ', 'سابق', 'اسم فاعل', 'سبق', 'سابق', 'سبق', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":سَوَابِقُ"', '', '', '', '', '', '', '', '', '". 1.""كَانَ السَّابِقَ"" : الأوَّلَ الَّذِي سَبَقَ إلَى عَمَلٍ مَّا. 2. ""إنَّهَا سَابِقَةٌ خَطِيرَةٌ"" : حَالَةٌ أوْ تَصَرُّفٌ يُرْتَكَبُ لأَوَّلِ مَرَّةٍ وَلَمْ يُسْبَقْ إلَيْهِ. ""سَابِقَةٌ لاَ مَثِيلَ لَهَا"" : قَدْ يُقْصَدُ بِهَا هُنَا تَصَرُّفٌ سَلِيمٌ يُحْتَذَى بِهِ. 3"', '');
