INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(139, 'زامِلٌ', 'زامل', 'اسم فاعل', 'زمل', 'زامل', 'زمل', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":زَوامِلُ"', '', '', '', '', '', '', '', '', '". 1.""رَجُلٌ زامِلٌ"" : يَزْمَلُ غَيْرَهُ، أَيْ يَتْبَعُهُ. 2.""حَيَوانٌ زامِلٌ"" : مُتَأَرْجِحٌ في سَيْرِهِ كَأَنَّهُ يَعْرُجُ أَو يَغْمِزُ. 3.""يَسيرُ وَراءَ الزَّامِلَةِ"": الدَّابَّةُ وَغَيْرُها يُحْمَل عَلَيْها."', '');
