INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(143, 'مُرِيعٌ', 'مريع', 'اسم فاعل', 'روع', 'مريع', 'مرع', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُرِيعٌ-مُرِيعٌ، ةٌ [ر و ع]. ""جَاءَ بِأَمْرٍ مُرِيعٍ"" : مُخِيفٍ. ""بَدَأَ جَسَدُهُ يَنْزِفُ عَرَقاً بِشَكْلٍ مُرِيعٍ"" ""لِلْمُسْتَبِدِّ أَفْعَالٌ مُرِيعَةٌ فِي إِطْفَاءِ نُورِ العِلْمِ"". (ع. الكواكبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(144, 'مُرِيدٌ', 'مريد', 'اسم فاعل', 'رود', 'مريد', 'مرد', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '". ""هُوَ مُرِيدُهُ"" : مِنْ طَلَبَتِهِ وأَنْصَارِهِ وَمُنَاصِرِيهِ. ""كَانَ مِنْ مُرِيدِيهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(145, 'مُرِيحٌ', 'مريح', 'اسم فاعل', 'روح', 'مريح', 'مرح', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُرِيحٌ-مُرِيحٌ، ةٌ [ر و ح]. ""عَمَلٌ مُرِيحٌ"" : هَادِئٌ، هَنِيءٌ. ""جَلْسَةٌ مُرِيحَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(146, 'مُرْضِي', 'مرضي', 'اسم فاعل', 'رضو', 'مرضي', 'مرض', '', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُرْضٍ-مُرْضٍ، الْمُرْضِي، ةٌ [ر ض و]. ""عَمَلٌ مُرْضٍ"" : كَافٍ، مُقْنِعٌ، مَقْبُولٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(147, 'رَاجِي', 'راجي', 'اسم فاعل', 'رجو', 'راجي', 'رج', '', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". ""جَاءهُ رَاجِياً فَضْلَهُ"" : مُؤَمِّلاً."', '');
