INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(165, 'حادِثٌ', 'حادث', 'اسم فاعل', 'حدث', 'حادث', 'حدث', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":حوادِثُ"', '', '', '', '', '', '', '', '', '". 1.""لَمْ يَكُنْ حاضِراً أَثْناءَ الحادِثِ"" : أَثْناءَ وُقوعِ أَمْرٍ طارِىءٍ. 2.""وَصَلَتِ الشُّرْطَةُ إلى مَكانِ الحادِثِ"" : الْمَكانُ الَّذي حَدَثَ فيهِ الحَدَثُ، الفِعْلُ، أَيْ جَريمَةٌ أوْ سَرِقَةٌ أَوِ اصْطِدامُ سَيَّارَةٍ. ""كُلُّ حادِثٍ لاَ بُ"', '');
