INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(167, 'جَامِدٌ', 'جامد', 'اسم فاعل', 'جمد', 'جامد', 'جمد', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":جَوَامِدُ"', '', '', '', '', '', '', '', '', '". 1.""صَخْرٌ جَامِدٌ"" : لَيْسَ بِهِ نُمُوٌّ وَحَرَكَةٌ. 2. ""هُوَ جَامِدٌ كَالحَجَرِ"": لاَ يَتَحَرَّكُ، مَنْ لَهُ عَاطِفَةٌ مَتَحَجِّرَةٌ. ""جَامِدُ القَلْبِ"". 3.""جَامِدُ الفِكْرِ"" : الرَّافِضُ لِلتَّطَوُّرِ. 4.""جَامِدُ اليَدِ"": البَخِيلُ. 5.""لَيْسَ"" : فِعْلٌ جَامِدٌ، غَيْرُ مُتَصَرِّف مِثْلَ عَسَى وَنِعْمَ."', '');
