INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(172, 'تَافِهٌ', 'تافه', 'اسم فاعل', 'تفه', 'تافه', 'تفه', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":تَوَافِهُ:تَافِهَاتٌ"', '', '', '', '', '', '', '', '', '". 1.""هُوَ رَجُلٌ تَافِهٌ"" : غَيْرُ مُتَّزِنٍ، قَلِيلُ العَقْلِ لاَ قِيمَةَ لأَعْمَالِهِ، حَقِيرٌ. 2.""قَدَّمَ لَهُ طَعَاماً تَافِهاً"" : لاَ طَعْمَ لَهُ. 3.""يَهْتَمُّ بِقَضَايَا تَافِهَةٍ"": لاَ قِيمَةَ لَهَا."', '');
