INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(176, 'باهِظٌ', 'باهظ', 'اسم فاعل', 'بهظ', 'باهظ', 'بهظ', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":بَوَاهظُ"', '', '', '', '', '', '', '', '', '". 1. ""تَحَمَّلَ ثَمَناً باهِظاً"" : غالياً مُفْرِطاً. ""كَلَّفَهُ العُرْسُ نَفَقَاتٍ باهِظَةً"". 2.""كَلَّفَهُ أَمْراً باهِظاً"" : شاقّاً. 3. ""كانَتِ الأسْعَارُ بَاهِظَةً"" : مُرْتَفِعَةً جِدّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(177, 'بَوَاهظُ', 'بواهظ', 'اسم فاعل', '', 'بواهظ', 'بهظ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
