INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(181, 'باكِي', 'باكي', 'اسم فاعل', 'بكي', 'باكي', 'بك', '', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":بُكَاةٌ:باكِياتٌ"', '', '', '', '', '', '', '', '', '". 1.""جاءَ يَشْتَكِي باكِياً"" : دَمْعُهُ يَسِيلُ عَلَى خَدِّهِ بِسَبَبِ ألَمٍ أو حُزْنٍ. 2.""هَرْوَلَتِ الباكِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(182, 'بُكَاةٌ', 'بكاة', 'اسم فاعل', '', 'بكاة', 'بكة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
