INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(184, 'مُبْكِي', 'مبكي', 'اسم فاعل', 'بكي', 'مبكي', 'مبك', '', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". ""عَمَلٌ مُبْكٍ"" : يَبْعَثُ عَلَى البُكَاءِ. ""كَانَ سُلُوكُهُ وَحَرَكَاتُهُ مِنَ الْمُبْكِيَاتِ"" ""ظَلَّ يَسْتَرْجِعُ مَا شَاهَدَه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(185, 'بَاصِرٌ', 'باصر', 'اسم فاعل', 'بصر', 'باصر', 'بصر', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":بَوَاصِرُ"', '', '', '', '', '', '', '', '', '"1.""لَمْحٌ بَاصِرٌ"" : ذُو بَصَرٍ وَتَحْديقٍ. 2.""لَقِيَ مِنْهُ لَمْحاً باصراً"" : أمْراً واضِحاً. 3.""لَهُ عَيْنٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(186, 'بَوَاصِرُ', 'بواصر', 'اسم فاعل', '', 'بواصر', 'بصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(187, 'بصار', 'بصار', 'اسم فاعل', '', 'بصار', 'بصر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(188, 'بصرة', 'بصرة', 'اسم فاعل', '', 'بصرة', 'بصرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(189, 'مُبْدِعٌ', 'مبدع', 'اسم فاعل', 'بدع', 'مبدع', 'مبدع', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". 1.""سُبْحَانَ مُبْدِعِ الكَوْنِ"" : خَالِقُهُ، مُنْشِئُهُ. 2.""مُبْدِعٌ لآلاَتٍ جَدِيدَةٍ"": مُخْتَرِعٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(190, 'مُتَآلِفٌ', 'متآلف', 'اسم فاعل', 'ألف', 'متءءلف', 'متآلف', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ـ:"', '', '', '', '', '', '', '', '', '". 1.""مُتَآلِفٌ مَعَ النَّغَمِ"" : مُنْسَجِمٌ. 2.""أَلْوَانٌ مُتَآلِفَةٌ"" : مُتَجَانِسَةٌ. ""أَنْغَامٌ مُتَآلِفَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(191, 'مُعْتَادٌ', 'معتاد', 'اسم فاعل', 'عود', 'معتاد', 'معتد', 'فَا. مفع. مِن اِعْتَادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(فَا. مفع. مِن اِعْتَادَ). 1.""مُعْتَادُ السَّفَرِ"" : مَنْ أَلِفَ وَتَعَوَّدَ السَّفَرَ ... 2.""كَالْمُعْتَادِ"" : أَيْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(192, 'مُمْتَدٌّ', 'ممتد', 'اسم فاعل', 'مدد', 'ممتد', 'ممتد', 'فَا. مفع. من اِمْتَدَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُمْتَدٌّ-مُمْتَدٌّ، ةٌ [م د د] (فَا. مفع. من اِمْتَدَّ). 1. ""حَبْلٌ مُمْتَدٌّ"" : مزيدٌ فِيهِ، مَبْسُوطٌ خِلاَف مَلْفُوف. 2.""حَقْلٌ مُمْتَدٌّ"": فَسِيحٌ وَاسِعٌ. 3.""الْمُمْتَدُّ"" : بَحْرٌ مِنْ بُحُورِ الشِّعْرِ وَزْنُهُ : فَاعِلُنْ فَاعِلاتُن*فَاعِلُنْ فَاعِلاَتُنْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(193, 'مُمْتَصٌّ', 'ممتص', 'اسم فاعل', 'مصص', 'ممتص', 'ممتص', 'فَا. مفع. من اِمْتَصَّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مُمْتَصٌّ-مُمْتَصٌّ، ةٌ [م ص ص] (فَا. مفع. من اِمْتَصَّ). ""تُرْبَةٌ مُمْتَصَّةٌ"" : أَيْ مَاصَّةٌ لِلْمَاءِ، مُبْتَلِعَةٌ لَهُ. ""ثَوْبٌ مُمْتَصٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(194, 'مُبْتَدِئٌ', 'مبتدئ', 'اسم فاعل', 'بدأ', 'مبتدء', 'مبتد', 'فَا. مِن اِبْتَدَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِبْتَدَأَ). ""لاَ يَزَالُ مُبْتَدِئاً فيِ العَمَلِ"" : حَدِيثَ العَهْدِ بِالعَمَلِ، أَيْ فِي بِدَايَةِ مُزَاوَلَتِهِ لَهُ. ""الفَضْلُ لِلْمُبْتَدِي وَإِنْ أَحْسَنَ الْمُقْتَدِي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(195, 'مُبْتَدِعٌ', 'مبتدع', 'اسم فاعل', 'بدع', 'مبتدع', 'مبتدع', 'فَا. مِن اِبْتَدَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِبْتَدَعَ). 1.""مُبْتَدِعُ آلَةٍ"" : مُخْتَرِعُهَا. 2.""مُبْتَدِعٌ فِي الكَلاَمِ"" : مُجَدِّدٌ. ""مَنْ جَرَى عَلَى لِسَانِهِ كَلاَمٌ يَسْتَحْسِنُهُ فَلاَ يَعْجَبَنَّ بِهِ إِعْجَابَ الْمُبْتَدِعِ"". 3.""رَجُلٌ مُبْتَدِعٌ"" : مَنْ يَأْتِي بِالبِدَعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(196, 'مُبْتَسِمٌ', 'مبتسم', 'اسم فاعل', 'بسم', 'مبتسم', 'مبتسم', 'فَا مِن اِبْتَسَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا مِن اِبْتَسَمَ). ""جَاءَ مُبْتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(197, 'مُبْتَكِرٌ', 'مبتكر', 'اسم فاعل', 'بكر', 'مبتكر', 'مبتكر', 'فَا. مِن اِبْتَكَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِبْتَكَرَ). ""مُبْتَكِرُ آلَةٍ جَدِيدَةٍ"" : مُخْتَرِعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(198, 'مُبْتَهِجٌ', 'مبتهج', 'اسم فاعل', 'بهج', 'مبتهج', 'مبتهج', 'فَا. مِن اِبْتَهَجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِبْتَهَجَ). ""مُبْتَهِجٌ بِمَا رَأَى"" : مَسْرُورٌ، سَعِيدٌ، فَرِحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(199, 'مُبْتَهِلٌ', 'مبتهل', 'اسم فاعل', 'بهل', 'مبتهل', 'مبتهل', 'فَا. مِن اِبْتَهَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِبْتَهَلَ). ""مُبْتَهِلٌ إِلَى الله"" : مُتَضَرِّعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(200, 'مُبْرِئٌ', 'مبرئ', 'اسم فاعل', 'برأ', 'مبرء', 'مبر', 'فا. من أبرأ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(201, 'مُبْرِقٌ', 'مبرق', 'اسم فاعل', 'برق', 'مبرق', 'مبرق', 'فا. من أَبْرَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُبْرِقٌ-مُبْرِقٌ [ب ر ق] (فا. من أَبْرَقَ). 1.""ضَوْءٌ مُبْرِقٌ"" : لاَمِعٌ. 2.""الجِهَازُ الْمُبْرِقُ"" : جِهَازٌ لاَسِلْكِيٌّ يَلْتَقِطُ الإِشَارَاتِ الْمُرْسَلَةَ وَيُحَوِّلُهَا إِلَى حُرُوفٍ مَطْبَعِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(202, 'مُبْرِمٌ', 'مبرم', 'اسم فاعل', 'برم', 'مبرم', 'مبرم', 'فَا. مِنْ أبرم', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(203, 'مُبْصِرٌ', 'مبصر', 'اسم فاعل', 'بصر', 'مبصر', 'مبصر', 'فَا. مِنْ أَبْصَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَبْصَرَ). ""مُبْصِرٌ بِحَقَائِقِ الأُمُورِ"" : مُدْرِكٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(204, 'مُبْطِلٌ', 'مبطل', 'اسم فاعل', 'بطل', 'مبطل', 'مبطل', 'فا. من أَبْطَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَبْطَلَ). ""مُبْطِلٌ لِلْعَمَلِ"" : مُفْسِدٌ لَهُ. ""مَا خَلَقَ اللَّهُ العَقْلَ إِلاَّ لِيَشْهَدَ بِالْحَقِّ لِلْمُحِقِّ وَالبَاطِلِ لِلْمُبْطِلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(205, 'مُبْغِضٌ', 'مبغض', 'اسم فاعل', 'بغض', 'مبغض', 'مبغض', 'فَا. مِنْ أَبْغَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَبْغَضَ). ""مُبْغِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(206, 'مُبْهِجٌ', 'مبهج', 'اسم فاعل', 'بهج', 'مبهج', 'مبهج', 'فَا. مِنْ أَبْهَجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُبْهِجٌ-مُبْهِجٌ [ب هـ ج] (فَا. مِنْ أَبْهَجَ). ""عَمَلٌ مُبْهِجٌ"" : مُفْرِحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(207, 'مُبْهِرٌ', 'مبهر', 'اسم فاعل', 'بهر', 'مبهر', 'مبهر', 'فَا. مِنْ أَبْهَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُبْهِرٌ-مُبْهِرٌ، ةٌ [ب هـ ر] (فَا. مِنْ أَبْهَرَ). ""عَمَلٌ مُبْهِرٌ"" : يُبْهِرُ، يُثِيرُ العَقْلَ وَالنَّظَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(208, 'مُتَّبِعٌ', 'متبع', 'اسم فاعل', 'تبع', 'متبع', 'متبع', 'فَا. مِن اِتَّبَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِتَّبَعَ). ""مَا زَالَ مُتَّبِعاً مَذْهَبَهُ"" : مُرِيداً، نَصِيراً، تَابِعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(209, 'مُتَّجِهٌ', 'متجه', 'اسم فاعل', 'وجه', 'متجه', 'متجه', 'فَا. مِن اِتَّجَهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِتَّجَهَ). ""مُتَّجِهٌ إِلَى الْمَعْمَلِ"" : يَسِيرُ فِي اتِّجَاهِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(210, 'مُتَّحِدٌ', 'متحد', 'اسم فاعل', 'وحد', 'متحد', 'متحد', 'فَا. مِن اِتَّحَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِتَّحَدَ). 1.""مُتَّحِدٌ مَعَهُ فِي السَّرَّاءِ وَالضَّرَّاءِ"" : مُتَّفِقٌ مَعَهُ. 2.""الدُّوَلُ العَرَبِيَّةُ أَعْضَاءٌ فِي الأُمَمِ الْمُتَّحِدَةِ"" : تَجَمُّعٌ دَوْلِيٌّ يَضُمُّ دُوَلَ العَالَمِ الْمُسْتَقِلَّةِ، لَهُ قَوَانِينُهُ، يَعْم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(211, 'مُتَّكِئٌ', 'متكئ', 'اسم فاعل', 'وكأ', 'متكء', 'متك', 'فَا. مِن اِتَّكَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِتَّكَأَ). ""مُتَّكِئٌ عَلَى "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(212, 'مُتَّزِنٌ', 'متزن', 'اسم فاعل', 'وزن', 'متزن', 'متزن', 'فَا. مِن اِتَّزَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِتَّزَنَ). 1.""مُتَزِّنٌ فِي سُلُوكِهِ"" : رَزِينٌ، مُسْتَقِيمُ الفِطْرَةِ وَالغَرِيزَةِ. 2.""يَسِيرُ بِخُطىً مُتَّزِنَةٍ"" : دَقِيقَةٍ، مَحْسُوبَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(213, 'مُتَّسِعٌ', 'متسع', 'اسم فاعل', '', 'متسع', 'متسع', 'فَا. مِن اِتَّسَعَ.', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"ج: ـون، ـات. (فَا. مِن اِتَّسَعَ). ""مَلْعَبٌ مُتَّسِعٌ لِآلاَفِ الْمُتَفَرِّجِين"" : وَاسِعٌ، فَسِيحٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(214, 'مُتَّسِقٌ', 'متسق', 'اسم فاعل', 'وسق', 'متسق', 'متسق', 'فَا. مِن اِتِّسَقَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِن اِتِّسَقَ). 1.""أَثَاثُ البَيْتِ مُتَّسِقٌ"" : مُرَتَّبٌ، مُتَنَاسِقٌ. 2.""جِسْمٌ مُتَّسِقٌ"" : جِسْمٌ أَطْرَافُهُ فِي تَنَاسُبٍ وَتَنَاسُقٍ مَعَ بَعْضِهَا، رَشِيقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(215, 'مُتَّشِحٌ', 'متشح', 'اسم فاعل', 'وشح', 'متشح', 'متشح', 'فَا. مِن اِتَّشَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِتَّشَحَ). 1.""كَانَ مُتَّشِحاً وَسَطَ الضُّيُوفِ"" : لاَ بِساً الوِشَاحَ. 2.""مُتَّشِحٌ بِثَوْبِهِ"" : لاَبِسٌ لِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(216, 'مُتَّصِلٌ', 'متصل', 'اسم فاعل', 'وصل', 'متصل', 'متصل', 'فَا. مِن اِتَّصَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِتَّصَلَ). ""عَمَلٌ مُتَّصِلُ الْحَلَقَاتِ"" : مُتَوَاصِلٌ، مُتَتَابِعٌ. ""الأَفْعَالُ الْمَحْمُودَةُ مُتَّصِلَةُ النَّفْعِ وَالشَّرَفِ وَالفَضِيلَةِ"". (الجاحظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(217, 'مُتْعِبٌ', 'متعب', 'اسم فاعل', 'تعب', 'متعب', 'متعب', 'فا. من أَتْعَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَتْعَبَ). ""عَمَلٌ مُتْعِبٌ"" : شَاقٌّ، مُرْهِقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(218, 'مُتَّفِقٌ', 'متفق', 'اسم فاعل', 'وفق', 'متفق', 'متفق', 'فَا. مِن اِتَّفَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِتَّفَقَ). ""مُتَّفِقٌ مَعَهُ"" : مُؤَيِّدٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(219, 'مُتَّقِدٌ', 'متقد', 'اسم فاعل', 'وقد', 'متقد', 'متقد', 'فَا. مِن اِتَّقَدَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِن اِتَّقَدَ). 1.""ضَوْءٌ مُتَّقِدٌ"" : مُتَلَأْلِئٌ. 2. ""نَارٌ مُتَّقِدَةٌ"" : مُشْتَعِلَةٌ. 3.""حُبٌّ مُتَّقِدٌ"" : حُبٌّ عَنِيفٌ، قَوِيٌّ، مُلْتَهِبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(220, 'مُتْقِنٌ', 'متقن', 'اسم فاعل', 'تقن', 'متقن', 'متقن', 'فَا. مِنْ أَتْقَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَتْقَنَ). ""صَانِعٌ مُتْقِنٌ لِعَمَلِهِ"" : دَقِيقٌ فِيهِ، مُدَقِّقٌ، مُجِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(221, 'أواثم', 'أواثم', 'اسم فاعل', '', 'ءواثم', 'ثم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(222, 'مُتْلِفٌ', 'متلف', 'اسم فاعل', 'تلف', 'متلف', 'متلف', 'فَا. مِنْ أَتْلَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ج:"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَتْلَفَ). ""مُتْلِفٌ لِكُلِّ الْمَزْرُوعَاتِ"" : الَّذِي يُتْلِفُهَا وَيُهْلِكُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(223, 'مُتَّهِمٌ', 'متهم', 'اسم فاعل', 'تهم،وهم', 'متهم', 'متهم', 'فَا. مِن اِتَّهَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِتَّهَمَ). ""هُوَ الْمُتَّهِمُ الوَحِيدُ"" : الَّذِي يَتَّهِمُ غَيْرَهُ بِارْتِكَابِ جَرِيمَةٍ أَوْ ذَنْبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(224, 'آتِي', 'آتي', 'اسم فاعل', 'أتي', 'ءاتي', 'آت', 'فَا. من أَتَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"آتٍ-آتٍ، الآتي، ةٌ [أ ت ي] (فَا. من أَتَى). 1.""هُوَ آتٍ لاَ رَيْبَ فِي ذَلِكَ"" : مُقْبِل، قَادِمٌ. ""كُلُّ آتٍ قَرِيبٌ"". (مثل) ""سَأزُورُكَ فِي الشَّهْرِ الآتِي"" : فِي الشَّهْرِ الْمُقبِلِ. 2. ""اِقْرَإِ العِبَارَةَ الآتِيَةَ"" : التَّالِيَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(225, 'أواتي', 'أواتي', 'اسم فاعل', '', 'ءواتي', 'ت', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(226, 'مُثِيرٌ', 'مثير', 'اسم فاعل', 'ثور', 'مثير', 'مثر', 'فَا. مِنْ أَثَارَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَثَارَ). 1.""عَمَلٌ مُثِيرُ لِلْأَعْصَابِ"" : مُقْلِقٌ، مُزْعِجٌ. 2.""مُثِيرٌ لِلْفِتَنِ أَيْنَمَا حَلَّ وَارْتَحَلَ"" : مُهَيِّجٌ، مُحَرِّضٌ. 3.""جَمَالُ مُثِيرٌ"" : فَاتِنٌ، أَيْ يَفْتِنُ العُقُولَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(227, 'مُؤَثِّرٌ', 'مؤثر', 'اسم فاعل', 'أثر', 'مءثر', 'مثر', 'فا. من أَثَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَثَّرَ). 1.""لَهُ أُسْلُوبٌ مُؤَثِّرٌ فِي النَّاسِ"" : فَعَّالٌ، ذُو أَثَرٍ.‏ ""وَسَائِلُ الإِعْلاَمِ لَهَا قُوَّةٌ مُؤَثِّرَةٌ فِي الجُمْهُورِ. 2.""وَدَّعْنَاهُ وَدَاعاً مُؤَثِّراً"" : أَيْ وَدَاعاً تَرَكَ أَثَراً فِي النَّفْسِ. 3.""لَمْ تَكُنْ أَحْكَامُهُ خَالِيَةً مِنْ مُؤَثِّرَاتٍ ذَاتِيَّةٍ وَمَوْضُوعِيَّةٍ"" : مِنْ عَوَامِلَ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(228, 'مُثْرِي', 'مثري', 'اسم فاعل', 'ثري', 'مثري', 'مثر', 'فَا. مِنْ أَثْرَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَثْرَى). ""رَجُلٌ مُثْرٍ"" : غَنِيٌّ، أَيْ مَنْ يَمْلِكُ ثَرْوَةً كَبِيرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(229, 'مُثْلِجٌ', 'مثلج', 'اسم فاعل', 'ثلج', 'مثلج', 'مثلج', 'فَا. مِنْ أَثْلَجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَثْلَجَ). ""جَوٌّ مُثْلِجٌ"" : فِيهِ ثَلْجٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(230, 'آثِمٌ', 'آثم', 'اسم فاعل', 'أثم', 'ءاثم', 'آثم', 'فَا. مِنْ أَثِمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"آثِمٌ-آثِمٌ [أ ث م] (فَا. مِنْ أَثِمَ). ""رَجُلٌ آثِمٌ"" : مُرْتَكِبُ الإثْمِ وَالْمَعْصِيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(231, 'مُجْدِبٌ', 'مجدب', 'اسم فاعل', 'جدب', 'مجدب', 'مجدب', 'فَا. مِنْ أَجْدَبَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَجْدَبَ). ""مَكَانٌ مُجْدِبٌ"" : قَاحِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(232, 'أثام', 'أثام', 'اسم فاعل', '', 'ءثام', 'ثم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(233, 'أثمة', 'أثمة', 'اسم فاعل', '', 'ءثمة', 'ثمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(234, 'مُثْمِر', 'مثمر', 'اسم فاعل', 'ثمر', 'مثمر', 'مثمر', 'فَا. مِنْ أَثْمَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَثْمَرَ). 1.""شَجَرٌ مُثْمِرٌ"" : يُعْطِي ثَمَراً. 2."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(235, 'مجُيِبٌ', 'مجيب', 'اسم فاعل', 'جوب', 'مجيب', 'مجب', 'فا. من أَجَابَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَجَابَ). ""مُجِيب الدُّعَاءِ"" : مَنْ يُجِيبُ الدُّعَاءَ أَوِ النِّدَاءَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(236, 'مُجِيدٌ', 'مجيد', 'اسم فاعل', 'جود', 'مجيد', 'مجد', 'فَا. مِنْ أَجَادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَجَادَ). ""مُجِيدٌ فِي شِعْرِهِ"" : مَنْ يَأْتِي بِالجَيِّدِ فِي شِعْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(237, 'مُجِيرٌ', 'مجير', 'اسم فاعل', 'جور', 'مجير', 'مجر', 'فا. من أَجَارَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُجِيرٌ-مُجِيرٌ [ج و ر] (فا. من أَجَارَ). ""جَاءهُ مُجِيراً فَأَفْرَجَ كُرْبَتَهُ"" : مُغيثاً، مُنْقِذاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(238, 'مُجِيزٌ', 'مجيز', 'اسم فاعل', 'جوز', 'مجيز', 'مجز', 'فا. من أَجَازَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُجِيزٌ-مُجِيزٌ [ج و ز] (فا. من أَجَازَ). 1. ""هَذَا مَا قَرَّرَهُ الْمُجِيزُ لِيُحَافِظَ عَلَى الْعَهْدِ"" : الْوَلِيُّ، الْوَصِيُّ. 2.: الْقَيِّمُ بِأَمْرِ اليَتِيمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(239, 'مُجْتَرّ', 'مجتر', 'اسم فاعل', 'جرر', 'مجتر', 'مجتر', 'فَا. مِن اِجْتَرَّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِجْتَرَّ). 1.""البَقَرَةُ حَيَوَانٌ مُجْتَرٌّ"" : تَجْتَرُّ طَعَامَهَا، أَيْ تُعِيدُهُ مِنْ بَطْنِهَا فَتَمْضَغُهُ مَرَّةً ثَانِيَةً. 2.""الْحَيَوَانَاتُ الْمُجْتَرَّةُ"" : هِيَ حَيَوَانَاتٌ فِقَرِيَّةٌ مِنْ رُتْبَةِ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(240, 'مُجْحِفٌ', 'مجحف', 'اسم فاعل', 'جحف', 'مجحف', 'مجحف', 'فَا. مِنْ أَجْحَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَجْحَفَ). ""صَدَرَ حُكْمٌ مُجْحِفٌ فِي حَقِّهِ"" : حُكْمٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(241, 'مُحْتَالٌ', 'محتال', 'اسم فاعل', 'حول', 'محتال', 'محتل', 'فَا. مِن اِحْتَالَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِحْتَالَ). ""رَجُلٌ مُحْتَالٌ"" : مَنْ يَلْجَأُ إِلَى أَسَالِيبِ الاحْتِيَالِ وَالْمُرَاوَغَةِ لِتَحْقِيقِ أَهْدَافِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(242, 'مُؤَجِّرٌ', 'مؤجر', 'اسم فاعل', 'أجر', 'مءجر', 'مجر', 'فا. من أَجَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَجَّرَ). ""مُؤَجِّرٌ لِلْبَيْتِ بِأَلْفِ دِرْهَمٍ"" : الْمُكْتَرِي لَهُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(243, 'مُجْرِمٌ', 'مجرم', 'اسم فاعل', 'جرم', 'مجرم', 'مجرم', 'فَا. مِنْ أَجْرَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَجْرَمَ). ""أُلْقِيَ القَبْضُ عَلَى الْمُجْرِمِ"" : الَّذِي ارْتَكَبَ جُرْم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(244, 'مُجْفِلٌ', 'مجفل', 'اسم فاعل', 'جفل', 'مجفل', 'مجفل', 'فَا. مِنْ أَجَفَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُجْفِلٌ-مُجْفِلٌ، ةٌ [ج ف ل] (فَا. مِنْ أَجَفَلَ). 1.""فَرَسٌ مُجْفِلٌ"" : نَافِرٌ. 2.""رَجُلٌ مُجْفِلٌ"" : فَزِعٌ، مَذْعُورٌ. ""يَزْحَفُ الخَوْفُ كَالهَوْلِ فَتَلْتَقِطُهُ حَوَاسُّنَا فَتَتَيَقَّظُ مُجْفِلَةً"". (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(245, 'مُؤَجِّلٌ', 'مؤجل', 'اسم فاعل', 'أجل', 'مءجل', 'مجل', 'فَا. مِنْ أَجَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَجَّلَ). ""مُؤَجِّلٌ لِأَعْمَالِهِ"" : مُؤَخِّرٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(246, 'مُجْمِعٌ', 'مجمع', 'اسم فاعل', 'جمع', 'مجمع', 'مجمع', 'فَا. مِنْ أَجَمَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُجْمَعٌ-مُجْمَعٌ، ةٌ [ج م ع]. 1.""أَمْرٌ مُجْمَعٌ عَلَيْهِ"" : مُتَّفَقٌ عَلَيْهِ. 2.""قَضَايَا مُجْمَعَةٌ"" : مَجْزُومٌ بِهَا وَمَحْكُومٌ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(247, 'مُجْهِضٌ', 'مجهض', 'اسم فاعل', 'جهض', 'مجهض', 'مجهض', 'فَا. مِنْ أَجْهَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَجَاهِضُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَجْهَضَ). 1.""اِمْرَأَةٌ مُجْهِضٌ، ةٌ"" : مَنْ أًلْقَتْ وَلَدَهَا قَبْلَ اكْتِمَالِهِ. 2.""طَبِيبٌ مُجْهِضٌ"" : مَنْ يَتَوَلَّى إِجْهَاضَ النِّسَاءِ. 3.""مُجْهِضٌ لِكُلِّ الأَعْمَالِ"" : مَنْ يَقُومُ بِتَدْمِيرِ الأَعْمَالِ وَتَحْطيمِها وَيَقِفُ دُونَ إِنْجَازِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(248, 'مَجَاهِضُ', 'مجاهض', 'اسم فاعل', '', 'مجاهض', 'مجهض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(249, 'مُحِبٌّ', 'محب', 'اسم فاعل', 'حبب', 'محب', 'محب', 'فَا. مِنْ أَحَبَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَحَبَّ). 1.""مُحِبٌّ وَلْهَانُ"" : العَاشِقُ الْمُتَيَّمُ. 2.""مُحِبٌّ لِأَهْلِ العِلْمِ"" : مُتَعَلِّقٌ بِحُبٍّ وَتَفَانٍ. 3. ""مُحِبٌّ لِذَاتِهِ"" : الأَنَانِيُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(250, 'مُحْتَاطٌ', 'محتاط', 'اسم فاعل', 'حوط', 'محتاط', 'محتط', 'فَا. مِن اِحْتَاطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِحْتَاطَ). ""محْتَاطٌ فِي أَمْرهِ"" : مُحْتَرِزٌ، حَذِرٌ. ""كَانَ حَذِراً هَيَّاباً وَمُتَحَفِّظاً مُحْتَاطاً"". (طه حسين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(251, 'مُحْدِثٌ', 'محدث', 'اسم فاعل', 'حدث', 'محدث', 'محدث', 'فَا. مِنْ أحْدَثَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أحْدَثَ). ""مُحْدِثٌ لِأَسَالِيب جَدِيدَةٍ"" : مُجَدِّدٌ، مُبْدِعٌ. ""كُلُّ حَادِثٍ لاَ بُدَّ لَهُ مِنْ مُحْدِثٍ"". (ابن طفيل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(252, 'مُحْتَجٌّ', 'محتج', 'اسم فاعل', 'حجج', 'محتج', 'محتج', 'فَا. مِن اِحْتَجَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِحْتَجَّ). ""مُحْتَجٌّ عَلَى سُلُوكِهِ وَتَصَرُّفِهِ"" : مُسْتَنْكِرٌ، مُعَارِضٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(253, 'مُحْتَدٌّ', 'محتد', 'اسم فاعل', 'حدد', 'محتد', 'محتد', 'فَا. مِن اِحْتَدَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِحْتَدَّ). 1.""مُحْتَدٌّ فِي كَلاَمِهِ"" : مُغْتَاظٌ. 2.""مَعْرَكَةٌ مُحْتَدَّةٌ"" : مَعْرَكَةٌ شَدِيدَةٌ وَحَادَّةٌ، حَامِيَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(254, 'مُحْتَرِفٌ', 'محترف', 'اسم فاعل', 'حرف', 'محترف', 'محترف', 'فَا. مِن اِحْتَرَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِحْتَرَفَ). ""لاَعِبٌ مُحْتَرِفٌ"" : مَنِ اتَّخَذَ رِيَاضَةً مَّا حِرْفَةً لَهُ. ""مُمَثِّلٌ مُحْتَرِفٌ"" ""صِحَافِيٌّ مُحْتَرِفٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(255, 'مُحْتَرِمٌ', 'محترم', 'اسم فاعل', 'حرم', 'محترم', 'محترم', 'فَا. مِن اِحْتَرَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِحْتَرَمَ). ""مُحْتَرِمٌ لِلْقَوَانِينِ"" : مَنْ يَقِفُ مَوْقِفَ الاحْتِرَامِ وَالتَّقْدِيرِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(256, 'مُحْتَسِبٌ', 'محتسب', 'اسم فاعل', 'حسب', 'محتسب', 'محتسب', 'فَا. مِن اِحْتَسَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِحْتَسَبَ). 1.""مُحْتَسِبٌ لِلأُمُورِ"" : مُقَدِّرٌ لِعَوَاقِبِهَا. 2.""اِحْتَكَمُوا إِلَى الْمُحْتَسِبِ"" : شَخْصِيَّةٌ لَهَا دِرَايَةٌ بِمِهَنِ الْمَدِينَةِ وَضَبْطِ الْمَوَازِينِ، تُرَاقِبُ سَيْرَ الْمُعَامَلاَتِ التِّجَارِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(257, 'مُحْتَشِمٌ', 'محتشم', 'اسم فاعل', 'حشم', 'محتشم', 'محتشم', 'فَا. مِن اِحْتَشَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِحْتَشَمَ). ""رَجُلٌ مُحْتَشِمٌ"" : مُسْتَحْيٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(258, 'مُحْتَفِلٌ', 'محتفل', 'اسم فاعل', 'حفل', 'محتفل', 'محتفل', 'فَا. مِن اِحْتَفَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِحْتَفَلَ). ""مُحْتَفِلٌ بِعِيدِ مِيلاَدِهِ"" : مُقِيمٌ لِحَفْلَةٍ بِالْمُنَاسَبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(259, 'مُحْتَقِرٌ', 'محتقر', 'اسم فاعل', 'حقر', 'محتقر', 'محتقر', 'فَا. مِن اِحْتَقَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِحْتَقَرَ). ""مُحْتَقِرٌ لِأَعْمَالِهِ"" : مُسْتَهِينٌ بِهَا، مُزْدَرٍ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(260, 'مُحْتَكِرٌ', 'محتكر', 'اسم فاعل', 'حكر', 'محتكر', 'محتكر', 'فَا. مِن اِحْتَكَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِحْتَكَرَ). ""تَاجِرٌ مُحْتَكِرٌ لِلْمَوَادِّ الغِذَائِيَّةِ"" : مُتَفَرِّدٌ بِالتَّصَرُّفِ فِيهَا، مُسَيْطِرٌ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(261, 'مُخْبِرٌ', 'مخبر', 'اسم فاعل', 'خبر', 'مخبر', 'مخبر', 'فا. من أَخْبَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَخْبَرَ). 1.""مُخْبِرٌ فِي جِهَازِ الأَمْنِ"" : مَنْ يَأْتِي بِالأَخْبَارِ بَعْدَ التَّحَرِّي وَالكَشْفِ عَنْ مَوَاطِنِهَا. 2.""مُخْبِرٌ صَحَفِيٌّ"" : مُزَوِّدُ الجَرِيدَةِ بِالأَخْبَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(262, 'مُحْدِقٌ', 'محدق', 'اسم فاعل', 'حدق', 'محدق', 'محدق', 'فَا. مِنْ أَحْدَقَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَحْدَقَ). ""شَعَرَ بِخَطَرٍ مُحْدِقٍ"" : وَشِيكٍ، قَرِيب الوُقُوعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(263, 'مُحْرِقٌ', 'محرق', 'اسم فاعل', 'حرق', 'محرق', 'محرق', 'فَا. مِنْ أَحْرَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَحْرَقَ). ""ما تَزَالُ الشَّمْسُ حَارَّةً مُحْرِقَةً فِي الخَارِجِ"" : حَارِقَةٌ، شَدِيدَةُ الاحْتِرَاقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(264, 'مُحْرِمٌ', 'محرم', 'اسم فاعل', 'حرم', 'محرم', 'محرم', 'فَا. مِنْ أَحْرَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مِحْرَمٌ-مِحْرَمٌ [ح ر م]. ""مِحْرَمُ الْحَاجِّ"" : لِبَاسُ الإِحْرَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(265, 'مُحْزِنٌ', 'محزن', 'اسم فاعل', 'حزن', 'محزن', 'محزن', 'فَا. مِنْ أَحْزَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُحْزِنٌ-مُحْزِنٌ، ةٌ [ح ز ن] (فَا. مِنْ أَحْزَنَ). ""أَمْرٌ مُحْزِنٌ"" : مُؤْلِمٌ، مُؤْسِفٌ. ""حَادِثَةٌ مُحْزِنَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(266, 'مُحْسِنٌ', 'محسن', 'اسم فاعل', 'حسن', 'محسن', 'محسن', 'فَا. مِنْ أَحْسَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَحْسَنَ). 1.""رَجُلٌ مُحْسِنٌ"" : يَقُومُ بِأَعْمَالِ الخَيْرِ.التوبة آية 120 إِنَّ الله لاَ يُضِيعُ أَجْرَ الْمُحْسِنِينَ (قرآن). 2.: اِسْمُ عَلَمٍ لِلْمُذَكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(267, 'مُحِقٌّ', 'محق', 'اسم فاعل', 'حقق', 'محق', 'محق', 'فَا. مِنْ أَحَقَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَحَقَّ). ""هُوَ مُحِقٌّ فِي حُكْمِهِ"" : مُصِيبٌ أَيْ كَانَ عَلَى صَوَابٍ. ""يَشْهَدُ بِالْحَقِّ لِلْمُحِقِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(268, 'مُحْمَرٌّ', 'محمر', 'اسم فاعل', 'حمر', 'محمر', 'محمر', 'فَا. مِن اِحْمَرَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُحْمَرُّ-مُحْمَرُّ، ةٌ [ح م ر] (فَا. مِن اِحْمَرَّ). ""عَيْنٌ مُحْمَرَّةٌ"": بِهَا حُمْرَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(269, 'مُحْوِلٌ', 'محول', 'اسم فاعل', 'حول', 'محول', 'محل', 'فا. مِن أَحْوَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُحْوِلٌ-مُحْوِلٌ [ح و ل] (فا. مِن أَحْوَلَ). ""صَبِيٌّ مُحْوِلٌ"" : مَنْ أَتَى عَلَيْهِ الْحَوْلُ، العَامُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(270, 'مُخِيفٌ', 'مخيف', 'اسم فاعل', 'خوف', 'مخيف', 'مخف', 'فَا. مِنْ أَخَافَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُخِيفٌ-مُخِيفٌ، ةٌ [خ و ف] (فَا. مِنْ أَخَافَ). ""أَمْرٌ مُخِيفٌ"": مُفْزِعٌ، مَخُوفٌ. ""سَمِعَ صَوْتَهَا الْمُخِيفَ وَهِيَ تَزْعَقُ فِي وَجْهِ الْجِيرَانِ"". (ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(271, 'مُخْتَلِفٌ', 'مختلف', 'اسم فاعل', 'خلف', 'مختلف', 'مختلف', 'فَا. مِن اِخْتَلَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِخْتَلَفَ). 1.""مُخْتَلِفٌ عَنْ غَيْرِهِ"" : مُتَبَايِنٌ، مُتَمَيِّزٌ. ""أَنْوَاعٌ مِنَ الطُّيُورِ مُخْتَلِفَةُ الفَصَائِلِ"". 2.""شَكْلٌ مُخْتَلِفُ الأَضْلاَعِ"" : أَضْلاَعُهُ تَخْتَلِفُ عَنْ بَعْضِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(272, 'مُخْتَبِئٌ', 'مختبئ', 'اسم فاعل', 'خبأ', 'مختبء', 'مختب', 'فَا. مِن اِخْتَبَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِخْتَبَأَ). ""مُخْتَبِئٌ فِي جُحْرِهِ"" : مُخْتَفٍ. ""مُخْتَبِئٌ يَا أُمَّاهُ! إِنَّمَا حَمَلْتُ السِّلاَحَ لِأَنِّي مَلِلْتُ اخْتِبَاءكُمْ"" (إميل حبيبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(273, 'مُخَتَبِرٌ', 'مختبر', 'اسم فاعل', 'خبر', 'مختبر', 'مختبر', 'فَا. مِن اِخْتَبَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِخْتَبَرَ). ""مُخْتَبِرٌ لِمَعْلُومَاتِهِ"" : مُمْتَحِنٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(274, 'مُخْتَرِعٌ', 'مخترع', 'اسم فاعل', 'خرع', 'مخترع', 'مخترع', 'فَا. مِن اِخْتَرَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِخْتَرَعَ). ""مُخْتَرِعُ التَّلْفَزَةِ"" : أَيْ أَوَّلُ مَنْ أَنْشَأَهَا وَفَكَّرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(275, 'مُخْتَرِقٌ', 'مخترق', 'اسم فاعل', 'خرق', 'مخترق', 'مخترق', 'فَا. مِن اِخْتَرَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِخْتَرَقَ). ""مُخْتَرِقٌ لِلصُّفُوفِ"" : خَارِقُهَا، نَافِذٌ فِي وَسَطِهَا. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(276, 'مُخْتَزِلٌ', 'مختزل', 'اسم فاعل', 'خزل', 'مختزل', 'مختزل', 'فَا. مِن اِخْتَزَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِخْتَزَلَ): مَنْ يَخْتَزِلُ عَمَلاً مَّا وَيُلَخِّصُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(277, 'مُخْتَصّ', 'مختص', 'اسم فاعل', 'خصص', 'مختص', 'مختص', 'فَا. مِن اِخْتَصَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِخْتَصَّ). 1.""مُخْتَصٌّ بِالرِّيَاضِيَّاتِ"" : مُتَخَصِّصُ فِيهَا. 2.""رَاجِعِ الجِهَاتِ الْمُخْتَصَّةَ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(278, 'مُخْتَصِرٌ', 'مختصر', 'اسم فاعل', 'خصر', 'مختصر', 'مختصر', 'فَا. مِن اِخْتَصَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِخْتَصَرَ). ""مُخْتَصِرٌ لِلشُّرُوحِ الطَّوِيلَةِ"" : مُوجِزٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(279, 'مُخْتَفِي', 'مختفي', 'اسم فاعل', 'خفي', 'مختفي', 'مختف', 'فَا. مِن اِخْتَفَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِخْتَفَى). ""مَا زَالَ مُخْتَفِياً عَنِ الأَنْظَارِ"" : مُتَوَارِياً، أَيْ لاَ يَرَاهُ أَحَدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(280, 'مُخْتَلِطٌ', 'مختلط', 'اسم فاعل', 'خلط', 'مختلط', 'مختلط', 'فَا. مِن اِخْتَلَطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِخْتَلَطَ). 1.""مُخْتَلِطٌ بِالأَجَانِبِ"" : مُعَاشِرٌ لَهُمْ. 2.""تَعْلِيمٌ مُخْتَلِطٌ"" : تَعْلِيمٌ عَامٌّ لِلذُّكُورِ وَالإِنَاثِ مَعاً. 3.""مَوَادُّ مُخْتَلِطَةٌ"": مَمْزُوجَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(281, 'مُدِينٌ', 'مدين', 'اسم فاعل', 'دين', 'مدين', 'مدن', 'فا. من أَدَانَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَدَانَ). ""أَدَّى الدَّيْنَ إِلَى"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(282, 'مُخْتَلِقٌ', 'مختلق', 'اسم فاعل', 'خلق', 'مختلق', 'مختلق', 'فَا. مِن اِخْتَلَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِخْتَلَقَ). ""مُخْتَلِقٌ لِلأَخْبَارِ"" : مُلَفِّقٌ لَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(283, 'مُخْتَنِقٌ', 'مختنق', 'اسم فاعل', 'خنق', 'مختنق', 'مختنق', 'فَا. مِن اِخْتَنَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِخْتَنَقَ). ""مَاتَ مُخْتَنِقاً بِالدُّخَانِ"" : مَنِ اخْتَنَقَ، مَنْ ضَاقَتْ أَنْفَاسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(284, 'مُخْجِلٌ', 'مخجل', 'اسم فاعل', 'خجل', 'مخجل', 'مخجل', 'فَا. مِنْ أَخْجَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُخْجِلٌ-مُخْجِلٌ، ةٌ [خ ج ل] (فَا. مِنْ أَخْجَلَ). ""قَامَ بِعَمَلٍ مُخْجِلٍ"" : مَعِيبٍ، شَائِنٍ. ""مَوْقِفٌ مُخْجِلٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(285, 'مُؤَخِّرٌ', 'مؤخر', 'اسم فاعل', 'أخر', 'مءخر', 'مخر', 'فا. من أَخَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَخَّرَ). ""مُؤَخِّرٌ لِلْعَمَلِ"" : مُؤَجِّلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(286, 'مُخْرِجٌ', 'مخرج', 'اسم فاعل', 'خرج', 'مخرج', 'مخرج', 'فَا. مِنْ أَخْرَجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَخْرَجَ). ""مُخْرِجُ الفِلْمِ"" : مَنْ يَقُومُ بِتَرْتِيبِ الْمَشَاهِدِ وَال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(287, 'مُخْطِئٌ', 'مخطئ', 'اسم فاعل', 'خطأ', 'مخطء', 'مخط', 'فَا. مِنْ أَخْطَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَخْطَأَ). ""مُخْطِئٌ فِي حِسَابِهِ"" : وَقَعَ فِي خَطَإٍ. ""إِمَّا أَنْ يَكُونَ مُخْطِئاً أَوْ مُصِيباً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(288, 'مُخْفِقٌ', 'مخفق', 'اسم فاعل', 'خفق', 'مخفق', 'مخفق', 'فَا. مِنْ أَخْفَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَخْفَقَ). ""مُخْفِقٌ فِي عَمَلِهِ"" : الفَاشِلُ الَّذِي لَمْ يُفْلِحْ فِي تَحْقِيقِ مَا يُرِيدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(289, 'مُخِلٌّ', 'مخل', 'اسم فاعل', 'خلل', 'مخل', 'مخل', 'فَا. مِنْ أَخَلَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَخَلَّ). 1.""مُخِلٌّ بِالآدَابِ"" : مُخَالِفٌ لَهَا. 2.""مُخِلٌّ بِالنِّظَامِ"": الْمُشَوِّشُ، الْمُعَرْقِلُ لِلنِّظَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(290, 'مُخْلِصٌ', 'مخلص', 'اسم فاعل', 'خلص', 'مخلص', 'مخلص', 'فَا. مِنْ أَخْلَصَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَخْلَصَ). 1.""مُخْلِصٌ فِي عَمَلِهِ"" : صَادِقٌ، مُجِدٌّ. 2.""مُخْلِصٌ لِأَصْدِقَائِهِ"" : وَفِيٌّ لَهُمْ. ""الصَّدِيقُ الْمُخْلِصُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(291, 'مُؤَدِّبٌ', 'مؤدب', 'اسم فاعل', 'أدب', 'مءدب', 'مدب', 'فَا. مِنْ أَدَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَدَّبَ). ""مُؤَدِّبُ الأَطْفَالِ"" : مُعَلِّمُهُمْ. ""مُعَلِّمُ نَفْسِهِ وَمُؤَدِّبُهَا أَحَقُّ بِالإجْلاَلِ"" (ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(292, 'مُدْبِرٌ', 'مدبر', 'اسم فاعل', 'دبر', 'مدبر', 'مدبر', 'فَا. مِنْ أَدْبَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَدْبَرَ). ""وَلَّى مُدْبِراً"" : وَلَّى عَلَى عَقِبِهِ.النمل آية 10فَلَمَّا رَآهَا تَهْتَزُّ كَأَنَّهَا جَانٌّ وَلَّى مُدْبِراً (قرآن) مِكَرٍّ مِفَرٍّ مُقْبِلٍ مُدْبِـرٍ مَعـاً*كَجُلْمودِ صَخْرٍ حَطَّهُ السَّيْلُ مِنْ عل (امرؤ القيس)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(293, 'مُدَّثِّرٌ', 'مدثر', 'اسم فاعل', 'دثر', 'مدثر', 'مدثر', 'فَا. مِن اِدَّثَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِدَّثَّرَ).المدثر آية 2 يَا أَيُّهَا الْمُدَّثِّرُ قُمْ فَأَنْذِرْ (قرآن) : يَا أَيُّهَا الْمُلْتَفُّ بِالدِّثَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(294, 'مُدْرِكٌ', 'مدرك', 'اسم فاعل', 'درك', 'مدرك', 'مدرك', 'فَا. مِنْ أَدْرَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَدْرَكَ). "" مُدْرِكٌ لِلْأُمُورِ"" : فَاهِمٌ لَهَا، وَاعٍ بِهَا. ""مُدْرِكٌ عَوَاقِبَ الأُمُورِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(295, 'مُدَّعِي', 'مدعي', 'اسم فاعل', 'دعو', 'مدعي', 'مدع', 'فَا. مِن اِدَّعَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُدَّعٍ-مُدَّعٍ، الْمُدَّعِي، ةٌ [د ع و] (فَا. مِن اِدَّعَى). 1.""وَقَفَ الْمُدَّعِي وَالْمُدَّعَى عَلَيْهِ أَمَامَ القَاضِي"" : مَنْ أَقَامَ الدَّعْوَى، الْمُخَاصِمُ. 2.""رَجُلٌ مُدَّعٍ"" : مَنْ يَدَّعِي مَا لَيْسَ فِيهِ. ""مُدَّعِي العِلْمِ"". 3.""كَانَتْ مُدَاخَلَةُ الْمُدَّعِي العَامِّ شَدِيدَةَ اللَّهْجَةِ"" : النَّائِبُ العَامُّ، وَكِيلُ الدَّوْلَةِ، وَكِيلُ الْمَلِكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(296, 'مُدْقِعٌ', 'مدقع', 'اسم فاعل', 'دقع', 'مدقع', 'مدقع', 'فَا. مِنْ أَدْقَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُدْقِعٌ-مُدْقِعٌ [د ق ع] (فَا. مِنْ أَدْقَعَ). 1.""رَجُلٌ مُدْقِعٌ"": حَقِيرٌ، أَنْفُهُ فِي التُّرَابِ. 2.""جُوعٌ مُدْقِعٌ"" : شَدِيدٌ. ""فَقْرٌ مُدْقِعٌ"". لاَ تَحِلُّ الْمَسْأَلَةُ إِلاَّ لِذِي فَقْرٍ مُدْقِعٍ . (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(297, 'مُدْمِنٌ', 'مدمن', 'اسم فاعل', 'دمن', 'مدمن', 'مدمن', 'فَا. مِنْ أَدْمَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَدْمَنَ). 1.""مُدْمِنٌ عَلَى شُرْبِ الخَمْرِ"" : الْمُدَاوِمُ عَلَيْهَا. ""يَرَى الْمُدْمِنُ فِي عَنَاقِيدِ الكَرْمِ سَحَابَةً مِنَ الخَمْرِ"". (م. ص. الرافعي). 2.""مُدْمِنٌ عَلَى الْمُخَدِّرَاتِ"" : المتَعَاطِي لَهَا عَلَى الدَّوَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(298, 'مُدْهِشٌ', 'مدهش', 'اسم فاعل', 'دهش', 'مدهش', 'مدهش', 'فَا. مِنْ أَدْهَشَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَدْهَشَ). ""عَمَلٌ مُدْهِشٌ"" : مُثِيرٌ، غَيْرُ مُتَوَقَّعٍ، مَا يَبْعَثُ عَلَى الدَّهْشَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(299, 'مُؤَدِّي', 'مؤدي', 'اسم فاعل', 'أدي', 'مءدي', 'مد', 'فا. من أَدَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُؤَدٍّ-مُؤَدٍّ، الْمُؤَدِّي، ةُ [أ د ي] (فا. من أَدَّى). ""طَرِيقٌ مُؤَدٍّ إِلَى الشَّاطِئِ"" : مُوصِلٌ إِلَى..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(300, 'مُذِيعٌ', 'مذيع', 'اسم فاعل', 'ذيع', 'مذيع', 'مذع', 'فَا. مِنْ أَذَاعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَذَاعَ). ""أَذَاعَ الْمُذِيعُ آخِرَ الأَخْبَارِ"" : مَنْ يُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(301, 'مُذْعِنٌ', 'مذعن', 'اسم فاعل', 'ذعن', 'مذعن', 'مذعن', 'فَا. مِنْ أَذْعَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَذْعَنَ). ""مُذْعِنٌ لِآرَاءِ خَصْمِهِ"" : خَاضِعٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(302, 'مُذِمٌّ', 'مذم', 'اسم فاعل', 'ذمم', 'مذم', 'مذم', 'فَا. مِنْ أَذَمَّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُذِمٌّ-مُذِمٌّ [ذ م م] (فَا. مِنْ أَذَمَّ). ""أَمْرٌ مُذِمٌّ"" : مَعِيبٌ، مَذْمُومٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(303, 'مُؤَذِّنٌ', 'مؤذن', 'اسم فاعل', 'أذن', 'مءذن', 'مذن', 'فا. من أَذَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَذَّنَ). ""نَادَى الْمُؤَذِّنُ لِلصَّلاَةِ"" : الْمُنَادِي لَهَا فِي وَقْتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(304, 'مُذْنِبٌ', 'مذنب', 'اسم فاعل', 'ذنب', 'مذنب', 'مذنب', 'فَا. مِنْ أَذْنَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَذْنَبَ). ""تَأَكَّدَ أَنَّهُ مُذْنِبٌ"" : أَنَّهُ ارْتَكَبَ ذَنْباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(305, 'مُذْهِلٌ', 'مذهل', 'اسم فاعل', 'ذهل', 'مذهل', 'مذهل', 'فا. من أَذْهَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَذْهَلَ). ""عَمَلٌ مُذْهِلٌ"" : مُدْهِشٌ، مُثِيرٌ، مُحَيِّرٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(306, 'مُؤْذِي', 'مؤذي', 'اسم فاعل', 'أذي', 'مءذي', 'مذ', 'فَا. مِنْ أذي', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أذي). ""مُؤْذٍ بِسُلُوكِهِ وَكَلاَمِهِ"" : مَنْ يُلْحِقُ الأَذَى بِغَيْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(307, 'مُؤَارِبٌ', 'مؤارب', 'اسم فاعل', 'أرب', 'مءارب', 'مرب', 'فا. من آرَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من آرَبَ). ""رَجُلٌ مُؤَارِبٌ"" : مُحْتَالٌ، مُخَاتِلٌ، مُخادِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(308, 'مُرْتَاحٌ', 'مرتاح', 'اسم فاعل', 'روح', 'مرتاح', 'مرتح', 'فا. مِن اِرْتَاحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِن اِرْتَاحَ). 1.""عَاشَ مُرْتَاحَ البَالِ"" : نَاعِمَ البَالِ، مُطْمَئِنّاً... 2.""مُرْتَاحُ الضَّمِيرِ"" : أَيْ لاَ شَيْءَ يُؤَنِّبُ ضَمِيرَهُ، هَادِئُ البَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(309, 'مُرْتَاعٌ', 'مرتاع', 'اسم فاعل', 'روع', 'مرتاع', 'مرتع', 'فَا. مِن اِرْتَاعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِرْتَاعَ). ""لَبِثَ فِي مَكَانِهِ حَائِراً مُرْتَاعاً"" : فَزِعاً، مُرَوَّعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(310, 'مُرْتَبِطٌ', 'مرتبط', 'اسم فاعل', 'ربط', 'مرتبط', 'مرتبط', 'فَا. مِن اِرْتَبَطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِرْتَبَطَ). 1.""مُرْتَبِطٌ بِعَمَلِهِ"" : مُتَّصِلٌ بِهِ. 2.""مُرْتَبِطٌ بِهَا"" : مُتَعَلِّقٌ بِهَا. 3.""لَمْ يَكُنْ مُرْتَبِطاً بِعَمَلٍ سَابِقٍ"" : أَيْ لَمْ يَكُنْ مَشْغُولاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(311, 'مُرْتَفِعٌ', 'مرتفع', 'اسم فاعل', 'رفع', 'مرتفع', 'مرتفع', 'فَا. مِن اِرْتَفَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِرْتَفَعَ). 1.""مَكَانٌ مُرْتَفِعٌ"" : عَالٍ. 2.""سِعْرٌ مُرْتَفِعٌ"" : غَالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(312, 'مُرْتَبِكٌ', 'مرتبك', 'اسم فاعل', 'ربك', 'مرتبك', 'مرتبك', 'فَا. مِن اِرْتَبَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِرْتَبَكَ). ""مُرْتَبِكٌ فِي عَمَلِهِ"" : مُضْطَرِبٌ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(313, 'مُرْتَجٌّ', 'مرتج', 'اسم فاعل', 'رجج', 'مرتج', 'مرتج', 'فَا. مِن اِرْتَجَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُرْتَجٌّ-مُرْتَجٌّ [ر ج ج] (فَا. مِن اِرْتَجَّ). ""جَاءَ مُرْتَجّاً"" : مُرْتَجِفاً، مُرْتَعِداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(314, 'مُرْتَجِلٌ', 'مرتجل', 'اسم فاعل', 'رجل', 'مرتجل', 'مرتجل', 'فَا. مِن اِرْتَجَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُرْتَجَلٌ-مُرْتَجَلٌ، ةٌ [ر ج ل] (مفع. مِن اِرْتَجَلَ). ""خِطَابٌ مُرْتَجَلٌ"" : تَمَّ إِلْقَاؤُهُ دُونَ تَحْضِيرٍ، تِلْقَائِيّاً. ""خُطْبَةٌ مُرْتَجَلَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(315, 'مُرْتَدٌّ', 'مرتد', 'اسم فاعل', 'ردد', 'مرتد', 'مرتد', 'فَا. مِن اِرْتَدَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِرْتَدَّ). ""مُرْتَدٌّ عَنْ دِينِهِ"" : مَنِ اعْتَنَقَ دِيناً أَوْ مَذْهَباً ثُمَّ ارْتَدَّ عَنْهُ، تَرَاجَعَ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(316, 'مُرْتَزِقٌ', 'مرتزق', 'اسم فاعل', 'رزق', 'مرتزق', 'مرتزق', 'فَا. مِن اِرْتَزَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِرْتَزَقَ). ""جُنْدِيٌّ مُرْتَزِقٌ"" : جُنْدِيٌّ يَتَّخِذُ مِنَ الْحَرْبِ وَسِيلَةً لِلارْتِزَاقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(317, 'مُرْتَشِي', 'مرتشي', 'اسم فاعل', 'رشو', 'مرتشي', 'مرتش', 'فَا. مِن اِرْتَشَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِرْتَشَى). ""لَعَنَ اللهُ الرَّاشِيَ وَالْمُرْتَشِيَ"" : الَّذِي أَخَذَ الرَّشْوَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(318, 'مُرْتَعِبٌ', 'مرتعب', 'اسم فاعل', 'رعب', 'مرتعب', 'مرتعب', 'فَا. مِن اِرْتَعَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِرْتَعَبَ). ""خَرَجَ مُرْتَعِباً مِنَ الكَهْفِ"" : مَفْزُوعاً. ""كَانَ كُلٌّ مَنْ فِي البَيْتِ خَائِفاً مُرْتَعِباً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(319, 'مُرْتَعِدٌ', 'مرتعد', 'اسم فاعل', 'رعد', 'مرتعد', 'مرتعد', 'فَا. مِن اِرْتَعَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِرْتَعَدَ). ""مُرْتَعِدٌ مِنَ البَرْدِ"" : مُرْتَعِشٌ، أَيْ بِهِ رَعْشَةٌ، رَعْدَةٌ. ""مُرْتَعِدٌ مِنَ الخَوْفِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(320, 'مُرْتَعِشٌ', 'مرتعش', 'اسم فاعل', 'رعش', 'مرتعش', 'مرتعش', 'فَا. مِن اِرْتَعَشَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِرْتَعَشَ). ""مُرْتَعِشٌ مِنَ البَرْدِ"" : مُرْتَعِدٌ مِنَ البَرْدِ، أَيْ بِهِ رَعْدَةٌ، رَعْشَةٌ. ""أَتَأَوَّهُ مُرْتَعِشاً، وَثِيَابِي تَلْصَقُ فِي جَسَدِي الْمُضْطَرِبِ"". (أمل دنقل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(321, 'مُرْعِبٌ', 'مرعب', 'اسم فاعل', 'رعب', 'مرعب', 'مرعب', 'فَا. مِنْ أَرْعَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَرْعَبَ). ""أَمْرٌ مُرْعِبٌ"" : مُخِيفٌ، مُفْزِعٌ. ""وَلَدُ مُرْعِبٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(322, 'مُرْتَقِبٌ', 'مرتقب', 'اسم فاعل', 'رقب', 'مرتقب', 'مرتقب', 'فَا. مِن اِرْتَقَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِرْتَقَبَ). ""مُرْتَقِبٌ لِمَا سَيَحْدُثُ"" : مُنْتَظِرٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(323, 'مُرْتَقِي', 'مرتقي', 'اسم فاعل', 'رقي', 'مرتقي', 'مرتق', 'فَا. مِن اِرْتَقَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِرْتَقَى). ""مُرْتَقٍ لِلصِّعَابِ"" : مَنْ يَرْتَقِي الصِّعَابَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(324, 'مُرْتَكِبٌ', 'مرتكب', 'اسم فاعل', 'ركب', 'مرتكب', 'مرتكب', 'فَا. مِن اِرْتَكَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِرْتَكَبَ). ""مُرْتَكِبُ الْمَعَاصِي وَالذُّنُوبِ"" : مُقْتَرِفُها، مُقارِفُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(325, 'مُرْتَكِزٌ', 'مرتكز', 'اسم فاعل', 'ركز', 'مرتكز', 'مرتكز', 'فَا. مِن اِرْتَكَزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِرْتَكَزَ). ""مُرْتَكِزٌ عَلَى دَعَائِمَ مَتِينَةٍ"" : مُعْتَمِدٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(326, 'مُرْتَهِنٌ', 'مرتهن', 'اسم فاعل', 'رهن', 'مرتهن', 'مرتهن', 'فَا. مِن اِرْتَهَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِرْتَهَنَ). ""تَاجِرٌ مُرْتَهِنٌ"" : دائِنٌ.ارْتَهَنَ يَرْتهِنُ ارْتِهَاناً  :- الشيءَ منه: أخذه بديْن؛ ارتهن لوحات الفنان حتى يسدد هذا دينه.- بالأمر: تقيَّد به؛ ترتهن موافقتي على المشروع بموافقة شريكي في العمل.', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(327, 'مُؤَرِّخٌ', 'مؤرخ', 'اسم فاعل', 'أرخ', 'مءرخ', 'مرخ', 'فا. من أرَّخَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أرَّخَ). ""مُؤَرِّخٌ عَرَبِيٌّ"" : مَنْ يُؤَرِّخُ لِأَحْدَاثِ العَرَبِ وَمَعَارِكِهِمْ، أَيِ العَالِمُ بِالتَّارِيخِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(328, 'مُرْسِلٌ', 'مرسل', 'اسم فاعل', 'رسل', 'مرسل', 'مرسل', 'فا. من أَرْسَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَرْسَلَ). ""مُرْسِلُ الخِطَابِ"" : بَاعِثُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(329, 'مُرْشِدٌ', 'مرشد', 'اسم فاعل', 'رشد', 'مرشد', 'مرشد', 'فَا. مِنْ أَرْشَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَرْشَدَ). 1.""مُرْشِدٌ دِينِيٌّ"" : الْمُكَلَّفُ بِالتَّوْجِيهِ الدِّينِيِّ فِي مُؤَسَّسَةٍ اِجْتِمَاعِيَّةٍ أَوْ جَمْعِيَّةٍ، الْمُوَجِّهُ. ""الْمُرْشِدُ الدِّينِيُّ لِلْقُوَّاتِ الْمُسَلَّحَةِ"" ""مُرْشِدَةٌ اِجْتِمَاعِيَّةٌ"". 2.""مُرْشِدٌ سِيَاحِيٌّ"": مَنْ يُوَجِّهُ السُّيَّاحَ إِلَى الأَمَاكِنِ الأَثَرِيَّةِ وَيُصَاحِبُهُمْ أَثْنَاءَ إِقَامَتِهِمْ فِي بَلَدِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(330, 'مُرْضِعٌ', 'مرضع', 'اسم فاعل', 'رضع', 'مرضع', 'مرضع', 'فَا. مِنْ أَرْضَعَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَرْضَعَ). ""اِمْرَأَةٌ مُرْضِعٌ"" : لَهَا وَلَدٌ تَقُومُ بِإِرْضَاعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(331, 'مُزْدَوِجٌ', 'مزدوج', 'اسم فاعل', 'زوج', 'مزدوج', 'مزدج', 'فَا. مِن اِزْدَوَجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُزْدَوِجٌ-مُزْدَوِجٌ، ةٌ [ز و ج] (فَا. مِن اِزْدَوَجَ). 1.""قَامَ بِعَمَلٍ مُزْدَوِجٍ"" : قَامَ بِعَمَلٍ مُكَوَّنٍ مِنْ شَيْئَيْنِ فِي آنٍ واحِدٍ. 2.""تَعْلِيمٌ مُزْدَوِجٌ"" : أَيْ تُدْرَسُ فِيهِ لُغَتَانِ أَوْ يُلَقَّنُ بِلُغَتَيْنِ. 3.""هُوَ مُزْدَوِجُ اللُّغَةِ"" : أَيْ يُتْقِنُ لُغَتَهُ الوَطَنِيَّةَ زِيادَةً على لُغَةٍ أَجَنَبِيَّةٍ. ""مُزْدَوِجُ الثَّقَافَةِ"". 4.""مَعْهَدٌ مُزْدَوِجٌ"" : أَيْ بِهِ ذُكُورٌ وَإِنَاثٌ. 5.""شَجَرَةٌ مُزْدَوِجَةٌ"": أَيْ تُثْمِرُ نَوْعَيْنِ مِنَ الفَوَاكِهِ فِي آنٍ وَاحِدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(332, 'مُرِنٌّ', 'مرن', 'اسم فاعل', 'رنن', 'مرن', 'مرن', 'فَا. مِنْ أَرَنَّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرِنٌّ-مُرِنٌّ، ةٌ [ر ن ن] (فَا. مِنْ أَرَنَّ). 1.""جَرَسٌ مُرِنٌّ"" : ذُو صَوْتٍ رَنَّانٍ. ""أَجْرَاسٌ مُرِنَّةٌ"". 2.""قَوْسٌ مُرِنَّةٌ"" : ذَاتُ رَنِينٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(333, 'مُرْهِبٌ', 'مرهب', 'اسم فاعل', 'رهب', 'مرهب', 'مرهب', 'فَا. مِنْ أَرْهَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَرْهَبَ). ""عَمَلٌ مُرْهِبٌ"" : مُخِيفٌ مُفْزِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(334, 'مُرْهِقٌ', 'مرهق', 'اسم فاعل', 'رهق', 'مرهق', 'مرهق', 'فَا. مِنْ أَرْهَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَرْهَقَ). 1.""عَمَلٌ مُرْهِقٌ"" : مُتْعِبٌ، مُكَلِّفٌ. 2.""حَرٌّ مُرْهِقٌ"" : شَدِيدٌ، مُفْرِطٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(335, 'مُزْئِرٌ', 'مزئر', 'اسم فاعل', 'زأر', 'مزءر', 'مزر', 'فَا. مِنْ أَزْأَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزْئِرٌ-مُزْئِرٌ [ز أ ر] (فَا. مِنْ أَزْأَرَ). ""أَسَدٌ مُزْئِرٌ"" : يُصَوِّتُ مِنْ صَدْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(336, 'مُزْبِدٌ', 'مزبد', 'اسم فاعل', 'زبد', 'مزبد', 'مزبد', 'فَا. مِنْ أَزْبَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُزْبِدٌ-مُزْبِدٌ [ز ب د] (فَا. مِنْ أَزْبَدَ). 1.""جَمَلٌ مُزْبِدٌ"" : قَاذِفٌ بِالزَّبَدِ مِنْ فَمِهِ. 2.""بَحْرٌ مُزْبِدٌ"" : هَائِجٌ يَقْذِفُ الزَّبَدَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(337, 'مُزْدَحِمٌ', 'مزدحم', 'اسم فاعل', 'زحم', 'مزدحم', 'مزدحم', 'فَا. مِن ازْدَحَمَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزْدَحَمٌ-مُزْدَحَمٌ، ةٌ [ز ح م] (مفع. مِن اِزْدَحَمَ). ""سُوقٌ مُزْدَحَمٌ"" : بِهِ زَحْمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(338, 'مُزْدَرِدٌ', 'مزدرد', 'اسم فاعل', 'زرد', 'مزدرد', 'مزدرد', 'فَا. مِن اِزْدَرَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُزْدَرِدٌ-مُزْدَرِدٌ، ةٌ [ز ر د] (فَا. مِن اِزْدَرَدَ). ""مُزْدَرِدٌ لِلْأَكْلِ"": مُبْتَلِعٌ لَهُ بِسُرْعَةٍ، أَكُولٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(339, 'مُزْدَرِي', 'مزدري', 'اسم فاعل', 'زري', 'مزدري', 'مزدر', 'فَا. مِن اِزْدَرَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِزْدَرَى). ""مُزْدَرٍ لِأَقْرَانِهِ"" : مُسْتَخِفٌّ بِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(340, 'مُزْدَهِرٌ', 'مزدهر', 'اسم فاعل', 'زهر', 'مزدهر', 'مزدهر', 'فَا. مِن اِزْدَهَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزْدَهِرٌ-مُزْدَهِرٌ، ةٌ [ز هـ ر] (فَا. مِن اِزْدَهَرَ). 1.""نَبَاتٌ مُزْدَهِرٌ"" : مُزْهِرٌ، مُغَطَّى بِالزَّهْرِ. 2.""تِجَارَةٌ مُزْدَهِرَةٌ"" : نَامِيَةٌ وَمُتَطَوِّرَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(341, 'مُسْتَأْنِفٌ', 'مستأنف', 'اسم فاعل', 'أنف', 'مستءنف', 'مستنف', 'فَا. مِن اِسْتَأْنَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَأْنَفَ). ""مُسْتَأْنِفُ الدَّعْوى"" : الْمُتَّهَمُ الطَّاعِنُ فِي الحُكْمِ وَالْمُطَالِبُ بِإِعَادَةِ النَّظَرِ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(342, 'مُزْعِجٌ', 'مزعج', 'اسم فاعل', 'زعج', 'مزعج', 'مزعج', 'فَا. مِنْ أَزْعَجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَزْعَجَ). ""صَوْتٌ مُزْعِجٌ"" : مُقْلِقٌ. ""حَرَكَاتٌ مُزْعِجَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(343, 'مُزَّمِّلٌ', 'مزمل', 'اسم فاعل', 'زمل', 'مزمل', 'مزمل', 'فَا. مِن اِزَّمَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُزَّمَّلٌ-مُزَّمَّلٌ [ز م ل] (مفع. مِنْ زَمَّلَ). ""مُزَمَّلٌ فِي مِعْطَفِهِ"": مُلْتَفٌّ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(344, 'مُزْمِنٌ', 'مزمن', 'اسم فاعل', 'زمن', 'مزمن', 'مزمن', 'فَا. مِنْ أَزْمَنَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزْمِنٌ-مُزْمِنٌ، ةٌ [ز م ن] (فَا. مِنْ أَزْمَنَ). ""مَرَضٌ مُزْمِنٌ"" : طَالَ وَاشْتَدَّ زَمَانُهُ. ""مُصَابٌ بِعُقْدَةٍ نَفْسِيَّةٍ مُزْمِنَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(345, 'مُزْهِرٌ', 'مزهر', 'اسم فاعل', 'زهر', 'مزهر', 'مزهر', 'فَا. مِنْ أَزْهَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزْهِرٌ-مُزْهِرٌ، ةٌ [ز هـ ر] (فَا. مِنْ أَزْهَرَ). 1.""نَبَاتٌ مُزْهِرٌ"": زَهْرُهُ طَالِعٌ. 2.""مُزْهِرُ الْحَيِّ"" : مَنْ يُوقِدُ النَّارَ لِلضُّيُوفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(346, 'مُسْبِتٌ', 'مسبت', 'اسم فاعل', 'سبت', 'مسبت', 'مسبت', 'فَا. مِنْ أَسْبَتَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَسْبَتَ). 1.""وَجَدَهُ مُسْبِتاً"" : لَمْ يَعُدْ يَتَحَرَّكُ لِمَرَضٍ أَوْ عِلَّةٍ. ""مَرِيضٌ مُسْبِتٌ"". 2.""حَيَوَانٌ مُسْبِتٌ"" : رَابِضٌ فِي مَكَانِهِ لاَ يَتَحَرَّكُ. 3.""يَهُودِيٌّ مُسْبِتٌ"" : مُنْقَطِعٌ عَنِ العَمَلِ بِدُخُولِهِ فِي مَسَاءِ يَوْمِ السَّبْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(347, 'مُسْتَاءٌ', 'مستاء', 'اسم فاعل', 'سوأ', 'مستاء', 'مست', 'فَا. مِن اِسْتَاءَ', '', '', 'مفرد', 'Dz', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَاءَ). ""مُسْتَاءٌ مِنْ عَمَلِهِ"" : مُتَضَايِقٌ، حَانِقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(348, 'مُسْتَاءَةٌ', 'مستاءة', 'اسم فاعل', '', 'مستاءة', 'مستة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَاءَ). ""مُسْتَاءٌ مِنْ عَمَلِهِ"" : مُتَضَايِقٌ، حَانِقٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(349, 'مُسْتَأْثِرٌ', 'مستأثر', 'اسم فاعل', 'أثر', 'مستءثر', 'مستثر', 'فَا. مِن اِسْتَأْثَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَأْثَرَ). 1.""مُسْتَأْثِرٌ بِكُلُّ شَيْءٍ"" : مَنْ يُعْطِي لِنَفْسِهِ الْحَقَّ فِي أَخْذِ كُلِّ شَيْءٍ، الْمُسْتَحْوِذُ... 2.""حَاكِمٌ مُسْتَأْثِرٌ بِالسُّلْطَةِ"" : مُسْتَبِدٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(350, 'مُسْتَأْجِرٌ', 'مستأجر', 'اسم فاعل', 'أجر', 'مستءجر', 'مستجر', 'فَا. مِن اِسْتَأْجَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَأْجَرَ). ""اِسْتَقَرَّ الْمُسْتَأْجِرُ الجَدِيدُ في شَقَّتِهِ"" : الْمُكْتَرِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(351, 'مُسْتَحِيلٌ', 'مستحيل', 'اسم فاعل', 'حول', 'مستحيل', 'مستحل', 'فَا. مِن اِسْتَحَالَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَحَالَ). 1.""مُسْتَحِيلٌ أَنْ يُحَقِّقَ هَدَفَهُ"" : مُحَالٌ، مُتَعَذِّرٌ غَيْرُ مُمكِن. ""مِنَ الْمُسْتَحِيلِ أَنْ..."". 2.""هَذَا مِنْ رَابِعِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(352, 'مُسْتَأْهِلٌ', 'مستأهل', 'اسم فاعل', 'أهل', 'مستءهل', 'مستهل', 'فَا. مِن اِسْتَأْهَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَأْهَلَ). ""مُسْتَأْهِلٌ لِلدَّرَجَةِ الأُولَى"" : مُسْتَحِقٌّ لَهَا، أَهْلٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(353, 'مُسْتَبِدٌّ', 'مستبد', 'اسم فاعل', 'بدد', 'مستبد', 'مستبد', 'فَا. مِن اِسْتَبَدَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَبَدَّ). 1.""مُسْتَبِدٌّ بِرَأْيِهِ"" : مَنْ يَتَعَصَّبُ، يَتَصَلَّبُ لِرَأْيِهِ وَلاَ يَقْبَلُ سَمَاعَ آرَاءِ الآخَرِينَ، العَنِيدُ. 2.""حَاكِمٌ مُسْتَبِدٌّ "": ظَالِمٌ، قَاهِرٌ. ""حَارَبَتِ الأُمَّةُ العَرَبِيَّةُ الْمُسْتَعْمِرِينَ وَالْمُسْتَبِدِّينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(354, 'مُسْتَبْشِرٌ', 'مستبشر', 'اسم فاعل', 'بشر', 'مستبشر', 'مستبشر', 'فَا. مِن اِسْتَبْشَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَبْشَرَ). ""جَاءَ مُسْتَبْشِراً وَهُوَ يُعْلِنُ لِلنَّاسِ خَبَراً سَارّاً"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(355, 'مُسْتَتِرٌ', 'مستتر', 'اسم فاعل', 'ستر', 'مستتر', 'مستتر', 'فَا. مِن اِسْتَتَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَتَرَ). ""عَمَلٌ مُسْتَتِرٌ"" : مُغَطًّى، مُخْتَفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(356, 'مُسْتَثِيرٌ', 'مستثير', 'اسم فاعل', 'ثور', 'مستثير', 'مستثر', 'فَا. مِن اِسْتَثَارَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُسْتَثِيرٌ-مُسْتَثِيرٌ، ةٌ [ث و ر] (فَا. مِن اِسْتَثَارَ). ""عَمَلٌ مُسْتَثِيرٌ لِلْغَضَبِ"" : مُثِيرٌ لِلْغَضَبِ، دَافِعٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(357, 'مُسْتَثْمِرٌ', 'مستثمر', 'اسم فاعل', 'ثمر', 'مستثمر', 'مستثمر', 'فَا. مِن اِسْتَثْمَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَثْمَرَ). ""مُسْتَثْمِرٌ لِأَمْوَالِهِ"" : مَنْ يَعْمَلُ عَلَى اسْتِث"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(358, 'مُسْتَجِيرٌ', 'مستجير', 'اسم فاعل', 'جور', 'مستجير', 'مستجر', 'فَا. مِن اِسْتَجَارَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَجَارَ). ""جَاءَ مُسْتَجِيراً بِهِ"" : مُسْتَغِيثاً بِهِ، مُلْتَجِئاً إِلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(359, 'مُسْتَجْدِي', 'مستجدي', 'اسم فاعل', 'جدو', 'مستجدي', 'مستجد', 'فَا. مِن اِسْتَجْدَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُسْتَجْدٍ، الْمُسْتَجْدِي، ةٌ - ج: ـون، ـات. [ج د و]. (فَا. مِن  اِسْتَجْدَى). ""لَيْسَ في بَلَدِهِمْ مُسْتَجْدٍ""  : مُسْتَعْطٍ، أَيْ طَالِبٌ عَطَاءهُمْ وَعَطْفَهُمْ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(360, 'مُسْتَجْوِبٌ', 'مستجوب', 'اسم فاعل', 'جوب', 'مستجوب', 'مستجب', 'فَا. مِن اِسْتَجْوَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَجْوَبَ). ""جَلَسَ وَرَاءَ الطَّاوِلَةِ مُسْتَجْوِباً الْمُتَّهَمَ"" : سَائِلاً إِيَّاهُ أَسْئِلَةً لِيُجِيبَ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(361, 'مُسْتَرِقٌ', 'مسترق', 'اسم فاعل', 'سرق', 'مسترق', 'مسترق', 'فَا. مِن اِسْتَرَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُسْتَرِقٌ - [س ر ق]. (فَا. مِن اِسْتَرَقَ). 1.""وَلَدٌ مُسْتَرِقٌ"" : نَاقِصٌ ضَعِيفُ الْخَلْقِ. 2.""مُسْتَرِقُ العُنُقِ"":  قَصِيرُهَا. 3. ""مُسْترِقُ السَّمْعِ"" : مُسْتَمِعٌ خُفْيَةً. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(362, 'مُسْتَحِقٌّ', 'مستحق', 'اسم فاعل', 'حقق', 'مستحق', 'مستحق', 'فَا. مِن اِسْتَحَقَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُسْتَحِقٌّ-مُسْتَحِقٌّ، ةٌ [ح ق ق] (فَا. مِن اِسْتَحَقَّ). ""الْمَبْلَغُ الْمُسْتَحِقُّ"" : الْمَبْلَغُ الوَاجِبُ أَدَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(363, 'مُسْتَحْوِذٌ', 'مستحوذ', 'اسم فاعل', 'حوذ', 'مستحوذ', 'مستحذ', 'فَا. مِن اِسْتَحْوَذَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَحْوَذَ). ""مُسْتَحْوِذٌ عَلَى كُلِّ الأَمْلاَكِ"" : مَالِكٌ لَهَا، أَيْ فِي حَوْزَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(364, 'مُسْتَحِي', 'مستحي', 'اسم فاعل', 'حيي', 'مستحي', 'مستح', 'فَا. مِن اِسْتَحْيا', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَحْيا). ""رَجُلٌ مُسْتَحْيٍ"" : خَجُولٌ. لاَ يَتَعَلَّمُ العِلْمَ مُسْتَحْيٍ وَلاَ مُسْتَكْبِرٌ (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(365, 'مُسْتَخْدِمٌ', 'مستخدم', 'اسم فاعل', 'خدم', 'مستخدم', 'مستخدم', 'فَا. مِن اِسْتَخْدَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَخْدَمَ). ""يُرَاقِبُ الْمُسْتَخْدِمُ عَمَلَ عُمَّال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(366, 'مُسْتَدِيمٌ', 'مستديم', 'اسم فاعل', 'دوم', 'مستديم', 'مستدم', 'فَا. مِن اِسْتَدَامَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُسْتَدِيمٌ-مُسْتَدِيمٌ [د و م] (فَا. مِن اِسْتَدَامَ). ""عَمَلٌ مُسْتَدِيمٌ"": دَائِمٌ، ثَابِتٌ، مُسْتَمِرٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(367, 'مُسْتَدِينٌ', 'مستدين', 'اسم فاعل', 'دين', 'مستدين', 'مستدن', 'فَا. مِن اِسْتَدَانَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَدَانَ). ""مُسْتَدِينٌ بِمَبْلَغٍ كَبِيرٍ مِنَ الْمَالِ"" : الْمُسْتَلِفُ، الْمُسْتَقْرِضُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(368, 'مُسْتَدْعِي', 'مستدعي', 'اسم فاعل', 'دعو', 'مستدعي', 'مستدع', 'فَا. مِن اِسْتَدْعَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَدْعَى). ""مُسْتَدْعٍ لاجْتِمَاعٍ طَارِئٍ"" : مَنْ يَدْعُو لِلاجْتِمَاعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(369, 'مُسْتَرِيحٌ', 'مستريح', 'اسم فاعل', 'روح', 'مستريح', 'مسترح', 'فَا. مِن اِسْتَرَاحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَرَاحَ). ""مُسْتَرِيحٌ فِي بَيْتِهِ"" : وَاجِدٌ لِلرَّاحَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(370, 'مُسْتَرْسِلٌ', 'مسترسل', 'اسم فاعل', 'رسل', 'مسترسل', 'مسترسل', 'فَا. مِن اِسْتَرْسَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَرْسَلَ). 1.""شَعْرٌ مُسْتَرْسِلٌ"" : مُسْتَقِيمٌ، مُرْسَلٌ، غَيْرُ مُتَجَعِّدٍ. 2.""ضَحِكَ ضَحْكَةً طَوِيلَةً مُسْتَرْسِلَةً"" : أَيْ مُتَتَابِعَةً . 3.""حَدِيثٌ مُسْتَرْسِلٌ"" : سَلِسٌ، مُتَتَابِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(371, 'مُسْتَعِدٌّ', 'مستعد', 'اسم فاعل', 'عدد', 'مستعد', 'مستعد', 'فَا. مِن اِسْتَعَدَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَعَدَّ). ""مُسْتَعِدٌّ لِخَوْضِ الْمَعْرَكَةِ"" : مُهَي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(372, 'مُسْتَزِيدٌ', 'مستزيد', 'اسم فاعل', 'زيد', 'مستزيد', 'مستزد', 'فَا. مِن اِسْتَزَادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَزَادَ). ""لَمْ يَتْرُكْ زِيَادَةً لِمُسْتَزِيدٍ"" : أَيْ لَمْ يَتْرُكْ زِيَادَةً لِمَنْ يُرِيدُ أَنْ يُضِيفَ شَيْئاً، إِذْ بَلَغَ أَقْصَاهُ. ""لَمْ يَبْقَ لِمُسْتَزِيدٍ اسْتِزَادَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(373, 'مُسْتَسْلِمٌ', 'مستسلم', 'اسم فاعل', 'سلم', 'مستسلم', 'مستسلم', 'فَا. مِن اِسْتَسْلَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَسْلَمَ). 1.""جُنْدِيٌّ مُسْتَسْلِمٌ"" : مَنِ اسْتَسْلَمَ وَطَرَحَ سِلاَحَهُ. 2.""مُسْتَسْلِمٌ لِأَهْوَائِهِ"" : خَاضِعٌ لِـ... ""جَلَسَتْ حَزِينَةً كَسِيرَةً مُسْتَسْلِمَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(374, 'مُسْتَشِيطٌ', 'مستشيط', 'اسم فاعل', 'شيط', 'مستشيط', 'مستشط', 'فَا. مِن اِسْتَشَاطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَشَاطَ). ""وَجَدَهُ مُسْتَشِيطاً غَضَباً"" : مُتَفَجِّراً غَضَباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(375, 'مُسْتَشْرِقٌ', 'مستشرق', 'اسم فاعل', 'شرق', 'مستشرق', 'مستشرق', 'فَا. مِن اِسْتَشْرَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَشْرَقَ). عَالِمٌ مِنَ البُلْدَانِ الأُورُوبِّيَّةِ عُموماً مُخْتَصٌّ بِاللُّغَاتِ وَالآدَابِ وَالعُلُومِ الشَّرْقِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(376, 'مُسْتَطِيرٌ', 'مستطير', 'اسم فاعل', 'سطر', 'مستطير', 'مستطر', 'فَا. مِن اِسْتَطَارَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُسْتَطِيرٌ-مُسْتَطِيرٌ، ةٌ [س ط ر] (فَا. مِن اِسْتَطَارَ). ""شَرٌّ مُسْتَطِيرٌ"" : أَيْ شَرٌّ مُنْتَشِرٌ ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(377, 'مُسْتَطِيلٌ', 'مستطيل', 'اسم فاعل', 'طول', 'مستطيل', 'مستطل', 'فـا. من اِسْتَطَالَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فـا. من اِسْتَطَالَ).1.""تَرَكَهُ مُسْتَطِيلاً عَلَى ضِفَّةِ النَّهْرِ"" : مُسْتَلْقِياً، مُمْتَدّاً. 2.""شَكْلٌ مُسْتَطِيلٌ"" : شَكْـلٌ هَنْدَسِيٌّ رُبَـاعِيٌّ، يَتَسَاوَى فِيهِ كُلُّ ضِلْعَيْنِ مُتَقَابِلَيْنِ، زَوَايَاهُ قَوَائِمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(378, 'مُسْتَعِيرٌ', 'مستعير', 'اسم فاعل', 'عور', 'مستعير', 'مستعر', 'فَا. مِن اِسْتَعَارَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَعَارَ). 1.""مُسْتَعِيرٌ لِكُتُبٍ عِلْمِيَّةٍ"" : مَنْ يَطْلُبُ إِعَارَتَهَا، مَنْ يَسْتَعِيرُ... 2.""هُوَ مُسْتَعِيرٌ "" : مَدِينٌ، مَدْيُونٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(379, 'مُسْتَعْبِدٌ', 'مستعبد', 'اسم فاعل', 'عبد', 'مستعبد', 'مستعبد', 'فَا. مِن اِسْتَعْبَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَعْبَدَ). ""مُسْتَعْبِدٌ لِلنَّاسِ"" : مَنْ يَتَّخِذُهُمْ عَبِيداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(380, 'مُسْتَعْجِلٌ', 'مستعجل', 'اسم فاعل', 'عجل', 'مستعجل', 'مستعجل', 'فَا. مِن اِسْتَعْجَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَعْجَلَ). ""مُسْتَعْجِلٌ فِي أُمُورِهِ"" : مُسْرِعٌ فِيهَا، أَيْ يُنْجِزُهَا عَلَى عَجَلَةٍ مِنْ أَمْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(381, 'مُسْتَغِلٌّ', 'مستغل', 'اسم فاعل', 'غلل', 'مستغل', 'مستغل', 'فَا. مِن اِسْتَغَلَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَغَلَّ). 1.""رَجُلٌ مُسْتَغِلٌّ"" : مُسْتَفِيدٌ مِنْ عَمَلِ غَيْرِه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(382, 'مُسْتَعِرٌ', 'مستعر', 'اسم فاعل', 'سعر', 'مستعر', 'مستعر', 'فَا. مِن اِسْتَعَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَعِرٌ-مُسْتَعِرٌ، ةٌ [س ع ر] (فَا. مِن اِسْتَعَرَ). ""جَمْرٌ مُسْتَعِرٌ"": مُشْتَعِلٌ، مُتَوَقِّدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(383, 'مُسْتَعْرِبٌ', 'مستعرب', 'اسم فاعل', 'عرب', 'مستعرب', 'مستعرب', 'فَا. مِن اِسْتَعْرَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَعْرَبَ). 1.""صَارَ مُسْتَعْرِباً"" : الأَجْنَبِيُّ الَّذِي تَعَلَّمَ اللُّغَةَ العَرَبِيَّةَ وَآدَابَهَا. 2.""هَذَا الكِتَابُ مِنْ تَأْلِيفِ الْمُسْتَعْرِبِ فُلاَن"": أَيِ العَالِمُ الْمُخْتَصُّ بِآدَابِ العَرَبِ وَعُلُومِهِمْ وَثَقَافَتِهِمْ وَتَارِيخِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(384, 'مُسْتَعْصِي', 'مستعصي', 'اسم فاعل', 'عصي', 'مستعصي', 'مستعص', 'فَا. مِن اِسْتَعْصَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَعْصَى). 1.""مَرَضٌ مُسْتَعْصٍ عِلاَجُهُ"": صَعْبٌ عِلاَجُهُ. 2.""وَجَدَ الْمَسْأَلَةَ مُسْتَعْصِيَةً عَلَى الْحَلِّ"": مُتَعَذِّرٌ حَلُّهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(385, 'مُسْتَعْطِي', 'مستعطي', 'اسم فاعل', 'عطي', 'مستعطي', 'مستعط', 'فَا. مِن اِسْتَعْطَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَعْطَى). ""رَجُلٌ مُسْتَعْطٍ"" : مُسْتَجْدٍ، طَالِبُ العَطَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(386, 'مُسْتَعْمِرٌ', 'مستعمر', 'اسم فاعل', 'عمر', 'مستعمر', 'مستعمر', 'فَا. مِن اِسْتَعْمَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُسْتَعْمِرٌ-مُسْتَعْمِرٌ [ع م ر] (فَا. مِن اِسْتَعْمَرَ). ""اِحْتَلَّ الْمُسْتَعْمِرُونَ البِلاَدَ"" : أَيِ الأَجَانِبُ الَّذِينَ يَحْتَلُّونَ بِلاَداً مَّا، وَيُسَيْطِرُونَ عَلَيْهَا قُوَّةً وَقَهْراً لِيَسْتَغِلُّوا خَيْرَاتِهَا وَمَوَارِدَهَا. ""حَارَبُوا الْمُسْتَعْمِرَ بِكُلِّ قُوَّةٍ"" ""الدَّوْلَةُ الْمُسْتَعْمِرَةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(387, 'مُسْتَعْمِلٌ', 'مستعمل', 'اسم فاعل', 'عمل', 'مستعمل', 'مستعمل', 'فَا. مِن اِسْتَعْمَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَعْمَلَ). ""هو مُسْتَعْمِلٌ ماهِرٌ لأَدَواتِ العَمَلِ"" : مُسْتَخْدِمٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(388, 'مُسْتَغِيثٌ', 'مستغيث', 'اسم فاعل', 'غوث', 'مستغيث', 'مستغث', 'فَا. مِن اِسْتَغَاثَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَغَاثَ). ""جَاءَ مُسْتَغِيثا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(389, 'مُسْتَغْرِقٌ', 'مستغرق', 'اسم فاعل', 'غرق', 'مستغرق', 'مستغرق', 'فَا. مِن اِسْتَغْرَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَغْرَقَ). ""مُسْتَغْرِقٌ فِي تَفْكِيرٍ عَمِيقٍ"" : مَأْخُوذٌ كُلِّيَّةً فِيهِ. ""مُسْتَغْرِقٌ فِي تَأَمُّلاَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(390, 'مُسْتَغْفِرٌ', 'مستغفر', 'اسم فاعل', 'غفر', 'مستغفر', 'مستغفر', 'فَا. مِن اِسْتَغْفَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَغْفَرَ). ""عَادَ نَادِماً مُسْتَغْفِراً"" : طَالِباً الْمَغْفِرَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(391, 'مُسْتَفِيدٌ', 'مستفيد', 'اسم فاعل', 'فيد،فود', 'مستفيد', 'مستفد', 'فَا. مِن اِسْتَفَادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَفَادَ). ""مُسْتَفِيدٌ مِنَ العَمَلِ"" : مُنْتَفِعٌ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(392, 'مُسْتَفِيضٌ', 'مستفيض', 'اسم فاعل', 'فيض', 'مستفيض', 'مستفض', 'فَا. مِن اِسْتَفَاضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَفَاضَ). ""حَدِيثٌ مُسْتَفِيضٌ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(393, 'مُسْتَفِزٌّ', 'مستفز', 'اسم فاعل', 'فزز', 'مستفز', 'مستفز', 'فَا. مِن اِسْتَفَزَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَفَزَّ). ""حَادِثٌ مُسْتَفِزٌّ"" : أَيْ مَا يُثِيرُ الأَعْصَابَ وَيُفْزِعُهَا وَيُزْعِجُهَا. ""مُسْتَفِزٌّ لِلْأَعْصَابِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(394, 'مُسْتَقِيلٌ', 'مستقيل', 'اسم فاعل', 'قيل', 'مستقيل', 'مستقل', 'فَا. مِن اِسْتَقَالَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَقَالَ). ""مُسْتَقِيلٌ مِنْ مَنْصِبِهِ"" : مَنْ قَدَّمَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(395, 'مُسْتَقِيمٌ', 'مستقيم', 'اسم فاعل', 'قوم', 'مستقيم', 'مستقم', 'فَا. مِن اِسْتَقَامَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَقَامَ). 1.""خَطٌّ مُسْتَقِيمٌ"" (هن) : خَطٌّ فِي مُسْتَوىً وَاحِدٍ غَيْرِ مُنْعَرِجٍ. 2.""صَاحِبُ خُلُقٍ مُسْتَقِيمٍ"" : مُسْتَوٍ، مُعْتَدِلٍ.الفاتحة آية 6 اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ (قرآن). 3.""ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(396, 'مُسْتَقْبِلٌ', 'مستقبل', 'اسم فاعل', 'قبل', 'مستقبل', 'مستقبل', 'فَا. مِن اِسْتَقْبَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَقْبَلَ). ""مُسْتَقْبِلٌ لِضُيُوفِهِ"" : أَيْ مُتَلَقِّيهِمْ مُرَحِّباً. ""مُسْتَقْبِلٌ لِكُلِّ الإِشَارَاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(397, 'مُسْتَقِرٌّ', 'مستقر', 'اسم فاعل', 'قرر', 'مستقر', 'مستقر', 'فَا. مِن اِسْتَقَرَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَقَرَّ). ""مُسْتَقِرٌّ فِي بَيْتِهِ"" : قَائِمٌ فِيهِ.النمل آية 40فَلَمَّا رَآهُ مُسْتَقِرّاً عِنْدَهُ قَالَ هَذَا مِنْ فَضْلِ رَبِّي (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(398, 'مُسْتَقْصِي', 'مستقصي', 'اسم فاعل', 'قصي', 'مستقصي', 'مستقص', 'فَا. مِن اِسْتَقْصَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَقْصَى). ""مُسْتَقْصٍ لِلْحَقَائِقِ"" : بَاحِثٌ وَفَاحِصٌ فِيهَا بِإِمْعَانٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(399, 'مُسْتَقْطِبٌ', 'مستقطب', 'اسم فاعل', 'قطب', 'مستقطب', 'مستقطب', 'فَا. مِن اِسْتَقْطَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَقْطَبَ). 1.""أَمْرٌ مُسْتَقْطِبٌ لِلْاِهْتِمَامِ"" : أَمْرٌ مَّا يَكونُ مَرْكَزاً، مِحْوَراً لِلاِهْتِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(400, 'مُسْتَقِلٌّ', 'مستقل', 'اسم فاعل', 'قلل', 'مستقل', 'مستقل', 'فَا. مِن اِسْتَقَلَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَقَلَّ). 1.""مُسْتَقِلٌّ بِنَفْسِهِ"" : قَائِمٌ بِنَفْسِه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(401, 'مُسْتَكْشِفٌ', 'مستكشف', 'اسم فاعل', 'كشف', 'مستكشف', 'مستكشف', 'فَا. مِن اِسْتَكْشَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَكْشَفَ). ""مُسْتَكْشِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(402, 'مُسْتَلْزِمٌ', 'مستلزم', 'اسم فاعل', 'لزم', 'مستلزم', 'مستلزم', 'فَا. من اِسْتَلْزَمَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَلْزِمٌ-مُسْتَلْزِمٌ، ةٌ [ل ز م] (فَا. من اِسْتَلْزَمَ). أَمْرٌ مُسْتَلْزِمٌ"": حَازِمٌ، ضَرُورِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(403, 'مُسْتَلِمٌ', 'مستلم', 'اسم فاعل', 'سلم', 'مستلم', 'مستلم', 'فَا. مِن اِسْتَلَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَلَمَ). ""مُسْتَلِمٌ مَبَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(404, 'مُسْتَمِيتٌ', 'مستميت', 'اسم فاعل', 'موت', 'مستميت', 'مستمت', 'فَا. مِن اِسْتَمَاتَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَمَاتَ). 1.""مَوْقِفٌ مُسْتَمِيتٌ"" : مَوْقِفٌ صَلْبٌ، ثَابِتٌ. 2.""قِتالٌ مُسْتَمِيتٌ"" : قِتَالٌ مُسْتَمِرٌّ بِثَبَاتٍ وَبِلاَ مُبَالاَةٍ بِأَيِّ شَيْءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(405, 'مُسْتَمْتِعٌ', 'مستمتع', 'اسم فاعل', 'سمع', 'مستمتع', 'مستمتع', 'فَا. مِن اِسْتَمْتَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَمْتَعَ). ""مَضَتْ فِي سَبِيلِهَا مُسْتَمْتِعَةً بِنُزْهَتِهَا اليَوْمِيَّةِ"" : أَيْ مُسْتَفِيدَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(406, 'مُسْتَمِدٌّ', 'مستمد', 'اسم فاعل', 'مدد', 'مستمد', 'مستمد', 'فَا. مِن اِسْتَمَدَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَمَدَّ). ""مُسْتَمِدٌّ آرَاءهُ مِنْ كُتُبِ التَّارِيخِ"" : أَيْ مُسْتَقِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(407, 'مُسْتَمِرٌّ', 'مستمر', 'اسم فاعل', 'مرر', 'مستمر', 'مستمر', 'فَا. مِن اِسْتَمَرَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَمَرَّ). 1.""مُسْتَمِرٌّ فِي عَمَلِهِ"" : مَاضٍ فِيهِ، مُنْهَمِكٌ فِيهِ بِاسْتِمْرَارٍ. 2.""نَجَاحٌ مُسْتَمِرٌّ"" : دَائِمٌ، مُتَوَاصِلٌ. ""عَمَلُهُ مُسْتَمِرٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(408, 'مُسْتَمِعٌ', 'مستمع', 'اسم فاعل', 'سمع', 'مستمع', 'مستمع', 'فا. مِن اسْتَمَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُسْتَمِعٌ-مُسْتَمِعٌ، ةٌ [س م ع] (فا. مِن اسْتَمَعَ). 1.""مُسْتَمِعٌ إِلَيْهِ بِانْتِبَاهٍ"" : مُسْتَرِقٌ السَّمْعَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(409, 'مُسْتَنِيرٌ', 'مستنير', 'اسم فاعل', 'نور', 'مستنير', 'مستنر', 'فَا. مِن اِسْتَنَارَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَنَارَ). ""يَتَمَتَّعُ بِعَقْلٍ مُسْتَنِيرٍ"" : بِعَقْلٍ وَاعٍ نَافِذٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(410, 'مُسْتَنِدٌ', 'مستند', 'اسم فاعل', 'سند', 'مستند', 'مستند', 'فا. من اِسْتَنَدَ.', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"ج: ون، ات. (فا. من اِسْتَنَدَ). 1.""مُسْتَنِدٌ إِلَى أَرِيكَتِهِ"" : مُتَّكِئٌ. 2.""حُجَّتُهُ مُسْتَنِدَةٌ إِلَى وَثَائِقَ"" : مُعْتَمِدَةٌ عَلَى ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(411, 'مُسْتَهْزِئٌ', 'مستهزئ', 'اسم فاعل', 'هزأ', 'مستهزء', 'مستهز', 'فَا. مِن اِسْتَهْزَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَهْزَأَ). ""مُسْتَهْزِئٌ بِالنَّاسِ"" : مَنْ يَسْخَرُ مِنْهُمْ وَيَسْتَخِفُّ بِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(412, 'مُسْتَنْزِفٌ', 'مستنزف', 'اسم فاعل', 'نزف', 'مستنزف', 'مستنزف', 'فَا. مِن اِسْتَنْزَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَنْزَفَ). 1.""مُسْتَنْزِفٌ لِطَاقَتِهِ"" : مُعْتَصِرٌ لَهَا. 2.""مُسْتَنْزِفٌ لِمَوَارِدِهِ"" : مُبَذِّرٌ لَهَا عَنْ آخِرِهَا. ""مُسْتَنْزِفٌ أَمْوَالَ النَّاسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(413, 'مُسْتَنْسِخٌ', 'مستنسخ', 'اسم فاعل', 'نسخ', 'مستنسخ', 'مستنسخ', 'فَا. مِن اِسْتَنْسَخَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَنْسَخَ). ""مُسْتَنْسِخُ الْكُتُب"" : مَنْ يَنْسَخُهَا بِإِعَادَةِ كِتَابَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(414, 'مُسْتَنْشِقٌ', 'مستنشق', 'اسم فاعل', 'نشق', 'مستنشق', 'مستنشق', 'فَا. مِن اِسْتَنْشَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَنْشَقَ). 1.""مُسْتَنْشِقُ الْهَوَاء"" : مَنْ يَشُمُّهُ. 2.""مُسْتَنْشِقُ الْمَاءِ"" : مَنْ يُدْخِلُهُ فِي أَنْفِهِ وَيَجْذِبُهُ بِالنَّفَسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(415, 'مُسْتَنْطِقٌ', 'مستنطق', 'اسم فاعل', 'نطق', 'مستنطق', 'مستنطق', 'فَا. مِن اِسْتَنْطَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَنْطَقَ). ""مُسْتَنْطِقُ الْمُتَّهَمِ"" : الَّذِي يَسْتَجْوِبُ الْمُتَّهَمَ لِيَنْتَزِعَ مِنْهُ اعْتِرَافَهُ بِالجَرِيمَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(416, 'مُسْتَنْفِرٌ', 'مستنفر', 'اسم فاعل', 'نفر', 'مستنفر', 'مستنفر', 'فَا. مِن اِسْتَنْفَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَنْفَرَ). ""جَاءَ مُسْتَنْفِراً جُنُودَهُ"" : مُحَرِّضاً لَهُمْ يَدْعُوهُمْ لِلْقِتَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(417, 'مُسْتَنْكِرٌ', 'مستنكر', 'اسم فاعل', 'نكر', 'مستنكر', 'مستنكر', 'فَا. مِن اِسْتَنْكَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَنْكَرَ). 1.""مُسْتَنْكِرٌ كُلَّ سُلُوكٍ سَيِّءٍ"" : مُسْتَقْبِحٌ، مُسْتَهْجِنٌ. 2.""لَهْجَةٌ مُسْتَنْكِرَةٌ"" : لَهْجَةُ الاسْتِهْجَانِ والتَّعْبِير عَنِ الاِسْتِنْكَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(418, 'مُسْتَنْكِفٌ', 'مستنكف', 'اسم فاعل', 'نكف', 'مستنكف', 'مستنكف', 'فَا. مِن اِسْتَنْكَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَنْكَفَ). ""مُسْتَنْكِفٌ عَنْ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(419, 'مُسْتَهْتِرٌ', 'مستهتر', 'اسم فاعل', 'هتر', 'مستهتر', 'مستهتر', 'فَا. مِن اِسْتَهْتَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَهْتَرَ). 1.""مُسْتَهْتِرٌ بِقِيَمِ أَهْلِهِ وَعاداتِهِمْ"" : غَيْرُ مُبَالٍ بِهَا، لاَ يُعْطِيهَا أَدْنَى قِيمَةٍ أَوِ اعْتِبَارٍ. 2.""اِمْرَأَةٌ مُسْتَهْتِرَةٌ"" : مُتَهَتِّكَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(420, 'مُسْتَهْجِنٌ', 'مستهجن', 'اسم فاعل', 'هجن', 'مستهجن', 'مستهجن', 'فَا. مِن اِسْتَهْجَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَهْجَنَ). ""رَجُلٌ مُسْتَهْجِنٌ"" : مُسْتَقْبِحٌ، أَي مُعَبِّرٌ عَن اسْتِنْكَارٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(421, 'مُسْرِعٌ', 'مسرع', 'اسم فاعل', 'سرع', 'مسرع', 'مسرع', 'فَا. مِن أَسْرَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَسْرَعَ). ""مُسْرِعٌ فِي عَمَلِهِ"" : عَجُولٌ، أَيْ يُنْجِزُهُ عَلَى عَجَلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(422, 'مُسْتَهْلِكٌ', 'مستهلك', 'اسم فاعل', 'هلك', 'مستهلك', 'مستهلك', 'فَا. مِن اِسْتَهْلَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَهْلَكَ). 1.""مُسْتَهْلِكٌ لِلْخُبْزِ بِكَثْرَةٍ"" : مُتَنَاوِلٌ... 2.""مُسْتَهْلِكٌ لِلآلاَتِ الصِّنَاعِيَّةِ"" : مُسْتَعْمِلٌ. 3.""لاَ بُدَّ مِنِ إِقَامَةِ تَوَازُنٍ بَيْنَ الْمُنْتِجِ وَالْمُسْتَهْلِكِ"" : بَيْنَ الْمُنْتِجِ وَالزَّبُونِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(423, 'مُسْتَهَامٌ', 'مستهام', 'اسم فاعل', 'هيم', 'مستهام', 'مستهم', 'فا. مِن اسْتُهِيمَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَهَامٌ-مُسْتَهَامٌ [هـ ي م] (فا. مِن اسْتُهِيمَ). 1.""مُسْتَهَامُ الفُؤَادِ"" : وَلْهَانٌ، مُوَلَّهٌ. 2.""قَلْبٌ مُسْتَهَامٌ"" : هَائِمٌ، شَدِيدُ الحُبِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(424, 'مُسْتَوْجِبٌ', 'مستوجب', 'اسم فاعل', 'وجب', 'مستوجب', 'مستجب', 'فا. مِن اِسْتَوْجَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُسْتَوْجِبٌ-مُسْتَوْجِبٌ، ةٌ [و ج ب] (فا. مِن اِسْتَوْجَبَ). ""عَمَلٌ مُسْتَوْجِبٌ كَفَاءةً عَالِيَةً"" : مُتَطَلِّبٌ، مُسْتَلْزِمٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(425, 'مُسْتَوْحِشٌ', 'مستوحش', 'اسم فاعل', 'وحش', 'مستوحش', 'مستحش', 'فَا. مِن اِسْتَوْحَشَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَوْحَشَ). ""يَعِيشُ بَيْنَ أَقْوَامٍ مُسْتَوْحَشِينَ"" : مَنْ تَغْلِبُ عَلَيْهِ صِفَةُ الوُحُوشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(426, 'مُسْتَوْرِدٌ', 'مستورد', 'اسم فاعل', 'ورد', 'مستورد', 'مسترد', 'فَا. مِن اِسْتَوْرَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَوْرَدَ). ""مُسْتَوْرِدٌ لِلْبَضَائِعِ الأَجْنَبِيَّةِ"" : مَنْ يَأْتِي بِالبَضَائِعِ مِنْ بُلْدَانٍ أَجْنَبِيَّةٍ لِلتِّجَارَةِ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(427, 'مُسْتَوْعِبٌ', 'مستوعب', 'اسم فاعل', 'وعب', 'مستوعب', 'مستعب', 'فَا. مِن اِسْتَوْعَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِسْتَوْعَبَ). 1.""مُسْتَوْعِبٌ عُلُومَ عَصْرِهِ"" : لَهُ طَاقَةٌ فِكْرِيَّةٌ لِفَهْمِهَا وَتَلَقِّيهَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(428, 'مُسْتَوْلِي', 'مستولي', 'اسم فاعل', 'ولي', 'مستولي', 'مستل', 'فَا. مِن اِسْتَوْلَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَوْلَى). ""مُسْتَوْلٍ عَلَى كُلِّ السُّلَطِ"" : أَيْ فِي يَدِهِ وَتَحْتَ سَيْطَرَتِهِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(429, 'مُسْتَوِي', 'مستوي', 'اسم فاعل', 'سوي', 'مستوي', 'مست', 'فَا. مِن اِسْتَوَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْتَوَى). 1.""طَعَامٌ مُسْتَوٍ"" : نَاضِجٌ. 2.""طَرِيقٌ مُسْتَوٍ"" : مُسْتَقِيمٌ. 3.""سَطْحٌ مُسْتَوٍ"" (هن) : إِذَا قَابَلْتَ فِيهِ أَيَّ نُقْطَتَيْنِ كَانَ الْمُسْتَقِيمُ الوَاصِلُ بَيْنَهُمَا مُنْطَبِقاً عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(430, 'مُسْدِلٌ', 'مسدل', 'اسم فاعل', 'سدل', 'مسدل', 'مسدل', 'فَا. مِن أَسْدَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَسْدَلَ). ""مُسْدِلٌ لِلسِّتَارِ"" : مُرْخٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(431, 'آسِنٌ', 'آسن', 'اسم فاعل', 'أسن', 'ءاسن', 'آسن', 'فَا. مِن أسَنَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"آسِنٌ-آسِنٌ [أ س ن] (فَا. مِن أسَنَ). ""مَاءٌ آسِنٌ فِي البُحَيْرَةِ"": مَاءٌ مُتَغَيِّرٌ طَعْمُهُ وَلَوْنُهُ وَرِيحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(432, 'مُسْرِفٌ', 'مسرف', 'اسم فاعل', 'سرف', 'مسرف', 'مسرف', 'فَا. مِن أَسْرَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَسْرَفَ). ""مُسْرِفٌ فِي الكَلاَمِ أَوِ الْمَالِ"" : مُجَاوِزٌ فِيهِ الْحَدَّ. ""الرِّجَالُ أَرْبَعَةٌ : جَوَادٌ وَبَخِيلٌ وَمُسْرِفٌ وَمُقْتَصِدٌ"". (ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(433, 'مُؤَسِّسٌ', 'مؤسس', 'اسم فاعل', 'أسس', 'مءسس', 'مس', 'فا. من أَسَّسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَسَّسَ). 1.""مُؤَسِّسُ الدَّوْلَةِ"" : مَنْ أَقَامَ قَوَاعِدَهَا وَأَسَّسَهَا تَحْتَ رِعَايَتِهِ. 2.""مُؤَسِّسُو الجَمْعِيَّةِ"" : مَنْ قَامُوا بِإِنْشَائِهَا وَإِيجَادِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(434, 'مُسْعِفٌ', 'مسعف', 'اسم فاعل', 'سعف', 'مسعف', 'مسعف', 'فَا. مِن أَسْعَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَسْعَفَ). 1.""مُسْعِفُ الْمَرْضَى"" : مُعَالِجٌ لَهُمْ بِالدَّوَاءِ. 2.""مُسْعِفُ الْفُقَرَاءِ"" : مَنْ يَقْضِي حَاجَاتِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(435, 'مُؤْسِفٌ', 'مؤسف', 'اسم فاعل', 'أسف', 'مءسف', 'مسف', 'فَا. مِنْ آسَفَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُؤْسِفٌ-مُؤْسِفٌ، ةٌ [أ س ف] (فَا. مِنْ آسَفَ). ""حَادِثٌ مُؤْسِفٌ"" : حَادِثٌ يَبْعَثُ عَلَى الأَسَفِ وَالأَلَمِ. ""حَوَادِثُ مُؤْسِفَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(436, 'آسِفٌ', 'آسف', 'اسم فاعل', 'أسف', 'ءاسف', 'آسف', 'فَا. مِنْ أسِفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"آسِفٌ-آسِفٌ [أ س ف] (فَا. مِنْ أسِفَ). 1.""آسِفٌ عَلَى مَا حَدَثَ"" : نَادِمٌ. ""غَيْرُ آسِفٍ عَلَى شَيءٍ"". 2.""إِنِّي آسِفٌ عَلَى غِيَابِهِ"" : حَزِينٌ، مُتَألِّمٌ، كَئِيبٌ. 3.""آسِفٌ كُلَّ الأسَفِ"": مُتَحسِّرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(437, 'أواسف', 'أواسف', 'اسم فاعل', '', 'ءواسف', 'سف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(438, 'مُسْكِرٌ', 'مسكر', 'اسم فاعل', 'سكر', 'مسكر', 'مسكر', 'فَا. مِن أَسْكَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', 'Cv', '"مُسْكِرٌ-مُسْكِرٌ، ةٌ [س ك ر] (فَا. مِن أَسْكَرَ). ""شَرَابٌ مُسْكِرٌ"" : شَرَاب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(439, 'مُسْلِمٌ', 'مسلم', 'اسم فاعل', 'سلم', 'مسلم', 'مسلم', 'فَا. مِن أَسْلَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَسْلَمَ).""يُؤَدِّي الْمُسْلِمُ الصَّلاَةَ خَمْسَ مَرَّاتٍ فِي اليَوْمِ"" : مَنْ يَتَّبِعُ دِينَ الإِسْلاَمِ و"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(440, 'مُسِنٌّ', 'مسن', 'اسم فاعل', 'سنن', 'مسن', 'مسن', 'فَا. مِن أَسَنَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَسَنَّ). ""رَجُلٌ مُسِنٌّ"" : كَبِيرُ السِّنِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(441, 'مُشْتَرِي', 'مشتري', 'اسم فاعل', 'شري', 'مشتري', 'مشتر', 'فَا. مِن اِشْتَرَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِشْتَرَى). ""مُشْتَرِي البَضَائِعِ"" : مُقْتَنِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(442, 'أواسن', 'أواسن', 'اسم فاعل', '', 'ءواسن', 'سن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(443, 'مُسْهِبٌ', 'مسهب', 'اسم فاعل', 'سهب', 'مسهب', 'مسهب', 'فَا. مِن أَسْهَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَسْهَبَ). ""خَطِيبٌ مُسْهِبٌ"" : مُطِيلٌ فِي خُطْبَتِهِ. ""مُسْهِبٌ فِي الكَلاَمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(444, 'مُسْهِمٌ', 'مسهم', 'اسم فاعل', 'سهم', 'مسهم', 'مسهم', 'فَا. مِن أسْهَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أسْهَمَ). ""مُسْهِمٌ فِي كُلِّ عَمَلٍ جَادٍّ"" : مُشَارِكٌ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(445, 'مُسْوَدٌّ', 'مسود', 'اسم فاعل', 'سود', 'مسود', 'مسد', 'فَا. مِن اِسْوَدَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِسْوَدَّ). 1. ""رَجُلٌ مُسْوَدُّ الوَجْهِ"" : أَكْحَلُ الوَجْهِ. 2. ""صَحْنٌ مُسْوَدٌّ"" : أَيْ عَلاَهُ السَّوَادُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(446, 'مُشِيدٌ', 'مشيد', 'اسم فاعل', 'شيد', 'مشيد', 'مشد', 'فَا. مِن أَشَادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَشَادَ). ""مُشِيدٌ بِمَكَارِمِهِ وَأخْلاَقِهِ"" : مُثْنٍ عَلَيْهِ بِثَنَاءِ الكَرَمِ وَالأَخْلاَقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(447, 'مُشِيرٌ', 'مشير', 'اسم فاعل', 'شور', 'مشير', 'مشر', 'فَا. مِن أَشَارَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَشَارَ). 1.""مُشِيرٌ إِلَيْهِ بِأَصَابِعِ الاتِّهَامِ"" : مُعَيِّنُ لَهُ. 2.""اِرْتَقَى إِلَى رُتْبَةِ الْمُشِيرِ"" : أَعْلَى رُتْبَةٍ فيِ الجِهَازِ العَسْكَرِيِّ، الْمَرِشَالُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(448, 'مُشْتَاقٌ', 'مشتاق', 'اسم فاعل', 'شوق', 'مشتاق', 'مشتق', 'فا. مِن اِشْتَاقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُشْتَاقٌ-مُشْتَاقٌ، ةٌ [ش و ق] (فا. مِن اِشْتَاقَ). ""مُشْتَاقٌ إِلَيْهَا"": رَاغِبٌ، مُتَشَوِّقٌ، تَوَّاقٌ. ""أَنا مُشْتَاقٌ وَعِنْدِي لَوْعَةٌ"". (أبو فراس الحمداني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(449, 'مُشْتَبِهٌ', 'مشتبه', 'اسم فاعل', 'شبه', 'مشتبه', 'مشتبه', 'فَا. مِن اِشْتَبَهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِشْتَبَهَ). 1.""وَجَدَهُ مُشْتَبِهاً"" : مُرْتَاباً، حَذِراً. 2.""أَمْرٌ مُشْتَبِهٌ"": مُلْتَبِسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(450, 'مُشْتَرِكٌ', 'مشترك', 'اسم فاعل', 'شرك', 'مشترك', 'مشترك', 'فَا. مِن اِشْتَرَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِشْتَرَكَ) 1. ""مُشْتَرِكٌ فِي العَمَلِ"" : مُسَاهِمٌ فِيهِ بِحِصَّةٍ وَنَصِيبٍ. 2.""مُشْتَرِكٌ فِي جَرِيدَةٍ يَوْمِيَّةٍ"" : أَيْ لَهُ فِيهَا اشْتِرَاكٌ شَهْرِيٌّ أَوْ سَنَوِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(451, 'مُشِعٌّ', 'مشع', 'اسم فاعل', 'شعع', 'مشع', 'مشع', 'فَا. مِن أَشَعَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُشِعٌّ-مُشِعٌّ، ةٌ [ش ع ع] (فَا. مِن أَشَعَّ). 1.""عُنْصُرٌ مُشِعٌّ"": مُضِيءٌ . 2.""نَظَائِرُ مُشِعَّةٌ"" : نَظَائِرُ لَهَا خَاصِّيَّةُ الفَاعِلِيَّةِ الإِشْعَاعِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(452, 'مُشْتَعِلٌ', 'مشتعل', 'اسم فاعل', 'شعل', 'مشتعل', 'مشتعل', 'فَا. مِن اِشْتَعَلَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشْتَعِلٌ-مُشْتَعِلٌ، ةٌ [ش ع ل] (فَا. مِن اِشْتَعَلَ). 1.""نَارٌ مُشْتَعِلَةٌ"" : مُوقَدَةٌ، مُلْتَهِبَةٌ. 2.""مَادَّةٌ مُشْتَعِلَةٌ"" : مَادَّةٌ قَابِلَةٌ لِلاشْتِعَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(453, 'مُشْتَكِي', 'مشتكي', 'اسم فاعل', 'شكو', 'مشتكي', 'مشتك', 'فَا. مِن اِشْتَكَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِشْتَكَى). ""جَاءتْ مُشْتَكِيَةً لِلْقَاضِي"" : اِلْتَجَأَتْ إِلَيْهِ تَبُثُّهُ شَكْوَاهَا لِيَرْفَعَ عَنْهَا الضَّيْمَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(454, 'مُشْتَمِلٌ', 'مشتمل', 'اسم فاعل', 'شمل', 'مشتمل', 'مشتمل', 'فَا. مِن اِشْتَمَلَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشْتَمِلٌ-مُشْتَمِلٌ، ةٌ [ش م ل] (فَا. مِن اِشْتَمَلَ). ""مُشْتَمِلٌ عَلَى عِدَّةِ عَنَاصِرَ"" : ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(455, 'مُشْتَهِي', 'مشتهي', 'اسم فاعل', 'شهي', 'مشتهي', 'مشته', 'فَا. مِن اِشْتَهَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِشْتَهَى). ""مُشْتَهٍ مَا طَابَ وَلَذَّ"" : مَنِ اشْتَدَّتْ رَغْبَتُهُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(456, 'مُشْتِي', 'مشتي', 'اسم فاعل', 'شتو', 'مشتي', 'مشت', 'فَا. مِن أَشْتَى', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشْتٍ، الْمُشْتِي - [ش ت و]. (فَا. مِن أَشْتَى). ""يَوْمٌ مُشْتٍ"" : يَوْمُ شِتَاءٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(457, 'مُشْجِرٌ', 'مشجر', 'اسم فاعل', 'شجر', 'مشجر', 'مشجر', 'فَا. مِن أَشَجَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشْجِرٌ-مُشْجِرٌ، ةٌ [ش ج ر] (فَا. مِن أَشَجَرَ). ""مَكَانٌ مُشْجِرٌ"" : كَثِيرُ الشَّجَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(458, 'مُؤَشِّرٌ', 'مؤشر', 'اسم فاعل', 'أشر', 'مءشر', 'مشر', 'فَا. مِنْ أَشَّرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَشَّرَ). 1.""ظَهَرَ مُؤَشِّرٌ يُنْبِئُ بِانْفِرَاجِ الأَزْمَةِ"" : عَلاَمَةٌ تَدُلُّ كُلُّ إِشَارَاتِهَا عَلَى أَنَّ الْمَشَاكِلَ فِي طَرِيقِهَا إِلَى الْحَلِّ. 2.""مُؤَشِّرُ المِيزَانِ"" : لِسَانُهُ، إِبْرَتُهُ. 3.""يُشِيرُ بِالْمُؤَشِّرِ إِلَى الْمَنَاطِقِ الجَبَلِيّةِ"" : قَضِيبٌ يُشَارُ بِهِ عَلَى الخَرِيطَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(459, 'مُشْرِفٌ', 'مشرف', 'اسم فاعل', 'شرف', 'مشرف', 'مشرف', 'فَا. مِن أَشْرَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ج:"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَشْرَفَ). 1.""مُشْرِفٌ عَلَى سَيْرِ الأَعْمَالِ"" : الْمَسْؤُولُ عَنْهَا. ""مُشْرِفٌ تَرْبَوِيّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(460, 'مُشْرِقٌ', 'مشرق', 'اسم فاعل', 'شرق', 'مشرق', 'مشرق', 'فَا. مِن أَشْرَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَشْرَقَ) ""مُشْرِقُ الوَجْهِ"" : مُضِيءٌ، مُتَلَأْلِئٌ حُسْناً. ""كَانَ رَجُلاً صَالِحاً طَيِّبَ القَلْبِ مُشْرِقَ الوَجْهِ فِي نَضْرَةٍ وَحُمْرَةٍ"". (أ. أمين) ""شَمْسٌ مُشْرِقَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(461, 'مُصِرٌّ', 'مصر', 'اسم فاعل', 'صرر', 'مصر', 'مصر', 'فَا. مِن أَصَرَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَصَرَّ). ""مُصِرٌّ عَلَى مَوْقِفِهِ"": ثَابِتٌ، مُلاَزِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(462, 'مُشْعِلٌ', 'مشعل', 'اسم فاعل', 'شعل', 'مشعل', 'مشعل', 'فَا. مِن أَشْعَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَشْعَلَ). 1.""مُشْعِلُ النَّارِ"" : مُوقِدُهَا. 2.""مُشْعِلُ الفِتَنِ"" : مُحَرِّكُهَا، مُحْدِثُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(463, 'مُشْفِقٌ', 'مشفق', 'اسم فاعل', 'شفق', 'مشفق', 'مشفق', 'فَا. مِن أَشْفَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَشْفَقَ). 1.""مُشْفِقٌ عَلَى حَالِهِ"" : عَاطِفٌ عَلَى حَالِهِ، أَيْ تَأْخُذُهُ الشَّفَقَةُ وَالرَّحْمَةُ وَالعَطْفُ. 2.الأنبياء آية 49 وهُمْ مِنَ السَّاعَةِ مُشْفِقُونَ (قرآن) : حَذِرُونَ، خَائِفُونَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(464, 'مُشْكِلٌ', 'مشكل', 'اسم فاعل', 'شكل', 'مشكل', 'مشكل', 'فا. مِن أَشْكَلَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":مَشَاكِلُ"', '', '', '', '', '', '', '', '', '"(فا. مِن أَشْكَلَ). 1.""اِعْتَرَضَهُ مُشْكِلٌ عَوِيصٌ"" : أَمْرٌ صَعْبٌ، مُلْتَبِسٌ، غَامِضٌ. 2.""مُشْكِلَةٌ سِيَاسِيَّةٌ"" : قَضِيَّةٌ تَحْتَاجُ إِلَى حَلٍّ وَمُعَالَجَةٍ. 3.""خُنْثَى مُشْكِلٌ"" : عَدَمُ وُضُوحِ أَيِّ الجِنْسَيْنِ هُوَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(465, 'مَشَاكِلُ', 'مشاكل', 'اسم فاعل', '', 'مشاكل', 'مشكل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(466, 'مُشْمَئِزٌّ', 'مشمئز', 'اسم فاعل', 'شمأز', 'مشمءز', 'مشمز', 'فا. مِن اِشْمَأَزَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُشْمَئِزٌّ-مُشْمَئِزٌّ [ش م أ ز] (فا. مِن اِشْمَأَزَّ). ""مُشْمَئِزٌّ مِنْ سُلُوكِهِ"" : مُتَقَزِّزٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(467, 'مُشْمَخِرٌّ', 'مشمخر', 'اسم فاعل', 'شمخر', 'مشمخر', 'مشمخر', 'فا. من اِشْمَخَرَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِشْمَخَرَّ). ""كَانَ مُشْمَخِرّاً فِي سُلُوكِهِ"" : مُتَكَبِّراً. ""وَجَدَهُ مُشْمَخِرَّ الأَنْفِ مُصَعَّرَ الخَدَّيْنِ مُنْتَفِخَ الأَوْدَاجِ"". (إسحق الحسيني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(468, 'مُشْمِسٌ', 'مشمس', 'اسم فاعل', 'شمس', 'مشمس', 'مشمس', 'فا. من أَشْمَسَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشْمِسٌ-مُشْمِسٌ [ش م س] (فا. من أَشْمَسَ). ""نَهَارٌ مُشْمِسٌ"": شَمْسُهُ مُشْرِقَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(469, 'مُصِيبٌ', 'مصيب', 'اسم فاعل', 'صوب', 'مصيب', 'مصب', 'فَا. مِن أَصَابَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَصَابَ). ""مُصِيبٌ فِي رَأْيِهِ"" : أَيْ ك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(470, 'مُصْدِرٌ', 'مصدر', 'اسم فاعل', 'صدر', 'مصدر', 'مصدر', 'فَا. مِن أَصْدَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَصْدَرَ). 1.""مُصْدِرٌ للأَوَامِرِ"" : مَنْ يُصْدِرُهَا وَيَأْمُرُ بِهَا. 2.""جِهَازٌ مُصْدِرٌ لِلصَّوْتِ"" : مُرْسِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(471, 'مُضْرِبٌ', 'مضرب', 'اسم فاعل', 'ضرب', 'مضرب', 'مضرب', 'فَا. مِن أَضْرَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَضْرَبَ). 1.""عَامِلٌ مُضْرِبٌ عَنِ العَمَلِ"" : الْمُنْقَطِعُ عَنِ العَمَلِ لِسَبَبٍ مِنَ الأَسْبَابِ كَعَدَمِ تَنْفِيذِ مَطْلَبٍ مِنْ مَطَالِبِهِ. 2.""مُضْرِبٌ عَنِ الطَّعَامِ"" : مُمْسِكٌ عَنِ الطَّعَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(472, 'مُصْطَحِبٌ', 'مصطحب', 'اسم فاعل', 'صحب', 'مصطحب', 'مصطحب', 'فَا. مِن اِصْطَحَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِصْطَحَبَ). ""خَرَجَ لِلنُّزْهَةِ مُصْطَحِباً أَوْلاَدَهُ"" : مُرَافِقاً لَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(473, 'مُصْغِي', 'مصغي', 'اسم فاعل', 'صغو', 'مصغي', 'مصغ', 'فَا. مِن أَصْغَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَصْغَى). ""كَانَ مُصْغِياً إِلَى حَدِيثِهِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(474, 'مُصْفَرٌّ', 'مصفر', 'اسم فاعل', 'صفر', 'مصفر', 'مصفر', 'فَا. مِن اِصْفَرَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِصْفَرَّ). ""مُصْفَرُّ الوَجْهِ"" : مَنْ عَلَتْ وَجْهَهُ صُفْرَةٌ نَتِيجَةَ مَرَضٍ أَوْ فَزَعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(475, 'مُصْلِحٌ', 'مصلح', 'اسم فاعل', 'صلح', 'مصلح', 'مصلح', 'فَا. مِن أَصْلَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَصْلَحَ). 1.""مُصْلِحُ الأَخْطَاءِ وَالْهَفَوَاتِ"" : مَنْ يُقَوِّمُ مَا اعْوَجَّ وَفَسَدَ. 2.""مُصْلِحٌ ذَاتِ بَيْنِ النَّاسِ"" : مَنْ يَسْعَى إِلَى الصُّلْحِ بَيْنَهُمْ. ""مُصْلِح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(476, 'مُضِيءٌ', 'مضيء', 'اسم فاعل', 'ضوأ', 'مضيء', 'مض', 'فَا. مِن أَضَاءَ', '', '', 'مفرد', 'Dz', 'Pm', '', '""', '', '', 'ـو', '', '', '', '', 'Cv', '"مُضِيءٌ-مُضِيءٌ، ةٌ [ض و أ] (فَا. مِن أَضَاءَ). ""بَيْتٌ مُضِيءٌ"": مُنِيرٌ، مُشِعٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(477, 'مُضِيئَةٌ', 'مضيئة', 'اسم فاعل', '', 'مضيءة', 'مضة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُضِيءٌ-مُضِيءٌ، ةٌ [ض و أ] (فَا. مِن أَضَاءَ). ""بَيْتٌ مُضِيءٌ"": مُنِيرٌ، مُشِعٌّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(478, 'مُضْجِرٌ', 'مضجر', 'اسم فاعل', 'ضجر', 'مضجر', 'مضجر', 'فَا. مِن أَضْجَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَضَاجِرُ"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَضْجَرَ). ""قَامَ بِعَمَلٍ مُضْجِرٍ"" : قَامَ بِعَمَلٍ مُسَبِّبٍ لِلضَّجَرِ وَالضِّيقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(479, 'مَضَاجِرُ', 'مضاجر', 'اسم فاعل', '', 'مضاجر', 'مضجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(480, 'مُضْحِكٌ', 'مضحك', 'اسم فاعل', 'ضحك', 'مضحك', 'مضحك', 'فَا. مِن أَضْحَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَضْحَكَ). ""جَاءَ عَمَلُهُ مُضْحِكاً"" : مُثِيراً لِلضَّحِكِ، بَاعِثاً عَلَى الضَّحِكِ. ""حَرَكَاتٌ مُضْحِكَةٌ"" ""تَمْثِيلِيَّةٌ مُضْحِكَةٌ"" ""مِنَ الْمُضْحِكَاتِ مَا يُبْكِي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(481, 'مُطْرِقٌ', 'مطرق', 'اسم فاعل', 'طرق', 'مطرق', 'مطرق', 'فَا. مِن أَطْرَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَطْرَقَ). ""اِسْتَمَعَ إِلَى حِكَايَتِهَا وَهُوَ مُطْرِقٌ"" : مُطَأْطِئُ الرَّأْسِ. ""رَأْسُهُ مُطْرِقٌ وَيَدَاهُ تَضُمَّانِ طَرَفَ عَبَاءتِهِ السَّوْدَاءِ"". (جمال الغيطاني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(482, 'مُضْطَرِبٌ', 'مضطرب', 'اسم فاعل', 'ضرب', 'مضطرب', 'مضطرب', 'فَا. مِن اِضْطَرَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِضْطَرَبَ). ""وَجَدَهُ مُضْطَرِباً"" : مُرْتَبِكاً، مُهْتَزّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(483, 'مُضْطَرِمٌ', 'مضطرم', 'اسم فاعل', 'ضرم', 'مضطرم', 'مضطرم', 'فَا. مِن اِضْطَرَمَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِن اِضْطَرَمَ). 1.""نَارٌ مُضْطَرِمَةٌ"" : مُشْتَعِلَةٌ. 2.""مُضْطَرِمُ العَوَاطِفِ"": مُشْتَعِلُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(484, 'مُضْطَهِدٌ', 'مضطهد', 'اسم فاعل', 'ضهد', 'مضطهد', 'مضطهد', 'فَا. مِن اِضْطَهَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِضْطَهَدَ). ""قَائِدٌ مُضْطَهِدٌ"" : مَنْ يُعَرِّضُ النَّاسَ لِلظُّلْمِ وَالقَهْرِ، قَاهِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(485, 'مُضِلٌّ', 'مضل', 'اسم فاعل', 'ضلل', 'مضل', 'مضل', 'فَا. مِن أَضَلَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَضَلَّ). 1.""مُضِلٌّ لِلنَّاسِ"" : مَنْ يَغْوِيهِمْ وَيَقُودُهُمْ إِلَى الضَّلاَلِ. 2.""مُضِلُّ الصَّحْرَاءِ"" : سَرَابُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(486, 'مُضْنِي', 'مضني', 'اسم فاعل', 'ضني', 'مضني', 'مضن', 'فَا. مِن أَضْنَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُضْنٍ-مُضْنٍ، الْمُضْنِي، ةٌ [ض ن ي] (فَا. مِن أَضْنَى). ""قَامَ بِعَمَلٍ مُضْنٍ"" : مُرْهِقٍ، مُتْعِبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(487, 'مُطْبِقٌ', 'مطبق', 'اسم فاعل', 'طبق', 'مطبق', 'مطبق', 'فَا. مِن أَطْبَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُطْبِقٌ-مُطْبِقٌ [ط ب ق] (فَا. مِن أَطْبَقَ). 1.""حَبَسُوهُ فِي الْمُطْبِقِ"" : الْحَبْسُ تَحْتَ الأَرْضِ. 2.""جُنُونٌ مُطْبِقٌ"" : جُنُونٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(488, 'مُطْرِبٌ', 'مطرب', 'اسم فاعل', 'طرب', 'مطرب', 'مطرب', 'فَا. مِن أَطْرَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَطْرَبَ). ""مُطْرِبٌ ذُو صَوْتٍ جَمِيلٍ"" : الْمُغَنِّي الَّذِي يُطْرِبُ السَّامِعِينَ بِحُسْنِ صَوْتِهِ وَغِنَائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(489, 'مُطَّرِدٌ', 'مطرد', 'اسم فاعل', 'طرد', 'مطرد', 'مطرد', 'فَا. مِن اِطَّرَدَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُطَّرِدٌ-مُطَّرِدٌ، ةٌ [ط ر د] (فَا. مِن اِطَّرَدَ). 1.""عَمَلٌ مُطَّرِد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(490, 'مُطْرِفٌ', 'مطرف', 'اسم فاعل', 'طرف', 'مطرف', 'مطرف', 'فَا. مِن أَطْرَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُطْرَفٌ-مُطْرَفٌ [ط ر ف]. : رِدَاءٌ أَوْ ثَوْبٌ مِنْ خَزٍّ مُرَبَّعٌ ذُو أَعْلاَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(491, 'مُطْفِئٌ', 'مطفئ', 'اسم فاعل', 'طفأ', 'مطفء', 'مطف', 'فَا. مِن أَطْفَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَطْفَأَ). 1.""مُطَفِئُ النِّيرَانِ"" : مُخْمِدُهَا. 2.""مَادَّةٌ مُطْفِئَةٌ"" : مَادَّةٌ تُخْمِدُ مَا اشْتَعَلَ. 3.""مُطْفِئُ الْجَمْرِ"" : الأَيَّامُ البَارِدَةُ. 4.""مُطْفِئُ الرَّضْفِ"" : الدَّاهِيَةُ، الْمُصِيبَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(492, 'مُطِلٌّ', 'مطل', 'اسم فاعل', 'طلل', 'مطل', 'مطل', 'فَا. مِن أَطَلَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَطَلَّ). 1.""رَآهُ مُطِلاًّ مِنَ النَّافِذَةِ"" : مُشْرِفاً مِنْهَا. 2.""نَافِذَةٌ مُطِلَّةٌ عَلَى الْحَدِيقَةِ"" : مُشْرِفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(493, 'مُطَّلِعٌ', 'مطلع', 'اسم فاعل', 'طلع', 'مطلع', 'مطلع', 'فا. مِن اِطَّلَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِن اِطَّلَعَ). 1.""مُطَّلِعٌ عَلَى الأُمُورِ"" : مُلِمٌّ بِهَا، لَهُ مَعْرِفَةٌ كَبِيرَةٌ بِهَا. 2.""الأَوْسَاطُ الْمُطَّلِعَةُ"": الأَوْسَاطُ العَلِيمَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(494, 'مُطْلِقٌ', 'مطلق', 'اسم فاعل', 'طلق', 'مطلق', 'مطلق', 'فَا. مِن أَطْلَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُطْلِقٌ، ةٌ - [ط ل ق]. (فَا. مِن أَطْلَقَ). ""مُطْلِقُ الرُّمْحِ"": رَامٍ، قَاذِفٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(495, 'مُطْمَئِنٌّ', 'مطمئن', 'اسم فاعل', 'طمن', 'مطمءن', 'مطمن', 'فَا. مِن اِطْمَأَنَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِطْمَأَنَّ). 1.""مُطْمَئِنٌّ فِي مَخْبَئِهِ"" : مُرْتَاحٌ. 2.""مُطْمَئِنٌّ عَلَى مُسْتَقْبَلِهِ"" : مُرْتَاحُ البَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(496, 'مُطْنِبٌ', 'مطنب', 'اسم فاعل', 'طنب', 'مطنب', 'مطنب', 'فَا. مِن أَطْنَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَطْنَبَ). ""مُطْنِبٌ فِي حَدِيثِهِ"" : مُسْهِبٌ، أَيْ مَنْ يُطِيلُ وَيُسْهِبُ فِي حَدِيثِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(497, 'مُظِلٌّ', 'مظل', 'اسم فاعل', 'ظلل', 'مظل', 'مظل', 'فَا. مِن أَظَلَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُظِلٌّ-مُظِلٌّ [ظ ل ل] (فَا. مِن أَظَلَّ). ""يَوْمٌ مُظِلٌّ"" : دَائِمُ الظِّلِّ. ""مَكَانٌ مُظِلٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(498, 'مُظْلِمٌ', 'مظلم', 'اسم فاعل', 'ظلم', 'مظلم', 'مظلم', 'فَا. مِن أَظْلَمَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُظْلِمٌ-مُظْلِمٌ، ةٌ [ظ ل م] (فَا. مِن أَظْلَمَ). 1.""بَيْتٌ مُظْلِمٌ"": بَيْتٌ حَالِكُ السَّوَادِ، سَوَادُ اللَّيْلِ. 2.""يَوْمٌ مُظْلِمٌ"" : يَوْمٌ كَثِيرُ الشَّرِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(499, 'مُعِيدٌ', 'معيد', 'اسم فاعل', 'عود', 'معيد', 'معد', 'فَا. مِن أَعَادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَعَادَ). 1.""مُعِيدٌ لِمَا سَمِعَهُ"" : مُكَرِّرٌ... 2. ""رَجُلٌ مُعِيدٌ"" : الْحَاذِقُ، الْمُجَرِّبُ لِلأُمُورِ والعَارِفُ بِهَا. 3.""مُعِيدٌ بِالجَامِعَةِ"" : مَنْ يُسْنَدُ إِلَيْهِ تَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(500, 'مُعِيقٌ', 'معيق', 'اسم فاعل', 'عيق', 'معيق', 'معق', 'فَا. مِن أَعَاقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَعَاقَ). ""مُعِيقٌ عَنِ العَمَلِ"" : مَانِعٌ لَهُ، مُثَبِّطٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(501, 'مُعِيلٌ', 'معيل', 'اسم فاعل', 'عول', 'معيل', 'معل', 'فَا. مِن أَعَالَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَعَالَ). 1.""مُعِيلٌ عِيَالَهُ"" : أَي القَائِمُ بِأَوَدِهِمْ وم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(502, 'مُعِينٌ', 'معين', 'اسم فاعل', 'عين', 'معين', 'معن', 'فَا. مِن أَعَانَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَعَانَ) ""هُوَ مُعِينُهُ"" : مُسَاعِدُهُ. ""اللَّهُ الْمُعِينُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(503, 'مُعْتَدٌّ', 'معتد', 'اسم فاعل', 'عدد', 'معتد', 'معتد', 'فَا. مِن اِعْتَدَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُعْتَدٌّ-مُعْتَدٌّ [ع د د] (فَا. مِن اِعْتَدَّ). ""مُعْتَدٌّ بِنَفْسِهِ"" : وَاثِقٌ مِنْ نَفْسِهِ، مُفْرِطٌ فِي الاعْتِدَادِ بِنَفْسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(504, 'مُعْتَدِلٌ', 'معتدل', 'اسم فاعل', 'عدل', 'معتدل', 'معتدل', 'فَا. مِن اِعْتَدَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِعْتَدَلَ). 1.""رَجُلٌ مُعْتَدِلُ القَامَةِ"" : أَيْ مَا بَيْنَ الطُّولِ وَالقِصَرِ. 2.""جَوٌّ مُعْتَدِلٌ"" : أَيْ مَا بَيْنَ الْحَارِّ وَالبَارِدِ. 3.""المِنْطَقَةُ الْمُعْتَدِلَةُ"" : المِنْطَقَةُ الْمُتَجَاوِرَةُ لِلْمِنْطَقَةِ الاسْتِوَائِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(505, 'مُعْتَدِي', 'معتدي', 'اسم فاعل', 'عدو', 'معتدي', 'معتد', 'فَا. مِن اِعْتَدَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِعْتَدَى). ""هُوَ الْمُعْتَدِي عَلَيْهِ"" : الْمُهَاجِمُ، الظَّالِمُ. ""جُيُوشٌ مُعْتَدِيَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(506, 'مُعْتَرِضٌ', 'معترض', 'اسم فاعل', 'عرض', 'معترض', 'معترض', 'فَا. مِن اِعْتَرَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِعْتَرَضَ). 1.""أَجَابَهُ مُعْتَرِضاً عَلَى كَلاَمِهِ"" : مُخَالِفاً لِكَلاَمِهِ، أَوْ مُسْتَنْكِراً. 2.""وَقَفَ مُعْتَرِضاً طَرِيقَهُ"" : وَقَفَ مَانِعاً إِيَّاهُ مِنَ الْمُرُورِ. 3.""جُمْلَةٌ مُعْتَرِضَةٌ"" : جُمْلَةٌ تَقَعُ بَيْنَ جُزْأَيْ جُمْلَةٍ أُخْرَى وَتوضَعُ بَيْنَ عارِضَتَيْنِ : ""كَانَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(507, 'مُعْتَرِفٌ', 'معترف', 'اسم فاعل', 'عرف', 'معترف', 'معترف', 'فَا. مِن اِعْتَرَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِعْتَرَفَ). ""مُعْتَرِفٌ بِأَخْطَائِهِ"" : مُقِرٌّ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(508, 'مُعْتَزِلٌ', 'معتزل', 'اسم فاعل', 'عزل', 'معتزل', 'معتزل', 'فَا. مِن اِعْتَزَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِعْتَزَلَ). ""مُعْتَزِلٌ عَنِ النَّاسِ"" : مَنْ يَعِيشُ فِي عُزْلَةٍ عَنِ النَّاسِ، الْمُنْزَوِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(509, 'مُعْتَصِمٌ', 'معتصم', 'اسم فاعل', 'عصم', 'معتصم', 'معتصم', 'فَا. مِن اِعْتَصَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِعْتَصَمَ). 1.""مُعْتَصِمٌ بِحَبْلِ اللهِ"" : مُتَمَسِّكٌ... 2.: اِسْمُ عَلَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(510, 'مُعْتَقِدٌ', 'معتقد', 'اسم فاعل', 'عقد', 'معتقد', 'معتقد', 'فَا. مِن اِعْتَقَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِعْتَقَدَ). ""مُعْتَقِدٌ فِيمَا حَصَلَ"" : مُصَدِّقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(511, 'مُعْدِي', 'معدي', 'اسم فاعل', 'عدو', 'معدي', 'معد', 'فَا. مِن أَعْدَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُعْدٍ-مُعْدٍ، الْمُعْدِي، ةٌ [ع د و] (فَا. مِن أَعْدَى). ""مَرَضٌ مُعْدٍ"" : أَيْ مَرَضٌ تَنْتَقِلُ عَدْوَاهُ مِنْ مَرِيضٍ إِلَى إِنْسَانٍ آخَرَ لَمْ يَكُنْ مُصَاباً بِهِ مِنْ قَبْلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(512, 'مُعْتِمٌ', 'معتم', 'اسم فاعل', 'عتم', 'معتم', 'معتم', 'فَا. مِن أَعْتَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُعْتِمٌ-مُعْتِمٌ، ةٌ [ع ت م] (فَا. مِن أَعْتَمَ). ""مَكَانٌ مُعْتِمٌ"" : مُظْلِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(513, 'مُعْتَمِدٌ', 'معتمد', 'اسم فاعل', 'عمد', 'معتمد', 'معتمد', 'فا. من اِعْتَمَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِعْتَمَدَ). 1.""مُعْتَمِدٌ عَلَيْهِ"" : مُتَّكِئٌ، مُتَّكِلٌ. 2.: اِسْمُ عَلَمٍ لِلذُّكُورِ."', '');
