INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(525, 'مُعْشِبٌ', 'معشب', 'اسم فاعل', 'عشب', 'معشب', 'معشب', 'فَا. مِن أَعْشَبَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعْشِبٌ-مُعْشِبٌ، ةٌ [ع ش ب] (فَا. مِن أَعْشَبَ). ""حَقْلٌ مُعْشِبٌ"" : ذُو عُشْبٍ، كَثِيرُ العُشْبِ. ""أَرْضٌ مُعْشِبَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(526, 'مُعْصِفٌ', 'معصف', 'اسم فاعل', 'عصف', 'معصف', 'معصف', 'فَا. مِن أَعْصَفَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":مَعَاصِفُ"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَعْصَفَ). ""رِيحٌ مُعْصِفٌ"" : شَدِيدَةٌ. ""رِيحٌ مُعْصِفَةٌ""."', '');
