INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(540, 'مُغْتَصِبٌ', 'مغتصب', 'اسم فاعل', 'غصب', 'مغتصب', 'مغتصب', 'فَا. مِن اِغْتَصَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِغْتَصَبَ). ""مُغْتَصِبٌ أَمْوَالَ غَيْرِهِ"" : مُسْتَوْلٍ عَلَيْهَا قَهْراً وغَصْباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(541, 'مُفْحِمٌ', 'مفحم', 'اسم فاعل', 'فحم', 'مفحم', 'مفحم', 'فَا. مِن أَفْحَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن أَفْحَمَ). ""كَانَ مُفْحِماً فِي جَوَابِهِ"" : مُقْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(542, 'مُغْتَمِرٌ', 'مغتمر', 'اسم فاعل', 'غمر', 'مغتمر', 'مغتمر', 'فَا. مِن اِغْتَمَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِغْتَمَرَ). 1.""رَجُلٌ مُغْتَمِرٌ"" : سَكْرَانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(543, 'مُغْرِضٌ', 'مغرض', 'اسم فاعل', 'غرض', 'مغرض', 'مغرض', 'فَا. مِنْ أَغْرَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ أَغْرَضَ). ""مُغْرِضٌ فِي قَوْلِهِ"" : جَاعِلٌ لِقَوْلِهِ غَرَضا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(544, 'مُغْرِي', 'مغري', 'اسم فاعل', 'غرو', 'مغري', 'مغر', 'فَا. مِن أَغْرَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَغْرَى). 1. ""اِمْرَأَةٌ مُغْرِيَةٌ"" : فَاتِنَةٌ بِمَفَاتِنِهَا. 2. ""عَمَلٌ مُغْرٍ"": مُثِيرٌ. 3. ""ثَمَنٌ مُغْرٍ"" : مُنَاسِبٌ جِدّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(545, 'مُغْنِي', 'مغني', 'اسم فاعل', 'غني', 'مغني', 'مغن', 'فا. من أَغْنَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَغْنَى). 1. ""هُوَ اللَّهُ الْمُغْنِي"" : اِسْمٌ مِنْ أَسْمَاءِ الله تَعَالَى، أَيْ هُوَ الَّذِي يُغْنِي مَنْ يَشَاءُ مِنْ عِب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(546, 'مُفِيدٌ', 'مفيد', 'اسم فاعل', 'فود،فيد', 'مفيد', 'مفد', 'فا. من أَفَادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُفِيدٌ-مُفِيدٌ، ةٌ [ف و د، ف ي د] (فا. من أَفَادَ). 1.""كَلاَمٌ مُفِيدٌ"" : تَامٌّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(547, 'مُفْتَرِسٌ', 'مفترس', 'اسم فاعل', 'فرس', 'مفترس', 'مفترس', 'فَا. مِن اِفْتَرَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن اِفْتَرَسَ). ""حَيَوَانٌ مُفْتَرِسٌ"" : الْحَيَوَانُ الَّذِي يَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(548, 'مُفْتَقِرٌ', 'مفتقر', 'اسم فاعل', 'فقر', 'مفتقر', 'مفتقر', 'فَا. مِن اِفْتَقَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِفْتَقَرَ). ""مُفْتَقِرٌ إِلَى الْمَالِ"" : مُحْتَاجٌ إِلَيْهِ وهُوَ غَيْرُ مَوْجُودٍ لَدَيْهِ. ""مُفْتَقِرٌ إِلَى الذَّكَاءِ لِتُحَلَّ مَشَاكِلُهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(549, 'مُفْتِي', 'مفتي', 'اسم فاعل', 'فتو', 'مفتي', 'مفت', 'فَا. مِن أَفْتَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُفْتٍ-مُفْتٍ، الْمُفْتِي [ف ت و] (فَا. مِن أَفْتَى). ""أَفْتَى الْمُفْتِي وَحُسِمَ الأَمْرُ"" : الفَقِيهُ العَالِمُ بِالشَّرِيعَةِ، يُعْطِي الفَتْوَى، الفَتَاو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(550, 'مُفْجِعٌ', 'مفجع', 'اسم فاعل', 'فجع', 'مفجع', 'مفجع', 'فَا. مِن أَفْجَعَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"أفْجَعَ - [ف ج ع]. (ف: ربا. متعد). أفْجَعَ، يُفْجِعُ، مص. إفْجَاعٌ. ""أفْجَعَتْهُ الْمَصَائِبُ"" : أوْجَعَتْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(551, 'أوافل', 'أوافل', 'اسم فاعل', '', 'ءوافل', 'فل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(552, 'مُفْرِحٌ', 'مفرح', 'اسم فاعل', 'فرح', 'مفرح', 'مفرح', 'فَا. مِن أَفْرَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن أَفْرَحَ). ""نَبَأٌ مُفْرِحٌ"" : مُسِرٌّ، مُبْهِجٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(553, 'مُفْرِطٌ', 'مفرط', 'اسم فاعل', 'فرط', 'مفرط', 'مفرط', 'فا. من أَفْرَطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَفْرَطَ). 1.""مُفْرِطٌ فِي الأَكْلِ"" : مُتَجَاوِزٌ لِلْحَدِّ الْمَعْقُولِ فِي الأَكْلِ. غَايَــةُ الْمُفْــرِطِ فِي سِلْمِـهِ*كَغَايَـةِ الْمُفْـرِطِ فِي حَرْبِــهِ (المتنبي). 2.""مُفْرِطُ الْحَسَاسِيَّةِ"" : حَسَاسِيَّتُهُ زَائِدَةٌ عَلَى اللُّزُومِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(554, 'مُفْزِعٌ', 'مفزع', 'اسم فاعل', 'فزع', 'مفزع', 'مفزع', 'فا. من أَفْزَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَفْزَعَ). ""حَادِثٌ مُفْزِعٌ"" : يُثِيرُ الفَزَعَ، الخَوْفَ. ""غَارَةٌ مُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(555, 'مُفْسِدٌ', 'مفسد', 'اسم فاعل', 'فسد', 'مفسد', 'مفسد', 'فا. من أَفْسَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَفْسَدَ). ""مُفْسِدُ الأَخْلاَقِ"" : مَنْ يَجْعَلُهَا فَاسِدَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(556, 'مُفْشِي', 'مفشي', 'اسم فاعل', 'فشو', 'مفشي', 'مفش', 'فا. من أَفْشَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَفْشَى). ""مُفْشي الأَسْرَارِ"" : مُذِيعُهَا ونَاشِرُهَا بَيْنَ النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(557, 'مُفْصِحٌ', 'مفصح', 'اسم فاعل', 'فصح', 'مفصح', 'مفصح', 'فا. من أَفْصَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَفْصَحَ). 1. ""مُفْصِحٌ فِي كَلاَمِهِ"" : وَاضِحٌ، مُبَيِّنٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(558, 'آفِلٌ', 'آفل', 'اسم فاعل', 'أفل', 'ءافل', 'آفل', 'فا. من أَفَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":أُفَّلٌ:أُفُولُ"', '', '', '', '', '', '', '', '', '"(فا. من أَفَلَ) ""كَعْبُهُ سَافِلٌ وَنَجْمُهُ آفِلٌ"" : غَائِبٌ، سَاقِطٌ.الأنعام آية 76فَلَمَّا أفَلَ قَالَ إِنِّي لاَ أُحِبُّ الآفِلِين (قرآن) ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(559, 'أُفَّلٌ', 'أفل', 'اسم فاعل', '', 'ءفل', 'فل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(560, 'أُفُولٌ', 'أفول', 'اسم فاعل', '', 'ءفول', 'فل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(561, 'مُقْتَرِفٌ', 'مقترف', 'اسم فاعل', 'قرف', 'مقترف', 'مقترف', 'فا. من اِقْتَرَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِقْتَرَفَ). ""مُقْتَرِفُ الجَرِيمَةِ"" : مُرْتَكِبُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(562, 'مُفْلِسٌ', 'مفلس', 'اسم فاعل', 'فلس', 'مفلس', 'مفلس', 'فا. من أَفْلَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَفْلَسَ). ""تَاجِرٌ مُفْلِسٌ"" : تَاجِرٌ مُصَابٌ بِالإِفْلاَسِ، أَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(563, 'مُفْلِقٌ', 'مفلق', 'اسم فاعل', 'فلق', 'مفلق', 'مفلق', 'فا. من أَفْلَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَفْلَقَ). ""شَاعِرٌ مُفْلِقٌ"" : جَيِّدٌ، مُبْدِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(564, 'مُقِيمٌ', 'مقيم', 'اسم فاعل', 'قوم', 'مقيم', 'مقم', 'فا. من أَقَامَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَقَامَ). 1. ""مُقِيمٌ فِي بِلاَدِ الغَرْبِ مُنْذُ زَمَنٍ طَوِيلٍ"" : مَنِ اتَّخَذَهَا مُقَاماً لَهُ. 2.""مُقِيمُ الصَّلاَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(565, 'مُقْبِلٌ', 'مقبل', 'اسم فاعل', 'قبل', 'مقبل', 'مقبل', 'فا. من أَقْبَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَقْبَلَ). 1. ""فِي الشَّهْرِ الْمُقْبِلِ"" : فِي الشَّهْرِ الآتِي. ""فِي السَّنَةِ الْمُقْبِلَةِ"". 2. ""الْمُدِيرُ مُقْبِلٌ"" : آتٍ. ""هَيْفَاءُ مُقْبِلَةٌ عَجْزَاءُ مُدْبِرَةٌ"". (كعب بن زهير). 3."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(566, 'مُقْتَبِسٌ', 'مقتبس', 'اسم فاعل', 'قبس', 'مقتبس', 'مقتبس', 'فا. من اقْتَبَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اقْتَبَسَ). 1. ""جَاءَ فِي ظُلْمَةِ اللَّيْلِ مُقْتَبِساً"" : طَالِباً نَاراً. 2.""مُقْتَبَسُ العِلْمِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(567, 'مُقْتَحِمٌ', 'مقتحم', 'اسم فاعل', 'قحم', 'مقتحم', 'مقتحم', 'فا. من اِقْتَحَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِقْتَحَمَ). ""مُقْتَحِمُ الْمَكَانِ"" : دَاخِلٌ لَهُ عَنْوَةً وق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(568, 'مُقْتَرِحٌ', 'مقترح', 'اسم فاعل', 'قرح', 'مقترح', 'مقترح', 'فا. من اِقْتَرَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِقْتَرَحَ). ""مُقْتَرِحُ كَذَا"" : مَنْ يُقَدّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(569, 'مُقْتَرِضٌ', 'مقترض', 'اسم فاعل', 'قرض', 'مقترض', 'مقترض', 'فا. من اِقْتَرَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِقْتَرَضَ). ""مُقْتَرِضٌ مِنْ صَدِيقِهِ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(570, 'مُقْتَرِعٌ', 'مقترع', 'اسم فاعل', 'قرع', 'مقترع', 'مقترع', 'فا. من اِقْتَرَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِقْتَرَعَ). ""الْمُقْتَرِعُ فِي الانْتِخَابِ"" : الْمُصَوِّتُ. """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(571, 'مُقْفِرٌ', 'مقفر', 'اسم فاعل', 'قفر', 'مقفر', 'مقفر', 'فا. من أَقْفَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقْفِرٌ، ةٌ - [ق ف ر]. (فا. من أَقْفَرَ). ""مَكَانٌ مُقْفِرٌ"" : خَالٍ مِنَ العُشْبِ والنَّاسِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(572, 'مُقْتَرِنٌ', 'مقترن', 'اسم فاعل', 'قرن', 'مقترن', 'مقترن', 'فا. من اِقْتَرَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِقْتَرَنَ). ""اِسْمُهُ مُقْتَرِنٌ بِكُلِّ الانْتِصَارَاتِ الْمَجِيدَةِ"" : مُرْتَبِطٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(573, 'مُقْتَصِدٌ', 'مقتصد', 'اسم فاعل', 'قصد', 'مقتصد', 'مقتصد', 'فا. من اِقْتَصَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِقْتَصَدَ). 1. ""مُقْتَصِدٌ فِي عَمَلِهِ"" : الْمُتَّزِنُ فِي عَمَلِهِ والْمُسَيِّرُ لَهُ بِلاَ إِفْرَاطٍ ولاَ تَفْرِيطٍ. المائدة آية 66 ومِنْهُمْ أُمَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(574, 'مُقْتَلِعٌ', 'مقتلع', 'اسم فاعل', 'قلع', 'مقتلع', 'مقتلع', 'فا. من اِقْتَلَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِقْتَلَعَ). ""مُقْتَلِعُ الشَّج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(575, 'مُقْتَنِي', 'مقتني', 'اسم فاعل', 'قني', 'مقتني', 'مقتن', 'فا. من اِقْتَنَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِقْتَنَى). ""مُقْتَني الْمَالِ"" : جَامِعُهُ، مُمْتَلِكُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(576, 'مُقْذِعٌ', 'مقذع', 'اسم فاعل', 'قذع', 'مقذع', 'مقذع', 'فا. من أَقْذَعَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فا. من أَقْذَعَ). 1.""كَلاَمٌ مُقْذِعٌ"" : فَاحِشٌ. ""هِجَاءٌ مُقْذِعٌ"". 2. ""فَاهَ بِمُقْذِعَاتٍ لاَ قِبَلَ لَهُ بِهَا"" : الشَّتَائِمُ الْمُسْتَقْبَحَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(577, 'مُقْرِضٌ', 'مقرض', 'اسم فاعل', 'قرض', 'مقرض', 'مقرض', 'فا. من أَقْرَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَقْرَضَ). ""مُقْرِضُ الأَمْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(578, 'مُقْرِفٌ', 'مقرف', 'اسم فاعل', 'قرف', 'مقرف', 'مقرف', 'فا. من أَقْرَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَقْرَفَ). 1.""رَجُلٌ مُقْرِفٌ"" : نَذْلٌ، خَسِيسٌ. 2.""وَجْهٌ مُقْرِفٌ"": قَبِيحُ الخِلْقَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(579, 'مُقْسِطٌ', 'مقسط', 'اسم فاعل', 'قسط', 'مقسط', 'مقسط', 'فا. من أَقْسَطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَقْسَطَ). 1. ""كَانَ مُقْسِطاً بَيْنَ النَّاسِ"" : عَادِلاً، مُنْصِفاً. 2.""الله الْمُقْسِطُ"" : مِنْ أَسْمَاءِ الله الْحُسْنَى، ومَعْنَاهُ العَادِلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(580, 'مُقْشَعِرٌّ', 'مقشعر', 'اسم فاعل', 'قشعر', 'مقشعر', 'مقشعر', 'فا. من اِقْشَعَرَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِقْشَعَرَّ).""مُقْشَعِرٌّ بَرْدًا"" : مَنْ أَخَذَتْهُ الرِّعْدَةُ فَأَحْدَثَتْ فِي جِسْمِهِ قُشَعْرِيرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(581, 'مُكْتَسِحٌ', 'مكتسح', 'اسم فاعل', 'كسح', 'مكتسح', 'مكتسح', 'فا. من اِكْتَسَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُكْتَسِحٌ-مُكْتَسِحٌ [ك س ح] (فا. من اِكْتَسَحَ). 1.""جَيْشٌ مُكْتَسِحٌ كَلَّ الأَرَاض"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(582, 'مُقِلٌّ', 'مقل', 'اسم فاعل', 'قلل', 'مقل', 'مقل', 'فا. من أَقَلَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَقَلَّ). 1. ""رَجُلٌ مُقِلٌّ"" : مَنْ عِنْدَهُ قَلِيلٌ مِنَ الْمَالِ. 2. ""مُقِلٌّ فِي إِنْتَاجِهِ"" : مَنْ لاَ يُنْتِجُ إِلاَّ القَلِيلَ. ""كَاتِبٌ مُقِلٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(583, 'مُقْلِقٌ', 'مقلق', 'اسم فاعل', 'قلق', 'مقلق', 'مقلق', 'فا. من أَقْلَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَقْلَقَ). ""مُقْلِقٌ لِرَاحَتِهِ"" : مُزْعِجٌ. ""وَجَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(584, 'مُقْمِرٌ', 'مقمر', 'اسم فاعل', 'قمر', 'مقمر', 'مقمر', 'فا. من أَقْمَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقْمِرٌ-مُقْمِرٌ، ةٌ [ق م ر] (فا. من أَقْمَرَ). ""لَيْلٌ مُقْمِرٌ "" : لَيْلٌ مُضَاءٌ بِنُورِ القَمَرِ. """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(585, 'مُقْتَنِعٌ', 'مقتنع', 'اسم فاعل', 'قنع', 'مقتنع', 'مقتنع', 'فَا. من اِقْنَتَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. من اِقْنَتَعَ). ""مُقْتَنِعٌ بِآرَائِهِ"" : مُؤْمِنٌ بِهَا رِضىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(586, 'مُقْنِعٌ', 'مقنع', 'اسم فاعل', 'قنع', 'مقنع', 'مقنع', 'فا. من أَقْنَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَقْنَعَ). 1. ""خَطِيبٌ مُقْنِعٌ"" : أَيْ مَنْ يُقْنِعُ بِالْحُجَّةِ والبُرْهَانِ والدَّلِيلِ. 2. ""كَلاَمٌ مُقْنِعٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(587, 'مُكِبٌّ', 'مكب', 'اسم فاعل', 'كبب', 'مكب', 'مكب', 'فا. من أَكَبَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُكِبٌّ-مُكِبٌّ [ك ب ب] (فا. من أَكَبَّ). ""مُكِبٌّ عَلَى العَمَلِ"" : مُجْتَهِدٌ، أَيْ مَنْ يَصُبُّ كُلَّ جُهْدِهِ وَطَاقَتِهِ عَلَى العَمَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(588, 'مُكْتَئِبٌ', 'مكتئب', 'اسم فاعل', 'كأب', 'مكتءب', 'مكتب', 'فا. من اِكْتَأَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِكْتَأَبَ). ""عَادَ مُكْتَئِباً خَجُولاً"" : حَزِيناً، مُغْتَمّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(589, 'مُكْتَتِبٌ', 'مكتتب', 'اسم فاعل', 'كتب', 'مكتتب', 'مكتتب', 'فا. من اِكْتَتَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُكْتَتِبٌ-مُكْتَتِبٌ [ك ت ب] (فا. من اِكْتَتَبَ). ""مُكْتَتِبٌ فِي مَشْرُوعٍ خَيْرِيٍّ"" : مُسَاهِمٌ بِقَدْرٍ مِنَ الْمَالِ مَعَ الْجَمَاعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(590, 'مُكْتَرِثٌ', 'مكترث', 'اسم فاعل', 'كرث', 'مكترث', 'مكترث', 'فا. من اِكْتَرَثَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِكْتَرَثَ). ""غَيْرُ مُكْتَرِثٍ"" : غَيْرُ مُبَالٍ، غَيْرُ مُهْتَمٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(591, 'مُكْتَفِي', 'مكتفي', 'اسم فاعل', 'كفي', 'مكتفي', 'مكتف', 'فا. من اِكْتَفَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِكْتَفَى). ""مُكْتَفٍ بِمَا عِنْدَهُ"" : مُسْتَغْنٍ، قَانِعٌ. ""كَانَ مَزْهُوّاً مُتَكَبِّراً مُنْفَرِداً مُكْتَفِياً بِرَأْيِهِ"". (ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(592, 'مُكْتَمِلٌ', 'مكتمل', 'اسم فاعل', 'كمل', 'مكتمل', 'مكتمل', 'فا. من اِكْتَمَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِكْتَمَلَ). ""رَجُلٌ مُكْتَمِلُ الصِّفَاتِ"" : تَامُّهَا. ""عَمَلٌ مُكْتَمِلٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(593, 'مُكْتَنِزٌ', 'مكتنز', 'اسم فاعل', 'كنز', 'مكتنز', 'مكتنز', 'فا. من اِكْتَنَزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِكْتَنَزَ). ""مَلأَ الْمَقْعَدَ بِجِسْمِهِ الْمُكْت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(594, 'مُكْثِرٌ', 'مكثر', 'اسم فاعل', 'كثر', 'مكثر', 'مكثر', 'فا. من أَكْثَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَكْثَرَ). ""رَجُلٌ مُكْثِرٌ"" : ذُو مَالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(595, 'مُؤَكِّدٌ', 'مؤكد', 'اسم فاعل', 'أكد', 'مءكد', 'مكد', 'فا. من أَكَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَكَّدَ). ""جَاءَ مُؤَكِّداً لِأَقْوَالِ الشُّهُودِ"" : مُثَبِّتاً لَهَا. ""أَقْوَالُهُ مُؤَكِّدَةٌ لِمَا حَدَثَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(596, 'مُكْرِهٌ', 'مكره', 'اسم فاعل', 'كره', 'مكره', 'مكره', 'فا. من أَكْرَهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَكْرَهَ). ""جَاءَ مُكْرِهاً إِيَّاهُ عَلَى ارْتِكَابِ جُرْمٍ"" : أَيْ مُجْبِراً إِيَّاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(597, 'مُكْفَهِرٌّ', 'مكفهر', 'اسم فاعل', 'كفهر', 'مكفهر', 'مكفهر', 'فا. من اِكْفَهَرَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِكْفَهَرَّ). 1. ""مُكْفَهِرُّ الوَجْهِ"" : عَابِسٌ. 2. ""جَوٌّ مُكْفَهِرٌّ"" : جَوٌّ مُتَراكِبُ السَّحَابِ الكَثِيرِ. 3. ""عَامٌ مُكْفَهِرٌّ"" : مُجْدِبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(598, 'مُلْتَئِمٌ', 'ملتئم', 'اسم فاعل', 'لأم', 'ملتءم', 'ملتم', 'فا. من اِلْتَأَمَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلْتَئِمٌ-مُلْتَئِمٌ، ةٌ [ل أ م] (فا. من اِلْتَأَمَ). 1.""جُرْحٌ مُلْتَئِمٌ"" : مُلْتَحِمٌ. ""جِرَاحٌ مُلْتَئِمَةٌ"". 2.""مُلْتَئِمُ الشَّمْلِ"" : مُوَحَّدُ الشَّمْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(599, 'مُلْتَبِسٌ', 'ملتبس', 'اسم فاعل', 'لبس', 'ملتبس', 'ملتبس', 'فا. من اِلْتَبَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِلْتَبَسَ). ""كَلاَمٌ مُلْتَبِسٌ"" : غَامِضٌ، غَيْرُ وَاضِحٍ. ""مَعْنىً مُلْتَبِسٌ"" ""مُلْتَبِسٌ فِي كَلاَمِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(600, 'مُلْتَحِقٌ', 'ملتحق', 'اسم فاعل', 'لحق', 'ملتحق', 'ملتحق', 'فا. من اِلْتَحَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِلْتَحَقَ). 1.""مُلْتَحِقٌ بِالرَّكْبِ"" : مُدْرِكُهُ. 2.""مُلْتَحِقٌ بِالْجَمَاعَةِ"": مُنْضَمٌّ إِلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(601, 'مُلْتَحِمٌ', 'ملتحم', 'اسم فاعل', 'لحم', 'ملتحم', 'ملتحم', 'فا. من اِلْتَحَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِلْتَحَمَ). 1.""جُرْحٌ مُلْتَحِمٌ"" : مُلْتَئِمٌ. 2.""حَرْبٌ مُلْتَحِمَةٌ"" : حَرْبٌ اِشْتَدَّ أُوَارُهَا. 3.""مُلْتَحِمٌ مَعَ الْجَمَاعَةِ"" : مُتَضَامِنٌ، مُتَّحِدٌ مَعَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(602, 'مُلْتَحِي', 'ملتحي', 'اسم فاعل', 'لحي', 'ملتحي', 'ملتح', 'فا. من اِلْتَحَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُلْتَحٍ-مُلْتَحٍ، الْمُلْتَحِي [ل ح ي] (فا. من اِلْتَحَى). ""رَجُلٌ مُلْتَحٍ"" : ذُو لِحْيَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(603, 'مُلْتَزِقٌ', 'ملتزق', 'اسم فاعل', 'لزق', 'ملتزق', 'ملتزق', 'فا. من اِلْتَزَقَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلْتَزِقٌ-مُلْتَزِقٌ، ةٌ [ل ز ق] (فا. من اِلْتَزَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(604, 'مُلْتَزِمٌ', 'ملتزم', 'اسم فاعل', 'لزم', 'ملتزم', 'ملتزم', 'فا. من اِلْتَزَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِلْتَزَمَ). 1.""مُلْتَزِمٌ بِإِنْجَازِ الْمَشْرُوعِ"" : مُتَعَهِّدٌ بِتَنْفِيذِ الْمَشْرُوعِ حَسَبَ عُقْدَةٍ أَو اِلْتِزَامٍ. 2.""كَاتِبٌ مُلْتَزِم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(605, 'مُلْتَصِقٌ', 'ملتصق', 'اسم فاعل', 'لصق', 'ملتصق', 'ملتصق', 'فا. من اِلْتَصَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِلْتَصَقَ). 1.""وَرَقٌ مُلْتَصِقٌ بِالْحَائِطِ"" : مُلْتَزِقٌ. 2.""مُلْتَصِقٌ بِعَمَلِهِ"" : مُرْتَبِطٌ، مُلْتَحِمٌ، مُتَعَلِّقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(606, 'مُلْحِدٌ', 'ملحد', 'اسم فاعل', 'لحد', 'ملحد', 'ملحد', 'فا. من أَلْحَدَ.', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَلاَحِدَةٌ"', '', '', '', '', '', '', '', '', '"ج: مَلاَحِدَةٌ، ون، ات. (فا. من أَلْحَدَ). ""رَجُلٌ مُلْحِدٌ"" : مَنْ يَجْحَدُ وُجُودَ اللَّهِ، كَافِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(607, 'مَلاَحِدَةٌ', 'ملاحدة', 'اسم فاعل', '', 'ملاحدة', 'ملحدة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(608, 'مُلْحِمٌ', 'ملحم', 'اسم فاعل', 'لحم', 'ملحم', 'ملحم', 'فا. من أَلْحَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَلْحَمَ). ""رَجُلٌ مُلْحِمٌ"" : مَنْ كَثُرَ عِنْدَهُ اللَّحْمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(609, 'مُلْزِمٌ', 'ملزم', 'اسم فاعل', 'لزم', 'ملزم', 'ملزم', 'فا. من أَلْزَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَلْزَمَ). ""قَانُونٌ مُلْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(610, 'مُلْسِنٌ', 'ملسن', 'اسم فاعل', 'لسن', 'ملسن', 'ملسن', 'فا. من أَلْسَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَلْسَنَ). ""خَطِيبٌ مُلْسِنٌ"" : فَصِيحٌ، أَوْ مَنْ يَتَكَلَّمُ كَثِيراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(611, 'مُمْتَلِئٌ', 'ممتلئ', 'اسم فاعل', 'ملأ', 'ممتلء', 'ممتل', 'فا. من اِمْتَلأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِمْتَلأَ). 1.""مُمْتَلِئُ الجِسْمِ"" : سَمِينٌ، ثَخِينٌ. ""مُمْتَلِئَ الخَدَّيْنِ"". 2.""قَاعَةٌ مُمْتَلِئَةٌ بِجُمْهُورٍ غَفِيرٍ"" : مَلْأَى، مَلْآنَةٌ. 3.""عَادُوا مِنْ رِحْلَتِهِمْ مُمْتَلِئِينَ إِعْجَاباً بِمَا رَأَوْا"" : مُفْعَمِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(612, 'مُؤَلِّفٌ', 'مؤلف', 'اسم فاعل', 'ألف', 'مءلف', 'ملف', 'فا. من أَلَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَلَّفَ). ""مُؤَلِّفُ الكِتَابِ"" : الَّذِي كَتَبَهُ، كَاتِبُهُ. ""حُقُوقُ الْمُؤَلِّفِ مَحْفُوظَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(613, 'مُلْقِي', 'ملقي', 'اسم فاعل', 'لقي', 'ملقي', 'ملق', 'فا. من أَلْقَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَلْقَى). 1.""مُلْقي السِّهَامِ"" : مَنْ يُلْقِيهَا. 2.""مُلْقي الْكَلاَمِ عَلَى عَوَاهِنِهِ"" : مَنْ يَتَلَفَّظُ بِالكَلاَمِ هَبَاءً، كَيْفَمَا اتَّفَقَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(614, 'مُؤْلِمٌ', 'مؤلم', 'اسم فاعل', 'ألم', 'مءلم', 'ملم', 'فا. من آلَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُؤْلِمٌ-مُؤْلِمٌ، ةٌ [أ ل م] (فا. من آلَمَ). ""حَادِثٌ مُؤْلِمٌ"" : مُؤْسِفٌ، يَبْعَثُ عَلَى الأَلَمِ وَالأَسَى، أَلِيمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(615, 'مُلِمٌّ', 'ملم', 'اسم فاعل', 'لمم', 'ملم', 'ملم', 'فا. من أَلَمَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَلَمَّ). ""مُلِمٌّ بِمَعَارِفَ كَثِيرَةٍ"" : عَالِمٌ مُطَّلِعٌ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(616, 'مُمِيتٌ', 'مميت', 'اسم فاعل', 'موت', 'مميت', 'ممت', 'فا. من أَمَاتَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُمِيتٌ-مُمِيتٌ، ةٌ [م و ت] (فا. من أَمَاتَ). 1.""خَطَأٌ مُمِيتٌ"": قَاتِلٌ، مُهْلِكٌ. 2.""خَطِيئَةٌ مُمِيتَةٌ"" : خَطِيئَةٌ مِنَ الكَبَائِرِ تَسْلُبُ النَّفْسَ حَيَاةَ النِّعْمَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(617, 'مُمْتَازٌ', 'ممتاز', 'اسم فاعل', 'ميز', 'ممتاز', 'ممتز', 'فا. مِن اِمتَازَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِن اِمتَازَ). 1.""عَمَلٌ مُمْتَازٌ"" : جَيِّدٌ جِدّاً، أَيْ يَتَمَتَّعُ بِامْتِيَازٍ. ""صِنْفٌ مُمْتَازٌ"". 2.""مُحَاضِرٌ مُمْتَازٌ"" : مُتَمَكِنٌ وفَاضِلٌ عَلَى غَيْرِهِ. 3.""صَدَرَ عَدَدٌ مُمْتَازٌ مِنَ الْمَجَلَّةِ"" : عَدَدٌ مُتَمَيِّزٌ عَنِ الأَعْدَادِ السَّابِقَةِ بِفُصُولٍ ومَوَادَّ إِضَافِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(618, 'مُمْتَحِنٌ', 'ممتحن', 'اسم فاعل', 'محن', 'ممتحن', 'ممتحن', 'فا. من اِمْتَحَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِمْتَحَنَ). ""دَخَلَ الْمُمْتَحِنُ قَاعَةَ الامْتِحَانِ"" : مَنْ يَمْتَحِنُ الطُّلاَّبَ، ويُجْرِي لَهُمْ الامْتِحَانَ. ""لَجْنَةُ الْمُمْتَحِنِينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(619, 'مُمْتِعٌ', 'ممتع', 'اسم فاعل', 'متع', 'ممتع', 'ممتع', 'فا. من أَمْتَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُمْتِعٌ-مُمْتِعٌ، ةٌ [م ت ع] (فا. من أَمْتَعَ). 1. ""جَوٌّ مُمْتِعٌ"" : جَوٌّ رَائِقٌ يَجْلُبُ الْمُتْعَةَ. ""كِتَابٌ مُمْتِعٌ"" ""نُصُوصٌ شِعْرِيَّةٌ مُمْتِعَةٌ"". 2.""الْمُمْتِعُ فِي الرِّحْلَةِ هُوَ مَعْرِفَةُ أَصْدِقَاءَ جُدُدٍ"" : الفَائِدَةُ الَّتِي يُنْتَفَعُ ويُسَرُّ بِهَا. ""قِرَاءةُ هَذَا الكِتَابِ مُمْتِعَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(620, 'مُمْتَقِعٌ', 'ممتقع', 'اسم فاعل', 'مقع', 'ممتقع', 'ممتقع', 'فا. من اِمْتَقَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِمْتَقَعَ). ""مُمْتقِعُ الوَجْهِ"" : مُتَغَيِّرٌ لَوْنُهُ مِنْ حُزْنٍ أو فَزَعٍ. ""كَانَ مُمْتَقِعَ اللَّوْنِ"" ""بَدَا وَجْهُهَا مُمْتَقِعاً شَاحِباً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(621, 'مُؤْمِنٌ', 'مؤمن', 'اسم فاعل', 'أمن', 'مءمن', 'ممن', 'فا. من آمَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من آمَنَ). ""رَجَلٌ مُؤْمِنٌ"" : مُصَدِّقٌ، يُؤْمِنُ بِالله وَاليَوْمِ الآخِرِ.النساء آية 162 وَالْمُؤْمِنُونَ يُؤْمِنُونَ بِمَا أُنْزِلَ إِلَيْكَ وَمَا أُنْزِلَ مِنْ قَبْلِكَ (قرآن) l ""إِنَّ قَلْبَ الْمُؤْمِنِ دَلِيلُهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(622, 'مُمْتَنِعٌ', 'ممتنع', 'اسم فاعل', 'منع', 'ممتنع', 'ممتنع', 'فا. من اِمْتَنَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِمْتَنَعَ). 1.""مُمْتَنِعٌ عَنِ الأَدَاءِ"" : أي رافِضٌ، مَنْ يَمْتَنِعُ عَنْ أَدَاءِ دَيْنٍ ونَحْوِهِ. 2.""جَبَلٌ مُمْتَنِعٌ عَنْ مُتَسَلِّقِي الجِبَالِ"" : مُسْتَعْصٍ، مُتَعَذِّرٌ. 3.""مُمْتَنِعٌ بِأَهْلِهِ ونَسَبِهِ"" : مُحْتَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(623, 'مُمْتَهِنٌ', 'ممتهن', 'اسم فاعل', 'مهن', 'ممتهن', 'ممتهن', 'فا. من اِمْتَهَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِمْتَهَنَ). 1.""مُمْتَهِنٌ لِكَرَامَتِهِ"" : مُحْتَقِرٌ، مُبْتَذِلٌ لَهَا. 2.""مُمْتَهِنٌ مِهْنَةَ الْمُحَامَاةِ"" : مُحْتَرِفُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(624, 'آمِرٌ', 'آمر', 'اسم فاعل', 'أم.ر', 'ءامر', 'آمر', 'فَا. من أمر', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"آمِرٌ-آمِرٌ [أ م. ر] (فَا. من أمر) 1.""كَانَ الآمِرَ فِي العَمَلِ"": مَن يَطْلُبُ مِنْ شَخْصٍ أوْ عَامِلٍ فِعْلَ عَمَلٍ مَّا وَإِنْجَازَهُ. 2.""هُو الآمِرُ الناهِي فِي البِلاَدِ"" : الحَاكِمُ الْمُطْلَقُ، السَّيِّدُ الْمُطْلَقُ، أي الَّذِي بِيَدِهِ الحَلُّ وَالعَقْدُ. ""أنْتَ آمِرٌ وَأنَا مُؤتَمِرٌ"".(التوحيدى)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(625, 'أوامر', 'أوامر', 'اسم فاعل', '', 'ءوامر', 'مر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(626, 'مُمْسِكٌ', 'ممسك', 'اسم فاعل', 'مسك', 'ممسك', 'ممسك', 'فا. من أَمْسَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَمْسَكَ). 1.""مُمْسِكٌ عَنِ الأَكْلِ"" : مُنْقَطِعٌ عَن ... 2.""رَجُلٌ مُمْسِكٌ"" : بَخِيلٌ. 3.""مُمْسِكٌ بِزِمَامِ الأُمُورِ"" : أَيْ مُتَمَكِّنٌ مِنْ إِدَارَتِهَا والإِشْرَافِ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(627, 'مُمْطِرٌ', 'ممطر', 'اسم فاعل', 'مطر', 'ممطر', 'ممطر', 'فا. من أَمْطَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُمْطِرٌ-مُمْطِرٌ، ةٌ [م ط ر] (فا. من أَمْطَرَ). ""يَوْمٌ مُمْطِرٌ"" : يَوْمٌ سَقَطَ فِيهِ مَطَرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(628, 'مُمْعِنٌ', 'ممعن', 'اسم فاعل', 'معن', 'ممعن', 'ممعن', 'فا. من أَمْعَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَمْعَنَ). ""مُمْعِنٌ فِي غَيِّهٍ"" : مُبَالِغٌ إِلَى حَدِّ الإِغْرَاقِ. ""ظَلَّ مُطْرِقاً مُمْعِناً فِي الإِطْرَاقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(629, 'مُمْكِنٌ', 'ممكن', 'اسم فاعل', 'مكن', 'ممكن', 'ممكن', 'فا. من أَمْكَنَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمْكِنٌ-مُمْكِنٌ [م ك ن] (فا. من أَمْكَنَ). 1.""مُمْكِنٌ أَنْ تَخْرُجَ الآنَ"" : مُتَيَسِّرٌ ... ""مِنَ الْمُمْكِنِ"" ""فِي أَقْرَبِ وَقْتٍ مُمْكِنٍ"". 2.""مِنَ الْمُمْكِنِ أَنْ أَحْضُرَ مَعَكُمْ"" : مِنَ الْمُحْتَمَلِ. 3.""الْمُمْكِنُ فِي حَقِّ اللَّهِ"" : الْجَائِزُ. 4.""غَيْرُ الْمُمْكِنِ"" : الْمُسْتَحِيلُ الَّذِي لاَ يَجُوزُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(630, 'مُمِلٌّ', 'ممل', 'اسم فاعل', 'ملل', 'ممل', 'ممل', 'فا. من أَمَلَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَمَلَّ). ""عَمَلٌ مُمِلٌّ"" : مُقْرِفٌ، أَيْ يَبْعَثُ عَلَى القَرَفِ والسَّأَمِ والْمَلَلِ. ""يُرَدِّدُ أَحَادِيثَهُ فِي رَتَابَةٍ مُمِلَّةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(631, 'مُنْبَطِحٌ', 'منبطح', 'اسم فاعل', 'بطح', 'منبطح', 'منبطح', 'فا. من اِنْبَطَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْبَطَحَ). 1.""وَجَدَهُ مُنْبَطِحاً"" : مُسْتَلْقِياً عَلَى بَطْنِهِ. 2.""جَعَلَهُ مُنْبَطِحاً"" : أَيْ ذَلِيلاً مُهَاناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(632, 'آمِنٌ', 'آمن', 'اسم فاعل', 'أم.ن', 'ءامن', 'آمن', 'فَا. منْ أمِنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. منْ أمِنَ). 1.""آمِنٌ بِتَجَارِبهِ العِلْمِيَّةِ"" : وَاثِقٌ بِهَا. 2.""آمِنٌ عَلَى حَالِهِ"" : مُطْمَئِنٌّ، مُسْتَرِيحٌ. ""ظَلَّ آمِناً فِي قَرْيَتِهِ"" ""هِيَ آمِنَةٌ فِي بَيْتِهَا"". 3.""آمِنَة"" : اِسْمُ عَلَمٍ لِلإْنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(633, 'أوامن', 'أوامن', 'اسم فاعل', '', 'ءوامن', 'من', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(634, 'مُنِيبٌ', 'منيب', 'اسم فاعل', 'نوب', 'منيب', 'منب', 'فا. من أَنَابَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَنَابَ). 1. ""مُرْتَدٌّ مُنِيبٌ"" : تَائِبٌ. 2.""مَطَرٌ مُنِيبٌ"" : غَزِيرٌ. 3.""رَبِيعٌ مُنِيبٌ"" : مُخْضَوْضِرٌ. 4.""مُنِيبٌ"" : اِسْمُ عَلَمٍ لِلْمُذَكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(635, 'مُنِيرٌ', 'منير', 'اسم فاعل', 'نور', 'منير', 'منر', 'فا. من أَنَارَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَنَارَ). 1.""مُنِيرُ الطَّلْعَةِ"" : حَسَنُ الوَجْهِ واللَّوْنِ، مُشْرِقُهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(636, 'مُنِيفٌ', 'منيف', 'اسم فاعل', 'نوف', 'منيف', 'منف', 'فا. من أَنَافَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُنِيفٌ-مُنِيفٌ، ةٌ [ن و ف] (فا. من أَنَافَ). 1.""جَبَلٌ مُنِيفٌ"": مُرْتَفِعٌ، شَامِخٌ، مُشْرِفٌ، مُطِلٌّ. 2.""اِمْرَأَةٌ مُنِيفَةٌ"" : كَامِلَةُ الأَوْصَافِ، تَامَّةُ الطُّولِ وَالْحُسْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(637, 'مُنْبَتٌّ', 'منبت', 'اسم فاعل', 'بتت', 'منبت', 'منبت', 'فا. من اِنْبَتَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُنْبَتٌّ-مُنْبَتٌّ [ب ت ت] (فا. من اِنْبَتَّ). 1.""أَمْرٌ مُنْبَتٌّ"" : مَقْطُوعٌ لاَ أَصْلَ لَهُ. 2. إِنَّ الْمُنْبَتَّ لاَ أَرْضاً قَطَعَ وَلاَ ظَهْراً أَبْقَى . (حديث) : يُقَالُ لِلْمُفْرِطِ فِي طَلَبِ الشَّيْءِ وَالْمُبَالِغِ فِيهِ حَتَّى رُبَّمَا يُفَوِّتَهُ عَلَى نَفْسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(638, 'مُنْبَثٌّ', 'منبث', 'اسم فاعل', 'بثث', 'منبث', 'منبث', 'فا. من اِنْبَثَّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْبَثٌّ-مُنْبَثٌّ، ةٌ [ب ث ث] (فا. من اِنْبَثَّ). ""صَارَ الخَبَرُ مُنْبَثّاً فِي كُلِّ مَكَانٍ"" : مُنْتَشِراً. ""وقَدْ وَجَدْنَا الْحَرَسَ مُنْبَثّاً فِي جَوَانِبِ الطَّرِيقِ"". (المختار السوسي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(639, 'منبثقٌ', 'منبثق', 'اسم فاعل', 'بثق', 'منبثق', 'منبثق', 'فا. من انبثق', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(640, 'مُنْبَسِطٌ', 'منبسط', 'اسم فاعل', 'بسط', 'منبسط', 'منبسط', 'فا. من اِنْبَسَطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْبَسَطَ). 1. ""نَبَاتٌ مُنْبَسِطٌ"" : مُنْتَشِرٌ. 2. ""مُنْبَسِطٌ عَلَى بَطْنِهِ"": مُمْتَدٌّ. 3. ""مُنْبَسِطٌ مِنْ عَمَلِهِ"" : مُنْشَرِحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(641, 'مُنْتَظِمٌ', 'منتظم', 'اسم فاعل', 'نظم', 'منتظم', 'منتظم', 'فا. من اِنْتَظَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْتَظَمَ). 1.""سَيْرُهُ مُنْتَظِمٌ"" : خُطُوَاتُ سَيْرِهِ مُتَتَابِعَةٌ بِانْتِظَامٍ. 2.""رَجُلٌ مُنْتَظِمٌ"" : مَنْ تَكُونُ أَعْمَالُهُ مَضْبُوطَةً وتَسِيرُ سَيْراً مُتَنَاسِقَاً. 3.""نَبْضُ قَلْبِهِ مُنْتَظِمٌ"" : دَقَّاتُهُ مُتَتَالِيَةٌ عَلَى دَرَجَةٍ وَاحِدَةٍ. 4.""حَرَكَاتُهُ مُنْتَظِمَةٌ"" : مُتَتَابِعَةٌ، مُتَتَالِيَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(642, 'مُنْتَبِهٌ', 'منتبه', 'اسم فاعل', 'نبه', 'منتبه', 'منتبه', 'فا. من اِنْتَبَهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْتَبَهَ). ""مُنْتَبِهٌ إِلَى مَا حَوَالَيْهِ"" : يَقِظٌ، فَطِنٌ، حَاضِرُ الذِّهْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(643, 'مُنْتِجٌ', 'منتج', 'اسم فاعل', 'نتج', 'منتج', 'منتج', 'فا. من أَنْتَجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَنْتَجَ). 1.""عَامِلٌ مُنْتِجٌ"" : الْمُسَاهِمُ فِي إِنْتَاجِ عَمَلٍ مَّا. 2.""عَمَلٌ مُنْتِجٌ"" : الْمُعْطِي إِنْتَاجاً. ""أَعْمَالٌ مُنْتِجَةٌ"" ""الدُّوَلُ العَرَبِيَّةُ الْمُنْتِجَةُ لِلنَّفْطِ"". 3.""مُنْتِجٌ سِينِمَائِيٌّ"" : الْمُسَاهِمُ فِي إِنْتَاجِ الأَفْلاَمِ السِّينِمَائِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(644, 'مُنْتَحِبٌ', 'منتحب', 'اسم فاعل', 'نحب', 'منتحب', 'منتحب', 'فا. من اِنْتَحَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِنْتَحَبَ). ""رَآهُ مُنْتَحِباً وَلَمْ يَعْرِفْ سِرَّ انْتِحَابِهِ"" : بَاكِياً بُكَاءً فيهِ شَهِيقٌ وَزَفِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(645, 'مُنْتَحِرٌ', 'منتحر', 'اسم فاعل', 'نحر', 'منتحر', 'منتحر', 'فا. من اِنْتَحَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْتَحَرَ). ""وَجَدَهُ مُنْتَحِراً فِي غُرْفَتِهِ"" : مَنْ قَتَلَ نَفْسَهُ عَمْداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(646, 'مُنْتَحِلٌ', 'منتحل', 'اسم فاعل', 'نحل', 'منتحل', 'منتحل', 'فا. من اِنْتَحَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُنْتَحِلٌ-مُنْتَحِلٌ، ةٌ [ن ح ل] (فا. من اِنْتَحَلَ). 1.""شَاعِرٌ مُنْتَحِلٌ"" : مَنْ يُزَوِّرُ شِعْرَ غَيْرِهِ، مُقَلِّدٌ. 2.""مُنْتَحِلُ شَخْصِيَّةٍ"" : مُتَشَبِّهٌ بِهَا عَلَى أَنَّهَا لَهُ، غَاصِبٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(647, 'مُنْتَخِبٌ', 'منتخب', 'اسم فاعل', 'نخب', 'منتخب', 'منتخب', 'فا. من اِنْتَخَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِنْتَخَبَ). ""مُنْتَخِبٌ فِي الانْتِخَابَاتِ"" : مَنْ يُشَارِكُ فِي عَمَلِيَّةِ الانْتِخَابَاتِ، الاقْتِرَاعُ. ""كَانَتْ نِسْبَةُ الْمُنَتَخِبِينِ مُرْتَفِعَةً فِي الانْتِخَابَاتِ البَرْلَمَانِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(648, 'مُنْتَسِبٌ', 'منتسب', 'اسم فاعل', 'نسب', 'منتسب', 'منتسب', 'فا. من اِنْتَسَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْتَسَبَ). 1.""مُنْتَسِبٌ لِلْجَمْعِيَّةِ"" : الْمُنْتَمِي إِلَيْهَا. ""طَالِبٌ مُنْتَسِبٌ إِلَى مَعْهَدِ الفُنُونِ الجَمِيلَةِ"". 2.""حَدَّدَتِ الكُلِّيَّةُ شُرُوطَ الْمُنْتَسِبِينَ"" : الطُّلاَّبُ الَّذِينَ يَدْرُسُونَ مِنْ خَارِجِ الكُلِّيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(649, 'مُنْتَصِبٌ', 'منتصب', 'اسم فاعل', 'نصب', 'منتصب', 'منتصب', 'فا. من اِنْتَصَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْتَصَبَ). 1.""مُنْتَصِبٌ لِلْهُجُومِ"" : مُهَيَّأٌ. 2.""تِمْثَالٌ مُنْتَصِبٌ"" : قَائِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(650, 'مُنْتَصِرٌ', 'منتصر', 'اسم فاعل', 'نصر', 'منتصر', 'منتصر', 'فا. من اِنْتَصَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْتَصَرَ). ""خَرَجَ مِنَ الْمَعْرَكَةِ مُنْتَصِراً"" : مَن اِنْتَصَرَ وفَازَ عَلَى عَدُوِّهِ. ""عَادُوا مُنْتَصِرِينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(651, 'مُنْتَمِي', 'منتمي', 'اسم فاعل', 'نمي', 'منتمي', 'منتم', 'فا. من اِنْتَمَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْتَمَى). ""مُنْتَمٍ إِلَى الحِزْبِ الوَطَنِيِّ"" : مُنْتَسِبٌ إِلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(652, 'مُنْتَعِشٌ', 'منتعش', 'اسم فاعل', 'نعش', 'منتعش', 'منتعش', 'فا. من اِنْتَعَشَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْتَعَشَ). 1.""وَجَدَهُ مُنْتَعِشاً فِي حَيَاتِهِ الجَدِيدَةِ"" : نَشِيطٌ، مُفْعَمٌ بِالْحَيَوِيَّةِ والنَّشَاطِ. 2.""طَيْرٌ مُنْتَعِشٌ"" : يَعِيشُ فِي حَرَكَةٍ بَعْدَ فُتُورٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(653, 'مُنْتَفِخٌ', 'منتفخ', 'اسم فاعل', 'نفخ', 'منتفخ', 'منتفخ', 'فا. من اِنْتَفَخَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْتَفَخَ). 1.""أُصْبُعٌ مُنْتَفِخٌ"" : بِهِ وَرَمٌ. 2.""بَطْنٌ مُنْتَفِخٌ"" : مُمْتَلِئٌ. 3.""عَيْنٌ مُنْتَفِخَةٌ"" : عَيْنٌ مُتَوَرِّمَةٌ. 4.""رَجُلٌ مُنْتَفِخٌ"" : مُتَكَبِّرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(654, 'مُنْتَفِشٌ', 'منتفش', 'اسم فاعل', 'نفش', 'منتفش', 'منتفش', 'فا. من اِنْتَفَشَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فا. من اِنْتَفَشَ). 1.""شَعْرٌ مُنْتَفِشٌ"" : غَيْرُ مَمْشُوطٍ، مُتَفَرِّقٌ. 2.""قِطٌّ مُنْتَفِشٌ"" : شَعْرُهُ مُنْتَصِبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(655, 'مُنْتَفِعٌ', 'منتفع', 'اسم فاعل', 'نفع', 'منتفع', 'منتفع', 'فا. من اِنْتَفَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِنْتَفَعَ). ""مُنْتَفِعٌ بِأَرْبَاحِ تِجَارَتِهِ"" : حَاصِلٌ عَلَى مَنْفَعَةٍ وفَائِدَةٍ مِنْهَا. ""مُنْتَفِعٌ بِحُقُوقِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(656, 'مُنْتَقِدٌ', 'منتقد', 'اسم فاعل', 'نقد', 'منتقد', 'منتقد', 'فا. من اِنْتَقَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِنْتَقَدَ). ""مُنْتَقِدٌ لِكُلِّ عَمَلٍ"" : نَاقِدٌ لَهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(657, 'مُنْتَقِلٌ', 'منتقل', 'اسم فاعل', 'نقل', 'منتقل', 'منتقل', 'فا. من اِنْتَقَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْتَقَلَ). ""مُنْتَقِلٌ مِنْ مَكَانٍ إِلَى آخَرَ"" : مُتَحَوِّلٌ مِنْ مَكَانٍ إِلَى آخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(658, 'مُنْتَقِمٌ', 'منتقم', 'اسم فاعل', 'نقم', 'منتقم', 'منتقم', 'فا. من اِنْتَقَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْتَقَمَ). ""مُنْتَقِمٌ مِنْ كُلِّ أَعْدَائِهِ"" : مُعَاقِبٌ لَهُ بِالانْتِقَامِ مِنْهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(659, 'مُنْتَقِي', 'منتقي', 'اسم فاعل', 'نقي', 'منتقي', 'منتق', 'فا. من اِنْتَقَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ج:"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِنْتَقَى). ""شَاعِرٌ مُنْتَقٍ أَلْفَاظَهُ بِعِنايَةٍ"" : أَيْ شَاعِرٌ يَعْمَلُ عَلَى انْتِقَاءِ أَلْفَاظِهِ واخْتِيَارِها..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(660, 'مُنْتَكِسٌ', 'منتكس', 'اسم فاعل', 'نكس', 'منتكس', 'منتكس', 'فا. من اِنْتَكَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْتَكَسَ). ""مَرِيضٌ مُنْتَكِسٌ"" : مَرِيضٌ عَاوَدَهُ الْمَرَضُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(661, 'مُنْحَرِفٌ', 'منحرف', 'اسم فاعل', 'حرف', 'منحرف', 'منحرف', 'فا. من اِنْحَرَفَ.', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"ج: ـون، ـات. (فا. من اِنْحَرَفَ). 1.""وَلَدٌ مُنْحَرِفُ الأَخْلاَقِ"" : خَارِجٌ عَنِ الطَّرِيقِ الْمُسْتَقِيمِ. ""سُلُوكٌ مُنْحَرِفٌ"". 2.""الْمُنْحَرِفُ فِي الرِّيَاضِيَّاتِ"" : شَكْلٌ رُبَاعِيٌّ لاَ يُوجَدُ فِيهِ ضِلْعَانِ مُتَوَازِيَانِ. 3.""شِبْهُ الْمُنْحَرِفِ"" : شَكْلٌ رُبَاعِيٌّ بِهِ ضِلْعَانِ مُتَوَازِيَانِ. 4. ""طَرِيقٌ غَيْرُ مُنْحَرِفَةٍ"" : مُسْتَقِيمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(662, 'مُنْتِنٌ', 'منتن', 'اسم فاعل', 'نتن', 'منتن', 'منتن', 'فا. من أَنْتَنَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْتِنٌ-مُنْتِنٌ، ةٌ [ن ت ن] (فا. من أَنْتَنَ). ""لَحْمٌ مُنْتِنٌ"" : رَائِحَتُهُ كَرِيهَةٌ. ""مَكَانٌ مُنْتِنٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(663, 'مُنْتَهِكٌ', 'منتهك', 'اسم فاعل', 'نهك', 'منتهك', 'منتهك', 'فا. من اِنْتَهَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من اِنْتَهَكَ). 1.""مُنْتَهِكٌ لِلْحُرْمَاتِ"" : مُتَنَاوِلُهَا بِمَا لاَ يَحِلُّ. 2.""مُنْتَهِكُ الأَمَاكِنِ الْمُقَدَّسَةِ"" : مُدَنِّسُهَا. 3."""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(664, 'مُنْتَهِي', 'منتهي', 'اسم فاعل', 'نهي', 'منتهي', 'منته', 'فا. من اِنْتَهَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْتَهَى). 1.""مُنْتَهٍ إِلَى قَرَارٍ حَاسِمٍ"". 2.""عَمَلٌ مُنْتَهٍ"" : اُنْتُهِيَ مِنْهُ، نَافِذٌ. ""مُنْتَهُونَ بِالتَّأْكِيدِ إِلَى مَصِيرٍ مَجْهُولٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(665, 'مُنْجِبٌ', 'منجب', 'اسم فاعل', 'نجب', 'منجب', 'منجب', 'فا. مِن أَنْجَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَنَاجِبُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِن أَنْجَبَ). ""شَيْخٌ مُنْجِبٌ"" : أَيْ وَلَدَ النُّجَبَاءَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(666, 'مَنَاجِبُ', 'مناجب', 'اسم فاعل', '', 'مناجب', 'منجب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(667, 'مُنْجِدٌ', 'منجد', 'اسم فاعل', 'نجد', 'منجد', 'منجد', 'فا. من أَنْجَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَنْجَدَ). ""اِسْتَعَانَ بِالْمُنْجِدِ"" : بِالْمُعِينِ الَّذِي يُلْتَجَأُ إِلَيْهِ لِلْمَعُونَةِ والْمُسَاعَدَةِ. ومِنْ هَذَا الْمَعْنَى اِسْتَعَارَ الأَبُ لوِيسُ مَعْلُوفٌ اسْمَ مُعْجَمِهِ اللُّغَوِيِّ : ""الْمُنْجِدُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(668, 'مُنْجَذِبٌ', 'منجذب', 'اسم فاعل', 'جذب', 'منجذب', 'منجذب', 'فا. من اِنْجَذَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْجَذَبَ). ""مُنْجَذِبٌ إِلَيْهِ"" : مُنْدَفِعٌ إِلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(669, 'مُنْجَلِي', 'منجلي', 'اسم فاعل', 'جلي', 'منجلي', 'منجل', 'فا. من اِنْجَلَى', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْجَلٍ-مُنْجَلٍ، الْمُنْجَلِي، ةٌ [ج ل ي] (فا. من اِنْجَلَى). ""أَمْرٌ مُنْجَلٍ"" : ظَاهِرٌ، بَيِّنٌ. ""حَقِيقَةٌ مُنْجَلِيَةٌ"" يَا دِجْلَةَ الْخَيْرِ: لَيْتَ الشَّكَّ مُنْجَلِياً*حَقِيقَةٌ دُونَ تَمْلِيحٍ وتَخْمِيــنِ (م. م. الجواهري)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(670, 'مُنْحَدِرٌ', 'منحدر', 'اسم فاعل', 'حدر', 'منحدر', 'منحدر', 'فا. من اِنْحَدَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُنْحَدِرٌ-مُنْحَدِرٌ، ةٌ [ح د ر] (فا. من اِنْحَدَرَ). 1.""طَرِيقٌ مُنْحَدِرٌ"" : مُنْخَفِضٌ إِلَى الأَسْفَلِ. 2.""رَأَى دَمْعَهُ مُنْحَدِراً عَلَى خَدَّيْهِ"" : مُتَسَاقِطٌ، سَائِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(671, 'مُؤْنِسٌ', 'مؤنس', 'اسم فاعل', 'أنس', 'مءنس', 'منس', 'فا. من آنَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من آنَسَ). ""مُؤْنِسٌ لَهُ فِي حَيَاتِهِ"" : مُلاَطِفٌ لَهُ وَمُزِيلٌ لِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(672, 'مُنْحَصِرٌ', 'منحصر', 'اسم فاعل', 'حصر', 'منحصر', 'منحصر', 'فا. من اِنْحَصَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فا. من اِنْحَصَرَ). ""عَمَلُهُ مُنْحَصِرٌ فِي الْمُرَاقَبَةِ"" : مَحْصُورٌ، مَحْدُودٌ. ""مُنْحَصِرٌ بَيْنَ الجُدْرَانِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(673, 'مُنْحَلٌّ', 'منحل', 'اسم فاعل', 'حلل', 'منحل', 'منحل', 'فا. من اِنْحَلَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْحَلَّ). 1.""عُقْدَةٌ مُنْحَلَّةٌ"" : مَحْلُولَةٌ. 2.""مُنْحَلُّ الأَخْلاَقِ"" : مُنْحَرِفُ الأَخْلاَقِ. ""أَخْلاَقُهُ مُنْحَلَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(674, 'مُنْحَنِي', 'منحني', 'اسم فاعل', 'حنو', 'منحني', 'منحن', 'فا. من اِنْحَنَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْحَنَى). 1.""ظَلَّ مُنْحَنِياً فِي رُكْنِهِ"" : مُطْرِقاً. 2.""خَطٌّ مُنْحَنٍ"" : خَطٌّ مُتَقَعِّرٌ، مُقَوّسٌ لَيْسَ بِمُسْتَقِيمٍ ولاَ مُنْكَسِرٍ. 3.""مُنْحَنٍ بَسِيطٌ"" : هُوَ أَبْسَطُ مُنْحَنٍ يُمْكِنُ رَسْمُهُ لِيَصِلَ بَيْنَ جُمْلَةِ نُقَطٍ مُتَتَالِيَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(675, 'مُنْخَفِضٌ', 'منخفض', 'اسم فاعل', 'خفض', 'منخفض', 'منخفض', 'فا. من اِنْخَفَضَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فا. من اِنْخَفَضَ). 1.""أَجَابَ بِصَوْتٍ مُنْخَفِضٍ"" : أَيْ بِصَوْتٍ خَافِتٍ. 2.""هُوَ مُنْخَفِضُ الصَّوْتِ"" : خَافِتُ الصَّوْتِ. 3.""اِشْتَرَى سِلْعَةً بِسِعْرٍ مُنْخَفِضٍ"" : أَيْ بِسِعْرٍ بَخْسٍ، غَيْرُ مُرْتَفِعٍ. ""أَسْعَارٌ مُنْخَفِضَةٌ"". 4.""أَرْضٌ مُنَخَفِضَةٌ"" : الْجُزْءُ الأَسْفَلُ مِنْهَا، وَاطِئَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(676, 'مُنْدَفِع', 'مندفع', 'اسم فاعل', 'دفع', 'مندفع', 'مندفع', 'فا. من اِنْدَفَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْدَفَعَ). 1.""شَابٌّ مُنْدَفِعٌ"" : الْمُتَحَمِّسُ إِلَى القِيَامِ بِعَمَلٍ بِحَمَاسٍ. 2.""كَانَ مُنْدَفِعاً غَيْرَ مُتَحَكِّمٍ فِي أَعْصَابِهِ"" : أَيْ سَرِيعَ الغَضَبِ، حَادَّ الطَّبْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(677, 'مُنْدَمِجٌ', 'مندمج', 'اسم فاعل', 'دمج', 'مندمج', 'مندمج', 'فا. من اِنْدَمَجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْدَمَجَ). 1.""مُنْدَمِجٌ فِي العَمَلِ"" : مُسْتَغْرِقٌ فِيهِ. 2.""خَلِيَّةٌ مُنْدَمِجَةٌ فِي أُخْرَى"" : مُلْتَحِمَةٌ، مُلْتَئِمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(678, 'مُنْذِرٌ', 'منذر', 'اسم فاعل', 'نذر', 'منذر', 'منذر', 'فا. من أَنْذَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُنْذِرٌ-مُنْذِرٌ [ن ذ ر] (فا. من أَنْذَرَ). ""جَاءهُ مُنْذِراً"" : مُحَذِّراً، مُنَبِّهاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(679, 'مُنْذَهِلٌ', 'منذهل', 'اسم فاعل', 'ذهل', 'منذهل', 'منذهل', 'فا. من اِنْذَهَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْذَهَلَ). ""مُنْذَه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(680, 'مُنْزَعِجٌ', 'منزعج', 'اسم فاعل', 'زعج', 'منزعج', 'منزعج', 'فا. من اِنْزَعَجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْزَعَجَ). ""مُنْزَعِجٌ لِمَا سَمِعَ مِنْ أَخْبَارٍ سَيِّئَةٍ"" : قَلِقٌ، جَزِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(681, 'مُنْشَغِفٌ', 'منشغف', 'اسم فاعل', 'شغف', 'منشغف', 'منشغف', 'فا. من اِنْشَغَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْشَغَفَ). ""قَلْبٌ مُنْشَغِفٌ بِحُبِّهَا"" : مُتَدَلِّهٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(682, 'مُنْسَاقٌ', 'منساق', 'اسم فاعل', 'سوق', 'منساق', 'منسق', 'فا. من اِنْسَاقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُنْسَاقٌ-مُنْسَاقٌ [س و ق] (فا. من اِنْسَاقَ). ""مُنْسَاقٌ مَعَ أَهْوَائِهِ"" : مُنْقَادٌ، خَاضِعٌ وَمُسَايِرٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(683, 'مُنْسَجِمٌ', 'منسجم', 'اسم فاعل', 'سجم', 'منسجم', 'منسجم', 'فا. من اِنْسَجَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْسَجَمَ). 1.""مُنْسَجِمٌ مَعَ أَفْكَارِهِ"" : مُتَّفِقٌ، أَيْ فِي تَوَافُقٍ تَامٍّ مَعَهَا. ""مُنْسَجِمٌ مَعَ نَفْسِهِ"". 2.""أَنْغ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(684, 'مُنْسَحِبٌ', 'منسحب', 'اسم فاعل', 'سحب', 'منسحب', 'منسحب', 'فا. من اِنْسَحَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْسَحَبَ). ""مُنْسَحِبٌ مِنَ الاجْتِمَاعِ"" : خَارِجٌ مِنْهُ بِسَبَبِ مَوْقِفٍ يَمْنَعُهُ مِنَ الْحُضُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(685, 'مُنْسَحِقٌ', 'منسحق', 'اسم فاعل', 'سحق', 'منسحق', 'منسحق', 'فا. من اِنْسَحَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُنْسَحِقٌ-مُنْسَحِقٌ، ةٌ [س ح ق] (فا. من اِنْسَحَقَ). 1.""حُبُوبٌ مُنْسَحِقَةٌ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(686, 'مُنْسَلِخٌ', 'منسلخ', 'اسم فاعل', 'سلخ', 'منسلخ', 'منسلخ', 'فا. من اِنْسَلَخَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْسَلَخَ). 1.""مُنْسَلِخُ الْجِلْدِ"" : مَنْزُوعُ الْجِلْدِ. 2.""مُنْسَلِخٌ عَنْ أَفْكَارِهِ"" : مُتَخَلٍّ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(687, 'مُنْشِئٌ', 'منشئ', 'اسم فاعل', 'نشأ', 'منشء', 'منش', 'فا. من أَنْشَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَنْشَأَ). 1.""مُنْشِئُ العَالَمِ"" : خَالِقُهُ. 2.""مُنْشِئُ دَوْلَةِ كَذا"" : مُؤَسِّسُهَا. 3.""مُنْشِئٌ لِلْمَعَامِلِ وَالْمَصَانِعِ"": مُحْدِثُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(688, 'مُنْشِدٌ', 'منشد', 'اسم فاعل', 'نشد', 'منشد', 'منشد', 'فا. من أَنْشَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَنْشَدَ). ""مُنْشِدٌ لِأُغْنِيَّةٍ دِينِيَّةٍ"" : أَيْ مُؤَدِّيهَا حَسَبَ لَحْنٍ وَإِيقَاعٍ. ""اِجْتَمَعَ الْمُنْشِدُونَ يُنْشِدُونَ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(689, 'مُنْشَرِحٌ', 'منشرح', 'اسم فاعل', 'شرح', 'منشرح', 'منشرح', 'فا. من اِنْشَرَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْشَرَحَ). ""مُنْشَرِحُ الصَّدْرِ"" : مُنْتَشٍ، فَرِحٌ. ""القَلْبُ مُطْمَئِنٌّ وَالصَّدْرُ مُنْشَرِحٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(690, 'مُنْشَطِرٌ', 'منشطر', 'اسم فاعل', 'شطر', 'منشطر', 'منشطر', 'فا. من اِنْشَطَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْشَطَرَ). ""مُنْشَطِرٌ إِلَى شَطْرَيْنِ"" : مُنْقَسِمٌ إِلَى نِصْفَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(691, 'مُنْشَغِلٌ', 'منشغل', 'اسم فاعل', 'شغل', 'منشغل', 'منشغل', 'فا. من اِنْشَغَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُنْشَغِلٌ-مُنْشَغِلٌ، ةٌ [ش غ ل] (فا. من اِنْشَغَلَ). ""كُلَّمَا كَلَّمَهُ يَجِدُهُ مُنْشَغِلاً"" : مُنْهَمِكاً فِي شُغْلِهِ، كَثِيرَ الأَشْغَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(692, 'مُنْشَقٌّ', 'منشق', 'اسم فاعل', 'شقق', 'منشق', 'منشق', 'فا. من اِنْشَقَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْشَقَّ). 1.""صَحْنٌ مُنْشَقٌّ"" : مُتَصَدِّعٌ. 2.""مُنْشَقٌّ عَنِ الصَّفِّ"" : خَارِجٌ عَنْهُ، مُخْتَلِفٌ عَنْهُ. ""مُنْشَقٌّ عَنِ الْحِزْبِ"" ""مُنْشَقُّونَ عَنِ الْجَمَاعَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(693, 'مُنْصِتٌ', 'منصت', 'اسم فاعل', 'نصت', 'منصت', 'منصت', 'فا. من أَنْصَتَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَنْصَتَ). ""مُنْصِتٌ إِلَى الْمُتَحَدِّثِ بِاهْتِمَامٍ بَالِغٍ"" : مُسْتَمِعٌ بِانْتِبَاهٍ. ""جَلَسَ يَتَحَدَّثُ وَالقَوْمُ مُنْصِتُونَ كَأَنَّ عَلَى رُؤُوسِهِمُ الطَّيْرُ"". (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(694, 'مُنْصَرِفٌ', 'منصرف', 'اسم فاعل', 'صرف', 'منصرف', 'منصرف', 'فا. من اِنْصَرَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْصَرَفَ). 1.""مُنْصَرِفٌ إِلَى عَمَلِهِ"" : ذَاهِبٌ إِلَيْهِ، مُنْهَمِكٌ. 2.""مُنْصَرِفٌ عَنِ اللَّهْوِ وَاللَّعِبِ"" : مُبْتَعِدٌ... 3.""اِسْمٌ مُنْصَرِفٌ"": قَابِلِيَّةُ دُخُولِ التَّنْوِينِ عَلَيْهِ. 4.""فِعْلٌ مُنْصَرِفٌ"" : فِعْلٌ يُصَرَّفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(695, 'مُنْصَرِمٌ', 'منصرم', 'اسم فاعل', 'صرم', 'منصرم', 'منصرم', 'فا. من اِنْصَرَمَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْصَرِمٌ-مُنْصَرِمٌ، ةٌ [ص ر م] (فا. من اِنْصَرَمَ). 1.""حَبْلٌ مُنْصَرِمٌ"" : مُنْقَطِعٌ. ""صَدَاقَةٌ مُنْصَرِمَةٌ"". 2.""الشَّهْرُ الْمُنْصَرِمُ"": الْمُنْقَضِي، الْمُنْتَهِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(696, 'مُنْصِفٌ', 'منصف', 'اسم فاعل', 'نصف', 'منصف', 'منصف', 'فا. من أَنْصَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَنْصَفَ). 1.""هُوَ مُنْصِفٌ فِي حُكْمِهِ"" : عَادِلٌ فِي حُكْمِهِ. 2.""مُنْصِفُ الزَّاوِيَةِ"" (هن) : نِصْفُ مُسْتَقِيمٍ يَخْرُجُ مِنْ رَأْسِ الزَّاوِيَةِ وَيُقَسِّمُهَا إِلَى زَاوِيَتَيْنِ مُتَسَاوِيَتَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(697, 'مُنْضَوِي', 'منضوي', 'اسم فاعل', 'ضوي', 'منضوي', 'منض', 'فا. من اِنْضَوَى', 'Tk', '‏Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْضَوَى). ""مُنْضَوٍ تَحْتَ رَايَةِ الإِسْلاَمِ"" : مُنْضَمٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(698, 'مُنْطَادٌ', 'منطاد', 'اسم فاعل', 'طود', 'منطاد', 'منطد', 'فا. من اِنْطَادَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":مَنَاطِيدُ"', '', '', '', '', '', '', '', '', '"(فا. من اِنْطَادَ). 1.""حَاوَلَ أَنْ يَطُوفَ العَالَمَ بِالْمُنْطَادِ"" : مَرْكَبَةٌ هَوَائِيَّةٌ تَعْلُوهَا قُبَّةٌ بِلاَ جَنَاحَيْنِ تُمْلأُ بِغَازِ الْهِيدْرُوجِين، تَرْتَفِعُ فِي الْجَوِّ وَتَسِيرُ بِبُطْءٍ وَتَطُوفُ الأَرْجَاءَ. 2.""بِنَاءٌ مُنْطَادٌ"" : مُرْتَفِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(699, 'مَنَاطِيدُ', 'مناطيد', 'اسم فاعل', '', 'مناطيد', 'منطد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(700, 'مُنْطَلِقٌ', 'منطلق', 'اسم فاعل', 'طلق', 'منطلق', 'منطلق', 'فا. من اِنْطَلَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْطَلَقَ). 1.""مُنْطَلِقٌ فِي عَمَلِهِ"" : سَائِرٌ فِيهِ. 2.""مُنْطَلِقُ اللِّسَانِ"": فَصِيحٌ مُتَكَلِّمٌ بِلاَ تَلَعْثُمٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(701, 'مُنْطَوِي', 'منطوي', 'اسم فاعل', 'طوي', 'منطوي', 'منط', 'فا. من اِنْطَوَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْطَوَى). 1.""عَاشَ مُنْطَوِياً عَلَى نَفْسِهِ"" : مُنْكَمِشاً "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(702, 'مُنْعَدِمٌ', 'منعدم', 'اسم فاعل', 'عدم', 'منعدم', 'منعدم', 'فا. من اِنْعَدَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْعَدَمَ). ""مُنْعَدِمُ الْحَيَاءِ"" : فَاقِدُ الْحَيَاءِ، عَدِيمُهُ. ""مُنْعَدِمُ الإِحْسَاسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(703, 'مُنْعَرِجٌ', 'منعرج', 'اسم فاعل', 'عرج', 'منعرج', 'منعرج', 'فا. من اِنْعَرَجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُنْعَرِجٌ-مُنْعَرِجٌ، ةٌ [ع ر ج] (فا. من اِنْعَرَجَ). ""طَرِيقٌ مُنْعَرِجٌ"": مُنْعَرِجٌ، أَيْ مُلْتَوٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(704, 'مُنْعَزِلٌ', 'منعزل', 'اسم فاعل', 'عزل', 'منعزل', 'منعزل', 'فا. من اِنْعَزَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْعَزَلَ). 1.""اِنْزَوَى فِي مَكَانٍ مُنْعَزِلٍ"" : مُنْزَوٍ، بَعِيد عَنِ النَّاسِ. 2.""عَاشَ مُنْعَزِلاً فِي آخِرِحَيَاتِهِ عَنِ النَّاسِ"" : مُنْطَوِياً، مُنْكَمِشاً عَلَى نَفْسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(705, 'مُنْعِشٌ', 'منعش', 'اسم فاعل', 'نعش', 'منعش', 'منعش', 'فا. من أَنْعَشَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُنْعِشٌ-مُنْعِشٌ، ةٌ [ن ع ش] (فا. من أَنْعَشَ). ""دَوَاءٌ مُنْعِشٌ"" : مُقَوٍّ، أَيْ بَاعِثٌ عَلَى الْحَيَوِيَّةِ والنَّشَاطِ بَعْدَ فُتُورٍ. ""عَصِيرٌ مُنْعِشٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(706, 'مُنْعَكِسٌ', 'منعكس', 'اسم فاعل', 'عكس', 'منعكس', 'منعكس', 'فا. من اِنْعَكَسَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْعَكَسٌ-مُنْعَكَسٌ، ةٌ [ع ك س] (مفع. مِن اِنْعَكَسَ). ""مُنْعَكَسُ الضَّوْءِ"" : نُقْطَةُ اِنْعِكَاسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(707, 'مُنْفَتِحٌ', 'منفتح', 'اسم فاعل', 'فتح', 'منفتح', 'منفتح', 'فا. من اِنْفَتَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْفَتَحَ). 1.""بَابٌ مُنْفَتِحٌ"" : مَفْتُوحٌ. 2.""مُنْفَتِحُ الصَّدْرِ"" : مُنْشَرِحٌ. 3.""مُنْفَتِحٌ عَلَى الأَفْكَارِ الْجَدِيدَةِ"" : مُتَقَبِّلٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(708, 'مُنْفَجِرٌ', 'منفجر', 'اسم فاعل', 'فجر', 'منفجر', 'منفجر', 'فا. من اِنْفَجَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْفَجَرَ). ""قُنْبُلَةٌ مُنْفَجِرَةٌ"" : مُتَفَجّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(709, 'مُنْفَرِجٌ', 'منفرج', 'اسم فاعل', 'فرج', 'منفرج', 'منفرج', 'فا. من اِنْفَرَجَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْفَرِجٌ-مُنْفَرِجٌ، ةٌ [ف ر ج] (فا. من اِنْفَرَجَ). 1.""جَوٌّ مُنْفَرِجٌ"" : أَيْ جَوٌّ صَحْوٌ بَعْدَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(710, 'مُنْفَرِدٌ', 'منفرد', 'اسم فاعل', 'فرد', 'منفرد', 'منفرد', 'فا. من اِنْفَرَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْفَرَدَ). 1.""مُنْفَرِدٌ بِنَفْسِهِ"" : مُنْعَزِلٌ ... ""ظَلَّتْ مُنْفَرِدَةً بِطِفْلِهَا فِي زَاوِيَةِ الغُرْفَةِ"". 2.""بَقِيَ مُنْفَرِداً بِرَأْيِهِ"" : مُتَشَبِّثاً ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(711, 'مُنْكَمِشٌ', 'منكمش', 'اسم فاعل', 'كمش', 'منكمش', 'منكمش', 'فا. من اِنْكَمَشَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْكَمَشَ). 1.""ثَوْبٌ مُنْكَمِشٌ"" : مُتَقَبِّضٌ. 2.""هُوَ مُنْكَمِشٌ عَلَى نَفْسِهِ"" : مُنْطَوٍ، مُنْعَزِلٌ، مُنْزَوٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(712, 'مُنْفَصِلٌ', 'منفصل', 'اسم فاعل', 'فصل', 'منفصل', 'منفصل', 'فا. من اِنْفَصَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْفَصَلَ). ""أَجْزَاءٌ مُنْفَصِلَةٌ عَنْ بَعْضِهَا"" : مُنْقَطِعَةٌ، أَيْ ل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(713, 'مُنْفَعِلٌ', 'منفعل', 'اسم فاعل', 'فعل', 'منفعل', 'منفعل', 'فا. من اِنْفَعَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْفَعَلَ). ""وَجَدَهُ مُنْفَعِلاً"" : مُتَأَثِّراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(714, 'مُنْقَادٌ', 'منقاد', 'اسم فاعل', 'قود', 'منقاد', 'منقد', 'فا. من اِنْقَادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْقَادَ). ""عَادَ مُنْقَاداً"" : خَاضِعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(715, 'مُنْقَبِضٌ', 'منقبض', 'اسم فاعل', 'قبض', 'منقبض', 'منقبض', 'فا. من اِنْقَبَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْقَبَضَ). 1.""مُنْقَبِضُ الصَّدْرِ"" : مُتَضَايِقُ النَّفْسِ. 2.""بَطْنٌ مُنْقَبِضٌ"" : مُتَقَلِّصٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(716, 'مُنْقِذٌ', 'منقذ', 'اسم فاعل', 'نقذ', 'منقذ', 'منقذ', 'فا. من أَنْقَذَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَنْقَذَ). 1.""مُنْقِذُهُ مِنَ الغَرَقِ"" : مَنْ أَنْقَذَهُ مِنَ الغَرَقِ. 2.""مُنْقِذٌ مِنَ الضَّلاَلِ"" : مُنَجٍّ. 3.""مُنْقِذُ البِلاَدِ مِنَ العُبُودِيَّةِ"" : مُحَرِّرُهَا، مُخَلِّصُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(717, 'مُنْقَرِضٌ', 'منقرض', 'اسم فاعل', 'قرض', 'منقرض', 'منقرض', 'فا. من اِنْقَرَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُنْقَرِضٌ-مُنْقَرِضٌ، ةٌ [ق ر ض] (فا. من اِنْقَرَضَ). ""الدِّينَاصُورُ ح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(718, 'مُنْقَطِعٌ', 'منقطع', 'اسم فاعل', 'قطع', 'منقطع', 'منقطع', 'فا. من اِنْقَطَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْقَطَعَ). 1.""حَبْلٌ مُنْقَطِعٌ"" : جُزْءٌ مِنْهُ مُنْفَصِلٌ عَنِ الآخَرِ. 2.""مَطَرٌ مُنْقَطِعٌ"" : مُحْتَبِسٌ. 3.""مُنْقَطِعٌ عَنِ العَمَلِ"" : تَارِكُهُ. 4.""التَّيَّارُ الكَهْرَبَائِيُّ مُنْقَطِعٌ مُنْذُ الص"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(719, 'مُنْقَلِبٌ', 'منقلب', 'اسم فاعل', 'قلب', 'منقلب', 'منقلب', 'فا. من اِنْقَلَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُنْقَلِبٌ-مُنْقَلِبٌ [ق ل ب] (فا. من اِنْقَلَبَ). 1.""رَجُلٌ مُنْقَلِبٌ عَلَى ظَهْرِهِ"" : مُسْتَلْقٍ على ظَهْرِهِ. ""سُلَحْفَاةٌ مُنْقَلِبَةٌ عَلَى ظَهْرِها"". 2."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(720, 'مُنْكِرٌ', 'منكر', 'اسم فاعل', 'نكر', 'منكر', 'منكر', 'فا. من أَنْكَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَنْكَرَ). 1.""مُنْكِرُ الفَضْلِ"" : جَاحِدٌ بِهِ غَيْرُ مُعْتَرِفٍ بِهِ. 2.""مُنْكِرٌ كُلَّ التُّهَمِ الْمُوَجَّهَةِ إِلَيْهِ"" : غَيْرُ مُقِرٍّ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(721, 'مُهْتَمٌّ', 'مهتم', 'اسم فاعل', 'همم', 'مهتم', 'مهتم', 'فا. من اِهْتَمَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِهْتَمَّ). ""مُهْتَمٌّ بِأُمُورِهِ"" : مُعْتَنٍ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(722, 'مُنْهَارٌ', 'منهار', 'اسم فاعل', 'هور', 'منهار', 'منهر', 'فا. من اِنْهَارَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(فا. من اِنْهَارَ). 1.""جِدَارٌ مُنْهَارٌ"" : مُنْهَدِمٌ. 2.""وَجَدَهُ مُنْهَارَ القُوَى"" : مُحَطَّماً، مَنْهُوكاً، مُصَاباً بِضُعْفٍ. ""مُنْهَارُ الأَعْصَابِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(723, 'مُنْهَزِمٌ', 'منهزم', 'اسم فاعل', 'هزم', 'منهزم', 'منهزم', 'فا. من اِنْهَزَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْهَزَمَ). ""جَيْشٌ مُنْهَزِمٌ"" : مُنْكَسِرٌ، "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(724, 'مُنْهِكٌ', 'منهك', 'اسم فاعل', 'نهك', 'منهك', 'منهك', 'فا. من أَنْهَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَنْهَكَ). ""مَرَضٌ مُنْهِكٌ"" : مُحَطِّمٌ، مُتْعِبٌ أَشَدُّ التَّعَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(725, 'مُنْهَمِرٌ', 'منهمر', 'اسم فاعل', 'همر', 'منهمر', 'منهمر', 'فا. من اِنْهَمَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْهَمِرٌ-مُنْهَمِرٌ، ةٌ [هـ م ر] (فا. من اِنْهَمَرَ). ""مَطَرٌ مُنْهَمِرٌ"": مُتَسَاقِطٌ بِغَزَارَةٍ. ""دُمُوعٌ مُنْهَمِرَةٌ عَلَى خَدِّهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(726, 'مُنْهَمِكٌ', 'منهمك', 'اسم فاعل', 'همك', 'منهمك', 'منهمك', 'فا. من اِنْهَمَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِنْهَمَكَ). ""مُنْهَمِكٌ فِي عَمَلِهِ"" : مُسْتَغْرِقٌ فِيهِ، مُنْكَبٌّ عَلَيْهِ، مُنْشَغِلٌ بِهِ. ""وَجَدَهُمْ جَمِيعاً مُنْهَمِكِينَ فِي أَحَادِيثِهِمْ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(727, 'مُهْتَاجٌ', 'مهتاج', 'اسم فاعل', 'هيج', 'مهتاج', 'مهتج', 'فا. من اِهْتَاجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِهْتَاجَ). ""جَاءَ إِلَيْهِ مُهْتَاجاً والغَضَبُ يَتَطَايَرُ مِنْ عَيْنَيْهِ"" : ثَائِراً مِنَ الغَضَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(728, 'مُهْتَدِي', 'مهتدي', 'اسم فاعل', 'هدي', 'مهتدي', 'مهتد', 'فا. من اِهْتَدَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِهْتَدَى). 1.""رَجُلٌ مُهْتَدٍ"" : السَّائِرُ فِي طَرِيقِ الرَّشَادِ والصَّوَابِ.النجم آية 30 إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَنْ ضَلَّ عَن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(729, 'مُهْتَرِئٌ', 'مهترئ', 'اسم فاعل', 'هرأ', 'مهترء', 'مهتر', 'فا. من اهْتَرَأَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُهْتَرِئٌ-مُهْتَرِئٌ، ةٌ [هـ ر أ] (فا. من اهْتَرَأَ). ""ثَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(730, 'مُهْتَزٌّ', 'مهتز', 'اسم فاعل', 'هزز', 'مهتز', 'مهتز', 'فا. من اِهْتَزَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من اِهْتَزَّ). 1.""جِدَارٌ مُهْتَزٌّ"" : غَيْرُ مُسْتَقِرٍّ عَلَى أُسُسٍ مَتِينَةٍ. 2. ""مُهْتَزٌّ طَرَباً"" : نَشِيطٌ، فَرِحٌ. 3.""أَصْوَاتٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(731, 'مُورِقٌ', 'مورق', 'اسم فاعل', 'ورق', 'مورق', 'مرق', 'فا. من أَوْرَقَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُورِقٌ-مُورِقٌ، ةٌ [و ر ق] (فا. من أَوْرَقَ). ""شَجَرَةٌ مُورِقَةٌ"" : أَوْرَاقُهَا مُنْبَسِطَةٌ خَضْرَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(732, 'آهِلٌ', 'آهل', 'اسم فاعل', 'أهل', 'ءاهل', 'آهل', 'فَا. مِنْ أهَل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"آهِلٌ-آهِلٌ [أ هـ ل] (فَا. مِنْ أهَل). 1.""رَجُلٌ آَهِلٌ "" : مَنْ لَهُ زَوْجَةٌ وَأَوْلاَدٌ . 2.""مَكَان"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(733, 'أواهل', 'أواهل', 'اسم فاعل', '', 'ءواهل', 'هل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(734, 'مُهْلِكٌ', 'مهلك', 'اسم فاعل', 'هلك', 'مهلك', 'مهلك', 'فا. من أَهْلَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَهْلَكَ). ""رَجُلٌ مُهْلِكٌ"" : مُدَمِّرٌ. ""مَرَضٌ مُهْلِكٌ"" ""نَارٌ مُهْلِكَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(735, 'مُهْمِلٌ', 'مهمل', 'اسم فاعل', 'همل', 'مهمل', 'مهمل', 'فا. من أَهْمَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَهْمَلَ). ""مُهْمِلٌ لِوَاجِبَاتِهِ"" : تَارِكٌ لَهَا عَمْداً. ""مُهْمِلَةٌ لِمَلاَبِسِهَا وَزِينَتِهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(736, 'مُوجِبٌ', 'موجب', 'اسم فاعل', 'وجب', 'موجب', 'مجب', 'فا. من أَوْجَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَوْجَبَ). ""سُلُوكٌ مُوجِبٌ لِلاِحْتِرَامِ"" : بَاعِثٌ، دَاعٍ. ""لاَ مُوجِبَ لِهَذَا الغَضَبِ"". 2.""بِمُوجِبِ القَانُونِ"" : بِمُقَتَضَاهُ. 3.""بِلاَ مُوجِبٍ"": بِلاَ سَبَبٍ. 4.""الْمُوجِبَاتُ فِي الشَّرْعِ"" : الكَبَائِرُ مِنَ الذُّنُوبِ الَّتِي تُوجِبُ عِقَابَ الآخِرَةِ أَوِ الْحَسَناَتُ الَّتِي تُوجِبُ الْجَنَّةَ. 5.""تَيَّارٌ مُوجِبٌ"" : أَيْ عَكْسُ السَّالِبِ، الإِشَارَةُ الْمُوجِبَةُ (+) هِيَ عَكْسُ الإِشَارَةِ السَّالِبَةِ (-). 6. ""العَدَدُ الْمُوجِبُ فِي الرِّيَاضِيَّاتِ"" : هُوَ أَكْبَرُ مِنَ الصِّفْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(737, 'مُوجِزٌ', 'موجز', 'اسم فاعل', 'وجز', 'موجز', 'مجز', 'فا. من أَوْجَزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَوْجَزَ). ""مُوجِزٌ فِي كَلاَمِهِ"" : مُخْتَصِرٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(738, 'مُوحَشٌ', 'موحش', 'اسم فاعل', 'وحش', 'موحش', 'محش', 'فا. من أَوْحَشَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوحَشٌ-مُوحَشٌ، ةٌ [و ح ش] (فا. من أَوْحَشَ). ""مَكَانٌ مُوحَشٌ"" : قَفْرٌ لاَ أُنْسَ فِيهِ. تَرَكَتْنِي هَائِماً أَبْكِي لِمَرْزِئَة*فِي مَنْزِلٍ مُوحَشٍ مِنْ بَعْدِ إِينَاسِ (عمران بن حطان)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(739, 'مُوحِي', 'موحي', 'اسم فاعل', 'وحي', 'موحي', 'مح', 'فا. من أَوْحَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَوْحَى). ""مَنِ الْمُوحِي إِلَيْهِ بِكُلِّ هَذَا"" : أَيْ مَنِ الَّذِي أَوْحَى إِلَيْهِ، الْمُشِيرُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(740, 'مُودِعٌ', 'مودع', 'اسم فاعل', 'ودع', 'مودع', 'مدع', 'فا. من أَوْدَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَوْدَعَ). ""جَاءَ مُودِعاً أَمْوَالَهُ فِي صُنْدُوقِ التَّوْفِيرِ"" : وَاضِعاً. ""مُودِعُو صُنْدُوقِ التَّوْفِيرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(741, 'مُوقِنٌ', 'موقن', 'اسم فاعل', 'يقن', 'موقن', 'مقن', 'فا. من أَيْقَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَيْقَنَ). ""مُوقِنٌ بِأَكَاذِيبِهِ"" : عَالِمٌ بِهَا ومُتَحَقِّقٌ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(742, 'مُوشِكٌ', 'موشك', 'اسم فاعل', 'وشك', 'موشك', 'مشك', 'فا. من أَوْشَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَوْشَكَ). ""مُوشِكٌ عَلَى الإِفْلاَسِ"" : أَيْ قَرِيبٌ مِنَ الإِفْلاَسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(743, 'مُوصِي', 'موصي', 'اسم فاعل', 'وصي', 'موصي', 'مص', 'فا. من أَوْصَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَوْصَى). ""مُوصٍ بِأَمْوَالِهِ وأَمْلاَكِهِ لأَعْمَالِ الْخَيْرِ"": وَاهِبُهَا بِمُوجِبِ وَصِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(744, 'مُوهِنٌ', 'موهن', 'اسم فاعل', 'وهن', 'موهن', 'مهن', 'فا. من أَوْهَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من أَوْهَنَ). ""مُوهِنُ النَّفْسِ"" : مُحْبِطُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(745, 'مُؤْتَزِرٌ', 'مؤتزر', 'اسم فاعل', 'أزر', 'مءتزر', 'متزر', 'فَا. مِن اِئْتَزَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِئْتَزَرَ). ""خَرَجَتْ مُؤْتَزِرَةً"" : لاَبِسَةً الإِزَارَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(746, 'مُؤْتَلِفٌ', 'مؤتلف', 'اسم فاعل', 'ألف', 'مءتلف', 'متلف', 'فَا. مِن اِئْتَلَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِئْتَلَفَ). 1.""كَانَا مُؤْتَلِفَيْنِ"" : مُجْتَمِعَيْنِ، مُتَوَافِقَيْنِ. 2.""حَدِيثٌ مُؤْتَلِفٌ مِنْ جُمَلٍ بَلِيغَةٍ"" : أَيْ مُكَوَّنٌ. ""أَسَالِيبُ مُؤْتَلِفَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(747, 'مُؤْتَمِرٌ', 'مؤتمر', 'اسم فاعل', 'أمر', 'مءتمر', 'متمر', 'فَا. مِن اِئْتَمَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن اِئْتَمَرَ). ""حَضَرَ الْمُؤْتَمِرُونَ"" : الَّذِينَ لَهُمُ الْحَقُّ فِي حُضُورِ الْمُؤْتَمَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(748, 'مُؤَيِّدٌ', 'مؤيد', 'اسم فاعل', 'أيد', 'مءيد', 'مد', 'فَا. مِنْ أَيَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ أَيَّدَ). ""كَانَ مُؤَيِّداً لِقَرَارِهِ"" : مُقَوِّياً، مُدَعِّماً لَهُ. ""مِنَ الْمُؤَيِّدِينَ لِسِيَاسَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(749, 'مُوسِرٌ', 'موسر', 'اسم فاعل', 'يسر', 'موسر', 'مسر', 'فا. من أَيْسَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَيَاسِرُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من أَيْسَرَ). ""رَجُلٌ مُوسِرُ الْحَالِ"" : غَنِيٌّ. ""كَانَ يُوَسِّعُ عَلَى الْمُقَتِّرِ ويُقَتِّرُ عَلَى الْمُوسِرِ"". (ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(750, 'مَيَاسِرُ', 'مياسر', 'اسم فاعل', '', 'مياسر', 'مسر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(751, 'بُورٌ', 'بور', 'اسم فاعل', '', 'بور', 'بر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(752, 'بَائِتٌ', 'بائت', 'اسم فاعل', 'بيت', 'باءت', 'بت', 'فا. من بات', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"بَائِتٌ-بَائِتٌ [ب ي ت] (فا. من بات). ""طَعَامٌ بَائِتٌ"" : مَا مَرَّتْ عَلَيْهِ لَيْلَةٌ. ""خُبْزٌ بَائِتٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(753, 'بوائت', 'بوائت', 'اسم فاعل', '', 'بواءت', 'بت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(754, 'بَائِخٌ', 'بائخ', 'اسم فاعل', 'بوخ', 'باءخ', 'بخ', 'فا. من باخ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"بَائِخٌ-بَائِخٌ [ب و خ] (فا. من باخ). 1 .""رجُلٌ بائِخٌ"" : تَافِهٌ. 2.""طَعْمٌ بَائِخٌ"" : باسِلٌ. 3.""طعامٌ بائِخٌ"" : فاسدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(755, 'بوائخ', 'بوائخ', 'اسم فاعل', '', 'بواءخ', 'بخ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(756, 'بَائِدٌ', 'بائد', 'اسم فاعل', 'بيد', 'باءد', 'بد', 'فا. من باد', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"بَائِدٌ-بَائِدٌ [ب ي د] (فا. من باد). ""هَذَا مِنَ العهْدِ البائِدِ"": مِنَ العَهْدِ الْمَاضِي الزَّائِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(757, 'بوائد', 'بوائد', 'اسم فاعل', '', 'بواءد', 'بد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(758, 'مُبَادِرٌ', 'مبادر', 'اسم فاعل', 'بدر', 'مبادر', 'مبدر', 'فا. من بادر', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(759, 'مُبَادِلٌ', 'مبادل', 'اسم فاعل', 'بدل', 'مبادل', 'مبدل', 'فا. من بَادَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(760, 'بَائِرٌ', 'بائر', 'اسم فاعل', 'بور', 'باءر', 'بر', 'فا. من بار', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":بُورٌ"', '', '', '', '', '', '', '', '', '"(فا. من بار). 1.""ظَلَّتْ هَذِهِ الأرْضُ بَائِرَةً"" : غَيْرَ مَزْروعَةٍ. 2.""مُنْذُ شهْرٍ وَالسُّوقُ بَائِرَةٌ"" : كَاسِدَةٌ، لاَ رَوَاجَ فِيهَا. ""سِلْعةٌ بَائِرةٌ"". 3.""ولَدٌ حَائِرٌ بَائِرٌ"" : تَائِهٌ دُونَ هَدَفٍ، لاَ يَأخُذُ بِكَلاَمِ أَحَدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(761, 'باتٌّ', 'بات', 'اسم فاعل', 'بتت', 'بات', 'بت', 'فا. من بَتَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"باتٌّ-باتٌّ [ب ت ت] (مص. بَتَّ). 1.""مَنَعَهُ مَنْعاً باتّاً مِنْ دُخولِ الفَصْلِ"" : مَنْعاً قاطِعاً، نِهائِيّاً. ""يُمْنَعُ مَنْعاً باتّاً دُخولُ الحَديقَةِ لَيْلاً"". 2.""مَنْعٌ باتٌّ"" : صَريحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(762, 'بوائر', 'بوائر', 'اسم فاعل', '', 'بواءر', 'بر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(763, 'مُبَارِزٌ', 'مبارز', 'اسم فاعل', 'برز', 'مبارز', 'مبرز', 'فَا. مِنْ بَارَزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ بَارَزَ). ""كَانَ مُبَارِزاً لَهُ"" : مُزَاحِماً، مُبَارِياً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(764, 'مُبَاشِرٌ', 'مباشر', 'اسم فاعل', 'بشر', 'مباشر', 'مبشر', 'فا. من بَاشَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُبَاشِرٌ-مُبَاشِرٌ، ةٌ [ب ش ر] (فا. من بَاشَرَ). 1. ""سَبَبٌ مُبَاشِرٌ"" : سَبَبٌ حَدَثَ دُونَ وَاسِطَةٍ. 2.""اِعْتَمَدَ أُسْلُوباً مُبَاشِراً فِي حَدِيثِهِ"" : أَيْ حَدِيثاً يَعْتَمِدُ عَلَى التَّصْرِيحِ وَالتَّقْرِيرِ. 3.""نَقْلٌ إِذَاعِيٌّ مُبَاشِرٌ"" : أَيْ نَقْلٌ فَوْرِيٌّ، دُونَ سَابِق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(765, 'بَائِعٌ', 'بائع', 'اسم فاعل', 'بيع', 'باءع', 'بع', 'فا. من باع', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":بَاعَةٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من باع). ""بَائِعُ الثَّوْبِ"" : الَّذِي يَبِيعُ الثَّوبَ. ""بائِعُ الصُّحُفِ"" ""تَفَرَّقَ البَاعَةُ فِي السُّوقِ"" ""أنا بَائِعُ مَا فِي هَذِهِ الجَرَّةِ بِدِينَارٍ"" (ابنُ المُقَفَّعِ)."', '');
