INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(792, 'بادِئٌ', 'بادئ', 'اسم فاعل', 'بدأ', 'بادء', 'بد', 'فا. من بدأ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"بادِئٌ-بادِئٌ [ب د أ] (فا. من بدأ). 1.""في بادِئِ الأَمْرِ"" : في أَوَّلِهِ. 2.""بَادِئَ ذِي بَدْءٍ"" : قَبْلَ كُلَّ شَيْءٍ. 3.""الشَّرُّ بِالشَّرِّ والبادِئُ أَظْلَمُ"" : الشَّرُّ بِالشَّرِّ والظَّالِمُ مَنْ ظَلَمَ في أَوَّلِ الأَمْرِ."', '');
