INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(794, 'بادِي', 'بادي', 'اسم فاعل', 'بدو', 'بادي', 'بد', 'فا. من بَدا', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من بَدا). ""كانَ الفَرَحُ بَادِياً على وَجْهِهِ"" : ظاهِراً، واضِحاً. ""آثارُ الحُزْنِ بادِيَةٌ على وُجوهِهِمْ"" ""دَلائِلُ الاسْتِغْرابِ بادِيَةٌ على وُجوهِهِمْ""."', '');
