INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(804, 'باذِخٌ', 'باذخ', 'اسم فاعل', 'بذخ', 'باذخ', 'بذخ', 'فا. من بَذَخَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":بُذَّخٌ:بَوَاذِخُ"', '', '', '', '', '', '', '', '', '"(فا. من بَذَخَ). 1.""رَجُلٌ باذِخٌ"" : مُتَكَبِّرٌ. 2.""جَبَلٌ باذِخٌ"" : عالٍ، شامِخٌ، مُرْتَفِعٌ. ¨""يُحِيطُ بِالقَرْيَةِ جِبَالٌ بَوَاذِخُ"". 3. ""هُوَ مِنْ عَائِلَةٍ لَهَا شَرَفٌ بَاذِخٌ"" : لَهَا شَأْنٌ عَظِيمٌ، مَجْدٌ عَظِيمٌ. "', '');
