INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(809, 'مُبَذِّرٌ', 'مبذر', 'اسم فاعل', 'بذر', 'مبذر', 'مبذر', 'فا. من بَذَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُبَذِّرٌ-مُبَذِّرٌ [ب ذ ر] (فا. من بَذَّرَ). ""مُبَذِّرٌ لِمَالِهِ"" : مُسْرِفٌ، أَيْ يُنْفِقُهُ فِي غَيْرِ مَحَلِّهِ."', '');
