INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(819, 'بَارِئٌ', 'بارئ', 'اسم فاعل', 'برأ', 'بارء', 'بر', 'فا. من برأ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"بَارِئٌ-بَارِئٌ [ب ر أ] (فا. من برأ). 1.""اللَّهُ البَارِئُ عَزَّ وَجَلَّ"" : الخَالِقُ. 2.""صَارَ بارئاً"" : مُتَعَافياً مِنْ كُلِّ مَرَضٍ وَعَيْبٍ. 3.""بارِئٌ مِنْ ذَنْبٍ أوْ تُهْمَةٍ"" : مُتَخلِّصٌ... "', '');
