INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(887, 'مُبَلِّطٌ', 'مبلط', 'اسم فاعل', 'بلط', 'مبلط', 'مبلط', 'فا. من بَلَّطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من بَلَّطَ). ""اِنْتَهَى الْمُبَلِّطُ مِنْ تَبْلِيطِ الرَّصِيفِ"" : عَامِلٌ يُبَلِّطُ الأَرْصِفَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(888, 'مُبَلِّغٌ', 'مبلغ', 'اسم فاعل', 'بلغ', 'مبلغ', 'مبلغ', 'فَا. مِنْ بَلَّغَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ بَلَّغَ). 1.""جَاءَ مُبَلِّغاً لِرِسَالَةٍ"" : رَسُولاً. 2.""مُبَلِّغُ الأَخْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(889, 'بالِغٌ', 'بالغ', 'اسم فاعل', 'بلغ', 'بالغ', 'بلغ', 'فا. من بَلَغَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"بالِغٌ-بالِغٌ، ةٌ [ب ل غ] (فا. من بَلَغَ) . 1.""وَلَدٌ بالِغٌ"" : بَلَغَ سِنَّ الرُّشْدِ، المُرَاهَقَةِ. ""فَتاةٌ بالِغٌ، بالِغَةٌ"". 2.""إنَّهُ لأَمْرٌ بالِغٌ هَذَا الَّذِي حَدَثَ"" : عَلَى قَدْرٍ كَبِيرٍ مِنَ الأهَمِّيَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(890, 'بوالغ', 'بوالغ', 'اسم فاعل', '', 'بوالغ', 'بلغ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(891, 'بلاغ', 'بلاغ', 'اسم فاعل', '', 'بلاغ', 'بلغ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
