INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(893, 'بِانِي', 'باني', 'اسم فاعل', 'بني', 'باني', 'بن', 'فا. من بَنَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":بُنَاةٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من بَنَى). ""بَانِي القُصُورِ والمُنْشَآتِ العُمْرَانِيَّةِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(894, 'بُنَاةٌ', 'بناة', 'اسم فاعل', '', 'بناة', 'بنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
