INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(896, 'باهِرٌ', 'باهر', 'اسم فاعل', 'بهر', 'باهر', 'بهر', 'فا من بَهَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', 'Cv', '"باهِرٌ-باهِرٌ، ةٌ [ب هـ ر] (فا من بَهَرَ). 1.""حَقَّقَ نَجاحاً باهراً"" : رائعاً. 2. ""كانَ الضَّوْءُ بَاهِراً فِي القاعَةِ"" : لاَمِعاً. ""زِينَةٌ باهِرةٌ لِكُلِّ عَيْنٍ"".(التوحيدي) ""سَتَصِيرِينَ غَداً سَيِّدَةً باهِرَةَ الجَمالِ"".(ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(897, 'بواهر', 'بواهر', 'اسم فاعل', '', 'بواهر', 'بهر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(898, 'بَائِسٌ', 'بائس', 'اسم فاعل', 'بأس', 'باءس', 'بس', 'فا. من بَئِسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":بُؤْسٌ:بُؤسَاءٌ"', '', '', '', '', '', '', '', '', '"(فا. من بَئِسَ). 1.""يَالَهُ مِنْ بَائِسٍ"" : مَنْ أصَابَتْهُ بَليَّةٌ. 2.""مُنْذُ عَرَفْتُهُ وَهُوَ بائِسٌ لاَ عَمَلَ لَهُ"" : فَقِيرٌ، مُعْوِزٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(899, 'بُؤْسٌ', 'بؤس', 'اسم فاعل', '', 'بءس', 'بس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
