INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(902, 'مُبَيِّضٌ', 'مبيض', 'اسم فاعل', 'بيض', 'مبيض', 'مبض', 'فَا. مِنْ بَيَّضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مَبِيضٌ-مَبِيضٌ [ب ي ض].: العُضْوُ الَّذِي تَتَكَوَّنُ فِيهِ البُوَيْضَةُ فِي جِسْمِ الأُنْثَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(903, 'تَائِبٌ', 'تائب', 'اسم فاعل', 'توب', 'تاءب', 'تب', 'فا. مِنْ تَابَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِنْ تَابَ). ""وَكَانَ مِنَ التَّائِبِينَ"" : مِنَ النَّادِمِينَ عَلَى مَا اقْتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(904, 'توائب', 'توائب', 'اسم فاعل', '', 'تواءب', 'تب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(905, 'تواب', 'تواب', 'اسم فاعل', '', 'تواب', 'تب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(906, 'مُتَأَبِّطٌ', 'متأبط', 'اسم فاعل', 'أبط', 'متءبط', 'متبط', 'فَا. مِنْ تَأَبَّطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَأَبَّطَ). ""جَاءَ مُتَأَبِّطاً ذِرَاعَهُ"" : وَاضِعاً إِيَّاهُ تَحْتَ إِبْطِهِ. ""نَسِيرُ جَنْباً لِجَنْبٍ مُتَأَبِّطِي الأَذْرُعِ"". (أحمد بوزفور)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(907, 'مُتَابِعٌ', 'متابع', 'اسم فاعل', 'تبع', 'متابع', 'متبع', 'فا. من تَابَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من تَابَعَ). ""مُتَابِعٌ لِلْعَمَلِ"" : مُسْتَمِرٌّ، مُثَابِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(908, 'مُتَأَثِّرٌ', 'متأثر', 'اسم فاعل', 'أثر', 'متءثر', 'متثر', 'فا. من تَأَثَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَأَثَّرَ). 1.""لاَ يَزَالُ مُتَأَثِّراً بِالْحَدَثِ"" : مُتَأَلِّماً، مُنْفَعِلاً. 2.""سَقَطَ مُتَأَثِّراً بِجِرَاحِهِ"" : سَقَطَ نَتِيجَةَ تَمَكُّنِ الجِرَاحِ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(909, 'مُتَأَجِّجٌ', 'متأجج', 'اسم فاعل', 'أجج', 'متءجج', 'متج', 'فا. من تَأَجَّجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَأَجِّجٌ-مُتَأَجِّجٌ، ةٌ [أ ج ج] (فا. من تَأَجَّجَ). 1. ""نَارٌ مُتَأَجِّجَةٌ"" : مُلْتَهِبَةٌ. 2.""حُبٌّ مُتَأَجِّجٌ"" : مُلْتَهِبٌ، حَارٌّ شَدِيدٌ. ""شَوْقٌ مُتَأَجِّجٌ"" ""عَاطِفَةٌ مُتَأَجِّجَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(910, 'مُتَاجِرٌ', 'متاجر', 'اسم فاعل', 'تجر', 'متاجر', 'متجر', 'فَا. مِنْ تَاجَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَاجَرَ). ""مُتَاجِرٌ فِي البَضَائِعِ الْمُسْتَوْرَدَةِ"" : الْمُمَارِسُ لِلْبَي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(911, 'مُتَأَمِّلٌ', 'متأمل', 'اسم فاعل', 'أمل', 'متءمل', 'متمل', 'فا. من تَأَمَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَأَمَّلَ). ""مُتَأَمِّلٌ فِي أَسْرَارِ الطَّبِيعَةِ"" : مُسْتَغْرِقُ التَّفْكِيرِ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(912, 'مُتَأَخِّرٌ', 'متأخر', 'اسم فاعل', 'أخر', 'متءخر', 'متخر', 'فا. من تَأَخَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَأَخَّرَ). 1.""وَصَلَ مُتَأَخِّراً إِلَى العَمَلِ"" : مَنْ يَصِلُ إِلَى مَكَانِ عَمَلِهِ بَعْدَ بِدَايَةِ الوَقْتِ الْمُعَيَّنِ لَهُ. 2.""مُتَأَخِّرٌ فِي عَمَلِهِ"" : لَمْ يُكَمِّلْهُ بَعْدُ، الَّذِي لاَ يَبْلُغُ غَايَتَهُ فِي عَمَلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(913, 'مُتَاخِمٌ', 'متاخم', 'اسم فاعل', 'تخم', 'متاخم', 'متخم', 'فَا. مِنْ تَاخَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَاخِمٌ-مُتَاخِمٌ، ةٌ [ت خ م] (فَا. مِنْ تَاخَمَ). ""بَلَدٌ مُتَاخِمٌ لِـ..."" : مُجَاوِرٌ لِـ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(914, 'مُتَأَدِّبٌ', 'متأدب', 'اسم فاعل', 'أدب', 'متءدب', 'متدب', 'فا. من تَأَدَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَأَدَّبَ). ""وَلَدٌ مُتَأَدِّبٌ"": مُتَخَلِّقٌ، مُهَذَّبٌ فيِ سُلُوكِهِ وَمُعَامَلاَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(915, 'مُتَأَرْجِحٌ', 'متأرجح', 'اسم فاعل', 'رجح', 'متءرجح', 'مترجح', 'فَا. مِنْ تَأَرْجَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَأَرْجَحَ). "" مُتَأَرْجِحٌ بَيْنَ مَوْقِفَيْنِ"" : مُتَرَدِّدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(916, 'مُتَأَسِّفٌ', 'متأسف', 'اسم فاعل', 'أسف', 'متءسف', 'متسف', 'فا. من تَأَسَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَأَسَّفَ). ""مُتَأَسِّفٌ عَلَى مَا حَصَلَ"" : مَنْ يَشْعُرُ بِأَسَفٍ وَنَدَمٍ عَلَى مَا بَدَرَ مِنْهُ مِنْ سُوءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(917, 'مُتَأَصِّلٌ', 'متأصل', 'اسم فاعل', 'أصل', 'متءصل', 'متصل', 'فَا. مِنْ تَأَصَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَأَصَّلَ). 1.""مُتَأَصِّلُ النَّسَبِ"" : أَصِيلُهُ. 2.""مَرَضٌ مُتَأَصِّلٌ"" : مُزْمِنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(918, 'مُتَأَكِّدٌ', 'متأكد', 'اسم فاعل', 'أكد', 'متءكد', 'متكد', 'فَا. مِنْ تَأَكَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَأَكَّدَ). ""مُتَأَكِّدٌ مِنْ أَقْوَالِهِ"" : مُتَيَقِّنٌ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(919, 'مُتَأَلِّقٌ', 'متألق', 'اسم فاعل', 'ألق', 'متءلق', 'متلق', 'فا. من تَأَلَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَأَلَّقَ). 1.""نَجْمٌ مُتَأَلِّقٌ"" : سَاطِعٌ، لاَمِعٌ. 2.""كَانَ مُتَأَلِّقاً فيِ مَجْلِسِهِ"" : بَارِزاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(920, 'مُتَآمِرٌ', 'متآمر', 'اسم فاعل', 'أمر', 'متءءمر', 'متآمر', 'فا. من تَآمَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَآمَرَ). ""رَجُلٌ مُتَآمِرٌ "" : أَيْ مَنْ يَشْتَرِكُ مَعَ طَرَفٍ ضِدَّ طَرَفٍ آخَرَ لِلإِيقَاعِ بِهِ فِي كَارِثَةٍ. ""مُتَآمِرٌ مَعَ أَعْدَاءِ البِلاَدِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(921, 'مُتَبَارِي', 'متباري', 'اسم فاعل', 'بري', 'متباري', 'متبر', 'فا. من تَبَارَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَبَارَى). ""مُتَبَارٍ مَعَ زَمِيلِهِ"" : مُتَنَافِسٌ بِدُخُولِهِ مَعَهُ فِي مُبَارَاةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(922, 'مُتَأَنِّقٌ', 'متأنق', 'اسم فاعل', 'أنق', 'متءنق', 'متنق', 'فا. من تَأَنَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَأَنَّقَ). ""مُتَأَنِّقٌ فِي مَلْبَسِهِ"" : أَنِيقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(923, 'مُتَأَنِّي', 'متأني', 'اسم فاعل', 'أني', 'متءني', 'متن', 'فَا. مِنْ تَأَنَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَأَنٍّ-مُتَأَنٍّ، الْمُتَأَنِّي، ةٌ [أ ن ي] (فَا. مِنْ تَأَنَّى). ""مُت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(924, 'تَائِهٌ', 'تائه', 'اسم فاعل', 'توه،تيه', 'تاءه', 'ته', 'فا. مِن تَاهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِن تَاهَ). ""وَلَدٌ تَائِهٌ"" : وَلَدٌ ضَالٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(925, 'توائه', 'توائه', 'اسم فاعل', '', 'تواءه', 'ته', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(926, 'تياه', 'تياه', 'اسم فاعل', '', 'تياه', 'ته', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(927, 'مُتَأَهِّبٌ', 'متأهب', 'اسم فاعل', 'أهب', 'متءهب', 'متهب', 'فَا. مِنْ تَأَهَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَأَهَّبَ). ""مُتَأَهِّبٌ لِلْعَمَلِ"" : مُسْتَعِدٌّ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(928, 'مُتَأَهِّلٌ', 'متأهل', 'اسم فاعل', 'أهل', 'متءهل', 'متهل', 'فَا. مِنْ تَأَهَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَأَهَّلَ). ""مُتَأَهِّلٌ مِنْ عَائِلَةٍ ذَاتِ نَسَبٍ وَحَسَبٍ"" : مُتَزَوِّجٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(929, 'مُتَأَوِّهٌ', 'متأوه', 'اسم فاعل', 'أوه', 'متءوه', 'مته', 'فَا. مِنْ تَأَوَّهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَأَوَّهَ). ""وَجَدَهُ مُتَأَوِّهاً فِي سَرِيرِهِ"": مُتَوَجِّعاً مُكْثِراً مِنَ الآهَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(930, 'مُتَبَادِلٌ', 'متبادل', 'اسم فاعل', 'بدل', 'متبادل', 'متبدل', 'فا. من تَبَادَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَبَادَلَ). ""الْمُتَبَادِلُونَ هُمُ الَّذِينَ يَلْتَمِسُ بَعْضُهُمُ الانْتِفَاعَ بِبَعْضٍ مُتَاجَرَةً"" : مَنْ يَتَبَادَلُ مَعَ غَيْرِهِ سِلْعَةً وَنَحْوَهَا. ""الْمُتَبَادِلُونَ ذَاتَ اليَدِ هُمُ المتَعَاوِنُونَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(931, 'مُتَبَرِّعٌ', 'متبرع', 'اسم فاعل', 'برع', 'متبرع', 'متبرع', 'فَا. مِنْ تَبَرَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَبَرَّعَ). ""مُتَبَرِّعٌ بِمَالِهِ"" : يُعْط"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(932, 'مُتَبَاطِئٌ', 'متباطئ', 'اسم فاعل', 'بطأ', 'متباطء', 'متبط', 'فا. من تَبَاطَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَبَاطَأَ). ""مُتَبَاطِئٌ فِي عَمَلِهِ"" : مُتَمَهِّلٌ، مُتَأَخِّرٌ. ""يَسِيرُ بِخَطَوَاتٍ مُتَبَاطِئَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(933, 'مُتَبَاعِدٌ', 'متباعد', 'اسم فاعل', 'بعد', 'متباعد', 'متبعد', 'فا. من تَبَاعَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَبَاعَدَ). 1.""مُتَبَاعِدٌ عَنْهُ"" : مُتَنَاءٍ. 2.""يَكْتُبُ لَهُ عَلَى فَتَرَاتٍ مُتَبَاعِدَةٍ"" : عَلَى فَتَرَاتٍ غَيْرِ مُقْتَرِبَةٍ، أَيْ تَفْصِلُ بَيْنَهَا مَسَافَةٌ زَمَنِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(934, 'مُتَبَاكِي', 'متباكي', 'اسم فاعل', 'بكي', 'متباكي', 'متبك', 'فا. من تباكَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَبَاكٍ-مُتَبَاكٍ، الْمُتَباكِي، ةٌ [ب ك ي] (فا. من تباكَى). ""جاءهُ مُتَباكِياً"" : مُتَظاهِراً بِالبُكاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(935, 'مُتَبَاهِي', 'متباهي', 'اسم فاعل', 'بهى', 'متباهي', 'متبه', 'فا. من تَبَاهَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَبَاهَى). ""مُتَبَاهٍ بِنَسَبِهِ"" : مُفْتَخِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(936, 'مُتَبَتِّلٌ', 'متبتل', 'اسم فاعل', 'بتل', 'متبتل', 'متبتل', 'فَا. مِنْ تَبَتَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَبَتَّلَ). ""مُتَبَتِّلٌ فِي زُهْدِهِ"" : مُتَعَبِّدٌ، مُتَخَشِّعٌ. ""تَعِيشُ عَيْشَ الزَّاهِدَاتِ الْمُتَبَتِّلاَتِ"" ""رَأَيْتُ فِي مَدِينَتِنَا نُوراً إِلاَهِيّاً لاَ يَعْرِفُهُ إِلاَّ العَابِدُ الْمُتَبَتِّلُ الَّذِي يَهَبُ حَيَاتَهُ إِلَى الله"". (إسحق الحسيني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(937, 'مُتَبَجِّحٌ', 'متبجح', 'اسم فاعل', 'بجح', 'متبجح', 'متبجح', 'فا. من تَبَجَّحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَبَجَّحَ). ""مُتَبَجِّحٌ بِانْتِصاراتِهِ"" : مُتَبَاهٍ، مُفْتَخِرٌ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(938, 'مُتَبَحِّرٌ', 'متبحر', 'اسم فاعل', 'بحر', 'متبحر', 'متبحر', 'فَا. مِنْ تَبَحَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَبَحَّرَ). ""مُتَبَحِّرٌ فِي عُلُومِ الدِّينِ"" : مُتَضَلِّعٌ مِنْها، مُلِمٌّ بِها، أَيْ لَهُ مَعْرِفَةٌ وَاسِعَةٌ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(939, 'مُتَبَخْتِرٌ', 'متبختر', 'اسم فاعل', 'بخر', 'متبختر', 'متبختر', 'فا. من تبختر', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '', ':لا شرح');
