INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(941, 'مُتَتَابِعٌ', 'متتابع', 'اسم فاعل', 'تبع', 'متتابع', 'متتبع', 'فَا. مِنْ تَتَابَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَتَابِعٌ-مُتَتَابِعٌ، ةٌ [ت ب ع] (فَا. مِنْ تَتَابَعَ). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(942, 'مُتَبَرِّمٌ', 'متبرم', 'اسم فاعل', 'برم', 'متبرم', 'متبرم', 'فَا. مِنْ تَبَرَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَبَرَّمَ). ""مُتَبَرِّمٌ مِنْ رَتَابَةِ حَيَاتِهِ اليَوْمِيَّةِ"" : مُتَضَجِّرٌ، أَيْ يَشْعُرُ بِاسْتِيَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(943, 'مُتَبَصِّرٌ', 'متبصر', 'اسم فاعل', 'بصر', 'متبصر', 'متبصر', 'فَا. مِنْ تَبَصَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَبَصَّرَ). ""مُتَبَصِّرٌ فِي أُمُورِهِ"" : مُتَأَمِّلٌ، مُسْتَقْصٍ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(944, 'تَابِعٌ', 'تابع', 'اسم فاعل', 'تبع', 'تابع', 'تبع', 'فا. مِنْ تَبِعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":تَوَابِعُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ تَبِعَ). 1. ""هُوَ تابِعٌ لَهُ"" : مِنْ خَدَمِهِ، مِنْ حَاشِيَتِهِ. 2.""هُوَ تَابِعٌ لِصَدِيقِهِ"" : يَسِيرُ وَرَاءهُ، يَتْبَعُهُ. 3.""الصَّحَابَةُ وَالتَّابِع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(945, 'تَوَابِعُ', 'توابع', 'اسم فاعل', '', 'توابع', 'تبع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(946, 'تبعة', 'تبعة', 'اسم فاعل', '', 'تبعة', 'تبعة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(947, 'تباع', 'تباع', 'اسم فاعل', '', 'تباع', 'تبع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(948, 'مُتَبَقِّي', 'متبقي', 'اسم فاعل', 'بقي', 'متبقي', 'متبق', 'فا. من تَبَقَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَبَقٍّ-مُتَبَقٍّ، الْمُتَبَقِّي، ةٌ [ب ق ي] (فا. من تَبَقَّى). ""الْمُتَبَقِّي مِنَ البِضَاعَةِ"" : مَا بَقِيَ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(949, 'مُتَبَلِّجٌ', 'متبلج', 'اسم فاعل', 'بلج', 'متبلج', 'متبلج', 'فَا. مِنْ تَبَلَّجَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَبَلِّجٌ-مُتَبَلِّجٌ، ةٌ [ب ل ج] (فَا. مِنْ تَبَلَّجَ). ""نُورٌ مُتَبَلِّجٌ"" : مُضِيءٌ، مُشِعٌّ. ""تَرْسُمُ خَطّاً جَدِيداً فِي لَوْحَةِ الصَّبَاحِ الْمُتَبَلِّجِ مِنْ إِشْرَاقَةِ النُّورِ"". (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(950, 'مُتَبَنِّي', 'متبني', 'اسم فاعل', 'بني', 'متبني', 'متبن', 'فا. من تَبَنَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من تَبَنَّى). 1.""مُتَبَنٍّ لِوَلَدٍ مِنَ الْمَيْتَمِ"" : أَيْ مَنْ تَبَنَّى وَلَداً وَجَعَلَهُ كَابْنِهِ. 2.""مُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(951, 'مُتَجَرِّدٌ', 'متجرد', 'اسم فاعل', 'جرد', 'متجرد', 'متجرد', 'فا. من تَجَرَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَجَرَّدَ). 1.""مُتَجَرِّدٌ فِي أَحْكَامِهِ"" : مَوْضُوعِيٌّ فِي أَحْكَامِهِ. 2.""مُتَجَرِّدٌ عَنْ ك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(952, 'مُتَثَاقِلٌ', 'متثاقل', 'اسم فاعل', 'ثقل', 'متثاقل', 'متثقل', 'فا. من تَثَاقَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَثَاقَلَ). ""سَعَى إِلَيْهِ بِخَطَوَاتٍ مُتَثَاقِلَةٍ"" : أَيْ مُتَبَاطِئَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(953, 'مُتَجَانِسٌ', 'متجانس', 'اسم فاعل', 'جنس', 'متجانس', 'متجنس', 'فا. من تَجَانَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَجَانَسَ). 1.""عَمَلٌ مُتَجَانِسٌ"" : مُتَّسِقٌ. 2.""أَفْكَارٌ مُتَجَانِسَةٌ"" : مُتَرَابِطَةٌ، مُتَمَاثِلَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(954, 'مُتَجَاوِرٌ', 'متجاور', 'اسم فاعل', 'جور', 'متجاور', 'متجر', 'فا. من تَجَاوَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَجَاوَرَ). 1.""بُيُوتٌ مُتَجَاوِرَةٌ"" : مُتَلاَصِقَةٌ. 2.""أَرَاضٍ مُتَجَاوِرَةٌ"": مُتَتاخِمَةٌ. 3.""زَوَايَا مُتَجَاوِرَةٌ"" : مُتَقَارِبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(955, 'مُتَجَاوِزٌ', 'متجاوز', 'اسم فاعل', 'جوز', 'متجاوز', 'متجز', 'فَا. مِنْ تَجَاوَزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَجَاوَزَ). ""مُتَجَاوِزٌ لِلْحُدُودِ"" : مَنْ يَتَعَدَّى الْحُدُودَ وَيَخْرُجُ عَنِ الْمَأْلُوفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(956, 'مُتَجَدِّدٌ', 'متجدد', 'اسم فاعل', 'جدد', 'متجدد', 'متجد', 'فَا. مِنْ تَجَدَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَجَدَّدَ). 1.""بِنَاءٌ مُتَجَدِّدٌ"" : أَيْ أُعِيدَ بِنَاؤُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(957, 'تَاجِرٌ', 'تاجر', 'اسم فاعل', 'تجر', 'تاجر', 'تجر', 'فا. مِنْ تَجَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":تُجَّارٌ:تَوَاجِرُ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ تَجَرَ). ""تَاجِرٌ فِي الْمَوَادِّ الغِذَائِيَّةِ"" : مَنْ يَتَعَاطَى تِجَارَتَهَا. وَهُنَاكَ : ""تَاجِرٌ بِالجُمْلَةِ"" : مَنْ يَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(958, 'تَوَاجِرُ', 'تواجر', 'اسم فاعل', '', 'تواجر', 'تجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
