INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(960, 'تجرة', 'تجرة', 'اسم فاعل', '', 'تجرة', 'تجرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(961, 'مُتَحَجِّرٌ', 'متحجر', 'اسم فاعل', 'حجر', 'متحجر', 'متحجر', 'فا. من تَحَجَّرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فا. من تَحَجَّرَ). ""لَهُ قَلْبٌ مُتَحَجِّرٌ"" : قَاسٍ. ""مُتَحَجِّرُ القَلْبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(962, 'مُتَجَسِّدٌ', 'متجسد', 'اسم فاعل', 'جسد', 'متجسد', 'متجسد', 'فا. من تَجَسَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَجَسَّدَ). ""أَمْرٌ مُت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(963, 'مُتَجَعِّدٌ', 'متجعد', 'اسم فاعل', 'جعد', 'متجعد', 'متجعد', 'فَا. مِنْ تَجَعَّدَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَجَعِّدٌ-مُتَجَعِّدٌ، ةٌ [ج ع د] (فَا. مِنْ تَجَعَّدَ). 1.""شَعْرٌ مُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(964, 'مُتَجَلِّي', 'متجلي', 'اسم فاعل', 'جلي', 'متجلي', 'متجل', 'فَا. مِنْ تَجَلَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَجَلَّى). ""كَانَ مُتَجَلِّياً لِلنَّاظِرِينَ"" : وَاضِحاً لِلْعِيَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(965, 'مُتَجَمِّدٌ', 'متجمد', 'اسم فاعل', 'جمد', 'متجمد', 'متجمد', 'فَا. مِنْ تَجَمَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَجَمِّدٌ-مُتَجَمِّدٌ، ةٌ [ج م د] (فَا. مِنْ تَجَمَّدَ). 1.""نَهْرٌ مُتَجَمِّدٌ"": مِيَاهُهُ صَارَتْ جَلِيداً، جَامِدَةً. 2.""الْمُحِيطُ الْمُتَجَمِّدُ الشَّمَالِيُّ"" : أَحَدُ الْمُحِيطَيْنِ اللَّذَيْنِ يَقَعَانِ فِي الْمِنْطْقَتَيْنِ القُطْبِيَّتَيْنِ الشَّمَالِيَّةِ وَالْجَنُوبِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(966, 'مُتَجَمِّعٌ', 'متجمع', 'اسم فاعل', 'جمع', 'متجمع', 'متجمع', 'فَا. مِنْ تَجَمَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَجَمَّعَ). ""جُمْهُورٌ مُتَجَمِّعٌ فِي السَّاحَةِ العُمُومِيَّةِ"" : مُحْتَشِدٌ، مُتَجَمْهِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(967, 'مُتَجَنِّسٌ', 'متجنس', 'اسم فاعل', 'جنس', 'متجنس', 'متجنس', 'فَا. مِنْ تَجَنَّسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَجَنَّسَ). ""صَارَ مُتَجَنِّسًا بِجِنْسِيَّةٍ أَجْنَبِيَّةٍ"" : مَنْ تَجَنَّسَ بِجِنْسِيَّةِ بِلاَدٍ أُخْرَى غَيْرِ بِلاَدِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(968, 'مُتَجَهِّمٌ', 'متجهم', 'اسم فاعل', 'جهم', 'متجهم', 'متجهم', 'فَا. مِنْ تَجَهَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَجَهَّمَ). ""مُتَجَهِّمُ الوَجْهِ"" : مُكْفَهِرُّهُ. ""وَجْهٌ مُتَجَهِّمٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(969, 'مُتَجَوِّلٌ', 'متجول', 'اسم فاعل', 'جول', 'متجول', 'متجل', 'فا. من تَجَوَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَجَوَّلَ). 1.""مُتَجَوِّلٌ فِي البِلاَدِ"" : مُتَنَقِّلٌ مِنْ مَكَانٍ إِلَى آخَرَ. 2.""تَاجِرٌ مُتَجَوِّلٌ"" : مَنْ يَنْتَقِلُ بِبَضَائِعِهِ مِنْ مَكَانٍ إِلَى آخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(970, 'مُتَحَالِفٌ', 'متحالف', 'اسم فاعل', 'حلف', 'متحالف', 'متحلف', 'فا. من تَحَالَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَحَالَفَ). ""مُتَحَالِفٌ مَعَ أَعْدَاءِ أَعْدَائِهِ"" : مُتَضَامِنٌ، مُتَعَاقِدٌ مَعَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(971, 'مُتَحَيِّرٌ', 'متحير', 'اسم فاعل', 'حير', 'متحير', 'متحر', 'فَا. مِنْ تَحَيَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَحَيَّرَ). ""مُتَحَيِّرٌ فِي أَمْرِهِ"" : مُتَرَدِّدٌ، مُنْدَهِشٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(972, 'مُتَحَدِّي', 'متحدي', 'اسم فاعل', 'حدو', 'متحدي', 'متحد', 'فَا. مِنْ تَحَدَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَحَدَّى). ""مُتَحَدٍّ لِكُلِّ الصُّعُوبَاتِ وَالعَرَاقِلِ"" : مُوَاجِهٌ لَهَا بِجُهْدٍ مُضَاعَفٍ وَعَزِيمَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(973, 'مُتَحَذْلِقٌ', 'متحذلق', 'اسم فاعل', 'حذلق', 'متحذلق', 'متحذلق', 'فَا. مِنْ تَحَذْلَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَحَذْلَقَ). ""متُحَذْلِقٌ فِي كَلاَمِهِ"" : مُتَصَنِّعٌ، مُتَكَلِّفٌ الْحِذْقَ والقُدْرَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(974, 'مُتَحَرِّكٌ', 'متحرك', 'اسم فاعل', 'حرك', 'متحرك', 'متحرك', 'فا. مِنْ تَحَرَّكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِنْ تَحَرَّكَ). 1.""عُودٌ مُتَحَرِّكٌ"" : مُتَمَايِلٌ. 2.""أَفْلاَمُ الرُّسُومِ أَوِ الصُّوَرِ الْمُتَحَرِّكَةِ"" : الرُّسُومِ الَّتِي يَتِمُّ تَحْرِيكُهَا بِتِقْنِيَّةٍ مَّا، وَهِيَ خَاصَّةٌ بِأَفْلاَمِ الصِّغَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(975, 'مُتَحَضِّرٌ', 'متحضر', 'اسم فاعل', 'حضر', 'متحضر', 'متحضر', 'فا. من تَحَضَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَحَضَّرَ). ""رَجُلٌ مُتَحَضِّرٌ"" : مُتَمَدِّنٌ، أَيْ مِنْ أَهْلِ الْحَضَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(976, 'مُتَحَفِّزٌ', 'متحفز', 'اسم فاعل', 'حفز', 'متحفز', 'متحفز', 'فا. من تَحَفَّزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَحَفَّزَ). ""مُتَحَفِّزٌ لِلانْقِضَاضِ عَلَى غَرِيمِهِ"" : مُتَوَثِّبٌ. ""كَانَتْ تَنْظُرُ إِلَيْهِ مُتَحَفِّزَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(977, 'مُتَحَفِّظٌ', 'متحفظ', 'اسم فاعل', 'حفظ', 'متحفظ', 'متحفظ', 'فا. من تَحَفَّظَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَحَفَّظَ). 1.""مُتَحَفِّظٌ مِنَ الْمَوَاقِفِ الْمُعَبَّرِ عَنْهَا"" : أَيْ مُتَّخِذٌ مَوْقِفَ الْحَذَرِ وَالاحْتِرَاسِ وَغَيْرُ مُوَافِقٍ عَلَيْهَا. 2.""هُوَ غَيْرُ مُتَحَفِّظٍ فِي كَلاَمِهِ"" : مَنْ يُبْدِي آرَاءهُ وَيَجْهَرُ بِهَا دُونَ احْتِرَاسٍ أَوْ حَذَرٍ أَوْ تَرَدُّدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(978, 'مُتَحَكِّمٌ', 'متحكم', 'اسم فاعل', 'حكم', 'متحكم', 'متحكم', 'فا. من تَحَكَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَحَكَّمَ). 1.""مُتَحَكِّمٌ فِي أُمُورِهِ"" : مُتَمَكِّنٌ مِنْهَا . 2.""مُتَحَكِّمٌ فِي أُمُورِ النَّاسِ"" : مُتَصَرِّفٌ فِيهَا وَفْقَ مَشِيئَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(979, 'مُتَحَلِّي', 'متحلي', 'اسم فاعل', 'حلي', 'متحلي', 'متحل', 'فَا. مِنْ تَحَلَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَحَلَّى). 1.""كَانَتْ مُتَحَلِّيَةً بِلِبَاسٍ جَمِيلٍ"" : مُتَزَيِّنَةً. 2.""رَجُلٌ مُتَحَلٍّ بِالصَّبْرِ"" : مُتَّصِفٌ. ""كَانَ مُتَحَلِّياً بِأَجْمَلِ مَا يَتَحَلَّى بِهِ مَخْلُوقٌ فِي هَذِهِ الْحَيَاةِ"". (إسحق الحسيني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(980, 'مُتَحَمِّسٌ', 'متحمس', 'اسم فاعل', 'حمس', 'متحمس', 'متحمس', 'فا. من تَحَمَّسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَحَمَّسَ). ""مُتَحَمِّسٌ لِعَمَلِهِ الجَدِيدِ"" : الْمُنْدَفِعُ إِلَيْهِ مَعَ اشْتِدَادِ الرَّغْبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(981, 'مُتَدَلِّي', 'متدلي', 'اسم فاعل', 'دلي', 'متدلي', 'متدل', 'فَا. مِنْ تَدَلَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَدَلٍّ-مُتَدَلٍّ، الْمُتَدَلِّي، ةٌ [د ل ي] (فَا. مِنْ تَدَلَّى). عُنْقُودٌ مُتَدَلٍّ"" : مُعَلَّقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(982, 'مُتَحَيِّزٌ', 'متحيز', 'اسم فاعل', 'حيز', 'متحيز', 'متحز', 'فَا. مِنْ تَحَيَّزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَحَيَّزَ). ""مُتَحَيِّزٌ لِصَاحِبِهِ"" : الْمُحَابِي لَهُ يُقَدِّمُهُ عَلَى غَيْرِهِ حَتَّى وَلَوْ لَمْ يَكُنْ أَهْلاً لِذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(983, 'مُتَخَبِّطٌ', 'متخبط', 'اسم فاعل', 'خبط', 'متخبط', 'متخبط', 'فا. من تَخَبَّطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَخَبَّطَ). ""مُتَخَبِّطٌ فِي عَمَلِهِ"" : الْمُتَصَرِّفُ فِيهِ بِعَشْوَائِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(984, 'مُتَخَرِّجٌ', 'متخرج', 'اسم فاعل', 'خرج', 'متخرج', 'متخرج', 'فا. من تَخَرَّجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَخَرَّجَ). ""مُتَخَرِّجٌ مِنْ مَعْهَدِ كذا"" : أَيْ تَلَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(985, 'مُتَخَشِّعٌ', 'متخشع', 'اسم فاعل', 'خشع', 'متخشع', 'متخشع', 'فَا. مِنْ تَخَشَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَخَشَّعَ). ""عَابِدٌ مُتَخَشِّعٌ"" : مُتَضَرِّعٌ، مُتَبَتِّلٌ. ""تَرْفَعُ يَدَهَا إِلَى السَّمَاءِ ضَارِعَةً مُتَخَشِّعَةً تَسْأَلُ الله"". (م. ل. المنفلوطي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(986, 'مُتَخَصِّصٌ', 'متخصص', 'اسم فاعل', 'خصص', 'متخصص', 'متخص', 'فَا. مِنْ تَخَصَّصَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَخَصَّصَ). ""بَاحِثٌ مُتَخَصِّصٌ فِي عِلْمِ كَذا"" : مَنْ يَكُونُ اخْتِصَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(987, 'مُتَدَاخِلٌ', 'متداخل', 'اسم فاعل', 'دخل', 'متداخل', 'متدخل', 'فَا. مِنْ تَدَاخَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَدَاخِلٌ-مُتَدَاخِلٌ، ةٌ [د خ ل] (فَا. مِنْ تَدَاخَلَ). ""أَمْرٌ مُتَدَاخِلٌ"" : مُتَشَابِكٌ. ""قَضَايَا مُتَدَاخِلَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(988, 'مُتَدَثِّرٌ', 'متدثر', 'اسم فاعل', 'دثر', 'متدثر', 'متدثر', 'فا. من تَدَثَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَدَثَّرَ). ""مُتَدَثِّرٌ بِغِطَاءٍ مِنْ صُوفٍ"" : مُتَلَفِّفٌ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(989, 'مُتَدَحْرِجٌ', 'متدحرج', 'اسم فاعل', 'دحرج', 'متدحرج', 'متدحرج', 'فَا. مِنْ تَدَحْرَجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَدَحْرَجَ). ""أَقْبَلَ مُتَدَحْرِجاً"" : مُنْقَلِباً بِالتَّتَابُعِ، مُنْحَدِراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(990, 'مُتَدَفِّقٌ', 'متدفق', 'اسم فاعل', 'دفق', 'متدفق', 'متدفق', 'فَا. مِنْ تَدَفَّقَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَدَفَّقَ). 1.""مَاءُ مُتَدَفِّقٌ مِنَ الجَبَلِ"" : مُتَصَبِّبٌ. 2.""عَاطِفَةٌ مُتَدَفِّقَةٌ بِالْحُبِّ الكَبِيرِ"" : فَائِضَةٌ، طَافِحَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(991, 'مُتَدَيِّنٌ', 'متدين', 'اسم فاعل', 'دين', 'متدين', 'متدن', 'فَا. مِنْ تَدَيَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَدَيَّنَ). ""رَجُلٌ مُتَدَيِّنٌ"" : مُتَعَبِّدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(992, 'مُتَذَبْذِبٌ', 'متذبذب', 'اسم فاعل', 'ذبذب', 'متذبذب', 'متذبذب', 'فَا. مِنْ تَذَبْذَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَذَبْذَبَ). ""إِنَّهُ مُتَذَبْذِبٌ لاَ قَرَارَ لَهُ"" : مُتَأَرْجِحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(993, 'مُتَذَرِّعٌ', 'متذرع', 'اسم فاعل', 'ذرع', 'متذرع', 'متذرع', 'فَا. مِنْ تَذَرَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَذَرَّعَ). ""مُتَذَرِّعٌ بِحُجَجٍ وَاهِيَةٍ"" : مُتَعَلِّلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(994, 'مُتَذَكِّرٌ', 'متذكر', 'اسم فاعل', 'ذكر', 'متذكر', 'متذكر', 'فَا. مِنْ تَذَكَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَذَكَّرَ). ""لاَ يَزَالُ مُتَذَكِّراً أَيَّامَ الصِّبَا"" : مُسْتَحْضِراً أَيَّامَهَا فِي ذَاكِرَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(995, 'مُتَذَلِّلٌ', 'متذلل', 'اسم فاعل', 'ذلل', 'متذلل', 'متذل', 'فَا. مِنْ تَذَلَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَذَلَّلَ). ""مَالِي أَرَاهُ مُتَذَلِّلاً"" : مُسْتَكِيناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(996, 'مُتَذَمِّرٌ', 'متذمر', 'اسم فاعل', 'ذمر', 'متذمر', 'متذمر', 'فَا. مِنْ تَذَمَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَذَمَّرَ). ""مُتَذَمِّرٌ مِنَ الأَوْضَاعِ السَّيِّئَةِ"" : سَاخِطٌ، نَاقِمٌ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(997, 'مُتَرَابِطٌ', 'مترابط', 'اسم فاعل', 'ربط', 'مترابط', 'متربط', 'فَا. مِنْ تَرَابَطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَرَابَطَ). ""حُقُولٌ مُتَرَابِطَةُ الأَطْرَافِ"" : مُتَّصِلَةُ الأَطْرَافِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(998, 'مُتَرَاخِي', 'متراخي', 'اسم فاعل', 'رخو', 'متراخي', 'مترخ', 'فَا. مِنْ تَرَاخَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَرَاخَى). ""أَرَاهُ مُتَرَاخِياً فِي عَمَلِهِ"" : مُتَهَاوِناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(999, 'مُتَرَادِفٌ', 'مترادف', 'اسم فاعل', 'ردف', 'مترادف', 'متردف', 'فَا. مِنْ تَرَادَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَرَادَفَ). ""الأَلْفَاظُ الْمُتَرَادِفَةُ"" : أَلْفَاظٌ مُتَطَابِقَةٌ أَوْ مُتَقَارِبَةُ الْمَعْنَى، أَيْ لَهَا الْمَعْنَى نَفْسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1000, 'مُتَرَاصٌّ', 'متراص', 'اسم فاعل', 'رصص', 'متراص', 'مترص', 'فَا. مِنْ تَرَاصَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَرَاصَّ). ""وَقَفُوا فِي صُفُوفٍ مُتَرَاصَّةٍ"" : مُنْضَمَّة، بَعْضُهَا إِلَى بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1001, 'مُتَرَامِي', 'مترامي', 'اسم فاعل', 'رمي', 'مترامي', 'مترم', 'فَا. مِنْ تَرَامَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَرَامٍ-مُتَرَامٍ، الْمُتَرَامِي، ةٌ [ر م ي] (فَا. مِنْ تَرَامَى). ""أَرَاضٍ مُتَرامِيَةُ الأَطْرَافِ"" : شَاسِعَةٌ، فَسِيحَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1002, 'مُتَرَبِّصٌ', 'متربص', 'اسم فاعل', 'ربص', 'متربص', 'متربص', 'فا. من تَرَبَّصَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَرَبَّصَ). ""مُتَرَبِّصٌ بِعَدُوِّهِ"" : مُرَاقِبٌ وَهُوَ فِي حَالةِ تَأَهُبٍّ، مُتَرَصِّدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1003, 'مُتَرَبِّعٌ', 'متربع', 'اسم فاعل', 'ربع', 'متربع', 'متربع', 'فَا. مِنْ تَرَبَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَرَبَّعَ). 1.""جَلَسَ مُتَرَبِّعاً"" : ثاَنِياً قَدَمَيْهِ تَحْتَ فَخِذَيْهِ مخُاَلِفاً لَهُمَا. 2.""مُتَرَبِّعٌ عَلَى عَرْشِ أَسْلاَفِهِ"" : جَالِسٌ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1004, 'مُتَرْجِمٌ', 'مترجم', 'اسم فاعل', 'ترجم', 'مترجم', 'مترجم', 'فَا. مِنْ تَرْجَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَرْجَمَ). ""مُتَرْجِمٌ جَيِّدٌ يُحَافِظُ عَلَى نَقْلِ النَّصِّ بِأَمَانَةٍ"" : مَنْ يَنْقُلُ نَصّاً مِنْ لُغَةٍ إِلَى لُغَةٍ أُخْرَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1005, 'مُتَرَدِّدٌ', 'متردد', 'اسم فاعل', 'ردد', 'متردد', 'مترد', 'فَا. مِنْ تَرَدَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَرَدَّدَ). ""مُتَرَدِّدٌ فِي مَوْقِفِهِ أَوفِي آرَائِهِ"" : مُتَحَيِّرٌ، مُتَأَرْجِحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1006, 'مُتَرَسِّبٌ', 'مترسب', 'اسم فاعل', 'رسب', 'مترسب', 'مترسب', 'فَا. مِنْ تَرَسَّبَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَرَسِّبٌ-مُتَرَسِّبٌ، ةٌ [ر س ب] (فَا. مِنْ تَرَسَّبَ). ""بَقَايَا مُتَرَسِّبَةٌ فِي قَعْرِ الوَادِي"" : بَقَايَا مِنْ جُسَيْمَاتِ الصُّخُورِ وَالرَّمْلِ وَالطِّينِ مُتَرَاكِمَةٌ بَعْضُهَا فَوْقَ بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1007, 'مُتَرَشِّحٌ', 'مترشح', 'اسم فاعل', 'رشح', 'مترشح', 'مترشح', 'فا. من تَرَشَّحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَرَشِّحٌ-مُتَرَشِّحٌ [رش ح] (فا. من تَرَشَّحَ). 1.""مَاءٌ مُتَرَشِّحٌ"": سَائِلٌ. ""عَرَقٌ مُتَرَشِّحٌ"" ""إِنَاءٌ مُتَرَشِّحٌ بِمَا فِيهِ"". 2.""مُتَرَشِّحٌ للانْتِخَابَاتِ"" : أَي مُتَقَدِّمٌ لَهَا لِيَخْتَارَهُ النَّاخِبُونَ مُمَثِّلاً لـهُمْ . 3.""مُتَرَشِّحٌ للأَمْرِ"" : مُتَهَيِّءٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1008, 'مُتَرَصِّدٌ', 'مترصد', 'اسم فاعل', 'رصد', 'مترصد', 'مترصد', 'فَا. مِنْ تَرَصَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَرَصَّدَ). ""مُتَرَصِّدٌ عَدُوَّهُ"" : مُرَاقِبٌ لَهُ، مُتَرَبِّصٌ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1009, 'مُتَرَفِّعٌ', 'مترفع', 'اسم فاعل', 'رفع', 'مترفع', 'مترفع', 'فَا. مِنْ تَرَفَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَرَفَّعَ). ""مُتَرَفِّعٌ عَنْ صَغَائِرِ الأُمُورِ"" : مُتَعَالٍ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1010, 'مُتَرَقْرِقٌ', 'مترقرق', 'اسم فاعل', 'رقرق', 'مترقرق', 'مترقرق', 'فَا. مِنْ تَرَقْرَقَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَرَقْرِقٌ-مُتَرَقْرِقٌ، ةٌ [ر ق ر ق] (فَا. مِنْ تَرَقْرَقَ). ""مِيَاهٌ صَافِيَةٌ مُتَرَقْرِقَةٌ عَلَى قِيعَانِ الْحَصَى الْمُلَوَّنَةِ"" : مُتَلَأْلِئَةٌ، أَيْ جَرْيُهَا جَرْياً هَادِئاً سَهْلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1011, 'مُتَرَنِّحٌ', 'مترنح', 'اسم فاعل', 'رنح', 'مترنح', 'مترنح', 'فَا. مِنْ تَرَنَّحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَرَنَّحَ). ""سِكِّيرٌ مُتَرَنِّحٌ"" : يَمْشِي وَهُوَ يَتَمَايَلُ يَمْنَةً وَيَسْرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1012, 'مُتَرَهِّلٌ', 'مترهل', 'اسم فاعل', 'رهل', 'مترهل', 'مترهل', 'فَا. مِنْ تَرَهَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَرَهَّلَ). ""مُتَرَهِّلُ الجِسْمِ"" : هَشُّ الجِسْمِ، أَيْ عَضَلاَتُهُ مُتَرَاخِيَةٌ. ""رَفَعَ يَدَهُ إِلَى وَجْهِهِ الْمُكْتَنِزِ الْمُتَرَهِّلِ وَرَاحَ يَفْرُكهُ دُونَ انْقِطَاعٍ"". (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1013, 'مُتَزَايِدٌ', 'متزايد', 'اسم فاعل', 'زيد', 'متزايد', 'متزد', 'فا. من تَزَايَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَزَايِدٌ-مُتَزَايِدٌ، ةٌ [ز ي د] (فا. من تَزَايَدَ). ""خَيْرٌ مُتَزَايِدٌ"" : مُتَكَاثِرٌ، مُتَضَاعِفٌ. ""عَلَى نَحْوٍ مُتَزَايِدٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1014, 'مُتَزَحْلِقٌ', 'متزحلق', 'اسم فاعل', 'زحلق', 'متزحلق', 'متزحلق', 'فَا. مِنْ تَزَحْلَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَزَحْلَقَ). ""مُتَزَحْلِقٌ عَلَى الجَلِيدِ"" : مُتَزَلِّجٌ، مَنْ يَتَزَحْلَقُ عَلَى..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1015, 'مُتَزَعْزِعٌ', 'متزعزع', 'اسم فاعل', 'زعزع', 'متزعزع', 'متزعزع', 'فَا. مِنْ تَزَعْزَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَزَعْزَعَ). ""إِيمَانُهُ مُتَزَعْزِعٌ"" : غَيْرُ قَارٍّ عَلَى شَيْءٍ مُحَدَّدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1016, 'مُتَزَلِّجٌ', 'متزلج', 'اسم فاعل', 'زلج', 'متزلج', 'متزلج', 'فَا. مِنْ تَزَلَّجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَزَلَّجَ). ""مُتَزَلِّجٌ بَارِعٌ"" : مَنْ يَتَزَلَّجُ عَلَى الثَّلْجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1017, 'مُتَزَلِّفٌ', 'متزلف', 'اسم فاعل', 'زلف', 'متزلف', 'متزلف', 'فَا. مِنْ تَزَلَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَزَلَّفَ). ""أَرَاهُ فِي كُلِّ مَحْفِلٍ مُتَزَلِّفاً لِأَسْيَادِهِ"" : مُتَمَلِّقاً، أَيْ مَنْ يُبْدِي بِلِسَانِهِ مِنَ الْحُبِّ وَالوُدِّ مَا لاَ يُضْمِرهُ فِي قَلْبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1018, 'مُتَزَمِّتٌ', 'متزمت', 'اسم فاعل', 'زمت', 'متزمت', 'متزمت', 'فَا. مِنْ تَزَمَّتَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَزَمَّتَ). ""مُتَزَمِّتٌ فِي مَوْقِفِهِ"" : مَنْ لاَ يَخْرُجُ عَنْ عَادَاتِهِ الْمَأْلُوفَةِ وَالْمُتَوَارَثَةِ وَيَتَعَصَّبُ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1019, 'مُتَزَهِّدٌ', 'متزهد', 'اسم فاعل', 'زهد', 'متزهد', 'متزهد', 'فَا. مِنْ تَزَهَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَزَهَّدَ). ""مُتَزَهِّدٌ فِي أُمُورِ الدُّنْيَا"" : مَنْ يَتْرُكُ أُمُورَ الدُّنْيَا لِلْعبِاَدَةِ وَالنُّسُكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1020, 'مُتَزَوِّجٌ', 'متزوج', 'اسم فاعل', 'زوج', 'متزوج', 'متزج', 'فَا. مِنْ تَزَوَّجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَزَوَّجَ). ""مُتَزَوِّجٌ بِابْنَةِ عَمِّهِ"" : مُتَأَهِّلٌ بِهَا، أَيِ اتَّخَذَهَا زَوْجَةً لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1021, 'مُتَزَيِّنٌ', 'متزين', 'اسم فاعل', 'زين', 'متزين', 'متزن', 'فَا. مِنْ تَزَيَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَزَيَّنَ). ""كَانَ مُتَزَيِّناً بِأَبْهَى الْمَلاَبِسِ"" : مُرْتَدِياً مَلاَبِسَ ذَاتَ جَمَالٍ وَأَنَاقَةٍ . ""كَانَتِ الأَرْوَاحُ تَتَراَءىَ لَنَا كَأَنَّهَا مُتَزَيِّنَةٌ بِأَحْسَنِ زِينَةٍ"" (إسحق الحسيني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1022, 'مُتَسَارِعٌ', 'متسارع', 'اسم فاعل', 'سرع', 'متسارع', 'متسرع', 'فَا. مِنْ تَسَارَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَسَارَعَ). ""يَمْشِي مُتَسَارِعَ الخُطَى"" : يَمْشِي بِخُطىً سَرِيعَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1023, 'مُتَسَاقِطٌ', 'متساقط', 'اسم فاعل', 'سقط', 'متساقط', 'متسقط', 'فَا. مِنْ تَسَاقَطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَسَاقَطَ). 1.""مُتَسَاقِطٌ فِي مَطْلَبِهِ"" : مَنْ يُلْقِي بِنَفْسِهِ طَلَباً لِلنَّجَاةِ أَوْ إِنْقَاذاً لَها مِنْ أَزْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1024, 'مُتَسَامِحٌ', 'متسامح', 'اسم فاعل', 'سمح', 'متسامح', 'متسمح', 'فَا. مِنْ تَسَامَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَسَامَحَ). ""مُتَسَامِحٌ مَعَ أَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1025, 'مُتَسَاهِلٌ', 'متساهل', 'اسم فاعل', 'سهل', 'متساهل', 'متسهل', 'فَا. مِنْ تَسَاهَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَسَاهَلَ). ""كَانَ مُتَسَاهِلاً مَعَهُ"" : أَيْ لَيِّنَ الْجَانِبِ، سَهْلَ الْمِرَاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1026, 'مُتَسَاوِي', 'متساوي', 'اسم فاعل', 'سوي', 'متساوي', 'متس', 'فَا. مِنْ تَسَاوَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَسَاوَى). 1.""مُتَسَاوٍ مَعَ زَمِيلِهِ"" : مُتَعَادِلٌ مُتَكَافِئٌ. ""يُولَدُ جَمِيعُ النَّاسِ أَحْرَاراً مُتَسَاوِينَ فِي الكَرَامَةِ وَالْحُق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1027, 'مُتَسَبِّبٌ', 'متسبب', 'اسم فاعل', 'سبب', 'متسبب', 'متسب', 'فَا. مِنْ تَسَبَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَسَبَّبَ). 1.""كَانَ هُوَ الْمُتَسَبِّبُ فِي كُلِّ مَا حَدَثَ"" : مَنْ كَانَ السَّبَبَ فِي حُدُوثِ مَا حَدَثَ. 2.""مُتَسَبِّبٌ فِي تِجَارَةِ الأَثْوَابِ البَالِيَةِ"" : مَنْ يَتَعَاطَى تِجَارَةً زَهِيدَةً يُحَاوِلُ أَنْ تَكُونَ سَبَبَ رِزْقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1028, 'مُتَسَرْبِلٌ', 'متسربل', 'اسم فاعل', 'سربل', 'متسربل', 'متسربل', 'فَا. مِنْ تَسَرْبَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَسَرْبَلَ). ""مُتَسَرْبِلٌ فِي حُلَّةِ العُرْسِ"" : لاَبِسٌ السِّرْبَالَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1029, 'مُتَسَرِّعٌ', 'متسرع', 'اسم فاعل', 'سرع', 'متسرع', 'متسرع', 'فَا. مِنْ تَسَرَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَسَرَّعَ). ""مُتَسَرِّعٌ فِي أَحْكَامِهِ"" : مَنْ يُصْدِرُ أَحْكَاماً بِلاَ تَفْكِيرٍ وَلاَ رَوِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1030, 'تَاسِعٌ', 'تاسع', 'اسم فاعل', 'تسع', 'تاسع', 'تسع', 'فا. مِنْ تَسَعَ', '', 'Ta', 'مفرد', 'DnT', '', '', '', '', '', '', '', '', '', '', '', '"تَاسِعٌ-تَاسِعٌ، ةٌ [ت س ع] (فا. مِنْ تَسَعَ). 1. : عَدَدٌ يَدُلُّ عَلَى التَّرْتِيبِ، وَيَكُونُ مَعْدُودُهُ مُذَكَّراً : ""هُوَ التَّاسِعُ فِي الفَصْلِ"" : أَيْ مَنْ كَانَتْ رُتْبَتُهُ بَيْنَ الثَّامِنِ والعَاشِرِ، وَيُعْرَبُ نَعْتاً فِي المِثَالِ التالِي : ""وَصَلَ الفَائِزُ التَّاسِعُ"" وَإِذَا لَمْ يُذْكَرْ مَعْدُودُهُ: ""وَصَلَ التَّاسِعُ"" يُعْرَبُ فَاعِلَ وَصَلَ، وَإِذَا قُلْتَ : ""كَلَّمْتُ التَّاسِعَ"" يُعْرَبُ مَفْعُولاً بِهِ، وَيُعْرَبُ حَسَبَ مَوْقِعِهِ فِي الجُمْلَةِ: ""التَّاسِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1031, 'تواسع', 'تواسع', 'اسم فاعل', '', 'تواسع', 'تسع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1032, 'مُتَسَكِّعٌ', 'متسكع', 'اسم فاعل', 'سكع', 'متسكع', 'متسكع', 'فَا. مِنْ تَسَكَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَسَكَّعَ). ""مُتَسَكِّعٌ فِي الأَزِقَّةِ"" : مَنْ يَتَجَوَّلُ فِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1033, 'مُتَسَلْسِلٌ', 'متسلسل', 'اسم فاعل', 'سلسل', 'متسلسل', 'متسلسل', 'فَا. مِنْ تَسَلْسَلَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَسَلْسَلَ). 1.""الرَّقْمُ الْمُتَسَلْسِلُ"" : الْمُتَتَابِعُ، الْمُتَوَالِي. 2.""فِلْمٌ مُتَسَلْسِلٌ"" : فِلْمٌ يُعْرَضُ عَلَى حَلَقَاتٍ. ""رِوَايَةٌ مُتَسَلْسِلَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1034, 'مُتَسَلِّطٌ', 'متسلط', 'اسم فاعل', 'سلط', 'متسلط', 'متسلط', 'فَا. مِنْ تَسَلَّطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَسَلَّطَ). 1.""حَاكِمٌ مُتَسَلِّطٌ"" : مُسْتَبِدٌّ. 2.""خَاطَبَهُ بِلَهْجَةٍ مُتَسَلِّطَةٍ"" : بِلَهْجَةٍ آمِرَةٍ، مُسْتَبِدَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1035, 'مُتَسَلِّقٌ', 'متسلق', 'اسم فاعل', 'سلق', 'متسلق', 'متسلق', 'فَا. مِنْ تَسَلَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَسَلَّقَ). 1.""مُتَسَلِّقُ الجِبَالِ"" : مَنْ يَتَسَلَّقُهَا. 2.""رَجُلٌ مُتَسَلِّقٌ"" : مَنْ يُحَاوِلُ أَنْ يَرْتَقِيَ مَنَاصِبَ بِسُرْعَةٍ دُونَ اسْتِحْقَاقٍ. 3.""مُتَسَلِّقَاتٌ"" (حو) : رُتْبَةٌ مِنَ الطُّيُورِ الجَوَاثِمِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1036, 'مُتَسَمِّرٌ', 'متسمر', 'اسم فاعل', 'سمر', 'متسمر', 'متسمر', 'فَا. مِنْ تَسَمَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَسَمَّرَ). "" وَقَفَ مُتَسَمِّرًا لاَ يَجِدُ مَهْرَباً"" : وَقَفَ جَامِدًا فِي مَكَانِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1037, 'مُتَسَوِّلٌ', 'متسول', 'اسم فاعل', 'سول', 'متسول', 'متسل', 'فَا. مِنْ تَسَوَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَسَوَّلَ). ""وَقَفَ الْمُتَسَوِّلُ أَمَامَ البَابِ"" : مَنْ يَسْتَجْدِي النَّاسَ عَطَاءً. ""لَمْ تَعُدْ فِي أَوَاخِرِ الخَرِيفِ حَشَائِشُ وَلاَ فُرُوضٌ وَلاَ أَغْطِيَةٌ لِمُتَسَوِّلٍ"". (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1038, 'مُتَشَائِمٌ', 'متشائم', 'اسم فاعل', 'شأم', 'متشاءم', 'متشم', 'فَا. مِنْ تَشَاءمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَشَاءمَ). ""مُتَشَائِمٌ مِنْ كُلِّ شَيْءٍ"" : الْمُتَطَيِّرُ، مَنْ يَرَى كُلَّ شَيْءٍ فِي الدُّنْيَا سَوَاداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1039, 'مُتَشَابِهٌ', 'متشابه', 'اسم فاعل', 'شبه', 'متشابه', 'متشبه', 'فَا. مِنْ تَشَابَهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَشَابَهَ). 1.""شَخْصَانِ مُتَشَابِهَانِ"" : مُتَنَاظِرَانِ، مُتَمَاثِلاَنِ. ""كَانَتِ الأَجِنَّةُ فِي أَوَّلِ خُرُوجِهَا مُتَشَابِهَةً تَشَابُهَ أَغْلِفَتِهَا"". (إسحق الحسيني). 2.آل عمران آية 7مِنْهُ آيَاتٌ مُحْكَمَاتٌ هُنَّ أُمُّ الكِتَابِ وَأُخَر مُتَشَابِهَاتٌ (قرآن) : أَيْ مُلْتَبِسَةٌ غَيْرُ وَاضِحَةٍ. 3.""مُثَلَّث"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1040, 'مُتَشَامِخٌ', 'متشامخ', 'اسم فاعل', 'شمخ', 'متشامخ', 'متشمخ', 'فَا. مِنْ تَشَامَخَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَشَامَخَ). ""مُتَشَامِخٌ فِي عَلْيَائِهِ"" : مُتَغَطْرِسٌ، مُتَعَاظِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1041, 'مُتَشَبِّثٌ', 'متشبث', 'اسم فاعل', 'شبث', 'متشبث', 'متشبث', 'فَا. مِنْ تَشَبَّثَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَشَبَّثَ). ""مُتَشَبِّثٌ بِرَأْيِهِ"" : مَنْ يَبْقَى عَلَى رَأْيِهِ وَلاَ يَحِيدُ عَنْهُ، العَنِيدُ، الْمُتَصَلِّبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1042, 'مُتَشَدِّدٌ', 'متشدد', 'اسم فاعل', 'شدد', 'متشدد', 'متشد', 'فَا. مِنْ تَشَدَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَشَدَّدَ). ""مُتَشَدِّدٌ مَعَ طُلاَّبِهِ"" : مَنْ يَكُونُ قَاسِياً غَيْرَ مُتَسَامِحٍ. ""مُتَشَدِّدٌ فِي أَحْكَامِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1043, 'مُتَشَدِّقٌ', 'متشدق', 'اسم فاعل', 'شدق', 'متشدق', 'متشدق', 'فَا. مِنْ تَشَدَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَشَدَّقَ). ""مُتَشَدِّقٌ فِي كَلاَمِهِ"" : الفَاتِحُ فَاهُ وَالْمُتَبَجِّحُ فِي القَوْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1044, 'مُتَشَرِّدٌ', 'متشرد', 'اسم فاعل', 'شرد', 'متشرد', 'متشرد', 'فَا. مِنْ تَشَرَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَشَرَّدَ). ""يَعِيشُ مُتَشَرِّداً"" : مَنْ يَعِيشُ بِلاَ مَأْوَى، مُتَسَكِّعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1045, 'مُتَشَعِّبٌ', 'متشعب', 'اسم فاعل', 'شعب', 'متشعب', 'متشعب', 'فَا. مِنْ تَشَعَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَشَعَّبَ). 1.""نَهْرٌ مُتَشَعِّبٌ"" : أَنْهَارٌ مُتَفَرِّقَةٌ. 2.""أَغْصَانٌ مُتَشَعِّبَةٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1046, 'مُتَشَنِّجٌ', 'متشنج', 'اسم فاعل', 'شنج', 'متشنج', 'متشنج', 'فَا. مِنْ تَشَنَّجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَشَنَّجَ). ""مُتَشَنِّجُ الأَعْصَابِ"" : هُوَ فِي حَالَةٍ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1047, 'مُتَشَوِّقٌ', 'متشوق', 'اسم فاعل', 'شوق', 'متشوق', 'متشق', 'فَا. مِنْ تَشَوَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَشَوَّقَ). ""مُتَشَوِّقٌ لِرُؤْيَةِ أَهْلِهِ"" : مَنْ يَشْعُرُ بِعَاطِفَةِ الشَّوْقِ الشَّدِيدِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1048, 'مُتَصَبِّبٌ', 'متصبب', 'اسم فاعل', 'صبب', 'متصبب', 'متصب', 'فَا. مِنْ تَصَبَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَصَبَّبَ). ""وَصَلَ مُتَصَبِّباً بِالعَرَق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1049, 'مُتَصَدِّعٌ', 'متصدع', 'اسم فاعل', 'صدع', 'متصدع', 'متصدع', 'فَا. مِنْ تَصَدَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَصَدَّعَ). ""حَائِطٌ مُتَصَدِّعٌ"" : الْح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1050, 'مُتَصَرِّفٌ', 'متصرف', 'اسم فاعل', 'صرف', 'متصرف', 'متصرف', 'فَا. مِنْ تَصَرَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَصَرَّفَ). 1.""مُتَصَرِّفٌ فِي مَالِ غَيْرِهِ"" : الْمُتَحَكِّمُ فِيهِ حَسَبَ أَهْوَائِهِ. 2.""مُتَصَرِّفُ الْمُتَصَرِّفِيَّةِ"" : حَاكِمُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1051, 'مُصَرِّفٌ', 'مصرف', 'اسم فاعل', 'صرف', 'مصرف', 'مصرف', 'فَا. مِنْ صَرَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1052, 'مُتَصَلِّبٌ', 'متصلب', 'اسم فاعل', 'صلب', 'متصلب', 'متصلب', 'فَا. مِنْ تَصَلَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَصَلَّبَ). ""مُتَصَلِّبٌ فِي مَوَاقِفِهِ"" : مَنْ كَانَ مُتَشَدِّدًا عَنِيداً فِي مَوَاقِفِهِ. ""رَأْيٌ مُتَصَلِّبٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1053, 'مُتَصَنِّعٌ', 'متصنع', 'اسم فاعل', 'صنع', 'متصنع', 'متصنع', 'فَا. مِنْ تَصَنَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَصَنَّعَ). 1.""مُتَصَنِّعٌ فِي كَلاَمِهِ"" : مُتَكَلِّفٌ فِي كَلاَمِه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1054, 'مُتَضَارِبٌ', 'متضارب', 'اسم فاعل', 'ضرب', 'متضارب', 'متضرب', 'فَا. مِنْ تَضَارَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَضَارَبَ). ""عَبَّرَ عَنْ رَأْيٍ مُتَضَارِبٍ"" : مُتَنَاقِضٍ، أَوْ بِهِ كَثِيرٌ مِنَ الغُمُوضِ وَالتَّنَاقُضِ وَالالْتِبَاسِ. ""مُتَضَارِبٌ فِي رَأْيِهِ"" ""قَدَّمَ أَفْكَاراً مُتَضَارِبَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1055, 'مُتَضَافِرٌ', 'متضافر', 'اسم فاعل', 'ضفر', 'متضافر', 'متضفر', 'فَا. مِنْ تَضَافَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَضَافَرَ). 1.""كَانَ مُتَضَافِراً مَعَهُ"" : مُتَعَاوِناً، مُسَاعِداً. 2.""مَشْرُوعٌ يَحْتَاجُ إِلَى جُهُودٍ مُتَضَافِرَةٍ"" : جُهُودٍ مُتَّحِدَةٍ، مُجْتَمِعَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1056, 'مُتَضَامِنٌ', 'متضامن', 'اسم فاعل', 'ضمن', 'متضامن', 'متضمن', 'فَا. مِنْ تَضَامَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَضَامَنَ). ""مُتَضَامِنٌ مَعَ زَمِيلِهِ"" : مُؤازِرٌ لَهُ، مُدَعِّمٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1057, 'مُتَضَايِقٌ', 'متضايق', 'اسم فاعل', 'ضيق', 'متضايق', 'متضق', 'فَا. مِنْ تَضَايَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَضَايَقَ). ""مُتَضَايِقٌ مِنْ حَرَكَاتِهِ الْمُزْعِجَةِ"" : مُنْزَعِجٌ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1058, 'مُتَضَرِّرٌ', 'متضرر', 'اسم فاعل', 'ضرر', 'متضرر', 'متضر', 'فَا. مِنْ تَضَرَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَضَرَّرَ). 1.""مُتَضَرِّرٌ مِنَ الخَسَارَةِ الَّتِي لَحِقَتْهُ"" : مُصَابٌ بِضَرَرٍ وَأَذىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1059, 'مُتَضَلِّعٌ', 'متضلع', 'اسم فاعل', 'ضلع', 'متضلع', 'متضلع', 'فَا. مِنْ تَضَلَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَضَلَّعَ). ""مُتَضَلِّعٌ مِنْ عُلُومِ الفِقْهِ"" : عَالِمٌ بِهَا عِلْماً وَافرا، مُتَعَمِّقٌ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1060, 'مُتَطَابِقٌ', 'متطابق', 'اسم فاعل', 'طبق', 'متطابق', 'متطبق', 'فَا. مِنْ تَطَابَقَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَطَابَقَ). 1. ""عَمَلٌ مُتَطَابِقٌ مَعَ الخُطَّةِ الْمَرْسُومَةِ"" : مُتَوَافِقٌ. 2.""شَهَادَتُهُ مُتَطَابِقَةٌ مَعَ الوَاقِعِ"" : مُتَمَاثِلَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1061, 'مُتَطَاوِلٌ', 'متطاول', 'اسم فاعل', 'طول', 'متطاول', 'متطل', 'فَا. مِنْ تَطَاوَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَطَاوَلَ). ""مُتَطَاوِلٌ عَلَى حُقُوقِ النَّاسِ"" : مُعْتَدٍ عَلَيْهَا بِعُنْفِ قَوْلاً أَوْ فِعْلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1062, 'مُتَطَبِّبٌ', 'متطبب', 'اسم فاعل', 'طبب', 'متطبب', 'متطب', 'فَا. مِنْ تَطَبَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَطَبَّبَ).""رَجُلٌ مُتَطَبِّبٌ"" : الْمُت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1063, 'مُتَطَرِّفٌ', 'متطرف', 'اسم فاعل', 'طرف', 'متطرف', 'متطرف', 'فَا. مِنْ تَطَرَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَطَرَّفَ). 1.""مُتَطَرِّفٌ فيِ آرَائِهِ"" : الْمُتَجَاوِزُ حُدُودَ الاعْتِدَالِ. ""مَوْقِفٌ مُتَطَرِّفٌ"" ""مَوَاقِفُ مُتَطَرّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1064, 'مُتَطَفِّلٌ', 'متطفل', 'اسم فاعل', 'طفل', 'متطفل', 'متطفل', 'فا. من تَطَفَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَطَفَّلَ). ""رَجُلٌ مُتَطَفِّلٌ"" : مَنْ يَأْتِي إِلَى الوَلاَئِمِ وَالْمَجَالِسِ دُونَ أَنْ يُدْعَى إِلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1065, 'مُتَطَلِّعٌ', 'متطلع', 'اسم فاعل', 'طلع', 'متطلع', 'متطلع', 'فَا. مِنْ تَطَلَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَطَلِّعٌ-مُتَطَلِّعٌ، ةٌ [ط ل ع] (فَا. مِنْ تَطَلَّعَ). 1.""رَفَعَ حَاجِبَيْهِ مُتَطَلِّعاً إِلَيْهَا بِنَظْرَةٍ صَامِتَةٍ"" : نَاظِراً إِلَى طَلْعَتِهَا. 2.""مُتَطَلِّعٌ إِلىَ العُلاَ"" : مُتَرَقِّبٌ بِشَوْقٍ وَرَغْبَةٍ إِلَى العُلاَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1066, 'مُتَطَوِّرٌ', 'متطور', 'اسم فاعل', 'طور', 'متطور', 'متطر', 'فَا. مِنْ تَطَوَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَطَوَّرَ). 1.""مُتَطَوِّرٌ فِي سُلُوكِهِ"" : مُتَحَضِّرٌ. ""شَعْبٌ مُتَطَوِّرٌ"". 2.""عَبَّرَ عَنْ أَفْكَارٍ مُتَطَوِّرَةٍ"" : عَنْ أَفْكَارٍ مُتَقَدِّمَةٍ. ""الأَحْوَالُ الاقْتِصَادِيَّةُ مُتَغَيِّرَةٌ مُتَطَوِّرَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1067, 'مُتَطَوِّعٌ', 'متطوع', 'اسم فاعل', 'طوع', 'متطوع', 'متطع', 'فَا. مِنْ تَطَوَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَطَوَّعَ). ""جَاءَ مُتَطَوِّعاً"" : جَاءَ طَوْعَ اخْتِيَارِهِ لِلْمُسَاهَمَةِ فِي عَمَلٍ مَّا مِنْ تِلْقَاءِ ذَاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1068, 'مُتَطَيِّرٌ', 'متطير', 'اسم فاعل', 'طير', 'متطير', 'متطر', 'فا. من تَطَيَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَطَيَّرَ). ""مُتَطَيِّرٌ مِمَّا رَأَى"" : مُتَشَائِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1069, 'مُتَظَاهِرٌ', 'متظاهر', 'اسم فاعل', 'ظهر', 'متظاهر', 'متظهر', 'فا. من تَظَاهَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". (فا. من تَظَاهَرَ). 1.""بَدَا مُتَظَاهِراً بِالكَسَلِ"" : مُظْهِراً الكَسَلَ. ""أَشَاحَ وَجْهَهُ مُتَظَاهِرًا بِعَدَمِ الاكْتِرَاثِ"" (ن. محفوظ). 2.""اِنْتَشَرَ الْمُتَظَاهِرُونَ فِي شَوَارِعِ الْمَدِينَةِ"" : الجَمَاعَةُ مِنَ النَّاسِ تَخْرُجُ فِي مُظَاهَرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1070, 'مُتَعَاطِفٌ', 'متعاطف', 'اسم فاعل', 'عطف', 'متعاطف', 'متعطف', 'فَا. مِنْ تَعَاطَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَاطَفَ). ""مُتَعَاطِفٌ مَعَ آرَائِهِ"" : الْمُنَاصِرُ وَالْمُؤَيِّدُ لَهَا فِي حُدُودِ التَّعَاطُفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1071, 'مُتَعَاظِمٌ', 'متعاظم', 'اسم فاعل', 'عظم', 'متعاظم', 'متعظم', 'فَا. مِنْ تَعَاظَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَاظَمَ). ""مُتَعَاظِمٌ فِي مَجْلِسِهِ"" : مُتَكَبِّرٌ، مُتَغَطْرِسٌ، مُتَعَجْرِفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1072, 'مُتَعَاقِبٌ', 'متعاقب', 'اسم فاعل', 'عقب', 'متعاقب', 'متعقب', 'فَا. مِنْ تَعَاقَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَاقَبَ). ""عَدَدٌ مُتَعَاقِبٌ"" : مُتَتَابِعٌ، مُتَوَالٍ. ""وُفُودٌ مُتَعَاقِبَةٌ"" ""أَجْيالٌ مُتَعَاقِبَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1073, 'مُتَعَاقِدٌ', 'متعاقد', 'اسم فاعل', 'عقد', 'متعاقد', 'متعقد', 'فَا. مِنْ تَعَاقَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَاقَدَ). 1.""مُتَعَاقِدٌ عَلَى الوَفَاءِ"" : مُتَّفِقٌ. 2.""الْمُتَعَاقِدَانِ عَلَى..."" : الطَّرَفَانِ اللَّذَانِ عَقَدَا الاتِّفَاقَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1074, 'مُتَعَالِي', 'متعالي', 'اسم فاعل', 'علو', 'متعالي', 'متعل', 'فَا. مِن تَعَالَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن تَعَالَى). 1.""مُتَعَالٍ عَنِ النَّاسِ"" : مُتَرَفِّعٌ. 2.""تَتَرَدَّدُ الأَصْدَاءُ مِنْ جُدْرَانِ القِلاَعِ الْمُتَعَالِيَةِ"" : الْمُرْتَفِعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1075, 'مُتَعَاوِنٌ', 'متعاون', 'اسم فاعل', 'عون', 'متعاون', 'متعن', 'فَا. مِنْ تَعَاوَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَاوَنَ). 1.""مُتَعَاوِنٌ مَعَهُ"" : مُؤَازِرٌ لَهُ وَمُشَارِكٌ لَهُ فِي عَمَلٍ مَّا. 2.""مُتَعَاوِنٌ مَعَ العَدُوِّ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1076, 'مُتَعَبِّدٌ', 'متعبد', 'اسم فاعل', 'عبد', 'متعبد', 'متعبد', 'فَا. مِنْ تَعَبَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَبَّدَ). ""مُتَعَبِّدٌ فِي صَوْمَعَتِهِ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1077, 'مُتَعَجْرِفٌ', 'متعجرف', 'اسم فاعل', 'عجرف', 'متعجرف', 'متعجرف', 'فَا. مِنْ تَعَجْرَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَجْرَفَ). ""مُتَعَجْرِفٌ فِي حَدِيثِهِ"" : مُتَكَبِّرٌ، مُتَغَطْرِسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1078, 'مُتَعَدِّدٌ', 'متعدد', 'اسم فاعل', 'عدد', 'متعدد', 'متعد', 'فَا. مِنْ تَعَدَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَدَّدَ). 1.""مُتَعَدِّدٌ الأَشْكَالِ"" : مُتَنَوِّعُهَا. 2.""رَسْمٌ مُتَعَدِّدُ الأَلْوَانِ"" : مُخْتَلِفُ الأَلْوَانِ. 3.""كَلِمَةٌ مُتَعَدِّدَةُ الْمَعَانِي"" : لَهَا مَعَانٍ مُخْتَلِفَةٌ. 4.""مُتَعَدِّدُ الاخْتِصَاصِ"" : مُتَنَوِّعُ الاخْتِصَاصِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1079, 'مُتَعَدِّي', 'متعدي', 'اسم فاعل', 'عدي', 'متعدي', 'متعد', 'فا. من تَعَدَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَعَدَّى). 1.""كَانَ هُوَ الْمُتَعَدِّي"" : الظَّالِمُ، الْمُتَجَاوِزُ لِلْحَدِّ. 2.""الفِعْلُ الْمُتَعَدِّي"" : الفِعْلُ الَّذِي يَنْصِبُ الْمَفْعُولَ بِهِ بِنَفْسِهِ دُونَ وَسَاطَةِ حَرْفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1080, 'مُتَعَذِّرٌ', 'متعذر', 'اسم فاعل', 'عذر', 'متعذر', 'متعذر', 'فَا. مِنْ تَعَذَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَعَذِّرٌ-مُتَعَذِّرٌ، ةٌ [ع ذ ر ] (فَا. مِنْ تَعَذَّرَ). ""عَمَلِيَّةٌ حِسَابِيَّةٌ مُتَعَذِّرٌ حَلُّهَا"" : مُمْتَنِعٌ حَلُّهَا. ""الوُصولُ إِلَيْهِ مُتَعَذِّرٌ"" : صَعْبٌ، غَيْرُ مُمْكِنٍ الوُصُولُ إِلَيْهِ، مُمْتَنِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1081, 'مُتَعَرِّجٌ', 'متعرج', 'اسم فاعل', 'عرج', 'متعرج', 'متعرج', 'فَا. مِنْ تَعَرَّجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَعَرِّجٌ-مُتَعَرِّجٌ، ةٌ [ع ر ج] (فَا. مِنْ تَعَرَّجَ). ""سَارَ فِي طَرِيقٍ مُتَعَرِّجٍ"" : مُتَشَعِّبٌ، مُلْتَوٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1082, 'مُتَعَصِّبٌ', 'متعصب', 'اسم فاعل', 'عصب', 'متعصب', 'متعصب', 'فَا. مِنْ تَعَصَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَعَصَّبَ). ""مُتَعَصِّبٌ لآرَائِهِ"" : شَدِيدُ الْحَمَاسِ لهَا، مَنْ يَتَشَبَّثُ بِآرَائِهِ إِلَى أَقْصَى حَدٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1083, 'مُتَعَطِّشٌ', 'متعطش', 'اسم فاعل', 'عطش', 'متعطش', 'متعطش', 'فَا. مِنْ تَعَطَّشَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَطَّشَ). ""مُتَعَطِّشٌ لِزِيَارَةِ أَهْلِهِ"" : شَدِيدُ الرَّغْبَةِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1084, 'مُتَعَفِّفٌ', 'متعفف', 'اسم فاعل', 'عفف', 'متعفف', 'متعف', 'فَا. مِنْ تَعَفَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَفَّفَ). ""متُعَفِّفٌ فِي سُلُوكِهِ"" : عَفِيفٌ، طَاهِرٌ، مُحْتَشِمٌ فِي سُلُوكِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1085, 'مُتَعَفِّنٌ', 'متعفن', 'اسم فاعل', 'عفن', 'متعفن', 'متعفن', 'فَا. مِنْ تَعَفَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَفَّنَ). ""لَحْمٌ مُتَعَفِّنٌ"" : لَحْمٌ نَتِنٌ تَفُوحُ مِنْهُ رَائِحَةٌ كَرِيهَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1086, 'مُتَعَقِّبٌ', 'متعقب', 'اسم فاعل', 'عقب', 'متعقب', 'متعقب', 'فَا. مِنْ تَعَقَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَعَقَّبَ). ""مُتَعَقِّبٌ لِأَثَرِهِ"" : مُقْتَفٍ، مُتَتَبِّعٌ، مُلاَحِقٌ لِأَثرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1087, 'مُتَعَقِّلٌ', 'متعقل', 'اسم فاعل', 'عقل', 'متعقل', 'متعقل', 'فَا. مِنْ تَعَقَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَقَّلَ). ""مُتَعَقِّلٌ فِي تَصَرُّفَاتِهِ"" : يَفْعَلُ الأَشْيَاءَ قَبْلَ الإِقْدَامِ عَلَيْهَا، رَزِينٌ، مُتَدَبِّرٌ، مُتَفَهِّمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1088, 'مُتَعَلِّقٌ', 'متعلق', 'اسم فاعل', 'علق', 'متعلق', 'متعلق', 'فَا. مِنْ تَعَلَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَلَّقَ). 1.""قَلْبُهُ مُتَعَلِّقٌ بِهِ"" : مُرْتَبِطٌ بِهِ. 2.""مُتَعَلِّقٌ بِمَادَّةِ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1089, 'مُتَعَلِّمٌ', 'متعلم', 'اسم فاعل', 'علم', 'متعلم', 'متعلم', 'فا. من تَعَلَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من تَعَلَّمَ). ""اِرْتَفَعَ عَدَدُ الْمُتَعَلِّمِينَ فِي البِلاَدِ"" : الَّذِينَ يَتَعَلَّمُونَ وَيَتَأَدَّبُونَ فِي الْمَدَارِسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1090, 'مُتَعَمِّدٌ', 'متعمد', 'اسم فاعل', 'عمد', 'متعمد', 'متعمد', 'فَا. مِنْ تَعَمَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَعَمَّدَ). ""مُتَعَمِّدٌ الإِسَاءةَ إِلَيْهِ"" : مَنْ يُقْدِمُ عَلَى أَمْرٍ عَنْ سَابِقِ إِصْرَارٍ وَتَصْمِيمٍ. ""قَتَلَهُ مُتَعَمِّداً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1091, 'مُتَعَنِّتٌ', 'متعنت', 'اسم فاعل', 'عنت', 'متعنت', 'متعنت', 'فَا. مِنْ تَعَنَّتَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَنَّتَ). ""مُتَعَنِّتٌ فِي مَوْقِفِهِ"" : مُتَصَلِّبٌ، أَيْ مَنْ يَتَشَبَّثُ بِأَمْرٍ مَّا إِلَى نِهَايَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1092, 'مُتَعَهِّدٌ', 'متعهد', 'اسم فاعل', 'عهد', 'متعهد', 'متعهد', 'فَا. مِنْ تَعَهَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَهَّدَ). ""مُتَعَهِّدٌ بِإِنْجَازِ مَا أُسْنِدَ إِلَيْهِ مِنْ مَهَامَّ"" : مَنْ يَلْتَزِمُ بِتَنْفِيذِ عَمَلٍ أَوْ مُهِمَّةٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1093, 'مُتَعَيِّشٌ', 'متعيش', 'اسم فاعل', 'عيش', 'متعيش', 'متعش', 'فَا. مِنْ تَعَيَّشَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَعَيَّشَ). ""مُتَعَيِّشٌ بِمَا رَزَقَهُ اللهُ"" : يَعِيشُ بِأَقَلِّ مَا يُمْكِنُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1094, 'مُتَغَضِّنٌ', 'متغضن', 'اسم فاعل', 'غضن', 'متغضن', 'متغضن', 'فَا. مِنْ تَغَضَّنَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَغَضِّنٌ-مُتَغَضِّنٌ [غ ض ن] (فَا. مِنْ تَغَضَّنَ). ""وَجْهٌ مُتَغَضِّنٌ"": مُتَجَعِّدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1095, 'مُتَغَطْرِسٌ', 'متغطرس', 'اسم فاعل', 'غطرس', 'متغطرس', 'متغطرس', 'فا. من تَغَطْرَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَغَطْرَسَ). ""مُتَغَطْرِسٌ عَلى زُمَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1096, 'مُتَغَيِّبٌ', 'متغيب', 'اسم فاعل', 'غيب', 'متغيب', 'متغب', 'فَا. مِنْ تَغَيَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَغَيَّبَ). ""هُوَ الْمُتَغَيِّبُ الوَحِيدُ عَنِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1097, 'مُتَغَيِّرٌ', 'متغير', 'اسم فاعل', 'غير', 'متغير', 'متغر', 'فَا. مِنْ تَغَيَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَغَيَّرَ). 1.""كَانَ مُتَغَيِّرَ اللَّوْنِ"" : مُتَبَدِّلَ اللَّوْنِ. 2.""مُتَغَيِّرٌ فِي آرَائِهِ"" : مُتَقَلِّبٌ، مَنْ لاَ يَثْبُتُ عَلَى حَالٍ. ""جَوٌّ مُتَغَيِّرٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1098, 'مُتَفَائِلٌ', 'متفائل', 'اسم فاعل', 'فأل', 'متفاءل', 'متفل', 'فَا. مِنْ تَفَاءَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَفَاءَلَ). ""مُتَفَائِلٌ بِالْمُسْتَقْبَلِ"" : مُتَوَقِّعٌ لِلْخَيْرِ. ""نَظْرَةٌ مُتَفَائِلَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1099, 'مُتَفَتِّتٌ', 'متفتت', 'اسم فاعل', 'فتت', 'متفتت', 'متفت', 'فَا. مِنْ تَفَتَّتَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَفَتِّتٌ-مُتَفَتِّتٌ، ةٌ [ف ت ت] (فَا. مِنْ تَفَتَّتَ). ""خُبْزٌ مُتَفَتِّتٌ"" : مَقْطُوعٌ إِلَى أَجْزاءٍ صَغِيرَةٍ. ""صَارَتْ أَجْزاءُ الآلَةِ مُتَفَتِّتَةً أَمَامَهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1100, 'مُتَفَتِّحٌ', 'متفتح', 'اسم فاعل', 'فتح', 'متفتح', 'متفتح', 'فَا. مِنْ تَفَتَّحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ج:"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَفَتَّحَ). 1.""وَرْدَةٌ مُتَفَتِّحَةٌ"" : الوَرْدَةُ عِنْدَمَا تَتَفَتَّحُ قُعالُها، أي تَويجيَّاتُها. 2.""مُتَفَتِّحٌ عَلَى آرَاءِ الآخَرِينَ"" : مَنْ يَقْبَلُ آرَاءَ الآخَرِينَ وَيَتَفَهَّمُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1101, 'مُتَفَجِّرٌ', 'متفجر', 'اسم فاعل', 'فجر', 'متفجر', 'متفجر', 'فَا. مِنْ تَفَجَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَفَجَّرَ). 1.""مَاءٌ مُتَفَجِّرٌ"" : مَاءٌ نَابِعٌ بِقُوَّةٍ وَعُنْفٍ. 2.""اِكْتَشَفَ عُبُوَّةً مِنَ الْمُتَفَجِّرَاتِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1102, 'مُتَفَحِّصٌ', 'متفحص', 'اسم فاعل', 'فحص', 'متفحص', 'متفحص', 'فَا. مِنْ تَفَحَّصَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَفَحَّصَ). 1.""مُتَفَحِّصٌ لِلْعَمَلِ"" : مُدَقِّقٌ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1103, 'مُتَفَرِّجٌ', 'متفرج', 'اسم فاعل', 'فرج', 'متفرج', 'متفرج', 'فَا. مِنْ تَفَرَّجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَفَرَّجَ). ""جَاءَ مُتَفَرِّجاً عَلَى الأَلْعَابِ"" : مُش"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1104, 'مُتَفَرِّعٌ', 'متفرع', 'اسم فاعل', 'فرع', 'متفرع', 'متفرع', 'فَا. مِنْ تَفَرَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَفَرَّعَ). ""غُصْنُ مُتَفَرِّعٌ"" : مُتَشَعِّبٌ إِلَى أَغْصَانٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1105, 'مُتَفَرِّغٌ', 'متفرغ', 'اسم فاعل', 'فرغ', 'متفرغ', 'متفرغ', 'فَا. مِنْ تَفَرَّغَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَفَرَّغَ). 1.""مُتَفَرِّغٌ عَنِ العَمَلِ"" : عَاطِلٌ. 2.""مُتَفَرِّغٌ لِلْعَمَلِ"" : مَنْ يُكَرِّسُ كُلَّ جُهْدِهِ لِلْعَمَلِ. ""مُتَفَرِّغٌ لِلْبَحْثِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1106, 'مُتَفَرِّقٌ', 'متفرق', 'اسم فاعل', 'فرق', 'متفرق', 'متفرق', 'فَا. مِنْ تَفَرَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَفَرَّقَ). ""رَجَعُوا إِلَى بُيُوتِهِمْ مُتَفَرِّقِينَ"" : مُوَزَّعِينَ، مُشَتَّتِينَ. ""لاَ يَبْدُو التَّشَابُهُ بَيْن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1107, 'مُتَفَسِّخٌ', 'متفسخ', 'اسم فاعل', 'فسخ', 'متفسخ', 'متفسخ', 'فَا. مِنْ تَفَسَّخَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَفَسَّخَ). 1.""سُلُوكٌ مُتَفَسِّخٌ"" : مُشِينٌ غَيْرُ مُحْتَشِمٍ. ""أَخْلاَقٌ مُتَفَسِّخَةٌ"". 2.""لَحْمٌ مُتَفَسِّخٌ"" : نَتِنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1108, 'مُتَفَشِّي', 'متفشي', 'اسم فاعل', 'فشو', 'متفشي', 'متفش', 'فا. من تَفَشَّى', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فا. من تَفَشَّى). ""مَرَضٌ مُتَفَشٍّ"" : مُنْتَشِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1109, 'مُتَفَكِّكٌ', 'متفكك', 'اسم فاعل', 'فكك', 'متفكك', 'متفك', 'فَا. مِنْ تَفَكَّكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَفَكَّكَ). ""مُتَفَكِّكٌ الأَجْزَاءِ"" : أَجْزَاؤُهُ مَفْصُولَةٌ بَعْضُهَا عَنْ بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1110, 'مُتَفَنِّنٌ', 'متفنن', 'اسم فاعل', 'فنن', 'متفنن', 'متفن', 'فَا. مِنْ تَفَنَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَفَنَّنَ). ""مُتَفَنِّنٌ فِي مَجَالِ النَّحْتِ"" : ذُو فَنٍّ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1111, 'مُتَفَوِّقٌ', 'متفوق', 'اسم فاعل', 'فوق', 'متفوق', 'متفق', 'فَا. مِنْ تَفَوَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَفَوَّقَ). ""مُتَفَوِّقٌ فِي دِرَاسَتِهِ"" : مُتَقَدِّمٌ فِيهَا وَمُسَيْطِرٌ عَلَى مَنْ عَدَاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1112, 'مُتَقَابِلٌ', 'متقابل', 'اسم فاعل', 'قبل', 'متقابل', 'متقبل', 'فَا. مِنْ تَقَابَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَقَابَلَ). 1.""الأَوْرَاقُ المتُقَاَبِلَةُ"" (نب) : الأَوْرَاقُ الَّتِي تَنْبُتُ أَزْوَاجاً فِي وَرَقَةٍ وَاحِدَةٍ. 2.""زَاوِيَتَانِ مُتَقَابِلَتَانِ"" (هن) : زَاوِيَتَانِ يَكُونُ ضِلْعُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1113, 'مُتَقَارِبٌ', 'متقارب', 'اسم فاعل', 'قرب', 'متقارب', 'متقرب', 'فَا. مِنْ تَقَارَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَقَارَبَ). 1.""رَجُلٌ مُتَقَارِبٌ"" : قَصِيرٌ. 2.""هُمَا مُتَقَارِبَانِ فِي السِّنِّ"" : قَرِيبَا السِّنِّ. ""زَادَ مِنْ صَدَاقَتِنَا أَنَّنَا مُتَقَارِبُو السِّنِّ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1114, 'مُتَقَاطِعٌ', 'متقاطع', 'اسم فاعل', 'قطع', 'متقاطع', 'متقطع', 'فَا. مِنْ تَقَاطَعَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَقَاطَعَ). 1.""خَطَّانِ مُتَقَاطِعَانِ"" : يَقْطَعُ كُلُّ وَاحِدٍ مِنْهُمَا الآخَرَ. 2.""مِنْ هُوَاةِ الكَلِمَاتِ الْمُتَقَاطِعَةِ"" : لُعْبَةٌ ذِهْنِيَّةٌ تَدُورُ حَوْلَ إِيجَادِ كَلِمَاتٍ يُشَارُ إِلَيْهَا مِنْ خِلاَلِ مَعْنـىً عَامٍّ أَوْ سُؤَالٍ مَّا، وَيُمْكِنُ إِدْخَالُهَا فِي مُرَبَّعَاتٍ وَتَأْتِي مُوَافِقَةً وَمُطَابِقَةً لِمُجْمَلِ مَعَانِي الكَلِمَاتِ العَمُودِيَّةِ وَالأُفُقِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1115, 'مُتَقَاعِدٌ', 'متقاعد', 'اسم فاعل', 'قعد', 'متقاعد', 'متقعد', 'فَا. مِنْ تَقَاعَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَقَاعَدَ). ""مُوَظَّفٌ مُتَقَاعِدٌ"" : صَارَ فِي سِنِّ التَّقَاعُدِ، أَيْ أُحِيلَ عَلَى الْمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1116, 'مُتَقَاعِسٌ', 'متقاعس', 'اسم فاعل', 'قعس', 'متقاعس', 'متقعس', 'فَا. مِنْ تَقَاعَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَقَاعَسَ). ""مُتَقَاعِسٌ عَنِ العَمَلِ مُتَغَافِلٌ"" : مُتَأَخِّرٌ، مُتَكَاسِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1117, 'مُتَقَبِّلٌ', 'متقبل', 'اسم فاعل', 'قبل', 'متقبل', 'متقبل', 'فَا. مِنْ تَقَبَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَقَبَّلَ). ""مُتَقَبِّلٌ لِلنَّقْدِ"" : يَتَقَبَّلُ النَّقْدَ بِلاَ تَعَصُّبٍ وَلاَ تَشَنُّجٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1118, 'مُتَقَدِّمٌ', 'متقدم', 'اسم فاعل', 'قدم', 'متقدم', 'متقدم', 'فَا. مِنْ تَقَدَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَقَدَّمَ). 1.""شَعْبٌ مُتَقَدِّمٌ"" : مُتَطَوِّرٌ. 2.""مُتَقَدِّمٌ فِي السِّنِّ"" : شَيْخٌ طَاعِنٌ فِي السِّنِّ. 3.""رَأْيٌ مُتَقَدِّمٌ ذِكْرُهُ"" : سَبَقَتِ الإِشَارَةُ إِلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1119, 'مُتَقَزِّزٌ', 'متقزز', 'اسم فاعل', 'قزز', 'متقزز', 'متقز', 'فَا. مِنْ تَقَزَّزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَقَزَّزَ). ""مُتَقَزِّزٌ مِنْ رَائِحَتِهِ"" : مَنْ يَكْرَهُ الشَّيْءَ وَيَعافُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1120, 'مُتَقَشِّفٌ', 'متقشف', 'اسم فاعل', 'قشف', 'متقشف', 'متقشف', 'فَا. مِنْ تَقَشَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَقَشَّفَ). ""مُتَقَشِّفٌ فِي مَصْرُوفِهِ"" : مَنْ يُقَتِّرُ وَيَتَقَشَّفُ وَلاَ يُنْفِقُ إِلاَّ القَلِيلَ جِدّاً. ""جَعَلَتْ مِنْهُ حَوَادِثُ الدَّهْرِ رَجُلاً مُتَقَشِّفاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1121, 'مُتَقَطِّعٌ', 'متقطع', 'اسم فاعل', 'قطع', 'متقطع', 'متقطع', 'فَا. مِنْ تَقَطَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَقَطَّعَ). 1.""عَمَلٌ مُتَقَطِّعٌ"" : عَمَلٌ غَيْرُ مُتَوَاصِلٍ. ""أَفْكَارٌ مُتَقَطِّعَةٌ"". 2.""غُرَّةٌ مُتَقَطِّعَةٌ"" : يَرْتَفِعُ بَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1122, 'مُتَقَلِّبٌ', 'متقلب', 'اسم فاعل', 'قلب', 'متقلب', 'متقلب', 'فَا. مِنْ تَقَلَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَقَلَّبَ). 1.""طَقْسٌ مُتَقَلِّبٌ"" : طَقْسٌ غَيْرُ مُسْتَقِرٍّ عَلَى حَالٍ. 2.""رَجُلٌ مُتَقَلِّبُ الأَطْوَارِ"" : مُتَغَيِّرُ المِزَاجِ. ""مُتَقَلِّبٌ كَالحِرْبَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1123, 'مُتَقَلِّصٌ', 'متقلص', 'اسم فاعل', 'قلص', 'متقلص', 'متقلص', 'فَا. مِنْ تَقَلَّصَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَقَلَّصَ). 1.""ظِلٍّ مُتَقَلِّصٌ"" : ظِلٌّ مُرْتَفِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1124, 'مُتَقَيِّحٌ', 'متقيح', 'اسم فاعل', 'قيح', 'متقيح', 'متقح', 'فَا. مِنْ تَقَيَّحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَقَيَّحَ). ""جُرْحٌ مُتَقَيِّحٌ"" : بِهِ قَيْحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1125, 'مُتَكَاثِرٌ', 'متكاثر', 'اسم فاعل', 'كثر', 'متكاثر', 'متكثر', 'فَا. مِنْ تَكَاثَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَكَاثَرَ). ""جَرَادٌ مُتَكَاثِرٌ"" : مُتَزَايِدٌ، مُتَوالِدٌ، متناسِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1126, 'مُتَكَافِئ', 'متكافئ', 'اسم فاعل', 'كفأ', 'متكافء', 'متكف', 'فَا. مِنْ تَكَافَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَكَافَأَ). ""ثَرْوَتُهُ مُتَكَافِئَةٌ مَعَ ثَرْوَةِ شَرِيكِهِ"" : مُتَسَاوِيَةٌ، مُتَمَاثِلَةٌ. ""مُتَكَافِئًا فِي العَمَلِ وَالفِعْلِ"" ""صِرَاعٌ غَيْرُ مُتَكَافِئٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1127, 'مُتَكَبِّرٌ', 'متكبر', 'اسم فاعل', 'كبر', 'متكبر', 'متكبر', 'فَا. مِنْ تَكَبَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَكَبَّرَ). ""مُتَكَبِّرٌ عَلَى زُمَلاَئِهِ"" : مُتَعَجْرِفٌ، مُتَغَطْرِسٌ، مُتَعَاظِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1128, 'مُتَكَتِّمٌ', 'متكتم', 'اسم فاعل', 'كتم', 'متكتم', 'متكتم', 'فَا. مِنْ تَكَتَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَكَتَّمَ). ""مُتَكَتِّمٌ عَلَى أَسْرَارِ صَحْبِهِ"" : أَي يَكْتُمُهَا وَيَحْتَفِظُ بِهَا وَلاَ يُذِيعُهَا في النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1129, 'مُتَكَرِّرٌ', 'متكرر', 'اسم فاعل', 'كرر', 'متكرر', 'متكر', 'فَا. مِنْ تَكَرَّرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَكَرِّرٌ-مُتَكَرِّرٌ، ةٌ [ك ر ر] (فَا. مِنْ تَكَرَّرَ). ""عَمَلٌ مُتَكَرِّرٌ"": مُعَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1130, 'مُتَكَلِّفٌ', 'متكلف', 'اسم فاعل', 'كلف', 'متكلف', 'متكلف', 'فَا. مِنْ تَكَلَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَكَلَّفَ). 1.""مُتَكَلِّفٌ فِي ضِيَافَتِهِ"" : مَنْ يَتَكَلَّفُ الشَّيْءَ الكَثِيرَ الز"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1131, 'مُتَكَلِّمٌ', 'متكلم', 'اسم فاعل', 'كلم', 'متكلم', 'متكلم', 'فَا. مِنْ تَكَلَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَكَلَّمَ). ""كَانَ الْمُتَكَلِّمَ الوَحِيدَ فِي الجَلْسَةِ"" : الْمُتَنَاوِلَ لِلْكَلاَمِ، الْمُتَحَدِّثَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1132, 'مُتَكَهِّنٌ', 'متكهن', 'اسم فاعل', 'كهن', 'متكهن', 'متكهن', 'فَا. مِنْ تَكَهَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَكَهَّنَ). ""مُتَكَهِّنٌ بِمَا سَيَحْدُثُ"" : مُت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1133, 'مُتَكَوِّنٌ', 'متكون', 'اسم فاعل', 'كون', 'متكون', 'متكن', 'فَا. مِنْ تَكَوَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَكَوَّنَ). 1.""كِتَابٌ مُتَكَوِّنٌ مِنْ خَمْسَةِ فُصُولٍ"" : مُتَأَلِّفٌ... 2.""طَالِبٌ مُتَكَوِّنٌ تَكْوِيناً عِلْمِيّاً"" : مُتَدَرِّبٌ، مُتَعَلِّمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1134, 'تَالِي', 'تالي', 'اسم فاعل', 'تلو', 'تالي', 'تل', 'فا. من تلا', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":تَوَالٍ:التَّوَالِي"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من تلا). 1.""اِنْتَقَلَ إِلَى الفَصْلِ التَّالِي"" : التَّابِعِ لِمَا قَبْلَهُ، 2.""لاَ بُدَّ مِنْ تَوَفُّرِ الشُّرُوطِ التَّالِيَةِ"" : الآتِيَةِ. 3.""بِالتَّالِي كَانَ عَلَيْهِ أَنْ يُرَاجِعَ حِسَابَهُ"" : مِنْ ثَمَّ، إِذاً، أَيْ بِالنَّتِيجَةِ لِمَا سَبَقَ. 4.""تَالِيَاتُ النُّجُومِ"" : أَوَاخِرُهَا. 5.""تَوَالِي الخَيْلِ وَالإِبِلِ"" : أَذْنَابُهَا وَأَرْجُلُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1135, 'تلاة', 'تلاة', 'اسم فاعل', '', 'تلاة', 'تلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1136, 'تَوالِي', 'توالي', 'اسم فاعل', '', 'توالي', 'تل', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1137, 'مُتَلاَئِمٌ', 'متلائم', 'اسم فاعل', 'لأم', 'متلاءم', 'متلم', 'فَا. مِنْ تَلاَءمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَلاَءمَ). ""لِبَاسٌ مُتَلاَئِمٌ مَعَ ذَوْقِهِ"" : مُتَنَاسِبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1138, 'مُتَلاَحِقٌ', 'متلاحق', 'اسم فاعل', 'لحق', 'متلاحق', 'متلحق', 'فَا. مِنْ تَلاَحَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَلاَحَقَ). ""جُهْدٌ مُتَلاَحِقٌ"" : مُتَوَاصِلٌ، مُتَتَابِعٌ. ""أَنْفَاسٌ مُتَلاَحِقَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1139, 'مُتَلاَحِمٌ', 'متلاحم', 'اسم فاعل', 'لحم', 'متلاحم', 'متلحم', 'فَا. مِنْ تَلاَحَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَلاَحَمَ). 1.""مُتَلاَحِمٌ مَعَ عَمَلِهِ"" : مُتَلاَئِمٌ. 2.""جَيْشَانِ مُتَلاَحِمَانِ"" : مُتَشَابِكَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1140, 'مُتَلاَزِمٌ', 'متلازم', 'اسم فاعل', 'لزم', 'متلازم', 'متلزم', 'فَا. مِنْ تَلاَزَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَلاَزَمَ). ""تَوَالَتِ الأَحْدَاثُ مُتَلاَزِمَةً"" : مُتَلاَحِقَةً، مُتَوَالِيَةً، مُتَزَامِنَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1141, 'مُتَلاَصِقٌ', 'متلاصق', 'اسم فاعل', 'لصق', 'متلاصق', 'متلصق', 'فَا. مِنْ تَلاَصَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَلاَصَقَ). ""مُتَلاَصِقُ الأَجْزَاءِ"" : مُتَلاَحِمٌ. ""جَلَسْنَا جَنْباً إِلَى جَنْبٍ مُتَلاَصِقَيْنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1142, 'مُتَلَأْلِئٌ', 'متلألئ', 'اسم فاعل', 'لألأ', 'متلءلء', 'متلل', 'فَا. مِنْ تَلَأْلَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَلَأْلَأَ). ""نَجْمٌ مُتَلَأْلِئٌ"" : مُضِيءٌ، أَيْ تَشِعُّ مِنْهُ الأَنْوَارُ، مُشِعٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1143, 'مُتَلاَمِعٌ', 'متلامع', 'اسم فاعل', 'لمع', 'متلامع', 'متلمع', 'فَا. مِنْ تَلاَمَعَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَلاَمِعٌ-مُتَلاَمِعٌ [ل م ع] (فَا. مِنْ تَلاَمَعَ). ""أَضْوَاءٌ مُتَلاَمِعَةٌ"" : مُضِيئَةٌ. ""كَانَتِ النُّجُومِ فَوْقَنَا كَالفَوَانِيسِ البَعِيدَةِ الْمُتَلاَمِعَةِ الْمُتَنَاثِرَةِ بِغَيْرِ نِظَامٍ"". (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1144, 'مُتَلَبِّسٌ', 'متلبس', 'اسم فاعل', 'لبس', 'متلبس', 'متلبس', 'فَا. مِنْ تَلَبَّسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَلَبَّسَ). ""أُلْقِيَ عَلَيْهِ القَبْضُ مُتَلَبِّساً بِالجَرِيمَةِ"" : أَيْ وَهُوَ فِي حَالَةِ الجُرْمِ الْمَشْهُودِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1145, 'مُتَلَفِّعٌ', 'متلفع', 'اسم فاعل', 'لفع', 'متلفع', 'متلفع', 'فَا. مِنْ تَلَفَّعَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَلَفَّعَ). 1.""جَاءتْ مُتَلَفِّعَةً بِمَلاَءتِهَا"" : مُتَغَطِّيَةً. 2.""نَارٌ مُتَلَفِّعَةٌ"": مُتَّقِدَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1146, 'مُتَلَقِّي', 'متلقي', 'اسم فاعل', 'لقي', 'متلقي', 'متلق', 'فَا. مِنْ تَلَقَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَلَقَّى).""كُلُّ مُتَعَلِّمٍ مُتَلَقٍّ لِلْمَعْرِفَةِ"" : مَنْ يَتَلَقَّى الشَّيْءَ، مُسْتَقْبِلٍ، مُتَعَلِّمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1147, 'مُتَلَمِّسٌ', 'متلمس', 'اسم فاعل', 'لمس', 'متلمس', 'متلمس', 'فَا. مِنْ تَلَمَّسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَلَمَّسَ). ""مُتَلَمِّسٌ لِلْمَعْرِفَةِ"" : بَاحِثٌ عَنْهَا بِإِلْحَاحٍ وَرَغْبَةٍ شَدِيدَةٍ. ""وَسَارَ مُتَلَمِّساً طَرِيقَهُ فِي ظَلاَمٍ دَامِسٍ"". (ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1148, 'مُتَلَهِّفٌ', 'متلهف', 'اسم فاعل', 'لهف', 'متلهف', 'متلهف', 'فَا. مِنْ تَلَهَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَلَهَّفَ). ""مُتَلَهِّفٌ لِرُؤْيَةِ أَهْلِهِ"" : مُتَشَوِّقٌ لِرُؤْيَتِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1149, 'مُتَلَوِّنٌ', 'متلون', 'اسم فاعل', 'لون', 'متلون', 'متلن', 'فَا. مِنْ تَلَوَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَلَوَّنَ). 1.""ثَوْبٌ مُتَلَوِّنٌ"" : اِخْتَلَفَتْ أَلْوَانُهُ. 2.""مُتَلَوِّنٌ كَالحِرْبَاءِ"" : مَنْ لاَ يَثْبُتُ عَلَى حَالٍ، مُتَغَيِّرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1150, 'مُتَلَوِّي', 'متلوي', 'اسم فاعل', 'لوى', 'متلوي', 'متل', 'فَا. مِنْ تَلَوَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَلَوَّى). 1.""شَارِعٌ مُتَلَوٍّ"" : مُنْعَطِفٌ. 2. ""حَيَّةٌ مُلْتَوِيَةٌ"" : مُسْتَدِيرَةٌ. 3.""مُتَلَوٍّ مِنَ الْمَرَضِ وَالآلاَمِ"" : مُنْقَبِضٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1151, 'تَامٌّ', 'تام', 'اسم فاعل', 'تمم', 'تام', 'تم', 'فا. من تَمَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"تَامٌّ-تَامٌّ، ةٌ [ت م م] (فا. من تَمَّ). 1.""كَانَ البَدْرُ تَامّاً فِي ذَلِكَ الْمَسَاءِ"" : كَامِلاً، أَي اكْتَمَلَتْ دَائِرَتُهُ. 2.""الجَوَابُ تَامٌّ"" : غَيْرُ نَاقِصٍ. 3.""وَلَدٌ تَامُّ الخِلْقَةِ"" : الْمُكْتَمِلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1152, 'توام', 'توام', 'اسم فاعل', '', 'توام', 'تم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1153, 'تمام', 'تمام', 'اسم فاعل', '', 'تمام', 'تمم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1154, 'تممة', 'تممة', 'اسم فاعل', '', 'تممة', 'تممة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1155, 'مُتَمَاثِلٌ', 'متماثل', 'اسم فاعل', 'مثل', 'متماثل', 'متمثل', 'فَا. مِنْ تَمَاثَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَاثَلَ). 1. ""عَدَدَانِ مُتَمَاثِلاَنِ"" : عَدَدَانِ مُتَسَاوِيَانِ. 2.""صُورَتَانِ مُتَمَاثِلَتَانِ"" : مُتَشَابِهَتَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1156, 'مُتَمَادِي', 'متمادي', 'اسم فاعل', 'مدي', 'متمادي', 'متمد', 'فَا. مِنْ تَمَادَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَادَى). ""مُتَمَادٍ فِي غَيِّهِ"" : مُسْتَمِرٌّ فِيهِ، مُدَاوِمٌ عَلَيْهِ. ""مُتَمَادِيَةٌ فِي إِغَاظَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1157, 'مُتَمَارِضٌ', 'متمارض', 'اسم فاعل', 'مرض', 'متمارض', 'متمرض', 'فَا. مِنْ تَمَارَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَارَضَ). ""كُلَّمَا دَعَوْتُهُ لِلْعَمَلِ، جاءَ مُتَمَارِضاً"" : مَنْ يَدَّعِي الْمَرَضَ وَهُوَ سَلِيمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1158, 'مُتَمَاسِكٌ', 'متماسك', 'اسم فاعل', 'مسك', 'متماسك', 'متمسك', 'فَا. مِنْ تَمَاسَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَاسَكَ). 1.""مُتَمَاسِكُ الأَجْزَاءِ"" : مُتَرَابِطٌ ... 2.""مُتَمَاسِكُ النَّفْسِ"" : مُنْضَبِطٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1159, 'مُتَمَاوِتٌ', 'متماوت', 'اسم فاعل', 'موت', 'متماوت', 'متمت', 'فا. من تَمَاوَتَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَمَاوَتَ). ""رَآهُ مُتَمَاوِتاً"" : أَيْ يَعُدُّ نَفْسَهُ مَيِّتاً وَهُوَ لَيْسَ كَذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1160, 'مُتَمَايِلٌ', 'متمايل', 'اسم فاعل', 'ميل', 'متمايل', 'متمل', 'فَا. مِنْ تَمَايَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَايَلَ). ""جَاءَ مُتَمَايِلاً فِي مِشْيَتِهِ"" : مُتَبَخْتِراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1161, 'مُتَمَتْرِسٌ', 'متمترس', 'اسم فاعل', 'مرس', 'متمترس', 'متمترس', 'فَا. مِنْ تَمَتْرَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَتْرَسَ).""مُتَمَتْرِسٌ وَرَاءَ الْمَتَارِيسِ"" : قَابِعٌ بِتَحَفُّزٍ وَحَذَرٍ. ""كَانُوا مُتَمَتْرِسِينَ وَرَاءَ الصُّخُورِ وَجُذُوعِ الصَّنَوْبَرِ""(حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1162, 'مُتَمَتِّعٌ', 'متمتع', 'اسم فاعل', 'متع', 'متمتع', 'متمتع', 'فَا. مِنْ تَمَتَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَتَّعَ). ""مُتَمَتِّعٌ بِكَامِلِ حُرِّيَّتِهِ"" : مُنْتَفِعٌ، مُمْتَلِكٌ لَهَا بِتَلَذُّذٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1163, 'مُتَمْتِمٌ', 'متمتم', 'اسم فاعل', 'تمتم', 'متمتم', 'متمتم', 'فَا. مِنْ تَمْتَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمْتَمَ). ""مُتَمْتِمٌ وَمُهَمْهِمٌ"" : الْمُعَجِّلُ فِي كَلاَمِهِ فَلاَ يُفْهَمُ مَا يَقُولُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1164, 'مُتَمَثِّلٌ', 'متمثل', 'اسم فاعل', 'مثل', 'متمثل', 'متمثل', 'فَا. مِنْ تَمَثَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَثَّلَ). ""مُتَمَثِّلٌ لِأَفْكَارِ الدَّرْسِ"" : مُسْتَحْضِرُهَا، مُسْتَوْعِبُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1165, 'مُتَمَدِّنٌ', 'متمدن', 'اسم فاعل', 'مدن', 'متمدن', 'متمدن', 'فَا. مِنْ تَمَدَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"َ:"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَدَّنَ). ""رَجُلٌ مُتَمَدِّنٌ"" : مُتَحَضِّرٌ، سَاكِنُ الْحَضَرِ، يَعِيشُ فِي حَضَارَةٍ. ""شُعُوبٌ مُتَمَدِّنَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1166, 'مُتَمَرِّدٌ', 'متمرد', 'اسم فاعل', 'مرد', 'متمرد', 'متمرد', 'فَا. مِنْ تَمَرَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَرَّدَ). ""مُتَمَرِّدٌ عَلَى النَّاسِ"" : مَنْ يَثُورُ وَيَتَمَرَّدُ عَلَى أَهْلِهِ أَوْ عَلَى سُلْطَةٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1167, 'مُتَمَرِّسٌ', 'متمرس', 'اسم فاعل', 'مرس', 'متمرس', 'متمرس', 'فَا. مِنْ تَمَرَّسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَرَّسَ). ""مُتَمَرِّسٌ فِي عَمَلِهِ"" : مَنْ يُمَارِسُ وَيَعْتَادُ عَمَلَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1168, 'مُتَمَرِّغٌ', 'متمرغ', 'اسم فاعل', 'مرغ', 'متمرغ', 'متمرغ', 'فَا. مِنْ تَمَرَّغَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَرَّغَ). ""مُتَمَرِّغٌ فِي الوَحَلِ أَوْ فِي التُّرَابِ"" : مَنْ تَمَرَّغَ وَالْتَفَّ فِي الوَحَلِ، مُلْتَفٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1169, 'مُتَمَرِّنٌ', 'متمرن', 'اسم فاعل', 'مرن', 'متمرن', 'متمرن', 'فَا. مِنْ تَمَرَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَرَّنَ). ""طَالِبٌ مُتَمَرِّنٌ"" : مُتَدَرِّبٌ. ""مُحَامٍ مُتَمَرِّنٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1170, 'مُتَمَكِّنٌ', 'متمكن', 'اسم فاعل', 'مكن', 'متمكن', 'متمكن', 'فا. من تَمَكَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَمَكَّنَ). 1.""مُتَمَكِّنٌ مِنْ فَنِّهِ"" : قَادِرٌ عَلَيْهِ، ضَابِطٌ لَهُ. 2.""الاسْمُ الْمُتَمَكِّنُ"" : هُوَ الاسْمُ الْمُعْرَبُ، وَهُوَ قِسْمَانِ : أ. مُتَمَكِّنٌ أَمْكَنُ: أَيِ الاسْمُ الْمُعْرَبُ، الَّذِي تَظْهَرُ فِي آخِرِه حَرَكَاتُ الإِعْرَاب مَعَ التَّنْوِينِ مِثْلُ : تِلْمِيذٌ، مُدَرِّسٌ.ب. مُتَمَكِّنٌ غَيْرُ أَمْكَنَ: أَيِ الْمَمْنُوعُ مِنَ الصَّرْفِ، أَيْ كُلُّ اسْمٍ يُجَرُّ بِفَتْحَةٍ عِوَضَ كَسْرَةٍ وَلاَ يَلْحَقُهُ التَّنْوِينُ، مِثْلُ: حَمْرَاءُ، مَعَاقِلُ. 3.""غَيْرُ مُتَمَكِّنٍ فِي النَّحْوِ"" : أَيْ مَا أَشْبَهَ الْحَرْفَ فَكَانَ مَبْنِيّاً مِثْلَهُ، مَثَلاً: كَيْفَ، أَيْنَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1171, 'مُتَمَلِّقٌ', 'متملق', 'اسم فاعل', 'ملق', 'متملق', 'متملق', 'فَا. مِنْ تَمَلَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَلَّقَ). ""مُتَمَلِّقٌ لِغَيْرِهِ"" : مُتَوَدِّدٌ، مُتَذَلِّلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1172, 'مُتَمِّمٌ', 'متمم', 'اسم فاعل', 'تمم', 'متمم', 'متم', 'فَا. مِنْ تَمَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَّمَ). ""مُتَمِّمٌ لِلْعَمَلِ"" : مُكَمِّلٌ ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1173, 'مُتَمَنِّي', 'متمني', 'اسم فاعل', 'مني', 'متمني', 'متمن', 'فا. من تَمَنَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَمَنَّى). ""مُتَمَنٍّ لآمَالٍ كَبِيرَةٍ"" : رَاغِبٌ فِي حُصُولِ طَلَبٍ يَأْمُلُ تَحْقِيقَهُ مَعَ صُعُوبَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1174, 'مُتَمَهِّلٌ', 'متمهل', 'اسم فاعل', 'مهل', 'متمهل', 'متمهل', 'فَا. مِنْ تَمَهَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَمَهَّلَ). 1. ""مُتَمَهِّلٌ فِي عَمَلِهِ"" : بَطِيءٌ فِيهِ. 2. ""يَمْشِي مُتَمَهِّلاً"" : يَمْشِي بِخَطَوَاتٍ بَطِيئَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1175, 'مُتَمَيِّزٌ', 'متميز', 'اسم فاعل', 'ميز', 'متميز', 'متمز', 'فَا. مِنْ تَمَيَّزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَمَيَّزَ). 1.""مُتَمَيِّزٌ فِي سُلُوكِهِ"" : مُنْفَرِدٌ. 2. ""قَامَ بِعَمَلٍ مُتمَيِّزٍ"" : بِعَمَلٍ لَهُ خَصَائِصُ مُعَيَّنَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1176, 'مُتَنَاثِرٌ', 'متناثر', 'اسم فاعل', 'نثر', 'متناثر', 'متنثر', 'فا. من تَنَاثَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَنَاثِرٌ-مُتَنَاثِرٌ، ةٌ [ن ث ر] (فا. من تَنَاثَرَ). ""غُبَارٌ مُتَنَاثِرٌ"" : مُوَزَّعٌ، مُشَتَّتٌ فِي كُلِّ جِهَةٍ. ""أَوْرَاقٌ مُتَنَاثِرَةٌ"" ""نُجُومٌ مُتَنَاثِرَةٌ"" ""بُيُوتٌ مُتَنَاثِرَةٌ بَيْنَ الْحُقُولِ فِي الهِضَابِ وَالْجِبالِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1177, 'مُتَنَاسِبٌ', 'متناسب', 'اسم فاعل', 'نسب', 'متناسب', 'متنسب', 'فا. من تَنَاسَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَنَاسَبَ). ""زِيٌّ مُتَنَاسِبٌ مَعَ قَامَتِهِ"" : مُتَلاَئِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1178, 'مُتَنَاسِقٌ', 'متناسق', 'اسم فاعل', 'نسق', 'متناسق', 'متنسق', 'فا. من تَنَاسَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَنَاسَقَ). ""عَمَلٌ مُتَنَاسِقٌ"": مُنْسَجِمٌ. ""يَسِيرُ بِخُطىً مُتَنَاسِقَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1179, 'مُتَنَاصِفٌ', 'متناصف', 'اسم فاعل', 'نصف', 'متناصف', 'متنصف', 'فَا. مِنْ تَنَاصَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَنَاصِفٌ-مُتَنَاصِفٌ، ةٌ [ن ص ف] (فَا. مِنْ تَنَاصَفَ). 1.""وَلَدٌ مُتَنَاصِفٌ"" : مُتَسَاوِي الْمَحَاسِنِ. 2.""أَرْضٌ مُتَنَاصِفَةٌ"" : مُتَسَاوِيَةُ الأَجْزَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1180, 'مُتَنَاعِمٌ', 'متناعم', 'اسم فاعل', 'نعم', 'متناعم', 'متنعم', 'فَا. مِنْ تَنَاعَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُتَنَاعِمٌ-مُتَنَاعِمٌ [ن ع م] (فَا. مِنْ تَنَاعَمَ). 1.""رَجُلٌ مُتَنَاعِمٌ"": حَسَنُ الْحَالِ، أَوْ كَثِيرُ الْمَالِ. 2.""نَبْتٌ مُتَنَاعِمٌ"" : مُسْتَوٍ، مُسْتَقِيمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1181, 'مُتَنَاغِمٌ', 'متناغم', 'اسم فاعل', 'نغم', 'متناغم', 'متنغم', 'فا. من تَنَاغَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَنَاغَمَ). 1.""أُسْلُوبٌ مُتَنَاغِمٌ"" : أُسْلُوبٌ يَحْكُمُهُ إِيقَاعٌ وَاحِدٌ. 2.""أَلْوَانٌ مُتَنَاغِمَةٌ"" : مُنْسَجِمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1182, 'مُتَنَافِرٌ', 'متنافر', 'اسم فاعل', 'نفر', 'متنافر', 'متنفر', 'فا. من تَنَافَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَنَافَرَ). 1.""أُسْلُوبٌ مُتَنَافِرٌ"" : أَلْفاظُهُ غَيْرُ مُتَناسِقَةٍ، غَيْرُ مُنْسَجِمَةٍ. 2.""أَلْوَانٌ مُتَنَافِرَةٌ"" : غَيْرُ مُتَنَاسِبَةٍ، لاَ انْسِجَامَ بَيْنَهَا. 3.""أَصْوَاتٌ مُتَنَافِرَةٌ"" : بِهَا نَشَازٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1183, 'مُتَنَاقِضٌ', 'متناقض', 'اسم فاعل', 'نقض', 'متناقض', 'متنقض', 'فا. من تَنَاقَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَنَاقَضَ). ""قَوْلُهُ مُتَنَاقِضٌ مَعَ فِعْلِهِ"" : غَيْرُ مُتَطَابِقٍ. ""وَلَقَدْ كَانَتْ سَارَّةُ وَهِنْدٌ عَلَى مِثَالَيْنِ مِنَ الأُنُوثَةِ مُتَنَاقِضَيْنِ"". (ع. م. العقاد)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1184, 'مُتَنَبِّهٌ', 'متنبه', 'اسم فاعل', 'نبه', 'متنبه', 'متنبه', 'فَا. مِنْ تَنَبَّهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَنَبَّهَ). ""جَلَسَ مُتَنَبِّهاً لِمَا قَدْ يَحْدُثُ"" : يَقِظاً، حَذِرًا، مُرْهِفاً لِلسَّمْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1185, 'مُتَنَزِّهٌ', 'متنزه', 'اسم فاعل', 'نزه', 'متنزه', 'متنزه', 'فَا. مِنْ تَنَزَّهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَنَزَّهَ). ""خَرَجَ مُتَنَزِّهاً فِي أَرْجَاءِ الْحَدِيقَةِ"" : خَرَجَ طَالِباً لِلنُّزْهَةِ مُرَوِّحاً عَنْ نَفْسِهِ. ""أَمْطَرَتِ السَّمَاءُ مَطَراً غَزِيراً عَلَى الْمُتَنَزِّهِينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1186, 'مُتَنَعِّمٌ', 'متنعم', 'اسم فاعل', 'نعم', 'متنعم', 'متنعم', 'فَا. مِنْ تَنَعَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَنَعَّمَ). ""يَعِيشُ مُتَنَعِّماً فِي ضَيْعَتِهِ"" : فِي بُحْبُوحَةِ عَيْشٍ، فِي نَعِيمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1187, 'مُتَنَفِّسٌ', 'متنفس', 'اسم فاعل', 'نفس', 'متنفس', 'متنفس', 'فَا. مِنْ تَنَفَّسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَنَفَّسَ). ""مُتَنَفِّسٌ بِصُعُوبَةٍ"" : مُدْخِلٌ الْهَوَاءَ إِلَى رِئَتَيْهِ وَمُخْرِجُهُ مِنْهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1188, 'مُتَنَقِّلٌ', 'متنقل', 'اسم فاعل', 'نقل', 'متنقل', 'متنقل', 'فا. من تَنَقَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من تَنَقَّلَ). 1. ""مُسَافِرٌ مُتَنَقِّلٌ"" : مُتَجَوِّلٌ مِنْ مَكَانٍ إِلَى آخَرَ. ""قَوَافِلُ مُتَنَقِّلَةٌ"". 2. ""مَعْرِضٌ مُتَنَقِّلٌ"" : مَعْرِضٌ يُنْقَلُ مِنْ مَكَانٍ إِلَى آخَرَ. ""مَكْتَبَةُ مُتَنَقِّلَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1189, 'مُتَنَكِّرٌ', 'متنكر', 'اسم فاعل', 'نكر', 'متنكر', 'متنكر', 'فَا. مِنْ تَنَكَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَنَكَّرَ). ""خَرَجَ مُتَنَكِّراً إِلَى الشَّارِعِ"" : لاَبِسًا قِنَاعاً أَوْ مُرْتَدِياً لِبَاساً غَيْرَ لِبَاسِهِ العَادِيِّ وَمُغَيِّراً مِنْ مَلاَمِحِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1190, 'مُتَنَمِّرٌ', 'متنمر', 'اسم فاعل', 'نمر', 'متنمر', 'متنمر', 'فَا. مِنْ تَنَمَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَنَمَّرَ).""وَلَدٌ مُشَاكِسٌ مُتَنَمِّرٌ"" : مُتَشَبِّهٌ بِالنَّمِرِ. ""فَإِذَا اسْتَفَزَّتْهَا امْرَأَةٌ و"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1191, 'مُتَنَوِّعٌ', 'متنوع', 'اسم فاعل', 'نوع', 'متنوع', 'متنع', 'فَا. مِنْ تَنَوَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَنَوَّعَ). 1.""مُتَنَوِّعُ الأَشْكَالِ"": مُخْتَلِفُهَا. ""أَصْنَافٌ مُتَنَوِّعَةٌ"". 2.""حَفْلَةُ مُتَنَوِّعَاتٍ"" : حَفْلَةٌ تُقَدَّمُ فِيهَا أَلْوَانٌ غِنَائِيَّةٌ مُخْتَلِفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1192, 'مُتَهَامِسٌ', 'متهامس', 'اسم فاعل', 'همس', 'متهامس', 'متهمس', 'فَا. مِنْ تَهَامَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَهَامَسَ). ""رَآهُمْ مُتَهَامِسِينَ وَلَمْ يَفْهَمْ مَا يُخَبِّئُونَ"" : كُلُّ وَاحِدٍ يَهْمِسُ فيِ أُذُنِ الآخَرِ. ""كُنَّ يَتَناَقَلْنَ الْحَدِيثَ مُتَهَامِسَاتٍ"". (أحمد بوزفور)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1193, 'مُتَهَاوِنٌ', 'متهاون', 'اسم فاعل', 'هون', 'متهاون', 'متهن', 'فَا. مِنْ تَهَاوَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَهَاوَنَ). ""مُتَهَاوِنٌ فِي عَمَلِهِ"" : الْمُتَرَاخِي فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1194, 'مُتَهَتِّكٌ', 'متهتك', 'اسم فاعل', 'هتك', 'متهتك', 'متهتك', 'فَا. مِنْ تَهَتَّكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَهَتَّكَ). ""رَجُلٌ مُتَهَتِّكٌ"" : مَنْ يُمَارِسُ أَعْمَالاً غَيْرَ مُحْتَشِمَةٍ وَلاَ يُبَالِي أَنْ يُهْتَكَ عِرْضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1195, 'مُتَهَجِّدٌ', 'متهجد', 'اسم فاعل', 'هجد', 'متهجد', 'متهجد', 'فَا. مِنْ تَهَجَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَهَجَّدَ). ""مُتَهَجِّدٌ فِي لَيَالِيهِ"" : قَائِمٌ مِنَ النَّوْمِ لَيْلاً لِلصَّلاَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1196, 'مُتَهَدِّجٌ', 'متهدج', 'اسم فاعل', 'هدج', 'متهدج', 'متهدج', 'فَا. مِنْ تَهَدَّجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَهَدَّجَ). ""كَانَ صَوْتُهُ مُتَهَدِّجاً مُتَكَسِّراً"" : أَيْ مُتَقَطِّعاً فِي ارْتِعَاشٍ. ""فَسَأَلَتْه مُتَهَكِّمَةً بِصَوْتٍ مُتَهَدِّجٍ مِنَ الغَضَبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1197, 'مُتَهَدِّمٌ', 'متهدم', 'اسم فاعل', 'هدم', 'متهدم', 'متهدم', 'فَا. مِنْ تَهَدَّمَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَهَدَّمَ). ""بَيْتٌ مُتَهَدِّمٌ"" : مُحَطَّمٌ، أَيْ تَحَطَّمَتْ، تَهَدَّمَتْ جُدْرَانُهُ. ""دُورٌ مُتَهَدِّمَةٌ"" ""تَرَكَتِ الْحَرْبُ الأَرْضَ خَرَاباً وَمُدُناً مُتَهَدِّمَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1198, 'مُتَهَذِّبٌ', 'متهذب', 'اسم فاعل', 'هذب', 'متهذب', 'متهذب', 'فَا. مِنْ تَهَذَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَهَذَّبَ). ""وَلَدٌ مُتَهَذِّبٌ"" : مُتَأَدِّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1199, 'مُتَهَكِّمٌ', 'متهكم', 'اسم فاعل', 'هكم', 'متهكم', 'متهكم', 'فَا. مِنْ تَهَكَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَهَكَّمَ). ""رَجُلٌ مُتَهَكِّمٌ"" : مُسْتَهْزِئٌ، أَي يَتَهَكَّمُ وَيَسْخَرُ مِنْ غَيْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1200, 'مُتَهَلِّلٌ', 'متهلل', 'اسم فاعل', 'هلل', 'متهلل', 'متهل', 'فَا. مِنْ تَهَلَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَهَلَّلَ). ""أَعْلَنَ عَنِ الخَبَرِ السَّارِّ مُتَهَلِّلَ الوَجْهِ"" : مُشْرِقَ، الوَجْهِ، مُبْتَهِجَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1201, 'مُتَهَوِّرٌ', 'متهور', 'اسم فاعل', 'هور', 'متهور', 'متهر', 'فَا. مِنْ تَهَوَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَهَوَّرَ). ""مُتَهَوِّرٌ فِي عَمَلِهِ"" : يَتَصَرَّفُ كَمَا اتَّفَقَ دُونَ تَفْكِيرٍ وَلاَ رَوِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1202, 'مُتَهَيِّبٌ', 'متهيب', 'اسم فاعل', 'هيب', 'متهيب', 'متهب', 'فَا. مِنْ تَهَيَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَهَيَّبَ). ""وَلَدٌ مُتَهَيِّبُ"" : خَائِفٌ، وَجِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1203, 'مُتَوَاتِرٌ', 'متواتر', 'اسم فاعل', 'وتر', 'متواتر', 'متتر', 'فَا. مِنْ تَوَاتَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَاتَرَ). ""حَدِيثٌ مُتَوَاتِرٌ"" : حَدِيثٌ رَوَاهُ عَدَدٌ مِنَ الرُّوَاةِ فَاسْتُبْعِدَ كَذِبُهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1204, 'مُتَوَارِي', 'متواري', 'اسم فاعل', 'وري', 'متواري', 'متر', 'فَا. مِنْ تَوَارَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَارَى). ""مُتَوَارٍ عَنِ الأَنْظَارِ"" : مُتَخَفٍّ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1205, 'مُتَوَازِنٌ', 'متوازن', 'اسم فاعل', 'وزن', 'متوازن', 'متزن', 'فَا. مِنْ تَوَازَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَازَنَ). 1.""رَجُلٌ مُتَوَازِنٌ فِي سُلُوكِهِ"" : مُعْتَدِلٌ، الضَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1206, 'مُتَوَازِي', 'متوازي', 'اسم فاعل', 'وزي', 'متوازي', 'متز', 'فَا. مِنْ تَوَازَى', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَازَى). 1.""عَمَلُهُ مُتَوَازٍ مَعَ سُلُوكِهِ"" : مُتَقَابِلٌ. 2.""مُتَوَازِي الأَضْلاَعِ"" (هن) : شَكْلٌ هَنْدَسِيٌّ مُغْلَقٌ ذُو أَرْبَعَةِ أَضْلاَعٍ، ضِلْعَاه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1207, 'مُتَوَاصِلٌ', 'متواصل', 'اسم فاعل', 'وصل', 'متواصل', 'متصل', 'فَا. مِنْ تَوَاصَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَاصَلَ). ""عَمَلٌ مُتَواصِلٌ"" : مُسْتَمِرٌّ، غَيْرُ مُنْقَطِعٍ. ""يَسْعَى في سَبِيلِ التَّعْلِيمِ سَعْياً ثَابِتاً وَجُهْداً مُتَوَاصِلاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1208, 'مُتَوَاضِعٌ', 'متواضع', 'اسم فاعل', 'وضع', 'متواضع', 'متضع', 'فَا. مِنْ تَوَاضَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". (فَا. مِنْ تَوَاضَعَ). ""رَجُلٌ مُتَوَاضِعٌ"" : غَيْرُ مُتَكَبِّرٍ، غَيْرُ مُتَعَجْرِفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1209, 'مُتَوَاطِئٌ', 'متواطئ', 'اسم فاعل', 'وطأ', 'متواطء', 'متط', 'فَا. مِنْ تَوَاطَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَاطَأَ). ""مُتَوَاطِئٌ مَعَ الْمُتَآمِرِينَ"" : مُشَارِكٌ مَعَهُمْ فِي تَآمُرِهِمْ، مُتَآمِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1210, 'مُتَوَافِرٌ', 'متوافر', 'اسم فاعل', 'وفر', 'متوافر', 'متفر', 'فَا. مِنْ تَوَافَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَافَرَ). 1.""مُتَوَافِرُ العَدَدِ"" : مُتَزَايِدٌ، مُتَكَاثِرٌ. 2.""قَوْمٌ مُتَوَافِرُونَ"": كَثِيرُونَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1211, 'مُتَوَافِقٌ', 'متوافق', 'اسم فاعل', 'وفق', 'متوافق', 'متفق', 'فَا. مِنْ تَوَافَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَافَقَ). ""مُتَوَافِقٌ مَعَ صَاحِبهِ"" : مُتَّفِقٌ مَعَهُ، مُنْسَجِمٌ. ""يَرْوِي "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1212, 'مُتَوَطِّدٌ', 'متوطد', 'اسم فاعل', 'وطد', 'متوطد', 'متطد', 'فَا. مِنْ تَوَطَّدَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَطَّدَ). ""مُتَوَطِّدُ الأَرْكَانِ"" : ثَابِتٌ عَلَى الدَّوَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1213, 'مُتَوَالِي', 'متوالي', 'اسم فاعل', 'ولي', 'متوالي', 'متل', 'فَا. مِنْ تَوَالَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَالَى). 1.""جُهْدٌ مُتَوَالٍ"" : مُتَتَابِعٌ. ""سَنَوَاتٌ مُتَوَالِيَةٌ"" ""بَقِيتُ أَنْتَظِرُهُ خَمْسَ سَاعَاتٍ مُتَوَالِيَاتٍ"". 2.""مُتَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1214, 'مُتَوَانِي', 'متواني', 'اسم فاعل', 'وني', 'متواني', 'متن', 'فَا. مِنْ تَوَانَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَانَى). ""مُتَوَانٍ فِي "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1215, 'مُتَوَتِّرٌ', 'متوتر', 'اسم فاعل', 'وتر', 'متوتر', 'متتر', 'فَا. مِنْ تَوَتَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَوَتَّرَ). 1.""مُتَوَتِّرُ الأَعْصَابِ"" : مَنْ كَانَتْ أَعْصَابُهُ شَدِيدَةَ التَّوَتُّرِ وَالانْقِبَاضِ وَالانْفِعَالِ عَكْسَ اللُّيُونَةِ. ""أَعْصَابٌ مُتَوَتِّرَةٌ"". 2.""عَلاَقَاتٌ مُتَوَتِّرَةٌ"" : عَلاَقَاتٌ يَسُودُهَا الْخِلاَفُ وَالْخِصَامُ وَعَدَمُ التَّفَاهُمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1216, 'مُتَوَحِّدٌ', 'متوحد', 'اسم فاعل', 'وحد', 'متوحد', 'متحد', 'فَا. مِنْ تَوَحَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَحَّدَ). 1.""مُتَوَحِّدٌ فِي بَيْتِهِ"" : الْمُنْفَرِدُ بِنَفْسِهِ. 2.""مُتَوَحِّدٌ فِي خُلْوَتِهِ"" : الْمُنْقَطِعُ عَنِ النَّاسِ تَنَسُّكاً وَتَعَبُّداً. ""المتَوَحِّدُونَ مِنَ الرُّهْبَانِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1217, 'مُتَوَحِّشٌ', 'متوحش', 'اسم فاعل', 'وحش', 'متوحش', 'متحش', 'فَا. مِنْ تَوَحَّشَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَحَّشَ). 1.""مَكَانٌ مُتَوَحِّشٌ"" : مَكَانٌ قَفْرٌ. 2.""رَجُلٌ مُتَوَحِّشٌ"" : أَيْ صَارَ كَالوَحْشِ. ""وَجَدَهَا مُتَوَحِّشَةً مَحْرُومَةً مِنْ نِعْمَةِ الأُنُوثَةِ"". (ن. محفوظ). 3.""مُتَوَحِّشٌ فِي خُلْوَتِهِ"" : شَاعِرٌ بِالوَحْشَةِ وَعَدَمِ الاسْتِئْنَاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1218, 'مُتَوَرِّمٌ', 'متورم', 'اسم فاعل', 'ورم', 'متورم', 'مترم', 'فَا. مِنْ تَوَرَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ تَوَرَّمَ). ""وَجْهٌ مُتَوَرِّمٌ"" : مُنْتَفِخٌ. ""جَاءَ يَشْكُو جُرْحَهُ الْمُتَوَرِّمَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1219, 'مُتَوَسِّدٌ', 'متوسد', 'اسم فاعل', 'وسد', 'متوسد', 'متسد', 'فَا. مِنْ تَوَسَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَسَّدَ). 1.""مُتَوَسِّدٌ ذِرَاعَهُ"" : مُتَّكِئٌ. 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1220, 'مُتَوَسِّطٌ', 'متوسط', 'اسم فاعل', 'وسط', 'متوسط', 'متسط', 'فَا. مِنْ تَوَسَّطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَسَّطَ). 1.""مُتَوَسِّطُ القَامَةِ"" : مُعْتَدِلُهَا. ""مُتَوَسِّطُ الْحَجْمِ"": أَيْ مَا بَيْنَ الكَبِيرِ وَالصَّغِيرِ. 2.""مُتَوَسِّطُ الْحَالِ"" : لَيْسَ بِالغَنِيِّ وَلاَ بِالفَقِيرِ. ""فِئَةٌ اِجْتِمَاعِيَّةٌ مُتَوَسِّطَةٌ"". 3.""مُتَوَسِّطُ الْحَرَارَةِ فِي البِلاَدِ"" : مُعَدَّلُهَا. 4.""البَحْرُ الأَبْيَضُ الْمُتَوَسِّطُ"" (جغ) : بَحْرٌ شِبْهُ مُغْلَقٍ، إِذْ لاَ يَتَّصِلُ بِالمحُيِطِ الأَطْلَسِيِّ إِلاَّ عَبْرَ مَضِيقِ ج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1221, 'مُتَوَسِّلٌ', 'متوسل', 'اسم فاعل', 'وسل', 'متوسل', 'متسل', 'فَا. مِنْ تَوَسَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَسَّلَ). ""دَقَّ بَابَهُ مُتَوَسِّلاً"" : مُسْتَعْطِفاً، أَيْ مَنْ يَطْلُبُ الاسْتِعْطَافَ وَالرَّحْمَةَ. ""عَادَ خَائِباً مُتَوَسِّلاً بِنَظَرَاتٍ ذَلِيلَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1222, 'مُتَوَهِّجٌ', 'متوهج', 'اسم فاعل', 'وهج', 'متوهج', 'متهج', 'فَا. مِنْ تَوَهَّجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَهَّجَ). 1.""نُورٌ مُتَوَهِّجٌ"" : مُشْتَعِلٌ. 2.""فِكْرٌ مُتَوَهِّجٌ"" : مُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1223, 'مُتَوَظِّفٌ', 'متوظف', 'اسم فاعل', 'وظف', 'متوظف', 'متظف', 'فَا. مِنْ تَوَظَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَظَّفَ). ""مُتَوَظِّفٌ فِي إِدَارَةِ كَذَا"" : أَيْ يَشْتَغِلُ بِأَعْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1224, 'مُتَوَعِّدٌ', 'متوعد', 'اسم فاعل', 'وعد', 'متوعد', 'متعد', 'فَا. مِنْ تَوَعَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَعَّدَ). ""جَاءهُ مُتَوَعِّداً"" : مُهَدِّداً، أَيْ مَنْ يُهَدِّدُ غَيْرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1225, 'مُتَوَعِّكٌ', 'متوعك', 'اسم فاعل', 'وعك', 'متوعك', 'متعك', 'فَا. مِنْ تَوَعَّكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَعَّكَ). ""مُتَوَعِّكٌ فِي ص"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1226, 'مُتَوَفِّي', 'متوفي', 'اسم فاعل', 'وفي', 'متوفي', 'متف', 'فَا. مِنْ تَوَفَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَفَّى). 1.""مُتَوَفٍّ فِي اللَّيْلِ"" : وَافَاهُ الأَجَلُ. 2.""مُتَوَفٍّ حَقَّهُ"" : آخِذٌ حَقَّهُ وَافِياً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1227, 'مُتَوَقِّدٌ', 'متوقد', 'اسم فاعل', 'وقد', 'متوقد', 'متقد', 'فا. مِنْ تَوَقَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِنْ تَوَقَّدَ). 1.""نَارٌ مُتَوَقِّدَةٌ"" : مُشْتَعِلَةٌ. 2.""لَهُ ذِهْنٌ مُتَوَقِّدٌ"" : حَاضِرُ البَدِيهَةِ، مُتَوَهِّجٌ. ""مُتَوَقِّدُ الذِّهْنِ حَادُّ الذَّكَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1228, 'مُتَوَقِّعٌ', 'متوقع', 'اسم فاعل', 'وقع', 'متوقع', 'متقع', 'فَا. مِنْ تَوَقَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَقَّعَ). ""مُتَوَقِّعٌ حُدُوثَ كَوَارِثَ"" : مُدْرِكُ لِمَا سَيَحْدُثُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1229, 'مُتَوَكِّئٌ', 'متوكئ', 'اسم فاعل', 'وكأ', 'متوكء', 'متك', 'فَا. مِنْ تَوَكَّأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَكَّأَ). ""سَارَ مُتَمَهِّلاً مُتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1230, 'مُتَوَكِّلٌ', 'متوكل', 'اسم فاعل', 'وكل', 'متوكل', 'متكل', 'فَا. مِنْ تَوَكَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَكَّلَ). ""مُتَوَكِّلٌ عَلَى الله"" : مُعْتَمِدٌ عَلَيْهِ.آل عمران آية 122 وَعَلَى الله فَلْيَتَوَكَّلِ الْمُتَوَكِّلُونَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1231, 'مُتَوَلِّدٌ', 'متولد', 'اسم فاعل', 'ولد', 'متولد', 'متلد', 'فَا. مِنْ تَوَلَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَلَّدَ). ""أَعْمَالٌ مُتَوَلِّدَةٌ عَنْهَا نَتَائِجُ وَخِيمَةٌ"" : نَاشِئَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1232, 'ثَوَابِتُ', 'ثوابت', 'اسم فاعل', '', 'ثوابت', 'ثبت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1233, 'مُتَوَهِّمٌ', 'متوهم', 'اسم فاعل', 'وهم', 'متوهم', 'متهم', 'فَا. مِنْ تَوَهَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَوَهَّمَ). ""مُتَوَهِّمٌ لِأُمُورٍ وَخِيمَةٍ"" : مُتَخَيِّلٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1234, 'مُتَيَسِّرٌ', 'متيسر', 'اسم فاعل', 'يسر', 'متيسر', 'متسر', 'فَا. مِنْ تَيَسَّرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَيَسَّرَ). ""أَمْرٌ مُتَيَسِّرٌ"" : أَمْرٌ مُتَاحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1235, 'مُتَيَقِّظٌ', 'متيقظ', 'اسم فاعل', 'يقظ', 'متيقظ', 'متقظ', 'فَا. مِنْ تَيَقَّظَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ تَيَقَّظَ). 1.""مُتَيَقِّظٌ مِنْ نَوْمِهِ"" : صَاحٍ مِنْهُ. 2.""مُتَيَقِظٌ فِي عَمَلِهِ"": مُتَنَبِّهٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1236, 'مُثَابِرٌ', 'مثابر', 'اسم فاعل', 'ثبر', 'مثابر', 'مثبر', 'فَا. مِنْ ثَابَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ ثَابَرَ). ""مُثَابِرٌ عَلَى العَمَلِ"" : مُوَاظِبٌ، مُدَاوِمٌ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1237, 'ثَائِرٌ', 'ثائر', 'اسم فاعل', 'ثأر،ثور', 'ثاءر', 'ثر', 'فا. مِنْ ثَارَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":ثُوَّارٌ:ثَوَائِرُ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ ثَارَ). ‍‍‍‍‍‌1.""ثَائِرٌ علَى مَا حَلَّ بِهِ مِنْ غُبْنٍ"" : غَضْبَانُ. 2.""ثَارَ ثَائِرُهُ"" : ثَارَ غَضَبُهُ. 3.""ثَائِرٌ عَلَى قَتْلِ أخِيهِ"" : مَنْ يَبْقَى عَلَى شَيْءٍ حَتّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1238, 'ثَوَائِرُ', 'ثوائر', 'اسم فاعل', '', 'ثواءر', 'ثر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1239, 'ثُوَّارٌ', 'ثوار', 'اسم فاعل', '', 'ثوار', 'ثر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1240, 'ثَوَرَةٌ', 'ثورة', 'اسم فاعل', '', 'ثورة', 'ثرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1241, 'ثَابِتٌ', 'ثابت', 'اسم فاعل', 'ثبت', 'ثابت', 'ثبت', 'فا. مِنْ ثَبَتَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":ثَوَابِتُ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ ثَبَتَ). 1.""أسَاسٌ ثَابِتٌ لاَ يَتَزَعْزَعُ"" : رَاسِخٌ، مَتِينٌ. 2.""ثَابِتٌ فِي مَوْقِفِهِ لاَ يَحِيدُ عَنْهُ"" : رَاسِخٌ، مُقيمٌ عَلَيْهِ لاَ يُغَيِّرُهُ.إبراهيم آية 24 كَلِمَةٌ طَيِّبَةٌ كَشَجَرَةٍ طَيِّبَةٍ أصْلُهَا ثَابِتٌ وَفَرْعُهَا فِي السَّمَاءِ .(قرآن). 3.""ثَابِتُ الإرَادَةِ وَالعَزْمِ"" : الْمُسْتَقِرُّ، الْمُصَمِّمُ القَصْدِ. 4.""ثَابِتُ الجَأْشِ"" : الجِرِّيءُ، الشُّجَاعُ. 5.""عَدَدٌ ثَابِـتٌ"": عَدَدٌ لاَ يَتَغَيَّرُ مِثْلَ 3 و 4. 6.""مِنَ الثَّابِتِ أنَّ الأرْضَ تَدُورُ حَوْلَ الشَّمْسِ "" : مِنَ الْمَعْلُومِ، مِنَ الْمُؤَكَّدِ وَالْمُقَرَّرِ. 7.""أَمْلا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1242, 'ثوامر', 'ثوامر', 'اسم فاعل', '', 'ثوامر', 'ثمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
