INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1245, 'مُثَبِّطٌ', 'مثبط', 'اسم فاعل', 'ثبط', 'مثبط', 'مثبط', 'فَا. مِنْ ثَبَّطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ ثَبَّطَ). ""مُثَبِّطٌ لِلْعَزَائِمِ"" : مُحْبِطُهَا، مَنْ لاَ يُشَجِّعُ عَلَى القِيَامِ بِشَيْءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1246, 'ثَاقِبٌ', 'ثاقب', 'اسم فاعل', 'ثقب', 'ثاقب', 'ثقب', 'فا. من ثَقِبَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فا. من ثَقِبَ). 1.""لَهُ رَأْيٌ ثَاقِبٌ"" : نَافِذٌ، عَمِيقٌ. 2.""ثَاقِبُ النَّظَرِ"" : حَادُّ النَّظَرِ، بَصِيرٌ، نَافِذٌ. ""نَظَرٌ ثَاقِبٌ"" "" لَهُ عَيْنَانِ ثَاقِبَتَانِ"". 3.""الثَّاقِبُ مِنَ العُقُولِ"" : الرَّاجِحُ. 4. ""هُوَ ثَاقِبُ الفِكْرِ"" : أَلْمَعِيٌّ، ذَكِيٌّ. 5.""ثَاقِبَةُ الوَرَقِ"" : آلَةٌ تَثْقُبُ الوَرَقَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1247, 'ثواقب', 'ثواقب', 'اسم فاعل', '', 'ثواقب', 'ثقب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1248, 'مُثَقِّفٌ', 'مثقف', 'اسم فاعل', 'ثقف', 'مثقف', 'مثقف', 'فَا. مِنْ ثَقَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ ثَقَّفَ). ""مُثَقِّفُ الأَجْيَالِ"" : مُهَذِّبُهَا، مُعَلِّمُهَا، مُرَبِّيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1249, 'ثَالِثٌ', 'ثالث', 'اسم فاعل', 'ثلث', 'ثالث', 'ثلث', 'فَا. مِنْ ثَلَثَ', '', 'Ta', 'مفرد', 'DnT', '', '', '', '', '', '', '', '', '', '', '', '"ثَالِثٌ-ثَالِثٌ، ةٌ [ث ل ث] (فَا. مِنْ ثَلَثَ). 1.عَدَدٌ يَدُلُّ عَلَى التَّرْتِيبِ، وَيَكُونُ مَعْدُودُهُ مُذَكَّراً : ""هُوَ الثَّالِثُ فِي الفَصْلِ"" : أيْ مَنْ كَانَتْ رُتْبَتُهُ بَيْنَ الثَّانِي وَالرَّابِعِ، وَيُعْرَبُ نَعْتاً فِي المِثَالِ التَّالي: ""وَصَلَ الفَائِزُ الثَّالِثُ"". وَإذَا لَمْ يُذْكَرْ مَعْدُودُهُ: ""وَصَلَ الثَّالِثُ"" فَيُعْرَبُ فاعل وَصَلَ، وَإِذا قُلْتُ : ""كَلَّمْتُ الثَّالِثَ"" : يُعْرَبُ مَفْعُولاً بِهِ، وَهَكذَا يُعْرَبُ حَسَبَ مَوْقِعِهِ فِي الجُمْلَةِ. ""كَانَ الثَّالِثَ مِنْ بَيْنِ الْمُتَسَابِقِينَ"" ""الجُزْءُ الثَّالِثُ"". وَفِي حَالَةِ الثَّأْن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1250, 'ثوالث', 'ثوالث', 'اسم فاعل', '', 'ثوالث', 'ثلث', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1251, 'مُثَلِّجٌ', 'مثلج', 'اسم فاعل', 'ثلج', 'مثلج', 'مثلج', 'فَا. مِنْ ثَلَّجَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. مِنْ ثَلَّجَ). ""جِهَازٌ مُثَلِّجٌ"" : أَيْ يُحَوِّلُ الْمَوَادَّ إِلَى ثَلْجٍ. ""مُثَلِّجَةُ الثّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1252, 'ثَامِرٌ', 'ثامر', 'اسم فاعل', 'ثمر', 'ثامر', 'ثمر', 'فَا. مِنْ ثَمَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"ثَامِرٌ-ثَامِرٌ، ةٌ [ث م ر] (فَا. مِنْ ثَمَرَ). ""شَجَرٌ ثَامِرٌ"" : شَجَرٌ طَلَعَ ثَمَرُهُ."', '');
