INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1264, 'ثَامِنٌ', 'ثامن', 'اسم فاعل', 'ثمن', 'ثامن', 'ثمن', 'فا. مِنْ ثَمَنَ', '', 'Ta', 'مفرد', 'DnT', '', '', '', '', '', '', '', '', '', '', '', '"ثَامِنٌ-ثَامِنٌ، ةٌ [ث م ن]. (فا. مِنْ ثَمَنَ). 1. عَدَدٌ يَدُلُّ عَلى التَّرْتِيبِ، وَيَكُونُ مَعْدُودُهُ مُذَكَّراً : ""هُوَ الثَّامِنُ فِي الفَصْلِ"" : أيْ مَنْ كَانَتْ رُتْبَتُهُ بَيْنَ السَّابِعِ وَالتَّاسِعِ، وَيُعْرَبُ نَعْتاً فِي المِثَالِ التَّالِي: ""وَصَلَ الفَائِزُ الثَّامِنُ"" ؛ وَإذَا لَمْ يُذْكَرْ مَعْدُودُهُ : ""وَصَلَ الثَّامِنُ"" : يُعْرَبُ فَاعِلَ وَصَلَ، وَإذَا قُلْتُ ""كَلَّمْتُ الثَّامِنَ"": يُعْرَبُ مَفْعُولاً بِهِ، وَكَذَا يُعْرَبُ حَسَبَ مَوْقِعِهِ فِي الجُمْلَةِ. ""كَان"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1265, 'ثوامن', 'ثوامن', 'اسم فاعل', '', 'ثوامن', 'ثمن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1266, 'ثَانِي', 'ثاني', 'اسم فاعل', 'ثني', 'ثاني', 'ثن', 'فا، من ثَنَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', '', '":"', '', '', '', '', '', '', '', '', '"ثَانٍ-ثَانٍ، الثَّانِي، ةٌ [ث ن ي] (فا، من ثَنَى). 1. عَدَدٌ يَدُلُّ عَلَى التَّرْتِيبِ وَيَكُونُ مَعْدُودُهُ مُذَكَّراً : ""هُوَ الثَّانِي فِي الفَصْلِ"": أيْ مَنْ كَانَتْ رُتْبَتُهُ بَيْنَ الأوَّلِ وَالثَّالِثِ، وَيُعْرَبُ نَعْتاً فِي المِثَالِ التَّالِي : ""وَصَلَ الفَائِزُ الثَّانِي""، وإذَا لَمْ يُذْكَرْ مَعْدُودُهُ : ""وَصَلَ الثَّانِي"" : فَيُعْرَبُ فَاعِلَ وَصَلَ، وإذَا قُلْتُ : ""كَلَّمْتُ الثَّانِي"" : يُعْرَبُ مَفْعُولاً بِهِ، وَهكَذَا يُعْرَبُ حَسَبَ مَوْقِعِهِ فِي الجُمْلَةِ. ""كَانَ الثَّانِيَ مِنْ بَيْنِ الْمُتَسَابِقِينَ"" ""الجُزْءُ الثَّانِي"". وَفِي حَالَةِ التَّأْنِيثِ يَكُونُ الْمَعْدُودُ مُؤَنَّثاً : ""هِيَ الثَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1267, 'ثناة', 'ثناة', 'اسم فاعل', '', 'ثناة', 'ثنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
