INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1269, 'مُجَازِفٌ', 'مجازف', 'اسم فاعل', 'جزف', 'مجازف', 'مجزف', 'فا. من جَازَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من جَازَفَ). ""رَجُلٌ مُجَازِفٌ"" : مُخَاطِرٌ بِحَيَاتِهِ، مُغَامِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1270, 'جَائِبٌ', 'جائب', 'اسم فاعل', 'جيب', 'جاءب', 'جب', 'فَا. مِن جَابَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":جَوائِبُ"', '', '', '', '', '', '', '', '', '"(فَا. مِن جَابَ). 1.""قَضَى حَيَاتَهُ جَائِباً"" : مُسَافِراً. 2.""جَائِبُ العَيْنِ"" : الأَسَدُ. 3.""اِنْتَشَرَتِ الجَائِبَةُ"" : السخَبَرُ الَّذِي يَذِيعُ فِي الأَرْضِ مِنْ بَلَدٍ إِلَى آخَرَ. 4.""جَرِيدَةُ الجَوَائِبِ"" : جَرِيدَةُ الأَخْبَارِ الْمُنْتَشِرَةِ فِي البُلْدَانِ، اِسْمُ الجَرِيدَةِ الَّتِي أَسَّسَهَا أَحْمَدُ فَارِسٌ الشَّدْيَاقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1271, 'جَوائِبُ', 'جوائب', 'اسم فاعل', '', 'جواءب', 'جب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1272, 'جَائِحٌ', 'جائح', 'اسم فاعل', 'جوح', 'جاءح', 'جح', 'فَا. مِن جَاحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"جَائِحٌ-جَائِحٌ [ج و ح] (فَا. مِن جَاحَ). ""أَهْلَكَ الجَائِحُ النَّبَاتَ وَالزَّرْعَ وَالأَشْجَارَ"" : الجَرَادُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1273, 'جوائح', 'جوائح', 'اسم فاعل', '', 'جواءح', 'جح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1274, 'مُجَادِلٌ', 'مجادل', 'اسم فاعل', 'جدل', 'مجادل', 'مجدل', 'فَا. مِنْ جَادَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ جَادَلَ). ""مُجَادِلٌ فِي كُلِّ أَمْرٍ"" : مَنْ يُجَادِلُ وَيُحَاوِرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1275, 'جَائِرٌ', 'جائر', 'اسم فاعل', 'جور', 'جاءر', 'جر', 'فَا. من جَارَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. من جَارَ). 1.""كَانَ جَائِرًا فِي حُكْمِهِ"" : ظَالِماً، مُسْتَبِدّاً. ""هُوَ قَائِدٌ جَائِرٌ"" ""اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ سُلْطَانٍ جَائِرٍ وَنَدِيمٍ فَاجِرٍ"". (التوحيدي). 2.""كَانَتْ أَيَّامُهُ جَائِرَةً"" : ظَالِمَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1276, 'جوائر', 'جوائر', 'اسم فاعل', '', 'جواءر', 'جر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1277, 'جَائِزٌ', 'جائز', 'اسم فاعل', 'جوز', 'جاءز', 'جز', 'فَا. من جَازَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"جَائِزٌ-جَائِزٌ، ةٌ [ج و ز] (فَا. من جَازَ). ""هَذَا عَمَلٌ جَائِزٌ"" : مُبَاحٌ، مَسْمُوحٌ بِهِ. ""عَمَلٌ غَيْرُ جَائِزٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1278, 'جوائز', 'جوائز', 'اسم فاعل', '', 'جواءز', 'جز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1279, 'مُجَبِّرٌ', 'مجبر', 'اسم فاعل', 'جبر', 'مجبر', 'مجبر', 'فَا. مِنْ جَبَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُجَبِّرٌ-مُجَبِّرٌ، ةٌ [ج ب ر] (فَا. مِنْ جَبَّرَ). ""مُجَبِّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1280, 'جَائِعٌ', 'جائع', 'اسم فاعل', 'جوع', 'جاءع', 'جع', 'فَا. مِن جَاعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":جِيَاعٌ:جُوَّعٌ"', '', '', '', '', '', '', '', '', '"(فَا. مِن جَاعَ). ""وَجَدَهُ جَائِعاً لَمْ يَأْكُلْ مُنْذُ أُسْبُوعٍ"" : لَمْ يَذُقْ طَعَاماً عَكْسَ الشَّبْعَانِ."', '');
