INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1284, 'مُجَامِلٌ', 'مجامل', 'اسم فاعل', 'جمل', 'مجامل', 'مجمل', 'فَا. مِنْ جَامَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ جَامَلَ). ""كَانَ مُجَامِلاً لَهُ"" : مُحَابِياً مُتَأَدِّباً لاَ عَنِ اقْتِنَاعٍ أَوْ تَسْلِيمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1285, 'مُجَانِبٌ', 'مجانب', 'اسم فاعل', 'جنب', 'مجانب', 'مجنب', 'فَا. مِنْ جَانَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ جَانَبَ). ""مُجَانِبٌ لِلصَّوَابِ"" : بَعِيدٌ عَنِ الصَّوَابِ. ""مُجَانِبٌ لِلْحَقِيقَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1286, 'مُجَانِسٌ', 'مجانس', 'اسم فاعل', 'جنس', 'مجانس', 'مجنس', 'فَا. مِنْ جَانَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ جَانَسَ). ""آلاَتٌ مُجَانِسَةٌ"" : عَلَى شَاكِلَةٍ وَاحِدَةٍ، مُتَمَاثِلَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1287, 'مُجَاهِدٌ', 'مجاهد', 'اسم فاعل', 'جهد', 'مجاهد', 'مجهد', 'فا. من جَاهَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من جَاهَدَ). ""مُجَاهِدٌ فِي سَبِيلِ قَضِيَّةٍ مُقَدَّسَةٍ"" : مَنْ يُجَاهِدُ، يُنَاضِلُ، يُحَارِبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1288, 'مُجَاوِرٌ', 'مجاور', 'اسم فاعل', 'جور', 'مجاور', 'مجر', 'فَا. مِنْ جَاوَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ جَاوَرَ). 1.""مُجَاوِرٌ لَهُ فِي السَّكَنِ"" : مَنْ يُجَاوِرُهُ فِي السَّكَنِ، أَيْ يَسْكُنُ بِالقُرْبِ مِنْهُ. 2.""بَلَدٌ مُجَاوِرٌ"" : بَلَدٌ مُحَادٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1289, 'جواثي', 'جواثي', 'اسم فاعل', '', 'جواثي', 'جث', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
