INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1332, 'جَارِي', 'جاري', 'اسم فاعل', 'جري', 'جاري', 'جر', 'فَا. من جَرَى', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"جَارٍ-جَارٍ، الجَارِي [ج ر ي] (فَا. من جَرَى). 1.""نَهْرٌ جَارٍ فِي كُلِّ السَّنَةِ"" : لاَيَجِفُّ مِنَ الْمَاءِ. 2.""حَرَكَةٌ جَارِيَةٌ"" : مُتَّصِلَةٌ غَيْرُ مُنْقَطِعَةٍ. ""اللٌّغَةُ جَارِيَةٌ عَلَى التَّوَسُّعِ"". (التَّوْحِيدِيُّ) ""صَدَقَةٌ جَار"', '');
