INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1342, 'جَافٌّ', 'جاف', 'اسم فاعل', 'جفف', 'جاف', 'جف', 'فَا. من جَفَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. من جَفَّ). 1. ""بَعْدَ سَنَةٍ مِنَ الجَفَافِ أَصْبَحَ الْمَكَانُ جَافّاً"" : يَابِساً، نَاشِفًا. ""يَعِيشُ أَكْثَر أَيَّامِهِ عَلَى البُقُولِ الجَافَّةِ"" (أ. أمين). 2.""أَجَابَهُ بِلَهْجَةٍ جَافَّةٍ"" : فَظَّةٍ، خَشِنَةٍ، قَاسِيَةٍ. 3.""قَلَمُ حِبْرٍ جَافٍّ"" : قَلَمٌ بِهِ مِدَادٌ جَامِدٌ، غَيْرُ سَائِلٍ."', '');
