INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1352, 'مُجَلِّدٌ', 'مجلد', 'اسم فاعل', 'جلد', 'مجلد', 'مجلد', 'فَا. مِنْ جَلَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ جَلَّدَ). ""مُجَلِّدُ الكُت"', '');
