INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1358, 'مُجَلِّي', 'مجلي', 'اسم فاعل', 'جلي', 'مجلي', 'مجل', 'فَا. مِنْ جَلَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ جَلَّى). هُوَ الْمُجَلِّي فِي السِّبَاقِ"" : الأَوَّلُ بِلاَ مُنَازِعٍ. ""الْمُجَلِّي فِي الصَّفِّ"" ""فَرَسٌ مُجَلٍّ"" ""كَاتِبٌ مُجَلٍّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1359, 'جَانِحٌ', 'جانح', 'اسم فاعل', 'جنح', 'جانح', 'جنح', 'فا. من جَنَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":جَوَانِحُ"', '', '', '', '', '', '', '', '', '"(فا. من جَنَحَ). 1. ""جَانِحُ البِنَايَةِ"" : الجَانِبُ مِنْهَا، الْمَائِلُ. 2.""الوَلَدُ الجَانِحُ"" : لَفْظٌ يُطْلَقُ عَلَى الْمُرَاهِقِ الَّذِي يَجْنَحُ إِلَى ارْتِكَابِ الْمُخَالَفَاتِ وَالخُرُوجِ عَنِ القَانوُنِ. 3.""الحَدَثُ الجَانِحُ"" : مَنِ اقْتَرَفَ جَرِيمَةً. 4. ""جَاِنحُ الإِنْسَانِ"" : الضِّلْعُ القَصِيَرةُ مِمَّا يَلِي الصَّدْرَ. 5. ""بَيْنَ جَوَانِحِهِ"" : فِي قَلْبِهِ وَأَعْمَاقِهِ، جَوَارِحِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1360, 'جَوَامِحُ', 'جوامح', 'اسم فاعل', '', 'جوامح', 'جمح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1361, 'مُجَمِّدٌ', 'مجمد', 'اسم فاعل', 'جمد', 'مجمد', 'مجمد', 'فَا. مِنْ جَمَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ جَمَّدَ). 1.""آلَةٌ مُجَمِّدَةٌ"" : أَيْ تُجَمِّدُ الْمَاءَ وَالسَّوَائِلَ. 2.""مُجَمِّدٌ لِنَشَاطِهِ فِي الْجَمْعِيَّةِ"" : مُوقِفٌ لِنَشَاطِهِ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1362, 'جَامِعٌ', 'جامع', 'اسم فاعل', 'جمع', 'جامع', 'جمع', 'فا. من جَمَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":جَوَامِعُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من جَمَعَ). 1. ""ذَهَبَ إِلَى الجَامِعِ لأَدَاءِ الصَّلاَةِ"" : الْمَسْجِدُ الكَبِيرُ. 2. ""اليَوْمُ الجَامِعُ"" : يَوْمُ الجُمُعَةِ. 3. ""جَامِعُ الطَّوَابِعِ البَرِيدِيَّةِ"" : الَّذِي يَجْمَعُ الطَّوَابِعَ. وَهُوَ مِنْ هُوَاتِهَا. 4. ""كَانَ كَلاَمُهُ جَامِعاً مَانِعاً"": شَامِلاً مُكَثَّفاً مُعَبِّراً. ""تَعْرِيفٌ جَامِعٌ"". 5.""رَجُلٌ جَامِعٌ لأَمْرِهِ"" : مُلِمٌّ وَضَابِطٌ وَحَازِمٌ لأَمْرِهِ. 6.""جَامِعُ الأَمْوَالِ"" : الَّذِي يَجْمَعُهَا وَيُرَاكِمُهَا. ""لَوْ عَلِمَ الجَامِعُ أَنَّهُ يَجْمَعُ لِلْوَارِثِ مَا جَمَعَ"". (مثل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1363, 'جَوَامِعُ', 'جوامع', 'اسم فاعل', '', 'جوامع', 'جمع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
