INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1366, 'جَانٌّ', 'جان', 'اسم فاعل', 'جنن', 'جان', 'جن', 'فَا. من جَنَّ', '', '', 'مفرد', '', '', '', '"جِنَّانٌ"', '', '', '', '', '', '', '', '', '"(فَا. من جَنَّ). 1.الرحمن آية 56 لَمْ يَطْمِثْهُنَّ إِنْسٌ قَبْلَهُمْ وَلاَ جَانٌّ . (قرآن) : جِنٌّ. 2. إِنَّ فِيهَا جَانّاً كَثِيراً (حديث) : نَوْعٌ مِنَ الحيَّاتِ أَكْحَلُ العَيْنَيْنِ يَضْرِبُ إِلَى الصُّفْرَةِ، لاَ يُؤْذِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1367, 'جِنَّانٌ', 'جنان', 'اسم فاعل', '', 'جنان', 'جنن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1368, 'مُجَنِّبٌ', 'مجنب', 'اسم فاعل', 'جنب', 'مجنب', 'مجنب', 'فَا. مِنْ جَنَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُجَنِّبٌ-مُجَنِّبٌ [ج ن ب] (فَا. مِنْ جَنَّبَ). ""مُجَنِّبٌ نَفْسَهُ الشَّرَّ وَالْخُسْرَانَ"" : مُبْعِدُهَا عَنْ..."', '');
