INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1373, 'جَانِي', 'جاني', 'اسم فاعل', 'جنى', 'جاني', 'جن', 'فا. من جَنَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":جُنَاةٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من جَنَى). ""تَأَكَّدُوا مِنْ شَخْصِيَّةِ الجَانِي"" : مَنِ ارْتَكَبَ ذَنْباً أَوْ جُرْماً."', '');
