INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1376, 'جَاهِدٌ', 'جاهد', 'اسم فاعل', 'جهد', 'جاهد', 'جهد', 'فَا. من جَهَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"جَاهِدٌ-جَاهِدٌ [ج هـ د] (فَا. من جَهَدَ). 1. ""بَذَلَ جُهْداً جَاهِداً"" : جُهْداً بَالِغاً، فَوْقَ الطَّاقَةِ، كَبِيراً. 2. ""سَارَ سَيْراً جَاهِداً فِي الصَّحْرَاءِ"" : تَكَلَّفَ السَّيْرَ أَكْثَرَ مِنْ طَاقَتِهِ."', '');
