INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1380, 'جَاهِزٌ', 'جاهز', 'اسم فاعل', 'جهز', 'جاهز', 'جهز', 'فَا. من جَهَزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. من جَهَزَ). 1. ""أَصْبَحَ البَيْتُ جَاهِزًا لِلسَّكَنِ"" : مُهَيَّأ. 2. ""اِشْتَرَى مَلاَبِسَ جَاهِزَةً "" : مُفَصَّلَةً وَمَخِيطَةً. ""ثَوْبٌ جَاهِزٌ"" ""أَثْوَابٌ جَاهِزَةٌ"". 3. ""لَهُ أَمْوَالٌ جَاهِزَةٌ لِلاسْتِثْمَارِ"" : قَابِلَةٌ لِتُسْتَثْمَرَ."', '');
