INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1384, 'مُجَهِّزٌ', 'مجهز', 'اسم فاعل', 'جهز', 'مجهز', 'مجهز', 'فا. من جَهَّزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من جَهَّزَ). ""مُجَهِّزُ السُّوقِ بِكُلِّ الْمَوَادِّ الغِذَائِيَّةِ"" : مُزَوِّدُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1385, 'جَاهِلٌ', 'جاهل', 'اسم فاعل', 'جهل', 'جاهل', 'جهل', 'فا. من جَهَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":جُهَّالٌ:جُهَلاَءُ:جَهَلَةٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من جَهَلَ). 1. ""إِنَّهُ جَاهِلٌ لاَ يَقْرَأُ وَلاَ يَكْتُبُ"" : العَامِّيُّ، الغَبِيُّ، الأُمِّيُّ. 2. ""جَاهِلٌ بِأُمُورِ التِّجَارَةِ"" : لاَ يَفْقَهُ فِيهَا شَيْئاً. ""الجَاهِلُ عَدُوُّ نَفْسِهِ، فَكَيْفَ يَكُونُ صَدِيقاً لِغَيْرِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1386, 'جواهل', 'جواهل', 'اسم فاعل', '', 'جواهل', 'جهل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1387, 'جُهَّالٌ', 'جهال', 'اسم فاعل', '', 'جهال', 'جهل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1388, 'جُهَلاَءُ', 'جهلاء', 'اسم فاعل', '', 'جهلاء', 'جهل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1389, 'مُحَاسِبٌ', 'محاسب', 'اسم فاعل', 'حسب', 'محاسب', 'محسب', 'فَا. مِنْ حَاسَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ حَاسَبَ). 1.""مُحَاسِبُ الإِدَارَةِ"" : الْمُكَلَّفُ بِالحِسَابَاتِ. 2.""مُحَاسِبٌ لِنَفْسِهِ"" : مُنَاقِشٌ لَهَا وَمُدَقِّقٌ فِي أَهْوَائِهَا. ""إِنِّي مُحَاسِبٌ لِقَلْبِي إِذَا مَالَ وَلِلِسَانِي إِذَا قَالَ"". (أ. الريحاني). 3.""هُوَ اللَّهُ الْمُحَاسِبُ"" : اللَّهُ الْحَاكِمُ الْمُقْتَدِرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1390, 'مُحَابِي', 'محابي', 'اسم فاعل', 'حبو', 'محابي', 'محب', 'فَا. مِنْ حَابَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ حَابَى). ""رَجُلٌ مُحَابٍ"" : مُتَسَاهِلٌ، مُتَسَامِحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1391, 'مُحَاذِي', 'محاذي', 'اسم فاعل', 'حذو', 'محاذي', 'محذ', 'فَا. مِنْ حَاذَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ حَاذَى). ""صَارَ مُحَاذِياً لَهُ"" : مُقَابِلاً لَهُ، إِزَاءهُ. ""هُوَ مُحَاذَاكَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1392, 'حائِرٌ', 'حائر', 'اسم فاعل', 'حور', 'حاءر', 'حر', 'فا. مِنْ حارَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حِيرانٌ:حوران:حوائِرُ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ حارَ). 1.""وَجَدْتُهُ حائِراً في أَمْرِهِ"" : مُرْتَبِكاً مُتَرَدِّداً مُضْطَرِباً، مُتَحَيِّراً. ""فَتاةٌ حائِرَةٌ بَيْنَ نَعَمْ وَلاَ"". 2.""وَلَدٌ حائِرٌ"" : مَهْزولٌ، ضَعيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1393, 'حِيرانٌ', 'حيران', 'اسم فاعل', '', 'حيران', 'حرن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
