INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1395, 'حوائِرُ', 'حوائر', 'اسم فاعل', '', 'حواءر', 'حر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1396, 'مُحَارِبٌ', 'محارب', 'اسم فاعل', 'حرب', 'محارب', 'محرب', 'فَا. مِنْ حَارَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ حَارَبَ). ""مُحَارِبٌ لِأَعْدَائِهِ"" : مُقَاتِلٌ لَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1397, 'حائِزٌ', 'حائز', 'اسم فاعل', 'حوز', 'حاءز', 'حز', 'فا. من حَازَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من حَازَ). 1.""حائِزٌ رِضا آبائِهِ"" : الْمُتَمَتِّعُ بِرِضاهُمْ. ""إِنَّما الْمَدارُ عَلَى أَنْ تَكُونَ بِهَذَا الكَمَالِ حَائِزٌ"".(التوحيدي). 2.""حَائِزٌ عَلَى شَهادَةِ البَكالورِيا"" : حاصِلٌ عَلَيْها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1398, 'حوائز', 'حوائز', 'اسم فاعل', '', 'حواءز', 'حز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1399, 'مُحَاصِرٌ', 'محاصر', 'اسم فاعل', 'حصر', 'محاصر', 'محصر', 'فَا. مِنْ حَاصَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ حَاصَرَ). ""مُحَاصِرٌ لِأَعْدَائِهِ"" : مُحِيطٌ بِهِمْ مِنْ كُلِّ جِهَةٍ، مُضَيِّقٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1400, 'حائِضٌ', 'حائض', 'اسم فاعل', 'حيض', 'حاءض', 'حض', 'فا. من حاضَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حائِضٌ-حائِضٌ [ح ي ض] (فا. من حاضَ). ""اُتْرُكْها، إِنَّها حائِضٌ"" : الْمَرْأَةُ في إِبَّانِ حَيْضِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1401, 'حوائض', 'حوائض', 'اسم فاعل', '', 'حواءض', 'حض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1402, 'مُحَاضِرٌ', 'محاضر', 'اسم فاعل', 'حضر', 'محاضر', 'محضر', 'فَا. مِنْ حَاضَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ حَاضَرَ). ""تَحَدَّثَ الْمُحَاضِرُ بِلُغَةٍ وَاضِحَةٍ"" : مَنْ يُلْقِي مُحَاضَرَةً فِي مَوْضُوعٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1403, 'حائِطٌ', 'حائط', 'اسم فاعل', 'حوط', 'حاءط', 'حط', 'فا. من حاطَ', '', '', 'مفرد', '', '', '', '"حيطانٌ"', '', '', '', '', '', '', '', '', '"(فا. من حاطَ). 1.""اِنْتَهَى مِنْ بِناءِ الحائِطِ الأوَّلِ لِلْبَيْتِ"" : بِناءٌ عَمودِيٌّ يَرْتَفِعُ حَسَبَ طولٍ مُعَيَّنٍ وَيُشَكِّلُ دِعامَةً لِلْبَيْتِ، كَما يُمْكِنُ أَنْ يَكونَ حاجِزاً بَيْنَ مِساحَتَيْنِ. ""بَنَى حائِطاً حَوْلَ حَقْلِهِ"". 2.""ضَرَبَ بِرَغَباتِهِ عُرْضَ الحائِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1404, 'حيطانٌ', 'حيطان', 'اسم فاعل', '', 'حيطان', 'حطن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1405, 'مُحَافِظٌ', 'محافظ', 'اسم فاعل', 'حفظ', 'محافظ', 'محفظ', 'فَا. مِنْ حَافَظَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ حَافَظَ). 1.""مُحَافِظٌ عَلَى العَهْدِ"" : الَّذِي يَحْفَظُ العَهْدَ وَلاَ يَخُونُهُ. 2.""مُحَافِظُ الإِقْلِيمِ"" : حَاكِمُ الْمُحَافَظَةِ، الوِلاَيَةِ. 3.""مُحَافِظُ الخِزَانَةِ"" : القَيِّمُ عَليْهَا، السَّاهِرُ عَلى تَنْظِيمِهَا. 4.""رَجُلٌ مُحَافِظٌ"" : مَنْ يُحَافِظُ عَلَى العَادَاتِ وَالتَّقَالِيدِ وَمَبَادِئِ النِّظَامِ الاجْتِمَاعِيِّ كَمَا هُوَ مَوْرُوثٌ، وَالبَعِيدُ عَنْ كُلِّ تَجْدِيدٍ. ""كَانَتْ مُحَافِظَةً بِطَبْعِهَا"" ""تُصَارِعُ آرَاءُ الْمُحَافِظِينَ آرَاءَ الْمُتَمَدِّنِينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1406, 'حائِكٌ', 'حائك', 'اسم فاعل', 'حوك', 'حاءك', 'حك', 'فا. من حاكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حاكَةٌ:حَوَكَةٌ:حوائِكُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من حاكَ). 1.""وَجَدَ الحائِكُ صوفاً لِيَحيكَهُ"" : مَنْ يَنْسُجُ مادَّةَ القُطْنِ أَوِ الصُّوفِ، أَيْ كُلَّ ما يُنْسَجُ لِيُجْعَلَ مِنْهُ نَسيجاً أَوْ ثِياباً. 2.""تُط"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1407, 'حاكَةٌ', 'حاكة', 'اسم فاعل', '', 'حاكة', 'حكة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
