INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1409, 'حوائِكُ', 'حوائك', 'اسم فاعل', '', 'حواءك', 'حك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1410, 'مُحَاكِي', 'محاكي', 'اسم فاعل', 'حكي', 'محاكي', 'محك', 'فَا. مِنْ حَاكَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ حَاكَى). ""مُحَاكٍ لِزَمِيلِهِ"" : مُقَلِّدٌ، مُشَابِهٌ لَهُ فِي القَوْلِ أَوِ الفِعْلِ أَوْ غَيْرِ ذَلِكَ. ""يَرْفُضُ أَنْ يَكُونَ مُحَاكِياً لِغَيْرِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1411, 'حائِلٌ', 'حائل', 'اسم فاعل', 'حول', 'حاءل', 'حل', 'فا. من حالَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حُوْلٌ:حُوَّلٌ:حَوائِلُ"', '', '', '', '', '', '', '', '', '"(فا. من حالَ). 1.""أَصْبَحَتْ أَلْوانُ قَميصِهِ حائِلَةً بَعْدَ تَصْبينِهِ"" : أَي مُتَغَيِّرَةً، مُخْتَلِطَة الأَلْوانِ. 2.""وَقَفَ حائِلاً بَيْنَهُما"" : حاجِزاً‎، مانِعاً. ""لاَ يَحولُ بَيْنَنَا حائِلٌ"" ""ما أَكْثَرَ الفُرُوقَ الحائِلَةَ بَيْنَ الأغْنِياءِ الْمُتْرَفينَ والفُقَراءِ البائِسينَ !"".(طه حسين). 3.""طِفْلٌ حائِلٌ"" : عُمْرُهُ حَوْلٌ. 4.""اِمْرَأَةٌ حائِلٌ"" : لا تَحْمِلُ. 5.""شَجَرَةٌ حائِلٌ"" : تَحْمِلُ عاماً ولا تَحْمِلُ عاماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1412, 'حُوْلٌ', 'حول', 'اسم فاعل', '', 'حول', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1413, 'حُوَّلٌ', 'حول', 'اسم فاعل', '', 'حول', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1414, 'حَوائِلُ', 'حوائل', 'اسم فاعل', '', 'حواءل', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1415, 'مُحَامِي', 'محامي', 'اسم فاعل', 'حمي', 'محامي', 'محم', 'فَا. مِنْ حَامَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ حَامَى). ""وَقَفَ الْمُحَامِي يُدَافِعُ عَنِ الْمُتَّهَمِ"" : الْمُدَافِعُ عَنِ الْمُتَّهَمِ وَقَضَايَا النِّزَاعِ بَيْنَ الْمُتَقَاضِينَ أَمَامَ الْمَحَاكِمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1416, 'مُحَاوِرٌ', 'محاور', 'اسم فاعل', 'حور', 'محاور', 'محر', 'فَا. مِنْ حَاوَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ حَاوَرَ). ""جَاءَ مُحَاوِراً لَهُ"" : مُجَادِلاً، مُحَادِثاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1417, 'مُحَايِدٌ', 'محايد', 'اسم فاعل', 'حيد', 'محايد', 'محد', 'فَا. مِنْ حَايَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ حَايَدَ). ""مُحَايِدٌ فِي أَحْكَامِهِ"" : مَنْ لاَ يَنْحَازُ إِلَى أَحَدِ الْمُتَخَاصِمِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1418, 'حابِلٌ', 'حابل', 'اسم فاعل', 'حبل', 'حابل', 'حبل', 'فا. مِنْ حَبَلَ', '', 'Ta', 'مفرد', 'DnT', '', '', '', '', '', '', '', '', '', '', '', '"حابِلٌ-حابِلٌ [ح ب ل] (فا. مِنْ حَبَلَ). 1.""صائِدٌ حابِلٌ"" : ناصِبُ الحِبالِ. 2.""اِخْتَلَطَ الحابِلُ بِالنَّابِلِ""(مثل) : اِخْتَلَطَ أَمْرُ مَنْ يَصيدُ بِالحِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1419, 'حواد', 'حواد', 'اسم فاعل', '', 'حواد', 'حد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1420, 'حاجِبٌ', 'حاجب', 'اسم فاعل', 'حجب', 'حاجب', 'حجب', 'فا. من حَجَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حَواجِبُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من حَجَبَ). 1.""حاجِبُ العَيْنِ"" : العَظْمُ الَّذِي فَوْقَ العَيْنِ بِلَحْمِهِ وَشَعْرِهِ. 2.""وَقَفَ الحاجِبُ على عَتَبَةِ بابِ الْمَلِكِ مُعْلِناً وُصولَ الوُفودِ"": مَنْ يَقِفُ عِنْدَ بابِ قُبَّةِ العَرْشِ، يُقَدِّمُ الزُّوارَ لِلْمَلِكِ. 3.""سَطَعَتْ حَواجِبُ الشَّمْسِ"" : أَشِعَّتُها، أَوَّلُ ما يَبْدو مِنْها. فَحاجِبُ الشَّمْسِ أَحْياناً يُضاحِكُها*وَرَيِّـقُ الغَيْثِ أَحْياناً يُباكِيهـا (البحْتُري)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1421, 'حَواجِبُ', 'حواجب', 'اسم فاعل', '', 'حواجب', 'حجب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
