INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1424, 'حاجِزٌ', 'حاجز', 'اسم فاعل', 'حجز', 'حاجز', 'حجز', 'فا. مِنْ حَجَزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حَواجِزُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ حَجَزَ). 1.""بَيْنَهُما حاجِزٌ"" : فاصِلٌ. ""حاجِزُ إِسْمَنْتٍ بَيْنَهُما يَحْجِزُ قِسْماً مِنَ القاعَةِ"".(عبد الرحمان منيف). 2.""أَقامَ رِجالُ الشُّرْطَةِ حَواجِزَ عِنْدَ مَدْخَلِ الْمَدينَةِ"" : أَعْمِدَةً مِنَ حَديدٍ لإيقافِ السَّيَّاراتِ مِنْ أَجْلِ هَدَفٍ مَّا. 3.""نَصَبَ الْمُتَظاهِرونَ حَواجِزَ في مُنْتَصَفِ الطَّريقِ"" : أَحْجاراً أَوْ أَسْلاكاً لِمَنْعِ السَّيَّاراتِ مِنْ وُلوجِ الطَّريقِ. 4.""وَقَفَتِ الحَواجزُ حائِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1425, 'حَواجِزُ', 'حواجز', 'اسم فاعل', '', 'حواجز', 'حجز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
