INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1427, 'حجزة', 'حجزة', 'اسم فاعل', '', 'حجزة', 'حجزة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1428, 'حادٌّ', 'حاد', 'اسم فاعل', 'حدد', 'حاد', 'حد', 'فا. مِنْ حَدَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"حادٌّ-حادٌّ، ةٌ [ح د د ] (فا. مِنْ حَدَّ). 1.""أَخْرَجَ مِنْ جَيْبِهِ سِكِّيناً حادّاً"" : مَسْنُوناً. 2.""يَغْضَبُ بِسُرْعَةٍ، هُوَ حادُّ المِزاجِ"" : سَريعُ الغَضَبِ، مُتَشَنِّجٌ. ""حادُّ الطَّبْعِ"" ""حادُّ الشُّعورِ"" ""أَجابَهُ بِلَهْجَةٍ حادَّةٍ"". 3.""يَنْظُرُ مِنْ بَعيدٍ، هُوَ حادُّ النَّظَرِ"" : ثاقِبُ النَّظَرِ نافِذُهُ. ""حادُّ البَصيرَةِ"" ""حادُّ الذِّهْنِ"". 4.""شَعَرَ بِأَلَمٍ حادٍّ"" : بِأَلَمٍ شَديدٍ. 5.""اِسْتَقْبَلَهُ الجُمْهورُ بِتَصْفيقاتٍ حادَّةٍ"" : حارَّةٍ. ""تَصْفيقٌ حادٌّ"". 6.""زاوِيَةٌ حادَّةٌ"" : اِنْفِراجُها أَصْغَرُ مِنَ الزَّاوِيَةِ القائِمَةِ (أَصْغَرُ من 90د)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1429, 'حارِثٌ', 'حارث', 'اسم فاعل', 'حرث', 'حارث', 'حرث', 'فا. مِنْ حَرَثَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حُرَّاثٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ حَرَثَ). 1.""حارِثُ الأرْضِ صاحِبُها"" : مَنْ يَحْرُثُ الأرْضَ، أَيْ مَنْ يُقَلِّبُها لِيَزْرَعَها، الزَّارِعُ. 2.""الحارِثُ بْنُ..."" : اِسْمُ عَلَمٍ، وَيُطْلَقُ على الأسَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1430, 'حداد', 'حداد', 'اسم فاعل', '', 'حداد', 'حدد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1431, 'حددة', 'حددة', 'اسم فاعل', '', 'حددة', 'حددة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1432, 'مُحَدِّثٌ', 'محدث', 'اسم فاعل', 'حدث', 'محدث', 'محدث', 'فَا. مِنْ حَدَّثَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ حَدَّثَ). 1.""قَالَ الْمُحَدِّثُ"" : الرَّاوِيُ، الْمُخْبِرُ، رَاوِي أَحَادِيث الرَّسُولِ ( . 2.""سَألَ مُحَدِّثَهُ"" : مُكَلِّمَهُ. ""نَظَرَتْ إِلَى مُحَدِّثِهَا بِعَيْنَيْنِ لاَ تَكَادَانِ تُصَدِّقَانِ"". (ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1433, 'مُحَدِّدٌ', 'محدد', 'اسم فاعل', 'حدد', 'محدد', 'محد', 'فَا. مِنْ حَدَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُحَدَّدٌ-مُحَدَّدٌ، ةٌ [ح د د] (مفع. مِنْ حَدَّدَ). ""عَمَلٌ مُحَدَّدٌ"": مُعَيَّنٌ، مُخَصَّصٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1434, 'حاذِقٌ', 'حاذق', 'اسم فاعل', 'حذق', 'حاذق', 'حذق', 'فا. مِنْ حَذَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حُذَّاقٌ:حِذَاقٌ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ حَذَقَ). 1.""إِنَّهُ لَصانِعٌ حاذِقٌ"" : ماهِرٌ في صِناعَتِهِ. 2.""خَلٌّ حَاذِقٌ"" : شَديدُ الحُموضَةِ."', '');
