INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1443, 'مُحَرِّرٌ', 'محرر', 'اسم فاعل', 'حرر', 'محرر', 'محر', 'فَا. مِنْ حَرَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ حَرَّرَ). 1.""مُحَرِّرُ البِلاَدِ"" : مَنْ حَرَّرَهَا مِنَ العُبُودِيَّةِ وَالانْعِتَاقِ وَقَادَهَا إِلَى الْحُرِّيَّةِ. 2.""مُحَرِّرٌ فِي الجَرِيدَةِ"" : مَنْ يَكْتُبُ فِيهَا وَيُنَسِّقُ مَوَاضِيعَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1444, 'مُتَحَرِّرٌ', 'متحرر', 'اسم فاعل', 'حرر', 'متحرر', 'متحر', 'فا. من حَرَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من حَرَّرَ). ""مُتَحَرِّرٌ مِنْ كُلِّ قَيْدٍ"" : مُتَخَلِّصٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1445, 'حارِسٌ', 'حارس', 'اسم فاعل', 'حرس', 'حارس', 'حرس', 'فا. مِنْ حَرَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حَرَسٌ:حُرَّاسٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ حَرَسَ). 1.""وَجَدَ حَارِسَ اللَّيْلِ وَاقِفاً بِعَصاهُ في رَأْسِ الشَّارِعِ"" : مَنْ يَحْرُسُ السُّوقَ بِاللَّيْلِ. ""حارِسُ العِمارَةِ"" ""حارِسُ الْمَعْ"', '');
