INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1451, 'مُحَرِّكٌ', 'محرك', 'اسم فاعل', 'حرك', 'محرك', 'محرك', 'فَا. مِنْ حَرَّكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ حَرَّكَ). 1.""عَمَلٌ مُحَرِّكٌ لِلْعَاطِفَةِ"" : مُهَيِّجٌ لَهَا. 2.""مُحَرِّكٌ لِمَا هُوَ جَامِدٌ"" : الْبَاعِثُ لَهَا عَلَى الْحَرَكَةِ. ""كُلُّ حَرَكَةٍ لاَ بُدَّ لَهَا مِنْ مُحَرِّكٍ"". (ابن طفيل). 3.""مُحَرِّكُ السَّيَّارَةِ"" : جِهَازٌ آلِيٌّ فِي قَلْبِ مُقَدِّمَةِ السَّيَّارَةِ أَوْ مُؤَخِّرَتِها، يُسَيِّرُهُ البِنْزِينُ أَوِ الْمَازُوتُ وَبِوَاسِطَتِهِ تُحْدَثُ قُوَّةٌ مُحَرِّكَةٌ دَافِعَةٌ. ""مُحَرِّكُ الطَّائِرَةِ"" ""مُحَرِّكُ السَّفِينَةِ"" ""مُحَرِّكُ الدَّرَّاجَةِ النَّارِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1452, 'حارِكٌ', 'حارك', 'اسم فاعل', 'حرك', 'حارك', 'حرك', 'فا. من حَرَكَ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"حارِكٌ-حارِكٌ [ح ر ك] (فا. من حَرَكَ).: أَعْلَى الكاهِلِ، أي مُقَدَّمُ أَعْلَى الظَّهْرِ مِمَّا يَلي العُنُقَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1453, 'حازِمٌ', 'حازم', 'اسم فاعل', 'حزم', 'حازم', 'حزم', 'فا. مِن حَزَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِن حَزَمَ). 1.""عَرَفْتُهُ رَجُلاً حازِماً"" : ضابِطاً لأَمْرِهِ مُتَحَكِّماً فيهِ بِثِقَةٍ. 2.""اِتَّخَذَ قَراراتٍ حازِمَةً"" : ذاتَ فَعَالِيَّةٍ وَتَأْثيرٍ وَضبْطٍ. ""تَدابيرُ حازِمَةٌ"" ""وَقالَ لَها بِصَوْتٍ جَهْوَرِيٍّ في لَهْجَةٍ حازِمَةٍ: أَنا رَجُلُ الأمْرِ النَّاهِي""(ن. محفوظ)."', '');
