INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1474, 'حاصِدٌ', 'حاصد', 'اسم فاعل', 'حصد', 'حاصد', 'حصد', 'فا.من حَصَد', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حَصَدَةٌ:حُصَّادٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"ج: حَصَدَةٌ، حُصَّادٌ. (ح ص د) (فا.من حَصَد)1.""حاصِدُ الزَّرْعِ"" : قاطِعُهُ بِالمِنْجَلِ. 2.""حاصِدَةُ الزَّرْعِ"" : آلَةُ حَصْدِ الزَّرْعِ."', '');
