INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1478, 'حاصِلٌ', 'حاصل', 'اسم فاعل', 'حصل', 'حاصل', 'حصل', 'فا. من حَصَل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حَواصِلُ"', '', '', '', '', '', '', '', '', '"(فا. من حَصَل). 1.""حاصِلُ العَمَلِ"" : ما بَقِيَ مِنْهُ وَثَبَتَتْ نَتيجَتُهُ. 2.""حاصِلُ الفِضَّةِ"" : ما خَلُصَ مِنْها مِنْ حِجارَةِ الْمَعْدِنِ. 3.""حاصِلُ الضَّرْبِ"" : ما يَنْتُجُ عَنْهُ مِنَ الأعْمالِ الحِسابِيَّةِ. 4.""حاصِلُ الكَلامِ"" : خُلاصَتُهُ. 5.""حاصِلُ الحَقْلِ"" : مَحْصولُ إِنْتاجِه، غَلَّتُهُ."', '');
