INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1482, 'حاضِرٌ', 'حاضر', 'اسم فاعل', 'حضر', 'حاضر', 'حضر', 'فا. مِن حَضَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حُضورٌ:حُضَّرٌ:حَواضِرُ"', '', '', '', '', '', '', '', '', '"(فا. مِن حَضَرَ). 1.""كانَ حاضِراً في القاعَةِ"" : مَوْجوداً. 2.""هُوَ حاضِرُ البَديهَةِ"" : سَريعُ الإِجابَةِ. ""كانَ لَبِقاً لَسِناً ذَكِيّاً واسِعَ الاطِّلاعِ حاضِرَ البَديهَةِ"". (أ. أمين). 3.""في الوَقْتِ الحاضِرِ"" : الآنَ، حالِياً. ""الزَّمانُ الحاضِرُ"" : أي الزَّمانُ الَّذِي أَنْتَ فيهِ. 4.""رَجُلٌ حاضِرٌ"" : ساكِنُ الحَضَرِ. 5.""حاضِرٌ بَهيجٌ"" : الحَيُّ العَظيمُ. 6.""مِنْ أَبْناءِ الحاضِرَةِ"" : مِنْ سُكَّانِ الْمَدينَةِ. ""أَلِفَ حَياةَ الحاضِرَةِ"". 7.""حاضِرَةُ الفيلِ"" : أُذُنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1483, 'حُضورٌ', 'حضور', 'اسم فاعل', '', 'حضور', 'حضر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
