INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1488, 'حاضِنٌ', 'حاضن', 'اسم فاعل', 'حضن', 'حاضن', 'حضن', 'فا. من حَضَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حَواضِنُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من حَضَنَ). 1.""حَمامَةٌ حاضِنٌ"" : الْمُرْخِمَةُ على بَيْضِها. 2.""تَوَلَّتِ الحاضِنَةُ رِعايَةَ الطِّفْلِ والسَّهَرَ على تَرْبِيَتِهِ"" : مَنْ تَقومُ على الطِّفْلِ وَتَرْعاهُ وَتُرَبِّيهِ. 3.""الحاضِنَةُ الكَهْرَبائِيَّةُ"" : آلَةٌ لِلتَّفْريخِ الاصْطِناعِيِّ، تَقومُ بِتَدْفِئَةِ البَيْضِ حَتَّى يَفْقَسَ وَتَخْرُجُ مِنْهُ الكَتاكيتُ."', '');
