INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1496, 'مُحَطِّمٌ', 'محطم', 'اسم فاعل', 'حطم', 'محطم', 'محطم', 'فَا. مِنْ حَطَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ حَطَّمَ). 1.""مُحَطِّمٌ لِلْبُنْيَانِ"" : مُهَدِّمُهَا. 2.""مُحَطِّمٌ لِكُلِّ آمَالِهِ"": مُضَيِّعٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1497, 'حافٌّ', 'حاف', 'اسم فاعل', 'حفف', 'حاف', 'حف', 'فا. من حَفَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"حافٌّ-حافٌّ [ح ف ف] (فا. من حَفَّ). 1.""رَجُلٌ حافٌّ"" : شَديدُ الإِصابَةِ بِالعَيْنِ. 2.""حافُّ الحَقْلِ"" : ما يُحيطُ بِهِ. 3.""هُوَ حافُّ الْمَطْعَمِ"" : أي يابِسُهُ. 4.""خُبْزٌ حافٌّ"" : لم يُجْعَلْ مَعَهُ شَيْءٌ"". 5.""طَحينٌ حافٌّ"" : يابِسٌ لا سَمْنَ وَلا زَيْتَ مَعَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1498, 'حواف', 'حواف', 'اسم فاعل', '', 'حواف', 'حف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
