INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1500, 'حافِزٌ', 'حافز', 'اسم فاعل', 'حفز', 'حافز', 'حفز', 'فا. من حَفَزَ', '', 'Ta', 'مفرد', 'DnT', '', '', '"حَوافِزُ"', '', '', '', '', '', '', '', '', '"(فا. من حَفَزَ). ""لابُدَّ لَهُ مِنْ حافِزٍ"" : الباعِثُ، الدَّافِعُ الَّذِي يَدْفَعُ الإِنْسانَ وَيَحُثُّهُ على القِيامِ بِعَمَلٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1501, 'حَوافِزُ', 'حوافز', 'اسم فاعل', '', 'حوافز', 'حفز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1502, 'حافِلٌ', 'حافل', 'اسم فاعل', 'حفل', 'حافل', 'حفل', 'فا. مِنْ حَفَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حُفَّلٌ:حَوافِلُ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ حَفَلَ). 1.""ضَرْعُها حافِلٌ بِاللَّبَنِ"": مَليءٌ. 2.""اِجْتَمَعُوا في جَمْعٍ حافِلٍ"" : عَدَدُ الحاضِرينَ فيهِ كُثْرٌ. 3.""حافِلٌ بِأَوامِرِهِ"" : مُكْتَرِثٌ. ""جَلَسُوا يَصْطَلونَ بِقُرْبِ الْمَواقِدِ غَيْرَ حافِلينَ بِأَشْباحِ اللَّيْلِ"". (جبران خ. جبران). 4.""كانَتِ السُّوقُ حافِلَةً بِجَميعِ أَنْواعِ الخُضَرِ والفَواكِهِ"" : بِها كُلُّ الأَنْواعِ، جامِعَةٌ لَها. 5.""في يَوْمِ العيدِ كانَتِ الدَّارُ حافِلَةً"": تَوافَدَ عَلَيْها كَثيرٌ مِنَ الأَهْلِ. 6.""رَكِبَ الحافِلَةَ"" : سَيَّارَةٌ كَبيرَةٌ لِنَقْلِ الرُّكَّابِ داخِلَ الْمَدينَةِ. 7.""حافِلَةُ القِطارِ"" : عَرَبَةٌ مِنْ عَرَباتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1503, 'حُفَّلٌ', 'حفل', 'اسم فاعل', '', 'حفل', 'حفل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
