INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1507, 'حافِي', 'حافي', 'اسم فاعل', 'حفي', 'حافي', 'حف', 'فا. من حَفِيَ', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حُفاةٌ:حَوافٍ"', '', '', '', '', '', '', '', '', '".(فا. من حَفِيَ) 1 .""جاءَ حافِيَ القَدَمَيْنِ"" : عارِيَ القَدَمَيْنِ، لا يَنْتَعِلُ شَيْئاً. ""رَجَعَ الصَّبِيُّ حافِياً حِينَ نَسِيَ نَعْلَيْهِ""(طه حسين). ""لَمْ نَجِدْ في القَرْيَةِ إِلاَّ الحُفاةَ العُراةَ"". 2.""إِسْكافِيٌ حافٍ"" (مثل) : مَنْ يَصْنَعُ الأَحْذِيَةَ وَيَسيرُ عارِيَ القَدَمَيْنِ. 3.""الرَّجُلُ الحافِي"" : الْمُبالِغُ في إِكْرامِ الغَيْرِ، أوِ الْمُكْثِرُ مِنَ السُّؤَالِ عَنْ حالِ الآخَرينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1508, 'حُفاةٌ', 'حفاة', 'اسم فاعل', '', 'حفاة', 'حفة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1509, 'حَوافِي', 'حوافي', 'اسم فاعل', '', 'حوافي', 'حف', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1510, 'حاقِدٌ', 'حاقد', 'اسم فاعل', 'حقد', 'حاقد', 'حقد', 'فا. مِنْ حَقَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حَقَدَةٌ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ حَقَدَ). ""وَجَدْتُهُ حاقِداً عَلَيْهِ"" : ناقِماً، ضاغِناً. ""لا تَكُنْ مِنَ الحاقِدينَ يا بُنَيَّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1511, 'حَقَدَةٌ', 'حقدة', 'اسم فاعل', '', 'حقدة', 'حقدة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1512, 'حواقد', 'حواقد', 'اسم فاعل', '', 'حواقد', 'حقد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1513, 'حقاد', 'حقاد', 'اسم فاعل', '', 'حقاد', 'حقد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1514, 'مُحَقِّقٌ', 'محقق', 'اسم فاعل', 'حقق', 'محقق', 'محق', 'فَا. مِنْ حَقَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ حَقَّقَ). 1.""أَجْرَى مَعَهُ الْمُحَقِّقُ تَحْقِيقاً مُفَصَّلاً"" : قَاضِي التَّحْقِيقِ الَّذِي يُحَقِّقُ مَعَ الْمُتَّهَمِ فِي قَضِيَّةٍ لِلْكَشْفِ عَنْ مَجْرَيَاتِهَا. 2.""مُحَقِّقُ الْمَخْطُوطِ"" : البَاحِثُ فِيهِ لِيُعِيدَ نَشْرَهُ بَعْدَ تَحْقِيقِهِ تَحْقِيقاً تَامّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1515, 'مُحَكِّمٌ', 'محكم', 'اسم فاعل', 'حكم', 'محكم', 'محكم', 'فَا. مِنْ حَكَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ حَكَّمَ). ""شَيْخٌ مُحَكِّمٌ"" : مَنْ حَنَّكَتْهُ التَّجَارِبُ وَصَارَتْ لِأَحْكَامِهِ مِصْدَاقِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1516, 'حاكِمٌ', 'حاكم', 'اسم فاعل', 'حكم', 'حاكم', 'حكم', 'فا. مِنْ حَكَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حُكَّامٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ حَكَمَ). 1.""جاءَ يَشْتَكيهِ إلى الحاكِمِ"" : القاضِي، وَيُمْكِنُ أَنْ يَكونَ الحاكِمُ أَميراً أَوْ باشا أَوْ عامِلاً أَوْ مَنْ يَتَوَلَّى إِدارَةَ شُؤُونِ البِلادِ مَلِكاً أَوْ رَئِيساً. 2.""هُوَ الحاكِمُ بِأَمْرِهِ"" : السَّيِّدُ الْمُطْلَقُ الَّذِي لا يَسْتَشيرُ أَحَداً في أَحْكامِهِ وَآرائِهِ. 3.""اِنْهَزَمَ الحِزْبُ الحَاكِمُ في الاِنْتِخَابَاتِ"" : الحِزْبُ الَّذِي يَتَوَلَّى السُّلْطَةَ في البُلْدانِ الدِّيمُقْراطِيَّةِ بَعْدَ فَوْزِهِ، وَيَتَخَلَّى عَنْها في حالَةِ انْهِزامِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1517, 'حُكَّامٌ', 'حكام', 'اسم فاعل', '', 'حكام', 'حكم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1518, 'مُحَمَّرٌ', 'محمر', 'اسم فاعل', 'حمر', 'محمر', 'محمر', 'فا من حَمَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُحَمَّرٌ-مُحَمَّرٌ، ةٌ [ح م ر] (فا من حَمَّرَ). 1.""ثَوْبٌ مُحَمَّرٌ"" : مَصْبوغٌ بِاللَّوْنِ الأَحْمَرِ. 2.""لَحْمٌ مُحَمَّرٌ"" : مَقْلِيٌّ إلى حَدِّ الاحْمِرارِ. ""دَجاجٌ مُحَمَّرٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1519, 'حواكم', 'حواكم', 'اسم فاعل', '', 'حواكم', 'حكم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
