INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1521, 'حاكِي', 'حاكي', 'اسم فاعل', 'حكي', 'حاكي', 'حك', 'فا. مِنْ حَكَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"حاكٍ-حاكٍ، الحاكِي [ح ك ي] (فا. مِنْ حَكَى). 1.""بَدَأَ الحاكِي يَرْوِي إِحْدَى قِصَصِهِ العَجيبَةِ"" : الرَّاوِي. 2.""وَضَعَ أُسْطُوانَةً على الحاكِي"" : آلَةٌ توضَعُ عَلَيْها الأُسْطُوانَةُ وَتُحَرِّكُها طاقَةٌ كَهْرَبائِيَّةٌ فَتَنْقُلُ ما عَلَيْها مِنْ أَصْواتٍ موسِيقِيَّةٍ مُسَجَّلَةٍ عَلَيْها وَتُذِيعُها."', '');
