INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1524, 'حالِبٌ', 'حالب', 'اسم فاعل', 'حلب', 'حالب', 'حلب', 'فا. من حَلَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حَلَبَةٌ:حَوالِبُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من حَلَبَ). ""حالِبُ البِئْرِ"" : مَنْبَعُ مائِها."', '');
