INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1528, 'مُحَلِّقٌ', 'محلق', 'اسم فاعل', 'حلق', 'محلق', 'محلق', 'فَا. مِنْ حَلَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ حَلَّقَ). 1.""طَائِرٌ مُحَلِّقٌ فِي الفَضَاءِ"" : مُرْتَفِعٌ وَهُوَ يَدُورُ فِي تَحْليقِهِ. ""ظَلَّ مُحَلِّقاً فَوْقَ رُؤُوسِهِمْ"". 2.""مُحَلِّقٌ بِبَصَرِهِ"" : رَافِعُهُ إِلَى أَعْلَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1529, 'حُماةٌ', 'حماة', 'اسم فاعل', '', 'حماة', 'حمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1530, 'مُحَمِّسٌ', 'محمس', 'اسم فاعل', 'حمس', 'محمس', 'محمس', 'فَا. مِنْ حَمَّسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ حَمَّسَ). ""مُحَمِّسٌ لِلْجُمْهُورِ"" : مَنْ يَبْعَثُ فِيهِمُ الْحَمَاسَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1531, 'حامِضٌ', 'حامض', 'اسم فاعل', 'حمض', 'حامض', 'حمض', 'فا. من حَمَضَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حامِضٌ-حامِضٌ [ح م ض] (فا. من حَمَضَ). 1.""وَجَدَ الطَّعامَ حامِضاً"" : فيهِ حُموضَةٌ. 2.""حامِضٌ"" (كيما) : مُرَكَّبٌ هيدْروجِينِيٌّ قابِلٌ للاسْتِبْدالِ والتَّحَوُّلِ بِإِحْلالِ الْمَعْدِنِ مَحَلَّ الهيدْروجينِ الْمُكَوِّنِ لَهُ. 3.""حامِضُ البورِيكِ"" : جِسْمٌ مُؤَلَّفٌ مِنْ بَلُّوراتٍ عَدبمَةِ اللَّوْنِ والرَّائِحَةِ، يُسْتَعْمَلُ سَماداً في الزِّراعَةِ وَمادَّةً مُعَقِّمَةً. 4.""حامِضُ الكِبْريتيكِ"" : حامِضٌ زَيْتِيٌّ، عَديمُ اللَّوْنِ، يَمْتَصُّ الماءَ وَيُساعِدُ على تَصْفِيَةِ البِتْرولِ. 5.""الْحامِضُ الكَرْبونِيّ"" : غازٌ في الهَواءِ ناتِجٌ عَن تَنَفُّسِ الأحْياءِ والاخْتِماراتِ وَغَيْرِها وَهُوَ الحامِضُ الفَحْمِيُّ. 6.""حامِضُ اللَّيْمونِ"" : حامِضٌ عُضْوِيٌ يوجَدُ في الحَمْضِيَّاتِ كالبُرْتُقالِ واللَّيْمونِ الحامِضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1532, 'حوامض', 'حوامض', 'اسم فاعل', '', 'حوامض', 'حمض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1533, 'حامِلٌ', 'حامل', 'اسم فاعل', 'حمل', 'حامل', 'حمل', 'فا. مِنْ حَمَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حَمَلَةٌ:حُمَّالٌ:حَوامِلُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ حَمَلَ). 1.""اِمْرَأَةٌ حامِلٌ"" : حُبْلَى. 2.""إِنَّهُ مِنْ حَمَلَةِ القُرْآنِ"": مِنْ حُفَّاظِهِ. 3.""أَعْطِ حامِلَ هَذِهِ الوَرَقَةِ ما يَطْلُبُهُ مِنْكَ"" : مَنْ يَحْمِلُها. ""حامِلُ الشِّيكِ"". 4.""رَسَتْ في الخَليجِ حامِلَةُ الطَّائِراتِ"" : سَفينَةٌ حَرْبِيَّةٌ ضَخْمَةٌ لَها مَدْرَجٌ، وَهِيَ تَحْمِلُ طائِراتٍ مُقاتِلَةً في عُرْضِ البَحْرِ تُقْلِعُ عِنْدَ الحاجَةِ."', '');
