INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1537, 'مُحَمْلِقٌ', 'محملق', 'اسم فاعل', 'حملق', 'محملق', 'محملق', 'فَا. مِنْ حَمْلَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ حَمْلَقَ). ""مُحَمْلِقٌ فِيهِ"" : نَاظِرٌ إِلَيْهِ نَظَراً مُتَفَحِّصاً. ""رَغْمَ الأَعْيُنِ الْمُحَمْلِقَةِ، بَدَا ثَابِتاً غَيْرَ هَيَّابٍ"". (ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1538, 'حامِي', 'حامي', 'اسم فاعل', 'حمي', 'حامي', 'حم', 'فا. من حَمَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":حُماةٌ:حامِيةٌ:حَوامٍ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من حَمَى). 1.""حامِي الدِّينِ"" : الْمُدافِعُ عَنْهُ، السَّاهِرُ عَلَيْهِ. 2.""وَصَلَتِ الحامِيَةُ"" : الجَماعَةُ الَّتِي تَحْمي نَفْسَها أَوْ غَيْرَها. 3.""اِسْتَقَرَّتْ حامِيَةُ الجَيْشِ في الْمَواقِعِ الأَمامِيَّةِ"" : فَيْلَقٌ مِنَ الجَيْشِ لِحِمايَةِ بَلَدٍ أَوْ مَوْقِعٍ مَّا. 4.""حُماةُ الوَطَنِ"" : الْمُدافِعونَ عَنْهُ بِحَمِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1539, 'خَائِرٌ', 'خائر', 'اسم فاعل', 'خور', 'خاءر', 'خر', 'فا. مِنْ خَارَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِنْ خَارَ). 1. ""وَصَلَ خَائِرَ الْقُوَى"" : مُحَطَّماً، مُنْهَزِماً. 2.""وَجَدْتُهُ خَائِرَ النَّفْسِ"" : مُكْتَئِباً مُحْبَطاً ."', '');
