INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1542, 'حاوِي', 'حاوي', 'اسم فاعل', 'حوي', 'حاوي', 'ح', 'فا. مِنْ حَوَى', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":حُواةٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ حَوَى). ""وَقَفُوا يَنْظُرونَ الحاوِيَ في دَهْشَةٍ وَهُوَ يُداعِبُ حَيَّاتِهِ"" : الَّذِي يُرَبِّي الحَيَّاتِ وَيَقومُ بِأَعْمالٍ عَجيبَةٍ بِحيلَةٍ."', '');
