INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1545, 'خَائِبٌ', 'خائب', 'اسم فاعل', 'خيب', 'خاءب', 'خب', 'فا. مِنْ خَابَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِنْ خَابَ). 1. ""حَظٌّ خَائِبٌ"" : عَاثِرٌ، تَعِسٌ. ""آمَالٌ خَائِبَةٌ"". 2.""رَجُلٌ خَائِبٌ"" : رَجُلٌ فَاشِلٌ، تَعِسُ الْحَظِّ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1546, 'خوائب', 'خوائب', 'اسم فاعل', '', 'خواءب', 'خب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1547, 'مُخَاتِلٌ', 'مخاتل', 'اسم فاعل', 'ختل', 'مخاتل', 'مختل', 'فَا. مِنْ خَاتَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ خَاتَلَ). ""رَجُلٌ مُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1548, 'مُخَادِعٌ', 'مخادع', 'اسم فاعل', 'خدع', 'مخادع', 'مخدع', 'فَا. مِنْ خَادَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ خَادَعَ). ""عَرَفَهُ مُخَادِعاً"" : مُرَاوِغاً، مُخَاتِلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1549, 'خَائِنٌ', 'خائن', 'اسم فاعل', 'خون', 'خاءن', 'خن', 'فا. مِنْ خَانَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":خَوَّانٌ:خَوَنَةٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ خَانَ). 1."" لَقِيَ الخَائِنُ مَصِيرَهُ"" : الَّذِي يَخُونُ بِلاَدَهُ بِالتَّعَامُلِ مَعَ الْعَدُوِّ. 2. ""خَائِنُ الْعَهْدِ"" : الَّذِي لاَ يَرْعَى العَهْدَ. 3. ""خَائِنَةُ الأعْيُنِ"" : النَّظَرُ بِريبَةٍ، النَّظْرَةُ الْمُريبَةُ أَوِ الْمُخْتَلِسَةُ إِلَى مَا لاَ يَحِلُّ.غافر آية 19 يَعْلَمُ خَائِنَةَ الأعْيُنِ وَمَا تُخْفِي الصُّدُور.(قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1550, 'خوائر', 'خوائر', 'اسم فاعل', '', 'خواءر', 'خر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
