INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1554, 'مُخَاطِرٌ', 'مخاطر', 'اسم فاعل', 'خطر', 'مخاطر', 'مخطر', 'فَا. مِنْ خَاطَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ خَاطَرَ). ""مخُاطِرٌ بِنَفْسِهِ"" : مَنْ يَرْمِي بِنَفْسِهِ إِلَى الْمَخَاطِرِ، الأَخْطَارِ، الْمَهَالِكِ. ""مُخَاطِرَةٌ بِحَيَاتِهَا"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1555, 'خَائِفٌ', 'خائف', 'اسم فاعل', 'خوف', 'خاءف', 'خف', 'فا. مِنْ خَافَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":خُوَّفٌ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ خَافَ). 1. ""كَانَ خَائِفاً مِنَ الْعِقَابِ"" : فَزِعاً، مُرْهَباً. 2.""خَائِفٌ عَلَى أهْلِهِ"" : قَلِقٌ عَلَيْهِمْ. ""وَنَحْنُ خَائِفُونَ، نَرقُبُ السُّكُونَ، فِي حَذَرٍ كَأنَّمَا هُنَاكَ شَيْءٌ لاَ يُرَى"" (أ. عبد المعطي حجازي)."', '');
