INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1603, 'خَاسِئٌ', 'خاسئ', 'اسم فاعل', 'خسأ', 'خاسء', 'خس', 'فا. مِنْ خَسَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"خَاسِئٌ-خَاسِئٌ، ةٌ [خ س أ] (فا. مِنْ خَسَأَ). 1. ""رَجُلٌ خَاسِئٌ"": ذَليـلٌ خَاضِعٌ.الملك آية 4 ثُمَّ ارْجِعِ الْبَصَرَ كَرَّتَيْنِ يَنْقَلِبْ إِلَيْكَ البَصَرُ خَاسِئاً وَهُوَ حَسِير(قرآن). 2. ""كَلْبٌ خَاسِئٌ"" : مَطْرُودٌ، مُبْعَدٌ عَنِ النَّاسِ. الأعراف آية 166فَلَمَّا عَتَـوْا عَنْ مَا نُهُوا عَنْهُ قُلْنَا لَهُمْ كُونُوا قِرَدَةً خَاسِئِينَ(قرآن)."', '');
