INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1632, 'مُخَطِّطٌ', 'مخطط', 'اسم فاعل', 'خطط', 'مخطط', 'مخط', 'فَا. مِنْ خَطَّطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ خَطَّطَ). ""مُخَطِّطٌ نَاجِحٌ"" : مَنْ يَرْسُمُ الخُطَطَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1633, 'خَاطِفٌ', 'خاطف', 'اسم فاعل', 'خطف', 'خاطف', 'خطف', 'فا. من خَطَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":خَوَاطِفُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من خَطَفَ). 1. ""لَمْ يَكُنْ يَرَى إِلاَّ الْبَرْقَ الْخَاطِفَ"" : الْمُشِعَّ وَالْمُخْتَفِيَ بِسُرْعَةٍ. 2. ""خَاطِفُ الذُّبَابِ"" : طَائِرٌ مِنْ رُتْبَةِ الْجَوَاثِمِ، يَصِيدُ الْحَشَرَاتِ الْمُجَنَّحَةَ وَهِيَ طَائِرَةٌ وَيَلْتَهِمُهَا . 3.""تَتَجَوَّلُ ذِئَابٌ خَاطِفَةٌ فِي الْجَبَلِ"" : مُفْتَرِسَةٌ. 4.""تَحَدَّثَ بِصُورَةٍ خَاطِفَةٍ عَنْ رِحْلَتِهِ "" : بِسُرْعَةٍ كَبِيرَةٍ. ""قَابَلَ أهْلَهُ مُقَابَلَةً خَاطِفَةً"" ""زِيَارَةٌ خَاطِفَةٌ"". 5. ""كَانَتْ حَرْباً خَاطِفَةً، حَقَّقَ فِيهَا الْعَدُوُّ نَصْرًا مُؤَقَّتـاً"" : وَجَّهَ فِيهَا ضَرَبَاتٍ مُرَكَّزَةً وَسَرِيعَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1634, 'خَوَاطِفُ', 'خواطف', 'اسم فاعل', '', 'خواطف', 'خطف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
