INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1637, 'خَافِتٌ', 'خافت', 'اسم فاعل', 'خفت', 'خافت', 'خفت', 'فا. من خَفَتَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":خَوافِتُ"', '', '', '', '', '', '', '', '', '"(فا. من خَفَتَ). 1. ""كَلَّمَهُ بِصَوْتٍ خَافِتٍ"" : مُنْخَفِضٍ. ""جَعَلْتُ صَوْتَهُ خَافِتاً أَشَدَّ الْخُفُوتِ""(طه حسين). 2. ""لَمْ تَكُنْ إِلاَّ سَحَابَةَ صَيْفٍ خَافِـتَةً"" : عَابِرَةً لاَ تَحْمِلُ مَطَراً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1638, 'خوافت', 'خوافت', 'اسم فاعل', '', 'خوافت', 'خفت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1639, 'خَوَافِي', 'خوافي', 'اسم فاعل', '', 'خوافي', 'خف', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1640, 'خَافِضٌ', 'خافض', 'اسم فاعل', 'خفض', 'خافض', 'خفض', 'فا. مِنْ خَفَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"خَافِضٌ-خَافِضٌ، ةٌ [خ ف ض] (فا. مِنْ خَفَضَ). 1. ""رَجُلٌ خَافِضُ الْجَنَاحِ"" : وَقُورٌ، سَاكِنٌ. ""خَافِضُ الطَّيْرِ"". 2.""الْخَافِضُ مِنَ الْعَيْشِ"" : الْوَاسِعُ. 3. ""الْخَافِضُ"" : اِسْمٌ مِنْ أسْماءِ اللهِ الْحُسْنَى ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1641, 'خوافض', 'خوافض', 'اسم فاعل', '', 'خوافض', 'خفض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1642, 'خفاض', 'خفاض', 'اسم فاعل', '', 'خفاض', 'خفض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1643, 'خفضة', 'خفضة', 'اسم فاعل', '', 'خفضة', 'خفضة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1644, 'مُخَفِّفٌ', 'مخفف', 'اسم فاعل', 'خفف', 'مخفف', 'مخف', 'فَا. مِنْ خَفَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ خَفَّفَ). ""مُخَفِّفٌ مِنْ أَعْبَائِهِ"" : الَّذِي يُخَفِّفُ، يُلَطِّفُ، الْمُلَطِّفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1645, 'خَافِقٌ', 'خافق', 'اسم فاعل', 'خفق', 'خافق', 'خفق', 'فا. من خَفَقَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":خَوَافِقُ"', '', '', '', '', '', '', '', '', '"(فا. من خَفَقَ). 1. ""يَحْمِلُ رَئِيسُ الْفَيْلَقِ عَلَماً خَافِقاً"" : مُرَفْرِفاً . ""أعْلاَمٌ خَافِقَةٌ"" ""أعْلاَمٌ خَافِقَاتٌ"". 2. ""مَايَزَالُ قَلْبُهُ خَافِقاً"": نَابِضاً، مُخْتَلِجاً. 3. ""اِسْتَغْرَقَهُ النَّظَرُ فِي الْخَافِقِ"" : الأفُقِ، وَهُوَ ذَلِكَ الخَطُّ الدَّائرِيُّ الذِي يُشَاهَدُ بَعِيداً فِي السَّمَاءِ وَيَجْعَلُهَا كَأنَّهَا مُلْتَقِيَةٌ بِالأرْضِ وَهُمَا خَافِقَانِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1646, 'خوافق', 'خوافق', 'اسم فاعل', '', 'خوافق', 'خفق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1647, 'خَافِي', 'خافي', 'اسم فاعل', 'خوف', 'خافي', 'خف', 'فا. من خَفِيَ', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":خَوَافٍ:الْخَوَافِي"', '', '', '', '', '', '', '', '', '"(فا. من خَفِيَ). 1. ""غَيْرُ خَافٍ عَلَيْكَ"" : أيْ غَيْرُ مَسْتُورٍ، مَعْرُوفٌ عِنْدَكَ، ظَاهِرٌ. ""يُظْهِرُ مَا كَانَ خَافِياً"" ""اِنْقَطَعَ الْحَبْلُ وَرَجَاهَا فِي أنْ تَكْتُمَ مَا لَمْ يَعُدْ خَافِياً"". (ع. غلاب). ""أُمُورٌ خَافِيَةٌ عَنْهُ"". 2.""الْخَافِي"" : الْجِنُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1648, 'خفاة', 'خفاة', 'اسم فاعل', '', 'خفاة', 'خفة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1649, 'خَالِصٌ', 'خالص', 'اسم فاعل', 'خلص', 'خالص', 'خلص', 'فا. من خَلَصَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":خُلَّصٌ"', '', '', '', '', '', '', '', '', '"(فا. من خَلَصَ). 1. ""ذَهَبٌ خَالِصٌ"" : ذَهَبٌ مِنْ عِيَارٍ حَقِيقِيٍّ، صَافٍ. 2. ""تَلْبَسُ ثَوْباً خَالِصاً"" : أَيْ شَدِيدَ البَيَاضِ، نَاصِعَ اللَّوْنِ. 3."" بَضَائِعُ خَالِصَةٌ مِنَ الْجُمْرُكِ"" : مُعْفَاةٌ مِنَ الرُّسُومِ. ""خَالِصٌ مِنَ الرُّسُومِ الْجُمْرُكِيَّةِ"". 4.""أَصْبَحَ خَالِصاً مِنْ كُلِّ دُيُونِهِ"" : مُتَحَرِّرًا مِنْ كُلِّ دَيْنٍ، أَدَّى مَا كَانَ عَلَيْهِ مِنْ دَيْنٍ. 5. ""نَسَبٌ خَالِصٌ"" : لاَ شَائِبَةَ فِيه."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1650, 'خَالِي', 'خالي', 'اسم فاعل', 'خلو', 'خالي', 'خل', 'فا. من خَلاَ', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":خَوَالٍ:الْخَوَالِي"', '', '', '', '', '', '', '', '', '"(فا. من خَلاَ). 1.""لاَ يُوجَدُ إِنْسَانٌ خَالٍ مِـنَ الْعُيُوبِ"" : مُنَزَّهٌ عَنْ ... 2.""كِتَابٌ خَالٍ مِنَ الْفَائِدَةِ"" : لاَ فَائِدَةَ فِيهِ، عَدِيمُهَا. 3.""الشَّابُّ الْخَالِي"" : الْعَزَبُ الَّذِي لاَ امْرَأةَ لَهُ. 4.""اِمْرَأَةٌ خَالِيَةٌ"" : عَزَبَةٌ، الَّتِي لاَزَوْجَ لَهَا. 5.""هُوَ خَالي البَالِ"" : لاَشَيْءَ يَشْغَلُهُ. ""خَالِي الذِّهْنِ"". 6. ""جَاءَ خَالِيَ الْوِفَاضِ"" : لاَ شَيْءَ مَعَهُ. 7."" تَبْكِي أَيَّامَهَا الْخَالِيَةَ"" : الأَيَّامَ الْمَاضِيَةَ الَّتِي لَمْ تَأْتِ بِشَيْءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1651, 'خلاة', 'خلاة', 'اسم فاعل', '', 'خلاة', 'خلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1652, 'خَوَالِي', 'خوالي', 'اسم فاعل', '', 'خوالي', 'خل', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1653, 'خَالِجٌ', 'خالج', 'اسم فاعل', 'خلج', 'خالج', 'خلج', 'فا. مِنْ خَلَجَ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"خَالِجٌ-خَالِجٌ [خ ل ج] (فا. مِنْ خَلَجَ). ""أَخَذَهُ الْخَالِجُ"" : الْمَوْتُ لِأنَّهُ يَخْلِجُ الخَلِيقَةَ، أيْ يَجْذِبُ أَرْوَاحَهَا وَيَنْتَزِعُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1654, 'خَالِدٌ', 'خالد', 'اسم فاعل', 'خلد', 'خالد', 'خلد', 'فا. مِنْ خَلَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِنْ خَلَدَ). 1.""عَمَلٌ خَالِدٌ"" : بَاقٍ، دَائِمٌ. ""بَقِيَ ذِكْرُهُ خَالِداً"" ""ذِكْرَى خَالِدَةٌ"". 2.""لَيْسَ بِخَالِدٍ فِي هَذِهِ الدُّنْيَا"" : غَيْرُ مُقِيمٍ فِيهَا إِلَى الأبَدِ. يُقَتِّرُ عِيسَى عَلَـى نَفْسِـهِ*وَلَيْـسَ بِبَاقٍ وَلاَ خَـالِدٍ (ابن الرومي). 3. ""قَادَ خَالِدُ بْنُ الْوَلِيدِ مَعْرَكَةً حَاسِمَةً"" : اِسْمُ عَلَمٍ لِلْمُذَكَّرِ. ""خَالِدَة"" : اِسْمُ عَلَمٍ لِلإِنَاثِ."', '');
