INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1686, 'دعبة', 'دعبة', 'اسم فاعل', '', 'دعبة', 'دعبة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1687, 'مُدَافِعٌ', 'مدافع', 'اسم فاعل', 'دفع', 'مدافع', 'مدفع', 'فَا. مِنْ دَافَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ دَافَعَ). ""مُدَافِعٌ عَنِ القِيَمِ النَّبِيلَةِ"" : أَيْ مَنْ يَتَوَلَّى الدِّفَاعَ عَنْهَا، الْمُحَامِي. ""مُدَافِعٌ عَنْ حَيَاتِهِ وَعَنْ عِرْضِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1688, 'دَائِمٌ', 'دائم', 'اسم فاعل', 'دوم', 'داءم', 'دم', 'فا. من دَامَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من دَامَ). 1.""هُوَ اللَّهُ الدَّائِمُ"" : مِنْ أسْمَاءِ اللًّهِ الحُسْنَى، أي الخَالِدُ، الثَّابِت. 2.""عَبْدُ الدَّائِمِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ. 3. ""بَلَدٌ دَائِمُ التَّقَدُّمِ"" : فِي تَقَدُّمٍ مُسْتَمِرٍّ. 4. ""دَائِماً"" : أبَداً، عَلَى نَحْوٍ مُسْتَقِيمٍ، فِي كُلِّ حِينٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1689, 'دَاثِرٌ', 'داثر', 'اسم فاعل', 'دثر', 'داثر', 'دثر', 'فا. مِنْ دَثَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":دَوَاثِرُ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ دَثَرَ). 1. ""أثَرٌ دَاثِرٌ"": صَارَ مُمَّحِيّاً، مَمْحُوّاً، مُنْدَثِراً، مُتَلاَشِياً. 2. ""أمْرٌ دَاثِرٌ"" : لاَ يُعْبَأُ بِهِ. 3. ""أَمْرُهُ دَاثِرٌ"" : هَالِكٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1690, 'دَائِنٌ', 'دائن', 'اسم فاعل', 'دين', 'داءن', 'دن', 'فا. من دَانَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من دَانَ). ""فرَضَ عَلَيْهِ الدَّائِنُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1691, 'دوائن', 'دوائن', 'اسم فاعل', '', 'دواءن', 'دن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1692, 'مُدَاهِمٌ', 'مداهم', 'اسم فاعل', 'دهم', 'مداهم', 'مدهم', 'فَا. مِنْ دَاهَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ دَاهَمَ). ""مُدَاهِمٌ لِلْبُيُوتِ لَيْلاً"" : مُهَاجِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1693, 'مُدَاهِنٌ', 'مداهن', 'اسم فاعل', 'دهن', 'مداهن', 'مدهن', 'فَا. مِنْ دَاهَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ دَاهَنَ). ""مُدَاهِنٌ لِلنَّاسِ"" : مُدَارٍ، مُلاَيِنٌ، مُصَانِعٌ لَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1694, 'مُدَاوِرٌ', 'مداور', 'اسم فاعل', 'دور', 'مداور', 'مدر', 'فَا. مِنْ دَاوَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ دَاوَرَ). ""مُدَاوِرٌ لِزُبُنِهِ"" : مُرَاوِغٌ، مُخَادِعٌ لَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1695, 'مُدَاوِمٌ', 'مداوم', 'اسم فاعل', 'دوم', 'مداوم', 'مدم', 'فَا. مِنْ دَاوَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ دَاوَمَ). ""مُدَاوِمٌ عَلَى العَمَلِ"" : مُوَاظِبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1696, 'مُدَبِّرٌ', 'مدبر', 'اسم فاعل', 'دبر', 'مدبر', 'مدبر', 'فَا. مِنْ دَبَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ دَبَّرَ). 1.""مُدَبِّرُهَا حَكِيمٌ"" : مَنْ يُسَوِّي الأُمُورَ وَيُعَالِجُهَا. 2.""مُدَبِّرُ الدَّيْرِ"" : مَنْ يُشَارِكُ الرَّئِيسَ الأَكْبَرَ فِي رَأْيِهِ. 3.""مُدَبِّرَةُ شُؤُونِ البَيْتِ"" : القَائِمَةُ عَلَى شُؤُونِهِ وَتَدْبِيرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1697, 'دَابِرٌ', 'دابر', 'اسم فاعل', 'دبر', 'دابر', 'دبر', 'فا. من دَبَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":دَوَابِرُ"', '', '', '', '', '', '', '', '', '"(فا. من دَبَرَ). 1.""وَقَعَ ذَلِكَ فِي الزَّمَنِ الدَّابِرِ"" : في الزَّمَنِ الغابِرِ، فِي الْمَاضِي البَعِيدِ. 2.""ذَهَبَ كَأَمْسِ الدَّابِرِ"" : ذَهَبَ دُونَ أنْ يَتْرُكَ أثَراً. 3.""قَطَعَ دَابِرَهُمْ"": اِسْتَأْصَلَهُمْ عَنْ آخِرِهِمْ. الأنعام آية 45 فَقُطِعَ دَابِرُ القَوْمِ الَّذِينَ ظَلَمُوا (قرآن). 4. ""دَابِرَةُ الحَيَوَانِ"" : عُرْقُوبُهُ. 5.""دَابِرَةُ الطَّيْرِ"" : الأصْبُعُ الَّذِي وَرَاءَ رِجْلَيْهِ. 6. ""دَابِرَةُ الحَافِرِ"" ‎: مُؤَخَّرُ الرُّسْغِ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1698, 'دَوَابِرُ', 'دوابر', 'اسم فاعل', '', 'دوابر', 'دبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1699, 'دَوَاثِرُ', 'دواثر', 'اسم فاعل', '', 'دواثر', 'دثر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1700, 'دَاجِنٌ', 'داجن', 'اسم فاعل', 'دجن', 'داجن', 'دجن', 'فا. من دَجَنَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":دَوَاجِنُ"', '', '', '', '', '', '', '', '', '"(فا. من دَجَنَ). 1.""يُرَبِّي الدَّاوَجِنَ"" : الطُّيًور وَالحَيَوانَات الألِيفَة كَالأرَانِبِ وَالحَمَامِ وَالدَّجَاجِ. 2. ""لَيْلٌ دَاجِنٌ"" : داجٍ، مُظْلِمٌ. 3. ""أمْطَرَتْ لَيْلَةُ الأمْسِ أمْطَاراً دَاجِنَةً"" : أمْطَاراً كَثِيرَةً، عَظِيمَةً. 4. ""سَحَابةٌ دَاجِنَةٌ"" : مُمْطِرَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1701, 'دَوَاجِنُ', 'دواجن', 'اسم فاعل', '', 'دواجن', 'دجن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1702, 'دَاجِي', 'داجي', 'اسم فاعل', 'دجو', 'داجي', 'دج', 'فا. من دَجَى', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دَاجٍ-دَاجٍ، الدَّاجِي، ةٌ [د ج و] (فا. من دَجَى). 1. ""إنَّهُ لَيْلٌ دَاجٍ"" : داجِنٌ، مُظْلِمٌ. ""لَيْلٌ دَاجٍ وَنَهارٌ سَاجٍ"". 2. ""فِي عَيْشٍ دَاجٍ"": رَغِيدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1703, 'دواجي', 'دواجي', 'اسم فاعل', '', 'دواجي', 'دج', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1704, 'رَاسِي', 'راسي', 'اسم فاعل', 'رسو', 'راسي', 'رس', '', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":الرَّواسِي"', '', '', '', '', '', '', '', '', '". 1.""مَازَالَتِ السَّفِينَةُ رَاسِيَةً فِي المِينَاءِ"" : ثَابِتَةً. 2.""قِدْرٌ رَاسِيَةٌ"" : لاَ تَبْرَحُ مَكَانَهَا وَلاَ يُطَاقُ تَحوِيلُهُا لِعِظَمِها.سبأ آية 13وجِفَانٍ كَالْجَوَابِ وَقُدورٍ رَاسِياتٍ (قرآن). 3.""الرَّاسِيَاتُ"" : الجِبَالُ الثَّوابِتُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1705, 'رواسي', 'رواسي', 'اسم فاعل', '', 'رواسي', 'رس', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1706, 'دَاحِسٌ', 'داحس', 'اسم فاعل', 'دحس', 'داحس', 'دحس', 'فا. من دَحِسَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دَاحِسٌ-دَاحِسٌ [د ح س] (فا. من دَحِسَ). ""أُصِيبَ أصْبُعُهُ بالدَّاحِسِ"" : وَرَمٌ وَتَقيُّحٌ فِي الأُصْبُعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1707, 'دواحس', 'دواحس', 'اسم فاعل', '', 'دواحس', 'دحس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1708, 'دَاخِلٌ', 'داخل', 'اسم فاعل', 'دخل', 'داخل', 'دخل', 'فا. من دَخَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من دَخَلَ). 1.""لَمْ يَحِسَّ بِشَيْءٍ وَهُوَ دَاخِلٌ إلَى بَيْتِهِ"" : وَهُوَ يَهُمُّ بِالدُّخُولِ، بِوُلُوجِ البَيْتِ. 2. ""كَانَ بِدَاخِلِ السَّيَّارَةِ"" : فِي قَلْبِهَا. 3.""يَتَكَلَّمُ مِنْ دَاخِلِ الدَّارِ"" : مِنْ جَوِّهَا. 4. ""دَاخِلاً"": ضِمْناً، بَاطِناً. 5.""دَاخِلٌ فِي حِسَابِهِ"" : مَحْسُوبٌ، مَعْدُودٌ."', '');
