INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1712, 'مُدَرِّبٌ', 'مدرب', 'اسم فاعل', 'درب', 'مدرب', 'مدرب', 'فَا. مِنْ دَرَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُدَرَّبٌ-مُدَرَّبٌ [د ر ب] (مفع. مِنْ دَرَّبَ). 1.""مُدَرَّبٌ عَلَى صُعُودِ الجِبَالِ"" : مُتَعَوِّدٌ...، مُجَرِّبٌ. 2.""رَجُلٌ مَدَرَّبٌ"": مُصابٌ بِالمَصائِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1713, 'دَارِجٌ', 'دارج', 'اسم فاعل', 'درج', 'دارج', 'درج', 'فا. من دَرَجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"دَارِجٌ-دَارِجٌ، ةٌ [د ر ج] (فا. من دَرَجَ). 1. ""عَمَلٌ دَارِجٌ"" : مَأْلُوفٌ، مُتَدَاوَلٌ. 2.""اللُّغَةُ الدَّارِجَةُ"" : العَامِيَّةُ الَّتِي يَتَحدَّثُ بِهَا عَامَّةُ الشَّعْبِ. ""كَلاَمٌ دَارِجٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1714, 'دوارج', 'دوارج', 'اسم فاعل', '', 'دوارج', 'درج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
