INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1718, 'دَارِسٌ', 'دارس', 'اسم فاعل', 'درس', 'دارس', 'درس', 'فا. من دَرَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":دَوَارِسُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من دَرَسَ). ""رَسْمٌ دَارِسٌ"" : عَفَا وَامَّحَى. ""أَثَرٌ دَارِسٌ وَذِكْرَيَاتٌ قَائِمَةٌ""."', '');
