INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1726, 'درعة', 'درعة', 'اسم فاعل', '', 'درعة', 'درعة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1727, 'دَارِكٌ', 'دارك', 'اسم فاعل', 'درك', 'دارك', 'درك', 'فا. من دَرَكَ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"دَارِكٌ-دَارِكٌ [د ر ك] (فا. من دَرَكَ). 1. ""سَيْرٌ دَارِكٌ"" : مُتَلاَحِقٌ، مُتَوَاصِلٌ. 2. ""طَعْنٌ دَارِكٌ"" : مُتَتَابِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1728, 'دَاعِي', 'داعي', 'اسم فاعل', 'دعو', 'داعي', 'دع', 'فا. من دَعَا', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":دُعَاةٌ:دَوَاعٍ:الدَّوَاعِي"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من دَعَا). 1. ""كَانَ دَاعِياً لِدِينِ الحَقِّ"" : مَنْ يَدْعُو النَّاسَ إلَى دِينِ الحَقِّ، التَّقِيُّ الْمُصْلِحُ. ""إنَّهُ مِنَ الدُّعَاةِ"". 2. ""دَاعِي اللَّهِ"" : مِنْ ألْقَابِ النَّبِيِّ. 3. ""شَيْخٌ دَاعِيَةٌ"": الَّذِي يَدْعُو النَّاسَ إلَى دِينِهِ وَمَبَادِئِهِ أوْ مَذْهَبِهِ. وَالتَّاءُ لِلْمُبَالَغَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1729, 'دَافِعٌ', 'دافع', 'اسم فاعل', 'دفع', 'دافع', 'دفع', 'فا. من دَفَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":دَوَافِعُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من دَفَعَ). 1. ""بِدَافِعِ الحُبِّ"" : بحَافِزِ الحُبِّ، بِبَاعِثٍ. 2. ""مَا الدَّافِعُ إلَى كُلِّ هَذَا"" : مَا الدَّاعِي. 3. ""دَافِعُ الحِسَابِ"" : مَنْ يَدْفَعُهُ. ""دَافِعُ الضَّرَائِبِ"". 4. ""القُوَّةُ الدَّافِعَةُ"" : القُوَّةُ الَّتِي تَنْدَفِعُ مِنَ الخَارِجِ وَالبَعِيدَةُ عَنِ الْمَرْكَزِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1730, 'دَوَاعِي', 'دواعي', 'اسم فاعل', '', 'دواعي', 'دع', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1731, 'دَاعِرٌ', 'داعر', 'اسم فاعل', 'دعر', 'داعر', 'دعر', 'فا. من دَعَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":دُعَّارٌ"', '', '', '', '', '', '', '', '', '"(فا. من دَعَرَ). 1. ""تَفَوَّهَ بِكَلاَمٍ دَاعِرٍ"" : فَاحِشٍ، فَاجِرٍ. 2. ""وَلَدٌ دَاعِرٌ"" : خَبِيثٌ، فَاسِدُ السُّلُوكِ."', '');
