INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1743, 'دَافِقٌ', 'دافق', 'اسم فاعل', 'دفق', 'دافق', 'دفق', 'فا. مِنْ دَفَقَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دَافِقٌ-دَافِقٌ، ةٌ [د ف ق] (فا. مِنْ دَفَقَ). ""جَرَى الْمَاءُ دَافِقاً مِنَ الصِّهْرِيجِ"" : فَائِضاً مِنْ جَوَانِبِهِ، ذُو دَفْقٍ.الطارق آية 6خُلِقَ مِنْ مَاءٍ دَافِقٍ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1744, 'دوافق', 'دوافق', 'اسم فاعل', '', 'دوافق', 'دفق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1745, 'مُدَقِّقٌ', 'مدقق', 'اسم فاعل', 'دقق', 'مدقق', 'مدق', 'فَا. مِنْ دَقَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ دَقَّقَ). ""مُدَقِّقُ الحِسَابَاتِ"" : الْمُسْتَقْصِي لِلْأَرْقَامِ بِدِقَّةٍ وَمُتَفَحِّصُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1746, 'دَاكِنٌ', 'داكن', 'اسم فاعل', 'دكن', 'داكن', 'دكن', 'فا. مِنْ دَكِنَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دَاكِنٌ-دَاكِنٌ، ةٌ [د ك ن] (فا. مِنْ دَكِنَ). ""لَوْنٌ دَاكِنٌ"" : مَائِلٌ إلَى السَّوَادِ. ""تَزِيدُ الأرْضُ بِتُرَابِهَا الدَّاكِنِ فِي جَهْمَةِ ذَلكَ اليَوْمِ الغَائِمِ"" (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1747, 'دواكن', 'دواكن', 'اسم فاعل', '', 'دواكن', 'دكن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1748, 'دَالِفٌ', 'دالف', 'اسم فاعل', 'دلف', 'دالف', 'دلف', 'فا. من دَلَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":دُلَّفٌ:دُلُفٌ"', '', '', '', '', '', '', '', '', '"(فا. من دَلَفَ). 1.""رَجُلٌ دَالِفٌ"" : كَبِيرٌ أخْضَعَتْهُ السِّنُّ. 2.""سَهْمٌ دَالِفٌ"" : سَهْمٌ يُصِيبُ مَا دُونَ الغَرَضِ وَيَنْبُو عَنْ مَوْضِعِهِ. 3.""عَامِلٌ دَالِفٌ"" : مَاشٍ بِالحِمْلِ الثَّقِيلِ مُقَارِباً الخَطْوَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1749, 'مُدَمْدِمٌ', 'مدمدم', 'اسم فاعل', 'دمدم', 'مدمدم', 'مدمدم', 'فَا. مِنْ دَمْدَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ دَمْدَمَ). ""مُدَمْدِمٌ عَلَيْهِمْ"" : غَاضِبٌ عَلَيْهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1750, 'دُلُفٌ', 'دلف', 'اسم فاعل', '', 'دلف', 'دلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
