INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1760, 'مُدَمِّرٌ', 'مدمر', 'اسم فاعل', 'دمر', 'مدمر', 'مدمر', 'فَا. مِنْ دَمَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ دَمَّرَ). 1.""سِلاَحٌ مُدَمِّرٌ"" : سِلاَحٌ مُهَدِّمٌ لِكُلِّ شَيْءٍ. 2.""جَهَزَّ الجَيْشَ بِمُدَمِّرَةٍ جَدِيدَةٍ"" : سَفِينَة حَرْبِيَّة مُجَهَّزَة بِآلاَتِ الْهُجُومِ وَالتَّدْمِيرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1761, 'دَامِسٌ', 'دامس', 'اسم فاعل', 'دمس', 'دامس', 'دمس', 'فا. مِنْ دَمَسَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دَامِسٌ-دَامِسٌ، ةٌ [د م س] (فا. مِنْ دَمَسَ). ""لَيْلٌ دَامِسٌ"": لَيْلٌ مُظْلِمٌ، دَامِجٌ، دَاجٍ."', '');
