INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1763, 'دَامِغٌ', 'دامغ', 'اسم فاعل', 'دمغ', 'دامغ', 'دمغ', 'فا. من دَمَغَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دَامِغٌ-دَامِغٌ، ةٌ [د م غ] (فا. من دَمَغَ). 1. ""قَدَّمَ دَلِيلاً دَامِغاً عَلَى بَرَاءتِهِ"" : مُقْنِعاً، حَاسِماً، قَاطِعاً. ""قَدَّمَ حُجَجاً دَامِغَةً"". 2. ""كَانَتْ شَهَادتُهُ دَامِغَةً"" : فَاصِلَةً، قَاطِعَةً، حَاسِمَةً، لاَ تُدْحَضُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1764, 'دوامغ', 'دوامغ', 'اسم فاعل', '', 'دوامغ', 'دمغ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1765, 'دَامِي', 'دامي', 'اسم فاعل', 'دمي', 'دامي', 'دم', 'فا. من دَمِيَ', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دَامٍ-دَامٍ، الدَّامِي، ةٌ [د م ي] (فا. من دَمِيَ). 1.""عِرَاكٌ دَامٍ"" : عِرَاكٌ نَتَجَ عَنْهُ سَيَلاَنُ الدَّمِ. 2. ""وَصَلَ دَامِيَ الوَجْهِ"" : أيْ سَائِلاً مِنْهُ ‎الدَّمُ. ""نَشَبَتْ بَيْنَ الفَرِيقَيْنِ مَعْرَكَةٌ دَامِيَةٌ"". 3.""دَامِي القَلْبِ"" : كَئِيبٌ، حَزِينٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1766, 'دوامي', 'دوامي', 'اسم فاعل', '', 'دوامي', 'دم', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1767, 'دَانِي', 'داني', 'اسم فاعل', 'دنو', 'داني', 'دن', 'فا. من دَنَا', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":دُنَاةٌ"', '', '', '', '', '', '', '', '', '"(فا. من دَنَا). ""عَلِمَ الأمْرَ القَاصِي وَالدَّانِي"" : البَعِيدُ وَالقَرِيبُ."', '');
