INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1770, 'مُدَنْدِنٌ', 'مدندن', 'اسم فاعل', 'دندن', 'مدندن', 'مدندن', 'فَا. مِنْ دَنْدَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ دَنْدَنَ). ""سَمِعَهُ مُدَنْدِناً بِكَلِمَاتٍ لَمْ يَفْهَمْ فَحْوَاهَا"" : مُرَدِّداً كَلِمَاتٍ بِصَوْتٍ خَافِتٍ لاَ يُفْهَمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1771, 'مُدَنِّسٌ', 'مدنس', 'اسم فاعل', 'دنس', 'مدنس', 'مدنس', 'فَا. مِنْ دَنَّسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ دَنَّسَ). ""مُدَنِّسٌ لِلْحُرُمَاتِ"" : مَنْ يُدَنِّسُ الْحُرُمَاتِ، أَيْ يُوَسِّخُ وَيُلَطِّخُ بِكُلِّ مَا هُوَ مَكْرُوهٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1772, 'دَاهِي', 'داهي', 'اسم فاعل', 'دهي', 'داهي', 'ده', 'فا. من دَهِيَ', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":دُهَاةٌ"', '', '', '', '', '', '', '', '', '"(فا. من دَهِيَ). 1. ""رَجُلٌ دَاهٍ"" : مَنْ يَتصَرَّفُ بِدَهَاءٍ. 2. ""كَانَ دَاهِيَةَ عَصْرِهِ"" : مَاكِراً، شَيْطَاناً، مُخَاتِلاً."', '');
