INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1775, 'دَاوِي', 'داوي', 'اسم فاعل', 'دوي', 'داوي', 'د', 'فا. من دَوِيَ', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دَاوٍ-دَاوٍ، الدَّاوِي، ةُ [د و ي] (فا. من دَوِيَ). ""جَاءَ صَوْتُهُ دَاوِياً مِنْ أَعْلَى الجَبَلِ"" : صَاخِباً، عَالِياً."', '');
