INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1802, 'رَائِبٌ', 'رائب', 'اسم فاعل', 'روب', 'راءب', 'رب', 'فا. مِنْ رَابَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"رَائِبٌ-رَائِبٌ، ةٌ [ر و ب] (فا. مِنْ رَابَ). ""شَرِبَ لَبَناً رَائِباً"": خَاثِراً. ""وَتَأْتِي تِلْكَ الفَلاَّحَةُ حَامِلَةً قِدْراً فَخَّارِيّاً فِيهِ لَبَنٌ رَائِبٌ"" (حَنَّا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1803, 'روائب', 'روائب', 'اسم فاعل', '', 'رواءب', 'رب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1804, 'مُرَابِي', 'مرابي', 'اسم فاعل', 'ربو', 'مرابي', 'مرب', 'فا. من رَابَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من رَابَى). ""التَّاجِرُ الْمُرَابِي"" : مَنْ يُقْرِضُ بِالفَائِدَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1805, 'رائِجٌ', 'رائج', 'اسم فاعل', 'روج', 'راءج', 'رج', 'فا. مِنْ رَاجَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رائِجٌ-رائِجٌ، ةٌ [ر و ج] (فا. مِنْ رَاجَ). ""آلاَتٌ رَائِجَةٌ"" : مُتَدَاوَلَةٌ بَيْنَ النَّاسِ. ""عُمْلَةٌ رَائِجَةٌ"" ""أُغْنِيَّةٌ رَائِجَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1806, 'روائج', 'روائج', 'اسم فاعل', '', 'رواءج', 'رج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1807, 'رَائِحٌ', 'رائح', 'اسم فاعل', 'روح', 'راءح', 'رح', 'فا. مِنْ رَاحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِنْ رَاحَ). ""رَائِحٌ إلَى بَيْتِهِ"" : ذَاهِبٌ إلَيْهِ. ""نَرَى النَّاسَ غَادِينَ رَائِحِينَ"" (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1808, 'روائح', 'روائح', 'اسم فاعل', '', 'رواءح', 'رح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1809, 'رَائِدٌ', 'رائد', 'اسم فاعل', 'رود', 'راءد', 'رد', 'فا. من رادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":رُوَّادٌ:رَوَائِدُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من رادَ). 1. ""رَائِدُ قَوْمِهِ"" : مَنْ يَتَقَدَّمُ قَوْمَهُ وَيُنِيرُ لَهُمُ الطَّرِيقَ. الرَّائِدُ لاَ يَكْذِبُ أَهْلَهُ ( حديث ) . 2.""رَائِدُ الشِّعْرِ الحَدِيثِ"" : إِمَامُ الشُّعَرَاءِ. 3. ""رَائِدُ الفَضَاءِ"" : مَنْ يَشُقُّ الطَّرِيقَ إلَى الفَضَاءِ دَاخِلَ مَرْكَبَةٍ فَضَائِيَّةٍ. ""رَائِدَةُ الفَضَاءِ"" ""رُوَّادُ الفَضَاءِ"". 4. ""رَائِدُ الضُّحَى"" : وَقْتُ ارْتِفَاعِ الشَّمْسِ وَانْبِسَاطِ النُّورِ فِي أَوَّلِ النَّهَارِ. 5. ""رَائِدٌ فِي الجَيْشِ"": ضَابِطٌ لَهُ رُتْبَةٌ عَسْكَريَّةٌ. 6. ""هَبَّتْ رِيحٌ رَائِدَةٌ"" : خَفِيفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1810, 'رُوَّادٌ', 'رواد', 'اسم فاعل', '', 'رواد', 'رد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1811, 'رَوَائِدُ', 'روائد', 'اسم فاعل', '', 'رواءد', 'رد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1812, 'مُرَادِفٌ', 'مرادف', 'اسم فاعل', 'ردف', 'مرادف', 'مردف', 'فَا. مِنْ رَادَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ رَادَفَ). 1.""جَاءَ بِمُرَادِفٍ لِكَلِمَةِ: عَالَمٌ"" : أَيْ جَاءَ بِكَلِمَةٍ تُطَابِقُ كَلِمَةَ ""عَالَم"" فِي الْمَعْنَى، وَالْمُرَادِفَاتُ هِيَ مَا يُطَابِقُ غَيْرَهَا فِي الْمَعْنَى مِنَ الأَلْفَاظِ. 2.""مُرَادِفٌ لَهُ"" : مُمَاثِلٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1813, 'رَائِزٌ', 'رائز', 'اسم فاعل', 'رأز', 'راءز', 'رز', 'فا. مِنْ رازَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":رَوَائِزُ:رَازَةٌ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ رازَ).: مِعْيَارٌ، وَسِيلَةٌ اخْتِبَارِيَّةُ في عِلْمِ النَّفْسِ والتَّربِيَةِ، يُمَيَّزُ بِهَا بَيْنَ أفْرادِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1814, 'رَوَائِزُ', 'روائز', 'اسم فاعل', '', 'رواءز', 'رز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1815, 'رَازَةٌ', 'رازة', 'اسم فاعل', '', 'رازة', 'رزة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1816, 'مُرَاسِلٌ', 'مراسل', 'اسم فاعل', 'رسل', 'مراسل', 'مرسل', 'فَا. مِنْ رَاسَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ رَاسَلَ). 1.""مُرَاسِلُ الإِدَارَةِ"" : مَنْ يَتَكَلَّفُ بِتَوْصِيلِ الْمُرَاسَلاَتِ وَالنَّشَرَاتِ بَيْنَ مُوَظَّفِي الإِدَارَةِ الوَاحِدَةِ. 2.""مُرَاسِلُ الجَرِيدَةِ"" : هُوَ الصَّحَفِيُّ الَّذِي يُزَوِّدُ جَرِيدَتَهُ بِأَخْبَارٍ وَمَعْلُومَاتٍ مِنْ مِنْطَقَةٍ مُعَيَّنَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1817, 'رَائِعٌ', 'رائع', 'اسم فاعل', 'روع', 'راءع', 'رع', 'فا. مِنْ رَاعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":رَوَائِعُ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ رَاعَ). 1. ""كَانَ رَائِعاً فِي عَمَلِهِ"" : كُلُّ مَا يُثِيرُ الإِعْجَابَ وَيَشُدُّ الانْتِبَاهَ. 2. ""أَتَى بِكَلامٍ رَائِعٍ"" : أيْ حَسَنٍ، رَائِقٍ، جَمِيلٍ. ""قَدَّمَ فِكْرَةً رَائِعَةً"" : رَائِقَةً مُثِيرَةً لِلإعْجَابِ. 3.""اِحْتَدَّ الحَرُّ فِي رائِعَةِ النَّهَارِ"" : فِي وَسَطِهِ، أَي الظَّهِيرَة. 4.""قَصِيدَةٌ مِنْ رَوَائِعِ الشِّعْرِ العَرَبِيِّ"" : مِنْ عُيُونِ الشِّعْرِ العَرَبِيِّ، مِنْ أَجْمَلِ قَصَائِدِهِ. 5.""لَوْحَةٌ مِنْ رَاوَئِعِ الفَنِّ"" : مِنَ التُّحَفِ الفَنِّيَّةِ الجَميلَةِ. 6.""رَائِعَةُ القَمَرِ"" : مُعْظَمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1818, 'رَوَائِعُ', 'روائع', 'اسم فاعل', '', 'رواءع', 'رع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1819, 'ربحة', 'ربحة', 'اسم فاعل', '', 'ربحة', 'ربحة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1820, 'مُرَافِعٌ', 'مرافع', 'اسم فاعل', 'رفع', 'مرافع', 'مرفع', 'فَا. مِنْ رَافَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُرَافِعٌ-مُرَافِعٌ [ر ف ع] (فَا. مِنْ رَافَعَ). ""جَعَلَ أَمْرَهُ بِيَدِ الْمُرَافِعِ"" : الْمُحَامِي أَوِ الْمُدَّعِي العَامّ الَّذِي يُقَدِّمُ مُرَافَعَتَهُ أَمَامَ القُضَاةِ فِي الْمَحْكَمَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1821, 'مُرَافِقٌ', 'مرافق', 'اسم فاعل', 'رفق', 'مرافق', 'مرفق', 'فَا. مِنْ رَافَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ رَافَقَ). ""مُرَافِقُ الرَّئِيسِ"" : مَنْ يُصَاحِبُهُ، يُرَافِقُهُ، الرَّفِيقُ. ""مُرَافِقُ الوَفْدِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1822, 'رَائِقٌ', 'رائق', 'اسم فاعل', 'روق', 'راءق', 'رق', 'فا. مِنْ رَاقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"رَائِقٌ-رَائِقٌ، ةٌ [ر و ق] (فا. مِنْ رَاقَ). 1. ""الجَوُّ رَائِقٌ هَذَا الْمَسَاءَ"" : صَافٍ. 2. ""شَرَابٌ رَائِقٌ"" : مُصَفّىً. 3. ""الرَّائِقُ مِنَ المِسْكِ"" : الخَالِصُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1823, 'روائق', 'روائق', 'اسم فاعل', '', 'رواءق', 'رق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1824, 'مُرَاقِبٌ', 'مراقب', 'اسم فاعل', 'رقب', 'مراقب', 'مرقب', 'فا. من رَاقَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من رَاقَبَ). 1.""مُرَاقِبُ الْمَعْمَلِ"" : مَنْ يُرَاقِبُ سَيْرَهُ وَعَمَلَهُ. ""مُرَاقِبُ الامْتِحَانِ"" "" مُرَاقِبُ التَّعْلِيمِ"". 2.""مُرَاقِبُ الحِسَابَاتِ"": القَائِمُ عَلَى مُرَاقَبَةِ سَيْرِ الْحِسَابَاتِ وَمُرَاجَعَتِهَا وَالتَّأَكُّدِ مِنْ سَلاَمَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1825, 'مُرَاهِقٌ', 'مراهق', 'اسم فاعل', 'رهق', 'مراهق', 'مرهق', 'فَا. مِنْ رَاهَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ رَاهَقَ). ""شَابٌّ مُرَاهِقٌ"" : قَارَبَ الرُّشْدَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1826, 'رَابِحٌ', 'رابح', 'اسم فاعل', 'ربح', 'رابح', 'ربح', 'فا. مِنْ رَبِحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ رَبِحَ). 1.""وَجَدَ نَفْسَهُ رَابِحاً"" : كَاسِباً، ذا رِبْحٍ. 2.""اِخْتَارَ تِجَارَةً رَابِحَةً"" : تِجَارَةً تَدُرُّ عَلَيْهِ بِمَكَاسِبَ."', '');
