INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1983, 'رَامِي', 'رامي', 'اسم فاعل', 'رمي', 'رامي', 'رم', 'فا. مِنْ رَمى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":رُمَاةٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ رَمى). 1. ""كَانَ رَامِياً مَاهِراً"" : مَنْ يُسَدِّدُ السَّهْمَ أوِ الرَّصَاصَ نَحْوَ هَدَفٍ مُعَيَّنٍ. 2. ""رُبَّ رَمْيَةٍ مِنْ غَيْرِ رَامٍ"".(مثل) : يُضْرَبُ لِمَنْ يُصِيبُ هَدفاً وَعادَتُهُ أنْ يُخْطِئَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1984, 'رُمَاةٌ', 'رماة', 'اسم فاعل', '', 'رماة', 'رمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1985, 'روامي', 'روامي', 'اسم فاعل', '', 'روامي', 'رم', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1986, 'رَاهِبٌ', 'راهب', 'اسم فاعل', 'رهب', 'راهب', 'رهب', 'فا. من رَهِبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":رُهْبَانٌ:رَوَاهِبُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من رَهِبَ). 1. ""رَاهِبُ الكَنِيسَةِ"" : الْمُتَعَبِّدُ وَالْمُعْتَزِل الزَّاهِدُ.المائدة آية 82 ذَلِكَ بِأَنَّ مِنْهُمْ قِسِّيسِينَ وَرُهْبَاناً (قرآن) ""يَتَعبَّدُ بِعَمَلِهِ كَما يَتَعَبَّدُ الرَّاهِبُ فِي صَوْمَعَتِهِ""(أ. أمين). 2. ""اِمْرَأةٌ رَاهِبَةٌ"" : مُعْتَزِلَةٌ فِي دَيْرٍ أوِ الْمُنْصَرِفَةُ إلَى أعْمَالِ البِرِّ وَالإحْسَانِ فِي مُسْتَشْفَيَاتِ الأطْفَالِ وَالعَجَزَةِ والْمَلاَجِئِ وَمُخَيَّمَاتِ اللاجِئِينَ وَالْمُهَاجِرِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1987, 'رُهْبَانٌ', 'رهبان', 'اسم فاعل', '', 'رهبان', 'رهبن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1988, 'رَوَاهِبُ', 'رواهب', 'اسم فاعل', '', 'رواهب', 'رهب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1989, 'رَاوِي', 'راوي', 'اسم فاعل', 'روي', 'راوي', 'ر', 'فا. مِنْ رَوَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:رُوَاةٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ رَوَى). 1.""قَالَ الرَّاوِي"" : الْمُتَحَدِّثُ الَّذِي يَرْوِي أَخْبَاراً وَقِصَصاً وَحِكَايَاتٍ. 2. ""كَانَ رَاوِياً مِنَ الثِّقاتِ"" : نَاقِلاً الحَدِيث وَذَاكِراً لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1990, 'رهبة', 'رهبة', 'اسم فاعل', '', 'رهبة', 'رهبة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1991, 'رَاهِنٌ', 'راهن', 'اسم فاعل', 'رهن', 'راهن', 'رهن', 'فا. مِنْ رَهَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"رَاهِنٌ-رَاهِنٌ، ةٌ [ر هـ ن] (فا. مِنْ رَهَنَ). 1. ""فِي الوَقْتِ الرَّاهِنِ لاَ أمْلِكُ دِرْهَماً وَاحِداً"" : فِي الوَقْتِ الحَاضِرِ. 2.""الظُّرُوفُ الرَّاهِنَةُ صَعْبَةٌ"" : الحَاضِرَةُ. 3. ""الحَالَةُ الرَّاهِنَةُ لِلْمَرِيضِ لاَ تَدْعُو لِلْقَلَقِ"" : وَضْعِيَّتُهُ الصِّحِّيَّةُ الَّتي عَلَيْها حالِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1992, 'رواهن', 'رواهن', 'اسم فاعل', '', 'رواهن', 'رهن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1993, 'رهان', 'رهان', 'اسم فاعل', '', 'رهان', 'رهن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1994, 'رهنة', 'رهنة', 'اسم فاعل', '', 'رهنة', 'رهنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1995, 'مُرَوِّجٌ', 'مروج', 'اسم فاعل', 'روج', 'مروج', 'مرج', 'فَا. مِنْ رَوَّجَ.', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"ج: ـون، ـات. (فَا. مِنْ رَوَّجَ). 1.""مُرَوِّجُ الْبَضَائِعِ فِي الأَسْوَاقِ"" : مَنْ يُرَوِّجُ لَهَا. 2.""مُرَوِّجُ الشَّائِعَاتِ"" : مَنْ يُشِيعُهَا بَيْنَ النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1996, 'مُرَوِّحٌ', 'مروح', 'اسم فاعل', 'روح', 'مروح', 'مرح', 'فَا. مِنْ رَوَّحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُرَوِّحٌ-مُرَوِّحٌ، ةٌ [ر و ح] (فَا. مِنْ رَوَّحَ). ""مُرَوِّحٌ لِلنَّفْسِ"": مَنْ يَجْعَلُهَا فِي رَاحَةٍ، مُرَفِّهٌ، مُسَلٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1997, 'مُرَوِّضٌ', 'مروض', 'اسم فاعل', 'روض', 'مروض', 'مرض', 'فَا. مِنْ رَوَّضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُرَوِّضٌ-مُرَوِّضٌ [ر و ض] (فَا. مِنْ رَوَّضَ). ""مُرَوِّضُ الْحَيَوَانَاتِ الْمُفْتَرِسَةِ"" : مَنْ يَسُوسُهَا وَيُدَرِّبُهَا وَيُعَوِّدُهَا عَادَاتٍ وَحَرَكَاتٍ مُعَيَّنَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1998, 'مُرَوِّعٌ', 'مروع', 'اسم فاعل', 'روع', 'مروع', 'مرع', 'فا. مِنْ رَوَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '".(فا. مِنْ رَوَّعَ). ""رَجُلٌ مُرَوِّعٌ"" : مُفْزِعٌ، مُرْعِبٌ، مُخِيفٌ. ""مَشْهَدٌ مُرَوِّعٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(1999, 'رُوَاةٌ', 'رواة', 'اسم فاعل', '', 'رواة', 'رة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2000, 'مُزَاحِمٌ', 'مزاحم', 'اسم فاعل', 'زحم', 'مزاحم', 'مزحم', 'فَا. مِنْ زَاحَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ زَاحَمَ). ""مُزَاحِمٌ لَهُ"" : مُنَافِسٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2001, 'زائِدٌ', 'زائد', 'اسم فاعل', 'زيد', 'زاءد', 'زد', 'فا. مِنْ زادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":زَوائِدُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ زادَ). 1.""زائِدٌ على الُّلزومِ"" : فَوْقَ ما يَنْبَغِي أَنْ يَكونَ. ""يتَحَدَّثُ بِمَرَحٍ زائِدٍ"" ""يَنْظُرونَ إلَى الْمالِ الزّائِدِ عَنِ الْحاجَةِ أَنَّهُ بَلاءٌ في بَلاءِ"". 2.""أَجْرَى عَمَلِيَّةً جِراحِيَّةً لاسْتِئْصالِ الزَّائِدَةِ الدُّودِيَّةِ"" : قَناةٌ صَغيرَةٌ مَسْدودَةٌ في ذَيْلِ الْمِعَى الأَعْوَرِ، تُحْدِثُ الْتِهاباً خَطيراً إِذا لَمْ تُسْتَأْصَلْ. 3.""زائِدَةُ الكَبِدِ"" : جُزْءٌ مِنْها صَغيرٌ إلَى جانِبِها، مُتَنَحٍّ عَنْها. 4.""عَلامَةُ زائِدٍ في الحِسابِ تُكْتَبُ هَكَذا (+)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2002, 'زَوائِدُ', 'زوائد', 'اسم فاعل', '', 'زواءد', 'زد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2003, 'مُزَارِعٌ', 'مزارع', 'اسم فاعل', 'زرع', 'مزارع', 'مزرع', 'فَا. مِنْ زَارَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ زَارَعَ). ""مُزَارِعُ أَرْضٍ"" : مَنْ يَقُومُ بِزِرَاعَةِ أَرْضٍ عَلَى أَنْ يَقْسِمَ النَّاتِجَ حَسَبَ اتِّفَاقٍ مُسْبَقٍ مَعَ مَالِكِ الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2004, 'زائِغٌ', 'زائغ', 'اسم فاعل', 'زيغ', 'زاءغ', 'زغ', 'فا. مِنْ زاغَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِنْ زاغَ). 1.""ما يَزالُ شابّاً زائِغاً"" : تائِهاً، حائِراً، غَيْرَ مُهْتَدٍ لِلطَّريقِ الصَّحيحِ. 2.""نَظرٌ زَائِغٌ"" : شَارِدٌ. ""في دُروبِ الْجوعِ أَلْهَثُ زائِغَ النَّظَرِ"". (بدر شاكر السياب)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2005, 'زوائغ', 'زوائغ', 'اسم فاعل', '', 'زواءغ', 'زغ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2006, 'زائِفٌ', 'زائف', 'اسم فاعل', 'زيف', 'زاءف', 'زف', 'فا. مِنْ زافَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":زُيَّفٌ:زُيُوفٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ زافَ). 1.""أَعْطاهُ دِرْهَماً زائِفاً"" : أَي غَيْرَ صالِحٍ للتَّداوُلِ. 2.""يُظْهِرُ تَواضُعاً زائِفاً"" : أَيْ غَيْرَ أَصيلٍ، مُتَكَلِّفاً. ""الشَّاعِرُ الزَّائِفُ كَالدِّينارِ الزَّائِفِ"". (م. ص. الرافعي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2007, 'زُيَّفٌ', 'زيف', 'اسم فاعل', '', 'زيف', 'زف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
