INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2010, 'زائِلٌ', 'زائل', 'اسم فاعل', 'زول', 'زاءل', 'زل', 'فا. مِنْ زالَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":زَوائِلُ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ زالَ). 1.""لاَ تَعْبَأْ بِما حَدَثَ لَكَ، إِنَّهُ أَمْرٌ زَائِلٌ"" : عابِرٌ. 2.""كُلُّ شَيْءٍ زائِلٌ"" : فانٍ. ""هِيَ أُمورُ الدُّنْيا زائِلَةٌ"" ""ثَرْوَةٌ زائِلَةٌ"". 3.""زائِلُ الظِّلِّ"" : وَقْتُ الظَّهيرَةِ، أَيِ انْتصافُ النَّهارِ. 4.""لَيْلٌ زائِلُ النُّجومِ"" : طَويلٌ."', '');
