INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2012, 'مُزَامِنٌ', 'مزامن', 'اسم فاعل', 'زمن', 'مزامن', 'مزمن', 'فَا. مِنْ زَامَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُزَامِنٌ-مُزَامِنٌ، ةٌ [ز م ن] (فَا. مِنْ زَامَنَ). ""مُزَامِنٌ لَهُ"" : مُعَاصِرٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2013, 'مُزَايِدٌ', 'مزايد', 'اسم فاعل', 'زيد', 'مزايد', 'مزد', 'فَا. مِنْ زَايَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ زَايَدَ). 1.""ظَلَّ مُزَايِدًا فِي الْمَزَادِ"" : مَنْ يُزَايِدُ فِي الْمَزَادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2014, 'زاجِرٌ', 'زاجر', 'اسم فاعل', 'زجر', 'زاجر', 'زجر', 'فا. مِنْ زَجَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"زاجِرٌ-زاجِرٌ، ةٌ[ز ج ر] (فا. مِنْ زَجَرَ). 1.""اِتَّخَذَ تَدْبيراً زاجِراً في حَقِّهِ"" : رادِعاً، أَيْ لِيوقِفَه عِنْدَ حَدِّهِ. 2.""زاجِرُ الإِنْسانِ"" : ضَميرُهُ، أَي الحاجِزُ الَّذِي يَقِفُ بيْنَهُ وَبَيْنَ أَعْمالِ الشَّرِّ."', '');
