INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2058, 'مُزَوِّدٌ', 'مزود', 'اسم فاعل', 'زود', 'مزود', 'مزد', 'فَا. مِنْ زَوَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ زَوَّدَ). 1.""مُزَوِّدُ الْمُسَا فِرِينَ"" : مَنْ يَمُدُّهُمْ بِالزَّادِ. 2.""مُزَوِّدُ الْمَتَاجِرِ الصَّغِيرَةِ"" : مَنْ يَمُدُّهُمْ بِالبَضَائِعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2059, 'مُزَوِّرٌ', 'مزور', 'اسم فاعل', 'زور', 'مزور', 'مزر', 'فَا. مِنْ زَوَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ زَوَّرَ). 1.""مُزَوِّرُ النُّقُودِ"" : مُزَيِّفُهَا. ""مُزَوِّرٌ الْوَثَائِقِ"". 2.""مُزَوِّرُ الأَخْبَارِ"" : الكَاذِبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2060, 'مُزَوِّقٌ', 'مزوق', 'اسم فاعل', 'زوق', 'مزوق', 'مزق', 'فَا. مِنْ زَوَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ زَوَّقَ). ""مُزَوِّقُ الكِتَابِ"" : مُزَخْرِفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2061, 'مُزَيِّفٌ', 'مزيف', 'اسم فاعل', 'زيف', 'مزيف', 'مزف', 'فَا. مِنْ زَيَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ زَيَّفَ). ""مُزَيِّفُ النُّقُودِ"" : مُزَوِّرُهَا. ""مُزَيِّفٌ الْحَقَائِقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2062, 'مُزَيِّنٌ', 'مزين', 'اسم فاعل', 'زين', 'مزين', 'مزن', 'فَا. مِنْ زَيَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ زَيَّنَ). 1.""مُزَيِّنُ القَاعَةِ"" : مُزَخْرِفُهَا، مُحَسِّنُهَا. 2.""ذَهَبَ عِنْدَ مُزَيِّنِ الْحَيِّ لِيَحْلِقَ شَعْرَهُ"" : الْحَلاَّقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2063, 'سَائِبٌ', 'سائب', 'اسم فاعل', 'سيب', 'ساءب', 'سب', 'فا. من سَابَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":سَوَائِبُ"', '', '', '', '', '', '', '', '', '"(فا. من سَابَ). 1.""صَارَ وَلَداً سَائِباً"" : تَائِهاً، ضَالاًّ. 2. ""لاَ أمْلِكُ مَالاً سَائِباً لِتَفْعَلَ بِهِ مَا تُرِيدُ"" : مُهْمَلاً، فَائِضاً، الْمَال الَّذِي لاَ حِفاظَ عَلَيْهِ. ""الْمَالُ السَّائِبُ يُعَلِّمُ النَّاسَ الحَرَامَ"" : أيْ إذَا كَانَ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2064, 'سَوَائِبُ', 'سوائب', 'اسم فاعل', '', 'سواءب', 'سب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2065, 'سَائِحٌ', 'سائح', 'اسم فاعل', 'سيح', 'ساءح', 'سح', 'فا. من سَاحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":سُيَّاحٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من سَاحَ). 1. ""ذَهَبَ سَائِحاً عَلَى وَجْهِ الأرْضِ"" : ذَهَبَ سَائِراً كَالتَّائِهِ. 2. ""اِلْتَقَى بِسَائِحٍ أَجْنَبِيِّ"" : الزَّائِرُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2066, 'سُيَّاحٌ', 'سياح', 'اسم فاعل', '', 'سياح', 'سح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
