INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2068, 'سَائِدٌ', 'سائد', 'اسم فاعل', 'سود', 'ساءد', 'سد', 'فا. من سَادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":سَادَةٌ:جسَادَاتٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من سَادَ). 1. ""كَانَ حَاكِماً سَائِداً عَلَى كُلِّ الأقَالِيمِ"" : مُهَيْمِناً، سَيِّداً مُسَيْطِراً. 2. ""كَانَ رَأْيُهُ هُوَ السَّائِدُ"" : الطَّاغِي، البَارِزُ، الغَالِبُ، الشَّائِعُ، الْمُسَيْطِرُ. ""اللَّوْنُ الأَزْرَقُ هُوَ السَّائِدُ فِي اللَّوْحَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2069, 'سَادَةٌ', 'سادة', 'اسم فاعل', '', 'سادة', 'سدة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
