INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2074, 'سَارٌّ', 'سار', 'اسم فاعل', 'سرر', 'سار', 'سر', 'فا. من سَارَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":(مؤسَارَّةٌ)"', '', '', '', '', '', '', '', '', '"(فا. من سَارَّ). ""جَاءهُ بِخَبَرٍ سَارٍّ"" : مُفْرِحٍ. ""غَمَرَتِ العَائِلَةَ أخْبَارٌ سَارَّةٌ""."', '');
