INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2078, 'سَائِسٌ', 'سائس', 'اسم فاعل', 'سوس', 'ساءس', 'سس', 'فا. من سَاسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":ساسَةٌ:سُوَّاسٌ"', '', '', '', '', '', '', '', '', '"سَائِسٌ - ج: ساسَةٌ، سُوَّاسٌ. [س و س]. (فا. من سَاسَ). 1. ""سَائِسٌ لِلْخَيْلِ"" : الَّذِي يُعْنَى بِهَا وَيُدَبِّرُ أُمُورَهَا. 2.""سَائِسٌ لِلأُمُورِ عَنْ تَجْرِبَةٍ وَحُنْكَةٍ"" : قَائِمٌ بِهَا كَمَا يَجِبُ وَعَنْ دِرَايَةٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2079, 'ساسَةٌ', 'ساسة', 'اسم فاعل', '', 'ساسة', 'سسة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2080, 'سُوَّاسٌ', 'سواس', 'اسم فاعل', '', 'سواس', 'سس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2081, 'مُسَاعِدٌ', 'مساعد', 'اسم فاعل', 'سعد', 'مساعد', 'مسعد', 'فَا. مِنْ سَاعَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ سَاعَدَ). 1.""مُسَاعِدُ الرَّئِيسِ"" : مُعَاوِنُهُ. ""مُسَاعِدُ الْمُدِيرِ"". 2.""أُسْتَاذٌ مُسَاعِدٌ"" : رُتْبَةٌ جَامِعِيَّةٌ لِفِئَةٍ مِنْ أَسَاتِذَةِ الجَامِعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2082, 'مُسَاعِفٌ', 'مساعف', 'اسم فاعل', 'سعف', 'مساعف', 'مسعف', 'فَا. مِنْ سَاعَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ سَاعَفَ). 1.""مُسَاعِفُ الْفُقَرَاءِ وَالْمُحْتَاجِينَ وَالْمَرْض"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2083, 'سَائِغٌ', 'سائغ', 'اسم فاعل', 'سوغ', 'ساءغ', 'سغ', 'فا. من سَاغَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"سَائِغٌ-سَائِغٌ، ةٌ [س و غ] (فا. من سَاغَ). 1. ""أمْرٌ سَائِغٌ"" : جَائِزٌ، أيْ يَجُوزُ فِعْلُهُ. ""أَمْرٌ غَيْرُ سَائِغٍ لَكَ القِيَامُ بِهِ"". 2.""وَجَدَ الطَّعَامَ سَائِغاً"" : سَهْلَ الأكْلِ وَالهَضْمِ. فاطر آية 12 هَذَا عَذْبٌ فُرَاتٌ سَائِغٌ شَرَابُهُ (قرآن) ""أرْوَتْهُ لَبَناً سَائِغاً"". (ابن طفيل). 3.""جَعَلَهُ لُقْمَةً سَائِغَةً"" : سَهْلَةً، أيْ لَمْ يُتْعِبْهُ أمْرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2084, 'سوائغ', 'سوائغ', 'اسم فاعل', '', 'سواءغ', 'سغ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2085, 'مُسَافِرٌ', 'مسافر', 'اسم فاعل', 'سفر', 'مسافر', 'مسفر', 'فَا. مِنْ سَافَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ سَافَرَ). ""يَنْتَظِرُ الْمُسَافِرُ القِطَارَ"" : مَنْ يَرْتَحِلُ مِنْ مَكَانٍ إِلَى آخَرَ. ""مَحَطَّةُ الْمُسَافِرِينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2086, 'سَائِقٌ', 'سائق', 'اسم فاعل', 'سوق', 'ساءق', 'سق', 'فا. من سَاقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":سُوَّاقٌ:سَاقَةٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من سَاقَ). 1.""سَائِقُ الْمَاشِيَةِ"" : الَّذِي يَحُثُّهَا مِنَ الخَلْفِ علَى السَّيْرِ. 2.""سَائِقُ سَيَّارَةٍ"" : مَنْ يَقُودُ مِقْوَدَهَا. ""سَائِقُ الحَافِلَةِ"" ""سَائِقُ القِطَارِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2087, 'سُوَّاقٌ', 'سواق', 'اسم فاعل', '', 'سواق', 'سق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2088, 'سَاقَةٌ', 'ساقة', 'اسم فاعل', '', 'ساقة', 'سقة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
