INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2090, 'سَائِلٌ', 'سائل', 'اسم فاعل', 'سأل', 'ساءل', 'سل', 'فا. من سَألَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":سُؤَّالٌ:سَألَةٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من سَألَ). 1.""جَاءَ سَائِلاً عَنْ شُؤُونِ البَيْتِ"" : مُسْتَفْسِراً. ""أنَا السَّائِلُ دَائِماً وَهِيَ الْمُجِيبُ دَائِماً"" َمَا الْمَسْؤُولُ عَنْهَا بِأعْلَم مِن السَّائِلِ (جُزْءٌ مِنْ حَدِيثِ). 2.الضحى آية 10وَأمَّا السَّائِلَ فلاَ تَنْهَرْ (قرآن) : الفَقِيرَ، الْمُعْدِمَ، الْمُسْتَعْطِيَ."', '');
