INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2094, 'مُسَالِمٌ', 'مسالم', 'اسم فاعل', 'سلم', 'مسالم', 'مسلم', 'فَا. مِنْ سَالَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ سَالَمَ). ""رَجُلٌ مُسَالِمٌ"" : مَنْ يُسَالِمُ النَّاسَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2095, 'مُسَامِرٌ', 'مسامر', 'اسم فاعل', 'سمر', 'مسامر', 'مسمر', 'فَا. مِنْ سَامَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ سَامَرَ). ""مُسَامِرُهُ فِي لَيَالِي الشِّتَاءِ "" : مُحَدِّثُهُ لَيْلاً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2096, 'مُسَاهِمٌ', 'مساهم', 'اسم فاعل', 'سهم', 'مساهم', 'مسهم', 'فَا. مِنْ سَاهَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ سَاهَمَ). 1.""مُسَاهِمٌ فِي العَمَلِ بِجِدٍّ"" : مُشَارِكٌ فِيهِ. 2.""مِنْ بَيْنِ الْمُسَاهِمِينَ فِي الشَّرِكَةِ"" : مِنْ بَيْنِ أَصْحَابِ الأَسْهُمِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2097, 'مُسَاوِي', 'مساوي', 'اسم فاعل', 'سوي', 'مساوي', 'مس', 'فَا. مِنْ سَاوَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ سَاوَى). ""خَطٌّ مُسَاوٍ لِلْخَطِّ الآخَرِ"" : مُعَادِلٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2098, 'مُسَبِّبٌ', 'مسبب', 'اسم فاعل', 'سبب', 'مسبب', 'مسب', 'فَا. مِنْ سَبَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ سَبَّبَ). 1.""مُسَبِّبُ مَا حَدَثَ"" : الَّذِي كَانَ السَّبَبَ. 2.""تَاجِرٌ مُسَبِّبٌ"" : أَيْ يُعِيدُ بَيْعَ مَوَادَّ قَدِيمَةٍ. 3.""حَاصَرُوا مُسَبِّبَاتِ انْتِشَارِ الأَمْرَاضِ"" : العَوَامِلُ الَّتِي كَانَتْ سَبَباً فِي انْتِشَارِهَا. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2099, 'سَابِحٌ', 'سابح', 'اسم فاعل', 'سبح', 'سابح', 'سبح', 'فا. من سَبَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":سُبَّاحٌ:سُبَحَاءُ:سَوَابِحُ', '', '', '', '', '', '', '', '', '"(فا. من سَبَحَ). 1.""مَضَى سَابِحاً فِي البَحْرِ"" : عَائِماً مُتَقَدِّماً بَيْنَ أمْوَاجِهِ. 2.""فَرَسٌ سَابِحٌ"" : سَرِيعٌ. 3.""ظَلَّ سَابِحاً فِي أفْكَارِهِ"" : غَارِقاً مُتَأمِّلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2100, 'سُبَّاحٌ', 'سباح', 'اسم فاعل', '', 'سباح', 'سبح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
