INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2115, 'سَاجِي', 'ساجي', 'اسم فاعل', 'سجو', 'ساجي', 'سج', 'فا. من سَجَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"سَاجٍ-سَاجٍ، السَّاجِي، ةٌ [س ج و] (فا. من سَجَى). 1.""إنَّ اللَّيْلَ سَاجٍ"" : هادِئٌ، سَاكِنٌ. ""إنَّ البَحْرَ سَاجٍ"" ""لَيْ"', '');
