INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2205, 'سَالِفٌ', 'سالف', 'اسم فاعل', 'سلف', 'سالف', 'سلف', 'فا. من سَلَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":سَلَفٌ:سُلاَّفٌ:سَوَالِفُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"سَالِفٌ، ةٌ - ج: سَلَفٌ، سُلاَّفٌ، سَوَالِفُ. [س ل ف]. (فا. من سَلَفَ). 1.""فِي الزَّمَنِ السَّالِفِ"" : الْمَاضِي، أيْ مَا مَضَى مِنَ الأيَّامِ وَالأزْمَانِ.   ""حَدَثَ ذَلِكَ فِي سَالِفِ الأيَّـامِ"" ""فِي سَالِفِ الأزْمَانِ"" ""فِي الأزْمِنَةِ السَّالِفَةِ"". 2.""سَالِفاً كُنْتُ أزُورُهُ"" : فِيمَا سَبَقَ، آنِفاً، مِنْ قَبْلُ. 3.""سَالِفَةُ شَعْرٍ"" : خُصْلَةُ الشَّعْرِ الْمُرْسَلَةُ عَلَى الخَدِّ. "', '');
