INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2219, 'سَامِعٌ', 'سامع', 'اسم فاعل', 'سمع', 'سامع', 'سمع', 'فا. من سَمِعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":ٌ:سُمَّاعٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من سَمِعَ). 1.""هَلْ أنْتَ سَامِعٌ مَا يَقُولُ"" : مُدْرِكٌ لِصَوْتِهِ وَقَوْلِهِ. ""أحْسَنُ الكَلاَمِ مَا صَدَقَ فِيهِ قَائِلُهُ وانْتَفَعَ بِهِ سَامِعُهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2220, 'سَامِدٌ', 'سامد', 'اسم فاعل', 'سمد', 'سامد', 'سمد', 'فا. من سَمَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من سَمَدَ). 1.""وَلَدٌ سَامِدٌ"" : غَبِيٌّ أوْ مُتَكَبِّرٌ. 2. ""وَجَدَهُ سَامِداً"" : سَاهِياً.النجم آية 60 أفَمِنْ هَذَا"', '');
