INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2251, 'مُسَهِّلٌ', 'مسهل', 'اسم فاعل', 'سهل', 'مسهل', 'مسهل', 'فَا. مِن سَهَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُسَهِّلٌ-مُسَهِّلٌ، ةٌ [س هـ ل] (فَا. مِن سَهَّلَ). ""دَوَاءٌ مُسَهِّلٌ"": دَوَاءٌ لَهُ مَفْعُولُ إِحْدَاثِ الإسْهَالِ، مُطْلِقٌ لِلْبَطْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2252, 'سَاهِمٌ', 'ساهم', 'اسم فاعل', 'سهم', 'ساهم', 'سهم', 'فا. من سَهَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من سَهَمَ). 1. ""وَجَدَهُ سَاهِماً"" : ضَامِراً مَهْمُوماً، لَوْنُهُ مُتَغَيِّرٌ. ""يَبْدُو سَاهِماً وَضَائِعاً، لاَ أع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2253, 'سواهم', 'سواهم', 'اسم فاعل', '', 'سواهم', 'سهم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2254, 'سهام', 'سهام', 'اسم فاعل', '', 'سهام', 'سهم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
