INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2256, 'مُسَوِّغٌ', 'مسوغ', 'اسم فاعل', 'سوغ', 'مسوغ', 'مسغ', 'فا. مِن سَوَّغَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُسَوِّغٌ-مُسَوِّغٌ، ةٌ [س و غ] (فا. مِن سَوَّغَ). 1.""أَتَى بِمُسَوِّغٍ"" : بِمُبَرِّرٍ. 2.""مُسَوِّغٌ قَانُونِيٌّ"" : مُوجِبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2257, 'مُسَوِّفٌ', 'مسوف', 'اسم فاعل', 'سوف', 'مسوف', 'مسف', 'فَا. مِن سَوَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن سَوَّفَ). ""رَجُلٌ مُسَوِّفٌ"" : أَيْ مَنْ يُمَاطِلُ فِي إنْجَازِ عَمَلٍ مَّا يَقُولُ: سَوْفَ أَفْعَلُ كَذَا وَكَذَا وَلاَ يَفْعَلُ لاَ هَذَا وَلاذَاكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2258, 'مُسَيِّرٌ', 'مسير', 'اسم فاعل', 'سير', 'مسير', 'مسر', 'فَا. مِن سَيَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن سَيَّرَ). ""مُسَيِّرُ الفَرِيقِ"" : مَنْ يُسَيِّرُهُ وَيُرْشِدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2259, 'شوائط', 'شوائط', 'اسم فاعل', '', 'شواءط', 'شط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2260, 'مُسَيِّلٌ', 'مسيل', 'اسم فاعل', 'سيل', 'مسيل', 'مسل', 'فا. مِن سَيَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُسَيِّلٌ-مُسَيِّلٌ، ةٌ [س ي ل] (فا. مِن سَيَّلَ). ""غَازٌ مُسَيِّلٌ للدُّمُوعِ"" : غَازٌ يُسَيِّلُ الدُّمُوعَ، أَيْ يَجْعَلُهَا تَنْهَمِرُ وَتَتَدَفَّقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2261, 'شَائِبٌ', 'شائب', 'اسم فاعل', 'شيب', 'شاءب', 'شب', 'فا. من شابَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":شُيَّبٌ"', '', '', '', '', '', '', '', '', '"(فا. من شابَ). 1.""رَأْسُهُ شَائِبٌ"" : صَارَ شَعْرُ رَأْسِهِ أبْيَضَ. 2. ""شَائِبَةُ الرَّأْسِ"": مُبْيَضَّةُ شَعْرِ الرَّأْسِ. 3. ""لاَ تَشُوبُها شَائِبَةٌ"" : صَافِيَةٌ، أيْ غَيْرُ مُخْتَلِطَةٍ بِشَيْءٍ مِنْ غَيْرِ جِنْسِهَا. ""إِنَّ مَاضِيكَ أبْيَضُ نَاصِعُ البَيَاضِ لاَ تَشُوبُهُ سِوَى شَائِبَةٍ سَوْداءَ واحِدَةٍ"". (إميل حبيبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2262, 'شُيَّبٌ', 'شيب', 'اسم فاعل', '', 'شيب', 'شب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2263, 'شوائب', 'شوائب', 'اسم فاعل', '', 'شواءب', 'شب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2264, 'مُشَابِهٌ', 'مشابه', 'اسم فاعل', 'شبه', 'مشابه', 'مشبه', 'فَا. مِن شَابَهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن شَابَهَ). ""مُشَابِهٌ لَهُ فِي سُلُوكِهِ وَخُلُقِهِ"" : مُمَاثِلٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2265, 'مُشَاجِرٌ', 'مشاجر', 'اسم فاعل', 'شجر', 'مشاجر', 'مشجر', 'فا. من شَاجَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من شَاجَرَ). ""رَجُلٌ مُشَاجِرٌ"" : مَنْ يَتَشَاجَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2266, 'مُشَاحِنٌ', 'مشاحن', 'اسم فاعل', 'شحن', 'مشاحن', 'مشحن', 'فا. مِنْ شَاحَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُشَاحِنٌ-مُشَاحِنٌ، ةٌ [ ش ح ن ] (فا. مِنْ شَاحَنَ). ""عَدُوٌّ مُشَاحِنٌ"" : حَقُودٌ، شَدِيدُ الْحِقْدِ وَالعَدَاوَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2267, 'مُشَارِكٌ', 'مشارك', 'اسم فاعل', 'شرك', 'مشارك', 'مشرك', 'فا. من شَارَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ج:"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من شَارَكَ). 1. ""مُشَارِكٌ فِي العَمَلِ"" : مُسَاهِمٌ فِيهِ. 2. ""مُشَارِكٌ فِي الأَرْبَاحِ"" : أَيْ مَنْ لَهُ نَصِيبٌ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2268, 'شَائِطٌ', 'شائط', 'اسم فاعل', 'شوط', 'شاءط', 'شط', 'فا. من شاطَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَائِطٌ-شَائِطٌ، ةٌ [ش و ط] (فا. من شاطَ). 1.""أكَلَ طَعَاماً شَائِطاً"" : مَا تَبَقَّى مِنَ الطَّعَامِ. 2.""صَارَ الطَّعَامُ شَائِطاً"" : مُحْتَرِقاً. ""أَخْرَجَ الخَبَّازُ الخُبْزَ شَائِطاً مِنَ الفُرْنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2269, 'شوائم', 'شوائم', 'اسم فاعل', '', 'شواءم', 'شم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2270, 'شَائِعٌ', 'شائع', 'اسم فاعل', 'شيع', 'شاءع', 'شع', 'فا. من شَاعَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَائِعٌ-شَائِعٌ، ةٌ [ش ي ع] (فا. من شَاعَ). 1. ""خَبَرٌ شَائعٌ بَيْنَ النَّاسِ"" : ذَائِعٌ، مُنْتَشِرٌ. ""حَدِيثٌ شَائِعٌ"" ""أَحَادِيثُ شَائِعةٌ"". 2.""مِلْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2271, 'شوانع', 'شوانع', 'اسم فاعل', '', 'شوانع', 'شنع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2272, 'مُشَاغِبٌ', 'مشاغب', 'اسم فاعل', 'شغب', 'مشاغب', 'مشغب', 'فَا. مِن شَاغَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ج:"', '', '', '', '', '', '', '', '', '"مُشَاغِبٌ-مُشَاغِبٌ، ةٌ [ش غ ب] (فَا. مِن شَاغَبَ). ""وَلَدٌ مُشَاغِبٌ"" : مُشَاكِسٌ، مُثِيرٌ لِلشَّغَبِ وَالْمُشَاكَسَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2273, 'شَائِقٌ', 'شائق', 'اسم فاعل', 'شوق', 'شاءق', 'شق', 'فا. من شَاقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ج:"', '', '', '', '', '', '', '', '', '"شَائِقٌ-شَائِقٌ، ةٌ [ش و ق] (فا. من شَاقَ). 1. ""شَائِقٌ إلَى أيَّامِ العُطَلِ"" : أَي يَحِنُّ بِشَوْقٍ إلَى...، يُحَرِّكُهُ الحَنِينُ... 2.""قِصَّةٌ رَائِعَةٌ شَائِقَةٌ"" : فِيهَا كُلُّ مَا هُوَ جَمِيلٌ وَحسَنٌ وَمُشَوِّقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2274, 'شوائق', 'شوائق', 'اسم فاعل', '', 'شواءق', 'شق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2275, 'شَائِكٌ', 'شائك', 'اسم فاعل', 'شوك', 'شاءك', 'شك', 'فا. من شَاكَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَائِكٌ-شَائِكٌ، ةٌ [ش و ك] (فا. من شَاكَ). 1. ""نَبَاتٌ شَائِكٌ"": بِهِ شَوْكٌ. ""شَجَرَةٌ شَائِكَةٌ"". 2. ""أُحِيطَ البُسْتَانُ بِأسْلاَكٍ شَائِكَةٍ"" : بِأسْلاَكٍ لَهَا رُؤُوسٌ حَادَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2276, 'شوائك', 'شوائك', 'اسم فاعل', '', 'شواءك', 'شك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2277, 'مُشَاكِسٌ', 'مشاكس', 'اسم فاعل', 'شكس', 'مشاكس', 'مشكس', 'فَا. مِن شَاكَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن شَاكَسَ). ""وَلَدٌ مُشَاكِسٌ"" : مُشَاغِبٌ، أَيْ مَنْ يُحْدِثُ الشَّغَبَ وَالْمُشَاكَسَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2278, 'شَائِمٌ', 'شائم', 'اسم فاعل', 'شأم', 'شاءم', 'شم', 'فا. من شَأمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من شَأمَ). ""رَجُلٌ شَائِمٌ"" : يَحْمِلُ الشُّؤْمَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2279, 'شَوَابِكُ', 'شوابك', 'اسم فاعل', '', 'شوابك', 'شبك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2280, 'شَائِنٌ', 'شائن', 'اسم فاعل', 'شين', 'شاءن', 'شن', 'فا. من شانَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', 'Cv', '"شَائِنٌ، ةٌ - [ش ي ن]. (فا. من شانَ). 1.""قَامَ بِعَمَلٍ شَائِنٍ"" : بِعَملٍ مُخْزٍ، مُخْجِلٍ. 2.""سُلُوكٌ شَائِنٌ"": مَعِيبٌ. 3.""تَفَوَّهَ بِكلاَمٍ شَائِنٍ"" : بِكلاَمٍ جَارِحٍ، بِألْفَاظٍ، بَذِيئَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2281, 'شوائن', 'شوائن', 'اسم فاعل', '', 'شواءن', 'شن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2282, 'مُشَاهِدٌ', 'مشاهد', 'اسم فاعل', 'شهد', 'مشاهد', 'مشهد', 'فَا. مِنْ شَاهَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ شَاهَدَ). 1.""مُشَاهِدٌ لِمَا حَدَثَ"" : النَّاظِرُ، أَيْ كَانَ حَاضِراً وَنَاظِراً. 2.""مُشَاهِدُ التَّلْفَزَةِ"" : الْمُتَفَرِّجُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2283, 'مُشَاوِرٌ', 'مشاور', 'اسم فاعل', 'شور', 'مشاور', 'مشر', 'فَا. مِن شَاوَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن شَاوَرَ). ""مُشَاوِرٌ فِيمَا يُقَرِّرُهُ"" : مَنْ يَطْلُبُ رَأْيَ النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2284, 'مُشَايِعٌ', 'مشايع', 'اسم فاعل', 'شيع', 'مشايع', 'مشع', 'فَا. مِن شَايَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُشَايِعٌ-مُشَايِعٌ [ش ي ع] (فَا. مِن شَايَع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2285, 'شَابٌّ', 'شاب', 'اسم فاعل', 'شبب', 'شاب', 'شب', 'فا. من شَبَّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":شَبَابٌ:شُبَّانٌ"', '', '', '', '', '', '', '', '', '"(فا. من شَبَّ). ""مَا يَزَالُ شَابّاً فِي مُقْتَبَلِ العُمْرِ"" : يافِعاً، فَتـىً، أَي هُوَ فِي سِنِّ الشَّبَابِ."', '');
