INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2292, 'شَاتِي', 'شاتي', 'اسم فاعل', 'شتو', 'شاتي', 'شت', 'فا. من شَتَا', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَاتٍ، الشَّاتِي، ةٌ - [ش ت و]. (فا. من شَتَا). 1. ""يَوْمٌ شَاتٍ"" : مُمْطِرٌ.   ""يَوْمٌ مِنْ أَيَّامِ الشِّتَاءِ الشَّاتِيَةِ""   ""سَمَاءٌ شَاتِيَةٌ"". 2. ""طَقْسٌ شَاتٍ"" : طَقْسٌ بَارِدٌ مُمْطِرٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2293, 'شواتي', 'شواتي', 'اسم فاعل', '', 'شواتي', 'شت', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2294, 'شَاجِي', 'شاجي', 'اسم فاعل', 'شجي', 'شاجي', 'شج', 'فا مِن شَجَا', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"شَاجٍ-شَاجٍ، الشَّاجِي، ةٌ [ش ج ي] (فا مِن شَجَا). ""صَوْتٌ شَاجٍ"" : مُحْزِنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2295, 'شجاة', 'شجاة', 'اسم فاعل', '', 'شجاة', 'شجة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
