INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2297, 'مُشَجِّعٌ', 'مشجع', 'اسم فاعل', 'شجع', 'مشجع', 'مشجع', 'فَا. مِن شَجَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن شَجَّعَ). 1.""مُشَجِّعُهُ عَلى الاسْتِمْرَارِ في العَمَلِ"" : الَّذِي يُلْهِبُ الْحَمَاسَ فِي الإِنْسَانِ. ""صَفَّقَ جُمْهُورٌ مِنَ الْمُشَجِّعِينَ"". 2.""عَمَلٌ مُشَجِّعٌ"" : عَمَلٌ يَبْعَثُ الْحَمَاسَ فِي النَّفْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2298, 'شَاجِنٌ', 'شاجن', 'اسم فاعل', 'شجن', 'شاجن', 'شجن', 'فا. من شَجَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":شَوَاجِنُ"', '', '', '', '', '', '', '', '', '"(فا. من شَجَنَ). 1.""رَجُلٌ شَاجِنٌ"" : حَزِينٌ. 2. ""وَادٍ شَاجِنٌ"" : كَثِيرُ الشَّجَرِ."', '');
