INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2303, 'شَاحِمٌ', 'شاحم', 'اسم فاعل', 'شحم', 'شاحم', 'شحم', 'فا. من شَحَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"شَاحِمٌ-شَاحِمٌ، ةٌ [ش ح م] (فا. من شَحَمَ). 1. ""رَجُلٌ شَاحِمٌ"": ذُو شَحْمٍ. 2. : بَائعُ الشَّحْمِ. 3. : مَنْ يُطْعِمُ النَّاسَ الشَّحْمَ."', '');
