INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2315, 'مُشَدِّدٌ', 'مشدد', 'اسم فاعل', 'شدد', 'مشدد', 'مشد', 'فَا. مِن شَدَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُشَدِّدٌ، ةٌ - [ش د د]. (فَا. مِن شَدَّدَ). ""ظُرُوفٌ مُشَدِّدَةٌ"": ظُرُوفٌ أَدَّتْ إِلَى تَشْدِيدِ العُقُوبَةِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2316, 'مُشَذِّبٌ', 'مشذب', 'اسم فاعل', 'شذب', 'مشذب', 'مشذب', 'فَا. مِن شَذَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُشَذِّبٌ-مُشَذِّبٌ [ش ذ ب] (فَا. مِن شَذَّبَ). ""مُشَذِّبُ الشَّجَرِ"" : مَنْ يُهَذِّبُهَا، مَنْ يُزِيلُ أَوْرَاقَهَا وَأَغْصَانَهَا الذَّابِلَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2317, 'شَارِبٌ', 'شارب', 'اسم فاعل', 'شرب', 'شارب', 'شرب', 'فا. من شَرِبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":شُرَّابٌ:شَوَارِبُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من شَرِبَ). 1. ""شارِبُ الماءِ"" : جارِعُهُ.الواقعة آية 55فَشَارِبونَ عَلَيْهِ مِنَ الحَمِيمِ، فَشَارِبونَ شُرْبَ الهيمِ . (قرآن). 2. ""شَارِبُ الرَّجُلِ"" : مَا يَنْبُتُ عَلَى شَفَتِهِ العُلْيَا. ""شَوَارِبُ الرَّجُلِ"" : الجَمْعُ هُنَا بِاعْتِبَارِ أَطْرَافِهِ وَأَجْزَائِهِ."', '');
