INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2335, 'شَارِعٌ', 'شارع', 'اسم فاعل', 'شرع', 'شارع', 'شرع', 'فا. من شَرَع', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":شُرَّعٌ"', '', '', '', '', '', '', '', '', '"(فا. من شَرَع). 1.""هَذَا مَا سَنَّهُ الشَّارِعُ حَسَبَ أُصُولِ العَقِيدَةِ"" : مَنْ يَضَعُ القَوَانِينَ وَيُشَرِّعُهَا. 2.""كَانَ أوَّلَ شَارِعٍ فِي العَمَلِ"" : أوَّلَ بادِئٍ فِيهِ. 3.""رُمْحُ شارِعٌ"" : مُسَدَّدٌ، مُصَوَّبٌ."', '');
