INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2363, 'شَاغِبٌ', 'شاغب', 'اسم فاعل', 'شغب', 'شاغب', 'شغب', 'فا. من شَغَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"شَاغِبٌ-شَاغِبٌ [ش غ ب] (فا. من شَغَبَ). ""رَجُلٌ شاغِبٌ"": مُثير لِلفِتَنِ والفَوْضَى. ""الْحَقُّ مُعْتَرَفٌ بِهِ وَإِنْ شَغَبَ شاغِبٌ"". (التوحيدي)."', '');
