INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2377, 'شَافِي', 'شافي', 'اسم فاعل', 'شفي', 'شافي', 'شف', 'فا. من شَفَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"شَافٍ-شَافٍ، الشَّافِي، ةٌ [ش ف ي] (فا. من شَفَى). 1.""تَنَاوَلَ دَوَاءً شَافِياً"" : نَاجِعاً. 2. ""إنَّهُ الجَوَابُ الشَّافِي لِسُؤَالِهِ"": الحَاسِمُ، القَاطِعُ. ""لَمْ يَتَلَقَّ مِنْهُ أجْوِبَةً شَافِيَةً""."', '');
