INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2380, 'شَاقٌّ', 'شاق', 'اسم فاعل', 'شقق', 'شاق', 'شق', 'فا. من شَقَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"شَاقٌّ-شَاقٌّ، ةٌ [ش ق ق] (فا. من شَقَّ). ""قَامَ بِعَمَلٍ شَاقٍّ"": مُتْعِبٍ، مُرْهِقٍ. ""مُهِمَّةٌ شَاقَّةٌ"" ""حُكِمَ عَلَيْهِ بِالأَشْغَالِ الشَّاقَّةِ""."', '');
