INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2388, 'شَاكِلٌ', 'شاكل', 'اسم فاعل', 'شكل', 'شاكل', 'شكل', 'فا. من شَكَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":شَوَاكِلُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من شَكَلَ). 1.""فِيهِ شَاكِلٌ مِنْ أبِيهِ"" : فِيهِ شَبَهُ أبِيهِ، مُشَابَهَةٌ، مُمَاثَلَةٌ. 2.""عَلَى شَاكِلَةٍ"" : عَلَى طَبِيعَةٍ، عَلَىسجِيَّةٍ، عَلَى هَيْئَةٍ.الإسراء آية 84قُلْ كُلٌّ يَعْمَلُ عَلَى شَاكِلَتِهِ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2389, 'شَامِخٌ', 'شامخ', 'اسم فاعل', 'شمخ', 'شامخ', 'شمخ', 'فا. من شَمَخَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":شُمَّخٌ:شَوَامِخُ"', '', '', '', '', '', '', '', '', '"(فا. من شَمَخَ). 1.""جَبَلٌ شَامِخٌ"" : عَالٍ، مُرْتَفِعٌ.المرسلات آية 27 وَجَعلْنَا فِيهَا رَوَاسِيَ شَامِخَاتٍ . (قرآن). 2.""رَجُلٌ شَامِخٌ"": مُتَكَبِّرٌ. ""شَامِخُ الأنْفِ"" ""شَامِخَةُ الأنْفِ"". 3.""نَسَبٌ شَامِخٌ"" : شَرِيفٌ، رَفِيعٌ، عَرِيقٌ."', '');
