INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2392, 'شَاكِي', 'شاكي', 'اسم فاعل', 'شكو', 'شاكي', 'شك', 'فا. مِنْ شَكى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"شَاكٍ-شَاكٍ، الشَّاكِي، ةٌ [ش ك و] (فا. مِنْ شَكى). 1.""جَاءهُ شَاكِياً بَاكِياً"" : جَاءهُ يَشْتَكِي، أيْ بَادِياً شَكْوَاهُ. 2.""أرَاهُ طِفْلاً شَاكِياً"" : مَنْ يَمْـرَضُ أقَـلَّ مَـرَضٍ وأهْوَنَهُ. 3. ""شَاكِي السِّلاحِ"" : تامُّ السِّلاحِ، كامِلُ الاسْتِعدادِ."', '');
