INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2403, 'شَامِسٌ', 'شامس', 'اسم فاعل', 'شمس', 'شامس', 'شمس', 'فا. من شَمُسَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَامِسٌ-شَامِسٌ، ةٌ [ش م س] (فا. من شَمُسَ). 1.""يَوْمٌ شَامِسٌ"" : يَوْمٌ مُشْمِسٌ. 2.""لَمْ نَرَ يَوْماً شَامِساً كَهَذَا"" : حَارّاً، شَدِيدَ الحَرَارَةِ. 3.""إنَّهُ لَرَجُلٌ شَامِسٌ"" : صَعْبُ المِرَاسِ، حَادُّ الخُلُقِ."', '');
