INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2405, 'شَامِلٌ', 'شامل', 'اسم فاعل', 'شمل', 'شامل', 'شمل', 'فا. من شَمَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"شَامِلٌ-شَامِلٌ، ةٌ [ش م ل] (فا. من شَمَلَ). ""كِتَابٌ شَامِلٌ"": أيْ عَامٌّ يَضُمُّ أهَمَّ الأفْكَارِ فِي مَوْضُوعِهِ. ""حَدِيثٌ شَامِلٌ"" ""أحَادِيثُ شَامِلَةٌ""."', '');
