INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2409, 'مُشَنِّعٌ', 'مشنع', 'اسم فاعل', 'شنع', 'مشنع', 'مشنع', 'فَا. مِنْ شَنَّعَ. ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"ج: ـون، ـات. (فَا. مِنْ شَنَّعَ). 1.""عَرَفَهُ مُشَنِّعاً"" : مُشَهِّراً، فَاضِحاً. 2.""كَلاَمٌ مُشَنِّعٌ"" : مَشِينٌ، فَاضِحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2410, 'شَاهِدٌ', 'شاهد', 'اسم فاعل', 'شهد', 'شاهد', 'شهد', 'فَا. مِنْ شَهَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":شُهُودٌ:أشْهَادٌ:شُهَّدٌ:وَش', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ شَهَدَ). 1. ""جَاءَ شَاهِداً عَلى مَا حَدَثَ"" : مَنْ يُدْلِي بِشَهَادَةٍ عِنْدَ الطَّلَبِ لِيُثْبِتَ وَاقِعَةً مِنَ الوَقَائِعِ. 2. ""شَاهِدُ عِيانٍ"" : مَنْ عَايَنَ شَيْئاً بِنَفْسِهِ. 3.""عَلَى رُؤُوسِ الأشْهَادِ"" : عَلَى مَرْأىً وَمَسْمَعٍ مِنَ الجَمِيعِ. 4.""رَاقَبَ الشَّاهِدَ عِنْدَ غُرُوبِ الشَّمْسِ"" : أَيِ النَّجْمَ. 5.""صَلاةُ الشَّاهِدِ"": أيْ صَلاَةُ الْمَغْرِبِ لأنَّهَا تُقَامُ عِنْدَ طُلُوعِ الشّ"', '');
