INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2428, 'مُشَيِّعٌ', 'مشيع', 'اسم فاعل', 'شيع', 'مشيع', 'مشع', 'فَا. مِن شَيَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن شَيَّعَ). 1.""مُشَيِّعُ الأَخَبْارِ"" : مُذِيعٌ لَهَا. 2.""رَافَقَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2429, 'صَائِغٌ', 'صائغ', 'اسم فاعل', 'صوغ', 'صاءغ', 'صغ', 'فا. من صَاغَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":صَاغَةٌ:صُوَّاغٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من صَاغَ). ""صَائِغٌ مَشْهُورٌ"" : مَنْ يَصُوغُ الذَّهَبَ وَيُعَالِجُهُما وَالفِضَّةَ وَيَصْنَعُ مِنْهُمَا الْحُلِيَّ."', '');
