INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2444, 'صَائِمٌ', 'صائم', 'اسم فاعل', 'صوم', 'صاءم', 'صم', 'فا. من صَامَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":صُيَّامٌ:صُوَّمٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من صَامَ). 1.""اللَّهُمَّ إِنِّي صَائِمٌ"" : الْمُمْسِكُ عَنِ الطَّعَامِ وَالشَّرَابِ تَعَبُّداً أَيَّامَ رَمَضَانَ مِنْ مَطْلَعِ الفَجْرِ إِلَى غُرُوبِ الشَّمْسِ. 2.""صَائِمٌ عَنِ الكَلاَمِ"" : مُمْتَنِعٌ عَنِ الكَلاَمِ. 3.""سِكِّينٌ صَائِمَةٌ"" : لاَ تَقْطَعُ."', '');
