INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2457, 'صَاحِي', 'صاحي', 'اسم فاعل', 'صحو', 'صاحي', 'صح', 'فا. من صَحَا', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":صُحَاةٌ"', '', '', '', '', '', '', '', '', '"(فا. من صَحَا). 1.""يَوْمٌ صَاحٍ"" : يَوْمٌ صَحْوٌ. 2.""قَلْبُهُ صَاحٍ"" : مُعَافىً، مُسْتَيْقِظٌ. 3.""مَا يَزَالُ صَاحِياً مُسْتَيْقِظًا"". ""أَسْكَرَ النُّعَاسُ سُكَّانَ الْمَدِينَةِ وَبَقِيتُ وَحْدِي صَاحِياً"". (جبران خ. جبران)."', '');
