INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2459, 'مُصَحِّفٌ', 'مصحف', 'اسم فاعل', 'صحف', 'مصحف', 'مصحف', 'فَا. مِن صَحَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن صَحَّفَ). ""مُصَحِّفُ اللَّفْظِ"" : يَرْوِيهِ خَطَأً أَوْ يَقْرَؤُهُ مُغَايِراً لِمَا فِي النَّصِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2460, 'صَاحِبٌ', 'صاحب', 'اسم فاعل', 'صحب', 'صاحب', 'صحب', 'فا. من صَحِبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":أَصْحَابٌ:صَحْبٌ:صِحَابٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من صَحِبَ). 1. ""صَاحِبِي لَنْ يَتَخَلَّى عَنِّي"": مُلاَزِمِي، مُرَافِقِي، مُعَاشِرِي. 2.""صَاحِبُ الكِتَابِ "" : مَالِكُهُ. ""صَاحِبُ الدَّارِ"".3.""إِنَّهَا صَاحِبَتِي"" : اِمْرَأَتِي،زَوْجَتِي.الأنعام آية 101 أَنَّى يَكُونُ لَهُ وَلَدٌ وَلَمْ تَكُنْ لَهُ صَاحِبَةٌ . (قرآن). 4.""صَاحِبَةُ الأَمْرِ"" : مَالِكَتُهُ. 5.""صَاحِبُ الجَلاَلَةِ"" : الْمَلِكُ، لَقَبٌ لِلتَّشْرِيفِ وَالتَّعْظِيمِ. 6.""صَاحِبُ السُّمُوِّ الأَمِيرُ"" : الأَمِيرُ الحَاكِمُ مِنَ الأُسْرَةِ الْمَلَكِيَّةِ. 7.""صَاحِبُ الْمَعَالِي"" : الوَزِيرُ. 8."""', '');
