INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2470, 'صَاخِبٌ', 'صاخب', 'اسم فاعل', 'صخب', 'صاخب', 'صخب', 'فا. من صَخِبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من صَخِبَ). 1.""رَجُلٌ صَاخِبٌ"" : كَثِيرُ الصَّخَبِ وَالصِّيَاحِ. 2.""اِجْتِمَاعٌ صَاخِبٌ"" : سَادَتْ فِيهِ الضَّوْضَاءُ، الصُّيَاحُ، الصَّخَبُ، الْجَلَبَةُ. ""جَلْسَةٌ صَاخِبَةٌ"" ""مُظَاهَرَةٌ صَاخِبَةٌ""."', '');
