INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2494, 'صَارِخٌ', 'صارخ', 'اسم فاعل', 'صرخ', 'صارخ', 'صرخ', 'فا. من صَرَخَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من صَرَخَ). 1.""لَوْنٌ صَارِخٌ"" : بَارِزٌ. 2.""ظُلْمٌ صَارِخٌ"" : وَاضِحٌ بَيِّنٌ لِحِدَّتِهِ. 3.""جَاءَ صَارِخاً أَهْلَهُ"" : مُسْتَغِيثاً"', '');
