INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2498, 'صَارِمٌ', 'صارم', 'اسم فاعل', 'صرم', 'صارم', 'صرم', 'فا. من صَرَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من صَرَمَ). 1.""سَيْفٌ صَارِمٌ"" : قَاطِعٌ، حَادٌّ جِدّاً. 2. ""رَجُلٌ صَارِمٌ فِي مَوَاقِفِهِ"" : لاَ يَحِيدُ عَنْهَا، حَادٌّ، حَاسِمٌ، شُجَاعٌ. ""لَهْجَةٌ صَارِمَةٌ "". 3. ""أَصْدَرَ الْحَاكِمُ حُكْماً صَارِماً "" : قَاسِياً، شَدِيداً، لَيْسَ فِيهِ تَسَامُحٌ وَلاَ رَأْفَةٌ."', '');
