INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2511, 'صَافِي', 'صافي', 'اسم فاعل', 'صفو', 'صافي', 'صف', 'فا. من صَفَا', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فا. من صَفَا). 1.""خَرَجَ لِلنُّزْهَةِ فِي يَوْمٍ صَافٍ"" : فِي يَوْمٍ لاَ غَيْمَ فِيهِ. ""كَانَتِ السَّمَاءُ صَافِيَةَ الأَدِيمِ"". 2.""صافِي اللَّمَعانِ"": وَاضِحٌ، نَاصِعٌ. ""وَجْهٌ مُشْرِقٌ صَافِي الإِشْرَاقِ"". (طه حسين). 3.""يَمْلِكُ قَلْباً صَافِياً"" : طَيِّ"', '');
