INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2513, 'مُصَفِّقٌ', 'مصفق', 'اسم فاعل', 'صفق', 'مصفق', 'مصفق', 'فَا. مِن صَفَّقَ ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن صَفَّقَ ). ""كَانَ مِنْ بَيْنِ الْمُصَفِّقِينَ"" : مَنْ يَضْرِبُ يَدًا بِيَدٍ تَرْحِيباً أَوْ إِعْجَاباً أَوْ غِنَاءً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2514, 'مُصَفِّي', 'مصفي', 'اسم فاعل', 'صفو', 'مصفي', 'مصف', 'فَا. مِن صَفَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن صَفَّى). 1.""مُصَفِّي الزَّيْتِ فِي الْمَعْصَرَةِ"" : مُنْتَقِيهَا وَمُزِيلُ ما فيها مِنْ ثُفْلٍ. 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2515, 'مُصَلِّحُ', 'مصلح', 'اسم فاعل', 'صلح', 'مصلح', 'مصلح', 'فَا. مِن صَلَّحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن صَلَّحَ). ""مُصَلِّحُ السَّاعَاتِ"" : مَنْ يُصْلِحُ مَا فَسَدَ مِنْهَا مُصْلِحٌ. ""مُصَلِّحُ السَّيَّارَاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2516, 'صَالِحٌ', 'صالح', 'اسم فاعل', 'صلح', 'صالح', 'صلح', 'فا. من صَلُحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":صُلَحَاءُ:صُلاَّحٌ:صَوَالِحُ', '', '', '', '', '', '', '', '', '"(فا. من صَلُحَ). 1.""كَانَ رَجُلاً صَالِحاً"": تَقِيّاً، مُؤْمِناً، وَرِعاً. 2.""تُرَاثُ السَّلَفِ الصَّالِحِ"" : تُرَاثُ الأَجِلاَّءِ التُّقَاةِ. 3.""قَامَ بِعَمَلٍ صَالِحٍ"" : بِعَمَلٍ مُثْمِرٍ، خَالٍ مِنَ العَيْبِ. ""يُمَيِّزُ بَيْنَ ا"', '');
