INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2529, 'مُصَوِّرٌ', 'مصور', 'اسم فاعل', 'صور', 'مصور', 'مصر', 'فَا. مِن صَوَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن صَوَّرَ). 1.الحشر آية 24 هُوَ اللهُ الخَالِقُ البَارِي الْمُصَوِّرُ (قرآن) : اِسْمٌ مِنْ أَسْمَاءِ اللهِ الحُسْنَى. 2.""أَخَذَ لَهُ الْمُصَوِّرُ صُورَةً"" : مَنْ يُصَوِّرُ بِآلَةِ التَّصْوِيرِ. ""مُصَوِّرٌ بِالتَّلْفزة"" ""مُصَوِّرُ أَفْلاَمٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2530, 'مُصَمِّمٌ', 'مصمم', 'اسم فاعل', 'صمم', 'مصمم', 'مصم', 'فَا. مِنْ صَمَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ صَمَّمَ). 1.""مُصَمِّمٌ العَزْمَ عَلَى الْمُضِيِّ فِي عَمَلِهِ"" : مُقَرِّرٌ، ثَابِتٌ، رَاسِخُ العَزْمِ، لاَ أَحَدَ يَثْنِيهِ عَنْ عَمَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2531, 'صَانِعٌ', 'صانع', 'اسم فاعل', 'صنع', 'صانع', 'صنع', 'فا. من صَنَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":صُنَّاعٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من صَنَعَ). 1.""صَانِعٌ مَاهِرٌ"" : عَامِلٌ يَعْمَلُ بِيَدِهِ. ""تَعْتَمِدُ الصِّنَاعَةُ التَّقْلِيدِيَّةُ عَلَى صُنَّاعٍ مَهَرَةٍ"". "', '');
