INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2535, 'مُصَنِّفٌ', 'مصنف', 'اسم فاعل', 'صنف', 'مصنف', 'مصنف', 'فَا. مِن صَنَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن صَنَّفَ). ""قَالَ الْمُصَنِّفُ"" : قَالَ الْمُؤَلِّفُ، أَيْ مُؤَلِّفُ الْمُصَنَّفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2536, 'صَاهِلٌ', 'صاهل', 'اسم فاعل', 'صهل', 'صاهل', 'صهل', 'فا. من صَهَلَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":صَوَاهِلُ"', '', '', '', '', '', '', '', '', '"(فا. من صَهَلَ). ""اِمْتَطَى ظَهْرَ صَاهِلِهِ"" : فَرَسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2537, 'صَوَاهِلُ', 'صواهل', 'اسم فاعل', '', 'صواهل', 'صهل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2538, 'مُصَوِّتٌ', 'مصوت', 'اسم فاعل', 'صوت', 'مصوت', 'مصت', 'فَا. مِن صَوَّتَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن صَوَّتَ). 1.""الْمُصَوِّتُ في الانْتِخَابَاتِ"" : مَنْ يُدْلِي بِرَأْيِهِ. ""بَلَغَ عَدَدُ الْمُصَوِّتِينَ في الانْتِخَابَاتِ البَرْلَمَانِيَّةِ نِسْبَةً كَبِيرَةً"". 2.""حَرْفٌ مُصَوِّتٌ"" : حَرْفُ عِلَّةٍ أَو لِينٍ أَو حَرَكَةٍ وَمَا يَتِمُّ نُطْقُهُ دُونَ عَوَائِقَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2539, 'ضواغن', 'ضواغن', 'اسم فاعل', '', 'ضواغن', 'ضغن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2540, 'صَاوِي', 'صاوي', 'اسم فاعل', 'صوي', 'صاوي', 'ص', 'فا. من صَوَى', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"صَاو-صَاوٍ، الصَّاوِي، ةٌ [ص و ي] (فا. من صَوَى). 1.""نَبَاتٌ صَاوٍ"" : يَابِسٌ. 2.""ضَرْعٌ صَاوٍ"" : جَافٌّ لَمْ يَبْقَ مِنْهُ شَيْءٌ مِنَ اللَّبَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2541, 'مُصَيِّفٌ', 'مصيف', 'اسم فاعل', 'صيف', 'مصيف', 'مصف', 'فَا. مِن صَيَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن صَيَّفَ). ""مُصَيِّفٌ مَعَ عَائِلَتِهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2542, 'مُضَارِبٌ', 'مضارب', 'اسم فاعل', 'ضرب', 'مضارب', 'مضرب', 'فَا. مِن ضَارَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن ضَارَبَ). ""مُضَارِبٌ فِي العَمَلِيَّاتِ التِّجَارِيَّةِ"" : مُتَاجِرٌ فِيهَا فِي الأَسْوَاقِ لِلانْتِفَاعِ مِنْ فُرُوقِ الأَسْعَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2543, 'مُضَارِعٌ', 'مضارع', 'اسم فاعل', 'ضرع', 'مضارع', 'مضرع', 'فَا مِنْ ضَارَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا مِنْ ضَارَعَ). 1.""مُضَارِعٌ لَهُ"" : مُشَابِهٌ. 2.""الفِعْلُ الْمُضَارِعُ"" (نح): هُوَ صِيغَةٌ فِعْلِيَّةٌ تَدُلُّ عَلَى الْحَالِ أَوِ الاِسْتِقْبَالِ. ""خَرَجَ"" مُضَارِعُهُ هُوَ : أَخْرُجُ، تَخْرُجُ، نَخْرُجُ، يَخْرُجُ، وَيَكُونُ مَبْدُوءاً بِأَحَدِ أَحْرُفِ الْمُضَارَعَةِ (أن ي ت، أنيت). 3.""بَحْرُ الْمُضَارِعِ"" : بَحْرٌ مِنْ بُحُورِ الشِّعْرِ العَرَبِيِّ وَوَزْنُهُ مَفَاعِيلُنْ فَاعِلاَتُنْ *مَفَاعِيلُنْ فَاعِلاَتُنْ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2544, 'ضَائِعٌ', 'ضائع', 'اسم فاعل', 'ضيع', 'ضاءع', 'ضع', 'فا. من ضَاعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":ضِيَاعٌ"', '', '', '', '', '', '', '', '', '"(فا. من ضَاعَ). 1.""يَبْحَثُ عَنْ شَيْءٍ ضَائِعٍ"" : عَنْ شَيْءٍ مَفْقُودٍ. ""الوَقْتُ الضَّائِعُ"" ""الزَّمَنُ الضَّائِعُ"". 2.""وَجَدَهُ ضَائِعاً بَيْنَ الأَزِقَّةِ "" : مُهْمَلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2545, 'ضِيَاعٌ', 'ضياع', 'اسم فاعل', '', 'ضياع', 'ضع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
