INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2552, 'ضَائِقٌ', 'ضائق', 'اسم فاعل', 'ضيق', 'ضاءق', 'ضق', 'فا. من ضَاقَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":ضَاقَةٌ"', '', '', '', '', '', '', '', '', '"(فا. من ضَاقَ). 1.""ضَائِقُ النَّفْسِ"" : مَنْ بِنَفْسِهِ ضَيْقٌ وَشِدَّةٌ، البَرِمُ بِالنَّاسِ. 2.""يَعِيشُ فِي ضَائِقَةٍ"" : فِي أَزْمَةٍ، فِي عُسْرٍ. ""يَتَخَبَّطُ فِي ضَائِقَةٍ مَالِيَّةٍ"" ""الضَّائِقَةُ الاقْتِصَادِيَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2553, 'ضوائق', 'ضوائق', 'اسم فاعل', '', 'ضواءق', 'ضق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2554, 'ضَائِمٌ', 'ضائم', 'اسم فاعل', 'ضيم', 'ضاءم', 'ضم', 'فا. من ضَامَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"ضَائِمٌ-ضَائِمٌ [ض ي م] (فا. من ضَامَ). ""رَجُلٌ ضَائِمٌ"" : مَظْلُومٌ، مَقْهُورٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2555, 'ضوائم', 'ضوائم', 'اسم فاعل', '', 'ضواءم', 'ضم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2556, 'مُضَايِقٌ', 'مضايق', 'اسم فاعل', 'ضيق', 'مضايق', 'مضق', 'فَا. مِن ضَايَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن ضَايَقَ). ""مُضَايِقٌ في العَمَلِ"" : مُعَرْقِلٌ، مُزْعِجٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2557, 'ضَابِطٌ', 'ضابط', 'اسم فاعل', 'ضبط', 'ضابط', 'ضبط', 'فا. من ضَبَطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":ضُبَّاطٌ:ضَوَابِطُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من ضَبَطَ). 1.""رَجُلٌ ضَابِطٌ لأُمُورِهِ"" : حَازِمٌ فِيهَا، مُتَحَكِّمٌ فِيهَا. 2.""لِكُلِّ قَانُونٍ ضَابِطٌ"" : حُكْمٌ كُلِّيٌّ يَنْطَبِقُ عَلَى جُزْئِيَّاتِهِ. 3.""يَتَصَرَّفُ بِغَيْرِ ضَابِطٍ وَلاَ رَادِعٍ"": بِلا قَيْدٍ وَلاَ رَقَابَةٍ. 4.""ضَابِطُ الارْتِبَاطِ"" : الْمَسْؤُولُ عَنْ رَبْطِ الاتِّصَالِ مَا بَيْنَ هَيْئَةٍ وَأُخْرَى. ""ضَابِطُ الاتِّصَالِ"". 5.""سُلْطَةٌ لاَ ضَابِطَ لَهَا"" : لاَ حُكْمَ، لاَ قَانُونَ يَح"', '');
