INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2565, 'ضَاحِي', 'ضاحي', 'اسم فاعل', 'ضحو', 'ضاحي', 'ضح', 'فا. من ضَحَا', 'Tk', 'Ta', 'مفرد', 'DnT', '', '', '"ضَوَاحٍ:الضَّوَاحِي"', '', '', '', '', '', '', '', '', '"(فا. من ضَحَا). 1.""طَرِيقٌ ضَاحٍ"" : بَارِزٌ. 2.""يَسْكُنُ فِي ضَاحِيَةٍ مِنَ ضَوَاحِي الْمَدِينَةِ"" : فِي نَاحِيَةٍ مِنْ نَوَاحِيهَا، كُلُّ مَا يُحِيطُ بِالمَدِينَةِ مِنْ أَرَاضٍ وَمَسَاكِنَ. ""ضَوَاحِي الْمَدِينَةِ"". 3.""ضَاحِيَةُ الإِنْسَانِ"" : مَا بَرَزَ مِنْ أَعْضَائِهِ لِلشَّمْسِ."', '');
