INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2568, 'ضَاحِكٌ', 'ضاحك', 'اسم فاعل', 'ضحك', 'ضاحك', 'ضحك', 'فا. من ضَحِكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من ضَحِكَ). ""تَجِدُهُ ضَاحِكاً فِي كُلِّ آنٍ"" : مَنْ تَنْفَرِجُ شَفَتَاهُ وَتَبْدُو أَسْنَانُهُ مِنَ الفَرَحِ وَالسُّرُورِ."', '');
