INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2572, 'مُضَخِّمٌ', 'مضخم', 'اسم فاعل', 'ضخم', 'مضخم', 'مضخم', 'فَا. مِن ضَخَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن ضَخَّمَ). 1.""مُضَخِّمُ الأُمُورِ"" : مَنْ يُضَخِّمُهَا وَيُعْطِيهَا حَجْماً أَكْبَرَ مِنْ حَجْمِها الحَقيقِيِّ. 2.""مُضَخِّمُ الصَّوْتِ"" : مُكَبِّرُ الصَّوْتِ، آلَةٌ صَوْتِيَّةٌ تَقُومُ بِتَضْخِيمِ الصَّوْتِ وَتَكْبِيرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2573, 'مُضِرٌّ', 'مضر', 'اسم فاعل', 'ضرر', 'مضر', 'مضر', 'فَا. مِن ضَرَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُضِرٌّ-مُضِرٌّ، ةٌ [ض ر ر] (فَا. مِن ضَرَّ). ""التَّدْخِينُ مُضِرٌّ بِصِحَّةِ الإِنْسَانِ"" : مُؤْذٍ، مُحْدِثٌ لِلضَّرَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2574, 'ضَارٌّ', 'ضار', 'اسم فاعل', 'ضرر', 'ضار', 'ضر', 'فا. من ضَرَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"ضَارٌّ-ضَارٌّ [ض ر ر] (فا. من ضَرَّ). ""عَمَلٌ ضَارٌّ"" : مُضِرٌّ."', '');
