INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2609, 'ضواة', 'ضواة', 'اسم فاعل', '', 'ضواة', 'ضة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2610, 'مُطَابِقٌ', 'مطابق', 'اسم فاعل', 'طبق', 'مطابق', 'مطبق', 'فَا. مِن طَابَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:"', '', '', '', '', '', '', '', '', '"مُطَابِقٌ-مُطَابِقٌ، ةٌ [ط ب ق] (فَا. مِن طَابَقَ). 1.""مُطَابِقٌ لِلْوَاقِعِ"" : مُوَافِقٌ لَهُ. 2.""نُسْخَةٌ مُطَابِقَةٌ لِلْأَصْلِ"" : مُصَادَقٌ عَلَيْهَا لِتَأْكِيدِ مُوَافَقَتِهَا وَعَدَمِ اخْتِلاَفِهَا عَنِ الأَصْلِ، أَوْ نُسْخَةٌ مُصَوَّرَةٌ عَنِ الأَصْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2611, 'مُطَارِدٌ', 'مطارد', 'اسم فاعل', 'طرد', 'مطارد', 'مطرد', 'فَا. مِن طَارَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُطَارِدٌ-مُطَارِدٌ [ط ر د] (فَا. مِن طَارَدَ). ""مُطَارِدُ اللُّصُوصِ"": مُلاَحِقهُمْ، مُتَعَقِّبُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2612, 'طَائِشٌ', 'طائش', 'اسم فاعل', 'طيش', 'طاءش', 'طش', 'فا. من طَاشَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من طَاشَ). 1.""لاَ يَزَالُ وَلَداً طَائِشاً"" : مَنْ يَتَصَرَّفُ تَصَرُّفَاتٍ هَوْجَاءَ، خَفِيفُ العَقْلِ، أَهْوَجُ. 2.""أَصَابَتْهُ رَصَاصَةٌ طَائِشَةٌ"" : الرَّصَاصَةُ الَّتِي صَدَرَتْ صِدْفَةً مِنْ سِلاَحٍ بِلاَ قَصْدٍ أوْ هَدَفٍ. 3.""سَهْمٌ طَائِشٌ"" : مُنْحَرِفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2613, 'طوائش', 'طوائش', 'اسم فاعل', '', 'طواءش', 'طش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2614, 'طَائِعٌ', 'طائع', 'اسم فاعل', 'طيع', 'طاءع', 'طع', 'فا. من طَاعَ.', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"ج: ـون، ـات. (فا. من طَاعَ). ""وَلَدٌ طَائِعٌ"', '');
