INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2616, 'طَائِفٌ', 'طائف', 'اسم فاعل', 'طوف', 'طاءف', 'طف', 'فا. من طَافَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":طُوَّفٌ:طَوَائِفُ"', '', '', '', '', '', '', '', '', '"(فا. من طَافَ). 1.""عَيَّنَهُ طَائِفاً بِاللَّيْلِ"" : حَارِساً. 2. الأعراف آية 201إِذَا مَسَّهُمْ طَائِفٌ مِنَ الشَّيْطَانِ تَذَكَّرُوا (قرآن) : أَيُّ شَيْءٍ أَلَمَّ بِهِمْ. 3.""مَضَتْ طَائِفَةٌ مِنَ اللَّيْلِ"" : القِطْعَةُ مِنْهُ، القِطْعَةُ مِنَ الشَّيْءِ. 4.""اِجْتَمَعَتْ طاَئِفَةٌ مِنَ الرِّجَالِ فِي سَاحَةِ الْمَدِينَةِ"" : جَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2617, 'طُوَّفٌ', 'طوف', 'اسم فاعل', '', 'طوف', 'طف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
