INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2621, 'مُطَالِبٌ', 'مطالب', 'اسم فاعل', 'طلب', 'مطالب', 'مطلب', 'فَا. مِن طَالَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُطَالِبٌ-مُطَالِبٌ [ط ل ب] (فَا. مِن طَالَبَ). ""جَاءَ مُطَالِباً بِحُقُوقِهِ"" : سَاعِياً لِلْحُصُولِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2622, 'مُطَالِعٌ', 'مطالع', 'اسم فاعل', 'طلع', 'مطالع', 'مطلع', 'فَا. مِن طَالَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:"', '', '', '', '', '', '', '', '', '"مُطَالِعٌ-مُطَالِعٌ [ط ل ع] (فَا. مِن طَالَعَ). ""مُطَالِعٌ لِلْكُتُبِ الْحَدِيثَةِ"" : قَارِئٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2623, 'مُطَرِّزٌ', 'مطرز', 'اسم فاعل', 'طرز', 'مطرز', 'مطرز', 'فَا. مِن طَرَّزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن طَرَّزَ). ""مُطَرِّزُ الفُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2624, 'طَارِفٌ', 'طارف', 'اسم فاعل', 'طرف', 'طارف', 'طرف', 'فا. من طَرَفَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":طَرَفَةٌ:طَوَارِفُ"', '', '', '', '', '', '', '', '', '"(فا. من طَرَفَ). 1.""ثَرَاؤُهُ ثَرَاءٌ طَارِفٌ"" : ثَرَاءٌ مُسْتَحْدَثٌ، طَارِئٌ. ""ثَرْوَةٌ طَارِفَةٌ"". 2.""الطَّارِفُ وَالتَّالِدُ"" : الطَّارِئُ وَالتَّالِدُ. 3.""جَاءَ بِطَارِفَةِ عَيْنٍ"" : بِمَالٍ كَثِيرٍ يُبْهِرُ العَيْنَ. 4.""طَارِفَةُ الْخَيْمَةِ"" : حَلَقٌ فِيهَا حِبَالٌ تُشَدُّ إِلَى الأَوْتَادِ. 5.""هَذَا الكِتَابُ فِيهِ طَوَارِفُ القَرَائِحِ"": فِيهِ مُسْتَمْلَحَاتُ الْخَوَاطِرِ وَمُسْتَظْرَفَاتُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2625, 'طَرَفَةٌ', 'طرفة', 'اسم فاعل', '', 'طرفة', 'طرفة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
