INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2627, 'طَارِقٌ', 'طارق', 'اسم فاعل', 'طرق', 'طارق', 'طرق', 'فا. من طَرَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":طُرَّاقٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من طَرَقَ). 1.""جَاءَ الطَّارِقُ يَبْحَثُ عَنْ مَأْوَى"" : الوَافِدُ لَيْلاً. 2.""مَنِ الطَّارِقُ"" : مَنْ يَدُقُّ البَابَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2628, 'طُرَّاقٌ', 'طراق', 'اسم فاعل', '', 'طراق', 'طرق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2629, 'طَاغِي', 'طاغي', 'اسم فاعل', 'طغي', 'طاغي', 'طغ', 'فا. من طَغَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":طُغَاةٌ"', '', '', '', '', '', '', '', '', '"(فا. من طَغَى). 1.""الْحَاكِمُ الطَّاغِي"" : الظَّالِمُ، الْجَبَّارُ الْمُتَجَبِّرُ، مَنْ يَحْكُمُ بِقَسْوَةٍ وَعُنْفٍ. ""حَاكِمٌ طَاغِيَةٌ"" ""اِنْتَهَى عَهْدُ الطُّغَاةِ"". 2.""أَظْهَرَ رَغْبَةً طاغِيَةً"" : جارِفَةً. ""اِسْتَبَدَّتْ بِهِ شَهْوَةٌ وَحْشِيَّةٌ طَاغِيَةٌ لِلرِّبْحِ"". (حنا مينا)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2630, 'طرقة', 'طرقة', 'اسم فاعل', '', 'طرقة', 'طرقة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2631, 'طَاعِمٌ', 'طاعم', 'اسم فاعل', 'طعم', 'طاعم', 'طعم', 'فا. من طَعِمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"طَاعِمٌ-طَاعِمٌ [ط ع م] (فا. من طَعِمَ). 1.""رَجُلٌ طَاعِمٌ"" : ذُو طَعَامٍ. 2.""هُوَ طَاعِمٌ"" : حَسَنُ الْحَالِ فِي الْمَطْعَمِ. 3.""هُوَ طَاعِمٌ عَنْ طَعَامِهِمْ"" : أَيْ مُسْتَغْنٍ عَنْهُ."', '');
