INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2639, 'طَالِبٌ', 'طالب', 'اسم فاعل', 'طلب', 'طالب', 'طلب', 'فا. من طَلَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":طُلاَّبٌ:طَلَبَةٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من طَلَبَ). 1.""طَالِبُ العِلْمِ"" : الرَّاغِبُ فِي تَحْصِيلِ العِلْمِ. ""اِثْنَانِ مَنْهُومَانِ: طَالِبُ عِلْمٍ وَطَالِبُ دُنْيَا"". (الجاحظ). 2.""طَالِبٌ فِي الْمَعْهَدِ"" : مَنْ يُتَابِعُ دِرَاسَتَهُ فِي سِلْكٍ أَعْلَى. ""طَالِبٌ فِي الْجَامِعَةِ"" ""اِلْتَحَقَ الطُّلابُ بِالكُلِّيَّةِ"". 3.""جَاءَ طَالِباً لِلزَّوَاجِ مِنِ ابْنَتِهِ"" : رَاغِباً فِي الزَّوَاجِ مِنْهَا."', '');
