INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2705, 'ظاهِرٌ', 'ظاهر', 'اسم فاعل', 'ظهر', 'ظاهر', 'ظهر', 'فا. من ظَهَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":ظَواهِرُ"', '', '', '', '', '', '', '', '', '"(فا. من ظَهَرَ). 1.""اِسْتَقَرَّ في ظاهِرِ الْمَدينَةِ"" : في ضَاحِيَتِها. 2.""عَلَى ظاهِرِ اليَدِ"" : على ظَهْرِ اليَدِ. 3.""يَقْرَأُ القَصيدَةَ ظاهِراً"" : يَقْرَأُها عَنْ ظَهْرِ قَلْبٍ، غَيْباً. 4.""هُوَ اللَّهُ الظَّاهِرُ"" : مِنْ أَسْماءِ اللَّهِ الْحُسْنَى. 5.""إِنَّ الحَوادِثَ كانَتْ عَفَوِيَّةً في الظَّاهِرِ"" : على ما يَبْدُو. ""حَسَبَ الظَّاهِرِ"". 6.""ظاهِرٌ جَلِيٌّ"" : شَكْلٌ. ""أَمْرُهُمْ مَكْشوفٌ وَظاهِرُهُمْ مَعْروفٌ"". (الجاحظ). ""لاَ تَحْكُمْ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2706, 'ظَواهِرُ', 'ظواهر', 'اسم فاعل', '', 'ظواهر', 'ظهر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
