INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2709, 'عَائِبٌ', 'عائب', 'اسم فاعل', 'عيب', 'عاءب', 'عب', 'فا. مِن عَابَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِن عَابَ). 1.""عَائِبُ الشَّيْءِ"" : مَنْ يَجِدُ فِي كُلِّ شَيْءٍ عَيْباً، مَنْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2710, 'عوائب', 'عوائب', 'اسم فاعل', '', 'عواءب', 'عب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2711, 'عَائِدٌ', 'عائد', 'اسم فاعل', 'عود', 'عاءد', 'عد', 'فا. مِنْ عَادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات:عَوَائِدُ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ عَادَ). 1.""عَائِدٌ إِلَى وَطَنِهِ"" رَاجِعٌ إِلَيْهِ. 2.""عَائِدُ الْمَرِيضِ"" : مَنْ يَزُورُ الْمَرِيضَ، أَيْ زَائِرُهُ. 3.""عَائِدَةُ أَعْمَالِهِ وَأَفْعَالِهِ"" : مَعْرُوفُهُ، صِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2712, 'عَوَائِدُ', 'عوائد', 'اسم فاعل', '', 'عواءد', 'عد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2713, 'مُعَادِلٌ', 'معادل', 'اسم فاعل', 'عدل', 'معادل', 'معدل', 'فَا. مِن عَادَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُعَادِلٌ-مُعَادِلٌ [ع د ل] (فَا. مِن عَادَلَ). 1.""ثَمَنٌ مُعَادِلٌ لِقِيمَةِ العَمَلِ"" : مُوَازٍ، مُسَاوٍ. 2.""الْمُعَادِلُ فِي مَوَادِّ الامْتِحَانِ"": هُوَ الرَّقْمُ الَّذِي نَضْرِبُهُ فِي حَاصِلِ نُقَطِ مَادَّةٍ مِنْ مَوَادِّ الامْتِحَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2714, 'مُعارِضٌ', 'معارض', 'اسم فاعل', 'عرض', 'معارض', 'معرض', 'فَا. مِن عَارَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن عَارَضَ). "" سِياسِيٌّ مُعَارِضٌ"" : مُعَاكِسٌ، مُضَادٌّ. ""مُعَارِضُ النِّظَامِ القَائِمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2715, 'مُعارِكٌ', 'معارك', 'اسم فاعل', 'عرك', 'معارك', 'معرك', 'فَا. مِن عَارَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن عَارَكَ). ""ظَلَّ مُعَارِكاً فِي الجَبْهَةِ"" : مُقَاتِلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2716, 'عَائِزٌ', 'عائز', 'اسم فاعل', 'عوز', 'عاءز', 'عز', 'فا. مِنْ عَازَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات:عَوَائِزُ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ عَازَ). ""رَجُلٌ عَائِزٌ"" : مُفْتَقِرٌ، أَعْوَزُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2717, 'عَوَائِزُ', 'عوائز', 'اسم فاعل', '', 'عواءز', 'عز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2718, 'عَائِشٌ', 'عائش', 'اسم فاعل', 'عيش', 'عاءش', 'عش', 'فا. مِنْ عَاشَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِنْ عَاشَ). 1.""هُوَ رَجُلٌ عَائِشٌ"" : مَنْ يَعِيشُ عِيشَةً هَنِيَّةً حَسَنَةً. 2.""عَائِشٌ طُولَ حَيَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2719, 'عَيْلَى', 'عيلى', 'اسم فاعل', '', 'عيلى', 'عل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
