INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2721, 'مُعَاصِرٌ', 'معاصر', 'اسم فاعل', 'عصر', 'معاصر', 'معصر', 'فَا. مِن عَاصَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن عَاصَرَ). 1.""كَاتِبٌ مُعَاصِرٌ"" : مَنْ هُوَ فِي عَصْرِكَ وَزَمَانِكَ. ""كَانَ مُعَاصِراً لِهَارُونَ الرَّشِيدِ"" : أَيْ عَاشَ فِي عَصْرِ هَارُون. 2.""حَدَثٌ مُعَاصِرٌ"" : مَا حَدَثَ فِي عَصْرِكَ وَزَمَانِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2722, 'عَائِقٌ', 'عائق', 'اسم فاعل', 'عوق', 'عاءق', 'عق', 'فا. مِنْ عَاقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":عَوَائِقُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ عَاقَ). 1.""مَنَعَهُ عَائِقٌ مِنَ الْوُصُولِ إِلَى عَمَلِهِ"" : مَانِعٌ، حَاجِزٌ، كُلُّ مَا يَعُوقُ الْمَرْءَ وَيَمْنَعُهُ. ""إِن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2723, 'عَوَائِقُ', 'عوائق', 'اسم فاعل', '', 'عواءق', 'عق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2724, 'مُعَاقِبٌ', 'معاقب', 'اسم فاعل', 'عقب', 'معاقب', 'معقب', 'فَا. مِن عَاقَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن عَاقَبَ). 1.""مُعَاقِبُ الأَشْرَارِ"" : مَنْ يُعَاقِبُ وَيُحَاسِبُ. 2.""ظَلَّ مُعَاقِباً الأَثَرَ"" : مُتَتَبِّعاً... 3.""مُعَاقِبُ الخَصْمِ"" : الْمُدْرِك بِالثَّأْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2725, 'مُعَاكِسٌ', 'معاكس', 'اسم فاعل', 'عكس', 'معاكس', 'معكس', 'فَا. مِن عَاكَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن عَاكَسَ). 1.""وَلَدٌ مُعَاكِسٌ"" : مُمَانِعٌ. 2.""هُجُومٌ مُعَاكِسٌ"" : هُجُومٌ يَنْتَقِلُ مِنَ الدِّفَاعِ إِلَى الهُجُومِ. 3.""تَيَّارٌ مُعَاكِسٌ"" : تَيَّارٌ يَهُبُّ مِنْ جَانِبٍ مُضَادٍّ. ""رِيحٌ مُعَاكِسَةٌ"" ""مَضَى فِي طَرِيقٍ مُعَاكِسٍ لِمَا أُرِيدُهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2726, 'عَائِلٌ', 'عائل', 'اسم فاعل', 'عول', 'عاءل', 'عل', 'فا. مِنْ عَالَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":عَالَةٌ:عُيَّلٌ:عَيْلَى"', '', '', '', '', '', '', '', '', '"(فا. مِنْ عَالَ). 1.""هُوَ رَجُلٌ عَائِلٌ"" : كَثِيرُ الْعِيَالِ. 2.""عَاشَ عَائِلاً طُولَ حَيَاتِهِ"" : مُفْتَقِرًا. 3.""عَائِلُ النَّبَاتِ"" : النَّبَاتُ الَّذِي يَعْتَمِد"', '');
