INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2729, 'عَابِئٌ', 'عابئ', 'اسم فاعل', 'عبأ', 'عابء', 'عب', 'فا. مِنْ عَبَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِنْ عَبَأَ). ""غَيْرُ عَابِئٍ بِشَيْءٍ"" : غَيْرُ مُكْتَرِثٍ، غَيْرُ مُهْتَمٍّ. ""فَسَارَتْ إِلَى جَانِبِهِ غَيْرَ عَابِئَةٍ بِالسَّابِلَةِ"". (ن. محفوظ)."', '');
