INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2732, 'عَائِمٌ', 'عائم', 'اسم فاعل', 'عوم', 'عاءم', 'عم', 'فا. مِنْ عَامَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِنْ عَامَ). 1. ""عَائِمٌ فِي الْمَاءِ"" : سَابِحٌ فِي"', '');
