INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2734, 'مُعَانِدٌ', 'معاند', 'اسم فاعل', 'عند', 'معاند', 'معند', 'فَا. مِن عَانَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن عَانَدَ). ""وَلَدٌ مُعَانِدٌ"" : مُخَالِفٌ، مُعَارِضٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2735, 'مُعَاوِدٌ', 'معاود', 'اسم فاعل', 'عود', 'معاود', 'معد', 'فَا. مِن عَاوَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُعَاوِدٌ-مُعَاوِدٌ، ةٌ [ع و د] (فَا. مِن عَاوَدَ). 1.""مُعَاوِدُ الأَشْيَاءِ"" : رَاجِعٌ إِلَيْهَا بَعْدَمَا كَانَ مُنْصَرِفاً عَنْهَا. 2.""حُمَّى مُعَاوِدَةٌ"" : عَادَتْ كَمَا كَانَتْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2736, 'مُعَاوِنٌ', 'معاون', 'اسم فاعل', 'عون', 'معاون', 'معن', 'فَا. مِن عَاوَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُعَاوِنٌ-مُعَاوِنٌ [ع و ن] (فَا. مِن عَاوَنَ). ""مُعَاوِنٌ لَهُ فِي أَعْمَالِهِ"" : مُسَاعِدٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2737, 'مُعَايِرٌ', 'معاير', 'اسم فاعل', 'عير', 'معاير', 'معر', 'فَا. مِن عَايَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُعَايِرٌ-مُعَايِرٌ، ةٌ [ع ي ر] (فَا. مِن عَايَر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2738, 'مُعَايِنٌ', 'معاين', 'اسم فاعل', 'عين', 'معاين', 'معن', 'فَا. مِن عَايَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن عَايَنَ). ""مُعَايِنٌ لِمَا حَدَثَ"" : مُشَاهِدٌ."', '');
