INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2751, 'مُعَبِّرٌ', 'معبر', 'اسم فاعل', 'عبر', 'معبر', 'معبر', 'فَا. مِن عَبَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(فَا. مِن عَبَّرَ). 1.""كَانَ مُعَبِّراً عَنْ أَفْكَارِهِ بِوُضُوحٍ"" : مُفْصِحاً عَنْهَا، مُبيّناً لَهَا. 2.""كَلاَمٌ مُعَبِّرٌ"" : فَصِيحٌ، بَلِيغٌ. ""صَمْتٌ مُعَبِّرٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2752, 'عَابِرٌ', 'عابر', 'اسم فاعل', 'عبر', 'عابر', 'عبر', 'فا. مِنْ عَبَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(فا. مِنْ عَبَرَ). 1.""خَرَجَ عَابِراً الطَّرِيقَ"" : الْمَارُّ مِنَ الطَّرِيقِ بِلاَ تَوَقُّفٍ. ""جَلَسَ فِي مُنْعَطَفِ الطَّرِيقِ يَمُدُّ يَدَهُ نَحْوَ العَابِرِينَ"". (جبران خ. جبران) ""كَانَتِ الطَّرِيقُ فِي تِلْكَ السَّاعَةِ خَالِيَةً مِنْ عَابِرٍ بَعِيدٍ أَوْ عَابِرَةٍ بَعِيدَةٍ"". (ع. م. العقاد). 2.""لَذَّةُ الْحُبِّ عَابِرَةٌ وَكَآبَتُهُ داَئِمَةٌ"" : زَائِلَةٌ. ""كَانَ الأَ"', '');
