INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2783, 'عَاجِلٌ', 'عاجل', 'اسم فاعل', 'عجل', 'عاجل', 'عجل', 'فا. مِنْ عَجِلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"عَاجِلٌ-عَاجِلٌ، ةٌ [ع ج ل] (فا. مِنْ عَجِلَ). 1.""دَعَاهُ لِلْحُضُورِ عَاجِلاً"" : فِي أَسْرَعِ وَقْتٍ مُمْكِنٍ، التَّقَدُّمُ بِسُرْعَةٍ. 2.""سَيُؤَدِّي ثَمَنَ ظُلْمِهِ عَاجِلاً أَمْ آجِلا"', '');
