INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2791, 'مُعَذِّبٌ', 'معذب', 'اسم فاعل', 'عذب', 'معذب', 'معذب', 'فَا. مِن عَذَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن عَذَّبَ). 1.""مُعَذِّبُ الحَيَوَانِ"" : مُرْهِقُهُ. 2."" مُعَذِّبُ النَّاسِ"" : مُضْطَهِدُهُمْ، مُنَكِّلٌ بِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2792, 'عَاذِلٌ', 'عاذل', 'اسم فاعل', 'عذل', 'عاذل', 'عذل', 'فا. مِنْ عَذَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":عُذَّالٌ:عَوَاذِلُ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ عَذَلَ). ""يَا عَاذِلِي، لاَ تَلُمْنِي"" : يَا لاَئِمِي. ""يا عاذِلِي في الهَوَى العُذْرِيِّ مَعْذِرَةً"" (الهمزية)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2793, 'عُذَّالٌ', 'عذال', 'اسم فاعل', '', 'عذال', 'عذل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
