INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2796, 'مُعَرِّبٌ', 'معرب', 'اسم فاعل', 'عرب', 'معرب', 'معرب', 'فَا. مِن عَرَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن عَرَّبَ). ""مُعَرِّبُ الكَلاَمِ"" : مُتَرْجِمُهُ إِلَى اللُّغَةِ العَرَبِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2797, 'مُعَرْبِدٌ', 'معربد', 'اسم فاعل', 'عربد', 'معربد', 'معربد', 'فَا. مِن عَرْبَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(فَا. مِن عَرْبَدَ). ""سِكِّيرٌ مُعَرْبِدٌ"" : سِكِّيرٌ يَفُوهُ بِكَلِمَاتٍ سَيِّئَةٍ مُكْثِرًا مِنَ الضَّحِكِ وَالضَّجِيجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2798, 'عَارِضٌ', 'عارض', 'اسم فاعل', 'عرض', 'عارض', 'عرض', 'فا. مِنْ عَرَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":عَوَارِضُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ عَرَضَ). 1.""عَارِضٌ فِي الأُفُقِ"" : مَا اعْتَرَضَ فِي الأُفُقِ مِنْ جَرَادٍ أَوْ نَحْوِهِ فَسَدَّهُ. 2. الأحقاف آية 24 قَالُوا هَذَا عَارِضٌ مُمْطِرُنَا‎ (قرآن) : سَحَابٌ مُمْطِرٌ. 3.""عَارِضُ الْوَجْهِ""، ""عَارِضَةُ الْوَجْهِ"": صَفْحَةُ الْخَدِّ، جَانِبُ الْوَجْهِ، وَهُمَا عَارِضَانِ. 4.""خَفِيفُ الْعَارِضَيْنِ"" : أَيْ شَعَرُ عَارِضَيْهِ قَلِيلٌ. 5.""عَارِضُ الْفَمِ""، ""عَارِضَةُ الْفَمِ"" : الثَّنِيَّةُ مِنَ الأَسْنَانِ. 6.""اِمْرَأَةٌ نَقِيَّةُ الْعَوَارِضِ"": نَقِيَّةُ عُرْضِ الْفَمِ. ""تَجْلُو عَوَارِضَ ذِي ظَلْمٍ إِذَا ابْتَسَمَتْ"". (كعب بن زهير). 7.""عَارِضُ الْعُنُقِ"" : صَفْحَةُ الْعُنُقِ. 8.""إِجَازَةٌ عَارِضَةٌ"" : إِجَازَةٌ تُمْنَحُ لِلْمُوَظَّفِ لِشَيْءٍ طَرَأَ عَلَيْهِ. 9.""عَرَضَ لَهُ عَارِضٌ مَنَعَهُ مِنَ الْحُضُورِ"" : مَانِعٌ، حَاجِزٌ، حَائِلٌ. 10.""تَسَلَّقَ الْعَارِضَ"" : الْجَبَلَ. 11. ""هُوَ قَوِيُّ الْعَارِضَةِ"": ذُو جَلَدٍ وَصَرَامَةٍ، وَقُدْرَةٍ عَلَى الْكَلاَمِ. 12.""جَاءَ بِعَارِضَةٍ"" : بِرَأْيٍ جَيِّدٍ. 13.""وَضَعَ جُمْلَةً بَيْنَ عَارِضَتَيْنِ"" : بَيْنَ خَطَّيْنِ هَكَذَا (-...-): بَيْنَ شَرْطَتَيْنِ. 14."""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2799, 'عراض', 'عراض', 'اسم فاعل', '', 'عراض', 'عرض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
