INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2801, 'عَارِفٌ', 'عارف', 'اسم فاعل', 'عرف', 'عارف', 'عرف', 'فا. مِنْ عَرَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":عَوَارِفُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ عَرَفَ). 1.""عَارِفُ الْجَمِيلِ"" : مُقِرٌّ بِهِ، شَاكِرٌ لَهُ. 2.""عَارِفٌ بِأُمُورِ دِينِهِ وَعَقِيدَتِهِ"" : مُتَضَلِّعٌ، مُتَمَكِّنٌ. ""نَجَا مِنْ آفَاتِ الدُّنْيَا مَنْ كَانَ مِنَ الْعَارِفِينَ"". (التوحيدي). 3.""هَذَا أَمْرٌ عَارِفٌ"" : مَعْرُوفٌ. 4.""اِمْرَأَةٌ عَارِفَةٌ"" : مُتَضَلِّعَةٌ، لَهَا مَعْرِفَةٌ بِالأَشْيَاءِ. 5.""رَجُلٌ مِنْ ذَوِي الْعَارِفَةِ"" : مِنْ ذَوِي الإِحْسَانِ. 6.""رَجُلٌ عَارِفٌ"" : صَبُورٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2802, 'عَوَارِفُ', 'عوارف', 'اسم فاعل', '', 'عوارف', 'عرف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
