INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2805, 'مُعَرْقِلٌ', 'معرقل', 'اسم فاعل', 'عرقل', 'معرقل', 'معرقل', 'فَا. مِن عَرْقَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن عَرْقَلَ). ""مُعَرْقِلٌ لِأَعْمَالِ غَيْرِهِ"" : يُقِيمُ العَرَاقِيلَ وَالصِّعَابَ وَالعَقَبَاتِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2806, 'عَارِمٌ', 'عارم', 'اسم فاعل', 'عرم', 'عارم', 'عرم', 'فا. مِنْ عَرِمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":عَرَمَةٌ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ عَرِمَ). 1.""رَجُلٌ عَارِمٌ"" : رَجُلٌ شَرِسٌ. 2.""يَوْمٌ عَارِمٌ"" : يَوْمٌ شَدِيدُ الْبَرْدِ. 3.""اِسْتَبَدَّ بِهِ عَيَاءٌ عَارِمٌ"" : شَدِيدُ الْوَطْأَةِ. 4.""أَخَذَتْهُ شَهْوَةٌ عَارِمَةٌ"" : شَهْوَةٌ قَوِيَّةٌ، عَنِيفَةٌ. ""ثَوْرَةٌ عَارِمَةٌ جَارِفَةٌ"". 5.""خُلُقٌ عَارِمٌ"" : شَرِسٌ، شَكِسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2807, 'عَرَمَةٌ', 'عرمة', 'اسم فاعل', '', 'عرمة', 'عرمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
