INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2841, 'عَاصِبٌ', 'عاصب', 'اسم فاعل', 'عصب', 'عاصب', 'عصب', 'فا. مِنْ عَصِبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"عَاصِبٌ-عَاصِبٌ [ع ص ب] (فا. مِنْ عَصِبَ). ""رَجُلٌ عَاصِبٌ"" : أَي عَصَبَ الرِّيقُ بِفَمِهِ، يَبِسَ."', '');
