INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2864, 'عَاطِلٌ', 'عاطل', 'اسم فاعل', 'عطل', 'عاطل', 'عطل', 'فا. مِنْ عَطَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":عَوَاطِلُ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ عَطَلَ). ""أَصْبَحَ عَاطِلاً عَنِ الْعَمَلِ"" : بِلاَ عَمَلٍ، وَهُوَ رَاغِبٌ فِيهِ وَلا يَجِدُهُ. ""اِزْدَادَ عَدَدُ الْعَاطِلِينَ""."', '');
