INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2902, 'مُعَلِّقٌ', 'معلق', 'اسم فاعل', 'علق', 'معلق', 'معلق', 'فَا. مِن عَلَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن عَلَّقَ). 1.""أَضَافَ مُعَلِّقاً عَلَى كَلاَمِهِ"" : مُعَقِّباً. 2.""مُعَلِّقٌ سِيَاسِيٌّ "" : مُحَلِّلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2903, 'مُعَلَّلٌ', 'معلل', 'اسم فاعل', 'علل', 'معلل', 'معل', 'فَا. مِن عَلَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُعَلَّلٌ-مُعَلَّلٌ، ةٌ [ع ل ل] (فَا. مِن عَلَّلَ). ""أَحْكَامُهُ مُعَلَّلَةٌ"": أَيْ ثُمَّ تَبْيِينُ عِلَلِهَا بِالدَّلِيلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2904, 'مُعَلِّلٌ', 'معلل', 'اسم فاعل', 'علل', 'معلل', 'معل', 'فَا. مِن عَلَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن عَلَّلَ). ""مُعَلِّلُ الأَحْكَامِ"" : مُفَسِّرُهَا ومُبَيِّنٌ لِعِلَلِهَا بِالدَّلِيلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2905, 'مُعَلِّمٌ', 'معلم', 'اسم فاعل', 'علم', 'معلم', 'معلم', 'فَا. مِن عَلَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن عَلَّمَ). ""مُعَلِّمُ صِبْيَانٍ"" : مَنْ يُعَلِّمُ القِرَاءةَ والكِتَابَةَ فِي الكُتَّابِ والْمَدَارِسِ الابْتِدَائِيَّةِ. قُمْ لِلْمُعَلِّـمِ وَفِّـهِ التَّبْجِيـلا*كَادَ الْمُعَلِّمُ أَنْ يَكُونَ رَسُولا (أحمد شوقي). ""مُتَخَرِّجٌ مِنْ مَدْرَسَةِ الْمُعَلِّمِينَ"". 2. ""الْمُعَلِّمُ الأَوَّلُ هُوَ أَرِسْطُو والْمُعَلِّمُ الثَّانِي هُوَ الفَارَابِي"" : الفَيْلَسُوفُ الذِي وَضَعَ الأَفْكَارَ الفَلْسَفِيَّةَ الأُولَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2906, 'عَالِمٌ', 'عالم', 'اسم فاعل', 'علم', 'عالم', 'علم', 'فا. مِنْ عَلِمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":عُلَمَاءُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. مِنْ عَلِمَ). 1.""عَالِمٌ بِأُمُورِ الدِّينِ وَالْعِلْمِ"" : عَارِفٌ بِهِما. 2.""عَالِمٌ فِي عِلْمٍ مَّا"" : الْمُتَضَلِّعُ مِنْهُ، الْمُتَّصِفُ بِالْعِلْمِ وَالْمَعْرِفَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2907, 'عُلَمَاءُ', 'علماء', 'اسم فاعل', '', 'علماء', 'علم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
