INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2913, 'عَامٌّ', 'عام', 'اسم فاعل', 'عمم', 'عام', 'عم', 'فا. مِنْ عَمَّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عَامٌّ-عَامٌّ، ةٌ [ع م م] (فا. مِنْ عَمَّ). 1.""الْعَامُّ وَالْخَاصُّ"" : مَا هُوَ شَامِلٌ. ""اِسْتَبَدَّ بِهِ عَيَاءٌ عَامٌّ"". 2.""الرَّأْيُ الْعَامُّ"" : مَا يَعْتَقِدُهُ الْجُمْهُورُ. 3.""الْمَرَافِقُ الْعَامَّةُ"" : الْمَرَافِقُ الْعُمُومِيَّةُ. 4.""قَدَّمَ أَفْكَاراً عَامَّةً"" : أَفْكَاراً غَيْرَ مُدَقَّقَة. 5.""أَصْدَرَتِ الأَرْكَانُ العَامَّةُ بَلاَغاً عَسْكَرِيّاً"" : الْقِيَادَةُ الْعَسْكَرِيَّةُ الْعُلْيَا. 6.""الْقِطَاعُ الْعَامُّ"" : الْمُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2914, 'عوام', 'عوام', 'اسم فاعل', '', 'عوام', 'عم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2915, 'مُعَمِّرٌ', 'معمر', 'اسم فاعل', 'عمر', 'معمر', 'معمر', 'فَا. مِن عَمَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن عَمَّرَ). 1.""رَجُلٌ مُعَمِّرٌ"" : مَنْ طَالَ بِهِ العُمْرُ. 2. ""مُعَمِّرُ البِلاَدِ"" : بَانِيهَا، مُشَيِّدُهَا. 3. اِسْتَوْطَنَ الْمُعَمِّرُونَ البِلاَدَ"" : مُسْتَعْمِرُو البِلاَدِ الَّذِينَ اِسْتَوْلَوْا عَلَى أَرَاضِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2916, 'عَامِرٌ', 'عامر', 'اسم فاعل', 'عمر', 'عامر', 'عمر', 'فا. مِنْ عَمَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"عَامِرٌ-عَامِرٌ، ةٌ [ع م ر] (فا. مِنْ عَمَرَ). 1.""بَيْتٌ عَامِرٌ"" : مَسْكُونٌ. 2.""بَلَدٌ عَامِرٌ"" : آهِلٌ بِالسُّكَّانِ. 3.""سُوقٌ عَامِرَةٌ"" : بِهَا حَرَكَةُ بَيْعٍ وَشِرَاءٍ، نَشِيطَةٌ."', '');
