INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2959, 'غَادِرٌ', 'غادر', 'اسم فاعل', 'غدر', 'غادر', 'غدر', 'فا. من غَدَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات:غُدَّارٌ"', '', '', '', '', '', '', '', '', '"(فا. من غَدَرَ). ""رَجُلٌ غَادِرٌ"" : خَادِعٌ، خَدَّاعٌ، خَائِنٌ، غَشَّاشٌ. ""اِمْرَأَةٌ غَادِرَةٌ"" ""اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ سُلْطَانٍ جَائِرٍ وَصَدِيقٍ غَادِرٍ"" (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2960, 'مُغَايِرٌ', 'مغاير', 'اسم فاعل', 'غير', 'مغاير', 'مغر', 'فَا. مِن غَايَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. مِن غَايَرَ). ""مُغَايِرٌ فِي سُلُوكِهِ لِلآخَرِينَ"" : مُخَالِفٌ. ""عَبَّرَ عَنْ رَأْيٍ جَدِيدٍ مُغَايِرٍ لِرَأْيِهِ السَّابِقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2961, 'غَابِرٌ', 'غابر', 'اسم فاعل', 'غبر', 'غابر', 'غبر', 'فا. من غَبَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات:غُبَّرٌ"', '', '', '', '', '', '', '', '', '"(فا. من غَبَرَ). 1.""يُحْكَى فِي الزَّمَنِ الغَابِرِ"" : فِي الزَّمَنِ الْمَاضِي. 2.""عَدَدُ الَّذِينَ هَاجَرُوا أَكْثَرُ مِنْ عَدَدِ الغَابِرِينَ"" : البَاقِينَ.الأعراف آية 83فَأَنْجَيْنَاهُ وَأَهْلَهُ إِلاَّ امْرَأَتَهُ كَانَتْ مِنَ الغَابِرِينَ (قرآن). 3.""غُبَّرُ الشَّيْءِ"": بَقِيَّتُهُ."', '');
