INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2974, 'مُغَرْبِلٌ', 'مغربل', 'اسم فاعل', 'غربل', 'مغربل', 'مغربل', 'فَا. مِن غَرْبَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِن غَرْبَلَ). ""مُغَرْبِلُ الحُبُوبِ"" : مَنْ يُغَرْبِلُ بِالغِرْبالِ. ""ولاَ تَأْتِي الغَرْبَلَةُ جَيِّدَةً إِلاَ إِذَا كَانَ غِرْباَلُ مُغَرْبِلِ الْحُبُوبِ آيةً مِنَ الدِّقَةِ"" ""الطَّبِيعَةُ أَكْبَرُ مُغَرْبِلٍ"". (ميخائيل نعيمة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(2975, 'مُغَرِّدٌ', 'مغرد', 'اسم فاعل', 'غرد', 'مغرد', 'مغرد', 'فَا. مِن غَرَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(فَا. مِن غَرَّدَ). 1.""طَائِرٌ مُغَرِّدٌ"" : رَافِعٌ صَوْتَهٌ بِالغِنَاءِ. 2.""مُغَرِّدٌ خَارِجَ سِرْبِهِ"" : أَيْ مُخْتَلِفٌ عَمَّا يُحِيطُ بِهِ."', '');
