INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3029, 'غَامِرٌ', 'غامر', 'اسم فاعل', 'غمر', 'غامر', 'غمر', 'فا. من غَمَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"غَامِرٌ-غَامِرٌ، ةٌ [غ م ر] (فا. من غَمَرَ). 1.""مَاءٌ غَامِرٌ"" : كَثِيرٌ. 2.""مَالٌ غَامِرٌ"" : فَائِضٌ. 3.""شَعَرَ بِفَرَحٍ غَامِرٍ"" : بِفَرَحٍ يَمْلأُ نَفْسَهُ. ""وَتَزْدَادُ بَهْجَتِي حَتَّى تَتَحَوَّلَ إِلَى فَرْحَةٍ غَامِرَةٍ""."', '');
