INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3123, 'فَارِغٌ', 'فارغ', 'اسم فاعل', 'فرغ', 'فارغ', 'فرغ', 'فا. من فَرَغَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فا. من فَرَغَ). 1.""مَقْعَدٌ فَارِغٌ"" : شَاغِرٌ، خَالٍ. 2.""حَدَّثَهُ بِكَلاَمٍ فَارِغٍ"": بِكَلاَمٍ لاَمَعْنَى لَهُ. ""أَحَادِيثُ فَارِغَةٌ"". 3.""اِنْتَظَرَهُ بِفَارِغِ الصَّبْرِ"" : بِصَبْرٍ يَكَادُ يَنْفَدُ. القصص آية 10وَأَصْبَحَ فُؤَادُ أُمِّ مُوسَى فَارِغاً (قرآن) : أَيْ خَالِياً مِنَ الصَّبْرِ وَالْعَقْلِ. ""فَارِغُ الْقَلْبِ"" ""فَارِغُ الصَّبْرِ"". 4.""غُرْفَةٌ فَارِغَةٌ"" : خَالِيَةٌ. 5.""مَعِدَتُهُ فَارِغَةٌ"" : لاَ طَعَامَ بِهَا، صَائِمٌ. "', '');
