INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3125, 'مُفَرِّقٌ', 'مفرق', 'اسم فاعل', 'فرق', 'مفرق', 'مفرق', 'فا. من فَرَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من فَرَّقَ). 1.""مُفَرِّقُ الشَّمْلِ"" : مُشَتِّتُهُ. 2.""مُفَرِّقُ الغَنَائِمِ"" : مُوَزِّعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3126, 'فَارِقٌ', 'فارق', 'اسم فاعل', 'فرق', 'فارق', 'فرق', 'فا. من فَرَقَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":فُرَّاقٌ:فَوَارِقُ"', '', '', '', '', '', '', '', '', '"(فا. من فَرَقَ). 1.""لَمْ يَكُنِ الْفَارِقُ بَيْنَهُمَا كَبِيراً"" : مَا يُمَيِّزُ بَيْنَهُمَا. 2.""اِنْتَشَرَ سَحَابٌ فَارِقٌ فِي السَّمَاءِ"" : سَحَابٌ مُنْعَزِلٌ."', '');
