INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3134, 'فَاسِقٌ', 'فاسق', 'اسم فاعل', 'فسق', 'فاسق', 'فسق', 'فا. من فَسَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":فُسَّاقٌ:فَوَاسِقُ"', '', '', '', '', '', '', '', '', '"(فا. من فَسَقَ). ""إِنَّهُ رَجُلٌ فَاسِقٌ"" : أَي الْفَاجِرُ الَّذِي لاَ يَتَوَرَّعُ عَنِ ارْتِكَابِ الْمُوبِقَاتِ وَالْفَوَاحِشِ. الحجرات آية 6يَا أَيُّهَا الَّذِينَ"', '');
