INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3172, 'فَاكِهٌ', 'فاكه', 'اسم فاعل', 'فكه', 'فاكه', 'فكه', 'فا. من فَكِهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":فَكَهَةٌ"', '', '', '', '', '', '', '', '', '"(فا. من فَكِهَ). 1.""مُمَثِّلٌ فَاكِهٌ"" : ذُو فُكَاهَةٍ. 2.""فَاكِهُ السُّوقِ"" : صَاحِبُ الْفَاكِهَةِ"', '');
