INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3180, 'مُقَابِلٌ', 'مقابل', 'اسم فاعل', 'قبل', 'مقابل', 'مقبل', 'فا. من قابَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُقَابِلٌ-مُقَابِلٌ، ةٌ [ق ب ل] (فا. من قابَلَ). 1. ""يَشْتَغِلُ مُقَابِلَ أَجْرٍ"" : لِقَاءَ أَجْرٍ. ""مُقَابِلَ ذَلِكَ"" ""يَعْمَلُ دُونَ مُقَابِلٍ"". 2.""جَلَسَ فِي الاتِّجَاهِ الْمُقَابِلِ"" : فِي الجَانِبِ الْمُوَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3181, 'مُقَاتِلٌ', 'مقاتل', 'اسم فاعل', 'قتل', 'مقاتل', 'مقتل', 'فا. من قَاتَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من قَاتَلَ). 1. ""مُقَاتِلٌ شَهْمٌ"" : مُحَارِبٌ. 2. ""طَائِرَةٌ مُقَاتِلَةٌ"" : طَائِرَةٌ عَسْكَرِيَّةٌ مُزَوَّدَةٌ بِالقَنَابِلِ والصَّوَارِيخِ تُسْتَخْدَمُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3182, 'قَائِدٌ', 'قائد', 'اسم فاعل', 'قود', 'قاءد', 'قد', 'فا. من قَادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات:قَادَةٌ:قُوَّادٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من قَادَ). 1.""قَائِدُ الْكَتِيبَةِ الْعَسْكَرِيَّةِ"" : مَنْ يَقُودُهَا وَيَتَحَكَّمُ فِي سَيْرِهَا وَحَرَكَاتِهَا وَتَخْضَعُ لِأَوَامِرِهِ. 2.""الْقَائِدُ الأَعْلَى لِلْقُوَّاتِ الْمُسَلَّحَةِ"" : الْمَلِكُ، رَئِيسُ الدَّوْلَةِ. 3.""قَائِدُ الْمِنْطَقَةِ الْجَنُوبِيَّةِ"": حَاكِمُهَا وَالْمَسْؤُولُ عَنْهَا."', '');
