INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3186, 'مُقَارِبٌ', 'مقارب', 'اسم فاعل', 'قرب', 'مقارب', 'مقرب', 'فا. من قَارَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُقَارِبٌ-مُقَارِبٌ [ق ر ب] (فا. من قَارَبَ). 1. ""عَمَلٌ مُقَارِبٌ"" : مُتَوَسِّطٌ بَيْنَ الْجَيِّدِ والرَّدِيءِ. 2. ""رَجُلٌ مُقَارِبٌ"": مُتَوَسِّطُ الْحَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3187, 'مُقَارِنٌ', 'مقارن', 'اسم فاعل', 'قرن', 'مقارن', 'مقرن', 'فا. من قَارَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من قَارَنَ). ""مُقَارِنٌ بَيْنَ عَمَلَيْنِ"" : مُمَاثِلٌ بَيْنَهُمَا، مُوَازِنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3188, 'مُقَاطِعٌ', 'مقاطع', 'اسم فاعل', 'قطع', 'مقاطع', 'مقطع', 'فا. من قَاطَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من قَاطَعَ). 1.""مُقَاطِعُ الْبَضَائِعِ الأَجْنَبِيَّةِ"" : مُمْتَنِعٌ عَنْ شِرَائِهَا. 2.""كَانَ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3189, 'قَائِظٌ', 'قائظ', 'اسم فاعل', 'قيظ', 'قاءظ', 'قظ', 'فا. من قَاظَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"قَائِظٌ، ةٌ - [ق ي ظ]. (فا. من قَاظَ). 1.""يَوْمٌ قَائِظٌ"" : شَدِيدُ الْحَرِّ. 2.""قَيْظٌ قَائِظٌ"" : قَيْظٌ شَدِيدٌ. "', '');
