INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3200, 'مُقَاوِلٌ', 'مقاول', 'اسم فاعل', 'قول', 'مقاول', 'مقل', 'فا. من قَاوَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من قَاوَلَ). ""مُقَاوِلُ بِنَاءٍ"" : الْمُتَعَهِّدُ بِإِنْجَازِ بِنَاءٍ أَوْ مَشَارِيعَ عُمْرَانِيَّةٍ حَسَبَ عَقْدٍ، أَي اتِّفَاقٌ بَيْنَهُ وبَيْنَ صَاحِبِ الْمَشْرُوعِ على أجْرٍ مُحَدَّدٍ وَأَجَلٍ مُسَمَّى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3201, 'مُقَاوِمٌ', 'مقاوم', 'اسم فاعل', 'قوم', 'مقاوم', 'مقم', 'فا. من قَاوَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من قَاوَمَ). 1. ""مُقَاوِمُ الشَّيْءِ"" : مُوَاجِهُهُ لَهُ بِمَا يَلْزَمُ. 2.""مُقَاوِمٌ أَظْهَرَ بَسَالَةً ضِدَّ قُوَّاتِ الاِحْتِلاَلِ"" : الْمُوَاجِهُ لَهَا بِالسِّلاَحِ، الْمُجَاهِدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3202, 'قَابِضٌ', 'قابض', 'اسم فاعل', 'قبض', 'قابض', 'قبض', 'فا. من قَبَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من قَبَضَ). ""قَابِضٌ عَلَى زِمَامِ الْمِقْوَدِ"" : مَاسِكٌ بِهِ."', '');
