INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3244, 'قَاذِفٌ', 'قاذف', 'اسم فاعل', 'قذف', 'قاذف', 'قذف', 'فَا. من قَذَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":قَوَاذِفُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. من قَذَفَ). 1.""قَاذِفُ الْكُرَةِ"" : الَّذِي يَرْمِي بِهَا. 2.""قَاذِفَةُ النَّارِ"" : الآلَةُ الَّتِي تَقْذِفُ النَّارَ بِقُوَّةٍ شَدِيدَةٍ. ""ق"', '');
