INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3246, 'قَارِي', 'قاري', 'اسم فاعل', 'قرر', 'قاري', 'قر', 'فا. من قَرَا.', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":قُرَاةٌ:قَوَارٍ:القَوَارِي"', '', '', '', '', '', '', '', '', '"ج: ون، قُرَاةٌ، قَوَارٍ، القَوَارِي. (فا. من قَرَا). 1.""هُمْ مِنْ قُرَاةِ البِلاَدِ"" : مِنْ سَاكِنِي القُرَى. 2.""فَارِ"', '');
