INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3248, 'قَارٌّ', 'قار', 'اسم فاعل', 'قرر', 'قار', 'قر', 'فا. من قَرَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"قَارٌّ، ةٌ - [ق ر ر]. (فا. من قَرَّ). 1.""يَوْمٌ قَارٌّ"" : بَارِدٌ.    ""قَضَى لَيْلَةً قَارَّةً"". 2.""غَضَبٌ قَارٌّ"" : شَدِيدُ الغَضَبِ. ""يَصُبُّ قَارَّ غَضَبِهِ عَلَى الأَرْضِ"". (غسان كنفاني). 3.""قَارٌّ فِي بَيْتِهِ"" : مُسْتَقِرٌّ.   ""لَهُ دَخْلٌ قَارٌّ"". 4.""لَجْنَةٌ قَارَّةٌ"" : دَائِمَةٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3249, 'قوار', 'قوار', 'اسم فاعل', '', 'قوار', 'قر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
