INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3256, 'قَارِسٌ', 'قارس', 'اسم فاعل', 'قرس', 'قارس', 'قرس', 'فَا. من قَرَسَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"قَارِسٌ-قَارِسٌ، ةٌ [ق ر س] (فَا. من قَرَسَ). ""بَرْدٌ قَارِسٌ"" : شَدِيدُ الْبُرُودَةِ."', '');
