INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3259, 'مُقَرِّبٌ', 'مقرب', 'اسم فاعل', 'قرب', 'مقرب', 'مقرب', 'فا. من قَرَّبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُقَرِّبٌ-مُقَرِّبٌ، ةٌ [ق ر ب] (فا. من قَرَّبَ). 1.""مُقَرِّبُ البَعِيدِ"" : مَنْ يَجْعَلُ البَعِيدَ قَرِيباً. 2.""عَدَسَةٌ مُقَرِّبَةٌ"" : عَدَسَةٌ لاَمَّةٌ، أَيْ تُقَرِّبُ الأَشْيَاءَ فِي نُقْطَةٍ مُرَكَّزَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3260, 'قَارِحٌ', 'قارح', 'اسم فاعل', 'قرح', 'قارح', 'قرح', 'فا. من قَرَحَ', '', 'Ta', 'مفرد', 'DnT', '', '', '"قَوَارِحُ:قُرَّحٌ"', '', '', '', '', '', '', '', '', '"قَارِحٌ، ةٌ - ج: قَوَارِحُ، قُرَّحٌ. [ق ر ح]. (فا. من قَرَحَ). 1.""حَافِرٌ قَارِحٌ"" : شُقَّتْ نَابُهُ وَطَلَعَتْ بَعْدَ بُلُوغِهِ الْخَامِسَةَ. 2.""قَارِحُ الفَرَسِ"" : نَابُهُ وَلِكُلِّ ذِي حَافِرٍ قَارِحَانِ عُلْوِيَّانِ، وَقَارِحَانِ سُفْلِيَّانِ. "', '');
