INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3265, 'مُقَرِّرٌ', 'مقرر', 'اسم فاعل', 'قرر', 'مقرر', 'مقر', 'فا. من قَرَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من قَرَّرَ). ""مُقَرِّرُ الاجْتِمَاعِ"" : عُضْوٌ مِنَ الأَعْضَاءِ الْمُجْتَمِعِينَ يُعْه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3266, 'مُقَرْفِصٌ', 'مقرفص', 'اسم فاعل', 'قرفص', 'مقرفص', 'مقرفص', 'فا. من قَرْفَصَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من قَرْفَصَ). ""جَلَسَ مُقَرْفِصاً"" : جَلَسَ شَادّاً يَدَيْهِ تَحْتَ رِجْلَيْهِ. ""ظَلَّتِ الأُمُّ مُقَرْفِصَةً تُطِلُّ عَلَيْهِ بِنَظَرَاتٍ شَاخِصَةٍ مَعَ أَنَّهُ كَانَ وَاقِفاً فَوْقَهَا كَالطَّوْدِ"". (إميل حبيبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3267, 'قوارس', 'قوارس', 'اسم فاعل', '', 'قوارس', 'قرس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
