INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3376, 'قَاوِي', 'قاوي', 'اسم فاعل', 'قوي', 'قاوي', 'ق', 'فا. من قَوِيَ', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"قَاوٍ-قَاوٍ، القَاوِي، ةٌ [ق و ي] (فا. من قَوِيَ). 1.""جَاءَ قَاوِياً"" : طاوِياً، جَائِعاً. 2.""سَنَةٌ قَاوِيَةٌ"" : قَلِيلَةُ الْمَطَرِ. 3.""بَلَدٌ قاوٍ"" : لَيْسَ فِيهِ أَحَدٌ."', '');
