INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3379, 'قَاهِرٌ', 'قاهر', 'اسم فاعل', 'قهر', 'قاهر', 'قهر', 'فا. من قَهَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ونَ:ات:قَوَاهِرُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من قَهَرَ). 1.""جَبَلٌ قَاهِرٌ"" : شَامِخٌ، عَالٍ. 2.""سَبَبٌ قَاهِرٌ"" : غَالِبٌ. ""أَسْبَابٌ قَاهِرَةٌ"". 3.""الْقَاهِرَةُ"" : عَاصِمَةُ جُمْهُورِيَّةِ مِصْرَ الْعَرَبِيَّةِ."', '');
