INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3383, 'مُقَوِّضٌ', 'مقوض', 'اسم فاعل', 'قوض', 'مقوض', 'مقض', 'فا. من قَوَّضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من قَوَّضَ). ""مُقَوِّضُ البُنْيَانِ"" : مُهَدِّمُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3384, 'مُقَوْلِبٌ', 'مقولب', 'اسم فاعل', 'قولب', 'مقولب', 'مقلب', 'فا. من قَوْلَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من قَوْلَبَ). ""مُقَوْلِبُ الْمَنْحُوتَاتِ"" : مَنْ يُفْرِغُ مَصْنُوعَاتِ النَّحَّاتِ فِي قَوَالِبَ، سَبَّاكٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3385, 'مُقَوِّمٌ', 'مقوم', 'اسم فاعل', 'قوم', 'مقوم', 'مقم', 'فا. من قَوَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من قَوَّمَ). 1.""مُقَوِّمُ الأَعْمَالِ الفَنِّيَّةِ"" : مَنْ يُعْطِيهَا قِيمَةً بِالبَحْثِ عَنْ خَصَائِصِهَا. 2.""أَجْزَاءٌ مُقَوِّمَةٌ"": مُكَوِّنَةٌ. 3.""مُقَوِّمَاتُ الْحَيَاةِ"" : عَنَاصِرُهَا وعَوَامِلُهَا الأَسَاسِيَّةُ الَّتِي بِهَا تَقُومُ. ""مُقَوِّمَاتُ العُمْرَانِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3386, 'كوابي', 'كوابي', 'اسم فاعل', '', 'كوابي', 'كب', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3387, 'مُقَوِّي', 'مقوي', 'اسم فاعل', 'قوي', 'مقوي', 'مق', 'فا. من قَوَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُقَوٍّ-مُقَوٍّ، الْمُقَوِّي، ةٌ [ق و ي] (فا. من قَوَّى). 1. ""دَوَاءٌ مُقَوٍّ"" : مُنْعِشٌ يَبْعَثُ فِي الذَّاتِ قُوَّةً وحَرَكَةً. 2. ""مُقَوِّي الصَّوْتِ"" : ""مُكَبِّرُهُ""، مُضَخِّمُهُ. 3. ""مُقَوِّي الشَّيْء"" : مُدَعِّمٌ، مُعَزِّزٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3388, 'مُقَيِّدٌ', 'مقيد', 'اسم فاعل', 'قيد', 'مقيد', 'مقد', 'فا. من قَيَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من قَيَّدَ). ""قَانُونٌ مُقَيِّدٌ لِلْحُرِّيَّةِ"" : قَانُونٌ يَحُدُّ مِنَ الْحُرِّيَّةِ ويَجْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3389, 'كَائِدٌ', 'كائد', 'اسم فاعل', 'كيد', 'كاءد', 'كد', 'فا. من كَادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(فا. من كَادَ). ""كَائِدٌ مَاكِرٌ"" : مَنْ يَكِيدُ الكَيْدَ، الْمُتَآمِرُ. ""اللَّهُ هُوَ الكَفِيلُ بِرَدِّ كَيْدِ الكَائِدِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3390, 'كوائد', 'كوائد', 'اسم فاعل', '', 'كواءد', 'كد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3391, 'مُكَافِئٌ', 'مكافئ', 'اسم فاعل', 'كفأ', 'مكافء', 'مكف', 'فا. من كَافَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من كَافَأَ). ""مُكَافِئٌ كَلَّ ذِي حَقٍّ حَقَّهُ"" : مُجَازٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3392, 'مُكَافِحٌ', 'مكافح', 'اسم فاعل', 'كفح', 'مكافح', 'مكفح', 'فا. من كَافَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من كَافَحَ). ""مُكَافِحٌ فِي سَبِيلِ تَحْرِيرِ بِلاَدِهِ"" : مُقَاتِلٌ، مُنَاضِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3393, 'كَائِنٌ', 'كائن', 'اسم فاعل', 'كون', 'كاءن', 'كن', 'فا. من كَانَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":كَوَائِنُ"', '', '', '', '', '', '', '', '', '"(فا. من كَانَ). 1.""الإِنْسَانُ كَائِنٌ حَيٌّ"" : مَوْجُودٌ حَيٌّ. 2.""اللُّغَةُ كَائِنٌ حَيٌّ"" : أَيْ لَهَا وُجُودٌ مِثْلُ وُجُودِ كُلِّ الْمَوْجُودَاتِ الْحَيَّةِ، تَنْمُو وَتَتَطَوَّرُ. 3.""المَحَلُّ التِّجَارِيُّ كَائِنٌ فِي آخِرِ الشَّارِعِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3394, 'كَوَائِنُ', 'كوائن', 'اسم فاعل', '', 'كواءن', 'كن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3395, 'كَابِي', 'كابي', 'اسم فاعل', 'كبو', 'كابي', 'كب', 'فا. من كَبَا', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"كَابٍ-كَابٍ، الكَابِي، ةٌ [ك ب و] (فا. من كَبَا). 1.""تُرَابٌ كَابٍ"" : لاَ يَسْتَقِرُّ عَلَى وَجْهِ الأَرْضِ. 2.""هُوَ كَابِي الرَّمَادِ"" : أَيْ عَظِيمُ الرَّمَادِ، كِنَايَةً عَنْ كَرَمِهِ وَحُسْنِ ضِيَافَتِهِ، مِضْيَافٌ. 3.""فَحْمٌ كَابٍ"" : خَمَدَتْ نَارُهُ. 4.""نَارٌ كَابِيَةٌ"" : نَارٌ مُغَطَّاةٌ بِرَمَادٍ، أَيْ أَنَّ جَمْرَهَا لَمْ يَنْطَفِئْ بَعْدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3396, 'مُكَبِّرٌ', 'مكبر', 'اسم فاعل', 'كبر', 'مكبر', 'مكبر', 'فـا. من كَبَّـرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُكَبِّرٌ-مُكَبِّرٌ، ةٌ [ك ب ر] (فـا. من كَبَّـرَ). 1. ""مُكَبِّـرُالصَّوْتِ"" : <جِهَازٌ يُضَخِّمُ الصَّوْتَ ويَجْعَلُهُ مَسْمُوعاً جِدّاً. 2.""نَظَّارَاتٌ مُكَبِّرَةٌ"" : نَظَّارَاتٌ تَجْعَلُ الْمَرْئِيَّات كَبِيرَةً وَاضِحَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3397, 'كَابِرٌ', 'كابر', 'اسم فاعل', 'كبر', 'كابر', 'كبر', 'فا. من كَبَرَ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"كَابِرٌ - [ك ب ر]. (فا. من كَبَرَ). 1.""هُوَ كَابِرُ قَوْمِهِ"" : كَبِيرُهُمْ، صَاحِبُ مَكَانَةٍ وَشَأْنٍ. 2.""تَوَارَثُوا الْمَجْدَ كَابِراً عَنْ كَابِرٍ"" : تَوَارَثُوهُ أَباً عَنْ جَدٍّ. 3.""يُرْجَعُ إِلَى الكَابِرِ فِي شَتَّى الأُمُورِ"" : الْجَدُّ الأَكْبَر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3398, 'كَابِسٌ', 'كابس', 'اسم فاعل', 'كبس', 'كابس', 'كبس', 'فا. من كَبَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"كَابِسٌ-كَابِسٌ، ةٌ [ك ب س] (فا. من كَبَسَ). 1.""أَرْنَبَةُ الأَنْفِ الكَابِسَةُ"" : أَيِ الْمُشْرِفَةُ عَلَى الشَّفَةِ العُلْيَا. 2.""نَاصِيَةٌ كَابِسَةٌ"" : مُقْبِلَةٌ عَلَى الْجَبْهَةِ."', '');
