INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3492, 'كَامِدٌ', 'كامد', 'اسم فاعل', 'كمد', 'كامد', 'كمد', 'فا. من كَمَدَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"كَامِدٌ-كَامِدٌ، ةٌ [ك م د] (فا. من كَمَدَ). ""وُجُوهٌ جَامِدَةُ التَّعَابِيرِ كَامِدَةُ النَّظَرِ"" : حَزِينَةٌ، مُتَغَيِّرَةٌ."', '');
