INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3494, 'مُكَمِّلٌ', 'مكمل', 'اسم فاعل', 'كمل', 'مكمل', 'مكمل', 'فا. من كَمَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من كَمَّلَ). 1.""عَمَلٌ مُكَمِّلٌ"" : مُتَمِّمٌ. 2. ""الْمُكَمِّلاَتُ فِي اللُّغَةِ"" : أَلْفَاظٌ تَكْمِيلِيَّةٌ تُوضَعُ بِجَانِبِ أَلْفَاظٍ أَسَاسِيَّةٍ فِي الجُمْلَةِ، مِثْلُ الضَّمَائِرِ وأَدَوَاتِ التَّنْكِيرِ وَأَسْماءِ الإِشارَةِ أَحْيَاناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3495, 'كَامِلٌ', 'كامل', 'اسم فاعل', 'كمل', 'كامل', 'كمل', 'فا. من كَمَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":كَمَلَةٌ"', '', '', '', '', '', '', '', '', '"(فا. من كَمَلَ). 1.""رَجُلٌ كَامِلٌ"" : لَهُ مُجْمَلُ الصِّفَاتِ الْحَمِيدَةِ. 2.""يَتَمَتَّعُ بِكَامِلِ قُوَّتِهِ العَقْلِيَّةِ"" : جَامِعٌ، مَالِكٌ لَهَا. 3.""كَامِلُ العُضْوِيَّةِ فِي الجَمْعِيَّةِ"" : لَهُ مُجْمَلُ الصِّفَاتِ واَلحُقُوقِ لِتَمَامِ عُض"', '');
