INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3513, 'مُكَوِّنٌ', 'مكون', 'اسم فاعل', 'كون', 'مكون', 'مكن', 'فا. من كَوَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من كَوَّنَ). 1.""مُكَوِّنُ الطُّلاَّبِ"" : مَنْ يُكَوِّنُهُمْ التَّكْوِينَ العِلْمِيَّ والتَّرْبَوِيَّ. 2.""مُكَوِّنَاتُ الْحَيَاةِ"" : عَنَاصِرُهَا، مُقَوِّمَاتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3514, 'مُكَيِّفٌ', 'مكيف', 'اسم فاعل', 'كيف', 'مكيف', 'مكف', 'فا. من كَيَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من كَيَّفَ). ""مُكَيِّفُ الْهَوَاءِ"" : جِهَازٌ آلِيٌّ خَاضِعٌ لِقُوَّةٍ كَهْرَبَائِيَّةٍ تَعْمَلُ عَلَى إِحْدَاثِ دَرَجَةٍ حَرَارِيَّةٍ مُعَيَّنَةٍ فِي البُيُوتِ أَوِ الإِدَارَاتِ أو القِطَاعَاتِ الصِّناعِيَّةِ أو الطَّائِرَاتِ مُخَالِفَةٍ لِلطَّقْسِ السَّائِدِ صَيْفاً أو شِتَاءً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3515, 'مُلاَئِمٌ', 'ملائم', 'اسم فاعل', 'لأم', 'ملاءم', 'ملم', 'فا. من لاءمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُلاَئِمٌ-مُلاَئِمٌ، ةٌ [ل أ م]. 1. (فا. من لاءمَ). ""عَمَلٌ مُلاَئِمٌ"": مُوَافِقٌ، مُنَاسِبٌ، مُنْسَجِمٌ. ""جَوٌّ مُلاَئِمٌ"" ""أَفْكَارٌ مُلاَئِمَةٌ"" ""عِبَارَةٌ مُلاَئِمَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3516, 'لاَئِمٌ', 'لائم', 'اسم فاعل', 'لوم', 'لاءم', 'لم', 'فا. من لاَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"لاَئِمٌ-لاَئِمٌ، ةٌ ـون، ـات. [ل و م] (فا. من لاَمَ). ""جَاءَ لاَئِماً"" : عَاتِباً. ""جَاءتْهُ لاَئِمَةً"" ""يَا لاَئِمِي فِي حُبِّ النَّاسِ"" ""رُبَّ لَائِمٍ مَلُومٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3517, 'مُلاَحِقٌ', 'ملاحق', 'اسم فاعل', 'لحق', 'ملاحق', 'ملحق', 'فا. من لاَحَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من لاَحَقَ). ""مُلاَحِقُ الشَّيْءِ"" : مُتَابِعٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3518, 'مُلاَزِمٌ', 'ملازم', 'اسم فاعل', 'لزم', 'ملازم', 'ملزم', 'فا. من لاَزَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من لاَزَمَ). 1. ""الصِّدْقُ مُلاَزِمُ الْعَمَلِ"" : مُرْتَبِطٌ، مُتَعَلِّقٌ بِهِ. ""مُلاَزِمُهُ مِثْلَ ظِلِّهِ"". 2.""نَاسِكٌ مُلاَزِمٌ لِلْعِبَادَةِ"" : مُدَاو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3519, 'مُلاَصِقٌ', 'ملاصق', 'اسم فاعل', 'لصق', 'ملاصق', 'ملصق', 'فا. من لاَصَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من لاَصَقَ). ""بَيْتُهُ مُلاَصِقٌ لِبَيْتِنَا"" : مُجَاوِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3520, 'مُلاَطِفٌ', 'ملاطف', 'اسم فاعل', 'لطف', 'ملاطف', 'ملطف', 'فا. من لاَطَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من لاَطَفَ). ""وَلَدٌ مُلاَطِفٌ"" : مُدَاعِبٌ، مُصَانِعٌ."', '');
