INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3625, 'لاَهِي', 'لاهي', 'اسم فاعل', 'لهو', 'لاهي', 'له', 'فَا. من لَهَا.', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"ج: ون، ـات. (فَا. من لَهَا). ""فَلَمْ يَزَلْ لاَهِياً غَافِلاً حَتَّى هَلَكَ"" : مُتَسَلٍّ. ""يَلْهُو مَعَ اللاَّهِينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3626, 'مُلَوِّنٌ', 'ملون', 'اسم فاعل', 'ملن', 'ملون', 'ملن', 'فا. من لَوَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُلَوِّنٌ-مُلَوِّنٌ، ةٌ [م ل ن] (فا. من لَوَّنَ). ""قَلَمٌ مُلَوِّنٌ"" : أَيْ يَحْتَوِي عَلَى مَادَّةٍ صِبَاغِيَّةٍ ."', '');
