INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3637, 'مُلَيِّنٌ', 'ملين', 'اسم فاعل', 'لين', 'ملين', 'ملن', 'فا. من لَيَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُلَيِّنٌ-مُلَيِّنٌ، ةٌ [ل ي ن] (فا. من لَيَّنَ). 1.""مُلَيِّنُ الْحَدِيدِ"" : مَنْ يَجْعَلُهُ لَيِّناً مَرِناً. 2.""دَوَاءٌ مُلَيِّنٌ"" : مُسَهِّلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3638, 'مَائِتٌ', 'مائت', 'اسم فاعل', 'موت', 'ماءت', 'مت', 'فا. من مَاتَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من مَاتَ). 1.""مَائِتٌ لاَ مَحَالَةَ"" : مَنْ قَارَبَ أَنْ يَمُوتَ. 2.""مَوْتٌ مَائِتٌ"" : مَوْتٌ فَظِيعٌ."', '');
