INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3641, 'مَائِجٌ', 'مائج', 'اسم فاعل', 'موج', 'ماءج', 'مج', 'فَا. مِنْ مَاجَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَائِجٌ-مَائِجٌ، ةٌ [م و ج] (فَا. مِنْ مَاجَ). 1.""بَحْرٌ مَائِجٌ"" : أَمْوَاجُهُ مُرْتَفِعَةٌ مُضْطَرِبَةٌ. 2.""مُعْتَرَكٌ مَائِجٌ"" : مُضْطَرِبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3642, 'موائج', 'موائج', 'اسم فاعل', '', 'مواءج', 'مج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3643, 'مُمَاحِكٌ', 'مماحك', 'اسم فاعل', 'محك', 'مماحك', 'ممحك', 'فا. من مَاحَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من مَاحَكَ). ""اِمْرَأَةٌ مُمَاحِكَةٌ"" : مُشَاكِسَةٌ، مُثِيرَةٌ لِلْمَشَاكِلِ. ""رِجَالٌ مُمَاحِكُونَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3644, 'مَائِدٌ', 'مائد', 'اسم فاعل', 'ميد', 'ماءد', 'مد', 'فا. من مَادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَيْدَى"', '', '', '', '', '', '', '', '', '"(فا. من مَادَ). 1.""غُصْنٌ مَائِدٌ"" : مَائِلٌ. 2.""هُوَ مَائِدٌ"" : مَنْ يُصِيبُهُ دُوَارٌ مِنْ رُكُوبِ الطَّائِرَةِ أَوِ البَحْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3645, 'مَيْدَى', 'ميدى', 'اسم فاعل', '', 'ميدى', 'مد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3646, 'أَمْجَادٌ', 'أمجاد', 'اسم فاعل', '', 'ءمجاد', 'مجد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3647, 'مُمَارِسٌ', 'ممارس', 'اسم فاعل', 'مرس', 'ممارس', 'ممرس', 'فا. من مَارَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من مَارَسَ). ""عامِلٌ مُمَارِسٌ"" : مُتَدَرِّبٌ، مُتَعَوِّدٌ مُزَاوَلَةَ عَمَلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3648, 'مُمَاطِلٌ', 'مماطل', 'اسم فاعل', 'مطل', 'مماطل', 'ممطل', 'فا. من مَاطَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من مَاطَلَ). ""مُمَاطِلُ الدَّيْنِ"" : مُسَوِّفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3649, 'مَائِعٌ', 'مائع', 'اسم فاعل', 'ميع', 'ماءع', 'مع', 'فا. من مَاعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من مَاعَ). 1.""صَارَ الثَّلْجُ مَائِعاً"" : سَائِلاً، ذَائِباً. ""مَادَّةٌ مَائِعَةٌ"". 2.""مَائِعُ التَّصَرُّفِ"" : بَلِيدُ التَّصَرُّفِ، فَاتِرٌ، مُسْتَهْتِرٌ، أَهْوَجُ، أَحْمَقُ. ""تَصَرُّفٌ مَائِعٌ"" ""أَطْلَقَ ضَحْكَةً مَائِعَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3650, 'موائع', 'موائع', 'اسم فاعل', '', 'مواءع', 'مع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3651, 'مَائِلٌ', 'مائل', 'اسم فاعل', 'ميل', 'ماءل', 'مل', 'فا. من مال', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَوَائِلُ"', '', '', '', '', '', '', '', '', '"(فا. من مال). 1.""جِدَارٌ مَائِلٌ"" : مُنْحَنٍ، أَيْ لَمْ يَعُدْ قَائِماً مُسْتَوِياً كَمَا كَانَ. ""خَطٌّ مَائِلٌ"". 2.""خَرَجَ مِنَ الْمُسْتَشْفَى مَائِلاً إِلَى الشِّفَاءِ"" : مُتَّجِهاً نَحْوَ الشِّفَاءِ. ""لَوْنٌ مَائِلٌ إِلَى الصُّفْرَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3652, 'مَوَائِلُ', 'موائل', 'اسم فاعل', '', 'مواءل', 'مل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3653, 'مُمَالِقٌ', 'ممالق', 'اسم فاعل', 'ملق', 'ممالق', 'مملق', 'فا. من مَالَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ـ:"', '', '', '', '', '', '', '', '', '"(فا. من مَالَقَ). ""رًَجُلٌ مُمَالِقٌ"" : مُتَوَدِّدٌ بِلِسَانِهِ بِمَا لَيْسَ فِي قَلْبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3654, 'مُمَثِّلٌ', 'ممثل', 'اسم فاعل', 'مثل', 'ممثل', 'ممثل', 'فا. من مَثَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من مَثَّلَ). 1.""مُمَثِّلٌ مَسْرَحِيٌّ"" : مَنْ يَقُومُ بِدَوْرِ تَمْثِيلِيٍّ فِي مَسْرَحِيَّةٍ. ""مُمَثِّلٌ سِينَمَائِيّ"". 2.""مُمَثِّلٌ تِجَارِيٌّ"" : الوَكِيلُ. 3.""مُمَثِّلٌ دِيبْلُومَاسِيٌّ"" : الْمَبْعُوثُ مِنْ حُكُومَتِهِ إِلَى بِلاَدٍ أَجْنَبِيَّةٍ لِيَرْعَى مَصَالِحَ بِلاَدِهِ عِنْدَهَا، وَالسَّاهِرُ عَلَى تَحْسِينِ العَلاَقَاتِ بَيْنَهُمَا وتَوْطِيدِهَا وتَنْمِيَتهَا. 4.""مُمَثِّلُو الأُمَّةِ فِي البَرْلَمَانِ"" : النُّوَّابُ، أَيْ الَّذِينَ انْتَخَبَهُمُ الشَّعْبُ لِيُمَثِّلُوهُ فِي البَرْلَمَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3655, 'مَاجِدٌ', 'ماجد', 'اسم فاعل', 'مجد', 'ماجد', 'مجد', 'فَا. مِنْ مَجَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":أَمْجَادٌ:مَوَاجِدُ"', '', '', '', '', '', '', '', '', '"(فَا. مِنْ مَجَدَ). 1.""مَاجِدٌ فِي مُلْكِهِ"" : ذُو الْمَجْدِ، شَرِيفٌ، خَيِّرٌ. ""اِمْرَأَةٌ مَاجِدَةٌ"". 2.""اِسْمُهُ مَاجِدٌ"" : اِسْمُ عَلَمٍ مُذَكَّر وَالْمُؤَنَّثُ مَاجِدَة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3656, 'محاق', 'محاق', 'اسم فاعل', '', 'محاق', 'محق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
