INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3672, 'مَاحِلٌ', 'ماحل', 'اسم فاعل', 'محل', 'ماحل', 'محل', 'فا. من مَحَلَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَاحِلٌ-مَاحِلٌ، ةٌ [م ح ل] (فا. من مَحَلَ). ""بَلَدٌ مَاحِلٌ"" : مُجْدِبٌ، أَيِ انْقَطَعَ عَنْهُ الْمَطَرُ، فَيَبِسَتْ أَرْضُهُ."', '');
