INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3674, 'مَادِحٌ', 'مادح', 'اسم فاعل', 'مدح', 'مادح', 'مدح', 'فا. من مدح', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من مدح). 1.""جَاءهُ مَادِحاً"" : مُثْنِياً عَلَيْهِ، أَيْ مُبْرِزاً مَزَايَاهُ وَفَضاَئِلَهُ. 2.""كَانَ مِنْ بَيْنِ الْمَادِحِينَ"" : مَنْ يُنْشِدُ الأَمداحَ النَّبوِيَّةَ، أي القَصَائِدَ الشِّعْرِيَّةَ فيِ مَدْحِ الرَّسُولِ (. ""صَدَحَتْ أَصْوَاتُ الْمَادِحِينَ وَالْمُرَتِّلِينَ تَتَنَاوَبُ مَعَ مَقَاطِعِ الْمُوسِيقَى الأَنْدَلُسِيَّةِ"". (محمد برادة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3675, 'موادح', 'موادح', 'اسم فاعل', '', 'موادح', 'مدح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3676, 'مُمَرِّنٌ', 'ممرن', 'اسم فاعل', 'مرن', 'ممرن', 'ممرن', 'فا. من مَرَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من مَرَّنَ). ""مُمَرِّنُ الفَرِيقِ"" : مُدَرِّبُهُ."', '');
