INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3678, 'مُمَدِّدٌ', 'ممدد', 'اسم فاعل', 'مدد', 'ممدد', 'ممد', 'فا. من مَدَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُمَدِّدٌ-مُمَدِّدٌ، ةٌ [م د د] (فا. من مَدَّدَ). ""مُمَدِّدُ مَعْدِنٍ"" : مُوَسِّعُهُ، مُطَوِّلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3679, 'مُمَدِّنٌ', 'ممدن', 'اسم فاعل', 'مدن', 'ممدن', 'ممدن', 'فا. من مَدَّنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من مَدَّنَ). ""رَجُلٌ مُمَدِّنٌ"" : أَيْ يَعْمَلُ مِنْ أَجْلِ التَّحَضُّرِ وَالْمَدَنِيَّةِ. ""اِدَّعَى أَنَّهُ جَاءَ مُمَدِّناً لِلشُّعُوبِ الْمُتَخَلِّفَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3680, 'مُمَرِّضٌ', 'ممرض', 'اسم فاعل', 'مرض', 'ممرض', 'ممرض', 'فا. من مَرَّضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من مَرَّضَ). ""وَقَفَ الْمُمَرِّضُ بِجَانِبِ الطَّبِيبِ"" : مَنْ يُسَاعِدُ الطَّبِيبَ ويُعْنَى بِالْمَرْضَى. ""اِعْتَبَرَ وُقُوفَ الْمُمَرِّضَةِ بِجَانِبِ سَرِيرِهِ كَأَنَّهَا مَلاَكٌ مِنْ مَلاَئِكَةِ الرَّحْمَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3681, 'مُمَرِّقٌ', 'ممرق', 'اسم فاعل', 'مرق', 'ممرق', 'ممرق', 'فا. من مَرَّقَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَرِّقٌ-مُمَرِّقٌ، ةٌ [م ر ق] (فا. من مَرَّقَ). ""لَحْمٌ مُمَرَّقٌ"" : أَيْ فِيهِ شَحْمٌ كَثِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3682, 'مَارِقٌ', 'مارق', 'اسم فاعل', 'مرق', 'مارق', 'مرق', 'فا. من مَرَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مُرَّاقٌ"', '', '', '', '', '', '', '', '', '"(فا. من مَرَقَ). 1.""مَارِقٌ عَنِ الدِّينِ"" : خَارِجٌ عَنْهُ، مُلْحِدٌ، كَافِرٌ. 2.""سَهْمٌ مَارِقٌ"" : نَافِذٌ إِلَى هَدَفِهِ مِنْهُ دُونَ اعْوِجَاجٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3683, 'مُرَّاقٌ', 'مراق', 'اسم فاعل', '', 'مراق', 'مرق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
