INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3693, 'مَاسِحٌ', 'ماسح', 'اسم فاعل', 'مسح', 'ماسح', 'مسح', 'فا. من مَسَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من مَسَحَ). 1.""رَجُلٌ مَاسِحٌ"" : كَذَّابٌ. 2.""مَاسِحُ الأَحْذِيَةِ"" : مَنْ يَمْسَحُهَا وَيُلَمِّعُ جِلْدَهَا."', '');
