INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3697, 'مَاسِكٌ', 'ماسك', 'اسم فاعل', 'مسك', 'ماسك', 'مسك', 'فا. من مَسَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من مَسَكَ). ""مَاسِكٌ لِلْمِقْوَدِ"" : قَابِضٌ، آخِذٌ. ""مَاسِكٌ بِزِمَامِ الأُمُورِ""."', '');
