INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3701, 'مَاشِطٌ', 'ماشط', 'اسم فاعل', 'مشط', 'ماشط', 'مشط', 'فَا. مِنْ مَشَطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَوَاشِطُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ مَشَطَ). 1.""مَاشِطُ الشَّعْرِ"" : مُسَرِّحُهُ. 2. ""اِهْتَمَّتِ الْمَاشِطَةُ بِالعَرُوسِ"" : الْمَرْأَةُ الْمُكَلَّفَةُ بِتَمْشِيطِ شَعْرِ النِّسَاءِ، وَتَتَّخِذُ ذَلِكَ مِهْنَةً لَهَا. ""وَانْدَفَعَ العَرِيسُ إِلَى بَابِ الغُرْفَةِ لِتَسْتَلِمَهُ الْمَاشِطَةُ مُشَجِّعَةً مُزَغْرِدَةً"".(ع. غلاب) ""مَاذَا تَصْنَعُ الْمَاشِطَةُ مَعَ العُرُوسِ القَرْعَاءِ"". (حنا مينه)."', '');
