INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3705, 'مَاشِي', 'ماشي', 'اسم فاعل', 'مشي', 'ماشي', 'مش', 'فا. من مَشَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مُشَاةٌ"', '', '', '', '', '', '', '', '', '"(فا. من مَشَى). 1.""ظَلَّ مَاشِياً"" : سَائِراً عَلَى رِجْلَيْهِ. ""كَانَ يَقْطَعُ الْمَسَافَةَ مَاشِياً عَلَى الأَقْدَامِ"". 2.""اِسْتَعْرَضَ فِرْقَةً مِنَ الْمُشَاةِ"" (عَسْك) : فِرْقَةً مِنَ العَسْكَرِ يَمْشُونَ عَلَى أَقْدَامِهِمْ. ""سِلاَحُ الْمُشَاةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3706, 'مُشَاةٌ', 'مشاة', 'اسم فاعل', '', 'مشاة', 'مشة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
