INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3708, 'مَاضِي', 'ماضي', 'اسم فاعل', 'مضي', 'ماضي', 'مض', 'فا. من مَضَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَوَاضٍ"', '', '', '', '', '', '', '', '', '"(فا. من مَضَى). 1.""حَدَثَ هَذَا فِي الزَّمَنِ الْمَاضِي"" : فيِ الزَّمَنِ الْمُنْصَرِمِ الَّذِي انْقَضَى. ""فِي الشَّهْرِ الْمَاضِي"" ""السَّنَوَاتُ الْمَاضِيَةُ"". 2.""خَرَجَ"" : فِعْلٌ مَاضٍ، أَيْ يَدُلُّ عَلَى مَا قَبْلَ الزَّمَانِ الَّذِي أَنْتَ فِيهِ وَضْعاً، حَالاً. 3.""سَيْفٌ مَاضٍ"" : سَيْفٌ حَادٌّ، قَاطِعٌ. ""سُيُوفٌ مَوَاضٍ"". 4.""هُوَ مَاضِي العَزِيمَةِ"" : حَازِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3709, 'مضاة', 'مضاة', 'اسم فاعل', '', 'مضاة', 'مضة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
