INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3711, 'مَاطِرٌ', 'ماطر', 'اسم فاعل', 'مطر', 'ماطر', 'مطر', 'فا. من مَطَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَاطِرٌ-مَاطِرٌ، ةٌ [م ط ر] (فا. من مَطَرَ). ""يَوْمٌ مَاطِرٌ"" : مَطيرٌ، ذُو مَطَرٍ. ""لَيْلَةُ مَاطِرَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3712, 'مواطر', 'مواطر', 'اسم فاعل', '', 'مواطر', 'مطر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3713, 'مُمَغْنِطٌ', 'ممغنط', 'اسم فاعل', 'مغنط', 'ممغنط', 'ممغنط', 'فا. من مَغْنَطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُمَغْنَطٌ-مُمَغْنَطٌ، ةٌ [م غ ن ط] (مفع. من مَغْنَطَ). ""حَدِيدٌ مُمَغْنَطٌ"" : أَيْ يَحْتَوِي عَلَى خَاصِّيَّةِ الْمِغْنَاطِيسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3714, 'مَاكِرٌ', 'ماكر', 'اسم فاعل', 'مكر', 'ماكر', 'مكر', 'فا. من مَكَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَكَرَةٌ"', '', '', '', '', '', '', '', '', '"(فا. من مَكَرَ). ""إِنَّهُ لَرَجُلٌ مَاكِرٌ"" : مُخَادِعٌ، مُرَاوِغٌ.آل عمران آية 54 وَمَكَرُوا وَمَكَرَ اللَّهُ وَالَّلهُ خَيْرُ الْمَاكِرِينَ (قرآن) اِرْتَسَمَتْ عَلَى مُحَيَّاهُ ابْتِسَامَةٌ مَاكِرَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3715, 'مَانِعٌ', 'مانع', 'اسم فاعل', 'منع', 'مانع', 'منع', 'فا. من مَنَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَنَعَةٌ:مَوَانِعُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من مَنَعَ). 1.: البَخِيلُ الْمُمْسِكُ. 2.""كَاَن مَانِعاً لِكُلِّ حَرَكَةٍ"" : ضَابِطاً، مُرَاقِباً لِعَدَمِ وُقُوعِ أَيِّ حَرَكَةٍ. 3.""مَنَعَنِي مَانِعٌ"" : عَائِقٌ، حَاجِزٌ. ""لاَ مَانِعَ عِنْدِي مِنْ أَنْ تُسَافِرَ"" ""لاَ مَانِعَ مِنْ ذَلِكَ"" ""لاَ أَرَى مَانِعاً"". 4.""مَوَانِعُ الزَّوَاجِ"" : عَوَائِقُهُ."', '');
