INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3719, 'مَالِحٌ', 'مالح', 'اسم فاعل', 'ملح', 'مالح', 'ملح', 'فَا. مِنْ مَلَحَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَالِحٌ-مَالِحٌ [م ل ح] (فَا. مِنْ مَلَحَ). 1.""مَاءُ البَحْرِ مَالِحٌ"" : غَيْرُ عَذْبٍ، بِهِ مِلْحٌ. 2.""طَعَامٌ مَالِحٌ"" : مَا كَانَ بِهِ مِلْحٌ زَائِدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3720, 'موالح', 'موالح', 'اسم فاعل', '', 'موالح', 'ملح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3721, 'مَالِكٌ', 'مالك', 'اسم فاعل', 'ملك', 'مالك', 'ملك', 'فَا. مِنْ مَلَكَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":مُلَّكٌ:مُلاَّكٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. مِنْ مَلَكَ). 1.""مَالِكُ البَيْتِ"" : صَاحِبُهُ. 2.""هُوَ الله الْمَالِكُ"" : مِنْ أَسْمَاءِ الله الْحُسْنَى.آل عمران آية 26 قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَنْ تَشَاءُ وَتَنْزِعُ الْمُلْكَ مِمَّنْ تَشَاءُ (قرآن). 3.""عَبْدُ الْمَالِكِ"": اِسْمُ عَلَمٍ مُرَكَّبٌ. 4.""أَبُو مَالِكٍ"" : كُنْيَةُ الكِبَرِ وَالشّيْخُوخَةِ. 5.""مَالِكٌ الْحَزِينُ"" (حو) : طَائِرٌ مَائِيٌّ. ن. بَلَشُونٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3722, 'مُلَّكٌ', 'ملك', 'اسم فاعل', '', 'ملك', 'ملك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
