INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3729, 'مناع', 'مناع', 'اسم فاعل', '', 'مناع', 'منع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3730, 'مُمَهِّدٌ', 'ممهد', 'اسم فاعل', 'مهد', 'ممهد', 'ممهد', 'فا. من مَهَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من مَهَّدَ). 1.""مُمَهِّدٌ لِلْمَوْضُوعِ"" : مُوَطِّئٌ لَهُ، أَيْ جَعَلَ لَهُ تَمْهِيداً. 2.""مُمَهِّدُ الطَّرِيقِ"" : مُسَوِّيهَا. ""مُمَهِّدٌ للأُمُورِ والْمَشَاكِلِ والعَقَبَاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3731, 'مَاهِرٌ', 'ماهر', 'اسم فاعل', 'مهر', 'ماهر', 'مهر', 'فا. من مَهَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":ات:مَهَرَةٌ:"', '', '', '', '', '', '', '', '', '"(فا. من مَهَرَ). ""صَانِعٌ مَاهِرٌ"" : فَنَّانٌ لَهُ قُدْرَةٌ هَائِلَةٌ وَكَفَاءةٌ عالِيَةٌ، فِي مَجَالِ الصِّنَاعَةِ. ""لاَعِبٌ مَاهِرٌ"" ""قَائِدٌ مَاهِرٌ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3732, 'مَهَرَةٌ', 'مهرة', 'اسم فاعل', '', 'مهرة', 'مهرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
