INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3734, 'مهار', 'مهار', 'اسم فاعل', '', 'مهار', 'مهر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3735, 'مُمَوِّلٌ', 'ممول', 'اسم فاعل', 'مول', 'ممول', 'ممل', 'فا. من مَوَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من مَوَّلَ). ""مُمَوِّلُ الْمَشْرُوعِ"" : مَنْ يُنْفِقُ عَلَى الْمَشْرُوعِ، يُمَوِّلُ حَاجَاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3736, 'أَنْدِيَةٌ', 'أندية', 'اسم فاعل', '', 'ءندية', 'ندة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3737, 'مُمَوِّهٌ', 'مموه', 'اسم فاعل', 'موه', 'مموه', 'ممه', 'فا. من مَوَّهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من مَوَّهَ). ""مُمَوِّهٌ مُحْتَالٌ"" : مَنْ يُقَدِّمُ الأَشْيَاءَ عَلَى غَيْرِ حَقِيقَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3738, 'مُمَيِّزٌ', 'مميز', 'اسم فاعل', 'ميز', 'مميز', 'ممز', 'فا. من مَيَّزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من مَيَّزَ). 1.""لَهُ مَلاَمِحُ مُمَيِّزَةٌ"" : لَهُ مَلاَمِحُ ذَاتُ خَصَائِصَ مُعَيَّنَةٍ، فَارِقَةٌ. ""عَلاَمَةٌ مُمَيِّزَةٌ"". 2.""مُمَيِّزٌ بَيْنَ النَّاسِ"" : مَنْ يُحْدِثُ تَمْيِيزاً بَيْنَهُمْ بِسَبَبِ اللَّوْنِ أو الدِّينِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3739, 'نَائِبٌ', 'نائب', 'اسم فاعل', 'نوب', 'ناءب', 'نب', 'فَا. من نَابَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":نُوَّابٌ:"', '', '', '', '', '', '', '', '', '"(فَا. من نَابَ). 1.""تَوَلَّى نَائِبُ الْمُدِيرِ الأَمْرَ"" : مَنْ يَقُومُ مَقَامَ الْمُدِيرِ فِي مُهِمَّةٍ أَوْ عَمَلٍ. ""غَابَ الرَّئِيسُ وَحَضَرَ نَائِبُهُ"". 2.""نَائِبٌ فِي الْبَرْلَمَانِ"" : مُمَثِّلُ جَمَاعَةٍ مِنَ الأُمَّةِ يَنْتَخ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3740, 'نُوَّابٌ', 'نواب', 'اسم فاعل', '', 'نواب', 'نب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3741, 'نوائب', 'نوائب', 'اسم فاعل', '', 'نواءب', 'نب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3742, 'مُنَاجِي', 'مناجي', 'اسم فاعل', 'نجو', 'مناجي', 'منج', 'فا. من نَاجَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من نَاجَى). ""مُنَاجِي الأَرْوَاحِ"" : مُسَارٌّ لَهَا، مُتَخَيِّلٌ لَهَا أَنَّهَا مُجَسَّدَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3743, 'نَائِحٌ', 'نائح', 'اسم فاعل', 'نوح', 'ناءح', 'نح', 'فا. مِنْ نَاحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":نَوَائِحُ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ نَاحَ). ""خَرَجَتْ نَائِحَةً بَعْدَ أَنْ فَاضَتْ رُوحُ زَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3744, 'نَوَائِحُ', 'نوائح', 'اسم فاعل', '', 'نواءح', 'نح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3745, 'نَادِي', 'نادي', 'اسم فاعل', 'ندو', 'نادي', 'ند', 'فا مِنْ نَادَى', 'Tk', '', 'مفرد', '', '', '', '"أَنْدِيَةٌ:نَوَادٍ:النَّوَادِ', '', '', '', '', '', '', '', '', '"(فا مِنْ نَادَى). 1.""نَادِي الْمُهَنْدِسِينَ"" : مَكَانُ، مَجْلِسُ اِجْتِمَاعِهِمْ. ‏ ""ذَهَبَ إِلَى النَّادِي"" ""النَّوَادِي الرِّيَاضِيَّةُ"". 2.""النَّادِي اللَّيْلِيُّ"" : مَكَانٌ للتَّسْلِيَةِ وَاللَّهْوِ. ""وَنَوَادِي اللَّيْلِ تَبْقَى عِنْدَنَا مَفْتُوحَةً حَتَّى الصَّبَاح"". ( نزار قباني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3746, 'مُنَافِسٌ', 'منافس', 'اسم فاعل', 'نفس', 'منافس', 'منفس', 'فا. من نَافَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَافَسَ). ""مُنَافِسٌ في كُلِّ مَوْضُوعٍ"" : مُزَاحِمٌ ، مُتَسَابِقٌ، مَتَبَارٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3747, 'نَوَادِي', 'نوادي', 'اسم فاعل', '', 'نوادي', 'ند', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3748, 'مُنَادِي', 'منادي', 'اسم فاعل', 'ندو', 'منادي', 'مند', 'فا. من نَادَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَادَى). ""جَاءَ مُنَادِياً الْجُمْهُورَ لإِغاثَتِهِ"" : دَاعِياً، صَائِحاً بِصَوْتٍ مُرْتَفِعٍ.آل عمران آية 193 رَبَّنَا إِنَّنَا سَمِعْنَا مُنَادِياً يُنَادِي لِلْإِيمَانِ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3749, 'مُنَازِعٌ', 'منازع', 'اسم فاعل', 'نزع', 'منازع', 'منزع', 'فا. من نَازَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَازَعَ). 1.""رَجُلٌ مُنَازِعٌ عَنِيدٌ"" : مُخَاصِمٌ، مُشَاغِبٌ. ""مِنَ الْمُتَنَازِعِينَ فِي كُلِّ أَمْرٍ"". 2.""لَيْسَ مِنْ مُنَازِعٍ فِي أَمْرِهِ"" : مَا مِنْ شَكٍّ فِيهِ. ""بِلاَ مُنَازِعٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3750, 'مُنَاسِبٌ', 'مناسب', 'اسم فاعل', 'نسب', 'مناسب', 'منسب', 'فا.من نَاسَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُنَاسِبٌ-مُنَاسِبٌ، ةٌ [ن س ب] (فا.من نَاسَبَ). 1""عَمَلٌ مُنَاسِبٌ"" : مُلاَئِمٌ. ""كَانَ الوَقْتُ مُنَاسِباً لإِجْرَاءِ العَمَلِيَّةِ"". 2.""الْمُنَاسِبُ فِي الرِّيَاضِيَّاتِ"" : أَي لَهُ النِّسْبَةُ نَفْسُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3751, 'مُنَاشِدٌ', 'مناشد', 'اسم فاعل', 'نشد', 'مناشد', 'منشد', 'فا. من نَاشَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَاشَدَ). ""جَاءَ مُنَاشِداً مُسَاعَدَتَهُ"" : طَالِباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3752, 'مُنَاصِرٌ', 'مناصر', 'اسم فاعل', 'نصر', 'مناصر', 'منصر', 'فا. من نَاصَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَاصَرَ). ""مُنَاصِرُ الْحَقِّ"" : مُدَافِعٌ عَنِ الْحَقِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3753, 'مُناضِلٌ', 'مناضل', 'اسم فاعل', 'نضل', 'مناضل', 'منضل', 'فا. من نَاضَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَاضَلَ). 1.""مُنَاضِلٌ سِيَاسِيٌّ"" : مُدَافِعٌ عَنِ الْحُقُوقِ السِّيَاسِيَّةِ والاِجْتِمَاعِيَّةِ. 2.""مُنَاضِلٌ فِي سَبِيلِ تَحْرِيرِ بِلاَدِهِ مِنَ الاحْتِلاَلِ"": مُكَافِحٌ، مُقَاوِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3754, 'مُنَاظِرٌ', 'مناظر', 'اسم فاعل', 'نظر', 'مناظر', 'منظر', 'فا. من نَاظَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَاظَرَ). 1.""مُنَاظِرٌ زَمِيلَهُ"" : مُمَاثِلٌ لَهُ، نَظِيرٌ لَهُ. 2.""عَالِمٌ مُنَاظِرٌ..."" : مُجَادِلٌ، مُسَاهِمٌ بِالحِوَارِ فِي مُنَاظَرَةٍ أَو مَوْضُوعٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3755, 'مُنَافِحٌ', 'منافح', 'اسم فاعل', 'نفح', 'منافح', 'منفح', 'فا. من نَافَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُنَافِحٌ-مُنَافِحٌ، ةٌ [ن ف ح] (فا. من نَافَحَ). 1.""مُنَافِحٌ عَنِ الْحَقِّ"" : مُكَافِحٌ، مُنَاضِلٌ. 2.""مُنَافِحٌ عَنْ أَفْكَارِهِ"" : مُدَافِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3756, 'نوائم', 'نوائم', 'اسم فاعل', '', 'نواءم', 'نم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3757, 'مُنَافِقٌ', 'منافق', 'اسم فاعل', 'نفق', 'منافق', 'منفق', 'فا. من نَافَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَافَقَ). 1.""رَجُلٌ مُنَافِقٌ"" : يُظْهِرُ خِلاَفَ مَا يُبْطِنُ. ""الْمُنَافِقُ يُكْثِرُ الكَلاَمَ ويُقِلُّ العَمَلَ"". 2.التوبة آية 68 وَعَدَ اللَّهُ الْمُنَافِقِينَ والْمُنَافِقَاتِ والكُفَّارَ نَارَ جَهَنَّمَ . (قرآن) : مَنْ يُخْفِي الكُفْرَ ويُظْهِرُ الإِيمَانَ. 3.""الْمُنَافِقُونَ"" : سُورَةٌ مِنْ سُوَرِ القُرْآنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3758, 'مُنَافِي', 'منافي', 'اسم فاعل', 'نفي', 'منافي', 'منف', 'فا. من نَافَى', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَافٍ-مُنَافٍ، الْمُنَافِي، ةٌ [ن ف ي] (فا. من نَافَى). ""مُنَافٍ لِلْحَقِيقَةِ"" : مُخَالِفٌ، مُعَاكِسٌ. ""سُلُوكٌ مُنَافٍ لِلأَخْلاقِ"" ""أَعْمَالُهُ مُنَافِيَةٌ لِلْعَادَاتِ والتَّقَالِيدِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3759, 'مُنَاقِشٌ', 'مناقش', 'اسم فاعل', 'نقش', 'مناقش', 'منقش', 'فا. من نَاقَشَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَاقَشَ). ""مُنَاقِشٌ صَارِمٌ"" : مُجَادِلٌ، أَيِ الَّذِي يَدْخُلُ فِي نِقَاشٍ مَعَ شَخْصٍ آخَرَ أو جَمَاعَةٍ. ""كَانَ مِنْ بَيْنِ الْمُنَاقِشِينَ في الْمُنَاظَرَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3760, 'مُنَاقِضٌ', 'مناقض', 'اسم فاعل', 'نقض', 'مناقض', 'منقض', 'فَا. من نَاقَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. من نَاقَضَ). ""أَمْرٌ مُنَاقِضٌ"" : مُخَالِفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3761, 'نَائِلٌ', 'نائل', 'اسم فاعل', 'نول', 'ناءل', 'نل', 'فَا. من نَالَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. من نَالَ). ""نَائِلُ الْمَكَارِمِ"" : أَيْ يَتَلَقَّى الْمَكَارِمَ وَيَحْصُلُ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3762, 'نوائل', 'نوائل', 'اسم فاعل', '', 'نواءل', 'نل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3763, 'نَائِمٌ', 'نائم', 'اسم فاعل', 'نوم', 'ناءم', 'نم', 'فا. مِنْ نَامَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":نِيَامٌ:نُوَّامٌ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ نَامَ). ""تَرَكَهُ نَائِماً مُسْتَغْرِقاً فِي النَّوْمِ : رَاقِداً. ""أَيُّهَا النَّائِمُونَ اِسْتَيْقِظُوا"" ""أَحْلاَمُ النَّائِمِ تُفْرِحُهُ فَإِذَا اسْتَيْقَظَ اِنْقَطَعَ الفَرَحُ عَنْهُ"". (ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3764, 'نِيَامٌ', 'نيام', 'اسم فاعل', '', 'نيام', 'نم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3765, 'نُوَّامٌ', 'نوام', 'اسم فاعل', '', 'نوام', 'نم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3766, 'نَابِي', 'نابي', 'اسم فاعل', 'نبو', 'نابي', 'نب', 'فَا. من نَبَا', 'Tk', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نَابٍ-نَابٍ، النَّابِي، ةٌ [ن ب و] (فَا. من نَبَا). 1.""سَيْفٌ نَابٍ"" : سَيْفٌ غَيْرُ حَادٍّ. 2.""كَلاَمٌ نَابٍ"" : بَذِيءٌ، مُنَافٍ لِلآدَابِ وَالأَخْلاَقِ. ""كَلِمَةٌ نَابِيَةٌ"". 3.""ذَوْقٌ نَابٍ"" : ذَوْقٌ جَافٌّ. 4.""سَهْمٌ نَابٍ"" : سَهْمٌ لَمْ يُصِبْ هَدَفَهُ. 5.""قَوْسٌ نَابِـيَةٌ"" : قَوْسٌ اِنْفَلَتَ حَبْلُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3767, 'مُنَاهِضٌ', 'مناهض', 'اسم فاعل', 'نهض', 'مناهض', 'منهض', 'فا. من نَاهَضَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَاهَضَ). ""مُنَاهِضُ الظُّلْمِ"" : مُقَاوِمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3768, 'مُنَاوِئٌ', 'مناوئ', 'اسم فاعل', 'نوأ', 'مناوء', 'من', 'فا. من نَاوَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فا. من نَاوَأَ). ""مُنَاوِئٌ خُصُومَهُ"" : مُنَاوِشٌ، مُعَادٍ، مُضَادٌّ، مُنَاهِضٌ، مُعَارِضٌ لَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3769, 'مُنَاوِئٌ', 'مناوئ', 'اسم فاعل', '', 'مناوء', 'من', '', '', 'Ta', 'جمع تكسير', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَاوَأَ). ""مُنَاوِئٌ خُصُومَهُ"" : مُنَاوِشٌ، مُعَادٍ، مُضَادٌّ، مُنَاهِضٌ، مُعَارِضٌ لَهُمْ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3770, 'مُنَاوِبٌ', 'مناوب', 'اسم فاعل', 'نوب', 'مناوب', 'منب', 'فا. من نَاوَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من نَاوَبَ). ""مُنَاوِبٌ عَلَى الحِرَاسَةِ فِي اللَّيْلِ"" : الْمُتَدَاوِلُ لِلْحِرَاسَةِ بِاللَّيْلِ مَعَ غَيْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3771, 'مُنَاوِرٌ', 'مناور', 'اسم فاعل', 'نور', 'مناور', 'منر', 'فا. من نَاوَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَاوَرَ). ""رَجُلٌ مُنَاوِرٌ"" : مَنْ يُنَاوِرُ بِالاحْتِيَالِ أو مَا شَابَهَ ذَلِك، مُخَاتِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3772, 'مُنَاوِشٌ', 'مناوش', 'اسم فاعل', 'نوش', 'مناوش', 'منش', 'فا. من نَاوَشَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُنَاوِشٌ-مُنَاوِشٌ [ن و ش ] (فا. من نَاوَشَ). ""كَانَ الْمُنَاوِشَ الوَحِيدَ فِي الْجَمَاعَةِ"" : الْمُنَازِعُ، الْمُزْعِجُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3773, 'نَائِي', 'نائي', 'اسم فاعل', 'نأي', 'ناءي', 'ن', 'فَا. من نَـأَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:"', '', '', '', '', '', '', '', '', '"(فَا. من نَـأَى). ""النَّائِي عَنْ بِلاَدِهِ "" : البَعِيدُ عَنْهَا. ""ظَلَّ نَائِياً عَنْهُ"" ""فِي بِلاَدٍ نَائِيَةٍ"" ""قَرْيَةٌ نَائِيَةٌ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3774, 'نآة', 'نآة', 'اسم فاعل', '', 'نءءة', 'نآة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
