INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3776, 'نَابِحٌ', 'نابح', 'اسم فاعل', 'نبح', 'نابح', 'نبح', 'فا. مِنْ نَبَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"نَابِحٌ-نَابِحٌ [ن ب ح] (فا. مِنْ نَبَحَ). ""رَجُلٌ نَابِحُ الصَّوْتِ"": شَدِيدُهُ، أَيْ صَوْتُهُ مُرْتَفِعٌ جِدّاً."', '');
