INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3778, 'نَابِتٌ', 'نابت', 'اسم فاعل', 'نبت', 'نابت', 'نبت', 'فَا. من نَبَتَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"نَابِتٌ-نَابِتٌ، ةٌ [ن ب ت] (فَا. من نَبَتَ). ""زَرْعٌ نَابِتٌ"" : بَارِزٌ، ظَاهِرٌ، نَامٍ. ""تَنْتَعِشُ الزَّهْرَةُ النَّابِتَةُ بَيْنَ الصُّخُورِ"". (جبران خ. جبران)."', '');
