INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3786, 'نَابِلٌ', 'نابل', 'اسم فاعل', 'نبل', 'نابل', 'نبل', 'فَا. من نَبَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ـو:نُبَّلٌ:نَبَلٌ"', '', '', '', '', '', '', '', '', '"(فَا. من نَبَلَ). 1.""رَجُلٌ نَابِلٌ"" : صَانِعُ النِّبَالِ. 2.""صَيَّادٌ نَابِلٌ"" : مَاهِرٌ فِي رَمْيِ النِّبَالِ. 3.""اِخْتَلَطَ الْحَابِلُ بِالنَّابِلِ"" : اِخْتَلَطَتِ الأُمُورُ وَالْتَبَسَتْ، وَأَصْلُهَا اخْتَلَطَ أَمْرُ مَنْ يَصِيدُ بِالْحِبَالِ وَالنِّبَالِ."', '');
