INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3802, 'نَاتِئٌ', 'ناتئ', 'اسم فاعل', 'نتأ', 'ناتء', 'نت', 'فَا. من نَتَأَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نَاتِئٌ-نَاتِئٌ، ةٌ [ن ت أ] (فَا. من نَتَأَ). ""حَبْلٌ نَاتِئٌ"" : بَارِزٌ، بِهِ نُتُوءٌ. ""جِبَالٌ نَاتِئَةٌ"" ""صَاحِبُ العَيْنِ النَّاتِئَةِ لاَ يُبْصِرُ مَا بَعُدَ عَنْهُ بَصَراً جَيِّداً "". (التوحيدي)."', '');
