INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3819, 'نَاجِزٌ', 'ناجز', 'اسم فاعل', 'نجز', 'ناجز', 'نجز', 'فَا. من نَجَزَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نَاجِزٌ-نَاجِزٌ [ن ج ز] (فَا. من نَجَزَ). 1.""وَعْدٌ نَاجِزٌ"" : قَائِمٌ، وُفِيَ بِهِ. 2.""عَمَلٌ نَاجِزٌ"" : تَامٌّ، كَامِلٌ. 3.""بِعْتُهُ نَاجِزاً بِنَاجِزٍ"" : أَيْ مَا بِعْتُهُ أَدَّى ثَمَنَهُ نَقْداً، يَداً بِيَدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3820, 'نواجز', 'نواجز', 'اسم فاعل', '', 'نواجز', 'نجز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3821, 'نَاجِسٌ', 'ناجس', 'اسم فاعل', 'نجس', 'ناجس', 'نجس', 'فَا. من نَجَسَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نَاجِسٌ-نَاجِسٌ، ةٌ [ن ج س] (فَا. من نَجَسَ). 1.""ثَوْبٌ نَاجِسٌ"" : نَجِسٌ، قَذِرٌ، أَيْ بِهِ نَجَاسَةٌ. 2.""مَكَانٌ نَاجِسٌ"" : تَقْشَعِرُّ مِنْهُ النَّفْسُ. 3.""دَاءٌ أَوْ مَرَضٌ نَاجِسٌ"" : لاَ يَنْفَعُ مَعَهُ دَوَاءٌ، مَرَضٌ، عُضَالٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3822, 'نواجس', 'نواجس', 'اسم فاعل', '', 'نواجس', 'نجس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3823, 'نَاجِعٌ', 'ناجع', 'اسم فاعل', 'نجع', 'ناجع', 'نجع', 'فَا. من نَجَعَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":نَوَاجِعُ"', '', '', '', '', '', '', '', '', '"(فَا. من نَجَعَ). 1.""مَاءٌ نَاجِعٌ"" : هَنِيءٌ، مَرِيءٌ. 2.""دَوَاءٌ نَاجِعٌ"" : شَافٍ، فَعَّالٌ، نَافِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3824, 'نَوَاجِعُ', 'نواجع', 'اسم فاعل', '', 'نواجع', 'نجع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3825, 'نَاجِمٌ', 'ناجم', 'اسم فاعل', 'نجم', 'ناجم', 'نجم', 'فَا. من نَجَمَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نَاجِمٌ-نَاجِمٌ، ةٌ [ن ج م] (فَا. من نَجَمَ). ""ضَرَرٌ نَاجِمٌ عَنِ الإِهْمَالِ"" : نَاتِجٌ . ""حَرَائِقُ نَاجِمَةٌ عَنْ شِدَّةِ الْجَفَافِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3826, 'نَاحِلٌ', 'ناحل', 'اسم فاعل', 'نحل', 'ناحل', 'نحل', 'فَا. من نَحَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":نُحُولٌ:نَوَاحِلُ"', '', '', '', '', '', '', '', '', '"(فَا. من نَحَلَ). ""نَاحِلُ الْجِسْمِ"" : رَقِيقُ الْجِسْمِ. ""نَاحِلُ القِوَامِ"" نَاحِلَةُ القِوَامِ"" ""اِمْرَأَةٌ نَاحِلَةُ الْمِعْصَمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3827, 'مُنَجِّمٌ', 'منجم', 'اسم فاعل', 'نجم', 'منجم', 'منجم', 'فا. من نَجَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَجَّمَ). 1.""اِدَّعَى الْمُنَجِّمُ كَذا"" : مَنْ يَسْتَطْلِعُ الغَيْبَ. ""يَسْتَطْلِعُ الْمُنَجِّمُ لِمَعْرِفَةِ مَا سَيَحْدُثُ لَهُ فِي الآجَالِ القَرِيبَةِ"" l ""كَذَبَ الْمُنَجِّمُونَ وإِنْ صَدَقُوا"". 2.""مُنَجِّمٌ عَالِمٌ"" : مَنْ يَنْظُرُ فِي مَطَالِعِ النُّجُومِ ويَسْتَطْلِعُ مِنْ ذَلِكَ أَحْوَالَ الكَوْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3828, 'مُنَجِّي', 'منجي', 'اسم فاعل', 'نجو', 'منجي', 'منج', 'فا. من نَجَّى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَجَّى). ""يَنْتَظِرُ الْمُنَجِّيَ لِيُخَلِّصَهُ مِنَ العَذَابِ"" : الْمُخَلِّص."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3829, 'نَاحِي', 'ناحي', 'اسم فاعل', 'نحو', 'ناحي', 'نح', 'فا مِنْ نَحَا', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":نُحَاةٌ"', '', '', '', '', '', '', '', '', '"(فا مِنْ نَحَا). ""عَالِمٌ نَاحٍ"" : عَالِمٌ بِالنَّحْوِ."', '');
