INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3926, 'نَاشِزٌ', 'ناشز', 'اسم فاعل', 'نشز', 'ناشز', 'نشز', 'فَا. من نَشَزَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات:نَوَاشِزُ"', '', '', '', '', '', '', '', '', '"(فَا. من نَشَزَ). 1.""عِرْقٌ نَاشِزٌ"" : مُنْتَفِخٌ، نَاتِئٌ. 2.""صَوْتٌ نَاشِزٌ "" : غَيْرُ مُنْسَجِمٍ مَعَ أَصْوَاتٍ مُرَافِقَةٍ لَهُ، أَيْ خَارِجٌ عَلَى اللَّحْنِ الْمَرْسُومِ. 3.""اِمْرَأَةٌ نَاشِزٌ، أَونَاشِزَةٌ"" : تَتَمَرَّدُ عَلَى زَوْجِهَا وتَبْغَضُهُ، تُسِيءُ العِشْرَةَ مَعَهُ. ""لَقَدْ وَجَدَهَا امْرَأَةً نَاشِزَةً تَصْعُبُ مُعَاشَرَتُهَا"". 4.""قَلْبٌ نَاشِزٌ"" : اِرْتَفَعَ مِنْ مَكَانِهِ رُعْباً. "', '');
