INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3944, 'مُنَشِّطٌ', 'منشط', 'اسم فاعل', 'نشط', 'منشط', 'منشط', 'فا. من نَشَّطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَشَّطَ). 1.""مُنَشِّطُ الْحَفْلَةِ"" : مَنْ يَكُونُ مَسْؤُولاً عَنْ تَنْشِيطِ الْحَفْلَةِ. 2.""دَوَاءٌ مُنَشِّطٌ"" : دَوَاءٌ بَاعِثٌ عَلَى الْحَيَوِيَّةِ وَالنَّشَاطِ فِي الْجِسْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3945, 'نَاشِفٌ', 'ناشف', 'اسم فاعل', 'نشف', 'ناشف', 'نشف', 'فَا. من نَشَفَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نَاشِفٌ-نَاشِفٌ، ةٌ [ن ش ف] (فَا. من نَشَفَ). 1.""خُبْزٌ نَاشِفٌ"" : يَابِسٌ. 2.""وَالْهَوَاءُ النَّاشِفُ يَهُبُّ لَذِيذاً"" : الْجَافُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3946, 'نَاصِرٌ', 'ناصر', 'اسم فاعل', 'نصر', 'ناصر', 'نصر', 'فا. من نَصَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات:نُصَّارٌ:أَنْصَارٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَصَرَ). 1.""نَاصِرٌ لَهُ عَلَى أَعْدَائِهِ"" : مُسَاعِدٌ، مُؤَيِّدٌ لَهُ.آل عمران آية 22 وَمَا لَهُمْ مِنْ نَاصِرِينَ (قرآن) ""وَهُوَ فِي الْخَلْوَةِ خَيْرُ مُسَامِرٍ وَعِنْدَ الْحَاجَةِ خَيْرُ نَاصِرٍ"". (الجاحظ). 2.""أَخَذَ بِنَاصِرِهِ"" : أَمَدَّهُ بِالعَوْنِ، سَاعَدَهُ. 3.""هُوَ اللَّهُ النَّاصِرُ"" : مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى. 4.""عَبْدُ النَّاصِرِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ. 5.""نَاصِرٌ"" : يُطْلَقُ عَلَى شَهْرِ يُونْيُو حَسَبَ اليَوْمِيَّةِ اللِّيبِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3947, 'مُنَشِّفٌ', 'منشف', 'اسم فاعل', 'نشف', 'منشف', 'منشف', 'فا. من نَشَّفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مُنَشِّفٌ-مُنَشِّفٌ، ةٌ [ن ش ف] (فا. من نَشَّفَ). ""مُنَشِّفُ الشَّعْرِ"" : آلَةٌ يُنَشَّفُ بِهَا الشَّعْرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3948, 'نَاصِبٌ', 'ناصب', 'اسم فاعل', 'نصب', 'ناصب', 'نصب', 'فَا. من نَصَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":نَوَاصِبُ"', '', '', '', '', '', '', '', '', '"(فَا. من نَصَبَ). 1.""نَاصِبٌ فِي سَيْرِهِ"" : جَادٌّ فِيهِ. 2.""هَمٌّ نَاصِبٌ"" : مُتْعِبٌ. 3.""عَيْشٌ نَاصِبٌ"" : فِيهِ كَدٌّ وتَعَبٌ. 4.""لَنْ حَرْفٌ نَاصِبٌ"" : يَنْصِبُ الفِعْلَ الْمُضَارِعَ : ""لَنْ يَخْرُجَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3949, 'نَوَاصِبُ', 'نواصب', 'اسم فاعل', '', 'نواصب', 'نصب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
