INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3952, 'نَاصِحٌ', 'ناصح', 'اسم فاعل', 'نصح', 'ناصح', 'نصح', 'فَا. من نَصَحَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. من نَصَحَ). 1.""نَاصِحٌ لَهُ"" : مُوَجِّهٌ النَّصَائِحَ.الأعراف آية 68 وَأَنَا لَكُمْ نَاصِحٌ أَمِينٌ (قرآن). 2.""بَيَاضٌ نَاصِحٌ"" : بَيَاضٌ صَافٍ، خَالِصٌ. 3.""نَاصِحُ الْجَيْبِ"" : نَقِيُّ القَلْبِ لاَ غِشَّ فِيهِ."', '');
