INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3961, 'نَاصِعٌ', 'ناصع', 'اسم فاعل', 'نصع', 'ناصع', 'نصع', 'فَا. من نَصَعَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. من نَصَعَ). 1.""أَبْيَضُ نَاصِعٌ"" : صَافٍ. ""كَانَتْ تَرْتَدِي ثَوْباً نَاصِعاً"". 2.""حَقٌّ نَاصِعٌ"" : ظَاهِرٌ، بَيِّنٌ، وَاضِحٌ. ""حَقِيقَةٌ نَاصِعَةٌ لاَ غُبَارَ عَلَيْهَا"". 3.""حَسَبٌ نَاصِعٌ"" : خَالِصٌ لاَ شَائِبَةَ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3962, 'نواصع', 'نواصع', 'اسم فاعل', '', 'نواصع', 'نصع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3963, 'نَاصِفٌ', 'ناصف', 'اسم فاعل', 'نصف', 'ناصف', 'نصف', 'فَا. من نَصَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":نُصَّافٌ:نَوَاصِفُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. من نَصَفَ). ""نَاصِفَةُ البَيْتِ"" : وَصِيفَتُهُ، خَادِمَتُهُ. ""نَاصِفُو الْقَصْرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3964, 'نُصَّافٌ', 'نصاف', 'اسم فاعل', '', 'نصاف', 'نصف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
