INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3966, 'مُنَضِّدٌ', 'منضد', 'اسم فاعل', 'نضد', 'منضد', 'منضد', 'فا. من نَضَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَضَّدَ). ""مُنَضِّدُ الْحُرُوفِ الْمَطْبَعِيَّةِ"" : مُصَفِّفُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3967, 'نَاضِبٌ', 'ناضب', 'اسم فاعل', 'نضب', 'ناضب', 'نضب', 'فَا. من نَضَبَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":نُضَّبٌ"', '', '', '', '', '', '', '', '', '"(فَا. من نَضَبَ). ""نَبْعٌ نَاضِبٌ"" : جَافٌّ، أَيْ ذَهَبَ مَاؤُهُ. ""غَدِيرٌ نَاضِبٌ"" ""مَدَّ إلَى القُلَلِ يَدَهُ أَلْفَاهَا نَاضِبَةً لَيْسَ فِي وَاحِدَةٍ مِنْهَا قَطْرَةٌ"". (محمود تيمور)."', '');
