INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3977, 'نَاضِرٌ', 'ناضر', 'اسم فاعل', 'نضر', 'ناضر', 'نضر', 'فَا. من نَضَرَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":نُضَّرٌ:نَوَاضِرُ"', '', '', '', '', '', '', '', '', '"(فَا. من نَضَرَ). 1.""وَجْهٌ نَاضِرٌ"" : جَمِيلٌ، حَسَنٌ.القيامة آية 22 ، 23وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ إِلَى رَبِّهَا نَاظِرَةٌ (قرآن). 2.""لَوْنٌ نَاضِرٌ"" : نَاصِعٌ، شَدِيدُ اللَّمَعَانِ. ""أَصْفَرُ نَاضِرٌ""‎ ""أَخْضَرُ نَاضِرٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3978, 'نُضَّرٌ', 'نضر', 'اسم فاعل', '', 'نضر', 'نضر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
