INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3988, 'نَاطِفٌ', 'ناطف', 'اسم فاعل', 'نطف', 'ناطف', 'نطف', 'فَا. من نَطِفَ', '', '', 'مفرد', '', '', '', '""', '', '', '', '', '', '', '', '', '"نَاطِفٌ-نَاطِفٌ [ن ط ف] (فَا. من نَطِفَ). : نَوْعٌ مِنَ الْحَلْوَى البَيْضَاءِ.النَّاطِفُ   : فا.-: السّائل من المائعات.-: ضربٌ من الحلوى يُصنع من اللّوز والجَوز والفُستق، وُيسمّى أيضاً القُبَّيط؛"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3989, 'نواطف', 'نواطف', 'اسم فاعل', '', 'نواطف', 'نطف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(3990, 'نَاطِقٌ', 'ناطق', 'اسم فاعل', 'نطق', 'ناطق', 'نطق', 'فَا. من نَطَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. من نَطَقَ). 1.""نَاطِقٌ بِالْحَقِّ"": الْمُتَكَلِّمُ. 2.""النَّاطِقُ بِاسْمِ الْحُكُومَةِ"" : الْمُتَحَدِّثُ بِاسْمِهَا. ""النَّاطِقُ الرَّسْمِيُّ"". 3.""الإِنْسَانُ حَيَوَانٌ نَاطِقٌ"": مُفَكِّرٌ، إِنْسَانٌ عَاقِلٌ. 4.""حَقَائِقُ نَاطِقَةٍ"" : وَاضِحَةٌ، بَيِّنَةٌ. 5.""مَا لَهُ نَاطِقٌ وَلاَ صَامِتٌ"" : أَيْ مَا لَهُ مَاشِيَةٌ وَلاَ ذَهَبٌ. 6.""النَّاطِقُونَ بِالضَّادِ"" : العَرَبُ. 7.""صُورَةٌ نَاطِقَةٌ بِأَكْثَرَ مِنْ مَعْنـىً"" : كَاشِفَةٌ، مُعَبِّرَةٌ. 8.""نَفْسٌ نَاطِقَةٌ"" : مُدْرِكَةٌ للأَشْيَاءِ، عَاقِلَةٌ. 9.""نَشْرَةُ الأَخْبَارِ النَّاطِقَةِ"" : أَيِ الأَخْبَارُ الَّتِي تُقَدِّمُهَا الإِذَاعَةُ خِلاَفُ الأَخْبَارِ الْمُصَوَّرَةِ الَّتِي تُقَدِّمُها التَّلْفَزَةُ."', '');
