INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4029, 'مُنَفِّذٌ', 'منفذ', 'اسم فاعل', 'نفذ', 'منفذ', 'منفذ', 'فا. من نَفَّذَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَفَّذَ). ""مُنَفِّذُ الأَوَامِرِ"" : مُطَبِّقٌ لَهَا. ""مُنَفِّذٌ الْوَصَايَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4030, 'نَافِرٌ', 'نافر', 'اسم فاعل', 'نفر', 'نافر', 'نفر', 'فَا. من نَفَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات:نَفْرٌ:نُفَّرٌ"', '', '', '', '', '', '', '', '', '"(فَا. من نَفَرَ). 1.""حَيَوَانٌ نَافِرٌ"" : صَعْبُ الْمِرَاسِ. 2.""نَافِرَةُ الرَّجُلِ"" : عَائِلَتُهُ، قَبِيلَتُهُ، قَوْمُهُ الأَقْرَبُونَ."', '');
