INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4036, 'مُنَفِّرٌ', 'منفر', 'اسم فاعل', 'نفر', 'منفر', 'منفر', 'فا. من نَفَّرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَفَّرَ). 1.""سُلُوكُهُ مُنَفِّرٌ"" : بَغِيضٌ، مُثِيرٌ لِلْاِشْمِئْزَازِ. 2.""قُبْحٌ مُنَفِّرٌ"" : كَرِيهٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4037, 'نَافِسٌ', 'نافس', 'اسم فاعل', 'نفس', 'نافس', 'نفس', 'فَا. من نَفَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"نَافِسٌ-نَافِسٌ [ن ف س] (فَا. من نَفَسَ). 1.""رَجُلٌ نَافِسٌ"" : مُصِيبٌ بِالعَيْنِ، أَوْ حَاسِدٌ. 2.""شَيْءٌ نَافِسٌ"" : رَفِيعٌ مَرْغُوبٌ فِيهِ."', '');
