INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4045, 'نَافِطٌ', 'نافط', 'اسم فاعل', 'نفط', 'نافط', 'نفط', 'فَا. من نَفَطَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":نَوَافِطُ"', '', '', '', '', '', '', '', '', '"(فَا. من نَفَطَ). 1.""نَافِطُ الْجِسْمِ"" : أَيْ جِسْمُهُ بِهِ قُرُوحٌ، بُثُورٌ. 2. : بُثُورٌ تَخْرُجُ فِي اليَدِ مَلْأَى بِالْمَاءِ. 3.""رَغْوَةٌ نَافِطَةٌ"" : ذَاتُ نُفَّاخَاتٍ. 4.""مَالَهُ عَافِطَةٌ وَلاَ نَافِطَةٌ"" : غَيْرُ مَالِكٍ لِشَيْءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4046, 'نَوَافِطُ', 'نوافط', 'اسم فاعل', '', 'نوافط', 'نفط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4047, 'نَافِعٌ', 'نافع', 'اسم فاعل', 'نفع', 'نافع', 'نفع', 'فَا. من نَفَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"نَافِعٌ-نَافِعٌ [ن ف ع] (فَا. من نَفَعَ). 1.""عَمَلٌ نَافِعٌ"" : مُفِيدٌ، فِيهِ مَنْفَعَةٌ. ""دَوَاءٌ نَافِعٌ لَهُ مَفْعُولٌ قَوِيٌّ"". 2.""هُوَ اللَّهُ النَّافِعُ"" : مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى، يُوصِلُ النَّفْعَ إِلَى مَنْ يَشَاءُ مِنْ عِبَادِهِ. ""لاَ يُمَيِّزُ الضَّارَّ مِنَ النَّافِعِ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4048, 'نوافع', 'نوافع', 'اسم فاعل', '', 'نوافع', 'نفع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
