INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4051, 'نَافِقٌ', 'نافق', 'اسم فاعل', 'نفق', 'نافق', 'نفق', 'فَا. من نَفَقَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نَافِقٌ-نَافِقٌ، ةٌ [ن ف ق] (فَا. من نَفَقَ). 1.""بَضَائِعُ نَافِقَةٌ"" : رَائِجَةٌ، عَلَيْهَا إِقْبَالُ الزُّبُنِ. 2.""سُوقٌ نَافِقَةٌ"" : خِلاَفُ الكَاسِدَةِ. 3.""النَّافِقَةُ"" : وِعَاءُ الْمِسْكِ."', '');
