INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4129, 'نَاهِي', 'ناهي', 'اسم فاعل', 'نهي', 'ناهي', 'نه', 'فَا. من نَهَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:نُهَاةٌ:نَوَاهٍ:النَّوَاهِ', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. من نَهَى). 1.""النَّاهِي عَنِ الْمُنْكَرِ"" : مَنْ يَنْهَى النَّاسَ عَنِ ارْتِكَابِ الْمَنَاكِرِ أَوِ الْمَعَاصِي. 2.""هَذَا شَاعِرٌ نَاهِيكَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4130, 'نُهَاةٌ', 'نهاة', 'اسم فاعل', '', 'نهاة', 'نهة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
