INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4132, 'مُنَوِّعٌ', 'منوع', 'اسم فاعل', 'نوع', 'منوع', 'منع', 'فا. من نَوَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَوَّعَ). ""مُنَوِّعٌ فِي صَنَائِعِهِ"" : مَنْ يُنَوِّعُ فِيهَا ويَأْتِي بِأَصْنَافٍ وأَنْوَاعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4133, 'مُنَوِّمٌ', 'منوم', 'اسم فاعل', 'نوم', 'منوم', 'منم', 'فا. من نَوَّمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من نَوَّمَ). 1.""دَوَاءٌ مُنَوِّمٌ"" : بَاعِثٌ عَلَى النَّوْمِ. ""حُبُوبٌ مُنَوِّمَةٌ"". 2.""مُنَوِّمٌ مَاهِرٌ"" : مَنْ يُزَاوِلُ التَّنْوِيمَ المِغْنَاطِيسِيَّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4134, 'نَاوِي', 'ناوي', 'اسم فاعل', 'نوي', 'ناوي', 'ن', 'فَا. من نَوَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:نِوَاءٌ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. من نَوَى). 1.""نَاوٍ السَّفَرَ إِلَى الْخَارِجِ"" : عَازِمٌ، قَاصِدٌ. 2.""نَاوِي الْقَوْم"" : كَبِيرُهُمْ وَسَيِّدُهُمْ وَصَاحِبُ أَْمِرِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4135, 'نِوَاءٌ', 'نواء', 'اسم فاعل', '', 'نواء', 'ن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4136, 'هَائِبٌ', 'هائب', 'اسم فاعل', 'هيب', 'هاءب', 'هب', 'فا. من هَابَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من هَابَ). 1.""رَجُلٌ هَائِبٌ"" : حَذِرٌ، خَائِفٌ. 2.""وَجَدَهُ فِي جَلْسَتِهِ هَائِبَ الْمَنْظَرِ"" : مُوَقَّراً، مُعَظَّماً. ""كَيْفَ لاَ أَطْلُبُ طَلَبَ الْجِرِّيءِ الْمُتَهَوِّرِ وَأَمْسِكُ إِمْسَاكَ الْهَائِبِ الْمُوَقَّرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4137, 'هوائب', 'هوائب', 'اسم فاعل', '', 'هواءب', 'هب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4138, 'مُهَاتِرٌ', 'مهاتر', 'اسم فاعل', 'هتر', 'مهاتر', 'مهتر', 'فا. من هَاتَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من هَاتَرَ). 1.""وَلَدٌ مُهاتِرٌ"" : مَنْ يَرُدُّ الشَّتَائِمَ بِمِثْلِهَا. 2.""رَجُلٌ مُهَاتِرٌ"" : لَوَّامٌ، مُعَاتِبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4139, 'هَائِجٌ', 'هائج', 'اسم فاعل', 'هيج', 'هاءج', 'هج', 'فا. من هَاجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":هَوَائِجُ"', '', '', '', '', '', '', '', '', '"(فا. من هَاجَ). 1.""كَانَ الْبَحْرُ هَائِجاً"" : مُتَلاطِمَ الأَمْوَاِج مُضْطَرِباً. ""اِخْتَبَأْنَا فِي كُوخٍ لَمَّا اشْتَدَّتِ الرِّيحُ الْهَائِجَةُ"". 2.""خَرَجَ الْجُمْهُورُ هَائِجاً مِنَ الْمَلْعَبِ"" : فَائِراً مِنَ الْغَضَبِ، صَائِحاً، صَاخِباً. ""عَرَفَ الِاجْتِمَاعُ جَلْسَةً هَائِجَةً"". 3.""هَاجَ هَائِـجُهُ"" : هَاجَتْ فَوْرَةُ غَضَبِهِ عَكْس ""هَدَأَ هَائِجُهُ"". 4.""أَرْضٌ هَائِجَةٌ"" : أَيْ بَقْلُهَا يَابِسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4140, 'هَوَائِجُ', 'هوائج', 'اسم فاعل', '', 'هواءج', 'هج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4141, 'مُهَاجِرٌ', 'مهاجر', 'اسم فاعل', 'هجر', 'مهاجر', 'مهجر', 'فا. من هَاجَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من هَاجَرَ). 1.""عَامِلٌ مُهَاجِرٌ"" : مُغْتَرِبٌ، أَيْ مَنْ يَشْتَغِلُ فِي بِلاَدٍ أَجْنَبِيَّةٍ، فِي بِلاَدِ الهِجْرَةِ. 2. التوبة آية 100 والسَّابِقُونَ الأَوَّلُونَ مِنَ الْمُهَاجِرينَ والأَنْصَارِ (قرآن) : الرِّجَالُ الَّذِينَ هَاجَرُوا مَعَ النَبِيِّ ( مِنْ مَكَّةَ إِلَى الْمَدِينَةِ. 3.""طُيُورٌ مُهَاجِرَةٌ"" : الطُّيُورُ الْمُتَنَقِّلَةُ مِنْ مِنْطَقَةٍ إِلَى مِنْطَقَةٍ خِلاَلَ فُصُولِ السَّنَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4142, 'مُهَاجِمٌ', 'مهاجم', 'اسم فاعل', 'هجم', 'مهاجم', 'مهجم', 'فا. من هَاجَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من هَاجَمَ). 1.""جُنْدِيٌّ مُهاجِمٌ"" : مُنْدَفِعٌ فَجْأَةً إلى الْمَعْرَكَةِ. 2.""الْمُهَاجِمُ الأَيْمَنُ فِي فَرِيقِ كُرَةِ القَدَمِ"" : اللاَّعِبُ الَّذِي يَحْتَلُّ مَكَانَةً فِي صَفِّ مُدَافِعِ الْخَصْمِ. ""الْمُهَاجِمُ الأَيْسَرُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4143, 'هَائِدٌ', 'هائد', 'اسم فاعل', 'هود', 'هاءد', 'هد', 'فا. من هَادَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":هُودٌ"', '', '', '', '', '', '', '', '', '"(فا. من هَادَ). ""رَجُلٌ هَائِدٌ"" : تَائِبٌ، عَائِدٌ إِلَى الْحَقِّ وَالصَّوَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4144, 'هُودٌ', 'هود', 'اسم فاعل', '', 'هود', 'هد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
