INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4146, 'مُهَادِنٌ', 'مهادن', 'اسم فاعل', 'هدن', 'مهادن', 'مهدن', 'فا. من هَادَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من هَادَنَ). ""رَجُلٌ مُهادِنٌ"" : مُصَالِحٌ، غَيْرُ مُناوِئٍ، مُسالِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4147, 'هَائِفٌ', 'هائف', 'اسم فاعل', 'هيف', 'هاءف', 'هف', 'فا. من هَافَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"هَائِفٌ-هَائِفٌ، ةٌ [هـ ي ف] (فا. من هَافَ). ""وَجَدَ وَلَدَهُ هَائِفاً"" : شَدِيدَ الْعَطَشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4148, 'هوائف', 'هوائف', 'اسم فاعل', '', 'هواءف', 'هف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4149, 'هَائِلٌ', 'هائل', 'اسم فاعل', 'هول', 'هاءل', 'هل', 'فا. من هَالَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"هَائِلٌ-هَائِلٌ، ةٌ [هـ و ل] (فا. من هَالَ). 1.""عَمَلٌ هَائِلٌ"" : عَظِيمٌ، كَبِيرٌ. ""يَتَمَتَّعُ الْجَيْشُ بِقُوَّةٍ هَائِلَةٍ"" ""كَانَتْ أَمَامَهُ صُعُوبَاتٌ هَائِلَةٌ"" ""مَعْرَكَةٌ هَائِلَةٌ"" ""هُنَالِكَ الْفَارِقُ الْهَائِلُ بَينَ مَا يُبَاعُ بِدِرْهَمٍ وَمَا لَيْسَ يُبَاعُ بِكُنُوزِ الأَرْضِ"". (ع. م. العقاد). 2.""دَوَىَ صَوْتٌ هَائِلٌ"" : مُفْزِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4150, 'هوائل', 'هوائل', 'اسم فاعل', '', 'هواءل', 'هل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4151, 'هَائِمٌ', 'هائم', 'اسم فاعل', 'هيم', 'هاءم', 'هم', 'فا. مِنْ هَامَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":هُيَّمٌ:هُيَّامٌ"', '', '', '', '', '', '', '', '', '"(فا. مِنْ هَامَ). 1.""اِنْطَلَقَ هَائِماً عَلَى وَجْهِهِ بَيْنَ الْوِدْيَانِ وَالْجِبَالِ"" : ضَائِعاً، تَائِهاً، لاَ يَعْرِفُ إِلَى أَيْنَ هُوَ مُتَّجِهٌ، مُتَحَيِّراً. 2. ""كَانَ هَائِماً فِي حُبِّهَا"" : مَجْنُوناً بِهَا. تَرَكَتْنِي هَائِمًا أَبْكِي لِمَرْزِئَة*فِي مَنْزِلٍ مُوحَشٍ مِنْ بَعْدِ إِينَاس (عمران بن حطان)."', '');
