INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4159, 'هَابِلٌ', 'هابل', 'اسم فاعل', 'هبل', 'هابل', 'هبل', 'فا. من هَبَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"هَابِلٌ-هَابِلٌ [هـ ب ل] (فا. من هَبَلَ). 1.""اِمْرَأَةٌ هَابِلٌ"" : ثَكْلَى، أَيْ فَقَدَتْ وَلَدَهَا . 2.""تَاجِرٌ هَابِلٌ"" : كَاسِبٌ أَوْ مُحْتَالٌ. 3.""وَلَدٌ هَابِلٌ"" : غَلِيظٌ، ثَخِينٌ."', '');
