INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4167, 'هَاجِي', 'هاجي', 'اسم فاعل', 'هجو', 'هاجي', 'هج', 'فا. من هَجَا', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"هَاجٍ-هَاجٍ، الْهَاجِي، ةٌ [هـ ج و] (فا. من هَجَا). ""عَرَفَهُ النَّاسُ بِالْهَاجِي لِلْأَقْرَبِينَ وَالأَبْعَدِينَ"" : الْمُعَدِّدُ لِمَعَايِبِهِمْ."', '');
