INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4188, 'هَادٌّ', 'هاد', 'اسم فاعل', 'هدد', 'هاد', 'هد', 'فا. من هَدَّ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"هَادٌّ-هَادٌّ، ةٌ [هـ د د] (فا. من هَدَّ). 1.""بَحْرٌ هَادٌّ"" : أَيْ يُسْمَعُ لِأَمْوَاجِهِ صَوْتٌ. 2.""وَجَدَهُ هَادّاً"" : مَوْهُوناً، مَنْهُوكَ الْقُوَى."', '');
