INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4192, 'هَادِئٌ', 'هادئ', 'اسم فاعل', 'هدأ', 'هادء', 'هد', 'فا. مِن هَدَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِن هَدَأَ). 1.""جَلَسَ هَادِئاً فِي زَاوِيَةِ الْغُرْفَةِ"" : سَاكِناً. ""اِرْتَسَمَت اِبْتِسَامَةٌ هَادِئَةٌ عَلَى مُحَيَّاهُ"" ""شَابٌّ هَادِئُ الْقَلْبِ وَالطَّبْعِ"". 2.""الْبَحْرُ الْهَادِئُ"" (جغ) : بَحْرٌ يُحِيطُ بِأَمْرِيكَا وَأُسْتُرَالِيَا، تَبْلُغُ مِسَاحَتُهُ 180 مليون كلم مربع."', '');
