INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4194, 'مُهَدِّئٌ', 'مهدئ', 'اسم فاعل', 'هدأ', 'مهدء', 'مهد', 'فا. من هَدَّأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من هَدَّأَ). 1.""جَاءَ مُهَدِّئاً مِنْ رَوْعِهِ"" : مُسَكِّناً مُخَفِّفاً مِنْ رَوْعِهِ. ""دَوَاءٌ مُهَدِّئٌ لِلأَوْجَاعِ"". 2.""الْمُهَدِّئُ فِي الفِيزِيَاءِ"" : مَادَّةٌ تُسْتَعْمَلُ فِي نَوْعٍ مِنَ الْمُفَاعِلاَتِ النَّوَوِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4195, 'مُهَدِّدٌ', 'مهدد', 'اسم فاعل', 'هدد', 'مهدد', 'مهد', 'فا. من هَدَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من هَدَّدَ). ""جاءهُ مُهَدِّداً"" : مُخَوِّفاً، مُتَوَعِّداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4196, 'هَادِرٌ', 'هادر', 'اسم فاعل', 'هدر', 'هادر', 'هدر', 'فا. من هَدَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":هَوَادِرُ"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من هَدَرَ). 1.""رَعْدٌ هَادِرٌ"" : مُدَوٍّ، صَاخِبٌ. ""هَوَتِ الْقُنْبُلَةُ هَادِرَةً كَالرَّعْدِ لاَ تُفَرِّقُ بَيْنَ قَصْرٍ وَكُوخٍ"". 2.""أَرْضٌ هَادِرَةٌ"" : خِصْبَةٌ، أَيْ مَلِيئَةٌ بِالنَّبَاتَاتِ."', '');
