INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4251, 'مُهَلِّلٌ', 'مهلل', 'اسم فاعل', 'هلل', 'مهلل', 'مهل', 'فا. من هَلَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من هَلَّلَ). 1.""جَاءهُ مَهَلِّلاً"" : مَصَفِّقاً، مُعَبِّراً عن فَرَحِهِ. ""كَانَ مِنْ بَيْنِ الْمُهَلِّلِينَ والْمُسْتَبْشِرينَ بِالأَخْبارِ السَّارَّةِ"". 2.""رَفَعَ الْمُسْلِمُ صَوْتَهُ مُهَلِّلاً"" : قَائِلاً: ""لاَ إِلَهَ إِلاَّ اللهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4252, 'مُهِمٌّ', 'مهم', 'اسم فاعل', 'همم', 'مهم', 'مهم', 'فا. من هَمَّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُهِمٌّ-مُهِمٌّ، ةٌ [هـ م م] (فا. من هَمَّ). 1.""أَمْرٌ مُهِمٌّ"" : أَمْرٌ شَدِيدُ الأَهَمِّيَّةِ. ""دَرْسٌ مُهِمٌّ"" ""قَضِيَّةٌ مُهِمَّةٌ"". 2.""مِنَ الْمُهِمِّ أَنْ تَحْضُرَ"" : مِنَ الْمُفِيدِ. 3. ""الْمُهِمُّ فِي هَذِهِ الْمَسْأَلَةِ"" : الأَسَاسِيُّ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4253, 'هَامِدٌ', 'هامد', 'اسم فاعل', 'همد', 'هامد', 'همد', 'فا. من هَمَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:اتهَوَامِدُ"', '', '', '', '', '', '', '', '', '"(فا. من هَمَدَ). 1.""وَجَدَهُ هَامِداً لاَ رُوحَ فِيهِ"" : سَاكِناً لاَحَرَكَةَ فِيهِ. ""سَقطَ جُثَّةً هَامِدَةً"". 2.""نَارٌ هَامِدَةٌ"" : مُطْفأَةٌ. 3.""نَبَاتٌ هَامِدٌ"": يَابِسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4254, 'هَوَامِدُ', 'هوامد', 'اسم فاعل', '', 'هوامد', 'همد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
