INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4263, 'هَامِسٌ', 'هامس', 'اسم فاعل', 'همس', 'هامس', 'همس', 'فا. من هَمَسَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من هَمَسَ). 1.""صَوْتٌ هَامِسٌ"" : صَوْتٌ بِهِ وَشْوَشَةٌ. ""تُرَدِّدُ كَلِمَاتٍ مُبْهَمَةً بِصَوْتٍ هَامِسٍ"" ""الْكُلُّ يُرَدِّدُ هَامِساً بِالْأَدْعِيَةِ وَالتَّسَابِيحِ"". (عبد الحكيم قاسم). 2.""هَامِسٌ فِي أُذُنِهِ بِسِرٍّ"" : مُوَشْوِشٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4264, 'هوامس', 'هوامس', 'اسم فاعل', '', 'هوامس', 'همس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
