INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4266, 'هَاوِي', 'هاوي', 'اسم فاعل', 'هوي', 'هاوي', 'ه', 'فا. من هَوِيَ', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":هُوَاةٌ"', '', '', '', '', '', '', '', '', '"(فا. من هَوِيَ). ""هَاوٍ لِلْفُنُونِ الْجَمِيلَةِ"" : مُولَعٌ بِهَا دُونَ أَنْ يَتَّخِذَهَا حِرْفَةً لِلِارْتِزَاقِ بِهَا. ""مِنْ هُوَاةِ جَمْعِ الطَّوَابِعِ الْبَرِيدِيَّةِ"" ""فِرْقَةُ الْمَسْرَحِ لِلْهُوَاةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4267, 'هَامِشٌ', 'هامش', 'اسم فاعل', 'همش', 'هامش', 'همش', 'فا. من هَمَشَ', '', '', 'مفرد', '', '', '', '"هَوَامِشُ"', '', '', '', '', '', '', '', '', '"(فا. من هَمَشَ). 1.""عَلَى هَامِشِ الدَّفْتَرِ"" : عَلَى حَاشِيَتِهِ. 2.""يَعِيشُ عَلَى هَامِشِ الْمُجْتَمَعِ"" : خَارِجَ سِيَاقِ الْمُجْتَمَعِ. 3. ""تَرَكَهُ عَلَى الْهَامِشِ"" : عَلَى الْجَانِبِ. 4. ""عَلَى هَامِشِ الْحَدَثِ"" : بِمُنَاسَبَة. 5.""عَلَى هَامِشِ الْأَخْبَارِ"" : تَعْلِيقاً عَلَى مَا وَرَدَ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4268, 'هَوَامِشُ', 'هوامش', 'اسم فاعل', '', 'هوامش', 'همش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4269, 'هَامِعٌ', 'هامع', 'اسم فاعل', 'همع', 'هامع', 'همع', 'فا. من هَمَعَ', '', 'Ta', 'مفرد', 'DnT', '', '', '"هَوَامِعُ"', '', '', '', '', '', '', '', '', '"(فا. من هَمَعَ). 1.""طَرْفٌ هَامِعٌ"" : سَيَّالٌ. 2. ""دُمُوعٌ هَوَامِعُ"" : سَيَّالَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4270, 'هَوَامِعُ', 'هوامع', 'اسم فاعل', '', 'هوامع', 'همع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4271, 'مُهَمْهِمٌ', 'مهمهم', 'اسم فاعل', 'همهم', 'مهمهم', 'مهمهم', 'فا. من هَمْهَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من هَمْهَمَ). ""كَانَ يُحَرِّكُ شَفَتَيْهِ مُهَمْهِماً"" : مُتَكَلِّماً بِكَلاَمٍ غَيْرِ مَفْهُومٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4272, 'هَانِئٌ', 'هانئ', 'اسم فاعل', 'هنأ', 'هانء', 'هن', 'فا. من هَنَأَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من هَنَأَ). 1.""هَانِئٌ فِي بَيْتِهِ"" : مُسْتَرِيحٌ، سَعِيدٌ، مُطْمَئِنٌّ. ""وَجَدَ فِي إِقَامَتِهِ الْجَدِيدَةِ حَيَاةً هَانِئَةً"". 2.""هَانِئٌ"" : اِسْمُ عَلَمٍ لِلْمُذَكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4273, 'هوانئ', 'هوانئ', 'اسم فاعل', '', 'هوانء', 'هن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4274, 'هناء', 'هناء', 'اسم فاعل', '', 'هناء', 'هن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4275, 'هنأة', 'هنأة', 'اسم فاعل', '', 'هنءة', 'هنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4276, 'مُوَارِبٌ', 'موارب', 'اسم فاعل', 'ورب', 'موارب', 'مرب', 'فا. من وَارَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من وَارَبَ). ""رَجُلٌ مُوَارِبٌ فِي كَلاَمِهِ"" : مُخَادِعٌ، مُخَاتِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4277, 'هُوَاةٌ', 'هواة', 'اسم فاعل', '', 'هواة', 'هة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4278, 'هَاوِي', 'هاوي', 'اسم فاعل', 'هوي', 'هاوي', 'ه', 'فا. من هَوَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:"', '', '', '', '', '', '', '', '', '"(فا. من هَوَى). 1.""رآهُ هَاوِياً مِنْ أَعْلَى الْجَبَلِ"" : سَاقِطاً. 2.""سَقَطَ فِي الْهَاوِيَةِ"" : الشَّرْخُ الْعَمِيقُ فِي الأَرْضِ. 3. القارعة آية 9وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ فَأُمُّهُ هَاوِيَةٌ. (قرآن) : نَارُ جَهَنَّمَ. 4.""اِمْرَأَةٌ هَاوِيَةٌ"" : فَقَدَتْ وَلَدَهَا، ثَكْلَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4279, 'هواة', 'هواة', 'اسم فاعل', '', 'هواة', 'هة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4280, 'مُهَيِّجٌ', 'مهيج', 'اسم فاعل', 'هيج', 'مهيج', 'مهج', 'فا. من هَيَّجَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من هَيَّجَ). 1.""مُهَيِّجُ الْجُمْهُورِ"" : مُحَرِّضٌ. 2.""عَقَّارٌ مُهَيِّجٌ"" : مُثِيرٌ للِشَّهْوَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4281, 'مُهَيْمِنٌ', 'مهيمن', 'اسم فاعل', 'هيمن', 'مهيمن', 'مهمن', 'فا. من هَيْمَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من هَيْمَنَ). 1.""هُوَ اللهُ الْمُهَيْمِنُ"" : مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى بِمَعْنَى الْمُؤْتَمَنُ الْمُسَيْطِرُ عَلَى كُلِّ شَيْءٍ، الْحَافِظُ لَهُ. 2.""مُهَيْمِنٌ عَلَى كُلِّ تِجَارَةِ الْبِلاَدِ"" : مُسَيْطِرٌ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4282, 'وَاثِقٌ', 'واثق', 'اسم فاعل', 'وثق', 'واثق', 'ثق', 'فَا. من وَاثَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. من وَاثَقَ). 1.""وَاثِقٌ بِصَاحِبِهِ"" : مُؤْتَمِنٌ. 2.""وَاثِقٌ مِنْ كَلاَمِهِ"" : مُتَأَكِّدٌ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4283, 'وثاق', 'وثاق', 'اسم فاعل', '', 'وثاق', 'ثق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4284, 'وثقة', 'وثقة', 'اسم فاعل', '', 'وثقة', 'ثقة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4285, 'مُوَاجِهٌ', 'مواجه', 'اسم فاعل', 'وجه', 'مواجه', 'مجه', 'فا. من وَاجَهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من وَاجَهَ). ""مُوَاجِهٌ لِكُلِّ الصُّعُوبَاتِ"" : مُجَابِهٌ، مُقَاوِمٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4286, 'وَابِلٌ', 'وابل', 'اسم فاعل', 'وبل', 'وابل', 'بل', 'فا. مِنْ وَبَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"وَابِلٌ-وَابِلٌ، ةٌ [و ب ل] (فا. مِنْ وَبَلَ). 1.""أَمْطَرَتِ السَّمَاءُ وَابِلاً مِنَ الْمَطَرِ"" : مَطَراً شَدِيداً. 2.""رَجُلٌ وَابِلٌ"" : جَوَادٌ، سَخِيٌّ، كَرِيمٌ. 3.""أَمْطَرَهُ بِوَابِلٍ مِنَ الشَّتَائِمِ"" : أَيْ شَتَمَهُ شَتَائِمَ كَثِيرَةً. ""أَمْطَرَهُ بِوَابِلٍ مِنَ الرَّصَاصِ"". 4.""وَابِلَةُ العَضُدِ أَوِ الفَخِذِ"" : طَرَفُ رَأْسِهِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4287, 'مُوَازِنٌ', 'موازن', 'اسم فاعل', 'وزن', 'موازن', 'مزن', 'فا. من وَازَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُوَازِنٌ-مُوَازِنٌ، ةٌ [و ز ن] (فا. من وَازَنَ). ""مَصَارِيفُ مُوَازِنَةٌ لِلْمَدَاخِيلِ"" : مُسَاوِيَةٌ، مُعَادِلَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4288, 'مُوَازِي', 'موازي', 'اسم فاعل', 'وزي', 'موازي', 'مز', 'فا. من وَازَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من وَازَى). 1.""عَمَلُهُ مُوَازٍ لِعَمَلِ زَمِيلِهِ"" : مُقَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4289, 'مُوَاسِي', 'مواسي', 'اسم فاعل', 'وسي', 'مواسي', 'مس', 'فا. من وَاسَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من وَاسَى). ""زَارَهُ مُوَاسِياً"" : مُخَفِّفاً عَنْهُ أَسَاهُ وَحُزْنَهُ وَمُصَابَهُ. ""أَحَاطُوا بِهِ مُوَاسِينَ وَمُعَزِّينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4290, 'مُوَاطِنٌ', 'مواطن', 'اسم فاعل', 'وطن', 'مواطن', 'مطن', 'فا. من وَاطَنَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من وَاطَنَ). ""مُوَاطِنٌ صَالِحٌ"" : مَنْ نَشَأَ فِي وَطَنٍ وَاحِدٍ وتَرَعْر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4291, 'مُوَاظِبٌ', 'مواظب', 'اسم فاعل', 'وظب', 'مواظب', 'مظب', 'فا. من وَاظَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من وَاظَبَ). ""تِلْمِيذٌ مُوَاظِبٌ عَلَى العَمَلِ"" : مُدَاوِمٌ، مُوَاكِبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4292, 'مُوَافِقٌ', 'موافق', 'اسم فاعل', 'وفق', 'موافق', 'مفق', 'فا. من وَافَقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من وَافَقَ). 1.""مُوَافِقٌ عَلَى مَاجَاءَ فِي كَلاَمِهِ"" : مُتَّفِقٌ. 2.""أَقْوَالُهُ مُوَافِقَةٌ لِعَمَلِهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4293, 'مُوَاكِبٌ', 'مواكب', 'اسم فاعل', 'وكب', 'مواكب', 'مكب', 'فا. من وَاكَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من وَاكَبَ). 1.""مُوَاكِبٌ عَلَى العَمَلِ"" : مُوَاظِبٌ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4294, 'مُوَالِي', 'موالي', 'اسم فاعل', 'ولي', 'موالي', 'مل', 'فا. من وَالَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. من وَالَى). 1.""مُوَالٍ لآرَاءِ زَمِيلِهِ"" : مُنَاصِرٌ لَهَا. 2.""مُوَالٍ لِرَئِيسِهِ"" : مُحِبٌّ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4295, 'مُوَبِّخٌ', 'موبخ', 'اسم فاعل', 'وبخ', 'موبخ', 'مبخ', 'فا. من وَبَّخَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من وَبَّخَ). ""سَأَلَهُ مُوَبِّخاً"" : مُؤَنِّباً لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4296, 'وبال', 'وبال', 'اسم فاعل', '', 'وبال', 'بل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4297, 'وبلة', 'وبلة', 'اسم فاعل', '', 'وبلة', 'بلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4298, 'وَاتِدٌ', 'واتد', 'اسم فاعل', 'وتد', 'واتد', 'تد', 'فَا. من وَتَدَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وَاتِدٌ-وَاتِدٌ [و ت د] (فَا. من وَتَدَ). 1.""وَتَدٌ وَاتِدٌ"" : ثَابِتٌ. 2.""تِمْثَالٌ وَاتِدٌ"" : مُنْتَصِبٌ، قَائِمٌ. ""قَرْنٌ وَاتِدٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4299, 'وَاثِبٌ', 'واثب', 'اسم فاعل', 'وثب', 'واثب', 'ثب', 'فَا. من وَثَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"وَاثِبٌ-وَاثِبٌ [و ث ب] (فَا. من وَثَبَ). ""اِنْدَفَعَ وَاثِباً مِنْ أَعْلَى الشَّجَرَةِ"" : قَافِزاً قَفْزَةً وَاحِدَةً. ""يَنْدَفِعُ مُسْرِعاً كَأَنَّهُ وَاثِبٌ إِلَى الْمُسْتَقْبَلِ"". (م. ص. الرافعي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4300, 'وثاب', 'وثاب', 'اسم فاعل', '', 'وثاب', 'ثب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4301, 'وثبة', 'وثبة', 'اسم فاعل', '', 'وثبة', 'ثبة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4302, 'مُوَثِّقٌ', 'موثق', 'اسم فاعل', 'وثق', 'موثق', 'مثق', 'فا. من وَثَّقَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من وَثَّقَ). ""مُوَثِّقُ العُقُودِ"" : مَنْ يُسَجِّلُ العُقُودَ ويُوَثِّقُهَا حَسَبَ الإِجْرَاءاتِ القَانُونِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4303, 'وَاثِنٌ', 'واثن', 'اسم فاعل', 'وثن', 'واثن', 'ثن', 'فا. مِنْ وَثَنَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وَاثِنٌ-وَاثِنٌ [و ث ن] (فا. مِنْ وَثَنَ). ""أَمْرٌ وَاثِنٌ"" : مُقِيمٌ، ثَابِتٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4304, 'وَاجِبٌ', 'واجب', 'اسم فاعل', 'وجب', 'واجب', 'جب', 'فَا. من وَجَبَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(فَا. من وَجَبَ). 1.""قَامَ بِالوَاجِبِ"" : بِاللاَّزِمِ وَمَا هُوَ ضَرُورِيٌّ، وَيَتَحَتَّمُ عَلَيْهِ فِعْلُهُ. ""الوَاجِبُ الوَطَنِيُّ"" ""الأَعْمَالُ الوَاجِبُ إِنْجَازُهَا"" ""عَلَى الْمُوَاطِنِ وَاجِبَاتٌ وَلَهُ حُقُوقٌ"" ""لاَ يُقَصِّرُ فِي وَاجِبِهِ"". 2.""أَنْجَزَ الطَّالِبُ وَاجِبَاتِهِ الْمَدْرَسِيَّةَ"" : تَمَارِينَهُ. ""عَلَى الطَّالِبِ أَلاَّ يُؤَخِّرَ وَاجِبَاتِ يَوْمِهِ لِغَدِهِ"". 3.""الوَاجِبُ"" : مَا يُقَابِلُ الْجَائِزَ وَالمُمْكِنَ وَالمُمْتَنِعَ. 4.""القِيَامُ بِأَرْكَانِ الإِسْلاَمِ وَاجِبٌ"" : مَا يُثَابُ عَلَى فِعْلِهِ وَيُعَاقَبُ عَلَى تَرْكِهِ. 5.""وَاجِبُ الوُجُودِ"" : هُوَ الَّذِي يَكُونُ وُجُودُهُ مِنْ ذَاتِهِ، وَلاَ يَحْتَاجُ إِلَى شَيْءٍ، اللَّهُ تَعَالَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4305, 'وَاجِدٌ', 'واجد', 'اسم فاعل', 'وجد', 'واجد', 'جد', 'فَا. من وَجَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. من وَجَدَ). 1.""وَاجِدٌ ضَالَّتَهُ"" : مُدْرِكُهَا، مُلاقِيها. ""وَاجِدٌ فيِ سُلُوكِهِ مِثَالَ الْمُرُوءةِ"". 2.""وَاجِدٌ بِحُبِّهَا"" : مُحِبٌّ، عَاشِقٌ. 3.""هُوَ اللَّهُ الوَاجِدُ"" : مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى، أَيِ الغَنِيُّ الَّذِي لاَ يَفْتَقِرُ. 4.""رَجُلٌ وَاجِدٌ"" : الْمُوسِرُ، الغَنِيُّ عَنِ النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4306, 'وجاد', 'وجاد', 'اسم فاعل', '', 'وجاد', 'جد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4307, 'وجدة', 'وجدة', 'اسم فاعل', '', 'وجدة', 'جدة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4308, 'وَاجِزٌ', 'واجز', 'اسم فاعل', 'وجز', 'واجز', 'جز', 'فَا. من وَجَزَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وَاجِزٌ-وَاجِزٌ، ةٌ [و ج ز] (فَا. من وَجَزَ). ""كَلاَمٌ وَاجِزٌ"" : مُخْتَصَرٌ قَصِيرٌ، سَرِيعُ الفَهْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4309, 'وَاجِسٌ', 'واجس', 'اسم فاعل', 'وجس', 'واجس', 'جس', 'فَا. من وَجَسَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وَاجِسٌ-وَاجِسٌ، ةٌ [و ج س] (فَا. من وَجَسَ). ""اِسْتَبَدَّ بِهِ وَاجِسٌ مِنَ الوَهْمِ"" : هَاجِسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4310, 'وَاجِفٌ', 'واجف', 'اسم فاعل', 'وجف', 'واجف', 'جف', 'فَا. من وَجَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. من وَجَفَ). ""قَلْبٌ وَاجِفٌ"" : خَافِقٌ، مُضْطَرِبٌ.النازعات آية 8قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ ( قرآن) ""صَوْتُهُ وَاجِفٌ يُثِيرُ الشَّفَقَةَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4311, 'وجاف', 'وجاف', 'اسم فاعل', '', 'وجاف', 'جف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4312, 'وجفة', 'وجفة', 'اسم فاعل', '', 'وجفة', 'جفة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4313, 'وَاجِمٌ', 'واجم', 'اسم فاعل', 'وجم', 'واجم', 'جم', 'فَا. من وَجَمَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. من وَجَمَ). ""وَجْهٌ وَاجِمٌ"" : عَابِسٌ مِنْ شِدَّةِ هَمٍّ أَوْ حُزْنٍ. ""دَخَلَتْ سَاهِمَةً وَاجِمَةً تَدْعَكُ أَصَابِعَهَا فِي قَلَقٍ"" (محمود تيمور)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4314, 'وجام', 'وجام', 'اسم فاعل', '', 'وجام', 'جم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
