INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4316, 'وجمة', 'وجمة', 'اسم فاعل', '', 'وجمة', 'جمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4317, 'مُوَجِّهٌ', 'موجه', 'اسم فاعل', 'وجه', 'موجه', 'مجه', 'فا. من وَجَّهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من وَجَّهَ). ""مُوَجِّهٌ لِطُلاَّبِهِ"" : مُرْشِدٌ لَهُمْ بِتَوْجِيهَاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4318, 'مُوَحِّدٌ', 'موحد', 'اسم فاعل', 'وحد', 'موحد', 'محد', 'فا. من وَحَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من وَحَّدَ). 1.""كَانَ مُوَحِّداً فِي دِينِهِ"" : مَنْ يَعْتَقِدُ بِوَحْدَانِيَّةِ الله. 2.""مُوَحِّدُ البِلاَدِ"" : مَنْ جَمَعَ أَقَالِيمَهَا ووَحَّدَ بَيْنَها."', '');
