INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4326, 'وَارِمٌ', 'وارم', 'اسم فاعل', 'ورم', 'وارم', 'رم', 'فَا. من وَرِمَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وَارِمٌ-وَارِمٌ، ةٌ [و ر م] (فَا. من وَرِمَ). ""جِلْدٌ وَارِمٌ"" : مُنْتَفِخٌ مِنْ مَرَضٍ. ""أَنْفٌ وَارِمٌ""."', '');
