INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4344, 'وَاسِطٌ', 'واسط', 'اسم فاعل', 'وسط', 'واسط', 'سط', 'فَا. من وَسَطَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"وَاسِطٌ-وَاسِطٌ، ةٌ [و س ط] (فَا. من وَسَطَ). 1.""جَلَسَ وَاسِطاً بَيْنَ أَهْلِهِ"" : الجَالِسُ وَسَطَهُمْ. ""كَانَ الوَاسِطَ فِي بَهْوِ الدَّارِ"". 2.""وَاسِطَةُ العِقْدِ"" : الْجَوْهَرَةُ الكَبِيرَةُ وَسَطَ العِقْدِ. 3.""هُوَ وَاسِطَةُ قَوْمِهِ"" : مِنْ أَفَاضِلِهِمْ، أَخْيَارِهِمْ. 4.""الغَايَةُ تُبَرِّرُ الوَاسِطَةَ"" : تُبَرِّرُ الوَسِيلةَ، العِلَّةَ. 5.""حَصَلَ عَلَى مَنْصِبٍ بِوَاسِطَةِ أَحَدِ أَقْرِبَائِهِ"" : أَيْ بِمُسَاعَدَةِ تَدَخُّلِهِ."', '');
