INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4377, 'وَاعِي', 'واعي', 'اسم فاعل', 'وعي', 'واعي', 'ع', 'فَا. من وَعَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. من وَعَى). 1.""وَاعِي اليَتِيم"" : وَصِيُّهُ، حَافِظُهُ. 2.""مَلَأَتِ الوَاعِيَةُ أَصْدَاءَ الْحَيِّ"" : الصُّرَاخُ عَلَى الْمَيِّتِ، الصَّوْتُ الْمُرْتَفِعُ. 3.""وَ"', '');
