INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4380, 'وَاغِلٌ', 'واغل', 'اسم فاعل', 'وغل', 'واغل', 'غل', 'فَا. من وَغَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"وَاغِلٌ-وَاغِلٌ، ةٌ [و غ ل] (فَا. من وَغَلَ). 1.""وَاغِلٌ إِلَى الوَلِيمَةِ"" : الآتِي إِلَيْهَا وَهُوَ غَيْرُ مَدْعُوٍّ إِلَيْهَا. 2. ""وَاغِلٌ فِي سَ"', '');
