INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4383, 'وَافِدٌ', 'وافد', 'اسم فاعل', 'وفد', 'وافد', 'فد', 'فَا. من وَفَدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات:وُفُودٌ"', '', '', '', '', '', '', '', '', '"(فَا. من وَفَدَ). 1.""وَافِدٌ مِنْ مَكَانٍ بَعِيدٍ"" : آتٍ، وَاصِلٌ، قَاد"', '');
