INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4387, 'وَافِرٌ', 'وافر', 'اسم فاعل', 'وفر', 'وافر', 'فر', 'فَا. من وَفَرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"وَافِرٌ-وَافِرٌ، ةٌ [و ف ر] (فَا. من وَفَرَ). 1.""مَالٌ وَافِرٌ"" : كَثِيرٌ. 2.""زَارَ الْمُتْحَفَ عَدَدٌ وَافِرٌ مِنَ الزُّوَارِ"" : عَدَدٌ كَثِيرٌ، هَائِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4388, 'وفار', 'وفار', 'اسم فاعل', '', 'وفار', 'فر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
