INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4390, 'وَافِي', 'وافي', 'اسم فاعل', 'وفي', 'وافي', 'ف', 'فَا. من وَفَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"وَافٍ-وَافٍ، الوَافِي، ةُ [و ف ي] (فَا. من وَفَى). ""شَرْحٌ وَافٍ"" : كَافٍ، تَامٌّ. ""شُرُوحٌ وَافِيَةٌ أَحَاطَتْ بِكُلِّ التَّفَاصِيلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4391, 'وفاة', 'وفاة', 'اسم فاعل', '', 'وفاة', 'فة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4392, 'مُوَقِّتٌ', 'موقت', 'اسم فاعل', 'وقت', 'موقت', 'مقت', 'فا. من وَقَّتَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"مَوْقِتٌ-مَوْقِتٌ [و ق ت]. ""مَوْقِتُ الصَّلاَةِ"" : تَوْقِيتُها، وَقْتُهَا الْمُحَدَّدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4393, 'وَاقِعٌ', 'واقع', 'اسم فاعل', 'وقع', 'واقع', 'قع', 'فَا. من وَقَعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":وُقَّعٌ:وُقُوعٌ"', '', '', '', '', '', '', '', '', '"(فَا. من وَقَعَ). 1.""أَمْرٌ وَاقِعٌ"" : حَاصِلٌ. 2. ""وَاقِعٌ عَلَى رَأْسِهِ لاَ مَحَالَةَ"" : سَاقِطٌ.أَلاَ يَا غُرَابَ البَيْنِ قَدْ طِرْتَ بِالَّذِي*أُحَاذِرُ مِنْ لَيْلَى فَهَلْ أَنْتَ وَاقِعُ. (قيس بن الملوح).3.""سِيَاسَةُ الأَمْرِ الوَاقِعِ"" : أَيْ الأَمْرُ السَّائِدُ. 4.""فِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4394, 'وُقَّعٌ', 'وقع', 'اسم فاعل', '', 'وقع', 'قع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4395, 'وُقُوعٌ', 'وقوع', 'اسم فاعل', '', 'وقوع', 'قع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4396, 'وقعة', 'وقعة', 'اسم فاعل', '', 'وقعة', 'قعة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4397, 'مُوَقِّعٌ', 'موقع', 'اسم فاعل', 'وقع', 'موقع', 'مقع', 'فا. من وَقَّعَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من وَقَّعَ). ""أَنَا الْمُوَقِّعُ أَسْفَلَهُ"" : أَنَا الْمُمْضِي أَسْفَلَهُ، أَيْ أَنَا صَاحِبُ التَّوْقِيعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4398, 'وَاقِفٌ', 'واقف', 'اسم فاعل', 'وقف', 'واقف', 'قف', 'فَا. من وَقَفَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":وُقُوفٌ"', '', '', '', '', '', '', '', '', '"(فَا. من وَقَفَ). 1.""وَاقِفٌ فِي الصَّفِّ"" : مُنْتَصِبٌ بِقَامَتِهِ، قَائِمٌ. 2.""وَاقِفٌ عَلَى بَابِهِ"" : مُنْتَظِرٌ. 3.""وَاقِفُ الوَقْفِ"" : الْمَسْؤُولُ عَنْ أَمْلاَكِ الأَوْقَافِ (الحُبُس). 4.""بِنَاءٌ وَاقِفٌ"" : بِنَاءٌ غَيِرُ مُهَدَّمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4399, 'وُقُوفٌ', 'وقوف', 'اسم فاعل', '', 'وقوف', 'قف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4400, 'وقاف', 'وقاف', 'اسم فاعل', '', 'وقاف', 'قف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4401, 'وقفة', 'وقفة', 'اسم فاعل', '', 'وقفة', 'قفة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4402, 'وَاقِي', 'واقي', 'اسم فاعل', 'وقي', 'واقي', 'ق', 'فَا. من وَقَى', 'Tk', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. من وَقَى). ""قِنَاعٌ وَاقٍ مِنَ الغَازَاتِ السَّامَّةِ"" : حَامٍ... ""دِرْعٌ وَاقٍ"" ""مِعْطَفٌ وَاقٍ مِنَ الْمَطَرِ"" ""رُفُوفٌ وَاقِيَةٌ مِنْ أَشِعَّةِ الشَّمْسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4403, 'وقاة', 'وقاة', 'اسم فاعل', '', 'وقاة', 'قة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4404, 'وَاكِفٌ', 'واكف', 'اسم فاعل', 'وكف', 'واكف', 'كف', 'فَا. من وَكَفَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وَاكِفٌ-وَاكِفٌ [و ك ف] (فَا. من وَكَفَ). ""مَطَرٌ وَاكِفٌ"" : شَدِيدُ التَّهَاطُلِ، مُنْهَمِرٌ، مُنْهَلٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4405, 'مُوَكِّلٌ', 'موكل', 'اسم فاعل', 'وكل', 'موكل', 'مكل', 'فا. من وَكَّلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من وَكَّلَ). ""طَلَبَ مِنَ الْمُوَكِّلِ تَوْكِيلاً"" : الْمُفَوِّضِ الَّذِي يُفَوِّضُ أُمُورَهُ إِلَى شَخْصٍ آخَرَ لِيُكَلِّفَهُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4406, 'وَاكِنٌ', 'واكن', 'اسم فاعل', 'وكن', 'واكن', 'كن', 'فَا. من وَكَنَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":وُكُونٌ"', '', '', '', '', '', '', '', '', '"(فَا. من وَكَنَ). 1.""طَيْرٌ وَاكِنٌ"" : قَابِعٌ فِي عُشِّهِ. 2. : طَائِرٌ وَاكِنٌ مِنْ أَعْلَى الشَّجَرَةِ"" : وَاقِعٌ حَيْثُمَا وَقَعَ. 3.""طُيُورٌ وَاكِنَةٌ"" : مُحْتَضِنَةٌ لِبَيْضِهَا. ""حَمَامٌ وُكُونٌ""."', '');
