INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4408, 'مُوَلِّدٌ', 'مولد', 'اسم فاعل', 'ولد', 'مولد', 'ملد', 'فا. من وَلَّدَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فا. من وَلَّدَ). 1.""الْمَرْأَةُ الْمُوَلِّدَةُ"" : الْمُخْتَصَّةُ بِتَوْلِيدِ النِّسَاءِ، القَابِلَةُ. ""طَبِيبٌ مُوَلِّدٌ"". 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4409, 'وَالِهٌ', 'واله', 'اسم فاعل', 'وله', 'واله', 'له', 'فَا. من وَلَهَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فَا. من وَلَهَ). ""مَا زَالَ وَالِهاً بِهَا"" : مُتَحَيَّراً بِهَا مِنْ شِدَّةِ الْحُبِّ و"', '');
