INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4412, 'مُوَلْوِلٌ', 'مولول', 'اسم فاعل', 'ولول', 'مولول', 'ملل', 'فا. مِن وَلْوَلَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(فا. مِن وَلْوَلَ). 1.""جَاءتْ مُوَلْوِلَةً"" : بَاكِيَةً صَائِ"', '');
