INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4418, 'وَاهِبٌ', 'واهب', 'اسم فاعل', 'وهب', 'واهب', 'هب', 'فَا. من وَهَبَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', 'Cv', '"(فَا. من وَهَبَ). ""الوَاهِبُ لِمَالِهِ فِي سَبِيلِ الخَيْرِ "" : الْمُقَدِّمُ لِمَالِهِ بِسَخَاءٍ وَبِلاَ عِوَضٍ."', '');
