INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4430, 'يَاسِرٌ', 'ياسر', 'اسم فاعل', 'يسر', 'ياسر', 'سر', 'فا. من يَسِرَ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":أَيْسَارٌ:يَوَاسِرُ"', '', '', '', '', '', '', '', '', '"(فا. من يَسِرَ). 1. ""عَمَلٌ يَاسِرٌ"" : سَهْلٌ. 2.""يَاسِرٌ فِي طَرِيقِهِ"" : الْمُتَّخِذُ لِلْيَسَارِ، خِلاَفُ الْيَامِنِ. 3.""الْيَاسِرُ فِي الْمَيْسِرِ"": الضَّارِبُ أَوِ اللاَّعِبُ فِي الْمَيْسِرِ، أَوِالَّذِي يَتَوَلَّى قِسْمَةَ جَزُورِ الْمَيْسِرِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4431, 'أَيْسَارٌ', 'أيسار', 'اسم فاعل', '', 'ءيسار', 'سر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
