INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4533, 'مُقَفّىً', 'مقفى', 'اسم مفعول', 'قفي', 'مقفى', 'مقف', 'مفع. من قَفَّى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"قَفّـىً - [ق ف ي]. (فا. من قَفَّى). 1. ""كَلاَمٌ مُقَفّـىً"" : فِيهِ سَجْعٌ، لَهُ قَافِيَةٌ، أَيْ تَوَافُقٌ عَلَى الْحَرْفِ الأَخِيرِ. 2."" رَجُلٌ مُقَفّىً بِهِ"" : مُحْتَفَىً بِهِ، مُكَرَّمٌ، مَحَطُّ تَشْرِيفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4534, 'مُقَفّاة', 'مقفاة', 'اسم مفعول', '', 'مقفاة', 'مقفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"قَفّـىً - [ق ف ي]. (فا. من قَفَّى). 1. ""كَلاَمٌ مُقَفّـىً"" : فِيهِ سَجْعٌ، لَهُ قَافِيَةٌ، أَيْ تَوَافُقٌ عَلَى الْحَرْفِ الأَخِيرِ. 2."" رَجُلٌ مُقَفّىً بِهِ"" : مُحْتَفَىً بِهِ، مُكَرَّمٌ، مَحَطُّ تَشْرِيفٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4535, 'مبتوت', 'مبتوت', 'اسم مفعول', '', 'مبتوت', 'مبتت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"قضية مبتوت فيها"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4536, 'مُضَافٌ', 'مضاف', 'اسم مفعول', 'ضيف', 'مضاف', 'مضف', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُضَافٌ-مُضَافٌ [ض ي ف]. 1.""الْمُضَافُ فِي النَّحْوِ"" : الاِسْمُ الَّذِي يُضَافُ إِلَيْهِ اسْمٌ آخَرُ طَلَباً لاَزِماً يُفِيدُ تَعْرِيفاً أَوْ تَخْصِيصاً. يُسَمَّى الأَوَّلُ مُضَافاً وَالثَّانِي مُضَافاً إِلَيْهِ، وَيَكُونُ مَجْرُوراً : ""قَلَمُ الرَّصَاصِ"". 2.""وَلَدٌ مُضَافٌ : خَائِفٌ. ""هَبَّ إِلَى نَجْدَةِ الْمُضَافِ"". 3.""رَجُلٌ مُضَافٌ"" : دَعِيٌّ، أَي مُنْتَسِبٌ إِلَى قَوْمٍ ولَيْسَ مِنْهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4537, 'مُبَيَّضَةٌ', 'مبيضة', 'اسم مفعول', 'بيض', 'مبيضة', 'مبضة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبَيَّضَةٌ-مُبَيَّضَةٌ [ب ي ض]. ""نُسْخَةٌ مُبَيَّضَةٌ"" : نَاصِعَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4538, 'مُبِينٌ', 'مبين', 'اسم مفعول', 'بين', 'مبين', 'مبن', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبَيَّنٌ-مُبَيَّنٌ [ب ي ن] (مفع. مِنْ بَيَّنَ). ""كَمَا هُوَ مُبَيَّنٌ"" : كَمَا هُوَ وَاضِحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4539, 'مُقَشَّرٌ', 'مقشر', 'اسم مفعول', 'قشر', 'مقشر', 'مقشر', 'مفع. من قَشَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَشَّرٌ، ةٌ - [ق ش ر]. (مفع. من قَشَّرَ). ""جَزَرٌ مُقَشَّرٌ"" : أُزِيلَتْ قِشْرَتُهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4540, 'مُهَبَّلٌ', 'مهبل', 'اسم مفعول', 'هبل', 'مهبل', 'مهبل', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". 1. مَنْ يُقَالُ لَهُ: ""هَبَلَتْكَ أُمُّكَ""، أَيْ فَقَدَتْكَ. 2. ""رَجُلٌ مُهَبَّلٌ"" : مَعْتُوهٌ، أَحْمَقُ، أَهْوَجُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4541, 'مُعَوَّضٌ', 'معوض', 'اسم مفعول', '', 'معوض', 'معض', '', '', 'ة', 'جمع تكسير', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"ج: ـون، ـات. (مفع. مِن عَوَّضَ). ""مُعَوَّضٌ عَنْ كُلِّ خَسَائِرِهِ"" : أَيْ عُوِّضَ بَدَلَ مَا خَسِرَهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4542, 'مَيْمُونٌ', 'ميمون', 'اسم مفعول', 'يمن', 'ميمون', 'ممن', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":ـ:مَيَامِينُ"', '', '', '', '', '', '', '', '', '". 1.""وَلَدٌ مَيْمُونٌ"" : ذُو يُمْنٍ وَبَرَكَةٍ. 2.""هُوَ مَيْمُونُ الطَّائِرِ"" : دُعَاءٌ لِلْمُسَافِرِ، أَيْ سِرْ مُوَفَّقاً تُصَاحِبُكَ السَّلاَمَةُ. ""زِيَارَةٌ مَيْمُونَةٌ"". 3.""قُدُومٌ مَيْمُونٌ"": قُدُومٌ مُبَارَكٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4543, 'مَيَامِينُ', 'ميامين', 'اسم مفعول', '', 'ميامين', 'ممن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4544, 'مُنْكَبٌّ', 'منكب', 'اسم مفعول', 'نكب', 'منكب', 'منكب', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". ""مُنْكَبٌّ عَلَى عَمَلِهِ"" : مُنْهَمِكٌ فِيهِ بِشَغَفٍ، مُسْتَغْرِقٌ فِيهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4545, 'مَنْدُوبٌ', 'مندوب', 'اسم مفعول', 'ندب', 'مندوب', 'مندب', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَنَادِيبُ"', '', '', 'ـو', '', '', '', '', '', '". 1.""مَيِّتٌ مَنْدُوبٌ"" : مَنْ يُنْدَبُ مِنَ الأَمْوَاتِ. 2.""أَمْرٌ مَنْدُوبٌ"": مُسْتَحَبٌّ فِعْلُهُ. 3.""الْمُنَادَى الْمَنْدُوبُ"" (نح) : الاِسْمُ يُنَادَى بِالوَاوِ وَهُوَ مَا يُعَبَّرُ بِهِ عَنِ التَّفَجُّعِ: ""وَامُعْتَصِمَاهُ!"": واو الاِسْتِغَاثَةِ. 4.""مَنْدُوبُ بِلاَدِهِ فِي الأُمَمِ الْمُتَّحِدَةِ"" : مُفَوَّضُهَا، مُمَثِّلُهَا يَقُومُ بِمُهِمَّةٍ نِيَابَةً عَنْهَا. ""مَنْدُوبُ الْجَرِيدَةِ"" ""مَنْدُوبُ الْحِـزْبِ"" ""مَنْدُوبُ الشَّرِكَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4546, 'مَنَادِيبُ', 'مناديب', 'اسم مفعول', '', 'مناديب', 'مندب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4547, 'مَنْجُورٌ', 'منجور', 'اسم مفعول', 'نجر', 'منجور', 'منجر', '', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '". ""أَرْضٌ مَنْجُورَةٌ"" : أَرْضٌ ذَاتُ مَسْلَكٍ غَيْرِ مُعَبَّدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4548, 'مَنْثُورٌ', 'منثور', 'اسم مفعول', 'نثر', 'منثور', 'منثر', '', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مَنْثُورٌ-مَنْثُورٌ، ةٌ [ن ث ر]. 1.""زَرْعٌ مَنْثُورٌ"" : مُتَفَرِّقٌ، مُتَشَتِّتٌ.الفرقان آية 23 فَجَعَلْنَاهُ هَبَاءً مَنْثُورا (قرآن). 2.""كَلاَمٌ مَنْثُورٌ"" : الكَلاَمُ الْمَكْتُوبُ نَثْراً عَكْسُ الْمَنْظُومِ. 3.""شِعْرٌ مَنْثُورٌ"" : كَلاَمٌ مُرْسَلٌ بِغَيْرِ وَزْنٍ ولاَ قَافِيَةٍ. 4.""أَزْهَرَ الْمَنْثُورُ بِأَشْكَالِهِ الْمُخْتَلِفَةِ وأَلْوَانِهِ الزَّاهِيَةِ"" : نَبَاتٌ ذُو زَهْرٍ زَكِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4549, 'مَدْعُوٌّ', 'مدعو', 'اسم مفعول', '', 'مدعو', 'مدع', '', '', 'ة', 'جمع تكسير', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"ج: ـون، ـات. 1.""مَدْعُوٌّ لِلْحَفْلَةِ"" : مَنْ وُجِّهَتْ إِلَيْهِ الدَّعْوَةُ لِحُضُورِ الْحَفْلَةِ. ""مَا ظَنَنْتُ أَنَّكَ تُجِيبُ إِلَى طَعَامِ قَوْمٍ عَائِلُهُمْ مَجْفُوٌّ وَغَنِيُّهُمْ مَدْعُوٌّ"". (علي بن أبي طالب). 2.""الْمَدْعُوُّ فُلاَنٌ"" : الْمُسَمَّى..."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4550, 'مُدْمىً', 'مدمى', 'اسم مفعول', 'مدمى', 'مدمى', 'مدم', '', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"مُدْمىً-مُدْمىً [م د م ى]. ن. مُدَمّىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4551, 'مُدْماةٌ', 'مدماة', 'اسم مفعول', '', 'مدماة', 'مدمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُدْمىً-مُدْمىً [م د م ى]. ن. مُدَمّىً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4552, 'مَخْطُوطٌ', 'مخطوط', 'اسم مفعول', '', 'مخطوط', 'مخطط', '', '', 'ة', 'جمع تكسير', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"ج: ـات. (مفع. مِنْ خَطَّ). 1.""وَجَدْنَا الْمَكْتَبَةَ غَنِيَّةً بِالكُتُبِ القَيِّمَةِ الْمَخْطُوطَةِ"" : كُلُّ كِتَابٍ كُتِبَ بِخَطِّ اليَدِ. ""حَقَّقَ مَخْطُوطاً نَادِراً"". 2.""قِسْمُ الْمَخْطُوطَاتِ"": القِسْمُ الَّذِي يَحْتَوِي عَلَى الكُتُبِ الَّتِي خَطَّهَا القُدَمَاءُ بِأَيْدِيهِمْ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4553, 'مَجْمُوعٌ', 'مجموع', 'اسم مفعول', '', 'مجموع', 'مجمع', '', '', 'ة', 'جمع تكسير', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات، مَجَامِيعُ. (مفع. مِنْ جَمَعَ). 1.""مَجْمُوعُ الْمَبْلَغِ الوَاجِبِ دَفْعُهُ"" : جُمْلَةُ الْمَبْلَغِ، كَمِّيَّةُ... 2.""مَجْمُوعُ عَدَدِ السُّكَانِ"" : عَدَدُهُمُ العَامُّ. 3.""عَمَلٌ جَيِّدٌ فِي مَجْمُوعِهِ"" : فِي إِجْمَالِهِ. 4 .""مَجْمُوعَةٌ مِنَ البَشَرِ"" : الجَمَاعَةُ مِنْهُمْ، الطَّائِفَةُ. 5.""الْمَجْمُوعَةُ الشَّمْسِيَّةُ"" : الشَّمْسُ وَمَا يَدُورُ فِي فَلَكِهَا مِنْ كَوَاكِبَ. 6.""مَجْمُوعَةٌ قَصَصِيَّةٌ"" : كِتَابٌ يَضُمُّ عَدَداً مِنَ القِصَصِ. ""مَجْمُوعَةٌ شِعْرِيَّةٌ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4554, 'مُلَطَّمٌ', 'ملطم', 'اسم مفعول', 'لطم', 'ملطم', 'ملطم', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". ""رَجُلٌ مُلَطَّمٌ"" : لَئِيمٌ، خَسِيسٌ، دَنِيءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4555, 'مُكَعَّبٌ', 'مكعب', 'اسم مفعول', 'كعب', 'مكعب', 'مكعب', '', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"مُكَعَّبٌ-مُكَعَّبٌ، ةٌ [ك ع ب] (هن). 1. ""وِعَاءٌ مُكَعَّبٌ"" : لَهُ سِتَّةُ سُطُوحٍ مُرَبَّعَةٍ مُتَسَاوِيَةٍ ومُتَوَازِيَةٍ. 2. : الْمُكَعَّب ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4556, 'مُكَسَّحٌ', 'مكسح', 'اسم مفعول', 'كسح', 'مكسح', 'مكسح', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". 1.""وَلَدٌ مُكَسَّحٌ"" : كَسيحٌ، مُصَابٌ ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4557, 'مُفَلْطَحٌ', 'مفلطح', 'اسم مفعول', 'فلطح', 'مفلطح', 'مفلطح', '', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُفَلْطَحٌ-مُفَلْطَحٌ، ةٌ [ف ل ط ح]. 1.""بُقْعَةٌ مُفَلْطَحَةٌ"" : مُن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4558, 'مُسْتَعْمَرٌ', 'مستعمر', 'اسم مفعول', 'عمر', 'مستعمر', 'مستعمر', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". ""لَمْ تَعُدْ هَذِهِ البِلاَدُ مِنْ مُسْتَعْمَرَاتِ دَوْلَةِ كَذَا"" : أَيْ كَانَتْ مُحْتَلَّةً مِنْ قَبْلُ وَخَاضِعَةً لِسَيْطَرَتِهَا حَيْثُ تَسْتَغِلُّهَا اقْتِصَادِيّاً وَسِيَاسِيّاً وَتَتَحَكَّمُ فِي تَسْيِيرِهَا"". ""اِتَّسَعَتِ الْمُسْتَعْمَرَاتُ الفَرَنْسِيَّةُ فِي القَرْنِ الْمَاضِي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4559, 'مُعَلَّبٌ', 'معلب', 'اسم مفعول', 'علب', 'معلب', 'معلب', '', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1. ""سَمَكٌ مُعَلَّبٌ"": سَمَكٌ مَحْفُوظٌ فِي عُلَبٍ مُعَقَّمَةٍ. ""مَوَادُّ مُعَلَّبَةٌ"". 2.""اِزْدَهَرَتْ صِنَاعَةُ الْمُعَلَّبَاتِ فِي أُورُوبَّا"" : صِنَاعَةُ تَعْلِيبِ الخُضَرِ والفَوَاكِهِ والأَسْمَاكِ ونَحْوِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4560, 'مُعْرَبٌ', 'معرب', 'اسم مفعول', 'عرب', 'معرب', 'معرب', '', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""اِسْمٌ مُعْرَبٌ"" : مُتَصَرِّفٌ، أَيْ مَا تَتَغَيَّرُ حَرَكَةُ آخِرِهِ بِتَغَيُّرِ العَامِلِ الدَّاخِلِ عَلَيْهِ. وَهُنَاكَ اسْمٌ مُعْرَبٌ بِالْحَرَكَاتِ، وَاسْمٌ مُعْرَبٌ بِالْحُرُوفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4561, 'مَعْتُوهٌ', 'معتوه', 'اسم مفعول', 'عته', 'معتوه', 'معته', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَعَاتِيهُ"', '', '', '', '', '', '', '', '', '". ""وَلَدٌ مَعْتُوهٌ"" : نَاقِصُ عَقْلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4562, 'معاتيه', 'معاتيه', 'اسم مفعول', '', 'معاتيه', 'معته', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4563, 'مُطِيعٌ', 'مطيع', 'اسم مفعول', 'طوع', 'مطيع', 'مطع', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". ""وَلَدٌ مُطِيعٌ"": الطَّائِعُ لِأَوَامِرِ وَالِدَيْهِ. ""مُطِيعٌ لِلْأَوَامِرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4564, 'مُطَرَّفٌ', 'مطرف', 'اسم مفعول', 'طرف', 'مطرف', 'مطرف', '', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُطَرَّفٌ-مُطَرَّفٌ، ةٌ [ط ر ف]. ""جَوَادٌ مُطَرَّفٌ"" : أَبْيَضُ الرَّأْسِ أَوِ الذَّنَبِ وَسَائِرُهُ مُخَالِفٌ لِذَلِكَ، أَوْ أَسْوَدُ أَحَدِهِمَا وَسَائِرُهُ مُخَالِفٌ لِذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4565, 'مَضِيفٌ', 'مضيف', 'اسم مفعول', 'ضيف', 'مضيف', 'مضف', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَضِيفٌ-مَضِيفٌ، ةٌ [ض ي ف]. ""نَزَلَ فِي الْمَضِيفِ"" : مَحَلُّ الضِّيَافَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4566, 'مَصُونٌ', 'مصون', 'اسم مفعول', 'صون', 'مصون', 'مصن', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". 1.""مَالُ الخَزِينَةِ مَالٌ مَصُونٌ"" : مَحْفُوظٌ وَمُؤْتَمَنٌ عَلَيْهِ. 2.""بَلَدٌ مَصُونٌ"": فِي مَنْأىً عَنْ كُلِّ اعْتِدَاءٍ. 3.""اِمْرَأَةٌ مَصُونٌ"" : ذَاتُ عِفَّةٍ وَفَضِيلَةٍ. 4.""الْحَرَمُ الْمَصُونُ"" : أَي الزَّوْجَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4567, 'مَشْوِيٌّ', 'مشوي', 'اسم مفعول', 'شوي', 'مشوي', 'مش', '', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَشْوِيٌّ-مَشْوِيٌّ، ةٌ [ش و ي]. ""لَحْمٌ مَشْوِيٌّ"" : مَا وُضِعَ عَلَى لَهِيبِ النَّارِ لِيَنْضَجَ. ""آجُرٌّ مَشْوِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4568, 'مُشَوَّكٌ', 'مشوك', 'اسم مفعول', 'شوك', 'مشوك', 'مشك', '', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَوَّكٌ-مُشَوَّكٌ، ةٌ [ش و ك]. 1.""شَجَرٌ مُشَوَّكٌ"" : بِهِ شَوْكٌ يَخْرُجُ مِنْهُ. 2.""جُدْرَانُ الدَّارَةِ مُشَوَّكَةٌ"" : أَيْ جُعِلَ فِيهَا الشَّوْكُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4569, 'طُعْمَةٌ', 'طعمة', 'اسم مفعول', 'طعم', 'طعمة', 'طعمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":طُعَمٌ[لايجوزجمعمذكرسالم]"', '', '', '', '', '', '', '', '', '". 1.""طُعْمَةُ الإِنْسَانِ"" : رِزْقُهُ. 2."" أَكْرَمْتُهُمْ طُعْمَةً لَذِيذَةً"" : أَيْ كُلُّ مَا يُطْعَمُ. 3.""هُوَ طَيِّبُ الطُّعْمَةِ"" : أَيْ نَقِيُّ الكَسْبِ الْحَلاَلِ. ""خَبِيثُ الطُّعْمَةِ"" ""عَفِيفُ الطُّعْمَةِ"" ""مَنْ نَصَبَ نَفْسَهُ لِلنَّاسِ إِمَاماً فَعَلَيْهِ أَنْ يَبْدَأَ بِتَعْلِيمِ نَفْسِهِ وَتَقْوِيمِهَا فِي السِّيرَةِ وَالطُّعْمَةِ"". (ابن المقفع). 3.""تَحَوَّلَتِ الْحُقُولُ طُعْمَةً لِلنِّيرَانِ"" : أَيْ مَادَّةً تَلْتَهِمُهَا الْتِهَاماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4570, 'طُعَمٌ', 'طعم', 'اسم مفعول', '', 'طعم', 'طعم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4571, 'ضُحْكَةٌ', 'ضحكة', 'اسم مفعول', 'ضحك', 'ضحكة', 'ضحكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"[لايجوزجمعمذكرسالم]"', '', '', '', '', '', '', '', '', '"ضُحْكَةٌ-ضُحْكَةٌ [ض ح ك]. ""صَارَ ضُحْكَةً فِي أَعْيُنِ النَّاسِ"" : مَسْخَرَةً، مُثِيراً لِلسُّخْرِيَةِ وَالْهُزْءِ، أُضْحُوكَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4572, 'مُضْغَةٌ', 'مضغة', 'اسم مفعول', 'مضغ', 'مضغة', 'مضغة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مُضَغٌ[لايجوزجمعمذكرسالم]"', '', '', '', '', '', '', '', '', '". 1.""يَلُوكُ مُضْغَةً فِي فَمِهِ"": القِطْعَةُ تُمْضَغُ مِنْ خُبْزٍ أَوْ لَحْمٍ وَغْيرِهِمَا، لُقْمَةٌ. ""وَجَدَ طَعَامَهُ مُضْغَةً سَائِغَةً"". 2.""صَارَ مُضْغَةً فِي أَفْوَاهِ النَّاسِ"": كَأَنَّهُ لُقْمَةٌ يَلُوكُهَا النَّاسُ، كِنَايَةً عَنِ التَّعْرِيضِ بِهِ. 3.""مُضَغُ الأُمُورِ"" : الأُمُورُ الَّتِي لاَ أَهَمِّيَّةَ لَهَا. 4.المؤمنون آية 14 فَخَلَقْنَا الْمُضْغَةَ عِظَاماً (قرآن) : العَلَقَةُ الَّتِي خُلِقَ مِنْهَا الإِنْسَانُ إِذَا صَارَتْ لَحْمَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4573, 'مُضَغٌ', 'مضغ', 'اسم مفعول', '', 'مضغ', 'مضغ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4574, 'أُكَلَةٌ', 'أكلة', 'اسم مفعول', 'أكل', 'ءكلة', 'كلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"[لايجوزجمعمذكرسالم]"', '', '', '', '', '', '', '', '', '"أُكَلَةٌ-أُكَلَةٌ [أ ك ل]. ""رَجلُ أُكَلةٌ"" : أَكَّالٌ، أكُولٌ، أَيْ كَثِيرُ الأَكْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4575, 'رِعْيٌ', 'رعي', 'اسم مفعول', 'رعي', 'رعي', 'رع', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَرْعاءٌ[لايجوزجمعمذكرسالم]"', '', '', '', '', '', '', '', '', '". ""رِعْيُ الْمَاشِيَةِ"" : الكَلأُ الَّذِي تَرْعاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4576, 'أَرْعاءُ', 'أرعاء', 'اسم مفعول', '', 'ءرعاء', 'رع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4577, 'ذِبْحٌ', 'ذبح', 'اسم مفعول', 'ذبح', 'ذبح', 'ذبح', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"[لايجوزجمعمذكرسالم]"', '', '', '', '', '', '', '', '', '"ذِبْحٌ-ذِبْحٌ [ذ ب ح]. : ما أُعِدَّ للذَّبْحِ، أَيْ ما يُذْبَحُ. صِيغَةٌ بِمَعْنَى مَفْعُول : مَذْبوح. الصافات آية 107وَفَدَيْناهُ بِذِبْحٍ عَظيمٍ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4578, 'مُنْخَفَضٌ', 'منخفض', 'اسم مفعول', 'خفض', 'منخفض', 'منخفض', '', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(جغ) (مفع. من اِنْخَفَضَ). 1.""مُنْخَفَضٌ أَرْضِيٌّ"" : مَوْضِعٌ يَنْخَفِضُ فِيهِ مُسْتَوَى سَطْحِ الأَرْضِ عَمَّا حَوْلَهُ مِنْ جِهَاتٍ. 2.""مُنْخَفَضٌ جَوِّيٌّ"" : ضَغْطٌ جَوِّيٌّ يَحْدُثُ فِي مِنْطَقَةٍ ويَكُونُ أَخَفَّ مِنَ الْمَنَاطِقِ الْمُحِيطَةِ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4579, 'مُجْمَعٌ', 'مجمع', 'اسم مفعول', 'جمع', 'مجمع', 'مجمع', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـون', '', '', '', '', '', '"مُجْمِعٌ-مُجْمِعٌ، ةٌ [ج م ع] (فَا. مِنْ أَجَمَعَ). 1.""أَمْرٌ مُجْمِعٌ"": مُتَّفَقٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4580, 'مُبَارَكٌ', 'مبارك', 'اسم مفعول', 'برك', 'مبارك', 'مبرك', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". 1.""العِيدُ مُبَارَكٌ عَلَيْكَ"" : لِيَكُنْ مَيْمُوناً مَبْرُوكاً. 2. : اِسْمُ عَلَمٍ مُذَكَّرٌ؛ وَمُبَارَكَة لِلْمُؤَنَّثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4581, 'مَبْرُورٌ', 'مبرور', 'اسم مفعول', 'برر', 'مبرور', 'مبرر', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَبْرُورٌ-مَبْرُورٌ [ب ر ر]. ""حَجٌّ مَبْرُورٌ"" : لاَ يُخَالِطُهُ شَيْءٌ مِنَ الْمَآثِمِ. ""الْحَجُّ الْمَبْرُورُ لَيْسَ لَهُ جَزَاءٌ إِلاَّ الجَنَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4582, 'مُؤَهِّلٌ', 'مؤهل', 'اسم مفعول', 'أهل', 'مءهل', 'مهل', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". ""لَهُ مُؤَهِّلاَتٌ عِلْمِيَّةٌ وَأَدَبِيَّةٌ"" : الصِّفَاتُ وَالقَابِلِيَّةُ وَالاسْتِعْدَادَاتُ الَّتِي تَجْعَلُ الْمَرْءَ أَهْلاً لِأَمْرٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4583, 'مُبَاحٌ', 'مباح', 'اسم مفعول', 'بوح', 'مباح', 'مبح', '', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"مُبَاحٌ-مُبَاحٌ [ب و ح]. ""أَمْرٌ مُبَاحٌ"" : جَائِزٌ، مَسْمُوحٌ بِهِ. ""الدُّخُولُ غَيْرُ مُبَاحٍ"" ""سَكَتَتْ شَهْرَزَادُ عَنِ الكَلاَمِ الْمُبَاحِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4584, 'مَأْسُوفٌ', 'مأسوف', 'اسم مفعول', 'أسف', 'مءسوف', 'مسف', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". مَأْسُوفٌ عَلَيْهِ"" : مُتَحَسَّرٌ، مُتَأَسَّفٌ عَلَيْهِ. ""تُوُفِّيَ القَائِدُ مَأْسُوفاً عَلَيْهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4585, 'مُؤَاتِي', 'مؤاتي', 'اسم مفعول', 'أتي', 'مءاتي', 'مت', '', 'Tk', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُؤَاتٍ-مُؤَاتٍ، الْمُؤَاتِي، ةٌ [أ ت ي]. ""عَمَلٌ مُؤَاتٍ"" : مُواتٍ، مُنَاسِبٌ، مُلاَئِمٌ. ""مَا زَالَتِ الظُّرُوفُ غَيْرَ مُؤَاتِيَةٍ لِتَحْقِيقِ انْتِصَارٍ كَامِلٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4586, 'مُؤَبَّدٌ', 'مؤبد', 'اسم مفعول', 'أبد', 'مءبد', 'مبد', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُؤَبَّدٌ-مُؤَبَّدٌ، ةٌ [أ ب د]. ""حُكِمَ عَلَيْهِ بِالسِّجْنِ الْمُؤَبَّدِ"" : بِالسِّجْنِ الدَّائِمِ مَدَى الْحَيَاةِ. ""نَطَقَ القَاضِي بِالأَشْغَالِ الشَّاقَةِ الْمُؤَبَّدَةِ فَاهْتَزَّتْ قَاعَةُ الْمَحْكَمَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4587, 'مَأْمُولٌ', 'مأمول', 'اسم مفعول', 'أمل', 'مءمول', 'ممل', '', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَأْمُولٌ-مَأْمُولٌ، ةٌ [أ م ل]. ""مِنَ الْمَأْمُولِ أَنْ نَحْتَفِلَ بِعَوْدَتِهِ"" : مِنَ الْمُؤَمَّلِ، مِنَ الْمُنْتَظَرِ. ""يَتُوقُ إِلَى نَتِيجَةٍ مَأْمُولَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4588, 'مَيْمُونٌ', 'ميمون', 'اسم مفعول', 'يمن', 'ميمون', 'ممن', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":ميامين"', '', '', '', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4589, 'مَيَامِينُ', 'ميامين', 'اسم مفعول', '', 'ميامين', 'ممن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4590, 'مَوْضُوعٌ', 'موضوع', 'اسم مفعول', 'وضع', 'موضوع', 'مضع', 'مفع. وَضَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَوَاضِيعُ"', '', '', '', '', '', '', '', '', '"(مص. وَضَعَ). 1.""مَالُهُ مَوْضُوعٌ فِي مَكَانٍ أَمِينٍ"" : مَتْرُوكٌ. ""وَثَائِقُ مَوْضُوعَةٌ فِي الْمَكْتَبَةِ العَامَّةِ"". 2.""مَوْضُوعُ الدَّرْسِ"": مَادَّتُهُ ومَدَارُهُ ومَا يَتَعَلَّقُ بِهِ. ""مَوْضُوعُ الكِتَابِ"" ""مَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4591, 'مَوَاضِيعُ', 'مواضيع', 'اسم مفعول', '', 'مواضيع', 'مضع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4592, 'مَطْمُورٌ', 'مطمور', 'اسم مفعول', 'طمر', 'مطمور', 'مطمر', '', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات:مَطَامِيرُ"', '', '', '', '', '', '', '', '', '". 1.""مَطْمُورَةُ الحُبُوبِ"" : حَفِيرَةٌ أَسْفَلُهَا مُوَسَّعٌ تُخْزَنُ فِيهَا الحُبُوبُ. 2.""مَطْمُورَةُ الْمَاءِ"" : حَفِيرَةٌ تَحْتَ الأَرْضِ، أَسْفَلُهَا مُوَسَّعٌ، تُخْزَنُ فِيهَا مِيَاهُ الأَمْطَارِ فِي البَوَادِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4593, 'مَطَامِيرُ', 'مطامير', 'اسم مفعول', '', 'مطامير', 'مطمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4594, 'متبوع', 'متبوع', 'اسم مفعول', 'تبع', 'متبوع', 'متبع', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":متابيعُ"', '', '', '', '', '', '', '', '', '"تَبعَ) الشيءَ-َ تَبَعًا، وتُبوعًا، وتَباعًا، وتَباعة: سار في أثره، أو تلاه. ويقال: تَبعَ فلانًا بحقِّه: طالبه به. وتَبعَ المصلِّي الإِمامَ: حذا حَذْوَه، واقتدى به. وتَبِعت الأغصانُ الرِّيحَ: مالت معه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4595, 'مَتَابِيعُ', 'متابيع', 'اسم مفعول', '', 'متابيع', 'متبع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4596, 'منكور', 'منكور', 'اسم مفعول', 'نكر', 'منكور', 'منكر', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مناكيرُ"', '', '', '', '', '', '', '', '', '"المَنْكُورُ : مفعـ.-: المجهولُ؛ اكتشفنا كتاباً قيَّماً لكاتب منكورج مَنَاكِيرُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4597, 'مَنَاكِيرُ', 'مناكير', 'اسم مفعول', '', 'مناكير', 'منكر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4598, 'مسلوخ', 'مسلوخ', 'اسم مفعول', 'سلخ', 'مسلوخ', 'مسلخ', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '" (السَّلِيخُ): المسلوخُ. و- ما لا طَعم له. يقال: سليخٌ مَلِيخٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4599, 'مساليخ', 'مساليخ', 'اسم مفعول', '', 'مساليخ', 'مسلخ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4600, 'مغلول', 'مغلول', 'اسم مفعول', 'غلل', 'مغلول', 'مغلل', '', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '" (غُلَّ): عَطِش أَشدَّ العَطَشِ. ويقال: غُلَّتْ يدُه إِلى عنقه: أَمسكَتْ عن الإِنفاق. فهو غَلِيلٌ، ومغلولٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4601, 'مغاليل', 'مغاليل', 'اسم مفعول', '', 'مغاليل', 'مغلل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4602, 'مَثْؤُوبٌ', 'مثؤوب', 'اسم مفعول', 'ثأب', 'مثءوب', 'مثب', 'مفع. تَثَاءَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع تَثَاءَبَ). ""رَآهُ مَثْؤُوباً"" : يَفْتَحُ فَاهُ وَهُوَ مُسْتَرْخٍ مِنَ التَّعَبِ وَالعَيَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4603, 'مُرَبَّعٌ', 'مربع', 'اسم مفعول', 'ربع', 'مربع', 'مربع', 'مفع. رَبَّعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. رَبَّعَ). 1.""شَكْلٌ مُرَبَّعٌ"" (هن) : شَكْلٌ هَنْدَسِيٌّ، ذُو أَضْلاَعٍ أَرْبَعَةٍ مُتَسَاوِيَةٍ تَقُومُ بَيْنَهَا زَوَايَا قَائِمَةٌ. 2.: حَاصِلُ ضَرْبِ عَدَدٍ في نفْسِهِ. 3.""رَجُلٌ مُرَبَّعُ الْحَاجِبَيْنِ"" : كَثِيرُ شَعْرِهِمَا، وَتَبْدُو كَأَنَّ لَهُ أَرْبَعَةَ حَوَاجِبَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4604, 'مُعَبَّدٌ', 'معبد', 'اسم مفعول', 'عبد', 'معبد', 'معبد', 'مفع. عَبَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَبَّدٌ-مُعَبَّدٌ، ةٌ [ع ب د] (مفع. عَبَّدَ). ""طَرِيقٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4605, 'مَعْشُوقٌ', 'معشوق', 'اسم مفعول', 'عشق', 'معشوق', 'معشق', 'مفع. فَا. مِن عَشِقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. فَا. مِن عَشِقَ). 1.""شَابٌّ مَعْشُوقٌ"" : مَحْبُوبٌ. 2.""مَعْشُوقٌ لِكُلِّ جَمَالٍ"" : عَاشِقٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4606, 'مُبتدَعٌ', 'مبتدع', 'اسم مفعول', 'بدع', 'مبتدع', 'مبتدع', 'مفع. من ابتدع', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4607, 'مُبْتَذَلٌ', 'مبتذل', 'اسم مفعول', 'بذل', 'مبتذل', 'مبتذل', 'مفع. مِن اِبْتَذَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبْتَذَلٌ-مُبْتَذَلٌ، ةٌ [ب ذ ل] (مفع. مِن اِبْتَذَلَ). 1. ""يَلْبَسُ ثَوْباً مُبْتَذَلاً"" : بَالِياً، مُمَزَّقاً. 2.""خَاطَبَهُ بِكَلاَمٍ مُبْتَذَلٍ"" : بِكَلاَمٍ سَفِيهٍ خَادِشٍ لِلْحَيَاءِ. 3.""أُسْلُوبٌ مُبْتَذَلٌ"" : كَثِيرُ الاسْتِعْمَالِ، مَأْلُوفٌ، مُتَدَاوَلٌ. ""فِكْرَةٌ مُبْتَذَلَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4608, 'مُبْتَسَرٌ', 'مبتسر', 'اسم مفعول', 'بسر', 'مبتسر', 'مبتسر', 'مفع. مِن اِبْتَسَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبْتَسَرٌ-مُبْتَسَرٌ، ةٌ [ب س ر] (مفع. مِن اِبْتَسَرَ). ""عَمَلٌ مُبْتَسَرٌ"" : عَمَلٌ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4609, 'مُبْتَغىً', 'مبتغى', 'اسم مفعول', 'بغي', 'مبتغى', 'مبتغ', 'مفع. مِن اِبْتَغَى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"مُبْتَغىً-مُبْتَغىً [ب غ ي] (مفع. مِن اِبْتَغَى). ""يَنْشُدُ مُبْتَغَاهُ"" : طَلَبَهُ، حَاجَتَهُ، مَا يُؤَمِّلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4610, 'مُبْتَغاة', 'مبتغاة', 'اسم مفعول', '', 'مبتغاة', 'مبتغة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبْتَغىً-مُبْتَغىً [ب غ ي] (مفع. مِن اِبْتَغَى). ""يَنْشُدُ مُبْتَغَاهُ"" : طَلَبَهُ، حَاجَتَهُ، مَا يُؤَمِّلُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4611, 'مُبْتَكَرٌ', 'مبتكر', 'اسم مفعول', 'بكر', 'مبتكر', 'مبتكر', 'مفع. مِن اِبْتَكَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِبْتَكَرَ). 1.""عَمَلٌ مُبْتَكَرٌ"" : مُبْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4612, 'مُبْتَلٌّ', 'مبتل', 'اسم مفعول', 'بلل', 'مبتل', 'مبتل', 'مفع. مِن اِبْتَلَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُبْتَلٌّ-مُبْتَلٌّ [ب ل ل] (مفع. مِن اِبْتَلَّ). ""ثَوْبٌ مُبْتَلُّ"" : مَبْلُولٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4613, 'مُبْتَلىً', 'مبتلى', 'اسم مفعول', 'بلي', 'مبتلى', 'مبتل', 'مفع. مِن ابْتَلَى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن ابْتَلَى). ""مُبْتَلىً بِعَاهَةٍ"" : مُصَابُ بِهَا. ""مُبْتَلُونَ ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4614, 'مُبْتَلاة', 'مبتلاة', 'اسم مفعول', '', 'مبتلاة', 'مبتلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن ابْتَلَى). ""مُبْتَلىً بِعَاهَةٍ"" : مُصَابُ بِهَا. ""مُبْتَلُونَ ب"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4615, 'مُبْطَلٌ', 'مبطل', 'اسم مفعول', 'بطل', 'مبطل', 'مبطل', 'مفع. مِنْ أَبْطَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَبْطَلَ). ""شَيْءٌ مُبْطَلٌ"" : غَيْرُ دَارِجٍ، مُهْمَلٌ، مَهْجُورٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4616, 'مُبْعَدُ', 'مبعد', 'اسم مفعول', 'بعد', 'مبعد', 'مبعد', 'مفع. مِنْ أَبْعَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ أَبْعَدَ). 1.""مُبْعَدٌ عَنْ بِلاَدِهِ"" : مَنْفِيٌّ عَنْهَا. 2.""مُبْعَدٌ عَنِ العَمَلِ"": مَطْرُودٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4617, 'مُبْغَضٌ', 'مبغض', 'اسم مفعول', 'بغض', 'مبغض', 'مبغض', 'مفع. مِنْ أَبْغَضَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ أَبْغَضَ). ""مُبْغَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4618, 'مُبْهَمٌ', 'مبهم', 'اسم مفعول', 'بهم', 'مبهم', 'مبهم', 'مفع. مِنْ أَبْهَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبْهَمٌ-مُبْهَمٌ [ب هـ م] (مفع. مِنْ أَبْهَمَ). 1.""تَحَدَّثَ بِكَلاَمٍ مُبْهَمٍ"" : غَامِضٍ لاَ يُدْرَكُ، مُلْتَبِسٍ. ""أَمْرٌ مُبْهَمٌ"". 2.""سَارَ فِي طَرِيقٍ مُبْهَمٍ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4619, 'مُتَاحٌ', 'متاح', 'اسم مفعول', 'تيح', 'متاح', 'متح', 'مفع. مِنْ أَتاحَ تَاحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَاحٌ-مُتَاحٌ [ت ي ح] (مفع. مِنْ أَتاحَ تَاحَ). ""الدُّخُولِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4620, 'مُتَّبَعٌ', 'متبع', 'اسم مفعول', 'تبع', 'متبع', 'متبع', 'مفع. مِن اِتَّبَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُتَّبَعٌ-مُتَّبَعٌ، ةٌ [ت ب ع] (مفع. مِن اِتَّبَعَ). 1.""مَنْهَجٌ مُتَّبَعٌ"": مُتَبَنّىً، السَّيْرُ عَلَى مِنْوَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4621, 'مُتَّجَهٌ', 'متجه', 'اسم مفعول', 'وجه', 'متجه', 'متجه', 'مفع. مِن اِتَّجَهَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَّجَهٌ-مُتَّجَهٌ [و ج هـ] (مفع. مِن اِتَّجَهَ). ""يَعْمَلُ فِي كُلِّ مُتَّجَهٍ"" : فِي كُلِّ اتِّجَاهٍ. ""لاَ يَعْرِفُ هَدَفاً وَلاَ مُتَّجَهاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4622, 'مُتْرَبٌ', 'مترب', 'اسم مفعول', 'ترب', 'مترب', 'مترب', 'مفع. مِنْ أَتْرَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتْرَبٌ-مُتْرَبٌ، ةٌ [ت ر ب] (مفع. مِنْ أَتْرَبَ). ""مَكَانٌ مُتْرَبٌ"" : كَثِيرُ الغُبَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4623, 'مُتْرَعٌ', 'مترع', 'اسم مفعول', 'ترع', 'مترع', 'مترع', 'مفع. مِنْ أَتْرَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتْرَعٌ-مُتْرَعٌ، ةٌ [ت ر ع] (مفع. مِنْ أَتْرَعَ). ""كَأْسٌ مُتْرَعَةٌ"": مَمْلُوءةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4624, 'مُتْرَفٌ', 'مترف', 'اسم مفعول', 'ترف', 'مترف', 'مترف', 'مفع. مِنْ أَتْرَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ أَتْرَفَ). ""رَجُلٌ مُتْرَفٌ"" : غَنِيٌّ، مَنْ يَعِيشُ فِي بُحْبُوحَةِ عَيْشٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4625, 'مُتَّسَعٌ', 'متسع', 'اسم مفعول', 'وسع', 'متسع', 'متسع', 'مفع. مِن اِتَّسَع', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَّسَعٌ-مُتَّسَعٌ [و س ع] (مفع. مِن اِتَّسَع). ""مَا زَالَ لَدَيْهِ مُتَّسَعٌ مِنَ الوَقْتِ"" : مَجَالٌ زَمَنِيٌّ، فُسْحَةٌ. ""لَمْ يَجِدْ مُتَّسَعاً مِنَ الوَقْتِ لِلْإِجَابَةِ عَلَى كُلِّ الأَسْئِلَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4626, 'مُتْعَبٌ', 'متعب', 'اسم مفعول', 'تعب', 'متعب', 'متعب', 'مفع. مِنْ أَتْعَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَتْعَبَ). ""وَصَلَ مُتْعَباً مِنَ العَمَلِ"" : أَيْ مُرْهَقاً، تَعِباً، بِهِ عَيَاءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4627, 'مُتَّفَقٌ', 'متفق', 'اسم مفعول', 'وفق', 'متفق', 'متفق', 'مفع. مِن اِتَّفَقَ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُتَّفَقٌ-مُتَّفَقٌ، ةٌ [و ف ق] (مفع. مِن اِتَّفَقَ)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4628, 'مُتْقَنٌ', 'متقن', 'اسم مفعول', 'تقن', 'متقن', 'متقن', 'مفع. مِنْ أَتْقَنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَتْقَنَ). ""عَمَلٌ مُتْقَنٌ"" : جَيِّدٌ، تَامٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4629, 'مُتَّكَأٌ', 'متكأ', 'اسم مفعول', 'وكأ', 'متكء', 'متك', 'مفع. مِن اِتَّكَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِتَّكَأَ). ""اِتَّخَذَ مِخَد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4630, 'مُتَّكَأَةٌ', 'متكأة', 'اسم مفعول', '', 'متكءة', 'متكة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِتَّكَأَ). ""اِتَّخَذَ مِخَد"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4631, 'مُتَّهَمٌ', 'متهم', 'اسم مفعول', 'تهم،وهم', 'متهم', 'متهم', 'مفع. مِن اِتَّهَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن اِتَّهَمَ). ""وَقَفَ الْمُتَّهَمُ فِي قَفَصِ الاتِّهَامِ"" : مَنِ اتُّهِمَ بِارْتِكَابِ ذَنْبٍ أَوْ جَرِيمَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4632, 'مُثْبَتٌ', 'مثبت', 'اسم مفعول', 'ثبت', 'مثبت', 'مثبت', 'مفع. مِنْ أَثْبَتَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُثْبَتٌ-مُثْبَتٌ [ث ب ت] (مفع. مِنْ أَثْبَتَ). 1.""عَمُودٌ مُثْبَتٌ"" : رَاسِخٌ، مَشْدُودٌ. 2.""مَرِيضٌ مُثْبَتٌ"" : لَمْ يَعُدْ يُفَارِقُ فِرَاشَهُ. 3.""كَلاَمٌ مُثْبَتٌ"" : قَائِمٌ، غَيْرُ مَنْفِيٍّ، وَاقِعٌ، مُؤَكَّدٌ. ""تُهْمَةٌ مُثْبَتَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4633, 'مُثْخَنٌ', 'مثخن', 'اسم مفعول', 'ثخن', 'مثخن', 'مثخن', 'مفع. مِنْ أَثْخَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَثْخَنَ). ""مُثْخَنٌ بِالجِرَاحِ"" : مُثْقَلٌ بِكَثْرَةِ الجِرَاحِ. ""وَقَعَ مُثْخَناً لاَ يَسْتَطِيعُ حَرَاكاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4634, 'مُثْقَلٌ', 'مثقل', 'اسم مفعول', 'ثقل', 'مثقل', 'مثقل', 'مفع. مِنْ أَثْقَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَثْقَلَ). 1.""مُثْقَلٌ بِالدُّيُونِ"" : مَنْ تَرَاكَمَتْ عَلَيْهِ الدُّيُونُ. 2.""مُثْقَلٌ بِالهُمُومِ وَالأَحْزَانِ"" : الرَّازِحُ تَحْتَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4635, 'مُجْبَرٌ', 'مجبر', 'اسم مفعول', 'جبر', 'مجبر', 'مجبر', 'مفع. مِنْ أَجْبَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَجْبَرَ). ""مُجْبَرٌ عَلَى القِيَامِ بِهَذَا العَمَلِ الشَّاقِّ"" : مُكْرَهٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4636, 'مُجْتَثٌّ', 'مجتث', 'اسم مفعول', 'جثث', 'مجتث', 'مجتث', 'مفع. من اِجْتَثَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُجْتَثٌّ-مُجْتَثٌّ، ةٌ [ج ث ث] (مفع. من اِجْتَثَّ). 1.""نَبَاتٌ مُجْتَثٌّ"" : كُلُّ نَبَاتٍ يُنْزَعُ مِنْ جُذُو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4637, 'مُجْتَمَعٌ', 'مجتمع', 'اسم مفعول', 'جمع', 'مجتمع', 'مجتمع', 'مفع. مِن اِجْتَمَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِجْتَمَعَ). 1.""اِتَّفَقُوا عَلَى أَنْ يَكُونَ مُجْتَمَعُهُمْ فِي السَّاحَةِ الكُبْرَى"" : مَكَان اجْتِمَاعِهِمْ. 2.""الْمُجْتَمَعُ العَرَبِيُّ"" : الجَمَاعَةُ مِنَ النَّاسِ تَعِيشُ سَوِيّاً وَتَرْبِطُهَا رَوَابِطُ مُشْتَرَكَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4638, 'مُؤَجَّرٌ', 'مؤجر', 'اسم مفعول', 'أجر', 'مءجر', 'مجر', 'مفع. مِنْ أَجَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُؤَجَّرٌ-مُؤَجَّرٌ، ةٌ [أ ج ر] (مفع. مِنْ أَجَّرَ).""بَيْتٌ مُؤَجَّرٌ"" : مُكْتَرىً، أَيْ تَمَّ اسْتِئْجَارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4639, 'مُؤَجَّلٌ', 'مؤجل', 'اسم مفعول', 'أجل', 'مءجل', 'مجل', 'مفع. مِنْ أَجَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُؤَجَّلٌ-مُؤَجَّلٌ، ةٌ [أ ج ل] (مفع. مِنْ أَجَّلَ) . ""مَوْعِدٌ مُؤَجَّلٌ"": مُؤَخَّرٌ. ""مَهْرٌ مُؤَجَّلٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4640, 'مُجْمَلٌ', 'مجمل', 'اسم مفعول', 'جمل', 'مجمل', 'مجمل', 'مفع. مِنْ أَجْمَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجْمَلٌ-مُجْمَلٌ، ةٌ [ج م ل] (مفع. مِنْ أَجْمَلَ). ""مُجْمَلُ القَوْلِ"" : مُوجَزُهُ، خُلاَصَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4641, 'مَجْنُونٌ', 'مجنون', 'اسم مفعول', 'جنن', 'مجنون', 'مجنن', 'مفع. مِنْ أَجَنَّ عَلَى غَيْرِ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مَجَانِينُ"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ أَجَنَّ عَلَى غَيْرِ قِيَاسٍ، أَيْ جَنَّ جُنَّ). 1.""مَجْنُونُ الْحَيِّ"" : مَنْ ذَهَبَ عَقْلُهُ. 2.""مُسْتَشْفَى الْمَجَانِينِ"" : مُسْتَشْفَى الأَمْرَاضِ العَقْلِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4642, 'مَجَانِينُ', 'مجانين', 'اسم مفعول', '', 'مجانين', 'مجنن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4643, 'مُجْهَضٌ', 'مجهض', 'اسم مفعول', 'جهض', 'مجهض', 'مجهض', 'مفع. مِنْ أَجْهَضَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجْهَضٌ-مُجْهَضٌ، ةٌ [ج هـ ض] (مفع. مِنْ أَجْهَضَ). 1.""جَنِينٌ مُجْهَضٌ"" : أُلْقِيَ بِهِ قَبْلَ اكْتِمَالِهِ. 2.""فِكْرَةٌ مُجْهَضَةٌ"": لَمْ تَكْتَمِلْ صُورَتُهَا. ""أَعْمَالٌ مُجْهَضَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4644, 'مُحَاطٌ', 'محاط', 'اسم مفعول', 'حوط', 'محاط', 'محط', 'مفع. مِنْ أَحَاطَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَحَاطَ). 1.""مُحَاطٌ مِنْ كُلِّ جِهَةٍ"" : مُحَاصَرٌ. 2.""أَسْرَارُهُ مُحَاطَةٌ بِالكِتْمَانِ"" : مَخْفِيَّةٌ. 3.""عَمَلُهُ مُحَاطٌ بِالغُمُوضِ"" : مُكْتَنَفٌ بِالغُمُوضِ، غَيْرُ وَاضِحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4645, 'مُحْتَرَمٌ', 'محترم', 'اسم مفعول', 'حرم', 'محترم', 'محترم', 'مفع. مِن اِحْتَرَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن اِحْتَرَمَ). ""رَجُلٌ مُحْتَرَمٌ"" : رَجُلٌ عَظِيمٌ، مُكَرَّمٌ، وَغَالِباً مَا تُسْتَعْمَلُ الكَلِمَةُ بَعْدَ الاسْمِ تَعْظِيماً وَتَقْدِيراً. ""سَيِّدِي الْمُحْتَرَمُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4646, 'مُحْتَسَبٌ', 'محتسب', 'اسم مفعول', 'حسب', 'محتسب', 'محتسب', 'مفع. مِن اِحْتَسَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحْتَسَبٌ-مُحْتَسَبٌ، ةٌ [ح س ب] (مفع. مِن اِحْتَسَبَ). ""عَمَلٌ مُحْتَسَبٌ"" : لَهُ اعْتِبَارُهُ وَقِيمَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4647, 'مُحْتَضَرٌ', 'محتضر', 'اسم مفعول', 'حضر', 'محتضر', 'محتضر', 'مفع. مِن اِحْتَضَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِحْتَضَرَ). ""مُحْتَضَرٌ عَلَى فِرَاشِهِ"" : مَنْ حَضَرَتْهُ الوَفَاةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4648, 'مُحْتَفَلٌ', 'محتفل', 'اسم مفعول', 'حفل', 'محتفل', 'محتفل', 'مفع. مِن اِحْتَفَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِحْتَفَلَ). ""الرَّجُلُ الْمُحْتَفَلُ بِهِ"" : مَنْ تُقَامُ الْحَفْلَةُ تَكْرِيماً لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4649, 'مُحْتَقَرٌ', 'محتقر', 'اسم مفعول', 'حقر', 'محتقر', 'محتقر', 'مفع. مِن اِحْتَقَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِحْتَقَرَ). 1.""عَمَلٌ مُحْتَقَرٌ"" : مُسْتَهَانٌ بِهِ. 2.""رَجُلٌ مُحْتَقَرٌ بَيْنَ النَّاسِ"" : ذَلِيلٌ، مُهَانٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4650, 'مُحْتَكَرٌ', 'محتكر', 'اسم مفعول', 'حكر', 'محتكر', 'محتكر', 'مفع. مِن اِحْتَكَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحْتَكَرٌ-مُحْتَكَرٌ، ةٌ [ح ك ر] (مفع. مِن اِحْتَكَرَ). ""سِلْعَةٌ مُحْتَكَرَةٌ مِنْ لَدُنِ التُّجَّارِ الكِبَارِ"" : أَيْ يَقَعُ التَّفَرُّدُ بِها وَالتَّصَرُّفُ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4651, 'مُحْتَلٌّ', 'محتل', 'اسم مفعول', 'حلل', 'محتل', 'محتل', 'مفع. مِن اِحْتَلَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن اِحْتَلَّ). 1.""يُحَارِبُ العَدُوَّ الْمُحْتَلَّ لِبِلاَدِهِ"" : مَنِ احْتَلَّ بِلاَدَهُ، اِسْتَوْلَى عَلَيْها. ""الْمُحْتَلُّونَ الغُزَاةُ"". 2.""هَزَّتِ الانْتِفَاضَةُ فِي الأَرَاضِي الْمُحْتَلَّةِ الضَّمِيرَ العَالَمِيَّ"" : الأَرَاضِي الَّتِي تَمَّ الاسْتِيلاَءُ عَلَيْهَا مِنْ لَدُنِ الصَّهَايِنَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4652, 'مُحْتَمَلٌ', 'محتمل', 'اسم مفعول', 'حمل', 'محتمل', 'محتمل', 'مفع. مِن اِحْتَمَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحْتَمَلٌ-مُحْتَمَلٌ، ةٌ [ح م ل] (مفع. مِن اِحْتَمَلَ). ""مِنَ الْمُحْتَمَلِ أَنْ أَزُورَكَ"" : مِنَ الْمُمْكِنِ، مِنَ الْمُرَجَّحِ، مِنَ الْجَائِزِ، مِنَ الْمُتَوَقَّعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4653, 'مُحْدَثٌ', 'محدث', 'اسم مفعول', 'حدث', 'محدث', 'محدث', 'مفع. مِنْ أَحْدَثَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَحْدَثَ). 1.""أَمْرٌ مُحْدَثٌ"" : مَا أُحْدِثَ وَلَمْ يَكُنْ مُتَدَاوَلاً فِي كِتَابٍ أَوْ سُنَّةٍ. ""شَرُّ الأُمُورِ مُحْدَثَاتُهَا وَكُلُّ مُحْدَثَةٍ بِدْعَةٌ وَكُلُّ بِدْعَةٍ ضَلالَةٌ"". 2.""كَاتِبٌ مُحْدَثٌ"" : مُتَأَخِّرٌ، أَيْ حَدِيثُ العَهْدِ. ""الكُتَّابُ القُدَمَاءُ وَالْمُحْدَثُونَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4654, 'مُحْدَوْدَبٌ', 'محدودب', 'اسم مفعول', 'حدب', 'محدودب', 'محددب', 'مفع. مِن اِحْدَوْدَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِحْدَوْدَبَ). ""مُحْدَوْدَبُ الظَّهْرِ"" : مُقَوَّسُ الظَّهْرِ، مُعْوَجُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4655, 'مُحْصَنٌ', 'محصن', 'اسم مفعول', 'حصن', 'محصن', 'محصن', 'مفع. مِنْ أَحْصَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَحْصَنَ). ""رَجُلٌ مُحْصَنٌ"" : مُتَزَوِّجٌ. ""اِمْرَأَةٌ مُحْصَنَةٌ"" : مُتَزَوِّجَةٌ، عَفِيفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4656, 'مُحْكَمٌ', 'محكم', 'اسم مفعول', 'حكم', 'محكم', 'محكم', 'مفع. مِنْ أَحْكَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَحْكَمَ). 1.""عَمَلٌ مُحْكَمُ الإِنْجَازِ"" : تَامٌّ، كَامِلٌ لاَ عَيْبَ فِيهِ. 2.""قَوْلٌ مُحْكَمٌ"" : مُحَدَّدٌ، وَاضِحٌ، مُثْبَتٌ. 3.""بِنَاءٌ مُحْكَمٌ"" : مَتِينٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4657, 'مُخْتَارٌ', 'مختار', 'اسم مفعول', 'خير', 'مختار', 'مختر', 'مفع. مِن اِخْتَارَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن اِخْتَارَ). 1.""مُخْتَارٌ مِنْ بَيْنِ أَصْدِقَائِهِ لِلْقِيَامِ بِهَذَا العَمَلِ"" : الْمُنْتَقَى، الْمُصْطَفَى. 2.""مُخْتَارَاتٌ شِعْرِيَّةٌ"" : مَجْمُوعَةُ قَصَائِدَ مُنْتَقَاةٌ، مُنْتَخَبَاتٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4658, 'مُخْتَرَعٌ', 'مخترع', 'اسم مفعول', 'خرع', 'مخترع', 'مخترع', 'مفع. مِن اِخْتَرَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِخْتَرَعَ). ""مُخْتَرَعٌ جَدِيدٌ فِي مَجَال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4659, 'مُخْتَزَلٌ', 'مختزل', 'اسم مفعول', 'خزل', 'مختزل', 'مختزل', 'مفع. مِن اِخْتَزَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخْتَزَلٌ-مُخْتَزَلٌ، ةٌ [خ ز ل] (مفع. مِن اِخْتَزَلَ). 1.""حِسَابٌ مُخْتَزَلٌ"" : مُخْتَصَرٌ. 2."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4660, 'مُخْتَصَرٌ', 'مختصر', 'اسم مفعول', 'خصر', 'مختصر', 'مختصر', 'مفع. مِن اِخْتَصَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِخْتَصَرَ). ""دَرْسٌ مُخْتَصَرٌ"" : مُوجَزٌ. ""كَلاَمٌ مُخْتَصَرٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4661, 'مُخْتَلٌّ', 'مختل', 'اسم مفعول', 'خلل', 'مختل', 'مختل', 'مفع. مِن اِخْتَلَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن اِخْتَلَّ). ""مُخْتَلُّ العَقْلِ"" : مَنِ اخْتَلَّ عَقْلُهُ، أَيْ مَنْ أَصَابَهُ مَسٌّ مِنَ الجُنُونِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4662, 'مُخْتَلَفٌ', 'مختلف', 'اسم مفعول', 'خلف', 'مختلف', 'مختلف', 'مفع. مِن اِخْتَلَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخْتَلَفٌ-مُخْتَلَفٌ [خ ل ف] (مفع. مِن اِخْتَلَفَ). ""أَمْرٌ مُخْتَلَفٌ فِيهِ"" : فِيهِ جِدَالٌ وَنِزَاعٌ. ""أَمْرٌ مُخْتَلَفٌ عَلَيْهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4663, 'مُخْتَلَقٌ', 'مختلق', 'اسم مفعول', 'خلق', 'مختلق', 'مختلق', 'مفع. مِن اِخْتَلَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخْتَلَقٌ-مُخْتَلَقٌ، ةٌ [خ ل ق] (مفع. مِن اِخْتَلَقَ). ""خَبَرٌ مُخْتَلَقٌ"" : مُلَفَّقٌ، أَيْ غَيْرُ صَحِيحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4664, 'مُؤَخَّرٌ', 'مؤخر', 'اسم مفعول', 'أخر', 'مءخر', 'مخر', 'مفع. مِنْ أَخَّرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَخَّرَ). 1.""مُؤَخَّرٌ فِي عَمَلِهِ"" : مُعَوَّقٌ. 2.""فِي مُؤَخَّرِ العَرَبَةِ"" : فيِ خَلْفِهَا. ""فِي مُؤَخَّرِ السَّفِينَةِ"". 3.""مُؤَخَّرُ صَدَاقِ الْمَرْأَةِ"": مَا أُخِّرَ وَأُجِّلَ دَفْعُهُ. ""لاَ مُؤَخَّرَ وَلاَ مُقَدَّمَ"". 4.""مُؤَخَّرَةُ الْجَيْشِ"" : جُزْءٌ مِنَ القُوَّةِ العَسْكَرِيَّةِ يَبْقَى لِحِرَاسَةِ الخُطُوطِ الخَلْفِيَّةِ. 5.""مُؤَخَّرَةُ الرَّجُلِ"" : عَجُزُهُ، دُبُرُهُ. 6."" مُؤَخَّرَةُ الْحَيَوَانِ"" : مَا يَجُرُّهُ خَلْفَهُ. 7.""أُعْلِنَ مُؤَخَّراً عَنْ مَشْرُوعِ دُسْتُورٍ جَدِيدٍ"" : أَخِيراً، حَدِيثاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4665, 'مُدَانٌ', 'مدان', 'اسم مفعول', 'دين', 'مدان', 'مدن', 'مفع. مِنْ أَدَانَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُدَانٌ-مُدَانٌ [د ي ن] (مفع. مِنْ أَدَانَ). 1.""مُدَانٌ لَهُ بِمِائَةِ دِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4666, 'مُؤَدَّبٌ', 'مؤدب', 'اسم مفعول', 'أدب', 'مءدب', 'مدب', 'مفع. مِنْ أَدَّبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ أَدَّبَ). ""وَلَدٌ مُؤَدَّبٌ"" : مُهَذَّبٌ. ""كَانَ وَلاَ يَزَالُ مُؤَدَّباً فِي تَعَامُلِهِ مَعَ النَّاسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4667, 'مُدَّثَّرٌ', 'مدثر', 'اسم مفعول', 'دثر', 'مدثر', 'مدثر', 'مفع. مِن اِدَّثَّرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِدَّثَّرَ). ""مُدَّثَّرٌ فِي مَلاَبِسَ صُوفِيَّةٍ"" : مُلْتَفٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4668, 'مُدْرَجٌ', 'مدرج', 'اسم مفعول', 'درج', 'مدرج', 'مدرج', 'مفع. مِنْ أَدْرَجَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُدْرَجٌ-مُدْرَجٌ [د ر ج] (مفع. مِنْ أَدْرَجَ). ""مَا قَالَهُ مُدْرَجٌ فِي هَذَا الكِتَابِ"" : دَاخِلٌ فِيهِ، مُدَوَّنٌ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4669, 'مُدْرَكٌ', 'مدرك', 'اسم مفعول', 'درك', 'مدرك', 'مدرك', 'مفع. مِنْ أَدْرَكَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُدْرَكٌ-مُدْرَكٌ [د ر ك] (مفع. مِنْ أَدْرَكَ). ""دَرْسٌ مُدْرَكٌ"" : أَيْ دَرْسٌ يُدْرَكُ مَعَ فَهْمِ مَعْنَاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4670, 'مُدَّعًى', 'مدعى', 'اسم مفعول', 'دعو', 'مدعى', 'مدع', 'مفع. مِن اِدَّعَى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِدَّعَى). ""مُدَّعًى عَلَيْهِ"" : مَنْ أُقِيمَتْ عَلَيْهِ الدَّعْوَى أَمَامَ القَضَاءِ، الْمُخَاصَمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4671, 'مُدَّعاة', 'مدعاة', 'اسم مفعول', '', 'مدعاة', 'مدعة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِدَّعَى). ""مُدَّعًى عَلَيْهِ"" : مَنْ أُقِيمَتْ عَلَيْهِ الدَّعْوَى أَمَامَ القَضَاءِ، الْمُخَاصَمُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4672, 'مُدْمَجٌ', 'مدمج', 'اسم مفعول', 'دمج', 'مدمج', 'مدمج', 'مفع. مِنْ أَدْمَجَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَدْمَجَ). ""مُدْمَجٌ فِي الفَرِيقِ"" : أُدْخِلَ فِيهِ. ""سَائِلٌ مُدْمَجٌ فِي بَاقِي الْمَوَادِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4673, 'مُؤَدّىً', 'مؤدى', 'اسم مفعول', 'أدي', 'مءدى', 'مد', 'مفع. مِنْ أَدَّى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"مُؤَدّىً-مُؤَدّىً [أ د ي] (مفع. مِنْ أَدَّى). ""مُؤَدَّى الكَلاَمِ"" : مَعْنَاهُ، مَضْمُونُهُ، فَحْوَاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4674, 'مُؤَدّاة', 'مؤداة', 'اسم مفعول', '', 'مءداة', 'مدة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُؤَدّىً-مُؤَدّىً [أ د ي] (مفع. مِنْ أَدَّى). ""مُؤَدَّى الكَلاَمِ"" : مَعْنَاهُ، مَضْمُونُهُ، فَحْوَاهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4675, 'مُرَادٌ', 'مراد', 'اسم مفعول', 'رود', 'مراد', 'مرد', 'مفع. مِنْ أَرَادَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرَادٌ-مُرَادٌ [ر و د] (مفع. مِنْ أَرَادَ). 1.""حَقّقَ مُرَادَهُ"" : الشَّيْء الَّذِي يُرَادُ، الْمُبْتَغَى، الْمَرْغُوبُ فِيهِ. 2.: اِسْمُ عَلَمٍ لِلْمُذَكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4676, 'مُرْتَجَعٌ', 'مرتجع', 'اسم مفعول', 'رجع', 'مرتجع', 'مرتجع', 'مفع. مِن اِرْتَجَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِرْتَجَعَ). 1.""مُرْتَجَعَاتُ الصُّحُفِ"" : مَا لَمْ يُبَعْ مِنْهَا، مَا تَبَقَّى مِنْهَا، الْمَرْجوعاتُ. 2.""أَمْرٌ مُرْتَجَعٌ"" : أُعِيدَ إِرْجَاعُهُ. 3.""عَمَلٌ مُرْتَجَعٌ"" : ذُو فَائِدَةٍ، ذُو نَفْعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4677, 'مُرْتَجَلٌ', 'مرتجل', 'اسم مفعول', 'رجل', 'مرتجل', 'مرتجل', 'مفع. مِن اِرْتَجَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرْتَجِلٌ-مُرْتَجِلٌ، ةٌ [ر ج ل] (فَا. مِن اِرْتَجَلَ). ""مُرْتَجِلٌ لِخِطَابِهِ"" : أَلْقَاهُ عَلَى بَغْتَةٍ، مِنْ دُونِ تَحْضِيرٍ، فَجْأَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4678, 'مُرْتَحَلٌ', 'مرتحل', 'اسم مفعول', 'رحل', 'مرتحل', 'مرتحل', 'مفع. مِن اِرْتَحَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرْتَحَلٌ-مُرْتَحَلٌ [ر ح ل] (مفع. مِن اِرْتَحَلَ). 1.""اِجْتَمَعُوا صَبَاحاً فِي الْمُرْتَحَلِ"" : مَوْضِعُ الارْتِحَالِ. 2.""مُرْتَحَلُ الجَمَلِ"": مَوْضِعُ رَحْلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4679, 'مُرْتَفَعٌ', 'مرتفع', 'اسم مفعول', 'رفع', 'مرتفع', 'مرتفع', 'مفع. مِن اِرْتَفَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِرْتَفَعَ). ""جَلَسَ فِي مُرْتَفَعٍ"" : مَكَانٌ عَالٍ. 2.""مُرْتَفَعَاتُ البِلاَدِ"" : جِبَالُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4680, 'مُرْتَقَبٌ', 'مرتقب', 'اسم مفعول', 'رقب', 'مرتقب', 'مرتقب', 'مفع. مِن اِرْتَقَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُرْتَقَبٌ-مُرْتَقَبٌ، ةٌ [ر ق ب] (مفع. مِن اِرْتَقَبَ). ""حَادِثٌ مُرْتَقَبٌ"" : مَا يُنْتَظَرُ حُدُوثُهُ وَتَوَقُّعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4681, 'مُرْتَقَعٌ', 'مرتقع', 'اسم مفعول', 'رقع', 'مرتقع', 'مرتقع', 'مفع. مِن اِرْتَقَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِرْتَقَعَ). ""ثَوْبٌ مُرْتَقَعٌ"" : مَوْضِعُ الرُّقْعَةِ مِنَ الثَّوْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4682, 'مُرْتَقىً', 'مرتقى', 'اسم مفعول', 'رقي', 'مرتقى', 'مرتق', 'مفع. مِن اِرْتَقَى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِرْتَقَى). ""مَكَانٌ صَعْبُ الْمُرْتَقَى"" : أَيْ صَعْبُ الارْتِقَاءِ، صَعْبُ الْمَنَالِ. ""اِرْتَقَى مُرْتَقًى صَعْباً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4683, 'مُرْتَقاة', 'مرتقاة', 'اسم مفعول', '', 'مرتقاة', 'مرتقة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِرْتَقَى). ""مَكَانٌ صَعْبُ الْمُرْتَقَى"" : أَيْ صَعْبُ الارْتِقَاءِ، صَعْبُ الْمَنَالِ. ""اِرْتَقَى مُرْتَقًى صَعْباً""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4684, 'مُرْتَكَبٌ', 'مرتكب', 'اسم مفعول', 'ركب', 'مرتكب', 'مرتكب', 'مفع. مِن اِرْتَكَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرْتَكَبٌ-مُرْتَكَبٌ [ر ك ب] (مفع. مِن اِرْتَكَبَ). ""اِقْتَرَفَ مُرْتَكَباً"" : ذَنْباً، مُقْتَرَفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4685, 'مُرْتَكَزٌ', 'مرتكز', 'اسم مفعول', 'ركز', 'مرتكز', 'مرتكز', 'مفع. مِن اِرْتَكَزَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِرْتَكَزَ). ""مُرْتَكَزَاتُ العَمَلِ أَوِ البِنَاءِ"" : أُسُسُهُ، دَعَائِمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4686, 'مُرْتَهَنٌ', 'مرتهن', 'اسم مفعول', 'رهن', 'مرتهن', 'مرتهن', '. مفع. مِن اِرْتَهَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". (مفع. مِن اِرْتَهَنَ). ""عَقَارٌ مُرْتَهَنٌ"" : كُلُّ مَا أُخِذَ رَهْناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4687, 'مُرْسَلٌ', 'مرسل', 'اسم مفعول', 'رسل', 'مرسل', 'مرسل', 'مفع. مِنْ أَرْسَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَرَاسِيلُ"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ أَرْسَلَ). 1.""مُرْسَلٌ إِلَى القَوْمِ"" : الْمَبْعُوثُ إِلَيْهِمْ.الأعراف آية 75 أَتَعْلَمُونَ أَنَّ صَالِحاً مُرْسَلٌ مِنْ رَبِّهِ (قرآن). 2.""الْمُرْسَلُ إِلَيْهِ"" : الْمُوَجَّهُ إِلَيْهِ الكَلاَمُ أَوِ الرِّسَالَةُ. 3.""شِعْرٌ مُرْسَلٌ"" : شِعْرٌ غَيْرُ مُقَيَّدٍ بِقَافِيَةٍ. 4.""نَثْرٌ مُرْسَلٌ"" : خَالٍ مِنَ السَّجْعِ وَالْمُحَسِّنَاتِ. 5.""حَدِيثٌ مُرْسَلٌ"" : هُوَ مَا سَقَطَ مِنْ إِسْنَادِهِ الصَّحَابِيُّ. 6.: سُورَةٌ مِنْ سُوَرِ القُرْآنِ.المرسلات آية 1،2 وَالْمُرْسَلاَتِ عُرْفاً فَالعَاصِفَاتِ عَصْفاً (قرآن): الرِّيَاحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4688, 'مَرَاسِيلُ', 'مراسيل', 'اسم مفعول', '', 'مراسيل', 'مرسل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4689, 'مُرْغَمٌ', 'مرغم', 'اسم مفعول', 'رغم', 'مرغم', 'مرغم', 'مفع. مِنْ أَرْغَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَرْغَمَ). ""قَامَ بِالعَمَلِ مُرْغَماً"" : مُجْبَراً، عَلَى الرَّغْمِ مِنْ إِرَادَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4690, 'مُرْفَقٌ', 'مرفق', 'اسم مفعول', 'رفق', 'مرفق', 'مرفق', 'مفع. مِنْ أَرْفَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مُرْفَقٌ-مُرْفَقٌ، ةٌ [ر ف ق] (مفع. مِنْ أَرْفَقَ). ""مُرْفَقٌ بِهِ"" : فِي طَيِّهِ، مَعَهُ. ""وَثَائِقُ مُرْفَقَةٌ مَعَ التَّقْرِيرِ العَامِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4691, 'مُؤَرَّقٌ', 'مؤرق', 'اسم مفعول', 'أرق', 'مءرق', 'مرق', 'مفع. مِنْ أَرَّقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُؤَرَّقٌ-مُؤَرَّقٌ، ةٌ [أ ر ق] (مفع. مِنْ أَرَّقَ)."" حُزْنُهُ وَهُمُومُهُ جَعَلَتْهُ مُؤَرَّقاً"" : مُصاباً بِالأرَقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4692, 'مُرْهَفٌ', 'مرهف', 'اسم مفعول', 'رهف', 'مرهف', 'مرهف', 'مفع. مِنْ أَرْهَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ أَرْهَفَ). 1.""مُرْهَفُ الجِسْمِ"" : دَقِيقُهُ. 2.""هُوَ مُرْهَفُ الحِسِّ"": رَقِيقُ الحِسِّ. 3.""سَيْفٌ مُرْهَفٌ"" : مُحَدَّدٌ، حَادُّ الطَّرَفِ. 4.""لَهَا خِصْرٌ مُرْهَفٌ"" : ضَامِرٌ، نَحِيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4693, 'مُرْهَقٌ', 'مرهق', 'اسم مفعول', 'رهق', 'مرهق', 'مرهق', 'مفع. مِنْ أَرْهَقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَرْهَقَ). ""وَجَدَهُ مُرْهَقاً "" : مُتْعَباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4694, 'مُزَاحٌ', 'مزاح', 'اسم مفعول', 'مزح', 'مزاح', 'مزح', 'مفع. مِنْ أَزَاحَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُزَاحٌ-مُزَاحٌ (مفع. مِنْ أَزَاحَ). ""عَمَلٌ مُزَاحٌ"" : مُبْعَدٌ، مُنَحًّى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4695, 'مُزْدَحَمٌ', 'مزدحم', 'اسم مفعول', 'زحم', 'مزدحم', 'مزدحم', 'مفع. مِن اِزْدَحَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزْدَحِمٌ-مُزْدَحِمٌ، ةٌ [ز ح م] (فَا. مِن ازْدَحَمَ). ""شَارِعٌ مُزْدَحِمٌ بِالْمَارَّةِ"" : كَثِيرُ الْمَارَّةِ، فِيهِ ازْدِحَامٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4696, 'مُزْمَعٌ', 'مزمع', 'اسم مفعول', 'زمع', 'مزمع', 'مزمع', 'مفع. مِنْ أَزْمَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزْمَعٌ-مُزْمَعٌ [ز م ع] (مفع. مِنْ أَزْمَعَ). ""سَفَرٌ مُزْمَعٌ عَلَيْهِ"": مُتَّفَقٌ عَلَيْهِ. ""اِجْتِمَاعٌ مُزْمَعٌ عَقْدُهُ"" ""قَرَارٌ مُزْمَعٌ عَلَى تَنْفِيذِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4697, 'مُسْبَعٌ', 'مسبع', 'اسم مفعول', 'سبع', 'مسبع', 'مسبع', 'مفع. مِنْ أَسَبَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْبَعٌ-مُسْبَعٌ [س ب ع] (مفع. مِنْ أَسَبَعَ). 1.""مَوْلُودٌ مُسْبَعٌ"" : مَوْلُودٌ لِسَبْعَةِ أَشْهُرٍ مِنَ الْحَمْلِ. 2.""رَضِيعٌ مُسْبَعٌ"" : مَاتَتْ أُمُّهُ فَتُرْضِعُهُ غَيْرُهَا. 3.""رَجُلٌ مُسْبَعٌ"" : مُتْرَفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4698, 'مُسْتَأْنَفٌ', 'مستأنف', 'اسم مفعول', 'أنف', 'مستءنف', 'مستنف', 'مفع. مِنْ: اِسْتَأْنَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مُسْتَأْنَفٌ-مُسْتَأْنَفٌ [أ ن ف] (مفع. مِنْ: اِسْتَأْنَفَ). ""حُكْمٌ مُسْتَأْن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4699, 'مُسْتَبَاحٌ', 'مستباح', 'اسم مفعول', 'بوح', 'مستباح', 'مستبح', 'مفع. مِن اِسْتَبَاحَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَبَاحَ). 1.""دَمُهُ مُسْتَبَاحٌ"" : أَيْ دَمُهُ مُجَازٌ سَفْكُهُ. 2.""حَدِيقَةٌ مُسْتَبَاحَةٌ"" : مُحَطَّمَةُ الأَشْجَارِ وَالأَسْوَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4700, 'مُسْتَبْعَدٌ', 'مستبعد', 'اسم مفعول', 'بعد', 'مستبعد', 'مستبعد', 'مفع. مِن اِسْتَبْعَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُسْتَبْعَدٌ-مُسْتَبْعَدٌ، ةٌ [ب ع د] (مفع. مِن اِسْتَبْعَدَ). ""أَمْرٌ مُسْتَبْعَدٌ حُدُوثُهُ"" : بَعِيدُ الوُقُوعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4701, 'مُسْتَثْنىً', 'مستثنى', 'اسم مفعول', 'ثني', 'مستثنى', 'مستثن', 'مفع. مِن اِسْتَثْنَى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"مُسْتَثْنىً-مُسْتَثْنىً [ث ن ي] (مفع. مِن اِسْتَثْنَى). 1.""مُسْتَثْنىً مِنْ بَيْنِ أَصْدِقَائِهِ"" : خَارِجٌ مِنْ نِطَاقِ عَمَلٍ أَوْ حُكْمٍ مِنْ بَيْنِ أَصْدِقَائِهِ. 2.""الْمُسْتَثْنَى فِي النَّحْوِ"" : هُوَ مَا وَقَعَ الإِسْنَادُ بِمَعْزِلٍ عَنْهُ: ""دَخَلَ الطُّلاَّبُ إِلاَّ عُمَرَ"". وَالْمُسْتَثْنَى أَنْوَاعٌ : مُتَّصِلٌ وَمُفَرَّعٌ وَمُنْقَطِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4702, 'مُسْتَثْناة', 'مستثناة', 'اسم مفعول', '', 'مستثناة', 'مستثنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَثْنىً-مُسْتَثْنىً [ث ن ي] (مفع. مِن اِسْتَثْنَى). 1.""مُسْتَثْنىً مِنْ بَيْنِ أَصْدِقَائِهِ"" : خَارِجٌ مِنْ نِطَاقِ عَمَلٍ أَوْ حُكْمٍ مِنْ بَيْنِ أَصْدِقَائِهِ. 2.""الْمُسْتَثْنَى فِي النَّحْوِ"" : هُوَ مَا وَقَعَ الإِسْنَادُ بِمَعْزِلٍ عَنْهُ: ""دَخَلَ الطُّلاَّبُ إِلاَّ عُمَرَ"". وَالْمُسْتَثْنَى أَنْوَاعٌ : مُتَّصِلٌ وَمُفَرَّعٌ وَمُنْقَطِعٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4703, 'مُسْتَجَابٌ', 'مستجاب', 'اسم مفعول', 'جوب', 'مستجاب', 'مستجب', 'مفع. مِن اِسْتَجَابَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَجَابَ). ""دَعْوَةٌ مُسْتَجَابَةٌ بِإِذْنِ الله"" : دَعْوَةٌ مَقْضِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4704, 'مُسْتَجَدٌّ', 'مستجد', 'اسم مفعول', 'جدد', 'مستجد', 'مستجد', 'مفع. مِن اِسْتَجَدَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَجَدَّ). ""مُسْتَجَدَّاتُ الْمَرْحَلَةِ الرَّاهِنَةِ"" : مُتَطَلَّبَاتُهَا الجَدِيدَةُ، تَطَوُّرَاتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4705, 'مُسْتَجْوَبٌ', 'مستجوب', 'اسم مفعول', 'جوب', 'مستجوب', 'مستجب', 'مفع. مِن اِسْتَجْوَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن اِسْتَجْوَبَ). ""مُسْتَجْوَبٌ في مَوْضُوعٍ مُحَدَّدٍ"" : أَيْ مَنْ تَمَّ اسْتِجْوَابُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4706, 'مُسْتَحَبٌّ', 'مستحب', 'اسم مفعول', 'حبب', 'مستحب', 'مستحب', 'مفع مِن اِسْتَحَبَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع مِن اِسْتَحَبَّ). ""عَمَلٌ مُسْتَحَبٌّ"" : مَا يُؤْثَرُ وَيُفَضَّلُ وَيُقَدَّمُ عَلَى غَيْرِهِ وَيَجِدُ اسْتِحْسَاناً فِي النَّفْسِ، مُسْتَحْسَنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4707, 'مُسْتَحْدَثٌ', 'مستحدث', 'اسم مفعول', 'حدث', 'مستحدث', 'مستحدث', 'مفع. مِن اِسْتَحْدَثَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَحْدَثَ). 1.""اِخْتِرَاعٌ مُسْتَحْدَثٌ"" : جَدِيدٌ. 2.""كَلاَمٌ مُسْتَحْدَثٌ"" : لَمْ يَكُنْ سَائِداً مِنْ قَبْلُ، مُبْتَكَرٌ، مُبْتَدَعٌ. 3.""مُصْطَلَحٌ مُسْتَحْدَثٌ"" : مُصْطَلَحٌ جَدِيدٌ، أَيْ لَمْ يَكُنْ مُتَدَاوَلاً مِنْ قَبْلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4708, 'مُسْتَحْسَنٌ', 'مستحسن', 'اسم مفعول', 'حسن', 'مستحسن', 'مستحسن', 'مفع. مِن اِسْتَحْسَنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَحْسَنٌ-مُسْتَحْسَنٌ، ةٌ [ح س ن] (مفع. مِن اِسْتَحْسَنَ). 1.""عَمَلٌ مُسْتَحْسَنٌ"" : مُسْتَحَبٌّ. 2.""نَالَ دَرَجَةَ مُسْتَحْسَنٍ"": أَيْ دَرَجَةً أَقَلَّ مِنْ حَسَنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4709, 'مُسْتَحْضَرٌ', 'مستحضر', 'اسم مفعول', 'حضر', 'مستحضر', 'مستحضر', 'مفع. مِن اِسْتَحْضَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَحْضَرَ). ""مُسْتَحْضَرٌ كِيمِيَائِيٌّ"" : مَزِيجٌ مِنَ الْمَوَادِّ جَرَى تَحْضِيرُهَا فِي الْمُخْتَبَرِ. ""مُسْتَحْضَرَاتُ التَّجْمِيلِ"" ""مُسْتَحْضَرَاتٌ طِبِّيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4710, 'مُسْتَحَقٌّ', 'مستحق', 'اسم مفعول', 'حقق', 'مستحق', 'مستحق', 'مفع. مِن اِسْتَحَقَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَحَقَّ). ""أَمْرٌ مُسْتَحَقٌّ"" : أَمْرٌ قَائِمٌ وَمَفْرُوضٌ. ""مُسْتَحَقَّاتُ الْمَرْحَلَةِ الرَّاهِنَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4711, 'مُسْتَحْكَمٌ', 'مستحكم', 'اسم مفعول', 'حكم', 'مستحكم', 'مستحكم', 'مفع. مِن اِسْتَحْكَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَحْكَمَ). 1.""كَانَ العَدَاءُ مُسْتَحْكَماً بَيْنَهُمَا"" : نَافِذاً. ""رَأَيْتُ الأُلْفَةَ مُسْتَحْكَمَةً بَيْنَ الإِنْسَانِ وَالْمَخْلُوقَاتِ"". 2.""حِصْنٌ مُسْتَحْكَمٌ"" : حِصْنٌ مَوْقِعُهُ مُحَصَّنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4712, 'مُسْتَحْلَبٌ', 'مستحلب', 'اسم مفعول', 'حلب', 'مستحلب', 'مستحلب', 'مفع. مِن اِسْتَحْلَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَحْلَبَ): مُرَكَّبٌ مُؤَلَّفٌ مِنْ سَائِلٍ غَيْرِ مُتَجَانِسٍ يُحَضَّرُ بِإِضَافَةِ سَائِلٍ آخَرَ لاَ يَمْتَزِجُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4713, 'مُسْتَحَمٌّ', 'مستحم', 'اسم مفعول', 'حمم', 'مستحم', 'مستحم', 'مفع. مِن اِسْتَحَمَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَحَمٌّ-مُسْتَحَمٌّ [ح م م] (مفع. مِن اِسْتَحَمَّ). ""ذَهَبَ إِلَى الْمُسْتَحَمِّ"" : مَوْضِعُ الاسْتِحْمَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4714, 'مُسْتَخْدَمٌ', 'مستخدم', 'اسم مفعول', 'خدم', 'مستخدم', 'مستخدم', 'مفع. مِن اِسْتَخْدَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن اِسْتَخْدَمَ). ""مُسْتَخْدَمٌ فِي مَعَامِلِ الزَّيْتِ"" : مَنْ يَشْتَغِلُ فِي...، أَجِيرٌ، عَامِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4715, 'مُسْتَخْرَجٌ', 'مستخرج', 'اسم مفعول', 'خرج', 'مستخرج', 'مستخرج', 'مفع. مِن اِسْتَخْرَجَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُسْتَخْرَجٌ-مُسْتَخْرَجٌ، ةٌ [خ ر ج] (مفع. مِن اِسْتَخْرَجَ). ""مَعْدِنٌ مُسْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4716, 'مُسْتَخْلَصٌ', 'مستخلص', 'اسم مفعول', 'خلص', 'مستخلص', 'مستخلص', 'مفع. مِن اِسْتَخْلَصَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَخْلَصَ). 1.""إِنْتَاجٌ مُسْتَخْلَصٌ"" : مُخْتَارٌ. 2.""مُسْتَخْلَصَاتُ الْحَلِيبِ"" : مُسْتَحْصَلاَتُهُ. 3.""فِكْرَةٌ مُسْتَخْلَصَةٌ مِنَ النَّصِّ"" : مُسْتَخْرَجَةٌ، مُسْتَنْتَجَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4717, 'مُسْتَدِيرٌ', 'مستدير', 'اسم مفعول', 'دور', 'مستدير', 'مستدر', 'مفع. مِن اِسْتَدَارَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَدِيرٌ-مُسْتَدِيرٌ، ةٌ [د و ر] (مفع. مِن اِسْتَدَارَ). 1.""وَقَفَ عِنْدَ الْمُسْتَدِيرَةِ"" : دَائِرَةٌ تَلْتَقِي عِنْدَهَا عِدَّةُ طُرُقٍ... 2.""شَكْلٌ مُسْتَدِيرٌ"" : عَلَى هَيْئَةِ دَائِرَةٍ. 3.""نُظِّمَتْ مَائِدَةٌ مُسْتَدِيرَةٌ حَوْلَ مَوْضُوعِ التَّعْلِيمِ"" : مَائِدَةٌ دَائِرِيَّةُ الشَّكْلِ يَجْلِسُ حَوْلَهَا الْمُتَحَاوِرُونَ لِلنِّقَاشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4718, 'مُسْتَدَقٌّ', 'مستدق', 'اسم مفعول', 'دقق', 'مستدق', 'مستدق', 'مفع. مِن اِسْتَدَقَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَدَقٌّ-مُسْتَدَقٌّ [د ق ق] (مفع. مِن اِسْتَدَقَّ). 1.""عَجِينٌ مُسْتَدَقٌّ"" : صُيِّرَ رَقِيقاً. 2.""مُسْتَدَقُّ السَّاعِدِ"" : مُقَدَّمَهُ مِمَّا يَلِي الرُّسْغَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4719, 'مُسْتَدَلٌّ', 'مستدل', 'اسم مفعول', 'دلل', 'مستدل', 'مستدل', 'مفع. مِن اِسْتَدَلَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَدَلَّ). ""آرَاءٌ مُسْتَدَلٌّ عَلَيْهَا بِحَقَائِقَ جَدِيدَةٍ"" : أَيْ مُدَعَّمَةٌ بِحَقَائِقَ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4720, 'مُسْتَرَقٌّ', 'مسترق', 'اسم مفعول', 'رقق', 'مسترق', 'مسترق', 'مفع. مِن اِسْتَرَقَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُسْتَرَقٌّ - [ر ق  ق]. (مفع. مِن اِسْتَرَقَّ). ""شَيْءٌ مُسْتَرَقٌّ"" : رَقِيقٌ، نَحِيفٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4721, 'مُسْتَسَاغٌ', 'مستساغ', 'اسم مفعول', 'سوغ', 'مستساغ', 'مستسغ', 'مفع. من اِسْتَسَاغَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَسَاغٌ-مُسْتَسَاغٌ، ةٌ [س و غ] (مفع. من اِسْتَسَاغَ). 1.""طَعَامٌ مُسْتَسَاغٌ"" : سَهْلُ البَلْعِ. ""شَرَابٌ مُسْتَسَاغٌ"". 2.""كَلاَمٌ مُسْتَسَاغٌ"" : كَلاَمٌ مَقْبُولٌ لِخِفَّتِهِ وَعُذُوبَةِ أَلْفَاظِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4722, 'مُسْتَشَارٌ', 'مستشار', 'اسم مفعول', 'شور', 'مستشار', 'مستشر', 'مفع. مِن اِسْتَشَارَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن اِسْتَشَارَ). ""مُسْتَشَارُ الْمَلِكِ أَوِ الرَّئِيسِ"" : مَنْ يُسْتَشَارُ وَيُؤْخَذُ بِرَأْيِهِ فِي القَضَايَا. ""مُسْتَشَارُ الشَّرِكَةِ"" ""مُسْتَشَارٌ فِي مَحْكَمَةِ الاسْتِئْنَافِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4723, 'مُسْتَشْفىً', 'مستشفى', 'اسم مفعول', 'شفي', 'مستشفى', 'مستشف', 'مفع. مِنْ اِسْتَشْفَى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ اِسْتَشْفَى). ""دَخَلَ الْمُسْتَشْفَى لِيُجْرِيَ فُحُوصاً طِبِّيَّةً"" : الْمَكَانُ الَّذِي يَدْخُلُهُ الْمَرْضَى لِلاسْتِشْفَاءِ، وَهُوَ مُجَهَّزٌ بِآلاَتِ الطِّبِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4724, 'مُسْتَشْفاة', 'مستشفاة', 'اسم مفعول', '', 'مستشفاة', 'مستشفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ اِسْتَشْفَى). ""دَخَلَ الْمُسْتَشْفَى لِيُجْرِيَ فُحُوصاً طِبِّيَّةً"" : الْمَكَانُ الَّذِي يَدْخُلُهُ الْمَرْضَى لِلاسْتِشْفَاءِ، وَهُوَ مُجَهَّزٌ بِآلاَتِ الطِّبِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4725, 'مُسْتَطَاعٌ', 'مستطاع', 'اسم مفعول', 'طوع', 'مستطاع', 'مستطع', 'مفع. من اِسْتَطَاعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَطَاعٌ-مُسْتَطَاعٌ [ط و ع] (مفع. من اِسْتَطَاعَ). ""فِي مُسْتَطَاعِهِ أَنْ يُنْجِزَ عَمَلَهُ"" : فِي مَقْدِرَتِهِ، فِي إِمْكَانِهِ. ""عَلَى قَدْرِ الْمُسْتَطَاعِ"" ""فَصَبْرًا فِي مَجَالِ الْمَوْتِ صَبْـراً*فَمَـا نَيْلُ الخُلُودِ بِمُسْتَطَـاعِ"". (قطري بن الفجاءة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4726, 'مُسْتَعَارٌ', 'مستعار', 'اسم مفعول', 'عور', 'مستعار', 'مستعر', 'مفع. مِن اِسْتَعَارَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَعَارٌ-مُسْتَعَارٌ، ةٌ [ع و ر] (مفع. مِن اِسْتَعَارَ). 1.""اِسْمٌ مُسْتَعَارٌ"" : اِسْمٌ غَيْرُ الاسْمِ الْحَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4727, 'مُسْتَعَانٌ', 'مستعان', 'اسم مفعول', 'عون', 'مستعان', 'مستعن', 'مفع. مِن اِسْتَعَانَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُسْتَعَانٌ - [ع و ن]. (مفع. مِن اِسْتَعَانَ).: مَنْ تَطْلُبُ مِنْهُ الْمُسَاعَدَةَ وَالْمَعُونَةَ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4728, 'مُسْتَعْبَدُ', 'مستعبد', 'اسم مفعول', 'عبد', 'مستعبد', 'مستعبد', 'مفع. مِن اِسْتَعْبَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُسْتَعْبَدُ-مُسْتَعْبَدُ، ةٌ [ع ب د] (مفع. مِن اِسْتَعْبَدَ). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4729, 'مُسْتَعْجَلٌ', 'مستعجل', 'اسم مفعول', 'عجل', 'مستعجل', 'مستعجل', 'مفع. مِن اِسْتَعْجَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُسْتَعْجَلٌ-مُسْتَعْجَلٌ، ةٌ [ع ج ل] (مفع. مِن اِسْتَعْجَلَ). ""أَمْرٌ مُسْتَعْجَلٌ"" : مُلِحٌّ، ضَرُورِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4730, 'مُسْتَعْجَمٌ', 'مستعجم', 'اسم مفعول', 'عجم', 'مستعجم', 'مستعجم', 'مفع. مِن اِسْتَعْجَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَعْجَمَ). ""رَجُلٌ مُسْتَعْجَمٌ"" : غَيْرُ قَادِرٍ عَلَى الكَلاَمِ أَصْلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4731, 'مُسْتَعْمَرٌ', 'مستعمر', 'اسم مفعول', 'عمر', 'مستعمر', 'مستعمر', 'مفع. مِن اِسْتَعْمَرَ.', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ون، ات. (مفع. مِن اِسْتَعْمَرَ). ""بَلَدٌ مُسْتَعْمَرٌ"" : أَيْ خَاضِعٌ لِسُلْطَةٍ أَجْنَبِيَّةٍ حَيْثُ تُسْتَغَلُّ خَيْرَاتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4732, 'مُسْتَعْمَلٌ', 'مستعمل', 'اسم مفعول', 'عمل', 'مستعمل', 'مستعمل', 'مفع. مِن اِسْتَعْمَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُسْتَعْمَلٌ-مُسْتَعْمَلٌ، ةٌ [ع م ل] (مفع. مِن اِسْتَعْمَلَ). ""آلَةٌ مُسْتَعْمَلَةٌ"" : أَي اِسْتُعْمِلَتْ، لَيْسَتْ جَدِيدَةً. ""سَيَّارَةٌ مُسْتَعْمَلَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4733, 'مُسْتَغَلٌّ', 'مستغل', 'اسم مفعول', 'غلل', 'مستغل', 'مستغل', 'مفع. مِن اِسْتَغَلَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن اِسْتَغَلَّ). ""عَامِلٌ مُسْتَغَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4734, 'مُسْتَقْبَلٌ', 'مستقبل', 'اسم مفعول', 'قبل', 'مستقبل', 'مستقبل', 'مفع. من اِسْتَقْبَلَ الآتِي مِ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُسْتَقْبَلٌ-مُسْتَقْبَلٌ [ق ب ل] (مفع. من اِسْتَقْبَلَ) (الآتِي مِنَ الزَّمَانِ). 1.""لَهُ مُسْتَقْبَلٌ زَاهِرٌ"" : سَتَكُونُ حَيَاتُهُ الْمُقْبِلَةُ، الآتِيَةُ زَاهِرَةً. ""رَسَّخَتْ وَثِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4735, 'مُسْتَقَرٌّ', 'مستقر', 'اسم مفعول', 'قرر', 'مستقر', 'مستقر', 'مفع. من اِسْتَقَرَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"(مفع. من اِسْتَقَرَّ). ""وَجَدَ فِي القَرْيَةِ مُسْتَقَرّاً"" : مَكَاناً لِلاسْتِقْرَارِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4736, 'مُسْتَكْشَفٌ', 'مستكشف', 'اسم مفعول', 'كشف', 'مستكشف', 'مستكشف', 'مفع. مِن اِسْتَكْشَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُسْتَكْشَفٌ-مُسْتَكْشَفٌ، ةٌ [ ك ش ف ] (مفع. مِن اِسْتَكْشَفَ) . ""مَعْدِنٌ مُسْتَكْشَفٌ"" : تَمَّ إِيجَادُهُ بَعْدَ التَّنْقِيب عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4737, 'مُسْتَلَبٌ', 'مستلب', 'اسم مفعول', 'سلب', 'مستلب', 'مستلب', 'مفع. مِن اِسْتَلَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن اِسْتَلَبَ). ""رَجُلٌ مُسْتَلَبٌ"" : مَأْخُوذٌ عِنْدَ غَيْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4738, 'مُسْتَلْزَمٌ', 'مستلزم', 'اسم مفعول', 'لزم', 'مستلزم', 'مستلزم', 'مفع. من اِسْتَلْزَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من اِسْتَلْزَمَ). ""مُسْتَلْزَمَاتُ الإِجْرَاءِ الجَدِيدِ"" : مُقْتَضَيَاتُهُ، مُتَطَلَّبَاتُهُ. ""أَدَوَاتٌ مِنْ مُسْتَلْزَمَاتِ الْحَضَارَةِ"" ""مُسْتَلْزَمَاتُ الْحَيَاةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4739, 'مُسْتَمَدٌّ', 'مستمد', 'اسم مفعول', 'مدد', 'مستمد', 'مستمد', 'مفع. مِن اِسْتَمَدَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَمَدٌّ-مُسْتَمَدٌّ، ةٌ [م د د] (مفع. مِن اِسْتَمَدَّ). ""فِكْرَةٌ مُسْتَمَدَّةٌ مِنَ الْفَلْسَفَةِ الإِسْلاَمِيَّةِ"" : مَأْخُوذَةٌ، مُسْتَقَاةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4740, 'مُسْتَمْطَرٌ', 'مستمطر', 'اسم مفعول', 'مطر', 'مستمطر', 'مستمطر', 'مفع. مِن اِسْتَمْطَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَمْطَرٌ-مُسْتَمْطَرٌ، ةٌ [م ط ر] (مفع. مِن اِسْتَمْطَرَ). ""مَكَانٌ مُسْتَمْطَرٌ"" : مَكَانٌ ظَاهِرٌ مُنْكَشِفٌ للمَطَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4741, 'مُسْتَمْلَحٌ', 'مستملح', 'اسم مفعول', 'ملح', 'مستملح', 'مستملح', 'مفع. مِن اِسْتَمْلَحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَمْلَحٌ-مُسْتَمْلَحٌ، ةٌ [م ل ح] (مفع. مِن اِسْتَمْلَحَ). 1.""وَجْهٌ مُسْتَمْلَحٌ"" : حَسَنٌ، مَلِيحٌ. 2.""هَمُّهُ فِي الْحَيَاةِ النُّكَتُ اللَّطِيفَةُ وَالنَّوَادِرُ الْمُسْتَمْلَحَةُ"" : أَيْ نَوَادِرُ حَسَنَةٌ لَهَا وَقْعٌ جَمِيلٌ عَلَى النَّفْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4742, 'مُسْتَنْبَتٌ', 'مستنبت', 'اسم مفعول', 'نبت', 'مستنبت', 'مستنبت', 'مفع. من اِسْتَنْبَتَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَنْبَتٌ-مُسْتَنْبَتٌ [ن ب ت] (مفع. من اِسْتَنْبَتَ).: مَكَانُ نَبْتِ النَّبَاتَاتِ وَالأَزْهَارِ، مَنْبِتٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4743, 'مُسْتَنْجَعٌ', 'مستنجع', 'اسم مفعول', 'نجع', 'مستنجع', 'مستنجع', 'مفع. مِن اِسْتَنْجَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَنْجَعَ). ""اِنْتَشَرَتِ القَافِلَةُ فِي الْمُسْتَنْجَعِ"" : الْمَكَانُ الَّذِي يَقْصِدُهُ النَّاسُ طَلَباً لِلْكَلإِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4744, 'مُسْتَنَدٌ', 'مستند', 'اسم مفعول', 'سند', 'مستند', 'مستند', 'مفع. مِن اِسْتَنَدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَنَدَ). 1.""مُسْتَنَدُ مِلْكِيَّةٍ"" : العَقْدُ الْمُعْتَمَدُ. 2.""قَدَّمَ حُجَجاً بِكُلِّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4745, 'مُسْتَنْزَفٌ', 'مستنزف', 'اسم مفعول', 'نزف', 'مستنزف', 'مستنزف', 'مفع. مِن اِسْتَنْزَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُسْتَنْزَفٌ-مُسْتَنْزَفٌ، ةٌ [ن ز ف] (مفع. مِن اِسْتَنْزَفَ). ""مَوَارِدُ مُسْتَنْزَفَةٌ"" : مُسْتَخْرَجَةٌ، مُسْتَخْلَصَةٌ عَنْ آخِرِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4746, 'مُسْتَنْسَخٌ', 'مستنسخ', 'اسم مفعول', 'نسخ', 'مستنسخ', 'مستنسخ', 'مفع. من اِسْتَنْسَخَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من اِسْتَنْسَخَ). 1.""نَصٌّ مُسْتَنْسَخٌ"" : نَصٌّ تَمَّ تَصْوِيرُهُ، نَسْخُهُ بِآلَةِ الاسْتِنْسَاخِ. 2.""مُسْتَنْسَخَاتُ الطُّلاَّبِ"" : الْمُحَاضَرَاتُ الَّتِي يَنْقُلُونَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4747, 'مُسْتَنْشَقٌ', 'مستنشق', 'اسم مفعول', 'نشق', 'مستنشق', 'مستنشق', 'مفع. من اِسْتَنْشَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَنْشَقٌ-مُسْتَنْشَقٌ [ن ش ق] (مفع. من اِسْتَنْشَقَ). ""هَوَاءٌ مُسْتَنْشَقٌ"" : هَوَاءٌ أُخِذَ مِنْهُ نَفَسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4748, 'مُسْتَنْفَرٌ', 'مستنفر', 'اسم مفعول', 'نفر', 'مستنفر', 'مستنفر', 'مفع. من اِسْتَنْفَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُسْتَنْفَرٌ-مُسْتَنْفَرٌ، ةٌ [ن ف ر] (مفع. من اِسْتَنْفَرَ). 1.""جَيْشٌ مُسْتَنْفَرٌ"" : مُعَبَّأٌ، عَلَى أُهْبَةِ الانْطِلاَقِ. 2.""حَيَوَانٌ مُسْتَنْفَرٌ"": فَزِعٌ، مُصَابٌ بِالذُّعْرِ. المدثر آية 50 كَأَنَّهُمْ حُمُرٌ مُسْتَنْفَرَةٌ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4749, 'مُسْتَنْقَعٌ', 'مستنقع', 'اسم مفعول', 'نقع', 'مستنقع', 'مستنقع', 'مفع. مِن اِسْتَنْقَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَنْقَعَ). 1.""نَتَنَ مَاءُ الْمُسْتَنْقَعِ"" : الْمَوْضِعُ الَّذِي يَتَجَمَّعُ فِيهِ الْمَاءُ مُدَّةً طَوِيلَةً وَيَكُونُ مَأْوىً لِلطَّحَالِبِ وَالضَّفَادِعِ وَالبَعُوضِ. 2.""حُمَّى الْمُسْتَنْقَعَاتِ"" : الْمَلاَرِيَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4750, 'مُسْتَنْكَرٌ', 'مستنكر', 'اسم مفعول', 'نكر', 'مستنكر', 'مستنكر', 'مفع. مِن اِسْتَنْكَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَنْكَرٌ-مُسْتَنْكَرٌ، ةٌ [ن ك ر] (مفع. مِن اِسْتَنْكَرَ). "" عَمَلٌ مُسْتَنْكَرٌ"" : مُسْتَقْبَحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4751, 'مُسْتَهْجَنٌ', 'مستهجن', 'اسم مفعول', 'هجن', 'مستهجن', 'مستهجن', 'مفع. مِن اِسْتَهْجَنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَهْجَنٌ-مُسْتَهْجَنٌ، ةٌ [هـ ج ن] (مفع. مِن اِسْتَهْجَنَ). 1.""كَلاَمٌ مُسْتَهْجَنٌ"" : مَعِيبٌ. 2.""عِبَارَةٌ مُسْتَهْجَنَةٌ"" : مُسْتَقْبَحَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4752, 'مُسْتَهَلٌّ', 'مستهل', 'اسم مفعول', 'هلل', 'مستهل', 'مستهل', 'مفع. من اِسْتَهَلَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَهَلٌّ-مُسْتَهَلٌّ [هـ ل ل] (مفع. من اِسْتَهَلَّ). 1.""مُسْتَهَلُّ العَمَلِ"" : بِدَايَتُهُ. 2.""مُسْتَهَلُّ القَصِيدَةِ"" : مَطْلَعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4753, 'مُسْتَهْلَكٌ', 'مستهلك', 'اسم مفعول', 'هلك', 'مستهلك', 'مستهلك', 'مفع. من اِسْتَهْلَكَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَهْلَكٌ-مُسْتَهْلَكٌ، ةٌ [هـ ل ك] (مفع. من اِسْتَهْلَكَ). ""الزَّيْتُ مَادَّةٌ مُسْتَهْلَكَةٌ فِي الْمَطْبَخِ العَرَبِيِّ"" : مُسْتَعْمَلَةٌ بِكَثْرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4754, 'مُسْتَوْدَعٌ', 'مستودع', 'اسم مفعول', 'ودع', 'مستودع', 'مستدع', 'مفع. مِن اِسْتَوْدَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَوْدَعَ). 1.""مُسْتَوْدَعُ الْمَلاَبِسِ"" : مَكَانُ حِفْظِهَا. 2.""مُسْتَوْدَعُ الْمَحَطَّةِ"" : مَكَانُ وَضْعِ الْحَقَائِبِ فِي الْمَحَطَّةِ لِوَقْتٍ مُعَيَّنٍ. 3.""مُسْتَوْدَعُ البَضَائِعِ"" : مَكَانٌ فَس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4755, 'مُسْتَوْرَدٌ', 'مستورد', 'اسم مفعول', 'ورد', 'مستورد', 'مسترد', 'مفع. مِن اِسْتَوْرَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُسْتَوْرَدٌ-مُسْتَوْرَدٌ، ةٌ [و ر د] (مفع. مِن اِسْتَوْرَدَ). ""ثَوْبٌ مُسْتَوْرَدٌ"" : جِيءَ بِهِ مِنْ بِلاَدٍ أَجْنَبِيَّةٍ. ""بَضَائِعُ مُسْتَوْرَدَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4756, 'مُسْتَوْصَفٌ', 'مستوصف', 'اسم مفعول', 'وصف', 'مستوصف', 'مستصف', 'مفع. مِن اِسْتَوْصَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَوْصَفَ). ""مُسْتَوْصَفُ الْحَيِّ"" : مُسْتَشْفًى صَغِيرٌ لِلاسْتِشَارَاتِ الطِّبِّيَّةِ وَالعِلاَجِ الطَّارِئِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4757, 'مُسْتَوْلَى', 'مستولى', 'اسم مفعول', 'ولي', 'مستولى', 'مستل', 'مفع. مِن اِسْتَوْلَى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"مُسْتَوْلَى-مُسْتَوْلَى [و ل ي] (مفع. مِن اِسْتَوْلَى). ""ثَرْوَةٌ مُسْتَوْلَى عَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4758, 'مُسْتَوْلاة', 'مستولاة', 'اسم مفعول', '', 'مستولاة', 'مستلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْتَوْلَى-مُسْتَوْلَى [و ل ي] (مفع. مِن اِسْتَوْلَى). ""ثَرْوَةٌ مُسْتَوْلَى عَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4759, 'مُسْتَوى', 'مستوى', 'اسم مفعول', 'سوي', 'مستوى', 'مست', 'مفع. مِن اِسْتَوَى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَوَى). 1.""مُسْتَوَى الْمَعِيشَةِ"" : دَرَجَةُ... ""مُسْتَوَى مَعِيشَةِ القَرَوِيِّ أَقَلُّ مِنْ مُسْتَوَى الْحَضَرِيِّ"" ""هُوَ فِي مُسْتَوَاهُ"". 2.""مُسْتَوَاهُ الثَّقَافِيُّ جَيِّدٌ"" : مَرْتَبَتُهُ، مِعْيَارُهُ. ""الْمُسْتَوَى الفِكْرِيُّ"". 3.""كَانَ فِي مُسْتَوَى الْمَسْؤُو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4760, 'مُسْتَواة', 'مستواة', 'اسم مفعول', '', 'مستواة', 'مستة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِسْتَوَى). 1.""مُسْتَوَى الْمَعِيشَةِ"" : دَرَجَةُ... ""مُسْتَوَى مَعِيشَةِ القَرَوِيِّ أَقَلُّ مِنْ مُسْتَوَى الْحَضَرِيِّ"" ""هُوَ فِي مُسْتَوَاهُ"". 2.""مُسْتَوَاهُ الثَّقَافِيُّ جَيِّدٌ"" : مَرْتَبَتُهُ، مِعْيَارُهُ. ""الْمُسْتَوَى الفِكْرِيُّ"". 3.""كَانَ فِي مُسْتَوَى الْمَسْؤُو"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4761, 'مُسْدَلٌ', 'مسدل', 'اسم مفعول', 'سدل', 'مسدل', 'مسدل', 'مفع. مِن أَسْدَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسْدَلٌ-مُسْدَلٌ [س د ل] (مفع. مِن أَسْدَلَ). 1.""سِتَارٌ مُسْدَلٌ"" : مُرْخىً. 2.""شَعْرٌ مُسْدَلٌ عَلَى كَتِفَيْهَا"" : مُسَرَّحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4762, 'مَسْعُودٌ', 'مسعود', 'اسم مفعول', 'سعد', 'مسعود', 'مسعد', 'مفع. مِن أَسْعَدَ وَسَعَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَسْعُودٌ-مَسْعُودٌ [س ع د] (مفع. مِن أَسْعَدَ وَسَعَدَ). ""رَائِدٌ مَسْعُودٌ"": مُوَفَّقٌ، مَحْظُوظٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4763, 'مُسْعَفٌ', 'مسعف', 'اسم مفعول', 'سعف', 'مسعف', 'مسعف', 'مفع. مِن أَسْعَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُسْعَفٌ-مُسْعَفٌ [س ع ف] (مفع. مِن أَسْعَفَ). ""مَرِيضٌ مُسْعَفٌ"" : أَيْ تَمَّ إِسْعَافُهُ وَمُسَاعَدَتُهُ، إِغَاثَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4764, 'مُسْهَبٌ', 'مسهب', 'اسم مفعول', 'سهب', 'مسهب', 'مسهب', 'مفع. مِن أسْهَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن أسْهَبَ). 1.""رَجُلٌ مُسْهَبٌ"" : طَوِيلُ القَدِّ. 2.""ألْقَى خُطْبَةً مُسْهَبَةً"" : خُطْبَةً طَوِيلَةً مُفَصَّلَةً. ""قِصَّةٌ مُسْهَبَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4765, 'مُشْبَعٌ', 'مشبع', 'اسم مفعول', 'شبع', 'مشبع', 'مشبع', 'مفع. مِن أَشْبَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُشْبَعٌ-مُشْبَعٌ [ش ب ع] (مفع. مِن أَشْبَعَ) ""شَرَابٌ مُشْبَعٌ بِالسُّكَّرِ"" : أَيْ فِيهِ سُكَّرٌ زَائِدٌ مِمَّا لاَ يَقْبَلُ زِيَادَةً. ""مَضَتِ النُّفُوسُ تَسْتَشْعِرُ حَيَوِيَّةً مُشْبَعَةً بِالأَرْيَحِيَّةِ"". (ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4766, 'مُشْتَبَهٌ', 'مشتبه', 'اسم مفعول', 'شبه', 'مشتبه', 'مشتبه', 'مفع. مِن اِشْتَبَهَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِشْتَبَهَ). 1.""رَجُلٌ مُشْتَبَهٌ فِي سُلُوكِهِ"" : يُشْتَبَهُ فِيهِ، الْمَشْكُوكُ فِيهِ، مَشْبُوهٌ. 2. ""طريقٌ مُشْتَبَهُ الأعْلامِ"" : لَيْسَ فيه عَلامَةٌ تُوجِّهُ السّائِرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4767, 'مُشْتَرَكٌ', 'مشترك', 'اسم مفعول', 'شرك', 'مشترك', 'مشترك', 'مفع. مِن اِشْتَرَكَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُشْتَرَكٌ-مُشْتَرَكٌ، ةٌ [ش ر ك] (مفع. مِن اِشْتَرَكَ). 1.""عَمَلٌ مُشْتَرَكٌ"" : عَمَلٌ يَشْتَرِكُ فِيهِ اثْنَانِ أَوْ أَكْثَرُ. 2. ""صَدِيقٌ مُشْتَرَكٌ"" : صَدِيقٌ لِعَدَدٍ مِنَ الأَصْدِقَاءِ. ""الْمَصْلَحَةُ الْمُشْتَرَكَةُ"". 3.""صَدَرَ بَلاَغٌ مُشْتَرَكٌ عَنِ الاجْتِمَاعِ"" : بَلاَغٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4768, 'مُشْتَقٌّ', 'مشتق', 'اسم مفعول', 'شقق', 'مشتق', 'مشتق', 'مفع. مِن اِشْتَقَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِشْتَقَّ). ""لَفْظٌ مُشْتَقٌّ"" : مَأْخُوذٌ مِنْ لَفْظٍ آخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4769, 'مُشْتَكًى', 'مشتكى', 'اسم مفعول', 'شكو', 'مشتكى', 'مشتك', 'مفع. مِن اِشْتَكَى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"مُشْتَكَى-مُشْتَكَى [ش ك و] (مفع. مِن اِشْتَكَى). ""الْمُشْتَكَى"": الْمُدَّعَى عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4770, 'مُشْتَكاة', 'مشتكاة', 'اسم مفعول', '', 'مشتكاة', 'مشتكة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشْتَكَى-مُشْتَكَى [ش ك و] (مفع. مِن اِشْتَكَى). ""الْمُشْتَكَى"": الْمُدَّعَى عَلَيْهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4771, 'مُشْتَهًى', 'مشتهى', 'اسم مفعول', 'شهي', 'مشتهى', 'مشته', 'مفع. مِن اِشْتَهَى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"مُشْتَهَى-مُشْتَهَى [ش هـ ي] (مفع. مِن اِشْتَهَى) ""كَانَ فِي الْحَفْلِ كُلُّ مُشْتَهَى"" : كُلُّ مَا يُشْتَهَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4772, 'مُشْتَهاة', 'مشتهاة', 'اسم مفعول', '', 'مشتهاة', 'مشتهة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشْتَهَى-مُشْتَهَى [ش هـ ي] (مفع. مِن اِشْتَهَى) ""كَانَ فِي الْحَفْلِ كُلُّ مُشْتَهَى"" : كُلُّ مَا يُشْتَهَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4773, 'مُصَابٌ', 'مصاب', 'اسم مفعول', 'صوب', 'مصاب', 'مصب', 'مفع. من أصابَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من أصابَ). 1."" مُصَابٌ بِمَرَضٍ عُضَالٍ"" : مَنْ أَصَابَهُ مَرَضٌ. ""عُضْوُهُ الأيْسَرُ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4774, 'مُصْطَفىً', 'مصطفى', 'اسم مفعول', 'صفو', 'مصطفى', 'مصطف', 'مفع. مِن اِصْطَفَى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِصْطَفَى). 1. ""عَمَلٌ مُصْطَفـىً"" : مُخْتارٌ. 2.""الْمُصْطَفَى"" : لَقَبُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4775, 'مُصْطَفاة', 'مصطفاة', 'اسم مفعول', '', 'مصطفاة', 'مصطفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِصْطَفَى). 1. ""عَمَلٌ مُصْطَفـىً"" : مُخْتارٌ. 2.""الْمُصْطَفَى"" : لَقَبُ ا"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4776, 'مُصْطَلَحٌ', 'مصطلح', 'اسم مفعول', 'صلح', 'مصطلح', 'مصطلح', 'مفع. مِنِ اِصْطَلَحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنِ اِصْطَلَحَ). 1. إِجْرَاءٌ مُصْطَلَحٌ عَلَيْهِ "": مُتَّفَقٌ عَلَيْهِ. 2. ""الْمُصْطَلَحُ فِي العُلُومِ"" : كُلُّ كَلِمَةٍ لَهَا دَلاَلَةٌ مُعَيَّنَةٌ، مُتَّفَقٌ عَلَيْهَا "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4777, 'مُضْطَرٌّ', 'مضطر', 'اسم مفعول', 'ضرر', 'مضطر', 'مضطر', 'مفع. مِن اِضْطَرَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِضْطَرَّ). ""مُضْطَرٌّ لِلسَّفَرِ لَيْلاً"" : مُكْرَهٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4778, 'مُضْطَهَدٌ', 'مضطهد', 'اسم مفعول', 'ضهد', 'مضطهد', 'مضطهد', 'مفع. مِن اِضْطَهَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن اِضْطَهَدَ). ""رَجُلٌ مُضْطَهَدٌ"" : أَيْ مُعَرَّضٌ لِلظُّلْمِ وَالقَهْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4779, 'مُضْمَرٌ', 'مضمر', 'اسم مفعول', 'ضمر', 'مضمر', 'مضمر', 'مفع. مِن أَضْمَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُضْمَرٌ-مُضْمَرٌ، ةٌ [ض م ر] (مفع. مِن أَضْمَرَ). ""فِي نَفْسِهِ شَيْءٌ مُضْمَرٌ"" : مَخْفِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4780, 'مُضْنىً', 'مضنى', 'اسم مفعول', 'ضني', 'مضنى', 'مضن', 'مفع. من أَضْنَى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"مُضْنـىً-مُضْنـىً [ض ن ي] (مفع. من أَضْنَى). ""وَجَدَهُ مُضْنىً"": مُرْهَقاً، مُتْعَباً، رَازِحاً تَحْتَ عِبْءٍ. ""مُضْنَاكَ جَفَاهُ مَرْقَدُهُ"". (أحمد شوقي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4781, 'مُضْناة', 'مضناة', 'اسم مفعول', '', 'مضناة', 'مضنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُضْنـىً-مُضْنـىً [ض ن ي] (مفع. من أَضْنَى). ""وَجَدَهُ مُضْنىً"": مُرْهَقاً، مُتْعَباً، رَازِحاً تَحْتَ عِبْءٍ. ""مُضْنَاكَ جَفَاهُ مَرْقَدُهُ"". (أحمد شوقي)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4782, 'مُطْفَأٌ', 'مطفأ', 'اسم مفعول', 'طفأ', 'مطفء', 'مطف', 'مفع. مِن أَطْفَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُطْفَأٌ-مُطْفَأٌ، ةٌ [ط ف أ] (مفع. مِن أَطْفَأَ). 1.""جَمْرٌ مُطْفَأٌ"": هَامِدٌ. 2.""ضَوْءٌ مُطْفَأٌ"" : غَيْرُ مُشْتَعِلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4783, 'مُطْفَأَةٌ', 'مطفأة', 'اسم مفعول', '', 'مطفءة', 'مطفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُطْفَأٌ-مُطْفَأٌ، ةٌ [ط ف أ] (مفع. مِن أَطْفَأَ). 1.""جَمْرٌ مُطْفَأٌ"": هَامِدٌ. 2.""ضَوْءٌ مُطْفَأٌ"" : غَيْرُ مُشْتَعِلٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4784, 'مُطْلَقٌ', 'مطلق', 'اسم مفعول', 'طلق', 'مطلق', 'مطلق', 'مفع. من أَطْلَقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُطْلَقٌ، ةٌ - [ط ل ق]. (مفع. من أَطْلَقَ). 1.""حُكْمٌ مُطْلَقٌ"" : عَامٌّ. 2.""بِلاَدٌ تَخْضَعُ لِلْحُكْمِ الْمُطْلَقِ"" : بِلاَدٌ لاَ دِيمُقْرَاطِيَّةَ فِيهَا تَخْضَعُ لِحُكْمِ فَرْدٍ وَاحِدٍ.   ""لَهُ سُلْطَةٌ مُطْلَقَةٌ"" ""لَهُ مُطْلَقُ الصَّلاحِيَّةِ"". 3.""قَاعِدَةٌ مُطْلَقَةٌ"" : قَاعِدَةٌ لاَ اسْتِثْنَاءَ فِيهَا. ""أَحْكَامٌ مُطْلَقَةٌ"". 4.""مَاءٌ مُطْلَقٌ"" : لاَ تُخَالِطُهُ نَجَاسَةٌ وَيُحَافِظٌ عَلَى نَقَائِهِ. 5.""أَمْرٌ لَمْ يَحْدُثْ مُطْلَقاً"" : لَمْ يَحْدُثْ قَطُّ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4785, 'مُعَارٌ', 'معار', 'اسم مفعول', 'عور', 'معار', 'معر', 'مفع. مِن أَعَارَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُعَارٌ-مُعَارٌ [ع و ر] (مفع. مِن أَعَارَ). ""فُسْتَانٌ مُعَارٌ"" : مَأْخُوذٌ إِعَارَةً. ""كِتَابٌ مُعَارٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4786, 'مُعَاقٌ', 'معاق', 'اسم مفعول', 'عوق', 'معاق', 'معق', 'مفع. مِن أَعَاقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن أَعَاقَ). ""وَلَدٌ مُعَاقٌ"" : بِهِ عَاهَةٌ تَعُوقُهُ عَنِ التَّكَيُّفِ مَعَ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4787, 'مُعْتَبَرٌ', 'معتبر', 'اسم مفعول', 'عبر', 'معتبر', 'معتبر', 'مفع. مِن اِعْتَبَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِعْتَبَرَ). ""عَمَلٌ مُعْتَبَرٌ"" : لَهُ قِيمَةٌ وَاعْتِبَارٌ. ""رَجُلٌ مُعْتَبَرٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4788, 'مُعْتَرَفٌ', 'معترف', 'اسم مفعول', 'عرف', 'معترف', 'معترف', 'مفع. مِن اِعْتَرَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِعْتَرَفَ). ""مُعْتَرَفٌ بِهِ"" : أَيْ مَنِ اعْتُرِفَ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4789, 'مُعْتَرَكٌ', 'معترك', 'اسم مفعول', 'عرك', 'معترك', 'معترك', 'مفع. مِن اِعْتَرَكَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن اِعْتَرَكَ). 1.""يُصَارِعُ فِي مُعْتَرَكِ الْحَيَاةِ"" : فِي خِضَمِّهَا. 2.""دَخَلَ الْمُحَارِبُونَ الْمُعْتَرَكَ"" : مَوْضِعَ القِتَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4790, 'مُعْتَصَمٌ', 'معتصم', 'اسم مفعول', 'عصم', 'معتصم', 'معتصم', 'مفع. مِن اِعْتَصَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعْتَصَمٌ-مُعْتَصَمٌ [ع ص م] (مفع. مِن اِعْتَصَمَ). ""اِلْتَجَأَ إِلَى مُعْتَصَمٍ آمِنٍ"" : مَلْجَأ، مَخْبَأ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4791, 'مُعْتَقٌ', 'معتق', 'اسم مفعول', 'عتق', 'معتق', 'معتق', 'مفع. مِن أَعْتَقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن أَعْتَقَ). ""عَبْدٌ مُعْتَقٌ"" : مُحَرَّرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4792, 'مُعْتَقَدٌ', 'معتقد', 'اسم مفعول', 'عقد', 'معتقد', 'معتقد', 'مفع. مِن اِعْتَقَدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِعْتَقَدَ). ""هَذَا تَصَوُّرُهُ حَسَبَ مُعْتَقَدِهِ"" : مَا يَعْتَقِدُهُ الإِنْسَانُ وَيُؤْمِنُ بِهِ بِحَيْثُ لاَ يَقْبَلُ فِيهِ الشَّكَّ. ""لِكُلِّ أُمَّةٍ مُعْتَقَدَاتُهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4793, 'مُعْتَقَلٌ', 'معتقل', 'اسم مفعول', 'عقل', 'معتقل', 'معتقل', 'مفع. مِن اِعْتَقَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن اِعْتَقَلَ). ""أَخْبَرُوهُ أَنَّ ابْنَهُ مُعْتَقَلٌ"" : أَيْ تَمَّ اعْتِقالهُ، حَبْسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4794, 'مُعْتَلٌّ', 'معتل', 'اسم مفعول', 'علل', 'معتل', 'معتل', 'مفع. مِن اِعْتَلَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن اِعْتَلَّ). 1.""مُعْتَلَّ الصِّحَّةِ"" : مَرِيضٌ، أَيْ مَنْ بِهِ عِلَّةٌ. 2.""فِعْلٌ مُعْتَلٌّ"": أَحَدُ حُرُوفِهِ مِنْ حُرُوفِ العِلَّةِ، أَيْ الأَلِفُ، الوَاوُ، اليَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4795, 'مُعْتَمَدٌ', 'معتمد', 'اسم مفعول', 'عمد', 'معتمد', 'معتمد', 'مفع. مِن اِعْتَمَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن اِعْتَمَدَ). 1.""رَجُلٌ مُعْتَمَدٌ"" : أَيْ يُعْتَمَدُ عَلَيْهِ، يُتَّكَأُ عَلَيْهِ. 2.""مُعْتَمَدُ بِلاَدِهِ"" : وَكِيلُهَا، مُمَثِّلُهَا. ""مُعْتَمَدٌ عَسْكَرِيٌّ"" ""مُعْتَمَدٌ سِيَاسِيٌّ"". 3.""وَثِيقَةٌ مُعْتَمَدَةٌ"" : أَيْ مُوَثَّقَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4796, 'مُعْجَبٌ', 'معجب', 'اسم مفعول', 'عجب', 'معجب', 'معجب', 'مفع. مِن أَعْجَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن أَعْجَبَ). ""مُعْجَبٌ بِنَفْسِهِ"" : مَزْهُو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4797, 'مُعَدٌّ', 'معد', 'اسم مفعول', 'عدد', 'معد', 'معد', 'مفع. من أَعَدَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُعَدٌّ-مُعَدٌّ، ةٌ [ع د د] (مفع. من أَعَدَّ). ""ثَوْبٌ مُعَدٌّ لِلْخِيَاطَةِ"" : جَاهِزٌ، مُهَيَّأٌ. ""كُلُّ شَيْءٍ مُعَدٌّ عَلَى أَحْسَنِ وَجْهٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4798, 'مُعْطىً', 'معطى', 'اسم مفعول', 'عطي', 'معطى', 'معط', 'مفع. مِن أَعْطَى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن أَعْطَى). ""جَاءَ بِمُعْطـىً جَدِيدٍ"" : بِمُسَلَّمَةٍ لِيَتَوَصَّلَ بِهَا إِلَى مَعْرِفَةِ قَضِيَّةٍ مَجْهُولَةٍ. ""طَرَحَ مُعْطَيَاتٍ لِلتَّفْكِيرِ فِيهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4799, 'مُعْطاة', 'معطاة', 'اسم مفعول', '', 'معطاة', 'معطة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن أَعْطَى). ""جَاءَ بِمُعْطـىً جَدِيدٍ"" : بِمُسَلَّمَةٍ لِيَتَوَصَّلَ بِهَا إِلَى مَعْرِفَةِ قَضِيَّةٍ مَجْهُولَةٍ. ""طَرَحَ مُعْطَيَاتٍ لِلتَّفْكِيرِ فِيهَا""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4800, 'مُعْفىً', 'معفى', 'اسم مفعول', 'عفو', 'معفى', 'معف', 'مفع. مِن أَعْفَى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن أَعْفَى). ""مُعْفـىً مِنَ الضَّرَائِبِ"" : مُسْتَثْنىً مِنْ أَدَائِهَا. ""بَضَائِعُ مُعْفَاةٌ مِنَ الرُّسُومِ الجُمْرُكِيَّةِ"" ""مُعْفـىً مِنَ الخِدْمَةِ العَسْكَرِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4801, 'مُعْفاة', 'معفاة', 'اسم مفعول', '', 'معفاة', 'معفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن أَعْفَى). ""مُعْفـىً مِنَ الضَّرَائِبِ"" : مُسْتَثْنىً مِنْ أَدَائِهَا. ""بَضَائِعُ مُعْفَاةٌ مِنَ الرُّسُومِ الجُمْرُكِيَّةِ"" ""مُعْفـىً مِنَ الخِدْمَةِ العَسْكَرِيَّةِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4802, 'مُعْلَنٌ', 'معلن', 'اسم مفعول', 'علن', 'معلن', 'معلن', 'مفع. مِن أَعْلَنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعْلَنٌ-مُعْلَنٌ، ةٌ [ع ل ن] (مفع. مِن أَعْلَنَ). 1.""خَبَرٌ مُعْلَنٌ"": خَبَرٌ مُذَاعٌ. 2.""حُكْمٌ مُعْلَنٌ"" : حُكْمٌ مُصَرَّحٌ بِهِ. 3.""حَرْبٌ مُعْلَنَةٌ"" : مَكْشُوفَةٌ لِلْعَامِّ والخَاصِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4803, 'مُغْتَالٌ', 'مغتال', 'اسم مفعول', 'غيل', 'مغتال', 'مغتل', 'مفع. مِن اِغْتَالَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِغْتَالَ). ""وَجَدُوهُ مُغْتَالاً فِي غُرْفَتِهِ"" : أَيْ وَقَعَ قَتْلُهُ عَلَى حِينِ غَفْلَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4804, 'مُغْتَصَبٌ', 'مغتصب', 'اسم مفعول', 'غصب', 'مغتصب', 'مغتصب', 'مفع. مِن اِغْتَصَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"( مفع. مِن اِغْتَصَبَ). 1. ""مَالٌ مُغْتَصَبٌ"" : مَالٌ أُخِذَ قَهْراً وغَصْباً. 2.""اِمْرَأَةٌ مُغْتَصَبَةٌ"" : اِمْرَأَةٌ اُعْتُدِيَ عَلَيْهَا جِنْسِيّاً عَلَى الرَّغْمِ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4805, 'مُغْرَمٌ', 'مغرم', 'اسم مفعول', 'غرم', 'مغرم', 'مغرم', 'مفع. مِن أَغْرَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن أَغْرَمَ). 1. ""مُغْرَمٌ بِلُعْبَةِ الشِّطْرَنْجِ"" : مُولَعٌ بِهَا. ""فَتَاةٌ مُغْرَمَةٌ بِالأَزْهَارِ"". 2. ""مُغْرَمٌ بِهَا"" : عَاشِقٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4806, 'مُغْفَلٌ', 'مغفل', 'اسم مفعول', 'غفل', 'مغفل', 'مغفل', 'مفع. مِن أَغْفَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن أَغْفَلَ). 1. ""رَجُلٌ مُغْفَلٌ"" : رَجُلٌ مَجْهُولُ الاسْمِ. 2. ""شَرِكَةٌ مُغْفَلَةٌ"" : شَرِكَةٌ مَجْهُولَةُ الاسْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4807, 'مُغْلَقٌ', 'مغلق', 'اسم مفعول', 'غلق', 'مغلق', 'مغلق', 'مفع. مِن أَغْلَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مُغْلَقٌ-مُغْلَقٌ [غ ل ق] (مفع. مِن أَغْلَقَ). 1. ""بَابٌ مُغْلَقٌ"" : مَسْدُودٌ. ""أَبْوَابٌ مُغ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4808, 'مُغْمَدٌ', 'مغمد', 'اسم مفعول', 'غمد', 'مغمد', 'مغمد', 'مفع. مِن أَغْمَدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مُغْمَدٌ-مُغْمَدٌ [غ م د] (مفع. مِن أَغْمَدَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4809, 'مُغْمىً', 'مغمى', 'اسم مفعول', 'غمي', 'مغمى', 'مغم', 'مفع. مِن أُغْمِيَ', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن أُغْمِيَ). ""سَقَطَ مُغْمىً عَلَيْهِ"" : سَقَطَ فَاقِداً لِلحَرَكَةِ والحِسِّ، مَغْشِيّاً عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4810, 'مُغْماة', 'مغماة', 'اسم مفعول', '', 'مغماة', 'مغمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"(مفع. مِن أُغْمِيَ). ""سَقَطَ مُغْمىً عَلَيْهِ"" : سَقَطَ فَاقِداً لِلحَرَكَةِ والحِسِّ، مَغْشِيّاً عَلَيْهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4811, 'مُفْتَرَضٌ', 'مفترض', 'اسم مفعول', 'فرض', 'مفترض', 'مفترض', 'مفع. مِن اِفْتَرَضَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مُفْتَرَضٌ-مُفْتَرَضٌ، ةٌ [ف ر ض] (مفع. مِن اِفْتَرَضَ) ""مِنَ الْمُفْتَرَضِ أَنْ يَحْضُرَ الآنَ"" : مِنَ الْمُسَلَّمِ بِهِ ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4812, 'مُفْتَرَقٌ', 'مفترق', 'اسم مفعول', 'فرق', 'مفترق', 'مفترق', 'مفع. مِن اِفْتَرَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مُفْتَرَقٌ-مُفْتَرَقٌ [ف ر ق] (مفع. مِن اِفْتَرَقَ). 1.""عِنْدَ مُفْتَرَقِ الطُّرُقِ"" : عِنْدَ مَفْرَقِهَا، مُنْعَطَفِهَا. 2.""اِنْتَهَتِ الأَزْمَةُ إِلَى مُفْتَرَقِ الطُّرُقِ"" : إِلَى مَوْقِفٍ مُتَشَعِّبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4813, 'مُفْتَعَلٌ', 'مفتعل', 'اسم مفعول', 'فعل', 'مفتعل', 'مفتعل', 'مفع. مِن اِفْتَعَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مُفْتَعَلٌ-مُفْتَعَلٌ، ةٌ [ف ع ل] (مفع. مِن اِفْتَعَلَ). 1.""صِرَاعٌ مُفْتَعَلٌ"" : مُصْطَنَعٌ. 2.""شِعْرٌ مُفْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4814, 'مُفْحَمٌ', 'مفحم', 'اسم مفعول', 'فحم', 'مفحم', 'مفحم', 'مفع. مِن أَفْحَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُفْحَمٌ، ةٌ - ج: ـون، ـات. [ف ح م]. (مفع. مِن أَفْحَمَ). ""وَجَدَ نَفْسَهُ مُفْحَماً بِالأَدِلَّةِ"" : عَاجِزاً عَنِ الرَّدِّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4815, 'مُفْرَدٌ', 'مفرد', 'اسم مفعول', 'فرد', 'مفرد', 'مفرد', 'مفع. مِن أَفْرَدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"(مفع. مِن أَفْرَدَ). 1.""اِسْمٌ مُفْرَدٌ"" : وَاحِدٌ. ""وَلَدٌ مُفْرَدُ أَوْلاَدٍ"". 2.""خَرَجَ بِمُفْرَدِهِ"" : خَرَجَ وَحْدَهُ، عَلَى حِدَةٍ. 3.""الأَرْقَامُ الْمُفْرَدَةُ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4816, 'مُفْرَغٌ', 'مفرغ', 'اسم مفعول', 'فرغ', 'مفرغ', 'مفرغ', 'مفع. من أَفْرَغَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مُفْرَغٌ-مُفْرَغٌ، ةٌ [ف ر غ] (مفع. من أَفْرَغَ). 1. ""دِرْهَمٌ مُفْرَغٌ"": الدِّرْهَمُ الْمَصْبُوبُ فِي قَالَبٍ غَيْرِ مَضْرُوبٍ. 2. ""يَدُورُ فِي حَلْقَةٍ مُفْرَغَةٍ"" : الْحَلْقَةُ الفَارِغَةُ مِنْ جَوْفِهَا الْمَقْطُوعَةُ الأَطْرَافِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4817, 'مُفْعَمٌ', 'مفعم', 'اسم مفعول', 'فعم', 'مفعم', 'مفعم', 'مفع. من أَفْعَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من أَفْعَمَ). ""مُفْعَمٌ بِالنَّشَاطِ والْحَيَوِيَّةِ"" : مُمْتَلِئٌ. ""أَجَابَ بِلَهْفَةٍ فَاتِرَةٍ ولَكِنَّهَا مُفْعَمَةٌ بِالتَّهَكُّمِ والتَّأْنِيبِ"". (ع. م. العقاد)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4818, 'مُقْتَبَسٌ', 'مقتبس', 'اسم مفعول', 'قبس', 'مقتبس', 'مقتبس', 'مفع. من اِقْتَبَسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقْتَبَسٌ-مُقْتَبَسٌ، ةٌ [ق ب س] (مفع. من اِقْتَبَسَ). 1. ""مُقْتَبَسُ النَّارِ"" : الجَمْرُ مِنْهَا. 2. ""عَمَلٌ مُقْتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4819, 'مُقْتَحَمٌ', 'مقتحم', 'اسم مفعول', 'قحم', 'مقتحم', 'مقتحم', 'مفع. من اِقْتَحَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقْتَحَمٌ-مُقْتَحَمٌ، ةٌ [ق ح م] (مفع. من اِقْتَحَمَ). ""مَنْزِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4820, 'مُقْتَرَحٌ', 'مقترح', 'اسم مفعول', 'قرح', 'مقترح', 'مقترح', 'مفع. من اِقْتَرَحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من اِقْتَرَحَ). ""تَقَدَّمَ بِمُقْتَرَحٍ جَدِيدٍ"" : بِفِكْرَةٍ تَتضَمَّنُ شَيْئاً جَدِيداً. "" لَمْ يَنَلِ الْمُقْتَرَحُ الْمُقَدَّمُ رِضَى الجَمِيعِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4821, 'مُقْتَرَضٌ', 'مقترض', 'اسم مفعول', 'قرض', 'مقترض', 'مقترض', 'مفع. من اِقْتَرَضَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقْتَرَضٌ-مُقْتَرَضٌ، ةٌ [ق ر ض] (مفع. من اِقْتَرَضَ). ""الْمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4822, 'مُقْتَضَبٌ', 'مقتضب', 'اسم مفعول', 'قضب', 'مقتضب', 'مقتضب', 'مفع. من اِقْتَضَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقْتَضَبٌ-مُقْتَضَبٌ، ةٌ [ق ض ب] (مفع. من اِقْتَضَبَ). 1.""كَلاَمٌ مُقْتَضَبٌ"" : مُوجَزٌ، مُخْتَصَرٌ. 2. ""الْبَح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4823, 'مُقْتَضىً', 'مقتضى', 'اسم مفعول', 'قضي', 'مقتضى', 'مقتض', 'مفع. من اِقْتَضَى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"(مفع. من اِقْتَضَى). ""مُقْتَضَيَاتُ العَمَلِ"" : مُتَطَلَّبَاتُهُ. ""لِكُلِّ حِرْفَةٍ مُقْتَضَيَاتُهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4824, 'مُقْتَضاة', 'مقتضاة', 'اسم مفعول', '', 'مقتضاة', 'مقتضة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من اِقْتَضَى). ""مُقْتَضَيَاتُ العَمَلِ"" : مُتَطَلَّبَاتُهُ. ""لِكُلِّ حِرْفَةٍ مُقْتَضَيَاتُهَا""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4825, 'مُقْتَطَعٌ', 'مقتطع', 'اسم مفعول', 'قطع', 'مقتطع', 'مقتطع', 'مفع. من اِقْتَطَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقْتَطَعٌ-مُقْتَطَعٌ، ةٌ [ق ط ع] (مفع. من اِقْتَطَعَ). ""حَجَرٌ مُقْتَطَعٌ مِنَ الجَبَلِ"" : مَفْصُولٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4826, 'مُقْتَطَفٌ', 'مقتطف', 'اسم مفعول', 'قطف', 'مقتطف', 'مقتطف', 'مفع. من اِقْتَطَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقْتَطَفٌ-مُقْتَطَفٌ، ةٌ [ق ط ف] (مفع. من اِقْتَطَفَ). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4827, 'مُقْتَلَعٌ', 'مقتلع', 'اسم مفعول', 'قلع', 'مقتلع', 'مقتلع', 'مفع. من اِقْتَلَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من اِقْتَلَعَ). ""مُقْتَلَعٌ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4828, 'مُقْعَدٌ', 'مقعد', 'اسم مفعول', 'قعد', 'مقعد', 'مقعد', 'مفع. مِن أَقْعَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن أَقْعَدَ). ""رَجُلٌ مُقْعَدٌ"" : مُصَابٌ بِدَاءِ القُعَادِ يَمْنَعُهُ مِنَ الْمَشْيِ، أَعْرَجُ، مَشْلُولٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4829, 'مُقْفَلٌ', 'مقفل', 'اسم مفعول', 'قفل', 'مقفل', 'مقفل', 'مفع. من أَقْفَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من أَقْفَلَ). 1. ""بَابٌ مُقْفَلٌ"" : مَسْدُودٌ، مُغْلَقٌ بِقُفْلٍ. ""وَجَدُوا الدَّكَاكِينَ مُقْفَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4830, 'مُكْتَسَبٌ', 'مكتسب', 'اسم مفعول', 'كسب', 'مكتسب', 'مكتسب', 'مفع. من اِكْتَسَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من اِكْتَسَبَ). 1. ""حَقٌّ مُكْتَسَبٌ"" : حَقٌّ تَمَّ تَحْصِيلُهُ عَنْ طَرِيقِ العَمَلِ. ""حُقُوقٌ مُكْتَس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4831, 'مُكْتَسَحٌ', 'مكتسح', 'اسم مفعول', 'كسح', 'مكتسح', 'مكتسح', 'مفع. من اِكْتَسَحَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُكْتَسَحٌ-مُكْتَسَحٌ، ةٌ [ك س ح] (مفع. من اِكْتَسَحَ). ""حَقْلٌ مُكْتَسَحٌ بِالْجَرَادِ"" : مُجْتَاحٌ، مُتْلَفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4832, 'مُكْتَظٌّ', 'مكتظ', 'اسم مفعول', 'كظظ', 'مكتظ', 'مكتظ', 'مفع. من اِكْتَظَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُكْتَظٌّ-مُكْتَظٌّ، ةٌ [ك ظ ظ] (مفع. من اِكْتَظَّ). ""شَارِعٌ مُكْتَظٌّ بِالسُّكَّانِ"" : مُمْتَلِئٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4833, 'مُكْتَنَفٌ', 'مكتنف', 'اسم مفعول', 'كنف', 'مكتنف', 'مكتنف', 'مفع. من اِكْتَنَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من اِكْتَنَفَ). 1. ""وَلَدٌ مُكْتَنَفٌ بِكُلِّ رِعَايَةٍ"" : مُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4834, 'مُؤَكَّدٌ', 'مؤكد', 'اسم مفعول', 'أكد', 'مءكد', 'مكد', 'مفع. مِنْ أَكَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُؤَكَّدٌ-مُؤَكَّدٌ، ةٌ [أ ك د] (مفع. مِنْ أَكَّدَ). ""خَبَرٌ مُؤَكَّدٌ"" : مَوْثُوقٌ بِهِ. ""أَعْطَوْا أَبَاهُمُ الْمَوَاثِيقَ الْمُؤَكَّدَةَ"". (الجاحظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4835, 'مُكْرَهٌ', 'مكره', 'اسم مفعول', 'كره', 'مكره', 'مكره', 'مفع. من أَكْرَهَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من أَكْرَهَ). 1. ""تَنَازَلَ عَنْ حَقِّهِ مُكْرَهاً لاَ رَاضِياً. 2. ""مُكْرَهٌ أَخُوكَ لاَ بَطَلٌ""(مثل) : أَيْ مَنْ يُجْبَرُ عَلَى القِيَامِ بِعَمَلٍ ولَيْسَ أَهْلاً لَهُ ولاَ شَجَاعَةَ لَهُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4836, 'مَأْكُولٌ', 'مأكول', 'اسم مفعول', 'أكل', 'مءكول', 'مكل', 'مفع. مِنْ أَكَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مَآكِيلُ"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَكَلَ). ""قَدَّمُوا لِلضُّيُوفِ أَنْوَاعاً مِنَ الْمَأْكُولاَتِ والْمَشْرُوبَاتِ"": مَا يُؤْكَلُ، الْمَآكِلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4837, 'مَآكِيلُ', 'مآكيل', 'اسم مفعول', '', 'مءءكيل', 'مآكل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4838, 'مُلْتَاعٌ', 'ملتاع', 'اسم مفعول', 'لوع', 'ملتاع', 'ملتع', 'مفع. من اِلْتَاعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من اِلْتَاعَ). ""قَلْبٌ مُلْتَاعٌ"" : مُحْتَرِقٌ مِنْ شَوْقٍ أَوْ هَمٍّ. ""اِنْدَفَعَتْ فِي بُكَاءٍ حَقِيقِيٍّ، بُكَاءٍ صَادِرٍ عَنِ عَاطِفَةِ الأُمُومَةِ الْمُلْتَاعَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4839, 'مُلْتَفٌّ', 'ملتف', 'اسم مفعول', 'لفف', 'ملتف', 'ملتف', 'مفع. من اِلْتَفَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من اِلْتَفَّ). 1.""جَاءتْ مُلْتَفَّةً فِي مُلاَءتِهَا"" : أَيْ مُشْتَمِلَةً، مُغَطَّاةً... ""شَجَرَةٌ عَظِيمَةٌ مُلْتَفَّةٌ بِالوَرَقِ"". 2.""مُلْتَفٌّ حَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4840, 'مُلْجَمٌ', 'ملجم', 'اسم مفعول', 'لجم', 'ملجم', 'ملجم', 'مفع. من أَلْجَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُلْجَمٌ-مُلْجَمٌ، ةٌ [ل ج م] (مفع. من أَلْجَمَ). ""جَوَادٌ مُلْجَمٌ"" : أَيْ أُلْبِسَ اللِّجَامَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4841, 'مُلْحَقٌ', 'ملحق', 'اسم مفعول', 'لحق', 'ملحق', 'ملحق', 'مفع. من أَلْحَقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَلاَحِقُ"', '', '', '', '', '', '', '', '', '"(مفع. من أَلْحَقَ). 1.""مُلْحَقُ الكِتَابِ"" : مَا يُلْحَقُ بِالكِتَابِ إِضَافَةً أَوْ زِيَادَةً بَعْدَ الفَرَاغِ مِنْهُ، مَعْلُومَاتٌ جَدِيدَةٌ. 2.""مُلْحَقُ الْجَرِيدَةِ"" : صَفَحَاتٌ دَاخِلِيَّةٌ مُضَافَةٌ إِلَى الْجَرِيدَةِ. ""الْمُلْحَقُ الثَّقَافِيُّ لِلْجَرِيدَةِ"" : صَفَحَاتٌ زَائِدَةٌ خَاصَّةٌ بِالثَّقَافَةِ تُضَافُ إِلَى الْجَرِيدَةِ. ""الْمَلاَحِقُ الثَّقَافِيَّةُ"". 3.""مُلْحَقٌ فِي السِّفَارَةِ"" : مُوَظَّفٌ سَامٍ فِي سِفَارَةِ بِلاَدِهِ، مُكَلَّفٌ بِمُهِمَّةٍ. ""الْمُلْحَقُ الثَّقَافِيُّ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4842, 'مَلاَحِقُ', 'ملاحق', 'اسم مفعول', '', 'ملاحق', 'ملحق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4843, 'مُلْزَمٌ', 'ملزم', 'اسم مفعول', 'لزم', 'ملزم', 'ملزم', 'مفع. من أَلْزَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من أَلْزَمَ). 1.""أَمْرٌ مُلْزَمٌ"" : مَفْرُوضٌ. 2.""وَجَد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4844, 'مُلْصَقٌ', 'ملصق', 'اسم مفعول', 'لصق', 'ملصق', 'ملصق', 'مفع. من أَلْصَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من أَلْصَقَ). ""مُلْصَقُ الحَفْلَةِ"" : وَرَقَةٌ مَطْبُوعَةٌ، تَتَضَمَّنُ فِي أَغْلَبِ الأَحْيَانِ رَسْماً أَوْ تَشْكِيلاً يَحْمِلُ خَبَراً أَوْ إِعْلاَماً بِأَمْرٍ مَّا... ""مُلْصَقُ الْحَفْلَةِ الْمُوسِيقِيَّةِ"" ""مُلْصَقُ الْمُؤْتَمَرِ"" ""مُلْصَقُ الْمَعْرِضِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4845, 'مُلْغَزٌ', 'ملغز', 'اسم مفعول', 'لغز', 'ملغز', 'ملغز', 'مفع. من أَلْغَزَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلْغَزٌ-مُلْغَزٌ، ةٌ [ل غ ز] (مفع. من أَلْغَزَ). ""كَلاَمٌ مُلْغَزٌ"" : مُلْتَبِسٌ، مُبْهَمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4846, 'مُلْغىً', 'ملغى', 'اسم مفعول', 'لغي', 'ملغى', 'ملغ', 'مفع. من أَلْغَى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"مُلْغىً-مُلْغىً، ةٌ [ل غ ي] (مفع. من أَلْغَى). 1.""صَوْتٌ مُلْغىً"" : غَيْرٌ مَحْسُوبٍ. 2.""حُكْمٌ مُلْغىً"" : تَمَّ إِبْطَالُهُ، أَيْ مُبْطَلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4847, 'مُلْغاة', 'ملغاة', 'اسم مفعول', '', 'ملغاة', 'ملغة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلْغىً-مُلْغىً، ةٌ [ل غ ي] (مفع. من أَلْغَى). 1.""صَوْتٌ مُلْغىً"" : غَيْرٌ مَحْسُوبٍ. 2.""حُكْمٌ مُلْغىً"" : تَمَّ إِبْطَالُهُ، أَيْ مُبْطَلٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4848, 'مُؤَلَّفٌ', 'مؤلف', 'اسم مفعول', 'ألف', 'مءلف', 'ملف', 'مفع. مِنْ أَلَّفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَلَّفَ). 1.""مُؤَلَّفٌ فِي الأَدَبِ وَاللُّغَةِ"" : كِتَابٌ أُلِّفَ فِي الأَدَبِ وَاللُّغَةِ. ""لَهُ مُؤَلَّفَاتٌ كَثِيرَةٌ"". 2.التوبة آية 60 لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ (قرآن) : أَيِ الَّذِينَ أَسْلَمُوا وَنِيَّتُهُمْ ضَعِيفَةٌ فِيهِ، فَتُسْتَأْلَفُ بِهَا قُلُوبُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4849, 'مَأْلُوفٌ', 'مألوف', 'اسم مفعول', 'ألف', 'مءلوف', 'ملف', 'مفع. مِنْ أَلِفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَأْلُوفٌ-مَأْلُوفٌ، ةٌ [أ ل ف] (مفع. مِنْ أَلِفَ). ""صَوْتٌ مَأْلُوفٌ لَدَيْهِ"" : مُعْتَادٌ لَهُ، مَا يَأْلَفُهُ. ""عَادَةٌ غَيْرُ مَأْلُوفَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4850, 'مُلْقىً', 'ملقى', 'اسم مفعول', 'لقي', 'ملقى', 'ملق', 'مفع. من أَلْقَى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"(مفع. من أَلْقَى). ""مُلْقَىً عَلَى الأَرْضِ"" : مَطْرُوحٌ أَرْضاً، مَرْمِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4851, 'مُلْقاة', 'ملقاة', 'اسم مفعول', '', 'ملقاة', 'ملقة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من أَلْقَى). ""مُلْقَىً عَلَى الأَرْضِ"" : مَطْرُوحٌ أَرْضاً، مَرْمِيٌّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4852, 'مُلْهَمٌ', 'ملهم', 'اسم مفعول', 'لهم', 'ملهم', 'ملهم', 'مفع. من أَلْهَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من أَلْهَمَ). ""شَاعِرٌ مُلْهَمٌ"" : ذُو قُدْرَةٍ مُوَفَّقَةٍ عَلَى اسْتِحْضَارِ أَفْكَارٍ ومَعَانٍ أَثْنَاءَ كِتَابَةِ الشِّعْرِ وهُوَ يَسْتَوْحِيهَا مِنِ إِلْهَامِهِ. ""فَنَّانَةٌ مُلْهَمَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4853, 'مُمْتَحَنٌ', 'ممتحن', 'اسم مفعول', 'محن', 'ممتحن', 'ممتحن', 'مفع. من اِمْتَحَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ـ:"', '', '', '', '', '', '', '', '', '"(مفع. من اِمْتَحَنَ). ""أَخَذَ كُلُّ مُمْتَحَنٍ مَكَانَهُ فِي قَاعَةِ الامْتِحَانِ"" : الطَّالِبُ الَّذِي يَتَقَدَّمُ إِلَى الامْتِحَانِ لِيَتِمَّ امْتِحَانُهُ فِي مَا تَعَلَّمَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4854, 'مُمْتَلَكٌ', 'ممتلك', 'اسم مفعول', 'ملك', 'ممتلك', 'ممتلك', 'مفع. من اِمْتَلَكَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من اِمْتَلَكَ). ""لَهُ مُمْتَلَكَاتٌ فِي الْمُدُنِ والقُرَى"" : مَا يُتَمَلَّكُ مِنْ أَرَاضٍ وَعَقَارَاتٍ. ""أَلْحَقَ أَضْرَاراً بِالأَرْوَاحِ والْمُمْتَلَكَاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4855, 'مُمْتَهَنٌ', 'ممتهن', 'اسم مفعول', 'مهن', 'ممتهن', 'ممتهن', 'مفع. من اِمْتَهَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من اِمْتَهَنَ). 1.""عَمَلٌ مُمْتَهَنٌ"" : مُحْتَقَرٌ، مُبْتَذَلٌ. 2.""رَجُلٌ مُمْتَهَنٌ"": صُيِّرَ خَادِماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4856, 'مَأْمُورٌ', 'مأمور', 'اسم مفعول', 'أمر', 'مءمور', 'ممر', 'مفع. مِنْ أمَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ أمَرَ). ""مَأْمُورٌ بِمَصْلَحَةِ الْمُوَظَّفِينَ"" : رُتْبَةٌ إِدَارِيَّةٌ بِالشَّرْقِ العَرَبِيِّ، أَيِ الْمُوَظَّفُ الَّذِي يَرْأَسُ قِسْماً مِنْ أَقْسَامِ الإِدَارَةِ الْحُكُومِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4857, 'مُؤَمَّلٌ', 'مؤمل', 'اسم مفعول', 'أمل', 'مءمل', 'ممل', 'مفع. مِنْ أَمَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُؤَمَّلٌ-مُؤَمَّلٌ [أ م ل] (مفع. مِنْ أَمَّلَ). ""حُضُورُهُ مُؤَمَّلٌ"" : مُتَوَقَّعٌ، مُنْتَظَرٌ. ""مِنَ الْمُؤَمَّلِ أَنْ يَحْضُرَ الرَّئِيسُ الْحَفْلَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4858, 'مُؤَمَّمٌ', 'مؤمم', 'اسم مفعول', 'أمم', 'مءمم', 'مم', 'مفع. مِنْ أَمَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُؤَمَّمٌ-مُؤَمَّمٌ، ةٌ [أ م م] (مفع. مِنْ أَمَّمَ). ""مُؤَسَّسَاتٌ اقْتِصَادِيَّةٌ مُؤَمَّمَةٌ"" : أَيْ صَارَتْ خَاضِعَةً لِمِلْكِيَّةِ الدَّوْلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4859, 'مُؤَمَّنٌ', 'مؤمن', 'اسم مفعول', 'أمن', 'مءمن', 'ممن', 'مفع. مِنْ أَمَّنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُؤَمَّنٌ-مُؤَمَّنٌ، ةٌ [أ م ن] (مفع. مِنْ أَمَّنَ). ""سَيَّارَةٌ مُؤَمَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4860, 'مَأْمُونٌ', 'مأمون', 'اسم مفعول', 'أمن', 'مءمون', 'ممن', 'مفع. مِنْ أَمِنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَمِنَ). 1.""رَجُلٌ مَأْمُونٌ"" : أَمِينٌ. 2.""اِلْتَجَأَ إِلَى مَكَانٍ مَأْمُونٍ"": إِلَى مَكَانٍ لا يَخْشَى فِيهِ على نَفْس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4861, 'مُنْتَجَعٌ', 'منتجع', 'اسم مفعول', 'نجع', 'منتجع', 'منتجع', 'مفع. من اِنْتَجَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من اِنْتَجَعَ). 1.""مُنْتَجَعُ الْمَاشِيَةِ"" : مَكَانٌ يُقْصَدُ لِطَلَبِ العُشْبِ، الكَلإِ. 2.""مُنْتَجَعٌ صِحِّيٌّ"" : مَكَانٌ يَقْصِدُهُ الْمَرْضَى وهُمْ فِي فَتْرَةِ النَّقَاهَةِ لِلرَّاحَةِ والاسْتِجْمَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4862, 'مُنْتَحَلٌ', 'منتحل', 'اسم مفعول', 'نحل', 'منتحل', 'منتحل', 'مفع. من اِنْتَحَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْتَحَلٌ-مُنْتَحَلٌ [ن ح ل] (مفع. من اِنْتَحَلَ). ""شِعْرٌ مُنْتَحَلٌ"" : شِعْرٌ مَصْنُوعٌ يُنْسَبُ إِلَى غَيْرِ قَائِلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4863, 'مُنْتَخَبٌ', 'منتخب', 'اسم مفعول', 'نخب', 'منتخب', 'منتخب', 'مفع. من اِنْتَخَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من اِنْتَخَبَ). 1.""مُنْتَخَبٌ مِنْ لَدُنِ الشَّعْبِ"" : مَنْ تَمَّ انْتِخَابُهُ، اِخْتِيَارُهُ لِيَكُونَ مُمَثِّلاً لِمَنِ اِنْتَخَبَهُ فِي مَجْلِسٍ أو بَرْلَمَانٍ. 2.""مُنْتَخَبُ الفَرِيقِ الوَطَنِيِّ"" : الفَرِيقُ الرِّيَاضِيُّ الَّذِي يَتَكَوَّنُ مِنْ عَنَاصِرَ جَيِّدَةٍ يَتِمُّ اخْتِيَارُهُمْ مِنْ عِدَّةِ فِرَقٍ. 3.""مُنْتَخَبَاتٌ أَدَبِيَّةٌ"": مُخْتَارَاتٌ أَدَبِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4864, 'مُنْتَدَبٌ', 'منتدب', 'اسم مفعول', 'ندب', 'منتدب', 'منتدب', 'مفع. من اِنْتَدَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من اِنْتَدَبَ). ""عُيِّنَ عُضْواً مُنْتَدَباً فِي الجَمْعِيَّةِ العَامَّةِ"" : مُكَلَّفاً بِمُهِمَّةٍ. ""عَيَّنَتِ الأُمَمُ الْمُتَّحِدَةُ لَجْنَةً دَوْلِيَّةً مُنْتَدَبَةً لإِنْهَاءِ النِّزَاعِ القَائِمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4865, 'مُنْتَصَفٌ', 'منتصف', 'اسم مفعول', 'نصف', 'منتصف', 'منتصف', 'مفع. من اِنْتَصَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْتَصَفٌ-مُنْتَصَفٌ [ن ص ف] (مفع. من اِنْتَصَفَ). 1.""زَارَهُ فِي مُنْتَصَفِ النَّهَارِ"" : فِي الظُّهْرِ، أَي الثَّانِيَةَ عَشْرَةَ. 2.""نَامَ فِي مُنَتَصَفِ اللَّيْلِ"" : أَي السَّاعَةُ الرَّابِعَةُ والعِشْرُونَ. ""أَطْرُقُ بَابَ صَدِيقِي فِي مُنْتَصَفِ اللَّيْلِ"". (أمل دنقل). 3.""تَوَقَّفَ فِي مُنْتَصَفِ الطَّرِيقِ"" : فِي وَسَطِهِ. ""مُنْتَصَفُ السَّنَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4866, 'مُنْتَقَدٌ', 'منتقد', 'اسم مفعول', 'نقد', 'منتقد', 'منتقد', 'مفع. من اِنْتَقَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من اِنْتَقَدَ). ""عَمَلُهُ مُنْتَقَدٌ"" : عَمَلٌ وُجِّهَ إِلَيْهِ النَّقْدُ والتَّجْرِيحُ. ""صَارَ مُنْتَقَداً مِنَ الجَمِيعِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4867, 'مُنْتَقىً', 'منتقى', 'اسم مفعول', 'نقي', 'منتقى', 'منتق', 'مفع. من اِنْتَقَى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"(مفع. من اِنْتَقَى). ""عُنْصُرٌ مُنْتَقىً مِنَ الجَامِعَةِ"" : مُخْتَارٌ. ""أَلْفَاظٌ مُنْتَقَاةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4868, 'مُنْتَقاة', 'منتقاة', 'اسم مفعول', '', 'منتقاة', 'منتقة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من اِنْتَقَى). ""عُنْصُرٌ مُنْتَقىً مِنَ الجَامِعَةِ"" : مُخْتَارٌ. ""أَلْفَاظٌ مُنْتَقَاةٌ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4869, 'مُنْتَهَكٌ', 'منتهك', 'اسم مفعول', 'نهك', 'منتهك', 'منتهك', 'مفع. من اِنْتَهَكَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْتَهَكٌ، ةٌ - ج: ـون، ـات. [ن هـ ك]. (مفع. من اِنْتَهَكَ). 1.""حُرُمَاتٌ مُنْتَهَكَةٌ"" : تَمَّ تَنَاوُلُهَا بِمَا لاَ يَحِلُّ. 2.""صَارَتِ الأَمَاكِنُ الْمُقَدَّسَةُ مُنْتَهَكَةً عَلَى يَدِ الصَّهَايِنَةِ"" : أَيْ مُدَنَّسَةً"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4870, 'مُنْتَهىً', 'منتهى', 'اسم مفعول', 'نهي', 'منتهى', 'منته', 'مفع. من اِنْتَهَى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"مُنْتَهىً-مُنْتَهىً [ن هـ ي] (مفع. من اِنْتَهَى). 1. ""مُنْتَهَى السَّيْرِ"" : نِهَايَتُهُ. ""مُنْتَهَى الصَّبْرِ"" ""بَلَغَ الصَّبْرُ مُنْتَهَاهُ""النجم آية 42 وأَنَّ إِلَى رَبِّكَ الْمُنْتَهَى (قرآن). 2.""زَجَرَهُ بِمُنْتَهَى ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4871, 'مُنْتَهاة', 'منتهاة', 'اسم مفعول', '', 'منتهاة', 'منتهة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْتَهىً-مُنْتَهىً [ن هـ ي] (مفع. من اِنْتَهَى). 1. ""مُنْتَهَى السَّيْرِ"" : نِهَايَتُهُ. ""مُنْتَهَى الصَّبْرِ"" ""بَلَغَ الصَّبْرُ مُنْتَهَاهُ""النجم آية 42 وأَنَّ إِلَى رَبِّكَ الْمُنْتَهَى (قرآن). 2.""زَجَرَهُ بِمُنْتَهَى ا"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4872, 'مُؤَنَّثٌ', 'مؤنث', 'اسم مفعول', 'أنث', 'مءنث', 'منث', 'مفع. مِنْ أَنَّثَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَنَّثَ). 1.""بُومٌ مُؤَنَّثُهُ بُومَةٌ"" : عَكْسَ الْمُذَكَّرِ. 2.""كَلِمَةٌ مُؤَن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4873, 'مُنْجَزٌ', 'منجز', 'اسم مفعول', 'نجز', 'منجز', 'منجز', 'مفع. من أَنْجَزَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"(مفع. من أَنْجَزَ). ""عَمَلٌ مُنْجَزٌ"" : تَمَّ إِنْجَازُهُ، وصَارَ تَامّاً كَامِلاً. ""مُنْجَزَاتُ الْحُكُومَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4874, 'مُنْحَدَرٌ', 'منحدر', 'اسم مفعول', 'حدر', 'منحدر', 'منحدر', 'مفع. مِن اِنْحَدَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِنْحَدَرَ). 1.""مُنْحَدَرُ جَبَلٍ"" : مَكَانُ انْحِدَارِهِ، اِنْزِلاَقِهِ مِنْ عُلُوٍّ إِلَى أَسْفَلَ. 2.""تَسَلَّقَ مُنْحَدَراً"": طَرِيقُ انْحِدَارِهِ مِنْ أَسْفَلَ إِلَى أَعْلَى. 3.""كَانَ عَلَى مُنْحَدَرِ السُّوءِ"" : مُنْزَلَقِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4875, 'مُنْزَلٌ', 'منزل', 'اسم مفعول', 'نزل', 'منزل', 'منزل', 'مفع. من أَنْزَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُنْزَلٌ-مُنْزَلٌ، ةٌ [ن ز ل] (مفع. من أَنْزَلَ). ""كَلاَمٌ مُنْزَلٌ"" : كَلاَمٌ مُوحىً بِهِ. ""الْكُتُبُ الْمُنْزَلَةُ"" : وَهِيَ التَّوْرَاةُ وَالإِنْجِيلُ وَالْقُرْآنُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4876, 'مُنْسَابٌ', 'منساب', 'اسم مفعول', 'سيب', 'منساب', 'منسب', 'مفع.من اِنْسابَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْسَابٌ-مُنْسَابٌ، ةٌ [س ي ب] (مفع.من اِنْسابَ). ""مِيَاهٌ مُنْسَابَةٌ بَيْنَ مُنْعَرَجَاتِ الْجَبَلِ"" : مُنْحَدِرَةٌ، مُنْزَلِقَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4877, 'مُنْسَلَخٌ', 'منسلخ', 'اسم مفعول', 'سلخ', 'منسلخ', 'منسلخ', 'مفع. من اِنْسَلَخَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْسَلَخٌ-مُنْسَلَخٌ [س ل خ] (مفع. من اِنْسَلَخَ). ""مُنْسَلَخُ الشَّهْرِ"" : نِهَايَتُهُ، آخِرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4878, 'مَنْشَأٌ', 'منشأ', 'اسم مفعول', 'نشأ', 'منشء', 'منش', 'مفع. من أَنْشَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْشَأٌ-مَنْشَأٌ [ن ش أ] (مفع. من أَنْشَأَ). 1.""يَعْرِفُ مَنْشَأَهُ وَأَصْلَهُ"" : أَيْ مَوْضِعَ نَشْأَتِهِ. 2.""حَاوَلَ أَنْ يُحَدِّدَ مَنْشَأَ‏ الفَوْضَى وَالفِتَنِ"" : سَبَبَهَا، أَصْلَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4879, 'مَنْشَأَةٌ', 'منشأة', 'اسم مفعول', '', 'منشءة', 'منشة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْشَأٌ-مَنْشَأٌ [ن ش أ] (مفع. من أَنْشَأَ). 1.""يَعْرِفُ مَنْشَأَهُ وَأَصْلَهُ"" : أَيْ مَوْضِعَ نَشْأَتِهِ. 2.""حَاوَلَ أَنْ يُحَدِّدَ مَنْشَأَ‏ الفَوْضَى وَالفِتَنِ"" : سَبَبَهَا، أَصْلَهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4880, 'مُنْصَرَفٌ', 'منصرف', 'اسم مفعول', 'صرف', 'منصرف', 'منصرف', 'مفع. من اِنْصَرَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْصَرَفٌ-مُنْصَرَفٌ [ص ر ف] (مفع. من اِنْصَرَفَ). ""اِلْتَقَى السُّيَّاحُ فِي الْمُنْصَرَفِ"" : مَكَانُ الانْطِلاَقِ، الرَّحِيلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4881, 'مُنْضَمٌّ', 'منضم', 'اسم مفعول', 'ضمم', 'منضم', 'منضم', 'مفع. من اِنْضَمَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من اِنْضَمَّ). ""مُنْضَمٌّ إِلَى الفَرِيقِ الرِّيَاضِيّ"" : مُلْتَحِقٌ بِهِ، مُنْضَوٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4882, 'مُنْطَلَقٌ', 'منطلق', 'اسم مفعول', 'طلق', 'منطلق', 'منطلق', 'مفع. مِن اِنْطَلَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"مُنْطَلَقٌ-مُنْطَلَقٌ [ط ل ق] (مفع. مِن اِنْطَلَقَ). 1.""مُنْطَلَقُ السِّبَاقِ"" : نُقْطَةُ الاِنْطِلاَقِ. 2.""كَانَ مُنْطَلَقُ مَشْرُوعِهِمْ جَيِّداً"" : بِدَايَةُ مَشْرُوعِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4883, 'مُنْعَرَجٌ', 'منعرج', 'اسم مفعول', 'عرج', 'منعرج', 'منعرج', 'مفع. مِن اِنْعَرَجَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"(مفع. مِن اِنْعَرَجَ). ""مُنْعَرَجُ نَهْرٍ"" : مُنْعَطَفُهُ. ""مُنْعَرَجُ الطَّرِيقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4884, 'مُنْعَطَفٌ', 'منعطف', 'اسم مفعول', 'عطف', 'منعطف', 'منعطف', ' مفع. من اِنْعَطَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ج"', '', '', '', '', '', '', '', '', '"( مفع. من اِنْعَطَفَ). 1.""مُنْعَطَفُ الطَّرِيقِ"" : مُنْعَرَجٌ، مَكَانُ انْحِرَافِهِ. 2.""مُنْعَطَفُ الوَادِي"" : مُنْحَنَاهُ، مُنْعَرَجُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4885, 'مُنْعَكَسٌ', 'منعكس', 'اسم مفعول', 'عكس', 'منعكس', 'منعكس', 'مفع. مِن اِنْعَكَسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"مُنْعَكِسٌ-مُنْعَكِسٌ، ةٌ [ع ك س] (فا. من اِنْعَكَسَ). 1.""نَظَرَتْ إِلَى صُورَتِهَا الْمُنْعَكِسَةِ فِي المِرْآةِ"" : أَيْ ظُهُورُ صُورَتِهَا البَادِيَةِ عَلَى المِرْآةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4886, 'مُنْقَعٌ', 'منقع', 'اسم مفعول', 'نقع', 'منقع', 'منقع', 'مفع. من أَنْقَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنْقَعٌ-مُنْقَعٌ، ةٌ [ن ق ع] (مفع. من أَنْقَعَ). ""تَمْرٌ مُنْقَعٌ"" : تَمْرٌ أُنْقِعَ، أَيْ تُرِكَ فِي الْمَاءِ حَتَّى تَغَيَّرَ لَوْنُهُ وطَعْمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4887, 'مُنْقَلَبٌ', 'منقلب', 'اسم مفعول', 'قلب', 'منقلب', 'منقلب', 'مفع. من اِنْقَلَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من اِنْقَلَبَ). الشعراء آية 227 وسَيَعْلَمُ الَّذِينَ ظَلَمُوا أَيَّ مُنْقَلَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4888, 'مُنْكَرٌ', 'منكر', 'اسم مفعول', 'نكر', 'منكر', 'منكر', 'مفع. من أَنْكَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"(مفع. من أَنْكَرَ). 1.""أَتَى بِمُنْكَرٍ فاحِشٍ"" : مَا يَأْتِي بِهِ الإِنْسَانُ مِنْ قَوْلٍ أو فِعْلٍ مُخَالِفٍ لِلشَّرْعِ وأَوَامِرِ الله.آل عمران آية 110 كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأمُرُونَ بِالْمَعْرُوفِ وتَنْهَوْنَ عَنِ الْمُنْكَرِ وتُؤْمِنُونَ بِالله (قرآن) ""الأَمْرُ بِالْمَعْرُوفِ والنَّهْيُ عَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4889, 'مُنْهَكٌ', 'منهك', 'اسم مفعول', 'نهك', 'منهك', 'منهك', 'مفع. من أَنْهَكَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من أَنْهَكَ). ""مُنْهَكُ القُوَى"" : مَنْهوكٌ، مُحَطَّمٌ مُتَعَبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4890, 'مُهَانٌ', 'مهان', 'اسم مفعول', 'هون', 'مهان', 'مهن', 'مفع. من أَهَانَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُهَانٌ-مُهَانٌ [هـ و ن] (مفع. من أَهَانَ). ""رَجُلٌ مُهَانٌ"" : مُحْتَقَرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4891, 'مُهْرَقٌ', 'مهرق', 'اسم مفعول', 'هرق', 'مهرق', 'مهرق', 'مفع. من أَهْرَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مَهَارِقُ"', '', '', '', '', '', '', '', '', '"(مفع. من أَهْرَقَ). 1.""خَطَّ عَلَى الْمُهْرَقِ"" : الصَّحِيفَةُ البَيْضَاءُ، أَوْ ثَوْبُ حَرِيرٍ أَبْيَضَ يُسْقَى بِالصَّمْغِ وَيُصْقَلُ ثُمَّ يُكْتَبُ فِيهِ. 2.""طَافَ الْمُهْرَقَ"" : الصَّحْرَاءَ الْمَلْسَاءَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4892, 'مَهَارِقُ', 'مهارق', 'اسم مفعول', '', 'مهارق', 'مهرق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4893, 'مُؤَهَّلٌ', 'مؤهل', 'اسم مفعول', 'أهل', 'مءهل', 'مهل', 'مفع. مِنْ أَهَّلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ أَهَّلَ). ""مُؤَهَّلٌ لِلْقِيَامِ بِهَذَا العَمَلِ"" : ذُو أَهْلِيَّةٍ، لَهُ كَفَاءةٌ وَقُدُرَاتٌ لِذَلِكَ. ""كَانَ مُؤَهَّلاً لِذَلِكَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4894, 'مَأْهُولٌ', 'مأهول', 'اسم مفعول', 'أهل', 'مءهول', 'مهل', 'مفع. مِنْ أَهِلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَأْهُولٌ-مَأْهُولٌ [أ هـ ل] (مفع. مِنْ أَهِلَ). ""مَكَانٌ مَأْهُولٌ"": مَكانٌ فِيهِ أَهْلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4895, 'مُهْمَلٌ', 'مهمل', 'اسم مفعول', 'همل', 'مهمل', 'مهمل', 'مفع. من أَهْمَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من أَهْمَلَ). 1.""أَرْضٌ مُهْمَلَةٌ"" : مَتْرُوكَةٌ بِلاَ عِنَايَةٍ. ""رِسَالَةٌ مُهْمَلَةٌ"". 2.""سَلَّةُ الْمُهْمَلاَتِ"" : سَلَّةٌ تُوضَعُ فِيهَا الأَوْرَاقُ وَالرَّسَائِلُ الَّتِي لاَ قِيمَةَ لَهَا. 3.""كَلاَمٌ مُهْمَلٌ"" : غَيْرُ مُعْتَنـىً بِهِ، لاَقِيمَةَ لَهُ. 4.""حَرْفٌ مُهْمَلٌ"" : غَيْرُ مَنْقُوطٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4896, 'مُوثَقٌ', 'موثق', 'اسم مفعول', 'وثق', 'موثق', 'مثق', 'مفع. من أَوْثَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوثَقٌ-مُوثَقٌ [و ث ق] (مفع. من أَوْثَقَ). ""مُوثَقُ اليَدَيْنِ وَالرِّجْلَيْنِ"" : مُقَيَّدٌ، مَرْبُوطٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4897, 'مُوجَبٌ', 'موجب', 'اسم مفعول', 'وجب', 'موجب', 'مجب', 'مفع. من أَوْجَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوجَبٌ-مُوجَبٌ، ةٌ [و ج ب] (مفع. من أَوْجَبَ). ""كَلاَمٌ مُوجَبٌ"" : أَيْ لاَ يَحْتَمِلُ الاسْتِفْهَامَ وَلاَ النَّفْيَ وَلاَ النَّهْيَ، أَيْ مُؤَكَّدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4898, 'مُوجَزٌ', 'موجز', 'اسم مفعول', 'وجز', 'موجز', 'مجز', 'مفع. من أَوْجَزَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مَوَاجِزُ"', '', '', '', '', '', '', '', '', '"(مفع. من أَوْجَزَ). ""كَلاَمٌ مُوجَزٌ"" : مُخْتَصَرٌ. ""مُوجَزُ نَشْرَةِ الأَخْبَارِ"" ""نَصٌّ مُوجَزٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4899, 'مَوَاجِزُ', 'مواجز', 'اسم مفعول', '', 'مواجز', 'مجز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4900, 'مُوحىً', 'موحى', 'اسم مفعول', 'وحي', 'موحى', 'مح', 'مفع. من أَوْحَى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"مُوحىً-مُوحىً [و ح ي] (مفع. من أَوْحَى). ""مُوحىً بِهِ"" : مُنْزَلٌ، مُلْهَمٌ. ""نَبِيٌّ مُوحىً إِلَيْهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4901, 'مُوحاة', 'موحاة', 'اسم مفعول', '', 'موحاة', 'محة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوحىً-مُوحىً [و ح ي] (مفع. من أَوْحَى). ""مُوحىً بِهِ"" : مُنْزَلٌ، مُلْهَمٌ. ""نَبِيٌّ مُوحىً إِلَيْهِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4902, 'مُودَعٌ', 'مودع', 'اسم مفعول', 'ودع', 'مودع', 'مدع', 'مفع. من أَوْدَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُودَعٌ-مُودَعٌ، ةٌ [و د ع] (مفع. من أَوْدَعَ). 1.""مَالٌ مَودَعٌ فِي البَنْكِ"" : مُسَلَّمٌ لِلْبَنْكِ عَلَى سَبِيلِ الإِيدَاعِ. 2.""أَم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4903, 'مُوصىً', 'موصى', 'اسم مفعول', 'وصي', 'موصى', 'مص', 'مفع. من أَوْصَى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"مُوصىً-مُوصىً [و ص ي] (مفع. من أَوْصَى). 1.""مُوصىً بِهِ"": كُلُّ مَوْهُوبٍ فِي وَصِيَّةٍ مَكْتُوبَةٍ. 2.""مُوصىً لَهُ بِكُلِّ الإِرْثِ"" : أَيْ مَوْهُوبٌ بِكُلِّ الإِرْثِ بِمُوجِبِ وَصِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4904, 'مُوصاة', 'موصاة', 'اسم مفعول', '', 'موصاة', 'مصة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوصىً-مُوصىً [و ص ي] (مفع. من أَوْصَى). 1.""مُوصىً بِهِ"": كُلُّ مَوْهُوبٍ فِي وَصِيَّةٍ مَكْتُوبَةٍ. 2.""مُوصىً لَهُ بِكُلِّ الإِرْثِ"" : أَيْ مَوْهُوبٌ بِكُلِّ الإِرْثِ بِمُوجِبِ وَصِيَّةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4905, 'مُوفَدٌ', 'موفد', 'اسم مفعول', 'وفد', 'موفد', 'مفد', 'مفع. من أَوْفَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من أَوْفَدَ). ""مُوفَدٌ مِنْ قِبَلِ رَئِيسِهِ"" : مُرْسَلٌ، مُبْعُوثٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4906, 'مُولَعٌ', 'مولع', 'اسم مفعول', 'ولع', 'مولع', 'ملع', 'مفع. من أَوْلَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من أَوْلَعَ). 1.""مُولَعٌ بِحُبِّ الْمَعْرِفَةِ"" : مُتَحَمِّسٌ. 2.""مُولَعٌ بِحُبِّهَا"" : مُغ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4907, 'مُومَأٌ', 'مومأ', 'اسم مفعول', 'ومأ', 'مومء', 'مم', 'مفع. من أَوْمَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من أَوْمَأَ). ""مُومَأٌ إِلَيْهِ"" : مُشَارٌ إِلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4908, 'مُومَأَةٌ', 'مومأة', 'اسم مفعول', '', 'مومءة', 'ممة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من أَوْمَأَ). ""مُومَأٌ إِلَيْهِ"" : مُشَارٌ إِلَيْهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4909, 'مُوهَنٌ', 'موهن', 'اسم مفعول', 'وهن', 'موهن', 'مهن', 'مفع. من أَوْهَنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من أَوْهَنَ). ""مُوهَنُ القُوَّةِ"" : وَاهِنُها، ضَعِيفُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4910, 'مُؤْتَمَنٌ', 'مؤتمن', 'اسم مفعول', 'أمن', 'مءتمن', 'متمن', 'مفع. مِن اِئْتَمَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُؤْتَمَنٌ-مُؤْتَمَنٌ، ةٌ [أ م ن] (مفع. مِن اِئْتَمَنَ). ""شَاهِدٌ مُؤْتَمَنٌ"": مَوْثُوقٌ بِهِ. ""رُبَّ مُؤْتَمَنٍ ظَنِينٍ وَمُتَّهَمٍ أَمِينٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4911, 'مُؤَيَّدٌ', 'مؤيد', 'اسم مفعول', 'أيد', 'مءيد', 'مد', 'مفع. مِنْ أَيَّدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ أَيَّدَ). 1.""مُؤَيَّدٌ بِالقَانُونِ"" : الْمُقَوَّى وَالْمُدَعَّمُ ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4912, 'مَبِيعٌ', 'مبيع', 'اسم مفعول', 'بيع', 'مبيع', 'مبع', 'مفع. مِنْ بَاعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ بَاعَ). ""مَبِيعَاتُ السِّلَعِ"" : مَا بِيعَ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4913, 'مَبْتُورٌ', 'مبتور', 'اسم مفعول', 'بتر', 'مبتور', 'مبتر', 'مفع. مِنْ بَتَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ بَتَرَ). 1.""مَبْتُورُ اليَدِ"" : مَقْطُوعُ اليَدِ. 2.""كِتَابٌ مَبْتُورٌ"" : تَنْقُصُهُ أَوْرَاقٌ، أَيْ هِيَ مَقْطُوعَةٌ مِنْهُ. 3.""أَجَابَ جَوَاباً مَبْتُوراً"": نَاقِصاً، غَيْرَ تَامٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4914, 'مَبْثُورٌ', 'مبثور', 'اسم مفعول', 'بثر', 'مبثور', 'مبثر', 'مفع. مِنْ بَثَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَبْثُورٌ-مَبْثُورٌ [ب ث ر] (مفع. مِنْ بَثَرَ). 1.""رَجُلٌ مَبْثُورٌ"" : غَنِيٌّ جِدّاً. 2.""هُوَ مَبْثُورٌ"" : مَحْسُودٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4915, 'مبجلٌّ', 'مبجل', 'اسم مفعول', 'بجل', 'مبجل', 'مبجل', 'مفع. من بجل', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '', ':لا شرح');
