INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4924, 'مُبرَمٌ', 'مبرم', 'اسم مفعول', 'برم', 'مبرم', 'مبرم', 'مفع. مِنْ بَرَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4925, 'مَبْرُومٌ', 'مبروم', 'اسم مفعول', 'برم', 'مبروم', 'مبرم', 'مفع. مِنْ بَرَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَبْرُومٌ-مَبْرُومٌ، ةٌ [ب ر م] (مفع. مِنْ بَرَمَ). ""حَبْلٌ مَبْرُومٌ"" : مَفْتُولٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4926, 'مُبَرْمَجٌ', 'مبرمج', 'اسم مفعول', 'برمج', 'مبرمج', 'مبرمج', 'مفع. مِنْ بَرْمَجَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُبَرْمَجٌ-مُبَرْمَجٌ [ب ر م ج] (مفع. مِنْ بَرْمَجَ). 1.""دَرْسٌ مُبَرْمَجٌ"" : أَيْ وُضِعَ وَفْقَ بَرْنَامَجٍ مَعْلُومٍ. 2.""التَّعْلِيمُ الْمُبَرْمَجُ"" : أَيِ التَّعْلِيمُ الَّذِي يُسْتَخْدَمُ وَفْقَ خُطَّةٍ، وَأَصْبَحَتْ هَذِهِ الكَلِمَةُ تُسْتَخْدَمُ فِي الْحَاسُوبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4927, 'مُبَرْهَنٌ', 'مبرهن', 'اسم مفعول', 'برهن', 'مبرهن', 'مبرهن', 'مفع. مِنْ بَرْهَنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبَرْهَنٌ-مُبَرْهَنٌ [ب ر هـ ن] (مفع. مِنْ بَرْهَنَ). ""عَمَلٌ مُبَرْه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4928, 'مَبْرِيٌّ', 'مبري', 'اسم مفعول', 'بري', 'مبري', 'مبر', 'مفع. مِنْ بَرَى', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَبْرِيٌّ-مَبْرِيٌّ، ةٌ [ب ر ي] (مفع. مِنْ بَرَى). ""قَلَمٌ مَبْرِيٌّ"" : مَنْحُوتٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4929, 'مُبَسَّطٌ', 'مبسط', 'اسم مفعول', 'بسط', 'مبسط', 'مبسط', 'مفع. مِنْ بَسَّطَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبَسَّطٌ-مُبَسَّطٌ، ةٌ [ب س ط] (مفع. مِنْ بَسَّطَ). ""دَرْسٌ مُبَسَّطٌ"" : سَهْلٌ، وَاضِحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4930, 'مَبْسُوطٌ', 'مبسوط', 'اسم مفعول', 'بسط', 'مبسوط', 'مبسط', 'مفع. مِنْ بَسَطَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"مَبْسُوطٌ-مَبْسُوطٌ، ةٌ [ب س ط] (مفع. مِنْ بَسَطَ). ""جَاءَ مَبْسُوطاً"" : مُنْشَرِحاً، بِرَحَابَةِ صَدْرٍ، بَاسِطاً ذِرَاعَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4931, 'مَبْشُورٌ', 'مبشور', 'اسم مفعول', 'بشر', 'مبشور', 'مبشر', 'مفع. مِنْ بَشَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَبْشُورٌ-مَبْشُورٌ، ةٌ [ب ش ر] (مفع. مِنْ بَشَرَ). ""جَزَرٌ مَبْشُورٌ"": مُفَتَّتٌ عَلَى شَكْلِ قِطَعٍ صَغِيرَةٍ دَقِيقَةٍ. ""جُبْنٌ مَبْشُورٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4932, 'مُبَطَّنٌ', 'مبطن', 'اسم مفعول', 'بطن', 'مبطن', 'مبطن', 'مفع. مِنْ بَطَّنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبَطَّنٌ-مُبَطَّنٌ، ةٌ [ب ط ن] (مفع. مِنْ بَطَّنَ). 1.""ثَوْبٌ مُبَطَّنٌ"" : لَهُ بِطَانَةٌ، غِلاَفٌ بِدَاخِلِهِ. 2.""كَلاَمٌ مُبَطَّنٌ"" : كَلاَمٌ يَتَضَمَّنُ إِشَارَاتٍ لِمَعَانٍ غَيْرِ مُصَرَّحٍ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4933, 'مَبْعُوثٌ', 'مبعوث', 'اسم مفعول', 'بعث', 'مبعوث', 'مبعث', 'مفع. مِنْ بَعَثَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', '', '"مَبْعُوثٌ-مَبْعُوثٌ، ةٌ [ب ع ث] (مفع. مِنْ بَعَثَ). 1.""جَاءَ مَبْعُوثاً مِنْ لَدُنِ الرَّئِيسِ"" : مَرْسُولاً، مُوفَداً. 2.""النَّبِيُّ مَبْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4934, 'مُبَعْثَرٌ', 'مبعثر', 'اسم مفعول', 'بعثر', 'مبعثر', 'مبعثر', 'مفع. مِنْ بَعْثَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبَعْثَرٌ-مُبَعْثَرٌ، ةٌ [ب ع ث ر] (مفع. مِنْ بَعْثَرَ). ""أَثَاثٌ مُبَعْث"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4935, 'مَبْغىً', 'مبغى', 'اسم مفعول', 'بغي', 'مبغى', 'مبغ', 'مفع. مِنْ بَغَى', '', '', 'مفرد', 'Dy', '', '', '":مَبَاغٍ:الْمَبَاغِي"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ بَغَى). 1. : مَكَانٌ يُبْحَثُ فِيهِ عَنْ تَحْقِيقِ رَغْبَةٍ أَوْ مَطْلَبٍ. 2.:رَغْبَةٌ، مَا يُرْجَى تَحْقِيقُهُ. 3.: ماخُورٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4936, 'مَبْغاة', 'مبغاة', 'اسم مفعول', '', 'مبغاة', 'مبغة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":مَبَاغٍ:الْمَبَاغِي"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ بَغَى). 1. : مَكَانٌ يُبْحَثُ فِيهِ عَنْ تَحْقِيقِ رَغْبَةٍ أَوْ مَطْلَبٍ. 2.:رَغْبَةٌ، مَا يُرْجَى تَحْقِيقُهُ. 3.: ماخُورٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4937, 'مَبَاغِي', 'مباغي', 'اسم مفعول', '', 'مباغي', 'مبغ', '', 'Tk', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4938, 'مُبَلَّطٌ', 'مبلط', 'اسم مفعول', 'بلط', 'مبلط', 'مبلط', 'مفع. مِنْ بَلَّطَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبَلَّطٌ-مُبَلَّطٌ، ةٌ [ب ل ط] (مفع. مِنْ بَلَّطَ). ""رَصِيفٌ مُبَلَّطٌ"": مَفْرُوشٌ بِالبَلاَطِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4939, 'مُبَلَّغٌ', 'مبلغ', 'اسم مفعول', 'بلغ', 'مبلغ', 'مبلغ', 'مفع. مِنْ بَلَّغَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُبَلَّغٌ-مُبَلَّغٌ [ب ل غ] (مفع. مِنْ بَلَّغَ). """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4940, 'مُبَلَّلٌ', 'مبلل', 'اسم مفعول', 'بلل', 'مبلل', 'مبل', 'مفع. مِنْ بَلَّلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ بَلَّلَ). ""وَصَلَ مُبَلَّلَ الثِّيَابِ"" : أَيْ مُبْتَلاًّ، مَبْلُولَ الثِّيَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4941, 'مُبَنَّجٌ', 'مبنج', 'اسم مفعول', 'بنج', 'مبنج', 'مبنج', 'مفع. مِنْ بَنَّجَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ بَنَّجَ). ""مَا زَالَ مُبَنَّجاً"" : فَاقِداً لِلْوَعْيِ بِسَبَبِ تَبْنِيجِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4942, 'مَبْنِيٌّ', 'مبني', 'اسم مفعول', 'بني', 'مبني', 'مبن', 'مفع. مِنْ بَنَى', '', 'ة', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَبْنِيٌّ-مَبْنِيٌّ، ةٌ [ب ن ي] (مفع. مِنْ بَنَى). 1.""بَيْتٌ مَبْنِيٌّ بِالحِجَارَةِ الصَّلْبَةِ"" : شُيِّدَ. ""عِمَارَةٌ مَبْنِيّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4943, 'مَبْهُورٌ', 'مبهور', 'اسم مفعول', 'بهر', 'مبهور', 'مبهر', 'مفع. مِنْ بَهَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ بَهَرَ). ""كَانَ مَبْهُوراً بِأَلْعَابِهِ البَهْلَوَانِيَّةِ"" : مَدْهُوشاً، مَأْخُوذاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4944, 'مُبَيَّنٌ', 'مبين', 'اسم مفعول', 'بين', 'مبين', 'مبن', 'مفع. مِنْ بَيَّنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُبِينٌ-مُبِينٌ [ب ي ن]. 1.""نَصْرٌ مُبِينٌ مِنَ الله"" : وَاضِحٌ لاَ غُبَارَ عَلَيْهِ. 2.""الكِتَابُ الْمُبِينُ"" : القُرْآنُ الكَرِيمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4945, 'مُتَابَعٌ', 'متابع', 'اسم مفعول', 'تبع', 'متابع', 'متبع', 'مفع. مِنْ تَابَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', '', '"مُتَابَعٌ-مُتَابَعٌ، ةٌ [ت ب ع] (مفع. مِنْ تَابَعَ). ""مَا زَالَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4946, 'مُتَبَادَلٌ', 'متبادل', 'اسم مفعول', 'بدل', 'متبادل', 'متبدل', 'مفع. مِنْ تَبَادَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', '', '"مُتَبَادَلٌ-مُتَبَادَلٌ، ةٌ [ب د ل] (مفع. مِنْ تَبَادَلَ). ""حُبٌّ مُتَبَادَلٌ"" : حُبٌّ فِيهِ أَخْذٌ وَعَطَاءٌ، أَيْ كُلٌّ يُبَادِلُ الآخَرَ الحُبَّ نَفْسَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4947, 'متبرعمٌ', 'متبرعم', 'اسم مفعول', 'برعم', 'متبرعم', 'متبرعم', 'مفع. من تبرعم', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4948, 'مُتَبَّلٌ', 'متبل', 'اسم مفعول', 'تبل', 'متبل', 'متبل', 'مفع. مِنْ تَبَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَبَّلٌ-مُتَبَّلٌ [ت ب ل] (مفع. مِنْ تَبَّلَ). ""طَعَامٌ مُتَبَّلٌ"" : مُطَيَّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4949, 'مُتَبَنّىً', 'متبنى', 'اسم مفعول', 'بني', 'متبنى', 'متبن', 'مفع. مِنْ تَبَنَّى', '', '', 'مفرد', 'Dy', 'Pm', '', '"ون"', '', '', 'ـو', '', '', '', '', '', '"مُتَبَنّىً-مُتَبَنّىً، ـاةٌ [ب ن ي] (مفع. مِنْ تَبَنَّى). ""وَلَـدٌ مُتَبَن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4950, 'مُتَبَنّاة', 'متبناة', 'اسم مفعول', '', 'متبناة', 'متبنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مُتَبَنّىً-مُتَبَنّىً، ـاةٌ [ب ن ي] (مفع. مِنْ تَبَنَّى). ""وَلَـدٌ مُتَبَن"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4951, 'مُتَجَاوَزٌ', 'متجاوز', 'اسم مفعول', 'جوز', 'متجاوز', 'متجز', 'مفع. مِنْ تَجَاوَزَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ تَجَاوَزَ). ""فِكْرٌ مُتَجَاوَزٌ"" : فِكْرٌ صَارَ مُتَخَطّىً، أَيْ لَمْ يَعُدْ مَعْمُولاً بِهِ. ""أَحْكَامٌ مُتَجَاوَزَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4952, 'مُتَدَاوَلٌ', 'متداول', 'اسم مفعول', 'دول', 'متداول', 'متدل', 'مفع. مِنْ تَدَاوَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"مُتَدَاوَلٌ-مُتَدَاوَلٌ، ةٌ [د و ل] (مفع. مِنْ تَدَاوَلَ). 1.""نَقْدٌ مُتَدَاوَلٌ"" : رَائِجٌ. ""عُمْلَةٌ مُتَدَاوَلَةٌ"". 2.""رَأْيٌ مُتَدَاوَلٌ بَيْنَ النَّاسِ"" : شَائِعٌ، سَائِدٌ، سَارٍ. ""كَلاَمٌ مُتَدَاوَلٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4953, 'مَتْرُوكٌ', 'متروك', 'اسم مفعول', 'ترك', 'متروك', 'مترك', 'مفع. مِنْ تَرَكَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ تَرَكَ). 1.""مَتَاعٌ مَتْرُوكٌ"" : مُهْمَلٌ. 2.""مَتْرُوكَاتُ الْمُتَوَفَّى"" : مِيرَاثُهُ، مَا خَلَّفَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4954, 'مُتَعَارَفٌ', 'متعارف', 'اسم مفعول', 'عرف', 'متعارف', 'متعرف', 'مفع. مِنْ تَعَارَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ تَعَارَفَ). ""اِتَّفَقُوا عَلَى مَا هُوَ مُتَعَارَفٌ عَلَيْهِ"" : عَلَى مَا هُوَ مَأْلُوفٌ وَمُعْتَادٌ وَجَرَتْ بِهِ العَادَةُ. ""أرْسَى مَبادِئَ حُقوقِ الإنْسانِ حَسَبَ ما هُوَ مُتَعارَفٌ عَلَيْها دَوْلِيّاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4955, 'مُتَعَبَّدٌ', 'متعبد', 'اسم مفعول', 'عبد', 'متعبد', 'متعبد', 'مفع. مِنْ تَعَبَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَعَبَّدٌ-مُتَعَبَّدٌ [ع ب د] (مفع. مِنْ تَعَبَّدَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4956, 'مَتْعُوسٌ', 'متعوس', 'اسم مفعول', 'تعس', 'متعوس', 'متعس', 'مفع. مِنْ تَعِسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مَتَاعِيسُ"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ تَعِسَ). ""مَتْعُوسُ الْحَظِّ"" : قَلِيلُهُ، بَائِسٌ، تَعِيسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4957, 'مَتَاعِيسُ', 'متاعيس', 'اسم مفعول', '', 'متاعيس', 'متعس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4958, 'مُتَكَلَّمٌ', 'متكلم', 'اسم مفعول', 'كلم', 'متكلم', 'متكلم', 'مفع. مِنْ تَكَلَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَكَلَّمٌ-مُتَكَلَّمٌ [ك ل م] (مفع. مِنْ تَكَلَّمَ). ""اِجْتَمَعُوا فِي الْمُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4959, 'مُتَنَاوَلٌ', 'متناول', 'اسم مفعول', 'نول', 'متناول', 'متنل', 'مفع. مِنْ تَنَاوَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَنَاوَلٌ-مُتَنَاوَلٌ، ةٌ [ن و ل] (مفع. مِنْ تَنَاوَلَ). ""فِي مُتَنَاوَلِ اليَدِ"" : مَا يُمْكِنُ الْحُصُولُ عَلَيْهِ، مُيَسَّرٌ. ""دَوَاءٌ فِي مُتَنَاوَلِ الجَمِيعِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4960, 'مُتَنَزَّهٌ', 'متنزه', 'اسم مفعول', 'نزه', 'متنزه', 'متنزه', 'مفع. مِنْ تَنَزَّهَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ تَنَزَّهَ). ""خَرَجَ إِلَى الْمُتَنَزَّهِ"" : مَكَانُ النُّزْهَةِ، التَّنَزُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4961, 'مُتَنَصَّحٌ', 'متنصح', 'اسم مفعول', 'نصح', 'متنصح', 'متنصح', 'مفع. مِنْ تَنَصَّحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَنَصَّحٌ-مُتَنَصَّحٌ [ن ص ح] (مفع. مِنْ تَنَصَّحَ). 1.""ثَوْبٌ مُتَنَصَّحٌ"" : مُرَقَّعٌ، أو مُخَيَّطٌ جَيِّداً. 2.""فِي ثَوْبِهِ مُتَنَصَّحٌ لَمْ يُصْلِحْهُ"": أَيْ مَوْضِعُ إِصْلاَحٍ وَخِيَاطَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4962, 'مُتَنَفَّسٌ', 'متنفس', 'اسم مفعول', 'نفس', 'متنفس', 'متنفس', 'مفع. مِنْ تَنَفَّسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَنَفَّسٌ-مُتَنَفَّسٌ [ن ف س] (مفع. مِنْ تَنَفَّسَ). ""وَجَدَ مُتَنَفَّساً لِحَلِّ أَزْمَتِهِ"" : مَخْرَجاً. ""وَجَدَ فِي الْهُجُومِ عَلَيْهِ مُتَنَفَّساً لِعَوَاطِفِهِ الثَّائِرَةِ الْمَكْتُومَةِ"". (ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4963, 'مُتَوَفّىً', 'متوفى', 'اسم مفعول', 'وفي', 'متوفى', 'متف', 'مفع. مِنْ تَوَفَّى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', 'ـو', '', '', '', '', '', '"مُتَوَفّىً-مُتَوَفّىً [و ف ي] (مفع. مِنْ تَوَفَّى). ""مُتَوَفّىً مُنْذُ زَمَنٍ بَعِيدٍ"" : الْمَيِّتُ، مَنْ فَاضَتْ رُوحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4964, 'مُتَوَفّاة', 'متوفاة', 'اسم مفعول', '', 'متوفاة', 'متفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَوَفّىً-مُتَوَفّىً [و ف ي] (مفع. مِنْ تَوَفَّى). ""مُتَوَفّىً مُنْذُ زَمَنٍ بَعِيدٍ"" : الْمَيِّتُ، مَنْ فَاضَتْ رُوحُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4965, 'مُتَوَقَّعٌ', 'متوقع', 'اسم مفعول', 'وقع', 'متوقع', 'متقع', 'مفع. مِنْ تَوَقَّعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَوَقَّعٌ-مُتَوَقَّعٌ [و ق ع] (مفع. مِنْ تَوَقَّعَ). 1.""مِنَ الْمُتَوَقِّعِ أَنْ يَحْضُرَ الْحَفْلَ"" : مِنَ الْمُحْتَمَلِ. 2.""أَمْرٌ مُتَوَقَّعٌ"" : حُدُوثُهُ مُرْتَقَبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4966, 'مُتَيَّمٌ', 'متيم', 'اسم مفعول', 'تيم', 'متيم', 'متم', 'مفع. مِنْ تَيَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ تَيَّمَ). ""شَاعِرٌ مُتَيَّمٌ"" : شَاعِرٌ مُسْتَبِدٌّ بِهِ الْحُبُّ وَقَدْ ذَهَبَ بِعَقْلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4967, 'مُثَبَّتٌ', 'مثبت', 'اسم مفعول', 'ثبت', 'مثبت', 'مثبت', 'مفع. مِنْ ثَبَّتَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ ثَبَّتَ). ""مِسْمَارٌ مُثَبَّتٌ"" : مُرَسَّخٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4968, 'مَثْرودٌ', 'مثرود', 'اسم مفعول', 'ثرد', 'مثرود', 'مثرد', 'مفع. من ثَردَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَثْرودٌ-مَثْرودٌ [ث ر د] (مفع. من ثَردَ). ""أطْعَمَهُ الْمَثْرودَ"" : ثَريدٌ، طَعامٌ من خُبْزٍ يُبَلُّ بالْمَرَقِ وبَعضِ الخُضَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4969, 'مُثَقَّفٌ', 'مثقف', 'اسم مفعول', 'ثقف', 'مثقف', 'مثقف', 'مفع. مِنْ ثَقَّفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ ثَقَّفَ). 1.""رَجُلٌ مُثَقَّفٌ"" : مُتَعَلِّمٌ، مَنْ لَهُ مَعْرِفَةٌ بِالْمَعَارِفِ، أَيْ ذُو ثَقَافَةٍ. 2.""النُّخْبَةُ الْمُثَقَّفَةُ"" : نُخْبَةٌ مِنْ أَهْلِ الفِكْرِ وَالثَّقَافَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4970, 'مُثَلَّثٌ', 'مثلث', 'اسم مفعول', 'ثلث', 'مثلث', 'مثلث', 'مفع. مِنْ ثَلَّثَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ ثَلَّثَ). 1.""حَرْفمُثَلَّثٌ"" : ذُو ثَلاَثِ نُقَـطٍ أَوْ ثَـلاَثِ حَرَكَـاتٍ.2.""شَكْلٌ مُغْلَقٌ يُحِيطُ بِهِ ثَلاَثَةُ أَضْلاَعٍ: ""مُثلَّثٌ مُخْتَلِفُ الأَضْلاَعِ"" ""مُثَلَّثٌ مُتَسَاوِي السَّاقَيْنِ"". 3.""عِلْـمُ حِسَـابِ الْمُثَلَّثَاتِ"" : فَرْعٌ مِنَ الرِّيَاضِيَّاتِ يَبْحَثُ العَلاَقَاتِ بَيْنَ أَضْلاَعِ الْمُثَلَّثَاتِ وَزَوَايَاهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4971, 'مُثَلَّجٌ', 'مثلج', 'اسم مفعول', 'ثلج', 'مثلج', 'مثلج', 'مفع. مِنْ ثَلَّجَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ ثَلَّجَ). 1.""مَاءٌ مُثَلَّجٌ"" : بَارِدٌ جِدّاً كَالثَّلْجِ. 2.""لَحْمٌ مُثَلَّجٌ"" : مُجَمَّدٌ. 3.""مُثَلَّجَاتٌ لَذِ"', '');
