INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4990, 'مُجَرَّدٌ', 'مجرد', 'اسم مفعول', 'جرد', 'مجرد', 'مجرد', 'مفع. مِنْ جَرَّدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ جَرَّدَ). 1.""وَجَدَهُ مُجَرَّداً مِنْ ثِيَابِهِ"" : عَارِياً. 2.""مُجَرَّدٌ مِنْ كُلِّ حُقُوقِهِ"" : الَّذِي انْتُزِعَتْ مِنْهُ حُقُوقُهُ. 3.""يَتَحَدَّثُ فِي الْمُجَرَّدِ"": فِي الْمُطْلَقِ. 4.""مُجَرَّدٌ عَنِ الأَفْكَارِ الْمُسْبَقَةِ"" : مُحَرَّرٌ، بَعِيدٌ عَنْهَا. ""مُجَرَّدُونَ عَنْ كُلِّ غايَةٍ"". 5.""بِمُجَرَّدِ وُصُولِهِ أَخْبَرَ"', '');
