INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4994, 'مُجَسَّمٌ', 'مجسم', 'اسم مفعول', 'جسم', 'مجسم', 'مجسم', 'مفع. مِنْ جَسَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ جَسَّمَ). ""تِمْثَالٌ مُجَسَّمٌ"" : مُشَخَّصٌ، مُجَسَّدٌ، أَيْ كُل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4995, 'مُجَعَّدٌ', 'مجعد', 'اسم مفعول', 'جعد', 'مجعد', 'مجعد', 'مفع. مِنْ جَعَّدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ جَعَّدَ). 1.""ثَوْبٌ مُجَعَّدٌ"" : مُتَقَبِّضٌ، مُلْتَوٍ. ""ش"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4996, 'مُجَفَّفٌ', 'مجفف', 'اسم مفعول', 'جفف', 'مجفف', 'مجف', 'مفع. مِنْ جَفَّفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ جَفَّفَ). 1.""عِنَبٌ مُجَفَّفٌ"" : يَابِسٌ. 2.""الْمُجَفَّفَاتُ"" : الثِّمَارُ وَالخُضَرُ الَّتِي تُجَفَّفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4997, 'مُجَلْجَلٌ', 'مجلجل', 'اسم مفعول', 'جلجل', 'مجلجل', 'مجلجل', 'مفع. مِنْ جَلْجَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ جَلْجَلَ). ""رَجُلٌ مُجَلْجَلٌ"" : رَجُلٌ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4998, 'مُجَلَّدٌ', 'مجلد', 'اسم مفعول', 'جلد', 'مجلد', 'مجلد', 'مفع. مِنْ جَلَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ جَلَّدَ). 1.""كِتَابٌ مُجَلَّدُ"" : الكِتَابُ الَّذِي تَمَّ تَجْلِيدُهُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(4999, 'مُجَمَّدٌ', 'مجمد', 'اسم مفعول', 'جمد', 'مجمد', 'مجمد', 'مفع. مِنْ جَمَّدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ جَمَّدَ). 1. ""مَاءٌ مُجَمَّدٌ"" : مَاءٌ صَارَ جَلِيداً. 2. ""بَقِيَ فِي مَكَانِهِ مُجَمَّداً"" : ثَابِتاً لاَ يَتَحَرَّكُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5000, 'مُجَمَّرٌ', 'مجمر', 'اسم مفعول', 'جمر', 'مجمر', 'مجمر', 'مفع. مِنْ جَمَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَمَّرٌ-مُجَمَّرٌ [ج م ر] (مفع. مِنْ جَمَّرَ). ""خُبْزٌ مُجَمَّرٌ"" : أَيْ مُحَمَّرٌ نَتِيجَةَ وَضْعِهِ عَلَى الجَمْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5001, 'مُجَمَّعٌ', 'مجمع', 'اسم مفعول', 'جمع', 'مجمع', 'مجمع', 'مفع. مِنْ جَمَّعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ جَمَّعَ). 1.""مُجَمَّعُ الصِّنَاعَةِ التَّقْلِيدِيَّةِ"" : مَبْنـىً بِهِ عَدَدٌ مِنَ الصُّنَّاعِ يَشْتَغِلُونَ و"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5002, 'مُجَنَّحٌ', 'مجنح', 'اسم مفعول', 'جنح', 'مجنح', 'مجنح', 'مفع. مِنْ جَنَّحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ جَنَّحَ). 1.""طَائِرٌ مُجَنَّحٌ"" : لَهُ جَنَاحَانِ. 2.""خَيَالٌ مُجَنَّحٌ"" : أَيْ يَذْهَبُ بَعِيداً. 3.""حَيَوَانٌ مِنْ مُجَنَّحَاتِ الأَرْجُلِ"" : رُتْبَةٌ مِنَ الرِّخَوِيَّاتِ الْمَعِدِيَّةِ تَتَمَيَّزُ بِأَرْجُلِهَا الْمُجَنَّحَةِ. 4.""حَيَوَانٌ مِنْ مُجَنَّحَاتِ الأَيْدِي"" : رُتْبَةٌ مِنَ الْحَيَوَانَاتِ اللَّبُونَةِ الرَّوَامِسِ، مُتَمَيِّزَةٌ بِغِلاَفٍ جِلْدِيٍّ يَكْتَنِفُ قَوَائِمَهَا وَيُمَكِّنُهَا مِنَ الطَّيَرَانِ، مِنْهَا الوَطْوَاطِيَّاتُ وَالْخُفَّاشِيَّاتُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5003, 'مَجْنِيٌّ', 'مجني', 'اسم مفعول', 'جني', 'مجني', 'مجن', 'مفع. مِنْ جَنَى', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَجْنِيٌّ-مَجْنِيٌّ، ةٌ [ج ن ي] (مفع. مِنْ جَنَى). ""شَابٌّ مَجْنِيٌّ عَلَيْهِ"" : ضَحِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5004, 'مَجْهُودٌ', 'مجهود', 'اسم مفعول', 'جهد', 'مجهود', 'مجهد', 'مفع. مِنْ جَهَدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ جَهَدَ). ""قَامَ بِمَجْهُودٍ جَبَّارٍ"" : الجُهْدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5005, 'مُجَهَّزٌ', 'مجهز', 'اسم مفعول', 'جهز', 'مجهز', 'مجهز', 'مفع. مِنْ جَهَّزَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ جَهَّزَ). ""مُخْتَبَرٌ مُجَهَّزٌ بِأَحْدَثِ الآلاَتِ"" : مُزَوَّدٌ بِـ... ""مَدْرَسَةٌ مُجَهَّزَةٌ بِكُلِّ الأَدَوَاتِ اللاَّزِمَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5006, 'مَجْهُولٌ', 'مجهول', 'اسم مفعول', 'جهل', 'مجهول', 'مجهل', 'مفع. مِنْ جَهِلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَجَاهِيلُ"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ جَهِلَ). 1.""رَجُلٌ مَجْهُولُ العُنْوَانِ"" : أَيْ عُنْوَانُهُ غَيْرُ مَعْلُومٍ، غَيْرُ مَعْرُوفٍ. "" لَقَدْ دُفِنَ صَدِيقُهُ بِتِلْكَ الأَرَاضِي الْمَجْهُولَةِ"". (غسان كنفاني). 2.""الجُنْدِيُّ الْمَجْهُولُ"" : نَصْبٌ تَذْكَارِيٌّ يُقَامُ لِجُنْدِيٍّ قُتِلَ في حَرْبٍ وَلَمْ تُعْرَفْ هُوِيَّتُهُ وَيَظَلُّ رَمْزاً لِكُلِّ الجُنُودِ مِنْ أَمْثَالِهِ. 3.""فِعْلٌ مَبْنِيٌّ لِلْمَجْهُولِ"" (نح) : وَهُوَ مَا جُهِلَ فَاعِلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5007, 'مَجَاهِيلُ', 'مجاهيل', 'اسم مفعول', '', 'مجاهيل', 'مجهل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5008, 'مُجَوَّفٌ', 'مجوف', 'اسم مفعول', 'جوف', 'مجوف', 'مجف', 'مفع. مِنْ جَوَّفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ جَوَّفَ). 1.""جِهَازٌ مُجَوَّفٌ"" : لَهُ جَوْفٌ أَوْ تَجَاوِيفُ. 2.""رَجُلٌ مُجَوَّفٌ"" : جَبَانٌ لاَ قَلْبَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5009, 'مُجَيَّرٌ', 'مجير', 'اسم مفعول', 'جير', 'مجير', 'مجر', 'مفع. مِنْ جَيَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَيَّرٌ-مُجَيَّرٌ، ةٌ [ج ي ر] (مفع. مِنْ جَيَّرَ). ""جِدَارٌ مُجَيَّرٌ"": جِدَارٌ مُجَصَّصٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5010, 'مُحَاصَرٌ', 'محاصر', 'اسم مفعول', 'حصر', 'محاصر', 'محصر', 'مفع. مِنْ حَاصَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَاصَرَ). ""مُحَاصَرٌ مِنْ كُلِّ جِهَةٍ"" : مُحَاطٌ. ""ظَلَّتِ القَرْيَةُ مُحَاصَرَةً عِدَّةَ أَيَّامٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5011, 'مَحْبُوبٌ', 'محبوب', 'اسم مفعول', 'حبب', 'محبوب', 'محبب', 'مفع. مِنْ حَبَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَبَّ). ""صَارَ مَحْبُوباً"" : صَارَ قَرِيباً عِنْدَ النَّاسِ يَوَدُّونَهُ وَيُحِبُّونَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5012, 'مُحَبَّبٌ', 'محبب', 'اسم مفعول', 'حبب', 'محبب', 'محب', 'مفع. مِنْ حَبَّبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَبَّبَ). ""مُحَبَّبٌ إِلَى النُّفُوسِ"" : مَنْ تَمِيلُ إِلَيْهِ النُّفُوسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5013, 'مُحَبَّرٌ', 'محبر', 'اسم مفعول', 'حبر', 'محبر', 'محبر', 'مفع. مِن حَبَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَبَّرٌ-مُحَبَّرٌ، ةٌ [ح ب ر] (مفع. مِن حَبَّرَ). 1.""ثَوْبٌ مُحَبَّرٌ"": مُخَطَّطٌ. 2.""حَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5014, 'مَحْبُوسٌ', 'محبوس', 'اسم مفعول', 'حبس', 'محبوس', 'محبس', 'مفع. مِنْ حَبَسَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَبَسَ). ""مَحْبُوسٌ فِي زِنْزَانَةٍ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5015, 'مَحْبُوكٌ', 'محبوك', 'اسم مفعول', 'حبك', 'محبوك', 'محبك', 'مفع. مِنْ حَبَكَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَبَكَ). ""عَمَلٌ مَحْبُوكٌ"" : مُتْقَنٌ، أَيْ كَأَنَّهُ نُسِجَ نَسْجاً مُحْكَماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5016, 'مَحْتُومٌ', 'محتوم', 'اسم مفعول', 'حتم', 'محتوم', 'محتم', 'مفع. مِنْ حَتَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مَحْتُومٌ-مَحْتُومٌ [ح ت م] (مفع. مِنْ حَتَمَ). ""أَمْرٌ مَحْتُومٌ"" : مُقَدَّرٌ، لاَ بُدَّ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5017, 'مُحَجَّبٌ', 'محجب', 'اسم مفعول', 'حجب', 'محجب', 'محجب', 'مفع. مِنْ حَجَّبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَجَّبَ). ""اِمْرَأَةٌ مُحَجَّبَةٌ"" : مُسْتَتِرَةٌ بِحِجَابٍ. ""جَلَسَتِ امْرَأَةٌ مُحَجَّبَةٌ بِجَانِبِ امْرَأَةٍ سَافِرَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5018, 'مَحْجُوبٌ', 'محجوب', 'اسم مفعول', 'حجب', 'محجوب', 'محجب', 'مفع. مِنْ حَجَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَجَبَ). 1.""مَحْجُوبٌ عَنِ الأَنْظَارِ"" : مَسْتُورٌ. ""كُلُّ مَحْجُوبٍ مَرْغُوبٌ"". 2.""مَحْجُوبٌ"" : اِسْمُ عَلَمٍ لِلْمُذَكَّرِ، وَ""مَحْجُوبَة"" : اِسْمُ عَلَمٍ لِلإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5019, 'مَحْجُورٌ', 'محجور', 'اسم مفعول', 'حجر', 'محجور', 'محجر', 'مفع. مِنْ حَجَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَجَرَ). ""وَلَدٌ مَحْجُورٌ"" : وَلَدٌ مَمْنُوعٌ مِنَ التَّصَرُّفِ بِمُمْتَلَكَاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5020, 'مَحْجُوزٌ', 'محجوز', 'اسم مفعول', 'حجز', 'محجوز', 'محجز', 'مفع. مِنْ حَجَزَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَجَزَ). 1.""مَقْعَدٌ مَحْجُوزٌ"" : مَأْخُوذٌ لِغَيْرِكَ. 2.""أَثَاثٌ مَحْجُوزٌ"" : مُصَادَرٌ. ""بَضَائِعُ مَحْجُوزَةٌ"". 3.""مَحْجُوزٌ عَلَيْهِ"" (قا) : الْمَدِينُ الَّذِي يُوقَعُ الْحَجْزُ عَلَى مَالِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5021, 'مُحَجَّلٌ', 'محجل', 'اسم مفعول', 'حجل', 'محجل', 'محجل', 'مفع. مِن حَجَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَجَّلٌ-مُحَجَّلٌ [ح ج ل] (مفع. مِن حَجَّلَ). ""الْمُحَجَّلُ مِنَ الخَيْلِ"" : مَا كَانَ فيِ قَوَائِمِهِ بَيَاضٌ. غُرٌّ مُحَجَّلونَ (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5022, 'مَحْدُودٌ', 'محدود', 'اسم مفعول', 'حدد', 'محدود', 'محدد', 'مفع. مِنْ حَدَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ حَدَّ). 1.""فِي إِطَارٍ مَحْدُوٍد"" : أَيْ إِطَارٍ مُحَدَّدٍ مُحَاطٍ. 2.""مَوَارِدُهُ مَحْدُودَةٌ"" : ضَعِيفَةٌ، قَلِيلَةٌ. 3.""مَحْدُودُ التَّفْكِيرِ"" : ضَيِّقُ التَّفْكِيرِ، قَاصِرُهُ، مَحْصُورٌ. ""كَانَ عَقْلُهُ مَحْدُوداً"" ""مَحْدُودُ الْمَدَى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5023, 'مُحَدَّبٌ', 'محدب', 'اسم مفعول', 'حدب', 'محدب', 'محدب', 'مفع. مِنْ حَدَّبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَدَّبَ). 1.""خَطٌّ مُحَدَّبٌ"" : مُقَوَّسٌ. 2.""ظَهْرٌ مُحَدَّبٌ"" : بِهِ حَدَبَةٌ. 3.""أَنْفٌ مُحَدَّبٌ"" : أَرْنَبَتُهُ مُلْتَوِيَةٌ إِلَى أَعْلَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5024, 'مُحَدَّدٌ', 'محدد', 'اسم مفعول', 'حدد', 'محدد', 'محد', 'مفع. مِنْ حَدَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مُحَدِّدٌ-مُحَدِّدٌ، ةٌ [ح د د] (فَا. مِنْ حَدَّدَ). ""مُحَدِّدٌ لِمَا يَنْبَغِي أَنْ يَكُونَ"" : مُعَيِّنٌ، مُخَصِّصٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5025, 'مَحْذُوفٌ', 'محذوف', 'اسم مفعول', 'حذف', 'محذوف', 'محذف', 'مفع. مِنْ حَذَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَذَفَ). ""عِبَارَةٌ مَحْذُوفَةٌ مِنَ النَّصِّ"" : سَاقِطَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5026, 'مَحْرُورٌ', 'محرور', 'اسم مفعول', 'حرر', 'محرور', 'محرر', 'مفع. مِنْ حَرَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَرَّ). 1. ""وَلَدٌ مَحْرُورٌ"" : مَنْ أَصَابَتْهُ حَرَارَةُ الْحَرِّ. 2.""رَجُلٌ مَحْرُورٌ"" : مُهَيَّجٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5027, 'مُحَرَّرٌ', 'محرر', 'اسم مفعول', 'حرر', 'محرر', 'محر', 'مفع. مِنْ حَرَّرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَرَّرَ). 1.""مُحَرَّرٌ مِنْ كُلِّ عُبُودِيَّةٍ"" : مُعْتَقٌ. 2.""أَرْضٌ مُحَرَّرَةٌ"" : تَمَّ تَحْرِيرُهَا مِنَ الاِحْتِلاَلِ. 3.""مَقَالٌ مُحَرَّرٌ"" : مَكْتُوبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5028, 'مَحْرُوسٌ', 'محروس', 'اسم مفعول', 'حرس', 'محروس', 'محرس', 'مفع. مِنْ حَرَسَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَرَسَ). 1.""بَيْتٌ مَحْرُوسٌ"" : عَلَيْهِ حِرَاسَةٌ. 2.""فَتَاةٌ مَحْرُوسَةٌ"": مَصونَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5029, 'مَحْرُوقٌ', 'محروق', 'اسم مفعول', 'حرق', 'محروق', 'محرق', 'مفع. مِنْ حَرَقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ حَرَقَ). 1.""وَجْهٌ مَحْرُوقٌ"" : مُصَابٌ بِإِحْرِاقٍ. "" مَحْرُوقُ الوَجْهِ وَاليَدَيْنِ، مُرَقَّعُ القُفَّةِ وَالثِّيَابِ"". (عبد الرفيع جواهري). 2.""الْمَحْرُوقَاتُ"" : كُلُّ مَا هُوَ قَابِلٌ لِلاِحْتِرَاقِ كَالبِنْزِينِ وَالْمَازُوتِ. ""رَائِحَةُ الْحَطَبِ الْمَحْرُوقِ الرَّطْبِ تَمْلَأُ الرِّئَاتِ"" (ع. منيف)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5030, 'مُحَرَّمٌ', 'محرم', 'اسم مفعول', 'حرم', 'محرم', 'محرم', 'مفع. مِنْ حَرَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَرَّمَ). 1.""هُوَ مُحَرَّمٌ"" : ذُو حُرْمَةٍ. 2.""جِلْدٌ مُحَرَّمٌ"" : لَمْ يُدْبَغْ. 3.""مَسُّها مُحَرَّمٌ عَلَيْهِ"" : الاقْتِرَابُ مِنْهَا مَمْنُوعٌ عَلَيْهِ. 4.: الشَّهْرُ الأَوَّلُ مِنْ شُهُورِ السَّنَةِ القَمَرِيَّةِ، عَدَدُ أَيَّامِهِ (30) يَوْماً، سُمِّيَ بِذَلِكَ لِأَنَّ العَرَبَ كَانُوا يُحَرِّمُونَ القِتَالَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5031, 'مَحْرُومٌ', 'محروم', 'اسم مفعول', 'حرم', 'محروم', 'محرم', 'مفع. مِنْ حَرَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ حَرَمَ). ""مَحْرُومٌ مِنْ كُلِّ شَيْءٍ"" : الَّذِي لاَ يَسْتَطِيعُ الوُصُولَ إِلَى مَا يُرِيدُهُ وَيَشْتَهِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5032, 'مَحْزُونٌ', 'محزون', 'اسم مفعول', 'حزن', 'محزون', 'محزن', 'مفع. مِنْ حَزَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَزَنَ). ""رَجُلٌ مَحْزُونٌ"" : بِهِ حُزْنٌ وَهَمٌّ وَغَمٌّ. ""فَلْتَكُنْ أَيُّهَا الْمَحْزُونُ أَكْبَرَ مِنْ هُمُومِكَ وَأَحْزَانِكَ"". (م. ص. الرافعي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5033, 'مَحْسُوسٌ', 'محسوس', 'اسم مفعول', 'حسس', 'محسوس', 'محسس', 'مفع. مِنْ حَسَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَسَّ). 1.: كُلُّ مَا هُوَ مُدْرَكٌ بِإِحْدَى الْحَوَاسِّ الخَمْسِ"". 2.""حَجَرٌ مَحْسُوسٌ"" : مَلْمُوسٌ. ""وَاقِعٌ مَحْسُوسٌ"" ""صُورَةٌ مَحْسُوسَةٌ"". 3.""تَقَدُّمٌ مَحْسُوسٌ"" : وَاضِحٌ، يُمْكِنُ مُشَاهَدَتُهُ بِالعَيْنِ الْمُجَرَّدَةِ وَلَمْسُهُ بِاليَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5034, 'مَحْسُوبٌ', 'محسوب', 'اسم مفعول', 'حسب', 'محسوب', 'محسب', 'مفع. مِنْ حَسَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَحَاسِيبُ"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَسَبَ). 1.""عَمَلٌ مَحْسُوبٌ"": عَمَلٌ مُدَقَّقٌ، مُحْتَاطٌ فِيهِ. ""يَخْطُو خَطَوَاتٍ مَحْسُوبَةً"". 2.""هُوَ مَحْسُوبٌ عَلَيْهِ"" : أَيْ هُوَ مِنْ جَمَاعَتِهِ وَمَسْؤُولِيَّتِهِ. 3."" أَنْفَاسُهُ مَحْسُوبَةٌ عَلَيْهِ"" : أَيْ هُوَ فِي مَوْقِعِ الرَّقَابَةِ وَأَنْفَاسُهُ مُحْصَاةٌ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5035, 'مَحَاسِيبُ', 'محاسيب', 'اسم مفعول', '', 'محاسيب', 'محسب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5036, 'مَحْسُودٌ', 'محسود', 'اسم مفعول', 'حسد', 'محسود', 'محسد', 'مفع. مِنْ حَسَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَسَدَ). ""رَجُلٌ مَحْسُودٌ مِنْ أَقْرِبَائِهِ"" : أَيْ يَتَمَنَّوْنَ أَنْ تَتَحَوَّلَ إِلَيْهِمْ نِعْمَتُهُ أَوْ أَنْ يَسْلُبهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5037, 'مَحْسُومٌ', 'محسوم', 'اسم مفعول', 'حسم', 'محسوم', 'محسم', 'مفع. مِنْ حَسَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَحْسُومٌ-مَحْسُومٌ، ةٌ [ح س م] (مفع. مِنْ حَسَمَ). 1.""مَبْلَغٌ مَحْسُومٌ مِنْهُ 10% "" : مَأْخُوذٌ مِنْهُ... 2.""حُكْمٌ مَحْسُومٌ فيِ أَمْرِهِ"" : نِهَائِيٌّ لاَ رِجْعَةَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5038, 'مُحَشّىً', 'محشى', 'اسم مفعول', 'حشي', 'محشى', 'محش', 'مفع. مِنْ حَشَّى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"مُحَشّىً-مُحَشّىً [ح ش ي] (مفع. مِنْ حَشَّى). ""كِتَابٌ مُحَشّىً"" : مُعَلَّقٌ عَلَيْهِ فِي الْحَوَاشِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5039, 'مُحَشّاة', 'محشاة', 'اسم مفعول', '', 'محشاة', 'محشة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَشّىً-مُحَشّىً [ح ش ي] (مفع. مِنْ حَشَّى). ""كِتَابٌ مُحَشّىً"" : مُعَلَّقٌ عَلَيْهِ فِي الْحَوَاشِي."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5040, 'مَحْصُورٌ', 'محصور', 'اسم مفعول', 'حصر', 'محصور', 'محصر', 'مفع. مِنْ حَصَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَصَرَ). ""مَحْصُورٌ فِي بَيْتِهِ"" : مُحَاطٌ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5041, 'مَحْصُولٌ', 'محصول', 'اسم مفعول', 'حصل', 'محصول', 'محصل', 'مفع. مِنْ حَصَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مَحَاصِيلُ"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَصَلَ). 1.""مَحْصُولُ الكَلاَمِ"" : مَفَادُهُ، مَعْنَاهُ. 2.""مَحَاصِيلُ الأَرْضِ"" : غَلاَّتُهَا، نِتاجُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5042, 'مَحَاصِيلُ', 'محاصيل', 'اسم مفعول', '', 'محاصيل', 'محصل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5043, 'مُحَصَّنٌ', 'محصن', 'اسم مفعول', 'حصن', 'محصن', 'محصن', 'مفع. مِنْ حَصَّنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُحَصَّنٌ-مُحَصَّنٌ، ةٌ [ح ص ن] (مفع. مِنْ حَصَّنَ). ""مُعَسْكَرٌ مُحَصَّنٌ"" : مَحْمِيٌّ، مَصونٌ.الحشر آية 14 وَلاَ يُقَاتِلُونَكُمْ جَمِيعاً إِلاَّ فِي قُرىً مُحَصَّنَةٍ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5044, 'مُحَطَّمٌ', 'محطم', 'اسم مفعول', 'حطم', 'محطم', 'محطم', 'مفع. مِنْ حَطَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ حَطَّمَ). 1.""وَصَلَ القَرْيَةَ مُحَطَّمَ القُوَى"" : مُنْهَاراً، أَيْ لاَ يَمْلِكُ قُوَّةً. "" مُحَطَّمُ الأَعْصَابِ"". 2.""شَابٌّ مُحَطَّمٌ"" : يَائِسٌ، فَاقِدُ الأَمَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5045, 'مَحْظُوظٌ', 'محظوظ', 'اسم مفعول', 'حظظ', 'محظوظ', 'محظظ', 'مفع. مِنْ حَظَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ حَظَّ). ""مَحْظُوظٌ فِي عَمَلِهِ"" : مَنْ كَانَ ذَا حَظٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5046, 'مَحْظُورٌ', 'محظور', 'اسم مفعول', 'حظر', 'محظور', 'محظر', 'مفع. مِنْ حَظَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَظَرَ). ""عَمَلٌ مَحْظُورٌ"" : القِيَامُ بِهِ مَمْنُوعٌ، مُحَرَّمٌ. ""الضَّرُورَاتُ تُبِيحُ الْمَحْظُورَاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5047, 'مَحْفُوفٌ', 'محفوف', 'اسم مفعول', 'حفف', 'محفوف', 'محفف', 'مفع. مِنْ حَفَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَفَّ). ""طَرِيقٌ مَحْفُوفٌ بِالْمَخَاطِرِ"" : مُحاطٌ بِها. ""تَصَاعَدَتْ مِنْ وَادِي النِّيلِ حُورِيَّةٌ مَحْفُوفَةٌ بِأَجْنِحَةٍ"".(جبران خ. جبران)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5048, 'مَحْفُورٌ', 'محفور', 'اسم مفعول', 'حفر', 'محفور', 'محفر', 'مفع. مِنْ حَفَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مَحْفُورٌ-مَحْفُورٌ [ح ف ر] (مفع. مِنْ حَفَرَ). ""بِئْرٌ مَحْفُورَةٌ مُنْذُ زَمَنٍ طَوِيلٍ"" : أَيْ تَمَّ حَفْرُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5049, 'مَحْفُوظٌ', 'محفوظ', 'اسم مفعول', 'حفظ', 'محفوظ', 'محفظ', 'مفع. مِنْ حَفِظَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَفِظَ). 1.""طَعَامٌ مَحْفُوظٌ"" : مَصُونٌ. 2.""دَرْسٌ مَحْفُوظٌ"" : حُفِظَ عَنْ ظَهْرِ قَلْبٍ . 3.""جَمِيعُ الْحُقُوقِ مَحْفُوظَةٌ"" : عِبَارَةٌ تُثْبَتُ فِي صَفْحَةٍ دَاخِلِيَّةٍ مِنَ الكِتَابِ تُؤَكِّدُ عَلَى أَنَّ حُقُوقَ طَبْعِهِ وَنَشْرِهِ تَعُودُ إِلَى النَّاشِرِ أَوِ الْمُؤَلِّفِ. 4.""الشِّعْرُ القَدِيمُ مِنْ مَحْفُوظَاتِهِ"" : مَا يُحْفَظُ مِنَ النُّصُوصِ الأَدَبِيَّةِ. ""حِصَّةُ الْمَحْفُوظَاتِ"" ""رَجُلٌ كَثِيرُ الْمَحْفُوظِ حَاضِرُ الجَوَابِ فَصِيحُ اللِّسَانِ"". 5.""مَحْفُوظَاتُ قِسْمِ الوَثَائِقِ"" : مَا يُوجَدُ بِهِ مِنْ وَثَائِقَ وَسِجِلاَّتٍ وَمَحْفُوظَاتٍ قَدِيمَةٍ أَوْ حَدِيثَةٍ. 6.""الْمَحْفُوظَاتُ مِنَ الْمَأْكُولاَتِ"" : الْمَوَادُّ الغِذَائِيَّةُ الْمَصُونَةُ فِي عُلَبٍ لِمُدَّةٍ طَوِيلَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5050, 'مُحَقَّقٌ', 'محقق', 'اسم مفعول', 'حقق', 'محقق', 'محق', 'مفع. مِنْ حَقَّقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"مُحَقَّقٌ-مُحَقَّقٌ، ةٌ [ح ق ق] (مفع. مِنْ حَقَّقَ). 1.""مَشْرُوعٌ مُحَقَّقٌ"" : أَكِيدٌ، ثَابِتٌ. ""خَطَرٌ مُحَقَّقٌ"" ""نَجا مِنْ مَوْتٍ مُحَقَّقٍ"". 2.""مِنَ الْمُحَقَّقِ أَنْ يُنْجِزَ مُهِمَّتَهُ"" : مِنَ الْمُؤَكَّدِ. 3.""كَلاَمٌ مُحَقَّقٌ"" : مُحْكَمٌ، مُنَظَّمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5051, 'مُحَكَّمٌ', 'محكم', 'اسم مفعول', 'حكم', 'محكم', 'محكم', 'مفع. مِنْ حَكَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَكَّمَ). ""عَادُوا إِلَى الْمُحَكَّمِ لِيَفْصِلَ فِي خِلاَفِهِمْ"" : الْحَكَمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5052, 'مَحْكُومٌ', 'محكوم', 'اسم مفعول', 'حكم', 'محكوم', 'محكم', 'مفع. مِنْ حَكَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ حَكَمَ). 1.""مَحْكُومٌ عَلَيْهِ بِشَهْرٍ سِجْناً"" : مَنْ حُكِمَ عَلَيْهِ. 2.""مَحْكُومٌ عَلَيْهِ بِالفَشَلِ"" : مَصِيرُهُ الفَشَلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5053, 'مَحْلُولٌ', 'محلول', 'اسم مفعول', 'حلل', 'محلول', 'محلل', 'مفع. مِنْ حَلَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات:مَحَاليلُ"', '', '', '', '', '', '', '', '', '"مَحْلُولٌ-مَحْلُولٌ، ةٌ [ح ل ل] (مفع. مِنْ حَلَّ). 1.""حِزَامٌ مَحْلُولٌ"" : مَفْكُوكٌ. 2.""عُقْدَةٌ مَحْلُولَةٌ"" : عُقْدَةٌ فُكَّتْ، مَفْكُوكَةٌ. 3.""مَسْأَلَةٌ مَحْلُولَةٌ"" : مَسْأَلَةٌ حُلَّتْ، وُجِدَ لَهَا حَلٌّ. 4.""تَنَاوَلَ مَحْلُولاً"" : سَائِلاً يَحْتَوِي عَلَى جُرْمٍ مُذَابٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5054, 'مَحَاليلُ', 'محاليل', 'اسم مفعول', '', 'محاليل', 'محلل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5055, 'مَحْلُوجٌ', 'محلوج', 'اسم مفعول', 'حلج', 'محلوج', 'محلج', 'مفع. مِنْ حَلَجَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَحْلُوجٌ-مَحْلُوجٌ [ح ل ج] (مفع. مِنْ حَلَجَ). ""قُطْنٌ مَحْلُوجٌ"": قُطْنٌ انْتُهِيَ مِنْ حَلْجِهِ وَنَدْفِهِ، مَنْدُوفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5056, 'مُحَلَّفٌ', 'محلف', 'اسم مفعول', 'حلف', 'محلف', 'محلف', 'مفع. مِنْ حَلَّفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ حَلَّفَ). 1.: مَنْ أَقْسَمَ في الْمَحْكَمَةِ فِي شَأْنِ مَوْضُوعٍ أَوْ مِهْنَةٍ لِيُصْبِحَ بَعْدَ ذَلِكَ مَوْثُوقاً بِهِ. ""مُتَرْجِمٌ مُحَلَّفٌ"" ""خَبِيرٌ مُحَلَّفٌ"". 2.""هَيْئَةُ الْمُحَلَّفِينَ"" : قَضَاءٌ فِي بَعْضِ البُلْدَانِ مُكَوَّنٌ مِنْ أَعْضَاءٍ أَدَّوْا القَسَمَ عَلَى تَحَرِّي الْحَقِيقَةِ وَإِصْدَارِ الْحُكْمِ الصَّحِيحِ عِنْدَمَا يَمْثُلُ أَمَامَهُمُ الْمُتَّهَمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5057, 'مَحْمُومٌ', 'محموم', 'اسم مفعول', 'حمم', 'محموم', 'محمم', 'مفع. مِنْ حَمَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَحْمُومٌ-مَحْمُومٌ [ح م م] (مفع. مِنْ حَمَّ). ""وَلَدٌ مَحْمُومٌ"" : مُصَابٌ بِالْحُمَّى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5058, 'مُحَمَّدٌ', 'محمد', 'اسم مفعول', 'حمد', 'محمد', 'محمد', 'مفع. مِنْ حَمَّدَ', '', '', 'مفرد', 'DnN', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"مُحَمَّدٌ-مُحَمَّدٌ [ح م د] (مفع. مِنْ حَمَّدَ). 1.""رَجُلٌ مُحَمَّدٌ"": كَثِيُر الخِصَالِ الْحَمِيدَةِ. 2.""مُحَمَّدٌ"" : اِسْمُ عَلَمٍ وَهُوَ اسْمُ النَّبِيِّ العَرَبِيِّ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5059, 'مَحْمُودٌ', 'محمود', 'اسم مفعول', 'حمد', 'محمود', 'محمد', 'مفع. مِنْ حَمِدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَمِدَ). 1.""قَامَ بِعَمَلٍ مَحْمُودٍ"" : بِعَمَلٍ يُحْمَدُ عَلَيْهِ، حَسَنٌ. ""الابْتِدَاءُ مَحْمُودٌ وَالعَوْدُ أَحْمَدُ"". 2.""مَحْمُودٌ"" : اِسْمُ عَلَمٍ لِلْمُذَكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5060, 'مَحْمُولٌ', 'محمول', 'اسم مفعول', 'حمل', 'محمول', 'محمل', 'مفع. مِنْ حَمَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَحْمُولٌ-مَحْمُولٌ [ح م ل] (مفع. مِنْ حَمَلَ). ""جِيءَ بِهِ مَحْمُولاً عَلَى الأَكْتَافِ"" : مَرْفُوعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5061, 'مَحْمِيٌّ', 'محمي', 'اسم مفعول', 'حمي', 'محمي', 'محم', 'مفع. مِنْ حَمَى', '', 'ة', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَمَى). 1.""رَجُلٌ مَحْمِيٌّ لاَ خَوْفَ عَلَيْهِ"" : يُوجَدُ تَحْتَ الحِمَايَةِ. 2.""بَلَدٌ مَحْمِيٌّ"" : خَاضِعٌ لِنِظَامِ الحِمَايَةِ. 3.""مِنْطَقَةٌ مَحْمِيَّةٌ"" : مِنْطَقَةٌ وَاقِعَةٌ تَحْتَ حِمَايَةِ سُلْطَةٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5062, 'مُحَنَّكٌ', 'محنك', 'اسم مفعول', 'حنك', 'محنك', 'محنك', 'مفع. مِنْ حَنَّكَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُحَنَّكٌ-مُحَنَّكٌ [ح ن ك] (مفع. مِنْ حَنَّكَ). ""رَجُلٌ مُحَنَّكٌ"": مَنْ حَنَّكَتْهُ التَّجَارِبُ وَجَعَلَتْهُ خَبِيراً وَحَكِيماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5063, 'مُحَيَّرٌ', 'محير', 'اسم مفعول', 'حير', 'محير', 'محر', 'مفع. مِنْ حَيَّرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ حَيَّرَ). ""مُحَيَّرٌ فِي أَمْرِهِ"" : مُضْطَرِبٌ، مُتَرَدِّدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5064, 'مُخَاطَبٌ', 'مخاطب', 'اسم مفعول', 'خطب', 'مخاطب', 'مخطب', 'مفع. مِنْ خَاطَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ خَاطَبَ). 1.""وَجَدَ مُخَاطَباً يَفْهَمُ رَأْيَهُ"" : مَنْ تَتَوَجَّهُ إِلَيْهِ بِالخِطَابِ. 2.""ضَمِيرُ الْمُخَاطَبِ"" : ضَمِيرُ الخِطَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5065, 'مَخُوفٌ', 'مخوف', 'اسم مفعول', 'خوف', 'مخوف', 'مخف', 'مفع. مِنْ خَافَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَخُوفٌ-مَخُوفٌ [خ و ف] (مفع. مِنْ خَافَ). 1.""رَجُلٌ مَخُوفٌ"" : مَا، مَنْ يُخَافُ مِنْهُ، خَطِيرٌ. 2.""طَرِيقٌ مَخُوفٌ"" : مُثِيرٌ لِلْخَوْفِ وَالفَزَعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5066, 'مَخْبُوءٌ', 'مخبوء', 'اسم مفعول', 'خبأ', 'مخبوء', 'مخب', 'مفع. مِنْ خَبَّأَ', '', '', 'مفرد', 'Dz', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَبَّأَ). ""مَخْبُوءٌ فِي جُحْرِهِ"" : مَسْتُورٌ. ""كَشَفَتْ مَسْتُورًا وَأَظْهَرَتْ مَخْبُوءاً"". (إسحق الحسيني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5067, 'مَخْبُوءَةٌ', 'مخبوءة', 'اسم مفعول', '', 'مخبوءة', 'مخبة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَبَّأَ). ""مَخْبُوءٌ فِي جُحْرِهِ"" : مَسْتُورٌ. ""كَشَفَتْ مَسْتُورًا وَأَظْهَرَتْ مَخْبُوءاً"". (إسحق الحسيني)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5068, 'مَخْبُولٌ', 'مخبول', 'اسم مفعول', 'خبل', 'مخبول', 'مخبل', 'مفع. مِنْ خَبَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مخابيلُ"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَبَلَ). ""رَجُلٌ مَخْبُولٌ"" : بِهِ خَبَلٌ، أَي الْمَعْتُوهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5069, 'مَخَابِيلُ', 'مخابيل', 'اسم مفعول', '', 'مخابيل', 'مخبل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5070, 'مَخْتُومٌ', 'مختوم', 'اسم مفعول', 'ختم', 'مختوم', 'مختم', 'مفع. مِنْ خَتَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَتَمَ). ""طَابَعٌ مَخْتُومٌ"" : وُضِعَ عَلَيْهِ الخَتْمُ. ""رِسَالَةٌ مَخْتُومَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5071, 'مَخْتُونٌ', 'مختون', 'اسم مفعول', 'ختن', 'مختون', 'مختن', 'مفع. مِنْ خَتَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَتَنَ). ""صَبِيٌّ مَخْتُونٌ"" : الَّذِي قُطِعَتْ قُلْفَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5072, 'مُخَدَّرٌ', 'مخدر', 'اسم مفعول', 'خدر', 'مخدر', 'مخدر', 'مفع. مِنْ خَدَّرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ خَدَّرَ). ""مُنْذُ فَتْرَةٍ طَوِيلَةٍ وَهُوَ مُخَدَّرٌ"" : فِي غَيْبُوبَةٍ بِسَبَبِ تَعَاطِي الْمُخَدِّرَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5073, 'مَخْدُوعٌ', 'مخدوع', 'اسم مفعول', 'خدع', 'مخدوع', 'مخدع', 'مفع. مِنْ خَدَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ خَدَعَ). ""رَجُلٌ مَخْدُوعٌ"" : مُغَفَّلٌ، أَيْ مَنْ خَضَعَ لِلْخَدِيعَةِ دُونَ دِرَايَةٍ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5074, 'مَخْدُومٌ', 'مخدوم', 'اسم مفعول', 'خدم', 'مخدوم', 'مخدم', 'مفع. مِنْ خَدَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مَخْدُومٌ، ةٌ - ج: ـون، ـات. [خ د م]. (مفع. مِنْ خَدَمَ). 1.""مَخْدُومٌ فِي كُلِّ الأَوْقَاتِ"" : السَّيِّدُ، أَيْ مَنْ يَخْدُمُهُ غَيْرُهُ. 2.""عَمَلٌ مَخْدُومٌ"" : مُحْكَمٌ، مُتْقَنٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5075, 'مَخْذُولٌ', 'مخذول', 'اسم مفعول', 'خذل', 'مخذول', 'مخذل', 'مفع. مِنْ خَذَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَخَاذِيلُ"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَذَلَ). ""مَخْذُولٌ فِي مَسْعَاهُ"" : مُحْبَطٌ، لاَ مَنْ يَنْصُرُهُ أَوْ يُعِينُهُ. ""نُفُوسٌ مَخْذ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5076, 'مَخَاذِيلُ', 'مخاذيل', 'اسم مفعول', '', 'مخاذيل', 'مخذل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5077, 'مُخَرَّبٌ', 'مخرب', 'اسم مفعول', 'خرب', 'مخرب', 'مخرب', 'مفع. مِنْ خَرَّبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخَرَّبٌ-مُخَرَّبٌ، ةٌ [خ ر ب] (مفع. مِنْ خَرَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5078, 'مَخْرُوطٌ', 'مخروط', 'اسم مفعول', 'خرط', 'مخروط', 'مخرط', 'مفع. مِنْ خَرَطَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَخْرُوطٌ-مَخْرُوطٌ [خ ر ط] (مفع. مِنْ خَرَطَ). ""الْمَخْرُوطُ فِي الهَنْدَسَةِ"" : شَكْلٌ هَن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5079, 'مَخْرُوقٌ', 'مخروق', 'اسم مفعول', 'خرق', 'مخروق', 'مخرق', 'مفع. مِنْ خَرَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"مَخْرُوقٌ، ةٌ - [خ ر ق]. (مفع. مِنْ خَرَقَ). ""جَوَارِبُ مَخْرُوقَةٌ"" : صَارَتْ بِهَا ثُقَبٌ، مُقَطَّعَةٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5080, 'مَخْزُونٌ', 'مخزون', 'اسم مفعول', 'خزن', 'مخزون', 'مخزن', 'مفع. مِنْ خَزَنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَخْزُونٌ - [خ ز ن]. (مفع. مِنْ خَزَنَ). ""مَخْزُونُ الْحُبُوبِ"" : مَا يُوضَعُ مِنْهُ فِي الْمَخْزَنِ الاحْتِيَاطِيِّ.   ""مَخْزُونُ البَضَائِعِ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5081, 'مَخْصُوصٌ', 'مخصوص', 'اسم مفعول', 'خصص', 'مخصوص', 'مخصص', 'مفع. مِنْ خَصَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ خَصَّ). ""رَجُلٌ مَخْصُوصٌ"" : مُعْوِزٌ، فَقِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5082, 'مَخْصُورٌ', 'مخصور', 'اسم مفعول', 'خصر', 'مخصور', 'مخصر', 'مفع. مِنْ خَصَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَخْصُورٌ - [خ ص ر]. (مفع. مِنْ خَصَرَ). ""رَجُلٌ مَخْصُورٌ""  : يَشْتَكِي مِنْ خَصْرهِ أَوْ خَاصِرَتِهِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5083, 'مُخَصَّصٌ', 'مخصص', 'اسم مفعول', 'خصص', 'مخصص', 'مخص', 'مفع. مِنْ خَصَّصَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَصَّصَ). 1.""مَكَانٌ مُخَصَّصٌ لِلرَّئِيسِ"" : وُضِعَ خِصِّيصاً لَهُ. 2.""مُخَصَّصَاتُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5084, 'مُخَضَّبٌ', 'مخضب', 'اسم مفعول', 'خضب', 'مخضب', 'مخضب', 'مفع. مِنْ خَضَّبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَضَّبَ). 1.""مُخَضَّبٌ بِالدَّمِ"" : مُلَطَّخٌ بِهِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5085, 'مُخَضْرَمٌ', 'مخضرم', 'اسم مفعول', 'خضرم', 'مخضرم', 'مخضرم', 'مفع. مِنْ خَضْرَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ خَضْرَمَ). ""شَاعِرٌ مُخَضْرَمٌ"" : قَضَى أَوَّلَ عُمْرِهِ فِي الجَاهِلِيَّةِ وَآخِرَهُ فِي الإِسْلاَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5086, 'مَخْطُوبٌ', 'مخطوب', 'اسم مفعول', 'خطب', 'مخطوب', 'مخطب', 'مفع. مِنْ خَطَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَخْطُوبَةٌ-مَخْطُوبَةٌ [خ ط ب] (مفع. مِنْ خَطَبَ). ""فَتَاةٌ مَخْطُوبَةٌ"" : فَتَاةٌ مَوْعُودَةٌ بِالزَّوَاجِ مِنَ الرَّجُلِ الَّذِي خَطَبَهَا، أَيِ الَّذِي طَلَبَهَا لِلزَّوَاجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5087, 'مُخَطَّطٌ', 'مخطط', 'اسم مفعول', 'خطط', 'مخطط', 'مخط', 'مفع. مِنْ خَطَّطَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخَطَّطٌ، ةٌ - ج: ـون، ـات. [خ ط ط]. (مفع. مِنْ خَطَّطَ). 1.""الحِمَارُ الوَحْشِيُّ حَيَوَانٌ مُخَطَّطٌ"" : بِهِ خُطُوطٌ. ""ثَوْبٌ مُخَطَّطٌ"". 2.""أَنْجَزَ مُخَطَّطاً لِمَشْرُوعِهِ"" : تَصْمِيماً. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5088, 'مَخْطُوفٌ', 'مخطوف', 'اسم مفعول', 'خطف', 'مخطوف', 'مخطف', 'مفع. مِنْ خَطَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَخْطُوفٌ-مَخْطُوفٌ [خ ط ف] (مفع. مِنْ خَطَفَ). ""وَلَدٌ مَخْطُوفٌ"" : الَّذِي تَمَّ خَطْفُهُ وَإِخْفَاؤُهُ عَنِ الأَنْظَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5089, 'مَخْفُورٌ', 'مخفور', 'اسم مفعول', 'خفر', 'مخفور', 'مخفر', 'مفع. مِنْ خَفَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَفَرَ). ""جَاءوا بِهِ مَخْفُوراً"" : مُحَاطاً بِحِرَاسَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5090, 'مُخَفَّضٌ', 'مخفض', 'اسم مفعول', 'خفض', 'مخفض', 'مخفض', 'مفع. مِنْ خَفَّضَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخَفَّضٌ-مُخَفَّضٌ [خ ف ض] (مفع. مِنْ خَفَّضَ). ""سِعْرٌ مُخَفَّضٌ"" : سِعْرٌ مَنْقُوصٌ مِنْ ثَمَنِهِ الأَصْلِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5091, 'مُخَفَّفٌ', 'مخفف', 'اسم مفعول', 'خفف', 'مخفف', 'مخف', 'مفع. مِنْ خَفَّفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَفَّفَ). ""عِبْءٌ مُخَفَّفٌ"" : أَيْ عِبْءٌ خَفِيفٌ، غَيْرُ شَدِيدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5092, 'مُخَلَّدٌ', 'مخلد', 'اسم مفعول', 'خلد', 'مخلد', 'مخلد', 'مفع. مِنْ خَلَّدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُخَلَّدٌ-مُخَلَّدٌ، ةٌ [خ ل د] (مفع. مِنْ خَلَّدَ). 1.""أَثَرٌ مُخَلَّدٌ"" : دَائِمٌ، أَبَدِيٌّ. ""عَمَلٌ فِكْرِيٌّ مُخَلَّدٌ"". 2.""فَتَاةٌ مُخَلَّدَةٌ"" : مُحَلاَّةٌ بِسِوَارٍ أَوْ قُرْطٍ.الواقعة آية 17 يَطُوفُ عَلَيْهِمْ وِلْدَانٌ مُخَلَّدُونَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5093, 'مَخْلُوطٌ', 'مخلوط', 'اسم مفعول', 'خلط', 'مخلوط', 'مخلط', 'مفع. من خَلَطَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من خَلَطَ). ""لَوْنٌ مَخْلُوطٌ"" : مَمْزُوجٌ. ""الظَّنُّ مَخْلُوطٌ بِالوَهْمِ"". (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5094, 'مَخْلُوعٌ', 'مخلوع', 'اسم مفعول', 'خلع', 'مخلوع', 'مخلع', 'مفع. مِنْ خَلَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَلَعَ). 1.""مُوَظَّفٌ مَخْلُوعٌ مِنْ وَظِيفَتِهِ"" : مَنْ تَمَّ خَلْعُهُ وَإِبْعَادُهُ... 2.""رَجُلٌ مَخْلُوعُ الفُؤَادِ"" : فَزِعٌ، هَلِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5095, 'مُخَلَّفٌ', 'مخلف', 'اسم مفعول', 'خلف', 'مخلف', 'مخلف', 'مفع. مِنْ خَلَّفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَلَّفَ). 1.""مِنْ مُخَلَّفَاتِ العَهْدِ الْمَاضِي"" : مِنْ بَقَايَاهُ. 2.""مُخَلَّفَاتُ الْمَصَانِعِ"" : النُّفَايَاتُ وَمَا تَبَقَّى مِنَ الاِسْتِخْدَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5096, 'مَخْلُوقٌ', 'مخلوق', 'اسم مفعول', 'خلق', 'مخلوق', 'مخلق', 'مفع. مِنْ خَلَقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَلَقَ). ""الإنْسانُ مَخْلوقٌ"" : كائِنٌ حَيٌّ. ""مَخْلُوقَاتُ هَذَا الكَوْنِ غَرَائِبُ وَعَجَائِبُ"" ""لِكُلِّ مَخْلُوقٍ حَاجَتُهُ"" ""الشِّدَّةُ لاَ تَدُومُ أَبَداً عَلَى مَخْلُوقٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5097, 'مُخَلَّلٌ', 'مخلل', 'اسم مفعول', 'خلل', 'مخلل', 'مخل', 'مفع. مِنْ خَلَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَلَّلَ).: كُلُّ مَا يُنْقَعُ فِي الْخَلِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5098, 'مَخْمُورٌ', 'مخمور', 'اسم مفعول', 'خمر', 'مخمور', 'مخمر', 'مفع. مِنْ خَمَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَمَرَ). ""وَجَدَهُ مَخْمُوراً عَلَى قَارِعَةِ الطَّرِيقِ"" : مَنْ أَسْكَرَتْهُ الْخَمْرُ، السَّكْرَانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5099, 'مُخَمَّسٌ', 'مخمس', 'اسم مفعول', 'خمس', 'مخمس', 'مخمس', 'مفع. مِنْ خَمَّسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَمَّسَ). 1.""شَكْلٌ هَنْدَسِيٌّ مُخَمَّسُ الزَّوَايَا"" (هن) : ذُو أَرْكَانٍ خَمْسَةٍ. 2.""شِعْرٌ مُخَمَّسٌ"" : شِعْرٌ مُقَسَّمٌ إِلَى قِطَعٍ، كُلُّ قِطْعَةٍ مُكَوَّنَةٍ مِنْ خَمْسَةِ أَسْطُرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5100, 'مَخْنُوقٌ', 'مخنوق', 'اسم مفعول', 'خنق', 'مخنوق', 'مخنق', 'مفع. مِنْ خَنَقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ خَنَقَ). ""وَجَدُوهُ مَخْنُوقاً فِي غُرْفَتِهِ"" : مُخْتَنِقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5101, 'مَدْيُونٌ', 'مديون', 'اسم مفعول', 'دين', 'مديون', 'مدن', 'مفع. مِنْ دَانَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَدْيُونٌ - [د ي ن]. (مفع. مِنْ دَانَ).: مَنْ كَانَ عَلَيْهِ دَيْنٌ، مَدِينٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5102, 'مُدَبَّجٌ', 'مدبج', 'اسم مفعول', 'دبج', 'مدبج', 'مدبج', 'مفع. مِنْ دَبَّجَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُدَبَّجٌ-مُدَبَّجٌ، ةٌ [د ب ج] (مفع. مِنْ دَبَّجَ). ""ثَوْبٌ مُدَبَّجٌ"" : مُزَيَّنٌ بِالدِّيبَاجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5103, 'مُدَبَّرٌ', 'مدبر', 'اسم مفعول', 'دبر', 'مدبر', 'مدبر', 'مفع. من دَبَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُدَبَّرٌ-مُدَبَّرٌ، ةٌ [د ب ر] (مفع. من دَبَّرَ). ""عَمَلٌ مُدَبَّرٌ"" : مُنَظَّمٌ، أَيْ عُمِلَ بِفِكْرٍ وَرَوِيَّةٍ وَتَحْضِيرٍ. ""خُطَّةٌ مُدَبَّرَةٌ"" ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5104, 'مَدْبُوغٌ', 'مدبوغ', 'اسم مفعول', 'دبغ', 'مدبوغ', 'مدبغ', 'مفع. مِنْ دَبَغَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَدْبُوغٌ-مَدْبُوغٌ، ةٌ [د ب غ] (مفع. مِنْ دَبَغَ). ""جِلْدٌ مَدْبُوغٌ"": أَيْ جِلْدٌ تَمَّ دَبْغُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5105, 'مُدَجَّجٌ', 'مدجج', 'اسم مفعول', 'دجج', 'مدجج', 'مدج', 'مفع. مِنْ دَجَّجَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ دَجَّجَ). ""جُنْدٌ مُدَجَّجٌ بِالسِّلاَحِ"" : مُزَوَّدٌ بِالسِّلاَحِ، مُسَلَّحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5106, 'مَدْخُولٌ', 'مدخول', 'اسم مفعول', 'دخل', 'مدخول', 'مدخل', 'مفع. مِنْ دَخَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مَدَاخِيلُ"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ دَخَلَ). 1.""مَدْخُولٌ عَلَيْهِ"" : الَّذِي دَخَلَ عَقْلَهُ أَوجَسَدَهُ فَسَادٌ. 2.""وَلَدٌ مَدْخُولٌ"" : مَهْزُولٌ، ضَعِيفٌ. 3.""لَهُ مَدْخُولٌ شَهْرِيٌّ"" : مَوْرِدٌ مَاِليٌّ، الدَّخْلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5107, 'مَدَاخِيلُ', 'مداخيل', 'اسم مفعول', '', 'مداخيل', 'مدخل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5108, 'مُدَرَّبٌ', 'مدرب', 'اسم مفعول', 'درب', 'مدرب', 'مدرب', 'مفع. مِنْ دَرَّبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُدَرِّبٌ-مُدَرِّبٌ [د ر ب] (فَا. مِنْ دَرَّبَ). ""مُدَرِّبُ الفَرِيقِ الرِّيَاضِيِّ"" : الَّذِي يُدَرِّبُ أَعْضَاءَ الفَرِيقِ وَيُمَرِّنُهُمْ بِتَمَارِينَ عَمَلِيَّةٍ. ""مُدَرِّبُ الجنودِ في الْمُعَسْكَرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5109, 'مَدْرُوسٌ', 'مدروس', 'اسم مفعول', 'درس', 'مدروس', 'مدرس', 'مفع. مِنْ دَرَسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَدْرُوسٌ-مَدْرُوسٌ، ةٌ [د ر س] (مفع. مِنْ دَرَسَ). 1.""كِتَابٌ مَدْرُوسٌ"" : كِتَابٌ تَمَّتْ دِرَاسَتُهُ. 2.""مَشْرُوعٌ مَدْرُوسٌ"" : دُرِسَتْ تَصَامِيمُهُ وَحَيْثِيَّاتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5110, 'مَدْسُوسٌ', 'مدسوس', 'اسم مفعول', 'دسس', 'مدسوس', 'مدسس', 'مفع. مِنْ دَسَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ دَسَّ). ""عَمَلٌ مَدْسُوسٌ"" : عَمَلٌ فِيهِ احْتِيَالٌ وَتَلاَعُبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5111, 'مَدْفُوعٌ', 'مدفوع', 'اسم مفعول', 'دفع', 'مدفوع', 'مدفع', 'مفع. مِنْ دَفَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ دَفَعَ). 1.""الْمَبْلَغُ الْمَدْفُوعُ"" : الْمَبْلَغُ الْمُقَدَّمُ، الْمُسَلَّمُ، مَا تَمَّ أَدَاؤُهُ. 2.""كَانَ مَدْفُوعاً تَحْتَ تَأْثِيرِ عَوَامِلَ خَارِجِيَّةٍ"" : مُضْطَرّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5112, 'مَدْفُونٌ', 'مدفون', 'اسم مفعول', 'دفن', 'مدفون', 'مدفن', 'مفع. مِنْ دَفَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَدْفُونٌ-مَدْفُونٌ، ةٌ [د ف ن] (مفع. مِنْ دَفَنَ). 1.""مَدْفُونٌ بِمَقْبَرَةِ الشُّهَدَاءِ"" : أَيْ مُقْبَرٌ في قَبْرِهِ... 2. ""حَشَرَةٌ سامَّةٌ مَدْفونَةٌ"": أي مَحْشُوَّةٌ في الأرْضِ. ""الْحَيَّةُ الْمَدْفُونَةُ فِي الأَرْضِ لاَ تَقْدِرُ عَلَى أَنْ تَخْلَعَ سَلْخَها"". 3.""الْمَدْفُونَةُ"" : طَعَامٌ شَرْقِيٌّ يُحَضَّرُ مِنَ الخُضَرِ وَالأُرُزِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5113, 'مُدَقَّقٌ', 'مدقق', 'اسم مفعول', 'دقق', 'مدقق', 'مدق', 'مفع. من دَقَّقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُدَقَّقٌ-مُدَقَّقٌ، ةٌ [د ق ق] (مفع. من دَقَّقَ). ""أَدْلَى بِكَلامٍ مُدَقَّقٍ"" : دَقِيقٌ، فِيهِ كَثِيرٌ مِنَ التَّحَرِّي. ""بَيَاضٌ مُدَقَّقٌ"" ""شَهَادَةٌ مُدَقَّقَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5114, 'مَدْلُولٌ', 'مدلول', 'اسم مفعول', 'دلل', 'مدلول', 'مدلل', 'مفع. مِنْ دَلَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ دَلَّ). ""مَدْلُولُ كَلِمَةٍ"" : مَعْنَاهَا وَفَحْوَاهَا، مُؤَدَّاهَا، الصُّورَةُ الذِّهْنِيَّة لِما تَدُلُّ عَلَيْهِ، أَوْ لِما تُحيلُ وَتُرْجِعُ إِلَيْهِ. ""الدَّالُّ وَالْمَدْلُولُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5115, 'مُدَلَّعٌ', 'مدلع', 'اسم مفعول', 'دلع', 'مدلع', 'مدلع', 'مفع. مِنْ دَلَّعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُدَلَّعٌ-مُدَلَّعٌ، ةٌ [د ل ع] (مفع. مِنْ دَلَّعَ). ""وَلَدٌ مُدَلَّعٌ"": مُدَلَّلٌ، مَنْ يَعِيشُ فِي غُنْجِ وَيُعْطَاهُ كُلَّ مَا يُرِيدُ وَيُخْضَعُ لِرَغَبَاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5116, 'مُدَلَّلٌ', 'مدلل', 'اسم مفعول', 'دلل', 'مدلل', 'مدل', 'مفع. مِنْ دَلَّلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ دَلَّلَ). ""طِفْلٌ مُدَلَّلٌ"" : مُدَلَّعٌ، مَنْ يَعِيشُ فيِ غُنْجٍ وَيُعْطَاهُ كُلَّ مَا يُرِيدُ وَيُخْضَعُ لِرَغَبَاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5117, 'مُدَلَّهٌ', 'مدله', 'اسم مفعول', 'دله', 'مدله', 'مدله', 'مفع. مِنْ دَلَّهَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ دَلَّهَ). ""مُدَلَّهٌ فِي حُبِّهَا"" : عَاشِقٌ وَلْهَانُ، الَّذِي ذَهَبَ عَقْلُهُ مِنَ الْحُبِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5118, 'مُدَمَّرٌ', 'مدمر', 'اسم مفعول', 'دمر', 'مدمر', 'مدمر', 'مفع. مِنْ دَمَّرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُدَمَّرٌ-مُدَمَّرٌ، ةٌ [د م ر] (مفع. مِنْ دَمَّرَ). ""بَلَدٌ مُدَمَّرٌ عَنْ آخِرِهِ"" : مُهَدَّمٌ، مُحَطَّمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5119, 'مُدَمَّسٌ', 'مدمس', 'اسم مفعول', 'دمس', 'مدمس', 'مدمس', 'مفع. مِنْ دَمَّسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُدَمَّسٌ-مُدَمَّسٌ [د م س] (مفع. مِنْ دَمَّسَ). 1.""فُولٌ مُدَمَّسٌ"": طَعَامٌ يُحَضَّرُ مِنَ الفُولِ الْمَسْلُوقِ الْمَمْزُوجِ بِالتَّوَابِلِ مِنْ خَلٍّ وَزَيْتٍ وَمِلْحٍ فِي قِدْرٍ مُغْلَقَةٍ. 2.""طَعَامٌ مُدَمَّسٌ"" : مَخْبُوءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5120, 'مُدَمّىً', 'مدمى', 'اسم مفعول', 'دمي', 'مدمى', 'مدم', 'مفع. مِنْ دَمَّى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"مُدَمّىً-مُدَمّىً، مُدَمَّاةٌ [د م ي] (مفع. مِنْ دَمَّى). 1.""وَصَلَ مُدَمًّى بِالدَّمِ"" : مُلَطَّخٌ بِهِ. 2.""مُدَمَّى الْقَلْبِ"" : مَكْلُومٌ، مَجْرُوحُ القَلْبِ. 3.""ثَوْبٌ مُدَمّىً"" : أَحْمَرُ. ""خَيْلٌ مُدَمَّاةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5121, 'مُدَمّاة', 'مدماة', 'اسم مفعول', '', 'مدماة', 'مدمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُدَمّىً-مُدَمّىً، مُدَمَّاةٌ [د م ي] (مفع. مِنْ دَمَّى). 1.""وَصَلَ مُدَمًّى بِالدَّمِ"" : مُلَطَّخٌ بِهِ. 2.""مُدَمَّى الْقَلْبِ"" : مَكْلُومٌ، مَجْرُوحُ القَلْبِ. 3.""ثَوْبٌ مُدَمّىً"" : أَحْمَرُ. ""خَيْلٌ مُدَمَّاةٌ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5122, 'مُدَنَّسٌ', 'مدنس', 'اسم مفعول', 'دنس', 'مدنس', 'مدنس', 'مفع. مِنْ دَنَّسَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُدَنَّسٌ-مُدَنَّسٌ، ةٌ [د ن س] (مفع. مِنْ دَنَّسَ). ""الْمُدَنَّسُ وَالْمُقَدَّسُ"" : الْمُلَطَّخُ وَالْمُوَسَّخُ بِكُلِّ مَا هُوَ دَنَسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5123, 'مَدْهُوشٌ', 'مدهوش', 'اسم مفعول', 'دهش', 'مدهوش', 'مدهش', 'مفع. مِنْ دَهِشَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ دَهِشَ). ""وَقَفَ مَدْهُوشاً"" : دَهِشاً، مُتَحَيِّراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5124, 'مَدْهُونٌ', 'مدهون', 'اسم مفعول', 'دهن', 'مدهون', 'مدهن', 'مفع. مِنْ دَهَنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَدْهُونٌ-مَدْهُونٌ، ةٌ [د هـ ن] (مفع. مِنْ دَهَنَ). 1.""جِلْدٌ مَدْهُونٌ"" : أَيْ جِلْدٌ طُلِيَ بِالزَّيْتِ أَوْ بِمَادَّةٍ دُهْنِيَّةٍ. 2.""أَرْضٌ مَدْهُونَةٌ"" : بَلَّلَهَا مَطَرٌ قَلِيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5125, 'مُدَوَّدٌ', 'مدود', 'اسم مفعول', 'دود', 'مدود', 'مدد', 'مفع. مِنْ دَوَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُدَوَّدٌ-مُدَوَّدٌ، ةٌ [د و د] (مفع. مِنْ دَوَّدَ). ""طَعَامٌ مُدَوَّدٌ"" : بِهِ دُودٌ. ""أَطْعِمَةٌ مُدَوَّدَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5126, 'مُدَوَّرٌ', 'مدور', 'اسم مفعول', 'دور', 'مدور', 'مدر', 'مفع. مِنْ دَوَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُدَوَّرٌ-مُدَوَّرٌ، ةٌ [د و ر] (مفع. مِنْ دَوَّرَ). ""شَكْلٌ مُدَوَّرٌ"" : دَائِرِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5127, 'مُدَوَّنٌ', 'مدون', 'اسم مفعول', 'دون', 'مدون', 'مدن', 'مفع. مِنْ دَوَّنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُدَوَّنٌ-مُدَوَّنٌ، ةٌ [د و ن] (مفع. مِنْ دَوَّنَ). ""نَصٌّ مُدَوَّنٌ فِي وثِيقَةٍ"" : مُسَجَّلٌ، مَكْتُوبٌ. ""نُصُوصٌ مُدَوَّنَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5128, 'مَذْبُوحٌ', 'مذبوح', 'اسم مفعول', 'ذبح', 'مذبوح', 'مذبح', 'مفع. مِنْ ذَبَحَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ ذَبَحَ). ""الطَّيْرُ يَرْقُصُ مَذْبُوحاً مِنَ الأَلَمِ"" : مَنْ وَقَعَ عَلَيْهِ الذَّبْحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5129, 'مُذَبْذَبٌ', 'مذبذب', 'اسم مفعول', 'ذبذب', 'مذبذب', 'مذبذب', 'مفع. مِنْ ذَبْذَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ ذَبْذَبَ). ""رَجُلٌ مُذَبْذَبٌ"" : مُتَحَيِّرٌ، مُتَرَدِّدٌ.النساء آية 143 مُذَبْذَبِينَ بَيْنَ ذَلِكَ لاَ إِلَى هَؤُلاَءِ وَلاَ إِلَى هَؤُلاَءِ (قرآن) ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5130, 'مَذْعُورٌ', 'مذعور', 'اسم مفعول', 'ذعر', 'مذعور', 'مذعر', 'مفع. مِنْ ذَعَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ ذَعَرَ). ""بَقِيَ فِي مَخْبَئِهِ مَذْعُوراً"" : خَائِفاً، مَرْعُوباً. ""وَلاَحَتْ فِي عَيْنَيْهِ نَظْرَةُ طِفْلٍ مَذْعُورٍ"". (ن. محفوظ) ""سَمِعْنَا صَرْخَةً قُمْنَا لَهَا مَذْعُورِينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5131, 'مَذْكُورٌ', 'مذكور', 'اسم مفعول', 'ذكر', 'مذكور', 'مذكر', 'مفع. مِنْ ذَكَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ ذَكَرَ). 1.""رَجُلٌ مَذْكُورٌ"" : ذُو شَأْنٍ، ذُو قِيمَةٍ، وَهُوَ غَالِباً مَا يُسْتَعْمَلُ فِي أُسْلُوبِ النَّفْيِ. ""الْعَيْبُ فِي الرَّجُلِ الْمَذْكُورِ مَذْكُورٌ""الإنسان آية 1 هَلْ أَتَى عَلَى الإِنْسَانِ حِينٌ مِنَ الدَّهْرِ لَمْ يَكُنْ شَيْئاً مَذْكُوراً (قرآن). 2.""حَسَبَ مَا هُوَ مَذْكُورٌ أَدْنَاهُ"" : حَسَبَ مَا هُوَ مُشَارٌ إِلَيْهِ، مَا ذُكِرَ سَلَفاً، آنِفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5132, 'مُذَلَّقٌ', 'مذلق', 'اسم مفعول', 'ذلق', 'مذلق', 'مذلق', 'مفع. مِنْ ذَلَّقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُذَلَّقٌ-مُذَلَّقٌ [ذ ل ق] (مفع. مِنْ ذَلَّقَ). 1.""سَيْفٌ مُذَلَّقٌ"" : مُحَدَّدُ الطَّرَفِ. 2.""لَبَنٌ مُذَلَّقٌ"" : مَمْزُوجٌ بِالْمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5133, 'مُذَلَّلٌ', 'مذلل', 'اسم مفعول', 'ذلل', 'مذلل', 'مذل', 'مفع. مِنْ ذَلَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُذَلَّلٌ-مُذَلَّلٌ، ةٌ [ذ ل ل] (مفع. مِنْ ذَلَّلَ). ""طَرِيقٌ مُذَلَّلٌ"" : مُعَبَّدٌ، مَسْلُوكٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5134, 'مَذْمُومٌ', 'مذموم', 'اسم مفعول', 'ذمم', 'مذموم', 'مذمم', 'مفع. مِنْ ذَمَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ ذَمَّ). ""رَجُلٌ مَذْمُومٌ"" : مَعيبٌ عَلَيْهِ، وَمَلُومٌ. الإسراء آية 29 وَلاَ تَجْعَلْ مَعَ الله إِلَهاً آخَرَ فَتَقْعُدَ مَذْمُوماً مَخْذُولاً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5135, 'مُذَمَّمٌ', 'مذمم', 'اسم مفعول', 'ذمم', 'مذمم', 'مذم', 'مفع. مِنْ ذَمَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُذَمَّمٌ-مُذَمَّمٌ، ةٌ [ذ م م] (مفع. مِنْ ذَمَّمَ). 1.""وَلَدٌ مُذَمَّمٌ"" : مَذْمُومٌ، مُصَابٌ، مَلُومٌ. 2.""مَكَانٌ مُذَمَّمٌ"" : ذُو حُرْمَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5136, 'مُذَنَّبٌ', 'مذنب', 'اسم مفعول', 'ذنب', 'مذنب', 'مذنب', 'مفع. مِنْ ذَنَّبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُذَنَّبٌ-مُذَنَّبٌ [ذ ن ب] (مفع. مِنْ ذَنَّبَ). 1.""حَيَوَانٌ مُذَنَّبٌ"" : لَهُ ذَنَبٌ. 2.""نَجْمٌ مُذَنَّبٌ"" (فك) : جُرْمٌ سَمَاوِيٌّ لَهُ ذَنَبٌ مُضِيءٌ يَدُورُ حَوْلَ الشَّمْسِ فِي فَلَكٍ بَيْضِيٍّ. 3.""كِتابٌ مُذَنَّبٌ"" : كتاب مُذَيَّلٌ، أُلْحِقَتْ بِهِ إْخْمامَةٌ، تَكْمِلَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5137, 'مُذَهَّبٌ', 'مذهب', 'اسم مفعول', 'ذهب', 'مذهب', 'مذهب', 'مفع. مِنْ ذَهَّبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُذَهَّبٌ،  ةٌ - ج: ـون، ـات. [ذ هـ ب]. (مفع. مِنْ ذَهَّبَ). 1.""مَعْدِنٌ مُذَهَّبٌ"" : مَطْلِيٌّ بِالذَّهَبِ. 2.""الْمُذَهَّبَاتُ"": سَبْعُ قَصَائِدَ تُعَدُّ فِي الْمَرْتَبَةِ الثَّانِيَةِ بَعْدَ الْمُعَلَّقَاتِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5138, 'مَذْهُولٌ', 'مذهول', 'اسم مفعول', 'ذهل', 'مذهول', 'مذهل', 'مفع. مِنْ ذَهِلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ ذَهِلَ). ""وَقَفَ مَذْهُولاً أَمَامَ الفَجِيعَةِ"" : مَدْهُوشاً، مَأْخُوذًا بِكُلِّ حَوَاسِّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5139, 'مُذَيَّلٌ', 'مذيل', 'اسم مفعول', 'ذيل', 'مذيل', 'مذل', 'مفع. مِنْ ذَيَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُذَيَّلٌ-مُذَيَّلٌ، ةٌ [ذ ي ل] (مفع. مِنْ ذَيَّلَ). 1.""فُسْتَانٌ مُذَيَّلٌ"" : طَوِيلُ الذَّيْلِ. 2.""كِتابٌ مُذَيَّل"" : الذي أُلْحِقَ بِهِ ذَيْلٌ أو تَكمِلَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5140, 'مَرْؤُوسٌ', 'مرؤوس', 'اسم مفعول', 'رأس', 'مرءوس', 'مرس', 'مفع. من رَأَسَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مَرْؤُوسٌ-مَرْؤُوسٌ [ر أ س] (مفع. من رَأَسَ). 1.""وَلَدٌ مَرْؤُوسٌ"": عَظِيمُ الرَّأْسِ. 2.""جَاءَ مِنَ الْمَعْرَكَةِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5141, 'مُرَاقَبٌ', 'مراقب', 'اسم مفعول', 'رقب', 'مراقب', 'مرقب', 'مفع. مِنْ رَاقَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُرَاقَبٌ-مُرَاقَبٌ [ر ق ب] (مفع. مِنْ رَاقَبَ). ""عَمَلٌ مُرَاقَبٌ"": أَيْ خَاضِعٌ لِلْمُرَاقَبَةِ ، لِلْحِرَاسَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5142, 'مُرَتَّبٌ', 'مرتب', 'اسم مفعول', 'رتب', 'مرتب', 'مرتب', 'مفع. مِنْ رَتَّبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ رَتَّبَ). 1.""بَيْتٌ مُرَتَّبٌ"" : مُنَسَّقٌ، مُنَظَّمٌ. 2. ""يَتَقَاضَى الْمُوَظَّفُ مُرَتَّبَهُ الشَّهْرِيَّ فِي أَخِرِ كُلِّ شَهْرٍ"" : مَا يَتَقَاضَاهُ مِنْ مَالٍ مُقَابِلَ عَمَلِهِ. ""يُطَالِبُ الْمُوَظَّفُونَ بِالزِّيَادَةِ فِي مُرَتَّبَاتِهِمْ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5143, 'مُرَتَّلٌ', 'مرتل', 'اسم مفعول', 'رتل', 'مرتل', 'مرتل', 'مفع. مِنْ رَتَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرَتَّلٌ-مُرَتَّلٌ، ةٌ [ر ت ل] (مفع. مِنْ رَتَّلَ). 1.""شِعْرٌ مُرَتَّلٌ"": مُغَنّىً. 2.""آيَاتٌ مُرَتَّلَةٌ"" : مُجَوَّدَةٌ، أَيْ تَمَّ تَجْوِيدُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5144, 'مُرَجَّحٌ', 'مرجح', 'اسم مفعول', 'رجح', 'مرجح', 'مرجح', 'مفع. مِنْ رَجَّحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ رَجَّحَ). ""مِنَ الْمُرَجَّحِ أَنْ يَعُودَ فِي الْمَسَاءِ"" : مِنَ الْمُحْتَمَلِ أَنْ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5145, 'مَرْجُوعٌ', 'مرجوع', 'اسم مفعول', 'رجع', 'مرجوع', 'مرجع', 'مفع. من رَجَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مَرَاجِيعُ"', '', '', '', '', '', '', '', '', '". (مفع. من رَجَعَ). 1.""مَرْجُوعُ الرِّسَالَةِ"" : جَوَابُهَا. 2. ""أَمْرٌ مَرْجُوعٌ"" : مَرْدُودٌ."" 3. وَشْمٌ مَرْجُوعٌ"" : مُجَدَّدٌ. ""ثَوْبٌ مَرْجُوعٌ"". 4.""سِلَعٌ مَرْجُوعَةٌ"" : أَيْ لَمْ تُبَعْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5146, 'مَرَاجِيعُ', 'مراجيع', 'اسم مفعول', '', 'مراجيع', 'مرجع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5147, 'مُرَجَّلٌ', 'مرجل', 'اسم مفعول', 'رجل', 'مرجل', 'مرجل', 'مفع. مِنْ رَجَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرَجَّلٌ-مُرَجَّلٌ [ر ج ل] (مفع. مِنْ رَجَّلَ). ""شَعْرٌ مُرَجَّلٌ"" : مُسَرَّحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5148, 'مُرَجَّمٌ', 'مرجم', 'اسم مفعول', 'رجم', 'مرجم', 'مرجم', 'مفع. مِنْ رَجَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرَجَّمٌ-مُرَجَّمٌ [ر ج م] (مفع. مِنْ رَجَّمَ). ""حَدِيثٌ مُرَجَّمٌ"" : لاَ يُعْرَفُ كُنْهُهُ وَلاَ حَقِيقَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5149, 'مَرْحُومٌ', 'مرحوم', 'اسم مفعول', 'رحم', 'مرحوم', 'مرحم', 'مفع. مِن رَحِمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن رَحِمَ). ""الْمَرْحُومُ السَّيِّدُ..."" : الْمُتَوَفَّى، الْمَيِّتُ، الفَقيدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5150, 'مُرَخَّصٌ', 'مرخص', 'اسم مفعول', 'رخص', 'مرخص', 'مرخص', 'مفع. مِنْ رَخَّصَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرَخَّصٌ-مُرَخَّصٌ، ةٌ [ر خ ص] (مفع. مِنْ رَخَّصَ). ""مُرَخَّصٌ لَهُ بِالزِّيَارَةِ"" : أَيْ قَدْ أُذِنَ لَهُ، رُخِّصَ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5151, 'مَرْدُودٌ', 'مردود', 'اسم مفعول', 'ردد', 'مردود', 'مردد', 'مفع. مِنْ رَدَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَرْدُودٌ-مَرْدُودٌ، ةٌ [ر د د] (مفع. مِنْ رَدَّ). 1.""قَوْلٌ مَرْدُودٌ"": مَرْفُوضٌ، غَيْرُ مَقْبُولٍ. ""أَفْكَارٌ مَرْدُودَةٌ"". 2.""عَمَلٌ مَرْدُودُهُ كَبِيرٌ"" : أَيْ ذُو عَطَاءٍ وَدَخْلٍ. 3.""غَلَطٌ مَرْدُودٌ"" : أَيْ يُمْكِنُ تَدَارُكُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5152, 'مُرَدَّدٌ', 'مردد', 'اسم مفعول', 'ردد', 'مردد', 'مرد', 'مفع. مِنْ رَدَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرَدَّدٌ-مُرَدَّدٌ، ةٌ [ر د د] (مفع. مِنْ رَدَّدَ). ""رَجُلٌ مُرَدَّدٌ"" : حَائِرٌ بَائِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5153, 'مَرْدُومٌ', 'مردوم', 'اسم مفعول', 'ردم', 'مردوم', 'مردم', 'مفع. مِنْ رَدَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ رَدَمَ). ""مَرْدُومٌ تَحْتَ التُّرَابِ"" : مُغَطًّى..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5154, 'مَرْذُولٌ', 'مرذول', 'اسم مفعول', 'رذل', 'مرذول', 'مرذل', 'مفع. مِنْ رَذُلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ رَذُلَ). ""رَجُلٌ مَرْذُولٌ"" : خَسِيسٌ، رَدِيءٌ. ""قَوْلٌ مَرْذُولٌ وَرَأْيٌ مَخْذُولٌ"" (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5155, 'مُرَزَّأٌ', 'مرزأ', 'اسم مفعول', 'رزأ', 'مرزء', 'مرز', 'مفع. مِنْ رَزَّأَ', '', '', 'مفرد', 'Dz', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ رَزَّأَ). 1.""رَجُلٌ مُرَزَّأٌ"" : كَرِيمٌ سَخِيٌّ. ""فَفِي يَوْمِنَا خَمْرٌ وَفِي غَدِنا أَمْرُ*""وَلاَ عَجَبٌ إِنَّ الكَرِيمَ مُرَزَّأُ"". (ابن زيدون). 2.""عَائِلَةٌ مُرَزَّأَةٌ"" : أَيْ عَائِلَةٌ فَقَدَتْ أَبْنَاءهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5156, 'مُرَزَّأَةٌ', 'مرزأة', 'اسم مفعول', '', 'مرزءة', 'مرزة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ رَزَّأَ). 1.""رَجُلٌ مُرَزَّأٌ"" : كَرِيمٌ سَخِيٌّ. ""فَفِي يَوْمِنَا خَمْرٌ وَفِي غَدِنا أَمْرُ*""وَلاَ عَجَبٌ إِنَّ الكَرِيمَ مُرَزَّأُ"". (ابن زيدون). 2.""عَائِلَةٌ مُرَزَّأَةٌ"" : أَيْ عَائِلَةٌ فَقَدَتْ أَبْنَاءهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5157, 'مَرْزُوقٌ', 'مرزوق', 'اسم مفعول', 'رزق', 'مرزوق', 'مرزق', 'مفع. مِنْ رَزَقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَرْزُوقٌ-مَرْزُوقٌ [ر ز ق] (مفع. مِنْ رَزَقَ). ""وَلَدٌ مَرْزُوقٌ"" : ذُو رِزْقٍ، حَسَنُ الْحَظِّ، مَحْظُوظٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5158, 'مَرْسُومٌ', 'مرسوم', 'اسم مفعول', 'رسم', 'مرسوم', 'مرسم', 'مفع. مِنْ رَسَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَرَاسِيمُ"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ رَسَمَ). 1.""مَرْسُومٌ إِدَارِيٌّ"" : قَرَارٌ. 2.""مَرْسُومٌ جُمْهُورِيٌّ"" : يُقَابِلُهُ الظَّهِيرُ فِي النِّظَامِ الْمَلَكِيِّ، وَهُوَ مَا يُصْدِرُهُ رَئِيسُ الدَّوْلَةِ يكَوُنُ لَهُ مَفْعُولُ القَانُونِ وَقَوَّتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5159, 'مَرَاسِيمُ', 'مراسيم', 'اسم مفعول', '', 'مراسيم', 'مرسم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5160, 'مُرَشَّحٌ', 'مرشح', 'اسم مفعول', 'رشح', 'مرشح', 'مرشح', 'مفع. مِنْ رَشَّحَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ رَشَّحَ). 1.""مُرَشَّحٌ لِلاِنْتِخَابَاتِ البَرْلَمَانِيَّةِ"" : مَنْ يُرَشِّحُ أَوْ يُقَدِّمُ نَفْسَهُ لِلاِنْتِخَابَاتِ. 2.""وَصَلَ مُرَشَّحاً مِنَ الجَبَلِ"" : مُصَاباً بِنَزْلَةِ بَرْدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5161, 'مَرْصُوصٌ', 'مرصوص', 'اسم مفعول', 'رصص', 'مرصوص', 'مرصص', 'مفع. مِنْ رَصَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَرْصُوصٌ-مَرْصُوصٌ، ةٌ [ر ص ص] (مفع. مِنْ رَصَّ). 1.""بِنَاءٌ مَرْصُوصٌ"" : مَا أُحْكِمَ بُنْيَانُهُ، مَتِينٌ.الصف آية 4 إِنَّ الله يُحِبُّ الَّذِينَ يُقَاتِلُونَ فيِ سَبِيلِهِ صَفّاً كَأَنَّهُمْ بُنْيَانٌ مَرْصُوصٌ (قرآن) ""صُفُوفٌ مَرْصُوصَةٌ"". 2.""أَرْضٌ مَرْصُوصَةٌ"" : مَطْرُوقَةٌ بِالحِجَارَةِ، مُبَلَّطَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5162, 'مَرْصُودٌ', 'مرصود', 'اسم مفعول', 'رصد', 'مرصود', 'مرصد', 'مفع. مِنْ رَصَدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَرْصُودٌ-مَرْصُودٌ [ر ص د] (مفع. مِنْ رَصَدَ). 1.""عَمَلٌ مَرْصُودٌ لِلْفُقَرَاءِ"" : مُوَجَّهٌ. 2.""أَمْوَالٌ مَرْصُودَةٌ"" : مَوْقُوفَةٌ، مَحْبُوسَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5163, 'مُرَصَّعٌ', 'مرصع', 'اسم مفعول', 'رصع', 'مرصع', 'مرصع', 'مفع. مِنْ رَصَّعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرَصَّعٌ-مُرَصَّعٌ، ةٌ [ر ص ع] (مفع. مِنْ رَصَّعَ). 1.""تَاجٌ مُرَصَّعٌ بِالجَوَاهِرِ"" : مُنَقَّطٌ، مُزَيَّنٌ بِالجَوَاهِرِ. ""قُفْطَانُ مُرَصَّعٌ"". 2.""كَلِمَاتٌ رَنَّانَةٌ وَجُمَلٌ مُرَصَّعَةٌ"" : مُسْتَوِيَةُ الأَوْزَانِ مُتَّفِقَةُ الأَعْجَازِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5164, 'مَرْصُوفٌ', 'مرصوف', 'اسم مفعول', 'رصف', 'مرصوف', 'مرصف', 'مفع. مِنْ رَصَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَرْصُوفٌ-مَرْصُوفٌ، ةٌ [ر ص ف] (مفع. مِنْ رَصَفَ). "" بِنَاءٌ مَرْصُوفٌ"" : مُبَلَّطٌ، مَرْصُوصٌ. ""سَاحَةٌ مَرْصُوفَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5165, 'مُرَطَّبٌ', 'مرطب', 'اسم مفعول', 'رطب', 'مرطب', 'مرطب', 'مفع. مِنْ رَطَّبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرَطَّبٌ-مُرَطَّبٌ، ةٌ [ر ط ب] (مفع. مِنْ رَطَّبَ). 1.""ثَوْبٌ مُرَطَّبٌ"" : مُبَلَّلٌ، رَطْبٌ، نَدِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5166, 'مَرْعُوبٌ', 'مرعوب', 'اسم مفعول', 'رعب', 'مرعوب', 'مرعب', 'مفع. مِنْ رَعَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ رَعَبَ). ""وَصَلَ مَرْعُوباً مِنْ جَرَّاءِ الكَارِثَةِ"" : مَفْزُوعاً، مُرْتَعِباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5167, 'مُرَعْبَلٌ', 'مرعبل', 'اسم مفعول', 'رعبل', 'مرعبل', 'مرعبل', 'مفع. مِن رَعْبَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرَعْبَلٌ-مُرَعْبَلٌ، ةٌ [ر ع ب ل] (مفع. مِن رَعْبَلَ). ""لَحْمٌ مُرَعْبَلٌ"" : مُقَطَّعٌ أَطْرَافاً لِتَتَمَكَّنَ النَّارُ مِن إنْضَاجِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5168, 'مَرْعِيٌّ', 'مرعي', 'اسم مفعول', 'رعى', 'مرعي', 'مرع', 'مفع. مِنْ رَعَى', '', 'ة', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَرْعِيٌّ-مَرْعِيٌّ [ر ع ى] (مفع. مِنْ رَعَى). 1.""عَمَلٌ مَرْعِيٌّ"": مَا يُرْعَى وَيُرَاعِيهِ النَّاسُ. 2.""القَانُونُ الْمَرْعِيُّ"" : القَانُونُ السَّارِي الْمَفْعُولِ، الْمَعْمُولُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5169, 'مَرْغُوبٌ', 'مرغوب', 'اسم مفعول', 'رغب', 'مرغوب', 'مرغب', 'مفع. مِنْ رَغِبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ رَغِبَ). 1.""عَمَلٌ مَرْغُوبٌ فِيهِ"" : هُوَ مَوْضِعُ رَغْبَةٍ وَطَلَبٍ. 2.""زَائِرٌ غَيْرُ مَرْغُوبٍ فِيهِ"" : أَيْ وُجُودُهُ غَيْرُ مُسْتَحَبٍّ، مَرْفُوضٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5170, 'مَرْفُوعٌ', 'مرفوع', 'اسم مفعول', 'رفع', 'مرفوع', 'مرفع', 'مفع. مِنْ رَفَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ رَفَعَ). 1.""مَرْفُوعُ الرَّأْسِ"" : عَالِي الرَّأْسِ. ""أُحِبُّ أَنْ أَمُوتَ مَرْفُوعَ العُيُونِ"". (عبد الرفيع جواهري). 2.""حَرْفٌ مَرْفُوعٌ"" : أَيْ فِي حَالَةِ الرَّفْعِ، عَلَيْهِ ضَمَّةٌ. 3.""حَدِيثٌ مَرْفُوعٌ"" : هُوَ مَا يَعْتَبِرُهُ الْمُحَدِّثُونَ مُتَّصِلَ الرِّوَايَةِ بِالنَّبِيِّ ( ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5171, 'مُرَقَّعٌ', 'مرقع', 'اسم مفعول', 'رقع', 'مرقع', 'مرقع', 'مفع. مِنْ رَقَّعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُرَقَّعٌ-مُرَقَّعٌ، ةٌ [ر ق ع] (مفع. مِنْ رَقَّعَ). ""ثَوْبٌ مُرَقَّعٌ"" : أَيْ ثَوْبٌ بِهِ رُقَعٌ. "" أَكْيَاسٌ مُرَقَّعَةٌ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5172, 'مُرَقَّقٌ', 'مرقق', 'اسم مفعول', 'رقق', 'مرقق', 'مرق', 'مفع. مِنْ رَقَّقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرَقَّقٌ-مُرَقَّقٌ، ةٌ [ر ق ق] (مفع. مِنْ رَقَّقَ). 1.""عُودٌ مُرَقَّقٌ"": مُلَيَّنٌ. 2.""صَوْتٌ مُرَقَّقٌ"" : غَيْرُ مُضَخَّمٍ. ""حَرْفٌ مُرَقَّقٌ"". 3.: رَغِيفٌ رَقِيقٌ مُنْبَسِطٌ وَوَاسِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5173, 'مُرَقَّمٌ', 'مرقم', 'اسم مفعول', 'رقم', 'مرقم', 'مرقم', 'مفع. مِنْ رَقَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُرَقَّمٌ-مُرَقَّمٌ، ةٌ [ر ق م] (مفع. مِنْ رَقَّمَ). ""أَوْرَاقٌ مُرَقَّمَةٌ"": أَيْ وُضِعَتْ عَلَيْهَا أَرْقَامٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5174, 'مَرْقُومٌ', 'مرقوم', 'اسم مفعول', 'رقم', 'مرقوم', 'مرقم', 'مفع. مِنْ رَقَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَرْقُومٌ-مَرْقُومٌ، ةٌ [ر ق م] (مفع. مِنْ رَقَمَ). 1.""ثَوْبٌ مَرْقُومٌ"" : مُخَطَّطٌ أَوْ مُطَرَّزٌ. 2.""كِتَابٌ مَرْقُومٌ"" : كِتَابٌ مَسْطُورٌ بَيِّنُ الكِتَابَةِ. ""مَا هُوَ مَرْقُومٌ يَدُومُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5175, 'مُرَكَّبٌ', 'مركب', 'اسم مفعول', 'ركب', 'مركب', 'مركب', 'مفع. مِنْ رَكِبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ رَكِبَ). 1.""جِهَازٌ مُرَكَّبٌ مِنْ عِدَّةِ أَجْزَاءٍ"" : مُكَوَّنٌ، مُؤَلَّفٌ. 2.""مُرَكَّبٌ صِنَاعِيٌّ"" : مُجَمَّعٌ يَضُمُّ عِدَّةَ أَنْوَاعٍ مِنَ الصِّنَاعَاتِ. 3.""مُرَكَّبٌ رِيَاضِيٌّ"" : مُجَمَّعٌ رِيَاضِيٌّ، أَيْ كُلُّ مَا هُوَ مُكَوَّنٌ مِنْ مَلاَعِبَ مُتَنَوِّعَةٍ فِي مَكَانٍ وَاحِدٍ. 4.""تَأَبَّطَ شَرّاً"" : اِسْمٌ مُرَكَّبٌ مُكَوَّنٌ مِنْ تَأَبَّطَ وشَرّاً. 5.""عَدَدٌ مُرَكَّبٌ"" : عَدَدٌ مُكَوَّنٌ مِنْ رَقْمَيْنِ أَوْ أَكْثَرَ. 6.""مُرَكَّبُ النَّقْصِ"" : هُوَ مَا يُعْرَفُ فِي عِلْمِ النَّفْسِ بِعُقْدَةِ النَّقْصِ، أَيْ إِحْسَاسُ الْمَرْءِ بِالنَّقْصِ عَنْ غَيْرِهِ. 7.""جَهْلٌ مُرَكَّبٌ"" : اِدِّعَاءُ الْمَرْءِ بِمَعْرِفَةِ الشَّيْءِ وَهُوَ يَجْهَلُ أَنَّهُ يَجْهَلُهُ. 8.""مُرَكَّبُ اسْتِعْلاَءٍ"" : تَصَوُّرُ الْمَرْءِ أَنَّهُ أَعْظَمُ مِنْ غَيْرِهِ. 9.""يَسِيرُ مِنَ البَسِيطِ إِلَى الْمُرَكَّبِ"": أَيْ إِلَى الْمُعَقَّدِ وَالصَّعْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5176, 'مَرْكُوبٌ', 'مركوب', 'اسم مفعول', 'ركب', 'مركوب', 'مركب', 'مفع. مِنْ رَكِبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَرَاكِيبُ"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ رَكِبَ). ""سَافَرَ عَلَى مَرْكُوبِهِ"" : كُلُّ مَا يُرْكَبُ حَيَوَاناً أَوْ عَرَبَةً أَوْ سَيَّارَةً أَوْ مَا شَابَهَ ذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5177, 'مُرَكَّزٌ', 'مركز', 'اسم مفعول', 'ركز', 'مركز', 'مركز', 'مفع. مِنْ رَكَّزَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرَكَّزٌ-مُرَكَّزٌ، ةٌ [ر ك ز] (مفع. مِنْ رَكَّزَ). 1.""عَمَلٌ مُرَكَّزٌ"": عَمَلٌ أُنْجِزَ بِانْتِبَاهٍ وَتَرْكِيزٍ. 2.""شَرَابٌ مُرَكَّزٌ"" : مُكَثَّفٌ. ""لَبَنٌ مُرَكَّزٌ"". 3.""أُسْلُوبٌ مُرَكَّزٌ"" : أُسْلُوبٌ لاحَشْوَ فِيهِ يُبَيِّنُ الْمَقْصُودَ مُبَاشَرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5178, 'مَرْمُوزٌ', 'مرموز', 'اسم مفعول', 'رمز', 'مرموز', 'مرمز', 'مفع. مِنْ رَمَزَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَرْمُوزٌ-مَرْمُوزٌ، ةٌ [ر م ز] (مفع. مِنْ رَمَزَ). 1.""مَرْمُوزٌ إِلَيْهِ بِعَلاَمَةِ كَذَا"" : مَنْ يَحْمِلُ عَلاَمَةً مَّا يُشَارُ بِهَا إِلَيْهِ، الْمُشَارُ إِلَيْهِ. 2.""أَمْرٌ مَرْمُوزٌ""(عس) : لَهُ دَلاَلَةٌ مَخْفِيَّةٌ، فَهْمُهُ يَقْتَضِي فَكَّ طَلاسِمِهِ. 3.""جِهَازٌ مَرْمُوزٌ"" : أَيْ لَهُ شَفْرَةٌ خَاصَّةٌ بِهِ لِحَلِّهِ وَالتَّعَامُلِ مَعَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5179, 'مُرَمَّشٌ', 'مرمش', 'اسم مفعول', 'رمش', 'مرمش', 'مرمش', 'مفع. مِنْ رَمَّشَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرَمَّشٌ-مُرَمَّشٌ [ر م ش] (مفع. مِنْ رَمَّشَ). ""مُرَمَّشُ العَيْنَيْنِ"": أَرْمَشُ، أَيْ بِعَيْنَيْهِ رَمَشٌ، اِحْمِرَارٌ مَعَ سَيَلاَنِ مَاءٍ مِنْهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5180, 'مَرْمُوقٌ', 'مرموق', 'اسم مفعول', 'رمق', 'مرموق', 'مرمق', 'مفع. مِنْ رَمَقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ رَمَقَ). 1.""رَجُلٌ مَرْمُوقٌ"": ذُو مَكَانَةٍ، ذُو مَنْزِلَةٍ عَالِيَةٍ. ""أَثَرٌ مَرْمُوقٌ"" ""مَكَانَةٌ مَرْمُوقَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5181, 'مُرَمَّمٌ', 'مرمم', 'اسم مفعول', 'رمم', 'مرمم', 'مرم', 'مفع. مِنْ رَمَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرَمَّمٌ-مُرَمَّمٌ، ةٌ [ر م م] (مفع. مِنْ رَمَّمَ). ""بَيْتٌ مُرَمَّمٌ"" : أَيْ بَيْتٌ أُجْرِيَتْ عَلَيْهِ إِصْلاَحَاتُ التَّرْمِيمِ. ""لَوْحَةٌ أَثَرِيَّةٌ مُرَمَّمَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5182, 'مَرْهُوبٌ', 'مرهوب', 'اسم مفعول', 'رهب', 'مرهوب', 'مرهب', 'مفع. مِنْ رَهِبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مَرْهُوبٌ-مَرْهُوبٌ [ر هـ ب] (مفع. مِنْ رَهِبَ). ""رَجُلٌ مَرْهُوبُ الجَانِبِ"" : رَجُلٌ يَخْشَى النَّاسُ جَانِبَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5183, 'مَرْهُونٌ', 'مرهون', 'اسم مفعول', 'رهن', 'مرهون', 'مرهن', 'مفع. مِنْ رَهَنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَرْهُونٌ-مَرْهُونٌ، ةٌ [ر هـ ن] (مفع. مِنْ رَهَنَ). 1.""مِلْكٌ مَرْهُونٌ"" : مُقَيَّدٌ بِـ... ""اِبْنَتُنَا مَرْهُونَةٌ عِنْدَ الْمُخْتَارِ، وَلاَ أَسْتَطِيعُ أَنْ أَتْرُكَهَا خَادِمَةً وَرَهِينَةً"". 2.""الأُمُورُ مَرْهُونَةٌ بِأَوْقَاتِهَا"" : أَيْ لَهَا زَمَانُهَا، وَمُرْتَبِطَةٌ بِنَتَائِجِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5184, 'مُرَوَّحٌ', 'مروح', 'اسم مفعول', 'روح', 'مروح', 'مرح', 'مفع. مِنْ رَوَّحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرَوَّحٌ-مُرَوَّحٌ [ر و ح] (مفع. مِنْ رَوَّحَ). ""مَكَانٌ مُرَوَّحٌ"" : عَطِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5185, 'مُرَوَّعٌ', 'مروع', 'اسم مفعول', 'روع', 'مروع', 'مرع', 'مفع. مِنْ رَوَّعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُرَوَّعٌ-مُرَوَّعٌ، ةٌ [ر و ع] (مفع. مِنْ رَوَّعَ). ""أَمْرٌ مُرَوَّعٌ"" : بِهِ هَلَعٌ وَرُعْبٌ وَذُعْرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5186, 'مُزَخْرَفٌ', 'مزخرف', 'اسم مفعول', 'زخرف', 'مزخرف', 'مزخرف', 'مفع. مِنْ زَخْرَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزَخْرَفٌ-مُزَخْرَفٌ، ةٌ [ز خ ر ف] (مفع. مِنْ زَخْرَفَ). 1.""فُسْتَانٌ مُزَخْرَفٌ"" : مُزَيَّنٌ بِأَلْوَانٍ شَتَّى. 2.""أُسْلُوبٌ مُزَخْرَفٌ"" : أُسْلُوبٌ يَتَضَمَّنُ تَعَابِيرَ وَأْلَفَاظاً مِنَ الْمُحَسِّنَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5187, 'مَزْرُوعٌ', 'مزروع', 'اسم مفعول', 'زرع', 'مزروع', 'مزرع', 'مفع. مِنْ زَرَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِنْ زَرَعَ). 1.""أَرْضٌ مَزْرُوعَةٌ خُضَراً وَقَمْحاً"" : مُلْقىً فِيهَا البَذْر لِيَنْبُتَ. 2.""قُنْبُلَةٌ مَزْرُوعَةٌ فِي الأَرْضِ"" : مَدْفُونَةٌ. ""أَلْغَامٌ مَزْرُوعَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5188, 'مُزَرْكَشٌ', 'مزركش', 'اسم مفعول', 'زركش', 'مزركش', 'مزركش', 'مفع. مِنْ زَرْكَشَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزَرْكَشٌ-مُزَرْكَشٌ، ةٌ [ز ر ك ش ] (مفع. مِنْ زَرْكَشَ). ""ثَوْبٌ مُزَرْكَشٌ"" : مُلَوَّنٌ بِعِدَّةِ أَلْوَانٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5189, 'مَزْعُومٌ', 'مزعوم', 'اسم مفعول', 'زعم', 'مزعوم', 'مزعم', 'مفع. مِنْ زَعَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَزْعُومٌ-مَزْعُومٌ [ز ع م] (مفع. مِنْ زَعَمَ). ""خَبَرٌ مَزْعُومٌ"" : غَيْرُ مَوْثُوقٍ بِهِ. ""زُهْدٌ مَزْعُومٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5190, 'مُزَفَّتٌ', 'مزفت', 'اسم مفعول', 'زفت', 'مزفت', 'مزفت', 'مفع. مِنْ زَفَّتَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزَفَّتٌ-مُزَفَّتٌ [ز ف ت] (مفع. مِنْ زَفَّتَ). ""طَرِيقٌ مُزَفَّتٌ"": مَرْصُوفٌ بِالزَّفْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5191, 'مَزْكُومٌ', 'مزكوم', 'اسم مفعول', 'زكم', 'مزكوم', 'مزكم', 'مفع. مِنْ زَكَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِنْ زَكَمَ). ""مَزْكُومٌ مُنْذُ أُسْبُوعٍ"" : مُصَابٌ بِالزُّكَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5192, 'مَزْمُومٌ', 'مزموم', 'اسم مفعول', 'زمم', 'مزموم', 'مزمم', 'مفع. مِنْ زَمَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَزْمُومٌ-مَزْمُومٌ، ةٌ [ز م م] (مفع. مِنْ زَمَّ). ""مَزْمُومُ الفَمِ"" : مَشْدُودٌ... ""شَفَتَاهُ مَزْمُومَتَانِ مُتَوَتِّرَتَانِ كَأَنَّهُمَا تَحْبِسَانِ كَلِمَةً تُرِيدُ أَنْ تَخْرُجَ"". (أحمد بوزفور)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5193, 'مُزَّمَّلٌ', 'مزمل', 'اسم مفعول', 'زمل', 'مزمل', 'مزمل', 'مفع. مِنْ زَمَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزَّمِّلٌ-مُزَّمِّلٌ [ز م ل] (فَا. مِن اِزَّمَّلَ). : سُورَةٌ مِنْ سُوَرِ القُرْآنِ:المزمل آية 1،2 يَا أَيُّهَا الْمُزَّمِّلُ، قُمِ اللَّيْلَ إِلاَّ قَلِيلاً (قرآن) : يَا أَيُّهَا الْمُتَلَفِّفُ، الْمُدَّثِّرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5194, 'مُزَوَّدٌ', 'مزود', 'اسم مفعول', 'زود', 'مزود', 'مزد', 'مفع. مِنْ زَوَّدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُزَوَّدٌ-مُزَوَّدٌ [ز و د] (مفع. مِنْ زَوَّدَ). 1.""مُزَوَّدٌ بِمَا يَحْتَاجُهُ فِي سَفَرِهِ"" : مُدَّ بِكُلِّ حَاجَاتِ السَّفَرِ. 2.""جَيْشٌ مُزَوَّدٌ بِأَسْلِحَةٍ حَدِيثَةٍ وَمُتَطَوِّرَةٍ"" : مُجَهَّزٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5195, 'مُزَوَّرٌ', 'مزور', 'اسم مفعول', 'زور', 'مزور', 'مزر', 'مفع. مِنْ زَوَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزَوَّرٌ-مُزَوَّرٌ، ةٌ [ز و ر] (مفع. مِنْ زَوَّرَ). 1.""نَقْدٌ مُزَوَّرٌ"" : مَغْشُوشٌ، مُزَيَّفٌ. 2.""إِمْضَاءٌ مُزَوَّرٌ"" : وَقَعَ تَزْوِيرُهُ، مُخَالِفٌ لِلأَصْلِ. ""وَثِيقَةٌ مُزَوَّرَةٌ"". 3.""شَهَادَةٌ مُزَوَّرَةٌ"" : كَاذِبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5196, 'مُزَوَّقٌ', 'مزوق', 'اسم مفعول', 'زوق', 'مزوق', 'مزق', 'مفع. مِنْ زَوَّقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزَوَّقٌ-مُزَوَّقٌ، ةٌ [ز و ق] (مفع. مِنْ زَوَّقَ). ""كِتَابٌ مُزَوَّقٌ"": مُزَخْرَفٌ، مَنْقُوشٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5197, 'مُزَيَّتٌ', 'مزيت', 'اسم مفعول', 'زيت', 'مزيت', 'مزت', 'مفع. مِنْ زَيَّتَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزَيَّتٌ-مُزَيَّتٌ، ةٌ [ز ي ت] (مفع. مِنْ زَيَّتَ). ""آلاَتٌ مُزَيَّتَةٌ"": آلاَتٌ وُضِعَ فِيهَا الزَّيْتُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5198, 'مُزَيَّفٌ', 'مزيف', 'اسم مفعول', 'زيف', 'مزيف', 'مزف', 'مفع. مِنْ زَيَّفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُزَيَّفٌ-مُزَيَّفٌ، ةٌ [ز ي ف] (مفع. مِنْ زَيَّفَ). 1.""نَقْدٌ مُزَيَّفٌ"" : مَغْشُوشٌ. ""بَطَائِقُ وَوَثَائِقُ مُزَيَّفَةٌ"". 2.""كَلاَمٌ مُزَيَّفٌ"" : بَاطِلٌ، كَاذِبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5199, 'مُزَيَّنٌ', 'مزين', 'اسم مفعول', 'زين', 'مزين', 'مزن', 'مفع. مِنْ زَيَّنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُزَيَّنٌ-مُزَيَّنٌ، ةٌ [ز ي ن] (مفع. مِنْ زَيَّنَ). 1.""جِدَارٌ مُزَيَّنٌ"": مُزَخْرَفٌ. ""شَوَارِعُ مُزَيَّنَةٌ بِالصُّوَرِ وَالرَّايَاتِ وَالأَضْوَاءِ"". 2.""كَلاَمٌ مُزَيَّنٌ يَجْذِبُكَ بِحُسْنِ إِيقَاعِهِ"" : حَسَنٌ، مُمَوَّهٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5200, 'مَسُودٌ', 'مسود', 'اسم مفعول', 'سود', 'مسود', 'مسد', 'مفع. مِن سَادَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن سَادَ). أَصْبَحَ السَّيِّدُ مَسُوداً وَالْمَخْدُومُ خَادِماً"" : خَاضِعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5201, 'مَسْؤُولٌ', 'مسؤول', 'اسم مفعول', 'سأل', 'مسءول', 'مسل', 'مفع. مِنْ سَأَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِنْ سَأَلَ). 1."" هُوَ مَسْؤُولٌ عَنْ عَائِلَتِهِ"" : رَاعِيهَا وَالسَّاهِرُ عَلَى شُؤُونِ مَعِيشَتِهَا، كَفِيلٌ. ""مَسْؤُولٌ عَنْ سَيْرِ الْمَعْمَلِ"". 2.""هُوَ الْمَسْؤُولُ الوَحِيدُ عَنِ الكَارِثَةِ"" : هُوَ الَّذِي تَقَعُ عَلَيْهِ تَبِعَاتُ الكَارِثَةِ"". 3.""هُوَ مِنْ بَيْنِ الْمَسْؤُولِينَ فِي البِلاَدِ"" : مِنْ بَيْنِ الَّذِينَ لَهُمْ مَسْؤُولِيَّاتٌ فِي جِهَازِ الدَّوْلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5202, 'مَسْبُوتٌ', 'مسبوت', 'اسم مفعول', 'سبت', 'مسبوت', 'مسبت', 'مفع. مِنْ سَبَتَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَسْبُوتٌ-مَسْبُوتٌ [س ب ت] (مفع. مِنْ سَبَتَ). 1.""وَجَدَهُ مَسْبُوتاً"" : مَغْشِيٌّ عَلَيْهِ. 2.""مِنْ بَيْنِ الْجَرْحَى جُنْدِيٌّ مَسْبُوتٌ"" : مَيِّتٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5203, 'مُسَبَّحٌ', 'مسبح', 'اسم مفعول', 'سبح', 'مسبح', 'مسبح', 'مفع. مِنْ سَبَّحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسَبَّحٌ-مُسَبَّحٌ [س ب ح] (مفع. مِنْ سَبَّحَ). ""ثَوْبٌ مُسَبَّحٌ"": نَسِيجُهُ قَوِيٌّ شَدِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5204, 'مُسَبَّعٌ', 'مسبع', 'اسم مفعول', 'سبع', 'مسبع', 'مسبع', 'مفع. مِنْ سَبَّعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسَبَّعٌ-مُسَبَّعٌ [س ب ع] (مفع. مِنْ سَبَّعَ). ""سَطْحٌ مُسَبَّعٌ "" (هن) : سَطْحٌ تُحِيطُ بِهِ سَبْعَةُ أَضْلاَعٍ مُتَسَاوِيَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5205, 'مُسَبَّقٌ', 'مسبق', 'اسم مفعول', 'سبق', 'مسبق', 'مسبق', 'مفع. مِنْ سَبَّقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسَبَّقٌ-مُسَبَّقٌ، ةٌ [س ب ق] (مفع. مِنْ سَبَّقَ). 1.""أَدَّى الثَّمَنَ مُسَبَّقاً"" : مُقَدَّماً، سَلَفاً. 2.""فِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5206, 'مَسْتُورٌ', 'مستور', 'اسم مفعول', 'ستر', 'مستور', 'مستر', 'مفع. مِن سَتَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مساتيرُ"', '', '', '', '', '', '', '', '', '"(مفع. مِن سَتَرَ). 1.""مَسْتُورٌ فِي بَيْتِهِ"" : الْمُخْتَفِي فِي بَيْتِهِ. 2.""مَسْتُورٌ عَنِ الأَنْظَارِ"" : بَعِيدٌ عَنِ الأَنْظَارِ لاَ أَحَدَ يَعْرِفُ عَنْهُ شَيْئاً، عَفِيفٌ. ""مَسْتُورٌ فِي مَعِيشَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5207, 'مَسَاتِيرُ', 'مساتير', 'اسم مفعول', '', 'مساتير', 'مستر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5208, 'مُسَتَّرَةٌ', 'مسترة', 'اسم مفعول', 'ستر', 'مسترة', 'مسترة', 'مفع. من سَتَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسَتَّرَةٌ-مُسَتَّرَةٌ [س ت ر] (مفع. من سَتَّرَ) ""اِمْرَأَةٌ مُسَتَّرَةٌ"" : مُحَجَّبَةٌ، مُتَوَارِيَةٌ فِي بَيْتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5209, 'مُسَجَّلٌ', 'مسجل', 'اسم مفعول', 'سجل', 'مسجل', 'مسجل', 'مفع. مِن سَجَّلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن سَجَّلَ). 1.""مُسَجَّلٌ فِي القَائِمَةِ"" : مُقَيَّدٌ بِهَا، مُدَوَّنٌ. 2.""اِخْتِرَاعٌ مُسَجَّلٌ"" : تَمَّ تَقْيِيدُهُ لِيَكْتَسِبَ صِفَةً رَسْمِيَّةً وَحَقَّ عَدَمِ التَّنَازُعِ فِيهِ. 3.""شَرِيطٌ مُسَجَّلٌ"" : شَرِيطٌ سُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5210, 'مَسْجُونٌ', 'مسجون', 'اسم مفعول', 'سجن', 'مسجون', 'مسجن', 'مفع. مِن سَجَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَسَاجِينُ"', '', '', '', '', '', '', '', '', '"(مفع. مِن سَجَنَ). ""أُفْرِجَ عَنِ الْمَسْجُونِ"" : الْمَحْبوسُ، السَّجِينُ."', '');
