INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5222, 'مُسَرَّحٌ', 'مسرح', 'اسم مفعول', 'سرح', 'مسرح', 'مسرح', 'مفع. مِن سَرَّحَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن سَرَّحَ). 1.""جُنْدِيٌّ مُسَرَّحٌ"" : مُعْفىً مِنَ الجُنْدِيَّةِ. 2.""مُسَرَّحٌ مِنَ الخِدْمَةِ"" : مُبْعَدٌ. ""عَامِلٌ مُسَرَّحٌ"". 3.""شَعْرٌ مُسَرَّحٌ"" : مُسْدَلٌ."', '');
