INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5243, 'مَسْلُوكٌ', 'مسلوك', 'اسم مفعول', 'سلك', 'مسلوك', 'مسلك', 'مفع. مِن سَلَكَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَسْلُوكٌ-مَسْلُوكٌ، ةٌ [س ل ك] (مفع. مِن سَلَكَ). ""طَرِيقٌ مَسْلُوكٌ"" : طَرِيقٌ يَسِيرُ فِيهِ النَّاسُ. ""الْمَسْلُوكُ مِنَ الطُّرُقِ""."', '');
