INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5245, 'مَسْمُومٌ', 'مسموم', 'اسم مفعول', 'سمم', 'مسموم', 'مسمم', 'مفع مِنْ سَمَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَسْمُومٌ، ةٌ - ج: ـون، ـات. [س م م]. (مفع مِنْ سَمَّ). 1.""طَعَامٌ مَسْمُومٌ"" : مَخْلُوطٌ بِالسُّمِّ. 2.""رَجُلٌ مَسْمُومٌ"": أَيْ مُؤْذٍ. ""أَنَا الْمَسْمُومُ مَا لِي تِرْيَاقٌ وَلاَ رَاقٍ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5246, 'مَسْمُوحٌ', 'مسموح', 'اسم مفعول', 'سمح', 'مسموح', 'مسمح', 'مفع. مِن سَمَحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَسْمُوحٌ-مَسْمُوحٌ [س م ح] (مفع. مِن سَمَحَ). ""مَسْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5247, 'مُسَمَّرٌ', 'مسمر', 'اسم مفعول', 'سمر', 'مسمر', 'مسمر', 'مفع. مِن سَمَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن سَمَّرَ). 1.""مُسَمَّرٌ فِي الْحَائِطِ"" : مُثَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5248, 'مَسْمُوعٌ', 'مسموع', 'اسم مفعول', 'سمع', 'مسموع', 'مسمع', 'مفع. مِن سَمِعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن سَمِعَ). 1.""رَأْيُهُ مَسْمُوعٌ"" : يُعْمَلُ بِهِ. 2.""رَجُلٌ مَسْمُوعُ الكَلِمَةِ"" : رَجُلٌ مُؤَثِّرٌ يُؤْخَذُ بِكَلاَمِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5249, 'مُسَمّىً', 'مسمى', 'اسم مفعول', 'سمي', 'مسمى', 'مسم', 'مفع. مِن سَمَّى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"مُسَمّىً-مُسَمّىً [س م ي] (مفع. مِن سَمَّى). 1.""الْمُسَمَّى فُلاَنٌ"" : الْمَدْعُو فُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5250, 'مُسَمّاة', 'مسماة', 'اسم مفعول', '', 'مسماة', 'مسمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسَمّىً-مُسَمّىً [س م ي] (مفع. مِن سَمَّى). 1.""الْمُسَمَّى فُلاَنٌ"" : الْمَدْعُو فُ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5251, 'مَسْنُونٌ', 'مسنون', 'اسم مفعول', 'سنن', 'مسنون', 'مسنن', 'مفع. مِن سَنَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَسْنُونٌ-مَسْنُونٌ [س ن ن] (مفع. مِن سَنَّ). ""سِكِّينٌ مَسْنُونٌ"": حَادٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5252, 'مُسَنَّنٌ', 'مسنن', 'اسم مفعول', 'سنن', 'مسنن', 'مسن', 'مفع. مِن سَنَّنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسَنَّنٌ-مُسَنَّنٌ، ةٌ [س ن ن] (مفع. مِن سَنَّنَ). ""رُمْحٌ مُسَنَّنٌ"": حَادُّ الرَّأْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5253, 'مُسَهَّدٌ', 'مسهد', 'اسم مفعول', 'سهد', 'مسهد', 'مسهد', 'مفع. مِن سَهَّدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(مفع. مِن سَهَّدَ). ""مُسَهَّدٌ فِي لَيَالِيهِ"" : قَلِيلُ النَّوْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5254, 'مُسَوَّرٌ', 'مسور', 'اسم مفعول', 'سور‎', 'مسور', 'مسر', 'مفع. مِنْ سَوَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسَوَّرٌ-مُسَوَّرٌ [س و ر‎] (مفع. مِنْ سَوَّرَ). ""مَنْزِلٌ مُسَوَّرٌ"" : مُحَاطٌ بِسِيَاجٍ، مُسَيَّجٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5255, 'مُسَوَّسٌ', 'مسوس', 'اسم مفعول', 'سوس', 'مسوس', 'مسس', 'مفع. مِن سَوَّسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسَوَّسٌ-مُسَوَّسٌ، ةٌ [س و س] (مفع. مِن سَوَّسَ). 1.""حِمَّصٌ مُسَوَّسٌ"" : دَخَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5256, 'مُسَيَّجٌ', 'مسيج', 'اسم مفعول', 'سيج', 'مسيج', 'مسج', 'مفع. مِن سَيَّجَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُسَيَّجٌ-مُسَيَّجٌ [س ي ج] (مفع. مِن سَيّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5257, 'مُسَيَّرٌ', 'مسير', 'اسم مفعول', 'سير', 'مسير', 'مسر', 'مفع. مِن سَيَّرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(مفع. مِن سَيَّرَ). 1.""هُوَ مُسَيَّرٌ لاَ مُخَيَّرٌ"" : أَعْمالُهُ وَأَفْعالُهُ خارِجَةٌ عَنْ إِرادَتِهِ الفِعْلِيَّةِ، وَلاَ سَيْطَرَةَ لَهُ عَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5258, 'مَشُوبٌ', 'مشوب', 'اسم مفعول', 'شوب', 'مشوب', 'مشب', 'مفع. مِن شَابَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن شَابَ). 1.""مَشُوبٌ بِالخَوْفِ وَالاِلْتِبَاسِ"" : مُخْتَلِطٌ. 2.""مَشُوبٌ بالغُموضِ"" : مُلْتَبِسٌ. ""كَانَ أَحَدُهُمَا مُغْرِياً بِالرَّجَاءِ وَالآخَرُ مَشُوباً بِاليَأْسِ وَالرِّيبَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5259, 'مَشْؤُومٌ', 'مشؤوم', 'اسم مفعول', 'شأم', 'مشءوم', 'مشم', 'مفع. مِن شَأَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَشَائيِمُ"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن شَأَمَ). ""رَجُلٌ مَشْؤُومٌ"" : رَجُلٌ يَجُرُّ الشُّؤْمَ. ""لاَ يَزَالُ يَذْكُرُ ذَلِكَ اليَوْمَ الْمَشْؤُومَ يَوْمَ الكَارِثَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5260, 'مَشَائيِمُ', 'مشائيم', 'اسم مفعول', '', 'مشاءيم', 'مشم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5261, 'مُشَاهَدٌ', 'مشاهد', 'اسم مفعول', 'شهد', 'مشاهد', 'مشهد', 'مفع. مِن شَاهَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُشَاهَدٌ-مُشَاهَدٌ، ةٌ [ش هـ د] (مفع. مِن شَاهَدَ). ""مُشَاهَدٌ مِنْ بَعِيدٍ"" : مَا يُرَى مِنْ بَعِيدٍ. ""مُشَاهَدٌ بِالعَيْنِ الْمُجَرَّدَةِ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5262, 'مَشْبُوبٌ', 'مشبوب', 'اسم مفعول', 'شبب', 'مشبوب', 'مشبب', 'مفع. مِن شَبَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مَشَابِيبُ"', '', '', '', '', '', '', '', '', '"(مفع. مِن شَبَّ). 1.""وَلَدٌ مَشْبُوبٌ"" : ذَكِيٌّ، شَهْمٌ. 2.""مَشْبُوبُ الوَجْهِ"": حَسَنُهُ ""يَتَمَتَّعُ بِحَيَوِيَّةٍ مَشْبُوبَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5263, 'مَشَابِيبُ', 'مشابيب', 'اسم مفعول', '', 'مشابيب', 'مشبب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5264, 'مُشَبَّكٌ', 'مشبك', 'اسم مفعول', 'شبك', 'مشبك', 'مشبك', 'مفع. مِن شَبَّكَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَبَّكٌ-مُشَبَّكٌ، ةٌ [ش ب ك] (مفع. مِن شَبَّكَ) 1.""عَمَلٌ مُشَبَّكٌ"" : مُتَدَاخِلٌ. 2.""يُعْجِبُهُ طَعْمُ الْمُشَبَّكِ"" : حَلْوَى عَلَى هَيْئَةِ عِيدَانٍ مُتَشَابِكَةٍ تُصْنَعُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5265, 'مُشَبَّهٌ', 'مشبه', 'اسم مفعول', 'شبه', 'مشبه', 'مشبه', 'مفع. مِن شَبَّهَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن شَبَّهَ). 1.""طَرَفَا التَّشْبِيهِ هُمَا الْمُشَبَّهُ وَالْمُشَبَّهُ بِهِ"" : فِي عِلْمِ البَيَانِ الْمُش"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5266, 'مَشْبُوهٌ', 'مشبوه', 'اسم مفعول', 'شبه', 'مشبوه', 'مشبه', 'مفع. مِن شَبَهَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مَشْبُوهٌ-مَشْبُوهٌ، ةٌ [ش ب هـ] (مفع. مِن شَبَهَ). ""رَجُلٌ مَشْبُوهٌ"" : مَنْ يُشَكُّ فِيهِ، الْمَشْكُوكُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5267, 'مُشَتَّتٌ', 'مشتت', 'اسم مفعول', 'شتت', 'مشتت', 'مشت', 'مفع. مِن شَتَّتَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن شَتَّتَ). 1.""مُشَتَّتُ الذِّهْنِ"" : الشَّارِدُ، مَنْ يُفَكِّرُ فِي أَشْيَاءٍ كَثِيرَةٍ فِي آنٍ وَاحِدٍ. ""مُشَتَّتُ الفِكْرِ خَائِرُ القُوَى"". 2.""أَثَاثٌ مُشَتَّتٌ"" : مُوَزَّعٌ، مُتَفَرِّقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5268, 'مُشَجَّرٌ', 'مشجر', 'اسم مفعول', 'شجر', 'مشجر', 'مشجر', 'مفع. مِن شَجَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَجَّرٌ-مُشَجَّرٌ، ةٌ [ش ج ر] (مفع. مِن شَجَّرَ). 1.""مَكَانٌ مُشَجَّرٌ"" : مَزْرُوعٌ شَجَراً. 2.""ثَوْبٌ مُشَجَّرٌ"" : مُوَشَّى بِشُجَيْرَاتٍ. 3.""خَطٌّ مُشَجَّرٌ"" : كِتَابَتُهُ صِينِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5269, 'مَشْحُوذٌ', 'مشحوذ', 'اسم مفعول', 'شحذ', 'مشحوذ', 'مشحذ', 'مفع. مِن شَحَذَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَشْحُوذٌ-مَشْحُوذٌ، ةٌ [ش ح ذ] (مفع. مِن شَحَذَ). ""سِكِّينٌ مَشْحُوذٌ"" : أَيْ شُحِذَ، سُنَّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5270, 'مَشْحُونٌ', 'مشحون', 'اسم مفعول', 'شحن', 'مشحون', 'مشحن', 'مفع. مِن شَحَنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَشْحُونٌ-مَشْحُونٌ، ةٌ [ش ح ن] (مفع. مِن شَحَنَ). 1.""صَدْرُهُ مَشْحُونٌ بِالكَرَاهِيَةِ"" : مَمْلُوءٌ. ""هَلُمُّوا نَخْرُج مِنْ هَذَا الْمَكَانِ الْمَشْحُونِ بِالآثَامِ وَالْمَعَاصِي"". (جبران خ. جبران). 2.""بِضَاعَةٌ مَشْحُونَةٌ إِلَى الخَارِجِ"" : أَيْ ت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5271, 'مَشْدُودٌ', 'مشدود', 'اسم مفعول', 'شدد', 'مشدود', 'مشدد', 'مفع. مِن شَدَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن شَدَّ). 1.""حَبْلٌ مَشْدُودٌ"" : أَيْ حَبْلٌ تَمَّ مَدُّهُ وَجَذْبُهُ. 2.""مَشْدُودُ اليَدَيْنِ وَالرِّجْلَيْنِ"" : مُقَيَّدٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5272, 'مُشَدَّدٌ', 'مشدد', 'اسم مفعول', 'شدد', 'مشدد', 'مشد', 'مفع. مِن شَدَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَدَّدٌ، ةٌ - [ش د د]. (مفع. مِن شَدَّدَ). 1.""إِجْرَاءٌ مُشَدَّدٌ"" : إِجْرَاءٌ فِيهِ قَسْوَةٌ وَشِدَّةٌ.   ""اِتَّخَذَ إِجْرَاءاتٍ مُشَدَّدَةً"". 2.""حَرْفٌ مُشَدَّدٌ"" : مُضَعَّفٌ، أَيْ عَلَيْهِ عَلاَمَةُ الشَّدَّةِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5273, 'مُشَذَّبٌ', 'مشذب', 'اسم مفعول', 'شذب', 'مشذب', 'مشذب', 'مفع. مِن شَذَّبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَذَّبٌ-مُشَذَّبٌ، ةٌ [ش ذ ب] (مفع. مِن شَذَّبَ). ""شَجَرٌ مُشَذَّبٌ"" : أَيْ أُزِيلَ مَا عَلَيْهِ مِنْ أَغْصَانٍ وَأَوْرَاقٍ. ""أَغْصَانٌ مُشَذَّبَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5274, 'مَشْرُوبٌ', 'مشروب', 'اسم مفعول', 'شرب', 'مشروب', 'مشرب', 'مفع. من شَرِبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مشاريبُ"', '', '', '', '', '', '', '', '', '"(مفع. من شَرِبَ). 1. ""مَشْرُوبٌ مُرَطِّبٌ"" : كُلُّ مَا يُشْرَبُ مِنْ مَاءٍ أَوْ عَصِيرٍ أَوْ كُحُولٍ. 2. ""مَشْرُوبَاتٌ رُوحِيَّةٌ"" : أَيْ مُسْكِرَةٌ بِهَا كُحُولٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5275, 'مَشَارِيبُ', 'مشاريب', 'اسم مفعول', '', 'مشاريب', 'مشرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5276, 'مَشْرُوطٌ', 'مشروط', 'اسم مفعول', 'شرط', 'مشروط', 'مشرط', 'مفع. مِنْ شَرَطَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَشْرُوطٌ-مَشْرُوطٌ، ةٌ [ش ر ط] (مفع. مِنْ شَرَطَ). ""حُضُورُكَ مَعَنَا مَشْرُوطٌ بِعِدَّةِ شُرُوطٍ"" : مَرْهُونٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5277, 'مَشْرُوعٌ', 'مشروع', 'اسم مفعول', 'شرع', 'مشروع', 'مشرع', 'مفع. مِنْ شَرَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مشاريعُ"', '', '', '', '', '', '', '', '', '"مَشْرُوعٌ-مَشْرُوعٌ، ةٌ [ش ر ع] (مفع. مِنْ شَرَعَ). 1."" عَمَلٌ مَشْرُوعٌ"" : عَمَلٌ مُسَوَّغٌ، أَيْ مَا سَوَّغَهُ الشَّرْعُ. 2.""اِسْتَخْدَمَ طُرُقاً مَشْرُوعَةً"" : طُرُقاً مَسْمُوحاً بِهَا. 3.""حَضَّرَ مَشْرُوعاً جَدِيداً"" : مَا يُحَضَّرُ فِي مَجَالٍ مِنَ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5278, 'مَشَارِيعُ', 'مشاريع', 'اسم مفعول', '', 'مشاريع', 'مشرع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5279, 'مُشَطَّبٌ', 'مشطب', 'اسم مفعول', 'شطب', 'مشطب', 'مشطب', 'مفع. مِن شَطَّبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن شَطَّبَ). 1.""وَجْهٌ مُشَطَّبٌ"" : فِيهِ أَثَرُ جُرْحِ أَظَافِرٍ، أَوْ جُرْحِ سِكِّيٍن وَنَحْوِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5280, 'مَشْطُوبٌ', 'مشطوب', 'اسم مفعول', 'شطب', 'مشطوب', 'مشطب', 'مفع. من شَطَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَشْطُوبٌ-مَشْطُوبٌ، ةٌ [ش ط ب] (مفع. من شَطَبَ). 1.""رَقْمٌ مَشْطُوبٌ"" : أَيْ خُطَّ عَلَيْهِ خَطٌّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5281, 'مَشْطُورٌ', 'مشطور', 'اسم مفعول', 'شطر', 'مشطور', 'مشطر', 'مفع. مِن شَطَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَشْطُورٌ-مَشْطُورٌ، ةٌ [ش ط ر] (مفع. مِن شَطَرَ). 1. ""لَوْحٌ مَشْطُورٌ"" : أَيْ قُسِمَ إِلَى نِصْفَيْنِ. 2.""قَصِيدَةٌ مِنْ مَشْطُورِ السَّرِيعِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5282, 'مُشَعَّثٌ', 'مشعث', 'اسم مفعول', 'شعث', 'مشعث', 'مشعث', 'مفع. مِن شَعَّثَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن شَعَّثَ). 1. ""شَعْرٌ مُشَعَّثٌ"" : مُتَلَبِّدٌ. 2. ""مُشَعَّثُ الشَّعْرِ"" : مُلَبَّدٌ، أَيْ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5283, 'مَشْغُوفٌ', 'مشغوف', 'اسم مفعول', 'شغف', 'مشغوف', 'مشغف', 'مفع. مِن شَغَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن شَغَفَ). ""قَلْبٌ مَشْغُوفٌ"" : مُصَابٌ بِالحُبِّ، مُولَعٌ بِهِ. ""أَقْبَلَ عَلَيْهَا مَشْغُوفاً بِهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5284, 'مَشْغُولٌ', 'مشغول', 'اسم مفعول', 'شغل', 'مشغول', 'مشغل', 'مفع. مِن شَغَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن شَغَلَ). 1.""بَيْتٌ مَشْغُولٌ"" : مَسْكُونٌ، أَيْ فِيهِ سُكَّانُهُ. 2.""مَشْغُولُ البَالِ"" : قَلِقٌ، مَهْمُومٌ. 3.""رَجُلٌ مَشْغُولٌ عَلَى الدَّوَامِ"" : دَائِمُ العَمَلِ، لاَ فَرَاغَ عِنْدَهُ. 4.""اِمْرَأَةٌ مَشْغُولَةٌ"" : لَهَا زَوْجٌ. 5.""مَنْصِبٌ مَشْغُولٌ"" : أَيْ مُحْتَلٌّ وَلَيْسَ بِشَاغِرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5285, 'مشاغيل', 'مشاغيل', 'اسم مفعول', '', 'مشاغيل', 'مشغل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5286, 'مَشْقُوقٌ', 'مشقوق', 'اسم مفعول', 'شقق', 'مشقوق', 'مشقق', 'مفع. مِن شَقَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَشْقُوقٌ-مَشْقُوقٌ [ش ق ق] (مفع. مِن شَقَّ). 1.""إِنَاءٌ مَشْقُوقٌ"" : بِهِ انْكِسَارٌ مَفْلُوقٌ. 2."" بَابٌ مَشْقُوقٌ"" : بِهِ انْكِسَارٌ مَفْتُوحٌ قَلِيلاً. 3.""شَفَةٌ مَشْقُوقَةٌ"" : مَفْلُوقَةٌ. 4.""تَنُّورَةٌ مَشْقُوقَةٌ مِنَ الْخَلْفِ"" : مَفْتُوحَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5287, 'مُشَقَّقٌ', 'مشقق', 'اسم مفعول', 'شقق', 'مشقق', 'مشق', 'مفع. مِن شَقَّقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَقَّقٌ-مُشَقَّقٌ [ش ق ق] (مفع. مِن شَقَّقَ). 1.""حَائِطٌ مُشَقَّقٌ"" : مُتَصَدِّعٌ، مُتَشَقِّقٌ. 2.""نَبَاتٌ مُشَقَّقٌ"" : مُنْفَطِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5288, 'مَشْكُوكٌ', 'مشكوك', 'اسم مفعول', 'شكك', 'مشكوك', 'مشكك', 'مفع. مِن شَكَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَشْكُوكٌ-مَشْكُوكٌ [ش ك ك] (مفع. مِن شَكَّ). ""مَشْكُوكٌ فِيهِ"": مُشْتَبَهٌ فِيهِ، مُرْتَابٌ فِي أَمْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5289, 'مُشَكَّلٌ', 'مشكل', 'اسم مفعول', 'شكل', 'مشكل', 'مشكل', 'مفع. مِن شَكَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَكَّلٌ-مُشَكَّلٌ، ةٌ [ش ك ل] (مفع. مِن شَكَّلَ). 1.""عَمَلٌ مُشَكَّلٌ"" : مُتَنَوِّعٌ. 2.""نَصٌّ مُشَكَّلٌ"" : عَلَيْهِ حَرَكَاتُ الشَّكْلِ. 3.مَجْلِسٌ مشَكَّلٌ مِنْ كَذَا"" : مُكَوَّنٌ، مُؤَلَّفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5290, 'مَشْكُولٌ', 'مشكول', 'اسم مفعول', 'شكل', 'مشكول', 'مشكل', 'مفع. مِن شَكَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَشْكُولٌ-مَشْكُولٌ، ةٌ [ش ك ل] (مفع. مِن شَكَّلَ). 1.""حِمَارٌ مَشْكُولٌ"" : مَرْبُوطٌ مِنْ رِجْلَيْهِ. 2.""نَصٌّ مَشْكُولٌ"" : مُشَكَّلٌ بِالْحَرَكاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5291, 'مَشْلُولٌ', 'مشلول', 'اسم مفعول', 'شلل', 'مشلول', 'مشلل', 'مفع. مِن شَلَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن شَلَّ). 1. ""مَشْلُولَ اليَدِ"" : أَيْ أُصِيبَ بِالشَّلَلِ فِي يَدِهِ. ""يَدٌ مَشْلُولَةٌ"". 2.""مَشْلُولُ التَّفْكيرِ"" : مُتَوَقِّفٌ، مُتَعَطِّلٌ. ""ظَلَّ زَائِغَ البَصَرِ، مَشْلُولَ التَّفْكِيرِ"". (ع. غلاب)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5292, 'مَشْمُومٌ', 'مشموم', 'اسم مفعول', 'شمم', 'مشموم', 'مشمم', 'مفع. من شَمَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَشْمُومٌ-مَشْمُومٌ [ش م م] (مفع. من شَمَّ). 1. كُلُّ مَا يُدْرَكُ بِا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5293, 'مُشَمَّسٌ', 'مشمس', 'اسم مفعول', 'شمس', 'مشمس', 'مشمس', 'مفع. من شَمَّسَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من شَمَّسَ). ""مُشَمَّسٌ فِي الْهَوَاءِ الطَّلْقِ"" : مَبْسُوطٌ مُعَرَّضٌ لِلشَّمْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5294, 'مَشْمُولٌ', 'مشمول', 'اسم مفعول', 'شمل', 'مشمول', 'مشمل', 'مفع. من شَمَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من شَمَلَ). 1. ""مَشْمُولٌ بِرِعَايَةِ اللهِ"" : مُحَاطٌ، مُغَطًّى. 2.""لَيْلَةٌ مَشْمُولَةٌ"" : بَارِدَةٌ بُرُودَةً مُعْتَدِلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5295, 'مُشَنَّجٌ', 'مشنج', 'اسم مفعول', 'شنج', 'مشنج', 'مشنج', 'مفع. من شَنَّجَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَنَّجٌ-مُشَنَّجٌ، ةٌ [ش ن ج] (مفع. من شَنَّجَ). 1.""وَجْهٌ مُشَنَّجٌ"" : مُقَبَّضٌ، ويُقَالُ لِلْمُبَال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5296, 'مَشْنُوقٌ', 'مشنوق', 'اسم مفعول', 'شنق', 'مشنوق', 'مشنق', 'مفع. من شَنَقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من شَنَقَ). ""مَشْنُوقٌ بِحَبْلٍ"" : مَنْ تَمَّ شَنْقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5297, 'مَشْهُودٌ', 'مشهود', 'اسم مفعول', 'شهد', 'مشهود', 'مشهد', 'مفع. من شَهِدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَشْهُودٌ-مَشْهُودٌ [ش هـ د] (مفع. من شَهِدَ). 1.""عَاشَ يَوْماً مَشْهُوداً"" : يَوْماً لَهُ أَهَمِّيَّةٌ كَبِيرَةٌ وتَارِيخِيَّةٌ. 2.""الجُرْمُ الْمَشْهُودُ"": جُرْمٌ يُرْتَكَبُ بِمَرْأَى النَّاسِ. 3.""اليَوْمُ الْمَشْهُودُ"" : يَوْمُ القِيَامَةِ، كَمَا يُطْلَقُ عَلَى يَوْمِ الجُمُعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5298, 'مَشْهُورٌ', 'مشهور', 'اسم مفعول', 'شهر', 'مشهور', 'مشهر', 'مفع. من شَهَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَشَاهِيرُ"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من شَهَرَ). ""كَاتِبٌ مَشْهُورٌ"" : مَعْرُوفٌ عَلَى نِطَاقٍ وَاسِعٍ، شَهِيرٍ، ذُو صِيتٍ. ""وَلاَ بُدَّ لِطَالِبِ العِلْمِ أَنْ لاَ يُفَرِّقَ بَيْنَ شَيْخٍ مَشْهُورٍ وَآخَرَ غَيْرِ مَعْرُوفٍ"". (الغزالي). ""مَشَاهيرُ التَّارِيخِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5299, 'مَشَاهِيرُ', 'مشاهير', 'اسم مفعول', '', 'مشاهير', 'مشهر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5300, 'مُشَوَّشٌ', 'مشوش', 'اسم مفعول', 'شوش', 'مشوش', 'مشش', 'مفع. مِن شَوَّشَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَوَّشٌ-مُشَوَّشٌ [ش و ش] (مفع. مِن شَوَّشَ). ""كَلاَمٌ مُشَوَّشٌ"" : كَلاَمٌ غَيْرُ وَاضِحٍ، غَامِضٌ، مُبْهَمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5301, 'مُشَوَّهٌ', 'مشوه', 'اسم مفعول', 'شوه', 'مشوه', 'مشه', 'مفع. مِن شَوَّهَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن شَوَّهَ). ""مُشَوَّهُ الخِلْقَةِ"" : قَبِيحُ الخِلْقَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5302, 'مُشَيَّدٌ', 'مشيد', 'اسم مفعول', 'شيد', 'مشيد', 'مشد', 'مفع. مِنْ شَيَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَيَّدٌ-مُشَيَّدٌ، ةٌ [ش ي د] (مفع. مِنْ شَيَّدَ). ""بِنَاءٌ مُشَيَّدٌ"" : قَائِمٌ، مُرْتَفِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5303, 'مُشَيَّعٌ', 'مشيع', 'اسم مفعول', 'شيع', 'مشيع', 'مشع', 'مفع. مِن شَيَّعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُشَيَّعٌ-مُشَيَّعٌ، ةٌ [ش ي ع] (مفع. مِن شَيَّعَ). ""خَبَرٌ مُشَيَّعٌ بَيْنَ النَّاسِ"" : ذَائِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5304, 'مُصَادَرٌ', 'مصادر', 'اسم مفعول', 'صدر', 'مصادر', 'مصدر', 'مفع. مِن صَادَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن صَادَرَ). ""أَثَاثٌ مُصَادَرٌ"" : مُنْتَزَعٌ لِسَبَبٍ مَّا. ""أَمْلاكٌ مُصَادَرَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5305, 'مُصَادَقٌ', 'مصادق', 'اسم مفعول', 'صدق', 'مصادق', 'مصدق', 'مفع. مِن صَادَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ح"', '', '', '', '', '', '', '', '', '"(مفع. مِن صَادَقَ). ""عَقْدٌ مُصَادَقٌ عَلَيْهِ"" : أَيْ مُثْبَتٌ صِحَّتُهُ وَمُوَافَقٌ عَلَيْهِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5306, 'مَصْبُوبٌ', 'مصبوب', 'اسم مفعول', 'صبب', 'مصبوب', 'مصبب', 'مفع. مِن صَبَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن صَبَّ). 1.""مَاءٌ مَصْبُوبٌ"" : مَا يُصَبُّ مِنْهُ. 2.""مَصْبُوبُ مَعْدِنٍ"" : مَايُصَبُّ مِنْ مَعْدِنٍ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5307, 'مَصْحُوبٌ', 'مصحوب', 'اسم مفعول', 'صحب', 'مصحوب', 'مصحب', 'مفع. مِن صَحِبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن صَحِبَ) .""سَافَرَ مَصْحُوباً بِسَلاَمَةِ الله"" : مُرْفَقاً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5308, 'مُصَحَّحٌ', 'مصحح', 'اسم مفعول', 'صحح', 'مصحح', 'مصح', 'مفع. مِن صَحَّحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن صَحَّحَ) .""نَصٌّ مُصَحَّحٌ"" : أَيْ وَقَعَ تَصْحِيحُهُ. ""أَوْرَاقُ الامْتِحَانِ مُصَحَّحَةٌ"" ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5309, 'مُصَدَّرٌ', 'مصدر', 'اسم مفعول', 'صدر', 'مصدر', 'مصدر', 'مفع. مِن صَدَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَدَّرٌ-مُصَدَّرٌ، ةٌ [ص د ر] (مفع. مِن صَدَّرَ). ""قَمْحٌ مُصَدَّرٌ إِلَى الخَارِجِ"" : أَيْ مُرْسَلٌ إِلَى الخَارِجِ بِقَصْدِ التِّجَارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5310, 'مَصْدُورٌ', 'مصدور', 'اسم مفعول', 'صدر', 'مصدور', 'مصدر', 'مفع. مِن صَدَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَصْدُورٌ-مَصْدُورٌ [ص د ر] (مفع. مِن صَدَرَ). ""مَرِيضٌ مَصْدُورٌ"" : مَرِيضٌ بِالسُّلِّ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5311, 'مَصْدُوعٌ', 'مصدوع', 'اسم مفعول', 'صدع', 'مصدوع', 'مصدع', 'مفع. مِن صَدَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَصْدُوعٌ-مَصْدُوعٌ [ص د ع] (مفع. مِن صَدَعَ). 1.""جِدَارٌ مَصْدُوع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5312, 'مُصَدَّقٌ', 'مصدق', 'اسم مفعول', 'صدق', 'مصدق', 'مصدق', 'مفع. مِن صَدَّقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن صَدَّقَ). 1.""رَسُولٌ مُصَدَّقٌ"" : مَوْثُوقٌ بِصِدْقِهِ. 2.""قَانُونٌ مُصَدَّقٌ عَلَيْهِ"" : مُوَافَقٌ عَلَيْه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5313, 'مُصَرَّحٌ', 'مصرح', 'اسم مفعول', 'صرح', 'مصرح', 'مصرح', 'مفع. من صَرَّحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَرَّحٌ-مُصَرَّحٌ [ص ر ح] (مفع. من صَرَّحَ). 1.""اِتِّفَاقٌ مُصَرَّحٌ بِهِ"" : مُعْلَنٌ عَنْهُ. 2.""بَضَائِعُ مُصَرَّحٌ بِاسْتِيرَادِهَا "" : مُرَخَّصٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5314, 'مَصْرُوعٌ', 'مصروع', 'اسم مفعول', 'صرع', 'مصروع', 'مصرع', 'مفع. من صَرَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". (مفع. من صَرَعَ). ""وَضَعَ الْمَصْرُوعُ يَدَهُ فَوْقَ قَلْبِهِ الْمَطْعُونِ"" : مَنْ وَقَعَ صَرْعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5315, 'مُصَرَّفٌ', 'مصرف', 'اسم مفعول', 'صرف', 'مصرف', 'مصرف', 'مفع. مِن صَرَّفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَرَّفٌ-مُصَرَّفٌ [ص ر ف] (مفع. مِن صَرَّفَ). ""فِعْلٌ مُصَرَّفٌ"" : مَا تَمَّ تَصْرِيفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5316, 'مَصْرُوفٌ', 'مصروف', 'اسم مفعول', 'صرف', 'مصروف', 'مصرف', 'مفع. مِن صَرَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مَصَارِيفُ"', '', '', '', '', '', '', '', '', '"(مفع. مِن صَرَفَ). 1.""مَصْرُوفُ الْمَعِيشَةِ"" : مَا يُنْفَقُ مِنْ أَجْلِ العَيْشِ. 2. ""مَصْرُوفٌ يَوْمِيٌّ"" : مَا يُنْفَقُ فِي اليَوْمِ. 3.""مَصْرُوفُ الجَيْبِ"" : مَا يُنْفَقُ لِقَضَاءِ حَاجَاتٍ طَارِئَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5317, 'مَصَارِيفُ', 'مصاريف', 'اسم مفعول', '', 'مصاريف', 'مصرف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5318, 'مُصَعَّرٌ', 'مصعر', 'اسم مفعول', 'صعر', 'مصعر', 'مصعر', 'مفع. مِن صَعَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن صَعَّرَ). ""مُصَعَّرُ الخَدِّ "": مُتَكَبِّرٌ، مُتَعَجْرِفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5319, 'مَصْعُوقٌ', 'مصعوق', 'اسم مفعول', 'صعق', 'مصعوق', 'مصعق', 'مفع. مِن صَعِقَ ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن صَعِقَ ). 1. ""وَجَدَهُ مَصْعُوقاً تَحْتَ الشَّجَرَةِ"" : مَغْشِيّاً عَلَيْهِ. 2. ""تَرَكَتْهُ الصَّاعِقَةُ مَصْعُوقاً"" : مَنْ أَصَابَتْهُ الصَّاعِقَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5320, 'مُصَغَّرٌ', 'مصغر', 'اسم مفعول', 'صغر', 'مصغر', 'مصغر', 'مفع. مِن صَغَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَغَّرٌ-مُصَغَّرٌ، ةٌ [ص غ ر] (مفع. مِن صَغَّرَ). ""رَسْمٌ مُصَغَّرٌ"": رَسْمٌ قُلِّصَ حَجْمُهُ، أيْ تَمَّ تَصْغِيرُهُ. ""صُورَةٌ مُصَغَّرَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5321, 'مُصَفَّحٌ', 'مصفح', 'اسم مفعول', 'صفح', 'مصفح', 'مصفح', 'مفع. مِن صَفَّحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن صَفَّحَ). 1.""مُصَفَّحُ الوَجْهِ"" : عَرِيضُ الوَجْهِ. 2.""مُصَفَّحٌ بِحَدِيدٍ"" : مُغَشَّى بِصَفَائِحَ مِنْ حَدِيدٍ. 3.""جَوَادٌ مُصَفَّحٌ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5322, 'مُصَفَّفٌ', 'مصفف', 'اسم مفعول', 'صفف', 'مصفف', 'مصف', 'مفع. مِن صَفَّفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن صَفَّفَ). ""مُصَفَّفُ الشَّعْرِ"" : مَنْ كَانَ شَعْرُ رَأْسِهِ مُنَسَّقاً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5323, 'مُصَفًّى', 'مصفى', 'اسم مفعول', 'صفو', 'مصفى', 'مصف', 'مفع. مِن صَفَّى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"مُصَفَّى-مُصَفَّى [ص ف و] (مفع. مِن صَفَّى). 1.""مَاءٌ مُصَفَّى"" : كُلُّ مَاءٍ تَمَّتْ تَصْفِيَتُهُ مِنَ الأَمْلاَحِ وَالجَرَاثِيمِ وَمَا عَلِقَ بِهِ. 2.""نَفْطٌ مُصَفَّى"" : مُكَرَّرٌ، أَيْ تَمَّ تَكْرِيرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5324, 'مُصَفاة', 'مصفاة', 'اسم مفعول', '', 'مصفاة', 'مصفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَفَّى-مُصَفَّى [ص ف و] (مفع. مِن صَفَّى). 1.""مَاءٌ مُصَفَّى"" : كُلُّ مَاءٍ تَمَّتْ تَصْفِيَتُهُ مِنَ الأَمْلاَحِ وَالجَرَاثِيمِ وَمَا عَلِقَ بِهِ. 2.""نَفْطٌ مُصَفَّى"" : مُكَرَّرٌ، أَيْ تَمَّ تَكْرِيرُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5325, 'مَصْقُولٌ', 'مصقول', 'اسم مفعول', 'صقل', 'مصقول', 'مصقل', 'مفع. من صَقَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من صَقَلَ). 1.""اِبْنُهُ مَصْقُولُ التَّرْبِيَةِ"" : مُهَذَّبٌ. 2.""وَرَقٌ مَصْقُولٌ"": شَفَّافٌ لاَمِعٌ. 3.""إِنَاءٌ مَصْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5326, 'مُصَلَّبٌ', 'مصلب', 'اسم مفعول', 'صلب', 'مصلب', 'مصلب', 'مفع. من صَلَّبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من صَلَّبَ). 1. ""رَجُلٌ مُصَلَّبٌ"" : رَجُلٌ تَمَّ تَصْلِيبُهُ. 2.""ثَوْبٌ مُصَلَّبٌ"" : عَلَيْهِ نَقْشٌ كَالصَّلِيبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5327, 'مَصْلُوبٌ', 'مصلوب', 'اسم مفعول', 'صلب', 'مصلوب', 'مصلب', 'مفع. من صَلَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من صَلَبَ). 1.""وَجَدَهُ مَصْلُوباً عَلَى الجِدَارِ"" : أَيْ مَمْدُودَ اليَدَيْنِ وَالرِّجْلَيْنِ. 2.""الْمَصْلُوبُ"" : العُودُ الْمُكَرَّمُ الَّذِي صُلِبَ عَلَيْهِ السَّيِّدُ الْمَسِيحُ في اعْتِقادِ النَّصارَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5328, 'مُصَنَّعٌ', 'مصنع', 'اسم مفعول', 'صنع', 'مصنع', 'مصنع', 'مفع. مِنْ صَنَّعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَنَّعٌ-مُصَنَّعٌ، ةٌ [ص ن ع] (مفع. مِنْ صَنَّعَ). ""بَلَدٌ مُصَنَّعٌ"": بَلَدٌ قَائِمٌ عَلَى الصِّنَاعَةِ الثَّقِيلَةِ وَمُزَوَّدٌ بِكُلِّ مَا يُنَمِّيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5329, 'مَصْنُوعٌ', 'مصنوع', 'اسم مفعول', 'صنع', 'مصنوع', 'مصنع', 'مفع. من صَنَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَصْنُوعٌ-مَصْنُوعٌ [ص ن ع] (مفع. من صَنَعَ). 1.""طَرْزٌ مَصْنُوعٌ بِاليَدِ"" : أَيْ تَمَّتْ صِنَاعَتُهُ وَحَبْكُهُ بِاليَدِ. ""مَصْنُوعَاتٌ يَدَوِيَّةٌ"" ""مَصْنُوعَاتٌ جِلْدِيَّةٌ"". 2.""مِعْطَفٌ مَصْنُوعٌ فِي الْمَغْرِبِ"" : تَمَّ صُنْعُهُ فِي ... 3.""بَيْتٌ شِعْرِيٌّ مَصْنُوعٌ"" : بَيْتٌ مَنْسُوبٌ لِغَيْرِ قاَئِلِهِ. 4.""قَصِيدَةٌ شِعْرِيَّةٌ مَصْنُوعَةٌ"" : مُتَكَلَّفَةٌ، مُفْتَعَلَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5330, 'مُصَنَّفٌ', 'مصنف', 'اسم مفعول', 'صنف', 'مصنف', 'مصنف', 'مفع. من صَنَّفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من صَنَّفَ). ""مُصَنَّفٌ في اللُّغَةِ"" : مُؤَلَّفٌ، كِتَابٌ. ""كَاتِبٌ لَهُ مُصَنَّفَاتٌ عَدِيدَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5331, 'مُصَوَّرٌ', 'مصور', 'اسم مفعول', 'صور', 'مصور', 'مصر', 'مفع. من صَوَّرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُصَوَّرٌ-مُصَوَّرٌ، ةٌ [ص و ر] (مفع. من صَوَّرَ). 1.""كِتَابٌ مُصَوَّرٌ"" : مُزَيَّنٌ بِالصُّوَرِ. 2.""نُسْخَةٌ مُصَوَّرَةٌ"" : نُسْخَةٌ مَنْقُولَةٌ عَنْ أَصْلٍ بِوَاسِطَةِ آلَةِ الاسْتِنْسَاخِ. 3.""الْمُصَوَّرُ الجُغْرَافِيُّ"" (جغ) : كِتَابٌ يَضُمُّ خَرَائِطَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5332, 'مُضَاعَفٌ', 'مضاعف', 'اسم مفعول', 'ضعف', 'مضاعف', 'مضعف', 'مفع. من ضَاعَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُضَاعَفٌ-مُضَاعَفٌ [ض ع ف] (مفع. من ضَاعَفَ). 1.""قَامَ بِجُهْدٍ مُضَاعَفٍ"" : بِجُهْدٍ أَكْثَرَ، فِيهِ جُهْدَانِ، مُضَعَّفٌ. 2.""الْمُضَاعَفُ فِي الصَّرْفِ"" : هُوَ فِي الثُّلاَثِيّ مَثَلاً: مَدَّ، أَيْ مَا كَانَتْ عَيْنُهُ وَلاَمُهُ مِنْ جِنْسٍ وَاحِدٍ وَفِي الرُّبَاعِيّ: زَعْزَعَ، أَيْ مَا تَكَرَّرَ حَرْفُهُ الأَوَّلُ وَالثَّانِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5333, 'مَضْبُوطٌ', 'مضبوط', 'اسم مفعول', 'ضبط', 'مضبوط', 'مضبط', 'مفع. من ضَبَطَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من ضَبَطَ). 1.""مَضْبُوطٌ فِي عَمَلِهِ"" : دَقِيقٌ. 2.""عَمَلٌ مَضْبُوطٌ"": تَامٌّ، صَحِيحٌ. ""عَمَلٌ غَيْرُ مَضْبُوطٍ"". 3.""مِيزَانٌ مَضْبُوطٌ"" : لاَ نَقْصَ فِيهِ. 4.""سَاعَةٌ مَضْبُوطَةٌ"" : لاَ خَلَلَ بِهَا. 5.""صَوْتٌ مَضْبُوطٌ"" : مُحْكَمٌ، مُتْقَنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5334, 'مُضَخَّمٌ', 'مضخم', 'اسم مفعول', 'ضخم', 'مضخم', 'مضخم', 'مفع. مِن ضَخَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُضَخَّمٌ-مُضَخَّمٌ، ةٌ [ض خ م] (مفع. مِن ضَخَّمَ). ""عَمَلٌ مُضَخَّمٌ"" : مُكَبَّرٌ، وَقَعَ تَضْخِيمُهُ. ""وَصَلَتْ أَخْبَارُ القَائِدِ مُضَخَّمَةً مِنَ القُرَى الْمُجَاوِرَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5335, 'مَضْرُوبٌ', 'مضروب', 'اسم مفعول', 'ضرب', 'مضروب', 'مضرب', 'مفع. مِن ضَرَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن ضَرَبَ). 1.""مَضْرُوبٌ فِي جَسَدِهِ"" : أَيْ تَعَرَّضَ جِسْمُهُ لِلضَّرْبِ. 2.""مَضْرُوبٌ عَلَى رَأْسِهِ"" : أَيْ فَاقِدٌ لِوَعْيِهِ. 3.""خَمْسَةٌ مَضْرُوبَةٌ فِي خَمْسَةٍ"" : أَيْ مُكَرَّرَةٌ خَمْسَ مَرَّاتٍ. 4.""حِصَارٌ مَضْرُوبٌ عَلَيْهِ"" : مُحاطٌ بِهِ، مَحْصُورٌ. ""تَسَلَّلَ مِنَ الْمُعَسْكَرِ زَاحِفاً وَخَرَجَ مِنْ نِطَاقِ الحِرَاسَةِ الْمَضْرُوبَةِ حَوْلَهُ"". (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5336, 'مُضَرَّبٌ', 'مضرب', 'اسم مفعول', 'ضرب', 'مضرب', 'مضرب', 'مفع. من ضَرَّبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُضَرَّبٌ-مُضَرَّبٌ [ض ر ب] (مفع. من ضَرَّبَ). ""فِرَاشٌ مُضَرَّبٌ"" : أَيْ مُخَيَّطٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5337, 'مُضَرَّجٌ', 'مضرج', 'اسم مفعول', 'ضرج', 'مضرج', 'مضرج', 'مفع. من ضَرَّجَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من ضَرَّجَ). ""مُضَرَّجٌ بِالدِّمَاءِ"" : مُلَطَّخٌ بِهَا. ""وَلِلْحُرِّيَّـةِ الْحَمْـرَاءِ بَـابٌ*بِكُـلِّ يَدٍ مُضَرَّجَةٍ يُـدَقُّ"". (أحمد شوقي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5338, 'مُضَرَّسٌ', 'مضرس', 'اسم مفعول', 'ضرس', 'مضرس', 'مضرس', 'مفع. مِن ضَرَّسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُضَرَّسٌ-مُضَرَّسٌ، ةٌ [ض ر س] (مفع. مِن ضَرَّسَ). 1.""حَجَرٌ مُضَرَّسٌ"" : صَلْبٌ. 2.""شَاطِئٌ مُضَرَّسٌ"" : أَيْ بِهِ نُتُوءٌ، ذُو تَضَارِيسَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5339, 'مَضْرُوسٌ', 'مضروس', 'اسم مفعول', 'ضرس', 'مضروس', 'مضرس', 'مفع. مِن ضَرَسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَضْرُوسَةٌ-مَضْرُوسَةٌ [ض ر س] (مفع. مِن ضَرَسَ). ""أَرْضٌ مَضْرُوسَةٌ"" : فِيهَا حِجَارَةٌ كَأَنَّهَا أَضْرَاسٌ، أَسْنَانٌ، مُسَنَّنَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5340, 'مُضَعَّفٌ', 'مضعف', 'اسم مفعول', 'ضعف', 'مضعف', 'مضعف', 'مفع. مِن ضَعَّفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُضَعَّفٌ-مُضَعَّفٌ، ةٌ [ض ع ف] (مفع. مِن ضَعَّفَ). 1.""جُهْدٌ مُضَعَّفٌ"" : مُضَاعَفٌ. 2.""حَرْفٌ مُضَعَّفٌ"" : حَرْفٌ مُدْغَمٌ، مُشَدَّدٌ. 3. ""أرْضٌ مُضَعَّفَةٌ"": أَصابَها مَطَرٌ خَفيفٌ، ضَعِيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5341, 'مُضَلَّعٌ', 'مضلع', 'اسم مفعول', 'ضلع', 'مضلع', 'مضلع', 'مفع. من ضَلَّعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من ضَلَّعَ). ""شَكْلٌ مُضَلَّعٌ"" : شَكْلٌ هَنْدَسِيٌّ ذُو خُطُوطٍ هِيَ الأَضْلاَعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5342, 'مُضَلَّلٌ', 'مضلل', 'اسم مفعول', 'ضلل', 'مضلل', 'مضل', 'مفع. مِن ضَلَّلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن ضَلَّلَ). ""رَجُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5343, 'مَضْمُومٌ', 'مضموم', 'اسم مفعول', 'ضمم', 'مضموم', 'مضمم', 'مفع. مِن ضَمَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَضْمُومٌ-مَضْمُومٌ، ةٌ [ض م م] (مفع. مِن ضَمَّ). 1.""ثَوْبٌ مَضْمُومٌ"" : مَجْمُوعٌ. 2.""شَفَتَانِ مَضْمُومَتَانِ"" : مُجْتَمِعَتَانِ، مَزْمومَتانِ. 3.""حَرْفٌ مَضْمُومٌ"" : أَيْ عَلَيْهِ ضَمَّةُ الرَّفْعِ. ""كَلِمَةٌ مَضْمُومَةُ الآخِرِ"" ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5344, 'مَضْمُونٌ', 'مضمون', 'اسم مفعول', 'ضمن', 'مضمون', 'مضمن', 'مفع. مِن ضَمِنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مضامينُ"', '', '', '', '', '', '', '', '', '"مَضْمُونٌ-مَضْمُونٌ، ةٌ [ض م ن] (مفع. مِن ضَمِنَ). 1.""عَمَلُهُ مَضْمُونٌ"" : أَيْ نَتَائِجُهُ مُؤَكَّدَةٌ، مُؤَمَّنَةٌ. ""حَقُّكَ مَضْمُونٌ"". 2.""رِسَالَةٌ مَضْمُونَةٌ"" : رِسَالَةٌ يُؤَدَّى عَلَيْهَا رَسْمٌ خَاصٌّ وَتَتَعَهَّدُ إِدَارَةُ البَرِيدِ بِإِيصَالِهَا إِلَى الْمُرْسَلِ إِلَيْهِ شَخْصِيّاً، مَكْفُولَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5345, 'مَضَامِينُ', 'مضامين', 'اسم مفعول', '', 'مضامين', 'مضمن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5346, 'مُطَارَدٌ', 'مطارد', 'اسم مفعول', 'طرد', 'مطارد', 'مطرد', 'مفع. من طَارَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُطَارَدٌ-مُطَارَدٌ، ةٌ [ط ر د] (مفع. من طَارَدَ). ""مُطَارَدٌ مِنْ كُلِّ جِهَةٍ"" : مُتَابَعٌ، مُلاَحَقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5347, 'مَطُوفٌ', 'مطوف', 'اسم مفعول', 'طوف', 'مطوف', 'مطف', 'مفع. مِن طَافَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَطُوفٌ-مَطُوفٌ [ط و ف] (مفع. مِن طَافَ). ""مَلْعَبٌ مَطُوفٌ حَوْلَهُ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5348, 'مُطَالَبٌ', 'مطالب', 'اسم مفعول', 'طلب', 'مطالب', 'مطلب', 'مفع. مِن طَالَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن طَالَبَ). ""مُطَالَبٌ بِإِنْجَازِ العَمَلِ فِي يَوْمٍ واحِدٍ"" : مَدْعُوٌّ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5349, 'مَطْبُوخٌ', 'مطبوخ', 'اسم مفعول', 'طبخ', 'مطبوخ', 'مطبخ', 'مفع. مِن طَبَخَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَطْبُوخٌ-مَطْبُوخٌ، ةٌ [ط ب خ] (مفع. مِن طَبَخَ). 1.""طَعَامٌ مَطْبُوخٌ"" : أَيْ تَمَّ طَبْخُهُ. 2.""مَوْضُوعٌ مَطْبُوخٌ ج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5350, 'مَطْبُوعٌ', 'مطبوع', 'اسم مفعول', 'طبع', 'مطبوع', 'مطبع', 'مفع. من طَبَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من طَبَعَ). 1.""مَطْبُوعٌ عَلَى مَكَارِمِ الأَخْلاَقِ"" : مَنْ نَشَأَ طَبْعُهُ عَلَى مَكَارِمِ الأَخْلاَقِ. 2.""شَاعِرٌ مَطْبُوعٌ"" : مَنْ يَأْتِي شِعْراً دُونَ تَكَلُّفٍ. 3.""كِتَابٌ مَطْبُوعٌ"" : كِتَابٌ صُفِّفَتْ حُرُوفُهُ مَطْبَعِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5351, 'مُطَبَّقٌ', 'مطبق', 'اسم مفعول', 'طبق', 'مطبق', 'مطبق', 'مفع. مِن طَبَّقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُطَبَّقٌ-مُطَبَّقٌ، ةٌ [ط ب ق] (مفع. مِن طَبَّقَ). 1.""بَرْنَامَجٌ مُطَبَّقٌ"" : مَعْمُولٌ بِهِ. 2.""سِعْرٌ مُطَبَّقٌ"" : سَائِدٌ، نَافِذٌ. 3.""أَحْكَامٌ مُطَبَّقَةٌ"" : سَارِيَةُ الْمَفْعُولِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5352, 'مُطَحْلَبٌ', 'مطحلب', 'اسم مفعول', 'طحلب', 'مطحلب', 'مطحلب', 'مفع. مِن طَحْلَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُطَحْلَبٌ-مُطَحْلَبٌ [ط ح ل ب] (مفع. مِن طَحْلَبَ). ""صِهْرِيجٌ مُطَحْلَبٌ"" : عَلاَهُ الطُّحْلُبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5353, 'مَطْحُونٌ', 'مطحون', 'اسم مفعول', 'طحن', 'مطحون', 'مطحن', 'مفع. من طَحَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَطْحُونٌ-مَطْحُونٌ، ةٌ [ط ح ن] (مفع. من طَحَنَ). ""قَمْحٌ مَطْحُونٌ"" : مَسْحُوقٌ بِآلَةِ الطَّحْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5354, 'مَطْرُوحٌ', 'مطروح', 'اسم مفعول', 'طرح', 'مطروح', 'مطرح', 'مفع. من طَرَحَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من طَرَحَ). 1.""مَطْرُوحٌ عَلَى قَارِعَةِ الطَّرِيقِ"" : مَرْمِيٌّ. ""كُنْتُ مَجْرُوحاً وَمَطْرُوحاً عَلَى وَجْهِي"" (نزار قباني). 2.""أَمْرٌ مَطْرُوحٌ لِلْحَسْمِ فِيهِ"" : مُقَدَّمٌ، مُقْتَرَحٌ، مَعْرُوضٌ. ""فِكْرَةٌ مَط"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5355, 'مَطْرُودٌ', 'مطرود', 'اسم مفعول', 'طرد', 'مطرود', 'مطرد', 'مفع. مِن طَرَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن طَرَدَ). ""مَطْرُودٌ مِنْ عَمَلِهِ"" : مُبْعَدٌ، مَفْصُولٌ عَنْ عَمَلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5356, 'مُطَرَّزٌ', 'مطرز', 'اسم مفعول', 'طرز', 'مطرز', 'مطرز', 'مفع. مِن طَرَّزَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُطَرَّزٌ-مُطَرَّزٌ [ط ر ز] (مفع. مِن طَرَّزَ)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5357, 'مَطْرُوفٌ', 'مطروف', 'اسم مفعول', 'طرف', 'مطروف', 'مطرف', 'مفع. من طَرَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من طَرَفَ). ""اِمْرَأَةٌ مَطْرُوفَةُ العَيْنِ"" : أَيْ تَمُدُّ بَصَرَهَا إِلَى غَيْرِ زَوْجِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5358, 'مَطْرُوقٌ', 'مطروق', 'اسم مفعول', 'طرق', 'مطروق', 'مطرق', 'مفع. مِن طَرَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَطْرُوقٌ-مَطْرُوقٌ [ط ر ق] (مفع. مِن طَرَقَ). 1.""طَرِيقٌ مَطْرُوقٌ"" : طَرِيقٌ يَمُرُّ مِنْهُ النَّاسُ. 2.""مَوْضُوعٌ مَطْرُوقٌ"" : عُولِجَ مِنْ قَبْلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5359, 'مُطَعَّمٌ', 'مطعم', 'اسم مفعول', 'طعم', 'مطعم', 'مطعم', 'مفع. مِن طَعَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُطَعَّمٌ-مُطَعَّمٌ [ط ع م] (مفع. مِن طَعَّمَ). 1.""شَجَرٌ مُطَعَّمٌ"" : مُلَقَّمٌ، أَيْ تَمَّ تَطْعِيمُهُ بِغُصْنِ شَجَرٍ آخَرَ. 2.""وَلَدٌ مُطَعَّمٌ"" : أَيْ مُلَقَّحٌ. 3.""خِنْجَرٌ مُطَعَّمٌ بِالفِضَّةِ، أَوِ الذَّهَبِ"" : مُرَصَّعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5360, 'مَطْعُونٌ', 'مطعون', 'اسم مفعول', 'طعن', 'مطعون', 'مطعن', 'مفع. مِن طَعَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن طَعَنَ). 1.""مَطْعُونٌ فِي فَخِذِهِ"" : مُصَابٌ بِطَعْنَةٍ فِي ... 2.""شَهِيدٌ مَطْعُونٌ"" : مُصَابٌ بِطَعَنَاتِ الأَعْدَاءِ. الشُّهَدَاءُ خَمْسَةٌ : الْمَطْعُونُ وَالْمَبْطُونُ وَالغَرِيقُ وَصَاحِبُ الهَدْمِ وَالشَّهِيدُ فِي سَبِيلِ اللهِ (حديث). 3.""كَانَ مِنْ بَيْنِ الْمَطْعُونِينَ بِالْمَدِينَةِ"": مِنْ بَيْنِ الْمُصَابِينَ بِدَاءِ الطَّاعُونِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5361, 'مَطْلُوبٌ', 'مطلوب', 'اسم مفعول', 'طلب', 'مطلوب', 'مطلب', 'مفع. مِن طَلَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن طَلَبَ). 1.""مَطْلُوبٌ لِلْعَدَالَةِ"" : مَنْ تُطَالِبُ بِهِ العَدَالَةُ لِتُحَاكِمَهُ. 2.""مَطْلُوبٌ مِنْهُ الحُضُورُ فِي ..."" : مُتَوَجِّبٌ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5362, 'مُطَلَّقٌ', 'مطلق', 'اسم مفعول', 'طلق', 'مطلق', 'مطلق', 'مفع. مِن طَلَّقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن طَلَّقَ). ""اِمْرَأَةٌ مُطَلَّقَةٌ"" : مَنْ طَلَّقَهَا زَوْجُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5363, 'مَطْمُوسٌ', 'مطموس', 'اسم مفعول', 'طمس', 'مطموس', 'مطمس', 'مفع. مِن طَمَسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن طَمَسَ). ""مَطْمُوسُ العَيْنِ"" : مُعَمّىً. ""رَجُلٌ مَطْمُوسُ البَصِيرَةِ مَمْلُوءُ الخَيَاشِيمِ بِالغُرُورِ"". (ع. م. العقاد)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5364, 'مُطَهَّرٌ', 'مطهر', 'اسم مفعول', 'طهر', 'مطهر', 'مطهر', 'مفع. من طَهَّرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من طَهَّرَ). ""مُطَهَّرٌ مِنْ كُلِّ نَجَاسَةٍ"" : نَقِيٌّ.الواقعة آية 79 لاَ يَمَسُّهُ إِلاَّ الْمُطَهَّرُونَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5365, 'مُطَهَّمٌ', 'مطهم', 'اسم مفعول', 'طهم', 'مطهم', 'مطهم', 'مفع. من طَهَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُطَهَّمٌ-مُطَهَّمٌ، ةٌ [ط هـ م] (مفع. من طَهَّمَ). 1.""جَوَادٌ مُطَهَّمٌ"" : مُكْتَمِلٌ، تَامٌّ، مُتَنَاهٍ فِي الرَّشَاقَةِ. 2.""وَجْهٌ مُطَهَّمٌ"" : بَارِعُ الجَمَالِ، مُمْتَلِئُ الخَدَّيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5366, 'مُطَوَّقٌ', 'مطوق', 'اسم مفعول', 'طوق', 'مطوق', 'مطق', 'مفع مِنْ طَوَّقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع مِنْ طَوَّقَ). 1.""حَمَامٌ مُطَوَّقٌ"" : حَمَامٌ ذُو طَوْقٍ. ""حَمَامَةٌ مُطَوَّقَةٌ"". 2.""فَيْلَقٌ مُطَوَّقٌ مِنْ كُلِّ جِهَةٍ"" : مُحَاصَرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5367, 'مُطَوَّلٌ', 'مطول', 'اسم مفعول', 'طول', 'مطول', 'مطل', 'مفع مِنْ طَوَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع مِنْ طَوَّلَ). ""كَتَبَ مَقَالاً مُطَوَّلاً"" : فِيهِ زِيَادَاتٌ وَإِضَافَاتٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5368, 'مَطْوِيٌّ', 'مطوي', 'اسم مفعول', 'طوي', 'مطوي', 'مط', 'مفع. من طَوَى', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَطْوِيٌّ-مَطْوِيٌّ، ةٌ [ط و ي] (مفع. من طَوَى). 1.""وَرَقٌ مَطْوِيٌّ"" : مَلْفُوفٌ. ""يَنَامُ وَرِجْلا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5369, 'مَظْرُوفٌ', 'مظروف', 'اسم مفعول', 'ظرف', 'مظروف', 'مظرف', 'مفع. مِن ظَرَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَظْرُوفٌ-مَظْرُوفٌ [ظ ر ف] (مفع. مِن ظَرَفَ). : مَا اشْتَمَلَ عَلَيْهِ الظَّرْفُ. ""رِسَالَةٌ مَظْرُوفَةٌ"" ""بَعَثَ بِالرَّسَائِلِ مَظْرُوفَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5370, 'مُظَفَّرٌ', 'مظفر', 'اسم مفعول', 'ظفر', 'مظفر', 'مظفر', 'مفع. مِن ظَفَّرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن ظَفَّرَ). ""خَرَجَ مِنَ الْمَعْرَكَةِ مُظَفَّراً "" : مُنْتَصِراً، ظَافِراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5371, 'مَظْلُومٌ', 'مظلوم', 'اسم مفعول', 'ظلم', 'مظلوم', 'مظلم', 'مفع. من ظَلَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من ظَلَمَ). ""ظَلَّ يَصْرُخُ أَمَامَ القَاضِي بِأَنَّهُ مَظْلُومٌ"" : مُعْتَدىً عَلَيْهِ وَقَدْ أَصَابَهُ ظُلْمٌ.الإسراء آية 33 وَمَنْ قُتِلَ مَظْلُوماً فَقَدْ جَعَلْنَا لِوَلِيِّهِ سُلْطَانا (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5372, 'مَعِيبٌ', 'معيب', 'اسم مفعول', 'عيب', 'معيب', 'معب', 'مفع. مِن عَابَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَعِيبٌ-مَعِيبٌ [ع ي ب] (مفع. مِن عَابَ). ""سُلُوكٌ مَعِيبٌ"": مَشِينٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5373, 'مُعاَفىً', 'معافى', 'اسم مفعول', 'عفو', 'معافى', 'معف', 'مفع. مِن عَافَى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"مُعاَفـىً-مُعاَفـىً [ع ف و] (مفع. مِن عَافَى). ""مُعَافىً مِنْ كُلِّ مَرَضٍ"" : الْمُتَمَتِّعُ بِالعَافِيَةِ وَالسَّلاَمَةِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5374, 'مُعاَفاة', 'معافاة', 'اسم مفعول', '', 'معافاة', 'معفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعاَفـىً-مُعاَفـىً [ع ف و] (مفع. مِن عَافَى). ""مُعَافىً مِنْ كُلِّ مَرَضٍ"" : الْمُتَمَتِّعُ بِالعَافِيَةِ وَالسَّلاَمَةِ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5375, 'مُعَاقَبٌ', 'معاقب', 'اسم مفعول', 'عقب', 'معاقب', 'معقب', 'مفع. مِن عَاقَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن عَاقَبَ). ""وَلَدٌ مُعَاقَبٌ"" : أَيْ مَنْ تَمَّتْ مُعَاقَبَتُهُ، عِقَابُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5376, 'مُعَالَجٌ', 'معالج', 'اسم مفعول', 'علج', 'معالج', 'معلج', 'مفع. مِن عَالَجَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُعَالَجٌ-مُعَالَجٌ [ع ل ج] (مفع. مِن عَالَجَ). ""مَرِيضٌ مُعَالَجٌ بِالْحُقَنِ"" : أَيْ تَمَّتْ مُعَالَجَتُهُ، مُدَاوَاتُهُ بِالْحُقَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5377, 'مَعْبُودٌ', 'معبود', 'اسم مفعول', 'عبد', 'معبود', 'معبد', 'مفع. من عَبَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من عَبَدَ). 1.""اللهُ هُوَ الْمَعْبُودُ بِحَقٍّ"" : الإِلَهُ الَّذِي يُعْبَدُ. 2."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5378, 'مُعَبَّرٌ', 'معبر', 'اسم مفعول', 'عبر', 'معبر', 'معبر', 'مفع. مِن عَبَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَبَّرٌ-مُعَبَّرٌ [ع ب ر] (مفع. مِن عَبَّرَ). ""مُعَبَّرٌ ع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5379, 'مُعَتَّقَةٌ', 'معتقة', 'اسم مفعول', 'عتق', 'معتقة', 'معتقة', 'مفع. من عَتَّقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَتَّقَةٌ-مُعَتَّقَةٌ [ع ت ق] (مفع. من عَتَّقَ). ""خَمْرٌ مُعَتَّقَةٌ"" : خَمْرٌ قَدِيمَةٌ جَيِّدَةٌ، أَيِ الَّتِي تُرِكَتْ لِتَقْدُمَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5380, 'مُعَجَّلٌ', 'معجل', 'اسم مفعول', 'عجل', 'معجل', 'معجل', 'مفع. مِن عَجَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَجَّلٌ-مُعَجَّلٌ، ةٌ [ع ج ل] (مفع. مِن عَجَّلَ). 1.""أَمْرٌ مُعَجَّلٌ"" : تَمَّ تَنْفِيذُهُ عَلَى عَجَلٍ وَقَبْلَ الوَقْتِ الْمُحَدَّدِ لِتَنْفِيذِهِ. ""إِجْرَاءاتٌ مُعَجَّلَةٌ"". 2.""مُعَجَّلُ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5381, 'مَعْجُونٌ', 'معجون', 'اسم مفعول', 'عجن', 'معجون', 'معجن', 'مفع. من عَجَنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":معاجينُ"', '', '', '', '', '', '', '', '', '"مَعْجُونٌ-مَعْجُونٌ [ع ج ن] (مفع. من عَجَنَ). ""مَعْجُونُ الأَسْنَانِ"" : مَادَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5382, 'مَعَاجِينُ', 'معاجين', 'اسم مفعول', '', 'معاجين', 'معجن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5383, 'مَعْدُودٌ', 'معدود', 'اسم مفعول', 'عدد', 'معدود', 'معدد', 'مفع. من عَدَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من عَدَّ). 1.""أَيَّامُهُ مَعْدُودَةٌ"" : مَحْسُوبَةٌ، أَيْ قَرِيبٌ مِنَ الْمَوْتِ. ""مَعْدُودٌ عَلَى رُؤُوسِ الأَصَابِعِ"". 2.""ثَقَافَتِي مِنَ العُلُومِ الدَّقِيقَةِ مَعْدُودَةٌ"" : مَحْدُودَةٌ. 3.""الأَيَّامُ الْمَعْدُودَاتُ"" : أَيَّامُ التَّشْرِيقِ وَهِيَ ثَلاَثَةٌ بَعْدَ يَوْمِ النَّحْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5384, 'مُعَدَّلٌ', 'معدل', 'اسم مفعول', 'عدل', 'معدل', 'معدل', 'مفع. مِن عَدَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَدَّلَ). 1.""مُعَدَّلُ السُّرْعَةِ"" : مُتَوَسِّطُهَا. ""مُعَدَّلُ الإِنْتَاجِ"" ""مُعَدَّلُ النُّمُوِّ الاقْتِصَادِيِّ"". 2.""حَصَلَ عَلَى الْمُعَدَّلِ فِي مَادَّةِ الرِّيَاضِيَّاتِ"" : عَلاَمَةٌ مَدْرَسِيَّةٌ تُشِيرُ إِلَى نِصْفِ النُّقَطِ الَّتِي يَنْب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5385, 'مَعْدُومٌ', 'معدوم', 'اسم مفعول', 'عدم', 'معدوم', 'معدم', 'مفع. مِنْ عَدَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَعْدُومٌ-مَعْدُومٌ، ةٌ [ع د م] (مفع. مِنْ عَدَمَ). 1.""حَيَاةٌ مَعْدُومَةٌ"" : غَيْرُ مَوْجُودَةٍ. 2.""أَمْرٌ مَعْدومٌ"" : مَفْقودٌ. ""الحُبُّ الَّذِي لاَ يَتَّصِلُ بِالصَّدِيقِ مَعْدُومُ القِيمَةِ"" ""وُجُودُهُ إِمَّا مَعْدُومٌ وَإِمَّا مَوْجُودٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5386, 'مُعَذَّبٌ', 'معذب', 'اسم مفعول', 'عذب', 'معذب', 'معذب', 'مفع. مِن عَذَّبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن عَذَّبَ). 1.""مُعَذَّبٌ فِي عَمَلِهِ"" : مُرْهَقٌ، مُضَايَقٌ. ""حَيَاةٌ مُعَذَّبَةٌ"". 2.""مُعَذَّبُو الأَرْضِ"" : الفُقَرَاءُ، الْمُعْدَمُونَ. 3.""وَجَدَهُمْ مُعَذَّبِينَ"" : مُضْطَهَدِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5387, 'مَعْذُورٌ', 'معذور', 'اسم مفعول', 'عذر', 'معذور', 'معذر', 'مفع. مِن عَذَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن عَذَرَ). ""أَنْتَ مَعْذُورٌ لِأَنَّكَ لاَ تَعْرِفُ الْحَقِيقَةَ"" : مَرْفُوعٌ عَنْكَ اللَّوْمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5388, 'مُعَرَّبٌ', 'معرب', 'اسم مفعول', 'عرب', 'معرب', 'معرب', 'مفع. مِن عَرَّبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن عَرَّبَ). ""لَفْظٌ مُعَرَّبٌ"" : لَفْظٌ مَنْقُولٌ إِلَى العَرَبِيَّةِ وَلَمْ يَكُنْ مَصُوغاً فِي الأَصْلِ بِصِيغَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5389, 'مُعَرَّضٌ', 'معرض', 'اسم مفعول', 'عرض', 'معرض', 'معرض', 'مفع. مِن عَرَّضَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن عَرَّضَ). 1.""وَجَدَ نَفْسَهُ مُعَرَّضاً لاتِّهَامَاتٍ خَطِيرَةٍ"" : كَانَ هَدَفاً... 2.""الأَطْفَالُ فِي القُرَى مُعَرَّضُونَ لِلْإِهْمَالِ"" : هُمْ عُرْضَةٌ وَهَدَفٌ.... ""مُعَرَّضٌ لِلشَّمْسِ"" ""مُعَرَّضٌ لِلْخَطَرِ"" ""مُعَرَّضٌ لِلسِّجْنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5390, 'مَعْرُوضٌ', 'معروض', 'اسم مفعول', 'عرض', 'معروض', 'معرض', 'مفع. مِن عَرَضَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن عَرَضَ). 1.""أَثَاثٌ مَعْرُوضٌ لِلْبَيْعِ"" : مَكْشُوفٌ، ظَاهِرٌ، مُقَدَّمٌ. 2.""مَعْرُوضَاتُ التِّجَارَةِ"" : مَنْتُوجَاتٌ مُقَدَّمَةٌ لِلْعَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5391, 'مَعْرُوفٌ', 'معروف', 'اسم مفعول', 'عرف', 'معروف', 'معرف', 'مفع. مِن عَرَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن عَرَفَ). 1.""كَاتِبٌ مَعْرُوفٌ"" : مَشْهُورٌ. ""مَعْرُوفٌ بِشَهَامَتِهِ وَحُسْنِ سُلُوكِهِ"". 2.""يَحُثُّ النَّاسَ عَلَى الْمَعْرُوفِ"" : عَلَى الإِحْسَانِ وَالخَيْرِ. ""الأَمْرُ بِالْمَعْرُوفِ وَالنَّهْيُ عَنِ الْمُنْكَرِ"". 3.""أَسْدَى إِلَيْهِ مَعْرُوفاً"" : جَمِيلاً، صَنِيعَةً. 4.""مِنَ الْمَعْرُوفِ أَنَّهُ صَاحِبُ فَضْلٍ"" : مِنَ الْمَعْلُومِ... ""وَاقِعَةٌ مَعْرُوفَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5392, 'مُعَرَّفٌ', 'معرف', 'اسم مفعول', 'عرف', 'معرف', 'معرف', 'مفع. من عَرَّفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُعَرَّفٌ-مُعَرَّفٌ [ع ر ف] (مفع. من عَرَّفَ). ""اِسْمٌ مُعَرَّفٌ"": اِسْمٌ دَخَلَتْ عَلَيْهِ أَدَاةُ التَّعْرِيفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5393, 'مُعَرْقَلٌ', 'معرقل', 'اسم مفعول', 'عرقل', 'معرقل', 'معرقل', 'مفع. مِن عَرْقَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُعَرْقَلٌ-مُعَرْقَلٌ، ةٌ [ع ر ق ل] (مفع. مِن عَرْقَلَ). ""مَا زَالَ عَمَلُهُ مُعَرْقَلاً"" : مَا زَالَتْ أَمَامَ عَمَلِهِ صُعُوبَاتٌ وَعَقَبَاتٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5394, 'مُعَرّىً', 'معرى', 'اسم مفعول', 'عري', 'معرى', 'معر', 'مفع. مِن عَرَّى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَرَّى). ""مُعَرّىً مِنْ كُلِّ ثِيَابِهِ"" : كُلُّ ثِيَابِهِ مَنْزُوعَةٌ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5395, 'مُعَرّاة', 'معراة', 'اسم مفعول', '', 'معراة', 'معرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَرَّى). ""مُعَرّىً مِنْ كُلِّ ثِيَابِهِ"" : كُلُّ ثِيَابِهِ مَنْزُوعَةٌ عَنْهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5396, 'مُعَزَّزٌ', 'معزز', 'اسم مفعول', 'عزز', 'معزز', 'معز', 'مفع من عَزَّزَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع من عَزَّزَ). 1.""كَانَ مُعَزَّزًا بَيْنَ أَهْلِهِ"" : مُكَرَّماً. 2.""قَدَّمَ مَوْضُوعاً مُعَزَّزًا بِالشَّوَاهِدِ"" : مُدَعَّماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5397, 'مَعْزُولٌ', 'معزول', 'اسم مفعول', 'عزل', 'معزول', 'معزل', 'مفع. مِن عَزَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن عَزَلَ). ""مَعْزُولٌ عَنِ النَّاس"" : مَفْصُولٌ عَنْهُمْ، مُنَحّىً..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5398, 'معازيل', 'معازيل', 'اسم مفعول', '', 'معازيل', 'معزل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5399, 'مُعَسْكَرٌ', 'معسكر', 'اسم مفعول', 'عسكر', 'معسكر', 'معسكر', 'مفع. مِن عَسْكَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَسْكَرَ). 1.""مُعَسْكَرُ الْجُنُودِ"" : مَكَانُ إِقَامَتِهِمْ وَتَجَمُّعِهِمْ. 2.""مُعَسْكَرٌ كَشْفِيٌّ"" : تَجَمُّعُ الكَشَّافَةِ لِفَتْرَةٍ مُعَيَّنَةٍ. 3.""مُعَسْكَرُ اعْتِقَالٍ"" : مَكَانٌ شَاسِعٌ مُحَاطٌ بِسِيَاجٍ يُجْمَعُ فِيهِ الْمُعْتَقَلُونُ. ""نَدَّدَتِ الْمُنَظَّمَاتُ الدَّوْلِيَّةُ لِحُقُوقِ الإِنْسَانِ بِمُعَسْكَرَاتِ الاعْتِقَالِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5400, 'مُعَسَّلٌ', 'معسل', 'اسم مفعول', 'عسل', 'معسل', 'معسل', 'مفع. مِن عَسَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَسَّلٌ-مُعَسَّلٌ [ع س ل] (مفع. مِن عَسَّلَ). ""طَعَامٌ مُعَسَّلٌ"": طَعَامٌ رُطِّبَ بِالعَسَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5401, 'مَعْسُولٌ', 'معسول', 'اسم مفعول', 'عسل', 'معسول', 'معسل', 'مفع. مِن عَسَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَسَلَ). 1.""طَعَامٌ مَعْسُولٌ"" : مَخْلُوطٌ بِالعَسَلِ. 2.""رَجُلٌ مَعْسُولُ الكَلاَمِ"" : حُلْوُ الكَلاَمِ. 3.""كَلاَمٌ مَعْسُولٌ"" : كَلاَمٌ حُلْوٌ رَطْبٌ، جَمِيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5402, 'مُعَشَّرٌ', 'معشر', 'اسم مفعول', 'عشر', 'معشر', 'معشر', 'مفع. مِن عَشَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَشَّرٌ-مُعَشَّرٌ [ع ش ر] (مفع. مِن عَشَّرَ). 1.""مُعَشَّرُ الزَّوَايَا"" (هن) : شَكْلٌ ذُو زَوَايَا عَشْرٍ. 2.""مُعَشَّرُ السُّطُوحِ""(هن) : شَكْلٌ ذُو سُطُوحٍ عَشَرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5403, 'مُعَصَّبٌ', 'معصب', 'اسم مفعول', 'عصب', 'معصب', 'معصب', 'مفع. مِن عَصَّبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُعَصَّبٌ-مُعَصَّبٌ [ع ص ب] (مفع. مِن عَصَّبَ). 1.""مُعَصَّبُ قَوْمِهِ"" : رَئِيسُهُمْ، سَيِّدُهُمْ. 2.""جَاءَ مُعَصَّباً بِعِمَامَةِ"" : مُعَمَّماً. 3.""رَجُلٌ مُعَصَّبٌ"" : جَائِعٌ، فَقِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5404, 'مَعْصُوبٌ', 'معصوب', 'اسم مفعول', 'عصب', 'معصوب', 'معصب', 'مفع. مِن عَصَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن عَصَبَ). 1.""جَاءهُ مَعْصُوبَ العَيْنَيْنِ"" : عَلَى عَيْنَيْهِ عِصَابٌ. 2.""جُرْحٌ مَعْصُوبٌ"" : مَلْفُوفٌ بِضَمَّادَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5405, 'مُعَصَّرٌ', 'معصر', 'اسم مفعول', 'عصر', 'معصر', 'معصر', 'مفع. مِن عَصَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَصَّرٌ-مُعَصَّرٌ [ع ص ر] (مفع. مِن عَصَّرَ). ""حَامِضٌ مُعَصَّرٌ"": حَامِضٌ مُسْتَخْرَجٌ مِنْهُ عَصِيرُهُ. ""لَيْمُونٌ مُعَصَّرٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5406, 'مَعْصُومٌ', 'معصوم', 'اسم مفعول', 'عصم', 'معصوم', 'معصم', 'مفع. مِن عَصَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن عَصَمَ). ""الإِمَامُ الْمَعْصُومُ"" : الْمُنَزَّهُ عَنِ الخَطَإِ وَالفَاحِشَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5407, 'مَعْطُوبٌ', 'معطوب', 'اسم مفعول', 'عطب', 'معطوب', 'معطب', 'مفع. مِن عَطَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن عَطَبَ). ""مَعْطُوبٌ فِي رِجْلِهِ"" : مُصَابٌ بِعَطَبٍ، بِضَرَرٍ. ""عَادَ مِنَ الْحَرْبِ مَعْطُوباً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5408, 'مُعَطَّرٌ', 'معطر', 'اسم مفعول', 'عطر', 'معطر', 'معطر', 'مفع. مِن عَطَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَطَّرٌ-مُعَطَّرٌ [ع ط ر] (مفع. مِن عَطَّرَ). ""ثَوْبٌ مُعَطَّرٌ"" : وُضِعَ فِيهِ العِطْرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5409, 'مُعَطَّلٌ', 'معطل', 'اسم مفعول', 'عطل', 'معطل', 'معطل', 'مفع. مِن عَطَّلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن عَطَّلَ). 1.""مُعَطَّلٌ عَنِ العَمَلِ"" : العَاطِلُ عَنِ العَمَلِ. 2.""يَوْمٌ مُعَطَّلٌ"" : يَوْمُ عُطْلَةٍ لاَ عَمَلَ فِيهِ. 3. ""أَرْضٌ مُعَطّلَةٌ"" : مَتْروكَةٌ بِمَوْتِ أهلِها.الحج آية 45 فهي خَاوِيةٌ على عُروشِها وبِئْرٍ مُعَطّلَةٍ وقَصْرٍ مَشيدٍ . (قرآن) ""أَيَّامٌ مُعَطَّلَةٌ"". 3.""سَيَّارَةٌ مُعَطَّلَةٌ"" : مُصَابَةٌ بِعَطَبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5410, 'مُعَظَّمٌ', 'معظم', 'اسم مفعول', 'عظم', 'معظم', 'معظم', 'مفع. مِن عَظَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن عَظَّمَ). ""رَجُلٌ مُعَظَّمٌ"" : مُوَقَّرٌ، مُبَجَّلٌ، مُحْتَرَمٌ. ""جَلاَلَةُ الْمَلِكِ الْمُعَظَّمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5411, 'مَعْفُوٌّ', 'معفو', 'اسم مفعول', 'عفو', 'معفو', 'معف', 'مفع. مِن عَفَا', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَفَا). ""مَعْفُوٌّ عَنْهُ"" : مَنْ صُفِحَ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5412, 'مُعَفَّرٌ', 'معفر', 'اسم مفعول', 'عفر', 'معفر', 'معفر', 'مفع. مِن عَفَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَفَّرَ). ""مُعَفَّرَ الوَجْهِ"" : وَجْهٌ مُغَطّىً بِالتُّرَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5413, 'مُعَفَّنٌ', 'معفن', 'اسم مفعول', 'عفن', 'معفن', 'معفن', 'مفع. مِن عَفَّنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن عَفَّنَ). ""لَحْمٌ مُعَفَّنٌ"" : مُنَتَّنٌ، أَيْ صَارَتْ تَنْبَعِثُ مِنْهُ رَائِحَةٌ كَرِيهَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5414, 'مُعَقَّبٌ', 'معقب', 'اسم مفعول', 'عقب', 'معقب', 'معقب', 'مفع. مِن عَقَّبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَقَّبَ). 1.""عَمَلٌ مُعَقَّبٌ"" : مُؤَخَّرٌ إِلَى مَرْحَلَةٍ لاَحِقَةٍ. 2.""مُعَقَّبٌ عَلَيْهِ"" : أَيْ كَلاَمُهُ كَانَ مَحَلَّ انْتِقَادٍ أَوْ إِضَافَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5415, 'مُعَقَّدٌ', 'معقد', 'اسم مفعول', 'عقد', 'معقد', 'معقد', 'مفع. مِن عَقَّدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن عَقَّدَ). 1. ""كَلاَمٌ مُعَقَّدٌ"" : مُبْهَمٌ غَيْرُ وَاضِحٍ. 2. ""مُشْكِلٌ مُعَقَّدٌ"" : مُسْتَعْصٍ. ""مَسْأَلَةٌ مُعَقَّدَةٌ"". 3.""رَجُلٌ مُعَقَّدٌ"" : أَيْ تَعْتَرِضُهُ عُقَدٌ نَفْسِيَّةٌ مِنْ جَرَّاءِ اضْطِرَابٍ نَفْسِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5416, 'مَعْقُودٌ', 'معقود', 'اسم مفعول', 'عقد', 'معقود', 'معقد', 'مفع. مِن عَقَدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَقَدَ). 1. ""مَعْقُودٌ بِحَبْلٍ"" : مَرْبُوطٌ بِهِ. ""كَانَ لِسَانُهُ مَعْقُودًا وفَمُهُ مُغْلَقاً"". (إسحق الحسيني). 2. ""سُكَّرٌ مَعْقُودٌ"" : سُك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5417, 'مَعْقُوفٌ', 'معقوف', 'اسم مفعول', 'عقف', 'معقوف', 'معقف', 'مفع. مِن عَقَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَقَفَ). 1.""أَنْفٌ مَعْقُوفٌ"" : مُعْوَجٌّ مِنْ أَرْنَبَتِهِ. ""مَعْقُوفُ الأَنْفِ"". 2. ""غُصْنٌ مَعْقٌوفٌ"" : أَعْوَجُ، مُنْحَنٍ. 3.""الصَّلِيبُ الْمَعْقُوفُ"" : صَلِيبٌ تَنْثَنِي أَطْرَافُهُ الأَرْبَعَةُ مُكَوِّنَةً زَوَايَا قائِمَةً، وهُوَ الشِّعَارُ الذِّي اتَّخَذَتْهُ النَّازِيَّةُ الأَلْمَانِيَّةُ رَمْزاً لَهَا. 4.""كَلِمَةٌ بَيْنَ مَعْقُوفَيْنِ"" : قَوْسَانِ مِن عَلاَمَاتِ التَّرْقِيمِ يُرْسَمانِ هَكَذَا "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5418, 'مَعْقُولٌ', 'معقول', 'اسم مفعول', 'عقل', 'معقول', 'معقل', 'مفع. مِن عَقَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَقَلَ). 1.""كَلاَمٌ مَعْقُولٌ"" : كَلاَمٌ عَلَى صَوابٍ يَقْبَلُهُ العَقْلُ. ""غَيْرُ مَعْقُولٍ"". 2. ""لَيْسَ مِنَ الْمَعْقُولِ أَنْ يَشْتُمَهُ"" : لَيْسَ مِنَ الصَّوَابِ أَنْ ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5419, 'مُعَقَّمٌ', 'معقم', 'اسم مفعول', 'عقم', 'معقم', 'معقم', 'مفع. مِن عَقَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُعَقَّمٌ-مُعَقَّمٌ، ةٌ [ع ق م] (مفع. مِن عَقَّمَ). ""حَلِيبٌ مُعَقَّمٌ"": خَضَعَ لِتَعْقِيمٍ لِكَيْ لا تَتَسَرَّبَ إِلَيْهِ الْجَرَاثِيمُ. ""حُجْرَةٌ مُعَقَّمَةٌ"" ""آلاَتٌ مُعَقَّمَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5420, 'مُعَكَّرٌ', 'معكر', 'اسم مفعول', 'عكر', 'معكر', 'معكر', 'مفع. مِن عَكَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَكَّرٌ-مُعَكَّرٌ، ةٌ [ع ك ر] (مفع. مِن عَكَّرَ). 1.""مَاءٌ مُعَكَّرٌ"": كَدِرٌ، أَي اخْتَلَطَتْ بِهِ أَتْرِبَةٌ ومَا شَابَهَ ذَلِكَ. 2.""جَوٌّ مُعَكَّرٌ"" : أَيْ غَيْرُ صَافٍ. ""صَارَتِ العَلاَقَاتُ مُعَكَّرَةً بَيْنَهُمَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5421, 'مَعْكُوسٌ', 'معكوس', 'اسم مفعول', 'عكس', 'معكوس', 'معكس', 'مفع. مِن عَكَسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَعْكُوسٌ-مَعْكُوسٌ، ةٌ [ع ك س] (مفع. مِن عَكَسَ). ""فَمُهُ مَعْكُوسٌ"": مَقْلُوبٌ. ""كَلِمَةٌ مَعْكُوسَةٌ"" ""صُورَةٌ مَعْكُوسَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5422, 'مَعْلُولٌ', 'معلول', 'اسم مفعول', 'علل', 'معلول', 'معلل', 'مفع. مِن عَلَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَلَّ). 1. ""مَعْلُولُ الجِسْمِ"" : عَلِيلٌ. 2. ""العِلَّةُ و الْمَعْلُولُ"" : أَيِ السَّبَبُ والنَّتِيجَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5423, 'مَعْلُوفٌ', 'معلوف', 'اسم مفعول', 'علف', 'معلوف', 'معلف', 'مفع. مِن عَلَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَلَفَ).""خَرُوفٌ مَعْلُوفٌ"" : أَيْ أُطْعِمَ عَلَفاً بِمَا فِيهِ الكِفَايَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5424, 'مُعَلَّقٌ', 'معلق', 'اسم مفعول', 'علق', 'معلق', 'معلق', 'مفع. مِن عَلَّقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن عَلَّقَ). 1. ""جِسْرٌ مُعَلَّقٌ"" : مَهْزُوزٌ في الفَضَاءِ. 2.""تَرَكَهُ مُعَلَّقاً بَيْنَ نَعَمْ ولاَ"" : مَهْزُوزاً، مُرْتَبِكاً، قَلِقاً. ""مُعَلَّقٌ بَيْنَ السَّمَاءِ والأَرْضِ"". 3.""مَوْضُوعٌ مُعَلَّقٌ"" : لَمْ يَجِدْ حَلاًّ. ""قَضَايَا مُعَلَّقَةٌ"". 4.""اِمْرَأَةٌ مُعَلَّقَةٌ"" : لاَ هِي مُتَزَوِّجَةٌ ولاَ هِي مُطَلّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5425, 'مُعَلَّمٌ', 'معلم', 'اسم مفعول', 'علم', 'معلم', 'معلم', 'مفع. مِن عَلَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُعَلَّمٌ-مُعَلَّمٌ، ةٌ [ع ل م] (مفع. مِن عَلَّمَ). 1.""شَابٌّ مُعَلَّمٌ"": مُتَعَلِّمٌ. 2.""بِضَاعَةٌ مُعَلَّمَةٌ"" : لَهَا عَلاَمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5426, 'مَعْلُومٌ', 'معلوم', 'اسم مفعول', 'علم', 'معلوم', 'معلم', 'مفع. مِن عَلِـمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَلِـمَ). 1. ""أَمْرٌ مَعْلُومٌ"" : مَعْرُوفٌ. ""مِنَ الْمَعْلُومِ أَنَّ ..."" ""الْمَعْلُومُ والْمَجْهُولُ"". 2.""فِعْلٌ مَعْلُومٌ"" (نح) : مَا كَانَ فَاعِلُهُ مَعْرُوفاً. 3. ""زَوَّدَهُ بِمَعْلُومَاتٍ قَيِّمَةٍ"" : بِحَقَائِقَ وأَخْبَارٍ ومَعَارِفَ تُسَاعِدُ عَلَى تَوْضِيحِ الأَشْيَاءِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5427, 'مُعَلًّى', 'معلى', 'اسم مفعول', 'علو', 'معلى', 'معل', 'مفع. مِن عَلَّى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"مُعَلَّى-مُعَلَّى [ع ل و] (مفع. مِن عَلَّى). 1.""بِنَاءٌ مُعَلَّى"" : مُرْتَفِعٌ . 2.""القِدْحُ الْمُعَلَّى"" : السَّهْمُ الفَائِزُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5428, 'مُعَلاة', 'معلاة', 'اسم مفعول', '', 'معلاة', 'معلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَلَّى-مُعَلَّى [ع ل و] (مفع. مِن عَلَّى). 1.""بِنَاءٌ مُعَلَّى"" : مُرْتَفِعٌ . 2.""القِدْحُ الْمُعَلَّى"" : السَّهْمُ الفَائِزُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5429, 'مُعَمَّرٌ', 'معمر', 'اسم مفعول', 'عمر', 'معمر', 'معمر', 'مفع. مِن عَمَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَمَّرٌ-مُعَمَّرٌ، ةٌ [ع م ر] (مفع. مِن عَمَّرَ). 1.""رَجُلٌ مُعَمَّرٌ"": عَاشَ زَمَناً طَوِيلاً. ""مِنَ الْمُعَمِّرِينَ مَنْ عَاشَ مِئَةً وعِشْرِينَ سَنَةً أَوْ أَكْثَرَ"". 2.""بَلَدٌ مُعَمَّرٌ"" : بَلَدٌ بُنِيَتْ فِيهِ بِنَايَاتٌ وعِمَارَاتٌ ومَزْرُوعُاتٌ وَصَنَائِعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5430, 'مَعْمُورٌ', 'معمور', 'اسم مفعول', 'عمر', 'معمور', 'معمر', 'مفع. مِن عَمَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَعْمُورٌ-مَعْمُورٌ، ةٌ [ع م ر] (مفع. مِن عَمَرَ). 1.""بَلَدٌ مَعْمُورٌ"": بَلَدٌ آهِلٌ بِالسُّكَّانِ. 2الطور آية 4 والبَيْتِ الْمَعْمُور (قرآن) : مَكَّةُ الْمُكَرَّمَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5431, 'مَعْمُولٌ', 'معمول', 'اسم مفعول', 'عمل', 'معمول', 'معمل', 'مفع. مِن عَمِلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَعْمُولٌ-مَعْمُولٌ، ةٌ [ع م ل] (مفع. مِن عَمِلَ). ""قَانُونٌ مَعْمُولٌ بِهِ"" : سَائِدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5432, 'مُعَمَّمٌ', 'معمم', 'اسم مفعول', 'عمم', 'معمم', 'معم', 'مفع. مِن عَمَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَمَّمَ). ""جَلَسَ الشَّيْخُ الْمُعَمَّمُ وَسَطَ الجَمَاعَةِ"" : الْمُعَصَّبُ بِعِمَامَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5433, 'مُعَمّىً', 'معمى', 'اسم مفعول', 'عمي', 'معمى', 'معم', 'مفع. مِن عَمَّى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"مُعَمّىً-مُعَمّىً [ع م ي] (مفع. مِن عَمَّى). 1.""الْمُعَمَّى مِنَ الكَلاَمِ"" : مَا عَمِيَ مَعْنَاهُ وخَفِيَ. 2.""مُعَمَّى البَصِيرَةِ"" : صُيِّرَ أَعْمَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5434, 'مُعَمّاة', 'معماة', 'اسم مفعول', '', 'معماة', 'معمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَمّىً-مُعَمّىً [ع م ي] (مفع. مِن عَمَّى). 1.""الْمُعَمَّى مِنَ الكَلاَمِ"" : مَا عَمِيَ مَعْنَاهُ وخَفِيَ. 2.""مُعَمَّى البَصِيرَةِ"" : صُيِّرَ أَعْمَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5435, 'مُعَنَّفٌ', 'معنف', 'اسم مفعول', 'عنف', 'معنف', 'معنف', 'مفع. مِن عَنَّفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن عَنَّفَ). ""وَجَدَهُ مُعَنَّفاً مِنْ قِبَلِ الْمُعَلِّمَةِ"" : مُوَبَّخاً وَمَأْخُوذاً بِالشِّدَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5436, 'مُعَنّىً', 'معنى', 'اسم مفعول', 'عني', 'معنى', 'معن', 'مفع. مِن عَنَّى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَنَّى). ""مُعَنَّى القَلْبِ والجَسَدِ"" : مُعَذَّبٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5437, 'مُعَناة', 'معناة', 'اسم مفعول', '', 'معناة', 'معنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن عَنَّى). ""مُعَنَّى القَلْبِ والجَسَدِ"" : مُعَذَّبٌ..."', ':لا جذر:لا مفرد');
