INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5439, 'مَعْهُودٌ', 'معهود', 'اسم مفعول', 'عهد', 'معهود', 'معهد', 'مفع. مِن عَهِدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَعْهُودٌ-مَعْهُودٌ [ع هـ د] (مفع. مِن عَهِدَ). ""عَاوَدَ الْمَكَانَ هُدُوؤُهُ الْمَعْهُودُ"" : الْمُعْتَادُ، العَادِيُّ. ""مَعْهُودٌ فِيهِ التَّقْوَى والصَّلاَحُ""."', '');
