INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5443, 'مُعَيَّنٌ', 'معين', 'اسم مفعول', 'عين', 'معين', 'معن', 'مفع. مِن عَيَّنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن عَيَّنَ). 1. ""مُعَيَّنٌ فِي مَنْصِبٍ هَامٍّ"" : مُسَمّىً. 2. ""مَكَانٌ مُعَيَّنٌ"": مُحَدَّدٌ. 3. ""أَمْرٌ مُعَيَّنٌ"" : مُخَصَّصٌ. ""يَزُورُنَا فِي أَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5444, 'مُغَبَّرٌ', 'مغبر', 'اسم مفعول', 'غبر', 'مغبر', 'مغبر', 'مفع. مِن غَبَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن غَبَّرَ). ""مُغَبَّرُ الوَجْهِ"" : مُلَطَّخٌ بالغُبَارِ. ""تَخْلَعُ الذِّكْرَى مَلاَبِسَهَا الْمُغَبَّرَةَ القَدِيمَة"". (أمل دنقل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5445, 'مَغْبُوطٌ', 'مغبوط', 'اسم مفعول', 'غبط', 'مغبوط', 'مغبط', 'مفع. مِن غَبَطَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن غَبَطَ). ""مَغْبُوطٌ فِي عَمَلِهِ"" : فِي غِبْطَةٍ وسُرُورٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5446, 'مَغْبُونٌ', 'مغبون', 'اسم مفعول', 'غبن', 'مغبون', 'مغبن', 'مفع. مِن غَبَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن غَبَنَ). ""وَلَدٌ مَغْبُونٌ"" : خَائِبٌ. ""رَجَعَ مَغْبُوناً مِنْ سَفَرِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5447, 'مُغَذّىً', 'مغذى', 'اسم مفعول', 'غذي', 'مغذى', 'مغذ', 'مفع. مِن غَذَّى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"مُغَذّىً-مُغَذّىً، ةٌ [غ ذ ي] (مفع. مِن غَذَّى). ""مُغَذّىً بِوَجْبَةٍ دَسِمَةٍ"" : أَيْ مُتَنَاوِلٌ لِوَجْبَةٍ مُغَذِّيَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5448, 'مُغَذّاة', 'مغذاة', 'اسم مفعول', '', 'مغذاة', 'مغذة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُغَذّىً-مُغَذّىً، ةٌ [غ ذ ي] (مفع. مِن غَذَّى). ""مُغَذّىً بِوَجْبَةٍ دَسِمَةٍ"" : أَيْ مُتَنَاوِلٌ لِوَجْبَةٍ مُغَذِّيَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5449, 'مَغْرُورٌ', 'مغرور', 'اسم مفعول', 'غرر', 'مغرور', 'مغرر', 'مفع. مِن غَرَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن غَرَّ). ""مَغْرُورٌ بِمَا حَقَّقَ مِنْ نَتَائِجَ"" : مَ"', '');
