INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5451, 'مُغَرْبَلٌ', 'مغربل', 'اسم مفعول', 'غربل', 'مغربل', 'مغربل', 'مفع. مِن غَرْبَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُغَرْبَلٌ-مُغَرْبَلٌ، ةٌ [غ ر ب ل] (مفع. مِن غَرْبَلَ). 1.""دَقِيقٌ مُغَرْبَلٌ"" : أَيْ تَمَّتْ غَرْبَلَتُهُ. 2.""رَجُلٌ مُغَرْبَلٌ"" : دَنِيءٌ، خَسِيسٌ، حَقِيرٌ. 3.""مَالٌ مُغَرْبَلٌ"" : ذَهَبَ كُلُّهُ، مُسْتَنْزَفٌ. 4.""مُلْكٌ مُغَرْبَلٌ"" : زَائِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5452, 'مَغْسُولٌ', 'مغسول', 'اسم مفعول', 'غسل', 'مغسول', 'مغسل', 'مفع. مِن غَسَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَغْسُولٌ ، ةٌ - [غ س ل]. (مفع. مِن غَسَلَ). ""ثِيَابٌ مَغْسُولَةٌ"" : أَيْ تَمَّ غَسْلُهَا وتَنْظِيفُهَا. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5453, 'مَغْشُوشٌ', 'مغشوش', 'اسم مفعول', 'غشش', 'مغشوش', 'مغشش', 'مفع. مِن غَشَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَغْشُوشٌ-مَغْشُوشٌ، ةٌ [غ ش ش] (مفع. مِن غَشَّ). 1. ""عَمَلٌ مَغْشُوشٌ"" : فِيهِ غِشٌّ. 2. ""ل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5454, 'مَغْشِيٌّ', 'مغشي', 'اسم مفعول', 'غشي', 'مغشي', 'مغش', 'مفع. مِن غَشِيَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن غَشِيَ). ""سَقَطَ مَغْشِيّاً عَلَيْهِ"" : مُغْمىً عَلَيْهِ، أَيْ فَاقِداً الحِسَّ والْحَرَكَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5455, 'مَغْضُوبٌ', 'مغضوب', 'اسم مفعول', 'غضب', 'مغضوب', 'مغضب', 'مفع. مِن غضِبَ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"(مفع. مِن غضِبَ). ""رَجُلٌ مَغْضُوبٌ عَلَيْهِ"" : رَجُلٌ مُبْغَضٌ.الفاتحة آية 7 غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5456, 'مَذْهُوبٌ', 'مذهوب', 'اسم مفعول', '', 'مذهوب', 'مذهب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"مذهوب بعقله."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5457, 'مَغْفُورٌ', 'مغفور', 'اسم مفعول', 'غفر', 'مغفور', 'مغفر', 'مفع. مِن غَفَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن غَفَرَ). 1. ""الْمَغْفُورُ لَهُ"" : الْمَرْحُومُ. 2. ""ذَنْبُهُ مَغْفُورٌ"" : ذَنْبُهُ مَحَلُّ غُفْرَانٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5458, 'مُغَفَّلٌ', 'مغفل', 'اسم مفعول', 'غفل', 'مغفل', 'مغفل', 'مفع. مِن غَفَّلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن غَفَّلَ). ""رَجُلٌ مُغَفَّلٌ"" : لاَ فِطْنَةَ لَهُ ولاَ ذَكَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5459, 'مَغْلُوبٌ', 'مغلوب', 'اسم مفعول', 'غلب', 'مغلوب', 'مغلب', 'مفع. مِن غَلَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن غَلَبَ). ""مَغْلُوبٌ عَلَى أَمْرِهِ"" : أَيْ عَاجِزٌ عَنِ الْحَرَكَةِ لاَ يَسْتَطِيعُ تَنْفِيذَ أَمْرٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5460, 'مَغْلُوطٌ', 'مغلوط', 'اسم مفعول', 'غلط', 'مغلوط', 'مغلط', 'مفع. مِن غَلِطَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَغْلُوطٌ-مَغْلُوطٌ، ةٌ [غ ل ط] (مفع. مِن غَلِطَ). ""حِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5461, 'مُغَلَّفٌ', 'مغلف', 'اسم مفعول', 'غلف', 'مغلف', 'مغلف', 'مفع. مِن غَلَّفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن غَلَّفَ). 1. ""سَلَّمَهُ مُغَلَّفاً"" : غِلاَف الرِّسَالَةِ. 2. ""مُغَلَّفٌ بِسِلْهَامِهِ"" : مُلْتَفٌّ بِهِ. 3. ""كِتَابٌ مُغَلَّفٌ"" : عَلَيْهِ غِلافٌ مِنْ وَرَقٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5462, 'مَغْلُوقٌ', 'مغلوق', 'اسم مفعول', 'غلق', 'مغلوق', 'مغلق', 'مفع. مِن غَلَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَغْلُوقٌ-مَغْلُوقٌ، ةٌ [غ ل ق] (مفع. مِن غَلَقَ). ""بَابٌ مَغْلُوقٌ"": مَسْدُودٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5463, 'مَغْمُومٌ', 'مغموم', 'اسم مفعول', 'غمم', 'مغموم', 'مغمم', 'مفع. مِن غَمَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن غَمَّ). ""رَجُلٌ مَغْمُومٌ"" : مَهْمُومٌ، حَزِينٌ، كَئِيبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5464, 'مُغَمَّدٌ', 'مغمد', 'اسم مفعول', 'غمد', 'مغمد', 'مغمد', 'مفع. مِن غَمَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُغَمَّدٌ-مُغَمَّدٌ، ةٌ [غ م د] (مفع. مِن غَمَّدَ).""جَسَدٌ مُغَمَّدٌ"" : مُغَطّىً. ""وَقَدْ قُبِضَ عَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5465, 'مَغْمُودٌ', 'مغمود', 'اسم مفعول', 'غمد', 'مغمود', 'مغمد', 'مفع. مِن غَمَدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَغْمُودٌ-مَغْمُودٌ [غ م د] (مفع. مِن غَمَدَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5466, 'مَغْمُورٌ', 'مغمور', 'اسم مفعول', 'غمر', 'مغمور', 'مغمر', 'مفع. مِن غَمَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن غَمَرَ). 1.""رَجُلٌ مَغْمُورٌ لاَ ذِكْرَ لَهُ"" : مَجْهُولٌ، خَامِلُ الذِّكْرِ. 2."""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5467, 'مَغْمُوزٌ', 'مغموز', 'اسم مفعول', 'غمز', 'مغموز', 'مغمز', 'مفع. مِن غَمَزَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن غَمَزَ). ""رَجُلٌ مَغْمُوزٌ"" : مُتَّهَمٌ بِعَيْبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5468, 'مُغَمَّضٌ', 'مغمض', 'اسم مفعول', 'غمض', 'مغمض', 'مغمض', 'مفع. مِن غَمَّضَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن غَمَّضَ). ""أَدْخَلُوهُ إِلَى غُرْفَةٍ مُغَمَّضَ العَيْنَيْنِ"" : مُطْبَقَ العَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5469, 'مُغَيَّبٌ', 'مغيب', 'اسم مفعول', 'غيب', 'مغيب', 'مغب', 'مفع. مِن غَيَّبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن غَيَّبَ). ""رَجُلٌ مُغَيَّبٌ"" : أَيْ أُبْعِدَ وتَمَّ تَغْيِيبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5470, 'مُغَيَّرٌ', 'مغير', 'اسم مفعول', 'غير', 'مغير', 'مغر', 'مفع. مِن غَيَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُغَيَّرٌ-مُغَيَّرٌ، ةٌ [غ ي ر] (مفع. مِن غَيَّرَ). ""لَوْنُهُ مُغَيَّرٌ"" : مُبَدَّلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5471, 'مُغَيَّمٌ', 'مغيم', 'اسم مفعول', 'غيم', 'مغيم', 'مغم', 'مفع. مِن غَيَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُغَيَّمٌ-مُغَيَّمٌ، ةٌ [غ ي م] (مفع. مِن غَيَّمَ). ""يَوْمٌ مُغَيَّمٌ"" : يَوْمٌ تُخَيِّمُ عَلَيْهِ الغُيُومُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5472, 'مُفَتَّتٌ', 'مفتت', 'اسم مفعول', 'فتت', 'مفتت', 'مفت', 'مفع. مِن فَتَّتَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُفَتَّتٌ-مُفَتَّتٌ، ةٌ [ف ت ت] (مفع. مِن فَتَّتَ). ""خُبْزٌ مُفَتَّتٌ"": مُكَسَّرٌ إِلَى فُتَاتٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5473, 'مَفْتُوحٌ', 'مفتوح', 'اسم مفعول', 'فتح', 'مفتوح', 'مفتح', 'مفع. مِن فَتَحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"مَفْتُوحٌ-مَفْتُوحٌ، ةٌ [ف ت ح] (مفع. مِن فَتَحَ). ""بَابٌ مَفْتُوحٌ"": مُشْرَعٌ عَلَى مِصْرَاعَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5474, 'مَفْتُولٌ', 'مفتول', 'اسم مفعول', 'فتل', 'مفتول', 'مفتل', 'مفع. مِن فَتَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن فَتَلَ). ""رَجُلٌ مَفْتُولُ السَّاعِدِ"" : قَوِيُّ العَضَلاَتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5475, 'مَفْتُونٌ', 'مفتون', 'اسم مفعول', 'فتن', 'مفتون', 'مفتن', 'مفع. مِن فَتَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن فَتَنَ). ""مَفْتُونٌ بِجَمَالِ الطَّبِيعَةِ"" : مَأْخُوذٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5476, 'مَفْجُوعٌ', 'مفجوع', 'اسم مفعول', 'فجع', 'مفجوع', 'مفجع', 'مفع. مِن فَجَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن فَجَعَ). ""رَجُلٌ مَفْجُوعٌ"" : مُصَابٌ بِفَاجِعَةٍ مُؤْلِمَةٍ. ""إِنَّ التَّجَمُّلَ بِالصَّبْرِ هُوَ آخِرُ سِلاَحِ الْمَفْجُوعِ"". (إسحق الحسيني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5477, 'مَفْدِيٌّ', 'مفدي', 'اسم مفعول', 'فدي', 'مفدي', 'مفد', 'مفع. مِن فَدَى', '', 'ة', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. مِن فَدَى). ""رَجُلٌ مَفْدِيٌّ"" : مُفَدّىً مَنْ خُلِّصَ مِنَ الأَسْرِ بِمُقَابِلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5478, 'مَفْرُوشٌ', 'مفروش', 'اسم مفعول', 'فرش', 'مفروش', 'مفرش', 'مفع. من فَرَشَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من فَرَشَ). 1.""بَيْتٌ مَفْرُوشٌ"" : مُؤَثَّثٌ. ""شُقَقٌ مَفْرُوشَةٌ"". 2.""مَفْرُوشَاتُ البَيْتِ"" : أَثَاثُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5479, 'مَفْرُوضٌ', 'مفروض', 'اسم مفعول', 'فرض', 'مفروض', 'مفرض', 'مفع. من فَرَضَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَفْرُوضٌ-مَفْرُوضٌ، ةٌ [ف ر ض] (مفع. من فَرَضَ). ""مِنَ الْمَفْرُوضِ أَنْ"" : مِنَ الوَاجِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5480, 'مَفْرُوغٌ', 'مفروغ', 'اسم مفعول', 'فرغ', 'مفروغ', 'مفرغ', 'مفع. من فَرَغَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَفْرُوغٌ-مَفْرُوغٌ، ةٌ [ف ر غ] (مفع. من فَرَغَ). 1.""إِنَاءٌ مَفْرُوغٌ"" : أُفْرِغَ مِمَّا فِيهِ. 2.""مَاءٌ مَفْرُوغٌ"" : سَائِلٌ. 3.""كَلاَمٌ مَفْرُوغٌ مِنْهُ"": مُنْتَهٍ، تَامٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5481, 'مُفَرَّقٌ', 'مفرق', 'اسم مفعول', 'فرق', 'مفرق', 'مفرق', 'مفع. من فَرَّقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُفَرَّقٌ-مُفَرَّقٌ [ف ر ق] (مفع. من فَرَّقَ). ""البَيْعُ بِالْمُفَرَّقِ"": ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5482, 'مَفْرُوكٌ', 'مفروك', 'اسم مفعول', 'فرك', 'مفروك', 'مفرك', 'مفع. من فَرَكَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَفْرُوكٌ-مَفْرُوكٌ، ةٌ [ف ر ك] (مفع. من فَرَكَ). 1.""حَبٌّ مَفْرُوكٌ"": تَمَّ فَرْكُهُ وَحَكُّهُ. 2.""رَجُلٌ مَفْرُوكٌ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5483, 'مَفْرُومٌ', 'مفروم', 'اسم مفعول', 'فرم', 'مفروم', 'مفرم', 'مفع. من فَرَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَفْرُومٌ-مَفْرُومٌ [ف ر م] (مفع. من فَرَمَ). ""لَحْمٌ مَفْرُومٌ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5484, 'مُفَسَّرٌ', 'مفسر', 'اسم مفعول', 'فسر', 'مفسر', 'مفسر', 'مفع. من فَسَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُفَسَّرٌ-مُفَسَّرٌ، ةٌ [ف س ر] (مفع. من فَسَّرَ). ""نَصٌّ مُفَسَّرٌ"": مَشْرُوحٌ، مُؤَوَّلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5485, 'مُفَصَّلٌ', 'مفصل', 'اسم مفعول', 'فصل', 'مفصل', 'مفصل', 'مفع. من فَصَّلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُفَصَّلٌ-مُفَصَّلٌ، ةٌ [ف ص ل] (مفع. من فَصَّلَ). 1.""قُمَاشٌ مُفَصَّلٌ"" : أَيْ فُصِّلَ إِلَى أَجْزَاءٍ. 2.""حَدِيثٌ مُفَصَّلٌ"" : مُبَيَّنٌ بِكُلِّ أَجْزَائِهِ وحَيْثِيَّاتِهِ. ""بَيَانٌ مُفَصَّلٌ بِالوَقَائِعِ"" ""اِسْتَمَعَ إِلَى نَشْرَةِ الأَخْبَارِ الْمُفَصَّلَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5486, 'مُفَضَّضٌ', 'مفضض', 'اسم مفعول', 'فضض', 'مفضض', 'مفض', 'مفع. من فَضَّضَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُفَضَّضٌ-مُفَضَّضٌ [ف ض ض] (مفع. من فَضَّضَ). ""مَعْدِنٌ مُفَضَّضٌ"" : مَطْلِيٌّ بِالفِضَّةِ، أَوْ مُرَصَّعٌ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5487, 'مُفَضَّلٌ', 'مفضل', 'اسم مفعول', 'فضل', 'مفضل', 'مفضل', 'مفع. من فَضَّلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من فَضَّلَ) . ""عَمَلٌ مُفَضَّلٌ لَدَيْهِ"" : أَثِيرٌ ل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5488, 'مَفْعُولٌ', 'مفعول', 'اسم مفعول', 'فعل', 'مفعول', 'مفعل', 'مفع. من فَعَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مَفَاعِيلُ"', '', '', '', '', '', '', '', '', '"(مفع. من فَعَلَ). 1.""دَوَاءٌ لَهُ مَفْعُولٌ قَوِيٌّ"" : تَأْثِيرٌ، أَثَرٌ، نَتِيجَةٌ. 2. ""قَانُونٌ لَهُ مَفْعُولٌ رَجْعِيّ"" : أَيْ يَشْمُلُ مَا قَبْلَهُ. 3. ""مَفْعُولٌ بِهِ"" : هُوَ اسْمٌ مَنْصُوبٌ يَقَعُ عَلَيْهِ فِعْلُ الفَاعِلِ : ""قَذَفَ اللاعِبُ الكُرَةَ"". 4.""الْمَفْعُولُ لَهُ، الْمَفْعُولُ لأَجْلِهِ"" : هُوَ مَصْدَرٌ يُبَيِّنُ سَبَبَ مَا قَبْلَهُ ويُشَارِكُ عَامِلَهُ فِي الزَّمَانِ وفِي الفَاعِلِ، ويُخَالِفُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5489, 'مَفَاعِيلُ', 'مفاعيل', 'اسم مفعول', '', 'مفاعيل', 'مفعل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5490, 'مَفْقُودٌ', 'مفقود', 'اسم مفعول', 'فقد', 'مفقود', 'مفقد', 'مفع. من فَقَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من فَقَدَ). 1. ""صَارَ الْحَلِيبُ مَفْقُوداً"" : أَيْ غَيْرَ مَوْجُودٍ، لاَ أَثَرَ لَهُ. 2.""عَزِيزٌ مَفْقُودٌ"" : فَقِيدٌ. ""أَصْبَحَ مَفْقُودًا مَا كَانَ عَزِيزاً فَقْدُهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5491, 'مَفْكُوكٌ', 'مفكوك', 'اسم مفعول', 'فكك', 'مفكوك', 'مفكك', 'مفع. من فَكَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَفْكُوكٌ-مَفْكُوكٌ [ف ك ك] (مفع. من فَكَّ). ""جهِاَزٌ مَفْكُوكُ الأَجْزَاءِ"" : مَفْصُولُ الأَجْزَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5492, 'مُفَكَّرٌ', 'مفكر', 'اسم مفعول', 'فكر', 'مفكر', 'مفكر', 'مفع. من فَكَّرَ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُفَكَّرٌ-مُفَكَّرٌ [ف ك ر] (مفع. من فَكَّرَ). ""أَفْكَارٌ مُفَكَّرٌ فِيهَا"" : أَيْ سَبَقَ التَّفْكِيرُ فِيهَا. ""ظَهَرَتْ آرَاءٌ غَيْرُ مُفَكَّرٍ فِيهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5493, 'مُفَكَّكٌ', 'مفكك', 'اسم مفعول', 'فكك', 'مفكك', 'مفك', 'مفع. من فَكَّكَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُفَكِّكٌ، ةٌ - [ف ك ك]. (مفع. من فَكَّكَ). 1. ""جِهَازٌ مُفَكَّكٌ"" : أَيْ حُلَّتْ قِطَعُهُ إِلَى أَجْزَاءٍ. 2.""عَمَلٌ مُفَكَّكٌ"" : غَيْرُ مُحْكَمٍ. ""رِوَايَةٌ غَرِيبَةُ الأَطْوَارِ مُفَكَّكَةُ الفُصُولِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5494, 'مَفْلُوجٌ', 'مفلوج', 'اسم مفعول', 'فلج', 'مفلوج', 'مفلج', 'مفع. مِن فَلِجَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مَفَالِيجُ"', '', '', '', '', '', '', '', '', '"(مفع. مِن فَلِجَ). ""رَجُلٌ مَفْلُوجٌ"" : مُصَابٌ بِدَاءِ الفَالِجِ، أَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5495, 'مَفَاهِيمُ', 'مفاهيم', 'اسم مفعول', '', 'مفاهيم', 'مفهم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5496, 'مَفْلُوحٌ', 'مفلوح', 'اسم مفعول', 'فلح', 'مفلوح', 'مفلح', 'مفع. من فَلَحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَفْلُوحٌ-مَفْلُوحٌ، ةٌ [ف ل ح] (مفع. من فَلَحَ). ""حَقْلٌ مَفْلُوحٌ"" : مَحْرُوثٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5497, 'مُفَلْفَلٌ', 'مفلفل', 'اسم مفعول', 'فلفل', 'مفلفل', 'مفلفل', 'مفع. من فَلْفَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُفَلْفَلٌ-مُفَلْفَلٌ [ف ل ف ل] (مفع. من فَلْفَلَ). 1. ""طَعَامٌ مُفَلْفَلٌ"": طَعَامٌ وُضِعَ فِيهِ الفُلْفُلُ. 2. ""الأَرُزُّ الْمُفَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5498, 'مَفْلُوقٌ', 'مفلوق', 'اسم مفعول', 'فلق', 'مفلوق', 'مفلق', 'مفع. مِن فَلَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَفْلُوقٌ-مَفْلُوقٌ [ف ل ق] (مفع. مِن فَلَقَ). 1.""حَافِرٌ مَفْلُوقٌ"": مَشْقُوقٌ،"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5499, 'مُفَنَّدٌ', 'مفند', 'اسم مفعول', 'فند', 'مفند', 'مفند', 'مفع. من فَنَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُفَنَّدٌ-مُفَنَّدٌ، ةٌ [ف ن د] (مفع. من فَنَّدَ). ""رَأْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5500, 'مُفَهْرَسٌ', 'مفهرس', 'اسم مفعول', 'فهرس', 'مفهرس', 'مفهرس', 'مفع. من فَهْرَسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُفَهْرَسٌ-مُفَهْرَسٌ، ةٌ [ف هـ ر س] (مفع. من فَهْرَسَ). ""كِتَابٌ مُفَهْرَسٌ"" : كِتَابٌ تَمَّ تَبْوِيبُ مَوَاضِيعِهِ وأَسْمَائِهِ وفَهْرَسَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5501, 'مَفْهُومٌ', 'مفهوم', 'اسم مفعول', 'فهم', 'مفهوم', 'مفهم', 'مفع. من فَهِمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مَفَاهِيمُ"', '', '', '', '', '', '', '', '', '"(مفع. من فَهِمَ). 1.""مَفْهُومُ التُّرَاثِ"" : مَجْمُوعُ الصِّفَاتِ والخَصَائِصِ الْمُوَضِّحَةِ لِمَعْنَاهُ ومَدْلُول"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5502, 'مَفَاهِيمُ', 'مفاهيم', 'اسم مفعول', '', 'مفاهيم', 'مفهم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5503, 'مُفَوَّضٌ', 'مفوض', 'اسم مفعول', 'فوض', 'مفوض', 'مفض', 'مفع. من فَوَّضَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من فَوَّضَ). 1. ""الْمُفَوَّضُ السَّامِي"" : مَنْ فُوِّضَتْ إِلَيْهِ إِدَارَةُ دَائِرَةٍ حُكُومِيَّةٍ. 2. ""مُفَوَّضُ الشُّرْطَةِ"" : ضَابِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5504, 'مُفَوَّهٌ', 'مفوه', 'اسم مفعول', 'فوه', 'مفوه', 'مفه', 'مفع. من فَوَّهَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من فَوَّهَ). ""خَطِيبٌ مُفَوَّهٌ"" : بَلِيغٌ جَيِّدُ الكَلاَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5505, 'مُقَابَلٌ', 'مقابل', 'اسم مفعول', 'قبل', 'مقابل', 'مقبل', 'مفع. من قَابَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُقَابَلٌ - [ق ب ل]. (مفع. من قَابَلَ). ""رَجُلٌ مُقَابَلٌ"" : رَجُلٌ كَرِيمُ النَّسَبِ مِنْ قِبَلِ أَبَوَيْهِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5506, 'مَقُودٌ', 'مقود', 'اسم مفعول', 'قود', 'مقود', 'مقد', 'مفع. من قَادَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَقُودٌ-مَقُودٌ، ةٌ [ق و د] (مفع. من قَادَ). ""حَيَوَانٌ مَقُودٌ"" : يُقَادُ بِمِقْوَدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5507, 'مُقَارَنٌ', 'مقارن', 'اسم مفعول', 'قرن', 'مقارن', 'مقرن', 'مفع. من قَارَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُقَارَنٌ-مُقَارَنٌ [ق ر ن] (مفع. من قَارَنَ). ""أَدَبٌ مُقَارَنٌ"" : الدِّرَاسَةُ الأَدَبِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5508, 'مَقُولٌ', 'مقول', 'اسم مفعول', 'قول', 'مقول', 'مقل', 'مفع. من قَالَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من قَالَ). 1.""لاَ يَهْتَمُّ بِكُلِّ مَقُولٍ"" : بِكُلِّ مَا يُقَالُ. 2. ""مَقُولُ القَوْلِ"" : مَفْعُولُ القَوْلِ. 3. ""مَقُولَةٌ دِينِيَّةٌ"" : الْمَعْنَى العَامُّ لِمَوْضُوعِ الدِّينِ. ""مَقُولَةٌ أَيدِيُولُوجِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5509, 'مُقَبَّبٌ', 'مقبب', 'اسم مفعول', 'قبب', 'مقبب', 'مقب', 'مفع. من قَبَّبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَبَّبٌ-مُقَبَّبٌ، ةٌ [ق ب ب] (مفع. من قَبَّبَ). 1."" ضَرِيحٌ مُقَبَّبٌ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5510, 'مَقْبُورٌ', 'مقبور', 'اسم مفعول', 'قبر', 'مقبور', 'مقبر', 'مفع. من قَبَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَقْبُورٌ، ةٌ - ج: ون، ات. [ق ب ر]. (مفع. من قَبَرَ). ""مَقْبُورٌ فِي قَبْرِهِ"" : مَدْفُونٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5511, 'مَقْبُوضٌ', 'مقبوض', 'اسم مفعول', 'قبض', 'مقبوض', 'مقبض', 'مفع. من قَبَضَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من قَبَضَ). 1.""مَقْبُوضٌ عَلَيْهِ"" : مَن اُعْتُقِلَ، وَقُبِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5512, 'مَقْبُولٌ', 'مقبول', 'اسم مفعول', 'قبل', 'مقبول', 'مقبل', 'مفع. من قَبِلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من قَبِلَ). 1. ""مَقْبُولٌ فِي الْمَعْهَدِ"" : مُوَافَقٌ عَلَى الْتِحَاقِهِ بِالْمَعْهَدِ. 2. ""حَصَلَ عَلَى دَرَجَةِ مَقْبُولٍ فِي الامْتِحَانِ"" : مَنْ حَصَلَ عَلَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5513, 'مَقْتُولٌ', 'مقتول', 'اسم مفعول', 'قتل', 'مقتول', 'مقتل', 'مفع. من قَتَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من قَتَلَ). ""مَقْتُولٌ بِخِنْجَرٍ"" : مَنْ قُتِلَ. ""كَانَ الأَطْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5514, 'مَقْدُودٌ', 'مقدود', 'اسم مفعول', 'قدد', 'مقدود', 'مقدد', 'مفع. من قَدَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من قَدَّ). ""مَقْدُودٌ مِنْ صَخْرٍ"" : مَنْحُوتٌ مِنْ صَخْرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5515, 'مُقَدَّدٌ', 'مقدد', 'اسم مفعول', 'قدد', 'مقدد', 'مقد', 'مفع. من قَدَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَدَّدٌ-مُقَدَّدٌ، ةٌ [ق د د] (مفع. من قَدَّدَ). ""لَحْمٌ مُقَدَّدٌ"" : لَحْمٌ مُمَلَّحٌ يَابِسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5516, 'مُقَدَّرٌ', 'مقدر', 'اسم مفعول', 'قدر', 'مقدر', 'مقدر', 'مفع. من قَدَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"(مفع. من قَدَّرَ). 1.""قَضَاءُ مُقَدَّرٌ"" : مَحْتُومٌ. ""مُقَدَّرٌ عَلَيْهِ العَذَابُ"". 2.""يَتَصَوَّرُ أَنَّ مُقَدَّرَاتِ الْمَشْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5517, 'مَقْدُورٌ', 'مقدور', 'اسم مفعول', 'قدر', 'مقدور', 'مقدر', 'مفع. من قَدَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَقْدُورٌ-مَقْدُورٌ [ق د ر] (مفع. من قَدَرَ). 1. ""أَمْرٌ مَقْدُورٌ عَلَيْهِ"" : مَحْتُومٌ عَلَيْهِ، مُقَد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5518, 'مُقَدَّسٌ', 'مقدس', 'اسم مفعول', 'قدس', 'مقدس', 'مقدس', 'مفع. من قَدَّسَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُقَدَّسٌ-مُقَدَّسٌ، ةٌ [ق د س ] (مفع. من قَدَّسَ). 1. ""الكِتَابُ الْمُقَدَّسُ"" : التَّوْراةُ، الإِنْجِيلُ. 2. ""البَيْتُ الْمُقَدَّسُ"" : بَيْتُ الْمَقْدِس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5519, 'مُقَدَّمٌ', 'مقدم', 'اسم مفعول', 'قدم', 'مقدم', 'مقدم', 'مفع. من قَدَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُقَدَّمٌ-مُقَدَّمٌ [ق د م] (مفع. من قَدَّمَ). 1. ""مُقَدَّمُ السَّفِينَةِ"" : جُؤْجُؤُهَا. 2. ""مُقَدَّمُ الرَّأْسِ"" : الجَبْهَةُ. 3. "" مُقَدَّمٌ عَلَى أَقْرَانِهِ "": مُمَيَّزٌ عَنْهُمْ، أَحْسَنُهُمْ. 4. ""مُقَدَّمُ الْحَيِّ"" : أ. وَظِيفَةٌ إِدَارِيَّةٌ فِي الْمَغْرِبِ تُطْل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5520, 'مَقْذُوفٌ', 'مقذوف', 'اسم مفعول', 'قذف', 'مقذوف', 'مقذف', 'مفع. من قَذَفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '":مَقَاذِيفُ"', '', '', '', '', '', '', '', '', '"مَقْذُوفٌ، ةٌ - ج: ـات، مَقَاذِيفُ. [ق ذ ف]. (مفع. من قَذَفَ). 1. ""حَجَرٌ مَقْذُوفٌ"" : مَرْمِيٌّ بِقُوَّةٍ. 2. ""قَذَفُوهُمْ بِوَابِلٍ مِنَ الْمَقَاذِيفِ"" : القَنابِلِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5521, 'مَقَاذِيفُ', 'مقاذيف', 'اسم مفعول', '', 'مقاذيف', 'مقذف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5522, 'مَقْرُورٌ', 'مقرور', 'اسم مفعول', 'قرر', 'مقرور', 'مقرر', 'مفع. من قَرَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَقْرُورٌ، ةٌ - ج: ون، ات. [ق ر ر]. (مفع. من قَرَّ). 1. ""جَوٌّ مَقْرُورٌ"" : جَوٌّ بَارِدٌ. 2. ""مَقْرُورٌ فِي بَيْتِهِ"" : الَّذِي أَصَابَهُ القَرُّ، البَرْدُ.   ""أَقْبَلَ الرَّبِيعُ وبَدَأَتْ تَبَاشِيرُ الصَّيْفِ تَهُبُّ عَلَى النُّفُوسِ الْمَقْرُورَةِ"". (ع. غلاب)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5523, 'مَقْرُوءٌ', 'مقروء', 'اسم مفعول', 'قرأ', 'مقروء', 'مقر', 'مفع. من قَرَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَقْرُوءٌ-مَقْرُوءٌ [ق ر أ] (مفع. من قَرَأَ). ""خَطٌّ مَقْرُوءٌ "" : خَطُّ يُمْكِنُ قِرَاءتهُ. ""مَخْطوطٌ مَقْروءٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5524, 'مَقْرُوءَةٌ', 'مقروءة', 'اسم مفعول', '', 'مقروءة', 'مقرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَقْرُوءٌ-مَقْرُوءٌ [ق ر أ] (مفع. من قَرَأَ). ""خَطٌّ مَقْرُوءٌ "" : خَطُّ يُمْكِنُ قِرَاءتهُ. ""مَخْطوطٌ مَقْروءٌ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5525, 'مُقَرَّبٌ', 'مقرب', 'اسم مفعول', 'قرب', 'مقرب', 'مقرب', 'مفع. من قَرَّبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من قَرَّبَ). ""مِنَ الْمُقَرَّبِينَ للرَّئِيسِ"" : مَنْ لَهُ مَكَانَةٌ خَاصَّةٌ عِنْدَهُ.الواقعة آية 10 والسَّابِقُونَ السَّابِقُونَ أُولَئِكَ الْمُقَرَّبُونَ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5526, 'مُقَرَّحٌ', 'مقرح', 'اسم مفعول', 'قرح', 'مقرح', 'مقرح', 'مفع. من قَرَّحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَرَّحٌ-مُقَرَّحٌ، ةٌ [ق ر ح] (مفع. من قَرَّحَ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5527, 'مَقْرُوحٌ', 'مقروح', 'اسم مفعول', 'قرح', 'مقروح', 'مقرح', 'مفع. من قَرَحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من قَرَحَ). ""مَقْرُوحُ البَدَنِ"" : مَنْ بِهِ قُرُوحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5528, 'مُقَرَّرٌ', 'مقرر', 'اسم مفعول', 'قرر', 'مقرر', 'مقر', 'مفع. من قَرَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَرَّرٌ-مُقَرَّرٌ، ةٌ [ق ر ر ] (مفع. من قَرَّرَ). 1. ""أَمْرٌ مُقَرَّرٌ"" : ثَابِتٌ، مُعْتَرَفٌ بِهِ. ""أَعْمَالُ مُقَرَّرَةٌ"" ""جَاءَ فِي الْمَوْعِدِ الْمُقَرَّرِ"". 2. ""الْمُقَرَّرُ الدِّرَاسِيُّ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5529, 'مَقْرُونٌ', 'مقرون', 'اسم مفعول', 'قرن', 'مقرون', 'مقرن', 'مفع. من قَرَنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَقْرُونٌ-مَقْرُونٌ، ةٌ [ق ر ن] (مفع. من قَرَنَ). 1. ""اِسْمُهُ مَقْرُونٌ بِالكَرَمِ"" : مُرْتَبِطٌ بـ... 2.""دَوَابُّ مَقْرُونَةٌ"" : مَشْدُودَةٌ مِنْ قُرُونِهَا. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5530, 'مُقَسَّمٌ', 'مقسم', 'اسم مفعول', 'قسم', 'مقسم', 'مقسم', 'مفع. من قَسَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُقَسَّمٌ-مُقَسَّمٌ [ق س م] (مفع. من قَسَّمَ). 1. ""إِرْثٌ مُقَسَّمٌ"": مُوَزَّعٌ. 2. ""الْمُقَسَّمُ الهَاتِفِيُّ"" : لَوْحَةٌ تَسْتَقْبِلُ الْمُكَالَمَاتِ الهَاتِفِيَّةَ حَيْثُ يَتِمُّ تَوْزِيعُهَا عَلَى الخُطُوطِ الدَّاخِلِيَّةِ بِالْمُؤَسَّسَةِ بِوَاسِطَةِ مُرَاقِبٍ دَائِمٍ أَوْ مُرَاقِبَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5531, 'مَقْسُومٌ', 'مقسوم', 'اسم مفعول', 'قسم', 'مقسوم', 'مقسم', 'مفع. من قَسَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَقْسُومٌ-مَقْسُومٌ، ةٌ [ق س م] (مفع. من قَسَمَ). 1. الحجر آية 44 لِكُلِّ بَابٍ مِنْهُمْ جُزْءٌ مَقْسُومٌ . (قرآن) : مَا يُجَزَّأُ بِحِصَصٍ مُتَسَاوِيَةٍ. 2.""الْمَقْسُومُ عَلَيْهِ"" : مَا يُوَزَّعُ عَلَيْهِ الْمَقْسُومُ. فِي العَمَلِيَّةِ الحِسَابِيَّةِ التَّالِيَةِ : 25 : 5 = 5 . العَدَدُ 25 هُوَ الْمَقْسُومُ، والعَدَدُ 5 هُوَ الْمَقْسُومُ عَلَيْهِ، وَالعَدَدُ 5 هُوَ خَارِجُ القِسْمَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5532, 'مُقَشَّبٌ', 'مقشب', 'اسم مفعول', 'قشب', 'مقشب', 'مقشب', 'مفع. من قَشَّبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من قَشَّبَ). 1.""خَشَبٌ مُقَشَّبٌ"" : غَيْرُ صَافٍ. 2.""رَجُلٌ مُقَشَّبُ الْحَسَبِ"" : أَيْ يُخَالِطُ حَسَبَهُ لُؤْمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5533, 'مَقْصُوصٌ', 'مقصوص', 'اسم مفعول', 'قصص', 'مقصوص', 'مقصص', 'مفع. من قَصَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من قَصَّ). 1. ""طَائِرٌ مَقْصُوصُ الجَنَاحَيْنِ"" : مَقْطُوعُ ... 2.""مَقْصُوصُ الجَنَاحِ"" : لاَقُوَّةَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5534, 'مُقَصَّبٌ', 'مقصب', 'اسم مفعول', 'قصب', 'مقصب', 'مقصب', 'مفع. من قَصَّبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَصَّبٌ-مُقَصَّبٌ، ةٌ [ق ص ب] (مفع. من قَصَّبَ). 1.""ثَوْبٌ مُقَصَّبٌ"" : مُوَشّىً بِالذَّهَبِ والفِضَّةِ. 2.""شَعْرٌ مُقَصَّبٌ"" : مُجَعَّدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5535, 'مَقْصُودٌ', 'مقصود', 'اسم مفعول', 'قصد', 'مقصود', 'مقصد', 'مفع. من قَصَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَقْصُودٌ-مَقْصُودٌ، ةٌ [ق ص د] (مفع. من قَصَدَ). ""كَانَ مَقْصُودُهُ ن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5536, 'مُقَصَّرٌ', 'مقصر', 'اسم مفعول', 'قصر', 'مقصر', 'مقصر', 'مفع. من قَصَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَصَّرٌ-مُقَصَّرٌ، ةٌ [ق ص ر] (مفع. من قَصَّرَ). 1. ""فُسْتَانٌ مُقَصَّرٌ"" : أَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5537, 'مَقْصُورٌ', 'مقصور', 'اسم مفعول', 'قصر', 'مقصور', 'مقصر', 'مفع. من قَصَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات:مقاصيرُ"', '', '', '', '', '', '', '', '', '"(مفع. من قَصَرَ). 1.""نَسِيجٌ مَقْصُورٌ"" : نَسِيجٌ قُطْنِيٌّ أَبْيَضُ. 2. ""قَصِيدَةٌ شِعْرِيَّةٌ مَقْصُورَةٌ"" : كَانَتْ قَافِيَتُهَا مَخ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5538, 'مَقَاصِيرُ', 'مقاصير', 'اسم مفعول', '', 'مقاصير', 'مقصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5539, 'مُقَطَّبٌ', 'مقطب', 'اسم مفعول', 'قطب', 'مقطب', 'مقطب', 'مفع. من قَطَّبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من قَطَّبَ). ""مُقَطَّبُ الْحَاجِبَيْنِ"": أَيْ جَمَعَ مَا بَيْنَهُمَا، مُعَبَّسٌ، مُكَشَّرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5540, 'مُقَطَّرٌ', 'مقطر', 'اسم مفعول', 'قطر', 'مقطر', 'مقطر', 'مفع. من قَطَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَطَّرٌ-مُقَطَّرٌ، ةٌ [ق ط ر] (مفع. من قَطَّرَ). ""زَهْرٌ مُقَطَّرٌ"" : أَيْ تَمَّ تَقْطِيرُهُ قَطْرَةً قَطْرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5541, 'مَقْطُوعٌ', 'مقطوع', 'اسم مفعول', 'قطع', 'مقطوع', 'مقطع', 'مفع. من قَطَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"(مفع. من قَطَعَ). 1. ""طَرِيقٌ مَقْطُوعٌ"" : طَرِيقٌ غَيْرُ مُمْكِنٍ اجْتِيَازُهُ. 2.""رَجُلٌ مَقْطُوعٌ بِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5542, 'مَقَاطِيعُ', 'مقاطيع', 'اسم مفعول', '', 'مقاطيع', 'مقطع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5543, 'مُقَعَّرٌ', 'مقعر', 'اسم مفعول', 'قعر', 'مقعر', 'مقعر', 'مفع. من قَعَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَعَّرٌ-مُقَعَّرٌ، ةٌ [ق ع ر] (مفع. من قَعَّرَ). 1. ""بِئْرٌ مُقَعَّرٌ"" : عَمِيقٌ. 2. ""شَكْلٌ هَنْدَسِيٌّ مُقَعَّرٌ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5544, 'مُقَفَّعٌ', 'مقفع', 'اسم مفعول', 'قفع', 'مقفع', 'مقفع', 'مفع. من قَفَّعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من قَفَّعَ). 1. ""رَجُلٌ مُقَفَّعٌ"" : مُنَكَّسُ الرَّأْسِ. 2. ""مُقَفَّعُ اليَدَيْنِ"" : مُتَشَنِّجُهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5545, 'مَقْلُوبٌ', 'مقلوب', 'اسم مفعول', 'قلب', 'مقلوب', 'مقلب', 'مفع. من قَلَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من قَلَبَ). 1. ""كُرْسِيٌّ مَقْلُوبٌ"" : أَعْلاَهُ أَسْفَلُهُ. ""سَيَّارَةٌ مَقْلُوبَةٌ"". 2.""بِالْمَقْلُوبِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5546, 'مُقَلَّدٌ', 'مقلد', 'اسم مفعول', 'قلد', 'مقلد', 'مقلد', 'مفع. من قَلَّدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من قَلَّدَ). ""مُقَلَّدٌ بِوِسَامٍ"" : مَنْ وُضِعَ عَلَى صَدْرِهِ أَوْ عُنُقِهِ وِسَامٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5547, 'مَقْلِيٌّ', 'مقلي', 'اسم مفعول', 'قلي', 'مقلي', 'مقل', 'مفع. من قَلَى', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَقْلِيٌّ-مَقْلِيٌّ، ةٌ [ق ل ي] (مفع. من قَلَى). ""لَحْمٌ مَقْلِيٌّ"" : لَحْمٌ قُلِيَ فِي المِقْلاَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5548, 'مَقْمُوعٌ', 'مقموع', 'اسم مفعول', 'قمع', 'مقموع', 'مقمع', 'مفع. من قَمَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من قَمَعَ). ""وَلَدٌ مَقْمُوعٌ"" : مَقْهُورٌ، مَنْ تَعَرَّضَ لِلْقَمْعِ والقَهْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5549, 'مُقَمَّلٌ', 'مقمل', 'اسم مفعول', 'قمل', 'مقمل', 'مقمل', 'مفع. من قَمَّلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُقَمَّلٌ-مُقَمَّلٌ، ةٌ [ق م ل] (مفع. من قَمَّلَ). ""ثَوْبٌ مُقَمَّلٌ"" : ثَوْبٌ اِنْتَشَرَ فِيهِ القُمَّلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5550, 'مُقَنْطَرٌ', 'مقنطر', 'اسم مفعول', 'قنطر', 'مقنطر', 'مقنطر', 'مفع. من قَنْطَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَنْطَرٌ-مُقَنْطَرٌ، ةٌ [ق ن ط ر] (مفع. من قَنْطَرَ). 1. ""بِنَاءٌ مُقَنْطَرٌ"" : مُتَقَوِّسٌ كَالقَنْطَرَةِ. 2. ""القَنَاطِيرُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5551, 'مُقَنَّعٌ', 'مقنع', 'اسم مفعول', 'قنع', 'مقنع', 'مقنع', 'مفع. من قَنَّعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من قَنَّعَ). 1. ""مُمَثِّلٌ مُقَنَّعٌ"" : عَلَى وَجْهِهِ قِنَاعٌ. مُجْرِمٌ مُقَنَّعٌ"". 2.""جَاءَ بِك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5552, 'مُقَوَّرٌ', 'مقور', 'اسم مفعول', 'قور', 'مقور', 'مقر', 'مفع. من قَوَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَوَّرٌ-مُقَوَّرٌ، ةٌ [ق و ر] (مفع. من قَوَّرَ). 1.""ثَوْبٌ مُقَوَّرٌ"": مَفْتُوحٌ، مَكْشُوفٌ. 2.""أَثْوَابٌ مُقَوَّرَةٌ"" : مَقْطُوعَةٌ أَطْرَافاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5553, 'مُقَوَّسٌ', 'مقوس', 'اسم مفعول', 'قوس', 'مقوس', 'مقس', 'مفع. من قَوَّسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من قَوَّسَ). 1. ""بِنَاءٌ مُقَوَّسٌ"" : مَا كَانَ عَلَى شَكْلِ قَوْسٍ. 2. ""ظَهْرٌ مُقَوَّسٌ"" : مُنْحَنٍ. 3. ""أَنْفٌ مُقَوَّسٌ"" : مُحَدَّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5554, 'مُقَوَّضٌ', 'مقوض', 'اسم مفعول', 'قوض', 'مقوض', 'مقض', 'مفع. من قَوَّضَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَوَّضٌ-مُقَوَّضٌ، ةٌ [ق و ض] (مفع. من قَوَّضَ). ""بِنَاءٌ مُقَوَّضٌ"" : مُهَدَّمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5555, 'مُقَوْلَبٌ', 'مقولب', 'اسم مفعول', 'قولب', 'مقولب', 'مقلب', 'مفع. من قَوْلَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَوْلَبٌ-مُقَوْلَبٌ، ةٌ [ق و ل ب] (مفع. من قَوْلَبَ). ""مَادَّةٌ مُقَوْلَبَةٌ"" : أَيْ وُضِعَتْ فِي قَالَبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5556, 'مُقَوَّمٌ', 'مقوم', 'اسم مفعول', 'قوم', 'مقوم', 'مقم', 'مفع. من قَوَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَوَّمٌ-مُقَوَّمٌ، ةٌ [ق و م] (مفع. من قَوَّمَ). 1.""عَمَلٌ مُقَوَّمٌ"" : عَمَلٌ تَمَّ تَقْوِيمُهُ وَ إِظْهَارُ قِيمَتِهِ. 2.""ثَمَنٌ مُقَوَّمٌ"" : أَيْ ثَمَنُهُ وُضِعَ حَسَبَ قِيمَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5557, 'مُقَوّىً', 'مقوى', 'اسم مفعول', 'قوي', 'مقوى', 'مق', 'مفع. من قَوَّى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"مُقَوّىً-مُقَوّىً، ةٌ [ق و ي] (مفع. من قَوَّى). ""وَرَقٌ مُقَوّىً"": وَرَقٌ غَلِيظٌ، صَفِيقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5558, 'مُقَوّاة', 'مقواة', 'اسم مفعول', '', 'مقواة', 'مقة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَوّىً-مُقَوّىً، ةٌ [ق و ي] (مفع. من قَوَّى). ""وَرَقٌ مُقَوّىً"": وَرَقٌ غَلِيظٌ، صَفِيقٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5559, 'مُقَيَّدٌ', 'مقيد', 'اسم مفعول', 'قيد', 'مقيد', 'مقد', 'مفع. من قَيَّدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من قَيَّدَ). 1.""مُقَيَّدٌ بِالسَّلاَسِلِ"" : مُكَبَّلٌ. 2.""حَيَوَانٌ مُقَيَّدٌ"" : مَرْبُوطٌ بِقَيْدٍ. 3.""كِتَابٌ مُقَيَّدٌ"" : مَشْكُولٌ. 4.""عَقْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5560, 'مُكَافَأٌ', 'مكافأ', 'اسم مفعول', 'كفأ', 'مكافء', 'مكف', 'مفع. مِن كَافَأَ', '', '', 'مفرد', 'Dz', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن كَافَأَ). ""مُكَافَأٌ عَلَى عَمَلِهِ"" : مُجَازىً عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5561, 'مُكَافَأَةٌ', 'مكافأة', 'اسم مفعول', '', 'مكافءة', 'مكفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. مِن كَافَأَ). ""مُكَافَأٌ عَلَى عَمَلِهِ"" : مُجَازىً عَلَيْهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5562, 'مَكْبُوتٌ', 'مكبوت', 'اسم مفعول', 'كبت', 'مكبوت', 'مكبت', 'مفع. من كَبَتَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَكْبُوتٌ-مَكْبُوتٌ [ك ب ت] (مفع. من كَبَتَ). ""شَابٌّ مَكْبُوتٌ"" : مَقْموعٌ، أَيْ مَنْ كَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5563, 'مَكْتُوبٌ', 'مكتوب', 'اسم مفعول', 'كتب', 'مكتوب', 'مكتب', 'مفع. من كَتَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَكَاتِيبُ"', '', '', '', '', '', '', '', '', '"(مفع. من كَتَبَ). 1. ""بُعِثَ إِلَيْهِ بِمَكْتُوبٍ"" : بِرِسَالَةٍ. 2.""كَلاَمٌ مَكْتُوبٌ بِعَاطِفَةٍ جَيَّاشَةٍ"" : مَخْطُوطٌ. 3.""مَا حَدَثَ مَكْتُوبٌ عَلَى الجَبِينِ"" : مُقَدَّرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5564, 'مَكَاتِيبُ', 'مكاتيب', 'اسم مفعول', '', 'مكاتيب', 'مكتب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5565, 'مَكْتُوفٌ', 'مكتوف', 'اسم مفعول', 'كتف', 'مكتوف', 'مكتف', 'مفع. من كَتَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من كَتَفَ). 1. ""أَسِيرٌ مَكْتُوفٌ"" : مَوْثُوقٌ. 2. ""وَقَفَ مَكْتُوفَ اليَدَيْنِ"" : عَاجِزاً عَنِ الْحَرَكَةِ والْمُبَادَرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5566, 'مُكَتَّلٌ', 'مكتل', 'اسم مفعول', 'كتل', 'مكتل', 'مكتل', 'مفع. من كَتَّلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُكَتَّلٌ-مُكَتَّلٌ، ةٌ [ك ت ل] (مفع. من كَتَّلَ). 1.""رَمْلٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5567, 'مَكْتُومٌ', 'مكتوم', 'اسم مفعول', 'كتم', 'مكتوم', 'مكتم', 'مفع. من كَتَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"(مفع. من كَتَمَ). 1. ""مَكْتُومُ النَّفَسِ"" : مَخْنُوقٌ ... اِنْطَلَقَتْ ضَحَكَاتٌ مَكْتُومَةٌ"". 2. ""صَوْتٌ مَكْتُومٌ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5568, 'مُكَثَّرٌ', 'مكثر', 'اسم مفعول', 'كثر', 'مكثر', 'مكثر', 'مفع. من كَثَّرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُكَثَّرٌ-مُكَثَّرٌ، ةٌ [ك ث ر] (مفع. من كَثَّرَ). ""نَبَاتٌ مُكَثَّرٌ"" : مُنَمّىً، مَزِيدٌ. ""مَادَّةٌ مُكَثَّرَةٌ فِي الأَسْوَاقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5569, 'مُكَثَّفٌ', 'مكثف', 'اسم مفعول', 'كثف', 'مكثف', 'مكثف', 'مفع. من كَثَّفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُكَثَّفٌ-مُكَثَّفٌ، ةٌ [ك ث ف] (مفع. من كَثَّفَ). 1. ""مَعْدِنٌ مُكَثَّفٌ"" : مُتَجَمِّعُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5570, 'مَكْدُودٌ', 'مكدود', 'اسم مفعول', 'كدد', 'مكدود', 'مكدد', 'مفع. من كَدَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"(مفع. من كَدَّ). 1. ""رَجَعَ مِنْ عَمَلِهِ مَكْدُوداً"" : تَعِباً"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5571, 'مُكَدَّرٌ', 'مكدر', 'اسم مفعول', 'كدر', 'مكدر', 'مكدر', 'مفع. من كَدَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"(مفع. من كَدَّرَ). 1. ""مَاءٌ مُكَدَّرٌ"" : مُخْتَلِطٌ بِأَتْرِبَةٍ ومَا شَابَهَ ذَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5572, 'مَكْرُوبٌ', 'مكروب', 'اسم مفعول', 'كرب', 'مكروب', 'مكرب', 'مفع. من كَرَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من كَرَبَ). ""وَجَدْتُهُ مَكْرُوباً"" : مَهْمُوماً. ""كَيْفَ تَصَامَمَتْ عَنْ نِدَاءِ قَلْبِي الْمَكْرُوبِ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5573, 'مُكَرَّرٌ', 'مكرر', 'اسم مفعول', 'كرر', 'مكرر', 'مكر', 'مفع. من كَرَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُكَرَّرٌ-مُكَرَّرٌ، ةٌ [ك ر ر] (مفع. من كَرَّرَ). 1.""رَقْمٌ مُكَرَّرٌ"": مَكْرورٌ، مُعَادٌ. ""فِكْرَةٌ مُكَرَّرَةٌ"". 2.""نَفْطٌ مُكَرَّرٌ"" : مُصَفّىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5574, 'مُكَرَّسٌ', 'مكرس', 'اسم مفعول', 'كرس', 'مكرس', 'مكرس', 'مفع. من كَرَّسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُكَرَّسٌ-مُكَرَّسٌ، ةٌ [ك ر س] (مفع. من كَرَّسَ). 1. ""بَحْثٌ مُكَرَّسٌ لِخِدْمَةِ العِلْمِ"" : مُخَصَّصٌ. ""حَي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5575, 'مُكَرَّمٌ', 'مكرم', 'اسم مفعول', 'كرم', 'مكرم', 'مكرم', 'مفع. من كَرَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من كَرَّمَ). ""رَجُلٌ مُكَرَّمٌ"" : مُعَزَّزٌ، مُحْتَرَمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5576, 'مَكْرُوهٌ', 'مكروه', 'اسم مفعول', 'كره', 'مكروه', 'مكره', 'مفع. من كَرِهَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من كَرِهَ). 1. ""رَجُلٌ مَكْرُوهٌ"" : مَمْقُوتٌ. 2. ""أَصَابَهُ مَكْرُوهٌ"" : أَصَابَهُ شَرٌّ، شِدَّةٌ، بَلِيَّةٌ. ""وَقَاكَ اللَّهُ كُلَّ مَكْرُوهٍ"" ""لاَ أَرَاكُمُ اللَّهُ بَعْدَ اليَوْمِ مَكْرُوهاً"". 3. ""فِعْلٌ مَكْرُوهٌ"" : مَا يُسْتَحْسَنُ تَرْكُهُ فِي قَضَايَا الفَرَائِضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5577, 'مُكَسَّرٌ', 'مكسر', 'اسم مفعول', 'كسر', 'مكسر', 'مكسر', 'مفع. من كَسَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من كَسَّرَ). 1.""سُكَّرٌ مُكَسَّرٌ"" : مُفَتَّتٌ. 2. ""جَمْعُ الْمُكَسَّرِ"" : جَمْعُ التَّكْسِيرِ. ن. تَكْسِير. 3.""يَقْتَاتُ بِالْمُكَسَّرَاتِ"" : أَيِ الجَوْز واللَّوْز والفَوَاكِه الجَافَّة ونَحْوها، النُّقْل."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5578, 'مَكْسُورٌ', 'مكسور', 'اسم مفعول', 'كسر', 'مكسور', 'مكسر', 'مفع. من كَسَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"(مفع. من كَسَرَ). 1. ""مَكْسُورُ الخَاطِرِ"" : خَائِرُ النَّفْسِ، مُكْتَئِبٌ، مُحْبَطٌ. 2. ""بَيْتٌ شِعْرِيٌّ مَكْسُورٌ"" : أَيْ وَزْنُهُ غَيْرُ قَائِمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5579, 'مَكَاسِيرُ', 'مكاسير', 'اسم مفعول', '', 'مكاسير', 'مكسر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5580, 'مَكْشُوفٌ', 'مكشوف', 'اسم مفعول', 'كشف', 'مكشوف', 'مكشف', 'مفع. من كَشَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من كَشَفَ). 1. ""مَكْشُوفُ الرَّأْسِ"" : حاسِرُ الرَّأْسِ، عَارِي الرَّأْسِ. 2. ""عَلَى الْمَكْشُو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5581, 'مَكْظُومٌ', 'مكظوم', 'اسم مفعول', 'كظم', 'مكظوم', 'مكظم', 'مفع. من كَظَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من كَظَمَ). ""أَحَسَّ بِالْحَاجَةِ إِلَى التَّنْفِيسِ عَنْ غَيْظِهِ الْمَك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5582, 'مَكْفُوفٌ', 'مكفوف', 'اسم مفعول', 'كفف', 'مكفوف', 'مكفف', 'مفع. من كَفَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من كَفَّ). ""مَكْفُوفُ البَصَرِ"" : أَعْمَى. ""جَمْعِيَّةُ الْمَكْفُوفِينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5583, 'مَكَافِيفُ', 'مكافيف', 'اسم مفعول', '', 'مكافيف', 'مكفف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5584, 'مَكْفُولٌ', 'مكفول', 'اسم مفعول', 'كفل', 'مكفول', 'مكفل', 'مفع. من كَفَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من كَفَلَ). 1. ""وَلَدٌ مَكْفُولٌ"" : مَنْ هُوَ فِي كَفَالَةِ غَيْرِهِ. 2."" أَمْوَالٌ مَكْفُولَةٌ"" : مَضْمُونَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5585, 'مُكَفَّنٌ', 'مكفن', 'اسم مفعول', 'كفن', 'مكفن', 'مكفن', 'مفع. من كَفَّنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من كَفَّنَ). ""مُكَفَّنٌ فِي كَفَنِهِ"" : أُلْبِسَ الكَفَنَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5586, 'مُكَلَّفٌ', 'مكلف', 'اسم مفعول', 'كلف', 'مكلف', 'مكلف', 'مفع. من كَلَّفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من كَلَّفَ). 1. ""شَابٌّ مُكَلَّفٌ"" : مَنْ بَلَغَ سِنَّ الرُّشْدِ. 2. ""مُكَلَّفٌ بِمُهِمَّةٍ"" : مَوْكُول"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5587, 'مُكَلَّلٌ', 'مكلل', 'اسم مفعول', 'كلل', 'مكلل', 'مكل', 'مفع. من كَلَّلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من كَلَّلَ). 1. ""مُكَلَّلٌ بِإِكْلِيلٍ مِنَ الذَّهَبِ"" : مُتَوَّجٌ. وفِي جَفْنَةٍ مَا يُغْلَقُ البَابُ دُونَهَا*مُكَلَّلَـةٍ لَحْماً مُدَفَّقـَـةٍ ثَــرْداً (المقنع الكندي). 2.""أَعْمَالُهُ مُكَلَّلَةٌ بِالنَّجَاحِ"" : أَتَتْ أُكْلَهَا، مُتَوَّجَةٌ بِالنَّجَاحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5588, 'مَكْمُومٌ', 'مكموم', 'اسم مفعول', 'كمم', 'مكموم', 'مكمم', 'مفع. من كَمَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَكْمُومٌ-مَكْمُومٌ، ةٌ [ك م م ] (مفع. من كَمَّ). 1. ""حَيَوَانٌ مَكْمُومٌ"" : مُكَمَّمٌ، أي وُضِعَتِ الكِمامَةُ على خَطْمِهِ لِمَنْعِهِ مِنَ العَضِّ. 2. ""ظَلَّتِ الْحَقِيقَةُ مَكْمُومَةً"" : مَسْتُورَةً، مَخْفِيَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5589, 'مَكْمُودٌ', 'مكمود', 'اسم مفعول', 'كمد', 'مكمود', 'مكمد', 'مفع. من كَمِدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', '', '', '', '', '', '', '"(مفع. من كَمِدَ). ""بَقِيَ مَحْزُوناً مَكْمُوداً"" : حَزِيناً، كَئِيباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5590, 'مُكَمَّمٌ', 'مكمم', 'اسم مفعول', 'كمم', 'مكمم', 'مكم', 'مفع. من كَمَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"(مفع. من كَمَّمَ). 1. ""رَفَضَ أَنْ يَظَلَّ مُكَمَّمَ الفَمِ"" : مَمْنُوعاً مِنَ الكَلاَمِ، وَمِنْ حُرِّيَّةِ التَّعْبِيرِ. 2.""حَيَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5591, 'مَكْنُونٌ', 'مكنون', 'اسم مفعول', 'كنن', 'مكنون', 'مكنن', 'مفع. من كَنَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من كَنَّ). 1.""مَالٌ مَكْنُونٌ"" : مَسْتُورٌ، مَخْفِيٌّ عَنِ الأَعْيُنِ.الواقعة آية 22 وَحُورٌ عَيْنٌ كَأَمْثَالِ اللُّؤْلُؤِ الْمَكْنُونِ (قرآن) ""جَوَاهِرُ مَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5592, 'مُكَنّىً', 'مكنى', 'اسم مفعول', 'كني', 'مكنى', 'مكن', 'مفع. من كَنَّى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"مُكَنّىً-مُكَنّىً [ك ن ي] (مفع. من كَنَّى). ""مُكَنّىً بِأَبِي جِهَادٍ"" : أَيْ أُطْلِقَتْ عَلَيْهِ كُنْيَةُ أَبِي جِهَادٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5593, 'مُكَنّاة', 'مكناة', 'اسم مفعول', '', 'مكناة', 'مكنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُكَنّىً-مُكَنّىً [ك ن ي] (مفع. من كَنَّى). ""مُكَنّىً بِأَبِي جِهَادٍ"" : أَيْ أُطْلِقَتْ عَلَيْهِ كُنْيَةُ أَبِي جِهَادٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5594, 'مُكَهْرَبٌ', 'مكهرب', 'اسم مفعول', 'كهرب', 'مكهرب', 'مكهرب', 'مفع. من كَهْرَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُكَهْرَبٌ-مُكَهْرَبٌ [ك هـ ر ب] (مفع. من كَهْرَبَ). 1.""خَيْطٌ مُكَهْر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5595, 'مُكَوَّرٌ', 'مكور', 'اسم مفعول', 'كور', 'مكور', 'مكر', 'مفع. من كَوَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُكَوَّرٌ-مُكَوَّرٌ، ةٌ [ك و ر] (مفع. من كَوَّرَ). ""وَرَقٌ مُكَوَّرٌ"" : مُدَوّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5596, 'مُكَوَّمٌ', 'مكوم', 'اسم مفعول', 'كوم', 'مكوم', 'مكم', 'مفع. من كَوَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من كَوَّمَ). ""تِبْنٌ مُكَوَّمٌ فِي البَيْدَرِ"" : مُجَمَّعٌ أَكْوَاماً"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5597, 'مُكَوَّنٌ', 'مكون', 'اسم مفعول', 'كون', 'مكون', 'مكن', 'مفع. من كَوَّنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من كَوَّنَ). 1.""تِمْثَالٌ مُكَوَّنٌ حَسَبَ نَمُوذَجٍ مُحَدَّدٍ"" : مُرَكَّبٌ، مُؤَلَّفُ الأَجْزَاءِ. 2.""طَالِبٌ مُكَوَّنٌ فِي الْمَعْهَدِ"" : أَيْ تَمَّ تَعْلِيمُهُ العِلْمِيُّ والتَّرْبَوِيُّ فِي الْمَعْهَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5598, 'مَكْوِيٌّ', 'مكوي', 'اسم مفعول', 'كوي', 'مكوي', 'مك', 'مفع. من كَوَى', '', 'ة', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَكْوِيٌّ-مَكْوِيٌّ، ةٌ [ك و ي] (مفع. من كَوَى). "" قَمِيصٌ مَكْوِيٌّ"" : أَيْ تَمَّ كَيُّهُ بِالمِكْوَاةِ. ""جَلاَلِيبُهُمْ نَظِيفَةٌ ولَكِنَّهَا غَيْرُ مَكْوِيَّةٍ"". (الطيب صالح)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5599, 'مُكَيَّفٌ', 'مكيف', 'اسم مفعول', 'كيف', 'مكيف', 'مكف', 'مفع. من كَيَّفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من كَيَّفَ). 1. ""صَارَ مُكَيَّفاً مَعَ الْمُحِيطِ الجَدِيدِ"" : مُنْسَجِماً مَعَهُ. 2.""قِطَارٌ مُكَيَّفُ الهَوَاءِ"" : أَيْ تَمَّ ضَبْطُ هَوَائِهِ حَسَبَ دَرَجَةٍ مِئَوِيَّةٍ مُعَيَّنَةٍ يحُاَفِظُ عَلَيْهَا. ""هَوَاءٌ مُكَيَّفٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5600, 'مُلاَحَقٌ', 'ملاحق', 'اسم مفعول', 'لحق', 'ملاحق', 'ملحق', 'مفع. من لاَحَقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من لاَحَقَ). ""مُلاَحَقٌ مِنْ كُلِّ جِهَةٍ"" : مُقْتَفٍ أَثَرَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5601, 'مُلاَمٌ', 'ملام', 'اسم مفعول', 'لوم', 'ملام', 'ملم', 'مفع. من لاَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُلاَمٌ-مُلاَمٌ [ل و م] (مفع. من لاَمَ). ""مُلاَمٌ عَلَى فِعْلِهِ الْمَشِينِ"" : الْمُتَعَرِّضُ لِمَا يَسْتَحِقُّ اللَّوْمَ عَلَيْهِ مِنْ غَيْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5602, 'مَلُومٌ', 'ملوم', 'اسم مفعول', 'لوم', 'ملوم', 'ملم', 'مفع. من لاَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من لاَمَ). ""مَلُومٌ عَلَى أَفْعَالِهِ السَّيِّئَةِ"" : مَنْ يُلاَمُ عَلَى ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5603, 'مُلَبَّدٌ', 'ملبد', 'اسم مفعول', 'لبد', 'ملبد', 'ملبد', 'مفع. من لَبَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلَبَّدٌ-مُلَبَّدٌ، ةٌ [ل ب د] (مفع. من لَبَّدَ). ""جَوٌّ مُلَبَّدٌ غُيُوماً"": مُغَطَّى بِالغُيُومِ. ""سَمَاءٌ مُلَبَّدَةٌ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5604, 'مُلَبَّسٌ', 'ملبس', 'اسم مفعول', 'لبس', 'ملبس', 'ملبس', 'مفع. من لَبَّسَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من لَبَّسَ). ""لاَ يَتَوَقَّفُ عَنْ أَكْلِ الْمُلَبَّسَاتِ"" : قِطَعٌ مِنْ حَلْوَى اللَّوْزِ ونَحْوِهِ تُلَبَّسُ بِالسُّكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5605, 'مَلْحُوظٌ', 'ملحوظ', 'اسم مفعول', 'لحظ', 'ملحوظ', 'ملحظ', 'مفع. من لَحَظَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من لَحَظَ). 1.""جَلَسَ فِي مَكَانٍ مَلْحُوظٍ"" : مَنْظُورٌ إٍلَيْهِ. 2.""رَجُلٌ مَلْحُوظُ الْجَانِبِ"" : ذُو شَأْنٍ وَاعْتِبَارٍ وَقِيمَةٍ. 3.""قَدَّمَ مَلْحُوظَةً فِي الاجْتِمَاعِ"" : مُلاَحَظَةً تَتَضَمَّنُ تَعْلِيقاً أَوْ تَنْبِيهاً عَلَىكَلاَمٍ أَوْ مَقَالَةٍ أَوْ كِتَابٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5606, 'مُلَحَّنٌ', 'ملحن', 'اسم مفعول', 'لحن', 'ملحن', 'ملحن', 'مفع. من لَحَّنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلَحَّنٌ-مُلَحَّنٌ، ةٌ [ل ح ن] (مفع. من لَحَّنَ). ""نَصٌّ شِعْرِيٌّ مُلَحَّنٌ"" : أَيْ نَصٌّ رُتِّبَتْ كَلِمَاتُهُ حَسَبَ أَنْغَامٍ مُعَيَّنَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5607, 'مَلْحُونٌ', 'ملحون', 'اسم مفعول', 'لحن', 'ملحون', 'ملحن', 'مفع. من لَحَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَلْحُونٌ-مَلْحُونٌ [ل ح ن] (مفع. من لَحَنَ). 1.""نَصٌّ شِعْرِيٌّ مَلْحُونٌ"" : أَيْ نَصٌّ وُضِعَتْ لَهُ أَلْحَانٌ. 2.""أَدَبُ الْمَلْح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5608, 'مُلَخَّصٌ', 'ملخص', 'اسم مفعول', 'لخص', 'ملخص', 'ملخص', 'مفع. من لَخَّصَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من لَخَّصَ). 1.""مُلَخَّصُ الكِتَابِ"" : مُخْتَصَرُهُ، مُوجَزُهُ. ""مُلَخَّصُ الْمَقَالِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5609, 'مُلَدَّنٌ', 'ملدن', 'اسم مفعول', 'لدن', 'ملدن', 'ملدن', 'مفع. من لَدَّنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلَدِّنٌ-مُلَدِّنٌ، ةٌ [ل د ن] (فا. من لَدَّنَ). ""مَادَّةٌ مُلَدِّنَةٌ"" : مَادَّةٌ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5610, 'مَلْسُوعٌ', 'ملسوع', 'اسم مفعول', 'لسع', 'ملسوع', 'ملسع', 'مفع. من لَسَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من لَسَعَ). ""صَاحَ مَلْسُوعاً"" : أَيْ مَنْ لَسَعَتْهُ العَقْرَبُ وَنَحْوُهَا..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5611, 'مُلَسَّنٌ', 'ملسن', 'اسم مفعول', 'لسن', 'ملسن', 'ملسن', 'مفع. من لَسَّنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلَسَّنٌ-مُلَسَّنٌ، ةٌ [ل س ن] (مفع. من لَسَّنَ). 1.""شَكْلٌ مُلَسَّنٌ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5612, 'مُلَطَّفٌ', 'ملطف', 'اسم مفعول', 'لطف', 'ملطف', 'ملطف', 'مفع. من لَطَّفَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من لَطَّفَ). 1.""عِبَارَةٌ مُلَطَّفَةٌ"" : ذَاتُ لُطْفٍ. 2.""وَجَدَ غَضَبَهُ مُلَطَّفاً عَلَى ما كانَ عَلَيْهِ مِنْ قَبْلُ"" : مُخَفَّفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5613, 'مَلْعُونٌ', 'ملعون', 'اسم مفعول', 'لعن', 'ملعون', 'ملعن', 'مفع. من لَعَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَلاَعِينُ"', '', '', '', '', '', '', '', '', '"(مفع. من لَعَنَ). 1.""وَلَدٌ مَلْعُونٌ"" : مَنْعُوتٌ بِالخِزْيِ والعَارِ. 2.""هُوَ مَلْعُونٌ"" : أَيْ عَلَيْهِ لَعْنَةُ اللَّه."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5614, 'مَلاَعِينُ', 'ملاعين', 'اسم مفعول', '', 'ملاعين', 'ملعن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5615, 'مَلْغُومٌ', 'ملغوم', 'اسم مفعول', 'لغم', 'ملغوم', 'ملغم', 'مفع. من لَغَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَلْغُومٌ-مَلْغُومٌ، ةٌ [ل غ م] (مفع. من لَغَمَ). 1. ""حَقْلٌ مَلْغُومٌ"": مَلِيءٌ بِالأَلْغَامِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5616, 'مَلْفُوفٌ', 'ملفوف', 'اسم مفعول', 'لفف', 'ملفوف', 'ملفف', 'مفع. من لَفَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَلْفُوفٌ-مَلْفُوفٌ، ةٌ [ل ف ف] (مفع. من لَفَّ). 1. (نب) : الكُرُنْبُ، وهُوَ بَقْلَةٌ زِرَاعِيَّةٌ أَوْرَاقُهَا خَضْرَاءُ، مَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5617, 'مَلْفُوظٌ', 'ملفوظ', 'اسم مفعول', 'لفظ', 'ملفوظ', 'ملفظ', 'مفع. من لَفَظَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من لَفَظَ). 1.""حَرْفٌ مَلْفُوظٌ"" : مَنْطُوقٌ، أَيْ يُنْطَقُ بِهِ. 2.""مَلْفُوظٌ مِنَ العَمَلِ"" : مَطْرُودٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5618, 'مُلَفَّقٌ', 'ملفق', 'اسم مفعول', 'لفق', 'ملفق', 'ملفق', 'مفع. من لَفَّقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلَفَّقٌ-مُلَفَّقٌ، ةٌ [ل ف ق] (مفع. من لَفَّقَ). 1.""خَبَرٌ مُلَفَّقٌ"": خَبَرٌ لُفِّقَ، مُمَوَّهٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5619, 'مُلَقَّنٌ', 'ملقن', 'اسم مفعول', 'لقن', 'ملقن', 'ملقن', 'مفع. من لَقَّنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏"', '', '', '', '', '', '', '', '', '"مُلَقَّنٌ، ةٌ - [ل ق ن]. (مفع. من لَقَّنَ). ""دَرْسٌ مُلَقَّنٌ"" : دَرْسٌ تَمَّ تَلْقِينُهُ، أَيْ تَحْفِيظُهُ بِالتَّكْرَارِ والإِعَادَةِ.    ""كَلاَمٌ مُلَقَّنٌ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5620, 'مُلَقّىً', 'ملقى', 'اسم مفعول', 'لقي', 'ملقى', 'ملق', 'مفع. من لَقَّى', '', '', 'مفرد', 'Dy', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"مُلَقّىً-مُلَقّىً [ل ق ي] (مفع. من لَقَّى). ""رَجُلٌ مُلَقّىً"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5621, 'مُلَقّاة', 'ملقاة', 'اسم مفعول', '', 'ملقاة', 'ملقة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلَقّىً-مُلَقّىً [ل ق ي] (مفع. من لَقَّى). ""رَجُلٌ مُلَقّىً"" "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5622, 'مَلْمُومٌ', 'ملموم', 'اسم مفعول', 'لمم', 'ملموم', 'ملمم', 'مفع. من لَمَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَلْمُومٌ-مَلْمُومٌ، ةٌ [ل م م] (مفع. من لَمَّ). 1.""أَثَاثٌ مَلْمُومٌ"" : مَجْمُوعٌ، مُسْتَدِيرٌ. 2.""كُتُبٌ مَلْمُومَةٌ"" : مَضْمُومٌ بَعْضُهَا إِلَى بَعْضٍ. 3.""صَخْرَةٌ مَلْمُومَةٌ"" : مُسْتَدِيرَةٌ صَلْبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5623, 'مَلْمُوسٌ', 'ملموس', 'اسم مفعول', 'لمس', 'ملموس', 'ملمس', 'مفع. من لَمَسَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏"', '', '', '', '', '', '', '', '', '"(مفع. من لَمَسَ). 1.""وَاقِعٌ مَلْمُوسٌ"" : مَحْسُوسٌ، أَيْ مُدْرَكٌ بِالْحَوَاسِ. ""وَقَائِعُ مَلْمُوسَةٌ وأُخْرَى مُجَرَّدَةٌ"". 2.""الْمَلْمُوسَاتُ"" : مُدْرَكَاتُ القُوَّةِ اللاَّمِسَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5624, 'مُلَمَّعٌ', 'ملمع', 'اسم مفعول', 'لمع', 'ملمع', 'ملمع', 'مفع. من لَمَّعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من لَمَّعَ). 1.""حِذَاءٌ مُلَمَّعٌ"" : مَمْسُوحٌ جَيِّداً بِدِهانِ الأَحْذِيَةِ. 2.""قُمَاشٌ مُلَمَّعٌ"" : فِيهِ بُقَعٌ تُخَالِفُ سَائِرَ لَوْنِهِ. 3.""رَجُلٌ مُلَمَّـعٌ"" : فِي جَسَدِهِ بُقَعٌ تُخَالِفُ سَائِرَ لَوْنِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5625, 'مُلَمْلَمٌ', 'ململم', 'اسم مفعول', 'لملم', 'ململم', 'ململم', 'مفع. من لَمْلَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلَمْلَمٌ-مُلَمْلَمٌ، ةٌ [ل م ل م] (مفع. من لَمْلَمَ). 1.""تِبْنٌ مُلَمْلَمٌ فِي الْحَقْلِ"" : مُجَمَّعٌ فِي مَوْضِعٍ. ""حَشَائِشُ مُلَمْلَمَةٌ"". 2.""وَجَدَ جَمْعَهُمْ مُلَمْلَماً"" : مُجَمَّعاً ومُتَشَابِكاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5626, 'مَلْهُوفٌ', 'ملهوف', 'اسم مفعول', 'لهف', 'ملهوف', 'ملهف', 'مفع. من لَهِفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من لَهِفَ). 1.""عَاشِقٌ مَلْهُوفُ القَلْبِ"" : مُحْتَرِقُ القَلْبِ. 2.""رَجُلٌ مَلْهُوفٌ"" : حَزِينٌ مَفْجُوعٌ، إِمَّا لِذَهَابِ مَالِهِ أَو فُقْدَانِ عَزِيزٍ عَلَيْهِ وهُوَ يُنَادِي ويَسْتَغِيثُ. 3.""مَلْهُوفٌ عَلَى تَكْدِيسِ الْمَالِ وخَزْنِ الذَّهَبِ"" : السَّاعِي إِلَى ذَلِكَ بِنَهَمٍ وشَغَفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5627, 'مُلَوَّثٌ', 'ملوث', 'اسم مفعول', 'لوث', 'ملوث', 'ملث', 'مفع. من لَوَّثَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من لَوَّثَ). 1.""ثَوْبٌ مُلَوَّثٌ"" : مُلَطَّخٌ بِنَجَاسَةٍ أو مَا شَابَهَ ذَلِكَ. ""ثَوْبٌ مُلَوَّثٌ بِالطِّينِ"" ""ثَوْبٌ مُلَوَّثٌ بِالدَّمِ"". 2.""رَجُلٌ مُلَوَّثُ السُّمْعَةِ"" : سَيِّءُ السُّمْعَةِ. 3.""هَوَاءُ الْمُدُنِ الصِّنَاعِيَّةِ مُلَوَّثٌ"" : مُتَعَفِّنٌ بِمَوَادِّ الْمَحْرُوقَاتِ والغَازَاتِ الْمُضِرَّةِ. ""صَارَتْ مِيَاهُ النَّهْرِ مُلَوَّثَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5628, 'مُلَوَّزٌ', 'ملوز', 'اسم مفعول', 'لوز', 'ملوز', 'ملز', 'مفع. من لَوَّزَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلَوَّزٌ-مُلَوَّزٌ، ةٌ [ل و ز] (مفع. من لَوَّزَ). ""تَمْرٌ مُلَوَّزٌ"" : التَّمْرُ الْمَحْشُوُّ بِاللَّوْزِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5629, 'مُلَوْلَبٌ', 'ملولب', 'اسم مفعول', 'لولب', 'ملولب', 'مللب', 'مفع. من لَوْلَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلَوْلَبٌ-مُلَوْلَبٌ [ل و ل ب] (مفع. من لَوْلَبَ). 1.""شَكْلُهُ شَكْلٌ مُلَوْلَبٌ"" : أَيْ عَلَى شَكْلِ لَوْلَبٍ. 2.""الْمُلَوْلَبُ"" : المِرْوَدُ وَنَحْوُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5630, 'مُلَوَّنٌ', 'ملون', 'اسم مفعول', 'لون', 'ملون', 'ملن', 'مفع. من لَوَّنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏"', '', '', '', '', '', '', '', '', '"(مفع. من لَوَّنَ). 1.""تِلْفَازٌ مُلَوَّنٌ"" : يُقَدِّمُ الصُّوَرَ بِأَلْوَانٍ مُخْتَلِفَةٍ"". ""صُوَرٌ مُلَوَّنَةٌ"". 2.""رَجُلٌ مُلَوَّنٌ"" : مَنْ كَانَ نَسْلُهُ مُخْتَلِطاً مِنْ غَيْرِ البِيضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5631, 'مُلَيَّنٌ', 'ملين', 'اسم مفعول', 'لين', 'ملين', 'ملن', 'مفع. من لَيَّنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من لَيَّنَ). 1.""جِلْدٌ مُلَيَّنٌ"" : مُرَطَّبٌ. 2.""بَطْنٌ مُلَيَّنٌ"" : بِهِ إِسْهَالٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5632, 'مُمَارَسٌ', 'ممارس', 'اسم مفعول', 'مرس', 'ممارس', 'ممرس', 'مفع. من مَارَسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَارَسٌ-مُمَارَسٌ، ةٌ [م ر س] (مفع. من مَارَسَ). ""عَمَلٌ مُمَارَسٌ"" : مُمَرَّنٌ عَلَيْهِ، مُدَرَّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5633, 'مَمْحُوٌّ', 'ممحو', 'اسم مفعول', 'محو', 'ممحو', 'ممح', 'مفع. من مَحَا', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَمْحُوٌّ-مَمْحُوٌّ [م ح و] (مفع. من مَحَا). ""خَطٌّ مَمْحُوٌّ"" : أُزِيلَ أَثَرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5634, 'مَمْخُوضٌ', 'ممخوض', 'اسم مفعول', 'مخض', 'ممخوض', 'ممخض', 'مفع. من مَخَضَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَمْخُوضٌ-مَمْخُوضٌ [م خ ض] (مفع. من مَخَضَ). ""لَبَنٌ مَمْخٌوضٌ"" : لَبَنٌ اسْتُخْرِجَ مِنْهُ زُبْدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5635, 'مُمَدَّدٌ', 'ممدد', 'اسم مفعول', 'مدد', 'ممدد', 'ممد', 'مفع. من مَدَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏"', '', '', '', '', '', '', '', '', '"(مفع. من مَدَّ). ""مُمَدَّدٌ عَلَى سَرِيرِهِ"" : مُسْتَلْقٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5636, 'مَمْدُودٌ', 'ممدود', 'اسم مفعول', 'مدد', 'ممدود', 'ممدد', 'مفع. من مَدَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من مَدَّ). 1.""نَظَرٌ مَمْدُودٌ"" : مُمْتَدٌ، مَبْسُوطٌ. 2.""مَمْدُودٌ عَلَى سَرِيرِهِ"" : مُسْتَلْقٍ. 3.""يَدٌ مَمْدُودَةٌ لِلتَّعَاوُنِ"" : يَدٌ مَفْتُوحَةٌ. 4.""لَهُ مَالٌ مَمْدُودٌ"" : لَهُ مَالٌ كَثِيرٌ.المدثر آية 12 وَجَعَلْتُ لَهُ مَالاً مَمْدُودا (قرآن). 5.""اِسْمٌ مَمْدُودٌ"" : كُلُّ اسْمٍ آخِرُهُ هَمْزَةٌ قَبْلَهَا أَلِفٌ زَائِدَةٌ مِثْل : سَمْرَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5637, 'مَمْدوحٌ', 'ممدوح', 'اسم مفعول', 'مدح', 'ممدوح', 'ممدح', 'مفع. من مَدَحَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏"', '', '', 'ـو', '', '', '', '', '', '"مَمْدوحٌ-مَمْدوحٌ، ةٌ [م د ح] (مفع. من مَدَحَ). ""قائِدٌ مَمْـدوحٌ"" : مُثْنىً عَلَيْهِ بِما لَهُ مِنَ الصِّفاتِ الْحَميدَةِ. ""هَذا الوَلَدُ مَمْدوحُ السُّلوكِ والأَخْلاقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5638, 'مُمَدَّنٌ', 'ممدن', 'اسم مفعول', 'مدن', 'ممدن', 'ممدن', 'مفع. من مَدَّنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏"', '', '', '', '', '', '', '', '', '"مُمَدَّنٌ-مُمَدَّنٌ [م د ن] (مفع. من مَدَّنَ). ""شَعْبٌ مُمَدَّنٌ"" : أَيْ صَارَ مُتَحَضِّراً، مُتَمَدِّناً، يَعِيشُ فِي حَضَارَةٍ. ""شُعُوبٌ مُمَدَّنَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5639, 'مُمَرَّنٌ', 'ممرن', 'اسم مفعول', 'مرن', 'ممرن', 'ممرن', 'مفع. من مَرَّنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من مَرَّنَ) ""مُمَرَّنٌ عَلَى رُكُوبِ الْخَيْلِ"" : مُدَرَّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5640, 'مَمْزُوجٌ', 'ممزوج', 'اسم مفعول', 'مزج', 'ممزوج', 'ممزج', 'مفع. من مَزَجَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَمْزُوجٌ-مَمْزُوجٌ، ةٌ [م ز ج] (مفع. من مَزَجَ). ""حَلِيبٌ مَمْزُوجٌ بِالْمَاءِ"" : مَخْلُوطٌ بِـ... ""وَشَرِبَ الْمَاءَ الْمَمْزُوجَ بِالذُّلِّ والعَيْبِ"". (جبران خ. جبران) ""كَانَ حَدِيثُهُ مَمْزُوجاً بِالحِكَمِ والأَمْثَالِ"" ""بَاتَ يُكِنُّ لَهُ عَاطِفَةً مَمْزُوجَةً بِالاحْتِقَارِ والبُغْضِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5641, 'مَمْسُوخٌ', 'ممسوخ', 'اسم مفعول', 'مسخ', 'ممسوخ', 'ممسخ', 'مفع. من مَسَخَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏"', '', '', '', '', '', '', '', '', '"مَمْسُوخٌ-مَمْسُوخٌ [م س خ] (مفع. من مَسَخَ). 1.""وَجْهٌ مَمْسُوخٌ"" : مَنْ تَغَيَّرَتْ مَلاَمِحُ وَجْهِهِ واتَّخَذَتْ شَكْلاً مُخَالِفاً لأَصْلِهَا. 2.""فَرَسٌ مَمْسُوخٌ"" : قَلِيلُ لَحْمِ العَجُزِ أَوِ الرِّدْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5642, 'مُمَسَّكٌ', 'ممسك', 'اسم مفعول', 'مسك', 'ممسك', 'ممسك', 'مفع. من مَسَّكَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏"', '', '', '', '', '', '', '', '', '"مُمَسَّكٌ-مُمَسَّكٌ، ةٌ [م س ك] (مفع. من مَسَّكَ). ""مَادَّةٌ مُمَسَّكَةٌ"" : مَادَّةٌ مَطْلِيَّةٌ بِالْمِسْكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5643, 'مَمْشُوطٌ', 'ممشوط', 'اسم مفعول', 'مشط', 'ممشوط', 'ممشط', 'مفع. من مَشَطَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من مَشَطَ). 1.""صُوفٌ مَمْشُوطٌ"" : مُسَرَّحٌ، أَيْ مُشِطَ بِالمِشْطِ. 2.""رَجُلٌ مَمْشُوطُ القَامَةِ"" : نَحِيفٌ وطَوِيلُ القَامَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5644, 'مَمْشُوقٌ', 'ممشوق', 'اسم مفعول', 'مشق', 'ممشوق', 'ممشق', 'مفع. من مَشَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"(مفع. من مَشَقَ). 1.""شَابٌّ مَمْشُوقُ القَدِّ"" : طَوِيلُ القَدِّ مَعَ تَنَاسُبٍ فِي الأَعْضَاءِ. ""مَمْشُوقَةُ القِوَامِ لاَ أَجْمَلَ مِنْهَا"". 2.""جَوَادٌ مَمْشُوقٌ"" : الدَّقِيقُ والقَلِيلُ اللَّحْمِ. 3.""غُصْنٌ مَمْشُوقٌ"" : لَيِّنٌ وَطَوِيل."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5645, 'مُمَغْنَطٌ', 'ممغنط', 'اسم مفعول', 'مغنط', 'ممغنط', 'ممغنط', 'مفع. من مَغْنَطَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَغْنِطٌ-مُمَغْنِطٌ، ةٌ [م غ ن ط] (فا. من مَغْنَطَ). ""مَادَّةٌ مُمَغْنَطَةٌ"" : مَادَّةٌ تُفْرِزُ وَتُنْتِجُ الْمِغْنَاطِيسَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5646, 'مَمْقُوتٌ', 'ممقوت', 'اسم مفعول', 'مقت', 'ممقوت', 'ممقت', 'مفع. من مَقَتَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من مَقَتَ). ""رَجُلٌ مَمْقُوتٌ"" : مَبْغُوضٌ، مَكْرُوهٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5647, 'مَمْلُوءٌ', 'مملوء', 'اسم مفعول', 'ملأ', 'مملوء', 'ممل', 'مفع. من مَلأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من مَلأَ). 1.""كَأْسٌ مَمْلُوءٌ بِالْمَاءِ"" : كَأْسٌ وُضِعَ فِيهِ مِنَ الْمَاءِ قَدْرُ مَا يَسْتَوْعِبُ. ""بَطْنٌ مَمْلُوءٌ"" ""شُبِّهَتِ البِئْرُ بِالدُّنْيَا الْمَمْلُوءةِ آفَاتٍ وسُرُوراً أو مَخَاوِفَ ومَتَالِفَ"". (ابن المقفع). 2.""كَانَ شَّابّاً مَرِحاً ذَكِيّاً مَمْلُوءا بِالْحَيَاةِ"" : مُشْبَعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5648, 'مَمْلُوءَةٌ', 'مملوءة', 'اسم مفعول', '', 'مملوءة', 'مملة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من مَلأَ). 1.""كَأْسٌ مَمْلُوءٌ بِالْمَاءِ"" : كَأْسٌ وُضِعَ فِيهِ مِنَ الْمَاءِ قَدْرُ مَا يَسْتَوْعِبُ. ""بَطْنٌ مَمْلُوءٌ"" ""شُبِّهَتِ البِئْرُ بِالدُّنْيَا الْمَمْلُوءةِ آفَاتٍ وسُرُوراً أو مَخَاوِفَ ومَتَالِفَ"". (ابن المقفع). 2.""كَانَ شَّابّاً مَرِحاً ذَكِيّاً مَمْلُوءا بِالْحَيَاةِ"" : مُشْبَعاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5649, 'مُمَلَّحٌ', 'مملح', 'اسم مفعول', 'ملح', 'مملح', 'مملح', 'مفع. من مَلَّحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَلَّحٌ-مُمَلَّحٌ، ةٌ [م ل ح] (مفع. من مَلَّحَ). ""طَعَامٌ مُمَلَّحٌ"" : فِيهِ مِلْحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5650, 'مَمْلُوكٌ', 'مملوك', 'اسم مفعول', 'ملك', 'مملوك', 'مملك', 'مفع. من مَلَكَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَمَالِيكُ"', '', '', '', '', '', '', '', '', '"(مفع. من مَلَكَ). ""مَمْلُوكُ سَيِّدِهِ"" : عَبْدُهُ. ""الإِنْسَانُ حُرٌّ لاَ مَمْلُوكٌ"" ""يَجْعَلُهُ مَالِكاً بَعْدَ أَنْ كَانَ مَمْلُوكاً"". (م. ص. الرافعي) ""الإِنْسَانُ الْحُرُّ مَالِكٌ لِنَفْسِهِ تَمَاماً ومَمْلُوكٌ لِقَوْمِهِ تَمَاماً"". (ع. الكواكبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5651, 'مَمَالِيكُ', 'مماليك', 'اسم مفعول', '', 'مماليك', 'مملك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5652, 'مَمْنُونٌ', 'ممنون', 'اسم مفعول', 'منن', 'ممنون', 'ممنن', 'مفع. من مَنَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من مَنَّ). 1. ""أَنَا مَمْنُونٌ لَكَ ياسَيِّدِي بِجَمِيلِكَ"" : أَنَا مُعْتَرِفٌ بِجَمِيلِكَ وشَاكِرٌ لِفَضْلِكَ. 2.""عَمَلٌ مَمْنونٌ"" : مَقْطُوعٌ.التين آية 6 فَلَهُمُ أَجْرٌ غَيْرُ مَمْنُونٍ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5653, 'مَمْنُوحٌ', 'ممنوح', 'اسم مفعول', 'منح', 'ممنوح', 'ممنح', 'مفع. من مَنَحَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من مَنَحَ). 1.""كَانَ الْمَمْنُوحَ الوَحِيدَ لِلْجَائِزَةِ"" : أَي الَّذِي مُنِحَ، أُعْطِيَ الْجَائِزَةَ. 2.""طَالِبٌ مَمْنُوحٌ"" : الْمُتَمَتِّعُ بِمِنْحَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5654, 'مَمْنُوعٌ', 'ممنوع', 'اسم مفعول', 'منع', 'ممنوع', 'ممنع', 'مفع. من مَنَعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من مَنَعَ). 1.""مَمْنُوعٌ مِنَ الكَلاَمِ"" : مَحْرُومٌ ...، غَيْرُ مَسْمُوحٍ لَهُ بِالكَلاَمِ. 2.""الْمُرُورُ مَمْنُوعٌ مِنْ هُنَا"" : الْمُرُورُ مِنْ هُنَا غَيْرُ مَسْمُوحٍ بِهِ. ""التَّدْخِينُ مَمْنُوعٌ فِي القَاعَةِ"". 3.""أَكْلُ لَحْمِ الخِنْزِيرِ وشُرْبُ الْخَمْرِ ولَعِبُ الْمَيْسِرِ مِنَ الْمَمْنُوعَاتِ فِي العَقِيدَةِ الإِسْلاَمِيَّةِ"" : مِنَ الْمَحْظُورَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5655, 'مُمَهَّدٌ', 'ممهد', 'اسم مفعول', 'مهد', 'ممهد', 'ممهد', 'مفع. من مَهَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَهَّدٌ-مُمَهَّدٌ، ةٌ [م هـ د] (مفع. من مَهَّدَ). 1.""فِرَاشٌ مُمَهَّدٌ"" : مَبْسُوطٌ. 2.""مَاءٌ مُمَهَّدٌ"" : مَاءٌ دَافِئٌ. 3.""طَرِيقٌ مُمَهَّدَةٌ"" : مُهَيَّأَةٌ مُسَوَّاةٌ. ""تُرَابٌ نَاعِمٌ مُمَهَّدٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5656, 'مُمَوَّنٌ', 'ممون', 'اسم مفعول', 'مون', 'ممون', 'ممن', 'مفع. من مَوَّنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏"', '', '', '', '', '', '', '', '', '"مُمَوَّنٌ-مُمَوَّنٌ، ةٌ [م و ن] (مفع. من مَوَّنَ). ""مَخْزَنٌ مُمَوَّنٌ مِنَ الشَّرِكَةِ الوَطَنِيَّةِ"" : مُزَوَّدٌ بِحَاجاتِهِ مِنَ الْمُؤَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5657, 'مُمَوَّهٌ', 'مموه', 'اسم مفعول', 'موه', 'مموه', 'ممه', 'مفع. من مَوَّهَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَوَّهٌ-مُمَوَّهٌ، ةٌ [م و هـ] (مفع. من مَوَّهَ). 1.""مَعْدِنٌ مُمَوَّهٌ بِالذَّهَبِ"" : مَعْدِنٌ مَطْلِيٌّ بِمَاءِ الذَّهَبِ ولَيْسَ بِذَهَبٍ. 2.""حَقٌّ مُمَوَّهٌ"" : أَيْ أُلْبِسَ بِالبَاطِلِ. 3.""خَبَرٌ مُمَوَّهٌ"" : خَبَرٌ عَلَى غَيْرِ حَقِيقَتِهِ. ""حَقَائِقُ مُمَوَّهَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5658, 'مُمَيَّزٌ', 'مميز', 'اسم مفعول', 'ميز', 'مميز', 'ممز', 'مفع. من مَيَّزَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏"', '', '', '', '', '', '', '', '', '"مُمَيَّزٌ-مُمَيَّزٌ، ةٌ [م ي ز] (مفع. من مَيَّزَ). 1.""عَمَلٌ مُمَيَّزٌ"" : ذُو امْتِيَازٍ، مُفَضَّلٌ. 2.""عَدَدٌ مُمَيَّزٌ"" : مَادِّيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5659, 'مُنَازَعٌ', 'منازع', 'اسم مفعول', 'نزع', 'منازع', 'منزع', 'مفع. من نَازَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَازَعٌ-مُنَازَعٌ [ن ز ع] (مفع. من نَازَعَ). ""أَمْرٌ مُنَازَعٌ فِيهِ"" : حَوْلَهُ نِزَاعُ وخِصَامٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5660, 'مَنُوطٌ', 'منوط', 'اسم مفعول', 'نوط', 'منوط', 'منط', 'مفع. من نَاطَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنُوطٌ-مَنُوطٌ [ن و ط] (مفع. من نَاطَ). 1.""بَعِيرٌ مَنُوطٌ"" : مُصَابٌ بِوَرَمِ الصَّدْرِ أو النَّحْرِ. 2.""إِنْجَازُ الْمَشْرُوعِ مَنُوطٌ بِهِ"": مُعَلَّقٌ بِهِ، مُرْتَبِطٌ بِهِ. 3.""هُوَ مَنُوطٌ بِالقَوْمِ"" : دَخِيلٌ فِيهِمْ أو دَعِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5661, 'مَنْبُوذٌ', 'منبوذ', 'اسم مفعول', 'نبذ', 'منبوذ', 'منبذ', 'مفع. من نَبَذَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '"ون:ات"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من نَبَذَ). 1.""وَلَدٌ مَنْبُوذٌ"" : وَلَدٌ الزِّنَا الَّذِي تُلْقِيهِ أُمُّهُ عَلَى قَارِعَةِ الطَّرِيقِ غَيْرَ رَاغِبَةٍ فِيهِ تَجَنُّباً لِلْفَضِيحَةِ. 2.""مَنْبُوذٌ مِنَ الْجَمَاعَةِ"": مَرْفُوضٌ، مُسْتَبْعَدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5662, 'مُنَتَّنٌ', 'منتن', 'اسم مفعول', 'نتن', 'منتن', 'منتن', 'مفع. من نَتَّنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَتَّنٌ-مُنَتَّنٌ، ةٌ [ن ت ن] (مفع. من نَتَّنَ). ""طَعَامٌ مُنَتَّنٌ"" : مُتَعَفِّنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5663, 'مُنَجَّدٌ', 'منجد', 'اسم مفعول', 'نجد', 'منجد', 'منجد', 'مفع. من نَجَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَجَّدٌ-مُنَجَّدٌ، ةٌ [ن ج د] (مفع. من نَجَّدَ). ""بَيْتٌ مُنَجَّدٌ"" : مُزَيَّنٌ بِسُتُورٍ وفُرُشٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5664, 'مَنْحُوتٌ', 'منحوت', 'اسم مفعول', 'نحت', 'منحوت', 'منحت', 'مفع. من نَحَتَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من نَحَتَ). ""تِمْثَالُ مَنْحُوتٌ"" : تَمَّ نَحْتُهُ وتَسْوِيَتُهُ واقْتِطَاعُهُ بِيَدِ النَّحَّاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5665, 'مَنْحُوسٌ', 'منحوس', 'اسم مفعول', 'نحس', 'منحوس', 'منحس', 'مفع. من نَحَسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من نَحَسَ). ""رَجُلٌ مَنْحُوسُ الطَّالِعِ"" : سَيِّئُ الطَّالِعِ، أَصَابَهُ النَّحْسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5666, 'مناحيس', 'مناحيس', 'اسم مفعول', '', 'مناحيس', 'منحس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5667, 'مَنْزُوعٌ', 'منزوع', 'اسم مفعول', 'نزع', 'منزوع', 'منزع', 'مفع. من نَزَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"(مفع. من نَزَعَ). 1.""جِذْعٌ مَنْزُوعٌ مِنْ جِذْرِهِ"" : مَقْلُوعٌ. 2.""اِتَّفَقُوا عَلَى أَنْ يُصْبِحَ البَلَدُ مَنْزُوعَ السِّلاَحِ"" : خَالِياً بِالْمَرَّةِ مِنْ كُلِّ سِلاَحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5668, 'مَنْزُوفٌ', 'منزوف', 'اسم مفعول', 'نزف', 'منزوف', 'منزف', 'مفع. من نَزَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏"', '', '', '', '', '', '', '', '', '"مَنْزُوفٌ-مَنْزُوفٌ، ةٌ [ن ز ف] (مفع. من نَزَفَ). 1.""جِسْمٌ مَنْزُوفٌ"" : جِسْمٌ سَالَ دَمُهُ كَثِيراً. 2.""بِئْرٌ مَنْزُوفَةٌ"" : اُسْتُخْرِجَ مَاؤُهَا إِلَى أَنْ نَفَدَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5669, 'مُنَزَّهٌ', 'منزه', 'اسم مفعول', 'نزه', 'منزه', 'منزه', 'مفع. من نَزَّهَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏"', '', '', '', '', '', '', '', '', '"(مفع. من نَزَّهَ). ""هُوَ مُنَزَّهٌ عَنْ كُلِّ خَطَإٍ"" : مَعْصُومٌ، بَعِيدٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5670, 'مَنْسُوبٌ', 'منسوب', 'اسم مفعول', 'نسب', 'منسوب', 'منسب', 'مفع. من نَسَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏:مناسيبُ"', '', '', 'ـو', '', '', '', '', '', '"مَنْسُوبٌ-مَنْسُوبٌ [ن س ب] (مفع. من نَسَبَ). 1.""مَكِّيٌّ، أَيْ مَنْسُوبٌ إِلَى مَكَّةَ"" : أَيْ أَصْلُهُ مُرْتَبِطٌ بِمَكَّةَ. 2.""شِعْرٌ مَنْسُوبٌ إِلَى حَمّادٍ"" : أَيْ يُنْسَبُ إِلَيْهِ. 3.""مَنْسُوبُ البَحْرِ"" : مُسْتَوَاهُ، مُعَدَّلُهُ. ""اِرْتَفَعَتِ الْمِيَاهُ فَوْقَ مَنْسُوبِهَا"". 4.""رَجُلٌ مَنْسُوبٌ"": صَرِيحُ النَّسَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5671, 'مَنَاسِيبُ', 'مناسيب', 'اسم مفعول', '', 'مناسيب', 'منسب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5672, 'مَنْسُوجٌ', 'منسوج', 'اسم مفعول', 'نسج', 'منسوج', 'منسج', 'مفع. من نَسَجَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من نَسَجَ). 1.""ثَوْبٌ مَنْسُوجٌ مِنَ الْحَرِيرِ"" : أَيْ نُسِجَ بِالْحَرِيرِ. 2.""مَنْسُوجَاتٌ قُطْنِيَّةٌ"" : أَثْوَابٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5673, 'مَنْسُوخٌ', 'منسوخ', 'اسم مفعول', 'نسخ', 'منسوخ', 'منسخ', 'مفع. من نَسَخَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":‏"', '', '', '', '', '', '', '', '', '"مَنْسُوخٌ-مَنْسُوخٌ، ةٌ [ن س خ] (مفع. من نَسَخَ). ""كَلاَمٌ مَنْسُوخٌ"" : مُلْغىً، لاَغٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5674, 'مُنَسَّقٌ', 'منسق', 'اسم مفعول', 'نسق', 'منسق', 'منسق', 'مفع. من نَسَّقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَسَّقٌ-مُنَسَّقٌ، ةٌ [ن س ق] (مفع. من نَسَّقَ). ""عَمَلٌ مُنَسَّقٌ"": أَيْ مُنَظَّمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5675, 'مَنْسُوقٌ', 'منسوق', 'اسم مفعول', 'نسق', 'منسوق', 'منسق', 'مفع. من نَسَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْسُوقٌ-مَنْسُوقٌ، ةٌ [ن س ق] (مفع. من نَسَقَ). ""أَلْوَانٌ مَنْسُوقَةٌ"" : مُتَنَاسِقَةٌ، مُنْسَجِمَةٌ. ""إِنَّ تَمَاثِيلَ الزَّهْرَةِ لَيْسَتْ عَلَى نَحَافَةٍ وَدِقَّةٍ فِي الْخُصُورِ وَالأَطْرَافِ وَلَكِنَّهَا مِثَالُ الْجِسْمِ الْمَتِينِ الْمَنْسُوقِ"". (ع. م. العقاد)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5676, 'مَنْسِيٌّ', 'منسي', 'اسم مفعول', 'نسي', 'منسي', 'منس', 'مفع. من نَسِيَ', '', 'ة', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَنْسِيٌّ-مَنْسِيٌّ، ةٌ [ن س ي] (مفع. من نَسِيَ). ""كِتَابٌ مَنْسِيٌّ"" : كِتَابٌ نُسِيَ ذِكْرُهُ، أَيْ لَمْ يَعُدْ يُذْكَرُ.مريم آية 23 وَكُنْتُ نَسْياً مَنْسِيّاً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5677, 'مَنْشُودٌ', 'منشود', 'اسم مفعول', 'نشد', 'منشود', 'منشد', 'مفع. من نَشَدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْشُودٌ-مَنْشُودٌ، ةٌ [ن ش د] (مفع. من نَشَدَ). ""الْهَدَفُ الْمَنْشُودُ"" : الْهَدَفُ الْمَطْلُوبُ تَحْقِيقُهُ بِرَغْبَةٍ مُلِحَّةٍ. ""سَعَادَةٌ مَنْشُودَةٌ"" l ""الآمَالُ الْمَنْشُودَةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5678, 'مَنْشُورٌ', 'منشور', 'اسم مفعول', 'نشر', 'منشور', 'منشر', 'مفع. من نَشَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مناشيرُ"', '', '', '', '', '', '', '', '', '"مَنْشُورٌ-مَنْشُورٌ [ن ش ر] (مفع. من نَشَرَ). 1.""خَشَبٌ مَنْشُورٌ"" : تَمَّ نَشْرُهُ بِالْمِنْشَارِ. 2.""خَبَرٌ مَنْشُورٌ"" : مُذَاعٌ، شَائِعٌ. ""تَسَاءلَ كَيْفَ أَصْبَحَ العِلْمُ مَسْتُورًا وَالْجَهْلُ مَنْشُوراً"". (ابن المقفع). 3.""وَزَّعَ مَنْشُوراً بِالْمَدِينَةِ"" : بَيَاناً يَتَضَمَّنُ شَرْحاً لِمَوْقِفٍ مَّا، وَغَالِباً مَا يَتَعَلَّقُ بِقَضِيَّةٍ سِيَاسِيَّةٍ أَوْ نَقَابِيَّةٍ. 4.""مَنْشُورٌ إِدَارِيٌّ"" : تَعْمِيمٌ حَوْلَ مَوْضُوعٍ مَّا. 5.""كِتَابٌ مَنْشُورٌ سَنَةَ 1970"" : أَيْ إِصْدَارُهُ، نَشْرُهُ .... 6.""مَنْشُورَاتٌ أَدَبِيَّةٌ ثَقَافِيَّةٌ"" : كِتَابَاتٌ مَطْبُوعَةٌ لِلْقِرَاءةِ. 7.""مَنْشُورٌ خُمَاسِيٌّ"" (هن) : جِسْمٌ كَثِيرُ السُّطُوحِ مُتَوَازِي الأَضْلاَعِ قَاعِدَتَاهُ مُضَلَّعَانِ مُتَوَازِيَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5679, 'مَنَاشِيرُ', 'مناشير', 'اسم مفعول', '', 'مناشير', 'منشر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5680, 'مُنَشَّطٌ', 'منشط', 'اسم مفعول', 'نشط', 'منشط', 'منشط', 'مفع. من نَشَّطَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُنَشَّطٌ-مُنَشَّطٌ، ةٌ [ن ش ط] (مفع. من نَشَّطَ). 1.""حَفْلٌ مُنَشَّطٌ"" : جُعِلَ فِيهِ نَشَاطٌ وَحَيَوِيَّةٌ وَحَرَكَةٌ. 2.""فَحْمٌ مُنَشَّطٌ"" : مُسَعَّرٌ، مُذَكىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5681, 'مَنْصُوصٌ', 'منصوص', 'اسم مفعول', 'نصص', 'منصوص', 'منصص', 'مفع. من نَصَّ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْصُوصٌ-مَنْصُوصٌ، ةٌ [ن ص ص] (مفع. من نَصَّ). 1.""حُكْمٌ مَنْصُوصٌ عَلَيْهِ فِي القَانُونِ"" : مَا نَصَّ عَلَيْهِ القَانُونُ وَحَدَّدَهُ. 2.""مِيعَادٌ مَنْصُوصٌ عَلَيْهِ"" : مُنْتَظَرٌ وَمُحَدَّدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5682, 'مَنْصُوبٌ', 'منصوب', 'اسم مفعول', 'نصب', 'منصوب', 'منصب', 'مفع. من نَصَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْصُوبٌ-مَنْصُوبٌ، ةٌ [ن ص ب] (مفع. من نَصَبَ). 1.""تِمْثَالٌ مَنْصُوبٌ"" : قَائِمٌ، مُنْتَصِبٌ. ""خَيْمَةٌ مَنْصُوبَةٌ"". 2.""اِسْمٌ مَنْصُوبٌ"" : اِسْمٌ دَخَلَ عَلَيْهِ النَّصْبُ، أَيْ آخِرُهُ يَحْمِلُ فَتْحَةً(ـَ). 3.""فِعْلٌ مَنْصُوبٌ"" : أَيْ دَخَلَ عَلَيْهِ النَّصْبُ: ""لَنْ تُسَافِرَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5683, 'مُنَضَّدٌ', 'منضد', 'اسم مفعول', 'نضد', 'منضد', 'منضد', 'مفع. من نَضَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَضَّدٌ-مُنَضَّدٌ، ةٌ [ن ض د] (مفع. من نَضَّدَ). 1.""أَثَاثٌ مُنَضَّدٌ"" : مُنَسَّقٌ، مُرَتَّبٌ. 2.""كُتُبٌ مُنَضَّدَةٌ"": مُرَصَّفَةٌ. 3.""أَسْنَانٌ مُنَضَّدَةٌ"" : مُصَفَّفَةٌ. ""أَحْرُفٌ طِبَاعِيَّةٌ مُنَضَّدَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5684, 'مَنْضُودٌ', 'منضود', 'اسم مفعول', 'نضد', 'منضود', 'منضد', 'مفع. من نَضَدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْضُودٌ-مَنْضُودٌ، ةٌ [ن ض د] (مفع. من نَضَدَ). ""لُؤْلُؤٌ مَنْضُودٌ"" : مَضْمُومٌ بَعْضُهُ إِلَى بَعْضٍ بِاتِّسَاقٍ. ""تَبْدُو جَمِيلَةً وَتَبْتَسِمُ مِثْلَ اللُّؤْلُؤِ الْمَنْضُودِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5685, 'مَنْطُوقٌ', 'منطوق', 'اسم مفعول', 'نطق', 'منطوق', 'منطق', 'مفع. من نَطَقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْطُوقٌ-مَنْطُوقٌ [ن ط ق] (مفع. من نَطَقَ). 1.""مَنْطُوقُ الكَلاَمِ"" : قَوْلُهُ، لَفْظُهُ. 2.""مَنْطُوقُ الكَلِمَةِ"" : مَعْنَاهَا الْحَقِيقِيُّ. 3.""مَنْطُوقُ الْحُكْمِ"" : النُّطْقُ بِهِ كَمَا هُوَ إِعْلاَنُهُ. 4.""مَنْطُوقُ الاِتِّهَامِ"" : مُحْتَوَاهُ، مَضْمُونُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5686, 'مَنْظُورٌ', 'منظور', 'اسم مفعول', 'نظر', 'منظور', 'منظر', 'مفع. من نَظَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَنْظُورٌ-مَنْظُورٌ، ةٌ [ن ظ ر] (مفع. من نَظَرَ). 1.""سَيِّدٌ مَنْظُورٌ"" : مَا يُرْجَى خَيْرُهُ. 2.""وَلَدٌ مَنْظُورٌ"" : مُصَابٌ بِالعَيْنِ. 3.""أَدَوَاتٌ مَنْزِلِيَّةٌ مَنْظُورَةٌ"" : تَتَعَلَّقُ بِهَا الأَنْظَارُ رَغْبَةً فِيهَا. 4.""اِمْرَأَةٌ مَنْظُورَةٌ"" : مَعِيبَةٌ، فَاسِدَةٌ، مُتَهَتِّكَةٌ. 5.""رَجُلٌ مَنْظُورٌ إِلَيْهِ"" : مُهْتَمٌّ بِهِ، مَحَلُّ اعْتِبَارٍ وَاهْتِمَامٍ وَاعْتِنَاءٍ. ""وَلَدٌ مَنْظُورٌ فِي أَمْرِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5687, 'مُنَظَّفٌ', 'منظف', 'اسم مفعول', 'نظف', 'منظف', 'منظف', 'مفع. من نَظَّفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُنَظَّفٌ-مُنَظَّفٌ، ةٌ [ن ظ ف] (مفع. من نَظَّفَ). ""مَكَانٌ مُنَظَّفٌ"" : نَظِيفٌ، لاَ أَوْسَاخَ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5688, 'مَنْظُومٌ', 'منظوم', 'اسم مفعول', 'نظم', 'منظوم', 'منظم', 'مفع. مِنْ نَظَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع مِنْ نَظَمَ). 1.""عِقْدٌ مَنْظُومٌ مِنْ لُؤْلُؤٍ وَمَرْجَانٍ"" : مُرَتَّبٌ، مَضْمُومٌ بَعْضُهُ إِلَى بَعْضٍ. 2.""يُجِيدُ قَوْلَ الْمَنْظُومِ"" : الشِّعْرِ. 3.""دَرَسَ مَنْظُومَةَ ابْنِ مَالِكٍ فِي الأَلْفِيَّةِ"" : الأُرْجوزَةُ، القَصِيدَةُ التَّعْلِيمِيَّةُ. 4.""كَانَ أَشْبَهَ بِالنَّجْمَيْنِ السَّيَّارَيْنِ فِي الْمَنْظُومَةِ الوَاحِدَةِ"" : الوَحْدَةُ الْمَدَارِيَّةُ تَتَضَمَّنُ عَدَداً مِنَ الكَوَاكِبِ. 5.""مَنْظُومَةٌ فِكْرِيَّةٌ"" : أَيْ أُطْرُوحَةٌ تَتَضَمَّنُ مَفَاهِيمَ حَوْلَ قَضِيَّةٍ فِكْرِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5689, 'مُنَظَّمٌ', 'منظم', 'اسم مفعول', 'نظم', 'منظم', 'منظم', 'مفع. من نَظَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من نَظَّمَ). ""عَمَلٌ مُنَظَّمٌ"" : مُرَتَّبٌ. ""صُفُوفٌ مُنَظَّمَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5690, 'مُنَعَّمٌ', 'منعم', 'اسم مفعول', 'نعم', 'منعم', 'منعم', 'مفع. من نَعَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من نَعَّمَ). 1.""قَمْحٌ مُنَعَّمٌ"" : مَطْحُونٌ طَحْناً دَقِيقاً نَاعِماً. 2.""مُنَعَّمُونَ فِي حَيَاتِهِمُ الجَدِيدَةِ"" : أَيْ هُمْ فِي حَيَاةٍ هَنِيئَةٍ ونِعْمَةٍ. 3.""كَلاَمٌ مُنَعَّمٌ"" : لَيِّنٌ لَطِيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5691, 'مُنَغَّمٌ', 'منغم', 'اسم مفعول', 'نغم', 'منغم', 'منغم', 'مفع. من نَغَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَغَّمٌ-مُنَغَّمٌ، ةٌ [ن غ م] (مفع. من نَغَّمَ). ""صَوْتٌ مُنَغَّمٌ"" : صَوْتٌ ذُو إِيقَاعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5692, 'مَنْفُوخٌ', 'منفوخ', 'اسم مفعول', 'نفخ', 'منفوخ', 'منفخ', 'مفع. من نَفَخَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْفُوخٌ-مَنْفُوخٌ، ةٌ [ن ف خ] (مفع. من نَفَخَ). 1.""بَطْنٌ مَنْفُوخٌ"" : بَطِينٌ، مُنْتَفِخٌ. 2.""كُرَةٌ مَنْفُوخَةٌ"" : وُضِعَ فِي دَاخِلِهَا هَوَاءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5693, 'مُنَفَّذٌ', 'منفذ', 'اسم مفعول', 'نفذ', 'منفذ', 'منفذ', 'مفع. من نَفَّذَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَفَّذٌ-مُنَفَّذٌ، ةٌ [ن ف ذ] (مفع. من نَفَّذَ). ""حُكْمٌ مُنَفَّذٌ"" : مَقْضِيٌّ، أَيْ صَارَ فِي حَيِّزِ التَّنْفِيذِ والتَّطْبِيقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5694, 'مَنْفُوشٌ', 'منفوش', 'اسم مفعول', 'نفش', 'منفوش', 'منفش', 'مفع. من نَفَشَ ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْفُوشٌ-مَنْفُوشٌ، ةٌ [ن ف ش] (مفع. من نَفَشَ ). ""شَعْرٌ مَنْفُوشٌ"" : مُنْتَفِشٌ، مُشَعَّثٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5695, 'مَنْفُوضٌ', 'منفوض', 'اسم مفعول', 'نفض', 'منفوض', 'منفض', 'مفع. من نَفَضَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من نَفَضَ). 1.""جِدَارٌ مَنْفُوضٌ"" : أُصِيبَ بِاهْتِزَازٍ، بِرَجَّةٍ، بِهَزَّةٍ. 2.""وَلَدٌ مَنْفُوضٌ : أَصَابَتْهُ رِعْدَةُ الْحُمَّى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5696, 'مَنْفِيٌّ', 'منفي', 'اسم مفعول', 'نفي', 'منفي', 'منف', 'مفع. من نَفَى', '', 'ة', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من نَفَى). ""مَنْفِيٌّ عَنْ وَطَنِهِ"" : مُبْعَدٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5697, 'مَنْقُوبٌ', 'منقوب', 'اسم مفعول', 'نقب', 'منقوب', 'منقب', 'مفع. من نَقَبَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْقُوبٌ-مَنْقُوبٌ، ةٌ [ن ق ب] (مفع. من نَقَبَ). ""خَشَبٌ مَنْقُوبٌ"" : مَثْقُوبٌ، مَخْرُوقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5698, 'مُنَقَّحٌ', 'منقح', 'اسم مفعول', 'نقح', 'منقح', 'منقح', 'مفع. من نَقَّحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من نَقَّحَ). ""أُسْلُوبٌ مُنَقَّحٌ"" : أُسْلُوبٌ صُحِّحَتْ أَخْطَاؤُهُ وعُدِّلَتْ فِقْرَاتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5699, 'مَنْقُوشٌ', 'منقوش', 'اسم مفعول', 'نقش', 'منقوش', 'منقش', 'مفع. من نَقَشَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْقُوشٌ-مَنْقُوشٌ، ةُ [ن ق ش] (مفع. من نَقَشَ). ""جِدَارٌ مَنْقُوشٌ"" : أَيْ جِدَارٌ تَمَّ عَلَيْهِ نَقْشٌ كِتَابَةً أو رَسْماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5700, 'مُنَقَّطٌ', 'منقط', 'اسم مفعول', 'نقط', 'منقط', 'منقط', 'مفع. من نَقَّطَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَقَّطٌ-مُنَقَّطٌ، ةٌ [ن ق ط] (مفع. من نَقَّطَ). 1. ""حَرْفٌ مُنَقَّطٌ"" : عَلَيْهِ نُقْطَةٌ أو نُقْطَتَانِ أو ثَلاَثُ نُقَطٍ. 2. ""ثَوْبٌ مُنَقَّطٌ"" : مُزَيَّنٌ بِنُقَطٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5701, 'مَنْقُوطٌ', 'منقوط', 'اسم مفعول', 'نقط', 'منقوط', 'منقط', 'مفع. من نَقَطَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْقُوطٌ-مَنْقُوطٌ [ن ق ط] (مفع. من نَقَطَ). ""كِتَابٌ مَنْقُوطٌ"" : مَشْكُولٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5702, 'مَنْقُوعٌ', 'منقوع', 'اسم مفعول', 'نقع', 'منقوع', 'منقع', 'مفع. من نَقَعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْقُوعٌ-مَنْقُوعٌ [ن ق ع] (مفع. من نَقَعَ). ""زَبِيبٌ مَنْقُوعٌ"" : زَبِيبٌ تُرِكَ فِي الْمَاءِ حَتَّى يَنْحَلَّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5703, 'مَنْقُولٌ', 'منقول', 'اسم مفعول', 'نقل', 'منقول', 'منقل', 'مفع. من نَقَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من نَقَلَ). 1.""جاءوا بِهِ مَنْقُولاً عَلَى سَرِيرٍ"" : مَحْمُولاً مِنْ مَكَانٍ إِلَى آخَرَ. 2.""نَصٌّ مَنْقُولٌ مِنَ الفَرَنْسِيَّةِ إِلَى العَرَبِيَّةِ"" : مُتَرْجَمٌ. 3.""حَدِيثٌ مَنْقُولٌ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5704, 'مَنْكُوبٌ', 'منكوب', 'اسم مفعول', 'نكب', 'منكوب', 'منكب', 'مفع. من نَكَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من نَكَبَ). ""شَعْبٌ مَنْكوبٌ"" : مُصَابٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5705, 'مُنَكَّدٌ', 'منكد', 'اسم مفعول', 'نكد', 'منكد', 'منكد', 'مفع. من نَكَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَكَّدٌ-مُنَكَّدٌ [ن ك د] (مفع. من نَكَّدَ). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5706, 'مَنْكُودٌ', 'منكود', 'اسم مفعول', 'نكد', 'منكود', 'منكد', 'مفع. من نَكَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَنَاكِيدُ"', '', '', '', '', '', '', '', '', '"(مفع. من نَكَدَ). 1.""رَجُلٌ مَنْكُودٌ"" : تَعِسٌ، شَقِيٌّ. ""مَنَاكِيدُ جِيَاعٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5707, 'مَنَاكِيدُ', 'مناكيد', 'اسم مفعول', '', 'مناكيد', 'منكد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5708, 'مُنَكَّرٌ', 'منكر', 'اسم مفعول', 'نكر', 'منكر', 'منكر', 'مفع. من نَكَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَكَّرٌ-مُنَكَّرٌ، ةٌ [ن ك ر] (مفع. من نَكَّرَ). ""رَجُلٌ"" : اِسْمٌ مُنَكَّرٌ (نح) خِلاَفُ الْمُعَرَّفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5709, 'مُنَكَّسٌ', 'منكس', 'اسم مفعول', 'نكس', 'منكس', 'منكس', 'مفع. من نَكَّسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من نَكَّسَ). 1.""فَرَسٌ مُنَكَّسٌ"" : رَأْسُهُ مُنْخَفِضٌ بِسَبَبِ ضُعْفٍ أَوْ عَيَاءٍ. 2.""جَاءَ مُنَكَّسَ الرَّأْسِ"" : مُنْخَفِضَ الرَّأ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5710, 'مَنْكُوسٌ', 'منكوس', 'اسم مفعول', 'نكس', 'منكوس', 'منكس', 'مفع. من نَكَسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْكُوسٌ-مَنْكُوسٌ [ن ك س] (مفع. من نَكَسَ). 1.""عَلَمٌ مَنْكُوسٌ"" : عَلَمٌ مَقْلُوبٌ يُخْفَضُ عَلَى إ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5711, 'مَنْكُوشٌ', 'منكوش', 'اسم مفعول', 'نكش', 'منكوش', 'منكش', 'مفع. من نَكَشَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَنْكُوشٌ-مَنْكُوشٌ، ةٌ [ن ك ش] (مفع. من نَكَشَ). 1.""شَعْرٌ مَنْكُوشٌ"" : مُش"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5712, 'مُنَمَّقٌ', 'منمق', 'اسم مفعول', 'نمق', 'منمق', 'منمق', 'مفع. من نَمَّقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَمَّقٌ-مُنَمَّقٌ، ةٌ [ن م ق] (مفع. من نَمَّقَ). 1.""ثَوْبٌ مُنَمَّقٌ"": مُزَيَّنٌ بِنُقُوشٍ. 2.""كِتَابٌ مُنَمَّقٌ"" : كِتَابٌ كِتَابَتُهُ مُجَوَّدَةٌ. 3.""كَلاَمٌ مُنَمَّقٌ"" : مُزَخْرَف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5713, 'مُنَمْنَمٌ', 'منمنم', 'اسم مفعول', 'نمنم', 'منمنم', 'منمنم', 'مفع. من نَمْنَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من نَمْنَمَ). 1.""وَشْمٌ مُنَمْنَمٌ"" : مَنْقُوشٌ. 2.""مُصْحَفٌ مُنَمْنَمٌ"" : مُزَخْرَفٌ. ""رُسُومٌ مُنَمْنَمَةٌ"". 3.""ثَوْبٌ مُنَمْنَمٌ"" : مُوشّىً. 4.""كِتَابٌ مُنَمْنَمٌ "" : مُزَيَّنٌ ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5714, 'مَنْهُوكٌ', 'منهوك', 'اسم مفعول', 'نهك', 'منهوك', 'منهك', 'مفع. من نَهَكَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من نَهَكَ). ""عَادَ إِلَى بَيْتِهِ مَنْهُوكَ القُوَى"" : مُنْهَكاً، مُتْعَباً تَعَباً شَدِيداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5715, 'مَنْهِيٌّ', 'منهي', 'اسم مفعول', 'نهي', 'منهي', 'منه', 'مفع. من نَهَى', '', 'ة', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَنْهِيٌّ-مَنْهِيٌّ، ةٌ [ن هـ ي] (مفع. من نَهَى). ""عَمَلٌ مَنْهِيٌّ عَنْهُ"" : مَحْظُورٌ، مُحَرَّمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5716, 'مُنَوَّرٌ', 'منور', 'اسم مفعول', 'نور', 'منور', 'منر', 'مفع. من نَوَّرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَوَّرٌ-مُنَوَّرٌ، ةٌ [ن و ر] (مفع. من نَوَّرَ). 1.""بَيْتٌ مُنَوَّرٌ"" : مُضَاءٌ. 2.""وَجْهٌ مُنَوَّرٌ"" : وَجْهٌ جَمِيلٌ تَعْلُوهُ ابْتِسَامَةٌ. 3"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5717, 'مُنَوَّعٌ', 'منوع', 'اسم مفعول', 'نوع', 'منوع', 'منع', 'مفع. من نَوَّعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من نَوَّعَ). 1.""طَعَامٌ مُنَوَّعٌ"" : أَنْوَاعُهُ مُخْتَلِفَةٌ. ""أَكْلاَتٌ مُنَوَّعَةٌ"". 2.""مُنَوَّعَاتٌ أَدَبِيَّةٌ"" : مُنْتَخَبَاتٌ. 3.""سَهْرَةُ الْمُنَوَّعَاتِ"" : سَهْرَةٌ مُتَنَوِّعَةٌ فِيهَا غِنَاءٌ ومَسْرَحٌ ورَقْصٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5718, 'مَهِيضٌ', 'مهيض', 'اسم مفعول', 'هيض', 'مهيض', 'مهض', 'مفع. من هَاضَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"مَهِيضٌ-مَهِيضٌ، ةٌ [هـ ي ض] (مفع. من هَاضَ). 1.""عَظْمٌ مَهِيضٌ"" : مَكْسُورٌ بَعْدَ الْجَبْرِ. 2.""مَهِيضُ الجَنَاحِ"" : ضَعِيفٌ، فَاقِدٌ لِلْقُوَى. ""طَائِرٌ مَهِيضُ الجَنَاحِ"" ""لاَ لَذَّةَ مَعَ كِبْرِيَاء مَهِيضَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5719, 'مَهُولٌ', 'مهول', 'اسم مفعول', 'هول', 'مهول', 'مهل', 'مفع. من هَالَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَهُولٌ-مَهُولٌ [هـ و ل] (مفع. من هَالَ). ""مَكَانٌ مَهُولٌ"" : يَبْعَثُ عَلَى الخَوْفِ وَالذُّعْرِ، مَخُوفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5720, 'مَهْبُولٌ', 'مهبول', 'اسم مفعول', 'هبل', 'مهبول', 'مهبل', 'مفع. من هَبِلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من هَبِلَ). ""وَلَدٌ مَهْبُولٌ"" : أَهْوَجُ، أَحْمَقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5721, 'مهابيل', 'مهابيل', 'اسم مفعول', '', 'مهابيل', 'مهبل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5722, 'مَهْجُوٌّ', 'مهجو', 'اسم مفعول', 'هجو', 'مهجو', 'مهج', 'مفع. من هَجَا', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من هَجَا). ""مَهْجُوٌّ مِنْ شَاعِرِ القَبِيلَةِ"" : أَيْ وَقَعَ عَلَيْهِ هِجَاءُ شَاعِرِ القَبِيلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5723, 'مُهَجَّرٌ', 'مهجر', 'اسم مفعول', 'هجر', 'مهجر', 'مهجر', 'مفع. من هَجَّرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من هَجَّرَ). ""رَجُلٌ مُهَجَّرٌ"" : أَيْ تَمَّ تَهْجِيرُهُ، تَرْحِيلُهُ مِن مَوْطِنِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5724, 'مَهْجُورٌ', 'مهجور', 'اسم مفعول', 'هجر', 'مهجور', 'مهجر', 'مفع. من هَجَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من هَجَرَ). 1.""بَيْتٌ مَهْجُورٌ"" : بَيْتٌ هَجَرَهُ أَهْلُهُ، خَالٍ. 2.""اِمْرَأَةٌ مَهْجُورَةٌ"" : مَتْرُوكَةٌ. 3.""جَزِيرَةٌ مَهْجُورَةٌ"" : غَيْرُ مَسْكُونَةٍ، أَيْ لاَ أَحَدَ عَلَى سَطْحِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5725, 'مُهَدَّدٌ', 'مهدد', 'اسم مفعول', 'هدد', 'مهدد', 'مهد', 'مفع. من هَدَّدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من هَدَّدَ). ""مُهَدَّدٌ بِعِقَابٍ شَدِيدٍ"" : مُخَوَّفٌ، مُتَوَعَّدٌ ... ""مُهَدَّدٌ بِالْمَوْتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5726, 'مُهَدَّمٌ', 'مهدم', 'اسم مفعول', 'هدم', 'مهدم', 'مهدم', 'مفع. من هَدَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُهَدَّمٌ-مُهَدَّمٌ، ةٌ [هـ د م ] (مفع. من هَدَّمَ). ""بُنْيَانٌ مُهَدَّمٌ"" : أَيْ جُدْرَانُهُ مُتَسَاقِطَةٌ. ""آثَارٌ مُهَدَّمَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5727, 'مَهْدِيٌّ', 'مهدي', 'اسم مفعول', 'هدي', 'مهدي', 'مهد', 'مفع. من هَدَى', '', 'ة', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من هَدَى). 1. ""وَلَدٌ مَهْدِيٌّ"" : الْمُنْقَادُ لِلْخَيْرِ ومَنْ هَدَاهُ الله لِطَرِيقِ الْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5728, 'مُهَذَّبٌ', 'مهذب', 'اسم مفعول', 'هذب', 'مهذب', 'مهذب', 'مفع. من هَذَّبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من هَذَّبَ). 1.""وَلَدٌ مُهَذَّبٌ"" : مُؤَدَّبٌ، أَيْ مَنْ كَانَتْ أَخْلاَق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5729, 'مُهَرَّبٌ', 'مهرب', 'اسم مفعول', 'هرب', 'مهرب', 'مهرب', 'مفع. من هَرَّبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من هَرَّبَ). ""بَضَائِعُ مُهَرَّبَةٌ"" : بَضَائِعُ وَقَعَ تَهْرِيبُهَا خُفْيَةً ع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5730, 'مَهْزُولٌ', 'مهزول', 'اسم مفعول', 'هزل', 'مهزول', 'مهزل', 'مفع. من هَزَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من هَزَلَ). ""مَهْزُولُ الْجِسْمِ"" : نَحِيفُهُ، ضَعِيفُهُ. """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5731, 'مَهْزُومٌ', 'مهزوم', 'اسم مفعول', 'هزم', 'مهزوم', 'مهزم', 'مفع. من هَزَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من هَزَمَ). ""جَيْشٌ مَهْزُومٌ"" : مُنْكَسِرٌ، خَائِبٌ فِي مَعْرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5732, 'مُهَشَّمٌ', 'مهشم', 'اسم مفعول', 'هشم', 'مهشم', 'مهشم', 'مفع. من هَشَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من هَشَّمَ). 1.""زُجَاجٌ مُهَشَّمٌ"" : مُكَسَّرٌ، مُحَطَّمٌ. 2.""مُهَشَّمُ الرَّأْسِ"" : مُصَابٌ فِي رَأْسِهِ بِجُرُوحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5733, 'مَهْضُومٌ', 'مهضوم', 'اسم مفعول', 'هضم', 'مهضوم', 'مهضم', 'مفع. من هَضَمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"(مفع. من هَضَمَ). 1.""طَعَامٌ مَهْضُومٌ"" : أَيْ حَصَلَتْ لَهُ عَمَلِيَّةُ الهَضْمِ. 2.""يُدَافِعُ عَنْ كُلِّ ضَعِيفٍ مَظْلُومٍ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5734, 'مُهَفْهَفٌ', 'مهفهف', 'اسم مفعول', 'هفهف', 'مهفهف', 'مهفهف', 'مفع. من هَفْهَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من هَفْهَفَ). ""شَابٌّ مُهَفْهَفٌ"" : ضَامِرُ الْبَطْنِ دَقِيقُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5735, 'مُهَلْهَلٌ', 'مهلهل', 'اسم مفعول', 'هلهل', 'مهلهل', 'مهلهل', 'مفع. من هَلْهَلَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُهَلْهَلٌ-مُهَلْهَلٌ، ةٌ [هـ ل هـ ل] (مفع. من هَلْهَلَ). 1.""ثَوْبٌ مُهَلْهَلٌ"" : ثَوْبٌ مَنْسُوجٌ نَسْجاً خَفِيفاً. 2.""كَلاَمٌ مُهَلْهَلٌ"" : غَيْرُ مُتَمَاسِكٍ، غَيْرُ مُنَقَّحٍ. ""شِعْرٌ مُهَلْهَلٌ"". 3.""الْمُهَلْهَلُ"" : طَيْرٌ مِنْ فَصِيلَةِ الْمَازُورِيَّاتِ يَأْلَفُ مَجَارِيَ الْمِيَاهِ وَيَقْتَاتُ بِالأَسْمَاكِ الصَّغِيرَةِ وَالْحَشَرَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5736, 'مَهْمُومٌ', 'مهموم', 'اسم مفعول', 'همم', 'مهموم', 'مهمم', 'مفع. من هَمَّ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من هَمَّ). ""رَجُلٌ مَهْمُومٌ بِمَشَاكِلِهِ"": مَغْمُومٌ، مَحْزُونٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5737, 'مَهْمُوسٌ', 'مهموس', 'اسم مفعول', 'همس', 'مهموس', 'مهمس', 'مفع. من هَمَسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَهْمُوسٌ-مَهْمُوسٌ، ةٌ [هـ م س] (مفع. من هَمَسَ). 1.""كَلاَمٌ مَهْمُوسٌ"" : كَلاَمٌ خَافِتٌ غَيْرُ ظَاهِرٍ. 2.""حَرْفٌ مَهْمُوسٌ"" : حَرْفٌ لاَ يَتَذَبْذَبُ مَعَهُ الْوَتَرَانِ الصَّوْتِيَّانِ أَثْنَاءَ النُّطْقِ بِهِ مِثْلُ البَاءِ وَالدَّالِ وَالسِّينِ وَالهَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5738, 'مُهَمَّشٌ', 'مهمش', 'اسم مفعول', 'همش', 'مهمش', 'مهمش', 'مفع. من هَمَّشَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من هَمَّشَ). 1.""كِتَابٌ مُهَمَّشٌ"" : كِتَابٌ بِهِ تَعْلِيقَاتٌ عَلَى هَامِشِهِ. 2.""مَوْضُوعٌ مُهَمَّشٌ"" : مَوْضُوعٌ هَامِشِيٌّ، أَيْ ثَانَوِيٌّ. ""قَضِيَّةٌ مُهَمَّشَةٌ"". 3.""شَابٌّ مُهَمَّشٌ"" : أَيْ يَعِيشُ عَلَى هَامِشِ الْمُجْتَمَعِ. ""يَعْرِفُ الْمُجْتَمَعُ الْحَدِيثُ فِئَةً مِنَ الْمُهَمَّشِينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5739, 'مُهَنَّدٌ', 'مهند', 'اسم مفعول', 'هند', 'مهند', 'مهند', 'مفع. من هَنَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُهَنَّدٌ-مُهَنَّدٌ [هـ ن د] (مفع. من هَنَّدَ). ""سَيْفٌ مُهَنَّدٌ"" : سَيْفٌ مَصْنُوعٌ مِنْ حَدِيدِ بِلاَدِ الْهِنْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5740, 'مُهَوَّسٌ', 'مهوس', 'اسم مفعول', 'هوس', 'مهوس', 'مهس', 'مفع. من هَوَّسَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من هَوَّسَ). ""رَجُلٌ مُهَوَّسٌ"" : ذُو هَوْسٍ، أَيْ مَنْ يُشْغِلُ نَفْسَهُ بِالْهَوَاجِسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5741, 'مَوْبُوءٌ', 'موبوء', 'اسم مفعول', 'وبأ', 'موبوء', 'مب', 'مفع. من وَبِئَ', '', '', 'مفرد', 'Dz', 'Pm', '', '""', '', '', '', '', '', '', '', '', '"(مفع. من وَبِئَ). 1.""وَلَدٌ مَوْبُوءٌ"" : مُصَابٌ بِالوَبَاءِ. ""بَلَدٌ مَوْبُوءٌ"". 2.""شَوَاطِئُ مَوْبُوءةٌ بِالبُقَعِ السَّوْدَاءِ"" : مُتَعَفِّنَةٌ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5742, 'مَوْبُوءَةٌ', 'موبوءة', 'اسم مفعول', '', 'موبوءة', 'مبة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من وَبِئَ). 1.""وَلَدٌ مَوْبُوءٌ"" : مُصَابٌ بِالوَبَاءِ. ""بَلَدٌ مَوْبُوءٌ"". 2.""شَوَاطِئُ مَوْبُوءةٌ بِالبُقَعِ السَّوْدَاءِ"" : مُتَعَفِّنَةٌ بِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5743, 'مَوْتُورٌ', 'موتور', 'اسم مفعول', 'وتر', 'موتور', 'متر', 'مفع. من وَتَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَوْتُورٌ-مَوْتُورٌ، ةٌ [و ت ر] (مفع. من وَتَرَ). 1.""رَجُلٌ مَوْتُـورٌ"" : مَنْ قُتِلَ لَهُ قَرِيبٌ وَلاَ قُدْرَةَ لَهُ عَلَى أَخْذِ ثَأْرِهِ. 2.""قَوْسٌ مَوْتُورَةٌ"" : قَوْسٌ ذَاتُ وَتَرٍ مَشْدُودٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5744, 'مُوَثَّقٌ', 'موثق', 'اسم مفعول', 'وثق', 'موثق', 'مثق', 'مفع. من وَثَّقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَثَّقٌ-مُوَثَّقٌ، ةٌ [و ث ق] (مفع. من وَثَّقَ). ""عَقْدٌ مَوَثَّقٌ"" : أَيْ تَمَّ تَوْثِيقُهُ حَسَبَ القَانُونِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5745, 'مَوْثُوقٌ', 'موثوق', 'اسم مفعول', 'وثق', 'موثوق', 'مثق', 'مفع. من وَثِقَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"(مفع. من وَثِقَ). 1.""مَوْثُوقٌ بِشَهَادَتِهِ"" : يُعْتَمَدُ عَلَى شَهَادَتِهِ، يُؤْخَذُ بِهَا. ""رَجُلٌ مَوْثُوقٌ بِهِ"". 2.""أَوْرَدَ خَبَراً مِنْ مَصْدَرٍ مَوْثُوقٍ بِهِ"" : مِنْ مَصْدَرٍ جَدِيرٍ بِالثِّقَةِ، أَيْ لاَ شَكَّ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5746, 'مَوْجُودٌ', 'موجود', 'اسم مفعول', 'وجد', 'موجود', 'مجد', 'مفع. من وَجَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَجَدَ). 1.""مَوْجُودٌ فِي بَيْتِهِ"" : أَيْ وُجُودُهُ فِي البَيْتِ حَاصِلٌ. ""غَيْرُ مَوْجُود"". 2.""بَضَائِعُ أَجْنَبِيَّةٌ مَوْجُودَةٌ بِالسُّوقِ"" : مُتَوَافِرَةٌ. 3.""أَنَا أُفَكِّرُ إِذًا أَنَا مَوْجُودٌ"" : أَنَا كَائِنٌ. 4.""مَوْجُودَاتُ الكَـوْنِ"" : كَائِنَاتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5747, 'مُوَجَّهٌ', 'موجه', 'اسم مفعول', 'وجه', 'موجه', 'مجه', 'مفع. من وَجَّهَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُوَجَّهٌ-مُوَجَّهٌ، ةٌ [و ج هـ] (مفع. من وَجَّهَ). 1.""كَلاَمٌ مُوَجَّهٌ إِلَى الْمَسْؤُولِينَ"" : مُرْسَلٌ. 2.""خُطَّةٌ مُوَجَّهَةٌ"" : خُطَّةٌ مَرْسُومَةٌ مِنْ جِهَةٍ مَّا. ""الاقْتِصَادُ الْمُوَجَّهُ"" : اِقْتِصَادٌ مَوْضُوعٌ ومَرْسُومٌ مِنْ قِبَلِ الْحُكُومَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5748, 'مُوَحَّدٌ', 'موحد', 'اسم مفعول', 'وحد', 'موحد', 'محد', 'مفع. من وَحَّدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَحَّدَ). 1.""شَعْبٌ مُوَحَّدٌ عَلَى كَلِمَةٍ وَاحِدَةٍ"" : مُتَّحِدٌ... 2.""بَرَامِجُ مُوَحَّدَةٌ"" : عَلى نَسَقٍ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5749, 'مَوْرُوثٌ', 'موروث', 'اسم مفعول', 'ورث', 'موروث', 'مرث', 'مفع. من وَرِثَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَرِثَ). 1.""الجَدُّ الْمَوْرُوثُ"" : الَّذِي تَرَكَ المِيرَاثَ. 2.""مَوْرُوثَاتُ العَائِلَةِ"" : مَا تَوَارَثَتْهُ مِنْ إِرْثٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5750, 'مُوَرَّدٌ', 'مورد', 'اسم مفعول', 'ورد', 'مورد', 'مرد', 'مفع. من وَرَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"مُوَرَّدٌ-مُوَرَّدٌ [و ر د] (مفع. من وَرَّدَ). ""خَدٌّ مُوَرَّدٌ"" : مُحْمَرٌّ كَالوَرْدَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5751, 'مُوَرَّمٌ', 'مورم', 'اسم مفعول', 'ورم', 'مورم', 'مرم', 'مفع. من وَرَّمَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَرَّمٌ-مُوَرَّمٌ، ةٌ [و ر م] (مفع. من وَرَّمَ). ""وَجْهٌ مُوَرَّمٌ"" : مُنْتَفِخٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5752, 'مُوَزَّعٌ', 'موزع', 'اسم مفعول', 'وزع', 'موزع', 'مزع', 'مفع. من وَزَّعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَزَّعَ). 1.""مُوَزَّعٌ بَيْنَ أَمْرَيْنِ"" : مُشَتَّتٌ... 2.""غَنِيمَةٌ مُوَزَّعَةٌ بَيْنَ الْمُنْتَصِرِينَ"" : مُقَسَّمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5753, 'مَوْزُونٌ', 'موزون', 'اسم مفعول', 'وزن', 'موزون', 'مزن', 'مفع. من وَزَنَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَوْزُونٌ-مَوْزُونٌ، ةٌ [و ز ن] (مفع. من وَزَنَ). 1. ""كَلاَمٌ مَوْزُونٌ"" : أَيْ كُلُّ كَلِمَةٍ فِي مَحَلِّهَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5754, 'مُوَسَّخٌ', 'موسخ', 'اسم مفعول', 'وسخ', 'موسخ', 'مسخ', 'مفع. من وَسَّخَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَسَّخَ). 1. ""ثَوْبٌ مُوَسَّخٌ"" : مُلَطّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5755, 'مُوَسَّعٌ', 'موسع', 'اسم مفعول', 'وسع', 'موسع', 'مسع', 'مفع. من وَسَّعَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَسَّعٌ-مُوَسَّعٌ [و س ع] (مفع. من وَسَّعَ). ""بَيْتٌ مُوَسَّعٌ"" : أَيْ فَسِيحُ الأَرْجَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5756, 'مُوَسْوَسٌ', 'موسوس', 'اسم مفعول', 'وسوس', 'موسوس', 'مسس', 'مفع. من وَسْوَسَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَسْوَسَ). ""رَجُلٌ مُوَسْوَسٌ"" : أَيْ مَرِيضٌ بِالوَسْوَاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5757, 'مُوَشَّحٌ', 'موشح', 'اسم مفعول', 'وشح', 'موشح', 'مشح', 'مفع. من وَشَّحَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَشَّحَ). 1.""مُوَشَّحٌ بِوِسَامِ العَرْشِ"" : أَيْ وُشِّحَ صَدْرُهُ بوِسَامٍ. 2.""مُوَشَّحٌ شِعْرِيٌّ"" : نَمَطٌ شِعْرِيُّ بَرَعَ فِيهِ أَهْلُ الأَنْدَلُسِ، وهُوَ يَضُمُّ أَسْمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5758, 'مُوَشّىً', 'موشى', 'اسم مفعول', 'وشي', 'موشى', 'مش', 'مفع. من وَشَّى', '', '', 'مفرد', 'Dy', '', '', '""', '', '', '', '', '', '', '', '', '"مُوَشّىً-مُوَشّىً [و ش ي] (مفع. من وَشَّى). ""ثَوْبٌ مُوَشّىً"" : مُزَيَّنٌ، مَنْقُوشٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5759, 'مُوَشّاة', 'موشاة', 'اسم مفعول', '', 'موشاة', 'مشة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَشّىً-مُوَشّىً [و ش ي] (مفع. من وَشَّى). ""ثَوْبٌ مُوَشّىً"" : مُزَيَّنٌ، مَنْقُوشٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5760, 'مَوْصُوفٌ', 'موصوف', 'اسم مفعول', 'وصف', 'موصوف', 'مصف', 'مفع. من وَصَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَصَفَ). 1.""رَجُلٌ مَوْصُوفٌ بِالكَرَمِ"" : مَنْعُوتٌ. 2.""الاِسْمُ الْمَوْصُوفُ"" : هُوَ مَا دَلَّ عَلَى ذَاتِ الشَّيْءِ وحَقِيقَتِهِ: رَجُلٌ، اِمْرَأَةٌ، شَمْسٌ، سَمَاءٌ ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5761, 'مَوْصُولٌ', 'موصول', 'اسم مفعول', 'وصل', 'موصول', 'مصل', 'مفع. من وَصَلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَوْصُولٌ-مَوْصُولٌ، ةٌ [و ص ل] (مفع. من وَصَلَ). 1.""حُبٌّ مَوْصُولٌ"" : مُتَبَادَلٌ ودَائِمٌ مُتَّصِلٌ. ""لاَحَظَ أَنَّ الْحُبَّ أَصْبَحَ مَقْطُوعاً والحِقْدَ مَوْصُولاً"". 2.""أَيَّامٌ مَوْصُولَةٌ"" : مُتَتَابِعَةٌ، مُتَتَالِيَةٌ. 3.""الْمَوْصُولُ فِي النَّحْوِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5762, 'مَوْصُومٌ', 'موصوم', 'اسم مفعول', 'وصم', 'موصوم', 'مصم', 'مفع. من وَصَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَصَمَ). 1.""مَوْصُومٌ بِالْجُبْنِ"" : مَعِيبٌ. 2.""مُمَارَسَاتٌ مَوْصُومَةٌ"": بِهَا عَيْبٌ مِنَ العُيُوبِ. ""وأَحْسَنُ مَا تُوصَفُ بِهِ الكَرَامَةُ عَلَى مَذْهَبِهَا أَنَّهَا كِسْوَةٌ اجْتِمَاعِيَّةٌ ولاَ يَخْلَعُهَا الْمَرْءُ فِي الْمَجَالِسِ ولاَ يَلْبَسُهَا مُمَزَّقَةً أَوْ مُرَقَّعَةً أو مَوْصُومَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5763, 'مُوَضَّحٌ', 'موضح', 'اسم مفعول', 'وضح', 'موضح', 'مضح', 'مفع. من وَضَّحَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَضَّحٌ-مُوَضَّحٌ، ةٌ [و ض ح] (مفع. من وَضَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5764, 'مُوَطَّأٌ', 'موطأ', 'اسم مفعول', 'وطأ', 'موطء', 'مط', 'مفع. من وَطَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَطَّأٌ-مُوَطَّأٌ [و ط أ] (مفع. من وَطَّأَ). ""مُوَطَّأُ الأَكْنَافِ"" : مَنْ يُمْكِنُكَ مُصَاحَبَتُهُ دُونَ أَنْ يُؤْذِيَكَ، كَرِيمٌ، مِضْيَافٌ. أَلاَ أُخْبِرُكُمْ ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5765, 'مُوَطَّأَةٌ', 'موطأة', 'اسم مفعول', '', 'موطءة', 'مطة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَطَّأٌ-مُوَطَّأٌ [و ط أ] (مفع. من وَطَّأَ). ""مُوَطَّأُ الأَكْنَافِ"" : مَنْ يُمْكِنُكَ مُصَاحَبَتُهُ دُونَ أَنْ يُؤْذِيَكَ، كَرِيمٌ، مِضْيَافٌ. أَلاَ أُخْبِرُكُمْ ب"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5766, 'مُوَطَّدٌ', 'موطد', 'اسم مفعول', 'وطد', 'موطد', 'مطد', 'مفع. من وَطَّدَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَطَّدٌ-مُوَطَّدٌ [و ط د] (مفع. من وَطَّدَ). ""بُنْيَانٌ مُوَطَّدٌ"" : مُقَوّىً، مُثَبَّتٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5767, 'مُوَظَّفٌ', 'موظف', 'اسم مفعول', 'وظف', 'موظف', 'مظف', 'مفع. من وَظَّفَ.', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مفع. من وَظَّفَ). 1.""مَالٌ مُوَظَّفٌ فِي البَنْكِ"" : مُسْتَثْمَرٌ. 2.""مُوَظَّفٌ حُكُومِيٌّ"" : مَنْ يَشْتَغِلُ فِي إِدَارَةٍ مِنِ إِدَارَاتِ الْحُكُومَةِ : ""مُوَظَّفُو الدَّوْلَةِ""، 3.""مُوَظَّفَةٌ فِي الشَّرِكَةِ"" : عامِلَةٌ في القِطاعِ الْخاصِّ. 4.""مُؤَسَّسَةٌ خَيْرِيَّةٌ مُوَظَّفَةٌ لِخِدْمَةِ الْمُعْوِزِينَ"" : مُخَصَّصَةٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5768, 'مَوْعُودٌ', 'موعود', 'اسم مفعول', 'وعد', 'موعود', 'معد', 'مفع. من وَعَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَوَاعِيدُ"', '', '', '', '', '', '', '', '', '"(مفع. من وَعَدَ). 1.""وَفَّى بِمَوْعُودِهِ"" : أَيْ بِعَهْدِهِ. 2.""مَوَاعِيدُ عُرْقُوبٍ"" : تَعَهُّدَاتُهُ، وعَرْقُوبٌ اسْمُ رَجُلٍ مِنْ يَثْرِبَ يُضْرَبُ بِهِ الْمَثَلُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5769, 'مَوَاعِيدُ', 'مواعيد', 'اسم مفعول', '', 'مواعيد', 'معد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5770, 'مَوْعُوكٌ', 'موعوك', 'اسم مفعول', 'وعك', 'موعوك', 'معك', 'مفع. من وَعَكَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَعَكَ). ""مَوْعُوكٌ فِي صِحَّت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5771, 'مَوْفُورٌ', 'موفور', 'اسم مفعول', 'وفر', 'موفور', 'مفر', 'مفع. من وَفَرَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"مَوْفُورٌ، ةٌ - ج: ون، ات. [و ف ر]. (مفع. من وَفَرَ). 1.""مَوْفُورُ الصِّحَّةِ"" : كَامِلُ الصِّحَّةِ. 2.""مَوْفُورُ الكَرَامَةِ"": مُحْتَرَمٌ، مُوَقَّرٌ.   ""بَدَتْ فِي هُدُوئِهَا مَوْفُورَةَ الرَّزَانَةِ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5772, 'مُوَفَّقٌ', 'موفق', 'اسم مفعول', 'وفق', 'موفق', 'مفق', 'مفع. من وَفَّقَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَفَّقَ). ""مُوَفَّقٌ فِي عَمَلِهِ"" : مُصِيبٌ ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5773, 'مُوَقَّتٌ', 'موقت', 'اسم مفعول', 'وقت', 'موقت', 'مقت', 'مفع. من وَقَّتَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَقَّتٌ-مُوَقَّتٌ، ةٌ [و ق ت] (مفع. من وَقَّتَ). 1.""وَقْتٌ مُوَقَّتٌ"" : مَوْقُوتٌ،وَقْتٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5774, 'مَوْقُوتٌ', 'موقوت', 'اسم مفعول', 'وقت', 'موقوت', 'مقت', 'مفع. من وَقَتَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَوْقُوتٌ-مَوْقُوتٌ، ةٌ [و ق ت] (مفع. من وَقَتَ). 1.""فِي زَمَنٍ مَوْقُوتٍ"" : أَيْ مُحَدَّدٍ مُعَيَّنٍ.النساء آية 103 إِنَّ الصَّلاَةَ كَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5775, 'مُوَقَّرٌ', 'موقر', 'اسم مفعول', 'وقر', 'موقر', 'مقر', 'مفع. من وَقَّرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَقَّرَ). ""شَيْخٌ مُوَقَّرٌ"" : مُحْتَرَمٌ. ""مَجْلِسٌ مُوَقَّرٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5776, 'مُوَقَّعٌ', 'موقع', 'اسم مفعول', 'وقع', 'موقع', 'مقع', 'مفع. من وَقَّعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَقَّعَ). 1.""رَجُلٌ مُوَقَّعٌ سَيِّءُ الْحَظِّ"" : مُصَابٌ بِمَصَائِبَ. 2.""سِكِّينٌ مُوَقَّعٌ"" : مُحَدَّد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5777, 'مَوْقُوفٌ', 'موقوف', 'اسم مفعول', 'وقف', 'موقوف', 'مقف', 'مفع. من وَقَفَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من وَقَفَ). 1.""مَوْقُوفٌ عَنِ العَمَلِ"" : أَيْ مَمْنُوعٌ مِنْ مُزَاوَلَةِ العَمَلِ. 2.""رَجُلٌ مَوْقُوفٌ"" : مُعْتَقَلٌ، مَحْرُومٌ مِنْ حُرِّيَّتِهِ. 3.""أَمْلاَكٌ مَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5778, 'مُوَكَّلٌ', 'موكل', 'اسم مفعول', 'وكل', 'موكل', 'مكل', 'مفع. من وَكَّلَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَكَّلَ). ""مُوَكَّلٌ بِأَمْرٍ هَامٍّ"" : مُكَلَّفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5779, 'مُوَلَّدٌ', 'مولد', 'اسم مفعول', 'ولد', 'مولد', 'ملد', 'مفع. من وَلَّدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَلَّدَ). 1.""كَلاَمٌ مُوَلَّدٌ"" : مُحْدَثٌ. ""لَفْظٌ مُوَلَّدٌ"" ""أَلْفَاظٌ مُوَلَّدَةٌ"". 2.""الشُّعَرَاءُ الْمُوَلَّدُونَ"" : الْمُحْدَثُونَ. 3.""رَجُلٌ مُوَلَّدٌ"" : لَيْسَ بِعَرَبِيٍّ خَالِصٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5780, 'مَوْلُودٌ', 'مولود', 'اسم مفعول', 'ولد', 'مولود', 'ملد', 'مفع. من وَلَدَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَوَالِيدُ"', '', '', '', '', '', '', '', '', '"(مفع. من وَلَدَ). 1.""اِزْدَانَ فِرَاشُهُ بِمَوْلُودٍ"" : بِطِفْلٍ صَغِيرٍ لِقُرْبِ عَهْدِهِ بِالوِلاَدَةِ. 2.""هُوَ مِنَ مَوَالِيدِ سَنَةِ 1950"" : أَيْ وُلِدَ ..."', '');
