INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5782, 'مُوَلَّعٌ', 'مولع', 'اسم مفعول', 'ولع', 'مولع', 'ملع', 'مفع. من وَلَّعَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَلَّعَ). 1.""رَجُلٌ مُوَلَّعٌ"" : فِيهِ لُمَعٌ مِنْ بَرَصٍ بِهِ. 2.""فَرَسٌ مُوَلَّعٌ"": بِهِ بُقَعٌ مِنْ بَيَاضٍ وَسَوَادٍ مُتَفَرِّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5783, 'مُوَلَّهٌ', 'موله', 'اسم مفعول', 'وله', 'موله', 'مله', 'مفع. من وَلَّهَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَلَّهَ). ""شَابٌّ مُوَلَّهٌ"" : عَاشِقٌ بِشَغَفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5784, 'مَوْهُوبٌ', 'موهوب', 'اسم مفعول', 'وهب', 'موهوب', 'مهب', 'مفع. من وَهَبَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مفع. من وَهَبَ). ""رَجُلٌ مَوْهُوبٌ"" : مَنْ يَتَمَتَّعُ بِمَوْهِبَةٍ، بِمَلَكَةٍ، بِقَرِيحَةٍ. ""شَاعِرٌ مَوْهُوبٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5785, 'مَوْهُومٌ', 'موهوم', 'اسم مفعول', 'وهم', 'موهوم', 'مهم', 'مفع. من وَهَمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من وَهَمَ) : ""رَجُلٌ مَوْهُومٌ"" : مَنْ سَيْطَرَ عَلَيْهِ الوَهْمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5786, 'مَوْهُونٌ', 'موهون', 'اسم مفعول', 'وهن', 'موهون', 'مهن', 'مفع. من وَهَنَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من وَهَنَ). ""مَوْهُونُ القُوَى"" : مُوهَنٌ، وَاهِنٌ، ضَعِيفُ القُوَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5787, 'مَيْسُورٌ', 'ميسور', 'اسم مفعول', 'يسر', 'ميسور', 'مسر', 'مفع. مِن يَسَرَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":مَيَاسِرُ"', '', '', 'ـو', '', '', '', '', '', '"(مفع. مِن يَسَرَ). 1.""رَجُلٌ مَيْسُورُ الْحَالِ"" : لَهُ مِنَ الْمَالِ مَا يَكْفِيهِ لِعَيْشِهِ فِي يُسْرٍ. 2.""عَمَلٌ مَيْسُورٌ"" : سَهْلٌ. ""مِنَ الْمَيْسُورِ أَنْ يُحَقِّقَ هَدَفَهُ"" ""خُذْ مَيْسُورَكَ وَاتْرُكْ مَعْسُورَهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5788, 'مَيَاسِرُ', 'مياسر', 'اسم مفعول', '', 'مياسر', 'مسر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
