INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5790, 'مُيَمَّمٌ', 'ميمم', 'اسم مفعول', 'يمم', 'ميمم', 'مم', 'مفع. من يَمَّمَ', '', 'ة', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(مفع. من يَمَّمَ). ""رَجُلٌ مُيَمَّمٌ"" : الظَّافِرُ بِمَطَالِبِهِ."', '');
