INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5792, 'مَيْؤُوسٌ', 'ميؤوس', 'اسم مفعول', 'يأس', 'ميءوس', 'مس', 'مفع. من يَئِسَ', '', 'ة', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مفع. من يَئِسَ). ""مَرِيضٌ مَيْؤُوسٌ مِنْ شِفَائِهِ"" : لاَ أَمَلَ مِنْ ... """', '');
