INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5796, 'جَوَارِيفُ', 'جواريف', 'جامد', '', 'جواريف', 'جرف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5797, 'تِلِفونٌ', 'تلفون', 'جامد', 'لفن', 'تلفون', 'تلفن', 'اِسْمُ أَداةٍ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تِلِفونٌ-تِلِفونٌ [ل ف ن] (اِسْمُ أَداةٍ). ""رَنَّ جَرَسُ التِّلِفونِ فَرَفَعَ السَّمَّاعَةَ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5798, 'شُورَى', 'شورى', 'جامد', 'شور', 'شورى', 'شر', 'اِسْمٌ بِمَعْنَى التَّشَاوُرُ', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"شُورَى-شُورَى [ش و ر] (اِسْمٌ بِمَعْنَى التَّشَاوُرُ). 1.""جَعَلَ الأَمْرَ بَيْنَهُمْ شُورَى"" : أَيْ جَعَلَ الأَمْرَ للتَّشَاوُرِ وَالاِسْتِمَاعِ إِلَى جَمِيعِ الآرَاءِ مِنْ أَجْلِ الاتِّفَاقِ عَلَى رَأْيٍ. ""كَانَ الْحُكْمُ شُورَى بَيْنَ النَّاسِ فِي صَدْرِ الإسْلاَمِ"". 2.""مَجْلِسُ الشُّورَى"" : مَجْلِسُ التَّشَاوُرِ وَالتَّدَاوُلِ فِي شُؤُونِ البِلاَدِ وَقَضَايَاها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5799, 'مَارَّةٌ', 'مارة', 'جامد', 'مرر', 'مارة', 'مرة', 'اسم جمع مَارُّونَ', '', '', 'مفرد', '', '', '', '"مَارُّون"', '', '', '', '', '', '', '', '', '"مَارَّةٌ-مَارَّةٌ [م ر ر] (اسم جمع مَارُّونَ). ""يُرَاقِبُ الْمَارَّةَ مِنَ الشُّرْفَةِ"" : أَيِ السَّائِرِينَ، العَابِرِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5800, 'مَارُّون', 'مارون', 'جامد', '', 'مارون', 'مرن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5801, 'فَحْشَاءُ', 'فحشاء', 'جامد', 'فحش', 'فحشاء', 'فحش', 'اِسْمٌ لِلْفَاحِشَةِ', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"فَحْشَاءُ-فَحْشَاءُ [ف ح ش] (اِسْمٌ لِلْفَاحِشَةِ). ""نَهَاهُ عَنِ الْفَحْشَاءِ"" : عَنِ الزِّنَى وَكُلِّ مَا يَشْتَدُّ قُبْحُهُ مِنَ الذُّنُوبِ. العنكبوت آية 45إِنَّ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5802, 'جُدَرِيٌّ', 'جدري', 'جامد', 'جدر', 'جدري', 'جدر', 'اِسْمُ مَرَضٍ', '', '', 'مفرد', '', '', '', '', '', 'R0', '', '', '', '', '', '', '"جُدَرِيٌّ-جُدَرِيٌّ [ج د ر] (اِسْمُ مَرَضٍ). ""أَصَابَ جِسْمَهُ الجُدَرِيُّ"" : مَرَضٌ يَظْهَر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5803, 'رُبَاعَ', 'رباع', 'جامد', 'ربع', 'رباع', 'ربع', 'اِسْمٌ مَعْدولٌ عَنْ أرْبَعَة ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', 'N', 'N', 'N', 'N', '', '"رُبَاعٌ-رُبَاعٌ [ر ب ع]. : اِسْمٌ مَعْدولٌ عَنْ أرْبَعَة أرْبَعة، مَمْنُوعٌ مِنَ الصَّرْفِ. ""وَصَلُوا رُبَاعَ"" :أَرْبَعَةً أرْبَعَةًفاطر آية 1 الحَمْدُ لِلَّهِ فاطِرِ السَّماواتِ والأَرْضِ جَاعِلِ الْمَلاَئِكَةِ رُسُلاً أُولِي أَجْنِحَةٍ مَثْنَى وَثُلاَثَ وَرُبَاعَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5804, 'تَقْوَى', 'تقوى', 'جامد', 'وقي', 'تقوى', 'تق', 'اِسْمٌ مِن اتَّقَى', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"تَقْوَى-تَقْوَى [و ق ي] (اِسْمٌ مِن اتَّقَى). 1.""كانَ رَجُلاً وَرِعاً شَديدَ التَّقْوَى"" : شَديدَ التَّنَسُّكِ وَالعِبَادَةِ وَمَخافَةِ اللَّهِ وَاحْتِرَامِ الشَّرِيعَةِ. 2. لاَفَرْقَ بَيْنَ عَرَبِيٍّ وَأَعْجَمِيٍّ إِلاَّ بِالتَّقْوَى . (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5805, 'سَقَرُ', 'سقر', 'جامد', 'سقر', 'سقر', 'سقر', 'اِسْمٌ مِنْ أسْمَاءِ جَهَنَّمَ', '', '', 'مفرد', 'DnN', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'N', 'O', 'O', '', '"سَقَرُ-سَقَرُ [س ق ر]. : اِسْمٌ مِنْ أسْمَاءِ جَهَنَّمَ. القمر آية 48 ي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5806, 'قُشَعْرِيرَةٌ', 'قشعريرة', 'جامد', 'قشعر', 'قشعريرة', 'قشعررة', 'اِسْمٌ مِن اِقْشَعَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قُشَعْرِيرَةٌ-قُشَعْرِيرَةٌ [ق ش ع ر] ( اِسْمٌ مِن اِقْشَعَرَّ). 1.""أَخَذَتْهُ قُشَعْرِيرَةٌ"" : رِعْدَةٌ تَدُلُّ عَلَى بِدَايَةِ أَعْرَاضِ الْحُمَّى. 2.""أَحَسَّ بِقُشَعْرِيرَةٍ"" : بِارْتِجَافٍ، اِقْشِعْرَارٍ. ""ولَمْ تَتَمَالَكِ الانْتِفَاضَ من قُشَعْرِيرَةٍ طَفَتْ بِقُوَّةٍ عَلَى جِلْدِهَا"". (أحمد التوفيق)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5807, 'تُهْمَةٌ', 'تهمة', 'جامد', 'وهم', 'تهمة', 'تهمة', 'اِسْمٌ مِنَ الاتِّهَامِ', '', '', 'مفرد', 'DnN', '', 'Pf', '"تُهَمٌ"', '', '', '', '', '', '', '', '', '"(اِسْمٌ مِنَ الاتِّهَامِ). ""أُلْصِقَتْ بِهِ تُهْمَةٌ هُوَ بَريءٌ مِنْهَا"" : مَا يُتَّهَمُ بِهِ الْمَرْءُ مِنْ فِعْلٍ إلَى أنْ يَثْبُتَ اتِّهَامهُ أوْ بَرَاءتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5808, 'تُهَمٌ', 'تهم', 'جامد', '', 'تهم', 'تهم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5809, 'حَرِيقٌ', 'حريق', 'جامد', 'حرق', 'حريق', 'حرق', 'اِسْمٌ مِنَ الاِحْتِرَاقِ', '', '', 'مفرد', 'DnN', '', '', '"حَرْقى"', '', '', '', '', '', '', '', '', '"(اِسْمٌ مِنَ الاِحْتِرَاقِ). ""شَبَّ حَرِيقٌ فِي الْمَعْمَلِ"" : اِشْتِعالُ النَّارِ واضْطِرَامُها.¨ ""أسْرَعَ رِجَالُ الْمَطافِئِ لإطْفَاءِ الحَرِيقِ"" ""لِكُلِّ حَرِيقٍ مُطْفِئٌ"" .(ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5810, 'حَرْقى', 'حرقى', 'جامد', '', 'حرقى', 'حرق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5811, 'نَفَقَةٌ', 'نفقة', 'جامد', 'نفق', 'نفقة', 'نفقة', 'اِسْمٌ مِنَ الْإِنْفَاقِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(اِسْمٌ مِنَ الْإِنْفَاقِ). 1.""نَفَقَةُ الْمَعِيشَةِ"" : مَا يُنْفَقُ، يُصْرَفُ مِنَ الدَّرَاهِمِ لِأَجْلِ... ""نَفَقَةُ الْأُسْرَةِ"". 2.""أَقَامَ ضِيَافَةً عَلَى نَفَقَتِهِ"" : عَلَى حِسَابِهِ. 3.""جَهَّزَ نَفَقَةَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5812, 'نَكِرَةٌ', 'نكرة', 'جامد', 'نكر', 'نكرة', 'نكرة', 'اِسْمٌ مِنَ الإِنْكَارِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(اِسْمٌ مِنَ الإِنْكَارِ). 1.""اِسْمٌ نَكِرَةٌ"" (نح) : هُوَ الاِسْمُ الَّذِي يَدُلُّ عَلَى مُسَمّىً شَائِعٍ فِي جِنْسٍ مَوْجُودٍ أَوْ مُقَدَّرٍ. (كِتَابٌ، رَجُلٌ، شَجَرَةٌ). 2.""هُوَ نَكِرَةٌ وَسَطَ قَوْمِهِ"" : غَيْرُ مَعْرُوفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5813, 'ذَفافٌ', 'ذفاف', 'جامد', 'ذفف', 'ذفاف', 'ذفف', 'اِسْمٌ مِنَ الذَّفِّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ذَفافٌ-ذَفافٌ [ذ ف ف] (اِسْمٌ مِنَ الذَّفِّ). ""ما ذاقَ ذَفافاً"" : شَيْئاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5814, 'سُقْيَا', 'سقيا', 'جامد', 'سقي', 'سقيا', 'سق', 'اِسْمٌ مِن السَّقْيِ', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"سُقْيَا-سُقْيَا [س ق ي] (اِسْمٌ مِن السَّقْيِ). ""سُقْيَا رَحْمَةٍ لاَ سُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5815, 'غَزَاةٌ', 'غزاة', 'جامد', 'غزو', 'غزاة', 'غزة', 'اِسْمٌ مِنَ الغَزْوِ', '', '', 'مفرد', '', '', '', '"غزوات"', '', 'Rw', '', '', '', '', '', '', '"(اِسْمٌ مِنَ الغَزْوِ). إِذَا قِيلَ: ""غَزَاةٌ""، فَهُوَ عَمَلُ س"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5816, 'غَزَواتٌ', 'غزوات', 'جامد', '', 'غزوات', 'غزت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5817, 'لُعْبَةٌ', 'لعبة', 'جامد', 'لعب', 'لعبة', 'لعبة', 'اِسْمٌ مِنَ اللَّعِبِ', '', '', 'مفرد', 'DnN', '', 'Pf', '":لُعَبٌ"', '', 'R', '', '', '', '', '', '', '"(اِسْمٌ مِنَ اللَّعِبِ). 1.""أَهْدَى لابْنَتِهِ لُعْبَةً"" : دُمْيَةً. 2. أَوْ كُلُّ مَا يَلْعَبُ بِهِ الأَطْفَالُ. ""يُجِيدُ لُعْبَةَ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5818, 'لُعَبٌ', 'لعب', 'جامد', '', 'لعب', 'لعب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5819, 'تِلْقاءٌ', 'تلقاء', 'جامد', 'لقي', 'تلقاء', 'تلق', 'اِسْمٌ مِنَ اللِّقاءِ', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"تِلْقاءٌ-تِلْقاءٌ [ل ق ي] (اِسْمٌ مِنَ اللِّقاءِ). 1.""جَلَسَ تِلْقاءَهُ"" : مُقابِلاً لَهُ، تُجاهَهُ. 2.""قامَ بِمَهامِّهِ مِنْ تِلْقاءِ نَفْسِهِ"" : دو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5820, 'لَمْحَةٌ', 'لمحة', 'جامد', 'لمح', 'لمحة', 'لمحة', 'اِسْمٌ مِنَ اللَّمْحِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"لَمْحَةٌ-لَمْحَةٌ [ل م ح] (اِسْمٌ مِنَ اللَّمْحِ). 1.""رَأَيْتُهُ فِي لَمْحَةِ الْبَرْقِ"" : فِي قَدْرِ لَمْحَةِ الْبَرْقِ، نَظْرَة سَرِيعَة جِدّاً. 2.""فِيهِ لَمْحَةٌ مِن أُمِّهِ"" : شَبَهٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5821, 'شَتِيمَةٌ', 'شتيمة', 'جامد', 'شتم', 'شتيمة', 'شتمة', 'اِسْمٌ مِنْ شَتَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '"شَتَائِمُ"', '', '', '', '', '', '', '', '', '"(اِسْمٌ مِنْ شَتَمَ). ""تَلَقَّى م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5822, 'شَتَائِمُ', 'شتائم', 'جامد', '', 'شتاءم', 'شتم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5823, 'عَدَدٌ', 'عدد', 'جامد', 'عدد', 'عدد', 'عد', 'اِسْمٌ مِنْ عَدَّ', '', '', 'مفرد', 'DnN', '', '', '"أَعْدَادٌ"', '', 'R', '', '', '', '', '', '', '"(اِسْمٌ مِنْ عَدَّ). 1. مَجْمُوعُ مِقْدَارِ الْكَمِّيَّةِ الَّتِي تُعَدُّ، مَحْصُولُهَا. ""عَدَدُ الْحَاضِرِينَ"" ""عَدَدٌ كَبِيرٌ مِنَ النَّاسِ"" ""عَدَدُ السُّكَّانِ"". 2.""الْعَدَدُ الأَصْلِيُّ"" : مَا يَدُلُّ عَلَى مِقْدَارِ الأَشْيَاءِ الْمَعْدُودَةِ. 3.""عَدَدٌ أَوَّلِيٌّ"" : مَا لاَ يَقْبَلُ الْقِسْمَةَ إِلاَّ عَلَى نَفْسِهِ أَوْ عَلَى الْوَاحِدِ الصَّحِيحِ (مثل 3، 5، 7، 11). 4.""عَدَدٌ تَرْتِيبِيٌّ"" : مَا يَدُلُّ عَلَى تَرْتِيبِ الأَشْيَاءِ (أَوَّلٌ، ثَانِ، ثَالِثٌ، رَابِعٌ، خَامِسٌ...). 5.""الْعَدَدُ التَّامُّ "" : أَيْ الصَّحِيحُ الْمُسَاوِي لِمَجْمُوعِ الأَعْدَادِ الَّتِي يُقْسَمُ عَلَيْهَا. 6.""الْعَدَدُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5824, 'أَعْدَادٌ', 'أعداد', 'جامد', '', 'ءعداد', 'عدد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5825, 'غُسْلٌ', 'غسل', 'جامد', 'غسل', 'غسل', 'غسل', 'اِسْمٌ مِنْ غَسَلَ', '', '', 'مفرد', 'DnN', '', '', '"أَغْسَالٌ"', '', 'R', '', '', '', '', '', '', '"(اِسْمٌ مِنْ غَسَلَ). ""الغُسْلُ وَاجِبٌ لأَدَاءِ الصَّلاَةِ"" : إِفَاضَةُ الْمَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5826, 'أَغْسَالٌ', 'أغسال', 'جامد', '', 'ءغسال', 'غسل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5827, 'قَرْصَنَةٌ', 'قرصنة', 'جامد', 'قرصن', 'قرصنة', 'قرصنة', 'اسْم مِنْ قُرْصَانٍ.', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '": (اسْم مِنْ قُرْصَانٍ). 1.""نَشِطَتِ القَرْصَنَةُ عَلَى الشَّوَاطِئِ قَدِيماً"" : التَّعَرُّضُ لِلسُّفُنِ وَحَجْزُهَا عَلَى ي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5828, 'رَهْبَنَةٌ', 'رهبنة', 'جامد', 'رهب', 'رهبنة', 'رهبنة', 'اِسْمٌ مِنْ مَعْنَى الرَّاهِبِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"رَهْبَنَةٌ-رَهْبَنَةٌ [ر هـ ب] (اِسْمٌ مِنْ مَعْنَى الرَّاهِبِ). : طَريقَةُ الرُّهْبانِ وَاتِّخاذُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5829, 'نُهْبَةٌ', 'نهبة', 'جامد', 'نهب', 'نهبة', 'نهبة', 'اِسْمٌ مِنْ نَهَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نُهْبَةٌ-نُهْبَةٌ [ن هـ ب] (اِسْمٌ مِنْ نَهَبَ). ""وَزَّعُوا النُّهْبَةَ"" : الْغَنِيمَة الَّتِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5830, 'مِيتَةٌ', 'ميتة', 'جامد', 'موت', 'ميتة', 'متة', 'اِسْمُ هَيْئَةٍ مِنْ مَاتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مِيتَةٌ-مِيتَةٌ [م و ت] (اِسْمُ هَيْئَةٍ مِنْ مَاتَ). ""مَاتَ الرَّجُلُ مِيتَةً رَضِيَّةً"" : أَيْ جَاءَ مَوْتُهُ فِي حَالَةٍ رَضِيَّةٍ. ""ماتَ مِيتَةَ الأَبْطالِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5831, 'عَنَنٌ', 'عنن', 'جامد', 'عنن', 'عنن', 'عن', 'اِسْمٌ ومص مِنْ عَنَّ', '', '', 'مفرد', 'DnN', '', '', '"أَعْنَانٌ"', '', 'R', '', '', '', '', '', '', '"(اِسْمٌ ومص مِنْ عَنَّ). بِمَعْنَى ظَهَرَ، اِعْتَرَضَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5832, 'أَعْنَانٌ', 'أعنان', 'جامد', '', 'ءعنان', 'عنن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5833, 'رَسُولٌ', 'رسول', 'جامد', 'رسل', 'رسول', 'رسل', 'الاسْمُ مِنْ أَرْسَلَ', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"رُسُلٌ"', '', 'R', '', '', '', '', '', '', '"(الاسْمُ مِنْ أَرْسَلَ) (لِلْمُذَكَّرِ وَالْمُؤَنَّثِ وَالوَاحِدِ وَالجَمْعِ). الْمُرْسَلُ. 1. ""بَعَثَ اللَّهُ النَّبِيَّ مُحَمَّداً ( رَسُولاً لِلنَّاسِ كَافَّةً"" : مُبَلِّغاً بِشَرْعِهِ وَرِسَالَتِهِ. وَقَدْ أضْحَتْ كَلِمَةُ ""رَسُول"" لَقَباً لِلنَّبِيِّ مُحَمَّدٍ : ""رَسُولُ اللَّهِ"".آل عمران آية 144 وَمَا مُحَمَّدٌ إلاَّ رَسُولٌ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُ (قرآن). 2.""تَعَالِيمُ رُسُلِ المسِيحِ"" : الَّذِينَ بشَّرُوا بِالإِنْجِيلِ الْمُقَدَّسِ، أيِ الحَوَارِيُّونَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5834, 'رُسُلٌ', 'رسل', 'جامد', '', 'رسل', 'رسل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5835, 'رِسَالَةٌ', 'رسالة', 'جامد', 'رسل', 'رسالة', 'رسلة', 'الاسْمُ مِنْ أرْسَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":رَسَائِلُ"', '', 'R', '', '', '', '', '', '', '"(الاسْمُ مِنْ أرْسَلَ). 1.""كَتَبَ رِسَالَةً لأهْلِهِ"" : مَا يَكْتُبُهُ الْمُرْسِلُ على ظَهْرِ وَرَقَةٍ مِنْ أَخْبارٍ وَمَعْلوماتٍ فَيُرْسِلُها إلَى الْمُرْسَلِ إلَيْهِ بِوَاسِطَةِ البَرِيدِ، الخِطَابُ. 2.""رِسَالَةٌ شَفَوِيَّةٌ"" : كَلاَمٌ يَبُثُّهُ شَخْصٌ مَّا لِيَنْقُلَهُ شَفَوِيّاً إلَى شَخْصٍ آخَرَ. 3.""رِسَالَةُ الرَّسُولِ"" : دَعْوَتُهُ لِلنَّاسِ بِمَا أُمِرَ بِهِِ وَأُوحِيَ إلَيْهِ. 4.""أدَّى الْمُصْلِحُ رِسَالَتَهُ"" : وَاجِبَهُ وَمَا يُحاوِلُهُ مِنْ إصْلاحٍ. 5.""رِسَالَةٌ جَامِعِيَّةٌ"" : بَحْثٌ في مَوْضُوعٍ جَدِيدٍ، أُطْرُوحَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5836, 'رَسَائِلُ', 'رسائل', 'جامد', '', 'رساءل', 'رسل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5837, 'خِيَارٌ', 'خيار', 'جامد', 'خير', 'خيار', 'خر', 'الاسْمُ مِنَ الاخْتِيَارِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خِيَارٌ-خِيَارٌ [خ ي ر] (الاسْمُ مِنَ الاخْتِيَارِ). 1. ""كَانَ أَمَامَ خِيَارٍ"" : أَمَامَ اخْتِيَارٍ بَيْنَ شَيْئَيْنِ أَيُّهُمَا أفضَلُ. ""لَكَ الخِيَارُ بَيْنَ البَقَاءِ أَوِ الذَّهَابِ"". 2. ""هُوَ مِنْ خِيَارِ النَّاسِ"" : مِنْ أفْضَلِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5838, 'رِدَّةٌ', 'ردة', 'جامد', 'ردد', 'ردة', 'ردة', 'الاسْمُ مِنَ الارْتِدَادِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"رَدَّةٌ-رَدَّةٌ [ر د د] (الْمَرَّةُ مِنْ رَدَّ). 1.""لَهُ رَدَّةٌ"" : رُجُوعٌ، عَطْفَةٌ. 2.""بِهِ رَدَّةٌ "" : عَيْبٌ أوْ قُبْحٌ مَعَ شَيْءٍ مِنَ الجَمَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5839, 'سَرَاحٌ', 'سراح', 'جامد', 'سرح', 'سراح', 'سرح', 'الاسْمُ مِنَ التَّسْرِيحِ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَرَاحٌ-سَرَاحٌ [س ر ح] (الاسْمُ مِنَ التَّسْرِيحِ). ""أُطْلِقَ سَرَاحُهُ بَعْدَ سَنَوَاتٍ مِنَ السَّجْنِ"" : أُفْرِجَ عَنْهُ، أُخْلِيَ سَبِيلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5840, 'نُزْهَةٌ', 'نزهة', 'جامد', 'نزه', 'نزهة', 'نزهة', 'الاسْمُ مِنَ التَّنَزُّهِ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نُزَهٌ"', '', 'R', '', '', '', '', '', '', '"(الاسْمُ مِنَ التَّنَزُّهِ). ""خَرَجَ إِلَى النُّزْهَةِ"" : خَرَجَ لِلتَّفَسُّحِ وَالرَّاحَةِ فِي الطَّبِيعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5841, 'نُزَهٌ', 'نزه', 'جامد', '', 'نزه', 'نزه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5842, 'رُجُولَةٌ', 'رجولة', 'جامد', 'رجل', 'رجولة', 'رجلة', 'الاسْمُ مِنَ الرَّجُلِ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رُجُولَةٌ-رُجُولَةٌ [ر ج ل] (الاسْمُ مِنَ الرَّجُلِ). 1.""رُجُولَةٌ نَادِرَةٌ"" : كَمَالُ الصِّفَاتِ الْمُمَيِّزَةِ لِلرَّجُلِ، الرُّجُولِيَّةُ. 2.""أظْهرَ رُجُولَةً كَبِيرَةً فِي الْمَعْرَكَةِ"" : قُوَّةً، شَجَاعَةً، حِنْكَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5843, 'لُقْيَا', 'لقيا', 'جامد', 'لقى', 'لقيا', 'لق', 'الاسْمُ مِنَ اللِّقَاءِ', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"لُقْيَا-لُقْيَا [ل ق ى] (الاسْمُ مِنَ اللِّقَاءِ). ""بِمُجَرَّد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5844, 'آهَةٌ', 'آهة', 'جامد', 'أوي', 'ءاهة', 'آهة', 'الاسْمُ مِنَ تَأَوَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الاسْمُ مِنَ تَأَوَّهَ): الصَّوْتُ الصَّادِرُ عَنِ الإنْسَانِ وَهُوَ فِي حَالَةِ الألَمِ أوِ الشَّكْوَى أوِ التَّوَجُّع."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5845, 'زِينَةٌ', 'زينة', 'جامد', 'زين', 'زينة', 'زنة', 'الاسْمُ مِنْ تَزَيَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":زِيَنٌ"', '', 'R', '', '', '', '', '', '', '"(الاسْمُ مِنْ تَزَيَّنَ). 1.""أَظْهَرَ الشَّعْبُ مَظاهِرَ الزِّينَةِ"" : مَظاهِرَ الفَرَحِ، وَذَلِكَ بارْتِداءِ أَفْخَرِ الْمَلابِسِ وَتَزْيِينِ أَسْواقِ الْمَدينَةِ وَشَوارِعِها وَمَنازِلِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5846, 'زِيَنٌ', 'زين', 'جامد', '', 'زين', 'زن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5847, 'حِجَّةٌ', 'حجة', 'جامد', 'حجج', 'حجة', 'حجة', 'الاسْمُ مِنْ حَجَّ', '', '', 'مفرد', 'DnN', '', '', '"حِجَجٌ"', '', 'R', '', '', '', '', '', '', '"(الاسْمُ مِنْ حَجَّ). 1.""في تِلْكَ الحِجَّةِ"" : تِلْكَ السَّنَةِ، لأَنَّ الحَجَّ يُقْضَىكُلَّ سَنَةٍ. 2.""ذو الحِجَّةِ هُوَ شَهْرُ الحَجِّ"" : مِنَ الشُّهورِ القَمَرِيَّةِ وَهُوَ آخِرُها، أي الشَّهْرُ الثَّانِي عَشَرَ، عَدَدُ أَيَّامِهِ (29) أَوْ (30) يَوْماً، يَأْتِي بَعْدَ ذِي القِعْدَةِ وَيَليهِ مُحَرَّم."', '');
