INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5849, 'حُنْكَةٌ', 'حنكة', 'جامد', 'حنك', 'حنكة', 'حنكة', 'الاِسْمُ مِنْ حَنَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حُنْكَةٌ-حُنْكَةٌ [ح ن ك] (الاِسْمُ مِنْ حَنَّكَ). ""أظْهَرَ حُنْكَةً"": مَقْدُرَةً، قُوَّةً مُتَبَصِّرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5850, 'سيرَةٌ', 'سيرة', 'جامد', 'سير', 'سيرة', 'سرة', 'الاسْمُ مِنْ سارَ', '', '', 'مفرد', 'DnN', '', '', '"سِيَرٌ"', '', 'R', '', '', '', '', '', '', '"(الاسْمُ مِنْ سارَ). 1.""سَنَّ سِيرَةً يَسيرُ على خُطاها"" : سُنَّةً، خُطَّةً. 2.""قَرَأَ نَصّاً مِنَ السِّيرَةِ النَّبَوِيَّةِ"" : نَصّاً مِنْ حَياةِ الرَّسولِ وَأَعْمالِهِ وَغَز"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5851, 'سِيَرٌ', 'سير', 'جامد', '', 'سير', 'سر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5852, 'سَكْتَةٌ', 'سكتة', 'جامد', 'سكت', 'سكتة', 'سكتة', 'الاسْمُ مِنْ سَكَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَكْتَةٌ-سَكْتَةٌ [س ك ت] (الاسْمُ مِنْ سَكَتَ). ""تُوُفِّيَ عَلَى إثْرِ سَكْتَةٍ قَلْبِيَّةٍ"" : تَوَقّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5853, 'نُدْبَةٌ', 'ندبة', 'جامد', 'ندب', 'ندبة', 'ندبة', 'الاسْمُ مِنْ نَدَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُدْبَةٌ-نُدْبَةٌ [ن د ب] (الاسْمُ مِنْ نَدَبَ). 1.""حَضَرُوا نُدْبَةَ الْمَيِّتِ"" : تَعْدَادُ مَنَاقِبِ الْمَيِّتِ وَمَحَاسِنُهُ. 2."" وَاحَرَّ قَلْبَاهُ مِمَّنْ قَلْبُهُ شَبِمُ"". (المتنبي) : ""وَا"" حَرْفُ نِدَاءٍ يُسْتَعْمَلُ فِي النُّدْبَةِ لِلْمُتَفَجَّعِ عَلَيْهِ أَوِ الْمُتَوَجَّعِ مِنْهُ. 3.""عَرَبِيٌّ نُدْبَةٌ"" : فَصِيحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5854, 'وَدَاعٌ', 'وداع', 'جامد', 'ودع', 'وداع', 'دع', 'الِاسْمُ مِنْ وَدَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَدَاعٌ-وَدَاعٌ [و د ع] (الِاسْمُ مِنْ وَدَّعَ). 1.""مَا أَقْسَى لَحْظَةَ الوَدَاعِ"" : اللَّحْظَةُ الَّتِي يُوَدِّعُ فِيهَا الْمَرْءُ أَهْلَهُ وَأَصْحَـابَهُ.‎ 2.""أَقَامُوا حَفْلَةَ وَدَاعٍ عَلَى شَرَفِهِ"" : أَيِ الْحَفْلُ "', '');
