INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5859, 'أكَّارَةٌ', 'أكارة', 'جامد', 'أكر', 'ءكارة', 'كرة', 'آلَةٌ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '".: آلَةٌ تُحْفَرُ بِهَا التُّرَعُ وَالأَنْهَارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5860, 'بَوْصَلَةٌ', 'بوصلة', 'جامد', '', 'بوصلة', 'بصلة', 'آلَةٌ ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '": آلَةٌ مُكَوَّنَةٌ أسَاساً مِن عَقْرَبٍ مُمَغْنَطٍ يَتَمَحْوَرُ حَوْلَ مَدَارٍ يَسْمَحُ اتِّجَاهُهُ بِمَعْرِفَةِ نَاحِيَةِ الشَّمَالِ. والعَربُ أوَّلُ مَـنِ اسْتَعْمَـلَهَـا بَعْـدَ الصِّينيِّينَ، وانْتَقَلَ اسْتِعْمَالُهَا بَعْدَ ذَلِكَ إلَى أُورُوبَّا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5861, 'بِيَانُو', 'بيانو', 'جامد', '', 'بيانو', 'بن', 'آلَةٌ ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', 'N', 'O', 'N', 'O', '', '": آلَةٌ مُوسِيقِيَّةٌ تَتَضَمَّنُ مَجْمُوعَةً مِنَ الْمَلاَمِسِ تَشُدُّهَا أوْتَارٌ بِدَاخِلِ صُنْدُوقٍ، يَنْقُرُ عَلَيْهَا العَازِفُ بِأنَامِلِهِ فَتَنْبَعِثُ مِنْهَا أصْوَاتٌ مُوسِيقِيَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5862, 'تِرْمُومِتْر', 'ترمومتر', 'جامد', '', 'ترمومتر', 'ترممتر', 'آلَةٌ ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', 'N', 'O', 'N', 'O', '', '": آلَةٌ عَلَى شَكْلِ قَلَمٍ مُسَطَّحٍ تُسْتَعْمَلُ لِبَيَانِ دَرَجَةِ الحَرَارَةِ، مِقْيَاسُ الحَرَارَةِ."', ':لا جذر:لا مفرد');
