INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5940, 'لِينُوتِيب', 'لينوتيب', 'جامد', '', 'لينوتيب', 'لنتب', 'آلَةٌ ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', 'N', 'O', 'N', 'O', '', '": آلَةٌ طِبَاعِيَّةٌ للِتَّصْفِيفِ مِيكَانِيكِيَّةٌ، لَهَا مَلاَمِسُ الْآلَةِ الْكَاتِبَةِ لِسَبْكِ سُطُورٍ تَظْهَرُ فِي قَوَالِبَ كَامِلَةٍ وَمُتَنَاسِقَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5941, 'مِشْطٌ', 'مشط', 'جامد', 'مشط', 'مشط', 'مشط', 'آلَةٌ ', '', '', 'مفرد', 'DnN', '', '', '"أَمْشَاطٌ"', '', 'R', '', '', '', '', '', '', '".: آلَةٌ مِنْ عَظْمٍ وَنَحْوِهِ، ذَاتُ أَسْنَانٍ يُسَرَّحُ بِهَـا الشَّعْـرُ. النَّاسُ سَوَاسِيَةٌ كَأَسْنَانِ الْمِشْطِ . (حديث)."', '');
