INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5943, 'نَارَجِيلَةٌ', 'نارجيلة', 'جامد', '', 'نارجيلة', 'نرجلة', 'آلَةٌ ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '": آلَةٌ لَهَا أُنْبُوبٌ طَوِيلٌ مُلْتَصِقٌ بِقِنِّينَةٍ بِهَا مَاءٌ وَهِيَ مَفْتُوحَةٌ عَلَى رَأْسِ غَلْيُونٍ، يُدَخَّنُ بِهَا التَّنْكُ، تُسْتَعْمَلُ بِكَثْرَةٍ بِبُلْدَانِ الشَّرْقِ العَرَبِيِّ."', ':لا جذر:لا مفرد');
