INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5949, 'نَوَاظِيرُ', 'نواظير', 'جامد', '', 'نواظير', 'نظر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5950, 'رَاوِيَةٌ', 'راوية', 'جامد', 'روي', 'راوية', 'رة', 'التَّاءُ للمُبَالَغَةِ', '', '', 'مفرد', 'DnN', '', 'Pf', '"رَوَايا"', '', '', '', '', '', '', '', '', '"(التَّاءُ للمُبَالَغَةِ). 1.""رَجُلٌ رَاوِيَةٌ"" : كَثيرُ الرِّوَايَةِ، رَاوِي الحَدِيثِ أوِ الشِّعْرِ. 2.""راوِيَةُ"" : اِسْمُ عَلَمٍ لِلإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5951, 'رَوَايا', 'روايا', 'جامد', '', 'روايا', 'ر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5952, 'مَرَّةٌ', 'مرة', 'جامد', 'مرر', 'مرة', 'مرة', 'الفَعْلَةُ الوَاحِدَةُ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مِرَارٌ"', '', '', '', 'N', 'O', 'N', 'O', '', '"(الفَعْلَةُ الوَاحِدَةُ). 1.""اِسْمُ الْمَرَّةِ"" : هُوَ الْمَصْدَرُ يُقْصَدُ بِهِ الْمَرَّةُ الوَاحِدَةُ مِنْ وُقُوعِ الفِعْلِ: ""أَكَلَ أَكْلَةً"" : أَكْلَةً : اِسْمُ مَرَّةٍ. 2.""لَقِيتُهُ مَرَّةً"" : أَيْ لَقِيتُهُ لِقَاءً وَاحِداً. ""ذَاتَ مَرَّةٍ"" ""الْمَرَّةَ تِلْوَ الْمَرَّةِ"" ""فِي كُلِّ مَرَّةٍ"" ""فِي آخِرِ مَرَّةٍ"" ""لِأَوَّلِ مَرَّةٍ"" ""أَكْثَر مِنْ مَرَّةٍ"" ""زُرْتُهُ مَرَّاتٍ كَثِيرَةً"". 3.""نَبَّهْتُهُ مِرَاراً"" : وَهُنَا اسْتِعْمَالُ الجَمْعِ لِلدّلاَلَةِ عَلَى الكَثْرَةِ. ""مِرَاراً وَتَكْرَاراً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5953, 'مِرَارٌ', 'مرار', 'جامد', '', 'مرار', 'مرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5954, 'فِيئَةٌ', 'فيئة', 'جامد', 'فيأ', 'فيءة', 'فة', 'النَّوْعُ مِنْ فَاءَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فَيْئَةٌ-فَيْئَةٌ [ف ي أ] (الْمَرَّةُ مِنْ فَاءَ). 1.""فَاءَ إِلَى اللَّهِ فَيْئَةً حَسَنَةً"" : تَابَ تَوْبَةً حَسَنَةً بِمَعْنَى الرّجْعَةِ. 2.""جَاءَ بَعْدَ فَيْئَةٍ"" : بَعْدَ حِينٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5955, 'فِرْشَةٌ', 'فرشة', 'جامد', 'فرش', 'فرشة', 'فرشة', 'النَّوْعُ مِنْ فَرَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فِرْشَةٌ-فِرْشَةٌ [ف ر ش] (النَّوْعُ مِنْ فَرَشَ). ""هُوَ حَسَنُ الفِرْشَةِ"" : الْهَيْئَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5956, 'قِيمَةٌ', 'قيمة', 'جامد', 'قوم', 'قيمة', 'قمة', 'النَّوْعُ مِنْ قَامَ', '', '', 'مفرد', 'DnN', '', '', '"قِيَمٌ"', '', 'R', '', '', '', '', '', '', '"(النَّوْعُ مِنْ قَامَ). 1.""لِلْعَمَلِ قِيمَةٌ لاَ تُقَدَّرُ"" : شَأْنٌ رَفِيعٌ، مَكَانَةٌ مُهِمَّةٌ. ""قِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5957, 'قِيَمٌ', 'قيم', 'جامد', '', 'قيم', 'قم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5958, 'هِينَةٌ', 'هينة', 'جامد', 'هون', 'هينة', 'هنة', 'النَّوْعُ مِنْ هَانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هِينَةٌ-هِينَةٌ [هـ و ن] (النَّوْعُ مِنْ هَانَ). 1.""فِي هِينَةٍ مِنْ أَمْرِهِ"" : فِي سَكِينَةٍ وَهُدُوءٍ، فِي تَمَهُّلٍ. 2.""اِمْشِ عَلَى هِينَتِكَ"" : عَلَى رِسْلِكَ. ""هُوَ يَمْشِي عَلَى هِينَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5959, 'حِرْباءةٌ', 'حرباءة', 'جامد', 'حرب', 'حرباءة', 'حربة', 'أُنْثَى الحِرْباءِ.', '', '', 'مفرد', 'DnN', '', '', '"حَرابِيُّ"', '', '', '', '', '', '', '', '', '".: أُنْثَى الحِرْباءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5960, 'حَرابِيُّ', 'حرابي', 'جامد', '', 'حرابي', 'حرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5961, 'عَرَاقِيلُ', 'عراقيل', 'جامد', 'عرقل', 'عراقيل', 'عرقل', 'بِصِيغَةِ الْجَمْعِ', '', '', 'مفرد', '', '', '', '"(بِصِيغَةِالْجَمْعِ)"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَرَاقِيلُ-عَرَاقِيلُ [ع ر ق ل] (بِصِيغَةِ الْجَمْعِ). ن. عَرْقَلَةٌ. ""وَاجَهَ العَرَاقِيلَ"" : الصِّعَابَ، الْمَشَاكِلَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5962, 'تَبَاشِيرُ', 'تباشير', 'جامد', 'بشر', 'تباشير', 'تبشر', 'بِصِيغَةِ الجَمْعِ', '', '', 'مفرد', '', '', '', '"(بِصِيغَةِالْجَمْعِ)"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"تَبَاشِيرُ-تَبَاشِيرُ [ب ش ر] (بِصِيغَةِ الجَمْعِ). ""وَعَلَتْ زَقْزَقَةُ الع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5963, 'أَسَارِيرُ', 'أسارير', 'جامد', 'سرر', 'ءسارير', 'سرر', 'بِصِيغَةِ الجَمْعِ', '', '', 'مفرد', '', '', '', '"(بِصِيغَةِالْجَمْعِ)"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَسَارِيرُ-أَسَارِيرُ [س ر ر] (بِصِيغَةِ الجَمْعِ). 1.""تَطَلَّعَتْ فِي أَسَارِيرِ كَفِّهِ"" : فِي خُطُوطِهَا. 2.""كَانَتْ أَسَارِيرُ وَجْهِهِ تُعَبِّرُ عَنِ الاِرْتِيَاحِ"" : خُطُوطُ الوَجْهِ وَمَا تُعَبِّرُ عَنْهُ مِنْ مَحَاسِنَ. ويقال أَيْضاً أسَارِيرُ الوَجْهِ والجبْهَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5964, 'أقْدَمُونَ', 'أقدمون', 'جامد', 'قدم', 'ءقدمون', 'قدمن', 'بصِيغَةِ الجَمْعِ', '', '', 'مفرد', '', '', '', '"(بِصِيغَةِالْجَمْعِ)"', '', '', '', '', '', '', '', '', '"أقْدَمُونَ-أقْدَمُونَ [ق د م] (بصِيغَةِ الجَمْعِ). ""هَذَا ما كانَ يَعْتَقِدُهُ آبَاؤُنا الأقْدَمُونَ"" : جُدُودُنَا الأَوائِلُ.الشعراء آية 76 أنْتُمْ وَآباؤُكُم الأقْدَمونَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5965, 'سُوقٌ', 'سوق', 'جامد', 'سوق', 'سوق', 'سق', 'تُذَكَّرُ وَتُؤَنَّثُ', '', '', 'مفرد', 'DnN', '', '', '"أَسْواقٌ"', '', 'R', '', '', '', '', '', '', '"(تُذَكَّرُ وَتُؤَنَّثُ). 1.""وَصَلَتْ بَضائِعُ جَديدَةٌ إلى السُّوقِ"" : مَوْضِعُ بَيْعِ، شِراءِ البَضائِعِ، أَيْ مُخْتَلِفِ الْمَوادِّ التِّجارِيَّةِ : ""سوقُ الخُضَرِ""، ""السُّوقُ الْمَرْكَزِيُّ"". 2.""يَتَذَمَّرُ التُّجَّارُ مِنْ كَسادِ السُّوقِ"" : مِنْ كَسادِ البَيْعِ والشِّراءِ. 3.""السُّوقُ السَّوْداءُ"" : كِنايَةٌ عَنِ التَّعامُلِ بَيْعاً وَشِراءً خُفْيَةً وَخارِجَ القَوانينِ الجَارِي بِها العَمَلُ في الْمَجالِ التِّجارِيِّ. 4.""السُّوقُ الحُرَّةُ"" : مَك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5966, 'أَسْواقٌ', 'أسواق', 'جامد', '', 'ءسواق', 'سق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5967, 'تُوَيْجٌ', 'تويج', 'جامد', 'توج', 'تويج', 'تج', 'تَصْغيرُ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تُوَيْجٌ-تُوَيْجٌ [ت و ج]. 1.: تَصْغيرُ التَّاجِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5968, 'دُوَيْلة', 'دويلة', 'جامد', 'دول', 'دويلة', 'دلة', 'تَصْغيرُ ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"دُوَيْلاتٌ-دُوَيْلاتٌ [د و ل].: تَصْغيرُ الدُّوَلِ، أَي الدُّوَلُ الصَّغيرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5969, 'زُرَيْقٌ', 'زريق', 'جامد', 'زرق', 'زريق', 'زرق', 'تَصْغيرُ ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"زُرَيْقٌ-زُرَيْقٌ[ز ر ق]. 1.: تَصْغيرُ أَزْرَق. 2.: طائِرٌ مِنْ فصيلَةِ الغُرابِيَّاتِ، مِنَ الْجَواثِمِ، لَهُ رِيشٌ أَسْمَرُ مَفْتوحٌ، تَتَخَلَّلُهُ نِقاطٌ زَرْقاءُ وَبَيْضاءُ وَسَوْداءُ، أَكْبَرُ مِنَ العُصْفورِ، يُطْلَقُ عَلَيْهِ القَيْقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5970, 'سُوَيْقَةٌ', 'سويقة', 'جامد', 'سوق', 'سويقة', 'سقة', 'تَصْغيرُ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"سُوَيْقَةٌ-سُوَيْقَةٌ [س و ق]. 1. : تَصْغيرُ سَاقٍ. 2. : تَصْغيرُ سوقٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5971, 'بُريكة', 'بريكة', 'جامد', '', 'بريكة', 'بركة', 'تَصْغيرُ ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5972, 'بُحَيْرَةٌ', 'بحيرة', 'جامد', 'بحر', 'بحيرة', 'بحرة', 'تَصْغِيرُ البَحْر', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(تَصْغِيرُ البَحْر). ""تُوجَدُ بُحَيْرَةٌ بِضاحِيَةِ الْمَدِينَةِ"" : مُجْتَمَعُ مَاءٍ تُحِيطُ بِهِ الأرْضِ من كُلِّ الجِهاتِ، يُطْلَقُ عَلَيْها بِالْمَغْرِبِ اسْم الضَّايَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5973, 'جُنَيْنَةٌ', 'جنينة', 'جامد', 'جنن', 'جنينة', 'جننة', 'تَصْغِيرُ الجَنَّةِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"جُنَيْنَةٌ-جُنَيْنَةٌ [ج ن ن] (تَصْغِيرُ الجَنَّةِ). ""جَلَسَ فِي الْجُنَيْنَةِ مُتَأَمِّلاً أَزْهَارَهَا"" : حَدِيقَةٌ صَغِيرَةٌ بِهَا أَزْهَارٌ وَفَوَاكِهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5974, 'طُوَيْرٌ', 'طوير', 'جامد', 'طير', 'طوير', 'طر', 'تَصْغِيرُ الطَّيْرِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"طُوَيْرٌ-طُوَيْرٌ [ط ي ر] (تَصْغِيرُ الطَّيْرِ). ""طُوَيْرٌ جَمِيلٌ"" : طَائِرٌ صَغِيرٌ جَمِيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5975, 'خُفَيْفٌ', 'خفيف', 'جامد', 'خفف', 'خفيف', 'خفف', 'تصغير خُفّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"خُفَيْفٌ-خُفَيْفٌ [خ ف ف] (تصغير خُفّ).: مَا يُشْبِهُ الجَوْرَبَ، يُوضَعُ فِي رِجْلِ الطِّفْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5976, 'دُرَيْهِمٌ', 'دريهم', 'جامد', 'درهم', 'دريهم', 'درهم', 'تَصْغِيرُ دِرْهَمٍ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(تَصْغِيرُ دِرْهَمٍ). ""لاَ يَمْلِكُ إلاَّ دُرَيْهِمَاتٍ"" : أَيْ نُقُوداً قَلِيلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5977, 'سُوَيْعَةٌ', 'سويعة', 'جامد', 'سوع', 'سويعة', 'سعة', 'تَصْغيرُ سَاعَة', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"سُوَيْعَةٌ-سُوَيْعَةٌ [س و ع] (تَصْغيرُ سَاعَة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5978, 'سُوَيْداء', 'سويداء', 'جامد', 'سود', 'سويداء', 'سد', 'تَصْغير سَوْداء', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سُوَيْداء-سُوَيْداء [س و د] (تَصْغير سَوْداء). ""سُوَيْداءُ القَلْبِ"": حَبَّتُهُ، عُمْقهُ، مُهْجَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5979, 'شُجَيْرَةٌ', 'شجيرة', 'جامد', 'شجر', 'شجيرة', 'شجرة', 'تَصْغِيرُ شَجَرَةِ :', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شُجَيْرَةٌ-شُجَيْرَةٌ [ش ج ر] (تَصْغِيرُ شَجَرَةِ) : أَيِ الشَّجَرَةُ الصَّغِيرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5980, 'صُحَيْنَةٌ', 'صحينة', 'جامد', 'صحن', 'صحينة', 'صحنة', 'تَصْغِيرُ صَحْنٌ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(تَصْغِيرُ صَحْنٌ). ""صُحَيْنَةُ الفِنْجَانِ"" : صَحْنٌ صَغِيرٌ يُوضَعُ تَحْتَ الفِنْجَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5981, 'مُوَيْسٌ', 'مويس', 'جامد', 'موس', 'مويس', 'مس', 'تَصْغِيرُ مُوسَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(تَصْغِيرُ مُوسَى). : سِكِّينٌ صَغِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5982, 'هُرَيْرَةٌ', 'هريرة', 'جامد', 'هرر', 'هريرة', 'هررة', 'تَصْغِيرُ هِرَّةٍ.', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"هَرِيرَةٌ-هَرِيرَةٌ [هـ ر ر]. ""لَمْ يَسْتَطِعْ إِخْفَاءَ هَرِيرَتِهِ"" : كَرَاهِيَتِهِ. ""أَجِدُ فِي وَجْهِهِ هَرِيرَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5983, 'ضِلْعٌ', 'ضلع', 'جامد', 'ضلع', 'ضلع', 'ضلع', 'تُؤَنَّثُ وَتُذَكَّرُ', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"أَضْلُعٌ:ضُلُوعٌ:أَضْلاَعٌ(مص', '', 'R', '', '', '', '', '', '', '"(تُؤَنَّثُ وَتُذَكَّرُ). 1. : عَظْمٌ مِنْ عِظَامِ الصَّدْرِ مُنْحَنٍ، طَوِيلٌ وَمُسَطَّحٌ، وَجُمَّاعُ الأَضْلاَعِ يُؤَلِّفُ القَفَصَ الصَّدْرِيَّ. ""ضِلْعُ خَرُوفٍ"". 2.""ضِلْعُ وَرَقَةِ النَّبَاتِ"" : طَرَفُهَا فِيهِ اعْوِجَاجٌ. 3.""ضِلْعُ شَكْل"', '');
