INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5987, 'أَمْس', 'أمس', 'جامد', '', 'ءمس', 'مس', 'ظَرْفُ زَمَانٍ', '', '', 'جمع تكسير', 'DnN', '', '', '"آمُسٌ:أَموسٌ:آماسِ"', '', 'R', '', '', '', '', '', '', '"ج: آمُسٌ، أَموسٌ، آماسِ.: ظَرْفُ زَمانٍ يُرادُ بِهِ اليَوْمُ الَّذي يَسْبِقُ اليَوْمَ الْحَاضِرَ الَّذِي أَنْتَ فيهِ، وَقَدْ يَدُلُّ على الماضِي مُطْلَقاً، وَهُوَ مَبْنِيٌّ على الكَسْرِ. قالوا : أَمْسِ الدَّابِرُ لا يَعودُ، وإِذا نُكِّرَ أَو أُضيفَ أو دَخَلَتْ عَلَيْهِ أَلْ، أُعْرِبَ. 1.""زُرْتُ الْمُتْحَفَ أَمْسِ"" : البارِحَ"', ':لا جذر:لا مفرد');
