INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5992, 'مَاجَرَيَاتٌ', 'ماجريات', 'جامد', 'جري', 'ماجريات', 'مجرت', 'كَلِمَةٌ مَأْخُوذَةٌ مِنْ جَرَ', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"مَاجَرَيَاتٌ-مَاجَرَيَاتٌ [ج ر ي] (كَلِمَةٌ مَأْخُوذَةٌ مِنْ ""جَرَى مَا جَرَى""). 1"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5993, 'مَخَاطِرُ', 'مخاطر', 'جامد', 'خطر', 'مخاطر', 'مخطر', 'لاَ مُفْرَدَ لَهَا مِنْ صِيغَت', '', '', 'مفرد', '', '', '', '"(بِصِيغَةِالْجَمْعِ)"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَخَاطِرُ-مَخَاطِرُ [خ ط ر] (لاَ مُفْرَدَ لَهَا مِنْ صِيغَتِهَا). ""وَاجَهَ مَخَاطِرَ فِي سَفَرِهِ"" : الْمَهَالِكَ، الأَخْطَارَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5994, 'غَنَمٌ', 'غنم', 'جامد', 'غنم', 'غنم', 'غنم', 'لاَ وَاحِدَ لَهُ مِنْ لَفْظِهِ', '', '', 'مفرد', 'DnN', '', '', '"أَغْنَامٌ"', '', 'R', '', '', '', '', '', '', '"(لاَ وَاحِدَ لَهُ مِنْ لَفْظِهِ). ""يَرْعَى الْغَنَمَ فِي سَفْحِ الجَبَلِ"" : الجَمَاعَةُ مِنَ الضَّأْنِ وَالْمَعِزِ."', '');
