INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5996, 'كَمَلٌ', 'كمل', 'جامد', 'كمل', 'كمل', 'كمل', 'لاَ يُثَنَّـى وَلاَ يُجْمَعُ', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'N', '', '"كَمَلٌ-كَمَلٌ [ك م ل] (لاَ يُثَنَّـى وَلاَ يُجْمَعُ). ""أَنْجَزَ عَمَلَهُ كَمَلاً"" : كَامِلاً، وَافِياً. ""أَعْطَاهُ حَقَّهُ كَمَلاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5997, 'وَلَدٌ', 'ولد', 'جامد', 'ولد', 'ولد', 'لد', 'للِذَّكَرِ وَالأُنْثَى وَالْمُ', '', '', 'مفرد', 'DnN', '', '', '"أَوْلاَدٌ:وِلْدَةٌ"', '', 'R', '', '', '', '', '', '', '"(للِذَّكَرِ وَالأُنْثَى وَالْمُثَنَّى وَالْجَمْعِ). 1.""وُلِدَ لَهُ وَلَدٌ"" : كُلُّ ما وُلِدَ. آل عمران آية "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(5998, 'أَوْلاَدٌ', 'أولاد', 'جامد', '', 'ءولاد', 'لد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
