INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6000, 'ثُلاثَ', 'ثلاث', 'جامد', 'ثلث', 'ثلاث', 'ثلث', 'لِلمُذَكَّرِ وَالْمُؤَنَّتِ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', 'N', 'N', 'N', 'N', '', '"ثَلاثُ-ثَلاثُ [ث ل ث] (عدَدٌ مُفْرَدٌ مَعْدُودُهُ جَمْعُ مُؤَنَّثٍ). 1.""حَضَرَتْ ثَلاثُ نِسَاءٍ"" : وَنسَاءٍ مُضَافٌ إلَى (ثلاَثُ). ""قَرَأْتُ النَّصَّ ثَلاَثَ مَرَّاتٍ"". 2.""ثَلاَثَ عَشْرَةَ سَنَةً"" : عَدَدٌ مُرَكَّبٌ مَعْدُودُهُ مُفْرَدٌ مُؤَنَّثٌ. ""صَارَ عُمْرُهَا ثَلاَثَ عَشْرَةَ سَنَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6001, 'دَابَّةٌ', 'دابة', 'جامد', 'دبب', 'دابة', 'دبة', 'لِلْمُذَكَّر وَالْمُؤَنَّثِ', '', '', 'مفرد', 'DnN', '', 'Pf', '":دَوَابُّ"', '', 'R', '', '', '', '', '', '', '"(لِلْمُذَكَّر وَالْمُؤَنَّثِ).: تُطْلَقُ عَلَى مُخْتَلفِ الحَيَواناتِ وَمَا دَبَّ مِنْهَا، وَغَلَبَ عَلَى مَا يُرْكَبُ وَيُحْمَلُ عَلَيْهِ. هود آية 6 وَمَا مِنْ دَابَّةٍ فِي الأرْضِ إلاَّ عَلَى اللَّهِ رِزْقُهَا (قرآن)."', '');
