INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6003, 'جَوَادٌ', 'جواد', 'جامد', 'جود', 'جواد', 'جد', 'لِلْمُذَكَّرِ وَالْمُؤَنَّثِ', '', '', 'مفرد', 'DnN', '', '', '"أَجْوَادٌ:أَجَاوِيدُ"', '', 'R', '', '', '', '', '', '', '"(لِلْمُذَكَّرِ وَالْمُؤَنَّثِ). 1.""عُرِفَ بِجَوَادِهِ"" : بِعَطَائِهِ وَسَخَائِهِ. 2.""هُوَ رَجُلٌ جَوَادٌ"" : السَّخِيُّ الكَرِيمُ."', '');
