INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6008, 'خُمَاسَ', 'خماس', 'جامد', 'خمس', 'خماس', 'خمس', 'لِلْمُذَكَّرِ وَالْمُؤَنَّثِ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', 'N', 'N', 'N', 'N', '', '"خُمَاسَ-خُمَاسَ [خ م س] (لِلْمُذَكَّرِ وَالْمُؤَنَّثِ). ""جَاءوا خُمَاسَ"" : جَاءوا خَمْسَةً خَمْسَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6009, 'قِنٌّ', 'قن', 'جامد', 'قنن', 'قن', 'قن', 'لِلْمُذَكَّرِ وَالْمُؤَنَّثِ، ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُنٌّ-قُنٌّ [ق ن ن]. ""سَكَنَ الْقُنَّ"" : الْجَبَلَ الصَّغِيرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6010, 'خِلْوٌ', 'خلو', 'جامد', 'خلو', 'خلو', 'خل', 'لِلْمُذَكَّرِ وَالْمُؤَنَّثِ و', '', '', 'مفرد', 'DnN', '', '', '"أَخِلاَّءُ"', '', 'R', '', '', '', '', '', '', '"(لِلْمُذَكَّرِ وَالْمُؤَنَّثِ وَالْمُثَنَّى وَالجَمْعِ). 1. ""بَالُهُ خِلْوٌ مِنْ كُلِّ غَمٍّ"" : خَالٍ. 2.""أَمْسَى الْمَكَانُ خِلْواً مِنْ سَاكِنِيهِ"" : فَارِغاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6011, 'أَخِلاَّءُ', 'أخلاء', 'جامد', '', 'ءخلاء', 'خل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6012, 'وَسَطٌ', 'وسط', 'جامد', 'وسط', 'وسط', 'سط', 'لِلْمُذَكَّرِ وِالْمُؤَنَّثِ و', '', '', 'مفرد', 'DnN', '', '', '"أَوْسَاطٌ"', '', 'R', '', '', '', '', '', '', '"(لِلْمُذَكَّرِ وِالْمُؤَنَّثِ وَالْمُفْرَدِ وَالْجَمْعِ). 1.""جَلَسَ فِي وَسَطِ البَيْتِ"" : فِي صَدْرِهِ، أَيْ بَيْنَ طَرَفَيْهِ. 2.""فِي وَسَطِ الطَّرِيقِ"" : فِي مُنْتَصَفِهِ. 3.""فِي وَسَطِ الْمَدِينَةِ"" : فِي قَلْبِهَا. 4.""هَوَاءٌ وَسَطٌ"" : مُعْتَدِلٌ. 5.""شَدَّتْ وَسَطَهَا بِحِزَامٍ"" : أَيْ مُنْتَصَفَ جِسْمِهَا. 6.""جَاءتْ نَتَائِجُهُ وَسَطاً"" : أَيْ بَيْنَ الرَّدِيءِ وَالْجَيِّدِ. 7. البقرة آية 143 وَكَذَلِكَ جَعَلْنَاكُمُ أُمَّةً وَسَطا ( قرآن) : أَيْ أُمَّةَ عَدْلٍ وَخَيْرٍ. 8.""هُوَ مِنْ وَسَطِ قَوْمِهِ"" : مِنْ خِيَارِهِمْ. 9.""عَاشَ فِي وَسَطٍ جَبَلِيٍّ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6013, 'أَوْسَاطٌ', 'أوساط', 'جامد', '', 'ءوساط', 'سط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6014, 'نَظُورَةٌ', 'نظورة', 'جامد', 'نظر', 'نظورة', 'نظرة', 'لِلْمُفْرَدِ وَالْجَمْعِ وَالْ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نَظُورَةٌ-نَظُورَةٌ [ن ظ ر] (لِلْمُفْرَدِ وَالْجَمْعِ وَالْمُذَكَّرِ وَالْمُؤَنَّثِ). 1. ""نَظُورَةُ الْقَوْمِ"" : عَمِيدُهُمْ وَسَيِّدُهُمُ الْمَنْظُورُ إِلَيْهِ. 2. ""نَظُورَةُ الْجَيْشِ"" : طَلِيعَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6015, 'يَفَعَةٌ', 'يفعة', 'جامد', 'يفع', 'يفعة', 'فعة', 'لِلْمُفْرَدِ وَالْمُثَنَّى وَا', '', '', 'مفرد', 'DnN', '', 'Pf', '"أَيْفَاعٌ"', '', 'R', '', '', '', '', '', '', '"(لِلْمُفْرَدِ وَالْمُثَنَّى وَالْجَمْعِ). ""شَابٌّ يَفَعَةٌ"" : مُتَرَعْرِعٌ. ""فَتَاةٌ يَفَعَةٌ"" l ""شُبَّانٌ يَفَعَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6016, 'أَيْفَاعٌ', 'أيفاع', 'جامد', '', 'ءيفاع', 'فع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6017, 'غَدَارِ', 'غدار', 'جامد', 'غدر', 'غدار', 'غدر', 'مَبْنِيٌّ عَلَى الكَسْرِ', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'N', '', '"غَدَارِ-غَدَارِ [غ د ر] (مَبْنِيٌّ عَلَى الكَسْرِ). ""يَا غَدَارِ"" : أَيْ يَا غَادِرَة، وَيَخْتَصُّ هَذَا بِالنِّدَاءِ لِشَتْمِ الْمَرْأَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6018, 'جَبِينٌ', 'جبين', 'جامد', 'جبن', 'جبين', 'جبن', 'مذ', '', '', 'مفرد', 'DnN', '', '', '"أَجْبِنَةٌ"', '', 'R', '', '', '', '', '', '', '"(مذ). ""جَبِينُ الرَّجُلِ"" : هُوَ مَا بَيْنَ مَنْبَتِ شَعْرِ الرَّأْسِ وَالحَاجِبَيْنِ. ""يَسْتَطِيبُونَ الخُبْزَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6019, 'أَجْبِنَةٌ', 'أجبنة', 'جامد', '', 'ءجبنة', 'جبنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6020, 'مِعًى', 'معى', 'جامد', 'معو', 'معى', 'مع', '.مُذَكَّرٌ وَقَدْ يُؤَنَّثُ', '', '', 'مفرد', 'Dw', '', '', '"أَمْعَاءٌ:أَمْعِيَةٌ"', '', 'Rw', '', '', '', '', '', '', '".: مُذَكَّرٌ وَقَدْ يُؤَنَّثُ، مُصْرَانُ البَطْنِ الْمُكَوِّنُ لِلْجِهَازِ الْهَضْمِيِّ، وَهُوَ جُزْءٌ مِنَ القَنَاةِ الْهَضْمِيَّةِ مِنَ الْمَعِدَةِ إِلَى الشَّرَجِ. ""الْمِعَى الغَلِيظُ"" : وَهُوَ الجُزْءُ الأَخِيرُ الْمُتَّسِعُ مِنَ الأَمْعَاءِ وَهُوَ يَلِي الْمِعَى الدَّقِيقَ وَيَتَأَلَّفُ مِنَ الأَعْوَرِ وَالقُولُونِ وَالْمُسْتَقِيمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6021, 'أَمْعَاءٌ', 'أمعاء', 'جامد', '', 'ءمعاء', 'مع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6022, 'أَمْعِيَةٌ', 'أمعية', 'جامد', '', 'ءمعية', 'معة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6023, 'مَثْنَى', 'مثنى', 'جامد', 'ثني', 'مثنى', 'مثن', 'مذ، مؤ', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'N', 'N', 'N', '', '"مَثْنَى-مَثْنَى [ث ن ي] (مذ، مؤ). 1.""جَاءوا مَثْنَى"" : اِثْنَيْنِ اثْنَيْنِ، وَهُوَ مَمْنُوعٌ مِنَ الصَّرْفِ. 2.""مَثْنَى أَوْتَارِ العُودِ"" : مَا بَعْدَ الأَوَّلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6024, 'روحٌ', 'روح', 'جامد', 'روح', 'روح', 'رح', 'مذ، مؤ', '', '', 'مفرد', 'DnN', '', '', '"أَرْواحٌ"', '', 'Rp', '', '', '', '', '', '', '"(مذ، مؤ). 1.""خَرَجَتْ رُوحُهُ"" : خَرَجَتْ نَفْسُهُ، أَيْ ما بِهِ حَياةُ النَّفْسِ، مَاتَ. ""أَزْهَقَ روحَهُ"" الإسراء آية 85 يَسْأَلونَكَ عَنِ الرُّوحِ، قُلِ الرُّوحُ مِنْ أَمْرِ رَبِّي وَما أُوتِيتُمْ منَ العِلْمِ إِلاَّ قَليلاً (قرآن) . 2. الشعراء آية 193 نَزَلَ بِهِ الرُّوحُ الأَمينُ (قرآن) : جِبْريلُ عَليْهِ السَّلام ُ.النحل آية 102 قُلْ نَزَّلَهُ رُوحُ القُدُسِ (قرآن) . 3 . غافر آية 15يُلْقِي الرُّوحَ مِنْ أَمْرِهِ على مَنْ يَشاءُ (قرآن) : الوَحْيُ. 4.""الرُّوحُ الأَعْظَمُ"" : اللَّهُ. 5.""روحُ العَمَلِ"" : جَوْهَرُهُ، أَيْ ما يُقابِلُ المادَّةَ. ""روحُ الكَلامِ"" ""رُوحُ الْمُلاحَظَةِ"". 6.""هُوَ خَفيفُ الرُّوحِ"" : لَطيفُ الْمَعْشَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6025, 'أَرْواحٌ', 'أرواح', 'جامد', '', 'ءرواح', 'رح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6026, 'سِكِّينٌ', 'سكين', 'جامد', 'سكن', 'سكين', 'سكن', 'مذ، مؤ', '', '', 'مفرد', 'DnN', '', '', '"سَكَاكِينُ"', '', 'R', '', '', '', '', '', '', '"(مذ، مؤ). ""يَقْطَعُ اللَّحْمَ بِالسِّكِّينِ"" : آلَةٌ ذَاتُ نَصْلٍ لِق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6027, 'سَكَاكِينُ', 'سكاكين', 'جامد', '', 'سكاكين', 'سككن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6028, 'سِلاَحٌ', 'سلاح', 'جامد', 'سلح', 'سلاح', 'سلح', 'مذ، مؤ', '', '', 'مفرد', 'DnN', '', '', '"أسْلِحَةٌ"', '', 'R', '', '', '', '', '', '', '"(مذ، مؤ). 1. ""سِلاحُ الجُنْدِيُّ"" : آلَةٌ حَرْبِيَّةٌ، مُسَدَّسٌ أوْ بُنْدُقِيَّةٌ أوْ مَا إلَى ذَلِكَ يُدَافِعُ بِهَا الجُنْدِيُّ وَيُقَاتِلُ. ""اِسْتَعْرَضَ الجَيْشُ قُوَّاتِهِ الْمُسَلَّحَةَ مِنْ سِلاحِ الْمُشَاةِ إلَى سِلاَحِ الجَوِّ وَسِلاَحِ الْمِدْفَعِيَّةِ"". 2.""جَرَتِ الْمَعْرَكَةُ بَيْنَهُمْ بِالسِّل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6029, 'أسْلِحَةٌ', 'أسلحة', 'جامد', '', 'ءسلحة', 'سلحة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6030, 'طَرِيقٌ', 'طريق', 'جامد', 'طرق', 'طريق', 'طرق', 'مذ، مؤ', '', '', 'مفرد', 'DnN', '', '', '"طُرُقٌ:طُرُقَاتٌ"', '', 'R', '', '', '', '', '', '', '"(مذ، مؤ). 1.""طَرِيقٌ لاَ ازْدِحَامَ فِيهِ"" : الْمَمَرُّ الَّذِي يَسْلُكُهُ الإِنْسَانُ وَكُلُّ وَسَائِلِ الْمُواصَلاتِ. ""سَارَ فِي الطَّرِيقِ"" ""الطَّرِيقُ العَامُّ"". 2.""اِبْتَعِدْ عَنْ طَرِيقِي"" : اِبْتَعِدْ عَنْ سَبِيلِي، عَنْ مَسَارِي. 3.""وَاصَلَ طَرِيقَهُ بِالرَّغْمِ مِنَ الصِّعَابِ"" : وَاصَلَ نَهْجَهُ، عَمَلَهُ. 4.""سَافَرَ بِطَرِيقِ الْجَوِّ"" : أَيْ بِالطَّائِرَةِ : خُطُوطُ الْمُوَاصَلاَتِ الْجَوِّيَّةِ. ""بِطَرِيقِ البَحْرِ"" : بِالبَاخِرَةِ، ""بِطَرِيقِ البَرِّ"" : بِالسَّيَّارَةِ أَوِ القِطَارِ، إلخ. 5. ""طَرِيقُ السَّلاَمَةِ"" : عِبَارَةٌ تَعْنِي ""لِتَصْحَبْكَ السَّلاَمَةُ فِي طَرِيقِكِ"". 6.""طَرِيق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6031, 'طُرُقٌ', 'طرق', 'جامد', '', 'طرق', 'طرق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6032, 'طُرُقَاتٌ', 'طرقات', 'جامد', '', 'طرقات', 'طرقت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6033, 'طُلَعَةٌ', 'طلعة', 'جامد', 'طلع', 'طلعة', 'طلعة', 'مذ، مؤ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طُلَعَةٌ-طُلَعَةٌ [ط ل ع] (مذ، مؤ). 1.""اِمْرَأَةٌ طُلَعَةٌ"" : كَثِيرَةُ التَّطَلُّعِ، أَوِ الطُّلُوعِ. 2.""نَفْسٌ طُلَعَةٌ"" : كَثِيرَةُ التَّطَلُّعِ وَالْمَيْلِ إِلَى الْهَوَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6034, 'مِلْحٌ', 'ملح', 'جامد', 'ملح', 'ملح', 'ملح', 'مذ، مؤ', '', '', 'مفرد', 'DnN', '', '', '"أَمْلاَحٌ"', '', 'R', '', '', '', '', '', '', '"(مذ، مؤ). 1. : مَادَّةٌ هَشَّةٌ بَلُّورِيَّةٌ، قَابِلَةٌ لِلذَّوَبَانِ، لَهَا طَعْمٌ حِرِّيفٌ، تُسْتَخْرَجُ مِنْ مَاءِ البَحْرِ أَوْ مِنْ جَوْفِ الأَرْضِ، تَصْلُحُ لِتَطْيِيبِ الطَّعَامِ، وَتُسْتَخْدَمُ لِتَجْفِيفِ اللَّحْمِ وَالسَّمَكِ لِحِفْظِهِمَا مِنَ التَّعَفُّنِ. 2.""مَاءٌ مِلْحٌ"" : أَيْ بِهِ مُلُوحَةٌ، خِلاَفُ العَذْبِ. 3.""رَجُلٌ مِلْحُهُ عَلَى رُكْبَتَيْهِ"" : لاَ وَفَاءَ لَهُ. 4.""مِلْحُ الأَرْضِ"" : أَي الْمُفْلِحُونَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6035, 'أَمْلاَحٌ', 'أملاح', 'جامد', '', 'ءملاح', 'ملح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6036, 'مُوسىً', 'موسى', 'جامد', 'موس', 'موسى', 'مس', 'مذ، مؤ', '', '', 'مفرد', 'Dy', '', '', '"مَوَاسٍ:أَمْوَاسٌ"', '', 'RwR0', '', '', '', '', '', '', '"(مذ، مؤ). ""مُوسَى الحِلاَقَةِ"" : آلَةٌ مِنْ فُولاَذٍ يُحْلَقُ بِهَا الشَّعْرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6037, 'مواسي', 'مواسي', 'جامد', '', 'مواسي', 'مس', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6038, 'أَمْوَاسٌ', 'أمواس', 'جامد', '', 'ءمواس', 'مس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6039, 'كَوَاسِبُ', 'كواسب', 'جامد', 'كسب', 'كواسب', 'كسب', 'مفرد كَاسِبَة', '', '', 'مفرد', '', '', '', '"مفردكَاسِبَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"كَوَاسِبُ-كَوَاسِبُ [ك س ب] (مفرد كَاسِبَة). ""كَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6040, 'كَاسِبَة', 'كاسبة', 'جامد', '', 'كاسبة', 'كسبة', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6041, 'بَيَاضٌ', 'بياض', 'جامد', 'بيض', 'بياض', 'بض', 'مَنْ لَوْنُهُ بَيَاضٌ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَيَاضٌ-بَيَاضٌ [ب ي ض] (مَنْ لَوْنُهُ بَيَاضٌ). 1."" عَزَلَ بَيَاضَ البَيْضِ عنْ مُحِّهِ"" : الآحُ الْمَادَّةُ البَيْضَاءُ فِي البَيْضِ، وَكَلِمَةُ البَيَاضِ تُطْلَقُ علَى صِفَةِ الَّلوْنِ الأبْيَضِ. 2.""لَبِسَ البَيَاضَ يَوْمَ العِيدِ"" : كُلَّ مَلاَبِسِهِ كَانَتْ بِيضاً. 3."" أصَابَهُ بَيَاضٌ فِي عَيْنِهِ"": بَيَاضُ العَيْنِ، أيْ مَا يَتَخَلَّلُ بُؤْبُؤَ العَيْنِ مِنْ خُيُوطٍ بيضٍ. 4.""حَافَظَ عَلَى بَيَاضِ وَجْهِهِ"" : نَقَائِهِ وَشَرَفِهِ وَكَرَامَتِهِ. 5."" ظَلَّ يَعْمَلُ بَيَاضَ يَوْمِهِ وَسَوَادَ لَيْلِهِ"" : لَيْلَ، نَهَارَ. 6."" بَيَاضُ النَّهَارِ"" : ضَوْؤُهُ. 7.""بَيَاضُ الَقَلْبِ"" : مَا يُحِيطُ بِهِ. 8.""خَتَمَ لَهُ عَلَى بَيَاضٍ"" : أيْ فَوَّضَ لَهُ الأمْرَ لِيَفْعَلَ مَا يَشَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6042, 'نِيرَةٌ', 'نيرة', 'جامد', 'نور', 'نيرة', 'نرة', 'مِنْ نَيَّرَ الثَّوْبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نِيرَةٌ-نِيرَةٌ [ن و ر] (مِنْ نَيَّرَ الثَّوْبَ). 1. : أَدَاةٌ مِنْ أَدَوَاتِ النَّسَّاجِ يَنْسُجُ بِهَا وَهِيَ الْخَش"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6043, 'مِزْمَارٌ', 'مزمار', 'جامد', 'زمر', 'مزمار', 'مزمر', 'مؤ', '', '', 'مفرد', 'DnN', '', '', '"مَزَامِيرُ"', '', 'R', '', '', '', '', '', '', '"(مؤ): آلَةٌ مُوسِيقِيَّةٌ مِـنَ العَائِلَةِ الْهَوَائِيَّةِ، وَهِيَ قَصَبَةٌ جَوْفَاءُ، مَفْتُوحَةُ الطَّرَفَيْنِ، تُوجَدُ فِي أَحَدِ وُجُوهِهَا سِتَّةُ ثُقُوبٍ، وَفِي الوَجْهِ الْمُقَابِلِ لَهُ يُوجَدُ ثَقْبٌ وَاحِدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6044, 'مَزَامِيرُ', 'مزامير', 'جامد', '', 'مزامير', 'مزمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6045, 'مِزْهَرٌ', 'مزهر', 'جامد', 'زهر', 'مزهر', 'مزهر', 'مؤ', '', '', 'مفرد', 'DnN', '', '', '"مَزَاهِرُ"', '', 'R', '', '', '', '', '', '', '"(مؤ).: آلَةٌ مُوسِيقِيَّةٌ مِنَ العَائِلَةِ الوَتَرِيَّةِ تُقَارِبُ العُودَ شَكْلاً، يُصْنَعُ هَيْكَلُهَا مِنَ الجِلْدِ وَيُشَدُّ عَليْهِ وَتَرَانِ، كَمَا يُطْلَقُ عَلَى الدَّفِّ الْمُسْتَدِيرِ اسْمُ الْمُزْهِر، وَهُوَ مُحَاطٌ بِصُنُوجٍ نُحَاسِيَّةٍ. ""دُقُّوا الْمَزَاهِرَ يَا أَهْلَ البَيْتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6046, 'مَزَاهِرُ', 'مزاهر', 'جامد', '', 'مزاهر', 'مزهر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6047, 'مَعْزُوفَةٌ', 'معزوفة', 'جامد', 'عزف', 'معزوفة', 'معزفة', 'مو', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مو) ""عَزَفَ مَعْزُوفَةً"": قِطْعَةً مُوسِيقِيَّةً تَعْزِفُهَا الآلاَتُ بِلاَ غِنَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6048, 'مَصَبٌّ', 'مصب', 'جامد', 'صبب', 'مصب', 'مصب', 'مَوْضِعُ الانْصِبَابِ', '', '', 'مفرد', 'DnN', '', '', '"مَصَابُّ"', '', 'R', '', '', '', '', '', '', '"(مَوْضِعُ الانْصِبَابِ). ""مَصَبُّ النَّهْرِ"" : مَوْضِعُ اِنْصِبَابِهِ فِي نَهْرٍ أَكْبَرَ أَوْ بَحْرٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6049, 'مَصَابُّ', 'مصاب', 'جامد', '', 'مصاب', 'مصب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6050, 'مَنُونٌ', 'منون', 'جامد', 'منن', 'منون', 'منن', 'مؤ، مذ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَنُونٌ-مَنُونٌ [م ن ن] (مؤ، مذ). ""ذَهَبَ بِهِمُ الْمَنُونُ جَمِيعاً"": الْمَنِيَّةُ، الْمَوْتُ. ""أَمِنَ الْمَنُونِ ورَيْبِهَا تَتَوَجَّعُ "". (أبو ذؤيب الهذلي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6051, 'نَارٌ', 'نار', 'جامد', 'نور', 'نار', 'نر', 'مؤ، مذ', '', '', 'مفرد', 'DnN', '', '', '"نِيَرانٌ"', '', 'Rp', '', '', '', '', '', '', '"(مؤ، مذ). 1.""نَارٌ مُشْتَعِلَةٌ"" : مَادَّةٌ مُضِيئَةٌ مُحْرِقَةٌ نَاجِمَةٌ عَنِ احْتِرَاقِ الْخَشَبِ أَوِ الفَحْمِ وَنَحْوِهِمَا. ""نَارُ الْمَوْقِدِ"" ""نَارُ جَهَنَّمَ"" القارعة آية 11 نَارٌ حَامِيَةٌ (قرآن) ""اِنْدَلَعَتِ النِّيرَانُ"". 2.""نَارُ الْجَبَلِ"" : البُرْكَانُ. 3.""أَوْقَدَ نَارَ الْحَرْبِ وَالفِتْنَةِ"" : أَوْقَدَ فَتِيلَهَا، اِنْدِلاَعَهَا. 4.""أَشْهَرُ مِنْ نَارٍ عَلَى عَلَمٍ"" : عِبَارَةٌ تُقَالُ لِرَجُلٍ مَشْهُورٍ، مَعْرُوفٍ جِدّاً، ذَائِعُ الصِّيتِ. 5.""نَارُ البَهِيمَةِ"" : عَلاَمَتُهَا، سِمَتُهَا. 6.""الانْتِظَارُ أَحَرُّ مِنَ النَّارِ"" : أَحَرُّ مِنَ الاِحْتِرَاقِ. 7.""أَطْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6052, 'نِيَرانٌ', 'نيران', 'جامد', '', 'نيران', 'نرن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6053, 'ذِراعٌ', 'ذراع', 'جامد', 'ذرع', 'ذراع', 'ذرع', 'مُؤَنَّثَةٌ وَقَدْ تُذَكَّرُ', '', '', 'مفرد', 'DnN', '', '', '"أَذْرُعٌ:ذُرْعانٌ"', '', 'R', '', '', '', '', '', '', '"(مُؤَنَّثَةٌ وَقَدْ تُذَكَّرُ). 1.""ذِراعُ اليَدِ"" : مِنَ طَرَفِ المِرْفَقِ إلى طَرَفِ الأُصْبُعِ. 2.""ذِراعُ الرَّجُلِ"" : السَّاعِدُ. 3.""ذِراعٌ مِنْ أَيْدِي البَقَرِ أَوِ الغَنَمِ"": فَوْقَ الكُراعِ، أَيْ مُسْتَدَقُّ السَّاقِ العارِي مِنَ اللَّحْمِ. 4.""ذِراعٌ مِنْ أَيْدِي الإِبِلِ"" : فَوْقَ الوَظيفِ. 5.""رَجُلٌ واسِعُ الذِّراعِ"" : أَيْ رَجُلٌ لَهُ طاقَةٌ وَقُدْرَةٌ، مُقْتَدِرٌ. 6.""ضاقَ بِذلِكَ ذِراعُهُ"" : لَمْ يُطِقْ ما صَدَرَ عَنْهُ. 7.""كانَ أَرْحَبَهُمْ ذِراعاً"" : أَرْحَبَهُمْ نَفْساً. قَلِّدوا أَمْرَكُمْ رَحْبَ الذِّراعِ (حديث). 8.""هُوَ ذِراعُهُ الأَيْمَنُ"" : مُساعِدُهُ الأَقْرَب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6054, 'أَذْرُعٌ', 'أذرع', 'جامد', '', 'ءذرع', 'ذرع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6055, 'ذُرْعانٌ', 'ذرعان', 'جامد', '', 'ذرعان', 'ذرعن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6056, 'وَسْنَى', 'وسنى', 'جامد', 'وسن', 'وسنى', 'سن', 'مؤنث وَسِنٌ', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"وَسْنَى-وَسْنَى [و س ن] (مؤنث وَسِنٌ). ""اِمْرَأَةٌ وَسْنَى"" : نَاعِسَةٌ، فَاتِرَةُ الطَّرْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6057, 'مِلْكٌ', 'ملك', 'جامد', 'ملك', 'ملك', 'ملك', '', '', '', 'مفرد', 'DnN', '', '', '"أملاك"', '', 'R', '', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6058, 'أَمْلاكٌ', 'أملاك', 'جامد', '', 'ءملاك', 'ملك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6059, 'شَذْرَةٌ', 'شذرة', 'جامد', 'شذر', 'شذرة', 'شذرة', 'وَاحِدَةُ الشَّذْرِ', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '":شُذُورٌ"', '', 'R', '', '', '', '', '', '', '"(وَاحِدَةُ الشَّذْرِ). 1.""شَذَرَاتُ ذَهَبٍ"" : قِطَعٌ مِنَ الذَّهَبِ. 2.""لَمْ يَقْرَأْ إِلاَّ شَذَرَاتٍ مِنَ الكِتَابِ"" : أَيْ فِقْرَاتٍ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6060, 'شُذُورٌ', 'شذور', 'جامد', '', 'شذور', 'شذر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6061, 'شَعْرٌ', 'شعر', 'جامد', 'شعر', 'شعر', 'شعر', 'وَاحِدَةُ الشَّعْرِ', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(وَاحِدَةُ الشَّعْرِ). 1.""لَمْ يَحِدْ عَنْ ذَلِكَ قَيْدَ شَعْرَةٍ"" : لَمْ يَحِدْ قَيْدَ أُنْمُلُةٍ، أَي الْتَزَمَ بِالأَمْرِ الْتِزَاماً تَام"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6062, 'حالٌ', 'حال', 'جامد', 'حول', 'حال', 'حل', 'وصف لِلْمُذَكَّرِ وَالْمُؤَنَّ', '', '', 'مفرد', 'DnN', '', '', '"أَحْوالٌ"', '', 'Rp', '', '', '', '', '', '', '"(وصف لِلْمُذَكَّرِ وَالْمُؤَنَّثِ). 1.""كَيْفَ حالُكَ؟ كَيْفَ أَحْوالُكَ؟ "" : سُؤالٌ عَنِ الصِّحَّةِ وَأُمورِ الْمَرْءِ، حالَتُهُ وَهَيْئَتُهُ وَطَبيعَتُهُ. ""إِنَّ الحالَ يُغْني عَنِ السُّؤالِ"" . ""لِسانُ الحالِ أَبْيَنُ مِنَ الْمَقالِ"". 2.""أَجابَ عَنْ رِسالَتِهِ في الحالِ"" : عَلى الفَوْرِ. 3.""على كُلِّ حالٍ لَسْتُ مَسْؤُولاً عَمَّا حَدَثَ"" : مَهْما يَكُنْ مِنْ أَمْرٍ. ""على أَيِّ حالٍ"". 4.""لَنْ أَخْضَعَ لَهُ بِأَيِّ حالٍ مِنَ الأَحْوالِ"" : بِأَيِّ وَجْهٍ كانَ. 5.""بِأَيِّ حالٍ عادَ إلى بِلادِهِ"" : بِأَيِّ صُورَةٍ. ""عيدُ بِأَيَّةِ حالٍ عُدْتَ يا عيدُ"". (المتنبي). 6.""عَلِمْتُ أَنَّ أَحْوالَهُ الاقْتِصادِيَّةَ سَيِّئَةٌ"" : ظُروفَهُ. 7.""هِيَ أَحْوالُ الدَّهْرِ هَكَذا"" : نَوائِبُهُ، تَقَلُّباتُهُ، صُر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6063, 'أَحْوالٌ', 'أحوال', 'جامد', '', 'ءحوال', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6064, 'حانوتٌ', 'حانوت', 'جامد', 'حنت', 'حانوت', 'حنت', 'يُذَكَّر وَيُؤَنَّثُ', '', '', 'مفرد', 'DnN', '', '', '"حَوانِيتُ"', '', 'R', '', '', '', '', '', '', '"(يُذَكَّر وَيُؤَنَّثُ). ""حانوتُ بَقَّالِ"" : الدُّكَّانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6065, 'حَوانِيتُ', 'حوانيت', 'جامد', '', 'حوانيت', 'حنت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6066, 'دَرْعٌ', 'درع', 'جامد', 'درع', 'درع', 'درع', 'يُذَكَّرُ وَيُؤَنَّثُ', '', '', 'مفرد', 'DnN', '', '', '"دُرُوعٌ:أدْرُعٌ:دِراعٌ"', '', 'R', '', '', '', '', '', '', '"(يُذَكَّرُ وَيُؤَنَّثُ). 1. ""لَبِسَ الجُنْدِيُّ الدِّرْعَ"" : قَمِيصٌ مِنْ حَدِيدٍ يُلْبَسُ وِقَايَةً مِنَ السِّلاَحِ. 2. ""دِرْعُ الْمَرْأَةِ"" : قَمِيصُهَا، يُلْبَسُ فِي البَيْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6067, 'دُرُوعٌ', 'دروع', 'جامد', '', 'دروع', 'درع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
