INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6069, 'دِراعٌ', 'دراع', 'جامد', '', 'دراع', 'درع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6070, 'سَبِيلٌ', 'سبيل', 'جامد', 'سبل', 'سبيل', 'سبل', 'يُذَكَّرُ وَيُؤَنَّثُ', '', '', 'مفرد', 'DnN', '', '', '"سُبُلٌ"', '', 'R', '', '', '', '', '', '', '"(يُذَكَّرُ وَيُؤَنَّثُ). 1.""ذَهَبَ إلَى حَالِ سَبِيلِهِ"" : إلَى شُغْلِهِ، مُهِمَّتِهِ. 2.""أخْلَى سَبِيلَهُ"" : أطْلَقَ سَرَاحَهُ. ""أَخْلَى سَبِيلَ السَّجِينِ"". 4.""اِبْنُ السَّبِيلِ"" : الْمُسَافِرُ الَّذِي لاَ يَمْلِكُ زَاداً كَثِيراً.البقرة آية 215 قُلْ مَا أنْفَقْتُمْ مِنْ خَيْرٍ فَلِلْوَالدَيْنِ وَالأقْرَبِينَ وَاليتَامى وَالْمَسَاكِينِ وابْنِ السَّبِيلِ (قرآن). 5.""عَابِرُ السَّبِيلِ"" : عَابِرُ الطَّرِيقِ. 6.""فِي سَبِيلِ الل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6071, 'سُبُلٌ', 'سبل', 'جامد', '', 'سبل', 'سبل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6072, 'سُلَّمٌ', 'سلم', 'جامد', 'سلم', 'سلم', 'سلم', 'يُذَكَّرُ وَيُؤَنَّثُ', '', '', 'مفرد', 'DnN', '', '', '"سَلالِمُ"', '', 'R', '', '', '', '', '', '', '"(يُذَكَّرُ وَيُؤَنَّثُ). 1.""اِرْتَقَى السُّلَّمَ"" : مِرْقَاة مِنْ خَشَبٍ أَوْ مَعْدِنٍ يَرْتَقِيهَا الْمَرْءُ لِلصُّعُودِ إِلَى مَكَانٍ أَعْلَى. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6073, 'سَلالِمُ', 'سلالم', 'جامد', '', 'سلالم', 'سللم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6074, 'آب', 'آب', 'جامد', '', 'ءءب', 'آب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ الثَّامِنُ مِنَ السَّنَةِ الشَّمْسِيَّةِ، وَهُوَ مِنَ الشُّهُورِ السُّرْيَانِيَّةِ، عَدَدُ أَيَّامِهِ 31 يَوْماً، يَأْتِي بَعْدَ تَمُّوزَ، وَيَلِيهِ أيْلُولُ، وَيُسَمَّى أيْضاً أَغُسْطُسَ، غُشْت، أُوت."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6075, 'أبَابِيلُ', 'أبابيل', 'جامد', '', 'ءبابيل', 'ببل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"الفِرَقُ (جَمْعٌ لاَ وَاحِدَ لَهُ).الفيل آية 3وَأرْسَلَ عَلَيْهِمْ طَيْراً أَبَابِيل (قرآن) : سِرْباً وَرَاءَ سِرْبٍ، مُتَتَابِعَةً، مُتَجَمِّعَةً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6076, 'أَبَازٌ', 'أباز', 'جامد', '', 'ءباز', 'بز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"أَبَازٌ-أَبَازٌ(حو).: مِـنْ فَصِيلَةِ القَنْغَرِ، مِنْ رُتْبَةِ الثَّدْيِيَّاتِ الكِيسِيَّةِ، وَهُوَ مِن حَيَوَانَاتِ أُسْتُرَالْيَـا، لأِنْثَاهُ كِيسٌ فِي سَطْـحِ بَطْنِهَا تَحْمِلُ فِيهِ صِغَارَها وَيُسَمَّى أيْضًا القَنْقَرُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6077, 'إِبَّالَةٌ', 'إبالة', 'جامد', '', 'ءبالة', 'إبلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '": حُزْمَةٌ مِنَ الحَطَبِ أَوْ مِنَ الأعْوادِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6078, 'أبَجَد', 'أبجد', 'جامد', '', 'ءبجد', 'بجد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', 'N', 'N', 'N', 'N', '', '": أَوَّلُ الألْفَاظِ الَّتِي جُمِعَتْ فِيهَا حُرُوفُ الهِجَاءِ فِي اللُّغَةِ العَرَبِيَّةِ وَهِيَ: ""أبَجَد، هَوَّزَ، حُطِّي، كَلَمُنْ، سعْفَصْ، قُرِشَتْ، ثَخَذ، ضَظَغ، وَتُقَابِلُ حُرُوفُهَا فِي حِسَابِ الجُمَّلِ الشَّكْلَ التَّالِي: أ = 1*ي = 10*ق = 100*ب = 2*ك = 20* ر = 200*ج = 3*ل = 30*ش = 300*د = 4*م = 40* ت = 400*هـ = 5 *ن = 50* ث = 500 و = 6*س = 60* خ = 600 ز = 7*ع = 70* ذ = 700 ح = 8*ف = 80* ض = 800ط = 9* ص = 90* ظ = 900 *غ = 1000 وَيُرَتِّبُ الْمَغَارِبَةُ الأَبْجَدِيَّةَ عَلَى الشَّكْلِ التَّالِي :أَبجد، هوز، حطي،كلمن، صعفض، قرست، ثخذ، ظغش. ا = *ي = 10*ق = 100 ب = 2 *ك = 20*ر = 200 ج = 3 * ل = 30 * س = 300 د = 4*م = 40*ت = 400 هـ = 5 *ن = 50*ث = 500 و = 6 *ص = 60*خ = 600 ز = 7 * ع = 70*ذ = 700 ح = 8 * ف = 80* ظ = 800 ط = 9 * ض = 90 * غ = 900 * ش = 1000"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6079, 'آبِدٌ', 'آبد', 'جامد', 'أبد', 'ءابد', 'آبد', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"أوَابِدُ"', '', '', '', '', '', '', '', '', '". 1.""إِنَّهَا حَقّاً لآبِدَةٌ"" : الأَمْرُ العَظِيمُ الَّذِي يُتَعَجَّبُ مِنهُ. 2.""آبِدَةُ الدًّهْرِ"" : الدَّاهِيَةُ يَبْقَى ذِكرُهَا أبَداً. ن. أوَابِدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6080, 'أوَابِدُ', 'أوابد', 'جامد', '', 'ءوابد', 'بد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6081, 'آبِدِينَ', 'آبدين', 'جامد', 'أبد', 'ءءبدين', 'آبدن', '', '', '', 'مفرد', '', '', '', 'الآبدين', '', '', '', 'N', 'O', 'N', 'N', '', '". ""لا أفْعَلُ ذَلِكَ أبَدَ الآبِدِينَ"" : أَبَدَ الدَّهْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6082, 'إِبْرَةٌ', 'إبرة', 'جامد', 'أبر', 'ءبرة', 'إبرة', '', '', '', 'مفرد', 'DnN', '', '', '"إِبَرٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""يَخِيطُ الثَّوْبَ بِإِبْرَةِ الخَيْطِ"": الْمَخِيطُ، أدَاةٌ مِنْ فُولاَذٍ دَقِيقَةٌ، لَهَا طَرَفٌ مُحَدَّدُ الرَّأْسِ وَطَرَفٌ مَثْقُوبٌ، يُخَاطُ بِهَا. 2.""حَقَنَتِ الْمُمَرِّضَةُ الْمَرِيضَ بِالإبْرَةِ"" : المِحْقَن، يُغْرَزُ طَرَفُهَا فِي الجِسْمِ لإدْخَالِ الدَّوَاءِ السَّائِلِ إِلَيْهِ. ""حَقَنَتْهُ الْمُمَرِّضَةُ إِبْرَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6083, 'إِبَرٌ', 'إبر', 'جامد', '', 'ءبر', 'إبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6084, 'إبْرِيزٌ', 'إبريز', 'جامد', '', 'ءبريز', 'إبرز', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": الذَّهَبُ الخَالِصُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6085, 'إِبْرِيقٌ', 'إبريق', 'جامد', '', 'ءبريق', 'إبرق', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أبَارِيقُ"', '', 'R', '', '', '', '', '', '', '"ج: أبَارِيقُ. ""يَصُبُّ القَهْوَةَ مِنَ الإِبْرِيقِ"": إِبْرِيقُ القَهْوَةِ، إِنَاءٌ لِلسَّوَائِلِ مِنْ خَزَفٍ أَوْ زُجَاجٍ أَوْ مَعْدِنٍ وَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6086, 'أَبْرِيل', 'أبريل', 'جامد', '', 'ءبريل', 'برل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ الرَّابِعُ مِنَ السَّنَةِ الشَّمْسِيَّةِ، عَدَدُ أَيَّامِهِ 30 يَوْماً، يَأْتِي بَعْدَ مَارِسَ، وَيَلِيهِ مَايُو، وَيُسَمَّى أَيْضاً نِيسَانَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6087, 'إِبْزيمٌ', 'إبزيم', 'جامد', '', 'ءبزيم', 'إبزم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَبَازيمُ"', '', 'R', '', '', '', '', '', '', '"ج: أَبَازيمُ. ""لِلْحِـزَامِ إِبْـزِيمٌ مَعْدنِيٌّ"" : عُـرْوَةٌ مَعْدِنِيَّةٌ لَهَا لِسَا"', ':لا جذر:لا مفرد');
