INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6089, 'إِبْطٌ', 'إبط', 'جامد', 'أبط', 'ءبط', 'إبط', '', '', '', 'مفرد', 'DnN', '', '', '"آبَاطٌ(مذ:مؤ)"', '', 'R', '', '', '', '', '', '', '". ""يَحْمِلُ تَحْتَ إِبْطِ يُمْنَاهُ رَبَابَةً وَكِتَاباً"" : فِي بَاطِنِ كَتِفِهِ. ""أشُمُّ رَائِحَةً تَنْبَعِثُ مِنْ إِبْطِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6090, 'آبَاطٌ', 'آباط', 'جامد', '', 'ءءباط', 'آبط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
