INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6092, 'آبَالٌ', 'آبال', 'جامد', '', 'ءءبال', 'آبل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6093, 'إبْلِيسُ', 'إبليس', 'جامد', '', 'ءبليس', 'إبلس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَبَالِيسُ:أَبَالِسَةٌ"', 'ممنوع من الصرف', 'R', '', 'O', 'N', 'O', 'O', '', '"ج: أَبَالِيسُ، أَبَالِسَةٌ. 1.البقرة آية 34وَإذْ قُلْنَا لِلْمَلاَئِكَةِ اُسْجُدُوا لآدَمَ فَسَجَدُوا إلاَّ إِبْلِيسَ أبَى ( قرآن) : اِسْمُ عَلَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6094, 'أَبَالِيسُ', 'أباليس', 'جامد', '', 'ءباليس', 'بلس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6095, 'أَبَالِسَةٌ', 'أبالسة', 'جامد', '', 'ءبالسة', 'بلسة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6096, 'اِبْنٌ', 'ابن', 'جامد', '', 'ابن', 'بن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَبْنَاءٌ:بَنُونَ(الوَلَدُالذ', '', 'R', '', '', '', '', '', '', '"ج: أَبْنَاءٌ، بَنُونَ (الوَلَدُ الذَّكَرُ). 1.""اِسْمُهُ أحْمَدُ بْنُ عَلاَّلٍ"" : أَيْ وَلَدُ عَلاَّل. 2.""هُوَ ابْنُ صُلْبِهِ"" : وَلَدُه الشَّرْعِيُّ. 3.""اِبْنُ أَمْسِ"" : مَنْ لَمْ يَخْبُرْ تَجَارِبَ الحَيَاةِ بَعْدُ. ""اِبْنُ البَارِحَةِ"". 4.""هُوَ ابْنُ بَطْنِهِ"" : مَنْ هَمُّهُ مَصْرُوفٌ إِلَى بَطْنِهِ. 5.""اِبْنُ جَلاَ"" : الرَّجُلُ الْمَشْهُورُ الْمَعْرُوفُ. ""أنَا ابْنُ جَلاَ وَطَلاَّعُ الثَّنَايَا*مَتَى أَضَعِ العِمَامَةَ تَعْرِفُونِي"".(سُحَيْم بن وثيل الرياحي). 6.""اِبْنُ البَلَدِ"" : أي الْمُوَاطِنُ السَّاكِنُ فِي البَلَدِ نَشَأةً وَإِقَامَةً. 7.""اِبْنُ حَلاَلٍ"" : أَيْ أَنَّهُ وُلِدَ مِنْ زَوَاجٍ شَرْعِيٍّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6097, 'أَبْنَاءٌ', 'أبناء', 'جامد', '', 'ءبناء', 'بن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6098, 'اِبْنَة', 'ابنة', 'جامد', '', 'ابنة', 'بنة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"مؤنَّثُالابْنِ"', '', '', '', '', '', '', '', '', '"مؤنَّثُ الابْنِ. 1.""هَذِهِ سَلْمَى ابْنَةُ عَمِّي"" : بِنْتُ عَمِّي. 2.""اِبْنَةُ الرَّمْلِ"" : أَي النَّعَامَة، وَقِيلَ الحَيَّةُ. 3.""اِبْنَةُ الكَرْمِ"" : أَي الخَمْرُ، لأنَّ عَنَاقِيدَ العِنَبِ الَّتِي يُصْنَعُ مِنْهَا الخَمْرُ تُؤْخَذُ مِنَ الكرْمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6099, 'آبُنُوس', 'آبنوس', 'جامد', '', 'ءءبنوس', 'آبنس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"آبُنُوس-آبُنُوس، آبِنُوس(نب).: شَجَرٌ مِنْ فَصِيلَةِ الآبنُوسِيَّاتِ، يَنْبُتُفِي الحَبَشَةِ وَالهِنْدِ، خَشَبُهُ ثَمِينٌ أسْوَدُ، صُلْبُ العُودِ ثَقِيلٌ، تُصْنَعُ مِنْهُ بَعْضُ الأثَاثِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6100, 'أُبَّهَةٌ', 'أبهة', 'جامد', '', 'ءبهة', 'بهة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"1.""أظْهَرَ أُبَّهَةً لا مَثِيلَ لَهَا"" : نَخْوَةً. ""لاَ يُخْفِي أُبَّهَتَهُ"". 2.""مُلْكٌ ظَاهِرُ الأبَّهَةِ"" : العَظَمَة. 3.""يَعِيشُ فِي أُبَّهَةٍ"": فِي كِبْرٍ ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6101, 'أَبٌ', 'أب', 'جامد', 'أبو', 'ءب', 'ب', '', '', '', 'مفرد', '', '', '', '"آباءٌ"', '', '', '', 'N', 'O', 'N', 'O', '', '".: الأبُ كَلِمَةٌ مِنَ الأسْمَاءِ الخَمْسَةِ، إِعْرَابُهَا بالحَرْفِ لاَ بالحَرَكَةِ، أيْ تُرْفَعُ بِالوَاوِ وَتُنْصَبُ بِالألِفِ وَتُجَرُّ بِاليَاء. 1.""جِئْتُ مَعَ أبِي"" : مَعَ وَالِدِي. ""حَضَرَ أَبُوكَ"" ""رَأَيْتُ أبَاكَ"" ""سَلَّمْتُ عَلَى أَبِيكَ"" ""وَيُقَالُ فِي نِدَائِهِ : يَا أَبِي، وَيَا أبَتِ وَيَا أبَتَا، وَيَا أبَتَاهُ. 2.""تَنَاقَلُوا العِلْمَ أبًا عَنْ جَدٍٍّ"" : خَلَفاً عَن سَلَفٍ ، أيْ بالتَّوَارُثِ. ""الآبَاءُ وَالأجْدَادُ"". 3.""أبُو الاسْتِقْلاَلِ"" : أيْ مَنْ أثَارَ فِكْرَةَ الاسْتِقلاَلِ لأوَّلِ مَرَّةٍ. 4.""بِأبِي أنْتَ"" : أيْ أَنْتَ مَفْدِيٌّ بِأَبِي... 5.""لِلَّهِ أبُوكَ"" : صِيغَةٌ تَأْتِي لِلمَدْحِ وَالتَّعَجُّبِ، بِمَعْنَى لِلَّهِ دَرُّكَ. 6.""لاَ أبَ لَكَ "" : لِلتُّعَجُّبِ وَالحَثِّ وَالزَّجْرِ. 7. وَلِلْمُنَادَى ""يَا أبَتِ"" : أيْ يَا أبِي. ""إِنَّ الفَتَى مَنْ يَقول هَـا أنَـذَا*لَيْسَ الفَتَى مَن يَقُولُ كَانَ أبِي"". 8.""جَاءوا عَنْ بَكْرَةِ أَبِيهِمْ"" : عَنْ آخِرِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6102, 'آباءٌ', 'آباء', 'جامد', '', 'ءءباء', 'آب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6103, 'أَتَانٌ', 'أتان', 'جامد', '', 'ءتان', 'تن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أُتُن:آتُن"', '', 'R', '', '', '', '', '', '', '"ج: أُتُن، آتُن. (حو).: أُنْثَى الحِمَارِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6104, 'أُتُن', 'أتن', 'جامد', '', 'ءتن', 'تن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6105, 'آتُن', 'آتن', 'جامد', '', 'ءاتن', 'آتن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6106, 'إِتْبٌ', 'إتب', 'جامد', '', 'ءتب', 'إتب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أُتُوبٌ"', '', 'R', '', '', '', '', '', '', '"ج: أُتُوبٌ. 1.: لِبَاسٌ قَصِيرٌ تَلْبَسُهُ الفَتاةُ إلى نِصْفِ السَّاقِ. 2. يُطْلَقُ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6107, 'أُتُوبٌ', 'أتوب', 'جامد', '', 'ءتوب', 'تب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6108, 'أثَاثٌ', 'أثاث', 'جامد', 'أتث', 'ءثاث', 'ثث', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أثَاثٌ-أثَاثٌ [أ ت ث]. 1.""تَمْلِكُ أثَاثاً فَاخِراً"" : الْمَتَاعُ الخَاصُّ بالبَيْتِ. 2.""أثَاثُهُ كَثِيرٌ"" : مَالُهُ كَثِيرٌ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6109, 'أتْرُجَّةٌ', 'أترجة', 'جامد', '', 'ءترجة', 'ترجة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"وَاحِدَةُالأُتْرُجِّ"', '', 'R', '', '', '', '', '', '', '"أتْرُجَّةٌ-أتْرُجَّةٌ (نب). وَاحِدَةُ الأُتْرُجِّ. مَثَلُ الْمُؤْمِنِ الَّذِي يَقْرَأُ القُرآنَ كَمَثَلِ الأَتْرُجَّةِ طَعْمُهَا طَيِّبٌ وَرِيحُهَا طَيِّبٌ . (حديث). ن. أُتْرُجّ ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6110, 'أُتْرُجٌّ', 'أترج', 'جامد', '', 'ءترج', 'ترج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"أُتْرُجٌّ-أُتْرُجٌّ (نب).: شَجَرٌ مِن فَصِيلَةِ البُرْتُقَالِيَّاتِ، يُعْطِي ثِمَاراً أَكْبَرَ مِنَ الَّليْمُونِ لاَ يُؤْكَلُ، يُصْنَعُ مِنْ قِشْرِهِ مُرَبَّى، عَصِيرُهُ حَامِضٌ. يُعْرَفُ بِالكَبَّادِ وَتُفَّاحِ العَجَمِ. ""كَأنَّكُمْ شَجَرُ الأَتْـرُجِّ طَابَـا مَعـاً*حَمْلاً، وَنَوْراً، وَطَابَ العُودُ وَالوَرَقُ"".(ابن الرومي)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6111, 'مَأْتَمٌ', 'مأتم', 'جامد', 'أتم', 'مءتم', 'متم', '', '', '', 'مفرد', 'DnN', '', '', '"مَآتِمُ"', '', 'R', '', '', '', '', '', '', '". ""كَانَ مَأْتَمُهُمْ مُفْزِعاً لِلْقُلُوبِ"" : نَحِيبُهُمْ وَحُزْنُهُمْ، وَالكَلِمَةُ تُطْلَقُ أَسَاساً عَلَى جَمَاعَةٍ مِنَ النَّاسِ فِي حُزْنٍ عَلَى إِثْرِ وَفَاةٍ أَوْ فِي مَرَاسِيمِ الجَنَازَةِ. ""كَانَتْ أَعْرَاسُنَا تَتَحَوَّلُ فِي كُلِّ مَرَّةٍ إِلَى مَآتِمَ"". (إميل حبيبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6112, 'مَآتِمُ', 'مآتم', 'جامد', '', 'مءءتم', 'مآتم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6113, 'أَتُونٌ', 'أتون', 'جامد', 'أتن', 'ءتون', 'تن', '', '', '', 'مفرد', 'DnN', '', '', '"أُتُنٌ:أتَانِينُ"', '', 'R', '', '', '', '', '', '', '". 1.""أتُّونُ الحَمَّام"" : مَوْقِدُ نَارِ الحَمَّامِ. 2.""أتُّونُ الكِلْسِ"" : حُجْرَةٌ تُقَامُ وَتُوقَدُ فِيهَا النَّارُ إِلَى أَنْ يَصِيرَ كِلْسًا. 3.""أتُونُ الْمَعْرَكةِ"" : شِدَّتُهَا، عُنْفُهَا، ضَرَاوَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6114, 'أُتُنٌ', 'أتن', 'جامد', '', 'ءتن', 'تن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6115, 'أتَانِينُ', 'أتانين', 'جامد', '', 'ءتانين', 'تنن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6116, 'إتَاوَةٌ', 'إتاوة', 'جامد', 'أتو', 'ءتاوة', 'إتة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"أَتَاوَى"', '', 'R', '', '', '', '', '', '', '". 1.""قَدَّمَ لَهُ إتَاوَةً"" : الرَّشْوَةَ. 2.""أَوْجَبَ الإتَاوَةَ عَلَيْهِمْ"" : الخَرَاجَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6117, 'أَتَاوَى', 'أتاوى', 'جامد', '', 'ءتاوى', 'ت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6118, 'مَأْتًى', 'مأتى', 'جامد', 'أتي', 'مءتى', 'مت', '', '', '', 'مفرد', 'Dy', '', '', '"مَآتٍ:المآتِي"', '', '', '', '', '', '', '', '', '". 1.""أَتَى الأَمْرَ مِنْ مَأْتَاهُ"" : مِنَ الجِهَةِ الَّتِي يُؤْتَى مِنْهَا. 2.""مَأْتَى رِزْقِهِ"" : مَصْدَرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6119, 'مآتي', 'مآتي', 'جامد', '', 'مءءتي', 'مآت', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6120, 'أَثَافِيٌّ', 'أثافي', 'جامد', '', 'ءثافي', 'ثف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"ن. أُثْفِيَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6121, 'إِثَارٌ', 'إثار', 'جامد', 'أثر', 'ءثار', 'إثر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"إِثَارٌ-إِثَارٌ [أ ث ر]. 1.""إثَارُ النَّهْدَيْنِ"" : حِزَامٌ نِسَائِيٌّ فِي حَجْمِ النَّهْدَيْن، يَشُدُّهُمَا حَتىَّ لاَ يَتَدَلَّيَا. 2.""إِثَارُ الفَاكِهَةِ"" : شِبْهُ كِيسٍ يُسْتَخْدَمُ وِقَايَةً لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6122, 'أثَرٌ', 'أثر', 'جامد', 'أثر', 'ءثر', 'ثر', '', '', '', 'مفرد', 'DnN', '', '', '"آثارٌ"', '', 'R', '', '', '', '', '', '', '". 1.""لَمْ نَجِدْ لَهُ أثَرًا"" : خَبَرًا. 2.""مَازَالَ أثَرُ الجُرْحِ بَاقِياً"" : عَلاَمَتُهُ. ""اِقْتَفَى أَثَرَ أَقْدَامِهِ"". 3.""يَطلُبُ أَثرًا بَعْدَ عَيْنٍ"" : أَيْ مَنْ يَتْرُكُ شَيْئًا يَرَاهُ ثُمَّ يَتْبَعُ أثَرَهُ وَيَسْعَى إِلَيْهِ بَعْدَ فَوَاتِ الأَوَانِ. 4.""لاَ أَطْلُبُ أَثَرًا بَعْدَ عَيْنٍ"" : لاَ ألْتَمِسُ شَيْئاً غَائِباً وَأَتْرُكُ مَا هُوَ مَوْجُودٌ أمَامَ عَيْني. 5.""جَاءَ فِي أثَرِه"": بَعْدَهُ. 6.""أجَابَ عَن سُؤَالِهِ عَلَى الأثَرِ"" : فِيِ الحَالِ. 7.""كُلُّ مَا بَنَاهُ صَارَ أَثَراً بَعْدَ عَيْنٍ"" : زَال، اِضْمَحَلَّ. 8.""الأثَرُ"": الحَدِيثُ. 9.""الأَثرُ"": السُّنَّةُ. ن. آثارٌ . 10.""أَثَرٌ فَنِّيٌّ رَائعٌ"" : عَمَلٌ فَنِّيٌّ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6123, 'آثَارٌ', 'آثار', 'جامد', 'أثر', 'ءءثار', 'آثر', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"1.""آثارُ التَّعَبِ وَاضِحَةٌ عَلَى مُحَيَّاهُ"" : عَلاَمَاتُ التَّعَبِ. 2.""زَارَ الضُّيُوفُ الآثارَ التَّارِيخيَّةَ"": أي القُصُورَ وَالأبْنِيَةَ القَدِيمَةَ وَمَا فِي الْمَتَاحِفِ مِنْ تَمَاثِيلَ وَتُحَفٍ مِنْ بَقَايَا التَّارِيخِ وَمَعَالِمِهِ. ""هَذِهِ آثارُنَا تَشْهَدُ عَلَيْنَا"" ""آثارُ القُدَمَاءِ"". 3.""عِلْمُ الآثَارِ"" : عِلْمٌ يَبْحَثُ في بَقَايَا العُمْرَانِ وَدَلاَلَتِهَا وَالْمُخَلَّفَاتِ الأثَرِيَّةِ القَدِيمَةِ. 4.""لَهُ آثارٌ أدَبِيَّةٌ مَشْهُوَرةٌ"": أَيِ الْمُؤَلَّفات والكِتَابَاتُ الأدَبِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6124, 'إثْرٌ', 'إثر', 'جامد', 'أثر', 'ءثر', 'إثر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"إثْرٌ-إثْرٌ [أ ث ر]. ""غَادَرَ البَيْتَ فَخَرَجْتُ فِي إِثرِهِ"" : بَعْدَهُ، عَقِبَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6125, 'أُثْفِيَّةٌ', 'أثفية', 'جامد', 'أثف', 'ءثفية', 'ثفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"أثَاف:الأثَافِيُّ"', '', '', '', '', '', '', '', '', '". 1. : أحَدُ الأحْجَارِ الثَّلاَثَةِ يُوضَعُ عَلَيْهَا القِدْرُ لِلطَّبْخِ. ""نَصَبُوا الأَثَافِيَّ بجانب الخَيْمَةِ"" ""جَلَسَ الطِّفْلُ مُقَرْفِصاً فِي مُوَاجَهَةِ الأثَافِيّ مُتَرقّباً نُضْجَ ثَمَرَةِ البَلُّوطِ الْمُودَعَةِ فِي الرَّمَادِ"". (أحمد التوفيق). 2.""ثَالِثَةُ الأثَافِيّ"" : القِطعَةُ مِنَ الجَبَلِ يُجْعَل إلَى جَانِبهَا أُثْفِيَّةٌ وَتَكُونُ هِيَ الثَّالِثَةُ. 3.""رَمَاهُ بثَالِثَةِ الأثَافِيّ"" : بِالشَّرِّ وَالْمُصِيبَةِ العَظِيَمَةِ. ""وَلِي جَسَدٌ كَوَاحِـدَةِ الْمَثَـانِي*لَهُ كَبِـدٌ كَثَالِثَـةِ الأثَافِـيِّ"". (بديع الزمان الهمذاني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6126, 'أَثَافِيٌّ', 'أثافي', 'جامد', '', 'ءثافي', 'ثف', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"ن. أُثْفِيَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6127, 'أَثْلٌ', 'أثل', 'جامد', '', 'ءثل', 'ثل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"أَثْلٌ-أَثْلٌ (نب).: شَجَر مِنْ فَصِيلَةِ الطَّرْفَائِيَّاتِ، يَكْثُرُ قُرْبَ المِيَاهِ بِالشَّرْق في الأَرَاضِي الرَّمْلِيَّةِ، خَشَبُهُ صَلْبٌ، أوْرَاقُهُ دَقِيقةٌ، وَأزْهَارُهُ وَرْدِيَّةٌ عُنْقُودِيَّة، تُصْنَعُ مِنْهُ القِصَاعُ وَالجِفَانُ وَالسُّفُنُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6128, 'أَثِيرٌ', 'أثير', 'جامد', '', 'ءثير', 'ثر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"""اِسْتَمَعْتُ إِلَى صَوْتِهِ عَبْرَ اَلأَثِير"" : عَبْرَ الْمِذْيَاع، أيْ حَمَلَتْ صَوْتَهُ الموْجَاتُ الصَّوْتِيَّةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6129, 'أَثِيل', 'أثيل', 'جامد', '', 'ءثيل', 'ثل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"""الأَثِيلُ فِي الكِيمِيَاءِ"" : مَجْمُوعَة أُحَادِيَّة التَّكَافُؤِ مُكَوَّنَة مِنْ ذَرَّتَيْنِ مِنَ ""الكَرْبُونِ"" وَخَمْسِ ذَرَّاتٍ مِنَ ""الهيدْرُوجِينَ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6130, 'أُجاجٌ', 'أجاج', 'جامد', 'أجج', 'ءجاج', 'جج', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أُجاجٌ-أُجاجٌ [أ ج ج]. ""طَعْمٌ أُجاجٌ"" : طَعْمٌ شَدِيد الْمُلوحَةِ والمرارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6131, 'أَجْرٌ', 'أجر', 'جامد', 'أجر', 'ءجر', 'جر', '', '', '', 'مفرد', 'DnN', '', '', '"أُجُورٌ"', '', 'R', '', '', '', '', '', '', '". 1.""كُلُّ عَمَلٍ لَهُ أَجْرٌ"": مُكَافَأَةٌ، مُقَابِلَ عَمَلٍ، خِدْمَة. ""لاَ خِدْمَةَ دُونَ أجْرٍ"". 2.""أَجْرُهُ كَبِيرٌ"" : ثوابُهُ. آل عمران آية 179وَإِنْ تُؤْمِنُوا وَتتَّقُوا فلَكُمْ أَجْرٌ عَظِيمٌ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6132, 'أُجُورٌ', 'أجور', 'جامد', '', 'ءجور', 'جر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6133, 'أُجْرَةٌ', 'أجرة', 'جامد', 'أجر', 'ءجرة', 'جرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"أُجَرٌ"', '', 'R', '', '', '', '', '', '', '". 1.""يَتَقَاضَى أُجْرَتَهُ فِي آخِرٍ كُلِّ شَهْرٍ"" : مَا يُعْطَى لِلأجيِرِ مُقَابِلَ عَمَلِهِ. ""لِكلِّ أَجيرٍ أُجْرَةٌ"". 2.""دَفَعَ أُجْرَةَ النَّقْلِ لِلسَّائِقِ"" : المِقْدَارُ الْمُسْتَحَقُّ مِنَ الْمَالِ مُقَابِلَ النَّقْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6134, 'أُجَرٌ', 'أجر', 'جامد', '', 'ءجر', 'جر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6135, 'آجُرَّة', 'آجرة', 'جامد', '', 'ءءجرة', 'آجرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"آجُرٌّ"', '', 'R', '', '', '', '', '', '', '"ج: آجُرٌّ. ""شُيِّـدَتْ جُدْرَانُ العِمَارَةِ بِالآجُرِّ"" : طِينٌ مِـنَ التُّرَابِ الأحْمَـرِ يُعْجَـنُ وَيُوضَعُ في قَوالِبَ مُسْتَطيلَةٍ وَيُشْوَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6136, 'آجُرٌّ', 'آجر', 'جامد', '', 'ءاجر', 'آجر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6137, 'آجِلٌ', 'آجل', 'جامد', 'أجل', 'ءاجل', 'آجل', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"آجِلٌ-آجِلٌ [أ ج ل]. 1.""سَيَصِلُ عَاجِلاً أوْ آجِلاً"" : حَالاً أوْ فِي وَقْتٍ مُتَأخِّرٍ. 2.""فِي العاجِلِ وَالآجِلِ"" : أي الآنَ وَفِي الْمُسْتَقْبَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6138, 'أَجَلٌ', 'أجل', 'جامد', 'أجل', 'ءجل', 'جل', '', '', '', 'مفرد', 'DnN', '', '', '"آجَالٌ"', '', 'R', '', '', '', '', '', '', '". ""لِكُلِّ شَيْء أجَل"" : وَقت مُعَيَّن. يونس آية 49لِكُل أُمَّة أجَلٌ إذاَ جَاءَ أجَلهُمْ فَلاَ يَسْتَأْخِرُون (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6139, 'آجَالٌ', 'آجال', 'جامد', '', 'ءءجال', 'آجل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6140, 'آجِلَةٌ', 'آجلة', 'جامد', 'أجل', 'ءءجلة', 'آجلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"آجِلَةٌ-آجِلَةٌ [أ ج ل]. ""سَيَلْقَى جَزَاءهُ فِي الآجِلَةِ"" : فِي الآخِرَة. ""صِنْفٌ مِنَ النَّاس عُقولُهُم مُلْتَهِبَةٌ، لَكِنَّهَا عَمِيَّةٌ عَنِ الآجِلَةِ"" (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6141, 'أَجَمَةٌ', 'أجمة', 'جامد', 'أجم', 'ءجمة', 'جمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"جآجَامٌ"', '', 'R', '', '', '', '', '', '', '". 1.""يَزْأرُ فِي أَجَمَتِهِ"": مَأوَى الأَسَدِ أَي العرينُ. 2.""اِخْتَفَى الحَيَوَانُ بَيْنَ الأَجَمَةِ"" : الشَّجَرُ الْمُلْتَفُّ الكَثِيفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6142, 'آجَامٌ', 'آجام', 'جامد', '', 'ءءجام', 'آجم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6143, 'أحَدٌ', 'أحد', 'جامد', 'وحد', 'ءحد', 'حد', '', '', '', 'مفرد', 'DnN', '', '', '"آحَادمؤإِحْدَى"', '', '', '', '', '', '', '', '', '". 1.: أوَّلُ العَدَدِ فِي التَّرْتِيبِ، وَاحِدٌ. 2. ""جَاءَ أَحَدُ الأَشْخَاصِ يَبْحَث عَنْكَ"" : وَاحِدٌ مِنَ النَّاسِ، أَحَدُهُمْ. ""لاَ أَحَدَ يَسْتَطِيعُ أنْ يَقْتَرِبَ مِنْهُ"". 3.الإخلاص آية 1قُلْ هُوَ اللَّهُ أَحَدٌ (قرآن) : مِنَ الأَسْمَاءِ الحُسْنَى، أَيْ لاَ ثَانِيَ لَهُ. 4. ""عَبْدُ الأحَدِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ. 5. ""جَاءَ لِزِيَارَتِهِ يَوْمَ الأحَدِ"" : اليَوْمُ الأو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6144, 'آحَادٌ', 'آحاد', 'جامد', '', 'ءءحاد', 'آحد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6145, 'إحْدَى', 'إحدى', 'جامد', '', 'ءحدى', 'إحد', '', '', '', 'جمع تكسير', '', '', '', '"مؤأَحَدٌ""فِيالفَصْلِإِحْدَىع', 'ممنوع من الصرف', '', '', 'O', 'N', 'O', 'O', '', '"مؤ: أَحَدٌ. ""فِي الفَصْلِ إِحْدَى عَشْرَةَ بِنْتاً"" : عَدَد مُرَكَّبٌ مَعْدُودُهُ مُؤنَّثٌ مَنْصُوبٌ عَلَى التَّمْيِيزِ. """', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6146, 'إِحْلِيلٌ', 'إحليل', 'جامد', '', 'ءحليل', 'إحلل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أحَالِيلُ"', '', 'R', '', '', '', '', '', '', '"ج: أحَالِيلُ. (تش). 1.: مَخْرَجُ البَوْلِ مِنَ الإِنْسَانِ. 2.: مَجْرَى اللَّبَنِ مِنَ الثَّدْيِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6147, 'أحَالِيلُ', 'أحاليل', 'جامد', '', 'ءحاليل', 'حلل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6148, 'إِحَنٌ', 'إحن', 'جامد', 'أحن', 'ءحن', 'إحن', '', '', '', 'مفرد', '', '', '', '"مفردإِحْنَة"', '', 'R', '', '', '', '', '', '', '". ""لَمْ يَرَ مِنْهُ إِلاَّ الإِحَنَ وَشَدائِدَ الأَوْجَاعِ"" : الحِقْد. ""إِنَّ الإِحَنَ تَجُرُّ المِحَنَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6149, 'إِحْنَة', 'إحنة', 'جامد', '', 'ءحنة', 'إحنة', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6150, 'أخَادِيدُ', 'أخاديد', 'جامد', '', 'ءخاديد', 'خدد', '', '', '', 'جمع تكسير', '', '', '', '"مفردأُخْدُود"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جمع أُخْدُود. ن. أُخْدُود."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6151, 'أُخْدُود', 'أخدود', 'جامد', '', 'ءخدود', 'خدد', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6152, 'ثَوابٌ', 'ثواب', 'جامد', 'ثوب', 'ثواب', 'ثب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ثَوابٌ-ثَوابٌ [ث و ب]. ""نَالَ ثَوَاباً"" جَزَاءً عَلَى عَمَلِ خَيْرٍ قَامَ بِهِ. آل عمران آية 148 فآتاهُمُ اللَّهُ ثَواب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6153, 'آخِرُ', 'آخر', 'جامد', 'أخر', 'ءاخر', 'آخر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"آخِرُ-آخِرُ [أ خ ر]. 1.""وَصَلَ آخِرُ الْمُتَسَابِقِينَ"" : مَنْ كَانَ بَعْدَ غَيْرِهِ مِنَ الْمُتَسَابِقِينَ. 2.""وَصَلَ في آخِرِ الأمْرِ"" : فِي نِهَايَةِ الأمْرِ. ""فِي آخِرِ الزَّمَانِ"". 3.""قَرَأ القُرآن إِلَى آخِرِه"" : أيْ بكَامِلِهِ. 4.""لاَ أفْعَلُهُ آخِرَ الدَّهْرِ"" : أيْ لاَ أفْعَلُهُ أبَدَاً. 5. ""إلَى آخِرِهِ"": هَلُمَّ جَرًّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6154, 'أُخْرَى', 'أخرى', 'جامد', 'أخر', 'ءخرى', 'خر', '', '', '', 'مفرد', 'Dy', '', '', '"أُخَرٌ:أُخْرَيَاتٌمؤنثآخَر"', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '". 1.""مِنَ الصَّعْبِ أنْ يَعُودَ مَرَّةً أُخْرَى"" : مَرَّةً ثانِيَةً. ""أنْتَظِرُ فُرْصَةً أُخْرَى"". 2. طه آية 18 هِيَ عَصَايَ أَتَوَكَّأُ عَلَيْهَا وَأهُشُّ بِهَا عَلَى غَنَمِي وَلِي فِيهَا مآرِبُ أُخْرَى (قرآن) : أشياءُ مُشَابِهَة. 3.""اِنْتَقَلَ إِلَى الدُّنْيَا الأُخْرَى"" : الآخِرَةُ، دَارُ البَقَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6155, 'أُخَرٌ', 'أخر', 'جامد', '', 'ءخر', 'خر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6156, 'أُخْرَيَاتٌ', 'أخريات', 'جامد', '', 'ءخريات', 'خرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6157, 'آخِرَةٌ', 'آخرة', 'جامد', 'أخر', 'ءءخرة', 'آخرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"آخِرَةٌ-آخِرَةٌ [أ خ ر].""اِنْتَقَلَ إلى الآخِرَةِ"" : دَارُ البَقاءِ بَعْدَ الْمَوْتِ. آل عمران آية 152مِنْكُمْ مَنْ يُرِيدُ الدُّنْيَا وَمِنْكُمْ مَنْ يُرِيدُ الآخِرَةَ (قرآن) ""أَنْتِ يَا نَفسُ تَفْرَحِينَ بِالآخِرَةِ قَبْلَ مَجِيء الآخِرَةِ"". (جبران خ. جبران)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6158, 'أُخْطُبُوطٌ', 'أخطبوط', 'جامد', '', 'ءخطبوط', 'خطبط', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"أُخْطُبُوطٌ-أُخْطُبُوطٌ (حو).: حَيَوَانٌ بَحْرِيٌّ مِنْ فَصِيلَةِ الرِّخْوِيَّاتِ، لَهُ ثَمَانِي أرجُلِ فِي رَأْسِهِ، فِيهَا مَحَاكِم يَلْتَصِقُ بِهَا، يَتَغَذَّى بالحَيَوَانَاتِ البَحْرِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6159, 'أَخٌ', 'أخ', 'جامد', 'أخو', 'ءخ', 'خ', '', '', '', 'مفرد', '', '', '', '"إِخْوَةٌ:إِخْوَانٌمُثَنَّاهُأ', '', '', '', 'N', 'O', 'N', 'O', '', '". 1.""لِي أخٌ أَكْبَرُ مِنيِّ"" : مَنْ يَجْمَعُكَ وَإِيَاهُ صُلْبٌ، أيْ مَنْ ولِدَ مِنْ أبِيكَ وَأُمِّكَ. 2.""هُوَ أَخٌ عَزِيزٌ عَلَيَّ"" : الصَّدِيقُ، الصَّاحِبُ الرَّفِيقُ، مَنْ تَرْبِطُكَ بهِ صَدَاقَةٌ. ""رُبَّ أخٍ لَمْ تَلِدْهُ لَكَ أُمُّكَ"" (مثل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6160, 'إِخْوَةٌ', 'إخوة', 'جامد', '', 'ءخوة', 'إخة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6161, 'إِخْوَانٌ', 'إخوان', 'جامد', '', 'ءخوان', 'إخن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6162, 'أُخْتٌ', 'أخت', 'جامد', 'أخو', 'ءخت', 'خت', '', '', '', 'مفرد', 'DnN', '', '', '"أَخَوَاتٌمذأخٌ"', '', 'R', '', '', '', '', '', '', '". ""كَانَتِ الأُخْتَ الوَحِيدَةَ"" : مَنْ وُلِدَتْ مِنْ أَبِيكَ وَأُمِّكَ. ""لِي إِخْوَةٌ وَأَخَوَاتٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6163, 'أَخَوَاتٌ', 'أخوات', 'جامد', '', 'ءخوات', 'خت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6164, 'أُخُوَّةٌ', 'أخوة', 'جامد', 'أخو', 'ءخوة', 'خة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'Rp', '', '', '', '', '', '', '"أُخُوَّةٌ-أُخُوَّةٌ [أ خ و]. 1. ""بَيْنَهُمْ أُخُوَّةٌ"" : صِلَةُ القَرَابَةِ بَيْنَ الإِخْوَةِ وَالأَخَوَاتِ. ""بينَهُمَا أُخُوَّةُ الرَّضَاعِ"". 2. ""تَرْبِطُنِي بِهِمْ أُخُوَّةٌ صَادِقَةٌ"" : صِلَةُ التَّضَامُنِ وَالْمَوَدَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6165, 'إدَاوَةٌ', 'إداوة', 'جامد', '', 'ءداوة', 'إدة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '": جِرَابٌ صَغِيرٌ مِنْ جِلْدٍ يُحْمَلُ فِيهِ الْمَاءُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6166, 'آدابٌ', 'آداب', 'جامد', 'أدب', 'ءءداب', 'آدب', '', '', '', 'مفرد', '', '', '', '"مفردأدَب"', '', 'R', '', '', '', '', '', '', '". 1.""آدابُ السُّلُوكِ"" : أخلاقُ السُّلُوكِ. 2.""الآدَابُ وَالفنُونُ"" : الإنْتَاجُ الفِكْرِيُّ شِعْراً أَو نَثْراً. 3.""يُتَابِعُ دِرَاسَتَهُ فِي كُلِّيَّةِ الآدَابِ"" : كلِّيَّة تُدَرَّسُ فِيهَا العُلومُ وَالْمَعَارِفُ الإنْسَانِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6167, 'أدَب', 'أدب', 'جامد', '', 'ءدب', 'دب', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6168, 'آدَمُ', 'آدم', 'جامد', '', 'ءادم', 'آدم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rp', '', 'N', 'N', 'N', 'O', '', '"1.: أَبُو البَشَرِ.البقرة آية 31وَعَلَّمَ آدَمَ الأسْمَاءَ كُلَّهَا (قرآن) . 2.""بَنُو آدَمَ"" : ذُرِّيَّةُ بَنِي آدَمَ، أي الجِنْسُ البَشَرِيُّ، الخَلْقُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6169, 'إِدَامٌ', 'إدام', 'جامد', 'أدم', 'ءدام', 'إدم', '', '', '', 'مفرد', 'DnN', '', '', '"أُدُم"', '', 'R', '', '', '', '', '', '', '". ""اِمتَلأَ الطَّجينُ بِالإِدَامِ"": بالْمَرَقِ وَالدَّسَمِ، وَهُوَ ما يُؤْتَدَمُ بِهِ مَعَ الخُبْزِ وَيُطَيِّبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6170, 'أُدُم', 'أدم', 'جامد', '', 'ءدم', 'دم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6171, 'أَدِيمٌ', 'أديم', 'جامد', 'أدم', 'ءديم', 'دم', '', '', '', 'مفرد', 'DnN', '', '', '"أَدَمٌ:أُدُمٌ:آدِمَةٌ:آدامٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""أَدِيمُ السَّمَاءِ"" : مَا ظَهَرَ مِنْهَا. 2.""أَدِيمُ الأَرضِ"" : وجهها. خَفِّفِ الوَطْءَ مَا أظنُّ أَدِيمَ الْـ*أَرْضِ إلاَّ مِنْ هَذِهِ الأجْسَادِ (المعري) . 3. ""ظَلَّ صَائِماً أَدِيمَ النَّهَارِ"" : أَي النَّهَارَ كُلَّهُ، بِكَامِلِهِ. 4.""أَدِيمُ الضُّحَى"" : أَوَّلُهُ. 5. ""اِشْتَاقَ إلى خُبْزٍ أَدِيمٍ"" : خُبْزٌ مَخْلُوطٌ بالإِدَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6172, 'أَدَمٌ', 'أدم', 'جامد', '', 'ءدم', 'دم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6173, 'أُدُمٌ', 'أدم', 'جامد', '', 'ءدم', 'دم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6174, 'آدِمَةٌ', 'آدمة', 'جامد', '', 'ءءدمة', 'آدمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6175, 'آدامٌ', 'آدام', 'جامد', '', 'ءءدام', 'آدم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6176, 'أدَاةٌ', 'أداة', 'جامد', 'أدو', 'ءداة', 'دة', '', '', '', 'مفرد', 'DnN', '', '', '"أَدَوَاتٌ"', '', '', '', '', '', '', '', '', '". 1. ""أَدَوَاتٌ مَنْزِلِيَّةٌ"" : آلاتُ الطَّبْخِ وَغَيْرُهَا. ""أَدَوَاتٌ صِنَاعِيَّةٌ"". 2. ""مُتَمَكِّنٌ مِنْ أَدَاةِ التَّعْبِيرِ"": مِنَ اللُّغَةِ. 3. ""لَمْ"" : أَدَاةُ جَزْمٍ. أَدَوَاتُ الجَزْمِ"" ""أَدَوَاتُ النَّصْبِ""..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6177, 'أَدَوَاتٌ', 'أدوات', 'جامد', '', 'ءدوات', 'دت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6178, 'آذَارُ', 'آذار', 'جامد', '', 'ءءذار', 'آذر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ الثَّالِثُ مِنَ السَّنَةِ الشَّمْسِيَّةِ، وَهُوَ مِنَ الشُّهُورِ السُّرْيَانِيَّةِ، عَدَدُ أيَّامِهِ 31 يَوْماً، يَأتِي بَعْدَ شُبَاطَ وَيَلِيهِ نِيسَانُ، يُسَمَّى أيْضاً مَارِسَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6179, 'مِئْذَنَةٌ', 'مئذنة', 'جامد', 'أذن', 'مءذنة', 'مذنة', '', '', '', 'مفرد', 'DnN', '', '', '"مَآذِنُ"', '', 'R', '', '', '', '', '', '', '".: البِنَاءُ العَالِي مَوْضِعُ الأذَانِ، الصَّوْمَعَةُ، الْمَنَارَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6180, 'مَآذِنُ', 'مآذن', 'جامد', '', 'مءءذن', 'مآذن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6181, 'أُذْنٌ', 'أذن', 'جامد', '', 'ءذن', 'ذن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"آذَانٌمؤنثةمثنىأُذُنَانِ"', '', 'R', '', '', '', '', '', '', '"مؤنثة. مثنى: أُذُنَانِ. ج: آذَانٌ. 1.""لِكُلِّ إِنْسَانٍ وَحَيَوَانٍ أُذْنَانِ يَسْمَعُ بِهِمَا"" : عُضْوُ السَّمَاعِ. وَالأذْنُ مِنَ الحَوَاسِّ الخَمْسِ. 2. ""أَعَرْتُهُ أُذْناً صاغِيَةً"" : اِسْتَمَعْتُ إِلَيْهِ بِانْتِباهٍ. ""أَعِرْنِي أُذُنَيْكَ"". 3.""لَهُ أُذْنٌ مُوسِيقِيَّةٌ"" : أَيْ هُوَ يَتَذَوَّقُ الْمُوسيقَى ويَسْتَوْعِبُ أَلْحَانَهَا. ""الأذْنُ‏ تَعْشَقُ قَبْلَ العَيْنِ أَحْيَاناً"".(بشار بن برد). 4. ""إِنَّ لِلْحِيطَانِ آذَاناً"" : تَعْبِيرٌ يُقالُ لِلْحِيطَةِ وَالحَذَرِ، أَيْ لِيَحْذَرِ الْمَرْءُ لِسَانَهُ !."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6182, 'آذَانٌ', 'آذان', 'جامد', '', 'ءءذان', 'آذن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6183, 'أَرَاكٌ', 'أراك', 'جامد', '', 'ءراك', 'رك', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"أَرَاكٌ-أَرَاكٌ (نب) .: شَجَـرٌ مِنْ فَصِيلَـةِ الزَّيْتُونِيَّاتِ، يَنْبُتُ فِي شِبْهِ جَزِيرَةِ العَرَبِ، تُتَّخَذُ أَعْوَادُ فُرُوعِهِ مَسَاوِيكَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6184, 'أَرَاكَةٌ', 'أراكة', 'جامد', '', 'ءراكة', 'ركة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"وَاحِدَةُالأرَاكِ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '": وَاحِدَةُ الأرَاكِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6185, 'أَرَبٌ', 'أرب', 'جامد', 'أرب', 'ءرب', 'رب', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"أَرَبٌ-أَرَبٌ [أ ر ب]. ""حَقَّقَ أَرَبَهُ"" : حَاجَتَهُ، أُمْنِيَّتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6186, 'إِرْبِيَانٌ', 'إربيان', 'جامد', 'أرب', 'ءربيان', 'إربن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"إِرْبِيَانٌ-إِرْبِيَانٌ [أ ر ب] (حو).: حَيَوَانَاتٌ بَحْرِيَّةٌ صَغِيرَةٌ مِنْ جِنْسِ السَّرَطَـانِ، مِـنَ القِشْرِيَّـاتِ العُشَارِيَّةِ الأَقْدَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6187, 'إِرْبٌ', 'إرب', 'جامد', '', 'ءرب', 'إرب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"آرَابٌ"', '', 'R', '', '', '', '', '', '', '"ج: آرَابٌ. 1. ""قَطَعَ الشَّاةَ إِرْباً إِرْباً"" : جُزْءاً جُزْءاً، قِطْعَةً قِطْعَةً، عُضْوًا عُضْوًا. "" مَزَّقَ فَرِيسَتَهُ إِرْباً إِرْباً"". 2. ""قَضَى إِرْبَهُ"" : حَاجَتَهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6188, 'آرَابٌ', 'آراب', 'جامد', '', 'ءءراب', 'آرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6189, 'أُرْبَةٌ', 'أربة', 'جامد', '', 'ءربة', 'ربة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":أُرَبٌ"', '', '', '', '', '', '', '', '', '"ج: أُرَبٌ، أُرْبَاتٌ. 1. ""اِرْتَدَى أُرْبَةً زَاهِيَةً مُلاَئِمَةً لِلَوْنِ بِذْلَتِهِ"" : رَبْطَةُ العُنُقِ. 2. ""شَدَّتْ شَعْرَهَا بِأُرْبَةٍ جَمِيلَةٍ"": العُقْدَةُ مِنَ الثَّوْبِ تَشُدُّ بِها الفَتاةُ شَعْرَ رَأْسِها."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6190, 'أُرَبٌ', 'أرب', 'جامد', '', 'ءرب', 'رب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6191, 'أُرثوذكس', 'أرثوذكس', 'جامد', '', 'ءرثوذكس', 'رثذكس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', 'N', 'O', 'N', 'O', '', '": كَلِمَةٌ تُطْلَقُ عَلَى جَمَاعَةِ الْمَسِيحيِّينَ الَّذِينَ يَعْتَقِدُونَ بِالطَّبِيعَةِ الوَاحِدَةِ والْمَشِيئَةِ الوَاحِدَةِ لِلْمَسِيحِ، وَالْمَعْنَى الأَصْلِيُّ لِلْكَلِمَةِ هُوَ الرَّأْيُ الْمُسْتَقِيمُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6192, 'أُرْجُوَانٌ', 'أرجوان', 'جامد', '', 'ءرجوان', 'رجن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"أُرْجُوَانٌ-أُرْجُوَانٌ (نب). 1.: شُجَيْرَةٌ مِنْ فَصِيلَةِ القَرْنِيَّاتِ تَصْلُحُ لِلتَّزْيِينِ، يَسْبِقُ زَهْرُهَا فِي الظُّهُورِ قَبْلَ بُرُوزِ أَوْرَاقِهَا فِي مَطْلَعِ الرَّبِيعِ، لهَا لَوْنٌ وَرْدِيٌّ. 2.""وَضَعَتْ أَحْمَرَ الشِّفَاهِ بِلَوْنِ الأُرْجُوَانِ"": صِبْغٌ أَحْمَرُ قَاتِمٌ، كَانَ الأقْدَمُونَ وَبالأَخَصِّ الفِنِيقِيُّونَ يَسْتَخْرِجُونَهُ مِنْ صَدَفَةِ ""موركس"". ""صَبَغُوا الثِّيَابَ بِالأرْجُوَانِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6193, 'تَارِيخٌ', 'تاريخ', 'جامد', 'أرخ', 'تاريخ', 'ترخ', '', '', '', 'مفرد', 'DnN', '', '', '"تَوَارِيخُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""تَارِيخُ اليَوْمِ هُوَ 15 أُكْتُوبر"" : الوَقْتُ الَّذِي نَحْنُ فِيهِ. 2.""عَقْدٌ يَنْتَهِي بِهِ العَمَلُ بِتَارِيخِ كَذَا"" : يَنْتَهِي أَجَلُهُ فِي وَقْتِ، فِي زَمَنِ كَذَا. 3.""تَارِيخُ مِيلاَدِ ابْنَتِي 30 ماي 1980"" : يَوْمُ مِيلاَدِهَا. 4.""دَرَسَ تَارِيخَ الْمُسْلِمِينَ"" : دَرَسَ وَقَائِعَهُمْ وَأَحْدَاثَهُمْ وَسِيرَتَهُمْ. 5.""التَّارِيخُ المِيلاَدِيُّ"" : تَسْجِيلُ الأَحْدَاثِ مَعَ بِدَايَةِ مِيلاَدِ السَّيِّدِ الْمَسِيحِ. 6.""التَّارِيخُ الهِجْرِيُّ"" : تَسْجِيلُ الأَحْدَاثِ مُنْذُ هِجْرَةِ الرَّسُولِ( إِلَى الْمَدِينَةِ. 7.""تَارِيخُ العَالَمِ الإِسْلاَمِيِّ"" : وَقَائِعُهُ وَأَحْدَاثُهُ. ""تَارِيخُ الأَدَبِ"". 8.""أُسْتَاذُ التَّارِيخِ"" : مَنْ يُدَرِّسُ مَادَّةَ التَّارِيخِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6194, 'تَوَارِيخُ', 'تواريخ', 'جامد', '', 'تواريخ', 'ترخ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6195, 'أَرْخَبِيلٌ', 'أرخبيل', 'جامد', '', 'ءرخبيل', 'رخبل', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '": مَجْمُوعَةُ جُزُرٍ مُتَجَاوِرَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6196, 'أَرُزٌّ', 'أرز', 'جامد', '', 'ءرز', 'رز', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أَرُزٌّ-أَرُزٌّ (نب).: نَبَاتٌ مِنْ فَصِيلَةِ النَّجِيلِيَّاتِ، حَبُّهُ يُشْبِهُ حَبَّ القَمْحِ،أَبْيَضُ اللَّوْنِ، يَنْمُو فِي البُلْدَانِ الرَّطْبَةِ وَالحَارَّةِ وَفِي أَحْوَاضٍ تَغْمُرُهَا المِيَاهُ، وَهُوَ غِذَاءٌ مُفَضَّلٌ لَدَى الشُّعُوبِ الأَسْيَوِيَّةِ، وَمِنْ طَعَامِهِمُ اليَوْمِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6197, 'أَرْزٌ', 'أرز', 'جامد', '', 'ءرز', 'رز', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أَرْزٌ-أَرْزٌ (نب). : شَجَرٌ حَرَجِيٌّ مِنْ فَصِيلَةِ الصَّنَوْبَرِيَّاتِ، مَعْرُوفٌ بِحَجْمِهِ وَصَلابَةِ خَشَبِهِ وَجَوْدَتِهِ، وَهُوَ هَرَمِيُّ الشَّكْلِ، أَنْوَاعُهُ مُخْتَلِفَةٌ، أَشْهَرُهَا أَرْزُ لُبْنَانَ وَجِبَالِ الأطْلَسِ وَالهَمَلاَيَا، أَوْراَقُهُ خَضْرَاءُ عَلَى الدَّوَامِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6198, 'أَرْزَةٌ', 'أرزة', 'جامد', '', 'ءرزة', 'رزة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَرْزٌ"', '', 'R', '', '', '', '', '', '', '"ج : أَرْزٌ. يَحْمِلُ عَلَمُ لُبْنَانَ رَسْمَ الأَرْزَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6199, 'أَرْزٌ', 'أرز', 'جامد', '', 'ءرز', 'رز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6200, 'أَرْصَادٌ', 'أرصاد', 'جامد', '', 'ءرصاد', 'رصد', '', '', '', 'جمع تكسير', 'DnN', '', '', '"رَصْدٌ"', '', 'R', '', '', '', '', '', '', '"ج: رَصْدٌ . ""أَكَّدَتِ الأرْصَادُ الجَوِّيَّةُ أَنَّ حَالَةَ الطَّقْسِ فِي تَحَسُّنٍ مُتَزَايِدٍ"" : طَرَائِقُ عِلْمِيَّةٌ لِمَعْرِفَةِ أَحْوَالِ الطَّقْسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6201, 'رَصْدٌ', 'رصد', 'جامد', '', 'رصد', 'رصد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6202, 'أرْضٌ', 'أرض', 'جامد', '', 'ءرض', 'رض', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَرَاضٍ:الأَرَاضِي:أَرَضون(مؤ', '', 'Rp', '', '', '', '', '', '', '"ج: أَرَاضٍ، الأَرَاضِي، أَرَضون. (مؤ). ""نَمْشِي عَلَى الأَرْضِ وَنَعِيشُ فَوْقَهَا"" : كُرَةٌ سَيَّارَةٌ، تَدورُ حَوْلَ الشَّمْسِ، وَهِيَ تَدُورُ دَوْرَةً كَامِلَةً لَيْلاً وَنَهَاراً، يَعِيشُ فِيهَا الإِنْسَانُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6203, 'أَرَاضِي', 'أراضي', 'جامد', '', 'ءراضي', 'رض', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6204, 'أَرَضَةٌ', 'أرضة', 'جامد', '', 'ءرضة', 'رضة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَرَضٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَرَضٌ، (حش).: حَشَرَةٌ مِنْ رُتْبَةٍ مُتَشَابِهَةِ الأجْنِحَةِ،جِلْدِيَّةُ التَّرْكِيبِ، أَغْلَبُهَا عَدِيمُ الأجْنِحَـةِ، تَقْضِـمُ الخَشَـب وَالحُبُوبَ، تُشْبِهُ إِلَى حَدٍّ مَّا النَّمْلَ، تَعِيشُ فِي البِلاَدِ الحَارَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6205, 'أَرَضٌ', 'أرض', 'جامد', '', 'ءرض', 'رض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6206, 'أُرْغُنٌ', 'أرغن', 'جامد', '', 'ءرغن', 'رغن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""اِسْتَخْدَمتِ الفِرْقَةُ الْمُوسِيقِيَّةُ آلةَ الأُرْغُنِ"" : آلَةٌ مُوسِيقيَّةٌ مٌتَوَسِّطَةُ الحَجْمِ، لَهَا مِزْمَارٌ دَاخلِيٌّ وَعِدَّةُ مَلاَمِسَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6207, 'أَرِيكَة', 'أريكة', 'جامد', 'أرك', 'ءريكة', 'ركة', '', '', '', 'مفرد', 'DnN', '', '', '"أَرَائِكُ"', '', '', '', '', '', '', '', '', '". ""تَمَدَّدَ عَلَى أَرِيكَتِهِ لِيَقْرَأَ الجَرِيدَةَ"" : مَقْعَدٌ مُرِيحٌ مُزَيَّنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6208, 'أَرَائِكُ', 'أرائك', 'جامد', '', 'ءراءك', 'رك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6209, 'أَرْكَانٌ', 'أركان', 'جامد', '', 'ءركان', 'ركن', '', '', '', 'جمع تكسير', '', '', '', '"مفردرُكْن"', '', 'R', '', '', '', '', '', '', '"جمع رُكْن. 1.""أَرْكَانُ الإسْلامِ خَمْسَةٌ"" : قَوَاعِدُهُ، أُسُسُهُ. 2.""الأَرْكَانُ الأَرْبَعَةُ"" : الهَوَاءُ وَالنَّارُ وَالأَرْضُ وَالْمَاءُ، عَنَاصِرُ الحَيَاةِ. 3.""هُوَ مِنْ أَرْكَانِ الدَّوْلَةِ"" : مِنْ أَعْمِدَتِهَا. 4."" أَرْكَانُ الجَيْشِ"" : الضُّبَّاطُ الكِبَارُ الَّذِينَ يُشْرِفُونَ عَلَى الجَيْشِ. 5.""بُنْيَانٌ ثَابِتُ الأرْكَانِ"" : مَتِينُ الأسُسِ. ""اِرْتِقَاءُ البِلاَدِ يَحْتَاجُ إِلَى عِلْمٍ وَجُهْدٍ وَبِنَاءٍ وَدَعَائِمَ وَأَرْكَانٍ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6210, 'رُكْن', 'ركن', 'جامد', '', 'ركن', 'ركن', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6211, 'أَرُومَةٌ', 'أرومة', 'جامد', 'أرم', 'ءرومة', 'رمة', '', '', '', 'مفرد', 'DnN', '', '', '"أُرُومٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""هُوَ طَيِّبُ الأُرُومَةِ، شَرِيفُ الأُرومَةِ"": مِنْ حَسَبٍ وَنَسَبٍ، وَأَصْلٍ شَرِيفٍ. 2.""أُرُومَةُ الشَّجَرَةِ"" : أَصْلُهَا وَمَا يَبْقَى مِنْهَا فِي الأرْضِ بَعْدَ القَطْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6212, 'أُرُومٌ', 'أروم', 'جامد', '', 'ءروم', 'رم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6213, 'أَرْمَلُ', 'أرمل', 'جامد', '', 'ءرمل', 'رمل', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"أَرَامِلُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ج: أَرَامِلُ. 1.""صَارَ عَمِّي أَرْمَلَ"" : أَيْ مَاتَتْ زَوْجَتُهُ، أَيْ كُلُّ رَجُلٍ تَمُوتُ زَوْجَتُهُ. ""اِمْرَأَةٌ أَرْمَلَةٌ"". 2.""هُوَ إِنْسَانٌ أَرْمَلُ"" : فَقِيرٌ لاَ مَنْ يَعُولُهُ وَيُطْعِمُهُ، لاَ أَهْلَ لَهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6214, 'أَرَامِلُ', 'أرامل', 'جامد', '', 'ءرامل', 'رمل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6215, 'إِزَارٌ', 'إزار', 'جامد', '', 'ءزار', 'إزر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أزُرٌ"', '', 'R', '', '', '', '', '', '', '"ج: أزُرٌ. ""اِرْتَدَتْ إِزَارَهَا وَخَرَجَتْ"" : المِلْحَفَة، ثَوْبٌ كَانَتْالْمَرْأَةُ العَرَبِيَّةُ تَتَّخِذُهُ لِحَافاً وَمَازَالَ فِي بَعْضِ الْمَنَاطِقِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6216, 'أزُرٌ', 'أزر', 'جامد', '', 'ءزر', 'زر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6217, 'مِئْزَرُ', 'مئزر', 'جامد', 'أزر', 'مءزر', 'مزر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَآزِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""لَفَّتْ مِئْزَرَهَا حَوْلَ خِصْرِهَا"" : ثَوْبٌ يُحِيطُ بِالقِسْمِ الأَسْفَلِ مِنَ البَدَنِ، الإِزَارِ. 2.""شَدَّ لِلْأَمْرِ مِئْزَرَهُ"" : تَهَيَّأَ لَهُ بِمَا فِيهِ الكِفَايَة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6218, 'مَآزِرُ', 'مآزر', 'جامد', '', 'مءءزر', 'مآزر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6219, 'آزِفَةٌ', 'آزفة', 'جامد', 'أزف', 'ءءزفة', 'آزفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"آزِفَةٌ-آزِفَةٌ [أ ز ف].النجم آية 57أَزِفَتِ الآزِفَةُ (قرآن) . دَنَا يَوْمُ الْقِيَامَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6220, 'مَأْزِقٌ', 'مأزق', 'جامد', 'أزق', 'مءزق', 'مزق', '', '', '', 'مفرد', 'DnN', '', '', '"مَآزِقُ"', '', 'R', '', '', '', '', '', '', '". 1.""دَخَلَ مَأْزِقَ الْحَرْبِ"" : مَوْضِعَهَا. 2.""وَقَعَ فِي مَأْزِقٍ"" : فيِ مَوْقِفٍ حَرِجٍ. ""يُحَاوِلُ الخُرُوجَ مِنَ الْمَآزِقِ التي جَعَلَتْهُ مُتَوَرِّطاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6221, 'مَآزِقُ', 'مآزق', 'جامد', '', 'مءءزق', 'مآزق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6222, 'أَزَلٌ', 'أزل', 'جامد', '', 'ءزل', 'زل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"""خَلقَ اللهُ العَالَمَ مُنْذُ الأزَلِ"" : أَيْ مُنْذُ القِدَمِ، أَيْ مَا لاَ نِهَايَةَ لَهُ فِي أَوَّلِهِ، وَلاَيُعْرَفُ وَقْتُ بَدْئِهِ. ""كَانَ فِي الأزَلِ وَلَيْسَ لِكَوْنِهِ زَوَالٌ"" (الغزالي) ""هُوَ اللَّهُ وُجُودُهُ فِي الأزَلِ وَالأَبَدِ وَاجِبٌ"" (الغزالي)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6223, 'أَزْمَةٌ', 'أزمة', 'جامد', 'أزم', 'ءزمة', 'زمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""أُصِيبَ بِأَزْمَةٍ قَلْبِيَّةٍ"" : نَوْبَةٍ. 2.""يَعِيشُ فِي أَزْمَةٍ مَالِيَّةٍ"" : ضَائِقَةٍ. ""أَزْمَةٌ اقْتِصَادِيَّةٌ"" ""أَزْمَةٌ سِيَاسِيَّةٌ"". 3.""يَعِيشُ أَزْمَةً نَفْسِيَّةً"" : أَيْ اضْطِرَاباً نَفْسِيّاً، ضَيْقاً، شِدَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6224, 'إِزْمِيلٌ', 'إزميل', 'جامد', '', 'ءزميل', 'إزمل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَزَامِيلُ"', '', 'R', '', '', '', '', '', '', '"ج: أَزَامِيلُ. 1.""يَسْتَخْدِمُ الحَذَّاءُ الإزْمِيلَ لِكَشْطِ جِلْدِالأَحْذِيَةِ"": شَفْرَةٌ حَادَّةٌ لِحَكِّ الجِلْدِ. 2.""الأزَامِيلُ أَنْوَاعٌ"": إِزْمِيلُ النَّجَّارِ (مِنْقَشٌ). إِزْمِيلُ النَّحَّاتِ (مِنْحَتٌ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6225, 'أَزَامِيلُ', 'أزاميل', 'جامد', '', 'ءزاميل', 'زمل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6226, 'أزُوتٌ', 'أزوت', 'جامد', '', 'ءزوت', 'زت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": جِسمٌ بَسِيطٌ، غازٌ عَدِيمُ اللَّوْنِ والطَّعْمِ والرَّائِحَةِ، يُكَوِّنُ أَرْبَعَةَ أَخْمَاسِ حَجْمِ الهَوَاءِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6227, 'آس', 'آس', 'جامد', '', 'ءءس', 'آس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": نَبَاتٌ مِنْ فَصِيلَةِ الآسِيَّاتِ، وَهُوَ مَا يُعْرَفُ بالرَّيْحَانِ، ذُو ثِمَارٍ كُرَوِيَّةٍ بِيضٍ مَائِلَةٍ إِلَى الصُّفْرَةِ، وَأحْيَاناً إِلَى الزُّرقَةِ مَعَ سَوَادٍ، لَهُ فُرُوعٌ مَلْسَاءُ، وَرَقـهُ عَطِـرٌ، خُضْرَتُهُ دَائِمَةٌ، وَأزْهَارُهُ صَغِيرَةٌ. "" للآس فَضْلُ بَقَائِـهِ وَوَفَـائِهِ*وَدَوَامُ نَضْرَتِـهِ عَلَى الأوْقَاتِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6228, 'أُسٌّ', 'أس', 'جامد', '', 'ءس', 'س', '', '', '', 'جمع تكسير', 'DnN', '', '', '"آسَاسٌ"', '', 'R', '', '', '', '', '', '', '"ج: آسَاسٌ. 1.""أُسّ البِنـاءِ"" : أَسَاسُهُ، قَاعِدَتُهُ. 2.""5² خَمْسَةٌ أُسُّ اثْنَيْنِ تُسَاوِي 25"": أَيْ دَليِلُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6229, 'آسَاسٌ', 'آساس', 'جامد', '', 'ءءساس', 'آسس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6230, 'إِسْبَانَخٌ', 'إسبانخ', 'جامد', '', 'ءسبانخ', 'إسبنخ', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"إِسْبَانَخٌ-إِسْبَانَخٌ (نب).: بَقْلَةٌ مِنْ فَصِيلَةِ السَّرْمَقِيَّاتِ، أَوْرَاقُهُ خَضْرَاءُ، تُسْلَقَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6231, 'أُسْتَاذٌ', 'أستاذ', 'جامد', '', 'ءستاذ', 'ستذ', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَسَاتِذَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَسَاتِذَةٌ. ""دَخَلَ الأسْتَاذُ قَاعَةَ الدَّرْسِ"" : الْمُعَلِّمُ العَالِمُ بِمَا يُعَلِّمُ وَيُدَرِّسُ العارِف لَهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6232, 'أَسَاتِذَةٌ', 'أساتذة', 'جامد', '', 'ءساتذة', 'ستذة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6233, 'أُسْترَالِيا', 'أستراليا', 'جامد', '', 'ءستراليا', 'سترل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'N', 'N', 'O', '', '"أُسْترَالِيا-أُسْترَالِيا (جغ).: مِنَ القَارَّاتِ الخمسِ، تُقدّر مساحَتُها بـ (7.700.000 كلم²) وعددُ سُكَّانِهَا بـ(15.800.000 نسمة)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6234, 'مَأْسَدَةٌ', 'مأسدة', 'جامد', 'أسد', 'مءسدة', 'مسدة', '', '', '', 'مفرد', 'DnN', '', '', '"مَآسِدُ"', '', 'R', '', '', '', '', '', '', '". ""تَحَوَّلَتِ الغَابَةُ إِلَى مَأْسَدَةٍ"" : الْمَكَانُ الَّذِي تَكْثُرُ فِيهِ الأُسُودُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6235, 'مَآسِدُ', 'مآسد', 'جامد', '', 'مءءسد', 'مآسد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6236, 'أَسَدٌ', 'أسد', 'جامد', '', 'ءسد', 'سد', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أُسُدُ:أُسودٌ(قَدْيَقَعُعلىال', '', 'R', '', '', '', '', '', '', '"ج: أُسُدُ، أُسودٌ. (قَدْ يَقَعُ على الْمُذَكَّرِ وَالْمُؤَنَّثِ).: جِنْسٌ مِنَ السِّباعِ اللَّبونَةِ مِنْ فَصيلَةِ السِّنَّوْرِيَّاتِ، آكِلاتِ اللُّحومِ، يُعْرَفُ بِمَلِكِ الغابَةِ. 1.""وَقَفَ الأَسَدُ أَمامَ عَرينِهِ، يَتَأَمَّلُ مُرورَ مَوْكِبِ الحَيَواناتِ"". 2.""هُوَ الأسَدُ"": يُشَبَّهُ بِالأسَدِ لِشَجاعَتِهِ. ""أَجْرَأُ مِنَ الأسَدِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6237, 'أُسُدٌ', 'أسد', 'جامد', '', 'ءسد', 'سد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6238, 'أُسودٌ', 'أسود', 'جامد', '', 'ءسود', 'سد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6239, 'إِسَارٌ', 'إسار', 'جامد', 'أسر', 'ءسار', 'إسر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"إِسَارٌ-إِسَارٌ [أ س ر]. 1.""إِسَارُ الأسِيرِ"" : القَيْدُ، ما يُشَدُّ بِهِ. 2.""وَقَعَ في إسَارِهِ"" : كانَ مُنْقَادًا لَهُ. 3.""ذَهَبَ إِسَارًا"" : جِهَةَ اليَسَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6240, 'أُسْرَةٌ', 'أسرة', 'جامد', 'أسر', 'ءسرة', 'سرة', '', '', '', 'مفرد', 'DnN', '', '', '"أُسَرٌ"', '', 'R', '', '', '', '', '', '', '". ""اِجْتَمَعَتِ الأُسْرَةُ في يَوْمِ العيدِ"": أَفْرادُ العائِلَةِ، مِنْ أَهْلِ الأبِ وَالأمِّ مَعاً. ""تَحْمِلُ الأُسْرَةُ الَّتي تَنْتَمِي إلى جَدٍّ مُشْتَرَكٍ اسْماً مُشْتَرَكاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6241, 'أُسَرٌ', 'أسر', 'جامد', '', 'ءسر', 'سر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6242, 'أَسَرِيَّةٌ', 'أسرية', 'جامد', 'أسر', 'ءسرية', 'سرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""أَسَرِيَّةُ الْمَتْجَرِ"": الواجِهَةُ الزُّجاجِيَّةُ بِالْمَتْجَرِ، يَضَعُ فِيها التَّاجِرُ سِلَعَهُ لِلْعَرْضِ. 2.""أَسَرِيَّةُ الْمَرْأَةِ"": خِزانَةٌ صَغيرَةٌ لَها جانِبانِ مِنْ زُجاجٍ، وَواجِهَةٌ تَضَعُ فِيها الْمَرْأَةُ أَدَواتِ التَّجْمِيلِ والْمَصوغاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6243, 'مَوَاشِي', 'مواشي', 'جامد', 'مشي', 'مواشي', 'مش', '', 'Tk', '', 'مفرد', '', '', '', '"مفردمَاشِيَة"', '', '', '', '', '', '', '', '', '". ن. مَاشِيَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6244, 'أسَاسٌ', 'أساس', 'جامد', 'أسس', 'ءساس', 'سس', '', '', '', 'مفرد', 'DnN', '', '', '"أُسُسٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَضَعُوا أَسَاسَ الجِدَارِ"": أَصْلَهُ، دِعَامَتَهُ، قَاعِدَتَهُ. ""أسَاسُ البِنَاءِ"" ""أَسَاسُ العَمَلِ الصِّدْقُ"". 2.""جَاءَ بِأخْبَارٍ لاَ أَسَاسَ لَهَا مِنَ الصِّحَّةِ"" : غَيْرِ مَوْثُوقٍ بِهَا. 3.""عَلَى أَسَاسِ تَجْرِبَتِهِ أَخْبَرْتُهُ"" : بِنَاءً عَلَى.."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6245, 'أُسُسٌ', 'أسس', 'جامد', '', 'ءسس', 'س', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6246, 'أُسُسٌ', 'أسس', 'جامد', 'أسس', 'ءسس', 'س', '', '', '', 'مفرد', 'DnN', '', '', '"أَسَاسٌ"', '', 'R', '', '', '', '', '', '', '". ""وَضَعَ أُسُسَ البِناءِ"" : أَعْمِدةً، دَعائِمَ، قواعِدَ. ""مَنْ يَبْني دُونَ أُسُسٍ كَأَنَّهُ يَبْنِي فَوْقَ الرَّمْلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6247, 'أَسَاسٌ', 'أساس', 'جامد', '', 'ءساس', 'سس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6248, 'مُؤَسَّسَةٌ', 'مؤسسة', 'جامد', 'أسس', 'مءسسة', 'مسسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""يُتَابِعُ دِرَاسَتَهُ فِي مُؤَسَّسَةٍ تَرْبَوِيَّةٍ"" : فِي مَعْهَدٍ تَرْبَوِيٍّ. 2.""مُؤَسَّسَةٌ اِقْتِصَادِيَّةٌ"" : شَرِكَةٌ لَهَا شَبَكَةٌ اِقْتِصَادِيَّةٌ وَاسِعَةٌ. ""مُؤَسَّسَةٌ دَوْلِيَّةٌ"" ""مُؤَسَّسَةٌ عِلْمِيَّةٌ"" ""مُؤَسَّسَةٌ خَيْرِيَّةٌ"" ""مُؤَسَّسَةٌ تِجَارِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6249, 'إِسْطَبْل', 'إسطبل', 'جامد', '', 'ءسطبل', 'إسطبل', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ج: إِسْطَبْلاتٌ. مَأْوَى الحَيَواناتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6250, 'أُسْطُوانَة', 'أسطوانة', 'جامد', '', 'ءسطوانة', 'سطنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":أَساطِينُ"', '', 'R', '', '', '', '', '', '', '"ج: أُسْطُواناتٌ، أَساطِينُ. 1.""أُسْطُوانَةُ البِناءِ"": دِعامَةٌ يَنْهَضُ عَلَيْها البِناءُ، عَمودٌ، سارِيةٌ. 2.""في الهَنْدَسَـةِ"": جِسْمٌ صَلْبٌ ذُو طَرَفَيْــنِ مُتَساوِيَيْنِ عـلى هَيْئَـةِ دَائِرَتَيْنِ مُتماثِلَتَيْنِ تَحْصُرانِ سَطْحاً مَلْفوفاً، بِحَيْثُ يُمْكِنُ مُتابَعَتُهُ بِخَطٍّ يَتَحَرَّكُ موازِياً لِنَفْسِهِ، وَيَنْتَهي طرَفاهُ في مُحيطَي هاتَيْنِ الدَّائِرَتَيْنِ. 3.""أُسْطُوانَةُ الدَّابَّةِ"" : إِحْدَى قوائِمِها. 4.""اِسْتَمَعَ إلى أُسْطُوانَةٍ بِها أُغْنِيَّةٌ جَدِيدَةٌ"" : قُرْصٌ دائِرِيٌّ مِنْ مادَّةِ بَلاسْتيكِيَّةٍ تُسَجَّلُ عَلَيْهِ الأَغانِي وَما شابَهَ ذَلِكَ، وَيُعادُ سَماعُها على الحاكِي."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6251, 'أَساطِينُ', 'أساطين', 'جامد', '', 'ءساطين', 'سطن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6252, 'إِسْفَنْجٌ', 'إسفنج', 'جامد', '', 'ءسفنج', 'إسفنج', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '""', '', 'R', '', 'N', 'O', 'O', 'O', '', '"إِسْفَنْجٌ-إِسْفَنْجٌ، ةٌ (حو). 1.: عَدَدٌ مِنَ الحَيَواناتِ البَحْرِيَّةِ المائِيَّةِ النَّباتِيَّةِ، لَهُ أَشْكالٌ غَيْرُ مُتَناسِقَةٍ، قائِمٌ على هَيْكَلٍ لِيفيٍّ، يَشُدُّ الكُتْلَةَ اللَّحْمِيَّةَ مِن جِسْمِهِ. 2.""اِسْتَخْدَمَتِ الإسْفَنْجَ لِتَنْظيفِ الأوانِي وَمَسْحِ الفُسَيْفِساءِ"" : مِنْ المادَّةِ الْمَذْكورَةِ نَفْسِها له مَسامٌّ، وَيُسْتَعْمَلُ في الغَسْلِ وَالتَّنْظِيفِ. وَلَه قُدْرَةٌ على امْتِصاصِ السَّوائِلِ وَاسْتِخْراجِها عِنْدَما يُعْصَرُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6253, 'اِسْفَنْجِيَّاتٌ', 'اسفنجيات', 'جامد', '', 'اسفنجيات', 'سفنجت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": شُعْبَةٌ حَيَوانِيَّةٌ مِنَ الحَلَوِيَّاتِ مُكَوَّنَةٌ مِنَ الإسْفَنْجِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6254, 'إِسْقُمْرِيٌّ', 'إسقمري', 'جامد', '', 'ءسقمري', 'إسقمر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": نَوْعٌ مِنَ السَّمَكِ، مِنْ فَصيلَةِ الإسْقُمْرِيَّاتِ، الكامِلاتِ العِظامِ والشَّائِكاتِ الزَّعانِفِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6255, 'إِسْقُمْرِيَّاتٌ', 'إسقمريات', 'جامد', '', 'ءسقمريات', 'إسقمرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"إِسْقُمْرِيَّاتٌ-إِسْقُمْرِيَّاتٌ (حو).: فَصِيلَةُ أَسْماكٍ، وَهِيَ مِنَ الكامِلاتِ العِظامِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6256, 'إِسْكافٌ', 'إسكاف', 'جامد', '', 'ءسكاف', 'إسكف', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَساكِفَةٌ"', '', 'Rp', '', '', '', '', '', '', '"ج: أَساكِفَةٌ. ""تَرَكْتُ حِذائِي عِنْدَ الإِسْكافِ لإصْلاحِهِ"": مُصْلِحُ الأحْذِيَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6257, 'أَساكِفَةٌ', 'أساكفة', 'جامد', '', 'ءساكفة', 'سكفة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6258, 'أَسَلٌ', 'أسل', 'جامد', '', 'ءسل', 'سل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"أَسَلٌ-أَسَلٌ (نب). 1.""تُصْنَعُ السِّلاَلُ مِنَ الأَسَلِ"" : رَقِيقُ الأغْصانِ يُسْتَعْمَلُ لِصُنْعِ السِّلالِ وَالكَراسِيّ. 2.""جَمَعَ بَيْنَ اليَراعِ والأَسَلِ"" : أَيْ بَيْنَ العِلْمِ وَالرُّمْحِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6259, 'أَسَلَةٌ', 'أسلة', 'جامد', '', 'ءسلة', 'سلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"وَاحِدَةُالأسَلِ"', '', 'R', '', '', '', '', '', '', '"وَاحِدَةُ الأسَلِ. 1.""أَخْرَجَ أَسَلَةَ لِسانِهِ"" : أَيْ رَأْسَ لِسانِهِ. 2.""طَعَنَهُ بِأَسَلَةِ رُمْحِهِ"" : بِرَأْسِ رُمْحِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6260, 'إِسْمَنْتٌ', 'إسمنت', 'جامد', '', 'ءسمنت', 'إسمنت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""يَعْتَمِدُ البِناءُ الحَدِيثُ على مادَّةِ الإسْمَنْتِ"" : خَليطٌ مِنَ الطِّينِ وَالرَّمْلِ وَالحِجارَةِ وَالكِلْسِ الصَّغِيرِ، يَصِيرُ مادَّةً صُلْبَةً بَعْدَ خَلْطِهِ بِالماءِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6261, 'أُسْوَةٌ', 'أسوة', 'جامد', 'أسو', 'ءسوة', 'سة', '', '', '', 'مفرد', 'DnN', '', '', '"أُسَى"', '', 'R', '', '', '', '', '', '', '". ""يَهْتَمُّ بِالرِّياضِيّاتِ أُسْوَةً بِأَخِيهِ"" : على مِثالِهِ، أَيْ مُقْتَدِياً بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6262, 'أُسَى', 'أسى', 'جامد', '', 'ءسى', 'س', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6263, 'أَسْوارٌ', 'أسوار', 'جامد', '', 'ءسوار', 'سر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَسَاوِرُ"', '', 'R', '', '', '', '', '', '', '"جج: أَسَاوِرُ. ""وَضَعَتْ أَساوِرَ في يَدِها"": حُلِيٌّ على شَكْلِ دَوائِرَ مِنَ الذَّهَبِ أَوِ الفِضَّةِ أَوْ ما شابَهَ ذَلِكَ، تَضَعُها الْمَرْأَةُ في مِعْصَمِها."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6264, 'أَسَاوِرُ', 'أساور', 'جامد', '', 'ءساور', 'سر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6265, 'آسِيَةٌ', 'آسية', 'جامد', 'أسي', 'ءءسية', 'آسة', '', '', '', 'مفرد', 'DnN', '', '', '"أسَايَا"', '', '', '', '', '', '', '', '', '". ""آسِيَة عَلَى مَا حَلَّ بِهَا مِن مُصَابٍ"" : حَزِينَةٌ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6266, 'أسَايَا', 'أسايا', 'جامد', '', 'ءسايا', 'س', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6267, 'مَأْسَاةٌ', 'مأساة', 'جامد', 'أسي', 'مءساة', 'مسة', '', '', '', 'مفرد', 'DnN', '', '', '"مَآسٍ:الْمَآسِي"', '', '', '', '', '', '', '', '', '". 1.""حَلَّتْ بِهِ الْمَأْسَاةُ"" : الفَاجِعَةُ، الْمُصِيبَةُ، الكَارِثَةُ. ""لَمْ يَعْرِفْ فِي حَيَاتِهِ إِلاَّ الْمَآسِيَ"". 2.""يُجِيدُ تَمْثِيلَ الْمَأْسَاةِ"" : تَمْثِيلِيَّةٌ تَعْرِفُ أَحْدَاثُهَا مَوَاقِفَ مُؤْلِمَةً وَخَطِيرَةً تُثِيرُ الرُّعْبَ وَالشَّفَقَةَ، التَّرَاجِيدِيَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6268, 'مَآسِي', 'مآسي', 'جامد', '', 'مءءسي', 'مآس', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6269, 'آسِيَا', 'آسيا', 'جامد', '', 'ءءسيا', 'آس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'N', 'N', 'O', '', '"آسِيَا-آسِيَا (جغ).: مِنَ القَارَّاتِ الخَمْسِ، يَحُدُّهَا الْمُحِيطُ الْمُتَجَمِّدُ الشَّمَاليُّ وَالْمُحِيطَانِ الهِنْدِيُّ وَالهَادِي، والبَحْرَان الأبْيَضُ الْمُتَوَسِّطُ وَالأَحْمَرُ وَأورُوبَّا، وَهِيَ مِنْ أكْبَرِ اَلْقَارَّاتِ مِسَاحَة (44 مِلْيُون كلم²) وَأَكْثَرِهَا سُكَّانًا ( 2', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6270, 'أُصْدَةٌ', 'أصدة', 'جامد', 'أصد', 'ءصدة', 'صدة', '', '', '', 'مفرد', 'DnN', '', '', '"أُصَدٌ"', '', 'R', '', '', '', '', '', '', '". ""أُصْدَةٌ أَنِيقَةٌ"" : ثَوْبٌ لاَ كُمَّ لَهُ تَلْبَسُهُ الْمَرْأَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6271, 'أُصَدٌ', 'أصد', 'جامد', '', 'ءصد', 'صد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6272, 'آصِرَة', 'آصرة', 'جامد', 'أصر', 'ءءصرة', 'آصرة', '', '', '', 'مفرد', 'DnN', '', '', '"أَوَاصِرُ"', '', 'R', '', '', '', '', '', '', '". ""تَجْمَعُنَا أَوَاصِرُ صَدَاقَةٍ"": رَوَابِطُهَا، عَلاَئِقُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6273, 'أَوَاصِرُ', 'أواصر', 'جامد', '', 'ءواصر', 'صر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6274, 'إِصْطَبْلٌ', 'إصطبل', 'جامد', '', 'ءصطبل', 'إصطبل', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ن. إِسْطَبْلٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6275, 'أُصْطُوَانَةٌ', 'أصطوانة', 'جامد', '', 'ءصطوانة', 'صطنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ن. أُسْطُوانَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6276, 'أًصْلٌ', 'أصل', 'جامد', 'أصل', 'ءصل', 'صل', '', '', '', 'مفرد', 'DnN', '', '', '"أُصولٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""هُوَ مِنْ أَصْلٍ شَريفٍ"": مِنْ مَنْبِتٍ، مَنْشَإٍ شَريفٍ. 2.""لاَ أَصْلَ لَهُ ولاَ فَصْلَ"" : لَيْسَ لَهُ نَسَبٌ أَصيلٌ. 3.""صورَةٌ طِبْقَ الأَصْلِ للِشَّهادَةِ"" : نُسْخَةٌ مُصادَقٌ عَلَيْها. 4.""هَذَا الأمْرُ ما فَعَلْتُهُ أَصْلاً"" : لَمْ أَقُمْ بِهِ إِطْلاقاً، نِهائِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6277, 'أُصولٌ', 'أصول', 'جامد', '', 'ءصول', 'صل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6278, 'أَصيصٌ', 'أصيص', 'جامد', '', 'ءصيص', 'صص', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أُصُصٌ"', '', 'R', '', '', '', '', '', '', '"ج: أُصُصٌ. ""على حافَةِ الشُّرْفَةِ أُصُصُ الزُّهورِ وَالنَّباتاتِ"" : الأَواَنِي مِنَ الطِّينِ الْمَشْوِيِّ، أَوْ مَا شابَهَ ذَلِكَ لِوَضْعِ النَّباتاتِ وَأَنْواعِ الزُّهورِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6279, 'أُصُصٌ', 'أصص', 'جامد', '', 'ءصص', 'ص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6280, 'إِطارٌ', 'إطار', 'جامد', 'أطر', 'ءطار', 'إطر', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أُطُرٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَضَعَ صورَةَ العائِلَةِ في إِطارٍ مُذَهَّبِ"" : حاشِيَة مِنْ خَشَبٍ أَوْ حَديدٍ أَو وَرَقٍ مُقَوّىً يُحيطُ بِالصُّورَةِ. 2.""أَعادَ صِباغَةَ أُطُرِ النَّوافِذِ"" : حَواشِيها. 3.""إِطارُ عَجَلَةِ السَّيَّارَةِ"" : مَطَّاطٌ يُنْفَخُ وَيوضَعُ في قَلْبِ العَجَلَةِ لِسَيْرِها. 4.""يَعْمَلُ في إِطارٍ ضَيِّقٍ"" : في مَجالٍ ضَيِّقٍ. ""إِطارُ العَمَلِ"". 5.""إِطارٌ مِنَ النَّاسِ"" : الحَلْقَةُ مِنْهُمْ. 6.""هُوَ مِنْ أُطُرِ الدَّوْلَةِ"" : مِنَ الْمُتَخَصِّصينَ في مَجالٍ عِلْمِيٍّ مُعَيَّنٍ يُعْتَمَدُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6281, 'أُطُرٌ', 'أطر', 'جامد', '', 'ءطر', 'طر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6282, 'أَطْلَسُ', 'أطلس', 'جامد', '', 'ءطلس', 'طلس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rp', '', 'N', 'O', 'N', 'O', '', '"أَطْلَسُ-أَطْلَسُ (جغ). 1.""كِتابُ الأطْلَسِ بِهِ خَرائِطُ العالَمِ"": كِتابٌ يَضُمُّ مَجْموعَةً مِنَ الخَرائِطِ الجُغْرافِيَّةِ. 2.""قَضَيْنا بِجِبالِ الأَطْلَسِ أُسْبوعاً"" : سِلْسِلَةٌ مِنَ الجِبالِ بِالْمَغْرِبِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6283, 'أَطْمارٌ', 'أطمار', 'جامد', '', 'ءطمار', 'طمر', '', '', '', 'جمع تكسير', '', '', '', '"مفردطِمْر"', '', 'R', '', '', '', '', '', '', '"جمع طِمْر. ""كانَ يَرْتَدي أَطْماراً بالِيَةً"" : أَثْواباً مُهْتَرِئَةً. ""إِنَّ الجاهِلَ إِذَا لَبِسَ الثَّوْبَ النَّاعِمَ هُوَ أَشْرَفُ مِنَ العالِمِ إِذَا لَبِسَ الأطْمارَ"". (التوحيدي)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6284, 'طِمْر', 'طمر', 'جامد', '', 'طمر', 'طمر', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6285, 'أَطومٌ', 'أطوم', 'جامد', '', 'ءطوم', 'طم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أُطُمٌ:آطِمَةٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: أُطُمٌ، آطِمَةٌ. (حو).: مِنْ فَصيلَةِ الثَّدْيِيَّاتِ، مِنْ رُتْبَةِ الخَيْلانِيَّاتِ، يَعيشُ في الْمُحيطِ الهِنْدِيِّ، يَبْلغُ طولُـهُ أَحْياناً ثَلاثَةَ أَمْتارٍ، يَقْتاتُ مِنَ النَّباتاتِ المائِيَّةِ، يَأْوي إلى الماءِ، لَهُ يَدانِ وَلَيْسَ لَهُ رِجْلانِ، يُسَمَّى بَقَرُ البَحْرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6286, 'أُطُمٌ', 'أطم', 'جامد', '', 'ءطم', 'طم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
