INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6288, 'أَعِنَّةٌ', 'أعنة', 'جامد', '', 'ءعنة', 'عنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"مفردعِنان"', '', '', '', '', '', '', '', '', '"جمع عِنان. ن. عِنانٌ. ""دَعِ الأُمورَ تَجْرِي في أَعِنَّتِها"": دَعْها تَسِيرُ في مَجْراها الطَّبِيعِيِّ، أَيْ يَسِّرْ لِجامَها."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6289, 'عِنان', 'عنان', 'جامد', '', 'عنان', 'عنن', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6290, 'أُغُسْطُس', 'أغسطس', 'جامد', '', 'ءغسطس', 'غسطس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '": الشَّهْرُ الثَّامِنُ مِنَ السَّنَةِ الشَّمْسِيَّةِ يَأْتِي بَعْدَ تَمُّوزَ وَيَلِيهِ أيْلُولُ، عَدَدُ أيَّامِهِ 31 يَوْماً. وَيُسَمَّى أيْضاً غشت، أوت، آب."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6291, 'إفْرنْجٌ', 'إفرنج', 'جامد', '', 'ءفرنج', 'إفرنج', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', 'N', 'O', 'N', 'O', '', '": اِسْمٌ يُطْلَقُ عَلَى الأُورُوبِّيِّينَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6292, 'إفْرِيقْيَا', 'إفريقيا', 'جامد', '', 'ءفريقيا', 'إفرق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'N', 'N', 'O', '', '"إفْرِيقْيَا-إفْرِيقْيَا (جغ).: مِنَ القَارَّاتِ الخَمْسِ، تُعْرَفُ بِالقارَّةِ السَّوْدَاءِ، تُقّدَّرُ مِسَاحَتُهَا بـ (30 مليون كلم² ) وعدد سُكَّانِها بـ ( 554 مليون نسمة)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6293, 'أفْعَى', 'أفعى', 'جامد', '', 'ءفعى', 'فع', '', '', '', 'جمع تكسير', 'Dy', '', '', '"أفَاعٍ:الأَفاعِي"', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"ج: أفَاعٍ، الأَفاعِي. (حو).: مِنَ الزَّواحِفِ، مِنْ فَصِيلَةِ الأفاعِيَّاتِ، حَيَّةٌ سامَّةٌ تُشْبِهُ الحَبْلَ. ""عَرَفَ اللَّهُ كَيْدَ الأفْعَى فَوَضَعَ رِجْلَها في بَطْنِها"".(حنا مينه)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6294, 'أَفاعِي', 'أفاعي', 'جامد', '', 'ءفاعي', 'فع', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6295, 'أُفْعُوانٌ', 'أفعوان', 'جامد', '', 'ءفعوان', 'فعن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"ذَكَرُالأَفْعَى"', '', 'R', '', '', '', '', '', '', '"ن. أَفْعَى.: ذَكَرُ الأَفْعَى. ""الأَفْعَى إِذا جَامَعَها الذَّكَرُ واسْمُهُ الأُفْعُوانُ تَحَوَّلَتْ إِلَيْهِ، فَإِنْ ظَفَرَتْ بِهِ أَكَلَتْ رَأْسَهُ مِنْ شِدَّةِ عِشْقِها لَهُ"".(التوحيدي)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6296, 'أُفُقٌ', 'أفق', 'جامد', 'أفق', 'ءفق', 'فق', '', '', '', 'مفرد', 'DnN', '', '', '"آفاقٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""يَنْظُرُ إلَى الأُفْقِ الأعْلَى بِمِنْظارِهِ"" : الحَدُّ الأقْصَى فِي السَّماءِ. ""حَدَّقَ بِالأُفُقِ البَعِيدِ""النجم آية 7 وَهُوَ بِالأفُقِ الأعْلَى (قرآن). 2.""وَقَفَ يَتَأمَّلُ فِي شُرْفَتِهِ الآفاقَ الْمُحِيطَةَ بِالْمَدِينَةِ"" : الجِهات، النَّواحِي. 3.""قامَ بِجَوْلَةٍ فِي الأُفُقِ"" : جَوْلَةٌ دَائِرِيَّةٌ اسْتِطْلاَعِيَّةٌ. 4.""كَشَفَ آفاقاً جَدِيدَةً"" : جَوَانِبَ، مَعَالِمَ، جِهاتٍ، أَماكِنَ. 5.""هُوَ جَوَّابُ آفاقِهِ"" : كَثِيرُ الأسْفارِ. 6.""وَسَّعَ آفَاقَ مَعَارِفِهِ"" : مَدارِكَهُ، وإمْكاناتِهِ. ""هُوَ وَاسِعُ الأفُقِ"". 7.التكوير آية 23 وَلَقَدْ رَآهُ بِالأفُقِ الْمُبِينِ (قرآن) : بِمَطْلَعِ الشَّمْسِ الأعْلَى. 8.""ضَيِّقُ الأُفُقِ"" : ضَيِّقُ التَّفْكِيرِ، مَنْ يَظَلُّ مَحْدوداً فِي تَفْكِيرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6297, 'آفاقٌ', 'آفاق', 'جامد', '', 'ءءفاق', 'آفق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
