INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6299, 'آفِكَةٌ', 'آفكة', 'جامد', 'أفك', 'ءءفكة', 'آفكة', '', '', '', 'مفرد', 'DnN', '', '', '"أَوَافِكُ"', '', 'R', '', '', '', '', '', '', '". ""سَنَةٌ آفِكَةٌ"" : مُجْدِبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6300, 'أَوَافِكُ', 'أوافك', 'جامد', '', 'ءوافك', 'فك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6301, 'أَفيكَةٌ', 'أفيكة', 'جامد', 'أفك', 'ءفيكة', 'فكة', '', '', '', 'مفرد', 'DnN', '', '', '"أَفائِكُ"', '', '', '', '', '', '', '', '', '". ""جاءَ بِأَفيكَةٍ لا مَثيلَ لَها"": بِكِذْبَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6302, 'أَفائِكُ', 'أفائك', 'جامد', '', 'ءفاءك', 'فك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6303, 'أفْواهٌ', 'أفواه', 'جامد', '', 'ءفواه', 'فه', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَفاويهُ"', '', '', '', '', '', '', '', '', '"ج: أَفاويهُ. ""لاَ طَعَامَ دُونَ أفاوِيهَ"": دُونَ تَوَابِلَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6304, 'أَفاويهُ', 'أفاويه', 'جامد', '', 'ءفاويه', 'فه', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6305, 'أفيُونٌ', 'أفيون', 'جامد', '', 'ءفيون', 'فن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": مادَّةٌ عِبارَةٌ عَنْ عُصَارَةٍ، تُسْتَخْرَجُ مِنَ الخَشْخَاشِ تُخَدِّرُ الجِسْمَ والعَقْلَ. ""لا تَقْتَرِبْ مِنَ الأفْيُونِ لِكَيْ لاَ تُخَرِّبَ عَقْلَكَ وَصِحَّتَكَ"". ‎‎"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6306, 'أُقْنُومٌ', 'أقنوم', 'جامد', '', 'ءقنوم', 'قنم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أقَانِيمُ"', '', 'R', '', '', '', '', '', '', '"ج: أقَانِيمُ. 1.: الشَّخْصُ. 2.: الأَصْلُ. 3.""أقَانِيمُ النَّصَارَى"" : الأَبُ والابنُ وَرُوحُ القُدُسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6307, 'أقَانِيمُ', 'أقانيم', 'جامد', '', 'ءقانيم', 'قنم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6308, 'أُكَالٌ', 'أكال', 'جامد', '', 'ءكال', 'كل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"1. ن. آكِلَةٌ. 2.: الْجَرَبُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6309, 'أُكْتُوبر', 'أكتوبر', 'جامد', '', 'ءكتوبر', 'كتبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ العَاشِرُ مِنَ السَّنَةِ الشَّمسِيَّةِ، عَدَدُ أيَّامِهِ (31) يَوْماً يَأتِي بَعْدَ سِبْتَمْبِر، أيْلُول، وَيَلِيهِ نوفَمْبر، تِشْرِينَ الثَّانِي، وَيُسَمَّى أيْضاً تِشْرِينَ الأوّل."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6310, 'أُكْسِجِين', 'أكسجين', 'جامد', '', 'ءكسجين', 'كسجن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"أُكْسِجِين-أُكْسِجِين (كيما).: غَازٌ غَيْرُ مَرْئِيٍّ ضَرُورِيٌّ لِجَمِيعِ الكَائِنَاتِ الحَيَّةِ، وَهُوَ لاَ لَوْنَ وَلاَ رَائِحَةَ لَهُ، يُوجَدُ فِي الهَوَاءِ بِصُورَةٍ حُرَّةٍ وَيُشَكِّلُ 21 % مِنْ حَجْمِهِ. يُوجَدُ القِسْمُ الأكْبَرُ مِنَ الأُكْسِجِينِ مُرَكَّباً كَمَا فِي الْمَاءِ وَالرَّمْلِ وَالصُّخُورِ وَالْمَعادِنِ الْمُخْتَلِفَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6311, 'أُكْسِيدٌ', 'أكسيد', 'جامد', '', 'ءكسيد', 'كسد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"أُكْسِيدٌ-أُكْسِيدٌ (كيما).: مُرَكَّبٌ نَاتِجٌ عَنِ الْتِحَامِ، أَيِ اتِّحَادِ جِسْمٍ مَعَ الأُكْسِجِينِ (بِيُوكْسِيد بِيرُوكْسِيد، بروتُوكْسِيد، حسَبَ نِسْبَةِ الأُكْسِجِينِ). أُكْسِيدُ الكَرْبُونِ، أُكْسِيدُ الحَدِيدِ، أُكْسِيدُ النُّحَاسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6312, 'إكْسِيرٌ', 'إكسير', 'جامد', '', 'ءكسير', 'إكسر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"1.: مَادَّةٌ مُرَكَّبَةٌ تُلْقَى عَلَى الْمَعْدِنِ البَسِيطِ فَتُحَوِّلُهُ إلَى ذَهَبٍ ظَاهِرٍ حَسَبَ اعْتِقَادِ الأقْدَمِينَ. 2.""إذَا رَغِبْتَ فِي طُولِ العُمْرِ فَابْحَثْ عَنْ إكْسِيرِ الحَيَاةِ"" : شَرَابٌ وَهْمِيٌّ يُقالُ إِنَّهُ يُطِيلُ الحَيَاةَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6313, 'عِرْبِيدٌ', 'عربيد', 'جامد', 'عربد', 'عربيد', 'عربد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عِرْبِيدٌ-عِرْبِيدٌ [ع ر ب د] (صف). 1.""وَجَدْتُ عِرْبِيداً فِي الشَّارِعِ"" : صِفَةٌ للِسِّكِّيرِ وَهُوَ يَتَمَايَلُ يَمِيناً وَشِمَالاً وَيُؤْذِي النَّاسَ فِي سُكْرِهِ. 2.""عِرْبِيدٌ فِي سُلُوكِهِ"" : سَيِّءُ السُّلُوكِ وَالأَخْلاَقِ، شِرِّيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6314, 'أُكْلٌ', 'أكل', 'جامد', 'أكل', 'ءكل', 'كل', '', '', '', 'مفرد', 'DnN', '', '', '"آكَالٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أُكْلُ الشَّجَرِ"" : ثَمَرُهُ. 2.""أتَىَ أُكْلَهُ"" : ثَمَرَهُ.إبراهيم آية 25 تُؤْتِي أُكْلَهَا كُلَّ حِينٍ بِإذْنِ رَبِّهَا (قرآن). 3.""لَهُ أُكْلٌ"" : رِزْقٌ وَاسِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6315, 'آكَالٌ', 'آكال', 'جامد', '', 'ءءكال', 'آكل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6316, 'آكِلَةٌ', 'آكلة', 'جامد', 'أكل', 'ءءكلة', 'آكلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '".: دَاءٌ يَقَعُ في العُضْوِ يَأْتَكِلُ مِنْهُ، الحِكَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6317, 'مَأْكَلٌ', 'مأكل', 'جامد', 'أكل', 'مءكل', 'مكل', '', '', '', 'مفرد', 'DnN', '', '', '"مَآكِلُ"', '', 'R', '', '', '', '', '', '', '". ""قَدَّمَ لَهُ مَا لَذَّ وَطَابَ مِنَ الْمَأْكَلِ"" : مَا يُؤْكَلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6318, 'مَآكِلُ', 'مآكل', 'جامد', '', 'مءءكل', 'مآكل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6319, 'أَكْلٌ', 'أكل', 'جامد', '', 'ءكل', 'كل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ن. أُكْلٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6320, 'إِكْليرُوس', 'إكليروس', 'جامد', '', 'ءكليروس', 'إكلرس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": رِجَالُ الدِّينِ عِنْدَ الْمَسِيحِيِّينَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6321, 'أَكَمَةٌ', 'أكمة', 'جامد', 'أكم', 'ءكمة', 'كمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَكَمٌجآكَامٌ"', '', 'R', '', '', '', '', '', '', '". 1.""تَرَبَّعَ الرَّاعِي فَوْقَ الأَكَمَةِ يَتَأمَّلُ غَنَمَهُ"" : التَّلُّ، مَكَانٌ مُرْتَفِعٌ. 2.""وَرَاءَ الأكَمَةِ مَا وَرَاءهَا"" : أيْ مَا وَرَاءهَا شَيْءٌ مُرِيبٌ وَمُخِيفٌ، إِنَّ في الأَمْرِ لَسِرّاً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6322, 'أَكَمٌ', 'أكم', 'جامد', '', 'ءكم', 'كم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6323, 'آكَامٌ', 'آكام', 'جامد', '', 'ءءكام', 'آكم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6324, 'أكُورْدِيون', 'أكورديون', 'جامد', '', 'ءكورديون', 'كردن', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', 'N', 'O', 'N', 'O', '', '"أكُورْدِيون-أكُورْدِيون (مو).: آلَةٌ مُوسِيقِيَّةٌ شَعْبِيَّةٌ فِي أُورُوبَّا تُحْمَلُ، ذَاتُ مَلاَمِسَ، تُحْدِثُ أَصْوَاتاً بِمُسَاعَدَةِ اهْتِزَازِ مِنْفَاخٍ وَتَمَوُّجَاتِهِ، اُخْتُرِعَتْ سَنَةَ 1829 م."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6325, 'أُرْدُنُ', 'أردن', 'جامد', '', 'ءردن', 'ردن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rp', '', 'N', 'O', 'N', 'O', '', '": مِنَ البُلْدَانِ العَرَبِيَّةِ (الْمَمْلَكَةُ الأرْدُنِيَّةُ الهاشِمِيَّةُ) عاصِمَتُهَا عَمَّان."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6326, 'حَبَشَة', 'حبشة', 'جامد', '', 'حبشة', 'حبشة', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', 'N', 'O', 'N', 'O', '', '": بَلَدٌ من البُلْدانِ الإِفْريقِيَّةِ تَقَعُ شَرْقَ إِفْريقِيا تُعْرَفُ بِإثيوبِيا، عاصِمَتُها أَديس أَبابا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6327, 'أُلْفَةٌ', 'ألفة', 'جامد', 'ألف', 'ءلفة', 'لفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"أُلْفَةٌ-أُلْفَةٌ [أ ل ف]. 1.""تَكَوَّنَتْ أُلْفَةٌ بَيْنَهُمَا"" : صَدَاقَةٌ، مُؤَانَسَةٌ. 2.""وَجَدَ أُلْفَةً فِي مُعَاشَرَتِهِ"" : أَي انْسِجَاماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6328, 'أَلْفِيَّةٌ', 'ألفية', 'جامد', 'ألف', 'ءلفية', 'لفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"أَلْفِيَّةٌ-أَلْفِيَّةٌ [أ ل ف]. ""أَلْفِيَّةُ اِبْنِ مَالِك"" : مَنْظُومَةٌ شِعْرِيَّةٌ حَوْلَ قَوَاعِدِ اللُّغَةِ، عَدَدُ أَبْيَاتِهَا أَلْفُ بَيْتٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6329, 'ألْفٌ', 'ألف', 'جامد', '', 'ءلف', 'لف', '', '', '', 'جمع تكسير', 'DnN', '', '', '"ألُوفٌ:آلاَفٌ"', '', 'R', '', '', '', '', '', '', '"ج: ألُوفٌ، آلاَفٌ. 1.""كَانَتْ تَنْقُصُهُ دَرَاهِمُ مَعْدُودَةٌ لِيُكَمِّلَ ألْفَ دِرْهَمٍ"" : أيْ 10 مِئاتِ دِرْهَمٍ (1000). 2.""كَانَ يَتَصَرَّفُ فِي الألُوفِ الْمُؤَلَّفَةِ"" : فِي آلاَفٍ عَدِيدَةٍ. 3.""مُنْذُ ألْفِ عَامٍ"" : أَيْ مُنْذُ عَشْرَةِ قُرُونٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6330, 'ألُوفٌ', 'ألوف', 'جامد', '', 'ءلوف', 'لف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6331, 'آلاَفٌ', 'آلاف', 'جامد', '', 'ءءلاف', 'آلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6332, 'أَلِفْبَاءٌ', 'ألفباء', 'جامد', '', 'ءلفباء', 'لفب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rz', '', 'N', 'O', 'N', 'O', '', '": اِخْتِزَالٌ لِمَجْمُوعِ الحُرُوفِ الهِجَائِيَّةِ الْمُرَتَّبَةِ حَسَبَ تَشَابُهِهَا فِي الرَّسْمِ. ا ب ت ث ج ح خ د ذ ر ز س ش ص ض ط ظ ع غ ف ق ك ل م ن هـ و ي."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6333, 'إلْقٌ', 'إلق', 'جامد', 'ألق', 'ءلق', 'إلق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"إلْقٌ-إلْقٌ [أ ل ق]. ""رَجُلٌ إِلْقٌ"": كَذُوبٌ، سَيِّئُ الْخُلُقِ. 2.: ذِئْبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6334, 'إلِكْتُرُونٌ', 'إلكترون', 'جامد', '', 'ءلكترون', 'إلكترن', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'Rp', '', 'N', 'O', 'O', 'O', '', '"ج: ـا ت. (كيما).‏: عُنْصُرٌ أوَّلُ ثَابِتٌ ذُو شِحْنَةٍ كَهْرَبَائِيَّةٍ سَلْبِيَّةٍ، أسَاسُ الآلِيَّاتِ الإلِكْتُرونِيَّةِ، وَهُوَ أحَدُ الْمُكَوِّنَاتِ فِي ذَرَّاتِ الْمَادَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6335, 'اللهُ', 'الله', 'جامد', '', 'الله', 'لله', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'N', 'N', 'O', '', '"1.: اِسْمُ الجَلاَلَةِ. الإلَهُ الْمَعْبُودُ بحَقٍّ: البقرة آية 255 اللهُ لاَ إلَهَ إلاَّ هُوَ (قرآن) : الخَالِقُ، وَأصْلُ كَلِمَةِ اللهِ إلاهٌ، دَخَلَتْ عَلَيْهِ ألْ، ثُمَّ حُذِفَتْ هَمْزَتُهُ وَأُدْغِمَ اللامَانِ. 2.""اَللَّهُمَّ إنَّكَ تَعْلَمُ سَرِيرَتِي"": أيْ يَا اللهُ. وَقَدْ حُذِفَ حَرْفُ النِّدَاءِ وَعُوِّضَ بِالمِيمِ الْمُشَدَّدَةِ وَلاَ يُجْمَعُ مَا بَيْنَ حَرْفِ النِّدَاءِ وَالمِيمِ، أيْ لاَ يُقَالُ يا اَللَّهُمَّ. ن. اَللَّهُمَّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6336, 'اللَّهُمَّ', 'اللهم', 'جامد', '', 'اللهم', 'للهم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'N', 'N', 'O', '', '"1.الزمر آية 46قُلِ اللَّهُمَّ فَاطِرَ السَّمَوَاتِ وَالأرْضِ (قرآن): أيْ يَا اللَّهُ. 2.""اللَّهُمَّ اجْعَلْنَا شَاكِرِينَ لِنعْمَتِكَ وَتُبْ عَلَيْنَا إنَّكَ أنْتَ التَّوَّابُ الرَّحِيمُ"" : اِسْتِعْمَالٌ لِلنِّدَاءِ الحَقِيقِيِّ. ""اللهُمَّ تَقَبَّلْ دُعَائِي"". 3.""أمُحَمَّدٌ فِي البَيْتِ: الَّلهُمَّ نَعَمْ"" : وَهِيَ هُنَا لِتَمْكِينِ الجَوَابِ فِي ذِهْنِ السَّامِعِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6337, 'أَلْمَاسُ', 'ألماس', 'جامد', '', 'ءلماس', 'لمس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'O', 'O', 'O', '', '"أَلْمَاسُ-أَلْمَاسُ (كيما).: حَجَرٌ كَرِيمٌ نَادِرٌ بِلَّوْرِيٌ مِنْ أشَدِّ الْمَعَادِنِ لَمَعاناً وَصَلاَبَةً وَأقْسَاهَا. ""وَضَعَتْ خَاتَماً مِنَ الأَلْمَاسِ فِي أُصْبُعِهَا""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6338, 'إلَهٌ', 'إله', 'جامد', 'أله', 'ءله', 'إله', '', '', '', 'مفرد', 'DnN', '', '', '"آلِهَةٌمؤإلَهَةٌ"', '', 'Rp', '', '', '', '', '', '', '". ""يَعْبُدُ إلاَهاً وَاحِداً"": مَعْبُوداً وَاحِداً. ""لاَ إلَهَ إلاَّ اللهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6339, 'آلِهَةٌ', 'آلهة', 'جامد', '', 'ءءلهة', 'آلهة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6340, 'إلَهِيَّاتٌ', 'إلهيات', 'جامد', 'أله', 'ءلهيات', 'إلهت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"إلَهِيَّاتٌ-إلَهِيَّاتٌ [أ ل هـ].: كُلُّ ما يَتَعَلَّقُ بِذَاتِ الإلَهِ وَصِفَاتِهِ وَ يُعالِجُ مَا لَهُ عَلاَقَةٌ بِالقَضَايَا الإلاَهِيَّةِ، وَفَلْسَفَةِ مَا وَرَاءَ الطَّبِيعَة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6341, 'ألُومِنْيُوم', 'ألومنيوم', 'جامد', '', 'ءلومنيوم', 'لمنم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ألُومِنْيُوم-ألُومِنْيُوم (كما).: مَعْدِنٌ خَفِيفٌ أبْيَضُ فِضِّيٌّ، مَتِينٌ وَبَسِيطٌ، قَابِلٌ لِلصَّهْرِ وَالسَّحْبِ، يَنْقُلُ الحَرَارَةَ وَالكَهْرَبَاءَ جَيِّداً، يُسْتَعْمَلُ بِكَثْرَةٍ فِي صِنَاعَةِ الأوَانِي الْمَنْزِلِيَّةِ وَغَيْرِهَا. ""إنَاءٌ مَصْنُوعٌ مِنْ مَادَّةِ الأَلومِنْيومِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6342, 'أَلَى', 'ألى', 'جامد', 'ألي', 'ءلى', 'ل', '', '', '', 'مفرد', 'Dy', '', '', '"آلاَءٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""أَلاَهُ كَبِيرٌ عَلَيَّ"" : نِعْمَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6343, 'آلاَءٌ', 'آلاء', 'جامد', '', 'ءءلاء', 'آل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6344, 'إلْيٌ', 'إلي', 'جامد', '', 'ءلي', 'إل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"آلاءٌ"', '', '', '', '', '', '', '', '', '"ج: آلاءٌ. ""إِلْيُهُ عَلَيَّ كَبيرٌ"" : نِعْمَتُهُ، آلاَهُ.الأعراف آية 69فاذْكُرُوا آلاَءَ اللهِ لَعَلَّكُمْ تُفْلِحُونَ (قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6345, 'آلاءٌ', 'آلاء', 'جامد', '', 'ءءلاء', 'آل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6346, 'ألْيَةٌ', 'ألية', 'جامد', '', 'ءلية', 'لة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":أَلاَيَامثنىألْيتَانِ"', '', '', '', '', '', '', '', '', '"ج: أَلاَيَا، أَلَياتٌ. مثنى: ألْيتَانِ.: العَجيزَةُ أَوْ ما رَكَبَها مِنْ شَحْمٍ وَلَحْمٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6347, 'أَلاَيَا', 'ألايا', 'جامد', '', 'ءلايا', 'ل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6348, 'أُمٌّ', 'أم', 'جامد', '', 'ءم', 'م', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أُمَّهَاتٌ"', '', 'R', '', '', '', '', '', '', '"ج: أُمَّهَاتٌ. 1.""حَنَّتِ الأُمُّ عَلَى ابْنِهَا"" : الوَالِدَةُ الَّتِي حَمَلَتْ بِهِ تِسْعَةَ أَشْهُرٍ. الأمُّ مَدْرَسَـةٌ إذَا أعْدَدْتَهَـا*أعْـدَدْتَ شَعْباً طَيِّبَ الأَعْـرَاق (حافظ إبراهيم). الجَنَّةُ تَحْتَ أَقْدَامِ الأُمَّهَاتِ (حديث). 2.""رَأَيْتُهُ بِأُمِّ عَيْنَيَّ"" : رَأيْتُهُ بِنَفْسِي رُؤْيَةً لاَ مَجَالَ للِشَّكِّ فِيهَا. 3.""أُمُّ البَشَرِ"" : حَوَّاءُ. 4.""أُمُّ أَرْبَعٍ وَأَرْبَعينَ"" : فَصِيلَةُ الحَيَوَانَاتِ الْمَفْصِلِيَّةِ، وَهِيَ دُوَيْبَّةٌ سَامَّةٌ لَهَا أرْجُلٌ كَثِيرَةٌ. 5.""ضَرَبَهُ عَلَى أُمِّ رَأسِهِ"" : الجِلْدَةُ الَّتِي تَجْمَعُ الدِّمَاغَ. 6.""أُمُّ الدِّماغِ"" : الجِلْدَةُ الرَّقيقَةُ الْمُحيطَةُ بِالد"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6349, 'أُمَّهَاتٌ', 'أمهات', 'جامد', '', 'ءمهات', 'مهت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6350, 'إمْبراطُورٌ', 'إمبراطور', 'جامد', '', 'ءمبراطور', 'إمبرطر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"أبَاطِرَةٌ"', '', 'Rp', '', '', '', '', '', '', '"ج: أبَاطِرَةٌ.: لَقَبٌ خَاصٌّ بِكُلِّ حَاكِمٍ يَحْكُمُ إمْبِرَاطُورِيَّةً، وَقَدْ يُطْلَقُ اعْتِبَاطاً وَلوْ مَعَ عَدَمِ وُجُودِ إمْبرَاطُورِيَّةٍ، مثل : إمْبرَاطُورُ اليَابَانِ. وَتُعْتَبَرُ زَوْجَةُ الإمْبِرَاطُورِ، إمْبرَاطُورَةً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6351, 'أبَاطِرَةٌ', 'أباطرة', 'جامد', '', 'ءباطرة', 'بطرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6352, 'أَمْبِير', 'أمبير', 'جامد', '', 'ءمبير', 'مبر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"أَمْبِير-أَمْبِير (فز).: وَحْدَةُ كَثَافَةٍ مِنْ وَقُوَّةُ التِّيَّارِ الكَهْرَبَائِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6353, 'أمْبِيريَّةٌ', 'أمبيرية', 'جامد', '', 'ءمبيرية', 'مبرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '": التَّيَّارُ الكَهْرَبَائِيُّ الْمَحْبُوسُ بِالأَمْبيرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6354, 'أَمَدٌ', 'أمد', 'جامد', 'أمد', 'ءمد', 'مد', '', '', '', 'مفرد', 'DnN', '', '', '"آمادٌ"', '', 'R', '', '', '', '', '', '', '". 1.""طالَ عَلَيْهِمُ الأَمَدُ"" : الوَقْتُ، الزَّمانُ. ""مُنْذُ أَمَدٍ بَعيدٍ"" ""مُنْذُ أَمَدٍ غَيْرِ بَعيدٍ"". 2.""أَنْجَزَ العَمَلِيَّةَ الحِسابِيَّةَ في أَمَدٍ قَصيرٍ"" : في وَقْتٍ قَصيرٍ، في فَتْرَةٍ، في بُرْهَةٍ. 3."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6355, 'آمادٌ', 'آماد', 'جامد', '', 'ءءماد', 'آمد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6356, 'أمَارَةٌ', 'أمارة', 'جامد', 'أمر', 'ءمارة', 'مرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""ظَهَرَتْ عَلَيْهِ أَمَارَاتُ الفَرَحِ"" : عَلاَمَاتُ ... 2.""أَمَارَاتُ الوَجْهِ"" : تَجَاعِيدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6357, 'إِمْرَةٌ', 'إمرة', 'جامد', 'أمر', 'ءمرة', 'إمرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"إِمْرَةٌ-إِمْرَةٌ [أ م ر]. ""كانَ تَحْتَ إِمْرَتِهِ"" : قِيادَتِهِ، سُلْطَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6358, 'مَأْمُورِيَّةٌ', 'مأمورية', 'جامد', 'أمر', 'مءمورية', 'ممرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1. وَحْدَةٌ إِدَارِيَّةٌ تَحْتَ إِشْرَافِ مَأْمُورٍ. 2.""عُيِّنَ فِي مَأْمُورِيَّةٍ عَاجِلَةٍ"" : فِي مُهِمَّةٍ أَوْ مَسْؤُولِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6359, 'مُؤْتَمَرٌ', 'مؤتمر', 'جامد', 'أمر', 'مءتمر', 'متمر', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""الْمُؤْتَمَرُ الوَطَنِيُّ لِلْحِزْبِ"" : مُجْتَمَعُ أَعْضَائِهِ لِلْحِوَارِ وَالتَّشَاوُرِ وَالبَحْثِ فِي مُجْمَلِ القَضَايَا الَّتِي تَهِمُّهُ. ""الْمُؤْتَمَرُ العَاشِرُ لِلْحِزْبِ"". 2.""مُؤْتَمَرُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6360, 'اِمْرَأَةٌ', 'امرأة', 'جامد', '', 'امرءة', 'مرة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"نِساءٌ:نِسْوَةٌ:نِسْوانٌمِنْغ', '', '', '', 'O', 'N', 'O', 'O', '', '"ج: نِساءٌ، نِسْوَةٌ، نِسْوانٌ مِنْ غَيْرِ لَفْظِها. اِمْرَأَةٌ عِنْدَ التَّنْكيرِ والْمَرْأَةُ عِنْدَ التَّعْريفِ. 1.""الْمَرْأَةُ نِصْفُ الرَّجُلِ"" : الأنْثَى شَريكَةُ حَياةِ الرَّجُلِ. 2.""اِمْرَأَةُ العَزيزِ"" : زَوْجَةُ مَلِكِ مِصْرَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6361, 'نِساءٌ', 'نساء', 'جامد', '', 'نساء', 'نس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6362, 'نِسْوَةٌ', 'نسوة', 'جامد', '', 'نسوة', 'نسة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6363, 'نِسْوانٌ', 'نسوان', 'جامد', '', 'نسوان', 'نسن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6364, 'الْمَرْأَةُ', 'المرأة', 'جامد', '', 'المرءة', 'لمرة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"اِمْرَأَةٌعِنْدَالتَّنْكيرِوا', 'ممنوع من الصرف', '', '', 'N', 'N', 'N', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6365, 'اِمْرُؤٌ', 'امرؤ', 'جامد', '', 'امرء', 'مر', '', '', '', 'جمع تكسير', 'Dz', '', '', '"عِنْدَالتَّذْكيرِمؤاِمْرَأَةٌ', '', '', '', 'O', 'N', 'O', 'O', '', '"عِنْدَ التَّذْكيرِ. مؤ: اِمْرَأَةٌ، والْمَرْءُ عِنْدَ التَّعْريفِ والجَمْعُ مِنْ غَيْرِ لَفْظِهِ وَكِتابَتُها حَسَبَ إِعْرابِها (اِمْرُؤٌ، اِمْرَأً، اِمْرِئٍ). ""كُلُّ امْرِئٍ وَنَصيبُهُ"" : كُلُّ إِنْسانٍ، كُلُّ رَجُلٍ، كُلُّ واحِدٍ. لِكُلِّ اِمْرئٍ ما نَوَى (حديث)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6366, 'الْمَرْءُ', 'المرء', 'جامد', '', 'المرء', 'لمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'N', 'N', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6367, 'أَمْرِيكا', 'أمريكا', 'جامد', '', 'ءمريكا', 'مرك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'N', 'N', 'O', '', '"أَمْرِيكا-أَمْرِيكا (جغ).: مِنَ القارَّاتِ الخَمْسِ، وَهيَ ما يُعْرَفُ بِأَمْريكا الشَّمالِيَّةِ وَأَمريكا الجَنوبِيَّةِ، تُقَدَّرُ مِساحَتُها بـ 42 مليون كلم‌²، وعَدَدُ سُكَّانِها بـ 675 مليون نَسَمة."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6368, 'إِمَّعٌ', 'إمع', 'جامد', 'إمع', 'ءمع', 'إمع', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"إِمَّعٌ-إِمَّعٌ، إِمَّعَةٌ [إ م ع]. ""رَجُلٌ إِمَّعٌ أَو إِمَّعَةٌ"" : الْمُتَرَدِّدُ الَّذِي لا يَثْبُتُ على رَأيٍ، وَيُوافِقُ كُلَّ واحِدٍ على رَأْيِهِ. وَتُزادُ التَّاءُ فيهِ لِلْمُبالَغَةِ. اُغْدُ عالِماً أَوْ مُتَعَلِّماً وَلا تَكُنْ إِمَّعَةً (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6369, 'إمَامٌ', 'إمام', 'جامد', 'أمم', 'ءمام', 'إمم', '', '', '', 'مفرد', 'DnN', '', '', '"أئِمَّةٌ:أَيِمّةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَقَفَ إمَامُ الْمَسْجِدِ يُصَلِّي بِالنَّاسِ"" : مَنْ يُقِيمُ الصَّلاَةَ بِالنَّاسِ، أيْ مَنْ يَؤُمُّ النَّاسَ. 2.""إمَامُ الْمُسْلِمِينَ"" : الخَلِيفَةُ الحَاكِمُ، كَبِيرُ القَوْمِ.الإسراء آية 71 يَوْمَ نَدْعُوا كُلَّ أُنََاسٍ بِإمَامِهِمْ (قرآن). 3.""إمَام"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6370, 'أئِمَّةٌ', 'أئمة', 'جامد', '', 'ءءمة', 'مة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6371, 'أَيِمّةٌ', 'أيمة', 'جامد', '', 'ءيمة', 'مة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6372, 'أُمَّةٌ', 'أمة', 'جامد', 'أمم', 'ءمة', 'مة', '', '', '', 'مفرد', 'DnN', '', '', '"أُمَمٌ"', '', '', '', '', '', '', '', '', '". 1.""جَمَاعَةٌ مِنَ النَّاسِ تَجْمَعُهُمْ رَوَابِطُ تَارِيخِيَّةٌ مُشْتَرَكَةٌ، قَدْ يَكُونُ فِيهَا مَا هُوَ لُغَوِيٌّ أوْ دِينِيٌّ أوِ اقْتِصَادِيٌّ وَلَهُمْ أهْدَافٌ مُشْتَرَكَةٌ فِي العَقِيدَةِ أَوِ السِّيَاسَةِ أَوِ الاقْتِصَادِ. "" الأُمَّةُ العَرَبِيَّةُ"" ""الأُمَّةُ الإسْلاَمِيّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6373, 'أُمَمٌ', 'أمم', 'جامد', '', 'ءمم', 'م', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6374, 'أُمِّيَّةٌ', 'أمية', 'جامد', 'أمم', 'ءمية', 'مة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"أُمِّيَّةٌ-أُمِّيَّةٌ [أ م م]. 1.""كانَتِ الأُمِّيَّةُ مُنْتَشِرَةً بَيْنَ النَّاسِ"": عَدَمُ شُيوعِ الكِتابَةِ وَالقِراءةِ، أَي الجَهْلُ بِهِما. إِنَّا أُمَّةٌ أُمِّيَّةٌ لا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6375, 'مَأْمَنٌ', 'مأمن', 'جامد', 'أمن', 'مءمن', 'ممن', '', '', '', 'مفرد', 'DnN', '', '', '"مَآمِنُ"', '', 'R', '', '', '', '', '', '', '". ""فِي مَأْمَنٍ مِنْ كُلِّ خَطَرٍ"" : أَيْ هُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6376, 'مَآمِنُ', 'مآمن', 'جامد', '', 'مءءمن', 'مآمن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6377, 'أمَةٌ', 'أمة', 'جامد', 'أمو', 'ءمة', 'مة', '', '', '', 'مفرد', 'DnN', '', '', '"إمَاءٌ"', '', '', '', '', '', '', '', '', '". ""جَلَسَتِ الأَمَةُ أمَامَ سَيِّدِهَا تَنْتَظِرُ مِنْهُ إشَارَةً"" : خَادِمَةٌ مِنَ العَبِيدِ كَانَتْ تَشْتَغِلُ فِي العُصُورِ القَدِيمَةِ فِي البُيُوتِ الكَبِيرَةِ وَتُسَخَّرُ لِكُلِّ الأَغْرَاضِ. ""اِنْتَهَى عَهْدُ الإمَاءِ""."', '');
