INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6379, 'أَمونْيُوم', 'أمونيوم', 'جامد', '', 'ءمونيوم', 'منم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": جِذْرٌ يَدْخُلُ في تَرْكيبِ الأَمْلاحِ النُّشادِرِيَّةِ وَيَقومُ بِدَوْرِ فِلِزٍّ أُحادِيِّ التَّكافُؤ."', ':لا جذر:لا مفرد');
