INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6383, 'أَناناسٌ', 'أناناس', 'جامد', '', 'ءناناس', 'ننس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": نَباتٌ عُشْبِيٌّ مِنْ فَصيلَةِ الأناناسِيَّاتِ على شَكْلِ كُرَةٍ مُسْتَطيلَةٍ، لَذيذُ الطَّعْمِ، طَيِّبُ الرَّائِحَةِ، يُزرَعُ في البُلْدانِ الاِسْتِوائِيَّةِ."', ':لا جذر:لا مفرد');
