INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6394, 'أَنْدَلُسُ', 'أندلس', 'جامد', '', 'ءندلس', 'ندلس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rp', '', 'N', 'O', 'N', 'O', '', '": بِلادُ جَنُوبِ إِسْبانِيا، وَهُوَ الاسْمُ الَّذِي أَطْلَقَهُ العربُ عَلَيْها حِينَ فَتَحوها سنة 671م/ 92هـ، واسْتَقَرُّوا فِيها إلى غايَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6395, 'إِنْسٌ', 'إنس', 'جامد', 'أنس', 'ءنس', 'إنس', '', '', '', 'مفرد', 'DnN', '', '', '"أُناسٌ"', '', 'R', '', '', '', '', '', '', '"ج: أُناسٌ. (أ ن س). 1.النمل آية 17وَحُشِرَ لِسُلَيْمانَ جُنودُهُ مِنَ الجِنِّ والإِنْسِ والطَّيْ"', '');
