INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6400, 'إِنْسانٌ', 'إنسان', 'جامد', '', 'ءنسان', 'إنسن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَناسِيُّ:أَناسِيَةٌ"', '', 'Rp', '', '', '', '', '', '', '"ج: أَناسِيُّ، أَناسِيَةٌ. 1.""خَلَقَ اللَّهُ الإِنْسانَ وَصَوَّرَهُ أَحْسَنَ تَصْويرٍ"" : اِسْمٌ يُطْلَقُ على الكائِنِ البَشَرِيِّ. ""العَقْلُ زينَةُ الإِنْسانِ"". 2.""هُوَ إِنْسانٌ مِثالِيٌّ"" : شَخْصٌ يَمْتازُ بِصِفاتٍ نَمُوذَجِيَّةٍ غَيْرِ عادِيَةٍ. ""لِكُلّ"', ':لا جذر:لا مفرد');
