INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6402, 'أَناسِيَةٌ', 'أناسية', 'جامد', '', 'ءناسية', 'نسة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6403, 'أَنْسُولِين', 'أنسولين', 'جامد', '', 'ءنسولين', 'نسلن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": هرمون يَتَوَلَّدُ نَتيجَةَ إِفْرازَاتِ غُدَدٍ في البَنْكِرْياسِ، وَتَعطُّلُها يُؤَدِّي إلى مَرَضِ البَوْلِ السُّكَّرِيِّ."', ':لا جذر:لا مفرد');
