INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6405, 'أَنْفٌ', 'أنف', 'جامد', '', 'ءنف', 'نف', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أُنوفٌ"', '', 'R', '', '', '', '', '', '', '"ج: أُنوفٌ.: عَضْوُ حاسَّةِ الشَّمِّ وَالتَّنَفُّس عِنْدَ الإِنْسانِ والحَيَوانِ، وَهُوَ مِنْ أَعْضاءِ الحَواسِّ الخَمْسِ. 1.""لَهُ أَنْفٌ أَفْطَسُ"" : مَنْ كانَتْ قَصَبَةُ أَنْفِهِ مُنْخَفِضَةً. 2.""اِقْتَرَبَ مِنْ أَنْفِ الجَبَلِ"" : نُتوءٌ بِالجَبَلِ، أَيْ ما خَرَجَ مِنْهُ. 3.""سَيُؤَدِّي ما عَلَيْهِ على الرَّغْمِ مِنْ "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6406, 'أُنوفٌ', 'أنوف', 'جامد', '', 'ءنوف', 'نف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6407, 'أَنْقَلِيسٌ', 'أنقليس', 'جامد', '', 'ءنقليس', 'نقلس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": سَمَكٌ مِنْ فَصيلَةِ الأَنْقَليسِيَّاتِ، طَويلٌ لَهُ ظَهْرٌ أَسْمَرُ مُخْضَرٌّ أَوْ مُسْوَدٌّ، وَبَطْنٌ مُصْفَـرٌّ أَوْ فِضِّيٌّ، لَـهُ زَعانِفُ صَغيرَةٌ مَلْساءُ الجِلْدِ، يُعْرَفُ في الْمَغْرِبِ بـ ""النُّونِ""، وَفي مِصْرَ بـ""ثُعْبانِ الماءِ"". وَفي العِراقِ بـ ""الْمَرْمَريج""، يَعِيشُ في النَّهْرِ والبَحْرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6408, 'أَنْقَليسِيَّاتٌ', 'أنقليسيات', 'جامد', '', 'ءنقليسيات', 'نقلست', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصيلَةُ أَسْماكِ مُتَمَيِّزَةٌ بِطولِها، تَعيشُ في البِحارِ والأنْهارِ، مِنْ أَشْهَرِ أَنْواعِها الأَنْقَلِيسُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6409, 'أُنْمُوذَجٌ', 'أنموذج', 'جامد', '', 'ءنموذج', 'نمذج', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":نَمَاذِجُ"', '', 'R', '', '', '', '', '', '', '"ج: نَمَاذِجُ، أُنْمُوذَجَاتٌ. 1.""كَانَ أُنْمُوذَجاً لِرِفَاقِهِ"" : مِثَالاً. 2.""وَضَعَ أُنْمُوذَجاً لِتَقْلِيدِهِ"" : شَكْلاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6410, 'نَمَاذِجُ', 'نماذج', 'جامد', '', 'نماذج', 'نمذج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6411, 'أَنُوقٌ', 'أنوق', 'جامد', '', 'ءنوق', 'نق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1.(حو): مِنْ فَصِيلَةِ النَّسْرِيَّاتِ، مِنْ رُتْبَةِ الجَوَارِحِ، لَهُ رَأْسٌ وَعُنُقٌ عَارِيَانِ مُلَوَّنانِ، يَتَغَذَّى مِنَ الجِيَفِ، وَيُسَمَّى أَيْضاً العُقَـابُ. 2.""أعَزُّ مِنْ بَيْضِ الأَن"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6412, 'آنَاءٌ', 'آناء', 'جامد', 'أني', 'ءءناء', 'آن', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', 'N', 'O', 'O', 'O', '', '"آنَاءٌ - [أ ن ي]. ""آناءُ الليْلِ"" : سَاعَاتُهُ.طه آية 130وَمِنْ آنَاءِ اللَّيْلِ فَسَبِّحْ وَأطرَافِ النَّهَارِ لَعَلَّكَ تَرْضَى (قرآن) "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6413, 'إِناءٌ', 'إناء', 'جامد', 'أني', 'ءناء', 'إن', '', '', '', 'مفرد', 'Dz', '', '', '"آنِيَةٌجأَوانٍ:الأوانِي"', '', 'Rz', '', '', '', '', '', '', '". ""لَمْ يَبْقَ إِناءٌ واحِدٌ، كُلُّ الأوانِي تَكَسَّرَتْ"" : الوِعاءُ، الصَّحْنُ، ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6414, 'آنِيَةٌ', 'آنية', 'جامد', '', 'ءءنية', 'آنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6415, 'أوانِي', 'أواني', 'جامد', '', 'ءواني', 'ن', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6416, 'إنْيٌ', 'إني', 'جامد', '', 'ءني', 'إن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"آنَاءٌ"', '', '', '', '', '', '', '', '', '"ج: آنَاءٌ. ""إنْيُ الَّليْلِ"" : سَاعَةٌ مِنْ سَاعَاتِ اللَّيْلِ، أيْ جُزْءٌ مِنَ الَّليْلِ.طه آية 130وَمِنْ آنَاءِ اللَّيْلِ فَسَبِّحْ وَأطْرَافَ النَّهَارِ لَعَلَّكَ تَرْضَى (قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6417, 'آنَاءٌ', 'آناء', 'جامد', '', 'ءءناء', 'آن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6418, 'إهَابٌ', 'إهاب', 'جامد', 'أهب', 'ءهاب', 'إهب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"إهَابٌ-إهَابٌ [أ هـ ب]. 1.: الجِلْدُ أوْ مَا لَمْ يُدْبَغْ مِنْهُ. 2.""كَادَ الفَرَسُ يَخْرُجُ مِنْ إهَابِهِ"" : أيْ مِنْ نَشَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6419, 'أُهْبَةٌ', 'أهبة', 'جامد', 'أهب', 'ءهبة', 'هبة', '', '', '', 'مفرد', 'DnN', '', '', '"أُهَبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""كَانَ عَلَى أُهْبَةِ السَّفَرِ"": عَلَى وَشْكِ السَّفَرِ. ""إنَّ الطَّائِرَةَ عَلَى أُهْبَةِ الإِقْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6420, 'أُهَبٌ', 'أهب', 'جامد', '', 'ءهب', 'هب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6421, 'أهْرَامٌ', 'أهرام', 'جامد', '', 'ءهرام', 'هرم', '', '', '', 'جمع تكسير', '', '', '', '"مفردهَرَمٌ"', '', 'R', '', '', '', '', '', '', '"جمع هَرَمٌ. ن.هَرَم."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6422, 'هَرَمٌ', 'هرم', 'جامد', '', 'هرم', 'هرم', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6423, 'أهْلِيَّةٌ', 'أهلية', 'جامد', 'أهل', 'ءهلية', 'هلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"أهْلِيَّةٌ-أهْلِيَّةٌ [أ هـ ل]. 1.""لَهُ مِنَ الأهْلِيَّةِ مَا يُؤَهِّلُهُ لِلْقِيامِ بِهَذَا العَمَلِ"" : الصَّلاحِيَّةُ، الجَدَارَةُ. 2.""هُوَ كَامِلُ الأَهْلِيَّةِ"" : لَهُ الصَّلاَحِيَّةُ الكَامِلَةُ، القُدْرَةُ الكَامِلَةُ. ""عَدَمُ الأهْلِيَّةِ"". 3.""شَهَادَةُ الأهْلِيَّةِ"" : شَهَادةُ الكَفَاءةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6424, 'أهْلٌ', 'أهل', 'جامد', '', 'ءهل', 'هل', '', '', '', 'جمع تكسير', 'DnN', '', '', '":أهَالٍ:الأهَالِي"', '', 'R', '', '', '', '', '', '', '"ج: أهْلُونَ، أهَالٍ، الأهَالِي. 1.""ظَلَّ مُرْتَبِطاً بِأهْلِهِ"": بِأقْرِبَائِهِ. ¨""زَاروا أَهْلَنا، وَزُرْنا أَهْلَهُمْ، أَهْلُكُمْ أَهْلُنا"". 2.""دَخَلَ عَلَى أهْلِهِ ليْلَةَ الزِّفَافِ"" : عَلَى زَوْجَتِهِ. 3.""مَنْ يَعْرِفُ أهْلَ الدَّارِ"" : سُكَّانَهَا. 4.""حَلُّ هَذِهِ القَضِيَّةِ بِيَدِ أهْلِ الأمْرِ"" : الحُكَّامُ "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6425, 'أهَالِي', 'أهالي', 'جامد', '', 'ءهالي', 'هل', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6426, 'أهْوَازٌ', 'أهواز', 'جامد', '', 'ءهواز', 'هز', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": مناطِقُ تَجْتَمِعُ فِيهَا المسَاكِنُ وَالقُرَى بَيْنَ البَصْرَةِ فِي العِراقِ وَبِلادِ فَارِسَ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6427, 'أوَانٌ', 'أوان', 'جامد', '', 'ءوان', 'ن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"آوِنَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: آوِنَةٌ. 1. ""هَذَا أوَانُ البَرْدِ"" : فَصْلُهُ. 2. ""لِكُلِّ شَيْءِ أوَانُهُ"" : وَقْتُهُ. ""هَذَا هُوَ الأوَانُ"" 3. ""وَصَلَ بَعْدَ فَوَاتِ الأوَانِ"" : الزَّمَنُ الْمُحَدَّدُ. يُقَالُ : قَبْلَ أوَانِهِ، وَفِي أَوَانِهِ، وَفِي غَيْرِ أوَانِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6428, 'آوِنَةٌ', 'آونة', 'جامد', '', 'ءءونة', 'آنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6429, 'أوْبَةٌ', 'أوبة', 'جامد', 'أوب', 'ءوبة', 'بة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"أوْبَةٌ-أوْبَةٌ [أ و ب]. ""يَنْتَظِرُ أوْبَتَهُ"" : رُجُوعَهُ، عَودَتَهُ. ""لَمْ تَكُنْ أوْبَتُهُ مَأمُونَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6430, 'أَوْباشٌ', 'أوباش', 'جامد', '', 'ءوباش', 'بش', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""هُوَ مِنَ الأوْبَاشِ"" : مِنْ سَفَلَةِ النَّاسِ وَأخْلاطِهِمْ. ""تَجَنَّبْ مُخَالَطَةَ الأوْبَاشِ يَا وَلَدِي""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6431, 'أُوت', 'أوت', 'جامد', '', 'ءوت', 'ت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ الثَّامِنُ مِنَ الشُّهُورِ الشَّمْسِيَّةِ، ويُسَمَّى أيْضاً أُغُسْطُسَ، غشت. ن. آب."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6432, 'أوْجٌ', 'أوج', 'جامد', '', 'ءوج', 'ج', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1.""كَانَ فِي أوْجِ عَظَمَتِهِ، أوْ مَجْدِهِ"" : فِي عُلُوٍّ، فِي قِمَّةٍ. ""وَصَلَ إلَى الأوْجِ"" ""حَضَارَةٌ فِي أوْجِهَا"". 2.""أوْجُ القَمَرِ"" : أبْعَدُ نُقْطَةٍ فِي مَدَارِ القَمَرِ عَنِ الأرْضِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6433, 'آح', 'آح', 'جامد', 'أوح', 'ءءح', 'آح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"آح-آحٌ [أ و ح]. : زُلاَلُ البَيْضَةِ، أيْ بَيَاضُهَا، وَالْمَاحُ صُفْرَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6434, 'أُوَارٌ', 'أوار', 'جامد', 'أور', 'ءوار', 'ر', '', '', '', 'مفرد', 'DnN', '', '', '"أُوْرٌ"', '', 'R', '', '', '', '', '', '', '". 1.""لَفَحَنِي أُوَارُ الشَّمْسِ"" : حَرُّهَا. 2.""لَفَحَنِي أُوَارُ النَّارِ"" : حَرُّهَا. 3.""بِهِ أُوَارٌ"" : شِدَّةُ العَطَشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6435, 'أُوْرٌ', 'أور', 'جامد', '', 'ءور', 'ر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6436, 'أُورَانْيُوم', 'أورانيوم', 'جامد', '', 'ءورانيوم', 'رنم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"أُورَانْيُوم-أُورَانْيُوم (كيما).: عُنْصُرٌ مَعْدِنِيٌّ قَلِيلُ الإشْعَاعِ يُوجَدُ فِي الطَّبِيعَةِ بِشَكْلِ أُكْسِيدِ الأورَانْيُوم، يَدْخُلُ فِي صُنْعِ بَعْضِ القَنَابِل الذَّرِّيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6437, 'أُورثُوذُكْس', 'أورثوذكس', 'جامد', '', 'ءورثوذكس', 'رثذكس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": أتْبَاعُ الكَنِيسَةِ الأورثوذُكْسِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6438, 'أُورُوبَّا', 'أوروبا', 'جامد', '', 'ءوروبا', 'رب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'N', 'N', 'O', '', '"أُورُوبَّا-أُورُوبَّا (جغ).: مِنَ القَارَّاتِ الخَمْسِ، تُقَدَّرُ مِسَاحَتُهَا بـ 10 مليون كلم² وَعَدَدُ سُكَّانِهَا بـ 495 مليون نسمة."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6439, 'إوَزَّةٌ', 'إوزة', 'جامد', 'أوز', 'ءوزة', 'إزة', '', '', '', 'مفرد', 'DnN', '', '', '"إوَزٌّ"', '', 'R', '', '', '', '', '', '', '"(حو).: طَائِرٌ مَائِيٌّ مِنْ فَصِيلَةِ الوَزِّيَّاتِ، مِنْ رُتْبَةِ كَفِّيَّاتِ القَدَمِ، صَفِيحِيَّاتِ الْمَنَاقِيرِ. ""سَبَحَتِ الإوَزَّةُ فِي البِرْكَةِ ثُمَّ طَارَتْ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6440, 'إوَزٌّ', 'إوز', 'جامد', '', 'ءوز', 'إز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6441, 'أُوزُونٌ', 'أوزون', 'جامد', '', 'ءوزون', 'زن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": جِسْمٌ بَسِيطٌ غَازيٌّ تَنْبَعِثُ مِنْهُ رائِحةٌ قَوِيَّةٌ مُؤَكْسَدَةٌ، يَمِيلُ إلَى الزُّرْقَةِ، وَيَتَكَوَّنُ مِنَ الأُكْسِجِينِ؛ كَمَا تُنْتِجُهُ الشَّرَارَاتُ الكَهْرَبَائِيَّةُ، يُوجَدُ فِي الأجْوَاءِ العُلْيَا حَيْثُ يَحولُ دُو"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6442, 'آفَةٌ', 'آفة', 'جامد', 'أوف', 'ءافة', 'آفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""حَلَّتِ الآفَةُ بالزَّرْعِ"" : مَا يُفْسِدُ الزَّرْعَ مِن دُودٍ أَوْ حَشَرَاتٍ وَغيْرِهَا. ""إنَّهَا آفةٌ أَصَابَتِ الزَّرْعَ وَالح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6443, 'آلةٌ', 'آلة', 'جامد', 'أول', 'ءالة', 'آلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"1. هُنَاكَ آلاتٌ مُتَعَدِّدَةٌ : ""آلةُ الخِياطَةِ""، ""الآلةُ الكَاتِبَةُ""، ""آلةُ الحَاسُوبِ""، ""الآلاتُ الزِّرَاعِيَّةُ وَالإلِكتْرُونِيَّة وَالْمَعْلُومَاتِيَّةُ"" : أدَاةٌ، أدَوَاتٌ يُنْجَزُ بِها عَمل ما، وَتُسَاعِدُ عَلَى ذَلِك. 2.""آلَةٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6444, 'آيَةٌ', 'آية', 'جامد', 'أوي', 'ءاية', 'آة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":آيٌ"', '', '', '', '', '', '', '', '', '". 1.: كُلُّ فِقْرَةٍ مِنْ فِقْرَاتِ القُرْآنِ أوْ جُمْلَةٍ مِنْ جُمَلِهِالبقرة آية 99وَلَقَدْ أنْزَلْنَا إِلَيْكَ آيَاتٍ بَيِّنَاتٍ (قرآن) .البقرة آية 252تِلْكَ آيَاتُ اللهِ نَتْلُوهَا عَلَيْكَ بِالحَقِّ (قرآن) . 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6445, 'آيٌ', 'آي', 'جامد', '', 'ءءي', 'آ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6446, 'أيَّارُ', 'أيار', 'جامد', '', 'ءيار', 'ر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ الخَامِسُ مِنَ السَّنَةِ الشَّمْسِيَّةِ، عَدَدُ أيَّامِهِ (31) يوما، وَيَأْتِي بَعْدَ نِيسَانَ وَيَلِيهِ حُزَيرَانُ وَيُسَمَّى أيْضاً مَاي، مَايُو."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6447, 'أيدز', 'أيدز', 'جامد', '', 'ءيدز', 'دز', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"IDS، اِخْتِزالٌ أنجليزيٌّ لأرْبَعِ كَلِماتٍ لِما يُعْرَفُ بِمَرَضِ فِقْدانِ الْمَناعَةِ بِسَبَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6448, 'أَيْقُونَةٌ', 'أيقونة', 'جامد', '', 'ءيقونة', 'قنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ج: أيْقُونَاتٌ.: صُورَةُ القُدُسِ عِنْدَ الْمَسِيحِيِّينَ أَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6449, 'أَيْكَةٌ', 'أيكة', 'جامد', '', 'ءيكة', 'كة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أيْكٌ"', '', 'R', '', '', '', '', '', '', '"ج: أيْكٌ. 1.""تَاهَ فِي الأَيْكَةِ"" : الشَّجَرُ الكَثِيفُ الْمُلْتَفُّ. 2.""أصْحَابُ الأيْكَةِ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6450, 'أيْكٌ', 'أيك', 'جامد', '', 'ءيك', 'ك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6451, 'أُيَّلٌ', 'أيل', 'جامد', '', 'ءيل', 'ل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أيَائِلُ"', '', 'R', '', '', '', '', '', '', '"ج. أيَائِلُ. (حو).: حَيَوَانٌ مِنْ فَصِيلَةِ الأَيِّلِيَّاتِ، مِنْ رُتْبَةِ شَفْعِيَّاتِ "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6452, 'أيَائِلُ', 'أيائل', 'جامد', '', 'ءياءل', 'ل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6453, 'أَيْلُول', 'أيلول', 'جامد', '', 'ءيلول', 'لل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ التَّاسِعُ مِنَ السَّنَةِ الشَّمْسِيَّةِ، يَأْتِي بَعْدَ أُغُسْطُسَ وَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6454, 'أيِّمٌ', 'أيم', 'جامد', 'أيم', 'ءيم', 'م', '', '', '', 'مفرد', 'DnN', '', '', '"أيَاَمى"', '', 'R', '', '', '', '', '', '', '".: مَنْ لاَ زَوْجَ لَهُ مِنَ الرِّجَالِ وَالنِّسَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6455, 'أيَاَمى', 'أيامى', 'جامد', '', 'ءيامى', 'م', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6456, 'إِيوَانٌ', 'إيوان', 'جامد', '', 'ءيوان', 'إن', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":أَوَاوينُ"', '', 'R', '', '', '', '', '', '', '"ج: إِيوَانَاتٌ، أَوَاوينُ. 1.: ""مَكَانٌ مُتَّسِعٌ وَمُرْتَفِعٌ يُحِيطُ بِهِ ثَلاثَةُ جُدْرَانٍ يَعْلُوها سَقْفٌ. 2.""إيَوانُ كِسْرَى"" : قَصْرُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6457, 'أَوَاوينُ', 'أواوين', 'جامد', '', 'ءواوين', 'ن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6458, 'أَيونٌ', 'أيون', 'جامد', '', 'ءيون', 'ن', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '": ذَرَّةٌ أوْ مَجْمُوعَةُ ذَرَّاتٍ مُتَمَاسِكَةٍ، ذَاتُ شِحْنَةٍ كَهْرَبَائِيَّةٍ مُوجِبَةٍ "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6459, 'بُؤْبُؤٌ', 'بؤبؤ', 'جامد', 'بأبأ', 'بءبء', 'بب', '', '', '', 'مفرد', 'Dz', '', '', '', '', 'Rz', '', '', '', '', '', '', '"بُؤْبُؤٌ-بُؤْبُؤٌ [ب أ ب أ]. 1. ""بُؤْبُؤُ العَيْنِ"" : إنْسانُ العَيْنِ، وَسَطُهَا، أي الفَتْحَةُ الْمَرْكَزِيَّةُ الَّتي تَقَعُ فِي مُنْتَصَفِ القُزَحِيَّةِ. ""هُوَ أعَزُّ عَلَيَّ مِنْ بُؤْبُؤِ عَيْنِي"". 2.""بُؤْبُؤُ الرَّجُلِ"" : أصْلُهُ. ¨ ""أنَا فِي بُؤْبُؤِ صِدْقٍ"" ""فِي بُؤْبُؤِ الْمَجْدِ وَبُحْبُوحِ الكَرَمِ"". 3.""البُؤْبُؤُ"" : السَّيِّدُ الطَّريفُ الخَفِيفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6460, 'بَابَا', 'بابا', 'جامد', '', 'بابا', 'بب', '', '', '', 'جمع تكسير', 'Dy', '', '', '"بَابَوَاتٌ"', 'ممنوع من الصرف', 'Rw', '', 'N', 'O', 'N', 'O', '', '"ج: بَابَوَاتٌ. ""تُوُفِّيَ البَابَا، وَأُعْلِنَ فِي رُومَا عَنِ انْتِخابِ البَابَا الجَدِيدِ"" : الرَّئيسُ الرُّوحِيُّ الأعْظَمُ لِلْكَنيسَةِ الكَاتُوليكِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6461, 'بَابَوَاتٌ', 'بابوات', 'جامد', '', 'بابوات', 'ببت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6462, 'بَابُونجٌ', 'بابونج', 'جامد', '', 'بابونج', 'ببنج', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"بَابُونجٌ-بَابُونجٌ (نب).: نباتٌ من فصيلَةِ الْمُرَكَّبَاتِ، عُشْبِيٌّ، وَزَهْرُهُ أصفَرُ وَيَكُونُ أَحيَاناً أحْمَرَ أَوْ أبْيَضَ، لَهُ رَائحَةٌ طَيِّبَةٌ يُعْرَفُ بالأقْحُوانِ النَّبيلِ، تُحَضَّرُ مِنهُ بَعْضُ الأَدْوِيَةِ، يُسَاعِدُ عَلَى الهَضْمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6463, 'باجٌ', 'باج', 'جامد', '', 'باج', 'بج', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات: تُبَّانٌ، أيْ لِباسٌ داخِلِيٌّ صَغيرٌ يَسْتُرُ العَوْرَةَ، لِلرِّجالِ والنِّساءِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6464, 'باخِرَةٌ', 'باخرة', 'جامد', '', 'باخرة', 'بخرة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَواخِرُ"', '', 'R', '', '', '', '', '', '', '"ج: بَواخِرُ. ""أَبْحَرَتْ بِهِ الباخِرَةُ"" : السَّفينَةُ البُخارِيَّةُ الكَبيرَةُ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6465, 'بَواخِرُ', 'بواخر', 'جامد', '', 'بواخر', 'بخر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6466, 'بَادِيَةٌ', 'بادية', 'جامد', '', 'بادية', 'بدة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":بَوَادٍ"', '', '', '', '', '', '', '', '', '"ج: بَوَادٍ، بَادِيَاتٌ. ""سافَرَ إِلَى الباديَة"" : مِسَاحَةٌ شَاسِعَةٌ تُحِيطُ بِهَا حُقُولٌ يَعِيشُ فِيهَا أَهْلُ القُرَى الْمُتَقَارِبَةِ أَحْيَاناً، وَالْمُتَبَاعِدَةِ فِي أَحْيَانٍ أُخْرَى. ""يُلاَئِمُنِي هَوَاءُ الْبَادِيَةِ، أنْهَارُها وَحُقُولُهَا، وَفَضَاؤُهَا الوَاسِعُ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6467, 'بَوَادي', 'بوادي', 'جامد', '', 'بوادي', 'بد', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6468, 'بَاذِنْجَانٌ', 'باذنجان', 'جامد', '', 'باذنجان', 'بذنجن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"بَاذِنْجَانٌ-بَاذِنْجَانٌ (نب).: نَبَاتٌ مِنَ الخُضَرِ الزِّرَاعِيَّةِ، مِنْ فَصِيلَةِ البَاذِنْجِيَّات، تَميلُ إِلَى سَوَادٍ مَفْتُوحٍ وَهُوَ مُسْتَطِيلٌ وَمُدَوَّرٌ لَهُ رَأْسٌ أخْضَرُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6469, 'بَاذِنْجَانِيَّاتٌ', 'باذنجانيات', 'جامد', '', 'باذنجانيات', 'بذنجنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْن، فِيهَا أَنْوَاعٌ كَثيرَةٌ، بَرِّيَّةٌ سَامَّةٌ، وَزِراعِيَّةٌ تُؤْكَلُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6470, 'بُؤْرَةٌ', 'بؤرة', 'جامد', 'بأر', 'بءرة', 'برة', '', '', '', 'مفرد', 'DnN', '', '', '"بُؤَرٌ"', '', 'R', '', '', '', '', '', '', '". 1.""فِي بُؤْرَةِ السَّاحَةِ"" : فِي حُفْرَتِها. ""حَفَرَ الجَيْشُ بُؤَراً عَلَى طُولِ الحُدُودِ"". 2.""بُؤْرةُ العَدَسَةِ"" : الزُّجاجَةُ الكَثِيفَةُ الَّتي تُشَكِّلُ مَرْكَزَ تَجَمُّعِ النُّورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6471, 'بُؤَرٌ', 'بؤر', 'جامد', '', 'بءر', 'بر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6472, 'بِئْرٌ', 'بئر', 'جامد', 'بأر', 'بءر', 'بر', '', '', '', 'مفرد', 'DnN', '', '', '"آبار(مؤ)"', '', 'R', '', '', '', '', '', '', '". 1.: حُفْرَةٌ عَمِيقَةٌ فِي الأرْضِ لاسْتِخْراجِ الماء. ""بِئْرُ زمْزَمٍ"" ""هُنَاكَ بِئْرٌ لاَ قَرَارَ لَها"". (بدر شاكر السياب). 2.""بِئْرُ البِتْرولِ"" : حُفْرَةٌ مُنَقَّبٌ عَنْها لاسْتِخْراجِ البِتْرولِ. 3.""بِئْرٌ أو رتْوَازِيَّة"" : حُفْرَةٌ يَتَفَجَّرُ مِنْها الماءُ بوجودِهِ في مُسْتَوىً بيْنَ طَبَقَتيْنِ مَحْصُورَتَيْنِ، تُحْفَرُ فِي مِنطَقةٍ كافِيَةٍ، يَتَفَجَّرُ منها الماءُ مُنْدَفِعاً بِقُوَّةِ الضَّغْطِ الدَّاخِلِيِّ، أي حَسَبَ مَبْدَإِ الأوْعِيَةِ الْمُسْتَطْرقَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6473, 'آبارٌ', 'آبار', 'جامد', '', 'ءءبار', 'آبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6474, 'بَارِجَةٌ', 'بارجة', 'جامد', '', 'بارجة', 'برجة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَوَارِجُ"', '', 'R', '', '', '', '', '', '', '"ج: بَوَارِجُ. ""اتَّجَهَتِ البَوَارِجُ الحَرْبِيَّةُ إلَى الخَلِيجِ العَرَبيِّ"" : سُفُنٌ قِتَاليَّةٌ لِمَعَارِكِ الحَرْبِ. ""دَخَلَتْ بَارِجَةٌ حَرْبِيَّةٌ البَحْرَ الأبْيَضَ الْمُتَوَسِّط""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6475, 'بَوَارِجُ', 'بوارج', 'جامد', '', 'بوارج', 'برج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6476, 'بَارودٌ', 'بارود', 'جامد', '', 'بارود', 'برد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَارودٌ-بَارودٌ (كيما). ""سَمِعْنَا طَلَقَاتِ بَارُودٍ مُدَوِّيَةً"" : مَادَّةٌ مُتَفَجِّرَةٌ مُرَكَّبَةٌ مِنَ كِبْرِيتٍ وَفَحْمٍ وَمِلْحٍ، تُوضَعُ فِي البَنادِقِ وَالأسْلِحَةِ النَّارِيَّةِ لإطْلاَقِ الرَّصَاصِ، وَتُسْتَعْمَلُ فِي عَمَلِيَّاتِ التَّفْجِيرِ وَالنَّسْفِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6477, 'بَارُودَةٌ', 'بارودة', 'جامد', '', 'بارودة', 'بردة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَوَارِيدُ"', '', 'R', '', '', '', '', '', '', '"ج: بَوَارِيدُ. ""وَضَعَ البَارُودَ فِي البَارُودَةِ لإطْلاَقِ الرَّصَاصِ"" : بُنْدُقِيَّةٌ مِنَ الأسْلِحَةِ القَدِيمَةِ لإطْلاَقِ الرَّصَاصِ بِها."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6478, 'بَوَارِيدُ', 'بواريد', 'جامد', '', 'بواريد', 'برد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6479, 'بَارُوكَةٌ', 'باروكة', 'جامد', '', 'باروكة', 'بركة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '": شَعْرٌ اصْطِنَاعِيٌّ يُوضَعُ فَوْقَ الرَّأْسِ للِزِّينَةِ كَمَا يُسْتَخْدَمُ فِي التَّمْثِيلِ وَفِي مُنَاسَبَاتٍ خَاصَّةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6480, 'بَارْيُوم', 'باريوم', 'جامد', '', 'باريوم', 'برم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": عُنْصُرٌ مِنَ العَنَاصِرِ العُلْوِيَّةِ التُّرَابيَّةِ، وَهُوَ فِلِزٌّ لَيِّنٌ، لَوْنُهُ فِضِّيٌّ يَتَأكْسَدُ بِسُرْعَةٍ في الهَواءِ وَيَتفَاعَلُ مَعَ الْمَاءِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6481, 'بَازٌ', 'باز', 'جامد', '', 'باز', 'بز', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بُزاةٌ:بِيزَانٌ"', '', 'R', '', '', '', '', '', '', '"ج: بُزاةٌ، بِيزَانٌ. (حو).: طَيْرٌ مِنْ فَصِيلَةِ الصَّقْرِيَّاتِ، وَهُوَ مِنَالجَوَارِحِ، لَهُ مِنْقَارٌ قَصِيرٌ مَعْقُوفٌ وَبُروزٌ فِي حَافَةِ الفَكِّ العُلْـوِيِّ، وَمِنْخَـرانِ مُسْتَدِيرانِ، وَجَنَاحَانِ مُسْتَدِيِرانِ حَادَّانِ، وَذَنَبٌ طَويلٌ، سَريعُ الانْقِضاضِ عَلَى غَنِيمَتِهِ، يُمْكِنُ تَدْجِينُهُ لِيُسْتَخْدَمَ في الصَّيْدِ، يُسَمَّى البَاشِقَ أيضاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6482, 'بُزاةٌ', 'بزاة', 'جامد', '', 'بزاة', 'بزة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6483, 'بِيزَانٌ', 'بيزان', 'جامد', '', 'بيزان', 'بزن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6484, 'بَازَارٌ', 'بازار', 'جامد', '', 'بازار', 'بزر', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"بَازَارٌ-بَازَارٌ (جغ). ""بَازَارُ الْمَدِينَةِ"" : سُوقٌ تِجَارِيَّةٌ بِهَا دَكَاكِينُ لِبَيْعِ مُخْتَلِفِ الْمَوَادِّ والبَضَائعِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6485, 'بَأْساءُ', 'بأساء', 'جامد', 'بأس', 'بءساء', 'بس', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"بَأْساءُ-بَأْساءُ [ب أ س].الأنعام آية 42 فَأخَذْناهُمْ بِالبأْسَاءِ (قرآن) : أي بِالشِّدَّةِ، الْمَشَقَّةِ، العَذَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6486, 'بِئْسٌ', 'بئس', 'جامد', 'بأس', 'بءس', 'بس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بِئْسٌ-بِئْسٌ [ب أ س]. 1. ""بِئْسُ العَذَابِ"" : شَدِيدُهُ وَأُوارُهُ. 2. ""بَناتُ بِئْسٍ"" : الكَوَارِثُ، الدَّوَاهِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6487, 'باسُورٌ', 'باسور', 'جامد', '', 'باسور', 'بسر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بوَاسِيرُ"', '', 'R', '', '', '', '', '', '', '"ج: بوَاسِيرُ. ""قَامَ بِعَمَلِيَّةٍ جِراحِيَّةٍ لِلْبَواسيرِ"" : عِلَّةٌ فِي مَقْعَدة الإنْسانِ تُحْدِثُ انْتِفاخاً وَتُسَبِّبُ نَزيفَ دَمٍ فِي عُروقِ الْمَقْعَدَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6488, 'بوَاسِيرُ', 'بواسير', 'جامد', '', 'بواسير', 'بسر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6489, 'باشا', 'باشا', 'جامد', '', 'باشا', 'بش', '', '', '', 'جمع تكسير', '', '', '', '"بَاشَوات"', 'ممنوع من الصرف', 'Rw', '', 'N', 'O', 'N', 'O', '', '"ج: بَاشَوات. ""شَكاهُ إلَى بَاشا الْمَدينَةِ"" : مَسْؤولٌ إدَاريٌّ يُسَيِّرُ شُؤُونَ الْمَدِينَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6490, 'بَاشَواتٌ', 'باشوات', 'جامد', '', 'باشوات', 'بشت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6491, 'بَاشِقٌ', 'باشق', 'جامد', '', 'باشق', 'بشق', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَواشِقُ"', '', '', '', '', '', '', '', '', '"ج: بَواشِقُ. (حو).: طَيْرٌ مِنْ فَصِيلَةِ الصَّقْريَّاتِ مِنَ الجَوَارِحِ، وَهُوَ أنْوَاعٌ. ن. بَاز."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6492, 'بَواشِقُ', 'بواشق', 'جامد', '', 'بواشق', 'بشق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6493, 'بَاطِيةٌ', 'باطية', 'جامد', '', 'باطية', 'بطة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَواطٍ"', '', '', '', '', '', '', '', '', '"ج: بَواطٍ. 1.""تَنِاوَلَ مُثَلَّجاتٍ فِي باطِيةٍ"" :كَأْسٌ مِنْ زُجاجٍ عَرِيضٍ. 2. : قِنِّينَةٌ ضَخْمَةٌ مِنْ زُجاجٍ تُمْلأُ بِالسَّوائِلِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6494, 'بَواطي', 'بواطي', 'جامد', '', 'بواطي', 'بط', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6495, 'باقولٌ', 'باقول', 'جامد', '', 'باقول', 'بقل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَواقِيلُ"', '', 'R', '', '', '', '', '', '', '"ج: بَواقِيلُ. ""وَضَعَتْ حُبُوبَ القَهْوَةِ فِي باقوُلٍ"" : إِناءٌ مِنْ زُجاجٍ أوْ خَزَفٍ بِلاَ عُرْوَةٍ. ""تُوجَدُ بَواقِيلُ كَثِيرَةٌ فِي الْمَطْبَخِ، كُلُّ باقُولٍ يَحْتَوِي عَلَى مادَّةٍ مِنَ الْمَوادِّ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6496, 'بَواقِيلُ', 'بواقيل', 'جامد', '', 'بواقيل', 'بقل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6497, 'بالٌ', 'بال', 'جامد', '', 'بال', 'بل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"بالٌ-بالٌ (حو).: ""جِنْسُ ثَدْييَّاتٍ بَحْرِيَّةٍ مِنْ فَصِيلَةِ الباليَّاتِ وَرُتْبَةِ الحِيتَانِ، وَهُوَ أطْوَلُ الحيَوَاناتِ ؛ إذْ يَبْلُغُ أحْياناً 30 متراً، وَيَزِنُ حَوَالَيْ 150 طُنّّاً، لَهُ شَحْـمٌ مُفِيـدٌ يُسْتَخْرَجُ مِنْهُ حَوالَيْ 30 طنّاً مِنَ الزَّيْتِ، يَتَغَذَّى بِعَلَقِ البَحْرِ، وَيُمْكِنُ أَنْ يَغْطِسَ نِصْفَ ساعَةٍ ثُمَّ يَعُودَ إلَى سَطْحِ الماءِ، يَزْفُرُ هَوَاءً مُشْبَعاً بِبُخارِ الماءِ، والبَالُ الحَقِيقِيُّ نادِرٌ جِدّاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6498, 'بالَةٌ', 'بالة', 'جامد', '', 'بالة', 'بلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"1.""أخَذَ دَواءً مِنْ بالَةٍ صَغِيرَةٍ"" : قارُورَةٍ. ""بالَةُ طِيبٍ"". 2.""ناوَلَهُ بالَةً لِمَسْحِ جِراحِهِ"" : حَزْمَةً مِنَ القُطْنِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6499, 'بامْيَا', 'باميا', 'جامد', '', 'باميا', 'بم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '"بامْيَا-بامْيَا (نب).: بَقْلَةٌ مِنْ الخُضَرِ الزِّراعِيَّةِ مِنْ فَصِيلَةِ الخُبَّازِيَّاتِ، لَهَالَوْنٌ أخْضَرُ بِداخِلِها حَبَّاتُ بِيضٌ تُؤْكَلُ مَطْبُوخَةً، أصْلُهـا مِنَ الهِنْدِ، وَتُزْرَعُ فِي بَعْضِ بُلْدانِ حَوْضِ البَحْرِ الأبْيَضِ الْمُتَوَسِّطِ، وَهِيَ الَّتِي يُسَمِّيها أهْلُ الْمَغْرِبِ ""مُلُوخِيَّة""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6500, 'بَانٌ', 'بان', 'جامد', '', 'بان', 'بن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَانٌ-بَانٌ (نب).: شَجَرٌ مَنْ فَصِيلَةِ البانِيَّاتِ لَيِّنٌ، لَهُ وَرَقٌ طَوِيلٌ مُرَكَّبٌ يُشْبِهُ وَرَقَ الصَّفْصافِ، أبْيَضُ الزَّهْرِ، يَنْمُو فِي البُلْدَانِ الرَّطْبَةِ، يُسْتَخْرَجُ مِنْهُ نَوْعٌ مِنَ الزَّيْتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6501, 'بانِيَّاتٌ', 'بانيات', 'جامد', '', 'بانيات', 'بنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةُ شَجَرِ البانِ، أنَواعُها مُتَعدِّدَةٌ. جَمِيعُها أشْجَارٌ، وَهِيَ شَجَراتٌ خُنْثَوِيَّةُ الأزْهارِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6502, 'بَبْرٌ', 'ببر', 'جامد', '', 'ببر', 'ببر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بُبُورٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: بُبُور (حو).: حَيَوَانٌ مِنْ فَصِيلَةِ السِّنَّوْريَّاتِ، مِنَ رُتْبَةِ الضَّواري، وَهُوَ نَوْعٌ مِنَ السِّبَاعِ الْمُفْتَرِسَةِ أصْفَرُ، وَعَلَى جِلْدِهِ خُطوطٌ سَوْدَاءُ، يُشْبِهُ النَّمِرَ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6503, 'بُبُورٌ', 'ببور', 'جامد', '', 'ببور', 'ببر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6504, 'بَبَّغاءُ', 'ببغاء', 'جامد', '', 'ببغاء', 'ببغ', '', '', '', 'جمع تكسير', 'DzDw', '', '', '"بَبَّغاوَاتٌ"', 'ممنوع من الصرف', 'Rz', '', '', '', '', '', '', '"ج: بَبَّغاوَاتٌ. (حو). 1.: طَيْرٌ مِنْ فَصِيلَةِ البَبَّغَاوَاتِ، لَهُ مِنْقَـارٌ قَصِيرٌ ضَخْـمٌ مَعْقُوفٌ، لِقَدَمِهِ أُصْبُعَان إلى الأمام وأُصْبُعانِ إلى الخَلْفِ، وَهُوَ طَائِرٌ يَتَميَّزُ بِألْوانِهِ الزَّاهيَةِ، لَهُ قُدْرَةٌ عَلَى تَقْليدِ الأصْواتِ وَترْدِيدِ مَا يَسْمَعُهُ مِنْ كَلاَمِ الإنْسَـانِ. 2.""لاَ تَكُنْ مِثْلَ البَبَّغَاءِ"" : أيْ لاَ تُعِدْ كَلاَم النَّاسِ، كُنْ مُبْدِعاً، مُبْتَكِراً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6505, 'بَبَّغاوَاتٌ', 'ببغاوات', 'جامد', '', 'ببغاوات', 'ببغت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6506, 'بَبَّغاءَاتٌ', 'ببغاءات', 'جامد', '', 'ببغاءات', 'ببغت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6507, 'بَتَاتٌ', 'بتات', 'جامد', 'بتت', 'بتات', 'بتت', '', '', '', 'مفرد', 'DnN', '', '', '"بُتُوتٌ:أبِتَّةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""حَمَلَتِ العَرُوسُ بَتاتَها"" : جِهَازَهَا. 2.""حَمَلَ الْمُسَافِرُ بَتَاتَهُ"" : زَادَهُ. 3.""هُوَ عَلَى بَتَاتِ أَمْرٍ"" : أَي مُشْرِفٌ عَلَيْهِ. 4.""لاَ أَرْضَى بَتَاتاً"" : أَي قَطْعاً، نِهَائِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6508, 'بُتُوتٌ', 'بتوت', 'جامد', '', 'بتوت', 'بتت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6509, 'أبِتَّةٌ', 'أبتة', 'جامد', '', 'ءبتة', 'بتة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6510, 'بِتْرُولٌ', 'بترول', 'جامد', '', 'بترول', 'بترل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": زَيْتُ وَقُودِ الْمُحَرِّكِ وَالإنارَةِ يُسْتَخْرَجُ مِنَ الآبَارِ الجَوْفِيَّةِ، وَيُعْرَفُ أيْضاً بِالنَّفْطِ. ""اِرْتَفَعَ سِعْرُ بِرْمِيلِ البِتْرُولِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6511, 'بُجْرَةٌ', 'بجرة', 'جامد', '', 'بجرة', 'بجرة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بُجَرٌ"', '', 'R', '', '', '', '', '', '', '"ج: بُجَرٌ.: السُّرَّةُ. 1. ""ذَكَرَ عُجَرَهُ وَبُجَرَهُ"" : ذَكَرَ عُيُوبَهُ ظاهِرَها وَباطِنَها. 2.""أطْلَعْتُهُ عَلَى عُجَرِي وَيُجَرِي"": أخْبَرْتَهُ بأسْرَاري. 3.""أشكُو إلَى اللَّهِ عُجَري وَبُجَرِي"" : أحْزَانِي وَهُمُومِي."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6512, 'بُجَرٌ', 'بجر', 'جامد', '', 'بجر', 'بجر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6513, 'بَجِيشٌ', 'بجيش', 'جامد', 'بجش', 'بجيش', 'بجش', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"بَجِيشٌ-بَجِيشٌ [ب ج ش]. 1.""عَيْنٌ بَجِيشٌ"" : مُتَدَفِّقَةٌ، غَزيرَةٌ. 2.""ماءٌ بَجِيشٌ"" : سائِلٌ، مُتَفَجِّرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6514, 'بَجَعَةٌ', 'بجعة', 'جامد', '', 'بجعة', 'بجعة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَجَعٌ"', '', 'R', '', '', '', '', '', '', '"واحدة بَجَعَةٌ.: طَيْرٌ مِنْ فَصِيلَةِ البَجْعِيَّات، مِنْ رُتْبَةِ كَفِّيَّات القَدَمِ. لَهُ مِنْقَارٌ طَوِيلٌ عَرِيضٌ مَعْقُوفٌ يَحْمِلُ تَحْتَهُ حُوَيْصِلَةً ضَخْمَةً، يَخْزِنُ فِيها الأكْلَ لِصِغارِهِ، لَهُ قُدْرَةٌ عَلَى السِّبَاحَةِ، وَقُـدْرَةٌ عَلَى الطَّيَرانِ أَسْرَابـاً، يَتَغَـذَّى مِنَ الأسماكِ، وهو أَنْواعٌ كثيرةٌ، ويُسَمَّى أيضاً ""أبو جِرابٍ""، وَالحَوْصَلَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6515, 'بَجَعٌ', 'بجع', 'جامد', '', 'بجع', 'بجع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6516, 'بَجَعِيَّات', 'بجعيات', 'جامد', '', 'بجعيات', 'بجعت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فصيلةُ البَجَعِ ورُتْبَةُ كَفِّيَّاتِ القَدَمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6517, 'بُحْبُوحَةٌ', 'بحبوحة', 'جامد', 'بحبح', 'بحبوحة', 'بحبحة', '', '', '', 'مفرد', 'DnN', '', '', '"بَحَابيحُ"', '', 'R', '', '', '', '', '', '', '". ""يَعِيشُ فِي بُحْبُوحَةِ عَيْشٍ"" : فِي عَيْشٍ رَغْدٍ، فِي هَنَاءٍ وَرَفاهيةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6518, 'بَحَابيحُ', 'بحابيح', 'جامد', '', 'بحابيح', 'بحبح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6519, 'مَبْحَثٌ', 'مبحث', 'جامد', 'بحث', 'مبحث', 'مبحث', '', '', '', 'مفرد', 'DnN', '', '', '"مَبَاحِثُ"', '', 'R', '', '', '', '', '', '', '". 1.""الْمَبْحَثُ الأَوَّلُ مِنَ الكِتَابِ"" : الفَصْلُ الأَوَّلُ مِنْهُ. 2.""قَدَّمَ مَبْحَثاً جَيِّداً"" : بَحْثاً، دَرْساً فِيهِ كَثِيرٌ مِنَ التَّحَرِّي وَالتَّحْقِيقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6520, 'مَبَاحِثُ', 'مباحث', 'جامد', '', 'مباحث', 'مبحث', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6521, 'بُحَّةٌ', 'بحة', 'جامد', 'بحح', 'بحة', 'بحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"بُحَّةٌ-بُحَّةٌ [ب ح ح]. ""أُصِيبَ بِبُحَّةٍ"" : أُصِيبَ بِوَعْكَةٍ فِي صَوْتِهِ، صارَتْ فِي رَنَّةِ صَوْتِهِ خُشُونَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6522, 'بَحْرٌ', 'بحر', 'جامد', 'بحر', 'بحر', 'بحر', '', '', '', 'مفرد', 'DnN', '', '', '"بِحارٌ(ج)أبْحُرٌ:وبُحُورٌ:وبِ', '', 'Rp', '', '', '', '', '', '', '". 1.""تَقَعُ مدينتُنا عَلَى البَحْرِ"": مياهٌ عَظِيمَةٌ تَحْمِلُها الأمْواجُ إلَى حُدودِ الأرْضِ اليابِسَةِ. ""يَحُدُّ الْمَغْرِبَ شَمالاً البَحْرُ الأبْيَضُ المتوسِّطُ، وَغَرْباً المُحِيطُ الأطْلَسِيُّ"". 2.""بُحُورُ الشِّعْرِ سِتَّةَ عَشَرَ بَحْراً"" : وَزْنُهُ فِي اصْطِلاَحِ أهْلِ العَرُوضِ. ""مِنْ حَسَناتِ عِلْمِ العَروضِ أنَّهُ كَثِيرُ البُحُورِ"". (ميخائيل نعيمة). 3.""سأزورُكَ فِي بَحْرِ هَذِهِ السَّنَةِ"" : فِي غُضُونِها، خِلالَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6523, 'بِحارٌ', 'بحار', 'جامد', '', 'بحار', 'بحر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
