INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6527, 'بَحْرَيْن', 'بحرين', 'جامد', '', 'بحرين', 'بحرن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '": مِنَ البُلْدانِ العَرَبيَّةِ بِالخَليجِ، عاصِمَتُها الْمَنامَة."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6528, 'بَخْتٌ', 'بخت', 'جامد', '', 'بخت', 'بخت', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بُخُوتٌ(ج)وأبْحَاثٌ"', '', 'R', '', '', '', '', '', '', '"ج: بُخُوتٌ. ""سُوءُ البَخْتِ"" : سُوءُ الحَظِّ، السَّعْدُ. ""أنا قَلِيلُ البَخْتِ""."', ':لا جذر:لا مفرد');
