INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6531, 'بُخارٌ', 'بخار', 'جامد', 'بخر', 'بخار', 'بخر', '', '', '', 'مفرد', 'DnN', '', '', '"أبْخِرَةٌ"', '', 'R', '', '', '', '', '', '', '". ""يَتَصَاعَدُ البُخَارُ مِنَ القِدْرِ"" : عِنْدَ وَضْعِ مَادّةٍ سَائِلَةٍ فِي إنَاءٍ عَلَى النَّارِ، يَصْعَدُ مِنْها الدُّخَانُ، مَاءٌ فِي حَالَةٍ غازِيَّةٍ. ""كانَ بُخَارُ الحَمَّامِ حارّاً"" ""بُخارُ الماءِ"" ""بُخارُ الدُّخانِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6532, 'أبْخِرَةٌ', 'أبخرة', 'جامد', '', 'ءبخرة', 'بخرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6533, 'مِبْخَرَةٌ', 'مبخرة', 'جامد', 'بخر', 'مبخرة', 'مبخرة', '', '', '', 'مفرد', 'DnN', '', '', '"مَبَاخِرُ"', '', 'R', '', '', '', '', '', '', '". : وِعَاءُ البَخُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6534, 'مَبَاخِرُ', 'مباخر', 'جامد', '', 'مباخر', 'مبخر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6535, 'بُخْنُقٌ', 'بخنق', 'جامد', 'بخق', 'بخنق', 'بخنق', '', '', '', 'مفرد', 'DnN', '', '', '"بَخانِقُ"', '', 'R', '', '', '', '', '', '', '". 1.""بُخْنُقُ الْمَرْأةِ"": خِرْقَةٌ تَتَقَنَّعُ بِهَا، فَتَشُدُّ طَرَفَيْها تَحْتَ حَنَكِها. 2. ""لَبِسَ الطِّفْلُ البُخْنُقَ"" : البُرْنُسَ الصَّغِيرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6536, 'بَخانِقُ', 'بخانق', 'جامد', '', 'بخانق', 'بخنق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6537, 'مَبْخَلَةٌ', 'مبخلة', 'جامد', 'بخل', 'مبخلة', 'مبخلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَبْخَلَةٌ-مَبْخَلَةٌ [ب خ ل]. ""وَلَدٌ مَبْخَلَةٌ"" : وَلَدٌ يُحْمَلُ عَلَى البُخْلِ. الوَلَدُ مَجْبَنَةٌ مَجْهَلَةٌ مَبْخَلَةٌ . (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6538, 'بُخُوريَّاتٌ', 'بخوريات', 'جامد', '', 'بخوريات', 'بخرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": نَباتَاتٌ مِنْ فَصِيلَةِ البُطْمِيّاتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6539, 'بَدْءٌ', 'بدء', 'جامد', 'بدأ', 'بدء', 'بد', '', '', '', 'مفرد', 'Dz', '', '', '"أبْداءٌ(يجوزبدءًا)"', '', 'Rz', '', '', '', '', '', '', '". 1.""في البَدْءِ كانَتِ الكلِمَةُ"" : في أوَّلِ شيْءٍ إطْلاقاً. 2.""كانَ مُنْتَبِهاً مُنْذُ البَدْءِ "" : مُنْذُ البِدَايَةِ. 3. ""بادِئَ ذِي بدْءٍ"" : أوَّلاً وَقَبْلَ كُلِّ شَيْءٍ. 4.""أفْعَلُهُ عوْداً على بَدْء"" : مِنْ أوَّلِهِ إلى آخِرهِ. ""قَرَأَ الكِتابَ من بَدْئِهِ إلى آخِرِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6540, 'أبْداءٌ', 'أبداء', 'جامد', '', 'ءبداء', 'بد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6541, 'مُبْتَدَأٌ', 'مبتدأ', 'جامد', 'بدأ', 'مبتدء', 'مبتد', '', '', '', 'مفرد', 'Dz', '', '', '', '', 'R', '', '', '', '', '', '', '"مُبْتَدَأٌ-مُبْتَدَأٌ [ب د أ]. 1.""مُبْتَدَأُ العَمَلِ"" : أَوَّلُهُ. 2.""الْمُبْتَدَأُ فِي النَّحْوِ هُوَ الاسْمُ الَّذِي يَكُونُ بِهِ ابْتِدَاءُ الكَلاَمِ نَحْوُ"" : ""البَيْتُ جَمِيلٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6542, 'مَبْدَأٌ', 'مبدأ', 'جامد', 'بدأ', 'مبدء', 'مبد', '', '', '', 'مفرد', 'Dz', '', '', '"مَبَادِئُ"', '', 'R', '', '', '', '', '', '', '"مَبْدَأٌ-مَبْدَأٌ [ب د أ]. 1.""مَبْدَأُ القَضِيَّةِ"" : أَصْلُهَا. 2.""الْمَبْدَأُ الأَسَاسِيُّ فِي العَمَلِ هُوَ النِّيَّةُ"" : القَاعِدَةُ. 3. ""الْمَبْدَأُ الأَوَّلُ"" : القَانُونُ، البَنْدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6543, 'مَبَادِئُ', 'مبادئ', 'جامد', '', 'مبادء', 'مبد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6544, 'بِدَايَةٌ', 'بداية', 'جامد', 'بدا', 'بداية', 'بدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""في بِدَايَةِ الأمْرِ كانَ مُهَذَّباً"" : فِي أوّلِهِ. 2.""البِدَايَةُ وَالنِّهايَةُ"" : الابْتِدَاءُ، أَوَّلُ شَيْءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6545, 'بادِرَةٌ', 'بادرة', 'جامد', 'بدر', 'بادرة', 'بدرة', '', '', '', 'مفرد', 'DnN', '', '', '"بَوادِرُ"', '', '', '', '', '', '', '', '', '". ""ظَهَرَتْ مِنْهُ بادِرَةُ خَيْرٍ""‏ : عَلامَةٌ، إِشارَةٌ. ""صَدَرَتْ عَنْهُ بادِرَةٌ مَحْمودَةٌ"" ""بَدَأتْ بَوَادِرُ الغَضَبِ تَظْهَرُ عَلَى مَلاَمِحِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6546, 'بَوادِرُ', 'بوادر', 'جامد', '', 'بوادر', 'بدر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6547, 'بَيْدَرٌ', 'بيدر', 'جامد', 'بدر', 'بيدر', 'بدر', '', '', '', 'مفرد', 'DnN', '', '', '"بَيادِرُ"', '', 'R', '', '', '', '', '', '', '". ""تَنْتَشِرُ البَيَادِرُ فِي السُّهُولِ أثْنَاءَ مَوْسِمِ الحَصَادِ"" : الْمَوْضِعُ الَّذِي تُجْمَعُ فِيهِ السَّنَابِلُ وَنَحْوُهَا لِدَوْسِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6548, 'بَيادِرُ', 'بيادر', 'جامد', '', 'بيادر', 'بدر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6549, 'بِدْعٌ', 'بدع', 'جامد', 'بدع', 'بدع', 'بدع', '', '', '', 'مفرد', 'DnN', '', '', '"أبْداعٌ:بُدُعٌ"', '', 'R', '', '', '', '', '', '', '". 1.""عَالِمٌ بِدْعٌ فِي عِلْمِهِ"" : يَأتِي بِالعَجَبِ، أيْ بِالْمُحدَثِ وَالمُبْتَكَرِ. 2.""لَم يَكُنِ اخْتِراعُهُ بِدْعاً فِي هذا الأمْرِ"" : أيْ لَمْ يَكُنْ أوَّلَ اخْتِراعٍ. 3.""لاَ بِدْعَ مِنْ ذَلِكَ"" : أيْ لاَ عَجَبَ. الأحقاف آية 9قُلْ ما كُنْتُ بِدْعاً مِنَ الرُّسُلِ (.قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6550, 'أبْداعٌ', 'أبداع', 'جامد', '', 'ءبداع', 'بدع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6551, 'بُدُعٌ', 'بدع', 'جامد', '', 'بدع', 'بدع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6552, 'بِدْعَةٌ', 'بدعة', 'جامد', 'بدع', 'بدعة', 'بدعة', '', '', '', 'مفرد', 'DnN', '', '', '"بِدَعٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هَذِه بِدْعَةٌ لَمْ نَرَ لَها مَثِيلاً"" : ما اسْتُحْدِثَ فِي الدِّينِ. كُلُّ بِدْعَةٍ ضَلاَلَةٌ . (حديث) ""اِعْتِقادٌ صَحِيحٌ لاَ يَكُونُ فِيهِ بِدْعَةٌ"". (الغزالي). 2.""اِحْذَرُوا أَهْلَ البِدَعِ"" : جَماعَةٌ تَعْمَلُ عَلَى إحْداثِ عادَاتٍ جَدِيدَةٍ عَلَى غَيْرِ مِثالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6553, 'بِدَعٌ', 'بدع', 'جامد', '', 'بدع', 'بدع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6554, 'مِشْمِشٌ', 'مشمش', 'جامد', '', 'مشمش', 'مشمش', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مِشْمِشٌ-مِشْمِشٌ، ةٌ (نب). 1.:شَجَرٌ مِنْ فَصِيلَةِ الوَرْدِيَّاتِ. تَظْهَرُ زُهُورُهُقَبْلَ أَوْرَاقِهِ، وَهِيَ ذَاتُ لَوْنٍ أَبْيَضَ أَوْ وَرْدِيٍّ يُعْطِـي ثَمَرَ المِشْمِشِ. 2.""ثَمَرُ المِشْمِشِ"" : ثَمَرُ شَجَرِ المِشْمِشِ أَصْفَرُ اللَّوْنِ لَهُ نَوَاةٌ عَظْمِيَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6555, 'بَدْلَةٌ', 'بدلة', 'جامد', 'بدل', 'بدلة', 'بدلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَدْلَةٌ-بَدْلَةٌ [ب د ل]. ""يَرْتَدِي بَدْلَةً جَدِيدَةً"" : كِسْوَةً، حُلَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6556, 'بَدَنٌ', 'بدن', 'جامد', 'بدن', 'بدن', 'بدن', '', '', '', 'مفرد', 'DnN', '', '', '"أبدانٌ"', '', 'R', '', '', '', '', '', '', '". 1.""كانَ بَدَنُهُ نَحِيفاً"" : جِسْمُهُ، جَسَدُهُ. 2.""رَجُلٌ بَدَنٌ"" : مُسِنٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6557, 'أبدانٌ', 'أبدان', 'جامد', '', 'ءبدان', 'بدن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6558, 'بَدِيهٌ', 'بديه', 'جامد', 'بده', 'بديه', 'بده', '', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"بَدِيهٌ-بَدِيهٌ [ب د هـ]. ""قالَهُ بَديهاً"" : اِرْتِجالاً، عَفْوَ الخاطِرِ. ""على البَدِيهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6559, 'بِديهَةٌ', 'بديهة', 'جامد', 'بده', 'بديهة', 'بدهة', '', '', '', 'مفرد', 'DnN', '', '', '"بَدائِهُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""عُرِفَ بِحُضورِ البَديهَةِ"" : سُرْعَة الفَهْمِ، الإجابَة السَّريعَة. ""كانَ لَبِقاً لَسِناً ذَكِيّاً واسِعَ الاطِّلاَعِ حاضِرَ البَديهةِ"". (أ. مين). 2.""يُجيبُ على البَديهَةِ"" : تِلْقائِيّاً وبِعَفَوِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6560, 'بَدائِهُ', 'بدائه', 'جامد', '', 'بداءه', 'بده', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6561, 'بَدْوٌ', 'بدو', 'جامد', 'بدو', 'بدو', 'بد', '', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"بَدْوٌ-بَدْوٌ[ب د و]. ""تُكَوِّنُ نِسْبَةُ البَدْوِ كَذَا مِنْ سُكَّانِ البِلادِ"" : سُكَّانُ البادِيَةِ مِنَ القَبائِلِ الرُّحَّلِ، أَهْلُ الوَبَرِ.يوسف آية 100 وجاءَ بِكُمْ مِنَ البَدْو ِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6562, 'بَذَخٌ', 'بذخ', 'جامد', 'بذخ', 'بذخ', 'بذخ', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَذَخٌ-بَذَخٌ [ب ذ خ]. 1.""ما هَذا البَذَخُ في الأكْلِ واللِّباسِ!"": ما هَذا الإفْراطُ والإنْفاقُ الكَثيرُ والافْتِخارُ بِذَلِكَ!. 2.""يُظْهِرُ بَذَخَهُ"" : أُبَّهَتَهُ، تَطاوُلَهُ بِكَلامِهِ وافْتِخارِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6563, 'بَذْرٌ', 'بذر', 'جامد', 'بذر', 'بذر', 'بذر', '', '', '', 'مفرد', 'DnN', '', '', '"بُذورٌ:بِذارٌ"', '', 'R', '', '', '', '', '', '', '". 1.""شَرَعَ في بَذْرِ الحُبوبِ"" : زَرْعِها. ""آنَ أَوَانُ البُذورِ"". 2.""نَشَرَ بُذورَ الفِتْنَةِ والتَّفْرِقَةِ بَيْنَ النَّاسِ"" : أَعْمالَ السُّوءِ، أَفْكارَ السُّوءِ. 3.""إِنَّ هَؤُلاءِ لَبَذْرُ سُوءٍ"" : مِنْ نَسْلِ سوءٍ. 4.""بُذورُ الزِّراعَةِ"" : البُزورُ، الحُبوبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6564, 'بُذورٌ', 'بذور', 'جامد', '', 'بذور', 'بذر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
