INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6566, 'بَذْرَةٌ', 'بذرة', 'جامد', 'بذر', 'بذرة', 'بذرة', '', '', '', 'مفرد', 'DnN', '', '', '"بَذْرٌ(واحِدَةُالحَبِّ)"', '', 'R', '', '', '', '', '', '', '". ""كانَتِ البَذْرَةُ الأولَى في الحَقْلِ"" : البِزْرَةُ، الحَبَّةُ، ما يَتَكَوَّنُ في الثَّمَرَةِ، وَيَضُمُّ بِداخِلِها النَّواةَ الأصْلِيَّةَ."', '');
