INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6569, 'مَبَاذِلُ', 'مباذل', 'جامد', '', 'مباذل', 'مبذل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6570, 'بَرِيَّةٌ', 'برية', 'جامد', 'برأ', 'برية', 'برة', '', '', '', 'مفرد', 'DnN', '', '', '"بَرايا"', '', '', '', '', '', '', '', '', '".البينة آية 7 أُولَئِكَ هُمْ خَيْرُ البَرِيَّةِ (قرآن).: الخَلْق، النَّاس."', '');
