INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6572, 'بَرَّادٌ', 'براد', 'جامد', '', 'براد', 'برد', '', '', '', 'جمع تكسير', 'DnN', '', '', '"براريدُ"', '', '', '', '', '', '', '', '', '"ج: براريدُ. ""يَصُبُّ الشَّايَ مِنَ البَرَّادِ"": إِناءٌ مِنْ مَعْدِنٍ، يُحَضَّرُ فيهِ الشَّايُ بِالْمَغْرِبِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6573, 'براريدُ', 'براريد', 'جامد', '', 'براريد', 'بررد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6574, 'بَرَازٌ', 'براز', 'جامد', '', 'براز', 'برز', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1. ""فَضَاءٌ بَرَازٌ"" : وَاسِعٌ، خَالٍ مِنَ النَّبَاتِ. 2.""أَلْقَى بَرَازَهُ"" : الخَرَاء، الغَائِط، أَيْ مَا تَلْفُظُهُ الأمْعَاءُ عِنْدَ قَضَاءِ الحَاجَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6575, 'بُراقٌ', 'براق', 'جامد', '', 'براق', 'برق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": دابَّةٌ رَكِبَها النَّبِيُّ محمد لَيْلَةَ المِعْراجِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6576, 'بَرَّاكَةٌ', 'براكة', 'جامد', '', 'براكة', 'بركة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"ج: ـات. ""يَسْكُنُ في بَرَّاكَةٍ"" : بَيْتٌ مَصْنوعٌ مِنَ اللَّوْحِ أَوِ القَصْديرِ وَنَحْوِهِما."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6577, 'بُرائِلُ', 'برائل', 'جامد', 'برأل', 'براءل', 'برل', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '"بُرائِلُ-بُرائِلُ [ب ر أ ل]. 1.: ما حَوْلَ عُنُقِ الطَّيْرِ مِنَ الرِّيشِ، العُفْرَة. 2.""أَبو البُرائِلِ"" : الدِّيكُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6578, 'بَرْبَرٌ', 'بربر', 'جامد', '', 'بربر', 'بربر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَرابِرُ:بَرابِرَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: بَرابِرَةٌ.""عاثَ البَرابِرَةُ فَساداً في الأرْضِ"" : الهَمَجِيّونَ، المُتَوَحِّشون."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6579, 'بَرابِرُ', 'برابر', 'جامد', '', 'برابر', 'بربر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
