INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6581, 'بُرْتُقالٌ', 'برتقال', 'جامد', '', 'برتقال', 'برتقل', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '": شَجَرٌ مِنْ فَصيلَةِ البُرْتُقالِيَّاتِ مِنَ الحَمْضِيَّاتِ، ثِمارُهُ لَذيذَةٌ، كُرَوِيَّةُ الشَّكْلِ، ذاتُ لَوْنٍ أَصْفَرَ مائِلٍ إلى الحُمْرَةِ، يَتَضَمَّنُ فِيتامِينَ(س)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6582, 'بُرْتُقالِيَّةٌ', 'برتقالية', 'جامد', '', 'برتقالية', 'برتقلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"ج: ـات. ""شَرِبَ بُرْتُقالِيَّةً"" : عَصِيرُ البُرْتُقالِ زائِدُ السُّكَّرِ والماءِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6583, 'بُرْثُنٌ', 'برثن', 'جامد', 'برثن', 'برثن', 'برثن', '', '', '', 'مفرد', 'DnN', '', '', '"بَراثِنُ"', '', 'R', '', '', '', '', '', '', '". ""أَنْشَبَ الأسَدُ بَراثِنَهُ في فَريسَتِهِ"" : مَخالِبَهُ (جمع مَخْلَب)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6584, 'بَراثِنُ', 'براثن', 'جامد', '', 'براثن', 'برثن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6585, 'بُرْجٌ', 'برج', 'جامد', '', 'برج', 'برج', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بُروجٌ:أَبْراجٌ"', '', 'R', '', '', '', '', '', '', '"ج: بُروجٌ، أَبْراجٌ. 1.""ظَهَرَ لِرَبابِنَةِ السَّفينَةِ بُرْجٌ لِلْمُراقَبَةِ مِنْ بَعيدٍ"" : بِناءٌ مُرْتَفِعٌ مُسْتَديرٌ أَوْ مُرَبَّعُ في المِيناءِ يَهْدِي السُّفُنَ وَيُوَجِّهُها، وَهَذِهِ الْمُهِمَّةُ نَفْسُها يُؤَدِّيها بُرْجُ الْمُراقَبَةِ في الْمَطارِ لِلطَّائِراتِ. 2.""كانَ الحارِسُ يَقْبَعُ في بُرْجِهِ عِنْدَ مَدْخَلِ الْمَدينَةِ"" : بِناءٌ وَسَطَ مَدْخَلِ سُورِ الْمَدينَةِ أَوْ كُلُّ سُورِ، حِصْنٌ. 3. النساء آية 78وَلَوْ كُنْتُمْ في بُروجٍ مُشَيَّدَةٍ ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6586, 'بُروجٌ', 'بروج', 'جامد', '', 'بروج', 'برج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6587, 'أَبْراجٌ', 'أبراج', 'جامد', '', 'ءبراج', 'برج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6588, 'بُرْجُدٌ', 'برجد', 'جامد', '', 'برجد', 'برجد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": غِطاءٌ ثَخينٌ مُخَطَّطٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6589, 'بَرْجَلٌ', 'برجل', 'جامد', '', 'برجل', 'برجل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَراجِلُ"', '', 'R', '', '', '', '', '', '', '"ج: بَراجِلُ. ""رَسَمَ دَوائِرَ وأَقْواساً بِالبَرْجَلِ"" : آلَةٌ ذاتُ ساقَيْنِمُتَّصِلَتَيْنِ، إِحْداهُما بِها مِسْمارٌ تَثْبُتُ فَوْقَ الوَرَقَةِ وَالأخْرَى بِها قَلَمٌ تَـدورُ حَوْلَها لِرَسْمِ دائِرَةٍ أَو نِصْفِها. وَيُسَمَّى أَيْضاً بِيكاراً وَبِرْكاراً وَفِرْجاراً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6590, 'بَراجِلُ', 'براجل', 'جامد', '', 'براجل', 'برجل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6591, 'بَراحٌ', 'براح', 'جامد', 'برح', 'براح', 'برح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَراحٌ-بَراحٌ [ب ر ح]. 1.""لا بَراحَ"" : لاَ رَيْبَ. 2.""تَحَدَّثَ في مَوْضوعِهِ بَراحاً"" : عَلَناً، صَراحَةً. ""باءَ الكُفْرَ بَراحاً"" : عَلَناً. 3.""جاءَ الأمْرُ بَراحاً"" : جَلِيّاً وَاضِحاً. 4.""أَرْضٌ بَراحٌ"" : شاسِعَةٌ لا نَباتَ فِيها ولاَ عُمْرانَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6592, 'تَبَارِيحُ', 'تباريح', 'جامد', 'برح', 'تباريح', 'تبرح', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"تَبَارِيحُ-تَبَارِيحُ [ب ر ح]. 1.""أَثْقَلَتْهُ تَبَارِيحُ الهُمُومِ"" : شَدَائِدُهَا. ""تَحْتَمِلُ عَذَابَ العُقْرِ وَمَرَارَةَ الشَّقَاءِ وَتَبَارِيحَ الفِرَاقِ"". (جبران خ. جبران). 2. ""أَفْصَحَ عَنْ تَبَارِيحِ حُبِّهِ"" : أَفْصَحَ عَنْ تَوَهُّجِ حُبِّهِ. ""تَبَارِيحُ الشَّوْقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6593, 'بَرْحَى', 'برحى', 'جامد', '', 'برحى', 'برح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"""بَرْحَى يا رَجُلُ !"" : كَلِمَةٌ تُقالُ عِنْدَ الخَطَإِ في الرَّمْي، وَيُقابِلُها ""مَرْحَى"" عِنْدَ الإِصابَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6594, 'بَرَّادَةٌ', 'برادة', 'جامد', 'برد', 'برادة', 'بردة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""ماءُ البَرَّادَةِ بارِدٌ"" : إِناءٌ مِنَ الطِّينِ الأحْمَرِ على شَكْلِ إِبْريقٍ لَكِنَّهُ أَضْخَمُ. 2.""وَضَعَ الطَّعامَ في البَرَّادَةِ"" : الثَّلاجَةِ، "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6595, 'بُرادَةٌ', 'برادة', 'جامد', 'برد', 'برادة', 'بردة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بُرادَةٌ-بُرادَةٌ [ب ر د]. ""اِمْتَلأتْ أَرْضُ الْمَعْمَلِ بِالبُرادَةِ مِنَ الحَديدِ أَوْ نَحْوِهِ أَثْناءَ عَمَلِيَّةِ البَرْدِ بِالمِبْرَدِ"" : ما يَتَساقَطُ مِنْهُ فُتاتاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6596, 'بُرْدٌ', 'برد', 'جامد', 'برد', 'برد', 'برد', '', '', '', 'مفرد', 'DnN', '', '', '"بُرودٌ:أَبْرادٌ"', '', 'R', '', '', '', '', '', '', '". ""كانَ مُلْتَحِفاً بُرْداً تَحْتَ الشَّجَرَةِ يَرْقُبُ غَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6597, 'بُرودٌ', 'برود', 'جامد', '', 'برود', 'برد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
