INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6599, 'بُرْدَةٌ', 'بردة', 'جامد', 'برد', 'بردة', 'بردة', '', '', '', 'مفرد', 'DnN', '', '', '"بُرَدٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِلْتَفَّ في بُرْدَتِهِ"" : ثَوْبٌ مُخَطَّطٌ يُلْتَحَفُ بِهِ. 2.""البُرْدَةُ"" : قَصيدَةٌ في مَدْحِ الرَّسولِ( لِكَعْبٍ بْنِ زُهَيْرٍ، سُمِّيَتْ بِذَلِكَ لأنَّ النَّبِيَّ خَلَعَ عَلَيْهِ بُرْدَتَهُ عِنْدَمَا انْتَهَى مِنْ إِنْشادِها. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6600, 'بُرَدٌ', 'برد', 'جامد', '', 'برد', 'برد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6601, 'بُرودَةٌ', 'برودة', 'جامد', 'برد', 'برودة', 'بردة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"بُرودَةٌ-بُرودَةٌ [ب ر د]. 1.""تسودُ المنْطَقَةَ بُرودَةٌ"" : حالَةُ بَرْد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6602, 'بَريدٌ', 'بريد', 'جامد', 'برد', 'بريد', 'برد', '', '', '', 'مفرد', 'DnN', '', '', '"بُرُدٌ"', '', 'R', '', '', '', '', '', '', '". 1.""مَكْتَبُ البَريدِ"" : مَصْلَحَةٌ عامَّةٌ لِنَقْلِ وَتَصْريفِ شُؤونِ الْمُراسَلاتِ والبَرْقِيَّاتِ والحَوالاَتِ والتِّلِيفوناتِ. ""يَشْتَغِلُ في إِدارَةِ البَريدِ والْمُواصَلاتِ السِّلْكِيَّةِ وَاللاَّسِلْكِيَّةِ"". 2.""صُنْدوقُ البريدِ"" : الصُّنْدوقُ الَّذِي توضَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6603, 'بُرُدٌ', 'برد', 'جامد', '', 'برد', 'برد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6604, 'مَبْرَدَة', 'مبردة', 'جامد', 'برد', 'مبردة', 'مبردة', '', '', '', 'مفرد', 'DnN', '', '', '"مَبَارِدُ"', '', 'R', '', '', '', '', '', '', '". 1.""رِيَاحٌ مَبْرَدَةٌ"" : تُسَبِّبُ البَرْدَ. 2.""أَرْضٌ مَبْرَدَةٌ"" : أَصَابَهَا البَرْدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6605, 'مَبَارِدُ', 'مبارد', 'جامد', '', 'مبارد', 'مبرد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6606, 'مِبْرَدٌ', 'مبرد', 'جامد', 'برد', 'مبرد', 'مبرد', '', '', '', 'مفرد', 'DnN', '', '', '"مَبَارِدُ"', '', 'R', '', '', '', '', '', '', '"مُبْرِدٌ-مُبْرِدٌ [ب ر د] (فا. من بَرَدَ). ""لَيْلٌ مُبْرِدٌ"" : ذُو بَرْدٍ، أَوْ ذُو بَرَدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6607, 'مَبَارِدُ', 'مبارد', 'جامد', '', 'مبارد', 'مبرد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
