INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6652, 'بُرْقُعٌ', 'برقع', 'جامد', 'برقع', 'برقع', 'برقع', '', '', '', 'مفرد', 'DnN', '', '', '"بَراقِعُ"', '', 'R', '', '', '', '', '', '', '". ""غَطَّتْ وَجْهَها بِبُرْقُعٍ"": نِقابٌ تُغَطِّي بِهِ الْمَرْأَةُ وَجْهَهَا إِلاَّ عَيْنَيْها. "', '');
