INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6655, 'بَرَكَةٌ', 'بركة', 'جامد', 'برك', 'بركة', 'بركة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""عاشَ في بَرَكَةٍ دائِمَةٍ"": السَّعادَةُ. 2.""مَعَهُ البَرَكَةُ"" : الخَيْرُ والنَّماءُ. ""في تِجارَتِهِ بَرَكَةٌ"" ""أَمَّا البَرَكَةُ فَهِيَ النَّماءُ والزِّيادَةُ والرَّفْعُ"". (التوحيدي) ""دَعا لَهُ بِالبَرَكَةِ"" ""وَيُبَكِّرُ في دَرْسِهِ فَإِنَّ في الوَقْتِ المُبَكِّرِ البَرَكَةَ والصَّفاءَ"" (الغ"', '');
