INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6657, 'بُرْكانٌ', 'بركان', 'جامد', '', 'بركان', 'بركن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَراكِينُ"', '', 'R', '', '', '', '', '', '', '"ج: بَراكِينُ. 1.""نَسْمَعُ مِنْ حينٍ لآخَرَ عَنِ انْفِجارِ بُرْكانٍ هُنا وَهُناكَ"" : فَتْحَةُ أَوْ فَوْهَةُ انْفجارٍ حَلَزونِيَّةُ الشَّكْلِ، تَكونُ في مَواقِعَ جَبَلِيَّةٍ تَقْذِفُ نيراناً مُلْتَهِبَةً. 2.""اِنْفَجَرَ مِنَ الغَضَبِ كَالبُرْكانِ"" : هاجَ مِنَ الغَضَبِ."', ':لا جذر:لا مفرد');
