INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6660, 'بِرْكَةٌ', 'بركة', 'جامد', '', 'بركة', 'بركة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بِرَكٌ"', '', 'R', '', '', '', '', '', '', '"ج: بِرَك. 1.""أَنْتَنَتِ البِرْكَةُ"" : الْمُسْتَنْقَعُ. 2.""جَلَسَ على حافَّةِ البِرْكَةِ"" : حَوْضُ الماءِ. ""سَبَحَ في البِرْكَةِ"" يا مَنْ رَأَى البِرْكَةَ الحَسْناءَ رُؤْيَتُها*لآنِساتٍ إِذا لاحَتْ مَغانِيها (البحتري)."', ':لا جذر:لا مفرد');
