INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6662, 'بَرْلَمانٌ', 'برلمان', 'جامد', '', 'برلمان', 'برلمن', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '": مَجْلِسُ الشَّعْبِ أَوْ مَجْلِسُ الأمَّةِ أَعْضاؤُهُ يُنْتَخَبونَ، وَيُمَثِّلونَ السُّلْطَةَ التَّشْريعِيَّةَ."', ':لا جذر:لا مفرد');
