INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6665, 'بَريمٌ', 'بريم', 'جامد', 'برم', 'بريم', 'برم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَريمٌ-بَريمٌ [ب ر م]. 1.""وَضَعَتْ في مِعْصمِها بَريماً"" : سِواراً مَبْروماً، مَفْتولاً. 2.""بَيْنَ أَصابِعِ الخَيَّاطِ بَريمٌ"" : حَبْلٌ مَفْتولٌ، الخَيْطُ وَكُلُّ ما يُبْرَمُ ويُفْتَلُ."', '');
