INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6736, 'بِضاعَةٌ', 'بضاعة', 'جامد', 'بضع', 'بضاعة', 'بضعة', '', '', '', 'مفرد', 'DnN', '', '', '"بَضائِعُ"', '', 'R', '', '', '', '', '', '', '". ""اِمْتَلأَتِ السُّوقُ بِبَضائعَ جَديدَةٍ"" : بِسِلَعٍ تِجارِيَّةٍ تُعْرَضُ لِلْبَيْعِ. ""باعَ بِضاعَتَهُ""يوسف آية 65 هَذِهِ بِضاعَتُنا رُدَّتْ إِلَيْنا. (قرآن)."', '');
