INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6738, 'بِضْعٌ', 'بضع', 'جامد', 'بضع', 'بضع', 'بضع', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"بِضْعٌ-بِضْعٌ، ةٌ [ب ض ع].: ما بَيْنَ الثَّلاثِ والتِّسْعِ فِي العَدَدِ ويَنْطَبِقُ عَلَيْهِ حُكْمُ العَدَدِ المُفْرَدِ. بِمَعْنَى بَعْضُ : ""بِضْعَةُ رِجالٍ""، ""بِضْعُ نِساءٍ""، ""شَاهَدْتُ بِضْعَةَ عَشَرَ رَجُلاً""، """"كَلَّمْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6739, 'مِبْضَعٌ', 'مبضع', 'جامد', 'بضع', 'مبضع', 'مبضع', '', '', '', 'مفرد', 'DnN', '', '', '"مَبَاضِعُ"', '', 'R', '', '', '', '', '', '', '". ""شَقَّ الْجَرَّاحُ الْجِلْدَ بِالْمِبْضَعِ"" : سِكِّينٌ دَقِيقٌ يُسْتَخْدَمُ فِي العَمَلِيَّاتِ الْجِرَاحِيَّةِ لإِحْدَاثِشَرَطَاتٍٍ فِي الْجِلْدِ."', '');
