INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6744, 'بَطَّارِيَّةٌ', 'بطارية', 'جامد', '', 'بطارية', 'بطرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"ج: بَطَّارِيَّاتٌ. ""يَشْتَغِلُ هَذَا المِذْياعُ بِالبَطَّارِيَّاتِ والكَهْرَباءِ مَعاً"" : أَقْراصٌ صُلْبَةٌ مَلِيئَةٌ بِطا"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6745, 'بَطاطا', 'بطاطا', 'جامد', '', 'بطاطا', 'بطط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '"بَطاطا-بَطاطا (نب).: نَباتٌ زِراعِيٌّ مِنْ فَصيلَةِ الباذِنْجانِيَّاتِ، يَنْبُتُ تَحْتَ الأرْضِ، ثِمارُهُ تُ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6746, 'بِطاقَةٌ', 'بطاقة', 'جامد', '', 'بطاقة', 'بطقة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":بَطائِقُ"', '', 'R', '', '', '', '', '', '', '"ج: بَطائِقُ، بِطاقاتٌ. 1.""أَرْسَلَ بِطاقَةً"" : رِسالَةً. 2.""سَلَّمَهُ بِطاقَتَهُ الشَّخْصِيَّةَ"" : وَرَقَةٌ مِنْ وَرَقٍ مُقَوَّى تَحْمِلُ اسْمَ الشَّخْصِ وَعُنْوانَهُ وَمِهْنَتَهُ. 3.""طَلَبَ مِنْهُ إِبْرازَ البِطاقَةِ الوَطَنِيَّةِ"" : الهُوَيَّةِ. 4.""بِطاقَةٌ بَرِيد"', ':لا جذر:لا مفرد');
