INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6748, 'بَطَّانِيَّةٌ', 'بطانية', 'جامد', '', 'بطانية', 'بطنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"ج: ـات. : لِحافٌ مِنْ صوفٍ أَوْ قُطْنٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6749, 'بَطَّةٌ', 'بطة', 'جامد', '', 'بطة', 'بطة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"واحدةالبط"', '', 'R', '', '', '', '', '', '', '"واحدة البط. ن.بَطّ ""بَطَّةُ غازٍ"" : قِنِّينَةُ غازٍ. وَهِيَ وِعاءٌ مِنْ مَعْدِنٍ صَلْبٍ، يُشْحَنُ بِالغازِ وَيُلْحَقُ بِواسِطَةِ أُنْبوبٍ بِآلَةِ الْمَطْبَخِ، وَعِنْدَ فَتْحِها تُشْعَلُ بِعودِ ثِقابٍ لإِشْعالِ الْمَوْقِدِ الآلِيِّ. ."', ':لا جذر:لا مفرد');
