INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6751, 'بُطاحٌ', 'بطاح', 'جامد', 'بطح', 'بطاح', 'بطح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بُطاحٌ-بُطاحٌ [ب ط ح]. ""اِشْتَدَّ بِهِ البُطَاحُ"" : الهَذَيَانُ النَّاشِئُ عَنِ الحُمَّى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6752, 'بِطاحٌ', 'بطاح', 'جامد', 'بطح', 'بطاح', 'بطح', '', '', '', 'مفرد', '', '', '', '"مفردبَطْحاء"', '', 'R', '', '', '', '', '', '', '". 1.""بَطْحاءُ مَكَّةَ وَبِطاحُها"" : وَهِيَ مَساكِنُ ""قُرَيْشُ البِطاحِ"" وَهُمْ خِلافُ قُرَيْشِ الظَّواهِر. 2.""وَغَمَرَتِ الظُّلْمَةُ البِطاحَ والأوْدِيَةَ"".(جبران خ جبران). السُّهول الفَسيحَة الأرْجاءِ."', '');
