INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6763, 'بِطْريقٌ', 'بطريق', 'جامد', '', 'بطريق', 'بطرق', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَطاريقُ"', '', 'R', '', '', '', '', '', '', '"ج: بَطاريقُ. (حو).: طَائِرٌ مِنْ فَصيلَةِ البَطْرِيقِيَّاتِ، مِنْرُتْبَةِ كَفِّيَّاتِ القَدَمِ، وَهُوَ بَرْمائِيٌّ يَكْثُـرُ في الْمَناطِقِ القُطْبِيَّةِ، لَهُ جِسْمٌ ناعِمٌ كَثيفُ"', ':لا جذر:لا مفرد');
