INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6765, 'بُطْمٌ', 'بطم', 'جامد', '', 'بطم', 'بطم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"بُطْمٌ-بُطْمٌ (نب). 1.: شَجَرٌ مِنْ فَصيلَةِ البُطْمِيَّاتِ يُشْبِهُ شَجَرَ الفُستُقِ. لَهُ أَوْراقٌ صَغيرَةٌ وَعَناقيدُ ت"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6766, 'بُطْمِيَّاتٌ', 'بطميات', 'جامد', '', 'بطميات', 'بطمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصيلَةٌ مِنْ ذَواتِ الفِلْقَتَيْنِ، تَشْمُلُ البُطْمَ والفُسْتُقَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6767, 'بِطَانٌ', 'بطان', 'جامد', 'بطن', 'بطان', 'بطن', '', '', '', 'مفرد', 'DnN', '', '', '"أَبْطِنَةٌ:بُطُنٌ"', '', 'R', '', '', '', '', '', '', '". 1.""شَدَّ بِطَانَ البَعِيرِ"" : حِزَامَهُ. 2.""بِطَانُ البَطْنِ"" : حِزَامٌ يُشَدُّ بِهِ. 3.""هُوَ عَريضُ البِطَانِ"" : رَخِيُّ البَالِ، قَدْ أَثْرَى وَكَثُرَ مَالُهُ. 4.""اِلتَقَتْ حَلْقَتَا البِطَانِ"" : كِنَايَةٌ عَنِ اشْتِدَادِ الأمْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6768, 'أَبْطِنَةٌ', 'أبطنة', 'جامد', '', 'ءبطنة', 'بطنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
