INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6770, 'بِطانَةٌ', 'بطانة', 'جامد', 'بطن', 'بطانة', 'بطنة', '', '', '', 'مفرد', 'DnN', '', '', '"بَطَائِنُ"', '', 'R', '', '', '', '', '', '', '". 1.""بِطانَةُ الرَّجُلِ"" : أَهْلُهُ وَأَقْرِباؤُهُ. آل عمران آية 118يَا أَيُّها الَّذينَ آمَنُوا لا تَتَّخِذُوا بِطانَةً مِنْ دونِكُمْ . (قرآن). 2.""بِطَانَةُ الثَّوْبِ"" : مَا يُبَطَّنُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6771, 'بَطَائِنُ', 'بطائن', 'جامد', '', 'بطاءن', 'بطن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6772, 'بَطْنٌ', 'بطن', 'جامد', 'بطن', 'بطن', 'بطن', '', '', '', 'مفرد', 'DnN', '', '', '"بُطونٌ:أَبْطُنٌ"', '', 'R', '', '', '', '', '', '', '"(تش) (مذ، مؤ). 1.""اِمْتَلأَ بَطْنُهُ"" : الكِرْشُ الجُزْءُ الأمامِيُّ مِنَ البَدَنِ تَحْتَ الصَّدْرِ، يَحْتَوِي على الأمْعاءِ. ¨ النحل آية 69 يَخْرُجُ مِنْ بُطونِها شَرابٌ مُخْتَلِفٌ أَلْوانُهُ فيهِ شِفاءٌ للنَّاسِ (قرآن). 2.""أَلْقَى ما في بَطْنِهِ"": أَخْرَجَ ما في جَوْفِهِ. 3.""أَكَلَ أَكْلاً دَسِماً فَأَوْ"', '');
