INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6775, 'بِطْنَةٌ', 'بطنة', 'جامد', 'بطن', 'بطنة', 'بطنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"بِطْنَةٌ-بِطْنَةٌ [ب ط ن]. ""البِطْنَةُ تُذْهِبُ الفِطْنَةَ"" (مثل): الامْتِلاءُ الشَّديدُ مِنَ الطَّعامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6776, 'بُطَيْنٌ', 'بطين', 'جامد', 'بطن', 'بطين', 'بطن', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"بُطَيْنٌ-بُطَيْنٌ [ب ط ن].: يُطْلَقُ على التَّجْوِيفَيْنِ الدَّاخِلِيَّيْنِ السُّفْلِيَّيْنِ لِلْقَلْبِ وَاللَّذَيْنِ يَجْتَمِعُ فِيهِما الدَّمُ، وَيُدْفَعُ لِلشَّرايِينِ وَهُما البُطَيْنُ الأيْمَنُ والبُطَيْنُ الأيْسَرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6777, 'بَاطن', 'باطن', 'جامد', '', 'باطن', 'بطن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَوَاطِنُ"', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
