INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6781, 'بِطِّيخٌ', 'بطيخ', 'جامد', '', 'بطيخ', 'بطخ', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"بِطِّيخٌ-بِطِّيخٌ (نب).: فاكِهَةٌ نَباتِيَّةٌ مِنْ فَصيلَةِ القَرْعِيَّاتِ، أَنْواعُهُ كَثيرَةٌ، كُرَوِيُّ الشَّكْلِ لَهُ قِشْرَةٌ سَميكَةٌ وَمادَّتُهُ خَضْراءُ أَوْ صَفْراءُ، طَعْمُهُ لَذيذٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6782, 'بُعْبُعٌ', 'بعبع', 'جامد', '', 'بعبع', 'بعبع', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَعابِعُ"', '', 'R', '', '', '', '', '', '', '"ج: بَعابِعُ. ""إِنَّ البُعْبُعَ آتٍ"" : صُورَةٌ خَيالِيَّةٌ لِحَيَوانٍ مُرْعِبٍ، الغُولُ، طَيْفٌ مُخيفٌ يُخَوِّفُ الأطْفالَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6783, 'بَعابِعُ', 'بعابع', 'جامد', '', 'بعابع', 'بعبع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
