INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6786, 'بِعْثَةٌ', 'بعثة', 'جامد', 'بعث', 'بعثة', 'بعثة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""وَصَلَتْ بَعْثَةٌ ثَقافِيَّةٌ"" : وَفْدٌ ثَقَافِيٌّ، هَيْئَةٌ. ""سافَرَ في بَعْثَةٍ دِراسِيَّةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6787, 'مَبْعَثٌ', 'مبعث', 'جامد', 'بعث', 'مبعث', 'مبعث', '', '', '', 'مفرد', 'DnN', '', '', '"مَبَاعِثُ"', '', 'R', '', '', '', '', '', '', '". ""الْمَبْعَثُ عَلَى ذَلِكَ هُوَ ..."" : السَّبَبُ، الْحَافِزُ. ""أَقْوَالُهُ مَبْعَثُ شَكٍّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6788, 'مَبَاعِثُ', 'مباعث', 'جامد', '', 'مباعث', 'مبعث', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6789, 'أَبْعَادٌ', 'أبعاد', 'جامد', 'بعد', 'ءبعاد', 'بعد', '', '', '', 'مفرد', '', '', '', '"مفردبُعْدٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""قِيَاسُ الأَبْعَادِ"" : قِيَاسُ الطُّولِ. 2.""أَبْعَادُ الموْضُوعِ"" : مَدَاهُ، اتِّسَاعُهُ، أعْمَاقُهُ وَمَا يَتَعَلَّقُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6790, 'بُعْدٌ', 'بعد', 'جامد', 'بعد', 'بعد', 'بعد', '', '', '', 'مفرد', 'DnN', '', '', '"أَبْعادٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""كانَ يَقِفُ على بُعْدِ عِشْرينَ مِتْراً مِنْ مَكانِ الحادِثَةِ"" : على مَسافَةٍ. 2.""إِنَّهُ لَذُو بُعْدٍ ثاقِبٍ"" : ذُو أُفُقٍ ثاقِبٍ. 3.""لَهُ بُعْدُ نَظَرٍ"" : فِكْرٌ عَميقٌ وَتَبَصُّرٌ. 4.""بُعْداً لَهُ"" : عِبارَةٌ تُقالُ لِلدُّعاءِ عَلَيْهِ، أَيْ سُحْقاً، هَلاكاً. 5.""رَآهُ عَنْ بُعْدٍ"" : على مَسافَةٍ بَعيدَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6791, 'أَبْعادٌ', 'أبعاد', 'جامد', '', 'ءبعاد', 'بعد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6792, 'مَبْعَدَةٌ', 'مبعدة', 'جامد', 'بعد', 'مبعدة', 'مبعدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَبْعَدَةٌ-مَبْعَدَةٌ [ب ع د]. ""كَانَ يَسِيرُ عَلَى مَبْعَدَةٍ وَرَاءَ الْمَوْكِبِ"" : بَعِيداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6793, 'بَعَرَةٌ', 'بعرة', 'جامد', '', 'بعرة', 'بعرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":أَبْعارٌ:(واحدةالبَعْر)"', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6794, 'بَعَرٌ', 'بعر', 'جامد', 'بعر', 'بعر', 'بعر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '". "" تَرَكَ الغَنَمُ أَبْعاراً وَراءهُ"" : رَجيعُ ذَواتِ الخُفِّ وَذَواتِ الظَّلْفِ. ""تَرَى بَعَرَ الأَرْآمِ في عَرَصاتِها"".(امرؤ القيس)."', '');
