INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6796, 'بَعيرٌ', 'بعير', 'جامد', 'بعر', 'بعير', 'بعر', '', '', '', 'مفرد', 'DnN', '', '', '"أَباعِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""لَمْ يَكُنْ يَمْلِكُ إِلاَّ بَعيراً واحِداً"" : كُلُّ ناقَةٍ أَوْ جَمَلٍ فَوْقَ الأَرْبَعِ سَنَواتٍ لِلذَّكَرِ والأنْثَى. 2.""وَجَهَّزُوا أَباعِرَهُمُ اسْتِعْداداً لِسَفَرٍ طَويلٍ عَبْرَ الصَّحْراءِ الْمَغْرِبِيَّةِ"" : جِمالٌ وَنِياقٌ صالِحَةٌ للرُّكوبِ والحَمْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6797, 'أَباعِرُ', 'أباعر', 'جامد', '', 'ءباعر', 'بعر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6798, 'بَعْضٌ', 'بعض', 'جامد', '', 'بعض', 'بعض', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَبْعاضٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَبْعاضٌ. 1.""في بَعْضِ الأحْيانِ"" : في حِينٍ مِنَ الأحْيانِ. ""فِي بَعْضِ الأَوْقَاتِ"". 2.""في بَعْضِ لَيالِي الشِّتاءِ كَانَتْ حِكاياتُنا لاَتَنْتَهِي"" : في إِحْدَى اللَّيالِي. 3.""جاءَ بَعْضُ الأساتِذَةِ فَقَطْ"" : طائِفَةٌ مِنْهُمْ. ""جاءَ بَعْضُهُم"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6799, 'أَبْعاضٌ', 'أبعاض', 'جامد', '', 'ءبعاض', 'بعض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
