INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6802, 'بَعوضَةٌ', 'بعوضة', 'جامد', '', 'بعوضة', 'بعضة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"(واحدةالبَعُوض)"', '', 'R', '', '', '', '', '', '', '"بَعوضٌ-بَعوضٌ (واحدة بَعُوضَةٌ).: مِنْ فَصيلَةِ البَعوضِيَّاتِ، مِنْ رُتْبَةِثُنائِيَّةِ الأجْنِحَةِ، لَها فَمٌ كَذَنَبِ الإِبْرَةِ، بِهِ تَلْدَغُ وَتَم"', ':لا جذر:لا مفرد');
