INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6806, 'بَغْدادُ', 'بغداد', 'جامد', '', 'بغداد', 'بغدد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'N', 'N', 'O', '', '": عاصِمَةُ جُمْهورِيَّةِ العِراقِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6807, 'بَغْريرَةٌ', 'بغريرة', 'جامد', '', 'بغريرة', 'بغررة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"واحدةالبَغْرير"', '', 'R', '', '', '', '', '', '', '"بَغْريرٌ-بَغْريرٌ (الواحدة بَغْريرَة). ""تَكْفِينِي بَغْريرَةٌ واحِدَةٌ"" : رَغيفٌ ي"', ':لا جذر:لا مفرد');
