INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6809, 'بَغْضاءُ', 'بغضاء', 'جامد', 'بغض', 'بغضاء', 'بغض', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"بَغْضاءُ-بَغْضاءُ [ب غ ض]. ""لَمْ يَعْرِفْ سَبَبَ هَذِهِ البَغْضاءِ والجَفاءِ"" : البُغْضُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6810, 'بَغْلٌ', 'بغل', 'جامد', '', 'بغل', 'بغل', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '":أَبْغالٌ:بِغالٌ"', '', 'R', '', '', '', '', '', '', '"ج: بِغالٌ، أَبْغالٌ، بَغْلاتٌ، بِغالٌ. (حو).: هُوَ حَيَوانٌ صَبورٌعَقيمٌ لا يَلِدُ، هَجِينُ الْخَيْلِ وَالْحَمِيرِ. يَقْطَعُ مَسافاتٍ طَويلَـةً وَبالأخَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6811, 'أَبْغالٌ', 'أبغال', 'جامد', '', 'ءبغال', 'بغل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
