INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6813, 'مَبْغَاةٌ', 'مبغاة', 'جامد', 'بغي', 'مبغاة', 'مبغة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مَبْغَاةٌ-مَبْغَاةٌ [ب غ ي]. ن: مَبْغىً.مَبْغىً، ةٌ - ج: مَبَاغٍ، الْمَبَاغِي. [ب غ ي]. (مفع. مِنْ بَغَى). 1. : مَكَانٌ يُبْحَثُ فِيهِ عَنْ تَحْقِيقِ رَغْبَةٍ أَوْ مَطْلَبٍ. 2.:رَغْبَةٌ، مَا يُرْجَى تَحْقِيقُهُ. 3.: ماخُورٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6814, 'بَقٌّ', 'بق', 'جامد', '', 'بق', 'بق', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"بَقٌّ-بَقٌّ، ةٌ (حش).: حَشَرَةٌ صَغيرَةٌ مُسَطَّحَةٌ مِنْ فَصيلَةِ البَقِّيَّاتِ، مِنْ رُتْبَةِ نِصْ"', ':لا جذر:لا مفرد');
