INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6847, 'مَبَاكِي', 'مباكي', 'جامد', '', 'مباكي', 'مبك', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6848, 'بِلاتِين', 'بلاتين', 'جامد', '', 'بلاتين', 'بلتن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": مَعْدِنٌ ثَمينٌ جِدّاً، فِضِّيُّ اللَّوْنِ لامِعٌ، ثابِتٌ، يَنْصَهِرُ بِصُعوبَةٍ، يُسْتَخْدَمُ لِصُنْعِ الأوانِي الكِيمْيائِيَّةِ والحُلِيِّ والْمُجَوْهَراتِ. ""في أُصْبُعِها خاتَمٌ مِنَ البِلاتِينِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6849, 'بِلادٌ', 'بلاد', 'جامد', '', 'بلاد', 'بلد', '', '', '', 'جمع تكسير', '', '', '', '"مفردبَلَد"', '', 'R', '', '', '', '', '', '', '"جمع بَلَد. 1.""بِلادٌ شاسِعَةٌ"" : الْمَكانُ الواسِعُ مِنَ الأرْضِ. 2.: مَكانٌ مَحْدودٌ جُغْرافِيّاً تَسْتَوْطِنُهُ جَماعاتٌ مُعَيَّنَةٌ. 3.""يا بِلادِي"" : يا وَطَنِي."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6850, 'بُلْبُلٌ', 'بلبل', 'جامد', 'بلبل', 'بلبل', 'بلبل', '', '', '', 'مفرد', 'DnN', '', '', '"بَلابِلُ"', '', 'R', '', '', '', '', '', '', '". 1.(حو).: طَـائِـرٌ مِنْ فَصيلَـةِ الهُدْهُـدِيَّاتِ، مِنْ رُتْبَـةِ الشِّقِرَّاقِيَّاتِ، لَهُ قُنْزُعَةٌ مُنْتَصِبَةٌ، بُنْدُقِيَّةُ اللَّـوْنِ مُحْمَرَّةٌ مُنْتَهِيَةٌ رِيشاتُها بِالسَّوادِ، لَهُ مِنْقارٌ طَويلٌ، مُقَوَّسٌ، صَغيرُ الجِسْمِ، مَشْهورٌ بِتَغْرِيدِهِ الجَميلِ، يُطْلَقُ عَلَيْهِ العَنْدَليبُ والهَزارُ. 2.""آه ! لَقَدْ تَكَسَّرَ بُلْبُلُ الإِبْرِيقِ"": قَناتُهُ الَّتِي يُصَبُّ مِنْها الماءُ."', '');
