INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6890, 'بَالٌ', 'بال', 'جامد', 'بلي', 'بال', 'بل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَالٌ-بَالٌ [ب ل ي]. 1. ""لَمْ يَخْطُرْ هَذَا الأمْرُ بِبَالِي قَطّْ"" : بِخاطِرِي، بِفِكْرِي. ""بالُهُ مَشْغُولٌ عَلَى الدَّوامِ"". 2.""هُوَ كاسِفُ البالِ"" : كاسِفُ النَّفْسِ. 3.""شَعَرَ بِراحَةِ البالِ"" : باطْمِئْنانِ حالِهِ وَنَفْسِهِ. 4.""أمْرٌ ذُو بالٍ"" : أمْرٌ ذُو شأْنٍ عَظِيمٍ. يوسف آية "', '');
