INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6897, 'بُنْدُقِيَّةٌ', 'بندقية', 'جامد', '', 'بندقية', 'بندقة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَنَادِقُ"', '', '', '', '', '', '', '', '', '"ج: بَنَادِقُ. 1. ""أصَابَ بِبُنْدُقِيَّتِهِ أرْنَباً"" : آلَةٌ لَها ذِرَاعٌ من خَشَبٍ وَقنَاةٌ حَدِيديَّةٌ يُقْـذَفُ بِهَـا الرَّصَـاصُ. 2.""يَسْتَخْدِمُ الجُنُودُ فِي مَعَارِكِهِمُ الحَرْبِيَّةِ بَنَادِقَ م"', ':لا جذر:لا مفرد');
