INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6901, 'بَنْزِينٌ', 'بنزين', 'جامد', '', 'بنزين', 'بنزن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""بَنْزِينُ السَّيَّارَةِ"" : سَائِلٌ زَيْتِيٌّ يُسْتَخْرَجُ مِنَ النَّفْطِ، سَريعُ الاشْتِعَالِ وَيُسْتَعْمَلُ وَقُوداً لِمُحَرِّكَاتِ السَّيَّارَاتِ وَالطَّائرَاتِ وغَيْرِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6902, 'بِنْصِرٌ', 'بنصر', 'جامد', '', 'بنصر', 'بنصر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَنَاصِرُ"', '', 'R', '', '', '', '', '', '', '"ج: بَنَاصِرُ. (مؤ). ""وَضَعتْ فِي بِنْصَرِهَا خَاتَماً"" : الأصبُعُ بَيْنَ الوُسْطَى والخنْصَر."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6903, 'بَنَاصِرُ', 'بناصر', 'جامد', '', 'بناصر', 'بنصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6904, 'بِنْطَالٌ', 'بنطال', 'جامد', '', 'بنطال', 'بنطل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بنَاطِيلُ"', '', 'R', '', '', '', '', '', '', '"ج: بنَاطِيلُ. : لِبَاسٌ يُشْبِهُ السِّرْوَال، ذُو شِقَّيْنِ تَدْخُلُ فِيهِمَا الرِّجْلان، يَرْتَدِيهِ الرِّجَالُ وَالنِّسَاءُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6905, 'بنَاطِيلُ', 'بناطيل', 'جامد', '', 'بناطيل', 'بنطل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6906, 'بَنَفْسَجَةٌ', 'بنفسجة', 'جامد', '', 'بنفسجة', 'بنفسجة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَنَفْسَجٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: بَنَفْسَجٌ (نب).: زَهْرَةٌ منْ فَصيلَةِ البَنَفْسَجيَّات، عَطِرَةٌ، لَهَا ألْوَانٌ مُخْتَلِفَةٌ (بَنَفْسَجِيَّةٌ وَصَفْرَاءُ وَبَيْضَاءُ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6907, 'بَنَفْسَجٌ', 'بنفسج', 'جامد', '', 'بنفسج', 'بنفسج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6908, 'بَنَفْسَجيَّاتٌ', 'بنفسجيات', 'جامد', '', 'بنفسجيات', 'بنفسجت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": من فَصِيلَةِ البَنَفْسَجيَّاتِ مِنْ ذَوَاتِ الفِلْقَتَيْنِ، جُلُّ أنْوَاعِهَا عُشْبيَّةٌ، ذَاتُ أزْهَارٍ عَطِرَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6909, 'بَنِيقَةٌ', 'بنيقة', 'جامد', 'بنق', 'بنيقة', 'بنقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"بَنِيقَةٌ-بَنِيقَةٌ [ب ن ق]. 1.""بَنِيقَةُ الشَّجَرِ"" : السَّطْرُ الْمُطَّرِدُ مِنْهُ. 2.""بَنِيقَةُ الْقَمِيصِ"" : الزِّيقُ يُخَاطُ فِي جَيْبِهِ، تُثْبَتُ فِيهِ الأَزْرَارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6910, 'بَنْكٌ', 'بنك', 'جامد', '', 'بنك', 'بنك', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بُنُوكٌ"', '', 'R', '', '', '', '', '', '', '"ج: بُنُوكٌ. ""يَضَعُ كُلَّ أمْوَالِهِ فِي البَنْكِ وَيَسْحَبُهَا مِنْ حِينٍ لآخَرَ"" : مُؤَسَّسَةٌ مَالِيَّةٌ توضَعُ فيها الأمْوَا"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6911, 'بُنُوكٌ', 'بنوك', 'جامد', '', 'بنوك', 'بنك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6912, 'أَبْنَاكٌ', 'أبناك', 'جامد', '', 'ءبناك', 'بنك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6913, 'بَنْكَامٌ', 'بنكام', 'جامد', '', 'بنكام', 'بنكم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": 1. سَاعَةُ الرَّمْلِ، 2.""أَداةٌ تُتَّخَدُ مِقْياساً زَمَنِيّاً لِطَه"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6914, 'بَنْكِرْيَاس', 'بنكرياس', 'جامد', '', 'بنكرياس', 'بنكرس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": لَوْزَةُ الْمَعِدَةِ، وَهِيَ عِبَارَةٌ عَنْ عُقْدَةٍ ضَخْمَةٍ تُوجَدُ خَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6915, 'بَنَانٌ', 'بنان', 'جامد', 'بنن', 'بنان', 'بنن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَنَانٌ-بَنَانٌ [ب ن ن]. 1.""ضَرَبَهُ عَلَى أطْرَافِ بَنَانِهِ"" : أطْرَافِ أصَابِعِهِ. 2.""يُشَارُ إلَيْهِ بِالبَنَانِ"" : كُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6916, 'بِنْتٌ', 'بنت', 'جامد', 'بني', 'بنت', 'بنت', '', '', '', 'مفرد', 'DnN', '', '', '"بناتٌ"', '', 'R', '', '', '', '', '', '', '". 1.""رُزِقَ بِنْتاً"" : الولَدُ الأنْثَى. 2."" لَمْ يَنْبَسْ بِبِنْتٍ شَفَةٍ"" : لَمْ تَصْدُرْ عَنْهُ وَلاَ كَلِمَةٌ وَاحِدَةٌ. 3.""هَذَا مِنْ بناتِ أفْكَارِهِ"" : مِنْ تَصَوّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6917, 'بناتٌ', 'بنات', 'جامد', '', 'بنات', 'بنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6918, 'بِنْيَةٌ', 'بنية', 'جامد', 'بني', 'بنية', 'بنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":بُنىً"', '', '', '', '', '', '', '', '', '". 1."" كَانَتْ بِنْيَةُ العِمَارَةِ عَلَى النَّمَطِ الحَدِيثِ"" : شَكْلُهَا، هَيْئَتُهَا. 2.""لَمْ يَكُنْ قَادِراً عَلَى حَمْلِ الأثْقَالِ لِضُعْفِ بِنْيَتِهِ"" : أيْ هُوَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6919, 'بُنىً', 'بنى', 'جامد', '', 'بنى', 'بن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6920, 'مَبَانِي', 'مباني', 'جامد', 'بني', 'مباني', 'مبن', '', 'Tk', '', 'مفرد', 'DnN', '', '', '"مَبْنـىً"', '', '', '', '', '', '', '', '', '". 1.""شُيِّدَتِ الْمَبَانِي"" : العِمَارَاتُ، البِنَايَاتُ. 2.""حُرُوفُ الْمَبَانِي"" : أَيِ الْحُرُوفُ الهِجَائِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6921, 'مَبْنىً', 'مبنى', 'جامد', '', 'مبنى', 'مبن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6922, 'مَبْنىً', 'مبنى', 'جامد', 'بني', 'مبنى', 'مبن', '', '', '', 'مفرد', 'Dy', '', '', '"مَبَانٍ:الْمَبَانِي"', '', '', '', '', '', '', '', '', '". 1.""تَمَّ إنْشَاءُ مَبْنـىً جَدِيدٍ"" : بِنَايَةٍ. 2.""الْمَعْنَى وَالْمَبْنَى"" : الشَّكْلُ، التَّعْبِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6923, 'مَبَانِي', 'مباني', 'جامد', '', 'مباني', 'مبن', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6924, 'بُهَارٌ', 'بهار', 'جامد', '', 'بهار', 'بهر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": جِنْسُ سَمَكٍ، كَبِيرُ الْقَدِّ، مِنْ فَصِيلَةِ الْبُهَارِيَّاتِ لَهُ جِسْمٌ مُسْتَطِيلٌ مُفَلْطَحٌ مِنَ الْجَانِبَيْنِ، وَمُغَطّىً بِقُشُورٍ مُشْطِيَّةٍ صَغِيرَةٍ، لَذِيذُ الطَّعْمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6925, 'مَبْهَجٌ', 'مبهج', 'جامد', 'بهج', 'مبهج', 'مبهج', '', '', '', 'مفرد', 'DnN', '', '', '"مَبَاهِجُ"', '', 'R', '', '', '', '', '', '', '". ""مَبْهَجُ الْحَيَاةِ"" : مَسَرَّتُهَا، بَهْجَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6926, 'مَبَاهِجُ', 'مباهج', 'جامد', '', 'مباهج', 'مبهج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6927, 'أبْهَرٌ', 'أبهر', 'جامد', 'بهر', 'ءبهر', 'بهر', '', '', '', 'مفرد', 'DnN', '', '', '"مثنىأبْهَرَانِ-أبْهَرَانِ"', '', 'R', '', '', '', '', '', '', '"أبْهَرَانِ-أبْهَرَانِ [ب هـ ر]. : العِرْقَانِ اللذَانِ يَخرُجَانِ مِنَ القَلْب وَمِنْهُمَا تَنْشَعِبُ كُلُّ الشَّرَايِينِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6928, 'بَهَارٌ', 'بهار', 'جامد', 'بهر', 'بهار', 'بهر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَهَارٌ-بَهَارٌ [ب هـ ر]. 1.""وَضَعَ البَهَارَ فِي الطَّعَامِ"" : التَّوَابِلَ، الإبْزَارَ. 2.""بَهَارُهَا لاَ أجْمَلَ مِنْهُ"" : جَمَالُهَا، حُسْنُهَا. 3.""اِنْتَشَرَ زَهْرُ البَهَارِ فِي الحُقُولِ"" : زَهْرٌ طَيِّبُ الرائِحَةِ يَكْثُرُ فِي فَصْلِ الرَّبِيعِ وَيُسَمَّى أيْضاً العَرَارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6929, 'بُهَارِيَّاتٌ', 'بهاريات', 'جامد', 'بهر', 'بهاريات', 'بهرت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"بُهَارِيَّاتٌ-بُهَارِيَّاتٌ [ب هـ ر]. : فَصِيلَةٌ سَمَكِيَّةٌ مِنْ كَامِلاَتِ الْعِظَام، وَشَائِكَاتِ الزَّعَانِفِ، أَصْنَافُهَا عَدِيدَةٌ مِنْ أَشْهَرِهَا الْبُهَارُ وَالزَّجَرُ، مُتَمَيِّزَةٌ بِكِبَرِ قَدِّهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6930, 'بَهْرَجٌ', 'بهرج', 'جامد', '', 'بهرج', 'بهرج', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1.""لُؤْلُؤٌ بَهْرَجٌ"" : اِصْطِنَاعِيٌّ، بِلا قِيمَةٍ. 2.""دِرْهَمٌ بَهْرَجٌ"" : زَائِفٌ، مَغْشُوشٌ. 3.""عَمَلٌ بَهْرَجٌ"" : رَدِيءٌ. 4.""قَوْلٌ بَهْرَجٌ"" : بَاطِلٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6931, 'بَهْلَوَانٌ', 'بهلوان', 'جامد', '', 'بهلوان', 'بهلن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""يُقَدِّمُ البَهْلَوَانُ ألْعَاباً غَرِيبَةً"" : مَنْ يَرْقُصُ وَيَمْشِي عَلَى الحِبَالِ وَالدَّوَائِرِ بِبَرَاعَةٍ فائِقَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6932, 'بُهْلُولٌ', 'بهلول', 'جامد', '', 'بهلول', 'بهلل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَهالِيلُ"', '', 'R', '', '', '', '', '', '', '"ج: بَهالِيلُ. 1.""بُهْلُولُ الحَيِّ"" : رَجُلٌ كَثِيرُ الضَّحِكِ، الضَّحّاكُ. 2.""رَجُلٌ بَهْلُولٌ"" : الجامِعُ لِكُلِّ صِفَاتِ الخَيْرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6933, 'بَهالِيلُ', 'بهاليل', 'جامد', '', 'بهاليل', 'بهلل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6934, 'بَهِيمَةٌ', 'بهيمة', 'جامد', 'بهم', 'بهيمة', 'بهمة', '', '', '', 'مفرد', 'DnN', '', '', '"بَهائِمُ"', '', '', '', '', '', '', '', '', '". 1.""تَقْبَعُ البَهَائِمُ فِي الحَظِيرَةِ"" : الدَّوَابُّ ذَاتُ القَوَائِمِ الأرْبَعِ بَرِّيةً أوْ بَحْرِيَّةً مَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6935, 'بَهائِمُ', 'بهائم', 'جامد', '', 'بهاءم', 'بهم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6936, 'باهَةٌ', 'باهة', 'جامد', 'بهو', 'باهة', 'بهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"باهَةٌ-باهَةٌ [ب هـ و].""وَقَفَ فِي باهَةِ الدَّارِ"" : فِي باحَتِها، ساحَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6937, 'بَهْوٌ', 'بهو', 'جامد', 'بهو', 'بهو', 'به', '', '', '', 'مفرد', 'DnN', '', '', '"أبْهَاءُ"', '', 'R', '', '', '', '', '', '', '". 1.""جَلَسَتِ العَرُوسُ فِي البَيْتِ"" : فِي صَدْرِ البَيْتِ. 2.""اِسْتَقْبَلَ ضُيُوفَهُ فِي البَهْوِ"" : الْمَكَانُ الْمُتَّسِعُ فِي الدَّارِ، قَاعَةُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6938, 'أبْهَاءُ', 'أبهاء', 'جامد', '', 'ءبهاء', 'به', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6939, 'مَبَاءةٌ', 'مباءة', 'جامد', 'بوأ', 'مباءة', 'مبة', '', '', '', 'مفرد', 'DnN', '', '', '"مَبَاوِئُ"', '', '', '', '', '', '', '', '', '". 1.""مَبَاءةُ الرَّجُلِ"" : مَنْزِلُهُ، مَسْكَنُهُ. 2.""هُوَ رَحِيبُ الْمَبَاءةِ"" : أَيْ ك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6940, 'مَبَاوِئُ', 'مباوئ', 'جامد', '', 'مباوء', 'مب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6941, 'بَوَاسِيرُ', 'بواسير', 'جامد', '', 'بواسير', 'بسر', '', '', '', 'جمع تكسير', '', '', '', '"مفردباسُورٌ"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"جمع: باسُورٌ : ن. باسور."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6942, 'بَابٌ', 'باب', 'جامد', 'بوب', 'باب', 'بب', '', '', '', 'مفرد', 'DnN', '', '', '"أَبْوَابٌ:بِيبَانٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أغْلَقَ بَابَ الدَّارِ"" : سَدَّ مَدْخَلَهَا، أيْ فَتْحَتَهَا، خَشَبٌ يُصْنَعُ منهُ رِتَاجٌ لِلْبُيُوتِ وَالغُرَفِ وَالدَّكَاكِينِ، ... إلخِ. ""دَخَلَ مِنَ البَابِ عِنْدَمَا سَمِعَ الجَوَابَ"". 2.""قَرَأْتُ البَابَ الأَوَّلَ مِنَ الكِتَابِ"" : الفُصُولَ الأوَلى مِنْهُ. 3.""أُغْلِقَتْ كُلُّ الأبْوَابِ فِي وَجْهِهِ"" : أي كُلُّ الطُّرُقِ، كُلُّ الطُرُقِ من كُلُّ السُّبُلِ. ""لَمْ يَتْرُكْ بَاباً إلاّ طَرَقَهُ"". 4.""العِيدُ عَلَى الأبْوابِ"" : أيْ صَارَ قَرِيباً. 5.""مِنْ بَابٍ أوْلَى أنْ تَكُونَ حَاضِراً"" : الأحْرَى، الأجْدَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6943, 'أَبْوَابٌ', 'أبواب', 'جامد', '', 'ءبواب', 'بب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6944, 'بِيبَانٌ', 'بيبان', 'جامد', '', 'بيبان', 'ببن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6945, 'بَوَّابَةٌ', 'بوابة', 'جامد', 'بوب', 'بوابة', 'ببة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""وَاجْتَمَعَ النَّاسُ عِنْدَ بَوَّابَةِ الْم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6946, 'بُوتاسٌ', 'بوتاس', 'جامد', '', 'بوتاس', 'بتس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": هيِدْرُوكْسِيد البوتَاسْيُوم، صَلْبٌ أبْيَضُ قَابِلٌ للذَّوَبَانِ فِي الْمَاءِ، يُسْتَعْمَلُ لِتَبْيِيضِ الْمَلابِسِ وَصِنَاعَةِ الصَّابُونِ الأسْوَدِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6947, 'بُوتَاسْيُوم', 'بوتاسيوم', 'جامد', '', 'بوتاسيوم', 'بتسم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": عُنْصُرٌ ذُو لَوْنٍ أبيَضَ، فِضِّيّ لَيِّنٌ جِدّاً، يُوجَدُ فِي الصُّخُورِ وَمَاءِ البَحْرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6948, 'بُوتان', 'بوتان', 'جامد', '', 'بوتان', 'بتن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": غازٌ عَدِيمُ اللَّوْنِ والرَّائِحَةِ يُوجَدُ فِي الغَازِ وَالغَازَاتِ الْمُصَاحِبَةِ لِلْبِتْرُولِ، يُسْتَعْمَلُ للوَقُودِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6949, 'بُوتَقَةٌ', 'بوتقة', 'جامد', '', 'بوتقة', 'بتقة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات، بَواتقُ. 1."" حُمِيَتِ الْمَادَّةُ فِي البُوتَقَةِ"" : الوِعَاءُ المُسْتَعْمَلُ لِتَسْخِينِ الْمَوَادِّ تَسْخِيناً شَدِيداً. 2."" أفْرَغَ الصَّائِغُ مَادَّةً مَعْدِنيَّةً فِي البُوتَقَةِ"" : وِعَاءٌ عَلَى شَكْلِ مَخْرُوطٍ تُذَابُ فِيهِ الْمَعَادِنُ وَتُصْهَرُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6950, 'باحَةٌ', 'باحة', 'جامد', 'بوح', 'باحة', 'بحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":بُوحٌ"', '', 'R', '', '', '', '', '', '', '". 1.""باحَةُ القَصْرِ"": ساحَتُهُ. 2.""لاَحَتْ مِنْ بَعيدٍ باحَةٌ على ضِفافِ النَّهْرِ"" : النَّخيلُ الكَثيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6951, 'بُوحٌ', 'بوح', 'جامد', '', 'بوح', 'بح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6952, 'بُورٌ', 'بور', 'جامد', 'بور', 'بور', 'بر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بُورٌ-بُورٌ [ب و ر]. ""أغْلَبُ مَنَاطِقِ الجَنُوبِ بُورٌ"" : أرَاضٍ قَاحِلَةٌ لَمْ تُزْرَعْ، أو تُتْرَك سَنَةً لِتُزْرَعَ بَعْدَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6953, 'بُورْصَةٌ', 'بورصة', 'جامد', '', 'بورصة', 'برصة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '": مؤسَّسَةٌ مَالِيَّةٌ يَجْتَمِعُ فِيهَا يَوْمِيّاً وُكَلاَءُ الشَّرِكَاتِ الكُبْرَى والتُّجَّارُ وَعُمَلاَءُ الْمَصَارِفِ وَالسَّمَاسِرَةُ لِلْمُضَارَبَةِ بِالأمْوَالِ، وَتَبَادُلِ العُمْلاَتِ الأجْنَبِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6954, 'بُورِيٌّ', 'بوري', 'جامد', '', 'بوري', 'بر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": نَوْعٌ مِنَ السَّمَكِ مِنَ العَظْمِيَّاتِ الشَّائِكَةِ الزَّعانِفِ، يُوجَدُ فِي النَّهْرِ وَالبَحْرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6955, 'بَوسَةٌ', 'بوسة', 'جامد', '', 'بوسة', 'بسة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ج:بَوسَاتٌ. ""وَضَعَتِ البِنْتُ بَوسَةً عَلَى خَدِّ أُمِّهَا بِحَنَانٍ"" : قُبْلَةً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6956, 'بُوعٌ', 'بوع', 'جامد', '', 'بوع', 'بع', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أبْوَاعٌ"', '', 'R', '', '', '', '', '', '', '"ج: أبْوَاعٌ . 1.: عَظْمٌ يَلِي إبْهَامَ الرِّجْلِ. 2.""لاَ يَعْرِفُ كوعَهُ مِنْ بُوعِهِ"" : الجاهِلُ الَّذِي لا يَعْرِفُ شَيْئاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6957, 'أبْوَاعٌ', 'أبواع', 'جامد', '', 'ءبواع', 'بع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6958, 'بُوغَازٌ', 'بوغاز', 'جامد', '', 'بوغاز', 'بغز', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَوَاغِيزُ"', '', 'R', '', '', '', '', '', '', '"ج: بَوَاغِيزُ. ""بُوغَازُ جَبَلِ طَارِق"" : الْمَضِيق البَحْرِيُّ الْمَحْصُورُ بَيْنَ بَرَّيْنِ، أرْضَيْنِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6959, 'بَوَاغِيزُ', 'بواغيز', 'جامد', '', 'بواغيز', 'بغز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6960, 'باقَةٌ', 'باقة', 'جامد', 'بوق', 'باقة', 'بقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""وَضَعَتْ باقةَ زَهْرٍ بِجانِبِ النَّافِذَةِ"" : حَزْمَةٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6961, 'بُوقٌ', 'بوق', 'جامد', '', 'بوق', 'بق', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أبْوَاقٌ"', '', 'R', '', '', '', '', '', '', '"ج: أبْوَاقٌ. 1.""آلةٌ هَوَائِيَّةٌ نُحَاسِيَّةٌ أوْ خَشَبِيَّةٌ عَلَى شَكْلِ أُسْطُوَانَةٍ فِي ثَلاَثَةِ أرْبَاعِهِ الأولَى، ثُمَّ يَتَحَوَّلُ إلَى شَكْلٍ مَخْرُوطٍ فِي أسْفَلِهِ، كَانَ العَرَبُ يَسْتَخْدِمُونَهُ أثْنَاءَ الحُرُوبِ. 2.""كَانَ صَوْتُ البُوقِ يَمْلأُ الأرْجَاءَ"" : مُكَبِّرُ الصَّوْتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6962, 'أبْوَاقٌ', 'أبواق', 'جامد', '', 'ءبواق', 'بق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6963, 'بُوقَالٌ', 'بوقال', 'جامد', '', 'بوقال', 'بقل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بَواقِيلُ"', '', 'R', '', '', '', '', '', '', '"ج: بَواقِيلُ: ن. بَاقُولٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6964, 'بَواقِيلُ', 'بواقيل', 'جامد', '', 'بواقيل', 'بقل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6965, 'تَبُّولَةٌ', 'تبولة', 'جامد', 'بول', 'تبولة', 'تبلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَبُّولَةٌ-تَبُّولَةٌ [ب و ل] (طخ). ""التَّبُّولَةُ أَكْلَةٌ شَرْقِيَّةٌ"" : طَعَامٌ يُحَضَّرُ بِالبُرْغُلِ وَالبَقْدُونِسِ وَالبَصَلِ وَالْخَسِّ وَالنَّعْنَاعِ، وَيُتَبَّلُ بِالتَّوَابِلِ وَعَصِيرِ اللَّيْمُونِ وَالحَامِضِ وَالزَّيْتِ وَالمِلْحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6966, 'مِبْوَلَةٌ', 'مبولة', 'جامد', 'بول', 'مبولة', 'مبلة', '', '', '', 'مفرد', 'DnN', '', '', '"مَبَاوِلُ"', '', 'R', '', '', '', '', '', '', '". 1. : إِنَاءٌ يُبَـالُ فِيـهِ.2.: مَكَانٌ فِيالسَّاحَاتِ أَوِ الأَمَاكِنِ العَامَّةِ يَبُولُ فِيهِ النَّاسُ. ""يَبُولُ فِي الفِرَاشِ كَمَا أَبُولُ فِي هَذِهِ المِبْوَلَـةِ الآنَ وَكَمَا يَبُولُ جَمِيعُ النَّاسِ فِي جَمِيعِ الْمَبَاوِلِ"". (أحمد بوزفور)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6967, 'مَبَاوِلُ', 'مباول', 'جامد', '', 'مباول', 'مبل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6968, 'بُومٌ', 'بوم', 'جامد', '', 'بوم', 'بم', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"بُومٌ-بُومٌ، ةٌ (حو).: (مذ، مؤ). 1.""طيْرٌ مِنْ فَصِيلَةِ البُومِيَّاتِ، مِنْ جَوَارِحِ الَّليْلِ، يَسْكُنُ الأمَاكِنَ الخَرِبَةَ، يَنْقَضُّ عَلَى الجُرْذَانِ وَالفِئْرَانِ، يُضْرَبُ بِهِ الْمَثَلُ فِي الشُّؤْمِ. 2.""لَمَحَ بُومَةً فِي طَرِيقِهِ، فَعَـادَ مِـنْ حَيْثُ أتَى"" : عَادَ إِلَى بَيْتِهِ لِيَحُدَّ الشُّؤْمَ. ""الَّذِي يَكْتَسِبُ مَعَاشَهُ لَيْلاً، البُومَةُ وَالوَطْوَاطُ"". (التوحيدي)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6969, 'بُومِيَّاتٌ', 'بوميات', 'جامد', '', 'بوميات', 'بمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةُ البُومِ، مِنْ رُتْبَةِ الجَوَارِحِ الكَوَاسِرِ الليْلِيَّةِ، أنْوَاعُهَا عَدِيدَةٌ، مِنْهَا البُوهَةُ وَالخَبَلُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6970, 'بَوْنٌ', 'بون', 'جامد', '', 'بون', 'بن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"1."" بَيْنَ المدينَتَيْنِ بَوْنٌ شَاسِعٌ"" : مَسَافَةٌ طَوِيلَةٌ. 2.""مَا بَيْنَ الرَّجُلَيْنِ بَوْنٌ شَاسِعٌ"" : فَرْقٌ كَبِيرٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6971, 'بُوهَةٌ', 'بوهة', 'جامد', '', 'بوهة', 'بهة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '": البُومَةُ الصَّغِيرَةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6972, 'بُوَيْضَةٌ', 'بويضة', 'جامد', '', 'بويضة', 'بضة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات : مَشِيجٌ، خَلِيَّةٌ جُرْثُومِيَّةٌ حَيَّةٌ فِي الْمَبِيضِ وَتَكُونَ مُهَيَّأَةً لِلإخْصَابِ بِوَاسِطَةِ الْمَادَّةِ الْمَنَوِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6973, 'بَيْتٌ', 'بيت', 'جامد', 'بيت', 'بيت', 'بت', '', '', '', 'مفرد', 'DnN', '', '', '"بُيُوتٌ:أبْيَاتٌجبُيُوتَاتٌ"', '', 'R', '', '', '', '', '', '', '". 1.""دَخَلَ البَيْتَ آمِناً"" : مَحَلُّ السُّكْنَى والإقَامَةِ. 2.""هُوَ مِنْ أهْلِ بَيْتِهِ"" : مِنْ عِيَالِهِ، مِنْ أُسْرَتِهِ. 3.""آمُلُ زِيَارَةَ البَيْتِ الحَرَامِ"": الكَعْبَة. 4.""بَيْتُ اللَّهِ"" : الْمَسْجِدُ، الكَنِيسَةُ. 5.""بَيْتُ الْمَقْدِسِ"" : مَدِينَةُ القُدْسِ بِفِلِسْطِينَ الْمُحْتَلَّةِ. ""طَالَ الزَّمَنُ أمْ قَصُرَ، لاَ بُدَّ لِبَيْتِ الْمَقْدِسِ أنْ يَعُودَ لِلمُسْلِمِينَ وَلأهْلِهِ"". 6.""بَيْتُ الْمَالِ"" : خَزِينَةُ أمْوَالِ الدَّوْلَةِ. ""بَيْتُ الْمَالِ أمَانَةٌ فِي عُنُقِ الحَاكِمِ"". 7.""بَيْتُ العَنْكَبُوتِ"" : الخُيُوطُ الَّتِي تَنْسُجُهَا العَنْكَبُوتالعنكبوت آية 41وَإنَّ أوْهَنَ البُيُوتِ لَبَيْتُ العَنْكَبُوتِ. (قرآن) 8.""أوْهَى مِنْ بَيْتِ العَنْكَبُوتِ"" : عِبَارَةٌ تُقَالُ ل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6974, 'بُيُوتٌ', 'بيوت', 'جامد', '', 'بيوت', 'بت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
