INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6978, 'مُبِيدٌ', 'مبيد', 'جامد', 'بيد', 'مبيد', 'مبد', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". ""اِسْتَعْمَلَ مُبِيدَ الْحَشَرَاتِ"" : مَادَّةٌ سَامَّةٌ لإِبَادَةِ الْحَشَرَاتِ. ""مُبِيدُ الجَرَاثِيمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6979, 'بَيْداءُ', 'بيداء', 'جامد', '', 'بيداء', 'بد', '', '', '', 'جمع تكسير', 'DzDw', '', '', '"بِيدٌ:بَيْدَاواتٌ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"ج: بِيدٌ، بَيْدَاواتٌ : الصَّحْراءُ."', ':لا جذر:لا مفرد');
