INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6982, 'بَيْدَقٌ', 'بيدق', 'جامد', '', 'بيدق', 'بدق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1.: طائِرٌ مِن الكَوَاسِرِ فِي حَجْمِ الصَّقْرِ، لا يَصِيدُ إِلاَّ العَصَافِيرَ. 2.: بَيْدَقٌ: ن. بيذَق."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6983, 'بَيذَقٌ', 'بيذق', 'جامد', '', 'بيذق', 'بذق', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بيَاذِقُ"', '', 'R', '', '', '', '', '', '', '"ج: بيَاذِقُ. ""لَمْ يَكُنْ يُحَرِّكُ البَيْذَقَ إلاَّ بَعْدَ تفْكِيرٍ"" : قِطْعَةُ الشِّطْرَنْجِ الصَّغِيرَةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6984, 'بيَاذِقُ', 'بياذق', 'جامد', '', 'بياذق', 'بذق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6985, 'بَيْرَمٌ', 'بيرم', 'جامد', '', 'بيرم', 'برم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": أداةٌ حَدِيدِيَّةٌ يَسْتَعْمِلُهَا النَّجَّارُ لِشَقِّ الخَشَبَةِ عِنْدَ نَشْرِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6986, 'بَيْرُوتُ', 'بيروت', 'جامد', '', 'بيروت', 'برت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'N', 'N', 'O', '', '": عَاصِمَةُ الجُمْهُورِيَّةِ اللُّبْنَانِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6987, 'بَيْضَةٌ', 'بيضة', 'جامد', 'بيض', 'بيضة', 'بضة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":بُيوضٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَلْقَتِ الدَّجاجَةُ بَيْضَتَها"" : كُتْلَةٌ بَيْضَوِيَّةُ الشَّكْلِ بَيْضاءُ اللَّوْنِ بِها مادَّةٌ لَزِجةٌ تُغَلِّفُها قِشْرَةٌ، في داخِلِها مُحٌّ أَصْفَرُ اللَّوْنِ، وَهِيَ تَنْشَأُ في مَبِيضِ إِناثِ الطَّيْرِ مُكَوِّنَةً جُرْثومَةَ الحَياةِ، جَنيناً مِنْ جِنْسِها. 2.""شَعَرَ بِأَلَمٍ في بَيْضَتِهِ"" : في خِصْيَتِهِ. 3.""وَضَعَ الجُنْدِيُّ بَيْضَتَهُ على رَأْسِهِ"" : الخُوذَةُ. 4.""اِفْتَرَشَ القَوْمُ بَيْضَةَ الدَّارِ"" : وَسَطَها. 5.""بَيْضَةُ الخِدْرِ"" : الفَتاةُ. 6.""بَيْضَةُ الدِّيكِ"" : يُقالُ لِلشَّيْءِ الذِي لا يَقَعُ إِلاَّ مَرَّةً واحِدَةً وَلا يَتَكَرَّرُ أَبَداً. 7.""بَيْضُ الأنوقِ"": ن. أنوق."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6988, 'بُيوضٌ', 'بيوض', 'جامد', '', 'بيوض', 'بض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6989, 'بَيْطَرَةٌ', 'بيطرة', 'جامد', '', 'بيطرة', 'بطرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '": مِهْنَةُ الطَّبِيبِ البَيْطارِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6990, 'بَاعٌ', 'باع', 'جامد', 'بيع', 'باع', 'بع', '', '', '', 'مفرد', 'DnN', '', '', '"أبْوَاعٌ:بيعانٌ"', '', 'R', '', '', '', '', '', '', '". 1.: مَسافَةُ مَا بَيْنَ الكَفَّيْنِ إذَا بُسِطَ الذِّرَاعَانِ. 2.""هُوَ طَوِيلُ الباعِ"" : مُقْتَدِرٌ، لَهُ بَأْسٌ. 3.""كَانَ رَحْبَ البَاعِ"" : سَمْحٌ،كَرِيمٌ. ""كَرِيمُ البَاعِ"". 4. يُقالُ : ""قَصِيرُ البَاعِ"" : ضَعِيفٌ، عَاجِزٌ، لاَ قُدْرَةَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6991, 'أبْوَاعٌ', 'أبواع', 'جامد', '', 'ءبواع', 'بع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6992, 'بيعانٌ', 'بيعان', 'جامد', '', 'بيعان', 'بعن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6993, 'بَيْعَةٌ', 'بيعة', 'جامد', '', 'بيعة', 'بعة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. 1.""جَرَتِ البَيْعَةُ في السُّوقِ"" : الصَّفْقَةُ على عَقْدِ البَيْعِ. 2.""جاءتِ القَبائِلُ لِتُقَدِّمَ البَيْعَةَ لِلْمَلِكِ"" : الطَّاعَةَ، المُبايَعَةَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6994, 'بِيعَةٌ', 'بيعة', 'جامد', '', 'بيعة', 'بعة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"بِيَعٌ"', '', 'R', '', '', '', '', '', '', '"ج: بِيَعٌ. 1.: هَيْئَةُ البَيْعِ. 2. ""بِيعَةُ اليَهودِ"" : مَعْبَدُ اليَهودِ. 3.""بِيعَةُ النَّصارَى"" : الكَنيسَةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6995, 'بِيَعٌ', 'بيع', 'جامد', '', 'بيع', 'بع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6996, 'بِيكارٌ', 'بيكار', 'جامد', '', 'بيكار', 'بكر', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '": ن. بَرْجَلٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6997, 'بَيِّنٌ', 'بين', 'جامد', 'بين', 'بين', 'بن', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"بَيْنٌ-بَيْنٌ [ب ي ن] (مص. بانَ). 1.""حالَ البَيْنُ بَيْنَهُما"" : الفِراقُ. 2.""اِشْتَدَّ بَيْنُ القَوْمِ"" : العَداوَةُ. 3.""ذاتُ البَيْنِ"" : القَرابَةُ، النَّسَبُ. 4.""تَقَطَّعَ البَيْنُ بَيْنَهُما"" : اِنْقَطَعَتْ عَلاقَةُ الوَصْلِ. 5.""سَعَى في إِصْلاحِ ذاتِ البَيْنِ بَيْنَهُما"" : أَيْ إِصْلاحُ عَلاقاتِهِمْ الَّتِي ساءتْ. ‎. 6.""أَشْأَمُ مِنْ غُرابِ البَيْنِ"" : يَتَشاءمُ بِهِ بأنَّهُ نَذِيرُ الفُرْقَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6998, 'بَيِّنَةٌ', 'بينة', 'جامد', 'بين', 'بينة', 'بنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""أتَى بِالبَيِّنَةِ الوَاضِحَةِ"": الحُجَّةُ، الدَّلِيلُ. 2.""قَرَأ آيَاتٍ بَيِّنَاتٍ"" : آيَاتُ القُرآنِ الكَرِيمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(6999, 'بِيئَةٌ', 'بيئة', 'جامد', '', 'بيءة', 'بة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'Rp', '', '', '', '', '', '', '": 1. هِيَ مَجْمُوعُ العَنَاصِرِ الطَّبِيعِيَّةِ والاصْطِنَاعِيَّةِ التِي تُحِيطُ بالإنْسَانِ وَالحَيَوَانِ وَالنَّبَاتِ، وتُشَكِّلُ مُحِيطَهُ الطَّبِيعيِّ. ""مِنْ أوْجَبِ الواجِبَاتِ فِي عَصْرِنَا ضَرُورَةُ المُحافَظَةِ عَلَى البِيئَةِ"" ""عَاشَ فِي بِيئَةٍ صَحْرَاوِيَّةٍ"". 2.""عَوَامِلُ البِيئَةِ"" : أي العَوَامِلُ الَّتِي تُسَيْطِرُ عَلَى أحْوَالِ الكَائِنَاتِ الحَيَّةِ وَتَوْزِيعِهَا فِي مُحِيطَاتِ الطَّبِيعَةِ المُخْتَلِفَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7000, 'تَابِلٌ', 'تابل', 'جامد', '', 'تابل', 'تبل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"تَوَابِلُ"', '', 'R', '', '', '', '', '', '', '"ج: تَوَابِلُ. ""وَضَعَتْ تَوَابِلَ فِي الطَّعَامِ"" : مَوَادٌّ تُطَيِّبُ الطَّعَامَ كَالفُلْفُلِ والإِبْزَارِ والزَّعْفَرَانِ، إلخ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7001, 'تَوَابِلُ', 'توابل', 'جامد', '', 'توابل', 'تبل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
