INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7014, 'تِبْنٌ', 'تبن', 'جامد', '', 'تبن', 'تبن', '', '', '', 'جمع تكسير', '', '', '', '"(الوَاحِدَةُتِبْنَةٌ)"', '', 'R', '', '', '', '', '', '', '"تِبْنٌ-تِبْنٌ (الوَاحِدَةُ تِبْنَةٌ). ""تَرَاكَمَتْ أَكْوَامٌ مِنَ التِّبْنِ حَوْلَ البَيَادِرِ بَعْدَ الدّ"', ':لا جذر:لا مفرد');
