INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7021, 'تَخْتٌ', 'تخت', 'جامد', '', 'تخت', 'تخت', '', '', '', 'جمع تكسير', 'DnN', '', '', '"تُخُوتٌ"', '', 'R', '', '', '', '', '', '', '"ج: تُخُوتٌ. 1.""وَضَعَتْ فَسَاتِينَهَا فِي التَّخْتِ"" : وِعَاءٌ مِنْ خَشَبٍ تُصَانُ فِيهِ الثِّيَابُ. 2.""اِسْتَرَاحَ عَلَى تَخْتِهِ"" : عَلَى سَرِيرِهِ. 3.""تَخْتُ الْمَلِكِ"" : عَرْشُهُ ."', ':لا جذر:لا مفرد');
