INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7023, 'تَدْرُجٌ', 'تدرج', 'جامد', '', 'تدرج', 'تدرج', '', '', '', 'جمع تكسير', 'DnN', '', '', '"تَدَارِجُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: تَدَارِجُ: طَيْرٌ مِنْ فَصِيلَةِ التَّدْرُجِيَّاتِ، مِنْ رُتْبَةِ الدَّجَاجِيَّاتِ، جَميلُ الصُّورَةِ، أَرْقَشُ، لَهُ رَأْسٌ مُعْتَـدِلٌ، وَمِنْقَارٌغَليظٌٌ وَقَوِيٌّ، فِي كُلِّ قَائِمَةٍ ثَلاَثَةُ أَصَابِعَ أَمَامِيَّةٍ طَوِيلَةٍوَأُصْبُعٌٌ خَلْفِيٌّ،طَويلُُ الذَّنَبِ نِسْبِيّاً. مِنْهُ أَنْوَاعٌ مَوْطِنُهُ الأَصْلِيُّ الأَنَاضُولُ وَالصِّينُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7024, 'تَدَارِجُ', 'تدارج', 'جامد', '', 'تدارج', 'تدرج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
