INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7029, 'تُرَابٌ', 'تراب', 'جامد', 'ترب', 'تراب', 'ترب', '', '', '', 'مفرد', 'DnN', '', '', '"أَتْرِبَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""يَرْفَعُ التُّرَابَ بِمِكْنَسَتِهِ"" : غُبَارُ الأَرْضِ، أَيْ مَا نَعِمَ مِنْ أَدِيمِهَا. ""تَرَاكَمَتِ الأَتْرِبَةُ بِالأَزِقَّةِ"" غافر آية 67 هُوَ الَّذِي خَلَقَكُمْ مِنْ تُرَابٍ .(قرآن). 2.""وَارَاهُ التُّرَابَ"" : دَفنَهُ بِالأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7030, 'أَتْرِبَةٌ', 'أتربة', 'جامد', '', 'ءتربة', 'تربة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7031, 'تُرْبَةٌ', 'تربة', 'جامد', 'ترب', 'تربة', 'تربة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":تُرَبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَارَاهُ فِي تُرْبَتِهِ"" : فِي قَبْرِهِ. 2.""وَقَفَ يَتَأَمَّلُ تُرْبَةَ الْمَدِينَةِ"" : الْمَقْبَرَةُ. 3.""نَشَأَ فِي تُربَـةٍ صَالِحَةٍ"" : فِي بِيئَةٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7032, 'تُرَبٌ', 'ترب', 'جامد', '', 'ترب', 'ترب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7033, 'تِرْبٌ', 'ترب', 'جامد', '', 'ترب', 'ترب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَتْرَابٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَتْرَابٌ. ""إِنَّ هَذَا الوَلَدَ تِرْبُ ابْنِي"" : هُوَ فِي سِنِّهِ. وَيُسْتَعْمَلُ أَكْثَرَ مَعَ الْمُؤَنَّثِ : ""سُعَادُ تِرْبُ سَلْمَى"". ""خَرَجَ مَعَ أَتْرابِهِ "" : مَعَ أَصْدِقَائِهِ الَّذِين هُمْ فِي سِنِّهِ النبأ آية 31،32،33 إِنَّ لِلْمُتَّقِينَ مَفَازاً، حَدَائِقَ وَأَعْنَاباً وَكَواعِبَ أَتْرَاباً . (قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7034, 'أَتْرَابٌ', 'أتراب', 'جامد', '', 'ءتراب', 'ترب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7035, 'تُرْجُمَانٌ', 'ترجمان', 'جامد', 'ترجم', 'ترجمان', 'ترجمن', '', '', '', 'مفرد', 'DnN', '', '', '"تَرَاجِمَةٌ"', '', 'R', '', '', '', '', '', '', '". ""طَلَبَ مِنْ تُرْجُمَانٍ أَنْ يُتَرْجِمَ لَهُ نُصُوصاً إِدَاريَّةً"" : مَنْ يَنْقُلُ الكَلاَمَ مِنْ لُغَةٍ إِلَى لُغةٍ أُخْرَى. ""تُرْجُمَانٌ مُحَلَّفٌ"" ""الشَّاعِرُ هُوَ تُرْجُمَانُ النَّفْسِ"".(ميخائيل نعيمة) ""اللِّسَانُ تُرْجُمَانُ القَلْبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7036, 'تَرَاجِمَةٌ', 'تراجمة', 'جامد', '', 'تراجمة', 'ترجمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7037, 'تُرْسٌ', 'ترس', 'جامد', '', 'ترس', 'ترس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَتْرَاسٌ:تُرُوسٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَتْرَاسٌ، تُرُوسٌ. 1.""كَانَ بِيَدِ الفَارسِ تُرْسُـهُ وَهُوَ يُحَارِبُ خَصْمَهُ"" : صَفْحَةٌ مِنَ الفُولاَذِ لِلْوِقَايَةِ مِنْ طَعْنَةِ السَّيْفِ وَضَرَبَاتِهِ. 2.""تُرْسُ الشَّمْسِ"" : قُرْصُهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7038, 'أَتْرَاسٌ', 'أتراس', 'جامد', '', 'ءتراس', 'ترس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7039, 'تُرُوسٌ', 'تروس', 'جامد', '', 'تروس', 'ترس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7040, 'تَرْسَانَةٌ', 'ترسانة', 'جامد', '', 'ترسانة', 'ترسنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرْسَانَةٌ-تَرْسَانَةٌ (عسك). 1.""أَخْرَجَ الجَيْشُ مَا فِي تَرْسَانَتِهِ"" : مُسْتَوْدَعُ ذَخَائِرِ الأَسْلِحَةِ. 2.""تَرْسَانَةُ السُّفُنِ"" : مَصْنَعُ السُّفُنِ وَالْمَرَاكِبِ ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7041, 'تُرْعَةٌ', 'ترعة', 'جامد', '', 'ترعة', 'ترعة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"تُرَعٌ"', '', 'R', '', '', '', '', '', '', '"ج: تُرَعٌ. ""يَنْسَابُ الْمَاءُ فِي تُرَعٍ إِلَى الجِنَانِ"" : أَيْ يَنْسَابُ فِي قَنَوَاتٍ ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7042, 'تُرَعٌ', 'ترع', 'جامد', '', 'ترع', 'ترع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7043, 'تُرْغُلَّةٌ', 'ترغلة', 'جامد', '', 'ترغلة', 'ترغلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"تُرْغُلَّةٌ-تُرْغُلَّةٌ (حو).: طَيْرٌ مِنْ فَصِيلَةِ الحَمَامِيَّاتِ، أَصْغَرُ حَجْماًمِنَ الحَمَامِ البَرِّيِّ، وَهُـوَ مِـنَ الطُّيُـورِ الْمُهَاجِرَةِ، لَوْنُهُ كَسْتُنَائِيٌّ وَبُنِّيٌّ أَحْمَرُ مَعَ وُجُودِ نُقَطٍ سَوْداءَ، بِعُنُقِهِ رُقْعَةٌ صَغِيرَةُ ذَاتُ أَشْرِطَةٍ سُودٍ وَبِيضٍ، رِيشُ ذَنَبِهِ أَسْوَدُ مَعَ إِطَارٍ أَبْيَضَ يُمَيِّزُهُ ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7044, 'تُرْفَةٌ', 'ترفة', 'جامد', 'ترف', 'ترفة', 'ترفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تُرْفَةٌ-تُرْفَةٌ [ت ر ف]. ""كَانَ يَعِيشُ فِي تُرْفَةٍ"" : فيِ عَيْشٍ رَغْدٍ وَنِعْمَةٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7045, 'تِرْفَاسٌ', 'ترفاس', 'جامد', '', 'ترفاس', 'ترفس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ن. الكَمْأَةُ ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7046, 'تَرِكَةٌ', 'تركة', 'جامد', 'ترك', 'تركة', 'تركة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرِكَةٌ-تَرِكَةٌ [ت ر ك]. 1.""تَرَكَ الشَّيْخُ تَرِكَةً لاَ تُقَدَّرُ لِأَوْلاَدِهِ"" : إِرْثاً. 2.""هَذَا مِنْ تَرِكَةِ الْمُوَظَّفِ السَّابِقِ"" : مِنْ مُخَلَّفَاتِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7047, 'تُرْمُسٌ', 'ترمس', 'جامد', '', 'ترمس', 'ترمس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"تُرْمُسٌ-تُرْمُسٌ (نب).: نَبَاتَاتٌ زِرَاعِيَّةٌ مِنْ فَصِيلَةِ القَطاَنِيَّاتِ، وَهِيَ أَنْوَاعٌ، بَعْضُهَا حَبُّهُ أَصْغَرُ، وَطَعْمُهَا مُرٌّ، تُؤْكَلُ بَعْدَ نَقْعِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7048, 'تِرْمُوسٌ', 'ترموس', 'جامد', '', 'ترموس', 'ترمس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": إِنَاءٌ مِنْ مَعْدِنٍ عَازِلٍ يَحْفَظُ مَا يَحْوِيهِ مِنْ سَوَائِلَ بِدَرَجَةِ حَرَارَتِهَا سَاخِناً كَانَ أَوْ بَارِداً ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7049, 'تُرُنْجٌ', 'ترنج', 'جامد', '', 'ترنج', 'ترنج', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"تُرُنْجٌ-تُرُنْجٌ (نب).: نَبَاتٌ مِنْ فَصِيلَةِ البُرْتُقَالِيَّاتِ أَكْبَرُ حَجْماً مِنْ لَيْمُونِ الحَامِضِ، مُرُّ الطَّعْمِ، يُسْتَعْمَلُ فِي صُنْعِ الحَلَوِيَّاتِ يُسَمَّى بِعَامِّيَّةِ الشَّرْقِ الكَبَّادَ، وَبِعَامِّيَّةِ الْمَغْرِبِ الزَّنْبُوغُ وَيُطْلقُ عَلَيْهِ أَيْضاً الأُتْرُجُّ ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7050, 'تُرُنْجَانٌ', 'ترنجان', 'جامد', '', 'ترنجان', 'ترنجن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"تُرُنْجَانٌ-تُرُنْجَانٌ (نب).: نَبَاتٌ مِنْ فَصِيلَةِ الشَّفَوِيَّاتِ، عَطِرُ الرَّائِحَةِ يَـنْبُتُ بـَرِّيّاً فِي الأَرَاضِي الرَّطْبَةِ، يُسْتَعْمَلُ فِي الطِّبِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7051, 'تُرَّهَةٌ', 'ترهة', 'جامد', '', 'ترهة', 'ترهة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. 1.""لاَتَصْدُرُ عَنْهُ إِلاَّ التُّرَّهَاتُ"" : تَوَافِهُ الأُمُورِ. 2.""هَذِهِ تُرَّهَةٌ لَيْسَ غَيْرُ"" : السَّخَافَةُ، التَّفَاهَةُ. ""مَنْ يَنْتَشِلُنَا مِنْ خُرَافَاتِ أَمْسِنَا وَتُرَّهَاتِ يَوْمِنَا"".(ميخائيل نعيمة)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7052, 'تَروتَةٌ', 'تروتة', 'جامد', '', 'تروتة', 'ترتة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"جِنْسٌ سَمَكٍ مِنْ فَصيلَةِ سَلْمونِيّاتِ، يَعيشُ في الأَنْهُرِ، طَعْمُهُ لَذيذٌ جِدّاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7053, 'تَرْوِيحَةٌ', 'ترويحة', 'جامد', '', 'ترويحة', 'ترحة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"ن. تَرَاوِيحُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7054, 'تَرِيبَةٌ', 'تريبة', 'جامد', '', 'تريبة', 'تربة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"تَرَائِبُنتَرَائِبُ"', '', '', '', '', '', '', '', '', '"ج: تَرَائِبُ. ن. تَرَائِبُ. 1.: العَظْمَةُ مِنَ الصَّدْرِ. 2.""تَرِيـبَةُ الصَّدْرِ"" : مَوْضِعُ القِلاَدَةِ مِنَ الصَّدْرِ ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7055, 'تَرَائِبُ', 'ترائب', 'جامد', '', 'تراءب', 'ترب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7056, 'تِسْعَةٌ', 'تسعة', 'جامد', 'تسع', 'تسعة', 'تسعة', '', '', '', 'مفرد', '', '', '', '"مُذَكَّرُتِسْعٍ"', '', '', '', 'N', 'O', 'N', 'O', '', '"تِسْعَةٌ-تِسْعَةٌ [ت س ع]. عَدَدٌ (9). مُذَكَّرُ تِسْعٍ: 1.""وَصَلَ تِسْعَةُ رِجَالٍ"" : عَدَدٌ مُفْرَدٌ مَعْدُودُهُ جَمْعُ مُذَكَّرٍ. 2.""سَلَّمْتُهُ تِسْعَةَ عَشَرَ دِرْهَماً"" : عَدَدٌ مُرَكَّبٌ مَعْدُودُهُ مُذَكَّرٌ مُفْرَدٌ مَنْصُوبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7057, 'تُسْعٌ', 'تسع', 'جامد', 'تسع', 'تسع', 'تسع', '', '', '', 'مفرد', '', '', '', '"أَتْسَاعٌ"', '', '', '', '', '', '', '', '', '".: الجُزْءُ مِنْ تِسْعَةِ أَجْزَاءِ الشَّيْءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7058, 'أَتْسَاعٌ', 'أتساع', 'جامد', '', 'ءتساع', 'تسع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7059, 'تِشْرِينُ', 'تشرين', 'جامد', '', 'تشرين', 'تشرن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'O', 'N', 'O', '', '": الشَّهْرُ العَاشِرُ مِنَ السَّنَةِ الشَّمْسِيَّةِ، عَدَدُ أَيَّامِهِ (31) يوماً، يَلِيهِ تِشْرِينُ الثَّانِي، أَيْ أُكْتُوبَر حَسَبَ الشُّهُورِ الغَرْبِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7060, 'تِشْرِينُ', 'تشرين', 'جامد', '', 'تشرين', 'تشرن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'O', 'N', 'O', '', '": الشَّهْرُ الحَادِي عَشَرَ مِنَ السَّنَةِ الشَّمْسِيَّةِ، عَدَدُ أَيَّامِهِ (30) يوماً، يَلِيهِ شَهْرُ كَانُونَ الأَوَّلِ، أَيْ نُوفَمْبِر حَسَبَ الشُّهُورِ الغَرْبِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7061, 'تَضَارِيسُ', 'تضاريس', 'جامد', '', 'تضاريس', 'تضرس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"ن. تَضْرِيسٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7062, 'أَتْعَابٌ', 'أتعاب', 'جامد', 'تعب', 'ءتعاب', 'تعب', '', '', '', 'مفرد', '', '', '', '"مفردتَعَب"', '', '', '', '', '', '', '', '', '". 1.""دَفَعَ لِلْمُحَامِي أَتْعَابَ عَمَلِهِ"" : أُجْرَتَهُ. 2.""ثِمَارُ أَتْعابه"" : ثِمارُ جُهْدِهِ. ""وَيَضَعُ بَيْنَ كَفَّيْهَا ثِمَارَ أتْعَابِهِ وَغَلَّةَ اجْتِهَادِهِ"". (جبران خ. جبران)."', '');
