INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7064, 'مَتَاعِبُ', 'متاعب', 'جامد', 'تعب', 'متاعب', 'متعب', '', '', '', 'مفرد', '', '', '', '"مفردمَتْعَب:مَتْعَبَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""مَتَاعِبُ الْحَيَاةِ"" : مَشَاقُّهَا، صِعَابُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7065, 'مَتْعَبٌ', 'متعب', 'جامد', 'تعب', 'متعب', 'متعب', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَتَاعِبُ"', '', 'R', '', '', '', '', '', '', '". 1.""يُعَانِي مِنَ الْمَتْعَبَةِ"": مِنَ التَّعَبِ، الْمَشَقَّةِ. 2.""أَرْهَقَتْهُ مَتَاعِبُ العَمَلِ"" : مَصَاعِبُهُ، مَشَقَّاتُهُ."', '');
