INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7076, 'تِفْلِقٌ', 'تفلق', 'جامد', '', 'تفلق', 'تفلق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"تِفْلِقٌ-تِفْلِقٌ (حو).: طَائِرٌ مِنْ فَصِيلَةِ التِّفْلِقِيَّاتِ مِنْ رُتْبَةِ طِوَالِ السَّاقِ. وَهُوَ مِنَ الطُّيُورِ الْمَائِيَّةِ، يَقْتَاتُ بِالحَشَرَاتِ وَبَعْضِ الْحُبُوبِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7077, 'تَفْلِيقِيَّاتٌ', 'تفليقيات', 'جامد', '', 'تفليقيات', 'تفلقت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"تَفْلِيقِيَّاتٌ-تَفْلِيقِيَّاتٌ (حو).: فَصِيلَةُ طُيُورٍ، مِنْ رُتْبَةِ طِوَالِ السَّاقِ، مِنْ أَشْهَرِ أَنْوَاعِهَا التِّفْلِقُ وَالْغُرُّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7078, 'تِقْنِيَّةٌ', 'تقنية', 'جامد', '', 'تقنية', 'تقنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"ج: ـات. ""تِقْنِيَّةٌ جَديدَةٌ"" : أُسْلُوبٌ مُخْتَصٌّ بِفَنٍّ أَوْ مِهْنَةٍ أَوْ حِرْفَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7079, 'تِكَّةٌ', 'تكة', 'جامد', '', 'تكة', 'تكة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"تِكَكٌ"', '', 'R', '', '', '', '', '', '', '"ج : تِكَكٌ. ""شَدَّ سِرْوالَهُ بِالتِّكَّةِ"" : أَيْ بِرِبَاطٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7080, 'تِكَكٌ', 'تكك', 'جامد', '', 'تكك', 'تك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7081, 'تَكْتِيكٌ', 'تكتيك', 'جامد', '', 'تكتيك', 'تكتك', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"""اِسْتَخْدَمَ الجَيْشُ تَكْتيكاً ناجِحاً لِدَحْرِ العَدُوِّ"": أُسْلوباً وَوَسائِلَ في التَّنْظِيمِ حَسَبَ خُطَّةٍ مَرْسومَةٍ تُؤَدِّي إلى النَّجاحِ والفَوْزِ. ""رَسَمَ تَكْتيكاً لإِنْجاحِ مَشْروعِهِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7082, 'تَكِيَّةٌ', 'تكية', 'جامد', '', 'تكية', 'تكة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"تَكايا"', '', '', '', '', '', '', '', '', '"ج: تَكايا. ""قَضَى آخِرَ حَياتِهِ في تَكِيَّةٍ"" : في مَلْجَإٍ لِلْعَجَزَةِ والْمُعْوِزينَ أوِ الْمُتَصَوِّفَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7083, 'تَكايا', 'تكايا', 'جامد', '', 'تكايا', 'تك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7084, 'تَليدٌ', 'تليد', 'جامد', 'تلد', 'تليد', 'تلد', '', '', '', 'مفرد', 'DnN', '', '', '"أَتْلادٌ"', '', 'R', '', '', '', '', '', '', '". 1.""تَرَكَ الأبُ مالاً تَليداً"" : إِرْثاً. 2.""يَتَمَتَّعُ بِمَجْدٍ تَليدٍ"" : بِمَجْدٍ قَدِيمٍ، أَصيلٍ، تالِدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7085, 'أَتْلادٌ', 'أتلاد', 'جامد', '', 'ءتلاد', 'تلد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7086, 'تِلِسكُوب', 'تلسكوب', 'جامد', '', 'تلسكوب', 'تلسكب', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"تِلِسكُوب-تِلِسكُوب (فك). ""يَرْصُدُ النُّجومَ بِواسِطَةِ تِلِسْكوب"": آلَةٌ يُطْلَقُ عَلَيْها أَيْضاً المِرْقَبُ لِرُؤْيَةِ الأجْسامِ البَعيدَةِ فَهُوَ يَرْقُبُها وَيُقَرِّبُها."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7087, 'تَلْعَةٌ', 'تلعة', 'جامد', 'تلع', 'تلعة', 'تلعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":تِلاعٌ:تِلَعٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِعْتَلَى التَّلْعَةَ"" : ما ارْتَفَعَ مِنَ الأَرْضِ. 2.""يَنْصَبُّ الماءُ مِنَ التَّلْعَةِ شَلاَّلاً"" : مَسيلُ الماءِ مِنْ أَعْلَى إلى أَسْفَلَ. 3.""تَلْعَةُ الوادِي"" : ما اتَّسَعَ مِنْ فَمِهِ. 4.""ما أَخافُ إِلاَّ مِنْ سَيْلِ تَلْعَتِي"" : مِنْ بَنِي عَمِّي وَذَوِي قَرابَتِي. 5.""هُوَ لا يُوثَقُ بِسَيْلِ تَلْعَتِهِ"" : لا يوثَقُ بِما يَقولُ وما يَجيءُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7088, 'تِلاعٌ', 'تلاع', 'جامد', '', 'تلاع', 'تلع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7089, 'تِلَعٌ', 'تلع', 'جامد', '', 'تلع', 'تلع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7090, 'تِلِغْرافٌ', 'تلغراف', 'جامد', '', 'تلغراف', 'تلغرف', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"1.: جِهازُ إِرْسالِ البَرْقِيَّاتِ. 2.""تَوَصَّلَ بِتِلِغْرافٍ"" : الرِّسالَةُ القَصيرَةُ الْمَبْعوثَةُ بَرْقِيّاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7091, 'مَتْلَفَةٌ', 'متلفة', 'جامد', 'تلف', 'متلفة', 'متلفة', '', '', '', 'مفرد', 'DnN', '', '', '"مَتَالِفُ"', '', 'R', '', '', '', '', '', '', '". 1.""ضَاعَ فِي الْمَتْلَفَةِ"" : الْمَغَارَةُ الْمُقْفِرَةُ. 2.""وَضَعَ أَغْرَاضَهُ القَدِيمَةَ فِي الْمَتْلَفَةِ"" : مَحَلُّ التَّلَفِ وَالإِتْلاَفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7092, 'مَتَالِفُ', 'متالف', 'جامد', '', 'متالف', 'متلف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7093, 'تِلْفازٌ', 'تلفاز', 'جامد', '', 'تلفاز', 'تلفز', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '": جِهازٌ إِلِكْتِرونِيّ. يَتَلَقَّى صُوَرَ بَرامِجَ وَأَفْلامٍ بِواسِطَةِ مَوْجاتٍ هِيرْتِزِيَّةٍ أَوْ كَهْرَبائِيَّةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7094, 'تَلَّةٌ', 'تلة', 'جامد', 'تلل', 'تلة', 'تلة', '', '', '', 'مفرد', 'DnN', '', '', '"تِلالٌ(واحِدَةُالتَّلِّ)"', '', 'R', '', '', '', '', '', '', '"تَلَّةٌ-تَلَّةٌ (واحِدَةُ التَّلِّ). ج: تِلالٌ. [ت ل ل]. 1.: الرَّابِيَةُ. 2.: الضَّجْعَةُ. 3.: الكَسَلُ. 4.: غِلافُ الطَّلْعِ يُجْعَلُ إِناءً لِلشُّرْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7095, 'تِلالٌ', 'تلال', 'جامد', '', 'تلال', 'تلل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7096, 'تِلَّةٌ', 'تلة', 'جامد', 'تلل', 'تلة', 'تلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"تِلَّةٌ-تِلَّةٌ [ت ل ل]. 1.""تَلَّهُ بِتِلَّةِ سُوءٍ"": رَمَاهُ بِأَمْرٍ قَبِيحٍ. 2.""وَجَدَهُ فِي تِلَّةِ سُوءٍ"": فِي حَالَةِ سُوءٍ. 3.""مَا زَالَ فِي تِلَّةٍ"": فِي كَسَلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7097, 'تِلامٌ', 'تلام', 'جامد', 'تلم', 'تلام', 'تلم', '', '', '', 'مفرد', 'DnN', '', '', '"تُلُمٌ"', '', 'R', '', '', '', '', '', '', '". ""تَرَكَ المِحْراثُ تِلاماً"" : الشَّقَّ الَّذي تَتْرُكُهُ سِكَّةُ المِحْراثِ في الأرْضِ، أُخْدُودٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7098, 'تُلُمٌ', 'تلم', 'جامد', '', 'تلم', 'تلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7099, 'تَلَمٌ', 'تلم', 'جامد', 'تلم', 'تلم', 'تلم', '', '', '', 'مفرد', 'DnN', '', '', '"أَتْلامٌ"', '', 'R', '', '', '', '', '', '', '". ""تَرَكَتْ سِكَّةُ الفَلاَّحِ تَلَماً في الأرْضِ"" : الشَّقُّ الَّذِي تَتْرُكُهُ سِكَّةُ المِحْراثِ فِي الأرْضِ، أُخْدودٌ، تِلاَمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7100, 'أَتْلامٌ', 'أتلام', 'جامد', '', 'ءتلام', 'تلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7101, 'تِلْميذٌ', 'تلميذ', 'جامد', '', 'تلميذ', 'تلمذ', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '":تَلاَمِيذُ:تَلاَمِذَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: ـاتٌ، تَلاميذُ، تَلامِذَةٌ. ""يَتَعَلَّمُ التِّلْميذُ مِنْ مُعَلِّمِهِ"" : مَنْ يَأْخُذُ عِلْماً أَوْ مِهْنَةً، طالِبُ عِلْمٍ. ""هَؤُلاءِ مِنْ تَلامِذَتِهِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7102, 'تَلاَمِيذُ', 'تلاميذ', 'جامد', '', 'تلاميذ', 'تلمذ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
