INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7109, 'تِمْساحٌ', 'تمساح', 'جامد', '', 'تمساح', 'تمسح', '', '', '', 'جمع تكسير', 'DnN', '', '', '"تَماسيحُ"', '', 'R', '', '', '', '', '', '', '"ج: تَماسيحُ. (حو).: حَيَوانٌ مِنْ رُتْبَةِ التَّماسيحِ، مِنْ صِنْفِ الزَّواحِفِ، طَويلُ الخَطْمِ وَضَخْمُ الجِسْمِ وَطويلُ الذَّنَبِ، على جِلْدِهِ دَوائِرُ مُتَّصِلَةٌ، قَصيرُ القَوائِمِ، وَهُوَ بَرْمائِيٌّ زَحَّافٌ، يَكونُ في أَنْهارِ البِلادِ الحارَّةِ، وَهُوَ أَنْواعٌ كالتِّمْساحِ الأمريكِيِّ مَثَلاً. ""دُموعُ التَّماسِيحِ"" : كِنايَةٌ عَنْ إِظْهارِ الضَّعْفِ الكاذِبِ لِجَلْبِ الشَّفَقَةِ ابْتِغاءَ الخَديعَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7110, 'تَماسيحُ', 'تماسيح', 'جامد', '', 'تماسيح', 'تمسح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7111, 'تَتِمَّةٌ', 'تتمة', 'جامد', 'تمم', 'تتمة', 'تتمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"تَتِمَّةٌ-تَتِمَّةٌ [ت م م]. ""أَنَا فِي انْتِظَارِ تَتِمَّةِ الْمَبْلَغِ"" : تَكْمِلَتُهُ، بَقِيَّتُهُ. ""تَتِمَّةُ الْمَقَالِ فِي الصَّفْحَةِ العَاشِرَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7112, 'تَمِيمَةٌ', 'تميمة', 'جامد', 'تمم', 'تميمة', 'تممة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَمَائِمُ"', '', '', '', '', '', '', '', '', '". ""وَضَعَتِ الأُمُّ تَمِيمَةً حَوْلَ عُنُقِ ابْنِهَا لِوِقَايَتِهِ مِنَ العَيْنِ"" : الحِرْزُ لِدَفْعِ الأرْوَاحِ الشِّرِّيرَةِ عَنْهُ."', '');
