INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7131, 'تُوهٌ', 'توه', 'جامد', '', 'توه', 'ته', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَتْواهٌ:أَتاوِيهُ"', '', 'R', '', '', '', '', '', '', '"ج: أَتْواهٌ، أَتاوِيهُ. 1.""نَجا مِنْ تُوهٍ مُحَقَّقٍ"" :الهَلاكُ الْمُحَق"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7132, 'أَتْواهٌ', 'أتواه', 'جامد', '', 'ءتواه', 'ته', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7133, 'أَتاوِيهُ', 'أتاويه', 'جامد', '', 'ءتاويه', 'ته', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7134, 'تَيَّارٌ', 'تيار', 'جامد', 'تير', 'تيار', 'تر', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""تَيَّارُ البَحْرِ"" :مَوْجُ البَحْرِ الهائِجِ. ""اِنْدَفَعَ تَيَّارُ النَّهْرِ يَجُرُّ وَراءهُ كُلَّ ما وَجَدَهُ أَمامَهُ"". 2."" التَّيَّارُ الكَهْرَبائِيُّ"" (فز) : اِنْتِقالُ الكَهْرَباءِ بِواسِطَةِ أَسْلاكٍ كَهْرَبائِيَّةٍ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7135, 'تَيسٌ', 'تيس', 'جامد', '', 'تيس', 'تس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"تُيوسٌ:أَتْياسٌ"', '', 'R', '', '', '', '', '', '', '"ج: تُيوسٌ، أَتْياسٌ. 1.: ذَكَرُ الْمَعِزِ والوُعولِ والظِّباءِ إِذا أَتَتْ عَلَيْهِ السَّنَةُ. 2.""تَيْسٌ في سَفينَةٍ"" : الغَبِيُّ الجاهِلُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7136, 'تُيوسٌ', 'تيوس', 'جامد', '', 'تيوس', 'تس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7137, 'أَتْياسٌ', 'أتياس', 'جامد', '', 'ءتياس', 'تس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7138, 'تَيفوسٌ', 'تيفوس', 'جامد', '', 'تيفوس', 'تفس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": مَرَضٌ تَظْهَرُ عَوارِضُهُ بارْتِفاعِ الحَرارَةِ وَظُهورِ بُقَعٍ عَلَى الجِلْدِ، وَيُصابُ صاحِبُهُ بِالإِغْماءِ مِنْ حينٍ لآخَرَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7139, 'تِيفُوئيد', 'تيفوئيد', 'جامد', '', 'تيفوءيد', 'تفد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": مَرَضٌ مُعْدٍ يَنْتِجُ عَنْهُ الْتِهابٌ في الأمْعاءِ الدَّقِيقَةِ وَانْتِفَاخُ الطِّحَالِ وَالعُقَدِ الأَمْعِيَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7140, 'تيلٌ', 'تيل', 'جامد', '', 'تيل', 'تل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"تيلٌ-تيلٌ (نب).: نَباتٌ مِنْ فَصيلَةِ الخَبُّازِيَّاتِ يُزْرَعُ لأَلْيافِهِ، يُسْتَخْدَمُ في صِناعَةِ الأكْياسِ والحِبالِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7141, 'تَيْمَاءُ', 'تيماء', 'جامد', 'تيم', 'تيماء', 'تم', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"تَيْمَاءُ-تَيْمَاءُ [ت ي م]. ""تَيْمَاءُ البِلاَدِ"" : الأَرْضُ الوَاسِعَةُ الْمُضِلَّةُ الْمُهْلِكَةُ. ""تَاهَ فِي تَيْمَاءَ وَسَطَ قِفَارٍ مُهْلِكَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7142, 'تينٌ', 'تين', 'جامد', '', 'تين', 'تن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"تينٌ-تينٌ (نب). 1.: شَجَرٌ مِنْ فَصيلَةِ الخبُّازِيَّاتِ أو التُّوتِيَّاتِ، ثِمارُهُ تُؤْكَلُ، وَهُوَ أَنْواعٌ كَثيرَةٌ. ""أما تَرَى التِّينَ في الغُصونِ بَدا مُمَزَّقَ الجِلْدِ مائِلَ العُنُقِ"". 2.""التِّينُ الشَّوْكِيُّ"" : يُعْرَفُ "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7143, 'تينَةٌ', 'تينة', 'جامد', '', 'تينة', 'تنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تينَةٌ-تينَةٌ (نب).: شَجَرَةُ التِّينِ أوْ ثَمَرَتُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7144, 'تَيْهاءُ', 'تيهاء', 'جامد', 'تيه', 'تيهاء', 'ته', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"تَيْهاءُ-تَيْهاءُ [ت ي هـ]. ""أَرْضٌ تَيْهاءُ"" : الأرْضُ الواسِعَةُ التِي يَضيعُ فيها الإِنْسانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7145, 'مَتَاهَةٌ', 'متاهة', 'جامد', 'تيه', 'متاهة', 'متهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""ضَاعَ فيِ مَتَاهَاتٍ لاَ حَدَّ لَهَا"" : مَوَاضِعُ التِّيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7146, 'ثُؤْلُولٌ', 'ثؤلول', 'جامد', 'ثأل', 'ثءلول', 'ثلل', '', '', '', 'مفرد', 'DnN', '', '', '"ثَآليلُ"', '', 'R', '', '', '', '', '', '', '"(طب). ""اِنْتَشَرَتْ فِي جِلْدِهِ ثَآلِيلُ"" : بَثْرٌ صَلْبٌ مُسْتَدِيرٌ يَخْرُجُ فِي الجِلْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7147, 'ثَآليلُ', 'ثآليل', 'جامد', '', 'ثءءليل', 'ثآلل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7148, 'ثِبَانٌ', 'ثبان', 'جامد', '', 'ثبان', 'ثبن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"ثُبُنٌ"', '', 'R', '', '', '', '', '', '', '"ج: ثُبُنٌ : مَا يُثْنَى مِنْ طَرَفِ الثَّوْبِ فَيُوضَعُ فِيهِ شَيْءٌ يُحْمَلُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7149, 'ثُبُنٌ', 'ثبن', 'جامد', '', 'ثبن', 'ثبن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7150, 'ثَبْتٌ', 'ثبت', 'جامد', 'ثبت', 'ثبت', 'ثبت', '', '', '', 'مفرد', 'DnN', '', '', '"أثْبَاتٌ"', '', 'R', '', '', '', '', '', '', '". 1.""رَجُلٌ ثَبْتٌ"" : شُجَاعٌ، حَازِمٌ، عَاقِلٌ. 2.""هُوَ ثَبْتُ الخُصُومةِ"" : لاَ يَزِلُّ لِسَانُهُ عِنْدَ الخُصُومَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7151, 'أثْبَاتٌ', 'أثبات', 'جامد', '', 'ءثبات', 'ثبت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7152, 'ثِدَامٌ', 'ثدام', 'جامد', 'ثدم', 'ثدام', 'ثدم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ثِدَامٌ-ثِدَامٌ [ث د م].: مِصْفَاةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7153, 'ثَدْيَاءُ', 'ثدياء', 'جامد', 'ثدي', 'ثدياء', 'ثد', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"ثَدْيَاءُ-ثَدْيَاءُ [ث د ي]. ""اِمْرَأةٌ ثَدْيَاءُ"" : عَظِيمَةُ الثَّدْيَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7154, 'ثَدْيٌ', 'ثدي', 'جامد', '', 'ثدي', 'ثد', '', '', '', 'جمع تكسير', 'DnN', '', '', '"ثُدِيٌّ:أثْدٍ(يُذَكَّرُوَيُؤَ', '', 'Rw', '', '', '', '', '', '', '"ج: ثُدِيٌّ، أثْدٍ. (يُذَكَّرُ وَيُؤَنَّثُ). 1.""ثَدْيُ الْمَرْأةِ"" : غُدَّةٌ فِي صَدْرِهَا. فِي وَسَطِهَا حَلَمَةٌ بِهَا ثُقَبٌ دَقِيقَةٌ يَمْتَصُّ مِنْهَا الرَّضِيعُ اللَّبَنَ. 2.""ثَدْيُ الحَيَوَانِ"" : ضَرْعُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7155, 'ثُدِيٌّ', 'ثدي', 'جامد', '', 'ثدي', 'ثد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7156, 'أثْدِي', 'أثدي', 'جامد', '', 'ءثدي', 'ثد', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7157, 'ثَدْيِيَّاتٌ', 'ثدييات', 'جامد', '', 'ثدييات', 'ثدت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"جمع ثَدْيِيٌّ. : فَصِيلَةُ الَّلبُونَاتِ الفَقَاريَّات، تَلِدُ وَتُرْضِعُ وَيَكْسُوهَا شَعَرٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7158, 'ثَرِيدٌ', 'ثريد', 'جامد', 'ثرد', 'ثريد', 'ثرد', '', '', '', 'مفرد', 'DnN', '', '', '"ثَرائِدُ"', '', 'R', '', '', '', '', '', '', '". ""ثَرِيدٌ لَذيذٌ نَالَ إعْجَابَ الضُّيُوفِ"" : طَعَامٌ مِنْ رَغِيفٍ يُفَتَّتُ وَيُبَلَّلُ بِالْمَرَقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7159, 'ثَرائِدُ', 'ثرائد', 'جامد', '', 'ثراءد', 'ثرد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7160, 'مَثْرودَةٌ', 'مثرودة', 'جامد', 'ثرد', 'مثرودة', 'مثردة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَثْرودَةٌ-مَثْرودَةٌ [ث ر د]. ""أَرْضٌ مَثْرودَةٌ"" : أصابَها مَطَرٌ خَفيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7161, 'ثُرَيَّا', 'ثريا', 'جامد', 'ثرو', 'ثريا', 'ثر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ثُرَيَّا-ثُرَيَّا [ث ر و]. 1. ""الثُّرَيَّا"" (فك) : مَجْمُوعَةٌ مِنَ الكَوَاكِبِ فِي عُنُقِ الثَّوْرِ. ""لَوْ كَانَ زَرَادُشْتُ أرَاهُمُ الثُّرَيَّا تَمْشِي عَلَى الأرْضِ مَا صَدَّقُوهُ"".(التوحيدي). 2.""عُلِّقَتِ الثُّرَيَّا فِي بَهْوِ البَيْتِ"" : مَنَارَةٌ مُتَعدِّدَةُ الْمَصَابِيحِ يُنَارُ بِهَا فِي البُيُوتِ الكَبِيرَةِ وَالقُصُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7162, 'ثُعْبَانٌ', 'ثعبان', 'جامد', '', 'ثعبان', 'ثعبن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"ثَعَابِينُ(يُطْلَقُعَلَىالذَّ', '', 'Rp', '', '', '', '', '', '', '"ج: ثَعَابِينُ. (حو).: (يُطْلَقُ عَلَى الذَّكَرِ وَالأُنْثَى). حَيَوانٌ مِنَ الزَّوَاحِفِ مِنْ فَصِيلَةِ الثُّعْبَانِيَّاتِ مُمْتَّدُ الجِسْمِ أمْلَسُ،وَيُطْلَقُ علَى الحَيَّةِ العَظِيمَةِ الضَّخْمَةِ.الأعراف آية 107 فَأَلْقَى عَصَاهُ فَإِذَا هِيَ ثُعْبَانٌ مُبِينٌ .(قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7163, 'ثَعَابِينُ', 'ثعابين', 'جامد', '', 'ثعابين', 'ثعبن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7164, 'ثُعْبَانِيَّاتٌ', 'ثعبانيات', 'جامد', '', 'ثعبانيات', 'ثعبنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةُ الحَيَّاتِ العَظِيمَةِ وَالأحْنَاشِ وَالخَفَافِيشِ مِنْهَا مَا هُوَ سَامٌّ وَغَيْرُ سَامٍّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7165, 'ثَعْلَبٌ', 'ثعلب', 'جامد', '', 'ثعلب', 'ثعلب', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"ثَعَالِبُ"', '', 'R', '', '', '', '', '', '', '"ج: ثَعَالِبُ. 1.""حَيَوَانٌ مِنْ فَصِيلَةِ الكَلْبِيَّاتِ مِنْ رُتْبَةِ الضَّوَارِي، لَهُ خَطْمٌ قَصِيرٌ وَذَنَبٌ طَوِيـلٌ، يَتَسَاقَـطُ شَعْرُهُ مَرَّةً فِي كُلِّ سَنَةٍ، يُعْرَفُ فِي الحِكَايَاتِ وَالقِصَصِ بِخِدَاعِهِ وتَحَايُلِهِ. 2.""دَاءُ الثَّعْلَبِ"" : مَرَضُ تَسَاقُطِ الشَّعْرِ. ""يَتَحَلَّى بِرَوَغَانِ الثَّعْلَبِ"" (التوحيدي)""كُنْ حَذِراً كَالثَّعْلَبِ (وَكُنْ) حَرِيصاً كالذِّئْبِ"".(عبد الرحمان منيف)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7166, 'ثَعَالِبُ', 'ثعالب', 'جامد', '', 'ثعالب', 'ثعلب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7167, 'ثُغْرَةٌ', 'ثغرة', 'جامد', 'ثغر', 'ثغرة', 'ثغرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":ثُغَرٌ"', '', 'R', '', '', '', '', '', '', '". 1.""ثُغْرَةُ الوَادِي"" : فُرْجَتُهُ. 2.""اِسْتَقَرَّ فِي الثُّغْرَةِ"" : فِي أعْلَى البِنَاءِ. 3.""سَدَّ ثُغْرَةً فِي الجَبْهَةِ"": الفَتْحَةُ الَّتِي يُمْكِنُ أنْ تُشَكِّلَ نُقْطَةَ ضَعْفٍ. ""وَاكْتَفَى بِالثُّغْرَةِ الَّتِي فَتَحَهَا"".(ن. محفوظ). 4.""ثُغْرَةُ النَّحْرِ"": نُقْرَةٌ بَيْنَ التَّرْقُوَتَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7168, 'ثُغَرٌ', 'ثغر', 'جامد', '', 'ثغر', 'ثغر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7169, 'ثَغْرٌ', 'ثغر', 'جامد', '', 'ثغر', 'ثغر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"ثُغُورٌ"', '', 'R', '', '', '', '', '', '', '"ج: ثُغُورٌ. 1.""اِفْتَرَّ ثَغْرُهُ عَنِ ابْتِسَامَةٍ خَفِيفَةٍ"" : فَمُهُ، مُقَدَّمُ أَسْنَانِهِ. 2.""اِسْتَقَرَّ الجُنْدُ فِي ثَغْرِ الجَبَلِ"" : فِي فُرْجَةِ الجَبَلِ. ""ثَغْرُ الوَادِي"". 3. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7170, 'ثُغُورٌ', 'ثغور', 'جامد', '', 'ثغور', 'ثغر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7171, 'ثُغَاءٌ', 'ثغاء', 'جامد', 'ثغو', 'ثغاء', 'ثغ', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', 'N', 'O', 'O', 'O', '', '"ثُغَاءٌ-ثُغَاءٌ [ث غ و]."" ثُغَاءُ الشَّاةِ"" : صَوْتُهَا، صَوْتُ الغَنَمِ. ""تَدْرُجُ أغْنَامُهُمْ وَأبْقَارُهُمْ مُسْرِعَةً إلَى زَرَائِبِهَا، تُرْسِلُ فِي الفَضَاءِ ثُغَاءً وَخُوَاراً"". (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7172, 'ثُفْلٌ', 'ثفل', 'جامد', '', 'ثفل', 'ثفل', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"1. ""ثُفْلُ القَهْوَةِ"" : مَا يَتَبَقَّى مِنْهَا بَعْدَ تَصْفِيَتِهَا. 2."" اِسْتَقَرَّ الثُّفْلُ فِي الكَأْسِ"" : مَا اسْتَقَرَّ وَرَسَبَ فِي أسْفَلِهِ مِنْ كُدْرَةٍ وَحُثَالَةٍ، البَقِيَّةُ مِنَ الشَّيْءِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7173, 'ثِقَابٌ', 'ثقاب', 'جامد', 'ثقب', 'ثقاب', 'ثقب', '', '', '', 'مفرد', 'DnN', '', '', '"ثُقُبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أشْعَلَ النَّارَ بِالثِّقَابِ"": دَقَائِقُ العِيدَانِ تُشْعَلُ بِهَا النَّارُ. 2.""أشْعَلَ سِيجَارَتَهُ بِعُودِ ثِقَابٍ"": عُودٌ دَقِيقٌ فِي أحَدِ طَرَفَيْهِ مَادَّةٌ كِبْرِيتِيَّةٌ تَشْتَعِلُ بَعْدَ حَكِّهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7174, 'ثُقُبٌ', 'ثقب', 'جامد', '', 'ثقب', 'ثقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
