INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7178, 'أثْقَالٌ', 'أثقال', 'جامد', 'ثقل', 'ءثقال', 'ثقل', '', '', '', 'مفرد', '', '', '', '"مفردثِقْل"', '', 'R', '', '', '', '', '', '', '". 1.""يَحْمِلُ ""أثْقَالاً"" : مَوَادَّ ثَقِيلَةً. 2.""أَثْقالُ الأرْضِ"" : ما في جَوْفِها من دَفَائِنَ وَأَمْواتٍ وَكُنوزٍ.الزلزلة آية 2 وأخْرجَتِ الأَرْضُ أَثْقَالهَا (قرآن). 3.""يَهْوَى رِيَاضَةَ رَفْعِ الأَثقَالِ"": فَنٌّ مِنَ الفُنُونِ الرِّيَاضِيَّةِ، مِنْ ألْعَابِ القُوَى: حَمْلُ الأَوْزَانِ الثَّقِيلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7179, 'ثَقَل', 'ثقل', 'جامد', 'ثقل', 'ثقل', 'ثقل', '', '', '', 'مفرد', 'DnN', '', '', '"مثنىثَقَلاَنِ-ثَقَلاَنِ"', '', 'R', '', 'N', 'O', 'N', 'N', '', '"ثَقَلاَنِ-ثَقَلاَنِ [ث ق ل].الرحمن آية 31 سنَفْرُغُ لَكُمُ أيُّهَا الثَّقَلاَنِ . (قرآن) : الإنْسُ وَالجِنُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7180, 'ثِقْلٌ', 'ثقل', 'جامد', 'ثقل', 'ثقل', 'ثقل', '', '', '', 'مفرد', 'DnN', '', '', '"أثْقَالٌ"', '', 'R', '', '', '', '', '', '', '". 1.""يحْمِلُ ثِقْلاً أرْهَقَ كَاهِلَهُ"": يَحْمِلُ الثَّقِيلَ. ""الجَمَلُ ذُو سِنَامٍ مُقَبَّبٍ يَكُونُ لِكَثْرَةِ الحِمْلِ وَاحْتِمَالِ الثِّقْلِ"".(أ. التوحيدي). 2.""أَعْطِهِ ثِقْلَهُ"" : وَزْنَهُ. 3.""يُمَارِسُ رِيَاضَةَ رَفْعِ الأثْقَالِ"" : أيْ حَمْلِ الأوْزَانِ الثَّقِيلَةِ، وَهِيَ رِيَاضَةٌ مِنْ ألْعَابِ القُوَى. 4. الزلزل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7181, 'أثْقَالٌ', 'أثقال', 'جامد', '', 'ءثقال', 'ثقل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7182, 'ثُكْنَةٌ', 'ثكنة', 'جامد', 'ثكن', 'ثكنة', 'ثكنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":ثُكَنٌ"', '', 'R', '', '', '', '', '', '', '". ""اِسْتَقَرَّ الجُنْدُ فِي الثُّكْنَةِ"" : مَرْكَزُ الجُنْدِ يَعِيشُونَ فِيهِ."', '');
