INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7188, 'ثَالُوثٌ', 'ثالوث', 'جامد', 'ثلث', 'ثالوث', 'ثلث', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ثَالُوثٌ-ثَالُوثٌ [ث ل ث].: مَا رُكِّبَ وَأُلِّفَ مِنْ ثَلاَثَةٍ. 1.""الثَّالُوثُ الحَاكِمُ"" : إذَا كَانَ نِظَامُ الحُكْمِ يَتَكَوَّنُ مِنْ ثَلاَثَةِ أفْرَادٍ. 2.""الثَّالُوثُ القُدُسُ"" : هُوَ عِنْدَ الْمَسِيحِيِّينَ اتِّحَادُ الأقَانِيمِ الثَّلاَثَةِ (الأبُ وَالاِبْنُ وَالرُّوحُ القُدُسُ). فِي الذَّاتِ الإلَهِيَّةِ. 3.""زَهْرَةُ الثَّالُوثِ"" (نب): مِنَ البَنَفْسَجِيَّاتِ، تُعْتَبَرُ فِي أُورُوبَّا رَمْزاً لِلذِّكْرَى، وَتُسَمَّى أيْضاً بَنَفْسَجَ الثَّالُوثِ. وَهُوَ صَغِيرُ الزَّهْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7189, 'ثُلاَثَاءُ', 'ثلاثاء', 'جامد', 'ثلث', 'ثلاثاء', 'ثلث', '', '', '', 'مفرد', '', '', '', '"ثُلاَثَاءاتٌ:أثَالِيثُ"', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '". ""يَوْمُ الثُّلاَثَاءِ"": اليَوْمُ الثَّالِثُ مِنَ الأُسْبُوعِ. وَقَدْ تُكْتَبُ ثُلَثَاءَ دُونَ ألِفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7190, 'ثُلاَثَاءاتٌ', 'ثلاثاءات', 'جامد', '', 'ثلاثاءات', 'ثلثت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
