INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7192, 'ثَلاثَةٌ', 'ثلاثة', 'جامد', 'ثلث', 'ثلاثة', 'ثلثة', '', '', '', 'مفرد', '', '', '', '"مُفْرَدٌمَعْدودُهُجَمْعُمُذَك', '', '', '', 'N', 'O', 'N', 'O', '', '"ثَلاثَةٌ-ثَلاثَةٌ [ث ل ث]. 1.: مُفْرَدٌ مَعْدودُهُ جَمْعُ مُذَكَّرٍ : ""حَضَرَ ثَلاثَةُ رِجالٍ""، ""رَفْرَفَ ثَلاثَةٌ مِنَ الطَّيْرِ""، ""مَرَرْتُ بِثَلاثَةٍ مِنْ أَعْضاءِ الجَمْعِيَّةِ"". 2.""ثَلاثَةَ عَشَرَ رَجُلاً"" : عَدَدٌ مُرَكَّبٌ مَعْدودُهُ مُفْرَدٌ مُذَكَّرٌ. ""أَخَذْتُ ثَلاثَةَ عَشَرَ دِرْهَماً""‎ ""عِنْدِي ثَلاثَةَ عَشَرَ دِرْهَماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7193, 'ثَلاثُ', 'ثلاث', 'جامد', 'ثلث', 'ثلاث', 'ثلث', '', '', '', 'مفرد', '', '', '', '"(عدَدٌمُفْرَدٌمَعْدُودُهُجَمْ', 'ممنوع من الصرف', 'Rp', '', 'N', 'N', 'N', 'N', '', '"ثُلاثَ-ثُلاثَ [ث ل ث] (لِلمُذَكَّرِ وَالْمُؤَنَّتِ). ""جَاءوا ثُلاَثَ"": ثَلاَثَةً ثَلاَثَةً، وَهُوَ غَيْرُ مُنْصَرِفٍ. فاطر آية 1 جَاعِلِ الْمَلاَئِكَةِ رُسُلاً أُولِي أَجْنِحَةٍ مَثْنَى وَثُلاثَ وَرُبَاعَ .(قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7194, 'ثُلْثٌ', 'ثلث', 'جامد', 'ثلث', 'ثلث', 'ثلث', '', '', '', 'مفرد', 'DnN', '', '', '"أَثْلاثٌ"', '', 'R', '', '', '', '', '', '', '". ""كانَ مِنْ نَصِيبِهِ ثُلْثُ الإِرْثِ"" : جُزْءٌ مِنْ ثَلاثَةِ أَجْزاءِ الإِرْثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7195, 'أَثْلاثٌ', 'أثلاث', 'جامد', '', 'ءثلاث', 'ثلث', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7196, 'مَثْلَثٌ', 'مثلث', 'جامد', 'ثلث', 'مثلث', 'مثلث', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَثْلَثٌ-مَثْلَثٌ [ث ل ث]. ""جَاءوا مَثْلَثَ"" : أَيْ ثَلاَثَةً ثَلاَثَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7197, 'ثُلْثِيٌّ', 'ثلثي', 'جامد', '', 'ثلثي', 'ثلث', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '"""خَطٌّ ثُلْثِيٌّ"" : مِنْ أَنْواعِ الخُطوطِ العَرَبِيَّةِ الْمُتَمَيِّزَةِ بِكَثافَتِها. ن خط."', ':لا جذر:لا مفرد');
