INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7205, 'تِلْمٌ', 'تلم', 'جامد', 'ثلم', 'تلم', 'تلم', '', '', '', 'مفرد', 'DnN', '', '', '"تِلامٌ"', '', 'R', '', '', '', '', '', '', '"تِلْمٌ- ج: تِلامٌ. [ث ل م]. 1.: الحَرَّاثُ. 2.: أكّارٌ. 3.: الصَّائِغُ. 4.: تِلْميذُ الصَّائِغِ. 5.: مِنْفاخُ الصَّائِغِ الطَّويلُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7206, 'تِلامٌ', 'تلام', 'جامد', '', 'تلام', 'تلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
