INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7208, 'ثَمانِي', 'ثماني', 'جامد', '', 'ثماني', 'ثمن', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '"اِسْمٌ مَحْذُوفُ الياءِ إِذا لَمْ يَكُنْ مُعَرَّفاً بِأَلْ وَلا مُضافاً. 1.""وَصَلَ مِنَ الطَّالِباتِ ثَمانٍ""، ""مَرَرْتُ بِثَمانٍ مِنَ الطَّالِباتِ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7209, 'ثُمانَ', 'ثمان', 'جامد', '', 'ثمان', 'ثمن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'N', '', '"""أَتَوْا ثُمانَ"" : أَتَوْا ثَمانِيَةً ثَمانِيَةً. وَهُوَ اسْمٌ مَمْنوعٌ مِنَ الصَّرْفِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7210, 'ثَمْرَاءُ', 'ثمراء', 'جامد', 'ثمر', 'ثمراء', 'ثمر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"ثَمْرَاءُ-ثَمْرَاءُ [ث م ر]. 1.""شَجَرَةٌ ثَمْرَاءُ"" : ظَهَرَ ثَمَرُهَا. 2.""أَرْضٌ ثَمْرَاءُ"" : كَثِيرَةُ الثَّمَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7211, 'ثَمَرَةٌ', 'ثمرة', 'جامد', 'ثمر', 'ثمرة', 'ثمرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""ثَمَرَةُ الزَّهْرَةِ"" : بُذُورُها الْمُتَكَوِّنَةُ في مَبِيضِها. 2.""هُوَ مِنْ ثَمَرَتِهِ"" : مِنْ نَسْلِهِ، مِنْ أَوْلادِهِ. 3.""ثَمَرَةُ القَلْبِ"" : الْمَحَبَّةُ، الوَلَدُ. ""تَزَوَّجُوا والْتَمِسُوا البَنِينَ فَإِنَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7212, 'ثَمَرٌ', 'ثمر', 'جامد', 'ثمر', 'ثمر', 'ثمر', '', '', '', 'مفرد', 'DnN', '', '', '"ثِمارٌجأَثْمارٌ"', '', 'R', '', '', '', '', '', '', '". 1.""ثَمَرُ الشَّجَرَةِ"": فاكِهَتُها. ""إِنَّ اللَّهَ إِذا أَرادَ ثَمَراً غَرَسَ لَهُ غَرْساً"". (التوحيدي). 2.""هَذَا مِنْ ثَمَرِ "', '');
