INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7225, 'ثَانِيَةٌ', 'ثانية', 'جامد', 'ثني', 'ثانية', 'ثنة', '', '', '', 'مفرد', 'DnN', '', '', '"ثَوَانٍ"', '', '', '', '', '', '', '', '', '". ""قَطَعَ الْمَسَافَةَ فِي ثلاثِ دَقَائِقَ وَثَانِيَةٍ وَاحِدَةٍ"" : عُشْرُ سُدْسِ الدَّقِيقَةِ، وَالدَّقِيقَةُ تَتَأَلَّفُ مِنْ سِتِّينَ جُزْءاً، والجُزْءُ هُنَا هُوَ الثَّانِيَةُ."', '');
