INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7229, 'ثَنِيَّةٌ', 'ثنية', 'جامد', 'ثني', 'ثنية', 'ثنة', '', '', '', 'مفرد', 'DnN', '', '', '"ثَنايا"', '', '', '', '', '', '', '', '', '". 1.""اِبْتَسَمَ عَنْ ثَنِيَّتِهِ"" : الأسْنانُ الأرْبَعَةُ في مُقَدَّمِ الفَمِ، ثِنْتَانِ مِنْ فَوْقُ وثِنْتَانِ مِنْ أَسْفَلَ. 2.""ثَنِيَّةُ الجَبَلِ"" : العَقَبَةُ، الْمُنْعَطَفُ، الطَّريقُ العالِي الْمُرْتَفِعُ. ""النَّسْرُ يَنامُ في شَظايا الجَبَلِ وَثَناياهُ"".(أ. التوحيدي). 3.""أَنا ابْنُ جَلاَ وَطَلاَّعُ الثَّنَايَا"".(الحجاج الثقفي): أَن"', '');
