INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7334, 'جَرَامِيزُ', 'جراميز', 'جامد', '', 'جراميز', 'جرمز', '', '', '', 'جمع تكسير', 'DnN', '', '', '"جَرَامِيزُ"', 'ممنوع من الصرف', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: جَرَامِيزُ. 1.""لَمْ نَكُنْ نَسْمَعُ فِي أَعْلَى الجَبَلِ إِلاَّ أَصْوَاتَ الجَرَامِيزِ"" : الذَّكَرُ مِنَ أَوْلاَدِ الذِّئْبِ. 2. ""تَتَكَوَّنُ فِرَقُ "', ':لا جذر:لا مفرد');
