INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7337, 'جِرَابٌ', 'جراب', 'جامد', 'جرب', 'جراب', 'جرب', '', '', '', 'مفرد', 'DnN', '', '', '"أَجْرِبَةٌ:جُرُبٌ"', '', 'R', '', '', '', '', '', '', '"1.""حَمَلَ الرَّاعِي جِرَابَهُ"": وِعَاءٌ مِنْ جِلْدٍ، كِيسٌ، حَقِيبَةٌ. 2.""وَضَعَ الْمُسَـدَّسَ فِـي الجِرَابِ"" : الجُعْبَة، القِرَاب، الغِلاَف. 3.""أَخْرَجَ السَّيْفَ مِنْ جِرَابِهِ"": مِنْ غِمْدِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7338, 'أَجْرِبَةٌ', 'أجربة', 'جامد', '', 'ءجربة', 'جربة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
