INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7340, 'جَرَبٌ', 'جرب', 'جامد', 'جرب', 'جرب', 'جرب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَرَبٌ - [ج ر ب].""أُصِيبَ بِالجَرَبِ وَصَارَ يَحُكُّ جِلْدَهُ حَكّاً شَدِيداً فِي كُلِّ آنٍ"" : دَاءٌ يُحْدِثُ بُثُوراً (خُرَّاجاً)، حُبَيْبَاتٌ تَنْتَشِرُ فِي البَدَنِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7341, 'جَرَّةٌ', 'جرة', 'جامد', '', 'جرة', 'جرة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"جِرَارٌ"', '', 'R', '', '', '', '', '', '', '"ج: جِرَارٌ. 1.""مَلأََتْ جَرَّتَهَا بِمَاءِ السَّاقِيَةِ"" : إِنَاءٌ مِنْ خَزَفٍ، لَهُ بَطْنٌ دَائِرِيٌّ وَعُرْوَتَانِ وَفَمٌ وَاسِعٌ. 2.""كَانَ الكَهْفُ مَلِيئاً بِجِرَارِ الْمُؤَنِ مِنْ زَيْتُونٍ وَدَقِيقٍ وَعَدَسٍ"" : نَوْعٌ آخَرُ مِنَ الجِرارِ دونَ عُرْوَتَيْنِ أَضْخَمُ"', ':لا جذر:لا مفرد');
