INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7343, 'جُرْثُومٌ', 'جرثوم', 'جامد', '', 'جرثوم', 'جرثم', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"جَرَاثِيمُ"', '', 'R', '', '', '', '', '', '', '"ج: جَرَاثِيمُ. 1.""جُرْثُومُ الشَّيْءِ"" : أَصْلُهُ. 2.""الْجَرَاثِيمُ"" : كَائِنَاتٌ حَيَّةٌ صَغِيرَةٌ جِدًّا لاَ تُرَى بِالعَيْنِ الْمُجَرَّدَةِ، يُمْكِنُ مُعَايَنَتُهَا بِالمِيكْرُوسْكُوبِ فَقَطْ، تُوجَدُ فِي التُّرَابِ وَالْمَاءِ وَالهَوَاءِ وَالأَجْسَامِ، وَهِيَ تَنْقُلُ الأَم"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7344, 'جَرَاثِيمُ', 'جراثيم', 'جامد', '', 'جراثيم', 'جرثم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7345, 'جَرْجَةٌ', 'جرجة', 'جامد', 'جرج', 'جرجة', 'جرجة', '', '', '', 'مفرد', 'DnN', '', '', '"جَرَجٌ"', '', 'R', '', '', '', '', '', '', '". 1.""مَشَى فِي الجَرْجَةِ"" : فيِ وَسَطِ الطَّرِيقِ. 2.""سَارَ فِي الجَرْجَةِ"" : فيِ الأَرْضِ الغَلِيظَةِ."', '');
