INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7347, 'جَارِحَةٌ', 'جارحة', 'جامد', 'جرح', 'جارحة', 'جرحة', '', '', '', 'مفرد', 'DnN', '', '', '"جَوَارِحُ"', '', 'R', '', '', '', '', '', '', '". 1.""جَوَارِحُ الإِنْسَانِ"": أَعْضَاؤُهُ الَّتِي تَكْسِبُ وَهِيَ عَوَامِلُهُ كَيَدَيْهِ وَرِجْلَيْهِ. 2.""اِشْتَاقَ إِلَى رُؤْيَةِ أَهْلِهِ بِكُلِّ جَوَارِحِهِ"" : بِكُلِّ مَا يَمْلِكُ مِنْ قُوَّةِ جَوَاِنحِهِ. 3.""مَا لَهُ جَارِحَةٌ"" : أَيْ مَا لَهُ كَاسِبٌ. 4.""جَوَارِحُ الحَيَوَانِ"" : ذَاتُ ا"', '');
