INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7349, 'جِرَاحَةٌ', 'جراحة', 'جامد', 'جرح', 'جراحة', 'جرحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":جِرَاحٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أُصِيبَ بِجِرَاحَةٍ فِي سَاقِهِ وَيَدَيْهِ"" : شُقوُقٌ فِي البَدَنِ يَنْتُجُ عَنْهَا سَيْلَ الدَّمِ. 2.""حَصَلَ عَلَى شَهَادَةٍ مِنْ كُلِّيَّةِ الطِّبِّ فِي عِلْمِ الجِرَاحَةِ"": عَمَلُ الجَرَّاحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7350, 'جِرَاحٌ', 'جراح', 'جامد', '', 'جراح', 'جرح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7351, 'جَوَارِحُ', 'جوارح', 'جامد', 'جرح', 'جوارح', 'جرح', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"جَوَارِحُ-جَوَارِحُ [ج ر ح] (حو). 1.""الصَّقْرُ مِنَ الطَّيْرِ الجوَارِحِ"" : أَيْ مِنَ الطَّيْرِ الكَوَاسِرِ الْمُفْتَرِسَةِ، وَهِيَ رُتْبَةٌ جَمِيعُهَا مِنَ اللَّوَاحِمِ، مِنْهَا جَوَارِحُ اللَّيْلِ وَجَوَارِحُ النَّهَارِ. أ.""جَوَارِحُ اللَّيْلِ"" : طَيْرٌ مِنْ رُتْبَةِ الجَوَارِح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7352, 'تَجْرِيدَةٌ', 'تجريدة', 'جامد', 'جرد', 'تجريدة', 'تجردة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْرِيدَةٌ-تَجْرِيدَةٌ [ج ر د]. 1.""تَجْرِيدَةُ نَخْلَةٍ"" : القَضِيبُ مِنَ النَّخْلِ جُرِّدَ مِنْ وَرَقِهِ. 2.""ا"', '');
