INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7422, 'جِزَافٌ', 'جزاف', 'جامد', 'جزف', 'جزاف', 'جزف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جِزَافٌ - [ج ز ف]. 1.""كَانَ البَيْعُ وَالشِّرَاءُ بَيْنَهُمَا جِزَافاً"": بِغَيْرِ وَزْنٍ وَلاَ كَيْلٍ. 2.""أَلْقَى الكَلاَمَ جِزَافاً"" : دُونَ رَوِيَّةٍ وَلاَ تَبَصُّرٍ، أَلْقَاهُ عَلَى عَوَاهِنِهِ. ""تَحَدَّثَ جِزَافاً"". الجُزَافُ (بضم الجيم أو كسرها): ما لا يُعْلَمُ كيله أو وزنه عند البَيع والشراء؛ أعطاه حاجته من القمح جُزافاً-: التعاقد على صفقة بمبلغ معيّن؛ باع غلة البستان بمبلغ جُزاف-: كلُّ ما لا يضبط أمره حسب المتعارف عليه؛ كال له المديحَ جُزافا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7423, 'مِجْزَفَةٌ', 'مجزفة', 'جامد', 'جزف', 'مجزفة', 'مجزفة', '', '', '', 'مفرد', 'DnN', '', '', '"مَجَازِفُ"', '', 'R', '', '', '', '', '', '', '". ""مِجْزَفَةُ صَيَّادِ السَّمَكِ"" : شَبَكَةٌ يُصَادُ بِهَا السَّمَكُ."', '');
