INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7426, 'جَزْلٌ', 'جزل', 'جامد', 'جزل', 'جزل', 'جزل', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"جَزْلٌ-جَزْلٌ، ةٌ [ج ز ل]. 1."" كَانَ جَزْلاً فِي عَطَائِهِ"" : سَخِيًّا، كَرِيماً. 2.""هُوَ جَزْلٌ بَيْنَ الخُطَبَاءِ"" : فَصِيحٌ. 3.""جَاءَ بِأَلْفَاظٍ جَزْلَةٍ"" : فَصِيحَةٍ. ""لَفْظٌ جَزْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7427, 'جَزْمَةٌ', 'جزمة', 'جامد', 'جزم', 'جزمة', 'جزمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"جَزْمَةٌ-جَزْمَةٌ [ج ز م]. ""جَزْمَةٌ مِنْ جِلْدٍ رَفيعٍ"" : حِذاءٌ طَويلُ السَّاقِ. ""اِنْتَعَلَتِ الفَتَاةُ جَزْمَةً تَصِلُ إِلىَ رُكْبَتَيْهَا""."', '');
