INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7492, 'مَجْلِسٌ', 'مجلس', 'جامد', 'جلس', 'مجلس', 'مجلس', '', '', '', 'مفرد', 'DnN', '', '', '"مَجَالِسُ"', '', 'R', '', '', '', '', '', '', '". 1.""اِسْتَقَبْلَهُمُ الأَمِيرُ فِي مَجْلِسِهِ"" : فِي حَضْرَتِهِ، مَكَانُ جُلُوسِهِ وَاجْتِمَاعِهِ بِالنَّاسِ. ""أَصْبَحَ حَدِيثَ مَجَالِسِ النَّاسِ"". 2.""انْتُخِبَ عُضْواً فِي الْمَجْلِسِ البَلَدِيِّ"" : فِي الْهَيْئَةِ الْمُنْتَخَبَةِ الَّتِي تَتَعَهَّدُ بِالإِصْلاَحَاتِ وَالْمُنْجَزَاتِ الخَاصَّةِ بِقَضَايَا الْمَدينَةِ وَشؤونِها. 3.""اِجْتَمَعَ مَجْلِسُ النُّوَّابِ فِي دَوْرَةٍ عَادِيَةٍ"" : مَا يُطْلَقُ عَلَى مَكَانِ اجْتِمَاعِ النُّوَّابِ وَعَلَى النُّوَّابِ أَنْفُسِهِمْ. ""مَجْلِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7493, 'مَجَالِسُ', 'مجالس', 'جامد', '', 'مجالس', 'مجلس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
