INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7495, 'جُلْفَةٌ', 'جلفة', 'جامد', 'جلف', 'جلفة', 'جلفة', '', '', '', 'مفرد', 'DnN', '', '', '"جُلَفٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَزَالَ جُلْفَةَ الْمَوْزِ أَوِ اللَّيْمُونِ"" : أَزَالَ قِشْرَتَهَا. 2.""قَشَرَ جُلْفَةَ الجِلْدِ"" : مَا يُقَشَّرُ مِنَ الجِلْدِ وَيُكْشَطُ."', '');
