INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7499, 'حَلِفَةٌ', 'حلفة', 'جامد', 'جلف', 'حلفة', 'حلفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حَلِفَةٌ-حَلِفَةٌ [ج ل ف]. ""أرْضٌ حَلِفَةٌ"" : كَثِيرةُ الحَلْفاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7500, 'جَلَلٌ', 'جلل', 'جامد', 'جلل', 'جلل', 'جل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَلَلٌ-جَلَلٌ [ج ل ل]. ""وَقَفَ مَذْهُولاً أَمَامَ الْمُصُابِ الجَلَلِ"": العَظِيمِ، الخَطِيرِ، البَالِغِ. ""إِنَّهُ لأَمْرٌ جَلَلٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7501, 'مَجَلَّةٌ', 'مجلة', 'جامد', 'جلل', 'مجلة', 'مجلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '".: الكَلِمَةُ كَانَتْ تَعْنِي الصَّحِيفَةَ الْمُتَضَمِّنَةَ لِحِكْمَةٍ، الكُرَّاسُ، وَتَعْنِي الآنَ كُلَّ جَرِيدَةٍ عَلَى شَكْلِ كُرَّاسٍ أَوْ كِتَابٍ يَصْدُرُ مَرَّةً فِي الأُسْبُوعِ أَوِ الشَّهْرِ. ""مَجَلَّةٌ أَدَبِيَّةٌ"" ""مَجَلَّةٌ عِلْمِيَّةٌ"" ""مَجَلَّةٌ سِيَاسِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7502, 'جَلْمَدٌ', 'جلمد', 'جامد', 'جلمد', 'جلمد', 'جلمد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَلْمَدٌ-جَلْمَدٌ [ج ل م د]. 1.: الصَّخْرُ. 2.""هُوَ جَلْمَدُ الصَّوْتِ"" : شَدِيدُ الصَّوْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7503, 'جُلْمُودٌ', 'جلمود', 'جامد', '', 'جلمود', 'جلمد', '', '', '', 'جمع تكسير', 'DnN', '', '', '"جَلاَمِيدُ"', '', 'R', '', '', '', '', '', '', '"ج: جَلاَمِيدُ. 1.""جُلُمُودُ الجَبَلِ"" : صَخْرُهُ. ""كَجُلْمُودِ صَخْرٍ حَطَّهُ السَّيْلُ مِنْ عَلِ"".(امرؤ القيس). 2.""أَلْقَى عَلَيْهِ جَلاَمِيدَهُ"" : أَثْقَالَهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7504, 'جَلاَمِيدُ', 'جلاميد', 'جامد', '', 'جلاميد', 'جلمد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7505, 'جُلَّنَارُ', 'جلنار', 'جامد', '', 'جلنار', 'جلنر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"""أَزْهَرَتْ شَجَرَةُ الرُّمَّانِ بِالجُلَّنَارِ"" : زَهْرُ الرُّمَّانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7506, 'جَالِيَةٌ', 'جالية', 'جامد', 'جلو', 'جالية', 'جلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":جَوَالٍ"', '', '', '', '', '', '', '', '', '". ""تَعِيشُ فِي بِلاَدِنَا جَالِيَاتٌ مُتَعَدِّدَةٌ، فَرَنْسِيَّةٌ وَإِيطَالِيَّةٌ وَإِسْبَانِيَّةٌ"" : أَجَانِبُ اسْتَوْطَنُوا البَلَدَ وَأَقَامُوا فِيهِ. ""تُوجَدُ جَالِيَةٌ عَرَبِيَّةٌ مُهِمَّةٌ فِي أُورُوبَّا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7507, 'جَوَالِي', 'جوالي', 'جامد', '', 'جوالي', 'جل', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7508, 'جَلاً', 'جلا', 'جامد', 'جلو', 'جلا', 'جل', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'N', 'N', 'N', '', '"جَلاً-جَلاً [ج ل و]. 1.""اِبْنُ جَلاَ"" : السَّيِّدُ الشَّرِيفُ، العَالِي الْمَقَامِ. ""أَنَا ابْنُ جَلاَ"".(الحجاج الثقفي). 2.""أَمْرٌ جَلاَ"" : وَاضِحٌ، بَيِّنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7509, 'جَلْوَةٌ', 'جلوة', 'جامد', 'جلو', 'جلوة', 'جلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جِلْوَةٌ-جِلْوَةٌ [ج ل و]. ""أَعْطَى عَرُوسَهُ جِلْوَةً"" : مَا يُعْطِيهِ العَرِيسُ عَرُوسَهُ وَقْتَ الجَلْوَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7510, 'جِلْوَةٌ', 'جلوة', 'جامد', 'جلو', 'جلوة', 'جلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَلْوَةٌ-جَلْوَةٌ [ج ل و]. ""حَضَرَ الأَهْلُ وَالصِّحَابُ وَقْتَ الجَلْوَةِ"" : الوَقْتُ الَّذِي يُعْطِي فِيهِ العَرِيسُ عَرُوسَهُ الْجِلْوَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7511, 'مَجْلىً', 'مجلى', 'جامد', 'جلي', 'مجلى', 'مجل', '', '', '', 'مفرد', 'Dy', '', '', '', '', '', '', '', '', '', '', '', '"مَجْلىً-مَجْلىً [ج ل ي]. ""تُجَلَّى الصُّحُونُ فِي الْمَجْلَى"" : حَوْضُ الغَسْلِ، المِغْسَلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7512, 'جُمَّارٌ', 'جمار', 'جامد', '', 'جمار', 'جمر', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات.""جُمَّارُ النَّخْلَةِ"" : قَلْبُهَا وَشَحْمُهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7513, 'جِمَارٌ', 'جمار', 'جامد', '', 'جمار', 'جمر', '', '', '', 'جمع تكسير', '', '', '', '"مفردجَمْرَة"', '', 'R', '', '', '', '', '', '', '"جمع جَمْرَة. ""جِمَارُ الحَجِّ"" : الحَصَى الَّتِي يَرْمِي بِهَا الحَاجُّ فِي مِنىً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7514, 'جَمْرَة', 'جمرة', 'جامد', '', 'جمرة', 'جمرة', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7515, 'جُمَّازَةٌ', 'جمازة', 'جامد', '', 'جمازة', 'جمزة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. ""اِرْتَدَى الجُمَّازَةَ"" : لِبَاسٌ يُلْبَسُ فَوْقَ القَمِيصِ وَنَحْوِهِ، يُغَطِّي الذِّرَاعَيْنِ، مَفْتُوحٌ مِنَ الأَمَامِ. ""إِنَّ النّبِيَّ تَوَضَّأَ فَضَاقَ عَنْ يَدَيْهِ كُمَّا جِمَازَةٍ كَانَتْ عَلَيْهِ . (حديث)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7516, 'جُمَانٌ', 'جمان', 'جامد', '', 'جمان', 'جمن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""يَمْلِكُ الْمُرْجَانَ وَالجُمَانَ"" : اللَّؤْلُؤَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7517, 'جِمْبَاز', 'جمباز', 'جامد', '', 'جمباز', 'جمبز', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جِمْبَاز-جِمْبَاز (ريا).: فَنٌّ مِنْ فُنُونِ الأَلْعَابِ الرِّيَاضِيَّةِ، يَشْمَلُ رِيَاضَةَ عَارِضَة الْمُتَوَازِيَاتِ وَحِصَان القَفْزِ وَالعُقْلاَتِ الثَّابِتَةِ وَالحَلَقَاتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7518, 'جُمْجُمَةٌ', 'جمجمة', 'جامد', 'جمجم', 'جمجمة', 'جمجمة', '', '', '', 'مفرد', 'DnN', '', '', '"جَمَاجِمُ"', '', 'R', '', '', '', '', '', '', '". ""جُمْجُمَةُ الرَّأْسِ"" : عَظْمُ الرَّأْسِ الْمُشْتَمِلُ عَلَى الدِّمَاغِ، وَهُوَ مُكَوَّنٌ مِنْ ثَمَانِيَةِ عِظَامٍ يَتَّصِلُ بَعْضُهُا بِبَعْضٍ. ""اِكْتَشَفَ كَهْفاً قَدِيماً بِهِ جَمَاجِمُ كَثِيرَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7519, 'جَمَاجِمُ', 'جماجم', 'جامد', '', 'جماجم', 'جمجم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7520, 'جَمَادٌ', 'جماد', 'جامد', 'جمد', 'جماد', 'جمد', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '".: مَا لاَ حَيَاةَ لَهُ، لاَ يَتَحَرَّكُ وَلاَ يَنْمُو خِلاَف الإِنْسَانِ وَالحَيَوَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7521, 'جُمَادَى', 'جمادى', 'جامد', 'جمد', 'جمادى', 'جمد', '', '', '', 'مفرد', 'Dy', '', '', '"جُمَادِيَاتٌ"', 'ممنوع من الصرف', 'R0', '', 'N', 'N', 'N', 'O', '', '". 1. ""جُمَادَى الأُولَى"" : مِنَ الشُّهُورٍ القَمَرِيَّةِ، وَهُوَ الشَّهْرُ الخَامِسُ، عَدَدُ أَيَّامِهِ (29) أو (30) يَوْمًا، يَأْتِي بَعْدَ رَبِيعِ الثَّانِي وَيَلِيهِ جُمَادَى الثَّانِيَةُ. 2.""جُمَادَى الثَّانِيَةُ"" : مِنَ الشُّهُورِ القَمَرِيَّةِ وَهُوَ الشَّهْرُ السَّادِسُ، عَدَدُ أَيَّامِهِ (29) أو (30) يَوْمًا، يَأْتِي بَعْدَ جُمَادَى الأُولَى وَيَلِيهِ رَجَب."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7522, 'جُمَادِيَاتٌ', 'جماديات', 'جامد', '', 'جماديات', 'جمدت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
