INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7526, 'جَمْرَةٌ', 'جمرة', 'جامد', 'جمر', 'جمرة', 'جمرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":جِمَارٌ:جَمْرٌ"', '', 'R', '', '', '', '', '', '', '". 1.:القِطْعَةُ مِنَ الفَحْمِ أَوِ الخَشَبِ عِنْدَ تَحَوُّلِهِما إِلَى نَارٍ خَمَدَ لَهِيبُهَا. 2.""الجَمْرَةُ"" : الحَصَاةُ الصَّغِيَرةُ الَّتِي يَرْمِي بِهَا الحَاجُّ فيِ منِىً. 3.""الجَمْرَةُ "', '');
