INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7529, 'جَمْرٌ', 'جمر', 'جامد', 'جمر', 'جمر', 'جمر', '', '', '', 'مفرد', '', '', '', '"مفردجَمْرَة"', '', 'R', '', '', '', '', '', '', '". 1.""تَحَلَّقُوا حَوْلَ الجَمْرِ لِيَسْتَدْفِئُوا بِهِ"" : الفَحْم أَوِ الخَشَب وَقَدْ تَحَوَّلَ إِلَى نَارٍ خَمَدَ لَهِيبُهَا. ""اِكْتَنَفَ الرَّمَادُ جَمْرَهُ"". (جبران خ. جبران). 2.""يَنْتَظِرُهُ عَلَى أَحَرَّ مِنَ الجَمْرِ"" : بِفَارِغِ الصَّبْرِ وَكَأَنَّهُ عَلَى نَارٍ. 3.""كَانَ عَلَى أَحَرَّ مِنَ الجَمْرِ"" : فِي وَضْعٍ حَرِجٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7530, 'مِجْمَرٌ', 'مجمر', 'جامد', 'جمر', 'مجمر', 'مجمر', '', '', '', 'مفرد', 'DnN', '', '', '"مَجَامِرُ"', '', 'R', '', '', '', '', '', '', '".: وِعَاءٌ مِنْ حَدِيدٍ أَوْ فَخَّاريُوقَدُ فِيهِ الخَشَبُ أَوِ الفَحْمُ لِيَتَحَوَّلَ إِلَى جَمْرٍ، الْمَوْقِدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7531, 'مَجَامِرُ', 'مجامر', 'جامد', '', 'مجامر', 'مجمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7532, 'جُمْرُكٌ', 'جمرك', 'جامد', '', 'جمرك', 'جمرك', '', '', '', 'جمع تكسير', 'DnN', '', '', '"جَمَارِكُ"', '', 'R', '', '', '', '', '', '', '"ج: جَمَارِكُ. 1.""خَضَعَ لِتَفْتِيشٍ دَقِيقٍ فِي الجُمْرُكِ"" : فِي الدٍّيوَانَةِ، نُقْطَةُ الْمُرُورِ فِي الحُدُودِ الفَاصِلَةِ بَيْنَ بَلَدَيْنِ، وَيَتَوَلّ"', ':لا جذر:لا مفرد');
