INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7534, 'جَامِعَةٌ', 'جامعة', 'جامد', 'جمع', 'جامعة', 'جمعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"مُؤَنَّثُالجَامِعِ"', '', 'Rp', '', '', '', '', '', '', '". 1.""غَلَّهُ بِالجَامِعَةِ"" : طَوْقٌ أَوْ قَيْدٌ مِنْ حَدِيدٍ يَجْمَعُ يَدَيِ الأَسِيِر أَوْ الْمُجْرِمِ إِلىَ العُنُقِ. 2. قِدْرُ جَامِعَةٌ"" : عَظِيمَةٌ. 3.""يَدْرُسُ بِالجَامِعَةِ"" : مَنْ يُتَابِعُ دِرَاسَتَهُ بِإِحْدَى الكُلِّيَّاتِ أَوِ الْمَعَاهِدِ العُلْي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7535, 'جَمَاعَةٌ', 'جماعة', 'جامد', 'جمع', 'جماعة', 'جمعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""اِلْتَقَتْ جَمَاعَةٌ مِنَ الرِّجَالِ"" : فِرْقَةٌ، مَجْمُوعَةٌ، زُمْرَةٌ، طَائِفَةٌ. 2.""وَصَلُوا جَمَاعَاتٍ وَأْفَرَاداً"" : زُمَراً، أَيْ بِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7536, 'جُمَّاعٌ', 'جماع', 'جامد', 'جمع', 'جماع', 'جمع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جُمَّاعٌ-جُمَّاعٌ [ج م ع]. 1.""جُمَّاعٌ مِنْ كُلِّ شَيْءٍ"" : مُجْتَمَعُ أَصْلِهِ، وَكُلُّ مَا اجْتَمَعَ وَانْضَمَّ بَعْضُهُ إِلَى بَعْضٍ. 2.""جُمَّاعُ النَّاسِ"" : أَخْلاَطُهُمْ. 3.""جُمَّاعُ الجَسَدِ"" : الرَّأْسُ. 4.""جُمَّاعُ الثُّرَيَّا"" : مَا اجْتَمَعَ مِنْ كَوَاكِبِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7537, 'جُمْعٌ', 'جمع', 'جامد', 'جمع', 'جمع', 'جمع', '', '', '', 'مفرد', 'DnN', '', '', '"أَجْمَاعٌ"', '', 'R', '', '', '', '', '', '', '". ""وَجَّهَ إِلَيْهِ لَكْمَةً بِج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7538, 'أَجْمَاعٌ', 'أجماع', 'جامد', '', 'ءجماع', 'جمع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7539, 'جَمْعِيَّةٌ', 'جمعية', 'جامد', 'جمع', 'جمعية', 'جمعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""كَوَّنُوا جَمْعِيَّةً"" : جَمَاعَةً مِنَ الأَفْرَادِ يَنْتَظِمُونَ فِي عَمَلٍ جَمَاعِيٍّ مُشْتَرَكٍ حَسَبَ قَانُونٍ دَاخِلِيٍّ لِهَدَف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7540, 'مَجَامِعُ', 'مجامع', 'جامد', 'جمع', 'مجامع', 'مجمع', '', '', '', 'مفرد', '', '', '', '"مفردمَجْمَع"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '". 1.""أَخَذَتْ مَحَبَّتُهُ بِمَجَامِعِ قَلْبِي"" : أَيْ بِكُلِّيَّتِهِ. 2.""مَجَامِعُ اللُّغَةِ"". ن. مَجْمَع."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7541, 'مَجْمَعٌ', 'مجمع', 'جامد', 'جمع', 'مجمع', 'مجمع', '', '', '', 'مفرد', 'DnN', '', '', '"مَجَامِعُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""مَجْمَعُ الجُمْهُورِ"" : مَوْضِعُ اجْتِمَاعِهِمْ. 2.""أَخَذَتْ مَحَبَّتُهُ بِمَجَامِعِ قَلْبِي"" : أَيْ بِجَمِيعِ أَجْزَائِهِ. 3.""الْمَجْمَعُ الدِّينِيُّ"" : هَيْئَةُ رِجَالِ الدِّينِ الكِبَارِ الْمُجْتَمِعَةِ لِلنَّظَرِ فِي القَضَايَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7542, 'مَجَامِعُ', 'مجامع', 'جامد', '', 'مجامع', 'مجمع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7543, 'جُمُعَةٌ', 'جمعة', 'جامد', '', 'جمعة', 'جمعة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":جُمَعٌ"', '', 'R', '', 'N', 'O', 'N', 'O', '', '"ج: جُمَعٌ، جُمُعَاتٌ. 1.""صَلاَةُ الجُمُعَةِ"" : صَلاَةُ يَوْمِ الجُمُعَةِ الَّتِي يُؤَدِّيهَا الْمُسْلِمُونَ جَمَاعَةً عِنْدَ الظُّهْرِ. 2.""يَوْمُ الجُمُعَةِ"" : اليَوْمُ السَّادِسُ مِنَ الأُسْبُوعِ.الجمعة آية 9 إِذَا نُودِيَ لِلصَّلاَةِ مِنْ يَوْمِ الجُمُعَةِ فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ وَذَرُوا البَيْعَ (قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7544, 'جُمَعٌ', 'جمع', 'جامد', '', 'جمع', 'جمع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7545, 'جُمْلَةٌ', 'جملة', 'جامد', 'جمل', 'جملة', 'جملة', '', '', '', 'مفرد', 'DnN', '', '', '"جُمَلٌ"', '', 'R', '', '', '', '', '', '', '". 1.""قَرَأَ الكتِاَبَ جُمْلَةً وَتَفْصِيلاً"" : أَيْ كُلِّيَّةً. ""فَهِمْتُ جَمِيعَ مَا قُلْتَ لِي بِالأَمْسِ وَبَانَ لِي الرُّشْدُ فِي جُمْلَتِهِ"".(التوحيدي). 2.""جُمْلَةُ القَوْلِ"" : قُصَارَى القَوْلِ. 3.""عَلَى الجُمْلَةِ سَأَحْكِي أَهَمَّ مَا فِي القِصَّةِ"" : بِاخْتِصَارٍ. 4.""كَانَ مِنْ جُمْلَةِ أَصْحَابِهِ"" : مِنْ بَيْنِهِمْ. 5.""وَالِدُهُ مِنْ تُجَّارِ الْجُمْلَةِ"" : مَنْ يَبِيعُ بِكَمِّيَّاتٍ كَبِيرَةٍ عَكْسَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7546, 'جُمَلٌ', 'جمل', 'جامد', '', 'جمل', 'جمل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7547, 'جُمَّلٌ', 'جمل', 'جامد', 'جمل', 'جمل', 'جمل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جُمَّلٌ-جُمَّلٌ [ج م ل]. ""حِسَابُ الجُمَّلِ"" : حِسَابُ الحُرُوفِ الأَبَجَدِيَّةِ. ن. تَعْرِيف كُلِّ حَرْفٍ مِنْ حُرُوفِ هَذَا الْمُعْجَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7548, 'جَمَلٌ', 'جمل', 'جامد', '', 'جمل', 'جمل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"جِمَالٌ"', '', 'R', '', '', '', '', '', '', '"ج: جِمَالٌ. (حو).: حَيَوَانٌ مِنْ فَصِيلَةِ الجَمَلِيَّاتِ، مُجْتَرٌّ ضَخْمٌ، طَوِيلُ العُنُقِ وَالقَوَائِمِ يَكُونُ بِسَنَامٍ أَوْ سَنَامَيْنِ، يَعِيشُ فِي الصَّحْرَاءِ وَيَصْبِرُ عَلَى العَطَشِ. ""سَارَ وَرَاءَ قَافِلَةِ الجِمَالِ"" ""وَبَرُ الجِمَالِ"" ""جَلْجَلَةُ الجِمَالِ"" ""الجَمَلُ لاَ يَرَى حَدَبَتَهُ"". (مثل)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7549, 'جِمَالٌ', 'جمال', 'جامد', '', 'جمال', 'جمل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7550, 'جِمَامٌ', 'جمام', 'جامد', 'جمم', 'جمام', 'جمم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جِمَامٌ-جِمَامٌ [ج م م]. ""هُوَ بِحَاجَةٍ إِلَى جِمَامٍ"" : الرَّاحَة مِنَ الحَرَكَةِ. ""اللَّيْلَةُ رَاحَةٌ لِمَا قَبْلَهَا مِنَ التَّعَبِ وَجِمَامٌ لمِاَ بَعْدَهَا مِنَ العَمَلِ"".(التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7551, 'جُمَّةٌ', 'جمة', 'جامد', 'جمم', 'جمة', 'جمة', '', '', '', 'مفرد', 'DnN', '', '', '"جُمَمٌ"', '', 'R', '', '', '', '', '', '', '". ""جُمَّةُ شَعَرِ الرَّأْسِ"" : مُجْتَمَعُ شَعَرِ الرَّأْسِ الْمُتَدَلِّي إِلَى شَحْمَةِ الأُذُنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7552, 'جُمَمٌ', 'جمم', 'جامد', '', 'جمم', 'جم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7553, 'جَمٌّ', 'جم', 'جامد', 'جمم', 'جم', 'جم', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"جَمَامٌ:جُمُومٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَحَبَّهُ حُبّاً جَمّاً"" : أَحَبَّهُ كَثِيراً. الفجر آية 20 وَتُحِبُّونَ الْمَالَ حُبّاً جَمّاً .(قرآن). 2.""جَاءوا جَمّاً غَفِيراً وَمِنْ كُلِّ فَجٍّ عَمِيقٍ"" : جَاءوا بِكَثْرَةٍ عَنْ آخِرِهِمْ، أَوْ مُعْظَمِهِمْ. 3.""لِلأَعْشَابِ فَوَائِدُ جَمَّةٌ"" : كَثِيرَةٌ، مُتَعَدِّدَةٌ."', '');
