INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7555, 'جُمُومٌ', 'جموم', 'جامد', '', 'جموم', 'جمم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7556, 'جَمِيمٌ', 'جميم', 'جامد', 'جمم', 'جميم', 'جمم', '', '', '', 'مفرد', 'DnN', '', '', '"أَجِمَّاءُ"', '', 'R', '', '', '', '', '', '', '". 1.""اِنْتَشَرَ الجَمِيمُ"" : النَّبَاتُ الكَثِيرُ المنُتَشِرُ. 2.""اِلْتَفَ الجَمِيمُ"" : النَّبَاتُ الطَّوِيلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7557, 'أَجِمَّاءُ', 'أجماء', 'جامد', '', 'ءجماء', 'جم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7558, 'جُمْهُورٌ', 'جمهور', 'جامد', 'جمهر', 'جمهور', 'جمهر', '', '', '', 'مفرد', 'DnN', '', '', '"جَمَاهِيرُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""اِلْتَفَّ جُمْهُورٌ غَفِيرٌ حَوْلَهُ"": جَمَاعَةٌ مِنَ النَّاسِ، حَشْدٌ. 2.""خَرَجَتِ الجَمَاهِيرُ عَنْ بَكْرَةِ أَبِيهَا"" : حُشُودٌ، جَمَاعَاتٌ. ""جَمَاهِيرُ الشَّعْبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7559, 'جَمَاهِيرُ', 'جماهير', 'جامد', '', 'جماهير', 'جمهر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7560, 'جُمَّيْزٌ', 'جميز', 'جامد', '', 'جميز', 'جمز', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"جُمَّيْزٌ-جُمَّيْزٌ، ةٌ (نب).: شَجَرٌ مِنْ فَصِيلَةِ التُّوتِيَّاتِ ثَمَرُهُ يُؤْكَلُ وَهُوَ يُشْبِهُ التِّينَ وَيُعَرَفُ بِتِينِ فِرْعَوْنَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7561, 'جِنٌّ', 'جن', 'جامد', '', 'جن', 'جن', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"""يَتَوَهَّمُ أَنَّ الجِنَّ يَسْكُنُ القَرْيَةَ الْمَهْجُورَةَ"": مَخْلُوقَاتٌ غَرِيبَةٌ، يَعْتَقِدُ الإِنْسَانُ وُجُودَهَا عَكْسَ الإِنْسِ.الكهف آية 50 فَسَجَدُوا إِلاَّ إِبْلِيسَ كَانَ مِنَ الجِنِّالنمل آية 39 قَالَ عِفْرِيتٌ مِنَ الجِنِّ أَنَا آتِيكَ بِه .(قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7562, 'جَنَّازٌ', 'جناز', 'جامد', '', 'جناز', 'جنز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"""الجَنَّازُ عِنْدَ الْمَسِيحِيِّينَ"" : الصَّلاَةُ عَلَى الْمَيِّتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7563, 'جَنَازَةٌ', 'جنازة', 'جامد', '', 'جنازة', 'جنزة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":جَنَائِزُ"', '', 'R', '', '', '', '', '', '', '"ج: جَنَائِزُ. ""سَارَ القَوْمُ وَرَاءَ الجَنَازَةِ"" : نَعْشُ الْمَيِّتِ فِي مَوْكِبِ الْمُشَيِّعِينَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7564, 'جَنَائِزُ', 'جنائز', 'جامد', '', 'جناءز', 'جنز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7565, 'جَانِبٌ', 'جانب', 'جامد', 'جنب', 'جانب', 'جنب', '', '', '', 'مفرد', 'DnN', '', '', '"جَوَانِبُ"', '', 'R', '', '', '', '', '', '', '". 1. ""رَآهُ يَدُورُ وَيَلُفُّ بِجَوَانِبِ القَصْرِ"" : الأَطْرَافُ، النَّوَاحِي. 2. ""كَانَ لَيِّنَ الجَانِبِ"": سَهْلَ الْمُعَاشَرَةِ. 3. ""رَقِيقُ الجَانِبِ"" : اللَّطِيفُ، الْمَحْبُوبُ، الأَنِيسُ. 4. ""عَزِيزُ الجَانِبِ"" : ذُو سَطْوَةٍ وَمَهَابَةٍ. ""مَنِيعُ الجَانِبِ"". 5. ""كَانَ يَجْلِسُ بِجَانِبِهِ"" : بِالقُرْبِ مِنْهُ. 6.""وَقَفَ إِلَى جَانِبِهِ"" : بِالقُرْبِ مِنْهُ، كَمَا تَعْنِي وَقَفَ مُنَاصِراً لَهُ. 7. ""قَدَّمَ لَهُ هَدِيَّةً مِنْ جَانِبِهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7566, 'جَوَانِبُ', 'جوانب', 'جامد', '', 'جوانب', 'جنب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7567, 'جَنَابٌ', 'جناب', 'جامد', 'جنب', 'جناب', 'جنب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جُنَابٌ-جُنَابٌ [ج ن ب] (اِسْمُ دَاءِ ذاَتِ الجَنْبِ). ""أُصِيبَ بِدَاءِ الجُنَابِ"" : اِلْتِهَابٌ فِي الغِلاَفِ الْمُحيِطِ بِالرِّئَةِ يُحْدِثُ سُعالاً وَضَيْقاً فِي التَّنَفُّسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7568, 'جُنَابٌ', 'جناب', 'جامد', 'جنب', 'جناب', 'جنب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَنَابٌ-جَنَابٌ [ج ن ب]. 1.""كَتَبَ رِسَالَةً إِلَى جَنَابِهِ الكَرِيمِ"": إِلَى حَضْرَتِهِ، وَتُطْلَقُ عَلَى أَكَابِرِ الـنَّاسِ. ""إِلَى جَنَابِ الْمُدِيرِ"". 2.""عِشْتُ فِي جَنَابِهِ"" : فِي كَنَفِهِ، فِي رِعَايَتِهِ. 3.""جَنَابُ مَكَانٍ"" : نَاحِيَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7569, 'جَنْبَةٌ', 'جنبة', 'جامد', 'جنب', 'جنبة', 'جنبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"جَنْبَةٌ-جَنْبَةٌ [ج ن ب]. 1.""جَنْبَةُ الدَّارِ"" : جَانِبُهَا، نَاحِيَتُهَا. ""جَنْبَتَا الوَادِي"" ""جَنْبَتا الأَنْفِ"". 2.""عَلَيْكُمْ بِالجَنْبَةِ فَإِنَّهَا عَفَافٌ"" : تَّجَنُّبُ الاعْتِزَالِ. 3.""جَنْبَةٌ مِنَ النَّبَاتِ"" : مَا كَانَ بَيْنَ الشَّجَرِ وَالبَقْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7570, 'جَنُوبٌ', 'جنوب', 'جامد', 'جنب', 'جنوب', 'جنب', '', '', '', 'مفرد', 'DnN', '', '', '"جَنَائِبُ"', '', 'Rp', '', '', '', '', '', '', '"(جغ). 1.""هُوَ مِنْ سُكَّانِ الجَنُوبِ"" : أَحَدُ الجِهَاتِ الأَصْلِيَّةِ، وَهُوَ مَا يُقَابِلُ قُطْرِيّاً جِهَةَ الشَّمَالِ. ""أَظْهَرَ سُكَّانُ جَنُوبِ لُبْنَانَ بُطُولَةً نَادِرَةً ضِدَّ الاحْتِلالِ الصَّهْيُونِيّ"". 2.""اِتَّجَهَ جَنُوباً بِسَيَّارَتِهِ"" : جِهَةَ الْجَنُوبِ. 3.""هَبَّتْ رِيَاحُ الجَنُوبِ"" : الرِّيَاحُ الآتِيَةُ مِنْ ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7571, 'جَنَائِبُ', 'جنائب', 'جامد', '', 'جناءب', 'جنب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7572, 'جَوَانِبُ', 'جوانب', 'جامد', 'جنب', 'جوانب', 'جنب', '', '', '', 'مفرد', '', '', '', '"مفردجَانِب"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""جَوَانِبُ البَيْتِ"" : نَوَاحِيهِ. 2.""يَكْتُبُ فِي جَوَانِبِ الكِتَابِ"" : فِي حَوَاشِيهِ. 3.""قَصْرٌ رَحْبُ الجَوَانِبِ"" : وَاسِعٌ، فَسِيحُ الأَرْكَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7573, 'مِجْنَبٌ', 'مجنب', 'جامد', 'جنب', 'مجنب', 'مجنب', '', '', '', 'مفرد', 'DnN', '', '', '"مَجَانِبُ"', '', 'R', '', '', '', '', '', '', '". 1.: الترُّْسُ.2.: السِّتْرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7574, 'مَجَانِبُ', 'مجانب', 'جامد', '', 'مجانب', 'مجنب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7575, 'جَنْبٌ', 'جنب', 'جامد', '', 'جنب', 'جنب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَجْنَابٌ:جُنُوبٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَجْنَابٌ، جُنُوبٌ. 1.""أَحَسَّ بِأَلَمٍ فيِ جَنْبِهِ الأَيْمَنِ"": فِي شِقِّهِ، فِي خَاصِرَتِهِ، فِي كَشْحِهِ. 2.""جَلَسَ بِجَنْبِهِ"": بِقُرْبِهِ. 3.""جَنْباً لِجَنْبٍ أَوْ جَنْباً إِلَى جَنْبٍ"" : الْمُحَاذَاةُ، الْمُجَاوَرَةُ. 4.""ذَاتُ الْجَنْبِ"" : مَرَضُ الْجُنَابِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7576, 'أَجْنَابٌ', 'أجناب', 'جامد', '', 'ءجناب', 'جنب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7577, 'جُنُوبٌ', 'جنوب', 'جامد', '', 'جنوب', 'جنب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7578, 'جَنَبَةٌ', 'جنبة', 'جامد', '', 'جنبة', 'جنبة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. 1.""طَافَ فِي كُلِّ جَنَبَاتِ القَصْرِ"" : نَوَاحِيهِ، فِي دَاخِلِهِ. 2.""ضَمَّتْ طِفْلَهَا بَيْنَ جَنَبَاتِهَا"" : فِي حِضْنِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7579, 'جَنَّةٌ', 'جنة', 'جامد', '', 'جنة', 'جنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":جِنَانٌ"', '', 'R', '', '', '', '', '', '', '"ج: جَنَّاتٌ، جِنَانٌ. 1.""يَعِيشُ فِي جَنّةٍ"" : فِي نَعِيمٍ. 2.""حَوَّلَ المِنْطَقَةَ إِلَى جِنَانٍ"" : إِلَى حَدَائِقَ. 3.البقرة آية 266 أَيَوَدُّ أَحَدُكُمْ أَنْ تَكُونَ لَهُ جَنَّةٌ مِنْ نَخِيلٍ وَأَعْنَاب، آل عمران آية 133سَارِعُوا إِلىَ مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّة"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7580, 'جِنَانٌ', 'جنان', 'جامد', '', 'جنان', 'جنن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7581, 'جَنَاحٌ', 'جناح', 'جامد', 'جنح', 'جناح', 'جنح', '', '', '', 'مفرد', 'DnN', '', '', '"أجْنِحَةٌمثنىجَناحان"', '', 'R', '', '', '', '', '', '', '". 1.""يَطِيرُ الطَّائِرُ بِجِنَاحَيْهِ"" : مَا يَطِيرُ بِهِ وَيُسَاعِدُهُ عَلَى الطَّيَرَانِ. 2.""جَنَاحُ الإِنْسَانِ"" : أَحَدُ طَرَفَيْهِ اليَدُ وَالإِبْطُ وَالعَضُدُ. 3.""جَنَاحُ الطَّائِرَةِ"" : أَحَدُ أَطْرَافِهَا. 4.""يَسْكُنُ فِي جَنَاحٍ بَعِيدٍ عَنِ القَرْيَةِ"" : فِي نَاحِيَةٍ. 5.""يَسْكُنُ فِي الجَنَاحِ الأَيْسِرِ مِنَ العِمَارَةِ"" : فِي الطَّرَفِ، فِي الجَانِبِ الْمُلْتَصِقِ بِالجُزْءِ الأَسَاسِيِّ مِنْهَا. 6.""هُوَ مَقْصُوصُ الجَنَاحَيْنِ"" : لاَ قُوَّةَ وَلاَ حَوْلَ لَهُ، عَاجِزٌ، ضَيِّقُ البَاعِ. 7. لَوْ كَانَتِ الدُّنْيَا تَعْدِلُ عِنْدَ الله جَنَاحَ بَعُوضَةٍ مَا سَقَى كَافِراً مِنْهَا شَرْبَةَ مَاءٍ.(حديث) : كِنَايَةً عَنِ القِلَّةِ وَالصِّغَرِ. 8.""أَجَابَه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7582, 'أجْنِحَةٌ', 'أجنحة', 'جامد', '', 'ءجنحة', 'جنحة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7583, 'جُنَاحٌ', 'جناح', 'جامد', 'جنح', 'جناح', 'جنح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جُنَاحٌ-جُنَاحٌ [ج ن ح]. ""لاَ جُنَاحَ عَلَيْكَ"" : لاَ إِثْمَ عَلَيْكَ .الأحزاب آية 5 لَيْسَ عَلَيْكُمْ جُنَاحٌ فِيمَا أَخْطَأْتُمْ بِهِ وَلَكِنْ مَا تَعَمَّدَتْ قُلُوبُكُمْ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7584, 'جُنْحٌ', 'جنح', 'جامد', 'جنح', 'جنح', 'جنح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جُنْحٌ-جُنْحٌ [ج ن ح]. ""تَسَلَّلَ اللِّصُّ فِي جُنْحِ اللَّيْلِ"" : تَحْتَ سِتَارِ الظَّلاَمِ. ""تَسَلَّلَ تَحْتَ جُنْحِ اللَّيْلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7585, 'جَوَانِحُ', 'جوانح', 'جامد', 'جنح', 'جوانح', 'جنح', '', '', '', 'مفرد', '', '', '', '"مفردُجَانِحَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""جَوَانِحُ الإِنْسَانِ"": أَضْلاَعُهُ القَصِيرَةُ مِمَّا يَلِي الصَّدْرَ. ""بَيْنَ جَوَانِحِي أَلَمٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7586, 'جُنْحَةٌ', 'جنحة', 'جامد', '', 'جنحة', 'جنحة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"جُنَحٌ"', '', 'R', '', '', '', '', '', '', '"ج: جُنَحٌ. ""اِرْتَكَبَ جُنْحَةً يُعَاقِبُ عَلَيْهَا القَانُونُ"": إِثْماً، خَطِيئَةً، ذَنْباً. ""اُتُّهِمَ بِجُنَحٍ كَثِيرَةٍ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7587, 'جُنَحٌ', 'جنح', 'جامد', '', 'جنح', 'جنح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7588, 'جُنْدِيَّةٌ', 'جندية', 'جامد', 'جند', 'جندية', 'جندة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جُنْدِيَّةٌ-جُنْدِيَّةٌ [ج ن د]. ""اِنْخَرَطَ فِي الجُنْدِيَّةِ"" : عَمَلُ الجُنْدِيِّ وَنِظَامُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7589, 'جُنْدٌ', 'جند', 'جامد', '', 'جند', 'جند', '', '', '', 'جمع تكسير', 'DnN', '', '', '"جُنُودٌ:أَجْنَادٌ"', '', 'R', '', '', '', '', '', '', '"ج : جُنُودٌ، أَجْنَادٌ. ""تَحَرَّكَ الْجُنْدُ فِي اتِّجَاهِ سَاحَةِ الْمَعْرَكَةِ"": العَسْكَرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7590, 'جُنُودٌ', 'جنود', 'جامد', '', 'جنود', 'جند', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
