INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7592, 'جُنْدُبٌ', 'جندب', 'جامد', '', 'جندب', 'جندب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"جَنَادِبُ"', '', 'R', '', '', '', '', '', '', '"ج: جَنَادِبُ : نَوْعٌ مِنَ الجَرَادِ الصَّغِيرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7593, 'جَنَادِبُ', 'جنادب', 'جامد', '', 'جنادب', 'جندب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7594, 'جَنْدَلٌ', 'جندل', 'جامد', '', 'جندل', 'جندل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"جَنَادِلُ"', '', 'R', '', '', '', '', '', '', '"ج: جَنَادِلُ. ""يَنْسَابُ النَّهْرُ قُرْبَ الجَنْدَلِ"" : الصَّخْر الضَّخْم."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7595, 'جَنَادِلُ', 'جنادل', 'جامد', '', 'جنادل', 'جندل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7596, 'جِنْسٌ', 'جنس', 'جامد', 'جنس', 'جنس', 'جنس', '', '', '', 'مفرد', 'DnN', '', '', '"أَجْنَاسٌ"', '', 'R', '', '', '', '', '', '', '". 1.""ظَلَّ الجِنْسُ البَشَرِيُّ يُحَافِظُ عَلَى بَقَائِهِ"" : أَي النَّوْعُ البَشَرِيُّ. ""أَجْنَاسُ الأَقْوَامِ"". 2. ""هُوَ مِنْ جِنْسٍ آخَرَ"" : مِنْ قَوْمِيَّةٍ أُخْرَى. 3.""الجِنْسُ اللَّطِيفُ"" : النِّسَاءُ. 4.""الجِنْسُ الخَشِنُ"" : الرِّجَالُ. 5.""مَارَسَ مَعَهَا الجِنْسَ"" : النِّكَاحَ، وَتُطْلَقُ كَلِمَةُ الجِنْسِ عَلَى مَا لَهُ عَلاَقَةٌ بِالوَظَائِفِ وَالأَعْضَاءِ التَّنَاسُلِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7597, 'أَجْنَاسٌ', 'أجناس', 'جامد', '', 'ءجناس', 'جنس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7598, 'جَنَانٌ', 'جنان', 'جامد', 'جنن', 'جنان', 'جنن', '', '', '', 'مفرد', 'DnN', '', '', '"أَجْنَانٌ"', '', 'R', '', '', '', '', '', '', '". 1.""جَنَانُ الْمَرْءِ"" : جَوْفُهُ، مَا بِدَاخِلِهِ وَمَا خَفِيَ مِنْهُ، القَلْبُ. ""إِذَا قَرِحَ الجَنَانُ بَكَتِ العَيْنَانِ"". (مثل). 2.""طَرَفُ الفَتَى يُخْبِرُ عَنْ جَنانِهِ"" : أي العَيْنانِ مِرْآةُ النَّفْسِ. 3.""ثَابِتُ الجَنَان"" : شُجُاعٌ، رَابِطُ الجَأْشِ. 4.""جَنَانُ اللَّيْلِ"" : شِدَّةُ ظُلْمَتِهِ. 5.""أَمْرٌ جَنَانٌ"" : خَفِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7599, 'أَجْنَانٌ', 'أجنان', 'جامد', '', 'ءجنان', 'جنن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7600, 'جَنِينٌ', 'جنين', 'جامد', 'جنن', 'جنين', 'جنن', '', '', '', 'مفرد', 'DnN', '', '', '"أَجِنَّةٌ"', '', 'R', '', '', '', '', '', '', '". ""جَنِينٌ فِي بَطْنِ أُمِّهِ"" : كَائِنٌ صَغِيرٌ فِي أَطْوَارِ النُّمُوِّ الأُولَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7601, 'أَجِنَّةٌ', 'أجنة', 'جامد', '', 'ءجنة', 'جنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7602, 'جِنِّيٌّ', 'جني', 'جامد', 'جني', 'جني', 'جن', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"جِنٌّ"', '', '', '', '', '', '', '', '', '". ""يَعْتَقِدُ أَنَّ جِنِّيّاً يَسْكُنُ البِئْرَ الْمَهْجُورَةَ"" : رُوحاً خَفِيَّةً عَكْسَ الإِنْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7603, 'جِنٌّ', 'جن', 'جامد', '', 'جن', 'جن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7604, 'مَجْنىً', 'مجنى', 'جامد', 'جني', 'مجنى', 'مجن', '', '', '', 'مفرد', 'Dy', '', '', '"مَجَانٍ(المجاني؟)"', '', '', '', '', '', '', '', '', '". 1.""مَجْنَى البَسَاتِينِ"": مَا يُجْنَى مِنَ الثِّمَارِ. 2.: الْمَوْضِعُ الَّذِي تُجْنَى فِيهِ الثِّمَارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7605, 'مَجْناةٌ', 'مجناة', 'جامد', 'جني', 'مجناة', 'مجنة', '', '', '', 'مفرد', 'DnN', '', '', '"مَجَانٍ(المجاني؟)"', '', '', '', '', '', '', '', '', '"مجناة. 1.""مَجْنَى البَسَاتِينِ"": مَا يُجْنَى مِنَ الثِّمَارِ. 2.: الْمَوْضِعُ الَّذِي تُجْنَى فِيهِ الثِّمَارُ."', '');
