INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7607, 'جِهْبِذٌ', 'جهبذ', 'جامد', '', 'جهبذ', 'جهبذ', '', '', '', 'جمع تكسير', 'DnN', '', '', '"جَهَابِذَةُ"', '', 'R', '', '', '', '', '', '', '"ج: جَهَابِذَةُ. ""عَالِمٌ جِهْبِذٌ مِنَ الجَهَابِذَةِ العِظَامِ"": العَارِفُ، الْمُتَضَلِّعُ مِنَ الْمَعَارِفِ، الخَبِيرُ النَّاقِدُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7608, 'جَهَابِذَةُ', 'جهابذة', 'جامد', '', 'جهابذة', 'جهبذة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7609, 'جُهْدٌ', 'جهد', 'جامد', 'جهد', 'جهد', 'جهد', '', '', '', 'مفرد', 'DnN', '', '', '"جُهُودٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَظْهَرَ جُهْداً بَالِغاً"" : طَاقَةً كَبِيرَةً، وُسْعاً.التوبة آية 79 وَالَّذِينَ لاَ يَجِدُونَ إِلاَّ جُهْدَهُمْ . (قرآن) ""سَعَى جُهْدَهُ لِيَسْتَغْنِيَ عَنْ غَيْرِهِ"" ""بَذَلَ جُهْدَ طَاقَتِهِ لِيَضْمَنَ عَيْشاً كَرِيماً لأَبْنَائهِ"" ""بَذَلَ جُهْدَ إِمْكَانِهِ لِيُقَدِّمَ لَهُ مُسَاعَدَةً"". 2. أَيُّ الصَّدَقَةِ أَفْضَل قَالَ: جُهْدُ الْمُقِلِّ . (حديث) : الشَّيْءُ القَلِيلُ الَّذِي يَعِيشُ بِهِ الفَقِيرُ، القَدْرُ الَّذِي يَحْتَمِلُ. 3.""بَذَلَ قُصَارَى جُهْدِهِ لإِعَانَتِهِ"" : أَقْصَى مَا يَمْلِكُ مِنْ قُدُرَاتٍ. ""هَذَا الجُهْدُ لاَ طَائِلَ تَحْتَهُ"" ""أَثْمَرَتْ جُهُودُهُ"" ""بَذَلَ جُهُوداً مَشْكُورَةً لِيُنْقِذَهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7610, 'جُهُودٌ', 'جهود', 'جامد', '', 'جهود', 'جهد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
