INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7612, 'مَجَاهِرُ', 'مجاهر', 'جامد', '', 'مجاهر', 'مجهر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7613, 'جِهَازٌ', 'جهاز', 'جامد', 'جهز', 'جهاز', 'جهز', '', '', '', 'مفرد', 'DnN', '', '', '"أَجْهِزَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""حَمَلَتِ العَرُوسُ جِهَازَهَا إِلَى بَيْتِ الزَّوْجِيَّةِ"" : كُلُّ مَا سَيَحْتَاجُهُ الزَّوْجَانِ مِنْ أَوَانٍ وَفِرَاشٍ وَأَقْمِشَةٍ، الخ. ""جِهَازُ الْمُسَافِرِ"". 2.""للإِنْسَانِ عِدَّةُ أَجْهِزَةٍ"" : ""الجِهَازُ الدَّمَوِيُّ"" وَ ""الجِهَازُ العَصَبِيُّ"" وَ ""الجِهَازُ الهَضْمِيُّ"" وَ""الجِهَازُ التَّنَفُّسِيُّ"" : أَيْ كُلَّ عُضْوٍ أَوْ أَعْضَاءٍ مُرَكَّبَةٍ تُؤَدِّي وَظِيفَةً مِنَ الأَجْهِزَةِ الْمَذْكُورَةِ .3.""أَجْهِزَةُ الدَّوْلَةِ"" : دَوَالِيبُهَا، أَيْ مَكَاتِبُهَا وَمَصَالِحُهَا. 4.""جِهَازُ التِّلْفَازِ"" : أَدَاتُهُ الْمُؤَدِّيَةُ لِوَظِيفَةٍ. ""اِمْتَلأَتِ الأَسْوَاقُ بِالأَجْهِزَةِ الإِلِكْتِرُونِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7614, 'أَجْهِزَةٌ', 'أجهزة', 'جامد', '', 'ءجهزة', 'جهزة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
