INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7616, 'مَجْهَلَةٌ', 'مجهلة', 'جامد', 'جهل', 'مجهلة', 'مجهلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَجْهَلَةٌ-مَجْهَلَةٌ [ج هـ ل]. ""وَلَدٌ مَجْهَلَةٌ"" : أَيْ يُحْمَلُ عَلَى الجَهْلِ. الوَلَدُ مَبْخَلَةٌ مَجْبَنَةٌ مَجْهَلَةٌ . (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7617, 'مَجْهَلٌ', 'مجهل', 'جامد', 'جهل', 'مجهل', 'مجهل', '', '', '', 'مفرد', 'DnN', '', '', '"مَجَاهِلُ"', '', 'R', '', '', '', '', '', '', '". ن. مَجَاهِلُ."', '');
