INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7620, 'جَوَادٌ', 'جواد', 'جامد', '', 'جواد', 'جد', '', '', '', 'جمع تكسير', 'DnN', '', '', '"جِيَادٌ:أَجْيَادٌ"', '', 'R', '', '', '', '', '', '', '"ج: جِيَادٌ، أَجْيَادٌ. 1.""رَكِبَ عَلَى ظَهْرِ جَوَادِهِ"" : عَلَى ظَهْرِ فَرَسِهِ. 2.""فَرَسٌ جَوَادٌ"" : سَرِيعُ الجَرْيِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7621, 'جِيَادٌ', 'جياد', 'جامد', '', 'جياد', 'جد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
