INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7623, 'جُوَالِقٌ', 'جوالق', 'جامد', '', 'جوالق', 'جلق', '', '', '', 'جمع تكسير', 'DnN', '', '', '"جَوَالِيقُ"', '', '', '', '', '', '', '', '', '"ج: جَوَالِيقُ. ""خَرَجَ وَعَلَى ظَهْرِهِ جُوَالِقٌ"" : جِرَابٌ كَبِيرٌ."', ':لا جذر:لا مفرد');
