INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7625, 'جَوَان', 'جوان', 'جامد', '', 'جوان', 'جن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ السَّادِسُ مِنَ الشُّهُورِ الغَرْبِيَّةِ الشَّمْسِيَّةِ، عَدَدُ أَيَّامِهِ (30) يَوْماً، يَأْتِي بَعْدَ مَايُو، أَيَّارَ، وَيَلِيهِ يوليوز، تَمُّوزُ. ن. حُزَيرَان."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7626, 'إِجَابَةٌ', 'إجابة', 'جامد', 'جوب', 'ءجابة', 'إجبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَجْوِبَةٌ"', '', 'R', '', '', '', '', '', '', '". ""أجابَ إِجابَةً مُخْتَصَرةً"" : أَي جَواباً ، رَدَّا. ""لَمْ تَكُنْ كُلُّ الإِجابات صَحِيحَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7627, 'أَجْوِبَةٌ', 'أجوبة', 'جامد', '', 'ءجوبة', 'جبة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7628, 'جَوَابٌ', 'جواب', 'جامد', 'جوب', 'جواب', 'جب', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَجْوِبَةٌ"', '', 'R', '', '', '', '', '', '', '". ""تَلَقَّى جَوَاباً عَنْ رِسَالَتِهِ"" : رَدّاً. ""إِنَّ لِكُلِّ خِطَابٍ جَوَاباً"" ""لَمْ يَجِدْ جَوَاباً لِسُؤَالِهِ"" ""الجَوَابُ مَا تَرَى لاَ مَا تَسْمَعُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7629, 'أَجْوِبَةٌ', 'أجوبة', 'جامد', '', 'ءجوبة', 'جبة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
