INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7631, 'جُوخٌ', 'جوخ', 'جامد', '', 'جوخ', 'جخ', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"أَجْوَاخٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَجْوَاخٌ. ""اِلْتَفَّ فِي جُوخٍ"" : غِطَاءٌ نَسِيجُهُ مِنْ صُوفٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7632, 'أَجْوَاخٌ', 'أجواخ', 'جامد', '', 'ءجواخ', 'جخ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7633, 'جُودٌ', 'جود', 'جامد', 'جود', 'جود', 'جد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جُودٌ-جُودٌ [ج و د]. ""عُرِفَ بِجُودِهِ"" : بِسَخَائِهِ، بِكَرَمِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7634, 'جُودُو', 'جودو', 'جامد', '', 'جودو', 'جد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": فَنٌّ مِنْ فُنُونِ الأَلْعَابِ الرِّيَاضِيَّةِ مِنْ أَصْلٍ يَابَانِيٍّ، قَائِمٌ عَلَى اسْتِخْدَامِ الأَيْدِي، وَهَدَفُهُ شَلُّ حَرَكَةِ الخَصْمِ أَوْ إِسْقَاطُهُ أَرْضاً أَوْ جَعْلُهُ يَفْقِدُ التَّوَازُنَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7635, 'جَارٌ', 'جار', 'جامد', 'جور', 'جار', 'جر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '":جِيرَانٌ"', '', 'R', '', '', '', '', '', '', '". 1.""يُعَامِلُ الجَارَ مُعَامَلَةً طَيِّبَةً"" : مَنْ يَسْكُنُ جَنْبَ مَنْزِلكِ، أَوْ يَجْلِسُ بِجَانِبِ مَقْعَدِكَ، الْمُجَاوِرُ لَكَ. "" اِسْأَلْ عَنِ الجَارِ قَبْلَ الدَّارِ"". (مَثَلٌ) ""كَانَتْ جَارَتَهُ فِي الحَارَةِ"" ""إِيَّاكِ أَعْنِي وَاسْمَعِي يَا جَارَةُ"". 2.""وَجَدَهُ جَاراً"" : مُجِيراً وَمُغِيثاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7636, 'جِيرَانٌ', 'جيران', 'جامد', '', 'جيران', 'جرن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7637, 'جَوْرَبٌ', 'جورب', 'جامد', '', 'جورب', 'جرب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"جَوَارِبُ"', '', 'R', '', '', '', '', '', '', '"ج: جَوَارِبُ. ""لَبِسَ جَوَارِبَهُ"" : مَا يُلْبَسُ فِي الأَرْجُلِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7638, 'جَوَارِبُ', 'جوارب', 'جامد', '', 'جوارب', 'جرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7639, 'جَائِزَةٌ', 'جائزة', 'جامد', 'جوز', 'جاءزة', 'جزة', '', '', '', 'مفرد', 'DnN', '', '', '"جَوَائِزُ"', '', '', '', '', '', '', '', '', '". ""كَانَتِ الجَائِزَةُ الأُولَى مِنْ نَصِيبِهِ"" : الْمُكَافَأَةُ وَالجَزَاءُ عَلَى عَمَلٍ مُمْتَازٍ أَوْ فَوْزٍ فِي مُسَابَقَةٍ مَّا، العَطِيَّةُ. ""وُزِّعَتِ الجَوَائِزُ فِي آخِرِ السَّنَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7640, 'جَوَائِزُ', 'جوائز', 'جامد', '', 'جواءز', 'جز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7641, 'مَجَازَةٌ', 'مجازة', 'جامد', 'جوز', 'مجازة', 'مجزة', '', '', '', 'مفرد', 'DnN', '', '', '"مَجَاوِزُ"', '', 'R', '', '', '', '', '', '', '". 1.""قَطَعَ الْمَجَازَةَ"" : طَرِيقٌ يُقْطَعُ مِنْ أَحَدِ جَانِبَيْهِ إِلَى الآخَرِ، مَعْبَرٌ. 2.""مَجَازَةُ النَّهْرِ"" : الْجِسْرُ. 3.""أَرْضٌ مَجَازَةٌ"" : كَثِيرَةُ الْجَوْزِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7642, 'مَجَاوِزُ', 'مجاوز', 'جامد', '', 'مجاوز', 'مجز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7643, 'مِجْوَزٌ', 'مجوز', 'جامد', 'جوز', 'مجوز', 'مجز', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِجْوَزٌ-مِجْوَزٌ [ج و ز] (مو).: آلَةٌ مُوسِيقِيَّةٌ مُكَوَّنَةٌ مِنْ قَصَبَتَيْنِ، يُنْفَخُ فِيهِمَا بِجَانِبِ قِرْبَةٍ بِهَا قَصَبَةٌ قَصِيرَةٌ يُنْفَخُ فِيهَا أَيْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7644, 'جَوْزٌ', 'جوز', 'جامد', '', 'جوز', 'جز', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَوْزٌ-جَوْزٌ، ةٌ (نب). 1.: شَجَرٌ مِنْ فَصِيلَةِ الجَوْزِيَّاتِ يُنْتِجُ ثَمَرَهُ دَاخِلَ مُجَفَّفٍ صَلْبٍ مُسْتَدِيرٍ، يُكَسَّرُ لإِخْرَاجِهَا، طَعْمُهُ لَذِيـذٌ. 2.: ثَمَرَةُ الجَوْزِ. 3.""جَوْزَةُ العُنُقِ"" : الغُضْرُوفُ الدَّرَقِيُّ عَلَى شَكْلِ نُتُوءٍ فِي مُقَدَّمِ العُنُقِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7645, 'جَوْزَاءُ', 'جوزاء', 'جامد', '', 'جوزاء', 'جز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', 'N', 'O', 'N', 'O', '', '"(فك).: بُرْجٌ مِنْ بُرُوجِ السَّمَاءِ يَتَّخِذُ شَكْلَ صُورَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7646, 'جَوْسَقٌ', 'جوسق', 'جامد', '', 'جوسق', 'جسق', '', '', '', 'جمع تكسير', 'DnN', '', '', '"جَواسِقُ:جَوَاسِيقُ"', '', 'R', '', '', '', '', '', '', '"ج: جَواسِقُ، جَوَاسِيقُ. 1.""تَحَصَّنَ بِالجَوْسَقِ"" : الحِصْنُ. 2.""يَسْكُنُ فِي جَوْسَقٍ"" : فِي قَصْرٍ صَغِيرٍ. 3.""جَوْسَقُ الشَّاطِئِ"": بَيْتٌ يُصْنَعُ مِنَ الخَشَبِ أَوْ نَحْوِهِ يُتَّخَذُ فِي حَمَّامَاتِ الشَّوَاطِئِ. 4.""جَوْسَقُ الجُنْدِيِّ"" : مَأْوَى الجُنْدِيِّ فِي الْمَنَاطِقِ النَّائِيَةِ، 5.""جَوْسَقُ الصُّحُفِ"" : الكِشْكُ. 6.""جَوْسَقُ السِّلَعِ"" : مَخْزَنٌ صَغِيرٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7647, 'جَواسِقُ', 'جواسق', 'جامد', '', 'جواسق', 'جسق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7648, 'جَوَاسِيقُ', 'جواسيق', 'جامد', '', 'جواسيق', 'جسق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7649, 'جُوعٌ', 'جوع', 'جامد', 'جوع', 'جوع', 'جع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جُوعٌ-جُوعٌ [ج و ع]. ""أَحَسَّ بِالجُوعِ"" : خُلُوُّ الْمَعِدَةِ مِنَ الطَّعَامِ، عَكْسُ الشِّبَعِ. ""مَنِ اتَّكَلَ عَلَى غَيْرِ نَفْسِهِ طَالَ جُوعُهُ"".(مثل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7650, 'جَوْفَاءُ', 'جوفاء', 'جامد', 'جوف', 'جوفاء', 'جف', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"جَوْفَاءُ-جَوْفَاءُ [ج و ف]. ""لاَحَظَ وُجُودَ أَشْجَارٍ جَوْفَاءَ فِي الغَابَةِ"" : فَارِغَةً مِنْ دَاخِلِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7651, 'جَوْقَةٌ', 'جوقة', 'جامد', 'جوق', 'جوقة', 'جقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""جَوْقَةٌ مِنَ النَّاسِ"" : جَمَاعَةٌ مِنْهُمْ. 2.""طَافَتْ جَوْقَةٌ عَسْكَرِيَّةٌ شَوَارِعَ الْمَدِينَةِ بِآلاَتِهَا الْمُوسِيقِيَّةِ"" : الفِرْقَةُ الغِنَائِيَّةُ، جَمَاعَةُ الفَنَّانِينَ يُؤَدُّونَ نَوْعاً مُشْتَرَكاً مِنَ الغِنَاءِ وَالعَزْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7652, 'جَوْقٌ', 'جوق', 'جامد', 'جوق', 'جوق', 'جق', '', '', '', 'مفرد', 'DnN', '', '', '"أَجْوَاقٌ"', '', 'R', '', '', '', '', '', '', '". 1.""تَجَمْهَرَ جَوْقٌ مِنَ النَّاسِ"": الْجَمَاعَةُ مِنَ النَّاسِ. 2.""قَدَّمَ الْجَوْقُ الوَطَنِيُّ مَقْطُوعَاتٍ مُوسِيقِيَّةً"" : جَمَاعَةٌ مِنَ الْمُوسِيقِيِّينَ يُقَدِّمُونَ فيِ آنٍ وَاحِدٍ أَنْغَاماً مُتَآلِفَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7653, 'أَجْوَاقٌ', 'أجواق', 'جامد', '', 'ءجواق', 'جق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7654, 'جَوْلَةٌ', 'جولة', 'جامد', 'جول', 'جولة', 'جلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَوْلَةٌ-جَوْلَةٌ [ج و ل]. 1.""قَامَ بِجَوْلَةٍ فِي الأَمَاكِنِ الأَثَرِيَّةِ "" : بِرِحْلَةٍ، بِاسْتِطْلاَعٍ. ""نُظِّمَتْ جَوْلَةٌ إِلَى الجَبَلِ"". 2.""اِنْتَهَتِ الجَوْلَةُ الأُولَى بِفَوْزِهِ"" : الشَّوْطُ الأَوَّلُ، الْمَرْحَلَةُ الأُولَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7655, 'جُولٌ', 'جول', 'جامد', 'جول', 'جول', 'جل', '', '', '', 'مفرد', 'DnN', '', '', '"أَجْوَالُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.: النَّاحِيَةُ. 2.: وَحْدَةٌ مِنَ العَمَلِ أَوِ الطاَّقَةِ أَوْ كَمِّيَّةِ الحَرَارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7656, 'أَجْوَالُ', 'أجوال', 'جامد', '', 'ءجوال', 'جل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7657, 'مَجَالٌ', 'مجال', 'جامد', 'جول', 'مجال', 'مجل', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""يَعْرِفُ مَجَالَ عَمَلِهِ"": أَيْ نِطَاقَهُ، مَدَاهُ. 2.""الْمَجَالُ الجَوِّيُّ"" : الفَضَاءُ. 3.""فِي هَذَا الْمَجَالِ"" : فِي هَذَا الصَّدَدِ. 4.""أَفْسَحَ لَهُ الْمَجَالَ"" : أَفْسَحَ لَهُ الطَّرِيقَ، أَعْطَاهُ الفُرْصَةَ. 5.""لَمْ يَتْرُكْ لَهُ مَجَالاً لِلْكَلاَمِ"" : حَيِّزاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7658, 'مِجْوَلٌ', 'مجول', 'جامد', 'جول', 'مجول', 'مجل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِجْوَلٌ-مِجْوَلٌ [ج و ل]. 1.""اِرْتَدَتِ المِجْوَلَ"" : لِبَاسٌ يُلْبَسُ فِي الْبَيْتِ. 2.""وَضَعَتِ الْمِجْوَلَ فِي رِجْلِهَا"" : الخَلْخَالَ. 3.:هِلاَلٌ مِنَ الفِضَّةِ وَسَطَ القِلاَدَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7659, 'دُوَّامَةٌ', 'دوامة', 'جامد', 'جوم', 'دوامة', 'دمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دُوَّامَةٌ-دُوَّامَةٌ [ج و م]. 1.""دُوَّامَةُ البَحْرِ"" : دائِرَةٌ تَدورُ عَلَيْها الأَمْواجُ بِشِدَّةٍ وَعُنْفٍ، أَعْلاها مُتَّسِعٌ وَأَسْفَلُها ضَيِّقٌ. 2.:خُذْروفٌ. ن. خُذْروفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7660, 'جَوْنٌ', 'جون', 'جامد', '', 'جون', 'جن', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"أَجْوَانٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَجْوَانٌ. 1.""ثَوْبٌ جَوْنٌ"" : أَسْوَدُ فِيهِ حُمْرَةٌ. تَقُولُ خَلِيلَتِي لَمَّا رَأَتْنِي*شَرِيحاً بَيْنَ مُبْيَضٍّ وَجَوْنِ. 2.""إِنَّ الشَّمْسَ جَوْنَةٌ"" : أَيْ بَيْضَاءُ. 3.""رَسَتِ السَّفِينَةُ فِي الجَوْنِ"" : فِي الخَلِيجِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7661, 'أَجْوَانٌ', 'أجوان', 'جامد', '', 'ءجوان', 'جن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7662, 'جَاهٌ', 'جاه', 'جامد', 'جوه', 'جاه', 'جه', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَاهٌ-جَاهٌ [ج و هـ]. ""يَتَمَتَّعُ بِالجَاهِ وَسَطَ قَوْمِهِ"" : بِمَكَانَةٍ وَعُلُوٍّ وَهِمَّةٍ، بِالشَّرَفِ وَالْمَنْزِلَةِ الرَّفِيعَةِ. ""هُوَ ذُو جَاهٍ وَسُلْطَةٍ"" ""ثُمَّ لاَ أَقْدِرُ عَلَى الاقْتِدَاءِ بِعِوَضٍ وَلاَ مَالٍ وَلاَ جَاهٍ وَلاَ عَوْنٍ"". (ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7663, 'مُجَوْهَرٌ', 'مجوهر', 'جامد', 'جوهر', 'مجوهر', 'مجهر', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". ""تَمْلِكُ مُجَوْهَرَاتٍ لَهَا قِيمَةٌ ثَمِينَةٌ"" : الحُلِيّ الْمُرَصَّعَةُ بِالأَحْجَارِ الكَرِيمَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7664, 'جَوْهَرٌ', 'جوهر', 'جامد', '', 'جوهر', 'جهر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"جَوَاهِرُ"', '', 'R', '', '', '', '', '', '', '"ج: جَوَاهِرُ. 1.""رَصَّعَتِ الفُسْتَانَ بِالجَوْهَرِ"" : حَجَرٌ كَرِيمٌ ثَمِينٌ. ""جَوْهَرَةٌ ثَمِينَةٌ"". 2.""جَوْهَرُ الْمَوْضُوعِ"" : طَبِيعَتُهُ الأَصْلِيَّةُ وَالأَسَاسِيُّ مِنْهُ. ""أَمَّا جَوْهَرُ الدِّينِ، فَظَلَّ سَاكِنًا فِي أَعْمَاقِ قَلْبِي"".(أحمد أمين). 3.""الْجَوْهَرُ الفَرْدُ"" : الجِسْمُ الصَّغِيرُ الَّذِي لاَ يَقْبَلُ الاِنْقِسَامَ وَهُوَ الذَّرَّةُ. 4.""الجَوَاهِرُ العُلْوِيَّةُ"" : الأَفْلاَكُ، الكَوَاكِبُ. 5.""الجَوَاهِرُ العُلْوِيَّةُ"" : الأَرْوَاحُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7665, 'جَوَاهِرُ', 'جواهر', 'جامد', '', 'جواهر', 'جهر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7666, 'جَوٌّ', 'جو', 'جامد', 'جوو', 'جو', 'ج', '', '', '', 'مفرد', 'DnN', '', '', '"أَجْوَاءٌ:جِوَاءٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِرْتَفَعَتِ الطَّائِرَةُ فِي الجَوِّ"": الْفَضَاءُ، أَيْ مَا بَيْنَ الأَرْضِ وَالسَّمَاءِ.النحل آية 79 أَلَمْ يَرَوْا إِلَى الطَّيْرِ مُسَخَّرَاتٍ فِي جَوِّ السَّمَاء . (قرآن). 2.""أَحْوَالُ الجَوِّ"": أَحْوَالُ الطَّقْسِ. ""جَوٌّ غَائِمٌ"" ""جَوٌّ مُتَقَلِّبٌ"". 3.""كَانَ جَوُّ البَيْتِ هَادِئاً"" : دَاخِلُهُ. 4.""جَوٌّ مُكَهْرَبٌ"" : مَا هُوَ سَائِدٌ فِي مَكَانٍ أَوْ ظَرْفٍ. 5.""سَافَرَ جَوّاً"" : فَضَاءً، أَيْ بِالطَّائِرَةِ. ""هَاجَمَ العَدُوُّ جَوّاً وَبَرّاً"". 6.""مَرَّ الحِوَارُ وَالتَّفَاوُضُ فِي جَوِّ الإِخَاءِ وَالوِفَاقِ"" : فِي إِطَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7667, 'أَجْوَاءٌ', 'أجواء', 'جامد', '', 'ءجواء', 'ج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7668, 'جِوَاءٌ', 'جواء', 'جامد', '', 'جواء', 'ج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7669, 'جَوَّةٌ', 'جوة', 'جامد', 'جوي', 'جوة', 'جة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"جَوَّةٌ-جَوَّةٌ [ج و ي]. 1.""جَوَّةُ الشَّيْءِ"" : بَاطِنُهُ. 2. : مَا اتَّسَعَ مِنَ الأَرْضِ وَانْخَفَضَ. 3. : القِطْعَةُ مِنَ الأَرْضِ فِيهَا غِلَظٌ، أَي الأَرْضُ الغَلِيظَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7670, 'جَيْبٌ', 'جيب', 'جامد', 'جيب', 'جيب', 'جب', '', '', '', 'مفرد', 'DnN', '', '', '"جُيُوبٌ"', '', 'R', '', '', '', '', '', '', '".1. ""أَخْرَجَ نُقُودًا مِنْ جَيْبِهِ"": كِيسٌ بِدَاخِلِ لِبَاسٍ مَّا أَوْ خَارِجَهُ فِي أَحَدِ جَوَانِبِهِ فَتْحَةٌ فِي الخَارِجِ. ""أَفْرَغَ كُلَّ مَا فِي جُيُوبِهِ"". 2.""جَيْبُ التَّمَام"" : هُوَ نِسْبَةُ الْمُجَاوِرِ إِلَى الوَتَرِ وَيُرْمَزُ إِلَيْهِ بِالرَّمْزِ: جتا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7671, 'جُيُوبٌ', 'جيوب', 'جامد', '', 'جيوب', 'جب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7672, 'جِيبُوتِي', 'جيبوتي', 'جامد', '', 'جيبوتي', 'جبت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": مِنَ البُلْدَانِ الأَعْضَاءِ فِي جَامِعَةِ الدُّوَلِ العَرَبِيّةِ، عَاصِمَتُهُا جِيبُوتِي."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7673, 'جِيدٌ', 'جيد', 'جامد', '', 'جيد', 'جد', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَجْيَادٌ:جُيُودٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَجْيَادٌ، جُيُودٌ. ""طَوِيلَةُ الجِيدِ"" : العُنُقِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7674, 'أَجْيَادٌ', 'أجياد', 'جامد', '', 'ءجياد', 'جد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7675, 'جُيُودٌ', 'جيود', 'جامد', '', 'جيود', 'جد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7676, 'جِيرٌ', 'جير', 'جامد', 'جير', 'جير', 'جر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جِيرٌ-جِيرٌ [ج ي ر]. ""طَلَى حِيطَانَ بَيْتِهِ بِالِجيِر"" : بِالْجِصِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7677, 'جَيْشٌ', 'جيش', 'جامد', 'جيش', 'جيش', 'جش', '', '', '', 'مفرد', 'DnN', '', '', '"جُيوشٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِنْخَرَطَ فِي الجَيْشِ"": فيِ سِلْكِ الجُندِيَّةِ، جَمَاعَةُ الجُنْدِ. ""قَامَتِ الجُيُوشُ الوَطَنِيَّةُ بِرَدِّ العُدْوَانِ"". 2.""نَاضَلَتِ الحَرَكَةُ الوَطَنِيَّةُ ضِدَّ جُيُوشِ الاحْتِلاَلِ"" : الق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7678, 'جُيوشٌ', 'جيوش', 'جامد', '', 'جيوش', 'جش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7679, 'جِيفَةٌ', 'جيفة', 'جامد', 'جيف', 'جيفة', 'جفة', '', '', '', 'مفرد', 'DnN', '', '', '"جِيَفٌ:أَجْيَافٌ"', '', 'R', '', '', '', '', '', '', '". ""تَجَمَّعَتِ الصُّقُورُ تَنْهَشُ الجِيفَةَ"" : جُثَّةُ الْمَيِّتِ إِذَا أَنْتَنَتْ."', '');
