INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7682, 'جِيلٌ', 'جيل', 'جامد', 'جيل', 'جيل', 'جل', '', '', '', 'مفرد', 'DnN', '', '', '"أَجْيَالٌ"', '', 'R', '', '', '', '', '', '', '". 1.""جِيلُ العَرَبِ"" : أُمَّةُ العَرَبِ. ""جِيلُ التُّرْكِ"" ""جِيلُ الغَجَرِ"". 2.""مَرَّ عَلَيْهِ جِيلٌ مِنَ الزَّمَانِ"" : قَرْنٌ مِنَ الزَّمَانِ. 3.""عَرَفَ الجيلُ الْمُعَاصِرُ وَيْلاَتِ الحَرْبِ"" : أَهْلُ الزَّمَانِ الوَاحِدِ، وَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7683, 'أَجْيَالٌ', 'أجيال', 'جامد', '', 'ءجيال', 'جل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7684, 'جِيلاَتِين', 'جيلاتين', 'جامد', '', 'جيلاتين', 'جلتن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": مَادَّةٌ شِبْهُ زُلاَلِيَّةٍ لَيِّنَةٌ لَزِجَةٌ تُسْتَعْمَلُ فِي بَعْضِ الأَطْعِمَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7685, 'جَيْهَلٌ', 'جيهل', 'جامد', '', 'جيهل', 'جهل', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"1.""حَرَّكَ الجَمْرَ بِالْجَيْهَلِ"" : أَدَاةٌ مِنْ خَشَبٍ أَوْ حَدِيدٍ يُحَرَّكُ بِهَا الجَمْرُ. 2.""صَخْرَةٌ جَيْهَلٌ"" : عَظِيمَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7686, 'جِيُوفِيزِيَاء', 'جيوفيزياء', 'جامد', '', 'جيوفيزياء', 'جفز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rz', '', 'N', 'O', 'N', 'O', '', '": عِلْمٌ يَبْحَثُ وَيَدْرُسُ تَكْوِينَ الكُرَةِ الأَرْضِيَّةِ وَالحَرَكَاتِ الفَاعِلَةَ فِيهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7687, 'حاجِبَةٌ', 'حاجبة', 'جامد', '', 'حاجبة', 'حجبة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"1.""تَمْشي وَهِيَ حاجِبَةٌ وَجْهَها"" : ساتِرَةٌ. 2.""وَضَعَ حاجِبَةَ الضَّوْءِ بِجانِبِ سَريرِهِ"" : مِصْباحٌ ضَوْئِيٌّ مُغَطّىً لِتَكْثيفِ الضَّوْءِ حَوْل"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7688, 'حاف', 'حاف', 'جامد', '', 'حاف', 'حف', '', '', '', 'جمع تكسير', '', '', '', '"مثنىافانِ-الْحافانِ"', '', 'R', '', '', '', '', '', '', '"""حافا اللِّسانِ"" : عِرْقانِ أَخْضَرانِ تَحْتَ اللِّسانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7689, 'حافِرِيَّاتٌ', 'حافريات', 'جامد', '', 'حافريات', 'حفرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصيلَةٌ حَيَوانِيَّةٌ مِنْ مُفْرَداتِ الأصابِعِ وَمُزْدَوِجاتِ الأصابِعِ والخرطومِيَّاتِ، تَشْمَلُ ذَواتَ الخُفِّ وَذَواتَ الظِّلْفِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7690, 'حاقولٌ', 'حاقول', 'جامد', '', 'حاقول', 'حقل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": سَمَكٌ أَخْضَرُ طَويلُ المِنْقارِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7691, 'حالَةٌ', 'حالة', 'جامد', '', 'حالة', 'حلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. 1.""وَجَدْتُهُ في حالَةٍ يُرْثَى لَها"" : في وَضْعِيَّة، الحال. ""تَبْعَثُ حالَتُهُ على القَلَقِ"" ""حالَتُهُ سَيِّئَةٌ"" ""الحالَةُ الصِّحِّيَّةُ"" ""الحالَةُ الاجْتِماعِيَّةُ"" ""الحالَةُ الاقْتِصادِيَّةُ"". 2.""في الحالَةِ الرَّاهِنَةِ"" : في الوَقْتِ الحاضِرِ. 3.""في حالَةِ غِيابِهِ سَأَجْلِسُ مَكانَهُ"" : عِنْدَ غِيابِهِ. ""في حالَةِ الوَفاةِ"". 4.""وَالحالَةُ هَذِهِ لا أَمْلِكُ جَواباً"" : في هَذا الظَّرْفِ، والأُمورُ كَما هِيَ. 5.""في هَذِهِ ال"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7692, 'حَبٌّ', 'حب', 'جامد', '', 'حب', 'حب', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '":حُبوبٌ:حُبَّانٌ"', '', 'R', '', '', '', '', '', '', '"ج: حُبوبٌ، حُبَّانٌ، حَبَّاتٌ. 1.""حَبُّ القَمْحِ"" : ما يَكونُ بِداخِلِ السُّنْبُلَةِ، البِزْرُ. 2.""حَبُّ الغَمامِ"" : البَرَدُ. 3.""حَبَّاتُ الْمِسْبَحَةُ"" :كُراتٌ صَغيرَةٌ مِنْ مادَّةٍ مَّا. ""حَبَّةُ العِنَبِ"" ""حَبَّاتُ الرَّمْلِ"" ""حَبَّاتُ العِقْدِ"". 4.""حَبَّةُ الأَوْزانِ"": مِقْدارُ شَعيرَتَيْنِ. 5.""حَبَّةُ العَيْنِ"" : م"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7693, 'حُبوبٌ', 'حبوب', 'جامد', '', 'حبوب', 'حبب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7694, 'حُبَّانٌ', 'حبان', 'جامد', '', 'حبان', 'حبن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7695, 'حُبابَةٌ', 'حبابة', 'جامد', '', 'حبابة', 'حببة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. حُبابٌ. 1.""أَضاءتْ حُبابَةُ الضَّوْءِ البَيْتَ"" : المِصْباحُ الضَّوْئِيُّ. 2.: دابَّةٌ مائِيَّةٌ صَغيرَةٌ سَوْداءُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7696, 'حُباحِبٌ', 'حباحب', 'جامد', '', 'حباحب', 'حبحب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1.: خُنْفُساءُ مُغَمَّدَةُ الأَجْنِحَةِ، تَطيرُ في اللَّيْلِ، لَها ذَنَبٌ مُشِعٌّ كالسِّراجِ. 2.""نارُ الحُباحِبِ"" : ما يَتَطايَرُ مِنْ شَرَرِ النَّارِ. 3.""أُمُّ حُباحِبَ"" : حَشَرَةٌ مِثْلُ الجُنْدُبِ مُخْتَلِفَةُ الألْوانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7697, 'حَبَّارٌ', 'حبار', 'جامد', '', 'حبار', 'حبر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَبَّارٌ-حَبَّارٌ (حو).: مِنْ فَصيلَةِ الرَّخْوِيَّاتِ، مِنْ رُتْبَةِ رَأْسِيَّةِ القدَمِ، بَيْضَوِيُّ الشَّكْلِ، مُغَطّىً بِغِلافٍ صَدَفِيٍّ، يُفْرِزُ سائِلاً أَسْوَدَ يُسْتَعْمَلُ للصِّباغَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7698, 'حُبارَى', 'حبارى', 'جامد', '', 'حبارى', 'حبر', '', '', '', 'جمع تكسير', 'Dy', '', '', '"حُبارِياتٌ(للذَّكَرِوالأُنْثَ', 'ممنوع من الصرف', 'R0', '', '', '', '', '', '', '"ج: حُبارِياتٌ. (حو) (للذَّكَرِ والأُنْثَى، والجَمْعُ فيهِ سَواءٌ). 1.: طَائِرٌ مِنْ فَصيلَةِ الحُبارِيَّاتِ، مِنْ رُتْبَةِ الطَويلاتِ السَّاقِ، سَمينٌ بِحَجْمِ الإِوَزَّةِ، طَويلُ العُنُقِ والذَّنَـبِ، غَليـظ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7699, 'حُبارِياتٌ', 'حباريات', 'جامد', '', 'حباريات', 'حبرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7700, 'حُبارِيَّاتٌ', 'حباريات', 'جامد', '', 'حباريات', 'حبرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصيلَةُ طَيْرٍ مِنْ رُتْبَةِ الطَّويلاتِ السَّاقِ، من أَشْهَرِها الحُبارَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7701, 'حَبابٌ', 'حباب', 'جامد', 'حبب', 'حباب', 'حبب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَبابٌ-حَبابٌ [ح ب ب]. ""يَعْلُو البُحَيْرَةَ الحَبابُ"" : الحَبَبُ، الفَقاقيعُ الَّتِي تَطْفُو على سَطْحِ الماءِ أَوْ في كَأْسِ عَصيرٍ. ""طَفا الحَبابُ على الشَّرابِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7702, 'حَبَبٌ', 'حبب', 'جامد', 'حبب', 'حبب', 'حب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَبَبٌ-حَبَبٌ [ح ب ب]. ""عَلاَ الماءَ حَبَبٌ"" : فَقاقيعُ تَطْفُو على سَطْحِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7703, 'حَبَّةٌ', 'حبة', 'جامد', '', 'حبة', 'حبة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ن. حَبٌّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7704, 'حَبْرَةٌ', 'حبرة', 'جامد', 'حبر', 'حبرة', 'حبرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حَبْرَةٌ-حَبْرَةٌ [ح ب ر]. 1.""هُوَ في حَبْرَةٍ"" : في سُرورٍ، في سَعَةِ عَيْشٍ ونِعْمَةٍ. 2.""حَبْرَةُ الأَسْنانِ"" : الصُّفْرَةُ التي تَعْلوها."', '');
