INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7747, 'حَبْوَةٌ', 'حبوة', 'جامد', 'حبو', 'حبوة', 'حبة', '', '', '', 'مفرد', 'DnN', '', '', '"حُبىً"', '', 'R', '', '', '', '', '', '', '". 1.""اِرْتَدَتْ حَبْوَةً"" : ما يُحْتَبَى بِهِ، أيْ ما يُشْتَمَلُ بِهِ مِنْ ثَوْبٍ وَغَيْرِهِ. 2.""سَلَّمَهُ حَبْوَةً"" : عَطِيَّةً."', '');
