INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7750, 'حَتاتٌ', 'حتات', 'جامد', '', 'حتات', 'حتت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""حَتاتُ الصُّخورِ"" : فُتاتُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7751, 'حَتْفٌ', 'حتف', 'جامد', '', 'حتف', 'حتف', '', '', '', 'جمع تكسير', 'DnN', '', '', '"حُتوفٌ"', '', 'R', '', '', '', '', '', '', '"ج: حُتوفٌ. 1.""ماتَ حَتْفَ أَنْفِهِ"" : ماتَ مَوْتَةً طَبيعِيَّةً. لَـوْ عَلِمْتُ بِأَنَّ حَتْفِـي*كَحَتْفِ أَبِي بِلالٍ لَمْ أُبال (عِمْرانُ بن حِطَّان). 2.""لَقِيَ حَتْفَهُ في حادِثَةِ سَيَّارَةٍ"" : لَقِيَ مَوْتَهُ. ""سَعَى إلى حَتْفِهِ بِظِلْفِهِ""(مثل) : يُضْرَبُ لِمَنْ يَحْفِرُ قَبْرَهُ بِنَفْسِهِ ""كالباحِثِ عَنْ حَتْفِهِ بِظِلْفِهِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7752, 'حُتوفٌ', 'حتوف', 'جامد', '', 'حتوف', 'حتف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7753, 'حُثالَةٌ', 'حثالة', 'جامد', 'حثل', 'حثالة', 'حثلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""بَقِيَتْ في الغِرْبالِ حُثالَةُ الشَّعيرِ"" : قِشْرُهُ، نُفايَتُهُ. 2.""حُثالَةُ الزَّيْتِ"" : ثُفْلُهُ. ""حُثالَةُ الكَأْسِ"". 3.""إِنَّهُ مِنْ حُثالَةِ النَّاسِ"" : مِنْ أَراذِلِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7754, 'حِجاً', 'حجا', 'جامد', '', 'حجا', 'حج', '', '', '', 'جمع تكسير', '', '', '', '"أَحْجاءٌ"', '', '', '', '', '', '', '', '', '"ج: أَحْجاءٌ. ""رَجُلٌ ذو حِجاً"" : ذُو عَقْلٍ وَرَجاحَةِ رَأْيٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7755, 'أَحْجاءُ', 'أحجاء', 'جامد', '', 'ءحجاء', 'حج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7756, 'حِجابَةٌ', 'حجابة', 'جامد', 'حجب', 'حجابة', 'حجبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حِجابَةٌ-حِجابَةٌ [ح ج ب]. ""يَتَوَلَّى مِهْنَةَ الحِجابَةِ أَباً عَنْ جَدٍّ"": مِهْنَة الحاجِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7757, 'حِجابٌ', 'حجاب', 'جامد', 'حجب', 'حجاب', 'حجب', '', '', '', 'مفرد', 'DnN', '', '', '"حُجُبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَزالَتِ الحِجابَ عَنْ وَجْهِها : النِّقابَ، الخِمارَ. 2.""تَتَكَلَّمُ مِنْ وَراءِ حِجابٍ"" : مِنْ وَراءِ سِتْرٍ. 3.""كَتَبَ لَها الفَقيهُ حِجاباً"" : تَعْويذَةً، رُقْيَةً، حِرْزاً. 4.""حِجابُ القَلْبِ"" : غِلافٌ يَحْجُبُ بَيْنَ القَلْبِ وَالبَطْنِ. 5.""كَيْفَ لَهُ أَنْ يَخْتَرِقَ حُجُبَ الغَيْبِ"" : مَا يَفْصِلُ بَيْنَ عَالَمَيْنِ. 6.""حِجَابُ الحَاجِزِ"" : عَضَلَةٌ عَرِيضَةٌ تَفْصِلُ بَيْنَ الصَّدْرِ وَالبَطْنِ. 7.""حِجَابُ الشَّمْسِ"" : ضَوْؤُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7758, 'حُجُبٌ', 'حجب', 'جامد', '', 'حجب', 'حجب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
