INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7766, 'حُجَّةٌ', 'حجة', 'جامد', 'حجج', 'حجة', 'حجة', '', '', '', 'مفرد', 'DnN', '', '', '"حُجَجٌ"', '', 'R', '', '', '', '', '', '', '". 1.""قَدَّمَ لَهُ حُجَّةً مُقْنِعَةً"": بُرْهاناً، دَليلاً. ""لَمْ تَكُنْ حُجَجُهُ مُقْنِعَةً"". 2.""لَمْ يُدْلِ بِأَيِّ حُجَّةٍ"" : بِأَيِّ اعْتِذارٍ. 3.""حُجَّةُ البَيْعِ"" : صَكُّ البَيْعِ."', '');
