INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7768, 'مَحَجَّةٌ', 'محجة', 'جامد', 'حجج', 'محجة', 'محجة', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَاجُّ"', '', 'R', '', '', '', '', '', '', '". 1.""مَحَجَّةُ الطَّرِيقِ"" : جَادَّتُهُ، وَسَطُهُ. 2.""مَحَجَّةُ الصَّوَابِ"" : الطَّرِيقُ الْمُسْتَقِيمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7769, 'مَحَاجُّ', 'محاج', 'جامد', '', 'محاج', 'محج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7770, 'مَحَجٌّ', 'محج', 'جامد', 'حجج', 'محج', 'محج', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَاجُّ"', '', 'R', '', '', '', '', '', '', '". ""جَعَلُوا مِنْ قَبْرِ الوَلِيِّ مَحَجَّهُمْ"" : الْمَكَانُ الَّذِي يُحَجُّ إِلَيْهِ لِلتَّبَرُّكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7771, 'مَحَاجُّ', 'محاج', 'جامد', '', 'محاج', 'محج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7772, 'حِجارَةٌ', 'حجارة', 'جامد', 'حجر', 'حجارة', 'حجرة', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حِجارَةٌ-حِجارَةٌ [ح ج ر]. 1.""رَماهُ بِالحِجارَةِ"" : بِالحَصَى. 2.""زَعْزَعَ أَطْفالُ الحِجارَةِ الكِيانَ الصُّهْيونِيَّ"" : ثَوْرَةُ الشَّعْبِ الفِلِسْطينِيِّ الَّتِي عِمادُها رَمْيُ أَطْفالِهِ العَدُوَّ بِالحَجَرِ. ""السَّلامُ على كُلِّ طِفْلٍ تَعَلَّمَ كَيْفَ يَصوغُ الحِجارَةَ"".(محمد القيسي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7773, 'حُجُراتٌ', 'حجرات', 'جامد', 'حجر', 'حجرات', 'حجرت', '', '', '', 'مفرد', '', '', '', '"مفردحُجْرَة"', '', '', '', '', '', '', '', '', '". 1.الحجرات آية 4 إِنَّ الَّذِينَ يُنادونَكَ من وراءِ الحُجُراتِ . (قرآن) : غُرَفُ نِساءِ الرَّسُولِ(. 2.: سورَةٌ مِن سُوَرِ القُرْآنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7774, 'حُجْرَةٌ', 'حجرة', 'جامد', 'حجر', 'حجرة', 'حجرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""حُجْرَةُ الدَّرْسِ"" : غُرْفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7775, 'حَجَرٌ', 'حجر', 'جامد', 'حجر', 'حجر', 'حجر', '', '', '', 'مفرد', 'DnN', '', '', '"أَحْجارٌ:حِجارَةٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""بَنَى دارَهُ بِأَحْجارٍ صَخْرِيَّةٍ"" : بِحَصىً صَخْرِيَّةٍ. 2.""يَبْنونَ بُيوتَهُمْ بِحَجَرِ الجيرِ"" : حَجَر الكَلْسِ. 3.""يَتَّجِرُ في الحَجَرِ الكَريمِ"" : في مَعْدِنِ الماسِ والزُّمُرُّدِ والجَواهِرِ والياقُوتِ. 4.""قَبَّلَ الحَجَرَ الأَسْوَدَ"": حَجَرُ الكَعْبَةِ الْمُشَرَّفَةِ. 6.""حَجَرُ الزَّاوِيَةِ"" : الرُّكْنُ الأَساسِيُّ في عَمَلٍ مَّا. 7.""وَضَعَ حَجَرَ الأَساسِ لِبِناءِ أَكْبَرِ سَدٍّ"" : أَوَّلَ حَصاةٍ، طِينٌ يَضَعُهُ مَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7776, 'أَحْجارٌ', 'أحجار', 'جامد', '', 'ءحجار', 'حجر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
