INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7778, 'مَحْجَرٌ', 'محجر', 'جامد', 'حجر', 'محجر', 'محجر', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَاجِرُ"', '', 'R', '', '', '', '', '', '', '". 1.: كُلُّ مَا لَهُ حُرْمَةٌ. 2.""مَكَثَ فِي الْمَحْجَرِ يَنْحَتُ الحِجَارَةَ"" : مَكَانُ نَحْتِ الحِجَارَةَ. 3.""الْمَحْجَرُ الصِّحِّيُّ"" : مَلْجَأٌ خَاصٌّ بِالْمُصَابِينَ بِالأَمْرَاضِ الْمُعْدِيَةِ يُقِيمُونَ فِيهِ مَنْعاً لانْتِشَارِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7779, 'مَحَاجِرُ', 'محاجر', 'جامد', '', 'محاجر', 'محجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7780, 'مَحْجِرٌ', 'محجر', 'جامد', 'حجر', 'محجر', 'محجر', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَاجِرُ"', '', 'R', '', '', '', '', '', '', '". ""مَحْجِرُ العَيْنِ"" : مَا أَحَاطَ بِهَا. ""فِي مَحْجِرَيْهَا يَتَجَمَّدُ الدَّمْعُ وَالتَّعَبُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7781, 'مَحَاجِرُ', 'محاجر', 'جامد', '', 'محاجر', 'محجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7782, 'حُجْزَةٌ', 'حجزة', 'جامد', 'حجز', 'حجزة', 'حجزة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حُجَزٌ"', '', 'R', '', '', '', '', '', '', '". ""حُجْزَةُ السِّرْوالِ"" : مَوْضِعُ الحِزامِ، مَعْقِدُ الإِزارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7783, 'حُجَزٌ', 'حجز', 'جامد', '', 'حجز', 'حجز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7784, 'حَجَلَةٌ', 'حجلة', 'جامد', 'حجل', 'حجلة', 'حجلة', '', '', '', 'مفرد', 'DnN', '', '', '"حِجالٌواحِدَةُالحَجَلِ"', '', 'R', '', '', '', '', '', '', '". 1.""رَبَّاتُ الحِجالِ"" : النِّساءُ. 2.: مَوْضِعٌ لِلْعَروسِ يُزَيَّنُ بِالثِّيابِ والسُّتُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7785, 'حِجالٌ', 'حجال', 'جامد', '', 'حجال', 'حجل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7786, 'حَجَلٌ', 'حجل', 'جامد', '', 'حجل', 'حجل', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"حِجْلانٌ"', '', 'R', '', '', '', '', '', '', '"ج: حِجْلانٌ. (حو).: طَائِرٌ مِنْ فَصيلَةِ التَّدْرُجِيَّاتِ، مِنْ رُتْبَةِ الدَّجاجِيّاتِ، رَمادِيُّ اللَّوْنِ، أَحْمَرُ المِنْقارِ والسَّاقَيْنِ، وَهُوَ في حَجْمِ الحَمامِ. جَرْيُهُ رَشيقٌ، وَطَعْمُ لَحْمِهِ لَذِيذٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7787, 'حِجْلانٌ', 'حجلان', 'جامد', '', 'حجلان', 'حجلن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7788, 'حِجَامَةٌ', 'حجامة', 'جامد', 'حجم', 'حجامة', 'حجمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حِجَامَةٌ-حِجَامَةٌ [ح ج م]. ""الحِجامَةُ مِنَ المِهَنِ التَّقْليدِيَّةِ"" : الْمُداواةُ بِالمِحْجَمِ والْمُعالَجَةُ بِهِ، اِسْتِخْراجُ دَمِ الْمَريضِ، فَصْدُهُ بِواسِطَةِ آلَةٍ تُشْبِهُ كَأْساً مُقَوَّسَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7789, 'حِجامٌ', 'حجام', 'جامد', 'حجم', 'حجام', 'حجم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حِجامٌ-حِجامٌ [ح ج م]. ""حِجامُ الكَلْبِ"" : جِلْدَةٌ تُوضَعُ في فَمِ الكَلْبِ أَوْ أَيِّ حَيَوانٍ لِمَنْعِهِ مِنَ العَضِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7790, 'أُحْجِيَّةٌ', 'أحجية', 'جامد', 'حجو', 'ءحجية', 'حجة', '', '', '', 'مفرد', 'DnN', '', '', '"أَحاجٍ:أَحَاجِيُّ"', '', '', '', '', '', '', '', '', '". ""تَحْكي لَهُ أُحْجِيَّةً فِي كُلِّ مَسَاءٍ"" : لُغْزاً، يَنْبَغِي إِعْمَالُ الفِكْرِ فِيهِ لِفَكِّ عُقْدَتِهِ، أوْ كَلِمَاتٍ يَتَحَاجَى بِهَا النَّاسُ وَتَتَضَمَّنُ عُقْدَةً وَمَعْنىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7791, 'أَحَاجِي', 'أحاجي', 'جامد', '', 'ءحاجي', 'حج', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7792, 'أَحَاجِيُّ', 'أحاجي', 'جامد', 'حجي', 'ءحاجي', 'حج', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَحَاجِيُّ-أَحَاجِيُّ [ح ج ي]. ن. أُحْجِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7793, 'حَدَأَةٌ', 'حدأة', 'جامد', '', 'حدءة', 'حدة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"حَدَأٌ:حِداءٌ"', '', 'Rz', '', '', '', '', '', '', '"ج: حَدَأٌ، حِداءٌ. 1.""يَشُقُّ الخَشَبَ بِالحَدأَةِ"" : فَأْسٌ ذاتُ رَأْسَيْنِ. 2.حَدَأَةُ الفَأْسِ"" : رَأْسُها الحادُّ، نَصْلُهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7794, 'حَدَأٌ', 'حدأ', 'جامد', '', 'حدء', 'حد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7795, 'حِداءٌ', 'حداء', 'جامد', '', 'حداء', 'حد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7796, 'أَحْدَاثٌ', 'أحداث', 'جامد', 'حدث', 'ءحداث', 'حدث', '', '', '', 'مفرد', '', '', '', '"مفردحَدَث"', '', '', '', '', '', '', '', '', '". ن. حَدَثٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7797, 'أُحْدُوثَةٌ', 'أحدوثة', 'جامد', 'حدث', 'ءحدوثة', 'حدثة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"أُحْدُوثَةٌ-أُحْدُوثَةٌ [ح د ث]. 1. ""تَروِي لأطْفَالِهَا أُحْدُوثَةً فِي كُلِّ مَسَاءٍ"": حِكَايَةً قَصِيرَةً. 2. ""حُسْنُ الأحْدُوثَةِ"" : الْمَدِيحُ وَالثَّنَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7798, 'حَدَثٌ', 'حدث', 'جامد', 'حدث', 'حدث', 'حدث', '', '', '', 'مفرد', 'DnN', '', '', '"أَحْداثٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هَذا حَدَثٌ لا قِبَلَ لَنا بِهِ"" : الْمُنْكَرُ، البِدْعَةُ، أَيْ ما لَمْ يَكُنْ مَعْروفاً. 2.""أَفْعالُ الحَدَثِ"" : أَفْعالُ صَغيرِ السِّنِّ. 3.""أَحْداثُ الدَّهْرِ"" : مَصائِبُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7799, 'أَحْداثٌ', 'أحداث', 'جامد', '', 'ءحداث', 'حدث', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7800, 'حُدوثَةٌ', 'حدوثة', 'جامد', 'حدث', 'حدوثة', 'حدثة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حُدوثَةٌ-حُدوثَةٌ [ح د ث]. ""حُدوثَةُ شَيْءٍ"" : أَوَّلُها، اِبْتِداؤُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7801, 'حَديثٌ', 'حديث', 'جامد', 'حدث', 'حديث', 'حدث', '', '', '', 'مفرد', 'DnN', '', '', '"أَحادِيثُ"', '', 'R', '', '', '', '', '', '', '". 1.""حَديثٌ نَبَوِيٌّ"": قَوْلَةٌ مِنْ أَقْوالِ النَّبِيِّ (. ""عِلْمُ الحَديثِ"" : هُوَ عِلْمٌ إِسْلامِيٌّ يَخْتَصُّ بِرِوايَةِ وَرُواةِ أَحاديثِ النَّبِيِّ( وَأَقْوالِه. ""رِجالُ الحَديثِ"" ""يُثَقَّفُ... الطَّالِبُ ثَقافَةً دينِيَّةً مِنْ تَفْسيرٍ وَحَديثٍ وَفِقْهٍ وَأُصولِ فِقْهٍ وَتَوْحيدٍ""(أ. أمين). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7802, 'أَحادِيثُ', 'أحاديث', 'جامد', '', 'ءحاديث', 'حدث', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7803, 'حَديثٌ', 'حديث', 'جامد', 'حدث', 'حديث', 'حدث', '', '', '', 'مفرد', 'DnN', '', '', '"حِداثٌ"', '', 'R', '', '', '', '', '', '', '". 1.""ما يَزالُ حَديثَ السِّنِّ"" : صَغيراً. 2.""هُوَ حَديثُ العَهْدِ بالعَمَلِ"" : أَيْ بَدَأَهُ مُنْذُ عَهْدٍ قَريبٍ. ""حَديثُ العَهْدِ بِالتَّدْريسِ"". 3.""حَديثُ غِنىً"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7804, 'حِداثٌ', 'حداث', 'جامد', '', 'حداث', 'حدث', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7805, 'حِدادَةٌ', 'حدادة', 'جامد', 'حدد', 'حدادة', 'حددة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حِدادَةٌ-حِدادَةٌ [ح د د]. ""يَتَعاطَى مِهْنَةَ الحِدادَةِ"" : مِهْنَة الحَدَّادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7806, 'حَديدَةٌ', 'حديدة', 'جامد', 'حدد', 'حديدة', 'حددة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حَدائِدُ"', '', 'R', '', '', '', '', '', '', '". 1.: القِطْعَةُ مِنَ الحَديدِ. 2.""حَديدَةُ المِحْراثِ"" : السِّكَّةُ الَّتِي يُحْرَثُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7807, 'حَدائِدُ', 'حدائد', 'جامد', '', 'حداءد', 'حدد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7808, 'حَدَقَهٌ', 'حدقه', 'جامد', 'حدق', 'حدقه', 'حدقه', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حَدَقٌ:حِدَاقٌ:جأَحْدَاقٌ"', '', 'R', '', '', '', '', '', '', '". ""حَدَقَةُ العَيْنِ"" : السَّوادُ الْمُحيطُ بِوَسَطِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7809, 'حَدَقٌ', 'حدق', 'جامد', '', 'حدق', 'حدق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
