INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7811, 'أَحْدَاقٌ', 'أحداق', 'جامد', '', 'ءحداق', 'حدق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7812, 'حَديقَةٌ', 'حديقة', 'جامد', 'حدق', 'حديقة', 'حدقة', '', '', '', 'مفرد', 'DnN', '', '', '"حَدائِقُ"', '', '', '', '', '', '', '', '', '". 1.""يَتَنَزَّهُ في الحَديقَةِ العُمومِيَّةِ"" : بُسْتانٌ بِه زُهورٌ وَأَشْجارٌ مُحاطٌ بِجِدارٍ أَوْ سِياجٍ، رَوْضَةٌ. 2.""حَديقَةُ الحَيَواناتِ"" : غابَةٌ صَغيرَةٌ مُحاطَةٌ، تَوَضَعُ فيها مُخْتَلِفُ الحَيَواناتِ داخِلَ حَواجِزَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7813, 'حَدائِقُ', 'حدائق', 'جامد', '', 'حداءق', 'حدق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7814, 'مِحْدَلَةٌ', 'محدلة', 'جامد', 'حدل', 'محدلة', 'محدلة', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَادِلُ"', '', 'R', '', '', '', '', '', '', '". 1.: سَيَّارَةٌ ذَاتُ مَقْعَدٍ عَالٍ مُرْتَفِعٍ، لَهَا عَجَلاَتٌ مُسْتَدِيرَةٌ عَرِيضَةٌ وَضَخْمَةٌ مِنَ الْحَدِيدِ يُرَصَّصُ بِهَا حِجَارَةُ الطُّـرُقِ وَطَبَقَاتُهَـا الزِّفْتِيَّةُ. 2. : خَشَبَةٌ قَصيرَةٌ مُسْتَديرَةٌ لِبَسْطِ عجين الحَلْوَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7815, 'مَحَادِلُ', 'محادل', 'جامد', '', 'محادل', 'محدل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7816, 'حَدَمَةٌ', 'حدمة', 'جامد', 'حدم', 'حدمة', 'حدمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَدَمَةٌ-حَدَمَةٌ [ح د م]. ""حَدَمَةُ النَّارِ"" : شِدَّةَ الْتِهابِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7817, 'حُدَمَةٌ', 'حدمة', 'جامد', 'حدم', 'حدمة', 'حدمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '".: طَنْجَرَةٌ مَعْدِنِيَّةٌ لَها غِطاءٌ يُحْكَمُ إِغْلاقَهُ عِنْدَ وَضْعِ ما يُرادُ طَبْخُهُ، بِهِ ثُقْبَةٌ يَعْلوها سَدّادٌ يُديرُهُ ضَغْطُ البُخارِ مِمَّا يُحْدِثُ صَفيراً، تُنْضِجُ الأَطْعِمَةَ في دَقائِقَ مَعْدودَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7818, 'حادِي', 'حادي', 'جامد', 'حدو', 'حادي', 'حد', '', 'Tk', '', 'مفرد', 'DnN', '', '', '"حُداةٌ"', '', '', '', '', '', '', '', '', '". 1.""سارَ الحادي وَراءَ إِبِلِهِ في تِلْكَ اللَّيْلَةِ الْمُقْمِرَةِ وَهُوَ يُغَنِّي"" : سائِقُ الإِبِلِ. 2.""الحادي عَشَرَ(11) مَقْلوبٌ عَنْ واحِدٍ في العَدَدِ التَّرْتيبِيِّ. ""الحادِي والعِشْرونَ (21)"". 3.""حادِي النَّجْمِ"" (فك) : كَوْكَبانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7819, 'حُداةٌ', 'حداة', 'جامد', '', 'حداة', 'حدة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7820, 'حُداءٌ', 'حداء', 'جامد', 'حدو', 'حداء', 'حد', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"حُداءٌ-حُداءٌ [ح د و]. ""ما أَعْذَبَ حُداءَ الحادِي"" : غِناءَ سائِقِ الإِبِلِ بِهِ يَحُثُّها على السَّيْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7821, 'حَديدٌ', 'حديد', 'جامد', '', 'حديد', 'حدد', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَحِدَّاءُ"', '', 'Rp', '', '', '', '', '', '', '"ج: أَحِدَّاءُ. 1.: مَعْدِنٌ صَلْبٌ يُتَّخَذُ في الصِّناعَةِ. 2.""سِكَّةُ الحَديدِ"" : قُضْبانٌ مَعْدِنِيَّةٌ يَسيرُ عَلَيْها القِطارُ. 3.""الحَديدُ بِالحَديدِ يُفْلَحُ"" : أَيْ لا يَقْطَعُ ما هُوَ مَعْدِنِيٌّ إِلاَّ الْمَعْدِنُ. 4.""رَجُلٌ حَديدُ الطَّبْعِ"" : ذُو حِدَّةٍ. 5.""مُكَبَّلٌ بِالحَديدِ"": بِالأغْلالِ والسَّلاسِلِ. ""أَنْزَلوهُ إلى أَعْماقِ الظُّلْمَةِ وَكَبَّلوهُ بِالحَديدِ"".(جبران خ. جبران)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7822, 'أَحِدَّاءُ', 'أحداء', 'جامد', '', 'ءحداء', 'حد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7823, 'حَذافيرُ', 'حذافير', 'جامد', 'حذفر', 'حذافير', 'حذفر', '', '', '', 'مفرد', '', '', '', '"مفردحِذْفار:حُذْفور"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""أَخَذَهُ بِحَذَافيرِهِ"" : أَخَذَهُ كُلَّهُ، بِأَسْرِهِ، أَيْ لَمْ يَتْرُكْ مِنْهُ شَيْئاً. ""رَوَى الخَبَرَ بِحَذافِيرِهِ"" ""اِمْرَأَةٌ تَتَمَثَّلُ فيها الأُنوثَةُ بِحَذافِيرِها"" (ع. م. العقاد)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7824, 'حِذْفارٌ', 'حذفار', 'جامد', 'حذفر', 'حذفار', 'حذفر', '', '', '', 'مفرد', '‎DnN', '', '', '"‎حَذافيرُ"', '', 'R', '', '', '', '', '', '', '". ""بَلَغَ الماءُ حِذْفارَ الحَقْلِ"" : جانِبَهُ، ناحِيَتَهُ. ن.حَذافيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7825, 'حذافير', 'حذافير', 'جامد', '', 'حذافير', 'حذفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
