INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7827, 'حذافير', 'حذافير', 'جامد', '', 'حذافير', 'حذفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7828, 'حِذاءٌ', 'حذاء', 'جامد', 'حذو', 'حذاء', 'حذ', '', '', '', 'مفرد', 'Dz', '', '', '"أَحْذِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '". 1.""اِنْتَعَلَ حِذاءً جَديداً"" : نَعْلاً. 2.""جَلَسْتُ بِحِذائِهِ"" : بِإزائِهِ. ""جَلَسَ حِذاءهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7829, 'أَحْذِيَةٌ', 'أحذية', 'جامد', '', 'ءحذية', 'حذة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7830, 'حَرَّابَةٌ', 'حرابة', 'جامد', 'حرب', 'حرابة', 'حربة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حَرَّابَةٌ-حَرَّابَةٌ [ح ر ب]. 1.""كَتِيبَةٌ حَرَّابَةٌ"" : كَثيرَةُ السَّلْبِ. 2.""اِمْرَأَةٌ حَرَّابَةٌ"" : دَسَّاسَةٌ، مُثيرَةٌ لِلْفِتَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7831, 'حِرْباءُ', 'حرباء', 'جامد', 'حرب', 'حرباء', 'حرب', '', '', '', 'مفرد', 'Dz', '', '', '"حَرابِيُّ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"(حو).: حَيَوَانٌ مِنْ فَصيلَةِ الحِرْباوِيَّاتِ، مِنْ رُتْبَةِ العَظايا، مِنْ صِنْفِ الزَّواحِفِ، لَها ذَنَبٌ طَويلٌ قادِرٌ على الالْتِفافِ على أَغْصانِ الأشْجارِ، لَهـا قُدْرَةٌ على تَغْيِيرِ لَوْنِها حَسَبَ اللَّوْنِ الَّذِي تَطَأُهُ، تَقْتاتُ مِنَ الحَشَراتِ والْهَوامِّ. 2.""مُتَقَلِّبٌ كالحِرْباءِ""(مثل) : يُقالُ لِمَنْ لا يَثْبُتُ على حالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7832, 'حَرابِيُّ', 'حرابي', 'جامد', '', 'حرابي', 'حرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7833, 'حَرْبَةٌ', 'حربة', 'جامد', 'حرب', 'حربة', 'حربة', '', '', '', 'مفرد', 'DnN', '', '', '"حِرابٌ"', '', 'R', '', '', '', '', '', '', '". ""طَعَنَهُ بِحَرْبَةٍ"" : آلَةُ حَرْبٍ مِنْ حَديدٍ قَصيرَةٌ مُحَدَّدَةُ الرَّأْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7834, 'مِحْرَابٌ', 'محراب', 'جامد', 'حرب', 'محراب', 'محرب', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَارِيبُ"', '', 'R', '', '', '', '', '', '', '". 1.""جَلَسَ فِي مِحْرَابِ الْمَجْلِسِ"" : فِي صَدْرِهِ. 2.""مِحْرَابُ الْمَسْجِدِ"" : مَقَامُ الإِمَامِ. ""صَعِدَ الخَطِيبُ المِحْرَابَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7835, 'مَحَارِيبُ', 'محاريب', 'جامد', '', 'محاريب', 'محرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7836, 'حِرْباوِيَّاتٌ', 'حرباويات', 'جامد', '', 'حرباويات', 'حربت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"حِرْباوِيَّاتٌ-حِرْباوِيَّاتٌ (حو).: فَصيلَةُ حَيَواناتٍ مِنَ الزَّواحِفِ، مِنْ رُتْبَةِ العَظائِيَّاتِ، أَشْهَرُ أَنْواعِها الحِرْباءُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7837, 'حِراثَةٌ', 'حراثة', 'جامد', 'حرث', 'حراثة', 'حرثة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حِراثَةٌ-حِراثَةٌ [ح ر ث]. 1.""يَتَهَيَّأُونَ لِحِراثَةِ الأَرْضِ"" : لِشَقِّ الأرْضِ وَتَهِيئَتِها لِلزِّراعَةِ. 2.""يَكْسِبُ عَيْشَهُ مِنَ الحِراثَةِ"" : حِرْفَةُ الحَرَّاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7838, 'حَرَجَةٌ', 'حرجة', 'جامد', 'حرج', 'حرجة', 'حرجة', '', '', '', 'مفرد', 'DnN', '', '', '"أَحْراجٌ"', '', 'R', '', '', '', '', '', '', '". ""اِخْتَبَأَ في الحَرَجَةِ"" : ما اجْتَمَعَ وَالْتَفَّ مِنَ الأشْجارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7839, 'أَحْراجٌ', 'أحراج', 'جامد', '', 'ءحراج', 'حرج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7840, 'حِرْجٌ', 'حرج', 'جامد', 'حرج', 'حرج', 'حرج', '', '', '', 'مفرد', 'DnN', '', '', '"حِراجٌ:أَحْراجٌ:حَرَجَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَقَعَ في حِرْجٍ"" : في إِثْمٍ. 2.""حِرْجُ الصَّائِدِ"" : حِبالَتُهُ، مِصْيَدَتُهُ. 3.""حِرْجُ الرَّاعِي"" : جَماعَةُ غَنَمِهِ"". 4.""حِرْجُ الحَيَوانِ"" : قِلادَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7841, 'حِراجٌ', 'حراج', 'جامد', '', 'حراج', 'حرج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
