INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7844, 'حَرِيدٌ', 'حريد', 'جامد', 'حرد', 'حريد', 'حرد', '', '', '', 'مفرد', 'DnN', '', '', '"حِرادٌ:حُرَدَاءُ"', '', 'R', '', '', '', '', '', '', '". 1. ""وَلَدٌ حَرِيدٌ"" : مُنْعَزِلٌ مُتَفَرِّدٌ عَنِ النَّاسِ، فَرِيدٌ، وَحِيدٌ. 2. ""كَوْكَبٌ حَرِيدٌ"" : مُعْتَزِلٌ عَنِ الكَوَاكِب."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7845, 'حِرادٌ', 'حراد', 'جامد', '', 'حراد', 'حرد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7846, 'حُرَدَاءُ', 'حرداء', 'جامد', '', 'حرداء', 'حرد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7847, 'حِرْذَوْنٌ', 'حرذون', 'جامد', '', 'حرذون', 'حرذن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"حَرَاذِينُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: حَرَاذِينُ. (حو).: دابَّةٌ صَغيرَةٌ مِنْ فَصيلَةِ الحِرْذَوْنِيَّاتِ، مِنْ رُتْبَةِ العَظائِيَّاتِ، تُشْبِهُ الحِرْباءَ، أَيْ مِنَ الزَّواحفِ، تَعيشُ في الْمَناطِقِ الحارَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7848, 'حَرَاذِينُ', 'حراذين', 'جامد', '', 'حراذين', 'حرذن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7849, 'حِرْذَوْنِيَّاتٌ', 'حرذونيات', 'جامد', '', 'حرذونيات', 'حرذنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فصيلَةُ حَيَواناتٍ مِنْ رُتْبَةِ العَظائِيَّاتِ، وَهِيَ مِنَ الزَّواحِفِ، مِنْ بَيْنِها الحِرْذَوْنُ والضَّبُّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7850, 'حُرٌّ', 'حر', 'جامد', 'حرر', 'حر', 'حر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '":أَحْرارٌ:حَرائِرُ"', '', '', '', '', '', '', '', '', '". 1.""أَصْبَحَ حُرّاً"" : تَحَرَّرَ بَعْدَما كانَ عَبْداً. 2.""هُوَ حُرٌّ في جَميعِ تَصَرُّفاتِهِ"": يَتَصَرَّفُ بِلا قَيْدٍ أَوْ ضابِطٍ. ""الحُرُّ حُرٌّ وَلَوْ مَسَّهُ الضُّرُّ"". 3.""اِمْرَأَةٌ حُرَّةٌ"" : طَليقَةٌ، أو كَريمَةٌ. 4.""حُرَّةُ الشَّهْرِ"" : أَوَّلُ لَيْلَةٍ مِنَ الشَّهْرِ. 5.""رَمْلَةٌ حُرَّةٌ"" : لا طِينَ فيها. 6.""سَحابَةٌ حُرَّةٌ"" : كَثيرَةُ الْمَطَرِ. 7.""ناضَلَتِ البِلادُ العَرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7851, 'أَحْرارٌ', 'أحرار', 'جامد', '', 'ءحرار', 'حرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7852, 'حَرائِرُ', 'حرائر', 'جامد', '', 'حراءر', 'حرر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7853, 'حَرُورٌ', 'حرور', 'جامد', 'حرر', 'حرور', 'حرر', '', '', '', 'مفرد', 'DnN', '', '', '"حَرَائِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""حَرُورُ الشَّمْسِ"" : حَرُّهَا. فاطر آية 21وَمَا يَسْتَوِي الأعْمَى وَالبَصِيرُ وَلاَ الظُّلُماتُ وَلاَ النُّورُ، وَلاَ الظِّلُّ وَلاَ الْحَرُورُ (قرآن). 2.""حَرُورُ النَّارِ"" : شِدَّةُ حَرَارَتِهَا. 3.""بَلَدٌ حَرُورٌ"" : حَرُّهُ دَائِمٌ. 4.""أشْعَلَ الحَرورَ"" : النَّارَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7854, 'حَرَائِرُ', 'حرائر', 'جامد', '', 'حراءر', 'حرر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7855, 'حُرِّيَّةٌ', 'حرية', 'جامد', 'حرر', 'حرية', 'حرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""حَقَّقَ الشَّعْبُ حُرِّيَّتَهُ"": أصْبَحَ سَيِّدَ أُمُورِهِ يُسَيِّرُهَا وَيُمَارِسُهَا كَمَا يُرِيدُ، التَّخَلُّصُ مِنَ السَّيْطَرَةِ الأجْنَبِيَّةِ. 2.""مِنْ حُقُوقِ الإنْسَانِ أنْ يَتَمَتَّعَ كُلُّ مَوَاطِنٍ بِحُرِّيَّةِ التَّجَوُّلِ وَحُرِّيَّةِ الرَّأْيِ وَحُرِّيَّةِ الاعْتِقَادِ وَحُرِّيَّةِ التَّعْبِيرِ"" : حَقُّهُ فِي اخْتِيَارِ مَا يُرِيدُ حَسَبَ اعْتِقَادِهِ، اِقْتِنَاعِهِ. أ. ""الحُرِّيَّةُ الفَرْدِيَّةُ"" : ما يَنْبَغِي أَنْ يَتَمَتَّعَ بِهِ الْمُواطِنُ مِنَ الحُقوقِ الْمَدَنِيَّةِ الَّتِي يُخَوِّلُها لَهُ القانونُ. ب. ""الحُرِّيَّةُ السِّي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7856, 'حَرَّى', 'حرى', 'جامد', 'حرر', 'حرى', 'حر', '', '', '', 'مفرد', '', '', '', '"مفردحَرَّان"', 'ممنوع من الصرف', 'RwR0', '', 'N', 'N', 'N', 'N', '', '". 1.""زَفَراتٌ حَرَّى"" : شَديدَةُ اللَّوْعَةِ. 2.""يَسْكُبُ دُموعاً حَرَّى"" : حارَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7857, 'حَرَّان', 'حران', 'جامد', '', 'حران', 'حرن', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', 'N', 'N', 'N', 'N', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7858, 'حَرِيرَةٌ', 'حريرة', 'جامد', 'حرر', 'حريرة', 'حررة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حَرِيرَةٌ-حَرِيرَةٌ [ح ر ر]. 1. ""حَرِيرَةُ ثَوْبٍ"" : القِطْعَةُ مِنَ الحَرِيرِ. 2. ""يَشْرَبُ الحَرِيرَةَ فِي كُلِّ مَساءٍ"" : حِسَاءٌ مِنْ دَقِيقٍ وَمَاءٍ وَقَطانِيَّاتٍ أوْ خُضَرٍ. ""شُرْبَةُ الحَرِيرَةِ مْن أَطْعِمَةِ شَهْرِ رَمَضَانَ بِالْمَغْرِبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7859, 'حَرِيرٌ', 'حرير', 'جامد', 'حرر', 'حرير', 'حرر', '', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"حَرِيرٌ-حَرِيرٌ [ح ر ر]. ""تَلْبَسُ قَمِيصاً مِنْ حَرِيرٍ"" : نَسِيجٌ نَاعِمٌ مِنْ خُيوطٍ دَقِيقَةٍ تُفْرِزُهَا دُودَةُ القَزِّ"". ""نُرَبِّي دُودَ الحَرِيرِ وَنحْصُلُ عَلَى مَوْسِمِ القَزِّ"" (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7860, 'مِحْرَارٌ', 'محرار', 'جامد', 'حرر', 'محرار', 'محرر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '".: مِيزَانُ الْحَرَارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7861, 'حِرْزٌ', 'حرز', 'جامد', 'حرز', 'حرز', 'حرز', '', '', '', 'مفرد', 'DnN', '', '', '"أَحْرازٌ"', '', 'R', '', '', '', '', '', '', '". 1.""كَتَبَ لَها الْمُشَعْوِذُ حِرْزاً"" : أَيْ تَعْويذَةً، رُقْيَةً تَقِي حامِلَها مِنَ الشَّرِّ والْمَرَضِ كَما يَزْعُمونَ. 2.""وَضَعَتْ جَواهِرَها في حِر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7862, 'أَحْرازٌ', 'أحراز', 'جامد', '', 'ءحراز', 'حرز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7863, 'حَرِيزٌ', 'حريز', 'جامد', 'حرز', 'حريز', 'حرز', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَرِيزٌ-حَرِيزٌ [ح ر ز]. 1. ""حِرْزٌ حَرِيزٌ"" : حصينٌ. 2. ""هُوَ حَرِيزُ الأمْرِ"" : نَزِيهٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7864, 'حَرْشَفٌ', 'حرشف', 'جامد', '', 'حرشف', 'حرشف', '', '', '', 'جمع تكسير', 'DnN', '', '', '"حَراشِفُ"', '', 'R', '', '', '', '', '', '', '"ج: حَراشِفُ. ن. خَرْشوفٌ."', ':لا جذر:لا مفرد');
