INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7869, 'حَرِيفٌ', 'حريف', 'جامد', 'حرف', 'حريف', 'حرف', '', '', '', 'مفرد', 'DnN', '', '', '"حُرَفاءُ"', '', 'R', '', '', '', '', '', '', '". ""حَرِيفُ الرَّجُلِ"": مُعامِلُهُ فِي حِرْفَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7870, 'حُرَفاءُ', 'حرفاء', 'جامد', '', 'حرفاء', 'حرف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7871, 'حارِقَةٌ', 'حارقة', 'جامد', 'حرق', 'حارقة', 'حرقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حارِقَةٌ-حارِقَةٌ [ح ر ق]. 1.""أُصيبَ في الحارِقَةِ"" : العَصَبَةُ التي تَجْمَعُ بَيْنَ رَأْسِ الفَخِذِ والوَرِكِ وَهُما حارِقَتانِ. 2.: السَّبُعُ. 3.""اِمْرَأَةٌ حارِقَةٌ"" : تُكْثِرُ سَبَّ جاراتِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7872, 'حَرَّاقَةٌ', 'حراقة', 'جامد', 'حرق', 'حراقة', 'حرقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حَرَّاقَةٌ-حَرَّاقَةٌ [ح ر ق]. ""تَوالَتْ قَذائِفُ الحَرَّاقَةِ"" : السَّفينَةِ التي تَقْذِفُ القَذائِفَ والنِّيرانَ في البَحْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7873, 'حُرْقَةٌ', 'حرقة', 'جامد', 'حرق', 'حرقة', 'حرقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حُرْقَةٌ-حُرْقَةٌ [ح ر ق]. 1. ""أصَابَتْهُ حُرْقَةٌ"" : أثَرُ الاِحْتِراقِ. 2.""فِي لِسَانِهِ حُرْقَةٌ"" : لَذْعَةُ الطَّعْمِ. ""حُرْقَةُ اللِّسَانِ"". 3.""شَعَرَ بِحُرْقَةٍ تَضْطَرِمُ فِي جَوَارِحِهِ"" : شِدَّةُ الحُزْنِ وَلَذْعَتُهُ. 4.""حُرْقَةُ الجَوِّ"" : حَرَارَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7874, 'حَرِيقَةٌ', 'حريقة', 'جامد', 'حرق', 'حريقة', 'حرقة', '', '', '', 'مفرد', 'DnN', '', '', '"حَرَائِقُ"', '', '', '', '', '', '', '', '', '". 1. ""اِشْتَدَّتِ الحَرِيقَةُ"": الحَرَارَةُ. 2. ""تَنَاوَلَ حَرِيقَةً"" : نَوْعٌ غَلِيظٌ مِنَ الحَسَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7875, 'حَرَائِقُ', 'حرائق', 'جامد', '', 'حراءق', 'حرق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7876, 'حَرْقَفَةٌ', 'حرقفة', 'جامد', '', 'حرقفة', 'حرقفة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"حَرَاقِفُ"', '', 'R', '', '', '', '', '', '', '"ج : حَرَاقِفُ.: رَأْسُ عَظْمِ الوَرِكِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7877, 'حَرَاقِفُ', 'حراقف', 'جامد', '', 'حراقف', 'حرقف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7878, 'حَراكٌ', 'حراك', 'جامد', 'حرك', 'حراك', 'حرك', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَراكٌ-حَراكٌ [ح ر ك]. ""لَمْ يَأْتِ بِحَراكٍ"" : بِحَرَكَةٍ. ""ما بِهِ حَراكٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7879, 'حَرَكَةٌ', 'حركة', 'جامد', 'حرك', 'حركة', 'حركة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""لَمْ تَهْدَأْ حَرَكَةُ الْمُرُورِ"" : عَمَلِيَّةُ الْمُرُورِ. 2.""لاَ يَتَوقَّفُ عَنِ الحَرَكَةِ"" : فِي عَمَلٍ دَائِمٍ، يَنْتَقِلُ مِنْ مَكَانٍ إلَى آخَرَ. 3.""يَمُوجُ السُّوقُ بِحَرَكَةٍ صَاخِبَةٍ"" ‎: بِعَمَلٍ، بِنَشَاطٍ. 4.""يُلازِمُهُ فِي حَرَكَاتِهِ وسَكَنَاتِهِ"" : فِي كُلِّ مَا يَعْمَلُ. 5.""وَجَدَهُ خَفِيفَ الحَرَكَةِ"" : نَشِيطاً فِي عَمَلَهِ. 6.""ثَقِيلُ الحَرَكَةِ"" : كَسُولٌ، خَامِدٌ، ثَقِيلُ الدَّمِ. 7.""رَجُلٌ شَدِيدُ الحَرَكَةِ"": الْمُتَيَقِّظُ. 8.""تَسِيرُ الكَواكِبُ وَالنُّجُومُ فِي حَرَكَةٍ مُنْتَظِمَةٍ"" : فِي دَوْرَةٍ، فِي سَيْرٍ. 9.""عَرَفَتِ البِلاَدُ حَرَكَةً ثَقَافِيَّةً"": نَشَاطاً وأعْمَالاً ثَقافِيَّةً. ""حَرَكَةٌ سِيَاسِيَّةٌ، نِقَابِيَّةٌ، فِكْرِيَّةٌ"". 10.""نَشَأتِ الحَرَكَةُ الوَطَنِيَّةُ لِتَحْرِيرِ البِلاَدِ مِنَ السَّيْطَرَةِ الأجْنَبِيَّةِ"" : مَجْمُوعَةُ العَمَلِ الوَطَنِيِّ. 11.""الحَرَكَةُ فِي النَّحْوِ"" : الضَّمَّةُ أوِ الفَتْحَةُ أوِ الكَسْرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7880, 'مِحْرَاكٌ', 'محراك', 'جامد', 'حرك', 'محراك', 'محرك', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِحْرَاكٌ-مِحْرَاكٌ [ح ر ك]. ""مِحْراكُ النَّارِ"": قَضِيبٌ مِنْ حَدِيدٍ تُحَرَّكُ بِهِالنَّارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7881, 'حَرامٌ', 'حرام', 'جامد', 'حرم', 'حرام', 'حرم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَرامٌ-حَرامٌ [ح ر م]. 1.""حَرامٌ علَيْكَ أَنْ تَأْكُلَ أَمْوالَ اليَتامَى"" : مَمْنوعٌ عَلَيْكَ... لا يَجوزُ لَكَ. 2.""حَرامُ اللَّهِ لَنْ أَرْتَكِبَ ما حَرَّمَ اللَّهُ"" : يَمينُ اللَّهِ لَنْ... 3.""الشَّهْرُ الحَرامُ"" : واحِدُ الأَشْهُرِ الأرْبَعَةِ : ذُو القِعْدَةِ، وَذو الحِجَّةِ والْمُحَرَّمُ وَرَجَبٌ. 4.الإسراء آية 1 سُبْحانَ الَّذِي أَسْرَى بِعَبْدِهِ لَيْلاً مِنَ الْمَسْجِدِ الحَرامِ إلى الْمَسْجِدِ الأقْصَى (قرآن) : الكَعْبَةُ بِمَكَّةَ الْمُكَرَّمَةَ. ""البَيْتُ الحَرامُ"". 5.""البَلَدُ الحَرامُ"" : مَكَّةُ. 6.""هُوَ ابنُ حَرامٍ"" : اِبْنٌ غَيْرُ شَرْعِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7882, 'حُرُمَةٌ', 'حرمة', 'جامد', 'حرم', 'حرمة', 'حرمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حُرَمٌ"', '', 'R', '', '', '', '', '', '', '". ن. حُرْمَة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7883, 'حُرَمٌ', 'حرم', 'جامد', '', 'حرم', 'حرم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7884, 'حُرْمَةٌ', 'حرمة', 'جامد', 'حرم', 'حرمة', 'حرمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حُرَمٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِنْتَهَكَ حُرْمَةَ مَسْكَنِهِ"" : حَصَانَتُهُ، مَا لاَ يَحِلُّ انْتِهَاكُهُ. 2.""يُحَافِظُ الرَّجُلُ عَلَى حُرْمَتِهِ"" : عَلَى أهْلِهِ أَوِ امْرَأَتِهِ. 3.""يُرَاعِي حُرْمَةَ الدِّينِ"" : مَا يَجِبُ القِيامُ بِهِ مِنْ حُقُوقِ الدِّينِ وَعَدَمِ التَّفْرِيطِ فِيهَا. 4. ""لَهُ حُرْمَةٌ فِي بِلاَدِهِ"" : مَهَابَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7885, 'حُرَمٌ', 'حرم', 'جامد', '', 'حرم', 'حرم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7886, 'حُرُمٌ', 'حرم', 'جامد', 'حرم', 'حرم', 'حرم', '', '', '', 'مفرد', '', '', '', '"مفردحِرْم"', '', 'R', '', '', '', '', '', '', '". ""الأَشْهُرُ الحُرُمُ"" : ذو القِعْدَةِ، وَذُو الحِجَّةِ ومُحَرَّمٌ وَرَجَبٌ، وَهِي أَشْهُرٌ كانَ العَرَبُ يُحَرِّمونَ فيها القِتالَ. التوبة آية 5 فَإِذا انْسَلَخَ الأَشْهُرُ الحُرُمُ فاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُموهُمْ .(قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7887, 'مَحْرَمَةٌ', 'محرمة', 'جامد', 'حرم', 'محرمة', 'محرمة', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَارِمُ"', '', 'R', '', '', '', '', '', '', '". 1.: مَا لاَ يَحِلُّ انْتِهَاكُهُ. 2.""مَحْرَمَةُ الرَّجُلِ"" : زَوْجَتُهُ وَعِيَالُهُ وَمَا يَحْمِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7888, 'مَحَارِمُ', 'محارم', 'جامد', '', 'محارم', 'محرم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7889, 'مَحْرَمٌ', 'محرم', 'جامد', 'حرم', 'محرم', 'محرم', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَارِمُ"', '', 'R', '', '', '', '', '', '', '". 1.:مَا حَرَّمَ اللهُ، أَيِ الْحَرَامُ. 2.""إِنَّهَا مَحْرَمٌ لَهُ"" : القَرِيبَةُ الَّذِي يَحْرُمُ التَّزَوُّجُ بِهَا نِهَائِيّاً لِرَحِمِهَا وَقَرَابَتِهَا. ""إِنَّهُ مَحْرَمٌ لَهَا"". 3.""مَحَارِمُ اللَّيْلِ"": مَخَاوِفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7890, 'مَحَارِمُ', 'محارم', 'جامد', '', 'محارم', 'محرم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7891, 'مِحْرَمٌ', 'محرم', 'جامد', 'حرم', 'محرم', 'محرم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مُحْرِمٌ-مُحْرِمٌ [ح ر م] (فَا. مِنْ أَحْرَمَ). 1.""هُوَ مُحْرِمُكَ"" : أَيْ فِي حِمَايَتِكَ. 2.""رَجُلٌ مُحْرِمٌ"" : مُسَالِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7892, 'حَرَمٌ', 'حرم', 'جامد', '', 'حرم', 'حرم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"مثنىحَرَمَانِ-حَرَمَانِ"', '', 'R', '', '', '', '', '', '', '": مَكَّةُ الْمُكَرَّمَةُ وَالْمَدِينَةُ الْمُنَوَّرَةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7893, 'حَرْمَلٌ', 'حرمل', 'جامد', '', 'حرمل', 'حرمل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَرْمَلٌ-حَرْمَلٌ (نب).: نَبَاتٌ مِنْ فَصِيلَةِ السَّذابِيَّاتِ، عُشْبِيٌّ عَطِرٌ، يَنْبُتُ فِي الْمَنَاطِقِ الرَّمْلِيَّةِ الحَارَّةِ، حَبُّهُ صَغِيرٌ أسْوَدُ، لَهُ فَوَائِدُ طِبِّيَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7894, 'حِزْبٌ', 'حزب', 'جامد', 'حزب', 'حزب', 'حزب', '', '', '', 'مفرد', 'DnN', '', '', '"أحْزَابٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""رَتَّلَ حِزْباً مِنَ القُرْآنِ"" : آيَات قُرْآنِيَّة تُكَوِّنُ قِسْمَاً مِنْهُ. ""فِي القُرآنِ سِتُّونَ حِزْباً"". 2.""تَكَوَّنَ حِزْبٌ سِيَاسِيُّ جَدِيدٌ"" : جَمَاعَةٌ مِنَ النَّاسِ تُشَكِّلُ قُوَّةً تَلْتَقِي حَوْلَ أهْدَافٍ مُشْتَرَكَةٍ، تَشَاكَلَتْ طُمُوحَاتُهُمْ وَأعْمَالُهُمْ وَمُيُولُهُمْ. ""حِزْبُ الاسْتِقْلالِ"" ""الحِزْبُ الوَطَنِيُّ"" ""الحِزْبُ الشُّيُوعِيُّ"" ""الْحِزْبُ الاشْتِرَاكِيُّ"". 3.""حِزْبُ الرَّجُلِ"" : أعْوَانُهُ، مُؤَيِّدُوهُ، جُنْدُهُ. المجادلة آية 22 أُولَئِكَ حِزْبُ اللَّهِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7895, 'أحْزَابٌ', 'أحزاب', 'جامد', '', 'ءحزاب', 'حزب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7896, 'حَزَازَةٌ', 'حزازة', 'جامد', 'حزز', 'حزازة', 'حززة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""حَزَازَةُ القَلْبِ"": وَجَعٌ فِي القَلْبِ مِنْ جَرَّاءِ غَيْظٍ أوْ حُرْقَةٍ. 2.""في نَفْسِهِ حَزَازَةٌ"" : عَدَاوَةٌ، ضَغينَةٌ. ""تَمَكَّنَتِ الحَزَازَاتُ مِنْ نُفُوسِهِمْ فَأعْمَتْ قُلُوبَهُمْ عَمَّا يُوَحِّدُهُمْ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7897, 'حَزَازٌ', 'حزاز', 'جامد', 'حزز', 'حزاز', 'حزز', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حَزَازٌ-حَزَازٌ، ةٌ [ح ز ز]. 1. ""يَتَسَاقَطُ مِنْ رَأْسِهِ حَزازٌ"" : قِشْرَةُ الرَّأْسِ، الَّتِي تَتَساقَطُ كالنُّخالَةِ. 2. ""اِشْتَدَّ بِهِ الحَزَازُ مُنْذُ وَفَاةِ وَالِدِهِ"" : الأَلَمُ الَّذِي يُؤَثِّرُ فِي النَّفْسِ وَيَسْتَوْلِي عَلَيْهَا. 3.""حَزَازٌ""(نب).: نَبَاتٌ يَنْبُتُ عَلَى الصُّخُورِ وَالحِيطَانِ وَقُشُورِ الشَّجَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7898, 'مَحَزٌّ', 'محز', 'جامد', 'حزز', 'محز', 'محز', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَحَزٌّ-مَحَزٌّ [ح ز ز]. ""مَوْضِعُ الحَزِّ"" : أي القَطْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7899, 'حِزَامٌ', 'حزام', 'جامد', 'حزم', 'حزام', 'حزم', '', '', '', 'مفرد', 'DnN', '', '', '"حُزُمٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""تَمَنْطَقَ بِحِزَامٍ"" : وَضَعَ فِي وَسَطِهِ نِطَاقاً، زُنَّاراً، مَا يُحْزَمُ بِهِ. 2. ""أُحِيطَ بِالْمَدِينَةِ حِزَامٌ أَخْضَرُ"" : شَرِيطٌ، رِبَاطٌ مِنَ النَّبَاتَاتِ الخَضْرَاءِ. 3. ""شَدَّ لِلْمَعْرَكَةِ حِزَامَهُ"" : اِسْتَعَدَّ لَهَا. 4. ""حِزَامُ الأمْنِ"" : تَدَابِيرُ لِتَأْمِينِ السَّلاَمَةِ وَالحِفَاظِ عَلَى الأمْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7900, 'حُزُمٌ', 'حزم', 'جامد', '', 'حزم', 'حزم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7901, 'حُزْمَةٌ', 'حزمة', 'جامد', 'حزم', 'حزمة', 'حزمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حُزَمٌ"', '', 'R', '', '', '', '', '', '', '". 1.""حَمَلَتْ فَوْقَ ظَهْرِهَا حُزْمَةَ حَطَبٍ"" : مَا جُمِعَ مِنْ حَطَبٍ وَغَيْرِهِ وَشُدَّ بِحَبْلٍ. ""كُنَّا نَقْطِفُ مِنَ النَّرْجِسِ حُزْمَاتٍ تُصْنَعُ مِنْها باقَةٌ"". (حنامينه). 2.""جَمَعَ حُزَماً مِنَ الأَوْراقِ"" : رُزَماً. 3.""حُزْمَةٌ كَهْرَبَائِيَّةٌ"" : سَيْلٌ مِنَ الدَّقَائقِ الكَهْرَبَائِيَّةِ. 4.""حُزْمَةٌ ضَوْئِيَّةٌ"" : مَجْمُوعُ الأَشِعَّةِ الضَّوْئِيَّةِ. 5.""حُزْمَةٌ هَرْتَزِيَّةٌ"" : هِيَ مَوْجَاتٌ كَهْرَطِيسِيَّةٌ تُمَكِّنُ مِنْ إرْسَالِ الصُّوَرِ التِّلِيفِزْيونِيَّةِ أَوِ الْمُخَابَرَاتِ الهَاتِفِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7902, 'حُزَمٌ', 'حزم', 'جامد', '', 'حزم', 'حزم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7903, 'حَيْزُومٌ', 'حيزوم', 'جامد', 'حزم', 'حيزوم', 'حزم', '', '', '', 'مفرد', 'DnN', '', '', '"حَيَازيمُ"', '', 'R', '', '', '', '', '', '', '". 1. ""يَشْعُرُ بِاخْتِنَاقٍ فِي حَيْزُومِهِ"" : فِي صَدْرِهِ، وَسَطَ الصَّدْرِ. 2. ""حَيْزُومُ السَّفِينَةِ"" : مُقَدَّمُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7904, 'حَيَازيمُ', 'حيازيم', 'جامد', '', 'حيازيم', 'حزم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7905, 'مِحْزَمٌ', 'محزم', 'جامد', 'حزم', 'محزم', 'محزم', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَازِمُ"', '', 'R', '', '', '', '', '', '', '": الحِزَامُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7906, 'مَحَازِمُ', 'محازم', 'جامد', '', 'محازم', 'محزم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7907, 'حُزَيرَانُ', 'حزيران', 'جامد', '', 'حزيران', 'حزرن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ السَّادِسُ مِنَ السَّنَةِ الشَّمْسِيَّةِ، عَدَدُ أيَّامِهِ 30 يَوْماً، يَأْتِي بَعْدَ أيَّارٍ وَيَلِيهِ تَمُّوزُ، وَهُوَ مِنَ الشُّهُورِ السُّرْيَانيَّةِ، ويُسَمَّى أيْضاً جوان، يونْيو."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7908, 'حاسوبٌ', 'حاسوب', 'جامد', 'حسب', 'حاسوب', 'حسب', '', '', '', 'مفرد', 'DnN', '', '', '"حَواسِيبُ"', '', 'R', '', '', '', '', '', '', '"حاسوبٌ-حاسوبٌ [ح س ب]. ج:حَواسِيبُ: جِهازٌ حِسابِيٌّ لَهُ شاشَةٌ، ناظِمٌ مُكَوَّنٌ مِنْ عَدَدٍ مُتَنَوِّعٍ مِنَ الوَحَداتٍ الْمُتَخَصِّصَةِ، تَحْكُمُهُ ذاكِرَةٌ خاضِعَـةٌ فـي بَرْمَجَتِها لِنظامٍ تَسْجيليِّ يَسْمَحُ بِطَرِيقَةٍ آلِيَّةٍ بِإِنْجازِ عَمَلِيَّاتٍ حِسابِيَّةٍ مُعَقَّدَةٍ مَعَ تَرْتيبِها في بِطاقاتٍ مَعَ نَتائِجِها وَمُعْطَياتِها، بِالإِضافَةِ إلى قُدْرَتِهِ على طَبْعِ النُّصوصِ وَتَحْليلِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7909, 'حَواسِيبُ', 'حواسيب', 'جامد', '', 'حواسيب', 'حسب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7910, 'مَحْسَدَةٌ', 'محسدة', 'جامد', 'حسد', 'محسدة', 'محسدة', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَاسِدُ"', '', 'R', '', '', '', '', '', '', '". ""لاَ شَيْءَ يَدْفَعُ إِلَى الْمَحْسَدَةِ"" : مَا يَدْعُو وَيَدْفَعُ إِلَى الْحَسَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7911, 'مَحَاسِدُ', 'محاسد', 'جامد', '', 'محاسد', 'محسد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7912, 'حَسْرَةٌ', 'حسرة', 'جامد', 'حسر', 'حسرة', 'حسرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""يَا حَسْرَةً عَلَى سُوءِ حَظِّهِ"" : يَا أسَفَا. ""أتَجَرَّعُ صَامِتاً كُؤُوساً مَرِيرَةً مِنَ الحَسْرَةِ"". (ع. بنجلون). 2.""يَا حَسْرَتِي"" : يَا لَوْعَتِي، يَا لَهْفتِي. ""وَاحَسْرَتَاهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7913, 'حاسَّةٌ', 'حاسة', 'جامد', 'حسس', 'حاسة', 'حسة', '', '', '', 'مفرد', 'DnN', '', '', '"حَواسٌّ"', '', 'R', '', '', '', '', '', '', '". 1.""لِلإِنْسانِ حَواسٌّ خَمْسٌ"" : القُوَّاتُ الْمُدْرِكَةُ مِنْ سَمْعٍ وَشَمٍّ وَلَمْسٍ وَنَظَرٍ وَذَوْقٍ، وَهِيَ قُوَّاتٌ طَبيعِيَّةٌ لإِدْراكِ الْمَحْسوساتِ. 2.""حاسَّةٌ سادِسَةٌ"" : الإِحْساسُ الباطِنِيُّ غَيْرُ الظَّاهِرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7914, 'حَواسٌّ', 'حواس', 'جامد', '', 'حواس', 'حس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7915, 'حَسَاسٌ', 'حساس', 'جامد', 'حسس', 'حساس', 'حسس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حُسَاسٌ-حُسَاسٌ [ح س س]. 1.""حُسَاسُ الحَجَرِ"" : كُسَارَةُ الحِجَارَةِ الصَّغِيرَةِ، الجُذاذُ مِنَ الشَّيْءِ. 2.: سَمَكٌ صَغِيرٌ يُجفَّفُ حَتَّى لاَ يَبْقَى فِيهِ شَيْءٌ مَن مَائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7916, 'حُسَاسٌ', 'حساس', 'جامد', 'حسس', 'حساس', 'حسس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَسَاسٌ-حَسَاسٌ [ح س س]. 1.""ذَهَبَ فَلا حَسَاسَ بِهِ"" : لاَ يُحَسُّ مَكَانُهُ. 2.""حَسَاسُ الحُمَّى"" : أوَّلُ مَا تَبْدَأُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7917, 'حَسَاسِيَّةٌ', 'حساسية', 'جامد', 'حسس', 'حساسية', 'حسسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَسَاسِيَّةٌ-حَسَاسِيَّةٌ [ح س س]. ""شَدِيدُ الحَسَاسِيَّةِ"" : مَرَضٌ يَكُونُ الجِسْمُ فِيهِ مُعَرَّضاً لِلتَّأثُّرِ بِعَوَامِلَ خَارِجِيَّةٍ أَوْ دَاخِلِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7918, 'حَوَاسُّ', 'حواس', 'جامد', 'حسس', 'حواس', 'حس', '', '', '', 'مفرد', '', '', '', '"مفردحَاسَّة"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '". ""لِلإنْسَانِ حَوَاسُّ خَمْسٌ"" : حَاسَّةُ البَصَرِ وَالسَّمْعِ وَالذَّوْقِ وَالشَّمِّ وَاللَّمْسِ. ""الحَوَاسُّ الخَمْسُ لاَ تُدْرِكُ إلاَّ الأَجْسَامَ""(ابن طفيل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7919, 'مِحَسَّةٌ', 'محسة', 'جامد', 'حسس', 'محسة', 'محسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مِحَسَّةٌ-مِحَسَّةٌ [ح س س]. ""أَخَذَ المِحَسَّةَ وَشَرَعَ يَحُسُّ دَوَابَّهُ"": آلَةُ حَسِّ الدَّوَابّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7920, 'حُسَافَةٌ', 'حسافة', 'جامد', 'حسف', 'حسافة', 'حسفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حُسَافَةٌ-حُسَافَةٌ [ح س ف]. 1.""جَمَعَ الحُسَافَةَ لِلحِفَاظِ عَلَى البِيئَةِ"": نُفَايَةُ كُلِّ شَيْءٍ. 2.""حُسَافَةُ التَّمْرِ"" : قُشُورُهُ وَرَدِيئُهُ. 3.""حُسَافَةُ النَّاسِ"" : رِذَالُهُمْ. 4.""حُسَافَةُ الْمَاءِ"" : القَلِيلُ مِنْهُ. 5.""بَيْنَهُمْ حُسَافَةٌ"" : غَيْظٌ، عَدَاوَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7921, 'حُسَافٌ', 'حساف', 'جامد', 'حسف', 'حساف', 'حسف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حُسَافٌ-حُسَافٌ [ح س ف]. 1.""حُسَافُ الْمَائِدَةِ"" : مَا تَنَاثَرَ مِنْهَا. 2.: نُفَايَةُ كُلِّ شَيْءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7922, 'حَسِيفَةٌ', 'حسيفة', 'جامد', 'حسف', 'حسيفة', 'حسفة', '', '', '', 'مفرد', 'DnN', '', '', '"حَسَائِفُ"', '', '', '', '', '', '', '', '', '". 1.""أَظْهَرَ حَسِيفَةً"": غَضَباً. 2.""اِمْتَلأَ قَلْبُهُ بِالحَسِيفَةِ"" : باِلحِقْدِ، بِالعَدَاوَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7923, 'حَسَائِفُ', 'حسائف', 'جامد', '', 'حساءف', 'حسف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7924, 'حَسَكٌ', 'حسك', 'جامد', 'حسك', 'حسك', 'حسك', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حَسَكٌ-حَسَكٌ، ةٌ [ح س ك]. 1.""أدْمَى حَسَكُ الوَرْدِ أصَابِعَهُ"": شَوْكُهُ، كُلُّ نَبَاتٍ شَائِكٍ. 2.""اِنْتَبِهْ لِحَسَكِ السَّمَكِ"": عِظَام السَّمَكِ الدَّقِيقَة. 3. (نب).: نَبَاتٌ مِنْ فَصِيلَةِ السّذَابِيَّاتِ، شَائِكٌ، أَزْهَارُهُ عَطِرَةٌ وَثِمَارُهُ تُسَاعِدُ عَلَى جَرَيَانِ البَوْلِ عِنْدَ انْحِسَارِهِ، كَمَا تُطَهِّرُ المجَارِيَ البَوْلِيَّةِ. 4.""حَسَكُ الصَّدْرِ"": الحِقْدُ، العَدَاوَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7925, 'حَسِيكَةٌ', 'حسيكة', 'جامد', 'حسك', 'حسيكة', 'حسكة', '', '', '', 'مفرد', 'DnN', '', '', '"حَسَائِكُ"', '', '', '', '', '', '', '', '', '". 1.""تَقْضُمُ الدَّابَّةُ الحَسِيكَةَ"" : العَلَفُ مِن شَعِيرٍ وَتِبْنٍ ومَا شَابَهَ ذَلِكَ. 2.""لَمْ يُخْفِ حَسيكَتَهُ"" : حِقْدَهُ، أوْ عَدَاوَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7926, 'حَسَائِكُ', 'حسائك', 'جامد', '', 'حساءك', 'حسك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7927, 'حُسَامٌ', 'حسام', 'جامد', 'حسم', 'حسام', 'حسم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حُسَامٌ-حُسَامٌ [ح س م]. 1.""اِسْتَلَّ حُسَامَهُ"" : السَّيْفَ القَاطِعَ. 2.""حُسَامُ السَّيْفِ"" : طَرَفُهُ الَّذِي يُضْرَبُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7928, 'حُسُومٌ', 'حسوم', 'جامد', 'حسم', 'حسوم', 'حسم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حُسُومٌ-حُسُومٌ [ح س م]. ""رَجُلٌ لَمْ يَعْرِفْ إلاَّ الحُسُومَ فِي حَيَاتِهِ"" : الشُّؤْمَ، النَّحْسَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7929, 'تَحَاسِينُ', 'تحاسين', 'جامد', 'حسن', 'تحاسين', 'تحسن', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"تَحَاسِينُ-تَحَاسِينُ [ح س ن]. 1.""وَضَعَتْ تَحَاسِينَ فِي غُرْفَتِهَا لِتَظْهَرَ أَكْثَرَ رَوْنَقاً"" : وَضَعَتْ أَشْيَاءَ جَمِيلَةً. 2.""تَحَاسِينُ الخَطِّ"" : تَجْوِيدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7930, 'حَسْنَاءُ', 'حسناء', 'جامد', 'حسن', 'حسناء', 'حسن', '', '', '', 'مفرد', 'Dw', '', '', '"حَسْنَاوَاتٌ:حِسَانٌ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""اِمْرَأةٌ حَسْنَاءُ"" : جَمِيلَةٌ بَهِيَّةٌ. 2.: اِسْمُ عَلَمٍ لِلْمؤنَّثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7931, 'حَسْنَاوَاتٌ', 'حسناوات', 'جامد', '', 'حسناوات', 'حسنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7932, 'حِسَانٌ', 'حسان', 'جامد', '', 'حسان', 'حسن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7933, 'حَسَنَةٌ', 'حسنة', 'جامد', 'حسن', 'حسنة', 'حسنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""هَذِهِ حَسَنَةٌ مِنْ حَسَنَاتِهِ"" : فِعْلٌ حَسَنٌ مِنْ أفْعَالِهِ وَأعْمَالِهِ الجَيِّدَةِ، عَكْسَ سَيِّئَة. 2. ""قَدَّمَ حَسَنَةً لِلْفُقَرَاءِ"" : مَعْرُوفاً. الأنعام آية 160مَنْ جَاءَ بِالحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا .(قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7934, 'مَحَاسِنُ', 'محاسن', 'جامد', 'حسن', 'محاسن', 'محسن', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"مَحَاسِنُ-مَحَاسِنُ [ح س ن]. 1.""مَحَاسِنُ الوَجْهِ"" : مَوَاضِعُ الْحُسْنِ فِيهِ. 2.""مَحَاسِنُ العَمَلِ"" : مَزَايَاهُ. ""لِكُلِّ أُمَّةٍ فَضَائِلُ وَرَذَائِلُ وَلِكُلِّ قَوْمٍ مَحَاسِنُ وَمَسَاوِئُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7935, 'حَسَاءٌ', 'حساء', 'جامد', 'حسو', 'حساء', 'حس', '', '', '', 'مفرد', 'Dz', '', '', '"أحْسَاءُ"', '', 'Rz', '', '', '', '', '', '', '". ن. الحَسَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7936, 'أحْسَاءُ', 'أحساء', 'جامد', '', 'ءحساء', 'حس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7937, 'حَسَا', 'حسا', 'جامد', 'حسو', 'حسا', 'حس', '', '', '', 'مفرد', 'Dy', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"حَسَا-حَسَا [ح س و] (طخ). : الحَرِيرَةُ، طَعَامٌ يُحَضَّرُ بِالدَّقيقِ وَالْمَاءِ وَالقَطَّانِيَّاتِ، الشُّرْبَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7938, 'حَسُّونٌ', 'حسون', 'جامد', '', 'حسون', 'حسن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"حَسُّونٌ-حَسُّونٌ (حو).: طَائِرٌ مِنْ فَصِيلَةِ الشَّرْشُورِيَّاتِ، حَسَنُ الصَّوْتِ، جَمِيلُ الْمَنْظَرِ وَألْوانُ رِيشِهِ زَاهِيَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7939, 'حَسَائِيَّةٌ', 'حسائية', 'جامد', 'حسي', 'حساءية', 'حسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". وِعَاءٌ مِنْ خَزَفٍ وَنَحْوِهِ يُقَدَّمُ فِيهِ الحَسَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7940, 'مَحَاشِدُ', 'محاشد', 'جامد', 'حشد', 'محاشد', 'محشد', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَحَاشِدُ-مَحَاشِدُ [ح ش د]. ""مَحَاشِدُ الجُمْهُورِ"" : الْمَحَافِلُ، الأَمَاكِنُ الَّتِي يُحْتَشَدُ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7941, 'حَشَرَةٌ', 'حشرة', 'جامد', 'حشر', 'حشرة', 'حشرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.: صِنْفٌ مِنْ شُعْبَةِ مَفْصِلِيَّاتِ الأَرْجُلِ، تَتَمَيَّزُ بِسِتَّةِ أرْجُلِ وَأرْبَعِ أَجْنِحَةٍ، لَهَا خُرْطُومانِ وَعَيْنَانِ، وَهِيَ عَدِيدَةُ الفَصَائِلِ. 2.""مُبِيدُ الحَشَرَاتِ"": مَادَّةٌ صِنَاعِيَّةٌ سَامَّةٌ تُبِيدُ الحَشَرَاتِ. 3.""عِلْمُ الحَشَرَاتِ"" : عِلْمٌ مُخْتَصٌّ بِبَحْثِ أنْوَاعِ الحَشَرَاتِ وَفَصَائِلِهَا وَرُتَبِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7942, 'حَشَرِيَّاتٌ', 'حشريات', 'جامد', '', 'حشريات', 'حشرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": رُتْبَةٌ مِنَ اللّبُونَاتِ تَعِيشُ عَلَى الحَشَرَاتِ، مِنْ أَشْهَرِهَا القُنْفُذِيَّاتُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7943, 'حُشَاشَةٌ', 'حشاشة', 'جامد', 'حشش', 'حشاشة', 'حششة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حُشَاشَةٌ-حُشَاشَةٌ [ح ش ش]. 1.""حُشَاشَةُ الْمُحْتَضِرِ"" : بَقِيَّةُ الرُّوحِ فِيهِ. 2.""حُشَاشَةُ القَلْبِ"" : رُوحُ القَلْبِ، رَمَقُ الحَيَاةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7944, 'حَشِيشٌ', 'حشيش', 'جامد', 'حشش', 'حشيش', 'حشش', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"حَشَائِشُ"', '', 'R', '', '', '', '', '', '', '". 1.""لَمْ يَبْقَ فِي الْمَرَاعِي إلاَّ الحَشِيشُ"" : العُشْبُ اليَابِسُ، وَيُطْلَقُ أيْضاً عَلَى الكَلإِ الرَّطْبِ. ""تَمُدُّ النَّارَ بِالحَشِيشِ وَالحَطَبِ الجَزْلِ"" (ابن طفيل). 2.""نَبَاتٌ مِنَ الْمَزْرُوعَاتِ الْمُنَبِّهَةِ، الْمُخَدِّرَةِ مِنَ القِنَّبِ الهِنْدِيّ، وَيُطْلَقُ عَلَيْهِ أيْضاً حَشِيشَةٌ. 3.""حَشِيشَةُ القِنَّبِ الْهِنْدِيِّ"" : نَوْعٌ مِنْ بِزْرِهِ يُسْتَخْرَجُ مِنْهُ مُخَدِّرٌ ضَارٌّ. 4.""حَشِيشَةُ الدِّينارِ"" : مِنْ فَصِيلةَ القِنَّبِيَّاتِ، تُسْتعْمَلُ فِي الجِعَةِ كَمَا تُسْتَخْدَمُ مادَّةً طِبِّيَّةً مُدِرَّةً لِلْبَوْلِ. 5.""حَشِيشَةُ النَّجْمِ"" (نب).: نَبَاتٌ مِنْ فَصِيلَةِ الزَّنْبَقِيَّاتِ، يُسْتَخْدَمُ فِي تَحْضِيرِ بَعْضِ الأدْوِيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7945, 'حَشَائِشُ', 'حشائش', 'جامد', '', 'حشاءش', 'حشش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7946, 'مَحَشٌّ', 'محش', 'جامد', 'حشش', 'محش', 'محش', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَحَاشُّ"', '', 'R', '', '', '', '', '', '', '".: الأَرْضُ الضَّيِّقَةُ الكَثِيرَةُ الْحَشِيشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7947, 'مَحَاشُّ', 'محاش', 'جامد', '', 'محاش', 'محش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7948, 'مِحَشٌّ', 'محش', 'جامد', 'حشش', 'محش', 'محش', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَحَاشُّ"', '', 'R', '', '', '', '', '', '', '". ""يَطُوفُ بِمِحَشَّتِهِ بَيْنَ الْحَشَائِشِ"" : مِنْجَلٌ لِلْحَشِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7949, 'مَحَاشُّ', 'محاش', 'جامد', '', 'محاش', 'محش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7950, 'حَشَفَةٌ', 'حشفة', 'جامد', 'حشف', 'حشفة', 'حشفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَشَفَةٌ-حَشَفَةٌ [ح ش ف]. ""حَشَفَةُ الذَّكَرِ"" : الجِلْدَةُ الَّتِي يَكْشِفُ عَنْهَا الخِتَانُ فِي عُضْوِ الذَّكَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7951, 'حَشَفٌ', 'حشف', 'جامد', 'حشف', 'حشف', 'حشف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَشَفٌ-حَشَفٌ [ح ش ف]. 1.""حَشَفُ التَّمْرِ"" : أَرْدؤهُ، كُلُّ تَمْرٍ يابسٍ بِلا حلاوَةٍ أَو لَحَمٍ. 2.""اِمْتَلأ الطَّبَقُ بِالحَشَفِ"" : الخُبْزُ اليَابِسُ. 3. ""ضَرْعٌ حَشَفٌ"" : ضَرْعٌ جَافٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7952, 'حَشِيفٌ', 'حشيف', 'جامد', 'حشف', 'حشيف', 'حشف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَشِيفٌ-حَشِيفٌ [ح ش ف]. ""اِرْتَدى حَشِيفاً"" : ثَوْباً بَالِياً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7953, 'حَشِيكةٌ', 'حشيكة', 'جامد', 'حشك', 'حشيكة', 'حشكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَشِيكةٌ-حَشِيكةٌ [ح ش ك]. ""تَرَكَ الدَّابَّةَ تَقْضِمُ الحَشِيكَةَ"" : العَلَفَ مِنْ شَعِيرٍ وَتِبْنٍ وَمَا شَابَهَ ذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7954, 'حِشْمَةٌ', 'حشمة', 'جامد', 'حشم', 'حشمة', 'حشمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حِشْمَةٌ-حِشْمَةٌ [ح ش م]. ""ظَهَرَتْ عَلَى مَلامِحِهَا حِشْمَةٌ"" : حَيَاءٌ، اِحْتِشَامٌ.‎ ""أظْهَرَتْ حِشْمَةً أمَامَ الضُّيُوفِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7955, 'حَشاً', 'حشا', 'جامد', 'حشو', 'حشا', 'حش', '', '', '', 'مفرد', 'Dy', '', '', '"أحْشَاءٌ"', '', 'Rw', '', '', '', '', '', '', '". 1.""يَشْعُرُ بِألَمٍ فِي أحْشَائِهِ"" : فِي جَوْفِ بَطْنِهِ. ""تَقَيَّأَ مَا فِي أَحْشَائِهِ"". 2.""فِي أحْشَائِهَا يَكْمُنُ الصَّفَاءُ"" : فِي دَاخِلِهَا، فِي أعْماقِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7956, 'أحْشَاءٌ', 'أحشاء', 'جامد', '', 'ءحشاء', 'حش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7957, 'حَشِيَّةٌ', 'حشية', 'جامد', 'حشو', 'حشية', 'حشة', '', '', '', 'مفرد', 'DnN', '', '', '"حَشايا"', '', '', '', '', '', '', '', '', '". ""اِسْتَلْقَى عَلَى الحَشِيَّةِ"" : الفِرَاش الْمَحْشُوّ بِالقُطْنِ أوِ الصُّوفِ وَنَحْوِهِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7958, 'حَشايا', 'حشايا', 'جامد', '', 'حشايا', 'حش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7959, 'حاشِيَةٌ', 'حاشية', 'جامد', 'حشي', 'حاشية', 'حشة', '', '', '', 'مفرد', 'DnN', '', '', '"حَواشٍ:الحَواشِي"', '', '', '', '', '', '', '', '', '". 1.""طَرَّزَتْ حاشِيَةَ فُسْتانِها"" : جانِبَهُ. 2.""حاشِيَةُ الكِتابِ"" : طَرَفُهُ، طُرَّتُهُ. ""يضُمُّ الكِتابُ مَتْناً وَشَرْحاً وَحاشِيَةً"".(أ. أمين). 3.""وَصَلَ الأميرُ مَعَ حاشِيَتِهِ"" : مَعَ أَهْلِهِ وَخاصَّتِهِ. 4.""رَجُلٌ رَقيقُ الحَواشِي"" : لَطيفُ الصُّحْبَةِ. 5.""كَلامٌ رَقيقُ الحَواشِي"" : لَيِّنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7960, 'حَواشِي', 'حواشي', 'جامد', '', 'حواشي', 'حش', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7961, 'حِصَانٌ', 'حصان', 'جامد', '', 'حصان', 'حصن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أحْصِنَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: أحْصِنَةٌ. 1. ""رَكِبَ الحِصَانَ"" : كُلُّ ذَكَرٍ مِنَ الخَيْلِ. ""حِصَانُ الجَرِّ"". 2.""سَيَّارَةٌ مِنْ أرْبَعةِ أحْصِنَةٍ"" : وَحْدَةٌ اِصْطِلاحِيَّةٌ تُعْرَفُ بِالحِصَانِ البُخَارِيِّ لِتَقْدِيرِ القُوَّةِ الآلِيَّةِ البُخَارِيَّةِ الْمُحَرِّكَةِ. 3. ""حِصَانُ البَحْرِ"" : جِنْسٌ مِنَ الأسْمَاكِ العَظِيمَةِ، لَهُ رَأْسٌ يُحَاكِي رَأْسَ الحِصَانِ. 4. ""حِصَانُ القَفْزِ""(ريا): أَدَاةٌ رِيَاضِيَّةٌ يَعْتَمِدُ عَلَيْهَا الرِّيَاضِيُّ بَعْدَ جَرْيٍ انْدِفَاعِيٍّ لِكَيْ يَتَمَكَّنَّ مِنَ القَفْزِ، وَهُوَ نَوْعٌ مِن رِيَاضَةِ الجمباز."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7962, 'أحْصِنَةٌ', 'أحصنة', 'جامد', '', 'ءحصنة', 'حصنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7963, 'حاصِبٌ', 'حاصب', 'جامد', 'حصب', 'حاصب', 'حصب', '', '', '', 'مفرد', 'DnN', '', '', '"حَواصِبُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَكانٌ حاصِبٌ"" : ذُو حَصْباءَ (صِغارُ صَخَرِ الرَّمْلِ). 2.""ريحٌ حاصِبٌ"": الرِّيَاحُ التِي تَحْمِلُ التُّرابَ والحَصْباءَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7964, 'حَواصِبُ', 'حواصب', 'جامد', '', 'حواصب', 'حصب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7965, 'حَصْبَاءُ', 'حصباء', 'جامد', 'حصب', 'حصباء', 'حصب', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"حَصْبَاءُ-حَصْبَاءُ [ح ص ب].: صِغَارُ الصَّخْرِ الرَّمْلِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7966, 'حَصْبَةٌ', 'حصبة', 'جامد', 'حصب', 'حصبة', 'حصبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حَصْبَةٌ-حَصْبَةٌ [ح ص ب]. : مَرَضٌ مُعْدٍ نَاتِجٌ عَنْ حُمَّى حَادَّةٍ تُفْرِزُ بُثُوراً تَظْهَرُ فِي الجَسَدِ وَيُرَافِقُهَا زُكَامٌ وَسُعَالٌ، وَلاَ تُنْتِجُ عَنْهُ مُضَاعَفَاتٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7967, 'حَصَبٌ', 'حصب', 'جامد', 'حصب', 'حصب', 'حصب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَصَبٌ-حَصَبٌ [ح ص ب]. 1.""كَثُرَ الحَصَبُ فِي السَّاحَةِ"" : صِغَارُ الحِجَارَةِ. 2.""أَلْقَى الحَصَبَ في النَّارِ"" : مَا يُلْقَى فِيهَا مِنْ حَطَبٍ وَوَقُودٍ. الأنبياء آية 98 إِنَّكُمْ وَمَا تَعْبُدُونَ مِنْ دُونِ اللهِ حَصَبُ جَهَنَّمَ أَنْتُمْ لَهَا وَارِدُونَ (قرآن).."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7968, 'مُحَصَّبٌ', 'محصب', 'جامد', 'حصب', 'محصب', 'محصب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مُحَصَّبُ-الْمُحَصَّبُ [ح ص ب]. : مَوْضِعُ رَمْيِ الجِمَارِ بِمِنـىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7969, 'مَحْصَبَةٌ', 'محصبة', 'جامد', 'حصب', 'محصبة', 'محصبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَحْصَبَةٌ-مَحْصَبَةٌ [ح ص ب]. ""أَرْضٌ مَحْصَبَةٌ"" : ذَاتُ حَصَبٍ أَوْ كَثِيرَةُ الحَصْبَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7970, 'حَصِيدَةٌ', 'حصيدة', 'جامد', 'حصد', 'حصيدة', 'حصدة', '', '', '', 'مفرد', 'DnN', '', '', '"حَصَائِدُ"', '', '', '', '', '', '', '', '', '". 1. ""تَرَاكَمَتِ الحَصَائِدُ فِي البَيَادِرِ"" : مَا تَمَّ حَصْدُهُ مِنْ زَرْعٍ. 2. ""وَكُنْتَ لاَ تَرَى إلاَّ وُجُوهاً مُسْتَبْشِرَةً أيَّامَ الحَصِيدَةِ"" : أَيَّامَ الحَصادِ. 3.""تَرَاكَمَ الزَّرْعُ في الحَصيدَةِ"" : في الْمَزْرَعَةِ. 4.""حَصَائِدُ الألْسِنَةِ"" : الكَلاَمُ الَّذِي لاَ خَيْرَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7971, 'حَصَائِدُ', 'حصائد', 'جامد', '', 'حصاءد', 'حصد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7972, 'حَصِيدٌ', 'حصيد', 'جامد', 'حصد', 'حصيد', 'حصد', '', '', '', 'مفرد', 'DnN', '', '', '"حَصَائِدُ"', '', 'R', '', '', '', '', '', '', '". 1. ""بَعْدَ تَعَبٍ جَلَسُوا يَنْظُرُونَ إلَى حَصِيدِهِمْ"" : مَا حَصَدُوهُ مِنْ زَرْعٍ. 2. ""أيَّامُ الحَصِيدِ"" : أيَّامُ الحَصَادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7973, 'حَصَائِدُ', 'حصائد', 'جامد', '', 'حصاءد', 'حصد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7974, 'حاصِرَةٌ', 'حاصرة', 'جامد', 'حصر', 'حاصرة', 'حصرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حَواصِرُ"', '', 'R', '', '', '', '', '', '', '". ""جُمْلَةٌ بَيْنَ حاصِرَتَيْنِ"" : عِضادَةٌ، هِيَ عَلامَةٌ مُضاعَفَةٌ على شَكْلِ نِصْفِ الْمُعَيَّنِ توضَعُ في بِدايَةِ جُمْلَـةٍ اعْتِراضِيَّةٍ وَخاتِمَتِها، وَعَلامَتُها هَكَذا: ( ) ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7975, 'حَواصِرُ', 'حواصر', 'جامد', '', 'حواصر', 'حصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7976, 'حِصَارٌ', 'حصار', 'جامد', 'حصر', 'حصار', 'حصر', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حِصَارٌ-حِصَارٌ [ح ص ر]. 1.""شَدَّ البَعِيرَ بِالحصَارِ"" : بِالوَثَاقِ. 2. ""أقَامَ الجُنْدُ حِصَاراً شَدِيداً عَلَى الْمَدِينَةِ"" : أحَاطُوا بِهَا مِنْ كُلِّ جَانِبٍ، جَعَلُوا حَوْلَهَا سُوراً. ""كَيْفَ لِلْمَرْءِ أَنْ يَنْسَى حِصَارَ بَيْرُوتَ وَقَدْ أحَاطَتْ بِهَا دَبَّابَاتُ الجَيْشِ الإسْرَائِيلِيّ"" ""الحِصَارُ العَسْكَرِيُّ"". 3. ""اِتَّفَقُوا عَلَى تَطْبِيقِ الحِصَارِ الاقْتِصَادِيّ عَلَى العَدُوِّ"" : تَضْييقُ الخِنَاقِ الاقْتِصَادِيِّ عَلَيْهِ بِمَنْعِ التَّعَامُلِ مَعَهُ تِجَارِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7977, 'حَصِيرٌ', 'حصير', 'جامد', 'حصر', 'حصير', 'حصر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"حُصُرٌ:أحْصِرَةٌ:حَصَائِرُ"', '', 'R', '', '', '', '', '', '', '". ""أدَّى الصَّلاَةَ عَلَى حَصِيرٍ"" : بِسَاط يُنْسَجُ بِطَرِيقَةٍ يَدَوِيَّةٍ مِنْ سَعَفِ النَّخِيلِ وَمَا شَابَهَ ذَلِكَ. ""لَمْ تَكُنْ عَصَا الفَقِيهِ فِي الكُتَّابِ قَادِرَةً عَلَى مَنْعِنَا مِنْ تَقْطِيعِ أعْوَادِ الأحْصِرَةِ"" ""حَصَائِرُ الْمَسْجِدِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7978, 'حُصُرٌ', 'حصر', 'جامد', '', 'حصر', 'حصر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7979, 'أحْصِرَةٌ', 'أحصرة', 'جامد', '', 'ءحصرة', 'حصرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7980, 'حَصَائِرُ', 'حصائر', 'جامد', '', 'حصاءر', 'حصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7981, 'حِصْرِمٌ', 'حصرم', 'جامد', '', 'حصرم', 'حصرم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1. ""ذَاقَ حِصْرِمَ العِنَبِ"" : أوَّلَهُ وَيَكُونُ عَادَةً أخْضَرَ حَامِضاً. 2. ""حِصْرِمُ الفَوَاكِهِ وَالخُضَرِ"" : بِدَايَتُهَا الأُولَى قَبْلَ أنْ تَنْضُجَ. ""الآبَاءُ يَأْكُلُونَ الحِصْرِمَ وَالأوْلاَدُ يَغْرِسُونَ"" (مثل)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7982, 'حِصْرِمةٌ', 'حصرمة', 'جامد', '', 'حصرمة', 'حصرمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"وَاحِدَةُالحِصْرِم"', '', 'R', '', '', '', '', '', '', '": وَاحِدَةُ الحِصْرِم."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7983, 'حِصَّةٌ', 'حصة', 'جامد', 'حصص', 'حصة', 'حصة', '', '', '', 'مفرد', 'DnN', '', '', '"حِصَصٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""أَخَذَ حِصَّتَهُ مِنَ المِيراثِ"" : النَّصِيبَ. ""وُزِّعَتِ الحِصَصُ بِالتَّسَاوِي"" ""أخَذْتُ حِصَّتِي مِنَ الطَّعَامِ"" ""أخَذَ حِصَّةَ الأَسَدِ"". 2.""الحِصَّةُ الأُسْبُوعِيَّةُ"" : الفَتْرَةُ الزَّمَنِيَّةُ الأُسْبُوعِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7984, 'حِصَصٌ', 'حصص', 'جامد', '', 'حصص', 'حص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7985, 'حَصَّالَةٌ', 'حصالة', 'جامد', 'حصل', 'حصالة', 'حصلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '".: صُنْدُوقٌ صَغِيرٌ مُقْفَلٌ تُوضَعُ فِيهِ النُّقُودُ بِقَصْدِ ادِّخَارِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7986, 'حُصَالَةٌ', 'حصالة', 'جامد', 'حصل', 'حصالة', 'حصلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حُصَالَةٌ-حُصَالَةٌ [ح ص ل]. ""حُصَالَةُ البَيْدَرِ"" : مَا يَبْقَى فِي البَيْدَرِ مِنْ حُبوبٍ بَعْدَ تَنْقِيَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7987, 'حِصْنٌ', 'حصن', 'جامد', 'حصن', 'حصن', 'حصن', '', '', '', 'مفرد', 'DnN', '', '', '"حُصُونٌ:أحْصَانٌ"', '', 'R', '', '', '', '', '', '', '". ""جَعَلَ الجُنْدُ مِنَ القَلْعَةِ حِصْناً مَنِيعاً"" : مَكَاناً مَحْمِيّاً مَنِيعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7988, 'حُصُونٌ', 'حصون', 'جامد', '', 'حصون', 'حصن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7989, 'أحْصَانٌ', 'أحصان', 'جامد', '', 'ءحصان', 'حصن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7990, 'حَصَاةٌ', 'حصاة', 'جامد', 'حصي', 'حصاة', 'حصة', '', '', '', 'مفرد', 'DnN', '', '', '"حصيات"', '', 'Rw', '', '', '', '', '', '', '"حَصَاةٌ-حَصَاةٌ [ح ص ي]. 1. ""رَجُلٌ ثَابِتُ الحَصَاةِ"" : عَاقِلٌ، رَزِينٌ. 2. ""حَصَاةُ اللِّسَانِ"" : طَلاَقَتُهُ. 3. ""مَالَهُ حَصاةٌ"" : مَا لَهُ رَأيٌ يُرَجَعُ إلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7991, 'حَصَيَاتٌ', 'حصيات', 'جامد', '', 'حصيات', 'حصت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7992, 'مَحْصَاةٌ', 'محصاة', 'جامد', 'حصي', 'محصاة', 'محصة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مَحْصَاةٌ-مَحْصَاةٌ [ح ص ي]. ""أَرْضٌ مَحْصَاةٌ"" : تَكْثُرُ فيها الأَحْجَارُ الصَّغِيرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7993, 'حَضْرَةٌ', 'حضرة', 'جامد', 'حضر', 'حضرة', 'حضرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""حَضْرَةُ الْمُدِيرِ"": سِيَادَةُ الْمُدِيرِ، أَيْ تَعْبِيراً عَنْ مَكَانَتِهِ. 2. تَحَدَّثَ إلَيْهِ بِحَضْرةِ أَخِيهِ"" : بِوُجُودِهِ، بِحُضُورِهِ. 3. ""شَاهَدَ الحَضْرَةَ بِالزَّاوِيَةِ"" : الجَذْبَةَ. 4. ""حَضَرَاتُ السَّادَةِ وَالسَيِّدَاتِ"" : عِبَارَةٌ تُرَدَّدُ عِنْدَمَا يُرَادُ التَّوجُّهُ بِالخِطَابِ لِلْحَاضِرِينَ، الحُضُور. 5.""نَزَلَ الحَضْرَةَ"" : الْمَدِينَةَ. 6. ""حَضْرَةُ الدَّارِ"" : فِنَاؤُهَا، سَاحَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7994, 'حَضَرٌ', 'حضر', 'جامد', 'حضر', 'حضر', 'حضر', '', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"حَضَرٌ-حَضَرٌ [ح ض ر]. 1. ""هُوَ منْ أهْلِ الحَضَرِ"" : مِنْ سُكَّانِ الْمُدُنِ وَالقُرَى الكَبِيرَةِ، عَكْس البَدَاوَةِ، البَدْوِ. 2.""سُكَّانُ الحَضَرِ"" : سُكَّانُ الْمُدُن وَالقُرَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7995, 'مَحْضَرٌ', 'محضر', 'جامد', 'حضر', 'محضر', 'محضر', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَاضِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""حَدَثَ ذَلِكَ بِمَحْضَرِهِ"" : بِمَشْهَدِهِ، بِحُضُورِهِ. 2.""مَحْضَرُ الاجْتِمَاعِ"" : التَّقْرِيرُ الَّذِي تُسَجَّلُ فِيهِ أَقْوَالُ كُلِّ الْحَاضِرِينَ وَآرَاؤُهُمْ فِي الاِجْتِمَاعِ. 3.""مَحْضَرُ الشُّرْطَةِ"" : صَحِيفَةٌ مِنْ دَفْتَرِ الْمُخَالَفَاتِ تُسَجَّلُ فِيهَا وَقَائِعُ الْحَوَادِثِ أَوِ الْمُخَالَفَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7996, 'مَحَاضِرُ', 'محاضر', 'جامد', '', 'محاضر', 'محضر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7997, 'حِضْنٌ', 'حضن', 'جامد', 'حضن', 'حضن', 'حضن', '', '', '', 'مفرد', 'DnN', '', '', '"أَحْضَانٌ:حُضُونٌ"', '', 'R', '', '', '', '', '', '', '". 1.""ضَمَّتِ الطِّفْلَةَ إلَى حِضْنِهَا"" : إلَى صَدْرِهَا، أوْ مَا دُونَ الإِبْطِ وَالبَطْنِ. 2. ""عَشَّشَ الطَّائِرُ فِي حِضْنِ الجَبَلِ"" : في سَفْحِهِ، فِي حَضِيضِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7998, 'أَحْضَانٌ', 'أحضان', 'جامد', '', 'ءحضان', 'حضن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(7999, 'حُضُونٌ', 'حضون', 'جامد', '', 'حضون', 'حضن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8000, 'حُطَيْئَةٌ', 'حطيئة', 'جامد', 'حطأ', 'حطيءة', 'حطة', '', '', '', 'مفرد', '', '', '', '"""رَجُلٌحُطَيْئَةٌ"""', '', 'R', '', 'N', 'O', 'N', 'O', '', '"حُطَيْئَةٌ-حُطَيْئَةٌ [ح ط أ]. 1.""رَجُلٌ حُطَيْئَةٌ"" : قَصِيرٌ، أو دَمِيمُ الوَجْهِ، قَبِيحٌ. 2.: اِسمُ شاعِرٍ مِنْ شُعَرَاءِ العَصْرِ الأُمَوِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8001, 'حَطَبَةٌ', 'حطبة', 'جامد', 'حطب', 'حطبة', 'حطبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حَطَبَةٌ-حَطَبَةٌ [ح ط ب].: قِطْعَةُ خَشَبٍ تُسْتَعْمَلُ عَادَةً للتَّدْفِئَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8002, 'حَطِيطَةٌ', 'حطيطة', 'جامد', 'حطط', 'حطيطة', 'حططة', '', '', '', 'مفرد', 'DnN', '', '', '"حَطائِطُ"', '', 'R', '', '', '', '', '', '', '". 1.""أَعْلَنَ المتْجَرُ عَنْ حَطِيطَةِ الْمَوْسِمِ"" : مَوْسِم تَخْفِيضِ الأَسْعَارِ. 2.""خَصَمَ حَطِيطَةً مِنَ الحِسَابِ"" : مَا يُنْقَصُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8003, 'حَطائِطُ', 'حطائط', 'جامد', '', 'حطاءط', 'حطط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8004, 'مَحَطَّةٌ', 'محطة', 'جامد', 'حطط', 'محطة', 'محطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""مَحَطَّةٌ لِكُلِّ العَابِرِينَ"" : مَوْقِفُ الاسْتِرَاحَةِ. 2.""مَحَطَّةُ القِطَارِ"" : مَكانُ انْطِلاَقِ القِطَارِ وَوُقُوفِهِ. ""مَحَطَّةُ الْحَافِلاَتِ"" الشَّاحِنَاتِ"" ""مَحَطَّةُ سَيَّارَةِ الأُجْرَةِ"". 3.""مَحَطَّةُ الإِذَاعَةِ"" : الْمَكَانُ الَّذِي تُذَاعُ مِنْهُ الأَخْبَارُ بِالرَّادْيُو. ""مَحَطَّةُ الإِرْسَالِ"". وَتُطْلَقُ كَلِمَةُ ""مَحَطَّةٌ"" عَلَى كُلِّ مَكَانٍ مَرْكَزِيٍّ فيِ مَجَالٍ مِنْ مَجَالاَتِ الأَرْصَادِ الجَوِّيَّةِ، ""الْمَحَطَّةُ الكَهْرَبَائِيَّةُ"" ""مَحَطَّةُ تَوْلِيدِ الكَهْرَبَاءِ"" ""الْمَحَطَّةُ الفَضَائِيَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8005, 'مَحَطٌّ', 'محط', 'جامد', 'حطط', 'محط', 'محط', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَاطُّ"', '', 'R', '', '', '', '', '', '', '". 1.""مَحَطُّ القَافِلَةِ"" : مَكَانُ نُزُولِهَا. 2.""كَانَ مَحَطَّ الأَنْظَارِ"" : نُقْطَةُ ارْتِكَازٍ، أَيْ كَانَتِ الأَنْظَارُ مُتَّجِهَةً إِلَيْهِ. 3.""هُوَ مَحَطُّ آمَالِهِمْ"" : مَوْضِعُ آمَالِهِمْ، أَيْ كَانَتْ تُعَلَّقُ عَلَيْهِ الآمَالُ. 4. ""مَحَطُّ الكَلاَمِ"" : مَوْضِعُ الفَائِدَةِ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8006, 'مَحَاطُّ', 'محاط', 'جامد', '', 'محاط', 'محط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8007, 'حاطِمَةٌ', 'حاطمة', 'جامد', 'حطم', 'حاطمة', 'حطمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حاطِمَةٌ-حاطِمَةٌ [ح ط م]. ""حاطِمَةُ الجَليدِ"" : آلَةٌ ضَخْمَةٌ لإِزالَةِ الجَليدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8008, 'حاطومٌ', 'حاطوم', 'جامد', 'حطم', 'حاطوم', 'حطم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حاطومٌ-حاطومٌ [ح ط م]. ""تَناوَلَ حاطوماً"" : دَواءً أو أَكْلاً يُسَهِّلُ الهَضْمَ، هَاضومٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8009, 'حُطَامَةٌ', 'حطامة', 'جامد', 'حطم', 'حطامة', 'حطمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حُطَامَةٌ-حُطَامَةٌ [ح ط م]. ""حُطَامَةُ شَيْءٍ"" : حُطَامُهُ، أيْ مَا تَحَطَّمَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8010, 'حُطَامٌ', 'حطام', 'جامد', 'حطم', 'حطام', 'حطم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حُطَامٌ-حُطَامٌ [ح ط م]. 1. ""دَعْكَ وَحُطَامَ الدُّنْيَا"" : مَا فِيهَا مِنْ مَالٍ وَمَتاعٍ قَلَّ أوْ كَثُرَ فَكُلُّهُ إلَى فَنَاءِ. ""يَمْلأُ أيْدِيَهُمْ مِنْ حُطَامِ الدُّنْيَا"".(طه حسين). 2.""تنَاثَرَ حُطَامُ النَّبَاتِ"" : مَا يَبِسَ مِنْهُ.الزمر آية 21 يَهِيجُ فَترَاهُ مُصْفَرّاً ثُمَّ يَجْعَلُهُ حُطَاماً .(قرآن). 3.""وَتَنَاثَرَ حُطَامُ الطَّائِرَةِ بَعْدَ سُقُوطِهَا"" : أَجْزَاؤُهَا، أطْرَافُهَا وَمَا تَكَسَّرَ مِنْهَا. ""لَمْ يَبْقَ إلاَّ الْمَوْتُ... وَالحُطَامُ وَالدَّمَارُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8011, 'حُطَمَةٌ', 'حطمة', 'جامد', 'حطم', 'حطمة', 'حطمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حُطَمَةٌ-حُطَمَةٌ [ح ط م]. ""رَماهُ فِي الحُطَمَةِ"" : فِي النَّارِ الْمُشْتَعِلَةِ الشَّدِيدَةِ. الهمزة آية 5 وَمَا أدْرَاكَ مَا الحُطَمَة (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8012, 'مُحَطِّمَةٌ', 'محطمة', 'جامد', 'حطم', 'محطمة', 'محطمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". "" الْمُحَطِّمَةُ الثَّلْجِيَّةُ"" : كَاسِحَةُ الجَلِيدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8013, 'حَظِيرَةٌ', 'حظيرة', 'جامد', 'حظر', 'حظيرة', 'حظرة', '', '', '', 'مفرد', 'DnN', '', '', '"حَظَائِرُ:حِظارٌ"', '', '', '', '', '', '', '', '', '". 1.""أدْخَلَ الرَّاعِي الْمَاشِيَةَ إلَى الحَظِيرَةِ"" : مَأْوَى الْمَاشِيَةِ مُحَاطٌ لِيَقِيهَا الرِّيحَ وَالبَرْدَ. 2. ""وَعَدَ اللَّهُ الْمُؤْمِنِينَ بِحَظِيرَةِ القُدْسِ"" : بِالجَنَّةِ. 3.""إنَّهُ لَنَكِدُ الحَظِيرَةِ"" : قَلِيلُ الخَيْرِ، بَخِيلٌ. 4. ""جَذَبَهُ إلَى حَظِيرَتِهِ"" : جَذَبَهُ إلَى سُلْطَتِهِ. 5. ""رَجَعَ إلَى حَظِيرَةِ أَهْلِهِ"": إلَى بَيْتِهِ العَائِلِيِّ. 6. ""حَظِيرَةُ الطَّائِرَاتِ"" : الْمَكَانُ الْمُتَّسِعُ لِلطَّائِرَاتِ خَلْفَ الْمَطَارِ. 7. ""حَظِيرَةُ السَّيَّارَاتِ"" : مَكَانُ إِصْلاَحِهَا، الْمَرْأَبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8014, 'حَظَائِرُ', 'حظائر', 'جامد', '', 'حظاءر', 'حظر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
