INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8016, 'حُفَّاتٌ', 'حفات', 'جامد', '', 'حفات', 'حفت', '', '', '', 'جمع تكسير', 'DnN', '', '', '"حفَافِيتُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: حفَافِيتُ. (حو).: حَيَّةٌ رَقْشَاءُ تَأْكُلُ الحَشِيشَ، غَيْرُ سَامَّةٍ، تَتَهَدَّدُ وَلاَ تَضُرُّ أَحَداً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8017, 'حَفِيدٌ', 'حفيد', 'جامد', 'حفد', 'حفيد', 'حفد', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَحْفادٌ:حُفَدَاءُ"', '', 'R', '', '', '', '', '', '', '". ""هَذَا حَفِيدِي"" : اِبْنُ ابْنِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8018, 'أَحْفادٌ', 'أحفاد', 'جامد', '', 'ءحفاد', 'حفد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8019, 'حُفَدَاءُ', 'حفداء', 'جامد', '', 'حفداء', 'حفد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8020, 'حافِرٌ', 'حافر', 'جامد', 'حفر', 'حافر', 'حفر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"حَوافِرُ"', '', '', '', '', '', '', '', '', '". 1.""حَوافِرُ الدَّابَّةِ"" : ما يُقابِلُ القَدَمَ عِنْدَ الإِنْسانِ، وَهُوَ تَرْكيبٌ صَلْدٌ يَتَكَوَّنُ حَوْلَ طَرَفِ الأَصْبُعِ في بَعْضِ الثَّدْيِيَّـاتِ الْمَعْروفَةِ بِالحافِرِيَّاتِ. ""رَفَعَ الحِصانُ قائِمَتَهُ وَرَكَلَهُ بِحافِرِهِ"". 2.""وَقَعَ الحافِرُ على الحافِرِ""(مثل) : تَوافَقَ الأمْرَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8021, 'حَوافِرُ', 'حوافر', 'جامد', '', 'حوافر', 'حفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8022, 'حُفْرَةٌ', 'حفرة', 'جامد', 'حفر', 'حفرة', 'حفرة', '', '', '', 'مفرد', 'DnN', '', '', '"حُفَرٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""حَفَرَ حُفْرَةً"" : خَنْدَقاً، أيْ تَجْوِيفاً فِي الأَرْضِ. 2. ""دَلاَّهُ فِي حُفْرَتِهِ"" : فِي قَبْرِهِ. ""مَنْ حَفَرَ حُفْرَةً لأَخِيهِ وَقَعَ فِيهَا"". (مثل) : يُضْرَبُ لِسُوءِ العَاقِبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8023, 'حُفَرٌ', 'حفر', 'جامد', '', 'حفر', 'حفر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8024, 'حَفْريَّاتٌ', 'حفريات', 'جامد', 'حفر', 'حفريات', 'حفرت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"حَفْريَّاتٌ-حَفْريَّاتٌ [ح ف ر].: ما يَقُومُ بِهِ عُلَمَاءُ الآثَارِ مِنْ حَفْرٍ وَتَنْقِيبٍ وَبَحْثٍ عَنِ الآثَارِ القَدِيمَةِ الَّتِي تَوَارَتْ تَحْتَ التُّرَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8025, 'حَفِيرَةٌ', 'حفيرة', 'جامد', 'حفر', 'حفيرة', 'حفرة', '', '', '', 'مفرد', 'DnN', '', '', '"حفَائِرُ"', '', '', '', '', '', '', '', '', '".: مَا حُفِرَ مِنَ الأَرْضِ، الحُفْرَةُ، الحَفِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8026, 'حفَائِرُ', 'حفائر', 'جامد', '', 'حفاءر', 'حفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8027, 'حَفِيرٌ', 'حفير', 'جامد', 'حفر', 'حفير', 'حفر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَفِيرٌ-حَفِيرٌ [ح ف ر]. 1. ""وَقَعَ فِي حَفِيرٍ"" : فِي حُفْرَةٍ. 2.""اِسْتَخْرَجَ الْمَاءَ مِنَ الحَفِيرِ"" : مِنْ بِئْرٍ مُوسَّعَةٍ. 3. ""وَضَعُوهُ فِي الحَفِيرِ"" : فِي القَبْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8028, 'مِحْفَارٌ', 'محفار', 'جامد', 'حفر', 'محفار', 'محفر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَحَافِيرُ"', '', 'R', '', '', '', '', '', '', '". ""تَنَاوَلَ المِحْفَارَ وَشَرَعَ يَحْفِرُ"" : آلَةُ الْحَفْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8029, 'مَحَافِيرُ', 'محافير', 'جامد', '', 'محافير', 'محفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8030, 'حِفَاضٌ', 'حفاض', 'جامد', 'حفض', 'حفاض', 'حفض', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""حِفاضُ الرَّضيعِ"" : قِطْعَةٌ مِنْ ثَوْبٍ شَفَّافٍ مَحْشُوَّةٌ بِالقُطْنِ أوْ مَا شَابَهَ ذَلِكَ تَضَعُهُ الْمَرْأةُ بَيْنَ فَخِذَيْ رَضِيعِهَا لِحِمَايَةِ مَلاَبِسِهِ وَسَرِيرِهِ مِنَ البَوْلِ أوِ البِرَازِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8031, 'حَفَضٌ', 'حفض', 'جامد', 'حفض', 'حفض', 'حفض', '', '', '', 'مفرد', 'DnN', '', '', '"أَحْفَاضٌ:حِفَاضٌ"', '', 'R', '', '', '', '', '', '', '". 1.""جَهَّزُوا الحَفَضَ لِلرَّحيلِ"" : مَتَاع البَيْتِ الْمُهَيَّأُ لِلحَمْلِ. 2.: الدَّابَّةُ الَّتِي تَحَمِلُ مَتَاعَ البَيْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8032, 'أَحْفَاضٌ', 'أحفاض', 'جامد', '', 'ءحفاض', 'حفض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8033, 'حِفَاضٌ', 'حفاض', 'جامد', '', 'حفاض', 'حفض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8034, 'حَفِيضَةٌ', 'حفيضة', 'جامد', 'حفض', 'حفيضة', 'حفضة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَفِيضَةٌ-حَفِيضَةٌ [ح ف ض].""اِجْتَمَعَ النَّحْلُ فِي الحَفِيضَةِ"" : فِي الخَلِيَّةِ. ""حَفِيضَةُ نَحْلٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8035, 'حافِظَةٌ', 'حافظة', 'جامد', 'حفظ', 'حافظة', 'حفظة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حافِظَةٌ-حافِظَةٌ [ح ف ظ]. 1.""لَهُ حافِظَةٌ قَوِيَّةٌ"" : الذَّاكِرَةُ والقُوَّةُ الَّتِي تَحْفَظُ الْمَعارِفَ والصُّوَرَ في الذِّهْنِ. 2. ""لا يملك شَيْئاً في حافِظَةِ نُقودِهِ"" : كيسٌ لِحِفْظِ النُّقودِ أَوِ الأوْراقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8036, 'حَفِيظَةٌ', 'حفيظة', 'جامد', 'حفظ', 'حفيظة', 'حفظة', '', '', '', 'مفرد', 'DnN', '', '', '"حَفائِظُ"', '', '', '', '', '', '', '', '', '". 1. ""أثَارَ حَفِيظَتَهُ"" : أثَارَ غَضَبَهُ. 2. ""حَفِيظَةُ الرَّجُلِ"" : حَمِيَّتُهُ. 3.""كَتَبَ لَهَا حَفِيظَةً لاِبْنِهَا"" : الحِرْزُ يُعَلَّقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8037, 'حَفائِظُ', 'حفائظ', 'جامد', '', 'حفاءظ', 'حفظ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8038, 'مِحْفَظَةٌ', 'محفظة', 'جامد', 'حفظ', 'محفظة', 'محفظة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَحَافِظُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِحْفَظَةُ نُقُودٍ"" : كِيسٌ صَغِيرٌ مِنَ الجِلْدِ أَوِ القُماشِ تُحْفَظُ فِيهِ قِطَعُ النُّقُودِ وَالأَوْرَاقُ الشَّخْصِيَّةُ. 2.""مِحْفَظَةُ الكُتُبِ"" : كِيسٌ مِنَ الجِلْدِ وَمَا شَابَهَهُ مُتَوَسِّطُ الْحَجْمِ تُوضَعُ فِيهِ الكُتُبُ وَالدَّفَاتِرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8039, 'مَحَافِظُ', 'محافظ', 'جامد', '', 'محافظ', 'محفظ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8040, 'حُفَافَةٌ', 'حفافة', 'جامد', 'حفف', 'حفافة', 'حففة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حُفَافَةٌ-حُفَافَةٌ [ح ف ف]. ""جمَعَ حُفَافَةَ شَعْرِهِ"" : مَا تَسَاقَطَ مِنَ الشَّعَرِ الْمَحْفُوفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8041, 'حِفَافٌ', 'حفاف', 'جامد', 'حفف', 'حفاف', 'حفف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حِفَافٌ-حِفَافٌ [ح ف ف]. 1. ""حِفَافُ الشَّيْءِ"" : مَا اسْتَدَارَ حَوْلَهُ وأَحْدَقَ بِهِ. 2 .""رَجُلٌ أصْلَعُ لَهُ حِفَافٌ"" : ما بَقِيَ مِنَ الشَّعْرِ حَوْلَ صَلْعَتِهِ. 3. ""حِفَافَا الجَبَلِ"" : جَانِبَاهُ. ""حِفَافَا الرَّأْسِ"" ""حِفَافا الْمَائِدَةِ"". 4. ""جَاءَ عَلَى حِفَافِ ذَلِكَ"" : فِي حِينِهِ وَإبَّانِهِ. 5. ""كَانَ الطَّعَامُ حِفَافَ مَا أكَلُوا"" : قَدْرَهُ لاَ يَزِيدُ وَلاَ يَنْقُصُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8042, 'حَفَفٌ', 'حفف', 'جامد', 'حفف', 'حفف', 'حف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَفَفٌ-حَفَفٌ [ح ف ف]. 1. ""جَاءَ عَلَى حَفَفِهِ"" : عَلَى أثَرِهِ. 2. ""طَعَامٌ حَفَفٌ"" : قَلِيلٌ. 3. ""يَعِيشُ حَيَاةَ حَفَفٍ"" : حَيَاةَ ضَيْقٍ وَعُسْرٍ وَقِلّةِ مَالٍ. 4. ""هُوَ عَلَى حَفَفِ السّاحَةِ"" : عَلَى نَاحِيَةٍ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8043, 'مِحَفَّةٌ', 'محفة', 'جامد', 'حفف', 'محفة', 'محفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَحَافُّ"', '', 'R', '', '', '', '', '', '', '". 1.""مِحَفَّةُ النِّسَاءِ"" : مُرَكَّبٌ بَسِيـطٌ يُشْبِـهُ الهَـوْدَجَ.2.""مِحَفَّةُ الْمَرِيضِ"" : سَرِيرٌ يُحْمَلُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8044, 'مَحَافُّ', 'محاف', 'جامد', '', 'محاف', 'محف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8045, 'اِحْتِفَالٌ', 'احتفال', 'جامد', 'حفل', 'احتفال', 'حتفل', '', '', '', 'مفرد', 'DnN', '', '', '"ـات"', '', 'R', '', '', '', '', '', '', '". ""أقَامُوا احْتِفَالاً"" : اِجْتِمَاعُ النَّاسِ فِي حَفْلٍ بِمُنَاسَبَةِ مَّا يَتِمُّ فِيهِ تَبَادُلُ التَّهَانِي وَإِقَامَةُ نَشَاطٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8046, 'حَفْلَةٌ', 'حفلة', 'جامد', 'حفل', 'حفلة', 'حفلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""أخَذَ لِلأَمْرِ حَفْلَتَهُ"": الجِدُّ وَالمبالغَةُ فِيهِ. 2.""دَعاهُ إلى حَفْلَةٍ"" : جَمْعٌ مُنَظَّمٌ يُقَدَّمُ فيهِ احْتِفالٌ. 3. ""نَظَّمَ حَفْلَةَ اسْتِقْبَالٍ عَلَى شَرَفِهِ"" : جَمْعٌ مِنَ النَّاسِ يَحْضُرُونَ لِلاحْتِفَالِ بِالشَّخْصِ الْمَعْنِيِّ...4. ""حَفْلَةٌ غِنَائِيَّةٌ"" : اِحْتِفَالٌ فِيهِ غِنَاءٌ. ""حَفْلَةٌ مُوسِيقِيَّةٌ"". 5. ""حَفْلَةٌ سَاهِرَةٌ"" : لِقَاءٌ لَيْلِيٌّ بَيْنَ أصْدِقَاءَ. 6.""حَفْلَةُ تَأْبِينٍ"" : اِجْتِمَاعُ جَمْعٍ مِنَ النَّاسِ لِرِثَاءِ مَيِّتٍ وَذِكْرِ مَآثِرِهِ. 7. ""حَفْلَةٌ دِينِيَّةٌ"" : لِقَاءُ جَمْعٍ مِنَ النَّاسِ فِي عِيدٍ دِينِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8047, 'حُقَالٌ', 'حقال', 'جامد', 'حفل', 'حقال', 'حقل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حُقَالٌ-حُقَالٌ [ح ف ل]. ""أُصِيبَتِ الْمَاشِيَةُ بِالحُقَالِ"" : داءٌ يُصيبُها إذَا أكَلَتْ بَقْلاً أوْ شَرِبَتْ مَاءً فِيهِ تُرَابٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8048, 'مَحْفَلٌ', 'محفل', 'جامد', 'حفل', 'محفل', 'محفل', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَافِلُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""اِلْتَقَى بِهِ فِي مَحْفَلٍ مَهِيبٍ"" : مَكَانُ اجْتِمَاعٍ لِمَوْضُوعٍ مَّا. 2. ""الْمَحَافِلُ الرَّسْمِيَّةُ"": الْمَجَالِسُ. ""الْمَحَافِلُ السِّيَاسِيَّةُ"" ""الْمحَافِلُ الدَّوْلِيَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8049, 'مَحَافِلُ', 'محافل', 'جامد', '', 'محافل', 'محفل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8050, 'حَفْنَةٌ', 'حفنة', 'جامد', 'حفن', 'حفنة', 'حفنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حُفَنٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""أعْطَاهُ حَفْنَةً مِنَ الدَّقِيقِ"" : مِلْءُ الكَفَّيْنِ. 2. ""تَعَرَّضَتْ لَهُ حَفْنَةٌ مِنَ الصَّعَالِيكِ"" : جَمَاعَةٌ، عَدَدٌ مَحْدُودٌ مِنْهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8051, 'حُفَنٌ', 'حفن', 'جامد', '', 'حفن', 'حفن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8052, 'حِقْبَةٌ', 'حقبة', 'جامد', 'حقب', 'حقبة', 'حقبة', '', '', '', 'مفرد', 'DnN', '', '', '"حِقَبٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""كَانَتْ حِقْبَةُ وِلاَيَتِهِ، حِقْبَةً تَارِيخِيَّةً مِنْ أَزْهَى الحِقَبِ"" : فَتْرَةُ حُكْمِهِ، مُدَّةً مِنَ الزَّمَنِ. 2. ""حِقْبَةٌ مِنَ الدَّهْرِ"" : الْمُدَّةُ لاَ وَقْتَ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8053, 'حِقَبٌ', 'حقب', 'جامد', '', 'حقب', 'حقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8054, 'حُقْبٌ', 'حقب', 'جامد', 'حقب', 'حقب', 'حقب', '', '', '', 'مفرد', 'DnN', '', '', '"حِقَابٌ:أَحْقَابٌ"', '', 'R', '', '', '', '', '', '', '". ""مَرَّتْ عَلَيْهِ حُقُبٌ"" : السِّنُونُ وَيُقْصَدُ بِهِ ثَمَانونَ سَنَةً أوْ أَكْثَرُ.الكهف آية 60 لاَ أبْرَحُ حَتَّى أبْلُغَ مَجْمَعَ البَحْرَيْنِ أوْ أَمْضِيَ حُقُبا (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8055, 'حِقَابٌ', 'حقاب', 'جامد', '', 'حقاب', 'حقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8056, 'أَحْقَابٌ', 'أحقاب', 'جامد', '', 'ءحقاب', 'حقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8057, 'أَحْقَادٌ', 'أحقاد', 'جامد', 'حقد', 'ءحقاد', 'حقد', '', '', '', 'مفرد', '', '', '', '"مفردحِقد"', '', '', '', '', '', '', '', '', '". ""مَلأَتْ قَلْبَهُ الأَحْقَادُ"": الضَّغَائِنُ. ن.حِقدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8058, 'حِقد', 'حقد', 'جامد', '', 'حقد', 'حقد', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8059, 'حَقِيدَةٌ', 'حقيدة', 'جامد', 'حقد', 'حقيدة', 'حقدة', '', '', '', 'مفرد', 'DnN', '', '', '"حَقَائِدُ"', '', '', '', '', '', '', '', '', '". ""أَضْمَرَ لَهُ حَقِيدَةً"" : ضَغينَةً، حِقْداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8060, 'حَقَائِدُ', 'حقائد', 'جامد', '', 'حقاءد', 'حقد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8061, 'مُحَقَّرَاتٌ', 'محقرات', 'جامد', 'حقر', 'محقرات', 'محقرت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُحَقَّرَاتٌ-مُحَقَّرَاتٌ [ح ق ر].: الصَّغَائِرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8062, 'مَحْقَرَةٌ', 'محقرة', 'جامد', 'حقر', 'محقرة', 'محقرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَحْقَرَةٌ-مَحْقَرَةٌ [ح ق ر]. ""تَعَرَّضَ لِلْمَحْقَرَةِ"" : لِلذُّلِّ وَالهَوَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8063, 'حُقَّةٌ', 'حقة', 'جامد', 'حقق', 'حقة', 'حقة', '', '', '', 'مفرد', 'DnN', '', '', '"حُقَقٌ:حِقَاقٌ"', '', 'R', '', '', '', '', '', '', '". 1.: وِعَاءٌ صَغِيرٌ ذُو غِطَاءٍ يُتَّخَذُ مِنْ عَاجٍ أوُ زُجَاجٍ أَوْ غَيْرِهِمَا، حُقٌّ. 2.: وِعَاءٌ صَغِيرٌ لَهُ قُفْلٌ ذُو فَتْحَةٍ يَدَّخِرُ فِيهِ الأَطْفَالُ الدَّرَاهِمَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8064, 'حُقَقٌ', 'حقق', 'جامد', '', 'حقق', 'حق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8065, 'حِقَاقٌ', 'حقاق', 'جامد', '', 'حقاق', 'حقق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8066, 'حُقٌّ', 'حق', 'جامد', 'حقق', 'حق', 'حق', '', '', '', 'مفرد', 'DnN', '', '', '"حِقَاقٌ:حُقوقٌ"', '', 'R', '', '', '', '', '', '', '". 1.""حُقُّ الطِّبِّ وَالدَّوَاءِ أوِ المِدَادِ"" : القارُورَةُ الصَّغِيرَةُ ذَاتُ غِطَاءٍ تُتَّخَذُ مِنْ عَاجٍ أوْ زُجَاجٍ أوْ غَيْرِهِمَا. 2. ""حُقُّ الفَخِذِ"" (هش) : النُّقْرَةُ التي فِيها رَأسُ الفَخِذِ. 3. ""حُقُّ الكَتِفِ"" (هش) : النُّقْرَةُ الَّتِي فِي رَأْسِ الكَتِفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8067, 'حِقَاقٌ', 'حقاق', 'جامد', '', 'حقاق', 'حقق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8068, 'حُقوقٌ', 'حقوق', 'جامد', '', 'حقوق', 'حقق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8069, 'حَقِيقَةٌ', 'حقيقة', 'جامد', 'حقق', 'حقيقة', 'حققة', '', '', '', 'مفرد', 'DnN', '', '', '"حَقَائِقُ"', '', 'R', '', '', '', '', '', '', '". 1. ""حَقِيقَةُ الأَمْرِ"" : وَاقِعُ الأَمْرِ، الوَاقِعُ كَمَا هُوَ، مَا هُوَ ثَابِتٌ وَصَحِيحٌ. ""اِكْتَشَفَ الْحَقِيقَةَ فَتَنَفَّسَ الصُّعَداءَ"" . ""اِعْتَرَفَ بِالْحَقِيقَةِ أَمَامَ القَاضِي"". 2. ""وَأَخِيراً بَدَا عَلَى حَقِيقَتِهِ"" : في صُوررَتِهِ كَما هُوَ عَلَيْها . 3. ""فِي الحَقِيقَةِ لَمْ أَكُنْ أَشُكُّ فِيهِ"" : فِي الوَاقِعِ. 4. ""حَقِيقَةً"" : بِلاَ رَيْبٍ، بِلا شَكٍّ. 5.""حَقِيقَةُ المادَّةِ"" : جَوْهَرُهَا، كُنْهُهَا. 6. ""الحَقِيقَةُ فِي اللُّغَةِ"" : اِسْتِعْمَالُ الكَلاَمِ فِي مَعْنَاهُ الأصْلِيِّ لاَ الْمَجَازِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8070, 'حَقَائِقُ', 'حقائق', 'جامد', '', 'حقاءق', 'حقق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8071, 'حَقْلَةٌ', 'حقلة', 'جامد', 'حقل', 'حقلة', 'حقلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حَقْلَةُ-حَقْلَةُ [ح ق ل]. 1.: الجُزْءُ مِنَ الحَقْلِ. 2.: دَاءُ الحُقَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8072, 'حَقْلٌ', 'حقل', 'جامد', 'حقل', 'حقل', 'حقل', '', '', '', 'مفرد', 'DnN', '', '', '"حُقُولٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""حَقْلٌ شَاسِعٌ"" : الأَرْضُ الْمَزْرُوعَةُ بِزَرْعٍ وَأَشْجَارٍ وَنَبَاتَاتٍ وَهِيَ فِي خُضْرَتِهَا. ""حُقُولٌ خَضْرَاءُ"". 2. تَنْتَشِرُ حُقُولُ النَّفْطِ فِي الجَزِيرَةِ العَرَبِيَّةِ"" : أَمَاكِنُ اسْتِخْرَاجِ البِتْرُولِ مِنْ طَبَقَاتٍ تَحْتَ الأَرْضِ. 3. ""حَقْلُ التَّجَارِبِ"" : الْمَكَانُ الَّذِي تُجْرَى فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8073, 'حُقُولٌ', 'حقول', 'جامد', '', 'حقول', 'حقل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8074, 'حَقْنَةٌ', 'حقنة', 'جامد', 'حقن', 'حقنة', 'حقنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حَقْنَةٌ-حَقْنَةٌ [ح ق ن]. وجَعٌ فِي البَطْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8075, 'حُقْنَةٌ', 'حقنة', 'جامد', 'حقن', 'حقنة', 'حقنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حُقَنٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""أَحْقَنَهُ بِحُقْنَةٍ"" : دَوَاء يُحْقَنُ بِهِ الْمَرِيضُ. 2. ""اِسْتَخْدَمَتْ حُقْنَةً جَدِيدَةً"" : الآلَةُ الَّتِي يُحْقَنُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8076, 'حُقَنٌ', 'حقن', 'جامد', '', 'حقن', 'حقن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8077, 'مِحْقَنَةٌ', 'محقنة', 'جامد', 'حقن', 'محقنة', 'محقنة', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَاقِنُ"', '', 'R', '', '', '', '', '', '', '". ن. مِحْقَنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8078, 'مَحَاقِنُ', 'محاقن', 'جامد', '', 'محاقن', 'محقن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8079, 'حَقْوَةٌ', 'حقوة', 'جامد', 'حقو', 'حقوة', 'حقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حَقْوَةٌ-حَقْوَةٌ [ح ق و]. ""اِرْتَدَتْ حَقْوَتَها"" : إزَارَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8080, 'حُكَرٌ', 'حكر', 'جامد', 'حكر', 'حكر', 'حكر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَكْرٌ-حَكْرٌ [ح ك ر] (مص. حَكَرَ). 1. ""شَعَرَ بِالْحَكْرِ"" : بِالظُّلْمِ وَسُوءِ العِشْرَةِ. 2. ""حَكْرُ الشَّيْءِ"" : القَلِيلُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8081, 'حَكّاكَةٌ', 'حكاكة', 'جامد', 'حكك', 'حكاكة', 'حككة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""اِنْتابَتْهُ الحَكَّاكاتُ"" : الوَسَاوِسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8082, 'حُكَاكٌ', 'حكاك', 'جامد', 'حكك', 'حكاك', 'حكك', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حُكَاكٌ-حُكَاكٌ [ح ك ك].: دَاءٌ جِلْدِيٌّ يُحَكُّ منْهُ، الجَرَبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8083, 'حِكّةٌ', 'حكة', 'جامد', 'حكك', 'حكة', 'حكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حِكّةٌ-حِكّةٌ [ح ك ك]. 1. ""سَاوَرَتْهُ الحِكَّةُ"" : الشَّكُ فِي الدِّينِ وَغَيْرِهِ. 2. ""بِهِ حِكَّةٌ"" : دَاءٌ يُصِيبُ الجِسْمَ فَيَضْطَرُّهُ إلَى الحَكِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8084, 'حُكٌّ', 'حك', 'جامد', 'حكك', 'حك', 'حك', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حُكٌّ-حُكٌّ [ح ك ك]. : إبْرَةٌ مِغْنَاطِيسِيَّةٌ عِنْدَ الْمَلاحِينَ تَتَّجِهُ دَائِماً إلَى الشَّمَالِ يَهْتَدُونَ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8085, 'مِحَكٌّ', 'محك', 'جامد', 'حكك', 'محك', 'محك', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِحَكٌّ-مِحَكٌّ [ح ك ك]. 1.""حَجَرُ المِحَكِّ"" : حَجَرٌ يُحَكُّ بِهِ الْمَعْدِنُ لِلاخْتِبَارِ وَالتَّجْرِيبِ. 2.""حَكَّ جِلْدَهُ بِمِحَكٍّ"" : مَا يُحَكُّ بِهِ الجِسْمُ. 3.""التَّجَارِبُ مِحَكُّ الرِّجَالِ"" : مُخْتَبَرُ الرِّجَالِ، مَجَالُ مَعْرِفَتِهِمْ. 4.""وُضِعَ عَلَى المِحَكِّ"" : وُضِعَ عَلَى سَبِيلِ الاخْتِبَارِ وَالتَّجْرِبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8086, 'أَحْكَامٌ', 'أحكام', 'جامد', 'حكم', 'ءحكام', 'حكم', '', '', '', 'مفرد', 'DnN', '', '', '"حُكْمٌ"', '', '', '', '', '', '', '', '', '". ""يُطَبِّقُ أحْكَامَ الشَّريعَةِ"": قَوَاعِدَهَا وشَرَائِعَهَا. ن.حُكْمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8087, 'حُكْمٌ', 'حكم', 'جامد', '', 'حكم', 'حكم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8088, 'حَكَمٌ', 'حكم', 'جامد', 'حكم', 'حكم', 'حكم', '', '', '', 'مفرد', 'DnN', '', '', '"حُكَّامٌ"', '', 'R', '', '', '', '', '', '', '"حَكَمٌ-حَكَمٌ [ح ك م]. 1. ""اِخْتَارُوهُ حَكَماً بَيْنَهُمَا"" : الفَاصِلُ بَيْنَهُمَا فِي نِزَاعٍ. النساء آية 35 وَإنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فابْعَثُوا حَكَماً مِنْ أهْلِهِ وَحَكَماً مِنْ أَهْلِهَا (قرآن). ""أنْتَ الخَصْمُ وَالحَكَمُ"" المتنبي). 2. ""سَيَّرَ الحَكَمُ الْمُبَارَاةَ تَسْييراً حَسناً"" : مَنْ يُسَيِّرُ الْمُبَارَيَاتِ الرِّيَاضِيَّةَ وَيَضْبِطُ سَيْرَها. 3. ""رَجُلٌ حَكَمٌ"": الْمُسِنُّ. 4. ""هُوَ اللَّهُ الحَكَمُ"" : مِنْ أسْمَاءِ اللَّهِ الحُسْنَى، أيِ الحَكِيمُ، الحَاكِمُ. 5. ""عَبْدُ الحَكَمِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8089, 'حُكَّامٌ', 'حكام', 'جامد', '', 'حكام', 'حكم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8090, 'مَحْكَمَةٌ', 'محكمة', 'جامد', 'حكم', 'محكمة', 'محكمة', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَاكِمُ"', '', 'R', '', '', '', '', '', '', '". 1.""عَرَضَ قَضِيَّتَهُ عَلَى الْمَحْكَمَةِ"" : مَجْلِسُ القُضَاةِ، هَيْئَةٌ تَتَوَلَّى الفَصْلَ فِي قَضَايَا النَّاسِ وَالْمُجْتَمَعِ وَتَتَنَوَّعُ صَلاَحِيَّتُهَا وَاخْتِصَاصَاتُهَا، مِنْهَا: ""مَحْكَمَةُ الجِنَايَاتِ""، ""مَحْكَمَةُ الاسْتِئْنَافِ""، ""الْمَحْكَمَةُ العَسْكَرِيَّةُ""، ""مَحْكَمَةُ العَدْلِ الدَّوْلِيَّةُ"". ""فَلِي مِنْ ضَمِيرِي مَحْكَمَةٌ تَقْضِي عَلَيَّ بِالعَدْلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8091, 'مَحَاكِمُ', 'محاكم', 'جامد', '', 'محاكم', 'محكم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8092, 'حَكِيٌّ', 'حكي', 'جامد', 'حكي', 'حكي', 'حك', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"حَكِيٌّ-حَكِيٌّ [ح ك ي]. ""اِسْتَغْرَقَ فِي الحَكِيِّ اللَّيْلَ كُلَّهُ"" : السَّرْدُ، رِوَايَةُ الحِكَايَاتِ. ""لِسَانُهَا لاَ يَتَوَقَّفُ عَنِ الحَكِيِّ"". (محمد برادة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8093, 'حالِبٌ', 'حالب', 'جامد', 'حلب', 'حالب', 'حلب', '', '', '', 'مفرد', '', '', '', '"مثنىحالِبانِ-الْحالِبانِ"', '', 'R', '', '', '', '', '', '', '"حالِبانِ-الْحالِبانِ [ح ل ب].: قَناتانِ يَجْرِي فيها البَوْلُ مِنَ الكِلْيَتَيْنِ إلى الْمَثانَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8094, 'حَلْبَةٌ', 'حلبة', 'جامد', 'حلب', 'حلبة', 'حلبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حَلائِبُ"', '', 'R', '', '', '', '', '', '', '". 1. ""اِنْطَلَقَ الخَيْلُ فِي حَلْبَةِ السِّبَاقِ"" : فِي مَيْدَانِ السِّبَاقِ. 2. ""حَلْبَةُ الرَّقْصِ"": سَاحَةٌ خَاصَّةٌ بِالرَّقْصِ. 3. ""حَلْبَةُ الْمُلاَكَمَةِ"" : مِنَصَّةٌ (مَنَصَّةٌ) تُحِيطُ بِهَا حِبَالٌ مِنْ جِهَاتِهَا الأرْبَعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8095, 'حَلائِبُ', 'حلائب', 'جامد', '', 'حلاءب', 'حلب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8096, 'حُلْبَةٌ', 'حلبة', 'جامد', 'حلب', 'حلبة', 'حلبة', '', '', '', 'مفرد', 'DnN', '', '', '"حُلَبٌ"', '', 'R', '', '', '', '', '', '', '"(نب).: نَباتٌ عُشْبِيٌّ مِنْ فَصِيلَةِ القَطَانِيَّاتِ، حَبُّهُ أصْفَرُ اللَّوْنِ، يُؤْكَلُ ويُعَالَجُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8097, 'حُلَبٌ', 'حلب', 'جامد', '', 'حلب', 'حلب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8098, 'حَلْبَةٌ', 'حلبة', 'جامد', 'حلب', 'حلبة', 'حلبة', '', '', '', 'مفرد', 'DnN', '', '', '"مثنىحَلْبَتَان-حَلْبَتَان"', '', 'R', '', '', '', '', '', '', '"حَلْبَتَان-حَلْبَتَان [ح ل ب].: الغَداةُ وَالعَشِيُّ، لأنَّ الحَلْبَ يَكُونُ فِيهِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8099, 'حَلِيبٌ', 'حليب', 'جامد', 'حلب', 'حليب', 'حلب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَلِيبٌ-حَلِيبٌ [ح ل ب]. 1. ""حَلِيبٌ صَافٍ"" : اللَّبَنُ الْمَحْلُوبُ. ""حَلِيبُ الشَّاةِ أَوِ النُّوقِ أَوِ البَقَرِ"" ""يَشْرَبُ القَهْوَةَ بِالحَلِيبِ"". 2. ""يَرْضَعُ حَلِيبَ أُمِّهِ"" : لَبَنَ أُمِّهِ. 3.""حَلِيبٌ مُرَكَّزٌ"" : لَبَنٌ ثَخِينٌ. 4. ""مَسْحُوقُ حَلِيبٍ"" : لَبَنٌ مُجَفَّفٌ يُصَبُّ عَلَيْهِ الْمَاءُ السَّاخِنُ فَيُحَوَّلُ حَلِيباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8100, 'مَحْلَبٌ', 'محلب', 'جامد', 'حلب', 'محلب', 'محلب', '', '', '', 'مفرد', 'DnN', '', '', '"مَحالِبُ"', '', 'R', '', '', '', '', '', '', '". 1.""أدْخَلَ البَقَرَةَ إلى الْمَحْلَبِ"": مَوْضِعُ الحَلْبِ. 2. (نب): نَبَاتٌ مِنْ فَصِيلَةِ الوَرْدِيَّاتِ، وَهُوَ نَوْعٌ مِنَ الكَرَزِ يُوجَدُ فِي الْمَنَاطِقِ الجَبَلِيَّةِ، مُرُّ الطَّعْمِ تُسْتَعْمَلُ بُذُورُهُ فِي الطِّبِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8101, 'مَحالِبُ', 'محالب', 'جامد', '', 'محالب', 'محلب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8102, 'مِحْلَبٌ', 'محلب', 'جامد', 'حلب', 'محلب', 'محلب', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَالِبُ"', '', 'R', '', '', '', '', '', '', '". ""عَادَتْ بِالْمِحْلَبِ وَهُوَ يَفِيضُ بِالْحَلِيبِ"" : الإِنَاء يُحْلَبُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8103, 'مَحَالِبُ', 'محالب', 'جامد', '', 'محالب', 'محلب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8104, 'حِلاَجَةٌ', 'حلاجة', 'جامد', 'حلج', 'حلاجة', 'حلجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حِلاَجَةٌ-حِلاَجَةٌ [ح ل ج]. ""مِهْنَةُ الحِلاجَة"": حِرْفَةُ الحَلاَّجِ، أيْ نَدْفُ القُطْنِ وَتَخْلِيصُهُ مِنْ بَذْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8105, 'حَلِيجٌ', 'حليج', 'جامد', 'حلج', 'حليج', 'حلج', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَلِيجٌ-حَلِيجٌ [ح ل ج]. ""حَلِيجُ قُطْنٍ"" : القُطْنُ وَقَدْ تَمَّ تَخْلِيصُهُ مِنْ بَذْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8106, 'مِحْلاَجٌ', 'محلاج', 'جامد', 'حلج', 'محلاج', 'محلج', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَالِيجُ"', '', 'R', '', '', '', '', '', '', '". ""يُحْلَجُ القُطْنُ بِالمِحْلاَجِ"" : آلَةٌ لِحَلْجِ القُطْنِ، مِحْلَجٌ، مِحْلَجَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8107, 'مَحَالِيجُ', 'محاليج', 'جامد', '', 'محاليج', 'محلج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8108, 'مَحْلَجٌ', 'محلج', 'جامد', 'حلج', 'محلج', 'محلج', '', '', '', 'مفرد', 'DnN', '', '', '"مَحالِجُ"', '', 'R', '', '', '', '', '', '', '".: مَوْضِعُ حَلْجِ القُطْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8109, 'مَحالِجُ', 'محالج', 'جامد', '', 'محالج', 'محلج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8110, 'حَلَزُونٌ', 'حلزون', 'جامد', '', 'حلزون', 'حلزن', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"حَلازِينُ"', '', 'R', '', '', '', '', '', '', '"ج: حَلازِينُ. (حو).: دُوَيِبَّةٌ بَحْرِيَّةٌ وَبَرِّيَّةٌ مِنْ فَصِيلَةِ الرَّخْوِيَّاتِ. تَعِيشُ دَاخِلَ صَدَفَةٍ لَوْلَبيَّةٍ ، تُؤْكَلُ بَعْدَ سَلْقِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8111, 'حَلازِينُ', 'حلازين', 'جامد', '', 'حلازين', 'حلزن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8112, 'حَلَزُونيَّاتٌ', 'حلزونيات', 'جامد', '', 'حلزونيات', 'حلزنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فصِيلَةٌ حَيَوَانِيَّةٌ مِنَ الرَّخْوِيَّاتِ الْمَعِدِيَّةِ الرِّئَوِيَّةِ، عَدِيدَةُ الأجْنَاسِ وَالأنْوَاعِ وَالأشْكَالِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8113, 'حِلْسٌ', 'حلس', 'جامد', '', 'حلس', 'حلس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَحْلاَسٌ:حِلَسَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَحْلاَسٌ، حِلَسَةٌ. ""وَضَعَ حِلْساً عَلَى ظَهْرِ دَابَّتِهِ"" : بِسَاطاً يُوضَعُ تَحْتَ السَّرْجِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8114, 'أَحْلاَسٌ', 'أحلاس', 'جامد', '', 'ءحلاس', 'حلس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8115, 'حِلَسَةٌ', 'حلسة', 'جامد', '', 'حلسة', 'حلسة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8116, 'حَلْفَاءُ', 'حلفاء', 'جامد', '', 'حلفاء', 'حلف', '', '', '', 'جمع تكسير', '', '', '', '"حُلْفٌ:حُلُفٌ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"ج: حُلْفٌ، حُلُفٌ. (نب).: ""حَلْفَاءُ اللِّحَافِ"" : مَادَّةٌ نَبَاتِيَّةٌ رَقِيقَةٌ تُشْبِهُ سَعَفَ النَّخْلِ تُحْشَى بِهَا الفُرُشُ، كَمَا تُصْنَعُ بِهَا الحِبَالُ وَالحَصَائِرُ وَالقُفَفُ وَالوَرَقُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8117, 'حُلْفٌ', 'حلف', 'جامد', '', 'حلف', 'حلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8118, 'حُلُفٌ', 'حلف', 'جامد', '', 'حلف', 'حلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8119, 'حَلْفَاةٌ', 'حلفاة', 'جامد', '', 'حلفاة', 'حلفة', '', '', '', 'جمع تكسير', '', '', '', '"واحِدَةُالحَلْفَاءِ"', '', '', '', '', '', '', '', '', '"واحِدَةُ الحَلْفَاءِ. (نب)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8120, 'حِلاَقَةٌ', 'حلاقة', 'جامد', 'حلق', 'حلاقة', 'حلقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حِلاَقَةٌ-حِلاَقَةٌ [ح ل ق]. 1. مِهْنَةُ الحِلاَقَةِ: حِرْفَةُ الحِلاَقَةِ، أَيْ إزَالَةُ شعْرِ الرَّأْسِ أوِ اللِّحْيَةِ وتَحْلِيقُهُمَا باعْتِدَالٍ. 2. ""آلَةُ الحِلاَقَةِ"" : الآلَةُ الَّتِي تُسْتَعْمَلُ لِلْحِلاَقَةِ وَالصَّابُونِ الْمُسْتَعْمَلِ لِلْغَرَضِ نَفْسِهِ. 3.""صَالُونُ الحِلاَقَةِ"" : مَحَلُّ الحَلاَّقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8121, 'حَلْقَةٌ', 'حلقة', 'جامد', 'حلق', 'حلقة', 'حلقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""حَلْقَةُ الأُذُنِ"": القُرْطُ. 2. ""تَكَوَّنَتْ حَلْقَةٌ مِنَ الجُمْهُورِ حَوْلَهُ"" : دَائِرَةٌ مِنِهُمْ. 3. كَانَ حَلْقَةَ اتِّصَالٍ بَيْنَهُمْ وَبَيْنَ الرَّئِيسِ"" : رابِطَةَ الاتِّصَالِ، صِلَةَ وَصْلٍ. ""حَلْقَةُ وَصْلٍ"". 4. ""يَدُورُ فِي حَلْقَةٍ مُفْرَغَةٍ"": هُوَ فِي وَضْعِيَّةٍ لاَ يَعْرِفُ كَيْفَ يَخْرُجُ مِنْهَا وَلاَ يَعْرِفُ كَيْفَ يَصِلُ إلَى مُبْتَغَاهُ. 5. ""دَقَّ حَلْقَةَ البَابِ"" : آلَة مِنْ حَدِيدٍ تَكُونُ دَائِرِيَّةً أوْ مُسْتَطِيلَةً مُلْصَقَةً بِالبَابِ لِيُقْرَعَ بِهَا. 6.""هُوَ فِي الحَلْقَةِ السَّابِعَةِ مِنْ عُمْرِهِ"" : فِي العَقْدِ السَّابِعِ. 7.""تَكَوَّنَتْ حَلْقَةٌ دِرَاسِيَّةٌ"" : مَجْموعَةٌ مِنَ الطُّلاَبِ تَحْتَ إِشْرَافِ أُسْتَاذٍ لِلْبَحْثِ وَالدِّرَاسَةِ. 8. ""حَلْقَةُ العَالِمِ"" : مَجْلِسُ عِلْمِهِ. 9. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8122, 'حَلَقٌ', 'حلق', 'جامد', 'حلق', 'حلق', 'حلق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَلَقٌ-حَلَقٌ [ح ل ق]. 1.: القُرْطُ، أيْ مَا يُوضَعُ مِنْ حَلْيٍ فِي الأذُنِ. 2.: الإبِلُ الْمَوْسُومَةُ بِالحَلْقَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8123, 'مِحْلَقٌ', 'محلق', 'جامد', 'حلق', 'محلق', 'محلق', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَالِقُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِحْلَقُ الشَّعْرِ"": آلَةُ حَلْقِ الشَّعْرِ. 2.""المِحْلَـقُ الكَهْرَبَائِيُّ"" : آلَةٌ كَهْرَبَائِيَّةٌ لِحَلْقِ شَعْرِ اللِّحْيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8124, 'مَحَالِقُ', 'محالق', 'جامد', '', 'محالق', 'محلق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8125, 'حُلْقُومٌ', 'حلقوم', 'جامد', 'حلقم', 'حلقوم', 'حلقم', '', '', '', 'مفرد', 'DnN', '', '', '"حَلاَقِيمُ:حَلاَقِمُ"', '', 'R', '', '', '', '', '', '', '".: عُضْوٌ مُجَوَّفٌ فِي أقْصَى الفَمِ يُؤَدِّي إلَى القَصَبَةِ الهَوَائِيَّةِ وَهُوَ مَجْرَى النَّفَسِ والطَّعَامِ وَالشَّرَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8126, 'حَلاَقِيمُ', 'حلاقيم', 'جامد', '', 'حلاقيم', 'حلقم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8127, 'حَلاَقِمُ', 'حلاقم', 'جامد', '', 'حلاقم', 'حلقم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8128, 'حَلْكَةٌ', 'حلكة', 'جامد', 'حلك', 'حلكة', 'حلكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حَلْكَةٌ-حَلْكَةٌ (حو) [ح ل ك].: دُوَيِبَّةٌ، تُشْبِهُ العَظَاءةُ، تَغُوصُ فِي الرَّمْلِ إذَا أَحَسَّتْ بِالإنْسَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8129, 'حُلْكَةٌ', 'حلكة', 'جامد', 'حلك', 'حلكة', 'حلكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حُلْكَةٌ-حُلْكَةٌ [ح ل ك]. ""اِشْتَدَّتْ حُلْكَةُ اللَّيْلِ"" : اِشْتَدَّ سَوَادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8130, 'حَلَّةٌ', 'حلة', 'جامد', 'حلل', 'حلة', 'حلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حَلَّةٌ-حَلَّةٌ [ح ل ل].: إنَاءُ الطَّبْخِ مِنَ الْمَعْدِنِ أوْ غَيْرِه، كَبِيرُ الحَجْمِ. ""الحَلَّةُ الكَاتِمَةُ"" : ن. حُدَمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8131, 'حُلَّةٌ', 'حلة', 'جامد', 'حلل', 'حلة', 'حلة', '', '', '', 'مفرد', 'DnN', '', '', '"حُلَلٌ:حُلاَلٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""اِرْتَدَى حُلَّةً عَصْرِيَّةً"" : أيْ زَيّاً جَدِيداً. 2. ""يَرْتَدِي الحُلَّةَ الرَّسْمِيَّةَ فِي أَوْقَاتِ العَمَلِ"" : اللِّبَاسُ الرَّسْمِيُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8132, 'حُلَلٌ', 'حلل', 'جامد', '', 'حلل', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
