INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8134, 'حُلُولِيَّةٌ', 'حلولية', 'جامد', 'حلل', 'حلولية', 'حللة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حُلُولِيَّةٌ-حُلُولِيَّةٌ [ح ل ل]. ""فِرْقَةُ الحلُوليَّةِ"" : طَائِفَةٌ مِنَ الصُّوفِيَّةِ تَعْتَقِدُ مَذْهَبَ الحُلُولِ عَلَى غَيْرِ مَا قَالَ بِهِ أهْلُ السُّنَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8135, 'حَلِيلَةٌ', 'حليلة', 'جامد', 'حلل', 'حليلة', 'حللة', '', '', '', 'مفرد', 'DnN', '', '', '"حَلاَئِلُ"', '', 'R', '', '', '', '', '', '', '". 1. ""حَلِيلَةُ الرَّجُلِ"" : زَوْجَتُهُ. 2. ""حَلِيلَتُكَ تَسْألُ عَنْكَ"" : جَارَتُكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8136, 'حَلاَئِلُ', 'حلائل', 'جامد', '', 'حلاءل', 'حلل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8137, 'حَلِيلٌ', 'حليل', 'جامد', 'حلل', 'حليل', 'حلل', '', '', '', 'مفرد', 'DnN', '', '', '"أَحِلاَّءُ"', '', 'R', '', '', '', '', '', '', '". 1. ""رَأيْتُ حَلِيلَكَ"" : زَوْجَكَ أوْ مَنْ يُقِيمُ مَعَكَ فِي دَارٍ وَاحِدَةٍ. 2. ""شَيْءٌ حَلِيلٌ"" : حَلاَلٌ. 3. ""حَلِيلُ الدَّارِ"" : الجارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8138, 'أَحِلاَّءُ', 'أحلاء', 'جامد', '', 'ءحلاء', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8139, 'مَحَلَّةٌ', 'محلة', 'جامد', 'حلل', 'محلة', 'محلة', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَالٌّ"', '', 'R', '', '', '', '', '', '', '". ""مَحَلَّةُ القَوْمِ"" : مَنْزِلُهُمْ."', '');
