INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8141, 'مَحَلٌّ', 'محل', 'جامد', 'حلل', 'محل', 'محل', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَالُّ"', '', 'Rp', '', '', '', '', '', '', '". 1.""فِي مَحَلِّ إِقَامَتِهِ"" : فِي مَكَانِ إِقَامَتِهِ. 2.""الْمَحَلُّ التِّجَارِيُّ"" : الْحَانُوتُ، الدُّكَّانُ. 3.""اِشْتَغَلَ فِي مَحَلِّهِ"" : فِي مَكَانِهِ الْمُنَاسِبِ. ""رَأْيٌ فِي مَحَلِّهِ"" ""كَلاَمٌ فِي مَحَلِّهِ"". 4.""آرَاءٌ فِي غَيْرِ مَحَلِّهَا"" : غَيْرُ مُنَاسِبَةٍ، غَيْرُ مُوَافِقَةٍ. 5.""لاَ مَحَلَّ لَهُ"" : لاَ مَوْضِعَ لَهُ. 6."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8142, 'مَحَالُّ', 'محال', 'جامد', '', 'محال', 'محل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8143, 'حَلَمَةٌ', 'حلمة', 'جامد', 'حلم', 'حلمة', 'حلمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حَلَمٌ"', '', 'R', '', '', '', '', '', '', '". ""أَعْطَتِ الحَلَمَةَ لِرَضِيعِهَا"": رَأَسَ الثَّدْيِ الَّذِي يَمُصُّهُ الرَّضِيعُ وَيَخْرُجُ مِنْهُ اللَّبَنُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8144, 'حَلَمٌ', 'حلم', 'جامد', '', 'حلم', 'حلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8145, 'حَلْواءُ', 'حلواء', 'جامد', 'حلو', 'حلواء', 'حل', '', '', '', 'مفرد', '', '', '', '"حَلاوَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '".: حَلْوَى. ""أُريدُ حَلْواءَ، هَذِهِ هِيَ العِبارَةُ الَّتِي ظَلَّ يُرَدِّدُها الطِّفْلُ إلى أَنِ اسْتَغْرَقَهُ النَّوْمُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8146, 'حَلاوَى', 'حلاوى', 'جامد', '', 'حلاوى', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8147, 'حُلْوِيَّاتٌ', 'حلويات', 'جامد', 'حلو', 'حلويات', 'حلت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"حُلْوِيَّاتٌ-حُلْوِيَّاتٌ [ح ل و]. ""حَرَّكَتْ رَائِحَةُ الحُلْوِيَّاتِ شَهِيَّتَهُ"": كُلُّ أنْوَاعِ الأَطْعِمَةِ النَّشَوِيَّةِ الْمَعْقُودَةِ بِالسُّكَّرِ وَالسَّمْنِ وَالعَسَلِ وَمَا إلَى ذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8148, 'حَلَوِيَّةٌ', 'حلوية', 'جامد', 'حلو', 'حلوية', 'حلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '".: صِنَاعَةُ الحَلْوَى وَالاتِّجَارُ فِيهَا ؛ دُكَّانُ الحَلْوَانِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8149, 'حَلْوَى', 'حلوى', 'جامد', 'حلو', 'حلوى', 'حل', '', '', '', 'مفرد', 'Dy', '', '', '"حَلاَوى"', 'ممنوع من الصرف', 'R0', '', '', '', '', '', '', '". 1. ""قَدَّمَ لِطِفْلِهِ الحَلْوَى"": مَا يُصْنَعُ مِنَ الدَّقِيقِ وَالسُّكَّرِ وَالسَّمْنِ وَاللَّوْزِ. وَالعَسَلِ. أَوْ مِنَ السُّكَّرِ الْمُصَفَّى. اِمْتَلأَتِ الصُّحُونُ بِأنْوَاعِ الحَلاَوَى شَرْقِيَّةً وَغَرْبِيَّةً"". 2. ""فَاكِهَةٌ حُلْوَى"": طَيِّبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8150, 'حَلاَوى', 'حلاوى', 'جامد', '', 'حلاوى', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8151, 'حِلْيَةٌ', 'حلية', 'جامد', 'حلي', 'حلية', 'حلة', '', '', '', 'مفرد', 'DnN', '', '', '"حِلىً"', '', '', '', '', '', '', '', '', '". 1. ""لَبِسَتِ العَرُوسُ الحِلْيَةَ"": أيْ مَا يُزَيَّنُ بِهِ مِنْ جَوَاهِرَ وَأَحْجَارٍ كَرِيمَةٍ وَمَا يُصَاغُ مِنْ مَعَادِنَ ثَمِينَةٍ. 2. ""حِلْيَةُ الإِنْسَانِ"" : صِفَتُهُ، خِلْقَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8152, 'حِلىً', 'حلى', 'جامد', '', 'حلى', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8153, 'حَلْيٌ', 'حلي', 'جامد', 'حلي', 'حلي', 'حل', '', '', '', 'مفرد', 'DnN', '', '', '"حُلِيٌّ"', '', 'Rw', '', '', '', '', '', '', '". ""لَبِسَتْ أفْخَرَ مَا كَانَتْ تَمْلِكُهُ مِن حُلِيٍّ"" : جَوَاهِرُ وَأحْجَارٌ كَرِيمَةٌ، أيْ مَا يُصَاغُ مِنَ الْمَعَادِنِ الثَّمِينَةِ. ""صَاغَةُ الذَّهَبِ وَالفِضَّةِ صَنَعُوا مِنْهَا مَا يُعْجِبُ النَّاسَ مِنَ الحُلِيِّ""(ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8154, 'حُلِيٌّ', 'حلي', 'جامد', '', 'حلي', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8155, 'حُلَيْمَاتٌ', 'حليمات', 'جامد', '', 'حليمات', 'حلمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": وَهِيَ نَوْعَانِ : أ. ""حُلَيْمَاتٌ عُلْيَا"" : أيْ الرَّوَاسِبُ الكِلْسِيَّةُ الْمُتَحَجِّرَةُ فِي سُقُوفِ الْمَغَاوِرِ. ب.""حُلَيْمَاتٌ سُفْلَى"" : أيِ الرَّوَاسِبُ الكِلْسِيَّةُ الْمُتَحَجِّرَةُ فِي أَسْفَلِ الْمَغَاوِرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8156, 'حَمْأةٌ', 'حمأة', 'جامد', 'حمأ', 'حمءة', 'حمة', '', '', '', 'مفرد', 'DnN', '', '', '"حَمَأٌ"', '', 'Rz', '', '', '', '', '', '', '". ""تَرَاكَمَتِ الحَمْأةُ فِي السَّاحَةِ"": الطِّينُ الأسْوَدُ الْمُنْتِنُ الْمُتَغَبِّرُ. ""غَاصَ بِهَا فِي حَمْأةِ الرَّذِيلَةِ"" (ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8157, 'حَمَأٌ', 'حمأ', 'جامد', '', 'حمء', 'حم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8158, 'حِمَارٌ', 'حمار', 'جامد', '', 'حمار', 'حمر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"حَمِيرٌ:حُمُرٌ:حَمَائِرُ"', '', 'R', '', '', '', '', '', '', '"ج: حَمِيرٌ، حُمُرٌ، حَمَائِرُ. (حو). 1.: حَيوانٌ مِنْ فَصِيلَة الخَيْلِيَّاتِ أهْلِيٌّ، طَوِيـلُ الأُذُنَيْـنِ، يَحْمِلُ الأثْقَالَ، صَبُورٌ. 2.""نَعَتَهُ بِالحِمَارِ"" : كِنَايَـةً عَـنْ بَلاَدَتِهِ.الجمعة آية 5 كَمَثَلِ الحِمَارِ يَحْمِلُ أَسْفَاراً (قرآن). 3.""صَاحَ صَيْحَةَ حِمَارٍ"": كِنَايَةً عَنْ نَعِيقِهِ الْمُزْعِجِ.لقمان آية 19 واغْضُضْ مِنْ صَوْتِكَ إنَّ أنْكَرَ الأَصْوَاتِ لَصَوْتُ الحَمِيرِ . (قرآن) ""نَهَقَ الحِمارُ نَهيقاً"". 4.""أثَارَ اِنْتِبَاهَهُ الحِمَارُ الوَحْشِيُّ وَهُوَ يَتَجَوَّلُ فِي حَدِيقَةِ الحَيَوَانَاتِ"" : نَوْعٌ مِنْ أنْواعِ الحَمِيرِ مِنْ فَصِيلَةِ الخَيْلِيَّاتِ، مُخَطَّطٌ بِخُطُوطٍ سَوْدَاءَ وَبَيْضَاءَ ويُسَمَّى أيْضاً حِمَارَ الزَّرَدِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8159, 'حَمِيرٌ', 'حمير', 'جامد', '', 'حمير', 'حمر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
