INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8165, 'حُمَمٌ', 'حمم', 'جامد', '', 'حمم', 'حم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8166, 'حَمَمٌ', 'حمم', 'جامد', '', 'حمم', 'حم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8167, 'حُمَةٌ', 'حمة', 'جامد', '', 'حمة', 'حمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":حُمًى"', '', 'R', '', '', '', '', '', '', '"ج: حُمًى، حُمَاتٌ. 1. ""حُمَةُ الأفْعَى"" : سُمُّهَا، أيْ سُمُّ كُلِّ مَا يَلْذَغُ وَيَلْسَعُ. 2. ""ضَربَهَا بِحُمَةٍ"" : الإبْرَةُ الَّتِي تَضْرِبُ بِهَا العَقْرَبُ وَالزُّنْبُورُ ونَحْوُهُما. 3. ""حُمَةُ البَرْدِ"" : شِدَّتُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8168, 'حُمًى', 'حمى', 'جامد', '', 'حمى', 'حم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8169, 'حَمَاحِمُ', 'حماحم', 'جامد', 'حمحم', 'حماحم', 'حمحم', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَمَاحِمُ-حَمَاحِمُ، ةٌ [ح م ح م] (نب). ""تَفُوحُ رَائِحَةُ الحَمَاحِمِ فِي جَوِّ البُسْتَانِ"" : نَبَاتُ الحَبَقِ، لَهُ وَرَقٌ عَرِيضٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8170, 'حِمْحَمٌ', 'حمحم', 'جامد', 'حمحم', 'حمحم', 'حمحم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حِمْحَمٌ-حِمْحَمٌ [ح م ح م]. 1. ""لَوْنٌ حِمْحَمٌ"" : أَسْوَدُ. 2.:نَبَاتٌ عُشْبِيٌّ مِنْ فَصِيلَةِ الحِمْحَمِيَّاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8171, 'حِمْحَمِيَّاتٌ', 'حمحميات', 'جامد', '', 'حمحميات', 'حمحمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"فَصِيلَةٌ نَبَاتِيَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8172, 'مَحْمَدَةٌ', 'محمدة', 'جامد', 'حمد', 'محمدة', 'محمدة', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَامِدُ"', '', 'R', '', '', '', '', '', '', '". ""وَجَدَ فِي عَمَلِهِ مَحْمَدَةً"" : مَا يُحْمَدُ الْمَرْءُ بِهِ أَوْ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8173, 'مَحَامِدُ', 'محامد', 'جامد', '', 'محامد', 'محمد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8174, 'حُمْرَةٌ', 'حمرة', 'جامد', 'حمر', 'حمرة', 'حمرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حُمْرَةٌ-حُمْرَةٌ [ح م ر]. 1. ""اِكْتَسَى الأفُقُ حُمْرَةً"" : الشَّفَقُ وَقَدِ اصْطَبَغَ بِلَوْنٍ أحْمَرَ. 2. ""طَلاهُ بِحُمْرَةٍ"" : صِبَاغَةٌ تُحَمِّرُ اللَّوْنَ. ""نُطْبِقُ فِي حِرْصٍ عَلَى مَنْدِيلٍ قَانِي الحُمْرَةِ"". (ع. غلاب). 3. ""أَنْهَكَ جِسْمَهُ وَبَاءُ الحُمْرَةِ"" : مَرَضٌ مُعْدٍ يُسَبِّبُ حُمَّى، وَبُقَعاً حُمْراً فِي الجسْمِ تُؤَدِّي إلَى الْتِهَابٍ فِي الجِلْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8175, 'حَمَاسٌ', 'حماس', 'جامد', 'حمس', 'حماس', 'حمس', '', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"حَمَاسٌ-حَمَاسٌ [ح م س]. 1. ""اُسْتُقْبِلَ بِحَمَاسٍ شَدِيدٍ"" : شِدَّةُ الانْدِفَاعِ وَحِدَّتُهُ، الحَمِيَّةُ. 2. ""أظْهَرَ حَمَاساً بَالِغاً"" : حَيَوِيَّةً، نَشَاطاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8176, 'حِمَّصٌ', 'حمص', 'جامد', 'حمص', 'حمص', 'حمص', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حِمَّصٌ-حِمَّصٌ، ةٌ [ح م ص] (نب).: مِنْ فَصِيلَةِ القَطَانِيَّاتِ، حَبَّتُهُ كُرَوِيَّةٌ صَفْرَاءُ اللَّوْنِ، تُحَضَّرُ مِنْهُ أَكْلاتٌ مُتَعدِّدَةٌ، يُؤْكَلُ مَقْلِيّاً أوْ مَطْبُوخاً أَوْ مَطْحُوناً. ""أشْهَرُ أَكْلَةٍ شَرْقِيَّةٍ : الحِمَّصُ بِالطَّحِينَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8177, 'حُمَّاضٌ', 'حماض', 'جامد', 'حمض', 'حماض', 'حمض', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حُمَّاضٌ-حُمَّاضٌ، ةٌ (نب) [ح م ض]. 1. ""يُعْجِبُهُ أَنْ يَكُونَ الْحُمَّاضُ عَلَى مَائِدَةِ طَعَامِ الغَدَاءِ"" : نَبَاتٌ عُشْبِيٌّ، بَرِّيٌّ مِنْ فَصِيلَةِ الحُمَّاضِيَّاتِ، طَعْمُهُ حَامِضٌ، وَتُطْلَقُ عَلَيْهِ العَامَّةُ الحُمَّيْضَةُ، وَهُوَ يُزْرَعُ بَقْلاً. 2.: مَا فِي جَوْفِ الأتْرُجِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8178, 'حَمْضٌ', 'حمض', 'جامد', 'حمض', 'حمض', 'حمض', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"حُمُوضٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""نَبَاتٌ حَمْضٌ"" : كُلُّ نَبْتٍ مَالِحٍ أوْ حَامِضٍ يَقُومُ عَلَى ساقٍ وَلاَ أَصْلَ لَهُ. 2. ""نَفْسٌ حَمْضَةٌ"" : تَنْفِرُ مِنَ الشَّيْءِ لَدى سَمَاعِهِ. ""فُؤَادٌ حَمْضٌ"". 3. حَمْضُ النَّتْرِيكِ"" : سَائِلٌ عَدِيمُ اللَّوْنِ، مِنْ أقْوَى الْمَوَادِّ الْمُؤَكْسَدَةِ، يَتَفَاعَلُ مَعَ مُجْمَلِ الفِلِزّاتِ، يُسْتَعْمَلُ فِي صِنَاعَةِ الْمَوَادِّ البلاسْتِيكِيَّةِ وَالأدْوِيَةِ وَالْمُتَفَجِّرَاتِ. 4.""الحَمْضُ الْمَائِيُّ"" : حَامِضُ اتِّحَادِ الهِيدْرُوجِينِ بِعُنْصُرٍ حَمْضِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8179, 'حُمُوضٌ', 'حموض', 'جامد', '', 'حموض', 'حمض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8180, 'حَمْضِيَّاتٌ', 'حمضيات', 'جامد', 'حمض', 'حمضيات', 'حمضت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"حَمْضِيَّاتٌ-حَمْضِيَّاتٌ [ح م ض]. 1. ""مُتَخَصِّصٌ فِي بَيْعِ الحَمْضِيَّاتِ"" : الفَوَاكِهُ ذَاتُ الحُمُوضَةِ : البُرْقُوقُ واللَّيْمُونُ الحُلْوُ، وَاللَّيْمونُ الحَامِضُ. 2.: أشْجَارٌ نَبَاتِيَّةٌ تَشْمَلُ البُرْتُقَالَ وَاللَّيْمُونَ وَالأَتْرُجَّ وَنَحوَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8181, 'حَوَامِضُ', 'حوامض', 'جامد', 'حمض', 'حوامض', 'حمض', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَوَامِضُ-حَوَامِضُ [ح م ض]. ""اِرْتَفَعَتْ صَادِرَاتُ الحَوَامِضِ"": اللَّيْمُونُ وَالبُرْتُقَالُ وَنَحْوُهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8182, 'حَمَاقٌ', 'حماق', 'جامد', 'حمق', 'حماق', 'حمق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَمَاقٌ-حَمَاقٌ، حُمَاقٌ [ح م ق]. : مَرَضٌ يُشْبِهُ الجُدَرِيَّ، يُصِيبُ جِسْمَ الإنْسَانِ وَيَنْتَشِرُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8183, 'حامولَةٌ', 'حامولة', 'جامد', 'حمل', 'حامولة', 'حملة', '', '', '', 'مفرد', 'DnN', '', '', '"حَواميلُ"', '', 'R', '', '', '', '', '', '', '". ""تَدَفَّقَتْ حامولَةُ السَّيْلِ"" : الماءُ الْمُتَدَفِّقُ سَيْلاً عِنْدَ اشْتِدادِ الْمَطَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8184, 'حَواميلُ', 'حواميل', 'جامد', '', 'حواميل', 'حمل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8185, 'حِمَالَةٌ', 'حمالة', 'جامد', 'حمل', 'حمالة', 'حملة', '', '', '', 'مفرد', 'DnN', '', '', '"حَمَائِلُ"', '', '', '', '', '', '', '', '', '". 1.""حِرْفَةُ الحِمَالَةِ"" : حِرْفَةُ الحَمَّالِ. 2. ""حِمَالَةُ السَّيْفِ"" : عِلاَقَتُهُ. 3. ""حِمَالَةُ الصَّدْرِ"" : مَا يُشَدُّ بِهِ النَّهْدُ. ن. صَدِيرَة، إثَارٌ. 4.""لَمْ يَعُدْ بِإمْكَانِهِ أنْ يَلْبَسَ سَرَاوِيلَهُ دُونَ حِمَالَةٍ"" : سُيُورٌ مِنْ أنْسِجَةٍ مَطَّاطَةٍ أوْ خُيُوطٍ قُطْنِيَّةٍ أوْ جِلْدِيَّةٍ يُشَدُّ بِهَا السِّرْوَالُ مِنَ الخَلْفِ إلَى الأَمَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8186, 'حَمَائِلُ', 'حمائل', 'جامد', '', 'حماءل', 'حمل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8187, 'حَمَلَةٌ', 'حملة', 'جامد', 'حمل', 'حملة', 'حملة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"مفردحامِل"', '', 'R', '', '', '', '', '', '', '". 1. ""هُوَ مِنْ حَملَةِ القُرآنِ"" : مِنْ حَفَظَتِهِ. 2. ""مِنْ حَمَلَةِ الأقْلاَمِ"" : مِنَ الكُتَّابِ، مِنَ الصُّحُفِيِّينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8188, 'حَمَلٌ', 'حمل', 'جامد', 'حمل', 'حمل', 'حمل', '', '', '', 'مفرد', 'DnN', '', '', '"حُمْلاَنٌ:أَحْمَالٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""حَمَلٌ يَجْرِي خَلْفَ القَطِيعِ"" : صَغِيرُ أَوْلاَدِ الضَّأْنِ. 2. ""مِنْ مَوَالِيدِ بُرْجِ الحَمَلِ"" : مِنَ البُرُوجِ الرَّبيِعيَّةِ يَبْتَدِئُ مِنْ 21 مَارِسَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8189, 'حُمْلاَنٌ', 'حملان', 'جامد', '', 'حملان', 'حملن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
