INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8191, 'حَمْلٌ', 'حمل', 'جامد', 'حمل', 'حمل', 'حمل', '', '', '', 'مفرد', 'DnN', '', '', '"أَحْمَالٌ:حُمُولٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""ظَهَرَ حَمْلُ زَوْجَتِهِ"" : ظَهَرَ أنَّ فِي بَطْنِهَا جَنِيناً، حَامِلٌ. 2.""حَمْلُ الشَّجَرَةِ"": فَوَاكِهُهَا، أيْ مَا تُخْرِجُهُ مِنْ ثَمَرٍ. 3.""حَمَلُوهَا فِي الحَمْلِ"" : فِي الهَوْدَجِ."', '');
