INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8194, 'حِمْلٌ', 'حمل', 'جامد', 'حمل', 'حمل', 'حمل', '', '', '', 'مفرد', 'DnN', '', '', '"أحْمَالٌ:حُمُولَةٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""حِمْلُ الشَّاحِنَةِ"" : أَثْقَالُهَا، مَا تَحْمِلُهُ. 2. ""أنْهَكَهُ حِمْلُ السِّنِينَ"": ثِقْلُهَا."', '');
