INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8197, 'حُمُولَةٌ', 'حمولة', 'جامد', 'حمل', 'حمولة', 'حملة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""حُمُولَةُ شَاحِنَةٍ"" : مَا يُحْمَلُ عَلَيْهَا. ""كَانَتِ العَرَبَتَانِ قَدْ أفْرَغَتَا حُمُولَتَهُمَا وَعَادَتَا"" (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8198, 'مَحْمَلٌ', 'محمل', 'جامد', 'حمل', 'محمل', 'محمل', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَامِلُ"', '', 'R', '', '', '', '', '', '', '". ""أَخَذَ كَلاَمَهُ عَلَى مَحْمَلِ الجِدِّ"" : أَخَذَهُ بِعَيْنِ الاعْتِبَارِ وَالأَهَمِّيَّةِ. ""يُحْمَلُ عَلَى مَحْمَلِ السُّوءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8199, 'مَحَامِلُ', 'محامل', 'جامد', '', 'محامل', 'محمل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
