INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8203, 'حَمَامَةٌ', 'حمامة', 'جامد', 'حمم', 'حمامة', 'حممة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حَمَائِمُ"', '', 'R', '', '', '', '', '', '', '"(حو) (وَاحِدَةُ الحَمَامِ). وَهِيَ لِلذَّكَرِ وَالأُنْثَى.: طَائِرٌ مِنْ فَصِيلَةِ الحَمَامِيَّاتِ، مِنْ رُتْبَةِ الحَمَامِيَّاتِ، وَهُوَ أَنْوَاعٌ مِنْهَا اليَمَامُ، وَالحَمَامُ الأزْرَقُ، وَالدَّاجِنُ، وَالزَّاجِلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8204, 'حَمَائِمُ', 'حمائم', 'جامد', '', 'حماءم', 'حمم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8205, 'حَمَّامٌ', 'حمام', 'جامد', 'حمم', 'حمام', 'حمم', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. تَجِدُ فِي كُلِّ حَيٍّ مِنْ أحْيَاءِ الْمَدِينَةِ حَمَّاماً لِلنِّسَاءِ وآخَرَ لِلرِّجَالِ"" : مَحَلٌّ عُمُومِيٌّ لِلاسْتِحْمَامِ وَالاغْتِسَالِ. 2. ""غُرْفَةُ الحَمَّامِ"" : غُرْفَةُ الاسْتِحْمَامِ بِالْمَنْزِلِ. 3. ""أخَذَتْ حَمَّامَ شَمْسٍ"" : أيْ عَرَضَتْ جِسْمَهَا لِحَرَارَةِ الشَّمْسِ. 4.""حَمَّامُ السِّبَاحَةِ"" : حَوْضٌ كَبِيرٌ مُعَدٌّ لِلسِّبَاحَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8206, 'حَمَامٌ', 'حمام', 'جامد', 'حمم', 'حمام', 'حمم', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حَمَائِمُ"', '', 'R', '', '', '', '', '', '', '"(حو). ن : حَمَامَةٌ."', '');
