INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8208, 'حَمَّة', 'حمة', 'جامد', 'حمم', 'حمة', 'حمة', '', '', '', 'مفرد', 'DnN', '', '', '"حَمٌّ:حِمَامٌ"', '', 'R', '', '', '', '', '', '', '". ""نَصَحَهُ الطَّبِيبُ بِالاسْتِحْمامِ فِي الحَمَّةِ"" : عَيْنٌ تَقْذِفُ مَاءً مَعْدِنِيّاً حَارّاً. ""حَمَّةُ مَوْلاَي يَعْقُوب""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8209, 'حَمٌّ', 'حم', 'جامد', '', 'حم', 'حم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8210, 'حِمَامٌ', 'حمام', 'جامد', '', 'حمام', 'حمم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8211, 'حِمَّةٌ', 'حمة', 'جامد', 'حمم', 'حمة', 'حمة', '', '', '', 'مفرد', 'DnN', '', '', '"حِمَمٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""اِقْتَرَبَتْ حِمَّتُهُ"" : مَنِيَّتُهُ، مَوْتُهُ. 2. ""تَصَبَّبَ حِمَّةً"" : عَرَقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8212, 'حِمَمٌ', 'حمم', 'جامد', '', 'حمم', 'حم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8213, 'حُمَمٌ', 'حمم', 'جامد', 'حمم', 'حمم', 'حم', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حُمَمٌ-حُمَمٌ، ةٌ [ح م م]. 1. ""قَذَفَ البُرْكَانُ حُمَماً"" : شَظَايَا، مَوَادَّ مُلْتَهِبَةً. 2. ""حُمَمُ النِّيرَانِ"" : مَا احْتَرَقَ بالنَّارِ وَتَطَايَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8214, 'حَمِيمِيَّةٌ', 'حميمية', 'جامد', 'حمم', 'حميمية', 'حممة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَمِيمِيَّةٌ-حَمِيمِيَّةٌ [ح م م]. ""صَدَاقَةٌ حَمِيمِيَّةٌ"" : صَدَاقَةٌ تَحْكُمُهَا الْمَوَدَّةُ العَمِيقَةُ الْمُتَبادَلَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8215, 'مِحَمٌّ', 'محم', 'جامد', 'حمم', 'محم', 'محم', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَامُّ"', '', 'R', '', '', '', '', '', '', '". 1.: وِعَاءٌ صَغِيرٌ مِنْ نُحَاسٍ وَنَحْوِهِ يُسَخَّنُ فِيهِ الْمَاءُ وَنَحْوُهُ. 2.: حَوْضٌ مِنَ الرُّخَامِ أَوِ الْمَعْدِنِ وَنَحْوِهِ يُمْلَأُ بِالْمَاءِ السَّاخِنِ وَيُسْتَحَمُّ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8216, 'مَحَامُّ', 'محام', 'جامد', '', 'محام', 'محم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8217, 'يَحْمُومٌ', 'يحموم', 'جامد', 'حمم', 'يحموم', 'حمم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يَحْمُومٌ-يَحْمُومٌ [ح م م]. 1.""عَلاَ الْيَحْمُومُ الْفَضَاءَ"" : الدُّخَانُ شَدِيدُ السَّوَادِ وَالْحَرَارَةِ.الواقعة آية 43 ، 44 وَظِلٍّ مِنْ يَحْمُومٍ، لاَ بَارِدٍ وَلاَ كَرِيمٍ (قرآن). 2.""نَبْتٌ يَحْمُومٌ"" : أَخْضَرُ رَيَّانُ أَسْوَدُ. 3.""جَبَلٌ يَحْمُومٌ"" : جَبَلٌ يَبْدُو أَسْوَدَ مِنْ بَعِيدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8218, 'حَمَاةٌ', 'حماة', 'جامد', 'حمو', 'حماة', 'حمة', '', '', '', 'مفرد', 'DnN', '', '', '"حمَوَاتٌ"', '', 'Rw', '', '', '', '', '', '', '". 1. ""جَاءتْ لِزِيَارَةِ حَمَاتِهَا"" : أُمُّ زَوْجِهَا. 2. ""كُلَّمَا جَاءتْ حَمَاتُهُ، تَذَكَّرَ مَوْعِداً نَسِيَهُ"" : أمُّ زَوْجَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8219, 'حمَوَاتٌ', 'حموات', 'جامد', '', 'حموات', 'حمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8220, 'حَمُو', 'حمو', 'جامد', 'حمو', 'حمو', 'حم', '', '', '', 'مفرد', 'DnN', '', '', '"أحْمَاءُمُثَنَّاهُحَمَوان"', '', 'R', '', '', '', '', '', '', '". 1.""حَضَرَ حَمُوهُ الحَفْلَةَ"" : أبُو امْرَأَتِهِ. 2. ""قُلْتُ لِحَمِيهَا إِنَّ..."": قُلْتُ لأَبِي زَوْجِهَا. ""سَأَلَتْ حَمَاهُ"". ""حَمُو"" مِنَ الأَسْمَاءِ الخَمْسَةِ الَّتِي تُعْرَبُ بِالوَاوِ رَفْعاً وَبِالأَلِفِ نَصْباً وَبِاليَاءِ خَفْضاً، وَلاَ يَرِدُ إلاَّ مُضَافاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8221, 'أحْمَاءُ', 'أحماء', 'جامد', '', 'ءحماء', 'حم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8222, 'حَمِيَّةٌ', 'حمية', 'جامد', 'حمي', 'حمية', 'حمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَمِيَّةٌ-حَمِيَّةٌ [ح م ي]. 1. ""أَظْهَرَ حَمِيَّةً"" : أَنَفةً، إبَاءً.الفتح آية 26 إذْ جَعَلَ الَّذِينَ كَفَرُوا فِي قُلُوبِهِمُ الحَمِيَّةَ حَمِيَّةَ الجَاهِلِيَّةِ (قرآن). 2. ""الحَمِيَّةُ القَوْمِيَّةُ"" : التَّعَصُّبُ القَوْمِيُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8223, 'حُمَّى', 'حمى', 'جامد', 'حمي', 'حمى', 'حم', '', '', '', 'مفرد', 'Dy', '', '', '"حُمَّياتٌ"', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '". ""أُصِيبَ بِحُمَّى"" : دَاءٌ تَرْتَفِعُ مَعَهُ دَرَجَةُ حَرَارَةِ الجِسْمِ، وَهِيَ أنْوَاعٌ، مِنْهَا حُمَّى التِّيفوئيدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8224, 'حُمَّياتٌ', 'حميات', 'جامد', '', 'حميات', 'حمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8225, 'حِمىً', 'حمى', 'جامد', 'حمي', 'حمى', 'حم', '', '', '', 'مفرد', 'Dy', '', '', '', '', 'Rw', '', '', '', '', '', '', '"حِمىً-حِمىً [ح م ي]. 1. ""حِمَى العَشِيرَةِ"" : الْمَوْضِعُ الَّذِي يُحْمَى ويُدَافَعُ عَنْهُ كَالدَّارِ وَالْمَرْعَى وَمَا إلَى ذَلِكَ. 2. ""أنَا فِي حِمَاكَ"" : فِي عِرْضِكَ. 3. ""حِمَى اللَّهِ"" : مَا حَرَّمَهُ، أيْ مَحَارِمُهُ. أَلاَ إِنَّ حِمَى اللَّهِ مَحَارِمُهُ (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8226, 'مُحَامَاةٌ', 'محاماة', 'جامد', 'حمي', 'محاماة', 'محمة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُحَامَاةٌ-مُحَامَاةٌ [ح م ي]. ""مِهْنَةُ الْمُحَامَاةِ"" : مِهْنَةُ الْمُحَامِي. ""هَيْئَةُ الْمُحَامَاةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8227, 'حِنَّاءٌ', 'حناء', 'جامد', '', 'حناء', 'حن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"حِنَّاءٌ-حِنَّاءٌ (نب) 1.: نَبَاتٌ مِنْ فَصِيلةِ الحِنَّائِيَّاتِ، وَرَقُهُ أخْضَرُ، يُتَّخذُ لِلْخِضَابِ الأحْمَرِ، يُطحَنُ طَحْناً وَيُخْلَطُ بِالْمَاءِ ليُخْضَبَ بِهِ، وَيُطْلَى بِهِ شَعْرُ النِّسَاءِ لِتَنْظِيفِهِ. 2.""يَوْمُ الحِنَّاءِ"" : يَوْمٌ تُطْلَى فِيهِ كَفّاً العَرُوسِ وَقَدَماها بِالحِنَّاءِ قَبْلَ يَوْمِ العُرْسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8228, 'حِنَّائِيَّات', 'حنائيات', 'جامد', '', 'حناءيات', 'حنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ بَرِّيَّةٌ وَزِرَاعِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ، ذَاتُ قُعَالاَتٍ عَدِيدَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8229, 'حَنْبَلٌ', 'حنبل', 'جامد', 'حنبل', 'حنبل', 'حنبل', '', '', '', 'مفرد', 'DnN', '', '', '"حَنَابِلُ"', '', 'Rp', '', '', '', '', '', '', '". 1. ""رَجُلٌ حَنْبَلٌ"": قَصِيرٌ، أَوْ ضَخْمُ البَطْنِ. 2. ""لَبِسَتِ الحَنْبَلَ"" : الفَرْوَ. 3.""شَاطِئُ الحَنْبَلِ"" : البَحْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8230, 'حَنَابِلُ', 'حنابل', 'جامد', '', 'حنابل', 'حنبل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8231, 'حُنْبُلٌ', 'حنبل', 'جامد', '', 'حنبل', 'حنبل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": بَقْلَةٌ زرَاعِيَّةٌ، لُوبِياء."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8232, 'حَنْجَرَةٌ', 'حنجرة', 'جامد', 'حنجر', 'حنجرة', 'حنجرة', '', '', '', 'مفرد', 'DnN', '', '', '"حَنَاجِرُ"', '', 'R', '', '', '', '', '', '', '". 1.: الْحُلْقُومُ، وَهُوَ العُضْوُ الْمُجَوَّفُ فِي أَقْصَى الفَمِ يُؤَدِّي إلَى القَصَبَةِ الهَوَائِيَّةِ، مَجْرَى النَّفَسِ وَالطَّعَامِ وَالشَّرَابِ. ""أُلَوِّحُ وَأصْرُخُ مِلْءَ حَنْجَرَتِي"". 2. ""يَتَمَيَّزُ بِحَنْجَرَتِهِ الذَّهبِيَّةِ"" : عِبَارَةٌ تُقَالُ لِلْمُغَنِّي جَيِّدِ الصَّوْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8233, 'حَنَاجِرُ', 'حناجر', 'جامد', '', 'حناجر', 'حنجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8234, 'حُنْجُورٌ', 'حنجور', 'جامد', 'حنجر', 'حنجور', 'حنجر', '', '', '', 'مفرد', 'DnN', '', '', '"حَنَاجِيرُ"', '', 'R', '', '', '', '', '', '', '". 1. ""صَوْتٌ حُنْجُورُهُ قَوِيٌّ"" : الحُلقُومُ. 2. ""أخْرَجَتْ حُنْجُورَ عِطْرٍ"" : قَارُورَةَ عِطْرٍ صَغِيرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8235, 'حَنَاجِيرُ', 'حناجير', 'جامد', '', 'حناجير', 'حنجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8236, 'حَنَشٌ', 'حنش', 'جامد', 'حنش', 'حنش', 'حنش', '', '', '', 'مفرد', 'DnN', '', '', '"أحْنَاشٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""أخْرَجَ الحَاوِي الحَنَشَ مِنَ الصُّنْدُوقِ وَلَفَّهُ حَوْلَ عُنُقِهِ"" : حَيَّةٌ سَودَاءُ وَهِيَ لَيْسَتْ مِنْ ذَوَاتِ السُّمُومِ. 2.: كُلُّ مَا أَشْبَهَ رَأْسُهُ رَأْسَ الحَيَّاتِ مِنْ زواحِفَ وَحَشَرَاتٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8237, 'أحْنَاشٌ', 'أحناش', 'جامد', '', 'ءحناش', 'حنش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8238, 'حِنَاطَةٌ', 'حناطة', 'جامد', 'حنط', 'حناطة', 'حنطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حِنَاطَةٌ-حِنَاطَةٌ [ح ن ط].: حِرْفَةُ بَائِع الحِنْطَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8239, 'حِنَاطٌ', 'حناط', 'جامد', 'حنط', 'حناط', 'حنط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَنّاطٌ-حَنّاطٌ [ح ن ط] (صِيغَةُ فَعَّالٍ). 1.: مَنْ يُحَنِّطُ الْمَوْتى. 2.: بَائِعُ الحِنْطَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8240, 'حِنْطَةٌ', 'حنطة', 'جامد', 'حنط', 'حنطة', 'حنطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"حِنَطٌ"', '', 'R', '', '', '', '', '', '', '". ""تَوَفَّرَتِ الحِنْطَةُ فِي الأَسْواقِ"" : القَمْحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8241, 'ح:حِنَطٌ', 'ح:حنط', 'جامد', '', 'ح:حنط', 'ح:حنط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8242, 'حَنوطٌ', 'حنوط', 'جامد', 'حنط', 'حنوط', 'حنط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَنوطٌ-حَنوطٌ [ح ن ط].: كُلُّ الْمَوادِّ الطِّبِّيَّةِ مِنْ مِسْكٍ وَعَنْبَرٍ وَكافورٍ تُوضَعُ فِي أَكْفانِ الْمَوْتَى وَأجْسَامِهِمْ خَاصَّةً لِتَحْفَظَهَا مِنَ الفَسادِ مُدَّةً طَوِيلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8243, 'حَنْظَلٌ', 'حنظل', 'جامد', '', 'حنظل', 'حنظل', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حَنْظَلٌ-حَنْظَلٌ، ةٌ (نب). : مِنْ فَصِيلَةِ القَرْعِيَّاتِ، نَبَاتُهُ بَرِّيٌّ يُشْبِهُ ثَمَرَةَ البِطِّيخِ، لَوْنُهُ بَيْنَ الاخْضِرارِ وَالاِصْفِرَارِ، بِدَاخِلِـهِ حَبَّاتٌ مُـرَّةٌ وَسامَّةٌ، يُسْتَعمَلُ فِي الأَدْوِيَةِ الطِّبِّيَّةِ. وَالخَيْلُ سَاهِمَةُ الوُجوهِ كَأنَّما*تُسْقَى فَوارِسُها نَقِيعَ الحَنْظَلِ (عنترة العبسيّ). 2. ""أسْمَيْتُهُ حَنْظَلَةَ كَرَمْزٍ لِلْمَـرَارَةِ"" (ناجي العلي) : الرَّمْـزُ الَّذِي اتَّخَذَهُ الرَّسَّامُ نَاجِي العليّ لِيُعَبِّرَ مِنْ خِلاَلِهِ عَنْ مَأْساةِ الطِّفْلِ الفلِسْطِينِيِّ الَّذِي يَظْهَرُ فِي كُلِّ رُسُومِهِ الكَريكَاتُورِيَّةِ. 3. "" أمَرُّ مِنَ الحَنْظَلِ"" (مثل) : يُضَرَبُ كِنَايَةٌ عَنِ الْمَرارَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8244, 'حَنَفِيَّةٌ', 'حنفية', 'جامد', 'حنف', 'حنفية', 'حنفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""أَخَذَ الْمَاءَ مِنَ الحَنَفِيَّةِ"": الصُّنْبورُ، أُنْبُوبَةٌ ذَاتُ لَوْلَبٍ يُفْتَحُ بِإدَارَتِهِ لإِنْزَالِ الْمَاءِ. وَهِيَ أَنْوَاعٌ وَأَشْكَالٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8245, 'حَنَكٌ', 'حنك', 'جامد', '', 'حنك', 'حنك', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَحْنَاكٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَحْنَاكٌ. 1.: أَعْلَى بَاطِنِ الفَمِ. 2.: أَسْفَلُ بَاطنِ الفَمِ. وَهُما حَنَكَانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8246, 'أَحْنَاكٌ', 'أحناك', 'جامد', '', 'ءحناك', 'حنك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8247, 'حَنْوٌ', 'حنو', 'جامد', 'حنو', 'حنو', 'حن', '', '', '', 'مفرد', 'DnN', '', '', '"أَحْناءٌ:حِنْوٌ"', '', 'R', '', '', '', '', '', '', '".: كُلُّ ما فيهِ انْثِناءٌ مِنَ البَدَنِ كالضِّلْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8248, 'أَحْناءٌ', 'أحناء', 'جامد', '', 'ءحناء', 'حن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8249, 'حِنْوٌ', 'حنو', 'جامد', '', 'حنو', 'حن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8250, 'حِنْوٌ', 'حنو', 'جامد', 'حنو', 'حنو', 'حن', '', '', '', 'مفرد', 'DnN', '', '', '"أحْنَاءٌ:حِنِيٌّ"', '', 'R', '', '', '', '', '', '', '". 1. ""حِنْوُ الوَادِي"": مُنْعَرَجُهُ. 2. ""حِنْوُ الضِّلْعِ"" : اِعْوِجَاجُهُ. 3.""أَحْنَاءُ الصَّدْرِ"": أَطْرَافُهُ وَجَوَانِبُهُ. ""اِمْتَلأتْ أَحْنَاءُ صَدْرِهِ حِقْداً"". 4. ""أحْنَاءُ الأُمُورِ"" : أطْرَافُهَا، نَوَاحِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8251, 'أحْنَاءٌ', 'أحناء', 'جامد', '', 'ءحناء', 'حن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8252, 'حِنِيٌّ', 'حني', 'جامد', '', 'حني', 'حن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8253, 'حَنِيَّةٌ', 'حنية', 'جامد', 'حنو', 'حنية', 'حنة', '', '', '', 'مفرد', 'DnN', '', '', '"حَنَايَا"', '', '', '', '', '', '', '', '', '". : القَوْسُ، كُلُّ مَا كَانَ مُنْحَنِياً. 1. ""خَرَجُوا بِالحَنَايَا يَبْتَغُونَ الرِّمايَا"" : خَرَجُوا بِالأقْوَاسِ. 2. ""فِي حَنَايَا صَدْرِهِ"" : فِي أَعْمَاقِهِ، فِي دَوَاخِلِهِ. ""حَنَايَا نَفْسِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8254, 'حَنَايَا', 'حنايا', 'جامد', '', 'حنايا', 'حن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8255, 'مُنْحَنىً', 'منحنى', 'جامد', 'حنو', 'منحنى', 'منحن', '', '', '', 'مفرد', 'Dy', '', '', '"مُنْحَنَيَات"', '', '', '', '', '', '', '', '', '". ""مُنْحَنَى الوَادِي"" : مُنْعَطَفُ الوَادِي. ""مُنْحَنَى الطَّرِيقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8256, 'مُنْحَنَيَات', 'منحنيات', 'جامد', '', 'منحنيات', 'منحنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8257, 'حُوٌّ', 'حو', 'جامد', '', 'حو', 'ح', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": نَمْلٌ أَحْمرُ يُقالُ لَهُ نَمْلُ سُلَيْمانَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8258, 'حَوَّاءُ', 'حواء', 'جامد', '', 'حواء', 'ح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rz', '', 'N', 'N', 'N', 'O', '', '": زَوْجُ آدَمَ، أُمُّ البَشَرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8259, 'حُوتٌ', 'حوت', 'جامد', 'حوت', 'حوت', 'حت', '', '', '', 'مفرد', 'DnN', '', '', '"حِيتَانٌ"', '', 'R', '', '', '', '', '', '', '". 1.: السَّمَكُ. 2.: مِنْ فَصِيلَةِ البَالِيَّاتِ، مِنْ رُتْبَةِ الحُوتِيَّاتِ مِنَ الثَّدْيِيَّاتِ الْمَائِيَّةِ الكَبِيرَةِ الحَجْمِ. 3. ""بُرْجُ الحُوتِ"" (فلك) : بُرْجٌ مِنْ أبْرَاجِ السَّمَاءِ يَبْتَدِئُ مِنْ 20 شُبَاط، فَبْرَايِر."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8260, 'حِيتَانٌ', 'حيتان', 'جامد', '', 'حيتان', 'حتن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8261, 'حاجَةٌ', 'حاجة', 'جامد', 'حوج', 'حاجة', 'حجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حَوائِجُ"', '', 'R', '', '', '', '', '', '', '". 1.""كانَ في حاجَةٍ ماسَّةٍ إلى مُساعَدَتِهِ"" : الافْتِقارُ إِلى...، في عَوْزٍ إلى... 2.""لا حاجَةَ لي بِهَذا الكِتابِ"" : لالُزومَ. 3.""عِنْدَ مَساسِ الحاجَةِ، عَلَيْكَ أَنْ تَتَّصِلَ بِي"" : عِنْدَ الضَّرورَةِ والاحْتِياجِ. ""الحاجَةُ أُمُّ الاخْتِراعِ. 4.""سافَرَ مُباشَرَةً بَعْدَما قَضى حاجاتِهِ"": بَعْدَ أَنْ أَنْهَى رَغَباتِهِ وَطَلَباتِهِ وَنَفَّذَها. 5.""دَخَلَ المِرْحاضَ لِيَقْضِيَ حاجَتَهُ"" : لِيَتَغَوَّطَ. ""إِنَّ لِكُلِّ مَخْلوقٍ حاجَةً"". (ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8262, 'حَوائِجُ', 'حوائج', 'جامد', '', 'حواءج', 'حج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8263, 'حاجِيَّاتٌ', 'حاجيات', 'جامد', 'حوج', 'حاجيات', 'حجت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"حاجِيَّاتٌ-حاجِيَّاتٌ [ح و ج]. ""قَضى بَعْضَ الحاجِيَّاتِ"" : بَعْضَ الضَّرورِيَّاتِ، أَيْ ما يَحْتَاجُ إِلَيْهِ الإِنْسانُ في حَياتِهِ اليَوْمِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8264, 'حُوذِيٌّ', 'حوذي', 'جامد', 'حوذ', 'حوذي', 'حذ', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"حُوذِيٌّ-حُوذِيٌّ [ح و ذ]. 1. ""يَسِيرُ الحُوذِيُّ خَلْفَ إبِلِهِ"" : المسْتَحِثُّ الإبِلَ أَوِ الدَّوَابَّ عَلَى السَّيْرِ. ""اِرْتَفَعَ صَوْتُ الحُوذِيِّ بِمَوَّالٍ"". 2. ""حُوذِيُّ عَرَبَةِ الخَيْلِ"" : سَائِقُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8265, 'حارَةٌ', 'حارة', 'جامد', 'حور', 'حارة', 'حرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""نَسْكُنُ في حارَةٍ وَاحِدَةٍ"": في حَيِّ واحِدٍ حَيْثُ المنازِلُ مُتَقارِبَةٌ بَعْضُها مِنْ بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8266, 'أوْحَد', 'أوحد', 'جامد', 'وحد', 'ءوحد', 'حد', 'صف', '', '', 'مفرد', 'DnN', '', '', '"أحْدانٌ:ولايقالللأنثىوَحْداء"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). 1.""اللَّهُ الأوْحَدُ"": الوَاحِدُ فِي مُلْكِهِ، ذُو الوَحْدَانِيَّةِ. 2.""هُوَ أوْحَدُ زَمَانِهِ"": لَمْ يَكُنْ لَهُ نَظِيرٌ. ""لَسْتُ فِي هذَا الأمْرِ بِأوْحَدَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8267, 'أحْدانٌ', 'أحدان', 'جامد', '', 'ءحدان', 'حدن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8268, 'حُوريَّةٌ', 'حورية', 'جامد', 'حور', 'حورية', 'حرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1. ""اِمْرَأةٌ حُورِيَّةٌ"" : حَسْنَاءُ. 2. يُحْكَى عَنْ حُورِيَّةِ البَحْرِ أنَّ..."" : فَتَاةٌ أُسْطُورِيَّةٌ، إِلَهَةٌ تَتَرَاءى فِي البِحَارِ وَالغَابَاتِ. 3. ""حُورِيَّةٌ"": اسْمُ عَلَمٍ لِلْمُؤَنَّثِ وَتَعْنِي الحَسْنَاءَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8269, 'مَحَارٌ', 'محار', 'جامد', 'حور', 'محار', 'محر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَحَارٌ-مَحَارٌ [ح و ر]. 1.: الْمَرْجِعُ. 2.: (تش). حَنَكُ الإِنْسَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8270, 'مِحْوَرٌ', 'محور', 'جامد', 'حور', 'محور', 'محر', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَاوِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِحْوَرُ البَكَرَةِ"" : الْحَدِيدَةُ الَّتِي تَدُورُ عَلَيْهَا البَكَرَةُ"". 2.""المِحْوَرُ فِي الهَنْدَسَةِ"" : الخَطُّ الْمُسْتَقِيمُ الْمُوصِلُ بَيْنَ قُطْبَيِ الكُرَةِ. 3.""مِحْوَرُ الأَرْضِ"" (فك) : خَطٌّ مُسْتَقِيمٌ تَدُورُ الأَرْضُ حَوْلَهُ. 4.""مِحْوَرُ الْمَوْضُوعِ"" : فِكْرَتُهُ الرَّئيسَةُ أَوِالرَّئِيسِيَّةُ، مَدَارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8271, 'مَحَاوِرُ', 'محاور', 'جامد', '', 'محاور', 'محر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8272, 'حَوْرٌ', 'حور', 'جامد', '', 'حور', 'حر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَحْوَارٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَحْوَارٌ. (نب).: شَجَرٌ مِنْ فَصِيلَةِ الصَّفْصَافِيَّاتِ، خَشَبُهُ أَبْيَضُ خَفِيفٌ، يُسْتَعْمَلُ بِكَثْرَةٍ فِي الصِّنَاعَةِ الخَشَبِيَّةِ لِصُنْعِ الأثَاثِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8273, 'أَحْوَارٌ', 'أحوار', 'جامد', '', 'ءحوار', 'حر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8274, 'حَوْزاءُ', 'حوزاء', 'جامد', 'حوز', 'حوزاء', 'حز', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"حَوْزاءُ-حَوْزاءُ [ح و ز]. ""اِشْتَدَّتِ الحَوْزَاءُ"" : الحَرْبُ. إذْ تَحُوزُ المحَارِبِينَ، أيْ تَجْمَعُهُمْ وَتَضُمُّهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8275, 'حَوْزَةٌ', 'حوزة', 'جامد', 'حوز', 'حوزة', 'حزة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حَوْزَةٌ-حَوْزَةٌ [ح و ز]. 1.""الكِتَابُ فِي حَوْزَتِهِ"" : بَيْنَ يَدَيْهِ، فِي مَكْتَبَتِهِ، في مِلْكِهِ . 2. ""يُدَافِعُ عَنْ حَوْزَةِ الوَطَنِ"" : عَنِ حِيَاضِ الوَطَنِ. 3. ""حَوْزَةُ الإسْلاَمِ"" : حُدُودُهُ وَنَواهِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8276, 'حَيِّزٌ', 'حيز', 'جامد', 'حوز', 'حيز', 'حز', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَيْزٌ-حَيْزٌ [ح ي ز] (مص. حَازَ يَحِيزُ). ن.حَيِّزٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8277, 'حِيَاصَةٌ', 'حياصة', 'جامد', 'حوص', 'حياصة', 'حصة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حِيَاصَةٌ-حِيَاصَةٌ [ح و ص]. ""شَدَّ حِيَاصَةَ دَابَّتِهِ"" : حِزَامَهَا الَّذِي يُشَدُّ بِهِ السَّرْجُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8278, 'حَوْصَلٌ', 'حوصل', 'جامد', '', 'حوصل', 'حصل', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"1. ""اِنْتَفَخَ حَوْصَلُ الطَّائِرِ"" : كُرَةٌ فِي الْمَرِيءِ، يُخْتَزَنُ فِيها الغَذَاءُ قَبْلَ أَنْ يَمُرَّ إلَى الْمَعِدَةِ. 2.""حَوْصَلُ حَوْضٍ"" : مُسَتَقَرُّ الْمَاءِ فِي أسْفَلِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8279, 'حِيَاضٌ', 'حياض', 'جامد', 'حوض', 'حياض', 'حض', '', '', '', 'مفرد', '', '', '', '"مفردحَوْض"', '', 'R', '', '', '', '', '', '', '". 1. ""ذَبَّ عَنْ حِيَاضِ الدِّينِ"" : دَافَعَ عَنْ قِيَمِهِ وَشَرِيعَتِهِ. 2. ""ذَادَ عَنْ حِيَاضِ الوَطَنِ"": دَافَعَ عَنْ حُدُودِهِ وَأَرَاضِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8280, 'حَوْضٌ', 'حوض', 'جامد', '', 'حوض', 'حض', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أحْوَاضٌ:حِيَاضٌ"', '', 'R', '', '', '', '', '', '', '"ج: أحْوَاضٌ، حِيَاضٌ. 1. ""يَسْبَحُ فِي الحَوْضِ"" : مُجْتَمَعُ الْمَاءِ. 2. ""اِرْتَمَى الأَوْلاَدُ فِي الحَوْضِ"": بِرْكَةُ مَاءٍ. 3.""حَوْضُ الأُذُنِ"" : مَحَارَتُهَا، صَدَفَتُهَا. 4.""حَوْضُ النَّهْرِ"" : المِنْطَقَةُ الَّتِي تَجْرِي فِيهَا رَوَافِدُهُ. 5.""أحْوَاضُ الفَحْمِ وَالحَدِيدِ"" : مُسْتَوْدَعَاتُهَا. 6.""حَوْضُ السِّبَاحَةِ"" : الْمَسْبَحُ. 7. ""حَوْضُ البَحْرِ"" : السَّوَاحِلُ الْمُحِيطَةُ بِهِ. ""بُلْدَانُ حَوْضِ البَحْرِ الأَبْيَضِ الْمُتَوَسِّطِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8281, 'أحْوَاضٌ', 'أحواض', 'جامد', '', 'ءحواض', 'حض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8282, 'حِيَاضٌ', 'حياض', 'جامد', '', 'حياض', 'حض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8283, 'حَوْطَةٌ', 'حوطة', 'جامد', 'حوط', 'حوطة', 'حطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حَوْطَةٌ-حَوْطَةٌ [ح و ط]. ""اِتَّخَذَ حَوْطَةً"" : اِحْتِياطاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8284, 'حافَّةٌ', 'حافة', 'جامد', 'حوف', 'حافة', 'حفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":حيفٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَقَفَ على حافَّةِ النَّهْرِ"" : على طَرَفِهِ، على جُرْفِهِ، على جانِبِهِ. ""حافَّتا الوادِي"". 2.""يَسيرُ على حافَّةِ الطَّريقِ"" : على طِوارِهِ. 3.""هُوَ في حافَّةٍ"" : في ضَيْقٍ، شِدَّةٍ، حاجَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8285, 'حيفٌ', 'حيف', 'جامد', '', 'حيف', 'حف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8286, 'حاقٌّ', 'حاق', 'جامد', 'حوق', 'حاق', 'حق', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'N', 'N', '', '"حاقٌّ-حاقٌّ، ةٌ [ح و ق]. 1.الحاقة آية 1،2،3 الحاقَّةُ ما الحاقَّةُ وَما أَدْراكَ ما الحاقَّةُ . (قرآن) : القِيامَةُ. 2.""سوَرةُ الحاقَّةِ"" : مِنْ سُوَرِ القُرآنِ. 3.""شُجاعٌ حاقَّةُ الشُّجاعِ"" : الكامِلُ فيها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8287, 'حُوقٌ', 'حوق', 'جامد', '', 'حوق', 'حق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": الإطَارُ الْمُحِيطُ بِالشَّيْءِ الْمُسْتَدِيرِ، وَيُطْلَقُ أيْضاً عَلَى الإطَارِ الْمَطَّاطِيِّ لِعَجَلَةِ السَّيَّارَةِ أَوِ الدَّرَّاجَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8288, 'حَوَالَةٌ', 'حوالة', 'جامد', 'حول', 'حوالة', 'حلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""تَوَصَّلَ بِحَوَالَةٍ بَرِيديَّةٍ"" : بِمَبْلغٍ مِنَ الْمَالِ يَبْعَثُ بِهِ شَخْصٌ (الْمُرْسِلُ) إلَى شَخْصٍ آخَرَ (الْمُرْسَلُ إلَيْهِ) بِوَاسِطَةِ البَرِيدِ. 2. ""قَبَضَ الْمُوَظَّفُ حَوَالَتَهُ فِي آخِرِ الشَّهْرِ"" : القَدْرُ الْمَالِيُّ الَّذِي يَتَوَصَّلُ بِهِ الْمُوَظَّفُ. 3. ""حَوَالَةُ نَهْرٍ"" : تَحْوِيلُ مَاءِ نَهْرٍ إلَى آخَر."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8289, 'حَوَالٌ', 'حوال', 'جامد', 'حول', 'حوال', 'حل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَوَالٌ-حَوَالٌ [ح و ل]. 1. ""حَوَالُ الْمَنْزِلِ"" : الجِهَاتُ الْمُحِيطَةُ بِهِ. 2. ""جَلَسَ حَوَالَهُ"" : إزَاءهُ. 3. ""حَوَالُ الدَّهْرِ"": تَغَيُّرُهُ وَنَوَائِبُهُ وَصُرُوفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8290, 'حَوْلِيٌّ', 'حولي', 'جامد', 'حول', 'حولي', 'حل', '', '', '', 'مفرد', 'DnN', '', '', '"حَوالِيُّ:حَوَالِيَّةٌ"', '', '', '', '', '', '', '', '', '". ""خَرُوفٌ حَوْلِيٌّ"" : أتَى عَلَيْهِ الحَوْلُ، السَّنَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8291, 'حَوالِيُّ', 'حوالي', 'جامد', '', 'حوالي', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8292, 'حَوَالِيَّةٌ', 'حوالية', 'جامد', '', 'حوالية', 'حلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8293, 'مَحَالَةٌ', 'محالة', 'جامد', 'حول', 'محالة', 'محلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَحَالَةٌ-مَحَالَةٌ [ح و ل]. 1.""لاَ مَحَالَةَ مِنْ عِقَابِهِ"" : لاَبُدَّ. 2.""هُوَ آتٍ لاَ مَحَالَةَ"" : لاَ رَيْبَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8294, 'حَوَّامَةٌ', 'حوامة', 'جامد', 'حوم', 'حوامة', 'حمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '".: الطَّائِرَةُ العَمُودِيَّةُ ذَاتُ الْمَرَاوِحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8295, 'حُوّةٌ', 'حوة', 'جامد', 'حوي', 'حوة', 'حة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"حُوّةٌ-حُوّةٌ [ح و ي]. 1. ""حُوَّةُ الشِّفَاهِ"" : سُمْرَتُهَا. 2.""حُوَّةُ نَباتٍ"" : سَوَادُهُ إلَى خُضْرَةٍ أوْ حُمْرَتُهُ إلَى سَوادٍ. 3. ""حُوّةُ الوادِي"" : جَانِبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8296, 'مُحْتَوًى', 'محتوى', 'جامد', 'حوي', 'محتوى', 'محت', '', '', '', 'مفرد', 'Dy', '', '', '"مُحْتَوَيَات"', '', '', '', '', '', '', '', '', '". 1.""مُحْتَوَى الكِتَابِ"" : مَا يَتَضَمَّنُهُ مِنْ آرَاءٍ وَأَفْكَارٍ. 2.""مُحْتَوَى الفِكْرَةِ"" : مَضْمُونُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8297, 'مُحْتَوَيَات', 'محتويات', 'جامد', '', 'محتويات', 'محتت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8298, 'حُوَيْصِلَةٌ', 'حويصلة', 'جامد', '', 'حويصلة', 'حصلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات . 1. ""الحُوَيْصِلاتُ الرِّئَوِيَّةُ"" : مَا يَحْصُلُ مِنِ انْتِفَاخٍ دَقِيقٍ فِي جُدْرَانِ الأَكْيَاسِ الهَوَائِيَّةِ فِي الرِّئَةِ حَيْثُ يَتِمُّ التّبَادُلُ التَّنَفُّسِيُّ الغَازِيُّ. 2. ""الحُوَيْصِلَةُ الصَّفْرَاوِيَّةُ"" : هِيَ عُضْوٌ فِي الجهَازِ الهَضْمِيِّ يَخْتَزِنُ الصَّفْرَاءَ الَّتِي يَفْرِزُهَا الكَبِدُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8299, 'حَيَّةٌ', 'حية', 'جامد', '', 'حية', 'حة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":حَيَوَاتٌ(تُذَكَّرُوَتُؤَنَّ', '', '', '', '', '', '', '', '', '"ج: حَيَّاتٌ، حَيَوَاتٌ. (تُذَكَّرُ وَتُؤَنَّثُ). 1.""فَاجَأتْهُ حَيَّةٌ بَيْنَ الأَعْشَابِ"" : الأَفْعَى وَهِيَ أَنْوَاعٌ، مِنْ رُتْبَةِ الزَّوَاحِفِ. ""مَنْ لَدَغَتْهُ الحَيَّةُ خَافَ مِنَ الحَبْلِ"". (مثل). 2.""هُوَ حَيَّةُ الوَادِي"" : مَنْ كَانَ يُعْرَفُ بِالدَّهَاءِ وَالخُبْثِ وَالْمَكْر. ""حَيَّةُ الأَرْضِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8300, 'حَيَوَاتٌ', 'حيوات', 'جامد', '', 'حيوات', 'حت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8301, 'حَيْثِيَّةٌ', 'حيثية', 'جامد', '', 'حيثية', 'حثة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"ج: ـات. 1. ""قَدَّمَ حَيْثِيَّاتٍ وَاهِيَةً"" : الاعْتِبَارَات، الأَسْبَاب. ""قَدَّمَ القَاضِي حَيْثِيَّاتِ الحُكْمِ"". 2.""قَدَّمَ حَيْثِيَّةً لَهَا اعْتِبَارُهَا"" : أَيْ وِجْهَةَ نَظَرٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8302, 'حَيَدَانٌ', 'حيدان', 'جامد', 'حيد', 'حيدان', 'حدن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَيَدَانٌ-حَيَدَانٌ [ح ي د]. ""حَيَدَانٌ عَنِ الطَّرِيقِ"" : الانْحِرَافُ، الْمَيْلُ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8303, 'حَيْدَةٌ', 'حيدة', 'جامد', 'حيد', 'حيدة', 'حدة', '', '', '', 'مفرد', 'DnN', '', '', '"حِيَدٌ"', '', 'R', '', '', '', '', '', '', '". 1.""حَيْدَةُ قَرْنِ الوَعْلِ"": عُقْدَتُهُ. 2.""ضَرَبَهُ عَلَى حَيْدَةِ رَأْسِهِ"" : عَلَى عُقْدَةِ جَانِبِ رَأْسِهِ. 3.""مَا نَظَرَ إِلَيَّ إِلاَّ نَظَرَ الحَيْدَةِ"" : نَظَرَ سُوءٍ، فِيهِ مَيْلٌ وَانْحِرَافٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8304, 'حِيَدٌ', 'حيد', 'جامد', '', 'حيد', 'حد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8305, 'حَيْدَرٌ', 'حيدر', 'جامد', '', 'حيدر', 'حدر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1.""هُوَ حَيْدَرٌ"" : هُوَ أَسَدٌ. 2.: اِسْمُ عَلَمٍ لِلْمُذَكَّرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8306, 'حِيَرٌ', 'حير', 'جامد', 'حير', 'حير', 'حر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حِيَرٌ-حِيَرٌ [ح ي ر]. 1.: الكَثِيرُ مِنَ الأَهْلِ وَالْمَالِ. 2. ""لا آتِيهِ حِيَرَ الدَّهْرِ"" : أبَدَ الدَّهْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8307, 'حِيَاضٌ', 'حياض', 'جامد', 'حيض', 'حياض', 'حض', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"حِيَاضٌ-حِيَاضٌ [ح ي ض]. ""حِيَاضُ الْمَرْأَةِ"" : دَمُ حَيْضِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8308, 'حِيضَةٌ', 'حيضة', 'جامد', 'حيض', 'حيضة', 'حضة', '', '', '', 'مفرد', 'DnN', '', '', '"حِيَضٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '".: خِرْقَةٌ تَضَعُهَا الْمَرْأَةُ لِتَتَلَقَّى دَمَ الحَيْض."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8309, 'حِيَضٌ', 'حيض', 'جامد', '', 'حيض', 'حض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8310, 'مُحِيطٌ', 'محيط', 'جامد', 'حيط', 'محيط', 'محط', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""عَاشَ فيِ مُحِيطٍ عِلْمِيٍّ"" : فِي وَسَطٍ عِلْمِيٍّ، أَيِ الجَوُّ وَالبِيئَةُ الَّتِي يَعِيشُ فِيهَا الِإْنَسَانُ. 2.""مُحِيطُ الدَّائِرَةِ"" (هن) : الخَطُّ الَّذِي يُحِيطُ بِالدَّائِرَةِ. 3.""الْمُحِيطُ الأَطْلَسِيُّ"" : البَحْرُ الَّذِي يُحِيطُ بِاليَابِسَةِ. ""تُغَطِّي الْمُحِيطَاتُ مَا يُقَارِبُ مِنْ ثُلُثَيِ الكُرَةِ الأَرْضِيَّةِ"" ""الْمُحِيطُ الهَادِي"" ""الْمُحِيطُ الهِنْدِيُّ"". 4.""عَالِمٌ مُحِيطٌ بِكُلِّ عُلُومِ عَصْرِهِ"" : مُلِمٌّ بِهَا، عَارِفٌ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8311, 'حِيَلٌ', 'حيل', 'جامد', 'حيل', 'حيل', 'حل', '', '', '', 'مفرد', '', '', '', '"مفردحِيلَة"', '', 'R', '', '', '', '', '', '', '". ""تَخصَّصَ فِي عِلْمِ الحِيَلِ"": فِي عِلْمِ المِيكَانِيكِ، كُلُّ مَا يَتَعَلَّقُ بِالبَحْثِ فِي الأجْسَامِ وَترْكِيبِهِا وَتَحْرِيكِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8312, 'حِيلَةٌ', 'حيلة', 'جامد', 'حيل،حول', 'حيلة', 'حلة', '', '', '', 'مفرد', 'DnN', '', '', '"حِيَلٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""حَبَكَ حِيلَةً"": خُدْعَةً، خَدِيَعةً، مَكِيدَةً. 2. ""لاَ حِيلَةَ لِي فِي الأمْرِ"" : لاَ قُدْرَةَ، لاَ اسْتِطَاعَةَ لِي. 3. ""مَا الحِيلَةُ "" : مَا العَمَلُ 4. ""لَمْ يَجِدْ حِيلَةً إلاَّ وَاسْتَخْدَمَهَا"" : وَسِيلَةً.النساء آية 98 لاَ يَسْتَطِيعُونَ حِيلَةً وَلاَ يَهْتَدُونَ سَبِيلاً (قرآن). 5. ""لَمْ تَبْقَ فِي يَدِهِ حِيلَةٌ"" : أي اسْتَنْفَدَ كُلَّ الوَسَائِلِ وَالإِمْكَاناتِ. ""أعْيَتْهُ الحِيَلُ"" ""ضَاقَتْ آفَاقُ الحِيَلِ فِي وَجْهِهَا"" (ع. غلاب)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8313, 'حِيَلٌ', 'حيل', 'جامد', '', 'حيل', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8314, 'حانَةٌ', 'حانة', 'جامد', 'حين', 'حانة', 'حنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حانَةٌ-حانَةٌ [ح ي ن]. ""حانَةُ الخَمْرِ"" : حانوتٌ لِبَيْعِ الخَمْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8315, 'حَيَّاتٌ', 'حيات', 'جامد', 'حيي', 'حيات', 'حت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"حَيَّاتٌ-حَيَّاتٌ [ح ي ي]. : شُعْبَةٌ مِنَ الحَيَوَانَاتِ الزَّحَّافَةِ. مُتَعَدِّدَةُ الفَصَائِلِ وَالرُّتَبِ حَسَبَ وَضْعِ أسْنانِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8316, 'حَيٌّ', 'حي', 'جامد', 'حيي', 'حي', 'ح', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"أَحْيَاءٌ"', '', '', '', '', '', '', '', '', '". 1. ""هُوَ حَيٌّ يُرْزَقُ"": يَنْبِضُ بِالحَيَاةِ وَالحَرَكَةِ. ""مَا زَالَ حَيّاً"". 2. هُوَ اللَّهُ الحَيُّ"": مِنْ أَسْمَاءِ اللَّهِ الحُسْنَى. 3. ""عَبْدُ الحَيِّ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ. 4. ""عِلْمُ الأحْيَاءِ"" : عِلْمُ دِرَاسَةِ مُخْتَلِفِ مَظَاهِرِ الكَائِنَاتِ مِنْ حَيَوانٍ وَنَبَاتٍ. 5. ""يَسْكُنُ فِي حَيِّ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8317, 'أَحْيَاءٌ', 'أحياء', 'جامد', '', 'ءحياء', 'ح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8318, 'حَيَوَانٌ', 'حيوان', 'جامد', 'حيي', 'حيوان', 'حن', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.: كُلُّ حَيٍّ نَاطِقٍ أوْ غَيْرِ نَاطِقٍ. 2. ""الحَيَوَانُ النَّبَاتِيُّ"" : حَيَوَانٌ يُشْبِهُ شَكْلَ النَّبَاتِ كَالإِسْفَنْجِ. 3. ""الحَيَوَانُ النُّخَاعِيُّ"" : حَيَوَانٌ فِقَرِيٌّ، لَهُ حَبْلٌ شَوْكِيٌّ وَلَيْسَ لَهُ مُخٌّ. 4. ""الحَيَوَانُ الْمَنَوِيُّ"" : النُّطْفَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8319, 'مُحَيَّا', 'محيا', 'جامد', 'حيي', 'محيا', 'مح', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مُحَيَّا-مُحَيَّا [ح ي ي]. ""أَشْرَقَتِ ابْتِسَامَةٌ عَلَى مُحَيَّاهُ"" : عَلَى وَجْهِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8320, 'خَافَةٌ', 'خافة', 'جامد', '', 'خافة', 'خفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '": جُـبَّةٌ مِنْ جِلْدٍ مُشَمَّعٍ يَلْبَسُهَا الْغَسَّالُ لِتَقِيَهُ لَسْعَ النَّحْلِ ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8321, 'خَانٌ', 'خان', 'جامد', '', 'خان', 'خن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": نُزُلٌ لِلشَّبَابِ الْمُسَافِرِينَ مِنْ كُلِّ الْجِنْسِيَّاتِ، مُهَيَّأٌ لِلْمَبِيتِ وَالطَّعَامِ وَالإِقَامَةِ الْمُؤَقَّتَةِ، مُقَابِلَ ثَمَنٍ زَهِيدٍ. وَهُوَ مَا يُعْرَفُ في الفَرنسِيَّة بِالأُوبِرْج."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8322, 'خَابِيَةٌ', 'خابية', 'جامد', 'خبأ', 'خابية', 'خبة', '', '', '', 'مفرد', 'DnN', '', '', '"خَوَابٍ:الْخَوَابِي"', '', '', '', '', '', '', '', '', '". ""خَابِيَةُ الْمَاءِ"" : جَرَّةٌ ضَخْمَةٌ مِنَ الطِّينِ لِحِفْظِ الْمَاءِ وَتَصْلُحُ لأغْرَاضٍ أخْرَى. ""كَانَتِ الْخَوَابِي مَلِيئَةً بِالْمُؤَنِ مِنْ زَيْتُونٍ وَعَدَسٍ وَدَقيقٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8323, 'خَوَابِي', 'خوابي', 'جامد', '', 'خوابي', 'خب', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8324, 'خُبَيْأَى', 'خبيأى', 'جامد', 'خبأ', 'خبيءى', 'خب', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R0', '', '', '', '', '', '', '"خُبَيْأَى-خُبَيْأَى [خ ب أ].: لُعْبَةُ الأطْفَالِ. ن: غُمَّيْضَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8325, 'خَبِيئَةٌ', 'خبيئة', 'جامد', 'خبأ', 'خبيءة', 'خبة', '', '', '', 'مفرد', 'DnN', '', '', '"خَبَايَا"', '', '', '', '', '', '', '', '', '". 1. ""لاَ أعْرِفُ خَبَايَا نَفْسِهِ"" : أسْرَارَهَا وَخَفَايَاهَا. 2. ""لَمْ نَكْتَشِفْ خَبَايَا الأرْضِ بَعْدُ"" : مَوَارِدَهَا الطَّبِيعِيَّةَ الْكَامِنَةَ فِي جَوْفِهَا، مَوَادَّهَا الخَامَ، الْمَعَادِنَ. اُطْلُبُوا الرِّزْقَ فِي خَبَايَا الأَرْض.(حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8326, 'خَبَايَا', 'خبايا', 'جامد', '', 'خبايا', 'خب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8327, 'مُخَبَّآتٌ', 'مخبآت', 'جامد', 'خبأ', 'مخبءءت', 'مخبآت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُخَبَّآتٌ-مُخَبَّآتٌ [خ ب أ].: الأَشْيَاءُ الْمَخْفِيَّةُ، الْمُخْتَبِئَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8328, 'مَخْبَأٌ', 'مخبأ', 'جامد', 'خبأ', 'مخبء', 'مخب', '', '', '', 'مفرد', 'Dz', '', '', '"مَخَابِئُ"', '', '', '', '', '', '', '', '', '". ""اِخْتَبَأَ فِي مَخْبَإٍ لاَ أَحَدَ اهْتَدَى إِلَيْهِ"" : مَوْضِعُ الاخْتِبَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8329, 'مَخَابِئُ', 'مخابئ', 'جامد', '', 'مخابء', 'مخب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8330, 'خِبَاءٌ', 'خباء', 'جامد', 'خبأ،خبي', 'خباء', 'خب', '', '', '', 'مفرد', 'Dz', '', '', '"أخْبِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '". ""تَجَمَّعُوا فِي خِبَاءٍ يَنْتَظِرُونَ مُرُورَ عَاصِفَةٍ رَمْلِيَّةٍ"" : خَيْمَةٌ مِنْ وَبَرٍ أَوْ صُوفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8331, 'أخْبِيَةٌ', 'أخبية', 'جامد', '', 'ءخبية', 'خبة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8332, 'خُبَّازٌ', 'خباز', 'جامد', '', 'خباز', 'خبز', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ن. خُبَّازَى، خُبَّيْزَةٌ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8333, 'خَبَايَا', 'خبايا', 'جامد', '', 'خبايا', 'خب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '": ن.خَبِيئَةٌ ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8334, 'خَبَبٌ', 'خبب', 'جامد', 'خبب', 'خبب', 'خب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَبَبٌ-خَبَبٌ [خ ب ب]. 1. "" مَشَى خَبَباً"" : ضَرْبٌ مِنْ عَدْوِ الْفَرَسِ عِنْدَمَا يَنْقلُ أيَامِنَهُ وَأيَاسِرَهُ جَمِيعاً. 2. ""بَحْرُ الْخَبَبِ"" : بَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8335, 'أَخْبَثٌ', 'أخبث', 'جامد', 'خبث', 'ءخبث', 'خبث', '', '', '', 'مفرد', 'DnN', '', '', '"مثنىأَخْبَثَانِ-أَخْبَثَانِ"', '', '', '', '', '', '', '', '', '"أَخْبَثَانِ-أَخْبَثَانِ [خ ب ث]. 1.: البَوْلُ وَالغَائِطُ. 2.: السَّهَرُ والضَّجَرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8336, 'خَبَائِثُ', 'خبائث', 'جامد', 'خبث', 'خباءث', 'خبث', '', '', '', 'مفرد', '', '', '', '"مفردخَبِيثَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1. ""حَرَّمَ العَرَبُ الخَبَائِثَ"" : مَا كَانَتْ تُحَرِّمُ أَكْلَهُ مِثْلَ الأَفَاعِي وَالْخَنَافسِ، الأعْمَالُ الْمَذْمُومَةُ. 2.""ح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8337, 'خُبْثٌ', 'خبث', 'جامد', 'خبث', 'خبث', 'خبث', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خُبْثٌ-خُبْثٌ [خ ب ث]. ""وَلَدٌ ذُو خُبْثٍ"" : ذُو مَكْرٍ وَفَسَادٍ وَمَكْرُوهٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8338, 'أَخْبَارٌ', 'أخبار', 'جامد', 'خبر', 'ءخبار', 'خبر', '', '', '', 'مفرد', '', '', '', '"مفردخَبَر"', '', '', '', '', '', '', '', '', '". 1. ""تَلَقَّى رِسَالَةً فِيهَا أخْبَارُ الأَهْلِ والْمُجْتَمَعِ"" : مَا يَتَعَلَّقُ بِأَحْدَاثِ الْمُجْتَمَعِ"". 2.""اِسْتَمَعَ إِلَى نَشْرَةِ الأَخْبَارِ"" : نَشْرَةٌ إِذَاعِيَّةٌ أَوْ تَلْف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8339, 'خَبَر', 'خبر', 'جامد', '', 'خبر', 'خبر', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8340, 'خَابُورٌ', 'خابور', 'جامد', 'خبر', 'خابور', 'خبر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"خَابُورٌ-خَابُورٌ [خ ب ر] (نب).: نَبَاتٌ مِنْ فَصِيلَةِ الْخَمَانِيَّاتِ، لَهُ زَهْرٌ زَاهِي الْمَنْظَرِ، أصْفَرُ اللَّوْنِ، جَيِّدُ الرَّائِحَةِ، تُزَيَّنُ بِهِ الْحَدَائِقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8341, 'خَبَارٌ', 'خبار', 'جامد', 'خبر', 'خبار', 'خبر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَبَارٌ-خَبَارٌ [خ ب ر]. 1. ""كَثُرَ خَبَارُ الأرْضِ"" : التُّرَابُ الْمُجْتمِعُ بِأصُولِ الشَّجَرِ. 2. ""أرْضٌ خَب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8342, 'مُخَابَرَةٌ', 'مخابرة', 'جامد', 'خبر', 'مخابرة', 'مخبرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". 1.""مُخَابَرَةٌ هَاتِفِيَّةٌ"" : الْمُحَادَثَةُ بِالهَاتِفِ، الْمُكَالْمَةُ الهَاتِفِيَّةُ، الْمُخَاطَبَةُ... 2.""قِسْمُ الْمُخَابَرَاتِ"" : الْمَكْتَبُ الْمَسْؤُولُ عَنِ الْحُصُولِ عَلَى الْمَعْلُومَاتِ السِّرِّيَّةِ وَالإِحَاطَةِ عَنْ قُرْبٍ بِأَوْضَاعِ الأَمْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8343, 'مَخْبَرٌ', 'مخبر', 'جامد', 'خبر', 'مخبر', 'مخبر', '', '', '', 'مفرد', 'DnN', '', '', '"مَخَابِرُ"', '', 'R', '', '', '', '', '', '', '". ""مَخْبَرُ الرَّجُلِ"" : دَخِيلَتُهُ، حَقِيقَتُهُ. ""طَابَقَ مَخْبَرُهُ مَظْهَرَهُ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8344, 'مَخَابِرُ', 'مخابر', 'جامد', '', 'مخابر', 'مخبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8345, 'مُخْتَبَرٌ', 'مختبر', 'جامد', 'خبر', 'مختبر', 'مختبر', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '".: غُرْفَةٌ مُجَهَّزَةٌ بِآلاَتٍ دَقِيقَةٍ مُعَدَّةٍ لِإِجْرَاءِ الاخْتِبَارَاتِ وَالتَّحْلِيلاَتِ الكِيمْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8346, 'خِبَازَةٌ', 'خبازة', 'جامد', 'خبز', 'خبازة', 'خبزة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"خِبَازَةٌ-خِبَازَةٌ [خ ب ز].: حِرْفَةُ الخَبَّازِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8347, 'خُبَّازِيَّاتٌ', 'خبازيات', 'جامد', 'خبز', 'خبازيات', 'خبزت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"خُبَّازِيَّاتٌ-خُبَّازِيَّاتٌ [خ ب ز].: فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الْفِلْقَتَيْنِ أنْوَاعُهَا مُتَعدِّدَةُ الأشْكَالِ فِي كُلِّ الْمَنَاطِقِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8348, 'خُبَّازَى', 'خبازى', 'جامد', 'خبز', 'خبازى', 'خبز', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'O', 'O', 'O', '', '"خُبَّازَى-خُبَّازَى [خ ب ز].: بَقْلَةٌ مِنْ فَصِيلَةِ الْخُبَّازِيَّاتِ تُشْبِهُ السَّبَانِخَ وَالسَّلْقَ، أوْرَاقُهَا مُسْتَدِيرَةٌ، تُؤْكَلُ مَطْبُوخَةً، وَمِنْهَا مَا يُزْرَعُ لِزَهْرِهِ، وَيُسْتَعْمَلُ فِي الطِّبِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8349, 'خُبَّيْزَةٌ', 'خبيزة', 'جامد', 'خبز', 'خبيزة', 'خبزة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"خُبَّيْزَةٌ-خُبَّيْزَةٌ [خ ب ز] : بَقْلَةٌ مِنْ فَصِيلَةِ الْخُبَّازِيَّاتِ، تُسْلَقُ وَيَتِمُّ تَحْضِيرُهَا بِالثُّومِ وَالْفُلْفُلِ وَالزَّيْتِ وَالْحَامِضِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8350, 'مَخْبِزٌ', 'مخبز', 'جامد', 'خبز', 'مخبز', 'مخبز', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَخَابِزُ"', '', 'R', '', '', '', '', '', '', '".: الْمَكَانُ الَّذِي يُخْبَزُ فِيهِ الخُبْزُ أَوْ يُبَاعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8351, 'مَخَابِزُ', 'مخابز', 'جامد', '', 'مخابز', 'مخبز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8352, 'خَبِيصٌ', 'خبيص', 'جامد', 'خبص', 'خبيص', 'خبص', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '"خَبِيصٌ-خَبِيصٌ، ةٌ [خ ب ص] (طخ). : حَلْوَاءُ مُكَوَّنَةٌ مِنْ خَلِيطٍ التُّمُورِ أوِ الفَوَاكِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8353, 'مِخْبَصَةٌ', 'مخبصة', 'جامد', 'خبص', 'مخبصة', 'مخبصة', '', '', '', 'مفرد', 'DnN', '', '', '"مَخَابِصُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِخْبَصَةُ الخَبِيصِ"" : مَا يُقَلَّبُ فِيهِ، أَيْ مَا يُشْبِهُ القِدْرَ. 2.: مَا يقلَّبُ بِهِ، أَي مَا يُشْبِهُ المِلْعَقَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8354, 'مَخَابِصُ', 'مخابص', 'جامد', '', 'مخابص', 'مخبص', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8355, 'خِبَاطٌ', 'خباط', 'جامد', 'خبط', 'خباط', 'خبط', '', '', '', 'مفرد', 'DnN', '', '', '"خُبُطٌ"', '', 'R', '', '', '', '', '', '', '". ""خَبَطَ الْبَعِيرَ بِخِبَاطٍ"" : عَلاَمَة، سِمَة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8356, 'خُبُطٌ', 'خبط', 'جامد', '', 'خبط', 'خبط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8357, 'خَبِيطٌ', 'خبيط', 'جامد', 'خبط', 'خبيط', 'خبط', '', '', '', 'مفرد', 'DnN', '', '', '"خُبُطٌ"', '', 'R', '', '', '', '', '', '', '". ""تَنَاوَلَ خَبِيطاً"" : لَبَناً رَائِباً يُصَبُّ عَلَيْهِ الحَلِيبُ ثُمَّ يُخْبَطُ حَتَّى يَخْتَلِطَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8358, 'خُبُطٌ', 'خبط', 'جامد', '', 'خبط', 'خبط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8359, 'مِخْبَاطٌ', 'مخباط', 'جامد', 'خبط', 'مخباط', 'مخبط', '', '', '', 'مفرد', 'DnN', '', '', '"مَخَابِيطُ"', '', 'R', '', '', '', '', '', '', '". ""مِخْبَاطُ التُّرَابِ أَوْ غَيْرِهِ"" : مَا يُخْبَطُ بِهِ كَالقَضِيبِ وَنَحْوِهِ. ""نَظَّفْنَا البَيْتَ، نَقَلْنَا الْمَاءَ وَرَشَشْنَا أَرْضِيَّتَهُ الْمُتْرَبَةَ وَبِمِخْبَاطٍ خَشَبِيٍّ خَبَطْنَاهَا"". (حنا مينه)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8360, 'مَخَابِيطُ', 'مخابيط', 'جامد', '', 'مخابيط', 'مخبط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8361, 'خَبَلٌ', 'خبل', 'جامد', '', 'خبل', 'خبل', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ات"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"خَبَلٌ-خَبَلٌ (حو).: بُومَةٌ سَمْرَاءُ لَهَـا عَيْنـانِ سَــوْداوان وجَناحانِ عَريضانِ مُسْتَديران، جِسْمُهَا بَدِينٌ، مِنْقار"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8362, 'خَاتِمَةٌ', 'خاتمة', 'جامد', 'ختم', 'خاتمة', 'ختمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":خَوَاتِيمُ"', '', '', '', '', '', '', '', '', '". 1. ""خَاتِمَةُ الْمَوْضُوعِ"" : آخِرُ تَعْلِيقٍ فِي الْمَوْضُوعِ، الْمُلَخَّصُ. 2. ""لَمْ يَقْرَأْ إِلاَّ خَاتِمَةَ الْكِتَابِ"" : الأفْكَار الْمُلَخِّصَة لَهُ. 3. ""كَان"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8363, 'خَوَاتِيمُ', 'خواتيم', 'جامد', '', 'خواتيم', 'ختم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8364, 'خِتَانَةٌ', 'ختانة', 'جامد', 'ختن', 'ختانة', 'ختنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خِتَانَةٌ-خِتَانَةٌ [خ ت ن]. ""تُزَاوِلُ عَائِلَتُهُ مِهْنَةَ الْخِتَانَةِ مُنْذُ عُقودٍ"" : حِرْفَةُ الْخَاتِنِ الَّذِي يَقْطَعُ، يَجُزُّ قُلَفَ الصِّبْيَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8365, 'خِتَانٌ', 'ختان', 'جامد', 'ختن', 'ختان', 'ختن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خِتَانٌ-خِتَانٌ [خ ت ن]. ""حَضَرَ الأهْلُ حَفْلَ خِتَانِ ابْنِهِمْ"" : اِسْتِئْصَال قُلْفَةِ ذَكَرِ الصَّبِيِّ، وَهُوَ مَا يُعْرَفُ بِالْمَغْرِبِ بِالطَّهَارَةِ، التَّطْهِيرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8366, 'خَتَنَةٌ', 'ختنة', 'جامد', 'ختن', 'ختنة', 'ختنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"خَتَنَةٌ-خَتَنَةٌ [خ ت ن]. ""جَاءتِ الْخَتَنَةُ لِزِيَارَةِ ابْنَتِهَا"" : أمُّ الزَّوْجَةِ."', '');
