INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8479, 'خِزَانَةٌ', 'خزانة', 'جامد', 'خزن', 'خزانة', 'خزنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":خَزَائنُ"', '', 'R', '', '', '', '', '', '', '". 1. ""خَزَائِنُ اللهِ"" : غُيُوبُ عِلْمِهِ لِغُمُوضِهَا عَلَى خَلْقِهِ.الحجر آية 21 وَإنْ مِنْ شَيْءٍ إِلاَّ عِنْدَنَا خَزَائِنُهُ.(قرآن ). 2.""خِزَانَةُ الإِنْسَانِ"" : قَلْبُهُ. ""وَالْقَلْبُ خِزَانَةٌ مُسْتَحْفَظَةٌ لِلْخَوَاطِرِ وَالأَسْرَارِ"".(الجاحظ). 3. يُطَالِعُ فِي الْخِزَانَةِ"" : مَكْتَبَةٌ عُمُوميَّةٌ، مَكْتَبَةُ الْمَدْرَسَةِ أَوِ الْمَعْهَدِ. ‎‎""الخِزَانَةُ الْعَامَّةُ"". 4. ""وَ"', '');
