INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8492, 'خَشَبَةٌ', 'خشبة', 'جامد', 'خشب', 'خشبة', 'خشبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"وَاحِدَةُالْخَشَبِ"', '', 'R', '', '', '', '', '', '', '". 1.""رُفِعَ الْمَيِّتُ عَلى الْخَشَبَةِ"" : النَّعْشُ. 2. ""وَقَفَ الْمُمَثِّلُ عَلَى خَشَبَةِ الْمَسْرَحِ"" : حَيِّزٌ مُرْتَفِعٌ فِي قَاعَةٍ يُقَامُ بِالْخَشَبِ يُؤَدِّي فِيهِ الْمُمَثِّلُون أَدْوَارَهُمْ، مِنَصَّةُ (مَنَصَّةُ) التَّمْثِيلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8493, 'خَشَبٌ', 'خشب', 'جامد', 'خشب', 'خشب', 'خشب', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَخْشَابٌ:خُشُبٌ"', '', 'R', '', '', '', '', '', '', '".: مَا يَبِسَ مِنَ الشَّجَرِ. المنافقون آية 4كَأَنَّهُمْ خُشُبٌ مُسَنَّدَة(قرآن)."', '');
