INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8497, 'خَشْرَمٌ', 'خشرم', 'جامد', '', 'خشرم', 'خشرم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"خَشَارِمَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: خَشَارِمَةٌ. 1.: جَمَاعَةُ النَّحْلِ وَالزَّنَابِيرِ. 2.:مَلِكَةُ النَّحْلِ. 3.: مَأْوَى النَّحْلِ. لَتَرْكَبُنَّ سَنَنَ مَنْ كَانَ قَبْلَكُمْ ذِرَاعاً بِذِرَاعٍ حَتَّى لَوْ سَلَكُوا خَشْرَمَ دَبْرٍ لَسَلَكْتُمُوه. (حديث)."', ':لا جذر:لا مفرد');
