INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8532, 'خُضَارٌ', 'خضار', 'جامد', 'خضر', 'خضار', 'خضر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"خُضَارٌ-خُضَارٌ، ةٌ [خ ض ر]. 1.: النَّقْلُ"', '');
