INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8534, 'خَضَارِيٌّ', 'خضاري', 'جامد', '', 'خضاري', 'خضر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8535, 'خُضْرَةٌ', 'خضرة', 'جامد', 'خضر', 'خضرة', 'خضرة', '', '', '', 'مفرد', 'DnN', '', '', '"خُضَرٌ"', '', 'R', '', '', '', '', '', '', '". 1."" تَمْلأُ الخُضْرَةُ كُلَّ الْبِقَاعِ"" : يَكْسُوهَا لَوْنٌ أَخْضَرُ. 2. "" بَائِعُ الخُضْرَةِ"" : بَائِعُ البُقُولِ. 3. ""خُضْرَةُ الدِّمَنِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8536, 'خُضَرٌ', 'خضر', 'جامد', '', 'خضر', 'خضر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8537, 'خِضْرٌ', 'خضر', 'جامد', 'خضر', 'خضر', 'خضر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خِضْرٌ-خِضْرٌ [خ ض ر]. 1. ""ذَهَبَ دَمُهُ خِضْراً"" : هَدَراً. 2.""أَخَذَهُ خِضْراً"" : هَنِيئاً مَرِيئاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8538, 'خِضَمٌّ', 'خضم', 'جامد', 'خضم', 'خضم', 'خضم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خِضَمٌّ-خِضَمٌّ [خ ض م]. 1. ""فِي هَذَا الخِضَمِّ"" : فِي هَذَا الجَمْعِ الكَبِيرِ. 2. ""شَقَّتِ البَاخِرَةُ الخِضَمَّ"" : البَحْرَ العَظِيمَ. 3.""رَجُلٌ خِضَمٌّ"" : كَثِيرُ العَطَاءِ، الجَوَادُ الكَرِيمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8539, 'خَطَأٌ', 'خطأ', 'جامد', 'خطأ', 'خطء', 'خط', '', '', '', 'مفرد', 'Dz', '', '', '"أَخْطَاءٌ"', '', 'Rz', '', '', '', '', '', '', '". 1. ""سَلَكَ سُلُوكاً فِيهِ خَطَأٌ"": بَعِيدٌ عَنِ الصَّوَابِ. 2. ""اِعْتَرَفَ بِأَخْطَائِهِ"" : أَقَرَّ بِذُنُوبِهِ، بِأَغْلاَطِهِ. 3.""يَحْتَوِي الكِتَابُ عَلَى أَخْطَاءٍ مَطْبَعِيَّةٍ"" : لَمْ تُكْتَبِ الكَلِمَاتُ كَمَا هِيَ فِي النَّصِّ الأَصْلِيِّ، أَغْلاَطٌ. ""يَا لَهُ مِنْ خَطَإٍ فَاحِشٍ !""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8540, 'أَخْطَاءٌ', 'أخطاء', 'جامد', '', 'ءخطاء', 'خط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8541, 'خَطِيَّةٌ', 'خطية', 'جامد', 'خطأ', 'خطية', 'خطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"خَطِيَّةٌ-خَطِيَّةٌ [خ ط أ]. ن.: الْخَطِيئَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8542, 'خَطِيئَةٌ', 'خطيئة', 'جامد', 'خطأ', 'خطيءة', 'خطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":خَطَايا"', '', '', '', '', '', '', '', '', '". 1. ""اِرْتَكَبَ خَطِيئَةً"": ذَنْباً مُتَعَمَّداً. 2. ""وَجَدَ الْقَوْمَ فِي خَطَايَا"" : وَجَدَهُمْ يَعِيشُونَ فِي الذُّنُوبِ.الأعراف آية 161 وَادْخُلُوا الْبَابَ سُجَّداً نَغْفِرْ لَكُمْ خَطِيئَاتِكُم (قرآن) ""الصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ كَمَا يُطْفِئُ الْمَاءُ النَّارَ"" (الغزالي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8543, 'خَطَايا', 'خطايا', 'جامد', '', 'خطايا', 'خط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8544, 'خُطَّافٌ', 'خطاف', 'جامد', '', 'خطاف', 'خطف', '', '', '', 'جمع تكسير', 'DnN', '', '', '"خَطَاطِيفُ"', '', 'R', '', '', '', '', '', '', '"ج: خَطَاطِيفُ. (حو).: طَائِرُ السُّنُونُو وَهُوَ مِنَ الطُّيُورِ الدَّوْرِيَّةِ، مِنْ فَصِيلَةِ الْخَطَاطِيفِ، مِنْ رُتْبَةِ الْعُصْفُورِيَّاتِ، عَرِيضُ الْجَنَاحَيْنِ، قَصِيرُ الرِّجْلَيْـنِ وَالْمِنْقَارِ، أَسْوَدُ الظَّهْرِ، أَبْيَضُ البَطْنِ، يَغِيبُ فِي الشِّتَاءِ، وَيَعُودُ فِي أَوَاخِرِ الرَّبِيعِ وَبِدَايَةِ الصَّيْفِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8545, 'خَطَاطِيفُ', 'خطاطيف', 'جامد', '', 'خطاطيف', 'خططف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8546, 'خَطَّابَةٌ', 'خطابة', 'جامد', 'خطب', 'خطابة', 'خطبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'Rp', '', '', '', '', '', '', '"خِطَابَةٌ-خِطَابَةٌ [خ ط ب]. ""يَحْتَرِفُ خِطَابَةَ الْمَسَاجِدِ"" : حِرْفَة الخَطِيبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8547, 'خِطَابَةٌ', 'خطابة', 'جامد', 'خطب', 'خطابة', 'خطبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"خَطَّابَةٌ-خَطَّابَةٌ [خ ط ب]. ""جَاءتِ الْخَطَّابَةُ إِلَى بَيْتِ أَهْلِ البِنْتِ"" : الْمَرْأَةُ الْمُكَلَّفَةُ مِنْ لَدُنِ الْخَطِيبِ أَوْ مِنْ أَهْلِهِ أَوْ أَصْدِقَائِهِ لِطَلَبِ يَدِ البِنْتِ مِنْ أَجْلِ زَوَاجِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8548, 'خُطْبَةٌ', 'خطبة', 'جامد', 'خطب', 'خطبة', 'خطبة', '', '', '', 'مفرد', 'DnN', '', '', '"خُطَبٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""اِرْتَجَلَ خُطْبَةَ الافْتِتَاحِ"" : الْكَلاَمُ الأَوَّلِي يُلْقَى في بِدَايَةِ مُؤْتَمَرٍ أَوِ اجْتِمَاعٍ أَوْ نَدْوَةٍ. ""لَمَّا أَتْمَمْتُ الخُطْبَةَ دَوَّى الْمَكَانُ بِالتَّصْفِيقِ"". (أ. أمين). 2. ""أَلْقَى الإِمَامُ خُطْبَةَ الْجُمُعَةِ"" : الْكَلاَمُ الوَعْظِيُّ الَّذِي يُلْقِيهِ الخَطِيبُ عَلَى النَّاسِ مُجْتَمِعِينَ. 3. ""خُطْبَةُ الكِتَابِ"": مُقَدِّمَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8549, 'خُطَبٌ', 'خطب', 'جامد', '', 'خطب', 'خطب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8550, 'خَطْبٌ', 'خطب', 'جامد', 'خطب', 'خطب', 'خطب', '', '', '', 'مفرد', 'DnN', '', '', '"خُطُوبٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""جَاءتْ مَذْعُورَةً، فَسَأَلَهَا عَنْ خَطْبِهَا"" : عَنْ شَأْنِهَا، عَنْ أَمْرِهَا، أَيْ مَا حَلَّ بِهَا. 2. ""مَا خَطْبُكَ"" : مَا شَأْنُكَ، مَا حَالُكَ. ""أَمْرٌ عَظِيمٌ وَأَدَبٌ نَفِيسٌ وَخَطْبٌ جَلِيلٌ"". 3. ""أَلَمَّ بِهِ خَطْبٌ"" : مَكْرُوهٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8551, 'خُطُوبٌ', 'خطوب', 'جامد', '', 'خطوب', 'خطب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8552, 'خُطُوبَةٌ', 'خطوبة', 'جامد', 'خطب', 'خطوبة', 'خطبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خُطُوبَةٌ-خُطُوبَةٌ [خ ط ب]. ""تَمَّتْ حَفْلَةُ الْخُطُوبَةِ"" : حَفْلَةُ الْمُوَافَقَةِ عَلَى طَلَبِ البِنْتِ لِلزَّوَاجِ مِنْها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8553, 'خَاطِرٌ', 'خاطر', 'جامد', 'خطر', 'خاطر', 'خطر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"خَوَاطِرُ"', '', 'R', '', '', '', '', '', '', '". 1. ""مَرَّتْ بِخَاطِرِي كُلُّ الذِّكْرَيَاتِ الْمَاضِيَةِ"" : مَرَّتْ بِبالي، بِفِكْرِي. 2. ""إِرْضَاءً لِخَاطِرِكَ"" : مِنْ أجْلِ رَاحَتِكَ، إِكْرَاماً لَكَ. ""مِنْ أجْلِ خَاطِرِكَ"". 3. ""سَامَحَهُ عَنْ طِيبِ خَاطِرٍ"" : عَنْ رِضىً وَسُرُورٍ. 4. ""مِنْ كُلِّ خَاطِرِي"" : مِنْ كُلِّ قَلْبِي. 5.""حَاوَلَ أنْ يَأْخُذَ بِخَاطِرِهِ"" : أنْ يُرِيحَهُ، أنْ يُطَمْئِنَهُ، يُرِيدُ تَسْلِيَتَهُ وَإِرْضَاءهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8554, 'خَوَاطِرُ', 'خواطر', 'جامد', '', 'خواطر', 'خطر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8555, 'خُطَّةٌ', 'خطة', 'جامد', 'خطط', 'خطة', 'خطة', '', '', '', 'مفرد', 'DnN', '', '', '"خُطَطٌ"', '', 'R', '', '', '', '', '', '', '". 1.""قَدَّمَ خُطَّةً مُحْكَمَةً"" : أَيْ خُطَّةَ عَمَلٍ، تَصْمِيماً، مِنْهَاجاً، مَا يُهْتَدَى بِهِ لِتَحْقِيقِ هَدَفٍ مَّا، حُجَّةً. ""أَنْجَزَ خُطَّةَ عَمَلٍ لإنْجازِ مَشْروعِهِ"". 2.""هَذِهِ خُطَّتُهُ في الْعَمَلِ"": نَهْجُهُ. ""كَانَ يَسِيرُ وَفْقَ خُطَّةٍ مَرْسُومَةٍ"". 3. ""في رَأْسِهِ خُطَّةٌ"" : يُدِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8556, 'خُطَطٌ', 'خطط', 'جامد', '', 'خطط', 'خط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8557, 'خِطَّةٌ', 'خطة', 'جامد', 'خطط', 'خطة', 'خطة', '', '', '', 'مفرد', 'DnN', '', '', '"خِطَطٌ"', '', 'R', '', '', '', '', '', '', '": ن.خُطَّةٌ.1. ""خِطَّةُ الْعِمَارَةِ"" : الْمَكَان الَّذِي اخْتُطَّ لَهَا. 2. ""خِطَّةُ الأَرْضِ"" : قِطْعَةُ أَرْضٍ تُحَاطُ بِسِيَاجٍ عَلاَمَةً عَلَى أَنَّهَا في مِلْكِ مَالكٍ لِيُقيمَ عَلَيْهَا بِـنَاءً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8558, 'خِطَطٌ', 'خطط', 'جامد', '', 'خطط', 'خط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8559, 'خَاطُوفٌ', 'خاطوف', 'جامد', 'خطف', 'خاطوف', 'خطف', '', '', '', 'مفرد', 'DnN', '', '', '"خَوَاطِيف"', '', 'R', '', '', '', '', '', '', '".: أَدَاةٌ يُخْتَطَفُ بِهَا الصَّيْدُ أوِ الْفَرَاشَاتُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8560, 'خَوَاطِيف', 'خواطيف', 'جامد', '', 'خواطيف', 'خطف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8561, 'خَطَاطِيفُ', 'خطاطيف', 'جامد', 'خطف', 'خطاطيف', 'خططف', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"خَطَاطِيفُ-خَطَاطِيفُ [خ ط ف]. ""خَطَاطِيفُ السِّبَاعِ"" : مَخَالِبُهَا، أَظَافِرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8562, 'خَطْفَةٌ', 'خطفة', 'جامد', 'خطف', 'خطفة', 'خطفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"خَطْفَةٌ-خَطْفَةٌ [خ ط ف]. 1. ""الْجُزْءُ الْمَخْطُوفُ"" : مَا اُخْتُطِفَ مِنْ أَعْضَاءِ الشَّاةِ وَنَحْوِهَا وَهِيَ حَيَّةٌ. أَنَّهُ صَلَّى الله عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْخَطْفَة (حديث). 2. ""خَطْفَةُ الرَّضِيعِ"": الرَّضْعَةُ الَّتِي يَخْطِفُهَا مِنَ الثَّدْيِ. 3. ""مَا مِنْ مَرَضٍ إِلاَّ وَلَهُ خَطْفَةٌ"" : خِفَّةٌ وَبُرْءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8563, 'خَطِيفَةٌ', 'خطيفة', 'جامد', 'خطف', 'خطيفة', 'خطفة', '', '', '', 'مفرد', 'DnN', '', '', '"خَطَائِفُ"', '', '', '', '', '', '', '', '', '". 1. ""بِنْتٌ خَطِيفَةٌ"": مَخْطُوفَةٌ. 2. : لَبَنٌ يُجْعَلُ عَلَيْهِ طَحِينٌ وَيُطْبَخُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8564, 'خَطَائِفُ', 'خطائف', 'جامد', '', 'خطاءف', 'خطف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8565, 'خِطَامٌ', 'خطام', 'جامد', 'خطم', 'خطام', 'خطم', '', '', '', 'مفرد', 'DnN', '', '', '"خُطُمٌ:أَخْطِمَةٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""خِطَامُ جَمَلٍ"": مَا يُوضَعُ عَلَى خَطْمِهِ لِيُقَادَ بِهِ، الزِّمَامُ. 2.""وَضَعَ الْخِطَامَ عَلَى أَنْفِهِ"" : مَلَكَهُ، اِسْتَبَدَّ بِهِ. 3. ""مَنَعَ خِطَامَهُ"" : اِمْتَنَعَ مِنَ الذُّلِّ وَالانْقِيَادِ. 4. ""خِطَامُ الْقَوْسِ"" : وَتَرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8566, 'خُطُمٌ', 'خطم', 'جامد', '', 'خطم', 'خطم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8567, 'أَخْطِمَةٌ', 'أخطمة', 'جامد', '', 'ءخطمة', 'خطمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8568, 'خَطْمٌ', 'خطم', 'جامد', 'خطم', 'خطم', 'خطم', '', '', '', 'مفرد', 'DnN', '', '', '"خُطُومٌ"', '', 'R', '', '', '', '', '', '', '". 1.: مُقَدَّمُ أنْفِ الدَّابَّةِ. 2.""خَطْمُ الطَّائِرِ"" : مِنْقَارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8569, 'خُطُومٌ', 'خطوم', 'جامد', '', 'خطوم', 'خطم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8570, 'خَطْمِيٌّ', 'خطمي', 'جامد', 'خطم', 'خطمي', 'خطم', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"خَطْمِيٌّ-خَطْمِيٌّ [خ ط م] (نب).: نَبَاتٌ عُشْبِيٌّ مِنْ فَصِيلَةِ الخُبَّازِيَّاتِ، مِنْهَا مَاهُوَ بَرِّيٌّ وَمِنْهَا مَا هُوَ زِرَاعِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8571, 'مِخْطَمٌ', 'مخطم', 'جامد', 'خطم', 'مخطم', 'مخطم', '', '', '', 'مفرد', 'DnN', '', '', '"مَخَاطِمُ"', '', 'R', '', '', '', '', '', '', '". ""مِخْطَمُ الطَّائِرِ"": مِنْقَارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8572, 'مَخَاطِمُ', 'مخاطم', 'جامد', '', 'مخاطم', 'مخطم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8573, 'خُطْوَةٌ', 'خطوة', 'جامد', 'خطو', 'خطوة', 'خطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":خُطًى"', '', 'R', '', '', '', '', '', '', '". 1.""أَنْجَزَ خُطْوَةً مُهِمَّةً"" : عَمَلاً مُهِمّاً. 2. ""تَقَدَّمَ خُطْوَةً فَخُطْوَةً"" : تَقَدَّمَ تَدْرِيجِيّاً. ""يُنْجِزُ أعْمَالَهُ َخُُطْوَةً فَخُُطْوَة"". 3.""خُطْوَتَانِ إِلَى الأَمَامِ وَخُطْوَةٌ إِلَى الْوَرَاءِ"" : السَّيْرُ الْمَحْسُوبُ ضِمْنَ خُطَّةِ عَمَلٍ سِيَّاسِيٍّ. 4. ""يَسِيُر عَلَى خُطَاهُ"": يَقْتَفِي أثَرَهُ، طُرُقَهُ.البقرة آية 168 لاَتَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8574, 'خُطًى', 'خطى', 'جامد', '', 'خطى', 'خط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8575, 'خُفٌّ', 'خف', 'جامد', '', 'خف', 'خف', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أخْفَافٌ:خِفَافٌ"', '', 'R', '', '', '', '', '', '', '"ج: أخْفَافٌ، خِفَافٌ. 1. ""اِنْتَعَلَ خُفَّهُ"" : مَا يُنْتَعَلُ فِي الرِّجْلِ حِذَاءً أَوْ بَلْغَةً أَوْ نَعْلاً. 2. ""خُفُّ الرَّقْصِ"" : نَقْلٌ خَفِيفٌ مِنَ الثَّوْبِ تَنْتَعِلُهُ الرَّاقِصَاتُ، نَعْلٌ. 3. ""رَأيْتُهُ يُعَالِجُ خُفَّ بَعِيرِهِ"" : حَافِرَهُ. 4. ""رَجَعَ بِخُفَّيْ حُنَيْنٍ"" (مثل) : أَخْفَقَ فِي مُهِمَّتِهِ، رَجَعَ خَائِباً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8576, 'أخْفَافٌ', 'أخفاف', 'جامد', '', 'ءخفاف', 'خفف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8577, 'خِفَافٌ', 'خفاف', 'جامد', '', 'خفاف', 'خفف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8578, 'خُفَّاشٌ', 'خفاش', 'جامد', '', 'خفاش', 'خفش', '', '', '', 'جمع تكسير', 'DnN', '', '', '"خَفَافِيشُ"', '', 'R', '', '', '', '', '', '', '"ج: خَفَافِيشُ. (حو). 1. طَائِرٌ لَبُونٌ مِنْ فَصِيلَةِ الْخُفَّاشِيَّاتِ، مِنْ رُتْبَةِ مُجَنَّحَاتِ الأَيْدِي، لَهُ جَنَاحَانِ وَاسِعَانِ، لاَ رِيشَ بِهِمَا، يُشْبِهُ جِسْمَ الْفَأْرِ، لاَ يَظْهَرُ إِلاَّ فِي اللَّيْلِ وَيُعْرَفُ أيْضاً بِالوَطْوَاطِ. 2. ""لَوْ كَانَ الْمُسْتَبِدُّ طَيْـراً لَكَانَ خُفَّاشاً"". (ع. الكواكبي): كِنَايَةً عَنْ خَوْفِهِ مِنَ النُّورِ وَأنَّهُ اعْتَـادَ الظَّــلاَمَ. ""خَفَافِيشُ تُظْلِمُ فِي أَعْيُنِهِمْ"" (ابن طفيل)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8579, 'خَفَافِيشُ', 'خفافيش', 'جامد', '', 'خفافيش', 'خففش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8580, 'خُفَّاشِيَّاتٌ', 'خفاشيات', 'جامد', '', 'خفاشيات', 'خفشت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ حَيَوَانِيَّةٌ مِنَ الثَّدْيِيَّاتِ، مُجَنَّحَاتِ الأَيْدِي، مِنْ أشْهَرِ أنْوَاعِهَا الخُفَّاشُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8581, 'خَفِيرٌ', 'خفير', 'جامد', 'خفر', 'خفير', 'خفر', '', '', '', 'مفرد', 'DnN', '', '', '"خُفَرَاءُ:خَفَرٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""خَلاَ السُّوقُ مِنْ أَيِّ خَفِيِر"" : مِنْ أَيِّ حَارِسٍ. 2. ""أَحَاطَ الْخُفَرَاءُ بِالسَّفِينَةِ"": حُرَّاسُ السَّوَاحِلِ. ""خَفَرُ الْحُدُودِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8582, 'خُفَرَاءُ', 'خفراء', 'جامد', '', 'خفراء', 'خفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8583, 'خَفَرٌ', 'خفر', 'جامد', '', 'خفر', 'خفر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8584, 'مَخْفَرٌ', 'مخفر', 'جامد', 'خفر', 'مخفر', 'مخفر', '', '', '', 'مفرد', 'DnN', '', '', '"مَخَافِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""حَقَّقُوا مَعَهُ فِي الْمَخْفَرِ"" : مَرْكَزٌ لِجِهَازِ الأَمْنِ فِي الْمُدُنِ وَالقُرَى لِلْمُحَافَظَةِ عَلَى الأَمْنِ. 2.""مَخْفَرٌ أَمَامِيٌّ لِلْقِتَالِ"" : مَكَانٌ لِلْجُنُودِ عَلَى الْحُدُودِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8585, 'مَخَافِرُ', 'مخافر', 'جامد', '', 'مخافر', 'مخفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8586, 'خِفٌّ', 'خف', 'جامد', 'خفف', 'خف', 'خف', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"خِفٌّ-خِفٌّ، ةٌ [خ ف ف]. ""خِفُّ الْمَتَاعِ"" : الْخَفِيفُ. ""على الرَّغْمِ مِنْ أنَّهُ خِفُّ الْمَظْهَرِ فَهُوَ رَاجِحُ الْعَقْلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8587, 'خَافِقٌ', 'خافق', 'جامد', 'خفق', 'خافق', 'خفق', '', '', '', 'مفرد', '', '', '', '"مثنىخَافِقَانِ-خَافِقَانِ"', '', '', '', '', '', '', '', '', '"خَافِقَانِ-خَافِقَانِ [خ ف ق]. ""مَا بَيْنَ الْخَافِقَيْنِ مِثْلُهُ"" : أفُقُ الْمَغْرِبِ وَأفُقُ الْمَشْرِقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8588, 'خِلْبٌ', 'خلب', 'جامد', 'خلب', 'خلب', 'خلب', '', '', '', 'مفرد', 'DnN', '', '', '"أَخْلاَبٌ"', '', 'R', '', '', '', '', '', '', '". ""أَخْرَجَ الأَسَدُ أَخْلاَبَهُ"": مَخالِبَهُ، أَيْ أَظَافِرَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8589, 'أَخْلاَبٌ', 'أخلاب', 'جامد', '', 'ءخلاب', 'خلب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8590, 'مِخْلَبٌ', 'مخلب', 'جامد', 'خلب', 'مخلب', 'مخلب', '', '', '', 'مفرد', 'DnN', '', '', '"مَخَالِبُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِخْلَبُ الأَسَدِ"" : ظُفْرُهُ. ""مِخْلَبُ الطَّائِرِ"". 2.""مَخَالِبُ الْمَوْتِ"" : أَظَافِرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8591, 'مَخَالِبُ', 'مخالب', 'جامد', '', 'مخالب', 'مخلب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8592, 'خُلَّبٌ', 'خلب', 'جامد', '', 'خلب', 'خلب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1. ""سَحَابٌ خُلَّبٌ"" : سَحَابٌ خَادِعٌ غَيْرُ مُمْطِرٍ. 2. ""بَرْقٌ خُلَّبٌ"" : بَرْقٌ يَحْمِلُ سَحَاباً لاَ مَطَرَ فِيهِ. 3.""إِنَّمَا أَنْتَ كَبَرْقٍ خُلَّبٍ"" : يُقَالُ لِمَنْ يَعِدُ وَلاَ يَفِي بِوَعْدِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8593, 'اِخْتِلاَجَةٌ', 'اختلاجة', 'جامد', 'خلج', 'اختلاجة', 'ختلجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"اِخْتِلاَجَةٌ-اِخْتِلاَجَةٌ [خ ل ج]. ""شَعَرَ بِاخْتِلاَجَةٍ تَسْرِي فِي كُلِّ أَعْضَائِهِ"": رَعْشَةٍ، اِرْتِعَادٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8594, 'خَلْخَالٌ', 'خلخال', 'جامد', 'خلخل', 'خلخال', 'خلخل', '', '', '', 'مفرد', 'DnN', '', '', '"خَلاَخِيلُ"', '', 'R', '', '', '', '', '', '', '". ""تَرْقُصُ بِخَلْخَالِهَا الجَمِيلِ"": سِوَارٌ مِنْ ذَهَبٍ أَوْ فِضَّةٍ يُوضَعُ فِي الرِّجْلِ. تَجُولُ خَلاَخِيلُ النِّسَاءِ، وَلاَ أَرَى*لِرَمْلَةَ خَلْخَالاً يَجُولُ وَلاَ قَلْبا (خالد بن يزيد)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8595, 'خَلاَخِيلُ', 'خلاخيل', 'جامد', '', 'خلاخيل', 'خلخل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8596, 'خَلْخَلٌ', 'خلخل', 'جامد', 'خلخل', 'خلخل', 'خلخل', '', '', '', 'مفرد', 'DnN', '', '', '"خَلاَخِلُ"', '', 'R', '', '', '', '', '', '', '". ن. الخَلْخَالُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8597, 'خَلاَخِلُ', 'خلاخل', 'جامد', '', 'خلاخل', 'خلخل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8598, 'خَلَدٌ', 'خلد', 'جامد', 'خلد', 'خلد', 'خلد', '', '', '', 'مفرد', 'DnN', '', '', '"أَخْلاَدٌ"', '', 'R', '', '', '', '', '', '', '". ""خَطَرَتْ فِي خَلَدِهِ أَفْكَارٌ"": فِي ذِكْرِهِ، فِي بَالِهِ. ""لَمْ يَدُرْ فِي خَلَدِي أَنَّهُ كَانَ يَخْدَعُنِي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8599, 'أَخْلاَدٌ', 'أخلاد', 'جامد', '', 'ءخلاد', 'خلد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8600, 'خُلْدٌ', 'خلد', 'جامد', '', 'خلد', 'خلد', '', '', '', 'جمع تكسير', 'DnN', '', '', '"مَنَاجِذُمِنْغَيْرِلَفْظِهِ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: مَنَاجِذُ مِنْ غَيْرِ لَفْظِهِ (حو).: حَيَوَانٌ ثَدْيِيٌّ مِنْ رُتْبَةِ القَوَارِضِ، آكِلاَتِ الحَشَرَاتِ، لَيْسَ لَهُ أُذُنَانِ فِي الظَّاهِرِ، وَلَهُ عَيْنَانِ صَغِيرَتَانِ بِقَدْرِ عُودِ الثِّقَابِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8601, 'مَنَاجِذُ', 'مناجذ', 'جامد', '', 'مناجذ', 'منجذ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8602, 'خُلْسَةٌ', 'خلسة', 'جامد', 'خلس', 'خلسة', 'خلسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"خُلْسَةٌ-خُلْسَةٌ [خ ل س]. 1. ""يَنْظُرُ إِلَيْهِ خُلْسَةً"" : خُفْيَةً، سِرّاً، عَلَى غَفْلَةٍ. 2. ""هَذِهِ خُلْسَةٌ فَانْتَهِزْهَا"" : هَذِهِ فُرْصَةٌ سَانِحَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8603, 'خِلْصٌ', 'خلص', 'جامد', 'خلص', 'خلص', 'خلص', '', '', '', 'مفرد', 'DnN', '', '', '"خُلَصَاءُ"', '', 'R', '', '', '', '', '', '', '". ""هُوَ مِنْ خُلَصَائِهِ"" : مِنْ أصْدِقَائِهِ الأوْفِيَاءِ الخَالِصِينَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8604, 'خُلَصَاءُ', 'خلصاء', 'جامد', '', 'خلصاء', 'خلص', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8605, 'خَلاَطَةٌ', 'خلاطة', 'جامد', 'خلط', 'خلاطة', 'خلطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"خَلاَطَةٌ-خَلاَطَةٌ [خ ل ط]. ""بِهِ خَلاَطَةٌ"" : حُمْقٌ، فَسَادُ عَقْلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8606, 'خِلْطٌ', 'خلط', 'جامد', 'خلط', 'خلط', 'خلط', '', '', '', 'مفرد', 'DnN', '', '', '"أَخْلاَطٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""لَوْحَةٌ بِهَا خِلْطُ ألوَانٍ"" : اِمْتِزَاجُ ألْوَانِهَا، تَدَاخُلُهَا. 2. ""مَعْدِنٌ خِلْطٌ"" : مَعْدِنٌ اِخْتَلَطَتْ بِهِ مَعَادِنُ أُخْرَى. 3. ""رَجُلٌ خِلْطٌ"" : أَحْمَقُ. 4. ""هُوَ خِلْطٌ"" : وَلَدُ الزِّنَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8607, 'أَخْلاَطٌ', 'أخلاط', 'جامد', '', 'ءخلاط', 'خلط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8608, 'مَخْلُوطَةٌ', 'مخلوطة', 'جامد', 'خلط', 'مخلوطة', 'مخلطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَخْلُوطَةٌ-مَخْلُوطَةٌ [خ ل ط] (طخ).: طَعَامٌ مِنَ العَدَسِ وَالرُّزِّ أَوِ البُرْغُلِ وَالْحِمَّصِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8609, 'خُلْعٌ', 'خلع', 'جامد', 'خلع', 'خلع', 'خلع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خُلْعٌ-خُلْعٌ [خ ل ع]. ""طَلاَقُ الخُلْعِ"" : طَلاَقُ الْمَرْأَةِ بِبَذْلٍ مِنْهَا أَوْ مِنْ غَيْرِهَا لِزَوْجِهَا لِيُطَلِّقَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8610, 'تَخْليِفٌ', 'تخليف', 'جامد', 'خلف', 'تخليف', 'تخلف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَخْليِفٌ-تَخْليِفٌ [خ ل ف]. 1. ""تَخْلِيفُ ابْنٍ"" : إِنْجَابُهُ. 2.""اِجْتَمَعَ الرَّأْيُ عَلَى تَخْلِيفِهِ"" : جَعْلِهِ خَلِيفَةً. 3.""تَخْلِيفُ إِرْثٍ"" : تَرْكُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8611, 'خِلْفٌ', 'خلف', 'جامد', 'خلف', 'خلف', 'خلف', '', '', '', 'مفرد', 'DnN', '', '', '"أَخْلاَفٌ:خُلُوفٌ"', '', 'R', '', '', '', '', '', '', '". 1.""خِلْفُ الضَّرْعِ"": حَلَمَتُهُ. 2.""نَبَاتٌ خِلْفٌ"" : يَنْبُتُ فِي الصَّيْفِ. 3.""وَلَدَانِ خِلْفَانِ"" : مُتَخَالِفَانِ فِي صِفَةٍ مِنَ الصِّفَاتِ. 4.""ذَاتُ الخِلْفَيْنِ"": الفَأْسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8612, 'أَخْلاَفٌ', 'أخلاف', 'جامد', '', 'ءخلاف', 'خلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8613, 'خُلُوفٌ', 'خلوف', 'جامد', '', 'خلوف', 'خلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8614, 'خَلِيفَةٌ', 'خليفة', 'جامد', 'خلف', 'خليفة', 'خلفة', '', '', '', 'مفرد', 'DnN', '', '', '"خُلَفَاءُ"', '', '', '', '', '', '', '', '', '". 1. ""بَايَعَ الْمُسْلِمُونَ الخَلِيفَةَ"" : مَنْ يَتَوَلَّى أَمْرَ الْمُسْلِمِينَ. 2. ""الخُلَفَاءُ الرَّاشِدُونَ"" : الْحُكَّام الَّذِينَ جَاءوا بَعْدَ وَفَاةِ الرَّسُولِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَهُمْ أَبُو بَكْرٍ وَعُمَرُ وَعُثْمَانُ وَعَلِيٌّ رَضِيَ الله عَنْهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8615, 'خُلَفَاءُ', 'خلفاء', 'جامد', '', 'خلفاء', 'خلف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8616, 'خَلِيفٌ', 'خليف', 'جامد', 'خلف', 'خليف', 'خلف', '', '', '', 'مفرد', 'DnN', '', '', '"خُلُفٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""سَارَ فِي الخَلِيفِ"": الطَّرِيقُ بَيْنَ جَبَلَيْنِ. 2. ""ثَوْبٌ خَلِيفٌ"" : ثَوْبٌ بَالٍ مُرَقَّعُ الوَسَطِ. 3. ""رَجُلٌ خَلِيفٌ"": مُخَالِفُ العَهْدِ. 4. ""الْوَلَدُ الخَلِيفُ"" : الْمُسْتَخْلَفُ، جَمْعُهُ خُلَفَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8617, 'خُلُفٌ', 'خلف', 'جامد', '', 'خلف', 'خلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8618, 'أخْلاقٌ', 'أخلاق', 'جامد', 'خلق', 'ءخلاق', 'خلق', '', '', '', 'مفرد', 'DnN', '', '', '"خُلُق"', '', 'R', '', '', '', '', '', '', '". ""لَهُ أَخْلاَقٌ حَسَنَةٌ"" : الآدَابُ والسُّلوكُ الحَسَنُ. إِنَّمَا بُعِثْتُ لأتَمِّمَ مَكَارِمَ الأَخْلاَقِ (حديث )."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8619, 'خُلُق', 'خلق', 'جامد', '', 'خلق', 'خلق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8620, 'خِلْقَةٌ', 'خلقة', 'جامد', 'خلق', 'خلقة', 'خلقة', '', '', '', 'مفرد', 'DnN', '', '', '"خِلَقٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""لَمْ يَرَ خِلْقَةً أَحْسَنَ مِنْهَا"" : هَيْئَةً، شَكْلاً. 2.""خِلْقَةُ الإِنْسَانِ"" : الفِطْرَةُ الَّتِي خُلِقَ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8621, 'خِلَقٌ', 'خلق', 'جامد', '', 'خلق', 'خلق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8622, 'خُلُقٌ', 'خلق', 'جامد', 'خلق', 'خلق', 'خلق', '', '', '', 'مفرد', 'DnN', '', '', '"أَخْلاَقٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""كَانَ عَلَى خُلُقٍ عَظِيمٍ"" : حَسَنُ الطَّبْعِ وَالأَدَبِ وَالسُّلُوكِ. ""عَرَفْتُهُ سَيِّئَ الخُلُقِ"" ""فَاقَ أَقرَانَهُ بِسُمُوِّ أَخْلاَقِهِ"" ""كَرَمُ الأَخْلاَقِ"" ""مَكَارِمُ الأَخْلاَقِ"". 2. ""شُرْطَةُ الأَخْلاَقِ"" : قِسْمٌ فِي جِهَازِ الأَمْنِ يَسْهَرُ عَلَى مُرَاقَبَةِ الآدَابِ العَامَّةِ فِي الْمَدِينَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8623, 'أَخْلاَقٌ', 'أخلاق', 'جامد', '', 'ءخلاق', 'خلق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8624, 'خَلِيقَةٌ', 'خليقة', 'جامد', 'خلق', 'خليقة', 'خلقة', '', '', '', 'مفرد', 'DnN', '', '', '"خَلائِقُ"', '', '', '', '', '', '', '', '', '". 1. ""انْظُرْ وَتَأَمَّلْ هَذِهِ الخَلِيقَةَ"" : مَا خَلَقَهُ اللهُ، الْمَخْلُوقَاتُ. 2. ""هَذِهِ خَلِيقَتُهُ"" : هَذِهِ طَبِيعَتُهُ، سَلِيقَتُهُ، عَادَتُهُ. ""النَّاسُ يَكْسِبُونَ عَلَى رَأْسِ كُلِّ سَنَةٍ عَادَةً جَدِيدَةً وَخَلِيقَةً غَيْرَ مَعْهُودَةٍ"" (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8625, 'خَلائِقُ', 'خلائق', 'جامد', '', 'خلاءق', 'خلق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8626, 'خِلْقِينٌ', 'خلقين', 'جامد', '', 'خلقين', 'خلقن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"خَلاَقِينُ"', '', 'R', '', '', '', '', '', '', '"ج: خَلاَقِينُ. ""خِلْقِينُ الْحَمَّامِ"" : قِدْرٌ مَعْدِنِيَّةٌ لِتَسْخِينِ الْمَاءِ وَتَوْلِيدِ البُخَارِ، المِرْجَلُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8627, 'خَلاَقِينُ', 'خلاقين', 'جامد', '', 'خلاقين', 'خلقن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8628, 'خَلاَّلَةٌ', 'خلالة', 'جامد', 'خلل', 'خلالة', 'خللة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '".: آلَةٌ تَشْبِكُ الأَوْرَاقَ بَعْضهَا بِبَعْضٍ بِالسِّلْكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8629, 'خَلاَلَةٌ', 'خلالة', 'جامد', 'خلل', 'خلالة', 'خللة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خَلاَلَةٌ-خَلاَلَةٌ [خ ل ل]. ""بَيْنَهُمَا خَلاَلَةٌ قَوِيَّةٌ"" : صَدَاقَةٌ، وُدٌّ صَادِقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8630, 'خِلاَلَةٌ', 'خلالة', 'جامد', 'خلل', 'خلالة', 'خللة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خِلاَلَةٌ-خِلاَلَةٌ، خُلاَلَةٌ [خ ل ل]. 1. ""تُنَظِّفُ فُرْشَاةُ الأَسْنَانِ كُلَّ خِلاَلَةٍ"" : مَا يَبْقَى مِنَ الطَّعَامِ بَيْنَ الأَسْنَانِ. 2.: مَا تُخَلَّلُ بِهِ الأَسْنَانُ. 3. ""رَجُلٌ يَأْكُلُ خُلاَلَتَهُ"" : أَيْ رَجُلٌ بَخِيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8631, 'خَلَّةٌ', 'خلة', 'جامد', 'خلل', 'خلة', 'خلة', '', '', '', 'مفرد', 'DnN', '', '', '"خِلاَلٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هَذِهِ خَلَّتُهُ الحَسَنَةُ"" : خَصْلَتُهُ. ""خَلَّةٌ سَيِّئَةٌ"". 2.""رَجُلٌ ذُو خَلَّةٍ"" : أَيْ مُحْتَاجٌ، فَقِيرٌ. 3.""اِمْرَأَةٌ خَلَّةٌ"" : نَحِيفَةٌ. 4.""خَلَّةُ البَابِ"" : ثُقْبَةٌ صَغِيرَةٌ، فُرْجَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8632, 'خِلاَلٌ', 'خلال', 'جامد', '', 'خلال', 'خلل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8633, 'خُلَّةٌ', 'خلة', 'جامد', 'خلل', 'خلة', 'خلة', '', '', '', 'مفرد', 'DnN', '', '', '"خُلَلٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""يَمْتَازُ بِخُلَلٍ عَالِيَةٍ"" : بِخِصَالٍ عَالِيَةٍ، أَخْلاَقٍ حَمِيدَةٍ. 2. ""تَجْمَعُني وَإِيَّاهُ خُلَّةٌ عَمِيقَةٌ"" : صَدَاقَةٌ، مَوَدَّةٌ، إِخَاءٌ. 3. ""خُلَّةُ الإِنْسَانِ"" : أَهْلُ مَوَدَّتِهِ. 4. ""خُلَّةُ الرَّجُلِ"" : زَوْجَتُهُ. 5 : كُلُّ نَبَاتٍ فِيهِ حَلاَوَةٌ. 6. : الأَرْضُ الَّتِي لاَ حَمْضَ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8634, 'خُلَلٌ', 'خلل', 'جامد', '', 'خلل', 'خل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8635, 'خِلَّةٌ', 'خلة', 'جامد', 'خلل', 'خلة', 'خلة', '', '', '', 'مفرد', 'DnN', '', '', '"خِلاَلٌ:خِلَلٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""بَيْنَهُمَا خِلَّةٌ صَادِقَةٌ"" : إِخَاءٌ، مَودَّةٌ، مُصَادَقَةٌ.إبراهيم آية 31 مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ لاَ بَيْعٌ فِيهِ وَلاَ خِلاَلٌ(قرآن). 2. ""خِلَّةُ الطَّعَامِ"" : بَقِيَّةُ الطَّعَامِ بَيْنَ الأَسْنَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8636, 'خِلاَلٌ', 'خلال', 'جامد', '', 'خلال', 'خلل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8637, 'خِلَلٌ', 'خلل', 'جامد', '', 'خلل', 'خل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8638, 'خَلَلٌ', 'خلل', 'جامد', 'خلل', 'خلل', 'خل', '', '', '', 'مفرد', 'DnN', '', '', '"خِلاَلٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""فِي الآلَةِ خَلَلٌ"" : عَطَبٌ، فَسَادٌ. 2. ""فِي رَأْيِهِ خَلَلٌ"" : فَسَادٌ، وَهَنٌ. 3.""أُصِيبَ بِخَلَلٍ عَقْلِيٍّ"" : بِمَسٍّ مِنَ الجُنونِ. 4. ""خَلَلُ الشَّيْئَيْنِ"" : مَا هُوَ مُنْفَرِجٌ بَيْنَهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8639, 'خِلاَلٌ', 'خلال', 'جامد', '', 'خلال', 'خلل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8640, 'خِلَلٌ', 'خلل', 'جامد', 'خلل', 'خلل', 'خل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خِلَلٌ-خِلَلٌ [خ ل ل]. 1.""خِلَلُ الأَسْنَانِ"" : بَقِيَّةُ الطَّعَامِ فِيهَا. 2.""هُوَ فِي خَلَلِ القَوْمِ"": أَيْ بَيْنَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8641, 'خَلْنَجٌ', 'خلنج', 'جامد', '', 'خلنج', 'خلنج', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"خَلْنَجٌ-خَلْنَجٌ (نب).: شَجَرٌ مِنْ فَصِيلَةِ الخَلْنَجِيَّاتِ ، تُنْحَتُ مِنْ خَشَبِهِ القِصَاعُ، لَهُ أَزْهَارٌ وَرْدِيَّةُ اللَّوْنِ وَأَوْرَاقٌ دَقِيقَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8642, 'خَلَوِيَّاتٌ', 'خلويات', 'جامد', '', 'خلويات', 'خلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": حَيَوَانَاتٌ تَتَضَمَّنُ أَعْضَاءَ مِنْ عِدَّةِ خَلاَيَا مُتَنَوِّعَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8643, 'خَلِيَّةٌ', 'خلية', 'جامد', 'خلي', 'خلية', 'خلة', '', '', '', 'مفرد', 'DnN', '', '', '"خَلاَيَا"', '', '', '', '', '', '', '', '', '". 1. ""خَلاَيَا النَّحْلِ مَلِيئَةٌ بِالعَسَلِ"" : بُيُوتُ النَّحْلِ يَقطُنُ فِيهَا. 2. ""خَلِيَّةُ الإِنْسَانِ"" : الْمَادَّةُ الأَسَاسِيَّةُ الَّتِي يَتَكَوَّنُ مِنْهَا كُلُّ كَائِنٍ حَيٍّ. 3. ""الْخَلِيَّةُ الْجُرْثُومِيَّةُ"" : الْمَادَّةُ الَّتِي تَنْتُجُ عَنْهَا الجَرَاثِيمُ، وَالْمُتَفَرِّعَةُ إِلى جُزْئِيَّاتٍ مُتتَالِيَةٍ. 4. ""الْخَلِيَّةُ الدَّمَوِيَّةُ"" : الْمَادَّةُ الْحَمْرَاءُ فِي جُسَيْمَاتِ الدَّمِ الْحُمْرِ. 5. ""خَلِيَّةٌ سِيَاسِيَّةٌ"" : جَمَاعَةٌ تَابِعَةٌ لِحِزْبٍ تَجْتَمِعُ عَلَى انْفِرَادٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8644, 'خَلاَيَا', 'خلايا', 'جامد', '', 'خلايا', 'خل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8645, 'مِخْلاَةٌ', 'مخلاة', 'جامد', 'خلي', 'مخلاة', 'مخلة', '', '', '', 'مفرد', 'DnN', '', '', '"مَخَالٍ"', '', '', '', '', '', '', '', '', '".: كِيسٌ يُجْعَلُ فِيهِ العَلَفُ وَيُعَلَّقُ فِي عُنُقِ الدَّابَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8646, 'مَخَالِي', 'مخالي', 'جامد', '', 'مخالي', 'مخل', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8647, 'خَلِيجٌ', 'خليج', 'جامد', '', 'خليج', 'خلج', '', '', '', 'جمع تكسير', 'DnN', '', '', '"خُلْجَانٌ:خُلُجٌ"', '', 'Rp', '', '', '', '', '', '', '"ج: خُلْجَانٌ، خُلُجٌ. 1. ""رَسَتِ السُّفُنُ فِي الخَلِيجِ العَرَبِيِّ"" : اِمْتِدَادُ نَهْرٍ ضَخْمٍ فِي اليابِسَةِ. 2. ""خَلِيجُ البَحْرِ أَوِ النَّهْرِ"" : جَانِبُهُ. 3. : نَهْرٌ صَغِيرٌ يُقْتَطَعُ مِنَ النَّهْرِ الكَبِيرِ إِلى جِهَةٍ يُنْتَفَعُ بِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8648, 'خُلْجَانٌ', 'خلجان', 'جامد', '', 'خلجان', 'خلجن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8649, 'خُلُجٌ', 'خلج', 'جامد', '', 'خلج', 'خلج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8650, 'خُمٌّ', 'خم', 'جامد', '', 'خم', 'خم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"خِمَمَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: خِمَمَةٌ. ""وَضَعَ الدَّجَاجَ فِي الخُمِّ"" : فِي القَفَصِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8651, 'خِمَمَةٌ', 'خممة', 'جامد', '', 'خممة', 'خممة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8652, 'خُمَانِيَّاتٌ', 'خمانيات', 'جامد', '', 'خمانيات', 'خمنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِنَ ذَواتِ الفِلْقَتَيْنِ وَحِيدَاتُ التُّوَيْجَاتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8653, 'خُمْخُمٌ', 'خمخم', 'جامد', 'خمخم', 'خمخم', 'خمخم', '', '', '', 'مفرد', 'DnN', '', '', '"خَمَاخِمُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"(حو).: مِنَ القِشْرِيَّاتِ العُشَارِيَّاتِ الأَقْدَامِ، قَصِيرُ الذَّيْلِ، مِنْهُ أَنْوَاعٌ عَدِيدَةٌ يَعِيشُ فِي البِحَارِ وَالأَنْهَارِ وَهُوَ مَا يُعْرَفُ بِالسَّرَطَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8654, 'خَمَاخِمُ', 'خماخم', 'جامد', '', 'خماخم', 'خمخم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8655, 'خَمَّارَةٌ', 'خمارة', 'جامد', 'خمر', 'خمارة', 'خمرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خَمَّارَةٌ-خَمَّارَةٌ [خ م ر].: مَحَلُّ بَيْعِ الخُمُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8656, 'خُمَارٌ', 'خمار', 'جامد', 'خمر', 'خمار', 'خمر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خُمَارٌ-خُمَارٌ [خ م ر]. 1. ""بِهِ خُمَارٌ"" : مَا يَعْقُبُ شُرْبَ الْخَمْرِ مِنْ صُدَاعٍ وَأَذىً. 2. ""خُمَارٌ مِنَ النَّاسِ"" : جَمَاعَتُهُمْ وَكَثْرَتُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8657, 'خِمَارٌ', 'خمار', 'جامد', 'خمر', 'خمار', 'خمر', '', '', '', 'مفرد', 'DnN', '', '', '"خُمُرٌ:خُمْرٌ:أَخْمِرَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَضَعَتْ خِمَارًا عَلَى رَأْسِهَا"" : قِطْعَةً مِنَ الثَّوْبِ تُغَطِّي بِهِ الْمَرْأَةُ رَأْسَهَا أَوْكَتِفَيْهَا. 2. ""خِمَارُ الرَّجُلِ"" : عِمَامَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8658, 'خُمُرٌ', 'خمر', 'جامد', '', 'خمر', 'خمر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8659, 'خُمْرٌ', 'خمر', 'جامد', '', 'خمر', 'خمر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8660, 'أَخْمِرَةٌ', 'أخمرة', 'جامد', '', 'ءخمرة', 'خمرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8661, 'خُمْرَةٌ', 'خمرة', 'جامد', 'خمر', 'خمرة', 'خمرة', '', '', '', 'مفرد', 'DnN', '', '', '"خُمَرٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""بِهِ خُمْرَةٌ"" : خُمارٌ، صُدَاع، أَلَمُ الخَمْرِ. 2. ""طَلَتْ وَجْهَهَا بِخُمْرَةٍ"" : غُمْرَةٌ، أَخْلاَطٌ مِنَ الطِّيبِ تَطْلِي بِهَا الْمَرْأَةُ وَجْهَهَا لِيَحْسُنَ لَوْنُهَا. 3.""خُمْرَةُ العَجِينِ"" : مَا يُجْعَلُ فِي العَجِينِ وَنَحْوِهِ مِنَ الْخَمِيَرةِ. 4. ""خُمْرَةُ النَّبِيذِ"" : عَكَرُهُ، أَيْ مَا خَثُرَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8662, 'خُمَرٌ', 'خمر', 'جامد', '', 'خمر', 'خمر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8663, 'خَمْرٌ', 'خمر', 'جامد', 'خمر', 'خمر', 'خمر', '', '', '', 'مفرد', 'DnN', '', '', '"خُمُورٌ"', '', 'R', '', '', '', '', '', '', '". ""لاَ يَشْرَبُ الْمُسْلِمُ الْخَمْرَ"" : عَصِيرُ العِنَبِ يُخْتَمَرُ وَيُسْكِرُ، أَيْ كُلُّ عَصِيرٍ مُسْكِرٍ. ""ثُمَّ تَذْهَبُ الأَحْلاَمُ وَالعَقْلُ مَعاً وَتَتْرُكُهُ الخَمْرُ بِرَذَائِلِهِ وَجُنُونِهِ"" (م. ص. الرافعي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8664, 'خُمُورٌ', 'خمور', 'جامد', '', 'خمور', 'خمر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8665, 'خِمْرٌ', 'خمر', 'جامد', 'خمر', 'خمر', 'خمر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خِمْرٌ-خِمْرٌ [خ م ر]. ""فِي نَفْسِهِ خِمْرٌ"" : حِقْدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8666, 'خَمْرِيَّاتٌ', 'خمريات', 'جامد', 'خمر', 'خمريات', 'خمرت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"خَمْرِيَّاتٌ-خَمْرِيَّاتٌ [خ م ر].: قَصَائِدُ تَصِفُ الْخَمْرَ وَمَجَالِسَهَا وَشَارِبِيهَا. ""خَمْرِيَّاتُ أَبِي نُوَاسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8667, 'خَمِيرٌ', 'خمير', 'جامد', 'خمر', 'خمير', 'خمر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"خَمَائِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""وَضَعْتُ الخَمِيَر فِي العَجِينِ"" : مَا يُجْعَلُ فِي العَجِينِ لِيَخْتمِرَ، أَيْ لِيَنْتَفِخَ بَعْدَ خَبْزِهِ. وَهُوَ مُكَوَّنٌ مِنْ مَادَّةٍ كِيمَاوِيَّةٍ قَادِرَةٍ عَلَى تَحْوِيلِ الْمَوَادِّ الْعُضْوِيَّةِ لِلْخُبْزِ. ""الخَمِيرُ اليسِيرُ يُخَمِّرُ العَجِينَ كُلَّهُ"". 2.""الخَمِيرُ"" : الخُبْزُ الَّذِي اخْتَمَرَ عَجِينُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8668, 'خَمَائِرُ', 'خمائر', 'جامد', '', 'خماءر', 'خمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8669, 'خَامِسٌ', 'خامس', 'جامد', 'خمس', 'خامس', 'خمس', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خَامِسٌ-خَامِسٌ، ةٌ [خ م س]. : 1. عَدَدٌ يَدُلُّ عَلَى التَّرتِيبِ وَيَكُونُ مَعْدُودُهُ مُذَكَّرًا :"" هُوَ الْخَامِسُ فِي الْفَصْلِ"" : أَيْ كَانَتْ رُتْبَتُهُ بَيْنَ الرَّابِعِ وَالسَّادِسِ، وَيُعْرَبُ فِي الْمِثَالِ التَّالي نَعْتاً: ""وَصَلَ الفَائِزُ الْخَامِسُ"". وَإِذَا لَمْ يُذْكَرُ مَعْدُودُهُ : ""وَصَلَ الخَامِسُ"" فَيُعْرَبُ فَاعِلاً، وَهَكَذَا يُعْرَبُ حَسَبَ مَوْقِعِهِ فِي الْجُمْلَةِ. "" الْجُزْءُ الْخَامِسُ"" ""الدَّرَجَةُ الْخَامِسَةُ"" ""تُشِيرُ السَّاعَةُ إِلَى الخَامِسَةِ"". 2. ""خَامِسَ عَشَرَ"" : عَدَدٌ مُرَكَّبٌ يَدُلُّ عَلَى التَّرْتِيبِ، مَعْدُودُهُ مُذَكَّرٌ. و""خَامِسَةَ عَشَرَةَ"" يَكُونُ مَعْدُودُهُ مُؤَنَّثاً. 3. ""خَامِساً"" : تَعْيِينُ التَّرْتِيبِ عِنْدَمَا يَتَعَلَّقُ الأَمْرُ بِمَوْضُوعٍ مُكَوَّنٍ مِنْ عِدَّةِ عَنَاصِرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8670, 'خَمْسَةٌ', 'خمسة', 'جامد', 'خمس', 'خمسة', 'خمسة', '', '', '', 'مفرد', '', '', '', '"عَدَد(5)مُذَكَّرُخَمْسَ:مُفْر', '', '', '', 'N', 'O', 'N', 'O', '', '"خَمْسَةٌ-خَمْسَةٌ [خ م س]. 1. عَدَد (5) مُذَكَّرُ خَمْسَ، مُفْرَدُ مَعْدُودِهِ جمع مذكر : ‏""قَضَى خَمْسَةَ أَيَّامٍ فِي الجَبَلِ"". ""خَمْسَةُ دَرَاهِمَ"". 2. ""سَلَّمَهُ خَمْسَةَ عَشَرَ دِرْهَماً"" : عَدَدٌ مُرَكَّبٌ مَعْدُودُهُ مُذَكَّرٌ مَنْصُوبٌ. ""وَصَلَ خَمْسَةَ عَشَرَ رَجُلاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8671, 'خَمْسٌ', 'خمس', 'جامد', 'خمس', 'خمس', 'خمس', '', '', '', 'مفرد', '', '', '', '"عَدَد(5)مُفْرَدٌمَعْدُودُهُجَ', '', '', '', 'N', 'O', 'N', 'O', '', '"خَمْسٌ-خَمْسٌ [خ م س]. 1. عَدَد (5) مُفْرَدٌ مَعْدُودُهُ جَمْعُ مُؤَنَّثٍ : ""وَصَلَتْ خَمْسُ بَنَاتٍ"". ""زُرْتُهُ خَمْسَ مَرَّاتٍ"". 2.""صَارَ عُمْرُهَا خَمْسَ عَشْرَةَ سَنَةً"": عَدَدٌ مُرَكَّبٌ مَعْدُودُهُ مُفْرَدٌ مُؤَنَّثٌ مَنْصُوبٌ عَلَى التَّمْيِيزِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8672, 'خُمُسٌ', 'خمس', 'جامد', 'خمس', 'خمس', 'خمس', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"خُمُسٌ-خُمُسٌ [خ م س]. ن. خُمْسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8673, 'خُمْسٌ', 'خمس', 'جامد', 'خمس', 'خمس', 'خمس', '', '', '', 'مفرد', 'DnN', '', '', '"أَخْمَاسٌ"', '', 'R', '', '', '', '', '', '', '".1. ""كَانَ نَصِيبُهُ هُوَ الْخُمْسُ"" : جُزْءٌ مِنْ خَمْسَةِ أَجْزَاءٍ. 2. ""ضَرَبَ أَخْمَاساً فِي أَسْدَاسٍ""(مثل) : خَبَطَ خَبْطَ عَشْوَاءَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8674, 'أَخْمَاسٌ', 'أخماس', 'جامد', '', 'ءخماس', 'خمس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8675, 'خَمِيسٌ', 'خميس', 'جامد', 'خمس', 'خميس', 'خمس', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '"خَمِيسٌ-خَمِيسٌ [خ م س]. 1. ""يَوْمُ الخَمِيسِ"" : الْيَوْمُ الخَامِسُ مِنَ الأُسْبُوعِ يَأْتِي بَعْدَ يَوْمِ الأَرْبِعَاءِ، وَيَلِيهِ يَوْمُ الجُمُعَةِ. 2.""اِسْتَقَرَّ الْخَمِيسُ فِي الْجَبْهَةِ الأَمَامِيَّةِ"" : الجَيْشُ الجَرَّارُ لَهُ خَمْسٌ: الْمُقَدِّمَةُ وَالقَلْبُ وَالْمَيْمَنَةُ وَالْمَيْسَرَةُ وَالسَّاقَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8676, 'خُمَاشَةٌ', 'خماشة', 'جامد', 'خمش', 'خماشة', 'خمشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""أُصِيبَ بِخُمَاشةٍ فِي وَجْهِهِ"" : بِجُرْحٍ خَفِيفٍ. 2. ""اِرْتَكَبَ خُمَاشَةً"" : جِنَايَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8677, 'خَمْشَةٌ', 'خمشة', 'جامد', 'خمش', 'خمشة', 'خمشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خَمْشَةٌ-خَمْشَةٌ [خ م ش]. ""تَرَكَتْ عَلَى وَجْهِهِ خَمْشَةً"" : خَدْشَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8678, 'أخمَصُ', 'أخمص', 'جامد', 'خمص', 'ءخمص', 'خمص', '', '', '', 'مفرد', 'DnN', '', '', '"أَخْمَاصٌ"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '". 1. ""أخْمَصُ القَدَمِ"": باطِنُها الَّذِي يَتَجَافَى عَن الأَرْضِ فَلاَ يُصِيبُهَا. ""مِنَ الرَّأْسِ إلَى أَخْمَصِ القَدَمِ"". 2. ""أَخْمَصُ البَدَنِ"" : وَسَطُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8679, 'أَخْمَاصٌ', 'أخماص', 'جامد', '', 'ءخماص', 'خمص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8680, 'خُمَالَةٌ', 'خمالة', 'جامد', 'خمل', 'خمالة', 'خملة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"خُمَالَةٌ-خُمَالَةٌ [خ م ل]. : رِيشُ النَّعَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8681, 'خُمَالٌ', 'خمال', 'جامد', 'خمل', 'خمال', 'خمل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خُمَالٌ-خُمَالٌ [خ م ل]. 1. : دَاءٌ فِي مَفَاصِلِ الإِنْسَانِ وَقَوَائِمِ الحَيَوَانِ يَعْرَجُ مِنْهُ. 2.""هُوَ خُمَالُهُ"": صَدِيقُهُ الْمُصَافِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8682, 'خَمْلَةٌ', 'خملة', 'جامد', 'خمل', 'خملة', 'خملة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خَمْلَةٌ-خَمْلَةٌ [خ م ل].: الثَّوْبُ الْمُخْمَلُ، القَطِيفَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8683, 'خَمْلٌ', 'خمل', 'جامد', 'خمل', 'خمل', 'خمل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَمْلٌ-خَمْلٌ [خ م ل]. 1. ""حَشَا الْمِخَدَّةَ بِالخَمْلِ"" : بِرِيشِ النَّعَامِ وَمَا شَابَهَ ذَلكَ. 2.: هَدْبُ الْقَطِيفَةِ وَنَحْوِهَا مِمَّا يُنْسَجُ وَتَفْضُلُ لَهُ فُضُولٌ. 3. ""خَمْلُ الْمَعِدَةِ"" : أَلْيَافٌ كَأَهْدَابِ القَطِيفَةِ تُغَطِّي سَطْحَهَا البَاطِنَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8684, 'خَمِيلَةٌ', 'خميلة', 'جامد', 'خمل', 'خميلة', 'خملة', '', '', '', 'مفرد', 'DnN', '', '', '"خَمَائِلُ"', '', '', '', '', '', '', '', '', '". 1.""اِخْتَفَى الحَيَوَانُ بَيْنَ الخَمَائِلِ"" : مَوَاضِيعُ كَثِيفَةُ الشَّجَرِ، مُلْتَفٌّ بَعْضُهَا بِبَعْضٍ. 2.""حَدِيقَةٌ خَمِيلَةٌ"" : كَثِيرَةُ الشَّجَرِ. 3.""سِرْوَالٌ، ثَوْبُهُ خَمِيلَةٌ"": أَيْ مِنَ الثِّيَابِ الْمُخْمَلَةِ، القَطِيفَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8685, 'خَمَائِلُ', 'خمائل', 'جامد', '', 'خماءل', 'خمل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8686, 'خَنَازِيرِيَّاتٌ', 'خنازيريات', 'جامد', '', 'خنازيريات', 'خنزرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"خَنَازِيرِيَّاتٌ-خَنَازِيرِيَّاتٌ (نب).: فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتيْنِ أَنْوَاعُهُ عَدِيدَةٌ مِنْهَا عُرْفُ الدِّيكِ وَأنْفُ العِجْلِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8687, 'خَنَازِيرِيَّةٌ', 'خنازيرية', 'جامد', '', 'خنازيرية', 'خنزرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"خَنَازِيرِيَّةٌ-خَنَازِيرِيَّةٌ (نب).: نَبَاتٌ مِنْ فَصِيلَةِ الخَنَازِيرِيَّاتِ، عُشْبِيٌّ جَنْبِيٌّ. تَظْهَرُ زَهْرَتُهُ فَوْقَ أَوْرَاقٍ عَرِيضَةٍ، رَائِحَتُهُ كَرِيهَةٌ، كَانَ يُسْتَخْدَمُ فِي مُعَالَجَةِ الأمْرَاضِ الجِلْدِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8688, 'خُنَثٌ', 'خنث', 'جامد', 'خنث', 'خنث', 'خنث', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خُنْثٌ-خُنْثٌ [خ ن ث]. ""جَاءَ فِي كَلاَمِهِ خُنْثٌ"" : التَّكَسُّرُ وَالتَّثَنِّي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8689, 'خُنْثٌ', 'خنث', 'جامد', 'خنث', 'خنث', 'خنث', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خُنَثٌ-خُنَثٌ [خ ن ث]. ""يَا خُنَثٌ"" : صِيغَةٌ تُقَالُ لِلرَّجُلِ فِي الشَّتْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8690, 'خُنْثَى', 'خنثى', 'جامد', 'خنث', 'خنثى', 'خنث', '', '', '', 'مفرد', 'Dy', '', '', '"خُنَاثَى"', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '". ""رَجُلٌ خُنْثَى"" : مَنْ تَتَدَاخَلُ فِيهِ صِفَةُ الرَّجُلِ وَالْمَرْأَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8691, 'خُنَاثَى', 'خناثى', 'جامد', '', 'خناثى', 'خنث', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8692, 'خَنْجَرٌ', 'خنجر', 'جامد', 'خنجر', 'خنجر', 'خنجر', '', '', '', 'مفرد', 'DnN', '', '', '"خَنَاجِرُ"', '', 'R', '', '', '', '', '', '', '". ""أَشْهَرَ خَنْجَرَهُ فِي وَجْهِهِ"" : السِّكِّين العَظِيمَة. ""وَضَعَ الخَنْجَرَ فِي حَمَالَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8693, 'خَنَاجِرُ', 'خناجر', 'جامد', '', 'خناجر', 'خنجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8694, 'خِنْجَرٌ', 'خنجر', 'جامد', 'خنجر', 'خنجر', 'خنجر', '', '', '', 'مفرد', 'DnN', '', '', '"خَنَاجِرُ"', '', 'R', '', '', '', '', '', '', '". ن. خَنْجَر."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8695, 'خَنَاجِرُ', 'خناجر', 'جامد', '', 'خناجر', 'خنجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8696, 'خَنْدَقٌ', 'خندق', 'جامد', 'خندق', 'خندق', 'خندق', '', '', '', 'مفرد', 'DnN', '', '', '"خَنَادِقُ"', '', 'R', '', '', '', '', '', '', '". ""حَفَرَ الجَيْشُ خَنَادِقَ حَوْلَ أَسْوَارِ الْمَدِينَةِ"" : حُفَرٌ مُسْتَطِيلَةٌ فِي الأَرْضِ لِلاحْتمَاءِ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8697, 'خَنَادِقُ', 'خنادق', 'جامد', '', 'خنادق', 'خندق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8698, 'خِنْزِيرٌ', 'خنزير', 'جامد', '', 'خنزير', 'خنزر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"خَنَازِيرُ"', '', 'R', '', '', '', '', '', '', '"ج: خَنَازِيرُ. (حو). 1.: حَيَوَانٌ مِنْ فَصِيلَةِ الخِنْزِيرِيَّاتِ مِنْ رُتْبَةِ الظِّلْفِيَّاتِ، آكِلاَتِ الأعْشَابِ وَاللُّحُومِ، سَمِينٌ، لَهُ خَطْمٌ طَوِيلٌ ذُو نِهَايَةٍ متَّسِعَةٍ. وَهُوَ أنْوَاعٌ : الْخِنْزِيرُ البَرِّيُّ وَيَخْتَلِفُ عَنِ الخِنْزِيرِ الأهْلِيِّ بِعَدَدِ أنْياَبِهِ وَجِلْدِهِ الْمُخْشَوْشِنِ. 2 ""خِنْزِيرُ البَحْرِ"" : نَوْعٌ مِنَ الحِيتَـانِ الثَّدْيِيَّاتِ يَعِيشُ فِي السَّوَاحِلِ وَهُوَ أَصْغَرُ مِنَ الدُّلْفِينِ.المائدة آية 3 حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الخِنْزِير (قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8699, 'خَنَازِيرُ', 'خنازير', 'جامد', '', 'خنازير', 'خنزر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8700, 'خِنْزِيرَةٌ', 'خنزيرة', 'جامد', '', 'خنزيرة', 'خنزرة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أُنْثَىالخِنْزِيرِ"', '', 'R', '', '', '', '', '', '', '": أُنْثَى الخِنْزِيرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8701, 'خِنْزِيرِيَّاتٌ', 'خنزيريات', 'جامد', '', 'خنزيريات', 'خنزرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ حَيَوَانِيَّةٌ مِنْ مُزْدَوِجَاتِ الأَصَابِعِ، مِنْ أشْهَرِ أنْوَاعِهَا الخِنْزِيرُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8702, 'خَنَّاسٌ', 'خناس', 'جامد', 'خنس', 'خناس', 'خنس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَنَّاسٌ-خَنَّاسٌ [خ ن س]. ""وَسْوَسَ لَهُ الخَنَّاسُ"" : الشَّيْطَانُ لِأَنَّهُ يَخْنِسُ، أَيْ يَنْقَبِضُ إِذَا ذُكِرَ اسْمُ اللهِ. الناس آية 1قُلْ أَعُوذُ بِرَبِّ النَّاسِ مَلِكِ النَّاسِ إِلَهِ النَّاسِ مِنْ شَرِّ الوَسْوَاسِ الْخَنَّاس (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8703, 'خَنْسَاءُ', 'خنساء', 'جامد', '', 'خنساء', 'خنس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"1. : البَقَرَةُ الوَحْشِيَّةُ. 2. ""اِمْرَأَةٌ خَنْسَاءُ"" : أَيْ لَهَا أَنْفٌ خَانِسٌ. 3.: اِسْمُ عَلَمٍ لِلْمُؤَنَّثِ عُرِفَتْ بِهِ شَاعِرَةٌ مِنَ العَصْرِ الْجَاهِلِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8704, 'خِنْصَرٌ', 'خنصر', 'جامد', 'خنصر', 'خنصر', 'خنصر', '', '', '', 'مفرد', 'DnN', '', '', '"خَنَاصِرُ(مؤ)"', '', 'R', '', '', '', '', '', '', '". 1.:الأُصْبُعُ الصُّغْرَى. 2. ""هَذَا أَمْرٌ تُعْقَدُ عَلَيْهِ الخَنَاصِرُ"" : أَيْ يُعْتَدُّ بِهِ وَيُصَانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8705, 'خَنَاصِرُ', 'خناصر', 'جامد', '', 'خناصر', 'خنصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8706, 'خَنَاعَةٌ', 'خناعة', 'جامد', 'خنع', 'خناعة', 'خنعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"خَنَاعَةٌ-خَنَاعَةٌ [خ ن ع]. ""رَفَضَ أَنْ يَرَاهُ فِي خَنَاعَةٍ"" : فِي ذِلَّةٍ، ضِعَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8707, 'خَنَعٌ', 'خنع', 'جامد', 'خنع', 'خنع', 'خنع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَنَعٌ-خَنَعٌ [خ ن ع]. ""عَاشَ فِي خَنَعٍ"" : فِي ذُلٍّ. وَلاَ ثَوْبُ البَقَاءِ بِثوْبِ عِزٍّ*فَيُطْوَى عَنْ أَخِي الخَنَعِ اليَرَاع (قطري بن فجاءة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8708, 'خَنُوعٌ', 'خنوع', 'جامد', 'خنع', 'خنوع', 'خنع', '', '', '', 'مفرد', 'DnN', '', '', '"خُنُعٌ"', '', 'R', '', '', '', '', '', '', '". ""عَاشَ خَنُوعاً"" : ذَلِيلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8709, 'خُنُعٌ', 'خنع', 'جامد', '', 'خنع', 'خنع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8710, 'خَنِيفَةٌ', 'خنيفة', 'جامد', 'خنف', 'خنيفة', 'خنفة', '', '', '', 'مفرد', 'DnN', '', '', '"خَنَائِفُ"', '', '', '', '', '', '', '', '', '".: كَتَّانٌ غَلِيظٌ صَلْبٌ، تُغَطَّى بِهِ البَضَائِعُ وَمَا يُخْشَى عَلَيْهِ مِنَ الْمَطَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8711, 'خَنَائِفُ', 'خنائف', 'جامد', '', 'خناءف', 'خنف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8712, 'خُنْفُسٌ', 'خنفس', 'جامد', 'خنفس', 'خنفس', 'خنفس', '', '', '', 'مفرد', 'DnN', '', '', '"خَنَافِسُ"', '', 'R', '', '', '', '', '', '', '".: دُوَيِبَّةٌ سَوْدَاءُ كَرِيهَةُ الرَّائِحَةِ مِنْ مُغْمَدَاتِ الأَجْنِحَةِ، وَهِيَ أَصْغَرُ مِنَ الجُعَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8713, 'خَنَافِسُ', 'خنافس', 'جامد', '', 'خنافس', 'خنفس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8714, 'خُنْفُسَاءُ', 'خنفساء', 'جامد', '', 'خنفساء', 'خنفس', '', '', '', 'جمع تكسير', 'Dz', '', '', '"خَنَافِسُ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"ج: خَنَافِسُ. 1. ن.خُنْفُـسٌ. 2. ""خُنْفُسَـاءُ البَطَاطيسِ"" : (حش).: حَشَرَةٌ مِنْ مُغْمَدَاتِ الأجْنِحَةِ، تَضُرُّ بِالْبَطَاطِيسِ. ""الخُنْفُسَاءُ إِذَا مُسَّتْ نَتُنَتْ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8715, 'خَنَافِسُ', 'خنافس', 'جامد', '', 'خنافس', 'خنفس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8716, 'خُنَّاقٌ', 'خناق', 'جامد', 'خنق', 'خناق', 'خنق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خِنَاقٌ-خِنَاقٌ [خ ن ق]. 1. ""أَخَذَ بِخِنَاقِهِ"" : أَيْ أَخَذَ بِعُنُقِهِ. 2. ""ضَيَّقَ الخِنَاقَ عَلَى العُمَّالِ"" : ضَايَقهُمْ بِشِدَّةٍ، أَكْثَرَ عَلَيْهِمُ العَمَلَ، أَحْرَجَهُمْ، جَعَلَهُمْ فِي مَوْقِفٍ حَرِجٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8717, 'خِنَاقٌ', 'خناق', 'جامد', 'خنق', 'خناق', 'خنق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خُنَّاقٌ-خُنَّاقٌ [خ ن ق]. ""أُصِيبَ بِدَاءِ الخُنَّاقِ"" : دَاءٌ يَعْسُرُ مَعَهُ دُخُولُ النَّفْسِ إِلَى الرِّئَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8718, 'مِخْنَقَةٌ', 'مخنقة', 'جامد', 'خنق', 'مخنقة', 'مخنقة', '', '', '', 'مفرد', 'DnN', '', '', '"مَخَانِقُ"', '', 'R', '', '', '', '', '', '', '". : مَا يُخْنَقُ بِهِ مِنْ حَبْلٍ أو غَيْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8719, 'مَخَانِقُ', 'مخانق', 'جامد', '', 'مخانق', 'مخنق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8720, 'خُنَانٌ', 'خنان', 'جامد', 'خنن', 'خنان', 'خنن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خُنَانٌ-خُنَانٌ [خ ن ن]. 1.: دَاءٌ يُصِيبُ الأَنْفَ كَالزُّكَامِ. 2.: دَاءٌ يُصِيبُ الطَّيْرَ فِي حُلُوقِهَا وَفِي العَيْنِ. 3.: زُكَامُ الإِبِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8721, 'خَوْخٌ', 'خوخ', 'جامد', 'خوخ', 'خوخ', 'خخ', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"خَوْخٌ-خَوْخٌ [خ و خ]. 1.: شَجَرٌ مُثْمِرٌ مِنْ فَصِيلَةِ الوَرْدِيَّاتِ. 2.: فَاكِهَةُ شَجَرَةِ الخَوْخِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8722, 'خَوْخَةٌ', 'خوخة', 'جامد', '', 'خوخة', 'خخة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":وَاحِدَةُالخَوْخِ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"وَاحِدَةُ الخَوْخِ. 1.: ثَمَرَةُ شَجَرَةِ الخَوْخِ. 2.""يُطِلُّ مِنْ وَرَاءِ الخَوْخَةِ"" : جُزْءٌ مِنْ لَوْحِ بَاب كَبِيرٍ أوْ بَابٌ صَغِيرٌ وَسَطَ البَابِ الكَبِيرِ،كُوَّةٌ تُؤَدِّي الضَّوْءَ إِلَى البَيْتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8723, 'خُوذَةٌ', 'خوذة', 'جامد', 'خوذ', 'خوذة', 'خذة', '', '', '', 'مفرد', 'DnN', '', '', '"خُوَذٌ"', '', 'R', '', '', '', '', '', '', '". ""خُوذَةُ الجُنْدِيِّ"" : مَا يَجْعَلُهُ الجُنْدِيُّ الْمُحَارِبُ عَلَى رَأْسِهِ لِيَقِيَهُ مِنَ الضَّرْبِ أَوِ الرَّصَاصِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8724, 'خُوَذٌ', 'خوذ', 'جامد', '', 'خوذ', 'خذ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8725, 'خُورِي', 'خوري', 'جامد', '', 'خوري', 'خر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"خَوَارِنَةٌ"', '', 'R0', '', '', '', '', '', '', '"ج: خَوَارِنَةٌ. 1.: الكَاهِنُ. 2. ""الخُورِي الأُسْقُفِيُّ"" : نَائِبُ الأُسْقُفِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8726, 'خَوَارِنَةٌ', 'خوارنة', 'جامد', '', 'خوارنة', 'خرنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8727, 'خُوصٌ', 'خوص', 'جامد', 'خوص', 'خوص', 'خص', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خُوصٌ-خُوصٌ [خ و ص]. ""يَصْنَعُ مِنْ خُوصِ النَّخِيلِ قُفَفاً"" : مِنْ وَرَقِ النَّخِيلِ. ""عَمِلَ مِنَ الخُوصِ وَالحَلْفَاءِ شِبْهَ حِزَامٍ عَلَى وَسَطِهِ"" (ابن طفيل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8728, 'مِخْوَضٌ', 'مخوض', 'جامد', 'خوض', 'مخوض', 'مخض', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِخْوَضٌ-مِخْوَضٌ [خ و ض].: آلَةٌ لِخَلْطِ الْمَوَادَّ السَّائِلَةِ وَتَحْرِيكِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8729, 'مَخَاوِفُ', 'مخاوف', 'جامد', 'خوف', 'مخاوف', 'مخف', '', '', '', 'مفرد', '', '', '', '"مفردمَخَافَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". "" اِسْتَبَدَّتْ بِهِ الْمَخَاوِفُ"" : الأَخْطَارُ، الأَوْجَاعُ، الْمَحَاذِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8730, 'مَخَافَة', 'مخافة', 'جامد', '', 'مخافة', 'مخفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8731, 'خَالٌ', 'خال', 'جامد', 'خول', 'خال', 'خل', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '":أخْوَالٌ:خُؤُولَةٌ"', '', 'R', '', '', '', '', '', '', '". ""جَاءَ خَالِي لِزِيَارَةِ أُخْتِهِ"" : أخُو أمِّي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8732, 'أخْوَالٌ', 'أخوال', 'جامد', '', 'ءخوال', 'خل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8733, 'خُؤُولَةٌ', 'خؤولة', 'جامد', '', 'خءولة', 'خلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8734, 'خَوْلَةٌ', 'خولة', 'جامد', 'خول', 'خولة', 'خلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"خَوْلَةٌ-خَوْلَةٌ [خ و ل]. 1.: ظَبْيَةٌ، غَزَالَةٌ. 2. خَوْلَةُ : اِسْمُ عَلَمٍ لِلإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8735, 'خَوْلَنْجَانُ', 'خولنجان', 'جامد', '', 'خولنجان', 'خلنجن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'O', 'O', 'O', '', '"خَوْلَنْجَانُ-خَوْلَنْجَانُ (نب).: نَبَاتٌ عُشْبِيٌّ مِنْ فَصِيلَةِ الزَّنْجَبِيلِيَّاتِ، أَنْوَاعُهُ عَدِيدَةٌ، مِنْهَا مَا هُوَ طِبِّيٌّ، وَمَا هُوَ تَزْيِينِيٌّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8736, 'خَانَةٌ', 'خانة', 'جامد', 'خون', 'خانة', 'خنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""خَانَةُ رُقْعَةِ الشِّطْرَنْجِ"": مُرَبَّعٌ مِنْ مُرَبَّعَاتِهِ. 2.""خَانَةُ الصَّوْتِ"" : مَقْطَعُ الصَّوْتِ فِي انْخِفَاضٍ أَوِ ارْتِفَاعٍ. 3. ""خَانَةُ الْعَشَرَاتِ"" : الْمَنْزِلَةُ الْحِسَابِيَّةُ لِلأَعْدَادِ، مَثَلاً 4563 : رَقَمُ 3 يَقَعُ فِي خَانَةِ الآحَادِ و6 فِي خَانَةِ العَشَرَاتِ و5 فِي خَانَةِ الْمِئَاتِ و4 فِي خَانَةِ الآلاَفِ. 4. ""خَانَةُ الطَّبَاشِيرِ"" : مُرَبَّعٌ مُكَعَّبٌ داخِلَ الجِدار يُوضَعُ فِيهِ الطَّبَاشِيرُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8737, 'خِوَانٌ', 'خوان', 'جامد', 'خون', 'خوان', 'خن', '', '', '', 'مفرد', 'DnN', '', '', '"أَخْوِنَةٌ:خُونٌ"', '', 'R', '', '', '', '', '', '', '". ""حَضَّرَتِ الخِوَانَ"": مَائِدَةَ الطَّعَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8738, 'أَخْوِنَةٌ', 'أخونة', 'جامد', '', 'ءخونة', 'خنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8739, 'خُونٌ', 'خون', 'جامد', '', 'خون', 'خن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8740, 'خُوَّةٌ', 'خوة', 'جامد', 'خوي', 'خوة', 'خة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خُوَّةٌ-خُوَّةٌ [خ و ي]. ""أقَامَ فِي خُوَّةٍ"" : فِي أرْضٍ خَاليةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8741, 'خَوِيَّةٌ', 'خوية', 'جامد', 'خوي', 'خوية', 'خة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خَوِيَّةٌ-خَوِيَّةٌ [خ و ي]. 1.""أَطْعَمَهَا الْخَوِيَّةَ"" : طَعَامٌ يُصْنَعُ لِلنُّفَسَاءِ. 2.: مَفْرَجٌ مَا بَيْنَ الضَّرْعِ وَالقُبُلِ مِنَ الأَنْعَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8742, 'خِيَارٌ', 'خيار', 'جامد', '', 'خيار', 'خر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": نَبَاتٌ مِنْ فَصِيلَةِ القَرْعِيَّاتِ يُؤكَلُ نَيِّئاً مُخَلَّلاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8743, 'خَيْتَ', 'خيت', 'جامد', '', 'خيت', 'خت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'N', '', '"1. ""خَيْتَ عَلَى مَا فَعَلَتْ"" : أَيْ ما أَحْقَرَ مَا فَعَلَتْ! . 2.: التَّصْوِيتُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8744, 'خَيْرَاتٌ', 'خيرات', 'جامد', 'خير', 'خيرات', 'خرت', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَيْرَاتٌ-خَيْرَاتٌ [خ ي ر]. ""خَيْرَاتُ الأَرْضِ لاَ حَصْرَ لَهَا"" : مَوَارِدُهَا، مَنَافِعُهَا، نِعَمُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8745, 'خَيْرَةٌ', 'خيرة', 'جامد', 'خير', 'خيرة', 'خرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"خَيْرَةٌ-خَيْرَةٌ [خ ي ر]. 1. ""هَذِهِ خَيْرَتِي"" : مَا يُخْتارُ. 2.""هِيَ خَيْرَةُ النِّسَاءِ"" : فَاضِلَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8746, 'خَيْرٌ', 'خير', 'جامد', 'خير', 'خير', 'خر', '', '', '', 'مفرد', 'DnN', '', '', '"خِيَارٌ:أَخْيَارٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""يَسْعَى إِلَى كُلِّ عَمَلٍ فِيهِ خَيْرٌ لِلنَّاسِ"" : نَفْعٌ. ""لاَ خَيْرَ فِيهِ"". 2. ""خَيْرٌ لَكَ أَنْ تُسَافِرَ صَبَاحاً"" : مِنَ الأَحْسَنِ، مِنَ الأَفْضَلِ. ‎ ""الوِقَايَةُ خَيْرٌ مِنَ العِلاَجِ"".(مثل). 3. ""هُوَ خَيْرٌ مِنْكَ"" : أَحْسَنُ مِنْكَ. 4.""الخَيْرُ العَامُّ"" : الصَّالِحُ العَامُّ. 5.""هُوَ مِنْ أَخْيَارِ النَّاسِ"" : مِنْ أَفَاضِلِهِمْ. ""خَيْرُ النَّاسِ"". 6.""خَيْرُ البِرِّ عَاجِلُهُ"" : مَافِيهِ نَفْعٌ يَنْبَغِي أَنْ يُعَجَّلَ بِهِ. ""خَيْرُ الغِنَى القُنُوعُ وَشَرُّ الفَقْرِ الخُضُوعُ"".(مثل) ""الخَيْرُ أَبْقَى وَإِنْ طَالَ الزَّمَانُ بِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8747, 'خِيَارٌ', 'خيار', 'جامد', '', 'خيار', 'خر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8748, 'أَخْيَارٌ', 'أخيار', 'جامد', '', 'ءخيار', 'خر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8749, 'مُخْتَارٌ', 'مختار', 'جامد', 'خير', 'مختار', 'مختر', '', '', '', 'مفرد', 'DnN', '', '', '"مَخَاتِيرُ"', '', 'R', '', '', '', '', '', '', '". ""مُخْتَارُ القَرْيَةِ"" : كَبِيرُ أَهْلِ القَرْيَةِ، العُمْدَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8750, 'مَخَاتِيرُ', 'مخاتير', 'جامد', '', 'مخاتير', 'مختر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8751, 'خَيْزُرَانٌ', 'خيزران', 'جامد', '', 'خيزران', 'خزرن', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"خَيَازِرُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: خَيَازِرُ. (نب).: نَبَاتٌ مِنْ فَصِيلَةِ النَّجْلِيَّاتِ، وَهُوَ سَرِيعُ النُّمُوِّ، يَمْتَازُ بِقُضْبَانِهِ اللَّيِّنَةِ وَعِيدَانِهِ الْمَلْسَاءِ، وَيُقْصَدُ بِهِ أَيْضاً القَصَبُ، وَيُسْتَعْمَلُ فِي الصِّنَاعَةِ الخَشَبِيَّةِ. فِي كَفِّهِ خَيْزُرَانٌ رِيحُهُ عَبِقٌ*مِنْ كَفٍّ أَرْوَعَ فِي عِرْنِينِهِ شَمَمٌ (الفرزدق)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8752, 'خَيَازِرُ', 'خيازر', 'جامد', '', 'خيازر', 'خزر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8753, 'خَيْشٌ', 'خيش', 'جامد', 'خيش', 'خيش', 'خش', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَيْشٌ-خَيْشٌ [خ ي ش]. ""صَنَعَ أَكْيَاساً مِنَ الْخَيْشِ"" : كَتَّانٌ يُنْسَجُ مِنْ خُيُوطٍ خَشِنَةٍ، أَيْ مِنْ قِشْرِ الْقِنَّبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8754, 'خَيْشُومٌ', 'خيشوم', 'جامد', 'خيش', 'خيشوم', 'خشم', '', '', '', 'مفرد', 'DnN', '', '', '"خَيَاشِيمُ"', '', 'R', '', '', '', '', '', '', '". 1.""يَسِيلُ الدَّمُ مِنْ خَيْشُومِ أَنْفِهِ"" : مِنْ أَقْصَى أَنْفِهِ. 2. ""تَتَنَفَّسُ السَّمَكَةُ مِنْ خَيَاشِيمِهَا"" : غَلاَصِمِهَا، أَعْضَاءُ تَنَفُّسِ الحَيَوَانَاتِ الْمَائِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8755, 'خَيَاشِيمُ', 'خياشيم', 'جامد', '', 'خياشيم', 'خشم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8756, 'خِيَاطَةٌ', 'خياطة', 'جامد', 'خيط', 'خياطة', 'خطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"خِيَاطَةٌ-خِيَاطَةٌ [خ ي ط]. 1.""تَعَلَّمَ الخِيَاطَةَ"" : مِهنةُ الخَيَّاطِ. 2.""آلَةُ الخِيَاطَةِ"" : آلَةٌ لِصُنْعِ الْمَلاَبِسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8757, 'خِيَاطٌ', 'خياط', 'جامد', 'خيط', 'خياط', 'خط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خِيَاطٌ-خِيَاطٌ [خ ي ط]. 1.: مَا يُخَاطُ بِهِ الثَّوْبُ كَالإِبْرَةِ، أَي المِخْيَطِ. 2. ""سَمُّ الخِيَاطِ"" : ثَقْبُ الإِبْرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8758, 'خَيْطٌ', 'خيط', 'جامد', 'خيط', 'خيط', 'خط', '', '', '', 'مفرد', 'DnN', '', '', '"خُيُوطٌ:خِيطَانٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""أَدْخَلَتِ الْخَيْطَ فِي عَيْنِ الإِبْرَةِ"" : السِّلْكُ مِنْ نَسِيجِ الكَتَّانِ أَوِ الثَّوْبِ أَوِ الصُّوفِ. 2. ""بَدَأَتْ خُيُوطُ الضَّوْءِ تَشِعُّ"" : أَشِعَّةُ الضَّوْءِ. 3.""الخَيْطُ الأَبْيَضُ"" : بَيَاضُ النَّهَارِ. 4. ""الخَيْطُ الأَسْوَدُ"" : سَوَادُ اللَّيْلِ.البقرة آية 187 وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الخَيْطُ الأَبْيَضُ مِنَ الخَيْطِ الأَسْوَدِ مِنَ الْفَجْرِ (قرآن). 5. ""خَيْطُ العَنْكَبُوتِ"" : مَا يَخْرُجُ مِنْ فَمِ العَنْكَبُوتِ، خَيْطٌ دَقِيقٌ جِدّاً. 6.""تَقَطَّعَتْ آخِرُ خُيُوطِ الأَمَلِ"" : أَيْ مَا كَانَ يَشُـدُّهُ إِلى الأَمَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8759, 'خُيُوطٌ', 'خيوط', 'جامد', '', 'خيوط', 'خط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8760, 'خِيطَانٌ', 'خيطان', 'جامد', '', 'خيطان', 'خطن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8761, 'مِخْيَطٌ', 'مخيط', 'جامد', 'خيط', 'مخيط', 'مخط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِخْيَطٌ-مِخْيَطٌ [خ ي ط]. : إِبْرَةٌ غَلِيظَةٌ لِلْخِيَاطَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8762, 'خَيْفٌ', 'خيف', 'جامد', 'خيف', 'خيف', 'خف', '', '', '', 'مفرد', 'DnN', '', '', '"أَخْيَافٌ:خُيُوفٌ"', '', 'R', '', '', '', '', '', '', '".: مَا ارْتَفَعَ عَنْ مَجْرَى السَّيْلِ وَانْحَدَرَ عَنْ غِلَظِ الجَبَلِ. ""خَيْفُ مِنـىً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8763, 'أَخْيَافٌ', 'أخياف', 'جامد', '', 'ءخياف', 'خف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8764, 'خُيُوفٌ', 'خيوف', 'جامد', '', 'خيوف', 'خف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8765, 'خَالٌ', 'خال', 'جامد', 'خيل', 'خال', 'خل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَالٌ-خَالٌ [خ ي ل]. ""خَالُهَا يَزِيدُهَا رَوْنَقاً وَجَمَالاً"" : بَثْرَةٌ، نُقْطَةٌ سَوْدَاءُ تَكُونُ فِي الوَجْهِ خِلْقَةً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8766, 'خَيَالَةٌ', 'خيالة', 'جامد', 'خيل', 'خيالة', 'خلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1. ""تَتَرَاءى لَهُ خَيَالاَتٌ"" : الأَشْبَاحُ، الأَطْيَافُ يَتَخَيَّلُهَا الْمَرْءُ فِي مَكَانٍ خَالٍ أَوْ فِي يَقَظَتِهِ. 2. ""خَيَالَةُ الرَّجُلِ"" : طَيْفُهُ، شَخْصُهُ. 3. ""فَنُّ الخَيَالَةِ"" : فَنُّ السِّينِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8767, 'خَيَالٌ', 'خيال', 'جامد', 'خيل', 'خيال', 'خل', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَخْيِلَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""ذَهَبَ خَيَالُهُ بَعِيداً"" : تَصَوُّرُهُ. 2.""لَهُ خَيَالٌ وَاسِعٌ"" : تَخَيُّلٌ، مَا يَرَاهُ الإِنْسَانُ مِنْ صُوَرٍ فِي يَقَظَتِهِ. 3.""شَتَّانَ مَا بَيْنَ الحَقِيقَةِ وَالخَيَالِ"": أَيِ الوَهْمِ. 4. ""يَخَافُ مِنْ خَيَالِهِ"" : مِنْ ظِلِّهِ. 5.""وَقَفَ يَتَأمَّلُ خَيَالَهُ"" : صُورَتَهُ الْمُنْعَكِسَةَ فِي المِرْآةِ. 6.""خَيَالُ الظِّلِّ"" : فَنٌّ مِنْ فُنُونِ التَّمْثِيلِ يَعْتَمِدُ عَلَى إِظْهَارِ الخَيَالِ مِنْ خَلْفِ السِّتَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8768, 'أَخْيِلَةٌ', 'أخيلة', 'جامد', '', 'ءخيلة', 'خلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8769, 'خُيَلاَءُ', 'خيلاء', 'جامد', 'خيل', 'خيلاء', 'خل', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خُيَلاَءُ-خُيَلاَءُ [خ ي ل]. ""يُظْهِرُ الخُيَلاَءَ"" : العُجْبَ، التَّكَبُّرَ، الكِبْرِيَاءَ، الإِعْجَابَ بِالنَّفْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8770, 'خَيْلاَنٌ', 'خيلان', 'جامد', 'خيل', 'خيلان', 'خلن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَيْلاَنٌ-خَيْلاَنٌ [خ ي ل]. ""ظَهَرَ لَهُ خَيْلاَنُ البَحْرِ"" : وَحْشٌ مَائِيٌّ أُسْطُورِيٌّ نِصْفُهُ إِنْسَانٌ وَنِصْفُهُ سَمَكَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8771, 'مَخَايِلُ', 'مخايل', 'جامد', 'خيل', 'مخايل', 'مخل', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَخَايِلُ-مَخَايِلُ [خ ي ل]. ""مَخَايِلُ السُّحُبِ"" : السُّحُبُ الْمُنْذِرَةُ بِالْمَطَرِ. 2.""ظَهَرَتْ فِيهِ مَخَايِلُ النَّجَابَةِ"" : عَلاَمَاتُهَا، إِشَارَاتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8772, 'مُخَيِّلَةٌ', 'مخيلة', 'جامد', 'خيل', 'مخيلة', 'مخلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""لَهُ مُخَيِّلَةٌ قَوِيَّةٌ"" : القُوَّةُ الَّتِي تَسْتَحْضِرُ الأَشْيَاءَ وَتَتَخَيَّلُهَا فِي الذِّهْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8773, 'خَيْلاَنِيَّاتٌ', 'خيلانيات', 'جامد', '', 'خيلانيات', 'خلنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"خَيْلاَنِيَّاتٌ-خَيْلاَنِيَّاتٌ (حو).: رُتْبَةٌ مِنَ الحَيَوَانَاتِ الْمَائِيَّةِ البَحْرِيَّةِ، لَبُونَةٌ مِنْ أَنْوَاعِهَا الأَطُومُ وَخَرُوفُ البَحْرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8774, 'خَيْلَعٌ', 'خيلع', 'جامد', '', 'خيلع', 'خلع', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1. ""لَبِسَ خَيْلَعاً"" : قَمِيصاً لاَ كُمَّ لَهُ. 2.""أَصَابَهُ الخَيْلَعُ"" : خَوْفٌ يُصِيبُ الإِنْسَانَ بِمَا يُشْبِهُ الوَسْوَاسَ. 3.""شَاهَدَ الخَيْلَعَ وَهُوَ يَعْوِي"" : الذِّئْبَ. 4.""وَلَدٌ خَيْلَعٌ"" : خَرِعٌ، ضَعِيفٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8775, 'خَامٌ', 'خام', 'جامد', 'خيم', 'خام', 'خم', '', '', '', 'مفرد', 'DnN', '', '', '"أَخْوَامٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""جِلْدٌ خَامٌ"" : الْجِلْدُ الَّذِي لَمْ يُدْبَغْ. 2. ""بِلاَدٌ غَنِيَّةٌ بِالْمَوَادِّ الْخَامِ "" : أَي بِالْمَعَادِنِ وَكُلِّ الْمَوَادِّ فِي حَالَتِهَا الطَّبِيعِيَّةِ الأُولَى وَلَمْ تُسْتَغَلَّ بَعْدُ فِي الصِّنَاعَةِ. "" الْمَاسُ خَامٌ "" ""حَرِيرٌ خَامٌ"" ""زَيْتٌ خَامٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8776, 'أَخْوَامٌ', 'أخوام', 'جامد', '', 'ءخوام', 'خم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8777, 'خَيْمِيَّاتٌ', 'خيميات', 'جامد', 'خيم', 'خيميات', 'خمت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"خَيْمِيَّاتٌ-خَيْمِيَّاتٌ [خ ي م].: فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ مِنْ نَبَاتِهَا الكَمُّونُ وَالكُزْبُرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8778, 'مُخَيَّمٌ', 'مخيم', 'جامد', 'خيم', 'مخيم', 'مخم', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '".: الْمَوْضِعُ الَّذِي تُنْصَبُ فِيهِ الْخِيَامُ. ""الْمُخَيَّمُ الكَشْفِيُّ"" ""الْمُخَيَّمَاتُ الصَّيْفِيَّةُ لِلأَطْفَالِ وَالشَّبَابِ"" ""اِعْتَادَ عَلَى حَيَاةِ الْمُخَيَّمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8779, 'خَيْمَةٌ', 'خيمة', 'جامد', '', 'خيمة', 'خمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":خِيَمٌ:خِيَامٌ"', '', 'R', '', '', '', '', '', '', '"ج: خِيَمٌ، خِيَامٌ، خَيْمَاتٌ. ""نَصَبَ الخَيْمَةَ"" : بَيْتٌ مِنَ الكَتَّانِ أَوْ مِنَ الصُّوفِ، الخِبَاءُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8780, 'خِيَمٌ', 'خيم', 'جامد', '', 'خيم', 'خم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
