INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8782, 'دَارصِينِى', 'دارصينى', 'جامد', '', 'دارصينى', 'درصن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '"دَارصِينِى-دَارصِينِى (نب).: قِشْرُ شَجَرٍ نَحِيفٍ مِنْ فَصِيلَةِ الغَارِيَّاتِ يُشْبِهُ القِرْفَةَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8783, 'دَاغِصَةٌ', 'داغصة', 'جامد', '', 'داغصة', 'دغصة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَوَاغِصُ"', '', 'R', '', '', '', '', '', '', '"ج: دَوَاغِصُ : العَظْمُ الْمُدَوَّرُ فِي أعْلَى الرُّكْبَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8784, 'دَوَاغِصُ', 'دواغص', 'جامد', '', 'دواغص', 'دغص', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8785, 'دَالٌ', 'دال', 'جامد', '', 'دال', 'دل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أدْوَالٌ"', '', 'R', '', '', '', '', '', '', '"ج: أدْوَالٌ. . ""دَالُ النَّهْرِ"" : رَواسِبُ نَهْرِيَّةٌ عَلَى شَكْلِ حَرْفِ الدَّالِ بَيْنَ أفْرُعِ النَّهْر."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8786, 'أدْوَالٌ', 'أدوال', 'جامد', '', 'ءدوال', 'دل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8787, 'دَأْماءُ', 'دأماء', 'جامد', 'دأم', 'دءماء', 'دم', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"دَأْماءُ-دَأْماءُ [د أ م].: البَحْرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8788, 'دَامَا', 'داما', 'جامد', '', 'داما', 'دم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '"""يَلْعَبُ مَعَ صَحْبِهِ لُعْبَةَ الدَّامَا"" : لُعْبَة تَجْرِي عَلَى لَوْحَةٍ بِهَا مُرَبَّعَاتٌ بِيضٌ وَسُودٌ كَرُقْعَةِ الشِّطْرَنْجِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8789, 'دُبٌّ', 'دب', 'جامد', '', 'دب', 'دب', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"دِبَبَةٌ:أدْبَابٌ:دِبَابٌ"', '', 'R', '', '', '', '', '', '', '"ج: دِبَبَةٌ، أدْبَابٌ، دِبَابٌ (حو). 1.:حَيَوَانٌ مِنْ فَصِيلَةِ الدُّبِّيَّاتِ، لَبُونٌ مِنْ رَاحِيَّاتِ القَدَمِ، مِنَ الكَواَسِر، ضَخْمُ الجُثَّةِ، كَثِيفُ الشَّعَرِ. أنْوَاعُهُ مُخْتَلِفَةٌ، مِنْهَا الدُّبُّ الأسْمَرُ يَعِيشُ فِي أُورُوبَّا وآسيَا، وَالدُّبُّ الأسْوَدُ يَعِيشُ فِي أمْرِيكَا وَكَنَدَا، وَالدُّبُّ الأبْيَضُ يَعِيشُ فِي الْمَنَاطِقِ القُطْبِيَّةِ، وَهُوَ مُتَمَيِّزٌ بِعُنُقٍ نَحِيفٍ وَرَأْسٍ مُسَطَّحٍ. ""رَأَيْتُ الدُّبَّ يُدَاعِبُ الدُّبَّةَ"". 2.""دَعْنِي وَدُبَّتِي"" : اُتْرُكْنِي أَتَصَرَّفُ كَمَا أُرِيدُ، دَعْنِي وَشَأْنِي. 3.""الدُّبُّ الأصْغَرُ"" (فك) : مَجْمُوعَةُ نُجُومٍ عَدَدُهَا سَبعَةٌ، مِنْهَا أرْبَعَةٌ تُكَوِّنُ مُرَبَّعاً، وَثَلاَثَةٌ تُكَوِّنُ ذَنَباً لَهُ، فِي نِهَايَتِهِ، النَّجْمُ القُطْبِيُّ. 4.""الدُّبُّ الأكْبَرُ"" : مَجْمُوعَةُ نُجُومٍ عَدَدُهَا سَبْعَةٌ، تُؤَلِّفُ صُورَةً سَمَاوِيَّةً عَلَى صُورَةِ الدُّبِّ الأَصْغَرِ، لَكِنَّهَا أَكْبَرُ، تُعْرَفُ بِبَناتٍ نَعْشٍ الكُبْرَى، وَبِهَا يُهْتدَى إلَى مَعْرِفَةِ النَّجْمِ القُطْبِيٍّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8790, 'دِبَبَةٌ', 'دببة', 'جامد', '', 'دببة', 'دببة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
