INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8793, 'دُوَيْبَّةٌ', 'دويبة', 'جامد', 'دبب', 'دويبة', 'دبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"دُوَيْبَّةٌ-دُوَيْبَّةٌ [د ب ب].: تَصْغيرُ دابَّة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8794, 'دَبَّاجٌ', 'دباج', 'جامد', 'دبج', 'دباج', 'دبج', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَبَّاجٌ-دَبَّاجٌ [د ب ج].: صَانِعُ الدِّيباجِ وَبَائِعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8795, 'دَبَرَةٌ', 'دبرة', 'جامد', 'دبر', 'دبرة', 'دبرة', '', '', '', 'مفرد', 'DnN', '', '', '"دَبَرٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""أُصِيبَتِ الدَّابَّةُ بِالدَّبَرَةِ"": بِقَرْحَةٍ. 2. ""ألْحَقَ بِالعَدُوِّ دَبَرَةً"" : هَزِيمَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8796, 'دَبَرٌ', 'دبر', 'جامد', '', 'دبر', 'دبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8797, 'دِبْرَةٌ', 'دبرة', 'جامد', 'دبر', 'دبرة', 'دبرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"دِبْرَةٌ-دِبْرَةٌ [د ب ر]. 1.: مَا يُسْتَدْبَرُ، أيْ نَقِيضُ القِبْلَةِ. 2.""لَيْسَ لِهَذَا الأمْرِ قِبْلَةٌ وَلاَ دِبْرَةٌ"" : أيْ لاَ يُعْرَفُ لَهُ وجْهٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8798, 'دِبْرٌ', 'دبر', 'جامد', 'دبر', 'دبر', 'دبر', '', '', '', 'مفرد', 'DnN', '', '', '"أَدْبُرٌ:أَدْبَارٌ"', '', 'R', '', '', '', '', '', '', '". 1.: جَمَاعَةُ النَّحْلِ وَالزَّنَابِيرِ. 2.: الْمَالُ الَّذِي لاَ يُحْصَى كَثْرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8799, 'أَدْبُرٌ', 'أدبر', 'جامد', '', 'ءدبر', 'دبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8800, 'أَدْبَارٌ', 'أدبار', 'جامد', '', 'ءدبار', 'دبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8801, 'دَبُورٌ', 'دبور', 'جامد', 'دبر', 'دبور', 'دبر', '', '', '', 'مفرد', 'DnN', '', '', '"دُبُرٌ:دَبَائِرُ"', '', 'R', '', '', '', '', '', '', '".: الرِّيحُ الغَرْبِيَّةُ، يُقَابِلُهَا الصَّبَا وَهِيَ الرِّيحُ الشَّرْقِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8802, 'دُبُرٌ', 'دبر', 'جامد', '', 'دبر', 'دبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8803, 'دَبَائِرُ', 'دبائر', 'جامد', '', 'دباءر', 'دبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8804, 'دَبْرٌ', 'دبر', 'جامد', '', 'دبر', 'دبر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دُبُورٌ"', '', 'R', '', '', '', '', '', '', '"ج: دُبُورٌ. 1.: جَمَاعَةُ النَّحْلِ وَالزَّنَابِيرِ. 2.: الْمَالُ الَّذِي لاَ يُحْصَى كَثْرَةً. 3. ""دَبْرُ الشَّيْءِ"" : خَلْفُهُ. 4. ""جَعَلْتُ كَلاَمَهُ دَبْرَ أُذُنِي"" : أيْ لَمْ أَعْبَأْ بِهِ وَلَمْ ألْتَفِتْ إلَيْهِ. 5.: الجَزِيرَةُ يعْلُوهَا الْمَاءُ وَيَنْحَسِرُ عَنْهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8805, 'دُبُورٌ', 'دبور', 'جامد', '', 'دبور', 'دبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8806, 'دُبُرٌ', 'دبر', 'جامد', '', 'دبر', 'دبر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أدْبَارٌ"', '', 'R', '', '', '', '', '', '', '"ج: أدْبَارٌ. 1. ""دُبُرُ الصَّلاَةِ"" : آخِرُهَا. 2.""دُبُرُ البَيْتِ"" : زَاوِيَتُهُ، مُؤَخَّرَتُهُ. 3. ""وَلَّى دُبُرَهُ"" : وَلَّى ظَهْرَهُ. كِنَايَةً عَنِ الهَرَبِ وَالفِرَارِ وَالانْهِزَامِ. ""وَلَّى الأدْبَارَ"". 4. ""دُبُرُ الإنْسَانِ"" : حَلْقَةُ سَافِلَتِهِ، اِسْتُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8807, 'أدْبَارٌ', 'أدبار', 'جامد', '', 'ءدبار', 'دبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8808, 'دَبْرَةٌ', 'دبرة', 'جامد', '', 'دبرة', 'دبرة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَبْرٌ:دِبَارٌ"', '', 'R', '', '', '', '', '', '', '"ج: دَبْرٌ، دِبَارٌ. 1.: قِطْعَةُ أرْضٍ تُسْتَصْلَحُ لِلزِّرَاعَةِ. 2. : قَنَاةٌ بَيْنَ الْمَزَارِعِ. 3. ""جَعَلَ اللَّهُ عَلَيْهِمُ الدَّبْرَةَ"" : الهَزِيمَةَ. 4. ""جَعَلَ اللَّهُ لَهُمُ الدَّبْرَةَ"" : الظَّفَرَ وَالنُّصْرَةَ بِهَزِيمَةِ غَيْرِهِمْ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8809, 'دَبْرٌ', 'دبر', 'جامد', '', 'دبر', 'دبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8810, 'دِبَارٌ', 'دبار', 'جامد', '', 'دبار', 'دبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8811, 'دَبَّاسَةٌ', 'دباسة', 'جامد', 'دبس', 'دباسة', 'دبسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '".: أدَاةٌ مَكْتَبِيَّةٌ صَغِيرَةٌ تَرْبِطُ الأوْرَاقَ بَعْضَهَا بِبَعْضٍ بِأسْلاكٍ رَقِيقَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8812, 'دُبْسَةٌ', 'دبسة', 'جامد', 'دبس', 'دبسة', 'دبسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"دُبْسَةٌ-دُبْسَةٌ [د ب س].: حُمْرَةٌ مُشْرَبَةٌ سَواداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8813, 'دِبْسٌ', 'دبس', 'جامد', 'دبس', 'دبس', 'دبس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دِبْسٌ-دِبْسٌ [د ب س]. 1.""دِبْسُ التَّمْرِ أَوِ العِنَبِ"": عَصِيرُهُ يُضَافُ إِلَيْهِمَا سُكَّرٌ وَيُعْقَدُ بِالنَّارِ. 2.""دِبْسُ النَّحْلِ"": عَسَلُهُ. 3.: الجَمْعُ الكَثِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8814, 'دَبَشٌ', 'دبش', 'جامد', 'دبش', 'دبش', 'دبش', '', '', '', 'مفرد', 'DnN', '', '', '"أدْبَاشٌ"', '', 'R', '', '', '', '', '', '', '". ""دَبَشُ البَيْتِ"" : أثَاثُهُ، سَقَطُ مَتَاعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8815, 'أدْبَاشٌ', 'أدباش', 'جامد', '', 'ءدباش', 'دبش', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8816, 'دِبَاغَةٌ', 'دباغة', 'جامد', 'دبغ', 'دباغة', 'دبغة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"دِبَاغَةٌ-دِبَاغَةٌ [د ب غ]. 1.: مِهْنَةُ الدِّبَاغَةِ، مِهْنَةُ الدَّبَّاغِ الَّذِي يَدْبَغُ الجُلُودَ. ""يُمَارِسُ مِهْنَةَ الدِّبَاغَةِ أباً عَنْ جَدٍّ"". 2.""يَصْنَعُ بِنَفْسِهِ مَادَّةَ الدِّبَاغَةِ"" : مَا يُدْبَغُ بِهِ الجِلْدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8817, 'دِبْغٌ', 'دبغ', 'جامد', 'دبغ', 'دبغ', 'دبغ', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دِبْغٌ-دِبْغٌ [د ب غ]. ""دِبْغُ الجِلْدِ"" : مَا يُدْبَغُ بِهِ الجِلْدُ، الدِّبَاغَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8818, 'مَدْبَغَةٌ', 'مدبغة', 'جامد', 'دبغ', 'مدبغة', 'مدبغة', '', '', '', 'مفرد', 'DnN', '', '', '"مَدَابِغُ"', '', 'R', '', '', '', '', '', '', '".: الْمَوْضِعُ الَّذِي تُدْبَغُ فِيهِ الْجُلُودُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8819, 'مَدَابِغُ', 'مدابغ', 'جامد', '', 'مدابغ', 'مدبغ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8820, 'دِبْقٌ', 'دبق', 'جامد', 'دبق', 'دبق', 'دبق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دِبْقٌ-دِبْقٌ [د ب ق].: مَادَّةٌ لَزِجَةٌ تُوضَعُ عَلَى قُضْبَانٍ دِقَاقٍ يُصَادُ بِهَا الطَّيْرُ والذُّبَابُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8821, 'دَبْكَةٌ', 'دبكة', 'جامد', 'دبك', 'دبكة', 'دبكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"دَبْكَةٌ-دَبْكَةٌ [د ب ك]. ""قَدَّمَتِ الفِرْقَةُ اللُّبْنَانِيَّةُ رَقْصَةَ الدَّبْكَةِ"" : رَقْصَةٌ جَمَاعِيَّةٌ بِسُورْيَا وَلُبْنَانَ تَعْتَمِدُ عَلَى حَرَكَاتٍ إيقَاعِيَّةٍ لِلْأَرْجُلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8822, 'دَبُّورٌ', 'دبور', 'جامد', '', 'دبور', 'دبر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَبَابِيرُ"', '', 'R', '', '', '', '', '', '', '"ج: دَبَابِيرُ.: الزُّنْبُورُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8823, 'دَبَابِيرُ', 'دبابير', 'جامد', '', 'دبابير', 'دببر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8824, 'دَبُّوسٌ', 'دبوس', 'جامد', '', 'دبوس', 'دبس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَبَابِيسُ"', '', 'R', '', '', '', '', '', '', '"ج: دَبَابِيسُ. 1.: عَصاً غَلِيظَةٌ مِنْ خَشَبٍ أوْ حَدِيدٍ كُرَوِيَّةُ الرَّأْسِ. 2.: إبْرَةٌ لَهَا رَأْسٌ غَلِيظٌ تُغْرَزُ فِي الأوْرَاقِ أوِ الثِّيَابِ لِجَمْعِهَا وَشَدِّهَا. 3.: سِلْكٌ مُلْتَوٍ تُجْمَعُ بِهِ الأوْرَاقُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8825, 'دَبَابِيسُ', 'دبابيس', 'جامد', '', 'دبابيس', 'دببس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8826, 'دِثَارٌ', 'دثار', 'جامد', 'دثر', 'دثار', 'دثر', '', '', '', 'مفرد', 'DnN', '', '', '"دُثُرٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""سَحَبَ عَلَيْهِ الدِّثَارَ وَعَادَ لِيَسْتَغْرِقَ فِي نَوْمِهِ"" : غِطَاء النَّائِمِ. 2. ""اِرْتَدَى دِثَارَهُ"" : الرِّدَاء الَّذِي يُلْبَسُ فَوْقَ الشِّعَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8827, 'دُثُرٌ', 'دثر', 'جامد', '', 'دثر', 'دثر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8828, 'دَجَاجٌ', 'دجاج', 'جامد', '', 'دجاج', 'دجج', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ةٌ، دُجاجٌ، دِجاجٌ. ج: دُجُجٌ. (حو).: مِنَ الطُّيُورِ الدَّوَاجِنِ، مِنْ فَصِيلَةِ التُّدْرُجِيَّـاتِ، وَهُـوَ أنْـواعٌ مِنْها : الدَّجَاجُ الهِنْدِيُّ وَهُوَ مَا يُعْرَفُ بِدَجَاجِ الحَبَشِ، وَالدَّجَاجُ الرُّومِيُّ وَهُوَ كَبِيرُ الحَجْمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8829, 'دَجَاجِيَّاتٌ', 'دجاجيات', 'جامد', '', 'دجاجيات', 'دججت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": رُتْبَةُ الدَّجَاجِ وَالتُّدْرُجِ والطَّاوُوسِ وَالحَجَلِ وَالسُّمَانَى وَالدِّيكِ الرُّومِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8830, 'دَيْجورٌ', 'ديجور', 'جامد', 'دجر', 'ديجور', 'دجر', '', '', '', 'مفرد', 'DnN', '', '', '"دَياجيرُ"', '', 'R', '', '', '', '', '', '', '". 1.""أَدْرَكَهُ لَيْلٌ دَيْجورٌ"": مُظْلِمٌ، ظَلامُ اللَّيْلِ. 2.""النُّورُ والدَّيْجورُ"" : النُّورُ والظَّلامُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8831, 'دَياجيرُ', 'دياجير', 'جامد', '', 'دياجير', 'دجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8832, 'دُجَالَةٌ', 'دجالة', 'جامد', 'دجل', 'دجالة', 'دجلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"دُجَالَةٌ-دُجَالَةٌ [د ج ل]. ""طَلَى الشَّيْءَ بِالدُّجَالَةِ"" : بِالقِطْرانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8833, 'دَجَالٌ', 'دجال', 'جامد', 'دجل', 'دجال', 'دجل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَجَالٌ-دَجَالٌ [د ج ل]. ""أصْلَحَ الأرْضَ بِالدَّجَالِ"" : بِالزِّبْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8834, 'دُجْنَةٌ', 'دجنة', 'جامد', 'دجن', 'دجنة', 'دجنة', '', '', '', 'مفرد', 'DnN', '', '', '"دُجَنٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""فِي دُجْنَةِ اللَّيْلِ"" : فِي ظُلْمَتِهِ. ""تَحُوطُ الدُّجْنَةُ بِالقَرْيَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8835, 'دُجَنٌ', 'دجن', 'جامد', '', 'دجن', 'دجن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8836, 'دَواجِنُ', 'دواجن', 'جامد', 'دجن', 'دواجن', 'دجن', '', '', '', 'مفرد', '', '', '', '"مفردداجِنَة"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '". ""دَواجِنُ الطَّيْرِ والحَيَوانِ"": ما اعْتادَ مِنَ الطَّيْرِ الإِقامَةَ مَعَ الإِنْسانِ. ""اِتَّخَذَ الدَّواجِنَ لِيَنْتَفِعَ بِبَيْضِها وَفِراخِها"". (ابن طفيل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8837, 'داجِنَة', 'داجنة', 'جامد', '', 'داجنة', 'دجنة', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8838, 'دُجْيَةٌ', 'دجية', 'جامد', 'دجو', 'دجية', 'دجة', '', '', '', 'مفرد', 'DnN', '', '', '"دُجىً"', '', '', '', 'N', 'O', 'O', 'O', '', '". ""دُجْيَةُ اللَّيْلِ"" : دُجْنَتُهُ ظُلْمَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8839, 'دُجىً', 'دجى', 'جامد', '', 'دجى', 'دج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8840, 'دَياجِي', 'دياجي', 'جامد', 'دجو', 'دياجي', 'دج', '', 'Tk', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"دَياجٍ-دَياجٍ، الدَّياجِي [د ج و]. ""ضاعَ في الدَّياجِي"" : في الظُّلُماتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8841, 'دُجًى', 'دجى', 'جامد', 'دجي', 'دجى', 'دج', '', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', 'N', 'O', 'O', 'O', '', '"دُجىً-دُجىً [د ج ي]. ""دُجَى اللَّيْلِ"" : سَوَادُهُ، ظُلْمَتُهُ، وَيُوصَفُ بِهِ عَلَى لَفْظِهِ يُقَال : ""لَيْلَةٌ دُجىً وَلَيَالٍ دُجىً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8842, 'دَحَضٌ', 'دحض', 'جامد', 'دحض', 'دحض', 'دحض', '', '', '', 'مفرد', 'DnN', '', '', '"دِحَاضٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""مَكَانٌ دَحَضٌ"" : زَلِقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8843, 'دِحَاضٌ', 'دحاض', 'جامد', '', 'دحاض', 'دحض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8844, 'دَاخِنَةٌ', 'داخنة', 'جامد', 'دحن', 'داخنة', 'دخنة', '', '', '', 'مفرد', 'DnN', '', '', '"دَوَاخِنُ"', '', 'R', '', '', '', '', '', '', '". : كُلُّ فَتْحَةٍ أوْ أُنْبُوبٍ مِنَ الحَجْمِ الكَبِيرِ يَخْرُجُ مِنْهُ الدُّخَّانُ. ""دَاخِنَةُ الْمَنْزِلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8845, 'دَوَاخِنُ', 'دواخن', 'جامد', '', 'دواخن', 'دخن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8846, 'دُخَّان', 'دخان', 'جامد', '', 'دخان', 'دخن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ن. دُخَانٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8847, 'دُخَسٌ', 'دخس', 'جامد', '', 'دخس', 'دخس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ن : الدُّلْفِينُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8848, 'دَاخِلَةٌ', 'داخلة', 'جامد', 'دخل', 'داخلة', 'دخلة', '', '', '', 'مفرد', 'DnN', '', '', '"دَوَاخِلُ"', '', 'R', '', '', '', '', '', '', '". ""دَاخِلَةُ الإنْسَانِ"" : دَخيلَتُهُ، نِيَّتُهُ، بَاطِنُهُ، عُمْقُهُ. ""تَحَدَّثَ مِنْ دَوَاخِلِهِ لِيُعَبِّرَ عَنْ مَشَاعِرِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8849, 'دَوَاخِلُ', 'دواخل', 'جامد', '', 'دواخل', 'دخل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8850, 'دَخْلَةٌ', 'دخلة', 'جامد', 'دخل', 'دخلة', 'دخلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"دِخْلَةٌ-دِخْلَةٌ [د خ ل]. ""دِخْلَةُ الإِنْسَانِ"" : دَاخِلَتُهُ، بَاطِنُهُ. ""هُوَ حَسَنُ الدِّخْلَةِ عَفِيفُ الدِّخْلَةِ"" ""خَبِيثُ الدِّخْلَةِ"" ""دِخْلَةُ الأمْرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8851, 'دُخْلَةٌ', 'دخلة', 'جامد', 'دخل', 'دخلة', 'دخلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"دُخْلَةٌ-دُخْلَةٌ [د خ ل]. 1. ""اِنْتَظَرَ العَرِيسُ الدُّخْلَةَ"" : لَيْلَةَ الزِّفَافِ. 2. ""دُخْلَةُ البَدَنِ"" : بَاطِنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8852, 'دِخْلَةٌ', 'دخلة', 'جامد', 'دخل', 'دخلة', 'دخلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"دَخْلَةٌ-دَخْلَةٌ [د خ ل]. 1.: مَعْسَلَةُ النَّحْلِ. 2. ""دَخْلَةُ البَدَنِ"": بَاطِنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8853, 'دَخْلٌ', 'دخل', 'جامد', 'دخل', 'دخل', 'دخل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَخْلٌ-دَخْلٌ [د خ ل]. 1. ""بِهِ دَخْلٌ"" : دَاءٌ فِي أعْمَاقِ البَدَنِ. 2. ""أصَابَهُ الدَّخْلُ"" : الفَسَادُ. 3. ""بِهِ دَخْلٌ"": شَكٌّ، رِيبَةٌ. 4.""دَخْلُ الإنْسَانِ"" : دَاخِلَتُهُ، دَخيلَتُهُ. 5. ""لاَ دَخْلَ لَهُ فِي هَذَا الْمَوْضُوعِ"": لاَ شَأْنَ لَهُ بِهِ، لاَ عَلاَقَةَ لَهُ بِهِ. 6. ""لاَ يَزَالُ دَخْلُهُ ضَعِيفاً"" : مَا يَحْصُلُهُ الْمَرْءُ مِنْ مَالٍ وَعَيْشِ. 7. ""الدَّخْلُ الوَطَنِيُّ"" : مَا تَسْتَخْلِصُهُ الدَّوْلَةُ مِن مَدَاخِيلَ عَامَّةٍ خِلاَلَ سَنَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8854, 'دَخِيلَةٌ', 'دخيلة', 'جامد', 'دخل', 'دخيلة', 'دخلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"دَخِيلَةٌ-دَخِيلَةٌ [د خ ل]. ""دَخِيلَةُ الإنْسَانِ"" : بَاطِنُهُ، دَاخِلُهُ، سَرِيرَتُهُ. قَرَارَتُهُ. ""يَحْتَفِظُ بِأسْرَارٍ فِي دَخِيلَتِهِ"" ""فِي دَخِيلَةِ نَفْسِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8855, 'مَدْخَلٌ', 'مدخل', 'جامد', 'دخل', 'مدخل', 'مدخل', '', '', '', 'مفرد', 'DnN', '', '', '"مَدَاخِلُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""مَدْخَلُ الدَّارِ"": بَابُ الدُّخُولِ. 2.""مَدْخَلُ الكِتَابِ"" : مُقَدِّمَتُهُ. 3.""مَدَاخِلُ الْمُعْجَمِ"": الكَلِمَاتُ الَّتِي يَشْرَحُهَا وَيُفَسِّرُهَا. 4.""يَعْرِفُ مَدَاخِلَ عَمَلِهِ وَمَخَارِجَهُ"" : أَيْ يَعْرِفُ كُنْهَهُ وَهُوَ بَارِعٌ فِي إِنْجَازِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8856, 'مَدَاخِلُ', 'مداخل', 'جامد', '', 'مداخل', 'مدخل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8857, 'دُخَانٌ', 'دخان', 'جامد', 'دخن', 'دخان', 'دخن', '', '', '', 'مفرد', 'DnN', '', '', '"أَدْخِنَةٌ"', '', 'R', '', '', '', '', '', '', '". ""يَتَصَاعَدُ الدُّخَانُ مِنَ الحَرَائِقِ"" : مَادَّةٌ غَازِيَّةٌ نَاتِجَةٌ عَنِ الأجْسَامِ الْمُحْتَرِقَةِ تَرْتَفِعُ فِي الفَضَاءِ. ""دُخَانُ الْمَدَاخِنِ"" ""دُخَانُ الحَرَائِقِ"" ""دُخَانُ السِّيجَارَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8858, 'أَدْخِنَةٌ', 'أدخنة', 'جامد', '', 'ءدخنة', 'دخنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8859, 'دَخَنٌ', 'دخن', 'جامد', 'دخن', 'دخن', 'دخن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دَخْنٌ-دَخْنٌ(نب).: نَبَاتٌ عُشْبِيٌّ مِنْ فَصِيلَةِ النَّجِيلِيَّاتِ، أنْوَاعُهُ عَدِيدَةٌ، بَرِّيَّةٌ وَزِرَاعِيَّةٌ، حَبُّهُ صَغِيرٌ أمْلَسُ يُشْبِهُ حَبَّ السِّمْسِمِ، يُعَدُّ مِنَ النَّبَاتَاتِ الطَّيِّبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8860, 'مِدْخَنَةٌٌ', 'مدخنة', 'جامد', 'دخن', 'مدخنة', 'مدخنة', '', '', '', 'مفرد', 'DnN', '', '', '"مَدَاخِنُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَدْخَنَةُ البَيْتِ"" : مَخْرَجُ الدُّخَانِيَكُونُ فَوْقَ سَطْحِ البَيْتِ. 2.""مَدَاخِنُ الْمَعَامِلِ"" : أُنْبُوبَةٌ رَأْسِيَّةٌ تُوضَعُ لِتَصْرِيفِ الغَازَاتِ الْمُحْتَرِقَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8861, 'مَدَاخِنُ', 'مداخن', 'جامد', '', 'مداخن', 'مدخن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8862, 'دَخْنٌ', 'دخن', 'جامد', '', 'دخن', 'دخن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَخَنٌ-دَخَنٌ [د خ ن]. 1. ""اِمْتَلأَ البَيْتُ بِالدَّخَنِ"" : بِالدُّخَانِ. 2. ""أصَابَهُ الدَّخَنُ"" : الفَسَادُ. 3. ""هُدْنَةٌ عَلَى دَخَنٍ"": عَلَى فَسَادٍ بَاطِنٍ. 4. ""بِهِ دَخَنٌ"" : حِقْدٌ. ""بَيْنَهُمَا دَخَنٌ"". 5.""أظْهَرَ دَخَناً"" : حِقْداً. 6. ""فِي مَتْنِ السَّيْفِ دَخَنٌ"" : مَا يَتَرَاءى فِي مَتْنِهِ مِنْ سَوَادٍ لِشِدَّةِ الصَّفَاءِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8863, 'دَيْدَنٌ', 'ديدن', 'جامد', 'ددن', 'ديدن', 'ددن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَيْدَنٌ-دَيْدَنٌ [د د ن]. ""هَذا مِنْ دَيْدَنِهِ"" : مِنْ عادَتِهِ، مِنْ دَأْبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8864, 'دُرٌّ', 'در', 'جامد', '', 'در', 'در', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '":دُرَرٌ"', '', 'R', '', '', '', '', '', '', '"ج: دُرَرٌ، دُرَّاتٌ. 1. ""زَيَّنَتْ جِيدَهَا بِالدُّرِّ"": بِاللُّؤْلُؤِ. ""حَيَّاكَ بِاليَاقُوتِ تَحْتَ الدُّرِّ مِنْ فَوْقِ الزَّبَرْجَدِ"". 2.""الدُّرُّ فِيهِ كَامِنٌ"": الْمَكَانَةُ، القِيمَةُ، الكَنْزُ. "" فِي أَحْشَائِهَا الدُّرُّ كَامِنٌ"" : أَي فِي اللُّغَةِ العَرَبِيَّةِ. (حافظ إبراهيم)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8865, 'دُرَرٌ', 'درر', 'جامد', '', 'درر', 'در', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8866, 'دَرِيئَةٌ', 'دريئة', 'جامد', 'درأ', 'دريءة', 'درة', '', '', '', 'مفرد', 'DnN', '', '', '"دَرَايَا"', '', '', '', '', '', '', '', '', '". ""دَرِيئَةُ الصَّائِدِ"" : مَا يَسْتَتِرُ بِهِ لِيَخْتِلَ الصَّيْدَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8867, 'دَرَايَا', 'درايا', 'جامد', '', 'درايا', 'در', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8868, 'دُرَّاجٌ', 'دراج', 'جامد', '', 'دراج', 'درج', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَرَارِيجُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: دَرَارِيجُ. : طَائِرٌ مِنْ فَصِيلَةِ الدَّجَاجِيَّاتِ شَبِيهٌ بِالحَجَلِ وَأكْبَرُ مِنْهُ حَجْماً، أسْوَدُ الوَجْهِ وَالعُنُقِ وَالصَّدْرِ تَتَخَلَّلُهُ نُقَطٌ، لَوْنُهَا أبْيَضُ، قَصِيرُ المِنْقَارِ، أسْفَلَ بَطْنِهِ وَتَحْتَ ذَنَبِهِ لَوْنٌ أحْمَرُ. كَمَا يَتَخَلَّلُ ذَنَبَهُ وَظَهْرَهُ نُقَطٌ تَمِيلُ إلَى السَّوَادِ وَالبَيَاضِ، يُحِيطُ بِعُنُقِهِ طَوْقٌ كَسْتَنائِيٌّ، يُعْرَفُ بِالدُّرَّاجِ العِرَاقِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8869, 'دَرَارِيجُ', 'دراريج', 'جامد', '', 'دراريج', 'دررج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8870, 'دَرَّاعَةٌ', 'دراعة', 'جامد', '', 'دراعة', 'درعة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَرَارِيعُ"', '', 'R', '', '', '', '', '', '', '"ج: دَرَارِيعُ. ""يَلْبَسُ الدَّرَّاعَةَ فِي بَيْتِهِ"" : جُبَّةٌ وَاسِعَةٌ تَخْتَلِفُ أشْكَالُهَا حَسَبَ الْمَنَاطِقِ والبُلْدانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8871, 'دَرَارِيعُ', 'دراريع', 'جامد', '', 'دراريع', 'دررع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8872, 'دَرَّاقٌ', 'دراق', 'جامد', '', 'دراق', 'درق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دَرَّاقٌ-دَرَّاقٌ (نب).: شَجَرَةٌ مِنْ فَصِيلَةِ الوَرْدِيَّاتِ، تُعْطِي فَاكِهَةَ الدَّرَّاقِ. لَهَا لَوْنٌ وَرْدِيٌّ وَنَوَاةٌ كَبِيرَةٌ، يُحِيطُ بِهَا لُبٌّ تُغَطِّيهِ قِشْرَةٌ رَقِيقَةٌ، وَهُوَ مَا يُعْرَفُ بِالخَوْخِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8873, 'دَرَّاقَةٌ', 'دراقة', 'جامد', '', 'دراقة', 'درقة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"واحدةالدَّرَّاقِ:"', '', 'R', '', '', '', '', '', '', '": وَاحِدَة الدَّرَّاقِ، ثَمَرَةُ الدَّرَّاقِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8874, 'دُرَاقِنٌ', 'دراقن', 'جامد', '', 'دراقن', 'درقن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"ن. الدَّرَّاق."', ':لا جذر:لا مفرد');
