INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8876, 'دِرَامَا', 'دراما', 'جامد', '', 'دراما', 'درم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R0', '', 'N', 'O', 'N', 'O', '', '": حِكَايَةٌ لِجَانِبٍ مِنَ الحَيَاةِ الإنْسَانِيَّةِ يَقُومُ بِأَدَاءِ أدْوَارِهَا مُمَثِّلُونَ وَمُمَثِّلاَتٌ عَلَى الْمَسْرَحِ يُقَلِّدُونَ فِيهَا أشْخَاصاً فِي لِبَاسِهِمْ وَأقْوَالِهِمْ وَأفْعَالِهِمْ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8877, 'دَرَاهِمُ', 'دراهم', 'جامد', '', 'دراهم', 'درهم', '', '', '', 'جمع تكسير', '', '', '', '"مفرددِرْهَم"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"جمع دِرْهَم. ن. دِرْهَم."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8878, 'دِرْهَم', 'درهم', 'جامد', '', 'درهم', 'درهم', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8879, 'دَرْبٌ', 'درب', 'جامد', 'درب', 'درب', 'درب', '', '', '', 'مفرد', 'DnN', '', '', '"دُرُوبٌ:دِرَابٌ:أدْرَابٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَقَفَ أمَامَ الدَّرْبِ"" : البَابُ الكَبِيرُ. 2. :""الْمَضْيَقُ فِي الجَبَلِ"". 3.:""كُلُّ مَدْخَلٍ إلَى بِلاَدِ الرُّومِ"". 4. ""يَسْكُنُ فِي دَرْبِ كَذَا"" : الزَّنْقَةُ التي تُوجَدُ فِي مَدْخَلٍ ضَيِّقٍ بِهَا دُورٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8880, 'دُرُوبٌ', 'دروب', 'جامد', '', 'دروب', 'درب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8881, 'دِرَابٌ', 'دراب', 'جامد', '', 'دراب', 'درب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8882, 'أدْرَابٌ', 'أدراب', 'جامد', '', 'ءدراب', 'درب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8883, 'دَرْبوزٌ', 'دربوز', 'جامد', '', 'دربوز', 'دربز', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَرَابِيزُ"', '', 'R', '', '', '', '', '', '', '"ج: دَرَابِيزُ. : شُبَّاكٌ مِنْ خَشَبٍ وَنحْوِهِ عَلَى شَكْلِ قَوَائِمَ تُقَامُ حَاجِزاً فِي مُقَدِّمَةِ الغُرَفِ بِالطَّابَقِ الثَّانِي مِنَ الدُّورِ التَّقْلِيدِيَّةِ. ""يَصْهَلُ مِنْ وَرَاءِ الدَّرْبُوزِ مُوَجِّهاً الأوَامِرَ إلَى مَنْ يَتَلكَّئون أو يَتَبَاطَئُونَ"". (محمد برادة)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8884, 'دَرَابِيزُ', 'درابيز', 'جامد', '', 'درابيز', 'دربز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8885, 'أَدْرَاجٌ', 'أدراج', 'جامد', 'درج', 'ءدراج', 'درج', '', '', '', 'مفرد', 'DnN', '', '', '"دَرَجَ"', '', 'R', '', '', '', '', '', '', '". 1. ""ذَهَبَ أَدْرَاجَ الرِّيَاحِ"": ضَاعَ مَعَ الرِّيَاحِ. 2.""ذَهَبَ دَمُهُ أَدْرَاجَ الرِّيَاحِ"" : هَدَرًا، أَي لَمْ يُؤْخَذْ بِثَأْرِهِ. 3. ""رَجَعْتُ أَدْرَاجِي"" : عُدْتُ مِنَ الطَّرِيقِ الَّذِي جِئْتُ مِنْهُ، عُدْتُ مِنْ حَيْثُ أَتَيْتُ. ""وَعُدْتُ أَدْرَاجِي لأجْمَعَ ما يَكونُ قَدْ تَنَاثَرَ مِنِّي"". (م. ص. الرافعي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8886, 'دَرَجَ', 'درج', 'جامد', '', 'درج', 'درج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8887, 'دَرَّاجَةٌ', 'دراجة', 'جامد', 'درج', 'دراجة', 'درجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.: آلَةٌ مِيكَانِيكِيَّـةٌ لَهَا عَجَلَتَانِ يُرْكَبُ عَلَيْهَا، وَتُحَرَّكُ دَوَّاسَتاها بِصَفْحَتَي القَدَمَيْنِ. 2.""دَرَّاجَةٌ نَارِيَّةٌ"": لَهَا مُحَرِّكٌ يَشْتَغِلُ بِالوَقُـودِ. 3.""سِبَـاقُ الدَّرَّاجَاتِ"" : رِيَاضَةُ السِّبَاقِ عَلَى الدَّرَّاجَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8888, 'دَرَجَةٌ', 'درجة', 'جامد', 'درج', 'درجة', 'درجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":دَرَجٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""حَصَّلَ عَلَى الدَّرَجَةِ الأُولَى"" : الرُّتْبَةِ الأولَى. 2. ""فِي الدَّرَجَةِ الأولَى"" : فِي الْمَرْتَبَةِ الأولَى. ""مِنَ الدَّرَجَةِ الثَّانِيَةِ"". 3. ""بَلَغَتْ دَرَجَةُ الحَرَارَةِ 40% "" : وَصَلَتْ قُوَّةُ الحَرَارَةِ...، وَحْدَتُهَا الَّتِي تَدُلُّ عَلَى قِيَاسِ الحَرَارَةِ. 4. ""بَلَغَتِ الحَرَارَةُ دَرَجَاتِهَا العُلْيَا"" : أقْصَى مَا تَصِلُ إلَيْهِ الحَرَارَةُ، عَكْسَ دَرَجَاتِهَا السُّفْلَى، أيْ أدْنَى مَا تَصِلُ إلَيْهِ الحَرَارَةُ. 5. ""لِدَرَجَةِ أنَّ"" : بِحَيْثُ أنَّ، عَلَى نَحْوِ أنَّ... 6. ""الدَّرَجَةُ"" (هن) : جُزْء مِنْ 90 جُزْءاً مِنْ أجْزَاءٍ مُتَسَاوِيَةٍ مِنَ الزَّاوِيَةِ القَائِمَةِ. 7. ""الجَنَّةُ دَرَجَاتٌ وَالنَّارُ دَرَكَاتٌ"": مَرَاتِبُ. ""النَّاسُ دَرَجَاتٌ"". 8. ""دَرَجُ البَيْتِ"" : المِرْقَاةُ الَّتِي تَصِلُ الغُرَفَ العُلْيَا. ""يَصْعَدُ الدَّرَجَ"". 9. ""فِي دَرَجِ الكَلاَمِ"": فِي أَثْنَائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8889, 'دَرَجٌ', 'درج', 'جامد', '', 'درج', 'درج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8890, 'مَدْرَجٌ', 'مدرج', 'جامد', 'درج', 'مدرج', 'مدرج', '', '', '', 'مفرد', 'DnN', '', '', '"مَدَارِجُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَدْرَجُ الْمَطَارِ"" : مَسْلَكٌ، طَرِيقٌ فَسِيحٌ فِي أَرْضِ الْمَطَارِ تَدْرُجُ عَلَيْهِ الطَّائِرَاتُ عِنْدَ الهُبُوطِ أَوِ الإِقْلاَعِ. 2.""يَسِيرُ فِي مَدَارِجِ الرُّقِيِّ الاجْتِمَاعِيِّ"" : فِي طَرِيقِ الرُّقِيِّ... 3.""نَشَأَ عَلَى حُبِّ الخَيْرِ مُنْذُ مَدْرَجِهِ"" : مُنْذُ نَشْأَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8891, 'مَدَارِجُ', 'مدارج', 'جامد', '', 'مدارج', 'مدرج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8892, 'مُدَرَّجٌ', 'مدرج', 'جامد', 'درج', 'مدرج', 'مدرج', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""مُدَرَّجُ الكُلِّيَّةِ"" : بِنَاءٌ فَسِيحٌ نِصْفُ دَائِرِيٍّ، يَضُمُّ مَقَاعِدَ طَوِيلَةً دَائِرِيَّةً لِلطُّلاَّبِ لِسَمَاعِ مُحَاضَرَاتِ الأَسَاتِذَةِ. ""مُدَرَّجُ الْمَلْعَبِ"" ""مُدَرَّجُ الْمَسْرَحِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8893, 'دَرَجٌ', 'درج', 'جامد', '', 'درج', 'درج', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أدْرَاجٌ"', '', 'R', '', '', '', '', '', '', '"ج: أدْرَاجٌ. 1. ""ذَهَبَتْ حَيَاتُهُ أدْرَاجَ الرِّيَاحِ"" : سُدًى، هَدَراً، ضَيَاعاً. 2.""رَجَعْتُ دَرَجِي"" : رَجَعْتُ مِنَ الطَّرِيقِ الَّذِي جِئْتُ مِنْهُ. 3. ""دَرَجُ السُّيُولِ"" : طَرِيقُهَـا فِـي مَعَاطِفِ الأوْدِيَةِ. 4. ""دَرَجُ السُّلَّمِ أَوِ البَيْتِ"": مَا يُتَخَطَّى مِنَ الأدْنَى إلَى الأعْلَى فِي الصُّعُودِ"". 5.""هُوَ دَرَجُ الْمُتَنَازِعَيْنَ"" : سَفِيرٌ بَيْنَهُمَا لِلصُّلْحِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8894, 'أدْرَاجٌ', 'أدراج', 'جامد', '', 'ءدراج', 'درج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8895, 'دَرْجٌ', 'درج', 'جامد', '', 'درج', 'درج', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1. ""فَتَحَ دَرْجَهُ وَبَدَأَ يَقْرَأُ"" : لِفَافَةٌ مِنَ الوَرَقِ يُكْتَبُ عَلَيْهَا. 2. ""نَحْنُ دَرْجُ يَدَيْكَ"" : طَوْعُ يَدَيْكَ. 3.""وَضَعَ رِسَالَةً فِي دَرْجِ الكِتَابِ"" : فِي طَيِّهِ. 4. ""دَرْجُ الحَدِيثِ"" : فِي أَثْنَائِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8896, 'دُرْجٌ', 'درج', 'جامد', '', 'درج', 'درج', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أدْرَاجٌ:دِرَجَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: أدْرَاجٌ، دِرَجَةٌ. 1. ""أخْرَجَتْ عِطْرَهَا مِنَ الدُّرْجِ"" : وِعَاءٌ صَغِيرٌ تَضَعُ فِيهِ الْمَرْأةُ أغْرَاضَهَا وَطِيبَهَا. 2.""خَبَّأ وَثِيقَةً فِي دُرْجِ مَكْتَبِهِ"" : صُنْدُوقٌ صَغِيرٌ يُسْحَبُ وَيُدْخَلُ مِنْ فُتْحَةِ الْمَكْتَبِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8897, 'أدْرَاجٌ', 'أدراج', 'جامد', '', 'ءدراج', 'درج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8898, 'دِرَجَةٌ', 'درجة', 'جامد', '', 'درجة', 'درجة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8899, 'دَرْدَارٌ', 'دردار', 'جامد', '', 'دردار', 'دردر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دَرْدَارٌ-دَرْدَارٌ (نب).: شَجَرٌ ضَخْمٌ مِنْ فَصِيلَةِ الزَّيْتُونِيَّاتِ، لَهُ زَهْرٌ أصْغَرُ‎، وَوَرَقٌ شَائِكٌ، ثَمَرُهُ كَقُرُونِ الدِّفْلَى، خَشَبُهُ أَبْيَضُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8900, 'دُرْدُرٌ', 'دردر', 'جامد', 'دردر', 'دردر', 'دردر', '', '', '', 'مفرد', 'DnN', '', '', '"درادِرُ"', '', 'R', '', '', '', '', '', '', '". ""لاكَ التَّمْرَ بِدَرادِرِهِ"" : بِمَغَارِزِ أسْنَانِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8901, 'درادِرُ', 'درادر', 'جامد', '', 'درادر', 'دردر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8902, 'دُرْدُورٌ', 'دردور', 'جامد', '', 'دردور', 'دردر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": مَوْضِعٌ فِي البَحْرِ يُشْبِهُ الحَلَزُونَ، دَوَّامَةٌ بإمْكَانِهَا أَنْ تَمْتَصَّ السَّابِحَ إذَا اقْتَرَبَ مِنْهَا. ""تُمْنَعُ السِّبَاحَةُ فِي الدُّردُورِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8903, 'دُرْدِيٌّ', 'دردي', 'جامد', '', 'دردي', 'درد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '": مَا يَرْسُبُ مِنْ حُثَالَةِ الزَّيْتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8904, 'دُرَّةٌ', 'درة', 'جامد', 'درر', 'درة', 'درة', '', '', '', 'مفرد', 'DnN', '', '', '"واحدةالدُّرِّ"', '', 'R', '', '', '', '', '', '', '"دُرَّةُ-دُرَّةُ [د ر ر].: وَاحِدَةُ الدُّرِّ، اللُّؤْلُؤَةُ. ن. دُرٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8905, 'دِرَّةٌ', 'درة', 'جامد', 'درر', 'درة', 'درة', '', '', '', 'مفرد', 'DnN', '', '', '"دِرَرٌ"', '', 'R', '', '', '', '', '', '', '". 1.: اللَّبَنُ أوْ كَثْرَةُ اللَّبَنِ. 2.""لِلسَّحَاب دِرّةٌ"" : صَبٌّ. 3. ""لِساقِ الرَّاكِبِ دِرَّةٌ"" : اِسْتِدْرَارٌ لِجَرْيِ الدَّابَّةِ. 4. ""لِلسُّوقِ دِرَّةٌ"" : رَواجٌ. 5. ""مَرَّ عَلَى دِرَّتِهِ"" : مَرَّ لا يَثْنِيهِ شَيْءٌ. 6. ""دِرَّةُ عُمَرَ بْنِ الخَطَّابِ"" : سَوْطُهُ الَّذِي يَضْرِبُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8906, 'دِرَرٌ', 'درر', 'جامد', '', 'درر', 'در', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8907, 'دَرورٌ', 'درور', 'جامد', 'درر', 'درور', 'درر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَرورٌ-دَرورٌ [د ر ر]. ""نَاقَةٌ دَرورٌ"" : كَثِيرَةُ الدَّرِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8908, 'دَرْزِيٌّ', 'درزي', 'جامد', 'درز', 'درزي', 'درز', '', '', '', 'مفرد', 'DnN', '', '', '"دَرَزَةٌ"', '', '', '', '', '', '', '', '', '". : الخَيَّاطُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8909, 'دَرَزَةٌ', 'درزة', 'جامد', '', 'درزة', 'درزة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8910, 'دُروزٌ', 'دروز', 'جامد', 'درز', 'دروز', 'درز', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دُروزٌ-دُروزٌ [د ر ز]. : طَائِفَةٌ مِنَ الإِسْمَاعِيلِيَّةِ يُنْسَبُونَ إلَى أبِي مُحَمَّد بْنِ عَبْدِ اللَّهِ الدُّرْزِيّ، لَهُمْ مَذْهَبٌ دِينِيٌّ وَفَلْسَفِيٌّ، كَانُوا يُعْرَفُونَ بِالْمُوَحِّدِينَ، يُؤْمِنُونَ بِالتَّقَمُّصِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8911, 'دَرَّاسَةٌ', 'دراسة', 'جامد', 'درس', 'دراسة', 'درسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""يَسْتَخْدِمُ الفَلاَّحُ دَرَّاسَةً عَصْرِيَّةً لِدَرْسِ قَمْحِهِ"" : آلَةً لَهَا مُحَرِّكٌ تَشْتَغِلُ بِالوَقُودِ تَدْرُسُ قَمْحَ السَّنَابِلِ. ""جَاءَ أبْنَاءُ القَرْيَةِ يُشَاهِدُونَ عَمَلَ الدَّرَّاسَاتِ فِي البَيْدَرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8912, 'دِرَاسَةٌ', 'دراسة', 'جامد', 'درس', 'دراسة', 'درسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""بَدَأَتِ الدِّرَاسَةُ فِي الْمَدَارِسِ"" : الأعْمَالُ الْمَدْرَسِيَّةُ، أَي القِرَاءةُ وَتَحْصِيلُ العُلُومِ وَالْمَعَارِفِ. 2. ""قَدَّمَ دِرَاسَةً مُهِمَّةً"" : بَحْثاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8913, 'دِرْسٌ', 'درس', 'جامد', 'درس', 'درس', 'درس', '', '', '', 'مفرد', 'DnN', '', '', '"أدْرَاسٌ:دِرْسَانٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""كَانَ يَرْتَدِي دِرْساً"" : ثَوْباً بَالِياً. 2. ""دِرْسُ البَعِيرِ"" : ذَنَبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8914, 'أدْرَاسٌ', 'أدراس', 'جامد', '', 'ءدراس', 'درس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8915, 'دِرْسَانٌ', 'درسان', 'جامد', '', 'درسان', 'درسن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8916, 'مَدْرَسَةٌ', 'مدرسة', 'جامد', 'درس', 'مدرسة', 'مدرسة', '', '', '', 'مفرد', 'DnN', '', '', '"مَدَارِسُ"', '', 'R', '', '', '', '', '', '', '". 1.""يَتَعَلَّمُ فِي الْمَدْرَسَةِ"": مُؤَسَّسَةٌ تَعْلِيمِيَّةٌ يَتَعَلَّمُ فِيهَا التَّلاَمِيذُ وَالطَّلَبَةُ. 2.""فَنَّانٌ مِنَ الْمَدْرَسَةِ الانْطِبَاعِيَّةِ"" : مِنْ تَيَّارٍ، مِنِ اتِّجَاهٍ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8917, 'مَدَارِسُ', 'مدارس', 'جامد', '', 'مدارس', 'مدرس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8918, 'دَارِعَةٌ', 'دارعة', 'جامد', 'درع', 'دارعة', 'درعة', '', '', '', 'مفرد', 'DnN', '', '', '"دَوَارِعُ"', '', 'R', '', '', '', '', '', '', '". : البَاخِرَةُ الحَرْبِيَّةُ الْمُجَهَّزَةُ بِالآلاتِ الْمُدَرَّعَةِ بِالفُولاَذِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8919, 'دَوَارِعُ', 'دوارع', 'جامد', '', 'دوارع', 'درع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8920, 'دَرْعَاءُ', 'درعاء', 'جامد', 'درع', 'درعاء', 'درع', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"دَرْعَاءُ-دَرْعَاءُ [د ر ع]. 1. ""نَعْجَةٌ دَرْعَاءُ"" : نَعْجَةٌ اِبْيَضَّ صَدْرُهَا وَنَحْرُهَا واسْوَدَّ فَخِذُهَا. 2. ""لَيْلَةٌ دَرْعَاءُ"" : لَيْلَةٌ يَطْلُعُ قَمَرُهَا عِنْدَ الصُّبْحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8921, 'مُدَرَّعَةٌ', 'مدرعة', 'جامد', 'درع', 'مدرعة', 'مدرعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""السَّفِينَةُ الْحَرْبِيَّةُ الْمُصَفَّحَةُ بِالفُولاَذِ. 2.""سَيَّارَةٌ مُدَرَّعَةٌ"" : سَيَّارَةٌ مُصَفَّحَةٌ بِالفُولاَذِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8922, 'دَرَقَةٌ', 'درقة', 'جامد', 'درق', 'درقة', 'درقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"دَرَقَةٌ-دَرَقَةٌ [د ر ق]. 1.: التُّرْسُ مِنْ جِلْدٍ لَيْسَ فِيهِ خَشَبٌ وَلاَ عَقَبٌ. 2.: صَفِيحَةٌ قَرْنِيَّةٌ أو عَظْمِيَّةٌ تَتَكَوَّنُ فِي جِلْدِ كَثِيرٍ مِنَ الحَيَوَانَاتِ مِثْلِ دَرَقاتِ السَّلاحِفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8923, 'دَركَةٌ', 'دركة', 'جامد', 'درك', 'دركة', 'دركة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":دَرَكٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""الجَنَّةُ دَرَجَاتٌ وَالنَّارُ دَرَكَاتٌ"" : أَسْفَلُ دَرَجَاتِ النَّارِ. ""الدَّرَكَاتُ السُّفْلَى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8924, 'دَرَكٌ', 'درك', 'جامد', '', 'درك', 'درك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8925, 'دَرِيكَةٌ', 'دريكة', 'جامد', 'درك', 'دريكة', 'دركة', '', '', '', 'مفرد', 'DnN', '', '', '"دَرَائِكُ"', '', '', '', '', '', '', '', '', '". ""لاَحَقَ الدَّرِيكَةَ"" : الطَّرِيدَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8926, 'دَرَائِكُ', 'درائك', 'جامد', '', 'دراءك', 'درك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8927, 'مُتَدَارَكٌ', 'متدارك', 'جامد', 'درك', 'متدارك', 'متدرك', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مُتَدَارَكٌ-مُتَدَارَكٌ [د ر ك].: بَحْرٌ مِنْ بُحُورِ الشِّعْرِ العَرَبِيِّ وَزْنُهُ: فَاعِلُنْ فَاعِلُنْ فَاعِلُنْ فَاعِلُنْ*فَاعِلُنْ فَاعِلُنْ فَاعِلُنْ فَاعِلُنْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8928, 'مَدَارِكُ', 'مدارك', 'جامد', 'درك', 'مدارك', 'مدرك', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"مَدَارِكُ-مَدَارِكُ [د ر ك]. 1.""الْمَدَارِكُ الخَمْسَةُ"" : الْحَوَاسُّ الخَمْسُ. 2.""عَلَى قَدْرِ مَدَارِكِهِ العَقْلِيَّةِ"" : مَلَكَاتُهُ، قُوَاهُ، قُدُرَاتُهُ الحِسِّيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8929, 'مُدْرَكَاتٌ', 'مدركات', 'جامد', 'درك', 'مدركات', 'مدركت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُدْرَكَاتٌ-مُدْرَكَاتٌ [د ر ك]. ""مُدْرَكَاتُ الإِنْسَانِ"" : حَوَاسُّهُ الخَمْسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8930, 'دَارِمٌ', 'دارم', 'جامد', 'درم', 'دارم', 'درم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دَارِمٌ-دَارِمٌ [د ر م]. : شَجَرٌ شَبِيهٌ بِالغَضَى تَسْتَاكُ النِّسَاءُ بِهِ فَيُحَمِّرُ شِفَاهَهُنَّ تَحْمِيراً شَدِيداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8931, 'دَرْمَاءُ', 'درماء', 'جامد', 'درم', 'درماء', 'درم', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', 'N', 'O', 'O', 'O', '', '"دَرْمَاءُ-دَرْمَاءُ [د ر م]. 1.: نَبَاتٌ أحْمَرُ الوَرَقِ، لَيْسَ بِشَجَرٍ وَلاَ عُشْبٍ عَلَى هَيْئَةِ الكَبِدِ، وَهُوَ مِنَ الحَمْضِ. 2. ""اِمْرَأةٌ دَرْمَاءُ"" : لاَ تَسْتَبِينُ كُعوبَهَا وَمرَافِقَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8932, 'دَرَنٌ', 'درن', 'جامد', 'درن', 'درن', 'درن', '', '', '', 'مفرد', 'DnN', '', '', '"أدْرَانٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""تَلَطَّخَ بِأدْرَانِ الحَظِيرَةِ"": بِأَوْسَاخِهَا. ""دَخَلَ الحَمَّامَ لِيَتَخَلًّصَ مِنْ أَدْرَانِ السَّفَرِ وَأَتْعابِ الطَّريقِ"".(أحمد التوفيق). 2. ""أُصِيبَ بِدَرَنٍ رِئَوِيٍّ"" : بِالسُّلِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8933, 'أدْرَانٌ', 'أدران', 'جامد', '', 'ءدران', 'درن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8934, 'دِرْهَمٌ', 'درهم', 'جامد', '', 'درهم', 'درهم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَرَاهِمُ"', '', 'R', '', '', '', '', '', '', '"ج: دَرَاهِمُ. : قِطْعَةٌ نَقْدِيَّةٌ مَعْدِنِيَّةٌ وَهِيَ أسَاسُ العُمْلَةِ الْمَغْرِبِيَّةِ الآنَ، مِقْدَارُهَا مِائَةُ سَنْتِيم، كَانَتْ قَدِيماً تُضْرَبُ مِنَ الفِضَّةِ. ""دِرْهَمُ وِقَايَةٍ خَيْرٌ مِنْ قِنْطَارِ دَوَاءٍ"". (مثل)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8935, 'دَرَاهِمُ', 'دراهم', 'جامد', '', 'دراهم', 'درهم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8936, 'دِرْواسٌ', 'درواس', 'جامد', '', 'درواس', 'درس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1.: كَلْبُ الحِرَاسَةِ، سَمِينٌ، لَهُ خَطْمٌ مُفَلْطَحٌ. 2.: الشُّجَاعُ. 3.: الأسَدُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8937, 'دَرْوِيشٌ', 'درويش', 'جامد', 'دروش', 'درويش', 'درش', '', '', '', 'مفرد', 'DnN', '', '', '"دَرَاوِيشُ"', '', 'R', '', '', '', '', '', '', '". 1. ""كَانَ دَرْوِيشاً فِي عَيْشِهِ"" : فَقِيراً. ""أنَا رَجلٌ دَرْوِيشٌ وَلاَ أفْهَمُ كُلَّ هَذِهِ التَّعْقِيدَاتِ"". (غسان كنفاني). 2.: تُطْلَقُ كَلِمَةُ دَرْوِيش عَلَى الرَّاهِبِ وَالزَّاهِدِ. 3.: اِسْمُ عَلَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8938, 'دَرَاوِيشُ', 'دراويش', 'جامد', '', 'دراويش', 'درش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8939, 'دِسَارٌ', 'دسار', 'جامد', '', 'دسار', 'دسر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دُسُرٌ"', '', 'R', '', '', '', '', '', '', '"ج: دُسُرٌ.1. ""دَقَّ الدِّسارَ"" : المِسْمَارَ.2.""دِسَارُ السَّفِينَةِ"" : حَبْلٌ مِنْ لِيفٍ تُشَدُّ بِهِ السَّفِينَةُ.القمر آية 13 وَحَمَلْنَاهُ عَلَى ذَاتِ أَلْوَاحٍ وَدُسُر ِ (قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8940, 'دُسُرٌ', 'دسر', 'جامد', '', 'دسر', 'دسر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8941, 'دَسْتٌ', 'دست', 'جامد', '', 'دست', 'دست', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دُسُوتٌ"', '', 'R', '', '', '', '', '', '', '"ج: دُسُوتٌ. 1. ""دَسْتُ الْمَجْلِسِ"" : صَدْرُهُ. 2.""دَسْتُ الوِزَارَةِ أوِ الحُكْمِ"" : الكُرْسِيُّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8942, 'دُسُوتٌ', 'دسوت', 'جامد', '', 'دسوت', 'دست', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8943, 'دُسْتُورٌ', 'دستور', 'جامد', '', 'دستور', 'دستر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَسَاتِيرُ"', '', 'Rp', '', '', '', '', '', '', '"ج: دَسَاتِيرُ. ""أقَرَّ الشَّعْبُ دُسْتُورَ البِلاَدِ"" : أيْ قَانُونَهَا العَامَّ الَّذِي يَحْكُمُ سُلُطَاتِ البِلاَدِ وَنِظَامَ الحُكْمِ فِيهَا وَقَوَاعِدَهَا الأسَاسِيَّةَ وَتَنْظِيمَ تَشْرِيعَاتِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8944, 'دَسَاتِيرُ', 'دساتير', 'جامد', '', 'دساتير', 'دستر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8945, 'دِسَامٌ', 'دسام', 'جامد', 'دسم', 'دسام', 'دسم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دِسَامٌ-دِسَامٌ [د س م]. ""دِسَامُ القِنِّينَةِ"" : مَا يُسَدُّ بِهِ رَأْسُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8946, 'دَسَمٌ', 'دسم', 'جامد', 'دسم', 'دسم', 'دسم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَسَمٌ-دَسَمٌ [د س م]. 1. ""أكْثَرَ الدَّسَمَ فِي الطَّعَامِ"" : دُهْن اللَّحْمِ وَالشَّحْمِ. 2. ""لَطَخَ ثِيَابَهُ بِالدَّسَمِ"" : الوَسَخِ، القَذَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8947, 'دَسيعَةٌ', 'دسيعة', 'جامد', '', 'دسيعة', 'دسعة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَسَائِعُ"', '', '', '', '', '', '', '', '', '"ج: دَسَائِعُ. 1.: طَنْجَرةٌ، جَفْنَةٌ كَبِيرةٌ. 2.""أعطاهُ دَسِيعَةً"" : عَطِيَّةً جَزِيلَةً. 3. ""دَسِيعَةُ الرّجُلِ"" : طَبِيعَتُهُ، خُلقُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8948, 'دَسَائِعُ', 'دسائع', 'جامد', '', 'دساءع', 'دسع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8949, 'دُشٌّ', 'دش', 'جامد', 'دشش', 'دش', 'دش', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دُشٌّ-دُشٌّ [د ش ش]. ""صَبَّ عَلَيْهِ مَاءَ الدُّشِّ"" : أدَاةٌ مِنْ مَعْدِنٍ وَنَحْوِهِ يَنْصَبُّ مِنْهَا الْمَاءُ عَلَى الْمُسْتَحِمِّ، المِشَنُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8950, 'دَشِيشَةٌ', 'دشيشة', 'جامد', 'دشش', 'دشيشة', 'دششة', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَشِيشَةٌ-دَشِيشَةٌ [د ش ش].: طَعَامٌ كالحَسَاءِ ثَخِينٌ يُتَّخَذُ مِنَ الدَّشِيشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8951, 'دَشِيشٌ', 'دشيش', 'جامد', 'دشش', 'دشيش', 'دشش', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَشِيشٌ-دَشِيشٌ [د ش ش].: حَبُّ البُرِّ يُطْحَنُ طَحْناً غَلِيظاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8952, 'تَدْشِينٌ', 'تدشين', 'جامد', 'دشن', 'تدشين', 'تدشن', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدْشِينٌ-تَدْشِينٌ [د ش ن]. 1.""قَامَ الوَزِيرُ بِتَدْشيِنِ السَّدِّ"" : اِحْتِفَالٌ يُعْلَنُ فِيهِ عَنْ بَدْءِ العَمَلِ لإِنْجَازِ مَشْرُوعٍ مَّا. 2.""تَدْشِينُ أَدَوَاتِ الْمَعْمَلِ وَآلاَتِهِ"" : اِسْتِعْمَالُهَا لأَوَّلِ مَرَّةٍ. 3.""تَدْشِينُ الكَنِيسَةِ"" : الصَّلاَةُ فِيهَا وَمُبَارَكَتُهَا قَبْلَ أَنْ يُصَلِّيَ فِيهَا أَحَدٌ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8953, 'دُعَابَةٌ', 'دعابة', 'جامد', 'دعب', 'دعابة', 'دعبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"دُعَابَةٌ-دُعَابَةٌ [د ع ب].1. : اللَّعِبُ وَالْمُمَازَحَةُ، الْمُدَاعَبَةُ. 2.: الحُمْقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8954, 'دِعْبَلٌ', 'دعبل', 'جامد', '', 'دعبل', 'دعبل', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"1.: بَيْضُ الضِّفْدَعِ. 2.: النَّاقَةُ القَوِيَّةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8955, 'دُعْسُوقَةٌ', 'دعسوقة', 'جامد', '', 'دعسوقة', 'دعسقة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: ـات، دعاسِيقُ (حش).: حَشَرَةٌ مُجَنَّحَةٌ مِنَ الدَّعْسُوقِيَّاتِ تُشْبِهُ الخُنْفُسَاءَ، لَوْنُهَا أحْمَرُ مَرْجَانِيٌّ، يَحْمِلُ كُلُّ غِمْدٍ مِنْ أجْنِحَتِهَا سِتَّ نُقَطٍ سُودٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8956, 'دُعْسُوقِيَّاتٌ', 'دعسوقيات', 'جامد', '', 'دعسوقيات', 'دعسقت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةُ حَشَرَاتٍ مِنْ غِمْدِيَّاتِ الأجْنِحَةِ مُتَعَدِّدَةُ الأنْوَاعِ وَالأجْنَاسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8957, 'دَعْصٌ', 'دعص', 'جامد', 'دعص', 'دعص', 'دعص', '', '', '', 'مفرد', 'DnN', '', '', '"دِعَصَةٌ:أدْعَاصٌ"', '', 'R', '', '', '', '', '', '', '": قِطْعَةٌ أوْ تَلٌّ مِن الرَّمْلِ مُجْتَمِعٌ وَمُسْتَدِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8958, 'دِعَصَةٌ', 'دعصة', 'جامد', '', 'دعصة', 'دعصة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8959, 'أدْعَاصٌ', 'أدعاص', 'جامد', '', 'ءدعاص', 'دعص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8960, 'دُعَاعٌ', 'دعاع', 'جامد', 'دعع', 'دعاع', 'دعع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دُعَاعٌ-دُعَاعٌ [د ع ع]. 1. : نَمْلٌ أسْوَدُ مُجَنَّحٌ. 2.: نَخْلٌ مُتَفَرِّقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8961, 'دِعَاعٌ', 'دعاع', 'جامد', 'دعع', 'دعاع', 'دعع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دِعَاعٌ-دِعَاعٌ [د ع ع].: عِيالُ الرَّجُلِ الصِّغَارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8962, 'دِعَامَةٌ', 'دعامة', 'جامد', 'دعم', 'دعامة', 'دعمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":دَعَائِمُ"', '', 'R', '', '', '', '', '', '', '". 1. ""دِعَامَةُ البَيْتِ"" : رُكْنُهُ، مَا يُدَعَّمُ بِهِ، كُلُّ خَشَبَةٍ يُدَعَّمُ بِها الشَّيْءُ لِيَثْبُتَ. 2.""هُوَ دِعَامَتُهُ"" : سَنَدُهُ. 3. ""هَذَا مِنْ دَعَائِمِ سِيَادَتِهِ"" : مِمَّا يُوَحِّدُهَا. 4. ""هُوَ دِعَامَةُ قَوْمِهِ"" : سَيِّدُهُمْ، سَنَدُهُمْ، رَئِيسُهُمْ، زَعِيمُهُمْ. 5. ""هَذَا مِن دَعَائِمِ الأُمُورِ"" : مِمَّا تَتَماسَكُ بِهِ الأُمُورُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8963, 'دَعَائِمُ', 'دعائم', 'جامد', '', 'دعاءم', 'دعم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8964, 'دِعَامَةٌ', 'دعامة', 'جامد', 'دعم', 'دعامة', 'دعمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', 'مثنى', '', 'R', '', '', '', '', '', '', '"دِعَامَتَانِ-الدِّعَامَتَانِ [د ع م].: خَشَبتَا البَكَرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8965, 'دِعَامٌ', 'دعام', 'جامد', 'دعم', 'دعام', 'دعم', '', '', '', 'مفرد', 'DnN', '', '', '"دُعُمٌ"', '', 'R', '', '', '', '', '', '', '". ""دِعَامُ البَيْتِ مُتَمَاسِكٌ"" : عِمَادُهُ، دِعَامَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8966, 'دُعُمٌ', 'دعم', 'جامد', '', 'دعم', 'دعم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8967, 'دِعَايَةٌ', 'دعاية', 'جامد', 'دعو', 'دعاية', 'دعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1. ""قَامُوا بِالدِّعَايَةِ لِلْبَضَائِعِ الجَدِيدَةِ"" : الإشْهَارُ لَهَا وَالتَّعْرِيفُ بِهَا. أ. ""قَامَ بِدِعَايَةٍ مُضَادَّةٍ لِأفْكَارِهِ"" : بِحَمْلَةٍ مُعَادِيَةٍ خَطَابَةً أوْ كِتَابَةً مُضَادَّةٍ لأفْكَارِهِ. ب. نَظَّمُوا دِعَايَةً وَاسِعَةً لِلْمُرَشَّحِ"" : نَظَّمُوا حَمْلَةً بِالخَطَابَةِ أوِ الإعْلانِ أوِ الكِتَابَةِ فِيهَا تَفْسِيرٌ وَتَعْرِيفٌ بِالْمُرَشَّحِ. 2. ""أدْعُوكَ بِدِعَايَةِ الإِسْلاَمِ"" (مِن كِتَابِ الرَّسُولِ إلى هرقل) : دَعْوَة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8968, 'دَواعِي', 'دواعي', 'جامد', 'دعو', 'دواعي', 'دع', '', 'Tk', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"دَواعٍ-دَواعٍ، الدَّواعِي [د ع و]. 1.""أَلَمَّتْ بِهِ دَواعِي الدَّهْرِ"": حَوادِثُهُ، صُروفُهُ. 2.""أَفْرَغَ دَواعِيَ صَدْرِهِ"" : هُمومَهُ وَأَحْزانَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8969, 'مَدْعَاةٌ', 'مدعاة', 'جامد', 'دعو', 'مدعاة', 'مدعة', '', '', '', 'مفرد', 'DnN', '', '', '"مدعيات"', '', '', '', '', '', '', '', '', '"مَدْعَاةٌ-مَدْعَاةٌ [د ع و]. 1.""وَجَّهَ إِلَيْهِ مَدْعَاةً"" : الدَّعْوَةُ إِلَى الطَّعَامِ. 2.""كَانَ نَجَاحُهُ مَدْعَاةً لِلْفَرَحِ"" : سَبَباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8970, 'مدعيات', 'مدعيات', 'جامد', '', 'مدعيات', 'مدعت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8971, 'دَغَلٌ', 'دغل', 'جامد', 'دغل', 'دغل', 'دغل', '', '', '', 'مفرد', 'DnN', '', '', '"أدْغَالٌ:دِغَالٌ"', '', 'R', '', '', '', '', '', '', '". ""كَانَ يُخِيفُهُ دَغَلُ الغَابَةِ"" : الشَّجَرُ الكَثِيرُ الْمُلْتَفُّ. ""ضَاعَ فِي أدْغَالِ إفْرِيقِيَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8972, 'أدْغَالٌ', 'أدغال', 'جامد', '', 'ءدغال', 'دغل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8973, 'دِغَالٌ', 'دغال', 'جامد', '', 'دغال', 'دغل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8974, 'دُفٌّ', 'دف', 'جامد', '', 'دف', 'دف', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دُفُوفٌ"', '', 'R', '', '', '', '', '', '', '"ج: دُفُوفٌ (مو).: آلَةٌ مُوسِيقِيَّةٌ هِيَ عِبَارَةٌ عَنْ إطَارٍ خَشَبِيٍّ مُدَوَّرٍ تُشَدُّ عَلَيْهِ قِطْعَةٌ مِنَ الجِلْدِ. ""كَانَ صَدى الدُّفُوفِ يَنْبَعِثُ مِن دَارِ العُرْسِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8975, 'دُفُوفٌ', 'دفوف', 'جامد', '', 'دفوف', 'دفف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8976, 'دِفْءٌ', 'دفء', 'جامد', 'دفأ', 'دفء', 'دف', '', '', '', 'مفرد', 'Dz', '', '', '"أدْفَاءٌ"', '', 'Rz', '', '', '', '', '', '', '". 1.""يَشْعُرُ بِدِفْءٍ تَحْتَ الغِطَاءِ"" : بِحَرَارَةٍ دَافِئَةٍ. 2.""فِي البَيْتِ دِفْءٌ"" : مَا يُدْفِئُ. النحل آية 5 وَالأنْعَامَ خَلَقَهَا لَكُمْ فِيهَا دِفْءٌ وَمَنَافِعُ وَمِنْهَا تَأْكُلُونَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8977, 'أدْفَاءٌ', 'أدفاء', 'جامد', '', 'ءدفاء', 'دف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8978, 'دَفِيئَةٌ', 'دفيئة', 'جامد', 'دفأ', 'دفيءة', 'دفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دَفِيئَةٌ-دَفِيئَةٌ [د ف أ]. : بِنَاءٌ وِقَائِيٌّ مُقَبَّبٌ مِنَ الزُّجَاجِ أوِ الْمَوَادِّ الْمَطَّاطِيَّةِ تُسْتَنْبَتُ بِدَاخِلِهِ نَبَاتَاتٌ لاَ تَحْتَمِلُ الحَرَارَةَ فِي البِلاَدِ الحَارَّةِ أوْ تِلْكَ الَّتِي لاَ تَحْتَمِلُ البُرُودَةَ فِي البِلاَدِ البَارِدَةِ. ""دَفِيئَةُ الْمَوْزِ"" ""كُنَّا نُشَاهِدُ دَفِيئَةً فِي كُلِّ حَقْلٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8979, 'مَدْفَأَةٌ', 'مدفأة', 'جامد', 'دفأ', 'مدفءة', 'مدفة', '', '', '', 'مفرد', 'DnN', '', '', '"مَدَافِئُ"', '', '', '', '', '', '', '', '', '". 1.""أَرْضٌ مَدْفَأَةٌ"" : كَثِيرَةُ الدِّفْءِ. 2.""مَدْفَأَةٌ زِرَاعِيَّةٌ"" : مُرَكَّبٌ زُجَاجِيٌّ شِبْهُ مُكَيَّفٍ تُسْتَنْبَتُ فِيهِ النَّبَاتَاتٌ الَّتِي لاَ تَحْتَمِلُ البَرْدَ شِتَاءً، أَوِالحَرَّ صَيْفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8980, 'مَدَافِئُ', 'مدافئ', 'جامد', '', 'مدافء', 'مدف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8981, 'مِدْفَأَةٌ', 'مدفأة', 'جامد', 'دفأ', 'مدفءة', 'مدفة', '', '', '', 'مفرد', 'DnN', '', '', '"مَدَافِئُ"', '', '', '', '', '', '', '', '', '". ""جَلَسَ قُرْبَ المِدْفَأَةِ"" : آلَةٌ لِتَدْفِئَةِ الْمَنْزِلِ، أَوْ نَارُ الْمَوْقِدِ الخَاصِّ بِالتَّدْفِئَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8982, 'مَدَافِئُ', 'مدافئ', 'جامد', '', 'مدافء', 'مدف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8983, 'دَفْتَرٌ', 'دفتر', 'جامد', '', 'دفتر', 'دفتر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَفَاتِرُ"', '', 'R', '', '', '', '', '', '', '"ج: دَفَاتِرُ. ""يَكْتُبُ عَلَى الدَّفْتَرِ"" : مَجْمُوعُ أَوْرَاقٍ مَضْمُومَةٍ تُكْتَبُ فِيهِ النُّصُوصُ وَالتَّمَارِينُ، الكُرَّاسَةُ. ""عَلَـى التِّلْمِيذِ أنْ يُصَاحِبَهُ دَائِماً قَلَمٌ وَدَفْتَرٌ لِيَكْتُبَ كُلَّ فَائِدَةٍ يَسْمَعُهَا"". (الغزالي). 2.""دَفْتَرُ مُذَكِّرَاتٍ"" : مَا يُسَجَّلُ فِيهِ مِنْ مُلاَحَظَاتٍ وأفْكَارٍ، مُذَكِّرَةٌ. 3.""أخْرَجَ دَفْتَرَ شِيكَاتِهِ وَسَلَّمَنِي شِيكاً"" : مَجْمُوعُ أوْرَاقِ الشِّيكَاتِ. 4.""مَسْكُ الدَّفَاتِرِ"" : أمْرُ الْمُحَاسَبَةِ فِي مُؤَسَّسَةٍ أوْ مَصْرِفٍ وَالقِيَامُ بِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8984, 'دَفَاتِرُ', 'دفاتر', 'جامد', '', 'دفاتر', 'دفتر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8985, 'دِفْتِرْيا', 'دفتريا', 'جامد', '', 'دفتريا', 'دفتر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '"""أُصِيبَ بِمَرَضِ الدِّفْتِرْيَا"" : مَرَضٌ يُصِيبُ الحَلْقَ، وَهُوَ مَا يُعْرَفُ بِالخُنَّاقِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8986, 'دِفْرَانٌ', 'دفران', 'جامد', '', 'دفران', 'دفرن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دِفْرَانٌ-دِفْرَانٌ (نب).: شَجَرٌ مِنْ فَصِيلَةِ الصَّنَوْبَرِيَّاتِ، مِنْ صِنْفِ شَجَر القَرْعِ، كَثِيرُ الارْتِفَاعِ، أوْرَاقُهُ عَرِيضَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8987, 'دُفْعَةٌ', 'دفعة', 'جامد', 'دفع', 'دفعة', 'دفعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":دُفَعٌ"', '', 'R', '', '', '', '', '', '', '". ""أَمْطَرَتِ الدُّفْعَةُ الأولَى مِنْ أمْطَارِ الشِّتَاءِ"" : الدَّفْقَةُ مِنَ الْمَطَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8988, 'دُفَعٌ', 'دفع', 'جامد', '', 'دفع', 'دفع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8989, 'مِدْفَعٌ', 'مدفع', 'جامد', 'دفع', 'مدفع', 'مدفع', '', '', '', 'مفرد', 'DnN', '', '', '"مَدَافِعُ"', '', 'R', '', '', '', '', '', '', '". ""دَوَّى صَوْتُ المِدْفَعِ"" : آلَةٌ حَرْبِيَّةٌ مُتَحَرِّكَةٌ تَقْذِفُ بِالقَنَابِلِ بَعِيداً وَهِيَ أَنْوَاعٌ: ""مِدْفَعُ الهَاوُنِ"" ""المِدْفَعُ الرَّشَّاشُ"" ""مِدْفَعٌ مُضَادٌّ لِلطَّائِرَاتِ"" ""مِدْفَعٌ مُضَادٌّ لِلصَّوَارِيخِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8990, 'مَدَافِعُ', 'مدافع', 'جامد', '', 'مدافع', 'مدفع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8991, 'دَفَّةٌ', 'دفة', 'جامد', 'دفف', 'دفة', 'دفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"دَفَّةٌ-دَفَّةٌ [د ف ف]. 1. ""رَدَّ دَفَّةَ البَابِ"" : مِصْرَاعَهُ. 2.""دَفَّةُ السَّفِينَةِ"" : خَشَبَةٌ عَرِيضَةٌ فِي مُؤَخَّرَةِ السَّفِينَةِ لإمَالَتِهَا مِنْ جِهَةٍ إلَى أخْرَى. 3. ""أمْسَكَ دَفَّةَ الحُكْمِ بِحَزْمٍ"" : أيْ سُدَّةَ الحُكْمِ، قِيَادَتَهُ. ""سَيَّرَ دَفَّةَ أُمُورِهِ بِنَجَاحٍ"". 4.""بَاتَ يَتَقَلَّبُ عَلَى دَفَّتَيْهِ"" : عَلَى جَنْبَيْهِ. 5. ""دَفَّتَا الطَّبْلِ"" : الجِلْدَتَانِ اللَّتَانِ تَكْتَنِفَانِ الطَّبْلَ وَيُضْرَبُ عَلَيْهِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8992, 'دِفْلٌ', 'دفل', 'جامد', 'دفل', 'دفل', 'دفل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دِفْلٌ-دِفْلٌ [د ف ل]. 1.: مَا غَلُظَ مِنَ القَطْرانِ وَالزَّفْتِ. 2.:الدِّفْلَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8993, 'دِفْلَى', 'دفلى', 'جامد', '', 'دفلى', 'دفل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', 'N', 'O', 'O', 'O', '', '"دِفْلَى-دِفْلَى (نب).: شَجَرٌ مِنْ فَصِيلَةِ الدِّفْلِيَّاتِ، زَهْرُهُ أحْمَرُ كَالوَرْدِ، وَثَمَرُهُ كَالخَرْنوبِ، مِنْهُ مَا هُوَ أَبْيَضُ دَائِمُ الخُضْرَةِ، يُسْتَعْمَلُ فِي الطِّبِّ. ""يُحِيطُ شَجَرُ الدِّفْلَى بِالحَدِيقَةِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8994, 'مَدْفِنٌ', 'مدفن', 'جامد', 'دفن', 'مدفن', 'مدفن', '', '', '', 'مفرد', 'DnN', '', '', '"مَدَافِنُ"', '', 'R', '', '', '', '', '', '', '". ""حَمَلُوهُ فَوْقَ النَّعْشِ إِلَى مَدْفِنهِ"" : مَوْضِعُ الدَّفْنِ، الْمَقْبَرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8995, 'مَدَافِنُ', 'مدافن', 'جامد', '', 'مدافن', 'مدفن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8996, 'دُفْقَةٌ', 'دفقة', 'جامد', 'دقق', 'دفقة', 'دفقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"دُفْقَةٌ-دُفْقَةٌ [د ق ق]. ""جَاءوا دُفْقَةً"" : أيْ دُفْعَةً وَاحِدَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8997, 'دَقَّاقَةٌ', 'دقاقة', 'جامد', 'دقق', 'دقاقة', 'دققة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"دَقَّاقَةٌ-دَقَّاقَةٌ [د ق ق]. 1. ""دَقَّاقَةُ البابِ"" : حَديدَةٌ تُعَلَّقُ على البابِ لِيُدَقَّ بِها. 2.""وَضَعُوا ساعَةً دَقَّاقَةً في صَدْرِ البَيْتِ"" : أَي ساعَةً تَدُقُّ دَقَّاتٍ مُتَوالِيَةً على رَأْسِ كُلِّ ساعَةٍ. 3. : ما يُدَقُّ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8998, 'دُقاقٌ', 'دقاق', 'جامد', 'دقق', 'دقاق', 'دقق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دُقاقٌ-دُقاقٌ [د ق ق]. 1.""هَبَّ دُقاقُ الرِّيحِ"" : غُبارُ الرِّيحِ. 2.""جَمَعَ دُقاقَ العيدانِ للتَّدْفِئَةِ"" : الأَخْشابُ الصَّغيرَةُ، حُطامُ الأَشْجارِ، كَسارُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(8999, 'دَقَّةٌ', 'دقة', 'جامد', 'دقق', 'دقة', 'دقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""تَوالَتْ دَقَّاتُ قَلْبِهِ"" : نَبَضاتُهُ، خَفَقاتُهُ. 2.""دَقَّ الجَرَسُ دَقَّتَيْنِ"" :ضَرْبَتَيْنِ، قَرْعَتَيْنِ. 3.""الدَّقَّةُ الْمُرَّاكُشِيَّةُ"" : لُعْبَةٌ فولُكْلورِيَّةٌ تَعْتَمِدُ الضَّرْبَ الجَماعِيَّ لِلتَّعْريجَةِ والبَنْديرِ وَالصَّنْجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9000, 'دُقَّةٌ', 'دقة', 'جامد', 'دقق', 'دقة', 'دقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"دِقَّةٌ-دِقَّةٌ [د ق ق] (مص. دَقَّ). 1.""يُجيبُ بِدِقَّةٍ مُتَناهِيَةٍ"": بِضَبْطٍ وَإِحْكامٍ وَعِنايَةٍ. ""يَمْتازُ عَمَلُهُ بِالدِّقَّةِ"". 2.""دِقَّةُ الجِسْمِ"": نُحولُهُ، نَحافَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9001, 'دِقٌّ', 'دق', 'جامد', 'دقق', 'دق', 'دق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دِقٌّ-دِقٌّ [د ق ق]. 1.""شَيْءٌ دِقٌّ"": دَقيقٌ عَكْس غَليظٌ. 2.""أَخَذَ دِقَّ الشَّيْءِ"" : قَليلَهُ. 3.""تَرْعَى الإِبِلُ دِقَّ الشَّجَرِ"" : أَي ما دَقَّ مِنْهُ وَخَسَّ. 4.""حُمَّى الدِّقِّ"" : حُمَّى تَأَتِي يَوْمِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9002, 'دَقوقَةٌ', 'دقوقة', 'جامد', 'دقق', 'دقوقة', 'دققة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"دَقوقَةٌ-دَقوقَةٌ [د ق ق].: دَوابُّ تَدُوسُ الزَّرْعَ الْمَحْصودَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9003, 'دَقوقٌ', 'دقوق', 'جامد', 'دقق', 'دقوق', 'دقق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَقوقٌ-دَقوقٌ [د ق ق].: دَواءٌ يُدَقُّ لِلْعَيْنِ فَيُذَرُّ فيها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9004, 'دَقيقَةٌ', 'دقيقة', 'جامد', 'دقق', 'دقيقة', 'دققة', '', '', '', 'مفرد', 'DnN', '', '', '"دَقائِقُ"', '', 'R', '', '', '', '', '', '', '". 1.""اِنْتَظَرَ دَقيقَةً"" : وَحْدَةٌ زَمَنِيَّةٌ تُعادِلُ جُزْءاً مِنْ سِتِّينَ جُزْءاً، أَي الثَّانِيَةُ مِنَ السَّاعَةِ. ""تُشيرُ السَّاعَةُ إلى العاشِرَةِ وَخَمْسَ عَشْرَةَ دَقيقَةً"" : السّاعَةُ العاشِرَةُ وَرُبْعُ السَّاعَةِ ""تَأَخَّرَ بِعَشْرِ دَقائِقَ"". 2.""يَعْرِفُ دَقائِقَ اللُّغَةِ"" : خَفاياها وَقَضاياها الصَّعْبَةَ، تَفاصيلَها وَجُزْئِيَّاتِها. ""يَعْرِفُ دَقائِقَ الأُمورِ"". 3.""أَنْجَزَ تَرْجَمَةً دَقيقَةً لِلنَّصِّ"" : تَرْجَمَةً وَافِيَةً، أَيْ أَحاطَ بِكُلِّ مَعانِيهِ حَتَّى ما خَفِيَ وَغَمُضَ مِنْها. 4.""آلَةٌ دَقيقَةُ الصُّنْعِ"" : مَصْنوعَةٌ بِإِحْكامٍ وَعِنايَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9005, 'دَقائِقُ', 'دقائق', 'جامد', '', 'دقاءق', 'دقق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9006, 'دَقيقٌ', 'دقيق', 'جامد', 'دقق', 'دقيق', 'دقق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَقيقٌ-دَقيقٌ [د ق ق]. ""عَجَنَتِ الدَّقيقَ"" : أَي مَسْحوقَ القَمْحِ أَوِ الذُّرَةِ أَوِ الشَّعيرِ، الطَّحينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9007, 'مِدَقٌّ', 'مدق', 'جامد', 'دقق', 'مدق', 'مدق', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَدَاقٌّ"', '', 'R', '', '', '', '', '', '', '": ""مِدَقُّ الْحُبُوبِ"" : مَا يُدَقُّ بِهِ. ""مِدَقُّ الغَسِيلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9008, 'مَدَاقٌّ', 'مداق', 'جامد', '', 'مداق', 'مدق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9009, 'دُكَّانٌ', 'دكان', 'جامد', '', 'دكان', 'دكن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَكاكينُ(يُذَكَّروَيُؤَنَّثُ)', '', 'R', '', '', '', '', '', '', '"ج: دَكاكينُ (يُذَكَّر وَيُؤَنَّثُ). ""دُكَّانُ بَيْعِ الْمَوادِّ الغِذائِيَّةِ"": حانوتٌ، مَتْجَرٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9010, 'دَكاكينُ', 'دكاكين', 'جامد', '', 'دكاكين', 'دككن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9011, 'دِكَّةٌ', 'دكة', 'جامد', '', 'دكة', 'دكة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دِكَكَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: دِكَكَةٌ. ""دِكَّةُ السِّرْوالِ"" : التِّكَّةُ، أَيْ حِزامٌ مِنْ نَسيجٍ أَوْ مَطَّاطٍ يُرْبَطُ بِهِ أَعْلَى السِّرْوالِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9012, 'دِكَكَةٌ', 'دككة', 'جامد', '', 'دككة', 'دككة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9013, 'دِكْتاتورٌ', 'دكتاتور', 'جامد', '', 'دكتاتور', 'دكتتر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"""اِنْتَهَى عَهْدُ الدِّكْتاتورِ"" : الحاكِمُ الَّذِي يَسْتَوْلِي على جَميعِ السُّلَطِ وَيَحْكُمُ حُكْماً مُطْلَقاً وَلا يَسْتَشِيرُ أَحَداً في أَحْكامِهِ، الَّتِي تَكونُ في كُلِّ الأَحْوَالِ ضِدَّ رَغَباتِ الشَّعْبِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9014, 'دُكْتورٌ', 'دكتور', 'جامد', '', 'دكتور', 'دكتر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَكاتِرَةٌ"', '', '', '', '', '', '', '', '', '"ج: دَكاتِرَةٌ. 1.""فَحَصَهُ الدًّكْتورُ فَحْصاً دَقيقاً"" : الطَّبيبُ. 2.""أَلْقَى الدُّكْتورُ مُحاضَرَةً عِلْمِيَّةً"" : صِفَةٌ تُعْطَى لِمَنْ أَحْرَزَ على شَهادَةِ الدُّكْتوراه فِي الطِّبِّ أَوِ الأَدَبِ أَوْ مُخْتَلِفِ العُلومِ الأُخْرى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9015, 'دَكاتِرَةٌ', 'دكاترة', 'جامد', '', 'دكاترة', 'دكترة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9016, 'دُكْتوراه', 'دكتوراه', 'جامد', '', 'دكتوراه', 'دكتره', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '"""أَحْرَزَ على شَهادَةِ الدُّكْتُورَاه"" : أَعْلَى شَهادَةٍ جامِعِيَّةٍ تُمْنَحُ بَعْدَ شَهادَةِ الإِجازَةُ (الْلِيسانْسِ) لِمَنْ قَدَّمَ بَحْثاً في عِلْمِ مِنَ العُلومِ في مُسْتَوَى الدِّراساتِ العُلْيا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9017, 'دَكَّةٌ', 'دكة', 'جامد', 'دكك', 'دكة', 'دكة', '', '', '', 'مفرد', 'DnN', '', '', '"دِكاكٌ"', '', 'R', '', '', '', '', '', '', '". ""اِسْتَوَى على دَكَّةٍ قُرْبَ مَنْزِلِهِ"" : بِناءٌ مُرْتَفِعٌ لِلْجُلوسِ وَهُوَ على هَيْئَةِ كُرْسِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9018, 'دِكاكٌ', 'دكاك', 'جامد', '', 'دكاك', 'دكك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9019, 'دُكْنَةٌ', 'دكنة', 'جامد', 'دكن', 'دكنة', 'دكنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دُكْنَةٌ-دُكْنَةٌ [د ك ن]. ""تَكْتَنِفُ الشَّاطِئَ دُكْنَةٌ في لَيالِي الشِّتاءِ"" : لَوْنٌ ضارِبٌ إلى السَّوادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9020, 'دُلاَّعٌ', 'دلاع', 'جامد', '', 'دلاع', 'دلع', '', '', '', 'جمع تكسير', '', '', '', '"واحدةدَلاَّعَةٌ"', '', 'R', '', '', '', '', '', '', '"واحِدَتُهُ دَلاَّعَةٌ. (نب). 1.: البطيخ الأحمر نَباتٌ مِنْ فَصيلَةِ القَرْعِيَّاتِ، ثَمَرَتُهُ كَبيرَةُ الحَجْمِ لَها غِطاءٌ أَخْضَرُ سَميكٌ، حَمْراءُ اللبِّ، لَذيذَةُ الطَّعْمِ، بِداخِلِها بُذورٌ سَوْداءُ اللَّوْنِ، أَوْ ذاتُ بُقَعٍ. 2.: نَوْعٌ مِنْ مَحارِ البَحْرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9021, 'دَلاَّعَةٌ', 'دلاعة', 'جامد', '', 'دلاعة', 'دلعة', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9022, 'دُلْبٌ', 'دلب', 'جامد', '', 'دلب', 'دلب', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دُلْبٌ-دُلْبٌ، ةٌ (نب).: جِنْس شَجَرٍ مِن فَصيلَةِ الدُّلْبِيَّاتِ، يَنْمو على ضِفافِ الأَنْهارِ والأَماكِنِ الرَّطْبَةِ لِحاجَتِهِ إلى الماءِ، يَبْلُغُ عُلُوُّهُ مِنْ عِشْرينَ إلى أَرْبَعينَ مِتْراً، وَهُوَ مِنَ الزَّهْرِيّاتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9023, 'دَلْبوثٌ', 'دلبوث', 'جامد', '', 'دلبوث', 'دلبث', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دَلْبوثٌ-دَلْبوثٌ (نب).: نَباتٌ مِنْ فَصيلَةِ السَّوْسَنِيَّاتِ، يَنْمُو وَسَطَ الزَّرْعِ، لَوْنُهُ مَخْمَلِيٌّ أَو بَنَفْسَجِيٌّ، وَرَقُهُ يُشْبِهُ السَّيْفَ، لِهَذا يُطْلَقُ عَلَيْهِ أَيْضاً سَيْفُ الغُرابِ، وَهُوَ الآنَ مِنْ أَزْهارِ الحَدائِقِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9024, 'دُلْدُولٌ', 'دلدول', 'جامد', '', 'دلدول', 'دلدل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دُلْدُولٌ-دُلْدُولٌ، دُلْدُلٌ (حو).: مِنَ القَواضِمِ، لَبونٌ، يَعيشُ في البِقاعِ الحارَّةِ، مُغَطّىً بِشَوْكٍ طَويلٍ، يُشْبِهُ القُنْفُذَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9025, 'دَلْسٌ', 'دلس', 'جامد', 'دلس', 'دلس', 'دلس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَلْسٌ-دَلْسٌ [د ل س]. ""لاَ يَسْمَحُ بِالدَّلْسِ في صِناعَتِهِ"" : لا يَسْمَحُ بِأَنْ يُدْخِلَ في صِناعَتِهِ خُدْعَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9026, 'دَلَسٌ', 'دلس', 'جامد', '', 'دلس', 'دلس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَدْلاسٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَدْلاسٌ. 1.""جاءَ في دَلَسِ اللَّيْلِ"" : في ظُلْمَتِهِ. 2.""دَلَسُ العُشْبِ"" : بَقاياهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9027, 'أَدْلاسٌ', 'أدلاس', 'جامد', '', 'ءدلاس', 'دلس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9028, 'دُلْفينٌ', 'دلفين', 'جامد', '', 'دلفين', 'دلفن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَلافينُ"', '', 'R', '', '', '', '', '', '', '"ج: دَلافينُ. (حو).: جِنْسٌ بَحْرِيٌّ مِنَ الكَواسِرِ، مِنْ رُتْبَةِ الحِيتانِ الثَّدْيِيَّاتِ لَهَا جِسْمٌ ضَخْـمٌ وَسَمينٌ، يَمْتَـدُّ رَأْسُهَا كَالْمِنْقارِ، وَهِيَ مَعْروفَةٌ بِذَكائِهَا، تُساعِدُ الغَريقَ بِتَمْكينِهِ مِنْ ظَهْرِها لإِنْقاذِهِ، وَتُسَمِّيَها العَرَبُ الدُّخَسَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9029, 'دَلافينُ', 'دلافين', 'جامد', '', 'دلافين', 'دلفن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9030, 'دَلوكٌ', 'دلوك', 'جامد', 'دلك', 'دلوك', 'دلك', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دُلوكُ-دُلوكُ [د ل ك] (مص. دَلَكَ). ""دُلوكُ الشَّمْسِ"": زَوالُها عَنْ كَبِدِ السَّماءِ. الإسراْء آية 78 أَقِمِ الصَّلاةَ لِدُلوكِ الشَّمْس ِ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9031, 'مِدْلَكَةٌ', 'مدلكة', 'جامد', 'دلك', 'مدلكة', 'مدلكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مِدْلَكَةٌ-مِدْلَكَةٌ [د ل ك]. ن. مِدْلَكٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9032, 'مِدْلَكٌ', 'مدلك', 'جامد', 'دلك', 'مدلك', 'مدلك', '', '', '', 'مفرد', 'DnN', '', '', '"مَدَالِكُ"', '', 'R', '', '', '', '', '', '', '". ""مِدْلَكُ الجِسْمِ"" : أَدَاةُ الدَّلْكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9033, 'مَدَالِكُ', 'مدالك', 'جامد', '', 'مدالك', 'مدلك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9034, 'دَالَّةٌ', 'دالة', 'جامد', 'دلل', 'دالة', 'دلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"دَالَّةٌ-دَالَّةٌ [د ل ل]. 1. ""أَظْهَرَ دَالَّةً"": مَا تَتَجرَّأُ بِهِ عَلَى الصَّدِيقِ أوِ القَرِيبِ، الجُرْأَةُ. 2. ""لَهُ عَلَيَّ دَالَّةٌ"" : مَنْزِلَةٌ، فَضْلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9035, 'دَلالَةٌ', 'دلالة', 'جامد', 'دلل', 'دلالة', 'دللة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":دَلائِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""لَمْ يَجِدْ دَلالَةً تُرْشِدُهُ في طَريقِهِ"" : أَي عَلامَةً، إِرْشاداً. 2.""لَمْ يَكُنْ يَمْلِكُ دَلائِلَ"" : بَراهينَ. 3.""دَلالَةُ اللَّفْظِ"" : فَهْمُ الْمَعْنَى مِنَ اللَّفْظِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9036, 'دَلائِلُ', 'دلائل', 'جامد', '', 'دلاءل', 'دلل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9037, 'دَليلَةٌ', 'دليلة', 'جامد', 'دلل', 'دليلة', 'دللة', '', '', '', 'مفرد', 'DnN', '', '', '"دَلائِلُمؤنثدَليل"', '', 'R', '', '', '', '', '', '', '". 1.""طَريقٌ دَليلَةٌ"": واضِحَةٌ. 2.""قَدَّمَ دَليلَةً"" : دَليلاً واضِحاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9038, 'دَلائِلُ', 'دلائل', 'جامد', '', 'دلاءل', 'دلل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9039, 'دَيْلَمٌ', 'ديلم', 'جامد', 'دلم', 'ديلم', 'دلم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَيْلَمٌ-دَيْلَمٌ [د ل م]. 1.""رَجُلٌ دَيْلَمٌ"" : داهِيَةٌ. 2.: مُجْتَمَعُ النَّمْلِ وَنَحْوِهِ عِنْدَ مُؤَخَّرِ الحَوْضِ. 3. : الجَيْشُ يُشَبَّهُ بِالنَّمْلِ لِكَثْرَتِهِ. 4. (حو).: ذَكَرُ الدُّرَّاجِ. 5. : ضَرْبٌ مِنَ القَطا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9040, 'دَلاةٌ', 'دلاة', 'جامد', 'دلو', 'دلاة', 'دلة', '', '', '', 'مفرد', 'DnN', '', '', '"دَلًى:دَلَواتٌ"', '', '', '', '', '', '', '', '', '".:دَلْوٌ صَغيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9041, 'دَلًى', 'دلى', 'جامد', '', 'دلى', 'دل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9042, 'دَلَواتٌ', 'دلوات', 'جامد', '', 'دلوات', 'دلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9043, 'دَلْوٌ', 'دلو', 'جامد', '', 'دلو', 'دل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دِلاءٌ(مُؤَنَّثٌوَقَدْيُذَكَّ', '', 'R', '', '', '', '', '', '', '"ج: دِلاءٌ. (مُؤَنَّثٌ وَقَدْ يُذَكَّرُ). 1.""دَلَّى الدَّلْوَ"" : السَّطْلَ. 2.""أَدْلَى بِدَلْوِهِ"" : شارَكَ بِرَأْيِهِ. ""أَلْقِ دَلْوَكَ بَيْنَ الدِّلاءِ"". 3.""بُرْجُ الدَّلْوِ"" : صورَةٌ مِنْ صُوَرِ مِنْطَقَةِ البُروجِ، وَهُوَ البُرْجُ الحادِي عَشَرَ، سُمِّيَ بِالدَّلْوِ تَشْبيهاً بِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9044, 'دِلاءٌ', 'دلاء', 'جامد', '', 'دلاء', 'دل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9045, 'دَاليَةٌ', 'دالية', 'جامد', 'دلي', 'دالية', 'دلة', '', '', '', 'مفرد', 'DnN', '', '', '"دَوَالٍ:الدَّوَالِي"', '', '', '', '', '', '', '', '', '". 1. ""تَدَلَّتْ عَنَاقِيدُ العِنَبِ مِنَ الدَّالِيَةِ"" : شَجَرَةُ الكَرْمِ. ""مَنْزِلٌ بِهِ دَالِيةٌ عَنَاقِيدُهَا تُثْمِرُ عِنَباً شَهِيّاً"". (محمد برادة). 2. ""دَالِيَةُ الْمَاءِ"" : النَّاعُورَةُ تَدُورُ بِالْمَاءِ، السَّاقِيَة. 3. ""أرْضٌ دَالِيَةٌ"" : الأرْضُ تُسْقَى بِالدَّلْوِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9046, 'دَوَالِي', 'دوالي', 'جامد', '', 'دوالي', 'دل', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9047, 'دَموثَةٌ', 'دموثة', 'جامد', 'دمث', 'دموثة', 'دمثة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"دَموثَةٌ-دَموثَةٌ [د م ث]. ن. دَماثَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9048, 'دِمْسٌ', 'دمس', 'جامد', 'دمس', 'دمس', 'دمس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دِمْسٌ-دِمْسٌ [د م س]. ""وَضَعَ القِدْرَ في الدِّمْسِ"" : خَليطٌ مِنَ التِّبْنِ وَرَوْثِ الدَّوابِّ وَغَيْرِهِما يُسْتَعْمَلُ في الوَقودِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9049, 'دِمَشْقُ', 'دمشق', 'جامد', '', 'دمشق', 'دمشق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rp', '', 'N', 'N', 'N', 'O', '', '"عاصِمَةُ الجُمْهورِيَّةِ السُّورِيَّة."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9050, 'دُماعٌ', 'دماع', 'جامد', 'دمع', 'دماع', 'دمع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دُماعٌ-دُماعٌ [د م ع]. 1.""دُماعُ العَيْنِ"" : ما يَسيلُ مِنَ العَيْنِ مِنْ عِلَّةٍ أَوْ كِبَرٍ. 2.""دُماعُ الشَّجَرَةِ"" : ما يَسيلُ مِنْها عِنْد قَطْعِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9051, 'دَمْعَةٌ', 'دمعة', 'جامد', 'دمع', 'دمعة', 'دمعة', '', '', '', 'مفرد', 'DnN', '', '', '"دَمْعٌ:أَدْمُعٌ:دُموعٌ"', '', 'R', '', '', '', '', '', '', '". ""رَأَيْتُ على خَدِّها دَمْعَةً فَرَقَّ قَلْبِي لِحالِها"" : قَطْرَةً مِنَ الدَّمْعِ."', '');
