INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9055, 'مَدَامِعُ', 'مدامع', 'جامد', 'دمع', 'مدامع', 'مدمع', '', '', '', 'مفرد', '', '', '', '"مفردمَدْمَع"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '". ""فَاضَتْ مَدَامِعُهُ"" : مَسِيلُ الدَّمْعِ فِي العَيْنِ أَوْ مُجْتَمَعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9056, 'مَدْمَعٌ', 'مدمع', 'جامد', 'دمع', 'مدمع', 'مدمع', '', '', '', 'مفرد', 'DnN', '', '', '"مَدَامِعُ"', '', 'R', '', '', '', '', '', '', '".: مَجْرَى الدَّمْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9057, 'مَدَامِعُ', 'مدامع', 'جامد', '', 'مدامع', 'مدمع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9058, 'دِماغٌ', 'دماغ', 'جامد', 'دمغ', 'دماغ', 'دمغ', '', '', '', 'مفرد', 'DnN', '', '', '"أَدْمِغَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَصابَ دِماغَهُ صُداعٌ"" : الْمُخُّ، وَهُوَ مَرْكَزٌ عَصَبِيٌّ في الرَّأْسِ يُسَيْطِرُ بِهِ عَلى الأَفْعالِ والأَعْمالِ. 2.""أُمُّ الدِّماغِ"" : جُلَيْدَةٌ رَقيقَةٌ تَجْمَعُ الْمُخَّ. ""بَلَغَتِ الشَّجَّةُ أُمَّ الدِّماغِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9059, 'أَدْمِغَةٌ', 'أدمغة', 'جامد', '', 'ءدمغة', 'دمغة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9060, 'دَمْغَةٌ', 'دمغة', 'جامد', 'دمغ', 'دمغة', 'دمغة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"دَمْغَةٌ-دَمْغَةٌ [د م غ]. 1.""تَرَكَ دَمْغَةَ أُصْبُعِهِ على الوَرَقَةِ"" : بَصْمَتَهُ. 2.""كَتَبَ العَقْدَ على وَرَقِ الدَّمْغَةِ"" : وَرَقٌ رَسْمِيٌّ عَلَيْهِ طابَعٌ خاصٌّ بِالأَوْراقِ القانونِيَّةِ والْمُسْتَنَداتِ الرَّسْمِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9061, 'دِمَقْسٌ', 'دمقس', 'جامد', '', 'دمقس', 'دمقس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""لَبِسَتْ قَميصاً مِنَ الدِّمَقْسِ"" : قَميصاً مِنَ الحَريرِ الأَبْيَضِ، الدِّيباج."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9062, 'دِمالٌ', 'دمال', 'جامد', 'دمل', 'دمال', 'دمل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دِمالٌ-دِمالٌ [د م ل]. 1.""دِمالُ الأَرْضِ"" : سَمادُها. 2.: تَمْرٌ عَفِنٌ أَسْوَدُ قَديمٌ. 3.""اِنْتَشَرَ الدِّمالُ على الشَّاطِىءِ"" : ما يَرْمِي بِهِ البَحْرُ مما لا خَيْرَ فيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9063, 'دُمَّلَةٌ', 'دملة', 'جامد', 'دمل', 'دملة', 'دملة', '', '', '', 'مفرد', 'DnN', '', '', '"واحدةالدُّمَّل"', '', 'R', '', '', '', '', '', '', '"دُمَّلَةٌ-دُمَّلَةٌ [د م ل].: واحِدَةُ الدُّمَّل. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9064, 'دُمَلٌ', 'دمل', 'جامد', 'دمل', 'دمل', 'دمل', '', '', '', 'مفرد', 'DnN', '', '', '"دَمامِلُ:دَماميلُ"', '', 'R', '', '', '', '', '', '', '"دُمَلٌ-دُمَلٌ، دُمَّلٌ [د م ل]. ج: دَمامِلُ، دَماميلُ. ""بَرَزَ دُمَّلٌ في فَخِذِهِ"" : الخُراجُ، البَثْرُ، وَهُوَ ما يَظْهَرُ على الجِلْدِ وَيُحْدِثُ انْتِفاخاً وَيَتَكَوَّنُ بِداخِلِهِ القَيْحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9065, 'دَمامِلُ', 'دمامل', 'جامد', '', 'دمامل', 'دممل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
