INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9067, 'دُمْلُجٌ', 'دملج', 'جامد', '', 'دملج', 'دملج', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَمالِجُ"', '', 'R', '', '', '', '', '', '', '"ج: دَمالِجُ. ""وَضَعَتْ في مِعْصَمِها دُمْلُجاً مِنْ ذَهَبٍ"" : أَيْ سِواراً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9068, 'دَمالِجُ', 'دمالج', 'جامد', '', 'دمالج', 'دملج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9069, 'دِمامٌ', 'دمام', 'جامد', 'دمم', 'دمام', 'دمم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دِمامٌ-دِمامٌ [د م م]. 1.""طَلَتْ وَجْهَها بِالدِّمامِ"" : الحُمْرَة التِي تُزَيِّنُ بِها الْمَرْأَةُ وَجْهَها. 2.""طَلَى عَيْنَهُ بِدِمامٍ"" : ما يُطْلَى بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9070, 'دَمانٌ', 'دمان', 'جامد', 'دمن', 'دمان', 'دمن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دَمانٌ-دَمانٌ [د م ن]. 1.""دَمانُ الحَقْلِ"" : سَمادَهُ. 2.""دَمانُ الجَمْرِ"" : رَمادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9071, 'دِمْنٌ', 'دمن', 'جامد', 'دمن', 'دمن', 'دمن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دِمْنٌ-دِمْنٌ [د م ن]. 1.""دِمْنُ الأَرْضِ"" : السَّمادُ الْمُتَلَبِّدُ. 2.""رَجُلٌ دِمْنُ مالٍ"" : سائِسُهُ لا يَنْفَكُّ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9072, 'دِمْنَةٌ', 'دمنة', 'جامد', '', 'دمنة', 'دمنة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دِمَنٌ:دَمْنٌ"', '', 'R', '', '', '', '', '', '', '"ج: دِمَنٌ، دَمْنٌ. 1.""وَقَفُوا على الدِّمَنِ"" : بَقايا آثارِ الدَّارِ. 2.""دِمْنَةُ الحَوْضِ"" : ما اخْتَلَطَ مِنَ البَعْرِ والطِّينِ فَتَلَبَّدَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9073, 'دِمَنٌ', 'دمن', 'جامد', '', 'دمن', 'دمن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9074, 'دَمْنٌ', 'دمن', 'جامد', '', 'دمن', 'دمن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9075, 'دَمٌ', 'دم', 'جامد', 'دمي', 'دم', 'دم', '', '', '', 'مفرد', 'DnN', '', '', '"دِماءٌ"', '', '', '', '', '', '', '', '', '". ""سالَ الدَّمُ مِنْ جِسْمِهِ"" : سائِلٌ أَحْمَرُ يَجْرِي في عُروقِ الكائِنِ إِنْساناً أَوْ حَيَواناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9076, 'دِماءٌ', 'دماء', 'جامد', '', 'دماء', 'دم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9077, 'دُمْيَةٌ', 'دمية', 'جامد', '', 'دمية', 'دمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"1.""تَلْعَبُ بِدُمْيَتِها"": صُورَةُ بِنْتٍ صَغيرَةٍ مَصْنوعَةٍ منَ الثَّوْبِ أَوِ الْمَطَّاطِ وَنَحْوِهِمَا. ""إِنَّها لَدُمْيَةٌ"" : تُقالُ إِعْجاباً بِجَمالِ امْرَأَةٍ. 2.""كـانَ دُمْيَةً بَيْنَ يَدَيْهِ"" : كِنايَةً عَنْ لُعْبَةٍ يَفْعَلُ بِها ما يَشاءُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9078, 'دَنٌّ', 'دن', 'جامد', '', 'دن', 'دن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دِنانٌ"', '', 'R', '', '', '', '', '', '', '"ج: دِنانٌ: الجَرَّةُ الضَّخْمَةُ لِلْخَمْرِ والزَّيْتِ وَنَحْوِهِما."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9079, 'دِنانٌ', 'دنان', 'جامد', '', 'دنان', 'دنن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9080, 'دُنُوٌّ', 'دنو', 'جامد', 'دنو', 'دنو', 'دن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دُنُوٌّ-دُنُوٌّ [د ن و]. ""إِنِّي لأَرَى دُنُوَّ أَجَلِهِ"" : أَيْ قُرْبَهُ. ""يَشْعُرُ بِدُنُوِّ الخَطَرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9081, 'دُنْيا', 'دنيا', 'جامد', 'دنو', 'دنيا', 'دن', '', '', '', 'مفرد', 'Dy', '', '', '"دُنىًمؤَنَّثُأَدْنَى"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""مَباهِجُ الدُّنْيا"" : الحَياةُ الحاضِرَةُ، العالَمُ. ""الحَياةُ الدُّنْيا"" : عَكْسَ الحَياة الأخرَى. 2.""أَقامَ الدُّنْيا وَأَقْعَدَها"" : شَغَلَ النَّاسَ، زَعْزَعَ كُلَّ شَيْءٍ. 3.""يَعيشُ في دُنْيا الأَحْلامِ"" : في عالَمِ الأَحْلامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9082, 'دُنىً', 'دنى', 'جامد', '', 'دنى', 'دن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9083, 'دَهْرٌ', 'دهر', 'جامد', 'دهر', 'دهر', 'دهر', '', '', '', 'مفرد', 'DnN', '', '', '"دُهورٌ"', '', 'R', '', '', '', '', '', '', '"1.""أَطالَ بِهِ الدَّهْرُ"" :مُدَّةُ الحَياةِ الدُّنْيا كُلُّها وَتُطْلَقُ على أَلْفِ سَنَةٍ.الجاثية آية 24وَقالُوا مَا هِيَ إِلاَّ حَياتُنا الدُّنْيا نَموتُ وَنَحْيا وَما يُهْلِكُنا إِلاَّ الدَّهْرُ . (قرآن). 2.""أَقامَ في بِلادِ الغُرْبَةِ دَهْراً"" : زَمَناً طَويلاً. 3.""في أَوَّلِ الدَّهْرِ"" : في أَوَّلِ الزَّمانِ. 4.""في آخِرِ الدَّهْرِ"" : نِهايَة العالَمِ. 5.""لا آتيكَ أَبَدَ الدَّهْرِ"" : لا آتيكَ أَبَداً. 6.""إلى دَهْرِ الدَّاهِرينَ"" : إلى الأَبَدِ. 7.""تَقَلُّباتُ الدَّهْرِ"" : صُروفُهُ. ""صُروفُ الدَّهْرِ"" ""تَصاريفُ الدَّهْرِ"". 8.""ما دَهْرِي !"" : ما هَمِّي، ما غايَتِي!. 9.""دَهْرُ الإِنْسانِ"" : الزَّمَنُ الَّذِي يَعيشُ فيهِ، العَصْرُ. ""أَكَلَ عَلَيْهِ الدَّهْرُ وَشَرِبَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9084, 'دُهورٌ', 'دهور', 'جامد', '', 'دهور', 'دهر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9085, 'دُهْسَةٌ', 'دهسة', 'جامد', 'دهس', 'دهسة', 'دهسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دُهْسَةٌ-دُهْسَةٌ [د هـ س].: لَوْنُ الرَّمْلِ يَعْلوهُ السَّوادُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9086, 'دَهْسٌ', 'دهس', 'جامد', 'دهس', 'دهس', 'دهس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دَهْسٌ-دَهْسٌ [د هـ س]. 1.""مَكانٌ دَهْسٌ"" : لَيِّنٌ لَيْسَ بِرَمْلٍ وَلا تُرابٍ. 2.""نَباتٌ دَهْسٌ"" : نَباتٌ لَمْ يَغْلُبْ عَلَيْهِ لَوْنُ الخُضْرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9087, 'دَهْشَةٌ', 'دهشة', 'جامد', 'دهش', 'دهشة', 'دهشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"دَهْشَةٌ-دَهْشَةٌ [د هـ ش]. ""ظَهَرَتْ على وَجْهِهِ دَهْشَةٌ"" : حَيْرَةٌ، اِرْتِباكٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9088, 'دُهِشَ', 'دهش', 'جامد', 'دهش', 'دهش', 'دهش', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'N', 'N', 'N', '', '"دُهِشَ-دُهِشَ [د هـ ش]. ن. دَهِشَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9089, 'دَهَقٌ', 'دهق', 'جامد', 'دهق', 'دهق', 'دهق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَهَقٌ-دَهَقٌ [د هـ ق]. ""عَذَّبَهُ بِالدَّهَقِ"" : خَشَبَتانِ كانَتا تُسْتَعْمَلانِ لِلتَّضْيِيقِ على السَّاقِ لِلتَّعْذِيبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9090, 'دِهْقانٌ', 'دهقان', 'جامد', '', 'دهقان', 'دهقن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَهاقِنَةٌ:دَهاقينُ"', '', 'R', '', '', '', '', '', '', '"ج: دَهاقِنَةٌ، دَهاقينُ. 1.""دِهْقانُ الإِقْليمِ"": رَئيسُهُ. 2.""دَهاقِنَةُ السِّياسَةِ"" :كِبارُ السَّاسَةِ. 3.""رَجُلٌ دِهْقانٌ"" : مَنْ لَهُ مالٌ وَعَقارٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9091, 'دَهاقِنَةٌ', 'دهاقنة', 'جامد', '', 'دهاقنة', 'دهقنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9092, 'دَهاقينُ', 'دهاقين', 'جامد', '', 'دهاقين', 'دهقن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9093, 'دِهْليزٌ', 'دهليز', 'جامد', '', 'دهليز', 'دهلز', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَهاليزُ"', '', 'R', '', '', '', '', '', '', '"ج: دَهاليزُ. 1.""دِهْليزُ الدَّارِ"" : الْمَدْخَلُ الْمُمْتَدُّ ما بَيْنَ البابِ وَوَسَطِ الدَّارِ. ""بَلَغَتِ الدِّهْليزَ الأَعْلَى وَكانَ قَليلَ الإِضاءةِ"". (جبرا إبراهيم جبرا). 2.""أَبْناءُ الدِّهْليزِ"" : اللُّقَطاءُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9094, 'دَهاليزُ', 'دهاليز', 'جامد', '', 'دهاليز', 'دهلز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9095, 'دَهْماءُ', 'دهماء', 'جامد', 'دهم', 'دهماء', 'دهم', '', '', '', 'مفرد', 'Dw', '', '', '"دُهْمٌ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""في لَيْلَةٍ دَهْماءَ"" : اللَّيْلَةُ شَديدَةُ السَّوادِ. 2.""حَديقَةٌ دَهْماءُ"" : الحَديقَةُ الخَضْراءُ وَلَوْنُها ضارِبٌ إلى السَّوادِ لِشِدَّةِ اخْضِرارِها وَرَيِّها. 3.""مِنَ الدَّهْماءِ"" : مِنْ عامَّةِ النَّاسِ. 4.""نَعْجَةٌ دَهْماءُ"" : الخالِصَةُ الحُمْرَةِ. 5.""داهِيَةٌ دَهْماءُ"" : دَاهِيَةٌ دَهْياءُ، الْمُصيبَةُ العَظيمَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9096, 'دُهْمٌ', 'دهم', 'جامد', '', 'دهم', 'دهم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9097, 'دَهْناءُ', 'دهناء', 'جامد', 'دهن', 'دهناء', 'دهن', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"دَهْناءُ-دَهْناءُ [د هـ ن]. 1.""تاهَ في الدَّهْناءِ"" : الصَّحْراءُ، الفلاةُ. 2. : عُشْبَةٌ حَمْراءُ لَها وَرَقٌ عَريضٌ يُدْبَغُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9098, 'دُهْنَةٌ', 'دهنة', 'جامد', 'دهن', 'دهنة', 'دهنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"دُهْنَةٌ-دُهْنَةٌ [د هـ ن]. : القَليلُ مِنَ الدُّهْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9099, 'دُهْنٌ', 'دهن', 'جامد', 'دهن', 'دهن', 'دهن', '', '', '', 'مفرد', 'DnN', '', '', '"أَدْهانٌ:دِهانٌ"', '', 'R', '', '', '', '', '', '', '". 1.""طَلَتْ شَعْرَها بِدُهْنٍ مُعَطَّرٍ"" : مادَّةٌ دَسِمَةٌ تُسْتَخْرَجُ مِنْ أَنْسِجَةِ النَّباتِ والحَيَوانِ، تَكونُ جامِدَةً في دَرَجَةِ الحَرارَةِ العادِيَةِ وَتُصْبِحُ زَيْتاً سائِلاً في دَرَجَةِ الحَرارَةِ العالِيَةِ. ""دُهْنُ الشَّعْرِ"". 2.""وَضَعَ الدُّهْنَ على الخُراجِ"" : الْمُرْهَمَ. 3.""دُهْنُ اللَّوْزِ"" : زَيْتٌ يُسْتَخْرَجُ مِنَ اللَّوْزِ. 4.""دُهْنُ النَّخيلِ"" : زَيْتٌ يُسْتَخْرَجُ مِنْ أَشْجارِ النَّخيلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9100, 'أَدْهانٌ', 'أدهان', 'جامد', '', 'ءدهان', 'دهن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9101, 'دِهانٌ', 'دهان', 'جامد', '', 'دهان', 'دهن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9102, 'دَاهِيَةٌ', 'داهية', 'جامد', 'دهي', 'داهية', 'دهة', '', '', '', 'مفرد', 'DnN', '', '', '"دَوَاهٍ:الدَّوَاهِي"', '', '', '', '', '', '', '', '', '". ""نَزَلَتْ بِهِ دَاهِيَةٌ"" : مُصِيبَةٌ، عَظِيمَةٌ، نَازِلَةٌ، بَلِيَّةٌ. ""تَوَالَتْ عَلَيْهِ الدَّوَاهِي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9103, 'دَوَاهِي', 'دواهي', 'جامد', '', 'دواهي', 'ده', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9104, 'دَهْياءُ', 'دهياء', 'جامد', '', 'دهياء', 'ده', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"""داهِيَةٌ دَهْياءُ"" : دَاهِيَةٌ دَهْماءُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9105, 'دَاءٌ', 'داء', 'جامد', 'دوأ', 'داء', 'د', '', '', '', 'مفرد', 'Dz', '', '', '"أدْوَاءٌ"', '', 'Rz', '', '', '', '', '', '', '". 1.""دَاءٌ فَتَّاكٌ"" : عِلَّةٌ، مَرَضٌ. 2.""دَاءُ الذِّئْبِ"" : الجُوعُ. 3. ""دَاءُ الكَلْبِ"" : الجُوعُ الشَّدِيدُ. 4. ""دَاءُ الثَّعْلَبِ"" : تَسَاقُطُ شَعْرِ الرَّأْسِ. 5. ""دَاءُ الأسَدِ"" : الحُمَّى. 6. ""دَاءُ الضَّرَائِرِ"" : الشَّرُّ الدَّائِمُ. 7. ""دَاءُ الْمَفَاصِلِ"" : آلاَمُ الْمَفَاصِلِ وَهُوَ ما يُعْرَفُ بِالرُّومَاتِيزم. 8. ""دَاءُ المِنْطَقَةِ"" : مَرَضٌ جِلْدِيٌّ يُسَبِّبُ بُثُوراً فِي الجِلْدِ وَيَظْهَرُ فِي الجِذْعِ وَالأعْضَاءِ السُّفْلَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9106, 'أدْوَاءٌ', 'أدواء', 'جامد', '', 'ءدواء', 'د', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9107, 'دَوْحَةٌ', 'دوحة', 'جامد', 'دوح', 'دوحة', 'دحة', '', '', '', 'مفرد', 'DnN', '', '', '"دُوحٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِسْتَقَلَّ بِظِلِّ الدَّوْحَةِ"": الشَّجَرَةُ العَظيمَةُ ذاتُ الفُروعِ الْمُفَرَّعَةِ. 2.""هُوَ مِنْ دَوْحَةِ الكَرَمِ"" : مِنْ شَجَرَةِ نَسَبٍ لَها كَرَمٌ وَحَسَبٌ. 3.""اِسْتَظَلَّ بِالدَّوْحَةِ"" : بِالمِظَلَّةِ الكَبيرَةِ. 4.""زارَ مَدينَةَ الدَّوْحَةِ"" : عاصِمَةَ قَطَرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9108, 'دُوحٌ', 'دوح', 'جامد', '', 'دوح', 'دح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9109, 'دَوْخَةٌ', 'دوخة', 'جامد', 'دوخ', 'دوخة', 'دخة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""أَحَسَّ بِدَوْخَةٍ"" : الشُّعورُ بِفِقْدانِ التَّوازُنِ وَعَدَمِ التَّحَكُّمِ في الأَعْصابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9110, 'دُوَيْدَةٌ', 'دويدة', 'جامد', 'دود', 'دويدة', 'ددة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"دُوَيْدَةٌ-دُوَيْدَةٌ [د و د].: تَصْغيرُ دُودَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9111, 'دُودَةٌ', 'دودة', 'جامد', '', 'دودة', 'ددة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دُودٌ:ديدانٌ"', '', 'R', '', '', '', '', '', '', '"ج: دُودٌ، ديدانٌ. (حو). 1.: دُوَيِبَّةٌ مِنْ عَديماتِ الفَقارِ، فَصائِلُها عَديدَةٌ وَأَجْناسُها مُتَنَوِّعَةٌ، أَغْلَبُها مِنَ الطُّفَيْلِيَّاتِ، تَقْتاتُ بِالْمَوادِّ العُضْوِيَّةِ في الأَجْسامِ الحَيَّةِ وَفِي الجِيفِ. 2.""الدُّودَةُ الوَحيدَةُ"" : نَوْعٌ يَكْثُرُ في الجُزْءِ الهَضْمِيِّ، مِنَ الدِّيدانِ الشَّريطِيَّةِ الطُّفَيْلِيَّةِ، وَتَعيشُ في أَمْعاءِ الثَّدْيِيَّاتِ، "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9112, 'دُودٌ', 'دود', 'جامد', '', 'دود', 'دد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9113, 'ديدانٌ', 'ديدان', 'جامد', '', 'ديدان', 'ددن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9114, 'دَارٌ', 'دار', 'جامد', 'دور', 'دار', 'در', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '":دُورٌ:دِيَارٌ:دِيَارَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""بَنَى دَارَهُ"" : مَحَلَّ سُكْنَاهُ، بَيْتُ السَّكَنِ، مَنْزِلٌ. 2. ""اِسْتَقَرَّ فِي دِيَارِ الإسْلاَمِ"" : فِي بِلاَدِ الإسْلاَمِ. 3. ""زَارَ دَارَ السَّلامِ"" : بَغْدَادَ. 4. ""اِنْتَقَلَ إلَى دَارِ الفَنَاءِ"" : تُوُفِّيَ، أي انْتَقَلَ إلَى الدَّارِ الآخِرَةِ. 5. ""اِكْتَمَلَتْ دَارَةُ القَمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9115, 'دُورٌ', 'دور', 'جامد', '', 'دور', 'در', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9116, 'دِيَارٌ', 'ديار', 'جامد', '', 'ديار', 'در', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9117, 'دِيَارَةٌ', 'ديارة', 'جامد', '', 'ديارة', 'درة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9118, 'دَائِرَةٌ', 'دائرة', 'جامد', 'دور', 'داءرة', 'درة', '', '', '', 'مفرد', 'DnN', '', '', '"دَوَائِرُ"', '', 'R', '', '', '', '', '', '', '". 1. ""رَسَمَ دَائِرَةً بِالبِرْكَارِ""(هن) : شَكْلٌ مُسْتَوٍ مَحْدُودٌ، وَنِقَاطُهُ مُتَسَاوِيَةُ الأبْعَادِ مِنْ نُقْطَةٍ دَاخِلِيَّةٍ تُسَمَّى مَرْكَزَ الدَّائِرَةِ. أ. ""مُحِيطُ الدَّائِرَةِ"" : الخَطُّ الدَّائِرُ. ب. ""قُطْرُ الدَّائِرَةِ"" : الخَطُّ الْمُسْتَقِيمُ الَّذِي يَقْسِمُ الدَّائِرَةَ نِصْفَيْنِ مُتَسَاوِيَيْنِ مَارًّا بِمَرْكَزِهَا. 2. ""دَائِرَةُ رَأْسِ الإنْسَانِ"" : شَعْرُهُ الْمُسْتَدِيرُ عَلَى قَرْنِهِ. 3. ""بَحَثَ عَنْ مَعْنَى كَلِمَةِ الدِّيمُقْرَاطِيَّةِ فِي دَائِرَةِ الْمَعَارِفِ"" : مَوْسُوعَةٌ تَضُمُّ مَعْلُومَاتٍ دَقِيقَةً عَنْ مُخْتَلِفِ مَيَادِينِ العِلْمِ وَالْمَعْرِفَةِ وَالفَنِّ. 4.""الدَّائِرَةُ الانْتِخَابِيَّةُ"" : تَقْسِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9119, 'دَوَائِرُ', 'دوائر', 'جامد', '', 'دواءر', 'در', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9120, 'دَوَّارَةٌ', 'دوارة', 'جامد', 'دور', 'دوارة', 'درة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دَوَّارَةٌ-دَوَّارَةٌ، دُوَّارَةٌ [د و ر]. 1.""دُوَّارَةُ رَأْسٍ"" : طائِفَةٌ مِنْهُ مُسْتَديرَةٌ. 2.""دُوَّارَةُ البَطْنِ"" : ما تَجَمَّعَ وَاسْتَدارَ مِن أَمْعائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9121, 'دَوَّارٌ', 'دوار', 'جامد', 'دور', 'دوار', 'در', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"دَوَّارٌ-دَوَّارٌ [د و ر]. 1.""يَسْتَخْرِجُ الزَّيْتَ مِنْ دَوَّارِ الشَّمْسِ"": نَباتٌ مُرْتَفِعٌ، في رَأْسِهِ زَهْرَةٌ صَفْراءُ مُدَوَّرَةٌ عَريضَةٌ، تَميلٌ حَيْثُ مالَتِ الشَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9122, 'دُوَّارٌ', 'دوار', 'جامد', 'دور', 'دوار', 'در', '', '', '', 'مفرد', 'DnN', '', '', '"دَواويرُ"', '', 'R', '', '', '', '', '', '', '". 1.""مُسْتدارُ رَمْلٍ تَدورُ حَوْلَهُ الوُحوشُ. 2.: الكَعْبَة. 3.""الْمَنْزِلُ، فِناءٌ فَسيحٌ في الْمَنْزِلِ الكَبيرِ لِلأُسْرَةِ. 4.""يَسْكُنُ في الدَّوارِ"" : القَرْيَةُ في البادِيَةِ تَضُمُّ عَدَداً مَحْدوداً مِنَ الدّورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9123, 'دَواويرُ', 'دواوير', 'جامد', '', 'دواوير', 'در', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9124, 'دُوارٌ', 'دوار', 'جامد', 'دور', 'دوار', 'در', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دُوارٌ-دُوارٌ [د و ر]. 1.""شَعَرَ بِدُوارٍ في رَأْسِهِ"" : دَوْخَةٌ، أَيْ ما يَأْخُذُ الرَّأْسَ مِنَ دَوَرانٍ. 2.""بِمُجَرَّدِ مارَكِبَ السَّفينَةَ اِسْتَوْلَى عَلَيْهِ دُوارُ البَحْرِ"" : الهُدامُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9125, 'دَوائِرُ', 'دوائر', 'جامد', 'دور', 'دواءر', 'در', '', '', '', 'مفرد', '', '', '', '"مفرددائِرَة"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '". 1. ""دارَتْ عَلَيْهِ الدَّوائِرُ"" : أَيْ نَزَلَتْ بِهِ تَقَلُّباتُ الدَّهْرِ وَتَصاريفُهُ، الدَّواهِي، النَّوائِبُ، صُروفُ الدَّهْرِ. 2. ""دَوائِرُ الطُّولِ"" : دَوائِرُ عُظْمَى عَمودِيَّةٌ على خَطِّ الاسْتِواءِ. 3. ""دَوائِرُ العَرْضِ"" : هِيَ دَوائِرُ مُتَوازِيَةٌ لِخَطِّ الاسْتِواءِ. 4. ""دَوائِرُ صُغْرَى"" : هِيَ مَقْطَعُ كُرَةٍ بِمُسْتَوىً لا يَمُرُّ مِنَ الْمَرْكَزِ. 5. ""دَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9126, 'دِيرَةٌ', 'ديرة', 'جامد', 'دور', 'ديرة', 'درة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"دِيرَةٌ-دِيرَةٌ [د و ر]. : ما اسْتَدارَ مِنَ الرَّمْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9127, 'مَدَارٌ', 'مدار', 'جامد', 'دور', 'مدار', 'مدر', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""مَدَارُ الأَرْضِ"" (فك) : مَسَارُهَا، أَيِ الفَلَكُ الَّذِي تَدُورُ عَلَيْهِ. 2.""مَدَارُ كَوْكَبٍ"" (فك) : مَسَارُهُ الَّذِي يَدُورُ عَلَيْهِ. 3.""مَدَارُ الجَدْيِ"" : خَطُّ عَرْضِ23', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9128, 'دَيْرٌ', 'دير', 'جامد', 'دور،دير', 'دير', 'در', '', '', '', 'مفرد', 'DnN', '', '', '"أَدْيِرَةٌ"', '', '', '', '', '', '', '', '', '". ""جَلَسَ الرَّاهِبُ في الدِّيرِ يَتَأَمَّلُ آياتِ الكِتابِ الْمُقَدَّسِ"" : مَقامُ الرُّهْبانِ والرَّاهِباتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9129, 'أَدْيِرَةٌ', 'أديرة', 'جامد', '', 'ءديرة', 'درة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9130, 'دَوْرَقٌ', 'دورق', 'جامد', '', 'دورق', 'درق', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَوارِقُ"', '', 'R', '', '', '', '', '', '', '"ج: دَوارِقُ. 1.""دَوْرَقُ الماءِ أَوِ الشَّرابِ"" : إِناءٌ مِنْ زُجاجٍ لَهُ عُرْوَتانِ وَلا بُلْبُلَةَ لَهُ. 2.""دَوْرَقُ الْمَخْبَرِ"" : زُجاجَةٌ ذاتُ عُنُقٍ طَويلٍ تُسْتَخْدَمُ في الْمَخابِرِ الكيماوِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9131, 'دَوارِقُ', 'دوارق', 'جامد', '', 'دوارق', 'درق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9132, 'دُورِيٌّ', 'دوري', 'جامد', '', 'دوري', 'در', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"دُورِيٌّ-دُورِيٌّ (حو). : طَيْرٌ مِنَ الجَواثِمِ، أَسْمَرُ مُخَطَّطٌ بِالأَسْوَدِ، يَكْثُرُ بِالْمُدُنِ وَيُعْرَفُ بالعُصْفورِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9133, 'دُوزانٌ', 'دوزان', 'جامد', '', 'دوزان', 'دزن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""وُضِعَ الدُّوزانُ بِجانِبِ آلَةِ البِيانُو"" : آلَةٌ لِضَبْطِ الآلاتِ الْمُوسيقِيَّةِ وَدَوْزَنَتِها."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9134, 'دَوَّاسَةٌ', 'دواسة', 'جامد', 'دوس', 'دواسة', 'دسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"دَوَّاسَةٌ-دَوَّاسَةٌ [د و س]. 1.""دَوَّاسَةُ النَّسَّاجِ"" : خَشَبَةٌ في أَسْفَلِ النَّوْلِ، يَدوسُها النَّسَّاج بِرِجْلِهِ لِتَتَفَتَّحَ الخُيوطُ. 2.""وَضَعَ رِجْلَهُ على دَوَّاسَة دَرَّاجَتِهِ وَانْطَلَقَ سَريعاً"" : مُحَرِّكٌ آلِيٌّ يَدورُ على نَفْسِهِ بِواسِطَةِ القَدَمَيْنِ يَدْفَعُ عَجَلَتَي الدَّراجَةِ. 3.""دَوَّاسَةُ البَيانُو"": رَافِعَةٌ حَديدِيَّةٌ تُدَاسُ بِالرِّجْلِ لِتَغْيِيرِ نَغَمـاتِ البَيانُـو. 4.""دَوَّاسَةُ البابِ"" : ما يوضَعُ عِنْدَ عَتَبَةِ البابِ لِمَسْحِ الأحْذِيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9135, 'مِدْوَاسٌ', 'مدواس', 'جامد', 'دوس', 'مدواس', 'مدس', '', '', '', 'مفرد', 'DnN', '', '', '"مَدَاوِسُ"', '', 'R', '', '', '', '', '', '', '". ن. مِدْوَسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9136, 'مَدَاوِسُ', 'مداوس', 'جامد', '', 'مداوس', 'مدس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9137, 'مِدْوَسٌ', 'مدوس', 'جامد', 'دوس', 'مدوس', 'مدس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِدْوَسٌ-مِدْوَسٌ [د و س]. 1.""مِدْوَسُ الدَّرَّاجَةِ "" : مُحَرِّكُهَا الَّذِي يُدْفَعُ بِالرِّجْلِ إِلَى الأَمَامِ وَهما مِدْوَسانِ. 2.""مِدْوَسُ الْحَصِيدِ"" : مَا يُدَاسُ بِهِ الْحَصِيدُ لِفَرْزِ الْحَبِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9138, 'دَالَةٌ', 'دالة', 'جامد', 'دول', 'دالة', 'دلة', '', '', '', 'مفرد', 'DnN', '', '', '"دَالٌ"', '', 'R', '', '', '', '', '', '', '".: الشُّهْرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9139, 'دَالٌ', 'دال', 'جامد', '', 'دال', 'دل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9140, 'دُولابٌ', 'دولاب', 'جامد', '', 'دولاب', 'دلب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَوالِيبُ"', '', 'R', '', '', '', '', '', '', '"ج: دَوالِيبُ. 1.""دَواليبُ الحَقْلِ أَوِ الحَوْضِ"" : الآلَةُ الَّتِي تُديرُها الدَّابَّةُ لِيُسْقَى بِها. 2.""أُصيبَ دُولابُ سَيَّارَتِهِ بِعَطَبٍ"" : إِطارُها، كُلُّ آلَةٍ تَدورُ حَوْلَ مِحْوَرٍ. 3.""أَخْرَجَتْ فُسْتانَها مِنَ الدُّولابِ"" : دُرْجٌ، صُنْدوقٌ مِنْ خَشَبٍ لِحِفْظِ الثِّيابِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9141, 'دَوالِيبُ', 'دواليب', 'جامد', '', 'دواليب', 'دلب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9142, 'دُولارٌ', 'دولار', 'جامد', '', 'دولار', 'دلر', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '": الوَرَقَةُ الخَضْراءُ وَهِيَ الوَحْدَةُ النَّقْدِيَّةُ الأَساسِيَّةُ لِعُمْلَةِ الوِلاياتِ الْمُتَّحِدَةِ الأَمْرِيكِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9143, 'دَوامٌ', 'دوام', 'جامد', 'دوم', 'دوام', 'دم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَوامٌ-دَوامٌ [د و م]. 1.""يُواصِلُ عَمَلَهُ على الدَّوامِ"" : دونَ انْقِطاعٍ، باسْتِمْرارٍ. ""تَجِدُهُ على الدَّوامِ مُنْكَبّاً على دُروسِهِ"". 2.""أَوْقاتُ الدَّوامِ بِالإِدارَةِ"" : ساعاتُ العَمَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9144, 'مُدَامٌ', 'مدام', 'جامد', 'دوم', 'مدام', 'مدم', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مُدَامٌ-مُدَامٌ، ةٌ [د و م].: الخَمْرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9145, 'مُدَوَّنَةٌ', 'مدونة', 'جامد', 'دون', 'مدونة', 'مدنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""مُدَوَّنَةُ الأَحْوَالِ الشَّخْصِيَّةِ"" : مَجْمُوعَةُ الأَحْكَامِ القَانُونِيَّةِ وَالفِقْهِيَّةِ الْمُتَعَلِّقَةِ بِتَنْظِيمِ الأُسْرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9146, 'دونَمٌ', 'دونم', 'جامد', '', 'دونم', 'دنم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": مِساحَةٌ مِنَ الأَرْضِ تُقَدَّرُ بِأَلْفِ مِتْرٍ مُرَبَّعٍ تَقْريباً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9147, 'دَواءٌ', 'دواء', 'جامد', 'دوي', 'دواء', 'د', '', '', '', 'مفرد', 'Dz', '', '', '"أَدْوِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '". ""سَلَّمَ لَهُ الطَّبِيبُ وَصْفَةَ دَواءٍ"" : مَوادُّ تُباعُ في الصَّيْدَلِيَّةِ تُصْنَعُ مِنَ النَّباتاتِ وَما إلى ذَلِكَ يُعالَجُ بِها الْمَريضُ مِنْ مَرَضِهِ. "" تَناوَلَ أَدْوِيَةً مُخْتَلِفَةً"" ""لِكُلِّ داءٍ دَواءٌ""(مثل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9148, 'أَدْوِيَةٌ', 'أدوية', 'جامد', '', 'ءدوية', 'دة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9149, 'دَواةٌ', 'دواة', 'جامد', 'دوي', 'دواة', 'دة', '', '', '', 'مفرد', 'DnN', '', '', '"دَوىً"', '', '', '', '', '', '', '', '', '". ""غَمَسَ ريشَةً في الدَّواةِ"" : قِنِّينَةٌ زُجاجِيَّةٌ يوضَعُ فيها الحِبْرُ، المِحْبَرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9150, 'دَوىً', 'دوى', 'جامد', '', 'دوى', 'د', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9151, 'دُوايَةٌ', 'دواية', 'جامد', 'دوي', 'دواية', 'دة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"دُوايَةٌ-دُوايَةٌ، دِوايَةٌ [د و ي]. ""عَلَتِ الدِّوايَةُ اللَّبَنَ"" : ما يَعْلوهُ مِنْ قِشْرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9152, 'دَوِيٌّ', 'دوي', 'جامد', 'دوي', 'دوي', 'د', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"دَوِيٌّ-دَوِيٌّ [د و ي]. 1.""سَمِعْنا مِنْ بَعيدٍ دَوِيَّ الْمَدافِعِ"" : أَيْ صَوْتَها. 2.""إِنَّ دَوِيَّ الرَّعْدِ يَهُزُّ مَشاعِرَنا وَنَحْنُ في الخَيْمَةِ"": جَلْجَلَةُ الرَّعْدِ. 3.""دَوِيُّ الأُذُنُ"" :طَنينُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9153, 'دَوٌّ', 'دو', 'جامد', 'دوي', 'دو', 'د', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"دَوٌّ-دَوٌّ [د وي].: الصَّحْراءُ الشَّاسِعَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9154, 'ديباجٌ', 'ديباج', 'جامد', '', 'ديباج', 'دبج', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَبابيجُ:دَيابيجُ"', '', 'R', '', '', '', '', '', '', '"ج: دَبابيجُ، دَيابيجُ. ""تَرْتَدِي قَميصاً مِنْ دِيباجِ"" : نَسيج مِنَ الحَريرِ الأَصيلِ، مُلَوَّنٌ أَلْواناً مُخْتَلِفَةً. ""هَلْ تَبْكِي الطَّبيعَةُ أَيُّها القَمَرُ فَتَكونُ أَنْتَ في ديباجِ السَّماءِ""(م. ص. الرافعي)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9155, 'دَبابيجُ', 'دبابيج', 'جامد', '', 'دبابيج', 'دببج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9156, 'دَيابيجُ', 'ديابيج', 'جامد', '', 'ديابيج', 'دبج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9157, 'دِيباجَةٌ', 'ديباجة', 'جامد', '', 'ديباجة', 'دبجة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"1.""دِيباجَةُ الوَجْهِ"" : حُسْنُ بَشَرَتِهِ. ""أَطَلَّ بِديباجَةِ وَجْهِهِ"". 2.""قَرَأَ دِيباجَةَ الكِتابِ"" : الْمُقَدِّمَةُ، الفاتِحَةُ، الْمَدْخَلُ الَّذِي يَسْتهِلُّ بِهِ الكاتِبُ كِتابَهُ. 3.""لِكَلامِهِ دِيباجَةٌ حَسَنَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9158, 'ديسٌ', 'ديس', 'جامد', '', 'ديس', 'دس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ديسٌ-ديسٌ (نب).: نَباتٌ مِنْ فَصيلَةِ النَّجْلِيَّاتِ، مُعَمِّرٌ، يَكْثُرُ في المناطِقِ الرَّطْبَةِ والمائِيَّةِ، تُصْنَعُ مِنْ أَلْيافِهِ الحُصُرُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9159, 'ديسمبر', 'ديسمبر', 'جامد', '', 'ديسمبر', 'دسمبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ الثَّانِي عَشَرَ مِنَ الشُّهورِ الغَرْبِيَّةِ عدد أَيَّامِهِ (31) يَوْماً. وَهُوَ ما يُقابِلُ كانون الأَوّل."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9160, 'دِيكٌ', 'ديك', 'جامد', 'ديك', 'ديك', 'دك', '', '', '', 'مفرد', 'DnN', '', '', '"دُيوكٌ:دِيَكَةٌ:أَدْياكٌذَكَر', '', 'R', '', '', '', '', '', '', '"دِيكٌ-دِيكٌ (حو). ج: دُيوكٌ، دِيَكَةٌ، أَدْياكٌ.[د ي ك]. 1.:ذَكَرُ الدَّجاجِ. 2.""الدِّيكُ الرُّومِيُّ"": طائِـرٌ مِـنْ رُتْبَـةِ الدَّجاجِيَّاتِ، "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9161, 'دُيوكٌ', 'ديوك', 'جامد', '', 'ديوك', 'دك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
