INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9163, 'أَدْياكٌ', 'أدياك', 'جامد', '', 'ءدياك', 'دك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9164, 'ديمَةٌ', 'ديمة', 'جامد', 'ديم', 'ديمة', 'دمة', '', '', '', 'مفرد', 'DnN', '', '', '"دِيَمٌ:دُيومٌ"', '', 'R', '', '', '', '', '', '', '". ""مَطَرَتِ السَّماءُ ديمَةً"": مَطراً يَدومُ سُقوطُهُ بِلا رَعْدٍ وَلا بَرْقٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9165, 'دِيَمٌ', 'ديم', 'جامد', '', 'ديم', 'دم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9166, 'دُيومٌ', 'ديوم', 'جامد', '', 'ديوم', 'دم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9167, 'دِيماسٌ', 'ديماس', 'جامد', '', 'ديماس', 'دمس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَيامِيسُ:دَمامِيسُ"', '', 'R', '', '', '', '', '', '', '"ج: دَيامِيسُ، دَمامِيسُ. ""وَضَعَ سَيَّارَتَهُ في الدِّيماسِ"" : بِناءٌ أَرْضِيّ"', ':لا جذر:لا مفرد');
