INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9169, 'دَمامِيسُ', 'دماميس', 'جامد', '', 'دماميس', 'دممس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9170, 'دَيَّانٌ', 'ديان', 'جامد', 'دين', 'ديان', 'دن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"دَيَّانٌ-دَيَّانٌ [د ي ن]. ""هُوَ الدَّيَّانُ"" : اللَّهُ عَزَّ وَجَلَّ وَهُوَ مِنَ الأَسْماءِ الحُسْنَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9171, 'دينَةٌ', 'دينة', 'جامد', 'دين', 'دينة', 'دنة', '', '', '', 'مفرد', 'DnN', '', '', '"دِينٌ"', '', 'R', '', '', '', '', '', '', '". 1.""يَلْتَزِمُ بِقَواعِدِ الدِّينَةِ"" : قَواعِدِ الدِّينِ، العِبادَةِ. 2.""يَرْغَبُ في دِينَتِهِ"" : في طاعَتِهِ. 3.""اِتَّفَقَ مَعَهُ على دينَةٍ"" : على دَيْنٍ، قَرْضٍ لأَجَلٍ مُعَيَّنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9172, 'دِينٌ', 'دين', 'جامد', '', 'دين', 'دن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9173, 'دَيْنونَةٌ', 'دينونة', 'جامد', 'دين', 'دينونة', 'دننة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"دَيْنونَةٌ - [د ي ن]. ""يَوْمُ الدَّيْنونَةِ"" : يَوْمُ الدِّينِ، يَوْمُ الحِسابِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9174, 'دِينارٌ', 'دينار', 'جامد', '', 'دينار', 'دنر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَنانيرُ"', '', 'R', '', '', '', '', '', '', '"ج: دَنانيرُ: ضَرْبٌ مِنَ العُمْلَةِ النَّقْدِيَّةِ الذَّهَبِيَّةِ، وَهُوَ الآنَ الوَحْدَةُ النَّقْدِيَّةُ لِلْعُمْلَةِ الجَزائِرِيَّةِ والتُّونُسِيَّةِ والعِراقِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9175, 'دَنانيرُ', 'دنانير', 'جامد', '', 'دنانير', 'دننر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9176, 'دِيناصورٌ', 'ديناصور', 'جامد', '', 'ديناصور', 'دنصر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"دِيناصورٌ-دِيناصورٌ (حو).: مِنَ الزَّواحِفِ الْمُنْقَرِضَةِ مِنَ العُصورِ القَديمَةِ، ضَخْمُ الجِسْمِ، صَغيرُ الدِّماغِ، يُقالُ بِأَنَّهُ أَضْخَمُ مِنَ الفيلِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9177, 'دينامو', 'دينامو', 'جامد', '', 'دينامو', 'دنم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '": جِهازٌ يُحَوِّلُ الطَّاقَةَ الميكانِيكِيَّةَ إلى طاقَةٍ كَهْرَبائِيَّةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9178, 'دينامِيتٌ', 'ديناميت', 'جامد', '', 'ديناميت', 'دنمت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": مادَّةٌ مُتَفَجِّرَةٌ، مَعْناها الأَصْلِيُّ بِاليونانِيَّةِ القُوَّةُ الشَّديدَةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9179, 'ديناميكٌ', 'ديناميك', 'جامد', '', 'ديناميك', 'دنمك', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', 'N', 'O', 'N', 'O', '', '": عِلْمٌ يَبْحَثُ في الحَرَكَةِ بِمَعْناها العامِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9180, 'دِيوانٌ', 'ديوان', 'جامد', '', 'ديوان', 'دن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"دَواوينُ"', '', 'R', '', '', '', '', '', '', '"ج: دَواوينُ. 1.""ديوانُ شِعْرٍ"" :كِتابٌ تُجْمَعُ فيهِ قَصائِدُ شاعِرٍ أَوْ شُعَراءَ. ""قَصائِدُ كُنْتُ أَكْتُبُها في دَواوينِي"". (بدر شاكر السياب). 2.""ديوانُ الجُنودِ"" : السِّجِلُّ تُكْتَبُ فيهِ أَسْماءُ الجُنودِ وَأَماكِنُ وُجودِهِمْ، وَما يَتَقاضَوْنَهُ مِنْ مَعاش"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9181, 'دَواوينُ', 'دواوين', 'جامد', '', 'دواوين', 'دن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9182, 'ذُؤابَةٌ', 'ذؤابة', 'جامد', 'ذأب', 'ذءابة', 'ذبة', '', '', '', 'مفرد', 'DnN', '', '', '"ذَوائِبُ"', '', 'R', '', '', '', '', '', '', '". 1.""ذُؤابَةُ قَوْمِهِ"" : شَرِيفُهُمْ والْمُقَدَّمُ فيهِمْ. 2.""شَعْبٌ في ذُؤابَةِ الْمَجْدِ"" : في قِمَّتِهِ. 3.""ذُؤابَةُ الأَسَدِ"" : شَعْرُ مُقَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9183, 'ذَوائِبُ', 'ذوائب', 'جامد', '', 'ذواءب', 'ذب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9184, 'ذُؤْبانٌ', 'ذؤبان', 'جامد', 'ذأب', 'ذءبان', 'ذبن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ذُؤْبانٌ-ذُؤْبانٌ [ذ أ ب]. ""ذُؤْبانُ العَرَبِ"" : لُصوصُهُمْ وَصَعالِيكُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9185, 'ذُؤافٌ', 'ذؤاف', 'جامد', 'ذأف', 'ذءاف', 'ذف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ذُؤافٌ-ذُؤافٌ [ذ أ ف]. 1.""سَقاهُ الذُّؤافَ"" : الزُّعاف، السُّمَّ القاتِلَ. 2.""مَوْتٌ ذُؤافٌ"" : مَوْتٌ سَريعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9186, 'ذُبابٌ', 'ذباب', 'جامد', '', 'ذباب', 'ذبب', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حش). 1.: حَشَرَةٌ مِنْ فَصيلَةِ الذُّبابِيَّاتِ، مِنْ رُتْبَةِ ذَاتِ الجَناحَيْنِ، وَهِيَ مُتَعَدِّدَةُ الأَنْواعِ، مِنها الزَّنابِيرُ والبَعوضُ، وَذُبابَةُ البُيوتِ تَتَغَذَّى بِالقاذُوراتِ وَتَنْقُلُ الأَمْراضَ. 2.""ذُبابَةُ الخَيْلِ"": حَشَرَةٌ مِنَ الذُّبابِيَّاتِ تَعيشُ في الإِصْطَبْلاتِ وَتَلْصَقُ في دُبُرِ الخَيْلِ والأَبْقارِ وَتَنْقُلُ الأَمْراضَ. 3.""الذُّبابَةُ الحَلَزونِيَّةُ"" : ذ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9187, 'ذُبالَةٌ', 'ذبالة', 'جامد', '', 'ذبالة', 'ذبلة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"ذُبالٌ"', '', 'R', '', '', '', '', '', '', '"ج: ذُبالٌ. ""ذُبالَةُ القِنْديلِ"" : فَتيلَتُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9188, 'ذُبالٌ', 'ذبال', 'جامد', '', 'ذبال', 'ذبل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9189, 'ذِبْحَةٌ', 'ذبحة', 'جامد', 'ذبح', 'ذبحة', 'ذبحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ذِبْحَةٌ-ذِبْحَةٌ [ذ ب ح] (طب). 1: أَلَمٌ يُحْدِثُ اخْتِناقاً في الصَّدْرِ. 2.""الذِّبْحَةُ الصَّدْرِيَّةُ"" : مَرَضٌ يُعَرِّضُ صاحِبَهُ لأَلَمٍ في جِهَةِ القَلْبِ مِنَ الصَّدْرِ، يَنْتَهِي بِالْمَوْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9190, 'ذَبيحَةٌ', 'ذبيحة', 'جامد', 'ذبح', 'ذبيحة', 'ذبحة', '', '', '', 'مفرد', 'DnN', '', '', '"ذَبائِحُ"', '', '', '', '', '', '', '', '', '".: ما يُذْبَحُ مِنَ الأَنْعامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9191, 'ذَبائِحُ', 'ذبائح', 'جامد', '', 'ذباءح', 'ذبح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9192, 'مَذْبَحَةٌ', 'مذبحة', 'جامد', 'ذبح', 'مذبحة', 'مذبحة', '', '', '', 'مفرد', 'DnN', '', '', '"مَذَابِحُ"', '', 'R', '', '', '', '', '', '', '". ""مَذْبَحَةٌ لَمْ يَعْرِفْ لَهَا التَّارِيخُ مَثِيلاً"" : حَادِثَةٌ فِي مَكَانٍ مَّا تَمَّ فِيهَا ذَبْحُ عَدَدٍ كَبِيرٍ مِنَ النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9193, 'مَذَابِحُ', 'مذابح', 'جامد', '', 'مذابح', 'مذبح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9194, 'مَذْبَحٌ', 'مذبح', 'جامد', 'ذبح', 'مذبح', 'مذبح', '', '', '', 'مفرد', 'DnN', '', '', '"مَذَابِحُ"', '', 'R', '', '', '', '', '', '', '". 1.: مَكَانُ الذَّبْحِ، الْمَسْلَخُ. 2.""مَذْبَحُ الكَنِيسَةِ"" : الْمَوْضِعُ الَّذِي يُقِيمُ عَلَيْهِ الكَهَنَةُ القُدَّاسَ الإِلَهِيَّ، بَيْتُ كُتُبِ الكَنِيسَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9195, 'مَذَابِحُ', 'مذابح', 'جامد', '', 'مذابح', 'مذبح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9196, 'ذَبْلٌ', 'ذبل', 'جامد', 'ذبل', 'ذبل', 'ذبل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ذَبْلٌ-ذَبْلٌ [ذ ب ل]. 1.""ذَبْلُ السُّلَحْفاةِ"" : جِلْدُها الَّذِي يُتَّخَذُ مِنْهُ السِّوارُ والأَمْشاطُ. 2.""وَلَدٌ في ذَبْلِهِ"" : في أَوَّلِ شَبابِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9197, 'ذُخْرٌ', 'ذخر', 'جامد', 'ذخر', 'ذخر', 'ذخر', '', '', '', 'مفرد', 'DnN', '', '', '"أَذْخارٌ"', '', 'R', '', '', '', '', '', '', '".: ما يُذَّخَرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9198, 'أَذْخارٌ', 'أذخار', 'جامد', '', 'ءذخار', 'ذخر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9199, 'ذَخيرَةٌ', 'ذخيرة', 'جامد', 'ذخر', 'ذخيرة', 'ذخرة', '', '', '', 'مفرد', 'DnN', '', '', '"ذَخائِرُ"', '', '', '', '', '', '', '', '', '". 1.""نَفِدَتِ الذَّخيرَةُ في عِزِّ الْمَعْرَكَةِ"" : عُدَّةُ الحَرْبِ مِنْ أَسْلِحَةٍ وَقَذائِفَ وَرَصاصٍ. 2.""ذَخيرَةٌ لأَيَّامِ العُسْرِ"" : الذُّخْرُ، أَيْ ما يُذَّخَرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9200, 'ذَخائِرُ', 'ذخائر', 'جامد', '', 'ذخاءر', 'ذخر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9201, 'ذُرّاجِيّاتٌ', 'ذراجيات', 'جامد', '', 'ذراجيات', 'ذرجت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"فَصيلَةٌ مِنْ رُتْبَةِ غِمْدِيّاتِ الأَجْنِحَةِ، أَنْواعُها عَديدَةٌ وَهَذِهِ الفَصيلَةُ مِنَ الحَشَراتِ أَغْلَبُها صَغيرُ القَدِّ، وَلَها أَجْسامٌ مُسْتَطيلَةٌ، وَأَغْمادُها ضَعيفَة."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9202, 'ذَرارِيٌّ', 'ذراري', 'جامد', '', 'ذراري', 'ذرر', '', '', '', 'جمع تكسير', '', '', '', '"مفردذُرِّيَّة"', '', '', '', '', '', '', '', '', '"جمع ذُرِّيَّة. ن.ذُرِّيَّة."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9203, 'ذَرَبٌ', 'ذرب', 'جامد', 'ذرب', 'ذرب', 'ذرب', '', '', '', 'مفرد', 'DnN', '', '', '"أَذْرابٌ"', '', 'R', '', '', '', '', '', '', '". 1.""ذَرَبُ اللِّسانِ"" : بَذاءَتُهُ. 2.""بِهِ ذَرَبٌ"" : مَرَضٌ يَعْرِضُ لِلْمَعِدَةِ فَلا تَهْضِمُ الطَّعامَ وَيَفْسُدُ فيها ولا تُمْسِكُهُ. 3.""ذَرَبُ الإِناءِ"" : صَدَأُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9204, 'أَذْخارٌ', 'أذخار', 'جامد', '', 'ءذخار', 'ذخر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9205, 'ذِرْبٌ', 'ذرب', 'جامد', 'ذرب', 'ذرب', 'ذرب', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"ذِرْبٌ-ذِرْبٌ، ةٌ [ذ ر ب]. 1.""وَلَدٌ ذِرْبٌ"" : سَليطُ اللِّسانِ. 2.""أُصيبَ في كَبِدِهِ بِذِرْبٍ"" : مَرَضٌ يُصيبُ الكَبِدَ. 3.""أُصيبَ عُنُقُهُ بِذِرْبٍ"" : وَرَمٌ يَكونُ في عُنُقِ الإِنْسانِ أو البَعيرِ يُشْبِهُ الحَصاةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9206, 'ذُرَّاحٌ', 'ذراح', 'جامد', 'ذرح', 'ذراح', 'ذرح', '', '', '', 'مفرد', 'DnN', '', '', '"ذَراريحُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '".: حَشَرَةٌ مِنْ فَصيلَةِ الذّرَّاحيّاتِ، أَنْواعُها عَديدَةٌ، حَمْراءُ اللَّوْنِ، مُبَرْقَعَةٌ بِالأَسْوَدِ، تَطيرُ، تُسْتَعْمَلُ طِبِّيّاً، إِذْ تُسْحَقُ وَتُجَفَّفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9207, 'ذَرارَةٌ', 'ذرارة', 'جامد', 'ذرر', 'ذرارة', 'ذررة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ذَرارَةٌ-ذَرارَةٌ [ذ ر ر].: ما تَناثَرَ مِنَ الشَّيْءِ الْمَذْرورِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9208, 'ذَرَّةٌ', 'ذرة', 'جامد', 'ذرر', 'ذرة', 'ذرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"واحدةذَرٌّ"', '', 'R', '', '', '', '', '', '', '"(كيما). 1.""تَناثَرَ الذَّرُّ"" : الهَباءُ الْمُنْتَشِرُ في الهَواءِ. 2.""مِثْقالُ ذَرَّةٍ"" : أَقَلُّ شَيْءٍ، مالاَ قيمَةَ لَهُ.النساء آية 40 إِنَّ اللَّهَ لاَ يَظْلِمُ مِثْقالَ ذَرَّةٍ (قرآن) ""مِقْدارُ ذَرَّةٍ"" ""ذَرَّةٌ مِنَ الشَّكِّ"". 3.""الذَّرَّةُ"" : أَصْغَرُ جُزْءٍ مِنْ أَجْزاءِ عُنْصُرٍكيمِيائِيٍّ، وَهُوَ مُتَناهٍ في الصِّغَرِ، يَدْخُلُ في تَفاعُلاتٍ، وَتُعَدُّ المادَّةُ اليَوْمَ تَراكُماً مِنْ جُزْئِيَّاتِ الطَّاقَةِ الْمُكَثَّفَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9209, 'ذَرورٌ', 'ذرور', 'جامد', 'ذرر', 'ذرور', 'ذرر', '', '', '', 'مفرد', 'DnN', '', '', '"أَذِرَّةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""ذَرورُ العَيْنِ أَوِ الجُرْحِ"" : ما يُذَرُّ في العَيْنِ أَوْ على الجُرْحِ مِنْ دَواءٍ يابِسٍ. 2.""ذَرورُ الطَّعامِ"" : ما يُذَرُّ على الطَّعامِ مِنْ مِلْحٍ مَسْحوقٍ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9210, 'أَذِرَّةٌ', 'أذرة', 'جامد', '', 'ءذرة', 'ذرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9211, 'ذُرِّيَّةٌ', 'ذرية', 'جامد', 'ذرر', 'ذرية', 'ذرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":ذَرارِيٌّ"', '', '', '', '', '', '', '', '', '". 1.""ذُرِّيَّةُ الرَّجُلِ"" : وَلَدُهُ، نَسْلُهُ. ""ذُرِّيَّةٌ صالِحَةٌ"". 2. لا تَقْتُلْ ذُرِّيَّةً وَلا عسيفاً (حديث) : النِّساءُ والصِّغارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9212, 'ذَرارِيٌّ', 'ذراري', 'جامد', '', 'ذراري', 'ذرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9213, 'ذَريعَةٌ', 'ذريعة', 'جامد', 'ذرع', 'ذريعة', 'ذرعة', '', '', '', 'مفرد', 'DnN', '', '', '"ذَرائِعُ"', '', '', '', '', '', '', '', '', '". ""يَبْحَثُ عنْ ذَريعَةٍ يَسْتَنِدُ إِلَيْها"" :حُجَّة، وَسيلَة. ""هُوَ ذَريعَتِي إلى الرَّئِيسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9214, 'ذَرائِعُ', 'ذرائع', 'جامد', '', 'ذراءع', 'ذرع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9215, 'مَذَارِفُ', 'مذارف', 'جامد', 'ذرف', 'مذارف', 'مذرف', '', '', '', 'مفرد', '', '', '', '"مفردمَذْرَف"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""سَالَتْ مَذَارِفُهُ"" : مَدَامِعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9216, 'مَذْرَف', 'مذرف', 'جامد', '', 'مذرف', 'مذرف', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9217, 'ذُرَقٌ', 'ذرق', 'جامد', 'ذرق', 'ذرق', 'ذرق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ذَرْقٌ-ذَرْقٌ [ذ ر ق] (مص. ذَرَقَ). ""ذَرْقُ الطَّائِرِ"" : سَلْحُهُ، خُرْؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9218, 'ذُراوَةٌ', 'ذراوة', 'جامد', 'ذرو', 'ذراوة', 'ذرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"ذُراوَةٌ-ذُراوَةٌ [ذ ر و]. 1.""ذُراوَةُ الحِنْطَةِ"" : ما يَسْقُطُ عِنْدَ التَّذْرِيَةِ. 2.""ذُراوَةُ التُّرابِ"" : ما ذَرَتْهُ الرِّيحُ وفَرَّقَتْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9219, 'ذُرَةٌ', 'ذرة', 'جامد', 'ذرو', 'ذرة', 'ذرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"ذُرَةٌ-ذُرَةٌ [ذ ر و] (نب).: نَباتٌ مِنَ النَّجْلِيَّاتِ، زِراعِيٌّ، أَمْريكِيُّ الأَصْلِ، ثِمارُهُ حُبوبٌ بِيضٌ أَوْ صُفْرٌ، تُؤْكَلُ مَسْلوقَةً أَوْ مُحَمَّصَةً، كَما أَنَّها تُطْحَنُ لِيُتَّخَذَ مِنْها الخُبْزُ، أَوْ بَعْضُ أَنْواعِ العَصيدَةِ، أَوِ الحَريرةِ، كَما يُقَدَّمُ عَلَفاً لِلْحَيَواناتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9220, 'ذُرْوَةٌ', 'ذروة', 'جامد', 'ذرو', 'ذروة', 'ذرة', '', '', '', 'مفرد', 'DnN', '', '', '"ذُرًى:ذِرًى"', '', 'R', '', '', '', '', '', '', '". 1.""ذِرْوَةُ الجَبَلِ"" : أَعْلاهُ، قِمَّتُهُ. ""في ذِرْوَةِ مَجْدِهِ"" ""في ذِرْوَةِ غَضَبِهِ"". 2.""مُؤْتَمَرُ الذِّرْوَةِ"" : مُؤْتَمَرُ القِمَّةِ الَّذِي يَجْتَمِعُ فيهِ رُؤَساءُ الدُّوَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9221, 'ذُرًى', 'ذرى', 'جامد', '', 'ذرى', 'ذر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9222, 'ذِرًى', 'ذرى', 'جامد', '', 'ذرى', 'ذر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9223, 'مِذْرَاةٌ', 'مذراة', 'جامد', 'ذرو', 'مذراة', 'مذرة', '', '', '', 'مفرد', 'DnN', '', '', '"مَذَارٍ"', '', '', '', '', '', '', '', '', '".: خَشَبَةٌ مُتَفَرِّعَةُ ذَاتُ أَطْرَافٍ كَالأَصَابِعِ تُذَرَّى بِهَا الحِنْطَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9224, 'مَذَارِي', 'مذاري', 'جامد', '', 'مذاري', 'مذر', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9225, 'ذارِيَةٌ', 'ذارية', 'جامد', 'ذري', 'ذارية', 'ذرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""هَبَّتِ الذَّارِيَةُ"" : الرِّيحُ. الذاريات آية 1 وَالذَّارِيَاتِ ذَرْواً (قرآن). 2.: سُورَةٌ مِنْ سُوَرِ القُرْآنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9226, 'ذُرَى', 'ذرى', 'جامد', 'ذري', 'ذرى', 'ذر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"ذُرَى-ذُرَى [ذ ر ي]. 1.: اِسْمٌ لِما ذَرَتْهُ الرِّيحُ. 2.""ذُرَى الدَّمْعِ"": ما انْصَبَّ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9227, 'ذَرَى', 'ذرى', 'جامد', 'ذري', 'ذرى', 'ذر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"ذَرَى-ذَرَى، ذَرا [ذ ر ي].: ما اسْتُتِرَ بِهِ. 1.""هُوَ في ذَرا أُسْرَةٍ كَريمَةٍ"" : في كَنَفِها. 2.""ذَرا الدَّمْعِ"" : ما انْصَبَّ مِنْهُ. 3.""هُوَ كَريمُ الذَّرا"" : كَريمُ الطَّبيعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9228, 'ذُعَرٌ', 'ذعر', 'جامد', 'ذعر', 'ذعر', 'ذعر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ذُعَرٌ-ذُعَرٌ [ذ ع ر]. ""أَمْرٌ ذُعَرٌ"" : يُخَافُ، يُفْزَعُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9229, 'ذُعْرٌ', 'ذعر', 'جامد', 'ذعر', 'ذعر', 'ذعر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ذُعْرٌ-ذُعْرٌ [ذ ع ر]. ""دَبَّ الذُّعْرُ إلى نَفْسِهِ"" : الخَوْفُ. ""ماتَ مِنَ الذُّعْرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9230, 'ذُعافٌ', 'ذعاف', 'جامد', 'ذعف', 'ذعاف', 'ذعف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ذُعافٌ-ذُعافٌ [ذ ع ف]. 1.""سُمٌّ ذُعافٌ"" : سُمٌّ زُعافٌ، سُمٌّ يَقْتُلُ مِنْ ساعَتِهِ. 2.""مَوْتٌ ذُعافٌ"" : مَوْتٌ سَريعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9231, 'ذِفْرَى', 'ذفرى', 'جامد', 'ذفر', 'ذفرى', 'ذفر', '', '', '', 'مفرد', 'Dy', '', '', '"ذَفارَى:ذِفْرَياتٌ"', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '".: العَظْمُ الْمَوْجودُ خَلْفَ الأُذُنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9232, 'ذَفارَى', 'ذفارى', 'جامد', '', 'ذفارى', 'ذفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9233, 'ذِفْرَياتٌ', 'ذفريات', 'جامد', '', 'ذفريات', 'ذفرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9234, 'ذُفافٌ', 'ذفاف', 'جامد', 'ذفف', 'ذفاف', 'ذفف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ذُفافٌ-ذُفافٌ [ذ ف ف]. 1.""وَلَدٌ ذُفافٌ"" : سَريعٌ خَفيفٌ. 2.""سَقاهُ ذُفافاً"" : سُمّاً قاتِلاً. 3.""ماءٌ ذُفافٌ"" : ماءٌ قَليلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9235, 'ذاقِنَةٌ', 'ذاقنة', 'جامد', 'ذقن', 'ذاقنة', 'ذقنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"ذاقِنَةٌ-ذاقِنَةٌ [ذ ق ن].: ما تَحْتَ الذَّقَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9236, 'ذَقَنٌ', 'ذقن', 'جامد', '', 'ذقن', 'ذقن', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ج: أَذْقانٌ. (مُذَكَّرٌ).: مُجْتَمَعُ اللَّحْيَيْنِ، أَيْ مَنْبِتُ شَعَرِ اللَّحْيَةِ مِنْ أَسْفَلِها."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9237, 'تَذْكِرَةٌ', 'تذكرة', 'جامد', 'ذكر', 'تذكرة', 'تذكرة', '', '', '', 'مفرد', 'DnN', '', '', '"تَذَاكِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""تَذْكِرَةُ السَّفَرِ"" : بِطَاقَةٌ خَاصَّةٌ مُرَقَّمَةٌ تَسْمَحُ بِرُكُوبِ القِطَارِ أَوِ الطَّائِرَةِ أَوْ أَيِّ وَسيِلَةٍ أُخْرَى مِنْ وَسَائِلِ النَّقْلِ. 2.""وَقَفَ يَنْتَظِرُ دَوْرَهُ أَمَامَ شُبَّاكِ التَّذَاكِرِ"" : مَكَانُ شِرَاءِ البَطَائِقِ الـخَاصَّةِ بِقَاعَاتِ السِّينِمَا أَوِ الْمَسْرَحِ وَنَحْوِهِمَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9238, 'تَذَاكِرُ', 'تذاكر', 'جامد', '', 'تذاكر', 'تذكر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9239, 'ذاكِرَة', 'ذاكرة', 'جامد', 'ذكر', 'ذاكرة', 'ذكرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '"ذاكِرَة-ذاكِرَةٌ [ذ ك ر]. ""لَهُ ذاكِرَةٌ قَوِيَّةٌ"" : قُوَّةٌ عِنْدَ النَّاسِ تَحْفَظُ الأَشْياءَ في الذِّهْنِ وَتُعيدُ إِحْياءها عِنْدَ الاقْتِضاءِ. ""ذاكِرَةُ الشُّعوبِ لا تَموتُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9240, 'ذَكَرٌ', 'ذكر', 'جامد', 'ذكر', 'ذكر', 'ذكر', '', '', '', 'مفرد', 'DnN', '', '', '"ذُكورٌ:ذُكورَةٌ:ذُكْرانٌ"', '', 'R', '', '', '', '', '', '', '". 1. : كُلُّ عُضْوٍ مُذَكَّرٍ، أَيْ خِلافُ الأُنْثَى. الحجرات آية 13 يا أَيُّها النَّاسُ إِنَّا خَلَقْناكُمْ مِنْ ذَكَرٍ وَأُنْثَى . (قرآن). 2.""ذَكَرُ الرَّجُلِ"" : قَضيبُهُ، عُضْوُهُ التَّناسُلِيُّ. 3.""نَخْلٌ ذَكَرٌ"" : نَخْلٌ لا يُثْمِرُ. 4.""حَديدٌ ذَكَرٌ"" : حَديدٌ مِنْ مَعْدِنٍ جَيِّدٍ. 5.""نُحاسٌ ذَكَرٌ"" : نُحاسٌ مِنْ مَعْدِنٍ رَديءٍ. 6.""ذُكورُ البَقْلِ"" : بَقْلٌ طَعْمُهُ مُرٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9241, 'ذُكورٌ', 'ذكور', 'جامد', '', 'ذكور', 'ذكر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9242, 'ذُكورَةٌ', 'ذكورة', 'جامد', '', 'ذكورة', 'ذكرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9243, 'ذُكْرانٌ', 'ذكران', 'جامد', '', 'ذكران', 'ذكرن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9244, 'ذُكْرٌ', 'ذكر', 'جامد', 'ذكر', 'ذكر', 'ذكر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ذِكْرٌ-ذِكْرٌ [ذ ك ر] (مص. ذَكَرَ). 1.""ما زالَ في ذِكْرِهِ ما حَدَثَ"" : ما يُحْفَظُ في الذَّاكِرَةِ مِنَ حَوادِثَ أَوْ مُخْتَلِفِ الصُّوَرِ. 2.""رَجُلٌ مَنْسِيُّ الذِّكْرِ"" : لا شَأْنَ لَهُ، مُهْمَلٌ. 3.""لَهُ ذِكْرٌ حَسَنٌ"" : صِيتٌ، مَقامٌ. ""لَهُ ذِكْرٌ في النَّاسِ"" "" لَهُ ذِكْرٌ شَيْءٌ"". 4.""أَشادَ بِذِكْرِهِ"" : نَوَّهَ بِهِ، أَثْنَى عَلَيْهِ. 5.""أَمْرٌ لاَ بُدَّ مِنْ ذِكْرِهِ"" : مِنَ الإِشارَةِ إِلَيْهِ. ""حَسَبَ ما تَمَّ ذِكْرُهُ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9245, 'ذِكْرَى', 'ذكرى', 'جامد', 'ذكر', 'ذكرى', 'ذكر', '', '', '', 'مفرد', 'Dy', '', '', '"ذِكْرَياتٌ"', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '". 1""يَحْتَفِظُ بِذِكْرَى جَميلَةٍ مِنْ أَيَّامِ الصِّبا"" : جَرَيانُ ذِكْرِ شَيْءٍ حَدَثَ في الماضِي بِاللِّسانِ أَوْ حُضورُهُ في البالِ. ""جَلَسَ خَلْفَ الشُّبَّاكِ يَسْتَعْرِضُ ذِكْرَياتِهِ الماضِيَةَ"". 2.""اِحْتَفَلَ الشَّعْبُ بِذِكْرَى عيدِ الاسْتِقْلالِ"" : يَوْم حُصولِهِ على الاِسْتِقْلالِ. ""الذِّكْرَى السَّنَوِيَّةُ"" ""ذِكْرَى وَطَنِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9246, 'ذِكْرَياتٌ', 'ذكريات', 'جامد', '', 'ذكريات', 'ذكرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9247, 'مُذَكِّرَةٌ', 'مذكرة', 'جامد', 'ذكر', 'مذكرة', 'مذكرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""الْمُذَكِّرَةُ السَّنَوِيَّةُ"" : كُتَيِّبُ صَغِيرٌ يَتَضَمَّنُ أَسْمَاءَ الشُّهُورِ مُرَتَّبَةً حَسَبَ الأَيَّامِ وَالأَسَابِيعِ، رُزْمَانَة. 2.""مُذَكِّرَةُ الجَيْبِ"" : دَفْتَرٌ صَغِيرٌ يُدَوَّنُ فِيهِ مَا يَنْبَغِي تَذَكُّرُهُ؛ مَوَاعِيدُ، عَنَاوِينُ. 3.""مُذَكِّرَاتُ كَاتِبٍ"" : يَوْمِيَّاتُهُ وَمَا يَكْتُبُهُ مِنْ خَوَاطِرَ. ""دَف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9248, 'ذُكْرَةٌ', 'ذكرة', 'جامد', 'ذكر', 'ذكرة', 'ذكرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"ذُكْرَةٌ-ذُكْرَةٌ [ذ كـ ر]. 1.""وَضَعَ الذُّكْرَةَ في رَأْسِ السَّيْفِ"": قِطْعَةٌ مِنْ فولاذٍ تُزادُ في رَأْسِهِ. 2.""لَهُ ذُكْرَةٌ حَسَنَةٌ"" : صيتٌ. 3.""ذُكْرَةُ رَجُلٍ"" : حِدَّتُهُ. ""ذُكْرَةُ سَيْفٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9249, 'ذُكورَةٌ', 'ذكورة', 'جامد', 'ذكر', 'ذكورة', 'ذكرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"ذُكورَةٌ-ذُكورَةٌ [ذ كـ ر].: صِفَةُ الذَّكَرِ، خِلافُ الأُنوثَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9250, 'ذُكاءٌ', 'ذكاء', 'جامد', 'ذكو', 'ذكاء', 'ذك', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"ذُكاءٌ-ذُكاءٌ [ذ ك و]. 1.: الشَّمْسُ. 2.""اِبْنُ ذُكاءٍ"" : الصُّبْحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9251, 'ذَكْوَةٌ', 'ذكوة', 'جامد', '', 'ذكوة', 'ذكة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"""رَمَى ذَكْوَةً على النَّارِ لِيَشْتَدَّ لَهيبُها"" : ما يُرْمَى على النَّارِ لِتُذْكَى بِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9252, 'ذَكاةٌ', 'ذكاة', 'جامد', 'ذكي', 'ذكاة', 'ذكة', '', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"ذَكاةٌ-ذَكاةٌ [ذ ك ي].: الذَّبْحُ، النَّحْرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9253, 'ذُلْذُلٌ', 'ذلذل', 'جامد', 'ذلذل', 'ذلذل', 'ذلذل', '', '', '', 'مفرد', 'DnN', '', '', '"ذَلاذِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""لَبِسَ ذُلْذُلَهُ"" : أَسْفَلَ القَميصِ الطَّويلِ"". 2.""شَمَّرَ ذَلاذِلَهُ لِلأَمْرِ"" : تَجَلَّدَ لِكِفايَتِهِ. 3.""فَرَسٌ خَفيفُ الذَّلاذِلِ"". 4.""لَحِقْنا ذَلاذِلَ مِنَ النَّاسِ"" : أَواخِرَ مِنْهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9254, 'ذَلاذِلُ', 'ذلاذل', 'جامد', '', 'ذلاذل', 'ذلذل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9255, 'ذُلَقٌ', 'ذلق', 'جامد', 'ذلق', 'ذلق', 'ذلق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ذَلْقٌ-ذَلْقٌ [ذ ل ق] (مص. ذَلَقَ). 1.""خَطيبٌ ذَلْقُ اللِّسانِ"": بَليغٌ، فَصيحٌ. 2.""ذَلْقُ اللِّسانِ"" : حادُّ اللِّسانِ. 3.""سِكِّينٌ ذَلْقٌ"": حادٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9256, 'ذَوْلَقٌ', 'ذولق', 'جامد', 'ذلق', 'ذولق', 'ذلق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ذَوْلَقٌ-ذَوْلَقٌ [ذ ل ق]. 1. ""ذَوْلَقُ اللِّسَانِ"" : أَسَلَتُهُ، طَرَفُهُ.‎ ""ذَوْلَقُ السِّنانِ"". ‎2.""ذَوْلَقُ الشَّيْءِ"" : حَدُّهُ ، ذَلْقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9257, 'ذِلٌّ', 'ذل', 'جامد', 'ذلل', 'ذل', 'ذل', '', '', '', 'مفرد', 'DnN', '', '', '"أَذْلالٌ"', '', 'R', '', '', '', '', '', '', '". 1.""عاشَ في ذِلٍّ"" : في ذُلٍّ، حَقارَةٍ، مَهانَةٍ. 2.""دَعْهُ على أَذْلالِهِ"" : كَما هُوَ. 3.""هُوَ مِنْ أَذْلالِ النَّاسِ"" : مِنْ أَراذِلِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9258, 'أَذْلالٌ', 'أذلال', 'جامد', '', 'ءذلال', 'ذلل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9259, 'ذُلِّلَ', 'ذلل', 'جامد', 'ذلل', 'ذلل', 'ذل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'N', '', '"ذُلِّلَ-ذُلِّلَ [ذ ل ل]. ""ذُلِّلَ الكَرْمُ"" : دُلِّيتْ عَناقيدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9260, 'ذِمَارٌ', 'ذمار', 'جامد', 'ذمر', 'ذمار', 'ذمر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ذِمَارٌ - [ذ م ر]. ""يَذُودُ عَنْ ذِمَارِهِ"" : مَا يَلْزَمُكَ حِيَاطَتُهُ وَالدِّفَاعُ عَنْهُ، وَالذَّوْدُ عَنْهُ كَالأَهْلِ وَالعِرْضِ وَالشَّرَفِ وَالْمُلْكِ.   ""هُوَ حَامِي الذِّمَارِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9261, 'ذَمَامَةٌ', 'ذمامة', 'جامد', 'ذمم', 'ذمامة', 'ذممة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"ذَمَامَةٌ-ذَمَامَةٌ [ذ م م]. 1.""يَسِيرُ فِي ذَمَامَةٍ"" : فِي ذِمَامٍ، فِي أمَانٍ وَكَفَالَةٍ. 2. ""بِهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9262, 'ذِمَامٌ', 'ذمام', 'جامد', 'ذمم', 'ذمام', 'ذمم', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"أَذِمَّةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""سَافَرَ فِي ذِمَامٍ"" : فِي أمَانٍ وَكَفَالَةٍ وَعَهْدٍ. فَسِرْ بِنَا فِي ذِمَامِ اللَّيْلِ مُهْتَدِيا*بِنَفْحَةِ الطّيبِ تَهْدِينَا إلَى الحِلَلِ (الطغرائي). 2. ""هُوَ حَامِي الذِّمَامِ"" : الحَقُّ، الحُرْمَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9263, 'أَذِمَّةٌ', 'أذمة', 'جامد', '', 'ءذمة', 'ذمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9264, 'ذِمَّةٌ', 'ذمة', 'جامد', 'ذمم', 'ذمة', 'ذمة', '', '', '', 'مفرد', 'DnN', '', '', '"ذِمَمٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""أَوْفَى بِالذِّمَّةِ"" : بِالعَهْدِ، بِالأَمانِ،بِالذّمامِ. الْمُسْلِمُونَ تَتكَافأُ دِمَاؤُهُمْ وَيَسْعَى بِذِمَّتِهِمْ أدْنَاهُمْ (حديث) : العَهْدُ، الأَمانُ، الكَفَالَةُ، الذِّمَامُ. 2. ""هَذَا الأمْرُ فِي ذِمَّتِي"" : أيْ فِي ضَمَانِي. 3. ""أُبَرِّئُ ذِمَّتِي"" : أُبَرِّئُ مَسْؤُولِيَّتي. 4. ""إنّ مَنْ تَرَكَ صَلاَةً مَكْتُوبَةً مُتَعمِّداً فَقَدْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9265, 'ذِمَمٌ', 'ذمم', 'جامد', '', 'ذمم', 'ذم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9266, 'ذُنَابَى', 'ذنابى', 'جامد', '', 'ذنابى', 'ذنب', '', '', '', 'جمع تكسير', 'Dy', '', '', '"ذُنَابَيات"', 'ممنوع من الصرف', 'R0', '', '', '', '', '', '', '"1. ""ذُنَابَى الطَّائِرِ"" : ذَنَبَهُ. وَقَدْ عَلِمَتْ رَبِيعةٌ بَلْ نِزَارُ*بِأَنَّا الرَّأْسُ وَالنَّاسُ الذُّنَابَى 2. ""ذُنَابَى الطَّائِرَةِ"" : الْمُسَطَّحَاتُ الْمَوْضُوعَةُ فِي مُؤَخَّرَةِ الطَّائِرَةِ لأجْلِ إثْبَاتِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9267, 'ذُنَابَيات', 'ذنابيات', 'جامد', '', 'ذنابيات', 'ذنبت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9268, 'أَذْنَابٌ', 'أذناب', 'جامد', 'ذنب', 'ءذناب', 'ذنب', '', '', '', 'مفرد', '', '', '', '"مفردذَنَبٌ"', '', '', '', '', '', '', '', '', '". ""مِنْ أَذْنَابِ النَّاسِ"": مِنْ سَفَلَتِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9269, 'ذُنَابَةٌ', 'ذنابة', 'جامد', 'ذنب', 'ذنابة', 'ذنبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":ذُنَائِبُ"', '', 'R', '', '', '', '', '', '', '". 1. ""ذُنَابَةُ الوَادِي"" : الْمَوْضِعُ الَّذِي يَنْتَهِي إلَيْهِ مَصَبُّهُ. 2. ""ذُنَابَاتُ النَّاسِ"": أتْبَاعُهُمْ وَسَفَلَتُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9270, 'ذُنَائِبُ', 'ذنائب', 'جامد', '', 'ذناءب', 'ذنب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9271, 'ذَنَبَةٌ', 'ذنبة', 'جامد', 'ذنب', 'ذنبة', 'ذنبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""ذَنَبَةُ الوَادِي"" : الْمَوْضِعُ الَّذِي يَنْتَهِي إلَيْهِ مَسِيلُهُ. 2. ""ذَنَبَاتُ النَّاسِ"" : سَفَلَتُهُمْ وَأتْبَاعُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9272, 'ذَنْبٌ', 'ذنب', 'جامد', 'ذنب', 'ذنب', 'ذنب', '', '', '', 'مفرد', 'DnN', '', '', '"ذُنُوبٌ"', '', 'R', '', '', '', '', '', '', '". ""اِرْتَكَبَ ذَنْباً"" : جُرْماً، ""اللَّهُمَّ اغْفِرْ ذُنُوبِي"" الْمُعْتَرِفُ بِالذَّنْبِ كَمَنْ لاَ ذَنْبَ لَهُ (حديث)."', '');
