INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9274, 'ذَنَبٌ', 'ذنب', 'جامد', '', 'ذنب', 'ذنب', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '":أذْنَابٌ"', '', 'R', '', '', '', '', '', '', '"ج: أذْنَابٌ، ذَنَبَاتٌ. 1. ""ذَنَبُ الحَيَوَانِ"" : ذَيْلُهُ. 2. ""ذَنَبُ العَيْنِ"" : مُؤْخِرُها، الجَانِبُ الخَارِجِيُّ لأِقْصَى العَيْنِ. ""نَظَرَ إلَيْهِ بِذَنَبِ عَيْنِهِ"". 3. ""رَكِبَ ذَنَبَ الرِّيحِ"" : سَبَقَ فَلَمْ يُدْرَكْ. 4. ""رَكِبَ ذَنَبَ البَعِيرِ"" "', ':لا جذر:لا مفرد');
