INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9277, 'مَذْهَبٌ', 'مذهب', 'جامد', 'ذهب', 'مذهب', 'مذهب', '', '', '', 'مفرد', 'DnN', '', '', '"مَذَاهِبُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَذْهَبُهُ فِي الْحَيَاةِ"" : طَرِيقَتُهُ، مَسْلَكُهُ. ""لِلنَّاسِ فِيمَا يَعْشَقُونَ مَذَاهِبُ"". 2.""مَذَاهِبُ الإِسْلاَمِ أَرْبَعَةٌ"" : الْمَالِكِيُّ وَال"', '');
