INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9290, 'ذِئْبٌ', 'ذئب', 'جامد', '', 'ذءب', 'ذب', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"ذِئابٌ:ذُؤْبانٌ"', '', 'R', '', '', '', '', '', '', '"ج: ذِئابٌ، ذُؤْبانٌ. (حو). 1.: حَيَوانٌ مِنْ فَصيلَةِ الكَلْبِيَّاتِ، مِنْ رُتْبَةِ اللَّواحِمِ، لَهُ خُرْطومٌ مُدَبَّبٌ يُمَيِّزُهُ عَنِ الكَلْبِ، أُذُناهُ مُنْتَصِبَتانِ وَذَيْلُهُ كَثيفُ مُهَـدَّلٌ، رمـادِيُّ اللَّوْنِ، مائِلٌ إلى الصُّفْرَةِ، يَعيشُ في السُّهولِ والجِبالِ والصَّح"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9291, 'ذِئابٌ', 'ذئاب', 'جامد', '', 'ذءاب', 'ذب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9292, 'ذُؤْبانٌ', 'ذؤبان', 'جامد', '', 'ذءبان', 'ذبن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9293, 'ذائِقَةٌ', 'ذائقة', 'جامد', 'ذيق', 'ذاءقة', 'ذقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"ذائِقَةٌ - [ذ ي ق]. 1.""ذائِقَةُ لِسانِهِ قَوِيَّةٌ"" : قُوَّةٌ تُدْرَكُ بِها الطُّعومُ. 2.آل عمران آية 185 كُلُّ نَفْسٍ ذائِقَةُ الْمَوْتِ (قرآن).كُلُّ نَفْسٍ سَتَذوقُ طَعْمَ الْمَوْتِ، أَيْ مَآلُها واحِدٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9294, 'ذَيْلٌ', 'ذيل', 'جامد', 'ذيل', 'ذيل', 'ذل', '', '', '', 'مفرد', 'DnN', '', '', '"ذُيُولٌ:أذْيَالٌ"', '', 'R', '', '', '', '', '', '', '". 1.""ذَيْلُ الحَيَوَانِ"" : ذَنَبُهُ. 2.""ذَيْلُ الثَّوْبِ"" : أَسْفَلُهُ إِذَا جُرَّ مَا أُسْبِلَ مِنْهُ. 3.""ذَيْلُ الرِّيحِ"" : مَا تَتْرُكُهُ الرِّيحُ فِي الرَّمْلِ كَأثَرِ ذَيْلٍ مَجْرُورٍ. 4.""فِي ذَيْلِهِ"" : أدْنَاهُ. 5.""رَجُلٌ طَوِيلُ الذَّيْلِ"" : غَنِيٌّ. 6.""طَاهِرُ الذَّيْلِ"": بَرِيءٌ. 7."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9295, 'ذُيُولٌ', 'ذيول', 'جامد', '', 'ذيول', 'ذل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9296, 'أذْيَالٌ', 'أذيال', 'جامد', '', 'ءذيال', 'ذل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9297, 'مَرْأَبٌ', 'مرأب', 'جامد', 'رأب', 'مرءب', 'مرب', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَائِبُ"', '', 'R', '', '', '', '', '', '', '". ""أَدْخَلَ السَّيَّارَةَ إِلَى الْمَرْأَبِ"" : بِنَاءٌ خَاصٌّ لِإِصْلاَحِ السَّيَّارَاتِ وَالدَّرَّاجَاتِ وَإِيوَائِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9298, 'مَرَائِبُ', 'مرائب', 'جامد', '', 'مراءب', 'مرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9299, 'رَادَارٌ', 'رادار', 'جامد', '', 'رادار', 'ردر', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '": جِهَازٌ إلِكْتِرُونِيٌّ مُرْسِلٌ لِمَوْجَاتٍ هِرْتِزِيَّةٌ لاَقِطٌّ لِمَوْجَاتٍمُنْعَكِسَةٍ مِنْهَا، لَهُ القُدْرَةُ عَلَى تَحَسُّسِ أَجْسَامٍ بَعِيدَةٍ وَتَمْيِيزِها كَالسُّفُنِ وَالطَّائِرَاتِ وَتحْدِيدِ اتِّجَاهَاتِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9300, 'رَادْيُو', 'راديو', 'جامد', '', 'راديو', 'رد', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ات"', '', 'R', '', 'N', 'O', 'N', 'O', '', '": جِهَازُ الإِرْسَالِ، ن. المِذْيَاعُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9301, 'رَادْيُومٌ', 'راديوم', 'جامد', '', 'راديوم', 'ردم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '": عُنْصُرٌ مَعْدِنِيٌّ مُشِعٌّ، وَزْنُهُ الذَّرِّيّ 226', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9302, 'رَأْسٌ', 'رأس', 'جامد', 'رأس', 'رءس', 'رس', '', '', '', 'مفرد', 'DnN', '', '', '"رُؤُوسٌ"', '', 'R', '', '', '', '', '', '', '". 1. (تش). ""رَأْسُ الإنْسَانِ"" : الجُمْجُمَةُ فِي أعْلَى الجِسْمِ، وَهُوَ يَضُمُّ الدِّمَاغَ وَحَاسَّةَ النَّظَرِ والسَّمْعِ وَالذَّوْقِ والشَّمِّ. ""حَرَّكَ رَأْسَهُ بِالْمُوَافَقَةِ"". 2. ""غِطَاءُ الرَّأْسِ"" : القُبَّعَةُ، الطَّاقِيَّةُ وَنَحْوُهُمَا. 3.""كَانَ عَلَى رَأْسِ الوَفْدِ"" : فِي مُقَدِّمَتِهِ، مُشْرِفاً عَلَيْهِ. 4.""تَوَصَّلَ بِهَدَايَا رَأْسِ السَّنَةِ"" : بِدَايَةِ السَّنَةِ، أَوَّلِ يَوْمٍ مِنَ السَّنَةِ الهِجْرِيَّةِ أوِ المِيلاَدِيَّةِ. 5. ""عَادَ إلَى مَسْقَطِ رَأْسِهِ"" : الْمَكَانُ الَّذِي وُلِدَ فِيهِ. 6. ""تَعَشَّى مَعَهُ رَأْساً لِرَأْسٍ"" : عَلَى انْفِرادٍ، وَجْهاً لِوَجْهٍ. 7. ""رَكِبَ رَأْسَهُ"" : عَمِلَ بِرَأْيِهِ دُونَ مَشُورَةٍ. 8.""أعَادَتْ تَنْظِيمَ الغُرْفَةِ رَأْساً عَلَى عَقِبٍ"" : حَوَّلَتْ كُلَّ مَا كَانَ بِهَا. 9. ""كُلُّ طَلَبَاتِكَ سَأُنْجِزُهَا عَلى الرَّأْسِ وَالعَيْنِ"" : بِكُلِّ طِيبَةِ خَاطِرٍ. 10. ""شَرِبَ مِنْ رَأْسِ العَيْنِ"" : مِنَ الْمَنْبَعِ. 11. ""أَعْلَنَ عَلَى رُؤُوسِ الأَشْهَادِ كُلَّ الوَقَائِعِ"" : أَظْهَرَ كُلَّ شَيْءٍ عَلاَنِيَةً. 12.""أَحْصَى أَرْبَعِينَ رَأْساً مِنَ الغَنَمِ"" : تُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9303, 'رُؤُوسٌ', 'رؤوس', 'جامد', '', 'رءوس', 'رس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9304, 'رَئِيسٌ', 'رئيس', 'جامد', 'رأس', 'رءيس', 'رس', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '":رُؤَسَاءُ"', '', 'R', '', '', '', '', '', '', '". 1.""اِنْتَخَبُوا الرَّئِيسَ"" : أي الْمَسْؤُولَ الْمُباشِرَ عَلَى رَأْسِ بَلَدٍ أوْ مُنَظَّمَةٍ ومَا شابَهَ ذَلِكَ. ""رَئِيسُ الدَّوْلَةِ"" ""رَئِيسُ الجُمْهُورِيَّةِ"" ""رَئِيسَةُ الحُكومَةِ"" ""رَئيسُ مَجْلِسِ النُّوَّابِ"". 2.""الأَعْضَاءُ الرَّئِي"', '');
