INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9307, 'رَافِدٌ', 'رافد', 'جامد', '', 'رافد', 'رفد', '', '', '', 'جمع تكسير', 'DnN', '', '', '"مثنىرافدان-رافدان"', '', 'R', '', '', '', '', '', '', '": نَهْرَا دِجْلَةَ وَالفُرَاتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9308, 'رَاقُولٌ', 'راقول', 'جامد', '', 'راقول', 'رقل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"رَوَاقِيلُ"', '', 'R', '', '', '', '', '', '', '"ج: رَوَاقِيلُ. : حَبْلٌ يُصْعَدُ بِهِ عَلَى النَّخْلِ."', ':لا جذر:لا مفرد');
