INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9310, 'رَاؤُولٌ', 'راؤول', 'جامد', 'رأل', 'راءول', 'رل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَاؤُولٌ-رَاؤُولٌ [ر أ ل]. : سِنٌّ زَائِدَةٌ خَلْفَ الأَضْراسِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9311, 'رُؤالٌ', 'رؤال', 'جامد', 'رأل', 'رءال', 'رل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"رُؤالٌ-رُؤالٌ [ر أ ل]. ""رُؤالُ الدَّابَّةِ"" : لُعابُها."', '');
