INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9313, 'رَاوُوقٌ', 'راووق', 'جامد', '', 'راووق', 'رق', '', '', '', 'جمع تكسير', 'DnN', '', '', '"رَوَاوِيقُ"', '', 'R', '', '', '', '', '', '', '"ج: رَوَاوِيقُ. 1.: المِصْفَاةُ. 2.: الكَأسُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9314, 'رَوَاوِيقُ', 'رواويق', 'جامد', '', 'رواويق', 'رق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9315, 'رَأْيٌ', 'رأي', 'جامد', 'رأي', 'رءي', 'ر', '', '', '', 'مفرد', 'DnN', '', '', '"آرَاءٌ"', '', '', '', '', '', '', '', '', '". 1.""قَدَّمَ رَأْياً صَرِيحاً فِي الْمَوْضُوعِ"" : مَا يَعْتَقِدُهُ الإِنْسَانُ وَيَرَاهُ صَحِيحاً. ""لَمْ يُبْدِ رَأْياً فِيمَا عُرِضَ عَلَيْهِ"". 2.""هَذَا رَأْيِي"" : هَذِهِ وِجْهَةُ نَظَرِي، مَا أَعْتَقِدُهُ. ""لَمْ يَكُنْ رَأْيُهُ مُلائِماً لِرَأْيِ الجَمَاعَةِ"". 3.""اِخْتَلَفَتْ آرَاؤُهُمْ"" : اِخْتَلَفَت اِقْتِنَاعَاتُهُمْ وَاعْتِقَادَاتُهُمْ. 4.""اِسْتَقَرَّ الرَّأْيُ عَلَى..."" : اِسْتَقَرَّ الاتِّفَاقُ فِي الأفْكَارِ... ""جَاءوا لِتَبَادُلِ الآرَاءِ"". 5.""الرَّأْيُ الأَخِيرُ لِلْقَائِدِ"" : الْمَوْقِفُ الفَصْلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9316, 'آرَاءٌ', 'آراء', 'جامد', '', 'ءءراء', 'آر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9317, 'رُؤْيَا', 'رؤيا', 'جامد', 'رأي', 'رءيا', 'ر', '', '', '', 'مفرد', 'Dy', '', '', '"رُؤًى"', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '". 1. ""رَأى رُؤْيَا فِي مَنَامِهِ"" : حُلْماً. الفتح آية 27 لَقَدْ صَدَقَ اللَّهُ رَسُولَهُ الرُّؤْيَا بِالحَقِّ .(قرآن). 2.""الرُّؤْيَا الصَّادِقَةُ"" : العَلاَمَةُ الأُولَى لِكَشْفِ الغَيْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9318, 'رُؤًى', 'رؤى', 'جامد', '', 'رءى', 'ر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9319, 'رِئَةٌ', 'رئة', 'جامد', 'رأي', 'رءة', 'رة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(تش). ""يَتَنَفَّسُ مِنْ رِئَتِهِ"" : عُضْوُالتَّنَفُّسِ عِنْدَ الإِنْسَانِ وَالحَيَوَانِ. ""أُصِيبَ بِالْتِهَابٍ فِي رِئَتِهِ"" : نَزْلَةٌ تُصِيبُ جِهَازَ التَّنَفُّسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9320, 'مِرْآةٌ', 'مرآة', 'جامد', 'رأي', 'مرءءة', 'مرآة', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَايَا"', '', 'R', '', '', '', '', '', '', '". ""وَقَفَتْ أَمَامَ الْمِرْآةِ تَتَأَمَّلُ وَجْهَهَا"" : زُجَاجٌ مِنْ بِلَّوْرٍ يُتَرَاءى فِيهِ، أَيْ يَنْعَكِسُ عَلَيْهِ وَجْهُ النَّاظِرِ إِلَيْهِ. ""الْمِرْآةُ مِثْلَمَا تُرِيهَا تُرِيكَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9321, 'مَرَايَا', 'مرايا', 'جامد', '', 'مرايا', 'مر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9322, 'مَرْأًى', 'مرأى', 'جامد', 'رأي', 'مرءى', 'مر', '', '', '', 'مفرد', 'Dy', '', '', '', '', 'R0', '', '', '', '', '', '', '"مَرْأًى-مَرْأًى [ر أ ي]. 1.""فَتَاةٌ لَهَا مَرْأًى حَسَنٌ"" : مَنْظَرٌ وَمَظْهَرٌ حَسَنٌ. 2.""عَلَى مَرْأىً وَمَسْمَعٍ مِنَ الجَمِيعِ"" : أَمَامَ نَظَرِ الجَمِيعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9323, 'مَرْئِيَّاتٌ', 'مرئيات', 'جامد', 'رأي', 'مرءيات', 'مرت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مَرْئِيَّاتٌ-مَرْئِيَّاتٌ [ر أ ي]. ""الْمَرْئِيَّاتُ وَالْمَحْسُوسَاتُ"" : الأَشْيَاءُ الْمَنْظُورَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9324, 'رَبِيئَةٌ', 'ربيئة', 'جامد', 'ربأ', 'ربيءة', 'ربة', '', '', '', 'مفرد', 'DnN', '', '', '"رَبايا"', '', '', '', '', '', '', '', '', '". ""تَقَدَّمَتِ الرَّبيئَةُ فَوْقَ التَّلِّ"" : طَليعَةُ الجُنْدِ الَّتِي تَرْقُبُ العَدُوَّ فِي مَكَانٍ عَالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9325, 'رَبايا', 'ربايا', 'جامد', '', 'ربايا', 'رب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9326, 'مَرْبَأٌ', 'مربأ', 'جامد', 'ربأ', 'مربء', 'مرب', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'Rz', '', '', '', '', '', '', '"مَرْبَأٌ-مَرْبَأٌ، ةٌ [ر ب أ]. 1.""مَرْبَأُ أَوْ مَرْبَأَةُ الْمُرَاقِبِ"" : مَكَانٌ يَقِفُ فِيهِ الْمُرَاقِبُ. 2.""مَرْبَأَةُ البَازِيِّ"" : مَكَانٌ يَقِفُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9327, 'رَبَابَةٌ', 'ربابة', 'جامد', '', 'ربابة', 'رببة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"ن.: الرَّبَابُ. ""ربابَةٌ"" : اسم علم للإناث. رَبابَةٌ رَبَّـةُ الْبَيْـتِ*تَصُـبُّ الْخَلّ في الزَّيْـتِ (ابن الرومي)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9328, 'رَبَابٌ', 'رباب', 'جامد', 'ربب', 'رباب', 'ربب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَبَابٌ-رَبَابٌ [ر ب ب]. 1.: آلَةٌ مُوسِيقيَّةٌ مِنَ العائِلَة الوَتَرِيَّةِ، وَهِيَعِبَارَةٌ عَنْ صُنْدُوقٍ مُجَوَّفٍ، لَهُ إطَارٌ خَشَبِيٌّ، عَلَيْهِ قِطْعَةٌ مِنَ الجِلْدِ، فِي أَعْلاَهُ مِفْتَاحٌ وَاحِدٌ، وَيَتَضَمَّنُ وَتَراً وَاحِداً. ""يَعْزِفُ عَلَى الرَّبابِ قِطْعَةً موسِيقِيَّةً مِنَ الطَّرَبِ الأَنْدَلُسِيِّ"". 2. ""ربابُ"" : اسم علم للإناث."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9329, 'رَبَّةٌ', 'ربة', 'جامد', 'ربب', 'ربة', 'ربة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مؤنثالرَّبُّ"', '', '', '', '', '', '', '', '', '". 1. ""رَبَّةُ قُرَيْشٍ فِي الجَاهِلِيَّةِ"" : كُلُّ صَنَمٍ عَلَى صُورَةِ الأُنْثَى كَاللاتِ. 2. ""رَبَّةُ بَيْتٍ مُقْتَدِرَةٌ"" ‎: سَيِّدَةُ البَيْتِ. 3. ""رَبَّةُ حُسْنٍ وَجَمَالٍ"" : عَلَى جَانِبٍ كَبِيرٍ مِنَ الحُسْنِ وَالجَمَالِ. 4. ""جَاءتْهُ رَبَّةُ الشِّعْرِ"" : الإلْهَامُ الشِّعْرِيُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9330, 'رَبُّ', 'رب', 'جامد', 'ربب', 'رب', 'رب', '', '', '', 'مفرد', 'DnN', '', '', '"أرْبَابٌ:رُبُوبٌ"', '', '', '', '', '', '', '', '', '". 1.""رَبُّ العَالَمِينَ"" : اللهُ، مِنْ أسْمَاءِ اللَّهِ تَعَالَى وَلاَ يُقَالُ الرَّبُّ فِي غَيْرِ اللهِ إِلاَّ بِالإِضَافَةِ. ""تُطَارِدُنِي لأِنِّي غَيْرَ رَبِّي وَحْدَهُ لَمْ أتَّخِذْ رَبّاً"". (بدر شاكر السياب). 2.""رَبُّ الْمَعْمَلِ"" : مَالِكُهُ، صاحِبُهُ. 3.""لِلْبَيْتِ رَبٌّ يَحْمِيهِ"" : سَيِّدٌ. ""رَبُّ الدَّارِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9331, 'أرْبَابٌ', 'أرباب', 'جامد', '', 'ءرباب', 'ربب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9332, 'رُبُوبٌ', 'ربوب', 'جامد', '', 'ربوب', 'ربب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9333, 'رَبِيبَةٌ', 'ربيبة', 'جامد', 'ربب', 'ربيبة', 'رببة', '', '', '', 'مفرد', 'DnN', '', '', '"رَبَائِبُ"', '', 'R', '', '', '', '', '', '', '". ""يُعَامِلُ رَبِيبَتَهُ بِلُطْفٍ"" : بِنْتُ الزَّوْجَةِ مِنْ زَوَاجٍ سَابِقٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9334, 'رَبَائِبُ', 'ربائب', 'جامد', '', 'رباءب', 'ربب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9335, 'رَبِيبٌ', 'ربيب', 'جامد', 'ربب', 'ربيب', 'ربب', '', '', '', 'مفرد', 'DnN', '', '', '"أَرِبَّةٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""لَمْ يَكُنِ الزَّوْجُ يَحْتَمِلُ وُجودَ رَبيبٍ في البَيْتِ"" : اِبْنُ امْرَأَةٍ مِنْ زَوْجٍ سابِقٍ. 2. ""لَمْ تَكُن عَلاَقَتُهُ مَعَ رَبِيبِهِ سَهْلَةً"" : زَوْجُ الأُمِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9336, 'أَرِبَّةٌ', 'أربة', 'جامد', '', 'ءربة', 'ربة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9337, 'رُبَدٌ', 'ربد', 'جامد', 'ربد', 'ربد', 'ربد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رُبَدٌ-رُبَدٌ [ر ب د]. ""رُبَدُ السَّيْفِ"" : جَوْهَرُهُ، أوْ وَشْيُهُ، أَوْ مَاؤُهُ الَّذِي يَجْرِي فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9338, 'رَبِيدَةٌ', 'ربيدة', 'جامد', 'ربد', 'ربيدة', 'ربدة', '', '', '', 'مفرد', 'DnN', '', '', '"رَبَائِدُ"', '', '', '', '', '', '', '', '', '". ""رَبَائِدُ الْمَكْتَبَةِ"" : مَا تُصَانُ فِيه الكتُبُ والسِّجِلاَّتُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9339, 'رَبَائِدُ', 'ربائد', 'جامد', '', 'رباءد', 'ربد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9340, 'رَبِيدٌ', 'ربيد', 'جامد', 'ربد', 'ربيد', 'ربد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَبِيدٌ-رَبِيدٌ [ر ب د]. ""هَيَّأَ الرَّبِيدَ"" : تَمْرٌ نُضِّدَ فِي وِعاءٍ ثُمَّ نُضِحَ بِالْمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9341, 'مِرْبَدٌ', 'مربد', 'جامد', 'ربد', 'مربد', 'مربد', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَابِدُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِرْبَدُ الإِبِلِ"" : مَحْبَسُهَا، مَوْقِفُهَا، سُوقُهَا. 2.""مِرْبَدُ الدَّارِ"" : مَا وَرَاءهَا مِنْ فَضَاءٍ. 3.""مِرْبَدُ البَصْرَةِ"" : سُوقُ الإِبِلِ وَفِيهِ كَانَ الشُّعَرَاءُ يَجْتَمِعُونَ لِإِنْشَادِ أَشْعَارِهِمْ. 4.""مِرْبَدُ التَّمْرِ"" : مَا يُبْسَطُ ويُجَفَّفُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9342, 'مَرَابِدُ', 'مرابد', 'جامد', '', 'مرابد', 'مربد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9343, 'رِبْذَةٌ', 'ربذة', 'جامد', 'ربذ', 'ربذة', 'ربذة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رِبْذَةٌ-رِبْذَةٌ [ر ب ذ]. 1. ""رِبْذَةُ الحَائِضِ"" : خِرْقَتُهَا. 2.""رِبْذَةُ الصَّائِغِ"" : خِرْقَةٌ يَجْلُو بِهَا الحَلْيَ. 3. ""رِبْذَةُ العَامِلِ"" : خِرْقَةٌ لِتَنْظِيفِ الآلَةِ وَالأَدَاةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9344, 'رَبْرَبٌ', 'ربرب', 'جامد', 'ربرب', 'ربرب', 'ربرب', '', '', '', 'مفرد', 'DnN', '', '', '"رَبارِبُ"', '', 'R', '', '', '', '', '', '', '". ""لاَحَ رَبْرَبٌ مِنْ بَعِيدٍ فاهْتَزَّ الصَّائِدُ مُتَرَبِّصاً"" : القَطِيعُ مِنْ بَقَرِ الوَحْشِ أَوِ البَقَرِ الأَلِيفِ أَوِ الغِزْلانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9345, 'رَبارِبُ', 'ربارب', 'جامد', '', 'ربارب', 'ربرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9346, 'رَبَضٌ', 'ربض', 'جامد', 'ربض', 'ربض', 'ربض', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْباضٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَدْخَلَ الغَنَمَ إلى الرَّبَضِ"" : مَأْواها. 2.""أَرْبَاضُ الْمَدِينَةِ"" : نَواحِيهَا، ضَواحِيهَا. 3.""رَبَضُ الْمَدينَةِ"" : سُورُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9347, 'أَرْباضٌ', 'أرباض', 'جامد', '', 'ءرباض', 'ربض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9348, 'رَبِيضٌ', 'ربيض', 'جامد', 'ربض', 'ربيض', 'ربض', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَبِيضٌ-رَبِيضٌ [ر ب ض]. 1.: الغَنَمُ بِرُعَاتِهَا الْمُجْتَمِعَةُ فِي مَرابِضهَا. 2.: مُجْتَمَعُ الأَمْعَاءِ فِي البَطْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9349, 'مَرْبِضٌ', 'مربض', 'جامد', 'ربض', 'مربض', 'مربض', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَابِضُ"', '', 'R', '', '', '', '', '', '', '". ""مَرْبِضُ الدَّوَابِّ"" : مَوْضِعُ إِقَامَتِهَا، رَبْضِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9350, 'مَرَابِضُ', 'مرابض', 'جامد', '', 'مرابض', 'مربض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9351, 'رَابِطَةٌ', 'رابطة', 'جامد', 'ربط', 'رابطة', 'ربطة', '', '', '', 'مفرد', 'DnN', '', '', '"رَوَابِطُ"', '', 'R', '', '', '', '', '', '', '". 1.""بَيْنَهُما رَابِطَةُ دَمٍ"": عَلاَقَةُ دَمٍ، صِلَةٌ. ""تَجْمَعُهُمْ رَوَابِطُ صَدَاقَةٍ قَدِيمَةٍ. 2.""رَابِطَةُ حُقُوقِ الإِنْسَانِ"" : جَمْعِيَّةٌ، عُصْبَةٌ. ""رَابِطَةُ الأُدَبَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9352, 'رَوَابِطُ', 'روابط', 'جامد', '', 'روابط', 'ربط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9353, 'رَبْطَةٌ', 'ربطة', 'جامد', 'ربط', 'ربطة', 'ربطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""يَحْـصُـدُ السَّنَابِلَ وَيَرْبِطُهَا رَبْطَةً"" : حُزْمَةً. ""رَبْطَةُ الحَطَبِ"". 2.""رَبْطَةُ العُنُقِ"" : عُقْدَةٌ مِنَ الثَّوْبِ تُوضَعُ حَوْلَ العُنُقِ فَوْقَ القَمِيصِ، أُرْبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9354, 'مَرْبَطٌ', 'مربط', 'جامد', 'ربط', 'مربط', 'مربط', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَابِطُ"', '', 'R', '', '', '', '', '', '', '". ""مَرْبَطُ الدَّوَابِّ"" : مَوْضِعُ رَبْطِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9355, 'مَرَابِطُ', 'مرابط', 'جامد', '', 'مرابط', 'مربط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9356, 'مِرْبَطٌ', 'مربط', 'جامد', 'ربط', 'مربط', 'مربط', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَرَابِطُ"', '', 'R', '', '', '', '', '', '', '". ""مِرْبَطُ الدَّابَّةِ"" : مَا تُرْبَطُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9357, 'مَرَابِطُ', 'مرابط', 'جامد', '', 'مرابط', 'مربط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9358, 'أَرْبِعَاءُ', 'أربعاء', 'جامد', 'ربع', 'ءربعاء', 'ربع', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '"أَرْبِعَاءُ-أَرْبِعَاءُ [ر ب ع]. ""سَافَرَ يَوْمَ الأرْبِعَاءِ"" : هُوَ اليَوْمُ الرَّابِعُ مِنْ أَيَّامِ الأسْبُوعِ، يَأْتِي بَعْدَ يَوْمِ الثُّلاثاءِ ويَلِيهِ يَوْمُ الخَمِيسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9359, 'أَرْبَعُ', 'أربع', 'جامد', 'ربع', 'ءربع', 'ربع', '', 'Tn', '', 'مفرد', '', '', '', '"عَدَدٌمُفْرَدٌ:مَعْدُودُهُجَم', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '"أَرْبَعُ-أَرْبَعُ [ر ب ع]. : عَدَدٌ مُفْرَدٌ، مَعْدُودُهُ جَمْعٌ مُؤَنَّثٌ. 1.""دَخَلَتِ القَاعَةَ أَرْبَعُ نِسَاءٍ مَعَ أَرْبَعِ بَنَاتٍ"". ""زُرْتُهُ أَرْبَعَ مَرَّاتٍ"". 2. ""صَارَ عُمْرُها أَرْبَعَ عَشْرَةَ سَنَةً"" : عَدَدٌ مُرَكَّبٌ مَعْدُودُهُ مُفْرَدٌ مُؤَنَّثٌ مَنْصُوبٌ عَلَى التَّمْيِيزِ. 3.""يَتَقَلَّبُ مَعَ الرِّيَاحِ الأَرْبَعِ"" : الصَّبَا وَالدَّبُورُ وَالجَنُوبُ وَالشَّمَالُ. 4.""حَيَوَانٌ مِنْ ذَوَاتِ الأَرْبَعِ"" : يَمْشِي عَلَى أَرْبَعِ قَوَائِمَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9360, 'أَرْبَعَةٌ', 'أربعة', 'جامد', 'ربع', 'ءربعة', 'ربعة', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '"أَرْبَعَةٌ-أَرْبَعَةٌ [ر ب ع].: عَدَدٌ (4)، مُذَكَّرُ أَرْبَع. 1. ""وَصَلَ أَرْبَعَةُ ضُيُوفٍ"". ""يُحِيطُ بِالبَيْتِ أَرْبَعَةُ جُدْرَانٍ"". 2.""سَلَّمَنِي أَرْبَعَةَ عَشَرَ دِرْهَماً"" : عَدَدٌ مُرَكَّبٌ مَعْدُودُهُ مُذَكَّرٌ مُفْرَدٌ مَنْصُوبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9361, 'رَابِعٌ', 'رابع', 'جامد', 'ربع', 'رابع', 'ربع', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رَابِعٌ-رَابِعٌ، ةٌ [ر ب ع]. 1.: عَدَدٌ يَدُلُّ عَلَى التَّرْتِيبِ وَيَكُونُ معْدُودُهُ مُذَكَّراً : ""هُوَ الرَّابِعُ فِي الصَّفِّ"" : أيْ كَانَتْ رُتْبَتُهُ بَيْنَ الثَّالِثِ وَالخَامِسِ وَيُعْرَبُ نَعْتاً فِي المِثَالِ التَّالِي : ""وَصَلَ الفَائِزُ الرَّابِعُ""، وَإذَا لَمْ يُذْكَرْ مَعدُودُهُ : ""وَصَلَ الرَّابِعُ"" فَيُعْرَبُ فاعِلَ وَصَلَ، وَإذَا قُلْتَ : ""كَلَّمْتُ الرَّابِعَ"" فَيُعْرَبُ مَفْعُولاً بِهِ، وَهَكَذَا يُعْرَبُ حَسَبَ مَوْقِعِهِ فِي الجُمْلَةِ. ""الجُزْءُ الرَّابِعُ"" ""الدَّرَجَةُ الرَّابِعَةُ"" ""تُشِيرُ السَّاعَةُ إلَى الرَّابِعَةِ"". 2.""رَابِعَ عَشَرَ"" : عَدَدٌ مُرَكَّبٌ يَدُلُّ علَى التَّرْتِيبِ مَعْدُودُهُ مُذَكَّرٌ و""رَابِعَةَ عَشْرَةَ"" ‎: يَكُونُ مَعْدُودُهُ مُؤَنَّثاً. 3.""رَابِعُ الْمُسْتَحِيلاَتِ"" : الأَمْرُ الْمُسْتَحِيلُ الَّذِي يَصْعُبُ تَصَوُّرُهُ. 4.""رَابِعاً"" : تَعْيِينُ التَّرْتِيبِ عِنْدَمَا يَتَعَلَّقُ الأَمْرُ بِمَوْضُوعٍ مُكَوَّنٍ مِنْ عِدَّةِ عَنَاصِرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9362, 'رُبَاعِيَّاتٌ', 'رباعيات', 'جامد', 'ربع', 'رباعيات', 'ربعت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"رُبَاعِيَّاتٌ-رُبَاعِيَّاتٌ [ر ب ع].: مُقَطَّعَاتٌ شِعْرِيَّةٌ يَتَألَّفُ كُلٌّ مِنْهَا مِنْ أرْبَعَةِ أَبْيَاتٍ. ""رُبَاعِيَّاتُ الخَيَّامِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9363, 'رَبْعَةٌ', 'ربعة', 'جامد', 'ربع', 'ربعة', 'ربعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رَبْعَةٌ-رَبْعَةٌ [ر ب ع]. 1.""وَضَعَ الْمُصْحَفَ فِي رَبْعَةٍ"" : صُنْدُوقُ الْمُصْحَفِ. 2.""رَبْعَةُ القَامَةِ"" : مُتَوَسِّطُ، مُتَوَسِّطَةُ القَامَةِ. (لِلْمُذَكَّرِ والْمُؤَنَّثِ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9364, 'رُبُعٌ', 'ربع', 'جامد', 'ربع', 'ربع', 'ربع', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْبَاعٌ"', '', 'R', '', '', '', '', '', '', '". ن. رُبْعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9365, 'أَرْبَاعٌ', 'أرباع', 'جامد', '', 'ءرباع', 'ربع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9366, 'رُبْعٌ', 'ربع', 'جامد', 'ربع', 'ربع', 'ربع', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْبَاعٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""تُشِيرُ السَّاعَةُ إلَى الوَاحِدَةِ والرُّبْعِ"" : أيْ مَا يُعَادِلُ خَمْسَ عَشْرَةَ دَقِيقَةً، رُبْعُ سَاعَةٍ، وَالسَّاعَةُ أرْبَعةُ أجْزَاءٍ، والرُّبْعُ جُزْءٌ مِنْهَا. 2. ""أَخَذَ رُبْعَ الحِصَّةِ"" : أَيْ جُزْءاً مِنْ أرْبَعَةِ أَجْزَاءِ الحِصَّةِ. 3. ""رُبْعُ الدَّائِرَةِ"": جُزْءٌ مِنْ أرْبَعةِ أَجْزَاءِ مُحِيطِهَا، وَهُو 90 دَرَجَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9367, 'أَرْبَاعٌ', 'أرباع', 'جامد', '', 'ءرباع', 'ربع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9368, 'رُبوعٌ', 'ربوع', 'جامد', 'ربع', 'ربوع', 'ربع', '', '', '', 'مفرد', '', '', '', '"مفردرَبْع"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""طَافُوا بِرُبُوعِ البِلاَدِ"" : بِأنْحَائِهَا، بِأَرْجَائِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9369, 'رَبِيعَةٌ', 'ربيعة', 'جامد', 'ربع', 'ربيعة', 'ربعة', '', '', '', 'مفرد', 'DnN', '', '', '"ربَائِعُ"', '', '', '', '', '', '', '', '', '". 1. ""حَمَلَ الرَّبِيعَةَ لِيُظْهِرَ قُوَّةَ عَضَلاَتِهِ"" : أدَاةٌ مِنْ حَجَرٍ أَوْ مَعْدِنٍ يَحْمِلُهَا رِيَاضِيُّو حَمْلِ الأثْقَالِ. 2. ""رَبِيعَةُ الجُنْدِيِّ"" : خُوذَةٌ مِنْ حَدِيدٍ يَلْبَسُهَا الجُنْدِيُّ فِي الحَرْبِ. 3.""رَبيعَةُ العَرُوسِ"" : حُقَّةٌ تُمْلأُ بِالطِّيبِ. 4.""رَبيعَةُ"" : اِسْمُ عَلَمٍ لِلإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9370, 'ربَائِعُ', 'ربائع', 'جامد', '', 'رباءع', 'ربع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9371, 'رَبِيعٌ', 'ربيع', 'جامد', 'ربع', 'ربيع', 'ربع', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْبِعةٌ:رِبَاعٌ:أرْبِعَاءُ"', '', 'R', '', '', '', '', '', '', '". 1.""حَلَّ فَصْلُ الرَّبِيعِ"" : فَصْلٌ مِنَ الفُصُولِ الأرْبَعَةِ عَلَى مَدَارِ السَّنَةِ يَمْتَدُّ مِنْ 21 مَارِسَ، (آذَارَ) إلَى 21 جوان، (حَزِيرانَ). 2.""رَبِيعٌ الأوَّلُ"" : الشَّهْرُ الثَّالِثُ مِنَ السَّنَةِ الهِجْرِيَّةِ، عَدَدُ أيَّامِهِ (30) يَوْماً ويُمْكِنُ أَنْ يَكُونَ (29) يَوْماً فَقَطْ. 3.""رَبِيعٌ الثَّانِي"": الشَّهْرُ الرَّابِعُ مِنَ السَّنَةِ الهِجْرِيَّةِ، عَدَدُ أَيَّامِهِ (29) يَوْماً وَيُمْكِنُ أَنْ يَكُونَ (30) يَوْماً. 4. ""يَقْضُمُ الغَنَمُ الرَّبِيعَ"" : الرَّجيعُ، الرَّجْعُ مَا يَنْبُتُ فِي فَصْلِ الرَّبِيعِ مِنْ عُشْبٍ وَكَلإٍ. 5.""أيَنَمَا وَلَّيْتَ وَجْهَكَ تَجِدْ زَهْرَةَ الرَّبِيعِ"" : زَهْرَةً بَيْضَاءَ أوْ وَرْدِيَّةً، وَسَطُهَا أصْفَرُ اللَّوْنِ تَكْثُرُ فِي الحُقُولِ والبَسَاتِينِ. 6.""رَبيعُ العُمْرِ"" : قُوَّةُ الشَّبَابِ وَفُتُوّتُهُ."', '');
