INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9378, 'مَرابِعُ', 'مرابع', 'جامد', '', 'مرابع', 'مربع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9379, 'مَرْبَعٌ', 'مربع', 'جامد', 'ربع', 'مربع', 'مربع', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَابِعُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَرْبَعُ الرَّبِيعِ"" : مَطَرُهُ. 2.""قَضَى عُطْلَتَهُ فِي الْمَرْبَعِ"" : مَكَانُ إِقَامَتِهِ فِي فَصْلِ الرَّبِيعِ."', '');
