INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9381, 'مِرْبَعٌ', 'مربع', 'جامد', 'ربع', 'مربع', 'مربع', '', '', '', 'مفرد', 'DnN', '', '', '"مَرابِعُ"', '', 'R', '', '', '', '', '', '', '". : عَصاً يأْخُذُ رَجُلاَنِ بِطَرَفَيْهَا لِيَحْمِلاَ بِهَا الحِمْلَ عَلى الدَّابَّةِ."', '');
