INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9383, 'رِبْقٌ', 'ربق', 'جامد', 'ربق', 'ربق', 'ربق', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"أرْبَاقٌ:رِبَاقٌ:رِبَقٌ"', '', 'R', '', '', '', '', '', '', '". 1.: حَبْلٌ فِيهِ عُرًى عَدِيدَةٌ، كُلُّ عُرْوَةٍ فِيهَا رِبْقَةٌ تُشَدُّ بِهَا البَهَائِمُ وَالغَنَمُ. 2.""حَلَّ رِبْقَتَهُ"" : فَرَّجَ كُرْبَتَهُ. ""لا يَرْضَى الحُرُّ رِبْقَةَ الذُّلِّ"" l ""رِبْقَةُ الاسْتِعْبادِ""."', '');
