INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9387, 'رُبَيْقٌ', 'ربيق', 'جامد', 'ربق', 'ربيق', 'ربق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رُبَيْقٌ-رُبَيْقٌ [ر ب ق]. ""أُمُّ الرُّبَيْقِ"" : الأَفْعَى. وَيُطْلَقُ عَلَى الحَرْبِ والشِّدَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9388, 'مُرَبَّقَةٌ', 'مربقة', 'جامد', 'ربق', 'مربقة', 'مربقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مُرَبَّقَةٌ-مُرَبَّقَةٌ [ر ب ق]. ""خُبْزَةٌ مُرَبَّقَةٌ"" : مَعْجونَةٌ بِشَحْمٍ أَو مَحْشُوَّةٌ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9389, 'رَبِيكَةٌ', 'ربيكة', 'جامد', 'ربك', 'ربيكة', 'ربكة', '', '', '', 'مفرد', 'DnN', '', '', '"رَبَائِكُ"', '', '', '', '', '', '', '', '', '". 1.: مَاءٌ مُخْتَلِطٌ بِالطِّينِ"". 2. ""بِهِ رَبِيكةٌ"" : أمْرُهُ مُخْتَلِطٌ عَلَيْهِ. 3.: جُبْنٌ بِتَمْرٍ وَسَمْنٍ وَرُبَّمَا صُبَّ عَلَيْهِ مَاءٌ لِيُشْرَبَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9390, 'رَبَائِكُ', 'ربائك', 'جامد', '', 'رباءك', 'ربك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9391, 'تَرَبُّلٌ', 'تربل', 'جامد', 'ربل', 'تربل', 'تربل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"تَرَبُّلٌ-تَرَبُّلٌ [ر ب ل]. 1.""تَرَبُّلُ الأَرْضِ"" : كَثْرَةُ رَبْلِهَا. 2.""تَرَبُّلُ الْجِسْمِ"" : غِلَظُهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9392, 'رَابِلَةٌ', 'رابلة', 'جامد', 'ربل', 'رابلة', 'ربلة', '', '', '', 'مفرد', 'DnN', '', '', '"رَوابِلُ"', '', 'R', '', '', '', '', '', '', '".: لَحْمَةُ الكَتِفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9393, 'رَوابِلُ', 'روابل', 'جامد', '', 'روابل', 'ربل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9394, 'رَبْلٌ', 'ربل', 'جامد', 'ربل', 'ربل', 'ربل', '', '', '', 'مفرد', 'DnN', '', '', '"رُبولٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"(نب).: جِنْسُ نَباتٍ بَرِّيٍّ وَتَزْيِينِيٍّ مِنْ فَصِيلَةِ الفُوِّيّاتِ، أنْوَاعُهُ عَدِيدَةٌ، بَعْضُهَا شَائِكٌ وَجَعْدٌ، ثِمَارُهُ عِنَبِيَّةٌ ثُنَائِيَّةُ الفِلْقَةِ، يَعْلُو ثِمارَهُ زَهْرٌ أُقْحُوانِيٌّ الشَّكْلِ، يَكْثُرُ فِي الأرَاضِي الرَّطْبَةِ وَعلى ضِفَافِ الأَنْهَارِ، يُسْتَخْرَجُ مِنْ ثِمَارِهِ صِباغٌ أَزْرَقُ جَيِّدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9395, 'رُبولٌ', 'ربول', 'جامد', '', 'ربول', 'ربل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9396, 'رَبِيلَةٌ', 'ربيلة', 'جامد', 'ربل', 'ربيلة', 'ربلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رَبِيلَةٌ-رَبِيلَةٌ [ر ب ل]. 1. ""يَعِيشُ فِي رَبِيلَةٍ"" : فِي نِعْمَةٍ وَخِصْبٍ. 2. ""ظَهَرَتْ عَلَيْهِ الرَّبِيلَةُ"" : السِّمَنُ. 3. ""فِي البَيْتِ رَبِيلَةٌ"" : رُطُوبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9397, 'رَبْلَةٌ', 'ربلة', 'جامد', '', 'ربلة', 'ربلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ج: رَبَلاتٌ. ""أخَذَ رَبْلَةً مِنْ لَحْمِ البَقَرِ"" : الجُزْءَ الغَلِيظَ مِنْهَا، لَحْمَةَ بَاطِنِ الفَخِذِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9398, 'رُبَّانٌ', 'ربان', 'جامد', 'ربن', 'ربان', 'ربن', '', '', '', 'مفرد', 'DnN', '', '', '"رَبابِنَةٌ:رَبابينُ"', '', '', '', '', '', '', '', '', '". 1.""يَقودُ السَّفينَةَ رُبَّانٌ"" : رَئيسُ مَلاَّحِي السَّفينَةِ وَقائِدُهُمْ. 2."" رُبَّانُ الشَّيْءِ"" : كُلُّهُ، مُعْظَمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9399, 'رَبابِنَةٌ', 'ربابنة', 'جامد', '', 'ربابنة', 'رببنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
