INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9401, 'رَابِيَةٌ', 'رابية', 'جامد', 'ربو', 'رابية', 'ربة', '', '', '', 'مفرد', 'DnN', '', '', '"رَوَابٍ:الرَّوابِي"', '', '', '', '', '', '', '', '', '". ""يُنَادِيهِ مِنْ أَعْلَى الرَّابِيَةِ"" : مَا ارْتَفَعَ مِنَ الأَرْضِ، التَّلَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9402, 'رَوابِي', 'روابي', 'جامد', '', 'روابي', 'رب', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9403, 'رَبَاءٌ', 'رباء', 'جامد', 'ربو', 'رباء', 'رب', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"رَبَاءٌ-رَبَاءٌ [ر ب و].""لِفُلانٍ عَلَيَّ رَبَاءٌ"" : فَضْلٌ، مِنَّةٌ، جَمِيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9404, 'رِبَا', 'ربا', 'جامد', 'ربو', 'ربا', 'رب', '', '', '', 'مفرد', 'Dw', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"رِبَا-رِبَا [ر ب و]. ""يَعِيشُ عَلَى الرِّبَا"" : مَا يَتَقَاضَاهُ الْمُرَابِي مِن فَائِدَةٍ مِنْ مَدِينِهِ مُقَابِلَ مَا أقْرَضَهُ مِنْ مَالٍ. البقرة آية 275 وَأحَلَّ اللَّهُ البَيْعَ وَحَرَّمَ الرِّبَا (قرآن) ""الرِّبَا هُوَ كَسْبٌ بِدُونِ مُقَابِلٍ مَادِّيٍّ وَفِيهِ مَعْنَى الغَصْبِ"". (ع. الكواكبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9405, 'رَبْوَةٌ', 'ربوة', 'جامد', 'ربو', 'ربوة', 'ربة', '', '', '', 'مفرد', 'DnN', '', '', '"رُبًى"', '', 'R', '', '', '', '', '', '', '". ""ظَهَرَتِ الرَّبْوَةُ مِنْ بَعِيدٍ"": مَا ارْتَفَعَ مِنَ الأَرْضِ، التَّلَّةُ، الرَّابِيَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9406, 'رُبًى', 'ربى', 'جامد', '', 'ربى', 'رب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9407, 'مُرَبَّى', 'مربى', 'جامد', 'ربو', 'مربى', 'مرب', '', '', '', 'مفرد', 'Dy', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مُرَبَّى-مُرَبَّى [ر ب و]. ""مُرَبَّى الفَاكِهَةِ"" : أَيِ الفَاكِهَةُ الَّتِي تُعْقَدُ بِالسُّكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9408, 'تَرَاتُبٌ', 'تراتب', 'جامد', 'رتب', 'تراتب', 'ترتب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَرَاتُبٌ-تَرَاتُبٌ [ر ت ب]. 1.""تَرَاتُبُ الطَّبَقَاتِ الاجْتِمَاعِيَّةِ"" : مَرَاتِبُهَا، طَبَقَاتُهَا. 2.""التَّرَاتُبُ العَسْكَرِيُّ"" : سِلْسِلَةُ الْمَرَاتِبِ العَسْكَرِيَّةِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9409, 'رُتْبَةٌ', 'رتبة', 'جامد', 'رتب', 'رتبة', 'رتبة', '', '', '', 'مفرد', 'DnN', '', '', '"رُتَبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""فَازَ بِالرُّتْبَةِ الأُولَى فِي السِّبَاقِ"" : الْمَنْزِلَةُ الأُولَى. 2.""اِحْتَلَّ رُتْبَةً عَالِيَةً"" : مَكَانَةً عَالِيَةً. 3.""الرُّتْبَةُ العَسْكَرِيَّةُ"" : الدَّرَجَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9410, 'رُتَبٌ', 'رتب', 'جامد', '', 'رتب', 'رتب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9411, 'رَواتِبُ', 'رواتب', 'جامد', 'رتب', 'رواتب', 'رتب', '', '', '', 'مفرد', '', '', '', '"مفردرَاتِب"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""يُؤَدِّي الْمُؤْمِنُ رَواتِبَهُ الدِّينِيَّةَ"" : واجِباتِهِ، فَرائِضَهُ الدِّينِيَّةَ. 2.""يَتَسَلَّمُ الْمُوَظَّفونَ الرَّواتِبَ في آخِرِ الشَّهْرِ"" : ما يَتَقاضَوْنَهُ مُقابِلَ أَداءِ واجِباتِهِمْ."', '');
