INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9415, 'رُتَّةٌ', 'رتة', 'جامد', 'رتت', 'رتة', 'رتة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رُتَّةٌ-رُتَّةٌ [ر ت ت]. ""فِي لِسَانِهِ رُتَّةٌ"" : عُجْمَةٌ، أَيِ التَّرَدُّدُ فِي النُّطْقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9416, 'رَتٌّ', 'رت', 'جامد', 'رتت', 'رت', 'رت', '', '', '', 'مفرد', 'DnN', '', '', '"رُتُوتٌ:رَتَتَةٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""هُوَ رَتُّ القَوْمِ"": سَيِّدُهُمْ، رَئِيسُهُمْ. ""هُوَ مِنْ رُتُوتِ النَّاسِ"" : أيْ مِنْ رُؤَسَائِهِمْ. 2. ""الرَّتُّ"" (حو).: الخِنْزِيرُ الوَحْشِيُّ."', '');
