INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9419, 'أُرْتِجَ', 'أرتج', 'جامد', 'رتج', 'ءرتج', 'رتج', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'N', '', '"أُرْتِجَ-أُرْتِجَ [ر ت ج]. ""أُرْتِجَ عَلَى الخَطِيبِ"" : اِسْتَغْلَقَ عَلَيْهِ الكَلاَمُ. ""أُرْتِجَ عَلَيْهِ وَانْعقَدَ لِسَانُهُ لَوْعَةً"" ""وَلَمَّا أَرَادَ الكَلاَمَ أُرْتِجَ عَلَيْهِ"". (جبران خ. جبران)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9420, 'رِتَاجَةٌ', 'رتاجة', 'جامد', 'رتج', 'رتاجة', 'رتجة', '', '', '', 'مفرد', 'DnN', '', '', '"رَتَائِجُ"', '', 'R', '', '', '', '', '', '', '". 1.""رِتَاجَةُ الجَبَلِ"" : كُلُّ طَرِيقٍ ضَيِّقٍ بِدَاخِلِ الجَبَلِ. 2.""اِعْتَلَى الرِّتَاجَةَ"" : الصَّخْرَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9421, 'رَتَائِجُ', 'رتائج', 'جامد', '', 'رتاءج', 'رتج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
