INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9432, 'رَثٌّ', 'رث', 'جامد', 'رثث', 'رث', 'رث', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"رِثَاثٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""يَرْتَدِي ثَوْباً رَثَّاً"" : بَالِياً، مُتَّسِخاً، مُمَزَّقاً. ""مَتَاعٌ رَثٌّ"". 2.""رَأيْتُهُ رَثَّ الهَيْئَةِ"" : قَبِيحَ الْمَنْظَرِ. 3. ""كَلاَمٌ غَثٌّ رَثٌّ"" : سَخِيفٌ."', '');
