INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9434, 'رَثْمَةٌ', 'رثمة', 'جامد', 'رثم', 'رثمة', 'رثمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', 'N', 'O', 'O', 'O', '', '"رُثْمَةٌ-رُثْمَةٌ [ر ث م]. ""رُثْمَةُ الفَرَسِ"" : بَيَاضٌ فِي طَرَفِ أنْفِهِ أوْ بَيَاضٌ فِي شَفَتِهِ العُلْيَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9435, 'رُثْمَةٌ', 'رثمة', 'جامد', 'رثم', 'رثمة', 'رثمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', 'N', 'O', 'O', 'O', '', '"رَثْمَةٌ-رَثْمَةٌ [ر ث م]. 1.""أصَابَتِ الأَرْضَ رَثْمَةٌ مِنَ الْمَطَرِ"": شَيْءٌ قَلِيلٌ وَضَعِيفٌ مِنَ الْمَطَرِ. 2.""بَلَغَتْهُ رَثْمَةٌ مِنَ الخَبَرِ"" : طَرَفٌ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9436, 'مَرْثَاةٌ', 'مرثاة', 'جامد', 'رثو،رثي', 'مرثاة', 'مرثة', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاثٍ:الْمَرَاثِي"', '', '', '', '', '', '', '', '', '". ""أَنْشَدَ مَرْثَاةً"" : مَا يُرْثَى بِهِ الْمَيِّتُ مِنْ شِعْرٍ أَوْ نَثْرٍ."', '');
