INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9440, 'رَثْيَةٌ', 'رثية', 'جامد', 'رثي', 'رثية', 'رثة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَثْيَةٌ-رَثْيَةٌ [ر ث ي]. 1.""فِي أَمْرِهِ رَثْيَةٌ"" : ضَعْفٌ وَفُتُورٌ. 2.""بِهِ رَثْيَةٌ"" : حُمْقٌ. 3.""أُصِيبَ بِالرَّثْيَةِ"" : دَاءُ الْمَفَاصِلِ، وَهُوَ مَا يُعْرَفُ بِالرُّومَاتِزْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9441, 'مُرْجِئَةٌ', 'مرجئة', 'جامد', 'رجأ', 'مرجءة', 'مرجة', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مُرْجِئَةٌ-مُرْجِئَةٌ [ر ج أ]. : فِرْقَةٌ إِسْلاَمِيَّةٌ، تَمَيَّزَتْ بِحِيَادِهَا مِنَ الصِّرَاعِ عَلى الْخِلاَفَةِ، رَفَضَتْ أَنْ تَحْكُمَ عَلَى أَحَدٍ مِنَ الْمُسْلِمِينَ بِشَيْءٍ، وَأَرْجَأَتِ الْحُكْمَ إِلَى يَوْمِ القِيَامَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9442, 'رَاجِبَةٌ', 'راجبة', 'جامد', 'رجب', 'راجبة', 'رجبة', '', '', '', 'مفرد', 'DnN', '', '', '"رَوَاجِبُ"', '', 'R', '', '', '', '', '', '', '". ""رَواجِبُ الأَصَابِعِ"" : مَفَاصِلُ أُصُولِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9443, 'رَوَاجِبُ', 'رواجب', 'جامد', '', 'رواجب', 'رجب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9444, 'رُجْبٌ', 'رجب', 'جامد', 'رجب', 'رجب', 'رجب', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْجَابٌ"', '', 'R', '', '', '', '', '', '', '".: رَأْسُ الضِّلْعِ مِنْ نَاحِيَةِ الصَّدْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9445, 'أَرْجَابٌ', 'أرجاب', 'جامد', '', 'ءرجاب', 'رجب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9446, 'رَجَبٌ', 'رجب', 'جامد', '', 'رجب', 'رجب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَرْجَابٌ:رُجُوبٌ"', '', 'R', '', 'N', 'N', 'N', 'O', '', '"ج: أَرْجَابٌ، رُجُوبٌ : الشَّهْرُ السَّابِعُ مِنَ السَّنَةِ الهِجْرِيَّةِ يَأْتِي بَعْدَ جُمَادَى الثَّانِيَةِ وَيَلِيهِ شَعْبَانُ، عَدَدُ أيَّامِهِ (30) يَوْماً أو (29) يَوْماً. ""عِشْ رَجَباً تَرَ عَجَباً"" (مثل)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9447, 'أَرْجَابٌ', 'أرجاب', 'جامد', '', 'ءرجاب', 'رجب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
