INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9449, 'رَجَّةٌ', 'رجة', 'جامد', 'رجج', 'رجة', 'رجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"رَجَّةٌ-رَجَّةٌ [ر ج ج]. 1. ""رَجَّةُ الأَرْضِ"" : اِهْتِزَازُهَا، زِلْزَالٌ خَفِيفٌ. 2. ""أَحْدَثَ البَاعَةُ رَجَّةً فِي السُّوقِ"" : ضَوْضَاءً، فَوْضىً، اِخْتِلاَطُ الأصْوَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9450, 'أُرْجُوحَةٌ', 'أرجوحة', 'جامد', 'رجح', 'ءرجوحة', 'رجحة', '', '', '', 'مفرد', 'DnN', '', '', '"أَرَاجِيحُ"', '', 'R', '', '', '', '', '', '', '". 1.""أَحَاطَ الأَطْفَالُبالأُرْجُوحَةِ يَدْفَعُ أَحَدُهُمُ الآخَرَ"" : خَشَبَةٌ مُعَلَّقَةٌ بِتَوَازُنٍ بَيْنَ حَبْلَيْنِ مَشْدُودَيْنِ إلى عَمُودَيْنِ أَوْ شَجَرَتَيْنِ، يَرْكَبُهَا شَخْصٌ وَاحِدٌ بَيْنَمَا يَدْفَعُ بِـهِ الآخَرُ لِيتَأَرْجَحَ فِي الفَضَاءِ. 2.""اِسْتَلْقَى فِي أُرْجُوحَةِ النَّوْمِ، يَتَأَرْجَحُ فِي هُدُوءٍ"" : ثَوْبٌ مُعَلَّقٌ مَشْدُودٌ مِـنْ طَرَفَيْهِ بَيْنَ حَبْلَيْنِ وَهُمَا مَشْدُودَيْنِ إلى عَمُودَيْنِ أَوْ شَجَرَتَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9451, 'أَرَاجِيحُ', 'أراجيح', 'جامد', '', 'ءراجيح', 'رجح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
