INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9453, 'أُرْجُوزَةٌ', 'أرجوزة', 'جامد', 'رجز', 'ءرجوزة', 'رجزة', '', '', '', 'مفرد', 'DnN', '', '', '"أَرَاجِيزُ"', '', 'R', '', '', '', '', '', '', '". ""يَحْفَظُ أَرَاجِيزَ كَثِيرَةً"": قَصَائِدَ شِعْرِيَّةً مِنْ بَحْرِ الرَّجَزِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9454, 'أَرَاجِيزُ', 'أراجيز', 'جامد', '', 'ءراجيز', 'رجز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9455, 'رَجَزٌ', 'رجز', 'جامد', '', 'رجز', 'رجز', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": بَحْرٌ مِنْ بُحُورِ الشِّعْرِ العَرَبِيِّ وَيُسَمَّى حِمارَ الشُّعَراءِ لِسُهولَةِ النَّظْمِ فيهِ، وَبِهِ تُنْظَمُ الْمَنْظوماتُ التَّعْليمِيَّة وَوزْنُهُ : مُسْتَفْعِلُنْ مُسْتَفْعِلُنْ مُسْتَفْعِلُنْ*مُسْتَفْعِلُنْ مُسْتَفْعِلُنْ مُسْتَفْعِلُنْ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9456, 'رِجْزٌ', 'رجز', 'جامد', '', 'رجز', 'رجز', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1. ""اِرْتَكَبَ رِجْزاً"" : إثْماً، ذَنْباً. 2.""دَخَلَهُ الرِّجْزُ"": الوَسْواسُ.الأنفال آية 11 وَيُنَزِّلُ عَلَيْكُمْ مِنَ السَّمَاءِ مَاءً لِيُطَهِّرَكُمْ بِهِ وَيُذْهِبَ عَنْكُمْ رِجْزَ الشَّيْطَانِ (قرآن). 3.""أَتَى رِجْزاً"" : عَمَلاً قَبِيحاً، قَذِراً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9457, 'رِجْسٌ', 'رجس', 'جامد', 'رجس', 'رجس', 'رجس', '', '', '', 'مفرد', 'DnN', '', '', '"أرْجَاسٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَتى رِجْساً"" : أتَى عَمَلاً دَنِيئاً، قَذِراً، قَبيحاً. 2.المائدة آية 19 إنَّمَا الخَمْرُ وَالْمَيْسِرُ وَالأَنْصَابُ وَالأَزْلامُ رِجْسٌ مِن عَمَلِ الشَّيْطَانِ (قرآن) : الإثْمُ الحَرَامُ. 3.""رِجْسُ الشَّيْطَانِ"" : وَسْوَسَتُهُ. 4.""عَلَيْهِ الرِّجْسُ"" : اللَّعْنَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9458, 'أرْجَاسٌ', 'أرجاس', 'جامد', '', 'ءرجاس', 'رجس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
