INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9463, 'رُجُعٌ', 'رجع', 'جامد', '', 'رجع', 'رجع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9464, 'مَرَاجِعُ', 'مراجع', 'جامد', 'رجع', 'مراجع', 'مرجع', '', '', '', 'مفرد', '', '', '', '"مفردمَرْجِع"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""مَرَاجِعُ الكِتَابِ"" : مَصَادِرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9465, 'مَرْجِعٌ', 'مرجع', 'جامد', 'رجع', 'مرجع', 'مرجع', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاجِعُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَرْجِعُهُ مِنْ حَيْثُ أَتَى"" : عَوْدَتُهُ، مَآلُهُ، مَرَدُّهُ.المائدة آية 48 إِلَى الله مَرْجِعُكُمْ (قرآن). 2.""مَرْجِعِي فِي اللُّغَةِ هُوَ الْمُعْجَمُ"" : مَا أَعُودُ إِلَيْهِ عِنْدَ الْحَاجَةِ، الْمَصْدَرُ ""مَرَاجِعُ البَحْثِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9466, 'مَرَاجِعُ', 'مراجع', 'جامد', '', 'مراجع', 'مرجع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9467, 'أَرَاجِيفُ', 'أراجيف', 'جامد', 'رجف', 'ءراجيف', 'رجف', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"أَرَاجِيفُ-أَرَاجِيفُ [ر ج ف]. ""لاَ يَحْكِي إلاَّ الأرَاجِيفَ"" : الأخْبَارَ الكَاذِبَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9468, 'مِرْجَفَةٌ', 'مرجفة', 'جامد', 'رجف', 'مرجفة', 'مرجفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مِرْجَفَةٌ-مِرْجَفَةٌ [ر ج ف]. ""مِرْجَفَةُ الزِّلْزَالِ"" : آلَةٌ دَقِيقَةٌ تُسَجِّلُ حُدُوثَ الزِّلْزَالِ، مُدَّتَهُ وَقُوَّتَهُ وَالسَّاعَةَ الَّتِي حَدَثَ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9469, 'رَجُلَةٌ', 'رجلة', 'جامد', 'رجل', 'رجلة', 'رجلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"رِجْلَةٌ-رِجْلَةٌ (نب).: بَقْلَةٌ عُشْبِيَّةٌ مِنْ فَصِيلَةِ الرِّجْلِيّات. حَوْلِيَّةٌ بَرِّيَّةٌ زِرَاعِيَّةٌ، سُوقُها وَأوْرَاقُها لَحْمِيَّةُ النَّسِيجِ، لَهَا بزُورُ دِقاقٌ، قَلِيلَةُ الحُمُوضَةِ، يُؤْكَلُ وَرَقُهَا مَطْبُوخاً وَنَيِّئاً، تُسْهِلُ الْمَعِدَةَ فِي حَالَةِ الإِكْثَارِ مِنْهَا، تُعْرَفُ بِالبَقْلَةِ الحَمْقَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9470, 'رِجْلَةٌ', 'رجلة', 'جامد', 'رجل', 'رجلة', 'رجلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رَجُلَةٌ-رَجُلَةٌ [ر ج ل]. 1.""اِرْتَفَعَ صَوْتُ الرَّجُلَةِ"" : الْمَرْأَة. 2.""اِمْرَأَةٌ رَجُلَةٌ"" : تَشَبَّهَتْ بِالرِّجالِ في الرَّأْيِ والْمَعْرِفَةِ. ""كانَتْ عائِشَةُ رَضِيَ اللهُ عَنْها رَجُلَةَ الرَّأْيِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9471, 'رَجُلٌ', 'رجل', 'جامد', 'رجل', 'رجل', 'رجل', '', '', '', 'مفرد', 'DnN', '', '', '"رِجَالٌ:رِجَالاَتٌ"', '', 'R', '', '', '', '', '', '', '". 1.""كَانَ الرَّجُلَ الوَحِيدَ بَيْنَ النِّسَاءِ"" : أي الإِنْسَانَ الذَّكَرَ عَكْسَ الْمَرْأَةِ. ""يَتَسَاوى الرَّجُلُ وَالْمَرْأةُ فِي الحُقُوقِ وَالوَاجِبَاتِ"". 2.""رَجُلُ الأَعْمَالِ"" : مَنْ يَشْتَغِلُ بِشُؤُونِ التِّجَارَةِ وَالاقْتِصَادِ. 3.""رَجُلُ السَّاعَةِ"" : الَّذِي يَتَوَلَّى إِنْجَازَ الْمَهَامَّ الصَّعْبَةِ فِي اللَّحَظَاتِ الحَرِجَةِ. 4.""رَجُلُ الدَّوْلَةِ"" : مَنْ لَهُ مَسْؤُولِيَّةٌ فِي جِهَازِ الدَّوْلَةِ. 5.""رِجَالُ الْمَطَافِئِ"" : العَامِلُونَ فِي جِهَازِ الإِطْفَاءِ، يُسْرِعُونَ لِإِطْفَاءِ الْحَرَائِقِ. 6.""هُوَ مِنْ رِجَالاَتِ قَوْمِهِ"" : مِنْ كِبَارِهَا وَسَادَتِهَا وَعُظَمَائِهَا. ""زَارَ مَقامَ سَبْعَةِ رِجَالٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9472, 'رِجَالٌ', 'رجال', 'جامد', '', 'رجال', 'رجل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9473, 'رِجَالاَتٌ', 'رجالات', 'جامد', '', 'رجالات', 'رجلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9474, 'رِجْلٌ', 'رجل', 'جامد', 'رجل', 'رجل', 'رجل', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْجُلٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَقَفَ عَلَى رِجْلٍ وَاحِدَةٍ"" : قَدَمٌ. 2.""جَلَسَ عِنْدَ رِجْلِ الجَبَلِ"" : عِنْدَ قَدَمِهِ، في سَفْحِهِ، في أَسْفَلِهِ. 3.""رِجْلُ البَحْرِ"" : خَليجُهُ. 4.""رِجْلُ الجَرادِ"" : الطَّائِفَةُ الكَبيرَةُ مِنْهُ. 5.""رِجْلُ العِجْلِ"" : قائِمَتُهُ. 6.""حَيَوَانٌ كَثِيرُ الأَرْجُلِ"" : صِفَةٌ تُطْلَقُ عَلَى الحَيَوَانَاتِ الْمَفْصِلِيَّةِ الْمُتَقَدِّمَةِ الْمَخَالِبِ. 7.""كَانَ يُقَدِّمُ رِجْلاً وَيُؤَخِّرُ أُخْرَى"" : عِبَارَةٌ تُقَالُ لِمَنْ يَتَرَدَّدُ فِي أُمُورِهِ وَلاَ يَحْسِمُ فِيهَا. ""لاَ يَعْرِف يَدَ الشَّيْءِ مِنْ رِجْلِهِ"". 8.""اِنْقَطَعَتِ الرِّجْلُ فِي مُنْتَصَفِ اللَّيْلِ"" : خَلاَ الطَّرِيقُ مِنَ الْمَارَّةِ. 9.""لاَ تَمْشِ بِرِجْلِ مَنْ أبَى"" (مثل) : لاَ تَسْتَعِنْ بِمَنْ لاَ يَهْتَمُّ بِكَ. 10.""رِجْلُ الغُرَابِ"" (نب) : نَباتٌ جُذُورُهُ سَطْحِيَّةٌ مُسْتَطِيلَةٌ، أزْهَارُهَا صُفْرٌ، يُطْبَخُ وَيُؤْكَلُ. 11.""رِجْلُ الجَبَّارِ""، ""رِجْلُ الجَوْزاءِ"" : كَواكِبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9475, 'أَرْجُلٌ', 'أرجل', 'جامد', '', 'ءرجل', 'رجل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9476, 'مِرْجَلٌ', 'مرجل', 'جامد', 'رجل', 'مرجل', 'مرجل', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاجِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""يَغْلِي مَا فِي المِرْجَلِ"": القِدْرُ مِنْ طِينٍ أَوْ مَعْدِنٍ. 2.""جَاشَتْ مَرَاجِلُهُ"" : اِشْتَدَّ غَضَبُهُ. ""وَغَلَى مِرْجَلُ الغَيْظِ فِي نُفُوسِهِمْ"". (ع. غلاب). 3.: خَزَّانُ الْمَاءِ فِي الآلاَتِ البُخَارِيَّةِ. 4.: جِهَازٌ تَتِمُّ بِهِ عَمَلِيَّةُ تَوْلِيدِ البُخَارِ مِنَ الْمَاءِ أَوْ غَيْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9477, 'مَرَاجِلُ', 'مراجل', 'جامد', '', 'مراجل', 'مرجل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9478, 'رِجْلِيَّاتٌ', 'رجليات', 'جامد', '', 'رجليات', 'رجلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِن ذَوَاتِ الفِلْقَتَيْنِ، كَثِيرَةُ القُعالاَتِ، أَجْنَاسُها وَأَنْوَاعُها عَدِيدَةٌ، أَشْهَرُ نَبَاتاتِهَا الرِّجْلَةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9479, 'رِجَامٌ', 'رجام', 'جامد', 'رجم', 'رجام', 'رجم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رِجَامٌ-رِجَامٌ [ر ج م]. 1.: مِرْجَاسٌ. 2.: مَا يُبْنَى عَلَى البِئْرِ فَتُجْعَلُ عَلَيِْهِ الخَشَبَةُ للِدَّلْوِ. 3.""الرِّجَامانِ"" : خشَبَتانِ تُنْصَبَانِ علَى البِئْرِ فَتُجْعَلُ فِيهِما البَكَرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9480, 'رُجْمَةٌ', 'رجمة', 'جامد', 'رجم', 'رجمة', 'رجمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رُجْمَةٌ-رُجْمَةٌ [ر ج م]. ""وَضَعَتْ رُجْمَةً عَلَى قَبْرِ زَوْجِهَا"" : نَصَبَتْ عَلَيْهِ عَلاَمَةً أَوْ حِجَارَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9481, 'رَجَمٌ', 'رجم', 'جامد', 'رجم', 'رجم', 'رجم', '', '', '', 'مفرد', 'DnN', '', '', '"رِجَامٌ:أَرْجَامٌ"', '', 'R', '', '', '', '', '', '', '". ""رَجَمُ القَبْرِ"" : حِجَارَةٌ تُوضَعُ علَى القَبْرِ. ""رَجَمُ البِئْرِ"" ""رَجَمُ التَّنُّورِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9482, 'رِجَامٌ', 'رجام', 'جامد', '', 'رجام', 'رجم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9483, 'أَرْجَامٌ', 'أرجام', 'جامد', '', 'ءرجام', 'رجم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9484, 'رُجُمٌ', 'رجم', 'جامد', 'رجم', 'رجم', 'رجم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رُجُمٌ-رُجُمٌ [ر ج م]. 1.""رُجُمُ السَّمَاءِ"" : مَا يَظْهَرُ فِي السَّمَاءِ كَأنَّهَا نُجُومٌ تَتَسَاقَطُ. 2.""رُجُمُ القَبْرِ"" : حِجَارَةٌ تُنْصَبُ عَلَى القَبْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9485, 'أَرْجاءُ', 'أرجاء', 'جامد', 'رجو', 'ءرجاء', 'رج', '', '', '', 'مفرد', '', '', '', '"مفردرَجاءمُثَنَّاهرَجَوان"', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '". ""أَرْجاءُ الْمَعْمورَةِ"" : رِحابُها. ""بادِيَةٌ مُنْبَسِطَةٌ فَسيحَةُ الأَرْجاءِ"". (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9486, 'رَجاء', 'رجاء', 'جامد', '', 'رجاء', 'رج', '', '', '', 'جمع تكسير', 'DzDw', '', '', '"مُثَنَّاهرَجَوان"', '', 'RzRw', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9487, 'تَرْحَابٌ', 'ترحاب', 'جامد', 'رحب', 'ترحاب', 'ترحب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَرْحَابٌ-تَرْحَابٌ [ر ح ب]. ""اِسْتَقْبَلَهُ بِتَرْحَابٍ"" : اِسْتَقْبَلَهُ بِبَشاشَةِ الوَجْهِ وَكَلِمَاتِ التَّرْحِيبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9488, 'رُحَابٌ', 'رحاب', 'جامد', 'رحب', 'رحاب', 'رحب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رُحَابٌ-رُحَابٌ [ر ح ب]. ""قِدْرٌ رُحَابٌ"" : وَاسِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9489, 'رَحْبَةٌ', 'رحبة', 'جامد', 'رحب', 'رحبة', 'رحبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":رِحَابٌ"', '', 'R', '', '', '', '', '', '', '"1.""تَجَمَّعَ الجُنُودُ فِي سَاحَةٍ رَحْبَةٍ"" : فِي سَاحَةٍ وَاسِعَةٍ. 2.""اِتَّسَعَتْ رَحْبَةُ الدَّارِ بِكُلِّ الضُّيُوفِ"" : سَاحَتُهَا. ""رَحْبَةُ الْمَسْجِدِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9490, 'رِحَابٌ', 'رحاب', 'جامد', '', 'رحاب', 'رحب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9491, 'رَحْبٌ', 'رحب', 'جامد', 'رحب', 'رحب', 'رحب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَحْبٌ-رَحْبٌ [ر ح ب]. 1.""اِسْتَقَرُّوا فِي مَكَانٍ رَحْبٍ"" : مُتَّسِعٍ، وَاسِعٍ. 2.""اِسْتَمَعَ إلَيْهِ بِصَدْرٍ رَحْبٍ"" : بِصَبْرٍ وَأَنَاةٍ. 3.""رَحْبُ الذِّرَاعِ"" : شَدِيدُ البَأْسِ، قَوِيُّ المِرَاسِ. 4.""رَحْبُ البَاعِ أَوِ الذِّرَاعِ"" : الكَرِيمُ السَّخِيُّ. 5.""رَحْبُ الفَهْمِ"" : مُتَّسِعُ الفَهْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9492, 'مَرْحَبٌ', 'مرحب', 'جامد', 'رحب', 'مرحب', 'مرحب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'N', '', '"مَرْحَبٌ-مَرْحَبٌ [ر ح ب]. 1.""مَكَانٌ مَرْحَبٌ"" : وَاسِعٌ. 2.""مَرْحَباً بِكَ يَا سَيِّدِي"" : عِبَارَةٌ تُقَالُ لِلضَّيْفِ، أَيْ صَادَفْتَ سَعَةً وَرَحْباً. ""أَهْلاً وَسَهْلاً وَمَرْحَباً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9493, 'مِرْحَاضٌ', 'مرحاض', 'جامد', 'رحض', 'مرحاض', 'مرحض', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاحِيضُ"', '', 'R', '', '', '', '', '', '', '". 1.: مَكَانُ الاغْتِسَالِ،الْمُغْتَسَلُ، بَيْتُ النَّظَافَةِ، الكَنِيفُ، بَيْتُ الخَلاَءِ. 2.""خَشَبَةٌ يُضْرَبُ بِها الثَّوْبُ عِنْدَ غَسْلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9494, 'مَرَاحِيضُ', 'مراحيض', 'جامد', '', 'مراحيض', 'مرحض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9495, 'رُحَاقٌ', 'رحاق', 'جامد', 'رحق', 'رحاق', 'رحق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رُحَاقٌ-رُحَاقٌ [ر ح ق]. 1.""تَنَاوَلَ رُحَاقاً"" : خَمْراً. 2.""اِخْتَارَ رُحَاقاً"" : خَمْراً صَافِيَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9496, 'تَرْحِيلٌ', 'ترحيل', 'جامد', 'رحل', 'ترحيل', 'ترحل', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرْحِيلٌ-تَرْحِيلٌ [ر ح ل]. ""أَمَرَ بِتَرْحِيلِهِ"" : فَرَضَ الرَّحِيلَ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9497, 'رَاحِلَةٌ', 'راحلة', 'جامد', 'رحل', 'راحلة', 'رحلة', '', '', '', 'مفرد', 'DnN', '', '', '"رَوَاحِلُ"', '', 'R', '', '', '', '', '', '', '". ""شَدَّ رَاحِلَتَهُ"" : اِسْتَعَدَّ لِلرِّحْلَةِ، للسَّفَرِ عَلَى النَّجِيبِ مِنَ الإِبِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9498, 'رَوَاحِلُ', 'رواحل', 'جامد', '', 'رواحل', 'رحل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9499, 'رُحْلَةٌ', 'رحلة', 'جامد', 'رحل', 'رحلة', 'رحلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رُحْلَةٌ-رُحْلَةٌ [ر ح ل]. 1.""سَتَكُونُ رُحْلَتُنَا فِي الشَّهْرِ الْمُقْبِلِ إلَى شَمَالِ البِلاَدِ"" : الجِهَةُ الَّتِي سَوْفَ يُتَّجَهُ إلَيْهَا. ""الكَعْبَةُ رُحْلَةُ الْمُسْلِمِينَ"" ""أَنْتُمْ رُحْلَتِي"". 2.""بَعِيرٌ ذُو رُحْلَةٍ وَرَحْلَةٍ"": قَوِيٌّ شَدِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9500, 'رُحَّلٌ', 'رحل', 'جامد', 'رحل', 'رحل', 'رحل', '', '', '', 'مفرد', '', '', '', '"مفردرَاحِل"', '', 'R', '', '', '', '', '', '', '". ""عَاشَرَ العَرَبَ الرُّحَّلَ"" : جَمَاعَاتٍ مِنَ العَرَبِ القُدَمَاءِ لَمْ يَكُونُوا يَسْتَقِرُّونَ فِي مَكَانٍ مُعَيَّنٍ، إذْ يَقْضُونَ كُلَّ حَيَاتِهِمْ فِي التَّرْحَالِ حَيْثُ العُشْبُ وَالكَلأُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9501, 'مَرْحَلَةٌ', 'مرحلة', 'جامد', 'رحل', 'مرحلة', 'مرحلة', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاحِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""قَطَعَ الْمَرْحَلَةَ الأُولَى مِنْ سَفَرِهِ"" : الْمَسَافَةُ الَّتِي يَقْطَعُهَا الْمُسَافِرُ. 2.""مَا زَالَ فِي الْمَرْحَلَةِ الأُوْلَى"" : فِي الطَّوْرِ الأَوَّلِ. ن. مَرَاحِلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9502, 'مَرَاحِلُ', 'مراحل', 'جامد', '', 'مراحل', 'مرحل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9503, 'رَحْمَانُ', 'رحمان', 'جامد', 'رحم', 'رحمان', 'رحمن', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'O', 'N', 'O', '', '"رَحْمَانُ-رَحْمَانُ [ر ح م]. 1.""هُوَ اللَّهُ الرَّحْمَانُ"" : مِنْ أَسْمَاءِ اللَّهِ الحُسْنَى، أيْ كَثِيرُ الرَّحْمَةِ. ""بِسْمِ اللَّهِ الرَّحْمَانِ الرَّحِيمِ"". 2.: سُورَةٌ مِن سُوَرِ القُرْآنِ. 3.""عَبْدُ الرَّحْمَانِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9504, 'رُحْمَى', 'رحمى', 'جامد', 'رحم', 'رحمى', 'رحم', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"رُحْمَى-رُحْمَى [ر ح م]. ""رُحْمَاكَ يَا رَبُّ"" : الدُّعَاءُ بِالرَّحْمَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9505, 'رَحِمٌ', 'رحم', 'جامد', '', 'رحم', 'رحم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَرْحَامٌ(يُؤَنَّثُوَيُذَكِّر', '', 'R', '', '', '', '', '', '', '"ج: أَرْحَامٌ. (يُؤَنَّثُ وَيُذَكِّر). 1.""بَدَأَ الجَنِينُ يَتَحَرَّكُ فِي رَحِمِ الأُمِّ"" : الْمَوْضِعُ الَّذِي يَسْتَقِرُّ فِيهِ الجَنِينُ فِي بَطْنِ الْمَرْأَةِ. ""يَصِفُونَ الخِلْقَةَ كُلَّهَا حَسَبَ مَا وَصَفَهُ الطَّبِيعِيُّونَ فِي خِلْقَةِ الجَنِينِ فِي الرَّحِمِ"". (ابن طفيل). 2.""ذو رَحِمٍ"" : ذُو قَرَابَةٍ. 3.""صِلَةُ الرَّحِمِ"" : بِرُّ الأقْرِبَاءِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9506, 'أَرْحَامٌ', 'أرحام', 'جامد', '', 'ءرحام', 'رحم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9507, 'رَحَى', 'رحى', 'جامد', 'رحي', 'رحى', 'رح', '', '', '', 'مفرد', 'Dy', '', '', '"أرْحَاءُمُثَنَّاهارَحَوَان"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"رَحَى-رَحَى [ر ح ي]. مُثَنَّاها. رَحَوَان. ج: أرْحَاءُ. 1.""تَطْحَنُ الذُّرَةَفِي الرَّحَى"" : فِي الطَّاحُونِ، وَهِيَ عِبَارَةٌ عَنْ حَجَرَتَيْنِ صَلْبَتَيْنِ نِصْف دَائرَتَيْنِ تُوضَعُ إحْدَاهُمَا علَى الأُخْرَى وَتُدَارُ أعْلاَهَا بِاليَدِ عَلَى قُطْبٍ. 2.""دَارَت رَحَى الحَرْبِ بَيْنَ القَبِيلَتَيْنِ"" : نَشَبَتْ حَوْمَةُ الحَرْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9508, 'أرْحَاءُ', 'أرحاء', 'جامد', '', 'ءرحاء', 'رح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9509, 'رُخٌّ', 'رخ', 'جامد', 'رخخ', 'رخ', 'رخ', '', '', '', 'مفرد', 'DnN', '', '', '"رِخَاخٌ"', '', 'R', '', '', '', '', '', '', '". 1.: طَائِرٌ خُرَافِيٌّ يَرِدُ ذِكْرُهُ فِي الأساطِيرِ. 2. : قِطْعَةٌ مِنْ قِطَعِ الشِّطْرَنْجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9510, 'رِخَاخٌ', 'رخاخ', 'جامد', '', 'رخاخ', 'رخخ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9511, 'رُخْصَةٌ', 'رخصة', 'جامد', 'رخص', 'رخصة', 'رخصة', '', '', '', 'مفرد', 'DnN', '', '', '"رُخَصٌ"', '', 'R', '', '', '', '', '', '', '". 1.""طَلَبَ رُخْصَةً مِنَ الْمُدِيرِ"" : الإذْنَ. 2.""هُوَ فِي رُخْصَةٍ"" : فِي إِجَازَةٍ. 3.""حَصَلَ عَلَى رُخْصَةِ قِيادَةِ السَّيَّارَةِ"" : شَهَادَةٌ تُؤَهِّلُهُ لِقِيَادَةَ السَّيَّارَاتِ. ""رُخْصَةُ صَيْدٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9512, 'رُخَصٌ', 'رخص', 'جامد', '', 'رخص', 'رخص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9513, 'رَخْفَةٌ', 'رخفة', 'جامد', 'رخف', 'رخفة', 'رخفة', '', '', '', 'مفرد', 'DnN', '', '', '"رِخَافٌ"', '', 'R', '', '', '', '', '', '', '"1.""صَارَ الْمَاءُ رَخْفَةً"": طِيناً رَقِيقاً"". 2. : حَجَرٌ رِخْوٌ خَفِيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9514, 'رِخَافٌ', 'رخاف', 'جامد', '', 'رخاف', 'رخف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9515, 'رَخِفَ', 'رخف', 'جامد', '', 'رخف', 'رخف', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'N', '', '"ن: رَخَفَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9516, 'رُخَامٌ', 'رخام', 'جامد', 'رخم', 'رخام', 'رخم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رُخَامٌ-رُخَامٌ [ر خ م]. ""بُنِيَتْ أَعْمِدَةُ القَصْرِ وَجَميعُ رِحَابِهِ بِالرُّخَامِ"" : حَجَرٌ صَلْبٌ أَسْلَسُ تَخْتَلِفُ ألْوَانُهُ مِنْ أسْوَدَ إلَى أبْيَضَ أوْ أزْرَقَ كمَا يتَكَوَّنُ مِنْ كَرْبُونَاتِ الكَلْسِيوم الْمُتَبَلْوِرِ يُصْقَلُ بِسُهُولَةٍ تَخْتَلِفُ أشْكَالُهُ مِنْ مُرَبَّعَاتٍ إلَى مُسْتَطِيلاتٍ. ""تِمْثَالٌ مِنْ رُخَامٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9517, 'رَخْمَةٌ', 'رخمة', 'جامد', '', 'رخمة', 'رخمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"رَخْمَةٌ-رَخْمَةٌ (حو).: حَيَوَانٌ مِنْ فَصِيلةِ النَّسْرِيَّاتِ، مِنْ رُتْبَةِالصَّقْرِيَّات يُشْبِهُ النَّسْرَ، لَهُ مِنْقَارٌ طَوِيلٌ مُقَوَّسٌ، رِيشُهُ غَزِيرٌ، يَخْتَلِطُ بِهِ السَّوَادُ وَالبَيَاضُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9518, 'رُخَاءٌ', 'رخاء', 'جامد', 'رخو', 'رخاء', 'رخ', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"رُخَاءٌ-رُخَاءٌ [ر خ و]. ""هَبَّتِ الرُّخَاءُ"" : رِيحٌ لَيِّنَةٌ لاَ تُحَرِّكُ شَيْئاً. ص آية 36 فَسَخَّرْنا لَهُ الرِّيحَ تَجْري بِأَمْرِهِ رُخاءً حَيْثُ أَصابَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9519, 'رَدَاءةٌ', 'رداءة', 'جامد', '', 'رداءة', 'ردة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '": المِلْحَفَةُ يُشْتَمَلُ بِهَا. ن. رِدَاءٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9520, 'مَرَدٌّ', 'مرد', 'جامد', 'ردد', 'مرد', 'مرد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَرَدٌّ-مَرَدٌّ [ر د د]. 1.""مَرَدُّ ذَلِكَ ضُعْفُ بَصَرِهِ"" : سَبَبُ ذَلِكَ، مَايُعْزَى إِلَيْهِ. 2.""لاَ مَرَدَّ لَهُ"" : لاَ يُقَاوَمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9521, 'رَادِفَةٌ', 'رادفة', 'جامد', 'ردف', 'رادفة', 'ردفة', '', '', '', 'مفرد', 'DnN', '', '', '"رَوَادِفُ"', '', 'R', '', '', '', '', '', '', '". 1.النازعات آية 6 يَوْمَ تَرْجُفُ الرَّاجِفَةُ تَتْبَعُهَا الرَّادِفَةُ (قرآن) : النَّفْخَةُ فِي الصُّورِ يَوْمَ القِيامَةِ. 2.""رَادِفَةُ الإِنْسانِ"" : عَجُزُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9522, 'رَوَادِفُ', 'روادف', 'جامد', '', 'روادف', 'ردف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9523, 'رِدْفٌ', 'ردف', 'جامد', 'ردف', 'ردف', 'ردف', '', '', '', 'مفرد', 'DnN', '', '', '"أرْدَافٌ"', '', 'R', '', '', '', '', '', '', '". 1.""كَانَ لَهُ رِدْفاً"" : تَابِعاً لَهُ، وَتُقَالُ لِلرَّاكِبِ خَلْفَ الرَّاكِبِ عَلَى حِصَانٍ أوْ دَرَّاجَةٍ. 2. ""جَاءتْ تَتَمايَلُ بِأرْدَافِهَا"" : بِعَجُزِهَا، بِكَشْحِهَا، أَيْ مَا بَيْنَ السُّرَّة وَوَسَطِ الظَّهْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9524, 'أرْدَافٌ', 'أرداف', 'جامد', '', 'ءرداف', 'ردف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9525, 'رَوادِفُ', 'روادف', 'جامد', 'ردف', 'روادف', 'ردف', '', '', '', 'مفرد', '', '', '', '"مفردرادِفَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ن. رادِفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9526, 'رَدْهَةٌ', 'ردهة', 'جامد', 'رده', 'ردهة', 'ردهة', '', '', '', 'مفرد', 'DnN', '', '', '"رَدْهٌ:رَدَاهٌ"', '', 'R', '', '', '', '', '', '', '". ""رَدْهَةُ البَيْتِ"" : الْمَمَرُّ الكَبِيرُ الَّذِي يَقُودُكَ إلَى وَسَطِ البَيْتِ وَحُجُرَاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9527, 'رَدْهٌ', 'رده', 'جامد', '', 'رده', 'رده', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9528, 'رَدَاهٌ', 'رداه', 'جامد', '', 'رداه', 'رده', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9529, 'رِدَاءٌ', 'رداء', 'جامد', 'ردي', 'رداء', 'رد', '', '', '', 'مفرد', 'DzDw', '', '', '"أرْدِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '". 1. ""تَرْتَدِي رِدَاءً خَفِيفاً"": لِبَاساً يُلْبَسُ فَوْقَ الثِّيَابِ يُشْبِهُ العَبَاءةَ وَالجُبَّةَ. 2.""رِدَاءُ الشَّمْسِ"": نُورُهَا، بَهَاؤُهَا. 3. ""مَا يَزَالُ فِي رِدَاءِ الشَّبَابِ"" : فِي نَضَارَتِهِ وَحُسْنِهِ. 4. ""غَمْرُ الرِّدَاءِ"" : كَثِيرُ الإحْسَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9530, 'أرْدِيَةٌ', 'أردية', 'جامد', '', 'ءردية', 'ردة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9531, 'رَدًى', 'ردى', 'جامد', 'ردي', 'ردى', 'رد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَدىً-رَدىً [ر د ي]. ""جَنَّبَكَ اللَّهُ الرَّدَى"" : الهَلاكَ، الْمَوْتَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9532, 'رَذِيلَةٌ', 'رذيلة', 'جامد', 'رذل', 'رذيلة', 'رذلة', '', '', '', 'مفرد', 'DnN', '', '', '"رَذَائِلُ"', '', '', '', '', '', '', '', '', '".: الخَصْلَةُ الذَّمِيمَةُ. ‎‎""لِكُلِّ أُمَّةٍ فَضَائِلُ وَرَذَائِلُ وَلِكُلِّ قَوْمٍ مَحَاسِنُ وَمَسَاوِئُ"". (التوحيدي) ""أَوَّلُ بَوادِرِ الانْهِزَامِ فِي صِراعِ الفَضِيلَةِ مَعَ الرَّذِيلَةِ أَنْ تَنْكَشِفَ الرَّذِيلَةُ وَتَظْهَرَ بِكَامِلِ قُوَاها"". (إسحق الحسيني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9533, 'رَذَائِلُ', 'رذائل', 'جامد', '', 'رذاءل', 'رذل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9534, 'رُزٌّ', 'رز', 'جامد', '', 'رز', 'رز', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ن. أَرُزٌّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9535, 'رُزْءٌ', 'رزء', 'جامد', 'رزأ', 'رزء', 'رز', '', '', '', 'مفرد', 'Dz', '', '', '"أَرْزَاءٌ"', '', 'Rz', '', '', '', '', '', '', '". ""أُصِيبَ بِرُزْءٍ"" : الْمُصِيبَةُ العَظِيمَةُ شَدِيدَةُ الوَطْأَةِ، الرَّزِيئَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9536, 'أَرْزَاءٌ', 'أرزاء', 'جامد', '', 'ءرزاء', 'رز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9537, 'رَزِيَّةٌ', 'رزية', 'جامد', 'رزأ', 'رزية', 'رزة', '', '', '', 'مفرد', 'DnN', '', '', '"رَزَايَا"', '', '', '', '', '', '', '', '', '". ""رَزِيَّةٌ عَظِيمَةٌ"" : مُصِيبَةٌ عَظِيمَةٌ، رَزِيئَةٌ، رُزْءٌ. ""تَوَالَتْ عَلَيْهِ الرَّزَايَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9538, 'رَزَايَا', 'رزايا', 'جامد', '', 'رزايا', 'رز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9539, 'رَزِيئَةٌ', 'رزيئة', 'جامد', 'رزأ', 'رزيءة', 'رزة', '', '', '', 'مفرد', 'DnN', '', '', '"رَزَايَا"', '', 'R', '', '', '', '', '', '', '". ""رَزَأتْهُ رَزِيئَةٌ"" : أصَابَتْهُ مُصِيبَةٌ، رُزْءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9540, 'رَزَايَا', 'رزايا', 'جامد', '', 'رزايا', 'رز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9541, 'مَرْزِئَةٌ', 'مرزئة', 'جامد', 'رزأ', 'مرزءة', 'مرزة', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَازِئُ"', '', 'R', '', '', '', '', '', '', '". ""كَانَتِ الْحَادِثَةُ مَرْزِئَةً لِلْعَائِلَةِ"" : أَيْ كَارِثَةً، مُصِيبَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9542, 'مَرَازِئُ', 'مرازئ', 'جامد', '', 'مرازء', 'مرز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9543, 'رَزَّةٌ', 'رزة', 'جامد', 'رزز', 'رزة', 'رزة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""أَدْخَلَ القُفْلَ فِي الرَّزَّةِ"": الحَدِيدَةُ الَّتِي يَدْخُلُ فِيهَا القُفْلُ. 2.""وَضَعُوا رَزَّاتٍ فِي الإِسْطَبْلِ لِرَبْطِ الخُيُولِ"" : حَدَائِدُ تُدَقُّ فِي الأَرْضِ أوِ الحَائِطِ لِرَبْطِ الدَّوَابِّ. 3.""وَضَعَ رَزَّةً علَى رَأْسِهِ"" : عِمَامَةً مِنْ ثَوْبٍ طَوِيلٍ تُلَفُّ عَلَى الرَّأْسِ، وَالكَلِمَةُ شَائِعَةٌ بِالْمَغْرِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9544, 'رِزٌّ', 'رز', 'جامد', 'رزز', 'رز', 'رز', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رِزٌّ-رِزٌّ [ر ز ز]. 1.""دَوَّى رِزٌّ"" : صَوْتُ الرَّعْدِ. 2.""سَمِعَ رِزّاً"" : صَوْتاً خَفِيفاً. 3.""رِزُّ الفَحْلِ"" : هَدِيرُهُ. 4.""رِزُّ البَطْنِ"" : قَرْقَرَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9545, 'مَرَزَّةٌ', 'مرزة', 'جامد', 'رزز', 'مرزة', 'مرزة', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَازُّ"', '', 'R', '', '', '', '', '', '', '".: مَوْضِعُ الأَرُزِّ، حُقُولُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9546, 'مَرَازُّ', 'مراز', 'جامد', '', 'مراز', 'مرز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9547, 'رِزْقٌ', 'رزق', 'جامد', 'رزق', 'رزق', 'رزق', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْزَاقٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""سَعى إلَى رِزْقِهِ"" : إلَى مَا يَسْتَرْزِقُ بِهِ، أي الوَسَائِلُ الَّتِي تُمَكِّنُ الْمَرْءَ مِنَ العَيْشِ. البقرة آية 22 وَأَنْزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقاً لَكُمْ (قرآن). 2.""وفِي السَّمَاءِ رِزْقُكُمْ"" : الْمَطَرُ الَّذِي تَنْتَفِعُ بِهِ الأَرْضُ.هود آية 6 وَمَا مِنْ دَابَّةٍ فِي الأَرْضِ إلاَّ عَلَى اللَّهِ رِزْقُها (قرآن) ""قَطْعُ الأرْزَاقِ مِنْ قَطْعِ الأَعْنَاقِ""(مثل). 3.""الرِّزْقُ الشَّهْرِيُّ"" : أي الرَّاتِبُ الَّذِي يَتَقَاضَاهُ العَامِلُ أوِ الْمُوَظَّفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9548, 'أَرْزَاقٌ', 'أرزاق', 'جامد', '', 'ءرزاق', 'رزق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9549, 'رَزْمَةٌ', 'رزمة', 'جامد', 'رزم', 'رزمة', 'رزمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"رَزْمَةٌ-رَزْمَةٌ [ر ز م]. ""تَنَاوَلَ مُجَرَّدَ رَزْمَةٍ"" : أَكْلَةٍ وَاحِدَةٍ فِي اليَوْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9550, 'رِزْمَةٌ', 'رزمة', 'جامد', 'رزم', 'رزمة', 'رزمة', '', '', '', 'مفرد', 'DnN', '', '', '"رِزَمٌ"', '', 'R', '', '', '', '', '', '', '". 1.""مَرَّ حَامِلاً رِزْمَةً عَلَى ظَهْرِهِ"" : حَزْمَةً، صُرَّةً. 2.""حَمَلَ رِزْمَةً مِنَ الكُتُبِ"" : أيْ مَجْمُوعَةً مِنَ الكُتُبِ جُمِعَتْ وَشُدَّتْ معاً. ""أحْرَقَ رِزْمَةً مِنَ الأوْرَاقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9551, 'رِزَمٌ', 'رزم', 'جامد', '', 'رزم', 'رزم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9552, 'رُسُوبِيَّاتٌ', 'رسوبيات', 'جامد', 'رسب', 'رسوبيات', 'رسبت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"رُسُوبِيَّاتٌ-رُسُوبِيَّاتٌ [ر س ب].: الرَّوَاسِبُ مِنَ الأَتْرِبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9553, 'رَواسِبُ', 'رواسب', 'جامد', 'رسب', 'رواسب', 'رسب', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَواسِبُ-رَواسِبُ [ر س ب]. 1.""رَواسِبُ الأَنْهارِ"" : الأَتْرِبَةُ الْمُتَرَسِّبَةِ في قَعْرِهِ. ن. رُسوبِيَّات. 2.""رَواسِبُ الماضِي"" : بَقاياهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9554, 'رِسَاغٌ', 'رساغ', 'جامد', 'رسغ', 'رساغ', 'رسغ', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رِسَاغٌ-رِسَاغٌ [ر س غ]. ""شُدَّتِ الدَّابَّةُ بِرِسَاغٍ"" : حَبْلٌ يُوضَعُ فِي رُسْغِ الدَّابَّةِ وَيُشَدُّ إلَى وَتَدٍ لِيَمْنَعَهَا مِنَ الانْفِلاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9555, 'رُسْغٌ', 'رسغ', 'جامد', 'رسغ', 'رسغ', 'رسغ', '', '', '', 'مفرد', 'DnN', '', '', '"أرْسَاغٌ:أَرْسُغٌ"', '', 'R', '', '', '', '', '', '', '"(تش). 1.""رُسْغُ اليَدِ"" :المِفْصَلُ مَا بَيْنَ الساَّعِدِ والكَـفِّ. 2.""رُسْغُ الرِّجْلِ"" : ما بَيْنَ السَّاقِ وَالقَدَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9556, 'أرْسَاغٌ', 'أرساغ', 'جامد', '', 'ءرساغ', 'رسغ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9557, 'أَرْسُغٌ', 'أرسغ', 'جامد', '', 'ءرسغ', 'رسغ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9558, 'رِسْلٌ', 'رسل', 'جامد', 'رسل', 'رسل', 'رسل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رِسْلٌ-رِسْلٌ [ر س ل]. 1.""عَلَى رِسْلِكَ"" : عَلَى مَهْلِكَ، أيْ سِرْ بِتُؤَدَةٍ وَتَأَنٍّ. 2.""عَيْشٌ رِسْلٌ"" : لَيِّنٌ، سَهْلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9559, 'رِسَامَةٌ', 'رسامة', 'جامد', 'رسم', 'رسامة', 'رسمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رِسَامَةٌ-رِسَامَةٌ [ر س م].: مِهْنَةُ الرَّسَّامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9560, 'رَسْمِيَّاتٌ', 'رسميات', 'جامد', 'رسم', 'رسميات', 'رسمت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"رَسْمِيَّاتٌ-رَسْمِيَّاتٌ [ر س م]. 1.""يَهْتَمُّ كَثِيراً بِالرَّسْمِيَّاتِ"" : التَّقَيُّدُ بِالعَادَاتِ وَالأَعْرَافِ الْمُتَّبَعَةِ فِي الاِحْتِفَالاتِ السِّيَاسِيَّةِ أوِ الدِّينِيَّةِ. 2.""بِلا رَسْمِيَّاتٍ"" : بِلا قُيُودٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9561, 'رَوْسَمٌ', 'روسم', 'جامد', 'رسم', 'روسم', 'رسم', '', '', '', 'مفرد', 'DnN', '', '', '"رَوَاسِمُ"', '', 'R', '', '', '', '', '', '', '". 1.: صَفِيحَةٌ مَعْدِنِيَّةٌ يُحْفَرُ عَلَيْهَا خَطٌّ أَوْ رَسْمٌ تُسْتَعْمَلُ فِي الطِّبَاعَةِ. 2.""وَضَعَ رَوْسَماً"" : رَسْماً، عَلاَمَةً. 3.""رَجُلٌ رَوْسَمٌ"" : دَاهِيَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9562, 'رَوَاسِمُ', 'رواسم', 'جامد', '', 'رواسم', 'رسم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9563, 'مَرَاسِمُ', 'مراسم', 'جامد', 'رسم', 'مراسم', 'مرسم', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"مَرَاسِمُ-مَرَاسِمُ [ر س م]. ""جَرَتْ مَرَاسِمُ الاحْتِفَالاَتِ حَسَبَ التَّقَالِيدِ الْمَرْعِيَّةِ"" : طُقُوسٌ وَتَقَالِيدُ وَعَادَاتٌ وَمَا يَنْبَغِي مُرَاعَاتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9564, 'مَرَاسِيمُ', 'مراسيم', 'جامد', 'رسم', 'مراسيم', 'مرسم', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"مَرَاسِيمُ-مَرَاسِيمُ [ر س م]. ن. مَرْسُومٌ. 1.""مَرَاسِيمُ الرِّئَاسَةِ"" : أَيْ مَا يُقَابِلُ التَّشْرِيفَاتِ فِي الأَنْظِمَةِ الْمَلَكِيَّةِ. 2.""مُدِيرُ الْمَرَاسِيمِ"" : مُدِيرُ التَّشْرِيفَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9565, 'مَرْسَمٌ', 'مرسم', 'جامد', 'رسم', 'مرسم', 'مرسم', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاسِم"', '', 'R', '', '', '', '', '', '', '". ""يَشْتَغِلُ الرَّسَّامُ فِي مَرْسَمِهِ"" : مَعْمَلُ الرَّسْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9566, 'رَسَنٌ', 'رسن', 'جامد', 'رسن', 'رسن', 'رسن', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْسَانٌ:أَرْسُنٌ"', '', 'R', '', '', '', '', '', '', '". ""رَسَنَ الدَّابَّةَ بِالرَّسَنِ"" : رَسَنَهَا بِالحَبْلِ، أيْ بِالزِّمَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9567, 'أَرْسَانٌ', 'أرسان', 'جامد', '', 'ءرسان', 'رسن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9568, 'أَرْسُنٌ', 'أرسن', 'جامد', '', 'ءرسن', 'رسن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9569, 'مِرْسَاةٌ', 'مرساة', 'جامد', 'رسو', 'مرساة', 'مرسة', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاسٍ:الْمَرَاسِي"', '', '', '', '', '', '', '', '', '". ""مِرْسَاةُ السَّفِينَةِ"" : الْحَدِيدَةُ الثَّقِيلَةُ تُلْقَى فِي الْمَاءِ تُثَبِّتُ السَّفِينَةَ فِي مَكَانِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9570, 'مَرَاسِي', 'مراسي', 'جامد', '', 'مراسي', 'مرس', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9571, 'مَرْسًى', 'مرسى', 'جامد', 'رسو', 'مرسى', 'مرس', '', '', '', 'مفرد', 'Dy', '', '', '"مَرَاسٍ:الْمَرَاسِي"', '', '', '', '', '', '', '', '', '". : الْمَرْفَأُ، الْمِينَاءُ، أَيْ مَحَلٌّ عَلَى شَطِّ البَحْرِ خَاصٌّ بِرُسُوِّ السُّفُنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9572, 'مَرَاسِي', 'مراسي', 'جامد', '', 'مراسي', 'مرس', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9573, 'رَسِيٌّ', 'رسي', 'جامد', 'رسي', 'رسي', 'رس', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"رَسِيٌّ-رَسِيٌّ [ر س ي]. 1.""وَضَعُوا أَوَّلاً رَسِيَّ الخَيْمَةِ"" : العَمودَ الرَّئِيسَ الَّذِي يَشُدُّ الخَيْمَةَ. 2.""رَسِيٌّ في مَكانِهِ"" : ثابِتٌ فيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9574, 'رَشَأٌ', 'رشأ', 'جامد', '', 'رشء', 'رش', '', '', '', 'جمع تكسير', 'Dz', '', '', '"أَرْشاءُ"', '', 'Rz', '', '', '', '', '', '', '"ج: أَرْشاءُ (حو).: وَلَدُ الغَزالَةِ الَّذِي قَوِيَ وَبَدَأَ يَمْشِي معَ أُمِّهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9575, 'أَرْشاءُ', 'أرشاء', 'جامد', '', 'ءرشاء', 'رش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9576, 'رَشَدٌ', 'رشد', 'جامد', 'رشد', 'رشد', 'رشد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَشَدٌ-رَشَدٌ [ر ش د]. ن. رُشْدٌ، رَشادٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9577, 'رَشَّاشٌ', 'رشاش', 'جامد', 'رشش', 'رشاش', 'رشش', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَشاشٌ-رَشاشٌ [ر ش ش]. ""تَطايَرَ رَشاشُ الْمَاءِ"" : ما تَرَشَّشَ مِنَ الماءِ أَوْ نَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9578, 'رَشاشٌ', 'رشاش', 'جامد', 'رشش', 'رشاش', 'رشش', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَشَّاشٌ-رَشَّاشٌ [ر ش ش]. ""تَسَلَّحَ الجُنْدِيُّ بِرَشَّاشٍ أُتوماتِيكِيٍّ"": نَوْعٌ مِنَ الأَسْلِحَةِ يُخْرِجُ رَصاصاً مُتَتابِعاً كَأَنَّهُ رَشاشٌ مُتَطايِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9579, 'رَشيشٌ', 'رشيش', 'جامد', 'رشش', 'رشيش', 'رشش', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"رَشيشٌ-رَشيشٌ، ةٌ [ر ش ش]. ""حَمَلَ رَشيشاً"" : أَي بُنْدُقِيَّةً صَغيرَةً رَشَّاشَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9580, 'مِرَشَّةٌ', 'مرشة', 'جامد', 'رشش', 'مرشة', 'مرشة', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاشٌّ"', '', 'R', '', '', '', '', '', '', '". 1.""مِرَشَّةُ البُسْتَانِيِّ"" : آلَةٌ لِرَشِّ الْمَاءِ وَنَحْوِهِ . 2.""مِرَشَّةُ الزَّهْرِ"" : قِنِّينَةٌ مِنَ الْمَعْدِنِ الفِضِّي، لَهَا عُنُقٌ طَوِيلٌ تُمْلَأُ بِمَاءِ الزَّهْرِ لِيُرَشَّ بِهِ الضُّيُوفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9581, 'مَرَاشٌّ', 'مراش', 'جامد', '', 'مراش', 'مرش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9582, 'مَرَاشِفُ', 'مراشف', 'جامد', 'رشف', 'مراشف', 'مرشف', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَرَاشِفُ-مَرَاشِفُ [ر ش ف]. ""عَلَى الْمَرَاشِفِ"" : عَلَى الشِّفَاهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9583, 'مِرْشَفٌ', 'مرشف', 'جامد', 'رشف', 'مرشف', 'مرشف', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاشِفُ"', '', 'R', '', '', '', '', '', '', '". ""مِرْشَفُ العَصِيرِ"": مَا يُمْتَصُّ بِهِ العَصِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9584, 'مَرَاشِفُ', 'مراشف', 'جامد', '', 'مراشف', 'مرشف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9585, 'رَشْقَةٌ', 'رشقة', 'جامد', 'رشق', 'رشقة', 'رشقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"رَشْقَةٌ-رَشْقَةٌ [ر ش ق]. 1.""سَمِعَ الأَهالِي رَشْقَةَ الْمَدافِعِ"" : أَي طَلْقَةَ الْمَدافِعِ عِنْدَما تُطْلَقُ دَفْعَةً واحِدَةً. 2.""رَشْقَةُ اللِّسانِ"": طَعْنَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9586, 'رَشَقٌ', 'رشق', 'جامد', 'رشق', 'رشق', 'رشق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَشَقٌ-رَشَقٌ [ر ش ق]. ""رَماهُ بِرَشَقٍ"" : بِسَهْمٍ سَريعَةٍ رَشيقَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9587, 'رِشْقٌ', 'رشق', 'جامد', 'رشق', 'رشق', 'رشق', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْشاقٌ"', '', 'R', '', '', '', '', '', '', '". 1.""رِشْقُ القَلَمِ"" : صَوْتُهُ أَثْناءَ الكِتابَةِ. 2.: ما يُرْمَى بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9588, 'أَرْشاقٌ', 'أرشاق', 'جامد', '', 'ءرشاق', 'رشق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9589, 'رَوْشَمٌ', 'روشم', 'جامد', 'رشم', 'روشم', 'رشم', '', '', '', 'مفرد', 'DnN', '', '', '"رَواشِمُ"', '', 'R', '', '', '', '', '', '', '". : الخاتَمُ أَوِ اللَّوْحُ الَّذِي تُرْشَمُ بِهِ الحُبوبُ الْمَجْموعةُ في البَيْدَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9590, 'رَواشِمُ', 'رواشم', 'جامد', '', 'رواشم', 'رشم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9591, 'رَشْنٌ', 'رشن', 'جامد', 'رشن', 'رشن', 'رشن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَشْنٌ-رَشْنٌ، رَشَنٌ [ر ش ن]. ""رَشَنُ النَّهْرِ"" : الثُّلْمَةُ في النَّهْرِ، يَنْحَدِرُ فيها الْمَاءُ وَيُسْقَى مِنْها، الشَّقُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9592, 'رِشاءٌ', 'رشاء', 'جامد', 'رشو', 'رشاء', 'رش', '', '', '', 'مفرد', 'DzDw', '', '', '"أَرْشِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '". 1.""وَضَعَتْ غَسيلَها على رِشاءٍ"" : على حَبْلِ الغَسيلِ. 2.""تَقَطَّعَ الرِّشاءُ وَسَقَطَ الدَّلْوُ"" : حَبْلُ الدَّلْوِ. 3.""راقَبَ الرِّشاءَ"" : نَجْمٌ نَيِّرٌ في الحوتِ، وَهُوَ الأَخيرُ مِنْ مَنازِلِ القَمَرِ وَيُسَمَّى بَطْنَ الحوتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9593, 'أَرْشِيَةٌ', 'أرشية', 'جامد', '', 'ءرشية', 'رشة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9594, 'رَشاةٌ', 'رشاة', 'جامد', 'رشو', 'رشاة', 'رشة', '', '', '', 'مفرد', 'DnN', '', '', '"رَشًا"', '', 'Rw', '', '', '', '', '', '', '". ""تَناوَلَ رَشاةً"" : عُشْبَةً تُشْرَبُ للإِسْهالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9595, 'رَشًا', 'رشا', 'جامد', '', 'رشا', 'رش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9596, 'رَشْوَةٌ', 'رشوة', 'جامد', 'رشو', 'رشوة', 'رشة', '', '', '', 'مفرد', 'DnN', '', '', '"رُشًى"', '', 'R', '', '', '', '', '', '', '". ""قَدَّمَ لَهُ رَشْوَةً"" : مالٌ أَوْ هِبَةٌ تُعطَى لِمَسْؤُولٍ لِقَضاءِ حاجَةٍ أَوْ مَصْلَحَةٍ حَقّاً أَوْ باطِلاً. ""يُعَاقِبُ القانونُ كُلَّ مَنْ تَلَقَّى رَشْوَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9597, 'رُشًى', 'رشى', 'جامد', '', 'رشى', 'رش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9598, 'رَصْدَةٌ', 'رصدة', 'جامد', 'رصد', 'رصدة', 'رصدة', '', '', '', 'مفرد', 'DnN', '', '', '"رِصادٌ"', '', 'R', '', '', '', '', '', '', '". : الدُّفْعَةُ مِنَ الْمَطَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9599, 'رِصادٌ', 'رصاد', 'جامد', '', 'رصاد', 'رصد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9600, 'رَصيدٌ', 'رصيد', 'جامد', 'رصد', 'رصيد', 'رصد', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْصِدَةٌ"', '', 'R', '', '', '', '', '', '', '"رَصيدٌ-رَصيدٌ [ر ص د]. 1.""لَهُ رَصيدٌ في الْمَصْرِفِ"" : لَهُ مالٌ مِمَّا أَوْدَعَهُ في حِسابِهِ الْمَصْرِفِيِّ. ""سَلَّمَهُ شِيكاً بِلا رَصيدٍ"". 2.""رَصيدُ الدَّوْلَةِ مِنَ الذَّهَبِ في تَقَلُّصٍ"" : الذَّهَبُ الْمُعْتَمَدُ والضَّامِنُ لإِصْدارِ العُمْلَةِ النَّقْدِيَّةِ. 3.""حَدَّدَ الرَّصيدَ اللُّغَوِيَّ للتَّعْليمِ الأَساسِيِّ"" : الكَمِّيَّةُ اللُّغَوِيَّةُ مِنَ الْمُفْرَداتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9601, 'أَرْصِدَةٌ', 'أرصدة', 'جامد', '', 'ءرصدة', 'رصدة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9602, 'مِرْصَادٌ', 'مرصاد', 'جامد', 'رصد', 'مرصاد', 'مرصد', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاصِيدُ"', '', 'R', '', '', '', '', '', '', '". ""وَقَفَ لَهُ بِالمِرْصَادِ"": مَكَانُ الْمُرَاقَبَةِ يُرْصَدُ فِيهِ. ""كَانَ لَهُ بِالمرْصَادِ"" ""هُوَ لَهُ بِالْمِرصَادِ"" الفجر آية 14 إِنَّ رَبَّكَ لَبِالمرْصَادِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9603, 'مَرَاصِيدُ', 'مراصيد', 'جامد', '', 'مراصيد', 'مرصد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9604, 'مَرْصَدٌ', 'مرصد', 'جامد', 'رصد', 'مرصد', 'مرصد', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاصِدُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَرْصَدُ أَحْوَالِ الطَّقْسِ"" : مَوْضِعٌ بِهِ آلاَتٌ تِقْنِيَّةٌ لِرَصْدِ الأَحْوَالِ الْجَوِّيَّةِ. ""الْمَرْصَدُ الْجَوِّيُّ"". 2.""الْمَرْصَدُ الطَّائِرُ"" : جِهَازٌ يُسَجِّلُ آلِيّاً عِدَّةَ عَنَاصِرَ جَوِّيَّةٍ بِالأَيْدِرُوجِينِ. 3.""مَرَاصِدُ الْحَيَّاتِ"" : مَكَامِنُهَا. 4.""الْمَرْصَدُ الوَطَنِيُّ لِحُقُوقُ الإِنْسَانِ"" : مَرْكَزٌ لِلتَّوْثِيقِ وَرَصْدِ قَضَايَا حُقُوقِ الإِنْسَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9605, 'مَرَاصِدُ', 'مراصد', 'جامد', '', 'مراصد', 'مرصد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9606, 'رَصَّاصَةٌ', 'رصاصة', 'جامد', 'رصص', 'رصاصة', 'رصصة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رَصَّاصَةٌ-رَصَّاصَةٌ [ر ص ص]. 1. : حَجَرٌ، أَو حِجارَةُ لاصِقَةٌ بِجَوانِبِ العَيْنِ الجارِيَةِ. 2.""رَجُلٌ رَصَّاصَةٌ"" : بَخيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9607, 'رَصاصٌ', 'رصاص', 'جامد', 'رصص', 'رصاص', 'رصص', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"رَصاصٌ-رَصاصٌ، ةٌ [ر ص ص]. 1. : مَعْدِنٌ أَبْيَضُ مائِلٌ للزُّرْقَةِ، لَيِّنٌ طَروقٌ، أَمْلاحُهُ مَوادُّ سامَّةٌ. 2.""أَطْلَقَ عَلَيْهِ الرَّصاصَ مِنْ مُسَدَّسِهِ"" : مَعْدِنٌ مُسْتَطيلٌ تُحْشَى بِهِ الأَسْلِحَةُ النَّارِيَّةُ كَالبُنْدُقِيَّةِ أَوِ الْمُسَدَّسِ. ""أُصِيبَ بِرَصَاصَةٍ فِي رَأْسِهِ فَمَاتَ فِي الْحِينِ"". 3.""قَلَمُ الرَّصاصِ"" : قَلَمٌ خَشَبِيٌّ بِداخِلِهِ مادَّةٌ مِنَ الجَرانيتِ يُكْتَبُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9608, 'رُصافَةٌ', 'رصافة', 'جامد', 'رصف', 'رصافة', 'رصفة', '', '', '', 'مفرد', 'DnN', '', '', '"رَصائِفُ"', '', 'R', '', '', '', '', '', '', '". 1.: عَقَبَةٌ تُشَدُّ وَتُلْوَى على مَدْخَلِ النَّصْلِ في السَّهْمِ. 2. : كُلُّ مَنْبِتٍ بِالسَّوادِ في ما حَوْلَ الْمَدينَةِ مِنَ القُرَى وَغَلَبَ على مَحَلَّةٍ بِبَغْدادَ. عُيونُ الْمَها بَيْنَ الرُّصافَةِ والجِسْرِ*جَلَبْنَ الهَوَى مِن حَيْثُ أَدْرِي وَلا أَدْرِي (علي بن الجهم)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9609, 'رَصائِفُ', 'رصائف', 'جامد', '', 'رصاءف', 'رصف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9610, 'رِصافٌ', 'رصاف', 'جامد', 'رصف', 'رصاف', 'رصف', '', '', '', 'مفرد', 'DnN', '', '', '"رُصُفٌ"', '', 'R', '', '', '', '', '', '', '". ""رِصافَةُ جانِبِ الطَّريقِ"" : حِجارَةٌ مَرْصوفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9611, 'رُصُفٌ', 'رصف', 'جامد', '', 'رصف', 'رصف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9612, 'رَصَفَةٌ', 'رصفة', 'جامد', 'رصف', 'رصفة', 'رصفة', '', '', '', 'مفرد', 'DnN', '', '', '"رَصَفٌ:أَرْصَافٌ"', '', 'R', '', '', '', '', '', '', '". 1. : واحِدَةُ الرِّصافِ أَو الرَّصَفِ لِلحِجارَةِ. 2. : عَصَبَةٌ في رَضْفَةِ الرُّكْبَةِ أَوْ عَيْنِ الرُّكْبَةِ. وَهُما رَصَفَتانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9613, 'رَصَفٌ', 'رصف', 'جامد', '', 'رصف', 'رصف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9614, 'أَرْصَافٌ', 'أرصاف', 'جامد', '', 'ءرصاف', 'رصف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9615, 'رُضابٌ', 'رضاب', 'جامد', 'رضب', 'رضاب', 'رضب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رُضابٌ-رُضابٌ [ر ض ب]. 1.""بَلَعَ رُضابَهُ"" : رِيقَهُ. 2.""ماءٌ رُضابٌ"" : ماءٌ عَذْبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9616, 'رُضوخٌ', 'رضوخ', 'جامد', 'رضخ', 'رضوخ', 'رضخ', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رُضوخٌ-رُضوخٌ [ر ض خ]. ""يَرْفُضُ الرُّضوخَ لأَوامِرِهِ"" : أَي الإِذْعَانَ، الخُضوعَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9617, 'رُضاضٌ', 'رضاض', 'جامد', 'رضض', 'رضاض', 'رضض', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رُضاضٌ-رُضاضٌ [ر ض ض]. ""رُضاضُ الْمَائِدَةِ"" : الفُتاتُ، الدُّقاقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9618, 'رَاضِعَةٌ', 'راضعة', 'جامد', 'رضع', 'راضعة', 'رضعة', '', '', '', 'مفرد', 'DnN', '', '', '"رَوَاضِعُ"', '', '', '', '', '', '', '', '', '".: السِّنُّ النَّابِتَةُ زَمَنَ الرِّضَاع."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9619, 'رَوَاضِعُ', 'رواضع', 'جامد', '', 'رواضع', 'رضع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9620, 'رَضَّاعَةٌ', 'رضاعة', 'جامد', 'رضع', 'رضاعة', 'رضعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"رَضَّاعَةٌ-رَضَّاعَةٌ [ر ض ع]. ""ناوَلَتْ طِفْلَها الرَّضَّاعَةَ"" : زُجاجَةٌ يُوضَعُ في رَأْسِها مَطَّاطٌ على شَكْلِ ثَدْيٍ، بِها حَليبٌ يُسْتَعْمَلُ لإرْضاعِ الطِّفْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9621, 'مِرْضَعَةٌ', 'مرضعة', 'جامد', 'رضع', 'مرضعة', 'مرضعة', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاضِعُ"', '', 'R', '', '', '', '', '', '', '". ""مِرْضَعَةُ الطِّفْلِ"" : آلَةٌ يُرْضَعُ مِنْهَا، رَضَّاعَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9622, 'مَرَاضِعُ', 'مراضع', 'جامد', '', 'مراضع', 'مرضع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9623, 'رَضَفَةٌ', 'رضفة', 'جامد', 'رضف', 'رضفة', 'رضفة', '', '', '', 'مفرد', 'DnN', '', '', '"رَضَفٌ"', '', 'R', '', '', '', '', '', '', '"(تش). ""سَقَطَ في الْمَلْعَبِ على رَضَفَةِ رُكْبَتِهِ"" : العَظْمُ الْمُدَوَّرُ الْمُتَحَرِّكُ في رَأْسِ الرُّكْبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9624, 'رَضَفٌ', 'رضف', 'جامد', '', 'رضف', 'رضف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9625, 'مِرْضَافَةٌ', 'مرضافة', 'جامد', 'رضف', 'مرضافة', 'مرضفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مِرْضَافَةٌ-مِرْضَافَةٌ [ر ض ف].: آلَةٌ يُكْوَى بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9626, 'تَرَاضِي', 'تراضي', 'جامد', 'رضي', 'تراضي', 'ترض', '', 'Tk', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"تَرَاضٍ-تَرَاضٍ، التَّرَاضِي [ر ض ي]. 1.""أَنْهَوْا خِصَامَهُمَا بِالتَّرَاضِي"" : بإِيِجَادِ صِيغَةٍ تُرْضِيهِمَا، بِالتَّوَافُقِ. 2.""التَّرَاضِي فِي الأَحْكَامِ"" : القَبُولُ بِهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9627, 'رَطْبَةٌ', 'رطبة', 'جامد', 'رطب', 'رطبة', 'رطبة', '', '', '', 'مفرد', 'DnN', '', '', '"رِطَابٌ"', '', 'R', '', '', '', '', '', '', '". ""عَلَفَ دَابَّتَهُ الرَّطْبَةَ"" : نَبَاتٌ يُزْرَعُ وَمِنْهُ ما يَنْبُتُ بَرِّيّاً. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9628, 'رِطَابٌ', 'رطاب', 'جامد', '', 'رطاب', 'رطب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9629, 'رُطَبٌ', 'رطب', 'جامد', 'رطب', 'رطب', 'رطب', '', '', '', 'مفرد', 'DnN', '', '', '"رِطابٌ:أَرْطابٌ"', '', 'R', '', '', '', '', '', '', '". ""رُطَبُ البُسْرِ"": ثَمَرُ النَّخْلِ قَبْلَ أَنْ يَصيرَ تَمْراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9630, 'رِطابٌ', 'رطاب', 'جامد', '', 'رطاب', 'رطب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9631, 'أَرْطابٌ', 'أرطاب', 'جامد', '', 'ءرطاب', 'رطب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9632, 'رُطْبٌ', 'رطب', 'جامد', 'رطب', 'رطب', 'رطب', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رُطْبٌ-رُطْبٌ، ةٌ [ر ط ب]. ""اِنْتَشَرَتِ الْمَاشِيَةُ في الرُّطْبِ"" : في الْمَرْعَى الأَخْضَرِ مِنَ العُشْبِ وَالشَّجَرِ.‏"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9633, 'رِطْلٌ', 'رطل', 'جامد', '', 'رطل', 'رطل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَرْطالٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَرْطالٌ. ""رِطْلٌ مِنَ الطَّماطِمِ"" : مِعْيارٌ يوزَنُ بِهِ ما يُعادِلُ اِثْنَتَيْ عَشْرَةَ أُوقِيَّةً أَوْ 500 غَرامٍ. وَهُوَ يَخْتَلِفُ بِاخْتِلاَفِ البِلاَدِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9634, 'أَرْطالٌ', 'أرطال', 'جامد', '', 'ءرطال', 'رطل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9635, 'رُطامٌ', 'رطام', 'جامد', 'رطم', 'رطام', 'رطم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رُطامٌ-رُطامٌ [ر ط م ]. ""أَصابَهُ رُطامٌ"" : إِمْساكٌ، قَبْضٌ، اِحْتِباسُ البَطْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9636, 'رُطْمَةٌ', 'رطمة', 'جامد', 'رطم', 'رطمة', 'رطمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رُطْمَةٌ-رُطْمَةٌ [ر ط م]. ""وَقَعَ في رُطْمَةٍ"" : في مَأْزِقٍ يَتَخَبَّطُ فيهِ، أو في أَمْرٍ لا تُعْرَفُ جِهَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9637, 'رِعْدَةٌ', 'رعدة', 'جامد', 'رعد', 'رعدة', 'رعدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رِعْدَةٌ-رِعْدَةٌ [ر ع د]. "" أَحَسَّ بِرِعْدَةٍ في جِسْمِهِ"" : أَي بِرَعْشَةٍ، باضْطِرابٍ في الجِسْمِ يَكونُ بِسَبَبِ حُمَّى أَوْ فَزَعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9638, 'رَواعِدُ', 'رواعد', 'جامد', 'رعد', 'رواعد', 'رعد', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَواعِدُ-رَواعِدُ [ر ع د]. ""ذاتُ الرَّواعِدِ"" : الْمُصيبَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9639, 'رَعْشَةٌ', 'رعشة', 'جامد', 'رعش', 'رعشة', 'رعشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"رَعْشَةٌ-رَعْشَةٌ، رِعْشَةٌ [ر ع ش]. ""أَخَذَتْهُ رَعْشَةُ الحُمَّى"" : رَجْفَةٌ تَعْتَري الجِسْمَ على إِثْرِ نَزْلَةِ زُكامٍ أَوْ سُعالٍ أَوْ حُمَّى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9640, 'رُعاعٌ', 'رعاع', 'جامد', 'رعع', 'رعاع', 'رعع', '', '', '', 'مفرد', '', '', '', '"واحدةرُعاعَةٌ"', '', 'R', '', '', '', '', '', '', '". ""اِخْتَلَطَ بِجَماعَةٍ مِنَ الرُّعاعِ"" : مِنَ غَوْغاءِ النَّاسِ، مِنْ سَفَلَتِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9641, 'رُعاعَةٌ', 'رعاعة', 'جامد', '', 'رعاعة', 'رععة', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9642, 'رَعيلٌ', 'رعيل', 'جامد', 'رعل', 'رعيل', 'رعل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَعيلٌ-رَعيلٌ [ر ع ل]. ""كانَ مِنَ الرَّعِيلِ الأَوَّلِ"" : مِنَ الجَماعَةِ الأُولىَ، من الفوْجِ الأَوَّلِ، مِنَ السَّابِقينَ. ""رَعيلٌ مِنَ الخَيْلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9643, 'رَعِيَّةٌ', 'رعية', 'جامد', 'رعي', 'رعية', 'رعة', '', '', '', 'مفرد', 'DnN', '', '', '"رَعايا"', '', '', '', '', '', '', '', '', '". 1.""مَشَى الرَّاعِي خَلْفَ رَعِيَّتِهِ"" : الْمَاشِيَةُ الرَّاعِيَةُ. 2.""رَعايانا"" : أَيْ خُدَّامُنا الخاضِعونَ لأَوامِرِنا. ""مُواطِنونَ لا رَعايا"". 3.""طَلَبَتِ السِّفارَةُ مِنْ رَعَايَاهَا الاتِّصالَ بِها عاجِلاً"" : الْمُواطِنونَ التَّابِعونَ لَها، أَي الحامِلونَ لِجِنْسِيَّةِ البَلَدِ الَّذي تَنْتَمي إِلَيْهِ السِّفارَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9644, 'رَعايا', 'رعايا', 'جامد', '', 'رعايا', 'رع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9645, 'مَرْعًى', 'مرعى', 'جامد', 'رعي', 'مرعى', 'مرع', '', '', '', 'مفرد', 'Dy', '', '', '"مَرَاعٍ:الْمَرَاعِي"', '', '', '', '', '', '', '', '', '". 1.""أرْضٌ بها الْمَرْعَى"" : الكَلأُ، العُشْبُ.الأعلى آية 4 وَالَّذِي أَخْرَجَ الْمَرْعَى (قرآن) ""زَعَمُوا أَنَّ أَسَدًا كَانَ فِي أَرْضٍ مُخْصِبَةٍ كَثِيرَةِ الوُحُوشِ وَالْمَاءِ وَالْمَرْعَى"". (ابن المقفع). 2.""اِنْتَشَرَتِ الْمَاشِيَةُ فِي الْمَرْعَى"" : مَكَانُ الرَّعْيِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9646, 'مَرَاعِي', 'مراعي', 'جامد', '', 'مراعي', 'مرع', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9647, 'رَغيبَةٌ', 'رغيبة', 'جامد', 'رغب', 'رغيبة', 'رغبة', '', '', '', 'مفرد', 'DnN', '', '', '"رَغائِبُ"', '', '', '', '', '', '', '', '', '". 1. : الْمَرْغوبُ فيهِ. 2. : العَطاءُ الكَثيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9648, 'رَغائِبُ', 'رغائب', 'جامد', '', 'رغاءب', 'رغب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
