INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9654, 'رَغامٌ', 'رغام', 'جامد', 'رغم', 'رغام', 'رغم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَغامٌ-رَغامٌ [ر غ م]. 1.""أَلْقَى الرَّغامَ عَلى وَجْهِهِ"" : التُّرابَ. 2.""أَلْقاهُ في الرَّغامِ"" : أَذَلَّهُ، أَهانَهُ."', '');
