INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9657, 'رُغامَى', 'رغامى', 'جامد', 'رغم', 'رغامى', 'رغم', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R0', '', '', '', '', '', '', '"رُغامَى-رُغامَى [ر غ م]. 1.: أَنْفٌ. 2.: قَصَبَةُ الرِّئَةِ. 3.:تَضَخُّمُ الكَبِدَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9658, 'مَرْغِمٌ', 'مرغم', 'جامد', 'رغم', 'مرغم', 'مرغم', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاغِمُ"', '', 'R', '', '', '', '', '', '', '". 1.الأَنْفُ. 2.""مَرَاغِمُ الإِنْسَانِ"" : أَنْفُهُ وَمَا حَوَالَيْهِ."', '');
