INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9663, 'رُغًى', 'رغى', 'جامد', '', 'رغى', 'رغ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9664, 'رِفاءٌ', 'رفاء', 'جامد', 'رفأ', 'رفاء', 'رف', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"رِفاءٌ-رِفاءٌ [ر ف أ]. ""بِالرِّفاءِ والبَنينَ"" : عِبارَةٌ تُرَدَّدُ للمُتَزَوِّجَيْنِ للِدُّعاءِ لَهُما بِالالْتِئامِ وَجَمْعِ الشَّمْلِ في انْتِظارِ أَنْ يُرْزَقا بَنينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9665, 'مَرْفَأٌ', 'مرفأ', 'جامد', 'رفأ', 'مرفء', 'مرف', '', '', '', 'مفرد', 'Dz', '', '', '"مَرَافِئُ"', '', 'Rz', '', '', '', '', '', '', '". ""مَرْفَأُ البَحْرِ"" : مَحَطَّةُ السُّفُنِ وَمَرْسَاهَا. ""مَرْفَأُ النَّهْرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9666, 'مَرَافِئُ', 'مرافئ', 'جامد', '', 'مرافء', 'مرف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9667, 'رُفاتٌ', 'رفات', 'جامد', 'رفت', 'رفات', 'رفت', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رُفاتٌ-رُفاتٌ [ر ف ت]. 1.""رُفاتُ الأَثاثِ"" : ما تَحَطَّمَ وَتَكَسَّرَ مِنْهُ وَبَلِيَ، الحُطامُ، الفُتاتُ. ""تَحَوَّلَتْ عِظامُهُ إلى رُفاتٍ""الإسراء آية 49 وَقالُوا أَئِذا كُنَّا عِظاماً وَرُفاتاً أءِنَّا لَمَبْعُوثُونَ خَلْقاً جَديداً (قرآن). 2.""نُقِلَ رُفاتُهُ إلى مَسْقَطِ رَأْسِهِ"" : جُثَّتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9668, 'رِفْدٌ', 'رفد', 'جامد', 'رفد', 'رفد', 'رفد', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْفادٌ:رُفودٌ"', '', 'R', '', '', '', '', '', '', '". 1. : رَفْدٌ. 2.""أَوْلاهُ رِفْداً"" : عَطاءً وَصِلَةً.هود آية 99 بِئْسَ الرِّفْدُ الْمَرْفودُ (قرآن) : أَي بِئْسَ العَطاءُ الْمُعْطَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9669, 'أَرْفادٌ', 'أرفاد', 'جامد', '', 'ءرفاد', 'رفد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
