INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9671, 'رِفْدٌ', 'رفد', 'جامد', 'رفد', 'رفد', 'رفد', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْفادٌ:رُفودٌ"', '', 'R', '', '', '', '', '', '', '". 1.""كانَ رِفْدُهُ لِلْجَماعَةِ كَبيراً"" : عَطاؤُهُ، مَعونَتُهُ. 2.""وَضَعُوا رُفوداً لِلْجِدارِ قَبْلَ أَنْ يَتَهاوَى"" : ما يَدْعَمُ وَيَسْنُدُ الجِدارَ."', '');
