INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9674, 'رَفيدَةٌ', 'رفيدة', 'جامد', 'رفد', 'رفيدة', 'رفدة', '', '', '', 'مفرد', 'DnN', '', '', '"رَفائِدُ"', '', '', '', '', '', '', '', '', '". ""هُوَ رَفيدَةُ صِدْقٍ"" : عَوْنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9675, 'رَفائِدُ', 'رفائد', 'جامد', '', 'رفاءد', 'رفد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9676, 'رَفْرَفٌ', 'رفرف', 'جامد', 'رفرف', 'رفرف', 'رفرف', '', '', '', 'مفرد', 'DnN', '', '', '"رَفارِفُ"', '', 'R', '', '', '', '', '', '', '". 1.""رَفْرَفُ البَيْتِ"" : الرَّفُّ تُوضَعُ علَيْهِ طَرائِفُ البَيْتِ. 2.""رَفْرَفُ الدَّارِ"" : مَا يُجْعَلُ فِي أَطْرَافِ الدَّارِ مِنَ الخارِجِ لِلْوِقايَةِ مِنْ حَرِّ الشَّمْسِ. 3.""رَفْرَفُ السَّيَّارَةِ"" : الجَناحُ الَّذِي فَوْقَ عَجَلَتِها. 4.""رَفْرَفُ الدِّرْعِ"" : جَوانِبُ الدِّرْعِ وَما تَدَلَّى مِنْها. 5.""اِتَّكَأَ عَلَى رَفْرَفٍ"" : وَسائِدَ مُرْتَفِعَةٍ.الرحمن آية 76 مُتَّكِئينَ على رَفْرَفٍ خُضْرٍ (قرآن). 6.""رَفْرَفُ الخَيْمَةِ"" : ما يُخاطُ في أَسْفَلِها. 7.""رَفْرَفُ الشَّجَرِ"" : ما تَهَدَّلَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9677, 'رَفارِفُ', 'رفارف', 'جامد', '', 'رفارف', 'رفرف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9678, 'رَفْسَةٌ', 'رفسة', 'جامد', 'رفس', 'رفسة', 'رفسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"رَفْسَةٌ-رَفْسَةٌ [ر ف س]. : الضَّرْبَةُ بِالرِّجْلِ في الصَّدْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9679, 'رَفيسٌ', 'رفيس', 'جامد', 'رفس', 'رفيس', 'رفس', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"رَفائِسُ"', '', 'R', '', '', '', '', '', '', '"(طخ). : طَعامٌ مَغْرِبِيٌّ، خَليطُ الطَّماطِمِ والبَصَلِ والحَلْبَةِ والتَّوابِلِ والزَّيْتِ والخُبْزِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9680, 'رَفائِسُ', 'رفائس', 'جامد', '', 'رفاءس', 'رفس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9681, 'رَافِضَةٌ', 'رافضة', 'جامد', 'رفض', 'رافضة', 'رفضة', '', '', '', 'مفرد', 'DnN', '', '', '"رَوَافِضُ"', '', 'R', '', '', '', '', '', '', '"رَافِضَةٌ-رَافِضَةٌ (فل). ج: رَوَافِضُ. [ر ف ض].: فِرْقَةٌ مِنْ فِرَقِ الشِّيعةِ عُرِفَتْ بِطَعْنِهَا فِي الصَّحَابةِ، وسُمُّوا بِذَلِكَ حِينَ رَفَضُوا زَيْداً بْنَ عَليٍّ عِنْدَمَا نَهَاهُمْ عَنِ الطَّعْنِ فِي الشَّيْخَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9682, 'رَوَافِضُ', 'روافض', 'جامد', '', 'روافض', 'رفض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9683, 'رَافِعَةٌ', 'رافعة', 'جامد', 'رفع', 'رافعة', 'رفعة', '', '', '', 'مفرد', 'DnN', '', '', '"رَوَافِعُ"', '', 'R', '', '', '', '', '', '', '".: كُلُّ أدَاةٍ تُسْتَعْمَـلُ لِرَفْعِ الأثْقَالِوَنَقْلِهَا وَتَتَألَّفُ مِـنْ ثَلاَثَةِ أقْسَـامٍ : نُقْطَـةُ الاسْتِنَادِ، وَذِرَاعُ الْمُقَاوَمَةِ وَذِرَاعُ القُوَّةِ، وَهِيَ ثَلاَثَةُ أنْوَاعٍ بِالنِّسْبَةِ إلَى مَوْقِعِ الاسْتِنَادِ. ""رَافِعَةُ البِنَاءِ"" رَافِعَةُ الألْغَامِ"" ""رَافِعَةُ الحَنَفِيَّةِ"" ""رَافِعَةُ تَبْدِيلِ السَّيْرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9684, 'رَوَافِعُ', 'روافع', 'جامد', '', 'روافع', 'رفع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9685, 'مَرَافِعُ', 'مرافع', 'جامد', 'رفع', 'مرافع', 'مرفع', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَرَافِعُ-مَرَافِعُ [ر ف ع].: هِيَ أَيَّامٌ مُعَيَّنَةٌ عِنْدَ الْمَسِيحِيِّينَ تَتَقَدَّمُ الصَّوْمَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9686, 'مَرْفَعٌ', 'مرفع', 'جامد', 'رفع', 'مرفع', 'مرفع', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَافِعُ"', '', 'R', '', '', '', '', '', '', '". 1.: أَيَّامٌ مَعْلُومَةٌ عِنْدَ الْمَسِيحِيِّينَ تَتَقَدَّمُ الصَّوْمَ. 2.""مَرْفَعُ البَيْتِ"" : الرَّفُّ لِوَضْعِ الأَشْيَاءِ عَلَيْهِ. ""مَرَافِعُ الْمَتْجَرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9687, 'مَرَافِعُ', 'مرافع', 'جامد', '', 'مرافع', 'مرفع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9688, 'رُفْقَةٌ', 'رفقة', 'جامد', 'رفق', 'رفقة', 'رفقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رُفْقَةٌ-رُفْقَةٌ، رِفْقَةٌ، رَفْقَةٌ [ر ف ق]. 1.""جاءَ بِرُفْقَتِهِ"" : بِصُحْبَتِهِ. 2.""هَؤُلاَءِ مِنْ رُفْقَتِهِ"" : جَماعَةُ الْمُرافِقينَ، الأَصْدِقاءُ، الرِّفاقُ. ""اِحْذَرْ مِنْ اخْتِيارِ رُفْقَتِكَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9689, 'مَرَافِقُ', 'مرافق', 'جامد', 'رفق', 'مرافق', 'مرفق', '', '', '', 'مفرد', '', '', '', '"مفردمَرْفِق"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '". 1.""اِنْتَهَى مِنْ تَجْهِيزِ مَرَافِقِ الدَّارِ"" : التَّجْهِيزَاتُ الأَسَاسِيَّةُ فِي البَيْتِ: دَوْرَةُ الْمِيَاهِ، وَالكَهْرَبَاءُ وَالْمَطْبَخُ... 2. ""الْمَرَافِقُ العَامَّةُ لِلْبِلاَدِ"" : الْمَصَالِحُ، الْمَنَافِعُ، الْمَوَارِدُ، أَيْ كُلُّ مَا يَخْدُمُ الْمُوَاطِنَ كَالبَرِيدِ وَالْجَمَارِكِ ... وَالْمُوَاصَلاَتِ... 3.المائدة آية 6 فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ (قرآن): مُوصِلُ الذِّرَاعِ إِلَى العَضُدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9690, 'مَرْفِق', 'مرفق', 'جامد', '', 'مرفق', 'مرفق', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9691, 'رَفَهَةٌ', 'رفهة', 'جامد', 'رفه', 'رفهة', 'رفهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رَفَهَةٌ-رَفَهَةٌ [ر ف هـ]. ""طَلَبَ رَفَهَتَهُ"" : رَحْمَتَهُ، رَأْفَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9692, 'رَقَبَةٌ', 'رقبة', 'جامد', 'رقب', 'رقبة', 'رقبة', '', '', '', 'مفرد', 'DnN', '', '', '"رِقابٌ"', '', 'R', '', '', '', '', '', '', '". 1.""شَدَّ رَقبَتَهُ"" : عُنُقَهُ. ""يَتَحَكَّمُ في رِقابِ العِبادِ"". 2.""عِتْقُ رَقَبَةٍ"" : تَحْريرُ نَفْسٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9693, 'رِقابٌ', 'رقاب', 'جامد', '', 'رقاب', 'رقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9694, 'مَرْقَبٌ', 'مرقب', 'جامد', 'رقب', 'مرقب', 'مرقب', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاقِبُ"', '', 'R', '', '', '', '', '', '', '".: الْمَوْضِعُ الْمُشْرِفُ الَّذِي يُرَاقَبُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9695, 'مَرَاقِبُ', 'مراقب', 'جامد', '', 'مراقب', 'مرقب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9696, 'رَاقُودٌ', 'راقود', 'جامد', 'رقد', 'راقود', 'رقد', '', '', '', 'مفرد', 'DnN', '', '', '"رَوَاقِيدُ"', '', 'R', '', '', '', '', '', '', '". ""أَخْرَجَتِ الْمَرْأةُ البَدَوِيَّةُ السَّمْنَ مِنَ الرَّاقُودِ"" : الجَرَّة الكَبِيرَة."', '');
