INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9698, 'رَقْدَةٌ', 'رقدة', 'جامد', 'رقد', 'رقدة', 'رقدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رَقْدَةٌ-رَقْدَةٌ [ر ق د]. 1.""أَخَذَتْهُ رَقْدَةٌ في الظَّهيرَةِ"" : نَوْمَةٌ. 2.""رَقَدَ رَقْدَتَهُ الأَخيرَةَ"" : نَوْمَتَهُ الأَخيرَةَ كِنايَةً عَنِ الْمَوْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9699, 'مَرْقَدٌ', 'مرقد', 'جامد', 'رقد', 'مرقد', 'مرقد', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاقِدُ"', '', 'R', '', '', '', '', '', '', '". ""نَامَ فِي مَرْقَدِهِ"" : مَضْجَعٌ، فِرَاشٌ. يس آية 52 يَاوَيْلَنَا مَنْ بَعَثَنَا مِنْ مَرْقَدِنَا (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9700, 'مَرَاقِدُ', 'مراقد', 'جامد', '', 'مراقد', 'مرقد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9701, 'رَقْشٌ', 'رقش', 'جامد', 'رقش', 'رقش', 'رقش', '', '', '', 'مفرد', 'DnN', '', '', '"رُقوشٌ"', '', 'R', '', '', '', '', '', '', '". ""دَفْتَرٌ بِهِ رَقْشٌ جَميلٌ"" : خَطٌّ حَسَنٌ."', '');
