INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9703, 'مَرْقَصٌ', 'مرقص', 'جامد', 'رقص', 'مرقص', 'مرقص', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاقِصُ"', '', 'R', '', '', '', '', '', '', '". ""دَخَلَ المَرْقَصَ"" : مَكَانٌ خَاصٌّ بِالرَّقْصِ. ""وَدَارَتْ عَيْنَاهَا بِالْمَرْقَصِ وَالرَّاقِصَاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9704, 'مَرَاقِصُ', 'مراقص', 'جامد', '', 'مراقص', 'مرقص', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9705, 'رُقْطَةٌ', 'رقطة', 'جامد', 'رقط', 'رقطة', 'رقطة', '', '', '', 'مفرد', 'DnN', '', '', '"رُقَطٌ"', '', 'R', '', '', '', '', '', '', '". ""ثَوْبٌ بِهِ رُقْطَةٌ "" : أَيْ بِهِ لَوْنٌ مُؤَلَّفٌ مِنْ بَيَاضٍ وَسَوَادٍ أَوْ مِنْ حُمْرَةٍ وَصُفْرَةٍ وَنَحْوِهِمَا."', '');
