INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9709, 'رُقْعَةٌ', 'رقعة', 'جامد', 'رقع', 'رقعة', 'رقعة', '', '', '', 'مفرد', 'DnN', '', '', '"رُقَعٌ:رِقاعٌ"', '', 'R', '', '', '', '', '', '', '". 1.""رَقَعَ الثَّوْبَ بِرُقْـعَةٍ"" : قِطْعَةٌ مِنَ النَّسيجِ تُصْلِحُ ما فُتِقَ مِنْهُ. 2.""اِشْتَرَى رُقْعَةَ أَرْضٍ"" : قِطْعَةَ أَرْضٍ. 3.""وَضَعَ البَيادِقَ عَلَى رُقْعَةِ الشِّطْرَنْجِ"" : لَوْحٌ بِهِ مُرَبِّعاتٌ بِيضٌ وَسُودٌ خاصٌّ بِلُعْبَةِ الشِّطْرَنْجِ أَوِ الدَّاما. 4.""رُقْعَةُ الهَدَفِ"" : اللَّوْحُ الَّذِي يُوَجَّهُ إِلَيْهِ السَّهْمُ. 5.""خَطُّ الرُّقْعَةِ"" : نَوْعٌ مِنْ أَنْواعِ الخُطوطِ العَرَبِيَّةِ. ن. خَطّ."', '');
