INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9716, 'رَقيقٌ', 'رقيق', 'جامد', 'رقق', 'رقيق', 'رقق', '', '', '', 'مفرد', 'DnN', '', '', '"أَرِقَّاءُ"', '', 'R', '', '', '', '', '', '', '". 1.""اِنتَهَى عَهْدُ الرَّقيقِ"" : عَهْدُ العَبيدِ. 2.""عَبْدٌ رَقيقٌ"" : مَمْلوكٌ..."', '');
