INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9718, 'أَرْقَامٌ', 'أرقام', 'جامد', 'رقم', 'ءرقام', 'رقم', '', '', '', 'مفرد', '', '', '', '"مفردرَقْم"', '', '', '', '', '', '', '', '', '". ""سَجَّلَ أَرْقَاماً فِي مُذَكِّرَتِهِ"": عَلاَمَاتُ الأَعْدَادِ مِنْ 0 إلى 9. ن.رقم."', '');
