INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9720, 'رَقيمٌ', 'رقيم', 'جامد', 'رقم', 'رقيم', 'رقم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَقيمٌ-رَقيمٌ [ر ق م]. 1 . "" الرَّقيمُ "" : الكِتابُ ، الصَّحيفَةُ . 2 الكهف آية 9أَمْ حَسِبْتَ أَنَّ أَصْحابَ الكَهْفِ والرَّقيمِ كانُوا مِنْ آياتِنا عَجَباً (قرآن). قيلَ اسْمُ قَرْيَةِ أَصْحابِ الكَهْفِ، أَوِ اسْمُ الصَّخْرَةِ، أَوِ الجَبَلِ، أَوِ اللَّوْحِ الَّذِي نُقِشَ فيهِ نَسَبُهُمْ وَأَسْماؤُهُمْ وَقيلَ كَلْبُهُمْ أَوِ الوادِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9721, 'مِرْقَمٌ', 'مرقم', 'جامد', 'رقم', 'مرقم', 'مرقم', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاقِمُ"', '', 'R', '', '', '', '', '', '', '".: كُلُّ أَدَاةٍ لِلرَّقْمِ أَوِ الكِتَابَةِ أَوِ التَّصْوِيرِ أَوِ النَّقْشِ."', '');
