INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9723, 'رَاقِنَةٌ', 'راقنة', 'جامد', 'رقن', 'راقنة', 'رقنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '".: ""تَكْتُبُ بِالرَّاقِنَةِ"" : آلَةٌ مَطْبَعِيَّةٌ صَغِيرَةٌ تُسْتَخْدَمُ لِكِتَابَةِ الرَّسَائِلِ وَالتَّقَارِيرِ وَمَا شَابَهَ ذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9724, 'مِرْقَنَةٌ', 'مرقنة', 'جامد', 'رقن', 'مرقنة', 'مرقنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَرَاقِنُ"', '', 'R', '', '', '', '', '', '', '". ""آلَةُ الْمِرْقَنَةِ"" : آلَةٌ كَاتِبَةٌ."', '');
