INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9726, 'تَرْقُوَةٌ', 'ترقوة', 'جامد', 'رقي', 'ترقوة', 'ترقة', '', '', '', 'مفرد', 'DnN', '', '', '"ترَاقٍ:التَّرَاقِي"', '', 'R', '', '', '', '', '', '', '"تَرْقُوَةٌ-تَرْقُوَةٌ [ر ق ي]. ج: ترَاقٍ، التَّرَاقِي : عَظْمَةٌ فِي أَعْلَى الصَّدْرِ بَيْنَ ثُغْرَةِ النَّحْرِ وَالعَاتِقِ وَهُمَا تَرْقُوتَانِ . ""بَلَغَتْ رُوحُهُ التَّرَاقِيَ"" : بَلَغَتِ اللَّحَظَاتِ الأَخِيرةَ، شَارَفَ الْمَوْتَ. القيامة آية 26 إِذَا بَلَغَتِ التَّرَاقِيَ .(قرآن) ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9727, 'تَرَاقِي', 'تراقي', 'جامد', '', 'تراقي', 'ترق', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9728, 'رُقْيَةٌ', 'رقية', 'جامد', 'رقي', 'رقية', 'رقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":رُقًى"', '', '', '', '', '', '', '', '', '". ""يَأْمُلُ شِفاءً بِرُقْيَةٍ"": ما يُرْقَى بِهِ المريضُ مِنْ كَلامٍ أَو كِتابَةِ حِرْزٍ . لا رُقْيَةَ إِلاَّ مِنْ عَيْنٍ أَوْ حُمَّةٍ (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9729, 'رُقًى', 'رقى', 'جامد', '', 'رقى', 'رق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9730, 'مِرْقَاةٌ', 'مرقاة', 'جامد', 'رقي', 'مرقاة', 'مرقة', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاقٍ"', '', '', '', '', '', '', '', '', '". ن. مَرْقَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9731, 'مَرَاقِي', 'مراقي', 'جامد', '', 'مراقي', 'مرق', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9732, 'مَرْقًى', 'مرقى', 'جامد', 'رقي', 'مرقى', 'مرق', '', '', '', 'مفرد', 'Dy', '', '', '"مَرَاقٍ:الْمَرَاقِي"', '', '', '', '', '', '', '', '', '".: الدُّرْجُ، أَيْ مَا يُصْعَدُ فِيهِ إِلَى أَعْلَى، السُّلَّمُ، المِرْقَاةُ."', '');
