INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9734, 'تَرْكيبَةٌ', 'تركيبة', 'جامد', 'ركب', 'تركيبة', 'تركبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَرْكيبَةٌ-تَرْكيبَةٌ [ر ك ب]. ""تَرْكِيبَةٌ مِنَ الزِّلِّيجِ"" : قِطْعَةٌ مِنْهُ مُنَسَّقَةٌ. ""وَضَعَ عَلَى القَبْرِ تَرْكِيبَةً مِنَ الرُّخَامِ"".(أ . أمين) ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9735, 'رِكابٌ', 'ركاب', 'جامد', 'ركب', 'ركاب', 'ركب', '', '', '', 'مفرد', 'DnN', '', '', '"رُكْبٌ:رَكائِبُ:رِكابٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَضَعَ الفارِسُ رِجْلَهُ في الرِّكابِ وَانْطَلَقَ بِفَرَسِهِ"" : أَداةٌ مِنْ حَديدٍ تُعَلَّقُ في السَّرْجِ، يَضَعُ عَلَيْها الرَّاكِبُ رِجْلَهُ وَهُما رِكابانِ. 2.""رَحَلُوا عَلَى الرِّكابِ"" : الإِبِلُ الَّتِي تُرْكَبُ. 3.""يَمْشِي في رِكابِهِ"" : أَيْ يَتْبَعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9736, 'رُكْبٌ', 'ركب', 'جامد', '', 'ركب', 'ركب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
