INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9739, 'رُكْبَةٌ', 'ركبة', 'جامد', 'ركب', 'ركبة', 'ركبة', '', '', '', 'مفرد', 'DnN', '', '', '"رُكَبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""سَقَطَ مِنْ فَوْقِ الفَرَسِ عَلَى رُكْبَتِهِ"" : الْمَوْصِلُ ما بَيْنَ الفَخِذِ والسَّاقِ.‎ ""يَحْبو الطِّفْلُ على يَدَيْهِ وَرُكْبَتِهِ"". 2.""هَذا أَمْرٌ تَصْطَكُّ لَهُ الرُّكَبُ"" : تَضْطَرِبُ وَتَضْرِبُ إِحْداها الأخْرَى مِنْ شِدَّةِ الفَزَعِ والخَوْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9740, 'رُكَبٌ', 'ركب', 'جامد', '', 'ركب', 'ركب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9741, 'رَكيزَةٌ', 'ركيزة', 'جامد', 'ركز', 'ركيزة', 'ركزة', '', '', '', 'مفرد', 'DnN', '', '', '"رَكائِزُ"', '', '', '', '', '', '', '', '', '". 1.""لابُدَّ مِنَ رَكيزَةٍ أَساسِيَّةٍ لِبَدْءِ العَمَلِ"" : أَيْ دِعامَةٌ. 2.""وَضَعُوا لِلْجِسْرِ رَكائِزَ صَلْبَةً"" : أَعْمِدَةً تَشُدُّهُ وَيُبْنَى عَلَيْها. ""رَكائِزُ البَيْتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9742, 'رَكائِزُ', 'ركائز', 'جامد', '', 'ركاءز', 'ركز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9743, 'مَرْكَزٌ', 'مركز', 'جامد', 'ركز', 'مركز', 'مركز', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاكِزُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَرْكَزُ الدَّائِرَةِ"" : النّقْطَةُ الوُسْطَى الَّتِي تَتَسَاوَى الْمُسْتَقِيمَاتُ الخَارِجَةُ مِنْهَا إِلَى الْمُحِيطِ. 2.""مَرْكَزُ الشُّرْطَةِ"" : الْمَخْفَرُ. 3.""مَرْكَزُ القِيَادَةِ"" : مَقَرُّهَا. 4.""الْمَرْكَزُ التِّجَارِيُّ أَوِ الصِّنَاعِيُّ"" : الْمَقَرُّ، أَيِ الفَضَاءُ الْخَاصُّ بِهِمَا. 6.""مَرْكَزُ الرَّجُلِ"" : مَكَانَتُهُ، مَنْزِلَتُهُ. ""يَتَمَتَّعُ بِمَرْكَزٍ مُحْتَرَمٍ بَيْنَ أَهْلِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9744, 'مَرَاكِزُ', 'مراكز', 'جامد', '', 'مراكز', 'مركز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9745, 'مَرْكَضٌ', 'مركض', 'جامد', 'ركض', 'مركض', 'مركض', '', '', '', 'مفرد', 'DnN', '', '', '"مَراكِضُ"', '', 'R', '', '', '', '', '', '', '".: مَكَانُ الرَّكْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9746, 'مَراكِضُ', 'مراكض', 'جامد', '', 'مراكض', 'مركض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9747, 'مِرْكَضٌ', 'مركض', 'جامد', 'ركض', 'مركض', 'مركض', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاكِضُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِرْكَضُ النَّارِ"" : مَا تُشْعَلُ بِهِ. 2.""مِرْكَضُ الشَّيْءِ"" : مُحَرِّكُهُ. 3.""مَرَاكِضُ الْمَسْبَحِ"" : جَوَانِبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9748, 'مَرَاكِضُ', 'مراكض', 'جامد', '', 'مراكض', 'مركض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9749, 'تَرْكِيعٌ', 'تركيع', 'جامد', 'ركع', 'تركيع', 'تركع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَرْكِيعٌ-تَرْكِيعٌ [ر ك ع]. ""تَرْكِيعُ الوَلَدِ"" : جَعْلُهُ يَرْكَعُ، إِخْضَاعُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9750, 'رُكامٌ', 'ركام', 'جامد', 'ركم', 'ركام', 'ركم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رُكامٌ-رُكامٌ [ر ك م]. 1.""رُكامُ السَّحابِ"" : السَّحابُ الْمُجْتَمِعُ بَعْضُهُ فَوْقَ بَعْضٍ. 2.""رُكامُ الحَجَرِ"" : أَحْجارٌ تَراكَمَ بَعْضُها عَلَى بَعْضٍ. ""رُكامُ الكُتُبِ"" ""رُكامُ الجَرائِدِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9751, 'مِرْكَمٌ', 'مركم', 'جامد', 'ركم', 'مركم', 'مركم', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاكِمُ"', '', 'R', '', '', '', '', '', '', '". ""مَرَاكِمُ السَّيَّارَةِ"" : بَطَّارِيَّاتٌ تُشْحَنُ بِالكَهْرَبَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9752, 'مَرَاكِمُ', 'مراكم', 'جامد', '', 'مراكم', 'مركم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9753, 'رُكْنٌ', 'ركن', 'جامد', 'ركن', 'ركن', 'ركن', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْكانٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِنْزَوَى في رُكْنِ البَيْتِ"": في زاوِيَةٍ مِنْ زَواياهُ، في جانِبِهِ، ""أَرْكانُ البَيْتِ"" : جَوانِبُهُ. 2.""كانَ رُكْنَهُ الْمَنِيعَ"" : ما يُقَوِّي بِهِ العِزَّ والْمَكانَةَ. 3.""كانَ قائِداً مِغْواراً وَرُكْناً مِنْ أَرْكانِ قَوْمِهِ"" : أَي أَحَدَ الأَعْمِدَةِ الأَساسِيَّةِ لِقَوْمِهِ. ""أَرْكانُ الإِسْلامِ خَمْسَةٌ : الشَّهادَتانِ والصَّلاةُ والصَّوْمُ والزَّكاةُ والحَجُّ"". 4.""اِجْتَمَعَ أَرْكانُ القُوَّاتِ الْمُسَلَّحَةِ"" : قادَةُ الجَيْشِ الكِبارُ. ""أَرْكانُ الحَرْبِ"". 5.""القائِدُ الرُّكْنُ"" : صِفَةٌ عَسْكَرِيَّةٌ لِمَنْ لَهُ مَعْرِفَةٌ بِالعُلومِ العَسْكَرِيَّةِ. 6.""الرُّكْنُ في الصَّحافَةِ"" : جُزْءٌ مِنَ الصَّفْحَةِ مُخَصَّصٌ لِمَوْضوعٍ مَّا. ""رُكْنُ الْمَرْأَةِ"" ""رُكْنُ الهُواةِ"" ""رُكْنُ الشَّبابِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9754, 'أَرْكانٌ', 'أركان', 'جامد', '', 'ءركان', 'ركن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9755, 'مَرْكَنٌ', 'مركن', 'جامد', 'ركن', 'مركن', 'مركن', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاكِنُ"', '', 'R', '', '', '', '', '', '', '". ""مَرْكَنُ السَّيَّارَاتِ"" : مَكَانُ وُقُوفِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9756, 'مَرَاكِنُ', 'مراكن', 'جامد', '', 'مراكن', 'مركن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9757, 'مِرْكَنٌ', 'مركن', 'جامد', 'ركن', 'مركن', 'مركن', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاكِنُ"', '', 'R', '', '', '', '', '', '', '". ""مِرْكَنُ غَسْلِ الثِّيَابِ"" : وِعَاءٌ مِنْ مَعْدِنٍ وَنَحْوِهِ تُغْسَلُ فِيهِ الثِّيَابُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9758, 'مَرَاكِنُ', 'مراكن', 'جامد', '', 'مراكن', 'مركن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9759, 'رِكْوَةٌ', 'ركوة', 'جامد', 'ركو', 'ركوة', 'ركة', '', '', '', 'مفرد', 'DnN', '', '', '"رِكاءٌ"', '', 'R', '', '', '', '', '', '', '". ""يُعَلِّقُ رِكْوَةً على جِرابِهِ"" : إِناءٌ مِنْ جِلْدٍ أَومَعْدِنٍ يُشْرَبُ مِنْهُ الماءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9760, 'رِكاءٌ', 'ركاء', 'جامد', '', 'ركاء', 'رك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9761, 'رُمَّانٌ', 'رمان', 'جامد', '', 'رمان', 'رمن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رُمَّانٌ-رُمَّانٌ (نب). 1.: شَجَرٌ مِنْ فَصيلَةِ الآسِيَّاتِ مُثْمِرٌ، ثَمَرَتُهُ علىشَكْلِ كُرَةٍ صَغيرَةٍ لَها تاجٌ، وَقِشْرَتُهُ ما بَيْنَ الخُضْرَةِ وَالصُّفْـرَةِ،كَثيفَـةٌ، داخِلِها حُبوبٌ وَرْدِيَّةٌ، بِها سائِلٌ حُلْوٌ أَوْ حامِضٌ. 2. : ثَمَرُ شَجَرِ الرُّمَّانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9762, 'رُمَّانَةٌ', 'رمانة', 'جامد', '', 'رمانة', 'رمنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"واحِدَةُالرُّمَّانِ"', '', 'R', '', '', '', '', '', '', '"واحِدَةُ الرُّمَّانِ. 1. : السُّرَّةُ وَما حَوْلَها. 2.""رُمَّانَةُ القَبَّانِ"" : ثِقْلٌ مِنَ الحَديدِ على شَكْلِ كُرَةٍ، تُحَرَّكُ عَلَى قَضِيبِ المِيزانِ،وَهُوَ ما يُعْرَفُ بِالقَبَّانِ ،حَتَّى يَعْتَدِلَ فَيُقْرَأَ رَقْمُ الوَزْنِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9763, 'رَمَّاحَةٌ', 'رماحة', 'جامد', 'رمح', 'رماحة', 'رمحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رَمَّاحَةٌ-رَمَّاحَةٌ [ر م ح]. 1.""قَوْسٌ رَمَّاحَةٌ"" : شَديدَةُ الدَّفْعِ. 2.""دابَّةٌ رَمَّاحَةٌ"" : كَثيرَةُ العَضِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9764, 'رُمْحٌ', 'رمح', 'جامد', 'رمح', 'رمح', 'رمح', '', '', '', 'مفرد', 'DnN', '', '', '"رِماحٌ:أَرْماحٌ"', '', 'R', '', '', '', '', '', '', '". ""طَعَنَـهُ بِرُمْحٍ"" : بِسَهْمٍ، أَيْ بِعُودٍ طَويلٍ في رَأْسِهِ حَرْبَةٌ يُطْعَنُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9765, 'رِماحٌ', 'رماح', 'جامد', '', 'رماح', 'رمح', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9766, 'أَرْماحٌ', 'أرماح', 'جامد', '', 'ءرماح', 'رمح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9767, 'رَمادٌ', 'رماد', 'جامد', 'رمد', 'رماد', 'رمد', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْمِدَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""لَمْ يَبْقَ مِنَ الجَمْرِ إِلاَّ الرَّمادُ"" : ما تَبَقَّى مِنْ جَمْرِ الفَحْمِ أَوِ الخَشَبِ بَعْدَ احْتِراقِهِ. 2.""يَنْفُخُ في الرَّمادِ"" (مثل) : يُضْرَبُ لِمَنْ يَبْذُلُ جُهوداً لا طائِلَ تَحْتَها. 3.""رَجُلٌ كَثيرُ الرَّمادِ"" : كَريمٌ، مِضْيافٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9768, 'أَرْمِدَةٌ', 'أرمدة', 'جامد', '', 'ءرمدة', 'رمدة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9769, 'مِرْمَدَةٌ', 'مرمدة', 'جامد', 'رمد', 'مرمدة', 'مرمدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". ""مِرْمَدَةُ السَّجَائِرِ"" : وِعَاءٌ صَغِيرٌ مِنْ مَعْدِنٍ وَنَحْوِهِ يُوضَعُ فِيهِ رَمَادُ السَّجَائِرِ، مِنْفَضَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9770, 'رَامِسَاتٌ', 'رامسات', 'جامد', 'رمس', 'رامسات', 'رمست', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"رَامِسَاتٌ-رَامِسَاتٌ [ر م س]. : رِيَاحٌ تَدْفِنُ الآثَارَ وَتُغَطِّيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9771, 'رَامِسٌ', 'رامس', 'جامد', 'رمس', 'رامس', 'رمس', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"رَوَامِسُ"', '', 'R', '', '', '', '', '', '', '". ""طَائِرٌ رَامِسٌ"" : يَخْرُجُ فِي اللَّيْلِ. ""دَابَّةٌ رَامِسَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9772, 'رَوَامِسُ', 'روامس', 'جامد', '', 'روامس', 'رمس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9773, 'مَرْمُوسةٌ', 'مرموسة', 'جامد', 'رمس', 'مرموسة', 'مرمسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَرْمُوسةٌ-مَرْمُوسةٌ [ر م س]. ""وَقَعُوا فِي مَرْمُوسَةٍ مِنْ أَمْرِهِمْ"" : فِي اخْتِلاَطٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9774, 'رَمْشَةٌ', 'رمشة', 'جامد', 'رمش', 'رمشة', 'رمشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"رَمْشَةٌ-رَمْشَةٌ [ر م ش]. ""في رَمْشَةِ العَيْنِ"" : أَي في أَسْرَعَ ما يَكونُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9775, 'رَمَشٌ', 'رمش', 'جامد', 'رمش', 'رمش', 'رمش', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَمَشٌ-رَمَشٌ [ر م ش]. ""أَصابَ الرَّمَشُ عَيْنَهُ"" : اِحْمِرارٌ في الجَفْنِ وَتَفَتُّلُ الأَشْفارِ مَعَ ماءٍ يَسيلُ مِنْها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9776, 'رَمْشٌ', 'رمش', 'جامد', 'رمش', 'رمش', 'رمش', '', '', '', 'مفرد', 'DnN', '', '', '"رُموشٌ"', '', 'R', '', '', '', '', '', '', '". 1.""رَمْشُ العَيْنِ"" : جَفْنُها. 2.""قَدَّمَ لهُ رَمْشاً"" : طاقَةً مِنَ الرَّيْحانِ أَوْ نَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9777, 'رُموشٌ', 'رموش', 'جامد', '', 'رموش', 'رمش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9778, 'مِرْمَاشٌ', 'مرماش', 'جامد', 'رمش', 'مرماش', 'مرمش', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَامِيشُ"', '', 'R', '', '', '', '', '', '', '". ""وَلَدٌ مِرْمَاشٌ"" : يُحَرِّكُ عَيْنَيْهِ كَثِيراً عِنْدَ النَّظَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9779, 'مَرَامِيشُ', 'مراميش', 'جامد', '', 'مراميش', 'مرمش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9780, 'رَمْضاءُ', 'رمضاء', 'جامد', 'رمض', 'رمضاء', 'رمض', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"رَمْضاءُ-رَمْضاءُ [ر م ض]. 1.""يَوْمٌ مِنْ أَيَّامِ الرَّمْضاءِ"" : اليَوْمُ الَّذِي يَشْتَدُّ فيهِ حَرُّ الشَّمْسِ. ""رَأَيْتُهُ يَتَمَلْمَلُ كَأَنَّما يَتَقَلَّبُ على الرَّمْضاءِ"". 2.""رَمْضاءُ الجَزِيرَةِ"" : أَرْضُها وَقَدْ حَمِيَتْ مِنْ حَرِّ الشَّمْسِ. ""كَالْمُسْتَجِيرِ مِنَ الرَّمْضاءِ بِالنَّارِ"" (مثل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9781, 'رَمَضانُ', 'رمضان', 'جامد', '', 'رمضان', 'رمضن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ التَّاسِعُ مِنَ الشُّهورِ الهِجْرِيَّةِ، يَأْتِي بَعْدَ شَهْرِ شَعْبانَ وَيَليهِ شَهْرُ شَوَّالَ، عَدَدُ أَيَّامِهِ (30) يَوْماً، أو (29) يَوْماً فَقَطْ. ""حَلَّ شَهْرُ رَمَضانَ، شَهْرُ الصِّيامِ والغُفْرانِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9782, 'رَمَقٌ', 'رمق', 'جامد', 'رمق', 'رمق', 'رمق', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْماقٌ"', '', 'R', '', '', '', '', '', '', '". 1.""الرَّمَقُ الأَخيرُ"" : أَي اللَّحْظَةُ الأَخيرَةُ قَبْلَ الوَفاةِ، بَقِيَّةُ الحَياةِ في الجَسَدِ. ""عَلَى آخِرِ رَمَقٍ"" ""لَنْ أَعودَ إِلَيْهِ وَبِي رَمَقٌ مِنَ الحَياةِ"". 2.""يَبْحَثُ عَمَّا يَسُدُّ رَمَقَهُ"" : القَليلُ مِنَ الطَّعامِ لِيُنْقِذَ بِهِ نَفْسَهُ مِنَ الْمَوْتِ جُوعاً. ""لاَ يَتَناوُلَ أَحَدٌ شَيْئاً إِلاَّ ما يُقيمُ بِهِ الرَّمَقَ"". (ابن طفيل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9783, 'أَرْماقٌ', 'أرماق', 'جامد', '', 'ءرماق', 'رمق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9784, 'رَمْلَةٌ', 'رملة', 'جامد', 'رمل', 'رملة', 'رملة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رَمْلَةٌ-رَمْلَةٌ [ر م ل]. 1. : حَبَّةُ الرَّمْلِ. 2.: قِطْعَةٌ مِنَ الرَّمْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9785, 'رَمْلٌ', 'رمل', 'جامد', 'رمل', 'رمل', 'رمل', '', '', '', 'مفرد', 'DnN', '', '', '"رِمالٌ"', '', 'R', '', '', '', '', '', '', '". ""رَمْلُ الشَّاطِئِ"" : فُتاتُ الصَّخْرِ وَذَرَّاتُهُ تُغَطِّي الشَّواطِئَ. ""شاطِئُ الرِّمالِ الذَّهَـبِيَّةِ"" ""رِمالُ الصَّحْراءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9786, 'رِمالٌ', 'رمال', 'جامد', '', 'رمال', 'رمل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9787, 'رُمَّةٌ', 'رمة', 'جامد', 'رمم', 'رمة', 'رمة', '', '', '', 'مفرد', 'DnN', '', '', '"رُمَمٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَدَّى الدَّيْنَ بِرُمَّتِهِ"" : بِجُمْلَتِهِ. 2.""أَنْشَدَ القَصيدَةَ بِرُمَّتِها"" : مِنْ أَوَّلِها إلى آخِرِهَا. 3.""رُمَّةُ الحَبْلِ"" : القِطْعَةُ البالِيَةُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9788, 'رُمَمٌ', 'رمم', 'جامد', '', 'رمم', 'رم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9789, 'رِمٌّ', 'رم', 'جامد', 'رمم', 'رم', 'رم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رِمٌّ-رِمٌّ [ر م م]. 1. : الثَّرَى. 2.""رِمُّ العَظْمِ"" : مُخُّهُ. 3.""رِمُّ الْمَاءِ"" : مَا يَحْمِلُهُ. 4.""رِمُّ الرِّيحِ "" : مَا تَحْمِلُهُ. 5.""جَاءهُمُ الطِّمُّ وَالرِّمُّ"" : أَيْ أَتَاهُمُ الشَّيْءُ الْكَثِيرُ وَالْقَلِيلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9790, 'رَمِيَّةٌ', 'رمية', 'جامد', 'رمي', 'رمية', 'رمة', '', '', '', 'مفرد', 'DnN', '', '', '"رَمايا"', '', '', '', '', '', '', '', '', '". ""أَصابَ الرَّمِيَّةَ"" : الصَّيْدَ الَّذِي يُرْمَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9791, 'رَمايا', 'رمايا', 'جامد', '', 'رمايا', 'رم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9792, 'رِمْيَةٌ', 'رمية', 'جامد', 'رمي', 'رمية', 'رمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رِمْيَةٌ-رِمْيَةٌ [ر م ي]. : حَجَرٌ أَو كُرَةٌ أَوْ قِطْعَةٌ مُسَطَّحَةٌ وَمُسْتَديرَةٌ تُرْمَى إلى أَقْرَبِ مَكانٍ مِنْ هَدَفٍ مُعَيَّنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9793, 'مَرْمًى', 'مرمى', 'جامد', 'رمي', 'مرمى', 'مرم', '', '', '', 'مفرد', 'Dy', '', '', '"مَرَامٍ:الْمَرَامِي"', '', '', '', '', '', '', '', '', '". 1.""مَرْمَـى السِّهَامِ"" : الهَدَفُ الَّذِي تُرْمَى فِيهِ السِّهَامُ. 2.""هُوَ مِنْكَ عَلَى مَرْمَى حَجَرٍ"" : أَيْ هُوَ عَلَى مَقْرُبَةٍ مِنْكَ. 3.""وَجَّهَ اللاَّعِبُ الكُرَةَ إِلَى قَلْبِ الْمَرْمَى"" : الشَّبَكَةُ الَّتِي تَشَدُّهَا عَارِضَةٌ وَعَمُودَانِ. ""حَارِسُ الْمَرْمَى"". 4.""هَدَفٌ بَعِيدُ الْمَرْمَى"" : هَدَفٌ بَعِيدُ الإِصَابَةِ وَالحُصُولِ عَلَيْهِ. ""فَهِمَ مَرَامِيَهُ"". 5.""مَرْمَى النَّظَرِ"" : مَدَى البَصَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9794, 'مَرَامِي', 'مرامي', 'جامد', '', 'مرامي', 'مرم', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
