INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9799, 'رَوْنَقٌ', 'رونق', 'جامد', 'رنق', 'رونق', 'رنق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَوْنَقٌ-رَوْنَقٌ [ر ن ق]. ""لَهُ رَوْنَقٌ"" : لَهُ حُسْنٌ وَبَهاءٌ. ""رَوْنَقُ الشَّبابِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9800, 'تَرْنِيمَةٌ', 'ترنيمة', 'جامد', 'رنم', 'ترنيمة', 'ترنمة', '', '', '', 'مفرد', 'DnN', '', '', '"تَرَانِيمُ"', '', 'R', '', '', '', '', '', '', '". ""لَحَّنَ تَرْنِيمَةً جَدِيدَةً"" : الأُنْشودَةُ الْمُغَنَّاةُ. ""تَرْنِيمَةٌ دِينِيَّةٌ"" ""تَرَانِيمُ تَصْدَحُ بِهَا أَرْجَاءُ القَاعَةِ"" ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9801, 'تَرَانِيمُ', 'ترانيم', 'جامد', '', 'ترانيم', 'ترنم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9802, 'رَهْبَلٌ', 'رهبل', 'جامد', 'رهبل', 'رهبل', 'رهبل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَهْبَلٌ-رَهْبَلٌ [ر هـ ب ل]. ""أَتَى بِرَهْبَلٍ"" : بِكَلامٍ لا يُفْهَمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9803, 'رَهْصَةٌ', 'رهصة', 'جامد', 'رهص', 'رهصة', 'رهصة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"رَهْصَةٌ-رَهْصَةٌ [ر هـ ص]. ""أُصيبَتِ الدَّابَّةُ بِرَهْصَةٍ"" : داءٌ يُصيبُها في باطِنِ حافِرِها مِنْ ضَرْبَةٍ أَوْ غَيْرِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9804, 'رَهْطٌ', 'رهط', 'جامد', 'رهط', 'رهط', 'رهط', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْهُطٌ:أَرْهاطٌ"', '', 'R', '', '', '', '', '', '', '". 1.""جاءَ يَدُقُّ بابَهُ رَهْطٌ مِنَ اللُّصُوصِ"" : عَدَدٌ يَجْمَعُ مِنَ الثَّلاثَةِ إلى العَشَرَةِ، لاَ واحِدَ لَهُ مِنْ لَفْظِهِ.النمل آية 48 وَكانَ في الْمَدينَةِ تِسْعَةُ رَهْطٍ (قرآن). 2.""رَهْطُ الرَّجُلِ"" : قَوْمُهُ، أَوْ قَبِيلَتُهُ أَوْ أَفْرادُ عائِلَتِهِ الأَقْرَبونَ. 3.""نَحْنُ ذَوو رَهْطٍ"" : مُجْتَمِعونَ."', '');
