INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9809, 'رَهينَةٌ', 'رهينة', 'جامد', 'رهن', 'رهينة', 'رهنة', '', '', '', 'مفرد', 'DnN', '', '', '"رَهائِنُ"', '', '', '', '', '', '', '', '', '". 1.""أَنا رَهينَةٌ بِعَمَلِي وَبِمَا قَدَّمْتُ"" : مَأْخوذٌ بِهِ وَضامِنٌ لَهُ. المدثر آية 38 كُلُّ نَفْسٍ بِما كَسَبَتْ رَهينَةٌ (قرآن). 2.""تَرَكَ أَغْرَاضَهُ رَهينَةً عِنْدَهُ"" : ما يُرْهَنُ مِنْ مَتاعٍ أَوْ عَقارٍ وَيُحْفَظُ بِهِ ضَماناً إلَى غايَةِ إِنْجازِ التَّعَهُّدِ. 3.""أَخَذوهُ رَهينَةً"" : أَخَذوهُ علَى أَنْ يُطْلَقَ سَراحُهُ مُقابِلَ ما يَطْلُبونَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9810, 'رَهائِنُ', 'رهائن', 'جامد', '', 'رهاءن', 'رهن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9811, 'رَوْبَةٌ', 'روبة', 'جامد', 'روب', 'روبة', 'ربة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رَوْبَةٌ-رَوْبَةٌ [ر و ب]. : خَميرَةٌ تُلْقَى في اللَّبَنِ لِيَروبَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9812, 'رَوْبٌ', 'روب', 'جامد', 'روب', 'روب', 'رب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَوْبٌ-رَوْبٌ [ر و ب]. ""تَناوَلَ رَوْباً بَعْدَ الأَكْلِ"" : أَي اللَّبَنَ الْمُرَوَّبَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9813, 'مِرْوَبٌ', 'مروب', 'جامد', 'روب', 'مروب', 'مرب', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاوِبُ"', '', 'R', '', '', '', '', '', '', '".: وِعَاءٌ يَرُوبُ فِيهِ اللَّبَنُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9814, 'مَرَاوِبُ', 'مراوب', 'جامد', '', 'مراوب', 'مرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9815, 'رَوْثٌ', 'روث', 'جامد', 'روث', 'روث', 'رث', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْواثٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""رَوْثُ الحَيَوانِ"" : رَجيعُ ذِي حافِرٍ، الزِّبْلُ. ""فَأُدْخِلَ الحَمَّامَ لِيَنْفُضَ أَوْسَاخَهُ ويَطْرُدَ عَنْهُ رَوَائِحَ الرَّوْثِ"". (أحمد التوفيق)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9816, 'أَرْواثٌ', 'أرواث', 'جامد', '', 'ءرواث', 'رث', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9817, 'تَرَاوِيحُ', 'تراويح', 'جامد', 'روح', 'تراويح', 'ترح', '', '', '', 'مفرد', '', '', '', '"مفردتَرْوِيحَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""يُصَلِّي صَلاَةَ التَّراوِيحِ"": صَلاَةٌ تُقَامُ بَعْدَ صَلاَةِ العِشَاءِ فِي شَهْرِ رَمَضَانَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9818, 'تَرْوِيحَة', 'ترويحة', 'جامد', '', 'ترويحة', 'ترحة', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9819, 'رَاحٌ', 'راح', 'جامد', 'روح', 'راح', 'رح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَاحٌ-رَاحٌ [ر و ح]. 1. ""يَعِيشُ فِي رَاحٍ"" : فِي انْبِسَاطٍ وَانْشِرَاحٍ. 2. ""بَسَطَ رَاحَهُ"" : مَدَّ كَفَّيْهِ، أيْ جَمْعُ رَاحَةِ الكَفِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9820, 'رَائِحَةٌ', 'رائحة', 'جامد', 'روح', 'راءحة', 'رحة', '', '', '', 'مفرد', 'DnN', '', '', '"رَوَائِحُ"', '', '', '', '', '', '', '', '', '". ""تَنْبَعِثُ مِنْهَا رَائِحَةٌ طَيِّبَةٌ"": مَا يُسْتَنْشَقُ، مَا يُشَمُّ. ""اِسْتَنْشَقَ رَائِحَةً كَرِيهَةً"" ""هُوَ كَرِيهُ الرَّائِحةِ"" : عَكسُهُ زَكِيُّ الرَّائِحَةِ ""رَائِحَةٌ خَبِيثَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9821, 'رَوَائِحُ', 'روائح', 'جامد', '', 'رواءح', 'رح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9822, 'رَوائِحُ', 'روائح', 'جامد', 'روح', 'رواءح', 'رح', '', '', '', 'مفرد', '', '', '', '"مفردرَائِحَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ن. رائِحَةٌ .""تَنْبَعِثُ رَوائِحُ زَكِيَّةٌ مِنَ الغُرْفَةِ"" : نَسائِمُ. ""رَوائِحُ كَريهَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9823, 'رَيْحانٌ', 'ريحان', 'جامد', 'روح', 'ريحان', 'رحن', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"رَياحِينُ"', '', 'R', '', '', '', '', '', '', '"(نب).: نَباتٌ مِنْ فَصيلَةِ الشَّفَوِيَّاتِ، طَيِّبُ الرَّائِحَةِ، الحَبَقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9824, 'رَياحِينُ', 'رياحين', 'جامد', '', 'رياحين', 'رحن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9825, 'مَرَاحٌ', 'مراح', 'جامد', 'روح', 'مراح', 'مرح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مُرَاحٌ-مُرَاحٌ [ر و ح]. ""مُرَاحُ الإِبِلِ وَالغَنَمِ"" : مَأْوَاهَا فِي اللَّيْلِ. ""عَادَتِ الإِبِلُ وَالغَنَمُ مِنْ مَرَاحِهَا فَأَخَذَهَا إِلَى مُرَاحِهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9826, 'مُرَاحٌ', 'مراح', 'جامد', 'روح', 'مراح', 'مرح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَرَاحٌ-مَرَاحٌ [ر و ح]. 1.""تَجَمَّعَ الأَطْفَالُ فِي الْمَرَاحِ يَلْعَبُونَ"": مَوْضِع اللَّعِبِ وَالرَّاحَةِ. 2.""مَرَاحُ الإِبِلِ وَالغَنَمِ"" : مَرْعَاهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9827, 'مِرْوَحٌ', 'مروح', 'جامد', 'روح', 'مروح', 'مرح', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَرَاوِح"', '', 'R', '', '', '', '', '', '', '". 1.""مِرْوَحٌ يَدَوِيٌّ"": رَايَةٌ صَغِيرَةٌ دَائِرِيَّةٌ أَوْ مُرَبَّعَةٌ مِنْ وَرَقٍ أَوْ ثَوْبٍ تُحَرَّكُ بِاليَدِ لاسْتِجْلابِ الْهَوَاءِ فِي وَقْتِ الْحَرِّ. 2.""مِرْوَحٌ كَهْرَبَائِيٌّ"" : آلَةٌ تُحَرِّكُهَا القُوَّةُ الكَهْرَبَائِيَّةُ لاسْتِجْلاَبِ الْهَوَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9828, 'مَرَاوِح', 'مراوح', 'جامد', '', 'مراوح', 'مرح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9829, 'مُسْتَرَاحٌ', 'مستراح', 'جامد', 'روح', 'مستراح', 'مسترح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مُسْتَرَاحٌ-مُسْتَرَاحٌ [ر و ح]. : بَيْتُ الخَلاَءِ، الْمِرْحَاضُ ، الكَنِيفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9830, 'مِرْوَدٌ', 'مرود', 'جامد', 'رود', 'مرود', 'مرد', '', '', '', 'مفرد', 'DnN', '', '', '"مَرَاوِدُ"', '', 'R', '', '', '', '', '', '', '". 1.: قِطْعَةٌ مِنَ العَاجِ أَوْ مِنَ الخَشَبِ تُسْتَخْدَمُ لِوَضْعِ الكُحْلِ فِي أَهْدابِ العَيْنِ. 2.""مِرْوَدُ البَكَرَةِ"" : قَضِيبٌ قَصِيرٌ مِنْ حَدِيدٍ تُدَارُ عَلَيْهِ البَكَرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9831, 'مَرَاوِدُ', 'مراود', 'جامد', '', 'مراود', 'مرد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9832, 'روزَنامَةٌ', 'روزنامة', 'جامد', '', 'روزنامة', 'رزنمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"1. : سِجِلٌّ لأَيَّامِ السَّنَةِ، يَتَضَمَّنُ أَحْوالَ شُهورِ السَّنَةِ وَطُلوعِ الشَّمْسِ والقَمَرِ. 2. : إِدارَةُ صَرْفِ مُرَتَّباتِ أَرْبابِ الْمَعاشِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9833, 'رَوائِسُ', 'روائس', 'جامد', 'روس', 'رواءس', 'رس', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَوائِسُ-رَوائِسُ [ر و س]. 1.""سُحُبٌ رَوائِسُ"" : سُحُبٌ مُتَقَدِّمَةٌ. 2.""رَوائِسُ الأَوْدِيَةِ"" : أَعالِيها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9834, 'رَوْضَةٌ', 'روضة', 'جامد', 'روض', 'روضة', 'رضة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":رِياضٌ:رَوْضٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِسْتَطابَ النُّزْهَةَ في الرَّوْضَةِ"" : البُستانُ الحَسَنُ، الحَدِيقَةُ الغَنَّاءُ. 2.الروم آية 15 فَأَمَّا الَّذِينَ آمَنوا وَعَمِلُوا الصَّالِحاتِ فَهُمْ في رَوْضَةٍ يُحْبَرونَ (قرآن) : الجَنَّةُ. 3.""رَوْضَةُ الأَطْفالِ"" : حَديقَةُ الأَطْفالِ يَرْتادونَها في سِنِّ الثَّالِثَةِ لِتَهْيِيئِهِمْ لِلمَدْرَسَةِ الاِبْتِدائِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9835, 'رِياضٌ', 'رياض', 'جامد', '', 'رياض', 'رض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9836, 'رَوْضٌ', 'روض', 'جامد', '', 'روض', 'رض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9837, 'رَوْضٌ', 'روض', 'جامد', 'روض', 'روض', 'رض', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَوْضٌ-رَوْضٌ [ر و ض]. ""أَرْضٌ رَوْضٌ"" : مُخْضَرَّةٌ بِأَنْواعِ النَّباتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9838, 'رِياضِيَّاتٌ', 'رياضيات', 'جامد', 'روض', 'رياضيات', 'رضت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"رِياضِيَّاتٌ-رِياضِيَّاتٌ [ر و ض]. ""شُعْبَةُ الرِّياضِيَّاتِ"" : شُعْبَةُ عِلْمِ الحِسابِ والجَبْرِ والهَنْدَسَةِ. ""عالِمُ الرِّياضِيَّاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9839, 'رَوْعَةٌ', 'روعة', 'جامد', 'روع', 'روعة', 'رعة', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَوْعَةٌ-رَوْعَةٌ [ر و ع]. ""رَوْعَةُ الطَّبيعَةِ"" : جَمالُها، فِتْنَتُها، بَهاؤُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9840, 'رُوعٌ', 'روع', 'جامد', 'روع', 'روع', 'رع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَوْعٌ-رَوْعٌ [ر و ع] (مص. راعَ). ""أَدْخَلَ الرَّوْعَ على قَلْبِهِ"": الفَزَعَ، الهَلَعَ.هود آية 74 فَلَّمَّا ذَهَبَ عَنْ إِبْراهيمَ الرَّوْعُ، وَجاءتْهُ البُشْرَى (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9841, 'رِواقٌ', 'رواق', 'جامد', 'روق', 'رواق', 'رق', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْوِقَةٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""رِواقُ البَيْتِ"" : سَقْفٌ في مُقَدِّمَتِهِ. 2.""جَلَسُوا في الرِّواقِ"" : مِظَلَّةٌ، سَقيفَةٌ في زَاوِيَةِ مَسْجِدٍ أَوْ مَعْبَدٍ أَوْ في وَسَطِهِما تُخَصَّصُ لِلدِّراسَةِ. 3.""زارَ الرِّواقَ العَرَبِيَّ في الْمَعْرِضِ الدَّوْلِيِّ"" : الجَناحُ الْمُسَيَّجُ وَسَطَ الأَرْوِقَةِ الأُخْرَى في الْمَعْرِضِ. 4.""خَرَجَ في رِواقِ اللَّيْلِ"" : في ظُلْمَتِهِ. 5.""رِواقُ العَيْنِ"" : حاجِبُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9842, 'أَرْوِقَةٌ', 'أروقة', 'جامد', '', 'ءروقة', 'رقة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9843, 'رَوْقَةٌ', 'روقة', 'جامد', 'روق', 'روقة', 'رقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رَوْقَةٌ-رَوْقَةٌ [ر و ق]. ""رَوْقَةُ الْمَنْظَرِ"" : جَمالُهُ الرَّائِقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9844, 'رُوقَةٌ', 'روقة', 'جامد', 'روق', 'روقة', 'رقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رُوقَةٌ-رُوقَةٌ [ر و ق]. ""رُوقَةُ النَّاسِ"" : خِيارُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9845, 'رُوقٌ', 'روق', 'جامد', 'روق', 'روق', 'رق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رُوقٌ-رُوقٌ [ر و ق]. ""رُوقُ الفَرَسِ"" : الرُّمْحُ الَّذِي يَمُدُّهُ الفارِسُ بَيْنَ أُذُنَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9846, 'مُرَوَّلَةٌ', 'مرولة', 'جامد', 'رول', 'مرولة', 'مرلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '".: قِطْعَةُ خُبْزٍ تُوضَعُ عَلَيْهَا زُبْدَةٌ أَوْ مُرَبَّى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9847, 'رُومٌ', 'روم', 'جامد', 'روم', 'روم', 'رم', '', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"رُومٌ-رُومٌ [ر و م]. 1.""رومُ الأُذُنِ"" : شَحْمَتُها. 2.""خَمْرُ الرُّومِ"" : شَرابٌ مُسْكِرٌ يُسْتَخْرَجُ مِن تَخْميرِ عُصارَةِ قَصَبِ السُّكَّرِ وَتَقْطِيرِها. 3.""الرُّومُ"" : سورَةٌ مِنْ سُوَرِ القُرآنِ. 4.""بَحْرُ الرُّومِ"" : البَحْرُ الأَبْيَضُ الْمُتَوَسِّطُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9848, 'رُومٌ', 'روم', 'جامد', '', 'روم', 'رم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"1. ن. رومان. 2.""الرُّومُ الأرْثوذِكس"" : يَنْتَمونَ إلى الكَنيسَةِ الْمَسيحِيَّةِ الشَّرْقِيَّةِ البيزَنْطِيَّةِ. 3.""الرُّومُ الكاثوليك"": هُمُ التَّابِعونَ لِسُلْطَةِ البابا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9849, 'روماتِيزَمٌ', 'روماتيزم', 'جامد', '', 'روماتيزم', 'رمتزم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": داءٌ يُصيبُ العَضَلاتِ والْمَفاصِلَ والأَنْسِجَةَ اللِّيفِيَّةَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9850, 'رُومانُ', 'رومان', 'جامد', '', 'رومان', 'رمن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rp', '', 'N', 'O', 'N', 'O', '', '": البِيزَنْطِيّونَ الَّذِينَ أَسَّسُوا الدَّوْلَةَ البيزَنْطِيَّةَ في القِسْمِ الشَّرْقِيِّ مِن الاِمْبَراطورِيَّةِ الرُّومانِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9851, 'رَوَنْدٌ', 'روند', 'جامد', '', 'روند', 'رند', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": جِنْسُ عُشْبٍ مُعَمِّرٌ، طِبِّيٌّ يُعْرَفُ أَيْضاً بِالرَّاوَنْدَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9852, 'أُرْوِيَّةٌ', 'أروية', 'جامد', 'روي', 'ءروية', 'رة', '', '', '', 'مفرد', 'DnN', '', '', '"أَرَاوٍ:الأرَاوِيُّ"', '', '', '', 'N', 'O', 'O', 'O', '', '"(حو).: أُنْثَى الوَعْلِ ضَأْن الجَبَلِ، لَهَا قَرْنَانِ مُنْتَحِيَانِ، وَهِيَ تُطْلَقُ عَلَى الذَّكَرِ وَالأنْثَى. ¨ ""تَرُودُ الأرَاوِيُّ حَوْلِي"". (الشنفرى)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9853, 'أَرَاوِي', 'أراوي', 'جامد', '', 'ءراوي', 'ر', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9854, 'رُواءٌ', 'رواء', 'جامد', 'روي', 'رواء', 'ر', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"رُواءٌ-رُواءٌ [ر و ي]. 1.""رُواءُ الوَجْهِ"" : بَهاؤُهُ ، جَمالُهُ. 2.""رُواءُ مَنْظَرٍ"" : حُسْنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9855, 'رِواءٌ', 'رواء', 'جامد', 'روي', 'رواء', 'ر', '', '', '', 'مفرد', 'DzDw', '', '', '"أَرْوِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '". ""رِواءُ الرَّحْلِ"" : حَبْلٌ تُشَدُّ بِهِ الأَمْتِعَةُ والأَحْمالُ على ظَهْرِ الجَمَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9856, 'أَرْوِيَةٌ', 'أروية', 'جامد', '', 'ءروية', 'رة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9857, 'رَوِيَّةٌ', 'روية', 'جامد', 'روي', 'روية', 'رة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"مؤنثالرَّوِيّ"', '', '', '', '', '', '', '', '', '". ""يَتَصَرَّفُ بِرَوِيَّةٍ"" : بِتَفْكيرٍ وَبُعْدِ نَظَرٍ. ""يَتَصَرَّفُ بِلاَ رَوِيَّةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9858, 'الرِّياض', 'الرياض', 'جامد', '', 'الرياض', 'لرض', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '": عاصِمَةُ الْمَمْلَكةِ العَرَبِيَّةِ السَّعودِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9859, 'رِياشٌ', 'رياش', 'جامد', 'ريش', 'رياش', 'رش', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رِياشٌ-رِياشٌ [ر ي ش]. 1.""يَضُمُّ البَيْتُ رِياشاً ثَميناً"" : أَثاثاً فاخِراً. 2.""رِياشُ اللِّباسِ"" : الحَسَنُ الفاخِرُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9860, 'رِيشَةٌ', 'ريشة', 'جامد', 'ريش', 'ريشة', 'رشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". وَاحِدَةُ الرِّيشِ. 1.""ريشَةُالكَاتِبِ"" : قَلَمٌ لَهُ سِنٌّ مَعْدِنِيَّةُ يُكْتَبُ بِها بِالحِبْرِ. ""كانَ القُدَماءُ يَكْتُبونَ بِريِشَةِ الطَّائِرِ"". 2.""يَنْقُرُ على العودِ بِريشَـةٍ"" : خَشَبَةٌ صَغيرَةٌ مَنْحوتَةٌ أَوْ ما شابَهَ ذَلِكَ يُنْقَرُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9861, 'رِيشٌ', 'ريش', 'جامد', 'ريش', 'ريش', 'رش', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَيْشٌ-رَيْشٌ [ر ي ش] (مص. راشَ يَريشُ). 1.""كَثُرَ رَيْشُهُ"": أَثاثُهُ. 2.""عُشْبٌ رَيْشٌ"" : كَثيرُ الوَرَقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9862, 'رَيْعانٌ', 'ريعان', 'جامد', 'ريع', 'ريعان', 'رعن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَيْعانٌ-رَيْعانٌ [ر ي ع]. 1.""هُوَ في رَيْعانِ عُمْرِهِ"" : في أَوَّلِهِ، في عِزِّهِ، أَي الفَتْرَة الزَّاهِيَة مِنَ حَياةِ الإِنْسانِ. ""ما يَزالُ في رَيْعانِ شَبابِهِ"". 2.""رَيْعَانُ الرَّبِيعِ"" : بِدَايَتُهُ، أَوَّلُهُ. مَرْحَباً بِالرَّبيعِ في رَيْعانِهِ*وَبِأَنْوارِهِ وَطيبِ زَمانِهِ (أحمد شَوْقِي). 3.""رَيْعانُ الْمَطَرِ"" : أَوَّلُهُ. 4.""رَيْعانُ السَّرابِ"" : ما اضْطَرَبَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9863, 'ريعٌ', 'ريع', 'جامد', 'ريع', 'ريع', 'رع', '', '', '', 'مفرد', 'DnN', '', '', '"رِياعٌ:رُيوعٌ:أَرْياعٌ"', '', 'R', '', '', '', '', '', '', '". 1.""مَكانٌ ريعٌ"" : مُرْتَفِعٌ. 2.""اِنْتَظَرَهُ في رِيعٍ"" : في طَريقٍ. 3. : الصَّوْمَعَةُ. 4. : بُرْجُ الحَمامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9864, 'رِياعٌ', 'رياع', 'جامد', '', 'رياع', 'رع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9865, 'رُيوعٌ', 'ريوع', 'جامد', '', 'ريوع', 'رع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9866, 'أَرْياعٌ', 'أرياع', 'جامد', '', 'ءرياع', 'رع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9867, 'رِيفٌ', 'ريف', 'جامد', 'ريف', 'ريف', 'رف', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْيافٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""نَشَأَ في الرِّيفِ"" : في البادِيَةِ، والرِّيفِ، أَيِ الأَرْضِ الَّتِي بِها الْمَزروعاتُ. 2.""مِنْ سُكَّانِ الرِّيفِ"" : مِنْ مِنْطَقَةِ شَمالِ الْمَغْرِبِ، كَما يُمْكِنُ أَنْ تُطْلَقَ على ساكِنِ البادِيَةِ. ""ما أَزْهَى حَياةَ الرِّيفِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9868, 'أَرْيافٌ', 'أرياف', 'جامد', '', 'ءرياف', 'رف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9869, 'تِرْيَاقٌ', 'ترياق', 'جامد', 'ريق', 'ترياق', 'ترق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تِرْيَاقٌ-تِرْيَاقٌ [ر ي ق].: دَوَاءٌ لِلْعِلاَجِ مِنَ السُّمُومِ. ""أَنَا الْمَسْمُومُ مَا لِي تِرْيَاقٌ وَلاَ رَاقٍ"" (مثل) : لَيْسَ لِي دَوَاءٌ يَدْفَعُ عَنِّي السُّمُومَ وَلاَ طَبِيبٌ ""بَعْضُ السُّمِّ تِرْياقٌ لِبَعْضٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9870, 'رَيِّقٌ', 'ريق', 'جامد', 'ريق', 'ريق', 'رق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَيْقٌ-رَيْقٌ [ر ي ق] (مص. راقَ يَريقُ). 1.""رَيْقُ الْمَطَرِ"" : أَوَّلُهُ. 2.""رَيْقُ الشَّيْءِ"" : أَفْضَلُهُ. 3.""اِنْسابَ رَيْقاً"" : ماءً. 4.""خُبْزٌ رَيْقٌ"" : لَم يُخْلَطْ بِما يُطَيِّبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9871, 'رِيقٌ', 'ريق', 'جامد', 'ريق', 'ريق', 'رق', '', '', '', 'مفرد', 'DnN', '', '', '"أَرْياقٌ:رِياقٌ"', '', 'R', '', '', '', '', '', '', '". 1.""بَلَعَ رِيقَهُ"" : أَي لُعابَ الفَمِ. 2.""مازِلْتُ على الرِّيقِ"" : أَيْ لَمْ أَذُقْ بَعْدُ طَعاماً وَلا شَراباً. ""يَأْكُلُ أُصْبُعَهُ أَسَفاً وَيَزْدَرِدُ ريقَهُ لَهَفاً"". (التوحيدي). 3.""رِيقُ الشَّيْءِ"" : قُوَّتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9872, 'أَرْياقٌ', 'أرياق', 'جامد', '', 'ءرياق', 'رق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9873, 'رِياقٌ', 'رياق', 'جامد', '', 'رياق', 'رق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9874, 'رِيالٌ', 'ريال', 'جامد', 'ريل', 'ريال', 'رل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رِيالٌ-رِيالٌ [ر ي ل]. 1.""رِيالُ الطِّفْلِ"" : لُعابُهُ. 2.: عُمْلَةٌ مِنَ الْمَسْكوكاتِ الفِضِّيَّةِ الإِسْبانِيَّةِ قَدِيماً. وَراجَ الاصْطِلاحِ نَفْسُهُ بِالْمَغْرِبِ والْمَمْلَكَةِ العَرَبِيَّةِ السَّعودِيَّةِ، الرِّيَالُ الْمَغْرِبِيُّ يُساوِي 5 سَنْتِيماتٍ، والرِّيَالُ السَّعودِي يُساوِي 2.40 دِرْهَماً مَغْرِبِيّاً تَقْرِيباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9875, 'مَرْيَلَةٌ', 'مريلة', 'جامد', 'ريل', 'مريلة', 'مرلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَرْيَلَةٌ-مَرْيَلَةٌ [ر ي ل].: قِطْعَةٌ مِنْ نَسِيجٍ أَوْ جِلْدٍ تُوضَعُ عَلَى صَدْرِ الطِّفْلِ عِنْدَ الأَكْلِ لِتَحْفَظَ مَلاَبِسَهُ، أي لِكَيْ لاَ يَسِيلَ عَلَيْهَا لُعَابُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9876, 'رَيْمٌ', 'ريم', 'جامد', 'ريم', 'ريم', 'رم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"رَيْمٌ-رَيْمٌ [ر ي م]. 1.""حَفَرَ الرَّيْمَ"" : القَبْرَ. 2.""وَصَلَ في الرَّيْمِ"" : مِنْ آخِرِ النَّهارِ إلَى اخْتِلاطِ الظُّلْمَةِ. 3.""عَلَيْكَ نَهارٌ رَيْمٌ"" : طَويلٌ. 4.""بَقِيَ رَيْمٌ مِنَ النَّهارِ"" : ساعَةٌ طَويلَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9877, 'رِيمٌ', 'ريم', 'جامد', '', 'ريم', 'رم', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": الظَّبْيُ الأَبْيَضُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9878, 'رَيْنَةٌ', 'رينة', 'جامد', 'رين', 'رينة', 'رنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"رَيْنَةٌ-رَيْنَةٌ [ر ي ن]. ""نَهَاهُ عَنْ شُرْبِ الرَّيْنَةِ"" : الخَمْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9879, 'زِئْبَقٌ', 'زئبق', 'جامد', 'زأبق', 'زءبق', 'زبق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زِئْبَقٌ-زِئْبَقٌ[ز أ ب ق]. : عُنْصُرٌ فِضِّيٌّ سائِلٌ لامِعٌ، عَدَدُهُ الذَّرِّيُّ (8)، وَكُتْلَتُهُ الذَّرِّيَّةُ (200', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9880, 'زاغٌ', 'زاغ', 'جامد', '', 'زاغ', 'زغ', '', '', '', 'جمع تكسير', 'DnN', '', '', '"زِيغانٌ:أَزْوَاغٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: زِيغانٌ، أَزْوَاغٌ. (حو). : طَيْرٌ مِنْ فَصيلَةِ الغِرْبانِ، مِنْرُتْبَةِ العُصْفورِيَّاتِ بِحَجْمِ الْحَمامَةِ، ذَنَبُهُ مُرَبَّعُ الشَّكْلِ وَريشُ ظَهْرِهِ أَسْوَدُ، بِرَأْسِهِ غُبْرَةٌ وَمَيْلٌ إلى البَياضِ، والقِسْمُ الأَعْلَى مِنْ مِنْقارِهِ مُنْعَطِفٌ نَحْوَ الأَسْفَلِ قَليلاً، يُقالُ لَهُ أَيْضاً الغُرابُ الزَّرْعِيُّ وَغُرابُ الزَّيْتونِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9881, 'زِيغانٌ', 'زيغان', 'جامد', '', 'زيغان', 'زغن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9882, 'أَزْوَاغٌ', 'أزواغ', 'جامد', '', 'ءزواغ', 'زغ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9883, 'زَبادٌ', 'زباد', 'جامد', '', 'زباد', 'زبد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1. : مادَّةٌ عَطِرَةٌ تُتَّخَذُ مِنْ سِنَّوْرِ الزَّبادِ. 2.""سِنَّوْرُ الزَّبَادِ"" (حو). : حَيَوانٌ مِنْ فَصيلَةِ الزَّبادِيَّاتِ، مِنْ رُتْبَةِ اللَّواحِمِ، يَتَمَيَّزُ بِوُجودِ جَيْبٍ تَحْتَ اِسْتِهِ تَتَجَمَّعُ فيـهِ مـادَّةٌ عَطِرَةٌ، يَعيشُ في الجِبالِ والأَدْغالِ، يَقْتاتُ بِالْحَيَواناتِ والحَشَراتِ والثِّمارِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9884, 'زَبادِيَّاتٌ', 'زباديات', 'جامد', '', 'زباديات', 'زبدت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصيلَةٌ حَيَوانِيَّةٌ مِن اللَّواحِمِ، مُفْتَرِسَةٌ، أَنْواعُها عَديدَةٌ مِنْها سِنَّوْرُ الزَّبادِ والنِّمْسُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9885, 'زَبيبٌ', 'زبيب', 'جامد', 'زبب', 'زبيب', 'زبب', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"زَبيبٌ-زَبيبٌ، ةٌ[ز ب ب]. ""تَحَوَّلَ العِنَبُ إلى زَبيبٍ"" : أَي العِنَبُ الْمُجَفَّفُ اليابِسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9886, 'زُبَّادٌ', 'زباد', 'جامد', 'زبد', 'زباد', 'زبد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زُبَّادٌ-زُبَّادٌ[ز ب د]. 1.""أَطْعَمَهُ الزُّبَّادَ"" : الزُّبْدَ. 2. : نَوْعٌ مِنَ النَّبَاتِ. 3.""زُبَّادُ اللَّبَنِ"" : مَالاَ خَيْرَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9887, 'زُبْدَةٌ', 'زبدة', 'جامد', 'زبد', 'زبدة', 'زبدة', '', '', '', 'مفرد', 'DnN', '', '', '"زُبَدٌ"', '', 'R', '', '', '', '', '', '', '". 1.""زُبْدَةُ البَقَرِ"". ن. زُبْدٌ. ""مَعَ الْمَخْضِ تَبْدُو الزُّبْدَةُ"". 2.""زُبْدَةُ الْمَوْضوعِ"" : خُلاصَتُهُ، ما هُوَ أَساسِيٌّ فيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9888, 'زُبَدٌ', 'زبد', 'جامد', '', 'زبد', 'زبد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9889, 'زَبَدٌ', 'زبد', 'جامد', 'زبد', 'زبد', 'زبد', '', '', '', 'مفرد', 'DnN', '', '', '"أَزْبادٌ"', '', 'R', '', '', '', '', '', '', '". 1.""زَبَدُ البَحْرِ"" : رَغْوَتُهُ، ما يَعْلو الْمَاءَ وَنَحْوَهُ مِنْ رَغْوَةٍ. 2.""ظَهَرَ زَبَدٌ على جانِبَيْ فَمِهِ"" : ما يَخْرُجُ مِنَ الفَمِ في حالَةِ الغَضَبِ. 3.""لاَ يَمْلِكُ إِلاَّ الزَّبَدَ"" : مَا لاَخَيْرَ فِيهِ وَلاَ فَائِدَةَ. الرعد آية 17فَأَمَّا الزَّبَدُ فَيَذْهَبُ جُفاءً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9890, 'أَزْبادٌ', 'أزباد', 'جامد', '', 'ءزباد', 'زبد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
