INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9894, 'زُبْدِيَّةٌ', 'زبدية', 'جامد', '', 'زبدية', 'زبدة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"ج: زُبْدِيَّاتٌ، زُبادِيٌّ : صَحْفَةٌ مِنْ خَزَفٍ يُخَثَّرُ فيها اللَّبَنُ، وَتُطْلَقُ في مِصْر عَلَى اللَّبَنِ الرَّائِبِ."', ':لا جذر:لا مفرد');
