INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9905, 'زَوْبَعَةٌ', 'زوبعة', 'جامد', 'زبع', 'زوبعة', 'زبعة', '', '', '', 'مفرد', 'DnN', '', '', '"زَوابِعُ"', '', 'R', '', '', '', '', '', '', '". 1.""هَبَّتْ زَوْبَعَةٌ"" : الإِعْصارُ الشَّديدُ، وَهُوَ عِبارَةٌ عَنْ تَصاعُدِ الرِّياحِ إلى السَّماءِ. 2.""زَوْبَعَةٌ في فِنْجانٍ"" : هَيَجانٌ مَحْدودُ الأَثَرِ في وَقْتٍ مُعَيَّنٍ."', '');
