INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9913, 'زُبانَى', 'زبانى', 'جامد', 'زبن', 'زبانى', 'زبن', '', '', '', 'مفرد', 'Dy', '', '', '"زُبانِياتٌ"', 'ممنوع من الصرف', 'R0', '', 'N', 'O', 'O', 'O', '', '". 1.""زُبانَى العَقْرَبِ"" : قَرْنُها، وَهُما زُبانِيانِ. 2.""الزُّبانِيانِ"" : نَجْمانِ في المِيزَانِ، هُما الْمَنْزِلُ السَّادِسُ عَشَرَ مِنْ مَنازِلِ القَمَرِ."', '');
