INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9915, 'زِبْنٌ', 'زبن', 'جامد', 'زبن', 'زبن', 'زبن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زِبْنٌ-زِبْنٌ[ز ب ن]. ""أَخَذَ زِبْنَهُ مِنَ الطَّعامِ"" : حاجَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9916, 'زَبونٌ', 'زبون', 'جامد', 'زبن', 'زبون', 'زبن', '', '', '', 'مفرد', 'DnN', '', '', '"زُبُنٌ"', '', 'R', '', '', '', '', '', '', '". ""زَبونٌ قَديمٌ"" : الْمُشْتَرِي، الْمُتَرَدِّدُ باسْتِمْرارٍ عَلَى تاجِرٍ واحِدٍ لِشِراءِ ما يَحْتاجُهُ مِنْ مَوادَّ. ""يُحافِظُ عَلَى زُبُنِهِ بِالْمُعامَلَةِ الحَسَنَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9917, 'زُبُنٌ', 'زبن', 'جامد', '', 'زبن', 'زبن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9918, 'زُبْيَةٌ', 'زبية', 'جامد', 'زبي', 'زبية', 'زبة', '', '', '', 'مفرد', 'DnN', '', '', '"زُبًى"', '', '', '', '', '', '', '', '', '". ""حَفَرُوا زُبْيَةً لِصَيْدِ الأَسَدِ"" : الحُفْرَةُ يُغَطَّى رَأْسُها لِصَيْدِ الأَسَدِ أَوْ كُلُّ حَيَوانٍ مُفْتَرِسٍ للإيقاعِ بِهِ. ""بَلَغَ السَّيْل الزُّبَى"" (مثل) : أَيْ تَجاوَزَ الأَمْرُ حُدودَهُ بِتَفاقُمِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9919, 'زُبًى', 'زبى', 'جامد', '', 'زبى', 'زب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9920, 'زُجٌّ', 'زج', 'جامد', '', 'زج', 'زج', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَزْجاجٌ:زِجاجٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَزْجاجٌ، زِجاجٌ. 1.""زُجُّ الرُّمْحِ"" : الحَديدَةُ الْمُلْتَصِقَةُ في أَسْفَلِهِ. 2.""زُجُّ السَّهْمِ"" : نَصْلُهُ. 3.""زُجُّ المِرْفَقِ"" : طَرَفُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9921, 'أَزْجاجٌ', 'أزجاج', 'جامد', '', 'ءزجاج', 'زجج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9922, 'زِجاجٌ', 'زجاج', 'جامد', '', 'زجاج', 'زجج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9923, 'زُجاجَةٌ', 'زجاجة', 'جامد', 'زجج', 'زجاجة', 'زججة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""زُجاجَةُ النَّافِذَةِ"" : القِطْعَةُ مِنَ الزُّجَاجِ. 2.""سَكَبَ الْمَاءَ مِنَ الزُّجاجَةِ"" : القِنِّينَةُ، إِناءٌ مِنْ زُجاجٍ. 3.النور آية 35 مَثَلُ نورِهِ كَمِشْكاةٍ فيها مِصْباحٌ، المِصْباحُ في زُجاجَةٍ (قرآن) : أَيْ في قِنْديلٍ مِنْ زُجاجٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9924, 'زِجاجَةٌ', 'زجاجة', 'جامد', 'زجج', 'زجاجة', 'زججة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"زِجاجَةٌ-زِجاجَةٌ[ز ج ج ]. 1. : القِطْعَةُ مِنَ الزُّجاجِ. 2. : صِناعَةُ الزَّجَّاجِ وَحِرْفَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9925, 'زُجاجٌ', 'زجاج', 'جامد', 'زجج', 'زجاج', 'زجج', '', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"زَجَّاجٌ-زَجَّاجٌ[ز ج ج] (صِيغَةُ فَعَّال). ""زَجَّاجٌ ماهِرٌ"" : صانِعُ الزُّجاجِ وَبائِعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9926, 'زَجَرٌ', 'زجر', 'جامد', '', 'زجر', 'زجر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"زُجورٌ"', '', 'R', '', '', '', '', '', '', '"ج: زُجورٌ. (حو). : جِنْسُ أَسْماكٍ من فَصيلَةِ البَهَارِيَّاتِ، شائِكَةُ الزَّعانِفِ، طَويلَةٌ، لَها رُؤوسٌ غَليظَةٌ، عُيُونُها كَبيرَةٌ مُسْتَديرَةٌ جاحِظَةٌ، زَعانِفُها الظَّهْرِيَّةُ مُسْتَطيلَةٌ، حَراشِفُها صَغيرَةٌ، يُراوِحُ طولُها ما بَيْنَ (70) وَ (120) سم."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9927, 'زُجورٌ', 'زجور', 'جامد', '', 'زجور', 'زجر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9928, 'زُحارٌ', 'زحار', 'جامد', 'زحر', 'زحار', 'زحر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زُحارٌ-زُحارٌ[ز ح ر]. ""أُصيبَ بالزُّحارِ"" : مَرَضٌ تَظْهَرُ أَعْراضُهُ بِتَبَرُّزٍ مُتَقَطِّعٍ، مُعْظَمُهُ دَمٌ وَمُخاطٌ مَصْحوبٌ بِأَلَمٍ وَمَغْصٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9929, 'زَحَّافاتٌ', 'زحافات', 'جامد', 'زحف', 'زحافات', 'زحفت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"زَحَّافاتٌ-زَحَّافاتٌ[ز ح ف]. ""الأَفْعَى مِنَ الحَيَواناتِ الزَّحَّافـاتِ"" : زَوَاحِفُ، كُلُّ الْحَيَواناتِ الَّتِي تَدِبُّ على الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9930, 'زَحَّافَةٌ', 'زحافة', 'جامد', 'زحف', 'زحافة', 'زحفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"زَحَّافَةٌ-زَحَّافَةٌ[ز ح ف]. ""سَوَّى الأَرْضَ بِالزَّحَّافَةِ"" : آلَةٌ تُسَوَّى بِها الأَرْضُ لِلزَّرْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9931, 'زِحافٌ', 'زحاف', 'جامد', 'زحف', 'زحاف', 'زحف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زِحافٌ-زِحافٌ[ز ح ف]. : هُوَ في عِلْمِ العَروضِ تَغْيِيرٌ يَلْحَقُ ثانِيَ السَّبَبِ الْخَفيفِ أَوِ الثَّقيلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9932, 'زَواحِفُ', 'زواحف', 'جامد', 'زحف', 'زواحف', 'زحف', '', '', '', 'مفرد', '', '', '', '"مفردزَاحِفَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". : الزَّحَّافَاتُ، الْحَيَواناتُ الفِقْرِيَّاتُ ذَواتُ الدَّمِ البارِدِ وَتَنْقَسِمُ إلى فِئَتَيْنِ: فِئَةٍ ذاتِ قَوائِمَ كالتَّماسِيحِ وَفِئَةٍ بِلا قَوائِمَ كالْحَيَّاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9933, 'زَاحِفَة', 'زاحفة', 'جامد', '', 'زاحفة', 'زحفة', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9934, 'مَزَاحِفُ', 'مزاحف', 'جامد', 'زحف', 'مزاحف', 'مزحف', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَزَاحِفُ-مَزَاحِفُ [ز ح ف]. 1.""مَزَاحِفُ الْحَيَّاتِ"" : مَوَاضِعُ دَبِّهَا، تَزْحَفُ وَتَنْسَابُ فِيهَا. 2.""مَزَاحِفُ السَّحَابِ"" : مَوَاقِعُ مَطَرِهِ. ن. مَزْحَفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9935, 'مَزْحَفٌ', 'مزحف', 'جامد', 'زحف', 'مزحف', 'مزحف', '', '', '', 'مفرد', 'DnN', '', '', '"مَزَاحِفُ"', '', 'R', '', '', '', '', '', '', '". ""مَزَاحِفُ الْحَيَّاتِ"" : مَوَاضِعُ دَبِّهَا وَزَحْفِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9936, 'مَزَاحِفُ', 'مزاحف', 'جامد', '', 'مزاحف', 'مزحف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9937, 'زُحَلٌ', 'زحل', 'جامد', 'زحل', 'زحل', 'زحل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'O', '', '"زُحَلٌ-زُحَلٌ[ز ح ل] (فك). : أَحَدُ الكَواكِبِ السَّيَّارَةِ في النِّظامِ الشَّمْسِيِّ، مُحاطٌ بِمِنْطَقَةٍ مُشِعَّةٍ، يُضْرَبُ بِهِ الْمَثَلُ في العُلُوِّ والبُعْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9938, 'زَواخِرُ', 'زواخر', 'جامد', 'زخر', 'زواخر', 'زخر', '', '', '', 'مفرد', '', '', '', '"مفردزَاخِر"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""زَواخِرُ الوادِي"" : أَعْشابُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9939, 'زَخارِفُ', 'زخارف', 'جامد', 'زخرف', 'زخارف', 'زخرف', '', '', '', 'مفرد', '', '', '', '"مفردزُخْرُف"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ن. زُخْرُفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9940, 'زُخْرُفٌ', 'زخرف', 'جامد', 'زخرف', 'زخرف', 'زخرف', '', '', '', 'مفرد', 'DnN', '', '', '"زَخارِفُ"', '', 'R', '', '', '', '', '', '', '". 1.""وَضَعَتْ في عُنُقِها قِلادَةً مِنَ الزُّخْرُفِ"" : مِنَ الذَّهَبِ. الإسراء آية 93 أَوْ يَكونَ لَكَ بَيْتٌ مِن زُخْرُفٍ (قرآن). 2.""زُخْرُفُ الأَرْضِ"" : أَلْوانُ نَباتِها.يونس آية 64 حَتَّى إِذَا أَخَذَتِ الأَرْضُ زُخْرُفَها (قرآن). 3.""زُخْرُفُ الدُّنيا"" : مَتاعُهَا، بَهْجَتُهَا. ""لا تَغْتَرَّ بِزَخارِفِ الدُّنْيا"" ""الدُّنْيا زُخْرُفٌ يَغْلِبُ الجوارِحَ ما لَمْ تَغْلِبْهُ الأَلْبابُ"". (ابن المقفع). 4.""زَيَّنَ البابَ بِزَخارِفَ في مُنْتَهَى الرَّوْعَةِ"" : بِرُسومٍ زاهِيَةٍ. 5.""يَجْذِبُ النَّاسَ إِلَيْهِ بِزُخْرُفِ الكَلامِ"": بِأُسْلوبِهِ الْمُنَمَّقِ الْمَلِيءِ بِالتَّمْويهِ والأَباطيلِ والكَذِبِ.الأنعام آية 114 يُوحِي بَعْضُهُمْ إلى بَعْضٍ زُخْرُفَ القَوْلِ غُروراً (قرآن). 6.""زَخارِفُ الماءِ"" : طَرائِقُهُ. 7.""زَخارِفُ""(حش). : دُوَيْبَاتٌ تَطيرُ عَلَى الْمَاءِ، مِنْ ذَواتِ الأَرْبَعِ كالذُّبابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9941, 'زَخارِفُ', 'زخارف', 'جامد', '', 'زخارف', 'زخرف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9942, 'زِرٌّ', 'زر', 'جامد', '', 'زر', 'زر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَزْرارٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَزْرارٌ. 1.""زِرُّ الوَركِ"" : وَهُما زِرَّانِ. 2.""زِرُّ القَلْبِ"" : عُظَيْمٌ تَحْتَ القَلْبِ وَهُوَ قِوامُهُ. 3.""عَقَدَ زِرَّ مِعْطَفِهِ"": صَدَفَتَهُ. 4.""ضَغَطَ على الزِّرِّ الكَهْرَبائِيِّ"" : آلَةُ المِفْتاحِ الَّتِي مِنْها يُشْعَلُ الضَّوْءُ. 5.""زِرُّ الْجَرَسِ"": الآلَةُ الَّتِي يُضْغَطُ عَلَيْها فَيَرِنُّ الْجَرَسُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9943, 'أَزْرارٌ', 'أزرار', 'جامد', '', 'ءزرار', 'زرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9944, 'زُرافَةٌ', 'زرافة', 'جامد', '', 'زرافة', 'زرفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":زَرافَى"', '', '', '', '', '', '', '', '', '"ج: زَرافَى، زَرافاتٌ. مِنْ رُتْبَةِ شَفْعِيَّةِ الأَظْلافِ، وَهِيَ مِنَ اللَّبائِنِ الْمُجْتَرَّةِ، طَويلَةُ العُنُقِ، قَائِمَتَاهَا الأَمامِيَّتَانِ(اليَدانِ) أَطْوَلُ مِنْ قَائِمَتَيْها الْخَلْفِيَّتَيْنِ (الرِّجْـلانِ)، يَعْلُو رَأْسَها قَرْنانِ قَصيرانِ، جِلْدُها تَسودُهُ بُقَعٌ مُحْمَرَّةٌ وَمُصْفَرَّةٌ، مَوْطِنُها إِفْريقِيا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9945, 'زَرافَى', 'زرافى', 'جامد', '', 'زرافى', 'زرف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9946, 'زِرْبٌ', 'زرب', 'جامد', 'زرب', 'زرب', 'زرب', '', '', '', 'مفرد', 'DnN', '', '', '"زُروبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""زِرْبُ الْمَاشِيَةِ"" : حَظيرَتُها. 2.""زِرْبُ الْمَاءِ"" : مَسيلُهُ."', '');
