INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9948, 'زَريبَةٌ', 'زريبة', 'جامد', 'زرب', 'زريبة', 'زربة', '', '', '', 'مفرد', 'DnN', '', '', '"زَرائِبُ"', '', '', '', '', '', '', '', '', '". ""زَرَبَ الماشِيَةَ في الزَّريبَةِ"": حَظيرَةُ الْماشِيَةِ. ""زَريبَةُ البَقَرِ"" ""زَريبَةُ الغَنَمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9949, 'زَرائِبُ', 'زرائب', 'جامد', '', 'زراءب', 'زرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
