INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9952, 'زَرْبِيَّةٌ', 'زربية', 'جامد', '', 'زربية', 'زربة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"زَرابِيُّ"', '', '', '', '', '', '', '', '', '"ج: زَرابِيُّ. ""فَرَشَ بَيْتَهُ بِزَرْبِيَّةٍ زاهِيَةٍ"" : سَجادٌ، سَجَّادَةٌ تُصْنَعُ مِنَ الصُّوفِ.الغاشية آية 15 ، 16وَنَمارِقُ مَصْفوفَةٌ وَزَرابِيُّ مَبْثوثَةٌ (قرآن)."', ':لا جذر:لا مفرد');
