INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9955, 'زُرودٌ', 'زرود', 'جامد', '', 'زرود', 'زرد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9956, 'زِرارَةٌ', 'زرارة', 'جامد', 'زرر', 'زرارة', 'زررة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"زِرارَةٌ-زِرارَةٌ[ز ر ر]. : حِرْفَةُ صانِعِ الأَزْرارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9957, 'زُرْزُورٌ', 'زرزور', 'جامد', 'زرزر', 'زرزور', 'زرزر', '', '', '', 'مفرد', 'DnN', '', '', '"زَرازِيرُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"(حو). : طائِرٌ مِنْ فَصيلَةِ الزَّرْزُورِيَّاتِ، أَكْبَرُ مِنَ العُصْفورِ، وَهُوَ مِنَ الطُّيورِ الْمُهاجِرَةِ، لَوْنُهُ أَسْوَدُ، وَأَسْوَدُ مُنَقَّطٌ بِالأَبْيَضِ، يَتَلَوَّنُ مِنْقارُهُ بِالأَصْفَرِ في فَصْلِ الصَّيْفِ، يُقَلِّدُ أَصْواتَ الطُّيورِ، وَيُشَكِّلُ خَطَراً على الْمَزْروعاتِ إذَا مَا تَكاثَرَتْ أَعْدادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9958, 'زَرازِيرُ', 'زرازير', 'جامد', '', 'زرازير', 'زرزر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9959, 'زُرْزورِيَّاتٌ', 'زرزوريات', 'جامد', '', 'زرزوريات', 'زرزرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصيلَةُ طَيْرٍ، مِنْ رُتْبَةِ الجَواثِمِ، ذاتُ أَلْوانٍ مُخْتَلِفَةٍ، مِنْ أَشْهَرِ أَنْواعِها الزَّرْزورُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9960, 'زَريعَةٌ', 'زريعة', 'جامد', 'زرع', 'زريعة', 'زرعة', '', '', '', 'مفرد', 'DnN', '', '', '"زَرائِعُ"', '', '', '', '', '', '', '', '', '". 1.""أَلْقَى بِالزَّريعَةِ في الْحَقْلِ"" : البُذورِ. 2.""بَدَأَتِ الزَّريعَةُ في الظُّهورِ"" : كُلُّ الْمَزْروعَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9961, 'زَرائِعُ', 'زرائع', 'جامد', '', 'زراءع', 'زرع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9962, 'زِرِّيعٌ', 'زريع', 'جامد', 'زرع', 'زريع', 'زرع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زِرِّيعٌ-زِرِّيعٌ[ز ر ع]. ""نَما الزِّرِّيعُ بَعد الْحَصادِ"" : ما يَنْبُتُ في الأَرْضِ مِمَّا يَتَناثَرُ فيها مِنَ الْحَبِّ أَيّامَ الْحَصادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9963, 'مَزْرَعَةٌ', 'مزرعة', 'جامد', 'زرع', 'مزرعة', 'مزرعة', '', '', '', 'مفرد', 'DnN', '', '', '"مَزَارِعُ"', '', 'R', '', '', '', '', '', '', '".: مَوْضِعُ الزَّرْعِ وَتَرْبِيَةِ الْمَوَاشِي وَالدَّوَاجِنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9964, 'مَزَارِعُ', 'مزارع', 'جامد', '', 'مزارع', 'مزرع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9965, 'زَرَّافَةٌ', 'زرافة', 'جامد', 'زرف', 'زرافة', 'زرفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"زَرَّافَةٌ-زَرَّافَةٌ[ز ر ف]. : أُنْبوبَةٌ مِن الزُّجاجِ وَنَحْوِهِ، أَحَدُ طَرَفَيْها واسِعٌ وَالآخَرُ ضَيِّقٌ، في جَوْفِها عودٌ يَجْذِبُ السَّائِلَ ثُمَّ يَدْفَعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9966, 'زَرافَةٌ', 'زرافة', 'جامد', 'زرف', 'زرافة', 'زرفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""جاءوا زَرافاتٍ وَوُحْداناً"": جَماعاتٍ، أَي الْجَماعَة مِنَ النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9967, 'زِرْفينٌ', 'زرفين', 'جامد', 'زرفن', 'زرفين', 'زرفن', '', '', '', 'مفرد', 'DnN', '', '', '"زَرافِينُ"', '', 'R', '', '', '', '', '', '', '". : خُصْلَةُ الشَّعْرِ تَتَّخِذُ شَكْلَ دَوائِرَ حَلَزونِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9968, 'زَرافِينُ', 'زرافين', 'جامد', '', 'زرافين', 'زرفن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9969, 'زُرَّقٌ', 'زرق', 'جامد', '', 'زرق', 'زرق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"زُرَّقٌ-زُرَّقٌ(حو). : طائِرٌ مِنْ فَصيلَةِ العُقابِ، مِنْ رُتْبَةِ الصَّقْرِيَّاتِ، رَأْسُهُ أَسْوَدُ، وَذَنَبُهُ رَمادِيٌّ أَزْرَقُ، بَطْنُهُ أَبْيَضُ، عَيْناهُ قُرْمُزِيَّتانِ، لَهُ مِنْقارٌ حادٌّ مُتَقَوِّسٌ، وَهُوَ مُمْتَلِئُ الجِسْمِ، مَوْطِنُهُ الشَّرْقُ الأَوْسَطُ وَإِفْريقِيا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9970, 'زَرْنيخٌ', 'زرنيخ', 'جامد', '', 'زرنيخ', 'زرنخ', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": مَعْدِنٌ عَديمُ الرَّائِحَةِ واللوْنِ، تُعْرَفُ مُرَكَّباتُهُ مُنْذُ القِدَمِ، وَهِيَ سَامَّةٌ، يُسْتَعْمَلُ في الطِّبِّ لِمُعالَجَةِ الأَمْراضِ الجِلْدِيَّةِ ولِمُكَافَحَةِ الْحَشَرَاتِ والْحَيَوانَاتِ الْمُضِرَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9971, 'زَعازِعُ', 'زعازع', 'جامد', '', 'زعازع', 'زعزع', '', '', '', 'جمع تكسير', '', '', '', '"مفردزَعْزَع"', 'ممنوع من الصرف', 'R', '', 'N', 'O', 'O', 'O', '', '"جمع زَعْزَع. ن. زَعْزَعٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9972, 'زَعْزَع', 'زعزع', 'جامد', '', 'زعزع', 'زعزع', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9973, 'زَعْتَرٌ', 'زعتر', 'جامد', '', 'زعتر', 'زعتر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": صَعْتَرٌ. ن. سَعْتَرٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9974, 'زُعْرانٌ', 'زعران', 'جامد', 'زعر', 'زعران', 'زعرن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زُعْرانٌ-زُعْرانٌ[ز ع ر]. ""زُعْرانُ الْحَيِّ"" : أَحْداثُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9975, 'زَعاريرُ', 'زعارير', 'جامد', 'زعرر', 'زعارير', 'زعرر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '"زَعاريرُ-زَعاريرُ[ز ع ر ر]. ""زَعاريرُ الصُّوفِ"" : كُتَلٌ تَتَلَبَّدُ في أَطْرافِ الصُّوفِ مِنَ الزِّبْلِ وَغَيْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9976, 'زُعْرورٌ', 'زعرور', 'جامد', '', 'زعرور', 'زعرر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"زُعْرورٌ-زُعْرورٌ، ةٌ(نب). 1. : جِنْسُ شَجَرٍ مِنْ فَصيلَةِ الوَرْدِيَّاتِ، وَهُوَ مُثْمِرٌ، ثَمَرُهُ أَحْمَرُ أَوْ أَصْفَرُ، عِنَبِيُّ الشَّكْلِ، لَهُ نَوىً صَلْبٌ مُسْتَديرٌ بِجَوْفِهِ. 2.""رَجُلٌ زُعْرورٌ"" : رَجُلٌ سَيِّءُ الْخُلُقِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9977, 'زَعْزَعٌ', 'زعزع', 'جامد', 'زعزع', 'زعزع', 'زعزع', '', '', '', 'مفرد', 'DnN', '', '', '"زَعازِعُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""سَيْرٌ زَعْزَعٌ"" : سَيْرٌ شَديدٌ، مُتْعِبٌ. 2.""هَبَّتِ الزَّعازِعُ"" : الرِّياحُ الشَّديدَةُ. 3.""زَعازِعُ الدَّهْرِ"" : شَدائِدُهُ وَمَصائِبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9978, 'زَعازِعُ', 'زعازع', 'جامد', '', 'زعازع', 'زعزع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9979, 'زَعْفَرانٌ', 'زعفران', 'جامد', '', 'زعفران', 'زعفرن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"زَعافِرُ"', '', 'R', '', '', '', '', '', '', '"ج: زَعافِرُ. (نب). : نَباتٌ مِنْ فَصيلَةِ السَّوْسَنِيَّاتِ، بَصَلِيٌّ، أَنْواعُهُ مِنْها ما هُوَ بَرِّيٌّ، وَما هُوَ زِراعِيٌّ، مِنْها الصِّباغِيُّ والطِّبِّيُّ، زَهْرُهُ أَحْمَرُ مائِلٌ إلى الصُّفْرَةِ، يُسْتَخْدَمُ لِتَطْيِيبِ بَعْضِ أَنْواعِ الطَّعامِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9980, 'زَعافِرُ', 'زعافر', 'جامد', '', 'زعافر', 'زعفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9981, 'مَزَاعِمُ', 'مزاعم', 'جامد', 'زعم', 'مزاعم', 'مزعم', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَزَاعِمُ-مَزَاعِمُ [ز ع م]. ""حَسَبَ مَزَاعِمِهِ"" : حَسَبَ ادِّعَاءاتِهِ، وَهِيَ الأُمُورُ الَّتِي لاَ يُوثَقُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9982, 'مَزْعَمٌ', 'مزعم', 'جامد', 'زعم', 'مزعم', 'مزعم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَزْعَمٌ-مَزْعَمٌ [ز ع م]. ن. مَزَاعِمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9983, 'زَعانِفُ', 'زعانف', 'جامد', 'زعنف', 'زعانف', 'زعنف', '', '', '', 'مفرد', '', '', '', '"مفردزَعْنَفَة"', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '". ""قَطَعَ زَعانِفَ السَّمَكَةِ"" : أَجْنِحَتَها. ن. زَعْنَفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9984, 'زَعْنَفَةٌ', 'زعنفة', 'جامد', '', 'زعنفة', 'زعنفة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"زَعانِفُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: زَعانِفُ. 1. ""زِعْنِفَةُ السَّمَكَةِ"" : جَناحُها. 2.""شَيْءٌ زِعْنِفَةٌ أَوْ رَجُلٌ زِعْنِفَةٌ"" : الرَّدِيءُ مِنْ كُلِّ شَيْءٍ، كَما يُقْصَدُ بِهِ اللَّئيمُ الدَّنِيءُ.بِأَيِّ لَفْظٍ تَقولُ الشِّعْرَ زِعْنِفَة*تَجوزُ عِنْدَكَ لاَ عُرْبٌ وَلاَ عَجَمُ (المتنبي). 3.""زَعْنِفَةٌ مِنَ النَّاس"" : طائِفَةٌ مِنْهُمْ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9985, 'زَعانِفُ', 'زعانف', 'جامد', '', 'زعانف', 'زعنف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9986, 'زُغْلولٌ', 'زغلول', 'جامد', 'زغل', 'زغلول', 'زغلل', '', '', '', 'مفرد', 'DnN', '', '', '"زَغالِيلُ"', '', 'R', '', '', '', '', '', '', '". 1.""زُغْلولُ الْحَمامِ"" : فَرْخُهُ. 2.""مازالَ زُغْلولاً"" : طِفْلاً. ""كَيْفَ زُغْلولُكَ"" : أَيْ صَغيرُكَ. 3. : اِسْمُ عَلَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9987, 'زَغالِيلُ', 'زغاليل', 'جامد', '', 'زغاليل', 'زغلل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9988, 'مِزْفَتَةٌ', 'مزفتة', 'جامد', 'زفت', 'مزفتة', 'مزفتة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مِزْفَتَةٌ-مِزْفَتَةٌ [ز ف ت]. ن. مِحْدَلَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9989, 'زِفْتٌ', 'زفت', 'جامد', '', 'زفت', 'زفت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": مادَّةٌ سَوْداءُ، لَزِجَةٌ، تَتَخَلَّفُ مِنَ تَقْطيرِ الْمَوادِّ القَطْرانِيَّةِ، وَتُخْلَطُ بِحِجارَةٍ صَغيرَةٍ تُسْتَخْدَمُ لِتَبْليطِ الشَّوارِعِ والطُّرُقِ، وَهِيَ ما يُعْرَفُ بِالقارِ والقيرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9990, 'زافِرَةٌ', 'زافرة', 'جامد', 'زفر', 'زافرة', 'زفرة', '', '', '', 'مفرد', 'DnN', '', '', '"زَوافِرُ"', '', '', '', '', '', '', '', '', '". 1.""زافِرَةُ البِناءِ"" : رُكْنُ البِناءِ وَما يُدْعَمُ بِهِ. 2.""زَوافِرُ الْمَجْدِ"" : أَعْمِدَتُهُ وَقَوائِمُهُ الْمُدَعِّمَةُ لَهُ. 3.""رَجُلٌ زافِرَةٌ"" : دَاهِيَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9991, 'زَوافِرُ', 'زوافر', 'جامد', '', 'زوافر', 'زفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9992, 'زَفْرَةٌ', 'زفرة', 'جامد', 'زفر', 'زفرة', 'زفرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":زُفَرٌ"', '', 'R', '', '', '', '', '', '', '". 1.""زَفَرَ زَفْرَةً"": تَنَفَّسَ تَنَفُّساً حارّاً فيهِ آهَةٌ وَحَرارَةٌ. ""ثُمَّ سَمِعْتُ صَوْتاً رَقيقاً تُقاطِعُهُ زَفَراتُ أَنْفاسٍ مُلْتَهِبَةٍ"". (جبران خ. جبران). 2.""زَفْرَةُ الشَّيْءِ"" : وَسَطُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9993, 'زُفَرٌ', 'زفر', 'جامد', '', 'زفر', 'زفر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9994, 'زُفْرَةٌ', 'زفرة', 'جامد', 'زفر', 'زفرة', 'زفرة', '', '', '', 'مفرد', 'DnN', '', '', '"زُفَرٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""زُفْرَةُ الْمَيْدَانِ"" : وَسَطُهُ. 2.""زُفْرَةُ الفَرَسِ"": جَوْفُهُ. ""فَرَسٌ عَظِيمُ الزُّفْرَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9995, 'زُفَرٌ', 'زفر', 'جامد', '', 'زفر', 'زفر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9996, 'زُفَرٌ', 'زفر', 'جامد', 'زفر', 'زفر', 'زفر', '', '', '', 'مفرد', '', '', '', '"""رَجُلٌزُفَرٌ"""', '', 'R', '', '', '', '', '', '', '"زُفَرٌ-زُفَرٌ[ز ف ر]. 1.""رَجُلٌ زُفَرٌ"" : شُجاعٌ، أَو سَيِّدٌ كَبيرٌ، أَو جَوادٌ كَريمٌ. 2. : البَحْرُ. 3. : نَهْرٌ كَثيرُ المِياهِ. 4.""قَدَّمَ زُفَراً"" : عَطِيَّةً كَثيرَةً. 5.""زُفَرُ الجَيْشِ"" :كَتيبَةٌ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9997, 'زَوافِرُ', 'زوافر', 'جامد', 'زفر', 'زوافر', 'زفر', '', '', '', 'مفرد', '', '', '', '"مفردزَافِرَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1. : الْخادِماتُ والإِماءُ اللَّواتِي يَحْمِلْنَ القِرَبَ. 2.""زَوافِرُ الكَرْمِ"" : خَشَباتٌ تُقامُ لِتُحْمَلَ عَلَيْها أَغْصانُ الكَرْمِ. 3.""فَرَسٌ شَديدُ الزَّوافِرِ"" : شَديدُ الضُّلوعِ. 4.""زَوافِرُ الْمَجْدِ"" : أَعْمِدَتُهُ، أَسْبابُهُ الْمُقَوِّيَةُ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9998, 'زَفْزافَةٌ', 'زفزافة', 'جامد', 'زفزف', 'زفزافة', 'زفزفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"زَفْزافَةٌ-زَفْزافَةٌ[ز ف ز ف]. 1.: رِيحٌ شَديدَةُ الْهُبوبِ في دَوامٍ. 2. : دَرَّاجَةٌ نارِيَّةٌ مُجَهَّزَةٌ بِمُحَرِّكٍ، طَفْطافَة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(9999, 'زَفوفٌ', 'زفوف', 'جامد', 'زفف', 'زفوف', 'زفف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زَفوفٌ-زَفوفٌ[ز ف ف]. 1. (حو). : نَعامَةٌ. 2.""ناقَةٌ زَفوفٌ"" : سَريعَةٌ، حَسَنَةُ الْمَشْيِ. 3.""قَوْسٌ زَفوفٌ"" : مُصَوِّتَةٌ، مُرِنَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10000, 'أزِقَّةٌ', 'أزقة', 'جامد', 'زقق', 'ءزقة', 'زقة', '', '', '', 'مفرد', 'DnN', '', '', '"زُقَاقٌ"', '', 'R', '', '', '', '', '', '', '". 1.""مَرَّ مِنْ أَزِقَّةٍ ضَيِّقَةٍ"" : زَنْقَاتٌ، دُرُوبٌ ضَيِّقَةٌ. 2.""مِنْ أَبْنَاءِ الأَزِقَّةِ"" : الْمُشَرَّدُونَ الَّذِينَ لاَ مَأْوَى لَهُمْ، دُونَ مَوْرِدٍ وَلاَ عَمَلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10001, 'زُقَاقٌ', 'زقاق', 'جامد', '', 'زقاق', 'زقق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10002, 'زُقاقٌ', 'زقاق', 'جامد', 'زقق', 'زقاق', 'زقق', '', '', '', 'مفرد', 'DnN', '', '', '"أَزِقَّةٌ"', '', 'R', '', '', '', '', '', '', '". ""اِنْتَقَلَ مِنْ زُقاقٍ إلى زُقاقٍ آخَرَ"" : الزَّنْقَةُ الضَّيِّقَةُ، الدَّرْبُ. ""تَفَقَّدَ أَزِقَّةَ الْمَدينَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10003, 'أَزِقَّةٌ', 'أزقة', 'جامد', '', 'ءزقة', 'زقة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10004, 'زِقٌّ', 'زق', 'جامد', 'زقق', 'زق', 'زق', '', '', '', 'مفرد', 'DnN', '', '', '"أَزْقاقٌ:زِقاقٌ"', '', 'R', '', '', '', '', '', '', '". 1.""سَكَبَ الْماءَ مِنَ الزِّقِّ"" : وِعاءٌ مِنْ جِلْدٍ يُمْلأُ بِالْماءِ أَوِ اللَّبَنِ أَوِ الْخَمْرِ وَنَحْوِهَا. 2.""زِقُّ الْحَدَّادِ"" : كيرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10005, 'أَزْقاقٌ', 'أزقاق', 'جامد', '', 'ءزقاق', 'زقق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10006, 'زِقاقٌ', 'زقاق', 'جامد', '', 'زقاق', 'زقق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10007, 'زَقَّومٌ', 'زقوم', 'جامد', '', 'زقوم', 'زقم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": شَجَرَةٌ مُرَّةُ الطَّعْمِ، كَريهَةُ الرَّائِحَةِ، تُعْرَفُ بِشُجَرَةِ جَهَنَّمَ لأَنَّ ثِمارَها طَعامُ أَهْلِ جَهَنَّمَ.الدخان آية 43 إِنَّ شَجَرَةَ الزَّقُّومِ طَعامُ الأَثيمِ . (قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10008, 'زُكٌّ', 'زك', 'جامد', 'زكك', 'زك', 'زك', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"زُكٌّ-زُكٌّ[ز ك ك]. : فَرْخُ الْحَمامِ البَرِّيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10009, 'زَلابِيَةٌ', 'زلابية', 'جامد', '', 'زلابية', 'زلبة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '": عَجينٌ على شَكْلِ حَلَقاتٍ مُتَّصِلَةٍ، يُقْلَى في الزَّيْتِ وَيُعْقَدُ بِالْمُرَبَّى أَوِ بِالسُّكَّرِ أَوِ العَسَلِ، وَهِيَ ما يُعْرَفُ بِالْمَغْرِبِ بِالشّبَّاكِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10010, 'زَلاَّجَةٌ', 'زلاجة', 'جامد', 'زلج', 'زلاجة', 'زلجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"زَلاَّجَةٌ-زَلاَّجَةٌ[ز ل ج]. 1. : أَداةٌ مِنَ حَديدٍ يُتَزَلَّجُ بِها على الْجَليدِ أَوْ على طَريقٍ مُزَفَّتٍ أَمْلَسَ. 2. : قِطْعَةٌ مِنَ خَشَبٍ، مُسَطَّحَةٌ وَمُسْتَطيلَةٌ يُتَزَلَّجُ بِها على الثَّلْجِ وَتَكونُ مُثْبَتَةً في القَدَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10011, 'زِلاجٌ', 'زلاج', 'جامد', 'زلج', 'زلاج', 'زلج', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زِلاجٌ-زِلاجٌ[ز ل ج]. ""أَحْكَمَ إِغْلاقَ البابِ بِالزِّلاجِ"" : حَديدَةٌ تُسْتَعْمَلُ لإِغْلاقِ البابِ، الْمِزْلاجُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10012, 'زَلِّيجَةٌ', 'زليجة', 'جامد', 'زلج', 'زليجة', 'زلجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":زَلِّيجٌ"', '', 'R', '', '', '', '', '', '', '". : قِطْعَةٌ صَغيرَةٌ مِنَ الصَّخْرِالأَمْلَسِ أَوِ الرُّخامِ وَنَحْوِهِ، يَتِمُّ صَقْلُهَا وتَلْوِينُهَا صِنَاعِيّاً، وَهِيَ ذاتُ أَشْكالٍ بِدَاخِلِها مُـرَبَّـعــاتٌ أَوْ مُسْتَطِيلاتٌ أَو دَوائِرُ مُلَوَّنَةٌ، يُضَمُّ بَعْضُها إلى بَعْضٍ، فُسَيْفِسَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10013, 'زَلِّيجٌ', 'زليج', 'جامد', '', 'زليج', 'زلج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10014, 'مِزْلاَجَةٌ', 'مزلاجة', 'جامد', 'زلج', 'مزلاجة', 'مزلجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مِزْلاَجَةٌ-مِزْلاَجَةٌ [ز ل ج].: خَشَبَةٌ طَوِيلَةٌ مُسَطَّحَةٌ، عَوَّامَةٌ يَشُدُّهَا شِرَاعٌ مُثْبَتٌ بِوَاسِطَةِ سَارِيَةٍ يُتَزَلَّجُ بِهَا عَلَى أَمْوَاجِ البَحْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10015, 'مِزْلاَجٌ', 'مزلاج', 'جامد', 'زلج', 'مزلاج', 'مزلج', '', '', '', 'مفرد', 'DnN', '', '', '"مَزَالِيجُ"', '', 'R', '', '', '', '', '', '', '". ""مِزْلاَجُ البَابِ"" : قِطْعَةٌ مِنَ الْحَدِيدِ أَوِ الخَشَبِ تُسْتَعْمَلُ لِإِغْلاَقِ البَابِ بِاليَدِ. ""كُنَّا نُغْلِقُ البَابَ وَنَضَعُ خَلْفَهُ المِزْلاَجَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10016, 'مَزَالِيجُ', 'مزاليج', 'جامد', '', 'مزاليج', 'مزلج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10017, 'مِزْلَجَةٌ', 'مزلجة', 'جامد', 'زلج', 'مزلجة', 'مزلجة', '', '', '', 'مفرد', 'DnN', '', '', '"مَزَالِجُ"', '', 'R', '', '', '', '', '', '', '": نَعْلٌ مَعْدِنِيَّةٌ ذَاتُ شَفَارٍ تُثْبَتُ فِيالحِذَاءِ أَوْ هِيَ جُزْءٌ مِنَ الحِذَاءِ، تُسْتَعْمَلُ لِلتَّزَلُّجِ عَلَى الجَلِيدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10018, 'مَزَالِجُ', 'مزالج', 'جامد', '', 'مزالج', 'مزلج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10019, 'مَزْلَجٌ', 'مزلج', 'جامد', 'زلج', 'مزلج', 'مزلج', '', '', '', 'مفرد', 'DnN', '', '', '"مَزَالِجُ"', '', 'R', '', '', '', '', '', '', '". 1.""يَسْتَعْمِلُ أَهْلُ الْمَنَاطِقِ القُطْبِيَّةِ المِزْلَجَ"" : مَرْكَبَة لاَ دَوَالِيبَ لَهَا، تُزْلَجُ عَلَى الجَلِيدِ. 2.:مَكَانٌ مُعَدٌّ لِلتَّزَحْلُقِ عَلَى الثَّلْجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10020, 'مَزَالِجُ', 'مزالج', 'جامد', '', 'مزالج', 'مزلج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10021, 'زَلَعَةٌ', 'زلعة', 'جامد', 'زلع', 'زلعة', 'زلعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"زَلَعَةٌ-زَلَعَةٌ[ز ل ع]. : جِراحَةٌ فاسِدَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10022, 'زَلَفَةٌ', 'زلفة', 'جامد', 'زلف', 'زلفة', 'زلفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":زَلَفٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِعْتَلَى زَلَفَةً"" : صَخْرَةً مَلْسَاءَ. 2.""زَلَفَةُ الشُّرْبَةِ"" : الصَّحْفَةُ، إِناءُ الطَّعامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10023, 'زَلَفٌ', 'زلف', 'جامد', '', 'زلف', 'زلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10024, 'زُلْفَةٌ', 'زلفة', 'جامد', 'زلف', 'زلفة', 'زلفة', '', '', '', 'مفرد', 'DnN', '', '', '"زُلَفٌ"', '', 'R', '', '', '', '', '', '', '". 1.""لَهُ عِنْدَهُ زُلْفَةٌ"" : مَنْزِلَةٌ، دَرَجَةٌ، مَكَانَةٌ. 2.""سَهِرَ زُلَفَ اللَّيْلِ"": أَجْزَاءً مِنْهُ. هود آية 114وَأَقِمِ الصَّلاةَ طَرَفَيِ النَّهارِ وَزُلَفاً مِنَ اللَّيْلِ (قرآن). 3.""زُلْفَةُ شُرْبَةٍ"" : صَحْفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10025, 'زُلَفٌ', 'زلف', 'جامد', '', 'زلف', 'زلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10026, 'زُلْفَى', 'زلفى', 'جامد', 'زلف', 'زلفى', 'زلف', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"زُلْفَى-زُلْفَى[ز ل ف]. ""لَهُ زُلْفَى بَيْنَ قَوْمِهِ"" : مَنْزِلَةٌ، دَرَجَةٌ، مَكانَةٌ. سبأ آية 37 وَما أَمْوالُكُمْ وَلا أَوْلادُكُمْ بِالَّتِي تُقَرِّبُكُمْ عِنْدَنا زُلْفَى (قرآن)ص آية 40 وَإِنَّ لَهُ عِنْدَنا لَزُلْفَى وَحُسْنَ مَآبٍ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10027, 'زُلَيْفَةٌ', 'زليفة', 'جامد', 'زلف', 'زليفة', 'زلفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '". : تَصْغيرُ زُلَفَة. ""زُلَيْفَةُ الشُّرْبَةِ"" : صَحْفَةٌ صَغيرَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10028, 'زَلاَّقَةٌ', 'زلاقة', 'جامد', 'زلق', 'زلاقة', 'زلقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"زَلاَّقَةٌ-زَلاَّقَةٌ[ز ل ق]. 1. : الْمَوْضِعُ الَّذِي لا تَثْبُتُ عَلَيْهِ القَدَمُ. 2. : أَداةٌ ثابِتَةٌ مِنْ لُعَبِ الأَطْفالِ يَجْلِسُ عَلَيْها الطِّفْلُ فَيَنْزَلِقُ مِنْ أَعْلَى إلى أَسْفَلَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10029, 'زَلَقَةٌ', 'زلقة', 'جامد', 'زلق', 'زلقة', 'زلقة', '', '', '', 'مفرد', 'DnN', '', '', '"زَلَقٌ"', '', 'R', '', '', '', '', '', '', '". 1. : صَخْرَةٌ مَلْساءُ. 2. : مِرْآةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10030, 'زَلَقٌ', 'زلق', 'جامد', '', 'زلق', 'زلق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10031, 'مَزْلَقَةٌ', 'مزلقة', 'جامد', 'زلق', 'مزلقة', 'مزلقة', '', '', '', 'مفرد', 'DnN', '', '', '"مَزَالِقُ"', '', 'R', '', '', '', '', '', '', '". مَدْرَجٌ مُرْتَفِعٌ، زَلِقٌ، يَتِمُّ بِنَاؤُهُ أَوْ تَرْكِيبُهُ عَلَى شَكْلِ هَضْبَةٍ مُنْحَدِرَةٍ مِنْ أَعْلَى إِلَى أَسْفَلَ، يَنْزَلِقُ عَلَيْهَا الأَطْفَالُ فِي الْحَدَائِقِ العَامَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10032, 'مَزَالِقُ', 'مزالق', 'جامد', '', 'مزالق', 'مزلق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10033, 'مِزْلَقٌ', 'مزلق', 'جامد', 'زلق', 'مزلق', 'مزلق', '', '', '', 'مفرد', 'DnN', '', '', '"مَزَالِقُ"', '', 'R', '', '', '', '', '', '', '".ن. الزَّلاَّقَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10034, 'مَزَالِقُ', 'مزالق', 'جامد', '', 'مزالق', 'مزلق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10035, 'زُلالٌ', 'زلال', 'جامد', 'زلل', 'زلال', 'زلل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زُلالٌ-زُلالٌ[ز ل ل]. 1.""زُلالُ البَيْضِ"" : آحُهُ، بَياضُهُ الْمُلْتَفُّ بِالْمُحِّ. 2.""ماءٌ زُلالٌ"" : الماءُ العَذْبُ الصَّافِي. ""يَشْرَبُ ماءً زُلاَلاً"". 3.""الزُّلالُ كِيمِيائِيّاً"" : مادَّةٌ بُروتينِيَّةٌ، تَحْتَوِي على نِسْبَةٍ مُرْتَفِعَةٍ مِنَ الكِبْريتِ قابِلَةٌ للذَّوَبانِ في الماءِ. 4.""الزُّلالُ في عِلْمِ الأَمْراضِ"" : مادَّةٌ برُوتِينِيَّةٌ تَنْتَشِرُ في أَنْسِجَةِ الْحَيَوانِ والنَّباتِ وَسَوائِلِها، وَمِنْها آحُ البَيْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10036, 'زُلالِيَّاتٌ', 'زلاليات', 'جامد', 'زلل', 'زلاليات', 'زللت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"زُلالِيَّاتٌ-زُلالِيَّاتٌ[ز ل ل]. : بْروتِيناتٌ تَحْتَوِي على مادَّةِ الزُّلالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10037, 'زَلَمَةٌ', 'زلمة', 'جامد', 'زلم', 'زلمة', 'زلمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"زَلَمَةٌ-زَلَمَةٌ[ز ل م]. 1. : قِطْعَةٌ مِنَ اللَّحْمِ تَتَدَلَّى مِنْ عُنُقِ الْمِعْزَى. 2. : هَيْئَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10038, 'زُمَّجٌ', 'زمج', 'جامد', '', 'زمج', 'زمج', '', '', '', 'جمع تكسير', 'DnN', '', '', '"زَمامِجُ"', '', 'R', '', '', '', '', '', '', '"ج: زَمامِجُ. (حو). : طائِرٌ مائِيٌّ مِنْ فَصيلَةِ النَّوْرَسِيَّاتِ، مِنْ رُتْبَةِ كَفِّيَّاتِ القَدَمِ، في حَجْمِ الْحَمامِ، مِنْقارُهُ مُقَوَّسٌ يَصْطادُ بِهِ، يَميلُ لَوْنُهُ إلَى خُضْـرَةٍ وَصُفْرَةٍ، يَعيشُ على السَّمَكِ، وَيُسَمَّى أَيْضاً النَّوْرَسَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10039, 'زَمامِجُ', 'زمامج', 'جامد', '', 'زمامج', 'زممج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10040, 'زِمِجَّةٌ', 'زمجة', 'جامد', '', 'زمجة', 'زمجة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"""زِمِجَّةُ النَّعامَةِ"" : مِنْقارُها."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10041, 'زَمْخَرٌ', 'زمخر', 'جامد', 'زمخ', 'زمخر', 'زمخر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زَمْخَرٌ-زَمْخَرٌ[ز م خ]. 1. : الأَجْوَفُ كَالقَصَبِ، أَو العَظْمُ الَّذِي لا مُخَّ فيهِ. 2. : قَصَبُ المِزْمارِ. 3. : شَجَرٌ كَثيرٌ مُلْتَفٌّ. 4.""رَجُلٌ زَمْخَرٌ"" : عالِي الهِمَّةِ والشَّأْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10042, 'زَمَّارَةٌ', 'زمارة', 'جامد', 'زمر', 'زمارة', 'زمرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات:زَمَاميرُ"', '', '', '', '', '', '', '', '', '". ""أَخَذَ زَمَّارَتَهُ وَاسْتَوَى ثُمَّ بَدَأَ يَعْزِفُ لَحْناً جَميلاً"" : آلَةٌ موسِيقِيَّــةٌ هَوائِيَّةٌ، تُصْنَعُ مِنَ القَصَبِ أَوْ ما شابَهَ ذَلِكَ، وَهِيَ مَفْتوحَةٌ مِنَ الجِهَتَيْنِ، وَبِها ثُقوبٌ هِيَ الَّتِي يُحَرِّكُ الزَّمَّارُ أَصابِعَهُ فَوْقَها حَسَبَ إِيقاعِ اللَّحْنِ. ""اِخْتَلَطَتِ الأَصْواتُ مِن نِداءِ الباعَةِ إلَى نَفْخِ الزَّمَّاراتِ"". (ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10043, 'زَمَاميرُ', 'زمامير', 'جامد', '', 'زمامير', 'زممر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10044, 'زِمارَةٌ', 'زمارة', 'جامد', 'زمر', 'زمارة', 'زمرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"زِمارَةٌ-زِمارَةٌ[ز م ر]. : فَنُّ اللَّعِبِ بِالمِزْمارِ، فَنُّ الزَّمَّارِ وَحِرْفَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10045, 'زُمْرَةٌ', 'زمرة', 'جامد', 'زمر', 'زمرة', 'زمرة', '', '', '', 'مفرد', 'DnN', '', '', '"زُمَرٌ"', '', 'R', '', '', '', '', '', '', '". 1.""خَرَجَ مَعَ زُمْرَةٍ مِنْ أَصْدِقائِهِ"" : جَماعَةٌ، فِرْقَةٌ. 2.""زُمْرَةٌ جُرْثومِيَّةٌ"" : مَجْموعَةٌ مِنَ الجَراثيمِ. 3.""دَمُهُ مِنْ زُمْرَةِ (ب)"" : أَيْ مِنْ فَصيلَةِ (ب). ""الزُّمْرَةُ الدَّمَوِيَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10046, 'زُمَرٌ', 'زمر', 'جامد', '', 'زمر', 'زمر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10047, 'زُمَرٌ', 'زمر', 'جامد', 'زمر', 'زمر', 'زمر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"زُمَرٌ-زُمَرٌ[ز م ر]. ""الزُّمَرُ"" : سُورَةٌ مِنْ سُوَرِ القُرْآنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10048, 'مَزَامِيرُ', 'مزامير', 'جامد', 'زمر', 'مزامير', 'مزمر', '', '', '', 'مفرد', '', '', '', '"مفردمَزْمُور"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '". ""مَزَامِيرُ دَاوُودَ"" : أَنَاشِيدُ، سِفْرٌ مِنْ أَسْفَارِ التَّوْرَاةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10049, 'مَزْمُورٌ', 'مزمور', 'جامد', 'زمر', 'مزمور', 'مزمر', '', '', '', 'مفرد', 'DnN', '', '', '"مَزَامِيرُ"', '', 'R', '', '', '', '', '', '', '". ن. مَزَامِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10050, 'مَزَامِيرُ', 'مزامير', 'جامد', '', 'مزامير', 'مزمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10051, 'زُمُرُّدٌ', 'زمرد', 'جامد', '', 'زمرد', 'زمرد', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"""وَضَعَتْ عِقْدَ زُمُرُّدٍ في عُنُقِها"" : حَجَرٌ كَريمٌ يَمْتازُ بِشَفافِيَّتِهِ وَشِدَّةِ خُضْرَتِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10052, 'زَمالَةٌ', 'زمالة', 'جامد', 'زمل', 'زمالة', 'زملة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"زَمالَةٌ-زَمالَةٌ[ز م ل]. 1.""بَيْنَهُما زَمالَةٌ"" : عَلاقَةُ رُفْقَةٍ وَصَداقَةٍ تَكَوَّنَتْ في مَجالٍ مِنَ الْمَجالاتِ. 2.""تَطْبَعُ روحُ الزَّمالَةِ عَلاقَتَهُمَا"" : روحُ التَّضامُنِ والتَّعاوُنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10053, 'زُمْلَةٌ', 'زملة', 'جامد', 'زمل', 'زملة', 'زملة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"زُمْلَةٌ-زُمْلَةٌ[ز م ل]. 1.""جاءَ في زُمْلَتِهِمْ"" : في زُمْرَتِهِمْ، في رُفْقَتِهِمْ. 2.""هُوَ مِنْ زُمْلَةِ كَذا"" : مِنْ جَماعَةِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10054, 'زِمْلٌ', 'زمل', 'جامد', 'زمل', 'زمل', 'زمل', '', '', '', 'مفرد', 'DnN', '', '', '"أَزْمالٌ"', '', 'R', '', '', '', '', '', '', '". 1.""كانَ زِمْلَهُ خِلالَ رِحْلَتِهِ على الدَّابَّةِ"" : كَانَ يَرْكَبُ خَلْفَ رَاكِبِ الدَّابَّةِ. 2.""وَلَدٌ زِمْلٌ"": جَبانٌ، ضَعيفٌ، أَو كَسْلانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10055, 'أَزْمالٌ', 'أزمال', 'جامد', '', 'ءزمال', 'زمل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10056, 'زِمامٌ', 'زمام', 'جامد', 'زمم', 'زمام', 'زمم', '', '', '', 'مفرد', 'DnN', '', '', '"أَزِمَّةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هُوَ زِمامُ قَوْمِهِ"" : زَعيمُهُمْ، مُقَدِّمُهُمْ وَصاحِبُ أَمْرِهِمْ. 2.""زِمامُ الحُكْمِ"" : مَقالِيدُ السُّلْطَةِ والْحُكْمِ. ""أَمْسَكَ بِزِمامِ الأَمْرِ. 3.""أَلْقَوْا في يَدِهِ زِمامَ أُمورِهِمْ"" : تَرَكُوا لَهُ أَنْ يَحْكُمَ بِما يَشاءُ وَيرَى. 4.""وَضَعَ زِماماً عَلَى حَقيبَتِهِ"" : رِباطاً، أي ما يُشَدُّ وَيُرْبَطُ وَيُزَمُّ بِهِ. 5.""زِمامُ الحِذاءِ"" : سَيْرُهُ، أَي الْخُيوطُ الَّتِي تَشُدُّ طَرَفَيِ الحِذاءِ. 6.""زِمامُ السَّيَّارَةِ"" : مِقْوَدُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10057, 'أَزِمَّةٌ', 'أزمة', 'جامد', '', 'ءزمة', 'زمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10058, 'أَزْمِنَةٌ', 'أزمنة', 'جامد', 'زمن', 'ءزمنة', 'زمنة', '', '', '', 'مفرد', '', '', '', '"مفردزَمَن"', '', '', '', '', '', '', '', '', '". 1.""يُسَافِرُ فِي كُلِّ أَزْمِنَةِ السَّنَةِ"" : فِي كُلِّ فُصُولِهَا : الخَرِيفُ، الشِّتَاءُ، الرَّبِيعُ، الصَّيْفُ. 2.""تَغَيَّرَتْ أَحْوَالُ النَّاسِ فِي الأزْمِنَةِ الحَدِيثَةِ عَكْسَ مَا كَانَ عَلَيْهِ الأمْرُ في الأزْمِنَةِ الْمَاضِيَةِ"" : العُصُورُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10059, 'زَمانٌ', 'زمان', 'جامد', 'زمن', 'زمان', 'زمن', '', '', '', 'مفرد', 'DnN', '', '', '"أَزْمِنَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""آثَارٌ مِنْ زَمَانٍ قَدِيمٍ"": عَصْرٍ قَدِيمٍ. ""كانَ يا ما كانَ، كانَ في قَدِيمِ الزَّمانِ"". 2.""مِنْ زَمانٍ لَمْ أَزُرْهُ"": مِنْ مُدَّةٍ طَويلَةٍ. 3.""اِنْتَظَرْتُهُ زَماناً"": مُدَّةً مِنَ الوَقْتِ. 4.""يَشْهَدُ أَهْلُ زَمانِهِ بِعِلْمهِ وَفَضْلِهِ"": مُعاصِروهُ، أَهْلُ عَصْرِهِ، 5.""عَرَفَ زَمانُهُ وَيْلاتِ الحَرْبِ"": عَرَفَ عَهْدُهُ، عَصْرُهُ، أَيِ الفَتْرَةُ الَّتِي عاشَ فيها. 6.""ظَرْفُ زَمانٍ"" (لغ) : اِسْمٌ يَدُلُّ على الزَّمانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10060, 'أَزْمِنَةٌ', 'أزمنة', 'جامد', '', 'ءزمنة', 'زمنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10061, 'زَمَنٌ', 'زمن', 'جامد', '', 'زمن', 'زمن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَزْمانٌ:أَزْمُنٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَزْمانٌ، أَزْمُنٌ. ن. زَمانٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10062, 'أَزْمانٌ', 'أزمان', 'جامد', '', 'ءزمان', 'زمن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10063, 'أَزْمُنٌ', 'أزمن', 'جامد', '', 'ءزمن', 'زمن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10064, 'زَمْهَريرٌ', 'زمهرير', 'جامد', 'زمهر', 'زمهرير', 'زمهرر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"زَمْهَريرٌ-زَمْهَريرٌ[ز م هـ ر]. ""يَشْتَدُّ الزَّمْهَريرُ في لَيالِي الشِّتاءِ"" : شِدَّةُ البَرْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10065, 'زِنْبارٌ', 'زنبار', 'جامد', '', 'زنبار', 'زنبر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"زَنابيرُ"', '', 'R', '', '', '', '', '', '', '"ج: زَنابيرُ. : حَشَرَةٌ مِنْ فَصيلَةِ الزُّنْبورِيَّاتِ، لَسْعُها أَليمٌ، أَنْواعُها عَديدَةٌ، تُشْبِهُ الذّبابَ، وَهِيَ غَيْرُ الزُّنْبُورِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10066, 'زَنابيرُ', 'زنابير', 'جامد', '', 'زنابير', 'زنبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10067, 'زَنْبَقٌ', 'زنبق', 'جامد', '', 'زنبق', 'زنبق', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"زَنابِقُ"', '', 'R', '', '', '', '', '', '', '"ج: زَنابِقُ (نب). : نَباتٌ مِنْ فَصيلَةِ الزَّنْبَقِيَّاتِ، لَهُ زَهْرٌ جَميلٌ زَكِيُّ الرَّائِحَةِ، أَوْراقُهُ مُسْتَطيلَةٌ وَرُمْحِيَّةٌ. مِنْهُ أَنْواعٌ عَدِيدَةٌ مُخْتَلِفَةُ الأَلْوانِ، أَشْهَرُها اللَّوْنُ الأَبْيَضُ، وَيَرْمُزُ بِهِ إلى الطَّهارَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10068, 'زَنابِقُ', 'زنابق', 'جامد', '', 'زنابق', 'زنبق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10069, 'زَنْبَقِيَّاتٌ', 'زنبقيات', 'جامد', '', 'زنبقيات', 'زنبقت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"زَنْبَقِيَّاتٌ-زَنْبَقِيَّاتٌ(نب). : فَصيلَةٌ نَباتِيَّةٌ مِن ذَواتِ الفِلْقَةِ الواحِدَةِ، أَجْناسُها عَديدَةٌ، مِنْها الزِّنْبَقُ والبَصَلُ والثُّومُ والْهَلْيونُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10070, 'زُنْبورٌ', 'زنبور', 'جامد', '', 'زنبور', 'زنبر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"زَنابيرُ"', '', 'R', '', '', '', '', '', '', '"ج: زَنابيرُ. (حو). : حَشَرَةٌ مِنْ فَصيلَةِ الزُّنْبورِيَّاتِ، مِنْ رُتْبَةِ غِشائِيَّاتِ الأَجْنِحَةِ، لَها جِسْمٌ مُسْتَدَقٌّ بَيْنَ الصَّدْرِ والبَطْـنِ، تُشْبِـهُ النَّحْلَ وَلا تُنْتِجُ عَسَلاً، وَتُلْحِقُ بِهِ أَضْراراً، لَسْعَتُها مُؤْلِمَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10071, 'زَنابيرُ', 'زنابير', 'جامد', '', 'زنابير', 'زنبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10072, 'زُنْبورِيَّاتٌ', 'زنبوريات', 'جامد', '', 'زنبوريات', 'زنبرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصيلَةُ حَشَراتٍ، مِنْ رُتْبَةِ غِشائِيَّاتِ الأَجْنِحَةِ، أَنْواعُها عَديدَةٌ، وَكُلُّها شَديدَةُ اللَّسْعِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10073, 'زَنْبيلٌ', 'زنبيل', 'جامد', '', 'زنبيل', 'زنبل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"زَنابيلُ"', '', 'R', '', '', '', '', '', '', '"ج: زَنابيلُ. ""مَلأَتِ الزَّنْبيلَ بِالْخُضَرِ"" : القُفَّةُ الكَبيرَةُ، الجِرابُ، الوِعاءُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10074, 'زَنابيلُ', 'زنابيل', 'جامد', '', 'زنابيل', 'زنبل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10075, 'زِنْجٌ', 'زنج', 'جامد', '', 'زنج', 'زنج', '', '', '', 'جمع تكسير', 'DnN', '', '', '"زُنوجٌ"', '', 'Rp', '', '', '', '', '', '', '"ج: زُنوجٌ. 1. : اِسْمٌ كانَ يُطْلَقُ على القَبائِلِ الإِفْريقِيَّةِ، وَمِنْهُ كانَ اسْمُ جَزيرَةِ زَنْجِبار. 2.""ثَوْرَةُ الزَّنْجِ بِالعِراقِ"" : اِسْمٌ أَطْلَقَهُ العَرَبُ على العَناصِرِ السُّودِ الآتِيَةِ مِنَ الأَقْطارِ الإِفْريقِيَّةِ، كَما تُطْلَقُ على قَوْمٍ مِنَ السُّودانِ. 3. :‎‎ سُكَّانُ إِفْريقِيا السُّودُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10076, 'زُنوجٌ', 'زنوج', 'جامد', '', 'زنوج', 'زنج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10077, 'زِنْجارٌ', 'زنجار', 'جامد', '', 'زنجار', 'زنجر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"""كَسا الزِّنْجارُ الآنِيَةَ النُّحاسِيَّةَ"" : الصَّدَأُ الَّذِي يَعْلُو كُلَّ إِناءٍ مِنْ مَعْدِنِ النُّحاسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10078, 'زَنْجَبيلٌ', 'زنجبيل', 'جامد', '', 'زنجبيل', 'زنجبل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زَنْجَبيلٌ-زَنْجَبيلٌ(نب). : نَباتٌ مِنْ فَصيلَةِ الزَّنْجَبيلِيَّاتِ، هِنْدِيُّ الأَصْلِ، يُعَمِّرُ طَويلاً، لَهُ عُروقٌ غِلاَظٌ تَتَوَلَّدُ في الأَرْضِ، حِرِّيفَةُ الطَّعْمِ، أَنْواعُهُ عَديدَةٌ، مِنْها ما هُوَ بَرِّيٌّ وَما هُوَ زِراعِيٌّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10079, 'زَنْجَبيلِيَّاتٌ', 'زنجبيليات', 'جامد', '', 'زنجبيليات', 'زنجبلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصيلَةٌ نَباتِيَّةٌ مِنْ ذَواتِ الفِلْقَةِ الواحِدَةِ، أَنْواعُها عَديدَةٌ، مِنْ أَشْهَرِها الزَّنْجَبيلُ والْخولِنْجانُ وقاقُلَّةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10080, 'زَنْجِيٌّ', 'زنجي', 'جامد', '', 'زنجي', 'زنج', '', '', '', 'جمع تكسير', '', '', '', '"واحِدُالزَّنْجِ"', '', '', '', '', '', '', '', '', '": واحِدُ الزَّنْجِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10081, 'زِنادٌ', 'زناد', 'جامد', 'زند', 'زناد', 'زند', '', '', '', 'مفرد', 'DnN', '', '', '"أَزْنِدَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَزْنِدَةٌ . [ز ن د]. 1.""ضَغَطَ على زِنادِ مُسَدَّسِهِ"" : كَبْسولَةٌ مَعْدِنِيَّةٌ تُشْبِهُ اللِّسانَ يُضْغَطُ عَلَيْها بِالأُصْبُـعِ لِيَخْرُجَ مِنَ الْمُسَدَّسِ الرَّصاصُ. ""زِنادُ البُنْدُقِيَّةِ"". 2.""زِنادُ القَدَّاحَةِ"" : لَوْلَبٌ في رَأْسِها، بِهِ تَشْتَعِلُ نارُها. 3.""رَجُلٌ وارِي الزِّنادِ"" : أَي مُفْلِحٌ. 4.""رَجُلٌ كابِي الزِّنادِ"" : أَيْ خاسِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10082, 'أَزْنِدَةٌ', 'أزندة', 'جامد', '', 'ءزندة', 'زندة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10083, 'زِنْديقٌ', 'زنديق', 'جامد', 'زندق', 'زنديق', 'زندق', '', '', '', 'مفرد', 'DnN', '', '', '"زَنادِيقُ:زَنادِقَةٌ"', '', 'R', '', '', '', '', '', '', '". ""يا لَهُ مِنْ زِنْديقٍ ضالٍّ"" : الْمُمارِسُ للزَّنْدَقَةِ، الضَّالُّ الخَبيثُ، الْمُلْحِدُ، مَنْ يُظْهِرُ الإِيمانَ وَيُخْفِي الكُفْرَ وَيُضْمِرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10084, 'زَنادِيقُ', 'زناديق', 'جامد', '', 'زناديق', 'زندق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10085, 'زَنادِقَةٌ', 'زنادقة', 'جامد', '', 'زنادقة', 'زندقة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10086, 'زَنْدَقَةٌ', 'زندقة', 'جامد', '', 'زندقة', 'زندقة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"""ما هَذِهِ الزَّنْدَقَةُ"" : الْخُبْثُ والضَّلالُ والْمَكْرُ والإِلْحادُ، وَكُلُّ قَوْلٍ يَخْرُجُ عَمَّا هُوَ مُتَعارَفٌ عَلَيْهِ وَإِنْكارُ الدِّينِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10087, 'زَنابيرُ', 'زنابير', 'جامد', 'زنر', 'زنابير', 'زنبر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"زَنابيرُ-زَنابيرُ[ز ن ر]. 1.: حَصىً صِغارٌ. 2.: ذُبابٌ صِغارٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10088, 'زُنَّارٌ', 'زنار', 'جامد', 'زنر', 'زنار', 'زنر', '', '', '', 'مفرد', 'DnN', '', '', '"زَنانيرُ"', '', 'R', '', '', '', '', '', '', '". 1.""شَدَّتْ زُنَّاراً على وَسَطِها"" : حِزاماً يُشَدُّ على الوَسَطِ، النِّطاقُ. ""وَقَفَ في الوَسَطِ فَتـىً في جِلْبابٍ أَبْيَضَ مُحْتَزِماً بِزُنَّارٍ"". (ن. محفوظ). 2.""زُنَّارُ الرَّاهِبِ"" : الحِزامُ الَّذِي يَشُدُّ بِهِ وَسَطَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10089, 'زَنانيرُ', 'زنانير', 'جامد', '', 'زنانير', 'زننر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10090, 'زَنَمَةٌ', 'زنمة', 'جامد', '', 'زنمة', 'زنمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"1. : ما يُقْطَعُ مِنْ أُذُنِ الْجَمَلِ أَو الشَّاةِ وَيُتْرَكُ مُعَلَّقاً وَيُفْعَلُ ذَلِكَ بِكِرامِ الإِبِلِ. 2.""زَنَمَتا الأُذُنِ"" : زَائِدَتانِ تَلِيانِ الشَّحْمَةَ وَتُقابِلانِ الوَتَرَةَ. 3.""زَنَمَةُ الْحَلْقِ"" : اللَّحْمَةُ الْمُتَدَلِّيَةُ في أَقْصَى الْحَلْقِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10091, 'زَهْرَةٌ', 'زهرة', 'جامد', 'زهر', 'زهرة', 'زهرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"واحِدَةُالزَّهْرِ"', '', 'R', '', '', '', '', '', '', '". 1.""ظَهَرَتْ زَهْرَةُ النَّباتِ"" : نَوْرُها. 2.""إِنَّها زَهْرَةُ الدُّنْيا"": بَهْجَتُها، زينَتُها.طه آية 131 وَلاَ تَمُدَّنَّ عَيْنَيْكَ إلى ما مَتَّعْنا بِهِ أَزْواجاً مِنْهُمْ زَهْرَةَ الحَياةِ الدُّنْيا (قرآن) ""زَهْرَةُ العُمْرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10092, 'زُهْرَةٌ', 'زهرة', 'جامد', 'زهر', 'زهرة', 'زهرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"زُهْرَةٌ-زُهْرَةٌ[ز هـ ر]. ""زُهْرَةُ امْرَأَةٍ"" : بَياضُها النَّاصِعُ، صَفاءُ لَوْنِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10093, 'زَهْرٌ', 'زهر', 'جامد', 'زهر', 'زهر', 'زهر', '', '', '', 'مفرد', 'DnN', '', '', '"زُهورٌ:أَزْهارٌجأَزاهِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""زَهْرُ النَّباتِ"" : نَوْرُهُ، أَيْ كُلُّ ما يَخْرُجُ فيهِ مِنْ وَرْدٍ أَوْ نَحْوِهِ. 2.""ماءُ الزَّهْرِ"" : سائِلٌ عَطِرٌ يُسْتَخْرَجُ مِنْ أَزْهارِ اللَّيْمونِ بِالتَّقْطيرِ. 3.""زَهْرُ النَّرْدِ"" : قِطْعَةٌ مِنَ العاجِ أَوِ الْخَشَبِ وَما شابَهَ ذَلِكَ، حُفِرَ على أَوْجُهِها السِّتَّةِ نُقَطٌ مِنْ 1 إلى 6، تُسْتَعْمَلُ في لُعَبِ الطَّاوِلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10094, 'زُهورٌ', 'زهور', 'جامد', '', 'زهور', 'زهر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10095, 'أَزْهارٌ', 'أزهار', 'جامد', '', 'ءزهار', 'زهر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10096, 'أَزاهِرُ', 'أزاهر', 'جامد', '', 'ءزاهر', 'زهر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10097, 'زُهْرٌ', 'زهر', 'جامد', 'زهر', 'زهر', 'زهر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"زُهْرٌ-زُهْرٌ[ز هـ ر]. ""زُهْرُ الشَّهْرِ"" : ثَلاثُ لَيالٍ مِنْ أَوَّلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10098, 'زَهْرِيَّةٌ', 'زهرية', 'جامد', 'زهر', 'زهرية', 'زهرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"زَهْرِيَّةٌ-زَهْرِيَّةٌ[ز هـ ر]. ""زَهْرِيَّةٌ جَميلَةٌ في بَهْوِ البَيْتِ"" : وِعاءٌ مِنَخَزَفٍ وَنَحْوِهِ يوضَعُ فِيهِ الوَرْدُ، والزَّهْرُ لِلزِّينَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10099, 'زُهورٌ', 'زهور', 'جامد', 'زهر', 'زهور', 'زهر', '', '', '', 'مفرد', '', '', '', '"مفردزَهْر"', '', '', '', '', '', '', '', '', '". ""ظَهَرَتِ الزُّهُورُ بِشَتَّى أَلْوَانِهَا مَعَ بِدَايَةِ فَصْلِ الرَّبيعِ"" : نَوْرُ النَّباتِ والشَّجَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10100, 'مِزْهَرِيَّةٌ', 'مزهرية', 'جامد', 'زهر', 'مزهرية', 'مزهرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""لَفَتَتِ الْمِزْهَرِيَّةُ نَظَرَ الجَالِسِينَ فِي الغُرْفَةِ"" : إِنَاءٌ مِنْ زُجَاجٍ تُوضَعُ فِيهِ الأَزْهَارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10101, 'زُهَرَةٌ', 'زهرة', 'جامد', '', 'زهرة', 'زهرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"1. : كَوْكَبٌ سَيَّارٌ مِنَ الْمَجْموعَة الشَّمْسِيَّةِ، وَالزُّهَرَةُ شَديدَةُ اللَّمَعانِ بَعْدَ الشَّمْسِ والقَمَرِ، تارَةً تَكونُ نَجْمَةَ الصُّبْحِ وَتارَةً نَجْمَةَ الْمَساءِ، تَدورُ حَوْلَ الشَّمْسِ بَيْنَ عُطارِدَ وَالأَرْضِ. 2.: إِلاهَةُ الْجَمالِ عِنْدَ الإِغْريقِ (أفروديت)، وَعِنْدَ الرُّمانِ (فينوس). يُسَمِّيها العَرَبُ بِالعُزَّى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10102, 'زُهاءٌ', 'زهاء', 'جامد', 'زهو', 'زهاء', 'زه', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"زُهاءٌ-زُهاءٌ[ز هـ و]. 1.""اِنْتَظَرْتُهُ زُهاءَ رُبْعِ ساعَةٍ"" : فَتْرَةً تُقارِبُ، حَوالَيْ رُبْعِ ساعَةٍ. ""يَسْتَغْرِقُ الدَّرْسُ زُهاءَ ساعَةٍ"". ""أَمْلِكُ زُهاءَ ثَمانِينَ دِرْهَماً"" ""هُمْ زُهاءُ أَلْفٍ"". 2.""كَمْ زُهاؤُهُمْ "" : كَمْ عَدَدَهُمْ تَقْريباً. 3.""هُمْ قَوْمٌ ذَوُو زُهاءٍ"": أَيْ ذَوُو عَدَدٍ كَبيرٍ. 4.""زُهاءُ الدُّنْيا"" : زِينَتُها، زُخْرُفُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10103, 'زُها', 'زها', 'جامد', 'زهو', 'زها', 'زه', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"زُها-زُها[ز هـ و]. 1.""زُها الوَجْهِ"" : حُسْنُهُ. 2.""زُها الدُّنْيا"" : زِينَتُها، زَخْرَفَتُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10104, 'زَهْوٌ', 'زهو', 'جامد', 'زهو', 'زهو', 'زه', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"زَهْوٌ-زَهْوٌ[ز هـ و] (مص. زَها). 1.""أَخَذَهُ الزَّهْوُ"" : الكِبْرُ، الفَخْرُ، التِّيهُ. 2.""مَنْظَرٌ زَهْوٌ"" : جَميلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10105, 'زُؤانٌ', 'زؤان', 'جامد', '', 'زءان', 'زن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زُؤانٌ-زُؤانٌ(نب). 1. : نَباتٌ مِنْ فَصيلَةِ النَّجْلِيَّاتِ، أَنْواعُهُ عَديدَةٌ، وَهُوَ حَبٌّ يُشْبِهُ حَبَّ الحِنْطَةِ، لَوْنُهُ يَميلُ إلى السَّوادِ والاصْفِرارِ، وَيُخالِطُ البُرَّ فَيُكْسِبُهُ رَداءةً، يُسَبِّبُ أَكْلُهُ اسْتِرْخاءً وَدُواخاً. ""يا فَرَساً شَهْباءَ، نُطْعِمُها الصَّبيرَ والزُّؤانَ"". (أَدونيس). 2.""فَصَلَ الزُّؤانَ عَنِ الحِنْطَةِ"". (مثل) : وَهُوَ يَعْنِي فَصْلَ الأَخْيارِ عَنِ الأَشْرارِ. ""وَلا يَحْصُلونَ لِقاءَ أَتْعابِهِمْ على غَيْرِ التِّبْنِ والزُّؤَانِ"". (جبران خ. جبران)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10106, 'تَزَاوُجٌ', 'تزاوج', 'جامد', 'زوج', 'تزاوج', 'تزج', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَزَاوُجٌ-تَزَاوُجٌ [ز و ج]. 1.""تَزَاوُجُ العَائِلَتَيْنِ"" : تَزَاوُجُ أَفْرَادِهَا بَعْضِهِمْ بَعْضاً. 2.""تَزَاوُجُ عَدَدٍ"": اِزْدِواجُهُ، صَيْرُهُ اثْنَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10107, 'زَوْجَةٌ', 'زوجة', 'جامد', 'زوج', 'زوجة', 'زجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"(زِيجَاتٌ)"', '', 'R', '', '', '', '', '', '', '". ""اِخْتارَها زَوْجَةً لَهُ"" : اِمْرَأَتَهُ، قَرينَتَهُ، حَرَمَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10108, 'زِيجَاتٌ', 'زيجات', 'جامد', '', 'زيجات', 'زجت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10109, 'مُزْدَوِجَاتٌ', 'مزدوجات', 'جامد', 'زوج', 'مزدوجات', 'مزدجت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"مُزْدَوِجَاتٌ-مُزْدَوِجَاتٌ [ز و ج] (حو). 1.""مُزْدَوِجَاتُ الأَرْجُلِ"": رُتْبَةٌ مِنْ حَيَوَانَاتِ القِشْرِيَّاتِ. 2.""مُزْدَوِجَاتُ الأَصَابِعِ"" : رُتْبَةٌ مِنَ الْحَيَوَانَاتِ اللَّبُونَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10110, 'زادٌ', 'زاد', 'جامد', 'زود', 'زاد', 'زد', '', '', '', 'مفرد', 'DnN', '', '', '"أَزْوادٌ:زُودٌ"', '', 'R', '', '', '', '', '', '', '". 1.""زادُ الْمُسافِرِ"" : مايَحْمِلَهُ مَعَهُ مِنْ طَعَامٍ. ""مَنْ كانَ لَهُ زادٌ فَلْيُعِنْ مَنْ لا زادَ لَهُ"". (التوحيدي). 2.""كَسَبَ زاداً"" : ما يَكْسِبُهُ الإِنْسانُ خَيْراً أَوْ شَرّاً.البقرة آية 197 وتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَى (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10111, 'أَزْوادٌ', 'أزواد', 'جامد', '', 'ءزواد', 'زد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10112, 'زُودٌ', 'زود', 'جامد', '', 'زود', 'زد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10113, 'مَزَادَةٌ', 'مزادة', 'جامد', 'زود', 'مزادة', 'مزدة', '', '', '', 'مفرد', 'DnN', '', '', '"مَزَايِدُ"', '', 'R', '', '', '', '', '', '', '". 1.""حَمَلَ مَعَهُ مَزَادَةً ثَقِيلَةً"": مَا يُوضَعُ فِيهِ الزَّادُ. 2.""مَزَادَةُ الكَشَّافِ"" : وِعَاءٌ مِنْ مَعْدِنٍ أَوْ نَحْوِهِ يُحْمَلُ فِيهِ الْمَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10114, 'مَزَايِدُ', 'مزايد', 'جامد', '', 'مزايد', 'مزد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10115, 'مِزْوَدَةٌ', 'مزودة', 'جامد', 'زود', 'مزودة', 'مزدة', '', '', '', 'مفرد', 'DnN', '', '', '"مَزَاوِدُ"', '', 'R', '', '', '', '', '', '', '". ن. مِزْوَدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10116, 'مَزَاوِدُ', 'مزاود', 'جامد', '', 'مزاود', 'مزد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10117, 'مِزْوَدٌ', 'مزود', 'جامد', 'زود', 'مزود', 'مزد', '', '', '', 'مفرد', 'DnN', '', '', '"مَزَاوِدُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِزْوَدُ الكَشَّافِ"" : وِعَاءٌ مِنْ جِلْدٍ وَنَحْوِهِ يُوضَعُ فِيهِ الزَّادُ. 2.: آلَةٌ مُوسِيقِيَّةٌ نَفْخِيَّةٌ بِتُونُسَ، وَهِيَ كَلِمَةٌ مُحَرَّفَةٌ مِنَ المِزْوَجِ وَتُعْرَفُ بِالعِرَاقِ بِاسْمِ الْمَطْبَخِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10118, 'مَزَاوِدُ', 'مزاود', 'جامد', '', 'مزاود', 'مزد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10119, 'زِوارٌ', 'زوار', 'جامد', 'زور', 'زوار', 'زر', '', '', '', 'مفرد', 'DnN', '', '', '"أَزْوِرَةٌ"', '', 'R', '', '', '', '', '', '', '". ""شَدَّ الأَسيرَ بِالزِّوارِ"" : حَبْلٌ تُرْبَطُ بِهِ يَدُ الأَسيرِ إلَى صَدْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10120, 'أَزْوِرَةٌ', 'أزورة', 'جامد', '', 'ءزورة', 'زرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10121, 'زُورٌ', 'زور', 'جامد', 'زور', 'زور', 'زر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زَوَرٌ-زَوَرٌ[ز و ر] (مص. زَوِرَ). 1.""زَوَرُ الشَّمْسِ"" : مَيْلُها. 2.""زَوَرُ الطَّائِشِ"" : طَيْشُهُ. 3.""زَوَرُ الصَّدْرِ"" : اِعْوِجاحُهُ. 4.""زَوَرُ العَيْنِ"" : أَيِ النَّظَرُ بِمُؤْخِرِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10122, 'زِيارٌ', 'زيار', 'جامد', 'زور،زير', 'زيار', 'زر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زِيارٌ-زِيارٌ[ز و ر، ز ي ر]. : ما يَشُدُّ بِهِ البَيْطارُ جَحْفَلَةَ الدَّابَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10123, 'زَوْرَقٌ', 'زورق', 'جامد', '', 'زورق', 'زرق', '', '', '', 'جمع تكسير', 'DnN', '', '', '"زَوارِقُ"', '', 'R', '', '', '', '', '', '', '"ج: زَوارِقُ. ""رَكِبَ الزَّوْرَقَ لِيَعْبُرَ النَّهْرَ"" : مَرْكَبٌ، قارِبٌ يُدْفَعُ بِالْمَجادِيفِ، وَهُوَ أَنْوَاعٌ: ""زَوْرَقُ صَيْدٍ""، ""زَوْرَقٌ بُخارِيٌّ""، ""زَوْرَقٌ هَوائِيٌّ"". ""اِنْطَلقَتْ زَوارِقُ النَّجاةِ تَبْحَثُ عَنْ جُثَّةِ الغَريقِ"" ""الرَّجُلُ والْمَرْأَةُ مِجْدَافانِ في زَوْرَقِ البَيْتِ"". (م. ص. الرافعي)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10124, 'زَوارِقُ', 'زوارق', 'جامد', '', 'زوارق', 'زرق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10125, 'زَواقٌ', 'زواق', 'جامد', 'زوق', 'زواق', 'زق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زَواقٌ-زَواقٌ[ز و ق]. ""زَواقُ الْمَرْأَةِ"" : زِينَتُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10126, 'مِزْوَلَةٌ', 'مزولة', 'جامد', 'زول', 'مزولة', 'مزلة', '', '', '', 'مفرد', 'DnN', '', '', '"مَزَاوِلُ"', '', 'R', '', '', '', '', '', '', '".: السَّاعَةُ الشَّمْسِيَّةُ، وَهِيَ آلَةٌ قَدِيمَةٌ كَانَ يُعْرَفُ بِهَا وَقْتُ الظُّهْرِ مِنَ الظِّلِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10127, 'مَزَاوِلُ', 'مزاول', 'جامد', '', 'مزاول', 'مزل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10128, 'زُونٌ', 'زون', 'جامد', '', 'زون', 'زن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَزْوانٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَزْوانٌ. : الصَّنَمُ، أَيْ ما عُبِدَ مِنْ دونِ اللَّهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10129, 'أَزْوانٌ', 'أزوان', 'جامد', '', 'ءزوان', 'زن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10130, 'زاوِيَةٌ', 'زاوية', 'جامد', 'زوي', 'زاوية', 'زة', '', '', '', 'مفرد', 'DnN', '', '', '"زَوايا"', '', '', '', '', '', '', '', '', '". 1.""زاوِيَةُ البَيْتِ"" : رُكْنُهُ. 2.""زاوِيَةُ النَّجَّارِ أَوِ البَنَّاءِ"" : أَداةٌ ذاتُ ضِلْعَيْنِ مُسْتَقيمَيْنِ يَتَكَوَّنُ مِن اتِّصالِهِما زاوِيَةٌ قائِمَةٌ. 3.""زاوِيَةٌ حادَّةٌ"" : ما كانَ انْفِراجُها أَصْغَرَ مِنَ الزَّاوِيَةِ القائِمَةِ (أَصْغَرَ من 90 درجة). 4.""زاوِيَةٌ مُنْفَرِجَةٌ"" : ما كانَ انْفِراجُها أَكْثَرَ من 90 دَرَجَة. 5.""الزَّاوِيَةُ الْمَرْكَزِيَّةُ"" : الزَّاوِيَةُ التِي يَكونُ رَأْسُها في مَرْكَز الدَّائِرَةِ. 6.""الزَّاوِيَتانِ الْمُتَقابِلَتانِ بِالرَّأْسِ"" : زَاوِيَتانِ يَكونُ ضِلْعَا إِحْداهُما امْتِداداً لِضِلْعَيِ الأُخْرَى. 7.""الزَّاوِيَتانِ الْمُتَكامِلَتانِ"" : زَاوِيَتـانِ يُساوِي مَجْموعُهُما زاوِيَتَيْنِ قائِمَتَيْنِ. 8.""الزَّاوِيَتانِ الْمُتَجاوِرَتانِ"": زَاوِيَتانِ لَهُما رَأْسٌ واحِد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10131, 'زَوايا', 'زوايا', 'جامد', '', 'زوايا', 'ز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10132, 'زَيْتٌ', 'زيت', 'جامد', 'زيت', 'زيت', 'زت', '', '', '', 'مفرد', 'DnN', '', '', '"زُيوتٌ"', '', 'R', '', '', '', '', '', '', '". 1. : مادَّةٌ سائِلَةٌ تُسْتَخْرَجُ مِنَ الزَّيْتونِ أَوْ مِنْ بَعْضِ النَّباتاتِ (كَنَوَّارةِ الشَّمْسِ والفُسْتُقِ والسِّمْسِمِ) أَوِ الْحَيَواناتِ، تُسْتَعْمَلُ في الطَّبْخِ. 2.""مَعْصَرَةُ الزَّيْتِ"" : الْمَعْمَلُ الَّذِي يُعْصَرُ فيهِ الزَّيْتونُ. 3.""سَكَبَ زَيْتَ الوَقودِ في مُحَرِّكِ سَيَّارَتِهِ"" : مادَّةٌ زَيْتِيَّةٌ مِنَ الْمَحْروقاتِ، النَّفْطُ، البِتْرولُ. 4.""قِنْديلُ زَيْتٍ"" : سائِلٌ زَيْتِيٌّ يُسْتَعْمَلُ للإِضاءةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10133, 'زُيوتٌ', 'زيوت', 'جامد', '', 'زيوت', 'زت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10134, 'زَيْتونٌ', 'زيتون', 'جامد', 'زيت', 'زيتون', 'زتن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زَيْتونٌ-زَيْتونٌ[ز ي ت] (نب). 1. : شَجَرَةٌ مِنْ فَصيلَةِ الزَّيْتونِيَّاتِ، لَها جِذْعٌ صَلْبٌ، بِهِ عُقَدٌ، أَوْراقُها خَضْراءُ شاحِبَةٌ، تُعْطِي ثَمَراً زَيْتِيّاً، تَخْتَلِفُ أَلْوانُهُ حَسَبَ نُضْجِهِ وَفَتَراتِ قَطْفِهِ مِنْ أَخْضَرَ وأَصْفَرَ إلى أَحْمَرَ بَنَفْسَجِيٍّ.عبس آية 27 ، 28 ، 29 فَأَنْبَتْنا فيها حَبّاً وَعِنَباً وَقَضْباً وَزَيْتوناً وَنَخْلاً . (قرآن) ""ما طَعامُكَ قالَ: الخُبْزُ والزَّيْتونُ"". 2.""بَساتينُ الزَّيْتونِ"" : مَزارِعُ أَشْجارِ الزَّيْتونِ. 3.""غُصْنُ الزَّيْتونِ"" : يُرْمَزُ بِهِ إلَى السَّلامِ تَذْكاراً بِالْحَمامَةِ الَتِي حَمَلَتْ بِمِنْقارِها غُصْنَ الزَّيْتونِ إلى سَفينَةِ نوحٍ عِنْدَ انْتِهاءِ الطُّوفانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10135, 'مِزْيَتَةٌ', 'مزيتة', 'جامد', 'زيت', 'مزيتة', 'مزتة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مِزْيَتَةٌ-مِزْيَتَةٌ [ز ي ت].: إِنَاءٌ ذُو بُلْبُلٍ رَقِيقٍ وَطَوِيلٍ تُزَيَّتُ بِهِ الآلاَتُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10136, 'زَيْتونَةٌ', 'زيتونة', 'جامد', '', 'زيتونة', 'زتنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":واحِدَةُالزَّيْتونِ"', '', 'R', '', '', '', '', '', '', '"واحِدَةُ الزَّيْتونِ. 1.""جَلَسَ تَحْتَ ظِلِّ زَيْتونَةٍ"": شَجَرَةُ الزَّيْتونِ. 2.""ذاقَ زَيْتونَةً"" : حَبَّةَ ثَمَرَةٍ مِنَ الزَّيْتونِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10137, 'زَيْتونِيَّاتٌ', 'زيتونيات', 'جامد', '', 'زيتونيات', 'زتنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصيلَةٌ نَباتِيَّةٌ مِنْ ذَواتِ الفِلْقَتَيْنِ، أَنْواعُها عَديدَةٌ، تَشْمُلُ ثَلاثَ مَراتِبَ: الزَّيْتونِيَّة والْمُرَّانِيَّة والياسَمينِيَّة."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10138, 'زيجٌ', 'زيج', 'جامد', '', 'زيج', 'زج', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":أَزْياجٌ:زِيجَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَزْياجٌ، زِيجَةٌ، زِيجاتٌ. (فك). 1. : جَدْوَلٌ تُعْرَفُ بِهِ أَحْوالُ حرَكاتِ الكَواكِبِ وَمِنْهُ يُسْتَخْرَجُ التَّقْويم سَنَةً سَنَةً. 2.""زيجُ البَنَّاءِ"" : الْخَيْطُ الَّذِي يَمُدُّهُ البَنّاءُ على الْحَائِطِ، المِطْمَرُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10139, 'أَزْياجٌ', 'أزياج', 'جامد', '', 'ءزياج', 'زج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10140, 'زِيجَةٌ', 'زيجة', 'جامد', '', 'زيجة', 'زجة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10141, 'مَزَادٌ', 'مزاد', 'جامد', 'زيد', 'مزاد', 'مزد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَزَادٌ-مَزَادٌ [ز ي د]. 1.""بَيْعٌ بِالْمَزَادِ العَلَنِيِّ"" : بَيْعٌ يَتِمُّ بَيْنَ الْمُشْتَرِينَ بِالْمُزَايَدَةِ، أَيْ حَسَبَ مَنْ يُقَدِّمُ أَعْلَى ثَمَنٍ. 2.""قَاعَةُ الْمَزَادِ"" : قَاعَةُ الأَشْيَاءِ الْمَعْرُوضَةِ لِلْمُزَايَدَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10142, 'زِيرٌ', 'زير', 'جامد', 'زير', 'زير', 'زر', '', '', '', 'مفرد', 'DnN', '', '', '"أزْيارٌ:أَزْوارٌ:زِيرَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""حَمَلَتِ الزِّيرَ على كَتِفَيْها"" : الْجَرَّةَ مِن الفَخَّارِ، وَهِيَ كَبيرَةٌ مَخْروطِيَّةُ الشَّكْلِ يُحْفَظُ فيها الْماءُ. 2.""شَدَّ أَزْيارَ العودِ"" : أَوْتارَهُ الدَّقيقَةَ. 3.""زيرُ النِّساءِ"" : مَـنْ يُحِـبُّ الاخْتِلاطَ بِالنِّساءِ والتَّحَدُّثَ إِلَيْهِنَّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10143, 'أزْيارٌ', 'أزيار', 'جامد', '', 'ءزيار', 'زر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10144, 'أَزْوارٌ', 'أزوار', 'جامد', '', 'ءزوار', 'زر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10145, 'زِيرَةٌ', 'زيرة', 'جامد', '', 'زيرة', 'زرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10146, 'زِيزٌ', 'زيز', 'جامد', 'زيز', 'زيز', 'زز', '', '', '', 'مفرد', 'DnN', '', '', '"زيزانٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"(حو). : حَشَرَةٌ مِنْ فَصيلَةِ الزِّيزِيَّاتِ، مِنْ رُتْبَةِ نِصْفِيَّاتِ الأَجْنِحَةِ، تَحُطُّ طَويلاً عَلَى الشَّجَرِ، لَها صَوْتٌ صَرْصارٌ على وَتيرَةٍ واحِدَةٍ (زيز) وَسُمِّيَتْ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10147, 'زيزانٌ', 'زيزان', 'جامد', '', 'زيزان', 'ززن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10148, 'زَيْزَفونٌ', 'زيزفون', 'جامد', '', 'زيزفون', 'ززفن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"زَيْزَفونٌ-زَيْزَفونٌ(نب). 1. : شَجَرٌ مِنْ فَصِيلَةِ الزَّيْزَفونِيَّاتِ، لَهُ زَهْرٌ أَبْيَضُ صَغيرٌ ذُو رائِحَةٍ طَيِّبَةٍ عَطِرَةٍ، بَرِّيٌّ وَزِراعِيٌّ، يَكْثُرُ حَوْلَ البَساتينِ والْحَدائِقِ، يُتَداوَى بِهِ. 2.""هُوَ كالزَّيْزَفونِ يُزْهِرُ وَلا يُثْمِرُ"": أَيْ يَعِدُ وَلا يَفِي بِوَعْدِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10149, 'زَيْزَفونِيَّاتٌ', 'زيزفونيات', 'جامد', '', 'زيزفونيات', 'ززفنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"زَيْزَفونِيَّاتٌ-زَيْزَفونِيَّاتٌ(نب). : فَصيلَةٌ نَباتِيَّةٌ مِنْ ذَواتِ الفِلْقَتَيْنِ، أَجْناسُها عَديدَةٌ، أَزْهارُها عِطْرِيَّةُ الرَّائِحَةِ، وَهِيَ فَرْدِيَّةٌ أَو عُنْقودِيَّةٌ، أَوْ مِحْوَرِيَّةٌ، أَو تاجِيَّةُ الارْتِكازِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10150, 'زِيزِيَّاتٌ', 'زيزيات', 'جامد', '', 'زيزيات', 'ززت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصيلَةُ حَشَراتٍ مِنْ نِصْفِيَّاتِ الأَجنِحَةِ الْمُتَجانِسَةِ، تتَمَيَّزُ بِأَصْواتِها الحادَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10151, 'زِيقٌ', 'زيق', 'جامد', 'زيق', 'زيق', 'زق', '', '', '', 'مفرد', 'DnN', '', '', '"أَزْيَاقٌ"', '', 'R', '', '', '', '', '', '', '". 1.""زِيقُ الْقَمِيصِ"" : يَاقَةٌ، مَا أَحَاطَ مِنْهُ بِالْعُنُقِ. 2.""زِيقُ الْبَنَّاءِ "" : الْخَيْطُ الَّذِي يُقَوِّمُ بِهِ الْحَائِطَ، الزِّيجُ، الْمِطْمَرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10152, 'أَزْيَاقٌ', 'أزياق', 'جامد', '', 'ءزياق', 'زق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10153, 'زِيمَةٌ', 'زيمة', 'جامد', 'زيم', 'زيمة', 'زمة', '', '', '', 'مفرد', 'DnN', '', '', '"زِيَمٌ"', '', 'R', '', '', '', '', '', '', '". ""زيمَةُ الجِمالِ"" : قِطْعَةٌ مِنَ الْجِمَالِ بَيْنَ الْجَمَلَيْنِ وَالْخَمْسَةَ عَشَرَ جَمَلاً تَقْريباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10154, 'زِيَمٌ', 'زيم', 'جامد', '', 'زيم', 'زم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10155, 'زَيْنَبٌ', 'زينب', 'جامد', '', 'زينب', 'زنب', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'Rp', '', '', '', '', '', '', '"زَيْنَبٌ-زَيْنَبٌ، ةٌ(نب). 1. : نَباتٌ مِنْ فَصيلَةِ الزَّنْبَقِيَّاتِ، أَصْلُهُ مِنَ المِكْسيكِ، يُزْرَعُ لِعَناقيدِهِ الْجَميلَةِ، وَحُسْنِ مَنْظَرِهِ وَأَوْراقِهِ الطَّيِّبَةِ النَّافِذَةِ. 2.""زَيْنَبُ"" : اِسْمُ عَلَمٍ لِلْمُؤَنَّثِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10156, 'زِيٌّ', 'زي', 'جامد', 'زيي', 'زي', 'ز', '', '', '', 'مفرد', 'DnN', '', '', '"أَزْياءٌ"', '', '', '', '', '', '', '', '', '". 1.""اِرْتَدَى زِيّاً عَسْكَرِيّاً"" : أَي اللِّباسُ الَّذِي يُعْطِي هَيْئَةً وَشَكْلاً لِصاحِبِهِ. ""حَضَرُوا الحَفْلَ بِالزِّيِّ الوَطَنِيِّ"" "" الزِّيُّ العَرَبِيُّ"" ""أَقْبَلَ بِزِيٍّ عَجيبٍ"". 2.""عَلَى الزِّيِّ الجَديدِ"" : على الطِّرازِ الجَديدِ. 3.""حَضَرَتْ مَعْرِضَ الأَزْياءِ"" : مَعْرِضٌ تُقَدَّمُ فيهِ أَشْكالٌ مُتَنَوِّعَةٌ مِنَ الْمَلابِسِ الْحَديثَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10157, 'أَزْياءٌ', 'أزياء', 'جامد', '', 'ءزياء', 'ز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10158, 'سَاءَ', 'ساء', 'جامد', '', 'ساء', 'س', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'N', '', '"فِعلٌ مَاضٍ جَامدٌ للذَّمِّ. ""سَاءَ مَا تَفْعَلُ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10159, 'سَابُورَةٌ', 'سابورة', 'جامد', '', 'سابورة', 'سبرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '": سَلَّةٌ مُجَوَّفَةٌ كَبِيرَةٌ تُسْتَعْمَلُ لِنَقْلِ التُّرَابِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10160, 'سَاجُورٌ', 'ساجور', 'جامد', '', 'ساجور', 'سجر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"سَواجِيرُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: سَواجِيرُ. ""سَاجُورُ الكَلْبِ"" : القِلاَدَةُ الَّتِي تُوضَعُ فِي عُنُقِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10161, 'سَواجِيرُ', 'سواجير', 'جامد', '', 'سواجير', 'سجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10162, 'سُؤْرَةٌ', 'سؤرة', 'جامد', 'سأر', 'سءرة', 'سرة', '', '', '', 'مفرد', 'DnN', '', '', '"سُؤَرٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""سُؤْرَةُ الشَّبابِ"" : البَقِيَّةُ مِنْهُ. 2.""سُؤْرَةُ الْمَالِ"" : جَيّدُهُ."', '');
