INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10166, 'مَسْأَلَةٌ', 'مسألة', 'جامد', 'سأل', 'مسءلة', 'مسلة', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَائِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""حَلُّ مَسْأَلَةٍ حِسَابِيَّةٍ"": مُشْكِلَة... ""مَسْأَلَةٌ مُعَقَّدَةٌ"". 2.""أَثَارَ مَسْأَلَةً عَلَى جَانِبٍ مِنَ الأَهَمِّيَّةِ"" : قَضِيَّةً. ""لاَ حَلَّ لِمَسْأَلَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10167, 'مَسَائِلُ', 'مسائل', 'جامد', '', 'مساءل', 'مسل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10168, 'سَامِرَةٌ', 'سامرة', 'جامد', '', 'سامرة', 'سمرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"1.: جمَاَعَةٌ فِي فِلِسْطِين تُشَارِكُ اليَهُودَ بَعْضَ عَقائِدِهِمْ وَتُخَالِفُهُمْ فِي بَعْضِهَا. 2.: أحَدُ بَنِي إسْرَائِيل منْ قَبِيلَةِ السَّامِرَةِ، صَنَعَ العِجْلَ وَعَبَدَهُ وَدَعَا قَوْمَهُ إِلَى عِبَادَتِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10169, 'سَبَّابَةٌ', 'سبابة', 'جامد', '', 'سبابة', 'سببة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '": الأُصْبُعُ الَّتِي بَيْنَ الإبْهَامِ وَالوُسْطَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10170, 'سَبَانِخُ', 'سبانخ', 'جامد', '', 'سبانخ', 'سبنخ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'O', 'O', 'O', '', '"سَبَانِخُ-سَبَانِخُ (نب). ن . إِسْبانَخٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10171, 'أَسْبَابٌ', 'أسباب', 'جامد', 'سبب', 'ءسباب', 'سبب', '', '', '', 'مفرد', '', '', '', '"مفردسَبَب"', '', '', '', '', '', '', '', '', '". 1.""لَمْ يَذْكُرْ أَسْبَابَ غِيَابِهِ"" : عِلَلَ. 2.""تَوَفَّرَتْ لَهُ أَسْبَابُ العَيْشِ وَالرَّاحَةِ"" : وَسَائِلُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10172, 'سَبَبٌ', 'سبب', 'جامد', 'سبب', 'سبب', 'سب', '', '', '', 'مفرد', 'DnN', '', '', '"أسْبَابٌ"', '', 'R', '', '', '', '', '', '', '". 1.: كُلُّ شَيْءٍ يُتَوَصَّلُ بِهِ إلَى غَيْرِهِ.الكهف آية 84 ، 85 وآتَيْنَاهُ مِنْ كُلِّ شَيْءٍ سَبَباً فَاتَّبَعَ سَبَباً (قرآن). 2.""عَرَفَ سَبَبَ مَرَضِهِ"" : عِلَّتَهُ. ""يَبْحَثُ عَنْ سَبَبِ غِيَابِهِ"" ""أسْبَابُ النِّزَاعِ"". 3.""لَمْ يَجِدْ سَبَباً يُقَدِّمُهُ"" : عُذْراً، حُجَّةً. ""قَدَّمَ أَسْبَاباً وَاهِيةً"" ""تَعَدَّدَتِ الأَسْبَابُ وَالْمَوْتُ وَاحِدٌ"". 4.""فَهِمَ أَسْبَابَ تَقَدُّمِهِ"" : حَوافِزَ تَقَدُّمِهِ. 5.""اِكْتَشَفَ أَنَّ بَيْنَهُما سَبَباً"" : قَرَابَةً، مَوَدَّةً، عَلاَقَةً. ""تَقَطَّعَتِ الأَسْبَابُ بَيْنَهُمْ"". 6.""تَقَطَّعَتْ بِهِمُ الأَسْبَابُ"" : أعْيَتْهُمُ الحِيَلُ. 7.""اِنْقَطَعَتْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10173, 'أسْبَابٌ', 'أسباب', 'جامد', '', 'ءسباب', 'سبب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10174, 'سَبَبِيَّةٌ', 'سببية', 'جامد', 'سبب', 'سببية', 'سببة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"سَبَبِيَّةٌ-سَبَبِيَّةٌ [س ب ب].: العَلاقَةُ بَيْنَ السَّبَبِ والْمُسَبَّبِ، وَهُوَ مَبْدَأٌ فَلْسَفِيٌّ وَعِلْمِيٌّ قائِمٌ على وُجودِ سَبَبٍ أَوْ عِلَّةٍ لِكُلِّ ما هُوَ مَوْجودٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10175, 'سُبَّةٌ', 'سبة', 'جامد', 'سبب', 'سبة', 'سبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سُبَّةٌ-سُبَّةٌ [س ب ب]. ""إِنَّهَا سُبَّةٌ فِي جَبِينِهِ"" : عَارٌ. ""وَإنَّا لَقَوْمٌ لاَ نَرَى الْمَوْتَ سُبَّةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10176, 'مَسَبَّةٌ', 'مسبة', 'جامد', 'سبب', 'مسبة', 'مسبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَسَبَّةٌ-مَسَبَّةٌ [س ب ب]. ""لَمْ يَتَحَمَّلِ الْمَسَبَّةَ"" : أَيِ الإِهَانَةَ، الشَّتِيمَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10177, 'سُبَاتٌ', 'سبات', 'جامد', 'سبت', 'سبات', 'سبت', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سُبَاتٌ-سُبَاتٌ [س ب ت]. ""وَجَدْتُهُ فِي سُبَاتٍ عَمِيقٍ"" : فِي نَوْمٍ عَمِيق، أَوْ فِي أَوَّلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10178, 'سَبْتٌ', 'سبت', 'جامد', 'سبت', 'سبت', 'سبت', '', '', '', 'مفرد', 'DnN', '', '', '"سُبُوتٌ:أَسْبُتٌ"', '', '', '', 'N', 'O', 'N', 'O', '', '". ""سَافَرَ يَوْمَ السَّبْتِ"" : يَوْمٌ مِنْ أَيَّامِ الأُسْبُوعِ بَعْدَ يَوْمِ الجُمُعَةِ، وَيَلِيهِ يَوْمُ الأحَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10179, 'سُبُوتٌ', 'سبوت', 'جامد', '', 'سبوت', 'سبت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10180, 'أَسْبُتٌ', 'أسبت', 'جامد', '', 'ءسبت', 'سبت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10181, 'سِبْتمبَر', 'سبتمبر', 'جامد', '', 'سبتمبر', 'سبتمبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ التَّاسِعُ مِنَ الشُّهُورِ الغَرْبِيَّةِ، عَدَدُ أيَّامِهِ (30) يَوْماً وَهُوَ مَا يُقَابِلُ شَهْرَ أيْلُول."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10182, 'تَسْبِيحَةٌ', 'تسبيحة', 'جامد', 'سبح', 'تسبيحة', 'تسبحة', '', '', '', 'مفرد', 'DnN', '', '', '"تَسابِيحُ"', '', 'R', '', '', '', '', '', '', '". ""جَلَسَ يُرَدِّدُ التَّسْبِيحَةَ فِي زَاوِيَةِ الْمَسْجِدِ"" : كَلاَمُ التَّسْبِيحِ. ""سَمِعْتُ تَسَابِيحَ الإنْسَانِيَّةِ"".(جبران خ. جبران)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10183, 'تَسابِيحُ', 'تسابيح', 'جامد', '', 'تسابيح', 'تسبح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10184, 'سَابِحَاتٌ', 'سابحات', 'جامد', 'سبح', 'سابحات', 'سبحت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"سَابِحَاتٌ-سَابِحَاتٌ [س ب ح]. 1.: سُفُنٌ. 2.: نُجُومٌ. 3.:مَلاَئِكَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10185, 'سُبُحَاتٌ', 'سبحات', 'جامد', 'سبح', 'سبحات', 'سبحت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"سُبُحَاتٌ-سُبُحَاتٌ [س ب ح]. ""سُبُحَاتُ وَجْهِ اللَّهِ"" : أَنْوارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10186, 'سُبْحَةٌ', 'سبحة', 'جامد', 'سبح', 'سبحة', 'سبحة', '', '', '', 'مفرد', 'DnN', '', '', '"سُبُحَاتٌ"', '', 'R', '', '', '', '', '', '', '". ""لاَ يُفَارِقُ السُّبْحَةَ، بِهَا يُسَبِّحُ لَيْلاًوَنَهاراً"" ‎: خَرَزَاتٌ، عَقِيقٌ مَنْظُومٌ فِي سِلْكٍ، يَذْكُرُ الْمُتَعَبِّدُ بِعَدَدِ حَبَّاتِهِ اِسْمَ اللَّهِ. وَغَالِباً مَا تُسْتَعْمَلُ فِي الْمَشْرِقِ العَرَبِيِّ لِلتَّسْلِيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10187, 'سُبُحَاتٌ', 'سبحات', 'جامد', '', 'سبحات', 'سبحت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10188, 'مِسْبَحَةٌ', 'مسبحة', 'جامد', 'سبح', 'مسبحة', 'مسبحة', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَابِيحُ"', '', 'R', '', '', '', '', '', '', '". ""لاَ تُفَارِقُ المِسْبَحَةُ أَصَابِعَهُ"" : السُّبْحَةُ لِلصَّلاَةِ وَالتَّسْبِيحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10189, 'مَسَابِيحُ', 'مسابيح', 'جامد', '', 'مسابيح', 'مسبح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
