INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10198, 'سِبَارٌ', 'سبار', 'جامد', 'سبر', 'سبار', 'سبر', '', '', '', 'مفرد', 'DnN', '', '', '"سُبُرٌ"', '', 'R', '', '', '', '', '', '', '". : أَدَاةٌ عَلَى شَكْلِ قَضِيبٍ أوْ فَتِيلَةٍ يُسْبَرُ بِها بَحْراً لِمَعْرِفَةِ عُمْقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10199, 'سُبُرٌ', 'سبر', 'جامد', '', 'سبر', 'سبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10200, 'سِبْرٌ', 'سبر', 'جامد', 'سبر', 'سبر', 'سبر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سِبْرٌ-سِبْرٌ [س ب ر]. ""وَلَدٌ حَسَنُ الحِبْرِ وَالسِّبْرِ"" : جَمِيلٌ حَسَنُ الهَيْئَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10201, 'سَبُّورَةٌ', 'سبورة', 'جامد', 'سبر', 'سبورة', 'سبرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَبُّورَةٌ-سَبُّورَةٌ [س ب ر]. ""يَكْتُبُ عَلَى السَّبُّورَةِ"" : لَوْحٌ مِن خَشَبٍ أوْ مَعْدِنٍ حَجَرِيٍّ أو نَحْوِهِ يُكْتَبُ عَلَيْهِ فِي الفُصُولِ الدِّرَاسِيَّةِ، وَيُمْكِنُ مَسْحُ مَا كُتِبَ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10202, 'مِسْبَارٌ', 'مسبار', 'جامد', 'سبر', 'مسبار', 'مسبر', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَابِيرُ"', '', 'R', '', '', '', '', '', '', '". ""آلَةُ المِسْبَارِ"" : آلَةٌ لِسَبْرِ الأَعْمَاقِ، وَتُعْرَفُ أَيْضاً بِالمِرْجَاسِ. ""مِسْبَارٌ لاَسِلْكِيٌّ"" ""مِسْبَارٌ بَحْرِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10203, 'مَسَابِيرُ', 'مسابير', 'جامد', '', 'مسابير', 'مسبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10204, 'سِبْطٌ', 'سبط', 'جامد', '', 'سبط', 'سبط', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ج: أسْبَاطٌ. ""هُوَ سِبْطٌ مِنْ أسْبَاطِهِ"" : وَلَدُ ابْنِهِ أوِ ابْنَتِهِ، أَيِ الحَفِيدُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10205, 'أُسْبُوعٌ', 'أسبوع', 'جامد', 'سبع', 'ءسبوع', 'سبع', '', '', '', 'مفرد', 'DnN', '', '', '"أَسَابِيعُ"', '', 'R', '', '', '', '', '', '', '". ""قَضَيْتُ أُسْبُوعاً فِي الجَبَلِ"" : أَيْ سَبْعَةَ أَيَّامٍ، مَثَلاً مِن يَوْمِ الجُمُعَةِ إِلَى يَوْمِ الخَمِيسِ. ""اِشْتَغَلْتُ الأسْبُوعَ الْمَاضِي"" ""دَرَسَ الأسْبُوعَ كُلَّهُ"" ""مَضَى أُسْبُوعٌ مِنَ الشَّهْرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10206, 'أَسَابِيعُ', 'أسابيع', 'جامد', '', 'ءسابيع', 'سبع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10207, 'سَابعٌ', 'سابع', 'جامد', 'سبع', 'سابع', 'سبع', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"سَابعٌ-سَابعٌ، ةٌ [س ب ع]. 1.: عَدَدٌ يَدُلُّ عَلَى التَّرْتِيبِ، وَيَكُونُ مَعْدُودُهُ مُذَكَّراً : ""هُوَ السَّابِعُ فِي الفَصْلِ"" : أيْ كَانَتْ رُتْبَتُهُ بَيْنَ السَّادِسِ وَالثَّامِنِ، وَيُعْرَبُ نَعْتاً فِي المِثَالِ التَّالِي : ""وَصَلَ الفَائِزُ السَّابِعُ"". وَإذَا لَمْ يُذْكَرْ مَعْدُودُهُ : ""وَصَلَ السَّابِعُ"" يُعْرَبُ فَاعِلَ وَصَلَ، وَإذَا قُلْتَ : ""كَلَّمْتُ السَّابِعَ"" يُعْرَبُ مَفْعُولاً بِهِ،"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10208, 'سَبْعَةٌ', 'سبعة', 'جامد', 'سبع', 'سبعة', 'سبعة', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '"سَبْعَةٌ-سَبْعَةٌ [س ب ع]. 1. : مُفْرَدٌ مَعْدُودُهُ جَمْعٌ مُذَكَّرٌ : ""وَصَلَ سَبْعَةُ رِجَالٍ""، ""يُحَلِّقُ سَبْعَةٌ مِنَ الطَّيْرِ""، ""مَرَرْتُ بِسَبْعَةِ رِجَالٍ"". 2. ""سَبْعَةَ عَشَرَ رَجُلاً"" : عَدَدٌ مُرَكَّبٌ مَعْدُودُهُ مُفْرَدٌ مُذَكَّرٌ. ""سَلَّمْتُهُ سَبْعَةَ عَشَرَ دِرْهَماً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10209, 'سَبْعٌ', 'سبع', 'جامد', 'سبع', 'سبع', 'سبع', '', '', '', 'مفرد', '', '', '', '"(عَدَدٌمُفْرَدٌمَعْدودُهُجَمْ', '', '', '', 'N', 'O', 'N', 'O', '', '"سَبْعٌ-سَبْعٌ [س ب ع] (عَدَدٌ مُفْرَدٌ مَعْدودُهُ جَمْعٌ مُؤَنَّثٌ). 1.""وَصَلَتْ سَبْعُ نِسَاءٍ"" : وَنِسَاءٌ مُضَافٌ إلَى ""سبْعُ"". ""زُرْتُهُ سَبْعَ مَرَّاتٍ"". 2. ""سَبْعَ عَشْرَةَ سَنَةً"" : عَدَدٌ مُرَكَّبٌ مَعْدُودُه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10210, 'سُبْعٌ', 'سبع', 'جامد', 'سبع', 'سبع', 'سبع', '', '', '', 'مفرد', 'DnN', '', '', '"أسْبَاعٌ"', '', 'R', '', '', '', '', '', '', '".: جُزْءٌ مِن سَبْعَةِ أجْزَاءٍ."', '');
