INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10217, 'أَسْبَقِيَّةٌ', 'أسبقية', 'جامد', 'سبق', 'ءسبقية', 'سبقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"أَسْبَقِيَّةٌ-أَسْبَقِيَّةٌ [س ب ق]. ""لَهُ الأسْبَقِيَّةُ"" : لَهُ الأوْلَوِيَّةُ..."', '');
