INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10220, 'سَوابِقُ', 'سوابق', 'جامد', 'سبق', 'سوابق', 'سبق', '', '', '', 'مفرد', '', '', '', '"مفردسابِقَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""رَكَضَتِ السَّوابِقُ"" : الخَيْلُ، ن.سابِق."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10221, 'سَبِيكةٌ', 'سبيكة', 'جامد', 'سبك', 'سبيكة', 'سبكة', '', '', '', 'مفرد', 'DnN', '', '', '"سَبائِكُ"', '', '', '', '', '', '', '', '', '". ""سَبيكَةٌ مِنْ ذَهَبٍ أوْ فِضَّةٍ"" : القِطْعَةُ الْمُذَوَّبَةُ أُفْرِغَتْ فِي قَالَبٍ مُعَيَّنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10222, 'سَبائِكُ', 'سبائك', 'جامد', '', 'سباءك', 'سبك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10223, 'مَسْبَكٌ', 'مسبك', 'جامد', 'سبك', 'مسبك', 'مسبك', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَابِكُ"', '', 'R', '', '', '', '', '', '', '". ""مَسْبَكُ الْحَدِيدِ"" : الْمَعْمَلُ الَّذِي تُسْبَكُ فِيهِ الْمَعَادِنُ. ""مَسْبَكُ الحُرُوفِ"" ""مَسْبَكُ الزُّجَاجِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10224, 'مَسَابِكُ', 'مسابك', 'جامد', '', 'مسابك', 'مسبك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10225, 'سَبَّالَةٌ', 'سبالة', 'جامد', 'سبل', 'سبالة', 'سبلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"سَبَّالَةٌ-سَبَّالَةٌ [س ب ل].: عيْنٌ أوْ سَاقيَةٌ أوْ حَنَفِيَّةٌ يسْتَقِي مِنْهَا العُمُومُ الْمَاءَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10226, 'سَبْلاءُ', 'سبلاء', 'جامد', 'سبل', 'سبلاء', 'سبل', '', '', '', 'مفرد', '', '', '', '"سُبْلٌ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""عَيْنٌ سَبْلاءُ"" : طَوِيلَةُ الهُدْبِ. 2.""اِمْرَأةٌ سَبْلاءُ"" : أيْ فَوْقَ شَفَتِهَا العُلْيَا شَعْرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10227, 'سُبْلٌ', 'سبل', 'جامد', '', 'سبل', 'سبل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10228, 'سَبَلَةٌ', 'سبلة', 'جامد', 'سبل', 'سبلة', 'سبلة', '', '', '', 'مفرد', 'DnN', '', '', '"سِبالٌ"', '', 'R', '', '', '', '', '', '', '". 1.""سَبَلَةٌ يانِعَةٌ"" : سُنْبُلَةٌ. 2.""سَبَلَةُ الرَّجُلِ"" : الدَّائِرَةُ الَّتِي فِي وَسَطِ شَفَتِهِ العُلْيا. 3.""سَبَلَةُ الإنَاءِ"" : رَأْسُهُ. 4.""جَرَّتِ الْمَرْأةُ سَبَلَتَهَا"" : ثِيَابَهَا الْمُسْبَلَة. 5.""وجَاءَ وَقَدْ نَشَرَ سَبَلَتَهُ"" : أيْ جَاءَ مُتَوَعِّداً. 6.""سَبَلةُ اللِّحْيَةِ"": مُقَدَّمُهَا. 7.""جَمَلٌ حَسَنُ السَّبَلَةِ"" : أَيْ رَقِيقُ الجِلْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10229, 'سِبالٌ', 'سبال', 'جامد', '', 'سبال', 'سبل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10230, 'سَبَلٌ', 'سبل', 'جامد', 'سبل', 'سبل', 'سبل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَبَلٌ-سَبَلٌ [س ب ل]. 1. ""غَمَرَ السَّبَلُ الأَرْضَ"" : الْمَطَرُ السَّاقِطُ. 2. ""نَضَجَ السَّبَلُ"" : السُّنْبُلُ. 3. ""أَصَابَهُ السَّبَلُ"" : دَاءٌ فِي العَيْنِ شِبْهُ غِشَاوةٍ كَأنَّها نَسْجُ العَنْكَبُوتِ. 4. ""ثَوْبٌ سَبَلٌ"": مُسْبَلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10231, 'سُبُولَةٌ', 'سبولة', 'جامد', 'سبل', 'سبولة', 'سبلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سُبُولَةٌ-سُبُولَةٌ [س ب ل]. : سُنْبُلَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10232, 'سِتَارَةٌ', 'ستارة', 'جامد', 'ستر', 'ستارة', 'سترة', '', '', '', 'مفرد', 'DnN', '', '', '"سَتَائِرُ"', '', 'R', '', '', '', '', '', '', '". ن: سِتَارٌ. ""أسْدَلُوا سَتَائِرَ النَّوَافِذِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10233, 'سَتَائِرُ', 'ستائر', 'جامد', '', 'ستاءر', 'ستر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10234, 'سِتَارٌ', 'ستار', 'جامد', 'ستر', 'ستار', 'ستر', '', '', '', 'مفرد', 'DnN', '', '', '"سُتُرٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""أسْدَلَ سِتَارَ النَّافِذَةِ"": حَاجِزٌ، حِجَابٌ مِنْ ثَوْبٍ يُعَلَّقُ لِحَجْبِ الضَّوْءِ أوِ الأشِعَّةِ أوِ النَّظَرِ. 2. ""أُسْدِلَ السِّتَارُ عَنِ القَضِيَّةِ"" : أَيْ تَمَّ إخْفَاؤُهَا وَحَجْبُهَا. ""أزَاحَ السِّتَارَ عَنْ وَقَائِعَ تَارِيخِيَّةٍ"". 3. ""مَدَّ اللَّيْلُ سِتَارَهُ"" : اِنْتَشَرَ ظَلاَمُهُ. 4. ""سِتَارُ الْمَسْرَحِ"" : القِطْعَةُ مِنَ الثَّوْبِ تُرْفَعُ عِنْدَ البَدْءِ بِعَرْضِ الْمَسْرَحِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10235, 'سُتُرٌ', 'ستر', 'جامد', '', 'ستر', 'ستر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10236, 'سُتْرَةٌ', 'سترة', 'جامد', 'ستر', 'سترة', 'سترة', '', '', '', 'مفرد', 'DnN', '', '', '"سُتَرٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""اِرْتَدَى سُتْرَةً"" : الرِّدَاءُ الَّذِي يَسْتُرُ النِّصْفَ الأَعْلَى مِنَ الجِسْمِ وَيُسَمَّى بِالعُلُوِّ. 2.""سُتْرَةُ السَّطْحِ"" : مَا يُبْنَـى حَوْلَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10237, 'سُتَرٌ', 'ستر', 'جامد', '', 'ستر', 'ستر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10238, 'سِتْرَةٌ', 'سترة', 'جامد', 'ستر', 'سترة', 'سترة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". : لِبَاسٌ يُلْبَسُ عَادَةً فَوْقَ قَمِيصٍ، أو مَا شَابَهَ ذَلِكَ، يُغَطِّي الجُزْءَ الأعْلَى مِنَ الجِسْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10239, 'سِتْرٌ', 'ستر', 'جامد', 'ستر', 'ستر', 'ستر', '', '', '', 'مفرد', 'DnN', '', '', '"سُتُورٌ:أَسْتَارٌ:سُتُرٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""لاَ سِتْرَ لَهُ"": لاَ شَيْءَ لَهُ يُسْتَتَرُ بِهِ، أوْ يَتَغَطَّى بِهِ. 2.""هَتَكَ سِتْرَهُ"" : هَتَكَ حَيَاءهُ، أيْ كَشَفَ مَسَاوِئَهُ. 3.""لاَ سِتْرَ لَهُ"" : لاَ عَقْلَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10240, 'سُتُورٌ', 'ستور', 'جامد', '', 'ستور', 'ستر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10241, 'أَسْتَارٌ', 'أستار', 'جامد', '', 'ءستار', 'ستر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10242, 'سُتُرٌ', 'ستر', 'جامد', '', 'ستر', 'ستر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10243, 'مِسَجَّةٌ', 'مسجة', 'جامد', 'سجج', 'مسجة', 'مسجة', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَاجٌّ"', '', 'R', '', '', '', '', '', '', '".: أَدَاةٌ مِنْ خَشَبٍ أَوْ مَعْدِنٍ تُطَيَّنُ وَتُمَلَّسُ بِهَا الأَرْضُ وَالجُدْرَانُ، مالِجٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10244, 'مَسَاجٌّ', 'مساج', 'جامد', '', 'مساج', 'مسج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10245, 'سَجَّادَةٌ', 'سجادة', 'جامد', 'سجد', 'سجادة', 'سجدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"(وَاحِدَةُالسَّجَّادِ)"', '', 'R', '', '', '', '', '', '', '"سَجَّادَةٌ-سَجَّادَةٌ [س ج د] (وَاحِدَةُ السَّجَّادِ). 1.""سَجَّادَةُ الصَّلاةِ"" : حَصِيرٌ،بِسَاطٌ، زَرْبِيَّةٌ صَغِيرَةٌ أوْ مُتَوَسِّطةُ الحَجْمِ. 2. : أثَرُ السُّجُودِ فِي الجَبْهَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10246, 'سُجُودٌ', 'سجود', 'جامد', 'سجد', 'سجود', 'سجد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سُجُودٌ-سُجُودٌ [س ج د]. ""وَجَدَ الْمُصَلِّينَ سُجُوداً"" : وَاضِعِين جَبْهَتَهُمْ على الأرْضِ فِي تَعَبُّدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10247, 'مَسَاجِدُ', 'مساجد', 'جامد', 'سجد', 'مساجد', 'مسجد', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَسَاجِدُ-مَسَاجِدُ [س ج د]. ""مَسَاجِدُ جِسْمِ الإِنْسَانِ"" : مَوَاضِعُ السُّجُودِ، أَيِ الْجَبْهَةُ وَالأَنْفُ وَالرُّكْبَتَانِ وَاليَدَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10248, 'مَسْجِدٌ', 'مسجد', 'جامد', 'سجد', 'مسجد', 'مسجد', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَاجِدُ"', '', 'R', '', '', '', '', '', '', '". 1.""أَدَّى الصَّلاَةَ فِي الْمَسْجِدِ"" : بَيْتُ الصَّلاَةِ وَالعِبَادَةِ عِنْدَ الْمُسْلِمِينَ. 2.""جَامِعُ الْمَسْجِدِ الْحَرَامِ"" : جَامِعُ مَكَّةَ. 3.""الْمَسْجِدُ الأَقْصَى"" : جَامِعُ القُدْسِ. 4.""الْمَسْجِدُ النّبَوِيُّ"": جامِعُ المَدينَةِ المُنَوَّرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10249, 'مَسَاجِدُ', 'مساجد', 'جامد', '', 'مساجد', 'مسجد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10250, 'سَجْعَةٌ', 'سجعة', 'جامد', 'سجع', 'سجعة', 'سجعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""أتى سَجْعَةً فِي مَكَانِهَا"" : بِفِقْرَةٍ، بِجُمْلَةٍ مُقَفَّاةٍ، أُسْجُوعَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10251, 'سَجْعٌ', 'سجع', 'جامد', 'سجع', 'سجع', 'سجع', '', '', '', 'مفرد', 'DnN', '', '', '"أَسْجَاعٌ"', '', 'R', '', '', '', '', '', '', '". ""اِحْتَوتْ خُطْبَتُهُ عَلَى سَجْعٍ"" : كَلاَمٌ مَنْثُورٌ مُقَفّـىً لَهُ فَوَاصِلُ، جُمَلٌ مُقَفَّاةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10252, 'أَسْجَاعٌ', 'أسجاع', 'جامد', '', 'ءسجاع', 'سجع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10253, 'سِجَافٌ', 'سجاف', 'جامد', 'سجف', 'سجاف', 'سجف', '', '', '', 'مفرد', 'DnN', '', '', '"سُجُفٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""اِرْتَدَتْ فُسْتَاناً بِهِ سِجَافٌ مُزَرْكَشَةٌ"" : مَا يُطَرَّزُ عَلَى حَوَاشِي الثَّوْبِ أوِ الفُسْتَانِ. 2. ""سِجَافُ الرَّأْسِ"" : مَا يُسْتَرُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10254, 'سُجُفٌ', 'سجف', 'جامد', '', 'سجف', 'سجف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10255, 'سُجُقّ', 'سجق', 'جامد', '', 'سجق', 'سجق', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَسْجَاقٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَسْجَاقٌ. (طخ).: مِعىً مَحْشُوٌّ بِالشَّحْمِ وَاللَّحْمِ الْمَفْرُومِ وَالأفَاوِيهِ، عَلَى شَكْلِ أَصَابِعَ مِنَ الحَجْمِ الكَبيرِ يُؤْكَلُ مَشْوِيّاً أو مَقْلِيّاً أوْ قِدِّيداً أوْ مُجَفَّفاً، تُعْرَفُ بِالمِرْكَاسِ، المِرْكَازِ، وَيُطْلَقُ عَلَيْهَا أَيْضاً اِسمُ الْمَقانِقِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10256, 'أَسْجَاقٌ', 'أسجاق', 'جامد', '', 'ءسجاق', 'سجق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10257, 'سِجِلٌّ', 'سجل', 'جامد', 'سجل', 'سجل', 'سجل', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""بَحَثَ فِي سِجِلِّ العُقُودِ"" :كِتَابٌ إدَارِيٌّ تُسَجَّلُ فِيهِ الوَثَائِقُ وَالعُقُودُ وَأصْحَابُهَا وَتَوَارِيخُهَا لِحِفْظِهَا وَالرُّجُوعِ إلَيْهَا عِنْدَ الحَاجَةِ وَهِيَ أنْوَاعٌ: ""السِّجِلُّ العَدْلِيُّ""، ""السِّجِلُّ التِّجَارِيُّ""، ""السِّجِلُّ القَضَائِيُّ""، ""سِجِلُّ التَّشْرِيفَاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10258, 'سِجِّيلَةٌ', 'سجيلة', 'جامد', 'سجل', 'سجيلة', 'سجلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". : عُلْبَةٌ مُقْفَلَةٌ، بِدَاخِلِهَا شَرِيطٌمِغْنَاطِيسِيّ تُسَجَّلُ عَلَيْهِ أصْوَاتٌ أَو صُوَرٌ أوْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10259, 'سِجِّيلٌ', 'سجيل', 'جامد', 'سجل', 'سجيل', 'سجل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سِجِّيلٌ-سِجِّيلٌ [س ج ل]. 1.الفيل آية 4تَرْمِيهِمْ بِحِجارةٍ مِنْ سِجِّيلٍ (قرآن) : الطِّينُ اليَاب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10260, 'سِجْنٌ', 'سجن', 'جامد', 'سجن', 'سجن', 'سجن', '', '', '', 'مفرد', 'DnN', '', '', '"سُجُونٌ"', '', 'R', '', '', '', '', '', '', '". ""خَرَجَ مِنَ السِّجْنِ"": الْمَحْبَسُ، أَيِ الْمَكَانُ الَّذِي يُحْبَسُ فِيهِ السَّجِينُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10261, 'سُجُونٌ', 'سجون', 'جامد', '', 'سجون', 'سجن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10262, 'سَجِيَّةٌ', 'سجية', 'جامد', 'سجو', 'سجية', 'سجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":سَجَايا"', '', '', '', '', '', '', '', '', '"سَجِيَّةٌ - ج: سَجَايا، سَجِيَّاتٌ. [س ج و]. 1. ""تَرَكَهُ عَلَى سَجِيَّتِهِ"" : عَلَى طَبِيعَتِهِ.   ""التَّصَاغُرُ دَوَاءُ النَّفْسِ وَسَجِيَّةُ أَهْلِ البَصِيرَةِ فِي الدُّنْيَا والدِّينِ"".(التوحيدي). 2. ""يتَحَلَّى بِسَجَايَا نَبِيلَةٍ"" : بِأَخْلاَقٍ نَبِيلَةٍ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10263, 'سَجَايا', 'سجايا', 'جامد', '', 'سجايا', 'سج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10264, 'سَحابَةٌ', 'سحابة', 'جامد', '', 'سحابة', 'سحبة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"سَحَائِبُ(وَاحِدَةُالسَّحَابِ', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سَحابَةٌ-سَحابَةٌ (وَاحِدَةُ السَّحَابِ). ج: سَحَائِبُ. 1. ""أَطَلَّتْ سَحَابَةٌ مِنْ بَعِيدٍ"" : غَيْمَةٌ. 2. ""إِنَّهَا سَحَابَةُ صَيْفٍ"" : غَيْمَةٌ غَيْرُ مُمْطِرَةٍ، وَتُقَالُ مَجَازاً عِنْدَ حُدُوثِ أزْمَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10265, 'سَحَائِبُ', 'سحائب', 'جامد', '', 'سحاءب', 'سحب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10266, 'سَحَابٌ', 'سحاب', 'جامد', 'سحب', 'سحاب', 'سحب', '', '', '', 'مفرد', 'DnN', '', '', '"سُحُبٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""تَرَاكَمَ السَّحَابُ"": الغَيْمُ. ""هَلْ يُرْجَى مَطَرٌ بِلاَ سَحَابٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10267, 'سُحُبٌ', 'سحب', 'جامد', '', 'سحب', 'سحب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10268, 'مَسْحَبٌ', 'مسحب', 'جامد', 'سحب', 'مسحب', 'مسحب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَسْحَبٌ-مَسْحَبٌ [س ح ب]. ""مَسْحَبُ الْهَوَاءِ"" : الكُوَّةُ أَوِ الرَّدْهَةُ الَّتِي يَتَسَرَّبُ مِنْهَا الرِّيحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10269, 'سُحْتٌ', 'سحت', 'جامد', 'سحت', 'سحت', 'سحت', '', '', '', 'مفرد', 'DnN', '', '', '"أسْحَاتٌ"', '', 'R', '', '', '', '', '', '', '".""تاجِرٌ يعيشُ على السُّحْتِ"":مَا خَبُثَ وَقَبُحَ مِنَ الْمَكَاسِبِ ،الح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10270, 'أسْحَاتٌ', 'أسحات', 'جامد', '', 'ءسحات', 'سحت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10271, 'سُحَارَةٌ', 'سحارة', 'جامد', 'سحر', 'سحارة', 'سحرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سُحَارَةٌ-سُحَارَةٌ [س ح ر]. 1. : الرِّئَةُ. 2. : القَلْبُ. 3.""سُحَارَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10272, 'سُحْرَةٌ', 'سحرة', 'جامد', 'سحر', 'سحرة', 'سحرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سُحْرَةٌ - [س ح ر]. 1.: آخِرُ اللَّيْلِ قُبَيْلَ الفَجْرِ. 2.:بَيَاضٌ يَعْلُو السَّوَادَ. "', '');
