INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10303, 'سَخَّانٌ', 'سخان', 'جامد', 'سخن', 'سخان', 'سخن', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَخَّانٌ-سَخَّانٌ، ةٌ [س خ ن]. 1. ""تَرَكَ الْمَاءَ يَغْلِي فِي السَّخَّانَةِ"": إِبْرِيقٌكَبِيرٌ مِنَ الْمَعْدِنِ يُسَخَّنُ فِيهِ الْمَاءُ. 2.""سَخَّانَةُ الحَمَّامِ"" : جِهَازٌ مُكَعَّبٌ غَازِيٌّ أَوْ كَهْر"', '');
