INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10305, 'سُدَادٌ', 'سداد', 'جامد', 'سدد', 'سداد', 'سدد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَدَادٌ - [س د د]. (مص. سَدَّ). 1. ""عُرِفَ بِسَدَادِ الرَّأْيِ"": بِصَوَابِهِ وَرَشَادِهِ وَتَعقُّلِهِ وَاسْتِقَامَتِهِ. 2. ""سَدَادُ الدَّيْنِ"": قَضَاؤُهُ وَتَأْدِيَتُهُ. "', '');
