INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10315, 'سِدْرٌ', 'سدر', 'جامد', '', 'سدر', 'سدر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سِدْرٌ-سِدْرٌ (نب).: شَجَرٌ مِنْ فَصِيلَة النَّبْقِيَّاتِ، شَائِكَةٌ، خَشَبُهَا صَلْبٌ، أَشْوَاكُهَا قَوِيَّةٌ جَامِدَةٌ، تُ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10316, 'سَادِسٌ', 'سادس', 'جامد', 'سدس', 'سادس', 'سدس', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"سَادِسٌ-سَادِسٌ، ةٌ [س د س]. 1.: عَدَدٌ يَدُلُّ عَلَى التَّرْتِيبِ وَيَكُونُ مَعْدودُهُ مُذَكَّراً : ""هُوَ السَّادِسُ فِي السِّبَاقِ"" : أيْ كَانْت رُتْبَتُهُ بَيْنَ الخَامِسِ وَالسَّابِعِ، وَيُعْرَبُ نَعْتاً فِي المِثَالِ التَّالِي: ""وَصَلَ الفَائِزُ السَّادِسُ""، وَإذَا لَمْ يُذْكَرْ مَعْدُودُهُ كَما في: ""وَصَلَ السَّادِسُ"" أُعْرِبَ فَاعِلَ وَصَلَ، وإذَا قُلْتَ : ""كَلَّمْتُ السَّادِسَ"" أُعْرِبَ مَفْعُولاً ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10317, 'سِتٌّ', 'ست', 'جامد', 'سدس', 'ست', 'ست', '', '', '"Ta "', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'N', 'O', '', '"سِتٌّ-سِتٌّ، ةٌ [س د س] (أُبْدِلَتِ الدَّالُ وَالسِّينُ تَاءيْنِ وَأُدْغِمَتَا). 1.""وَصَلَتْ سِتُّ بَنَاتٍ"" : عَدَدٌ مُفْرَدٌ مَعْدُودُهُ جَمْعُ مُؤَنَّثٍ، وَالبناتُ مُضَافٌ إلَى سِتٍّ. ""قَرَأْتُ الكِتَابَ سِتَّ مَرَّاتٍ"". 2. ""سِتَّ عَشْرَةَ سَنَةً"" : عَدَدٌ مُرَكَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10318, 'سُدَاسٌ', 'سداس', 'جامد', 'سدس', 'سداس', 'سدس', '', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"سُدَاسٌ-سُدَاسٌ [س د س]. ""وَصَلُوا سُدَاسَ"" : أيْ سِتَّةً سِتَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10319, 'سُدْسٌ', 'سدس', 'جامد', 'سدس', 'سدس', 'سدس', '', '', '', 'مفرد', 'DnN', '', '', '"أَسْداسٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَخَذَ سُدْسَ الحِصَّةِ"": جُزْءاً مِنْ سِتَّةٍ. 2.""ضَ"', '');
