INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10361, 'تَسْرِيحَةٌ', 'تسريحة', 'جامد', 'سرح', 'تسريحة', 'تسرحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""أَنْجَزَتْ تَسْرِيحَةً جَدِيدَةً لِشَعْرِهَا"" : التَّمْشِيط، وَالتَّصْفِيف حَسَبَ طَرِيقَةٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10362, 'مَسْرَحٌ', 'مسرح', 'جامد', 'سرح', 'مسرح', 'مسرح', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَارِحُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""مَسْرَحُ الْمَاشِيَةِ"": مَرْعَاهَا. 2. ""مَسْرَحُ التَّمْثِيلِ"" : مَكَانٌ مُرْتَفِعٌ مَبْنِيٌّ مِنْ خَشَبٍ فِي قَاعَةٍ مُعَدَّةٍ لِأَدَاءِ تَمْثِيلِيَّاتٍ أَوْ مَقَاطِع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10363, 'مَسَارِحُ', 'مسارح', 'جامد', '', 'مسارح', 'مسرح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10364, 'مُنْسَرِحٌ', 'منسرح', 'جامد', 'سرح', 'منسرح', 'منسرح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مُنْسَرِحٌ-مُنْسَرِحٌ [س ر ح]. ""الْبَحْرُ الْمُنْسَرِحُ"" : بَحْرٌ مِنْ بُحُورِ الشِّعْرِ الْعَرَبِيِّ وَوَزْنُهُ: مُسْتَفْعِلٌنْ فَاعِلاَتُ مُفْتَعِلُنْ*مُسْتَفْعِلُنْ فَاعِلاَتُ مُفْتَعِلُنْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10365, 'سَرِيدَةٌ', 'سريدة', 'جامد', 'سرد', 'سريدة', 'سردة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". : عُقْدَةٌ مِنْ خَيْطٍ تُسْرَدُ مِنَ الصُّوفِ أَوِ القُطْنِ بِالْمَسَارِدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10366, 'مَسْرَدٌ', 'مسرد', 'جامد', 'سرد', 'مسرد', 'مسرد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَسْرَدٌ-مَسْرَدٌ [س ر د]. ""مَسْرَدُ كِتَابٍ"" : فِهْرِسٌ، قَائِمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10367, 'مِسْرَدٌ', 'مسرد', 'جامد', 'سرد', 'مسرد', 'مسرد', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"ات:مَسَارِدُ"', '', 'R', '', '', '', '', '', '', '". 1. : إِبْرَةٌ غَلِيظَةٌ وَطَوِيلَةٌ، لَهَا رَأْسٌ مَعْقُوفٌ تُسْتَخْدَمُ لِسَرْدِ الْمَلاَبِسِ ذَاتِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10368, 'مَسَارِدُ', 'مسارد', 'جامد', '', 'مسارد', 'مسرد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10369, 'سِرْدَابٌ', 'سرداب', 'جامد', '', 'سرداب', 'سردب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"سَرَادِيبُ"', '', 'R', '', '', '', '', '', '', '"ج: سَرَادِيبُ. 1. ""بُنِيَ سِرْدَابٌ فِي وَسَطِ الْمَدِينَةِ"" : نَفَقٌ تَحْتَ الأَرْضِ تَدْخُلُ فِيهِ السَّيَّارَاتُ لِتَنْفُذَ مِنْهُ إلَى الطَّرَفِ الآخَرِ. 2. ""سِرْدَابُ الدّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10370, 'سَرَادِيبُ', 'سراديب', 'جامد', '', 'سراديب', 'سردب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10371, 'سَرْدَةٌ', 'سردة', 'جامد', '', 'سردة', 'سردة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '": عُقْدَةُ خَيْطٍ تُسْرَدُ مِنَ الصُّوفِ أَوِ القُطْنِ بِالْمَسارِدِ. ن.سَريدَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10372, 'سَرْدِينٌ', 'سردين', 'جامد', '', 'سردين', 'سردن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": نَوْعٌ منَ السَّمَكِ صَغِيرُ الحَجْمِ، يُؤْكَلُ طَرِيّاً وَ يُمَلَّحُوَيُعَلَّبُ فِي عُلَبٌ، مَنْسُوبٌ إلَى جَزِيرَةِ ""سَرْدِينِيَةَ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10373, 'سَرَّاء', 'سراء', 'جامد', 'سرر', 'سراء', 'سر', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"سَرَّاء-سَرَّاء [س ر ر]. 1. ""يَعِيشُ فِي سَرَّاءِ"" : فِي عَيْشٍ رَغْدٍ، فِي مَسَرَّةٍ، فِي نِعْمَةٍ، فِي إخَاءٍ. ""يَعِيشَانِ فِي السَّرَّاءِ وَالضَّرَّاءِ"" ""الحَمْدُ لِلَّهِ الَّذِي لا يُحْمَدُ على السَّرَّاءِ والضَّرَّاءِ سِواهُ"" (المختار السُّوسي). 2. ""رَجُلٌ سَرَّاءُ"" :كَثِيرُ السُّرَى. 3.""أَرْضٌ سَرَّاءُ"" : طَيِّبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10374, 'سَرَارَةٌ', 'سرارة', 'جامد', 'سرر', 'سرارة', 'سررة', '', '', '', 'مفرد', 'DnN', '', '', '"سَرَارٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""سَرَارَةُ الأَرْضِ"" : أفْضَلُ مَوَاضِعِهَا وَأَكْرَمُهَا وَأَطْيَبُهَا. 2. ""سَرَارَةُ الحَسَبِ وَالنَّسَبِ"" : أوْسَطُهُ وَأَفْضَلُهُ. 3. ""سَرَارَةُ العَيْشِ"" : خَيْرُهُ وَأَفْضَلُهُ. 4. ""سِرٌّ بَيِّنُ السَّرَارَةِ"" : خَالِصٌ مِنْ كُلِّ شَيْءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10375, 'سَرَارٌ', 'سرار', 'جامد', '', 'سرار', 'سرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10376, 'سَرَارٌ', 'سرار', 'جامد', 'سرر', 'سرار', 'سرر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سِرَارٌ-سِرَارٌ [س ر ر]. 1. ""سِرَارُ الشَّهْرِ"" : آخِرُ لَيْلَةٍ قَمَرِيَّةٍ فِيهِ. 2.""سِرَارُ الأرْضِ"" : أوْسَطُهُ وَأفْضَلُ مَوْضِعٍ فِيهَا. 3.""سِرَارُ الكَفِّ"" : خَطٌّ فِي بَاطِنِهِ. ""سِرَارُ الوَجْهِ أوِ الجَبْهَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10377, 'سِرَارٌ', 'سرار', 'جامد', 'سرر', 'سرار', 'سرر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَرَارٌ-سَرَارٌ [س ر ر]. 1. ""سَرَارُ الشَّهْرِ"" : آخِرُ لَيْلَةٍ قَمَرِيَّةٍ فِيهِ. 2.""سَرَارُ الحَسَب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10378, 'سَرَّةٌ', 'سرة', 'جامد', 'سرر', 'سرة', 'سرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سَرَّةٌ-سَرَّةٌ [س ر ر]. ""وضَعَ سَرَّةً عَلَى قَبْرِ جَدِّهِ"" : طَاقَةً مِنَ الرَّيْحانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10379, 'سُرَّةٌ', 'سرة', 'جامد', 'سرر', 'سرة', 'سرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""سُرَّةُ البَطْنِ"" : التَّجْوِيفُ الصَّغِيرُ الْمَوْجُودُ فِي وَسَطِ البَطْنِ، وَهُوَ الرّابِطُ بَيْنَ الوَلَدِ وَأُمِّهِ في بَطْنِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10380, 'سَرَرٌ', 'سرر', 'جامد', 'سرر', 'سرر', 'سر', '', '', '', 'مفرد', 'DnN', '', '', '"أَسْرَارٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""سَرَرُ الشَّهْرِ"" : آخِرُ لَيْلَةٍ في الشَّهْرِ القََمَرِيِّ. 2. ""سَرَرُ الْمَوْلُودِ"" : مَا يُقْطَعُ مِنْ سُرَّتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10381, 'أَسْرَارٌ', 'أسرار', 'جامد', '', 'ءسرار', 'سرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10382, 'سُرُرٌ', 'سرر', 'جامد', 'سرر', 'سرر', 'سر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سُرُرٌ-سُرُرٌ [س ر ر]. 1. ""سُرُرُ الْمَوْلودِ"" : مَا يُقْطَعُ مِنْ سُرَّتِهِ. 2. ""سُرُرُ الكَفِّ أَوِ الوَجْهِ"" : أَسارِيرُهُما، خُطُوطُهُمَا. ""سُرُرُ الجَبْهَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10383, 'سُرٌّ', 'سر', 'جامد', 'سرر', 'سر', 'سر', '', '', '', 'مفرد', 'DnN', '', '', '"أَسِرَّةٌ"', '', 'R', '', '', '', '', '', '', '". ""قَطَعَتِ القَابِلَةُ سُرَّهُ"" : مَا تَقْطَعُهُ القَابِلَةُ مِنْ سُرَّةِ الطِّفْلِ عِنْدَ وِلاَدَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10384, 'أَسِرَّةٌ', 'أسرة', 'جامد', '', 'ءسرة', 'سرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10385, 'سِرٌّ', 'سر', 'جامد', 'سرر', 'سر', 'سر', '', '', '', 'مفرد', 'DnN', '', '', '"أَسْرَارٌ"', '', 'Rp', '', '', '', '', '', '', '". 1. ""يَكْتُمُ سِرَّهُ مُنْذُ سِنينَ"" : مَا يُخْفِيهِ الْمَرْءُ وَلاَ يُذِيعُهُ. ""سِرُّكَ أسِيرُكَ فإنْ نَطَقْتَ بِهِ كُنْتَ أسِيرَهُ"" (مثل) ""يُحَافِظُ عَلَى أسْرَارِ صَدِيقِهِ"". 2.""أَسْرَارُ القَلْبِ"" : خَفَايَاهُ. 3. ""يُحَافِظُ عَلَى سِرِّ المِهْنَةِ"" : تِقْنِيَتهَا وَخَفَايَاهَا. 4.""وَشْوَشَ فِي أُذْنِهِ بِكَلِمَةِ السِّرِّ"" :كَلِمَةُ الْمُرُورِ الْمُتَدَاوَلَةُ بَيْنَ فِرِيقٍ مِنَ الجُنْدِ أوْ جَمَاعَةٍ. 5.""بَقِيَ الأمْرُ سِرّاً"":خَفِيًّا', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10386, 'أَسْرَارٌ', 'أسرار', 'جامد', '', 'ءسرار', 'سرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10387, 'سَرِيرَةٌ', 'سريرة', 'جامد', 'سرر', 'سريرة', 'سررة', '', '', '', 'مفرد', 'DnN', '', '', '"سَرَائِرُ"', '', 'R', '', '', '', '', '', '', '". 1. ""أخْفَى سَرِيرَتَهُ فِي قَلْبِهِ"" : سِرَّهُ، أَيْ مَا يَكْتُمُهُ الإنْسَانُ. 2. ""وَجَدَهُ طَيِّبَ السَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10388, 'سَرَائِرُ', 'سرائر', 'جامد', '', 'سراءر', 'سرر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10389, 'سَرِيرٌ', 'سرير', 'جامد', 'سرر', 'سرير', 'سرر', '', '', '', 'مفرد', 'DnN', '', '', '"أسِرَّةٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""اِرْتَمَى فِي سَرِيرِهِ"" : فِي فِرَاشِهِ، أيْ مَا يُضْطَجَعُ عَلَيْهِ. 2. ""سَرِيرُ الْمُلْكِ"" : العَرْش، نِعمَةُ، وَعِزَّةُ الْمُلْكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10390, 'أسِرَّةٌ', 'أسرة', 'جامد', '', 'ءسرة', 'سرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10391, 'مَسَرَّةٌ', 'مسرة', 'جامد', 'سرر', 'مسرة', 'مسرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات:مَسَارُّ"', '', 'R', '', '', '', '', '', '', '". "" أَدْخَلَ الْمَسَرَّةَ عَلَى نَفْسِهِ"" : السُّرُورُ، الغِبْطَةُ، الابْتِهَاجُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10392, 'مَسَارُّ', 'مسار', 'جامد', '', 'مسار', 'مسر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10393, 'سِرَاطٌ', 'سراط', 'جامد', 'سرط', 'سراط', 'سرط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سِرَاطٌ-سِرَاطٌ [س ر ط]. ""يَتَّبِعُ السِّرَاطَ الْمُسْتَقِيمَ"" : الطَّرِيقَ السَّلِيمَ، الوَاضِحَ. الفاتحة آية 6 اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ (قرآن) والصِّراطُ لُغَةٌ في السِّراطِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10394, 'سَرَطَانٌ', 'سرطان', 'جامد', '', 'سرطان', 'سرطن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1. ""سَرَطَانُ البَحْرِ"" : حَيَوَانٌ بَحْرِيٌّ مِنَ القِشْرِيَّاتِ،عُشَارِيُّ الأَرْجُلِ، لَهُ كَلاَّبَتَانِ كَبِيرَتـانِ صَلْبَتَـانِ وَبَطْنٌ قَوِيٌّ. 2.""سَرَطَانٌ بَحْرِيٌ مُشَوَّكٌ"" : يُعْرَفُ بِأمِّ الرُّوبِيَانِ وَهُوَ مِنَ القِشْرِيَّاتِ، لَوْنُهُ أسْوَدُ مُزَرْكَشٌ بِنُقَـطٍ زُرْقٍ وَأُخْرَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10395, 'سُرْعُوبٌ', 'سرعوب', 'جامد', '', 'سرعوب', 'سرعب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سُرْعُوبٌ-سُرْعُوبٌ (حو). : حَيَوَانٌ مِنْ فَصِيلَةِ السُّرْعُوبِيَّاتِ وَهُوَ مَا يُعْرَفُ بِابْنِ عِرْسٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10396, 'سُرْعُوبِيَّاتٌ', 'سرعوبيات', 'جامد', '', 'سرعوبيات', 'سرعبت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلةٌ حَيَوَانِيَّةٌ مِنْ رُتْبَةِ اللَّوَاحِمِ تَشْمُلُ السَّمُّورَ والسُّرْعُوبَ، أَي اِبْنَ عِرْسٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10397, 'سَارِقَةٌ', 'سارقة', 'جامد', 'سرق', 'سارقة', 'سرقة', '', '', '', 'مفرد', 'DnN', '', '', '"سَوَارِقُ:مؤسَارِق"', '', 'R', '', '', '', '', '', '', '". 1.: الغُلُّ. 2.: مِسْمَارٌ فِي القَيْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10398, 'سَوَارِقُ', 'سوارق', 'جامد', '', 'سوارق', 'سرق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10399, 'سِرْكٌ', 'سرك', 'جامد', '', 'سرك', 'سرك', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَسْرَاكٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَسْرَاكٌ : مَلْعَبٌ مُسْتَدِيرٌ مُغَطّـىً، تُعْرَضُ فِيهِ ألْعَابٌ بَهْلَوَانِيَّةٌ، كَمَا تُقَدَّمُ فِيهِ بَعْضُ الحَيَوَانَاتِ الأَهْلِيَّةِ الْمُرَوَّضَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10400, 'أَسْرَاكٌ', 'أسراك', 'جامد', '', 'ءسراك', 'سرك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10401, 'سَرْمَدٌ', 'سرمد', 'جامد', '', 'سرمد', 'سرمد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""تراثٌ سَرْمَدٌ"" : دائِمٌ، مُتَّصِلٌ غَيْرُ مُنْقَطِعٍ. القصص آية 72 قُلْ أَرَأيْتُمْ إنْ جَعَلَ اللَّهُ عَلَيْكُمُ النَّهَارَ سَرْمَداً إِلَى يَوْمِ القِيَامَة (قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10402, 'سَرْمَقٌ', 'سرمق', 'جامد', '', 'سرمق', 'سرمق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سَرْمَقٌ-سَرْمَقٌ (نب).: نباتٌ مِنْ فَصِيلَةِ السَّرْمَقِيَّاتِ. بَرِّيٌّ عُشْبِيٌّ، يَكْثُرُ بِالبَسَاتِينِ وَيُؤْكَلُ مِثْلَ سَلَطَةٍ، لَهُ فَوَائِدُ طِبِّيَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10403, 'سَرْمَقِيَّاتٌ', 'سرمقيات', 'جامد', '', 'سرمقيات', 'سرمقت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"سَرْمَقِيَّاتٌ-سَرْمَقِيَّاتٌ (نب).: فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ تَتَضَمَّنُ أَنْوَاعاً وَأَجْنَاساً. مِنْهَا مَا لَهُ فَوَائِدُ طِبِّيَّةٌ، وَمِنْهَا مَا يُؤْكَلُ، وَمِنْهَا مَا هُوَ صَالِحٌ لِعلَفِ الحَيَوانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10404, 'سَرَاةٌ', 'سراة', 'جامد', 'سرو', 'سراة', 'سرة', '', '', '', 'مفرد', 'DnN', '', '', '"سَرَواتٌ"', '', 'Rw', '', '', '', '', '', '', '". 1. ""سَراةُ الفَرَسِ"" : أَعْلَى مَتْنِهِ. 2.""سَرَاةُ النَّهَارِ"" : وَقْتُ ارْتِفَاعِهِ وَوَسَطِهِ. 3.""سَرَاةُ الطَّرِيقِ"" : مُعْظَمُهُ وَوَسَطُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10405, 'سَرَواتٌ', 'سروات', 'جامد', '', 'سروات', 'سرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10406, 'سُرْوَةٌ', 'سروة', 'جامد', 'سرو', 'سروة', 'سرة', '', '', '', 'مفرد', 'DnN', '', '', '"سُرًى:سِرًى"', '', 'R', '', '', '', '', '', '', '". 1. : سَهْمٌ عَرِيضُ النَّصْلِ طَوِيلُهُ. 2.: سَهْمٌ قَصِيرٌ صَغِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10407, 'سُرًى', 'سرى', 'جامد', '', 'سرى', 'سر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10408, 'سِرًى', 'سرى', 'جامد', '', 'سرى', 'سر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10409, 'سَرِيَّةٌ', 'سرية', 'جامد', 'سرو', 'سرية', 'سرة', '', '', '', 'مفرد', 'DnN', '', '', '"سَرَايَا"', '', '', '', '', '', '', '', '', '". 1. ""سَرِيَّةُ الجُنْدِ"" : الفِرْقَةُ مِنَ الجُنْدِ. 2. ""سَرِيَّةُ المِدْفَعِيَّةِ"" : الْمُشَاةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10410, 'سَرَايَا', 'سرايا', 'جامد', '', 'سرايا', 'سر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10411, 'سَرْوٌ', 'سرو', 'جامد', '', 'سرو', 'سر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سَرْوٌ-سَرْوٌ (نب) 1.: شَجَرٌ مِنْ فَصِيلَةِ الصَّنَوْبَرِيَّاتِ، مَعْرُوفٌ مُنْذُ القِدَمِ، لَهُ شَكْلٌ جَمِيلٌ، دَائِمُ الخُضْرَةِ، يُزْرَعُ لِلتَّزْيِينِ، وَلِسياجِ الْمَزْرُوعَاتِ. ""كَأنَّهُ شَجَرَةُ سَرْوٍ سَارِحَةٌ فِي السَّحَابِ"". (ن. محفوظ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10412, 'سِرْوَالٌ', 'سروال', 'جامد', '', 'سروال', 'سرل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"سَرَاوِيلُ"', '', 'R', '', '', '', '', '', '', '"ج: سَرَاوِيلُ. : لِبَاسٌ يُغَطِّي النِّصْفَ الأسْفَلَ مِنَ الجِسْمِ، أيْ مِنَ السُّرَّةِ إلَى القَدَمَيْنِ، وَيَجْمَعُ الرِّجْلَيْنِ مُنْفَصِلَيْنِ."', ':لا جذر:لا مفرد');
