INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10435, 'سَعْتَرٌ', 'سعتر', 'جامد', '', 'سعتر', 'سعتر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَعْتَرٌ-سَعْتَرٌ (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الشَّفَوِيَّاتِ، عُشْبِيٌّ مُعَطَّرٌ، زَهْرُهُ مَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10436, 'سَاعِدٌ', 'ساعد', 'جامد', 'سعد', 'ساعد', 'سعد', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"سَوَاعِدُ"', '', 'R', '', '', '', '', '', '', '". 1.""أُصِيبَ بِكَسْرٍ فِي سَاعِدِهِ"" : مَا بَيْنَ الْمَرْفِقِ والكَفِّ. 2.""شَدَّ عَلَى سَاعِدِهِ"" : عَاوَنَهُ، آزَرَهُ، عَاضَدَهُ. ""شَمَّرَ الرِّجَالُ عَلَى سَوَاعِدِهِمْ"". 3.""كَانَ سَاعِدَهُمُ الأكْبَرَ"" : مُعَاوِنَهُمْ. 4.""يَعْتَبِرُهُ سَاعِدَهُ الأيْمَنَ"" : أَيِ الشَّخْصَ الرَّئِيسَ الَّذِي يَعْتَمِدُ عَليْهِ فِي أعْمَالِهِ. 5.""مَا لَهُمْ سَاعِدٌ يَعْتَمِدُونَهُ"" : أيْ مَا لَه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10437, 'سَوَاعِدُ', 'سواعد', 'جامد', '', 'سواعد', 'سعد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
