INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10439, 'سَواعِدُ', 'سواعد', 'جامد', 'سعد', 'سواعد', 'سعد', '', '', '', 'مفرد', '', '', '', '"مفردساعِد"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""سَواعِدُ الطَّيْرِ"" : أَجْنِحَتُها. 2.""أَمْرٌ ذُو سَواعِدَ"" : ذُو وُجوهٍ وَمَخارِجَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10440, 'تَسْعِيرَةٌ', 'تسعيرة', 'جامد', 'سعر', 'تسعيرة', 'تسعرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"تَسْعِيرَةٌ-تَسْعِيرَةٌ [س ع ر]. ""وُضِعَتْ تَسْعِيرَةٌ جَدِيدَةٌ لِكُلِّ الْمَوَادِّ الغِذ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10441, 'سُعَارٌ', 'سعار', 'جامد', 'سعر', 'سعار', 'سعر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سُعَارٌ-سُعَارٌ [س ع ر]. 1. ""اِشْتَدَّ السُّعَارُ"" : حَرُّ النَّارِ. 2.""اِشْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10442, 'سَعْرَةٌ', 'سعرة', 'جامد', 'سعر', 'سعرة', 'سعرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سَعْرَةٌ-سَعْرَةٌ [س ع ر]. 1. ""أخَذَتْهُ سَعْرَةٌ"" : السُّعَالُ. 2.""فَعَلَ ذَلِكَ فِي سَعْرَةِ شَبَابِهِ"" : فِي أوَّلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10443, 'سُعْرَةٌ', 'سعرة', 'جامد', 'سعر', 'سعرة', 'سعرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.: وَحْدَةٌ قِيَاسِيَّةٌ حَرَارِيَّةٌ، وَهِيَ الكَمِّيَّةُ اللاَّزِمَةُ لِرَفْعِ غرَامٍ وَاحِدٍ مِنَ الْمَاءِ دَرَجَةً وَاحِدَةً مِئَوِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10444, 'سُعُرٌ', 'سعر', 'جامد', 'سعر', 'سعر', 'سعر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَعَرٌ-سَعَرٌ [س ع ر] (مص. سَعِرَ).: لَوْنٌ يَمِيلُ إلَى السَّوَادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10445, 'سُعْرٌ', 'سعر', 'جامد', 'سعر', 'سعر', 'سعر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سُعْرٌ-سُعْرٌ [س ع ر]. 1. ""يَشْعُرُ بِسُعْرٍ"" : أيْ بِجُوعٍ شَدِيدٍ. 2. ""بِهِ سُعْرٌ"" : بِهِ جُنُونٌ. 3.""اِشْتَدَّ السُّعْرُ"" : الحَرَارَةُ الشَّدِيدَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10446, 'سِعْرٌ', 'سعر', 'جامد', 'سعر', 'سعر', 'سعر', '', '', '', 'مفرد', 'DnN', '', '', '"أسْعَارٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""سِعْرُ البِضَاعَةِ"" : ثَمَنُهَا، أيْ مَا يُسَاوِي بِالنَّقْدِ قِيمَتَهَا. ""اِرْتَفَعَتِ الأسْعَارُ فِي السُّوقِ فَجْأةً"". 2. ""سِعْرُ السُّوقِ"" : "', '');
