INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10448, 'مِسْعَرٌ', 'مسعر', 'جامد', 'سعر', 'مسعر', 'مسعر', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَاعِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِسْعَرُ الْحَرَارَةِ"" : جِهَازٌ يُسْتَعْمَلُ لِقِيَاسِ كَمِّيَّةِ الْحَرَارَةِ. 2.""مِسْعَرُ النَّارِ"" : مُوقِدُهَا. 3.""كَلْبٌ مِسْعَرٌ"" : مَسْعورٌ، كَلِبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10449, 'مَسَاعِرُ', 'مساعر', 'جامد', '', 'مساعر', 'مسعر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
