INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10453, 'سُعُوفٌ', 'سعوف', 'جامد', 'سعف', 'سعوف', 'سعف', '', '', '', 'مفرد', '', '', '', '"مفردسَعَف"', '', 'R', '', '', '', '', '', '', '". 1. ""تِلْكَ سُعُوفُهُ"" : طبَائِعُهُ. 2. ""سُعُوفُ البَيْتِ"" : أمْتِعَتُهُ. 3. ""اِشْتَرَى سُعُوفاً"": أقْداحاً كَبِيرَةً."', '');
