INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10486, 'سَافِنٌ', 'سافن', 'جامد', 'سفن', 'سافن', 'سفن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَافِنٌ-سَافِنٌ [س ف ن]. : عِرْقٌ فِي بَاطِنِ الصُّلْبِ طُولاً، يَتَّصِلُ بِهِ نِيَاطُ القَلْبِ، وَهُوَ مَا يُعْرَفُ بِالأَكْحَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10487, 'سِفَانَةٌ', 'سفانة', 'جامد', 'سفن', 'سفانة', 'سفنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سِفَانَةٌ-سِفَانَةٌ [س ف ن]. ""يَحْتَرِفُ السِّفَانَةَ"" : صِنَاعَةَ السُّفُنِ."', '');
