INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10533, 'سَكِنَةٌ', 'سكنة', 'جامد', 'سكن', 'سكنة', 'سكنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""وَجَدَ رَاحَةً فِي سَكِنَتِهِ"" : فِي مَسْكَنِهِ. 2.""تَرَكْتُهُمْ علَى سَكِنَاتِهِمْ"" : عَلَى أَحْوَالِ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10534, 'سَكِينَةٌ', 'سكينة', 'جامد', 'سكن', 'سكينة', 'سكنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"سَكِينَةٌ-سَكِينَةٌ [س ك ن]. 1. ""يَعِيشُ فِي سَكِينَةٍ"" : فِي طُمَأْنِينَةٍ وَوَقَارٍ وَخُشُوعٍ. 2. ""يَطْلُبُ سَكِينَتَهُ"" : رَحْمَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10535, 'سُكَيْنَةٌ', 'سكينة', 'جامد', 'سكن', 'سكينة', 'سكنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"""اِمْرأةٌسُكَيْنَةٌ"""', '', '', '', '', '', '', '', '', '"سُكَيْنَةٌ-سُكَيْنَةٌ [س ك ن]. 1. ""اِمْرأةٌ سُكَيْنَةٌ"" : خَفِيفَةُ الرُّوحِ، ظَرِيفَةٌ. 2. ""سُكَيْنَةُ"" : اِسْمُ عَلَمٍ للإنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10536, 'سِكِّينَةٌ', 'سكينة', 'جامد', 'سكن', 'سكينة', 'سكنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سِكِّينَةٌ-سِكِّينَةٌ [س ك ن]. 1. ""نَاوَلَهُ سِكِّينَةً"" : سِكِّيناً. 2.""شَعَرَ بِالسِّكِّينَةِ"" :بالر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10537, 'مَسْكَنَةٌ', 'مسكنة', 'جامد', 'سكن', 'مسكنة', 'مسكنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَسْكَنَةٌ-مَسْكَنَةٌ [س ك ن]. ""يَعِيشُ فِي مَسْكَنَةٍ"" : فِي ذُلٍّ، فِي مَهَانَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10538, 'مَسْكَنٌ', 'مسكن', 'جامد', 'سكن', 'مسكن', 'مسكن', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَاكِنُ"', '', 'R', '', '', '', '', '', '', '". ""مَسْكَنٌ جَدِيدٌ"" : بَيْتٌ، مَنْزِلُ السُّكْنَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10539, 'مَسَاكِنُ', 'مساكن', 'جامد', '', 'مساكن', 'مسكن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10540, 'مُسَكِّنٌ', 'مسكن', 'جامد', 'سكن', 'مسكن', 'مسكن', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""دَوَاءٌ مُسَكِّنٌ"" : مُهَدِّئٌ، أَيْ يُهَدِّئُ الأَعْصَابَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10541, 'سُلٌّ', 'سل', 'جامد', '', 'سل', 'سل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سُلٌّ-سُلٌّ (طب). 1.: دَاءٌ يُصِيبُ الرِّئَتَيْنِ يَشُلُّ أَنْسِجَتَهُمَا. 2.: الهُزَالُ، الضُّعْفُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10542, 'سَلاَطَةٌ', 'سلاطة', 'جامد', '', 'سلاطة', 'سلطة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سَلاَطَةٌ-سَلاَطَةٌ (طخ). : طَعَامٌ مِنَ الخُضْرَوَاتِ مِثْل الخَسِّ وَمَا شَابَهَهُ، تُحَضَّرُ بِالخَلِّ وَالزَّيْتِ وَالمِلْحِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10543, 'سُلاَمَى', 'سلامى', 'جامد', '', 'سلامى', 'سلم', '', '', '', 'جمع تكسير', 'Dy', '', '', '"سُلاَمِيَّاتٌ"', 'ممنوع من الصرف', 'R0', '', '', '', '', '', '', '"ج: سُلاَمِيَّاتٌ : عِظَامُ الأَصَابِعِ الْمُجَوَّفَةُ فِي اليَدِ وَالقَدَمِ."', ':لا جذر:لا مفرد');
