INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10545, 'أُسْلوبٌ', 'أسلوب', 'جامد', 'سلب', 'ءسلوب', 'سلب', '', '', '', 'مفرد', 'DnN', '', '', '"أَسالِيبُ"', '', 'R', '', '', '', '', '', '', '". 1.""يَمْتازُ أُسْلوبُ هَذَا الكِتابِ بِالوُضوحِ"" : طَريقَةُ كِتابَتِهِ. ""تَخْتَلِفُ أَسالِيبُ الكُتَّابِ"". 2.""أُسْلوبُهُ فِي العَمَلِ صارِمٌ"" : نَهْجُهُ، طَرِيقَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10546, 'أَسالِيبُ', 'أساليب', 'جامد', '', 'ءساليب', 'سلب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
