INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10548, 'سَلْبُوتٌ', 'سلبوت', 'جامد', '', 'سلبوت', 'سلبت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سَلْبُوتٌ-سَلْبُوتٌ (نب). : نَباتٌ عُشْبِيٌّ مِنْ فَصيلَةِ السَّلْبوتِيَّاتِ، مِنْ نَباتاتِ التَّزْي"', ':لا جذر:لا مفرد');
