INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10550, 'سَلَّةٌ', 'سلة', 'جامد', '', 'سلة', 'سلة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"سِلاَلٌ"', '', 'R', '', '', '', '', '', '', '"ج: سِلاَلٌ. 1.""مَلأَ السَّلَّةَ بِالفَواكِهِ"" : وِعَاءٌ مِنْ قَصَبٍ وَمَاشَابَهَ ذَلِكَ، القُفَّةُ. 2.""سَلَّةُ الْمُ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10551, 'سِلاَلٌ', 'سلال', 'جامد', '', 'سلال', 'سلل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
