INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10593, 'مَسْلَكٌ', 'مسلك', 'جامد', 'سلك', 'مسلك', 'مسلك', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَالِكُ"', '', 'R', '', '', '', '', '', '', '". 1.""سَارَ فِي مَسْلَكٍ وَعْرٍ"" : فِي طَرِيقٍ وَعْرٍ. ""مَسَالِكُ الأَمْصَارُ"". 2.""كُلٌّ وَمَسْلَكُهُ"" : كُلٌّ وَطَرِيقُهُ، نَهْجُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10594, 'مَسَالِكُ', 'مسالك', 'جامد', '', 'مسالك', 'مسلك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10595, 'سُلَكٌ', 'سلك', 'جامد', '', 'سلك', 'سلك', '', '', '', 'جمع تكسير', 'DnN', '', '', '"سَلَكَانٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: سَلَكَانٌ. : فَرْخُ القَطَاةِ وَالحَجَلِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10596, 'سَلَكَانٌ', 'سلكان', 'جامد', '', 'سلكان', 'سلكن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10597, 'سُلاَلَةٌ', 'سلالة', 'جامد', 'سلل', 'سلالة', 'سللة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""هُوَ مِنْ سُلاَلَةٍ عَرِيقَةٍ، في الْمَجْدِ"" : مِنْ جَماعَةٍ حافَظَتْ على عَراقَتِها، لَهَا صِفَاتٌ عَرِيقَةٌ مَوْرُوثَةٌ. 2. ""هُوَ مِنْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10598, 'مِسَلَّةٌ', 'مسلة', 'جامد', 'سلل', 'مسلة', 'مسلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""يَخِيطُ الأَكْيَاسَ بِالمِسَلَّةِ"" : الإِبْرَةُالكَبِيرَةُ تُخَاطُ بِهَا الأَكْيَاسُ مِنَ الكَتَّانِ أَوِ الخَيْشِ. 2.""ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10599, 'سَلَمٌ', 'سلم', 'جامد', 'سلم', 'سلم', 'سلم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَلَمٌ-سَلَمٌ [س ل م]. 1. ""أَعْلَنُوا السَّلَمَ"" : الاسْتِسْلامَ. ""اِنْهَزَمُوا وَلَمْ يَكُنْ أمَامَهُمْ إلاَّ السَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10600, 'مُسَلَّمَةٌ', 'مسلمة', 'جامد', 'سلم', 'مسلمة', 'مسلمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""مِنَ الْمُسَلَّمَاتِ"" : مِنَ البَدِيهِيَّاتِ، الأَوَّلِيَّاتِ، حَقَائِقُ مُقَرَّرَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10601, 'سَلْمٌ', 'سلم', 'جامد', '', 'سلم', 'سلم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أسْلُمٌ:سِلامٌ"', '', 'R', '', '', '', '', '', '', '"ج: أسْلُمٌ، سِلامٌ. 1. ""عَاشَ فِي سِلْمٍ"" : فِي طُمَأْنِينَةٍ وَرَاحَةِ بَالٍ"". 2. ""أَعْلَنُوا السِّلْمَ بَعْدَ حَرْبٍ"" : الصُّلْحَ.الأن"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10602, 'أسْلُمٌ', 'أسلم', 'جامد', '', 'ءسلم', 'سلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10603, 'سِلامٌ', 'سلام', 'جامد', '', 'سلام', 'سلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10604, 'سَلْمُونٌ', 'سلمون', 'جامد', '', 'سلمون', 'سلمن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سَلْمُونٌ-سَلْمُونٌ (حو). : سَمَكٌ مِنْ فَصِيلَةِ السَّلْمُونِيَّاتِ، رُتْبَةُالصَّابُوغِيَّاتِ، وَهُوَ مِنَ الأسْمَاكِ العَظْمِيَّةِ، بَحْرِيَّةٌ مُفْتَرِسَةٌ لاحِمَةٌ، أَنْواعُها عَدِيدَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10605, 'سَلْمونِيَّاتٌ', 'سلمونيات', 'جامد', '', 'سلمونيات', 'سلمنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"سَلْمونِيَّاتٌ-سَلْمونِيَّاتٌ (حو). : فَصيلَةُ أسْمَاكٍ مِنْها السَّلْمونُ وَالتَّرُوتَةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10606, 'سَلْوَةٌ', 'سلوة', 'جامد', 'سلو', 'سلوة', 'سلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سَلْوَةٌ-سَلْوَةٌ، سُلْوَةٌ [س ل و]. ""مُنْذُ عَرَفْتُهُ وَهُوَ فِي سَلْوَةٍ مِنَ العَيْشِ"" : فِي رَغَدٍ مِنَ العَيْشِ، فِي رَفَاهِيةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10607, 'سَلْوًى', 'سلوى', 'جامد', 'سلو', 'سلوى', 'سل', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"سَلْوىً-سَلْوىً [س ل و]. 1.""وَجَدْتُ فِي كَلِمَاتِهِ سَلْوىً"" : فِي كَلِمَاتِهِ مَا يُسَلِّيني وَيُواسِيني. 2.""سَلْوَى"" : اِسْمُ عَلَمٍ للإِناثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10608, 'مَسْلاَةٌ', 'مسلاة', 'جامد', 'سلو', 'مسلاة', 'مسلة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مَسْلاَةٌ-مَسْلاَةٌ [س ل و]. 1.""مُجَالَسَةُ الإِخْوَانِ مَسْلاَةٌ لِلْأَحْزَانِ"" : كُلُّ مَا يَبْعَثُ عَلَى السَّلْوِ. 2.""مَسْلاَةُ السَّمَرِ"" : مَكَانُ التَّسْلِيَةِ وَاللَّهْوِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10609, 'سَلُوقِيٌّ', 'سلوقي', 'جامد', '', 'سلوقي', 'سلق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R0', '', '', '', '', '', '', '": سُلاَلَةُ كِلاَبٍ يُسْتَخْدَمُ فِي الصَّيْدِ، لَهُ قَوَائِمُ طَوِيلَةٌ، نَحِيفُ الجِسْمِ، خَفِيفُ الحَرَكَةِ، سَرِيعُ الجَرْيِ. ""كَانَ كَلْبُهُ السَّلُوقِيُّ يَجْرِي خَلْفَهُ بِخِفَّةٍ وَرَشَاقَةٍ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10610, 'سَلْوَى', 'سلوى', 'جامد', '', 'سلوى', 'سل', '', '', '', 'جمع تكسير', '', '', '', '"واحدةسَلْواةٌ"', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '"سَّلْوى-السَّلْوى (حو). وَاحِدَتُهُ سَلْواةٌ. 1. : طَائِرٌ مِنْ فَصِيلَةِ التِّفْلِقِيَّاتِ،مِنْ رُتْبَةِ الدَّجَاجِيَّاتِ، مِنَ الطُّيُورِ الْمُهَاجِرَةِ، يُعْرَفُ بِسَاقَيْهِ الطَّوِيلَتيْنِ الْمُتَدَلِّيَتَيْنِ، لَوْنُهُ بُنّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10611, 'سَلْواةٌ', 'سلواة', 'جامد', '', 'سلواة', 'سلة', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10612, 'سَلًى', 'سلى', 'جامد', 'سلي', 'سلى', 'سل', '', '', '', 'مفرد', 'Dy', '', '', '"أَسْلاءٌ"', '', 'Rw', '', '', '', '', '', '', '". 1.: غِطَاءٌ رَقِيقٌ يَكُونُ فِيهِ الجَنِينُ فِي بَطْنِ أُمِّهِ. 2. ""اِنْقَطَعَ السَّلَى فِي البَطْنِ"" : إذَا بَلَغَ الأَمْرُ غَايَتَهُ وَانْقَطَعَتْ فِيهِ الحِيَلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10613, 'أَسْلاءٌ', 'أسلاء', 'جامد', '', 'ءسلاء', 'سل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10614, 'سَمَّارٌ', 'سمار', 'جامد', '', 'سمار', 'سمر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سَمَّارٌ-سَمَّارٌ (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الأَسْلِيَّاتِ، طَوِيلُ السِّيقَانِ، يَنْبُتُ فِي الأَرَاضِي الرَّطْبَةِ، تُسْتَعْمَلُ أَوْرَاقُهُ فِي صُنْعِ الحُصُرِ وَالسِّلاَلِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10615, 'سُمَّاقٌ', 'سماق', 'جامد', '', 'سماق', 'سمق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سُمَّاقٌ-سُمَّاقٌ (نب). :شَجَرٌ مِنْ فَصِيلَةِ البُطْمِيَّاتِ، مَهْدُهُ الأَصْلِيُّ مِنْطَقَةُ البَحْرِ الأبْيَضِ الْمُتَوَسِّطِ، ثَمَرُهُ شَدِيدُ الحُمُوضَةِ، تُسْتَعْمَلُ أوْرَاقُهُ دِبَاغاً، وَبُذُورُهُ تَابِلاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10616, 'سُمَّانَى', 'سمانى', 'جامد', '', 'سمانى', 'سمن', '', '', '', 'جمع تكسير', 'Dy', '', '', '"سُمَّانَيَاتنسَلْوىً"', 'ممنوع من الصرف', 'R0', '', 'N', 'O', 'O', 'O', '', '"سُمَّانَى-سُمَّانَى (حو). ج: ـات. ن. سَلْوىً."', ':لا جذر:لا مفرد');
