INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10618, 'سَمَادٌ', 'سماد', 'جامد', 'سمد', 'سماد', 'سمد', '', '', '', 'مفرد', 'DnN', '', '', '"أسْمِدَةٌ"', '', 'R', '', '', '', '', '', '', '". ""وَضَعَ السَّمَادَ بِالحَقْلِ"" : مَادَّةٌ مِن زِبْلِ الحَيَوَانَاتِ، أ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10619, 'أسْمِدَةٌ', 'أسمدة', 'جامد', '', 'ءسمدة', 'سمدة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10620, 'سَمِيدٌ', 'سميد', 'جامد', 'سمد', 'سميد', 'سمد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَمِيدٌ-سَمِيدٌ [س م د]. 1.""طَعَامٌ مِنْ سَمِيدٍ"" : طَعَامٌ مِنَ لُبَابِ الدَّقِيقِ. 2. : طَحينٌ أَبْيَضُ خَشِنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10621, 'سُمْرَةٌ', 'سمرة', 'جامد', 'سمر', 'سمرة', 'سمرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سُمْرَةٌ-سُمْرَةٌ [س م ر]. ""كَانَتْ تَعْلُو مُحَيَّاهُ سُمْرَةُ الشَّمْسِ"": اِحْمِرَارٌ يَمِيلُ إلَى سَوَادٍ مَعَ وُجُودِ بَيَاضٍ أَصْلِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10622, 'سَمَرٌ', 'سمر', 'جامد', 'سمر', 'سمر', 'سمر', '', '', '', 'مفرد', 'DnN', '', '', '"أسْمَارٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""جَاءَ لِلسَّمَرِ مَعَ زُملائِهِ"" : لِيَقْضِيَ مَعَهُمْ سَوَادَ اللَّيْلِ يَسْمُرُ مَعَهُمْ، أيْ لِيَتَحَدَّثَ مَعَهُمْ لَيْلاً. 2. ""لَيَالِي السَّمَرِ"" : اللَّيَالِي الَّتِي يَقْضِيهَا النَّاسُ فِيمَا بَيْنَهُمْ وَهُمْ يَتَحَدَّثُونَ وَيَتَنَاجَوْنَ. 3. ""سَمَرُ اللَّيْلِ"" : سَوَادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10623, 'أسْمَارٌ', 'أسمار', 'جامد', '', 'ءسمار', 'سمر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10624, 'مِسْمَارٌ', 'مسمار', 'جامد', 'سمر', 'مسمار', 'مسمر', '', '', '', 'مفرد', 'DnN', '', '', '"َسَامِيرُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""دَقَّ المِسْمَارَ فِـي اللَّوْحِ"" :وَتَدٌ دَقِيقٌ مِنْ مَعْدِنٍ، لَهُ ذَنَبٌ حَادٌّ وَرَأْسٌ مُسَطَّحٌ ، يُدَقُّ عَادَةً فِي أَطْرَافِ الخَشَبِ لِشَدِّهَا، أَوْ فِي الجُدْرَانِ لِتَعْلِيقِ أَوْ مُخْتَلِفِ الأَشْيَاءِ تَثْبِيتِها. 2.""مِسْمَارُ جُحَا"" : إِشَارَةٌ إِلَى قِصَّةِ جُحَا الَّذِي بَاعَ الدَّارَ وَاحْت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10625, 'َسَامِيرُ', 'سامير', 'جامد', '', 'سامير', 'سمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10626, 'سَمَرْمَرٌ', 'سمرمر', 'جامد', '', 'سمرمر', 'سمرمر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سَمَرْمَرٌ-سَمَرْمَرٌ، ةٌ (حو). : طَائِرٌ مِنْ فَصِيلَةِ الزَّرَازِيرِ، أسْوَدُ اللَّوْنِ، قُوتُهُ الجَرَادُ وَالجَنَادِبُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10627, 'سِمْسَارٌ', 'سمسار', 'جامد', 'سمسر', 'سمسار', 'سمسر', '', '', '', 'مفرد', 'DnN', '', '', '"سَمَاسِرَةٌ"', '', 'R', '', '', '', '', '', '', '". ""سِمْسَارُ الحَيِّ"" : الوَسِيطُ بَيْنَ صَاحِبِ البَيْتِ والْمُكْتَرِي، الوَسِيطُ بَيْنَ البَائِعِ وَالشَّارِي لإجْرَاءِ الصَّفَقَاتِ التِّجَارِيَّةِ. ""كُنَّا قَوْماً نُسَمَّى السَّمَاسِرَةَ بِالْمَدِينَة فِي عَهْدِ رَسُولِ اللَّهِ فَسَمَّانَا التُّجَّارَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10628, 'سَمَاسِرَةٌ', 'سماسرة', 'جامد', '', 'سماسرة', 'سمسرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10629, 'سِمْسِمٌ', 'سمسم', 'جامد', '', 'سمسم', 'سمسم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سِمْسِمٌ-سِمْسِمٌ (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الخَنَازِيرِيَّاتِ، زِرَاعِيٌّ لَهُ حَبٌّ صَغِيرٌ، يُسْتَخْرَجُ مِنْهُ الشَّيْرَجُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10630, 'سِمَاطٌ', 'سماط', 'جامد', 'سمط', 'سماط', 'سمط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سِمَاطٌ-سِمَاطٌ [س م ط]. ""وَضَعَتِ السِّمَاطَ عَلَى طَاوِلَةِ الأَكْلِ"" : نَسِيجٌ مِنْ ثَوْبٍ، أَوْ نَحْوِهِ يُبْسَطُ عَلَى طَاوِلَةِ الأكْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10631, 'سُمْطٌ', 'سمط', 'جامد', 'سمط', 'سمط', 'سمط', '', '', '', 'مفرد', 'DnN', '', '', '"أَسْمَاطٌ"', '', 'R', '', '', '', '', '', '', '". ""اِرْتَدَى سُمْطاً"" : ثَوْباً مِنَ الصُّوفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10632, 'أَسْمَاطٌ', 'أسماط', 'جامد', '', 'ءسماط', 'سمط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10633, 'سِمْطٌ', 'سمط', 'جامد', 'سمط', 'سمط', 'سمط', '', '', '', 'مفرد', 'DnN', '', '', '"أسْمَاطٌ"', '', 'R', '', '', '', '', '', '', '". ""سِمْطُ الْمُوَشَّحِ"" : هُوَ كُلُّ شِعْرٍ مِنْ أَشْطُرِ الدَّوْرِ، وَتَخْتَلِفُ الأَسْمَاطُ مِنْ حَيْثُ عَدَدُ الفِقْرَاتِ بَيْنَ مُوَشَّحٍ وَآخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10634, 'أسْمَاطٌ', 'أسماط', 'جامد', '', 'ءسماط', 'سمط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10635, 'سِمْطٌ', 'سمط', 'جامد', 'سمط', 'سمط', 'سمط', '', '', '', 'مفرد', 'DnN', '', '', '"سُمُوطٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""وَضَعَتْ حَوْلَ عُنُقِها سِمْطاً مِنَ اللُّؤْلُؤِ"" : قِلاَدَةً، العِقْدُ الَّذِي يَنْتَظِمُ فِيهِ اللُّؤْلُؤُ وَنَحْوُهُ. 2. ""رَجُلٌ سِمْطٌ"" : خَفِيفٌ، فَطِنٌ، أَوْ دَاهِيَةٌ فِي أَمْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10636, 'سُمُوطٌ', 'سموط', 'جامد', '', 'سموط', 'سمط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10637, 'سَامِعٌ', 'سامع', 'جامد', 'سمع', 'سامع', 'سمع', '', '', '', 'مفرد', 'DnN', '', '', '"مثنىسَّامِعَانِ-السَّامِعَانِ', '', '', '', '', '', '', '', '', '"سَّامِعَانِ-السَّامِعَانِ [س م ع]. : الأُذنانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10638, 'سمَّاعَةٌ', 'سماعة', 'جامد', 'سمع', 'سماعة', 'سمعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""رَفَعَ السَّمَّاعَةَ وَأخَذَ يُجِيبُ مُحَدِّثَهُ"" : آلَةُ الهَاتِفِ تُرْفَعُ عِنْدَمَا يَرِنُّ لِلْمُحَادَثَةِ، وَهِيَ لِلإرْسَالِ والتِقَاطِ الصَّوْتِ. 2.""وَصَلَ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10639, 'سَمْعَةٌ', 'سمعة', 'جامد', 'سمع', 'سمعة', 'سمعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سَمْعَةٌ-سَمْعَةٌ [س م ع]. 1. ""أُذُنٌ سَمْعَةٌ"" : شَدِيدَةُ السَّمْعِ. 2. ""فَعَلَ ذَلِكَ رِياءً وَسَمْعَةً"" : أَيْ لِيَكْتَسِبَ صِيتاً لِيَرَاهُ النَّاسُ وَيَسْمَعُوا بهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10640, 'سُمْعَةٌ', 'سمعة', 'جامد', 'سمع', 'سمعة', 'سمعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سُمْعَةٌ-سُمْعَةٌ [س م ع]. ""يُحَافِظُ عَلَى سُمْعَتِهِ"" : عَلَى صِيتِهِ وَذِكْرِهِ الحَسَنِ مِنْ كُلِّ مَا يُمْكِنُ أنْ يَشِينَهُ. ""مَعْرُوفٌ بِسُمْعَتِهِ الطَّيِّبَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10641, 'مَسْمَعٌ', 'مسمع', 'جامد', 'سمع', 'مسمع', 'مسمع', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَامِعُ"', '', 'R', '', '', '', '', '', '', '". 1.مَسْمَعُ الإِنْسَانِ"" : الأُذُنُ الَّتِي يَسْمَعُ بِهَا. 2.""عَلَى مَرْأىً وَمَسْمَعٍ مِنَ النَّاسِ"" : حَيْثُ كَانَ النَّاسُ يَرَوْنَ وَيَسْمَعُونَ. ""عَلَى مَسْمَعٍ مِنْهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10642, 'مَسَامِعُ', 'مسامع', 'جامد', '', 'مسامع', 'مسمع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10643, 'سَمْفُونِيَّةٌ', 'سمفونية', 'جامد', '', 'سمفونية', 'سمفنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"سَمْفُونِيَّةٌ-سَمْفُونِيَّةٌ (مو). : تَأْليفٌ مُوسِيقِيٌّ مُتَكَامِلٌ تَشْتَرِكُ فِيهِ مَجْموعَةٌ مِنَ الآلاتِ، وَيَتَكَوَّنُ مِنْ عِدَّةِ حَرَكَاتٍ، تُصَوِّرُ مُوسِيقِيّاً حَالَةً أَوْ مَعْنـىً أَوْ مَوْضُوعاً أَوْ حِكَايَةً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10644, 'سِماكٌ', 'سماك', 'جامد', 'سمك', 'سماك', 'سمك', '', '', '', 'مفرد', 'DnN', '', '', '"مثنىسماكان-السماكان"', '', 'R', '', '', '', '', '', '', '"سِّماكانِ-السِّماكانِ [س م ك]. : نَجْمَانِ نَيِّرَانِ، أحَدُهُمَا فِي الشَّمَالِ"', '');
