INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10702, 'سِنْدِيَانِيَّاتٌ', 'سنديانيات', 'جامد', '', 'سنديانيات', 'سندنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةُ البَلُّوطِيَّاتِ مِنْ ذَوَاتِ الفِلْقَتَيْنِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10703, 'سَنْطٌ', 'سنط', 'جامد', '', 'سنط', 'سنط', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سَنْطٌ-سَنْطٌ (نب). : شَجَرَةٌ مُعَمِّرَةٌ تَحْتَلُّ بِأغْصَانِهَا حَجْماً كَبِيراً وَتَنْمُو بِسُرْعَةٍ هَائِلَةٍ، أزْهَا"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10704, 'سُنْطُورٌ', 'سنطور', 'جامد', '', 'سنطور', 'سنطر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سُنْطُورٌ-سُنْطُورٌ (مو). : آلَةٌ مُوسِيقِيَّةٌ تُشْبِهُ القَانُونَ، لَهَا مِائَةُ وَتَرٍ، وَكُلُّ أرْبَعَةِ أوْتَارٍ تُطْلِقُ صَوْتاً وَاحِداً، يُنْقَرُ عَلَيْهَا بِوَاسِطَةِ مِضْرَبَيْنِ خَشَبِيَّيْنِ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10705, 'تَسْنِيمٌ', 'تسنيم', 'جامد', 'سنم', 'تسنيم', 'تسنم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَسْنِيمٌ-تَسْنِيمٌ [س ن م].: عَيْنٌ ذُكِرَ أَنَّهَا تُوجَدُ فِي الجَنَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10706, 'سَنَامٌ', 'سنام', 'جامد', 'سنم', 'سنام', 'سنم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سَنَامٌ-سَنَامٌ [س ن م]. ""سَنَامُ الجَمَلِ"" : حَدَبَةُ ظَهْرِهِ. ""لِبَعْضِ الإبِلِ سَنَامَانِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10707, 'سَنَمَةٌ', 'سنمة', 'جامد', 'سنم', 'سنمة', 'سنمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سَنَمَةٌ-سَنَمَةٌ [س ن م]. ""سَنَمَةُ النَّبْتَةِ"" : رَأْسُهَا الأعْلَى، زَهْرَتُهَا العُلْيَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10708, 'سِنٌّ', 'سن', 'جامد', 'سنن', 'سن', 'سن', '', '', '', 'مفرد', 'DnN', '', '', '"أسْنَانٌ:أسِنَّةٌ(مؤ)"', '', 'R', '', '', '', '', '', '', '". 1. ""بَرَزَتْ سِنُّ الرَّضِيعِ"" : عَظْمٌ يَنْبُتُ فِي فَكِّ الإنْسَانِ وَالحَيَوَانِ. وَبِالأسْنَانِ يُمْضَغُ الطَّعَامُ. 2. ""رَجُلٌ كَبِيرُ السِّنِّ"" : كَبِيرُ العُمْرِ. ""طَعَنَ فِي السِّنِّ"". 3. ""صَغِيرُ السِّنِّ"" : طِفْلٌ، شَابٌّ. 4.""بَلَغَ سِنَّ الرُّشْدِ"" : أصْبَحَ بَالِغاً. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10709, 'أسْنَانٌ', 'أسنان', 'جامد', '', 'ءسنان', 'سنن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10710, 'أسِنَّةٌ', 'أسنة', 'جامد', '', 'ءسنة', 'سنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10711, 'سَنَنٌ', 'سنن', 'جامد', 'سنن', 'سنن', 'سن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَنَنٌ-سَنَنٌ [س ن ن]. 1. ""نَهَجَ سَنَنَهُ"" : طَرِيقَتَهُ، مِثَالَهُ. ""بَنَوْا بُيُوتَهُمْ عَلَى سَنَنٍ وَاحِدٍ"". 2. ""سِرْ عَلَى سَنَنِكَ"" : عَلَى طَرِيقِكِ، عَلَى نَهْجِكَ، عَلَى وُجْهَتكَ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10712, 'مِسَنٌّ', 'مسن', 'جامد', 'سنن', 'مسن', 'مسن', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَانُّ"', '', 'R', '', '', '', '', '', '', '". ""يَسُنُّ السِّكِّينَ عَلَى المِسَنِّ"" : آلَةٌ يُسَنُّ بِهَا أَوْ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10713, 'مَسَانُّ', 'مسان', 'جامد', '', 'مسان', 'مسن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10714, 'سانِيَةٌ', 'سانية', 'جامد', 'سنو', 'سانية', 'سنة', '', '', '', 'مفرد', 'DnN', '', '', '"سَوانٍ"', '', '', '', '', '', '', '', '', '". 1.""حَمَلَ تِلالَ الماءِ على ظَهْرِ السَّانِيَةِ"" : النَّاقَةُ الَّتِي يُسْتَقَى عَلَيْها. 2.""شَرِبَ مِنَ السَّانِيَةِ"" : مِنَ السَّاقِيَةِ. 3.: ناعُورَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10715, 'سَوانِي', 'سواني', 'جامد', '', 'سواني', 'سن', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10716, 'سِنَّوْرٌ', 'سنور', 'جامد', '', 'سنور', 'سنر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"سَنَانِيرُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: سَنَانِيرُ. (حو). : حَيَوَانٌ مِنْ فَصِيلَةِ السِّنَّوْرِيَّاتِ، مِنْ رُتْبَةِ الضَّوَارِي اللَّوَاحِمِ، يُعْرَفُ بِالقِطِّ الوَحْشِيِّ، وَمِنْهُ مَا هُوَ ألِيفٌ، يَعِيشُ فِي الْـبُيُوتِ، وَيَصْطَادُ الفِئْرَانَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10717, 'سَنَانِيرُ', 'سنانير', 'جامد', '', 'سنانير', 'سننر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10718, 'سِنَّوْرِيَّاتٌ', 'سنوريات', 'جامد', '', 'سنوريات', 'سنرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '": فَصِيلَةٌ حَيَوَانِيَّةٌ مِنْ رُتْبَةِ اللَّوَاحِمِ تَشْمُلُ القِطَّ وَالسِّنَّوْرَ وَالأسَدَ وَالْبَبْرَ وَالنَّمِرَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10719, 'سَنُونٌ', 'سنون', 'جامد', '', 'سنون', 'سنن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": مَعْجُونٌ تُنَظَّفُ بِهِ الأسْنَانُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10720, 'سُنُونُو', 'سنونو', 'جامد', '', 'سنونو', 'سنن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سُنُونُو-سُنُونُو (حو). : حَيَوَانٌ مِنْ فَصِيلَةِ الخَطَاطِيفِ، مِنْ رُتْبَةِ العُصْفُورِيَّاتِ، قَصيرُ الرِّجْلَيْنِ، عَرِيضُ القَاعِدَةِ، دَقِيقُ النَّظَرِ، وَذَنَبُهُ يَتَشَعَّبُ شُعْبَتَيْنِ طَوِيلَتَيْنِ، سَرِيعُ الطَّيَرَانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10721, 'سُنُونُوَةٌ', 'سنونوة', 'جامد', '', 'سنونوة', 'سننة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"وَاحِدَةُالسُّنُونُو"', '', 'R', '', 'N', 'O', 'O', 'O', '', '": وَاحِدَةُ السُّنُونُو."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10722, 'سَهْبٌ', 'سهب', 'جامد', 'سهب', 'سهب', 'سهب', '', '', '', 'مفرد', 'DnN', '', '', '"سُهوبٌ"', '', 'R', '', '', '', '', '', '', '". ""رَعَتِ الْمَاشِيَةُ فِي السَّهْبِ"" : الأرْضُ البَعِيدَةُ السَّهْلَةُ. 2. ""أرْضٌ سَهْبٌ"" : فَلاَةٌ، وَاسِعَةٌ. 3. ""فَرَسٌ سَهْبٌ"" : شَدِيدُ الجَرْيِ. 4. ""مَضَى سَهْبٌ مِنَ اللَّيْلِ"" : وَقْتٌ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10723, 'سُهوبٌ', 'سهوب', 'جامد', '', 'سهوب', 'سهب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10724, 'سُهَرَةٌ', 'سهرة', 'جامد', 'سهر', 'سهرة', 'سهرة', '', '', '', 'مفرد', '', '', '', '"""رَجُلٌسُهَرَةٌ"""', '', 'R', '', '', '', '', '', '', '"سُهَرَةٌ-سُهَرَةٌ [س هـ ر]. ""رَجُلٌ سُهَرَةٌ"" : كَثِيرُ السَّهَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10725, 'سِهْلَةٌ', 'سهلة', 'جامد', 'سهل', 'سهلة', 'سهلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سِهْلَةٌ-سِهْلَةٌ [س هـ ل]. ""بِهِ سِهْلَةٌ"" : إِسْهَالُ البَطْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10726, 'سَهَامٌ', 'سهام', 'جامد', 'سهم', 'سهام', 'سهم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سُهَامٌ-سُهَامٌ [س هـ م]. ""تَمَكَّنَ مِنْهُ السُّهَامُ"" : الضُّمورُ، الضُّعْفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10727, 'سُهَامٌ', 'سهام', 'جامد', 'سهم', 'سهام', 'سهم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَهَامٌ-سَهَامٌ [س هـ م]. 1. ""اِشْتَدَّ السَّهَامُ"" : حَرُّ رِيحِ السَّمُومِ. أوْ حَرُّ وَهْجِ الصَّيْفِ. 2. ""أصَابَهُ السَّهَامُ"" : الضُّمُورُ، الضَّعْفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10728, 'سَهْمٌ', 'سهم', 'جامد', 'سهم', 'سهم', 'سهم', '', '', '', 'مفرد', 'DnN', '', '', '"أَسْهُمٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هَذا ما نَطَقَ بِهِ سَهْمُهُ"" : نَصيبُهُ وَحَظُّهُ. 2.""اِشْتَرَكَ بِعِشْرينَ سَهْماً"" : مُصْطَلَحٌ في الْمُعامَلاتِ الاقْتِصادِيَّةِ والتِّجارِيَّةِ، وَهُوَ جُزْءٌ مِنْ رَأْسِ مالٍ مُشْتَرَكٍ يَزيدُ وَيَنْقُصُ حَسَبَ رَواجِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10729, 'أَسْهُمٌ', 'أسهم', 'جامد', '', 'ءسهم', 'سهم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10730, 'سَهْمٌ', 'سهم', 'جامد', 'سهم', 'سهم', 'سهم', '', '', '', 'مفرد', 'DnN', '', '', '"سِهَامٌ"', '', 'R', '', '', '', '', '', '', '". ""أخَذَ قَوْسَهُ وَرمَاهُ بِسَهْمٍ"" : عُودٌ مُسْتقِيمٌ مِنَ الخَشَبَ يُسَوَّى فِي طَرَفِهِ نَصْلٌ يُرْمَى بِهِ مِنَ القَوْسِ، النَّبْلُ. ""اِنطَلَقَ كالسَّهْمِ لاَ يُوقِفُهُ شَيْءٌ"" ""الكَلاَمُ سَهْمٌ نَافِذٌ لاَ يُمْكِنُ رَدُّهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10731, 'سِهَامٌ', 'سهام', 'جامد', '', 'سهام', 'سهم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10732, 'سُهَا', 'سها', 'جامد', 'سهو', 'سها', 'سه', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', 'N', 'O', 'O', 'O', '', '"سُهَا - [س هـ و]. (فك). 1.: كَوْكَبٌ صَغِيرٌ خَفِيفُ الضَّوْءِ فِي بَنَاتِ نَعْشِ الكُبْرَى أوِ الصُّغْرَى. 2.""أُرِيهَا السُّهَا وَتُرِينِي القَمَرَ"" : أسْألُهَا عَنْ شَيْءٍ فَتُجِيبُنِي جَواباً لاَ عَلاَقَةَ لَهُ بِمَا أسْألُ عَنْهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10733, 'سَهْوَةٌ', 'سهوة', 'جامد', 'سهو', 'سهوة', 'سهة', '', '', '', 'مفرد', 'DnN', '', '', '"سِهاءٌ:مؤنثسَهْوٍ"', '', 'R', '', '', '', '', '', '', '". 1.""هُوَ في سَهْوَةٍ مِنْ أَمْرِهِ"" : في غَفْلَةٍ. 2.""وَضَعَتْ في السَّهْوَةِ ما لا حاجَةَ لَنا بِهِ"" : غُرْفَةٌ في سَطْحِ الحُجُراتِ الفَوْقِيَّةِ لِحِفْظِ الحاجاتِ والأَدَواتِ الَّتِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10734, 'سِهاءٌ', 'سهاء', 'جامد', '', 'سهاء', 'سه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10735, 'سُهَيْلٌ', 'سهيل', 'جامد', '', 'سهيل', 'سهل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سُهَيْلٌ - (فك). 1.""كانَ سُهَيْلٌ النَّجْمَ الوَحيدَ اللاَّمِعَ في تِلْكَ اللَّيْلَةِ مِنْ لَيالِي الصَّيْفِ"" : نَجْمٌ مِنْ أَلْمَعِ النُّجومِ بَعْدَ  الشِّعْرَى سِيرُوسَ، يُقالُ عِنْدَ طُلُوعِهِ تَنْضَجُ الفَواكِهُ وَيَنْقَضِي القَيْظُ. 2.""وَصَلَ سُهَيْلٌ في آخِرِ اللَّيْلِ"" : اسْمُ علَمٍ لِلْمُذَكَّرِ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10736, 'سَوْءةٌ', 'سوءة', 'جامد', 'سوأ', 'سوءة', 'سة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '". ""سَوْءةُ الرَّجُلِ"" : عَوْرَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10737, 'سُوءٌ', 'سوء', 'جامد', 'سوأ', 'سوء', 'س', '', '', '', 'مفرد', 'Dz', '', '', '"أَسْواءٌ"', '', 'Rz', '', '', '', '', '', '', '". 1.""عَمَلٌ يَنْطَوِي على السُّوءِ"" : على القَبيحِ. 2.""سوءُ الحَظِّ"" : تَعاسَتُهُ. 3.""خِلافٌ ناتِجٌ عَنْ سُوءِ تَفاهُمٍ"" : خِلافٌ يَنْطَوِي على فَهْمٍ أُسيءَ فَهْمُهُ وَعَلَى غَيْرِ حَقيقَتِهِ. 4.""أَقْدَمَ على العَمَلِ بِسُوءِ نِيَّةٍ"" : بِنِيَّةٍ غَيْرِ سَلِيمَةٍ، أَيْ أَقْدَمَ على ما أَقْدَمَ عَلَيْهِ مِنْ عَيْبٍ أَوْ جُرْمٍ عن عَمْدٍ. 5.""سُوءُ الظَّنِّ"" : الظَّنُّ الَّذِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10738, 'أَسْواءٌ', 'أسواء', 'جامد', '', 'ءسواء', 'س', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10739, 'مَسَاءةٌ', 'مساءة', 'جامد', 'سوأ', 'مساءة', 'مسة', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَاوِئُ"', '', 'Rz', '', '', '', '', '', '', '".: كُلُّ مَا هُوَ قَبِيحٌ فِعْلاً أَوْ قَوْلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10740, 'مَسَاوِئُ', 'مساوئ', 'جامد', '', 'مساوء', 'مس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10741, 'مَسَاوِئُ', 'مساوئ', 'جامد', 'سوأ', 'مساوء', 'مس', '', '', '', 'مفرد', '', '', '', '"مفردمَسَاءة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""مَسَاوِئُهُ كَثِيرَةٌ"" : نَقَائِصُهُ، مَعَايِبُهُ. ""مَسَاوِئُ العَمَلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10742, 'سِوارٌ', 'سوار', 'جامد', '', 'سوار', 'سر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَساوِرُ:أَسْوِرَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَساوِرُ، أَسْوِرَةٌ. ""وَضَعَتْ أَساوِرَ مِنْ ذَهَبٍ في مِعْصَمَيْها"" : حِلْيَةٌ دائِرِيَّةٌ مِنْ ذَهَبٍ، أَوْ فِضَّةٍ أَوْ مَعْدِنٍ، تَضَعُها الْمَرْأَةُ في مِعْصَمِها."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10743, 'أَساوِرُ', 'أساور', 'جامد', '', 'ءساور', 'سر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10744, 'أَسْوِرَةٌ', 'أسورة', 'جامد', '', 'ءسورة', 'سرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10745, 'سَاحَةٌ', 'ساحة', 'جامد', 'سوح', 'ساحة', 'سحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":سُوحٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِجْتَمَعَ النَّاسُ فِي السَّاحَةِ العُمُومِيَّةِ"" : مَكَانٌ وَاسِعٌ وَسَطَ بِنَاءٍ. ""سَاحَةُ الْمَدْرَسَةِ"". 2.""تَقَدَّمَ إِلَى سَاحَةِ الْمَعْرَكَةِ"" : مَيْدَانُ الْمَعْرَكَةِ، الحَلْبَةُ. 3.""بَرَّأَتِ الْمَحْكَمَةُ ساحَةَ الْمُتَّهَمِ"" : بَرَّأتْهُ مِن كُلِّ ذَنْبٍ. ""بَرِيءُ السَّاحَةِ"". 4.""نَزَلَ بِسَاحَتِهِ"" : أيْ نَزَلَ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10746, 'سُوحٌ', 'سوح', 'جامد', '', 'سوح', 'سح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10747, 'سَوادٌ', 'سواد', 'جامد', 'سود', 'سواد', 'سد', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"سَوادٌ-سَوادٌ [س و د]. 1.""تَحَوَّلَ لَوْنُ الجِدارِ إلى سَوادٍ"" : لَوْنٌ أَسْوَدُ كالفَحْمِ داكِنٌ عَكْس البَياضِ. 2.""عَرَفَ الخَبَرَ سَوادُ النّاسَ"" : أَغْلَبُهُمْ، عامَّتُهُمْ، جَميعُهُمْ. ""السَّوا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10748, 'سُودانُ', 'سودان', 'جامد', 'سود', 'سودان', 'سدن', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rp', '', 'N', 'O', 'N', 'O', '', '"سُّودانُ-السُّودانُ [س و د]. : مِنَ البُلْدانِ العَرَبِيَّةِ (الجُمْهورِيَّةُ السُّودانِيَّةُ). عاصِمَتُها الخُرْطومُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10749, 'مُسْوَدَّةٌ', 'مسودة', 'جامد', 'سود', 'مسودة', 'مسدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". ""مُسْوَدَّةُ التِّلْمِيذِ"" : مَا يَكْتُبُهُ بِقَصْدِ الْمُرَاجَعَةِ وَإِعَادَةِ التَّصْحِيح. ""مُسْوَدَّةُ مَقَالَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10750, 'سُورَةٌ', 'سورة', 'جامد', 'سور', 'سورة', 'سرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سَوْرَةٌ-سَوْرَةٌ [س و ر] (الْمَرَّةُ مِنْ سارَ). 1.""اِسْتَبَدَّتْ بِهِ سَوْرَةُ الغَضَبِ"" : شِدَّةُ الغَضَبِ. 2.""لَمْ يَجِدْ إِلاَّ كَهْفاً لِيَحْتَمِيَ بِهِ مِنْ سَوْرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10751, 'سورٌ', 'سور', 'جامد', 'سور', 'سور', 'سر', '', '', '', 'مفرد', 'DnN', '', '', '"أَسْوارٌ"', '', 'R', '', '', '', '', '', '', '". ""يُحيطُ سورٌ بِالْمَدينَةِ مِنْ عَهْدٍ قَديمٍ"" : حائِطٌ مُرْتَفِعٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10752, 'أَسْوارٌ', 'أسوار', 'جامد', '', 'ءسوار', 'سر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10753, 'سُورِيَّة', 'سورية', 'جامد', '', 'سورية', 'سرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": مِنَ البُلْدانِ العَرَبِيَّةِ بِالشَّرْقِ الأَوْسَطِ. (الج"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10754, 'سوسَةٌ', 'سوسة', 'جامد', 'سوس', 'سوسة', 'سسة', '', '', '', 'مفرد', 'DnN', '', '', '"واحدةالسُّوسِ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سوسَةٌ-سوسَةٌ [س و س]. : واحِدَةُ السُّوسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10755, 'سُوسٌ', 'سوس', 'جامد', 'سوس', 'سوس', 'سس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سُوسٌ-سُوسٌ [س و س]. 1.""أَفْسَدَ السُّوسُ القَطانِيَّاتِ الْمَوْجودَةَ في الْمَخْزَنِ"" : دودٌ مِنْ مُغْمَداتِ الأَجْنِحَةِ يَنْخَرُ أَنْواعَ القَطانِيَّاتِ مِنْ فولٍ وَحِمَّصٍ وَعَدَسٍ.. وَالصُّوفَ والثِّيابَ والخَشَبَ. 2. : نَباتٌ مِنْ فَصيلَةِ القَرْنِيَّاتِ، "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10756, 'سَوْسانٌ', 'سوسان', 'جامد', '', 'سوسان', 'سسن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ن. سَوْسَنٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10757, 'سَوْسَنٌ', 'سوسن', 'جامد', '', 'سوسن', 'سسن', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": نَباتٌ مِنْ فَصيلَةِ السَّوْسَنِيَّاتِ، طَيِّبُ الرَّائِحَةِ، أَنْواعُهُ كَثيرَةٌ جَميلَةُ اللَّوْنِ، بَنَفْسَجِيَّةٌ وَبَيْضاءُ وَصَفْراءُ، مِنْهُ ما هُوَ زِراعِيٌّ، تُسْتَخْرَجُ مِنْ جُذورِهِ مَوادُّ طِبِّيَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10758, 'سَوْسَنِيّاتٌ', 'سوسنيات', 'جامد', '', 'سوسنيات', 'سسنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصيلَةٌ نَباتِيَّةٌ مِنَ وَحِيدَاتِ الفِلْقَةِ، أنواعُها عديدةٌ، مِن أشْهَرِها: السَّوْسَنُ والزّعْفرانُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10759, 'سُوسيّات', 'سوسيات', 'جامد', '', 'سوسيات', 'سست', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَة حَشرات، مِنَ غِمْدِيّات الأجْنِحَة. أنواعُها لاَ حَصْرَ لها. تَنْتَشِرُ بَيْنَ مُخْتَلِفِ الأعْضاءِ والنّباتاتِ والحيواناتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10760, 'سِياطٌ', 'سياط', 'جامد', 'سوط', 'سياط', 'سط', '', '', '', 'مفرد', 'DnN', '', '', '"سَوْطٌ"', '', 'R', '', '', '', '', '', '', '". ""جَلَدُوهُ بِالسِّياطِ"" : ما يُضْرَبُ بِهِ مِنْ جِلْدٍ. ""أَمَرَ بِجَلْدِي فَجُلِدْتُ بِسِياطٍ مِنَ الْمَرَسِ"". (جبران خ. جبران)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10761, 'سَوْطٌ', 'سوط', 'جامد', '', 'سوط', 'سط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10762, 'سَاعَةٌ', 'ساعة', 'جامد', 'سوع', 'ساعة', 'سعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""فِي هَذِهِ السَّاعَةِ"" : في هَذَاالوَقْتِ، فِي هَذِهِ اللَّحْظَةِ. ""مَنْ لَمْ يَذُقْ مُرَّ التَّعَلُّمِ سَاعةً تَجَرَّعَ ذُلَّ الجَهْلِ طَوَالَ حَيَاتِهِ"". 2.""اِنْتَظَرْتُ سَاعَةً"" : أيْ سِتِّينَ دَقِيقَةً. ""اِسْتَغْرَقَ الدَّرْسُ سَاعةً"". 3.""مِنْ سَاعَتِهِ"": فَوْراً، حَالاً. 4.""حَتَّى السَّاعَةِ لَمْ يَأْتِ"" : إلَى حَدِّ الآنَ. 5.""رَجُلُ السَّاعَةِ"" : الرَّجُلُ الَّذِي يَصِيرُ مِحْوَرَ اهْتِمَامٍ. 6.""سَاعَتَئِذٍ"" : مُرَكَّبَةٌ مِنَ الاسْمِ ""سَاعَة"" وَ ""إذ"" وَالتَّنْوِينُ فِيهَا تَنْوِينُ عِوَضٍ. 7.""إنَّهَا عَلاَمَاتُ السَّاعَةِ"" : القِيامَةُ.الأحزاب آية 63يَسْألُكَ النَّاسُ عَنِ السَّاعَةِ قُلْ إنَّمَا عِلْمُهَا عِنْدَ اللَّهِ (قرآن). 8.""هُوَ فِي سَاعَتِهِ الأَخِـيرَةِ"" : أيْ فِـي اللَّحَظَـاتِ الأَخِيرَةِ مِنْ حَيَاتِهِ. 9.""نَظَرَ إلَى سَاعَتِهِ اليَدَوِيَّةِ"" : آلَةٌ يُعْرَفُ بِها الوَقْتُ ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10763, 'مَسَافَةٌ', 'مسافة', 'جامد', 'سوف', 'مسافة', 'مسفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""مَسَافَةٌ طَوِيلَةٌ"" : خَطٌّ، طَرِيقٌ مَا بَيْنَ نُقْطَتَيْنِ مُتَبَاعِدَتَيْنِ. 2.""عَلَى مَسَافَةِ عَشْرِ كِيلُومِتْرَاتٍ"" : عَلَى بُعْدِ. 3.""يَتَطَلَّبُ الوُصُولُ إِلَى الْمَدِينَةِ مَسَافَةَ يَوْمٍ"" : أَيْ بُعْدُ أَرْضٍ يَقْتَضِي سَفَرَ يَوْمٍ. ""مَسَافَةُ أُسْبُوعٍ"" ""مَسَافَةُ شَهْرٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10764, 'سُوفِياتٌ', 'سوفيات', 'جامد', '', 'سوفيات', 'سفت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": كَلِمَةٌ روسِيَّةٌ تَعْنِي الْمَجالِسَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10765, 'سَاقٌ', 'ساق', 'جامد', 'سوق', 'ساق', 'سق', '', '', '', 'مفرد', 'DnN', '', '', '"سُوقٌ:سِيقَانٌ(مؤ)"', '', 'R', '', '', '', '', '', '', '". 1.""رَفَعَ سَاقَهُ"" : مَا بَيْنَ الكَعْبَةِ والرُّكْبَةِ. 2.""سَاقُ سُنْبُلَةٍ"" : القَشَّةُ الْمُجَوَّفَةُ الْمُنْتَصِبَةُ، وَهِيَ المِحْوَرُ الأصْلِيُّ لِكُلِّ النَّبَاتَاتِ الْمُجَوَّفَةِ. 3.""سَاقُ الشَّجَرَةِ"" : جِذْعُهَا. 4.""اِسْتَمَرَّتِ الأعْمَالُ على قَدَمٍ وَساقٍ"" : أَيْ فِي حَرَكَةٍ مُتَزَايِدَةٍ"". 5. شَمَّرَ عَنْ سَاقِهِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10766, 'سُوقٌ', 'سوق', 'جامد', '', 'سوق', 'سق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10767, 'سُوقٌ', 'سوق', 'جامد', '', 'سوق', 'سق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10768, 'سِياقَةٌ', 'سياقة', 'جامد', 'سوق', 'سياقة', 'سقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سِياقَةٌ-سِياقَةٌ [س و ق]. ""شَهادَةُ السِّياقَةِ"" : مَعْرِفَةُ قِيادَةِ السَّيَّاراتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10769, 'سِواكٌ', 'سواك', 'جامد', 'سوك', 'سواك', 'سك', '', '', '', 'مفرد', 'DnN', '', '', '"سُوكٌ"', '', 'R', '', '', '', '', '', '', '". ""يُنَظِّفُ أَسْنانَهُ بِالسِّواكِ"": عودٌ مِنْ شَجَرِ السِّواكِ، عودُ الأَرَكِ، لَهُ رائِحَةٌ طَيِّبَةٌ تُنَظَّفُ بِهِ الأَسْنانُ. السِّواكُ مَطْهَرَةٌ لِلفَمِ (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10770, 'سُوكٌ', 'سوك', 'جامد', '', 'سوك', 'سك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10771, 'مِسْوَاكٌ', 'مسواك', 'جامد', 'سوك', 'مسواك', 'مسك', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَاوِيكُ"', '', 'R', '', '', '', '', '', '', '". ""لاَ يُفَارِقُهُ المِسْوَاكُ صَبَاحَ مَسَاءَ"" : العُودُ الْمَأْخُوذُ مِنْ شَجَرِ الأَرَاكِ تُنَظَّفُ بِهِ الأسْنَانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10772, 'مَسَاوِيكُ', 'مساويك', 'جامد', '', 'مساويك', 'مسك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10773, 'سَامٌ', 'سام', 'جامد', 'سوم', 'سام', 'سم', '', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"سَامٌ-سَامٌ [س و م]. 1.""سامُ الذَّهَبِ أوِ الفِضَّةِ"" : عُرُوقُهما فِي الحَجَرِ وَالْمَعْدِنِ، أو سَبِيكَةٌ مِنْ سبَائِكِهَا. 2.: الْمَوْتُ. 3.:خَيْزُرَانٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10774, 'سَائِمَةٌ', 'سائمة', 'جامد', 'سوم', 'ساءمة', 'سمة', '', '', '', 'مفرد', 'DnN', '', '', '"سَوَائِمُ"', '', 'R', '', '', '', '', '', '', '". ""مَاشِيَةٌ سَائِمَةٌ"" : كُلُّ مَاشِيَةٍ تُرْسَل للرَّعْيِ وَلاَ تُعْلَفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10775, 'سَوَائِمُ', 'سوائم', 'جامد', '', 'سواءم', 'سم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10776, 'سَوامٌ', 'سوام', 'جامد', 'سوم', 'سوام', 'سم', '', '', '', 'مفرد', 'DnN', '', '', '"سَوائِمُ"', '', 'R', '', '', '', '', '', '', '". : الماشِيَةُ والإِبِلُ الرَّاعِيَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10777, 'سَوائِمُ', 'سوائم', 'جامد', '', 'سواءم', 'سم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10778, 'سُومَةٌ', 'سومة', 'جامد', 'سوم', 'سومة', 'سمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سُومَةٌ-سُومَةٌ [س و م]. ""سُومَةُ السِّلْعَةِ"" : عَلامَتُها الْمُمَيِّزَةُ لَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10779, 'سِيماءٌ', 'سيماء', 'جامد', 'سوم', 'سيماء', 'سم', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"سِيماءٌ-سِيماءٌ [س و م]. ""فِعْلُهُ مِن سِيمائِهِ"" : مِنْ عَلامَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10780, 'سِيمَةٌ', 'سيمة', 'جامد', 'سوم', 'سيمة', 'سمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"سِيمَةٌ-سِيمَةٌ [س و م]. 1.""وَصَلَ وَسيمَةُ الغَضَبِ على مُحَيَّاهُ"": عَلامَةُ، سِمَةُ. 2.""سِيمَةُ السِّلْعَةِ"" : عَلامَتُها الْمُمَيِّزَةُ لَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10781, 'سَواءٌ', 'سواء', 'جامد', 'سوي', 'سواء', 'س', '', '', '', 'مفرد', 'Dz', '', '', '"أَسْواءٌ:سَواسِيَةٌعلىغَيْرِق', '', '', '', '', '', '', '', '', '"سَواءٌ - ج: أَسْواءٌ، سَواسِيَةٌ على غَيْرِ قِياسٍ. [س و ي]. 1.""هُمْ على حَدٍّ سَواءٌ"" : لاَ فَرْقَ بَيْنَهُمْ. 2.""هُما في هَذا سَواءٌ"" : أَيْ مَثِيلاَنِ، شَبيهانِ. 3.""يَأْمُلُ أَنْ يَهْدِيَهُ سَواءَ السَّبيلَ"" : الطَّريقَ الْمُسْتَقيمَ، ما اسْتَقامَ مِنْهُ. 4.آل عمران آية 64 تَعالَوْا إلى كَلِمَةٍ سَواءٍ بَيْنَنا وَبَيْنَكُمْ (قرآن) : كَلِمَةُ عَدْلٍ. 5.""مَكانٌ سَواءٌ"" : مُسْتَوٍ طولُهُ وَعَرْضُهُ.   ""غُرْفَةٌ سَواءٌ وَزَرْبِيَّةٌ سَواءٌ"". 6.""لَقِيَتْهُ في سَواءِ النَّهارِ"" : في مُنْتَصَفِهِ، في وَسَطِهِ. 7.""إِذا كانَ بَعْدَ ""سَواء"" هَمْزَةُ التَّسْوِيَةِ، فَلا بُدَّ مِن ""أم"" مَعَ الكَلِمَتَيْنِ اسْمَيْنِ كانَتِ الكَلِمَتانِ أَمْ فِعْلَيْنِ : ""سَواءٌ عَلَيَّ أَسَعْدٌ حَضَرَ أَمْ عادِلٌ""، ""سَواءٌ عَلَيَّ أَدَخَلْتَ أَمْ خَرَجْتَ"". وَإِذَا كان بَعْدَها فِعْلانِ بِغَيْرِ هَمْزَةِ التَّسْوِيَةِ عُطِفَ الثّانِي بِـ أَو : ""سواءٌ علَيَّ دَخَلْتَ أَوْ خَرَجْتَ"". وَإِذا كانَ بَعْدَها مَصْدَرانِ عُطِفَ الثّانِي بِالواوِ أو بِـ أَوْ: ""سَواءٌ عَلَيَّ دخولُكَ وَخُروجكَ"" و ""دُخولُكَ أو خُروجُكَ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10782, 'أَسْواءٌ', 'أسواء', 'جامد', '', 'ءسواء', 'س', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
