INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10784, 'سَيالٌ', 'سيال', 'جامد', '', 'سيال', 'سل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سَيالٌ-سَيالٌ (نب). : شَجَرٌ مِنْ فَصيلَةِ القَرْنِيَّاتِ شائِكٌ، لَهُ قِشْرٌ أَحْمَرُ، يُسْتَعْمَلُ في الدِّباغَةِ، أَغْصانُهُ مُلْسٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10785, 'سِياجٌ', 'سياج', 'جامد', 'سيج', 'سياج', 'سج', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَسْياجٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَحاطَ الحَديقَةَ بِسِياجٍ"" : ما يُحاطُ بِها مِنْ حائِطٍ أَوْ شَوْكٍ.. 2.""سِياجُ ال"', '');
