INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10792, 'سَيَّاراتٌ', 'سيارات', 'جامد', 'سير', 'سيارات', 'سرت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"(فك).: أَجْرامٌ سَماوِيَّةٌ تَدورُ حَوْلَ الشَّمْسِ على مَسافَةٍ أَبْعَدَ مِنْ مَسافَةِ الأرْضِ والْمِرِّيخِ وَالْمُشْتَرِي وَزُحُلَ وَأورَانُو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10793, 'سَيَّارَةٌ', 'سيارة', 'جامد', 'سير', 'سيارة', 'سرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '". ""اِنْطَلَقَتِ السَّيَّارَةُ"" : القافِلَةُ . 1.يوسف آية 19(وَجاءتْ سَيَّارَةٌ فَأَرْسَلُوا وارِدَهُمْ (قرآن).2.""يَسوقُ السَّيَّارَةَ"" : مَر"', '');
