INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10799, 'سَيْفٌ', 'سيف', 'جامد', '', 'سيف', 'سف', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَسْيافٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"سَيْفٌ-سَيْفٌ (حو). ج: أَسْيافٌ. 1. : سَمَكٌ بَحْرِيٌّ مِنْ فَصيلَةِ السَّيْفِيّاتِ،ن: أبو سَيْف. 2. (فك): ثَلاثَةُ كَواكِبَ. 3.""سَيْفُ الغُرابِ"" (نب) : ن"', ':لا جذر:لا مفرد');
