INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10804, 'سِينارْيُو', 'سيناريو', 'جامد', '', 'سيناريو', 'سنر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"""السِّنارْيُو السِّينَمائِيّ أَوِ الْمَسْرَحِيُّ"" : أَيِ النَّصُّ السِّينَمَائِيّ أَو الْمَسْرَحِيُّ الْمُتَضَمِّنُ لِتَعْلِيماتِ الْمُخْرِجِ وَلِحَرَكاتِ الْمُمَثِّلينَ وَأَجْواءِ أَداءِ أَدْوارِهِمْ مِنْ حَيْثُ الْمَناظِرُ والإِضاءةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10805, 'سِينَما', 'سينما', 'جامد', '', 'سينما', 'سنم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '"1 : فَنُّ التَّصْويرِ الْمُسَجَّلِ بِواسِطَةِ الصِّوارَةِ (كاميرا) حيثتُصْبِحُ الْمادَّةُ الْمُصَوَّرَةُ مُتَحَرِّكَةً على الشاشة أمام النّظارةِ. 2.""قاعَةُ السِّينِما"" : قاعَةٌ تَعرِضُ الأَفْلامَ على شاشَةٍ كَبيرَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10806, 'سينماتوغراف', 'سينماتوغراف', 'جامد', '', 'سينماتوغراف', 'سنمتغرف', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', 'N', 'O', 'N', 'O', '', '": جِهازٌ يَعْكِسُ الصُّوَرَ الْمُتَحَرِّكَةَ على الشَّاشَةِ أَمامَ النّظارةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10807, 'شُؤْبُوبٌ', 'شؤبوب', 'جامد', 'شأبب', 'شءبوب', 'شبب', '', '', '', 'مفرد', 'DnN', '', '', '"شَآبِيبُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1. ""شَآبِيبُ الْمَطَرِ"" : القَطَرَاتُ الأُولَى مِنَ الْمَطَرِ. 2.""أنْزَلَ اللَّهُ عَلَيْهِ شآبِيبَ رَحْمَتِهِ"" : غَمَرَهُ بِعَفْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10808, 'شَآبِيبُ', 'شآبيب', 'جامد', '', 'شءءبيب', 'شآبب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10809, 'شَابِلٌ', 'شابل', 'جامد', '', 'شابل', 'شبل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَابِلٌ-شَابِلٌ (حو). 1.""سَمَكُ الشَّابِلِ"" : نَوْعٌ مِنَ السَّمَكِ مِـنْ فَصِيلَةِ الصَّابُوغِيَّاتِ،كَبِيرُ الحَجْمِ، لَحْمُهُ لَذِيذٌ. 2.""فَتـىً شَابِلٌ"" : فَتـىً غَضٌّ مُمْتَلِئٌ فُتُوَّةً وَصِحَّةً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10810, 'شَادِنٌ', 'شادن', 'جامد', '', 'شادن', 'شدن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"شَوادِنُ"', '', 'R', '', '', '', '', '', '', '"ج: شَوادِنُ : الظَّبْيُ الصَّغِيرُ، أيْ وَلَدُ الظَّبْيَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10811, 'شَوادِنُ', 'شوادن', 'جامد', '', 'شوادن', 'شدن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10812, 'شَاشِيَةٌ', 'شاشية', 'جامد', '', 'شاشية', 'ششة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"""وضَعَ عَلَى رَأْسِهِ شَاشِيَةً"" : غِطَاءً لِلرَّأْسِ مِنْ صُوفٍ، الطَّاقِيَّةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10813, 'شَاطِئٌ', 'شاطئ', 'جامد', '', 'شاطء', 'شط', '', '', '', 'جمع تكسير', 'Dz', '', '', '"شَواطِئُ:شُطآنٌ"', '', 'Rz', '', '', '', '', '', '', '"ج: شَواطِئُ، شُطآنٌ. 1.""شاطِئُ النَّهْرِ"" : جَانِبُهُ، ضِفَّتُهُ. 2.""يَرْحَلُ كُلَّ صَيْفٍ إلَى شاطِئِ البَحْرِ"": سَاحِلُهُ، ضِفَافُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10814, 'شَواطِئُ', 'شواطئ', 'جامد', '', 'شواطء', 'شط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10815, 'شُطآنٌ', 'شطآن', 'جامد', '', 'شطءءن', 'شطآن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10816, 'شَأْفَةٌ', 'شأفة', 'جامد', 'شأف', 'شءفة', 'شفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"شَأْفَةٌ-شَأْفَةٌ [ش أ ف]. 1. ""أصَابَتْهُ الشَّأْفَةُ"" : القُرْحَةُ تَخْشُنُ فَتُسْتَأْصَلُ بِالكَيِّ. 2.""اِسْتَأْصَلَ اللَّهُ شَأْفَتَهُمْ"" : أزَالَهُمْ مِنْ أَصْلِهِمْ، قَطَعَ دَابِرَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10817, 'شَاقُوفٌ', 'شاقوف', 'جامد', '', 'شاقوف', 'شقف', '', '', '', 'جمع تكسير', 'DnN', '', '', '"شواقيفُ"', '', 'R', '', '', '', '', '', '', '"ج: شواقيفُ. ""يَشُقُّ الحِجَارَةَ بِالشَّاقُوفِ"" : مِطْرَقَةٌ ضَخْمَةٌ تُقْطَعُ بِهَا الحِجَارَةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10818, 'شواقيفُ', 'شواقيف', 'جامد', '', 'شواقيف', 'شقف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10819, 'شَاقُولٌ', 'شاقول', 'جامد', '', 'شاقول', 'شقل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"شَوَاقِيلُ"', '', 'R', '', '', '', '', '', '', '"ج: شَوَاقِيلُ. : مِيزَانُ البَنَّائِينَ وَالْمُهَنْدِسِينَ لِلتَّأَكُّدِ مِن اسْتِقَامَةِ الحَائِطِ، وَهُوَ عِبَارَةٌ عَنْ خيْطٍ فِي أسْفَلِهِ ثِقْلٌ، المِطْمَارُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10820, 'شَوَاقِيلُ', 'شواقيل', 'جامد', '', 'شواقيل', 'شقل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10821, 'شُؤْمٌ', 'شؤم', 'جامد', 'شأم', 'شءم', 'شم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شُؤْمٌ-شُؤْمٌ [ش أ م]. 1.""حَيَاةُ شُؤْمٍ"" : حَيَاةُ شَرٍّ. 2.""يَجْلُبُ الشُّؤْمَ"" : النَّحْسَ، خِلاَفُ اليُمْن."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10822, 'مَشْأَمَةٌ', 'مشأمة', 'جامد', 'شأم', 'مشءمة', 'مشمة', '', '', '', 'مفرد', 'DnN', '', '', '"مَشَائِمُ"', '', 'R', '', '', '', '', '', '', '". 1.""حَلَّتْ بِهِ الْمَشْأَمَةُ"": الشُّؤْمُ، النَّحْسُ، الشَّرُّ. 2.الواقعة آية 9 وَأَصْحَابُ الْمَشْأَمَةِ مَا أَصْحَابُ الْمَشْأَمَةِ (قرآن) : جِهَةُ الشِّمَالِ، اليَسَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10823, 'مَشَائِمُ', 'مشائم', 'جامد', '', 'مشاءم', 'مشم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10824, 'شَامَةٌ', 'شامة', 'جامد', '', 'شامة', 'شمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. 1. ""شَامَتُهَا تُضْفِي علَيْهَا جمَالاً وَلُطْفاً"" : الخَالُ، أيْ نُقْطَةٌ سَوْدَاءُ فِي الوَجْهِ أوْ فِي البَدَنِ مُطْلَقاً. 2.""شامَةُ"" : اِسْمُ عَلَمٍ لِلإنَاثِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10825, 'شَأْنٌ', 'شأن', 'جامد', 'شأن', 'شءن', 'شن', '', '', '', 'مفرد', 'DnN', '', '', '"شُؤُونٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""كَانَ لَهُ شَأْنٌ كَبِيرٌ"" : مَكَانَةٌ، رِفْعَةٌ. ""رَفِيعُ الشَّأْنِ"" ""أعْرِفُهُ رَجُلاً ذَا شَأْنٍ عَظِيمٍ"" ""رَجُلٌ مِنْ ذَوِي الشَّأْنِ"". 2. ""دَعْهُ وَشَأْنَهُ"" : دَعْهُ وَأمْرَهُ. ""دَعْنِي وَشَأْنِي"". 3.""لاَ شَأْنَ لِي بِهَذَا الْمَوْضُوعِ"": لاَ دَخْلَ لِي فِيهِ. 4.""مَا شَأْنُكَ وَمَا شَأْنُهَا "" : مَا حَالُكَ وَح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10826, 'شُؤُونٌ', 'شؤون', 'جامد', '', 'شءون', 'شن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10827, 'شُؤُونٌ', 'شؤون', 'جامد', 'شأن', 'شءون', 'شن', '', '', '', 'مفرد', '', '', '', '"مفردشَأْنٌ"', '', 'R', '', '', '', '', '', '', '". 1.""شُؤُونُ العَيْنِ"": مَجَارِيهَا الدَّمْعِيَّةُ. 2.""شُؤُونُ النَّاسِ"" : حَالاَتُهُمْ، قَضَايَاهُمْ، أُمُورُهُمْ. ""لاَ يَتَدخَّلُ فِي شُؤُونِ الآخَرِينَ"" ""شُؤُونُ العُمَّالِ"". 3.""وِزَارَةُ الشُّؤُونِ الثَّقَافِيَّةِ"" : الوِزَارَةُ الَّتِي تَهْتَمُّ بِقَضَايَا الثَّقَافَةِ. ""وِزَارَةُ الشُّؤُونِ الاجْتِمَاعِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10828, 'شَاهٌ', 'شاه', 'جامد', '', 'شاه', 'شه', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1.: مَلِكُ الفُرْسِ سَابِقاً. 2.: قِطْعَةٌ مِنْ قِطَعِ رُقْعَةِ الشِّطْرَنْجِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10829, 'شَاهِينُ', 'شاهين', 'جامد', '', 'شاهين', 'شهن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"شَوَاهِينُ:شياهِينُ"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"ج: شَوَاهِينُ، شياهِينُ. (حو). 1.: طَائِرٌ مِنْ فَصِيلَةِ الصَّقْرِيَّاتِ، مِنْ رُتْبَةِ الصَّقْرِيَّاتِ، مِنَ الجَوَارِحِ، طَوِيلُ الجَنَاحَيْنِ، قَوِيُّ البِنْيَةِ. 2.: عَمُودُ المِيزَانِ. 3.: اِسْمُ عَلَمٍ لِلْمُذَكَّرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10830, 'شَوَاهِينُ', 'شواهين', 'جامد', '', 'شواهين', 'شهن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10831, 'شياهِينُ', 'شياهين', 'جامد', '', 'شياهين', 'شهن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10832, 'شَاوَرْمَةٌ', 'شاورمة', 'جامد', '', 'شاورمة', 'شرمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"شَاوَرْمَةٌ-شَاوَرْمَةٌ (طبخ).""شَطِيرَةُ شَاوَرْمَةٍ"" : لَحْمٌ يُوضَعُ فِي سَفُّودٍ كَبِيرٍ يَنْضَجُ عَلَى وَهَجِ النَّارِ وَيُقَطَّعُ بعد ذَلِكَ قِطَعاً صِغاراً، وَهِيَ أَكْلَةٌ سَائِدَةٌ بِالشَّرْقِ العَرَبِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10833, 'شَاوِيشٌ', 'شاويش', 'جامد', '', 'شاويش', 'شش', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""اِلْحَقْنِي يَا شَاويشُ"" : رُتْبَةٌ عَسْكَرِيَّةٌ دُونَ الضَّابِطِ، تُوازِي ""رَقِيب""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10834, 'شَايٌ', 'شاي', 'جامد', '', 'شاي', 'ش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"(نب).: شَجَرَةٌ مِنْ فَصِيلَةِ الكَامِيلِيَّاتِ خَضْرَاءُ، لَهَا أزْهَارٌ بِيضٌ، تُعْطِي أَوْرَاقاً، يُحَضَّرُ مِنْهَا شَرَابُ الشَّايِ، وَهُوَ مَادَّةٌ مُنَبِّهَةٌ، تُغْلَى بِالْمَاءِ وتُشْرَبُ، مَهْدُهَا الأصْلِيُّ الشَّرْقُ الأقْصَى. ""تَنَاوَلَ كَأسَ شَايٍ"" ""شَايٌ أخْضَرُ"" ""شَايٌ أسْوَدُ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10835, 'شُبَاطٌ', 'شباط', 'جامد', '', 'شباط', 'شبط', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ الثَّانِي مِنَ السَّنَةِ الشَّمْسِيَّةِ، عَدَدُ أيَّامِهِ 28 يَوْماً فِي السِّنِينَ العَادِيَةِ، وَ 29 يَوْماً فِي السِّنِينَ الكَبِيسَةِ، يَأْتِي بَعْدَ كَانُونٍ الثَّانِي، وَيَلِيهِ آذَار، وَيُعْرَفُ أيْضاً بِاسْمِ فَبْرَايِر."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10836, 'شَبَحٌ', 'شبح', 'جامد', 'شبح', 'شبح', 'شبح', '', '', '', 'مفرد', 'DnN', '', '', '"أشْبَاحٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""رَأى شَبَحاً مِنْ بَعِيدٍ"": خَيَالَ شَخْصٍ يَبْدُو مِنْ بَعِيدٍ. ""شَبَحٌ لاَ يُرَى وَلاَ يَنْبَغِي أنْ يُرَى"". ‎(توفيق الحكيم). 2. ""شَبَحُ الْمَوْتِ"" : ثِقْلُهُ وَوَطْأَتُهُ. ""شَبَحٌ مُخِيفٌ"". 3. ""أَشْبَاحُ اللَّيْلِ"" : أَطْيَافُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10837, 'أشْبَاحٌ', 'أشباح', 'جامد', '', 'ءشباح', 'شبح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10838, 'شِبْرٌ', 'شبر', 'جامد', 'شبر', 'شبر', 'شبر', '', '', '', 'مفرد', 'DnN', '', '', '"أَشْبَارٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""عَرْضُ الحُفْرَةِ لاَ يَتَجَاوَزُ شِبْراً"" : مِقْيَاسُهَا مَا بَيْنَ طَرَفِ الإبْهَامِ وَطَرَفِ الخِنْصِرِ مُمْتَدَّيْنِ. 2. ""تَابَعَ خُطَاهُ شِبْراً شِبْراً"" : شَيْئاً فَشَيْئاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10839, 'أَشْبَارٌ', 'أشبار', 'جامد', '', 'ءشبار', 'شبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10840, 'شُبَّاكٌ', 'شباك', 'جامد', 'شبك', 'شباك', 'شبك', '', '', '', 'مفرد', 'DnN', '', '', '"شَبَابِيكُ"', '', 'R', '', '', '', '', '', '', '". 1. ""طَلَّ مِنَ الشُّبَّاكِ"": مِنَ النَّافِذَةِ الَّتِي تُشَبَّكُ بِالحَدِيدِ أَوِ الخَشَبِ. 2.""أَخَذَ التَّذْكِرَةَ مِنْ شُبَّاكِ السِّينمَا"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10841, 'شَبَابِيكُ', 'شبابيك', 'جامد', '', 'شبابيك', 'شببك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10842, 'شَبَكَةٌ', 'شبكة', 'جامد', 'شبك', 'شبكة', 'شبكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":شِبَاكٌ"', '', 'R', '', '', '', '', '', '', '". 1.""رَمَى الصَّيَّادُ الشَّبَكَةَ فِي البَحْرِ"" : خُيُوطٌ مُتَشَابِكَةٌ تُسْتَعْمَلُ لِصَيْدِ السَّمَكِ، شَرَكَةٌ. 2.""اِتَّسَعَتْ شَبَكَةُ خُطُوطِ السِّكَّةِ الحَدِيدِيَّةِ فِي البِلاَدِ"" : مَجْمُوعُ خُطُوطِ السِّكَّةِ الحَدِيدِيَّةِ. 3.""أُدْخِلَتْ إصْلاَحَاتٌ مُهِمّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10843, 'شِبَاكٌ', 'شباك', 'جامد', '', 'شباك', 'شبك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10844, 'شُبْكَةٌ', 'شبكة', 'جامد', 'شبك', 'شبكة', 'شبكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"شُبْكَةٌ-شُبْكَةٌ [ش ب ك]. ""بَيْنَهُمَا شُبْكَةٌ"" : قَرَابَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10845, 'شَبَكِيَّةٌ', 'شبكية', 'جامد', 'شبك', 'شبكية', 'شبكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَبَكِيَّةٌ-شَبَكِيَّةٌ [ش ب ك]. ""شَبَكِيَّةُ العَيْنِ"" : إحْدَى طَبَقَاتِ العَيْنِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10846, 'شَبِيكَةٌ', 'شبيكة', 'جامد', 'شبك', 'شبيكة', 'شبكة', '', '', '', 'مفرد', 'DnN', '', '', '"شَبَائِكُ"', '', '', '', '', '', '', '', '', '". 1. ""شَبِيكَةُ النَّافِذَةِ"": شُبَّاكٌ مِنْ أَسْلاَكٍ حَدِيدِيَّةٍ دَقِيقَةٍ مَنْسُوجَةٍ، يُشَدُّ إلَى النَّافِذَةِ. 2.""شَبِيكَةُ الحَدِيقَةِ"" : مَا تُسَيَّجُ بِهِ الحَدِيقَةُ مِنْ أسْلاَكٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10847, 'شَبَائِكُ', 'شبائك', 'جامد', '', 'شباءك', 'شبك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10848, 'شِبْلٌ', 'شبل', 'جامد', '', 'شبل', 'شبل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَشْبَالٌ"', '', 'R', '', '', '', '', '', '', '"شِبْلٌ - ج: أَشْبَالٌ. : وَلَدُ الأَسَدِ إذَا أدْرَكَ الصَّيْدَ.   ""هَذَا الشِّبْلُ مِنْ ذَاكَ الأسَدِ"". (مثل)"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10849, 'أَشْبَالٌ', 'أشبال', 'جامد', '', 'ءشبال', 'شبل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10850, 'شِبَامٌ', 'شبام', 'جامد', 'شبم', 'شبام', 'شبم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"شِبَامٌ - [ش ب م]. ""وَضَعَ الشِّبَامَ فِي فَمِ الحَيَوَانِ"" : عُودٌ يُوضَعُ فِي فَمِ الحَيَوَانِ الرَّضِيعِ لِئَلاَّ يَرْضَعَ أُمَّهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10851, 'شُبْهَةٌ', 'شبهة', 'جامد', 'شبه', 'شبهة', 'شبهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":شُبَهٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هُوَ شُبْهَةُ أخِيهِ"" : مِثْلُهُ. 2. ""مَازَالَ تَحْتَ الشُّبْهَةِ"" : مُرْتَابٌ فِي أَمْرِهِ، أيْ مَازَالَ يَدْعُو لِسُوءِ الظَّنِّ فِيهِ. ""رَجُلٌ بَعِيدٌ عَنْ كُلِّ الشُّبُهَاتِ"". 3.""مِنْ أَصْحَابِ الشُّبُهَات"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10852, 'شُبَهٌ', 'شبه', 'جامد', '', 'شبه', 'شبه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
