INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10854, 'أَشْبَاهٌ', 'أشباه', 'جامد', '', 'ءشباه', 'شبه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10855, 'شِبْهٌ', 'شبه', 'جامد', 'شبه', 'شبه', 'شبه', '', '', '', 'مفرد', 'DnN', '', '', '"أشْبَاهٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""وَجَدْتُهُ فِي شِبْهِ غَيْبُوبَةٍ"" : فِي غَيْبُوبَةٍ تَكَادُ تَكُونُ تَامَّةً. ""فِي شِبْهِ عُزْلَةٍ تَامَّةٍ"". 2.""خَبَرٌ شِبْهُ رَسْمِيٍّ"" : لَيْسَتْ لَهُ صِفَةٌ رَسْمِيَّةٌ مَعَ أَنَّهُ أُذِيعَ مِنْ جِهَاتٍ مَسْؤُولَةٍ. 3. ""شِبْهُ الجَزِيرَةِ"" : أرْضٌ تُحِيطُ بِهَا المِياهُ مِنْ جَمِيعِ الجِهَاتِ مَا عَدَا جِهَةً وَاحِدَةً تَصِلُهَا بِالبَرِّ. 4.""شِبْهُ الجُمْل"', '');
