INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10863, 'مَشْتًى', 'مشتى', 'جامد', 'شتو', 'مشتى', 'مشت', '', '', '', 'مفرد', 'Dy', '', '', '"الْمَشَاتِي"', '', '', '', '', '', '', '', '', '"مَشْتـىً - ج: الْمَشَاتِي. [ش ت و]. 1.""قَضَى مَشْتـىً قَارِساً"" : أَيَّاماً مِنْ زَمَانِ الشِّتَاءِ. 2.""هَذِهِ مَشَاتِينَا وَمَصَايِفُنَا"": مَوْضِعُ الإِقَامَةِ فِي الشِّتَاءِ"', '');
