INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10869, 'شَجَّةٌ', 'شجة', 'جامد', 'شجج', 'شجة', 'شجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"شَجَّةٌ - [ش ج ج]. ""أُصِيبَ بِشَجَّةٍ فِي رَأْسِهِ"" : بِجُرْحٍ وَفِي الرَّأْسِ خَاصَّةً. "', '');
