INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10880, 'شُحْرُورٌ', 'شحرور', 'جامد', '', 'شحرور', 'شحرر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"شَحَارِيرُ"', '', 'R', '', '', '', '', '', '', '"ج: شَحَارِيرُ. (حو).: طَائِرٌ مِنْ فَصِيلَةِ الشُّحْرُورِيَّاتِ، مِنْ رُتْبَةِ العُصْفُورِيَّاتِ، مِنَ الطُّيُورِ الْمُغَـرِّدَةِ، أَسْوَدُ اللَّوْنِ، مِنْقَارُهُ بُرْتُقَالِيٌّ، وَالأَرْجُلُ وَالْمَخَالِبُ سَمْرَاءُ غَامِقَةٌ، وَالأُنْثَى مِنْقَارُهَا أسْمَرُ قَائِمٌ، وَرِيشُهَا أَسْمَرُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10881, 'شَحَارِيرُ', 'شحارير', 'جامد', '', 'شحارير', 'شحرر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10882, 'شُحْرُوِيَّاتٌ', 'شحرويات', 'جامد', '', 'شحرويات', 'شحرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ حَيَوَانِيَّةٌ مِنْ طُيُورِ الجَوَاثِمِ، مَنَاقِيرُهَا مَشْرُومَةٌ تَشْمُلُ الشُّحْرُورَ وَالسُّمْنَةَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10883, 'شَحْطَةٌ', 'شحطة', 'جامد', 'شحط', 'شحطة', 'شحطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"شَحْطَةٌ-شَحْطَةٌ [ش ح ط]. 1.""أَشْعَلَ شَحْطَةً"" : أَشْعَلَ عُودَ الثِّقَابِ. 2.""بِشَحْطَةِ قَلَمٍ"" : بِجَرَّةِ قَلَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10884, 'شَحْمَةٌ', 'شحمة', 'جامد', 'شحم', 'شحمة', 'شحمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":شُحُومٌ"', '', 'R', '', '', '', '', '', '', '". 1.""نَاوَلَهُ شَحْمَةً"" : قِطْعَةَ شَحْمٍ. 2.""شَحْمَةُ العَيْنِ"" : مُقْلَتُهَا. 3.""ثَقَبَتْ شَحْمَةَ أُذُنِهَا"" : أَسْفَل الأُذُنِ حَيْثُ تُعَلِّقُ الْمَرْأَةُ القُرْطَ. 4.""مَا كُلُّ بَيْضَاءَ شَحْمَةٌ وَ لاَ سَوْدَاءَ ثَمَرَةٌ"".(مثل) : يُضْرَبُ فِيمَا يَتَشَابَهُ فِي صِفَةٍ وَيَتَبَايَنُ فِي صِفَاتٍ أُخْرَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10885, 'شُحُومٌ', 'شحوم', 'جامد', '', 'شحوم', 'شحم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10886, 'شَاحِنَةٌ', 'شاحنة', 'جامد', 'شحن', 'شاحنة', 'شحنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1. ""مَرَّتْ شَاحِنَةٌ مُحَمَّلَةٌ بِالبَضَائِعِ"" : سَيَّارَةٌ تَجُرُّ وَرَاءهَا عَرَبَةً تُشْبِهُ صُنْدُوقاً كَبِيراً مُسْتَطِيلاً. ""صَادَفْنَا شَاحِنَاتٍ فِي الطَّرِيقِ السَّيَّارِ"". 2.""سَفِينَةٌ شَاحِنَةٌ"" : سَفِينَةٌ مُحَمَّلَةٌ بِالبَضَائِعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10887, 'شَحْنَاءُ', 'شحناء', 'جامد', 'شحن', 'شحناء', 'شحن', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"شَحْنَاءُ-شَحْنَاءُ [ش ح ن]. ""اِمْتَلأَ قَلْبُهُ بِالشَّحْنَاءِ"" : بِالعَدَاوَةِ وَالبَغْضَاءِ وَالحِقْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10888, 'شِحْنَةٌ', 'شحنة', 'جامد', 'شحن', 'شحنة', 'شحنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":شِحَنٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""زَوَّدَ البَطَّارِيَّةَ بِشِحْنَةٍ كَهْرَبَائِيَّةٍ"" : بِطَاقَةٍ كَهْرَبَائِيَّةٍ، أَيْ مَا يَتَحَمَّلُهُ جِسْمٌ مَّا مِنَ الكَهْرَبَاءِ. 2. ""شِحْنَةُ السَّفِينَةِ"" : مَا تُشْحَنُ بِهِ مِنَ البَضَائِعِ. 3. ""بالإسطبل شِحْنَةٌ مِنَ الخَيْلِ"" : فِرْقَةٌ مِنَ الخَيْلِ. 4.""بَيْنَهُمَا شِحْنَةٌ"" : شَحْناءُ، عَدَاوَةٌ، بَغْضَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10889, 'شِحَنٌ', 'شحن', 'جامد', '', 'شحن', 'شحن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10890, 'شَخْصٌ', 'شخص', 'جامد', '', 'شخص', 'شخص', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَشْخَاصٌ:شُخُوصٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَشْخَاصٌ، شُخُوصٌ. 1.""رَأَى شَخْصاً غَرِيباً"" : إِنْسَاناً. ""وَصَلَ بَعْضُ الأَشْخَاصِ وَلَمْ يَتَعَرَّفْ عَلَى أَسْمَائِهِمْ بَعْدُ"". 2.""جَاءَ بِشَخْصِهِ"" : بِنَفْسِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10891, 'أَشْخَاصٌ', 'أشخاص', 'جامد', '', 'ءشخاص', 'شخص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10892, 'شُخُوصٌ', 'شخوص', 'جامد', '', 'شخوص', 'شخص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10893, 'أَشُدٌّ', 'أشد', 'جامد', 'شدد', 'ءشد', 'شد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أَشُدٌّ-أَشُدٌّ [ش د د]. ""بَلَغَ الوَلَدُ أَشُدَّهُ"" : بَلَغَ سِنَّ الإِدْراكِ وَالبُلوغِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10894, 'شِدْقٌ', 'شدق', 'جامد', 'شدق', 'شدق', 'شدق', '', '', '', 'مفرد', 'DnN', '', '', '"أَشْدَاقٌ:شُدُوقٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""نَفَخَ شِدْقَيْهِ"" : زَاوِيَةُ الفَمِ مِنْ تَحْتِ الخَدَّيْنِ وَباطِنِهِما. ""ضَحِكَ مِلْءَ شِدْقَيْهِ"". 2. ""نَزَلَ بِشِدْقِ الوَادِي"" : أَيْ بِجَانِبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10895, 'أَشْدَاقٌ', 'أشداق', 'جامد', '', 'ءشداق', 'شدق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10896, 'شُدُوقٌ', 'شدوق', 'جامد', '', 'شدوق', 'شدق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10897, 'شَدَهٌ', 'شده', 'جامد', 'شده', 'شده', 'شده', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَدَهٌ-شَدَهٌ [ش د هـ]. ""أَصابَهُ الشَّدَهُ"" : الحَيْرَةُ، الدَّهَشُ، التَّعَجُّبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10898, 'شِدْيَاقٌ', 'شدياق', 'جامد', '', 'شدياق', 'شدق', '', '', '', 'جمع تكسير', 'DnN', '', '', '"شَدَايِقَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: شَدَايِقَةٌ. : رُتْبَةٌ كَهَنُوتِيَّةٌ عِنْدَ النَّصَارَى، وَهِيَ دُونَ الكَاهِنِ دَرَجَةٌ وَاحِدَةٌ، الشَّمَّاسُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10899, 'شَدَايِقَةٌ', 'شدايقة', 'جامد', '', 'شدايقة', 'شدقة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10900, 'شَذَبٌ', 'شذب', 'جامد', 'شذب', 'شذب', 'شذب', '', '', '', 'مفرد', 'DnN', '', '', '"أَشْذَابٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""شَذَبُ الشَّجَرِ"": مَا يُقْطَعُ مِنْهُ وَيُلْقَى. 2.""بَقِيَ عِنْدَهُ شَذَبٌ مِنْ مَالٍ"" : بَقِيَّةٌ مِنْهُ. ""مَا بَقِيَ لَهُ إِلاَّ شَذَبٌ مِنَ العَسْكَرِ"". 3.""شَذَبُ البَيْتِ"" : مَتَاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10901, 'أَشْذَابٌ', 'أشذاب', 'جامد', '', 'ءشذاب', 'شذب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10902, 'شُذَّاذٌ', 'شذاذ', 'جامد', 'شذذ', 'شذاذ', 'شذذ', '', '', '', 'مفرد', '', '', '', '"مفردشَاذّ"', '', 'R', '', '', '', '', '', '', '". ""شُذَّاذُ الآفَاقِ"" : الغُرَبَاءُ الَّذِينَ لاَ وَطَنَ لَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10903, 'شَاذّ', 'شاذ', 'جامد', '', 'شاذ', 'شذ', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10904, 'شَذْرٌ', 'شذر', 'جامد', 'شذر', 'شذر', 'شذر', '', '', '', 'مفرد', 'DnN', '', '', '"شُذُورٌ"', '', 'R', '', '', '', '', '', '', '". 1.""شُذُورُ الذَّهَبِ"" : القِطَعُ الْمُلْتَقَطَةُ مِنْ مَعْدِنهِ. 2.""شَذْرُ العِقْدِ"" : خَرَزٌ يُفْصَلُ بِهِ بَيْنَ حَبَّاتِ العِقْدِ. 3.""اِخْتَارَتْ شَذْراً جَمِيلاً"" : لُؤْلُؤاً صِغاراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10905, 'شُذُورٌ', 'شذور', 'جامد', '', 'شذور', 'شذر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10906, 'شَذَا', 'شذا', 'جامد', 'شذو', 'شذا', 'شذ', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"شَذَا-شَذَا [ش ذ و]. 1.""عَبَقَ الشَّذَا الْمَكَانَ"" : قُوَّةُ الرَّائِحَةِ. 2.""لَحِقَهُ شَذَاهُ"" : شَرُّهُ، آذَاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10907, 'شَرَايِينُ', 'شرايين', 'جامد', '', 'شرايين', 'شرن', '', '', '', 'جمع تكسير', '', '', '', '"مفردشَرْيان"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"جمع شَرْيان. : عرُوقٌ، أَوْعِيَةٌ تَنْقُلُ الدَّمَ الصَّادِرَ مِنَ القَلْبِ إِلَى الجِسْمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10908, 'شَرْيان', 'شريان', 'جامد', '', 'شريان', 'شرن', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10909, 'شَرَابٌ', 'شراب', 'جامد', 'شرب', 'شراب', 'شرب', '', '', '', 'مفرد', 'DnN', '', '', '"أَشْرِبَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""شَرَابٌ مِنْ عَصِيرِ كَذَا"" : كُلُّ مَا يُشْرَبُ. ""شَرَابٌ مَذَاقُهُ حُلْوٌ"". 2.""اِجْتَمَعُوا فِي لَيْلَةٍ سَاهِرَةٍ عَلَى الشَّرَابِ"" : عَلَى شُرْبِ الخَمْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10910, 'أَشْرِبَةٌ', 'أشربة', 'جامد', '', 'ءشربة', 'شربة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10911, 'شَرَبَةٌ', 'شربة', 'جامد', 'شرب', 'شربة', 'شربة', '', '', '', 'مفرد', 'DnN', '', '', '"شَرَبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""بِهِ شَرَبَةٌ"" : كَثْرَةُ الشُّرْبِ، أَوِ العَطَشِ. ""لَمْ تَزَلْ بِهِ شَرَبَةُ هَذَا اليَوْمِ"". 2.""يَوْمٌ ذُو شَرَبَةٍ"" : شَدِيدُ الحَرِّ، أَيْ يُشْربُ فيهِ الْمَاءُ كَثِيراً. 3.""طَعَامٌ ذُو شَرَبَةٍ"" : لاَ يَرْوَى آكِلُهُ بِالْمَاءِ. 4.""شَرَبَةُ الشَّجَرَةِ"": حَوْضٌ صَغِيرٌ يُحْفَرُ حَوْلَ الشَّجَرَةِ وَيُمْلأُ مَاءً لِتَشْرَبَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10912, 'شَرَبٌ', 'شرب', 'جامد', '', 'شرب', 'شرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10913, 'شُرْبَةٌ', 'شربة', 'جامد', 'شرب', 'شربة', 'شربة', '', '', '', 'مفرد', 'DnN', '', '', '"شُرَبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""جَرَعَ شُرْبَةً مِنَ الْمَاءِ"" : مِقْدَارُ مَا يُشْرَبُ مِنَ الْمَاءِ. 2.""يَتَنَاوَلُ شُرْبَةً فِي كُلِّ مَسَاءٍ"" : حَسَاءً مِنَ الخُضَرِ. 3. ""شُرْبَةُ الوَجْهِ"" : حُمْرَةٌ فِي الوَجْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10914, 'شُرَبٌ', 'شرب', 'جامد', '', 'شرب', 'شرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10915, 'شُرُوبٌ', 'شروب', 'جامد', 'شرب', 'شروب', 'شرب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شُرُوبٌ-شُرُوبٌ [ش ر ب]. ""تَنَاوَلَ شُرُوباً"" : الشَّرَابُ الَّذِي يَتَنَاوَلُهُ الْمَرِيضُ دَوَاءً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10916, 'مَشْرَبٌ', 'مشرب', 'جامد', 'شرب', 'مشرب', 'مشرب', '', '', '', 'مفرد', 'DnN', '', '', '"مَشَارِبُ"', '', 'R', '', '', '', '', '', '', '". 1. ""اِرْتَمَى العَطْشَانُ يَغْرِفُ مِنَ الْمَشْرَبِ"" : مَاءُ الشُّرْبِ، مَوْضِعُ الشُّرْبِ.البقرة آية 60 قَدْ عَلِمَ كُلُّ أُنَاسٍ مَشْرَبَهُمْ (قرآن). 2.""مَشْرَبُ الإِنْسَانِ"" : مَيْلُهُ، هَوَاهُ. ""تَخْتَلِفُ مَشَارِبُ النَّاسِ وَتَتَنَوَّعُ رَغَبَاتُهُمُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10917, 'مَشَارِبُ', 'مشارب', 'جامد', '', 'مشارب', 'مشرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10918, 'شَيْرَجٌ', 'شيرج', 'جامد', 'شرج', 'شيرج', 'شرج', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَيْرَجٌ-شَيْرَجٌ، شِيْرِجٌ [ش ر ج]. : دُهْنُ السِّمْسِمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10919, 'شَوَارِدُ', 'شوارد', 'جامد', 'شرد', 'شوارد', 'شرد', '', '', '', 'مفرد', '', '', '', '"مفردشَارِدَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""يَبْحَثُ فِي شَوَارِدِ اللُّغَةِ"": فِي نَوَادِرِهَا وَغَرِيبِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10920, 'شِرْذِمَةٌ', 'شرذمة', 'جامد', '', 'شرذمة', 'شرذمة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"شَرَاذِمُ"', '', 'R', '', '', '', '', '', '', '"ج: شَرَاذِمُ. ""شِرْذِمَةٌ مِنَ النَّاسِ"" : جَمَاعَةٌ مِنَ النَّاسِ. الشعراء آية 54 إِنَّ هَؤُلاَءِ لَشِرْذِمَةٌ قَلِيلُونَ . (قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10921, 'شَرَاذِمُ', 'شراذم', 'جامد', '', 'شراذم', 'شرذم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10922, 'شَرَارٌ', 'شرار', 'جامد', 'شرر', 'شرار', 'شرر', '', '', '', 'مفرد', '', '', '', '"مفردشَرَارَة"', '', 'R', '', '', '', '', '', '', '". 1.""شَرَارُ النِّيرَانِ"" : مَا يَتَطَايَرُ مِنْهَا مِنْ ذَرَّاتٍ مُتَوَهِّجَةٍ، الشَّرَرُ. 2.""رَأَيْتُ شَرَاراً يَتَطَايَرُ مِنْ عَيْنَيْهِ"" : كِنَايَةٌ عَنْ حِدَّةِ الغَضَبِ وَالعُنْفِ وَظُهُورِ ذَلِكَ عَلَى الْمَلاَمِحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10923, 'شَرَارَة', 'شرارة', 'جامد', '', 'شرارة', 'شررة', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10924, 'شَرَرٌ', 'شرر', 'جامد', 'شرر', 'شرر', 'شر', '', '', '', 'مفرد', '', '', '', '"مفردشَرَرَة"', '', 'R', '', '', '', '', '', '', '". 1. ""يَتَطَايَرُ شَرَرُ النَّارِ"": مَا يَتَطَايَرُ مِنَ النَّارِ. 2. ""كَانَ الشَّرَرُ يَتَطَايَرُ مِنْ عَيْنِهِ"": كِنَايَةٌ عَنِ الغَضَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10925, 'شَرَرَة', 'شررة', 'جامد', '', 'شررة', 'شررة', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10926, 'شُرْسُوفٌ', 'شرسوف', 'جامد', 'شرسف', 'شرسوف', 'شرسف', '', '', '', 'مفرد', 'DnN', '', '', '"شَرَاسِفُ"', '', 'R', '', '', '', '', '', '', '"(تش). : الطَّرَفُ اللَّيِّنُ مِنَ الضِّلْعِ مِمَّا يَلِي البَطْنَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10927, 'شَرَاسِفُ', 'شراسف', 'جامد', '', 'شراسف', 'شرسف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10928, 'شَرَاشِرُ', 'شراشر', 'جامد', 'شرشر', 'شراشر', 'شرشر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَرَاشِرُ-شَرَاشِرُ [ش ر ش ر]. 1. ""شَرَاشِرُ الطَّيْرِ"" : أَطْرَافُ أَجْنِحَتِهِ. 2. ""شَرَاشِرُ الجِسْمِ"" : أَيْ جُمْلَةُ الجِسْمِ. 3.""أَلْقَى عَلَيْهِ شَرَاشِرَهُ"" : أَيْ أَعْبَاءهُ وَهُمُومَهُ، أَوْ أَلْقَى عَلَيْهِ نَفْسَهُ حِرْصاً وَمَحَبَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10929, 'شُرْشورٌ', 'شرشور', 'جامد', '', 'شرشور', 'شرشر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": شراشِيرُ. (حو).: طَائِرٌ مِنْ فَصِيلَةِ الشُّرْشورِيَّاتِ، جَمِيلُ الصَّوْتِ، صَغِيرُ الحَجْمِ، رِيشُهُ أَزْرَقُ وَأَخْضَرُ، لَهُ مِنْقَارٌ مَخْرُوطٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10930, 'شُرْشُورِيَّاتٌ', 'شرشوريات', 'جامد', '', 'شرشوريات', 'شرشرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"شُرْشُورِيَّاتٌ-شُرْشُورِيَّاتٌ (حو). : فَصِيلَةُ طُيُورٍ مِنَ الَجَوَاثِمِ، لَهَا مَنَاقِيرُ مَخْرُوطَةٌ، تَشْمُلُ الحَسُّونَ وَالدُّورِيَّ وَالكَنَارَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10931, 'شَرْطَةٌ', 'شرطة', 'جامد', 'شرط', 'شرطة', 'شرطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""وَضَعَ شَرْطَةً بَيْنَ الكَلِمَتَيْنِ"" : الخَطُّ القَصِيرُ (ـ) بَيْنَ كَلِمَتَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10932, 'شُرْطَةٌ', 'شرطة', 'جامد', 'شرط', 'شرطة', 'شرطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"مفردشُرْطِيّ"', '', 'Rp', '', '', '', '', '', '', '". 1.""رِجَالُ الشُّرْطَةِ"": رِجَالُ الأَمْنِ، أَيِ الْمَسْؤُولُونَ عَنْ حِفْظِ النِّظَامِ. ""سَيَّارَةُ الشُّرْطَةِ"". 2.""الشُّرْطَةُ القَضَائِيَّةُ"" : الْمَسْؤُولُونَ عَنْ تَقْدِيمِ الْمُعْتَقَلِينَ لِرِجَالِ القَضَاءِ. 3.""شُرْطَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10933, 'شَرِيطَةٌ', 'شريطة', 'جامد', 'شرط', 'شريطة', 'شرطة', '', '', '', 'مفرد', 'DnN', '', '', '"شَرَائِطُ"', '', 'R', '', '', '', '', '', '', '". 1.""شَدَّتْ شَعْرَهَا بِشَرِيطَةٍ"" : قِطْعَةٌ مِنْ ثَوْبٍ عَلَى شَكْلِ فَرَاشَةٍ تَعْقِدُ بِهَا الفَتَيَاتُ شَعْرَهُنَّ، أَوْ يُزَيِّنَّ بِهَا ثِيَابَهُنَّ. 2. ""أَقْرَضَهُ مَبْلَغاً مِنَ الْمَالِ شَرِيطَةَ أَنْ يُرْجِعَهُ قَبْلَ آخِرِ الشَّهْرِ"" : بِشَرْطِ."', '');
