INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10935, 'شَرِيطٌ', 'شريط', 'جامد', 'شرط', 'شريط', 'شرط', '', '', '', 'مفرد', 'DnN', '', '', '"أَشْرِطَةٌ:شَرَائِطُ"', '', 'R', '', '', '', '', '', '', '". 1. ""شَدَّتْ شَعْرَهَا بِشَرِيطٍ"" : نَسِيج مِنْ خُيُوطٍ يُفْتَلُ بَعْضُهَا مَعَ بَعْضٍ. 2.""يَمْتَدُّ شَرِيطُ الكَهْرَبَاءِ إِلَى كُلِّ الغُرَفِ"" : سِلْكٌ مَعْدِنِيٌّ دَقِيقٌ مَفْتُولٌ. 3. ""الشَّرِيطُ السِّينِمَائِيُّ"" : الفِلْمُ. 4. ""شَرِيطُ التَّسْجِيلِ"" : مَادَّةٌ مَغْنَاطِيسِيَّةٌ "', '');
