INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10950, 'شَرِيعَةٌ', 'شريعة', 'جامد', 'شرع', 'شريعة', 'شرعة', '', '', '', 'مفرد', 'DnN', '', '', '"شَرَائِعُ"', '', '', '', '', '', '', '', '', '". 1.""أَحْكَامُ الشَّرِيعَةِ"" : العَقِيدَةُ، أَيْ مَا شَرَّعَهُ اللَّهُ لِعِبَادِهِ مِنْ أَحْكَامٍ. 2.""سَنَّ شَرِيعَةً"": طَرِيقاً صَحِيحاً، مَنْهَجاً ب"', '');
