INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10953, 'تَشْرِيفَاتٌ', 'تشريفات', 'جامد', 'شرف', 'تشريفات', 'تشرفت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"تَشْرِيفَاتٌ-تَشْرِيفَاتٌ [ش ر ف]. 1.: العَادَاتُ، الأُصُولُ الْمَرْعِيَّةُ. 2.""اِسْتَقْبَلَ الْمَلِكُ ضَي"', '');
