INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10956, 'مَشَارِفُ', 'مشارف', 'جامد', 'شرف', 'مشارف', 'مشرف', '', '', '', 'مفرد', '', '', '', '"مفردمَشْرَف"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""مَشَارِفُ الأَرْضِ"" : أَعَالِيهَا. 2.""مَشَارِفُ الْمَدِينَةِ"" : مَا يُحِيطُ بِهَا مِنْ قُرىً وَبِنَايَاتٍ، ضَوَاحِيهَا. 3.""مَشَارِفُ العِرَاقِ"" : القُرَى الْمُشْرِفَةُ عَلَى سَوَادِ العِرَاقِ. ""مَشَارِفُ الشَّامِ"" ""مَشَارِفُ اليَمَنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10957, 'مَشْرَفٌ', 'مشرف', 'جامد', 'شرف', 'مشرف', 'مشرف', '', '', '', 'مفرد', 'DnN', '', '', '"مَشَارِفُ"', '', 'R', '', '', '', '', '', '', '". ""مَشْرَفُ الْمَسْكَنِ"": بَهْوٌ صَغِيرٌ يَكُونُ مُلْتَصِقاً بِغُرْفَةٍ مِنْ غُر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10958, 'مَشَارِفُ', 'مشارف', 'جامد', '', 'مشارف', 'مشرف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10959, 'شُرْفَةٌ', 'شرفة', 'جامد', '', 'شرفة', 'شرفة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"شُرَفٌ"', '', 'R', '', '', '', '', '', '', '"ج: شُرَفٌ. 1. ""يُطِلُّ مِنْ شُرْفَةِ القَصْرِ"" : فَتْحَةٌ ثُلاَثِيَّةُ أَوْ رُبَاعِيَّةُ الشَّكْلِ تُبْنَى فِي أَعْلَى القَصْرِ كَمَا تُبْنَى فِي أَعَالِي الأَسْوَارِ، أَوْ مُجَرَّدُ بَهْوٍ صَغِيرٍ غَيْرِ مُغَطّىً خَارِجٍ مِنَ البِنَاءِ يُسْتَشْرَفُ مِنْهُ عَلَى مَا حَوْلَهُ. 2.""جَلَسَ فِي شُرْفَةِ الْمَسْرَحِ"" : الْمَقْصُورَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10960, 'شُرَفٌ', 'شرف', 'جامد', '', 'شرف', 'شرف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10961, 'شَرْقٌ', 'شرق', 'جامد', 'شرق', 'شرق', 'شرق', '', '', '', 'مفرد', 'DnN', '', '', '"أَشْرَاقٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""تُشْرِقُ الشَّمْسُ مِنَ الشَّرْقِ"" : أَحَدُ الْجِهَاتِ الأَصْلِيَّةِ، وَيَكُونُ جِهَةَ طُلُوعِ الشَّمْسِ وَشُرُوقِهَا. ""الْجِهَاتُ الأَرْبَعُ هِيَ: الشَّرْقُ وَالغَرْبُ واَلشَّمَالُ وَالْجَنُوبُ"" (جغ) ""الْمَنَاطِقُ الَّتي تَقَعُ شَرْقَ البَحْرِ الأَبْيَضِ الْمُتَوَسِّطِ وَشَرْقَ أُورُوبَّا، وَهِيَ أَقْسَامٌ"" : الشَّرْقُ الأَدْنَى، الشَّرْقُ الأَوْسَطُ، الشَّرْقُ الأَقْصَى"". 2. ""اِتَّجَهَ شَرْقاً"" : اِتَّجَهَ وِجْهَةَ شُرُوقِ الشَّم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10962, 'أَشْرَاقٌ', 'أشراق', 'جامد', '', 'ءشراق', 'شرق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10963, 'مَشَارِقُ', 'مشارق', 'جامد', 'شرق', 'مشارق', 'مشرق', '', '', '', 'مفرد', '', '', '', '"مفردمَشْرِق"', 'ممنوع من الصرف', 'Rp', '', '', '', '', '', '', '". ""جَابَ مَشَارِقَ الأَرْضِ وَمَغَارِبَهَا"" : جَابَ بُلْدَاناً مِنْ أَقْصَى شَرْقِ الْمَعْمُورَةِ إِلَى غَرْبِهَا. ن. مَشْرِقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10964, 'مَشْرِقٌ', 'مشرق', 'جامد', 'شرق', 'مشرق', 'مشرق', '', '', '', 'مفرد', 'DnN', '', '', '"مَشَارِقُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""مَشْرِقُ الشَّمْسِ"": الجِهَةُ الَّتِي تُشْرِقُ مِنْهَا الشَّمْسُ. 2.""الْمَشْرِقُ العَرَبِيُّ"" : البِلاَدُ العَرَبِيَّةُ فِي الشَّرْقِ العَرَبِيِّ. 3. الزخرف آية 38 يَا لَيْتَ بَيْنِي وَبَيْنَكَ بُعْدَ الْمَشْرِقَيْنِ فَبِئْسَ القَرِينُ (قرآن) : الْمَشْرِقُ وَالْمَغْرِبُ.البقرة آية 115 وَلله الْمَشْرِقُ وَالْمَغْرِبُ فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ الله (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10965, 'مَشَارِقُ', 'مشارق', 'جامد', '', 'مشارق', 'مشرق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10966, 'شِرَقْرَاقٌ', 'شرقراق', 'جامد', '', 'شرقراق', 'شرقرق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ن.: شَرَقْرَقٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10967, 'شَرَقْرَقٌ', 'شرقرق', 'جامد', '', 'شرقرق', 'شرقرق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"شَرَقْرَقٌ-شَرَقْرَقٌ (حو).: طَائِرٌ صَغِيرٌ، مِنْ فَصِيلَةِ الشَّقِرَّاقِيَّاتِ، أَصْغَرُ مِنَ الْحَمَامَةِ، لَوْنُهُ بَيْنَ خُضْرَةٍ وَحُمْرَةٍ وَزُرْقَةٍ وَسَوَادٍ، تَغْلِبُ عَلَيْهِ الْخُضْرَةُ، مِنْقَارُهُ أَسْوَدُ وَمُسْتَقِيمٌ، مَعْقُوفٌ عِنْدَ طَرَفِهِ، لاَ يَهَابُ الطُّيُورَ، يُسَمَّى بِالشَّرَقْرَاقِ أَوِ الشَّقِرَّاق، وَهُوَ مِنَ الطُّيُورِ الَّتِي تَتَشَاءمُ بِها العَرَبُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10968, 'شِرَاكٌ', 'شراك', 'جامد', 'شرك', 'شراك', 'شرك', '', '', '', 'مفرد', 'DnN', '', '', '"شُرُكٌ"', '', 'R', '', '', '', '', '', '', '". ""شَدَّ نَعْلَهُ بِشِرَاكٍ"": بِسَيْرِ النَّعْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10969, 'شُرُكٌ', 'شرك', 'جامد', '', 'شرك', 'شرك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10970, 'شَرَكَةٌ', 'شركة', 'جامد', 'شرك', 'شركة', 'شركة', '', '', '', 'مفرد', 'DnN', '', '', '"واحدةالشَّرَكِ"', '', 'R', '', '', '', '', '', '', '". ""رَمَى بِالشَّرَكَةِ فِي النَّهْرِ"" : شَبَكَةُ الصَّيْدِ لِلسَّمَكِ وَالطَّيْرِ مَعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10971, 'شَرَكٌ', 'شرك', 'جامد', 'شرك', 'شرك', 'شرك', '', '', '', 'مفرد', 'DnN', '', '', '"أَشْرَاكُ"', '', 'R', '', '', '', '', '', '', '". ""نَصَبَ لِلْحَيَوَانِ شَرَكاً"": أَيْ حَبَائِلَ الصَّيْدِ، المِصْيَدَةَ، الكَمِينَ. ""أَوْقَعَهُ فِي شَرَكٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10972, 'أَشْرَاكُ', 'أشراك', 'جامد', '', 'ءشراك', 'شرك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10973, 'شِرْكٌ', 'شرك', 'جامد', 'شرك', 'شرك', 'شرك', '', '', '', 'مفرد', 'DnN', '', '', '"أَشْراكٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَظْهَرَ شِرْكاً بِاللَّهِ"" : أَي الإِلْحَادَ أَوِ القَوْلَ بِتَعَدُّدِ الآلِهَةِ. لقمان آية 13 يَا بُنَيَّ لاَ تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ . (قرآن). 2.""هَذَا شِرْكُهُ"" : نَصِيبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10974, 'أَشْراكٌ', 'أشراك', 'جامد', '', 'ءشراك', 'شرك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10975, 'شَرْوٌ', 'شرو', 'جامد', 'شرو', 'شرو', 'شر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَرْوٌ-شَرْوٌ، شِرْوٌ [ش ر و]. ""شَرْوُ النَّحْلِ"" : عَسَلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10976, 'شَرْوَى', 'شروى', 'جامد', 'شرو', 'شروى', 'شر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَرْوَى-شَرْوَى [ش ر و]. 1.""هُوَ شَرْوَاكَ"" : أَيْ مِثْلُكَ. لِلْمُفْرَدِ وَالْمُثَنَّى وَالْجَمْع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10977, 'شُرَاةٌ', 'شراة', 'جامد', 'شري', 'شراة', 'شرة', '', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"شُرَاةٌ-شُرَاةٌ [ش ر ي]. : فِرْقَةٌ مِنَ الخَوَارِجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10978, 'شَرْيَانٌ', 'شريان', 'جامد', 'شري', 'شريان', 'شرن', '', '', '', 'مفرد', 'DnN', '', '', '"شَرَايِينُ"', '', 'R', '', '', '', '', '', '', '"(تش). 1.""يَجْرِي الدَّمُ فِي الشَّرَايِينِ"" : فِي العُرُوقِ النَّابِضَةِ، يَجْرِي فِيهَا الدَّمُ الأَحْمَرُ الصَّادِرُ مِنَ القَلْبِ إِلَى الْجِسْمِ. 2.""الشَّر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10979, 'شَرَايِينُ', 'شرايين', 'جامد', '', 'شرايين', 'شرن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10980, 'شَرِيٌّ', 'شري', 'جامد', 'شري', 'شري', 'شر', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"شَرِيٌّ - [ش ر ي]. ""جِلْدٌ شَرِيٌّ"" : ظَهَرَتْ عَلَيْهِ عِلَّةُ الشَّرَى. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10981, 'شَرْيٌ', 'شري', 'جامد', 'شري', 'شري', 'شر', '', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', 'N', 'O', 'O', 'O', '', '"شَرْيٌ-شَرْيٌ [ش ر ي].: حَنْظَلٌ، وَهُوَ نَبَاتٌ شَدِيدُ الْمَرَارَةِ. ن. حَنْظَلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10982, 'شَرًى', 'شرى', 'جامد', 'شري', 'شرى', 'شر', '', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"شَرىً-شَرىً [ش ر ي]. 1. ""أَصَابَتْهُ عِلَّةُ الشَّرَى"" : بُثُورٌ حُمْرٌ دَائِرِيَّةٌ مُؤْلِم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(10983, 'شَزْرَاءُ', 'شزراء', 'جامد', 'شزر', 'شزراء', 'شزر', '', '', '', 'مفرد', '', '', '', '"مُؤَنَّثُأَشْزَر"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". ""عَيْنٌ شَزْرَاءُ"" : عَيْنٌ مُحْمَرّ"', '');
