INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11012, 'شُعَرَاءُ', 'شعراء', 'جامد', 'شعر', 'شعراء', 'شعر', '', '', '', 'مفرد', '', '', '', '"مفردشَاعِر"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""الشُّعَراءُ"" : سُورَةٌ مِنْ سُوَرِ القُرْآنِ. الشعراء آية 224 وَالشُّعَرَاءُ يَتْبَعُهُمُ الغَاوُونَ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11013, 'شُفْعَةٌ', 'شفعة', 'جامد', 'شفع', 'شفعة', 'شفعة', '', '', '', 'مفرد', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '"شُفْعَةٌ-شُفْعَةٌ [ش ف ع]. ""شُفْعَةُ الدَّارِ أَوِ الأَرْضِ أَوِ الْعَقَارِ"": أَيْ حَقُّ تَفْضِيلِ أَحَدِ الْمُشْتَرِينَ عَلَى غَيْرِهِ عِنْدَ عَرْضِهَا لِلْبَيْعِ بِشُرُوطٍ خَاصَّةٍ أَوْ بِعَقْدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11014, 'شَعْرِيَّةٌ', 'شعرية', 'جامد', 'شعر', 'شعرية', 'شعرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""وَضَعَ شَعْرِيَّةً عَلَى النَّافِذَةِ"" : مَا يُوضَعُ عَلَى النَّافِذَةِ مِنْ أَخْشَابٍ أَوْ أَسْلاَكٍ دَقِيقَةٍ ك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11015, 'شِعْرَى', 'شعرى', 'جامد', 'شعر', 'شعرى', 'شعر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', 'N', 'O', 'O', 'O', '', '"شِعْرَى-شِعْرَى [ش ع ر ]. : كَوْكَبٌ نَيِّرٌ يَطْلُعُ بَعْدَ الْجَوْزَاءِ، وَيَكُونُ طُلُوعُهُ فِي شِدَّةِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11016, 'أَشِعَّةٌ', 'أشعة', 'جامد', 'شعع', 'ءشعة', 'شعة', '', '', '', 'مفرد', '', '', '', '"مفردشُعاعٌ"', '', '', '', 'N', 'O', 'O', 'O', '', '". 1.""كانَتْ أَشِعَّةُ الشَّمْسِ مُحْرِقَةً"" : خُيوطٌ ضَوْئِيَّةٌ شَفَّافَةٌ تَخْتَرِقُ الأشْياءَ، وَتَصِلُ الأَرْضَ مِنَ الفَضاءِ الخارِجِيِّ. ""أَشِعَّةٌ نَجْمِيَّةٌ"". 2.""الأَشِعَّةُ السِّينِيَّةُ"". (فيز) : أَشِعَّةٌ مُماثِلَةٌ لِلضَّوْءِ، وَهِيَ مَغْناطيسِيَّةٌ وَأَشَدُّ تَواتُراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11017, 'شُعاعٌ', 'شعاع', 'جامد', '', 'شعاع', 'شعع', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11018, 'شُعَاعٌ', 'شعاع', 'جامد', 'شعع', 'شعاع', 'شعع', '', '', '', 'مفرد', 'DnN', '', '', '"أَشِعَّةٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""شُعَاعُ الشَّمْسِ"" : ضَوْؤُهَا وَيَكُونُ عِبَارَةً عَنْ خُيُوطٍ رَهِيفَةٍ مُمْتَدَّةٍ وَمُشِعَّةٍ. 2.""شُعَاعُ الدَّائِرَةِ"" : قِطْعَةٌ مُسْتَقِيمَةٌ تَصِلُ بَيْنَ الْمَرْكَزِ وَنُقْطَةٍ مِنَ الدَّائِرَةِ وَهُوَ نِصْفُ القُطْرِ. 3.""أَجْرَى فَحْصاً بِالأَشِعَّةِ"" : وَمَضَاتٌ شُعَاعِيَّةٌ ذَاتُ نَفَاذٍ وَتَأْثِيرٍ قَوِيٍّ تُسْتَخْدَمُ فِي الطِّبِّ وَغَيْرِهِ. 4. ""شُعَاعٌ أَخْضَرُ"" : هُوَ لَمَعَانٌ أَخْضَرُ اللَّوْنِ، يُرَى فِي البَحْرِ عِنْدَ مَغِيبِ الشَّمْسِ فِي الأُفُقِ. 5.""الشُّعَاعُ الْمُنْعَكِسُ"" : هُوَ الَّذِي يَرْجِعُ إِلَى الْجِهَةِ الَّتِي أَتَى مِنْهَا بَعْدَ سُقُوطِهِ عَلَى سَطْحٍ، وَتُسَاوِي زَاوِيَةُ الانْعِكَاسِ فِيهِ زَاوِيَةَ السُّقُوطِ. 6.""الشُّعَاعُ السَّاقِطُ"" : هُوَ شُعَاعُ النُّورِ الَّذِي ي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11019, 'أَشِعَّةٌ', 'أشعة', 'جامد', '', 'ءشعة', 'شعة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
