INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11022, 'شَعَفَةٌ', 'شعفة', 'جامد', 'شعف', 'شعفة', 'شعفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"شَعَفَةٌ-شَعَفَةٌ [ش ع ف]. 1.""شَعَفَةُ القَلْبِ"" : رَأْسُهُ، وَالشَّعَفَةُ مِنْ كُلِّ شَيْءٍ أَعْلاَهُ. 2.""شَعَفَةُ الجَبَلِ"" : قِمَّتُهُ. 3.""شَعَفَةُ شَعَرِ الرَّأْسِ"" : خُصْلَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11023, 'شَعَفٌ', 'شعف', 'جامد', 'شعف', 'شعف', 'شعف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَعَفٌ-شَعَفٌ [ش ع ف]. ""أَلَمَّ بِهِ شَعَفُ حُبِّهَا"" : شِدَّةُ حُبِّهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11024, 'شُعْلَةٌ', 'شعلة', 'جامد', 'شعل', 'شعلة', 'شعلة', '', '', '', 'مفرد', 'DnN', '', '', '"شُعَلٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""شُعْلَةُ النَّارِ"" : لَهَبُهَا. 2.""أَخَذَالشُّعْلَةَ وَطَافَ بِهَا أَرْجَاءَ الْمَلْعَبِ"": لَهِيبٌ مُشْعَلٌ فِي عَمُودٍ مُجَوَّفٍ بِدَاخِلِهِ غَازٌ يَنْفُذُ إِلَى أَعْلَى. ""شُعْلَةُ الأَلْعَابِ الأُولُمْبِيَّةِ"". 3.""هُوَ شُعْلَةٌ مِنَ النَّشَاطِ"": ذُو نَشَاطٍ مُتَزَايِدٍ. 4.""هُوَ شُعْلَةٌ مِنَ الذَّكَاءِ"": ذُو ذَكَاءٍ مُتَوَقِّدٍ. 5."" هُوَ شُعْلَةُ نَارٍ"" : أَيْ هُوَ حَادُّ الطَّبْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11025, 'شُعَلٌ', 'شعل', 'جامد', '', 'شعل', 'شعل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11026, 'شَعِيلَةٌ', 'شعيلة', 'جامد', 'شعل', 'شعيلة', 'شعلة', '', '', '', 'مفرد', 'DnN', '', '', '"شُعَلٌ"', '', '', '', '', '', '', '', '', '". ""أَشْعَلَ الشَّعِيلَةَ"" : فَتِيلَ السِّرَاجِ، أَيِ الْفَتِيلَةَ الْمُشْتَعِلَةَ فِي قِنْدِيلٍ أَوْ شَمْعَةٍ. ""شَعِيلَةُ قِنْدِيلٍ"" ""شَعِيلَةُ شَمْعَةٍ""."', '');
