INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11030, 'مَشْعَلٌ', 'مشعل', 'جامد', 'شعل', 'مشعل', 'مشعل', '', '', '', 'مفرد', 'DnN', '', '', '"مَشَاعِلُ"', '', 'R', '', '', '', '', '', '', '". 1. ""أَشْعَلَ المِشْعَلَ"" : مَا يُشْعَلُ مِنَ الْحَطَبِ. 2.""مَشْعَلُ الأَلْعَابِ الأُولَمْبِيَّةِ"" : أَيِ الشُّعْلَةُ، وَهِيَ قِطْعَةٌ مِنَ النَّارِ فِي وِعَاءٍ مِنْ مَعْدِنٍ تَظَلُّ مُشْتَعِلَةً بِصِفَتِها رَمْزاً لِلْقُوَّةِ وَالاِسْتِمْرَارِ."', '');
