INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11032, 'مِشْعَلٌ', 'مشعل', 'جامد', 'شعل', 'مشعل', 'مشعل', '', '', '', 'مفرد', 'DnN', '', '', '"مَشَاعِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِشْعَلُ النَّارِ"" : مَا يُشْعَلُ بِهِ الْحَطَبُ، آلَةُ الشَّعْلِ. 2.: مِصْفَاةٌ."', '');
