INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11036, 'شَعِيرٌ', 'شعير', 'جامد', '', 'شعير', 'شعر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَعِيرٌ-شَعِيرٌ (نب).: نَبَاتٌ مِنْ فَصِيلَةِ النَّجِيلِيَّاتِ يُصْنَعُ مِنْهُ الخُبْزُ وَيُقَدَّمُ عَلَفاً للِدَّوَابِّ، كَمَا تُصْنَعُ مِنْهُ الجِعَةُ عِنْدَ نَقْعِهِ."', ':لا جذر:لا مفرد');
