INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11041, 'شَغَافٌ', 'شغاف', 'جامد', 'شغف', 'شغاف', 'شغف', '', '', '', 'مفرد', 'DnN', '', '', '"شُغُفٌ"', '', 'R', '', '', '', '', '', '', '". ""شَغَافُ القَلْبِ"" : غِلاَفُهُ، حَبَّتُهُ، سُوَيْدَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11042, 'شُغُفٌ', 'شغف', 'جامد', '', 'شغف', 'شغف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11043, 'أَشْغالٌ', 'أشغال', 'جامد', 'شغل', 'ءشغال', 'شغل', '', '', '', 'مفرد', '', '', '', '"مفردشُغْل"', '', '', '', '', '', '', '', '', '". 1.""كانَتْ لَدَيْهِ أَشْغالٌ كَثيرَةٌ"" : أَعْمالٌ. ""أَنْهَيْتُ أَشْغالِي"". 2.""حُكِمَ عَلَيْهِ بِالأشْغالِ الشَّاقَّةِ"" : القِيامُ بِأَعْمالٍ مُرْهِقَةٍ في السِّجْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11044, 'شُغْل', 'شغل', 'جامد', '', 'شغل', 'شغل', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11045, 'مَشْغَلٌ', 'مشغل', 'جامد', 'شغل', 'مشغل', 'مشغل', '', '', '', 'مفرد', 'DnN', '', '', '"مَشَاغِلُ"', '', 'R', '', '', '', '', '', '', '". ""مَشْغَلُ الصِّنَاعَةِ التَّقْلِيدِيَّةِ"" : مَعْمَلٌ صَغِيرٌ، تُزَاوَلُ فِيهِ الأَشْغَالُ اليَدَوِيَّةُ."', '');
