INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11047, 'شَفْرَةٌ', 'شفرة', 'جامد', 'شفر', 'شفرة', 'شفرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":شِفَارٌ"', '', 'R', '', '', '', '', '', '', '". 1.""يَقْطَعُ الْجِلْدَ بِشَفْرَةٍ"" :بِسِكِّينٍ عَظِيمَةٍ حَادَّةٍ. 2.""شَفْرَةُ السَّيْفِ"" : حَدُّهُ. 3.""شَفْرَةُ الحِلاَقَةِ"" : مُوسـىً ذَاتُ حَدَّيْنِ لِلْحِلاَقَةِ. 4.""شَفْرَةُ الإِسْكَافِ"" : إِزْمِيلُهُ. 5. ""مَا بِالدَّارِ شَفْرَةٌ"" : أَيْ لَيْسَ بِهَا أَحَدٌ. 6.""شَفْرَةُ جِهَازِ الأَمْنِ"" : رُمُوزٌ سِرِّيَّةٌ لِلاِتِّصَالِ وَالتَّفَاهُمِ. ""شَفْرَةُ الاتِّصَالاتِ اللاسِلْكِيَّةِ"" ""شَفْرَةُ التَّعْلِيمَاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11048, 'شِفَارٌ', 'شفار', 'جامد', '', 'شفار', 'شفر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11049, 'شُفْرٌ', 'شفر', 'جامد', 'شفر', 'شفر', 'شفر', '', '', '', 'مفرد', 'DnN', '', '', '"أَشْفَارٌ"', '', 'R', '', '', '', '', '', '', '". ""طَلَتْ أَشْفَارَ جَفْنِهَا بِالكُحْلِ"" : أَصْلُ مَنْبِتِ شَعَرِ الْجَفْنِ، الْهُدْبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11050, 'أَشْفَارٌ', 'أشفار', 'جامد', '', 'ءشفار', 'شفر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11051, 'شَفِيرٌ', 'شفير', 'جامد', 'شفر', 'شفير', 'شفر', '', '', '', 'مفرد', 'DnN', '', '', '"أَشْفَارٌ"', '', 'R', '', '', '', '', '', '', '". 1.""رَفْرَفَتْ أَشْفَارُ جَفْنَيْهَا مِنَ الهَلَعِ"" : أَصْلُ مَنْبِتِ شَعَرِ الْجَفْنِ. 2.""كَانَ عَلَى شَفِيرِ الْهَاوِيَةِ"" : عَلَى حَافَّتِهَا. حَتَّى وَقَفُوا عَلَى شَفِيرِ جَهَنَّمَ . (حديث). 3.""شَفِيرُ الوَادِي"" : نَاحِيَتُهُ الْعُلْيَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11052, 'أَشْفَارٌ', 'أشفار', 'جامد', '', 'ءشفار', 'شفر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11053, 'مِشْفَرٌ', 'مشفر', 'جامد', 'شفر', 'مشفر', 'مشفر', '', '', '', 'مفرد', 'DnN', '', '', '"مَشَافِرُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""مِشْفَرُ البَعِيرِ"" : شَفَتُهُ الغَليظَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11054, 'مَشَافِرُ', 'مشافر', 'جامد', '', 'مشافر', 'مشفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11055, 'شَفَّاطَةٌ', 'شفاطة', 'جامد', 'شفط', 'شفاطة', 'شفطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '".: القَصَبَةُ الهَشَّةُ يُشْرَبُ بِهَا مِنَ القِنِّينَةِ أَوِ الكَأْسِ، مَصَّاصَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11056, 'شُفَافَةٌ', 'شفافة', 'جامد', 'شفف', 'شفافة', 'شففة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"شُفَافَةٌ-شُفَافَةٌ [ش ف ف]. 1.""شُفَافَةُ شَرَابٍ"" : مَا تَبَقَّى مِنْهُ فِي كَأْسٍ أَوْ إِنَاءٍ. 2.""شُفَافَةُ النَّهَارِ"" : بَقِيَّتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11057, 'شَفَقَةٌ', 'شفقة', 'جامد', 'شفق', 'شفقة', 'شفقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"شَفَقَةٌ-شَفَقَةٌ [ش ف ق]. 1.""أَظْهَرَ شَفَقَةً عَلَيْهِ"" : عَطْفاً وَحَنَاناً. 2.""يَسْتَحِقُّ الشَّفَقَةَ"" : الرَّحْمَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11058, 'شِفْنِينٌ', 'شفنين', 'جامد', '', 'شفنين', 'شفنن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"شِفْنِينٌ-شِفْنِينٌ (حو). 1.: طَائِرٌ مِنْ فَصِيلَةِ الحَمَامِيَّاتِ، ذَهَبِيُّ اللَّوْنِ، يَكْسُو عُنُقَهُ رِيشٌ طَوِيلٌ، شَبِيهٌ إِلَى حَدٍّ مَّا بِالْحَجَلِ، يَسْبَحُ فِي الْمَاءِ. 2.""الشِّفْنِينُ البَحْرِيُّ"" : جِنْسُ أَسْمَاكٍ بَحْرِيَّة، غُضْرُوفِيَّة، أَنْوَاعُهَا كَثِيرَةٌ، كَبِيرَةُ الحَجْمِ وَالزَّعَانِفِ مُفَلْطَحَةُ الْمُقَدَّمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11059, 'شِفَةٌ', 'شفة', 'جامد', 'شفه', 'شفة', 'شفة', '', '', '', 'مفرد', 'DnN', '', '', '"شِفَاهٌ:شَفَايِفُ"', '', '', '', '', '', '', '', '', '". 1.""شَفَتَا الإِنْسَانِ"" : اللَّحْمَتَانِ الظَّاهِرَتَانِ اللَّتَانِ تَسْتُرَانِ الأَسْنَانَ مِنْ أَعْلَى وَ مِنْ أَسْفَلَ. 2.""اِبْتَسَمَ مِنْ طَرَفِ شَفَتَيْهِ"": ابْتَسَمَ ابْتِسَامَةً خَفِيفَةً. 3.""لَمْ يَنْبِسْ بِبِنْتِ شَفَةٍ"" : لَمْ يُحَرِّكْ سَاكِناً. 4.""بِنْتُ شَفَةٍ"" : الْكَلِمَةُ. 5.""شَفَةُ الصَّحْنِ"": حَافَّتُهُ، حَرْفُهُ. ""شَفَةُ الجَبَلِ"" ""شَفَةُ الدَّلْوِ"". 6.""تَرَدَّدَ اسْمُهُ عَلَى كُلِّ الشِّفَاهِ"" : أَيْ صَارَ اسْمُهُ فِي كُلِّ الأَفْوَاهِ. 7.""أَحْمَرُ الشِّفَاهِ"" : قَلَمٌ ثَخِينٌ مُلَوَّنٌ يُسْتَخْدَمُ لِتَلْوِينِ الشَّفَتَيْنِ. 8.""عَضَّ شَفَتَيْهِ"" : الشُّعُورُ بِالنَّدَمِ. 9.""لَهُ فِي النَّاسِ شَفَةٌ حَسَنَةٌ"" : ذِكْرٌ حَسَنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11060, 'شِفَاهٌ', 'شفاه', 'جامد', '', 'شفاه', 'شفه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11061, 'شَفَايِفُ', 'شفايف', 'جامد', '', 'شفايف', 'شفف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11062, 'شَفَا', 'شفا', 'جامد', 'شفو', 'شفا', 'شف', '', '', '', 'مفرد', 'Dw', '', '', '"أَشْفَاءٌ"', 'ممنوع من الصرف', 'Rw', '', 'N', 'O', 'O', 'O', '', '". 1.""شَفَا الهِلاَلِ"" : بَقِيَّةُ الهِلاَلِ قَبْلَ أَنْ يَخْتَفِيَ. 2.""كَانَ عَلَى شَفَا حُفْرَةٍ"" : عَلَى حَافَّتِهَا، حَرْفُ كُلِّ شَيْءٍ. آل عمران آية 103 وَكُنْتُمْ عَلَى شَفَا حُفْرَةٍ مِنَ النَّارِ فَأَنْقَذَكُمْ مِنْهَا . (قرآن). 3.""مَا بَقِيَ مِنْهُ إِلاَّ شَفَا"" : قَلِيلُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11063, 'أَشْفَاءٌ', 'أشفاء', 'جامد', '', 'ءشفاء', 'شف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11064, 'شَفَوِيَّاتٌ', 'شفويات', 'جامد', '', 'شفويات', 'شفت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"شَفَوِيَّاتٌ-شَفَوِيَّاتٌ (نب).: فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الْفِلْقَتَيْنِ، أَنْوَاعُهَا عَدِيدَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11065, 'شَقِرَّاقٌ', 'شقراق', 'جامد', '', 'شقراق', 'شقرق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ن. شَرَقْرَاقٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11066, 'شَقِرَّاقِيَّاتٌ', 'شقراقيات', 'جامد', '', 'شقراقيات', 'شقرقت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ مِنَ الطُّيُورِ الجَوَاثِمِ، وَمِنْ أَجْنَاسٍ عَدِيدَةٍ، ذَاتُ أَلْوَانٍ مُخْتَلِفَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11067, 'شِقْشِقَةٌ', 'شقشقة', 'جامد', 'شقشق', 'شقشقة', 'شقشقة', '', '', '', 'مفرد', 'DnN', '', '', '"شَقَاشِقُ"', '', 'R', '', '', '', '', '', '', '". 1. : شَيْءٌ كَالرِّئَةِ يُخْرِجُهُ الْجَمَلُ مِنْ فَمِهِ إِذَا هَاجَ وَهَدَرَ. 2.""هُوَ شِقْشِقَةُ الخُطَبَاءِ"" : فَصِيحُهُمْ. 3.""هُوَ شِقْشِقَةُ قَوْمِهِ"" : زَعِيمُهُمُ الْمُتَحَدِّثُ بِاسْمِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11068, 'شَقَاشِقُ', 'شقاشق', 'جامد', '', 'شقاشق', 'شقشق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11069, 'شِقَاقٌ', 'شقاق', 'جامد', 'شقق', 'شقاق', 'شقق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شِقَاقٌ-شِقَاقٌ [ش ق ق]. ""هُوَ مِنْ أَهْلِ الشِّقَاقِ"" : مِنْ أَهْلِ الخِلاَفِ وَالنِّزَاعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11070, 'شُقَّةٌ', 'شقة', 'جامد', 'شقق', 'شقة', 'شقة', '', '', '', 'مفرد', 'DnN', '', '', '"شُقَقٌ"', '', 'R', '', '', '', '', '', '', '". 1.""قَطَعَ الْمُسَافِرُ شُقَّةً"" : مَسَافَةً، أَيِ الْمَسَافَةُ الَّتِي يَقْطَعُهَا الْمُسَافِرُ. 2.""يَعْرِفُ شُقَّتَهُ"" : النَّاحِيَةُ الَّتِي يَقْصِدُهَا الْمُسَافِرُ. 3.""شُقَّةٌ كُرَوِيَّةٌ"" : السَّطْحُ الْمَحْصُورُ بَيْنَ قَوْسَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11071, 'شُقَقٌ', 'شقق', 'جامد', '', 'شقق', 'شق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11072, 'شِقَّةٌ', 'شقة', 'جامد', 'شقق', 'شقة', 'شقة', '', '', '', 'مفرد', 'DnN', '', '', '"شِقَقٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""شِقَّةُ ثَوْبٍ"" : قِطْعَةٌ مِنْهُ. 2. ""يَسْكُنُ فِي شِقَّةٍ جَمِيلَةٍ"" : فِي مَسْكَنٍ، فِي بِنَايَةٍ. ""شِقَقٌ مَسْكُونَةٌ فِي الطَّابَقِ الثَّالِثِ"" ""شِقَقٌ مَفْرُوشَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11073, 'شِقَقٌ', 'شقق', 'جامد', '', 'شقق', 'شق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11074, 'شِقٌّ', 'شق', 'جامد', 'شقق', 'شق', 'شق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شِقٌّ-شِقٌّ [ش ق ق]. 1.""شِقُّ الإِنْسَانِ"" : جَانِبُهُ الْوَاحِدُ. ""نَمْ عَلَى شِقِّكَ الأَيْمَنِ"". 2. ""شِقُّ الخُبْزِ"" : نِصْفُهُ. 3.""حَصَلَ عَلَى نَصِيبِهِ بِشِقِّ الأَنْفُسِ"" : بِمَشَقَّةٍ، بِتَعَبٍ.النحل آية 7 إِلَى بَلَدٍ لَمْ تَكُونُوا بَالِغِيهِ إِلاَّ بِشِقِّ الأَنْفُسِ . (قرآن). 4.""وَقَعَ بَيْنَ شِقَّيْ رَحـىً"" : بَيْنَ الحَجَرَتَيْنِ الْمُسْتَدِيرَتَيْنِ، كِنَايَةً عَمَّا مَا يَعِيشُهُ وَيُحِيطُ بِهِ مِنْ مَشَاكِلَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11075, 'شَقْلَبَانٌ', 'شقلبان', 'جامد', 'شقلب', 'شقلبان', 'شقلبن', '', '', '', 'مفرد', 'DnN', '', '', '"شَقَالِبَةٌ"', '', 'R', '', '', '', '', '', '', '".: الْبَهْلَوَانُ. ""تَحَلَّقَ الأَطْفالُ حَوْلَ الشَّقْلَبانِ يُتابِعونَ حَرَكاتِهِ مَبْهورينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11076, 'شَقَالِبَةٌ', 'شقالبة', 'جامد', '', 'شقالبة', 'شقلبة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11077, 'شَكْوَةٌ', 'شكوة', 'جامد', 'شكو', 'شكوة', 'شكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""أَخَذَ اللَّبَنَ مِنَ الشَّكْوَةِ "": وِعَاءٌ مِنْ جِلْدٍ يُوضَعُ فِيهِ اللَّبَنُ وَيُمْخَضُ، كَما يوضَعُ فيهِ الماءُ، قِرْبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11078, 'شَقِيقيَّاتٌ', 'شقيقيات', 'جامد', '', 'شقيقيات', 'شققت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"شَقِيقيَّاتٌ-شَقِيقيَّاتٌ (نب).: فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الْفِلْقَتَيْنِ مُتَعَدِّدَةُ الأَنْوَاعِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11079, 'شَكْشُوكَةٌ', 'شكشوكة', 'جامد', '', 'شكشوكة', 'شكشكة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"شَكْشُوكَةٌ-شَكْشُوكَةٌ (طخ). : طَعَامٌ تُونُسِيٌّ يُحَضَّرُ مِنْ خَلِيطِ الخُضَرِ مِنْ بَصَلٍ وَبَطَاطَا وَفُلْفُلٍ وَطَمَاطِمَ مَعَ بَيْضٍ وَقِدِّيدٍ أَوْ مَقَانِقَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11080, 'مِشْكَاكٌ', 'مشكاك', 'جامد', 'شكك', 'مشكاك', 'مشكك', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِشْكَاكٌ-مِشْكَاكٌ [ش ك ك]. 1.""مِشْكاَكُ زَهْرٍ"" : إِكْلِيلُ زَهْرٍ. 2.""مِشْكَاكُ بَصَلٍ"" : رَبْطَةٌ مَلْفُوفَةٌ مِنْ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11081, 'مِشَكَّةٌ', 'مشكة', 'جامد', 'شكك', 'مشكة', 'مشكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَشَاكُّ"', '', 'R', '', '', '', '', '', '', '". : مِلْعَقَةٌ لَهَا رُؤُوسٌ مُسَنَّنَةٌ، تُسْتَخْدَمُ لِمَسْكِ الأَطْعِمَةِ مِنَ الْمَاعُونِ، شَوْكَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11082, 'مَشَاكُّ', 'مشاك', 'جامد', '', 'مشاك', 'مشك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11083, 'مِشَكٌّ', 'مشك', 'جامد', 'شكك', 'مشك', 'مشك', '', '', '', 'مفرد', 'DnN', '', '', '"مَشَاكُّ"', '', 'R', '', '', '', '', '', '', '". 1.: أَدَاةٌ يُشَكُّ بِهَا، أَيْ يُخَاطُ بِهَا. 2.: سَيْرٌ يُشَكُّ بِهِ الدِّرْعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11084, 'مَشَاكُّ', 'مشاك', 'جامد', '', 'مشاك', 'مشك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11085, 'تَشْكِيلَةٌ', 'تشكيلة', 'جامد', 'شكل', 'تشكيلة', 'تشكلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَشْكِيلَةٌ-تَشْكِيلَةٌ [ش ك ل].""دَخَلَتِ الفِرْقَةُ الرِّيَاضِيَّةُ بِتَشْكِيلَةٍ جَدِيدَةٍ"" : بِوَحْدَةٍ، بِمَجْموعَةٍ. ""ظَهَرَتْ تَشْكِيلَةٌ مِنَ الطَّائِرَاتِ فِي السَّمَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11086, 'شِكَالٌ', 'شكال', 'جامد', 'شكل', 'شكال', 'شكل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شِكَالٌ-شِكَالٌ [ش ك ل]. ""تَتَخَبَّطُ الدَّابَّةُ فِي شِكَالِهَا "" : الْعِقَالُ، الْقَيْدُ، الْوِثَاقُ، أَيِ الْحَبْلُ الَّذِي يَشُدُّ قَوَائِمَ الدَّوَابِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11087, 'شَكْلَةٌ', 'شكلة', 'جامد', 'شكل', 'شكلة', 'شكلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":شَكْلٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""وَضَعَ شَكْلَةً عَلَى الحَرْفِ"" : الحَرَكَةُ الْوَاحِدَةُ، وَهِيَ الْعَلاَمَةُ الَّتِي تُوضَعُ فَوْقَ الحَرْفِ، أَوْ تَحْتَهُ لِضَبْطِ نُطْقِهِ، أَي الفَتْحَةُ أَوِ الكَسْرَةُ، أَوِ الضَّمَّةُ أَوِ السُّكونُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11088, 'شَكْلٌ', 'شكل', 'جامد', '', 'شكل', 'شكل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11089, 'شُكْلَةٌ', 'شكلة', 'جامد', 'شكل', 'شكلة', 'شكلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"شُكْلَةٌ-شُكْلَةٌ [ش ك ل]. 1.""شُكْلَةُ الأَْلَواِن"" : اِخْتِلاَطُهَا. 2.""شُكْلَةُ الْعَيْنِ"" : حُمْرَةٌ فِي بَيَاضِهَا. 3.""فِيهِ شُكْلَةٌ مِنْ أَبِيهِ"" : شَبَهٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11090, 'شَكِيمَةٌ', 'شكيمة', 'جامد', 'شكم', 'شكيمة', 'شكمة', '', '', '', 'مفرد', 'DnN', '', '', '"شَكَائِمُ"', '', '', '', '', '', '', '', '', '". 1.""شَكِيمَةُ الدَّابَّةِ"" : حَدِيدَةُ اللِّجَامِ. 2.""رَجُلٌ شَدِيدُ الشَّكِيمَةِ"" : عِنْدَهُ إِبَاءٌ وَأَنَفَةٌ، أَبِيٌّ لاَ يَنْقَادُ، حَازِمٌ. ""هُوَ ذُو شَكِيمَةٍ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11091, 'شَكَائِمُ', 'شكائم', 'جامد', '', 'شكاءم', 'شكم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11092, 'شُكُولاَطَةٌ', 'شكولاطة', 'جامد', '', 'شكولاطة', 'شكلطة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": نَوْعٌ مِنَ الْحَلْوَى يَتَكَوَّنُ مِنْ عَجِينِ الكُوكُو الْمَعْقُودِ بِالسُّكَّرِ، وَقَدْ يُخَلَّطُ بِمَوَادَّ أُخْرَى كَاللَّوْزِ، يُجَمَّدُ وَيُشَكَّلُ فِي قَوَالِبَ مُرَبَّعَةٍ أَوْ مُسْتَطِيلَةٍ أَوْ دَائِريَّةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11093, 'شلِيخٌ', 'شليخ', 'جامد', 'شلخ', 'شليخ', 'شلخ', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شلِيخٌ-شلِيخٌ [ش ل خ] (طخ). : طَعَامٌ يُتَّخَذُ مِنَ اللَّحْمِ وَاللَّبَنِ وَالْبَصَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11094, 'شَلاَّلٌ', 'شلال', 'جامد', 'شلل', 'شلال', 'شلل', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""تَتَدَفَّقُ المِياهُ تَدَفُّقاً صاخِباً مِنَالشَّلاَّلِ"" : هُبُوطُ المِيَاهِ مِنْ مُرْتَفَعَاتٍ عَالِيَةٍ لِتَصُبَّ فِي نَهْرٍ عَظِيمٍ. ""وَقَفَ مَشْدُوهاً أَمَامَ عَظَمَةِ شَلاَّلاَتِ نِيَاغَارَا"" 2.""شَلاَّلُ الْعَيْنِ"" (طب): مَرَضٌ يُصِيبُ العَيْنَ فَتَضْعُفُ قُدْرَتُهَا عَلَى الإِبْصَارِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11095, 'مِشَلٌّ', 'مشل', 'جامد', 'شلل', 'مشل', 'مشل', '', '', '', 'مفرد', 'DnN', '', '', '"مَشَالِلُ"', '', 'R', '', '', '', '', '', '', '".: ثَوْبٌ يُغَطَّى بِهِ العُنُقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11096, 'مَشَالِلُ', 'مشالل', 'جامد', '', 'مشالل', 'مشل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11097, 'أَشْلاءٌ', 'أشلاء', 'جامد', 'شلو', 'ءشلاء', 'شل', '', '', '', 'مفرد', '', '', '', '"مفردشِلْو"', '', '', '', '', '', '', '', '', '". 1.""صارَتْ أَعْضاؤُهُ أَشْلاءً"": أَعْضاءُ الجِسْمِ بَعْدَ التَّفَرُّقِ وَالتَّشَتُّتِ. 2.""صارَ أَثاثُ البَيْتِ أَشْلاءً"": مُبَعْثَراً. ""تَحَطَّمَ البَيْتُ أَشْلاءً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11098, 'شِلْوٌ', 'شلو', 'جامد', 'شلو', 'شلو', 'شل', '', '', '', 'مفرد', 'DnN', '', '', '"أَشْلاَءٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""شِلْوُ الإِنْسَانِ"" : عُضْوُهُ. 2. ""أَشْلاَءُ الإِنْسَانِ"" : أَعْضَاؤُهُ بَعْدَ التَّفَرُّقِ وَالْبِلَى. 3.""شِلْوُ لَحْمٍ"" : قِطْعَةٌ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11099, 'أَشْلاَءٌ', 'أشلاء', 'جامد', '', 'ءشلاء', 'شل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11100, 'شِلْوَابٌ', 'شلواب', 'جامد', 'شلوب', 'شلواب', 'شلب', '', '', '', 'مفرد', 'DnN', '', '', '"شَلاَوِيبُ"', '', 'R', '', '', '', '', '', '', '". : مَنْ يَحْذِقُ فَنَّ الشَّلْوَبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11101, 'شَلاَوِيبُ', 'شلاويب', 'جامد', '', 'شلاويب', 'شلب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11102, 'شَمَارٌ', 'شمار', 'جامد', '', 'شمار', 'شمر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"شَمَارٌ-شَمَارٌ (نب).: بَقْلَةٌ عُشْبِيَّةٌ بَرِّيَّةٌ مِنْ فَصِيلَةِ الخَيْمِيَّاتِ، مِنْهُ نَوْعٌ حُلْوٌ، يُزْرَعُ وَيُؤْكَلُ نَيِّئاً، وَنَوْعٌ آخَرُ سُكَّرِيٌّ يُؤْكَلُ مَطْبُوخاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11103, 'شَمَّاسٌ', 'شماس', 'جامد', '', 'شماس', 'شمس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": مُعَاوِنُ الْكَاهِنِ عِنْدَ الْمَسِيحِيِّينَ، وَهِيَ رُتْبَةٌ دُونَ الكَاهِنِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11104, 'شَمَّاسِيَّةٌ', 'شماسية', 'جامد', '', 'شماسية', 'شمسة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '": وَظِيفَةُ الشَّمَّاسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11105, 'شَمَّامٌ', 'شمام', 'جامد', '', 'شمام', 'شمم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"شَمَّامٌ-شَمَّامٌ (نب).: نَوْعٌ مِنَ البَطِّيخِ، مِنْ فَصِيلَةِ القَرْعِيَّاتِ، أَصْفَرُ اللَّوْنِ، قِشْرَتُهُ مُخَطَّطَةٌ بِخُضْرَةٍ وَصُفْرَةٍ، رَائِحَتُهُ طَيِّبَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11106, 'شَمْسٌ', 'شمس', 'جامد', 'شمس', 'شمس', 'شمس', '', '', '', 'مفرد', 'DnN', '', '', '"شُمُوسٌ(مؤ)"', '', 'R', '', '', '', '', '', '', '". 1.""أَشْرَقَتِ الشَّمْسُ"" : كَوْكَبٌ تَدُورُ حَوْلَهُ الأَرْضُ مَعَ سَائِرِ الكَوَاكِبِ الشَّمْسِيَّةِ، وَهُوَ الَّذِي يَمُدُّهَا بِالضَّوْءِ وَالْحَرَارَةِ. 2.""نَفْحَةُ شَمْسٍ"" : لَفْحَةُ شَمْسٍ، صُدَاعٌ فِي الرَّأْسِ وَالْجِسْمِ يُسَبِّبُ ارْتِفَاعَ الْحَرَارَةِ بِسَبَبِ التَّعَرُّضِ لأَشِعَّة الشَّمْسِ القَوِيَّةِ. 3.""لاَ جَدِيدَ تَحْتَ الشَّمْسِ"" : لاَ جَدِيدَ يُذْكَرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11107, 'شُمُوسٌ', 'شموس', 'جامد', '', 'شموس', 'شمس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11108, 'شَمَّاعَةٌ', 'شماعة', 'جامد', 'شمع', 'شماعة', 'شمعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""عَلَّقَ مَلاَبِسَهُ عَلَى الشَّمَّاعَةِ"" : الْمِشْجَب الَّذِي تُعَلَّقُ عَلَيْهِ الْمَلاَبِسُ، وَهُوَ عِبَارَةٌ عَنْ قِطْعَةٍ مِنَ الخَشَبِ، أَوْ مَعْدِنٍ وَنَحْوِهِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11109, 'شَمْعَدَانٌ', 'شمعدان', 'جامد', 'شمع', 'شمعدان', 'شمعدن', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":شَمَاعِدُ"', '', 'R', '', '', '', '', '', '', '". : مَنَارَةٌ صَغِيرَةٌتُرَكَّزُ عَلَيْهَا الشّمُوعُ الْمُشَمَّعَةُ."', '');
