INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11112, 'شَمْعَةٌ', 'شمعة', 'جامد', '', 'شمعة', 'شمعة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":شَمْعٌ:شُمُوعٌ"', '', 'R', '', '', '', '', '', '', '"ج: شَمْعٌ، شُمُوعٌ، شَمْعَاتٌ. 1.""أَشْعَلَ شَمْعَةً فِي كُوخِهِ"" :مَادَّةٌ دُهْنِيَّةٌ بِهَا فَتِيلٌ فِي وَسَطِهَا يُشْعَلُ لِيُسْتَضَاءَ بِهِ. ""صِغَارُ بِلاَدِي شُمُوعٌ مُضيئَةٌ"" (أدونيس). 2.""عِشْرُونَ شَمْعَةً"": وَحْدَةٌ تُقَاسُ بِهَا ق"', ':لا جذر:لا مفرد');
