INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11141, 'شِهَابٌ', 'شهاب', 'جامد', 'شهب', 'شهاب', 'شهب', '', '', '', 'مفرد', 'DnN', '', '', '"شُهُبٌ:أَشْهُبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""يَتَلَأْلَأُ شِهَابُ النَّارِ"" : الشُّعْلَةُ الْمُضِيئَةُ مِنَ النَّارِ. 2.""تَسْطَعُ شُهُبٌ لاَمِعَةٌ فِي السَّمَاءِ"" : مَا يُرَى كَأَنَّهُ نُجُومٌ تَهْوِي مِنَ السَّمَاءِ .الصافات آية 10 فَأَتْبَعَهُ شِهَابٌ ثَاقِبٌ . (قرآن)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11142, 'شُهُبٌ', 'شهب', 'جامد', '', 'شهب', 'شهب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
