INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11148, 'شَاهِدَةٌ', 'شاهدة', 'جامد', 'شهد', 'شاهدة', 'شهدة', '', '', '', 'مفرد', 'DnN', '', '', '"شَوَاهِدُ"', '', '', '', '', '', '', '', '', '". 1.""شَاهِدَةُ قَبْرٍ"" : حَجَرٌ مُسْتَطِيلٌ يُوضَعُ على قَبْرِهِ. 2. : أرْضٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11149, 'شَوَاهِدُ', 'شواهد', 'جامد', '', 'شواهد', 'شهد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11150, 'شُهْدٌ', 'شهد', 'جامد', 'شهد', 'شهد', 'شهد', '', '', '', 'مفرد', 'DnN', '', '', '"شِهَادٌ"', '', 'R', '', '', '', '', '', '', '". ""يَأْخُذُ الشُّهْدَ مِنْ شَمْعِهِ"" : عَسَلُ النَّحْلِ مَادَامَ لَمْ يُعْصَرْ مِنْ شَمْعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11151, 'شِهَادٌ', 'شهاد', 'جامد', '', 'شهاد', 'شهد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11152, 'شُهْدَةٌ', 'شهدة', 'جامد', '', 'شهدة', 'شهدة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '": القِطْعَةُ مِنَ الشَّهْدِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11153, 'شُهْرَةٌ', 'شهرة', 'جامد', 'شهر', 'شهرة', 'شهرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"شُهْرَةٌ-شُهْرَةٌ [ش هـ ر]. ""يَتَمَتَّعُ بِشُهْرَةٍ دَوْلِيَّةٍ"" : انْتِشَارُ اسْمِهِ عَلَى نِطَاقٍ وَاسِعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11154, 'مَشَاهِيرُ', 'مشاهير', 'جامد', 'شهر', 'مشاهير', 'مشهر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَشَاهِيرُ-مَشَاهِيرُ [ش هـ ر]. ن. مَشْهُورٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11155, 'شُهَاقٌ', 'شهاق', 'جامد', 'شهق', 'شهاق', 'شهق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شُهَاقٌ-شُهَاقٌ [ش هـ ق]. : مَرَضٌ مُعْدٍ وَخَاصَّةً بَيْنَ الأَطْفَالِ يُحْدِثُ سُعَالاً حَادّاً يُعْرَفُ بِالسُّعَالِ الدِّيكِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11156, 'شُهْلَةٌ', 'شهلة', 'جامد', 'شهل', 'شهلة', 'شهلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"شُهْلَةٌ-شُهْلَةٌ [ش هـ ل]. ""عَيْنٌ بِهَا شُهْلَةٌ"" : اِخْتِلاَطُ سَوَادِهَا بِزُرْقَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11157, 'شاهِيَةٌ', 'شاهية', 'جامد', 'شهو', 'شاهية', 'شهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شاهِيَةٌ-شاهِيَةٌ [ش هـ و]. ""يَمْلِكُ شَاهِيَةً لِلأَكْلِ"" : شَهِيَّةً، شَهْوَةً، الرَّغْبَة فِي الأَكْلِ. ""يَأْكُلُ بِلاَ شَاهِيَةٍ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11158, 'شَاشَةٌ', 'شاشة', 'جامد', 'شوش', 'شاشة', 'ششة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَاشَةٌ-شَاشَةٌ [ش و ش]. 1.""شَاشَةُ السِّينِمَا"" : سِتَارٌ أبْيَضُ مُسْتَطِيلٌ، تُعْرَضُ عَلَيْهِ صُوَرُ الأَفْلاَمِ الصَّادِرَةِ مِنْ صَوَّارَةِ التَّسْجِيلِ. (كاميرا). 2.""الشَّاشَةُ الصَّغِيرَةُ"" : التَّلْفَزَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11159, 'مُشَهِّيَاتٌ', 'مشهيات', 'جامد', 'شهي', 'مشهيات', 'مشهت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُشَهِّيَاتٌ-مُشَهِّيَاتٌ [ش هـ ي]. ""مُشَهِّيَاتُ الطَّعَامِ"" : أَنْوَاعُ السَّلاَطَةِ تُقَدَّمُ فِي أَوَّلِ الأَكْلِ، وَمِنْهَا أَيْضاً الْمُخَلَّلاَتُ وَالْمُمَلَّحَاتُ وَنَحْوُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11160, 'شُوَارٌ', 'شوار', 'جامد', '', 'شوار', 'شر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1.""شُوَارُ البَيْتِ"" : مَتَاعُهُ. 2.""شُوَارُ العَرُوسِ"" : جِهَازُهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11161, 'شَوَّالٌ', 'شوال', 'جامد', '', 'شوال', 'شل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ العَاشِرُ مِنَ السَّنَةِ القَمَرِيَّةِ يَأْتِي بَعْدَ ذِي القِعْدَةِ وَيَلِيهِ رَمَضَانُ، عَدَدُ أَيَّامِهِ (30) يَوْماً أو (29) يَوْماً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11162, 'شَوَائِبُ', 'شوائب', 'جامد', 'شوب', 'شواءب', 'شب', '', '', '', 'مفرد', '', '', '', '"مفردشَائِبَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""عَمَلُهُ خَالٍ مِنَ الشَّوَائِبِ"" : مِنَ العُيُوبِ وَالرَّذَائِلِ وَكُلِّ مَا يُدَنِّسُ. 2.""لَيْسَ فِي ثَوْبِ الْحَرِيرِ شَائبَةٌ"" : أَيْ لَيْسَ بِهِ مَادَّةٌ مِنْ أَيِّ نَسِيجٍ آخَرَ غَيْرِ الْحَرِيرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11163, 'شَارَةٌ', 'شارة', 'جامد', 'شور', 'شارة', 'شرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""شَارَاتُ الْمُرُورِ"" : عَلاَمَاتُ الْمُرُورِ. 2.""يَحْمِلُ شَارَةَ ذِرَاعٍ حَمْرَاءَ"" : شَرِيطُ ثَوْبٍ يُوضَعُ عَلَى الذِّرَاعِ إِعْلاناً عَنِ الإِضْرابِ. 3.""مُنِحَ شَارَةً"": وِسَاماً. 4.""كَانَتْ شَارَتُهُ علَى أحْسَنِ مَا يُرَامُ"" : هيْئَتُهُ، هِنْدَامُهُ، مَنْظَرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11164, 'شُوَاظٌ', 'شواظ', 'جامد', 'شوظ', 'شواظ', 'شظ', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شُوَاظٌ-شُوَاظٌ [ش و ظ] 1. ""شُوَاظُ النّارِ"" : وَهْجُها، لَهِيبُها.الرحمن آية 35 يُرْسَلُ عَلَيْكُمَا شُوَاظٌ مِنْ نَارٍ وَنُحَاسُّ فَلاَ تَنْتَصِرَانِ . (قرآن). 2. ""شُوَاظُ النَّهارِ"" : حَرُّها. ""تَنْتَعِشُ النُّفُوسُ مِنْ هَبَّاتِ النَّسِيمِ وَتُنْسِي شُوَاظَ النَّهَارِ"". (محمد برادة). 3.""اِشْتَدَّ الشُّوَاظُ"" : اللَّهَبُ لاَ دُخَانَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11165, 'مِشْوَارٌ', 'مشوار', 'جامد', 'شور', 'مشوار', 'مشر', '', '', '', 'مفرد', 'DnN', '', '', '"مَشَاوِيرُ"', '', 'R', '', '', '', '', '', '', '". ""خَرَجَ فِي مِشْوَارٍ"": فِي جَوْلَةٍ قَصِيرَةٍ مُحَدَّدَةٍ بِمَسَافَةٍ يَقْطَعُهَا السَّائِرُ. ""عَادَ مِنْ مِشْوَارِهِ الْمَعْهُودِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11166, 'مَشَاوِيرُ', 'مشاوير', 'جامد', '', 'مشاوير', 'مشر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11167, 'شَوْكَةٌ', 'شوكة', 'جامد', '', 'شوكة', 'شكة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":الواحدةمِنَالشَّوْكِ"', '', 'R', '', '', '', '', '', '', '"الوَاحِدَةُ مِنَ الشَّوْكِ. 1.""وَخَزَهُ بِشَوْكَةٍ"" : عُودٌ صَغِيرٌ حَادٌّشَبِيهٌ بِرَأْسِ الإِبْرَةِ. 2.""شَوْكَةُ العَقْرَبِ"" : شَوْلَتُها إِبْرَتُهَا. 3.""يَأْكُلُ بِالشَّوْكَةِ وَالسِّكِّينِ"" : أَدَاةٌ مِنْ مَعْدِنٍ لَهَا رُؤُوسٌ مُسَنَّنَةٌ يُتَنَاوَلُ بِهَا الطَّعَامُ. 4.""كَانَ عَنِيداً فَكَسَرَ شَوْكَتَهُ"" : أَيْ أَخْضَعَهُ وَكَسَّرَ بَأْسَهُ وَقُ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11168, 'شَوْكِ', 'شوك', 'جامد', '', 'شوك', 'شك', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11169, 'شَوْلَةٌ', 'شولة', 'جامد', 'شول', 'شولة', 'شلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"شَوْلَةٌ-شَوْلَةٌ [ش و ل]. 1.""شَوْلَةُ العَقْرَبِ"" : ما تَرْفَعُهُ مِنْ ذَنَبِها، شَوْكَتُها، إِبْرَتُها. 2.""وَضَعَ الشَّوْلَةَ بَيْنَ الجُمْلَتَيْنِ"" : الفَصْلَةُ، وَهي عَلامَةٌ مِن عَلامات"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11170, 'شَوْنَةٌ', 'شونة', 'جامد', 'شون', 'شونة', 'شنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '".: بِنَايَةٌ لِتَخْزِينِ الْحَصَائِدِ وَالتِّبْنِ وَالعَلَفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11171, 'شَاةٌ', 'شاة', 'جامد', 'شوه', 'شاة', 'شة', '', '', '', 'مفرد', 'DnN', '', '', '"شِيَاهٌ"', '', '', '', '', '', '', '', '', '".: الوَاحِدَةُ مِنَ ذَوَاتِ الظِّلْفِ، النَّعامُ، أي الضَّأْنُ أَوِ الْمَعِزُ أَوِ الظِّبَاءُ أوِ البَقَرُ أوِ النَّعَامُ لِلذَّكَرِ وَالأُنْثَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11172, 'شِيَاهٌ', 'شياه', 'جامد', '', 'شياه', 'شه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11173, 'شُوهَةٌ', 'شوهة', 'جامد', 'شوه', 'شوهة', 'شهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"شُوهَةٌ-شُوهَةٌ [ش و هـ]. 1.""بَيْنَهُمَا شُوهَةٌ"" : بُعْدُ مَسَافَةٍ. 2.""يَا لَهَا مِنْ شُوهَةٍ"" : مِنْ قُبْحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11174, 'شَوَاةٌ', 'شواة', 'جامد', 'شوي', 'شواة', 'شة', '', '', '', 'مفرد', '', '', '', '"واحدةالشَّوَة"', '', '', '', '', '', '', '', '', '"شَوَاةٌ-شَوَاةٌ [ش و ي].: وَاحِدَةُ الشَّوَة.الشَّوَاةُ  [شوي]: واحدةُ الشَّوَى، وهي أطراف الجسم. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11175, 'شَوِيَّةٌ', 'شوية', 'جامد', 'شوي', 'شوية', 'شة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"شَوِيَّةٌ-شَوِيَّةٌ [ش و ي]. ""تَنَاوَلَ شَوِيَّةً مِنَ اللَّحْمِ وَالْخُبْزِ"" : قِطْعَةً صَغِيرَةً مِنَ اللَّحْمِ وَالْخُبْزِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11176, 'شَوْكٌ', 'شوك', 'جامد', 'شوك', 'شوك', 'شك', '', '', '', 'مفرد', 'DnN', '', '', '"أَشْوَاكٌ"', '', 'R', '', '', '', '', '', '', '". ""شَوْكُ الوَرْدِ"" : مَا يَنْبُتُ عَلَى سَاقِ الوَرْدِ أَوْ بَعْضِ النَّبَاتِ يُشْبِهُ رَأْسَ الإِبَرِ وَهُوَ حَادٌّ. ""لاَ يُثْمِرُ الشَّوْكُ العِنَبَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11177, 'أَشْوَاكٌ', 'أشواك', 'جامد', '', 'ءشواك', 'شك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11178, 'شَوَى', 'شوى', 'جامد', 'شوي', 'شوى', 'ش', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَوَى-شَوَى [ش و ي]. 1.""شَوَى الْجَسَدِ"" : أَطْرَافُهُ. 2.""فَرَسٌ عَبْلُ الشَّوَى"" : ضَخْمُ القَوَائِمِ. 3.""شَوَى الْجِسْمِ"" : ظَاهِرُ الْجِلْدِ. المعارج آية "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11179, 'مِشْوَاةٌ', 'مشواة', 'جامد', 'شوي', 'مشواة', 'مشة', '', '', '', 'مفرد', 'DnN', '', '', '"مَشَاوٍالْمَشَاوِي"', '', '', '', '', '', '', '', '', '". ""مِشْوَاةُ اللَّحْمِ"" : آلَةُ شَيِّ اللَّحْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11180, 'مَشَاوِي', 'مشاوي', 'جامد', '', 'مشاوي', 'مش', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11181, 'شِيعَةٌ', 'شيعة', 'جامد', 'شيع', 'شيعة', 'شعة', '', '', '', 'مفرد', 'DnN', '', '', '"شِيَعٌ:أَشْيَاعٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""هُوَ مِنْ شِيعَتِهِ"": مِنْ فِرْقَتِهِ، أَيِ الفِرْقَةُ الْمُجْتَمِعَةُ عَلَى أَمْرٍ مَّا. 2.""مِنْ أَهْلِ الشِّيعَةِ"": فِرْق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11182, 'شِيَعٌ', 'شيع', 'جامد', '', 'شيع', 'شع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11183, 'أَشْيَاعٌ', 'أشياع', 'جامد', '', 'ءشياع', 'شع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11184, 'شَيْءٌ', 'شيء', 'جامد', 'شيأ', 'شيء', 'ش', '', '', '', 'مفرد', 'Dz', '', '', '"أَشْيَاءٌ"', '', 'Rz', '', '', '', '', '', '', '". 1.""خَلَقَ اللَّهُ كُلَّ شَيْءٍ"" : أَيْ كُلَّ مَا لَهُ وُجُودٌ مُثْبَتٌ مُتَحَقِّقٌ.البقرة آية 284 وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِير . (قرآن) ""لَيْسَ كَمِثْلِهِ شَيْءٌ"". 2.""يُرِيدُ شَيْئاً فَشَيْئاً مِنَ الطَّعَامِ"" : قَلِيلاً مِنْهُ، بَعْضَهُ. 3.""يَتَقَدَّمُ شَيْئاً فَشَيْئاً"" : قَلِيلاً قَلِيلاً، خُطْوَةً خُطْوَةً. ""شَيْءٌ مِنَ الْحَيَاءِ"" ""شَيْءٌ مِنَ التَّعَبِ"" ""شَيْءٌ مِنَ الوَقْتِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11185, 'أَشْيَاءٌ', 'أشياء', 'جامد', '', 'ءشياء', 'ش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11186, 'مَشِيئَةٌ', 'مشيئة', 'جامد', 'شيأ', 'مشيءة', 'مشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""كُلُّ شَيْءٍ بِمَشِيئَةِ اللَّهِ"": بِإِرادَةِ اللَّهِ وَمَا يُرِيدُهُ لِعِبَادِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11187, 'شِيتَةٌ', 'شيتة', 'جامد', 'شيت', 'شيتة', 'شتة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""شَيَّتَ أَسْنَانَهُ بِالشِّيتَةِ"" : فُرْشَاةُ الأَسْنَانِ. 2.""شِيتَةُ الْمَلاَبِسِ"" : أَدَاةٌ مِنْ خَشَبٍ أَوْ غَيْرِهِ تَحْمِلُ شُعَيْرَاتٍ دَقِيقَةً تُسْتَعْمَلُ لِتَنْقِيَةِ الْمَلاَبِسِ وَحَكِّهَا لإِزَالَةِ مَا عَلِقَ بِهَا مِنْ وَسَخٍ أَوْ أَتْرِبَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11188, 'كَيْفِيَّةٌ', 'كيفية', 'جامد', 'كيف', 'كيفية', 'كفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(صف). : هَيْئَةُ الشَّيْءِ، الطَّرِيقَةُ. 1.""كَيْفِيَّةُ تَنَاوُلِ الدَّوَاءِ"" : أَيْ طَرِيقَةُ تَنَاوُلِهِ. ""مَا الكَيْفِيَّةُ الَّتِي يَنْبَغِي اتِّبَاعُهَا"". 2.""كَيْفِيَّةُ الصُّورَةِ"" : صِفَتُهَا، حَالَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11189, 'حَوَرٌ', 'حور', 'جامد', 'حور', 'حور', 'حر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَوَرٌ-حَوَرٌ [ح و ر] (صف). ""فِي عَيْنَيْهَا حَوَرٌ"" : شِدَّةُ بَيَاضِ العَيْنِ مَعَ شِدَّةِ سَوَادِهَا. ""تَألَّقَتْ عَيْنَاهَا حَتَّى بَدَا حَوَرُهُمَا سَاطِعاً"" (ن. محفوظ) إنَّ العُيُونَ الَّتِي فِي طَرْفِهَا حَوَر*قَتَلْنَنَا ثُمَّ لَمْ يَحْيِينَ قَتْلاَنَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11190, 'حَدَبَةٌ', 'حدبة', 'جامد', 'حدب', 'حدبة', 'حدبة', 'صف', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَدَبَةٌ-حَدَبَةٌ [ح د ب] (صف). ""في ظَهْرِهِ حَدَبَةٌ"" : بُروزُ تَوَرُّمٍ أَوْ نُتوءٍ صَلْبٍ في ظَهْرِ الإِنْسانِ يَجْعَلُهُ مُرْتَفِعاً إلى أَعْلَى وَصَدْرُهُ وَبَطْنُهُ داخِلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11191, 'شِيحٌ', 'شيح', 'جامد', '', 'شيح', 'شح', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"شِيحٌ-شِيحٌ (نب).: نَبَاتٌ عُشْبِيٌّ بَرِّيٌّ، مِنْ فَصِيلَةِ الْمُرَكَّبَاتِ، لَهُ رَائِحَةٌ طَيِّبَةٌ قَوِيَّةٌ، يُسْتَعْمَلُ فِي الطِّبِّ، تَرْعَاهُ الْمَاشِيَةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11192, 'شَيْخٌ', 'شيخ', 'جامد', 'شيخ', 'شيخ', 'شخ', '', '', '', 'مفرد', 'DnN', '', '', '"شُيُوخٌ:أَشْيَاخٌ:مَشْيَخَةٌج', '', 'R', '', '', '', '', '', '', '". 1.""صَارَ شَيْخاً"" : أَيْ رَجُلاً مُسِنّاً وَقَدْ ظَهَرَتْ عَلَيْهِ مَلاَمِحُ الشَّيْخُوخَةِ. 2.""هُوَ شَيْخُ العُلَمَاءِ"" : كَبِيرُهُمْ وَتُطْلَقُ عَلَى العَالِمِ وَكَبِيرِ الطَّرِيقَةِ، وَمَنْ يَكُونُ لَهُ مَقَامٌ أَوْ فَضْلٌ أَوْ عِلْمٌ بَيْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11193, 'شُيُوخٌ', 'شيوخ', 'جامد', '', 'شيوخ', 'شخ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11194, 'أَشْيَاخٌ', 'أشياخ', 'جامد', '', 'ءشياخ', 'شخ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11195, 'مَشْيَخَةٌ', 'مشيخة', 'جامد', '', 'مشيخة', 'مشخة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11196, 'مَشَايِخُ', 'مشايخ', 'جامد', '', 'مشايخ', 'مشخ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11197, 'شَيْخُوخَةٌ', 'شيخوخة', 'جامد', 'شيخ', 'شيخوخة', 'شخخة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"شَيْخُوخَةٌ-شَيْخُوخَةٌ [ش ي خ]. ""ظَهَرَتِ الشَّيْخُوخَةُ عَلَى مَلاَمِحِهِ"" : مَرْحَلَةٌ مِنْ مَرَاحِلِ العُمْرِ تَبْدَأُ مِنْ سِنِّ الْخَمْسِينَ فَما فَوْق."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11198, 'شِيدٌ', 'شيد', 'جامد', 'شيد', 'شيد', 'شد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شِيدٌ-شِيدٌ [ش ي د]. ""طَلَى الْحَائِطَ بِالشِّيدِ"" : مَا يُطْلَى بِهِ مِنْ جِصٍّ أَوْ صِبَاغَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11199, 'شِيشٌ', 'شيش', 'جامد', '', 'شيش', 'شش', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1. : نَوْعٌ مِنَ السُّيُوفِ الدَّقِيقَـةِ وَالْخَفِيفَـةِ تُحِيطُ بِمَقْبَضِهِدَائِرَةٌ كُرَوِيَّةٌ صَغِيرَةٌ، يُتَمَرَّسُ بِهَا فِي"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11200, 'شِيشَةٌ', 'شيشة', 'جامد', '', 'شيشة', 'ششة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '": ""مُدْمِنٌ عَلَى الشِّيشَةِ"" : عَلَى النَّارْجِيلَةِ، تُسْتعْمَلُ فِي التَّدْخِينِ. ن. نارجيلة."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11201, 'شِيَاطٌ', 'شياط', 'جامد', 'شيط', 'شياط', 'شط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شِيَاطٌ-شِيَاطٌ [ش ي ط]. ""يَفُوحُ مِنَ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11202, 'شَيْطَانٌ', 'شيطان', 'جامد', 'شيط', 'شيطان', 'شطن', '', '', '', 'مفرد', 'DnN', '', '', '"شَيَاطِينُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""اِحْذَرِ الشَّيْطَانَ"": الرُّوحُ الشِّرِّيرُ الَّذِي يَرْمِي بِكَ للتَّهْلُكَةِ لِبُعْدِهِ عَنِ الْخَيْرِ وَطَرِيقِ الْحَقِّ. ""أَعُوذُ باللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ""البقرة آية 168 وَلاَ تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ . (قرآن). 2.""يَا لَهُ مِنْ وَلَدٍ شَيْطَانٍ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11203, 'شَيَاطِينُ', 'شياطين', 'جامد', '', 'شياطين', 'شطن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11204, 'شَائِعَةٌ', 'شائعة', 'جامد', 'شيع', 'شاءعة', 'شعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":شوَائِعُ"', '', '', '', '', '', '', '', '', '"شَائِعَةٌ - ج: شوَائِعُ، شَائِعَاتٌ. [ش ي ع]. ""إنَّهَا مُجَرَّدُ شَائِعَةٍ"" : خَبَرٌ لاَ أَسَاسَ لَهُ مِنَ الصِّحَّةِ ذَائِعٌ بَيْنَ النَّاسِ.   ""يَبْحَثُ عَنْ مَصْدَرِ الشَّائِعَاتِ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11205, 'شوَائِعُ', 'شوائع', 'جامد', '', 'شواءع', 'شع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11206, 'شِيكٌ', 'شيك', 'جامد', '', 'شيك', 'شك', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"1. ""أَعْطَاهُ شِيكاً لِيَسْحَبَهُ مِنَ الْمَصْرِفِ"" : وَرَقَةٌ بَنْكِيَّةٌ لِشَخْصٍ مَّا لَهُ حِسَابٌ فِي الَمْصَرِفِ، يَتِمُّ بِمُقْتَضَاهَا سَحْبُ القَدْرِ الْمَالِيّ الْمَكْتُوبِ عَلَيْهِ، الصَّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11207, 'شَالٌ', 'شال', 'جامد', 'شيل', 'شال', 'شل', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""وَضَعَتْ عَلَى شَعْرِهَا شَالاً صَغِيراً بِلَونٍ يتَنَاسَبُ مَع المِعْطَفِ الرَّمَادِيِّ"" : قِطْعَةٌ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11208, 'شَيَّالَةٌ', 'شيالة', 'جامد', 'شيل', 'شيالة', 'شلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شَيَّالَةٌ - [ش ي ل]. ""رَفَعَ القِدْرَ بِالشَّيَّالَةِ"" : أَدَاةٌ أَوْ خِرْقَةٌ تُرْفَعُ بِهَا القِدْرُ عَنِ النَّارِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11209, 'شَيَّالٌ', 'شيال', 'جامد', 'شيل', 'شيال', 'شل', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"شَيَّالٌ - [ش ي ل]. ""نَادَى عَلَى الشَّيَّالِ لِيَحْمِلَ حَقَائِبَهُ"": الْحَمَّالُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11210, 'صَابُوغَةٌ', 'صابوغة', 'جامد', '', 'صابوغة', 'صبغة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"(حو).: جِنْسُ سَمَكٍ مِنْ فَصِيلَةِ الصَّابُوغِيَّاتِ، كَبِ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11211, 'صَابُوغِيَّاتٌ', 'صابوغيات', 'جامد', '', 'صابوغيات', 'صبغت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةُ أَسْمَاكٍ مُتَعَدِّدَةُ الأَجْنَاسِ، مِن"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11212, 'صَالَةٌ', 'صالة', 'جامد', '', 'صالة', 'صلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"ج: ـات. 1.: مَكَانٌ فَسِيحٌ فِي وَسَطِ الْمَسْكَنِ يُوصِلُ إِلَى سَائِرِ الْحُجُرَاتِ، الرَّدْهَةُ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11213, 'صَامِغٌ', 'صامغ', 'جامد', '', 'صامغ', 'صمغ', '', '', '', 'جمع تكسير', '', '', '', '"مثنىصَامِغَانِ-الصَّامِغَانِ"', '', '', '', '', '', '', '', '', '": جَانِبَا الفَمِ عِنْدَ مُلْتَقَى الشَّفَتَيْنِ مِمَّا يَلِي الشِّدْقَيْنِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11214, 'صَابِئَةٌ', 'صابئة', 'جامد', 'صبأ', 'صابءة', 'صبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"صَابِئَةٌ-صَابِئَةٌ [ص ب أ].: قَوْمٌ كانوا يَعْبُدُونَ النُّجُومَ وَالكَوَاكِبَ، وَيَزْعُمُو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11215, 'صَبَّارٌ', 'صبار', 'جامد', '', 'صبار', 'صبر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"صَبَّارٌ-صَبَّارٌ (نب).: نَبَاتٌ مِنْ فَصِيلَةِ الصَّبَّارِيَّاتِ، يَتَكَيَّفُ مَعَ الْمَنَاطِقِ الْحَارَّةِ، أَوْرَاقُهُ مُدَوَّرَةٌ سَمِيكَةٌ شَائِكَةٌ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11216, 'صَبَّارِيَّاتٌ', 'صباريات', 'جامد', '', 'صباريات', 'صبرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ، أَجْنَاسُهَا عَدِيدَةٌ، تَتَكَيَّفُ مَعَ الْمَنَاطِقِ الْحَارَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11217, 'صُبَابَةٌ', 'صبابة', 'جامد', 'صبب', 'صبابة', 'صببة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صُبَابَةٌ - ج: ـات. [ص ب ب]. 1.""صُبَابَةُ الإِنَاءِ"" : أَيْ بَقِيَّتُهُ القَلِيلَةُ مِنَ الْمَاءِ وَنَحْوِهِ. 2.""لَمْ أُدْرِكْ مِنَ العَيْشِ إِلاَّ صُبَابَةً"" : أَيْ إِلاَّ بَقِيَّةً، أَيِ القَلِيلَ مِنْه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11218, 'أُصْبوحَة', 'أصبوحة', 'جامد', 'صبح', 'ءصبوحة', 'صبحة', '', '', '', 'مفرد', 'DnN', '', '', '"أَصابيحُ"', '', 'R', '', '', '', '', '', '', '"أُصْبوحَة-أُصْبوحَةٌ [ص ب ح]. ج: أَصابيحُ. ن. الصّباح."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11219, 'أَصابيحُ', 'أصابيح', 'جامد', '', 'ءصابيح', 'صبح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11220, 'صَبَاحٌ', 'صباح', 'جامد', 'صبح', 'صباح', 'صبح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَبَاحٌ-صَبَاحٌ [ص ب ح]. 1.""اِسْتَيْقَظَ فِي الصَّبَاحِ البَاكِرِ"" : فِي بِدَايَةِ أَوَّلِ النَّهَارِ. 2.""صَبَاحُ الْخَيْرِ"" : عِبَارَةٌ لِلتَّحِيَّةِ تُسْتَعْمَلُ فِي مَطْلَعِ النَّهَارِ، لِيَكُنْ يَوْمُكَ هَنِيئاً مُرِيحاً. ""عِمْ صَبَاحاً"". 3.""حَدَّدَ مَوْعِداً مَعَهُ عَلَى السَّاعَةِ التَّاسِعَةِ صَبَاح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11221, 'صُبْحٌ', 'صبح', 'جامد', 'صبح', 'صبح', 'صبح', '', '', '', 'مفرد', 'DnN', '', '', '"أَصْبَاحٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِنْبَلَجَ الصُّبْحُ"" : ظَهَرَ أَوَّلُ ضَوْءِ الصَّبَاحِ. 2.""خَرَجَ لِيُؤَدِّيَ صَلاَةَ الصُّبْحِ"" : الصَّلاَةُ الأُولَى مِنَ الص"', '');
