INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11223, 'صُبْحِيَّةٌ', 'صبحية', 'جامد', 'صبح', 'صبحية', 'صبحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"صُبْحِيَّةٌ-صُبْحِيَّةٌ [ص ب ح]. ""يَبْدَأُ عَمَلَهُ مُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11224, 'صَبُوحٌ', 'صبوح', 'جامد', 'صبح', 'صبوح', 'صبح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَبُوحٌ-صَبُوحٌ [ص ب ح]. 1.""سَقَاهُ الصَّبُوحَ"" : سَقَاهُ شَرَابَ الصَّبَاحِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11225, 'مَصَابِيحُ', 'مصابيح', 'جامد', 'صبح', 'مصابيح', 'مصبح', '', '', '', 'مفرد', '', '', '', '"مفردمِصْبَاحٍ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ن. مِصْبَاحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11226, 'مِصْبَاحٌ', 'مصباح', 'جامد', 'صبح', 'مصباح', 'مصبح', '', '', '', 'مفرد', 'DnN', '', '', '"مَصَابِيحُ"', '', 'R', '', '', '', '', '', '', '". 1. ""أَضَاءَ نُورُ المِصْبَاحِ الغُرْفَةَ"" : كُلُّ مَا يُسْتَضَاءُ بِهِ، سِرَاجٌ. ""مِصْبَاحٌ كَهْرَبَائِيٌّ"". 2.""مِصْبَاحُ السَّيَّارَةِ "": ضَوْؤُهَا الَّذِي يَشْتَعِلُ لَيْلاً، وَهُمَا مِصْبَاحَانِ أَمَامِيَّانِ وَمِصْبَاحَانِ خَلْفِيَّانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11227, 'مَصَابِيحُ', 'مصابيح', 'جامد', '', 'مصابيح', 'مصبح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11228, 'صَابُورَةٌ', 'صابورة', 'جامد', 'صبر', 'صابورة', 'صبرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"صَابُورَةٌ-صَابُورَةٌ [ص ب ر].: مَا يُوضَعُ فِي بَطْنِ السَّفِينَةِ مِنَ الثِّقْلِ لِئَلاَّ تَمِيلَ عَلَى أَحَدِ جَوَانِبِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11229, 'صَبَارَةٌ', 'صبارة', 'جامد', 'صبر', 'صبارة', 'صبرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"صَبَارَةٌ-صَبَارَةٌ [ص ب ر]. ""اِشْتَدَّتِ الصَّبَارَةُ"" : شِدَّةُ الْبَرْدِ. ""يَقْضِي النَّهَارَ وَاللَّيْلَ فِي صَبَارَةِ الشِّتَاءِ بِلِبَاسِ الصَّيْفِ"". (ع. م. العقاد)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11230, 'صِبَارَةٌ', 'صبارة', 'جامد', 'صبر', 'صبارة', 'صبرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"صِبَارَةٌ-صِبَارَةٌ [ص ب ر]. ""صِبَارَةُ القَارُورَةِ"" : سِدَادُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11231, 'صُبْرَةٌ', 'صبرة', 'جامد', 'صبر', 'صبرة', 'صبرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"صُبْرَةٌ-صُبْرَةٌ [ص ب ر]. 1.""كَوَّمَ صُبْرَةً مِنَ البُرِّ"" : كُومَةٌ. ""صُبْرَةٌ مِنَ الطَّعَامِ"". 2.""اِشْتَرَى الطَّعَامَ صُبْرَةً"" : جِزَافاً، أَيْ بِلاَ كَيْلٍ أَوْ وَزْنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11232, 'صَبِرٌ', 'صبر', 'جامد', 'صبر', 'صبر', 'صبر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"صُبُورٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". : عُصَارَةُ شَجَرٍ مُرٍّ تُسْتَعْمَلُ فِي الطِّبِّ."', '');
