INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11235, 'أُصْبُعٌ', 'أصبع', 'جامد', 'صبع', 'ءصبع', 'صبع', '', '', '', 'مفرد', 'DnN', '', '', '"إِصْبَعٌ:أَصابِعُ"', '', 'R', '', '', '', '', '', '', '". 1.""شَبَّكَتْ أَصابِعَ يَدَيْها وَاسْتَغْرَقَـتْ في التَّأَمُّـلِ"" : أَطْرافٌ مُسْتَطيلَةٌ بِكَفِّ اليَدِ. ""تَعَضُّ على أَصاب"', '');
