INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11272, 'صِحَافَةٌ', 'صحافة', 'جامد', 'صحف', 'صحافة', 'صحفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'Rp', '', '', '', '', '', '', '"صِحَافَةٌ-صِحَافَةٌ [ص ح ف]. 1.""اِخْتَارَ الصِّحَافَةَ مِهْنَةً"" : العَمَلُ فِي الْجَرَائِدِ وَالْمَجَلاَّتِ وَوَسَائِلِ الإِعْلاَمِ، أَيْ تَتَبُّعُ الأَخْبَارِ وَكِتَابَةُ التَّعَالِيقِ وَالتَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11273, 'صَحْفَةٌ', 'صحفة', 'جامد', 'صحف', 'صحفة', 'صحفة', '', '', '', 'مفرد', 'DnN', '', '', '"صِحَافٌ"', '', 'R', '', '', '', '', '', '', '".""صَحْفَةُ الطَّعامِ"": إِنْاءٌ مِنْ آنِيَةِ الطَّعَامِ، كَبِيرُ الْحَجْمِ يُطَافُ بِهِ عَلَى الآكِلِينَ. ""وَقَدْ دُعِيَ إِلَى وَلِيمَةٍ فَرَأَى الصِّحَافَ تُوضَعُ وَتُرْفَعُ"". (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11274, 'صِحَافٌ', 'صحاف', 'جامد', '', 'صحاف', 'صحف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11275, 'صَحِيفَةٌ', 'صحيفة', 'جامد', 'صحف', 'صحيفة', 'صحفة', '', '', '', 'مفرد', 'DnN', '', '', '"صَحَائِفُ:صُحُفٌ"', '', '', '', '', '', '', '', '', '". 1.: مَا يُكْتَبُ فِيهِ مِنْ وَرَقٍ ونَحْوِهِ، الوَرَقُ الْمَكْتُوبُ. 2.""صُحُفُ الأَوَّلِينَ"": كُتُبُهُمْ.الأعلى آية 19 إِنَّ هَذَا لَفِي الصُّحُفِ الأُولَى صُحُفِ إِبْرَاهِيمَ وَمُوسَى . (قرآن). 3.""صَحِيفَةُ الوَجْهِ"" : بَشَرَتُهُ. 4.""يَقْرَأُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11276, 'صَحَائِفُ', 'صحائف', 'جامد', '', 'صحاءف', 'صحف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11277, 'صُحُفٌ', 'صحف', 'جامد', '', 'صحف', 'صحف', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11278, 'مُصْحَفٌ', 'مصحف', 'جامد', 'صحف', 'مصحف', 'مصحف', '', '', '', 'مفرد', 'DnN', '', '', '"مَصَاحِفُ"', '', 'R', '', '', '', '', '', '', '". : القُرْآنُ الكَرِيمُ لِأَنَّهُ جُمِعَتْ فِيهِ الآيَاتُ كُلُّهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11279, 'مَصَاحِفُ', 'مصاحف', 'جامد', '', 'مصاحف', 'مصحف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11280, 'صَاخَّةٌ', 'صاخة', 'جامد', 'صخخ', 'صاخة', 'صخة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"صَاخَّةٌ-صَاخَّةٌ [ص خ خ]. 1. عبس آية 33 فَإِذَا جَاءتِ الصَّاخَّةُ يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ . (قرآن) : الصَّيْحَةُ الَّتِي تَكُونُ يَوْمَ القِيَامَةِ. 2.""أَحْدَثَ الانْفِجَارُ صَاخَّةً"" : صَيْحَةً عَظِيمَةً تُصِمُّ الأُذُنَ لِشِدَّتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11281, 'صَاخِرَةٌ', 'صاخرة', 'جامد', 'صخر', 'صاخرة', 'صخرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"صَاخِرَةٌ-صَاخِرَةٌ [ص خ ر]. ""يَشْرَبُ مِنَ الصَّاخِرَةِ"" : إِنَاءٌ مِنَ الْخَزَفِ لِلشُّرْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11282, 'صَخْرَةٌ', 'صخرة', 'جامد', 'صخر', 'صخرة', 'صخرة', '', '', '', 'مفرد', 'DnN', '', '', '"صُخُورٌ:صَخْرٌ"', '', 'R', '', '', '', '', '', '', '". 1.""مِنْطَقَةٌ لاَ يُوجَدُ بِهَا إِلاَّ الصَّخْرُ"" : الْحَجَرُ العَظِيمُ الصَّلْبُ. 2.""عِلْمُ الصَّخْرِ"" : عِلْمٌ مُخْتَصٌّ بِبَحْثِ حَالَةِ الصُّخُورِ مِنْ حَيْثُ أَصْلُهَا وَتَرْكِيبُهَا وَخَصَائِصُهَا وَتَصْنِيفُ أَنْوَاعِهَا وَأَحْوَالُ وُجُودِهَا. ""صُخُورُ الْجِبَالِ"". 3. أَنْوَاعُ الصُّخُورِ: أ. ""الصُّخُورُ النَّارِيَّةُ"": وَهِيَ الأَصْلِيَّةُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11283, 'صُخُورٌ', 'صخور', 'جامد', '', 'صخور', 'صخر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
