INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11285, 'صَخْرِيَّاتٌ', 'صخريات', 'جامد', 'صخر', 'صخريات', 'صخرت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"صَخْرِيَّاتٌ-صَخْرِيَّاتٌ [ص خ ر]. : فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ تَنْبُتُ بَيْنَ الصُّخُورِ وَالْمَنَاطِقِ القَاحِلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11286, 'صَخْرٌ', 'صخر', 'جامد', '', 'صخر', 'صخر', '', '', '', 'جمع تكسير', '', '', '', '"مفردصَخْرَة"', '', 'Rp', '', '', '', '', '', '', '"جمع صَخْرَة. ن. صَخْرَةٌ."', ':لا جذر:لا مفرد');
