INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11288, 'صَادِرَاتٌ', 'صادرات', 'جامد', 'صدر', 'صادرات', 'صدرت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"صَادِرَاتٌ-صَادِرَاتٌ [ص د ر]. ""بلَغَتْ صَادِرَاتُ البِلاَدِ مِنْ كَذَا كَمِّيَّةً كَبِيرَةً هَذِهِ السَّنَةَ"" : مَا تُصَدِّرُهُ، مَا تُرْسِلُهُ البِلاَدُ مِنَ الْمَنْتُوجَاتِ سَواءٌ أَكَانَتْ زِرَاعِيَّةً أَمْ كانَتْ صِنَاعِيَّةً إِلَى بُلْدَانٍ أَجْنَبِيَّةٍ لِبَيْعِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11289, 'صَدَارَةٌ', 'صدارة', 'جامد', 'صدر', 'صدارة', 'صدرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"صَدَارَةٌ-صَدَارَةٌ [ص د ر]. 1.""يَحْتَلُّ مَكَانَ الصَّدَارَةِ"" : مَكَاناً مُتَقَدِّماً، فِي الوَاجِهَةِ. ""لَهُ الصَّدَارَةُ بَيْنَ قَوْمِهِ"". 2.""الصَّدَارَةُ فِي اللُّغَةِ وَعِنْدَ النُّحَاةِ"" : اِخْتِصَاصُ الكَلِمَةِ بِأَنْ تَكُونَ فِي صَدْرِ الكَلاَمِ كَأَسْمَاءِ الاسْتِفْهَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11290, 'صِدَارٌ', 'صدار', 'جامد', 'صدر', 'صدار', 'صدر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صِدَارٌ-صِدَارٌ [ص د ر]. ""يَرْتَدِي صِدَاراً"" : ثَوْباً بِلاَ كُمَّيْنِ يُغَطَّى بِهِالصَّدْرُ وَهُوَ خَاصٌّ بِالرِّجَالِ يُلْبَسُ مَعَ البِذْلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11291, 'صُدْرَةٌ', 'صدرة', 'جامد', 'صدر', 'صدرة', 'صدرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". : لِبَاسٌ بِكُمَّيْنِ، يُشَدُّ بِأَزْرارٍ أَمَامِيَّةٍ يُغَطِّي الْجُزْءَ الأَعْلَى مِنَ الْجِسْمِ إِلَى الوَرِكَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11292, 'صُدْرِيَّةٌ', 'صدرية', 'جامد', 'صدر', 'صدرية', 'صدرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"صُدْرِيَّةٌ-صُدْرِيَّةٌ [ص د ر]. ""وَضَعَتْ صُدْرِيَّةً عَلَى صَدْرِ رَضِيعِهَا"" : قِطْعَةٌ مِنْ قُمَاشٍ، تُوضَعُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11293, 'صَدِيرَةٌ', 'صديرة', 'جامد', 'صدر', 'صديرة', 'صدرة', '', '', '', 'مفرد', 'DnN', '', '', '"صَدَائِرُ"', '', '', '', '', '', '', '', '', '". 1.: أَعْلَى الوَادِي وَصَدْرُهُ. 2.""صَدِيرَةُ النَّهْدَيْنِ"" : حِمَالَةُ النَّهْدَيْنِ... وَهُنَاكَ مَنْ يُطْلِقُ عَلَيْهَا حِمَالَةَ الصَّدْرِ، وَهُوَ مَا يُعْرَفُ بِالإِثَارِ قَديماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11294, 'صَدَائِرُ', 'صدائر', 'جامد', '', 'صداءر', 'صدر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11295, 'مَصْدَرٌ', 'مصدر', 'جامد', 'صدر', 'مصدر', 'مصدر', '', '', '', 'مفرد', 'DnN', '', '', '"مَصَادِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""تَأَكَّدَ مِنْ مَصْدَرِ الخَبَرِ "": أَيْ أَصْلُهُ، مَنْبَعُهُ، مَرْجِعُهُ، مَكَانُ صُدُورِهِ. ""جَاءَ الخَبَرُ مِنْ مَصْدَرِ ثِقَةٍ"". 2.""مَصْدَرٌ رَسْمِيٌّ"" : أَيِ الجِهَةُ أَوالشَّخْصُ الَّذِي لَهُ صِفَةٌ رَسْمِيَّةٌ وَيَصْدُرُ عَنْهُ مَاهُوَ رَسْمِيٌّ . 3.""أَثْبَتَ مَصَادِرَ بَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11296, 'مَصَادِرُ', 'مصادر', 'جامد', '', 'مصادر', 'مصدر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11297, 'صُدَاعٌ', 'صداع', 'جامد', 'صدع', 'صداع', 'صدع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صُدَاعٌ-صُدَاعٌ [ص د ع] (طب). ""يَشْتَكِي مِنْ صُدَاعٍ فِي رَ"', '');
