INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11300, 'صَدِيدٌ', 'صديد', 'جامد', 'صدد', 'صديد', 'صدد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَدِيدٌ-صَدِيدٌ [ص د د]. 1.""اِمْتَلأَ الْجُرْحُ بِالصَّدِيدِ"" : بِالقَيْحِ. 2.""صَدِيدُ الفِضَّةِ"" : ذَائِبُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11301, 'صَدَفِيَّاتٌ', 'صدفيات', 'جامد', 'صدف', 'صدفيات', 'صدفت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"صَدَفِيَّاتٌ-صَدَفِيَّاتٌ [ص د ف] (حو).: فَصِيلَةُ حَيَوَانَاتٍ رَخْوِيَّةٍ مِنْ ذَوَاتِ الصَّدَفَتَيْنِ وَف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11302, 'صَدَفٌ', 'صدف', 'جامد', '', 'صدف', 'صدف', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَدَفٌ - 1.: إِقْبَالُ إِحْدَى الرُّكْبَتَيْنِ عَلَى الأُخْرَى حِينَ الْمَشْيِ. ""صَدَفَا الْجَبَلِ"" : جَانِبَاهُ .الكهف آية 96 حَتَّى إِذَا سَاوَى بَيْنَ الصَّدَفَيْنِ قَالَ اُنْفُخُوا . (قرآن). 3.""الصَّدَفُ"" : غِشَاءُ الدُّرِّ. ن. صَدَفَةٌ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11303, 'صَدَفَةٌ', 'صدفة', 'جامد', '', 'صدفة', 'صدفة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"صَدَفٌ"', '', 'R', '', '', '', '', '', '', '"ج: صَدَفٌ. 1.""شَدَّ صَدَفَةَ قَمِيصِـهِ"" : دَائِـرَةٌ صَغِيرَةٌ (عُقْدَةٌ) مِنْ دُرٍّ مُصْطَنَعٍ أَوْ خَشَبٍ أَوْ مَا شَابَهَ ذَلِ"', ':لا جذر:لا مفرد');
