INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11305, 'صَدَاقَةٌ', 'صداقة', 'جامد', 'صدق', 'صداقة', 'صدقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""جَمَعَتْ بَيْنَهُمَا صَدَاقَةٌ قَدِيمَةٌ"" : مَوَدَّةٌ، مَحَبَّةٌ، عَلاَقَةُ الإِخْلاَصِ بَيْنَ الْمُتَقَارِبِينَ. 2.""جَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11306, 'صَدَاقٌ', 'صداق', 'جامد', 'صدق', 'صداق', 'صدق', '', '', '', 'مفرد', 'DnN', '', '', '"صُدُقٌ"', '', 'R', '', '', '', '', '', '', '". ""قَدَّمَ صَدَاقاً لِلْمَرْأَةِ"" : الصَّدُقَةُ، الْمَهْرُ الْمُقَدَّمُ لِلْمَرْأَةِ يُتَّفَقُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11307, 'صُدُقٌ', 'صدق', 'جامد', '', 'صدق', 'صدق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11308, 'صَدَقَةٌ', 'صدقة', 'جامد', 'صدق', 'صدقة', 'صدقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""دَقَّ بَابَهُ، لِيَطْلُبَ مِنْهُ صَدَقَةً لِوَجْهِ اللَّهِ"" : عَطَاءً، أَيْ مَا يُعْطَى لِلْفُقَرَاءِ تَقَرُّباً لِلَّهِ وَرَجَاءً لِثَوَابِهِ. 2.""أَخْرَجُوا الصَّدَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11309, 'صَدُقَةٌ', 'صدقة', 'جامد', 'صدق', 'صدقة', 'صدقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '".: الصَّداقُ، الْمَهْرُ الَّذِي يُقَدَّمُ لِلْمَرْأَةِ عِنْدَ طَلَبِ الزَّوَاجِ بِهَا. ""لاَ تُغَالُوا فِي الصَّدُقَاتِ"". (عمر بن الخطاب)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11310, 'صَرَّارٌ', 'صرار', 'جامد', 'صرر', 'صرار', 'صرر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"صَرَّارٌ-صَرَّارٌ [ص ر ر] (حش). : حَشَرَةٌ مِنْ فَصِيلَةِ الْجُدْجُدِيَّاتِ، مِنْ رُتْبَةِ مُسْتَقِيمَاتِ الأَجْنِحَةِ، تَمْتَازُ بِقَوَاسِمِهَا الطَّوِيلَةِ، وَالذَّكَرُ لَهُ قُدْرَةٌ عَلَى إِحْدَاثِ صَوْتٍ بِاحْتِكَاكِ أَجْنِحَتِهِ الأَمَامِيَّةِ، وَيُسَمَّى أَيْضاً الْجُدْجُدَ. ""صَرَّارُ اللَّيْلِ"" : وَهُوَ نَوْعَانِ: جُدْجُدٌ حَقْلِيٌّ وَجُدْجُدٌ مَنْزِلِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11311, 'صُدَامٌ', 'صدام', 'جامد', 'صدم', 'صدام', 'صدم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صُدَامٌ - [ص د م]. 1.(طب). : دَاءٌ فِي رُؤُوسِ الدَّوَابِّ.  2. : نَزْلَةٌ وَافِدَةٌ (الإِنْفُلُونْزَة)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11312, 'صَدْمَةٌ', 'صدمة', 'جامد', 'صدم', 'صدمة', 'صدمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"مثنىصَدْمَتَانِ-الصَّدْمَتَان', '', 'R', '', '', '', '', '', '', '"صَدْمَتَانِ-الصَّدْمَتَانِ [ص د م].: جَانِبَا الْجَبْهَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11313, 'صَدَى', 'صدى', 'جامد', 'صدي', 'صدى', 'صد', '', '', '', 'مفرد', 'Dy', '', '', '"أَصْدَاءُ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""يُرَدِّدُ الْجَبَلُ الصَّدَى"" : رَجْعُ الصَّوْتِ يَرُدُّهُ جِسْمٌ عَاكِسٌ كَالْجَبَلِ أَوِ الْمَغَارَةِ، أَوْ بَهْوِ قَصْرٍ وَاسِعِ الأَرْجَاءِ. ""وَقَفَ حَائِراً وَهُوَ يَسْمَعُ صَدَى صَوْتِهِ يَتَرَدَّدُ فِي الفَضَاءِ"" ""جَلَسْتُ أَسْمَعُ الصَّدَى، "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11314, 'أَصْدَاءُ', 'أصداء', 'جامد', '', 'ءصداء', 'صد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11315, 'صَرَّارَةٌ', 'صرارة', 'جامد', '', 'صرارة', 'صررة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"صَرَّارَةٌ-صَرَّارَةٌ (حو).: طَائِرٌ مِنَ الْجَوَارِحِ، مِنْ فَصِيلَةِ الصَّقْرِيَّاتِ وَهُوَ نَوْعٌ مِنَ العِقْبَانِ العَظِيمَةِ، يَأْكُلُ الأَفَاعِيَ، وَلاَ يَصِيدُ غَيْرَهَا، وَيُعْرَفُ فِي سُورِيَةَ وَلُبْنَانَ بِأَبِي صُوَيّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11316, 'صِرَاحٌ', 'صراح', 'جامد', 'صرح', 'صراح', 'صرح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صِرَاحٌ-صِرَاحٌ، صُرَاحٌ [ص ر ح]. 1.""نَسَبٌ صُرَاحٌ"" : خَالِصٌ لاَ تَشُوبُهُ شَائِبَةٌ. 2.""تَكَلَّمَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11317, 'صَرْحٌ', 'صرح', 'جامد', 'صرح', 'صرح', 'صرح', '', '', '', 'مفرد', 'DnN', '', '', '"صُرُوحٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَقَامَ صَرْحاً عَالِياً"" : بِنَاءً عَالِياً.غافر آية 36 يَا هَامَانُ ابْنِ لِي صَرْحاً لَعَلِّيَ أَبْلُغُ الأَسْبَابَ . (قرآن)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11318, 'صُرُوحٌ', 'صروح', 'جامد', '', 'صروح', 'صرح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11319, 'صَارُوخٌ', 'صاروخ', 'جامد', 'صرخ', 'صاروخ', 'صرخ', '', '', '', 'مفرد', 'DnN', '', '', '"صَوَارِيخُ"', '', 'R', '', '', '', '', '', '', '". 1.""أَصَابَ الصَّارُوخُ هَدَفَهُ"" :سَهْمٌ عَلَى شَكْلِ أُنْبُوبٍ، ضَخْمٌ يَحْمِلُ قُوَّةً نَارِيَّةً، مَحْشُوٌّ بِغَازَاتٍ، يُقْذَفُ إِلَى مَسَافَـاتٍ بَعِيـدَةٍ بِتَأْثِـيرِ انْفِجَارَاتِ الغَازَاتِ الَّتِي تَنْدَفِعُ مِنْ أَسْفَلِ الأُسْطُوَانَةِ. وَقَدْ تَحْمِلُ مَوَادَّ كِيمَاوِيَّةً أَوْ نَوَوِيَّةً. وَإِذَا مَا اشْتَعَلَ فَتِيلُهُ نَحْوَ هَدَفِهِ اِنْفَجَرَ مُحْدِثاً خَسَائِرَ فِي العَتَادِ وَالأَرْوَاحِ، سِلاَحٌ حَرْبِيٌّ. ""صَارُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11320, 'صَوَارِيخُ', 'صواريخ', 'جامد', '', 'صواريخ', 'صرخ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11321, 'صَرْخَةٌ', 'صرخة', 'جامد', 'صرخ', 'صرخة', 'صرخة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""سَمِعَ صَرْخَةً صَادِرَةً مِنْ وَرَاءِ النَّافِذَةِ"" : الصَّيْحَةُ الشَّدِيدَةُ عِنْدَ الفَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11322, 'صُرَّةٌ', 'صرة', 'جامد', 'صرر', 'صرة', 'صرة', '', '', '', 'مفرد', 'DnN', '', '', '"صُرَرٌ"', '', 'R', '', '', '', '', '', '', '". ""أَخْرَجَتْ نُقُوداً مِنْ صُرَّتِهَا"" : خِرْقَةٌ تُجْمَعُ فِيهَا النُّقُودُ وَغَيْرُهَا وَتُشَدُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11323, 'صُرَرٌ', 'صرر', 'جامد', '', 'صرر', 'صر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11324, 'صِرَّةٌ', 'صرة', 'جامد', 'صرر', 'صرة', 'صرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"صَرَّةٌ-صَرَّةٌ [ص ر ر]. 1.""صَرَّةُ صَوْتٍ"" : صَيْحَتُهُ، ضَجَّتُهُ.الذاريات آية 29 فَأَقْبَلَتِ امْرَأَتُهُ فِي صَرَّةٍ فَصَكَّتْ وَجْهَهَا . (قرآن). 2.""فِي صَرَّةٍ"" : فِي جَمَاعَةٍ. 3.""بِهِ صَرَّةٌ"" : شِدَّةُ الهَمِّ مِن بَرْدٍ أَوْ حَرٍّ أَو فَجيعَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11325, 'صَرَرٌ', 'صرر', 'جامد', 'صرر', 'صرر', 'صر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَرَرٌ-صَرَرٌ [ص ر ر].: سُنْبُلٌ لَمْ يَتَكَوَّنْ فِيهِ الْحَبُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11326, 'صَرْصَرٌ', 'صرصر', 'جامد', 'صرصر', 'صرصر', 'صرصر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَرْصَرٌ-صَرْصَرٌ [ص ر ص ر]. ""رِيحٌ صَرْصَرٌ"" : شَدِيدَةُ البَرْدِ. ""كَانَتِ الرِّيحُ صَرْصَراً وَقَدِ ازْدَادَتْ بُرُودَةُ الْهَوَاءِ وَرُطُوبَةُ الْجَوِّ"". (حنا مينا)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11327, 'صُرْصُورٌ', 'صرصور', 'جامد', '', 'صرصور', 'صرصر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"صَرَاصِيرُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: صَرَاصِيرُ. (حش).: حَشَرَةٌ مِنْ مُسْتَقِيمَاتِ الأَجْنِحَةِ، لَهَا لَوَامِسُ شَعْرِيَّةٌ، وَهِيَ سَوْدَاءُ ضَارَّةٌ، تُوجَدُ بِكَثْرَةٍ فِي الْمَجَارِي وَالْمَرَاحِيضِ وَالأَمَاكِنِ القَذِرَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11328, 'صَرَاصِيرُ', 'صراصير', 'جامد', '', 'صراصير', 'صرصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11329, 'صِرَاطٌ', 'صراط', 'جامد', 'صرط', 'صراط', 'صرط', '', '', '', 'مفرد', 'DnN', '', '', '"صُرُطٌ"', '', 'R', '', '', '', '', '', '', '". ""الصِّرَاطُ الْمُسْتَقِيمُ"" : الطَّرِيقُ القَوِيمُ. الفاتحة آية 7 اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ، صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ . (قرآن) : تُكْتَبُ بِالسِّينِ أَيْضاً. ن. سِرَاطٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11330, 'صُرُطٌ', 'صرط', 'جامد', '', 'صرط', 'صرط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11331, 'صَرْعٌ', 'صرع', 'جامد', 'صرع', 'صرع', 'صرع', '', '', '', 'مفرد', 'DnN', '', '', '"مثنىصرعان-الصرعان"', '', 'R', '', '', '', '', '', '', '"صَرْعَانِ-الصَّرْعَانِ [ص ر ع]. 1.""لِلأَمْرِ صَرْعَانِ"" : طَرَفَانِ. 2.""جِئْتُهُ صَرْعَيِ النَّهَارِ"" : أَيْ غُدْوَةً وَعَشِيَّةً. 3.""الصَّرْعَانِ"" : اللَّيْلُ وَالنَّهَارُ. 4.""هُوَ ذُو صَرْعَيْنِ"" : ذُو لَوْنَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11332, 'مِصْرَاعٌ', 'مصراع', 'جامد', 'صرع', 'مصراع', 'مصرع', '', '', '', 'مفرد', 'DnN', '', '', '"مَصَارِيعُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""مِصْرَاعُ البَابِ "": أَحَدُ جُزْءيْهِ. ""فَتَحَ البَابَ عَلَى مِصْرَاعَيْهِ"" ""مِصْرَاعُ النَّافِذَةِ"" ""لَطَمَتْ رِيَاحٌ بَارِدَةٌ مَصَارِيعَ النَّوَافِذِ الْمَفْتُوحَةِ، مُنْذِرَةٌ بِالْمَطَرِ القَرِيبِ"". 2.""مِصْرَاعُ البَيْتِ الشِّعْرِيِّ"" : أَحَدُ شَطْرَيْ بَيْتِ الشِّعْرِ، وَهُمَا مِصْرَاعَانِ : الصَّدْرُ وَالعَجُزُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11333, 'مَصَارِيعُ', 'مصاريع', 'جامد', '', 'مصاريع', 'مصرع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11334, 'تَصَارِيفُ', 'تصاريف', 'جامد', 'صرف', 'تصاريف', 'تصرف', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"تَصَارِيفُ-تَصَارِيفُ [ص ر ف]. ""تَصَارِيفُ الدَّهْرِ"" : نَوَائِبُهُ، مَصائِبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11335, 'صِرَافَةٌ', 'صرافة', 'جامد', 'صرف', 'صرافة', 'صرفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"صِرَافَةٌ-صِرَافَةٌ [ص ر ف]. ""يَتَعَاطَى الصِّرَافَةَ"" : حِرْفَةُ الصَّيْرَفِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11336, 'مُتَصَرِّفِيَّةٌ', 'متصرفية', 'جامد', 'صرف', 'متصرفية', 'متصرفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَصَرِّفِيَّةٌ-مُتَصَرِّفِيَّةٌ [ص ر ف].: تَقْسِيمٌ إِدَارِيٌّ فِي عَهْدِ الإِمْبِراطُورِيَّةِ العُثْمَانِيَّةِ يُقَابِلُ الإِقْلِيمَ أَوِ الْمِنْطَقَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11337, 'مَصَارِيفُ', 'مصاريف', 'جامد', 'صرف', 'مصاريف', 'مصرف', '', '', '', 'مفرد', '', '', '', '"مفردمَصْرُوف"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""كَثُرَتْ مَصَارِيفُهُ"" : نَفَقَاتُهُ. ن. مَصْرُوفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11338, 'مَصْرُوف', 'مصروف', 'جامد', '', 'مصروف', 'مصرف', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11339, 'مَصْرِفٌ', 'مصرف', 'جامد', 'صرف', 'مصرف', 'مصرف', '', '', '', 'مفرد', 'DnN', '', '', '"مَصَارِفُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""وَضَعَ أَمْوَالَهُ فِي الْمَصْرِفِ"" : مُؤَسَّسَةٌ مَالِيَّةٌ تُوضَعُ فِيهَا الأَمْوَالُ وَالوَدَائِعُ وَيُؤْتَمَنُ عَلَيْهَا، تُسْحَبُ عِنْدَ الْحَاجَةِ كَمَا تُقَدِّمُ قُرُوضاً، البَنْكُ. ""سَحَبَ قَدْرًا مِنَ الْمَالِ مِنَ الْمَصْرِفِ"". 2.""مَصْرِفُ الْمِيَاهِ"" : مَكَانُ جَرَيَانِهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11340, 'مَصَارِفُ', 'مصارف', 'جامد', '', 'مصارف', 'مصرف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11341, 'صَرِيمَةٌ', 'صريمة', 'جامد', 'صرم', 'صريمة', 'صرمة', '', '', '', 'مفرد', 'DnN', '', '', '"صَرَائِمُ"', '', '', '', '', '', '', '', '', '". 1.""لَهُ صَرِيمَةٌ قَوِيَّةٌ"" : عَزِيمَةٌ. 2.""صَرِيمَةٌ مِنَ اللَّيْلِ"" : قِطْعَةٌ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11342, 'صَرَائِمُ', 'صرائم', 'جامد', '', 'صراءم', 'صرم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11343, 'صُرُوفٌ', 'صروف', 'جامد', 'صرف', 'صروف', 'صرف', '', '', '', 'مفرد', '', '', '', '"مفردصَرْف"', '', '', '', 'N', 'O', 'O', 'O', '', '". ""صُرُوفُ الدَّهْرِ"" : نَوَائِبُهُ وَشَدَائِدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11344, 'صَرْف', 'صرف', 'جامد', '', 'صرف', 'صرف', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11345, 'مِصْطَبَةٌ', 'مصطبة', 'جامد', 'صطب', 'مصطبة', 'مصطبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مِصْطَبَةٌ-مِصْطَبَةٌ [ص ط ب]. 1.""عَلاَ الْمَصْطَبَةَ"" : سَطْحٌ مُرْتَفِعٌ قَلِيلاً يُجْلَسُ عَلَيْهِ لِرُؤْيَةِ الْمَشَاهِدِ مِنْ عَلُ. 2.""مَصْطَبَةُ الفَصْلِ"" : الْمَكَانُ الْمُرْتَفِعُ تَحْتَ السَّبُّورَةِ يَكُونُ مِنْ خَشَبٍ أَوْ بِنَاءٍ يُصْعَدُ عَلَيْهِ لِلتَّمَكُّنِ مِنَ الكِتَابَةِ عَلَى السَّبُّورَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11346, 'صَعَالِيكُ', 'صعاليك', 'جامد', '', 'صعاليك', 'صعلك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ن. صُعْلُوكٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11347, 'صُرَدٌ', 'صرد', 'جامد', '', 'صرد', 'صرد', '', '', '', 'جمع تكسير', 'DnN', '', '', '"صِرْدَانٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: صِرْدَانٌ. (حو).: طَائِرٌ أَكْبَرُ مِنَ العُصْفُورِ، مِنْ فَصِيلَةِ الصُّرْدِيَّاتِ، أَبْقَعُ أَبْيَضُ البَطْنِ، أَخْضَرُ الظَّهْرِ، ضَخْمُ الرَّأْسِ وَالْمِنْقَارِ يَصِيدُ صِغَارَ الْحَشَرَاتِ وَالعَصَافِيرِ، وَهُوَ شَرِسُ الطِّبَاعِ ذَنَبُهُ دَائِمُ الْحَرَكَةِ."', ':لا جذر:لا مفرد');
