INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11349, 'مَصَاعِبُ', 'مصاعب', 'جامد', 'صعب', 'مصاعب', 'مصعب', '', '', '', 'مفرد', '', '', '', '"مفردمَصْعَب"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""اِعْتَرَضَتْهُ مَصَاعِبُ وَعَرَاقِيلُ"" : الشَّدَائِدُ، الْمَشَقَّاتُ. "" مُوَاجَهَةُ الْحَقِيقَةِ مِنْ أَصْعَبِ الْمَصَاعِبِ فِي هَذِهِ الدُّنْيَا"". (ع. م. العقاد)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11350, 'مَصْعَب', 'مصعب', 'جامد', '', 'مصعب', 'مصعب', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11351, 'صَعْتَرٌ', 'صعتر', 'جامد', '', 'صعتر', 'صعتر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"صَعْتَرٌ-صَعْتَرٌ (نب).: نَبَاتٌ مِنْ فَصِيلَةِ الشَّفَوِيَّاتِ، عُشْبِيٌّ مُخْشَوْشَبٌ، حِرِّيفُ الطَّعْمِ، زَهْرُهُ أَبْيَضُ، بَعْضُهُ يُسْتَعْمَلُ فِي الطِّبِّ، وَبَعْضُهُ يُؤْكَلُ أَخْضَرَ مَعَ السُّمَّاقِ وَالسِّمْسِمِ وَالزَّيْتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11352, 'صُعَدَاءُ', 'صعداء', 'جامد', 'صعد', 'صعداء', 'صعد', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"صُعَدَاءُ-صُعَدَاءُ [ص ع د]. ""تَنَفَّسَ الصُّعَدَاءَ"" : اِنْفَرَجَ هَمُّهُ وَضَيْقُهُ، تَنَهَّدَ تَنَهُّداً مَمْدُوداً بِعُمْقٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11353, 'صَعِيدٌ', 'صعيد', 'جامد', 'صعد', 'صعيد', 'صعد', '', '', '', 'مفرد', 'DnN', '', '', '"صُعُدٌ:أَصْعِدَةٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""أَقَامُوا الْخِيَامَ عَلَى صَعِيدٍ مِنَ الأَرْضِ"" : مَا ارْتَفَعَ مِنْهَا وَاتَّسَعَ. 2.""تَرَاكَمَ الصَّعِيدُ"" : التُّرَابُ.النساء آية 43 فَتَيَمَّمُوا صَعِيداً طَيِّباً . (قرآن). 3"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11354, 'صُعُدٌ', 'صعد', 'جامد', '', 'صعد', 'صعد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
