INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11356, 'مِصْعَدٌ', 'مصعد', 'جامد', 'صعد', 'مصعد', 'مصعد', '', '', '', 'مفرد', 'DnN', '', '', '"مَصَاعِدُ"', '', 'R', '', '', '', '', '', '', '". ""يَنْتَظِرُ الْمِصْعَدَ فِي الطَّابَقِ التَّحْتِيِّ "": جِهَازٌ كَهْرَبَائِيٌّ عَمُودِيٌّ فِي قَلْبِ البِنَايَاتِ وَالعِمَارَاتِ الْحَدِيثَةِ يَصْعَدُ وَيَهْبِطُ بِالنَّاسِ مِنْ طَابَقٍ إِلَى آخَرَ."', '');
