INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11358, 'صُعْلُوكٌ', 'صعلوك', 'جامد', 'صعلك', 'صعلوك', 'صعلك', '', '', '', 'مفرد', 'DnN', '', '', '"صَعَالِيكُ"', '', 'R', '', '', '', '', '', '', '". 1.""عَرَفْتُهُ صُعْلُوكاً"" : رَذِيلاً، لِصّاً. 2.""صَعَالِيكُ الْعَرَبِ فِي الْجَاهِلِيَّةِ"" : لُصُوصُهُمْ، فُقَرَاؤُهُمْ. ""مِنَ الشُّعَرَاءِ الصَّعَالِيكِ"". 3.""اِحْتَشَدَ الصَّعَالِيكُ فِي السَّاحَةِ العُمُومِيَّةِ"" : رِجَالٌ مُهَمَّشُونَ فِي الْمُجْتَمَعِ لاَ شُغْلَ لَهُمْ، أَرَاذِلُهُمْ."', '');
