INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11361, 'صَغَائِرُ', 'صغائر', 'جامد', 'صغر', 'صغاءر', 'صغر', '', '', '', 'مفرد', '', '', '', '"مفردصَغِيرَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""يَهْتَمُّ بِصَغَائِرِ الأُمُورِ"" : بِتَوَافِهِهَا، بِمَا لَيْسَ لَهُ قِيمَةٌ. 2.""اِحْذَرِ الصَّغَائِرَ وَالكَبَائِرَ"" : الذُّنُوبَ البَسِيطَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11362, 'صُفَارِيَّةٌ', 'صفارية', 'جامد', '', 'صفارية', 'صفرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"صُفَارِيَّةٌ-صُفَارِيَّةٌ (حو).: طَائِرٌ لَهُ رِيش"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11363, 'صَفَائِحُ', 'صفائح', 'جامد', 'صفح', 'صفاءح', 'صفح', '', '', '', 'مفرد', '', '', '', '"مفردصَفِيحَة"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '". 1.""صَفَائِحُ البَابِ"": أَلْوَاحُهُ. 2.""اِخْتَارَ صَفَائِحَ جَمِيلَةً لِتَبْلِيطِ أَرْضِيَّةِ البَيْتِ"" : الزِّلِّيجُ، أَيْ رُقَاقٌ مِنْ رُخَامٍ أَوْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11364, 'صَفْحَةٌ', 'صفحة', 'جامد', 'صفح', 'صفحة', 'صفحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"مُثَنَّىصَفْحَتَانِ"', '', 'R', '', '', '', '', '', '', '". 1.""صَفْحَةُ الكِتَابِ"" : وَجْهُ الوَرَقَةِ. 2.""صَفْحَةُ الأَدِيمِ"" : وَجْهُ الأَرْضِ. 3.""أَبْدَى لَهُ صَفْحَتَهُ"" : كَاشَفَهُ وَبَاحَ بِأَسْرَارِهِ. 4.""صَفْحَتَا الوَجْهِ"" : خَدَّاهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11365, 'صُفْحٌ', 'صفح', 'جامد', 'صفح', 'صفح', 'صفح', '', '', '', 'مفرد', 'DnN', '', '', '"أَصْفَاحٌ"', '', 'R', '', '', '', '', '', '', '". 1.""صُفْحُ الكَفِّ"" : وَجْهُهُ. ""صُفْحَا الكَفَّيْنِ"" : وَجْهَاهُمَا. 2."""', '');
