INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11404, 'صَقْرِيَّاتٌ', 'صقريات', 'جامد', '', 'صقريات', 'صقرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ حَيَوَانِيَّةٌ مِنَ الصُّقُورِ، وَهِيَ مِنْ كَوَاسِرِ النَّهَارِ وَرُتْبَةِ الْجَوَارِحِ ذَاتِ الْمَنَاقِيرِ الْمُقَوَّسَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11405, 'صَقْعَةٌ', 'صقعة', 'جامد', 'صقع', 'صقعة', 'صقعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَقْعَةٌ-صَقْعَةٌ [ص ق ع]. ""سَادَتِ الصَّقْعَةُ فِي جَمِيعِ الأَصْقَاعِ"" : شِدَّةُ البَرْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11406, 'صُلْحٌ', 'صلح', 'جامد', 'صلح', 'صلح', 'صلح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صُلْحٌ-صُلْحٌ [ص ل ح]. 1.""عَقَدَ صُلْحاً بَيْنَهُمَا"" : وِفَاقاً بَعْدَ خِصَامٍ، إِنْهَاءُ حَالَةِ الْحَر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11407, 'مَصْلَحَةٌ', 'مصلحة', 'جامد', 'صلح', 'مصلحة', 'مصلحة', '', '', '', 'مفرد', 'DnN', '', '', '"مَصَالِحُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِنْ مَصْلَحَتِهِ الخَاصَّةِ أَنْ يَبْحَثَ عَنْ حَلٍّ"" : مِنْ نَفْعِهِ، أَي مَا يُمْكِنُ أَنْ يَعُودَ عَلَيْهِ بِالخَيْرِ. 2.""قَامَ بِذَلِكَ العَمَلِ لِمَصْلَحَةِ جَارِهِ"" : لِفَائِدَةِ...، لِصالِحٍ. 3.""يُضَحِّي بِكُلِّ شَيْءٍ لِأَجْلِ الْمَصْلَحَةِ الو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11408, 'مَصَالِحُ', 'مصالح', 'جامد', '', 'مصالح', 'مصلح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11409, 'صَلْصَةٌ', 'صلصة', 'جامد', '', 'صلصة', 'صلصة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '": مَادَّةٌ مُتَبَّلَةٌ ثَخِينَهٌ دُهْنِيَّةٌ تُتَّخَذُ تَابِلاً للِطَّعَامِ لإِعْطَائِهِ نَكْهَةً خَاصَّةً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11410, 'صَلْصَالٌ', 'صلصال', 'جامد', 'صلصل', 'صلصال', 'صلصل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَلْصَالٌ-صَلْصَالٌ [ص ل ص ل]. ""طَلَى اللَّوْحَ بِالصَّلْصَالِ"" : الطِّينُ الْحُرُّ الْيَابِسُ تُطْلَى بِهِ مَثَلاً أَلْوَاحُ الْمَسِّيدِ (الْكُتَّاب) وَهِيَ مُبَلَّلَةٌ فَيَتَحَوَّلُ لَوْنُهَا إِلَى أَبْيَضَ مَفْتُوحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11411, 'صَلَطَةٌ', 'صلطة', 'جامد', '', 'صلطة', 'صلطة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '": خُضَرٌ أَوْ خُسٌّ مُتَبَّلٌ بِالْخَلِّ أَوِ الْحَامِضِ وَالْخَرْدَلِ وَالثُّومِ، سَلاطَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11412, 'صَلْعَةٌ', 'صلعة', 'جامد', 'صلع', 'صلعة', 'صلعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"صَلْعَةٌ-صَلْعَةٌ، صُلْعَةٌ [ص ل ع]. ""بَرِيقٌ يَسْطَعُ مِنْ صَلْعَتِهِ"" : مَوْقِعُ انْحِسَارِ الشَّعْرِ عَنِ الرَّأْسِ، أَيْ مَوْضِعُ الصَّلَعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11413, 'صَلْفَاءُ', 'صلفاء', 'جامد', 'صلف', 'صلفاء', 'صلف', '', '', '', 'مفرد', '', '', '', '"صِلاَفٌ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". ""أَرْضٌ صَلْفَاءُ"" : أَرْضٌ شَدِيدَةٌ صَلْبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11414, 'صِلاَفٌ', 'صلاف', 'جامد', '', 'صلاف', 'صلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11415, 'صَلِيقَةٌ', 'صليقة', 'جامد', 'صلق', 'صليقة', 'صلقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '".: شَرِيحَةٌ مِنْ لَحْمِ الْبَقَرِ للِشَّيِّ أَوِ الْقَلْيِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11416, 'مُصَلَّى', 'مصلى', 'جامد', 'صلو', 'مصلى', 'مصل', '', '', '', 'مفرد', 'Dy', '', '', '"مُصلَّيَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""اِتَّجَهَ إِلَى الْمُصَلَّى"": مَكَانُ الصَّلاَةِ. البقرة آية 125 واتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلَّى (قرآن). 2.""اِجْتَمَعَ النَّاسُ فِي الْمُصَلَّى"" : سَاحَةٌ خَارِجَ الْمَدِينَةِ تُقَامُ بِهَا صلاةُ العيدَيْنِ، صَلاَةُ الاسْتِسْقَاءِ، مَكَانٌ في الْمَقْبَرَةِ تُقَامُ فِيهِ صَلاةُ الجَنازَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11417, 'مُصلَّيَاتٌ', 'مصليات', 'جامد', '', 'مصليات', 'مصلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11418, 'مِصْلاَةٌ', 'مصلاة', 'جامد', 'صلي', 'مصلاة', 'مصلة', '', '', '', 'مفرد', 'DnN', '', '', '"مَصَالٍ:الْمَصَالِي"', '', '', '', '', '', '', '', '', '". ""مِصْلاَةُ صَيْدِ الْحَيَوَانَاتِ"" : شَرَكٌ أَوْ فَخٌّ يُنْصَبُ لِلصَّيْدِ."', '');
