INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11420, 'صُلَّجَةٌ', 'صلجة', 'جامد', 'صلج', 'صلجة', 'صلجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"صُلَّجَةٌ-صُلَّجَةٌ [ص ل ج]. ""صُلَّجَةُ دُودَةِ القَزِّ"" : غِشَاءٌ حَرِيرِيٌّ تَنْسُجُهُ دُودَةُ القَزِّ وَهُوَ مَا يَتَحَوَّلُ إِلَى شَرْنَقَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11421, 'صِمَاغٌ', 'صماغ', 'جامد', '', 'صماغ', 'صمغ', '', '', '', 'جمع تكسير', 'DnN', '', '', '"مثنىصماغان-الصماغان"', '', 'R', '', '', '', '', '', '', '"ن. الصّامِغَانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11422, 'صُمْتَةٌ', 'صمتة', 'جامد', 'صمت', 'صمتة', 'صمتة', '', '', '', 'مفرد', 'DnN', '', '', '"صُمَتٌ"', '', 'R', '', '', '', '', '', '', '". ""وَضَعَتِ الصُّمْتَةَ فِي فَمِ رَضِيعِهَا"" : السَّكَّاتَةَ، أَيْ مَا يُلَهَّى بِهِ الرَّضِيعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11423, 'صُمَتٌ', 'صمت', 'جامد', '', 'صمت', 'صمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11424, 'صِمَاخٌ', 'صماخ', 'جامد', 'صمخ', 'صماخ', 'صمخ', '', '', '', 'مفرد', 'DnN', '', '', '"صُمُخٌ:أَصْمِخَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""صِمَاخُ الأُذُنِ"" : الْقَنَاةُ الَّتِي تُغَطِّي بَاطِنَهَا إِلَى طَبْلَتِهَا الْمُؤَدِّيَةِ إِلَى الرَّأْسِ. 2.""ضَرَبَ اللَّهُ عَلَى صِمَاخِهِ"" : أَنَامَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11425, 'صُمُخٌ', 'صمخ', 'جامد', '', 'صمخ', 'صمخ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
