INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11427, 'صِمَادٌ', 'صماد', 'جامد', 'صمد', 'صماد', 'صمد', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"صِمَادٌ-صِمَادٌ، ةٌ [ص م د]. 1.""لَفَّ صِمَاداً عَلَى رَأْسِهِ"" : خِرْقَةً، مِنْدِيلاً، أَيْ مَا يَلُفُّهُ الرَّجُلُ عَلَى رَأْسِهِ مِمَّا هُوَ دُونَ الْعِمَامَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11428, 'صَمَدٌ', 'صمد', 'جامد', 'صمد', 'صمد', 'صمد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'N', '', '"صَمَدٌ-صَمَدٌ [ص م د]. 1.""هُوَ اللَّهُ الصَّمَدُ"" : مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى، أَيْ عَظِيمُ الْجَلاَلَةِ، الدَّائِمُ الْخَالِدُ.الإخلاص 1،2 قُلْ هُوَ اللَّهُ أَحَدٌ اللَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11429, 'صَوْمَعَةٌ', 'صومعة', 'جامد', 'صمع', 'صومعة', 'صمعة', '', '', '', 'مفرد', 'DnN', '', '', '"صَوَامِعُ"', '', 'R', '', '', '', '', '', '', '". 1.""اِرْتَفَعَ صَوْتُ الْمُؤَذِّنِ مِنَ الصَّوْمَعَةِ"" : مِنَ الْمِئْذَنَةِ، الْمَنَارَةِ. 2.""اِنْعَزَلَ الْعَابِدُ فِي صَوْمَعَ"', '');
