INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11432, 'صَمْغٌ', 'صمغ', 'جامد', 'صمغ', 'صمغ', 'صمغ', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَمْغٌ-صَمْغٌ [ص م غ]. 1.""صَمْغُ الشَّجَرَةِ"" : مَا يَسِيلُ عَلَيْهَا مِنْ مَادَّةٍ لَزِجَةٍ وَتَتَجَمَّدُ عَلَيْهَا، تُسْتَعْمَلُ فِي إِلْصَاقِ الأَوْرَاقِ. 2.""يَكْتُبُونَ فِي الْكُتَّابِ بِالصَّمْغِ"" : مِدَادٌ أَسْوَدُ اللَّوْنِ يُكْتَبُ بِهِ عَلَى اللَّوْحِ، وَهُوَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11433, 'صِمَامَةٌ', 'صمامة', 'جامد', 'صمم', 'صمامة', 'صممة', '', '', '', 'مفرد', 'DnN', '', '', '"صَمَائِمُ"', '', 'R', '', '', '', '', '', '', '". ن. الصِّمَامُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11434, 'صَمَائِمُ', 'صمائم', 'جامد', '', 'صماءم', 'صمم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
