INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11437, 'صِمَّةٌ', 'صمة', 'جامد', 'صمم', 'صمة', 'صمة', '', '', '', 'مفرد', 'DnN', '', '', '"صِمَمٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَضَعَ صِمَّةً عَلَى الْقِنِّينَةِ"" : السِّدَادَةُ، الصِّمَامُ. 2.""رَجُلٌ صِمَّةٌ"" : شُجَاعٌ. 3.:أُنْثَى الْقَنَافِذِ."', '');
