INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11440, 'صَنَانِيرُ', 'صنانير', 'جامد', '', 'صنانير', 'صننر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11441, 'صُنْبُورٌ', 'صنبور', 'جامد', '', 'صنبور', 'صنبر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"صَنَابِيرُ"', '', 'R', '', '', '', '', '', '', '"ج: صَنَابِيرُ. 1.""ظَهَرَ صُنْبُورٌ"" : سَعَفَةٌ تَنْبُتُ فِي جِذْعِ النَّخْلَةِ لاَ فِي الأَرْضِ. 2.""صُنْبُورُ نَخْلَةٍ"" : نَخْلَةٌ تَخْرُجُ مِنْ أَصْلِ النَّخْلَةِ الأُخْرَى مِنْ غَيْرِ أَنْ تُغْرَسَ. 3.""صُنْبُورُ الإِدَاوَةِ"" : قَصَبَتُهَا الَّتِ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11442, 'صَنَابِيرُ', 'صنابير', 'جامد', '', 'صنابير', 'صنبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11443, 'صَنَّاجٌ', 'صناج', 'جامد', 'صنج', 'صناج', 'صنج', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"صَنَّاجٌ-صَنَّاجٌ، صَنَّاجَةٌ [ص ن ج].: صَاحِبُ الصَّنْجِ، أَوِ اللاَّعِبُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11444, 'صَنْجٌ', 'صنج', 'جامد', '', 'صنج', 'صنج', '', '', '', 'جمع تكسير', 'DnN', '', '', '"صُنُوجٌ"', '', 'R', '', '', '', '', '', '', '"ج: صُنُوجٌ. 1.: صَفِيحَةٌ نُحَاسِيَّةٌ مُدَوَّرَةٌ يُضْرَبُ بِهَا عَلَى أُخْرَى مِثْلِهَا لأَدَاءِ إِيقَاعٍ مُوسِيقِيٍّ يُحْدِثُ طَنِينـاً.2.""صُنُوجُ الدَّفِّ"" : أَقْرَاطٌ نُحَاسِيَّةٌ صَغِيرَةٌ مُسْتَدِيرَةٌ لَهَا فَتَحَاتٌ فِي وَسَطِهَا تُثْبَتُ فِـي إِطَـا"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11445, 'صُنُوجٌ', 'صنوج', 'جامد', '', 'صنوج', 'صنج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11446, 'صَنَادِيدُ', 'صناديد', 'جامد', 'صند', 'صناديد', 'صندد', '', '', '', 'مفرد', '', '', '', '"مفردصِنْدِيد"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ن. صِنْدِيدٌ."', '');
