INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11448, 'صُنْدُوقَةٌ', 'صندوقة', 'جامد', 'صندق', 'صندوقة', 'صندقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"صُنْدُوقَةٌ-صُنْدُوقَةٌ [ص ن د ق]. ""وَضَعَتِ الْحِلِيَّ فِي صُنْدُوقَةٍ"" : الصُّنْدُوقُ الصَّغِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11449, 'صُنْدُوقٌ', 'صندوق', 'جامد', 'صندق', 'صندوق', 'صندق', '', '', '', 'مفرد', 'DnN', '', '', '"صَنَادِيقُ"', '', 'R', '', '', '', '', '', '', '". 1.""وَضَعَتْ ثِيَابَهَا فِي صُنْدُوقٍ"" : وِعَاءٌ مِنْ خَشَبٍ أَوْ مَعْدِنٍ، أَوْ وَرَقٍ مُقَوّىً مِنْ مُخْتَلِفِ الأَحْجَامِ لِحِفْظِ الْمَلاَبِسِ وَمُخْتَلِفِ الأَدَوَاتِ... 2.""صُنْدُوقُ السَّيَّارَةِ"" : مَا يَكُونُ فِي مُؤَخَّرَةِ السَّيَّارَةِ أَوْ مُقَدِّمَتِها. 3.""صُـنْدُوقُ الْبَرِيدِ"" : عُلْبَةٌ مِنْ مَعْدِنٍ وَنَحْوِهِ تُلْقَى فِيهَا الرَّسَائِلُ لِيَتِمَّ حَمْلُهَا وَإِرْسَالُهَا إِلَى أَصْحَابِهَا بِوَاسِطَةِ مُوَظَّفِي الْبَريِدِ. 4.""أَمِينُ الصُّنْدُو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11450, 'صَنَادِيقُ', 'صناديق', 'جامد', '', 'صناديق', 'صندق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11451, 'صُنَادِلٌ', 'صنادل', 'جامد', 'صندل', 'صنادل', 'صندل', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"صُنَادِلٌ-صُنَادِلٌ [ص ن د ل]. ""حَيَوَانٌ صُنَادِلٌ"" : ضَخْمُ الرَّأْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11452, 'صَنْدَلٌ', 'صندل', 'جامد', '', 'صندل', 'صندل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَنْدَلٌ-صَنْدَلٌ (نب).: شَجَرٌ هِنْدِيٌّ، خَشَبُهُ مُخْتَلِفُ الأَلْوَانِ طَيِّبُ الرَّائِحَةِ، أَبْيَضُ الزَّهْرِ، يَفُوحُ طِيبُهُ بِالدَّلْكِ أَوْ بِالإِحْرَاقِ، يُنْتِجُ ثَمَراً فِي عَنَاقِيدَ، وَلَهُ حَبٌّ أَخْضَرُ. ""دَوَّخَتْهَا رَائِحَةُ الصَّنْدَلِ الْمَحْرُوقِ"". (الطيب صالح)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11453, 'صَنْدَلٌ', 'صندل', 'جامد', '', 'صندل', 'صندل', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"""صَنْدَلَةٌ صَيْفِيَّةٌ"" : خُفٌّ ذُو نَعْلٍ مَتِينٍ، لَهُ سُيُورٌ، خَفِيفٌ وَمَكْشُوفٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11454, 'صِلٌّ', 'صل', 'جامد', '', 'صل', 'صل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَصْلاَلٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: أَصْلاَلٌ. 1.(حو).: حَيَّةٌ خَبِيثَةٌ لَهَا عُنُقٌ يَنْتَفِخُ فِي حَالَةِ الْهَيَجَانِ وَالغَيْظِ. 2.""هُوَ صِلُّ أَصْلاَلٍ"" : دَاهِيَةٌ خَبِيثٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11455, 'أَصْلاَلٌ', 'أصلال', 'جامد', '', 'ءصلال', 'صلل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11456, 'صِنَاعَةٌ', 'صناعة', 'جامد', 'صنع', 'صناعة', 'صنعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":صَنَائِعُ"', '', 'R', '', '', '', '', '', '', '". 1.""صِنَاعَةُ الصَّانِعِ"" : حِرْفَةُ الصَّانِعِ. ""سَأَلَهُ الْقَاضِي عَنِ اسْمِهِ وَصِنَاعَتِهِ"". (توفيق الحكيم). 2.""الصِّنَاعَةُ التَّقْلِيدِيَّةُ"" : الأَعْمَالُ الْحِرَفِيَّةُ الْقَدِيمَةُ الَّتِي مَا زَالَتْ سَائِدَةً وَتَعْتَمِدُ عَلَى الْعَمَلِ الْيَدَوِيِّ. ""أَصْحَابُ الصَّنَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11457, 'صَنَائِعُ', 'صنائع', 'جامد', '', 'صناءع', 'صنع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11458, 'صَنِيعَةٌ', 'صنيعة', 'جامد', 'صنع', 'صنيعة', 'صنعة', '', '', '', 'مفرد', 'DnN', '', '', '"صَنَائِعُ"', '', '', '', '', '', '', '', '', '". 1.""قَدَّمَ لَهُ صَنِيعَةً لَنْ يَنْسَاهَا "" : إِحْسَاناً وَفَضْلاً وَمَعْرُوفاً. ""يَدٌ بَيْضَاءُ وَصَنِيعَةٌ غَرَّاءُ"". 2.""هُوَ صَنِيعَتِي"" : أَيْ أَنَا الَّذِي رَبَّيْتُهُ وَاصْطَنَعْتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11459, 'صَنَائِعُ', 'صنائع', 'جامد', '', 'صناءع', 'صنع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11460, 'مُصَانَعَةٌ', 'مصانعة', 'جامد', 'صنع', 'مصانعة', 'مصنعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مُصَانَعَةٌ-مُصَانَعَةٌ [ص ن ع]. 1. ""كَانَتْ مُصَانَعَتُهُ مُمَاثِلَةً "" : أَيْ أَنْ تَصْنَعَ لِغَيْرِكَ شَيْئاً لِيَصْنَعَ لَكَ شَيْئاً أخَرَ في مُقابِلِهِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11461, 'مَصَانِعُ', 'مصانع', 'جامد', 'صنع', 'مصانع', 'مصنع', '', '', '', 'مفرد', '', '', '', '"مفردمَصْنَع"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ن. مَصْنَعٌ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11462, 'مَصْنَعٌ', 'مصنع', 'جامد', 'صنع', 'مصنع', 'مصنع', '', '', '', 'مفرد', 'DnN', '', '', '"مَصَانِعُ"', '', 'R', '', '', '', '', '', '', '".: كُلُّ مَكَانٍ يُسْتَخْدَمُ لِصِنَاعَةِ مَادَّةٍ مِنَ الْمَوَادِّ، وَتُوجَدُ بِهِ آلاَتٌ وَأَدَوَاتٌ وَأَيْدٍ عَامِلَةٌ، ""مَصْنَعُ النَّسِيجِ"" ""مَصْنَعُ الْحَدِيدِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11463, 'مَصَانِعُ', 'مصانع', 'جامد', '', 'مصانع', 'مصنع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11464, 'تَصَانِيفُ', 'تصانيف', 'جامد', 'صنف', 'تصانيف', 'تصنف', '', '', '', 'مفرد', '', '', '', '"مفردتَصْنِيفٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""مُؤَلِّفٌ لَهُ تَصانِيفُ كَثِيرَةٌ"" : كُتُبٌ مُصَنَّفَةٌ، مَكْتُوبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11465, 'تَصْنِيفٌ', 'تصنيف', 'جامد', '', 'تصنيف', 'تصنف', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11466, 'صِنْفٌ', 'صنف', 'جامد', 'صنف', 'صنف', 'صنف', '', '', '', 'مفرد', 'DnN', '', '', '"أَصْنَافٌ:صُنُوفٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هَذا صِنْفٌ مُلائِمٌ"" : نَوْعٌ لَهُ صِفَاتٌ وَخَصَائِصُ مُشْتَرَكَةٌ. ""أَصْنَافُ الْفَوَاكِهِ"". 2.""هَذَا لَيْسَ مِنْ صِنْفِهِ"" : لَيْسَ مِنْ صِفَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11467, 'أَصْنَافٌ', 'أصناف', 'جامد', '', 'ءصناف', 'صنف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11468, 'صُنُوفٌ', 'صنوف', 'جامد', '', 'صنوف', 'صنف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11469, 'صُنَانٌ', 'صنان', 'جامد', 'صنن', 'صنان', 'صنن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صُنَانٌ-صُنَانٌ [ص ن ن]. 1.""يَفُوحُ مِنْهُ صُنَانٌ"" : رَائِحَةُ الإبْطِ الكَرِيهَةِ. 2.""صُنَانُ لَحْمٍ"" : نَتَنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11470, 'صِنَّةٌ', 'صنة', 'جامد', 'صنن', 'صنة', 'صنة', '', '', '', 'مفرد', 'DnN', '', '', '"أَصِنَّةٌ"', '', 'R', '', '', '', '', '', '', '". ن. صُنَانٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11471, 'أَصِنَّةٌ', 'أصنة', 'جامد', '', 'ءصنة', 'صنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11472, 'صِنْوٌ', 'صنو', 'جامد', 'صنو', 'صنو', 'صن', '', '', '', 'مفرد', 'DnN', '', '', '"صِنْوَانٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هُوَ صِنْوُهُ"" : شَقِيقُهُ، هُمَا صِنْوَانِ. 2.""لاَ صِنْوَ لَهُ"" : لاَ مَثِيلَ لَهُ، لاَ نِدَّ لَهُ، لاَ شَبِيهَ لَهُ. ""وَجَدَ صِنْوَهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11473, 'صِنْوَانٌ', 'صنوان', 'جامد', '', 'صنوان', 'صنن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11474, 'صَنَوْبَرٌ', 'صنوبر', 'جامد', '', 'صنوبر', 'صنبر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"صَنَوْبَرٌ-صَنَوْبَرٌ، ةٌ (نب).: جِنْسُ أَشْجَارٍ مِنْ فَصِيلَةِ الصَّنَوْبَرِيَّاتِ عَارِيَاتِالْبُذُورِ، دَائِمُ الْخُضْرَةِ، مِنْ أَنْو"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11475, 'صَنَوْبَرِيَّاتٌ', 'صنوبريات', 'جامد', '', 'صنوبريات', 'صنبرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِن الزَّهْرِيَّاتِ وَالْبُذُورِ الْعَارِيَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11476, 'صَيْهَبٌ', 'صيهب', 'جامد', 'صهب', 'صيهب', 'صهب', '', '', '', 'مفرد', 'DnN', '', '', '"صَيَاهِبُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"صَيْهَبٌ - ج: صَيَاهِبُ. [ص هـ  ب]. 1.""يَوْمٌ صَيْهَبٌ"": يَوْمٌ حَارٌّ. 2.""أَرْضٌ صَيْهَبٌ"" : مُسْتَوِيَةٌ. 3.""صَخْرَةٌ صَيْهَبٌ"" : صَلْبَةٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11477, 'صَيَاهِبُ', 'صياهب', 'جامد', '', 'صياهب', 'صهب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11478, 'صَيْهَدٌ', 'صيهد', 'جامد', 'صهد', 'صيهد', 'صهد', '', '', '', 'مفرد', 'DnN', '', '', '"صَيَاهِدُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""يَوْمٌ بِهِ صَيْهَدٌ"" : حَرٌّ شَدِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11479, 'صَيَاهِدُ', 'صياهد', 'جامد', '', 'صياهد', 'صهد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11480, 'صُهَارَةٌ', 'صهارة', 'جامد', 'صهر', 'صهارة', 'صهرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"صُهَارَةٌ - [ص هـ ر]. 1.: كُلُّ شَيْءٍ مُنْصَهِرٌ مُذَابٌ. 2.""عَزَلَ اللَّحْمَ عَنِ الصُّهَارَةِ"" : عَنِ الشَّحْمِ. 3.""صُهَارَةُ عَظْمٍ"": مُخُّهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11481, 'صَهْرٌ', 'صهر', 'جامد', 'صهر', 'صهر', 'صهر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"صَهْرٌ - [ص هـ ر]. 1.""صَهْرُ الْحَدِيدِ"" : إِذَابَتُهُ. 2.""الصَّهْرُ فِي الكِيمِيَاءِ"" : تَحْوِيلُ الْمَادَّةِ مِنَ الصَّلاَبَةِ إِلَى السُّيُولَةِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11482, 'صِهْرٌ', 'صهر', 'جامد', 'صهر', 'صهر', 'صهر', '', '', '', 'مفرد', 'DnN', '', '', '"أَصْهَارٌ"', '', 'R', '', '', '', '', '', '', '". ""صَارَ صِهْراً لَهُ"" : أيْ صَارَ زَوْجاً لاِبْنَتِهِ أَوْ زَوْجاً لِأُخْتِهِ، الْقَرَابَةُ بِالزَّ"', '');
