INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11493, 'مُصِيبَةٌ', 'مصيبة', 'جامد', 'صوب', 'مصيبة', 'مصبة', '', '', '', 'مفرد', 'DnN', '', '', '"مَصَائِبُ"', '', 'R', '', '', '', '', '', '', '". 1.""حَلَّتْ بِهِ الْمُصِيبَةُ"" : الفَجِيعَةُ. 2.""يَا لَلْمُصِيبَةِ !"" : صِيغَةٌ لِلتَّعَجُّبِ مِنْ فَجِيعَةِ الْمُصَابِ."', '');
