INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11514, 'مَصُوغٌ', 'مصوغ', 'جامد', 'صوغ', 'مصوغ', 'مصغ', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". "" مَصُوغَاتٌ ذَهَبِيَّةٌ وَفِضِّيَّةٌ"" : حُلِيٌّ صِيغَتْ مِنْ ذَهَبٍ أَوْ فِضَّةٍ أَوْ جَوَاهِرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11515, 'صُوفٌ', 'صوف', 'جامد', '', 'صوف', 'صف', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَصْوَافٌ"', '', 'Rp', '', '', '', '', '', '', '"ج: أَصْوَافٌ. ""صُوفُ الْغَنَمِ"" : شَعْرُهُ، أَيْ مَا يُغَطِّي جِلْدَهُ. ""يَلْبَسُ جِلْبَاباً مِنَ الصُّوفِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11516, 'أَصْوَافٌ', 'أصواف', 'جامد', '', 'ءصواف', 'صف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11517, 'صَوْلَجَانٌ', 'صولجان', 'جامد', '', 'صولجان', 'صلجن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""صَوْلَجَانُ الْمَلِكِ"" : عَصَا الْمَلِكِ. ""اِنْتَزَعَ مِنَ الدَّغَلِ عُوداً أَخْضَرَ حَمَلَهُ فِي يَدِهِ كَالصَّوْلَجَانِ"". (توفيق الحكيم)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11518, 'صُومَال', 'صومال', 'جامد', '', 'صومال', 'صمل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": بَلَدٌ إِسْلاَمِيٌّ (جُمْهُورِيَّةُ الصُّومَالِ الدِّيمُقْرَاطِيَّةُ) بِإِفْرِيقِيَا الشَّرْقِيَّةِ مُطِلٌّ عَلَى الْمُحِيطِ الْهِنْدِيِّ، عُضْوٌ بِجَامِعَةِ الدُّوَّلِ الْعَرَبِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11519, 'صِوَانَةٌ', 'صوانة', 'جامد', 'صون', 'صوانة', 'صنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '".: لُعْبَةٌ مُكَوَّنَةٌ مِنْ هَيْكَلٍ مُثَلَّثٍ أَوْشِبْهِ مُسْتَدِيرٍ خَفِيفٍ يُوضَعُ عَلَيْهِ وَرَقٌ مُقَوّىً أَوْ قِطْعَةٌ مِنْ قُمَـاشٍ، تُرْبَطُ بِخَيْطٍ طَوِيلٍ يُمْسَكُ بِهِ عِنْدَمَا تَطِيرُ فِي الْهَوَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11520, 'صُوَانٌ', 'صوان', 'جامد', 'صون', 'صوان', 'صن', '', '', '', 'مفرد', 'DnN', '', '', '"أَصْوِنَةٌ"', '', 'R', '', '', '', '', '', '', '". ""أَخْرَجَتْ فُسْتَانَهَا مِنَ الصُّوَانِ"" : جَانِبٌ فِي الْبَيْتِ دَاخِلِيٌّ، أَوْ خِزَانَةٌ لَهَا أَدْرَاجٌ مِنْ خَشَبٍ لِحِفْظِ الثِّيَابِ أَوِ الْكُتُبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11521, 'أَصْوِنَةٌ', 'أصونة', 'جامد', '', 'ءصونة', 'صنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
