INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11524, 'مُصَانٌ', 'مصان', 'جامد', 'صون', 'مصان', 'مصن', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""مَصَانُ الْمَلاَبِسِ "": مَكَانُ وَضْعِ الْمَعَاطِفِ أَوِ القُبَّعَاتِ أَوِ الْمَطَرِيَّاتِ وَمَا شَابَهَ ذَلِكَ فِي مُؤَسَّسَاتٍ عُمُومِيَّةٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11525, 'مِصْيَدَةٌ', 'مصيدة', 'جامد', 'صيد', 'مصيدة', 'مصدة', '', '', '', 'مفرد', 'DnN', '', '', '"مَصَائِدُ"', '', '', '', '', '', '', '', '', '". ""مِصْيَدَةُ الْجُرْذَانِ"" : أَداةٌ مُخْتَلِفَةُ الأشْكالِ يُصَادُ بِها. ""مِصْيَدَةُ الأَرَانِبِ""."', '');
