INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11530, 'صَيْحَةٌ', 'صيحة', 'جامد', 'صيح', 'صيحة', 'صحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""سَمِعَ صَيْحَةً مِنْ بَعِيدٍ"" : صُرَاخاً. ""صَيْحَةُ الطِّفْلِ"". 2.""هَلَكَتْهُ الصَّيْحَةُ"": الْعَذَابُ.هود آية 67 وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَة . (قرآن). 3.""يَوْمُ الصَّيْحَةِ"" : يَوْمُ النَّفْخِ في الصُّورِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11531, 'مَصَادٌ', 'مصاد', 'جامد', 'صيد', 'مصاد', 'مصد', '', '', '', 'مفرد', 'DnN', '', '', '"مَصَايِدُ"', '', 'R', '', '', '', '', '', '', '". ""خَرَجَ إِلَى الْمَصَادِ"" : مَكَانُ الصَّيْدِ."', '');
