INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11536, 'ضَوْضَاءُ', 'ضوضاء', 'جامد', 'ضأضأ', 'ضوضاء', 'ضض', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rz', '', '', '', '', '', '', '"ضَوْضَاءُ-ضَوْضَاءُ (مؤ) [ض أ ض أ]. ""أَحْدَثُوا ضَوْضَاءَ فِي أَرْجَاءِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11537, 'ضَأْنٌ', 'ضأن', 'جامد', 'ضأن', 'ضءن', 'ضن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَأْنٌ-ضَأْنٌ [ض أ ن] (حو). : حَيَوَانٌ مِنْ فَصِيلَةِ الغَنَمِيَّاتِ مُجْتَرٌّ، أَهْلِيٌّ، وَيُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11538, 'صِيصَةٌ', 'صيصة', 'جامد', 'صيص', 'صيصة', 'صصة', '', '', '', 'مفرد', 'DnN', '', '', '"صَيَاصٍ"', '', 'R', '', '', '', '', '', '', '"صِيصَةٌ - ج: صَيَاصٍ. [ص ي ص]. 1.""صِيصَةُ  الدِّيكِ"": الشَّوْكَةُ الَّتِي فِي مُؤَخَّرَةِ رِجْلِهِ. 2.""صِيصَةُ الظِّبَاءِ أَوِ الْبَقَرِ"" : قَرْنُهُ. 3.""صِيصَةُ الْحَائِكِ"" : الشَّوْكَةُ الَّتِي تُسَوَّى بِهَا السَّدَاةُ وَاللُّحْمَةُ. "', '');
