INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11540, 'ضَبٌّ', 'ضب', 'جامد', '', 'ضب', 'ضب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَضُبٌّ:ضُبَّانٌ:ضِبَـابٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: أَضُبٌّ، ضُبَّانٌ، ضِبَـابٌ. (حو). 1. : مِـنَالزَّحَّافَاتِ وَرُتْبَةِ العَظَائِيَّاتِ، يَتَمَيَّزُ بِذَنَبٍ عَرِيضٍ خَشِنٍ كَثِيرِ العُقَدِ، غَلِيظُ الجِسْمِ، و"', ':لا جذر:لا مفرد');
