INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11544, 'ضَبَابٌ', 'ضباب', 'جامد', 'ضبب', 'ضباب', 'ضبب', '', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', 'N', 'O', 'O', 'O', '', '"ضَبَابٌ-ضَبَابٌ [ض ب ب]. : القِطْعَةُ مِنْهُ ضَبَابَةٌ. ""غَشَّى الضَّبَابُ الْمُرْتَفَعَاتِ"" : سَحَابٌ خَفِيفٌ مُكَوَّنٌ مِنْ رَذَاذِ الْمَاءِ الْمُتَكَاثِفِ عَلَى الدُّخَانِ، يُغَشِّي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11545, 'ضَبَّةٌ', 'ضبة', 'جامد', 'ضبب', 'ضبة', 'ضبة', '', '', '', 'مفرد', 'DnN', '', '', '"ضِبَابٌ:ضُبَّانٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1. : أُنْثَى الضَّبِّ. 2. : حَدِيدَةٌ أَوْ صَحِيفَةٌ عَرِيضَةٌ يُغْلَقُ بِهَا البَابُ. 3.""اِمْرَأَةٌ خَبَّةٌ ضَبَّةٌ "" : مُرَاوِغَةٌ، خَدَّاعَةٌ."', '');
