INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11548, 'صَيِّفٌ', 'صيف', 'جامد', 'صيف', 'صيف', 'صف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَيِّفٌ-صَيِّفٌ [ص ي ف].: كُلُّ مَا يَجِيءُ فِي الصَّيْفِ: مَطَرٌ أَوْ عُشْبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11549, 'إِضبارَةٌ', 'إضبارة', 'جامد', 'ضبر', 'ءضبارة', 'إضبرة', '', '', '', 'مفرد', 'DnN', '', '', '"أَضابيرُ"', '', 'R', '', '', '', '', '', '', '". 1.""وَضَعَ على مَكْتَبِهِ إِضْبارَةً مِنَ الصُّحُفِ"" : حُزْمَةً، إِضْمامَةً. ""في مَكْتَبِ الْمُديرِ أَضَابيرُ ك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11550, 'أَضابيرُ', 'أضابير', 'جامد', '', 'ءضابير', 'ضبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11551, 'ضُبَارَةٌ', 'ضبارة', 'جامد', 'ضبر', 'ضبارة', 'ضبرة', '', '', '', 'مفرد', 'DnN', '', '', '"ضَبَائِرُ"', '', 'R', '', '', '', '', '', '', '". ""تَرَاكَمَتْ ضُبَارَةٌ مِنَ الصُّحُفِ"" : الْحُزْمَةُ مِنَ الصُّحُفِ. ""ضُبَارَةُ السِّهَامِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11552, 'ضَبَائِرُ', 'ضبائر', 'جامد', '', 'ضباءر', 'ضبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11553, 'ضَبْعٌ', 'ضبع', 'جامد', 'ضبع', 'ضبع', 'ضبع', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"ضِبَاعٌ"', '', 'R', '', '', '', '', '', '', '"(حو). : مِنْفَصِيلَةِ الضَّبْعِيَّاتِ، مِنْ رُتْبَةِ الضَّوَارِي، ضَخْمُ الرَّأْسِ، ثَخِينُ الشَّعْرِ، قَوِيُّ الفَكَّيْنِ، يَتَمَيَّزُ بِانْحِدَارِ جِسْمِهِ إِلَى الْمُؤَخِّرَةِ، وَهُوَ ثَلاَثَةُ أَنْوَاعٍ : الضَّبُعُ الغَثْرَاءُ، وَالضَّبُعُ الرَّقْطَاءُ (الضَّاحِكَةُ)، وَالضَّبُعُ الْمُخَطَّطَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11554, 'ضِبَاعٌ', 'ضباع', 'جامد', '', 'ضباع', 'ضبع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11555, 'ضَبْعِيَّاتٌ', 'ضبعيات', 'جامد', '', 'ضبعيات', 'ضبعت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةُ الضِّبَاعِ، مِنْ رُتْبَةِ الضَّوَارِي، مِنْ أَهَمِّ أَنْوَاعِهَا الضَّبُعُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11556, 'ضِبْنٌ', 'ضبن', 'جامد', '', 'ضبن', 'ضبن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَضْبَانٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَضْبَانٌ. : مَا بَيْنَ الإِبْطِ وَالخَاصِرَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11557, 'أَضْبَانٌ', 'أضبان', 'جامد', '', 'ءضبان', 'ضبن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11558, 'ضَجَّةٌ', 'ضجة', 'جامد', 'ضجج', 'ضجة', 'ضجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""أَحْدَثَ الجُمْهُورُ ضَجَّةً فِي الْمَلْعَبِ"" : الصُّيَاحُ، الْجَلَبَةُ، الضَّوْضَاءُ. 2.""أَحْدَثَ خِطَابُهُ ضَجَّةً فِي الأَوْسَاطِ السِّيَاسِيَّةِ"" : أَحْدَثَ رُدُودَ فِعْلٍ قَوِيَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11559, 'مَضْجَعٌ', 'مضجع', 'جامد', 'ضجع', 'مضجع', 'مضجع', '', '', '', 'مفرد', 'DnN', '', '', '"مَضَاجِعُ"', '', 'R', '', '', '', '', '', '', '". 1.""بَعْدَ انْتِهَاءِ السَّهْرَةِ أَوَى كُلٌّ إِلَى مَضْجَعِهِ"" : الْمَخْدَعُ، مَكَانُ الضُّجُوعِ وَالنَّوْمِ. ""أَقَضَّ مَضْجَعَهُ"" : أَقْلَقَ رَاحَتَهُ وَحَرَمَهُ النَّوْمَ، ""أَقَضَّ عَلَيْهِ الْمَضْجَعَ"" ""تَقُضُّ الهُمُومُ وَالأَحْزَانُ مَضْجَعَهُ"". 2.""مَضَاجِعُ الغَيْثِ"" : مَسَاقِطُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11560, 'مَضَاجِعُ', 'مضاجع', 'جامد', '', 'مضاجع', 'مضجع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11561, 'أُضْحُوكَةٌ', 'أضحوكة', 'جامد', 'ضحك', 'ءضحوكة', 'ضحكة', '', '', '', 'مفرد', 'DnN', '', '', '"أَضاحِيكُ"', '', 'R', '', '', '', '', '', '', '". 1.""إِنَّهُ مُمَثِّلٌ هَزْلِيٌّ رَائِعٌ، يُقَدِّمُ أَضاحِيكَ مُمْتِعَةً"" : حِكَايَاتٍ هَزْلِيَّةً، فُكاهاتٍ. 2.""جَعَلَهُ أُضْحوكَةً أَمامَ النَّاسِ"" : مَحَلَّ سُخْرِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11562, 'أَضاحِيكُ', 'أضاحيك', 'جامد', '', 'ءضاحيك', 'ضحك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11563, 'ضَاحِكَةٌ', 'ضاحكة', 'جامد', 'ضحك', 'ضاحكة', 'ضحكة', '', '', '', 'مفرد', 'DnN', '', '', '"ضَوَاحِكُ(تش)"', '', '', '', '', '', '', '', '', '". ""ظَهَرَتْ ضَاحِكَتُهُ"" : كُلُّ سِنٍّ تَبْدُو عِنْدَ الضَّحِكِ. ""اِفْتَرَّ عَنْ ضَوَاحِكِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11564, 'ضَوَاحِكُ', 'ضواحك', 'جامد', '', 'ضواحك', 'ضحك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11565, 'ضَحْكَةٌ', 'ضحكة', 'جامد', 'ضحك', 'ضحكة', 'ضحكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""عَبَّرَ بِضَحْكَتِهِ عَمَّا لاَ يُرِيدُ قَوْلَهُ"" : هَيْئَةُ الضَّحِكِ. 2.""ضَحِكَ ضَحْكَةً صَفْرَاءَ"" : اِبْتِسَامَةٍ صَفْرَاءَ مُصْطَنَعَةٍ لاَ تُعَبِّرُ عَنِ الوُدِّ وَالسُّرُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11566, 'أَضْحى', 'أضحى', 'جامد', 'ضحو', 'ءضحى', 'ضح', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '"أَضْحى-أَضْحى [ض ح و]. ""عِيدُ الأَضْحَى"" : عيدٌ زَمانُهُ وَقْتَ أَداءِ مَناسِكِ الحَجِّ في اليَوْمِ الْعَاشِرِ مِنْ شَهْرِ ذي الحِجَّةِ بَيْنَ ذِي القِعْدَةِ وَمُحَرَّم وَفيهِ يَنْحَرُ الْمُسلِمونَ الأَضاحِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11567, 'ضَحِيَّةٌ', 'ضحية', 'جامد', 'ضحو', 'ضحية', 'ضحة', '', '', '', 'مفرد', 'DnN', '', '', '"ضَحَايَا"', '', '', '', '', '', '', '', '', '". 1.""ضَحِيَّةُ العِيدِ"" : الشَّاةُ يُضَحَّى بِهَا. 2.""ذَهَبَ ضَحِيَّةَ أَهْوَائِهِ وَنَزَوَاتِهِ"" : تَعَرَّضَ لِلأَذَى وَالْمَصَائِبِ نَتِيجَةَ أَهْوَائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11568, 'ضَحَايَا', 'ضحايا', 'جامد', '', 'ضحايا', 'ضح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11569, 'ضُحًى', 'ضحى', 'جامد', 'ضحو', 'ضحى', 'ضح', '', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"ضُحىً-ضُحىً [ض ح و]. 1.""زَارَهُ وَقْتَ الضُّحَى"" : وَقْتَ ارْتِفَاعِ النَّهَارِ وَانْتِصاَفِهِ. 2.الشمس آية 1 وَالشَّمْسِ وَضُحَاهَا . (قرآن) : ضَوْءُ الشَّمْسِ. 3.""اِنْتَهَى صِيتُهُ بَيْنَ لَيْلَةٍ وَضُحَاهَا"" : فَجْأَةً، فِي بُرْهَةٍ مِنَ الزَّمَنِ كَأَنَّهُ لَمْ يَكُنْ. ""صَارَ حَاكِماً بَيْنَ لَيْلَةٍ وَضُحَاهَا"" ""بَيْنَ عَشِيَّةٍ وَضُحَاهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11570, 'مِضَخَّةٌ', 'مضخة', 'جامد', 'ضخخ', 'مضخة', 'مضخة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""مِضَخَّةُ الْمَاءِ"" : آلَةٌ يُسْتَخْرَجُ بِهَا الْمَاءُ مِنْ بَاطِنِ الأَرْضِ. ""مِضَخَّةُ البِنْزِينِ"". 2.""مِضَخَّةُ الْحَرَائِقِ"" : الأُنْبُوبُ الضَّخْمُ الَّذِي يَسْتَعْمِلُهُ رِجَالُ الْمَطَافِئِ لإِطْفَاءِ الْحَرَائِقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11571, 'أَضْدادٌ', 'أضداد', 'جامد', 'ضدد', 'ءضداد', 'ضدد', '', '', '', 'مفرد', '', '', '', '"مفردالضِّدُّ"', '', '', '', 'N', 'O', 'O', 'O', '', '". ""أَضْدادُ الكَلِماتِ"" : مُفْرَداتٌ دالَّةٌ على مَعْنَيَيْنِ مُتَبَايِنَيْنِ، مُتَضادَّيْنِ. الأبْيَضُ ضِدُّهُ الأسْوَدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11572, 'ضِدٌّ', 'ضد', 'جامد', 'ضدد', 'ضد', 'ضد', '', '', '', 'مفرد', 'DnN', '', '', '"أَضْدَادٌ:ضِدٌّ"', '', 'R', '', '', '', '', '', '', '". 1.""الْخَيْرُ ضِدُّ الشَّـرِّ"" : مُنَاقِضٌ لَهُ. 2.""لَسْتُ ضِدَّ أَحَدٍ"" : لَسْتُ مُعَاكِساً، مُعَارِضاً، مُخَالِفاً لأَحَدٍ. 3.""كَانَ عَلَى الضِّدِّ مِنْ ذَلِكَ"" : أَيْ عَلَى النَّقِيضِ. ""كُلُّ مَا زَادَ عَنْ حَدِّهِ يَنْقَلِبُ إِلَى ضِدِّهِ"". 4.""رَفَعَ دَعْوَةً ضِدَّهُ"" : رَفَعَ دَعْوَةً لِمُوَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11573, 'أَضْدَادٌ', 'أضداد', 'جامد', '', 'ءضداد', 'ضدد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11574, 'ضِدٌّ', 'ضد', 'جامد', '', 'ضد', 'ضد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11575, 'ضَدِيدٌ', 'ضديد', 'جامد', 'ضدد', 'ضديد', 'ضدد', '', '', '', 'مفرد', 'DnN', '', '', '"أَضْدَادٌ"', '', 'R', '', '', '', '', '', '', '". ""هُوَ ضَدِيدُهُ"" : شَبِيهُهُ، مِثْلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11576, 'أَضْدَادٌ', 'أضداد', 'جامد', '', 'ءضداد', 'ضدد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11577, 'ضَوَّايَةٌ', 'ضواية', 'جامد', 'ضوي', 'ضواية', 'ضة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""شَعَّ ضَوْءُ الضَّوَّايَةِ فِي كُلِّ الأَرْجَاءِ"" : آلَةٌ لَهَا طَاقَةٌ ضَـوْئِيَّةٌ كَبِـيرَةٌ يَنْتَشِرُ ضَوْؤُهَا فِي أَرْجَاءِ الْمَكَانِ كَمَا تُرْسِلُهُ بَعِيداً. ""ضَوَّايَةُ الْمَلْعَبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11578, 'ضَرَّابَةٌ', 'ضرابة', 'جامد', 'ضرب', 'ضرابة', 'ضربة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"ضَرَّابَةٌ-ضَرَّابَةٌ [ض ر ب]. ""ضَرَّابَةُ جَرَسٍ أَوْ نَاقُوسٍ"" : حَدِيدَةٌ فِي وَسَطِ الجَرَسِ تُحْدِثُ رَنَّةَ الْجَرَسِ عِنْدَمَا يَتِمُّ تَحْرِيكُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11579, 'ضَرَبَانٌ', 'ضربان', 'جامد', 'ضرب', 'ضربان', 'ضربن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَرَبَانٌ-ضَرَبَانٌ [ض ر ب]. ""ضَرَبَانُ الدَّهْرِ"" : مَصَائِبُهُ، نَوَائِبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11580, 'ضَرِيبَةٌ', 'ضريبة', 'جامد', 'ضرب', 'ضريبة', 'ضربة', '', '', '', 'مفرد', 'DnN', '', '', '"ضَرَائِبُ"', '', 'R', '', '', '', '', '', '', '". 1.""تَرَكَ ضَرِيبَةً عَلَى جِسْمِهِ"" : أَثَر الضَّرْبِ. 2.""هَذِهِ ضَرِيبَتُهُ الَّتِي ضُرِبَ عَلَيْهَا"" : طَبْعُهُ الَّذِي طُبِعَ عَلَيْهِ. 3.""ضَرِيبَةُ السَّيْفِ"" : حَدُّهُ. 4.""أَدَّى مَا عَلَيْهِ مِنَ الضَّرَائِبِ"" : أَيْ مَا يُفْرَضُ عَلَى الْمِلْكِ وَالإِنْتَاجِ وَالصِّنَاعَةِ وَالدَّخْلِ لِلدَّوْلَةِ بِنِسَبٍ مَعْلُومَةٍ. ""ضَرِيبَةُ الأَمْلاَكِ"" ""ضَرِيبَةُ الْمَبَانِي"" ""ضَرِيبَةُ الدَّخْلِ"" ""الضَّرِيبَةُ الْمُضَافَةُ عَلَى القِيمَةِ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11581, 'ضَرَائِبُ', 'ضرائب', 'جامد', '', 'ضراءب', 'ضرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11582, 'ضَرِيبٌ', 'ضريب', 'جامد', 'ضرب', 'ضريب', 'ضرب', '', '', '', 'مفرد', 'DnN', '', '', '"أَضْرَابٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هُوَ ضَرِيبُهُ"" : شَبِيهُهُ، نَظِيرُهُ. 2.""ضَرِيبُ الثَّوْبِ"" : مِثْلُهُ وَشَكْلُهُ. 3.""يُفَضِّلُ شُرْبَ الضَّرِيبِ"" : اللَّبَنُ الَّذِي يُحْلَبُ مِنْ عِدَّةِ نُوقٍ وَنَحْوِهَا فِي إِنَاءٍ وَاحِدٍ. 4.""تَعَرَّضَ لِلضَّرِيبِ "" : لِلصَّقِيعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11583, 'أَضْرَابٌ', 'أضراب', 'جامد', '', 'ءضراب', 'ضرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11584, 'مِضْرَابٌ', 'مضراب', 'جامد', 'ضرب', 'مضراب', 'مضرب', '', '', '', 'مفرد', 'DnN', '', '', '"مَضَارِيبُ"', '', 'R', '', '', '', '', '', '', '". 1.""رَجُلٌ مِضْرَابٌ"" : شَدِيدُ الضَّرْبِ. 2.""مِضْرَابُ كُرَةِ الْمَضْرِبِ"" : الأَدَاةُ الَّتِي يُضْرَبُ بِهَا الكُرَةُ، وَمَا يُضْرَبُ بِهِ عَلَى الإِطْلاَقِ. 3.""مِضْرَابُ العُودِ"" : رِيشَةُ العَازِفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11585, 'مَضَارِيبُ', 'مضاريب', 'جامد', '', 'مضاريب', 'مضرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11586, 'مَضْرَبَةٌ', 'مضربة', 'جامد', 'ضرب', 'مضربة', 'مضربة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مُضَرَّبَةٌ-مُضَرَّبَةٌ [ض ر ب]. : فِرَاشٌ ذُو طَاقَيْنِ مَخِيطَيْنِ بيْنهمَا قُطْنٌ أَوْ صُوفٌ يُنَامُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11587, 'مُضَرَّبَةٌ', 'مضربة', 'جامد', 'ضرب', 'مضربة', 'مضربة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مِضْرَبَةٌ-مِضْرَبَةٌ [ض ر ب]. 1.: آلَةُ الضَّرْبِ. 2. : مِضْرَبَةُ الْجَرَسِ"" : مِقْرَعَتُهُ، مِدَقَّتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11588, 'مِضْرَبَةٌ', 'مضربة', 'جامد', 'ضرب', 'مضربة', 'مضربة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَضْرَبَةٌ-مَضْرَبَةٌ [ض ر ب]. ""مَضْرَبَةُ السَّيْفِ"" : حَدُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11589, 'مَضْرَبٌ', 'مضرب', 'جامد', 'ضرب', 'مضرب', 'مضرب', '', '', '', 'مفرد', 'DnN', '', '', '"مَضَارِبُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَضْرَبُ السَّيْفِ"" : حَدُّهُ. 2.""مَضْرَبُ الْمُخِّ"" : العَظْمُ الَّذِي يَحْتَوِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11590, 'مَضَارِبُ', 'مضارب', 'جامد', '', 'مضارب', 'مضرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11591, 'مَضْرِبٌ', 'مضرب', 'جامد', 'ضرب', 'مضرب', 'مضرب', '', '', '', 'مفرد', 'DnN', '', '', '"مَضَارِبُ"', '', 'R', '', '', '', '', '', '', '".: مَكَانُ الضَّرْبِ أَوْ زِمَامُهُ. 1.""مَضْرِ بُ السَّيْفِ"" : حَدُّهُ. 2.""مَضْرِبُ الأَرُزِّ"" : مَكَانُ قَشْرِهِ. 3.""مَضْرِبُ الج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11592, 'مَضَارِبُ', 'مضارب', 'جامد', '', 'مضارب', 'مضرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11593, 'مِضْرَبٌ', 'مضرب', 'جامد', 'ضرب', 'مضرب', 'مضرب', '', '', '', 'مفرد', 'DnN', '', '', '"مَضَارِبُ"', '', 'R', '', '', '', '', '', '', '".: كُلُّ أَدَاةٍ يُضْرَبُ بِهَا. 1.""مِضْرَبُ الكُرَةِ"" : الأَدَاةُ الَّتِي يُلْعَبُ بِهَا فِي كُرَةِ الْمَضْرِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11594, 'مَضَارِبُ', 'مضارب', 'جامد', '', 'مضارب', 'مضرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11595, 'ضَرِيحٌ', 'ضريح', 'جامد', 'ضرح', 'ضريح', 'ضرح', '', '', '', 'مفرد', 'DnN', '', '', '"ضَرَائِحُ:أَضْرِحَةٌ"', '', 'R', '', '', '', '', '', '', '". ""زَارَ ضَرِيحَ الوَلِيِّ الصَّالِحِ"" : القَبْرُ الْمَوْجُودُ فِي مَكَانٍ مُسَيَّجٍ أَوْ بِنَاءٍ يُبْنَى خِصِّيصاً لَهُ. ""اِتَّجَها مَعاً إِلى قَلْبِ الضَّريحِ، وَبَعْد لَمْسِ الغِطاءِ الأَخْضَرِ وَتَقْبيلِ الجَوانِبِ الأرْبَعَةِ جَلَسا يَنْظُرانِ وَيَتَأَمَّلانِ المُقْرِئِينَ وَهُمْ يُرَدِّدونَ آياتِ القُرْآنِ الكَريمِ"". (أ. عبد الغني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11596, 'ضَرَائِحُ', 'ضرائح', 'جامد', '', 'ضراءح', 'ضرح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11597, 'أَضْرِحَةٌ', 'أضرحة', 'جامد', '', 'ءضرحة', 'ضرحة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11598, 'ضَرَّاءُ', 'ضراء', 'جامد', 'ضرر', 'ضراء', 'ضر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ضَرَّاءُ-ضَرَّاءُ [ض ر ر]. 1.""مَعَهُ فِي السَّرَّاءِ وَالضَّرَّاءِ"" : فِي حَالَةِ الانْفِرَاجِ وَالشِّدَّةِ، فِي اليُسْرِ وَالعُسْرِ. ""شَارَكَ أَصْدِقَاءهُ فِي بُؤْسِهِمْ وَنَعِيمِهِمْ وَضَرَّائِهِمْ وَسَرَّائِهِمْ عَلَى السَّوَاءِ"". (إسحق الحسيني). 2.""يَعِيشُ فِي الضَّرَّاءِ"" : فِي الفَقْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11599, 'ضَرَّةٌ', 'ضرة', 'جامد', 'ضرر', 'ضرة', 'ضرة', '', '', '', 'مفرد', 'DnN', '', '', '"ضَرَائِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""رَفَضَتْ أَنْ تَكُونَ ضَرَّةً"" : إِحْدَى زَوْجَتَيِ الرَّجُلِ، أَوْ إِحْدَى زَوْجَاتِهِ. ""الدُّنْيَا وَالآخِرَةُ ضَرَّتَانِ مَتَى أَرْضَيْتَ إِحْدَاهُمَا أَسْخَطْتَ الأُخْرَى"". (التوحيدي). 2.""بَيْنَهُمْ دَاءُ الضَّرَائِرِ"" : الْحَسَدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11600, 'ضَرَائِرُ', 'ضرائر', 'جامد', '', 'ضراءر', 'ضرر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11601, 'ضَرُورَةٌ', 'ضرورة', 'جامد', 'ضرر', 'ضرورة', 'ضررة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات:ضَرَائِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""لاَ ضَرُورَةَ لِذَلِكَ"" : لاَ حَاجَةَ. ""عِنْدَ الضَّرُورَةِ"". 2.""بِالضَّرُورَةِ"" : وُجُوباً. 3.""لِلضَّرُورَةِ أَحْكَامٌ"" : مَا يَكُونُ مُلِحّاً لِلإِنْسَانِ وَبِهِ حَاجَةٌ يَجْعَلُ لَهُ حُكْماً مُنَاسِباً. ""الضَّرُورَاتُ تُبِيحُ الْمَحْظُورَاتِ"". 4.""دَفَعَتْهُ الضَّرُورَةُ القُصْوَى إِلَى ذَلِكَ"" : الْحَاجَةُ الْمُلِحَّةُ وَقَدْ بَلَغَتْ أَقْصَاهَا، الشِّدَّةُ. 5.""الضَّرُورَةُ الشِّعْرِيَّةُ"" : الْحَالَةُ الَّتِي تَفْرِضُ عَلَى الشَّاعِرِ أَنْ يَلْتَجِئَ إِلَى اسْتِعْمَالِ مَا لاَ تُجِيزُهُ قَوَاعِدُ اللُّغَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11602, 'ضَرَائِرُ', 'ضرائر', 'جامد', '', 'ضراءر', 'ضرر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11603, 'ضَرُورِيَّاتٌ', 'ضروريات', 'جامد', 'ضرر', 'ضروريات', 'ضررت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"ضَرُورِيَّاتٌ-ضَرُورِيَّاتٌ [ض ر ر]. ""هَذَا مِنْ ضَرُورِيَّاتِ الْحَيَاةِ"" : الحَاجَاتُ الَّتِي لاَ غِنىً عَنْهَا لِلإِنْسَانِ. ""نَحْنُ فِي حَاجَةٍ إِلَى الضَّرُورِيَّاتِ وَأَنْتَ تُحَدِّثُنَا عَنِ الكَمَالِيَّاتِ"". (ميخائيل نعيمة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11604, 'مَضَرَّةٌ', 'مضرة', 'جامد', 'ضرر', 'مضرة', 'مضرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات:مَضَارُّ"', '', 'R', '', '', '', '', '', '', '". ""كَانَتْ مَضَارُّ الْحَرَائِقِ وَخِيمَةً"" : أَضْرَارُهُ. ""الْمُغَامَرَةُ لَهَا مَنَافِعُهَا وَمَضَارُّهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11605, 'مَضَارُّ', 'مضار', 'جامد', '', 'مضار', 'مضر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11606, 'تَضْرِيسٌ', 'تضريس', 'جامد', 'ضرس', 'تضريس', 'تضرس', '', '', '', 'مفرد', 'DnN', '', '', '"تَضَارِيسُ"', '', 'R', '', '', '', '', '', '', '". 1.""لُؤْلُؤَةٌ بِهَا تَضْرِيسٌ"" : بِهَا تَحْزِيزٌ، حَزٌّ أَوْ نُتُوءٌ. 2.""قَدَّمَ دَرْساً عَنْ تَضَارِيسِ الأَرْضِ العَرَبِيَّةِ"" : مَعْرِفَةُ سَطْحِهَا وَمَا فِيهَا مِن انْخِفَاضٍ وَارْتِفَاعٍ وَمُنْحَدَرَاتٍ وَهِضَابٍ وَجِبَالٍ وَوِدْيَانٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11607, 'تَضَارِيسُ', 'تضاريس', 'جامد', '', 'تضاريس', 'تضرس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11608, 'ضِرْسٌ', 'ضرس', 'جامد', 'ضرس', 'ضرس', 'ضرس', '', '', '', 'مفرد', 'DnN', '', '', '"أَضْرَاسٌ(مذ:مؤ)"', '', 'R', '', '', '', '', '', '', '". 1.""يُوجِعُهُ الضِّرْسُ"" : السِّنُّ الطَّاحِنَةُ. 2.""اِكْتَمَلَتْ أَضْرَاسُهُ"" : الأَسْنَانُ الْخَمْسَةُ الَّتِي تَكُونُ فِي كُلِّ جَانِبٍ مِنْ مُؤَخَّرِ الفَكَّيْنِ. 3.""ضِرْسُ العَقْلِ"" : سِنٌّ حَادَّةٌ تَخْرُجُ فِي أَقْصَى الأَضْرَاسِ. 4.""رَجُلٌ ضِرْسٌ"" : خَشِنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11609, 'أَضْرَاسٌ', 'أضراس', 'جامد', '', 'ءضراس', 'ضرس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11610, 'ضَرْعَاءُ', 'ضرعاء', 'جامد', 'ضرع', 'ضرعاء', 'ضرع', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"ضَرْعَاءُ-ضَرْعَاءُ [ض ر ع]. ""بَقَرَةٌ ضَرْعَاءُ"" : لَهَا ضَرْعٌ عَظِيمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11611, 'ضِرْعٌ', 'ضرع', 'جامد', 'ضرع', 'ضرع', 'ضرع', '', '', '', 'مفرد', 'DnN', '', '', '"ضُرُوعٌ"', '', 'R', '', '', '', '', '', '', '". ""هُوَ ضِرْعُهُ"" : مِثْلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11612, 'ضُرُوعٌ', 'ضروع', 'جامد', '', 'ضروع', 'ضرع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11613, 'ضِرْغَامٌ', 'ضرغام', 'جامد', 'ضرغم', 'ضرغام', 'ضرغم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضِرْغَامٌ-ضِرْغَامٌ [ض ر غ م]. 1.""خَرَجَ الضِّرْغَامُ مِنْ عَرِينِهِ وَمَخَالِبُهُ تَتَأَهَّبُ"" : الأَسَدُ الضَّارِي. 2.""رَجُلٌ ضِرْغَامٌ"" : شُجَاعٌ، قَوِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11614, 'ضِرَامٌ', 'ضرام', 'جامد', 'ضرم', 'ضرام', 'ضرم', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"ضِرَامٌ-ضِرَامٌ، ةٌ [ض ر م]. 1.""ضِرَامُ النَّارِ"" : لَهِيبُهَا، اِضْطِرَامُهَا، اِتِّقَادُهَا. ""إِنَّ الشَّرَارَةَ الخَفِيَّةَ رُبَّمَا صَارَتْ ضِرَاماً"". (التوحيدي). 2.""أَشْعَلَ النَّارَ بِضِرَامٍ أَوْ ضِرَامَةٍ"" : مَا تُشْعَلُ بِهِ النَّارُ مِنَ الْحَطَبِ سَرِيعِ الاشْتِعَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11615, 'ضَوَارِي', 'ضواري', 'جامد', 'ضري', 'ضواري', 'ضر', '', 'Tk', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"ضَوَارٍ-ضَوَارٍ، الضَّوَارِي [ض ر ي]. 1.""الأَسَدُ مِنْ ضَوَارِي الْحَيَوَانَاتِ"" : مِنَ الْحَيَوَانَاتِ الْمُفْتَرِسَةِ. 2.""الكِلاَبُ الضَّوارِي"" : الْمُدَرَّبَةُ عَلَى الصَّيْدِ. ن. ضَارِيَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11616, 'ضِعْفٌ', 'ضعف', 'جامد', 'ضعف', 'ضعف', 'ضعف', '', '', '', 'مفرد', 'DnN', '', '', '"أَضْعَافٌ"', '', 'R', '', '', '', '', '', '', '". 1.""ضِعْفُ الْمَبْلَغِ"" : مِثْلُهُ، مِقْدَارُهُ مَرَّتَيْنِ أَوْ مَا زَادَ عَلَى ذَلِكَ. ""يَمْلِكُ مِنَ الوَسَائِلِ أَضْعَافَ مَا عِنْدَ الآخَرِينَ"" ""هَذَا ضِعْفُ ذَاكَ"" : مِثْلُهُ، ""ضِعْفَاهُ"" : مِثْلاَهُ، ""أَضْعَافُهُ"" : أَمْثَالُهُ.سبأ آية 37 فَأُولَئِكَ لَهُمْ جَزَاءُ الضِّعْفِ بِمَا عَمِلُوا . (قرآن) : وَالزِّيَادَةُ هُنَا غَيْرُ مَحْصُورَةٍ. 2.""أَضْعَافُ الكِتَابِ"" : حَوَاشِيهِ وَمَا بَيْنَ سُطُورِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11617, 'أَضْعَافٌ', 'أضعاف', 'جامد', '', 'ءضعاف', 'ضعف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11618, 'أَضْغاثٌ', 'أضغاث', 'جامد', 'ضغت', 'ءضغاث', 'ضغث', '', '', '', 'مفرد', '', '', '', '"مفردضِغْث"', '', '', '', '', '', '', '', '', '"أَضْغاثٌ - جمع ضِغْث. [ض غ ت]. ""وَما هِيَ إِلاَّ أَضْغاثُ أَحْلامٍ"" : أَحْلامٌ مُخْتَلِفَةٌ مُتَداخِلَةٌ وَمُضْطَرِبَةٌ يَصْعُبُ تَأْوِيلُها وَتَفْسيرُها.يوسف آية 44 قالُوا أَضْغاثُ أَحْلامٍ وَما نَحْنُ بِتاويل الأَحلامِ بِعالِمينَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11619, 'ضِغْثٌ', 'ضغث', 'جامد', 'ضغث', 'ضغث', 'ضغث', '', '', '', 'مفرد', 'DnN', '', '', '"أَضْغَاثٌ"', '', 'R', '', '', '', '', '', '', '"ضِغْثٌ - ج: أَضْغَاثٌ. [ض غ ث]. ""ضِغْثُ نَبَاتٍ"": حُزْمَةٌ مِنَ النَّبَاتِ يَخْتَلِطُ فِيهَا الرَّطْبُ وَاليَابِسُ.ص آية 44 وَخُذْ بِيَدِكَ ضِغْثاً فَاضْرِبْ بِهِ وَلاَ تَحْنَثْ . (قرآن). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11620, 'أَضْغَاثٌ', 'أضغاث', 'جامد', '', 'ءضغاث', 'ضغث', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11621, 'ضَاغُوطٌ', 'ضاغوط', 'جامد', 'ضغط', 'ضاغوط', 'ضغط', '', '', '', 'مفرد', 'DnN', '', '', '"ضَوَاغِيطُ"', '', 'R', '', '', '', '', '', '', '". ""ضَاغُوطُ اللَّيْلِ"" : كَابُوسٌ."', '');
