INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11624, 'مَضَاغِطُ', 'مضاغط', 'جامد', '', 'مضاغط', 'مضغط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11625, 'ضَيْمٌ', 'ضيم', 'جامد', 'ضيم', 'ضيم', 'ضم', '', '', '', 'مفرد', 'DnN', '', '', '"ضُيُومٌ"', '', 'R', '', '', '', '', '', '', '". 1.""نَزَلَ بِهِ الضَّيْمُ"" : الظُّلْمُ. 2.""لاَ تَرْضَى نَفْسُهُ الضَّيْمَ"" : الإِذْلاَلَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11626, 'ضُيُومٌ', 'ضيوم', 'جامد', '', 'ضيوم', 'ضم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11627, 'ضِغْنٌ', 'ضغن', 'جامد', 'ضغن', 'ضغن', 'ضغن', '', '', '', 'مفرد', 'DnN', '', '', '"أَضْغَانٌ"', '', 'R', '', '', '', '', '', '', '". ""مَايَزَالُ يَحْمِلُ فِي قَلْبِهِ ضِغْناً"" : حِقْداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11628, 'أَضْغَانٌ', 'أضغان', 'جامد', '', 'ءضغان', 'ضغن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11629, 'ضَغِينَةٌ', 'ضغينة', 'جامد', 'ضغن', 'ضغينة', 'ضغنة', '', '', '', 'مفرد', 'DnN', '', '', '"ضَغَائِنُ"', '', 'R', '', '', '', '', '', '', '". ""يَكِنُّ لَهُ ضَغِينَةً"" : حِقْداً. ""الْمِرَاءُ يُقَسِّي القُلُوبَ وَيُورِثُ الضَّغَائِنَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11630, 'ضَغَائِنُ', 'ضغائن', 'جامد', '', 'ضغاءن', 'ضغن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11631, 'ضِفْدَعَةٌ', 'ضفدعة', 'جامد', 'ضفدع', 'ضفدعة', 'ضفدعة', '', '', '', 'مفرد', 'DnN', '', '', '"واحدةالضِّفْدَعِ"', '', 'R', '', '', '', '', '', '', '"ضِفْدَعَةٌ-ضِفْدَعَةٌ [ض ف د ع] (وَاحِدَةُ الضِّفْدَعِ). ""الرَّجُلُ الضِّفْدَعَةُ"" : الغَطَّاسُ فِي الْمَاءِ لِمَعْرِفَةِ قِيعَانِ البِحَارِ أَوِ الاِشْتِرَاكِ فِي العَمَلِيَّاتِ العَسْكَرِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11632, 'ضِفْدَعٌ', 'ضفدع', 'جامد', 'ضفدع', 'ضفدع', 'ضفدع', '', '', '', 'مفرد', 'DnN', '', '', '"ضَفَادِعُ"', '', 'R', '', '', '', '', '', '', '"(حو) (لِلْمُذَكَّرِ وَالْمُؤَنَّثِ). 1.: مِنْ فَصِيلَةِ الضِّفْدَعِيَّاتِ، بَرْمَائِيٌّ لاَ ذَنَبَ لَـهُ، رَخْوٌ، دَقِيقُ العِظَامِ، جَمِيلُ السِّبَاحَةِ، وَهُوَ أَنْوَاعٌ، ضَفَادِعُ الْمَاءِ، وَضَفَادِعُ الجَبَلِ، ذُو نَقِيقٍ، يَبِيضُ فِي الْمَاءِ وَيَلْتَصِقُ بَيْضُهُ بَعْضُهُ بِبَعْضٍ، وَبَعْضُ أَنْوَاعِ الضّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11633, 'ضَفَادِعُ', 'ضفادع', 'جامد', '', 'ضفادع', 'ضفدع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11634, 'ضِفْدَعِيَّاتٌ', 'ضفدعيات', 'جامد', '', 'ضفدعيات', 'ضفدعت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ حَيَوَانِيَّةٌ مِنَ الفِقْرِيَّاتِ جِلْدِيَّةِ التَّنَفُّسِ، بَرْمَائِيَّةٌ، أَنْوَاعُهَا عَدِيدَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11635, 'ضَفِيرَةٌ', 'ضفيرة', 'جامد', 'ضفر', 'ضفيرة', 'ضفرة', '', '', '', 'مفرد', 'DnN', '', '', '"ضَفَائِرُ"', '', 'R', '', '', '', '', '', '', '". ""جَعَلَتْ مِنْ شَعْرِهَا ضَفِيرَةً وَاحِدَةً"" : خُصْلَةً وَاحِدَةً. ""مِنْ تَقَالِيدِ الْمَرْأَةِ الإِفْرِيقِيَّةِ أَنْ تَجْعَلَ مِنْ شَعْرِهَا ضَفَائِرَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11636, 'ضَفَائِرُ', 'ضفائر', 'جامد', '', 'ضفاءر', 'ضفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11637, 'ضِفَّةٌ', 'ضفة', 'جامد', 'ضفف', 'ضفة', 'ضفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":ضِفَافٌ:ضِفَفٌ"', '', 'R', '', '', '', '', '', '', '". 1.""ضِفَّةُ النَّهْرِ"" : شَطُّهُ، جَانِبُهُ. 2.""ضِفَّةُ البَحْرِ"" : سَاحِلُهُ. ""الضَّفَّتَانِ"" : الضَّفَّةُ الغَرْبِيَّةُ وَالضَّفَّةُ الشَّرْقِيَّةُ"" ."', '');
