INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11640, 'ضَلَلٌ', 'ضلل', 'جامد', 'ضلل', 'ضلل', 'ضل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَلَلٌ-ضَلَلٌ [ض ل ل]. 1.""هُوَ فِي ضَلَلٍ"" : فِي مَيْلٍ عَنِ الْهُدَى وَالاِسْتِقَامَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11641, 'مَضْيَعَةٌ', 'مضيعة', 'جامد', 'ضيع', 'مضيعة', 'مضعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَضْيَعَةٌ-مَضْيَعَةٌ [ض ي ع]. ""كَلاَمُهُ مَضْيَعَةٌ لِلْوَقْتِ"" : أَيْ لاَ فَائِدَةَ مِنْهُ، فِيهِ ضَيَاعٌ لِلْوَقْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11642, 'ضِمَادَةٌ', 'ضمادة', 'جامد', 'ضمد', 'ضمادة', 'ضمدة', '', '', '', 'مفرد', 'DnN', '', '', '"ضَمَائِدُ"', '', 'R', '', '', '', '', '', '', '". 1.""لَفَّ الضِّمَادَةَ عَلَى الْجُرْحِ"" : الضِّمَادَ. 2. : حِرْفَةُ الضَّامِدِ أَوِ الْمُضَمِّدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11643, 'ضَمَائِدُ', 'ضمائد', 'جامد', '', 'ضماءد', 'ضمد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11644, 'ضُمْرٌ', 'ضمر', 'جامد', 'ضمر', 'ضمر', 'ضمر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضُمْرٌ-ضُمْرٌ [ض م ر]. ""بِهِ ضُمْرٌ"" : هُزَالٌ، نَحَافَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11645, 'ضَمِيرٌ', 'ضمير', 'جامد', 'ضمر', 'ضمير', 'ضمر', '', '', '', 'مفرد', 'DnN', '', '', '"ضَمَائِرُ"', '', 'R', '', '', '', '', '', '', '". : مَا يُضْمِرُهُ الإِنْسَانُ فِي نَفْسِهِ وَيَصْعُبُ الوُقُوفُ عَلَيْهِ، وَيُعَبَّرُ عَنْهُ بِالقِيَمِ سَلْباً أَوْ إِيجَاباً. 1.""حَيُّ الضَّمِيرِ"" : لَهُ نَفْسٌ تُضْمِرُ حَيَوِيَّةً وَتَيَقُّظاً وَأَنَفَةً. 2.""فَاقِدُ الضَّمِيرِ"" : لاَ شَيْءَ يُحَرِّكُ وَعْيَهُ وَإِدْرَاكَهُ وَإِحْسَاسَهُ. 3.""تَأْنِيبُ الضَّمِيرِ"" : مَا يُحِسُّهُ الْمَرْءُ مِنْ تَأْنِيبٍ وَعَذَابٍ وَنَدَمٍ نَتِيجَةَ سُلُوكٍ مُشِينٍ قَامَ بِهِ. 4.""وَجَدَهُ مُرْتَاحَ الضَّمِيرِ"" : هَادِئَ البَالِ. 5.""الضَّمي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11646, 'ضَمَائِرُ', 'ضمائر', 'جامد', '', 'ضماءر', 'ضمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11647, 'إِضْمامَةٌ', 'إضمامة', 'جامد', 'ضمم', 'ءضمامة', 'إضممة', '', '', '', 'مفرد', 'DnN', '', '', '"أَضامِيم"', '', 'R', '', '', '', '', '', '', '". 1.""قَدَّمَ لَهُ إِضْمامَةً مِنَ الوَرْدِ"" : باقَةً. 2.""قَدَّمَتْ لَهُ إِضْمامَةً مِنَ الكُتُبِ في آخِرِ السَّنَةِ"": مَجْموعَةً مِنَ الكُتُبِ، إِضْبارَةً."', '');
