INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11649, 'ضِمْنٌ', 'ضمن', 'جامد', 'ضمن', 'ضمن', 'ضمن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضِمْنٌ-ضِمْنٌ [ض م ن]. 1.""تُوجَدُ ضِمْنَ الكِتَابِ وَثَائِقُ تَارِيخِيَّةٌ"" : فِي طَيِّهِ. 2.""كَانَ مِنْ ضِمْنِهِمْ"" : مِنْ بَيْنِهِمْ، فِي عِدَادِهِمْ. 3."" اعْتَرَفَ بِذَنْبِهِ ضِمْناً"" : الشَّيْءُ الْمُعَبَّرُ عَنْهُ بِالكَلاَمِ بِشَكْلٍ غَيْرِ مُبَاشِرٍ وَمِنْ غَيْرِ تَصْرِيحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11650, 'مَضْمُونٌ', 'مضمون', 'جامد', 'ضمن', 'مضمون', 'مضمن', '', '', '', 'مفرد', 'DnN', '', '', '"مَضَامِينُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""مَضْمُونُ جُمْلَةٍ"" : فَحْوَاهَا وَمَا تُشِيرُ إِلَيْهِ. ""فَهِمَ مَضْمُونَ الْحَدِيثِ""."', '');
