INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11674, 'طَبَائِعُ', 'طبائع', 'جامد', 'طبع', 'طباءع', 'طبع', '', '', '', 'مفرد', '', '', '', '"مفردطَبِيعَة"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '". ""الطَّبَائِعُ الأَرْبَعُ"" : الْحَرَارَةُ، البُرُودَةُ، الرُّطُوبَةُ، اليُبُوسَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11675, 'طَبِيعَةٌ', 'طبيعة', 'جامد', 'طبع', 'طبيعة', 'طبعة', '', '', '', 'مفرد', 'DnN', '', '', '"طَبَائِعُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""عَالِمُ الطَّبِيعَةِ"" : عَالِمُ الكَائِنَاتِ بِمَا فِيهَا مِنْ مَخْلُوقَاتٍ وَجِبَالٍ وَأَوْدِيَةٍ وَنَبَاتاتٍ وَسَمَاوَاتٍ. 2.""لَهُ طَبِيعَةٌ هَادِئَةٌ"" : سَجِيَّةٌ، أَيْ مَا جُبِلَ عَلَيْهِ الإِنْسَانُ مِنْ سُلُوكٍ وَخُلُقٍ. ""عَلَى طَبِيعَتِهِ"". 3.""طَبِيعَةُ النَّفْسِ"": خَصِيصَتُهَا وَصِفَاتُهَا. 4.""الطَّبَائِعُ الأَرْبَعُ"" : الْحَ"', '');
