INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11680, 'مَطْبُوعَةٌ', 'مطبوعة', 'جامد', 'طبع', 'مطبوعة', 'مطبعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""مَطْبُوعَاتُ دَارِ النَّشْرِ"": مَنْشُورَاتٌ، أَيْ مَا يُنْشَرُ مِنَ الكُتُبِ."', '');
