INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11684, 'طَبَقَةٌ', 'طبقة', 'جامد', 'طبق', 'طبقة', 'طبقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":طَبَقٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""طَبَقَةٌ مِنَ النَّاسِ"" : شَرِيَحَةٌ، فِئَةٌ. ""النَّاسُ عَلَى طَبَقَاتٍ شَتّى وَالنَّاسُ طَبَقَاتٌ"" ""طَبَقَةٌ اِجْتِمَاعِيَّةٌ"" ""طَبَقَةٌ وُسْطَى"" ""طَبَقَةٌ بُورْجُوَازِيَّةٌ"" ""طَبَقَةُ الأَغْنِيَاءِ"" ""الطَّبَقَةُ العَامِلَةُ"". 2. الملك آية 3 أَلَمْ تَرَوْا كَيْفَ خَلَقَ اللَّهُ سَبْعَ سَمَاوَاتٍ طِبَاقاً (قرآن) : دَرَجَاتٍ، مَنَازِلَ، مَر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11685, 'طَبَقٌ', 'طبق', 'جامد', '', 'طبق', 'طبق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
