INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11689, 'طَبْلِيَّةٌ', 'طبلية', 'جامد', 'طبل', 'طبلية', 'طبلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""جَلَسَ إِلَى الطَّبْلِيَّةِ"" : خِوَانٌ مُسْتَدِيرٌ مُنْخَفِضٌ يُؤْكَلُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11690, 'طَابُونٌ', 'طابون', 'جامد', 'طبن', 'طابون', 'طبن', '', '', '', 'مفرد', 'DnN', '', '', '"طَوَابِينُ"', '', 'R', '', '', '', '', '', '', '". ""طَابُونُ النَّارِ"" : حُفْرَةٌ تُدْفَنُ فِيهَا النَّارُ لِئَلا تُطْفَأَ، وَقَدْ يُطْلَقُ أَيْضاً عَلَى الْمَخْبَزِ أَوِ الفُرْنِ."', '');
