INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11692, 'طُبْيٌ', 'طبي', 'جامد', 'طبي', 'طبي', 'طب', '', '', '', 'مفرد', 'DnN', '', '', '"أَطْبَاءٌ"', '', '', '', '', '', '', '', '', '". ""طُبْيُ النَّاقَةِ"" : حَلَمَةُ ضَرْعِهَا الَّتِي فِيهَا اللَّبَنُ، أَيْ مَا يَرْضِعُ مِنْهُ الرَّضِيعُ."', '');
