INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11696, 'طُبٌّ', 'طب', 'جامد', 'طبب', 'طب', 'طب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طِبٌّ-طِبٌّ [ط ب ب] (مص. طَبَّ). 1.""يَتَعَاطَى الطِّبَّ"" : عِلاَجُ الْجِسْمِ وَالنَّفْسِ. 2.""طَالِبٌ فِي كُلِّيَّةِ الطِّبِّ"" : الكُلِّيَّةُ الَّتِي يَدْرُسُ فِيهَا الطُّلاَّبُ أُسْلُوبَ عِلاَجِ الأَمْرَاضِ وَتَشْرِيحِهَا. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11697, 'طِحَالٌ', 'طحال', 'جامد', 'طحل', 'طحال', 'طحل', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":طُحُلٌ"', '', 'R', '', '', '', '', '', '', '".: غُدَّةٌ فِي جَوْفِ الإِنْسَانِ وَالْحَيَوَانِ بِالْجَنْبِ الأَيْسَرِ، سَوْدَاءُ اللَّوْنِ، لَهَا وَظِيفَةٌ تَتَعَلَّقُ بِتَكْوِينِ الدَّمِ وَإِتْلاَفِ الفَاسِدِ مِنْ كُرَيَّاتِهِ."', '');
