INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11702, 'طَاحُونٌ', 'طاحون', 'جامد', 'طحن', 'طاحون', 'طحن', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '":طَوَاحِينُ"', '', 'R', '', '', '', '', '', '', '". 1.""تُدِيرُ الطَّاحُونَ"" :الرَّحَى، أَيْ آلَةٌ لِطَحْنِ الْحَبِّ. 2.""حَمَلَتِ القَمْحَ إِلَى الطَّاحُونِ"" : بَيْتُ الطَّحْنِ. 3.""طَاحُونَةٌ هَوَائِيَّة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11703, 'طَوَاحِينُ', 'طواحين', 'جامد', '', 'طواحين', 'طحن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11704, 'طِحْنٌ', 'طحن', 'جامد', 'طحن', 'طحن', 'طحن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طِحْنٌ - [ط ح ن]. ""أَسْمَعُ جَعْجَعَةً وَلاَ أَرَى طِحْناً"" (مثل) :  أَيْ لاَ أَرَى طَحِيناً، دَقِيقا"', '');
