INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11717, 'طَرِيدٌ', 'طريد', 'جامد', 'طرد', 'طريد', 'طرد', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"طَرَائِدُ"', '', 'R', '', '', '', '', '', '', '"طَرِيدٌ، ةٌ - ج: طَرَائِدُ. [ط ر د]. 1.""خَرَجَ مِنْ قَرْيَتِهِ طَرِيداً"" : هَارِباً أَوْ مَطْرُوداً. 2.""هُوَ طَرِيدُ أَخِيهِ"" : وُلِدَ بَعْدَهُ.   ""كُلٌّ مِنْهُمَا طَرِيدُ الآخَرِ"". 3.""الطَّرِيدَانِ"" : اللَّيْلُ وَالنَّهَارُ. 4.""تَعَقَّبَ الطَّرِيدَةَ"" : مَا يُطَارِدُهُ الصَّيَّادُ مِنْ صَيْدٍ. 5.""عَادَ بِلا طَرَائِدَ"" : بِلا صَيْد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11718, 'طَرَائِدُ', 'طرائد', 'جامد', '', 'طراءد', 'طرد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11719, 'مُطَارِدَةٌ', 'مطاردة', 'جامد', 'طرد', 'مطاردة', 'مطردة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". ""مُطَارِدَةٌ حَرْبِيَّةٌ"" : طَائِرَةٌ حَرْبِيَّةٌ ذَاتُ سُرْعَةٍ فَائِقَةٍ، تُتَّخَذ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11720, 'طَارَّةٌ', 'طارة', 'جامد', 'طرر', 'طارة', 'طرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '"طَارَّةٌ - ج: ات. [ط ر ر]. ""لُعْبَةُ الطَّارَّةِ"" : عَجَلَةٌ خَفِيفَةٌ مِنَ اللَّوْحِ أَوِ النَّيْلونُ يَدْفَعُهَا الأَطْفَالُ أَمَامَهُمْ بِعَصاً تَجْعَلُهَا تَتَدَحْرَجُ، وَتَجْعَلُهُمْ يَجْرُونَ وَرَاءهَا. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11721, 'طُرَّةٌ', 'طرة', 'جامد', 'طرر', 'طرة', 'طرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":طُرَرٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""طُرَّةُ الكِتَابِ"" : هَامِشُهُ. 2.""طُرَّةُ الثَّوْبِ"" : حَاشِيَتُهُ. ""تَعْرِفُ كَيْ"', '');
