INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11732, 'طَسٌّ', 'طس', 'جامد', '', 'طس', 'طس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"طُسُوتٌ(مذ:مؤ)"', '', 'R', '', '', '', '', '', '', '"ج: طُسُوتٌ. (مذ، مؤ). ""قَدَّمَ لَهُ الطَّسْتَ لِغَسْلِ يَدَيْهِ"" : إِنَاءٌ مِنْ نُحَاسٍ، طَاسٌ."', ':لا جذر:لا مفرد');
