INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11734, 'أَطْرافٌ', 'أطراف', 'جامد', 'طرف', 'ءطراف', 'طرف', '', '', '', 'مفرد', '', '', '', '"مفردطَرَف"', '', '', '', '', '', '', '', '', '". 1.""لِلْبَدَنِ أَطْرافُهُ"" : اليَدانِ والرِّجْلانِ والرَّأْسُ. 2.""وَقَفْنا عِنْدَ أَطْرافِ الْمَدينَةِ"" : نَواحِيها. 3.""أَطْرافُ الأحاديثِ"" : ما يُتَبادَلُ مِنَ الأَحاديثِ الشَّيِّقَةِ، وَبالأَخَصِّ بَيْنَ الْمُحِبِّينَ. ""أ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11735, 'طَرَائِفُ', 'طرائف', 'جامد', 'طرف', 'طراءف', 'طرف', '', '', '', 'مفرد', '', '', '', '"مفردطَرِيفَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""طَرَائِفُ الْحَدِيثِ"" : مُخْتَارَاتُهُ."', '');
