INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11737, 'طُرْفَةٌ', 'طرفة', 'جامد', 'طرف', 'طرفة', 'طرفة', '', '', '', 'مفرد', 'DnN', '', '', '"طُرَفٌ"', '', 'R', '', '', '', '', '', '', '". ""حَكَى لَهُ طُرْفَةً"" : نُكْتَةً، مُلْحَةً، الكَلاَمُ الْمُسْتَمْلَحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11738, 'طُرَفٌ', 'طرف', 'جامد', '', 'طرف', 'طرف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11739, 'طَرَفٌ', 'طرف', 'جامد', 'طرف', 'طرف', 'طرف', '', '', '', 'مفرد', 'DnN', '', '', '"أَطْرَافٌ"', '', 'R', '', '', '', '', '', '', '". 1.""طَرَفُ الْحَدِيقَةِ"" : جَانِبُهَا، نَاحِيَتُهَا. ""تَجَوَّلَ فِي أَطْرَافِ الْمَدِينَةِ"" : فِي نَوَاحِيهَا، فِي ضَوَاحِيهَا. 2.""طَرَفَا النَّهَارِ"" : أَوَّلُهُ وَآخِرُهُ.هود آية 114 وَأَقِمِ الصَّلاَةَ طَرَفَيِ النَّهَارِ (قرآن). 3.""مُتَرَامِي الأَطْرَافِ"": مُتَّسِعُ الأَرْجَاءِ ، الأَبْعَادِ. 4.""أَطْرَافُ الإنْسانِ"" : أَعْضَاؤُهُ. 5.""تَجَاذَبَ أَطْرَافَ الْحَدِيثِ"" : تَحَدَّثَ مَعَهُ فِي مُخْتَلِفِ الْمَوَاضِيعِ. 6.""تَع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11740, 'أَطْرَافٌ', 'أطراف', 'جامد', '', 'ءطراف', 'طرف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11741, 'طَرْفَاءُ', 'طرفاء', 'جامد', '', 'طرفاء', 'طرف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', 'N', 'O', 'O', 'O', '', '"طَرْفَاءُ-طَرْفَاءُ (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الطَّرْفَائِيَّاتِ، وَهِيَ شُجَيْرَةٌ لَهَا أَوْرَاقٌ صَغِيرَةٌ حَرْشَفِيَّةٌ، تُعْطِي زُهُورًا وَرْدِيَّةً سُنْبُلِيَّةً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11742, 'طَرْفَائِيَّاتٌ', 'طرفائيات', 'جامد', '', 'طرفاءيات', 'طرفت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"طَرْفَائِيَّاتٌ-طَرْفَائِيَّاتٌ (نب).: فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ أَشْهَرِ أَنْوَاعِهَا الطَّرْفَاءُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11743, 'طَارِقٌ', 'طارق', 'جامد', 'طرق', 'طارق', 'طرق', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"طُرَّاقٌ:أَطْرَاقٌ:طَوَارِقُ"', '', 'R', '', '', '', '', '', '', '". 1.""النَّجْمُ الطَّارِقُ"" : نَجْمُ الصُّبْحِ.الطارق آية 2 ، 3 وَمَا أَدْرَاكَ مَا الطَّارِقُ النَّجْمُ الثَّاقِبُ (قرآن) . 2.""نَحْنُ بَنَاتُ طَارِقٍ"" : أَيْ إِنَّ أَبَانَا عالِي الْمَقَامِ كَالنَّجْمِ ال"', '');
