INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11747, 'طُرْقَةٌ', 'طرقة', 'جامد', 'طرق', 'طرقة', 'طرقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"طُرْقَةٌ-طُرْقَةٌ [ط ر ق]. 1.""لَهُ طُرْقَتُهُ"" : مَذْهَبُهُ. 2.""تِلْكَ طُرْقَتُهُ"" : عَادَتُهُ، ما دَأَبَ عَلَيْهِ. 3.""سَارَ فِي طُرْقَةٍ سَالِكَةٍ"" : طَرِيقٍ."', '');
