INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11753, 'مِطْرَقَةٌ', 'مطرقة', 'جامد', 'طرق', 'مطرقة', 'مطرقة', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَارِقُ"', '', 'R', '', '', '', '', '', '', '". ""دَقَّ المِسْمَارَ بِالمِطْرَقَةِ"" : آلَةٌلِلدَّقِّ، لَهَا رَأْسٌ مِنْ حَدِيدٍ يَشُدُّهُ مِقْبَضٌ مِنْ خَشَبٍ أَوْ نَحْوِهِ. ""وَقَعَ بَيْنَ السِّنْدَانِ وَالْمِطْرَقَةِ""."', '');
