INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11756, 'طِعَمٌ', 'طعم', 'جامد', '', 'طعم', 'طعم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11757, 'طُعْمٌ', 'طعم', 'جامد', 'طعم', 'طعم', 'طعم', '', '', '', 'مفرد', 'DnN', '', '', '"طُعُومٌ:أَطْعَامٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""جَعَلَ الطُّعْمَ فِي الصِّنَّارَةِ"" : مَا يُوضَعُ مِنْ طَعَامٍ فِي رَأْسِ الصِّنَّارَةِ لِجَلْبِ السَّمَكِ، أَوْ كُلُّ مَا يُرَادُ صَيْدُهُ. 2.""طُعْمُ التَّلْقِيحِ"" : مَا يُحْقَنُ بِهِ الْجِسْمُ لإِكْسَابِهِ مَنَاعَةً ضِدَّ الأَمْرَاضِ، الْمَصْلُ. 3.""قَلَّ طُعْمُ الوَلَدِ"" : أَيْ قَلَّ أَكْلُهُ، قَلَّتْ قُدْرَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11758, 'طُعُومٌ', 'طعوم', 'جامد', '', 'طعوم', 'طعم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
