INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11760, 'طَعْمِيَّةٌ', 'طعمية', 'جامد', 'طعم', 'طعمية', 'طعمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"طَعْمِيَّةٌ-طَعْمِيَّةٌ [ط ع م]. : طَعَامٌ شَعْبِيٌّ يُتَّخَذُ مِنَ الفُولِ الْمَدْقُوقِ وَتُضَافُ إِلَيْهِ الْخُضَرُ مَعَ تَوَابِلَ، ثُمَّ يُجْعَلُ أَقْرَاصاً صِغَاراً تُقْلَى بِالزَّيْتِ، يُعْرَفُ بِأُمِّ الفَلاَفِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11761, 'مَطْعَمٌ', 'مطعم', 'جامد', 'طعم', 'مطعم', 'مطعم', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَاعِمُ"', '', 'R', '', '', '', '', '', '', '". 1. ""تَنَاوَلَ غَدَاءهُ في الْمَطْعَمِ"" : قَاعَةٌ فِي مَبْنـىً عُمُومِيٍّ لِتَنَاوُلِ الطَّعَامِ مُقَابِلَ ثَمَنٍ. ""الْمَطْعَمُ الْمَدْرَسِيُّ"" : قَاعَةٌ لِلْأَكْلِ فِي مَدْرَسَةٍ دَاخِلِيَّةٍ. ""الْمَطْعَمُ الجَامِعِيُّ"" : خَاصٌّ بِطُلاَّبِ الجَامِعَةِ. 2.""مَطْعَمُ الْخِدْمَةِ الذَّاتِيَّةِ"" : مَطْعَمٌ عُمُومِيٌّ يَتَوَلَّى الزُّبُنُ فِيهِ خِدْمَةَ أَنْفُسِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11762, 'مَطَاعِمُ', 'مطاعم', 'جامد', '', 'مطاعم', 'مطعم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
