INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11764, 'طَوَاعِينُ', 'طواعين', 'جامد', '', 'طواعين', 'طعن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11765, 'مَطْعَنٌ', 'مطعن', 'جامد', 'طعن', 'مطعن', 'مطعن', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَاعِنُ"', '', 'R', '', '', '', '', '', '', '". ""مَا زَالَ مَطْعَنُهُ يُؤْلِمُهُ"": مَوْضِعُ الطَّعْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11766, 'مَطَاعِنُ', 'مطاعن', 'جامد', '', 'مطاعن', 'مطعن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11767, 'طُغْرَاءُ', 'طغراء', 'جامد', '', 'طغراء', 'طغر', '', '', '', 'جمع تكسير', '', '', '', '"طُغْرَاءاتٌ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"ج: طُغْرَاءاتٌ. 1.""طُغْرَاءُ الْمَسْكُوكَاتِ"" : عَلاَمَتُهَا الْمُمَيِّزَةُ لَهَا. 2.""طُغْرَاءُ الرِّسَالَةِ"" : الطُّرَّةُ، مَا يَكُونُ فِي أَعْلاَهَا مِنْ مَعْلُومَاتٍ أَوْ صِفَاتٍ مُتَعَلِّقَةٍ بِالْحَاكِمِ وَأَلْقَابِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11768, 'طُغْرَاءاتٌ', 'طغراءات', 'جامد', '', 'طغراءات', 'طغرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11769, 'طُغْمَةٌ', 'طغمة', 'جامد', 'طغم', 'طغمة', 'طغمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":طُغَمٌ"', '', 'R', '', '', '', '', '', '', '". ""طُغْمَةٌ مِنَ النَّاسِ"" : الْجَمَاعَةُ مِنْهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11770, 'طُغَمٌ', 'طغم', 'جامد', '', 'طغم', 'طغم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11771, 'طَاغُوتٌ', 'طاغوت', 'جامد', 'طغو', 'طاغوت', 'طغت', '', '', '', 'مفرد', 'DnN', '', '', '"طَوَاغِيتُ"', '', 'R', '', '', '', '', '', '', '". 1.""حَاكِمٌ طَاغُوتٌ"": طَاغٍ، مُتَجَبِّرٌ، ظَالِمٌ. 2.""اِحْتَرِسْ مِنَ الطَّاغُوتِ"" : مِنَ الشَّيْطَانِ.النحل آية 36 اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ (قرآن)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11772, 'طَوَاغِيتُ', 'طواغيت', 'جامد', '', 'طواغيت', 'طغت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11773, 'مِطْفَأَةٌ', 'مطفأة', 'جامد', 'طفأ', 'مطفءة', 'مطفة', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَافِئُ"', '', '', '', '', '', '', '', '', '". 1.""مِطْفَأَةٌ اِحْتِيَاطِيَّةٌ"" : آلَةُ الإِطْفَاءِتَكُونُ فِي مَدَاخِلِ بَعْضِ الْمُؤَسَّسَاتِ. 2.""هَبَّ رِجَالُ الْمَطَافِئِ إِلَى مَكَانِ الْحَرِيقِ"" : الرِّجَالُ الَّذِينَ يُطْفِئُونَ الْحَرِيقَ. 3.""مِطْفَأَةُ السَّجَائِرِ"" : وِعَاءٌ تُطْفَأُ فِيهِ السَّجَائِرُ، مَنْفَضَةُ السَّجائِرِ."', '');
