INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11775, 'طَفْرَةٌ', 'طفرة', 'جامد', 'طفر', 'طفرة', 'طفرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""حَقَّقَ طَفْرَةً فِي عَمَلِهِ"" : وَثْبَةً، أَيْ مَزِيداً مِنَ التَّقَدُّمِ. 2.""حَدَثَ هَذَا طَفْرَةً"" : فَجْأَةً دُونَ تَدَرَّجٍ. 3.""طَفْرَةُ اللَّبَنِ"" : خُثُورَتُهُ، اِشْتِدادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11776, 'طَفْطَافَةٌ', 'طفطافة', 'جامد', 'طفطف', 'طفطافة', 'طفطفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":طَفَاطِيفُ"', '', 'R', '', '', '', '', '', '', '". : الدَّرَّاجَةُ النَّارِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11777, 'طَفَاطِيفُ', 'طفاطيف', 'جامد', '', 'طفاطيف', 'طفطف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11778, 'طَفْطَافٌ', 'طفطاف', 'جامد', 'طفطف', 'طفطاف', 'طفطف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَفْطَافٌ-طَفْطَافٌ [ط ف ط ف]. 1. ""نَبَاتٌ طَفْطَافٌ"" : رَطْبٌ. 2.""طَفْطَافُ الشَّجَرِ"" : أَطْرَافُهُ. 3.""طَفْطَافُ غُصْنٍ"" : وَرَقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11779, 'طِفْلٌ', 'طفل', 'جامد', 'طفل', 'طفل', 'طفل', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '":أَطْفَالٌ(وَقَدْيَسْتَوِيفِي', '', 'R', '', '', '', '', '', '', '". 1.""تُلاَعِبُ طِفْلَهَا"" : أَيْ وَلَدَهَا الصَّغِيرَ. 2.""لاَيَزَالُ طِفْلاً"" : صَغِيراً، لَمْ يَصِلْ سِنَّ البُلُوغِ بَعْدُ.النور آية 59 وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا (قرآن) ""لِكُلِّ طِفْلٍ حَقٌّ أَصِيلٌ فِي الْحَيَاةِ وَفِي التَّعْلِيمِ وَفِي الْحِفَاظِ عَلَى هُوِيَّتِهِ"". 3.""طِفْلُ النَّارِ"" : جَمْرَتُهَا، شَرَارَتُهَا. ""تَطَايَرَتْ أَطْفَالُ النَّارِ"". 4.""عُشْبٌ طِفْلٌ"" : قَصِيرٌ. 5."" أَتَيْتُهُ وَاللَّيْلُ طِفْلٌ"" : فِي أَوَّلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11780, 'أَطْفَالٌ', 'أطفال', 'جامد', '', 'ءطفال', 'طفل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11781, 'طَفَّايَةٌ', 'طفاية', 'جامد', 'طفأ', 'طفاية', 'طفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""اِسْتَخْدَمَ رِجَالُ الْمَطَافِئِ الطَّفَّايَاتِ لإِطْفَاءِ الْحَرِيقِ"" : جِهَازٌ يُسْتَعْمَلُ لإِطْفَاءِ الْحَرِيقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11782, 'طَفَاوَةٌ', 'طفاوة', 'جامد', 'طفو', 'طفاوة', 'طفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"طَفَاوَةٌ-طَفَاوَةٌ [ط ف و]. ""طَفَاوَةُ الشَّمْسِ"" : داَرَتُهَا. ""طَفَاوَةُ القَمَرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11783, 'طُفَاوَةٌ', 'طفاوة', 'جامد', 'طفو', 'طفاوة', 'طفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"طُفَاوَةٌ-طُفَاوَةٌ [ط ف و]. ""طُفَاوَةُ القِدْرِ"" : مَا عَلاَهُ مِنْ زَبَدٍ وَنَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11784, 'طَقْسٌ', 'طقس', 'جامد', '', 'طقس', 'طقس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"طُقُوسٌ"', '', 'R', '', '', '', '', '', '', '"ج: طُقُوسٌ. 1.""تَغَيَّرَ الطَّقْسُ فَجْأَةً"" : حَالَةُ الْجَوِّ مِنْ بَرْدٍ وَحَرَارَةٍ وَاعْتِدَالٍ فِي مَكَانٍ وَزَمَانٍ مُعَيَّنَيْنِ. ""حَالَةُ الطَّقْسِ"". 2.""الطَّقْسُ عِنْدَ الْمَسِيحِيِّينَ"" : نِظَامُ العِبَادَاتِ الدِّينِيَّةِ وَأَشْكالِها، شَعاَئِرُهَا وَاحْتِفَالاَتُهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11785, 'طُقُوسٌ', 'طقوس', 'جامد', '', 'طقوس', 'طقس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11786, 'طَقْمٌ', 'طقم', 'جامد', 'طقم', 'طقم', 'طقم', '', '', '', 'مفرد', 'DnN', '', '', '"طُقُومٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِرْتَدَى طَقْماً أَنِيقاً"" : البَدْلَةُ. 2.""جَهَّزَ فَرَسَهُ بِطَقْمٍ كَامِلٍ"" : عُدَّةُ الْفَرَسِ. 3.""نَظَّفَ طَقْمَ أَسْنَانِهِ"" : مَجْمُوعُ أَسْنَانِهِ. 4. ""طَقْمُ مُجَوْهَرَاتٍ"" : مَجْمُوعَ مُجَوْهَرَاتٍ تُكَمِّلُ إِحْدَاهَا الأُخْرَى. 5.""طَقْمُ الشَّايِ"": مَجْمُوعَةُ أَوَانِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11787, 'طُقُومٌ', 'طقوم', 'جامد', '', 'طقوم', 'طقم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11788, 'طَلِبَةٌ', 'طلبة', 'جامد', 'طلب', 'طلبة', 'طلبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"طَلِبَةٌ-طَلِبَةٌ [ط ل ب]. ""لَبَّى طَلْبَتَهُ"" : حَاجَتَهُ، أَوْ مَا هُوَ مَطْلُوبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11789, 'طَلْبَةٌ', 'طلبة', 'جامد', 'طلب', 'طلبة', 'طلبة', '', '', '', 'مفرد', 'DnN', '', '', '"طِلَبٌ"', '', 'R', '', '', '', '', '', '', '". ""مَا طِلْبَتُكَ أَيُّهَا الوَلَدُ"" : مَا هُوَ مَطْلُوبُكَ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11790, 'طِلَبٌ', 'طلب', 'جامد', '', 'طلب', 'طلب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11791, 'طَلَبِيَّةٌ', 'طلبية', 'جامد', 'طلب', 'طلبية', 'طلبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"طَلَبِيَّةٌ-طَلَبِيَّةٌ [ط ل ب]. ""تَقَدَّمَ بِطَلَبِيَّتِهِ لِلتَّاجِرِ"" : مَا يَطْلُبُهُ الزَّبُونُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11792, 'مُتَطَلَّبَاتٌ', 'متطلبات', 'جامد', 'طلب', 'متطلبات', 'متطلبت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُتَطَلَّبَاتٌ-مُتَطَلَّبَاتٌ [ط ل ب]. ""مُتَطَلَّبَاتُ الْحَيَاةِ"" : مُقْتَضَيَاتُهَا وَحَاجِيَاتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11793, 'مَطَالِبُ', 'مطالب', 'جامد', 'طلب', 'مطالب', 'مطلب', '', '', '', 'مفرد', '', '', '', '"مفردمَطْلَب"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""مَطَالِبُ العُمَّالِ"" : ما يُطَالِبُونَ بِهِ لانْتِزَاعِ حَقٍّ مِنْ حُقُوقِهِمْ. ""حُقُوقُ الإِنْسَانِ مَطْلَبٌ مِنْ مَطَالِبِ العَصْرِ"" ""وَمَا نَيْلُ الْمَطَالِبِ بِالتَّمَنِّي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11794, 'مَطْلَبٌ', 'مطلب', 'جامد', 'طلب', 'مطلب', 'مطلب', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَالِبُ"', '', 'R', '', '', '', '', '', '', '". ""لَهُ مَطْلَبٌ وَحِيدٌ فِي الْحَيَاةِ"" : مَسْعًى وَحِيدٌ. (ن. مَطَالِبُ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11795, 'مَطَالِبُ', 'مطالب', 'جامد', '', 'مطالب', 'مطلب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11796, 'طَلْحٌ', 'طلح', 'جامد', 'طلح', 'طلح', 'طلح', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"طَلْحٌ-طَلْحٌ، ةٌ [ط ل ح]. 1.: شَجَرٌ شَائِكٌ ضَخْمٌ مِنْ شَجَرِ العِضَاهِ تَرْعَاهُ الإِبِلُ. 2.الواقعةآية 29 وَطَلْحٍ مَنْضُودٍ (قرآن) : مَوْزٌ. 3.""حَيَوَانٌ طَلْحٌ"" : بَطْنُهُ خَالٍ مِنَ الطَّعَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11797, 'طَلاَّسَةٌ', 'طلاسة', 'جامد', 'طلس', 'طلاسة', 'طلسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""طَلاَّسَةُ السَّبُّورَةِ"" : الْمِمْحَاةُ مِنْ خِرْقَةٍ وَنَحْوِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11798, 'مَطْلِعٌ', 'مطلع', 'جامد', 'طلع', 'مطلع', 'مطلع', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَالِعُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""مَطْلِعُ الشَّمْسِ"" : مَكَانُ طُلُوعِهَا. الكهف آية 90 حَتَّى إِذَا بَلَغَ مَطْلِعَ الشَّمْسِ (قرآن) ""لِلشَّمْسِ مَطَالِعُ وَمَغَارِبُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11799, 'مَطَالِعُ', 'مطالع', 'جامد', '', 'مطالع', 'مطلع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11800, 'طِلْسَمٌ', 'طلسم', 'جامد', 'طلسم', 'طلسم', 'طلسم', '', '', '', 'مفرد', 'DnN', '', '', '"طَلاَسِمُ"', '', 'R', '', '', '', '', '', '', '". 1.""خَطَّ طَلاَسِمَ"" : مَا يَخُطُّهُ السَّاحِرُ مِنْ خُطُوطٍ بِهَا أَلْغَازٌ غَامِضَةٌ وَمُبْهَمَةٌ، يَدَّعِي أَنَّهَا تَرُدُّ الأَذَى وَتُسَاعِدُ عَلَى قَضَاءِ الْحَاجَاتِ. 2. ""فَكَّ طِلْسَمَهُ أَوْ طَلاَسِمَهُ"" : وَضَّحَهُ، فَسَّرَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11801, 'طَلاَسِمُ', 'طلاسم', 'جامد', '', 'طلاسم', 'طلسم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11802, 'طِلاَعٌ', 'طلاع', 'جامد', 'طلع', 'طلاع', 'طلع', '', '', '', 'مفرد', 'DnN', '', '', '"طُلُعٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""سَهْلٌ طِلاَعٌ"" : طَلَعَتْ عَلَيْهِ الشَّمْسُ. 2.""طِلاَعُ الشَّيْءِ"" : مِلْؤُهُ. 3.""إِنَاءٌ طِلاَعٌ"" : مَلْآنُ. 4.""عَيْنٌ طِلاَعٌ"" : مَلْأى مِنَ الدَّمْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11803, 'طُلُعٌ', 'طلع', 'جامد', '', 'طلع', 'طلع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11804, 'طَلاَئِعُ', 'طلائع', 'جامد', 'طلع', 'طلاءع', 'طلع', '', '', '', 'مفرد', '', '', '', '"مفردطَلِيعَة"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '". 1.""طَلاَئِعُ الْجَيْشِ"" : الفِرَقُ الأُولَى الَّتِي تَكُونُ فِي الْمُقَدِّمَةِ. 2.""طَلاَئِعُ الرَّبِيعِ"" : أَوَائِلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11805, 'طَلْعٌ', 'طلع', 'جامد', 'طلع', 'طلع', 'طلع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"طَلْعٌ-طَلْعٌ [ ط ل ع ]. 1.""طَلْعُ النَّخْلِ"" : مَادَّةُ إِخْصَابِهِ تُجْمَعُ فِي غِلاَفٍ يُشْبِهُ الكُوزَ يَنْفَتِحُ عَنْ حَبٍّ مَنْضُودٍ. 2. ""طَلْعُ الْمَسَافَةِ"" : مِقْدَارُهَا. 3.""نَادَاهُ مِنْ طَلْعٍ"" : مِنْ مَكَانٍ عَالٍ يُطَّلَعُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11806, 'طَلِيعَةٌ', 'طليعة', 'جامد', 'طلع', 'طليعة', 'طلعة', '', '', '', 'مفرد', 'DnN', '', '', '"طَلاَئِعُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""طَلِيعَةُ الْجَيْشِ"" : مُقَدِّمَتُهُ. 2.""هُوَ فِي الطَّلِيعَةِ"" : فِي الوَاجِهَةِ، فِي الْمَقَامِ الأَوَّلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11807, 'طَلاَئِعُ', 'طلائع', 'جامد', '', 'طلاءع', 'طلع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
