INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11809, 'طُلَلٌ', 'طلل', 'جامد', '', 'طلل', 'طل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11810, 'طَلَلٌ', 'طلل', 'جامد', 'طلل', 'طلل', 'طل', '', '', '', 'مفرد', 'DnN', '', '', '"أَطْلاَلٌ:طُلُولٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَقَفَ يَتَأَمَلُّ أَطْلاَلَ بَقَايَا القَصْرِ"" : الآثَار البَاقِيَة. 2.""جَذَبَهَا إِلَيْهِ طَلَلُهُ"" : شَخْصُهُ. 3.""مَشَى عَلَى طَلَلِ الْمَاءِ"" : عَلَى سَطْحِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11811, 'أَطْلاَلٌ', 'أطلال', 'جامد', '', 'ءطلال', 'طلل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
