INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11813, 'طُلْمَةٌ', 'طلمة', 'جامد', 'طلم', 'طلمة', 'طلمة', '', '', '', 'مفرد', 'DnN', '', '', '"طُلَمٌ"', '', 'R', '', '', '', '', '', '', '". 1.""نَاوَلَهُ طُلْمَةً"" : خُبْزَةً. 2.: حَجَرٌ عَرِيضٌ يُنْصَبُ كَالطَّابَقِ وَيُخْبَزُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11814, 'طُلَمٌ', 'طلم', 'جامد', '', 'طلم', 'طلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11815, 'طَلَمٌ', 'طلم', 'جامد', 'طلم', 'طلم', 'طلم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَلَمٌ-طَلَمٌ [ط ل م]. ""طَلَمُ الأَسْنَانِ"" : وَسَخُهَا النَّاتِجُ عَنْ إِهْمَالِ تَنْظِيفِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11816, 'طُلْمٌ', 'طلم', 'جامد', 'طلم', 'طلم', 'طلم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"طُلْمٌ-طُلْمٌ [ط ل م]. ""طُلْمُ الْخُبْزِ"" : خِوَانٌ يُبْسَطُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11817, 'طَلاَوَةٌ', 'طلاوة', 'جامد', 'طلو', 'طلاوة', 'طلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '". 1.""تَشُدُّنِي طَلاَوَةُ حَدِيثِهِ"" : عُذُوبَتُهُ، فَصَاحَتُهُ. ""فِي حَدِيثِهِ طَلاَوَةٌ"". 2.""طَلاَوَةُ اللَّبَنِ أَوِ الْحَلِيبِ"" : الْجِلْدَةُ الرَّقِيقَةُ الَّتِي تَعْلُو اللَّبَنَ أَوِ الْحَلِيبَ. 3.""فِي فَمِهِ طَلاَوَةٌ "" : بَقِيَّةُ الطَّعَامِ. 4.""أَذْهَلَهُ بِطَلاَوَتِهِ"" : بِسِحْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11818, 'طُلاَوَةٌ', 'طلاوة', 'جامد', 'طلو', 'طلاوة', 'طلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"طُلاَوَةٌ-طُلاَوَةٌ [ط ل و]. 1.""طُلاَوَةٌ مِنْ مَادَّةِ كَذَا"" : كُلُّ مَا يُطْلَى بِهِ. 2.""طُلاَوَةُ مَاءٍ"" : طُحْلُبُهُ. 3.""طُلاَوَةُ كَلإٍ"" : قَلِيلٌ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11819, 'طِلًى', 'طلى', 'جامد', 'طلي', 'طلى', 'طل', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"طِلىً-طِلىً [ط ل ي]. ""قَضَى طِلاَهُ"" : لَذَّتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11820, 'طَمَاطِمُ', 'طماطم', 'جامد', '', 'طماطم', 'طمطم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"1. : بَقْلٌ مِنْ فَصِيلَةِ البَاذِنْجَانِيَّاتِ، مُدَوَّرٌ، يَظْهَرُ أَخْضَرَ اللَّوْنِ وَيَحْمَّرُ مَعَ نُضْجِهِ. 2. : ثَمَرُ بَقْلِ الطَّمَاطِمِ يُؤْكَلُ نَيِّئاً أَوْ مَطْبُوخاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11821, 'اِنْطِلاقَةٌ', 'انطلاقة', 'جامد', 'طلق', 'انطلاقة', 'نطلقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"اِنْطِلاقَةٌ-اِنْطِلاقَةٌ [ط ل ق]. ""اِنْطِلاقَةٌ جَديدَةٌ لِنَشاطِ الجَمْعِيَّةِ"": دَفْعَةٌ جَديدَةٌ فيها حَماسٌ وَحَمِيَّةٌ. ""اِنْطِلاقَةٌ ثَوْرِيَّةٌ"" ""اِنْطِلاقَةٌ فَنِّيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11822, 'مَطْمَحٌ', 'مطمح', 'جامد', 'طمح', 'مطمح', 'مطمح', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَامِحُ"', '', 'R', '', '', '', '', '', '', '". 1.""بَعِيدُ الْمَطْمَحِ"" : مَا يُطْمَحُ إِلَيْهِ، مَا يُرْغَبُ فِيهِ. 2.""مَطْمَحُ الأَنْظَارِ"" : مَا يَجْذِبُ إِلَيْهِ الأَنْظَارَ، مَرْكَزُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11823, 'مَطَامِحُ', 'مطامح', 'جامد', '', 'مطامح', 'مطمح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11824, 'طِمْرٌ', 'طمر', 'جامد', 'طمر', 'طمر', 'طمر', '', '', '', 'مفرد', 'DnN', '', '', '"أَطْمَارٌ"', '', 'R', '', '', '', '', '', '', '". 1.""يَرْتَدِي طِمْراً"" : ثَوْباً بَالِياً. 2.""رَجُلٌ طِمْرٌ"" : فَقِيرٌ، مُعْدِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11825, 'أَطْمَارٌ', 'أطمار', 'جامد', '', 'ءطمار', 'طمر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11826, 'مِطْمَارٌ', 'مطمار', 'جامد', 'طمر', 'مطمار', 'مطمر', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَامِيرُ"', '', 'R', '', '', '', '', '', '', '". ""مِطْمَارُ الْمُهَنْدِسِ"" : خَيْطُ القِيَاسَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11827, 'مَطَامِيرُ', 'مطامير', 'جامد', '', 'مطامير', 'مطمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11828, 'مِطْمَرٌ', 'مطمر', 'جامد', 'طمر', 'مطمر', 'مطمر', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَامِرُ"', '', 'R', '', '', '', '', '', '', '".: خَيْطُ البَنَّاءِ أَوِ الْمُهَنْدِسِ الْمِعْمَارِيِّ، يَسْتَعْمِلُهُ لِقِيَاسِ الْمَسَافَاتِ. ن. مِطْمَارٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11829, 'مَطَامِرُ', 'مطامر', 'جامد', '', 'مطامر', 'مطمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11830, 'مَطْمَعٌ', 'مطمع', 'جامد', 'طمع', 'مطمع', 'مطمع', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَامِعُ"', '', 'R', '', '', '', '', '', '', '". : ما يُطْمَعُ فيهِ، ما يُرْغَبُ فيهِ. ""لاَ مَطْمَعَ لَهُ فِيمَا لَيْسَ فِي مِلْكِهِ"" : لاَ يَطْمَعُ فِيهِ، لاَ رَغْبَةَ لَهُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11831, 'مَطَامِعُ', 'مطامع', 'جامد', '', 'مطامع', 'مطمع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11832, 'طَامَّةٌ', 'طامة', 'جامد', 'طمم', 'طامة', 'طمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"طَامَّةٌ-طَامَّةٌ [ط م م]. 1.""إِنَّهَا الطَّامَّةُ الكُبْرَى"" : الكَارِثَةُ الكُبْرَى، الْمُصِيبَةُ، الدَّاهِيَةُ. ""مَا مِنْ طَامَّةٍ إِلاَّ وَفَوْقَهَا طَامَّةٌ"". 2.النازعات آية 34 ، 35 فَإِذَا جَاءتِ الطَّامَّةُ الكُبْرَى يَوْمَ يَتَذَكَّرُ الإِنْسَانُ مَا سَعَى (قرآن): يَوْمُ القِيَامَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11833, 'طِمٌّ', 'طم', 'جامد', 'طمم', 'طم', 'طم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طِمٌّ-طِمٌّ [ط م م]. 1.""تَدَفَّقَ طِمٌّ لاَ عَهْدَ لَنَا بِهِ"" : مَاءٌ كَثِيرٌ. 2.""نَزَحَ طِمٌّ مِنَ الْمُهَاجِرِينَ"" : عَدَدٌ كَبِيرٌ مِنْهُمُ. 3.""أَتَى بِطِمٍّ"": بِعَجَبٍ عَجِيبٍ. 4.""جَاءَ رَاكِباً عَلَى طِمٍّ"" : فَرَسٍ، جَوَادٍ. 5.""جَاءهُمُ الطِّمُّ وَالرِّمُّ"" : أَتَاهُمُ الشَّيْءُ الكَثِيرُ وَالقَلِيلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11834, 'طُنٌّ', 'طن', 'جامد', '', 'طن', 'طن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَطْنَانٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَطْنَانٌ. 1. ""طُنُّ الإِنْسَانِ"" : بَدَنُهُ أَوْ قَامَتُهُ. 2.""تَسَعُ الشَّاحِنَةُ طُنّاً مِنَ الْخَشَبِ"" : وَحْدَةُ وَزْنٍ مِقْدَارُهَا أَلْفُ كِيُلو غرام."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11835, 'أَطْنَانٌ', 'أطنان', 'جامد', '', 'ءطنان', 'طنن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11836, 'طُنُبٌ', 'طنب', 'جامد', 'طنب', 'طنب', 'طنب', '', '', '', 'مفرد', 'DnN', '', '', '"أَطْنَابٌ"', '', 'R', '', '', '', '', '', '', '". 1.""شَدَّ أَطْنَابَ الْخَيْمَةِ"" : الْحِبَالَ الَّتِي تَشُدُّهَا. 2.""ضَرَبَ الفَسَادُ أَطْنَابَهُ"" : اِنْتِشارُهُ على نِطاقٍ واسِعٍ. ""يَضْرِبُ الدَّاءُ الْجَدِيدُ أَطْنَابَهُ فِي العَالَمِ"". 3.""شَدَّ أَطْنَابَهُ"" : خَيَّمَ، أَقَامَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11837, 'أَطْنَابٌ', 'أطناب', 'جامد', '', 'ءطناب', 'طنب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11838, 'مَطْنَبٌ', 'مطنب', 'جامد', 'طنب', 'مطنب', 'مطنب', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَانِبُ"', '', 'R', '', '', '', '', '', '', '". ""مَطْنَبُ الرَّجُلِ"" : مَنْكِبُهُ، أَيْ مُجْتَمَعُ الكَتِفِ وَالعَضُدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11839, 'مَطَانِبُ', 'مطانب', 'جامد', '', 'مطانب', 'مطنب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11840, 'طُنْبُورٌ', 'طنبور', 'جامد', '', 'طنبور', 'طنبر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"طَنَابِيرُ"', '', 'R', '', '', '', '', '', '', '"ج: طَنَابِيرُ. : آلَةٌ مُوسِيقِيَّةٌ مِنْ ذَوَاتِ الأَوْتَارِ، لَهَا عُنُقٌ طَويلٌ يَتَّصِلُ بِصُنْدُوقٍ شَبيهٍ بِالبَيْضَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11841, 'طَنَابِيرُ', 'طنابير', 'جامد', '', 'طنابير', 'طنبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11842, 'طَنْجَرَةٌ', 'طنجرة', 'جامد', '', 'طنجرة', 'طنجرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ج: طَنْجَرَاتٌ. ""غَلَى الطَّعَامُ فِي الطَّنْجَرَةِ"" : قِدْرٌ مِنْ نُحَاسٍ أَوْ مَعْدِنٍ آخَرَ يُطْبَخُ فِيهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11843, 'طِنْجِيرٌ', 'طنجير', 'جامد', '', 'طنجير', 'طنجر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"طَنَاجِيرُ"', '', 'R', '', '', '', '', '', '', '"ج: طَنَاجِيرُ. : وِعَاءٌ يُعْمَلُ فِيهِ الْخَبِيصُ وَنَحْوُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11844, 'طَنَاجِيرُ', 'طناجير', 'جامد', '', 'طناجير', 'طنجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11845, 'طُنْفٌ', 'طنف', 'جامد', '', 'طنف', 'طنف', '', '', '', 'جمع تكسير', 'DnN', '', '', '"طُنُوفٌ:أَطْنَافٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: طُنُوفٌ، أَطْنَافٌ. 1.""طُنْفُ بَابِ الدَّارِ"" : السَّقِيفَةُ تُشْرَعُ وَتُبْنَى فَوْقَ بَابِ الدَّارِ. ""وَقَفَ تَحْتَ طُنْفِ مَحَطَّةِ الْحَافِلاَتِ"" : سَقِيفَةٌ تُقَامُ بِمَحَطَّةِ الْحَافِلاَتِ للوِقَايَةِ مِنَ الْمَطَرِ أَوْ حَرَارَةِ الشَّمْسِ. 2.""طُنْفُ الْجَبَلِ"" : مَا نَتَأَ مِنْهُ وَظَهَرَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11846, 'طُنُوفٌ', 'طنوف', 'جامد', '', 'طنوف', 'طنف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11847, 'أَطْنَافٌ', 'أطناف', 'جامد', '', 'ءطناف', 'طنف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11848, 'طُنْفُسَةٌ', 'طنفسة', 'جامد', 'طنفس', 'طنفسة', 'طنفسة', '', '', '', 'مفرد', 'DnN', '', '', '"طَنافِسُ"', '', 'R', '', '', '', '', '', '', '". ""اِسْتَلْقَى عَلَى الطُّنْفُسَةِ"" : البِساط. ""يَعودُ لِيَجْلِسَ على الطُّنْفُسَةِ وَيَأْخُذُ رَأْسَهُ بِيَدَيْهِ وَيَبْكِي"". (أحمد التوفيق)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11849, 'طَنافِسُ', 'طنافس', 'جامد', '', 'طنافس', 'طنفس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11850, 'طَنَّانَةٌ', 'طنانة', 'جامد', 'طنن', 'طنانة', 'طننة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"طَنَّانَةٌ-طَنَّانَةٌ [ط ن ن] (حش). : حَشَرَةٌ مِنْ فَصِيلَةِ النَّحْلِيَّاتِ، كَثِيرَةُ الشَّعَرِ اللاَّمِعِ، تُحْدِثُ أَجْنِحَتُهَا طَنِيناً، خِلاَلَ الطَّيَرَانِ، تَخْتَلِفُ أَلْوَانُهَا بِاخْتِلافِ الأَصْنَافِ، تُفِيدُ فِي إِلْقَاحِ الزُّهُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11851, 'طِهَارَةٌ', 'طهارة', 'جامد', 'طهر', 'طهارة', 'طهرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"طِهَارَةٌ-طِهَارَةٌ [ط هـ ر]. : خِتانَةٌ، حِرْفَةُ مَنْ يُطَهِّرُ الصِّبْيَانَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11852, 'طُهْرَةٌ', 'طهرة', 'جامد', 'طهر', 'طهرة', 'طهرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"طُهْرَةٌ-طُهْرَةٌ [ط هـ ر]. 1.""طُهْرَةُ ثَوْبٍ"" : نَقَاؤُهُ. 2.""طُهْرَةُ الْجِسْمِ"" : اِغْتِسَالُهُ بِالْمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11853, 'مَطْهَرَةٌ', 'مطهرة', 'جامد', 'طهر', 'مطهرة', 'مطهرة', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَاهِرُ"', '', 'R', '', '', '', '', '', '', '". 1.: كُلُّ إِنَاءٍ يُتَطَهَّرُ بِهِ. 2.: كُلُّ بَيْتٍ يُتَطَهَّرُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11854, 'مَطَاهِرُ', 'مطاهر', 'جامد', '', 'مطاهر', 'مطهر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11855, 'مَطْهَرٌ', 'مطهر', 'جامد', 'طهر', 'مطهر', 'مطهر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَطْهَرٌ-مَطْهَرٌ [ط هـ ر].: الْمَكَانُ الَّذِي تُطَهَّرُ فِيهِ الأَنْفُسُ بَعْدَ الْمَوْتِ بِعَذَابٍ مَحْدُودٍ فِي اعْتِقَادِ الْمَسِيحِيِّينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11856, 'طُهَاوَةٌ', 'طهاوة', 'جامد', 'طهو', 'طهاوة', 'طهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"طُهَاوَةٌ-طُهَاوَةٌ [ط هـ و]. ""طُهَاوَةُ لَبَنٍ أَوْ دَمٍ"" : طَلاوَةٌ، جِلْدَةٌ رَقِيقَةٌ تَكُونُ فَوْقَهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11857, 'طِهَايَةٌ', 'طهاية', 'جامد', 'طهو', 'طهاية', 'طهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"طِهَايَةٌ-طِهَايَةٌ [ط هـ و]. : حِرْفَةُ الطَّاهِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11858, 'مِطْهَاةٌ', 'مطهاة', 'جامد', 'طهو', 'مطهاة', 'مطهة', '', '', '', 'مفرد', 'DnN', '', '', '"مَطاهٍ"', '', '', '', '', '', '', '', '', '". ""وَضَعَتِ اللَّحْمَ وَالخُضَرَ فِي المِطْهَاةِ"" : إِناءُ الطَّبْخِ مِنْ مَعْدِنٍ أَوْ نَحْوِهِ، لَهُ مِقْبَضٌ، تُغْلَّى فِيهِ السَّوَائِلُ أَوْ غَيْرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11859, 'مَطاهِي', 'مطاهي', 'جامد', '', 'مطاهي', 'مطه', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11860, 'طَهْيٌ', 'طهي', 'جامد', 'طهي', 'طهي', 'طه', '', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"طَهْيٌ-طَهْيٌ [ ط هـ ي ]. 1.""طَهْيُ الطَّعَامِ"" : طَبْخُهُ، إِنْضَاجُهُ، خَبْزُهُ. 2.""طَهْيُ الصَّيْفِ"" : الغَمَامُ الرَّقِيقُ. 3.""أَلَّمَهُ بِطَهْيِهِ"" : بِضَرْبِهِ ضَرْباً شَدِيداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11861, 'طَوَابِعُ', 'طوابع', 'جامد', '', 'طوابع', 'طبع', '', '', '', 'جمع تكسير', '', '', '', '"مفردطَابَع"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جمع طَابَع. ن. طَابَع."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11862, 'طَابَع', 'طابع', 'جامد', '', 'طابع', 'طبع', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11863, 'طُوبَةٌ', 'طوبة', 'جامد', 'طوب', 'طوبة', 'طبة', '', '', '', 'مفرد', 'DnN', '', '', '"واحدةالطُّوبِ"', '', 'R', '', '', '', '', '', '', '"طُوبَةٌ-طُوبَةٌ [ط و ب]. : وَاحِدَةُ الطُّوبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11864, 'طُوبٌ', 'طوب', 'جامد', 'طوب', 'طوب', 'طب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طُوبٌ-طُوبٌ [ط و ب]. ""بَنَى دَارَهُ بِالطُّوبِ الأَحْمَرِ"" : مَا يُشْبِهُ الأَجُرَّ الْمَشْوِيَّ مِنَ التُّرَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11865, 'طاَفَّةٌ', 'طافة', 'جامد', 'طوف', 'طافة', 'طفة', '', '', '', 'مفرد', 'DnN', '', '', '"طَوَافُّ"', '', 'R', '', '', '', '', '', '', '". ""طَافَّةُ البُسْتَانِ"" : مَا يُحِيطُ بِهِ مِنْ سُورٍ وَنَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11866, 'طَوَافُّ', 'طواف', 'جامد', '', 'طواف', 'طف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11867, 'مَطَاوِحُ', 'مطاوح', 'جامد', 'طوح', 'مطاوح', 'مطح', '', '', '', 'مفرد', '', '', '', '"مفردمَطَاح"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""لَقِيَ الْمَطَاوِحَ فِي حَيَاتِهِ"" : الْمَهَالِكَ، الْمَخَاطِرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11868, 'مَطَاح', 'مطاح', 'جامد', '', 'مطاح', 'مطح', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11869, 'مِطْوَاحٌ', 'مطواح', 'جامد', 'طوح', 'مطواح', 'مطح', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَاوِيحُ"', '', 'R', '', '', '', '', '', '', '". 1.""رَفَعَ مِطْوَاحَهُ مُهَدِّداً"" : عَصَاهُ. 2.""قَذَفَهُ مِطْوَاحاً"" : مَا يُرْمَى بِهِ فِي الْهَوَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11870, 'مَطَاوِيحُ', 'مطاويح', 'جامد', '', 'مطاويح', 'مطح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11871, 'طَوْدٌ', 'طود', 'جامد', 'طود', 'طود', 'طد', '', '', '', 'مفرد', 'DnN', '', '', '"أَطْوَادٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""اِنْتَصَبَ الطَّوْدُ شَامِخاً"" : الْجَبَلُ العَظِيمُ. الشعراء آية 63 فَانْفَلَقَ فَكَانَ كُلُّ فِرْقٍ كَالطَّوْدِ العَظِيمِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11872, 'أَطْوَادٌ', 'أطواد', 'جامد', '', 'ءطواد', 'طد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11873, 'طَوَارٌ', 'طوار', 'جامد', 'طور', 'طوار', 'طر', '', '', '', 'مفرد', 'DnN', '', '', '"أَطْوِرَةٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""طَوَارُ الدَّارِ"" : مَا كَانَ مُمْتَدّاً مَعَهَا مِنَ الفِنَاءِ"". 2.""طِوَارُ الشَّارِعِ"" : جَانِبُهُ، أَي الْمُرْتَفَعُ يَمْشِي فيهِ الْمُشَاةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11874, 'أَطْوِرَةٌ', 'أطورة', 'جامد', '', 'ءطورة', 'طرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11875, 'طَوْرٌ', 'طور', 'جامد', 'طور', 'طور', 'طر', '', '', '', 'مفرد', 'DnN', '', '', '"أَطْوَارٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِنْتَقَلَ مِنْ طَوْرٍ إِلَى طَوْرٍ"" : مِنْ مَرْحَلَةٍ إِلَى مَرْحَلَةٍ. ""طَوْراً بَعْدَ طَوْرٍ"". 2.""يَجْلِسُ طَوْراً وَيَقِفُ طَوْراً آخَرَ"" : تَارَةً وَتَارَةً. "" يَزُورُهُ طَوْراً بَعْدَ طَوْرٍ"". 3.""خَرَجَ عَنْ طَوْرِهِ"" : فَقَدَ رُشْدَهُ. 4.""فِي طَوْرِ النَّقَاهَةِ"" : فِي فَتْرَةِ النَّقَاهَةِ. 5.""جَاوَزَ طَوْرَهُ"" : حَدَّهُ، قَدْرَهُ. 6.""النَّاسُ أَطْوَارٌ"" : أَصْنَافٌ وَأَنْوَاعٌ وَحَالاَتٌ. ""هُوَ غَرِيبُ الأَطْوَارِ"". 7.""هَذَا طَوْرُهُ"" : حالُهُ، هَيْئَتُهُ. 8.نوح آية 14 وَقَدْ خَلَقَكُمْ أَطْوَاراً (قرآن) : طَوْراً عَلَقَةً وَطَوْراً مُضْغَةً، أي من شَكْلٍ إلى آخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11876, 'أَطْوَارٌ', 'أطوار', 'جامد', '', 'ءطوار', 'طر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11877, 'طُورٌ', 'طور', 'جامد', 'طور', 'طور', 'طر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طُورٌ-طُورٌ [ط و ر ]. 1.""صَعِدَ الطُّورَ"" : الْجَبَلَ. الطور آية 1 ، 2 وَالطُّورِ وَكِتَابٍ مَسْطُورٍ (قرآن) : الْجَبَلُ الَّذِي نَاجَى فِيهِ مُوسَى رَبَّهُ، سورَةٌ مِن سور القرآن. 2.""طورُ الدّارِ"" : ساحَتُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11878, 'طَاسٌ', 'طاس', 'جامد', 'طوس', 'طاس', 'طس', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""طَاسُ الغَسْلِ"" : إِنَاءٌ مِنْ نُحَاسٍ تُغْسَلُ فِيهِ اليَدانِ اسْتِعْدَاداً لِلأَكْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11879, 'طَاوُوسٌ', 'طاووس', 'جامد', 'طوس', 'طاووس', 'طس', '', '', '', 'مفرد', 'DnN', '', '', '"طَوَاوِيسُ"', '', 'R', '', '', '', '', '', '', '"(حو). : مِنْ فَصِيلَةِالتَّدْرُجِيَّاتِ، رُتْبَةُ الدَّجَاجِيَّاتِ، جَمِيلُ الشَّكْلِ، كَثِيرُ الأَلْوَانِ، طَوِيلُ العُنُقِ، صَغِيرُ الرَّأْسِ، عَرِيضُ الذَّنَبِ، حَادُّ الصَّوْتِ، أَصْلُهُ مِنَ الْهِنْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11880, 'طَوَاوِيسُ', 'طواويس', 'جامد', '', 'طواويس', 'طس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11881, 'طَوَاعِيَةٌ', 'طواعية', 'جامد', 'طوع', 'طواعية', 'طعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"طَوَاعِيَةٌ-طَوَاعِيَةٌ [ط و ع]. 1.""اِسْتَجَابَ عَنْ طَوَاعِيَةٍ"" : عَنِ اخْتِيَارٍ، عَنْ طَاعَةٍ. 2.""طَوَاعِيَةُ جِسْمٍ"" : لُيُونَتُهُ، طَرَاوَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11882, 'طَوْعِيٌّ', 'طوعي', 'جامد', 'طوع', 'طوعي', 'طع', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"طَوْعِيٌّ-طَوْعِيٌّ [ط و ع]. ""اِسْتَجَابَ طَوْعِيّاً"" : اِخْتِيَارِيّاً، عَنْ رِضًى، بِلا قَهْرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11883, 'طُوفَانٌ', 'طوفان', 'جامد', 'طوف', 'طوفان', 'طفن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طُوفَانٌ-طُوفَانٌ [ط و ف]. ""غَمَرَ الطُّوفَانُ كُلَّ البِقَاعِ"" : الفَيَضَانُ العَظِيمُ.العنكبوت آية 14فَأَخَذَهُمُ الطُّوفَانُ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11884, 'طَوْفٌ', 'طوف', 'جامد', 'طوف', 'طوف', 'طف', '', '', '', 'مفرد', 'DnN', '', '', '"أَطْوَافٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَقَامَ طَوْفاً حَوْلَ ضَيْعَتِهِ"" : جِدَاراً أَوْ حَاجِزاً يُقَامُ حَوْلَ قِطْعَةٍ مِنَ الأرْضِ. 2.""أَطْوَافُ السُّوقِ"" : حُرَّاسُ الل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11885, 'أَطْوَافٌ', 'أطواف', 'جامد', '', 'ءطواف', 'طف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11886, 'مَطَافٌ', 'مطاف', 'جامد', 'طوف', 'مطاف', 'مطف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَطَافٌ-مَطَافٌ [ط و ف]. 1.""مَطَافُ الْحَاجِّ"" : مَوْضِعُ الطَّوَافِ، الكَعْبَةُ. 2.""اِنْتَهَى بِهِ الْمَطَافُ إِلَى الاسْتِسْلاَمِ"" : اِنْتَهَى بِهِ الدَّوَرَانُ. 3.""خَاتِمَةُ الْمَطَافِ"" : الْمَآلُ، النِّهَايَةُ. ""فِي نِهَايَةِ الْمَطَافِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11887, 'طُوَّالٌ', 'طوال', 'جامد', 'طول', 'طوال', 'طل', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"طُوَّالٌ-طُوَّالٌ [ط و ل] (حو). 1.: طَائِرٌ مَائِيٌّ، ذُو سَاقَيْنِ طَوِيلَتَيْنِ، وَمِنْقَارٍ طَوِيلٍ أَسْوَدَ، مُسْتَطِيلِ الشَّكْلِ، يَعِيشُ عَلَى صَيْدِ السَّمَكِ. 2.""رَجُلٌ طُوَّالٌ"" : طَويلٌ جِدّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11888, 'طَاقٌ', 'طاق', 'جامد', 'طوق', 'طاق', 'طق', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَطْوَاقٌ:طِيقَانٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.: مَا جُعِلَ وَعُطِفَ مِنَ البِنَاءِ مِنْ قَنْطَرَةٍ أَوْ ناَفِذَةٍ كَالقَوْسِ. 2.""طَاقُ نَعْلٍ"" : فِرَاشُهُ. 3.""طَاقُ جَبَلٍ"" : نُتُوؤُهُ، بُرُوزُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11889, 'أَطْوَاقٌ', 'أطواق', 'جامد', '', 'ءطواق', 'طق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
