INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11891, 'طَوْقٌ', 'طوق', 'جامد', 'طوق', 'طوق', 'طق', '', '', '', 'مفرد', 'DnN', '', '', '"أَطْوَاقٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هَذَا العَمَلُ طَوْقُ طَاقَتِهِ"" : عَلَى قَدْرِ طاقَتِهِ. 2.""أَلْبَسُوا العَرُوسَ طَوْقاً جَمِيلاً"" : إِكْلِيلاً مِنَ الذَّهَبِ. "" أَأَنْسَى أَيَادِيكَ وَهِيَ طَوْقُ رَقَبَتِي "". (التوحيدي). 3.""شَبَّ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11892, 'أَطْوَاقٌ', 'أطواق', 'جامد', '', 'ءطواق', 'طق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11893, 'طَاوِلَةٌ', 'طاولة', 'جامد', 'طول', 'طاولة', 'طلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""جَلَسَ وَرَاءَ الطَّاوِلَةِ"": مَائِدَةٌ مِنْ خَشَبٍ وَنَحْوِهِ. ""طَاوِلَةُ الأَكْلِ"". 2.""لُعْبَةُ الطَّاوِلَةِ"" : لُعْبَةُ النَّرْدِ. 3.""جَلَسُوا حَوْلَ طاَوِلَةِ الْمُفَاوَضَاتِ"" : مَائِدَةٌ يَتَفَاوَضُ حَوْلَهَا الْمُتَفَاوِضُونَ وَجْهاً لِوَجْهٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11894, 'طَوِيَّةٌ', 'طوية', 'جامد', 'طوي', 'طوية', 'طة', '', '', '', 'مفرد', 'DnN', '', '', '"طَوَايا"', '', '', '', '', '', '', '', '', '". 1."" عَبَّرَ عَنْ طَوِيَّتِهِ"" : عَنْ نِيَّتِهِ، عَنْ ضَمِيرِهِ. 2.""إِنْسَانٌ حَسَنُ الطَّوِيَّةِ"" : حَسَنُ النِّيَّةِ وَالضَّم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11895, 'طَوَايا', 'طوايا', 'جامد', '', 'طوايا', 'ط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11896, 'طَيَّةٌ', 'طية', 'جامد', 'طوي', 'طية', 'طة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', 'N', 'O', 'O', 'O', '', '". ""وَجَدْتُهُ بِطَيَّةِ الْهِضَابِ"" : بِنَوَاحِيهَا وَجِهَاتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11897, 'طَيٌّ', 'طي', 'جامد', 'طوي', 'طي', 'ط', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"طَيٌّ-طَيٌّ [ط و ي]. 1.""فِي طَيِّ الكِتَابِ"" : فِي دُرْجِهِ، فِي دَاخِلِهِ. ""سَتَجِدُ طَيَّهُ رِسَالَةً لأَهْلِي"" "" فِي طَيِّهِ"". 2.""صَارَتْ أَخْبَارُهُ فِي طَيِّ النِّسْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11898, 'مَطَاوِي', 'مطاوي', 'جامد', 'طوي', 'مطاوي', 'مط', '', 'Tk', '', 'مفرد', '', '', '', '"مفردمِطْوَاة"', '', '', '', 'N', 'O', 'O', 'O', '', '". 1.""مَطَاوِي الأَمْعَاءِ"" : ثَنَايَاهَا، بَاطِنُهَا. 2.""مَطَاوِي الْحَيَّةِ"" : اِلْتِفَاف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11899, 'مِطْوَاةٌ', 'مطواة', 'جامد', 'طوي', 'مطواة', 'مطة', '', '', '', 'مفرد', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '"مِطْوَاةٌ-مِطْوَاةٌ [ط و ي]. : سِكِّينٌ صَغِيرَةٌ ذَاتُ شَفْرَةٍ أَوْ أَكْثَرَ تُطْوَى فِينِصَابِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11900, 'طَوْلٌ', 'طول', 'جامد', 'طول', 'طول', 'طل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَوْلٌ-طَوْلٌ [ط و ل]. ""كَانَ صَاحِبَ الْحَوْلِ وَالطَّوْلِ"" : صَاحِبَ فَضْلٍ وَغِنىً وَيُسْرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11901, 'مَطْيَبَةٌ', 'مطيبة', 'جامد', 'طيب', 'مطيبة', 'مطبة', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَايِبُ"', '', 'R', '', '', '', '', '', '', '". 1.""اِسْتَقَرَّ فِي الْمَطْيَبَةِ"": مَكَانُ الطِّيبِ. 2.""شَرَابٌ مَطْيَبَةٌ لِلنَّفْسِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11902, 'مَطَايِبُ', 'مطايب', 'جامد', '', 'مطايب', 'مطب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11903, 'طَائِرَةٌ', 'طائرة', 'جامد', 'طير', 'طاءرة', 'طرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". 1.""حَطَّتِ الطَّائِرَةُ بِالْمَطَارِ"": مَرْكَبَةٌجَوِّيَّةٌ ذَاتُ أَجْنِحَةٍ يَقُودُهَا رُبَّانٌ، تُسْتَخْدَمُ لأَغْرَاضٍ شَتَّى : أ.""طَائِرَةٌ مَدَنِيَّةٌ"" : خَاصَّةٌ بِنَقْلِ الْمُسَافِرِينَ بَيْنَ الأَقْطَارِ وَالْمُدُنِ البَعِيدَةِ. ب.""طَائِرَةٌ عَسْكَرِيَّـةٌ"" : تُسْتَخْـدَمُ لأَهْدَافٍ عَسْكَرِيَّةٍ وَهِيَ أَنْوَاعٌ: أ.""طَائِرَةٌ مُقَاتِلَةٌ"" : مُجَهَّزَةٌ لأَغْرَاضِ القِتَالِ. ب.""طَائِرَةٌ قَاذِفَةٌ لِلْقَنَابِلِ"" : تَرْمِـي العَـدُوَّ بِالقَنَابِـلِ. ج.""حَامِلَةُ الطَّائِرَاتِ"" : سَفِينَةٌ حَرْبِيَّةٌ ضَخْمَةٌ تَحُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11904, 'طَائِرٌ', 'طائر', 'جامد', 'طير', 'طاءر', 'طر', '', '', '', 'مفرد', 'DnN', '', '', '"طَيْرٌ:طُيُورٌ"', '', '', '', '', '', '', '', '', '". 1.""طَائِرٌ عَلَى الشَّجَرَةِ"" : كُلُّحَيَوَانٍ ذِي جَنَاحَيْنِ وَهُوَ أَنْوَاعٌ وَأَشْكَالٌ. أ.كُلُّ طائِرٍ يَطِيرُ فِي الهَواءِ. ب.""طُيُورٌ دَاجِنَةٌ"" : أَلِيفَةٌ، أي دَجَاجٌ، إِوَزٌّ، حَمَامٌ... ج. ""طُيُورٌ جَارِحَةٌ"" : مُفْتَرِسَةٌ، أي عُقَابٌ، بَازٌ. 2.""سِرْ عَلَى الطَّائِرِ الْمَيْمُونِ"" : دُعَاء"', '');
