INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11908, 'طَيْلَسَانٌ', 'طيلسان', 'جامد', '', 'طيلسان', 'طلسن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"طَيَالِسُ:طَيَالِسَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: طَيَالِسُ، طَيَالِسَةٌ. ""اِلْتَفَّ الشَّيْخُ فِي طَيْلسَانِهِ"" : كِسَاءٌ أَخْضَرُ، يَرْتَدِيهِ العُلَمَاءُ وَالْمَشَايِخُ."', ':لا جذر:لا مفرد');
