INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11911, 'طَيْرَةٌ', 'طيرة', 'جامد', 'طير', 'طيرة', 'طرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"طَيْرَةٌ-طَيْرَةٌ [ط ي ر]. 1.""عُرِفَ بِطَيْرَتِهِ"" : بِخِفَّتِهِ، بِطَيْشِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11912, 'طِيَرَةٌ', 'طيرة', 'جامد', 'طير', 'طيرة', 'طرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"طِيَرَةٌ-طِيَرَةٌ، طِيرَةٌ [ط ي ر]. : مَا يُتَشَاءمُ مِنْهُ أَوْ يُتَفَاءلُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11913, 'مَطَارٌ', 'مطار', 'جامد', 'طير', 'مطار', 'مطر', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". ""حَطَّتِ الطَّائِرَةُ بِالْمَطَارِ"": بِنَاءٌ في أَرْضٍ خَارِجَ الْمَدِينَةِ مُجَهَّزٌ بِتَجْهِيزَاتٍ مُرَتَّبَةٍ (أَبْرَاجُ الْمُرَاقَبَةِ وغَيْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11914, 'طِيَافٌ', 'طياف', 'جامد', 'طيف', 'طياف', 'طف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"طِيَافٌ-طِيَافٌ [ط ي ف]. ""طِيَافُ اللَّيْلِ"" : سَوَادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11915, 'طِينَةٌ', 'طينة', 'جامد', 'طين', 'طينة', 'طنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"طِينَةٌ-طِينَةٌ [ط ي ن]. 1.""طَلَى الشُّقُوقَ بِطِينَةٍ"" : بِقِطْعَةٍ مِنَ الطِّينِ. 2.""هُوَ مِنْ طِينَةٍ حَسَنَةٍ"" : حَسَنُ الْجِبِلَّةِ. ""طِينَةٌ طَيِّبَةٌ"". 3.""اِبْنٌ لَيْسَ مِنْ طِينَةِ أَبِيهِ"" : لاَ يُشْبِهُهُ فِي سُلُوكِهِ، لَيْسَ مِنْ مَعْدِنِهِ. 4.""هُمَا مِنْ طِينَةٍ وَاحِدَةٍ"" : عَلَى شَاكِلَةٍ وَاحِدَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11916, 'طِينٌ', 'طين', 'جامد', 'طين', 'طين', 'طن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طِينٌ-طِينٌ [ط ي ن]. 1.""بُنِيَتْ مَنَازِلُ القَرْيَةِ بِالطِّينِ"" : تُرَابٌ يُجَلَّلُ بِالْمَاءِ وَيُبْنَى بِهِ، كَمَا يُطْلَى بِهِ، الوَحْلُ.الأنعام آية 2 هُوَ الَّذِي خَلَقَكُمْ مِنْ طِينٍ (قرآن). 2.""زَادَ الطِّينَ بَلَّةً"" : زَادَ الأَمْرَ تَعْقِيداً وَسُوءاً. ""زَادَ فِي الطِّينِ بَلَّةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11917, 'ظَبْأَةٌ', 'ظبأة', 'جامد', 'ظبأ', 'ظبءة', 'ظبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'Rz', '', 'N', 'O', 'O', 'O', '', '"ظَبْأَةٌ-ظَبْأَةٌ [ظ ب أ]. (حو). : ضَبُعٌ عَرْجَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11918, 'ظَبْيٌ', 'ظبي', 'جامد', 'ظبي', 'ظبي', 'ظب', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"ظِباءٌ:ظَبْياتٌ"', '', '', '', 'N', 'O', 'O', 'O', '', '". (حو). : مِنْفَصيلَةِ البَقَرِيَّاتِ، مِنْ رُتْبَةِ شَفْعِيَّةِ الأَظْلافِ ومُجَوَّفاتِ القُرونِ، قَصيرُ الذَّنَبِ، رَشيقُ الجِسْمِ، سَريعُ الجَرْيِ، وَهُوَ ما يُعْرَفُ بِالغَزالِ. ""يُقـالُ لَيْسَ في الحَيَوانِ أَبْصَرُ مِنَ الظِّباءِ، وَيُقالُ لَها النَّظَّارَةُ"". (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11919, 'ظِباءٌ', 'ظباء', 'جامد', '', 'ظباء', 'ظب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11920, 'ظَبْياتٌ', 'ظبيات', 'جامد', '', 'ظبيات', 'ظبت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11921, 'ظَرِبٌ', 'ظرب', 'جامد', 'ظرب', 'ظرب', 'ظرب', '', '', '', 'مفرد', 'DnN', '', '', '"ظِرابٌ"', '', 'R', '', '', '', '', '', '', '". 1. : ما نَشَأَ مِنَ الحِجارَةِ وَحُدِّدَ طَرَفُهُ. 2.: الجَبَلُ الْمُنْبَسِطُ. اللَّهُمَّ على الآكامِ والظِّرابِ وَبُطونِ الأَوْدِيَةِ (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11922, 'ظِرابٌ', 'ظراب', 'جامد', '', 'ظراب', 'ظرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11923, 'ظَرِبانٌ', 'ظربان', 'جامد', '', 'ظربان', 'ظربن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"ظَرابينُ:ظَرابِيٌّ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: ظَرابينُ، ظَرابِيٌّ. (حو).: مِنْ فَصيلَةِ السَّمُّورِيَّاتِ. مِنْ رُتْبَةِ القَوارِضِ، فيجِلْدِهِ أَشْواكٌ قَصَبِيَّةٌ قابِلَةٌ لِلاسْتِقامَةِ، يَسْتَخْدِمُها لِلدِّفاعِ عَنْ نَفْسِهِ، قَصيرُ القَوائِمِ، كَريهُ الرَّائِحَةِ، أَبْيَضُ البَطْنِ، وَهُوَ في حَجْمِ القِطِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11924, 'ظَرابينُ', 'ظرابين', 'جامد', '', 'ظرابين', 'ظربن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11925, 'ظِرٌّ', 'ظر', 'جامد', 'ظرر', 'ظر', 'ظر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"ظِرَّانٌ:ظُرَّانٌ:ظِرارٌ"', '', 'R', '', '', '', '', '', '', '". 1.: حَجَرٌ حادٌّ كَحَدِّ السِّكِّينَ. 2.: قِطَعٌ من الصِّوَّانِ كانَتْ تُسْتَعْمَلُ قَديماً أَدَواتٍ حَرْبِيَّةً : حِرابٌ ونِصالٌ وفُؤُوسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11926, 'ظِرَّانٌ', 'ظران', 'جامد', '', 'ظران', 'ظرن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
