INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11928, 'ظِرارٌ', 'ظرار', 'جامد', '', 'ظرار', 'ظرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11929, 'طِيَانَةٌ', 'طيانة', 'جامد', 'طين', 'طيانة', 'طنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"طِيَانَةٌ-طِيَانَةٌ [ط ي ن]. : حِرْفَةُ الطَّيَّانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11930, 'ظَعينَةٌ', 'ظعينة', 'جامد', 'ظعن', 'ظعينة', 'ظعنة', '', '', '', 'مفرد', 'DnN', '', '', '"ظَعائِنُ:ظُعُنٌ:أَظْعانٌ"', '', '', '', '', '', '', '', '', '". 1.""اِرْتَحَلَ على ظَعينَتِهِ"" : عَلَى راحِلَتِهِ الَّتي يَرْتَحِلُ عَلَيْها. 2.""هِيَ ظَعينَتُهُ"": زَوْجَتُهُ. 3.""حَمَلُوها في الظَّعينَةِ"" : الهَوْدَجِ."', '');
