INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11934, 'ظَفَرَةٌ', 'ظفرة', 'جامد', 'ظفر', 'ظفرة', 'ظفرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"ظَفَرَةٌ-ظَفَرَةٌ [ظ ف ر]. : جُلَيْدَةٌ تَغْشَى العَيْنَ مِنَ الجانِبِ الَّذِي يَلي الأنْفَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11935, 'ظُفْرٌ', 'ظفر', 'جامد', '', 'ظفر', 'ظفر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَظْفارٌجأَظافِرُ"', '', 'R', '', '', '', '', '', '', '"ج: أَظْفارٌ. جج. أَظافِرُ. 1.""حَكَّ جِلْدَهُ بِظُفْرِهِ"" : مادَّةٌ قَرْنِيَّةٌ تَنْبُتُ في أَطْرافِ أَصابِعِ الإِنْسانِ وَبَعْضِ الحَيَوانات. ""ما حَكَّ جِلْدَكَ مِثْلُ ظُفْرِكَ"" ""يُقَلِّمُ أَظافِرَه"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11936, 'أَظْفارٌ', 'أظفار', 'جامد', '', 'ءظفار', 'ظفر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11937, 'أَظافِرُ', 'أظافر', 'جامد', '', 'ءظافر', 'ظفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11938, 'ظَلَعٌ', 'ظلع', 'جامد', 'ظلع', 'ظلع', 'ظلع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ظَلَعٌ-ظَلَعٌ [ظ ل ع]. : عَرَجٌ، غَمْزٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11939, 'ظِلْفٌ', 'ظلف', 'جامد', 'ظلف', 'ظلف', 'ظلف', '', '', '', 'مفرد', 'DnN', '', '', '"أَظْلافٌ"', '', 'R', '', '', '', '', '', '', '". 1.""حَيَوانٌ مِنْ ذَواتِ الأَظْلافِ"" : الظُّفْرُ الْمَشْقوقُ لِكُلِّ حَيَوانٍ مُجْتَرٍّ كَالبَقَرَةِ والشَّاةِ والظَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11940, 'أَظْلافٌ', 'أظلاف', 'جامد', '', 'ءظلاف', 'ظلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11941, 'ظِلالٌ', 'ظلال', 'جامد', 'ظلل', 'ظلال', 'ظلل', '', '', '', 'مفرد', '', '', '', '"مفردظِلّ"', '', 'R', '', '', '', '', '', '', '". 1.""تَحْتَ ظِلالِ الشَّجَرِ"" : تَحْتَ فَيْئِها. 2.""ظِلالُ البَحْرِ"" : أَمْواجُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11942, 'ظُلَّةٌ', 'ظلة', 'جامد', 'ظلل', 'ظلة', 'ظلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":ظُلَلٌ"', '', 'R', '', '', '', '', '', '', '". 1.""جَلَسَ تَحْتَ الظُّلَّةِ"" : المِظَلَّةِ. 2.""ظُلَّةُ الشَّجَرَةِ"" : ما أَظَلَّ مِنْها. البقرة آية 210 هَل يَنْظُرونَ إلا أَنْ يَأْتِيَهُمُ اللَّهُ في ظُلَلٍ مِنَ الغَمامِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11943, 'ظُلَلٌ', 'ظلل', 'جامد', '', 'ظلل', 'ظل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11944, 'ظِلٌّ', 'ظل', 'جامد', 'ظلل', 'ظل', 'ظل', '', '', '', 'مفرد', 'DnN', '', '', '"ظِلالٌ"', '', 'R', '', '', '', '', '', '', '". 1.""جَلَسَ تَحْتَ ظِلِّ الشَّجَرَةِ"" : تَحْتَ فَيْئِها، ضَوْءُ شُعاعِ الشَّمْسِ عِنْدَما يُسْتَتَرُ بِحاجِزٍ مَّا. 2.""يَتْبَعُهُ كَظِلِّهِ"" : كَخَيالِهِ. ""أَلْزَمُ لِلْمَرْءِ مِنْ ظِلِّهِ"". 3.""عاشَ في ظِلِّهِ مُعَزَّزاً مُكَرَّماً"" : في كَنَفِهِ، في حِمايَتِهِ. 4.""إِنْسانٌ خَفيفُ الظِّلِّ"" : مَرِحٌ، نَشيطٌ، خَفيفُ الرُّوحِ. 5.""إِنْسانٌ ثَقيلُ الظِّلِّ"" : مُمِلٌّ، مُضْجِرٌ، ثَقيلُ الرُّوحِ، طُفَيْلِيٌّ. 6.""ظِلُّ اللَّيْلِ"" : ظَلامُهُ، سَوادُهُ. 7.""ظِلُّ الشَّبابِ"" : أَوَّلُهُ. ""ظِلُّ الشِّتاءِ"" ""ظِلُّ اللَّيْلِ"". 8.""وَجْهُهُ كَظِلِّ الحَجَرِ"" : أَسْوَدُ. 9.""اِنْتَعَلْتُ ظِلِّي"" : أَي مَشَيْتُ في مُنْتَصَفِ النَّهارِ وَقْتَ القَيْظِ. ""مَشَيْتُ عَلَى ظِلِّي"". 10.""الظِّلُّ الخَلْفِيُّ"" : ما يُرْسَمُ في "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11945, 'ظِلالٌ', 'ظلال', 'جامد', '', 'ظلال', 'ظلل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11946, 'ظِلِّيلٌ', 'ظليل', 'جامد', 'ظلل', 'ظليل', 'ظلل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ظِلِّيلٌ-ظِلِّيلٌ [ظ ل ل]. ""المِصْباحُ الظِّلِّيلُ"" : المِصْباحُ الْمُحاطُ بِقُبَّعَةٍ مِنْ ثَوْبٍ مُلَوَّنٍ وَغَيْرِهِ يُكَثِّفُ ضَوْءهُ فيما حَوْلهُ، الظُّلَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11947, 'مِظَلَّةٌ', 'مظلة', 'جامد', 'ظلل', 'مظلة', 'مظلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَظَالُّ"', '', 'Rp', '', '', '', '', '', '', '". 1.""مِظَلَّةٌ شَمْسِيَّةٌ"" :مَا يُسْتَظَلُّ بِهِ مِنَ الشَّمْسِ. 2. ""مِظَلَّةُ الْمَطَـرِ"" :مَا يُسْتَتَرُ بِهِ مِنَ الْمَطَرِ. 3.""نَزَلَ الطَّيَّارُ بِالمِظَلَّةِ"" : كَتَّانٌ صَلْبٌ مَشْدُودٌ بِحِبَالٍ إِلَى حِزَامٍ يَعْقِدُهُ الطَّيَّارُ حَوْلَ قَامَتِهِ فَيَهْبِطُ بِهَا وَهِيَ مُحَلِّقَةٌ فِي الجَوِّ. 4.""جُنُودُ المِظَلاَّتِ"" : الِمظَلِّيُّونَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11948, 'مَظَالُّ', 'مظال', 'جامد', '', 'مظال', 'مظل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11949, 'ظَلامٌ', 'ظلام', 'جامد', 'ظلم', 'ظلام', 'ظلم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ظَلامٌ-ظَلامٌ [ظ ل م]. ""خَيَّمَ الظَّلامُ"" : الظُّلْمَةُ، سَوادُ اللَّيْلِ. ""اِنْسَلَّ تَحْتَ جُنْحِ الظَّلامِ"" ""ظَلامٌ كَثيفٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11950, 'ظَلْماءُ', 'ظلماء', 'جامد', 'ظلم', 'ظلماء', 'ظلم', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"ظَلْماءُ-ظَلْماءُ [ظ ل م]. ""لَيْلَةٌ ظَلْماءُ"" : شَديدَةُ الظَّلامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11951, 'ظُلْمَةٌ', 'ظلمة', 'جامد', 'ظلم', 'ظلمة', 'ظلمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""اِشْتَدَّتِ الظُّلْمَةُ في القَرْيَةِ"" : اِشْتَدَّ سَوادُ اللَّيْل.ِ ""أَخَذَتْ ظُلْمَةُ اللَّيْلِ تَغْزُو الفَضاءَ""فاطر آية 19 ، 20 وَما يَسْتَوِي الأَعْمَى والبَصيرُ وَلا الظُّلُماتُ وَلا النُّورُ (قرآن). 2.""بَحْرُ الظُّلَماتِ"" : الْمُحيطُ الأَطْلَسِيُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11952, 'ظُلَمٌ', 'ظلم', 'جامد', 'ظلم', 'ظلم', 'ظلم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ظُلْمٌ-ظُلْمٌ [ظ ل م] (مص. ظَلَمَ). ""لَحِقَهُ ظُلْمٌ"" : جَوْرٌ، اِنْتِهاكُ حَقِّ الآخَرِ عُدْواناً، عَدَمُ الإِنْصافِ. ""ظُلْماً وَعُدْواناً"" ""وَظُلْمُ ذَوِي القُرْبَى أَشَدُّ مَضاضَةً"". (طرفة بن العبد)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11953, 'ظِنانَةٌ', 'ظنانة', 'جامد', 'ظنن', 'ظنانة', 'ظننة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"ظِنانَةٌ-ظِنانَةٌ [ظ ن ن]. ""أَلْصَقُوا بِهِ ظِنانَةً"" : تُهْمَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11954, 'ظِنَّةٌ', 'ظنة', 'جامد', 'ظنن', 'ظنة', 'ظنة', '', '', '', 'مفرد', 'DnN', '', '', '"ظِنَنٌ:ظَنائِنُ"', '', 'R', '', '', '', '', '', '', '". ""أُلْحِقَتْ بِهِ ظِنَّةٌ"" : تُهْمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11955, 'ظِنَنٌ', 'ظنن', 'جامد', '', 'ظنن', 'ظن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11956, 'ظَنائِنُ', 'ظنائن', 'جامد', '', 'ظناءن', 'ظنن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11957, 'ظَمْياءُ', 'ظمياء', 'جامد', 'ظمي', 'ظمياء', 'ظم', '', '', '', 'مفرد', '', '', '', '"ظُمًى"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""عَيْنٌ ظَمْياءُ"" : رَقيقَةُ الجَفْنِ. 2.""ساقٌ ظَمْياءُ"" : قَليلَةُ اللَّحْمِ. 3.""لِثَةٌ ظَمْياءُ"" : قَليلَةُ الدَّمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11958, 'ظُمًى', 'ظمى', 'جامد', '', 'ظمى', 'ظم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11959, 'مَظَانُّ', 'مظان', 'جامد', 'ظنن', 'مظان', 'مظن', '', '', '', 'مفرد', '', '', '', '"مفردمَظِنَّة"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '". 1.""بَحَثَ عَنِ الْمَفَاتِيحِ فِي مَظَانِّهَا"" : الْمَوَاضِعُ الَّتِي يُرَجَّحُ وُجُودُهَا فِيهَا. 2.""كُنْتُ إِذَا وَصَلْتُ إِلَى الْمَوْضُوعِ أَجْمَعُ مَظَانَّهُ فِي الكُتُبِ"" : الْمَرَاجِعُ، الْمَصَادِرُ الَّتِي يَسْتَقِي مِنْهَا أَفْكَارَ مَوْضُوعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11960, 'مَظَنَّةٌ', 'مظنة', 'جامد', 'ظنن', 'مظنة', 'مظنة', '', '', '', 'مفرد', 'DnN', '', '', '"مَظَانُّ"', '', 'R', '', '', '', '', '', '', '".: أَصْلُ الشَّيْءِ وَمَنْبَعُهُ. ن. مَظَانّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11961, 'مَظَانُّ', 'مظان', 'جامد', '', 'مظان', 'مظن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11962, 'تَظَاهُرَةٌ', 'تظاهرة', 'جامد', 'ظهر', 'تظاهرة', 'تظهرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""خَرَجَ النَّاسُ فِي تَظَاهُرَةٍ شَعْبِيَّةٍ ضِدَّ الاحْتِلاَلِ الأَجْنَبِيِّ"" : اِجْتِمَاعُهُمْ جَمَاعَاتٍ لِلاحْتِجَاجِ وَتَأْكِيدِ مَطَالِبِهِمْ ضِدَّ... ""عَرَفَتِ الْمَدِينَةُ تَظَاهُرَاتٍ صَاخِبَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11963, 'ظُهارَةٌ', 'ظهارة', 'جامد', 'ظهر', 'ظهارة', 'ظهرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ظُهارَةٌ-ظُهارَةٌ [ظ هـ ر]. ""ظُهارَةُ الدَّابَّةِ"" : ما يوضَعُ على ظَهْرِها لِوِقايَتِها أَوْ رُكوبِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11964, 'ظِهارَةٌ', 'ظهارة', 'جامد', 'ظهر', 'ظهارة', 'ظهرة', '', '', '', 'مفرد', 'DnN', '', '', '"ظَهائِرُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""ظِهارَةُ ثَوْبٍ"": ظاهِرُهُ، خِلافُ بِطانَتِهِ. 2.""ظِهارَةُ البِساطِ"" : وَجْهُهُ الَّذِي يراهُ النَّاظِرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11965, 'ظَهائِرُ', 'ظهائر', 'جامد', '', 'ظهاءر', 'ظهر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11966, 'ظَهَرَةٌ', 'ظهرة', 'جامد', 'ظهر', 'ظهرة', 'ظهرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"ظَهَرَةٌ-ظَهَرَةٌ [ظ هـ ر]. : ما في البَيْتِ مِنْ قِناعٍ وَثِيابٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11967, 'ظُهْرَةٌ', 'ظهرة', 'جامد', 'ظهر', 'ظهرة', 'ظهرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"ظُهْرَةٌ-ظُهْرَةٌ [ظ هـ ر]. 1.""كانَ لَهُ ظُهْرةً"" : مُعيناً. 2.""هُوَ مِنْ ظُهْرَتِهِ"" : من عَشيرَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11968, 'ظُهْرٌ', 'ظهر', 'جامد', 'ظهر', 'ظهر', 'ظهر', '', '', '', 'مفرد', 'DnN', '', '', '"أَظْهارٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَصَلَ بَعْدَ الظُّهْرِ"" : بَعْدَ مُنْتَصَفِ النَّهارِ. 2.""أَدَّى صَلاةَ الظُّهْرِ"" : صَلاةَ وَقْتِ الظًّهيرَةِ. 3.""أَراهُ نُجومَ الظُّهْرِ"" : أَزْعَجَهُ، ضايَقَهُ مُضايَقَةً شَديدَةً. (لأَنَّ النُّجومَ لا تَظْهَرُ في مُنْتَصَفِ النَّهارِ). ""أَرَاهُ النُّجُومَ في عِزِّ الظُّهْرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11969, 'أَظْهارٌ', 'أظهار', 'جامد', '', 'ءظهار', 'ظهر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11970, 'ظَهيرَةٌ', 'ظهيرة', 'جامد', 'ظهر', 'ظهيرة', 'ظهرة', '', '', '', 'مفرد', 'DnN', '', '', '"ظَهائِرُمُؤَنَّثُظَهِير"', '', '', '', '', '', '', '', '', '". ""خَرَجَ في الظَّهيرَةِ"" : وَقْتَ انْتِصافِ النَّهارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11971, 'ظَهائِرُ', 'ظهائر', 'جامد', '', 'ظهاءر', 'ظهر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11972, 'ظَهيرٌ', 'ظهير', 'جامد', 'ظهر', 'ظهير', 'ظهر', '', '', '', 'مفرد', 'DnN', '', '', '"ظَهائِرُ"', '', 'R', '', '', '', '', '', '', '". ""صَدَرَ ظَهيرٌ شَريفٌ"" : مَرْسومٌ مَلَكِيٌّ يُصْدِرهُ الْمَلِكُ فيما يَخُصُّ قَضايا الدَّوْلَةِ من تَعْييناتٍ وَقَراراتٍ عُلْيا. ""ظَهائِرُ مَلَكِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11973, 'ظَهائِرُ', 'ظهائر', 'جامد', '', 'ظهاءر', 'ظهر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11974, 'ظَواهِرُ', 'ظواهر', 'جامد', 'ظهر', 'ظواهر', 'ظهر', '', '', '', 'مفرد', '', '', '', '"مفردظاهِرَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ن. ظاهِرَةٌ. 1.""اِسْتَشْرَفَ الظَّواهِرَ"" : أَعَالِي الأَوْدِيَةِ. 2.""عِلْمُ الظَّواهِرِ الْجَوِّيَّةِ"" : عِلْمٌ يَدْرُسُ حَوادِثَ الأَجْواءِ لِمَعْرِفَةِ حالاتِ الطَّقْسِ. 3.""ظَواهِرُ أَدَبِيَّةٌ"" : نَماذِجُ وَأَشْكالٌ تَتَضَمَّنُ مَفاهِيمَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11975, 'ظاهِرَة', 'ظاهرة', 'جامد', '', 'ظاهرة', 'ظهرة', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11976, 'مَظْهَرٌ', 'مظهر', 'جامد', 'ظهر', 'مظهر', 'مظهر', '', '', '', 'مفرد', 'DnN', '', '', '"مَظَاهِرُ"', '', 'Rp', '', '', '', '', '', '', '". ""يُحَافِظُ عَلَى مَظْهَرِهِ الخَارِجِيِّ"" : عَلَى شَكْلِهِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11977, 'مَظَاهِرُ', 'مظاهر', 'جامد', '', 'مظاهر', 'مظهر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11978, 'مُظْهَرٌ', 'مظهر', 'جامد', 'ظهر', 'مظهر', 'مظهر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مُظْهَرٌ-مُظْهَرٌ [ظ هـ ر]. ""الْمُظْهَرُ فِي النَّحْوِ"" : الاسْمُ الَّذِي لَيْسَ بِضَمِيرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11979, 'عَادٌ', 'عاد', 'جامد', '', 'عاد', 'عد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'O', '', '"التوبة آية 70 أَلَمْ يَأْتِهِمْ نَبَأُ الَّذِينَ مِنْ قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ (قرآن) : اِسْمُ رَجُلٍ مِنَ الْعَرَبِ الأَوَائِلِ وَبِهِ سُمِّيَتْ قَبِيلَتُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11980, 'ظَليمَةٌ', 'ظليمة', 'جامد', 'ظلم', 'ظليمة', 'ظلمة', '', '', '', 'مفرد', 'DnN', '', '', '"ظَلائِمُ"', '', '', '', '', '', '', '', '', '". 1. : ما أُخِذَ مِنْكَ ظُلْماً. 2. : اللَّبَنُ يُشْرَبُ مِنْهُ قَبْلَ أَن يَروبَ وَيَخْرُجَ زُبْدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11981, 'ظَلائِمُ', 'ظلائم', 'جامد', '', 'ظلاءم', 'ظلم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11982, 'عَاسُوقٌ', 'عاسوق', 'جامد', '', 'عاسوق', 'عسق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عَاسُوقٌ-عَاسُوقٌ (حو). : طَائِرٌ مِنْ فَصِيلَةِ الصَّقْرِيَّاتِ، وَهُوَ فِي حَجْم ِ الْبَاشِقِ، أَحْمَرُ اللَّوْنِ مُنَقَّطٌ بِسَوَادٍ، يَعِيشُ عَلَى الْحَشَرَاتِ وَالضَّفَادِعِ وَالطُّيُورِ وَالْحَيَّاتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11983, 'عِبْءٌ', 'عبء', 'جامد', 'عبأ', 'عبء', 'عب', '', '', '', 'مفرد', 'Dz', '', '', '"أَعْبَاءٌ"', '', 'Rz', '', '', '', '', '', '', '". ""عِبْءٌ ثَقِيلٌ"" : حِمْلٌ، ثِقْلٌ، تَعَبٌ. ""وَتَطْرَحُ النَّفْسُ أَعْبَاءهَا كَمَا تَطْرَحُ الْقَافِلَةُ أَحْمَالَهَا"". (ع.م. العقاد) ""نَهَضَ بِالأَعْبَاءِ وَحْدَهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11984, 'أَعْبَاءٌ', 'أعباء', 'جامد', '', 'ءعباء', 'عب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11985, 'عَبَاءةٌ', 'عباءة', 'جامد', 'عبأ', 'عباءة', 'عبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"عَبَاءةٌ-عَبَاءةٌ [ع ب أ]. 1. ""اِرْتَدَى الشَّيْخُ عَبَاءتَهُ"": اِرْتَدَى كِسَاءً مُكَوَّناًمِنْ قِطْعَةٍ وَاحِدَةٍ، مَفْتُوحٌ مِنْ قُدَّامٍ، وَاسِعٌ بِلاَ كُمَّيْنِ، يُلْبَسُ فَوْقَ الثِّيَابِ، يُعْرَفُ في الْمَغْـرِبِ بِالسِّلْهَـامِ. 2.""عَبَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11986, 'عُبٌّ', 'عب', 'جامد', 'عبب', 'عب', 'عب', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْبَابٌ"', '', 'R', '', '', '', '', '', '', '". ""عُبُّ الْقَمِيصِ"" : كُمُّهُ. ""عُبُّ الْعَبَاءةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11987, 'أَعْبَابٌ', 'أعباب', 'جامد', '', 'ءعباب', 'عبب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11988, 'مَعْبَرٌ', 'معبر', 'جامد', 'عبر', 'معبر', 'معبر', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَابِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""اِجْتَازُوا الْمَعْبَرَ بِسَلاَمٍ"": مَكَانُ العُبُورِ، الْجِسْرُ. 2.""صَعِدُوا إِلَى السَّفِينَةِ بِوَاسِطَةِ الْمَعْبَرِ"" : أَلْوَاحٌ تُتَّخَذُ لِلْعُبُورِ عَلَيْهَا..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11989, 'مَعَابِرُ', 'معابر', 'جامد', '', 'معابر', 'معبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11990, 'عَبيثَةٌ', 'عبيثة', 'جامد', 'عبث', 'عبيثة', 'عبثة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عَبيثَةٌ - [ع ب ث]. (طخ). : طَعامٌ يُتَّخَذُ مِنْ صِنْفَيْنِ مَخْلوطَيْنِ يُؤْكَلانِ مَعاً"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11991, 'عِبَادَةٌ', 'عبادة', 'جامد', 'عبد', 'عبادة', 'عبدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '"عِبَادَةٌ - ج: ات. [ع ب د]. 1. ""حَارَبَ الرَّسُولُ( عِبَادَةَ الأَصْنَام"" : التَّعَلُّقُ بِالأَصْنَامِ وَتَعَبُّدُهَا وَالوَلَعُ بِهَا. 2.""عِبَادَةُ اللَّهِ "": أَدَاءُ فَرَائِضَ فَرَضَهَا اللَّهُ عَلَى عِبَادِه،ِ أَيْ إِقَامَةُ الشَّرَائِعِ. "" يَقْضُونَ بَقِيَّةَ حَيَاتِهِمْ عِبَادَةً وَتَسْبِيحاً""    ""فَرَائِضُ العِبادَاتِ""  3.""عِبَادَةُ الشَّخْصِ"" : التَّعَلُّقُ بِشَخْصٍ وَتَأْلِيهُهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11992, 'عِبَادٌ', 'عباد', 'جامد', 'عبد', 'عباد', 'عبد', '', '', '', 'مفرد', '', '', '', '"مفردعَبْد"', '', 'R', '', '', '', '', '', '', '". ""يَا عِبَادَ اللَّهِ"": أَيُّهَا الْخَلْقُ، النَّاسُ أَجْمَعُونَ، الْبَشَرُ.فاطر آية 31 إِنَّ اللَّهَ بِعِبَادِهِ لَخَبِيرٌ بَصِيرٌ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11993, 'عَبْدٌ', 'عبد', 'جامد', 'عبد', 'عبد', 'عبد', '', '', '', 'مفرد', 'DnN', '', '', '"عَبِيدٌ:عِبَادٌ"', '', 'R', '', '', '', '', '', '', '". 1.""حَرَّرَ الْعَبْدَ"" : الرَّقِيقَ الْمَمْلُوكَ. ""اِنْتَهَى عَهْدُ الْعَبِيدِ"". 2.""وَدَّعَ عَبْدُ اللَّهِ أَهْلَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11994, 'عَبِيدٌ', 'عبيد', 'جامد', '', 'عبيد', 'عبد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11995, 'عِبَادٌ', 'عباد', 'جامد', '', 'عباد', 'عبد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11996, 'مَعْبَدٌ', 'معبد', 'جامد', 'عبد', 'معبد', 'معبد', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَابِدُ"', '', 'R', '', '', '', '', '', '', '". ""يُدَاوِمُ الصَّلاَةَ فِي الْمَعْبَدِ"": مَكَانُ العِبَادَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11997, 'مَعَابِدُ', 'معابد', 'جامد', '', 'معابد', 'معبد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11998, 'عَبْرَةٌ', 'عبرة', 'جامد', 'عبر', 'عبرة', 'عبرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". ""غَمَرَتْ عَيْنَيْهَا عَبْرَةٌ "" : دَمْعَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(11999, 'عِبْرَةٌ', 'عبرة', 'جامد', 'عبر', 'عبرة', 'عبرة', '', '', '', 'مفرد', 'DnN', '', '', '"عِبَرٌ"', '', 'R', '', '', '', '', '', '', '". ""لَكَ فِي ذَلِكَ عِبْرَةٌ"" : دَرْسٌ، عِظَةٌ، اِتِّعَاظٌ، الاِعْتِبَارُ بِمَا حَدَثَ وَمَضَى. يوسف آية 111 لَقَدْ كَانَ فِي قَصَصِهِمْ عِبْرَةٌ لأُولِي الأَلْبَابِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12000, 'عِبَرٌ', 'عبر', 'جامد', '', 'عبر', 'عبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12001, 'عَبْقَرُ', 'عبقر', 'جامد', 'عبقر', 'عبقر', 'عبقر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'N', 'N', 'N', '', '"عَبْقَرُ-عَبْقَرُ [ع ب ق ر]. : مَوْضِعٌ فِي الْجَزِيرَةِ العَرَبِيَّةِ كَانَ العَرَبُ يَعْتَقِدُونَ أَنَّهُ مَوْضِعُ الجِنِّ وَمَسْكَنُهُمْ وَيَنْسِبُونَ إِلَيْهِ كُلَّ عَجِيبٍ وَعَمَلٍ خَارِقٍ جَيِّدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12002, 'عَبْطٌ', 'عبط', 'جامد', 'عبط', 'عبط', 'عبط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَبْطٌ-عَبْطٌ [ع ب ط]. ""جَاءَ بِعَبْطٍ"" : بِكَذِبٍ مُخْتَلَقٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12003, 'عَبَايَةٌ', 'عباية', 'جامد', 'عبي', 'عباية', 'عبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ن. الْعَبَاءةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12004, 'عَتَبَةٌ', 'عتبة', 'جامد', 'عتب', 'عتبة', 'عتبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""جَلَسَ بِعَتَبَةِ الْبَابِ"" : خَشَبَةُ الْبَابِ الَّتِي يُوطَأُ عَلَيْهَا قَبْلَ اجْتِيَازِهِ. ""لِلْبَابِ عَتَبَتَانِ: العَتَبَةُ السُّفْلَى وَالعَتَبَةُ العُلْيَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12005, 'عَتَبٌ', 'عتب', 'جامد', 'عتب', 'عتب', 'عتب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَتَبٌ-عَتَبٌ [ع ت ب]. 1. ""مَا هَذَا الْعَتَبُ "": مَا هَذِهِ الشِّدَّةُ، أَوْ مَا هَذَا الأَمْرُ الْكَرِيهُ. 2.""أَتَى بِعَتَبٍ"" : بِنَقْصٍ وَفَسَادٍ. 3. : مَا بَيْنَ السَّبَّابَةِ وَالوُسْطَى، أَوْ مَا بَيْنَ الْوُسْطَى وَالْبِنْصِرِ. 4. : مَا بَيْنَ الْجَبَلَيْنِ. 5. : عِيدَانٌ مَعْرُوضَةٌ عَلَى وَجْهِ الْعُودِ، مِنْهَا تُمَدُّ الأَوْتَارُ إِلَى طَرَفِ الْعُودِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12006, 'إِعْتاقٌ', 'إعتاق', 'جامد', 'عتق', 'ءعتاق', 'إعتق', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"إِعْتاقٌ-إِعْتاقٌ [ع ت ق].""إِعْتاقُ عَبْدٍ"" : تَحْريرُهُ، تَخْليصُهُ مِنَ الرِّقِّ والعُبُودِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12007, 'عَتَلَةٌ', 'عتلة', 'جامد', 'عتل', 'عتلة', 'عتلة', '', '', '', 'مفرد', 'DnN', '', '', '"عَتَلٌ"', '', 'R', '', '', '', '', '', '', '". 1. : عَمُودٌ قَصِيرٌ مِنْ حَدِيدٍ، لَهُ رَأْسٌ عَرِيضٌ يُسْتَخْدَمُ لِهَدْمِ الحَائِطِ. 2. : هَرَاوَةٌ غَلِيظَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12008, 'عَتَلٌ', 'عتل', 'جامد', '', 'عتل', 'عتل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12009, 'عَتَمَةٌ', 'عتمة', 'جامد', 'عتم', 'عتمة', 'عتمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عَتَمَةٌ-عَتَمَةٌ [ع ت م]. ""اِشْتَدَّتْ عَتَمَةُ اللَّيْلِ بِالقَرْيَةِ"" : ظُلْمَةُ اللَّيْلِ. ""تَسِيرُ مُخْتَرِقَةً الأَزِقَّةَ الْغَاطِسَةَ فِي فُسَيْفِسَاءِ الْعَتَمَةِ وَالضَّوْءِ"". (محمد برادة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12010, 'عَثْرَةٌ', 'عثرة', 'جامد', 'عثر', 'عثرة', 'عثرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"1.""عَثْرَةُ لِسَانٍ"" : زَلَّةُ لِسَانٍ. 2.""وَقَفَ حَجَرَ عَثْرَةٍ فِي طَرِيقِهِ"" : وَقَفَ حَائِلاً دُونَهُ، حَالَ دُونَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12011, 'عُثْكُولٌ', 'عثكول', 'جامد', '', 'عثكول', 'عثكل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"عَثَاكِيلُ"', '', 'R', '', '', '', '', '', '', '"ج: عَثَاكِيلُ. ""عُثْكُولُ نَخْلَةٍ"" : شَطْبَةُ نَخْلَةٍ، وَهُوَ بِمَنْزِلَةِ الْعُنْقُودِ فِي الْكَرْمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12012, 'عَثَاكِيلُ', 'عثاكيل', 'جامد', '', 'عثاكيل', 'عثكل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12013, 'أُعْجوبَةٌ', 'أعجوبة', 'جامد', 'عجب', 'ءعجوبة', 'عجبة', '', '', '', 'مفرد', 'DnN', '', '', '"أَعاجِيبُ"', '', 'R', '', '', '', '', '', '', '". ""نَجا بِأُعْجوبَةٍ مِنْ حادِثَةِ سَيَّارَةٍ"" : بِمُعْجِزَةٍ، بِشَكْلٍ لا يُصَدَّقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12014, 'أَعاجِيبُ', 'أعاجيب', 'جامد', '', 'ءعاجيب', 'عجب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12015, 'عُجْبٌ', 'عجب', 'جامد', 'عجب', 'عجب', 'عجب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُجْبٌ-عُجْبٌ [ع ج ب]. ""اِسْتَبَدَّ بِهِ الْعُجْبُ "" : الزَّهْوُ، الكِبْرُ. ""الصِّفَاتُ الرَّذ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12016, 'عُجَّةٌ', 'عجة', 'جامد', '', 'عجة', 'عجة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُجَّةٌ-عُجَّةٌ (طخ). : طَعَامٌ يُصْنَعُ مِنَ الْبَيْضِ، يُضْرَبُ ثُمَّ يُقْلَى بِالسَّمْنِ أَوِ الزَّيْتِ. ""الْعُجَّةُ لاَ تَقْلِي عُجَّةً""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12017, 'عَجْرَفَةٌ', 'عجرفة', 'جامد', 'عجرف', 'عجرفة', 'عجرفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عَجْرَفَةٌ-عَجْرَفَةٌ [ع ج ر ف]. ""أَظْهَرَ عَجْرَفَةً بِسُلُوكِهِ هَذَا"" : تَكَبُّراً، جَفْوَةً فِي السُّلُوكِ أَوِ الْكَلاَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12018, 'عَجُزٌ', 'عجز', 'جامد', 'عجز', 'عجز', 'عجز', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْجَازٌ(مذ:مؤ)"', '', 'R', '', '', '', '', '', '', '"1.""عَجُزُ الإِنْسَانِ"" : مُؤَخِّرَتُهُ، أَي الجُزْءُ الخَلْفِيُّ فِي نِهَايَةِ السِّلْسِلَةِ الْفَقَارِيَّةِ. 2 ""عَجُزُ الْبَيْتِ الشِّعْرِيِّ"" : الشَّطْرُ الأَخِيرُ مِنْهُ. 3.""أَعْجَازُ النَّخْلِ"" : أُصُول"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12019, 'أَعْجَازٌ', 'أعجاز', 'جامد', '', 'ءعجاز', 'عجز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12020, 'عَتَادٌ', 'عتاد', 'جامد', 'عتد', 'عتاد', 'عتد', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْتِدَةٌ:عُتُدٌ"', '', 'R', '', '', '', '', '', '', '". ""عَتَادُ الْحَرْبِ"" : الأَسْلِحَةُ وَمُخْتَلِفُ الأَجْهِزَةِ وَالْمَوَادِّ الخَاصَّةِ بِهَا، عُدَّتُهُ. لِكُلِّ حَالٍ عِنْدَهُ عَتَادٌ (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12021, 'أَعْتِدَةٌ', 'أعتدة', 'جامد', '', 'ءعتدة', 'عتدة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
