INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12023, 'عَجِيزَةٌ', 'عجيزة', 'جامد', 'عجز', 'عجيزة', 'عجزة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَجِيزَةٌ-عَجِيزَةٌ [ع ج ز]. ""عَجِيزَةُ الْمَرْأَةِ"" : عَجُزُهَا، مُؤَخِّرَتُهَا. ""سَقَطَتْ عَلَى عَجِيزَتِهَا"" ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12024, 'مُعْجِزَةٌ', 'معجزة', 'جامد', 'عجز', 'معجزة', 'معجزة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". 1.""كَانَ النَّبِيُّ ( يَأْتِي بِالْمُعْجِزَاتِ"" : أَمْرٌ خَارِقٌ لِلْعَادَةِ غَيْرُ مَأْلُوفٍ حُدُوثُهُ أَوْ رُؤْيَتُهُ. 2.""الْحَوَاسِيبُ الإِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12025, 'عُجَالَةٌ', 'عجالة', 'جامد', 'عجل', 'عجالة', 'عجلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُجَالَةٌ-عُجَالَةٌ [ع ج ل]. 1.""أَنْجَزَ عَمَلَهُ عَلَى عُجَالَةٍ"" : بِاسْتِعْجَالٍ، عَلَى عَجَلٍ، بِسُرْعَةٍ. 2.""عُجَالَةُ مُسَافِرٍ"" : مَا يَحْمِلُهُ مِمَّا لاَ تَعَبَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12026, 'عُجْلَةٌ', 'عجلة', 'جامد', 'عجل', 'عجلة', 'عجلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُجْلَةٌ-عُجْلَةٌ [ع ج ل]. : عُجَالَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12027, 'مِعْجَلٌ', 'معجل', 'جامد', 'عجل', 'معجل', 'معجل', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاجِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِعْجَلُ الرِّيَاضَةِ"" : آلَةٌ لِقِيَاسِ السُّرْعَةِ. 2.""مِعْجَلُ السَّيّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12028, 'مَعَاجِلُ', 'معاجل', 'جامد', '', 'معاجل', 'معجل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12029, 'عِجْلٌ', 'عجل', 'جامد', '', 'عجل', 'عجل', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"عُجُولٌ"', '', 'R', '', '', '', '', '', '', '"ج: عُجُولٌ. وَلَدُ الْبَقَرَةِ فِي سَنَتِهِ الأُولَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12030, 'عُجُولٌ', 'عجول', 'جامد', '', 'عجول', 'عجل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12031, 'عُجَام', 'عجام', 'جامد', 'عجم', 'عجام', 'عجم', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عُجَام-عُجَامٌ ، ةٌ [ع ج م]. ""عُجَامُ التَّمْرِ"" : حَبَّتُهُ، بِزْرَتُهُ، النَّوَى. ""عُجَامُ الزَّبِيبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12032, 'عَجْمَاءُ', 'عجماء', 'جامد', 'عجم', 'عجماء', 'عجم', '', '', '', 'مفرد', 'Dw', '', '', '"عَجْمَاوَاتٌ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1. : بَهِيمَةٌ، خَرْسَاءُ. جُرْحُ الْعَجْمَاءِ جُبَارٌ (حديث) : أَيْ هَدَرٌ لاَ غُرْمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12033, 'عَجْمَاوَاتٌ', 'عجماوات', 'جامد', '', 'عجماوات', 'عجمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12034, 'عَجَمٌ', 'عجم', 'جامد', 'عجم', 'عجم', 'عجم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عَجَمٌ-عَجَمٌ [ع ج م]. ""رَحَلَ إِلَى بِلاَدِ الْعَجَمِ"" : خِلاَفُ بِلاَدِ الْعَرَبِ، أَيْ بِلاَدُ الْفُرْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12035, 'عِجَارٌ', 'عجار', 'جامد', 'عجر', 'عجار', 'عجر', '', '', '', 'مفرد', 'DnN', '', '', '"عُجُرٌ"', '', 'R', '', '', '', '', '', '', '"""تَرْتَدِي الْعِجَارَ"" : حِجَابٌ تَلُفُّهُ عَلَى اسْتِدَارَةِ رَأْسِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12036, 'عُجُرٌ', 'عجر', 'جامد', '', 'عجر', 'عجر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12037, 'مُعْجَمَةٌ', 'معجمة', 'جامد', 'عجم', 'معجمة', 'معجمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مُعْجَمَةٌ-مُعْجَمَةٌ [ع ج م]. ""أَبْيَاتٌ شِعْرِيَّةٌ مُعْجَمَةٌ"" : أَحْرُفُهَا مُنَقَّطَةٌ كُلُّهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12038, 'مُعْجَمٌ', 'معجم', 'جامد', 'عجم', 'معجم', 'معجم', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَعَاجِمُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""الْمُعْجَمُ اللُّغَوِيُّ"" : كِتَابٌ يَضُمُّ مَجْمُوعَ كَلِمَاتِ لُغَةٍ مَّا مُرَتَّبَةً تَرْتيباً أَلِفْبَائِيّاً أَوْ تَرْتيباً آخرَ، وَكُلُّ كَلِمَةٍ لَهَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12039, 'مَعَاجِمُ', 'معاجم', 'جامد', '', 'معاجم', 'معجم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12040, 'عَجْنَاءُ', 'عجناء', 'جامد', 'عجن', 'عجناء', 'عجن', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"عَجْنَاءُ-عَجْنَاءُ [ع ج ن]. 1.""نَاقَةٌ عَجْنَاءُ"" : بَالِغَةُ السِّمَنِ، سَمِينَةٌ. 2.""نَاق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12041, 'مِعْجَنَةٌ', 'معجنة', 'جامد', 'عجن', 'معجنة', 'معجنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مِعْجَنَةٌ-مِعْجَنَةٌ [ع ج ن].: آلَةُ العَجْنِ يُعْجَنُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12042, 'مِعْجَنٌ', 'معجن', 'جامد', 'عجن', 'معجن', 'معجن', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاجِنُ"', '', 'R', '', '', '', '', '', '', '". ""تُوَاصِلُ عَجْنَ العَجِينِ فِي المِعْجَنِ"" : مَا يُعْجَنُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12043, 'مَعَاجِنُ', 'معاجن', 'جامد', '', 'معاجن', 'معجن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12044, 'عُجْوَةٌ', 'عجوة', 'جامد', 'عجو', 'عجوة', 'عجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""عُجْوَةُ الْبَهْلَوَانِ"" : تَغْيِيرُ مَلاَمِحِ الْوَج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12045, 'عَجْوَةٌ', 'عجوة', 'جامد', '', 'عجوة', 'عجة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"1. : ضَرْبٌ مِنْ أَجْوَدِ التَّمْرِ بِالْمَدِينَةِ، وَنَخْلَتُهَا تُسَمّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12046, 'عَدَّادٌ', 'عداد', 'جامد', 'عدد', 'عداد', 'عدد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَدَّادٌ-عَدَّادٌ [ع د د]. 1.""رَاقَبَ عَدَّادَ سَيَّارَتِهِ"" : جِهَازٌ آلِيٌّ يُبَيِّنُ الْمَسَافةَ الَّتِي تَقْطَعُهَا السَّيَّارَةُ. 2.""عَدَّادُ سَيَّارَةِ الأُجْرَةِ"" : جِهَازٌ آلِيٌّ يُسَجِّلُ ثَمَنَ الرِّحْلَةِ حَسَبَ الْمَسَافَةِ الَّتِي تَقْطَعُهَا السَّيَّارَةُ. 3.""الْعَدَّادُ الْكَهْرَبَائِيُّ أَوِالْمَائِيُّ"" : آلَةٌ تُسَجِّلُ الْكَمِّيَّةَ الْمُسْتَهْلَكَةَ مِنَ الْكَهْرَبَاءِ أَوِ الْمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12047, 'عُدَّةٌ', 'عدة', 'جامد', 'عدد', 'عدة', 'عدة', '', '', '', 'مفرد', 'DnN', '', '', '"عُدَدٌ"', '', 'R', '', '', '', '', '', '', '". 1.""كُونُوا عَلَى عُدَّةٍ"" : كُونُوا عَلَى اسْتِعْدَادٍ وَأُهْبَةٍ. ""عَدَّ لِلأَمْرِ عُدَّتَهُ"". 2.""عُدَّةُ الْجَيْشِ"" : عَتَادُهُ وَآلاَتُهُ الْحَرْبِيَّةُ. 3.""عُدَّةُ الْفَرَسِ"" : سَرْجُهَا. 4.""عُدَّةُ الْبَنَّاءِ وَالنَّجَّارِ وَالصَّيَّادِ"" : آلاَتُهُمْ وَمَا يَحْتَاجُونَهُ لِعَمَلِهِمْ. ""صَيَّرَ الْعِلْمَ عُدَّةً لِيَوْمِ الشِّدَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12048, 'عُدَدٌ', 'عدد', 'جامد', '', 'عدد', 'عد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12049, 'عِدَّةٌ', 'عدة', 'جامد', 'عدد', 'عدة', 'عدة', '', '', '', 'مفرد', 'DnN', '', '', '"عِدَدٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""بَقِيَ عِدَّةَ أَشْهُرٍ بِالْمَدِينَةِ"": أَيْ عَدَداً مِنَ الشُّهُورِ. ""قَرَأَ عِدَّةَ كُتُبٍ فِي شَهْرٍ وَاحِدٍ"". 2.""عِدَّةُ الْمَرْأَةِ "" : الفَتْرَةُ الزَّمَنِيَّةُ الَّتِي يَحْرُمُ عَلَيْهَا أَنْ تَتَزَوَجَّ فِيهَا بَعْدَ طَلاَقٍ أَوْ وَفَاةِ زَوْجِهَا الأَوَّلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12050, 'عِدَدٌ', 'عدد', 'جامد', '', 'عدد', 'عد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12051, 'عُدٌّ', 'عد', 'جامد', 'عدد', 'عد', 'عد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُدٌّ-عُدٌّ [ع د د]. ""عُدُّ الوَجْهِ"" : بَثْرٌ يَظْهَرُ فِي وَجْهِ الشَّابِّ اليَافِعِ وَهُوَ مَا يُعْرَفُ بِـ""حَبِّ الشَّبَابِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12052, 'عِدٌّ', 'عد', 'جامد', 'عدد', 'عد', 'عد', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْدَادٌ"', '', 'R', '', '', '', '', '', '', '". 1.""سَيْلٌ عِدٌّ"" : جَارٍ لاَ يَنْقَطِعُ. 2.""عِدُّ الشَّيْءِ"" : كَثْرَتُهُ. 3.""هُوَ عِدُّهُ"" : مَثِيلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12053, 'أَعْدَادٌ', 'أعداد', 'جامد', '', 'ءعداد', 'عدد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12054, 'مُعَدَّاتٌ', 'معدات', 'جامد', 'عدد', 'معدات', 'معدت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُعَدَّاتٌ-مُعَدَّاتٌ [ع د د]. ""مُعَدَّاتٌ عَسْكَرِيَّةٌ"" : مَوَادُّ مُصَن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12055, 'عَدَسَةٌ', 'عدسة', 'جامد', 'عدس', 'عدسة', 'عدسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"وَاحِدَةُالعَدَسِ"', '', 'R', '', '', '', '', '', '', '". 1.""أَصَابَتْهُ الْعَدَسَةُ"" : بَثْرَةٌ تَخْرُجُ فِي الْجِسْمِ كَالطَّاعُونِ أَوِ السَّرَطَانِ وَقَلَّمَا يَسْلَمُ صَاحِبُهَا. 2.""عَدَسَةُ الْعَيْنِ"" : جِسْمٌ شَفَّافٌ مَرِنٌ مُحَدَّبُ السَّطْحَيْنِ يَقَعُ بَيْنَ الْقُزَحِيَّةِ وَالْجِسْمِ الزُّجَاجِيِّ، وَيُجَمِّعُ الضَّوْءَ السَّاقِطَ عَلَى الْقَرْنِيَّةِ فِي نُقْطَةٍ وَاحِدَةٍ تَقَعُ عَلَى "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12056, 'عَدَسٌ', 'عدس', 'جامد', '', 'عدس', 'عدس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَدَسٌ-عَدَسٌ (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الْقَرْنِيَّاتِ، عُشْبِيٌّ زِرَاعِيٌّ، ثَمَرَتُهُحَبَّةٌ صَغِيرَةٌ مُفَلْطَحَةٌ مُكَوَّنَةٌ مِنْ فِلْقَتَيْنِ، وَهُوَ مِنَ الْمَوَادِّ الْغِدَائِيَّةِ الْمُتَوَافِرَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12057, 'عَدَسِيَّةٌ', 'عدسية', 'جامد', '', 'عدسية', 'عدسة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '": قِطْعَةٌ مِنَ الْبِلَّوْرِ الشَّفَّافِ مُكَبِّرَةٌ تَدْخُلُ فِي آلاَتِ التَّصْوِيرِ وَغَيْرِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12058, 'عِدْلٌ', 'عدل', 'جامد', 'عدل', 'عدل', 'عدل', '', '', '', 'مفرد', 'DnN', '', '', '"عُدُولٌ:أَعْدَالٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هُوَ عِدْلُهُ "" : نَظِيرُهُ، مِثْلُهُ. 2.""عِدْلُ الْحِمْلِ"" : نِصْفُهُ عل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12059, 'عُدُولٌ', 'عدول', 'جامد', '', 'عدول', 'عدل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12060, 'أَعْدَالٌ', 'أعدال', 'جامد', '', 'ءعدال', 'عدل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12061, 'عَدْلِيَّةٌ', 'عدلية', 'جامد', 'عدل', 'عدلية', 'عدلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عَدْلِيَّةٌ-عَدْلِيَّةٌ [ع د ل]. : مَجْمُوعَةُ الْمَحَاكِمِ وَ قُضَاتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12062, 'تَعْدِينٌ', 'تعدين', 'جامد', 'عدن', 'تعدين', 'تعدن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَعْدِينٌ-تَعْدِينٌ (كيما) [ع د ن]. ""تَطَوَّرَتْ صِنَاعَةُ التَّعْدِينِ فِي بِلاَدِنَا"" : اِسْتِخْرَاجُ الْمَعَادِنِ مِنْ تَحْتِ الأَرْضِ، تَنْقِيَتُهَا وَسَبْكُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12063, 'مَعْدِنٌ', 'معدن', 'جامد', 'عدن', 'معدن', 'معدن', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَادِنُ"', '', 'R', '', '', '', '', '', '', '". 1.: جِسْمٌ صَلْبٌ مُتَمَيِّزٌ بِقَابِلِيَّةٍ لِتَوْصِيلِ الكَهْرَبَاءِ وَالْحَرَارَةٍ كَالْحَدِيدِ وَالنُّحَاسِ وَالذَّهَبِ وَالفِضَّةِ وَالبَلاَتِينِ. 2. ""مَعْدِنُ الرَّجُلِ"" : مَنْبِتُهُ ، أَصْلُهُ الَّذِي يَنْحَدِرُ مِنْهُ. ""مِنْ مَعْدِنٍ أَصِيلٍ"" ""هُوَ مَعْدِنُ خَيْرٍ"". 3. ""اِمْتَحَنَ مَعْدِنَهُ"" : عَجَمَ عودَهُ، اِمْتَحَنَ حَقِيقَةَ جَوْهَرِهِ وَطَبْعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12064, 'مَعَادِنُ', 'معادن', 'جامد', '', 'معادن', 'معدن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12065, 'عَدَن', 'عدن', 'جامد', '', 'عدن', 'عدن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', 'N', 'N', 'N', 'O', '', '": مِنَ مُدُنِ الْجمْهوريَّةِ اليَمَنِيَّةِ، عَاصِمَةُ جُمْهُورِيَّةِ الْيَمَنِ الدِّيمُقْرَاطِيَّةِ سَابِقاً مِنْ 1970 إلى 1990."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12066, 'عَدْنٌ', 'عدن', 'جامد', '', 'عدن', 'عدن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'O', '', '"""جَنَّةُ عَدْنٍ"" : جَنَّةُ إِقَامَةٍ لِمَكَانِ الْخُلْدِ فِيهَا.طه آية 76 جَنَّاتُ عَدْنٍ تَجْرِي مِنْ تَحْتِهَا الأَْنَهَارُ خَالِدِينَ فِيهَا (قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12067, 'عَذَابٌ', 'عذاب', 'جامد', 'عذب', 'عذاب', 'عذب', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَعْذِبَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""قَاسَى الشَّقَاءَ وَالْعَذَابَ"": الأَلَمَ النَّفْسِيَّ الْمُتْعِبَ. السَّفَرُ قِطْعَةٌ مِنَ الْعَذَابِ (حديث). 2.""تَعَرَّضَ لِلْعَذَابِ عَلَى يَدِ طُغَاةٍ عُتَاةٍ"" : الأَلَمُ الجَسَدِيُّ الْمُؤْلِمُ. ""يَسُومُهُ سُوءَ عَذَابٍ""إبراهيم آية 22إِنَّ الظَّالِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12068, 'أَعْذِبَةٌ', 'أعذبة', 'جامد', '', 'ءعذبة', 'عذبة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12069, 'عَدَاوَةٌ', 'عداوة', 'جامد', 'عدو', 'عداوة', 'عدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '". ""اِسْتَحْكَمَتِ الْعَدَاوَةُ بَيْنَهُمَا"" : الْمُعَادَاةُ، الْخِصَامُ، الْخُصُومَةُ.المائدة آية 64وَأَلْقَيْنَا بَيْنَهُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12070, 'عَدُوٌّ', 'عدو', 'جامد', 'عدو', 'عدو', 'عد', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْدَاءٌ"', '', '', '', '', '', '', '', '', '". ""اِحْذَرْ عَدُوَّكَ"" : الْخَصْم، مَنْ يُكِنُّ لَكَ الْعَدَاوَةَ. ""عَدُوٌّ عَاقِلٌ خَيْرٌ مِنْ صَدِيقٍ جَاهِلٍ"" ""وَقَعَ فِي قَبْضَةِ أَعْدَائِهِ""البقرة آية 168 وَلاَ تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12071, 'أَعْدَاءٌ', 'أعداء', 'جامد', '', 'ءعداء', 'عد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12072, 'عِدًى', 'عدى', 'جامد', 'عدو', 'عدى', 'عد', '', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"عِدىً-عِدىً [ع د و]. 1.""حَاصَرَهُ الْعِدَى مِنْ كُلِّ جِهَةٍ"" : الأَعْدَاءُ. 2.""تَكَاثَرَ الْعِدَى فِي الْبِلاَدِ"" : الْغُرَبَاءُ. 3.""عِدَى الْوَادِي"" : شَاطِئُهُ، نَاحِيَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12073, 'عُدْوَةٌ', 'عدوة', 'جامد', '', 'عدوة', 'عدة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"عُدًى:عِدَاءٌ"', '', 'R', '', '', '', '', '', '', '"ج: عُدىً، عِدَاءٌ. 1.""ظَلَّ يَنْظُرُ إِلَيْهِمْ مِنْ عُدْوَةٍ"": مِنْ مَكَانٍ مُرْتَفِعٍ. 2.""عُدْوَةُ الْوَادِي"" : شَاطِئُهُ، جَانِبُهُ.الأنفال آية 42 إِذْ أَنْتُمْ بِالْعُدْوَةِ الدُّنْيَا وَهُمْ بِالعُدْوَةِ الْقُصْوَى (قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12074, 'عُدًى', 'عدى', 'جامد', '', 'عدى', 'عد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
