INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12076, 'عِذَارٌ', 'عذار', 'جامد', 'عذر', 'عذار', 'عذر', '', '', '', 'مفرد', 'DnN', '', '', '"عُذُرٌ"', '', 'R', '', '', '', '', '', '', '". 1.""تَوَرَّدَ عِذَارُهُ"" : خَدُّهُ. 2.""عِذَارَا الطَّرِيقِ"" : جَانِبَاهُ. ""عِذَارَا الْوَادِي"". 3.""عِذَارُ اللِّجَامِ"" : مَا تَدَلَّى مِنَ اللِّجَامِ عَلَى خَدِّ الْفَرَسِ. 4.""عِذَارُ الشَّعْرِ"" : الشَّعْرُ المُحَاذِي لِلأُذُنِ مِنْ جَانِبِ اللِّحْيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12077, 'عُذُرٌ', 'عذر', 'جامد', '', 'عذر', 'عذر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12078, 'عُذْرَةٌ', 'عذرة', 'جامد', 'عذر', 'عذرة', 'عذرة', '', '', '', 'مفرد', 'DnN', '', '', '"عُذَرٌ"', '', 'R', '', '', '', '', '', '', '". 1.""عُذْرَةٌ مِنَ الشَّعْرِ"" : الْخُصْلَةُ مِنْهُ. 2.""عُذْرَةُ الْفَرَسِ"" : الشَّعْرُ عَلَى كَاهِلِ الْفَرَسِ. 3.""عُذْرَةُ الْفَتَاةِ"" : بَكَارَتُهَا، وَهُوَ غِشَاءٌ رَهِيفٌ يُغَطِّي الْفَتْحَةَ التَّنَاسُلِيَّةَ لِلأُنْثَى. 4.""بَنُو عُذْرَةَ"" : اِسْمُ قَبِيلَةٍ حِجَازِيَّةٍ اِشْتَهَرَتْ بِالْحُبِّ الْعُذْرِيِّ الْعَفِيفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12079, 'عُذَرٌ', 'عذر', 'جامد', '', 'عذر', 'عذر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12080, 'عُذْرٌ', 'عذر', 'جامد', 'عذر', 'عذر', 'عذر', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْذَارٌ"', '', 'R', '', '', '', '', '', '', '". ""قَدَّمَ عُذْراً مَقْبُولاً"" : الْحُجَّةُ الَّتِي يَعْتَذِرُ بِهَا. ""عُذْرٌ أَقْبَحُ مِنْ ذَنْبٍ"" ""الْعُذْرُ أَقْبَحُ مِنَ الزَّلَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12081, 'أَعْذَارٌ', 'أعذار', 'جامد', '', 'ءعذار', 'عذر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12082, 'مَعْذِرَةٌ', 'معذرة', 'جامد', 'عذر', 'معذرة', 'معذرة', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاذِرُ:مَعَاذِيرُ"', '', 'R', '', '', '', '', '', '', '". ""طَلَبَ مِنْهُ الْمَعْذِرَةَ"" : الصَّفْحَ، الْمُسَامَحَةَ. ""لَمْ يَقْبَلْ مَعْذِرَتَهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12083, 'مَعَاذِرُ', 'معاذر', 'جامد', '', 'معاذر', 'معذر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
