INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12085, 'عَذِرَةٌ', 'عذرة', 'جامد', 'عذر‎‎', 'عذرة', 'عذرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عَذِرَةٌ-عَذِرَةٌ [ع ذ ر‎‎]. 1.""عَذِرَةُ كَلُّ كَائِنٍ حَيٍّ"" : غَائِطُهُ. 2.""عَذِرَةُ الدَّارِ"" : فِنَاؤُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12086, 'عَذْرَاءُ', 'عذراء', 'جامد', '', 'عذراء', 'عذر', '', '', '', 'جمع تكسير', 'Dw', '', '', '"عَذَارَى:عَذْرَاوَاتٌ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"ج: عَذَارَى، عَذْرَاوَاتٌ. 1.""فَتَاةٌ عَذْرَاءُ"" : بِكْرٌ. 2.""السَّيِّدَةُ العَذْراءُ"" : لَقَبُ السَّيِّدَةِ مَرْيَمَ، أُمِّ المَسِيحِ. ""تَوَهَّمَ أَنَّ الْعَذْرَاءَ تَجَسَّدَتْ أَمَامَهُ"". 3.""غَابَةٌ عَذْرَاءُ"" : غَابَةٌ بِكْرٌ لَمْ تُسْتَغَلَّ بَعْدُ."', ':لا جذر:لا مفرد');
