INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12088, 'عَذْرَاوَاتٌ', 'عذراوات', 'جامد', '', 'عذراوات', 'عذرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12089, 'عِذْقٌ', 'عذق', 'جامد', 'عذق', 'عذق', 'عذق', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْذَاقٌ:عُذُوقٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1. ""عِذْقُ النَّخْلَةِ"" : عُرْجُونُهَا، عُنْقُودُهَا، قِنْوُهَا. 2. ""عِذْقُ الْعِنَبِ"" : عُنْقُودُهُ."', '');
