INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12093, 'أَعْرابٌ', 'أعراب', 'جامد', 'عرب', 'ءعراب', 'عرب', '', '', '', 'مفرد', 'DnN', '', '', '"أعاريبُ"', '', 'Rp', '', '', '', '', '', '', '". ""سُرعانَ ما عادَ الأعْرابُ إلى بادِيَتِهِم فَهُمْ لَمْ يَأْلَفُوا حَياةَ الحاضِرَةِ"" : سُكَّانُ البادِيَةِ. ""كانَ الأصْمَعِيُّ يَجْمَعُ اللُّغَةَ مِنَ الأعْرابِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12094, 'أعاريبُ', 'أعاريب', 'جامد', '', 'ءعاريب', 'عرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
