INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12098, 'عَرْبَانُ', 'عربان', 'جامد', 'عرب', 'عربان', 'عربن', '', '', '', 'مفرد', '', '', '', '"""رَجُلٌعَرْبَانُ"""', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"عَرْبَانُ-عَرْبَانُ [ع ر ب]. ""رَجُلٌ عَرْبَانُ"" : فَصِيحُ اللِّسَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12099, 'عُرْبَانٌ', 'عربان', 'جامد', 'عرب', 'عربان', 'عربن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُرْبَانٌ-عُرْبَانٌ [ع ر ب]. ""هُوَ مِنَ الْعُرْبَانِ"" : مِنَ العَرَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12100, 'عَرَبٌ', 'عرب', 'جامد', 'عرب', 'عرب', 'عرب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَرَبٌ-عَرَبٌ [ع ر ب]. ""أُمَّةُ الْعَرَبِ"" : أُمَّةٌ السَّامِيِّينَ، مَنْشَؤُهُمْ بِشِبْهِ الْجَزِيرَةِ، وَانْتَشَرُوا مِنَ الْخَلِيجِ إِلَى الْمُحِيطِ بَعْدَ الْفُتُوحَاتِ الإِسْلاَمِيَّةِ. ""بِلاَدُ الْعَرَبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12101, 'عَرَبَةٌ', 'عربة', 'جامد', '', 'عربة', 'عربة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ج: عَرَبَاتٌ. ""تَجُرُّ الْخَيْلُ الْعَرَبَةَ"" : مَرْكَبَةٌ ذَاتُ عَجَلَتَيْنِ أَوْ أَرْبَعِ عَجَلاتٍ تَجُرُّهَا الْخَيْلُ. ""عَـرَبَـةُ حِصَانٍ"" ""عَرَبَةُ حِمَارٍ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12102, 'عُرْبُونٌ', 'عربون', 'جامد', 'عربن', 'عربون', 'عربن', '', '', '', 'مفرد', 'DnN', '', '', '"عَرَابِينُ"', '', 'R', '', '', '', '', '', '', '". ""دَفَعَ الْعُرْبُونَ فِي انْتِظَارِ إِنْهَاءِ الْبَيْعِ"" : مَا يَدْفَعُهُ الشَّارِي مُقَدَّماً لِتَأْكِيدِ رَغْبَتِهِ فِي الشِّرَاءِ عَلَى أَنْ يُخْصَمَ مِنَ الثَّمَنِ إِنْ تَمَّ البَيْعُ وَلاَ يُسْتَرْجَعَ إِذَا لَمْ يَتِمَّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12103, 'عَرَابِينُ', 'عرابين', 'جامد', '', 'عرابين', 'عربن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12104, 'مِعْرَاجٌ', 'معراج', 'جامد', 'عرج', 'معراج', 'معرج', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَارِجُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِعْرَاجُ العِمَارَةِ"" : الْمَصْعَدُ، السُّلَّمُ. 2.""لَيْلَةُ المِعْرَاجِ"" : لَيْلَةُ صُعُودِ الرَّسُولِ ( إِلَى السَّمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12105, 'مَعَارِجُ', 'معارج', 'جامد', '', 'معارج', 'معرج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12106, 'عُرْجُونٌ', 'عرجون', 'جامد', '', 'عرجون', 'عرجن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"عَرَاجِينُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: عَرَاجِينُ. ""عُرْجُونُ النَّخْلَةِ"" : عِذْقُهَا، أَيْ عُنْقُودُهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12107, 'عَرَاجِينُ', 'عراجين', 'جامد', '', 'عراجين', 'عرجن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12108, 'عُرَارٌ', 'عرار', 'جامد', 'عرر', 'عرار', 'عرر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُرَارٌ-عُرَارٌ [ع ر ر]. ""اِعْتَرَفَ بِعُرَارِهِ"" : بِخَطِيئَتِهِ، بِإِثْمِهِ، بِجِنَايَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12109, 'عُرَّةٌ', 'عرة', 'جامد', 'عرر', 'عرة', 'عرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُرَّةٌ-عُرَّةٌ [ع ر ر]. 1.""أُصِيبَ بِالْعُرَّةِ"" : بِالْجَرَبِ، أَوِ اعْتَرَاهُ جُنُونٌ. 2.""هُوَ عُرَّةُ قَوْمِهِ "" : قَذَرُهَا. 3.""عُرَّةُ السَّنَامِ"" : شَحْمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12110, 'عُرْسٌ', 'عرس', 'جامد', 'عرس', 'عرس', 'عرس', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْرَاسٌ"', '', 'R', '', '', '', '', '', '', '". ""حَضَرَ عُرْسَ صَدِيقِهِ"" : زِفَافَهُ، تَزْوِيجَهُ. ""حَفْلَةُ الْعُرْسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12111, 'أَعْرَاسٌ', 'أعراس', 'جامد', '', 'ءعراس', 'عرس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12112, 'عِرْسٌ', 'عرس', 'جامد', 'عرس', 'عرس', 'عرس', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْرَاسٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هُوَ عِرْسُهَا"" : زَوْجُهَا. ""هِيَ عِرْسُهُ"" : زَوْجَتُهُ. ""هُمَا عِرْسَانِ"". 2. عِرْس، اِبْنُ: ن. اِبْنُ عِرْسٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12113, 'أَعْرَاسٌ', 'أعراس', 'جامد', '', 'ءعراس', 'عرس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
