INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12116, 'عَرُوسٌ', 'عروس', 'جامد', 'عرس', 'عروس', 'عرس', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"عَرَائِسُ"', '', 'R', '', '', '', '', '', '', '". 1.""اِسْتَقْبَلُوا العَرُوسَ بِالزَّغَارِيدِ"" : الْمَرْأَةُ مَادَامَتْ فِي عُرْسِهَا، أَيْ في يَوْمِ زِفَافِهَا. 2.""يُحِبُّ مُشَاهَدَةَ مَسْرَحِ العَرَائِسِ"" : مَسْرَحُ الدُّمَى لِلْأَطْفَالِ."', '');
