INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12122, 'عَرِيشٌ', 'عريش', 'جامد', 'عرش', 'عريش', 'عرش', '', '', '', 'مفرد', 'DnN', '', '', '"عُرُشٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَقَامَ عَرِيشاً فِي مُنْتَصَفِ الطَّرِيقِ"" : مَا يُسْتَظَلُّ بِهِ وَيُتَّخَذُ مِنَ الأَغْصَانِ أَوْ سَعَفِ النَّخْلِ. 2.""عَرِيشُ الكَرْمِ"" : مَا عُرِّشَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12123, 'عُرُشٌ', 'عرش', 'جامد', '', 'عرش', 'عرش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12124, 'عَرْصَةٌ', 'عرصة', 'جامد', '', 'عرصة', 'عرصة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":أَعْرَاصٌ:عِرَاصٌ"', '', 'R', '', '', '', '', '', '', '"ج: عَرَصَاتٌ، أَعْرَاصٌ، عِرَاصٌ. 1.""عَرْصَةُ الدُّورِ"" : الْبُقْعَةُ الوَاسِعَةُ بَيْنَ الدُّورِ لاَ بِنَاءَ فِيهَا. 2.""عَرْصَةُ الدَّارِ"" : وَسَطُهَا. تَحَمَّلَ أَصْحَابِي عِشَاءً وغَادَرُوا*أَخَا ثِقَـةٍ في عَرْصَةِ الدَّارِ ثَاويا (مالك بن الرَّيْبِ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12125, 'أَعْرَاصٌ', 'أعراص', 'جامد', '', 'ءعراص', 'عرص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12126, 'عِرَاصٌ', 'عراص', 'جامد', '', 'عراص', 'عرص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12127, 'عِرَاضٌ', 'عراض', 'جامد', 'عرض', 'عراض', 'عرض', '', '', '', 'مفرد', 'DnN', '', '', '"عُرْضٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""عِرَاضُ الشَّيْءِ"" : نَاحِيَتُهُ، شَقُّهُ. 2.""عِرَاضُ جَمَلٍ"" : خَطٌّ فِي فَخِذِهِ عَرْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12128, 'عُرْضٌ', 'عرض', 'جامد', '', 'عرض', 'عرض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12129, 'عُرْضَةٌ', 'عرضة', 'جامد', 'عرض', 'عرضة', 'عرضة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"عُرْضَةٌ-عُرْضَةٌ [ع ر ض]. 1.""كَانَ عُرْضَةً للِشَّتَائِمِ"" : كَانَ هَدَفاً للِشَّتَائِمِ. 2.""هُوَ عُرْضَةٌ للِشَّرِّ"" : قَوِيٌّ عَلَيْهِ. 3.""هِيَ عُرْضَةٌ لِزَوْجِهَا"" : أَيْ قَوِيَّةٌ عَلَيْهِ. 4.""هُوَ عُرْضَةٌ لِلْكَلاَمِ"" : أَيْ كَثِيراً مَا يَعْتَرِضُهُ كَلاَمُ النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12130, 'عَرَضٌ', 'عرض', 'جامد', 'عرض', 'عرض', 'عرض', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْرَاضٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""هَذَا مَا يَمْلِكُ مِنْ عَرَضٍ"" : مَتَاعُ الدُّنْيَا قَلَّ أَوْ كَثُرَ.النور آية 33 لِتَبْتَغُوا عَرَضَ الحَيَاةِ الدُّنْيَا (قرآن). 2.""مَا قُمْتُ بِهِ كَانَ عَرَضاً"" : مِنْ دُونِ تَفْكِيرٍ أَوْ قَصْدٍ أَوْ رَوِيَّةٍ. 3.""بَدَأَتْ أَعْرَاضُ الْمَرَضِ تَظْهَرُ عَلَيْهِ "" : مَا يَظْهَرُ عَلَى الْمَرِيضِ مِنَ الظَّوَاهِرِ الطَّارِئَةِ الدَّالَّةِ عَلَى الْمَرَضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12131, 'أَعْرَاضٌ', 'أعراض', 'جامد', '', 'ءعراض', 'عرض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12132, 'عُرْضٌ', 'عرض', 'جامد', 'عرض', 'عرض', 'عرض', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُرْضٌ-عُرْضٌ [ع ر ض]. 1.""فِي عُرْضِ الْبَحْرِ"" : فِي وَسَطِهِ. ""فِي عُرْضِ النَّهْرِ"". 2.""عُرْضُ الْجَبَلِ"" : سَفْحُهُ. 3.""عُرْضُ السَّيْفِ"" : صَفْحَتُهُ. 4.""ضَرَبَ بِنَصَائِحِهِ عُرْضَ الْحَائِطِ"" : لَمْ يَهْتَمَّ بِهَا وَلَمْ يُبَالِ، رَمَى بِهَا فِي نَاحِيَةٍ مِنْ نَوَاحِيهِ. 5.""عُرْضُ الْعُنُقِ أَوِالْوَجْهِ"" : جَانِبُهُ. 6.""هُوَ مِنْ عُرْضِ النَّاسِ"" : أَيْ مِنْ عَامَّتِهِمْ. 7.""نَظَرَ إِلَيْهِ عَنْ عُرْضٍ"" : أَيْ مِنْ جَانِبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12133, 'عِرْضٌ', 'عرض', 'جامد', 'عرض', 'عرض', 'عرض', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْرَاضٌ"', '', 'R', '', '', '', '', '', '', '". 1.""يُحَافِظُ عَلَى عِرْضِهِ "" : عَلَى حَسَبِهِ وَنَسَبِهِ، شَرَفِهِ. 2.""عِرْضُ الاِنْسَانِ"" : بَدَنُهُ، نَفْسُهُ. 3. : سَحَابٌ عَظِيمٌ. 4. : وَادٍ فِيهِ شَجَرٌ وَقُرىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12134, 'أَعْرَاضٌ', 'أعراض', 'جامد', '', 'ءعراض', 'عرض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12135, 'مُسْتَعْرِبَةٌ', 'مستعربة', 'جامد', 'عرب', 'مستعربة', 'مستعربة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مُسْتَعْرِبَةٌ-مُسْتَعْرِبَةٌ [ع ر ب]. ""العَرَبُ الْمُستَعْرِبَةُ"" : أَيِ الَّذِينَ اِسْتَقَرُّوا فِي بِلاَدِ العَرَبِ وَهُمْ مِنْ أَصْلٍ آخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12136, 'عَرُوضٌ', 'عروض', 'جامد', 'عرض', 'عروض', 'عرض', '', '', '', 'مفرد', 'DnN', '', '', '"أَعَارِيضُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""عِلْمُ العَرُوضِ"" : عِلْمُ مِيزَانِ الشِّعْرِ. 2.""عَرُوضُ البَيْتِ الشِّعْرِيِّ"" : آخِرُ تَفْعِيلَةِ شَطْرِهِ الأَوَّلِ. 3.""زَارَ العَرُوضَ"" : مَكَّةَ وَالْمَدِينَةَ وَمَا حَوْلَهُمَا. 4.""عَرُوضُ مَكَانٍ مَّا : نَاحِيَتُهُ. 5.""عَرُوضُ جَبَلٍ"" : طَرِيقٌ فِي عُرْضِهِ، مَضْيَقٌ. 6.""عَرُوضُ الكَلاَمِ"" : فَحْوَاهُ، مَعْنَاهُ. ""عَرَفْتُ هَذَا فِي عَرُوضِ كَلاَمِهِ"". 7.""هَذِهِ المَسْأَلَةُ عَرُوضُ هَذِهِ"" : نَظِيرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12137, 'أَعَارِيضُ', 'أعاريض', 'جامد', '', 'ءعاريض', 'عرض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12138, 'عَرِيضَةٌ', 'عريضة', 'جامد', 'عرض', 'عريضة', 'عرضة', '', '', '', 'مفرد', 'DnN', '', '', '"عَرَائِضُمُؤَنَّثُعَرِيض"', '', '', '', '', '', '', '', '', '". ""قَدَّمَ سُكَّانُ الْحَيِّ عَرِيضَةً للِسُّلُطَاتِ الْمَحَلِّيَّةِ"" : صَحِيفَةٌ تَتَضَمَّنُ مُلْتَمَساً بِمَطَالِبَ أَوْ مَظَالِمَ تُعْرَضُ عَلَى الْمَسْؤُولِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12139, 'عَرَائِضُ', 'عرائض', 'جامد', '', 'عراءض', 'عرض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12140, 'مَعْرِضٌ', 'معرض', 'جامد', 'عرض', 'معرض', 'معرض', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَارِضُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَعْرِضُ الصُّوَرِ"": مَكَانُ عَرْضِ الصُّوَرِ وَإِظْهَارِهَا. ""مَعْرِضٌ فَنِّيٌّ"". 2.""الْمَعْرِضُ الدُّوَلِيُّ"" : أَرْوِقَةٌ فِي بِنَاءٍ وَاسِعِ الأَرْكَانِ لِعَرْضِ الْمَنْتُوجَاتِ وَالصِّنَاعَاتِ وَالاخْتِرَاعَاتِ لِلدِّعَايَةِ وَالتَّعْرِيفِ بِهَا. ""الْمَعْرِضُ الصِّنَاعِيُّ"". 3.""ذَكَرَ ذَلِكَ فِي مَعْرِضِ حَدِيثِهِ"" : فِي مَجَالِ، خِلاَلَ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12141, 'مَعَارِضُ', 'معارض', 'جامد', '', 'معارض', 'معرض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12142, 'مِعْرَضٌ', 'معرض', 'جامد', 'عرض', 'معرض', 'معرض', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَارِضُ:مَعَارِيضُ"', '', 'R', '', '', '', '', '', '', '". 1.""لَبِسَتْ عَارِضَةُ الأَزْيَاءِ مِعْرَضاً لِتَعْرِضَهُ عَلَى الْمُشْتَرِينَ"" : مَا تَعْرِضُهُ العَارِضَةُ مِنْ لِبَاسٍ عَلَى الْمُشْتَرِينَ. 2.""مِعْرَضُ العَرُوسِ"" : لِبَاسُ لَيْلَةِ زِفَافِهَا تَظْهَرُ بِهِ. 3.""الأَلْفَاظُ مَعَارِيضُ الْمَعَانِي"" : تُجَمِّلُهَا وَتُنَمِّقُهَا وَتُزَيِّنُهَا."', '');
