INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12145, 'عَرْعَرٌ', 'عرعر', 'جامد', '', 'عرعر', 'عرعر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عَرْعَرٌ-عَرْعَرٌ (نب). : مِنْ فَصِيلَةِ الصَّنَوْبَرِيَّاتِ، يُشْبِهُ السَّرْوَ، أَنْوَاعُهُ عَدِيدَةٌ، تَصْلُحُ لِلصِّنَاعَةِ الْخَشَبِيَّةِ وَالتَّزْيِينِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12146, 'تَعْرِفَةٌ', 'تعرفة', 'جامد', 'عرف', 'تعرفة', 'تعرفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""حُدِّدَتْ تَعْرِفَةٌ جَدِيدَةٌ لأَسْعَارِ الْمَوَادِّ الغِذَائِيَّةِ"" : لاَئِحَةٌ تُحَدِّدُ الأَسْعَارَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12147, 'تَعْرِيفَةٌ', 'تعريفة', 'جامد', 'عرف', 'تعريفة', 'تعرفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""عُلِّقَتْ عَلَى بَابِ الْمَتْجَرِ تَعْرِيفَةٌ بِالْمَوَادِّ الْمَعْرُوضَةِ لِلْبَيْعِ"" : لاَئِحَةُ الأَسْعَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12148, 'عِرَافَةٌ', 'عرافة', 'جامد', 'عرف', 'عرافة', 'عرفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عِرَافَةٌ-عِرَافَةٌ [ع ر ف]. : مِهْنَةُ، وَعَمَلُ العَرَّافِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12149, 'عِزْبَةٌ', 'عزبة', 'جامد', 'عزب', 'عزبة', 'عزبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عِزْبَةٌ-عِزْبَةٌ [ع ز ب]. ""سَافَرَ إِلَى العِزْبَةِ"" : الضَّيْعَةُ، الْمَزْرَعَةُ تُحِيطُ بِهَا بُيُوتُ الفَلاَّحِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12150, 'عُرْفٌ', 'عرف', 'جامد', 'عرف', 'عرف', 'عرف', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْرَافٌ"', '', 'R', '', '', '', '', '', '', '". 1.""عُرْفٌ تَعَارَفَ عَلَيْهِ النَّاسُ"" : مَا اسْتَقَرَّ فِي الْوَسَطِ الاجْتِمَاعِيِّ وَ أَصْبَحَ عَادَةً جَارِيَةً بَيْنَ النَّاسِ فِي مُعَامَلاَتِهِمْ. 2.""عُرْفُ اللِّسَانِ"" : مَا يُفْهَمُ مِـنَ اللَّفْظِ بِحَسَبِ وَضْعِهِ اللُّغَوِيِّ. 3.""عُرْفُ الدِّيكِ"" : لَحْمَةٌ مُسْتَطِيلَةٌ فِي أَعْلَى رَأْسِهِ. 4.""عُرْفُ الْفَرَسِ"" : شَعْرُ عُنُقِ الْفَرَسِ. 5.""عُـرْفُ الدِّيـكِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12151, 'أَعْرَافٌ', 'أعراف', 'جامد', '', 'ءعراف', 'عرف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12152, 'عَرَفَاتٌ', 'عرفات', 'جامد', '', 'عرفات', 'عرفت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'O', '', '"عَرَفَةُ. ""يَوْمُ عَرَفَاتٍ"" : الْيَوْمُ التَّاسِعُ مِنْ ذِي الْحِجَّةِ، وَهُوَ يَوْمُ الْوُقُوفِ بِجَبَلِ عَرَفَاتٍ الْقَرِيبِ مِنْ مَكَّةَ. ""يَوْمُ عَرَفَةَ يَوْمٌ عَظِيمٌ"" ""قَالَ أَفْضَلُ الأَيَّامِ يَوْمُ عَرَفَةَ . (حديث) الْحَجُّ عَرَفَة . (حديث)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12153, 'عِرَاقٌ', 'عراق', 'جامد', 'عرق', 'عراق', 'عرق', '', '', '', 'مفرد', 'DnN', '', '', '"مثنىعراقان-العراقان"', '', 'Rp', '', '', '', '', '', '', '"عِرَاقَان-الْعِرَاقَان [ع ر ق]. : الْكُوفَةُ وَالْبَصْرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12154, 'عِرَاقٌ', 'عراق', 'جامد', 'عرق', 'عراق', 'عرق', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْرِقَةٌ:عُرْقٌ:عُرُقٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""عِرَاقُ النَّهْرِ"" : شَاطِئُهُ. ‎""عِرَاقُ الْبَحْرِ"". 2.""عِرَاقُ الدَّارِ"" : سَاحَتُهَا، فِنَاؤُهَا. 3.""عِرَاقُ الأَذُنِ"" : كِفَافُهَا. 4.""الْعِرَاقُ"" : مِنَ الأَقْطَارِ الْعَرَبِيَّةِ، ""الْجُمْهورِيَّةُ العِراقِيَّةُ"" عَاصِمَتُهَا بَغْدَاد. يَقَعُ العِراقُ فِي غَرْبِ آسِيَا بَيْنَ سُورِيَةَ وَالسُّعُودِيَّةِ وَالْكُوَيتِ وَإيرانَ وَتُرْكِيَا وَالأُرْدُنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12155, 'أَعْرِقَةٌ', 'أعرقة', 'جامد', '', 'ءعرقة', 'عرقة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
