INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12157, 'عُرُقٌ', 'عرق', 'جامد', '', 'عرق', 'عرق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12158, 'عَرْقَاةٌ', 'عرقاة', 'جامد', 'عرق', 'عرقاة', 'عرقة', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"عَرْقَاةٌ-عَرْقَاةٌ [ع ر ق]. ""عَرْقَاةُ الشَّجَرَةِ"" : أَصْلُ أَرُومَتِهَا الَّتِي تَذْهَبُ فِي الأَرْضِ وَتَتَشَعَّبُ مِنْهَا العُرُوقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12159, 'عِرْقَةٌ', 'عرقة', 'جامد', 'عرق', 'عرقة', 'عرقة', '', '', '', 'مفرد', 'DnN', '', '', '"عِرَقٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ن. عَرْقَاةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12160, 'عِرَقٌ', 'عرق', 'جامد', '', 'عرق', 'عرق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12161, 'عِرْقٌ', 'عرق', 'جامد', 'عرق', 'عرق', 'عرق', '', '', '', 'مفرد', 'DnN', '', '', '"عُرُوقٌ:أَعْرَاقٌ"', '', 'R', '', '', '', '', '', '', '". : أَصْلُ كُلِّ شَيْءٍ. 1.""يَجِرِي الدَّمُ فِي عُرُوقِ الإِنْسَانِ"" : الأَوْرِدَةُ، مَجْرَى الدَّمِ فِي الْجَسَدِ. ""لَنْ أَسْتَسْلِمَ جَرَى دَمٌ فِي عُرُوقِي"" ""تَجَمَّدَتِ الدِّمَاءُ فِي عُرُوقِهِ"". 2.""عِرْقُ السُّوسِ"" (نب) : نَبَاتٌ مِنَ فَصِيلَةِ القَرْنِيَّاتِ يُصْنَعُ مِنْهُ شَرَابٌ نَافِعٌ وَيُسْتَخْدَمُ مَسْحُوقُهُ فِي الْمَجَالِ الطِّبِّيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12162, 'عُرُوقٌ', 'عروق', 'جامد', '', 'عروق', 'عرق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12163, 'أَعْرَاقٌ', 'أعراق', 'جامد', '', 'ءعراق', 'عرق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12164, 'عُرْقُوبٌ', 'عرقوب', 'جامد', 'عرق', 'عرقوب', 'عرقب', '', '', '', 'مفرد', 'DnN', '', '', '"عَرَاقِيبُ"', '', 'R', '', '', '', '', '', '', '". 1.""وَتَرُ العُرْقُوبِ"" : عَصَبٌ غَلِيظٌ فَوْقَ العَقِبِ مِنَ الإِنْسَانِ. 2.""عُرْقُوبُ الدَّابَّةِ"" : مَا يَكُونُ فِي رِجْلِهَا بِمَنْزِلَةِ الرُّكْبَةِ فِي يَدِهَا بَيْنَ السَّاقِ وَالوَظِيفِ. 3.""مُتَقَارِبُ العُرْقُوبَيْنِ"" : صِفَةٌ للدَّوابِّ بِتَقَارُبِ عَرْقُوبَي القَائِمَتَيْنِ الْخَلْفِيَّتَيْنِ بِحَيْثُ يَصْطَدِمَانِ عِنْدَ السَّيْرِ. 4.""كُلُّ أَمْرٍ لَهُ عَرَاقِيبُهُ"" : عَرَاقِيلُهُ، صِعَابُهُ، مَشَاكِلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12165, 'عَرَاقِيبُ', 'عراقيب', 'جامد', '', 'عراقيب', 'عرقب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12166, 'عَرَقِيَّةٌ', 'عرقية', 'جامد', 'عرق', 'عرقية', 'عرقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَرَقِيَّةٌ-عَرَقِيَّةٌ [ع ر ق]. ""وَضَعَ العِمَامَةَ فَوْقَ العَرَقِيَّةِ"" : مَا يُلْبَسُ تَحْتَ العِمَامَةِ لِيَمْتَصَّ العَرَقَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12167, 'عُرْقُوبٌ', 'عرقوب', 'جامد', '', 'عرقوب', 'عرقب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""مَوَاعِيدُ عُرْقُوبٍ"" : اِسْمُ رَجُلٍ فِي الْجَاهِلِيَّةِ يُضْرَبُ بِهِ الْمَثَلُ فِي الْخُلْفِ بِالوَعْدِ وَالْمَوْعِدِ. كَانَتْ مَوَاعِيدُ عُرْقُوبٍ لَهَا مَثَلاً*وَمَا مَوَاعِيـدُهَـا إِلاَّ الأَبَاطِيلُ (كعب بن زهير). ""أَخْلَفُ مِنْ عُرْقُوبٍ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12168, 'عَرِيكَةٌ', 'عريكة', 'جامد', 'عرك', 'عريكة', 'عركة', '', '', '', 'مفرد', 'DnN', '', '', '"عَرَائِكُ"', '', 'R', '', '', '', '', '', '', '". 1.""هُوَ لَيِّنُ العَرِيكَةِ"" : سَلِسُ الْخُلُقِ. 2.""شَدِيدُ العَرِيكَةِ"" : شَدِيدُ النَّفْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12169, 'عَرَائِكُ', 'عرائك', 'جامد', '', 'عراءك', 'عرك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12170, 'مَعْرَكَةٌ', 'معركة', 'جامد', 'عرك', 'معركة', 'معركة', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَارِكُ"', '', 'R', '', '', '', '', '', '', '". 1.""خَاضَ مَعْرَكَةً ضَارِيَةً"" : قِتَالاً ضَارِياً. 2.""ذَهَبُوا إِلَى الْمَعْرَكَةِ"" : مَوْضِع القِتَالِ. 3.""بَدَأَتِ الْمَعْرَكَةُ الانْتِخَابِيَّةُ"" : الْحَمْلَةُ الانْتِخَابِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12171, 'مَعَارِكُ', 'معارك', 'جامد', '', 'معارك', 'معرك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12172, 'عُرَامٌ', 'عرام', 'جامد', 'عرم', 'عرام', 'عرم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُرَامٌ-عُرَامٌ [ع ر م]. 1.""عُرَامُ الشَّجَرَةِ"" : قِشْرَتُهَا. 2.""عُرَامُ الْقِدْرِ"" : وَسَخُهَا. 3.""عُرَامُ الْجَيْشِ"" : كَثْرَتُهُ وَشِدَّتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12173, 'عُرْمَةٌ', 'عرمة', 'جامد', 'عرم', 'عرمة', 'عرمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُرْمَةٌ-عُرْمَةٌ [ع ر م]. ""خَلَّفَ عُرْمَةً مِنْ سَنَابِلِ القَمْحِ وَرَاءهُ"": كُومَةُ السَّنَابِلِ، مَا تَكَدَّسَ مِنَ الْحِنْطَةِ تُجْمَعُ لِتُذَرَّى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12174, 'عُزُوبَةٌ', 'عزوبة', 'جامد', 'عزب', 'عزوبة', 'عزبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُزُوبَةٌ-عُزُوبَةٌ [ع ز ب]. ""يَعِيشُ فِي عُزُوبَةٍ"" : حَيَاةُ الأَعْزَبِ الَّذِي لَمْ يَتَزَوَّجْ بَعْدُ. ""لِمَاذَا قَضَيْتَ عَلَى نَفْسِكَ بِالعُزُوبَةِ كُلَّ هَذَا الدَّهْرِ"". (ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12175, 'عِرْنِينٌ', 'عرنين', 'جامد', '', 'عرنين', 'عرنن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"عَرَانِينُ"', '', 'R', '', '', '', '', '', '', '"ج: عَرَانِينُ. 1. : مَا تَحْتَ مُجْتَمَعِ الْحَاجِبَيْنِ أَوَّلُ الأَنْفِ مِنْ فَوْقُ. 2.""رَجُلٌ عِرْنِينٌ"" : شَرِيفٌ. 3.""عَرَانِينُ السَّحَابِ"": أَوَائِلُ الْمَطَرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12176, 'عَرَانِينُ', 'عرانين', 'جامد', '', 'عرانين', 'عرنن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12177, 'عُرْوَةٌ', 'عروة', 'جامد', 'عرو', 'عروة', 'عرة', '', '', '', 'مفرد', 'DnN', '', '', '"عُرًى"', '', 'R', '', '', '', '', '', '', '". 1.""أَخَذَ الإِبْرِيقَ مِنْ عُرْوَتِهِ"" : مِقْبَضِهِ. 2.""عُرْوَةُ ثَوْبٍ"": مَا يُدْخَلُ فِيهِ الزِّرُّ. 3.""بَيْنَهُمَا عُرْوَةٌ وُثْقَى"" : رِبَاطٌ قَـوِيٌّ يُسْتَمْسَكُ بِهِ.البقرة آية 256 فَقَدِ اسْتَمْسَكَ بِالعُرْوَةِ الوُثْقَى لاَ انْفِصَامَ لَهَا (قرآن). 4.""عُرْوَةُ الشَّجَرِ"" : مَا لاَ يَسْقُطُ وَرَقُهُ فِي الشِّتَاءِ. 5.""وَجَدَ عِنْدَهُ ما فِيهِ عُرْوَةٌ"" : أي ما يُعَوَّلُ عَلَيْهِ. 6.""عُرْوَةُ البِلاَدِ"" : ضَوَاحِيها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12178, 'عُرًى', 'عرى', 'جامد', '', 'عرى', 'عر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12179, 'عُرًى', 'عرى', 'جامد', 'عرو', 'عرى', 'عر', '', '', '', 'مفرد', '', '', '', '"مفردعُرْوَة"', '', 'Rw', '', '', '', '', '', '', '". ""عُرَى الصَّدَاقَةِ"" : رَوَابِطُهَا، مَا يُسْتَمْسَكُ بِهِ. ن. عُرْوَةٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12180, 'عَرَاءٌ', 'عراء', 'جامد', 'عري', 'عراء', 'عر', '', '', '', 'مفرد', '', '', '', '"أَعْرَاءُ"', '', 'Rz', '', '', '', '', '', '', '". ""نَامَ فِي الْعَرَاءِ"" : فِي فَضَاءٍ لاَ يُحِيطُ بِهِ شَيْءٌ، لاَ يَسْتُرُهُ وَلاَ يُغَطِّيهِ شَيْءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12181, 'أَعْرَاءُ', 'أعراء', 'جامد', '', 'ءعراء', 'عر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12182, 'عَرِينٌ', 'عرين', 'جامد', '', 'عرين', 'عرن', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"عُرُنٌ:عَرَائِنُ"', '', 'R', '', '', '', '', '', '', '"ج: عُرُنٌ، عَرَائِنُ. 1.""عَرِينُ الأَسَدِ"" : أَجَمَتُهُ، مَأْوَاهُ. 2.""عَرِينُ الْحَيَّةِ"" : جُحْرُهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12183, 'عُرُنٌ', 'عرن', 'جامد', '', 'عرن', 'عرن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12184, 'عَرَائِنُ', 'عرائن', 'جامد', '', 'عراءن', 'عرن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12185, 'مَعَازِفُ', 'معازف', 'جامد', 'عزف', 'معازف', 'معزف', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَعَازِفُ-مَعَازِفُ [ع ز ف]. ""مَعَازِفُ الطَّرَبِ"" : آلاَتٌ مُوسِيقِيَّةٌ ذَاتُ أَوْتَارٍ كَالعُودِ وَالكَمَانِ وَنَحْوِهِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12186, 'مِعْزَفٌ', 'معزف', 'جامد', 'عزف', 'معزف', 'معزف', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَعَازِفُ"', '', 'R', '', '', '', '', '', '', '". ""يُحْسِنُ العَزْفَ عَلَى الْمِعْزَفِ"" : آلَةُ طَرَبٍ كَالعُودِ أَوِ البَيَانِ وَنَحْوِهِمَا..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12187, 'مَعَازِفُ', 'معازف', 'جامد', '', 'معازف', 'معزف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12188, 'عُزْلَةٌ', 'عزلة', 'جامد', 'عزل', 'عزلة', 'عزلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُزْلَةٌ-عُزْلَةٌ [ع ز ل]. ""يَعِيشُ فِي عُزْلَةٍ عَنِ النَّاسِ"" : في اعْتِكَافٍ، اعْتِزَالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12189, 'مُعْتَزِلَةٌ', 'معتزلة', 'جامد', 'عزل', 'معتزلة', 'معتزلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مُعْتَزِلَةٌ-مُعْتَزِلَةٌ [ع ز ل].: فِرْقَةٌ إِسْلاَمِيَّةٌ فَلْسَفِيَّةٌ كَانَ عِمَادُ فِكْرِهَا الْمَنْطِقُ وَالقِيَاسُ وَنَفْيُ القَدَرِ، نَشَأَتْ فِي أَوَاخِرِ القَرْنِ الأَوَّلِ الهِجْرِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12190, 'مَعْزِلٌ', 'معزل', 'جامد', 'عزل', 'معزل', 'معزل', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَازِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَعْزِلُ الْمَرْضَى"" : مَوْضِعٌ يُعْزَلُ فِيهِ الْمَرْضَى عَنِ الأَصِحَّاءِ. 2.""كَانَ بِمَعْزِلٍ عَنْ كُلِّ الْمَزَالِقِ"" : بَعِيدًا عَنْ ... 3.""هُوَ عَنِ الْحَقِّ بِمَعْزِلٍ"" : مُجَانِبٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12191, 'مَعَازِلُ', 'معازل', 'جامد', '', 'معازل', 'معزل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12192, 'مَعْزَى', 'معزى', 'جامد', 'عزي', 'معزى', 'معز', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"مَعْزَى-مَعْزَى [ع ز ي]. ""اِلْتَقَى الأهْلُ والأصْحابُ فِي المَعْزَى"": مَكانُ التَّعْزِيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12193, 'عِزْرَائِيلُ', 'عزرائيل', 'جامد', '', 'عزراءيل', 'عزرل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'N', 'N', 'O', '', '": اِسْمُ مَلاَكِ الْمَوْتِ الْمُكَلَّفِ بِقَبْضِ أَرْوَاحِ البَشَرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12194, 'يَعْسُوبٌ', 'يعسوب', 'جامد', 'عسب', 'يعسوب', 'عسب', '', '', '', 'مفرد', 'DnN', '', '', '"يَعَاسِيبُ"', '', 'R', '', '', '', '', '', '', '"(حش). 1. : حَشَرَةٌ مِنْ فَصِيلَةِ الْيَعْسُوبِيَّاتِ، لَهَا أَرْبَعَةُ أَجْنِحَةٍ غِشَائِيَّةٍ، تَعِيشُ قُرْبَ الْمِيَاهِ الْهَادِئَةِ، تَصْطَادُ الْحَشَرَاتِ الصَّغِيرَةَ جَوّاً. 2.""يَعْسُوبُ النَّحْلِ"" : مَلِكَةُ النَّحْلِ. 3.""كَانَ يَعْسُوبَ قَوْمِهِ"" : أَيْ رَئِيسَهُمْ، كَبِيرَهُمْ، زَعِيمَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12195, 'يَعَاسِيبُ', 'يعاسيب', 'جامد', '', 'يعاسيب', 'عسب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12196, 'عَوْسَجٌ', 'عوسج', 'جامد', 'عسج', 'عوسج', 'عسج', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عَوْسَجٌ-عَوْسَجٌ [ع س ج] (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الْبَاذِنْجَانِيَّاتِ، مِنْ نَوْعِ الْفَرَوْلاَتِ، شَائِكٌ لَهُ ثَمَرٌ مُدَوَّرٌ يُؤْكَلُ. ""طَارَ إِلَى قَفَصٍ آخَرَ مَحْبُوكٍ مِنْ قُضْبَانِ الْعَوْسَجِ. (جبران خ. جبران)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12197, 'عَسْجَدٌ', 'عسجد', 'جامد', 'عسجد', 'عسجد', 'عسجد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَسْجَدٌ-عَسْجَدٌ [ع س ج د]. ""فِي خَزَائِنِهِ عَسْجَدٌ وَدُرٌّ وَيَاقُوتٌ"" : الذَّهَبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12198, 'عُسْرَةٌ', 'عسرة', 'جامد', 'عسر', 'عسرة', 'عسرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُسْرَةٌ-عُسْرَةٌ [ع س ر]. ""يَعِيشُ فِي عُسْرَةٍ"" : فِي ضِيقٍ وَشِدَّةٍ.البقرة آية 280وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ (قرآن). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12199, 'عُسٌّ', 'عس', 'جامد', 'عسس', 'عس', 'عس', '', '', '', 'مفرد', 'DnN', '', '', '"عِسَاسٌ:أَعْسَاسٌ"', '', 'R', '', '', '', '', '', '', '".: قَدَحٌ كَبِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12200, 'عِسَاسٌ', 'عساس', 'جامد', '', 'عساس', 'عسس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
