INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12202, 'مِعْسَفَةٌ', 'معسفة', 'جامد', 'عسف', 'معسفة', 'معسفة', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاسِفُ"', '', 'R', '', '', '', '', '', '', '". ""مِعْسَفَةُ البَيْـتِ"":عَصاً فِي رَأْسِهَا رِيشٌ أَوْ خُيُوطُ ثَوْبٍ أَوْ سَعَفٍ تُنَظِّفُ بِهَا جُدْرَانُ البَيْتِ وَسُقُوفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12203, 'مَعَاسِفُ', 'معاسف', 'جامد', '', 'معاسف', 'معسف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12204, 'عَسْقَلٌ', 'عسقل', 'جامد', 'عسقل', 'عسقل', 'عسقل', '', '', '', 'مفرد', 'DnN', '', '', '"عَسَاقِلُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". : جُزْءٌ مِنْ سَاقٍ نَبَاتِيَّةٍ أَوْ مِنْ جِذْرٍ نَبَاتِيٍّ يَحْتَوِي عَلَى مَوَادَّ غِذَائِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12205, 'عَسَاقِلُ', 'عساقل', 'جامد', '', 'عساقل', 'عسقل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12206, 'عَسْكَرٌ', 'عسكر', 'جامد', 'عسكر', 'عسكر', 'عسكر', '', '', '', 'مفرد', 'DnN', '', '', '"عَسَاكِرُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""دَخَلَ العَسْكَرُ الْمَدِينَةَ"" : الْجَيْشُ، الْجُنْدُ. 2.""عَسْكَرٌ مِنَ الرِّجَالِ"" : عَدَدٌ كَثِيرٌ مِنْهُمْ. ""عَسْكَرٌ مِنْ خَيْلٍ"". 3.""عَسْكَرُ اللَّيْلِ"" : ظُلْمَتُهُ. 4.""اِنْجَلَتْ عَنْهُ عَسَاكِرُ الْهُمُومِ"" : زَالَ هَمُّهُ. 5.""شَهِدَ العَسْكَرَيْنِ"" : عَرَفَةَ وَمِنـىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12207, 'عَسَاكِرُ', 'عساكر', 'جامد', '', 'عساكر', 'عسكر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12208, 'هُوِيَّةٌ', 'هوية', 'جامد', '', 'هوية', 'هة', 'مَنْسُوبٌ إِلَى هُوَ', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"هُوِيَّةٌ-هُوِيَّةٌ (مَنْسُوبٌ إِلَى هُوَ). 1.""هُوِيَّةُ الْإِنْسَانِ"": حَقِيقَتُهُ الْمُطْلَقَةُ وَصِفَاتُهُ الْجَوْهَرِيَّةُ. 2.""الْهُوِيَّةُ الْوَطَنِيَّةُ"" : مَعَالِمُهَا وَخَصَائِصُهَا الْمُمَيَّزَةُ وَأَصَالَتُهَا. 3.""بِطَاقَةُ الْهُوِيَّةِ"" : الْبِطَاقَةُ الشَّخْصِيَّةُ تَحْمِلُ اسْمَ الشَّخْصِ وَتَارِيخَ مِيلاَدِهِ وَعَمَلَهُ وَجِنْسِيَّتَهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12209, 'عَسَلٌ', 'عسل', 'جامد', 'عسل', 'عسل', 'عسل', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْسَالٌ:عُسُولٌ(مذ:مؤ)"', '', 'R', '', '', '', '', '', '', '". ""وَضَعَ العَسَلَ عَلَى الرَّغِيفِ"" : الْمَادَّةُ اللُّعَابِيَّةُ الَّتِي يُنْتِجُهَا النَّحْلُ. ""مَنْ كَانَ يَكْرَهُ أَنْ يَلْقَى مَنِيَّتَهُ*فَالْمَوْتُ أَشْهَى إِلَى قَلْبِي مِنَ العَسَلِ (البهلول الخارجي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12210, 'أَعْسَالٌ', 'أعسال', 'جامد', '', 'ءعسال', 'عسل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
