INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12216, 'عُشْبٌ', 'عشب', 'جامد', 'عشب', 'عشب', 'عشب', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْشَابٌوَاحِدَتُهُعُشْبَةٌ"', '', '', '', '', '', '', '', '', '". ""نَبَتَ العُشْبُ مَعَ بِدَايَةِ الرَّبِيعِ"" : الكَلأُ الرَّطْبُ الأَخْضَرُ، مَادَّةٌ غِذَائِيَّةٌ لِلأَغْنَامِ وَالبَقَرِ."', '');
