INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12219, 'عَاشِرٌ', 'عاشر', 'جامد', 'عشر', 'عاشر', 'عشر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"عُشُرٌ:عَوَاشِرُ"', '', '', '', '', '', '', '', '', '". 1.""اِحْتَلَّ الصَّفَ الْعَاشِرَ"" : جَاءَ بَعْدَ التَّاسِعِ. 2.""طِفْلَةٌ فِي الْعَاشِرَةِ مِنْ عُمْرِهَا"" : أَيْ بَلَغَتْ عَشْرَ سَنَوَاتٍ. 3.""عَوَاشِرُ الطَّيْرِ"" : قَوَادِمُ رِيشِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12220, 'عُشُرٌ', 'عشر', 'جامد', '', 'عشر', 'عشر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12221, 'عَوَاشِرُ', 'عواشر', 'جامد', '', 'عواشر', 'عشر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12222, 'عَاشُورَاءُ', 'عاشوراء', 'جامد', 'عشر', 'عاشوراء', 'عشر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rz', '', 'N', 'N', 'N', 'O', '', '"عَاشُورَاءُ-عَاشُورَاءُ [ع ش ر]. ""يَحْتَفِلُونَ بِعِيدِ عَاشُورَاءَ"" : الْيَوْمُ الْعَاشِرُ مِنْ شَهْرِ مُحَرَّمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12223, 'عُشَارَةٌ', 'عشارة', 'جامد', 'عشر', 'عشارة', 'عشرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. : قِطْعَةٌ مِنْ كُلِّ شَيْءٍ. 2.""صَارَ القَوْمُ عُشَارَاتٍ"" : مُتَفَرِّقِينَ فِي كُلِّ مَكَانٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12224, 'عُشَارٌ', 'عشار', 'جامد', 'عشر', 'عشار', 'عشر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'N', '', '"عُشَارٌ-عُشَارٌ [ع ش ر]. ""جَاءوا عُشَارَ"" : عَشَرَةً عَشَرَةً. للمُذَكَّرِ وَالْمُؤَنَّثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12225, 'شَفْعِيَّةٌ', 'شفعية', 'جامد', 'شفع', 'شفعية', 'شفعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"شَفْعِيَّةٌ-شَفْعِيَّةٌ [ش ف ع]. 1.""شَفْعِيَّةُ الأَظْلاَفِ"" : زَوْجِيَّةُ الأَظْلاَفِ الْمُتَقَابِلَةِ. 2.""شَفْعِيَّةُ التَّرْكِيبِ"" : صِفَةٌ لِلأَوْرَاقِ الْمُرَكَّبَةِ الْمُنْتَهِيَةِ بِوَرَقَتَيْنِ مُتَقَابِلَتَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12226, 'عَشْرَاءُ', 'عشراء', 'جامد', 'عشر', 'عشراء', 'عشر', '', '', '', 'مفرد', '', '', '', '"عِشَارٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". "" نَاقَةٌ عَشْرَاءُ"" : أَيْ مَضَى عَلَى حَمْلِهَا عَشَرَةُ أَشْهُرٍ.التكوير آية 4 وَإِذَا العِشَارُ عُطِّلَتْ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12227, 'عِشَارٌ', 'عشار', 'جامد', '', 'عشار', 'عشر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12228, 'عِشْرَةٌ', 'عشرة', 'جامد', 'عشر', 'عشرة', 'عشرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عِشْرَةٌ-عِشْرَةٌ [ع ش ر]. ""دَامَتْ عِشْرَتُهُمَا مُدَّةً طَوِيلَةً"" : صُحْبَتُهُمَا، مُعَاشَرَتُهُمَا، مُخَالَطَتُهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12229, 'عَشْرٌ', 'عشر', 'جامد', 'عشر', 'عشر', 'عشر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"عَشَرَاتٌ"', '', 'R', '', 'N', 'O', 'N', 'O', '', '". ""كَانَ يَحْضُرُ عَشَاءهُ مِنْ خَمْسَةٍ إِلَى سِتَّةٍ إِلَى عَشَرَةٍ"" : عَدَدٌ للمُذَكَّرِ مِنْ 1 إِلَى 10. ""عَشْرُ نِسَاءٍ كُنَّ حَاضِرَاتٍ"" : تُحْذَفُ التَّاءُ إِذَا دَخَلَ العَدَدُ عَلَى اِسْمٍ مُؤَنَّثٍ. ""أَخَذْتُ مِنْهُ خَمْسَةَ عَشَرَ دِرْهَماً"" : يُلاَحَظُ أَنَّ الْجُزْءَ الأَوَّلَ مِنَ العَدَدِ جَاءَ مُؤَنَّثاً بِخِلاَفِ الْجُزْءِ الثَّانِي الَّذِي جَاءَ مُذَكَّراً بِعَكْسِ الْمِثَالِ التَّالِي: ""فِي الفَصْلِ خَمْسَ عَشْرَةَ تِلْمِيذَةً"" : الْجُزْءُ الأَوَّلُ مِنَ العَدَدِ جَاءَ مُذَكَّراً بِخِلاَفِ الْجُزْءِ الثَّانِي الَّذِي جَاءَ مُؤَنَّثاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12230, 'عَشَرَاتٌ', 'عشرات', 'جامد', '', 'عشرات', 'عشرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12231, 'عَشِيرَةٌ', 'عشيرة', 'جامد', 'عشر', 'عشيرة', 'عشرة', '', '', '', 'مفرد', 'DnN', '', '', '"عَشَائِرُ"', '', 'R', '', '', '', '', '', '', '". ""عَشِيرَةُ الرَّجُلِ"" : بَنُو أَبِيهِ الأَقْرَبُونَ وَقَبِيلَتُهُ.الشعراء آية 214 وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12232, 'عَشَائِرُ', 'عشائر', 'جامد', '', 'عشاءر', 'عشر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12233, 'مَعْشَرٌ', 'معشر', 'جامد', 'عشر', 'معشر', 'معشر', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاشِرُ"', '', 'R', '', '', '', '', '', '', '". 1. ""يَا مَعْشَرَ النَّاسِ"" : أَيَّتُهَا الجَمَاعَةُ.الأنعام آية 130 يَا مَعْشَرَ الجِنِّ وَالإِنْسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِنْكُمْ (قرآن). 2.""مَعْشَرُ الرَّجُلِ"" : أَهْلُهُ. 3.""لَطِيفُ الْمَعْشَرِ"" : لَطِيفُ الرُّفْقَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12234, 'مَعَاشِرُ', 'معاشر', 'جامد', '', 'معاشر', 'معشر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12235, 'عُشَّةٌ', 'عشة', 'جامد', 'عشش', 'عشة', 'عشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". : كُوخٌ مِنْ خَشَبٍ يُقَامُ عَلَى شَاطِئِ البَحْرِ كَمَا يُطْلَقُ عَلَى الكُوخِ بِالبَادِيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12236, 'عُشٌّ', 'عش', 'جامد', 'عشش', 'عش', 'عش', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْشَاشٌ:عِشَاشٌ:عُشُوشٌ"', '', 'R', '', '', '', '', '', '', '". ""يَقْبَعُ الطَّائِرُ فِي عُشِّهِ"" : عَشٌّ، مَوْقِعُ الطَّائِرِ الْمُكَوَّنُ مِنْ عِيدَانِ الشَّجَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12237, 'أَعْشَاشٌ', 'أعشاش', 'جامد', '', 'ءعشاش', 'عشش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12238, 'عِشَاشٌ', 'عشاش', 'جامد', '', 'عشاش', 'عشش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12239, 'عُشُوشٌ', 'عشوش', 'جامد', '', 'عشوش', 'عشش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12240, 'تَعْشِيقٌ', 'تعشيق', 'جامد', 'عشق', 'تعشيق', 'تعشق', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"تَعْشِيقٌ-تَعْشِيقٌ، ةٌ [ع ش ق]. 1.""تَعْشِيقُ الخَشَبِ"" : تَرْكِيبُ أَجْزَاءِ الخَشَبِ وَتَثْبِيتُهَا وَاحِداً فِي الآخَرِ بِوَاسِطَةِ تَشْكِيلِ مَوَاضِيعِ التَّثْبِيتِ لِتَتَزَاوَجَ بِإِحْكَامٍ. 2.""تَعْشِيقَةُ خَشَبٍ"" : كُلُّ ازْدِوَاجٍ يَدْخُلُ فِيهِ جُزْءٌ مِنَ الخَشَبِ فِي آخَرَ، وَهُوَ أَنْوَاعٌ : أ.""تَعْشِيقَةُ ذَيْلِ الزَّاوِيَةِ"" : تَوْصِيلُ الجُزْءَيْنِ الْمُسَطَّحَيْنِ لِتَكْوِينِ رُكْنٍ. ب.""تَعْشِيقَةُ طَرَفٍ لِطَرَفٍ"" : تَوْصِيلُ الجُزْءيْنِ بِتَلاَمُسِ الطَّرَفَيْنِ دُونَ دُخُولٍ. ج.""تَعْشِيقَةُ النِّصْفِ عَلَى النِّصْفِ"" : تَوْصِيلُ الجُزْءيْنِ بِتَعَارُضٍ كَالصَّلِيبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12241, 'عَشَاءٌ', 'عشاء', 'جامد', 'عشو', 'عشاء', 'عش', '', '', '', 'مفرد', 'Dz', '', '', '"أَعْشِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '". ""تَنَاوَلَ العَشَاءَ مَعَ أَوْلاَدِهِ"" : طَعَامُ العَشِيِّ، طَعَامُ اللَّيْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12242, 'أَعْشِيَةٌ', 'أعشية', 'جامد', '', 'ءعشية', 'عشة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12243, 'عِشَاءٌ', 'عشاء', 'جامد', 'عشو', 'عشاء', 'عش', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"عِشَاءٌ-عِشَاءٌ [ع ش و]. 1.""أَقْبَلَ العِشَاءُ"" : أَوَّلُ اللَّيْلِ، بِدَايَةُ العَتَمَةِ مِنَ الْمَغْرِبِ إِلَى آخِرِ اللَّيْلِ. 2.""أَدَّى صَلاَةَ العِشَاءِ"" : الصَّلاَةُ الَّتِي تَلِي الْمَغْرِبَ. 3.""العِشَاءانِ"" : الْمَغْرِبُ واَلعِشَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12244, 'عَشَاوَةٌ', 'عشاوة', 'جامد', 'عشو', 'عشاوة', 'عشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عَشَاوَةٌ-عَشَاوَةٌ [ع ش و]. ""بِعَيْنَيْهِ عَشَاوَةٌ"" : سُوءُ البَصَرِ بِاللَّيْلِ، أَوْ بِالنَّهَارِ أَيْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12245, 'عَشِيَّةٌ', 'عشية', 'جامد', 'عشو', 'عشية', 'عشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":عَشَايَا"', '', '', '', '', '', '', '', '', '". ن. عَشِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12246, 'عَشَايَا', 'عشايا', 'جامد', '', 'عشايا', 'عش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12247, 'عَشِيٌّ', 'عشي', 'جامد', 'عشو', 'عشي', 'عش', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عَشِيٌّ-عَشِيٌّ [ع ش و]. 1.""سَيَقْضِي العَشِيَّ بِالنَّادِي"" : مِنْ زَوَالِ الشَّمْسِ إِلَى الْمَغْرِبِ أَوْ مِنَ الْمَغْرِبِ إِلَى العَتَمَةِ. ""شَمْسُ العَشِيِّ غَرَّبَتْ وَاسْتَغْرَبَتْ"" (موشح). 2.""صَلاَتَا العَشِيِّ"" : الظُّهْرُ وَالعَصْرُ. 3.""جَمَلٌ عَشِيٌّ"" : يُطِيلُ الرَّعْيَ لَيْلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12248, 'عِصَابَةٌ', 'عصابة', 'جامد', 'عصب', 'عصابة', 'عصبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":عَصَائِبُ"', '', 'R', '', '', '', '', '', '', '". 1.""وَضَعَ عِصَابَةً عَلَى رَأسِهِ"" : العِمَامَةُ. 2.""لَفَّ الْجُرْحَ بِعِصَابَةٍ"" : مَا يُعْصَبُ بِهِ مِنْ ثَوْبٍ أَوْ مِنْدِيلٍ وَنَحْوِهِ. 3.""عِصَابَةُ الْخَيْلِ"" : مَجْمُوعَةُ الْخَيْلِ. ""عِصَابَةُ طَيْرٍ"". 4.""أُلْقِيَ القَبْضُ عَلَى زَعِيمِ العِصَابَةِ"" : مَنْ يَتَرَأَّسُ مَجْمُوعَةً مِنَ الْمُجْرِمِينَ. 5.""حَرْبُ العِصَابَاتِ"" : حَرْبٌ تُنَظِّمُهَا جَمَاعَاتٌ غَيْرُ نِظَامِيَّةٍ ضِدَّ الاحْتِلاَلِ أَوِ السُّلْطَةِ الْمَرْكَزِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12249, 'عَصَائِبُ', 'عصائب', 'جامد', '', 'عصاءب', 'عصب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12250, 'عُصَابٌ', 'عصاب', 'جامد', 'عصب', 'عصاب', 'عصب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عِصَابٌ-عِصَابٌ [ع ص ب]. : مَا يُرْبَطُ بِهِ الرَّأْسُ مِنْ مِنْدِيلٍ وَنَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12251, 'عِصَابٌ', 'عصاب', 'جامد', 'عصب', 'عصاب', 'عصب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُصَابٌ-عُصَابٌ [ع ص ب]. ""أُصِيبَ بِعُصَابٍ"" : بِاضْطِرَابٍ نَفْسِيٍّ أَوْ عَقْلِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12252, 'عَصَبَةٌ', 'عصبة', 'جامد', 'عصب', 'عصبة', 'عصبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'Rp', '', '', '', '', '', '', '"عَصَبَةٌ-عَصَبَةٌ [ع ص ب]. 1.""عَصَبَةُ الرَّجُلِ"" : بَنُوهُ وَقَرَابَتُهُ لأَبِيهِ أَوْ قَوْمِهِ. 2.""العَصَبَةُ فِي الْمِيرَاثِ"" : مَنْ لَيْسَتْ لَهُ فَرِيضَةٌ مُسَمَّاةٌ فِي الْمِيرَاثِ، وَإِنَّمَا يَأْخُذُ مَا أَبْقَى ذَوُو الفُرُوضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12253, 'عُصْبَةٌ', 'عصبة', 'جامد', 'عصب', 'عصبة', 'عصبة', '', '', '', 'مفرد', 'DnN', '', '', '"عُصَبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""عُصْبَةُ الْخَيْلِ"" : جَمَاعَةُ الْخَيْلِ. ""عُصْبَةُ الطَّيْرِ"". 2.""عُصْبَةُ حُقُوقِ الإِنْسَانِ"" : جَمْعِيَّةٌ، جَمَاعَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12254, 'عُصَبٌ', 'عصب', 'جامد', '', 'عصب', 'عصب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12255, 'إعْصَارٌ', 'إعصار', 'جامد', 'عصر', 'ءعصار', 'إعصر', '', '', '', 'مفرد', 'DnN', '', '', '"أعَاصِيرُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1. ""إعْصَارٌ شَدِيدٌ"" : رِيَاحٌ مُرْتَفِعَةٌ قَوِيَّةٌ تَنْثُرُ التُّرَابَ مَعَهَا وَتُكَوِّنُ مِنْهُ دَوَائِرَ. 2.""تعَرَّضَتِ البَاخِرَةُ لإِعْصَارٍ جَارفٍ"" : اِرْتِفَاعُ مِياهِ البَحْرِ وَاسْتِدَارَتُها مُكَوِّنَةً أمْوَاجاً عَالِيَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12256, 'أعَاصِيرُ', 'أعاصير', 'جامد', '', 'ءعاصير', 'عصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12257, 'عَصَّارَةٌ', 'عصارة', 'جامد', 'عصر', 'عصارة', 'عصرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عَصَّارَةٌ-عَصَّارَةٌ [ع ص ر]. : آلَةٌ لِعَصْرِ الفَوَاكِهِ وَنَحْوِها واسْتِخْرَاجِ عُصَارَتِها أَوعَصِيرِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12258, 'عُصَارَةٌ', 'عصارة', 'جامد', 'عصر', 'عصارة', 'عصرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". 1.""إِنَّهَا عُصَارَةُ فِكْرِهِ"": خُلاَصَتُهُ، زُبْدَتُهُ. 2.""أَخَذَ عُصَارَةَ الأَرْضِ"" : غَلَّتَهَا. 3.""هُوَ كَرِيمُ العُصَارَةِ"" : جَوَادٌ كَرِيمٌ عِنْدَ الْمَسْأَلَةِ. 4.: نُفَايَةُ مَا عُصِرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12259, 'عُصَارٌ', 'عصار', 'جامد', 'عصر', 'عصار', 'عصر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُصَارٌ-عُصَارٌ [ع ص ر]. ""عُصَارُ الشَّيْءِ"" : مَا يُسْتَخْدَمُ مِنْ مَادَّةٍ إِذَا عُصِرَتْ. ""عُصَارُ الزَّيْتُونِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12260, 'عَصِيرٌ', 'عصير', 'جامد', 'عصر', 'عصير', 'عصر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَصِيرٌ-عَصِيرٌ [ع ص ر]. ""عَصِيرُ البُرْتُقَالِ"" : الْمَاءُ الَّذِي يُعْصَرُ مِنَ البُرْتُقَالِ أَوْ نَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12261, 'مِعْصَارٌ', 'معصار', 'جامد', 'عصر', 'معصار', 'معصر', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاصِيرُ"', '', 'R', '', '', '', '', '', '', '".: كُلُّ أَدَاةٍ أَوْ آلَةٍ تَعْصِرُ مَا يُوضَعُ فِيهَا حَتَّى يَتَحَلَّبَ مَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12262, 'مَعَاصِيرُ', 'معاصير', 'جامد', '', 'معاصير', 'معصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12263, 'مُعْصِرَاتٌ', 'معصرات', 'جامد', 'عصر', 'معصرات', 'معصرت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"مُعْصِرَاتٌ-مُعْصِرَاتٌ [ع ص ر]. ""سُحُبٌ مُعْصِرَاتٌ"" : سُحُبٌ تَعْتَصِرُهَا الرِّيَاحُ بِالْمَطَرِ.النبأ آية 14 وأَنْزَلْنا مِن المُعْصِراتِ ماءً ثَجَّاجاً (قرآن) ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12264, 'مَعْصَرَةٌ', 'معصرة', 'جامد', 'عصر', 'معصرة', 'معصرة', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاصِرُ"', '', 'R', '', '', '', '', '', '', '". ""مَعْصَرَةُ الزَّيْتِ"" : مَكَانُ عَصْرِ الزَّيْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12265, 'مَعَاصِرُ', 'معاصر', 'جامد', '', 'معاصر', 'معصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12266, 'مِعْصَرَةٌ', 'معصرة', 'جامد', 'عصر', 'معصرة', 'معصرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مِعْصَرَةٌ-مِعْصَرَةٌ [ع ص ر]. ""مِعْصَرَةُ الزَّيْتُونِ"" : آلَةُ العَصْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12267, 'عَصِيدَةٌ', 'عصيدة', 'جامد', 'عصد', 'عصيدة', 'عصدة', '', '', '', 'مفرد', 'DnN', '', '', '"عَصَائِدُ"', '', 'R', '', '', '', '', '', '', '". ""هَيَّأَتِ العَصِيدَةَ"" : طَبِيخٌ مِنْ طَحِينٍ يُعْقَدُ بِالسَّمْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12268, 'عَصَائِدُ', 'عصائد', 'جامد', '', 'عصاءد', 'عصد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12269, 'مِعْصَرٌ', 'معصر', 'جامد', 'عصر', 'معصر', 'معصر', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاصِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِعْصَرُ الفَوَاكِهِ"" : مَا يُعْصَرُ بِهَا. ""مِعْصَرُ الزَّيْتُونِ"". 2.""مِعْصَرُ الثِّيَابِ"" : آلَةٌ لِعَصْرِ، الثِّيَابِ وَتَنْشِيفِها وَتَجْفِيفِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12270, 'مَعَاصِرُ', 'معاصر', 'جامد', '', 'معاصر', 'معصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12271, 'عَصْرٌ', 'عصر', 'جامد', '', 'عصر', 'عصر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"عُصُرٌ"', '', 'Rp', '', '', '', '', '', '', '"ج: عُصُر. 1.""قَضَى العَصْرَ فِي الْحَدِيقَةِ"" : الوَقْتُ فِي آخِرِ النَّهَارِ إِلَى احْمِرَارِ الشَّمْسِ. 2.""صَلاَةُ العَصْرِ"" : الصَّلاَةُ الَّتِي يُؤَدِّيهَا الْمُسْلِمُ فِي آخِرِ فَتْرَةِ النَّهَارِ. 3.""العَصْرَانِ"": الغَدَاةُ وَالعَشِيُّ وَاللَّيْلُ وَالنَّهَارُ. 4.""اِزْدَهَرَتِ العُلُومُ فِي عَصْرِهِ"": زَمَنٌ تَارِيِخيٌّ يُنْسَبُ إِلَى مَلِكٍ أَوْ دَوْلَةٍ أَوْ صِفَةٍ. ""العَصْرُ الْحَجَرِيُّ"" ""العَصْرُ القَدِيمُ"" ""العَصْرُ العَبَّاسِيُّ"" ‏ ""عَصْرُ الْمُرَابِطِينَ"" ""العَصْرُ الْحَدِيثُ"". 5.""نَعِيشُ فِي عَصْرِ الْمَعْلُومَاتِيَّةِ"" : فِي زَمَنِ ..."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12272, 'عُصُرٌ', 'عصر', 'جامد', '', 'عصر', 'عصر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12273, 'عُصْعُصٌ', 'عصعص', 'جامد', 'عصعص', 'عصعص', 'عصعص', '', '', '', 'مفرد', 'DnN', '', '', '"عَصَاعِصُ"', '', 'R', '', '', '', '', '', '', '". : عَظْمُ الذَّنَبِ فِي نِهَايَةِ العَمُودِ الفِقَرِيِّ. وَيَتَكَوَّنُ مِنِ الْتِحَامِ ثَلاَثِ فِقْرَاتٍ أَوْ أَرْبَعٍ."', '');
