INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12275, 'عَصْعُوصٌ', 'عصعوص', 'جامد', 'عصعص', 'عصعوص', 'عصعص', '', '', '', 'مفرد', 'DnN', '', '', '"عَصَاعِيصُ"', '', 'R', '', '', '', '', '', '', '". ن. عُصْعُصٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12276, 'عَصَاعِيصُ', 'عصاعيص', 'جامد', '', 'عصاعيص', 'عصعص', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12277, 'عَصِيفَةٌ', 'عصيفة', 'جامد', 'عصف', 'عصيفة', 'عصفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"عَصِيفَةٌ-عَصِيفَةٌ [ع ص ف]. 1.""عَصِيفَةُ السُّنْبُلِ"" : الوَرَقُ الْمُجْتَمِعُ حَوْلَهُ. 2.""عَصِيفَةُ الثَّمَرَةِ"" : الوَرَقُ الْمُنْفَتِحُ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12278, 'عَصْفُورٌ', 'عصفور', 'جامد', 'عصفر', 'عصفور', 'عصفر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"عَصَافِيرُ"', '', 'R', '', '', '', '', '', '', '". 1. : طَائِرٌ مِنْ جِنْسِ الطُّيُورِ الْجَوَاثِمِ مَخْرُوطَاتِ الْمَنَاقِيرِ. 2.""أَصَابَ عُصْفُورَيْنِ بِحَجَرٍ وَاحِدٍ"" (مثل) : حَصَلَ عَلَى عَمَلَيْنِ بِمَجْهُودٍ وَاحِدٍ. 3.""عُصْفُورٌ فِي اليَدِ خَيْرٌ مِنْ عَصَافِيرَ فِي السَّمَاءِ"" (مثل) : مَا فِي اليَدِ أَحْسَنُ مِمَّا هُوَ لَيْسَ فِي مِلْكِكَ. 4.""غَنَّتْ عَصَافِيرُ بَطْنِهِ"" : جَاعَ. 5.""طَارَتْ عَصَافِيرُ رَأْسِهِ"" : تَكَبَّرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12279, 'عَصَافِيرُ', 'عصافير', 'جامد', '', 'عصافير', 'عصفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12280, 'عَصَبِيَّةٌ', 'عصبية', 'جامد', 'عصب', 'عصبية', 'عصبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عَصَبِيَّةٌ-عَصَبِيَّةٌ [ع ص ب]. 1.""وَجَدْتُهُ فِي حَالَةٍ عَصَبِيَّةٍ شَدِيدَةٍ"" : فَقْدُ السَّيْطَرَةِ عَلَى الأَعْصَابِ. 2.""ضَحِكَ ضَحْكَةً عَصَبِيَّةً"" : مُتَشَنِّجَةً. 3.""عُرِفَ بِعَصَبِيَّتِهِ لأَصْلِهِ"" : شِدَّةُ الارْتِبَاطِ بِأَهْلِهِ وَنُصْرَتُهُمْ وَالتَّعَصُّبُ لَهْم وَلِتَقَالِيدهِمْ وَمَبَادِئِهِم. ""العَصَبِيَّةُ القَبَلِيَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12281, 'عَاصِمَةٌ', 'عاصمة', 'جامد', 'عصم', 'عاصمة', 'عصمة', '', '', '', 'مفرد', 'DnN', '', '', '"عَوَاصِمُ"', '', 'R', '', '', '', '', '', '', '". ""الرِّبَاطُ هِيَ عَاصِمَةُ الْمَمْلَكَةِ الْمَغْرِبِيَّةِ"" : الْمَدِينَةُ الإِدَارِيَّةُ، قَاعِدَةُ السُّلْطَةِ السِّيَاسِيَّةِ لِلْبِلاَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12282, 'عَوَاصِمُ', 'عواصم', 'جامد', '', 'عواصم', 'عصم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12283, 'عَاصِمٌ', 'عاصم', 'جامد', 'عصم', 'عاصم', 'عصم', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عَاصِمٌ-عَاصِمٌ [ع ص م]. 1.""عَاصِمُ الْجَمَاعَةِ"" : حَامِيهَا، مَانِعُهَا. 2. : اِسْمُ عَلَمٍ للمُذَكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12284, 'عِصَامٌ', 'عصام', 'جامد', 'عصم', 'عصام', 'عصم', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْصِمَةٌ:عُصُمٌ"', '', 'Rp', '', 'N', 'O', 'O', 'O', '', '". 1.""عِصَامُ الإِنَاءِ"" : عُرْوَتُهُ يُعَلَّقُ بِهَا. 2.""عِصَامُ القِرْبَةِ"" : حَبْلٌ تُشَدُّ بِهِ وَتُحْمَلُ. 3. : اِسْمُ عَلَمٍ. ""مَا وَرَاءكَ يَا عِصَامُ "" (مثل) : يُضْرَبُ فِي الاسْتِخْبَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12285, 'أَعْصِمَةٌ', 'أعصمة', 'جامد', '', 'ءعصمة', 'عصمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
