INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12287, 'عِصْمَةٌ', 'عصمة', 'جامد', 'عصم', 'عصمة', 'عصمة', '', '', '', 'مفرد', 'DnN', '', '', '"عِصَمٌ:أَعْصُمٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هُوَ فِي عِصْمَةٍ"" : مَلَكَةُ اجْتِنَابِ فِعْلِ الْمَعْصِيَةِ وَالْمَيْلِ إِلَيْهَا مَعَ القُدْرَةِ عَلَيْهِ. 2.""عِصْمَةُ الزَّوْجِيَّةِ"" : رِبَاطُ الزَّوْجِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12288, 'عِصَمٌ', 'عصم', 'جامد', '', 'عصم', 'عصم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
