INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12290, 'عُصْمٌ', 'عصم', 'جامد', 'عصم', 'عصم', 'عصم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عُصْمٌ-عُصْمٌ [ع ص م]. 1.: بَقِيَّةُ كُلِّ شَيْءٍ. 2.: أَثَرُ كُلِّ شَيْءٍ مِنْ خِضَابٍ أَوْ قَطِرَان أَوْ نَحْوِهِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12291, 'مِعْصَمٌ', 'معصم', 'جامد', 'عصم', 'معصم', 'معصم', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاصِمُ"', '', 'R', '', '', '', '', '', '', '". ""مِعْصَمُ السِّوَارِ"" : مَوْضِعُهُ مِنَ السَّاعِدِ. ""مَا أَجْمَلَ السِّوَارَ فِي مِعْصَمِهَا"" l ""لاَ يُحِبُّ القُيُودَ فِي مِعْصَمِهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12292, 'مَعَاصِمُ', 'معاصم', 'جامد', '', 'معاصم', 'معصم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12293, 'عَصًا', 'عصا', 'جامد', 'عصو', 'عصا', 'عص', '', '', '', 'مفرد', 'Dw', '', '', '"عِصِيٌّ(مؤ)"', '', 'Rw', '', '', '', '', '', '', '". 1. ""عَصاً مِنْ خَشَبٍ"" : عودٌ. ""اِتَّخَذَ مِنْ أَغْصَانِ الشَّجَرِ عِصِيّاً""طه آية 18قَالَ هِيَ عَصَايَ أَتَوَكَّأُ عَلَيْهَا وَأَهُشُّ بِهَا عَلَى غَنَمِي (قرآن). 2.""شَقَّ عَصَا الطَّاعَةِ"" : خَالَفَ أَهْلَهُ وَتَمَرَّدَ عَلَيْهِمْ. 3.""رَجُلٌ لَيِّنُ العَصَا"" : رَقِيقٌ لَيِّنٌ حَسَنُ السِّيَاسَةِ. 4.""رَجُلٌ شَدِيدُ العَصَا"": صَلْبٌ، عَنِيفٌ. 5.""أَلْقَى الْمُسَافِرُ العَصَا"" : وَصَلَ الْمَكَانَ الْمَقْصُودَ، أَقَامَ. ""أَلْقَى عَصَا التَّرْحَالِ"". 6.""اِنْشَقَّتِ العَصَا"" : وَقَعَ الْخِلاَفُ. 7.""قَرَعَ لَهُ العَصَا"" : نَبَّهَهُ، فَطَّنَهُ. 8.""رَأْسُ العَصَا"" : رَأْسٌ صَغِيرٌ. 9.""نَشَرَ لَهُ العَصَا"" : أَظْهَرَ لَهُ مَا فِي ضَمِيرِهِ. 10.""رَفَعَ عَصَاهُ"" : سَارَ. 11.""هُمْ عَبِيدُ العَصَا"" : مُسْتَذَلُّونَ، أَيْ أَذِلاَّءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12294, 'عِصِيٌّ', 'عصي', 'جامد', '', 'عصي', 'عص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12295, 'عُصَيَّةٌ', 'عصية', 'جامد', 'عصي', 'عصية', 'عصة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عُصَيَّةٌ-عُصَيَّةٌ [ع ص ي]. : عَصاً صَغِيرَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12296, 'عُضْوٌ', 'عضو', 'جامد', 'عضو', 'عضو', 'عض', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْضَاءٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اليَدُ عُضْوٌ مِنْ أَعْضَاءِ الْجِسْمِ"" : كُلُّ جُزْءٍ مِنْ مُكَوِّنَاتِ الْجِسْمِ كَالرِّجْلِ وَالأُذُنِ وَالرَّأْسِ. 2.""أَصْبَحَ عُضْواً فِي النَّادِي"" : أَحَدُ أَفْرَادِ النَّادِي. ""حَضَرَ الاجْتِمَاعَ كُلُّ أَعْضَاءِ الْجَمْعِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12297, 'أَعْضَاءٌ', 'أعضاء', 'جامد', '', 'ءعضاء', 'عض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12298, 'مَعْصِيَةٌ', 'معصية', 'جامد', 'عصي', 'معصية', 'معصة', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاصٍ:الْمَعَاصِي"', '', '', '', '', '', '', '', '', '". ""تَضَرَّعَ إِلَى اللهِ لِيَغْفِرَ لَهُ مَعْصِيَتَهُ"" : زَلَّتَهُ، خَطِيئَتَهُ. ""الْحُبُّ يَسْتُرُ جَمِيعَ الْمَعَاصِي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12299, 'مَعَاصِي', 'معاصي', 'جامد', '', 'معاصي', 'معص', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12300, 'عِضَادَةٌ', 'عضادة', 'جامد', 'عضد', 'عضادة', 'عضدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عِضَادَةٌ-عِضَادَةٌ [ع ض د]. 1.""عِضَادَةُ الطَّرِيقِ"" : نَاحِيَتُهُ. 2.""عِضَادَتَا البَابِ"" : خَشَبَتَانِ مَنْصُوبَتَانِ مِنْ جَانِبَيْهِ. 3.""هُوَ عِضَادَةٌ لَهُ"" : مُرَافِقُهُ، مُعَاوِنُهُ. ""عِضَادَتا الرَّجُلِ"". 4.""عِضَادَتَا الْجُمْلَةِ"" : حَاصِرَتَا <...>."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12301, 'عَضُدٌ', 'عضد', 'جامد', 'عضد', 'عضد', 'عضد', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْضَادٌ:أَعْضُدٌ"', '', 'R', '', '', '', '', '', '', '". 1.""عَضُدُ الإِنْسَانِ"" : الذِّرَاعُ مِنْ مَرْفِقٍ إِلَى الكَتِفِ. 2.""هُوَ عَضُدِي"" : نَاصِرِي وَمُعِينِي وَقُوَّتِي. ""أَصْبَحَتْ مِنْ بَعْدهِ لاَ تَمْلِكُ مَالاً وَلا عَضُداً"". (م. ل. المنفلوطي). 3.""يَشُدُّ عَضُدَهُ فِي كُلِّ آنٍ"": يُقَوِّيهِ، يُثْبِتُ مَكَانَتَهُ. 4.""يَفُتُّ فِي عَضُدِهِ"" : يُضْعِفُ قُوَّتَهُ. 5.""عَضُدُ الطَّرِيقِ"" : نَاحِيَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12302, 'أَعْضَادٌ', 'أعضاد', 'جامد', '', 'ءعضاد', 'عضد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12303, 'أَعْضُدٌ', 'أعضد', 'جامد', '', 'ءعضد', 'عضد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12304, 'عَضَاضٌ', 'عضاض', 'جامد', 'عضض', 'عضاض', 'عضض', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عَضَاضٌ-عَضَاضٌ [ع ض ض]. 1.""عَضَاضُ الشَّيْءِ"" : مَا يُعَضُّ عَلَيْهِ وَيُؤْكَلُ. 2.""عَضَاضُ الشَّجَرِ"": مَا غَلُظَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12305, 'مُعْضِلَةٌ', 'معضلة', 'جامد', 'عضل', 'معضلة', 'معضلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""اِمْرَأَةٌ مُعْضِلَةٌ"" : وِلاَدَتُهَا صَعْبَةٌ وَعَسِيرَةٌ. 2.""بَعْدَ مَسِيرٍ شَاقٍّ وَجَدَ نَفْسَهُ فِي مُعْضِلَةٍ"" : فِي طَرِيقٍ ضَيِّقَةِ الْمَخَارِجِ. 3.""وَاجَهَ مُعْضِلَةً لاَ حَلَّ لَهَا"" : مَسْأَلَةً صَعْبَةً، مُشْكِلَةً عَويصَةً لاَ يُهْتَدَى لِحَلِّهَا. ""وَاجَهَ كُلَّ الْمُعْضِلاَتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12306, 'عَضَلَةٌ', 'عضلة', 'جامد', 'عضل', 'عضلة', 'عضلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"""قَوِيُّ العَضَلاَتِ"" : كُلُّ عَصَبَةٍ يُحِيطُ بِهَا لَحْمٌ مُجْتَمِعٌ يُحْدِثُ بِانْقِبَاضِ أَلْيَافِهِ حَرَكَةً فِي الْجِسْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12307, 'عُطَارِدٌ', 'عطارد', 'جامد', '', 'عطارد', 'عطرد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'O', '', '"عُطَارِدٌ-عُطَارِدٌ (فلك). : مِنَ الكَوَاكِبِ السَّيَّارَةِ وَهُوَ أَقْرَبُهَا إِلَى الشَّمْسِ، يُتِمُّ دَوْرَتَهُ حَوْلَهَا فِي ثَمَانِيَة وَثَمَانِينَ يَوْماً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12308, 'عَطَبٌ', 'عطب', 'جامد', 'عطب', 'عطب', 'عطب', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْطَابٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""حَدَثَ عَطَبٌ فِي السَّيَّارَةِ"" : خَلَلٌ في آلَةٍ مِنْ آلاتِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12309, 'أَعْطَابٌ', 'أعطاب', 'جامد', '', 'ءعطاب', 'عطب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12310, 'مَعْطَبٌ', 'معطب', 'جامد', 'عطب', 'معطب', 'معطب', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاطِبُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""وَقَفَ يُعَايِنُ الْمَعْطَبَ"" : مَوْضِعَ العَطَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12311, 'مَعَاطِبُ', 'معاطب', 'جامد', '', 'معاطب', 'معطب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12312, 'عِطَارَةٌ', 'عطارة', 'جامد', 'عطر', 'عطارة', 'عطرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عِطَارَةٌ-عِطَارَةٌ [ع ط ر]. : حِرْفَةُ العَطَّارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12313, 'عِفْرِيتٌ', 'عفريت', 'جامد', 'عفرت', 'عفريت', 'عفرت', '', '', '', 'مفرد', 'DnN', '', '', '"عَفَارِيتُ"', '', 'R', '', '', '', '', '', '', '". 1.""حِكَايَةُ العِفْرِيتِ"" : صُورَةٌ مُتَخَيَّلَةٌ لِلْجِنِّ. ""اِسْتَعَرْنَا مِنْ حِكَايَاتِ الأَهْلِ عَنِ العِفْرِيتِ مَعَالِمَ الشَّخْصِيَّةِ الَّتِي سَتَقُضُّ مَضَاجِعَنَا فِي لَيَالِي الشِّتَاءِ"". (حنا مينه). 2.""هُوَ العِفْرِيتُ بِعَيْنِهِ"" : الدَّاهِي، النَّافِذُ فِي الأَمْرِ مَعَ دَهَاءٍ وَمَكْرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12314, 'عَفَارِيتُ', 'عفاريت', 'جامد', '', 'عفاريت', 'عفرت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12315, 'عِطْرٌ', 'عطر', 'جامد', 'عطر', 'عطر', 'عطر', '', '', '', 'مفرد', 'DnN', '', '', '"عُطُورٌ"', '', 'R', '', '', '', '', '', '', '". ""يَفُوحُ عِطْرٌ زَكِيٌّ مِنْ فُسْتَانِهَا"" : مَا يُتَطَيَّبُ بِهِ لِحُسْنِ رَائِحَتِهِ. ""تَشْرَبُ قَطَرَاتِ النَّدَى وَتَسْكُبُ دَقَائِقَ العِطْرِ"". (جبران خ. جبران)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12316, 'عُطُورٌ', 'عطور', 'جامد', '', 'عطور', 'عطر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12317, 'مَعْطَرَةٌ', 'معطرة', 'جامد', 'عطر', 'معطرة', 'معطرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '".: الْمَحَلُّ الَّذِي تُبَاعُ فِيهِ العُطُورُ."', '');
