INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12331, 'عُطْلَةٌ', 'عطلة', 'جامد', 'عطل', 'عطلة', 'عطلة', '', '', '', 'مفرد', 'DnN', '', '', '"عُطَلٌ"', '', 'R', '', '', '', '', '', '', '". 1.""عُطْلَةُ الصَّيْفِ"" : الْمُدَّةُ الزَّمَنِيَّةُ الَّتِي يَتَعَطَّلُ فِيهَا التَّلاَمِيذُ عَنِ الدِّرَاسَةِ. ""عُطْلَةُ الرَّبِيعِ"". 2.""يَوْمُ العِيدِ يَوْمُ عُطْلَةٍ رَسْمِيَّةٍ"" : اليَوْمُ الَّذِي يَتَوَقَّفُ العَمَلُ خِلاَلَهُ فِي جَمِيعِ الدَّوَائِرِ وَالْمُؤَسَّسَاتِ."', '');
