INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12335, 'عَطَاءٌ', 'عطاء', 'جامد', 'عطو', 'عطاء', 'عط', '', '', '', 'مفرد', 'Dz', '', '', '"أَعْطِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '". ""رَجُلٌ كَثِيرُ العَطَاءِ"" : سَخِيٌّ، أَيْ يُعْطِي مِنْ مَالِهِ الكَثِيرَ. ""الذَّهَبُ يُعْرَفُ بِالنَّارِ وَأَمَانَةُ الرَّجُلِ بِالأَخْذِ وَالعَطَاءِ"". (ابن المقفع) ""الْحَيَاةُ أَخْذٌ وَعَطَاءٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12336, 'أَعْطِيَةٌ', 'أعطية', 'جامد', '', 'ءعطية', 'عطة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12337, 'عَطِيَّةٌ', 'عطية', 'جامد', 'عطو', 'عطية', 'عطة', '', '', '', 'مفرد', 'DnN', '', '', '"عَطَايَا"', '', '', '', '', '', '', '', '', '". ""قَدَّمَ لَهُ عَطِيَّةً"" : عَطَاءً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12338, 'عَطَايَا', 'عطايا', 'جامد', '', 'عطايا', 'عط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12339, 'مُعْطَيَاتٌ', 'معطيات', 'جامد', 'عطي', 'معطيات', 'معطت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُعْطَيَاتٌ-مُعْطَيَاتٌ [ع ط ي]. ن: مُعْطى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12340, 'عَظَائِيَّاتٌ', 'عظائيات', 'جامد', '', 'عظاءيات', 'عظت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": رُتْبَةُ العَظَاءِ، مِنَ الْحَيَوَانَاتِ الزَّاحِفَةِ، تَتَمَيَّزُ بِصِغَرِ حَجْمِهَا وَقُوَّةِ أَرْجُلِهَا، أَشْهَرُ فَصَائِلِهَا : الْجَعْرُورِيَّاتُ وَالْحِرْبَاوِيَّاتُ وَالْحِرْذَوْنِيَّاتُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12341, 'عَظَمَةٌ', 'عظمة', 'جامد', 'عظم', 'عظمة', 'عظمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""عَظَمَةُ اللِّسَانِ"" : مَا غَلُظَ مِنْهَا. 2.""اِسْتَبَدَّتْ بِهِ العَظَمَةُ"" : النَّخْوَةُ، الزَّهْوُ، الكِبْرِيَاءُ. ""أَحَاطَ مَظَاهِرَ حَيَاتِهِ بِالعَظَمَةِ وَالقُوَّةِ"". 3.""عَظَمَةُ اللَّهِ"" : قُدْرَتُهُ، جَلاَلُهُ، مَهَابَتُهُ. 4.""جُنُونُ العَظَمَةِ"" : الإِصابَةُ بِجُنُونِ الضَّخَامَةِ وَالكِبْرِيَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12342, 'يَعْفُورٌ', 'يعفور', 'جامد', 'عفر', 'يعفور', 'عفر', '', '', '', 'مفرد', 'DnN', '', '', '"يَعَافِيرُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1. : نَوْعٌ مِنَ الظِّبَاءِ، أَغْبَرُ اللَّوْنِ. 2.""يَعْفُورُ الْبَقَرَةِ الْوَحْشِيَّةِ"" : وَلَدُهَا. 3.""يَعْفُورُ اللَّيْلِ"" : جُزْءٌ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12343, 'يَعَافِيرُ', 'يعافير', 'جامد', '', 'يعافير', 'عفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12344, 'مُعْظَمٌ', 'معظم', 'جامد', 'عظم', 'معظم', 'معظم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مُعْظَمٌ-مُعْظَمٌ [ع ظ م]. 1.""مُعْظَمُ النَّاسِ"" : مُجْمَلُهُمْ، أَغْلَبُهُمُ. ""حَضَرَ مُعْظَمُ الضُّيوفِ"". 2.""يقْضِي مُعْظَمَ وَقْتِهِ في الدَّرْسِ"" : يَقْضِي أَغْلَبَ... ""فَهِمَ مُعْظَمَ الدَّرْسِ"" ""أَعْطَيْتُهُ مُعْظَمَ مَا عِنْدِي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12345, 'عَظْمٌ', 'عظم', 'جامد', '', 'عظم', 'عظم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَعْظُمٌ:عِظَامٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَعْظُمٌ، عِظَامٌ. ""عَظْمُ الإِنْسَانِ أَوِ الْحَيَوَانِ"" : القَصَبُ الَّذِيعَلَيْهِ اللَّحْمُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12346, 'أَعْظُمٌ', 'أعظم', 'جامد', '', 'ءعظم', 'عظم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
