INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12348, 'عَظَاءةٌ', 'عظاءة', 'جامد', 'عظي', 'عظاءة', 'عظة', '', '', '', 'مفرد', 'DnN', '', '', '"عَظَايَا"', '', 'Rz', '', 'N', 'O', 'O', 'O', '', '". : دُوَيِبَّةٌ مِنَ الزَّوَاحِفِ ذَوَاتِالأَرْبَعِ، مَلْسَاءُ، أَنْوَاعُهَا كَثِيرَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12349, 'عَظَايَا', 'عظايا', 'جامد', '', 'عظايا', 'عظ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12350, 'عُفْرَةٌ', 'عفرة', 'جامد', 'عفر', 'عفرة', 'عفرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عُفْرَةٌ-عُفْرَةٌ [ع ف ر]. 1. : بَيَاضٌ تُخَالِطُهُ حُمْرَةٌ. 2.""عُفْرَةُ الدِّيكِ"" : رِيشُ عُنُقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12351, 'عَافِيَةٌ', 'عافية', 'جامد', 'عفي', 'عافية', 'عفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"""رَجُلٌكَثِيرُالْعَافِيَةِ""', '', '', '', '', '', '', '', '', '"عَافِيَةٌ-عَافِيَةٌ [ع ف ي]. 1.""رَجُلٌ كَثِيرُ الْعَافِيَةِ"" : كَثِيرُ الضُّيُوفِ. 2.""لَكَ الْعَافِيَةُ وَالسَّلاَمَةُ"" : الصِّحَّةُ الْكَامِلَةُ. 3.""عَافِيَةُ الْمَاءِ"" : وَارِدَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12352, 'عُقَابٌ', 'عقاب', 'جامد', '', 'عقاب', 'عقب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"عِقْبَانٌ(مذ:مؤ)"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: عِقْبَانٌ. (مذ، مؤ).: طَائِرٌ مِنْ فَصِيلَةِ الصَّقْرِيَّاتِ، مِنَ الكَوَاسِرِ، لَهُ مَخَالِبُ قَوِيَّةٌ حَادَّةٌ، حَادُّ الْبَصَرِ، وَمِنْقَارٌ أَعْقَفُ، مِنْــهُ أَنْوَاعٌ عَدِيدَةٌ. ""هُوَ أَبْصَرُ مِنْ عُقَابٍ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12353, 'عِقْبَانٌ', 'عقبان', 'جامد', '', 'عقبان', 'عقبن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12354, 'أعْقَابٌ', 'أعقاب', 'جامد', 'عقب', 'ءعقاب', 'عقب', '', '', '', 'مفرد', '', '', '', '"مفردعَقْب:عَقِب"', '', '', '', '', '', '', '', '', '". ""رَجَعُوا عَلَى أعْقَابِهِمْ خَاسِرينَ"" : عَلَى أَواخِرِهمْ. عادُوا مِنْ حَيْثُ أَتَوْا. o ""اِرْتَدُّوا عَلَى أعْقَابِهِمْ فِي حَالَةٍ يُرْثَى لَهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12355, 'عَاقِبَةٌ', 'عاقبة', 'جامد', 'عقب', 'عاقبة', 'عقبة', '', '', '', 'مفرد', 'DnN', '', '', '"عَوَاقِبُ"', '', '', '', '', '', '', '', '', '". 1.""اللَّهُمَّ اجْعَلْ عَاقِبَتَنَا خَيْراً"" : أَيْ خَاتِمَتَنَا، آخِرُ كُلِّ شَيْءٍ. 2.""يَخْشَى سُوءَ الْعَاقِبَةِ"" : الْجَزَاءَ. ""إِنَّهَا مُغَامَرَةٌ غَيْرُ مَأْمُونَةِ الْعَوَاقِبِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12356, 'عَوَاقِبُ', 'عواقب', 'جامد', '', 'عواقب', 'عقب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12357, 'عَقَبَةٌ', 'عقبة', 'جامد', 'عقب', 'عقبة', 'عقبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""عَقَبَةُ الْجَبَلِ"" : الطَّرَفُ فِي أَعْلَى الْجَبَلِ. ""وَقَفَ حِمَارُ الشَّيْخِ فِي الْعَقَبَةِ"". 2.""اِسْتَطَاعَ أَنْ يَتَغَلَّبَ عَلَى جَمِيعِ العَقَبَاتِ"" : عَلَى الصِّعَابِ، الْمَصَاعِبِ، الْمَوَانِعِ، العَوَائِقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12358, 'عُقْبَةٌ', 'عقبة', 'جامد', 'عقب', 'عقبة', 'عقبة', '', '', '', 'مفرد', 'DnN', '', '', '"عُقَبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""عُقْبَةُ الشَّيْءِ"" : آخِرُهُ. 2.""جَاءتْ عُقْبَتُهُ"" : نَوْبَتُهُ. 3.""عُقْبَةُ الطَّعَامِ"" : مَا يُؤْكَلُ فِي آخِرِهِ مِنْ حَلْوَى أَوْ فَاكِهَةٍ. 4.""هُوَ عُقْبَةُ بَنِي فُلاَنٍ"" : أَيْ آخِرُ مَنْ بَقِيَ مِنْهُمْ. 5.""عُقْبَةُ الْجَمَالِ"" : أَثَرُهُ وَهَيْئَتُهُ. 6.""عُقْبَةُ الطَّائِرِ"" : مَسَافَةُ مَا بَيْنَ ارْتِفَاعِهِ وَانْحِطَاطِهِ. 7.""مَا يَفْعَلُ ذَلِكَ إِلاَّ عُقْبَةَ القَمَرِ"" : إِذَا كَانَ يَفْعَلُهُ كُلَّ شَهْرٍ مَرَّةً. 8.""عُقْبَةُ بْنُ نَافِعٍ"" : اِسْمُ عَلَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12359, 'عُقَبٌ', 'عقب', 'جامد', '', 'عقب', 'عقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12360, 'عَقَبٌ', 'عقب', 'جامد', 'عقب', 'عقب', 'عقب', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْقَابٌ"', '', 'R', '', '', '', '', '', '', '". ""شدّ الشَّيْءَ بِالعَقَبِ"" : أَي القَصَب الَّذِي تُصْنَعُ مِنْهُ الأَوْتَارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12361, 'أَعْقَابٌ', 'أعقاب', 'جامد', '', 'ءعقاب', 'عقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12362, 'عَقِبٌ', 'عقب', 'جامد', 'عقب', 'عقب', 'عقب', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْقَابٌ"', '', 'R', '', '', '', '', '', '', '". 1.""عَقِبُ مُؤَخَّرِ القَدَمِ"": عَظْمُ مُؤَخَّرِ القَدَمِ وَهُوَ أَكْبَرُ عِظَامِهَا. 2.""رَجَعَ عَلَى عَقِبِهِ"" : رَجَعَ مِنْ حَيْثُ أَتَى. 3.""رُدَّ عَلَى عَقِبِهِ"" : رُدَّ إِلَى الْجِهَةِ الَّتِي جَاءَ مِنْهَا. ""اِنْقَلَبَ الوَضْعُ رَأْساً عَلَى عَقِبٍ"". 4.""جَاءَ عَقِبَهُ وَبِعَقِبِهِ"" : خَلْفَهُ، فِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12363, 'أَعْقَابٌ', 'أعقاب', 'جامد', '', 'ءعقاب', 'عقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12364, 'عُقْبٌ', 'عقب', 'جامد', 'عقب', 'عقب', 'عقب', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْقَابٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""ضَرَبَهُ بِعُقْبِ البُنْدُقِيَّةِ"" : مُؤَخِّرَتُهَا. 2.""عُقْبُ السِّيجَارَةِ"" : مُؤَخِّرُهَا الْمُتَبَقِّي مِنْهَا. 3.""جَرَتْ حَمْلَةُ اعْتِقَالاَتٍ فِي أَعْقَابِ الْمُظَاهَرَةِ"" : فِي نِهَايَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12365, 'أَعْقَابٌ', 'أعقاب', 'جامد', '', 'ءعقاب', 'عقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12366, 'عُقْبَى', 'عقبى', 'جامد', 'عقب', 'عقبى', 'عقب', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"عُقْبَى-عُقْبَى [ع ق ب]. 1.""عُقْبَى الأَمْرِ"" : آخِرُ كُلِّ شَيْءٍ.الرعد آية 35وَعُقْبَى الكَافِرِينَ النَّارُ (قرآن). 2.""العُقْبَى"" : الآخِرَةُ. 3.""عُقْبَى لَكَ"" : الدَّعْوَةُ ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12367, 'عُقُوبَةٌ', 'عقوبة', 'جامد', 'عقب', 'عقوبة', 'عقبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""تَعَرَّضَ لِعُقُوبَةٍ شَدِيـدَةٍ"" : لِعِقَابٍ. ""قَانُونُ العُقُوبَاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12368, 'عَقِيبٌ', 'عقيب', 'جامد', 'عقب', 'عقيب', 'عقب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَقِيبٌ-عَقِيبٌ [ع ق ب]. ""عَقِيبُ شَيْءٍ"" : كُلُّ شَيْءٍ يَأْتِي بَعْدَ شَيْءٍ وَيَتْلُوهُ. ""هُوَ عَقِيبُهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12369, 'يَعْقُوبٌ', 'يعقوب', 'جامد', 'عقب', 'يعقوب', 'عقب', '', '', '', 'مفرد', 'DnN', '', '', '"يَعَاقِيبُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""يَعْقُوبُ الْحَجَلِ"": ذَكَرُهُ. 2.""يَعْقُوبُ"" : اِسْمُ عَلَمٍ لِلْمُذَكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12370, 'يَعَاقِيبُ', 'يعاقيب', 'جامد', '', 'يعاقيب', 'عقب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
