INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12372, 'عِقَادَةٌ', 'عقادة', 'جامد', 'عقد', 'عقادة', 'عقدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عِقَادَةٌ-عِقَادَةٌ [ع ق د]. : مِهْنَةُ العَقَّادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12373, 'عَقَّادٌ', 'عقاد', 'جامد', 'عقد', 'عقاد', 'عقد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَقَّادٌ-عَقَّادٌ [ع ق د]. 1. : صَانِعُ الْخُيُوطِ وَالأَزْرَارِ وَبَائِعُهَا. 2. : مِنَ الأَسْمَاءِ العَائِلِيَّةِ بِالْمَشْرِقِ وَالْمَغْرِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12374, 'عُقْدَةٌ', 'عقدة', 'جامد', 'عقد', 'عقدة', 'عقدة', '', '', '', 'مفرد', 'DnN', '', '', '"عُقَدٌ"', '', 'R', '', '', '', '', '', '', '". 1.""عُقْدَةُ الْحَبْلِ أَوِ الْمِنْدِيلِ وَغَيْرِهِ"" : مَوْضِعُ العَقْدِ. 2.""عُقْدَةُ النَّبَاتِ"" : مَوْضِعُ ظُهُورِ الوَرَقَةِ عَلَى سَاقِ النَّبَاتِ. 3.""العُقْدَةُ مِنَ الأَرْضِ"" : الأَرْضُ الصَّالِحَةُ لِلزِّرَاعَةِ أَوِ البِنَاءِ، البُقْعَةُ. 4.""عُقْدَةُ النِّكَاحِ"" : وُجُوبُهُ وَإِحْكَامُهُ إِبْرَاماً. البقرة آية 235 وَلاَ تَعْزِمُوا عُقْدَةَ النِّكَاحِ حَتَّى يَبْلُغَ الكِتَابُ أَجَلَهُ (قرآن). 5.""فِي لِسَانِهِ عُقْدَةٌ"" : اِلْتِوَاءٌ وَعَدَمُ الطَّلاَقَةِ فِي الْكَلاَمِ. ""ع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12375, 'عُقَدٌ', 'عقد', 'جامد', '', 'عقد', 'عقد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
