INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12388, 'عُقْرُبَانٌ', 'عقربان', 'جامد', 'عقرب', 'عقربان', 'عقربن', '', '', '', 'مفرد', 'DnN', '', '', '"(الذَّكَرُمِنَالعَقَارِبِ)"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عُقْرُبَانٌ-عُقْرُبَانٌ [ع ق ر ب]. : الذَّكَرُ مِنَ العَقَارِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12389, 'عَقْرَبٌ', 'عقرب', 'جامد', 'عقرب', 'عقرب', 'عقرب', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"عَقَارِبُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""لَسَعَتْهُ عَقْرَبٌ"" : دُوَيِبَّةٌ سَامَّةٌ مِنَ العَنْكَبِيَّاتِ تَلْسَعُ. 2.""عَقْرَبُ البَحْرِ"": سَمَكَةٌ فِي البِحَارِ الاسْتِوَائِيَّةِ لَهَا رَأْسٌ ضَخْمٌ وَزِعْنِفَةٌ ظَهْرِيَّةٌ كَبِيرَةٌ، بَعْضُ أَنْوَاعِهَا سَامٌّ. 3.""بُرْجُ العَقْرَبِ"" (فلك) : بُرْجٌ مِنْ بُرُوجِ السَّمَاءِ، وَهُوَ الْبُرْجُ الثَّامِنُ مِنْهَا تَنْزِلُهُ الشَّمْسُ فِي الثَّالِثِ وَالعِشْرِينَ مِنْ شَهْرِ أُكْتُوبَر. 4.""عَقَارِبُ الشِّتَاءِ"" : قُوَّةُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12390, 'عَقَارِبُ', 'عقارب', 'جامد', '', 'عقارب', 'عقرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12391, 'عَقْعَقٌ', 'عقعق', 'جامد', '', 'عقعق', 'عقعق', '', '', '', 'جمع تكسير', 'DnN', '', '', '"عَقَاعِقُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: عَقَاعِقُ. (حو). : طَيْرٌ مِنْ فَصِيلَةِ الغُرَابِيَّاتِ، مِنْ رُتْبَةِالعُصْفُورِيَّاتِ، أَسْوَدُ اللَّوْنِ مَعَ وُجُودِ بُقْعَةٍ بَيْضَاءَ فِي جَنَاحَيْهِ، طَوِيلُ الذَّنَبِ، هَدَّارٌ جَمِيلُ الطَّيَرَانِ، مُسْتَمِيتٌ فِي دِفَاعِهِ عَنْ فِرَاخِهِ وَيَمْتَازُ بِالْحَذَرِ. ""هُوَ أَحْذَرُ مِنْ عَقْعَقٍ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12392, 'عَقَاعِقُ', 'عقاعق', 'جامد', '', 'عقاعق', 'عقعق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12393, 'عُقَافَةٌ', 'عقافة', 'جامد', 'عقف', 'عقافة', 'عقفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُقَافَةٌ-عُقَافَةٌ [ع ق ف]. : عَصاً أَوْ حَدِيدَةٌ فِي أَحَدِ طَرَفَيْهَا الْتِوَاءٌ يُشْبِهُ الصِّنَّارَةَ يُجْذَبُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12394, 'عُقَافٌ', 'عقاف', 'جامد', 'عقف', 'عقاف', 'عقف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عُقَافٌ-عُقَافٌ [ع ق ف]. : دَاءٌ يُصِيبُ قَوَائِمَ الشَّاةِ فَتَعْوَجُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12395, 'عَقِيقَةٌ', 'عقيقة', 'جامد', 'عقق', 'عقيقة', 'عققة', '', '', '', 'مفرد', 'DnN', '', '', '"عَقَائِقُ"', '', 'R', '', '', '', '', '', '', '". 1.""أَقَامَ حَفْلَةَ عَقِيقَةٍ لابْنِهِ الْمَوْلُودِ"" : حَفْلَة اليَوْمِ السَّابِعِ الَّذِي تُذْبَحُ فِيهِ شَاةٌ لاخْتِيَارِ اسْمِ الابْنِ وَحَلْقِ شَعْرِهِ. 2.""عَقِيقَةُ بَرْقٍ"" : مَا يُخَلِّفُهُ البَرْقُ مِنْ شُعَاعِ ضَوْئِهِ فِي السَّحَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12396, 'عَقَائِقُ', 'عقائق', 'جامد', '', 'عقاءق', 'عقق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12397, 'عَقِيقٌ', 'عقيق', 'جامد', 'عقق', 'عقيق', 'عقق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَقِيقٌ-عَقِيقٌ [ع ق ق].: حَجَرٌ كَرِيمٌ أَحْمَرُ تُصْنَعُ مِنْهُ الفُصُوصُ. ""يَعُودُ كَلَوْنِ العَقِيقِ فِي رَائِحَةِ الْمِسْكِ العَتِيقِ"". (الجاحظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12398, 'عُقَّالٌ', 'عقال', 'جامد', 'عقل', 'عقال', 'عقل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُقَّالٌ-عُقَّالٌ [ع ق ل]. 1.""أُصِيبَ فَجْأَةً بِعُقَّالٍ"" : اِنْقِبَاضٌ شَدِيدُ التَّوَتُّرِ مُؤْلِمٌ فِي بَعْضِ العَضَلاَتِ، يُسَبِّبُ وُقُوفَ الْحَرَكَةِ وَقْتِيّاً. 2.""دَاءٌ ذُو عُقَّالٍ"" : دَاءٌ عُضَالٌ، لاَ يُبْرَأُ مِنْهُ، لاَ يُرْجَى مِنْهُ شِفَاءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12399, 'عِقَالٌ', 'عقال', 'جامد', 'عقل', 'عقال', 'عقل', '', '', '', 'مفرد', 'DnN', '', '', '"عُقُلٌ"', '', 'R', '', '', '', '', '', '', '". 1.""عِقَالُ الدَّابَّةِ"" : حَبْلٌ تُشَدُّ بِهِ فِي وَسَطِ ذِرَاعِهَا. 2.""شَدَّ الكُوفِيَّةَ بِالعِقَالِ"" : جَدِيلَةٌ مِنَ الصُّوفِ أَوِ الْحَرِيرِ تُلَفُّ عَلَـى الكُوفِيَّةِ فَـوْقَ الـرَّأْسِ. 3.""أَطْلَقَهُ مِنْ عِقَالِهِ"" : مِنْ قَيْدِهِ. 4.""أَطْلَقَ الفِتْنَةَ مِنْ عِقَالِهاَ"" : أَثَارَهَا بَعْدَمَا كَانَتْ خَافِتَةً سَاكِنَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12400, 'عُقُلٌ', 'عقل', 'جامد', '', 'عقل', 'عقل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12401, 'عُقْلَةٌ', 'عقلة', 'جامد', 'عقل', 'عقلة', 'عقلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُقْلَةٌ-عُقْلَةٌ [ع ق ل]. 1.""عُقْلَةُ العِقَالِ"" : مَا يُعْقَلُ بِهِ. 2.""عُقْلَةُ الدَّابَّةِ"" : قَيْدُهَا. 3.""عُقْلَةُ الرِّيَاضَةِ"" : قَضِيبٌ مِنَ الْخَشَبِ أَوِ الْمَعْدِنِ مَشْدُودُ الطَّرَفَيْنِ فِـي حَبْلَيْنِ مُثْبَتَيْنِ مِـنْ أَعْلَى فِي سَقْفٍ، أَوْ عَارِضَةٍ مَشْدُودَةٍ بِدَوْرِهَا مِنْ كُلِّ طَرَفَيْهَا بِمَا يُثَبِّتُهَا بِالأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12402, 'عَقِيلَةٌ', 'عقيلة', 'جامد', 'عقل', 'عقيلة', 'عقلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":عَقَائِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""جَاءَ بِرُفْقَةِ عَقِيلَتِهِ"" : زَوْجَتِهِ الكَرِيمَةِ. 2.""نَاقَةٌ عَقِيلَةٌ"" : كَرِيمَةٌ. 3.""عَقَائِلُ الكَلاَمِ"" : أَفْضَلُهُ، أَجْوَدُهُ. 4.""عَقِيلَةُ القَوْمِ"" : سَيِّدُهُمْ. 5.""عَقِيلَةُ البَحْرِ"" : دُرَّتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12403, 'عَقَائِلُ', 'عقائل', 'جامد', '', 'عقاءل', 'عقل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12404, 'مُعْتَقَلٌ', 'معتقل', 'جامد', 'عقل', 'معتقل', 'معتقل', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""قَضَى زَمَناً فِي الْمُعْتَقَلِ"" : فِي السِّجْنِ، مَكَانُ الاعْتِقَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12405, 'مَعْقِلٌ', 'معقل', 'جامد', 'عقل', 'معقل', 'معقل', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاقِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""اِلْتَجَأَ إِلَى مَعْقِلٍ مُرْتَفِعٍ"" : الجَبَلُ، الحِصْنُ. 2. ""تَحَصَّنُوا فِي مَعْقِلِهِمْ"" : فِي مَلْجَئِهِمْ. ""وَدَكَّ مَعَاقِلَ الطَّاغُوتِ فِي بَغْدَادَ أَبْطَالُ"". (بدر شاكر السياب)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12406, 'مَعَاقِلُ', 'معاقل', 'جامد', '', 'معاقل', 'معقل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12407, 'عُكَّازٌ', 'عكاز', 'جامد', 'عكز', 'عكاز', 'عكز', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '":عَكَاكِيزُ"', '', 'R', '', '', '', '', '', '', '". ""يَتَحَسَّسُ الطَّرِيقَ بِعُكَّازِهِ"" : عَصاً يَتَوَكَّأُ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12408, 'عَكَاكِيزُ', 'عكاكيز', 'جامد', '', 'عكاكيز', 'عككز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12409, 'عُكُوفٌ', 'عكوف', 'جامد', 'عكف', 'عكوف', 'عكف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُكُوفٌ-عُكُوفٌ [ع ك ف]. ""العُكوفُ عَلَى العَمَلِ"" : لُزُومُهُ والتَّفَرُّغُ لَهُ. ""كَانَ إِفْرَاطُهُ فِي الْجِدِّ وَحُبُّهُ لِلْعُزْلَةِ وَعُكُوفُهُ عَلَى القِرَاءةِ مَحَطَّ إِعْجَابٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12410, 'عِلْبَاءُ', 'علباء', 'جامد', 'علب', 'علباء', 'علب', '', '', '', 'مفرد', '', '', '', '"عِلاَبِيُّ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". ""عِلْبَاءُ العُنُقِ"" : عَصَبَةٌ صَفْرَاءُ مُمْتَدَّةٌ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12411, 'عِلاَبِيُّ', 'علابي', 'جامد', '', 'علابي', 'علب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12412, 'عُلْبَةٌ', 'علبة', 'جامد', 'علب', 'علبة', 'علبة', '', '', '', 'مفرد', 'DnN', '', '', '"عُلَبٌ:عِلاَبٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""عُلْبَةُ كِبْرِيتٍ "": صُنْدُوقٌ صَغِيرٌ مِنْ وَرَقٍ مُقَوّىً تُجْمَعُ فِيهِ عِيدَانُ الْكِبْرِيتِ. ""عُلْبَةُ تِبْغٍ"". 2. ""علَى الـرَّفِّ عُلَـبُ الْمَـوَادِّ الْغِذَائِيَّةِ"" : أَوْعِيَةٌ مِنَ الْقَصْدِيرِ تَحْفَظُ الْمَوَادَّ الغِذَائِيَّةَ مِنَ التَّعَفُّنِ وَالفَسَادِ بِفِعْلِ مَوَادَّ كِيمِيَائِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12413, 'عُلَبٌ', 'علب', 'جامد', '', 'علب', 'علب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12414, 'عِلاَبٌ', 'علاب', 'جامد', '', 'علاب', 'علب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12415, 'مُعَقِّمَةٌ', 'معقمة', 'جامد', 'عقم', 'معقمة', 'معقمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مُعَقِّمَةٌ-مُعَقِّمَةٌ [ع ق م]. : آلَةُ التَّعْقِيمِ، أَيْ آلَةُ تَطْهيرِ الْمَوَادِّ مِنَ الْجَرَاثِيمِ، مِعْقَامٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12416, 'عِلْجٌ', 'علج', 'جامد', 'علج', 'علج', 'علج', '', '', '', 'مفرد', 'DnN', '', '', '"عُلُوجٌ:أَعْلاَجٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""جَاءَ رَاكِباً فَوْقَ عِلْجٍ"" : فَوْقَ حِمَارٍ، وَيُطْلَقُ الْعِلْجُ عَلَى الْحِمَارِ الوَحْشِيِّ القَوِيِّ السَّمِينِ. 2.""هُوَ مِنَ الْعُلُوجِ"" : أَيْ مِنَ الرِّجَالِ الضِّخَامِ الأَقْوِيَاءِ الْمُنْحَدِرِ مِنَ الْكُفَّارِ الْعَجَمِ، كَمَا كَانَ يُطْلَقُ الْعِلْجُ عَلَى الْكَافِرِ مُطْلَقاً. 3.""رَجُلٌ عِلْجٌ"" : شَدِيدٌ غَلِيظٌ. 4.""خُبْزٌ عِلْجٌ"" : غَلِيظٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12417, 'عُلُوجٌ', 'علوج', 'جامد', '', 'علوج', 'علج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
