INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12419, 'عَلَجَانٌ', 'علجان', 'جامد', '', 'علجان', 'علجن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عَلَجَانٌ-عَلَجَانٌ (نب). : شُجَيْرَةٌ ذَاتُ سِيقَانٍ، وَهِيَ أُسْطُوَانِيَّةٌ دَقِيقَةٌ، يَبْلُغُ طُولُهَا أَحْيَاناً ثَلاَثِينَ مِتْراً، أَوْرَاقُهَا حَرْشَفِيَّةٌ، لَهَا زَهْرٌ أَصْفَرُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12420, 'عُلْجُومٌ', 'علجوم', 'جامد', '', 'علجوم', 'علجم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"عَلاَجِيمُذَكَرُالضَّفَادِعِ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: عَلاَجِيمُ. 1.(حو) : ذَكَرُ الضَّفَادِعِ. 2. : مَاءٌ غَمْرٌ كَثِيرٌ."', ':لا جذر:لا مفرد');
