INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12426, 'مَعْلَفٌ', 'معلف', 'جامد', 'علف', 'معلف', 'معلف', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَالِفُ"', '', 'R', '', '', '', '', '', '', '". ""مَعْلَفُ الْحَيَوَانِ"" : مَوْضِعُ العَلَفِ."', '');
