INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12428, 'عَلاَّقَةٌ', 'علاقة', 'جامد', 'علق', 'علاقة', 'علقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""عَلَّقَ ثِيَابَهُ عَلَى العَلاَّقَةِ"" : أَدَاةٌ مِنْ خَشَبٍ أَوْ مِنْ مَعْدِنٍ تُعَلَّقُ عَلَيْهَا الثِّيَابُ وَنَحْوُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12429, 'عَلاَقَةٌ', 'علاقة', 'جامد', 'علق', 'علاقة', 'علقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":عَلاَئِقُ"', '', 'R', '', '', '', '', '', '', '". 1.""تَرْبِطُهُ بِهِ عَلاَقَةُ صَدَاقَةٍ"" : صِلَةٌ، رَابِطَةٌ. 2.""تَرْبِطُهُ بِهِ عَلاَقَةٌ عَائِلِيَّةٌ"" : قَرَابَةٌ. 3.""لاَ عَلاَقَةَ لِي بِمَا حَدَثَ"" : لاَ صِلَةَ... ""لاَ عَلاَقَةَ لِهَذَا الْمَوْضُوعِ بِـ..."" ""بَيْنَهُمَا عَلاَقَةُ حُبٍّ مُتَبَادَلَةٌ"" ""أَصْبَحَتِ العَلاَقَاتُ بَيْنَ البَلَدَيْنِ مُتَوَتِّرَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12430, 'عَلاَئِقُ', 'علائق', 'جامد', '', 'علاءق', 'علق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12431, 'عِلاَقَةٌ', 'علاقة', 'جامد', 'علق', 'علاقة', 'علقة', '', '', '', 'مفرد', 'DnN', '', '', '"عَلاَئِقُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""عِلاَقَةُ السَّيْفِ"" : مَا يُعَلَّقُ عَلَيْهِ السَّيْفُ وَنَحْوُهُ. 2.""عِلاَقَةُ الثِّمَارِ"" : مَا تَعَلَّقَ عَلَى الأَشْجَارِ مِنَ الثِّمَارِ. 3. : الْجُزْءُ الدَّقِيقُ مِنْ وَرَقَةِ النَّبَاتِ يَحْمِلُ فِي طَرَفِهِ صَفِيحَتَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12432, 'عَلاَئِقُ', 'علائق', 'جامد', '', 'علاءق', 'علق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12433, 'عَلَقَةٌ', 'علقة', 'جامد', 'علق', 'علقة', 'علقة', '', '', '', 'مفرد', 'DnN', '', '', '"واحدةالْعَلَقِ"', '', 'R', '', '', '', '', '', '', '"عَلَقَةٌ-عَلَقَةٌ [ع ل ق] (وَاحِدَةُ الْعَلَقِ).غافر آية 67هُوَ الَّذِي خَلَقَكُمْ مِنْ تُرَابٍ، ثُمَّ مِنْ نُطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ (قرآن) : طَوْرٌ مِنْ أَطْوَارِ الْجَنِينِ، وَهِيَ القِطْعَةُ الْمَنَوِيَّةُ الَّتِي يَتَكَوَّنُ مِنْهَا بَعْدَ النُّطْفَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12434, 'عَلَق', 'علق', 'جامد', '', 'علق', 'علق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12435, 'عُلَّيْقٌ', 'عليق', 'جامد', 'علق', 'عليق', 'علق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُلَّيْقٌ - [ع ل ق]. 1.""عُلَّيْقُ الشَّجَرِ"" : النَّبَاتُ الَّذِي يَنْبُتُ بِالشَّجَرِ وَيَتَلَوَّى عَلَيْهِ. 2.""تُوتُ العُلَّيْقِ"" : ثَمَرَةُ العَوْسَجِ، نَبْتُهُ شَائِكُ الأَغْصَانِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12436, 'مِعْلاَقٌ', 'معلاق', 'جامد', 'علق', 'معلاق', 'معلق', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَالِيقُ"', '', 'R', '', '', '', '', '', '', '". ""مِعْلاَقُ الْمَلاَبِسِ"" : مَا يُعَلَّقُ عَلَيْهِ ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12437, 'مَعَالِيقُ', 'معاليق', 'جامد', '', 'معاليق', 'معلق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12438, 'عَلْقَمٌ', 'علقم', 'جامد', 'علقم', 'علقم', 'علقم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَلْقَمٌ -[ع ل ق م]. ""سَقَوْهُ الْخَلَّ مَمْزُوجاً بِنَقِيعِ الْعَلْقَمِ"": الْحَنْظَل، كُلُّ شَيْءٍ مُرٍّ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12439, 'عِلْكٌ', 'علك', 'جامد', 'علك', 'علك', 'علك', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"عُلُوكٌ:أَعْلاَكٌ"', '', 'R', '', '', '', '', '', '', '". : ضَرْبٌ مِنَ الصَّمْغِ يُعْلَكُ"', '');
