INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12442, 'عِلَّةٌ', 'علة', 'جامد', 'علل', 'علة', 'علة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":عِلَلٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أُصِيبَ بِعِلَّةٍ لَمْ يَعُدْ يَنْفَعُ مَعَهَا دَوَاءٌ"" : الْمَرَضُ الفَتَّاكُ الشَّاغِلُ. 2.""لَمْ أَفْهَمْ عِلَّةَ مَجِيئِهِ"" : سَبَبَ مَجِيئِهِ. 3.""الْعِلَّةُ وَالمَعْلُولُ"" : السَّبَبُ وَالنَّتِيجَةُ. 4.""عِلَّةُ الْعِلَلِ فِي كُلِّ هَذَا هِيَ..."" : أَصْلُ السَّب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12443, 'عِلَلٌ', 'علل', 'جامد', '', 'علل', 'عل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12444, 'تَعْلِيمَاتٌ', 'تعليمات', 'جامد', 'علم', 'تعليمات', 'تعلمت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"تَعْلِيمَاتٌ-تَعْلِيمَاتٌ [ع ل م]. ""أَصْدَرَ الوَزِيرُ تَعْلِيمَاتٍ جَدِيدَةً"": أَوَامِرَ وَتَوْجِيهَاتٍ لِلاسْتِرْشَادِ بِهَا، أُسْلُوبُ العَمَلِ وَطَرِيقَتُهُ وَالغَايَةُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12445, 'عَالَمٌ', 'عالم', 'جامد', 'علم', 'عالم', 'علم', '', '', '', 'مفرد', 'DnN', '', '', '"عَوَالِمُ"', '', 'Rp', '', '', '', '', '', '', '". ""عَالَمُ الإِنْسَانِ وَالْحَيَوَانِ"" : مَجْمُوعُ كُلِّ شَيْءٍ يُوجَدُ عَلَى وَجْهِ الْبَسِيطَةِ، الدُّنْيَا. ""عَالَمُ النَّبَاتِ"" ""يُوَاجِهُ الإِنْسَانُ عَالَمَهُ مَبْهُوراً"". 2.""اِكْتَسَبَ شُهْرَةً فِي عَالَمِ السِّيَاسَةِ"" : فِي مَجَالِ ... 3.""الْعَالَمُ الْجَدِيدُ"" : أَمْرِيكَا. 4.""الْعَالَمُ الْقَدِيمُ"" : أُورُوبَّا وَآسِيَا وَإِفْرِيقِيَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12446, 'عَوَالِمُ', 'عوالم', 'جامد', '', 'عوالم', 'علم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12447, 'عُلْمَةٌ', 'علمة', 'جامد', 'علم', 'علمة', 'علمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُلْمَةٌ-عُلْمَةٌ [ع ل م]. : شَقٌّ فِي الشَّفَةِ الْعُلْيَا لِلإِنْسَانِ، فَتُشْبِهُ بِذَلِكَ شَفَةَ الأَرْنَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12448, 'عَلْمٌ', 'علم', 'جامد', 'علم', 'علم', 'علم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَلْمٌ-عَلْمٌ [ع ل م]. : عَالَمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12449, 'مَعْلَمَةٌ', 'معلمة', 'جامد', 'علم', 'معلمة', 'معلمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""مَعْلَمَةُ العُلُومِ"" : مَوْسُوعَةُ العُلُومِ. ""مَعْلَمَةُ الْمَغْرِبِ"" ""الْمَعْلَمَةُ الإِسْلامِيَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12450, 'مَعْلَمٌ', 'معلم', 'جامد', 'علم', 'معلم', 'معلم', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَالِمُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَعْلَمُ الطَّرِيقِ"" : إِشَارَةُ الطَّرِيقِ الَّتِي تَدُلُّ عَلَيْهَا. ""مَعَالِمُ الطَّرِيقِ"". 2.""زَارَ مَعَالِمَ الْمَدِينَةِ"" : أَيْ مَآثِرَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12451, 'مَعَالِمُ', 'معالم', 'جامد', '', 'معالم', 'معلم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12452, 'عِلاَوَةٌ', 'علاوة', 'جامد', 'علو', 'علاوة', 'علة', '', '', '', 'مفرد', 'DnN', '', '', '"عَلاوَى:عَلاَوٍ"', '', 'R', '', '', '', '', '', '', '". 1.""عِلاَوَةُ الرَّأْسِ"" : أَعْلاَهُ. 2.""عِلاَوَةً عَلَى ذِلِكَ"" : بِالإِضَافَةِ إِلَى ذَلِكَ. 3.""سَلَّمَهُ مِائَةَ دِرْهَمٍ عِلاَوَةً"" : زِيَادَةً عَلَى مَا يَحِقُّ لَهُ، إِضَافَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12453, 'عَلاوَى', 'علاوى', 'جامد', '', 'علاوى', 'عل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12454, 'عَلاوِي', 'علاوي', 'جامد', '', 'علاوي', 'عل', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12455, 'عَلْوٌ', 'علو', 'جامد', 'علو', 'علو', 'عل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُلُوٌّ-عُلُوٌّ [ع ل و] (مص. عَلاَ). 1.""عُلُوُّ الهِمَّةِ"" : سُمُوٌّ، مَكَانَةٌ، عَظَمَةٌ. عُلُوٌّ فِي الحَيَاةِ وَفِي الْمَمَاتِ*لَعَمْرِي تِلْكَ إِحْدَى الْمُعْجِزَاتِ (صفي الدين الحلي). 2.""أَظْهَرَ عُلُـوّاً"" : تَجَبُّراً.القصص آية 83 تِلْكَ الدَّارُ الآخِرَةُ نَجْعَلُهَا لِلَّذِينَ لاَ يُرِيدُونَ عُلُوّاً فِي الأَرْضِ وَلاَ فَسَاداً (قرآن). 3.""تُوجَدُ القَرْيَةُ عَلَى عُلُوِّ أَلْفِ مِتْرٍ"" : عَلَى اِرْتِفَاعٍ. ""عُلُوٌّ شَاهِقٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12456, 'مَعَالِي', 'معالي', 'جامد', 'علو', 'معالي', 'معل', '', 'Tk', '', 'مفرد', 'DnN', '', '', '"مَعْلاَةٌ"', '', '', '', '', '', '', '', '', '". 1.""مَعَالِي الأُمُورِ"" : أَشْرَفُهَا، أَنْبَلُهَا. 2.""مَعَالِي الوَزِيرِ"" : لَقَبٌ لِلْوَزِيرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12457, 'مَعْلاَةٌ', 'معلاة', 'جامد', '', 'معلاة', 'معلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12458, 'عُلاَ', 'علا', 'جامد', 'علي', 'علا', 'عل', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"عُلاَ-عُلاَ، عُلَى [ع ل ي]. ""يَصْبُو إِلَى العُلاَ"" : الرِّفْعَةِ وَالشَّرَفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12459, 'عَلْيَاءُ', 'علياء', 'جامد', 'علو،علي', 'علياء', 'عل', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"عَلْيَاءُ-عَلْيَاءُ [ع ل و،ع ل ي]. 1.""اِرْتَقَى الْعَلْيَاءَ"" : رَأْسَ الْجَبَلِ، الْمَكَانَ الْمُشْرِفَ فِي قِمَّةٍ. 2.""عَلْيَاءُ الْمَجْدِ"" : شَرَفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12460, 'عُلِّيَّةٌ', 'علية', 'جامد', '', 'علية', 'علة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"عَلاَلِيُّ"', '', '', '', '', '', '', '', '', '"ج: عَلاَلِيُّ. 1.""يَسْكُنُ فِي الْعُلِّيَّةِ"" : فِي الْغُرْفَةِ الْمَوْجُودَةِ فِي الطَّبَقَةِ الثَّانِيَةِ مِنَ الدَّارِ وَمَا فَوْقَهَا. 2.""هُوَ مِنْ عُلِّيَّةِ الْقَوْمِ"" : أَيْ مِنْ خِيَارِهِمْ وَأَشْرَاِفِهِمْ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12461, 'عَلاَلِيُّ', 'علالي', 'جامد', '', 'علالي', 'علل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12462, 'عَمَّانُ', 'عمان', 'جامد', '', 'عمان', 'عمن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rp', '', 'N', 'N', 'N', 'O', '', '": عَاصِمَةُ الْمَمْلَكَةِ الأُرْدُنِيَّةِ الهَاشِمِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12463, 'عُمَانُ', 'عمان', 'جامد', '', 'عمان', 'عمن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rp', '', 'N', 'N', 'N', 'O', '', '": ""سَلْطَنَةُ عُمان"" : مِنْ بِلاَدِ الْعَرَبِ، تَقَعُ فِي جَنُوبِ شَرْقِيِّ الْجَزِيرَةِ الْعَرَبِيَّةِ عَلَى الْخَلِيجِ الْعَرَبِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12464, 'عَامِدٌ', 'عامد', 'جامد', 'عمد', 'عامد', 'عمد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عَامِدٌ-عَامِدٌ [ع م د] (هن). 1. : الْخَطُّ النَّازِلُ عَمُودِيّاً مِنْ مَرْكَزٍ مُضَلَّعٍ مُنْتَظِمٍ عَلَى أَحَدِ أَضْلاَعِهِ. 2. : الْخَطُّ النَّازِلُ عَمُودِيّاً مِنْ رَأْسِ هَرَمٍ مُنْتَظِمٍ عَلَى أَحَدِ ضُلُوعِ مُضَلَّعِ قَاعِدَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12465, 'عِمَادَةٌ', 'عمادة', 'جامد', 'عمد', 'عمادة', 'عمدة', '', '', '', 'مفرد', 'DnN', '', '', '"عِمَادٌ"', '', 'R', '', '', '', '', '', '', '". 1. : الأَبْنِيَةُ الْعَالِيَةُ الْمُرْتَفِعَةُ. 2.""أَصْحَابُ الْعِمَادِ"" : أَصْحَابُ الأَبْنِيَةِ الْعَالِيَةِ.الفجر آية 7إِرَمَ ذَاتِ الْعِمَادِ (قرآن). 3. ""إدارَةُ العِمادَةِ"" : إِدارَةُ عَمِيدِ الْكُلِّيَّةِ أَوِ الْجَامِعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12466, 'عِمَادٌ', 'عماد', 'جامد', '', 'عماد', 'عمد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12467, 'عِمَادٌ', 'عماد', 'جامد', 'عمد', 'عماد', 'عمد', '', '', '', 'مفرد', 'DnN', '', '', '"عَمَدٌ:عُمُدٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِسْتَنَدَ إِلَى الْعِمَـادِ"" : السَّارِيةُ، الْخَشَبَةُ. 2.""عِمَادُ الدِّينِ"" : أَسَاسُهُ. 3.""هُوَ رَفِيعُ الْعِمَادِ"" : شَرِيفٌ. 4.""عِمَادُ الصَّبِيِّ فِي الدِّينِ الْمَسِيحِيِّ "" : غَسْلُهُ بِمَاءِ الْمَعْمُودِيَّةِ. 5.""عِمَادُ الرُّكْنِ"" : رَئِيسُ العَسْكَرِ، وَهِيَ رُتْبَةٌ عَسْكَرِيَةٌ عُلْيَا. 6. : اِسْمُ عَلَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12468, 'عَمَدٌ', 'عمد', 'جامد', '', 'عمد', 'عمد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12469, 'عُمُدٌ', 'عمد', 'جامد', '', 'عمد', 'عمد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12470, 'عُمْدَةٌ', 'عمدة', 'جامد', 'عمد', 'عمدة', 'عمدة', '', '', '', 'مفرد', 'DnN', '', '', '"عُمَدٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هُوَ عُمْدَةُ أَهْلِهِ"" : رُكْنُهَا الَّذِي يُتَّكَلُ عَلَيْهِ. 2.""أَنْتَ عُمْدَتُنَا فِي الشَّدَائِدِ"" : أَيْ مَنْ نَعْتَمِدُ عَلَيْهِ وَنَسْتَنِدُ إِلَيْهِ. 3.""عُمْدَةُ الْقَرْيَةِ"" : هُوَ عِنْدَ المِصْرِيِّينَ بِمَثَابَةِ شَيْخِ الْبَلَدِ. 4.""عُمْدَةُ الْكَلاَمِ"" : أَيْ مَا لاَ يَصِحُّ حَذْفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12471, 'عُمَدٌ', 'عمد', 'جامد', '', 'عمد', 'عمد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12472, 'عَمُودٌ', 'عمود', 'جامد', 'عمد', 'عمود', 'عمد', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْمِدَةٌ:عُمُدٌ:عَمَدٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَعْمِدَةُ الْبَيْتِ"": مَا يَقُومُ عَلَيْهِ. 2.""أَعْمِدَةُ القَصْرِ"" : سَوَارِيهِ. 3.""الْعَمُودُ الْكَهْرَبَائِيُّ"" : الْقَضِيبُ الْحَدِيدِيُّ. 4.""الْعَمُودُ الْفِقْرِيُّ"" : سِلْسِلَةٌ عَظْمِيَّةٌ عِنْدَ الإِنْسَانِ وَالْحَيَوَانِ تَمْتَدُّ مِنْ قَاعِدَةِ الْجُمْجُمَةِ إِلَى مَنْبِتِ الفَخِذَيْنِ. 5.""عَمُودُ الشِّعْرِ"" : الشِّعْرُ الْقَائِمُ عَلَى الْقَافِيَةِ وَالأَوْزَانِ الشِّعْرِيَّةِ الْمَوْرُوثَةِ عَنِ الْعَـرَبِ. 6.""عَمُودُ الإِشَارَةِ"" : قَضِيبٌ حَدِيدِيٌّ بِأَعْلاَهُ ذِرَاعٌ يُشَارُ بِهَا إِلَى أَنَّ الطَّرِيقَ مَفْتُوحٌ. 7. ""عَمُودُ المِيزَانِ"" : مَا تُعَلَّقُ كَفّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12473, 'أَعْمِدَةٌ', 'أعمدة', 'جامد', '', 'ءعمدة', 'عمدة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
