INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12475, 'عَمَدٌ', 'عمد', 'جامد', '', 'عمد', 'عمد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12476, 'عَمَارَةٌ', 'عمارة', 'جامد', 'عمر', 'عمارة', 'عمرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُمَارَةٌ-عُمَارَةٌ [ع م ر]. ""أَخَذَ الْعَامِلُ عُمَارَتَهُ"" : أُجْرَتَهُ فِي بِنَاءِ العِمَارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12477, 'عُمَارَةٌ', 'عمارة', 'جامد', 'عمر', 'عمارة', 'عمرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عَمَارَةٌ-عَمَارَةٌ [ع م ر]. ن. عَمَارٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12478, 'عَمَارٌ', 'عمار', 'جامد', 'عمر', 'عمار', 'عمر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَمَارٌ-عَمَارٌ [ع م ر]. 1. : رَيْحَانٌ يُحَيَّى بِهِ الْمَلِكُ مَعَ قَوْلِ : ""عَمَّرَكَ اللَّهُ"". 2. : رُقْعَةٌ مُزَيَّنَةٌ تُحَاطُ بِالْمِظَلَّةِ. 3. : كُلُّ شَيْءٍ عَلَى الرَّأْسِ مِنْ عِمَامَةٍ أَوْ قَلَنْسُوَةٍ وَمَا إِلَى ذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12479, 'عُمْرَةٌ', 'عمرة', 'جامد', 'عمر', 'عمرة', 'عمرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":عُمَرٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""أَدَّى مَنَاسِكَ الْعُمْرَةِ"" : هُوَ مَا يُعْرَفُ بِالْحَجِّ الأَصْغَرِ، وَمَنَاسِكُهُ أَرْبَعَةٌ : الإِحْرَامُ وَالطَّوَافُ وَالسَّعْيُ بَيْنَ الصَّفَا وَالْمَرْوَةِ وَالْحَلْق. 2.:القَصْدُ إِلَى مَكَانٍ عَامِرٍ. 3.""عُمَرُ"" : اِسْمُ عَلَمٍ لِلْمُذَكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12480, 'عُمَرٌ', 'عمر', 'جامد', '', 'عمر', 'عمر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12481, 'عُمُرٌ', 'عمر', 'جامد', 'عمر', 'عمر', 'عمر', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْمَارٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَطَالَ اللَّهُ عُمْرَهُ"": أَطَالَ لَهُ حَيَاتَهُ. ""تَمَنَّى لَهُ طُولَ الْعُمْرِ"" ""هِيَ الأَعْمَارُ بِيَدِ اللَّهِ"". 2.""عُمْرُها سَبْعُ سَنَواتٍ"" : سِنُّها. ""صَارَ عُمْرِي خَمْسَ عَشْرَةَ، صِرْتُ أَحْلَى أَلْفَ مَرَّةٍ"". (نزار قباني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12482, 'أَعْمَارٌ', 'أعمار', 'جامد', '', 'ءعمار', 'عمر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12483, 'عَمِيرَةٌ', 'عميرة', 'جامد', 'عمر', 'عميرة', 'عمرة', '', '', '', 'مفرد', 'DnN', '', '', '"عَمَائِرُ"', '', '', '', 'N', 'O', 'O', 'O', '', '". ""عَمِيَرةُ النَّحْلِ"" : مَجْمُوعُ خَلاَيَاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12484, 'عَمَائِرُ', 'عمائر', 'جامد', '', 'عماءر', 'عمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12485, 'مَعْمُورَةٌ', 'معمورة', 'جامد', 'عمر', 'معمورة', 'معمرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَعْمُورَةٌ-مَعْمُورَةٌ [ع م ر]. 1.""اِسْتَقَرَّ فِي الْمَعْمُورَةِ"" : الدَّارُ، أَوِ الدَّارُ الآهِلَةُ بِالسُّكَّانِ. 2. ""فِي أَرْجَاءِ الْمَعْمُورَةِ"" : فِي العَالَمِ، الدُّنْيَا، الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12486, 'عُمَالَةٌ', 'عمالة', 'جامد', 'عمل', 'عمالة', 'عملة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُمَالَةٌ-عُمَالَةٌ [ع م ل]. ""سَلَّمَهُ عُمَالَتَهُ فِي آخِرِ الشَّهْرِ"" : أُجْرَة الْعَامِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12487, 'عِمَالَةٌ', 'عمالة', 'جامد', 'عمل', 'عمالة', 'عملة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""عِمَالَةُ الإِقْلِيمِ"" : الْمَرْكَزُ الإِدَارِيُّ لِلعامِلِ، أي حاكِمُ الإِقْليمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12488, 'عِمَالَةٌ', 'عمالة', 'جامد', 'عمل', 'عمالة', 'عملة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عِمَالَةٌ-عِمَالَةٌ [ع م ل]. 1.""يَتَقَاضَى عِمَالَةً عَلَى عَمَلِهِ الْيَوْمِيِّ"": أُجْرَة الْعَامِلِ. 2.""تَقَاضَى عِمَالَتَهُ"" : مَا يَأْخُذُهُ الْوَسِيطُ لِقَاءَ صَفْقَةِ بَيْعٍ أَوْ شِرَاءٍ. 3. : حِرْفَةُ العامِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12489, 'عُمْلَةٌ', 'عملة', 'جامد', 'عمل', 'عملة', 'عملة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""عُمْلَةُ الْعَامِلِ"": أُجْرَتُهُ. 2.""يَحْتَفِظُ بِعُمْلَةٍ أَجْنَبِيَّةٍ"" : بِنُقُودٍ أَجْنَبِيَّةٍ. ""العُمْلَةُ الصَّعْبَةُ"". 3.""الْعُمْلَةُ الْوَطَنِيَّةُ"" : النَّقْدُ الَّذِي يُتَعَامَلُ بِهِ فِي الْبَيْعِ وَالشِّرَاءِ دَاخِلَ الْبِلاَدِ، قِطَعٌ مَعْدِنِيَّةٌ أَوْ وَرَقِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12490, 'عَمَلِيَّةٌ', 'عملية', 'جامد', 'عمل', 'عملية', 'عملة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1. ""أَجْرَى الطَّبِيبُ عَمَلِيَّةً جِرَاحِيَّةً"" : مَا يَقُومُ بِهِ الطَّبِيبُ مِنْ أَعْمَالٍ جِرَاحِيَّةٍ لِمُعَالَجَةِ جِسْمِ الْمَرِيضِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12491, 'مِعْمَارٌ', 'معمار', 'جامد', 'عمر', 'معمار', 'معمر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِعْمَارٌ-مِعْمَارٌ [ع م ر]. ""يَهْتَمُّ بِالْمِعْمَارِ"" : بِبِنَاءِ العِمَارَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12492, 'عُمُولَةٌ', 'عمولة', 'جامد', 'عمل', 'عمولة', 'عملة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""أَخَذَ عُمُولَةً مِنْ أَجْلِ صَفْقَةٍ تِجَارِيَّةٍ قَامَ بِهَا "" : مَا يَأْخُذُهُ الْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12493, 'عَوَامِلُ', 'عوامل', 'جامد', 'عمل', 'عوامل', 'عمل', '', '', '', 'مفرد', '', '', '', '"مفردعَامِلَة"', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '". 1.""عَوَامِلُ الدَّابَّةِ"" : قَوَائِمُهَا، أَرْجُلُهَا. 2. : بَقَرٌ وَإِبِلٌ تُسْتَعْمَلُ فِي السَّقْيِ وَالْحَرْثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12494, 'مُعَامِلٌ', 'معامل', 'جامد', 'عمل', 'معامل', 'معمل', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.: عَدَدٌ مُحَدِّدٌ لِقِيمَةِ كُلِّ مَادَّةٍ مِنْ مَوَادِّ امْتِحَانٍ مَّا. 2. : الْمُعَامِلُ فِي الرِّيَاضِيَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12495, 'مَعْمَلٌ', 'معمل', 'جامد', 'عمل', 'معمل', 'معمل', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَامِلُ"', '', 'Rp', '', '', '', '', '', '', '". ""يَشْتَغِلُ فِي الْمَعْمَلِ"" : مَوْضِعُ العَمَلِ، ويُطْلَقُ عَلَى الْمَكَانِ الَّذِي تُوجَدُ بِهِ آلاَتُ التَّصْنِيعِ وتُصْنَعُ فِيهِ الآلاَتُ ومُخْتَلِفُ الْمَوَادِّ الصِّنَاعِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12496, 'مَعَامِلُ', 'معامل', 'جامد', '', 'معامل', 'معمل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12497, 'عِمْلاَقٌ', 'عملاق', 'جامد', 'عملق', 'عملاق', 'عملق', '', '', '', 'مفرد', 'DnN', '', '', '"عَمَالِقَةٌ"', '', 'R', '', '', '', '', '', '', '". ""رَجُلٌ عِمْلاَقٌ"" : طَوِيلُ الْقَامَةِ ضَخْمُ الْجُثَّةِ. ""كَانَ الْجَيْشُ عِمْلاَقاً، وَحْشاً بَشَرِيّاً""."', '');
