INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12502, 'عَوَامُّ', 'عوام', 'جامد', 'عمم', 'عوام', 'عم', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '"عَوَامُّ-عَوَامُّ [ع م م]. ""جُمْهُورُ الْعَوَامِّ"" : عَامَّةُ النَّاسِ. ""لُغَةُ الْعَوَامِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12503, 'عَمَاءٌ', 'عماء', 'جامد', 'عمي', 'عماء', 'عم', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', 'N', 'O', 'O', 'O', '', '"عَمَاءٌ-عَمَاءٌ [ع م ي]. ""سَالَ الْعَمَاءُ"" : السَّحَابُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12504, 'عَمِيَّةٌ', 'عمية', 'جامد', 'عمي', 'عمية', 'عمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَمِيَّةٌ-عَمِيَّةٌ [ع م ي]. ""هُمْ فِي عَمِيَّةٍ"" : فِي ضَلاَلٍ وَغَوَايَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12505, 'عُنَّابٌ', 'عناب', 'جامد', '', 'عناب', 'عنب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عُنَّابُ-الْعُنَّابُ (نب). : شَجَرٌ مِنْ فَصِيلَةِ النَّبْقِيَّاتِ، شَائِكٌ، يَبْلُغُ ارْتِفَاعُهُ سِتَّةَ أَمْتَارٍ، يُعْطِي ثَمَراً أَحْمَرَ يُعْرَفُ بِهِ، لَذِيذُ الطَّعْمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12506, 'عَنَاقٌ', 'عناق', 'جامد', '', 'عناق', 'عنق', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَعْنُقٌ:عُنُوقٌالأُنْثَىمِنْ', '', 'R', '', '', '', '', '', '', '"ج: أَعْنُقٌ، عُنُوقٌ. : الأُنْثَى مِنْ أَوْلاَدِ الْمَاعِزِ وَالْغَنَمِ قَبْلَ بُلُوغِهَا السَّنَةَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12507, 'أَعْنُقٌ', 'أعنق', 'جامد', '', 'ءعنق', 'عنق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
