INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12509, 'عَنَانٌ', 'عنان', 'جامد', '', 'عنان', 'عنن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عَنَانٌ-عَنَانٌ [ع ن يِهَاعَنَانُ السَّمَاءِ"" : مَا يَبْدُو لَكَ مِنَ السَّمَاءِ إِذَا نَظَرْتَ إِلَيْهَا. ""عَنَانُ السَّحَابِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12510, 'عُنَّابَةٌ', 'عنابة', 'جامد', 'عنب', 'عنابة', 'عنبة', '', '', '', 'مفرد', 'DnN', '', '', '"واحدة(الْعُنَّابِ)"', '', 'R', '', '', '', '', '', '', '"عُنَّابَةٌ-عُنَّابَةٌ [ع ن ب]. وَاحِدَةُ (الْعُنَّابِ).: ثَمَرَةُ العُنَّابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12511, 'عِنَبٌ', 'عنب', 'جامد', 'عنب', 'عنب', 'عنب', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"أَعْنَابٌ"', '', 'R', '', '', '', '', '', '', '". 1.: ثَمَرُ الْكَرْمِ وَيَكُونُ أَبْيَضَ اللَّوْنِ أَوْ أَسْوَدَ أَوْ أُرْجُوَانِيّاً يُصْنَعُ مِنْـهُ الخَمْـرُ وَبَعْضُ الْمُرَبَّيَاتِ بِالسُّكَّرِ. 2.""تَتَدَلَّى عَنَاقِيـدُ الْعِنَبِ مِنَ الْكَرْمِ"" : كَرْمُ الْعِنَبِ. ""لاَ يُثْمِرُ الشَّوْكُ العِنَبَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12512, 'أَعْنَابٌ', 'أعناب', 'جامد', '', 'ءعناب', 'عنب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12513, 'عَنْبَرٌ', 'عنبر', 'جامد', '', 'عنبر', 'عنبر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"عَنَابِرُ"', '', 'R', '', '', '', '', '', '', '"ج: عَنَابِرُ. 1. : طِيبٌ وَهُوَ مَادَّةٌ صُلْبَةٌ لاَ طَعْمَ لَهَا وَ لاَ رِيحَ إِلاَّ إِذَا أُحْرِقَتْ أَوْ سُحِقَتْ. 2. : حَيَوَانٌ بَحْرِيٌّ مِنْ فَصِيلَةِ الْقِيطُسِيَّاتِ، مِنْ رُتْبَةِ الْحِيتَانِ، ضَخْمُ الرَّأْسِ، لَهُ أَسْنَانٌ بِخِلاَفِ الْبَالِ، يُقَالُ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12514, 'عَنَابِرُ', 'عنابر', 'جامد', '', 'عنابر', 'عنبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12515, 'عَنْتَرٌ', 'عنتر', 'جامد', 'عنتر', 'عنتر', 'عنتر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'Rp', '', 'N', 'O', 'O', 'O', '', '"عَنْتَرٌ-عَنْتَرٌ، ةٌ [ع ن ت ر]. : ذُبَابٌ أَزْرَقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12516, 'عَنْدَلِيبٌ', 'عندليب', 'جامد', '', 'عندليب', 'عندلب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"عَنَادِلُ"', '', 'R', '', '', '', '', '', '', '"ج: عَنَادِلُ. (حو). : طَائِرٌ مِنْ فَصِيلَةِ الدُّخَّلِيَّاتِ، صَغِيرُ الْحَجْمِ، جَمِيلُ الصَّوْتِ كَثِيرُ الْحَرَكَةِ وَالتَّنَقُّلِ فِي الحَدَائِقِ وَالْغَابَاتِ، يَظْهَرُ مَعَ بِدَايَةِ الرَّبِيعِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12517, 'عَنَادِلُ', 'عنادل', 'جامد', '', 'عنادل', 'عندل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12518, 'عَنَزَةٌ', 'عنزة', 'جامد', 'عنز', 'عنزة', 'عنزة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":عَنَزٌ"', '', 'R', '', '', '', '', '', '', '". 1.""طَعَنَهَ بِالْعَنَزَةِ"" : عَصاً مِثْلُ العُكَّازَةِ، قَصِيرَةٌ تُشْبِهُ الرُّمْحَ، لَهَا حَدِيدَةٌ فِي أَسْفَلِهَا يُتَوَكَّأُ عَلَيْهَا. 2.""عَنَزَةُ الْفَأْسِ"" : حَدُّهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12519, 'عَنَزٌ', 'عنز', 'جامد', '', 'عنز', 'عنز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12520, 'عُنْصُرٌ', 'عنصر', 'جامد', 'عنصر', 'عنصر', 'عنصر', '', '', '', 'مفرد', 'DnN', '', '', '"عَنَاصِرُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""رَجُلٌ كَرِيمُ الْعُنْصُرِ"" : كَرِيمُ الأَصْلِ وَالْحَسَبِ. 2.""هُوَ مِنَ الْعُنْصُرِ الْعَرَبِيِّ"": مِنَ الجِنْسِ... ""لِكُلِّ إِنْسَانٍ حَقُّ التَّمَتُّعِ بِكَافَّةِ الْحُقُوقِ وَالْحُرِّيَّاتِ دُونَمَا تَمْيِيزٍ مِنْ أَيِّ نَوْعٍ، وَلاَ سِيَّمَا التَّمْيِيزُ بِسَبَبِ الْعُنْصُرِ"". (الإعْلاَنُ العَالَمِيُّ لِحُقُوقِ الإنْسَانِ). 3.""الأ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12521, 'عَنَاصِرُ', 'عناصر', 'جامد', '', 'عناصر', 'عنصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12522, 'عَنْفَقَةٌ', 'عنفقة', 'جامد', 'عنفق', 'عنفقة', 'عنفقة', '', '', '', 'مفرد', 'DnN', '', '', '"عَنَافِقُ"', '', '', '', '', '', '', '', '', '". : شُعَيْرَاتٌ بَيْنَ الشَّفَةِ السُّفْلَى وَالذَّقَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12523, 'عَنَافِقُ', 'عنافق', 'جامد', '', 'عنافق', 'عنفق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12524, 'عُنْفُوَانٌ', 'عنفوان', 'جامد', '', 'عنفوان', 'عنفن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"""مَا يَزَالُ فِي عُنْفُوَانِ شَبَابِهِ"" : فِي أَوَّلِهِ، فِي أَوْجِهِ، في رَيْعَانِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12525, 'عُنُقٌ', 'عنق', 'جامد', 'عنق', 'عنق', 'عنق', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْنَاقٌ(مؤ:مذ)"', '', 'R', '', '', '', '', '', '', '". 1.""عُنُقُ الإِنْسَانِ"" : رَقَبَتُهُ. ""كَأَنَّ عُنُقَهَا إِبْرِيقُ فِضَّةٍ"". (الجاحظ). 2.""عُنُقُ الزُّجَاجَةِ"" : الْجُزْءُ الأَعْلَى مِنْهَا، وَتُسْتَخْدَمُ كِنَايَةً عَنْ حُدُوثِ أَزْمَةٍ وَوُجُودِهَا فِي مَنْفَذٍ ضَيِّقٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12526, 'أَعْنَاقٌ', 'أعناق', 'جامد', '', 'ءعناق', 'عنق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12527, 'مِعْنَقَةٌ', 'معنقة', 'جامد', 'عنق', 'معنقة', 'معنقة', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَانِقُ"', '', 'R', '', '', '', '', '', '', '". ""فِي جِيدِهَا مِعْنَقَةٌ جَمِيلَةٌ"": مَا يُجْعَلُ فِي العُنُقِ مِنَ الحُلِيّ، عِقْدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12528, 'مَعَانِقُ', 'معانق', 'جامد', '', 'معانق', 'معنق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12529, 'عَنْكَبٌ', 'عنكب', 'جامد', '', 'عنكب', 'عنكب', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"عَنَاكِبُذَكَرُالْعَنْكَبُوتِ', '', 'R', '', '', '', '', '', '', '"ج: عَنَاكِبُ. 1. : ذَكَرُ الْعَنْكَبُوتِ. 2. : أُنْثَى الْعَنْكَبُوتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12530, 'عَنَاكِبُ', 'عناكب', 'جامد', '', 'عناكب', 'عنكب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12531, 'عَنْكَبُوتٌ', 'عنكبوت', 'جامد', '', 'عنكبوت', 'عنكبت', '', '', '', 'جمع تكسير', 'DnN', '', '', '"عَنَاكِبُ"', '', 'R', '', '', '', '', '', '', '"ج: عَنَاكِبُ. (حش). 1. : حَشَرَةٌ مِنْ فَصِيلَةِ الْعَنْكَبِيَّاتِ لَهَا أَرْبَعَةُ أَزْوَاجٍ مِنَ الأَرْجُلِ، تَنْسُـجُ مِنْ لُعَابِهَـا خُيُوطاً رَقِيقَةً، تَبْنِي بِهَا بَيْتاً، تُطَارِدُ الحَشَرَاتِ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12532, 'عَنَاكِبُ', 'عناكب', 'جامد', '', 'عناكب', 'عنكب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12533, 'عَنْكَبِيَّاتٌ', 'عنكبيات', 'جامد', '', 'عنكبيات', 'عنكبت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": قِسْمُ الْحَشَرَاتِ الْمِفْصَلِيَّةِ يَشْمُلُ الْعَنَاكِبَ وَالْعَقَارِبَ وَالقُمَّلَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12534, 'أَعْنَانٌ', 'أعنان', 'جامد', 'عنن', 'ءعنان', 'عنن', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"أَعْنَانٌ-أَعْنَانٌ [ع ن ن]. 1.""أعْنَانُ الشَّجَرِ"" : أطْرَافُهُ. 2.""أعْنانُ السَّمَاءِ"" : نوَاحِيها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12535, 'عُنْوَانٌ', 'عنوان', 'جامد', 'عنن', 'عنوان', 'عنن', '', '', '', 'مفرد', 'DnN', '', '', '"عَنَاوِينُ"', '', 'R', '', '', '', '', '', '', '". 1.""سُجِّلَ عُنْوَانُ الْكِتَابِ"" : أَي اِسْمُهُ وَسِمَتُهُ. 2.""أَخَذَ مِنْهُ عُنْوَانَ سُكْنَاهُ"" : اِسْمُ الشَّارِعِ وَرَقْمُ الْبَيْتِ. ""كَتَبَ العُنْوَانَ عَلَى ظَهْرِ الرِّسَالَةِ"". 3.""الظَّاهِرُ عُنْوَانُ الْبَاطِنِ"" : دَلِيلُهُ، سِمَتُهُ. ""مَا قَدَّمَهُ يُعْتَبَرُ عُنْوَاناً عَلَى كَرَمِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12536, 'عَنَاوِينُ', 'عناوين', 'جامد', '', 'عناوين', 'عنن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12537, 'عَهْرٌ', 'عهر', 'جامد', 'عهر', 'عهر', 'عهر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَهْرٌ-عَهْرٌ، عَهِرٌ، عِهْرٌ [ع هـ ر]. ""اِرْتَكَبَ عَهْراً"" : فُجُوراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12538, 'مَعْنًى', 'معنى', 'جامد', 'عني', 'معنى', 'معن', '', '', '', 'مفرد', 'Dy', '', '', '"مَعَانٍ:الْمَعَانِي"', '', 'RwR0', '', '', '', '', '', '', '". 1. ""مَعْنَى الكَلِمَةِ"" : مَدْلُولُهَا، أَيْ مَا تَدُلُّ عَلَيْهِ. ""كَلاَمٌ لاَ مَعْنَى لَهُ"". 2.""مَعْنـىً وَاضِحٌ"" : بَيِّنٌ مَعْرُوفٌ. ""مَعْنـىً غَامِضٌ"". 3.""الْمَعْنَى الْحَقِيقِيُّ لِلْكَلِمَةِ"" : التَّصَوُّرُ الذِّهْنِيُّ الْمُرْتَبِطُ بِالكَلِمَةِ ارْتِبَاطاً بِالْمُطَابَقَةِ. 4. ""الْمَعْنَى الضِّمْنِيُّ"" : التَّصَوُّرُ الذِّهْنِيُّ الْمُرْتَبِطُ بِالكَلِمَةِ بِالتَّضَمُّنِ أَوِ اللُّزُومِ. 5.""الْمَعْنَى الْمَجَازِيُّ"" : التَّصَوُّرُ الذِّهْنِيُّ الْمُرْتَبِطُ بِالكَلِمَةِ مَجَازِيّاً، اِسْتِعَارَةً. 6.""الْمَعْنَى الطَّبِيعِيُّ"" : التَّصَوُّرُ الْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12539, 'مَعَانِي', 'معاني', 'جامد', '', 'معاني', 'معن', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12540, 'عُنْيَةٌ', 'عنية', 'جامد', '', 'عنية', 'عنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"ج: ـات. ""عُنْيَةُ الدَّفْتَرِ أَوِ السِّلْعَةِ"" : وُرَيْقَةٌ صَغِيرَةٌ مُرَبَّعَةٌ أَوْ مُسْتَطِيلَةٌ تُلْصَقُ عَلَى الدَّفْتَرِ، وَيُكْتَبُ عَلَيْهَا اسْمُ صَاحِبِهِ وَمَادَّتُهُ، أَوْ عَلَى السِّلْعَةِ فَيُكْتَبُ عَلَيْهَا نَوْعُهَا وَثَمَنُهَا كَمَا تُلْصَقُ عَلَى الْحَقِيبَةِ لِيُكْتَبَ عَلَيْهَا اسْمُ صَاحِبِهَا وَعُنْوَانُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12541, 'عِهَادٌ', 'عهاد', 'جامد', 'عهد', 'عهاد', 'عهد', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"عِهَادٌ-عِهَادٌ، ةٌ [ع هـ د]. ""اِسْتَبْشَرَ الْفَلاَّحُ بِالْعِهَادِ أَوِ الْعِهَادَةِ"" : مَطَرُ أَوَّلِ السَّنَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12542, 'عُهْدَةٌ', 'عهدة', 'جامد', 'عهد', 'عهدة', 'عهدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُهْدَةٌ-عُهْدَةٌ [ع هـ د]. ""فِي عُهْدَتِهِ"" : تَحْتَ مَسْؤُولِيَّتِهِ، فِي رِعَايَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12543, 'مَعْهَدٌ', 'معهد', 'جامد', 'عهد', 'معهد', 'معهد', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاهِدُ"', '', 'R', '', '', '', '', '', '', '". ""يَدْرُسُ بِمَعْهَدِ كَذَا"" : مُؤَسَّسَةٌ لِلتَّعْلِيمِ والدِّرَاسَةِ والبَحْثِ. ""الْمَعْهَدُ الزِّرَاعِيُّ"" ""الْمَعْهَدُ الوَطَنِيُّ لِلدِّرَاسَاتِ والأَبْحَاثِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12544, 'مَعَاهِدُ', 'معاهد', 'جامد', '', 'معاهد', 'معهد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12545, 'عَادَةٌ', 'عادة', 'جامد', 'عود', 'عادة', 'عدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":عَوَائِدُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِنْ عَادَتِهِ أَنْ يَزُورَ أَهْلَهُ"" : مِنَ الْمَأْلُوفِ، مَا يَعْتَادُهُ الْمَرْءُ وَيُكَرِّرُهُ. 2.""هَذَا مَا جَرَتْ بِهِ الْعَادَةُ"" : هَذَا مَا جَرَى بِهِ التَّقْلِيدُ. ‎""حَسَبَ الْعَادَةِ"" ""يَحْتَرِمُ عَادَاتِ شَعْبِهِ"" ""إِنَّ النَّاسَ يَكْتَسِبُونَ عَلَى رَأْسِ كُلِّ مِائَةِ سَنَةٍ عَادَةً جَدِيدَةً"". (التوحيدي). 3.""الْعَادَةُ الشَّهْرِيَّةُ"" : حَيْضُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12546, 'عَوَائِدُ', 'عوائد', 'جامد', '', 'عواءد', 'عد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12547, 'عَوَاهِنُ', 'عواهن', 'جامد', 'عهن', 'عواهن', 'عهن', '', '', '', 'مفرد', '', '', '', '"مفردعَاهِن"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""أَلْقَى الْكَلاَمَ عَلَى عَوَاهِنِهِ"" : أَلْقَاهُ بِلاَ تَفْكِيرٍ وَلاَ رَوِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12548, 'عَاهِن', 'عاهن', 'جامد', '', 'عاهن', 'عهن', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12549, 'عَوَائِدُ', 'عوائد', 'جامد', 'عود', 'عواءد', 'عد', '', '', '', 'مفرد', '', '', '', '"مفردعَائِد"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""عَوَائِدُ الدَّوْلَةِ مِنَ الضَّرَائِبِ"" : الدَّخْلُ، مَا يَعُودُ عَلَيْهَا مِنَ الضَّرَائِبِ. 2.""عَوَائِدُ الْجُمْرُكِ"" : رُسُومُ الْجُمْرُكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12550, 'عَوَائِدُ', 'عوائد', 'جامد', 'عود', 'عواءد', 'عد', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"عَوَائِدُ-عَوَائِدُ [ع و د]. : أَرْبَعَةُ كَوَاكِبَ وَسَطُهَا كَوْكَبٌ يُسَمَّى الرُّبَعَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12551, 'عُودٌ', 'عود', 'جامد', 'عود', 'عود', 'عد', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْوَادٌ:عِيدَانٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""قَطَعَ عُوداً"" : غُصْناً. 2.""حَطَبَ الْعُودَ"" : كُلُّ خَشَبَةٍ، دَقِيقَةً كَانَتْ أَوْ غَلِيظَةً، رَطْبَةً كَانَتْ أَوْ يَابِسَةً. 3.""تَبَخَّرَت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12552, 'أَعْوَادٌ', 'أعواد', 'جامد', '', 'ءعواد', 'عد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12553, 'عِيدَانٌ', 'عيدان', 'جامد', '', 'عيدان', 'عدن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12554, 'عِيدٌ', 'عيد', 'جامد', 'عود', 'عيد', 'عد', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْيَادٌ"', '', 'R', '', '', '', '', '', '', '". 1.""حَلَّ يَوْمُ الْعِيدِ"" : يَوْمٌ لِلاحْتِفَالِ وَالتَّذْكَارِ بِحَادِثٍ دِينِيٍّ أَوْ تَارِيخِيٍّ مُهِمٍّ. ""عِيدُ الأَضْحَى"" ""عِيدُ الْمِيلاَدِ"" ""عِيدُ الْفِطْرِ"" ""عِيدُ الْمَوْلِدِ النَّبَوِيِّ"" ""عِيدُ الاسْتِقْلاَلِ"". 2.""أَدْعُوكَ لِحُضُورِ عِيدِ مِيـلاَدِي"" : ذِكْرَى يَوْمَ وُلِدْتُ. 3.""أَمْرُهُ عِيدٌ"" : مَا يُعُودُ الإِنْسَانَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12555, 'أَعْيَادٌ', 'أعياد', 'جامد', '', 'ءعياد', 'عد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12556, 'عَاجٌ', 'عاج', 'جامد', 'عوج', 'عاج', 'عج', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَاجٌ-عَاجٌ [ع و ج]. ""تُحَفٌ فَنِّيَّةٌ مَصْنُوعَةٌ مِنَ الْعَاجِ"" : مِنْ أَنْيَابِ الْفِيلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12557, 'عَوَاذٌ', 'عواذ', 'جامد', 'عوذ', 'عواذ', 'عذ', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَوَاذٌ-عَوَاذٌ [ع و ذ]. ""فِي قَلْبِه عَوَاذٌ"" : كَرَاهَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12558, 'عُوذَةٌ', 'عوذة', 'جامد', 'عوذ', 'عوذة', 'عذة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عُوذَةٌ-عُوذَةٌ [ع و ذ]. ""كَتَبَ لَهُ الْعُوذَةَ"" : الرُّقْيَةُ فِي الاِعْتِقَادِ القَدِيمِ تُقْرَأُ أَوْ تُكْتَبُ، وَتُعَلَّقُ عَلَى الإِنْسَانِ لِوِقَايَتِهِ مِنَ الشَّرِّ وَالْجِنِّ، التَّمِيمَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12559, 'عَوْذٌ', 'عوذ', 'جامد', 'عوذ', 'عوذ', 'عذ', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَوْذٌ-عَوْذٌ [ع و ذ]. 1. ""عَوْذٌ بِاللَّهِ مِنْكَ"" : لِيَحْفَظْنِي اللَّهُ مِنْكَ، أَيْ أَعُوذُ بِاللَّهِ مِنْكَ. 2. ""وَجَدَ عِنْدَهُمْ عُوذاً"" : مَلْجَأً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12560, 'عَارَةٌ', 'عارة', 'جامد', 'عور', 'عارة', 'عرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَارَةٌ-عَارَةٌ [ع و ر]. : مَا تُعْطِيهِ غَيْرَكَ عَلَى أَنْ يُعِيدَهُ إِلَيْكَ. ""كُلُّ عَارَةٍ مُسْتَرَدَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12561, 'عَارِيَةٌ', 'عارية', 'جامد', 'عور', 'عارية', 'عرة', '', '', '', 'مفرد', 'DnN', '', '', '"عَوَارٍ"', '', '', '', '', '', '', '', '', '". : مَا تُعْطِيهِ غَيْرَكَ عَلَى أَنْ يُعِيدَهُ إِلَيْكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12562, 'عَوَارِي', 'عواري', 'جامد', '', 'عواري', 'عر', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12563, 'عَوْرَةٌ', 'عورة', 'جامد', 'عور', 'عورة', 'عرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". 1.""سَتَرَ عَوْرَتَهُ"" : سَتَرَ أَعْضَاءهُ التَّنَاسُلِيَّةَ. 2.""أَظْهَرَ عَوْرَتَهُ"" : عَيْبَهُ. 3.""دَارُهُ عَـوْرَةٌ"" : بِهَا خَلَلٌ يُخْشَى دُخُولُ الْعَدُوِّ مِنْهُ. الأحزاب آية 1"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12564, 'مِعْوَلٌ', 'معول', 'جامد', 'عول', 'معول', 'معل', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاوِلُ"', '', 'R', '', '', '', '', '', '', '". ""يَغْرِسُ مِعْوَلَهُ فِي الأَرْضِ ويُلَوِّحُ بِالتُّرَابِ بَعِيداً"": أَدَاةٌ تُحْفَرُ بِهَا الأَرْضُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12565, 'مَعَاوِلُ', 'معاول', 'جامد', '', 'معاول', 'معل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12566, 'عِيَالٌ', 'عيال', 'جامد', 'عول،عيل', 'عيال', 'عل', '', '', '', 'مفرد', '', '', '', '"مفردعَيِّل"', '', 'R', '', '', '', '', '', '', '". ""عِيَالُ الرَّجُلِ"" : أَهْلُ بَيْتِهِ، أَوْلاَدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12567, 'عَيِّل', 'عيل', 'جامد', '', 'عيل', 'عل', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12568, 'عَامٌ', 'عام', 'جامد', 'عوم', 'عام', 'عم', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْوَامٌ"', '', 'Rp', '', '', '', '', '', '', '". ""اِزْدَادَ فِي عَامِ كَذَا"" : فِي سَنَةِ...، الْحَوْلُ. ""مَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12569, 'أَعْوَامٌ', 'أعوام', 'جامد', '', 'ءعوام', 'عم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12570, 'عَوَّامَةٌ', 'عوامة', 'جامد', 'عوم', 'عوامة', 'عمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""يُقِيمُ فِي الْعَوَّامَةِ"" : بَيْتٌ عَلَى شَكْلِ مَرْكَبٍ عَائِمٍ فِي الْبَحْرِ أَوِ النَّهْرِ. 2.""ي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12571, 'مَعَامَةٌ', 'معامة', 'جامد', 'عوم', 'معامة', 'معمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""مَعَامَةُ السِّبَاحَةِ"" : لِبَاسٌ خَفِيفٌ يُغ"', '');
