INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12573, 'عَوْسَجَةٌ', 'عوسجة', 'جامد', '', 'عوسجة', 'عسجة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"واحدةالْعَوْسَجِ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '": وَاحِدَةُ الْعَوْسَجِ."', ':لا جذر:لا مفرد');
