INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12578, 'عَاهَةٌ', 'عاهة', 'جامد', 'عوه،عيه', 'عاهة', 'عهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""بِهِ عَاهَـةٌ"" : مُصَابٌ بِآفَةٍ وَمَرَضٍ ظَاهِرٍ لِلْعِيَانِ. 2.""عَاهَةٌ نَبَاتِيَّةٌ"": مَا يُصِيبُ الزَّرْع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12579, 'مَعَابٌ', 'معاب', 'جامد', 'عيب', 'معاب', 'معب', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَعَايِبُ"', '', 'R', '', '', '', '', '', '', '". ""فِيهِ مَعَابٌ كَبِيرٌ"": عَيْبٌ."', '');
