INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12582, 'أَعْيَارٌ', 'أعيار', 'جامد', '', 'ءعيار', 'عر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12583, 'عِيرٌ', 'عير', 'جامد', 'عير', 'عير', 'عر', '', '', '', 'مفرد', 'DnN', '', '', '"عِيرَاتٌ"', '', 'R', '', '', '', '', '', '', '". : قَافِلَةُ الْحَمِيرِ وَقَدْ تُطْلَقُ عَلَى كُلِّ الْقَوَافِلِ. ""هُوَ لاَ فِي الْعِ"', '');
