INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12586, 'مِعْيَارٌ', 'معيار', 'جامد', 'عير', 'معيار', 'معر', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَايِيرُ"', '', 'Rp', '', '', '', '', '', '', '". 1. ""لِكُلِّ مِقْيَاسٍ مِعْيَارٌ"": مِقْيَاسٌ أَسَاسِيٌّ، عِيَارٌ. 2. ""اِتَّخَذَ عَمَلَهُ الأَوَّلَ مِعْيَاراً"" : نَمُوذَجاً. ""خَضَعَ اخْتِيَارُ الْمُرَشَّحِينَ لِمَعَايِيرَ دَقِيقَةٍ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12587, 'مَعَايِيرُ', 'معايير', 'جامد', '', 'معايير', 'معر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12588, 'عِيَاطٌ', 'عياط', 'جامد', 'عيط', 'عياط', 'عط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عِيَاطٌ-عِيَاطٌ [ع ي ط]. ""كَثُرَ الْعِيَاطُ فِي السُّوقِ"" : الصِّيَاحُ وَالضَّجَّةُ وَاخِتلاَطُ الأَصْوَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12589, 'عَالَةٌ', 'عالة', 'جامد', 'عيل', 'عالة', 'علة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"عَالَةٌ-عَالَةٌ [ع ي ل]. 1.""يَعِيشُ فِي عَالَةٍ"" : فِي فَاقَةٍ. 2.""يَعِيشُ عَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12590, 'عَالٌ', 'عال', 'جامد', 'عيل', 'عال', 'عل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَالٌ-عَالٌ [ع ي ل]. ""مَا لَهُ عَالٌ وَلاَ مَالٌ"" : مَا لَهُ شَيْءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12591, 'عَيِّلٌ', 'عيل', 'جامد', 'عيل', 'عيل', 'عل', '', '', '', 'مفرد', 'DnN', '', '', '"عِيَالٌ"', '', 'R', '', '', '', '', '', '', '". 1.""عَيِّلُ الرَّجُلِ"" : أَهْلُ بَيْتِهِ الَّذِينَ يُؤَمِّنُ مَعَاشَهُمْ وَيَكْفُلُهُمْ وَيُنْفِقُ عَلَيْ"', '');
