INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12593, 'أعْيانٌ', 'أعيان', 'جامد', 'عين', 'ءعيان', 'عن', '', '', '', 'مفرد', '', '', '', '"مفردعَيْن"', '', '', '', '', '', '', '', '', '". ""حَضَرَ أعْيَانُ الْمَدِينَةِ"" : كِبَارُ الْمَدِينَةِ، أشْرَافُهَا، أَفاضِلُها. ""اِجْتَمَعَ أعْيانُ القَوْمِ فِي القَصْرِ البَلَدِيِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12594, 'عَيْن', 'عين', 'جامد', '', 'عين', 'عن', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12595, 'عُيُونٌ', 'عيون', 'جامد', 'عين', 'عيون', 'عن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُيُونٌ-عُيُونٌ [ع ي ن]. ""عُيُونُ البَقَرِ"" : نَوْعٌ مِنَ العِنَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12596, 'عَيِّنَةٌ', 'عينة', 'جامد', 'عين', 'عينة', 'عنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""عَيِّنَةُ ثَوْبٍ"" : مَا يُؤْخَذُ مِنْهُ نَمُوذَجاً لِسَائِرِهِ بِخَصَائِصِهِ وَصِفَاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12597, 'عَيْنِيَّةٌ', 'عينية', 'جامد', 'عين', 'عينية', 'عنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""عَيْنِيَّةُ الفَرَسِ"" : جِلْدَةٌ تُرَكَّبُ فِي رَأْسِيَّةِ الفَرَسِ وَنَحْوِهِ فَتَمْنَعُهُ مِنَ النَّظَرِ إِلَى جَانِب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12598, 'غَارِيَّاتٌ', 'غاريات', 'جامد', '', 'غاريات', 'غرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ، وَهِيَ تَشْمُلُ الغَارَ وَالقَرْفَةَ وَ الكَافُورَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12599, 'غَازٌ', 'غاز', 'جامد', '', 'غاز', 'غز', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ج: ات. (كيما).: كُلُّ سَائِلٍ كَالْهَوَاءِ وَالأُكْسِجِينِ وَثَانِي أُكْسِيدِ الكَرْبُونِ، لاَ لَوْنَ لَهُ يَشْغَلُ كُلَّ حَيِّزٍ يُوضَعُ فِيهِ وَيَتَشَكَّلُ بِشَكْلِهِ. 1.""غَازُ الفَحْمِ"" : مَخْلُوطٌ مِنَ الغَازَاتِ يُسْتَعْمَلُ فِي الْمَوَاقِدِ وَالإِنَارَةِ. 2.""غَازُ الاسْتِصْبَاحِ"" : كُلُّ غَازٍ يُسْتَخْدَمُ فِي الإِضَاءةِ بِإِشْعَالِهِ. 3.""غَازُ الْخَرْدَلِ"" : غَازٌ سَامٌّ يُسْتَعْمَلُ فِي الْحُرُوبِ. 4.""غَازٌ طَبِيعِيٌّ"" : غَازٌ يُسْتَخْرَجُ مِنْ بَاطِنِ الأَرْضِ وَيُسْتَخْدَمُ مُبَاشَرَةً دُونَ تَصْنِيعٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12600, 'غَاقٌ', 'غاق', 'جامد', '', 'غاق', 'غق', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"غَاقٌ-غَاقٌ، ةٌ (حو).: طَائِرٌ أَسْوَدُ مِنْ فَصِيلَةِ البَجَعِيَّاتِ، وَرُتْبَةِ كَفِّيَّاتِ القَدَمِ، مِنْ طُيُورِ الْمَاءِ، يَصِيدُ السَّمَكَ وَيَقْتَاتُ بِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12601, 'غُبٌّ', 'غب', 'جامد', 'غبب', 'غب', 'غب', '', '', '', 'مفرد', 'DnN', '', '', '"أَغْبَابٌ:غُبُوبٌ:غُبَّانٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""طَغَى الْغُبُّ"" : مَاءُ البَحْرِ الطَّاغِي عَلَى الشَّاطِئِ. 2.: الوَادِي الَّذِي مَلأَهُ مَاءُ البَحْرِ. ""أَصَابَنَا مَطَرٌ سَالَ مِنْهُ الغُبَّانُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12602, 'أَغْبَابٌ', 'أغباب', 'جامد', '', 'ءغباب', 'غبب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12603, 'غُبُوبٌ', 'غبوب', 'جامد', '', 'غبوب', 'غبب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12604, 'غُبَّانٌ', 'غبان', 'جامد', '', 'غبان', 'غبن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12605, 'مَغَبَّةٌ', 'مغبة', 'جامد', 'غبب', 'مغبة', 'مغبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"مَغَبَّةٌ-مَغَبَّةٌ [غ ب ب]. ""حَذَّرَهُ مِنْ مَغَبَّةِ سُلُوكِهِ وتَصَرُّفِهِ الْمَشِينِ"" : العَاقِبَةُ، النِّهَايَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12606, 'غُبَارٌ', 'غبار', 'جامد', 'غبر', 'غبار', 'غبر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غُبَارٌ-غُبَارٌ [غ ب ر]. 1.""اِنْتَشَرَ الغُبَارُ فِي السَّاحَةِ"" : مَادَّةٌ مِنَ التُّرَابِ أَوِ الرَّمَادِ. 2.""القَضِيَّةُ وَاضِحَةٌ لاَ غُبَارَ عَلَيْهَا"" : لاَ غُمُوضَ وَلاَ الْتِبَاسَ بِهَا. 3.""لاَ يُشَقُّ لَهُ غُبَارٌ"" : لاَ مَثِيلَ لَهُ، مِنَ الصَّعْبِ التَّفَوُّقُ عَلَيْهِ. 4.""طَلَبَهُ فَمَا شَقَّ غُبَارَهُ"" : أَيْ لَمْ يُدْرِكْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12607, 'غَبَرَةٌ', 'غبرة', 'جامد', 'غبر', 'غبرة', 'غبرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"غُبْرَةٌ-غُبْرَةٌ [غ ب ر] (مص. غَبر). 1.""تَحَوَّلَ الْجَوُّ غُبْرَةً"" : أَيْ تَحَوَّلَ الْجَوُّ إِلَى لَوْنِ الغُبَارِ. 2.""اِنْتَشَرَتِ الغُبْرَةُ فِي الفَضَاءِ"" : الغُبَارُ. 3.""يَمِيلُ لَوْنُهُ إِلَى الغُبْرَةِ"" : يَمِيلُ لَوْنُهُ إِلَى لَوْنِ الغُبَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12608, 'غَارٌ', 'غار', 'جامد', '', 'غار', 'غر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"غَارٌ-غَارٌ (نب). : شَجَرٌ مِنْ فَصِيلَةِ الغَارِيَّاتِ، بَرِّيٌّ، ثِمَارُهُ تُشْبِهُ ثِمَارَ الزَّيْتُونِ، يُسْتَخْرَجُ مِنْهَا زَيْتٌ يَدْخُلُ فِي مُكَوِّنَاتِ صِنَاعَةِ الصَّابُونِ وَالْمَوَادِّ الْمُعَطَّرَةِ، كَانَ الْمُنْتَصِرُونَ فِي الْحُرُوبِ يَتَّخِذُونَ مِنْ أَوْرَاقِهِ أَكَالِيلَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12609, 'غُبْشَةٌ', 'غبشة', 'جامد', 'غبش', 'غبشة', 'غبشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"غُبْشَةٌ-غُبْشَةٌ [غ ب ش]. 1.""عَادَ إِلَى بَيْتِهِ مَعَ غُبْشَةِ اللَّيْلِ"" : مَعَ ظُلْمَةِ آخِرِ اللَّيْلِ. 2.""غُبْشَةُ الدَّابَّةِ"" : سَوَادٌ شَدِيدٌ فِي لَوْنِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12610, 'غَبِينَةٌ', 'غبينة', 'جامد', 'غبن', 'غبينة', 'غبنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"غَبِينَةٌ-غَبِينَةٌ [غ ب ن]. ""أَوْقَعَهُ فِي غَبِينَةٍ"" : فِي خَدِيعَةٍ. ‏ ""لَحِقَتْهُ فِي تِجَارَتِهِ غَبِينَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12611, 'غَبْوَةٌ', 'غبوة', 'جامد', 'غبو', 'غبوة', 'غبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"غَبْوَةٌ-غَبْوَةٌ [غ ب و]. ""كَانَ فِي غَبْوَةٍ مِنْ أَمْرِهِ"" : فِي غَفْلَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12612, 'غُثَاءٌ', 'غثاء', 'جامد', 'غثو', 'غثاء', 'غث', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'Rz', '', '', '', '', '', '', '"غُثَاءٌ-غُثَاءٌ، ةٌ [غ ث و]. 1.""غُثَاءُ القِدْرِ"" : زَبَدُها، رَغْوَتُها. 2.""غُثَاءُ اللَّيْلِ"" : الْحَشَائِشُ اليَابِسَةُ وَفُتَاتُ الأَرْضِ وَمَا يُجْرَفُ مَعَ رَغْوَةِ السَّيْلِ. الأعلى آية 4 ، 5وَالَّذِي أَخْرَجَ الْمَرْعَى فَجَلَهُ غُثاءً أَحْوَى (قرآن). 3.""هُوَ مِنْ غُثَاءِ النَّاسِ"" : مِنْ أَرَاذِلِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12613, 'غُدَّةٌ', 'غدة', 'جامد', 'غدد', 'غدة', 'غدة', '', '', '', 'مفرد', 'DnN', '', '', '"غُدَدٌ:غَدَائِدُ"', '', 'R', '', '', '', '', '', '', '". 1.""بَرَزَتْ غُدَّةٌ فِي فَخِذِهِ"" : قِطْعَةٌ مِنْ لَحْمٍ، صَلْبَةٌ تَبْرُزُ مَا بَيْنَ الْجِلْدِ وَاللَّحْمِ عَلَى إِثْرِ دَاءٍ مَّا. 2.""غُدَّةٌ تَنَاسُلِيَّةٌ"" : مَادَّةٌ غَرَائِيَّةٌ فِي الْجِهَازِ التَّنَاسُلِيِّ لأُنْثَى الْحَشَرَاتِ، وَظِيفَتُهَا إِلْصَاقُ البَيْضِ بَعْضِهُ بِبَعْضٍ. 3.""غُدَّةٌ ثَدْيِيَّةٌ"" : عُضْوٌ لَحْمِيٌّ يَبْرُزُ فِي ثَدْيِ الْمَرْأَةِ وَيُفْرِزُ اللَّبَنَ. 4.""غُدَّةٌ لُعَابِيَّةٌ"" : مَادَّةٌ إِفْرَازِيَّةٌ هَضْمِيَّةٌ. 5.""غُدَّةٌ دَمْعِيَّةٌ"": أُنْبُوبٌ صَغِيرٌ يُفْرِزُ الدَّمْعَ الَّذِي يَغْسِلُ الْعَيْنَ. 6.""الغُدَّةُ الصَّمَّاءُ"" : هِيَ الَّتِي تَفْرِزُ مَادَّتَهَا دَاخِلَ الْجِسْمِ فِي الدَّمِ. 7.""الغُدَّةُ النُّخَامِيَّةُ"" : هِيَ غُدَّةٌ صَمَّاءُ فِي قَاعِدَةِ القِحْفِ تَفْرِزُ هُرْمُونَاتِ النُّمُوِّ وَهُرْمُونَاتٍ تُسَاعِدُ عَمَلَ الغُدَدِ الأُخْرَى. 8.""غُدَّةُ الإِبِلِ"" : الطّاعُونُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12614, 'غُدَدٌ', 'غدد', 'جامد', '', 'غدد', 'غد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12615, 'غَدَائِدُ', 'غدائد', 'جامد', '', 'غداءد', 'غدد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12616, 'غِرَامٌ', 'غرام', 'جامد', '', 'غرام', 'غرم', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: ـات. ""عِشْرُونَ غِرَاماً"" : وَحْدَةُ الوَزْنِ تُسَاوِي جُزْءاً مِنْ أَلْفٍ مِنَ الكِيلُو غِرَامِ. وَتُنْطَقُ بِالْجِيمِ أَيْضاً جِرَاماً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12617, 'غَدِيرَةٌ', 'غديرة', 'جامد', 'غدر', 'غديرة', 'غدرة', '', '', '', 'مفرد', 'DnN', '', '', '"غَدَائِرُ"', '', '', '', '', '', '', '', '', '". 1.""ظَهَرَتْ بِغَدَائِرِهَا الْجَمِيلَةِ"" : بِضَفَائِرِهَا. 2.""حَشَّ الغَدِيرَةَ"" : القِطْعَةَ مِنَ النَّبَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12618, 'غَدَائِرُ', 'غدائر', 'جامد', '', 'غداءر', 'غدر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12619, 'غَدِيرٌ', 'غدير', 'جامد', 'غدر', 'غدير', 'غدر', '', '', '', 'مفرد', 'DnN', '', '', '"غُدْرَانٌ"', '', '', '', 'N', 'O', 'O', 'O', '', '". 1.""مَاءُ الغَدِيرِ"" : مَاءُ النَّهْرِ الصَّغِيرِ. 2.""غَديرُ النّباتِ"" : قِطْعَةٌ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12620, 'غُدْرَانٌ', 'غدران', 'جامد', '', 'غدران', 'غدرن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12621, 'غَدَفٌ', 'غدف', 'جامد', 'غدف', 'غدف', 'غدف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَدَفٌ-غَدَفٌ [غ د ف]. ""هُوَ فِي غَدَفٍ مِنَ العَيْشِ"" : فِي سَعَةٍ وَخِصْبٍ وَنِعْمَةٍ. ""هُمْ فِي غَدَفٍ مِنْ مَعِيشَتِهِمْ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12622, 'غَدَاءٌ', 'غداء', 'جامد', 'غدو', 'غداء', 'غد', '', '', '', 'مفرد', 'Dz', '', '', '"أَغْدِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '". ""تَنَاوَلَ الغَدَاءَ"" : أَكْلَةَ الظَّهِيرَةِ.الكهف آية 62آتِنا غَداءنَا لَقَدْ لَقِينا مِنْ سَفَرِنا هَذَا نَصَباً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12623, 'أَغْدِيَةٌ', 'أغدية', 'جامد', '', 'ءغدية', 'غدة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12624, 'غَدَاةٌ', 'غداة', 'جامد', 'غدو', 'غداة', 'غدة', '', '', '', 'مفرد', 'DnN', '', '', '"غَدَوَاتٌ"', '', 'Rw', '', '', '', '', '', '', '". 1.""بَيْنَ الغَدَاةِ وَالعَشِيِّ"" : أَيْ بَيْنَ الفَجْرِ وَطُلُوعِ الشَّمْسِ. 2.""فِي غَدَوَاتِهِ وَرَوَحَاتِهِ"": فِي ذَهَابِهِ وَإِيَابِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12625, 'غَدَوَاتٌ', 'غدوات', 'جامد', '', 'غدوات', 'غدت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12626, 'غَدٌ', 'غد', 'جامد', 'غدو', 'غد', 'غد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَدٌ-غَدٌ [غ د و]. ""إِلَى الغَدِ"" : اليَوْمُ الآتِي بَعْدَ يَوْمِكَ الَّذِي أَنْتَ فِيهِ. ""سَنَلْتَقِي بَعْدَ غَدٍ"" ""مَا الغَدُ بِبَعِيدٍ"" ""لاَ تُرْجِئْ إِلَى غَدِكَ مَا تَسْتَطِيعُهُ فِي يَوْمِكَ""لاَ يَعْلَمُ أَحَدٌ مَا يَكُونُ فِي غَدٍ (حديث) ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12627, 'غَدِيَّةٌ', 'غدية', 'جامد', 'غدو', 'غدية', 'غدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":غَدَايَا"', '', '', '', '', '', '', '', '', '". : بُكْرَةٌ، أَيْ مَا بَيْنَ الفَجْرِ وَطُلُوعِ الشَّمْسِ، أَوَّلُ النَّهَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12628, 'غَدَايَا', 'غدايا', 'جامد', '', 'غدايا', 'غد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12629, 'غِذَاءٌ', 'غذاء', 'جامد', 'غذو', 'غذاء', 'غذ', '', '', '', 'مفرد', 'Dz', '', '', '"أَغْذِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '". 1.""غِذَاءٌ دَسِمٌ"" : الطَّعَامُ وَالشَّرَابُ، أَيْ مَا يُغَذَّى بِهِ. 2.""يَحْتَاجُ الإِنْسَانُ إِلَى الغِذَاءِ الرُّوحِيِّ"" : إِلَى مَا يُنَمِّي وَيُغَذِّي رُوحَهُ. ""لَيْسَ غِذَاءُ الطَّعَامِ بِأَسْرَعَ فِي نَبَاتِ الْجَسَدِ مِنْ غِذَاءِ الأَدَبِ فِي نَبَاتِ العَقْلِ"" (ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12630, 'أَغْذِيَةٌ', 'أغذية', 'جامد', '', 'ءغذية', 'غذة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12631, 'غُرَابٌ', 'غراب', 'جامد', '', 'غراب', 'غرب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"غِرْبَانٌ:أَغْرِبَةٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: غِرْبَانٌ، أَغْرِبَةٌ. (حو). 1. : طَائِرٌ مِنَ الْجَوَاثِمِ يُتَشَاءمُ مِنْهُ، وَهُوَ أَنْوَاعٌ مِنْهَا: أ. ""الغُرَابُ الأَسْوَدُ"": وَهُوَ كَبِيرٌ لَمَّاعٌ صَقِيلُ الرِّيشِ، رِيشُ عُنُقِهِ طَوِيلٌ رُمْحِيُّ الشَّكْلِ، يَعِيشُ عَلَى اللُّحُومِ وَيُضْرَبُ بِهِ المَثَلُ في الحَذَرِ والسَّوادِ. ب.""غُرَابُ الزَّرْعِ"" : وَهُوَ مِنْ فَصِيلَةِ الغُرَابِيَّاتِ، مِنْ رُتْبَةِ العُصْفُورِيَّاتِ، يَقْبَعُ فِي الأَمَاكِنِ الْخَرِبَةِ وَالبُرُوجِ. ج.""غُرَابُ اللَّيْلِ"" : مِنْ فَصِيلَةِ مَالِكٍ الْحَزِينِ، مِنْ رُتْبَةِ اللَّقَال"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12632, 'غِرْبَانٌ', 'غربان', 'جامد', '', 'غربان', 'غربن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12633, 'أَغْرِبَةٌ', 'أغربة', 'جامد', '', 'ءغربة', 'غربة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12634, 'غُرَابِيَّاتٌ', 'غرابيات', 'جامد', '', 'غرابيات', 'غربت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةُ الغِرْبَانِ وَهِيَ أَنْوَاعٌ مِنَ الْجَوَاثِمِ ذَوَاتِ الْمَنَاقِيرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12635, 'مَغَارِبُ', 'مغارب', 'جامد', 'غرب', 'مغارب', 'مغرب', '', '', '', 'مفرد', '', '', '', '"مفردمَغْرِب"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '". ""جَابَ مَشَارِقَ الأَرْضِ ومَغَارِبَهَا"" : أَيْ جَابَ بُلْداناً مِنْ أَقْصَى شَرْقِ الْمَعْمُورَةِ إِلَى غَرْبِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12636, 'مَغْرِبَانٌ', 'مغربان', 'جامد', 'غرب', 'مغربان', 'مغربن', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مَغْرِبَانٌ-مَغْرِبَانٌ [غ ر ب]. ""مَغْرِبَانُ الشَّمْسِ"" : حَيْثُ تَغْرُبُ، غُرُوبُهَا مَغْرِبُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12637, 'مَغْرِبٌ', 'مغرب', 'جامد', 'غرب', 'مغرب', 'مغرب', '', '', '', 'مفرد', 'DnN', '', '', '"مَغَارِبُ"', '', 'Rp', '', '', '', '', '', '', '". 1. ""مَغْرِبُ الشَّمْسِ"" (جغ) : مَكَانُ غُرُوبِ الشَّمْسِ. 2. ""بِلاَدُ الْمَغْرِبِ"" : مِنَ البُلْدَانِ العَرَبِيَّةِ (الْمَمْلَكَةُ الْمَغْرِبِيَّةُ) تَقَعُ فِي الشَّمَالِ الإِفْرِيقِيِّ، مِنْ بُلْدَانِ الْمَغْرِبِ العَرَبِيِّ. 3.""بُلْدَانُ الْمَغْرِبِ العَرَبِيّ"" : لِيبْيَا وتُونُسُ والجَزَائِرُ والْمَغْرِب ومُورِيطَانْيَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12638, 'مَغَارِبُ', 'مغارب', 'جامد', '', 'مغارب', 'مغرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12639, 'غِرْبَالٌ', 'غربال', 'جامد', 'غربل', 'غربال', 'غربل', '', '', '', 'مفرد', 'DnN', '', '', '"غَرَابِيلُ"', '', 'R', '', '', '', '', '', '', '". ""بِيَدِهَا غِرْبَالٌ تُغَرْبِلُ بِهِ الطَّحِينَ"" : أَدَاةٌ دائِرِيَّةٌ يُغَرْبَلُ بِهَا الطَّحِينُ وَمَا إِلَى ذَلِكَ، تُشْبِهُ الدُّفَّ، أي يَشُدُّ مُحيطَها جِلْدٌ أَوْ مَعْدِنٌ بِهِ ثُقُوبٌ صَغِيرَةٌ تُنَقِّي الْمَادَّةَ الْمُغَرْبَلَةَ. ""يَنْظُرُونَ مِنْ خِلاَلِ ثُقُوبِ غَرَابِيلِهِمْ"" (ميخائيل نعيمة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12640, 'غَرَابِيلُ', 'غرابيل', 'جامد', '', 'غرابيل', 'غربل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12641, 'غُرَبِيَّةٌ', 'غربية', 'جامد', '', 'غربية', 'غربة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"غُرَبِيَّةٌ-غُرَبِيَّةٌ (طخ). : نَوْعٌ مِنَ الْحَلْوَى يُحَضَّرُ بِالسَّمِيدِ وَالسَّمْنِ وَالسُّكَّرِ وَيُقَدَّمُ عَادَةً عَلَى شَكْلِ أَقْرَاصٍ دَائِرِيَّةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12642, 'أُغْرود', 'أغرود', 'جامد', 'غرد', 'ءغرود', 'غرد', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"أغَارِيدُ"', '', 'R', '', '', '', '', '', '', '". 1.""اِسْتَمَعْنَا إلَى أُغْرُودَةِ العِيدِ"" : أُنْشُودَةٌ، أُغْنِيَةٌ، نَشِيدٌ. 2.""كَانَتْ أغَارِيدُ الطُّيُورِ تَمْلأُ أَجْوَاءَ الحَدِيقَةِ"" : غِنَاؤُهَا، زَقْزَقَتُها."', '');
