INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12644, 'غَرَانِيت', 'غرانيت', 'جامد', '', 'غرانيت', 'غرنت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": كَلِمَةٌ دَخِيلَةٌ، مَادَّةٌ مِنْ حِجَارَةِ الرُّخَامِ، صَلْبَةٌ مُتَبَلْوِرَةٌ، تُسْتَعْمَلُ فِي البِنَاءِ."', ':لا جذر:لا مفرد');
