INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12681, 'غَرْوَى', 'غروى', 'جامد', 'غرو', 'غروى', 'غر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"غَرْوَى-غَرْوَى [غ ر و]. 1.""هُوَ غَرْوَى بِالإِنْشَادِ"" : مُولَعٌ بِهِ. 2.""لاَ غَرْوَى"" : لاَ عَجَبَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12682, 'غُرَيْرٌ', 'غرير', 'جامد', '', 'غرير', 'غرر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"غُرَيْرٌ-غُرَيْرٌ (حو). : مِنْ فَصِيلَةِ السُّرْعُوبِيَّاتِ، مِنْ رُتْبَةِ اللَّوَاحِمِ، لَبُونٌ،شَكْلُهُ مَا بَيْنَ الكَلْبِ وَالسِّنَّوْ"', ':لا جذر:لا مفرد');
