INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12707, 'غُسَانٌ', 'غسان', 'جامد', 'غسن', 'غسان', 'غسن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غُسَانٌ - [غ س ن]. ""غُسَانُ القَلْبِ"" : غَسَّانُهُ، أَقْصَاهُ، عُمْقُهُ. "', '');
