INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12710, 'غِشَاشٌ', 'غشاش', 'جامد', 'غشش', 'غشاش', 'غشش', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"غِشَاشٌ-غِشَاشٌ [غ ش ش]. 1.""غِشَاشُ اللَّيْلِ"" : أَوَّلُ ظُلْمَتِهِ وَآخِرُهَا. 2.""غِشَاشُ النَّوْمِ"" : قَلِيلُهُ. 3.""شُرْبٌ غِشَاشٌ"" : غَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12711, 'غِشَاوَةٌ', 'غشاوة', 'جامد', 'غشو', 'غشاوة', 'غشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غِشَاوَةٌ-غِشَاوَةٌ [غ ش و]. 1.""غِشاوَةُ القَلْبِ"" : جِلْدَةُ القَلْبِ. 2.""عَلَى عَيْنَيْهِ غِشَاوَةٌ"" : غِطَاءٌ، غِشَاءٌ يَمْنَعُه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12712, 'غَاشِيَةٌ', 'غاشية', 'جامد', 'غشي', 'غاشية', 'غشة', '', '', '', 'مفرد', 'DnN', '', '', '"غَوَاشٍ:الغَوَاشِي"', '', '', '', '', '', '', '', '', '". 1.""غَاشِيَةُ الفِرَاشِ"" : غِطَاؤُهُ. 2.""غَاشِيَةُ القَلْبِ"" : غِلاَفُهُ. 3.""نَزَلَتْ بِهِ الغَاشِيَةُ"" : الْمُصِيبَةُ. 4.""الغاشِيَةُ"" : سورةٌ مِن سُوَرِ القرآن. 5.الغاشية آية 1هَلْ أَتَاكَ حَد"', '');
