INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12725, 'غَضَا', 'غضا', 'جامد', '', 'غضا', 'غض', '', '', 'Ta', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"غَضَا-غَضَا، ةٌ (نب). 1. : شَجَرٌ مِنَ الأَثْلِ، خَشَبُهُ صَلْبٌ جِدّاً، وَجَمْرُهُ يَبْقَى زَمَناً طَوِيلاً لاَ يَنْطَفِئُ، يَكْثُرُ فِي مِنْطَقَةِ نَجْدٍ، لِهَذَا أُطْلِقَ عَلَى أَهْلِ"', ':لا جذر:لا مفرد');
