INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12727, 'غَضْرَاءُ', 'غضراء', 'جامد', 'غضر', 'غضراء', 'غضر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"غَضْرَاءُ-غَضْرَاءُ [غ ض ر]. 1.""أَرْضٌ غَضْرَاءُ"" : ذَاتُ طِينٍ لَزِجٍ أَخْضَرَ، لاَ رَمْلَ فِيهَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12728, 'غُضْرُوفٌ', 'غضروف', 'جامد', 'غضرف', 'غضروف', 'غضرف', '', '', '', 'مفرد', 'DnN', '', '', '"غَضَارِيفُ"', '', 'R', '', '', '', '', '', '', '". ""غُضْرُوفُ الأَنْفِ"" : العَظْمُ اللَّيِّنُ الْمُكَوِّنُ لِلْأَنْفِ، وَالغُضْرُوفُ يُطْلَ"', '');
