INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12827, 'غَيَابَةٌ', 'غيابة', 'جامد', 'غيب', 'غيابة', 'غبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"غَيَابَةٌ-غَيَابَةٌ [غ ي ب]. 1.""غَيَابَةُ الحُفْرَةِ"" : قَعْرُهَا. يوسف آية 10 وَأَلْقُوهُ فِي غَيَابَةِ الْجُبّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12828, 'غَابَةٌ', 'غابة', 'جامد', 'غيب', 'غابة', 'غبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":غَابٌ"', '', 'R', '', '', '', '', '', '', '". ""غَابَةُ الأَشْجَارِ"": مِسَاحَةٌ شَاسِعَةٌ تَكْتَنِفُهَا الأَشْجَارُ الكَثِيفَةُ مِنْ كُلِّ جِهَةٍ وَتَكُونُ مَرْتَعاً ل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12829, 'غَابٌ', 'غاب', 'جامد', '', 'غاب', 'غب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12830, 'غِيلَةٌ', 'غيلة', 'جامد', 'غيل', 'غيلة', 'غلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"غِيلَةٌ-غِيلَةٌ [غ ي ل]. ""أَضَرَّتِ الغِيلَةُ بِالرَّضِيعِ"" : إِذَا أَرْضَعَتْهُ أُمُّهُ وَهِيَ حَامِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12831, 'غَيْلَمٌ', 'غيلم', 'جامد', '', 'غيلم', 'غلم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَيْلَمٌ-غَيْلَمٌ (حو). 1. : ذَكَرُ السُّلَحْفَاةِ. 2.""شَابٌّ غَيْلَمٌ"" : عَرِيضُ الْمَفْرِقِ كَثِيرُ الشَّعَرِ. 3.""غَيْلَمُ الآبَارِ"" : مَنْبَعُ الْمَاءِ فِيهَا. 4.""مَا بِالدَّارِ غَيْلَمٌ"" : أَحَدٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12832, 'غَايَةٌ', 'غاية', 'جامد', 'غيي', 'غاية', 'غة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":غَايٌ"', '', '', '', '', '', '', '', '', '". 1.""غَايَةُ الشَّيْءِ"" : نِهَايَتُهُ، آخِرُهُ، مَدَاهُ. 2.""غَايَةُ هَدَفِهِ"" : الفَائِدَةُ الْمَقْصُودَةُ مِنْهُ. ""بَلَغَ غَايَتَهُ"" ""الغَايَةُ تُبَرِّرُ الوَسِيلَةَ"". 3.""هُوَ بَعِيدُ الغَايَةِ"" : أَيْ صَائِبُ الرَّأْيِ. 4.""غَايَتُكَ أَنْ تَفْعَلَ هَذَا"" : أَيْ نِهَايَةُ طَاقَتِكَ أَوْ فِعْلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12833, 'غَايٌ', 'غاي', 'جامد', '', 'غاي', 'غ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12834, 'فُؤَادٌ', 'فؤاد', 'جامد', 'فأد', 'فءاد', 'فد', '', '', '', 'مفرد', 'DnN', '', '', '"أَفْئِدَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""فُؤَادُ الإِنْسَانِ"" : قَلْبُهُ. الفرقان آية 32كَذَلِكَ لِنُثَبِّتَ بِهِ فُؤَادَكَ (قرآن) نَقِّلْ فُؤَادَكَ حَيْثُ شِئْتَ مِنَ الْهَوَى*مَا الْحُبُّ إِلاَّ لِلْحَبِيبِ الأَوَّل (أبو تمام). 2.""فَارِغُ الْفُؤَادِ"" : خَالٍ مِنَ الْهَمِّ وَالْحُزْنِ. 3.""فُؤَادٌ"" : اِسْمُ عَلَمٍ للمُذَكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12835, 'أَفْئِدَةٌ', 'أفئدة', 'جامد', '', 'ءفءدة', 'فدة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12836, 'فَادِنٌ', 'فادن', 'جامد', '', 'فادن', 'فدن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"فَوَادِنُ"', '', '', '', '', '', '', '', '', '"ج: فَوَادِنُ. : آلَةٌ لاخْتِبَارِ اسْتِقَامَةِ الْبِنَاءِ وَاسْتِوَائِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12837, 'فَوَادِنُ', 'فوادن', 'جامد', '', 'فوادن', 'فدن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12838, 'فَأْرٌ', 'فأر', 'جامد', '', 'فءر', 'فر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"فِئْرَانٌ:فِئَرَةٌ(مذ:مؤ)"', '', 'R', '', '', '', '', '', '', '"ج: فِئْرَانٌ، فِئَرَةٌ. (مذ، مؤ) (حو). : حَيَوَانٌ مِنْ فَصِيلَةِ الْفَأْرِيَّاتِ، مِنْ رُتْبَةِ الْقَوَارِضِ، يَسْكُنُ الْمَجَارِيَ وَالْبُيُوتَ، يُفْسِدُ الْمُؤَنَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12839, 'فِئْرَانٌ', 'فئران', 'جامد', '', 'فءران', 'فرن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12840, 'فِئَرَةٌ', 'فئرة', 'جامد', '', 'فءرة', 'فرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12841, 'فَأْرِيَّاتٌ', 'فأريات', 'جامد', '', 'فءريات', 'فرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"فَأْرِيَّاتٌ-فَأْرِيَّاتٌ (حو). : فَصِيلَةٌ حَيَوَانِيَّةٌ مِنَ اللَّبُونَاتِ، مِنَ الْقَوَارِضِ، أَنْوَاعُهَا عَدِيدَةٌ، مِنْهَا الْجُرَذُ، صَغِيرَةٌ أَوْ كَبِيرَةُ الْحَجْمِ، تَعِيشُ فِي الْمَنَازِلِ الْخَرِبَةِ وَالْحُقُولِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12842, 'فَازُورَةٌ', 'فازورة', 'جامد', '', 'فازورة', 'فزرة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"فَوَازِيرُ"', '', 'R', '', '', '', '', '', '', '"ج: فَوَازِيرُ. ""فَوَازِيرُ اللَّيَالِي الرَّمَضَانِيَّةِ"" : الأَلْغَازُ وَالأَحَاجِيُّ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12843, 'فَوَازِيرُ', 'فوازير', 'جامد', '', 'فوازير', 'فزر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12844, 'غِيطَةٌ', 'غيطة', 'جامد', '', 'غيطة', 'غطة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غِيطَةٌ-غِيطَةٌ (مو). ج: ـات. : آلَةٌ مُوسِيقِيَّةٌ مَغْرِبِيَّةٌ شَبِيهَةٌ بِالنَّايِ، إِلاَّ أَنَّهَا أَكْبَرُ حَجْماً، ذَاتُ مَخْرَجٍ وَاسِـعٍ، بِهَا ثُقَبٌ تَتَحَكَّمُ الأَصَابِعُ فِي نَغَمَاتِهَا أَثْنَاءَ النَّفْخِ فِيهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12845, 'غِيَرٌ', 'غير', 'جامد', 'غير', 'غير', 'غر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"غِيَرٌ-غِيَرٌ [غ ي ر]. ""غِيَرُ الدَّهْرِ"" : أَحْدَاثُهُ، نَوَائِبُهُ، صُرُوفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12846, 'فَاصُولِيَا', 'فاصوليا', 'جامد', '', 'فاصوليا', 'فصل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '"فَاصُولِيَا-فَاصُولِيَا (نب). ن. لُوبِيَاء."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12847, 'فَاقَةٌ', 'فاقة', 'جامد', '', 'فاقة', 'فقة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"1.""يَعِيشُ فِي فَاقَةٍ"" : فِي فَقْرٍ. 2.""اِشْتَدَّتْ بِهِ الْفَاقَةُ"" : الْحَاجَةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12848, 'فَاكِهَةٌ', 'فاكهة', 'جامد', '', 'فاكهة', 'فكهة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"فَوَاكِهُ"', '', 'R', '', '', '', '', '', '', '"ج: فَوَاكِهُ. 1.""قَدَّمَ للِضُّيُوفِ الْفَاكِهَةَ"" : الثِّمَارُ مِنْ مَوْزٍ وَتُفَّاحٍ وَعِنَبٍ وَمَا شَابَهَ ذَلِكَ. 2.""فَاكِهَةُ الشِّتَاءِ"" : النَّارُ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12849, 'فَوَاكِهُ', 'فواكه', 'جامد', '', 'فواكه', 'فكه', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12850, 'فَالِجٌ', 'فالج', 'جامد', '', 'فالج', 'فلج', '', '', '', 'جمع تكسير', 'DnN', '', '', '"فَوَالِجُ"', '', '', '', '', '', '', '', '', '"ج: فَوَالِجُ. (طب). ""أُصِيبَ بِدَاءِ الْفَالِجِ"" : مَرَضٌ يُحْدِثُ شَلَلاً فِي أَحَدِ شَقَّيِ الْبَدَنِ يُفْقِدُ الإِحْسَاسَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12851, 'فَوَالِجُ', 'فوالج', 'جامد', '', 'فوالج', 'فلج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12852, 'فَالُوذٌ', 'فالوذ', 'جامد', '', 'فالوذ', 'فلذ', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ن. فَالُوذَجٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12853, 'فَالُوذَجٌ', 'فالوذج', 'جامد', '', 'فالوذج', 'فلذج', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": حَلْوَاءُ تُهَيَّأُ مِنَ الدَّقِيقِ وَالْمَاءِ وَالعَسَلِ، وَتُحَضَّرُ الآنَ مِنَ النَّشَا وَالْمَاءِ وَالسُّكَّرِ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12854, 'فَانُوسٌ', 'فانوس', 'جامد', '', 'فانوس', 'فنس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"فَوَانِيسُ"', '', 'R', '', '', '', '', '', '', '"ج: فَوَانِيسُ. ""أَشْعَلَ الْفَانُوسَ وَتَقَدَّمَ الْقَافِلَةَ"" :الْمِصْبَاحُ اللَّيْلِيُّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12855, 'فَوَانِيسُ', 'فوانيس', 'جامد', '', 'فوانيس', 'فنس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12856, 'فِئَةٌ', 'فئة', 'جامد', 'فأي', 'فءة', 'فة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""فِئَةٌ مِنَ النَّاسِ"" : جَمَاعَةٌ، طَائِفَةٌ.البقرة آية 249كَمْ مِنْ فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً بِإِذْنِ اللَّهِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12857, 'فِبْرَاير', 'فبراير', 'جامد', '', 'فبراير', 'فبرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ الثَّانِي مِنَ الشُّهُورِ الْغَرْبِيَّةِ، عَدَدُ أَيَّامِهِ (28) يَوْماً، و(29) يَوْماً فِي السَّنَةِ الكَبِيسَةِ. وَيُنْطَقُ أَيْضاً فِيفْرِيّ، شُباط."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12858, 'فُتَاتٌ', 'فتات', 'جامد', 'فتت', 'فتات', 'فتت', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فُتَاتٌ-فُتَاتٌ [ف ت ت]. 1.""فُتَاتُ الْخُبْزِ"" : مَا تَكَسَّرَ مِنْهُ. 2.""فُتَاتُ الْمَائِدَةِ"" : فَضَلاَتُ الطَّعَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12859, 'فَتَّةٌ', 'فتة', 'جامد', 'فتت', 'فتة', 'فتة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"فَتَّةٌ-فَتَّةٌ (فِتَّةٌ) [ف ت ت]. 1.""فَتَّةُ تَمْرٍ"" : كُتْلَةٌ مِنْهُ. 2. : ثَرِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12860, 'فَتِيتَةٌ', 'فتيتة', 'جامد', 'فتت', 'فتيتة', 'فتتة', '', '', '', 'مفرد', 'DnN', '', '', '"فَتَائِتُ"', '', 'R', '', '', '', '', '', '', '". : قِطْعَةٌ مِنْ شَيْءٍ مَفْتُوتٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12861, 'فَتَائِتُ', 'فتائت', 'جامد', '', 'فتاءت', 'فتت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12862, 'اِفْتِتَاحِيَّةٌ', 'افتتاحية', 'جامد', 'فتح', 'افتتاحية', 'فتتحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"اِفْتِتَاحِيَّةٌ-اِفْتِتَاحِيَّةٌ [ف ت ح]. ""يَقْرأُ افْتِتَاحِيَّةَ الجَرِيدَةِ فِي كُلِّ صَبَاحٍ"" : الْمَقَالُ الافْتِتَاحِيُّ فِي الصَّفْحَةِ الأُولى للِجَرِيدَةِ، وَيَتَضَمَّنُ عَادَةً مَوْقِفَهَا الرَّسْمِيَّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12863, 'فَاتِحَةٌ', 'فاتحة', 'جامد', 'فتح', 'فاتحة', 'فتحة', '', '', '', 'مفرد', 'DnN', '', '', '"فَوَاتِحُ"', '', '', '', 'N', 'O', 'O', 'O', '', '". 1.""قَرَأَ الْفَاتِحَةَ"" : السُّورَةُ الأُولَى مِنَ الْقُرْآنِ. 2.""فَاتِحَةُ الْكِتَابِ"" : مُقَدِّمَتُهُ، تَوْطِئَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12864, 'فَوَاتِحُ', 'فواتح', 'جامد', '', 'فواتح', 'فتح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12865, 'فَتَّاحَةٌ', 'فتاحة', 'جامد', 'فتح', 'فتاحة', 'فتحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"فَتَّاحَةٌ-فَتَّاحَةٌ [ف ت ح]. : أَدَاةٌ تُفْتَحُ بِهَا الْعُلَبُ الْمُغْلَقَةُ مِنَ الصَّفِيحِ وَنَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12866, 'فِتَاحٌ', 'فتاح', 'جامد', 'فتح', 'فتاح', 'فتح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فِتَاحٌ-فِتَاحٌ، فُتَاحٌ [ف ت ح]. 1.""صَارَ أَمْرُهُمَا إِلَى الْفِتَاحِ"": إِلَى التَّحَاكُمِ، التَّقَاضِي. 2.""فِتَاحُ حُقُولِ الزَّرْعِ"" : حَرْثُ الأَرْضِ سَطْحِيّاً بَعْدَ الْحَصَادِ لِقَلْعِ الزَّرْعِ الْمَحْصُودِ وَدَفْنِهِ وَتَهْوِيَةِ التُّرْبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12867, 'فُتْحَةٌ', 'فتحة', 'جامد', 'فتح', 'فتحة', 'فتحة', '', '', '', 'مفرد', 'DnN', '', '', '"فُتَحٌ"', '', 'R', '', '', '', '', '', '', '". ""فِي الْجِدَارِ فُتْحَةٌ"" : فُرْجَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12868, 'فُتَحٌ', 'فتح', 'جامد', '', 'فتح', 'فتح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12869, 'فُتُوحَاتٌ', 'فتوحات', 'جامد', 'فتح', 'فتوحات', 'فتحت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فُتُوحَاتٌ-فُتُوحَاتٌ [ف ت ح]. ""عَصْرُ الْفُتُوحَاتِ الإِسْلاَمِيَّةِ"" : الْعَصْرُ الَّذِي تَمَّ فِيهِ فَتْحُ الْبُلْدَانِ الَّتِي اعْتَنَقَتِ الإِسْلاَمَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12870, 'مِفْتَاحٌ', 'مفتاح', 'جامد', 'فتح', 'مفتاح', 'مفتح', '', '', '', 'مفرد', 'DnN', '', '', '"مَفَاتِيحُ"', '', 'R', '', '', '', '', '', '', '". 1. ""مِفْتَاحُ البَيْتِ"" : آلَةٌ حَدِيدِيَّةٌتَدْخُلُ فِي القُفْلِ لِفَتْحِ البَابِ ومَا شَابَهَ ذَلِكَ. 2.""شَعَرَ بِأَنَّهُ يَقْبِضُ عَلَى مَفَاتِيحِ الْمُسْتَقْبَلِ كُلِّهِ"": أَيْ مَا يُمْكِنُ أَنْ يُوصِّلَـهُ ويَفْتَحَ أَمَامَهُ الْمُسْتَقْبَلَ. ""الصَّبْرُ مِفْتَاحُ الفَرَجِ"". 3. ""مِفْتَاحُ الشَّرِّ"" : أَيْ مَنْ يُشْعِلُ نَارَ الفِتْنَةِ. ""مِفْتَاحُ الشَّرِّ كَلِمَةٌ"". 4.الأنعام آية 59 وَعِنْدَهُ مَفَاتِيحُ الغَيْبِ لاَ يَعْلَمُهَا إِلاَّ هُوَ (قرآن) : أَيْ عِلْمُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12871, 'مَفَاتِيحُ', 'مفاتيح', 'جامد', '', 'مفاتيح', 'مفتح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12872, 'فَتْرَةٌ', 'فترة', 'جامد', 'فتر', 'فترة', 'فترة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". 1.""بِحَاجَةٍ إِلَى فَتْرَةِ رَاحَةٍ"": الْمُدَّةُ الْفَاصِلَةُ بَيْنَ زَمَنَيْنِ، الْوَقْتُ. ""بَيْنَ فَتْرَةٍ وَأُخْرَى"". 2.""إِنَّهَا فَتْرَةٌ مِنْ أَصْعَبِ الْفَتَرَاتِ "" : مَرْحَلَةٌ. ""فَتْرَةُ الامْتِحَانِ"" ""فَتْرَةُ الانْتِقَالِ"" ""فَتْرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12873, 'فِتْرٌ', 'فتر', 'جامد', '', 'فتر', 'فتر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَفْتَارٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَفْتَارٌ. : مَا بَيْنَ طَرَفِ الإِبْهَامِ وَطَرَفِ السَّبَّابَةِ عِنْدَ فَتْحِهِمَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12874, 'أَفْتَارٌ', 'أفتار', 'جامد', '', 'ءفتار', 'فتر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12875, 'مُفَتِّشِيَّةٌ', 'مفتشية', 'جامد', 'فتش', 'مفتشية', 'مفتشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُفَتِّشِيَّةٌ-مُفَتِّشِيَّةٌ [ف ت ش]. : مَقَرُّ جِهَازِ الْمُفَتِّشِ وعَمَلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12876, 'فِتْنَةٌ', 'فتنة', 'جامد', 'فتن', 'فتنة', 'فتنة', '', '', '', 'مفرد', 'DnN', '', '', '"فِتَنٌ"', '', 'R', '', '', '', '', '', '', '". 1.""نَشَرَ الْفِتْنَةَ بَيْنَ النَّاسِ"" : مَا يَقَعُ بَيْنَهُمْ مِن اخْتِلاَفٍ فِي الرَّأْيِ يَجْعَلُهُمْ يَتَطَاحَنُونَ وَيَتَقَاتَلُونَ. 2.""عَرَفَتْ خِلاَفَةُ عُثْمَانَ فِتْنَةً كُبْرَى"" : اِنْشِقَاقاً فِي صُفُوفِ الْمُسْلِمِينَ أَدَّى بِهِمْ إِلَى الْقِتَالِ فِيمَا بَيْنَهُمْ. 3.""هُمْ فِي فِتْنَةٍ مِنْ أَمْرِهِمْ"" : فِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12877, 'فِتَنٌ', 'فتن', 'جامد', '', 'فتن', 'فتن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
