INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12973, 'فُرٌّ', 'فر', 'جامد', 'فرر', 'فر', 'فر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فُرٌّ-فُرٌّ [ف ر ر]. 1.""هَذَا فُرُّهُ"" : أَفْضَلُهُ. 2.""هُوَ فُرُّ قَوْمِهِ"": مِنْ خِيَارِهِمْ، وُجَهَائِهِمْ."', '');
