INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12975, 'مَفَرٌّ', 'مفر', 'جامد', 'فرر', 'مفر', 'مفر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَفَرٌّ-مَفَرٌّ [ف ر ر]. ""أَيْنَ الْمَفَرُّ "" : إِلَى أَيْنَ الفِرَارُ، الْمَلْجَأُ.القيامة آية 10 يَقُولُ الإِنْسَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12976, 'فِرْزَانٌ', 'فرزان', 'جامد', '', 'فرزان', 'فرزن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"فَرَازِينُ"', '', 'R', '', '', '', '', '', '', '"ج: فَرَازِينُ. : الْمَلِكَةُ فِي لُعْبَةِ الشِّطْرَنْجِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12977, 'فَرَازِينُ', 'فرازين', 'جامد', '', 'فرازين', 'فرزن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12978, 'إِفْرِيزٌ', 'إفريز', 'جامد', 'فرز', 'ءفريز', 'إفرز', '', '', '', 'مفرد', 'DnN', '', '', '"أفْاريزُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '": ""إِفْريزُ العِمارَةِ"" : ما يَبْرُزُ مِنْها في هَيْئَةِ حافَّةٍ أُفُقِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12979, 'أفْاريزُ', 'أفاريز', 'جامد', '', 'ءفاريز', 'فرز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12980, 'فَرْزَةٌ', 'فرزة', 'جامد', 'فرز', 'فرزة', 'فرزة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"فَرْزَةٌ - [ف ر ز]. ""فَرْزَةُ الأَرْضِ الغَلِيظَةِ"" : شَقٌّ يَكُونُ فِيهَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12981, 'فَرَزْدَقٌ', 'فرزدق', 'جامد', 'فرز', 'فرزدق', 'فرزدق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَرَزْدَقٌ - [ف ر ز]. 1. : رَغِيفٌ سَاقِطٌ فِي التَّنُّورِ.       2. : قِطَعُ العَجِينِ. 3. : فُتَاتُ خُبْزٍ. 4. : لَقَبُ شَاعِرٍ مِنْ شُعَرَاءِ العَصْرِ الأُمَوِيِّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12982, 'فِرَاسٌ', 'فراس', 'جامد', 'فرس', 'فراس', 'فرس', '', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', 'N', 'O', 'O', 'O', '', '"فِرَاسٌ - [ف ر س]. ""أَبُو فِرَاسٍ"" : الأَسَدُ، اِسْمُ عَلَمٍ لِلْمُذَكَّرِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12983, 'فَرِيسَةٌ', 'فريسة', 'جامد', 'فرس', 'فريسة', 'فرسة', '', '', '', 'مفرد', 'DnN', '', '', '"فَرَائِسُ"', '', '', '', '', '', '', '', '', '". ""اِنْقَضَّ عَلَى الْفَرِيسَةِ"": مَا يَفْتَرِسُهُ كُلُّ حَيَوَانٍ مُفْتَرِسٍ. ""وَقَعَ فَرِيسَةً بَيْنَ أَيْدِي أَعْدَائِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12984, 'فَرَائِسُ', 'فرائس', 'جامد', '', 'فراءس', 'فرس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12985, 'فَرَسٌ', 'فرس', 'جامد', '', 'فرس', 'فرس', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"فُرُوسٌ:فَرَسَاتٌ(مؤ:مذ)"', '', 'R', '', '', '', '', '', '', '"ج: فُرُوسٌ، فَرَسَاتٌ. (مؤ، مذ) (حو). 1.:مِنْ فَصِيلَةِالْخَيْلِيَّاتِ مِنْ رُتْبَةِ الظَّلْفِيَّاتِ، وَهُوَ حَيَوَانٌ أَهْلِيٌّ، يَكْثُرُ اسْتِعْمَالُهُ للِرُّكُوبِ وَالسِّبَاقِ وَجَرِّ الْعَرَبَاتِ. يُقَالُ أَيْضاً الْحِصَانُ للِذَّكَرِ. 2.""هُمَا كَفَرَسَيْ رِهَانٍ"". (مثل) : يُضْرَبُ لِلْمُتَنَافِسَيْنِ عَلَى غَايَةٍ وَاحِدَةٍ يَسْتَوِيَانِ فِي الْكَـفَــاءةِ وَالْمَقْدُرَة"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12986, 'فُرُوسٌ', 'فروس', 'جامد', '', 'فروس', 'فرس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
