INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12988, 'فَرْسَخٌ', 'فرسخ', 'جامد', '', 'فرسخ', 'فرسخ', '', '', '', 'جمع تكسير', 'DnN', '', '', '"فَرَاسِخُ"', '', 'R', '', '', '', '', '', '', '"ج: فَرَاسِخُ. ""قَطَعَ مَسَافَةَ فَرْسَخٍ"" : مِقْيَاسُ الْمَسَافَاتِ، يُقَدَّرُ بِثَلاَثَةِ أَمْيَالٍ، أَيْ مَا يُعَادِلُ سِتَّ كِيلُومِتْرَاتٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12989, 'فَرَاسِخُ', 'فراسخ', 'جامد', '', 'فراسخ', 'فرسخ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12990, 'فَرَاشٌ', 'فراش', 'جامد', 'فرش', 'فراش', 'فرش', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَرَاشٌ-فَرَاشٌ [ف ر ش]. 1.""فَرَاشُ الشَّرَابِ"" : حَبَابٌ يَعْلُوهُ. 2.""فَرَاشُ اللِّسَانِ"" : عِرْقَانِ أَخْضَرَانِ تَحْتَ اللِّسَانِ. 3.""فَرَاشُ الرَّأْسِ"" : عِظَامٌ رِقَاقٌ فِي الرَّأْسِ. 4.""فَرَاشُ الْحَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12991, 'فُرْشَاةٌ', 'فرشاة', 'جامد', 'فرش', 'فرشاة', 'فرشة', '', '', '', 'مفرد', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '"فُرْشَاةٌ-فُرْشَاةٌ [ف ر ش]. ن. فُرْشَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12992, 'فُرْشَةٌ', 'فرشة', 'جامد', 'فرش', 'فرشة', 'فرشة', '', '', '', 'مفرد', 'DnN', '', '', '"فُرُوشٌ"', '', 'R', '', '', '', '', '', '', '". 1.""فُرْشَةُ الثِّيَابِ"" : أَدَاةٌ ذَاتُ شَعْرٍ خَشِنٍ تُسْتَخْدَمُ لِتَنْظِيفِ الثِّيَابِ. 2.""فُرْشَةُ الأَسْنَانِ"": مَقْبِضٌ يَحْمِلُ فِي رَأْسِهِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12993, 'فُرُوشٌ', 'فروش', 'جامد', '', 'فروش', 'فرش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12994, 'فَرِيشٌ', 'فريش', 'جامد', 'فرش', 'فريش', 'فرش', '', '', '', 'مفرد', 'DnN', '', '', '"فَرَائِشُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""اِنْتَشَرَ الْفَرِيشُ فِي الْبِقَاعِ"" : النَّبَاتُ الْمُنْبَسِطُ عَلَى وَجْهِ الأَرْضِ وَلَمْ يَقُمْ عَلَى سَاقٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12995, 'فَرَائِشُ', 'فرائش', 'جامد', '', 'فراءش', 'فرش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12996, 'مِفْرَشَةٌ', 'مفرشة', 'جامد', 'فرش', 'مفرشة', 'مفرشة', '', '', '', 'مفرد', 'DnN', '', '', '"مَفَارِشُ"', '', 'R', '', '', '', '', '', '', '". 1. ""مِفْرَشَةُ الرَّاكِبِ"": فِرَاشٌ يَكُونُ عَلَى الرَّحْلِ يُقْعَدُ عَلَيْهِ. 2. ""مِفْرَشَةُ الجَالِسِ"" : فِرَاشٌ يُجْلَسُ عَلَيْهِ. 3. ""مِفْرَشَةُ الصَّحْنِ"" : مَا يُوضَعُ تَحْتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12997, 'مَفَارِشُ', 'مفارش', 'جامد', '', 'مفارش', 'مفرش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12998, 'مِفْرَشٌ', 'مفرش', 'جامد', 'فرش', 'مفرش', 'مفرش', '', '', '', 'مفرد', 'DnN', '', '', '"مَفَارِشُ"', '', 'R', '', '', '', '', '', '', '". ""مِفْرَشُ الْمَائِدَةِ"" : غِطَاؤُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(12999, 'مَفَارِشُ', 'مفارش', 'جامد', '', 'مفارش', 'مفرش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13000, 'فَرِيصَةٌ', 'فريصة', 'جامد', 'فرص', 'فريصة', 'فرصة', '', '', '', 'مفرد', 'DnN', '', '', '"فَرَائِصُ"', '', 'R', '', '', '', '', '', '', '"(تش). اللَّحْمَةُ بَيْنَ الْجَنْبِ وَالصَّدْرِ وَالْكَتِفِ، وَهُمَا فَرِيصَتَانِ. يُقَالُ : ""اِرْ"', '');
