INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13013, 'فُرْقَةٌ', 'فرقة', 'جامد', 'فرق', 'فرقة', 'فرقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"فُرْقَةٌ-فُرْقَةٌ [ف ر ق]. ""بَاعَدَتِ الْفُرْقَةُ بَيْنَهُمَا"" : الاِفْتِرَاقُ، الْفِرَاقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13014, 'فِرْقَةٌ', 'فرقة', 'جامد', 'فرق', 'فرقة', 'فرقة', '', '', '', 'مفرد', 'DnN', '', '', '"فِرَقٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""فِرْقَةٌ دِينِيَّةٌ"" : جَمَاعَةٌ، طَائِفَةٌ مِنَ النَّاسِ عَلَى دِينٍ مَّا، إِلاَّ أَنَّ لَهَا مُعْتَقَدَاتٍ وَمُمَارَسَاتٍ خَاصَّة بِهَا. ""فِرْقَةُ الْمُعْتَزِلَةِ"" ""فِرْقَةُ الشِّيعَةِ"" ""الْفِرَقُ الدِّينِيَّةُ الإِسْلاَمِيَّةُ"". 2.""فِرْقَةُ الرِّيَاضَةِ"" : مَجْمُوعَةٌ"', '');
