INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13022, 'فَرْقَدٌ', 'فرقد', 'جامد', '', 'فرقد', 'فرقد', '', '', '', 'جمع تكسير', 'DnN', '', '', '"فَرَاقِدُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: فَرَاقِدُ. (فك). 1. : كَوْكَبٌ مِنْ بَنَاتِ نَعْشٍ الصُّغْرَى قَرِيبٌ مِنَ الْقُطْبِ الشَّمَالِيِّ، وَيُسَمَّى ""النَّجْمُ الْقُطْبِ"', ':لا جذر:لا مفرد');
