INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13024, 'فَرْقِيعَةٌ', 'فرقيعة', 'جامد', 'فرقع', 'فرقيعة', 'فرقعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. : هِيَ مُتَفَجِّرَاتٌ سِلْمِيَّةٌ تُقْذَفُ فِي الْفَضَاءِ فَتَنْفَجِرُ، فَتُرْسِلُ أَلْوَاناً زَاهِيَةً. 2. : م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13025, 'مُفَرْقَعَةٌ', 'مفرقعة', 'جامد', 'فرقع', 'مفرقعة', 'مفرقعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""لَمْ يَكُونُوا يَسْمَعُونَ إِلاَّ الْمُفَرْقَعَاتِ"" : الْمُتَفَجِّرَاتُ."', '');
