INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13027, 'فَرِيكٌ', 'فريك', 'جامد', 'فرك', 'فريك', 'فرك', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَرِيكٌ - [ف ر ك]. 1. : الْمَفْرُوكُ مِنَ الْحَبِّ، الْمُنَقَّى. 2.""فَرِيكُ الْبُرِّ أَوِ الذُّرَةِ"" : هُوَ مَا يُشْوَى أَوَّلَ نُضجِهِ ثُمَّ يُدَبَّسُ وَيُجَشُّ وَيُطْبَخُ. 3.""فَرِيكَا اللِّسَانِ"" : عَظْمَانِ فِي أَصْلِ اللِّسَانِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13028, 'فَرِيكِيَّةٌ', 'فريكية', 'جامد', 'فرك', 'فريكية', 'فركة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"فَرِيكِيَّةٌ-فَرِيكِيَّةٌ [ف ر ك]. : طَعَامٌ يُحَضَّرُ مِنَ الْحَبِّ الْمَفْرُوكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13029, 'مَفْرُوكَةٌ', 'مفروكة', 'جامد', 'فرك', 'مفروكة', 'مفركة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَفْرُوكَةٌ-مَفْرُوكَةٌ [ف ر ك] (طخ). : طَعَامٌ مِنْ فَطِيرِ الذُّرَةِ ونَحْوِهَا "', '');
