INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13069, 'فَسَافِسُ', 'فسافس', 'جامد', 'فسفس', 'فسافس', 'فسفس', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '". : حَشَرَةٌ سَوْدَاءُ، خَبِيثَةُ الرَّائِحَةِ، مُضِرَّةٌ، مَا يُعْرَفُ بِالبَقَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13070, 'فُسْتَانٌ', 'فستان', 'جامد', '', 'فستان', 'فستن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"فَسَاتِينُ"', '', 'R', '', '', '', '', '', '', '"ج: فَسَاتِينُ. ""جَاءتْ تَخْتَالُ بِفُسْتَانِهَا الْجَمِيلِ"" : "', ':لا جذر:لا مفرد');
