INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13072, 'فُسْفُورٌ', 'فسفور', 'جامد', '', 'فسفور', 'فسفر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"فُسْفُورٌ-فُسْفُورٌ (كيما). : جِسْمٌ بَسِيطٌ سَرِيعُ الالْتِهَابِ، مُضِيءٌ فِي الظُّلْمَةِ، يَدْخُلُ فِي تَرْكِيبِ الْعِظَامِ وَهُوَ ضَرُورِيٌّ لِلْحَيَاةِ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13073, 'فَسْقِيَّةٌ', 'فسقية', 'جامد', '', 'فسقية', 'فسقة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"فَسَاقِيُّ"', '', '', '', '', '', '', '', '', '"ج: فَسَاقِيُّ. : حَوْضٌ مِنَ الرُّخَامِ وَنَحْوِهِ، وَهُوَ فِي الأَغْلَبِ يَكُونُ مُسْتَدِيراً وَفِي وَسَطِهِ نَافُورَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13074, 'فَسَاقِيُّ', 'فساقي', 'جامد', '', 'فساقي', 'فسق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13075, 'فُسَالَةٌ', 'فسالة', 'جامد', 'فسل', 'فسالة', 'فسلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"فُسَالَةٌ-فُسَالَةٌ [ف س ل]. ""فُسَالَةُ الْحَدِيدِ"" : مَا تَنَاثَرَ مِنْهُ عِنْدَ الطَّرْقِ إِذَا طُبِعَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13076, 'فَسِيلَةٌ', 'فسيلة', 'جامد', 'فسل', 'فسيلة', 'فسلة', '', '', '', 'مفرد', 'DnN', '', '', '"فَسَائِلُ"', '', '', '', '', '', '', '', '', '". 1. : النَّخْلَةُ الْفَرْعِيَّةُ مِنَ الأُمِّ، تُقْطَعُ فَتُغْرَسُ. 2. : كُلُّ عُودٍ يُقْطَعُ مِنْ شَجَرَتِهِ فَيُغْرَسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13077, 'فَسَائِلُ', 'فسائل', 'جامد', '', 'فساءل', 'فسل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
