INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13079, 'فِشَّةٌ', 'فشة', 'جامد', 'فشش', 'فشة', 'فشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"فِشَّةٌ - [ف ش ش]. : رِئَةٌ تَفُشُّ مَا فِيهَا مِنْ هَوَاءٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13080, 'فِصْحٌ', 'فصح', 'جامد', 'فصح', 'فصح', 'فصح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فِصْحٌ-فِصْحٌ [ف ص ح]. عِيدُ الْفِصْحِ. أ. : عِنْدَ الْمَسِيحِيِّينَ هُوَ يَوْمُ تَذْكَارِ قِيَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13081, 'فَصِيدٌ', 'فصيد', 'جامد', 'فصد', 'فصيد', 'فصد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَصِيدٌ-فَصِيدٌ [ف ص د]. : دَمٌ يُوضَعُ فِي مِعـىً وَيُشْوَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13082, 'فَصٌّ', 'فص', 'جامد', 'فصص', 'فص', 'فص', '', '', '', 'مفرد', 'DnN', '', '', '"فُصُوصٌ"', '', 'R', '', '', '', '', '', '', '". 1.""فَصُّ الْعَظْمَيْنِ"" : مُلْتَقَى كُلِّ عَظْمَيْنِ، وَالْمَفَاصِلُ كُلُّهَا فُصُوصٌ. 2.""فَصُّ الْخَاتَمِ"" : مَا يُرَكَّبُ فِي وَسَطِهِ مِنَ الْحِج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13083, 'فُصُوصٌ', 'فصوص', 'جامد', '', 'فصوص', 'فصص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13084, 'فِصْفَصَةٌ', 'فصفصة', 'جامد', 'فصفص', 'فصفصة', 'فصفصة', '', '', '', 'مفرد', 'DnN', '', '', '"فَصَافِصُ"', '', 'R', '', '', '', '', '', '', '". ""أَطْعَمَ الدَّوَابَّ الفِصْفَصَةَ"" : نَبَاتٌ أَخْضَرُ رَطْبٌ تَأْكُلُهُ الدَّوَابُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13085, 'فَصَافِصُ', 'فصافص', 'جامد', '', 'فصافص', 'فصفص', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
