INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13087, 'فَصْلَةٌ', 'فصلة', 'جامد', 'فصل', 'فصلة', 'فصلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'Rp', '', '', '', '', '', '', '"فَصْلَةٌ-فَصْلَةٌ [ف ص ل]. 1.""فَصْلَةُ نَخْلَةٍ"" : النَّخْلَةُ الْمَنْقُولَةُ مِنْ مَوْضِعِهَا. 2.""فَصْلَةٌ مِنْ كِتَابٍ أَوِ مَجَلَّةٍ"" : جُزْءٌ أَوْ مَقَالٌ أَوْ بَحْثٌ مُنْتَزَعٌ مِنْهُمَا. 3. : فَاصِلَةٌ، مِنْ عَلاَمَاتِ التَّرْقِيمِ، تُرْسَمُ هَكَذَا (،)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13088, 'فُصِّلَتْ', 'فصلت', 'جامد', 'فصل', 'فصلت', 'فصلت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '"فُصِّلَتْ-فُصِّلَتْ [ف ص ل]. : سُورَةٌ مِنْ سُوَرِ القُرْآنِ.فصلت آية 3كِتَابٌ فُصِّلَتْ آيَات"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13089, 'فَصِيلَةٌ', 'فصيلة', 'جامد', 'فصل', 'فصيلة', 'فصلة', '', '', '', 'مفرد', 'DnN', '', '', '"فَصَائِلُ"', '', '', '', '', '', '', '', '', '". 1.""فَصِيلَةُ عُضْوٍ"" : الْقِطْعَةُ مِنْ أَعْضَاءِ الْجَسَدِ. 2.""فَصِيلَةُ الْفَخِذِ"" : الْقِطْعَةُ مِنْهُ. 3.""فَصِيلَةُ الرَّجُلِ"" : عَشِيرَتُهُ. 4.""جَاءوا بِفَصِيلَتِهِمْ"" : بِأَجْمَعِهِمْ. 5.""فَصِيلَةُ الْحَيَوَانِ أَوِ النَّبَاتِ"" : جُمْلَةُ أَجْنَاسٍ مُتَقَارِبَةٍ لَهَا صِفَاتٌ مُشْتَرَكَةٌ. 6.""فَصِيلَةُ الْجَيْشِ"" : الْفِرْقَةُ مِنْهُ. ""فَصَائِلُ الْمُقَاوَمَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13090, 'فَصَائِلُ', 'فصائل', 'جامد', '', 'فصاءل', 'فصل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
