INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13094, 'فَيْصَلٌ', 'فيصل', 'جامد', 'فصل', 'فيصل', 'فصل', '', '', '', 'مفرد', 'DnN', '', '', '"فَيَاصِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""نَطَقَ الْفَيْصَلُ بِالْحُكْمِ النِّهَائِيِّ"" : الْقَاضِي، الْحَاكِمُ. 2.""أَصْدَرَ حُكْماً فَيْصَلاً"": حُكْماً نِهَائِيّاً. 3.""طَعَنَهُ بِفَيْصَلٍ حَادٍّ"" : بِسَيْفٍ حَادٍّ. 4.""فَيْصَل"" : اِسْمُ عَلَمٍ للِذُّكُورِ."', '');
