INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13097, 'مِفْصَلَةٌ', 'مفصلة', 'جامد', 'فصل', 'مفصلة', 'مفصلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مِفْصَلَةٌ-مِفْصَلَةٌ [ف ص ل]. ""مِفْصَلَةُ البَابِ"" : أَدَاةٌ حَدِيدِيَّةٌ ونَحْوُهَ"', '');
