INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13099, 'مَفَاصِلُ', 'مفاصل', 'جامد', '', 'مفاصل', 'مفصل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13100, 'فَضَاحَةٌ', 'فضاحة', 'جامد', 'فضح', 'فضاحة', 'فضحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"فَضَاحَةٌ-فَضَاحَةٌ [ف ض ح]. ""يَا لَهَا مِنْ فَضَاحَةٍ! "" : كَشْفُ الْمَسَاوِئِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13101, 'فَضِيحَةٌ', 'فضيحة', 'جامد', 'فضح', 'فضيحة', 'فضحة', '', '', '', 'مفرد', 'DnN', '', '', '"فَضَائِحُ"', '', '', '', '', '', '', '', '', '". ""فَضِيحَةٌ أَخْلاَقِيَّةٌ"" : اِنْكِشَافُ الْمَسَاوِئِ أَمَامَ الْملَإِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13102, 'فَضَائِحُ', 'فضائح', 'جامد', '', 'فضاءح', 'فضح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13103, 'فَضْلَةٌ', 'فضلة', 'جامد', 'فضل', 'فضلة', 'فضلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""فَضْلَةُ الطَّعَامِ"" : الْبَقِيَّةُ مِنْهُ. ""الإِنْجِيلُ يَقُولُ : لَيْسَ بِالْخُبْزِ وَحْدَهُ يَحْيَى الإِنْسَانُ، ثَمَّ الْكَلْبُ يَجِد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13104, 'فُضُلٌ', 'فضل', 'جامد', 'فضل', 'فضل', 'فضل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فُضُلٌ-فُضُلٌ [ف ض ل]. 1.""اِرْتَدَى فُضُلاً"" : مَا يُلْبَسُ فِي البَيْتِ أَوْ لِلنَّوْمِ أَوِ العَمَلِ. 2.""رَجُلٌ فُضُلٌ"" : أَيْ مُتَفَضِّلٌ بِثَوْبٍ وَاحِدٍ. ""اِمْرَأَةٌ فُضُلٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13105, 'فَضِيلَةٌ', 'فضيلة', 'جامد', 'فضل', 'فضيلة', 'فضلة', '', '', '', 'مفرد', 'DnN', '', '', '"فَضَائِلُ"', '', '', '', '', '', '', '', '', '". 1.""مَعْرُوفٌ بِالْفَضِيلَةِ"": بِالدَّرَجَةِ الرَّفِيعَةِ فِي الْفَضْلِ. 2.""فَضِيلَةُ الْعَمَلِ"" : مَزِيَّتُهُ. ""فَضِيلَةُ الصَّوْم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13106, 'فَضَائِلُ', 'فضائل', 'جامد', '', 'فضاءل', 'فضل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
