INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13110, 'فِطَحْلٌ', 'فطحل', 'جامد', '', 'فطحل', 'فطحل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"فَطَاحِلُ"', '', 'R', '', '', '', '', '', '', '"ج: فَطَاحِلُ. 1.""أَخَذَهُ الْفِطَحْلُ"" : السَّيْلُ الْعَظِيمُ. 2.""مِنْ فَطَاحِلِ الْعُلَمَاءِ"" : مِنْ عُظَمَائِهِمْ، مَنْ كَانَ نَاراً عَلَى عَلَمٍ، أَيْ مَشْهُوراً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13111, 'فَطَاحِلُ', 'فطاحل', 'جامد', '', 'فطاحل', 'فطحل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13112, 'فِطْرَةٌ', 'فطرة', 'جامد', 'فطر', 'فطرة', 'فطرة', '', '', '', 'مفرد', 'DnN', '', '', '"فِطَرٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""ما يَزَالُ عَلَى الْفِطْرَةِ"" : الصِّفَةُ الأُولَى الَّتِي يَكُونُ عَلَيْهَا الإِنْسَانُ فِي أَوَّلِ حَيَاتِهِ، أَيْ خِلْقَتُهُ الطَّبِيعِيَّةُ. الروم آية 30فِطْرَةُ اللَّهِ الَّتِي فَطَرَ النَّاسَ عَلَيْهَا (قرآن). 2.""أَخْرَجَ الْفِطْرَةَ"" : أَيْ صَدَقَةَ عِيدِ الْفِطْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13113, 'فِطَرٌ', 'فطر', 'جامد', '', 'فطر', 'فطر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13114, 'فِطْرٌ', 'فطر', 'جامد', 'فطر', 'فطر', 'فطر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فِطْرٌ-فِطْرٌ [ف ط ر]. 1. : حَبَّاتُ الْعِنَبِ إِذَا بَدَتْ رُؤُوسُهَا. 2.""عِيدُ الْفِطْرِ"" : عِيدُ الْمُسْلِمِيَن يَحُلُّ بَعْدَ صَوْمِ شَهْرِ رَمَضَانَ. 3.""صَدَقَةُ الْفِطْرِ أَوْ زَكَاةُ الْفِطْرِ"" : مَا يُقَدِّمُهُ الْمُسْلِمُ مِنْ صَدَقَةٍ وَاجِبَةٍ فِي عِيدِ الْفِطْرِ. 4.""رَجُلٌ فِطْرٌ"" : مُفْطِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13115, 'فُضَالَةٌ', 'فضالة', 'جامد', 'فضل', 'فضالة', 'فضلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""فُضَالَةُ الطَّعَامِ"" : الْبَقِيَّةُ مِنْهُ، فَضْلَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13116, 'فُطُورٌ', 'فطور', 'جامد', 'فطر', 'فطور', 'فطر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فُطُورٌ-فُطُورٌ [ف ط ر]. ن. فَطُورٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13117, 'فَطِيرَةٌ', 'فطيرة', 'جامد', 'فطر', 'فطيرة', 'فطرة', '', '', '', 'مفرد', 'DnN', '', '', '"فَطَائِرُ"', '', '', '', '', '', '', '', '', '". ""حَضَّرَتْ فَطَائِرَ للِضُّيُوفِ""(طخ) : رُقَاقَةٌ مِنَ الْعَجِينِ تُوضَعُ بِدَاخِلِهَا التَّوَابِلُ أَوِ اللَّحْمُ وَأَنْوَاعٌ مِنَ الْخُضْرَةِ تُثْنَى وَتُخْبَزُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13118, 'فَطَائِرُ', 'فطائر', 'جامد', '', 'فطاءر', 'فطر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13119, 'فِطِّيسَةٌ', 'فطيسة', 'جامد', 'فطس', 'فطيسة', 'فطسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"فِطِّيسَةٌ-فِطِّيسَةٌ [ف ط س]. ""فِطِّيسَةُ الْخِنْزِيرِ"" : أَنْفُهُ وَمَا وَالاَهُ، خَطْمُهُ، فِنْطِيسَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13120, 'فِضَّةٌ', 'فضة', 'جامد', 'فضض', 'فضة', 'فضة', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فِضَّةٌ-فِضَّةٌ [ف ض ض]. : مَعْدِنٌ أَبْيَضُ كَانَتْ تُضْرَبُ مِنْهُ النُّقُودُ وَتُصْنَعُ مِنْهُ الْحِلِيُّ التَّقْلِيدِيَّةُ، وَالْفِضَّةُ أَكْثَرُ الْمَعَادِنِ قَابِلِيَّةً للِتَّطْرِيقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13121, 'فِطَامٌ', 'فطام', 'جامد', 'فطم', 'فطام', 'فطم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فِطَامٌ-فِطَامٌ [ف ط م]. ""فِطَامُ الوَلَدِ"" : فَصْلُهُ عَنِ الرَّضَاعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13122, 'فِطْنَةٌ', 'فطنة', 'جامد', 'فطن', 'فطنة', 'فطنة', '', '', '', 'مفرد', 'DnN', '', '', '"فِطَنٌ"', '', 'R', '', '', '', '', '', '', '". ""يَتَمَتَّعُ بِفِطْنَةٍ خَارِقَةٍ"" : بِحِذْقٍ وَمَهَارَةٍ فِي الْفَهْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13123, 'فِطَنٌ', 'فطن', 'جامد', '', 'فطن', 'فطن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13124, 'فَطِيسَةٌ', 'فطيسة', 'جامد', '', 'فطيسة', 'فطسة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '": مِطْرَقَةٌ كَبِيرَةٌ، يَسْتَعْمِلُهَا الْحَدَّادُ، كَمَا يُمْكِنُ أَنْ تُسْتَعْمَلَ لِتَكْسِيرِ الْحِجَارَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13125, 'فَاقِعَةٌ', 'فاقعة', 'جامد', 'فقع', 'فاقعة', 'فقعة', '', '', '', 'مفرد', 'DnN', '', '', '"فَوَاقِعُ"', '', '', '', '', '', '', '', '', '". ""نَزَلَتْ بِهِ الفَاقِعَةُ"" : النَّازِلَةُ الْمُفْجِعَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13126, 'فَوَاقِعُ', 'فواقع', 'جامد', '', 'فواقع', 'فقع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13127, 'فَظَائِعُ', 'فظائع', 'جامد', 'فظع', 'فظاءع', 'فظع', '', '', '', 'مفرد', '', '', '', '"مفردفَظَاعَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""فَظَائِعُ الْحَرْبِ"" : وَيْلاَتُهَا، شَرَاسَتُهَا، مَجَازِرُهَا. ""اِرْتَكَبَ الْعَدُوُّ الإِسْرَائِيلِيُّ فَظَائِعَ يَشِيبُ لَهَا الْوِلْدَانُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13128, 'فَظَاعَة', 'فظاعة', 'جامد', '', 'فظاعة', 'فظعة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13129, 'فِعَالٌ', 'فعال', 'جامد', 'فعل', 'فعال', 'فعل', '', '', '', 'مفرد', 'DnN', '', '', '"فُعُلٌ"', '', 'R', '', '', '', '', '', '', '". 1.""فِعْلٌ فِعَالٌ"" : إِذَا كَانَ مِنْ فَاعِلَيْنِ مُتَعَدِّدَيْنِ. 2.""فِعَالُ الفَأْسِ أَوِ الْمِطْرَقَةِ"" : نِصَابُهَا، مَقْبِضُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13130, 'فُعُلٌ', 'فعل', 'جامد', '', 'فعل', 'فعل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13131, 'فُقَاسٌ', 'فقاس', 'جامد', 'فقس', 'فقاس', 'فقس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فُقَاسٌ-فُقَاسٌ [ف ق س]. ""أُصِيبَ بِالفُقَاسِ"" : دَاءٌ فِي الْمَفَاصِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13132, 'فِعْلٌ', 'فعل', 'جامد', 'فعل', 'فعل', 'فعل', '', '', '', 'مفرد', 'DnN', '', '', '"أَفْعَالٌ:أَفَاعِيلُ"', '', 'R', '', '', '', '', '', '', '". 1.""الْفِعْلُ"" (نح) : هُوَ لَفْظٌ يَدُلُّ عَلَى حَالَةٍ أَوْ حَدَثٍ يَقْتَرِنُ بِزَمَانٍ فِي الْمَاضِي أَوِ الْحَاضِرِ أَوِ الْمُسْتَقْبَلِ. ""خَرَجَ، وَقَفَ، نَامَ""، ""يَخْرُجُ، أَخْرُجُ"". 2.""لَمْ يَك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13133, 'أَفْعَالٌ', 'أفعال', 'جامد', '', 'ءفعال', 'فعل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
