INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13137, 'فَقَارَةٌ', 'فقارة', 'جامد', 'فقر', 'فقارة', 'فقرة', '', '', '', 'مفرد', 'DnN', '', '', '"فَقَارٌ"', '', 'R', '', '', '', '', '', '', '". 1.""فَقَارَةُ الظَّهْرِ"" : فَقْرَتُهُ، الْخَرَزَةُ مِنْ خَرَزَاتِ السِّلْسِلَةِ العَظْمِيَّةِ الظَّهْرِيَّةِ الْمُمْتَدَّةِ مِنَ الرَّأْسِ إِلَى العُصْعُصِ. 2.""فَقَارُ السَّمَاءِ"" : كَوَاكِبُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13138, 'فَقَارٌ', 'فقار', 'جامد', '', 'فقار', 'فقر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13139, 'فَقَارِيَّاتٌ', 'فقاريات', 'جامد', 'فقر', 'فقاريات', 'فقرت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"فَقَارِيَّاتٌ-فَقَارِيَّاتٌ [ف ق ر]. : فَصِيلَةٌ حَيَوَانِيَّةٌ مِنْ مُخْتَلِفِ الأَصْنَافِ، لَهَا جَمِيعُهَا عَمُودٌ فَقْرِيٌّ، وَهِيَ الأَسْمَاكُ وَالْبَرْمَائِيَّاتُ وَالزَّوَاحِفُ وَالطُّيُورُ وَالثَّدْيِيَّاتُ."', '');
