INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13264, 'أَفْؤُلٌ', 'أفؤل', 'جامد', '', 'ءفءل', 'فل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13265, 'فُوَّةٌ', 'فوة', 'جامد', '', 'فوة', 'فة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"فُوَّةٌ-فُوَّةٌ (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الْفُوِّيَّاتِ، مُعَمِّرٌ، لَهُ سِيقَانٌ حُمْرٌ مُتَسَلِّقَةٌ، وَجُذُورُهُ تُسْتَخْرَجُ مِنْهَا مَادَّةٌ حَمْرَاءُ، تُعْرَفُ بِفُوَّةِ الصَّبَّاغِينَ، وَمَادَّتُهُ تُسْتَعْمَلُ فِي صَبْغِ الْحَرِيرِ وَالصُّوفِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13266, 'فُولٌ', 'فول', 'جامد', 'فول', 'فول', 'فل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فُولٌ-فُولٌ [ف و ل] (نب). 1. : نَبَاتٌ عُشْبِيٌّ مِنْ فَصِيلَةِ الْقَطَانِيَّاتِ، يُؤْكَلُ أَخْضَرَ وَ يَابِساً وَنَيِّئاً مَطْبُوخاً. 2.""الْفُولُ السُّودَانِيُّ"" (نب) : هُوَ مَا يُعْرَف بِفُسْتُق الْعَبِيدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13267, 'أَفْواهٌ', 'أفواه', 'جامد', 'فوه', 'ءفواه', 'فه', '', '', '', 'مفرد', '', '', '', '"مفردفوهٌ:فَمٌ"', '', '', '', '', '', '', '', '', '".آل عمران آية 167 يَقولونَ بِأَفْواهِهِمْ ما لَيْسَ في قُلوبِهِمْ (قرآن): الأَفْمامُ مَوْضِعُ خُروجِ الكَلامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13268, 'فَاهٌ', 'فاه', 'جامد', 'فوه', 'فاه', 'فه', '', '', '', 'مفرد', 'DnN', '', '', '"أَفْوَاهٌ"', '', 'R', '', '', '', '', '', '', '". ""فَتَحَ فَاهَهُ"" : فَمَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13269, 'أَفْوَاهٌ', 'أفواه', 'جامد', '', 'ءفواه', 'فه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13270, 'فُوَّهَةٌ', 'فوهة', 'جامد', 'فوه', 'فوهة', 'فهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""فُوَّهَةُ النَّاسِ"" : القِيلُ وَالقَالُ وَمَا يُشَاعُ. ""يَخْشَى فُوَّهَةَ النَّاسِ"". 2.""إِنَّهُ ذُو فُوَّهَةٍ"" : ذُو قَالَةٍ فِي النَّاسِ، أَي شَدِيدُ الكَلامِ فِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13271, 'فُوهٌ', 'فوه', 'جامد', '', 'فوه', 'فه', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَفْوَاهٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَفْوَاه. 1.""فُوهُ الإِنْسَانِ"" : فَمُهُ. 2.""طَيَّبَ الطَّعَامَ بِالْفُوهِ"" : طَيَّبَهُ بِالتَّابِلِ. جَمْعُ أَفَاوِيه."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13272, 'أَفْوَاهٌ', 'أفواه', 'جامد', '', 'ءفواه', 'فه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13273, 'أَفَاوِيهُ', 'أفاويه', 'جامد', 'فوو', 'ءفاويه', 'فه', '', '', '', 'مفرد', '', '', '', '"مفردفُوَّهٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ن. أفْوَاهٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13274, 'فُوِيّاتٌ', 'فويات', 'جامد', '', 'فويات', 'فت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"فُوِيّاتٌ-فُوِيّاتٌ (نب). : فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ، أَنْوَاعُهَا عَدِيدَةٌ جِدّاً، مِنْ بَيْنِهَا البُنُّ وَالكِينَا وَالفُوَّةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13275, 'فِيتَامِين', 'فيتامين', 'جامد', '', 'فيتامين', 'فتمن', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: ـات. : مَادَّةٌ عُضْوِيَّةٌ مُتَنَوِّعَةٌ، تُوجَدُ بِقِلَّةٍ فِي كَثِيرٍ مِنَ الأَطْعِمَةِ، وَهِيَ ضَرُورِيَّةٌ لإِتْمَامِ التَّغْذِيَّةِ وَتَنْشِيطِ الْحَيَوِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13276, 'فَيْجَنٌ', 'فيجن', 'جامد', '', 'فيجن', 'فجن', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"فَيْجَنٌ-فَيْجَنٌ، ةٌ (نب). : نَبَاتٌ وَرَقُهُ يُشْبِهُ الصَّعْتَرَ، يُعْرَفُ بِالسَّذَابِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13277, 'فَيْحَاءُ', 'فيحاء', 'جامد', 'فيح', 'فيحاء', 'فح', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"فَيْحَاءُ-فَيْحَاءُ [ف ي ح]. 1.""يَسْكُنُ فِي فَيْحَاءَ"" : فِي دَارٍ وَاسِعَةٍ. 2.""زَارَ دِمَشْقَ الْفَيْحَاءَ"" : لَقَبُ دِمَشْقَ، كَمَا تُطْلَقُ عَلَى الْبَصْرَةِ وَطَرَابُلُسَ وَفَاسَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13278, 'فَائِدَةٌ', 'فائدة', 'جامد', 'فيد', 'فاءدة', 'فدة', '', '', '', 'مفرد', 'DnN', '', '', '"فَوَائِدُ"', '', '', '', '', '', '', '', '', '". 1.""اِسْتَفَادَ فَائِدَةً عُظْمَى مِنْ عِلْمِهِ"" : مَا يَسْتَفِيدُهُ الإِنْسَانُ مِنْ عِلْمِ أَوْ عَمَلٍ أَوْ مَالٍ. ""مَا أَشَدَّ تَنَوُّعَهُ وَأَعْظَمَ فَائِدَتَهُ"". 2.""حَصَلَ عَلَى فَائِدَةٍ مِنْ زِيَارَتِهِ"" : الزِّيَارَةُ التَّيِ تَحْصُلُ لِلْإِنْسَانِ وَت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13279, 'فَوَائِدُ', 'فوائد', 'جامد', '', 'فواءد', 'فد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13280, 'مُفَادٌ', 'مفاد', 'جامد', 'فيد', 'مفاد', 'مفد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مُفَادٌ-مُفَادٌ [ف ي د]. ""حَدَّثَنِي بِكَلاَمٍ مُفَادُهُ أَنَّكَ لَنْ تَعُودَ"": مَضْمُونُهُ، فَحْوَاهُ. ""خَبَرٌ مُفَادُهُ أَنَّ ...""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13281, 'فَيْرُوز', 'فيروز', 'جامد', '', 'فيروز', 'فرز', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1. : حَجَرٌ كَرِيمٌ غَيْرُ شَفَّافٍ، أَزْرَقُ اللَّوْنِ بِلَوْنِ السَّمَاءِ أَوْ أَمْيَلُ إِلَى الْخُضْرَةِ قَلِيلاً. 2. ""فَيْروز"" : اِسْمُ عَلَمٍ لِلْإِنَاثِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13282, 'فِيرُوس', 'فيروس', 'جامد', '', 'فيروس', 'فرس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": كَائِنَاتٌ حَيَّةٌ مُتَنَاهِيَةٌ فِي الصِّغَرِ، تُرَى بِالْمِجْهَرِ الإِلِكْتَرُونِيِّ، تَنْفُذُ مِنَ الرَّاشِحَاتِ البَكْتِيرِيَّةِ وَتُحْدِثُ بَعْضَ الأَمْرَاضِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13283, 'فِيزِيَاءُ', 'فيزياء', 'جامد', '', 'فيزياء', 'فز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rz', '', '', '', '', '', '', '": عِلْمٌ يَبْحَثُ وَيَدْرُسُ الْخَوَاصَّ الْعَامَّةَ لِلْمَادَّةِ وَالْفَضَاءِ وَالزَّمَانِ، وَيُحَدِّدُ الْقَوَانِينَ الَّتِي تُظْهِرُ الظَّوَاهِرَ الطَّبِيعِيَّةَ، عِلْمُ الطَّبِيعِيَّاتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13284, 'فِيلَجَةٌ', 'فيلجة', 'جامد', '', 'فيلجة', 'فلجة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"فَيَالِجُ"', '', 'R', '', '', '', '', '', '', '"ج: فَيَالِجُ. : بَيْتٌ مِنْ حَرِيرٍ تَنْسُجُهُ دُودَةُ الْقَزِّ عَلَى نَفْسِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13285, 'فَيَالِجُ', 'فيالج', 'جامد', '', 'فيالج', 'فلج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13286, 'فِيلِيَّاتٌ', 'فيليات', 'جامد', '', 'فيليات', 'فلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"فِيلِيَّاتٌ-فِيلِيَّاتٌ (حو). : فَصِيلَةُ الأَفْيَالِ، مِنْ رُتْبَةِ الْخُرْطُومِيَّاتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13287, 'أُفْنُونٌ', 'أفنون', 'جامد', 'فين', 'ءفنون', 'فنن', '', '', '', 'مفرد', 'DnN', '', '', '"أَفانِينُ"', '', 'R', '', '', '', '', '', '', '". 1. ""شَذَبَ أُفْنوناً"": الْغُصْنُ الْمُلْتَفُّ. 2.""هُوَ فِي أفْنونِهِ"" : فِي أوَّلِ شَبابِهِ. 3.""أفانِينُ الكَلاَمِ"" : أنْوَاعُهُ، أسالِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13288, 'أَفانِينُ', 'أفانين', 'جامد', '', 'ءفانين', 'فنن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13289, 'فَيْنَةٌ', 'فينة', 'جامد', 'فين', 'فينة', 'فنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"فَيْنَةٌ-فَيْنَةٌ [ف ي ن]. 1.""أَلْقَاهُ الْفَيْنَةَ بَعْدَ الْفَيْنَةِ"" : أَيْ حِيناً بَعْدَ حِينٍ. 2.""بَيْنَ الْفَيْنَةِ وَالأُخْرَى"" : بَيْنَ الْحِينِ وَالآخَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13290, 'قَاتِيَّاتٌ', 'قاتيات', 'جامد', '', 'قاتيات', 'قتت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '"قَاتِيَّاتٌ-قَاتِيَّاتٌ (نب). : فَصِيلَةٌ نَبَاتِيَّةٌ زِرَاعِيَّةٌ مِنْ أَهَمِّ أَنْوَاعِهَا القَاتُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13291, 'قَادُوسٌ', 'قادوس', 'جامد', '', 'قادوس', 'قدس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"قَوَادِيسُ"', '', 'R', '', '', '', '', '', '', '"ج: قَوَادِيسُ. 1. : وِعَاءٌ كَبِيرٌ قَمْعِيُّ الشَّكْلِ، يُلْقَى فِيهِ الْحَبُّ عِنْدَ الطَّحْنِ. 2.""قَادُوسُ الْمَجَارِي"" : أُنْبُوبٌ مُ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13292, 'قَوَادِيسُ', 'قواديس', 'جامد', '', 'قواديس', 'قدس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13293, 'قَارِبٌ', 'قارب', 'جامد', '', 'قارب', 'قرب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"قَوَارِبُ"', '', 'R', '', '', '', '', '', '', '"ج: قَوَارِبُ. ""أَبْحَرَ عَلَى ظَهْرِ قَارِبٍ"" : أَيْ مَرْكَب بَحْرِيّ. ""قَوَارِبُ الصَّيْدِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13294, 'قَوَارِبُ', 'قوارب', 'جامد', '', 'قوارب', 'قرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
