INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13296, 'قَاقُمٌ', 'قاقم', 'جامد', '', 'قاقم', 'ققم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قَاقُمٌ-قَاقُمٌ (حو).: حَيَوَانٌ ثَدْيِيٌّ مِنْ فَصِيلَةِ السَّمُّورِيَّاتِ، مِنْ رُتْبَةِ الضَّواَرِي، شَبِيهٌ بِابْنِ عِرْسٍ، لَوْنُهُ أَحْمَر"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13297, 'قَاقُومٌ', 'قاقوم', 'جامد', '', 'قاقوم', 'ققم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ن. قَاقُم."', ':لا جذر:لا مفرد');
