INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13299, 'قَوَاوِيقُ', 'قواويق', 'جامد', '', 'قواويق', 'قق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13300, 'قَاوُونٌ', 'قاوون', 'جامد', '', 'قاوون', 'قن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قَاوُونٌ-قَاوُونٌ (نب). : نَبَاتٌ عُشْبِيٌّ مِنْ فَصِيلَةِ القَرْعِيَّاتِ، نَوْعُهُ يَمِيلُ إِلَى الاصْفِرَارِ حُلْوُ الْمَذَاقِ وَال"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13301, 'قَائِمْقَامٌ', 'قائمقام', 'جامد', '', 'قاءمقام', 'قمقم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"1. : رُتْبَةٌ عَسْكَرِيَّةٌ، عَقِيدٌ. 2. : مُوَظَّفٌ إِدَارِيٌّ دُونَ الْمُحَافِظِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13302, 'قَائِمْقَامِيَّةٌ', 'قائمقامية', 'جامد', '', 'قاءمقامية', 'قمقمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '"1. : مَنْصِبُ الْقَائِمْقَامِ. 2. : مُقَاطَعَةٌ إِدَارِيَّةُ يُدِيرُ أَعْمَالَهَا الْقَائِمْقَامُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13303, 'قُبَّةٌ', 'قبة', 'جامد', 'قبب', 'قبة', 'قبة', '', '', '', 'مفرد', 'DnN', '', '', '"قِبَابٌ:قُبَبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""قُبَّةُ الْمَسْجِدِ"" : بِنَاءٌ سَقْفُهُ نِصْفُ دَائِرِيٍّ مُقَعَّرٌ مِنْ دَاخِلِـهِ. ""قُبَّةُ الْقُـدْسِ شَمْسُ الْمَشْرِقِ"". 2.""الْقُبَّةُ الزَّرْقَاءُ أَوِ الْخَضْرَاءُ "" : السَّمَاء. 3.""الْق"', '');
