INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13306, 'قَبٌّ', 'قب', 'جامد', 'قبب', 'قب', 'قب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَبٌّ-قَبٌّ [ق ب ب]. 1.""قَبُّ القَوْمِ"" : رَئِيسُهُمْ، سَيِّدُهُمْ . ""عَلَيْكَ بِالقَبِّ الأَكْبَرِ"". 2."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13307, 'قِبٌّ', 'قب', 'جامد', 'قبب', 'قب', 'قب', '', '', '', 'مفرد', 'DnN', '', '', '"أَقْبَابٌ"', '', 'R', '', '', '', '', '', '', '". 1. : الْعَظْمُ النَّاتِئُ مِنَ الظَّهْرِ بَيْنَ الأَلْيَتَيْنِ. 2.""قِبُّ الْجِلْبَابِ"" : غِطَاءُ الرَّأْسِ الْمُلْتَصِقُ بِالْجِلْبَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13308, 'أَقْبَابٌ', 'أقباب', 'جامد', '', 'ءقباب', 'قبب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13309, 'قِبِّيَّةٌ', 'قبية', 'جامد', 'قبب', 'قبية', 'قبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""قِبِّيَّةُ مِعْطَفٍ"" : غِطَاءُ الرَّأْسِ يَكُونُ عَادَةً مُلْتَصِقاً بِالْمِعْطَفِ خَلْفَ الْعُنُقِ. ""مِعْطَفٌ بِقِبِّيَّةٍ""."', '');
