INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13312, 'فِيلٌ', 'فيل', 'جامد', 'فيل', 'فيل', 'فل', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"أَفْيَالٌ:فِيلَةٌ"', '', 'R', '', '', '', '', '', '', '"(حو). 1. : حَيَوَانٌ مِنْ فَصِيلَةِ الْفِيلِيَّاتِ وَرُتْبَةِ الْخُرْطُومِيَّاتِ، ضَخْمُ الْجُثَّةِ، ثَخِينُ الْجِلْدِ، لَهُ خُرْطُومٌ طَوِيلٌ، يَرْفَعُ بِهِ الْعَلَفَ وَالْمَاءَ إِلَى فَمِهِ، وَنَابَانِ طَوِيلَتَان"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13313, 'أَفْيَالٌ', 'أفيال', 'جامد', '', 'ءفيال', 'فل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13314, 'فِيلَةٌ', 'فيلة', 'جامد', '', 'فيلة', 'فلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13315, 'قُبَّرَةٌ', 'قبرة', 'جامد', '', 'قبرة', 'قبرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: قُبَّرٌ. (حو). : عُصْفُورَةٌ مِنْ فَصِيلَةِ الْقُبَّرِيَّاتِ، مِنْ رُتْبَةِالْعُصْفُورِيَّاتِ، تَكْسُو رِيشَهَا سُمْرَةٌ، وَمِنْهَا نَوْعٌ يَتَمَيّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13316, 'قُبَّرِيَّاتٌ', 'قبريات', 'جامد', '', 'قبريات', 'قبرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"قُبَّرِيَّاتٌ-قُبَّرِيَّاتٌ (حو). : فَصِيلَةُ طَيْرٍ مِنَ الْجَوَاثِمِ، مَخْرُوطِيَّاتِ الْمَنَاقِيرِ، مِنْ أَنْوَاعِهَا القُبَّرُ وَالْمُكَاءُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13317, 'قَبَسٌ', 'قبس', 'جامد', 'قبس', 'قبس', 'قبس', '', '', '', 'مفرد', 'DnN', '', '', '"أَقْبَاسٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""قَبَسٌ مِنْ نَارٍ"" : شُعْلَةٌ مِنْ نَارٍ."', '');
