INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13319, 'مَقْبِسٌ', 'مقبس', 'جامد', 'قبس', 'مقبس', 'مقبس', '', '', '', 'مفرد', 'DnN', '', '', '"مَقَابِسُ"', '', 'R', '', '', '', '', '', '', '". ""رَمَى الْحَطَبَ فِي الْمَقْبِسِ"" : مَوْضِعُ إِشْعَالِ النَّارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13320, 'مَقَابِسُ', 'مقابس', 'جامد', '', 'مقابس', 'مقبس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13321, 'مِقْبَسٌ', 'مقبس', 'جامد', 'قبس', 'مقبس', 'مقبس', '', '', '', 'مفرد', 'DnN', '', '', '"مَقَابِسُ"', '', 'R', '', '', '', '', '', '', '". ""مِقْبَسُ النَّارِ"" : مَا تُؤْخَذُ بِهِ النَّارُ مِنْ عُودٍ وَنَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13322, 'مَقَابِسُ', 'مقابس', 'جامد', '', 'مقابس', 'مقبس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
