INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13324, 'قَبَاضٌ', 'قباض', 'جامد', 'قبض', 'قباض', 'قبض', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قَبَاضٌ-قَبَاضٌ، ةٌ [ق ب ض]. 1. : سُرْعَةٌ. 2. : اِنْكِمَاشٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13325, 'قُبْضَةٌ', 'قبضة', 'جامد', 'قبض', 'قبضة', 'قبضة', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُبْضَةٌ - [ق ب ض]. 1. : مَا قَبَضْتَ عَلَيْهِ مِنَ الشَّيْءِ بِكَفِّكَ. 2.""قُبْضَةُ عَجِينٍ"" : مِلْءُ الكَفِّ مِنْهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13326, 'مَقْبِضٌ', 'مقبض', 'جامد', 'قبض', 'مقبض', 'مقبض', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَقَابِضُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""مَقْبِضُ السَّيْفِ"" : مَا يُقْبَضُ عَلَيْهِ بِجُمْعِ الكَفِّ نِصابٌ. "" مَقْبِضُ السِّكِّينِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13327, 'مَقَابِضُ', 'مقابض', 'جامد', '', 'مقابض', 'مقبض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
