INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13336, 'قَبَاقِيبُ', 'قباقيب', 'جامد', '', 'قباقيب', 'قبقب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13337, 'قُبَالَةٌ', 'قبالة', 'جامد', 'قبل', 'قبالة', 'قبلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قُبَالَةٌ-قُبَالَةٌ [ق ب ل]. 1.""جَلَسَ قُبَالَتَهُ"" : تُجَاهَهُ. ""أَلْقَتْ نَفْسَهَا بِإِعْيَاءٍ عَلَى الْكُرْسِيِّ قُبَالَتَهُ"". (عبد الجبار السحيمي). 2.""قُبَالَةُ الطَّرِيقِ"" : أَوَّلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13338, 'قُبْلَةٌ', 'قبلة', 'جامد', 'قبل', 'قبلة', 'قبلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قُبْلَةٌ-قُبْلَةٌ [ق ب ل]. ""وَضَعَ قُبْلَةً عَلَى خَدِّهَا"" : اللَّثْمَةُ، أَيْ وَضْعُ الشِّفَاهِ عَلَى الْخَدِّ، بُوسَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13339, 'قِبْلَةٌ', 'قبلة', 'جامد', 'قبل', 'قبلة', 'قبلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قِبْلَةٌ-قِبْلَةٌ [ق ب ل]. 1.""تَوَجَّهَ إِلَى الْقِبْلَةِ لأَدَاءِ صَلاَتِهِ"" : الْجِهَةُ الَّتِي يُصَلِّي نَحْوَهَا... ""قِبْلَةُ الْمُصَلِّي"". 2.""مَا بِكَلاَمِهِ قِبْلَةٌ"" : جِهَةٌ. 3.""أَيْنَ قِبْلَتُكَ "" : أَيْنَ جِهَتُكَ . 4.""مَا يَعْرِفُ قِبْلَةً وَلاَ دِبْرَةً "" : إِذَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13340, 'قُبَلٌ', 'قبل', 'جامد', 'قبل', 'قبل', 'قبل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُبَلٌ-قُبَلٌ [ق ب ل]. ""رَأَيْتُهُ قُبَلاً"" : أَيْ عِيَاناً، مُقَابَلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13341, 'قُبُلٌ', 'قبل', 'جامد', 'قبل', 'قبل', 'قبل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُبُلٌ - [ق ب ل]. 1.""قُبُلُ الشَّيْءِ"" : مُقَدَّمُهُ.يوسف آية 26إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ    ( قرآن). 2.""قُبُلُ الْجَبَلِ"" : سَفْحُهُ. 3.""قُبُلُ الزَّمَانِ"" : أَوَّلُهُ. ""كَانَ ذَلِكَ فِي قُبُلِ الصَّيْفِ أَوْ فِي قُبُلِ الشِّتَاءِ"". 4.""قُبُلُ الْمَرْأَةِ أَوِ الرَّجُلِ"" : أَيْ نَقِيضُ الدُّبُرِ، العَوْرَةُ الأَمَامِيَّةُ. 5.""رَأَيْتُهُ قُبُلاً"" : عِيَاناً، مُقَابَلَةً"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13342, 'قُبْلٌ', 'قبل', 'جامد', 'قبل', 'قبل', 'قبل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُبْلٌ - [ق ب ل]. ""قَصَدَ قُبْلَهُ"" : قَصْدَهُ.   ""إِذاً أَقْبِلُ قُبْلَكَ"" : أَيْ أَقْصِدُ قَصْدَكَ وَأَتَوَجَّهُ نَحْوَكَ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13343, 'قِبَلٌ', 'قبل', 'جامد', 'قبل', 'قبل', 'قبل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قِبَلٌ - [ق ب ل]. 1.""سَلَّمَ لَهُ رِسَالَةً مِنْ قِبَلِ أَبِيهِ"" : مِنْ جِهَتِهِ، مِنْ عِنْدِهِ. 2.""لاَ قِبَلَ لَهُ بِهَذَا الْعَمَلِ"" : لاَ طَاقَةَ، لاَ قُدْرَةَ. 3.""لِي قِبَلَ جَارِي دَيْنٌ"" : عِنْدَهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13344, 'قَبِيلٌ', 'قبيل', 'جامد', 'قبل', 'قبيل', 'قبل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَبِيلٌ - [ق ب ل]. 1.""مِنْ قَبِيلِ الصُّدَفِ"" : مِنْ وَاقِعِ الصُّدَفِ. 2.""مِنْ هَذَا الْقَبِيلِ"" : مِنْ هَذَا النَّوْعِ، الصِّنْفِ.   ""هَذَا النَّوْعُ مِنْ هَذَا الْقَبِيلِ"". 3.""مِنْ قَبِيلِ الإِيضَاحِ"" : عَلَى سَبِيلِ... 4.""مَا يَعْرِفُ قَبِيلاً مِنْ دَبِيرٍ"" : لاَ يَفْقَهُ شَيْئاً، لاَ يُفَرِّقُ بَيْنَ الْأََشْيَاءِ. 5.""رَأَيْتُهُ قَبِيلاً"" : عِيَاناً، مُقَابَلَةً"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13345, 'مُقَبِّلٌ', 'مقبل', 'جامد', 'قبل', 'مقبل', 'مقبل', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""طَعَامٌ مُقَبِّلٌ"" : مُشَهٍّ، شَهِيٌّ. 2.""قَدَّمَ لِضَيْفِهِ مُقَبِّلاَتٍ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13346, 'مُقْتَبَلٌ', 'مقتبل', 'جامد', 'قبل', 'مقتبل', 'مقتبل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مُقْتَبَلٌ-مُقْتَبَلٌ [ق ب ل]. 1. ""شَابٌّ فِي مُقْتَبَلِ العُمْرِ"" : لاَ يَزَالُ شَابّاً يَافِعاً. 2. ""وَصَلَ فِي مُقْتَبَلِ النَّهَارِ "" : فِي بِدَايَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13347, 'قِبَانَةٌ', 'قبانة', 'جامد', 'قبن', 'قبانة', 'قبنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قِبَانَةٌ-قِبَانَةٌ [ق ب ن]. : حِرْفَةُ الْقَبَّانِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13348, 'قَبَّانٌ', 'قبان', 'جامد', 'قبن', 'قبان', 'قبن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَبَّانٌ-قَبَّانٌ [ق ب ن]. : آلَةٌ تُوزَنُ بِهَا الْأَشْيَاءُ الثَّقِيلَةُ، وَهِيَ أَنْوَاعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13349, 'مَقْبَرَةٌ', 'مقبرة', 'جامد', 'قبر', 'مقبرة', 'مقبرة', '', '', '', 'مفرد', 'DnN', '', '', '"مَقَابِرُ"', '', 'R', '', '', '', '', '', '', '". ""يَسِيرُ مَوْكِبُ الجَنَازَةِ بِخَطَوَاتٍ خاشِعَةٍ إِلَى الْمَقْبَرَةِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13350, 'مَقَابِرُ', 'مقابر', 'جامد', '', 'مقابر', 'مقبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13351, 'قَبَاءٌ', 'قباء', 'جامد', 'قبو', 'قباء', 'قب', '', '', '', 'مفرد', 'Dz', '', '', '"أَقْبِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '". ""خَاطَ قَبَاءً"" : لِبَاسٌ يُلْبَسُ فَوْقَ القَمِيصِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13352, 'أَقْبِيَةٌ', 'أقبية', 'جامد', '', 'ءقبية', 'قبة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13353, 'قَبِيلَةٌ', 'قبيلة', 'جامد', '', 'قبيلة', 'قبلة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"قَبَائِلُ"', '', '', '', '', '', '', '', '', '"ج: قَبَائِلُ. ""هُوَ مِنْ قَبِيلَةِ كَذَا"" : كِيَانٌ لَهُ نِظَامُهُ الْخَاصُّ يَضُمُّ جمَاَعَةً مُنْحَدِرَةً مِنْ جَدٍّ وَاحِدٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13354, 'قَبَائِلُ', 'قبائل', 'جامد', '', 'قباءل', 'قبل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13355, 'قَتَادٌ', 'قتاد', 'جامد', '', 'قتاد', 'قتد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قَتَادٌ-قَتَادٌ (نب). : شَجَرٌ مِنْ فَصِيلَةِ الْقَرْنِيَّاتِ صَلْبٌ، لَهُ شَوْكٌ كَالإِبَرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13356, 'قُتَيْبَةٌ', 'قتيبة', 'جامد', 'قتب', 'قتيبة', 'قتبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(طخ). : مِعىً مَحْشُوَّةٌ بِالشَّحْمِ وَاللَّحْمِ الْمَفْرُومِ وَالأَفَاوِيهِ، عَلَى شَكْلِ أَصَابِعَ تُؤْكَلُ مَشْوِيَّةً أَوْ مَقْل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13357, 'قُتَارٌ', 'قتار', 'جامد', 'قتر', 'قتار', 'قتر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُتَارٌ - [ق ت ر]. ""اِنْتَشَرَ  القُتَارُ فِي فَضَاءِ الْمَطْبَخِ"" : الدُّخَانُ الْمُنْبَعِثُ مِنَ الطَّبِيخِ أَوِ الشِّوَاءِ، أَوِ العَظْمِ الْمَحْرُوقِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13358, 'قِتْلَةٌ', 'قتلة', 'جامد', 'قتل', 'قتلة', 'قتلة', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قِتْلَةٌ-قِتْلَةٌ [ق ت ل]. ""قَتَلَهُ شَرَّ قِتْلَةٍ"" : نَوْعُ الْقَتْلِ، أَيْ شَرَّ مَوْتَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13359, 'قِتْلٌ', 'قتل', 'جامد', 'قتل', 'قتل', 'قتل', '', '', '', 'مفرد', 'DnN', '', '', '"أَقْتَالٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هُوَ قِتْلُهُ"" : نَظِيرُهُ، مِثْلُهُ. ""هُمَا قِتْلاَن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13360, 'أَقْتَالٌ', 'أقتال', 'جامد', '', 'ءقتال', 'قتل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13361, 'قِثَّاءٌ', 'قثاء', 'جامد', 'قثأ', 'قثاء', 'قث', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'Rz', '', 'N', 'O', 'O', 'O', '', '"قِثَّاءٌ-قِثَّاءٌ، ةٌ [ق ث أ] (نب). : نَبَاتٌ مِنْ فَصِيلَةِ القَرْعِيَّاتِ شَبِيهٌ بِالْخِيَارِ، لَكِنَّهُ أَطْوَلُ مِنْهُ، يُعْرَفُ فِي "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13362, 'مَقْتَلٌ', 'مقتل', 'جامد', 'قتل', 'مقتل', 'مقتل', '', '', '', 'مفرد', 'DnN', '', '', '"مَقَاتِلُ"', '', 'R', '', '', '', '', '', '', '". 1. ""أَصَابَ مِنْهُ مَقْتَلاً"" : العُضْوُ الَّذِي إِذَا أَصِيبَ صَاحِبُهُ لاَ يَكَادُ يَسْلَم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13363, 'مَقَاتِلُ', 'مقاتل', 'جامد', '', 'مقاتل', 'مقتل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13364, 'قَتَامٌ', 'قتام', 'جامد', 'قتم', 'قتام', 'قتم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَتَامٌ-قَتَامٌ [ق ت م]. 1.""اِنْتَشَرَ الْقَتَامُ فِي سَاحَةِ الْمَعْرَكَةِ"": الْغُبَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13365, 'قَتَمَةٌ', 'قتمة', 'جامد', 'قتم', 'قتمة', 'قتمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قَتَمَةٌ - [ق ت م]. 1.""قَتَمَةُ اللَّيْلِ"" : عَتَمَتُهُ، ظُلْمَتُهُ. 2.""اِنْتَشَرَتْ قَتَمَةٌ فِي الْجَوِّ"" : قِطْعَةٌ مِنَ الْغُبَارِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13366, 'قُتْمَةٌ', 'قتمة', 'جامد', 'قتم', 'قتمة', 'قتمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قُتْمَةٌ-قُتْمَةٌ [ق ت م]. ""قُتْمَةُ الْجَوِّ"" : لَوْنُهُ فِيهِ غُبْرَةٌ وَحُمْرَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13367, 'قُحَافَةٌ', 'قحافة', 'جامد', 'قحف', 'قحافة', 'قحفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قُحَافَةٌ-قُحَافَةٌ [ق ح ف]. : كُلُّ مَا يُجْرَفُ مِنَ الإِنَاءِ وَغَيْرِهِ مِنْ ثَرِيدٍ وَنَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13368, 'قُحَافٌ', 'قحاف', 'جامد', 'قحف', 'قحاف', 'قحف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قُحَافٌ-قُحَافٌ [ق ح ف].""سَيْلٌ قُحَافٌ"" : جَرَّافٌ، يَجْرُفُ كُلَّ شَيْءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13369, 'قَحْفَاءُ', 'قحفاء', 'جامد', 'قحف', 'قحفاء', 'قحف', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"قَحْفَاءُ-قَحْفَاءُ [ق ح ف]. ""عَجَاج"', '');
