INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13373, 'قَدَحٌ', 'قدح', 'جامد', 'قدح', 'قدح', 'قدح', '', '', '', 'مفرد', 'DnN', '', '', '"أَقْدَاحٌ"', '', 'R', '', '', '', '', '', '', '". ""نَاوَلَهُ قَدَحاً مَمْلُوءاً مَاءً"" : إِنَاءٌ يُشْرَبُ بِهِ الْمَاءُ وَنَحْوُهُ. ""مَلأَ قَدَحَهُ وَجَعَلَ يُدِيرُ فِيهِ الْمِلْعَقَةَ""."', '');
