INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13383, 'قُدٌّ', 'قد', 'جامد', 'قدد', 'قد', 'قد', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قُدٌّ-قُدٌّ، ةٌ [ق د د] (حو). : جِنْسُ سَمَكٍ بَحْرِيٍّ، شَائِكُ الزَّعَانِفِ،"', '');
