INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13389, 'مِقْدَارٌ', 'مقدار', 'جامد', 'قدر', 'مقدار', 'مقدر', '', '', '', 'مفرد', 'DnN', '', '', '"مَقَادِيرُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1. ""مِقْدَارُ الشَّيْءِ"" : أَيْ مِثْلُهُ فِي العَدَدِ أَوِ الوَزْنِ أَوِ الكَيْلِ أَوِ المِسَاحَةِ.المعارج آية 4 وَتَعْرُجُ الْمَلاَئِكَةُ والرُّوحُ إِلَيْهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ (قرآن). 2. ""أَعْطَاهُ مِقْدَاراً مِنَ الدَّقِيقِ"" : كَمِّيَّةً. ""مِقْدَارُ النَّفَقَاتِ"', '');
