INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13391, 'مَقْدُرَةٌ', 'مقدرة', 'جامد', 'قدر', 'مقدرة', 'مقدرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". ""لَهُ مَقْدِرَةٌ عَلَى خَوْضِ الْمَعَارِكِ"" : لَهُ القُوَّةُ، القُدْرَةُ، الاسْتِطَاعَةُ. ""العَفْوُ عِنْدَ الْمَقْدِرَةِ"" ""خَيْرُ العَفْوِ مَا كَانَ عِنْدَ الْمَقْدِرَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13392, 'قِدْرٌ', 'قدر', 'جامد', '', 'قدر', 'قدر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"قُدُورٌ"', '', 'Rp', '', '', '', '', '', '', '"ج: قُدُورٌ. ""وَضَعَتِ القِدْرَ عَلَى النَّ"', ':لا جذر:لا مفرد');
