INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13394, 'قُدَّاسٌ', 'قداس', 'جامد', 'قدس', 'قداس', 'قدس', '', '', '', 'مفرد', 'DnN', '', '', '"قَدَادِيسُ"', '', 'R', '', '', '', '', '', '', '". : صَلاَةٌ عِنْدَ الْمَسِيحِيِّينَ عَلَى الْخُبْزِ وَالْخَمْرِ، يُرْمَزُ بِهِمَا عَلَى الْهَيْكَلِ إِلَى جَسَدِ الْمَسِيحِ وَدَمِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13395, 'قَدَادِيسُ', 'قداديس', 'جامد', '', 'قداديس', 'قددس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13396, 'قُدُسٌ', 'قدس', 'جامد', 'قدس', 'قدس', 'قدس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُدُسٌ-قُدُسٌ [ق د س]. 1.""رُوحُ القُدُسِ، الرُّوحُ القُدُسُ"" : عِنْدَ الْمَسِيحِيِّيَن، الأُقْنُومُ الثَّالِثُ مِنَ الأَقَانِيمِ الإِلَه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13397, 'قُدْسٌ', 'قدس', 'جامد', 'قدس', 'قدس', 'قدس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"قُدْسٌ-( قرآن). قُدْسٌ [ق د س]. 1.""يَعِيشُ فِي قُدْسٍ"" : فيِ طُهْرٍ وَبَرَكَةٍ، فِي قَدَاسَةٍ. 2.""قُدْسُ الأَبِ"" : لَقَبُ رَجُلِ الدِّينِ عِنْدَ الْمَسِيحِيِّينَ بِمَعْنَى حَضْرَةِ الأَبِ. 3.""قُدْسُ الأَقْدَاسِ"" : عِنْدَ اليَهُودِ هُوَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13398, 'قُدُّوسٌ', 'قدوس', 'جامد', 'قدس', 'قدوس', 'قدس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'N', '', '"قُدُّوسٌ-قُدُّوسٌ [ق د س]. 1.""هُوَ اللَّهُ الْحَيُّ القُدُّوسُ"" : مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى، أَيِ الْمُنَزَّهُ عَنْ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13399, 'مَقْدِسٌ', 'مقدس', 'جامد', 'قدس', 'مقدس', 'مقدس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَقْدِسٌ-مَقْدِسٌ [ق د س]. 1. ""فِي الْمَقْدِسِ"" : فِي الْمَكَانِ الْمُقَدَّسِ. 2. ""بَيْتُ الْمَقْدِسِ"" : حَرَمُ القُدْسِ الشَّرِيفِ، مَدِينَةُ القُدْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13400, 'قُدَّامٌ', 'قدام', 'جامد', 'قدم', 'قدام', 'قدم', '', '', '', 'مفرد', '', '', '', '"(مُؤَنَّثَةٌوَقَدْتُذَكَّرُ)"', '', 'R', '', '', '', '', '', '', '"قُدَّامٌ-قُدَّامٌ (مُؤَنَّثَةٌ وَقَدْ تُذَكَّرُ) [ق د م]. 1.""جَلَسَ قُدَّامِي"" : أَمَامِي، وَهُوَ ظَرْفُ مَكَانٍ. 2.""لَقِيتُهُ قُدَّامَ ذَاكَ"" : أَيْ قَبْلَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13401, 'قُدَامٌ', 'قدام', 'جامد', 'قدم', 'قدام', 'قدم', '', '', '', 'مفرد', 'DnN', '', '', '"قُدَامَى"', '', 'R', '', '', '', '', '', '', '". ""مِنْ قُدَامِ الْحَيِّ"" : أَيْ مِنْ سُكَّانِهِ الَّذِينَ سَكَنُوهُ مُنْذُ زَمَنٍ قَدِيمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13402, 'قُدَامَى', 'قدامى', 'جامد', '', 'قدامى', 'قدم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13403, 'قَدَمَةٌ', 'قدمة', 'جامد', 'قدم', 'قدمة', 'قدمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قَدَمَةٌ - [ق د م]. 1.""قَدَمَةُ الغَنَمِ"": هِيَ الَّتِي تَكُونُ فِي مُقَدِّمَةِ الغَنَمِفِي الرَّعْيِ. 2.""اِمْرَأَةٌ قَدَمَةٌ"" : الَّتِي لَهَا مَرْتَبَـةٌ فِـي الْخَيْرِ. 3. : مِقْيَاسٌ مِنَ الْمَعْدِنِ تُثَبَّتُ فِيهِ سِنَّانِ مُدَبَّبَتَانِ إِحْدَاهُمَا ثَابِتَةٌ وَالأُخْرَى مُتَحَرِّكَةٌ تُقَاسُ بِهِ الأَطْوَالُ الصَّغِيرَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13404, 'أقْدَمِيَّةٌ', 'أقدمية', 'جامد', 'قدم', 'ءقدمية', 'قدمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"أقْدَمِيَّةُ-أقْدَمِيَّةُ [ق د م]. 1.""أصْبَحَتْ لَهُ أقْدَمِيَّةٌ فِي وَظِيفَتِهِ"": قِدَمٌ، مَنِ اشْتَغَلَ عِدَّةَ سَنَوَاتٍ فِي عَمَلٍ دُونَ أنْ يُغَيِّرَهُ فَيَكونُ لَهُ بِذَلِكَ حَقُّ الأقْدَمِيَّةِ. 2. ""كَسَبَ حَقّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13405, 'مُقَدِّمَةٌ', 'مقدمة', 'جامد', 'قدم', 'مقدمة', 'مقدمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""مُقَدِّمَةُ الكِتَابِ"" : الصَّفَحَاتُ الأُولَى القَلِيلَةُ الَّتِي تَشْرَحُ مَضْمُونَ الكِتَابِ ومَوْضُوعَهُ. وَتُعَرِّفُ بِهِ. 2.""الْمُقَدِّمَةُ الْمُوسِيقِيَّةُ"" : نَغَم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13406, 'مَقْدِمٌ', 'مقدم', 'جامد', 'قدم', 'مقدم', 'مقدم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَقْدِمٌ-مَقْدِمٌ [ق د م]. ""مَقْدِمُ العَيْنِ"" : الْجَانِبُ الدَّاخِلِيُّ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13407, 'قَدَمٌ', 'قدم', 'جامد', '', 'قدم', 'قدم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَقْدَامٌ(مُؤَنَّثَةٌوَقَدْتُ', '', 'R', '', '', '', '', '', '', '"ج: أَقْدَامٌ. (مُؤَنَّثَةٌ وَقَدْ تُذَكَّرُ). 1.""وَقَفَ عَلَى قَدَمٍ وَاحِدَةٍ"" :العُضْوُ الأَسْفَـلُ مِـنَ الْجِسْمِ مَا بَيْنَ طَرَفِ إِبْهَامِ الرِّجْلِ وَطَرَفِ الكَعْبِ. ""بَدَأَ الطِّفْلُ يَمْشِي عَلَى قَدَمَيْهِ"". 2.""م"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13408, 'أَقْدَامٌ', 'أقدام', 'جامد', '', 'ءقدام', 'قدم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13409, 'قُدْوَةٌ', 'قدوة', 'جامد', 'قدو', 'قدوة', 'قدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""كَانَ قُدْوَةً لِلْآخَرِينَ"" : مِثَالاً، كُلَّ مَا يُقْتَدَى وَيُتَّخَذُ مِثَالاً. ""القُدْوَةُ الْحَسَنَةُ"" ""القُدْوَةُ السَّيِّئَةُ"". 2.""لِي بِكَ قُدْوَةٌ"" : أُسْوَةٌ، مِثَالٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13410, 'قَدْوَى', 'قدوى', 'جامد', 'قدو', 'قدوى', 'قد', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَدْوَى-قَدْوَى [ق د و]. ""عُرِفَ بِالقَدْوَى "" : بِالاسْتِقَامَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13411, 'قَدُومٌ', 'قدوم', 'جامد', '', 'قدوم', 'قدم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"قَدَائِمُ(مؤ)"', '', 'R', '', '', '', '', '', '', '"ج: قَدَائِمُ. (مؤ). : آلَةٌ لِلنَّحْتِ وَالنَّجْرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13412, 'قَدَائِمُ', 'قدائم', 'جامد', '', 'قداءم', 'قدم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13413, 'قُذَاذَةٌ', 'قذاذة', 'جامد', 'قذذ', 'قذاذة', 'قذذة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', 'N', 'O', 'O', 'O', '', '".القُذَاذَةُ :- من كل شيءٍ : ما قذّ منه وسقط، أي ما قطع من أطرافه؛ قذاذة الشَّعر، قذاذة الذهب أو الفضة حين تُبْرَد ج قُذاذاتٌ.', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13414, 'قُذَّةٌ', 'قذة', 'جامد', 'قذذ', 'قذة', 'قذة', '', '', '', 'مفرد', 'DnN', '', '', '"قُذَذٌ:قِذَاذٌ"', '', 'R', '', '', '', '', '', '', '". 1. : رِيشَةُ السَّهْمِ، وَغَالِباً مَا تُؤْخَذُ مِنَ النَّسْرِ وَالصَّقْرِ بَعْدَ نَحْتِهَا وَإِعْدَادِهَا لِتُرَكَّبَ فِي السَّهْمِ. 2. : أُذُنُ الإِنْسَانِ وَالفَرَسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13415, 'قُذَذٌ', 'قذذ', 'جامد', '', 'قذذ', 'قذ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13416, 'قِذَاذٌ', 'قذاذ', 'جامد', '', 'قذاذ', 'قذذ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13417, 'قَاذُورَاتٌ', 'قاذورات', 'جامد', 'قذر', 'قاذورات', 'قذرت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"قَاذُورَاتٌ-قَاذُورَاتٌ [ق ذ ر]. ""اِمْتَلأَتِ الشَّوَارِعُ بِالْقَاذُورَاتِ"" : بِالْأَوْسَاخِ وَكُلِّ مَا هُوَ نَتِنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13418, 'قَاذُورٌ', 'قاذور', 'جامد', 'قذر', 'قاذور', 'قذر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَاذُورٌ-قَاذُورٌ، ةٌ [ق ذ ر]. 1.""رَجُلٌ قَاذُورٌ"" : الرَّجُلُ السَّيِّءُ الَّذِي يَتَقَذَّرُ النَّاسَ وَلاَ يُخَالِطُهُمْ وَلاَ يُعَاشِرُهُمْ. 2.""أَتَى بِالْقَاذُورَةِ"" : بِالْفَاحِشَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13419, 'قُحُولَةٌ', 'قحولة', 'جامد', 'قحل', 'قحولة', 'قحلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قُحُولَةٌ-قُحُولَةٌ [ق ح ل]. ""سَادَتِ الْقُحُو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13420, 'قِذَافٌ', 'قذاف', 'جامد', 'قذف', 'قذاف', 'قذف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قِذَافٌ-قِذَافٌ [ق ذ ف]. 1. : كُلُّ مَا يُرْمَى بِهِ بَعِيداً. 2.""رَأَيْتُهُ يَسِيرُ قِذَافاً"" : أَيْ سَيْراً سَرِيعاً. 3.""نَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13421, 'قَذَفٌ', 'قذف', 'جامد', 'قذف', 'قذف', 'قذف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَذْفٌ-قَذْفٌ [ق ذ ف] (مص. قَذَفَ). 1.""قَذْفُ الكُرَةِ"" : رَمْيُهَا. ""القَذْفُ بِالْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13422, 'قَذِيفَةٌ', 'قذيفة', 'جامد', 'قذف', 'قذيفة', 'قذفة', '', '', '', 'مفرد', 'DnN', '', '', '"قَذَائِفُ(عسك)"', '', '', '', '', '', '', '', '', '". 1.""رَمَاهُ بِقَذِيفَةٍ"" : قُنْبُلَة يَدَوِيَّة تُلْقَى بِاليَدِ فَتَنْفَجِرُ. 2."" نَظَّمُوا هُجُوماً بِالقَذَائِفِ"" : مَوَادّ مُتَفَجِّرَة مُحْر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13423, 'قَذَائِفُ', 'قذائف', 'جامد', '', 'قذاءف', 'قذف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13424, 'مِقْذَافٌ', 'مقذاف', 'جامد', 'قذف', 'مقذاف', 'مقذف', '', '', '', 'مفرد', 'DnN', '', '', '"مَقَاذِيفُ"', '', 'R', '', '', '', '', '', '', '". ""مِقْذَافُ الْمَرْكَبِ"": مِجْدافٌ، الخَشَبَةُ الَّتِي تُضْرَبُ فِي الْمَاءِ فَتَدْفَعُ الْمَرْكَبَ إِلَى الأَمَامِ."', '');
