INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13426, 'قَذَالٌ', 'قذال', 'جامد', 'قذل', 'قذال', 'قذل', '', '', '', 'مفرد', 'DnN', '', '', '"قُذُلٌ:أَقْذِلَةٌ"', '', 'R', '', '', '', '', '', '', '". ""قَذَالُ الإِنْسَانِ"" : مَا بَيْنَ الأُذُنَيْنِ مِنْ مُؤَخِّرَةِ الرَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13427, 'قُذُلٌ', 'قذل', 'جامد', '', 'قذل', 'قذل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13428, 'أَقْذِلَةٌ', 'أقذلة', 'جامد', '', 'ءقذلة', 'قذلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13429, 'قَذَاةٌ', 'قذاة', 'جامد', 'قذي', 'قذاة', 'قذة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"قَذَاةٌ-قَذَاةٌ [ق ذ ي]. ن. قَذَى.قَذىً - ج: قُذِيٌّ، أَقْذَاءٌ. [ق ذ ي]. (مص. قَذِيَ). 1.""قَذَى العَيْنِ"" : مَا يَقَعُ فِي العَيْنِ مِنْ وَسَخٍ أَبْيَضَ يَتَجَمَّعُ فِي مُؤْقِ العَيْنِ. 2.""غَمَضَ جُفُونَهُ عَلَى القَذَى"" : صَبَرَ عَلَى الظُّلْمِ وَالضَّيْمِ. 3.""قَذَى الشَّرَابِ"" : مَا يَقَعُ فِيهِ مِنْ تِبْنٍ وَحَصىً وَتُرَابٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13430, 'مِقْرَأٌ', 'مقرأ', 'جامد', 'قرأ', 'مقرء', 'مقر', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"مِقْرَأٌ-مِقْرَأٌ [ق ر أ]. 1. ""وَضَعَ الكِتَابَ عَلَى المِقْرَإِ"" : مَا يُجْعَلُ عَلَيْهِ الكِتَابُ عِنْدَ القِرَاءةِ. 2.""مِقْرَأُ الْمُوسِيقَى"" : مَا يُجْعَلُ عَلَيْهِ دَفْتَرُ الْمُوسِيقَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13431, 'قُرَادٌ', 'قراد', 'جامد', '', 'قراد', 'قرد', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"قِرْدَانٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: قِرْدَانٌ. (حو). : دُوَيِبَّةٌ مُتَطَفِّلَةٌ ذَاتُ أَرْجُلٍ كَثِيرَةٍ تَتَعَلَّقُ بِالدَّوابِّ والطُّيورِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13432, 'قِرْدَانٌ', 'قردان', 'جامد', '', 'قردان', 'قردن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13433, 'قَرَاصِيَا', 'قراصيا', 'جامد', '', 'قراصيا', 'قرص', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '"قَرَاصِيَا-قَرَاصِيَا (نب). : شَجَرٌ مُثْمِرٌ مِنْ فَصِيلَةِ الوَرْدِيَّاتِ، يُعْرَفُ في شَمَالِ الشَّامِ بِالْخَوْخِ الْمُجَفَّفِ، وَبِمِصْرَ بِالبَرْقُوقِ الْمُجَفَّفِ، وَهُوَ بَنَفْسَجِيُّ اللَّوْنِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13434, 'قُرَّاصِيَّاتٌ', 'قراصيات', 'جامد', '', 'قراصيات', 'قرصت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ، لاَ قُعَالاَت لَهَا، مُتَعَدِّدَةُ الأَجْنَاسِ وَالأَنْوَاعِ، مِنْهَا مَا هُوَ عُشْبِيٌّ وَمَا هُوَ شَجَرِيٌّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13435, 'قَرَامِطَةٌ', 'قرامطة', 'جامد', '', 'قرامطة', 'قرمطة', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": فِرْقَةٌ مِنَ الفِرَقِ السِّيَاسِيَّةِ الدِّينِيَّةِ الَّتِي ظَهَرَتْ فِي القَرْنِ الثَّالِثِ، تُنْسَبُ إِلَى حَمْدَانَ قَرْمَط.كَانَ لِأَتْبَاعِهَا نُفُوذٌ فِي البَحْرَيْنِ وَاليَمَنِ، وَالْجَزِيرَةِ العَرَبِيَّةِ. وَكَانَتْ تَدْعُو إِلَى الْمُسَاوَاةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13436, 'قُرَابٌ', 'قراب', 'جامد', 'قرب', 'قراب', 'قرب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُرَابٌ-قُرَابٌ [ق ر ب]. 1.""مَا هُوَ بِعَالِمٍ وَلاَ قُرَابِ عَالِمٍ"" : وَلاَ قَرِيبٌ مِنْ عَالِمٍ. 2.""مَعَهُ أَلْفُ دِرْهَمٍ أَوْ قُرَابُهُ"" : أَيْ ما يُقَارِبُ ذَلِكَ. 3.""أَتَيْتُهُ قُرَابَ العَشِيِّ"" : أَيْ فِي وَقْتٍ قَرِيبٍ مِنَ العَشِيِّ. ""قُرَابُ اللَّيْلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13437, 'قِرَابٌ', 'قراب', 'جامد', 'قرب', 'قراب', 'قرب', '', '', '', 'مفرد', 'DnN', '', '', '"قُرُبٌ:أَقْرِبَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""قِرَابُ السَّيْفِ"": غِمْدُهُ. 2.""قِرَابُ الْمُسَافِرِ"" : وِعَاءٌ مِنْ جِلْدٍ وَنَحْوِهِ يَضَعُ فِيهِ الْمُسَافِرُ زَادَهُ وَأَغْرَاضَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13438, 'قُرُبٌ', 'قرب', 'جامد', '', 'قرب', 'قرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13439, 'أَقْرِبَةٌ', 'أقربة', 'جامد', '', 'ءقربة', 'قربة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13440, 'قِرْبَةٌ', 'قربة', 'جامد', 'قرب', 'قربة', 'قربة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":قِرَبٌ"', '', 'R', '', '', '', '', '', '', '". ""قِرْبَةُ الْمَاءِ"" : وِعَاءٌ مِنْ جِلْدٍ يُوضَعُ فِيهِ الْمَاءُ وَنَحْوُهُ. ""فِي القِرْبَةِ لَبَنٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13441, 'قِرَبٌ', 'قرب', 'جامد', '', 'قرب', 'قرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13442, 'قُرْحَةٌ', 'قرحة', 'جامد', 'قرح', 'قرحة', 'قرحة', '', '', '', 'مفرد', 'DnN', '', '', '"قُرُوحٌ"', '', 'R', '', '', '', '', '', '', '". 1.""ما تَزَالُ قُرْحَتُهُ تُؤْلِمُهُ"": الْجُرْحُ الْمُتَقَادِمُ الَّذِي فَسَدَ وَاجْتَمَعَ فِيهِ القَيْحُ. 2.""قُرْحَةُ الْمَعِدَةِ"" : دَاءٌ نَاتِجٌ عَنْ بَثْرَةٍ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13443, 'قُرُوحٌ', 'قروح', 'جامد', '', 'قروح', 'قرح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13444, 'قَرِيحَةٌ', 'قريحة', 'جامد', 'قرح', 'قريحة', 'قرحة', '', '', '', 'مفرد', 'DnN', '', '', '"قَرَائِحُ"', '', '', '', '', '', '', '', '', '". ""قَرِيحَةُ الشَّاعِرِ أَوِ الْكَاتِبِ"": مَلَكَتُهُ أَوْ طَيْفُهُ، أَيْ مَا يُمَكِّنُهُ مِنْ إِج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13445, 'قَرَائِحُ', 'قرائح', 'جامد', '', 'قراءح', 'قرح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13446, 'قَارَّةٌ', 'قارة', 'جامد', 'قرر', 'قارة', 'قرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'Rp', '', '', '', '', '', '', '". 1. (جغ) : كُلُّ قِطْعَةٍ عَظِيمَةٍ مِنَ الْيَابِسَةِ. 2.""قَارَّاتُ الأَرْضِ خَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13447, 'قَارُورَةٌ', 'قارورة', 'جامد', 'قرر', 'قارورة', 'قررة', '', '', '', 'مفرد', 'DnN', '', '', '"قَوَارِيرُ"', '', 'R', '', '', '', '', '', '', '". ""قَارُورَةُ عَصِيرٍ"" : إِنَاءٌ مِنْزُجَاجٍ طَوِيلٌ، لَهُ عُنُقٌ، يُسَدُّ بِسَدَّادَةٍ، تُوضَعُ فِيهِ السَّوَائِلُ."', '');
