INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13449, 'قَرَارَةٌ', 'قرارة', 'جامد', 'قرر', 'قرارة', 'قررة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قَرَارَةٌ-قَرَارَةٌ [ق ر ر]. 1.""قَرَارَةُ النَّفْسِ"" : دَخِيلَتُهَا. 2.""قَرَارَةُ البَحْرِ"" : عُمْقُهُ، غَوْرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13450, 'مَقَرٌّ', 'مقر', 'جامد', 'قرر', 'مقر', 'مقر', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""مَقَرُّ العَمَلِ"" : مَكَانُهُ. 2.""عَادَ إِلَى مَقَرِّهِ"" : إِلَى مَحَلِّهِ الَّذِي كَانَ جِالِساً فِيهِ. 3.""مَقَرُّ الْمُؤَسَّسَةِ"" : مَكَا"', '');
