INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13458, 'قُرَصٌ', 'قرص', 'جامد', '', 'قرص', 'قرص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13459, 'قُرْصٌ', 'قرص', 'جامد', 'قرص', 'قرص', 'قرص', '', '', '', 'مفرد', 'DnN', '', '', '"أَقْرَاصٌ"', '', 'R', '', '', '', '', '', '', '". 1.""قُرْصُ الْخُبْزِ"" : قِطْعَةٌ مِنْهُ مُسْتَدِيرَةٌ مَبْسُوطَةٌ. 2.""قُرْصُ الشَّمْسِ"" : عَيْنُهَا. ""غَابَ قُرْصُ الشَّمْسِ"". 3.""رَمَى بِالقُرْصِ بَعِيداً"" : قِطْعَةٌ مُسْتَدِيرَةٌ مِنْ حَدِيدٍ يَقْذِفُهَا الرِّيَاضِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13460, 'أَقْرَاصٌ', 'أقراص', 'جامد', '', 'ءقراص', 'قرص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13461, 'قُرْصَانٌ', 'قرصان', 'جامد', '', 'قرصان', 'قرصن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"قَرَاصِنَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: قَرَاصِنَةٌ. ""اِعْتَرَضَ القَرَاصِنَةُ السَّفِينَةَ فِي عُرْضِ البَحْرِ"" : لُصُوصُ البَحْرِ الَّذِينَ يَعْتَرِضُونَ السُّفُنَ وَيَسْتَوْلُونَ عَلَيْهَا."', ':لا جذر:لا مفرد');
