INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13463, 'قُرْبَةٌ', 'قربة', 'جامد', '', 'قربة', 'قربة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":قُرَبٌ"', '', 'R', '', '', '', '', '', '', '"ج: قُرَبٌ، قُرُبَاتٌ. 1.""بَيْنِي وَبَيْنَهُ قُرْبَةٌ"" : قَرَابَةٌ. 2.""قَدَّمَ قُرْبَةً"" : مَا يُتَقَرَّبُ بِهِ إِلَى اللَّهِ تَعَالَى مِنْ أَعْمَالِ البِرِّ وَالإِحْسَانِ وَالطَّاعَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13464, 'قُرَبٌ', 'قرب', 'جامد', '', 'قرب', 'قرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13465, 'قُرَاضَةٌ', 'قراضة', 'جامد', 'قرض', 'قراضة', 'قرضة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قُرَاضَةٌ - [ق ر ض]. ""قُرَاضَةُ الفِضَّةِ"" : مَا يَسْقُطُ بِالقَرْضِ. ""قُرَاضَةُ الذَّهَبِ"" ""قُرَاضَةُ الثَّوْبِ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13466, 'قَرِيضٌ', 'قريض', 'جامد', 'قرض', 'قريض', 'قرض', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَرِيضٌ-قَرِيضٌ [ق ر ض]. ""يَنْظِمُ الْقَرِيضَ"" : الشِّعْرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13467, 'قَوَارِضُ', 'قوارض', 'جامد', 'قرض', 'قوارض', 'قرض', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '"قَوَارِضُ - [ق ر ض]. ن. قَارِضٌ، قَوَاضِمُ. "', '');
