INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13470, 'قِيرَاطٌ', 'قيراط', 'جامد', 'قرط', 'قيراط', 'قرط', '', '', '', 'مفرد', 'DnN', '', '', '"قَرَارِيطُ"', '', 'R', '', '', '', '', '', '', '". : مِعْيَارٌ فِي الوَزْنِ فِي القِيَاسِ، اِخْتَلَفَتْ مَقَادِيرُهُ بِاخْتِلاَفِ الأَزْمِنَةِ وَالأَقْطَارِ، وَهُوَ يُقَدَّرُ حَالِياً ب"', '');
