INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13474, 'قَارِعَةٌ', 'قارعة', 'جامد', 'قرع', 'قارعة', 'قرعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"قَارِعَةٌ-قَارِعَةٌ [ق ر ع]. 1.""قَارِعَةُ الطَّرِيقِ"" : وَسَطُهُ، جَانِبُهُ، الْمَوْضِعُ الَّذِي يَقْرَعُهُ الْمَارُّونَ بِأَرْجُلِهِمْ. ""نَصَبُوا بِقَارِعَةِ الطَّرِيقِ خِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13475, 'قُرَاعٌ', 'قراع', 'جامد', 'قرع', 'قراع', 'قرع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُرَاعٌ-قُرَاعٌ [ق ر ع]. ""أُصِيبَ بِمَرَضِ القُرَاعِ"" : مَرَضٌ جِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13476, 'قِرَاعٌ', 'قراع', 'جامد', 'قرع', 'قراع', 'قرع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قِرَاعٌ-قِرَاعٌ [ق ر ع]. ""كَانَ بَيْنَهُمْ صِرَاعٌ وَقِرَاعٌ "" : صُدَاعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13477, 'قُرْعَةٌ', 'قرعة', 'جامد', 'قرع', 'قرعة', 'قرعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قُرْعَةٌ-قُرْعَةٌ [ق ر ع]. 1.""هَذِهِ قُرْعَتُهُ"" : هَذَا نَصِيبُهُ وَسَهْمُهُ. 2.""أَجْرَى القُرْعَةَ بَيْنَ الفِرَقِ"" : عَمَلِيَّةٌ تَقْتَضِي وَضْعَ اسْمِ كُلِّ فَرِيقٍ فِي وَرَقَةٍ مُنْعَزِلَةٍ وَطَيَّهَا ثُمَّ تُخْلَطُ مُجْمَلُ الأَوْرَاقِ لِيَتِمّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13478, 'مِقْرَعَةٌ', 'مقرعة', 'جامد', 'قرع', 'مقرعة', 'مقرعة', '', '', '', 'مفرد', 'DnN', '', '', '"مَقَارِعُ"', '', 'R', '', '', '', '', '', '', '". 1. ""مِقْرَعَةُ الجَلاَّدِ"" : السَّوْطُ الَّذِي يُقْرَعُ بِهِ. 2. ""مِقْرَعَةُ الطَّبْلِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13479, 'مَقَارِعُ', 'مقارع', 'جامد', '', 'مقارع', 'مقرع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13480, 'قَرَعٌ', 'قرع', 'جامد', '', 'قرع', 'قرع', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَرَعٌ-قَرَعٌ (طب). : مَرَضٌ جِلْدِيٌّ يُصِيبُ شَعْرَ الرَّأْسِ فَيُسْقِطُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13481, 'قَرْعٌ', 'قرع', 'جامد', '', 'قرع', 'قرع', '', '', '', 'جمع تكسير', 'DnN', '', '', '"قَرْعَةٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: قَرْعَةٌ. (نب). : نَبَاتٌ مِنْ فَصِيلَةِ القَرْعِيَّاتِ، ثِمَارُهُ كَبِيرَةُ الْحَجْمِ، مُسْتَطِيلَةٌ وَمُسْتَدِيرَةٌ، بُرْتُقَالِيّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13482, 'قَرْعَةٌ', 'قرعة', 'جامد', '', 'قرعة', 'قرعة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13483, 'قَرْعَةٌ', 'قرعة', 'جامد', '', 'قرعة', 'قرعة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. ""قَرْعَةٌ زُجَاجِيَّةٌ"" : قِنِّينَةٌ زُجَاجِيَّةٌ ذَاتُ عُنُقٍ ضَيِّقٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13484, 'قَرْعِيَّاتٌ', 'قرعيات', 'جامد', '', 'قرعيات', 'قرعت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"قَرْعِيَّاتٌ-قَرْعِيَّاتٌ (نب). : فَصِيلَةُ القَرْعِيَّةِ، وَهِيَ مِنْ ذَوَاتِ الفِلْقَتَيْنِ تَشْمُلُ القَرْعَ وَالْخِيَارَ وَالبَطِّيخَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13485, 'مَقْرِفٌ', 'مقرف', 'جامد', 'قرف', 'مقرف', 'مقرف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَقْرِفُ-مَقْرِفُ [ق ر ف]. : مَوْضِعُ القَشْرِ مِنَ الْمَقْشورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13486, 'قِرْدٌ', 'قرد', 'جامد', '', 'قرد', 'قرد', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"قُرُودٌ:قِرَدَةٌأُنْثَاهُقِرْ', '', 'R', '', '', '', '', '', '', '"ج: قُرُودٌ، قِرَدَةٌ. أُنْثَاهُ قِرْدَةٌ. (حو). : حَيَوَانٌ مِنْ فَصِيلَةِ اللَّبُونَاتِ، مُقَلِّدٌ لِحَرَكَاتِ الإِ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13487, 'قُرُودٌ', 'قرود', 'جامد', '', 'قرود', 'قرد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13488, 'قِرَدَةٌ', 'قردة', 'جامد', '', 'قردة', 'قردة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13489, 'قِرْفَةٌ', 'قرفة', 'جامد', '', 'قرفة', 'قرفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قِرْفَةٌ-قِرْفَةٌ (نب). : قِشْرَةُ لِحَاءٍ عَطِرَةٍ مِنْ فَصِيلَةِ الغَارِيَّاتِ، لَوْنُهَا أَحْمَرُ قَاتِمٌ، وَهِيَ مِنَ التَّوَابِلِ، تُؤْخَذُ مِنْ شَجَرَةِ القِرْفَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13490, 'قُرْفُصَاءُ', 'قرفصاء', 'جامد', 'قرفص', 'قرفصاء', 'قرفص', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rz', '', '', '', '', '', '', '"قُرْفُصَاءُ-قُرْفُصَاءُ [ق ر ف ص]. ""جَلَسَ القُرْفُصَاءَ"" : أَنْ يَجْلِسَ الْمَرْءُ على أَلْيتَيْهِ وَيُلْصِقَ فَخِذيْهِ بِبَطْنِهِ وَيَحْتَبِي بِيَدَيْهِ يَضَعُهُما عَلَى ساقَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13491, 'قَرْمَدٌ', 'قرمد', 'جامد', 'قرمد', 'قرمد', 'قرمد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَرْمَدٌ-قَرْمَدٌ [ق ر م د]. 1. : كُلُّ مَا طُلِيَ بِهِ للزِّينَةِ كَالزَّعْفَرَانِ وَالْجَصِّ. 2. : الآجُرُّ الَّذِي يُوضَعُ عَلَى "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13492, 'قِرْمِيدٌ', 'قرميد', 'جامد', 'قرمد', 'قرميد', 'قرمد', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"قَرَامِيدُ"', '', 'R', '', '', '', '', '', '', '". ""قِرْمِيدُ الدَّارِ"" :الآجُرُّ الَّذِي يُوضَعُ عَلَى حَافَّةِ سَطْحِ الدَّارِ أَوْ حَافَّةِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13493, 'قَرَامِيدُ', 'قراميد', 'جامد', '', 'قراميد', 'قرمد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13494, 'قُرْنَةٌ', 'قرنة', 'جامد', 'قرن', 'قرنة', 'قرنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":قُرَنٌ"', '', 'R', '', '', '', '', '', '', '". 1. : قَالَبٌ عَلَى شَكْلِ قَرْنٍ يُمْلأُ بِالثَّلِيجَةِ. 2. : النُّقْطَةُ الَّتِي يَتَلاَقَى عِنْدَهَا فَرْعا مُنْحَنٍ، وَلا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13495, 'قُرَنٌ', 'قرن', 'جامد', '', 'قرن', 'قرن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13496, 'قَرْنِيَّاتٌ', 'قرنيات', 'جامد', 'قرن', 'قرنيات', 'قرنت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '"قَرْنِيَّاتٌ-قَرْنِيَّاتٌ [ق ر ن]. : فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ، مِنْ أَشْهَرِ أَنْوَاعِهَا العَدَسُ وَالْحِمَّصُ وَالفُولُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13497, 'قَرْنِيَّةٌ', 'قرنية', 'جامد', 'قرن', 'قرنية', 'قرنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"قَرْنِيَّةٌ-قَرْنِيَّةٌ [ق ر ن] (تش). : الْجُزْءُ الأَمَامِيُّ الشَّفَّافُ مِنْ جِدَارِ مُقْلَةِ العَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13498, 'قَرَنْفُلٌ', 'قرنفل', 'جامد', '', 'قرنفل', 'قرنفل', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قَرَنْفُلٌ-قَرَنْفُلٌ، ةٌ (نب). 1. : شَجَرَةٌ مِنْ فَصِيلَةِ الآسِيَّاتِ، تُثْمِرُ زَهْراً، يُقْطَفُ قَبْلَ تَفَتُّحِهِ ثُمَّ يُجَفَّفُ، وَهُوَ مِنَ التَّوَابِلِ الْحَارَّةِ. 2. : نَبَاتٌ مِنْ فَصِيلَةِ القَرَنْفُلِيَّاتِ لَهُ زَهْرٌ جَمِيلٌ عَاطِرٌ، أَبْيَضُ أَوْ أُرْجُوَانِيٌّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13499, 'قَرَنْفُلِيَّاتٌ', 'قرنفليات', 'جامد', '', 'قرنفليات', 'قرنفلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ، أَنْوَاعُهَا عَدِيدَةٌ، مِنْهَا مَا هُوَ خَاصٌّ بِالطِّبِّ وَما هو خاصٌّ بِالتزْيِينِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13500, 'قَرْيَةٌ', 'قرية', 'جامد', 'قري', 'قرية', 'قرة', '', '', '', 'مفرد', 'DnN', '', '', '"قُرَى"', '', '', '', '', '', '', '', '', '". 1.""يَسْكُنُ الْقَرْيَةَ"" : عَدَدٌ قَلِيلٌ مِنَ الدُّورِ فِي بُقْعَةٍ مِنَ الأَرْضِ فِي السَّهْلِ أَوِ الْجَبَلِ. 2.""أُمُّ الْقُرَى"" : مَكَّةُ الْمُكَرَّمَةُ. 3.""القَرْيَتَانِ"" : مَكَّةُ وَالطَّائِفُ.الزخرف آية 31 وَقَالُوا لَوْلاَ نُزِّلَ هَذَا القُرْآنُ عَلَى رَجُلٍ مِنَ القَرْيَتَيْنِ عَظِيمٍ(قرآن) . 4.""قَرْيَةُ النَّمْلِ"" : مَأْوَاهَا ."', '');
