INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13502, 'مِقْرِنٌ', 'مقرن', 'جامد', 'قرن', 'مقرن', 'مقرن', '', '', '', 'مفرد', 'DnN', '', '', '"مقارِنُ"', '', 'R', '', '', '', '', '', '', '". : خَشَبَةٌ تُشَدُّ على رَأْسِ الثَّوْرَيْنِ عِنْدَ الحَرْثِ."', '');
