INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13507, 'قُزَحٌ', 'قزح', 'جامد', 'قزح', 'قزح', 'قزح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قُزَحٌ-قُزَحٌ [ق ز ح]. ""لاَحَ قَوْسُ قُزَحٍ فِي الأُفُقِ"" : قَوْسُ اللَّهِ، قَوْسٌ مِنَ الْغَمَامِ الْمُلَوَّنِ بِأَلْوَانٍ مِنْهَا الْبَنَفْسَجِيُّ وَالنِّيلِيُّ وَالأَزْرَقُ وَالأَخْضَرُ وَالأَصْفَرُ، وَالْبُرْتُقَالِيُّ وَالأَحْمَرُ، تَبْدُو مُقَوَّسَةً بِسَبَبِ انْكِسَارِ النُّورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13508, 'قُزَحِيَّةٌ', 'قزحية', 'جامد', 'قزح', 'قزحية', 'قزحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"قُزَحِيَّةٌ-قُزَحِيَّةٌ [ق ز ح] (تش). ""قُزَحِيَّةُ الْعَيْنِ"" : حِجَابٌ مُسْتَدِيرٌ مُلَوَّنٌ خَلْفَ الْقَرْنِيَّةِ، يَتَوَسَّطُهُ ثُقْبٌ يُسَمَّى إِنْسَانَ الْعَيْنِ أَوِ الْبُؤْبُؤَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13509, 'قَازُوزَةٌ', 'قازوزة', 'جامد', 'قزز', 'قازوزة', 'قززة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قَازُوزَةٌ-قَازُوزَةٌ [ق ز ز]. : قَارُورَةٌ صَغِيرَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13510, 'قِزَازَةٌ', 'قزازة', 'جامد', 'قزز', 'قزازة', 'قززة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قِزَازَةٌ-قِزَازَةٌ [ق ز ز]. ""قِزَازَةُ دُودَةِ الْقَزِّ"" : تَرْبِيَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13511, 'قِرْنٌ', 'قرن', 'جامد', '', 'قرن', 'قرن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَقْرَانٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَقْرَانٌ. ""هُوَ قِرْنُهُ"" : نَظِيرُهُ، مَثِيلُهُ، زَمِيلُهُ فِي السِّنِّ. ""خَرَجَ مَعَ أَقْرَانِهِ إِلَى النُّزْهَةِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13512, 'أَقْرَانٌ', 'أقران', 'جامد', '', 'ءقران', 'قرن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13513, 'قَسٌّ', 'قس', 'جامد', 'قسس', 'قس', 'قس', '', '', '', 'مفرد', 'DnN', '', '', '"قُسُوسٌ"', '', 'R', '', '', '', '', '', '', '". 1. : مَنْ كَانَ بَيْنَ الأُسْقُفِ وَالشَّمَّاسِ. 2. : الْكَاهِنُ."', '');
