INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13515, 'قِسْطٌ', 'قسط', 'جامد', 'قسط', 'قسط', 'قسط', '', '', '', 'مفرد', 'DnN', '', '', '"أَقْسَاطٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَخَذَ قِسْطَهُ مِنَ الطَّعَامِ"" : نَصِيبَهُ، حِصَّتَهُ. ""قَالَ مَا العَدْلُ فَقَالَ الْقِسْطُ الْقَائِمُ عَلَى التَّسَاوِي"". (التوحيدي) ""نَالَ قِسْطاً مِنَ الرَّاحَةِ"" ""دَفَعَ قِسْطَهُ"". 2.""صَرَفَ قِسْطاً مِنْ رَأْسِ مَالِهِ"" : جُزْءاً مِنْهُ. 3.""كَانَ عَلَى قِسْطٍ كَبِيرٍ مِنَ الْخُلُقِ"" : عَلَى جَانِبٍ كَبِيرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13516, 'أَقْسَاطٌ', 'أقساط', 'جامد', '', 'ءقساط', 'قسط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13517, 'قِسْطَاسٌ', 'قسطاس', 'جامد', 'قسطس', 'قسطاس', 'قسطس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قِسْطَاسٌ-قِسْطَاسٌ[ق س ط س]. ""وَزَنَ بِالقِسْطَاسِ"" : بِأَضْبَطِ مِيزَانٍ وَ أَقْوَمِهِ.الإسراء آية 35وَزِنُوا بِالقِسْطَاسِ الْمُسْتَقِيمِ ( قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13518, 'قَسْطَلٌ', 'قسطل', 'جامد', '', 'قسطل', 'قسطل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"قَسَاطِلُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: قَسَاطِلُ. 1.""تَعَالَى قَسْطَلُ الْمَعْرَكَةِ"" : الْغُبَارُ السَّاطِعُ فِي الْمَعَارِكِ الْحَرْبِيَّةِ. 2.""أُمُّ قَسْطَلٍ"" : الدَّاهِيَةُ، الْمَنِيَّةُ. فَإِنْ تَبْتَئِسْ بِالشَّنْفَرَى أُمُّ قَسْطَلٍ*لَمَا اغْتَبَطَتْ بِالشَّنْفَرَى قَبْلُ أَطْوَلُ (الشنفرى).3. : شَجَرٌ مِنْ فَصِيلَةِ الْبَلُّوطِيَّاتِ، كَسْتَنَاء. ن.كَسْتَنَاء."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13519, 'قَسَاطِلُ', 'قساطل', 'جامد', '', 'قساطل', 'قسطل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13520, 'قَسَمَةٌ', 'قسمة', 'جامد', 'قسم', 'قسمة', 'قسمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""عَبَّرَتْ قَسَمَاتُ وَجْهِهِ عَنِ الامْتِعَاضِ"" : خُطُوطُهُ، مَلاَمِحُهُ. 2.""قَسَمَةُ الْوَجْهِ"" : جَمَالُهُ، حُسْنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13521, 'قِسْمَةٌ', 'قسمة', 'جامد', 'قسم', 'قسمة', 'قسمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"قِسَمٌ"', '', 'R', '', '', '', '', '', '', '". 1.""نَالَ قِسْمَتَهُ"" : نَصِيبَهُ، حِصَّتَهُ. ""كُلُّ شَيْءٍ قِسْمَةٌ وَنَصِيبٌ"" ""أَخَذَ كُلُّ شَرِيكٍ قِسْمَتَهُ"" ""قِسْمَةُ الْمَالِ"" ""قِسْمَةُ الْمِيرَاثِ"". 2.""الْقِسْمَةُ فِي الْحِسَابِ"" : قِسْمَةُ عَدَدٍ عَلَى آخَرَ، تَجْزِئَةُ الأَوَّلِ أَجْزَاءً بِقَدْرِ الْعَدَدِ الثَّانِي. وَيُسَمَّى الأَوَّلُ: الْمَقْسُومَ، وَالآخَرُ: الْمَقْسُومَ عَلَيْهِ، وَالنَّاتِجُ: خَارِجَ الْقِسْمَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13522, 'قِسَمٌ', 'قسم', 'جامد', '', 'قسم', 'قسم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13523, 'قَسَمٌ', 'قسم', 'جامد', 'قسم', 'قسم', 'قسم', '', '', '', 'مفرد', 'DnN', '', '', '"أَقْسَامٌ"', '', 'R', '', '', '', '', '', '', '". ""أَدَّى الْقَسَمَ"" : الْيَمِينَ بِاللَّهِ."', '');
