INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13525, 'قِسْمٌ', 'قسم', 'جامد', 'قسم', 'قسم', 'قسم', '', '', '', 'مفرد', 'DnN', '', '', '"أَقْسَامٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَخَذَ قِسْمَهُ"" : نَصِيبَهُ، حِصَّتَهُ، حَظَّهُ. 2.""دَخَلَ الْقِسْمَ"" : حُجْرَةَ الدَّرْسِ. 3. : شُعْبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13526, 'أَقْسَامٌ', 'أقسام', 'جامد', '', 'ءقسام', 'قسم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13527, 'قَسِيمٌ', 'قسيم', 'جامد', 'قسم', 'قسيم', 'قسم', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"قَسَائِمُ"', '', 'R', '', '', '', '', '', '', '". 1.""كَانَ قَسِيمَهُ"" : مَنْ يُقَاسِمُ غَيْرَهُ شَيْئاً. 2.""قَسِيمُ الْجَنَاحِ"" : شَطْرُهُ. 3.""وَجْهٌ قَسِيمٌ"": جَمِيلٌ. 4.""قَسِيمَةُ بَيْعٍ"" : وَثِيقَةٌ لَهَا فِي التَّعَامُلِ أَكْثَرُ مِنْ نُسْخَةٍ. ""قَسِيمَةُ الزَّوَاجِ"". 5.""أَرْضٌ قَسِيمَةٌ"" : قِطْعَةٌ مَقْسُومَةٌ مَفْرُوزَةٌ مِنَ الأَرْضِ لِلْبِنَاءِ أَوِ الزَّرْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13528, 'قَسَائِمُ', 'قسائم', 'جامد', '', 'قساءم', 'قسم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13529, 'قُصَّةٌ', 'قصة', 'جامد', '', 'قصة', 'قصة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"قُصَصٌ:قِصَاصٌ"', '', '', '', '', '', '', '', '', '"ج: قُصَصٌ، قِصَاصٌ. 1.""قُصَّةُ شَعْرٍ"" : خُصْلَتُهُ. 2. : شَعْرُ مُقَدَّمِ الرَّأْسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13530, 'قُصَصٌ', 'قصص', 'جامد', '', 'قصص', 'قص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13531, 'قِصَاصٌ', 'قصاص', 'جامد', '', 'قصاص', 'قصص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13532, 'قَشَّابِيَّةٌ', 'قشابية', 'جامد', 'قشب', 'قشابية', 'قشبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". : لِبَاسٌ مَغْرِبِيٌّ عَلَى شَكْلِ جِلْبَابٍ إِلاَّ أَنَّهَا أَقْصَرُ مِنْهُ، تُنْسَجُ عَادَةً مِنَ الصُّوفِ، لَهَا غِطَاءُ لِلرَّأْسِ يُوضَعُ عِنْدَ الْحَاجَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13533, 'قَشَبٌ', 'قشب', 'جامد', 'قشب', 'قشب', 'قشب', '', '', '', 'مفرد', 'DnN', '', '', '"أَقْشَابٌ"', '', 'R', '', '', '', '', '', '', '". ""وَضَعَ لَهُ القَشَبَ فِي الطَّعَامِ"" : السُّمَّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13534, 'أَقْشَابٌ', 'أقشاب', 'جامد', '', 'ءقشاب', 'قشب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13535, 'قِشْدَةٌ', 'قشدة', 'جامد', 'قشد', 'قشدة', 'قشدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قِشْدَةٌ-قِشْدَةٌ [ق ش د]. : زُبْدَةٌ رَقِيقَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13536, 'قُشَارَةٌ', 'قشارة', 'جامد', 'قشر', 'قشارة', 'قشرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قُشَارَةٌ-قُشَارَةٌ [ق ش ر]. ""قُشَارَةُ الْخُضَرِ"" : مَا نُزِعَ عَنْهَا، أَيْ مَا يَتَسَاقَطُ مِنْهَا عِنْدَ القَشْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13537, 'قُشَارٌ', 'قشار', 'جامد', 'قشر', 'قشار', 'قشر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُشَارٌ-قُشَارٌ [ق ش ر].""قُشَارُ الْحَيَّةِ"" : سِلْخٌ، جِلْدُهَا إِذَا سَلَخَتْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13538, 'قِشْرَةٌ', 'قشرة', 'جامد', 'قشر', 'قشرة', 'قشرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"واحدةقِشْر"', '', 'R', '', '', '', '', '', '', '". 1.""قِشْرَةُ الْبَيْضَةِ"" : غِلاَفُهَا. 2.""قِشْرَةُ الْجِلْدِ"" : الثَّوْبُ الرَّقِيقُ الَّذِي يُغَطِّي الْجِلْدَ يَظْهَرُ عِنْدَ تَقَشُّرِهِ. 3.""قِشْرَةُ الأَرْضِ"" : الْيَابِسَةُ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13539, 'قِشْرٌ', 'قشر', 'جامد', 'قشر', 'قشر', 'قشر', '', '', '', 'مفرد', 'DnN', '', '', '"قُشُورٌ"', '', 'R', '', '', '', '', '', '', '". 1.""قِشْرُ الشَّيْءِ"" : غِلاَفُهُ، غِطَاؤُهُ، خِلْقَةً أَوْعَرَضاً. ""قِشْرُ الْبُرْتُقَالِ"" ""قِشْرُ الدُّمَّلِ"" ""قِشْرُ الشَّجَرَةِ"". 2.""لَمْ يَتْرُكْ لَهُ إِلاَّ الْقُشُورَ"" : الْفَضَلاَت. 3.""قُشُورُ الْكَلاَمِ"" : التَّافِهُ مِنْهُ. 4.""عَلَيْهِ قِشْرٌ حَسَنٌ"" : كُلُّ مَلْبُوسٍ يُغَطِّي الْجِسْمَ. 5. : جِنْسُ سَمَكٍ، قَيْضُها، نَهْرِيٌّ عَرِيضٌ، طُولُهُ شِبْرٌ، وَلَحْمُهُ لَذِيذٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13540, 'أَقْشَابٌ', 'أقشاب', 'جامد', '', 'ءقشاب', 'قشب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13541, 'قِشْرِيَّاتٌ', 'قشريات', 'جامد', 'قشر', 'قشريات', 'قشرت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"قِشْرِيَّاتٌ-قِشْرِيَّاتٌ [ق ش ر]. : فَصِيلَةٌ حَيَوَانِيَّةٌ مَفْصِلِيَّةٌ مَائِيَّةٌ، مِنْهَا السَّرَطَانُ، وَرُتَبُهَا عَدِيدَةٌ منْها مُزْدَوِجَاتُ الأَرْجُلِ وَالصَّدَفِيَّاتُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13542, 'قَشَّةٌ', 'قشة', 'جامد', 'قشش', 'قشة', 'قشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"واحدةالقَشِّ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""قَشَّةُ النَّبَاتِ"" : مَا صَغُرَ مِنَ النَّبَاتِ اليَابِسِ. 2.""قَشَّةُ ارْتِشَافِ العَصِيرِ"" : عُودٌ نَحِيفٌ مُجَوَّفٌ يُرْتَشَفُ بِهِ العَصِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13543, 'قَشّ', 'قش', 'جامد', '', 'قش', 'قش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13544, 'قَشِيشٌ', 'قشيش', 'جامد', 'قشش', 'قشيش', 'قشش', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قَشِيشٌ-قَشِيشٌ [ق ش ش]. ""قَشِيشُ الْحَيَّةِ"" : صَوْتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13545, 'قِشْلَةٌ', 'قشلة', 'جامد', '', 'قشلة', 'قشلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قِشْلَةٌ-قِشْلَةٌ (عسك). ""قِشْلَةُ الْعَسْكَرِ"" : مُعَسْكَرٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13546, 'قِصَابَةٌ', 'قصابة', 'جامد', 'قصب', 'قصابة', 'قصبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قِصَابَةٌ-قِصَابَةٌ [ق ص ب]. 1. : حِرْفَةُ الْقَصَّابِ. 2. : دُكَّانُ الْقَصَّابِ. 3. : الْخُصْلَةُ الْمُلْتَوِيَةُ مِنَ الشَّعْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13547, 'قَصَبَةٌ', 'قصبة', 'جامد', 'قصب', 'قصبة', 'قصبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"واحدةالْقَصَبِ"', '', 'R', '', '', '', '', '', '', '". 1.""قَصَبَةُ الشَّعْرِ"": الْخُصْلَةُ الْمُلْتَوِيَةُ مِنْهُ. 2.""قَصَـبَةُ الأَنْـفِ"" (تش) : عَظْمُـهُ. 3.""قَصَبَةُ الْمَريءِ"" (تش) : مَجْرَى الطَّعَامِ مِنَ الْحَلْقِ إِلَى الْمَعِدَةِ. 4.""قَصَبَةُ الرِّئَةِ"" (تش) : مَجْرَى"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13548, 'قَصَبٌ', 'قصب', 'جامد', '', 'قصب', 'قصب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَصَبٌ-قَصَبٌ (نب). 1. : نَبَاتٌ مِنْ فَصِيلَةِ النَّجْلِيَّاتِ، مَائِيٌّ، وَهُوَ مُجَوَّفٌ وَمِنْهُ أَنْوَاعٌ مُخْتَلِفَةٌ. 2.""قَصَبُ السُّكَّرِ"" : نَبَاتٌ زِرَاعِيٌّ مِنْ فَصِيلَةِ النَّجْلِيَّاتِ، يُسْتَخْرَجُ مِنْ أَلْيَافِ سُوقِهِ الْإِسْفَنْجِيَّةِ عُصَارَةٌ سُكَّرِيَّةٌ. ""الْقَصَبُ لاَ يَنْبُتُ إِلاَّ عَلَى شُطُوطِ الْأَنْهَارِ"". 3.""الْقَصَبُ الْهَوَائِيُّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13549, 'مَقْصِدٌ', 'مقصد', 'جامد', 'قصد', 'مقصد', 'مقصد', '', '', '', 'مفرد', 'DnN', '', '', '"مَقَاصِدُ"', '', 'R', '', '', '', '', '', '', '". 1. ""مَقْصِدُ الْمُسَافِرِينَ"": مَكَانُ تَوَجُّهِهِمْ، الوِجْهَةُ. ""مَقْصِدُ الْحُجَّاجِ"". 2. ""مَقَاصِدُ الشَّرِيعَةِ"" : مَرَامِيهَا، أَهْدَافُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13550, 'مَقَاصِدُ', 'مقاصد', 'جامد', '', 'مقاصد', 'مقصد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13551, 'قَصْدِيرٌ', 'قصدير', 'جامد', '', 'قصدير', 'قصدر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"1. : مَعْدِنٌ أَبْيَضُ خَفِيفٌ، تُصْنَعُ مِنْهُ صَفَائِحُ لِبِنَاءِ بُيُوتٍ مُؤَقَّتَةٍ. 2.""مُدُنُ الْقَصْدِيرِ"" :"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13552, 'قُصَارَةٌ', 'قصارة', 'جامد', 'قصر', 'قصارة', 'قصرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قُصَارَةٌ-قُصَارَةٌ [ق ص ر]. 1.""يَسْكُنُ مُطْمَئِنّاً فِي قُصَارَةٍ"" : فِي دَارٍ وَاسِعَةٍ مُحَصَّنَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13553, 'قُصَارٌ', 'قصار', 'جامد', 'قصر', 'قصار', 'قصر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُصَارٌ-قُصَارٌ [ق ص ر]. ""قُصَارُكَ أَنْ تَقُومَ بِهَذَا"" : قُصاراكَ، حَسْبُكَ وَغَايَتُكَ وَمَا اقْتَصَرْتَ عَلَيْهِ."', '');
