INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13582, 'قَضَّةٌ', 'قضة', 'جامد', 'قضض', 'قضة', 'قضة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"واحدةقِضَاض"', '', 'R', '', '', '', '', '', '', '"قَضَّةٌ - [ق ض  ض]. وَاحِدَةُ قِضَاض. 1.""قَضَّةُ الْحَصَى"": مَا تَفَتَّتَ مِنْهَا. 2. : كُبَّةٌ صَغِيَرةٌ مِنَ الغَزْلِ. 3.""أَرْضٌ قَضَّةٌ"" : كَثِيرَةُ الْحَصَى وَالتُّرَابِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13583, 'قِضَاض', 'قضاض', 'جامد', '', 'قضاض', 'قضض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13584, 'قِضَّةٌ', 'قضة', 'جامد', 'قضض', 'قضة', 'قضة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قِضَّةٌ-قِضَّةٌ [ق ض ض].1. : حِجَارَةٌ صَغِيرَةٌ. 2.""أَرْضٌ قِضَّةٌ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13585, 'قُضَاعٌ', 'قضاع', 'جامد', 'قضع', 'قضاع', 'قضع', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قُضَاعٌ-قُضَاعٌ، ةٌ [ق ض ع]. 1.""قُضَاعَةُ الدَّقِيقِ أَوْ قُضَاعُهُ"" : غُبَارُهُ. 2.""قُضَاعَةُ الْجِدَارِ"" : مَا يَتَحَتَّتُ مِنْ أَصْلِ الْجِدَارِ. 3.""أَلَمَّ بِهِ قُضَاعٌ "" : وَجَعٌ فِي البَطْنِ. 4. (حو) : حَيَوَانٌ مِنْ فَصِيلَةِ الس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13586, 'قَضَامِيٌّ', 'قضامي', 'جامد', 'قضم', 'قضامي', 'قضم', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"قَضَامِيٌّ-قَضَامِيٌّ [ق ض م]. : حِمَّصٌ، يُبَلُّ ثُمَّ يُحَمَّصُ عَلَى الْمِقْلاَةِ قَلِيلاً فَيُقْضَمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13587, 'قَاضِيَةٌ', 'قاضية', 'جامد', 'قضي', 'قاضية', 'قضة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"قَاضِيَةٌ-قَاضِيَةٌ [ق ض ي]. 1.""أَتَتْ عَلَيْهِ الْقَاضِيَةُ"" : الْمَنِيَّةُ. 2.""وَجَّهَ إِلَيهِ ضَرْبَةً قَاضِيَةً"" : ضَرْبَةً قَاتِلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13588, 'قَضِيَّةٌ', 'قضية', 'جامد', 'قضي', 'قضية', 'قضة', '', '', '', 'مفرد', 'DnN', '', '', '"قَضَايَا"', '', '', '', '', '', '', '', '', '". ""شَرَحَ قَضِيَّتَهُ"" : أَيْ مَسْأَلَتَهُ الَّتِي تَطْرَحُ جَوَانِبَ مِنْ حَالَةٍ تَحْتَاجُ إِلَى حَلٍّ أَوْ يُتَنَازَعُ فِيهَا. ""رَفَعَ الْقَضِيَّةَ إِلَى"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13589, 'قَضَايَا', 'قضايا', 'جامد', '', 'قضايا', 'قض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13590, 'قَطَائِفُ', 'قطائف', 'جامد', '', 'قطاءف', 'قطف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَطَائِفُ-قَطَائِفُ (طخ). : نَوْعٌ مِنْ أَنْوَاعِ الْحَلْوَى وَهِيَ رَقَائِقُ مِنْ عَجِينِ الدَّقِيقِ وَالزُّبْدَةِ تُحْشَى بِالسُّكَّرِ وَاللَّوْزِ وَتُقْلَى فيِ السَّمْنِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13591, 'قُطْبٌ', 'قطب', 'جامد', '', 'قطب', 'قطب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَقْطَابٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَقْطَابٌ. 1.""قُطْبُ الرَّحَى"" : الْعَصَا الْغَلِيظَةُ أَوِ الْحَدِيدَةُ الْمُلَصَّقَةُ بِالطَّبَقِ الأَسْفَلِ مِنَ الرَّحَى يَدُورُ عَلَيْهِ الطَّبَقُ الأَعْلَى. 2.""نَجْمَةُ الْقُطْبِ"" : نَجْمٌ لاَ يَبْرَحُ مَكَانَهُ بَيْنَ الْفَرْقَدَيْنِ وَالْجَدْيِ تُبْنَى عَلَيْهِ الْقِبْلَةُ وَيَدُورُ عَلَيْهِ الْفَلَكُ. 3.""قُطْبُ الأَرْضِ"" : طَرَفُ مِحْوَرِ الأَرْضِ وَهُمَا قُطْبَانِ: الْقُطْبُ الشَّمَالِيُّ وَالْقُطْبُ الْجَنُوبِيُّ. 4.""أَصْبَحَ قُطْباً فِي بِلا"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13592, 'أَقْطَابٌ', 'أقطاب', 'جامد', '', 'ءقطاب', 'قطب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13593, 'قَطَّارَةٌ', 'قطارة', 'جامد', 'قطر', 'قطارة', 'قطرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قَطَّارَةٌ-قَطَّارَةٌ [ق ط ر]. 1.""قَطَّارَةُ الزَّهْرِ"" : أَدَاةٌ يُقَطَّرُ بِهَا الزَّهْرُ. 2.""قَطَّارَةُ الْمُخْتَبَرِ"" : أَدَاةٌ يُقَطَّرُ بِهَا الدَّوَاءُ قَطْرَةً قَطْرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13594, 'قُطَارَةٌ', 'قطارة', 'جامد', 'قطر', 'قطارة', 'قطرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قُطَارَةٌ-قُطَارَةٌ [ق ط ر]. 1.""قُطَارَةُ شَيْءٍ سَائِلٍ"" : مَا سَالَ وَجَرَى مِنْهُ قَطْرَةً قَطْرَةً. 2.""قُطَارَةُ الْمَاءِ"" : القَلِيلُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13595, 'قِطَارٌ', 'قطار', 'جامد', 'قطر', 'قطار', 'قطر', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":قُطُرٌ"', '', 'R', '', '', '', '', '', '', '". 1.""قِطَارٌ مِنَ الإِبِلِ"" : قِطْعَةٌ مِنْهَا يَلِي بَعْضُهَا عَلَى نَسَقٍ وَاحِدٍ. 2.""اِنْطَلَقَ قِطَارُ السِّكَّةِ الْحَدِيدِيَّةِ"" : مَجْمُوعَةُ عَرَبَاتِ السِّكَّةِ الْحَدِيدِيَّةِ تَجُرُّهَا قَاطِرَةٌ. ""الْقِطَارُ السَّرِيعُ"". 3 .""فَاتَهُ الْقِطَارُ"" : فَاتَتْهُ الْفُرْصَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13596, 'قُطُرٌ', 'قطر', 'جامد', '', 'قطر', 'قطر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13597, 'قَطْرَانٌ', 'قطران', 'جامد', 'قطر', 'قطران', 'قطرن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَطْرَانٌ-قَطْرَانٌ، قِطْرَانٌ [ق ط ر]. 1. : إِفْرَازَاتُ شَجَرِ الصَّنَوْبَرِ وَالأَرْزِ وَنَحْوِهِمَا. 2.""قَطْرَانٌ"" : سَائِلٌ لَزِجٌ أَسْوَدُ يُسْتَخْرَجُ مِنَ الْخَشَبِ وَالْفَحْمِ الْحَجَرِيِّ بِالتَّقْطِيرِ. 3.""الْقَطْرَانُ الْمَعْدِنِيُّ"" : نَوْعٌ مِنَ الزِّفْتِ يُسْتَعْمَلُ لِتَعْبِيدِ الطُّرُقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13598, 'مَقْطُورَةٌ', 'مقطورة', 'جامد', 'قطر', 'مقطورة', 'مقطرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '". ""مَقْطُورَةُ القِطَارِ"" : عَرَبَةٌ تَجُرُّهَا قَاطِرَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13599, 'قَطَر', 'قطر', 'جامد', '', 'قطر', 'قطر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'O', '', '": مِنَ الْبُلْدَانِ الْعَرَبِيَّةِ (دَوْلَةُ قَطَر) بِالْخَلِيجِ الْعَرَبِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13600, 'قُطْرٌ', 'قطر', 'جامد', '', 'قطر', 'قطر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَقْطَارٌ"', '', 'Rp', '', '', '', '', '', '', '"ج: أَقْطَارٌ. 1.""تَجَوَّلَ فِي أَقْطَارِ الْبِلاَدِ"" : فِي جِهَاتِهَا نَوَاحِيهَا، فِي أَقَالِيمِهَا. ""أَقْطَارُ الدُّنْيَا"". 2.""الْأَقْطَارُ الْعَرَبِيَّةُ"" : أَيِ الْبُلْدَانُ الْعَرَبِيَّةُ مِنْ جِهَةِ إِنَّ كُلَّ بَلَدٍ قُطْرٌ يُشَكِّلُ إِقْلِيماً أَوْ جِهَةً. 3.""قُطْرُ الدَّائِرَةِ"" (هن) : خَطٌّ مُسْتَقِيمٌ يَمُرُّ بِمَرْكَزِ الدَّائِرَةِ وَيَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13601, 'أَقْطَارٌ', 'أقطار', 'جامد', '', 'ءقطار', 'قطر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13602, 'إقْطَاعَةٌ', 'إقطاعة', 'جامد', 'قطع', 'ءقطاعة', 'إقطعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"أت"', '', 'Rp', '', '', '', '', '', '', '".: قِطْعَةٌ مِنَ الأرْضِ فِي مِلْكِ الإقْطَاعِيِّ يَتَحَكَّمُ فِيهَا، أَوْ ما كانَ يُقْطَعُ للْجُنْدِ مِنَ الأَراضِي فَتُجْعَلُ لَهُمْ غَلَّتُهَا رِزْقاً. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13603, 'تَقاطِيعُ', 'تقاطيع', 'جامد', 'قطع', 'تقاطيع', 'تقطع', '', '', '', 'مفرد', '', '', '', '"مفردتَقْطيعٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ن. تَقْطِيعٌ."', '');
