INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13605, 'قُطَاعَةٌ', 'قطاعة', 'جامد', 'قطع', 'قطاعة', 'قطعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قُطَاعَةٌ-قُطَاعَةٌ [ق ط ع]. 1. : مَا قُطِعَ مِنَ الشَّيْءِ. 2. : مَا سَقَطَ مِنَ الْقَطْعِ."', '');
