INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13638, 'قُعَادٌ', 'قعاد', 'جامد', 'قعد', 'قعاد', 'قعد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُعَادٌ-قُعَادٌ [ق ع د]. ""أُصِيبَ بِالقُعَادِ"" : دَاءٌ يُصِيبُ الإِنْسَانَ يُقْعِدُهُ عَنِ العَمَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13639, 'قُعْدَةٌ', 'قعدة', 'جامد', 'قعد', 'قعدة', 'قعدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قُعْدَةٌ-قُعْدَةٌ [ق ع د]. 1. : مَا يُقْعَدُ عَلَيْهِ مِنْ سَرْجٍ أَورَحْلٍ وَنَحْوِهِ. 2. : مَا يَتَّخِذُهُ الرَّاعِي لِلرُّكُوبِ وَحَمْلِ الزَّادِ وَالْمَتَاعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13640, 'مَقْعَدَةٌ', 'مقعدة', 'جامد', 'قعد', 'مقعدة', 'مقعدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَقْعَدَةٌ-مَقْعَدَةٌ [ق ع د]. 1. ""مَكَانُ القُعُودِ"" : الجُلُوسِ. 2.:السَّافِلَةُ مِنَ الإِنْسَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13641, 'مَقْعَدٌ', 'مقعد', 'جامد', 'قعد', 'مقعد', 'مقعد', '', '', '', 'مفرد', 'DnN', '', '', '"مَقَاعِدُ"', '', 'R', '', '', '', '', '', '', '". 1.""جَلَسَ فِي مَقْعَدِهِ"" : مَكَانُ القُعُودِ، الجُلُوسِ.القمر آية 55 فِي مَقْعَدِ صِدْقٍ عِنْدَ مَلِيكٍ مُقْتَدِرٍ (قرآن) l ""تَجَنَّبْ مَقْعَدَكَ مَعَ أَهْلِ السُّوءِ"". 2.""الْمَقْعَدُ الدِّرَاسِيُّ"" : الكُرْسِيُّ الَّذِي يُجْلَسُ عَلَيْهِ."', '');
