INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13700, 'قُلْقَاسِيَّاتٌ', 'قلقاسيات', 'جامد', '', 'قلقاسيات', 'قلقست', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ، مِنْ ذَوَاتِ الْفِلْقَةِ الوَاحِدَةِ، عَسْقَلِيّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13701, 'أقَلِّيَّةٌ', 'أقلية', 'جامد', 'قلل', 'ءقلية', 'قلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""هُمْ أقَلِّيَّةً فِي الْمَهْجَرِ"": جَمَاعَةٌ تَرْبِطُهَا أَوَاصِرُ القَرَابَةِ وَالأصْلِ لُغَةً وَدِيناً ووَطَناً، تَعِيشُ وَسَطَ شَعْبٍ يَفُوقُه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13702, 'إقْلِيمٌ', 'إقليم', 'جامد', 'قلم', 'ءقليم', 'إقلم', '', '', '', 'مفرد', 'DnN', '', '', '"أقَالِيمُ"', '', 'Rp', '', '', '', '', '', '', '"(جغ). ""يَتَمَيَّزُ إقْلِيمُ الْغَرْبِ بِخُصوبَةِ أرَاضِيهِ"" : مِنْطَقَةٌ، جِهَةٌ لَهَا خَصَائِصُهَا الجُغْرَافِيَّةُ ومُمَيِّزَاتُهَا الإنْتَاجِيَّةُ. ""تَنْقَسِمُ البِلاَدُ إلَى عِدَّةِ أقَالِيمَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13703, 'أقَالِيمُ', 'أقاليم', 'جامد', '', 'ءقاليم', 'قلم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13704, 'قُلاَمَةٌ', 'قلامة', 'جامد', 'قلم', 'قلامة', 'قلمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قُلاَمَةٌ-قُلاَمَةٌ [ق ل م]. 1.""قُلاَمَةُ الظُّفْرِ"" : مَا قُطِعَ مِنْ طَرَفِهِ. 2.""لاَ يُسَاوِي قُلاَمَةَ ظُفْرٍ"" : أَيْ هُوَ حَقِيرٌ لاَ قِيمَةَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13705, 'قَلَمٌ', 'قلم', 'جامد', 'قلم', 'قلم', 'قلم', '', '', '', 'مفرد', 'DnN', '', '', '"أَقْلاَمٌ"', '', 'R', '', '', '', '', '', '', '". 1.""يَكْتُبُ بِقَلَمِ الرَّصَاصِ"" : عُودٌ بِدَاخِلِهِ رَصَاصٌ يُبْرَى لِيُكْتَبَ بِهِ. ""قَلَمُ حِبْرٍ"" ""قَلَمٌ جَافٌّ"". 2.""قَلَمُ التَّحْرِيرِ"" : هَيْئَةُ التَّحْرِيرِ. 3.""مَقَالَةٌ بِقَلَمِ فُلاَنٍ"": مِنْ إِنْشَائِهِ. 4.""هُوَ مِنْ أَهْلِ القَلَمِ"" : مِنْ أَهْلِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13706, 'أَقْلاَمٌ', 'أقلام', 'جامد', '', 'ءقلام', 'قلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13707, 'مِقْلَمَةٌ', 'مقلمة', 'جامد', 'قلم', 'مقلمة', 'مقلمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". : صُنْدُوقَةٌ صَغِيرَةٌ تُوضَعُ فِيهَا أَقْلاَمُ الكِتَابَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13708, 'قَلَنْسُوَةٌ', 'قلنسوة', 'جامد', '', 'قلنسوة', 'قلنسة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ات:قَلاَنِسُ"', '', 'R', '', '', '', '', '', '', '"ج: ات، قَلاَنِسُ. ""وَضَعَ قَلَنْسُوَةً عَلَى رَأْسِهِ"" : طَاقِيَةً، غِطَاء الرَّأْسِ، أَشْكَالُهَا مُتَنَوِّعَةٌ حَس"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13709, 'قَلاَنِسُ', 'قلانس', 'جامد', '', 'قلانس', 'قلنس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13710, 'قَلِيَّةٌ', 'قلية', 'جامد', 'قلي', 'قلية', 'قلة', '', '', '', 'مفرد', 'DnN', '', '', '"قَلاَيَا"', '', '', '', '', '', '', '', '', '"(طخ). ""أَكْلَةُ القَلِيَّةِ"" : مَا قُلِيَ مِنْ لَحْمٍ وَغَيْرِهِ مَعَ مَرَقٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13711, 'قَلاَيَا', 'قلايا', 'جامد', '', 'قلايا', 'قل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13712, 'مِقْلاَةٌ', 'مقلاة', 'جامد', 'قلي', 'مقلاة', 'مقلة', '', '', '', 'مفرد', 'DnN', '', '', '"مَقَالٍ"', '', '', '', '', '', '', '', '', '".: صَحْنٌ مِنْ مَعْدِنٍ يُقْلَى فِيهِ اللَّحْمُوبَعْضُ أَنْوَاعِ الخُضَرِ والْحِمَّصُ والفُولُ ونَحْوُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13713, 'مَقَالِي', 'مقالي', 'جامد', '', 'مقالي', 'مقل', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13714, 'مِقْلَى', 'مقلى', 'جامد', 'قلي', 'مقلى', 'مقل', '', '', '', 'مفرد', 'Dy', '', '', '"مَقَالٍ:الْمَقَالِي"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ن. مِقْلاَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13715, 'مَقَالِي', 'مقالي', 'جامد', '', 'مقالي', 'مقل', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13716, 'قِلْيٌ', 'قلي', 'جامد', '', 'قلي', 'قل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rw', '', 'N', 'O', 'O', 'O', '', '": مَوَادُّ مُرَكَّبَةٌ مِنْ مَعْدِنٍ وَأُكْسِجِينٍ كَالكِلْسِ وَالبُوتَاسْيُومِ وَالصُّودْيُومِ. ن. قَلَوِيٌّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13717, 'قُمَاشٌ', 'قماش', 'جامد', '', 'قماش', 'قمش', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَقْمِشَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَقْمِشَةٌ. 1.""تَعْتَنِي بِقُمَاشِ البَيْتِ"" : بِأَمْتِعَتِهِ وَأَثَاثِهِ. 2.""ثَوْبٌ جَيِّدُ القُمَاشِ"" : نَسِيجُهُ جَي"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13718, 'أَقْمِشَةٌ', 'أقمشة', 'جامد', '', 'ءقمشة', 'قمشة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13719, 'قَمْحِيَّةٌ', 'قمحية', 'جامد', 'قمح', 'قمحية', 'قمحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"قَمْحِيَّةٌ-قَمْحِيَّةٌ [ق م ح] (طخ). : حَلْوَى تُحَضَّرُ مِنَ القَمْحِ الْمَسْلُوقِ وَتُحَلَّى بِالسُّك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13720, 'قَمْحٌ', 'قمح', 'جامد', '', 'قمح', 'قمح', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '": نَبَاتٌ يَنْمُو دَاخِلَ سُنْبُلَةٍ، يُدْرَسُ، وَيُطْحَنُ وَيُتَّخَذُ مِنْهُ الْخُبْزُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13721, 'قِمَارٌ', 'قمار', 'جامد', 'قمر', 'قمار', 'قمر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قِمَارٌ-قِمَارٌ [ق م ر]. : رِهَانٌ قَائِمٌ عَلَى الصِّدْفَةِ وَالْحَظِّ بِأَدَوَاتٍ مُخْتَلِفَةٍ، يَأْخُذُ بِمُقْتَض"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13722, 'قَمْرَاءُ', 'قمراء', 'جامد', 'قمر', 'قمراء', 'قمر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"قَمْرَاءُ-قَمْرَاءُ [ق م ر]. ""لَيْلَةٌ قَمْرَاءُ"" : لَيْلَةٌ قَمْرَةٌ، مُضِيئَةٌ بِنُورِ القَمَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13723, 'قِطْمِيرٌ', 'قطمير', 'جامد', '', 'قطمير', 'قطمر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"قَطَامِيرُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قِطْمِيرٌ - ج: قَطَامِيرُ. 1.""قِطْمِيرُ النَّوَاةِ"" : الْقِشْرَةُ الرَّقِيقَةُ عَلَى النَّوَاةِ. 2.""مَا أَمْلِكُ قِطْمِيراً"" : مَا أَمْلِكُ شَيْئاً هَيِّناً أَوْ حَقِيراً. ""مَا أَصَبْتُ مِنْهُ قِطْمِيراً"". "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13724, 'قَطَامِيرُ', 'قطامير', 'جامد', '', 'قطامير', 'قطمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13725, 'قُمْرَةٌ', 'قمرة', 'جامد', 'قمر', 'قمرة', 'قمرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قُمْرَةٌ - [ق م ر]. 1.""لَوْنُهُ لَوْنُ قُمْرَةٍ"" : بَيَاضٌ إِلَى خُضْرَةٍ. 2.""ظَهَرَتِ الْقُمْرَةُ"" : الْقَمَرُ فِي اللَّيْلَةِ الثَّالِثَةِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13726, 'قَمْرِيَّةٌ', 'قمرية', 'جامد', 'قمر', 'قمرية', 'قمرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"قَمْرِيَّةٌ-قَمْرِيَّةٌ [ق م ر]. ""يُطِلُّ مِنَ القَمْرِيَّةِ"" : نَافِذَةٌ صَغِيرَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13727, 'قَمَرٌ', 'قمر', 'جامد', '', 'قمر', 'قمر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَقْمَارٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَقْمَارٌ. 1.""أَرْسَلَ القَمَرُ خُيُوطَهُ الفِضِّيَّةَ عَلَى البِقَاعِ"" : كَوْكَبٌ يَسْتَمِدُّ نُورَهُ مِنَ الشَّمْسِ فَيَنْعَكِسُ عَلَى الأَرْضِ فِي دَوَرَاتِهِ عَلَيْهَا، وَيُسَمَّى هِلاَلاً بِثَلاَثِ لَيَالٍ مِنْ أَوَّلِ الشًّهْرِ، ثُمَّ هُوَ قَمَرٌ فِي سَائِرِ أَيَّامِهِ. 2.""أَقْمَارُ العِلْمِ وَشُمُ"', ':لا جذر:لا مفرد');
