INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13729, 'قُمْرِيُّ', 'قمري', 'جامد', '', 'قمري', 'قمر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"قُمْرٌ:قَمَارِيٌّ"', '', '', '', '', '', '', '', '', '"ج: قُمْرٌ، قَمَارِيٌّ. (حو). : ضَرْبٌ مِنَ الْحَمَامِ، أَسْمَرُ اللَّوْنِ وَرَمَادِيٌّ، حَسَنُ الصَّوْتِ."', ':لا جذر:لا مفرد');
