INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13745, 'قَمَعَةٌ', 'قمعة', 'جامد', 'قمع', 'قمعة', 'قمعة', '', '', '', 'مفرد', 'DnN', '', '', '"قَمَعٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قَمَعَةٌ - ج: قَمَعٌ. [ق م ع]. 1.""قَمَعَةُ الذَّنَبِ"" : طَرَفُهُ.   ""قَمَعَةُ الْحُلْقُومِ"". 2.""قَمَعَةُ الْعَيْنِ"" : قُرْحَتُهَا. 3.""قَمَعَةُ الشَّيْءِ"": خِيَارُهُ. 4.""قَمَعُ الدَّوَابِّ"" : ذُبَابٌ أَزْرَقُ عَظِيمٌ يَدْخُلُ فِي أُنُوفِهَا، وَيَقَعُ بِالأَخَصِّ عَلَى الإِبِلِ وَالظِّبَاءِ وَالْوَحْشِ إِذَا اشْتَدَّ الْحَرُّ فَيَلْسَعُهَ"', '');
