INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13763, 'مِقْنَبٌ', 'مقنب', 'جامد', 'قنب', 'مقنب', 'مقنب', '', '', '', 'مفرد', 'DnN', '', '', '"مَقَانِبُ"', '', 'R', '', '', '', '', '', '', '"مِقْنَبٌ - ج: مَقَانِبُ. [ق ن ب]. 1. ""مَقَانِبُ الأَسَدِ"" : مَخَالِبُهُ. 2. ""مِقْنَبُ الصَّائِدِ"" : مِخْلاَتُهُ، أَيْ مَا يَضَعُ فِيهِ صَيْدَهُ. 3. ""تَهَيُّـؤُ المِقْنَبِ"" : الجَمَاعَةُ مِنَ الخَيْلِ، تَجْتَمِعُ لِلْغَارَةِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13764, 'مَقَانِبُ', 'مقانب', 'جامد', '', 'مقانب', 'مقنب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13765, 'قُنَّبٌ', 'قنب', 'جامد', '', 'قنب', 'قنب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُنَّبٌ-قُنَّبٌ (نب). : نَبَاتٌ مِنْ فَصِيلَةِ القُنَّبِيَّاتِ يُنْتِجُ لِيفاً مَتِيناً يُفْتَلُ لِصُنْعِ الْحِبَالِ أَوِ الْقِيطَانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13766, 'قُنْبُرَةٌ', 'قنبرة', 'جامد', '', 'قنبرة', 'قنبرة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"قَنَابِرُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: قَنَابِرُ. (حو). : طائِرٌ مِنْ فَصِيلَةِ مَالِكٍ الْحَزِينِ، مِنْ رُتْبَةِ اللَّقَالِقِ، لَهُ رِي"', ':لا جذر:لا مفرد');
