INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13768, 'قُنْبُلَةٌ', 'قنبلة', 'جامد', 'قنبل', 'قنبلة', 'قنبلة', '', '', '', 'مفرد', 'DnN', '', '', '"قَنَابِلُ"', '', 'R', '', '', '', '', '', '', '". 1. : قَذِيفَةٌ مَحْشُوَّةٌ بِمَوَادَّ مُتَفَجِّرَةٍ يُلْقَى بِهَا عَلَى العَدُوِّ، وَهِيَ أَنْوَاعٌ : ""القُنْبُلَةُ الْحَارِقَةُ""، ""القُنْبُلَةُ الْجُرْثُومِيَّةُ""، ""القُنْبُلَةُ النَّوَوِيَّةُ"". 2.""شَتَّتُوا الْمُتَظَ"', '');
