INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13771, 'قُنَّبِيطٌ', 'قنبيط', 'جامد', '', 'قنبيط', 'قنبط', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُنَّبِيطٌ-قُنَّبِيطٌ (نب).: بَقْلَةٌ مِنْ فَصِيلَةِ الصَّلِيبِيَّاتِ، تُقْطَفُ قَبْلَ إِزْهَارِهَا، بَيْضَاءُ وَلَحْمِيَّةٌ فِي جَمِيعِ أَجْزَائِهَا، تُعْرَفُ فِي مِصْرَ وَالشَّامِ بِالقَرْنَبِيطِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13772, 'قُنُوتٌ', 'قنوت', 'جامد', 'قنت', 'قنوت', 'قنت', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُنُوتٌ-قُنُوتٌ [ق ن ت]. 1.""هُوَ فِي قُنُوتِ اللَّهِ"" : فيِ طَاعِتِهِ. 2.""اِرْتَفَعَ صَوْتُهُ قُنُوتاً"" : دُعَاءً. 3.""القُنُوتُ فِي الصَّلاَةِ"" : القِيَامُ فِي الصَّلاَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13773, 'قُنْدُسٌ', 'قندس', 'جامد', '', 'قندس', 'قندس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قُنْدُسٌ-قُنْدُسٌ(حو). : حَيَوانٌ مِنْ فَصيلَـةِ القُنْدُسِيَّـاتِ مِـنَ القَوارِضِ الْمَائِيَّةِ، لَهُ ذَنَبٌ قَوِيٌّ مُفَلطَحٌ"', ':لا جذر:لا مفرد');
