INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13792, 'قَانُونٌ', 'قانون', 'جامد', 'قنن', 'قانون', 'قنن', '', '', '', 'مفرد', 'DnN', '', '', '"قَوَانِينُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""قَانوُنُ الْعَمَلِ"" : مِقْيَاسُ كُلِّ شَيْءٍ وَطَرِيقُهُ. 2.""هُوَ خَاضِعٌ لِلْقَانُونِ"" : خَاضِعٌ للِنِّظَامِ، للِشَّرِيعَةِ. 3.""رَجُلُ الْقَانُونِ"" : الْعَارِفُ بِالْقَوَانِينِ وَالْأَحْكَامِ وَالْمُتَخَصِّصُ فِيهَا. 4.""قَانُونُ الأَحْوَالِ الشَّخْصِيَّةِ"" : مُدَوَّنَةُ الأَحْوَالِ الشَّخْصِيَّةِ الَّتِي تَضُمُّ مَجْمُوعَ التَّشْرِيعَاتِ الْمُنَظِّمَةِ لِلْأُسْرَةِ. ""الْقَانُونُ الْجِنَائِيُّ"" ""الْقَانُونُ الدَّوْلِيُّ"". 5.""يَعْزِفُ عَل"', '');
