INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13806, 'مُقْتَنَيَاتٌ', 'مقتنيات', 'جامد', 'قني', 'مقتنيات', 'مقتنت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُقْتَنَيَاتٌ-مُقْتَنَيَاتٌ [ق ن ي]. ""كَانَتْ كُلُّ مُقْتَنَيَاتِهِ مِنَ كَذَا"" : مُشْتَرَيَاتِهِ، مُمْتَلَكَاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13807, 'قَهْوَةٌ', 'قهوة', 'جامد', 'قهو', 'قهوة', 'قهة', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَهْوَةٌ-قَهْوَةٌ [ق هـ و]. : شَرَابُ البُنِّ الْمُغَلَّى. ""يَرْتَشِفُ قَهْوَةَ الصَّبَاحِ"" ""رَكْوَةُ القَهْوَةِ"" ""فِنْجَانُ القَهْوَةِ"". 2.""اِلْتَقَى بِهِ فِي القَهْوَةِ "" : الْمَقْهَى، مَكَانُ شُرْبِ القَهْوَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13808, 'مَقْهَى', 'مقهى', 'جامد', 'قهو', 'مقهى', 'مقه', '', '', '', 'مفرد', 'Dy', '', '', '"مَقَاهٍ:الْمَقَاهِي"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""جَلَسَ فِي الْمَقْهَى يَحْتَسِي قَهْوَتَهُ"" : الْمَحَلُّ الَّذِي تُشْرَبُ فِيهِ القَهْوَةُ ومَا شَابَهَ ذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13809, 'مَقَاهِي', 'مقاهي', 'جامد', '', 'مقاهي', 'مقه', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13810, 'قَوَاضِمُ', 'قواضم', 'جامد', '', 'قواضم', 'قضم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '": رُتْبَةٌ حَيَوَانِيَّةٌ مِنَ اللَّبُونَاتِ، مُتَمَيِّزَةٌ بِصِغَرِ حَجْمِهَا، لَهَا ثَنَايَا مُسْتَطِيلَةٌ حَادَّةُ الأَطْرَافِ تُمَكِّنُهَا مِنَ القَضْمِ، مِنْ أَشْهَرِ فَصَائِلِهَا السِّنْجَابِيَّاتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13811, 'قُواعٌ', 'قواع', 'جامد', '', 'قواع', 'قع', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُواعٌ-قُواعٌ (حو). : ذَكَرُ الأَرْنَبِ، كما يُطْلَقُ على الأَرْنَبِ الوَحْشِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13812, 'قَابٌ', 'قاب', 'جامد', 'قوب', 'قاب', 'قب', '', '', '', 'مفرد', 'DnN', '', '', '"أَقْوَابٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""قَابُ الْقَوْسِ"" : مَا بَيْنَ نِصْفِ وَتَرِ الْقَوْسِ وَطَرَفِهِ. 2.""بَيْنَهُمَا قَابُ قَوْسٍ"" : كِنَايَةٌ عَنِ القُرْبِ. 3.""قَابُ قَوْسَيْنِ"" : أَيْ طُولَ قَوْسَيْنِ.النجم آية 9 فَكَانَ قَابَ قَوْسَيْنِ أَو أَدْنَى ( قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13813, 'أَقْوَابٌ', 'أقواب', 'جامد', '', 'ءقواب', 'قب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13814, 'قَاتٌ', 'قات', 'جامد', 'قوت', 'قات', 'قت', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَاتٌ-قَاتٌ [ق و ت] (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الْقَاتِيَّاتِ، يُزْرَعُ فِي الْيَمَنِ، وَتُمْضَغُ أَوْرَاقُهُ خَضْرَاءَ، وَهُوَ مُنَبِّهٌ وَمُخَدِّرٌ فِي حَالَةِ الْإِكْثَارِ مِنْ مَضْغِهِ،كَمَا يُصْنَعُ مِنْ تَقْطِيرِ ثِمَارِهِ عَصِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13815, 'قُوتٌ', 'قوت', 'جامد', 'قوت', 'قوت', 'قت', '', '', '', 'مفرد', 'DnN', '', '', '"أَقْوَاتٌ"', '', 'R', '', '', '', '', '', '', '". ""يَبْحَثُ عَنْ قُوتِهِ"" : مَا يَأْكُلُهُ الكَائِنُ الْحَيُّ وَيَقْتَاتُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13816, 'أَقْوَاتٌ', 'أقوات', 'جامد', '', 'ءقوات', 'قت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13817, 'مِقْوَدٌ', 'مقود', 'جامد', 'قود', 'مقود', 'مقد', '', '', '', 'مفرد', 'DnN', '', '', '"مَقَاوِدُ"', '', 'R', '', '', '', '', '', '', '". 1. ""شَدَّ مِقْوَدَ الدَّابَّةِ"" : مَا تُقَادُ بِهِ الدَّابَّةُويَكُونُ مُتَّصِلاً بِاللِّجَامِ. 2. ""مِقْوَدُ السَّيَّارَةِ"" : جِهَازٌ آلِيٌّ يَتَحَكَّمُ فِي سَيْرِ السَّيَّارَةِ وتَوْجِيهِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13818, 'مَقَاوِدُ', 'مقاود', 'جامد', '', 'مقاود', 'مقد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13819, 'قَوَارِيُّ', 'قواري', 'جامد', 'قور', 'قواري', 'قر', '', '', '', 'مفرد', '', '', '', '"مفردقَارِيَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""هُـمْ قَوَارِيُّ اللَّهِ فِي أَرْضِهِ"" : أُمَنَاؤُهُ، شُهَدَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13820, 'قَارِيَة', 'قارية', 'جامد', '', 'قارية', 'قرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13821, 'مِقْوَرَةٌ', 'مقورة', 'جامد', 'قور', 'مقورة', 'مقرة', '', '', '', 'مفرد', 'DnN', '', '', '"مَقَاوِرُ"', '', 'R', '', '', '', '', '', '', '". ""مِقْوَرَةُ الخُضَرِ"" : أَدَاةٌ لِتَجْوِيفِ الخُضَرِ كَالبَاذِنْجَانِ ونَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13822, 'مَقَاوِرُ', 'مقاور', 'جامد', '', 'مقاور', 'مقر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13823, 'قَارٌ', 'قار', 'جامد', 'قور،قير', 'قار', 'قر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قَارٌ-قَارٌ [ق و ر، ق ي ر]. 1. : مَادَّةٌ سَوْدَاءُ تُطْلَى بِهَا السُّفُنُ. 2. : الزِّفْتُ وَهُوَ مَادَّةٌ سَوْدَاءُ لِتَبْلِيطِ الطُّرُقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13824, 'قَوْسٌ', 'قوس', 'جامد', '', 'قوس', 'قس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَقْوَاسٌ(مؤ:وَقَدْتُذَكَّرُ)', '', 'R', '', '', '', '', '', '', '"ج: أَقْوَاسٌ. (مؤ، وَقَدْ تُذَكَّرُ). 1.""رَمَاهُ بِالقَوْسِ"" : آلَةٌ حَرْبِيَّةٌ قَدِيمَةٌ نِصْفُ دَائِرِيَّةٍ، مَشْدُودَةٌ مِنْ طَرَفَيْهَا بِحَبْلٍ مَطَّاطٍ، تُرْمَى بِهَا السِّهَامُ. وَتُضَافُ إِلَى مَا يُخَصِّصُهَا فَيُقَالُ: ""قَوْسُ نَبْلٍ""، ""قَـوْسُ قُـزَحٍ""، ""قَوْسُ كَمَنْجَةٍ"". 2.""قَوْسُ دَائِرَةٍ"" : نِصْفُهَا، وَيُطْلَقُ عَلَى كُلِّ مَا كَانَ مُنْ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13825, 'أَقْوَاسٌ', 'أقواس', 'جامد', '', 'ءقواس', 'قس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13826, 'قَاعَةٌ', 'قاعة', 'جامد', 'قوع', 'قاعة', 'قعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""قَاعَةُ الدَّارِ"" : سَاحَتُهَا. 2.""قَاعَةُ الاِسْتِقْبَالِ"" : الرَّدْهَةُ الْوَاسِعَةُ مِنَ الْبِنَاءِ. ""قَاعَةُ الْمُحَاضَرَاتِ"" ""قَاعَةُ الْمُطَالعَةِ"" ""قَاعَةُ الْمَحْكَمَةِ"" ""قَاعَةُ الأَكْلِ"" ""قَاعَةُ الانْتِظَارِ"" ""قَاعَةُ الدَّرْسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13827, 'قَاعٌ', 'قاع', 'جامد', 'قوع', 'قاع', 'قع', '', '', '', 'مفرد', 'DnN', '', '', '"قِيعَانٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '".""غَاصَتِ الْغَوَّاصَةُ فِي قَاعِ الْبَحْرِ"" : فِي عُمْقِهِ، فِي قَعْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13828, 'قِيعَانٌ', 'قيعان', 'جامد', '', 'قيعان', 'قعن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13829, 'قَافٌ', 'قاف', 'جامد', 'قوف', 'قاف', 'قف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قَافٌ-قَافٌ [ق و ف]. ""قَافُ الرَّقَبَةِ"" : الشَّعْرُ السَّائِلُ فِي نُقْرَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13830, 'قَافِيَةٌ', 'قافية', 'جامد', 'قوف', 'قافية', 'قفة', '', '', '', 'مفرد', 'DnN', '', '', '"قَوَافٍ:الْقَوَافِي"', '', '', '', '', '', '', '', '', '". : هِيَ آخِرُ كَلِمَةٍ فِي الْبَيْتِ الشِّعْرِيِّ، أَيِ السَّاكِنَانِ الْأَخِيرانِ مِنْهُ وَمَا بَيْنَهُمَا مَعَ الْمُتَحَرِّكِ الَّذِي قَبْلَهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13831, 'قَوَافِي', 'قوافي', 'جامد', '', 'قوافي', 'قف', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13832, 'قَاقٌ', 'قاق', 'جامد', 'قوق', 'قاق', 'قق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قَاقٌ-قَاقٌ [ق و ق] (حو). : طَائِرٌ مِنْ فَصِيلَةِ الْغُرَابِيَّاتِ، مِنْ رُتْبَةِالْعُصْفُورِيَّاتِ، رَمَادِيُّ اللَّوْنِ، أَسْوَدُ الرَّأْسِ وَالْجَنَاحَيْنِ وَالذَّنَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13833, 'قَوْقَعٌ', 'قوقع', 'جامد', '', 'قوقع', 'ققع', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ن. حَلَزونٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13834, 'قَوْقَعِيَّاتٌ', 'قوقعيات', 'جامد', '', 'قوقعيات', 'ققعت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ حَيَوَانِيَّةٌ تُعْرَفُ بِالرِّخْوِيَاتِ، لَهَا أَصْدَافٌ مُفْرَدَةٌ حَلَزُونِيَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13835, 'قِيَامَةٌ', 'قيامة', 'جامد', 'قوم', 'قيامة', 'قمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"قِيَامَةٌ-قِيَامَةٌ [ق و م]. 1.""قِيَامَةُ الأَمْوَاتِ"" : اِنْبِعَاثُهُمْ مِنَ الْمَوْتِ. 2.""أَقَامَ صَلاَةَ عِيدِ القِيَامَةِ"" : عِيدُ الفِصْحِ عِنْدَ الْمَسِيحِيِّينَ. 3.""القِيَامَة"" : سُورَةٌ مِنْ سُوَرِ القُرْآنِ الكَرِيمِ.القيامة آية 1لاَ أُقْسِمُ بِيَوْمِ القِيَامَةِ ). قرآن). 4.""يَوْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13836, 'قَائِمَةٌ', 'قائمة', 'جامد', 'قوم', 'قاءمة', 'قمة', '', '', '', 'مفرد', 'DnN', '', '', '"قَوَائِمُ"', '', '', '', '', '', '', '', '', '". 1.""قَائِمَةُ الدَّابَّةِ"" : رِجْلُهَا أَوْ يَدُهَا. ""حَيَوَانٌ مِنْ ذَوَاتِ الْقَوَائِمِ"". 2.""قَائِمَةُ السَّيْفِ"" : مَقْبَضُهُ. 3.""قَوَائِمُ الْمَائِدَةِ"": أَعْمِدَتُهَا. 4.""قَدَّمَ لَهُ قَائِمَةً بِالْحِسَابِ"" : وَرَقَةٌ تُبَيِّنُ الْحِسَابَ الْمَطْلُوبَ. 5.""قَائِمَةُ الْكُتُبِ"" : لاَئِحَةُ الْكُتُبِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13837, 'قَوَائِمُ', 'قوائم', 'جامد', '', 'قواءم', 'قم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13838, 'قَوَامٌ', 'قوام', 'جامد', 'قوم', 'قوام', 'قم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَوَامٌ-قَوَامٌ [ق و م]. 1.""رُمْحٌ قَوَامٌ"" : مُسْتَقِيمٌ. 2.""قَوَامُ الإِنْسَانِ"" : قَامَتُهُ وَحُسْنُ طُولِهِ.الفرقان آية 67وَكَانَ بَيْنَ ذَلِكَ قَوَاما ( قرآن) : أَيْ عَدْلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13839, 'مَقَامَةٌ', 'مقامة', 'جامد', 'قوم', 'مقامة', 'مقمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""مَقَامَةُ النَّاسِ"" : مَجْمَعُهُمْ، مَجْلِسُهُمْ. 2. ""أَلْقَى مَقَامَةً عَلَى الجُمْهُورِ"" : خُطْبَةً. 3. ""كَتَبَ مَقَامَةً فُكَاهِيَّةً"" : أَيْ حَدِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13840, 'مَقَامٌ', 'مقام', 'جامد', 'قوم', 'مقام', 'مقم', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""مَقَامُ الوَلِيِّ الصَّالِحِ"" : مَكَانُهُ الْمُقَدَّسُ. 2. ""لَهُ مَقَامٌ مُهِمٌّ فِي إِدَارَتِهِ"" : مَنْزِلَةٌ. 3. ""قَامَ مَقَامَهُ"" : أَخَذَ مَكَانَهُ. ""أَنِيرِي مَكَانَ البَدْرِ إِنْ أَفَلَ البَدْرُ وقُومِي مَقَامَ الشَّمْسِ مَا اسْتَأْجَرَ الف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13841, 'مِقْوَمٌ', 'مقوم', 'جامد', 'قوم', 'مقوم', 'مقم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِقْوَمٌ-مِقْوَمٌ [ق و م]. ""مِقْوَمُ المِحْرَاثِ"" : خَشَبَةُ المِحْرَاثِ الَّتِي يُمْسِكُهَا الْحَرَّاثُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13842, 'قَوَاءٌ', 'قواء', 'جامد', 'قوي', 'قواء', 'ق', '', '', '', 'مفرد', '', '', '', '"أَقْوَاءٌ"', '', 'Rz', '', 'N', 'O', 'O', 'O', '', '". 1.""تَاهَ فِي القَوَاءِ"" : فِي صَحْرَاءَ مُقْفِرَةٍ، القَفْر، الْخَلاَء. 2.""بَاتَ القَوَاءَ"" : بَاتَ جَائِعاً. 3.""مَنْزِلٌ قَوَاءٌ"" : لاَ أَنِيسَ بِهِ، خَالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13843, 'أَقْوَاءٌ', 'أقواء', 'جامد', '', 'ءقواء', 'ق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
