INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13846, 'قَيْدٌ', 'قيد', 'جامد', 'قيد', 'قيد', 'قد', '', '', '', 'مفرد', 'DnN', '', '', '"قُيُودٌ"', '', 'R', '', '', '', '', '', '', '". 1.""رَبَطَ يَدَيْهِ بِقَيْدٍ"" : بِحَبْلٍ أَوْ بِحَدِيدٍ، أَيْ غَلَّ يَدَيْهِ. ""وَلاَ بُدَّ لِلْقَيْدِ أَنْ يَنْكَسِر"". (أبو القاسم الشابي). 3.""اِسْتَجَابَ لِرَغْبَتِهِ بِل"', '');
