INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13849, 'قَيْدُومٌ', 'قيدوم', 'جامد', '', 'قيدوم', 'قدم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"قَيَادِمَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: قَيَادِمَةٌ. 1.""قَيْدُومُ الْجَبَلِ"" : أنْفٌ يَتَقَدَّمُ مِنْهُ. 2.""قَيْد"', ':لا جذر:لا مفرد');
