INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13855, 'قِيسَارِيَّةٌ', 'قيسارية', 'جامد', '', 'قيسارية', 'قسرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '": سُوقٌ كَبِيرٌ فِي الْمُدُنِ العَتِيقَةِ تُبَاعُ فِيهِ الأَثْوَابُ وَالزَّرَابِيُّ وَنَحْوُهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13856, 'قَيْصَرٌ', 'قيصر', 'جامد', '', 'قيصر', 'قصر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"قَيَاصِرَةٌ"', '', 'Rp', '', '', '', '', '', '', '"ج: قَيَاصِرَةٌ. : لَقَبُ كُلِّ مَلِكٍ مِنْ مُلُوكِ الرُّومَانِ وَالبِيزَنْطِيِّينَ وَالرُّوسِ. بَك"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13857, 'قَيَاصِرَةٌ', 'قياصرة', 'جامد', '', 'قياصرة', 'قصرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13858, 'قَيْصَرِيَّةٌ', 'قيصرية', 'جامد', '', 'قيصرية', 'قصرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'N', 'O', '', '"""لَمْ يَكُنْ بُدٌّ مِنْ إِجْرَاءِ العَمَلِيَّةِ القَيْصَرِيَّةِ"" : عَمَلِيَّةٌ جِرَاحِيَّةٌ يَلْجَأُ إِلَيْهَا الطَّبِيبُ، تَقْتَضِ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13859, 'قَيْضٌ', 'قيض', 'جامد', 'قيض', 'قيض', 'قض', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قَيْضٌ-قَيْضٌ [ق ي ض]. ""قَيْضُ البَيْضَةِ"" : قِشْرَتُهَا اليَابِسَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13860, 'قِيقٌ', 'قيق', 'جامد', '', 'قيق', 'قق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"قِيقٌ-قِيقٌ (حو). : طَائِرٌ مِنْ فَصِيلَةِ الغُرَابِيَّاتِ، مِنْ رُتْبَةِ العُصْفُورِيَّاتِ بِحَجْمِ الْحَمَامَةِ،"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13861, 'مَقِيلٌ', 'مقيل', 'جامد', 'قيل', 'مقيل', 'مقل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَقِيلٌ-مَقِيلٌ [ق ي ل]. 1. ""اِسْتَرَاحُوا فِي الْمَقِيلِ"" : مَوْضِعُ القَيْلُولَةِ. 2. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13862, 'قَيُّومٌ', 'قيوم', 'جامد', 'قوم', 'قيوم', 'قم', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'N', 'N', '', '"قَيُّومٌ-قَيُّومٌ [ق و م]. ""هُوَ اللهُ الْحَيُّ القَيُّومُ"" : مِنْ أَسْمَاءِ اللهِ الْحُسْنَى، أَي الَّذي لا بَدْءَ لَهُ، وَالقَائِمُ بِذَاتِهِ وَلاَ نَظِيرَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13863, 'قَيَّانَةٌ', 'قيانة', 'جامد', 'قين', 'قيانة', 'قنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""قَيَّانَةُ البَيْتِ"" : الْمَرْأَةُ القَائِمَةُ بِشُؤُونِ الْمَنْزِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13864, 'كَأْبَاءُ', 'كأباء', 'جامد', 'كأب', 'كءباء', 'كب', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"كَأْبَاءُ-كَأْبَاءُ [ك أ ب]. ""عَاشَ حَيَاةً كَأْبَاءَ"" : حَيَاةً مَلِيئَةً بِالحُزْنِ الشَّدِيدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13865, 'كَاتِدْرَائِيَّةٌ', 'كاتدرائية', 'جامد', '', 'كاتدراءية', 'كتدرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"1. : كَنِيسَةُ الكُرْسِيِّ الأُسْقُفِيِّ. 2.:الكَنِيسَةُ الأُسْقُفِيَّةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13866, 'كَاثُولِيك', 'كاثوليك', 'جامد', '', 'كاثوليك', 'كثلك', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '": اِسْمٌ يُطْلَقُ عَلَى كُلِّ الْمَسِيحِيِّينَ الْمُنْضَوِينَ تَحْتَ لِوَاءِ قَدَاسَةِ البَابَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13867, 'كَأْدَاءُ', 'كأداء', 'جامد', 'كأد', 'كءداء', 'كد', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"كَأْدَاءُ-كَأْدَاءُ [ك أ د]. 1.""وَاجَهَ حَيَاةً كَأْدَاءَ"" : صَعْبَةً، شَاقَّةً. 2.""عَقَبَةٌ كَأْدَاءُ"" : ص"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13868, 'كَأْسٌ', 'كأس', 'جامد', '', 'كءس', 'كس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"كُؤُوسٌ:كَاسَاتٌ(مؤ)"', '', 'R', '', '', '', '', '', '', '"كَأْسٌ-كَأْسٌ (مؤ). ج: كُؤُوسٌ، كَاسَاتٌ. 1.""نَاوَلَهُ كَأْسَ مَاءٍ"" : إِنَاء مَاءٍ مُخْتَلِفُ الأَشْكَالِ وَالأَنْـوَاعِ يُشْـرَبُ فِيـهِ. 2.""كَأْسُ الزَّهْرَةِ"" : الغِلاَفُ الخَارِجِيُّ لَهَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13869, 'كُؤُوسٌ', 'كؤوس', 'جامد', '', 'كءوس', 'كس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
