INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13876, 'كَالُورِي', 'كالوري', 'جامد', '', 'كالوري', 'كلر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R0', '', 'N', 'O', 'N', 'O', '', '": سُعْرَةٌ، حُرَيْرَةٌ : الوَحْدَةُ الْحَرَارِيَّةُ، وَهِيَ الكَمِّيَّةُ الْحَرَارِي"', ':لا جذر:لا مفرد');
