INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13878, 'كَامِخٌ', 'كامخ', 'جامد', '', 'كامخ', 'كمخ', '', '', '', 'جمع تكسير', 'DnN', '', '', '"كَوَامِخُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: كَوَامِخُ. : إِدَامٌ، وَيُخَصُّ بِهِ أَنْوَاعُ مُخَلَّلاَتِ الطَّعَامِ ومُشَهِّيَاتِهِ."', ':لا جذر:لا مفرد');
