INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13881, 'كَامِلِيَّةٌ', 'كاملية', 'جامد', '', 'كاملية', 'كملة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"كَامِلِيَّةٌ-كَامِلِيَّةٌ (نب). : شَجَرَةٌ مِنْ فَصِيلَةِ الكَامِلِيَّاتِ، مِنْ أَصْلٍ أَسْيَوِيٍّ"', ':لا جذر:لا مفرد');
