INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13883, 'كَاوْكَاوِيَّةٌ', 'كاوكاوية', 'جامد', '', 'كاوكاوية', 'ككة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '": ثَمَرَةُ شَجَرَةِ الكَاوْكَاوْ، وَهِيَ عَلَى شَكْلِ نَوَاةِ التَّمْرِ، تَحْوِي دَاخِلَ قِشْرَتِهَا حَبَّاتٍ، تُؤْكَلُ مَشْوِيَّةً، وَيُسْتَخْرَجُ مِنْهَا زَيْتٌ"', ':لا جذر:لا مفرد');
