INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13885, 'كَبَّةٌ', 'كبة', 'جامد', 'كبب', 'كبة', 'كبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"كَبَّةٌ-كَبَّةٌ [ك ب ب]. 1.""جَاءوا كَبَّةً"" : جَمَاعَةً مِنَ النَّاسِ. 2.""لَقِيتُهُ فِي الكَبَّةِ"" : أ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13886, 'كُبَّةٌ', 'كبة', 'جامد', 'كبب', 'كبة', 'كبة', '', '', '', 'مفرد', 'DnN', '', '', '"كُبَبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَلْقَى عَلَيْهِ كُبَّتَهُ"" : ثِقْلَهُ. 2.""كُبَّةُ الغَزْلِ"" : اللَّفِيفَةُ، أَيْ مَا جُمِعَ مِنْهَا عَلَى شَكْلِ كُرَةٍ. 3.""قَدَّمَتِ الكُبَّةَ لِلضُّيُوفِ"" : أَكْلَةٌ مِنَ الل"', '');
