INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13888, 'مِكَبٌّ', 'مكب', 'جامد', 'كبب', 'مكب', 'مكب', '', '', '', 'مفرد', 'DnN', '', '', '"مِكَبَّاتٌ:مَكَابُّ"', '', 'R', '', '', '', '', '', '', '".: كُرَةٌ يُلَفُّ عَلَيْهَا الغَزْلُ، أَوِالخُيُوطُ، أَوِ الأَشْرِطَةُ السِّينَمَائِيَّةُ، أَوْ أَشْرِطَةُ التَّسْجِيلِ، بَكَرَةٌ."', '');
