INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13891, 'مِكْبَحٌ', 'مكبح', 'جامد', 'كبح', 'مكبح', 'مكبح', '', '', '', 'مفرد', 'DnN', '', '', '"مَكَابِحُ"', '', 'R', '', '', '', '', '', '', '". ""مَكَابِحُ السَّيَّارَةِ"". : فَرَامِلُهَا الَّتي ت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13892, 'مَكَابِحُ', 'مكابح', 'جامد', '', 'مكابح', 'مكبح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13893, 'كُبَادٌ', 'كباد', 'جامد', 'كبد', 'كباد', 'كبد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كُبَادٌ-كُبَادٌ [ك ب د]. ""أُصِيبَ بِالكُبَادِ"" : وَجَعُ الكَبِدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13894, 'كَبْدَاءُ', 'كبداء', 'جامد', 'كبد', 'كبداء', 'كبد', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"كَبْدَاءُ-كَبْدَاءُ [ك ب د]. 1.""كَبْدَاءُ السَّمَاءِ"" : وَسَطُهَا. 2.""أَدَارَ الكَبْدَاءَ"" : الرَّحَى تُدَارُ بِاليَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13895, 'كَبِدٌ', 'كبد', 'جامد', 'كبد', 'كبد', 'كبد', '', '', '', 'مفرد', 'DnN', '', '', '"أَكْبَادٌ:كُبُودٌ(مؤ:مذ)"', '', 'R', '', '', '', '', '', '', '". 1.:غُدَّةٌ لَحْمِيَّةٌ سَوْدَاءُ فِي الجَانِبِ الأَيْمَنِ مِنَ البَطْنِ تُفْرِزُ الصَّفْرَاءَ. 2.""فِي كَبِدِ السَّمَاءِ"" : فِي وَسَطِهَا. 3.""أَصَابَ كَبِدَ الْحَقِيقَةِ"": أَيْ أَصَابَ صُلْبَهَا. 4.""أَوْلاَدُنَا أَكْب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13896, 'أَكْبَادٌ', 'أكباد', 'جامد', '', 'ءكباد', 'كبد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13897, 'كُبُودٌ', 'كبود', 'جامد', '', 'كبود', 'كبد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13898, 'كَبُّودٌ', 'كبود', 'جامد', 'كبد', 'كبود', 'كبد', '', '', '', 'مفرد', 'DnN', '', '', '"كَبُّودَاتٌ"', '', 'R', '', '', '', '', '', '', '". ""جَاءَ الْحَارِسُ مُرْتَدِياً كَبُّوداً فِي لَيْلَةٍ مِنْ لَيَالِي الشِّتَاءِ"" : مِعْطَفٌ لَهُ قَلَنْسُوَةٌ تُغَطِّي الرَّأْسَ، يَلْبَسُهُ الْجُنُودُ أَوِ الْحُرَّاسُ فِي ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13899, 'كَبُّودَاتٌ', 'كبودات', 'جامد', '', 'كبودات', 'كبدت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13900, 'كَبْرَةٌ', 'كبرة', 'جامد', 'كبر', 'كبرة', 'كبرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"كَبْرَةٌ-كَبْرَةٌ [ك ب ر]. ""عَلَتْهُ كَبْرَةٌ"" : الشَّيْخُوخَةُ، التَّقَدُّمُ فِي السِّنِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13901, 'كِبْرٌ', 'كبر', 'جامد', 'كبر', 'كبر', 'كبر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كِبْرٌ-كِبْرٌ [ك ب ر]. 1.""كِبْرُهُ يَزِيدُ يَوْماً بَعْدَ يَوْمٍ"" : تَعَاظُمُهُ، تَجَبُّرُهُ. 2.""اِرْتَكَبَ كِبْراً"" : إِثْماً فَاحِشاً. النور آية 11وَالذي تَوَلَّى كِبْرَهُ مِنْهُمْ لَهُ عَذَابٌ عَظِيمٌ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13902, 'كَبَرٌ', 'كبر', 'جامد', '', 'كبر', 'كبر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"(نب). : شُجَيْرَةٌ شَائِكَةٌ مِنْ فَصِيلَةِ الكَبَرِيَّاتِ، لَهَا أَزْهَارٌ جَمِيلَةُ الشَّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13903, 'كِبْرِيتٌ', 'كبريت', 'جامد', 'كبرت', 'كبريت', 'كبرت', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كِبْرِيتٌ-كِبْرِيتٌ [ك ب ر ت]. : مَادَّةٌ مَعْدِنِيَّةٌ، صَفْرَاءُ اللَّوْنِ، شَدِيدَةُ الاشْتِعَالِ، تَكْثُرُ فِي الْمَنَاطِقِ البُرْكَانِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13904, 'كَابُوسٌ', 'كابوس', 'جامد', 'كبس', 'كابوس', 'كبس', '', '', '', 'مفرد', 'DnN', '', '', '"كَوَابِيسُ"', '', 'R', '', '', '', '', '', '', '". 1.""عَرَاهُ كَابُوسٌ وَهُوَ مُسْتَغْرِقٌ فِي نَوْمِهِ"" : أَيْ مَا يَسْتَوْلِي عَلَى الإِنْسَانِ فِي نَوْمِهِ وَيُفْقِدُهُ القُدْرَةَ عَلَى الْحَرَكَةِ، وَيُطْلَقُ عَلَيْهِ أَيْضاً جَاثُومٌ. 2.""مَا هَذَا الكَابُوسُ"" : مَا هَذَا الْجَوُّ الْخَانِقُ ""بَدَتْ لَهُ الأيَّامُ الْمَاضِيَةُ مُجَرَّدَ كَابُوسٍ اِنْتَهَى"". (غسان كنفاني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13905, 'كَوَابِيسُ', 'كوابيس', 'جامد', '', 'كوابيس', 'كبس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13906, 'كَبِيسَةٌ', 'كبيسة', 'جامد', 'كبس', 'كبيسة', 'كبسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"كَبِيسَةٌ-كَبِيسَةٌ [ك ب س]. ""السَّنَةُ الكَبِيسَةُ"" : أَيِ السَّنَةُ الَّتِي يَزِيدُ فِيهَا يَوْمٌ عَلَى شَهْرِ شُبَّاطَ (فبراير) فَيَصِيرُ 29 يَوْماً، وَذَلِكَ مَرَّةً فِي كُلِّ أَرْبَعِ سَنَوَاتٍ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13907, 'كُبْسٌ', 'كبس', 'جامد', '', 'كبس', 'كبس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": سِلْكٌ مَعْدِنِيٌّ قَابِلٌ لِلانْصِهَارِ يَكُونُ عَلَى مَجْرَى تَيَّارٍ كَهْرَبَائِيٍّ، يَذُوبُ إِذَا زَادَ التَّيَّارُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13908, 'كَبْسُولٌ', 'كبسول', 'جامد', '', 'كبسول', 'كبسل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1. : غِطَاءٌ رَأْسِيٌّ مِنَ الْمَعْدِنِ أَوْ نَحْوِهِ يُغَطِّي عُنُقَ القِنِّينَةِ، وَيُسْتَعْمَلُ لِفَتْحِهَا. 2.""كَبْسُولُ بُنْدُقِيَّةٍ"" : آلَةٌ رَأْسِيَّةٌ تُسْتَخْدَمُ لإِطْلاَقِ نَارِ البُنْدُقِيَّةِ وَنَحْوِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13909, 'كَبْشَةٌ', 'كبشة', 'جامد', 'كبش', 'كبشة', 'كبشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"كَبْشَةٌ-كَبْشَةٌ [ك ب ش]. : مَا يُغْرَفُ بِهِ الطَّعَامُ مِنَ القِدْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13910, 'كَبْشٌ', 'كبش', 'جامد', '', 'كبش', 'كبش', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَكْبَاشٌ:كِبَاشٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَكْبَاشٌ،كِبَاشٌ. 1.(حو).: فَحْلُ الضَّـأْنِ. 2.""وَلَدٌ كَبْشٌ"" : تَابِعٌ، خَاضِعٌ دُونَ إِرَادَةٍ. ""إِنَّهُمْ كَالقَطِيعِ يَسِيرُونَ وَرَاءَ الكَبْشِ الأَوَّلِ"". (ع. منيف). 3.""كَبْشُ الفِدَاءِ"": مَا يُضَحَّى بِهِ فِي سَبِيلِ نَجاةِ غَيْرِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13911, 'أَكْبَاشٌ', 'أكباش', 'جامد', '', 'ءكباش', 'كبش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13912, 'كِبَاشٌ', 'كباش', 'جامد', '', 'كباش', 'كبش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13913, 'كَابُولٌ', 'كابول', 'جامد', 'كبل', 'كابول', 'كبل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَابُولٌ-كَابُولٌ [ك ب ل]. ""رَصَدَ الصَّائِدُ كَابُولاً"" : مِصْيَدَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13914, 'كَتَّانٌ', 'كتان', 'جامد', '', 'كتان', 'كتن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"كَتَّانٌ-كَتَّانٌ (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الكَتَّانِيَّاتِ، لَهُ زَهْرٌ أَزْرَقُ وَسَاقٌ طَوِيلَةٌ، تُنْسَجُ مِنْ أَلْيَافِهِ الأَثْوَابُ، وَيُعْتَصَرُ مِنْ بِزْرِهِ زَيْتٌ لِلْمَصَابِيحِ يُسْتَضَاءُ بِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13915, 'كُتَّابٌ', 'كتاب', 'جامد', 'كتب', 'كتاب', 'كتب', '', '', '', 'مفرد', 'DnN', '', '', '"كَتَاتِيبُ"', '', 'R', '', '', '', '', '', '', '". ""يَتَعَلَّمُ فِي الكُتَّابِ"" : مَوْضِعُ التَّعْلِيمِ الأَوَّلِيِّ، وَيُطْلَقُ خَاصَّةً عَلَى مَدَارِسِ تَعْلِيمِ القُرْآنِ وَتَحْفِيظِهِ."', '');
