INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13921, 'مَكْتَبَةٌ', 'مكتبة', 'جامد', 'كتب', 'مكتبة', 'مكتبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""أَخَذَ كِتَاباً مِنَ الْمَكْتَبَةِ"" : مَكَانُ وَضْعِ الكُتُبِ فِي الْمَنْزِلِ وغَيْرِهِ. 2. ""اِشْتَرَى كُتُباً مِنَ الْمَكْتَبَةِ"" : مَكَانُ بَيْعِ الكُتُبِ. 3. ""اِسْتَعَارَ كِتَاباً مِنَ الْمَكْتَبَةِ"" : بِنَايَةٌ مُخَصَّصَةٌ لِقُرَّاءِ الكُتُبِ، وهِي لِلْقِرَاءةِ والْمُطَالَعَةِ والاسْتِعَارَةِ، وَتُطْلَقُ عَلَيْهَا أَسْمَاءٌ مُخْتَلِفَةٌ، فِي الْمَغْرِبِ تُعْرَفُ بِالخِزَانَةِ العَامَّةِ، وفِي الجَزَائِرِ بِالْمَكْتَبَةِ الوَطَنِيَّةِ، وفِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13922, 'مَكْتَبٌ', 'مكتب', 'جامد', 'كتب', 'مكتب', 'مكتب', '', '', '', 'مفرد', 'DnN', '', '', '"مَكَاتِبُ"', '', 'R', '', '', '', '', '', '', '". 1. ""جَلَسَ يَكْتُبُ عَلَى الْمَكْتَبِ"" : طَاوِلَةٌ يُكْتَبُ عَلَيْهَا. 2. ""بَقِي فِي الْمَكْتَبِ يَقْرَأُ ويَكْتُبُ"" : الْحُجْرَةُ الَّتِي تَضُمُّ الْمَكْتَبَ. 3. ""مَكْتَبُ الْمُوَظَّفِ"" : الْمَكَانُ الَّذِي يَعْمَلُ فِيهِ. 4. ""مَكْتَبُ البَرِيدِ"" : إِدَارَةُ البَرِيدِ."', '');
