INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13943, 'كَادِمَةٌ', 'كادمة', 'جامد', 'كدم', 'كادمة', 'كدمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"كَادِمَةٌ - [ك د م]. : مِجَزٌّ آلِيٌّ يُسْتَعْمَلُ لِقَطْعِ الأَعْشَابِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13944, 'كُدْيَةٌ', 'كدية', 'جامد', 'كدي', 'كدية', 'كدة', '', '', '', 'مفرد', 'DnN', '', '', '"كُدًى"', '', '', '', '', '', '', '', '', '". 1.""صَعِدَ الكُدْيَةَ"" : الأَرْضُ الْمُرْتَفِعَةُ، وَتُطْلَقُ عَلَى الأَرْضِ الصَّلْبَةِ الغَلِيظَةِ . 2.""يُعَانِي مِنَ الكُدْيَةِ"" : مِنْ شِدَّةِ الدَّهْر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13945, 'كُدًى', 'كدى', 'جامد', '', 'كدى', 'كد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13946, 'أُكْذُوبَةٌ', 'أكذوبة', 'جامد', 'كذب', 'ءكذوبة', 'كذبة', '', '', '', 'مفرد', 'DnN', '', '', '"أكَاذِيبُ"', '', 'R', '', '', '', '', '', '', '". 1. ""هُوَ لاَ يَنْشُرُ إلاَّ الأكَاذِيبَ"" : الأَخْبَارُ الْمُخْتَلَقَةُ غَيْرُ الصَّحِيحَةِ. 2.""لاَ تُصَدِّقْ! إِنَّهَا أُكْذُوبَةٌ"" : إِشَاعَةٌ، بُهْتَانٌ، زَيْفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13947, 'أكَاذِيبُ', 'أكاذيب', 'جامد', '', 'ءكاذيب', 'كذب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13948, 'كُرَّاثٌ', 'كراث', 'جامد', '', 'كراث', 'كرث', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"كُرَّاثٌ-كُرَّاثٌ، ةٌ (نب). : بَقْلٌ زِرَاعِيٌّ مِنْ فَصِيلَةِ الزَّنْبَقِيَّاتِ، طَوِيلٌ أَبْيَضُ الرَّأْسِ، شَبِيهٌ بِالبَصَلِ، أَخْضَرُ الأَوْرَاقِ، تُؤْكَلُ سُوقُهُ مَطْبُوخَةً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13949, 'كِرَازَةٌ', 'كرازة', 'جامد', '', 'كرازة', 'كرزة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '": الوَعْظُ بِالتَّعَالِيمِ الْمَسِيحِيَّةِ وَالتَّبْشِيرُ بِها."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13950, 'كُرَّاسٌ', 'كراس', 'جامد', '', 'كراس', 'كرس', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '":كَرَارِيسُ"', '', 'R', '', '', '', '', '', '', '"ج: كَرَارِيسُ، كُرَّاسَاتٌ. 1.""يُسَجِّلُ أَفْكَارَهُ فِي كُرَّاسٍ"" : فِي دَفْتَرٍ، أَيْ فِي مَجْمُوِع أَوْرَاقٍ. 2.""كُرَّاسَةٌ مِنْ كِتَابٍ"" : الجُزْءُ مِنَ الكِتَابِ، مَلْزَمَةٌ، فَصْلَةٌ، مُسْتَلَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13951, 'كَرَارِيسُ', 'كراريس', 'جامد', '', 'كراريس', 'كررس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13952, 'كُرَاعٌ', 'كراع', 'جامد', '', 'كراع', 'كرع', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَكْرُعٌ:أَكَارِعُ"', '', 'R', '', '', '', '', '', '', '"ج: أَكْرُعٌ، أَكَارِعُ. (تش). 1.""كُرَاعُ الإِنْسَانِ"": مَادُونَ الرُّكْبَةِ إِلَى الكَعْبِ. 2.""كُرَاعُ البَقَرِ أَوِ الغَنَمِ..."" : مُسْتَدَقُّ السَّاقِ العَارِي مِنَ اللَّحْمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13953, 'أَكْرُعٌ', 'أكرع', 'جامد', '', 'ءكرع', 'كرع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
