INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13957, 'كُرْبَةٌ', 'كربة', 'جامد', '', 'كربة', 'كربة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"كُرَبٌ"', '', 'R', '', '', '', '', '', '', '"ج: كُرَبٌ. ""كَانَتْ كُرْبَتُهُ شَدِيدَةً"" : حُزْنُهُ، كَآبَتُهُ. ""فَرَّجَ اللَّهُ كُرْبَتَهُ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13958, 'كُرَبٌ', 'كرب', 'جامد', '', 'كرب', 'كرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13959, 'كَرْبُونٌ', 'كربون', 'جامد', '', 'كربون', 'كربن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"كَرْبُونٌ-كَرْبُونٌ (كيما). : جِسْمٌ بَسِيطٌ وَزْنُهُ الذَّرِّيُّ: 12', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13960, 'كَرْبُونَاتٌ', 'كربونات', 'جامد', '', 'كربونات', 'كربنت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"كَرْبُونَاتٌ-كَرْبُونَاتٌ (كيما). : مَسْحُوقٌ أَبْيَضُ أَمْلاَحُ حِمْضِ الكَرْبُونِيكْ وَهِيَ عَلَى نَوْعَيْنِ: "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13961, 'مَكْرَجٌ', 'مكرج', 'جامد', 'كرج', 'مكرج', 'مكرج', '', '', '', 'مفرد', 'DnN', '', '', '"مَكَارِجُ"', '', 'R', '', '', '', '', '', '', '". : مَكَانٌ لِتَسْلِيَةِ الأَطْفَالِ بِالأَلْعَابِ البَهْلَوَانِيَّةِ، ورُكُوبِ السَّيَّارَاتِ الصَّغِيرَةِ الآلِيَّةِ ومَا شَابَهَ ذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13962, 'مَكَارِجُ', 'مكارج', 'جامد', '', 'مكارج', 'مكرج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13963, 'كَرْدِينَال', 'كردينال', 'جامد', '', 'كردينال', 'كردنل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"كَرَادِلَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: كَرَادِلَةٌ.: أَحَدُ أَحْبَارِ الكَنِيسَةِ الكَاثُولِيكِيَّةِ، الَّذِينَ يُؤَلِّفُونَ الجَمْعَ الْمُقَدَّسَ، وَبَعْدَ مَوْتِ البَابَا يَجْتَمِعُونَ لانْتِخَابِ البَابَا الجَدِيدِ ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13964, 'كَرَادِلَةٌ', 'كرادلة', 'جامد', '', 'كرادلة', 'كردلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13965, 'مِكَرٌّ', 'مكر', 'جامد', 'كرر', 'مكر', 'مكر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَكْرٌ-مَكْرٌ [م ك ر] (مص. مَكَرَ). ""كَانَ مَكْرُهُ شَدِيداً"" : خِدَاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13966, 'كُرْزٌ', 'كرز', 'جامد', 'كرز', 'كرز', 'كرز', '', '', '', 'مفرد', 'DnN', '', '', '"أَكْرَازٌ"', '', 'R', '', '', '', '', '', '', '". 1.""كُرْزُ الرَّاعِي"" : وِعَـاءٌ مِنْ صُوفٍ أَوْ شَعَرٍ يَضَعُ فِيهِ الرَّاعِي حَاجَاتِهِ. 2. : كِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13967, 'أَكْرَازٌ', 'أكراز', 'جامد', '', 'ءكراز', 'كرز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13968, 'مَكْرَزَةٌ', 'مكرزة', 'جامد', 'كرز', 'مكرزة', 'مكرزة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَكْرَزَةٌ-مَكْرَزَةٌ [ك ر ز]. : مَوْضِعُ الكَرَزِ، حَقْلُهُ، بِناؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13969, 'كَرَزٌ', 'كرز', 'جامد', '', 'كرز', 'كرز', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"(نب). : شَجَرٌ مِنْ فَصِيلَةِ الوَرْدِيَّاتِ، يُعْطِي ثِمَاراً كَالخَوْخِ لَكِنَّهُ أَصْغَرُ مِنْهُ، أَحْمَرُ اللَّوْنِ، يُؤْكَلُ طَرِيّاً وَيُتَّخَذُ فِي تَحْضِـير"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13970, 'كُرْسِيٌّ', 'كرسي', 'جامد', '', 'كرسي', 'كرس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"كَرَاسِيُّ"', '', '', '', '', '', '', '', '', '"ج: كَرَاسِيُّ. 1.""جَلَسَ عَلَى الكُرْسِيِّ"" : مَـايُقْعَدُ عَلَيْهِ. 2.""اِسْتَلْقَى عَلَى الكُرْسِيِّ"" : السَّرِيرُ. 3.""تَرَبَّعَ عَلَى كُرْسِيِّ الْمُلْكِ"" : عَلَى العَرْش"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13971, 'كَرَاسِيُّ', 'كراسي', 'جامد', '', 'كراسي', 'كرس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13972, 'كَرِشٌ', 'كرش', 'جامد', 'كرش', 'كرش', 'كرش', '', '', '', 'مفرد', 'DnN', '', '', '"كُرُوشٌ"', '', 'R', '', '', '', '', '', '', '".: مَعِدَةُ كُلِّ حَيَوَانٍ ذِي ظِلْفٍ أَوْ خُفٍّ أَوْ مُجْتَرِّ، وَهُوَ بِمَنْزِلَةِ الْمَعِدَةِ لِلإِنْسَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13973, 'كُرُوشٌ', 'كروش', 'جامد', '', 'كروش', 'كرش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13974, 'كِرْشٌ', 'كرش', 'جامد', '', 'كرش', 'كرش', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَكْرَاشٌ:كُرُوشٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: أَكْرَاشٌ، كُرُوشٌ. (نب). : نَبَاتٌ عُشْبِيٌّ أَمْلَسُ، مِنْ فَصِيلَةِ السُّعْدِيَّاتِ، لَهُ سِيقَانٌ قَائِمَةٌ وَأَصْلٌ غَلِيظٌ، تُصْنَعُ مِنْهُ الْحُصْرُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13975, 'أَكْرَاشٌ', 'أكراش', 'جامد', '', 'ءكراش', 'كرش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
