INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13977, 'كَارِثَةٌ', 'كارثة', 'جامد', 'كرث', 'كارثة', 'كرثة', '', '', '', 'مفرد', 'DnN', '', '', '"كَوَارِثُ"', '', 'R', '', '', '', '', '', '', '". ""أَحْدَثَ الزِّلْزَالُ خَرَاباً، إِنَّهَا كَارِثَةٌ"" : مُصِيبَةٌ، آفَةٌ، نَكْبَةٌ. ""يَعْرِفُ العَالَمُ مِنْ حِينٍ لآخَرَ كَوَارِثَ طَبِيعِيَّةً""."', '');
