INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13979, 'كَرَفْسٌ', 'كرفس', 'جامد', '', 'كرفس', 'كرفس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"كَرَفْسٌ-كَرَفْسٌ (نب).: بَقْلٌ مِنْ فَصِيلَةِ الْخَيْمِيَّاتِ، لَهُ دِرْنَاتٌ غَلِيظَةٌ، يُؤْكَلُ نَيِّئاً وَمَطْبُوخاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13980, 'كَرَّاكَةٌ', 'كراكة', 'جامد', 'كرك', 'كراكة', 'كركة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"كَرَّاكَةٌ-كَرَّاكَةٌ [ك ر ك]. : آلَةٌ تَجْمَعُ مَا يَرْسُبُ مِنْ رَمْلٍ وَطِينٍ فِي القَنَوَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13981, 'كَرْكَدَنٌّ', 'كركدن', 'جامد', '', 'كركدن', 'كركدن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"كَرْكَدَنٌّ-كَرْكَدَنٌّ (حو). : حَيَوَانٌ مِنْ رُتْبَةِ وَتَرِيَّةِ الأَظْـلاَفِ، ضَخْمُ الجُثَّةِ، قَصِيرُ القَوَائِمِ، غَلِيظُ الجِلْدِ، يَتَمَي"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13982, 'كَرْكُوزٌ', 'كركوز', 'جامد', '', 'كركوز', 'كركز', '', '', '', 'جمع تكسير', 'DnN', '', '', '"كَرَاكِيزُ"', '', 'R', '', '', '', '', '', '', '"ج: كَرَاكِيزُ. : الدُّمَى الْمُتَحَرِّكَةُ الَّتِي تُسْتَخْدَمُ فِي "', ':لا جذر:لا مفرد');
