INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13990, 'كَرْمٌ', 'كرم', 'جامد', '', 'كرم', 'كرم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"كُرُومٌ"', '', 'R', '', '', '', '', '', '', '"ج: كُرُومٌ. (نب). : شُجَيْرَةٌ مِنْ فَصِيلَةِ الكَرْمِيَّاتِ، تُزْرَعُ مُنْذُ القِدَمِ، تُعْطِي عَنَاقِيدَ العِنَبِ، وَهُوَ يُؤْكَلُ فَاكِهَةً وَيُجَفَّفُ لِيُصْنَعَ مِنْهُ الزَّبِيبُ، وَعَصِيرُهُ يُخَمَّرُ وَيَصِيرُ خَمْراً. 2.""الكَرْمُ البَرِّيُّ"" : شُجَيْرَةٌ مُعَرَّشَةٌ لَهَا أَغْصَانٌ طَو"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13991, 'كُرُومٌ', 'كروم', 'جامد', '', 'كروم', 'كرم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13992, 'كَرْمَةٌ', 'كرمة', 'جامد', '', 'كرمة', 'كرمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"1. : الكَرْمُ لِلْعِنَبِ، وَهِيَ أَخَصُّ مِنْهُ. 2.""بِنْتُ الكَرْمَةِ"" : اِبْنَةُ الكَرْمِ، الْخَمْرَةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13993, 'كَرْمِيَّاتٌ', 'كرميات', 'جامد', '', 'كرميات', 'كرمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ، أَجْنَاسُهَا وَأَنْوَاعُهَا عَدِيدَةٌ، مِنْهَا الكَرْمَةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13994, 'كُرُنْبٌ', 'كرنب', 'جامد', '', 'كرنب', 'كرنب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"كُرُنْبٌ-كُرُنْبٌ (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الصَّلِيبِيَّاتِ، تَتَجَمَّعُ أَوْرَاقُهُ وَتَلْتَفُّ حَوْلَ بَعْضِهَا حَيْثُ تَبْقَى بَيْضَاءَ أَوْ حَمْرَاءَ. تُؤْكَلُ نَيِّئَةً أَوْ مَطْبُوخَةً، وَيُعْرَفُ بِالْمَلْفُوفِ أَوِ الْمُكَوَّرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13995, 'كُرُنْبِيَّةٌ', 'كرنبية', 'جامد', '', 'كرنبية', 'كرنبة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"كُرُنْبِيَّةٌ-كُرُنْبِيَّةٌ (طخ). : طَعَامٌ يُعْمَلُ مِنَ الكُرُنْبِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13996, 'كَرْهٌ', 'كره', 'جامد', 'كره', 'كره', 'كره', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كُرْهٌ-كُرْهٌ [ك ر هـ] (مص. كَرِهَ). 1.""نَفَّذَ أَمْراً عَلَى كُرْهٍ مِنْهُ"" : عَلَى الرَّغْمِ مِنِ إِرَادَتِهِ. 2.""عَمَلٌ كُرْهٌ"" : عَمَلٌ فِيهِ مَشَقَّةٌ وَتَعَبٌ.البقرة آية 216 كُتِبَ عَلَيْكُمُ القِتَالُ وَهُوَ كُرْهٌ لَكُمْ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13997, 'كَرِيهَةٌ', 'كريهة', 'جامد', 'كره', 'كريهة', 'كرهة', '', '', '', 'مفرد', 'DnN', '', '', '"كَرَائِهُ"', '', '', '', 'N', 'O', 'O', 'O', '', '". 1.""يَوْمُ الكَرِيهَةِ"" : يَوْمُ الْحَرْبِ وَالْمُصِيبَةِ. 2.""ذُو الكَرِيهَةِ"" : السَّيْفُ الْمَاضِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13998, 'كَرَائِهُ', 'كرائه', 'جامد', '', 'كراءه', 'كره', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(13999, 'مَكَارِهُ', 'مكاره', 'جامد', 'كره', 'مكاره', 'مكره', '', '', '', 'مفرد', '', '', '', '"مفردمَكْرَه"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""تَعَوَّدَ الصَّبْرَ عَلَى الْمَكَارِهِ"" : عَلَى كُلِّ مَا هُوَ مَكْرُوهٌ."', '');
