INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14004, 'كَرَوَانٌ', 'كروان', 'جامد', 'كرو', 'كروان', 'كرن', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"كَرَاوِينُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"(حو).: طَائِرٌ مِـنْ فَصِيلَةِ الدَّجَاجِيَّاتِ، مِنْ رُتْبَةِ طَوِيلاَتِ السَّاقِ، أَغْبَرُ اللَّوْنِ، لَهُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14005, 'كَرَاوِينُ', 'كراوين', 'جامد', '', 'كراوين', 'كرن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14006, 'كُرَيَّاتٌ', 'كريات', 'جامد', 'كرو', 'كريات', 'كرت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"كُرَيَّاتٌ-كُرَيَّاتٌ [ك ر و]. 1.""الكُرَيَّاتُ الْحُمْرُ"" : خَلِيَّةُ الدَّمِ الأَحْمَرِ، وَيَتَكَوَّنُ دَاخِلَ النَّقِيِّ الأَحْمَرِ، تَتَحَدَّدُ وَظِيفَتُها في نَقْلِ الأُكْسِجينِ مِنَ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14007, 'كُرُومٌ', 'كروم', 'جامد', '', 'كروم', 'كرم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"كُرُومٌ-كُرُومٌ (كيما). : مَعْدِنٌ رَمَادِيُّ اللَّوْنِ فُولاذِيٌّ، صَلْبٌ، صَعْبُ الانْصِهَارِ، ثِقْلُهُ النَّوْعِيُّ مِنْ 6 إِلَى 6', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14008, 'كُرُومُوزُوم', 'كروموزوم', 'جامد', '', 'كروموزوم', 'كرمزم', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. : مَادَّةٌ جُرْمِيَّةٌ شَكْلِيَّةٌ نَوَوِيَّةٌ مَعْدُودَةٌ، تَكُونُ فِي نَوَاةِ الْخَلِيَّةِ، وَعَدَدُ الكُرُومُوزُومَاتِ نَوْعِيٌّ لاَ يَتَغَيَّرُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14009, 'كُرُومِيت', 'كروميت', 'جامد', '', 'كروميت', 'كرمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": مَعْدِنٌ مُكَوَّنٌ مِنْ عَنَاصِرِ الْحَدِيدِ وَالكُرُومِ وَالأُكْسِجِينِ، يُوجَدُ فِي الطَّبِيعَةِ عَلَى هَيْئَةِ كُتَلٍ تُعْتَبَرُ خَاماً لِلْكُرُومِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14010, 'كَرَوْيَا', 'كرويا', 'جامد', '', 'كرويا', 'كر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '"(نب). : نَبَاتٌ مِنْ فَصِيلَةِ الخَيْمِيَّاتِ، مُعَطَّرٌ، بَذْرَتهُ مِنَ التَّوَابِلِ، كَرَوْيَاء."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14011, 'كِرَاءٌ', 'كراء', 'جامد', 'كري', 'كراء', 'كر', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"كِرَاءٌ-كِرَاءٌ [ك ر ي]. ""كِرَاءُ البَيْتِ"" : إِيجَارُهُ. ""ثَمَنُ الكِرَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14012, 'كَارِيَةٌ', 'كارية', 'جامد', 'كرى', 'كارية', 'كرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"كَارِيَةٌ-كَارِيَةٌ [ك ر ى]. : آلَةٌ زِرَاعِيَّةٌ تُقْلَبُ بِهَا الأَرْضُ لِتَهْيِئَتِهَا لِلزِّرَاعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14013, 'كُرَيَّةٌ', 'كرية', 'جامد', '', 'كرية', 'كرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"ج: ـات. (تَصْغيرُ كُرَة). : كُرَةٌ صَغِيرَةٌ مِنْ حَجَرٍ أَوْ مَعْدِنٍ أَوْ زُجَاجٍ يَلْعَبُ بِهَا الأَطْفَالُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14014, 'كَرِيكٌ', 'كريك', 'جامد', '', 'كريك', 'كرك', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1.""كَرِيكُ الخَبَّازِ"" : الْخَشَبَةُ الَّتِي يَدْفَعُ بِهَا الخَبَّازُ الخُبْزَ دَاخِلَ الفُرْنِ وَيَجْذِبُهُ بِهَا. 2. : أَدَاةٌ لِنَقْلِ التُّرَابِ أَوِ الْحَفْرِ الْخَفِيفِ، ذَاتُ خَشَبَةٍ طَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14015, 'كُزْبَرَةٌ', 'كزبرة', 'جامد', '', 'كزبرة', 'كزبرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"كُزْبَرَةٌ-كُزْبَرَةٌ، كُزْبُرَةٌ (نب). : بَقْلَةٌ مِنْ فَصِيلَةِ الخَيْمِيَّاتِ، زِرَاعِيَّةٌ حَوْلِيَّةٌ، تُ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14016, 'كِسْبَةٌ', 'كسبة', 'جامد', 'كسب', 'كسبة', 'كسبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"كِسْبَةٌ - [ك س ب]. ""يَعِيشُ مِنْ كِسْبَتِهِ"" : أَيْ مِمَّا اكْتُسِبَ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14017, 'مَكْسَبٌ', 'مكسب', 'جامد', 'كسب', 'مكسب', 'مكسب', '', '', '', 'مفرد', 'DnN', '', '', '"مَكَاسِبُ"', '', 'R', '', '', '', '', '', '', '". ""حَصَلَ عَلَى مَكْسَبٍ كَبِيرٍ"" : عَلَى رِبْحٍ، فَائِدَةٍ. ""مَكَاسِبُهُ كَثِيرَةٌ مِنْ عَمَلِهِ وَجُهْدِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14018, 'مَكَاسِبُ', 'مكاسب', 'جامد', '', 'مكاسب', 'مكسب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14019, 'كَسْتَنَاءُ', 'كستناء', 'جامد', '', 'كستناء', 'كستن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rz', '', 'N', 'O', 'O', 'O', '', '"1. : ثَمَرَةُ الكَسْتَنَةِ مِنْ فَصِيلَةِ البَلُّوطِيَّاتِ، وَهِيَ كَثِيرَةُ النَّشَاءِ تَحْتَوِي عَلَى غِلاَفٍ أَسْمَرَ قَا"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14020, 'كَسْتَنَةٌ', 'كستنة', 'جامد', '', 'كستنة', 'كستنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"(نب). : شَجَرٌ مِنْ فَصِيلَةِ البَلُّوطِيَّاتِ، يُعَمِّرُ قُرُو"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14021, 'كُسَاحَةٌ', 'كساحة', 'جامد', 'كسح', 'كساحة', 'كسحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"كُسَاحَةٌ - [ك س ح]. ""كُسَاحَةُ الأَزْبَالِ"" : كُنَاسَتُهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14022, 'كُسَاحٌ', 'كساح', 'جامد', 'كسح', 'كساح', 'كسح', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كُسَاحٌ-كُسَاحٌ [ك س ح]. ""كُسَاحُ الأَطْفَالِ"" : شَلَلُ الأَ"', '');
