INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14024, 'كَرًى', 'كرى', 'جامد', 'كري', 'كرى', 'كر', '', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"كَرىً-كَرىً [ك ر ي]. ""غَالَبَهُ الكَرَى"" : النُّعَاسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14025, 'كَسَّارَةٌ', 'كسارة', 'جامد', 'كسر', 'كسارة', 'كسرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"كَسَّارَةٌ-كَسَّارَةٌ [ك س ر]. 1.""كَسَّارَةُ الجَوْزِ"" : أَدَاةٌ يُكَسَّرُ بِهَا الجَوْزُ وَالبُنْدُقُ وَاللَّوْزُ. 2.""كَسَّارَةُ الحِجَارَةِ"" : أَدَاةٌ مَعْدِنِيَّةٌ تُسْتَخْدَمُ لِكَسْرِ الحِجَارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14026, 'كُسَارَةٌ', 'كسارة', 'جامد', 'كسر', 'كسارة', 'كسرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"كُسَارَةٌ-كُسَارَةٌ [ك س ر]. ""كُسَارَةُ الْحَطَبِ"" : مَا تَكَسَّرَ مِنْهُ، أَيْ دِقَاقُهُ الْمُكَسَّرَةُ. ""كُسَارَةُ الزُّجَاجِ"" ""كُسَارَةُ الخُبْزِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14027, 'كِسْرَةٌ', 'كسرة', 'جامد', 'كسر', 'كسرة', 'كسرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":كِسَرٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَعْطَاهُ كِسْرَةَ خُبْزٍ"" : القِطْعَةُ مِنَ الخُبْزِ الْمَكْسُورِ. ""طَعَامِي: الكِسْرَةُ وَالمَاءُ وَبَعْضُ التَّمَرَاتِ اليَابِسَةِ"". (أمل دنقل). 2.""تَحَوَّلَ الزُّجَاجُ إِلَى كَسَرَاتٍ"" : إِلَى قِطَعٍ مُكَسَّرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14028, 'كِسَرٌ', 'كسر', 'جامد', '', 'كسر', 'كسر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14029, 'كِسْرٌ', 'كسر', 'جامد', 'كسر', 'كسر', 'كسر', '', '', '', 'مفرد', 'DnN', '', '', '"أَكْسَارٌ:كُسُورٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""كِسْرُ البَيْتِ"": جَانِبُهُ. 2.""كِسْرُ الضَّيْعَةِ"" : نَاحِيَتُهَا، وَنَاحِيَةُ كُلِّ شَيْءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14030, 'أَكْسَارٌ', 'أكسار', 'جامد', '', 'ءكسار', 'كسر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14031, 'كُسُورٌ', 'كسور', 'جامد', '', 'كسور', 'كسر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14032, 'كُسُورٌ', 'كسور', 'جامد', 'كسر', 'كسور', 'كسر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"كُسُورٌ-كُسُورٌ [ك س ر]. ""كُسُورُ الأَوْدِيَةِ"" : شِعَابُهَا، مُنْعَطَفَاتُهَا، مُنْحَدَرَاتُهَا. (لاَ وَاحِدَ لَهَا مِنْ لَفْظِهَا بِهَذَا الْمَعْنَى)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14033, 'كَوَاسِرُ', 'كواسر', 'جامد', 'كسر', 'كواسر', 'كسر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"كَوَاسِرُ-كَوَاسِرُ [ك س ر]. : رُتْبَةٌ مِنَ الطَّيْرِ، وَتُعْرَفُ بِالْجَوَارِحِ، وَمِنْهَا البُومُ وَالصُّقُورُ وَالنُّسُورُ وَالعِقْبَانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14034, 'مَكْسِرٌ', 'مكسر', 'جامد', 'كسر', 'مكسر', 'مكسر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَكْسِرٌ-مَكْسِرٌ [ك س ر]. 1. ""مَكْسِرُ اليَدِ"" : مَوْضِعُ الكَسْرِ بِهَا. 2. ""هُوَ طَيِّبُ الْمَكْسِرِ"" : الْمَحْمُودُ، صَاحِبُ خِبْرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14035, 'كَسْرٌ', 'كسر', 'جامد', '', 'كسر', 'كسر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": هُوَ كَسْرٌ بَسْطُهُ أَصْغَرُ مِنْ مَقَامِهِ. 1.""كَسْرٌ دَوْرِيٌّ"" : هُوَ كَسْرٌ يَتَكَرَّرُ فِيهِ بِاسْتِمْرَارٍ رَقْمٌ أَوْ مَجْمُوعَةُ أَرْقَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14036, 'كِسْرَى', 'كسرى', 'جامد', '', 'كسرى', 'كسر', '', '', '', 'جمع تكسير', '', '', '', '"أَكَاسِرَةٌ"', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"ج: أَكَاسِرَةٌ. : لَقَبٌ كَانَ يُطْلَقُ عَلَى كُلِّ مَلِكٍ مِنْ مُلُوكِ الفُرْسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14037, 'أَكَاسِرَةٌ', 'أكاسرة', 'جامد', '', 'ءكاسرة', 'كسرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14038, 'كَسْكَاسٌ', 'كسكاس', 'جامد', 'كسكس', 'كسكاس', 'كسكس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَسْكَاسٌ-كَسْكَاسٌ [ك س ك س]. 1.: إِنَاءٌ مِنْ مَعْدِنٍ أَوْ فَخَّارٍ، مُقَعَّرٌ ذُو ثُقَبٍ، يُوضَعُ فِيهِ الكُسْكُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14039, 'كُسْكُسٌ', 'كسكس', 'جامد', '', 'كسكس', 'كسكس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"(طخ). : طَعَامٌ يُحَضَّرُ مِنْ دَقِيقِ القَمْحِ وَالْمَاءِ فَيَصِيرُ حَبَّاتٍ دَقِيقَةً، يُنْضَجُ فِي"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14040, 'كِسَاءٌ', 'كساء', 'جامد', 'كسو', 'كساء', 'كس', '', '', '', 'مفرد', 'Dz', '', '', '"أَكْسِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '". ""غَطَّاهُ بِكِسَاءٍ"" : بِثَوْبٍ، بِغِطَاءٍ. ""يَشْت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14041, 'أَكْسِيَةٌ', 'أكسية', 'جامد', '', 'ءكسية', 'كسة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14042, 'كُسْوَةٌ', 'كسوة', 'جامد', 'كسو', 'كسوة', 'كسة', '', '', '', 'مفرد', 'DnN', '', '', '"كُسًا"', '', 'R', '', '', '', '', '', '', '". ""اِرْتَدَى كُسْوَةَ العِيدِ"" : لِبَاسَ العِيد"', '');
