INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14044, 'كُشْتُبَانٌ', 'كشتبان', 'جامد', '', 'كشتبان', 'كشتبن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"كَشَاتِبِينُ"', '', 'R', '', '', '', '', '', '', '"ج: كَشَاتِبِينُ. : قِمَعُ الخَيَّاطِ يُغَطِّي بِ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14045, 'كَشَاتِبِينُ', 'كشاتبين', 'جامد', '', 'كشاتبين', 'كشتبن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14046, 'مِكْشَطٌ', 'مكشط', 'جامد', 'كشط', 'مكشط', 'مكشط', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَكَاشِطُ"', '', 'R', '', '', '', '', '', '', '". ""مِكْشَطُ الْجُلُودِ"": أَدَاةٌ لِلْكَشْطِ وَالْحَكِّ، مِحَكٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14047, 'مَكَاشِطُ', 'مكاشط', 'جامد', '', 'مكاشط', 'مكشط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
