INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14049, 'أَكْشَاكٌ', 'أكشاك', 'جامد', '', 'ءكشاك', 'كشك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14050, 'كَشْكُولٌ', 'كشكول', 'جامد', '', 'كشكول', 'كشكل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"كَشَاكِيلُ"', '', 'R', '', '', '', '', '', '', '"ج: كَشَاكِيلُ. ""كَشْكُولُ الْمُتَسَوِّلِ"" : وِعَاءٌ يَجْمَعُ فِيهِ مَا يُتَصَدَّقُ بِهِ عَلَيْهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14051, 'كَشَاكِيلُ', 'كشاكيل', 'جامد', '', 'كشاكيل', 'كشكل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14052, 'كِظَامَةٌ', 'كظامة', 'جامد', '', 'كظامة', 'كظمة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"كَظَائِمُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: كَظَائِمُ 1. : قَنَاةٌ لِمَجْرَى الْمَاءِ وَغَيْرِهِ فِي بَاطِنِ الأَرْضِ. 2.""تَرْبِطُ بَيْنَ البِئْرَيْنِ كِظَامَةٌ"" : مَجْرىً مَائِيٌّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14053, 'كَظَائِمُ', 'كظائم', 'جامد', '', 'كظاءم', 'كظم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14054, 'كَظِيمَةٌ', 'كظيمة', 'جامد', 'كظم', 'كظيمة', 'كظمة', '', '', '', 'مفرد', 'DnN', '', '', '"كَظَائِمُ"', '', '', '', '', '', '', '', '', '". 1. : بِئْرٌ مُتَّصِلَةٌ بِبِئْـرٍ أُخْرَى وَبَيْنَهُمَا مَجْرىً فِي بَاطِنِ الأَرْضِ. 2.: وِعَاءٌ يُوضَعُ فِيهِ الزَّادُ. 3. : يُمْكِنُ أَنْ تُطْلَق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14055, 'كَظَائِمُ', 'كظائم', 'جامد', '', 'كظاءم', 'كظم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14056, 'كَعْبَةٌ', 'كعبة', 'جامد', 'كعب', 'كعبة', 'كعبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":كِعَابٌ"', '', 'R', '', '', '', '', '', '', '". 1.""شَيَّدَ كَعْبَةً"" : بَيْتاً مُرَبَّعَ الجَوَانِبِ. 2.""زَارَ الكَعْبَةَ الْمُكَرَّمَةَ"" : البَيْتَ الْحَرَامَ فِي مَكَّةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14057, 'كِعَابٌ', 'كعاب', 'جامد', '', 'كعاب', 'كعب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14058, 'كَعْبٌ', 'كعب', 'جامد', 'كعب', 'كعب', 'كعب', '', '', '', 'مفرد', 'DnN', '', '', '"كُعُوبٌ:كِعَابٌ"', '', 'R', '', '', '', '', '', '', '".: كُلُّ مَفْصِلٍ مِنَ العِظَامِ. 1.""كَعْبُ الرِّجْلِ"" : العَظْمُ البَارِزُ عِنْدَ مُلْتَقَى السَّاقِ وَالقَدَمِ. ""فِي كُلِّ قَدَمٍ كَعْبَانِ عَنْ يَمْنَتِهَا وَعَنْ يَسْرَتِهَا"". 2.""كَعْبُ القَصَبَةِ"" : العُقْدَةُ مَا بَيْنَ الأُنْبُوبَتَيْنِ. 3.""رَجُلٌ عَالِي الكَعْبِ"" : يُوصَفُ بِالشَّرَفِ وَالظَّفَرِ، عَكْسُهُ ""ك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14059, 'كُعُوبٌ', 'كعوب', 'جامد', '', 'كعوب', 'كعب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14060, 'كِعَابٌ', 'كعاب', 'جامد', '', 'كعاب', 'كعب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14061, 'كَعْكٌ', 'كعك', 'جامد', '', 'كعك', 'كعك', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"(طخ). : خُبْزٌ يُحَضَّرُ مِنَ الدَّقِيقِ واَلحَلِيبِ وَالسُّكَّرِ وَالسَّمِيدِ وَيُسَوَّى مُسْتَدِيرا أَوْ مُسْتَطِيلاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14062, 'كَفَاءةٌ', 'كفاءة', 'جامد', 'كفأ', 'كفاءة', 'كفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'Rz', '', '', '', '', '', '', '". 1.""لَهُ كَفَاءةٌ عِلْمِيَّةٌ"" : قُدْرَةٌ، مُؤَهِّلاَتٌ عِلْمِيَّةٌ. 2.""يَتَمَتَّعُ بِكَفَاءةٍ عَالِيَةٍ"" : بِقُدْرَةٍ عَالِيَةٍ عَلَى العَمَلِ، بِجَدَارَةٍ وَأَهْلِيَّةٍ. 3.""حَصَلَ عَلَى شَهَادَةِ الكَفَاءةِ"" : شَهَادَةُ دُرُوسٍ عِلْمِيَّةٍ أَوْ تَكْمِيلِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14063, 'كَفْتَةٌ', 'كفتة', 'جامد', '', 'كفتة', 'كفتة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"كَفْتَةٌ-كَفْتَةٌ (طبخ). : اللَّحْمُ الْمَفْرُومُ أَوِ الْمَدْقُوقُ تُتَّخَذُ مِنْهُ أَقْرَاصٌ وَأَصَابِعُ تُقْلَى أَوْ تُشْوَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14064, 'كَفَّارَةٌ', 'كفارة', 'جامد', 'كفر', 'كفارة', 'كفرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". ""كَفَّارَةُ اليَمِينِ"" : مَا يَسْتَغْفِرُ بِهِ الآثِمُ مِنْ صَدَقَةٍ أَوْ صَوْمٍ.المائدة آية 89 فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14065, 'كَافَّةٌ', 'كافة', 'جامد', 'كفف', 'كافة', 'كفة', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '"كَافَّةٌ-كَافَّةٌ [ك ف ف]. ""حَضَرَ النَّاسُ كَافَّةً"" : أَيْ كُلُّهُمْ وَتَكُونُ مَنْصُوبَةً عَلَى الْحَالِ لُزُوماً. التوبة آية 36وَقَاتِلُوا الْمُشْرِكِينَ كَافَّةً كَمَا يُقَاتِلُونَكُمْ كَافَّةً . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14066, 'كَفَافٌ', 'كفاف', 'جامد', 'كفف', 'كفاف', 'كفف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَفَافٌ-كَفَافٌ [ك ف ف]. 1.""الكَفَافُ مِنَ الرِّزْقِ"" : مَا كَفَى عَنِ النَّاسِ وَأَغْنَى. 2.""يَعِيشُ عَلَى الكَفَافِ وَالعَفَافِ"" : يَعِيشُ عَلَى قَدْرِ مَا يَمْلِكُ بِلاَ زِيَادَةٍ وَلاَ نُقْصَانٍ. ""يَعِيشُ كَفَافَ يَوْمِهِ"" ""حَيَاةُ كَفَافٍ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14067, 'كِفَافٌ', 'كفاف', 'جامد', 'كفف', 'كفاف', 'كفف', '', '', '', 'مفرد', 'DnN', '', '', '"أَكِفَّةٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""كِفَافُ الثَّوْبِ"" : ثَنْيُ حَاشِيَتِهِ. 2.""كِفَافُ الصُّورَةِ"" : مُحِيطُهَا. 3.""كِفَافُ الأُذُنِ"" : اِسْتِدَارَتُهَا. 4.""كِفَافُ السَّيْفِ"" : حَدُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14068, 'أَكِفَّةٌ', 'أكفة', 'جامد', '', 'ءكفة', 'كفة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14069, 'كَفَّةٌ', 'كفة', 'جامد', 'كفف', 'كفة', 'كفة', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَفَّةٌ-كَفَّةٌ [ك ف ف]. 1.""كَفَّةُ الْمِيزَانِ"" : الصَّحْنُ الدَّائِرِيُّ الَّذِي يُوزَنُبِهِ، وَلِلْمِيزَانِ كَفَّتَانِ. 2.""لَقِيتُهُ كَفَّةً كَفَّةً"" : أَيْ مُوَاجَهَةً. ""لَقِيتُهُ كَفَّةً عَنْ كَفَّةٍ أَوْ كَفَّةً لِكَفَّةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14070, 'كُفَّةٌ', 'كفة', 'جامد', 'كفف', 'كفة', 'كفة', '', '', '', 'مفرد', 'DnN', '', '', '"كُفَفٌ:كُفَافٌ"', '', 'R', '', '', '', '', '', '', '". 1.""كُفَّةُ النَّاسِ"": عَامَّتُهُمْ. 2.""كُفَّةُ الثَّوْبِ"" : جَانِبُهُ الأَعْلَى. 3.""كُفَّةُ الْمَائِدَةِ"" : حَاشِيَتُهَا. 4.""كُفَّةُ اللِّثَةِ"" : مَا انْحَدَرَ مِنْهَا. 5.""كُفَّةُ القَمِيصِ"": مَا اسْتَدَارَ حَوْلَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14071, 'كُفَفٌ', 'كفف', 'جامد', '', 'كفف', 'كف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14072, 'كُفَافٌ', 'كفاف', 'جامد', '', 'كفاف', 'كفف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14073, 'كِفَّةٌ', 'كفة', 'جامد', 'كفف', 'كفة', 'كفة', '', '', '', 'مفرد', 'DnN', '', '', '"كِفَفٌ:كِفَافٌ"', '', 'R', '', '', '', '', '', '', '". 1. : كُلُّ أَدَاةٍ مُسْتَدِيرَةٍ. 2.""كِفَّةُ الْمِيزَانِ"" : الصَّحْنُ الدَّائِرِيُّ الَّذِي يُوزَنُ بِهِ، وَلِلْمِيزَانِ كِفَّتَانِ. 3.""كِفَّةُ الدَّفِّ"" : عُودُهُ. 4.""كِفَّةُ الصَّائِدِ"" : مِصْيَدَتُهُ. 5.""الكِفَّةُ بِالكِفَّةِ"" : عِبَارَةٌ عَنِ الْمُسَاوَاةِ فِي الْمُوَازَنَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14074, 'كِفَفٌ', 'كفف', 'جامد', '', 'كفف', 'كف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14075, 'كِفَافٌ', 'كفاف', 'جامد', '', 'كفاف', 'كفف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14076, 'كَفَفٌ', 'كفف', 'جامد', 'كفف', 'كفف', 'كف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَفَفٌ-كَفَفٌ [ك ف ف]. 1.""يَعِيشُ عَلَى الكَفَفِ"" : عَلَى التَّسَوُّلِ. 2.""يَقْنَعُ بِكَفَفِ رِزْقِهِ"" : بِمِقْدَارِ حَاجَتِهِ، بِكَفَافِهِ. 3.""كَفَفُ الْوَشْمِ"" : دَارَاتٌ وَحَلَقَاتٌ تَكُونُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14077, 'كَفِّيَّاتٌ', 'كفيات', 'جامد', 'كفف', 'كفيات', 'كفت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"كَفِّيَّاتٌ-كَفِّيَّاتٌ [ك ف ف]. ""كَفِّيَّاتُ القَدَمِ"" : رُتْبَةٌ مِنَ الطُّيُورِ وَهِيَ أَرْبَعَةُ أَصْنَافٍ: أ. طَوِيلاَتُ الرِّيشِ. ب. شَامِلاَتُ الكُفُوفِ، مِنْهَا البَجَعُ. ح. صَفِيحِيَّاتُ الْمَنَاقِيرِ، مِنْهَا الوَزِّيَّاتُ وَالبَطِّيَّاتُ. د. عَدِيمَاتُ الرِّيشِ، مِنْهَا البِطْرِيقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14078, 'كَفَنٌ', 'كفن', 'جامد', 'كفن', 'كفن', 'كفن', '', '', '', 'مفرد', 'DnN', '', '', '"أَكْفَانٌ"', '', 'R', '', '', '', '', '', '', '". ""أَحْضَرُوا الكَفَنَ"" : لِبَاسَ الْمَيِّتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14079, 'أَكْفَانٌ', 'أكفان', 'جامد', '', 'ءكفان', 'كفن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14080, 'مُسْتَكِفَّاتٌ', 'مستكفات', 'جامد', 'كفف', 'مستكفات', 'مستكفت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُسْتَكِفَّاتٌ-مُسْتَكِفَّاتٌ [ك ف ف].: عُيُونٌ، لأَنَّهَا فِي كِفَفٍ، أَيْ نُقَرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14081, 'كِفْلٌ', 'كفل', 'جامد', 'كفل', 'كفل', 'كفل', '', '', '', 'مفرد', 'DnN', '', '', '"أَكْفَالٌ"', '', 'R', '', '', '', '', '', '', '". 1.""كِفْلُ الثَّوْرِ"" : قِطْعَةٌ مِنَ الثَّوْبِ تُوضَعُ عَلَى عُنُقِهِ. 2.""هُوَ كِفْلُهُ"" : مَثِيلُهُ، نَظِيرُهُ. 3.""رَجُلٌ كِفْلٌ"" : يُلْقِي نَفْسَهُ وَأَثْقَالَهُ عَلَى النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14082, 'أَكْفَالٌ', 'أكفال', 'جامد', '', 'ءكفال', 'كفل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14083, 'مَكْلأَةٌ', 'مكلأة', 'جامد', 'كلأ', 'مكلءة', 'مكلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَكْلأَةٌ-مَكْلأَةٌ [ك ل أ]. ""اِنْتَشَرَتِ الْمَاشِيَةُ فِي الْمَكْلأَةِ"" : الأَرْضُ الكَثِيرَةُ الكَلأِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14084, 'كُلاَّبٌ', 'كلاب', 'جامد', 'كلب', 'كلاب', 'كلب', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"كَلاَلِيبُ"', '', 'R', '', '', '', '', '', '', '". 1. : المِهْمَازُ، حَدِيدَةٌ الَّتِي عَلَى خُفِّ رَائِضِ الخَيْلِ أَوْ رَاكِبِهَا، يُهْمَزُ بِهَا جَنْبَا الفَرَسِ. 2. : حَدِيدَةٌ مُعَوَّجَةُ الرَّأْسِ يُنْتَشَلُ بِهَا الشَّيْءُ أَوْ يُعَلَّقُ. 3.""كُلاَّبَةُ الأَسْنَانِ"" : أَدَاةٌ تُخْلَعُ بِهَا الأَسْنَانُ. 4.""كَـلاَلِيبُ البَـازِيِّ"" : مَخَالِبُـهُ. 5.""كَلاَلِيبُ الشَّجَرِ"" : شَوْكُهُ. 6.""كَلاَلِيبُ النَّجَّارِ"" : آلاَتٌ تُقْلَعُ بِهَا الْمَسَامِيرُ وَغَيْرُهَا، وَهِيَ أَنْوَاعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14085, 'كَلاَلِيبُ', 'كلاليب', 'جامد', '', 'كلاليب', 'كللب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14086, 'كَلِبٌ', 'كلب', 'جامد', 'كلب', 'كلب', 'كلب', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"كَلِبٌ-كَلِبٌ، ةٌ [ك ل ب]. 1.""كَلْبٌ كَلِبٌ"" : كَلْبٌ مُصَابٌ بِدَاءِ الكَلَبِ. 2.""سَنَةٌ كَلِبَةٌ"" : مُجْدِبَةٌ. 3.""أَرْضٌ كَلِبَةٌ"" : قَاحِلَةٌ يَابِسَةٌ. 4.""دَهْرٌ كَلِبٌ"" : صَعْبٌ، سَيِّءٌ. 5.""وَجَدَهُ كَلِباً عَلَى أَمْوَالِهِ"" : طَامِعاً فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14087, 'كَلْبِيَّاتٌ', 'كلبيات', 'جامد', 'كلب', 'كلبيات', 'كلبت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"كَلْبِيَّاتٌ-كَلْبِيَّاتٌ [ك ل ب]. : فَصِيلَةُ الكِلاَبِ، وَهِيَ تَشْمُلُ الكَلْبَ وَالثَّعْلَبَ وَالذِّئْبَ وَابْنَ آوَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14088, 'مَكْلَبَةٌ', 'مكلبة', 'جامد', 'كلب', 'مكلبة', 'مكلبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَكْلَبَةٌ-مَكْلَبَةٌ [ك ل ب]. ""أَرْضٌ مَكْلَبَةٌ"" : كَثِيرَةُ الكِلاَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14089, 'كَلْبٌ', 'كلب', 'جامد', '', 'كلب', 'كلب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"كِلاَبٌ"', '', 'R', '', '', '', '', '', '', '"ج: كِلاَبٌ. (حو). : مِنْ فَصِيلَةِ الكَلْبِيَّاتِ، مِنَ الضَّوَارِي، يُوجَدُ مِنْهُ أَنْوَاعٌ كَثِيرَةٌ مُخْتَلِفَـةُ الطِّبَاعِ وَالْمُهِمَّاتِ. 1.""كَلْبُ الصَّيْدِ""،""كَلْبُ الْحُقُولِ""، ""كَلْبُ الرُّعَاةِ""، ""كَلْبُ الحِرَاسَةِ""، ""كَلْبٌ بُولِيسِيٌّ"". 2.""كَلْبُ الزَّلاَّقَاتِ"" :"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14090, 'كِلاَبٌ', 'كلاب', 'جامد', '', 'كلاب', 'كلب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14091, 'كَلْبَةٌ', 'كلبة', 'جامد', '', 'كلبة', 'كلبة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"مثنىكَلْبَتَانِ-كَلْبَتَانِ"', '', 'R', '', '', '', '', '', '', '"1. : أَدَاةٌ مِنْ حَدِيدٍ يَلْقُطُ بِهَا الْحَدَّادُ الْحَدِيدَ أَوِ الْجَمْرَ. 2. : أَدَاةٌ لِخَلْعِ الأَضْرَاسِ وَيُطْلَقُ عَلَيْهَا أَيْضاً الكُلاَّبَةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14092, 'كِلْسٌ', 'كلس', 'جامد', '', 'كلس', 'كلس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": مَادَّةٌ حَجَرِيَّةٌ تُشَكِّلُ الجُزْءَ الأَكْبَرَ مِنَ الأَحْجَارِ كَالرُّخَامِ و"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14093, 'كَلَسَةٌ', 'كلسة', 'جامد', '', 'كلسة', 'كلسة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. : الجَوْرَبُ القَصِيرُ الب"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14094, 'كَلْسُيُومٌ', 'كلسيوم', 'جامد', '', 'كلسيوم', 'كلسم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '"كَلْسُيُومٌ-كَلْسُيُومٌ (كيما). : فِلِزٌّ أَبْيَضُ اللَّوْنِ مُرَكَّبَاتُهُ الطَّبِيعِيَّةُ: الْحَجَرُ الكِلْسِي"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14095, 'تَكْلِفَةٌ', 'تكلفة', 'جامد', 'كلف', 'تكلفة', 'تكلفة', '', '', '', 'مفرد', 'DnN', '', '', '"تَكاليفُ"', '', 'R', '', '', '', '', '', '', '". 1.""تَكْلِفَةُ الحَياةِ"": مَشَقَّتُها.سَئِمْتُ تَكالِيفَ الحَياةِ وَمَنْ يَعِشْ*ثَمانِينَ حَوْلاً لاَ أَبا لَكَ يَسْأَمِ (زهير بن أبي سلمى). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14096, 'تَكاليفُ', 'تكاليف', 'جامد', '', 'تكاليف', 'تكلف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14097, 'كُلْفَةٌ', 'كلفة', 'جامد', 'كلف', 'كلفة', 'كلفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"كُلَفٌ"', '', 'R', '', '', '', '', '', '', '". 1.""صَارَ لَوْنُ وَجْهِهِ كُلْفَةً"" : لَوْنٌ مَا بَيْنَ السَّوَادِ وَالْحُمْرَةِ. 2.""كُلْفَةُ العَمَلِ"" : مَا يُنْفَقُ عَلَيْهِ م"', '');
