INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14099, 'إكْلِيلٌ', 'إكليل', 'جامد', 'كلل', 'ءكليل', 'إكلل', '', '', '', 'مفرد', 'DnN', '', '', '"أَكَالِيلُ"', '', 'R', '', '', '', '', '', '', '". 1.""إكْلِيلُ الْمَلِكِ"" : التَّاجُ. 2.""إكْلِيلُ الأَمِيرَةِ"" : عصَابَةٌ تُزَيَّنُ بِالجَوْهَرِ. 3.""قَدَّمَ لَهَا إكْلِيلاً مِنَ الوَرْدِ"" : بَاقَةً مِنَ الوَرْدِ عَلَى هَيْئَةِ تَاجٍ. 4.""الإكْلِيلُ عِنْدَ النَّصَارى"" : الزَّوَاجُ. 5.""إكْلِيلُ الجَبَلِ"" : نَباتٌ عُشْبِـيٌّ"', '');
