INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14103, 'كَلَلٌ', 'كلل', 'جامد', 'كلل', 'كلل', 'كل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَلَلٌ-كَلَلٌ [ك ل ل]. 1.""يَشَتَغِلُ وَيَعْمَلُ بِلاَ كَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14104, 'كُلِّيَّةٌ', 'كلية', 'جامد', 'كلل', 'كلية', 'كلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""اِلْتَحَقَ بِالكُلِّيَّةِ بَعْدَ حُصُولِهِ عَلَى البَكَالُورِيَا"" : مُؤَسَّسَةٌ عِلْمِيَّةٌ يُتَابِعُ فِيهَا الطَّالِبُ دِرَاسَتَهُ العُلْيَا حَسَبَ تَخَصُّصِهِ فِي عِلْمٍ مِنَ العُلُومِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14105, 'كَلاَمٌ', 'كلام', 'جامد', 'كلم', 'كلام', 'كلم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَلاَمٌ-كَلاَمٌ [ك ل م].1.""كَلاَمٌ مُهَذَّبٌ"" : قَوْلٌ، حَدِيثٌ، خِطَابٌ يَتَضَمَّنُ مَعْنىً. ""لاَ فَائِدَةَ مِنْ كَلاَمِهِ"" ""مِنْ آدَابِ الكَلاَمِ أَنْ لاَ يَتَجَاوَزَ الْمَرْءُ فِي مَدْحٍ وَلاَ يُسْرِفَ فِي ذَمٍّ"" ""كَلاَمٌ غَامِضٌ"" ""كَلاَمٌ وَضِيعٌ"" ""كَلاَمٌ جَمِيلٌ"".""وَتَعَطَّلَتْ لُغَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14106, 'كَلِمَةٌ', 'كلمة', 'جامد', 'كلم', 'كلمة', 'كلمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":كَلِمٌ"', '', 'R', '', '', '', '', '', '', '"كَلِمَةٌ-كَلِمَةٌ، (كِلْمَةٌ، كَلْمَةٌ) ج: كَلِمٌ، كَلِمَاتٌ. [ك ل م].: اللَّفْظَةُ، أَيْ مَجْمُوعَةٌ مِنَ الأَحْرُفِ الهِجَائِيَّةِ مُرَكَّبَةٌ تُفِيدُ مَعْنـىً، وَهِيَ: 1. اِسْمٌ يَدُلُّ عَلَى مَوْصُوفٍ: ""رَجُلٌ، أَسَدٌ""، أَوْ صِفَةٌ: ""أَحْمَرُ، مُفِيدٌ"". 2. فِعْلٌ يَدُلُّ عَلَى حَالَةٍ أَوْ حَدَثٍ: كَتَبْتُ، أَكْتُبُ، اُكْتُبْ. 3.""حَرْفٌ"" : هُوَ مَا يَدُلُّ مَعْنَاهُ بِإِضَافَتِهِ إِلَى الفِعْلِ أَوِالاسْمِ: لاَ، هَلْ، لَمْ. 4.""شُجَاعٌ بِالْمَعْنَىالصَّحِيحِ لِهَذِهِ الكَلِمَةِ"" : أَيْ بِكُلِّ مَاتَحْمِلُهُ هَذِهِ اللَّفْظَةُ مِنْ مَعْنـىً.5.""كَلِمَةُ اللَّهِ"" : حُكْمُهُ وَإِرَادَتُهُ.التوبة آية 40 وَكَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14107, 'كَلِمٌ', 'كلم', 'جامد', '', 'كلم', 'كلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
