INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14109, 'كَلْمٌ', 'كلم', 'جامد', 'كلم', 'كلم', 'كلم', '', '', '', 'مفرد', 'DnN', '', '', '"كُلُومٌ:كِلاَمٌ"', '', 'R', '', '', '', '', '', '', '". ""أُصِيبَ بِكَلْمٍ"" : بِجُرْحٍ. ""كَانَ كَلْمُهُ عَمِيقاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14110, 'كُلُومٌ', 'كلوم', 'جامد', '', 'كلوم', 'كلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
