INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14113, 'كُلُورٌ', 'كلور', 'جامد', '', 'كلور', 'كلر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كُلُورٌ-كُلُورٌ (كيما). : غَازٌ سَامٌّ أَصْفَرُ اللَّوْنِ يَمِيلُ إِلَى الخُضْرَةِ، ذُو رَائِحَةٍ خَانِقَةٍ، وَزْنُهُ الذَّرِّيُّ 35', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14114, 'كْلُورُوفُورَم', 'كلوروفورم', 'جامد', '', 'كلوروفورم', 'كلرفرم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": سَائِلٌ عَدِيمُ اللَّوْنِ، أَثِيرِيُّ الرَّائِحَةِ، يُسْتَعْمَلُ فِي الطِّبِّ مُبَنِّجاً لِتَخْدِيرِ الأَعْصَابِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14115, 'كُلْيَةٌ', 'كلية', 'جامد', 'كلي', 'كلية', 'كلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":كُلًى"', '', '', '', '', '', '', '', '', '". وَاحِدَةُ الكُلْيَتَيْنِ: وَهُمَا غُدَّتَانِ حَمْراوَانِ لاَزِقَتَانِ بِعَظْمِ الصَّلْبِ عِنْدَ الخَاصِرَتَيْنِ تَعْمَلاَنِ عَلَى إِفْرَازِ البَوْلِ مِنَ الدَّمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14116, 'كُلًى', 'كلى', 'جامد', '', 'كلى', 'كل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14117, 'كُلِّيَّاتٌ', 'كليات', 'جامد', '', 'كليات', 'كلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"كُلِّيَّاتٌ-كُلِّيَّاتٌ (فل). : كُلُّ مَا يُدْرَكُ بِالعَقْلِ وَالْمَنْطِقِ وَلاَ يَقَعُ تَحْتَ حُكْمِ الْحَوَاسِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14118, 'كِمٌّ', 'كم', 'جامد', '', 'كم', 'كم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَكِمَّةٌ:أَكْمَامٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: أَكِمَّةٌ، أَكْمَامٌ. ""كِمُّ الزَّهْرَةِ"" : غِلاَفُهَا الَّذِي يُحِيطُ بِهَا ثُمَّ يَنْشَقُّ عَنْهَا. ""كِمُّ الثَّمَرَةِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14119, 'أَكِمَّةٌ', 'أكمة', 'جامد', '', 'ءكمة', 'كمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
