INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14121, 'كَمْءٌ', 'كمء', 'جامد', 'كمأ', 'كمء', 'كم', '', '', '', 'مفرد', 'Dz', '', '', '"كَمْأَةٌ:أَكْمُؤٌ"', '', 'Rz', '', 'N', 'O', 'O', 'O', '', '". (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الكَمْئِيَّاتِ، يُشْبِهُ البَطَاطَا إِلاَّ أَنَّهُ رَخْوٌ، يُؤْكَلُ نَيِّئاً وَمَطْبُوخاً. (الكَمْأَةُ اسْمٌ لِلْجَمْعِ أَو هِيَ لِلْوَاحِدِ، والكَمْءُ لِلْجَمْعِ أَوْ هِيَ تَكُونُ وَاحِدَةً وجَمْعاً)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14122, 'كَمْأَةٌ', 'كمأة', 'جامد', '', 'كمءة', 'كمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14123, 'أَكْمُؤٌ', 'أكمؤ', 'جامد', '', 'ءكمء', 'كم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14124, 'كَلاَّسَةٌ', 'كلاسة', 'جامد', 'كلس', 'كلاسة', 'كلسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"كَلاَّسَةٌ-كَلاَّسَةٌ [ك ل س]. : الْمَعْمَلُ الَّذِي يُصْنَعُ فِيهِ الكِلْسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14125, 'كَمْئِيَّاتٌ', 'كمئيات', 'جامد', 'كمأ', 'كمءيات', 'كمت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"كَمْئِيَّاتٌ-كَمْئِيَّاتٌ [ك م أ]. : فَصِيلَةٌ نَبَاتِيَّةٌ، أَنْوَاعُهَا عَدِيدَةٌ، تَنْبُتُ تَحْتَ الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14126, 'مَكْمَأَةٌ', 'مكمأة', 'جامد', 'كمأ', 'مكمءة', 'مكمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَكْمَأَةٌ-مَكْمَأَةٌ [ك م أ]. : الأَرْضُ الَّتِي تَكْثُرُ بِهَا الكَمْأَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14127, 'كَمَانٌ', 'كمان', 'جامد', '', 'كمان', 'كمن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَمَانٌ-كَمَانٌ (مو). : آلَةٌ مِنَ الفَصِيلَةِ الوَتَرِيَّةِ، وَهِيَ مُنْحَدِرَةٌ مِنَ الرَّبَابِ،مُكَوَّنَةٌ مِنْ صُنْدُوقٍ خَشَبِيٍّ تُشَدُّ عَلَيْهِ أَرْبَعَةُ أَوْتَارٍ يَمُرُّ فَوْقَهَا قَوْسٌ، الكَمَنْجَةُ. ""عَازِفُ الكَمَانِ""."', ':لا جذر:لا مفرد');
