INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14129, 'كِمَادٌ', 'كماد', 'جامد', 'كمد', 'كماد', 'كمد', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". 1.""اِحْتَاجَ إِلَى كِمَادِ أَعْضَائِهِ"" : تَسْخِينِهَا بِقِطَعٍ مِنَ القُمَاشِ أَوْ نَحْوِهِ. 2.""وَضَعَ الكِمَادَ عَلَى ظَهْرِهِ"" : قِطْعَةٌ مِنَ القُمَاشِ تُبَلَّلُ فِي الْمَاءِ السَّاخِنِ وَتُوضَعُ عَلَى مَوْضِعِ الأَلَمِ فِي الجِسْمِ."', '');
