INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14220, 'كَوْكَبَةٌ', 'كوكبة', 'جامد', 'كوكب', 'كوكبة', 'ككبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"كَوْكَبَةٌ-كَوْكَبَةٌ [ك و ك ب]. 1.""اِلْتَحَقَتْ بِهِمْ كَوْكَبَةٌ مِنَ الفُرْسَانِ"" : جَمَاعَةٌ. ""كَوْكَبَةٌ مِنَ الضُّبَّاطِ"". 2.""كَوْكَبَةُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14221, 'كَوْكَبٌ', 'كوكب', 'جامد', 'كوكب', 'كوكب', 'ككب', '', '', '', 'مفرد', 'DnN', '', '', '"كَوَاكِبُ"', '', 'R', '', '', '', '', '', '', '"(فك). 1.: جُرْمٌ سَمَاوِيٌّ يَدُورُ حَوْلَ الشَّمْسِ وَيُسْتَضَاءُ بِضَوْئِهِ، وَأَشْهَرُ الكَوَاكِبِ مَرْتَبَةً عَلَى حَسَبِ قُرْبِهَا مِنَ الشَّمْسِ: عُطَارِدُ، الزُّهْرَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14222, 'كَوَاكِبُ', 'كواكب', 'جامد', '', 'كواكب', 'ككب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14223, 'كُوكِيَّاتٌ', 'كوكيات', 'جامد', '', 'كوكيات', 'ككت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"كُوكِيَّاتٌ-كُوكِيَّاتٌ (نب). : فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ، عَدِيدَةُ القُعَالاَتِ، مِنْ أَشْهَرِ أَجْنَاسِهَا نَبَاتُ الكُوكَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14224, 'كُولَةٌ', 'كولة', 'جامد', '', 'كولة', 'كلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"كُولَةٌ-كُولَةٌ (نب). : جِنْسُ شَجَرٍ بَرِّيٍّ، زِرَاعِيٌّ، مِنْ فَصِيلَةِ البِرَازِيَّاتِ، يَكْثُرُ فِي الْمَنَاطِقِ الاسْت"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14225, 'كُولُوم', 'كولوم', 'جامد', '', 'كولوم', 'كلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '": هُوَ وَحْدَةُ الكَمِّيَّةِ الكَهْرَبَائِيَّةِ تُعَادِلُ كَمِّيَّةَ الكَهْرَبَاءِ الّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14226, 'كُولِيرَا', 'كوليرا', 'جامد', '', 'كوليرا', 'كلر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '"كُولِيرَا-كُولِيرَا (طب). : مَرَضٌ وَبَائِيٌّ وَخِيمٌ، يَنْتَقِلُ عَبْرَ الْمَاءِ وَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14227, 'كُومَةٌ', 'كومة', 'جامد', 'كوم', 'كومة', 'كمة', '', '', '', 'مفرد', 'DnN', '', '', '"أَكْوَامٌ"', '', 'R', '', '', '', '', '', '', '".: القِطْعَةُ الْمُتَجَمِّعَةُ مِنَ أَيِّ مَادَّةٍ بَعْضُهَا فَوْقَ بَعْضٍ. ""كُومَةُ السَّنَابِلِ"" : رُكَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14228, 'أَكْوَامٌ', 'أكوام', 'جامد', '', 'ءكوام', 'كم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14229, 'مَكَانٌ', 'مكان', 'جامد', 'كون', 'مكان', 'مكن', '', '', '', 'مفرد', 'DnN', '', '', '"أَمْكِنَةٌأَمْكُنٌجأَمَاكِنُ"', '', 'R', '', '', '', '', '', '', '". 1.""اِسْتَقَرَّ فِي مَكَانٍ هَادِئٍ"": فِي مَوْضِعٍ. ""لاَ مَكَانَ لَهُ"" ""يَخْتَبِئُ فِي مَكَانٍ مَّا"" ""أَجِدُهُ فِي كَلِّ مَكَانٍ"" ""مَكَانُ الْحَادِثِ"". 2.""لَهُ مَكَانٌ مَرْمُوقٌ"" : مَنْزِلَةٌ، مَكَانَةٌ، شَأْنٌ. ""هُوَ رَفِيعُ الْمَكَانِ"" ""الرَّجُلُ الْمُنَاسِبُ فِي الْمَكَانِ الْمُنَاسِبِ"". 3. ""هُوَ مِنَ العِل"', '');
