INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14233, 'كِيلُووَاط', 'كيلوواط', 'جامد', '', 'كيلوواط', 'كلط', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": مِنَ الْمَقَايِيسِ الكَهْرَبَائِيَّةِ وَقَدْرُهُ أَلْفُ وَاطٍ، وَهُوَ الَّذِي يُمَثِّلُ وَحْدَةً كَهْرَبَائِيَّةً طَاقَتُهَا أَلْفُ جُولٍ فِي الثَّانِيَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14234, 'كُوَّةٌ', 'كوة', 'جامد', 'كوي', 'كوة', 'كة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":كِوَاءٌ:كُوًى"', '', 'R', '', '', '', '', '', '', '". ""يُطِلُّ مِنْ كُوَّةٍ خَلْفَ الجِدَارِ"" : خَرْقٌ فِيهِ ثَلْمَةٌ، فَتْحَةٌ."', '');
