INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14236, 'كُوًى', 'كوى', 'جامد', '', 'كوى', 'ك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14237, 'مِكْوَاةٌ', 'مكواة', 'جامد', 'كوي', 'مكواة', 'مكة', '', '', '', 'مفرد', 'DnN', '', '', '"مَكَاوٍ:الْمَكَاوِي"', '', '', '', '', '', '', '', '', '". ""تَكْـوِي الْمَلاَبِسَ بِالمِكْوَاةِ"" : آلَةٌ لَهَا صَفِيحَةٌ مِنْ مَعْدِنٍ صَقِيلٍ ومَقْبِضٌ، تُسَخَّنُ بِالنَّارِ أو الكَهْرَبَاءِ لِتُكْوَى بِهَا الْمَلاَبِسُ."', '');
