INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14240, 'كِيرٌ', 'كير', 'جامد', '', 'كير', 'كر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَكْيَارٌ:كِيَرَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَكْيَارٌ، كِيَرَةٌ. : جِلْدٌ عَلَى شَكْلِ مِنْفَاخٍ يَسْتَخْدِمُهُ الْحَدَّادُ لِلنَّفْخِ فِي النَّارِ لإِشْعَالِهَا أَوْ إِبْقَائِهَا مُشْتَعِلَةً لِتَحْمِيرِ الْحَدِيدِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14241, 'أَكْيَارٌ', 'أكيار', 'جامد', '', 'ءكيار', 'كر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14242, 'كِيَرَةٌ', 'كيرة', 'جامد', '', 'كيرة', 'كرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14243, 'كَاسَةٌ', 'كاسة', 'جامد', 'كيس', 'كاسة', 'كسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". : كِيسٌ مِنْ صُوفٍ أَوْ قُطْنٍ بِمَقَاسِ اليَدِ، يُسْتَعْمَلُ لِغَسْلِ الجِسْمِ وَدَلْكِهِ عِنْدَ الاسْتِحْمَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14244, 'كِيسٌ', 'كيس', 'جامد', 'كيس', 'كيس', 'كس', '', '', '', 'مفرد', 'DnN', '', '', '"أَكْيَاسٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَخْرَجَ الدَّرَاهِمَ مِنْ كِيسِهِ"" :وِعَاءٌ مِنَ الثَّوْبِ يُخَاطُ عَلَى شَكْلِ مُرَبَّعٍ أَوْ مُسْتَطِيلٍ تُوضَعُ فِيهِ الدَّرَاهِمُ. 2.""كاسَةٌ، كِيسُ الغَسْلِ"" : يُسْتَعْمَلُ فِي غ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14245, 'أَكْيَاسٌ', 'أكياس', 'جامد', '', 'ءكياس', 'كس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14246, 'كِيَالَةٌ', 'كيالة', 'جامد', 'كيل', 'كيالة', 'كلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"كِيَالَةٌ-كِيَالَةٌ [ك ي ل].: حِرْفَةُ الكَيَّالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14247, 'كَيَّالٌ', 'كيال', 'جامد', 'كيل', 'كيال', 'كل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَيَّالٌ-كَيَّالٌ [ك ي ل]. 1. : مَنْ حِرْفَتُهُ الكَيْلُ. 2.""لِكُلِّ حِنْطَةٍ كَيَّالٌ"" : كُلُّ شَيْءٍ إِلاَّ وَلَهُ صَاحِبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14248, 'مِكْيَالٌ', 'مكيال', 'جامد', 'كيل', 'مكيال', 'مكل', '', '', '', 'مفرد', 'DnN', '', '', '"مَكَايِيلُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِكْيَالُ الْحُبُوبِ"" : مَا يُكَالُ بِهِ . هود آية 84 ولاَ تَنْقُصُوا المِكْيَالَ والمِيزَانَ . (قرآن). 2.""الكَيْلُ بِمِكْيَالَيْنِ"" : عِبَارَةٌ تُقَالُ لِلرَّجُلِ غَيْرِ العَادِلِ، أَيْ عِنْدَمَا يَنْظُرُ إِلَى الشَّيْءِ الوَاحِدِ بِمِكْيَالَيْنِ، بِمِعْيَارَيْنِ مُخْتَلِفَيْنِ مَعَ أَنَّ لَهُمَا قِيمَةً واحِدةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14249, 'مَكَايِيلُ', 'مكاييل', 'جامد', '', 'مكاييل', 'مكل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14250, 'مَكِيلٌ', 'مكيل', 'جامد', 'كيل', 'مكيل', 'مكل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَكِيلٌ-مَكِيلٌ [ك ي ل]. : كُلُّ مَا يُكَالُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14251, 'كِيلُو', 'كيلو', 'جامد', '', 'كيلو', 'كل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '"1. : وَحْدَةٌ وَزْنِيَّةٌ عِنْدَمَا تُضَافُ إِلَى غَرَامٍ، كِيلُو غَرَام : أَيْ وَزْنُ شَيْءٍ يُسَاوِي أَلْفَ غَرَامٍ. 2. : وَحْدَةٌ قِيَاسِيَّةٌ عِنْدَمَا تُضَافُ إِلَى مِتْر : كِيلُومِتْر : أَيْ قِيَاسُ الْمَسَافَةِ يُسَاوِي أَلْفَ مِتْرٍ. 3. : وَحْدَةٌ وَزْنِيَّةٌ لِقُوَّةِ الطَّاقَةِ عِنْدَمَا تُضَافُ إِلَى وَاطْ، كِيلُووَاطْ : أَيْ أَلْف وَاطٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14252, 'كَيْلُوس', 'كيلوس', 'جامد', '', 'كيلوس', 'كلس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": مُجْمَلُ الْمَوَادِّ الغِذَائِيَّةِ الْمُتَجَمِّعَةِ فِي الْمَعِدَةِ عَلَى شَكْلِ كُتْلَةٍ عَجِينِيَّةٍ قَبْلَ أَنْ تَدْخُلَ فِي الأَمْعَاءِ الدَّقِيقَةِ. ن. كَيْموسٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14253, 'كِيمْيَاءُ', 'كيمياء', 'جامد', '', 'كيمياء', 'كم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rz', '', '', '', '', '', '', '": عِلْمٌ فِي طَبِيعَةِ الأَجْسَامِ وَعَنَاصِرِهَا وَمُرَكَّبَاتِهَا، وَمَا يَنْشَأُ عَنْهَا مِنْ تَحَوُّلاَتٍ وَتَفَاعُلاَتٍ، وَتُقْسَمُ الكِيمْيَاءُ إِلَى عِدَّةِ فُرُوعٍ: ""الكِيمْيَاءُ الفِيزْيَائِيَّةُ""، ""الكِيمْيَاءُ العُضْوِيَّةُ""، ""الكِيمْيَاءُ اللاَّعُضْوِيَّةُ""، ""الكِي"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14254, 'كِينَا', 'كينا', 'جامد', '', 'كينا', 'كن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '"كِينَا-كِينَا (نب). : شَجَرَةٌ مِنْ فَصِيلَةِ الفُوِيَّاتِ، تَنْمُو فِي الْمَنَاطِقِ الْحَارَّةِ مِنْ أَمْرِيكَا الجَنُوبِيَّةِ، تُسْتَعْمَلُ قُشُورُهَا دَوَاءً لِعِلاَجِ الْحُمَّى وَالْمَلاَرِيَا وَمُقَاوَمَتِها."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14255, 'لاَتٌ', 'لات', 'جامد', '', 'لات', 'لت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": صَنَمٌ مِنْ أَصْنَامِ العَرَبِ فِي الْجَاهِلِيَّةِ كَانُوا يَعْبُدُونَهُ.النجم آية 19أَفَرَأَيْتُمُ اللاَّتَ وَالعُزَّى (قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14256, 'لاَزَوَرْدٌ', 'لازورد', 'جامد', '', 'لازورد', 'لزرد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '": مَعْدِنٌ شَفَّافٌ ثَمِينٌ، صَافٍ أَزْرَقُ، ضَارِبٌ إِلَى حُمْرَةٍ وَخُضْرَةٍ يُتَّخَذُ لِلْحُلِيِّ، وَيُسْتَخْدَمُ فِي الْمَجَالِ الطِّبِّيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14257, 'لُبٌّ', 'لب', 'جامد', 'لبب', 'لب', 'لب', '', '', '', 'مفرد', 'DnN', '', '', '"أَلْبَابٌ"', '', 'R', '', '', '', '', '', '', '". 1.""لُبُّ الرَّجُلِ"" : عَقْلُهُ. ""أَخَذَ جَمَالُهَا بِلُبِّهِ""المائدة آية 100فَاتَّقُوا اللَّهَ يَا أُولِي الأَلْبَابِ (قرآن). 2.""لُبُّ الْمَوْضُوعِ"" : خُلاَصَتُهُ. ""وَقَفَ عَلَى لُبِّ الْحَقِيقَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14258, 'أَلْبَابٌ', 'ألباب', 'جامد', '', 'ءلباب', 'لبب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14259, 'لُؤْلُؤٌ', 'لؤلؤ', 'جامد', 'لألأ', 'لءلء', 'لل', '', '', '', 'مفرد', 'Dz', '', '', '"لآلِئُ"', '', 'Rz', '', '', '', '', '', '', '". ""عِقْدُ لُؤْلُؤٍ"" : الدُّرُّ، يُوجَدُ فِي صَدَفٍ فِي بَعْضِ البِحَارِ، كُرَوِيٌّ صَلْبٌ لَمَّاعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14260, 'لُؤْلُؤَةٌ', 'لؤلؤة', 'جامد', 'لألأ', 'لءلءة', 'للة', '', '', '', 'مفرد', 'DnN', '', '', '"لآلِئُ"', '', '', '', '', '', '', '', '', '"لُؤْلُؤَةٌ . ""عِقْدُ لُؤْلُؤٍ"" : الدُّرُّ، يُوجَدُ فِي صَدَفٍ فِي بَعْضِ البِحَارِ، كُرَوِيٌّ صَلْبٌ لَمَّاعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14261, 'لآلِئُ', 'لآلئ', 'جامد', '', 'لءءلء', 'لآل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14262, 'لُؤْلُئِيَّةٌ', 'لؤلئية', 'جامد', 'لألأ', 'لءلءية', 'للة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', 'N', 'O', 'O', 'O', '', '"(نب). : نَبَاتٌ مِنْ فَصِيلَةِ الْمُرَكَّبَاتِ، ذَاتُ أَزْهَارٍ صُفْرٍ فِي وَسَطِهَا، وَأَزْهَارٍ بِيضٍ تُحِيطُ بِجَوَانِبِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14263, 'لاَهُوتٌ', 'لاهوت', 'جامد', '', 'لاهوت', 'لهت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1. : الأُلُوهَةُ. 2.""عِلْمُ اللاَّهُوتِ"" : عِلْمٌ يَبْحَثُ فِي العَقَائِدِ الدِّينِيَّةِ وَالقَضَايَا الإِلَهِيَّةِ وَصِفَاتِ اللَّهِ تَعَالَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14264, 'لَبْوَةٌ', 'لبوة', 'جامد', 'لبأ', 'لبوة', 'لبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"لَبْوَةٌ-لَبْوَةٌ [ل ب أ] (حو). ن. لَبُؤَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14265, 'لَبَانٌ', 'لبان', 'جامد', '', 'لبان', 'لبن', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"لَبَانٌ-لَبَانٌ، ةٌ (نب). : نَبَاتٌ مِنْ فَصِيلَةِ البُخُورِيَّاتِ، يُفْرِزُ صَمْغاً، وَيُسَمَّى الكُنْدُرَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14266, 'لَبَّيْكَ', 'لبيك', 'جامد', 'لبب', 'لبيك', 'لبك', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '"لَبَّيْكَ-لَبَّيْكَ [ل ب ب]. ""لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ"" : اللَّهُمَّ إِنِّي عَلَى طَاعَتِكَ مُقِيمٌ، والتَّثْنِيَةُ لِلتَّوْكِيدِ، وَالكَلِمَةُ مَنْصُوبَةٌ عَلَى أَنَّهَا مَفْعُولٌ مُطْلَقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14267, 'لَبَّةٌ', 'لبة', 'جامد', 'لبب', 'لبة', 'لبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":لِبَابٌ"', '', 'R', '', '', '', '', '', '', '". 1.: مَوْضِعُ القِلاَدَةِ مِنَ العُنُقِ. 2.""وَضَعَتِ اللَّبَّةَ فِي عُنُقِهَا"" : القِلاَدَةَ ذَاتهَا. 3.""اِمْرَأَةٌ لَبَّةٌ"" : مُحِبَّةٌ لِزَوْجِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14268, 'لِبَابٌ', 'لباب', 'جامد', '', 'لباب', 'لبب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14269, 'لُبْدَةٌ', 'لبدة', 'جامد', 'لبد', 'لبدة', 'لبدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"لُبْدَةٌ-لُبْدَةٌ [ل ب د]. ن. لِبْدَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14270, 'لُبَدٌ', 'لبد', 'جامد', 'لبد', 'لبد', 'لبد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَبَدٌ-لَبَدٌ [ل ب د] (مص. لَبَدَ). 1. : الصُّوفُ الْمُتَلَبِّدُ. 2.""لاَ سَبَدٌ وَلاَ لَبَدٌ"" (مثل) : لاَ شَعْرٌ وَلاَ صُوفٌ، أَيْ لاَ قَلِيلٌ وَلاَ كَثِيرٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14271, 'لِبْدٌ', 'لبد', 'جامد', 'لبد', 'لبد', 'لبد', '', '', '', 'مفرد', 'DnN', '', '', '"لُبُودٌ:أَلْبَادٌ"', '', 'R', '', '', '', '', '', '', '". 1.""كَانَ يَحْمِلُ لِبْداً تَحْتَ إِبْطِهِ"" : البِسَاطُ مِنْ صُوفٍ. 2.""لِبْدُ الفَرَسِ"" : مَا يوضَعُ عَلَى ظَهْرِهِ تَحْتَ السَّرْجِ. 3.""سَرَحَ لِبْدَهُ"" : شَعْرَهُ الْمُتَلَبِّدَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14272, 'لُبُودٌ', 'لبود', 'جامد', '', 'لبود', 'لبد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14273, 'أَلْبَادٌ', 'ألباد', 'جامد', '', 'ءلباد', 'لبد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14274, 'لِبْدَةٌ', 'لبدة', 'جامد', '', 'لبدة', 'لبدة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَلْبَادٌ:لُبُودٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَلْبَادٌ، لُبُودٌ. 1.""لِبْدَةُ الأَسَدِ"" : عُفْرَتُهُ، أَيِ الشَّعْرُ الْمُجَمَّعُ بَيْنَ كَتِفَيْهِ. ""هُوَ أَمْنَعُ مِنْ لِبْدَةِ الأَسَدِ"" (مثل). : أَيِ الوُصُولُ إِلَيْهِ صَعْبٌ مُمْتَنِعٌ. 2. : نَوْعٌ مِنْ أَغْطِيَةِ الرُّؤُوسِ يُتَّخَذُ غَالِباً مِنَ الصُّوفِ الْمُتَلَبِّدِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14275, 'أَلْبَادٌ', 'ألباد', 'جامد', '', 'ءلباد', 'لبد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14276, 'لُبُودٌ', 'لبود', 'جامد', '', 'لبود', 'لبد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14277, 'لِبَاسٌ', 'لباس', 'جامد', 'لبس', 'لباس', 'لبس', '', '', '', 'مفرد', 'DnN', '', '', '"لُبُسٌ:أَلْبِسَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""لِبَاسُ الإِنْسَانِ"": مَا يُلْبَسُ مِنْ كُسْوَةٍ أَوْ غَيْرِهَا، الزِّيُّ. ""اللِّبَاسُ العَسْكَرِيُّ"" ""لِبَاسُ السَّهْرَةِ"". 2.البقرة آية 187هُنَّ لِبَاسٌ لَكُمْ وَأَنْتُمْ لِبَاسٌ لَهُنَّ (قرآن) : الزَّوْجُ وَالزَّوْجَةُ. 3.""لِبَاسُ الزَّهْرِ"" : أَكْمَامُهُ. 4.""لِبَاسُ التَّقْوَى"" : الْحَيَاءُ. 5.""لِبَاسُ الْمِعْطَفِ"" : غِشَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14278, 'لُبُسٌ', 'لبس', 'جامد', '', 'لبس', 'لبس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14279, 'أَلْبِسَةٌ', 'ألبسة', 'جامد', '', 'ءلبسة', 'لبسة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14280, 'لِبْسٌ', 'لبس', 'جامد', 'لبس', 'لبس', 'لبس', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"لُبُوسٌ"', '', 'R', '', '', '', '', '', '', '". 1. : جُلَيْدَةٌ رَقِيقَةٌ جِدّاً تَكُونُ بَيْنَ الْجِلْدِ وَاللَّحْمِ. 2.""لِبْسُ الكَعْبَةِ أَوِ الْهَوْدَجِ"" : كُسْوَتُهُمَا. 3.""لِكُلِّ زَمَانٍ لِبْسَةٌ"" : حَالَةٌ يُلْبَسُ عَلَيْهَا مِنْ شِدَّةٍ وَرَخَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14281, 'لُبُوسٌ', 'لبوس', 'جامد', '', 'لبوس', 'لبس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14282, 'مَلاَبِسُ', 'ملابس', 'جامد', 'لبس', 'ملابس', 'ملبس', '', '', '', 'مفرد', '', '', '', '"مفردمَلْبَس"', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '". 1.""اِرْتَدَى مَلاَبِسَهُ"" : مَا يَلْبَسُهُ الإِنْسَانُ عَلَى جَسَدِهِ. ""مَلاَبِسُ صُوفِيَّةٌ"" ""مَلاَبِسُ قُطْنِيَّةٌ"" ""مَلاَبِسُ حَرِيرِيَّةٌ"". 2.""مَلاَبِسُ الْمِهْنَةِ"" : مَا يَلْبَسُهُ العَامِلُ وَنَحْوُهُ لِلْعَمَلِ ويُمَيِّزُهُ عَنْ غَيْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14283, 'مَلْبَسٌ', 'ملبس', 'جامد', 'لبس', 'ملبس', 'ملبس', '', '', '', 'مفرد', 'DnN', '', '', '"مَلاَبِسُ"', '', 'R', '', '', '', '', '', '', '". ن. مَلاَبِسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14284, 'مَلاَبِسُ', 'ملابس', 'جامد', '', 'ملابس', 'ملبس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14285, 'لَبَكَةٌ', 'لبكة', 'جامد', 'لبك', 'لبكة', 'لبكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"لَبَكَةٌ-لَبَكَةٌ [ل ب ك]. ""تَنَاوَلَ لَبَكَةً"" : لُقْمَةً أَوْ قِطْعَةً مِنْ ثَرِيدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14286, 'لَبْكَةٌ', 'لبكة', 'جامد', 'لبك', 'لبكة', 'لبكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"لَبْكَةٌ-لَبْكَةٌ [ل ب ك]. ""وَقَعَ فِي لَبْكَةٍ مَا بَعْدَهَا مِنْ لَبْكَةٍ"" : فِي اخْتِلاَفٍ لاَ يَرَى مِنْهُ أَيَّ وُضُوحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14287, 'لَبْلاَبِيَّاتٌ', 'لبلابيات', 'جامد', '', 'لبلابيات', 'لبلبت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ، أَنْوَاعُهَا عَدِيدَةٌ، مُعْتَرِشَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14288, 'لَبْلاَبٌ', 'لبلاب', 'جامد', 'لبلب', 'لبلاب', 'لبلب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"لَبْلاَبٌ-لَبْلاَبٌ [ل ب ل ب] (نب). : نَبَاتٌ مِنْ فَصِيلَةِ اللَّبْلاَبِيَّاتِ، مُعْتَرِشٌ، يَلْتَفُّ عَلَى الْمَزْرُوعَاتِ وَالشَّجَرِ، أَنْوَاعُهُ كَثِيرَةٌ، بَعْضُهُ يُسْتَعْمَلُ فِي الطِّبِّ وَفِي التَّزْيِينِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14289, 'لَبْلَبٌ', 'لبلب', 'جامد', 'لبلب', 'لبلب', 'لبلب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَبْلَبٌ-لَبْلَبٌ [ل ب ل ب]. : نَحْرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14290, 'لُبَّادَةٌ', 'لبادة', 'جامد', 'لبد', 'لبادة', 'لبدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '". : مِعْطَفٌ مِنْ جِلْدٍ أَوْ مُشَمَّعٍ وَنَحْوِهِ يُلْبَسُ لِلْوِقَايَةِ مِنَ الْمَطَرِ أَوِ الْبَرْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14291, 'لُبَانَةٌ', 'لبانة', 'جامد', 'لبن', 'لبانة', 'لبنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":لُبَانٌ"', '', 'R', '', '', '', '', '', '', '". ""قَضَى لُبَانَتَهُ"" : حَاجَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14292, 'لُبَانٌ', 'لبان', 'جامد', '', 'لبان', 'لبن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14293, 'لِبَانٌ', 'لبان', 'جامد', 'لبن', 'لبان', 'لبن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لِبَانٌ-لِبَانٌ [ل ب ن]. ""هُوَ أَخُوهُ بِلِبَانِ أُمِّهِ"" : أَيْ أَخُوهُ مِنَ الرَّضَاعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14294, 'لَبِنَةٌ', 'لبنة', 'جامد', 'لبن', 'لبنة', 'لبنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَبِنَةٌ-لَبِنَةٌ [ل ب ن]. 1.""بَقَرَةٌ لَبِنَةٌ"" : تُعْطِي لَبَناً جَيِّداً وَكَثِيراً، ذَاتُ اللَّبَنِ. 2.""اللَّبِنَةُ الأُولَى"" : وَاحِدَةُ اللَّبِنِ مِنَ الطِّينِ الْمَشْوِيِّ يُبْنَى بِهِ. ""وَضَعَ اللَّبِنَةَ الأُولَى لِعَمَلِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14295, 'لَبَنٌ', 'لبن', 'جامد', 'لبن', 'لبن', 'لبن', '', '', '', 'مفرد', 'DnN', '', '', '"أَلْبَانٌ"', '', 'R', '', '', '', '', '', '', '". 1. : سَائِلٌ أَبْيَضُ يَجْرِي فِي ثَدْيِ النِّسَاءِ مُنْذُ اليَوْمِ الأَوَّلِ مِنَ الوِلاَدَةِ، كَمَا يَكُونُ فِي ضَرْعِ الْحَيَوَانَاتِ الثَّدْيِيَّةِ، الْحَلِيبُ. 2.""لَبَنُ الشَّجَرَةِ"" : مَاؤُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14296, 'أَلْبَانٌ', 'ألبان', 'جامد', '', 'ءلبان', 'لبن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14297, 'لَبِنٌ', 'لبن', 'جامد', 'لبن', 'لبن', 'لبن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَبِنٌ-لَبِنٌ [ل ب ن]. 1. : الْمَضْرُوبُ مِنَ الطِّينِ يُبْنَى بِهِ لِلْبِنَاءِ دُونَ أَنْ يُطْبَخَ. 2.""لَبِنُ القَمِيصِ"" : رُقْعَةٌ تُخَاطُ فِي أَعْلاَهُ، بَنِيقَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14298, 'لُبْنَى', 'لبنى', 'جامد', 'لبن', 'لبنى', 'لبن', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"لُبْنَى-لُبْنَى [ل ب ن]. 1. (نب). : شَجَرَةٌ لَهَا لَبَنٌ كَالعَسَلِ. 2. ""لُبْنَى"" : اِسْمُ عَلَمٍ لِلإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14299, 'لَبُونَاتٌ', 'لبونات', 'جامد', 'لبن', 'لبونات', 'لبنت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '"لَبُونَاتٌ-لَبُونَاتٌ [ل ب ن]. : كُلُّ حَيَوَانٍ مِنْ فَصِيلَةِ الضَّرْعِيَّاتِ، الثَّدْيِيَّاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14300, 'مَلْبَنَةٌ', 'ملبنة', 'جامد', 'لبن', 'ملبنة', 'ملبنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَلْبَنَةٌ-مَلْبَنَةٌ [ل ب ن]. : مَكَانُ، مَصْنَعُ مُعَالَجَةِ الْحَلِيبِ وَصُنْعِ الْجُبْنِ وَالزُّبْدَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14301, 'مَلْبَنٌ', 'ملبن', 'جامد', 'لبن', 'ملبن', 'ملبن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَلْبَنٌ-مَلْبَنٌ [ل ب ن]. : نَوْعٌ مِنَ الْحَلْوَاءِ يُصْنَعُ مِنَ اللَّبَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14302, 'مِلْبَنٌ', 'ملبن', 'جامد', 'لبن', 'ملبن', 'ملبن', '', '', '', 'مفرد', 'DnN', '', '', '"مَلاَبِنُ"', '', 'R', '', '', '', '', '', '', '". 1. : مِصْفَاةُ اللَّبَنِ. 2.:مِحْلَبٌ يُحْلَبُ فِيهِ اللَّبَنُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14303, 'مَلاَبِنُ', 'ملابن', 'جامد', '', 'ملابن', 'ملبن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14304, 'لُبْنَان', 'لبنان', 'جامد', '', 'لبنان', 'لبنن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', 'N', 'N', 'N', 'O', '', '": مِنَ البُلْدَانِ العَرَبِيَّةِ بِالشَّرْقِ الأَوْسَطِ (الجُمْهُورِيَّةُ اللُّبْنَانِيَّةُ). عَاصِمَتُهَا بَيْرُوت."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14305, 'لَبْنِيَّةٌ', 'لبنية', 'جامد', '', 'لبنية', 'لبنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"لَبْنِيَّةٌ-لَبْنِيَّةٌ (طخ). : طَعَامٌ يُصْنَعُ مِنَ اللَّبَنِ وَالأَرُزِّ وَاللَّحْمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14306, 'لَبُؤَةٌ', 'لبؤة', 'جامد', '', 'لبءة', 'لبة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":لَبُؤٌأُنْثَىالأَسَدِ"', '', 'Rz', '', '', '', '', '', '', '"ج: لَبُؤٌ، لَبُؤَاتٌ. : أُنْثَى الأَسَدِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14307, 'لَبُؤٌ', 'لبؤ', 'جامد', '', 'لبء', 'لب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14308, 'لَتَيَّا', 'لتيا', 'جامد', '', 'لتيا', 'لت', '', '', '', 'جمع تكسير', 'Dy', '', '', '"اللَّتَيَّاتِالتَّثْنِيَةُالل', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"التَّثْنِيَةُ : اللَّتَيَّانِ. ج: اللَّتَيَّاتِ. ""وَقَعَ فِي اللَّتَيَّا وَالَّتِي"" : أَيْ وَقَعَ فِي الدَّوَاهِي وَالْمَصَائِبِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14309, 'لَتَيَّاتٌ', 'لتيات', 'جامد', '', 'لتيات', 'لتت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14310, 'لُثْغَةٌ', 'لثغة', 'جامد', 'لثغ', 'لثغة', 'لثغة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"لُثْغَةٌ-لُثْغَةٌ [ل ث غ]. ""بِلِسَانِهِ لُثْغَةٌ"" : قَلْبُ السِّينِ ثَاءً فِي النُّطْقِ أَوِ الرَّاءِ غَيْناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14311, 'لِثَامٌ', 'لثام', 'جامد', 'لثم', 'لثام', 'لثم', '', '', '', 'مفرد', 'DnN', '', '', '"لُثُمٌ"', '', 'R', '', '', '', '', '', '', '". ""لِثَامُ الْمَرْأَةِ"" : كُلُّ ثَوْبٍ يُوضَعُ عَلَى الأَنْفِ وَمَا حَوْلَهُ، الْحِجَابُ، النِّقَابُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14312, 'لُثُمٌ', 'لثم', 'جامد', '', 'لثم', 'لثم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14313, 'لِثَةٌ', 'لثة', 'جامد', 'لثي', 'لثة', 'لثة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":لِثًى"', '', 'R', '', '', '', '', '', '', '". : مَا حَوْلَ الأَسْنَانِ مِنَ اللَّحْمِ وَفِيهِ مَغَارِزُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14314, 'لِثًى', 'لثى', 'جامد', '', 'لثى', 'لث', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14315, 'مَلْجَأٌ', 'ملجأ', 'جامد', 'لجأ', 'ملجء', 'ملج', '', '', '', 'مفرد', 'Dz', '', '', '"مَلاَجِئُ"', '', 'Rz', '', '', '', '', '', '', '". 1.""كُلٌّ يَبْحَثُ عَنْ مَلْجَإٍ يَلْجَأُ إِلَيْهِ بَعْدَمَا تَتَابَعَتِ الغَارَاتُ الْجَوِّيَّةُ"" : مَخْبَأٌ يَكُونُ حَصِيناً.الشورى آية 47 مَا لَكُمْ مِنْ مَلْجَإٍ يَوْمَئِذٍ (قرآن). 2.""مَلْجَأُ العَجَزَةِ"" : مُؤَسَّسَةٌ خَيْرِيَّةٌ لِإِيوَاءِ العَجَزَةِ. ""مَلْجَأُ اليَتَامَى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14316, 'مَلاَجِئُ', 'ملاجئ', 'جامد', '', 'ملاجء', 'ملج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14317, 'لُجٌّ', 'لج', 'جامد', 'لجج', 'لج', 'لج', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"لُجٌّ-لُجٌّ [ل ج ج]. 1.""لُجُّ البَحْرِ"" : مُعْظَمُ الْمَاءِ حَيْثُ لاَ يُدْرَكُ قَعْرُهُ. 2.""لُجُّ اللَّيْلِ"" : شِدَّةُ ظُلْمَتِهِ وَسَوَادِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14318, 'لِجَامٌ', 'لجام', 'جامد', 'لجم', 'لجام', 'لجم', '', '', '', 'مفرد', 'DnN', '', '', '"لُجْمٌ:لُجُمٌ:أَلْجِمَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""شَدَّ لِجَامَ فَرَسِهِ"": مَا يُجْعَلُ فِي فَمِ الفَرَسِ مِنْ حَدِيدَةٍ فِي طَرَفَيْهَا سَيْرٌ مِنْ جِلْدٍ. ""فَرَسٌ مُسَرَّجٌ بِأَرْوَعِ سَرْجٍ، مُلَجَّمٌ بِأَجْمَلِ لِجَامٍ"". (ع. غلاب) ""أَتْبَعَ الفَرَسَ لِجَامَهَا"". 2.""لَفَظَ لِجَامَهُ"" : اِنْصَرَفَ مُتَذَمِّراً مِنَ الإِعْيَاءِ وَالتَّعَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14319, 'لُجْمٌ', 'لجم', 'جامد', '', 'لجم', 'لجم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
