INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14322, 'لَجْنَةٌ', 'لجنة', 'جامد', 'لجن', 'لجنة', 'لجنة', '', '', '', 'مفرد', 'DnN', '', '', '"لِجَانٌ"', '', 'R', '', '', '', '', '', '', '".: أَعْضَاءٌ فِي مُؤَسَّسَةٍ أَوْ تَنْظِيمٍ يَجْتَمِعُونَ لِلنَّظَرِ فِي أَمْرٍ مَّا. ""اللَّجْنَةُ الثَّقَافِيَّةُ"" ""اللَّجْنَةُ الاجْتِمَاعِيَّةُ"" ""اللَّجْنَةُ الْمَالِيَّةُ"" ""لَجْنَةُ الامْتِحَانِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14323, 'لِجَانٌ', 'لجان', 'جامد', '', 'لجان', 'لجن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14324, 'لَجِينٌ', 'لجين', 'جامد', 'لجن', 'لجين', 'لجن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"لَجِينٌ-لَجِينٌ [ل ج ن]. ""لَجِينُ الإِبِلِ"" : زَبَدُ أَفْوَاهِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14325, 'لُجَيْنٌ', 'لجين', 'جامد', 'لجن', 'لجين', 'لجن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لُجَيْنٌ-لُجَيْنٌ [ل ج ن]. ""خَاتَمٌ مِنْ لُجَيْنٍ"" : خَاتَمٌ مِنْ فِضَّةٍ. ""فَتَظْهَرُ أسْنَانُهُنَّ صَافِيةً تَعْكِسُ نُورَ الشَّمْسِ، فَتَلْمَعُ وكَأَنَّهَا اللُّجَيْنُ الخَالِصُ"". (أحمد التوفيق). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14326, 'لِحَاظٌ', 'لحاظ', 'جامد', '', 'لحاظ', 'لحظ', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ن. لَحْظٌ.لَحْظٌ - ج: لِحَاظٌ. (مص. لَحَظَ). 1.""لَمْ يَكُنْ لَحْظُهُ دَقِيقاً"" : مُرَاقَبَتُهُ، مُلاَحَظَتُهُ. 2.""فِي لَحْظِهِ بَيَاضٌ"" : بَاطِنُ العَيْنِ، غِشَاءُ مُقْلَةِ العَيْنِ الْخَارِجِيُّ. 3.""عَبَّرَ بِلَحْظِهِ عَمَّا يُرِيدُ قَوْلَهُ"" : بِغَمْ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14327, 'إلْحَاحٌ', 'إلحاح', 'جامد', 'لحح', 'ءلحاح', 'إلحح', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"إلْحَاحٌ-إلْحَاحٌ [ل ح ح]. ""طَلَبَ مُسَاعَدَتَهُ بِإلْحَاحٍ"": بِإلْحَافٍ وَإصْرَارٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14328, 'لاَحِسَةٌ', 'لاحسة', 'جامد', 'لحس', 'لاحسة', 'لحسة', '', '', '', 'مفرد', 'DnN', '', '', '"لَوَاحِسُ"', '', '', '', 'N', 'O', 'O', 'O', '', '"(حش). 1.""لاَحِسَةُ السُّكَّرِ"" : حَشَرَةٌ مِنْ فَصِيلَةِ عَدِيمَاتِ الأَجْنِحَةِ، مِنْ رُتْبَةِ الْمُذَنَّبَاتِ، لَهَا جِسْمٌ رَقِيقٌ مُغَطَّى بِقُشُورٍ فِضِّيَّةٍ، تُفْسِدُ مَؤُونَاتِ البَيْتِ وَتَقْرِضُ الْكُتُبَ. 2.""سَنَةٌ لاَحِسَةٌ"" : شَدِيدَةٌ لاَ تُبْقِي عَلَى شَيْءٍ مِنَ النَّبَاتِ. 3.""أَصَابَتْهُمْ لَوَاحِسُ"" : سِنُونَ شِدَادٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14329, 'لَوَاحِسُ', 'لواحس', 'جامد', '', 'لواحس', 'لحس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14330, 'لَحْسٌ', 'لحس', 'جامد', 'لحس', 'لحس', 'لحس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"لَحْسٌ-لَحْسٌ [ل ح س]. : مَا يَظْهَرُ مِنْ رُؤُوسِ البَقْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14331, 'لاَحِظَةٌ', 'لاحظة', 'جامد', 'لحظ', 'لاحظة', 'لحظة', '', '', '', 'مفرد', 'DnN', '', '', '"لَوَاحِظُ"', '', 'R', '', '', '', '', '', '', '". ""لاَحِظَةُ الإِنْسَانِ"" : عَيْنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14332, 'لَوَاحِظُ', 'لواحظ', 'جامد', '', 'لواحظ', 'لحظ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14333, 'مَلْحَظٌ', 'ملحظ', 'جامد', 'لحظ', 'ملحظ', 'ملحظ', '', '', '', 'مفرد', 'DnN', '', '', '"مَلاَحِظُ"', '', 'R', '', '', '', '', '', '', '". : اللَّحْظُ أَوْ مَوْضِعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14334, 'مَلاَحِظُ', 'ملاحظ', 'جامد', '', 'ملاحظ', 'ملحظ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14335, 'لِحَافٌ', 'لحاف', 'جامد', 'لحف', 'لحاف', 'لحف', '', '', '', 'مفرد', 'DnN', '', '', '"لُحُفٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِرْتَدَتْ لِحَافَهَا وَخَرَجَتْ تُهَرْوِلُ"" :كُلُّ ثَوْبٍ يُلْتَحَفُ بِهِ. 2.""غَطَّتْ وَلَدَهَا بِلِحَافٍ مِنْ صُوفٍ"" : مَا يُتَغَطَّى بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14336, 'لُحُفٌ', 'لحف', 'جامد', '', 'لحف', 'لحف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14337, 'مِلْحَفَةٌ', 'ملحفة', 'جامد', 'لحف', 'ملحفة', 'ملحفة', '', '', '', 'مفرد', 'DnN', '', '', '"مَلاَحِفُ"', '', 'R', '', '', '', '', '', '', '". ""اِرْتَدَتْ مِلْحَفَتَهَا وَخَرَجَتْ مُسْرِعَةً"" : مَا يُلْتَحَفُ بِهِ مِنْ ثَوْبٍ. مَنْ كَانَ أَعْوَزَهُ كِسَاءٌ مِنْهُمْ*فَالصَّيْفُ مِلْحَفَةٌ لَهُ وَكِسَاءُ (معروف الرُّصافي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14338, 'مَلاَحِفُ', 'ملاحف', 'جامد', '', 'ملاحف', 'ملحف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14339, 'لَحَقٌ', 'لحق', 'جامد', 'لحق', 'لحق', 'لحق', '', '', '', 'مفرد', 'DnN', '', '', '"أَلْحَاقٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هُمُ اللَّحَقُ"" : أَيْ مَنْ يَلْحَقُونَ بِقَوْمٍ بَعْدَ مُضِيِّهِمْ. 2.""لَحَقُ الكِتَابِ"" : اِسْتِدْرَاكٌ، أَيْ مَا يُلْحَقُ بِهِ بَعْدَ الفَرَاغِ مِنْهُ، فَيُلْحَقُ بِهِ مَا سَقَطَ عَنْهُ. 3.""لَحَقُ الْمُعَاهَدَةِ"" : مُجْمَلُ الأَحْكَامِ التَّفْصِيلِيَّةِ الْمُلْحَقَةِ بِهَا. 4.""وَلَدٌ لَحَقٌ"" : الدَّعِيُّ الْمُلْصَقُ بِغَيْرِ أَبِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14340, 'أَلْحَاقٌ', 'ألحاق', 'جامد', '', 'ءلحاق', 'لحق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14341, 'مَلْحَمَةٌ', 'ملحمة', 'جامد', 'لحم', 'ملحمة', 'ملحمة', '', '', '', 'مفرد', 'DnN', '', '', '"مَلاَحِمُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""اِلْتَقَى الْجَيْشَانِ فِي مَلْحَمَةٍ حَامِيَةِ الوَطِيسِ"" : الْحَرْبُ الشَّدِيدَةُ، مَوْضِعُ الْتِحَامِ الْحَرْبِ. 2.""أَنْشَدَهُمْ مَلْحَمَةً بُطُولِيَّةً"" : نَصٌّ أَدَبِيٌّ مُطَوَّلٌ مِنَ الأَدَبِ القَدِيمِ، شِعْراً أَوْ قِصَّةً، يَسْرُدُ أَحْدَاثاً وَبُطُولاَتٍ عَجِيبَةً تَعْتَمِدُ خَيَالاً كَبِيراً، أَبْطَالُهَا آلِهَةٌ أَوْ بَشَرٌ يَتَمَتَّعُونَ بِصِفَاتٍ خَارِقَةٍ لِلْعَادَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14342, 'مَلاَحِمُ', 'ملاحم', 'جامد', '', 'ملاحم', 'ملحم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14343, 'لِحَامٌ', 'لحام', 'جامد', 'لحم', 'لحام', 'لحم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لِحَامٌ-لِحَامٌ [ل ح م]. ""لِحَامُ الْمَعْدِنِ"" : مَادَّةٌ يُلْحَمُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14344, 'لُحْمَةٌ', 'لحمة', 'جامد', 'لحم', 'لحمة', 'لحمة', '', '', '', 'مفرد', 'DnN', '', '', '"لُحَمٌ"', '', 'R', '', '', '', '', '', '', '". 1.""لُحْمَةُ الصَّيْدِ"" : مَا يُصَادُ بِهِ. 2.""لُحْمَةُ جِلْدَةِ الرَّأَسِ وَغَيْرِهِ"" : مَا بَطَنَ مِمَّا يَلِي اللَّحْمَ. 3. ""لُحْمَةُ الثَّوْبِ"" : خُيُوطُهُ الْمُمْتَدَّةُ عَرْضاً يُلْحَمُ بِهَا السَّدَى. 4.""بَيْنَهُمْ لُحْمَةُ نَسَبٍ"" : قَرَابَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14345, 'لُحَمٌ', 'لحم', 'جامد', '', 'لحم', 'لحم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14346, 'لَحْمٌ', 'لحم', 'جامد', 'لحم', 'لحم', 'لحم', '', '', '', 'مفرد', 'DnN', '', '', '"لُحُومٌ"', '', 'R', '', '', '', '', '', '', '".: كُلُّ الْمَادَّةِ الْمُكَوِّنَةِ لِحَيَوِيَّةِ الْجَسَدِ، خِلاَفُ العَظْمِ وَالشَّحْمِ. 1.""لَحْمُ الْحَيَوَانَاتِ"": مَادَّتُهَا الْحَمْرَاءُ الصَّالِحَةُ لِلأَكْلِ. ""لَحْمُ الْغَنَمِ"" ""لَحْمُ البَقَرِ"" ""لَحْمٌ مَشْوِيٌّ"". 2.""هُوَ مِنْ لَحْمِهِ وَدَمِهِ"" : مِنْ صُلْبِهِ. 3.""أَكَلَ لَحْمَهُ"" : ذَكَرَ عُيُوبَهُ فِي غِيَابِهِ.الحجرات آية 12 أَيُحِبُّ أَحَدُكُمْ أَنْ يَأْكُلَ لَحْمَ أَخِيهِ مَيْتاً (قرآن). 4.""رَآهُ بِلَحْمِهِ وَشَحْمِهِ"": كَمَا هُوَ، بِهَيْئَتِهِ الكَامِلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14347, 'لُحُومٌ', 'لحوم', 'جامد', '', 'لحوم', 'لحم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14348, 'لِحْيَةٌ', 'لحية', 'جامد', 'لحي', 'لحية', 'لحة', '', '', '', 'مفرد', 'DnN', '', '', '"لِحًى:لُحًى"', '', '', '', '', '', '', '', '', '". 1.""رَجُلٌ كَثِيفُ اللِّحْيَةِ"" : لَهُ شَعْرٌ عَلَى الخَدَّيْنِ وَالذَّقَنِ. 2.""لِحْيَةُ التَّيْسِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14349, 'لِحًى', 'لحى', 'جامد', '', 'لحى', 'لح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
