INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14351, 'لَذَّةٌ', 'لذة', 'جامد', 'لذذ', 'لذة', 'لذة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""لَذَّةُ الطَّعَامِ"" : طِيبَتُهُ. 2.""لَذَّةُ الْحَيَاةِ"" : الشُّعُورُ بِالارْتِيَاحِ وَالاِطْمِئْنَانِ. ""وَيَجِدُ اللَّذَّةَ كُلَّ اللَّذَّةِ فِيمَا يَرَى"". (طه حسين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14352, 'مَلَذَّةٌ', 'ملذة', 'جامد', 'لذذ', 'ملذة', 'ملذة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""وَجَدَ مَلَذَّةً فِي النُّزْهَةِ"" : لَذَّةً، مُتْعَةً، شَهْوَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14353, 'لِزَاقٌ', 'لزاق', 'جامد', 'لزق', 'لزاق', 'لزق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لِزَاقٌ - [ل ز ق]. ""اِسْتَعْمَلَ لِزَاقاً لِلَصْقِ الوَرَقِ"" : مَا يُلْزَقُ بِهِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14354, 'لَزْقَةٌ', 'لزقة', 'جامد', 'لزق', 'لزقة', 'لزقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"لَزْقَةٌ-لَزْقَةٌ [ل ز ق]. : مَا يُكَمَّدُ بِهِ الْجِسْمُ لِتَخْفِيفِ الأَلَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14355, 'لِزْقٌ', 'لزق', 'جامد', 'لزق', 'لزق', 'لزق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لِزْقٌ-لِزْقٌ [ل ز ق]. ""كَانَ بلِزْقِهِ"" : لِصْقُهُ،"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14356, 'لَزُوقٌ', 'لزوق', 'جامد', 'لزق', 'لزوق', 'لزق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَزُوقٌ - [ل زق]. (طب). : دَوَاءٌ لِلْجُرْحِ يَلْزَمُهُ حَتَّى يَبْرَأَ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14357, 'لَوَازِمُ', 'لوازم', 'جامد', 'لزم', 'لوازم', 'لزم', '', '', '', 'مفرد', '', '', '', '"مفردلاَزِمَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""جَمَعَ لَوَازِمَهُ"" : حَاجَاتِهِ، أَدَوَاتِهِ الضَّرُورِيَّةَ. ""اللَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14358, 'لاَزِمَة', 'لازمة', 'جامد', '', 'لازمة', 'لزمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14359, 'مَلْزَمَةٌ', 'ملزمة', 'جامد', 'لزم', 'ملزمة', 'ملزمة', '', '', '', 'مفرد', 'DnN', '', '', '"مَلاَزِمُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""مَلْزَمَةُ الكِتَابِ"" : قِطْعَةٌ مِنْهُ وَتَتَكَوَّنُ مِنْ ثَمَانِي صَفَحَاتٍ أَوْ سِتَّ عَشْرَةَ صَفْحَةً أَو اِثْنَتَيْنِ وَثَلاَثِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14360, 'مَلاَزِمُ', 'ملازم', 'جامد', '', 'ملازم', 'ملزم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14361, 'مِلْزَمٌ', 'ملزم', 'جامد', 'لزم', 'ملزم', 'ملزم', '', '', '', 'مفرد', 'DnN', '', '', '"مَلاَزِمُ"', '', 'R', '', '', '', '', '', '', '". : خَشَبَتَانِ أَوْ حَدِيدَتَانِ تُشَدُّ إِحْدَاهُمَا إِلَى الأُخْرَى بِحَدِيدَةٍ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14362, 'مَلاَزِمُ', 'ملازم', 'جامد', '', 'ملازم', 'ملزم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14363, 'لِسَانٌ', 'لسان', 'جامد', 'لسن', 'لسان', 'لسن', '', '', '', 'مفرد', 'DnN', '', '', '"أَلْسِنَةٌ:أَلْسُنٌ(مذ:مؤ)"', '', 'R', '', '', '', '', '', '', '". 1.""أَخْرَجَ لِسَانَهُ"" : عُضْوٌ فِي الفَمِ مِنْ عُرُوقٍ وَعَضَلٍ، وَهُوَ أَدَاةُ النُّطْقِ وَالذَّوْقِ وَالبَلْعِ وَتَنَاوُلِ الطَّعَامِ. 2.""اللِّسَانُ العَرَبِيُّ"" : الكَلاَمُ العَرَبِيُّ، اللُّغَةُ. ""لِسَانٌ فَصِيحٌ"". 3.""أَمْسَكَ لِسَانَهُ فِي حَلْقِهِ بِصُعُوبَةٍ"" : أَيْ أَمْسَكَ عَنِ الكَلاَمِ. 4.""لِسَانُ النَّارِ"" : لَهَبُهَا الْمُشْتَعِلُ. 5.""هُوَ لِسَانُ قَوْمِهِ"" : الْمُتَحَدِّثُ عَنْهُمْ. ""جَرِيدَةُ ""الرَّأْيِ العَامِّ"" لِسَانُ الْحِزْبِ الوَطَنِيِّ"". 6.""لِسَانُ صِدْقٍ"" : الذِّكْرُ الْحَسَنُ.الشعراء آية 84وَاجْعَلْ لِي لِسَانَ صِدْقٍ فِي الآخِرِينَ (قرآن). 7.""لِسَانُ الْحَالِ"" : مَا دَلَّ عَلَى حَالَةِ الشَّيْءِ. 8.""نَطَقَ بِلِسَانِ اللَّهِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14364, 'أَلْسِنَةٌ', 'ألسنة', 'جامد', '', 'ءلسنة', 'لسنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
