INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14366, 'لِسَانِيَّاتٌ', 'لسانيات', 'جامد', 'لسن', 'لسانيات', 'لسنت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"لِسَانِيَّاتٌ-لِسَانِيَّاتٌ [ل س ن]. : عِلْمٌ يَهْتَمُّ بِدِرَاسَةِ اللُّغَةِ مِنْ حَيْثُ تَرَاكِيبُهَا وَتَطَوُّرُهَا وَعَلاَقَاتُ اللُّغَاتِ فِيمَا بَيْنَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14367, 'لِصٌّ', 'لص', 'جامد', 'لصص', 'لص', 'لص', '', '', '', 'مفرد', 'DnN', '', '', '"لُصُوصٌ:لِصَصَةٌ:مؤلُصَّةٌ:لُ', '', 'R', '', '', '', '', '', '', '". ""أُلْقِيَ القَبْضُ عَلَى اللِّصِّ"" : عَلَى السَّارِقِ، أَيْ مَنْ يَسْتَوْلِي عَلَى أَشْيَاءِ النَّاسِ وَيَسْرِقُهَا خُفْيَةً. ""ذَهَبَ جَمَاعَةٌ مِنَ اللُّصُوصِ إِلَى بَيْتِ رَجُلٍ مِنَ الأَغْنِيَاءِ لِيَسْرِقُوا مَتَاعَهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14368, 'لُصُوصٌ', 'لصوص', 'جامد', '', 'لصوص', 'لصص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
