INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14372, 'لَصَائِصُ', 'لصائص', 'جامد', '', 'لصاءص', 'لصص', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14373, 'لاَصُوقٌ', 'لاصوق', 'جامد', 'لصق', 'لاصوق', 'لصق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لاَصُوقٌ-لاَصُوقٌ [ل ص ق]. 1. : مَا يُلْصَقُ مِنْ دَوَاءٍ عَلَى الْجُرْحِ. 2. : الخِرْقَةُ الَّتِي تُشَدُّ عَلَى الْجُرْحِ لِمُدَاوَاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14374, 'لِصَاقٌ', 'لصاق', 'جامد', 'لصق', 'لصاق', 'لصق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لِصَاقٌ-لِصَاقٌ [ل ص ق]. ""لِصَاقُ وَرَقَةٍ"" : مَادَّةٌ لَزِجَةٌ تُلْصَقُ بِهَا الأَشْيَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14375, 'لِصْقٌ', 'لصق', 'جامد', 'لصق', 'لصق', 'لصق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لِصْقٌ-لِصْقٌ [ل ص ق]. ""هُوَ لِصْقِي أَوْ بِلِصْقِي"" : أَيْ لِزْقِي أَوبِلِزْقِي، بِجَنْبِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14376, 'لَصُوقٌ', 'لصوق', 'جامد', 'لصق', 'لصوق', 'لصق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَصُوقٌ-لَصُوقٌ [ل ص ق] (طب). : دَوَاءٌ يُلْصَقُ عَلى الجُرْحِ، أَوْ ثَوْبٌ شَفَّافٌ يُلْصَقُ عَلَى الْجُرْحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14377, 'لُطْعَةٌ', 'لطعة', 'جامد', '', 'لطعة', 'لطعة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"لُطَعٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: لُطَعٌ. : بَيْضُ دُودَةِ القُطْنِ تَضَعُهُ عَلَى بَاطِنِ الوَرَقَةِ."', ':لا جذر:لا مفرد');
