INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14409, 'لُغْمٌ', 'لغم', 'جامد', '', 'لغم', 'لغم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَلْغَامٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَلْغَامٌ. ""وَضَعُوا لُغْماً عَلَى الْحُدُودِ"" : أَيْ مَادَّةً مُتَفَجِّرَةً تَخْتَلِفُ أَحْجَامُهَا، تُوضَعُ فِي حُفْرَةٍ أَوْ وَس"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14410, 'أَلْغَامٌ', 'ألغام', 'جامد', '', 'ءلغام', 'لغم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14411, 'لُغَةٌ', 'لغة', 'جامد', 'لغو', 'لغة', 'لغة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.: مَا يَتَكَلَّمُهُ الإِنْسَانُ مِنْ أَصْوَاتٍ يُعَبِّرُ بِهَا عَنْ أَغْرَاضِهِ. أ. ""اللُّغَةُ العَرَبِيَّةُ هِيَ لُغَةُ الضَّادِ"": مَا يَتَكَلَّمُهُ العَرَبُ. ب.""اللُّغَةُ الفُصْحَى"" : لُغَةُ الأَدَبِ وَالكِتاَبَةِ. ج. ""يُتْقِنُ لُغَاتٍ أَجْنَبِيَّةً"" : هُوَ مُتَعَدِّدُ اللُّغَاتِ، يَعْرِفُ كَلاَمَ الأَجْنَبِيِّ. ""اللُّغَةُ الآرَامِيَّةُ لُغَةٌ مَيِّتَةٌ، وَالعَرَبِيَّةُ لُغَةٌ حَيَّةٌ"". د.""اللُّغَةُ العَامِّيَّةُ"" : الكَلاَمُ العَامِّيُّ الدَّارِجُ. 2.""ل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14412, 'لاَفِتَةٌ', 'لافتة', 'جامد', 'لفت', 'لافتة', 'لفتة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""خَرَجُوا فِي مُظَاهَرَةٍ يَحْمِلُونَ اللاَّفِتَاتِ"" : لَوْحٌ أَوْ ثَوْبٌ يُكْتَبُ عَلَيْهِ مَا يَشُدُّ الانْتِبَاهَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14413, 'لِفْتٌ', 'لفت', 'جامد', '', 'لفت', 'لفت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لِفْتٌ-لِفْتٌ (نب). : بَقْلٌ مِنْ فَصِيلَةِ الصَّلِيبِيَّاتِ، أَبْيَضُ اللَّوْنِ أَوْ أَصْفَرُهُ، مُسْتَدِيرٌ أَوَمُسْتَطِيلٌ، لَهُ جُذُورٌ ذَاتُ أَوْرَاقٍ، يُطْبَخُ أَوْ يُنْقَعُ فِي الْخَلِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14414, 'لَفْحَةٌ', 'لفحة', 'جامد', 'لفح', 'لفحة', 'لفحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', 'N', 'O', 'O', 'O', '', '".""لَفْحَةُ النَّارِ"" : لَسْعَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14415, 'تِلِفِزْيون', 'تلفزيون', 'جامد', 'لفز', 'تلفزيون', 'تلفزن', '', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"تِلِفِزْيون-تِلِفِزْيون [ل ف ز]. جِهَازُ نَقْلِ الأَصْواتِ والصُّوَرِ الْمُتَحَرِّكَةِ بِوَاسِطَةِ الأمْواجِ الكَهْرَبائِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14416, 'لاَفِظَةٌ', 'لافظة', 'جامد', 'لفظ', 'لافظة', 'لفظة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"لاَفِظَةٌ-لاَفِظَةٌ [ل ف ظ]. 1.""رَمَتِ اللاَّفِظَةُ جُثَّتَهُ بَعْدَمَا تَقَاذَفَتْهُ الأَمْوَاجُ"" : البَحْرُ لأَنَّهُ يَلْفُظُ مَا فِي جَوْفِهِ إِلَى الشُّطُوطِ. 2.""طُيُورٌ لاَفِظَةٌ"" : أَيْ تِلْكَ الَّتِي تُطْعِمُ فَرْخَهَا، لأَنَّهَا تُخْرِجُ لَهُ مِنْ جَوْفِهَا. 3.""الرَّحَى"" : سُمِّي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14417, 'لُفَاظَةٌ', 'لفاظة', 'جامد', 'لفظ', 'لفاظة', 'لفظة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":لِفَاظٌ"', '', 'R', '', '', '', '', '', '', '". 1.""لَفَظَ لُفَاظَـةً"" : مَا يُلْفَظُ وَيُطْرَحُ مِنَ الْفَمِ."', '');
