INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14433, 'أَلْقَاطٌ', 'ألقاط', 'جامد', '', 'ءلقاط', 'لقط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14434, 'لُقَاطٌ', 'لقاط', 'جامد', 'لقط', 'لقاط', 'لقط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لُقَاطٌ-لُقَاطٌ [ل ق ط]. ""تَرَكَ الْحَصَّادُونَ لُقَاطاً"" : السُّنْبُلُ الَّذِي يَبْقَى بَعْدَ الْحَصَادِ فَيَلْتَقِطُهُ النَّاسُ، وَكُلُّ مَا يُلْقَطُ مِنَ السَّنَابِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14435, 'لُقْطَةٌ', 'لقطة', 'جامد', 'لقط', 'لقطة', 'لقطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"لُقْطَةٌ-لُقْطَةٌ [ل ق ط]. : مَا يُوجَدُ مُلْقىً عَلَى الأَرْضِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14436, 'لَقَطٌ', 'لقط', 'جامد', 'لقط', 'لقط', 'لقط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَقْطٌ-لَقْطٌ [ل ق ط] (مص. لَقَطَ). 1. ""لَقْطُ الطَّائِرِ"" : الْحُبُوبُ الَّتِي يَقْتَاتُ بِهَا. 2. ""لَقْطُ الْأَثير"" : ضَبْطُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14437, 'مِلْقَطٌ', 'ملقط', 'جامد', 'لقط', 'ملقط', 'ملقط', '', '', '', 'مفرد', 'DnN', '', '', '"مَلاَقِطُ"', '', 'R', '', '', '', '', '', '', '". ""مِلْقَطُ الْحَدَّادِ"" : أَدَاةٌ يُلْقَطُ بِهَا تَتَكَوَّن مِنْ ذِرَاعَيْنِ. ""مِلْقَطُ النَّارِ"" ""مِلْقَطُ الطَّبِيبِ"" ""مِلْقَطُ السُّكَّرِ""."', '');
