INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14463, 'لاَمِسَةٌ', 'لامسة', 'جامد', 'لمس', 'لامسة', 'لمسة', '', '', '', 'مفرد', 'DnN', '', '', '"لَوَامِسُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""لاَمِسَةُ الْحَشَرَةِ"" : قِرْنُهَا الاسْتِشْعَارِيُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14464, 'لَوَامِسُ', 'لوامس', 'جامد', '', 'لوامس', 'لمس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14465, 'مَعِيَّةٌ', 'معية', 'جامد', 'لمع', 'معية', 'معة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"أَلْمَعِيَّةٌ-أَلْمَعِيَّةٌ [ل م ع]. ""هُوَ ذُو أَلْمَعِيَّةٍ حَادَّةٍ"" : حِدَّةُ الذِّهْنِ، مَهَارَةٌ عَقْلِيَّةٌ، فِطْنَةٌ. ""عُرِفَ بِألْمَعِيَّةٍ لاَ حَدَّ لَهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14466, 'مُلَمَّعَةٌ', 'ملمعة', 'جامد', 'لمع', 'ملمعة', 'ملمعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مُلَمَّعَةٌ-مُلَمَّعَةٌ [ل م ع]. ""أَبْيَاتٌ شِعْرِيَّةٌ مُلَمَّعَةٌ"" : أَبْيَاتٌ شَطْرٌ مِنْهَا مُنَقَّطٌ وَشَطْرٌ مُهْمَلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14467, 'يَلْمَعٌ', 'يلمع', 'جامد', 'لمع', 'يلمع', 'لمع', '', '', '', 'مفرد', 'DnN', '', '', '"يَلاَمِعُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""سَطَعَ الْيَلْمَعُ"" : الْبَرْقُ الَّذِي يَكُونُ فِي سَحَابٍ لاَ مَطَرَ فِيهِ. 2.""يَلْمَعُ الصَّحْرَاءِ"" : سَرَابُهَا. ""أَخْدَعُ وَأَكْذَبُ مِنْ يَلْمَعٍ"". 3.""سِلاَحٌ يَلْمَعٌ"" : مَا بَرَقَ مِنْهُ وَلَمَعَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14468, 'يَلاَمِعُ', 'يلامع', 'جامد', '', 'يلامع', 'لمع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14469, 'لُمَّةٌ', 'لمة', 'جامد', 'لمم', 'لمة', 'لمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"لُمَّةٌ-لُمَّةٌ [ل م م]. ""هُوَ لُمَّتُهُ فِي سَفَرِهِ"" : صَاحِبُهُ أَوْ أَصْحَابُهُ، رُفْقَتُهُ، مُؤْنِسُهُ. ""لاَ تُسَافِرُوا حَتَّى تُصِيبُوا لُمَّةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14470, 'مُلِمَّةٌ', 'ملمة', 'جامد', 'لمم', 'ملمة', 'ملمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""مُلِمَّةُ الدَّهْرِ"" : مُصِيبَتُهُ العَظِيمَةُ، الشَّدِيدَةُ. ""شَيْخٌ وَقُورٌ يَقْصِدُهُ النَّاسُ فِي الْمُلِمَّاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14471, 'لَمًى', 'لمى', 'جامد', 'لمي', 'لمى', 'لم', '', '', '', 'مفرد', '', '', '', '', '', 'RwR0', '', '', '', '', '', '', '"لَمىً-لَمىً [ل م ي]. ""فِي شَفَتِهِ لَمىً"" : سُمْرَةٌ أَوْ سَوَادٌ فِي بَاطِنِ الشَّفَةِ.اللَّمَى  [لمي]: سمرةُ في الشفة مستحسَنة.', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14472, 'لَهَازِمُ', 'لهازم', 'جامد', '', 'لهازم', 'لهزم', '', '', '', 'جمع تكسير', '', '', '', '"مفردلِهْزِمَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جمع لِهْزِمَة. ن. لِهْزِمَةٌ.لِهْزِمَةٌ - ج: لَهَازِمُ. [ل هـ ز م].: عَظْمٌ نَاتِىءٌ فِي اللَّحْيِ تَحْتَ الْحَنَكِ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14473, 'لِهْزِمَة', 'لهزمة', 'جامد', '', 'لهزمة', 'لهزمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14474, 'لُهَابٌ', 'لهاب', 'جامد', 'لهب', 'لهاب', 'لهب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لُهَابٌ-لُهَابٌ [ل هـ ب]. ""بِهِ لُهَابٌ"" : عَطَشٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14475, 'لَهْجَةٌ', 'لهجة', 'جامد', 'لهج', 'لهجة', 'لهجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. : لُغَةُ الْإِنْسَانِ الَّتِي فُطِرَ عَلَيْها وَتَعَوَّدَهَا. ""اللَّهْجَةُ الْمَحَلِّيَّةُ"". 2. ""كَانَ شَدِيدَ اللَّهْجَةِ مَعَهُ"" : حَادَّ الْكَلاَمِ. ""لَهْجَةٌ حَادَّةٌ"" ""لَهْجَةٌ حَاسِمَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14476, 'لُهْجَةٌ', 'لهجة', 'جامد', 'لهج', 'لهجة', 'لهجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لُهْجَةٌ-لُهْجَةٌ [ل هـ ج]. ""أَطْعَمَهُ اللُّهْجَةَ"" : ما يُتَعَلَّلُ بِهِ قَبْلَ وَقْتِ تَناوُلِ الطّعامِ، لُمْجَة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14477, 'لِهْزِمَةٌ', 'لهزمة', 'جامد', 'لهزم', 'لهزمة', 'لهزمة', '', '', '', 'مفرد', 'DnN', '', '', '"لَهَازِمُ"', '', 'R', '', '', '', '', '', '', '".: عَظْمٌ نَاتِىءٌ فِي اللَّحْيِ تَحْتَ الْحَنَكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14478, 'لَهَازِمُ', 'لهازم', 'جامد', '', 'لهازم', 'لهزم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14479, 'أُلْهُوَّةٌ', 'ألهوة', 'جامد', 'لهو', 'ءلهوة', 'لهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"أُلْهُوَّةٌ-أُلْهُوَّةٌ [ل هـ و]. ""جَعَلَهُ أُلْهُوَّةً"" : مَا يُتَلاَهَى بِهِ. ""بَيْنَهُمْ أُلْهُوَّةٌ يَتَلاَهَوْنَ بِهَا"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14480, 'لاَهَةٌ', 'لاهة', 'جامد', 'لهو', 'لاهة', 'لهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"لاَهَةٌ-لاَهَةٌ [ل هـ و]. ""أَفْزَعَتْهُ اللاَّهَةُ"" : الْحَيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14481, 'لَهَاةٌ', 'لهاة', 'جامد', 'لهو', 'لهاة', 'لهة', '', '', '', 'مفرد', 'DnN', '', '', '"لَهَوَاتٌ"', '', 'Rw', '', '', '', '', '', '', '"(تش): اللَّحْمَةُ الْمُشْرِفَةُ عَلَى الْحَلْقِ فِي أَقْصَى سَقْفِ الْفَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14482, 'لَهَوَاتٌ', 'لهوات', 'جامد', '', 'لهوات', 'لهت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14483, 'مَلْهًى', 'ملهى', 'جامد', 'لهو', 'ملهى', 'مله', '', '', '', 'مفرد', 'Dy', '', '', '"مَلاَهٍ:الْمَلاَهِي"', '', '', '', '', '', '', '', '', '". 1.""مَلْهَى الأَطْفَالِ"" : مَكَانُ اللَّهْوِ واللَّعِبِ. ""لاَ يَزَالُ يَتَذَكَّرُ مَلْهى طُفُولَتِهِ"". 2.""مَلْهىً لَيْلِيٌّ"" : مَكَانُ اللَّهْوِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14484, 'مَلاَهِي', 'ملاهي', 'جامد', '', 'ملاهي', 'مله', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14485, 'مَلْهَاةٌ', 'ملهاة', 'جامد', 'لهو', 'ملهاة', 'ملهة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مَلْهَاةٌ-مَلْهَاةٌ [ل هــ و]. ""اِسْتَمْتَعَ بِمُشَاهَدَةِ مَلْهَاةٍ مُثِيرَةٍ لِلضَّحِكِ"" : أَيْ مَسْرَحِيَّةٍ، تَمْثِيلِيَّةٍ مُضْحِكَةٍ، هَزْلِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14486, 'لَوَاحِمُ', 'لواحم', 'جامد', '', 'لواحم', 'لحم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '": رُتْبَةٌ مِنَ الثَّدْيِيَّاتِ اللَّبُونَةِ تَتَغَذَّى أَسَاساً بِاللُّحُومِ، فَصَائِلُهَا عَدِيدَةٌ، مِنْهَا السِّنَّوْرِيَّاتُ وَالْكَلْبِيَّاتُ وَالضَّبْعِيَّاتُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14487, 'لُوبْيَاءُ', 'لوبياء', 'جامد', '', 'لوبياء', 'لب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"لُوبْيَاءُ-لُوبْيَاءُ (نب).: بَقْلَةٌ زِرَاعِيَّةٌ مِنْ فَصِيلَةِ الْقَرْنِيَّاتِ، تُطْبَخُ لِثِمَارِهَا وَحُبُوبِهَا، وَتُسَمَّى أَيْضاً فَاصُولِيَا بَيْضَاءَ، تُؤْكَلُ حُبُوبُهَا، وَفَاصُولِيَا خَضْرَاءَ تُؤْكَلُ قِشْرَتُهَا وَحُبُوبُهَا مَعاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14488, 'لاَئِحَةٌ', 'لائحة', 'جامد', 'لوح', 'لاءحة', 'لحة', '', '', '', 'مفرد', 'DnN', '', '', '"لَوَائِحُ"', '', '', '', '', '', '', '', '', '". 1.""لاَئِحَةُ الْحِسَابِ"" : وَرَقَةٌ تَتَضَمَّنُ الْحِسَابَ. 2.""لاَئِحَةُ الْمَطْعَمِ"" : وَرَقَةٌ تَتَضَمَّنُ أَنْوَاعَ الْمَأْكُولاَتِ الْمَوْجُودَةِ بِالْمَطْعَمِ"". 3.""لاَئِحَةُ الكُتُبِ"" : عَنَاوِينُهَا وَأَسْمَاءُ مُؤَلِّفِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14489, 'لَوَائِحُ', 'لوائح', 'جامد', '', 'لواءح', 'لح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14490, 'لَوْحَةٌ', 'لوحة', 'جامد', 'لوح', 'لوحة', 'لحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""لَوْحَةُ خَشَبٍ"" : اللَّوْحُ. 2.""لَوْحَةُ الْإِعْلاَنَاتِ"" : لاَفِتَةٌ مِنْ خَشَبٍ أَوْ وَرَقٍ مُقَوّىً. 3.""لَوْحَةٌ تَذْكَارِيَّةٌ"" : صَفِيحَةٌ مَعْدِنِيَّةٌ يُسَجَّلُ فِيهَا كَلاَمٌ مَّا للِذِّكْرَى. 4.""لَوْحَةُ رَسَّامٍ"" : مَا يَرْسُمُهُ الرَّسَّامُ مِن مَناظِرَ وَوُجوهٍ عَلَى لَوْحٍ أَوْ ثَوْبٍ أَوْ وَرَقٍ. ""لَوْحَةٌ زَيْتِيَّةٌ"" ""لَوْحَةٌ مِنْ أَجْمَلِ لَوَحَاتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14491, 'مَلاَذٌ', 'ملاذ', 'جامد', 'لوذ', 'ملاذ', 'ملذ', '', '', '', 'مفرد', 'DnN', '', '', '"مَلاَوِذُ"', '', 'R', '', '', '', '', '', '', '". ""وَجَدَ فِي بَيْتِ أَهْلِهِ مَلاَذاً"": مَلْجَأً. ""أَنْتَ مَلاَذِي الأَخِيرُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14492, 'مَلاَوِذُ', 'ملاوذ', 'جامد', '', 'ملاوذ', 'ملذ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14493, 'لَوْزَةٌ', 'لوزة', 'جامد', 'لوز', 'لوزة', 'لزة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"واحدةاللَّوْزِ)"', '', 'R', '', '', '', '', '', '', '"لَوْزَةٌ-لَوْزَةٌ [ل و ز] (وَاحِدَةُ اللَّوْزِ). : لَحْمَةٌ فِي جَانِبِ الْحَلْقِ قُرْبَ اللَّهَاةِ، وَهُمَا لَوْزَتَانِ. ""أُصِيبَ بِالْتِهَابِ اللَّوْزَتَيْنِ"" ""اِسْتِئْصَالُ اللَّوْزَتَيْنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14494, 'لَوْزٌ', 'لوز', 'جامد', 'لوز', 'لوز', 'لز', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَوْزٌ-لَوْزٌ [ل و ز] (نب). : شَجَرٌ مِنْ فَصِيلَةِ الْوَرْدِيَّاتِ، لَهُ حَبٌّ مُثْمِرٌ مُسْتَطِيلٌ، لَذِيذُ الطَّعْمِ، كُلُّ حَبَّةٍ أَوْ حَبَّتَيْنِ تَكُـونُ دَاخِلَ غِشَاءٍ سَمِيكٍ، يُكَسَّرُ، مِنْهُ مَا هُوَ حُلْوٌ وَمَا هُوَ مُرٌّ. يَدُومُ طَوِيلاً وَيَحْتَفِظُ بِطَعْمِـهِ، وَيُسْتَخْدَمُ اللَّوْزُ كَثِيراً فِي تَحْضِيرِ أَنْوَاعٍ مِنَ الْحَلاَوَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14495, 'لَوْزِيَّةٌ', 'لوزية', 'جامد', 'لوز', 'لوزية', 'لزة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"لَوْزِيَّةٌ-لَوْزِيَّةٌ [ل و ز] (طخ). : حَلْوَى تُصْنَعُ بِالْجَوْزِ الْمَعْجُونِ أَوِ الْفُسْتُقِ وَالسُّكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14496, 'لَوْلاَءُ', 'لولاء', 'جامد', 'لول', 'لولاء', 'لل', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"لَوْلاَءُ-لَوْلاَءُ [ل و ل]. ""عَاشُوا فِي اللَّوْلاَءِ زَمَناً طَوِيلاً"" : الضَّيْقُ، الشِّدَّة، الضُّرُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14497, 'لَوْلَبٌ', 'لولب', 'جامد', 'لولب', 'لولب', 'للب', '', '', '', 'مفرد', 'DnN', '', '', '"لَوَالِبُ"', '', 'R', '', '', '', '', '', '', '". 1. : آلَةٌ مِنْ خَشَبٍ أَوْ مَعْدِنٍ، ذَاتُ مِحْوَرٍ حَلَزُونِيٍّ. 2. : مِسْمَارٌ لَهُ شَكْلٌ حَلَزُونيٌّ يُعْرَفُ بِالْبُرْغِيِّ. 3.""لَوْلَبُ مَنْعِ الْحَمْلِ"" : أَدَاةٌ طِبِّيَّةٌ لِمَنْعِ الْحَمْلِ تُشْبِهُ اللَّوْلَبَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14498, 'لَوَالِبُ', 'لوالب', 'جامد', '', 'لوالب', 'للب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14499, 'لاَمٌ', 'لام', 'جامد', 'لوم', 'لام', 'لم', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""أَمْرٌ لاَمٌ"" : شَدِيدٌ. 2.""أَفْزَعَهُ اللاَّمُ أَوِ اللاَّمَةُ"" : الْهَوْلُ. ""وَيَكَادُ مِنْ لاَمٍ يَطِيرُ فُؤَادُهَا"". 3.""رَأَيْتُ لاَمَهُ"" : شَخْصَهُ. 4.""أَتَى اللاَّمَةَ"" : مَا يُلاَمُ عَلَيْهِ. 5.""اللاَّمُ"" : حَرْفٌ مِنْ حُرُوفِ الْهِجَاءِ. ن.. ل."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14500, 'لاَئِمَةٌ', 'لائمة', 'جامد', 'لوم', 'لاءمة', 'لمة', '', '', '', 'مفرد', 'DnN', '', '', '"لَوَائِمُ"', '', '', '', '', '', '', '', '', '". ""أَنْحَى عَلَيْهِ بِاللاَّئِمَةِ"" : بِاللَّوْمِ. ""اِسْتَحَقَّ اللاَّئِمَةَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14501, 'لَوَائِمُ', 'لوائم', 'جامد', '', 'لواءم', 'لم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14502, 'لَوْنٌ', 'لون', 'جامد', 'لون', 'لون', 'لن', '', '', '', 'مفرد', 'DnN', '', '', '"أَلْوَانٌ"', '', 'R', '', '', '', '', '', '', '". 1.""لَوْنٌ أَحْمَرُ أَوْ أَسْوَدُ أَوْ أَبْيَضُ"" : صِفَةُ الشَّيْءِ وَهَيْئَةُ مَادَّتِهِ. 2.""لَدَيْهِ لَوْنٌ جَيِّدٌ مِنَ الثِّيَابِ"" : صِنْفٌ، نَوْعٌ. ""قَدَّمَ لَهُ أَلْوَاناً مِنَ الطَّعَامِ"" ""يَأْتِي بِأَلْوَانٍ مِنَ الْحَدِيثِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14503, 'أَلْوَانٌ', 'ألوان', 'جامد', '', 'ءلوان', 'لن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14504, 'لِوَاءٌ', 'لواء', 'جامد', 'لوي', 'لواء', 'ل', '', '', '', 'مفرد', 'Dz', '', '', '"أَلْوِيَةٌ:أَلْوِيَاتٌ"', '', 'Rz', '', '', '', '', '', '', '". 1.""رَفَعُوا اللِّوَاءَ"" : الْعَلَمَ وَهُوَ دُونَ الرَّايَةِ. 2.""نَشَرَ لِوَاءَ الْعَدْلِ"" : نَشَرَ ظِلَّ الْعَدْلِ. 3.""لِوَاءُ الْجَنُوبِ"" (في الْمَشْرِق العَرَبِيِّ) : الإِقْلِيمُ فِي التَّقْسِيمِ الإِدَارِيِّ. 4.""يَحْتَلُّ رُتْبَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14505, 'أَلْوِيَةٌ', 'ألوية', 'جامد', '', 'ءلوية', 'لة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14506, 'أَلْوِيَاتٌ', 'ألويات', 'جامد', '', 'ءلويات', 'لت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14507, 'مَلاَوِي', 'ملاوي', 'جامد', 'لوي', 'ملاوي', 'مل', '', 'Tk', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مَلاَوٍ-مَلاَوٍ، الْمَلاَوِي [ل و ي]. ""تَاهَ فِي الْمَلاَوِي"" : فِي الطُّرُقِ الْمُلْتَوِيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14508, 'لِيبْيَا', 'ليبيا', 'جامد', '', 'ليبيا', 'لب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'N', 'N', 'O', '', '": مِنَ الْبُلْدَانِ الْعَرَبِيَّةِ (الْجَمَاهِيرِيَّةُ الْعَرَبِيَّةُ اللِّيبِيَّةُ الشَّعْبِيَّةُ الاشْتِرَاكِيَّةُ الْعُظْمَى). مِنْ بُلْدَانِ الْمَغْرِبِ الْعَرَبِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14509, 'لَيْثٌ', 'ليث', 'جامد', 'ليث', 'ليث', 'لث', '', '', '', 'مفرد', 'DnN', '', '', '"لُيُوثٌ"', '', 'R', '', '', '', '', '', '', '"(حو). : الْأَسَدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14510, 'لُيُوثٌ', 'ليوث', 'جامد', '', 'ليوث', 'لث', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14511, 'لِيسَانس', 'ليسانس', 'جامد', '', 'ليسانس', 'لسنس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""حَصَلَ عَلَى شَهَادَةِ اللِّيسَانس"" : شَهَادَةٌ يَحْصُلُ عَلَيْهَا الطَّالِبُ بَعْدَ نِهَايَةِ الدُّرُوسِ الْجَامِعِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14512, 'لِيفٌ', 'ليف', 'جامد', 'ليف', 'ليف', 'لف', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"أَلْيَافٌ"', '', 'R', '', '', '', '', '', '', '". 1. : قِشْرُ النَّخْلِ وَمَا شَابَهَهُ. ""النَّخْلَةُ جِذْعُهَا نَمَّاءٌ وَلِيفُهَا رَشَّاءٌ"". (التوحيدي). 2.""أَلْيَافٌ صِنَاعِيَّةٌ"" : النَّيْلُونُ وَمَا شَابَهَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14513, 'أَلْيَافٌ', 'ألياف', 'جامد', '', 'ءلياف', 'لف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14514, 'لَيْلاَءُ', 'ليلاء', 'جامد', 'ليل', 'ليلاء', 'لل', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"لَيْلاَءُ-لَيْلاَءُ [ل ي ل]. ""لَيْلَةٌ لَيْلاَءُ"" : طَوِيلَةٌ شَدِيدَةُ السَّوَادِ، لَيْلَى. ""قَضَى بِجَانِبِ الْمَرِيضِ لَيْلَةً لَيْلاَءَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14515, 'لَيْلٌ', 'ليل', 'جامد', 'ليل', 'ليل', 'لل', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '":لَيَالٍ:اللَّيَالِي"', '', 'R', '', '', '', '', '', '', '". 1.""سَهِرَ اللَّيْلَ كُلَّهُ"" : مِنْ مَغْرِبِ الشَّمْسِ إِلَى طُلُوعِ الْفَجْرِ. ""عَادَ لَيْلاً"" ""وَعُدْتُ كَمَا أَبْدَأُ وَاللَّيْلُ أَلْيَلُ"". (الشنفرى) ""يَا لَيْلُ مَا أَطْوَلَكَ"" ""نِمْتُ لَيْلَةً هَادِئَةً"" ""اللَّيْلُ أَخْفَى لِلْوَيْلِ"". (مثل) ""كَلامُ اللَّيْلِ يَمْحُوهُ النَّهَارُ "".2.القدر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14516, 'لَيَالِي', 'ليالي', 'جامد', '', 'ليالي', 'لل', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14517, 'لَيْلَى', 'ليلى', 'جامد', 'ليل', 'ليلى', 'لل', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'R0', '', '', '', '', '', '', '"لَيْلَى-لَيْلَى [ل ي ل]. 1.""لَيْلَى الْخَمْرِ"" : نَشْوَتُهَا، بَدْءُ سُكْرِهَا. 2.""أُمُّ لَيْلَى"" : الْخَمْرُ. 3.""لَيْلَةٌ لَيْلَى"" : طَوِيلَةٌ وَشَدِيدَةُ الظُّلْمَةِ، صَعْبَةٌ، لَيْلاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14518, 'لَيْمُونِيَّةٌ', 'ليمونية', 'جامد', 'ليم', 'ليمونية', 'لمنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". : مَشْرُوبٌ يُهَيَّأُ بِعَصِيرِ اللَّيْمُونِ وَالْمَاءِ وَالسُّكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14519, 'لَيْمُونٌ', 'ليمون', 'جامد', '', 'ليمون', 'لمن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَيْمُونٌ-لَيْمُونٌ (نب). 1. : شَجَرٌ مُثْمِرٌ مِنْ فَصِيلَةِ السَّذَابِيَّاتِ، يَشْمُلُ أَنْوَاعَ البُرْتُقَالِ وَالْأُتْرُجِّ وَاللَّيْمُونِ الْحُلْوِ وَاللَّيْمُونِ الْحَامِضِ. ""عَصِيرُ اللَّيْمُونِ"" ""مُرَبَّى اللَّيْمُونِ"". 2.""اللَّيْمُونُالْهِنْدِيُّ"" : شَجَرٌ مِنْ فَصِيلَةِ السَّذَابِيَّاتِ، يُعْطِي ثِمَارا"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14520, 'لُيُونَةٌ', 'ليونة', 'جامد', 'لين', 'ليونة', 'لنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"لُيُونَةٌ-لُيُونَةٌ [ل ي ن]. ""يُعَامِلُهُ بِاللُّيُونَةِ"" : بِالنُّعُومَةِ وَاللُّطْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14521, 'مَار', 'مار', 'جامد', '', 'مار', 'مر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '": السَّيِّدُ، وَأَكْثَرُ اسْتِعْمَالِهَا عِنْدَ القِدِّيسِينَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14522, 'مَارِس', 'مارس', 'جامد', '', 'مارس', 'مرس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ الثَّالِثُ مِنَ الشُّهُورِ الْمِيلاَدِيَّةِ. ن: آذَار."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14523, 'مَارِيّ', 'ماري', 'جامد', '', 'ماري', 'مر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"1.""مَارِيُّ البَقَرَةِ"" : وَلَدُهَا الأَمْلَسُ الأَبْيَضُ. 2.""اِمْرَأَةٌ مَارِيَّةٌ"" : بَيْضَاءُ. 3.""مَارِيَّة"" : اِسْمُ عَلَمٍ لِلإِنَاثِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14524, 'مَازُرِيَّاتٌ', 'مازريات', 'جامد', '', 'مازريات', 'مزرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"مَازُرِيَّاتٌ-مَازُرِيَّاتٌ (حو) .: فَصِيلَةٌ مِنَ الطُّيُورِ، عَديدَةُ الأنْوَاعِ، لَهَا مَنَاقيرُعَرِيضةٌ وَكَبِيرَةٌ، تَعِيشُ دَاخِلَ الجَمَاعَةِ، تَتَغَذَّى بالْحَشَرَاتِ والقِشْرِيَّاتِ والأَسْمَاكِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14525, 'مَازُورٌ', 'مازور', 'جامد', '', 'مازور', 'مزر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مَازُورٌ-مَازُورٌ (حو).: طَائِرٌ مِنْ فَصِيلَةِ الْمَازُوريَّاتِ عَريضُ المِنْقَارِ، يَقْتَاتُ بِالحَشَراتِ والدِّيدَانِ وَالْقِشْرِيَّاتِ والأَسْمَاكِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14526, 'مَاسُورَةٌ', 'ماسورة', 'جامد', '', 'ماسورة', 'مسرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '": أُنْبُوبٌ أَجْوَفُ مُسْتَدِيرٌ مِنْ مَعْدِنٍ لِسَكْبِ المِيَاهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14527, 'مَاعِزٌ', 'ماعز', 'جامد', '', 'ماعز', 'معز', '', '', '', 'جمع تكسير', 'DnN', '', '', '"مَوَاعِزُ:مِعَازٌ:مَعِزٌيُطْل', '', 'R', '', '', '', '', '', '', '"ج: مَوَاعِزُ، مِعَازٌ، مَعِزٌ. يُطْلَقُ عَلَى الذَّكَرِ وَالأُنْثَى: مِنْفَصِيلَةِ الْمَعِزِ وَالبَقَرَاتِ، مِنْ رُتْبَةِ شَفْعِيَّةِ الأَظْلاَفِ، وَهِيَ مِنَ اللَّبَائِنِ الْمُجْتَرَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14528, 'مَوَاعِزُ', 'مواعز', 'جامد', '', 'مواعز', 'معز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14529, 'مِعَازٌ', 'معاز', 'جامد', '', 'معاز', 'معز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14530, 'مَعِزٌ', 'معز', 'جامد', '', 'معز', 'معز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14531, 'مُؤْقٌ', 'مؤق', 'جامد', 'مأق', 'مءق', 'مق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مُؤْقٌ-مُؤْقٌ [م أ ق]. ""مُؤْقُ العَيْنِ"" : طَرَفُهَا مِمَّا يَلِي الأَنْفَ، وَهُوَ مَجْرَى الدَّمْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14532, 'مَالَجٌ', 'مالج', 'جامد', '', 'مالج', 'ملج', '', '', '', 'جمع تكسير', 'DnN', '', '', '"مَوالِجُ"', '', 'R', '', '', '', '', '', '', '"ج: مَوالِجُ. ""مَالَجُ البَنَّاءِ"" : مِسَجَّةٌ، أَداةٌ يُطَيَّنُ بِها."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14533, 'مَوالِجُ', 'موالج', 'جامد', '', 'موالج', 'ملج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14534, 'مَؤُونَةٌ', 'مؤونة', 'جامد', 'مأن', 'مءونة', 'منة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مُؤَنٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَخَذَ مَعَهُ مَؤُونَتَهُ"" : ذَخِيرَتَهُ، عُدَّتَهُ، قُوتَهُ. ""وَفَّرُوا كُلَّ الْمُؤَنِ لِخَوْضِ الْمَعْرَكَةِ"". 2.""كَفَى غَيْرُهُ مَؤُونَتَهُ"" : أَيْ قَامَ مَقَامَهُ أَوْ قَضَى حَاجَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14535, 'مُؤَنٌ', 'مؤن', 'جامد', '', 'مءن', 'من', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14536, 'مَاهِيَةٌ', 'ماهية', 'جامد', '', 'ماهية', 'مهة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"ج: ـات. (نِسْبَةً إِلَى مَا هُوَ). ""مَاهِيَةُ الأَمْرِ"" : حَقِيقَتُهُ وَطَبِيعَتُهُ وَصِفَاتُهُ الجَوْهَرِيَّةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14537, 'مَأْوًى', 'مأوى', 'جامد', '', 'مءوى', 'م', '', '', '', 'جمع تكسير', 'Dy', '', '', '"مَآوٍ:الْمَآوِي"', '', '', '', '', '', '', '', '', '"ج: مَآوٍ، الْمَآوِي. ""مَأْوَى الإِنْسَانِ"" : الْمَسْكَنُ.النازعات آية 39 ، 40، 41 فَإِنَّ الجَحِيمَ هِيَ الْمَأْوَى ......... فَإِنَّ الجَنَّةَ هِيَ الْمَأْوَى (قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14538, 'مَآوِي', 'مآوي', 'جامد', '', 'مءءوي', 'مآ', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14539, 'مَايُو', 'مايو', 'جامد', '', 'مايو', 'م', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ الخَامِسُ مِنَ الشُّهُورِ الغَرْبِيَّةِ، يُنْطَقُ مَايْ أَيْضاً. ن. أَيَّار."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14540, 'مِبْذَلٌ', 'مبذل', 'جامد', '', 'مبذل', 'مبذل', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '"مَبَاذِلُ"', '', 'R', '', '', '', '', '', '', '"ج: مَبَاذِلُ. 1. ""يَرْتَدِي مِبْذَلَهُ"" : بِذْلَتَهُ، أَيْ مَا يُسْتَعْمَلُ مِنَ الثِّيَابِ كُلَّ يَوْمٍ. ""جَاءَ فِي مَبَاذِلِهِ"" : فِي ثِيَابِهِ العَادِيَةِ. 2.""ثَوْبٌ مِبْذَلٌ"" : ثَوْبٌ رَثٌّ، بَالٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14541, 'مَبَاذِلُ', 'مباذل', 'جامد', '', 'مباذل', 'مبذل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14542, 'مِتْرٌ', 'متر', 'جامد', '', 'متر', 'متر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَمْتَارٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَمْتَارٌ. : قِيَاسٌ مُسْتَعْمَلٌ لِتَحْدِيدِ طُولِ مُخْتَلِفِ الأَشْيَاءِ، قَدْرُهُ ذِرَاعٌ وَنِصْفٌ تَقْرِيباً، يُقَسَّمُ إِلَى مِئَةِ سَنْتِمتْرٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14543, 'أَمْتَارٌ', 'أمتار', 'جامد', '', 'ءمتار', 'متر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14544, 'مِتْرَاسٌ', 'متراس', 'جامد', '', 'متراس', 'مترس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"مَتَارِيسُ"', '', 'R', '', '', '', '', '', '', '"ج: مَتَارِيسُ. 1.""تَحَصَّنَ وَرَاءَ المِتْرَاسِ"" : مَا يَسْتَتِرُ بِهِ الجُنْدِيُّ أَوِ الْمُدَافِعُ عَنْ نَفْسِهِ كَالَحائِطِ أَوِ الْحَاجِزِ وَمَا شَابَهَ ذَلِكَ. 2.""أَقَامَ الْمُتَظَاهِرُونَ مَتَارِيسَ وَسَطَ الشَّوَارِعِ"": حَوَاجِزَ أَلْوَاحٍ أَوْ أَحْجَارٍ وَمَا شَابَهَ ذَلِكَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14545, 'مَتَارِيسُ', 'متاريس', 'جامد', '', 'متاريس', 'مترس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14546, 'مِتَانٌ', 'متان', 'جامد', 'متن', 'متان', 'متن', '', '', '', 'مفرد', 'DnN', '', '', '"مُتُنٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""مِتَانُ العَمُودَيْنِ"" : مَا بَيْنَ كُلٍّ مِنْهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14547, 'مُتُنٌ', 'متن', 'جامد', '', 'متن', 'متن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14548, 'مَتَاعٌ', 'متاع', 'جامد', 'متع', 'متاع', 'متع', '', '', '', 'مفرد', 'DnN', '', '', '"أَمْتِعَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""جَمَعَ مَتَاعَهُ"" : كُلُّ مَا يُنْتَفَعُ بِهِ مِنْ أَثَاثٍ وَأَدَوَاتٍ وَسِلَعٍ. 2.""مَتَاعُ الدُّنْيَا"" : حُطَامُهَا قَلِيلُهُ أَوْ كَثِيرُهُ.آل عمران آية 185وَمَا الْحَيَاةُ الدُّنْيَا إِلاَّ مَتَاعُ الغُرُورِ (قرآن). 3.""سَقَطُ الْمَتَاعِ"" : رَدِيئُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14549, 'أَمْتِعَةٌ', 'أمتعة', 'جامد', '', 'ءمتعة', 'متعة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14550, 'مُتْعَةٌ', 'متعة', 'جامد', 'متع', 'متعة', 'متعة', '', '', '', 'مفرد', 'DnN', '', '', '"مُتَعٌ"', '', 'R', '', '', '', '', '', '', '". 1.""يَعِيشُ فِي مُتْعَةٍ"" : فِي بُحْبُوحَةِ عَيْشٍ، فِي تَلَذُّذٍ وَنَشْوَةٍ. ""يَجِدُ فِي حَدِيثِهِ مُتْعَةً لاَ تُدَانِيهَا مُتْعَةٌ"" ""مُتْعَةٌ سِيَاحِيَّةٌ"" ""مُتْعَةٌ فِكْرِيَّةٌ. 2.""أَمَاكِنُ الْمُتْعَةِ"" : أَمَاكِنُ التَّرْفِيهِ العَامَّةُ. 3.""مُتْعَةُ الْحَجِّ"" : التَّمَتُّعُ بِمَنَاسِكِهِ. 4.""زَوَاجُ مُتْعَةٍ"" : زَوَاجُ تَمَتُّعٍ لِفَتْرَةٍ مُعَيَّنَةٍ. 5.""مُتْعَةُ الْمَرْأَةِ"" : مَا تُعْطَاهُ بَعْدَ الطَّلاَقِ مِنْ مَالٍ وَنَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14551, 'مُتَعٌ', 'متع', 'جامد', '', 'متع', 'متع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14552, 'مَثَانَةٌ', 'مثانة', 'جامد', '', 'مثانة', 'مثنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. (تش).: جَيْبٌ عَضَلِيٌّ وَغِشَائِيٌّ يُوجَدُ خَلْفَ العَانَةِ، فِيهِ يَسْتَقِرُّ البَوْلُ بَعدَما أَن تُفْرِزهُ الكُلْيَتانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14553, 'أُمْثولَةٌ', 'أمثولة', 'جامد', 'مثل', 'ءمثولة', 'مثلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَماثيلُ"', '', 'R', '', '', '', '', '', '', '". 1.""أَدَّبَهُ لِيَكونَ أُمْثولَةً لِغَيْرِهِ"" : عِبْرَةً. 2.""جاءَ بِأُمْثولاَتٍ مِنَ الشِّعْرِ القَديمِ"" : قَدَّمَ أَبْياتاً مِنْهُ نَماذِجَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14554, 'أَماثيلُ', 'أماثيل', 'جامد', '', 'ءماثيل', 'مثل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14555, 'تِمْثالٌ', 'تمثال', 'جامد', 'مثل', 'تمثال', 'تمثل', '', '', '', 'مفرد', 'DnN', '', '', '"تَماثيلُ"', '', 'R', '', '', '', '', '', '', '". ""تِمْثالٌ رَائِعٌ"" : مَا يَنْحِتهُ النَّحَّاتُ مِنْ صُورَةٍ أَوْ رَمْزٍ فِي مَعْدِنٍ أَوْ حَجَرٍ يُحَاكِي بِهِ نَمُوذَجاً مِنَ الطَّبِيعَةِ أَوِ الإِنْسَانِ. ""كُلُّ التَّمَاثِيلِ الَّتِي شَاهَدَهَا فِي الْمُتْحَفِ أَثَارَتْ إِعْجَابَهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14556, 'تَماثيلُ', 'تماثيل', 'جامد', '', 'تماثيل', 'تمثل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14557, 'مَجُوسٌ', 'مجوس', 'جامد', 'مجس', 'مجوس', 'مجس', '', '', '', 'مفرد', 'DnN', '', '', '"مَجُوسِيٌّ"', '', 'Rp', '', '', '', '', '', '', '". ""قَوْمٌ كَانُوا مِنَ الْمَجُوسِ"" : مِنْ عَبَدَةِ الشَّمْسِ أَوِ القَمَرِ أَوِ النَّارِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14558, 'مَجُوسِيٌّ', 'مجوسي', 'جامد', '', 'مجوسي', 'مجس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14559, 'مَثَّالٌ', 'مثال', 'جامد', 'مثل', 'مثال', 'مثل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَثَّالٌ-مَثَّالٌ [م ث ل]. ""تِمْثَالٌ مِنْ صُنْعِ الْمَثَّالِ الإيطَالِيِّ..."": مَنْ يَنْحَتُ التَّمَاثِيلَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14560, 'مِثَالٌ', 'مثال', 'جامد', 'مثل', 'مثال', 'مثل', '', '', '', 'مفرد', 'DnN', '', '', '"أَمْثِلَةٌ:مَثَلٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""مِثَالٌ يُقْتَدَى بِهِ"": نَمُوذَجٌ. ""كَانَ عَلَى مِثَالِهِ"" ""قَدَّمَ عَدَداً مِنَ الأَمْثِلَةِ"" : مِنَ النَّمَاذِجِ. 2.""مِثَالُ ذَلِكَ"" : شِبْهُ ذَلِكَ. ""اِبْتَكَرَ رُسُوماً عَلَى غَيْرِ سَابِقِ مِثَالٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14561, 'أَمْثِلَةٌ', 'أمثلة', 'جامد', '', 'ءمثلة', 'مثلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14562, 'مَثَلٌ', 'مثل', 'جامد', '', 'مثل', 'مثل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14563, 'مَثَلٌ', 'مثل', 'جامد', 'مثل', 'مثل', 'مثل', '', '', '', 'مفرد', 'DnN', '', '', '"أَمْثَالٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هُوَ مَثَلُهُ الأَعْلَى"" : نَمُوذَجُهُ. 2. ""اِتَّخَذَ مِنْ ذَلِكَ مَثَلاً"" : عِبْرَةً. 3.""الْمَثَلُ السَّائِرُ"": القَوْلُ السَّائِرُ هُوَ كَلاَمٌ فِي جُمْلَةٍ أَوْ جُمْلَتَيْنِ يُمَثِّلُ عِبْرَةً مُسْتَخْلَصَةً مِنْ وَاقِعَةٍ مُعَيَّنَةٍ يُرَدَّدُ فِي أُخْرَى مُشَابِهَةٍ لَهَا.الحشر آية 21 وَتِلْكَ الأَمْثَالُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ (قرآن).4.الأعراف آية 176 فَمَثَلُهُ كَمَثَلِ الكَلْبِ إِنْ تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْتَتْرُكْهُ يَلْهَثْ (قرآن) : الشَّبِيهُ. 5.""الْمَثَلُ الْخُرَافِيُّ"" : فَنٌّ قَصَصِيٌّ يَجْرِي عَلَى أَلْسِنَةِ الْحَيَوَانَاتِ. 6.""مَثَلاً"" : عَلَى سَبِيلِ الْمِثَالِ، وَهُوَ اسْمٌ مَنْصُوبٌ، نَائِبٌ عَنِ الْمَفْعُولِ الْمُطْلَقِ، أَيْ أُمَثِّلُ تَمْثِيلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14564, 'أَمْثَالٌ', 'أمثال', 'جامد', '', 'ءمثال', 'مثل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14565, 'مِثْلٌ', 'مثل', 'جامد', 'مثل', 'مثل', 'مثل', '', '', '', 'مفرد', 'DnN', '', '', '"أَمْثَالٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هُوَ مِثْلُهُ فِي كُلِّ شَيْءٍ"": شَبِيهُهُ، نَظِيرُهُ. 2.""عَامَلَهُ بِالمِثْلِ"" : بِالشَّيْءِ نَفْسِهِ. ""لاَ تَنْهَ عَنْ خُلُقٍ وَتَأْتِيَ مِثْلَهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14566, 'أَمْثَالٌ', 'أمثال', 'جامد', '', 'ءمثال', 'مثل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14567, 'مُجَاجٌ', 'مجاج', 'جامد', 'مجج', 'مجاج', 'مجج', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مُجَاجٌ-مُجَاجٌ، ةٌ [م ج ج]. 1.: مَا يَقْذِفُهُ الإِنْسَانُ مِنْ رِيقٍ أَوْ مُخَاطٍ مِنْ فَمِهِ. 2.""مُجَاجُ العِنَبِ"" : عَصِيرُهُ. 3.""مُجَاجُ النَّحْلِ"" : عَسَلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14568, 'مُجَدَّرَةٌ', 'مجدرة', 'جامد', '', 'مجدرة', 'مجدرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مُجَدَّرَةٌ-مُجَدَّرَةٌ (طخ).: طَعَامٌ شَرْقِيٌّ يُطْبَخُ مِنَ العَدَسِ وَالرُّزِّ وَالبَصَلِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14569, 'المُشْتَرِي', 'المشتري', 'جامد', '', 'المشتري', 'لمشتر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'N', '', '"مُشْتَرِي-الْمُشْتَرِي (فك). : كَوْكَبٌ سَيَّارٌ يُعَدُّ مِنْ أَكْبَرِ الكَوَاكِبِ حَجْماً وَ أَشَدِّهَا لَمَعَاناً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14570, 'مِجَنٌّ', 'مجن', 'جامد', 'مجن', 'مجن', 'مجن', '', '', '', 'مفرد', 'DnN', '', '', '"مَجَانُّ"', '', 'R', '', '', '', '', '', '', '". 1.""مِجَنُّ الفَارِسِ"" : تُرْسُهُ. 2.""أَدَارَ لَهُ ظَهْرَ الْمِجَنِّ"" : أَيْ تَحَوَّلَ مِنْ صَدَاقَتِهِ إِلَى عَدَاوَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14571, 'مَجَانُّ', 'مجان', 'جامد', '', 'مجان', 'مجن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14572, 'مَحَارِيَّاتٌ', 'محاريات', 'جامد', '', 'محاريات', 'محرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ مِنَ الرِّخْوِيَّاتِ ذَاتِ الصَّدَفَتَيْنِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14573, 'مُحٌّ', 'مح', 'جامد', 'محح', 'مح', 'مح', '', '', '', 'مفرد', 'DnN', '', '', '"أَمْحَاحٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""مُحُّ بَيْضَةٍ"" : صُفْرَتُهَا، الْمَاحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14574, 'أَمْحَاحٌ', 'أمحاح', 'جامد', '', 'ءمحاح', 'محح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14575, 'مَحَارَةٌ', 'محارة', 'جامد', 'محر', 'محارة', 'محرة', '', '', '', 'مفرد', 'DnN', '', '', '"مَحَارٌ"', '', 'R', '', '', '', '', '', '', '". 1.: الصَّدَفَةُ وَنَحْوُهَا، وَتُطْلَقُ أَيْضاً عَلَى ضَرْبٍ مِنَ الرِّخْوِيّاتِ الصَفِيحَاتِ الخَيَاشِيمِ، يُسْتَخْرَجُ مِنْ بَعْضِهَا اللُّؤْلُؤُ. 2.""مَحَارَةُ الأُذُنِ"" : جَوْفُهَا. 3.""الْمَحَارَتَانِ"" : رَأْسَا الوَرِكِ الْمُسْتَدِيرَانِ اللَّذَانِ يَدُورُ فِيهِمَا رَأْسا الفَخِذَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14576, 'مَحَارٌ', 'محار', 'جامد', '', 'محار', 'محر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14577, 'مَحَاقٌ', 'محاق', 'جامد', 'محق', 'محاق', 'محق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مَحَاقٌ-مَحَاقٌ، مِحَاقٌ، مُحَاقٌ [م ح ق] (فك).: 1.: مَا يُلاَحَظُ مِنْ نُقْصَانٍ فِي القَمَرِ بَعْدَ اكْتِمَالِهِ. 2.: آخِرُ الشَّهْرِ القَمَرِيِّ. 3.""لَيَالِي المحَاقِ"" : لَيَاليِ مُرُورِ القَمَرِ فِي مَرْحَلَةِ الْمَحَاقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14578, 'مِحْنَةٌ', 'محنة', 'جامد', 'محن', 'محنة', 'محنة', '', '', '', 'مفرد', 'DnN', '', '', '"مِحَنٌ"', '', 'R', '', '', '', '', '', '', '". ""يَعِيشُ فِي مِحْنَةٍ"" : ما يُمْتَحَنُ بِهِ الإِنْسَانُ مِنْ بَلِيَّةٍ أَوْ مُصِيبَةٍ. ""الْمِحْنَةُ خَيْرٌ وَاعِظٍ لِلإِنْسَانِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14579, 'مِحَنٌ', 'محن', 'جامد', '', 'محن', 'محن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14580, 'مِمْحَاةٌ', 'ممحاة', 'جامد', 'محو', 'ممحاة', 'ممحة', '', '', '', 'مفرد', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '"مِمْحَاةٌ-مِمْحَاةٌ [م ح و]. 1.""مِمْحَاةُ السَّبُّورَةِ"" : أَدَاةٌ مِنْ ثَوْبٍ ثَخِينٍ، أَوْ <خِرْقَةٍ تُمْحَى بِهَا الكِتَابَةُ أَوْ تُزَالُ بِهَا الأَوْسَاخُ. 2.""مِمْحَاةُ الدَّفْتَرِ"": أَدَاةٌ مِنَ الْمَطَّاطِ تُمْحَى بِهَا الكِتَابَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14581, 'مُخٌّ', 'مخ', 'جامد', 'مخخ', 'مخ', 'مخ', '', '', '', 'مفرد', 'DnN', '', '', '"مِخَاخٌ:أَمْخَاخٌ"', '', 'R', '', '', '', '', '', '', '".: الْمَادَّةُ العَصَبِيَّةُ الرَّخْوَةُ الَّتِي تُشَكِّلُ دِمَاغَ الإِنْسَانِ أَوِ الْحَيَوَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14582, 'مِخَاخٌ', 'مخاخ', 'جامد', '', 'مخاخ', 'مخخ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14583, 'أَمْخَاخٌ', 'أمخاخ', 'جامد', '', 'ءمخاخ', 'مخخ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14584, 'مَاخِرَةٌ', 'ماخرة', 'جامد', 'مخر', 'ماخرة', 'مخرة', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَاخِرُ"', '', '', '', '', '', '', '', '', '".: السَّفِينَةُ.النحل آية 14 وَتَرَى الفُلْكَ مَوَاخِرَ فِيهِ وَلِتَبْتَغُوا مِنْ فَضْلِهِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14585, 'مَوَاخِرُ', 'مواخر', 'جامد', '', 'مواخر', 'مخر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14586, 'مَخَاضٌ', 'مخاض', 'جامد', 'مخض', 'مخاض', 'مخض', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَخَاضٌ-مَخَاضٌ [م خ ض]. ""فَاجَأَهَا الْمَخَاضُ فِي اللَّيْلِ"" : وَجَعُ الوِلاَدَةِ. مريم آية 23فَأَجاءها الْمَخاضُ إلى جِذْعِ النَّخْلَةِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14587, 'مَخِيضٌ', 'مخيض', 'جامد', 'مخض', 'مخيض', 'مخض', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَخِيضٌ-مَخِيضٌ [م خ ض]. : اللَّبَنُ الَّذِي اُسْتُخْرِجَ زُبْدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14588, 'مِمْخَضَةٌ', 'ممخضة', 'جامد', 'مخض', 'ممخضة', 'ممخضة', '', '', '', 'مفرد', 'DnN', '', '', '"مَمَاخِضُ"', '', 'R', '', '', '', '', '', '', '". : وِعَاءٌ مِنْ جِلْدٍ ونَحْوِهِ يُضْرَبُ فِيهِ اللَّبَنُ ويُحَرَّكُ حَتَّى يَخْرُجَ مِنْهُ الزُّبْدُ، ويُمْكِنُ أَنْ يُطْلَقَ عَلَى كُلِّ آلَةٍ لِهَذَا الغَرَضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14589, 'مَمَاخِضُ', 'مماخض', 'جامد', '', 'مماخض', 'ممخض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
