INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14592, 'غَائِلَةٌ', 'غائلة', 'جامد', 'غيل', 'غاءلة', 'غلة', '', '', '', 'مفرد', 'DnN', '', '', '"غَوَائِلُ"', '', '', '', '', '', '', '', '', '". 1.""نَزَلَتْ بِهِ الغَائِلَةُ"" : الْمُصِيبَةُ، الدَّاهِيَةُ. 2.""اِسْتَبَدَّتْ بِهِمُ الغَائِلَةُ"" : الفَسَادُ وَالشَّرُّ. 3.""الْمَرْأَةُ الغَائِلَةُ"" : الَّتِي تُرْضِعُ وَلَدَهَا وَهِيَ حَامِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14593, 'غَوَائِلُ', 'غوائل', 'جامد', '', 'غواءل', 'غل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14594, 'مُخَيْخٌ', 'مخيخ', 'جامد', '', 'مخيخ', 'مخخ', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مُخَيْخٌ-مُخَيْخٌ (تش).: جُزْءٌ مِنَ الدِّمَاغِ خَلْفَ الْمُخِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14595, 'أَمْداحٌ', 'أمداح', 'جامد', 'مدح', 'ءمداح', 'مدح', '', '', '', 'مفرد', '', '', '', '"مفردمَدْحٌ"', '', '', '', '', '', '', '', '', '". ""الأمْداحُ النَّبَوِيَّةُ"" : القَصائِدُ الشِّعْرِيَّةُ التي تُقالُ في مَدْحِ الرَّسول محمَّدٍ (. ""يُداوِمُ الْمَسْجِدَ وَحَلَقاتِ الذِّكْرِ والأمْداحِ"". (محمد برادة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14596, 'مَدْحٌ', 'مدح', 'جامد', '', 'مدح', 'مدح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14597, 'مَادَّةٌ', 'مادة', 'جامد', 'مدد', 'مادة', 'مدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَوَادُّ"', '', 'Rp', '', '', '', '', '', '', '". 1.""مَادَّةُ الْحَدِيدِ"" : مَا يَتَرَكَّبُ وَيَتَكَوَّنُ مِنْهُ الْحَدِيدُ أَوْ غَيْرُهُ مِنَ الأَجْسَامِ وَيَقُومُ بِهِ وَيَتَّخِذُ أَشْكَالاً وَأَحْجَاماً. 2.""مَادَّةُ الشَّيْءِ"" : عَنَاصِرُهُ الْمُكَوِّنَةُ لَهُ سَوَاءٌ كَانَتْ. أ. حِسِّيَّةً: ""مَادَّةُ التُّرَابِ"" أَوْ ب. مَعْنَوِيَّةً : ""مَادَّةُ أَفْكَارِهِ"". ""مَوَادُّ غِذَائِيَّةٌ"" ""مَوَادُّ أَوَّلِيَّةٌ"" ""الْمَوَادُّ التَّعْلِيمِيَّةُ"". 3.""الْمَادَّةُ الخَامِسَةُ مِنَ الدُّسْتُورِ"" (قا) : أَيِ الفِقْرَةُ... 4.""الْمَادَّةُ اللُّغَوِيَّةُ"" : أُصُولُ اشْتِقَاقِهَا، أَيْ أَنَّ ""مَدَدَ"" هِيَ مَادَّةُ الْمَدَاخِلِ مَدَّ، مَدَّدَ، مَدٌّ، مَدِيدٌ، مَمْدُودٌ، اِسْتَمَدَّ، إلخ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14598, 'مَوَادُّ', 'مواد', 'جامد', '', 'مواد', 'مد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14599, 'مِدَادٌ', 'مداد', 'جامد', 'مدد', 'مداد', 'مدد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِدَادٌ-مِدَادٌ [م د د]. 1.""مِدَادُ الدَّوَاةِ"" : حِبْرُهَا. 2.""مِدَادُ السِّرَاجِ"" : مَا صُبَّ فِيهِ مِنْ زَيْتٍ وَنَحْوِهِ. ""سَجَّلَ انْتِصَارَهُ بِمِدَادِ الفَخْرِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14600, 'مُدٌّ', 'مد', 'جامد', 'مدد', 'مد', 'مد', '', '', '', 'مفرد', 'DnN', '', '', '"أَمْدَادٌ:مِدَادٌ:مِدَدَةٌ"', '', 'R', '', '', '', '', '', '', '".: ضَرْبٌ مِنَ الْمَكَايِيلِ يُسَاوِي 18 لِتْراً تَقْرِيباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14601, 'أَمْدَادٌ', 'أمداد', 'جامد', '', 'ءمداد', 'مدد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
