INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14604, 'مُدَّةٌ', 'مدة', 'جامد', 'مدد', 'مدة', 'مدة', '', '', '', 'مفرد', 'DnN', '', '', '"مُدَدٌ"', '', '', '', '', '', '', '', '', '". ""اِنْتَظَرَهُ مُدَّةً زَمَنِيَّةً"" : أَيْ وَقْتاً، فَتْرَةً زَمَنِيَّةً لِلْكَثِيرِ وَالقَلِيلِ مِنْهَا. ""أَنْجَزَ عَمَلَهُ فِي مُدَّةٍ قَصِيرَةٍ"" ""أَعَارَهُ كِتَاباً لِمُدَّةٍ مِنَ الزَّمَنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14605, 'مُدَدٌ', 'مدد', 'جامد', '', 'مدد', 'مد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14606, 'مَدَدٌ', 'مدد', 'جامد', 'مدد', 'مدد', 'مد', '', '', '', 'مفرد', 'DnN', '', '', '"أَمْدَادٌ"', '', 'R', '', '', '', '', '', '', '". 1.""مَدَدُ الْحَبْلِ"" : مَا يُمَدَّ بِهِ. الكهف آية 109 قُلْ لَوْ كانَ البَحْرُ مِداداً لِكَلِمات رَبِّي لَنَفِدَ البَحْرُ قَبْلَ أنْ تَنْفَدَ كَلِماتُ رَبِّي وَلَوْ جِئْنا بِمِثْلِهِ مَدَداً .(قرآن). 2.""أَمَدَّهُ بِمَدَدٍ"" : بِعَوْنٍ، بِغَوْثٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14607, 'أَمْدَادٌ', 'أمداد', 'جامد', '', 'ءمداد', 'مدد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14608, 'مَدِينَةٌ', 'مدينة', 'جامد', 'مدن', 'مدينة', 'مدنة', '', '', '', 'مفرد', 'DnN', '', '', '"مُدُنٌ:مَدَائِنُ"', '', '', '', '', '', '', '', '', '". 1.""سَكَنَ الْمَدِينَةَ"" : تَجَمُّعٌ سُكَّانِيٌّ يَعِيشُ وَسَطَ مَرَافِقَ حَيَوِيَّةٍ وَمُنْشَآتٍ حَضَارِيَّةٍ وَعُمْرَانِيَّةٍ. ""مَدِينَةُ القُدْسِ زَهْرَةُ الْمَدَائِنِ"". 2.""مَدِينَةُ السَّلاَمِ"": بَغْدَادُ. 3.""دَخَلَ الرَّسُولُ الْمَدِينَةَ ظَافِراً"" : اِسْمُ عَلَمٍ أُطْلِقَ عَلَى مَدِينَةِ ""يَثْرِبَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14609, 'مُدُنٌ', 'مدن', 'جامد', '', 'مدن', 'مدن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14610, 'مَدَائِنُ', 'مدائن', 'جامد', '', 'مداءن', 'مدن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14611, 'مُدْيَةٌ', 'مدية', 'جامد', 'مدي', 'مدية', 'مدة', '', '', '', 'مفرد', 'DnN', '', '', '"مُدًى"', '', '', '', '', '', '', '', '', '". ""سَلَّ مُدْيَتَهُ مِنْ غِمْدِهَا"" : الشَّفْرَةُ الكَبِيرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14612, 'مُدًى', 'مدى', 'جامد', '', 'مدى', 'مد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14613, 'مَدًى', 'مدى', 'جامد', 'مدي', 'مدى', 'مد', '', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"مَدًى-مَدًى [م د ي]. 1.""بَلَغَ مَدَاهُ"" : غَايَتَهُ، مُنْتَهَاهُ، بَلَغَ أَقْصَى مَدَاهُ. ""عَلَى الْمَدَى البَعِيدِ"" ""بَعِيدُ الْمَدَى"". 2.""مَدَى الْحَيَاةِ"" : طَوَالَ الْحَيَاةِ. ""عَلَى مَدَى الأَيَّامِ"". 3.""بَلَغَ المَدَى"" : الْحَدُّ الأقْصَى. ""أَخِي جَاوَزَ الظَّالِمُونَ الْمَدَى"". (علي محمود طه). 4.""الْمَدَى الْحَيَوِيُّ لِلْبِلاَدِ"" : الْمَجَالُ الضَّرُورِيُّ لَهَا اجْتِمَاعِيّاً وَاقْتِصَادِيّاً وَتِجَارِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14614, 'مَذْقَةٌ', 'مذقة', 'جامد', 'مذق', 'مذقة', 'مذقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَذْقَةٌ-مَذْقَةٌ [م ذ ق]. ""سَقَاهُ مَذْقَةً"" : لَبَناً مَمْزُوجاً بِالْمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14615, 'مَارِجٌ', 'مارج', 'جامد', 'مرج', 'مارج', 'مرج', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَارِجٌ-مَارِجٌ [م ر ج].الرحمن آية 15 وَخَلَقَ الجَانَّ مِنْ مَارِجٍ مِنْ نَارٍ (قرآن) : شِهَابٌ سَاطِعٌ ذُو لَهَبٍ شَدِيدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14616, 'مَرْجَانٌ', 'مرجان', 'جامد', 'مرج', 'مرجان', 'مرجن', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَرْجَانٌ-مَرْجَانٌ، ةٌ [م ر ج]. 1.: جِنْسُ حَيَوَانَاتٍ بَحْرِيَّةٍ مِنْ فَصِيلَةِ الْمَرْجَانِيَّاتِ، لَهَا عُرُوقٌ حُمْرٌ كَأَصَابِعِ الكَفِّ، تُفْرِزُ حَصىً بِأَلْوَانٍ زَاهِيَةٍ عَدِيدَةٍ يَغْلِبُ عَلَيْهَا الأَحْمَرُ وَالوَرْدِيُّ، تُعَدُّ مِنَ الأَحْجَارِ الكَرِيمَةِ. الرحمن آية 22 يَخْرُجُ مِنْهَا اللُّؤْلُؤُ وَالْمَرْجَانُ(قرآن). 2.: نَوْعٌ مِنَ السَّمَكِ زَعَانِفُهُ حُمْرٌ، يَكْثُرُ في البَحْرِ الأَبْيَضِ الْمُتَوَسِّطِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14617, 'مَرْجٌ', 'مرج', 'جامد', 'مرج', 'مرج', 'مرج', '', '', '', 'مفرد', 'DnN', '', '', '"مُرُوجٌ"', '', 'R', '', '', '', '', '', '', '". ""تَرْعَى الْمَاشِيَةُ فيِ الْمَرْجِ"": أَرْضٌ ذَاتُ نَبَاتٍ وَمَرْعًى. ""فَلَمْ يَزَلْ يَدِبُّ حَتَّى أَتَى مَرْجاً خَصِيباً كَثِيرَ الْمَاءِ وَالكَلَأِ"". (ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14618, 'مُرُوجٌ', 'مروج', 'جامد', '', 'مروج', 'مرج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14619, 'مَرْجَانِيَّاتٌ', 'مرجانيات', 'جامد', '', 'مرجانيات', 'مرجنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"مَرْجَانِيَّاتٌ-مَرْجَانِيَّاتٌ (حو).: فَصِيلَةٌ حَيَوَانِيَّةٌ بَحْرِيَّةٌ مِنْ صِنْفِ الْمُجَوَّفَاتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14620, 'مَرْدَدُوشٌ', 'مرددوش', 'جامد', '', 'مرددوش', 'مرددش', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"مَرْدَدُوشٌ-مَرْدَدُوشٌ (نب).: نَبَاتٌ مِنْ فَصِيلَةِ الشَّفَوِيَّاتِ، وَهُوَ نَوْعٌ مِنَ الرَّيَاحِينِ، دَقِيقُ الوَرَقِ، زَهْرُهُ أَبْيَضُ عَطِرٌ، تُحَضَّرُ مِنْهُ بَعْضُ الأَدْوِيَةِ، يُقَالُ لَهُ أَيْضاً سَمْسَقٌ، مَرْدَقوشٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14621, 'أَمَرٌّ', 'أمر', 'جامد', 'مرر', 'ءمر', 'مر', '', '', '', 'مفرد', 'DnN', '', '', '"مثنىأَمَرَّانِ-أَمَرَّانِ"', '', '', '', '', '', '', '', '', '"أَمَرَّانِ-أَمَرَّانِ [م ر ر]. 1.""لَقِيَ مِنْهُ الأمَرَّيْنِ"" : كُلَّ أَنْواعِ الْمَصائِبِ، أَي الشَّرَّ وَالأَمْرَ العَظيمَ. ‌2.""أَصابَهُ الأمَرَّانِ"" : الهَرَمُ وَالْمَرَضُ أَوِ الهَرَمُ وَالفَقْرُ أَوِ العُرْيُ وَالجُوعُ. 3.""يُعانِي الأمَرَّيْنِ"": الجُوعُ والعَطَشُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14622, 'ضُرْمٌ', 'ضرم', 'جامد', 'ضرم', 'ضرم', 'ضرم', 'صِيغَةُ فَعِل', '', '', 'مفرد', '', '', '', '"(نب)"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ضُرْمٌ-ضُرْمٌ (نب) . : نَبَاتٌ بَرِّيٌّ، طَيِّبُ الرَّائِحَةِ، لَهُ وَرَقٌ يُشْبِهُ وَرَقَ الشِّيحِ، وَثَمَرُهُ أَحْمَرُ يُقَارِبُ شَكْلَ البَلُّوطِ، زَهْرُهُ أَبْيَضُ صَغِيرٌ شَبِيهٌ بِالصَّعْتَرِ، كَثِيرُ العَسَلِ. يُسْتَخْرَجُ مِنْهُ عِطْرُ الْخُزَامَى وَدُهْنُهُ، وَالضُّرْمُ مِنْ أَجْوَدِ أَنْوَاعِ الْخُزَامَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14623, 'مَسَامِيرُ', 'مسامير', 'جامد', '', 'مسامير', 'مسمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ن. مِسْمَارٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14624, 'وَقُودٌ', 'وقود', 'جامد', 'وقد', 'وقود', 'قد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَقُودٌ-وَقُودٌ [و ق د] (صِيغَةُ فَعُول). 1.""وَقُودُ النَّارِ"" : مَا تُوقَدُ بِهِ. 2.""وَقُودُ السَّيَّارَاتِ"" : النَّفْطُ، البِتْرُولُ، إِذْ يَتَوَلَّدُ مِنِ احْتِرَاقِهَا طَاقَةٌ حَرَارِيَّةٌ، وَيُطْلَقُ عَلَى كُلِّ مَادَّةٍ مِنْ هَذَا النَّوْعِ كَالغَازِ مَثَلاً. ""مَخْزَنُ الوَقُودِ"". 3. ""الوَقُودُ النَّوَوِيُّ"" : الْمَادَّةُ القَابِلَةُ لِلانْشِطَارِ، تُسْتَعْمَلُ فِي الْمُفَاعِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14625, 'جَلاَدَةٌ', 'جلادة', 'جامد', 'جلد', 'جلادة', 'جلدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"جَلاَدَةٌ - [ج ل د]. (صف). ""أَظْهَرَ جَلاَدَةً"" : الصَّبْرَ، الصَّلاَبَةَ، الشِّدَّة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14626, 'مَرَاسَةٌ', 'مراسة', 'جامد', 'مرس', 'مراسة', 'مرسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مَرَاسَةٌ-مَرَاسَةٌ [م ر س]. ""مَرَاسَةُ عَمَلٍ"" : شِدَّتُهُ، قُوَّتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14627, 'مَرِيسَةٌ', 'مريسة', 'جامد', 'مرس', 'مريسة', 'مرسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَرَائِسُ"', '', 'R', '', '', '', '', '', '', '". ""تَنَاوَلَ مَرِيسَةً"": عَجِينَة البَطَاطَا الْمَسْلُوقَةِ فِي الْمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14628, 'مَرَائِسُ', 'مرائس', 'جامد', '', 'مراءس', 'مرس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14629, 'مَرِيسٌ', 'مريس', 'جامد', 'مرس', 'مريس', 'مرس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَرِيسٌ-مَرِيسٌ [م ر س].: كُلُّ مَا أُنْقِعَ فِي اللَّبَنِ أَوِ الْمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14630, 'مَرْسَةٌ', 'مرسة', 'جامد', '', 'مرسة', 'مرسة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"مَرَسٌ:أَمْرَاسٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: مَرَسٌ، أَمْرَاسٌ. ""أَمْرَاسُ الْمَرْكَبِ"" : أَطْنَابُهُ، حِبَالُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14631, 'مَرَسٌ', 'مرس', 'جامد', '', 'مرس', 'مرس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14632, 'أَمْرَاسٌ', 'أمراس', 'جامد', '', 'ءمراس', 'مرس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14633, 'مَرْسَحٌ', 'مرسح', 'جامد', '', 'مرسح', 'مرسح', '', '', '', 'جمع تكسير', 'DnN', '', '', '"مَرَاسِحُ"', '', 'R', '', '', '', '', '', '', '"ج: مَرَاسِحُ. : مَكَانٌ مُعَدٌّ لِلتَّمْثِيلِ أَوِ الرَّقْصِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14634, 'مَرَاسِحُ', 'مراسح', 'جامد', '', 'مراسح', 'مرسح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14635, 'مَرْقَةٌ', 'مرقة', 'جامد', 'مرق', 'مرقة', 'مرقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ن. مَرَقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14636, 'مَرَقٌ', 'مرق', 'جامد', 'مرق', 'مرق', 'مرق', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَرَقٌ-مَرَقٌ، ةٌ [م ر ق] (طخ). ""يَغْمِسُ الخُبْزَ فِي الْمَرَقِ"": كُلُّ مَاءٍ أُغْلِيَ فِي اللَّحْمِ وَالشَّحْمِ وَصَارَ دَسِماً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14637, 'مِرْكَازٌ', 'مركاز', 'جامد', '', 'مركاز', 'مركز', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِرْكَازٌ-مِرْكَازٌ، مِرْكَاسٌ (طخ).: مِعًى مَحْشُوَّةٌ بِاللَّحْمِ وَالشَّحْمِ الْمَفْرُومِ عَلَى شَكْلِ أَصَابِعَ، تُؤْكَلُ مَشْوِيَّةً أَوْ مَقْلِيَّةً. ن. قتيبة. مَقانِقُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14638, 'مُرَكَّبَاتٌ', 'مركبات', 'جامد', '', 'مركبات', 'مركبت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ، وَهِيَ مِنْ أَكْبَرِ الفَصَائِلِ النَّبَاتِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14639, 'مَرْمَرٌ', 'مرمر', 'جامد', 'مرمر', 'مرمر', 'مرمر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَرْمَرٌ-مَرْمَرٌ [م ر م ر]. ""بَيْتٌ مِنْ رُخَامٍ وَمَرْمَرٍ"" : نَوْعٌ مِنَ الرُّخَامِ صَلْبٌ شَدِيدُ الصَّفَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14640, 'مُرِّيٌّ', 'مري', 'جامد', 'مري', 'مري', 'مر', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُرِّيٌّ-مُرِّيٌّ [م ر ي].: تَوَابِلُ تُطَيِّبُ الطَّعَامَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14641, 'مَرِيءٌ', 'مريء', 'جامد', 'مرأ', 'مريء', 'مر', '', '', '', 'مفرد', 'Dz', '', '', '"أَمْرِئَةٌ:مُرُؤٌ"', '', 'Rz', '', '', '', '', '', '', '"ج: أَمْرِئَةٌ، مُرُؤٌ : مَجْرَى الطَّعَامِ مِنَ الْحُلْقُومِ إِلَى الْمَعِدَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14642, 'أَمْرِئَةٌ', 'أمرئة', 'جامد', '', 'ءمرءة', 'مرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14643, 'مُرُؤٌ', 'مرؤ', 'جامد', '', 'مرء', 'مر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14644, 'مِرِّيخ', 'مريخ', 'جامد', '', 'مريخ', 'مرخ', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', 'N', 'O', 'N', 'O', '', '"مِرِّيخ-مِرِّيخ (فك). 1.: كَوْكَبٌ سَيَّارٌ وَهُوَ الرَّابِعُ فِي النِّظَامِ الشَّمْسِيِّ، أَصْغَرُ مِنَ الأَرْضِ وَيُعْرَفُ بِمَارس. 2. ""الْمِرِّيخُ"" : يُطْلَقُ عَلَى شَهْرِ مَارس حَسَبَ اليَوْمِيَّةِ اللِّيبِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14645, 'مِزَاجٌ', 'مزاج', 'جامد', 'مزج', 'مزاج', 'مزج', '', '', '', 'مفرد', 'DnN', '', '', '"أَمْزِجَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""مِزَاجُ العَصِيرِ"" : مَا يُمْزَجُ بِهِ كَالْمَاءِ أَوِ الْحَلِيبِ وَنَحْوِهِ. 2.""لَهُ مِزَاجٌ حَادٌّ"" : مَا جُبِلَتْ عَلَيْهِ النَّفْسُ مِنْ أَحْوَالٍ وَطَبَائِعَ. ""هَذَا لاَ يُوَافِقُ مِزَاجَهُ"" ""لَطِيفُ المِزَاجِ"" ""عَصَبِيُّ المِزَاجِ"" ""كَانَتْ ذَاتَ مِزاجٍ حادٍّ يَنْفَعُها في زَرْعِ الرُّعْبِ"". (أحمد التوفيق)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14646, 'أَمْزِجَةٌ', 'أمزجة', 'جامد', '', 'ءمزجة', 'مزجة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14647, 'مِزْجٌ', 'مزج', 'جامد', 'مزج', 'مزج', 'مزج', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مِزْجٌ-مِزْجٌ [م ز ج]. 1.""مِزْجُ النَّحْلِ"" : شَهْدُهُ، عَسَلُهُ. 2.""مِزْجُ الْخَمْرِ"" : الْمَاءُ البَارِدُ الَّذِي تُمْزَجُ بِهِ. 3.: لَوْزٌ مُرٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14648, 'مَزَّةٌ', 'مزة', 'جامد', 'مزز', 'مزة', 'مزة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَزَّةٌ-مَزَّةٌ [م ز ز]. 1.""مَزَّةُ الشَّرَابِ"" : مَا يُؤْكَلُ عَلَى الشَّرَابِ مِنْ مُخَلِّلاَتٍ وَنَحْوِهَا. 2.""خَلَّفَتِ الحَمْضِيَّةُ مَزَّةً فِي أَسْنَانِهَا"" : مَذَاقاً بَيْنَ الحُلْوِ وَالْحَامِضِ. اِسْقِنِـي وَاسْـقِ يوسُـفا*مَـزَّةَ الطَّعْـمِ قَرْقَفَـا (أبو نواس)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14649, 'مِزْمَارِيَّاتٌ', 'مزماريات', 'جامد', '', 'مزماريات', 'مزمرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَةِ الوَحِيدَةِ، مَائِيَّةٌ، أَنْوَاعُهَا عَدِيدَةٌ، وَأَزْهَارُهَا عُنْقُودِيَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14650, 'مَزِيَّةٌ', 'مزية', 'جامد', 'مزي', 'مزية', 'مزة', '', '', '', 'مفرد', 'DnN', '', '', '"مَزَايَا"', '', '', '', '', '', '', '', '', '". ""يَتَمَيَّزُ بِمَزِيَّةِ حُبِّ الخَيْرِ"" : أَيْ بِفَضِيلَةِ ... ""مَزَايَاهُ لاَ تُعَدُّ وَلاَ تُحْصَى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14651, 'مَزَايَا', 'مزايا', 'جامد', '', 'مزايا', 'مز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14652, 'مِمْسَحَةٌ', 'ممسحة', 'جامد', 'مسح', 'ممسحة', 'ممسحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَمَاسِحُ"', '', 'R', '', '', '', '', '', '', '". ""بِيَدِهِ مِمْسَحَةٌ يَمْسَحُ بِهَا الزُّجَاجَ"" : مَا يُمْسَحُ بِهِ الشَّيْءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14653, 'مَمَاسِحُ', 'مماسح', 'جامد', '', 'مماسح', 'ممسح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14654, 'مَسَدٌ', 'مسد', 'جامد', 'مسد', 'مسد', 'مسد', '', '', '', 'مفرد', 'DnN', '', '', '"مِسَادٌ:أَمْسَادٌ"', '', 'R', '', 'N', 'O', 'N', 'O', '', '". 1.""حَبْلٌ مِنْ مَسَدٍ"" :حَبْلٌ مَضْفُورٌ مُحْكَمُ الفَتْلِ. ""وَفَتَلَ كُلُّ إِنْسَانٍ لِعَدُوِّهِ حَبْلاً مِنْ مَسَدٍ"". (التوحيدي). 2. الْمَسَدُ : سُورَةٌ مِنْ سُوَرِ القُرْآنِ المسد آية 5 فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ (قرآن) : أَيْ مِنْ لِيفٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14655, 'مِسَادٌ', 'مساد', 'جامد', '', 'مساد', 'مسد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14656, 'أَمْسَادٌ', 'أمساد', 'جامد', '', 'ءمساد', 'مسد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14657, 'مَسَاسٌ', 'مساس', 'جامد', 'مسس', 'مساس', 'مسس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَسَاسٌ-مَسَاسٌ [م س س]. ""إِضَافَاتٌ لاَ مَسَاسَ لَهَا بِصُلْبِ الْمَوْضُوعِ"" : لاَ عَلاَقَةَ لَهَا. ""عِلْمٌ لَهُ مَسَاسٌ بِاخْتِصَاصَاتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14658, 'مِسَاسٌ', 'مساس', 'جامد', 'مسس', 'مساس', 'مسس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِسَاسٌ-مِسَاسٌ [م س س]. 1.""لاَ مِسَاسَ بِهَذَا"" : أَيْ لاَ تَلْمَسْهُ، لاَ تَمَسَّهُ. طه آية 97 قَالَ فَاذْهَبْ فَإِنَّ لَكَ فِي الْحَيَاةِ أَنْ تَقُولَ لاَ مِسَاسَ (قرآن). 2.""لاَ يَنْبَغِي الْمِسَاسُ بِحُقُوقِ الإِنْسَانِ"": أَيْ لاَ يَنْبَغِي التَّعَرُّضُ لَهَا بِأَذىً أَوِ النَّيْلُ مِنْهَا. 3.""عِنْدَ مِسَاسِ الْحَاجَةِ"" : عِنْدَ الضَّرُورَةِ الْمُلِحَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14659, 'مَسِيسٌ', 'مسيس', 'جامد', 'مسس', 'مسيس', 'مسس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مَسِيسٌ-مَسِيسٌ [م س س] . ""هُوَ فِي مَسِيسِ الْحَاجَةِ إِلَى الْمُسَاعَدَةِ"" : فِي ضَرُورَةٍ مُلِحَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14660, 'مُمَاسَّةٌ', 'مماسة', 'جامد', 'مسس', 'مماسة', 'ممسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مُمَاسَّةٌ-مُمَاسَّةٌ [م س س] (هن). ""نُقْطَةُ الْمُمَاسَّةِ"" : نُقْطَةُ الاتِّصَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14661, 'مُمَاسٌّ', 'مماس', 'جامد', 'مسس', 'مماس', 'ممس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مُمَاسٌّ-مُمَاسٌّ [م س س] (هن). ""خَطٌّ مُمَاسٌّ"" : خَطٌّ مُسْتَقِيمٌ مُتَلاَمِسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14662, 'مَاسِكَةٌ', 'ماسكة', 'جامد', 'مسك', 'ماسكة', 'مسكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَاسِكَةٌ-مَاسِكَةٌ [م س ك]. 1.: قِشْرَةٌ تَعْلُو وَجْهَ الصَّبِيِّ أَوِ الْمُهْرِ. 2.""بَيْنَنَا مَاسِكَةُ رَحِمٍ"" : أَيْ قَرَابَةٌ مُتَّصِلَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14663, 'مَسَّاكٌ', 'مساك', 'جامد', 'مسك', 'مساك', 'مسك', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَسَاسِيكُ"', '', '', '', '', '', '', '', '', '".: سَاقٌ صَغِيرَةٌ مِنْ مَعْدِنٍ أَوْ نَحْوِهِ، لَهَا رَأْسٌ يُسْتَخْدَمُ لِمَسْكِ الأَشْيَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14664, 'مَسَاسِيكُ', 'مساسيك', 'جامد', '', 'مساسيك', 'مسسك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14665, 'مُسْكَةٌ', 'مسكة', 'جامد', 'مسك', 'مسكة', 'مسكة', '', '', '', 'مفرد', 'DnN', '', '', '"مُسَكٌ"', '', 'R', '', '', '', '', '', '', '". 1.""مُسْكَةُ الشَّيْءِ"" : مَا يُتَمَسَّكُ بِهِ. 2.""مُسْكَةُ البَابِ"" : مَقْبِضُهُ. 3.""مُسْكَةُ الرَّجُلِ"" : عَقْلُهُ الوَافِرُ. 4.""يَعِيشُ فِي مُسْكَةٍ"" : فِي بُخْلٍ. 5.""مَا فِيهِ مُسْكَةٌ"" : لاَ خَيْرَ فِيهِ. 6.""لَيْسَ لأَمْرِهِ مُسْكَةٌ"" : أَيْ لاَ أَصْلَ لَهُ يُعْتَمَدُ عَلَيْهِ فِيهِ. 7.""فِيهِ مُسْكَةٌ مِنْ خَيْرٍ"" : أَيْ بَقِيَّةٌ. 8.""مَا فِي إِنَائِهِ مُسْكَةٌ مِنْ مَاءٍ"" : أَيْ قَلِيلٌ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14666, 'مُسَكٌ', 'مسك', 'جامد', '', 'مسك', 'مسك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14667, 'مَسَكٌ', 'مسك', 'جامد', 'مسك', 'مسك', 'مسك', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَسَكٌ-مَسَكٌ [ م س ك]. 1.""مَسَكُ الأَرْضِ"" : طِبَاقُهَا. 2.""مَسَكُ الْمَرْأَةِ"" : أَسَاوِرُهَا وَخَلاَخِيلُهَا مِنْ قُرُونٍ أَوْ عَاجٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14668, 'مُسْكٌ', 'مسك', 'جامد', 'مسك', 'مسك', 'مسك', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِسْكٌ-مِسْكٌ (مذ، مؤ). وَاحِدَتُهُ مِسْكَةٌ. ج: مِسَكٌ. [م س ك]. 1.: نَوْعٌ مِنَ الطِّيبِ يُحَضَّرُ مِنْ دَمِ الغَزَالِ. 2.""مِسْكُ الخِتَامِ"" : خَاتِمَةٌ حَسَنَةٌ. ""مِسْكُ الخِتَامِ آيَاتٌ مِنَ القُرْآنِ"": أَيْ أَجْمَلُ مَا يُخْتَتَمْ بِهِ لِيَتْرُكَ أَثَراً فِي الخِتَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14669, 'مِسْكٌ', 'مسك', 'جامد', 'مسك', 'مسك', 'مسك', '', '', '', 'مفرد', 'DnN', '', '', '"مِسَكٌ(مذ:مؤ)وَاحِدَتُهُمِسْك', '', 'R', '', '', '', '', '', '', '"مُسْكٌ-مُسْكٌ [م س ك]. 1.""مُسْكُ الرَّجُلِ"" : عَقْلُهُ الوَافِرُ. 2.""مُسْكُ الأَبْدَانِ"" : مَا يُمْسِكُهَا مِنْ شَرَابٍ أَوْ طَعَامٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14670, 'مِسَكٌ', 'مسك', 'جامد', '', 'مسك', 'مسك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14671, 'مَشِيجٌ', 'مشيج', 'جامد', 'مشج', 'مشيج', 'مشج', '', '', '', 'مفرد', 'DnN', '', '', '"أَمْشَاجٌ"', '', 'R', '', '', '', '', '', '', '". 1."" لَوْنٌ مَشِيجٌ"" : أَيْ كُلُّ لَوْنَيْنِ اخْتَلَطَا. 2.الإنسان آية 2 إِنَّا خَلَقْنَا الإِنْسَانَ مِنْ نُطْفَةٍ أَمْشَاجٍ (قرآن) : أَيْ مِنْ نُطْفَتَيْنِ مُخْتَلِطَتَيْنِ. 3.""الْمَشِيجُ"": الخَلِيَّةُ ذَكَرِيَّةٌ أَوْ أُنْثَوِيَّةٌ قَبْلَ انْدِمَاجِهَا وَتَلاَقُحِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14672, 'أَمْشَاجٌ', 'أمشاج', 'جامد', '', 'ءمشاج', 'مشج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14673, 'مَشْرَبِيَّةٌ', 'مشربية', 'جامد', '', 'مشربية', 'مشربة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"ج: ـات. ""يُطِلُّ مِنَ الْمَشْرَبِيَّةِ"" : شُرْفَةٌ مِنَ المِعْمَارِالقَدِيمِ مُغْلَقَةُ، تُطِلُّ عَلَى الأَمَاكِنِ الَّتِي حَوْلَهَا. ""تُهْـرَعُ إِلَـىالْمَشْرَبِيَّةِ فَتَمُدُّ بَصَرَهَا الزَّائِغَ مِنْ ثُقُوبِهَا"". (ن. محفوظ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14674, 'مَشَّاطَةٌ', 'مشاطة', 'جامد', 'مشط', 'مشاطة', 'مشطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَشَّاطَةٌ-مَشَّاطَةٌ [م ش ط].: الْمَرْأَةُ الَّتِي تَعْتَنِي بِمَشْطِ شَعْرِ النِّسَاءِ، الْمَاشِطَةُ، الوَصِيفَةُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14675, 'مُشَاطَةٌ', 'مشاطة', 'جامد', 'مشط', 'مشاطة', 'مشطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مُشَاطَةٌ-مُشَاطَةٌ [م ش ط]. : مَا يَسْقُطُ مِنَ الشَّعْرِ عِنْدَ مَشْطِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14676, 'مَشَّاطٌ', 'مشاط', 'جامد', 'مشط', 'مشاط', 'مشط', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مَشَّاطٌ-مَشَّاطٌ [م ش ط].: مَنْ يَصْنَعُ الْمُشْطَ أَوْ يَبيعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14677, 'مُشْطٌ', 'مشط', 'جامد', 'مشط', 'مشط', 'مشط', '', '', '', 'مفرد', 'DnN', '', '', '"أَمْشَاطٌ"', '', 'R', '', '', '', '', '', '', '". 1. : آلَةٌ يُنْسَجُ بِهَا، مِنْسَجٌ. ""ضَرَبَالنَّاسِجُ بِمُشْطِهِ"". 2.""مُشْطُ القَدَمِ"" : جُزْءُ القَدَمِ الَّذِي يَقَعُ بَيْنَ رُسْغِهَا وَأَصَابِعِهَا. ""اِنْكَسَرَ مُشْطُ قَدَمِهِ"". 3.""مُشْطُ الكَتِفِ"" : عَظْمُهَا العَرِيضُ. 4. : خَشَبَةٌ عَرِيضَةٌ يُغَطَّى بِهَا الْحَبُّ بَعْدَ أَنْ يُنْثَرَ فِي الأَرْضِ. 5.: جِنْسُ سَمَكٍ نَهْرِيٍّ أَوْ بَحْرِيٍّ مِنْ فَصِيلَةِ الْمُشْطِيَّاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14678, 'أَمْشَاطٌ', 'أمشاط', 'جامد', '', 'ءمشاط', 'مشط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14679, 'مُشْطِيَّاتٌ', 'مشطيات', 'جامد', 'مشط', 'مشطيات', 'مشطت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"مُشْطِيَّاتٌ-مُشْطِيَّاتٌ [م ش ط]. : فَصِيلَةٌ أَسْمَاكٍ مِنْ شَائِكَاتِ الزَّعَانِفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14680, 'مِمْشَطٌ', 'ممشط', 'جامد', 'مشط', 'ممشط', 'ممشط', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مِمْشَطٌ-مِمْشَطٌ، ةٌ [م ش ط]. : مِشْطٌ، أَيْ أَدَاةٌ يُمْشَطُ بِهِا الشَّعْرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14681, 'مِمْشَقَةٌ', 'ممشقة', 'جامد', 'مشق', 'ممشقة', 'ممشقة', '', '', '', 'مفرد', 'DnN', '', '', '"مَمَاشِقُ"', '', 'R', '', '', '', '', '', '', '". ""مِمْشَقَةُ الثِّيَابِ"" : أَدَاةٌ كَالْمُشْطِ لِمَشْقِ الثِّيَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14682, 'مَمَاشِقُ', 'مماشق', 'جامد', '', 'مماشق', 'ممشق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14683, 'أُمْسِيَّةٌ', 'أمسية', 'جامد', 'مسو', 'ءمسية', 'مسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَماسِيُّ"', '', '', '', '', '', '', '', '', '". 1.""وَصَلَ أُمْسِيَّةً"" : مِنْ آخِرِ النَّهارِ إلى مُنْتَصَفِ اللَّيْلِ، مساءً. 2.""حَضَرَ أُمْسِيَّةً شِعْرِيَّةً"" : قِراءاتٍ شِعْرِيَّةً في الْمَساءِ. 3.""قَضَيْنا أُمْسِيَّةً فَنِّيَّةً"" : أَي سَهْرَةً، حَفْلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14684, 'أَماسِيُّ', 'أماسي', 'جامد', '', 'ءماسي', 'مس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14685, 'مَاشِيَةٌ', 'ماشية', 'جامد', 'مشي', 'ماشية', 'مشة', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَاشٍ:الْمَوَاشِي"', '', '', '', '', '', '', '', '', '".: الإِبِلُ وَالبَقَرُ وَالغَنَمُ وَيَكْثُرُ اسْتِعْمَالُهَا لِلْغَنَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14686, 'مَوَاشِي', 'مواشي', 'جامد', '', 'مواشي', 'مش', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14687, 'مُشَاةٌ', 'مشاة', 'جامد', 'مشي', 'مشاة', 'مشة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُشَاةٌ-مُشَاةٌ [م ش ي]. ""فَيْلَقٌ مِنَ الْمُشَاةِ"" : فَيْلَقٌ عَسْكَرِيٌّ يُحَارِبُ مَشْياً عَلَى الأَقْدَامِ، الرَّجَّالَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14688, 'مَشَّايَةٌ', 'مشاية', 'جامد', 'مشي', 'مشاية', 'مشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""يَنْتَعِلُ الْمَشَّايَةَ فِي البَيْتِ"" : نَعْلٌ،خُفٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14689, 'مَمْشًى', 'ممشى', 'جامد', 'مشي', 'ممشى', 'ممش', '', '', '', 'مفرد', 'Dy', '', '', '"مَمَاشٍ:الْمَمَاشِي"', '', '', '', '', '', '', '', '', '". ""مَمْشَى الْحَدِيقَةِ"" : مَكَانُ التَّمَشِّي والْمُرُورِ. ""رَأَيْتُهَا تَسِيرُ فِي الْمَمْشَى الْجَانِبِيِّ وتَتَقَدَّمُ مِنَ المِنَصَّةِ"". (جبرا إبراهيم جبرا)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14690, 'مَمَاشِي', 'مماشي', 'جامد', '', 'مماشي', 'ممش', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14691, 'مَسَاءٌ', 'مساء', 'جامد', 'مسو', 'مساء', 'مس', '', '', '', 'مفرد', 'Dz', '', '', '"أَمْسِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '". 1.""حَلَّ الْمَسَاءُ"" : زَمَانٌ بَيْنَ الظُّهْرِ وَالْمَغْرِبِ، أَوْ وَقْتَ غُرُوبِ الشَّمْسِ وَزَوَالِهَا. ""مَا أَرْوَعَ الْمَسَاءَ أَنْ يَأْتِيَ الْمَسَاءُ فِي كُلِّ مَسَاءٍ "". (أ. عبد الغني). 2.""مَسَاءُ الخَيْرِ"" : لِيَكُنْ حُلُولُ بِدَايَةِ اللَّيْلِ خَيْراً. 3.""يَزُورُهُ صَبَاحَ مَسَاءَ"" : فِي أَوَّلِ النَّهَارِ وَفِي آخِرِهِ، مَبْنِيَّتَيْنِ عَلَى الفَتْحِ، أَيْ صَبَاحاً وَمَسَاءً. 4.""مَسَاءَ أَمْسٍ"" : البَارِحَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14692, 'أَمْسِيَةٌ', 'أمسية', 'جامد', '', 'ءمسية', 'مسة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14693, 'مُصَّانٌ', 'مصان', 'جامد', '', 'مصان', 'مصن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مُصَّانٌ-مُصَّانٌ (نب).: قَصَبُ السُّكَّرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14694, 'مِصْرٌ', 'مصر', 'جامد', 'مصر', 'مصر', 'مصر', '', '', '', 'مفرد', 'DnN', '', '', '"أَمْصَارٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""اِنْتَقَلَ مِنْ مِصْرٍ إِلَى مِصْرٍ"" : مِنْ بِلاَدٍ إِلَى بِلاَدٍ، مِنْ مَدِينَةٍ إِلَى مَدِينَةٍ. 2.""بِلاَدُ مِصْرَ"" : مِنَ البُلْدَانِ العَرَبِيَّةِ (جُمْهُورِيَّةُ مِصْرَ العَرَبِيَّةِ) عَاصِمَتُهَا القَاهِرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14695, 'أَمْصَارٌ', 'أمصار', 'جامد', '', 'ءمصار', 'مصر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14696, 'مَصِيرٌ', 'مصير', 'جامد', 'مصر', 'مصير', 'مصر', '', '', '', 'مفرد', 'DnN', '', '', '"مُصْرَانٌ:أَمْصِرَةٌ:مَصَارِي', '', 'R', '', '', '', '', '', '', '".: الْمِعَى الَّتِي يَنْتَقِلُ إِلَيْهَا الطَّعَامُ بَعْدَ الْمَعِدَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14697, 'مُصْرَانٌ', 'مصران', 'جامد', '', 'مصران', 'مصرن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14698, 'أَمْصِرَةٌ', 'أمصرة', 'جامد', '', 'ءمصرة', 'مصرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14699, 'مَصَارِينُ', 'مصارين', 'جامد', '', 'مصارين', 'مصرن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14700, 'مَصَّاصَةٌ', 'مصاصة', 'جامد', 'مصص', 'مصاصة', 'مصصة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""مَصَّاصَةٌ لَذِيذَةٌ"": حَلْوَى يَمْتَصُّهَا الأَطْفَالُ. 2.""مَصَّاصَةُ العَصِيرِ"" : القَصَبَةُ الهَشَّةُ يُشْرَبُ بِهَا مِنَ القِينِّنَةِ أَوِ الكَأْسِ، شَفَّاطَةٌ، مِمَصٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14701, 'مُصَاصَةٌ', 'مصاصة', 'جامد', 'مصص', 'مصاصة', 'مصصة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مُصَاصَةٌ-مُصَاصَةٌ [م ص ص]. ""مُصَاصَةُ قَصَبِ السُّكَّرِ"" : مَا يُمَصُّ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14702, 'مُصَيْصَةٌ', 'مصيصة', 'جامد', 'مصص', 'مصيصة', 'مصصة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""مُصَيْصَةُ الرَّضِيعِ"": مَصَّاصَةٌ مَطَّاطِيَّةٌ، لَهَا رَأْسٌ شَبِيهٌ بِحَلَمَةِ الثَّدْيِ، تُعْطَى لِلرَّضِيعِ لِيَكُفَّ عَنِ البُكَاءِ، وَلِكَيْ لاَ يَرْضَعَ أُصْبُعَهُ. 2.: نَوْعٌ مِنَ الْحَلْوَى مُثْبَتٌ فِي رَأْسِ عُودٍ، يَمُصُّهَا الأَطْفَالُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14703, 'مِمَصٌّ', 'ممص', 'جامد', 'مصص', 'ممص', 'ممص', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1. : أُنْبُوبٌ مُلْتَوٍ يُسْتَخْدَمُ لِنَقْلِ سَائِلٍ مِنْ مُسْتَوىً إِلَى مُسْتَوَى آخَرَ أَدْنَى مِنْهُ. 2. : أُنْبُوبٌ مُلْتَوٍ مَرَّتَيْنِ يُسْتَخْدَمُ لإِفْرَاغِ المِيَاهِ الْمُسْتَعْمَلَةِ وَيَمْنَعُ انْتِشَارَ الرَّوَائِحِ الكَرِيهَةِ. 3. : دَوْرَقٌ مِنْ زُجَاجٍ ثَخِينٍ، مَشْدُودٌ بِأُنْبُوبٍ، لَهُ صِمَامٌ تَتَحَكَّمُ فِي اشْتِغَالِهِ دَافِعَةٌ لِلْحُصُولِ عَلَى جَرَيَانِ سَائِلٍ تَحْتَ الضَّغْطِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14704, 'مُصْطَكَى', 'مصطكى', 'جامد', '', 'مصطكى', 'مصطك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R0', '', 'N', 'O', 'O', 'O', '', '"مُصْطَكَى-مُصْطَكَى(نب).: شَجَرٌ مِنْ فَصِيلَةِ البَطْمِيَّاتِ، قَرِيبٌ مِنَ البَطْمِ، بَرِّيُّ، تُسْتَخْرَجُ مِنْهُ مَادَّةٌ صَمْغِيَّةٌ لَزِجَةٌ، وَهُوَ نَوْعَانِ: أَبْيَضُ نَاعِمٌ، طَيِّبُ الرَّائِحَةِ، وَأَسْوَدُ مَائِلٌ إِلَى الحُمْرَةِ، يَكْثُرُ في سَوَاحِلِ الشَّامِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14705, 'مَصَالَةٌ', 'مصالة', 'جامد', 'مصل', 'مصالة', 'مصلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مَصَالَةٌ-مَصَالَةٌ [م ص ل ]. ""مَصَالَةُ الجَرَّةِ"" : مَا قَطَرَ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14706, 'مِمْصَلٌ', 'ممصل', 'جامد', 'مصل', 'ممصل', 'ممصل', '', '', '', 'مفرد', 'DnN', '', '', '"مَمَاصِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""وَضَعَ الْمَصْلَ فِي الْمِمْصَلِ"" : وِعَاءُ الْمَصْلِ. 2.""رَجُلٌ مِمْصَلٌ"" : يُنْفِقُ مَالَهُ فِي الفَسَادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14707, 'مَمَاصِلُ', 'مماصل', 'جامد', '', 'مماصل', 'ممصل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14708, 'مَضِيرٌ', 'مضير', 'جامد', 'مضر', 'مضير', 'مضر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَضِيرٌ-مَضِيرٌ [م ض ر]. ""لَبَنٌ مَضِيرٌ"" : حَامِضٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14709, 'مُضَاضٌ', 'مضاض', 'جامد', 'مضض', 'مضاض', 'مضض', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مُضَاضٌ-مُضَاضٌ [م ض ض]. 1.""شَرِبَ الْمُضَاضَ"" : الْمَاءَ الْمَالِحَ. 2.""هُوَ مِنْ مُضَاضِ القَوْمِ"" : مِنْ خَالِصِهِمْ نَسَباً. 3.""بِعَيْنِهِ مُضَاضٌ"" : وَجَعٌ، أَلَمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14710, 'مَاضِغٌ', 'ماضغ', 'جامد', 'مضغ', 'ماضغ', 'مضغ', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَوَاضِغُمثنىمَاضِغَانِ"', '', '', '', '', '', '', '', '', '"1.:أَصْلُ اللَّحْيِ عِنْدَ مَنْبِتِ الأَضْرَاسِ، وَهُمَا مَاضِغَانِ. 2.:الأَضْرَاسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14711, 'مَوَاضِغُ', 'مواضغ', 'جامد', '', 'مواضغ', 'مضغ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14712, 'مَطَّاطٌ', 'مطاط', 'جامد', '', 'مطاط', 'مطط', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَطَّاطٌ-مَطَّاطٌ (نب).: شَجَرُ الْمَطَّاطِ وَهُوَ مِنْ فَصِيلَةِ الغَرْبِيُونِيَّاتِ، مَهْدُهُ الأَصْلِيُّ أَمرِيكَا الْجَنُوبِيَّةُ، يَكْثُرُ فِي جُزُرِ الهِنْدِ الشَّرْقِيَّةِ، يُزْرَعُ فِي الْمَنَاطِقِ الْحَارَّةِ، عُصَارَتُهُ تُسْتَخْدَمُ فِي صِنَاعَةِ الْمَطَّاطِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14713, 'مَطَرِيَّةٌ', 'مطرية', 'جامد', 'مطر', 'مطرية', 'مطرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '".: أَدَاةٌ تُحَمَلُ لِلْوِقَايَةِ مِنَ الْمَطَرِ، مُكَوَّنَةٌ مِنْ مِقْبَضٍ وَثَوْبٍ شَفَّافٍ يُنْشَرُ بِوَاسِطَةِ زِيرٍ عَلَى مِحْوَرٍ آلِيٍّ مُكَوَّنٍ مِنْ قُضْبَانٍ حَدِيدِيَّةٍ رَقِيقَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14714, 'مِمْطَرٌ', 'ممطر', 'جامد', 'مطر', 'ممطر', 'ممطر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَمَاطِرُ"', '', 'R', '', '', '', '', '', '', '". ""خَرَجَ مُرْتَدِياً مِمْطَرَةً فِي جَوٍّ مُمْطِرٍ"" : مِعْطَفٌ مُشَمَّعٌ يُلْبَسُ وَقْتَ الْمَطَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14715, 'مَمَاطِرُ', 'مماطر', 'جامد', '', 'مماطر', 'ممطر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14716, 'مَطْرَانٌ', 'مطران', 'جامد', '', 'مطران', 'مطرن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"مَطَارِنَةٌ:مَطَارِينُ"', '', 'R', '', '', '', '', '', '', '"ج: مَطَارِنَةٌ، مَطَارِينُ: رَئِيسُ الكَهَنَةِ عِنْدَ الْمَسِيحِيِّينَ، وَهِيَ رُتْبَةٌ فَوْقَ الأُسْقُفِ وَدُونَ البَطْرِيرِكِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14717, 'مَطَارِنَةٌ', 'مطارنة', 'جامد', '', 'مطارنة', 'مطرنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
