INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14719, 'مُطْرَانِيَّةٌ', 'مطرانية', 'جامد', '', 'مطرانية', 'مطرنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '": الأَبْرَشِيَّةُ، مَقَرُّ الْمَطْرَانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14720, 'مَطَرَةٌ', 'مطرة', 'جامد', '', 'مطرة', 'مطرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"1.: قِرْبَةُ الْمَاءِ. 2.""مَطَرَةُ الْمُسافِرِ"" : قِنِّينَةٌ مِنْ مَعْدِنٍ، لَهَا سَدَّادَةٌ يَضَعُ فِيهَا الْمُسَافِرُ الْمَاءَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14721, 'مَطَّاطٌ', 'مطاط', 'جامد', 'مطط', 'مطاط', 'مطط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَطَّاطٌ-مَطَّاطٌ [م ط ط]. 1.: مَادَّةٌ لَزِجَةٌ، وَهِيَ نَوْعَانِ: مَطَّاطٌ طَبِيعِيٌّ مُسْتَخْرَجٌ مِنْ تَجَلُّطِ عُصَارَةِ بَعْضِ أَنْوَاعِ الأَشْجَارِ كَشَجَرِ الْمَطَّاطِ. 2.""مَطَّاطٌ اِصْطِنَاعِيٌّ"" : وَهُوَ تَرْكِيبٌ مُعَقَّدٌ مُسْتَخْرَجٌّ مِنْ بَعْضِ مُشْتَقَّاتِ النَّفْطِ، وَلَهُ نَفْسُ خاَصِّيَّةِ الْمَطَّاطِ الطَّبِيعِيِّ نَفْسُها، يُسْتَخْدَمُ بِكَثْرَةٍ فِي الصِّنَاعَةِ الْحَدِيثَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14722, 'مَطِيلَةٌ', 'مطيلة', 'جامد', 'مطل', 'مطيلة', 'مطلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَطَائِلُ"', '', 'R', '', '', '', '', '', '', '". : أَدَاةٌ حَدِيثَةٌ مُسَطَّحَةٌ تُضْرَبُ سَوَاءٌ كَانَتْ بَارِدَةً أَوْ حَامِيَةً، وَتُمَدُّ، ثُمَّ تُطْبَعُ بَعْدَ الْمَطْلِ فَتُجْعَلُ صَفْحَةً وَتَكُونُ غَالِباً مَلْسَاءَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14723, 'مَطَائِلُ', 'مطائل', 'جامد', '', 'مطاءل', 'مطل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14724, 'مِطْلَمَةٌ', 'مطلمة', 'جامد', '', 'مطلمة', 'مطلمة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"مَطَالِمُ"', '', 'R', '', '', '', '', '', '', '"ج: مَطَالِمُ. : أَدَاةٌ خَشَبِيَّةٌ أوْ مَعْدِنِيَّةٌ يُبْسَطُ بِها عَجينُ الحَلَوِيَّاتِ قَبْلَ تَقْطيعِهِ، مِحْدَلَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14725, 'مَطَالِمُ', 'مطالم', 'جامد', '', 'مطالم', 'مطلم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14726, 'مَطِيَّةٌ', 'مطية', 'جامد', 'مطو', 'مطية', 'مطة', '', '', '', 'مفرد', 'DnN', '', '', '"مَطَايَا:مَطِيٌّ(مؤ:مذ)"', '', '', '', '', '', '', '', '', '". ""وَصَلَ رَاكِباً عَلَى مَطِيَّتِهِ"" : الدَّابَّةُ الَّتِي تُرْكَبُ. ""أَقِيمُوا بَنِي أُمِّي صُدُورَ مَطِيِّكُمْ"". (الشنفرى)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14727, 'مَطَايَا', 'مطايا', 'جامد', '', 'مطايا', 'مط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
