INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14729, 'مَعِيَّةٌ', 'معية', 'جامد', 'مع', 'معية', 'معة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَعِيَّةٌ-مَعِيَّةٌ [م ع]. 1. ""سَافَرَ بِمَعِيَّةِ الرَّئِيسِ"" : مَعَهُ، بِرُفْقَتِهِ، بِصُحْبَتِهِ. 2. ""وَاوُ الْمَعِيَّةِ"" : هِي الوَاوُ الَّتِي تَكُونُ بِمَعْنَى مَعَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14730, 'مَعَارِفُ', 'معارف', 'جامد', '', 'معارف', 'معرف', '', '', '', 'جمع تكسير', '', '', '', '"مفردمَعْرِفَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جمع مَعْرِفَة. 1.""اِتَّسَعَتْ مَعَارِفُهُ"" : عُلُومُهُ. ""حَصَلَ عَلَى مَعَارِفَ جَمَّةٍ"". 2.""وَزِيرُ الْمَعَارِفِ"" : وَزِيرُ التَّرْبِيَةِ الوَطَنِيَّةِ. 3.""مَعَارِفُ الرَّجُلِ"" : أَصْحَابُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14731, 'مَعْرِفَة', 'معرفة', 'جامد', '', 'معرفة', 'معرفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14732, 'مَعِدِيَّاتٌ', 'معديات', 'جامد', 'معد', 'معديات', 'معدت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"مَعِدِيَّاتٌ-مَعِدِيَّاتٌ [م ع د] (حو).""مَعِدِيَّاتُ الأَرْجُلِ"" : رُتْبَةٌ مِنَ الرِّخْوِيَّاتِ، مُتَمَيِّزَةٌ بِرِجْلٍ مُسَطَّحَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14733, 'مَعِدَةٌ', 'معدة', 'جامد', '', 'معدة', 'معدة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"مَعِدٌ:مِعَدٌ"', '', 'R', '', '', '', '', '', '', '"ج: مَعِدٌ، مِعَدٌ. ""اِمْتَلأَتْ مَعِدَتُهُ بِالأَكْلِ"": الكِيسُ الْمُرْتَبِطُ عَبْرَ الْمَرِيءِ وَقَبْلَ أَنْ يَمُرَّ إِلَى الأَمْعَاءِ."', ':لا جذر:لا مفرد');
