INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14741, 'مِعْزَى', 'معزى', 'جامد', 'معز', 'معزى', 'معز', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"مِعْزَى-مِعْزَى [م ع ز]. ن. مَعْزٌ، مَاعِزٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14742, 'مَعْكَرُونَةٌ', 'معكرونة', 'جامد', '', 'معكرونة', 'معكرنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَعْكَرُونَةٌ-مَعْكَرُونَةٌ (طخ). ""يُجِيدُ الإِيطَالِيُّونَ طَبْخَ الْمَعْكَرُونَـةِ"" : طَعَامٌ مِنَ العَجِينِ عَلَى شَكْلِ خُيُوطٍ يَابِسَةٍ يُوضَعُ فِي الْمَاءِ السَّاخِنِ لِيَسْتَوِيَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14743, 'مَاعُونٌ', 'ماعون', 'جامد', 'معن', 'ماعون', 'معن', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَاعِينُ"', '', 'R', '', '', '', '', '', '', '". 1.:كُلُّ مَا انْتُفِعَ بِهِ منْ أَشْياَءِالبَيْتِ كَالصُّحُونِ وَالقُدُورِ وَمَا شَابَـهَ ذَلِـكَ. الماعون آية 7 الَّذِينَ هُمْ يُرَاءونَ وَيَمْنَعُونَ الْمَاعُونَ (قرآن). 2.""سُورَةُ الْمَاعُونِ"" : سُورَةٌ مِنْ سُوَرِ القُرْآنِ. 3.""مَاعُونُ وَرَقٍ"" : كَمِّيَّةٌ مَحْدُودَةٌ مِنَ الوَرَقِ عَدَدُهَا خَمْسُمِائَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14744, 'مَوَاعِينُ', 'مواعين', 'جامد', '', 'مواعين', 'معن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14745, 'مِعَاءٌ', 'معاء', 'جامد', 'معو', 'معاء', 'مع', '', '', '', 'مفرد', '', '', '', '"أَمْعِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '". ن. مِعـىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14746, 'أَمْعِيَةٌ', 'أمعية', 'جامد', '', 'ءمعية', 'معة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14747, 'مُغْرَبِيَّةٌ', 'مغربية', 'جامد', '', 'مغربية', 'مغربة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مُغْرَبِيَّةٌ-مُغْرَبِيَّةٌ (طخ). : طَعَامٌ مِنْ فَتَائِلِ العَجِينِ والسَّمْنِ واللَّحْمِ والحِمَّصِ والبَصَلِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14748, 'مِغْنَاطِيسٌ', 'مغناطيس', 'جامد', '', 'مغناطيس', 'مغنطس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِغْنَاطِيسٌ-مِغْنَاطِيسٌ (فيز).: مَعْدِنٌ أَوْ حَجَرٌ يَحْتَوِي عَلَى قُوَّةٍ تَجْذِبُ الْحَدِيدَ إِلَيْهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14749, 'مِغْنَطِيسٌ', 'مغنطيس', 'جامد', '', 'مغنطيس', 'مغنطس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ن. مِغْنَاطِيسٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14750, 'مُفَاعِلٌ', 'مفاعل', 'جامد', '', 'مفاعل', 'مفعل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""مُفَاعِلٌ ذَرِّيٌّ أَوْ نَوَوِيٌّ"" : جِهَازٌ دَقِيقٌ يَقُومُ بِإِنْتَاجِ الطَّاقَةِ مِنَ الذَّرَّاتِ، بَعْدَ مُرُورِهَا مِنْ مَرْحَلَةِ الانْشِطَارِ فِي دَاخِلِهِ، مِثْلَ انْشِطَارِ اليُورَانْيُوم."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14751, 'مَفْصِلِيَّاتٌ', 'مفصليات', 'جامد', '', 'مفصليات', 'مفصلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ حَيَوَانِيَّةٌ مِنَ الْحَيَوَانَاتِ اللاَّفِقْرِيَّةِ، لهَا أَرْجُلٌ مَفْصِلِيَّةٌ تَشْمَلُ الْحَشَرَاتِ والقِشْرِيَّاتِ والعَنَاكِبَ والعَقَارِبَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14752, 'مُفَلْطَحَةٌ', 'مفلطحة', 'جامد', '', 'مفلطحة', 'مفلطحة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مُفَلْطَحَةٌ-مُفَلْطَحَةٌ (حو). : جِنْسُ سَمَكٍ مِنْ فَصِيلَةِ الْمُفَلْطَحَاتِ، مَلْسَاءُ، لَهَا جِسْمٌ مُنْبَسِطٌ وَعَرِيضٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14753, 'مَقَانِقُ', 'مقانق', 'جامد', '', 'مقانق', 'مقنق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"مَقَانِقُ-مَقَانِقُ (طخ).: مِعـىً مَحْشُوٌّ بِالشَّحْمِ الْمَفْرُومِ والأَفَاوِيهِ، عَلَىشَكْلِ أَصَابِعَ، تُؤْكَلُ مَشْوِيَّةً أَوْ مَقْلِيَّةً تُعْرَفُ بِالمِرْكَاسِ، المِرْكَازِ، ويُطْلَقُ عَلَيْهَا أَيْضاً سُجُقّ وَهُوَ أَغلَظُ مِنْها، وقُتَيْبَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14754, 'مَقْدُونُسٌ', 'مقدونس', 'جامد', '', 'مقدونس', 'مقدنس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَقْدُونُسٌ-مَقْدُونُسٌ (نب). : بَقْدونس، نَبَاتٌ مِنْ فَصِيلَةِ الخَيْمِيَّاتِ، عُشْبِيٌّ، لَهُ رَائِحَةٌ طَيِّبَةٌ، يُسْتَعْمَلُ فِي الطَّعَامِ، يُعْرَفُ في تُونُس والْمَغْرِب، بِالْمَعْدَنوسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14755, 'مِقْرَاجٌ', 'مقراج', 'جامد', '', 'مقراج', 'مقرج', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ن. بُقْراجٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14756, 'مُقْلَةٌ', 'مقلة', 'جامد', 'مقل', 'مقلة', 'مقلة', '', '', '', 'مفرد', 'DnN', '', '', '"مُقَلٌ"', '', 'R', '', '', '', '', '', '', '". ""مُقْلَةُ العَيْنِ"" : شَحْمَةُ العَيْنِ الَّتِي تَجْمَعُ السَّوَادَ والبَيَاضَ. ""فِي مُقْلَتِهِ احْمِرَارٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14757, 'مُقَلٌ', 'مقل', 'جامد', '', 'مقل', 'مقل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14758, 'مُكَّاءٌ', 'مكاء', 'جامد', '', 'مكاء', 'مك', '', '', '', 'جمع تكسير', '', '', '', '"مَكَاكِيٌّ"', '', 'Rz', '', 'N', 'O', 'O', 'O', '', '"ج: مَكَاكِيٌّ. (حو).: طَيْرٌ مِنْ فَصِيلَةِ القُبَّرِيَّاتِ، مُتَمَيِّزٌ بِصَفِيرٍ حَسَنٍ وتَصْعِيدٍ وهُبُوطٍ وهُوَ في ذَلِكَ يَمْكُو، أَيْ يُصَفِّرُ، لِذَلِكَ سُمِّيَ بِالْمُكَّاءِ، ومِنْ أَسْمَائِهِ الأَخْرُجُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14759, 'مَكَاكِيٌّ', 'مكاكي', 'جامد', '', 'مكاكي', 'مكك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14760, 'مِكْرُوسْكُوبٌ', 'مكروسكوب', 'جامد', '', 'مكروسكوب', 'مكرسكب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ن. الْمِجْهَرُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14761, 'مُكَاكٌ', 'مكاك', 'جامد', 'مكك', 'مكاك', 'مكك', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مُكَاكٌ-مُكَاكٌ [م ك ك]. : الْمَادَّةُ الرَّخْوَةُ الْمَوْجُودَةُ بِدَاخِلِ العِظَامِ، الْمُخَاخَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14762, 'مَكُّوكٌ', 'مكوك', 'جامد', 'مكك', 'مكوك', 'مكك', '', '', '', 'مفرد', 'DnN', '', '', '"مَكَاكِيكُ"', '', 'R', '', '', '', '', '', '', '". 1. : بَكَرَةٌ مِنْ مَعْدِنٍ أَوْ خَشَبٍ تُسْتَعْمَلُ فِي آلَةِ الخِيَاطَةِ، أو فِي نَـوْلِ الْحِيَاكَةِ. 2. : طَاسٌ يُشْرَبُ بِهِ، أَعْلاَهُ ضَيِّقٌ، وَوَسَطُـهُ وَاسِـعٌ. 3.""مَكُّـوكُ الفَضَاءِ"" : مَرْكَبَةٌ فَضَائِيَّةٌ تَدُورُ حَوْلَ الأَرْضِ تُطْلَقُ مِنْ قَاعِدَةٍ وتَعُودُ إِلَى الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14763, 'مَكَاكِيكُ', 'مكاكيك', 'جامد', '', 'مكاكيك', 'مككك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14764, 'إِمْكانِيَّةٌ', 'إمكانية', 'جامد', 'مكن', 'ءمكانية', 'إمكنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '".""لَهُ إِمْكانِيَّةٌ على إِنْجازِ ما يَرْغَبُ فِيهِ"" : لَهُ القُدْرَةُ، الطَّاقَةُ. ""إِمْكانِيَّاتُهُ مَحْدودَةٌ جِدّاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14765, 'مُمْكِنَاتٌ', 'ممكنات', 'جامد', 'مكن', 'ممكنات', 'ممكنت', '', '', '', 'مفرد', '', '', '', '"مفردمُمْكِن"', '', '', '', '', '', '', '', '', '". ""أَضْحَتْ كُلُّ الأُمُورِ مِنَ الْمُمْكِنَاتِ"" : أَيْ مُحْتَمَلَةٌ وَبِالإِمْكَانِ حُدُوثُهَا، أَيْ لَمْ تَعُدْ مِنَ الْمُسْتَحِيلاَتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14766, 'مُمْكِن', 'ممكن', 'جامد', '', 'ممكن', 'ممكن', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14767, 'مَكَنَةٌ', 'مكنة', 'جامد', '', 'مكنة', 'مكنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '": كُلُّ آلَةٍ مِنْ شَأْنِهَا أَنْ تُؤَدِّي عَمَلاً آلِيّاً لِلإِنْتَاجِ الصِّنَاعِيِّ، آلَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14768, 'مَكاً', 'مكا', 'جامد', 'مكو', 'مكا', 'مك', '', '', '', 'مفرد', 'Dw', '', '', '"أَمْكَاءٌ"', '', 'Rw', '', 'N', 'O', 'O', 'O', '', '".: جُحْرُ الثَّعْلَبِ والأَرْنَبِ ونَحْوِهِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14769, 'أَمْكَاءٌ', 'أمكاء', 'جامد', '', 'ءمكاء', 'مك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14770, 'مَكْوٌ', 'مكو', 'جامد', 'مكو', 'مكو', 'مك', '', '', '', 'مفرد', 'DnN', '', '', '"أَمْكَاءٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". : جُحْرُ الثَّعْلَبِ والأَرْنَبِ ونَحْوِهِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14771, 'أَمْكَاءٌ', 'أمكاء', 'جامد', '', 'ءمكاء', 'مك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14772, 'مِلْءٌ', 'ملء', 'جامد', 'ملأ', 'ملء', 'مل', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', 'N', 'O', 'O', 'O', '', '"مِلْءٌ-مِلْءٌ [م ل أ]. 1. : مَا يَسْتَوْعِبُهُ الإِنَاءُ إِذَا امْتَلأَ. 2.""مِلْءُ اليَدِ"" : الْحَفْنَةُ، القَبْضَةُ. 3.""بِمِلْءِ شِدْقَيْهِ"" : مَا امْتَلأَ بِهِ شِدْقَاهُ. ""مِلْءُ الكَأْسِ"". 4.""نَامَ مِلْءَ جَفْنِهِ"" : أَيْ نَامَ بِلاَ هَمٍّ ولاَ غَمٍّ. أَنَامُ مِلْءَ جُفُونِي عَنْ شَوَارِدِهَا ويَسْهَرُ الْخَلْقُ جَرَّاهَا ويَخْتَصِمُ (المتنبي). 5.""بِمِلْءِ إِرَادَتِهِ"" : بِمَحْضِ إِرَادَتِهِ. 6.""مِلْءُ السَّمْعِ والبَصَرِ"" : أَيْ مَنْ يَمْلأ السَّمْعَ بِذِكْرِهِ والبَصَرَ بِمَهَابَتَهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14773, 'مُلاَءةٌ', 'ملاءة', 'جامد', 'ملأ', 'ملاءة', 'ملة', '', '', '', 'مفرد', 'DnN', '', '', '"مُلاَءٌ"', '', 'Rz', '', '', '', '', '', '', '". 1.""اِلْتَفَّتْ فِي مُلاَءتِهَا"" : الْحَائِكُ وهُوَ ثَوْبٌ مِنْ قِطْعَةٍ وَاحِدَةٍ ذُو شَقَّيْنِ مُتَضَامِنَيْنِ. 2.""مُلاَءةُ السَّرِيرِ"" : غِطَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14774, 'مُلاَءٌ', 'ملاء', 'جامد', '', 'ملاء', 'مل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14775, 'مَلاَرِيَا', 'ملاريا', 'جامد', '', 'ملاريا', 'ملر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '"مَلاَرِيَا-مَلاَرِيَا (طب). : مَرَضٌ يُصِيبُ الإِنْسَانَ مِنْ جَرَّاءِ بَعُوضِ الْمُسْتَنْقَعَاتِ يُسَبِّبُ نَوْبَاتٍ مِنَ الْحُمَّى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14776, 'أُمْلوحَةٌ', 'أملوحة', 'جامد', 'ملح', 'ءملوحة', 'ملحة', '', '', '', 'مفرد', 'DnN', '', '', '"أَماليحُ"', '', 'R', '', '', '', '', '', '', '". ""لاَ يَحْكِي إِلاَّ الأَماليحَ"": الحِكايات الْمُسْتَمْلَحَة، الكَلام الْمُسْتَحْسَن. ""يَحْكي أُمْلوحَةً بَعْدَ أُخْرى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14777, 'أَماليحُ', 'أماليح', 'جامد', '', 'ءماليح', 'ملح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14778, 'مَلاَّحَةٌ', 'ملاحة', 'جامد', 'ملح', 'ملاحة', 'ملحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَلاَّحَةٌ-مَلاَّحَةٌ [م ل ح]. 1.""تَبَخَّرَ مَاءُ الْمَلاَّحَةِ"" : حَوْضُ تَجْفِيفِ المِلْحِ. 2.""اِشْتَرَوْا المِلْحَ مِنَ الْمَلاَّحَةِ"" : مَكَانُ بَيْعِ المِلْحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14779, 'مِلاَحَةٌ', 'ملاحة', 'جامد', 'ملح', 'ملاحة', 'ملحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مِلاَحَةٌ-مِلاَحَةٌ [م ل ح]. 1. ""اِرْتَبَطَ بِالمِلاَحَةِ مُنْذُ شَبَابِهِ"" : حِرْفَةُ الْمَلاَّحِ. 2.""المِلاَحَةُ البَحْرِيَّةُ"" : فَنُّ السَّفَرِ فِي البِحَارِ أَو الأَنْهُرِ الكُبْرَى. 3.""المِلاَحَةُ الْجَوِّيَّةُ"" : فَنُّ السَّفَرِ فِي الْجَوِّ. ""يَشْتَغِلُ فِي شَرِكَةِ المِلاَحَةِ البَحْرِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14780, 'مَلأٌ', 'ملأ', 'جامد', 'ملأ', 'ملء', 'مل', '', '', '', 'مفرد', 'Dz', '', '', '"أَمْلأُ"', '', 'Rz', '', '', '', '', '', '', '". 1.""عَلَى الْمَلَإِ"" : عَلاَنِيَةً. 2.""خَطَبَ فِي مَلَإٍ مِنَ النَّاسِ"" : في جَمَاعَةٍ مِنْهُمْ. 3.""ما أَحْسَنَ مَلأَ وَلَدِهِ"" : أَخْلاقَهُ وعِشْرَتَهُ. 4.""الْمَلأُ الأَعْلَى"" : عَالَمُ العُقُولِ الْمُجَرَّدَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14781, 'أَمْلأُ', 'أملأ', 'جامد', '', 'ءملء', 'مل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14782, 'مُلْحَةٌ', 'ملحة', 'جامد', 'ملح', 'ملحة', 'ملحة', '', '', '', 'مفرد', 'DnN', '', '', '"مُلَحٌ"', '', 'R', '', '', '', '', '', '', '". 1.""فِي كَلاَمِهِ مُلْحَةٌ"" : فِيهِ مَا يَلِذُّ وَيُرَوِّحُ عَنِ النَّفْسِ. 2.""رَوَى لَهُ مُلْحَةً أَضْحَكَتْهُ مِنَ الأَعْمَاقِ"" : نَادِرَةً، طَرِيفَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14783, 'مُلَحٌ', 'ملح', 'جامد', '', 'ملح', 'ملح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14784, 'مَمْلَحَةٌ', 'مملحة', 'جامد', 'ملح', 'مملحة', 'مملحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَمْلَحَةٌ-مَمْلَحَةٌ [م ل ح]. : الْحَقْلُ الَّذِي يُصَفَّى فِيهِ المِلْحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14785, 'مِمْلَحَةٌ', 'مملحة', 'جامد', 'ملح', 'مملحة', 'مملحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مِمْلَحَةٌ-مِمْلَحَةٌ [م ل ح]. : زُجَاجَةٌ صَغِيرَةٌ، وأَيُّ وِعَاءٍ آخَرَ يُوضَعُ فِيهِ المِلْحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14786, 'مَلاَّسَةٌ', 'ملاسة', 'جامد', 'ملس', 'ملاسة', 'ملسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""مَلاَّسَةُ البِنَاءِ"" : أَدَاةٌ مِنْ خَشَبٍ أوحَدِيدٍ تُسَوَّى وتُمَلَّسُ بِهَا الْجُدْرَانُ والأَرْضُ، مِسَجَّةٌ، مالَجٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14787, 'مَلاَكٌ', 'ملاك', 'جامد', 'ملك', 'ملاك', 'ملك', '', '', '', 'مفرد', 'DnN', '', '', '"مَلاَئِكَةٌ:مَلاَئِكُ"', '', 'R', '', '', '', '', '', '', '". ن. مَلَكٌ. 1.""مَلاَكُ الْمَوْتِ"" : جِبْرِيل. 2.""مَلاَكُ الْحُبِّ"" : سُلْطَتُهُ وَقُوَّتُهُ. 3.""مَلاَئِكَةُ الرَّحْمَانِ"" : الأَرْوَاحُ السَّمَاوِيَّةُ. 4.""مَلاَكُ الأَمْرِ"" : قَوَامُهُ وَعُنْصُرُهُ الأَسَاسِيُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14788, 'مَلاَئِكَةٌ', 'ملائكة', 'جامد', '', 'ملاءكة', 'ملكة', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14789, 'مَلاَئِكُ', 'ملائك', 'جامد', '', 'ملاءك', 'ملك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14790, 'مَلَكَةٌ', 'ملكة', 'جامد', 'ملك', 'ملكة', 'ملكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""يَتَمَتَّعُ بِمَلَكَةٍ فَنِّيَّةٍ عَالِيةٍ"" : صِفَةٌ رَاسِخَةٌ فِي النَّفْسِ أَوِ العَقْلِ، قَائِمَةٌ عَلَى اسْتِعْدَادٍ فِطْرِيٍّ. ""مَلَكَةٌ شِعْرِيَّةٌ"" ""مَلَكَةٌ مُوسِيقِيَّةٌ"". 2.""هُوَ مَلَكَةُ يَمِينِي"" : أَيْ مَا أَسْتَطِيعُهُ وَأَمْلِكُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14791, 'مَلَكٌ', 'ملك', 'جامد', 'ملك', 'ملك', 'ملك', '', '', '', 'مفرد', 'DnN', '', '', '"مَلاَئِكَةٌ"', '', 'R', '', '', '', '', '', '', '". ن. مَلاَكٌ. 1.""إِنَّ اللَّهَ ومَلاَئِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ"" : الأَرْوَاحُ السَّمَاوِيَّةُ. 2.""مَلَكُ الْمَوْتِ"" : عِزْرَائِيلُ. 3.""اِمْرَأَةٌ مَلَكٌ"" : طَاهِرَةٌ. 4.""مَا لَهُ مَلَكٌ"": لاَ يَمْلِكُ شَيْئاً. 5.""مَلَكٌ"" : اِسْمُ عَلَمٍ لِلإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14792, 'مَلاَئِكَةٌ', 'ملائكة', 'جامد', '', 'ملاءكة', 'ملكة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14793, 'مَلِكٌ', 'ملك', 'جامد', 'ملك', 'ملك', 'ملك', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":مُلُوكٌ"', '', 'Rp', '', '', '', '', '', '', '". 1. ""هُوَ الْمَلِكُ فِي مَلَكُوتِهِ"" : اللَّهُ تَعَالَى، أَي الْمَالِكُ الْمُطْلَقُ.طه آية 114 فَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ (قرآن). 2.""جَلاَلَةُ الْمَلِكِ"" : صَاحِبُ الأَمْرِ والسُّلْطَةِ عَلَى بِلاَدٍ تَخْضَعُ لَهُ. ""مَلِكَةُ سَبَإٍ"". 3.""مَلِكَةُ الْجَمَالِ"" : مَنْ تُخْتارُ فِي مُبَارَاةٍ دَوْلِيَّةٍ مِنْ بَيْنِ العَدِيدِ مِنَ النِّسَاءِ وَيُنْظَرُ إِلَيْهَا على أَنَّها أَجْمَلُ امْرَأَةٍ. 4.""مَلِكَةُ النَّحْلِ"": يَعْسُوبُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14794, 'مُلُوكٌ', 'ملوك', 'جامد', '', 'ملوك', 'ملك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14795, 'مَلَكُوتٌ', 'ملكوت', 'جامد', 'ملك', 'ملكوت', 'ملكت', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَلَكُوتٌ-مَلَكُوتٌ [م ل ك]. 1.""فِي مَلَكُوتِهِ"" : فِي مُلْكِهِ العَظِيمِ.المؤمنون آية 88 قُلْ مَنْ بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ (قرآن). 2.""فِي أَبْهَى الْمَلَكُوتِ"" : العِزِّ، السُّلْطَانِ. 3.""الْمَلَكُوتُ السَّمَاوِيُّ"" : مَحَلُّ القِدِّيسِينَ والأَبْرَارِ فِي السَّمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14796, 'مِلْكِيَّةٌ', 'ملكية', 'جامد', 'ملك', 'ملكية', 'ملكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""مِلْكِيَّةٌ خَاصَّةٌ"" : مَا يَمْلِكُهُ الإِنْسَانُ، وَيَتَصَرَّفُ فِيهِ. 2.""مِلْكِيَّةٌ عَامَّةٌ"" : مَا هُوَ فِي مِلْكِ العُمُومِ، يَتَمَتَّعُ بِهِ الْجَمِيعُ وَيَكُونُ خَاضِعاً لِسُلْطَةِ الدَّوْلَةِ. 3.""مِلْكِيَّةٌ مُشْتَرَكَةٌ"" l ""مِلْكِيَّةٌ مُشَاعَةٌ"" l ""تَقْتَضِي مَصْلَحَةُ الدَّوْلَةِ أَحْيَاناً نَزْعَ المِلْكِيَّةِ الخَاصَّةِ لِصَالِحِ المِلْكِيَّةِ العَامَّةِ"". 4.""حَقُّ المِلْكِيَّةِ الأَدَبِيَّةِ حَقٌّ مُقَدَّسٌ"" : حَقُّ الاسْتِعْمَالِ والتَّصَرُّفِ فِيهَا إِطْلاَقاً فِي نِطَاقِ القَانُونِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14797, 'مَلِيكٌ', 'مليك', 'جامد', 'ملك', 'مليك', 'ملك', '', '', '', 'مفرد', 'DnN', '', '', '"مُلَكَاءُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَلِيكُ الخَلْقِ"" : الرَّبُّ والْمَالِكُ. القمر آية 55 فِي مَقْعَدِ صِدْقٍ عِنْدَ مَلِيكٍ مُقْتَدِرٍ (قرآن). 2.""يَحْكُمُ البِلاَدَ مَلِيكٌ"" : صَاحِبُ الْمُلْكِ والسُّلْطَةِ. 3.""مَلِيكُ النَّحْلِ"" : أَمِيرَتُهَا، مَلِكَتُها، يَعْسُوبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14798, 'مُلَكَاءُ', 'ملكاء', 'جامد', '', 'ملكاء', 'ملك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14799, 'مِلَّةٌ', 'ملة', 'جامد', 'ملل', 'ملة', 'ملة', '', '', '', 'مفرد', 'DnN', '', '', '"مِلَلٌ"', '', '', '', '', '', '', '', '', '". ""يُدَافِعُ عَنِ المِلَّةِ"" : الشَّرِيعَة، العَقِيدَة. ""الْمِلَلُ وَالنِّحَلُ"" ""مِلَّةُ الإِسْلامِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14800, 'مِلَلٌ', 'ملل', 'جامد', '', 'ملل', 'مل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14801, 'مِلاَطٌ', 'ملاط', 'جامد', 'ملط', 'ملاط', 'ملط', '', '', '', 'مفرد', 'DnN', '', '', '"مُلُطٌ:أَمْلِطَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""مِلاَطُ الْجُدْرَانِ"": الطِّينُ الَّذِي تُطْلَى بِهِ الْجُدْرَانُ، أَو يُجْعَلُ بَيْنَ حَجَرَيْنِ أو آجُرَّتَيْنِ فِي البِنَاءِ. 2.""مِلاَطُ الأَسْنَانِ"" : عَجِينٌ تُلْصَقُ بِهِ الأَسْنَانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14802, 'مُلُطٌ', 'ملط', 'جامد', '', 'ملط', 'ملط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14803, 'أَمْلِطَةٌ', 'أملطة', 'جامد', '', 'ءملطة', 'ملطة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14804, 'مُلُوخِيَّةٌ', 'ملوخية', 'جامد', '', 'ملوخية', 'ملخة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"مُلُوخِيَّةٌ-مُلُوخِيَّةٌ (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الْخُبَّازِيَّاتِ، مِنْ أَصْلٍ هِنْدِيٍّ، أَوْرَاقُهُ خَضْرَاءُ يُسْتَهْلَكُ كَثِيراً بِمِصْرَ وبَعْضِ بُلْدَانِ الشَّرْقِ. يُطْبَخُ بِلَحْمِ البَقَرِ أَوالأَرَانِبِ، والْمُلوخِيَّةُ: تُطْلَقُ في الْمَغْرِبِ عَلَى ما يَدْعُوهُ الْمشَارِقَةُ البَامِيَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14805, 'مِلْيَارٌ', 'مليار', 'جامد', '', 'مليار', 'ملر', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. ""عَدَدُ سُكَّانِ الصِّينِ أَزْيَدُ مِنْ مِلْيَارِ نَسَمَةٍ"" : أَزْيَدُ مِنْ أَلْفِ مِلْيُونٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14806, 'مِلِّيمٌ', 'مليم', 'جامد', '', 'مليم', 'ملم', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. : عُمْلَةٌ تُسَاوِي جُزءاً مِنْ أَلْفٍ مِنَ الجُنَيْهِ المِصْرِيِّ أَوِ الدِينَارِ أَوْ مِنْ 10 دَرَاهِمَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14807, 'مِلْيُونٌ', 'مليون', 'جامد', '', 'مليون', 'ملن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"مَلاَيِينُ"', '', 'R', '', '', '', '', '', '', '"ج: مَلاَيِينُ. ""مِلْيُونُ دِرْهَمٍ"" : أَلْفٌ أَلْفَ مَرَّةٍ. ""مِلْيُونُ نَسَمَةٍ"" ""عَشَرَةُ مَلاَيِينَ مِنَ السُّكَّانِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14808, 'مَلاَيِينُ', 'ملايين', 'جامد', '', 'ملايين', 'ملن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14809, 'مِلْيُونِيرٌ', 'مليونير', 'جامد', '', 'مليونير', 'ملنر', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', 'R', '', '', '', '', '', '', '"""تَاجِرٌ مِلْيُونِيرٌ"" : أَيْ ثَرْوَتُهُ تُعَدُّ بِالْمَلاَيِينِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14810, 'مَنَاجِذُ', 'مناجذ', 'جامد', '', 'مناجذ', 'منجذ', '', '', '', 'جمع تكسير', '', '', '', '"مفردجُلْذ:مِنْغَيْرِلَفْظِهِ:', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جمع جُلْذ، مِنْ غَيْرِ لَفْظِهِ، وجَمْعُ خُلْد وهُوَ الفَأْرُ الأَعْمَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14811, 'مَنْجَنِيقٌ', 'منجنيق', 'جامد', '', 'منجنيق', 'منجنق', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":مَجانِقُ:مَجَانِيقُ"', '', 'R', '', '', '', '', '', '', '"ج: مَجانِقُ ومَجَانِيقُ، مَنْجَنِيقَاتٌ. ""رَمَوْا قِلاَعَ العَدُوِّ <بِالْمَجَانِيقِ"" : آلَـةٌ رْبِيَّةٌ قَدِيمَةٌ، تُسْتَعْمَلُ لِدَكِّ أَسْوَارِ الْمُدُنِ أوِ القِلاَعِ."', ':لا جذر:لا مفرد');
