INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14821, 'أُمْنِيَّةٌ', 'أمنية', 'جامد', 'مني', 'ءمنية', 'منة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَمانٍ:الأَمانِي"', '', '', '', '', '', '', '', '', '". 1.""كانَتْ أُمْنِيَّتُهُ أَنْ يَنْجَحَ"" : بُغْيَتُهُ. 2.""لاَ تُبْلَغُ الغاياتُ بِالأَمانِي"".(مثل) : لَنْ تَبْلُغَ هَدَفَكَ بِمُجَرَّدِ التَّمَنِّي والتَّرَجِّي."', '');
