INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14841, 'مَهَلٌ', 'مهل', 'جامد', 'مهل', 'مهل', 'مهل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَهَلٌ-مَهَلٌ [م هـ ل]. ""عَلَى مَهَلٍ"" : عَلَى مَهْلٍ، أَي دُونَ عَجَلَةٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14842, 'مَهْلٌ', 'مهل', 'جامد', 'مهل', 'مهل', 'مهل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَهْلٌ-مَهْلٌ [م هـ ل]. 1.""سِرْ عَلَى مَهْلٍ"" : سِرْ بِبُطْءٍ وَتُؤْدَةٍ. ""عَلَى مَهْلِكَ"". 2.""مَهْلاً يَا وَلَدُ"" : رِفْقاً، وَهُوَ نَائِبٌ مَنَابَ فِعْلِهِ لِلْمُذَكَّرِ وَالْمُؤَنَّثِ مُفْرَداً وَمُثَنّىً وَجَمْعاً. ""مَهْلاً يَا رِجَالُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14843, 'مَهَاةٌ', 'مهاة', 'جامد', 'مهو', 'مهاة', 'مهة', '', '', '', 'مفرد', 'DnN', '', '', '"مَهًا:مَهَوَاتٌ"', '', 'Rw', '', '', '', '', '', '', '"(حو) 1. : بَقَرَةٌ لَبونٌ مِنْ فَصِيلَةِ البَقَرِيَّاتِ، مِنْ رُتْبَةِ شَفْعِيَّاتِ الأَظْلاَفِ، لَهَا قَرْنَانِ حَلَقِيَانِ لَوْلَبِيَّانِ، جِلْدُهَا أَبْيَضُ أَغْبَرُ، عَيْنَاهَا كَبِيرَتَانِ مُكَحَّلَتَانِ، وَهِيَ مَا يُعْرَفُ بِالبَقَرَةِ الوَحْشِيَّةِ. 2.جمع مَهَا، اِسْمُ عَلَمٍ لِلإِنَاثِ، تَشْبِيهاً لِجَمَالِ عَيْنَيْهَا واتِّسَاعِهِمَا. عُيُونُ الْمَهَا بَيْنَ الرُّصَافَةِ والجِسْرِ*جَلَبْنَ الْهَوَى مِنْ حَيْثُ أَدْرِي ولاَ أَدْرِي (علي بن الجهم)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14844, 'مَهًا', 'مها', 'جامد', '', 'مها', 'مه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14845, 'مَهَوَاتٌ', 'مهوات', 'جامد', '', 'مهوات', 'مهت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14846, 'مُوَاءُ', 'مواء', 'جامد', 'موأ', 'مواء', 'م', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rz', '', 'N', 'O', 'O', 'O', '', '". ""مُوَاءُ القِطِّ"" : صَوْتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14847, 'مَوَالِيا', 'مواليا', 'جامد', '', 'مواليا', 'مل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '": نَوْعٌ مِنَ الشِّعْرِ، مِنَ البَحْرِ البَسِيطِ، كَانَ العَبِيدُ يَتَغَنَّوْنَ بِهِ، ويَقُولُونَ فِي آخِرِ كُلِّ صَوْتٍ مِنْهُ أو مَقْطُوعَةٍ : يَا مَوَالِيَ إِشَارَةً إِلَى سَادَتِهِمْ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14848, 'مَمَاتٌ', 'ممات', 'جامد', 'موت', 'ممات', 'ممت', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَمَاتٌ-مَمَاتٌ [م و ت]. ""أَرْعَبَ النَّاسَ فِي حَيَاتِهِ ومَمَاتِهِ"" : أَيْ مَوْتِهِ. الإسراء آية 75 إِذًا لأَذَقْنَاكَ ضِعْفَ الْحَيَاةِ وضِعْفَ الْمَمَاتِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14849, 'مَوْتَةٌ', 'موتة', 'جامد', 'موت', 'موتة', 'متة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '"مَوْتَةٌ-مَوْتَةٌ [م و ت]. ""مَاتَ مَوْتَةً شَنِيعَةً"" : أَيْ مَوْتاً ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14850, 'مِمْوَاجٌ', 'ممواج', 'جامد', 'موج', 'ممواج', 'ممج', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِمْوَاجٌ-مِمْوَاجٌ [م و ج]. : جِهَازٌ طِبِّيٌّ يَتَمَكَّنُ مِنْ مَعْرِفَةِ الأَعْضَاءِ الدَّاخِلِيَّةِ كَأَحْشَاءِ البَطْنِ مَثَلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14851, 'مُورِيتَانْيَا', 'موريتانيا', 'جامد', '', 'موريتانيا', 'مرتن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'N', 'N', 'O', '', '": مِنَ البُلْدَانِ العَرَبِيَّةِ (الجُمْهُورِيَّةُ الإِسْلاَمِيَّةُ الْمُورِيتَانِيَّةُ) تَقَعُ غَرْبَ إِفْرِيقْيَا جَنُوبَ الْمَغْرِبِ، مِنْ دُوَلِ الْمَغْرِبِ العَرَبِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14852, 'مَوْزٌ', 'موز', 'جامد', '', 'موز', 'مز', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَوْزٌ-مَوْزٌ (نب). : شَجَرٌ مِنْ فَصِيلَةِ الْمَوْزِيَّاتِ، يَنْبُتُ فِي البِلاَدِ الْحَارَّةِ،يُعْطِي فَاكِهَةَ الْمَوْزِ، وهِيَ طَوِيلَةٌ، لَهَا قِشْرَةٌ صَفْرَاءُ ثَخِينَةٌ مَلْسَاءُ، ومَادَّتُهَا نَشَوِيَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14853, 'مَوْزِيَّاتٌ', 'موزيات', 'جامد', '', 'موزيات', 'مزت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"مَوْزِيَّاتٌ-مَوْزِيَّاتٌ (نب). : فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ أَنْوَاعِهَا شَجَرُ الْمَوْزِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14854, 'مَاسٌ', 'ماس', 'جامد', 'موس', 'ماس', 'مس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَاسٌ-مَاسٌ [م و س]. ""حَجَرُ الْمَاسِ"" : حَجَرٌ كَرِيمٌ شَدِيدُ اللَّمَعَانِ، لَهُ قِيمَةٌ نَفِيسَةٌ يُقَطَّعُ بِهِ الزُّجَاجُ لِصَلاَبَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14855, 'مُوسِيقَارٌ', 'موسيقار', 'جامد', '', 'موسيقار', 'مسقر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '": مَنْ حِرْفَتُهُ الْمُوسِيقَى وَلَهُ بَرَاعَةٌ فِي تَأْلِيفِ الأَلْحَانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14856, 'مُوسِيقَى', 'موسيقى', 'جامد', '', 'موسيقى', 'مسق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'Rp', '', '', '', '', '', '', '": فَنٌّ يَعْتَمِدُ عَلَى تَلْحِينِ الألْحَانِ وتَأْلِيفِهَا وغِنَائِهَا والتَّطْرِيبِ بِهَا، وهِيَ أَنْواعٌ وأَشْكالٌ: ""مُوسِيقَى الآلَةِ"" ""الْمُوسِيقَى الشَّعْبِيَّةُ"" ""مُوسِيقَى الْجَازِ"" ""الْمُوسِيقَى الكِلاَسِيكِيَّةُ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14857, 'مَالٌ', 'مال', 'جامد', 'مول', 'مال', 'مل', '', '', '', 'مفرد', 'DnN', '', '', '"أَمْوَالٌ(مذ:مؤ)"', '', 'Rp', '', '', '', '', '', '', '". 1.""لَهُ مَالٌ كَثِيرٌ"": مُمْتَلَكَاتٌ وَمَتَاعٌ. ""ذُو مَالٍ"" ""مَالُهُ قَلِيلٌ"". 2.""صَرَفَ أَمْوَالاً طَائِلَةً"" : فُلُوساً، نُقُوداً، دَرَاهِمَ، عُمْلَةً. 3.""لَهُ رَأْسُ مَالٍ كَبِيرٌ"" : مِقْدَارٌ مِنَ الفُلُوسِ، النُّقُودِ يُوَظَّفُ فِي مَشْرُوعٍ تِجَارِيٍّ. 4.""بَيْتُ الْمَالِ"" : الخَزِينَةُ. 5.""أَمِينُ الْمَالِ"" : الْمَسْؤُولُ عَنِ الْمَصَارِيفِ وَالْمَدَاخِيلِ فِي جَمْعِيَّةٍ أَوْ مُؤَسَّسَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14858, 'أَمْوَالٌ', 'أموال', 'جامد', '', 'ءموال', 'مل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14859, 'مُومِيَاءُ', 'مومياء', 'جامد', 'موم', 'مومياء', 'مم', '', '', '', 'مفرد', 'Dz', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"مُومِيَاءُ-مُومِيَاءُ [م و م]. : الْجُثَّةُ الْمُحَنَّطَةُ عِنْدَ قُدَمَاءِ الْمَصْرِيِّينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14860, 'مُونَةٌ', 'مونة', 'جامد', 'مون', 'مونة', 'منة', '', '', '', 'مفرد', 'DnN', '', '', '"مُوَنٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِحْتَاطُوا لِلْشِّتَاءِ بِتَوْفِيرِ الْمُونَةِ"" : مَا يُدَّخَرُ مِنَ الْمَوَادِّ الغِذَائِيَّةِ. 2.""بَيْتُ الْمُونَةِ"" : الْمَوْضِعُ الَّذِي تُوضَعُ فِيهِ الْمُونَةُ مِنْ سَمْنٍ وزَيْتٍ وقَمْحٍ وزَيْتُونٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14861, 'مُوَنٌ', 'مون', 'جامد', '', 'مون', 'من', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14862, 'مَاءٌ', 'ماء', 'جامد', 'موه', 'ماء', 'م', '', '', '', 'مفرد', 'Dz', '', '', '"مِيَاهٌ:أَمْواهٌ"', '', 'Rz', '', '', '', '', '', '', '". 1.: سَائِلٌ لاَ لَوْنَ لَهُ وَلاَ رَائِحَةَ لَهُ، مِنَ الأُوكْسِجِينِ وَالِهيدْرُوجِينِ، يُشْرَبُ. وَأَصْلُهُ ""مَوَه"". ""مَاءٌ صَالِحٌ لِلشُّرْبِ"" الأنبياء آية 30 وَجَعَلْنَا مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ (قرآن). 2.""مَاءُ الزَّهْرِ"" : سَائِلٌ عَطِرُ يُسْتَخْرَجُ مِنْهُ التَّقْطِيرُ. ""مَاءُ الوَرْدِ"". 3.""حَافَظَ عَلَى مَاءِ وَجْهِهِ"" : عَلَى أَنَفَتِهِ وَعِزَّتِهِ وَحَيَائِهِ وَنَضَارَتِهِ. 4.""مَا زَالَ يَتَمَتَّعُ بِمَاءِ الشَّبَابِ"": بِرَوْنَقِهِ وَنَضَارَتِهِ. 5. ""مَاءُ السَّيْفِ"" : رَوْنَقُهُ. 6.""أُصِيبَ بِالْمَاءِ الأَزْرَقِ"" : غِشَاوَةٌ تَتَكَوَّنُ فِي وَسَطِ حَدَقَةِ العَيْنِ فَيَكُفُّ بَصَرُهَا. 7.""مَاءٌ آسِنٌ"" : بِهِ عُفُونَةٌ. 8.""غَطَّتْ مِيَاهُ الأَمْطَارِ كُلَّ الْحُقُولِ"" : مَا يَنْزِلُ مِنْ مَطَرٍ. ""مِيَاهُ البِحَارِ"" ""مِيَاهُ الأَنْهَارِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14863, 'مِيَاهٌ', 'مياه', 'جامد', '', 'مياه', 'مه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14864, 'أَمْواهٌ', 'أمواه', 'جامد', '', 'ءمواه', 'مه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14865, 'مِيثُولُوجِيَّةٌ', 'ميثولوجية', 'جامد', '', 'ميثولوجية', 'مثلجة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '": مَجْمُوعُ الأَسَاطِيرِ الَّتِي نَسَجَتْهَا الشُّعُوبُ قَدِيماً عَنْ تَصَوُّرَاتِهَا لِلْآلِهَةِ وَأَبْطَالِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14866, 'مَائِدَةٌ', 'مائدة', 'جامد', 'ميد', 'ماءدة', 'مدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات:مَوَائِدُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَائِدَةُ الطَّعَامِ"": الخِوَانُ الَّذِي عَلَيْهِ الطَّعَامُ وَالشَّرَابُ. 2.""قَدَّمَ الْمَائِدَةَ لِلضُّيُوفِ"": الطَّعَامَ. 3.""جَلَسُوا لِلتَّفَاوُضِ حَوْلَ مَائِدَةٍ مُسْتَدِيرَةٍ"" : طَاوِلَة أُعْطِيَهَا هَذَا الاسْمُ لأِنَّ الْمُتَفاوِضينَ حَوْلَهَا عَلَى قَدَمِ الْمُسَاوَاةِ وَلاَ أَسْبَقِيَّةَ لِأَحَدٍ فِي الكَلاَمِ على غَيْرِهِ حَيْثُ لاَ بِدَايَةَ لِلدَّائِرَةِ، وَذَلِكَ لِفَضِّ نِزَاعٍ أَوْ خِصَامٍ بَيْنَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14867, 'مَوَائِدُ', 'موائد', 'جامد', '', 'مواءد', 'مد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14868, 'مَيْدَانٌ', 'ميدان', 'جامد', 'ميد', 'ميدان', 'مدن', '', '', '', 'مفرد', 'DnN', '', '', '"مَيَادِينُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""مَيْدَانُ الْحَرْبِ"" : سَاحَتُهَا. 2.""مَيْدَانُ سِبَاقِ الْخَيْلِ"" : البُقْعَةُ الأَرْضِيَّةُ الوَاسِعَةُ الْمُعَدَّةُ لِسِبَاقِ الْخَيْلِ. 3.""دَخَلَ اللاَّعِبُ إِلَى الْمَيْدَانِ"" : سَاحَةُ اللَّعِبِ. 4.""خَرَجَ مِنْ مَيْدَانِ العَمَلِ"" : مِنْ مَجَالِ، حَقْلِ، مِضْمَارِ العَمَلِ. ""لَهُ نُفُوذٌ فِي مَيَادِينِ الثَّقَافَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14869, 'مَيَادِينُ', 'ميادين', 'جامد', '', 'ميادين', 'مدن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14870, 'مِيدَالْيَةٌ', 'ميدالية', 'جامد', '', 'ميدالية', 'مدلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"ج: ـات. ""حَصَلَ عَلَى مِيدَالْيَةٍ ذَهَبِيَّةٍ"" : قِلادَةٌ مِنْ مَعْدِنٍأو ثَوْبٍ تَحْمِلُ رَسْماً أَوْ كِتَابَةً تُسَلَّمُ لِشَخْصٍ تَشْرِيفاً لَهُ إِمَّا بِمُنَاسبَةِ مُبَارَاةٍ وَإمَّا بِمُناسَبَةِ احْتِفَالٍ بِذِكْرَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14871, 'مَيْرُونٌ', 'ميرون', 'جامد', '', 'ميرون', 'مرن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": زَيْتٌ مُقَدَّسٌ عِنْدَ الْمَسِيحِيِّينَ يُمْسَحُ بِهِ الْمُؤْمِنُ فِي بَعْضِ أَسْرَارِ الكَنِيسَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14872, 'مِيعَةٌ', 'ميعة', 'جامد', 'ميع', 'ميعة', 'معة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مِيعَةٌ-مِيعَةٌ [م ي ع]. 1.""مِيعَةُ الشَّبَابِ"" : فَوْرَةُ الشَّبَابِ، بَهَاؤُهُ. 2.""مِيعَةُ النَّهَارِ"" : أَوَّلُهُ، بِدَايَتُهُ. 3.""مِيعَةُ السَّائِلِ"" : سَيَلاَنُ السَّائِلِ الْمَصْبُوبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14873, 'مُيُوعَةٌ', 'ميوعة', 'جامد', 'ميع', 'ميوعة', 'معة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مُيُوعَةٌ-مُيُوعَةٌ [م ي ع]. 1.""مُيُوعَةُ السَّائِلِ"" : سُيُولَتُهُ. 2.""فِي كَلاَمِهِ مُيُوعَةٌ"" : تَهَتُّكٌ، تَغَنُّجٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14874, 'مِيكَانِيكَا', 'ميكانيكا', 'جامد', '', 'ميكانيكا', 'مكنك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R0', '', 'N', 'O', 'N', 'O', '', '": عِلْمُ الآلاَتِ وَكُلُّ مَا لَهُ عَلاَقَةٌ بِالْحَرَكَةِ بِمَعْنَاهَا العَامِّ وَبِالتَّوَازُنِ وَبِالسُّكُونِ أَيْضاً، وَهُوَ قِسْمَانِ. 1.الدِّينَامِيكَا: وَهُوَ العِلْمُ الَّذِي يُبْحَثُ فِيهِ عَنْ حَرَكَةِ الأَجْسَامِ عَلَى الوَجْهِ الَّذِي تُرَاعَى فِيهِ القُوَى. 2. الإِسْتَاتِيكَا: وَهُوَ العِلْمُ الَّذِي يُبْحَثُ فِيهِ عَنْ شُرُوطِ اتِّزَانِ القُوَى وَسُكُونِ الأَجْسَامِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14875, 'مَيكْرُوبٌ', 'ميكروب', 'جامد', '', 'ميكروب', 'مكرب', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. : كَائِنٌ حَيٌّ مُكَوَّنٌ مِنْ خَلِيَّةٍ دَقِيقَةٍ يَنْقُلُ الْجَرَاثِيمَ وَالأَمْرَاضَ الْمُعْدِيَةَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14876, 'إمَالَةٌ', 'إمالة', 'جامد', 'ميل', 'ءمالة', 'إملة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"إمَالَةٌ-إمَالَةٌ [م ي ل]. 1.""إمَالَةُ الوَجْهِ"" : تَحْرِيكُهُ وَتَصْييرُهُ مَائِلاً. 2.""الإمَالَةُ فِي القِرَاءةِ"" : أَي الْمَيْلُ بِالفَتْحَةِ إلَى جِهَةِ الكَسْرَةِ أَوْ مَيْلُ الفَتْحَةِ الَّتِي قَبْلَ الألِفِ إلَى جِهَةِ اليَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14877, 'مِيلٌ', 'ميل', 'جامد', '', 'ميل', 'مل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَمْيَالٌ:أَمْيُلُ"', '', 'R', '', '', '', '', '', '', '"ج: أَمْيَالٌ، أَمْيُلُ. 1.""مِيلُ الكُحْلِ"" : عَصاً دَقِيقَةٌ يُجْعَلُ بِهَا الكُحْلُ فِي الْعَيْنِ. 2.""مِيلُ الْجَرَّاحِ"" : آلَةٌ لِلْجِرَاحَةِ يَسْبِرُ بِهَا الْجُرُوحَ وَنَحْوَهَا. 3.""قَطَعَ مَسَافَةً تُقَدَّرُ بِمِيلٍ"" : مِقْيَاسٌ لِلطُّولِ يُقَدَّرُ بِـ 1200 مِتْرٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14878, 'أَمْيَالٌ', 'أميال', 'جامد', '', 'ءميال', 'مل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14879, 'أَمْيُلُ', 'أميل', 'جامد', '', 'ءميل', 'مل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14880, 'مِيلِشْيَا', 'ميلشيا', 'جامد', '', 'ميلشيا', 'ملش', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ج: ـات. : جَمَاعَةٌ مُكَوَّنَةٌ مِنْ مُوَاطِنِينَ مُسَلَّحِينَ تَقُومُ بِتَدَارِيبَ عَسْكَرِيَّةٍ لِمُوَاجَهَةِ حَالاَتِ الطَّوَارِئِ، وَهِيَ غَالِباً مَّا تَكُونُ فِي البُلْدَانِ الَّتِي لاَ تَمْلِكُ جَيْشاً نِظَامِيّاً، وَتَنْتَمِي إِلَى طَائِفَةٍ مِنَ الطَّوَائِفِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14881, 'مِيلِّغْرَام', 'ميلغرام', 'جامد', '', 'ميلغرام', 'ملغرم', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', 'N', 'O', 'N', 'O', '', '"ج: ـات. : جُزْءٌ مِنْ أَلْفِ جُزْءٍ مِنَ الغرَامِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14882, 'مِيلِّمِتْرٌ', 'ميلمتر', 'جامد', '', 'ميلمتر', 'ملمتر', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', 'N', 'O', 'N', 'O', '', '"ج: ـات. : جُزْءٌ مِنْ أَلْفِ جُزْءٍ مِنَ المِتْرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14883, 'مِيمٌ', 'ميم', 'جامد', '', 'ميم', 'مم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"""يُجِيدُ فَنَّ الْمِيمِ"" : فَنٌّ مِنَ الفُنُونِ التَّمْثيِلِيَّةِ الْهَزْلِيَّةِ، يَعْتَمِدُ التَّعْبِيرَ بِالإِشَارَاتِ وَالْحَرَكَاتِ لاَ بِالكَلاَمِ، يُشَخِّصُ الْمُمَثِّلُ مِنْ خِلاَلِهَا أَعْمَالاً وَعَوَاطِفَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14884, 'مِيمُوزا', 'ميموزا', 'جامد', '', 'ميموزا', 'ممز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R0', '', '', '', '', '', '', '"ن. سَنْطٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14885, 'مِينَاءٌ', 'ميناء', 'جامد', '', 'ميناء', 'من', '', '', '', 'جمع تكسير', 'Dz', '', '', '"مَوَانٍ:مَوَانِئُ"', '', 'Rz', '', '', '', '', '', '', '"ج: مَوَانٍ، مَوَانِئُ. 1.""رَسَتِ السُّفُنُ بِالْمِينَاءِ"" : مَرْسَى السُّفُنِ، الْمَرْفَإِ. 2.""مِينَاءُ السَّاعَةِ"" : وَجْهُهَا الَّذِي فِيهِ عَقْرَبَاهَا وَعَلَيْهِ الأَرْقَامُ. 3.""مِينَاءُ الزُّجَاجِ"" : جَوْهَرُهُ. 4.""مِينَاءُ الْمَعْدِنِ"" : الطِّلاَءُ الَّذِي يُغَشَّى بِهِ كُلُّ مَعْدِنٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14886, 'مَوَانِي', 'مواني', 'جامد', '', 'مواني', 'من', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14887, 'نَاحِيَةٌ', 'ناحية', 'جامد', '', 'ناحية', 'نحة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"نَوَاحٍ:النَّوَاحِي"', '', '', '', '', '', '', '', '', '"ج: نَوَاحٍ، النَّوَاحِي. 1.""فِي النَّاحِيَةِ الْجَنُوبِيَّةِ"" : فِي الْجِهَةِ، فِي الْمِنْطَقَةِ. 2.""مِنْ هَذِهِ النَّاحِيَةِ"" : مِنْ هَذِهِ الوِجْهَةِ، مِنْ هَذَا الْجَانِبِ. 3.""تَنَاوَلَ مَوْضُوعاً مُتَعَدِّدَ النَّوَاحـِي"" : الْمَجَالاَتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14888, 'نَوَاحِي', 'نواحي', 'جامد', '', 'نواحي', 'نح', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14889, 'نَافُورٌ', 'نافور', 'جامد', '', 'نافور', 'نفر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": عِنْدَ الْمَسِيحِيِّينَ سِرُّ القُرْبَانِ الْمُقَدَّسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14890, 'نَافُورَةٌ', 'نافورة', 'جامد', '', 'نافورة', 'نفرة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"نَوَافِيرُ"', '', 'R', '', '', '', '', '', '', '"ج: نَوَافِيرُ. ""نَافُورَةُ مَاءٍ"" : مَكَانٌ فِي دَارٍ أَوْ سَاحَةٍ عُمُومِيَّةٍ أَوْ حَدِيقَةٍ يَنْبُعُ مِنْهُ الْمَاءُ بِتَأْثِيرِ ضَغْطٍ دَاخِلِيٍّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14891, 'نَوَافِيرُ', 'نوافير', 'جامد', '', 'نوافير', 'نفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14892, 'نَافُورِيَّةٌ', 'نافورية', 'جامد', '', 'نافورية', 'نفرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"""الطَّائِرَةُ النَّافُورِيَّةُ"" : الطَّائِرَةُ السَّرِيعَةُ جِدّاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14893, 'نَاقِبَةٌ', 'ناقبة', 'جامد', '', 'ناقبة', 'نقبة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نَاقِبَةٌ-نَاقِبَةٌ (طب). ""أُصِيبَ بِنَاقِبَةٍ"" : قُرْحَة تَخْرُجُ فِي الْجَنْبِ، رَأْسُهَا مِنْ دَاخِلٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14894, 'نَاقَةٌ', 'ناقة', 'جامد', '', 'ناقة', 'نقة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":نُوقٌ:أَنْوَاقٌ"', '', 'R', '', '', '', '', '', '', '"ج: نُوقٌ، نَاقَاتٌ، أَنْوَاقٌ. 1. : الأُنْثَى مِنَ الإِبِلِ. 2.""لاَ نَاقَةَ لِي فِي ذَلِكَ وَلاَ جَمَلَ"" : أَيْ لاَ دَخْلَ لِي فِي ذَلِكَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14895, 'نُوقٌ', 'نوق', 'جامد', '', 'نوق', 'نق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14896, 'أَنْوَاقٌ', 'أنواق', 'جامد', '', 'ءنواق', 'نق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14897, 'نَاقُوسٌ', 'ناقوس', 'جامد', '', 'ناقوس', 'نقس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"نَوَاقِيسُ"', '', 'R', '', '', '', '', '', '', '"ج: نَوَاقِيسُ. 1.""دَقَّ نَاقُوسُ الْمَدْرَسَةِ"" : أَدَاةٌ مِنْ حَدِيدٍ،مُجَوَّفَةٌ مِنَ الدَّاخِلِ عَلَىشَكْلِ كُوبٍ كَبِيرٍ مَقْلُـوبٍ، مَشْدُودَةٌ إِلَى الْجِدَارِ، بِدَاخِلِهَا قَضِيبٌ مِنْ مَعْدِنٍ يُحْدِثُ صَوْتاً عِنْدَ تَحْرِيكِهِ بِوَاسِطَةِ حَبْلٍ أَوسِلْسِلَةٍ. ""نَاقُوسُ الكَنِيسَةِ"". 2.""دَقَّ نَاقُوسُ الْخَطَرِ"": أُثِيرَ الاِنْتِبَاهُ إِلَى خَطَرٍ قَادِمٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14898, 'نَوَاقِيسُ', 'نواقيس', 'جامد', '', 'نواقيس', 'نقس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14899, 'نَامُوسِيَّةٌ', 'ناموسية', 'جامد', '', 'ناموسية', 'نمسة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '": نَسِيجٌ رَقِيقٌ يُجْعَلُ عَلَى السَّرِيرِ وِقَايَةً مِنَ النَّامُوسِ أَوِ الذُّبَابِ؛ كَمَا يُطْلَقُ عَلَى السَّرِيرِ، الفِرَاشِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14900, 'نَايٌ', 'ناي', 'جامد', '', 'ناي', 'ن', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"ج: ـات. (مذ). : آلَةٌ مُوسِيقِيَّةٌ مِنْ فَصِيلَةِ الْهَوَائِيَّاتِ، وَهِيَقَصَبَةٌ جَوْفَاءُ، مَفْتُوحَةُ الطَّرَفَيْنِ، وَعَلَى ظَهْرِهَا الأَمَامِيِّ سِتَّةُ ثُقُوبٍ وَثَقْبٌ وَاحِدٌ عَلَى الظَّهْرِ الْخَلْفِـيِّ، يُنْفَخُ فِيهَا بِالشِّفَاهِ عَلَى حَافَةِ فَتْحَتِهَا. ""أَعْطِنِي النَّايَ وَغَنِّ"". (جبران خ. جبران)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14901, 'آنِسُون', 'آنسون', 'جامد', 'نب', 'ءءنسون', 'آنسن', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '"آنِسُون-آنِسُون [ن ب].: نَبَاتٌ مِنْ فَصِيلَةِ الخَيْمِيَّاتِ، حَوْلِيٌّ، زَهْرُهُ صَغِيرٌ أبْيَضُ، ثَمَرُهُ وَبِزَارُهُ حَبٌّ صَغِيرٌ طَيِّبُ الرَّائِحَةِ، يُسْتَخْرَجُ مِنْهُ عِطْرُ الآنِسُون، وَيُسْتَعْمَلُ فِي أغْرَاضٍ طِبِّيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14902, 'إجَّاصٌ', 'إجاص', 'جامد', 'نب', 'ءجاص', 'إجص', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"إجَّاصٌ-إجَّاصٌ، ةٌ [نب].: شَجَرٌ مِنْ فَصِيلَةِ الوَرْدِيَّاتِ، مُتَوَسِّطُ الطُّولِ، أَسْفَلَهُ مُنْتَفِخٌ، لَهُ ثَمَرٌ لَذِيذٌ. يُعْرَفُ فِي سورِيَة وفلسطين بِالكُمَّثْرَى، وكان يُعْرَفُ فِي مصر بالبُرْقُوقِ. ""اللهُ يُطْعِم الإِجَّـاصَ لِمَنْ لَيْسَ لَهُ أَضْرَاسٌ"". (مثل). يقول الشاعر: ""كَأنَّمَاالإجَّاصُ فِي صِبْغِه*مُسْتَرِقٌ فِي اللوْنِ صِبْغَ الْمُهَجْ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14903, 'ثُومٌ', 'ثوم', 'جامد', 'نب', 'ثوم', 'ثم', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"ثُومٌ-ثُومٌ، ةٌ [نب].: مِنْ فَصيلَةِ الزَّنْبَقِيَّاتِ، بَصَلِيٌّ عُشْبِيٌّ تَتَوَلَّدُ فُصوصُهُ في الأرْضِ، يُسْتَعْمَلُ لِتَطْيِيبِ الطَّعامِ، وَهُوَ قَوِيُّ الطَّعْمِ والرَّائِحَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14904, 'نَبَأٌ', 'نبأ', 'جامد', 'نبأ', 'نبء', 'نب', '', '', '', 'مفرد', 'Dz', '', '', '"أَنْبَاءٌ"', '', 'Rz', '', '', '', '', '', '', '". 1.""جَاءَ بِنَبَإٍ مُثِيرٍ"" : بِخَبَرٍ.النبأ آية 1، 2 عَمَّ يَتَسَاءلُونَ عَنِ النَّبَإِ العَظِيمِ (قرآن). 2.""وَكَالَةُ الأَنْبَاءِ"": الوَكَالَةُ الَّتِي تَمُدُّ الْجَرَائِدَ بِالأَخْبَارِ. 3.""نَشْرَةُ الأَنْبَاءِ بِالإِذَاعَةِ أَوِ التَّلْفَزَةِ"" : نَشْرَةُ الأَخْبَارِ. ""تَنْشُرُ كُلُّ صَحِيفَةٍ أَنْبَاءَ الْمُجْتَمَعِ فِي حِينِهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14905, 'أَنْبَاءٌ', 'أنباء', 'جامد', '', 'ءنباء', 'نب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14906, 'نُبُوءةٌ', 'نبوءة', 'جامد', 'نبأ', 'نبوءة', 'نبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"نُبُوءةٌ-نُبُوءةٌ [ن ب أ]. 1.""صَدَّقَ نُبُوءتَهُ"": صَدَّقَ مَا جَاءَ بِهِ مِنْ أَخْبَارٍ عَنِ الغَيْبِ. 2.""نُبُوءةُ النَّبِيِّ "" : نَقْلُ الوَحْيِ وَتَبْلِيغُهُ مِنَ اللَّهِ إِلَى النَّاسِ. الحديد آية 26وَجَعَلْنَا فِي ذُرِّيَّتِهِمَا النُّبُوءةَ وَالكِتَابَ (قرآن). 3.""لَمْ تَكُنْ نُبُوءتُهُ صَادِقَةً"" : الإِخْبَارُ عَنِ الشَّيْءِ قَبْلَ وَقْتِهِ حَزْراً وتَخْمِيناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14907, 'نُبُوَّةٌ', 'نبوة', 'جامد', 'نبأ', 'نبوة', 'نبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نَبْوَةٌ-نَبْوَةٌ [ن ب و] (مص. نَبَا). "" نَبْوَةُ الدَّهْرِ"" : مُصِيبَتُهُ، جَفْوَتُهُ. ‏""لِكُلِّ جَوَادٍ كَبْوَةٌ ولِكُلِّ فَارِسٍ نَبْوَةٌ"". (مثل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14908, 'مَنْبِتٌ', 'منبت', 'جامد', 'نبت', 'منبت', 'منبت', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَابِتُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَنْبِتُ النَّبَاتِ والزُّهُورِ"" : مَوْضِعُ نَبْتِهَا. 2.""مَنْبِتُ الرَّجُلِ "" : مَنْشَؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14909, 'مَنَابِتُ', 'منابت', 'جامد', '', 'منابت', 'منبت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14910, 'يَنْبُوتٌ', 'ينبوت', 'جامد', 'نبت', 'ينبوت', 'نبت', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"يَنْبُوتٌ-يَنْبُوتٌ، ةٌ [ن ب ت] (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الْقَرْنِيَّاتِ، مُخْشَوْشِبٌ مُعَمِّرٌ، شَائِكٌ، طَوِيلُ الْجُذُورِ، يَكْثُرُ فِي بَعْضِ الأَرَاضِي الزِّرَاعِيَّةِ وَيَصْعُبُ اسْتِئْصَالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14911, 'نُبْذَةٌ', 'نبذة', 'جامد', 'نبذ', 'نبذة', 'نبذة', '', '', '', 'مفرد', 'DnN', '', '', '"نُبَذٌ"', '', 'R', '', '', '', '', '', '', '". ""قَدَّمَ نُبْذَةً عَنْ حَيَاتِهِ"" : جُزْءاً عَنْهَا. "" نُبْذَةٌ تَارِيخِيَّةٌ"" ""نُبْذَةٌ مِنْ كِتَابٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14912, 'نُبَذٌ', 'نبذ', 'جامد', '', 'نبذ', 'نبذ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14913, 'نَبِيذٌ', 'نبيذ', 'جامد', 'نبذ', 'نبيذ', 'نبذ', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْبِذَةٌ"', '', 'R', '', '', '', '', '', '', '". : الْخَمْرُ، شَرَابٌ مُسْكِرٌ يُحَضَّرُ مِنْ عَصِيرِ العِنَبِ أَوِ التَّمْرِ أَوْ غَيْرِهِمَا. ""نَبِيذٌ أَحْمَـرُ"" ""نَبِيذٌ أَبْيَضُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14914, 'أَنْبِذَةٌ', 'أنبذة', 'جامد', '', 'ءنبذة', 'نبذة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14915, 'مِنْبَرٌ', 'منبر', 'جامد', 'نبر', 'منبر', 'منبر', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَابِرُ"', '', 'Rp', '', '', '', '', '', '', '". 1.""صَعِدَ الخَطِيبُ المِنْبَرَ"" : مَحَلٌّمُرْتَفِعٌ، أَوْ كُرْسِيٌّ مُرْتَفِعٌ يَعْتَلِيهِ الخَطِيبُ وَيَتَحَدَّثُ مِنْهُ إِلىَ الجَمْعِ. 2.""مِنْبَرُ العَدَالَةِ"" : مَكَانُ جُلُوسِ القَاضِي. 3.""مِنْبَرُ الرَّأْيِ"": مُنْتَدَى..."', '');
