INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14918, 'أَنْبَارٌ', 'أنبار', 'جامد', '', 'ءنبار', 'نبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14919, 'نِبْرَاسٌ', 'نبراس', 'جامد', 'نبرس', 'نبراس', 'نبرس', '', '', '', 'مفرد', 'DnN', '', '', '"نَبَارِيسُ"', '', 'R', '', '', '', '', '', '', '". 1.""أَشْعَلَ النِّبْـرَاسَ"" : الْمِصْبَاحَ. 2.""اتَّخَذَ مِنْهُ نِبْرَاساً"" : اِتَّخَذَهُ قُدْوَةً وَمِثَالاً. 3.""إِنَّهُ نِبْرَاسُ زَمَانِهِ"" : إِنَّهُ ضَوْءُ عَصْرِهِ."', '');
