INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14921, 'نَبَزٌ', 'نبز', 'جامد', 'نبز', 'نبز', 'نبز', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْبَازٌ"', '', 'R', '', '', '', '', '', '', '". ""هَذَا نَبَزُهُ"" : هَذَا لَقَبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14922, 'أَنْبَازٌ', 'أنباز', 'جامد', '', 'ءنباز', 'نبز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14923, 'مَنْبِضٌ', 'منبض', 'جامد', 'نبض', 'منبض', 'منبض', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَابِضُ"', '', 'R', '', '', '', '', '', '', '"(طب). ""جَسَّ مَنْبِضَ الْمَرِيضِ"" : الْمَحَلُّ الَّذِي يَجُسُّهُ الطَّبِيبُ مِنَ الجِسْمِ لِيَعْرِفَ حَالَةَ نَبْضِ القَلْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14924, 'مَنَابِضُ', 'منابض', 'جامد', '', 'منابض', 'منبض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14925, 'نَبْضَةٌ', 'نبضة', 'جامد', 'نبض', 'نبضة', 'نبضة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَبْضَةٌ-نَبْضَةٌ [ن ب ض]. : الدُّفْقَةُ الوَاحِدَةُ مِنَ النَّبْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14926, 'نَبَطٌ', 'نبط', 'جامد', 'نبط', 'نبط', 'نبط', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْبَاطٌ:نُبُوطٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""نَبَطُ الْفَرَسِ"" : بَيَاضٌ يَكُونُ تَحْتَ إِبْطِهِ وَبَطْنِهِ. 2.""نَبَطُ الإِنْسَانِ"" : بَاطِنُهُ. 3.""نَبَطُ الْبِئْرِ"" : مَا يَظْهَرُ مِنْ مَائِهَا لِأَوَّلِ وَهْلَةٍ. 4.""مِنْ أَهْلِ النَّبَطِ"" : قَوْمٌ كَانُوا يَسْكُنُونَ بَيْنَ الْعِرَاقِ وَالأُرْدُنِ، كَانَتْ لِدَوْلَتِهِمْ حَضَارَةٌ، عَاصِمَتُهَا الْبَتْرَاءُ. وَتُطْلَقُ الآنَ كَلِمَةُ أَنْبَاطٍ عَلَى أَخْلاَطِ النَّاسِ وَعَوَامِّهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14927, 'أَنْبَاطٌ', 'أنباط', 'جامد', '', 'ءنباط', 'نبط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
