INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14929, 'نَبَطِيَّةٌ', 'نبطية', 'جامد', 'نبط', 'نبطية', 'نبطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نَبَطِيَّةٌ-نَبَطِيَّةٌ [ن ب ط]. ""كَلِمَةٌ نَبَطِيَّةٌ"" : عَامِّيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14930, 'مَنْبَعٌ', 'منبع', 'جامد', 'نبع', 'منبع', 'منبع', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَابِعُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَنْبَعُ الْمَاءِ"" : مَخْرَجُهُ. ""مَنَابِعُ المِيَاهِ"". 2.""مَنْبَعُ البِتْرُولِ"" : بِئْرُ البِتْرُولِ. 3.""مَنْبَعُ الْمَشَاكِلِ"" : مَصْدَرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14931, 'مَنَابِعُ', 'منابع', 'جامد', '', 'منابع', 'منبع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14932, 'يَنْبُوعٌ', 'ينبوع', 'جامد', 'نبع', 'ينبوع', 'نبع', '', '', '', 'مفرد', 'DnN', '', '', '"يَنَابِيعُ"', '', 'R', '', '', '', '', '', '', '". 1.""يَنْبُوعُ الْمَاءِ"" : الْعَيْنُ الَّتِي يَخْرُجُ مِنْهَا الْمَاءُ. 2.""يَتَدَفَّقُ السَّهْلُ بِالْيَنَابِيعِ"" : بِالْجَدَاوِلِ كَثِيرَةِ الْمِيَاهِ. 3.""يَنْبُوعُ العِلْمِ وَ الْحِكْمَةِ"" : مَصْدَرُهُ، مَنْبَعُهُ. ""فَجَّرَ اللَّهُ يَنَابِيعَ الْحِكْمَةِ عَلَى لِسَانِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14933, 'يَنَابِيعُ', 'ينابيع', 'جامد', '', 'ينابيع', 'نبع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14934, 'نَبْقِيَّاتٌ', 'نبقيات', 'جامد', 'نبق', 'نبقيات', 'نبقت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"نَبْقِيَّاتٌ-نَبْقِيَّاتٌ [ن ب ق]. : فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الْفِلْقَتَيْنِ، كَثِيرَةُ الْقُعَالاَتِ، مِنْ أَنْوَاعِهَا : النَّبْقُ وَالعُنَّابُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14935, 'نَبْقٌ', 'نبق', 'جامد', '', 'نبق', 'نبق', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نَبْقٌ-نَبْقٌ، ةٌ (نب). 1. : ثَمَرُ السِّدْرِ. 2. : شَجَرَةٌ مِنْ فَصِيلَةِ النَّبْقِيَّاتِ، وَهِيَ مَا يُعْرَفُ بِشَجَرَةِ السِّدْرِ، لَهَا أَغْصَانٌ مُلْسٌ قَلِيلَةُ الِارْتِفَاعِ، أَزْهَارُهَا صَغِيرَةٌ وَثَمَرَتُهَا حُلْوَةٌ تُؤْكَلُ. 3. : دَقِيقٌ يَخْرُجُ مِنْ لُبِّ جِذْعِ النَّخْلَةِ حُلْوٌ، يُسْتَعْمَلُ فِي صُنْعِ النَّبِيذِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14936, 'نِبَالَةٌ', 'نبالة', 'جامد', 'نبل', 'نبالة', 'نبلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نِبَالَةٌ-نِبَالَةٌ [ن ب ل]. : حِرْفَةُ صَانِعِ النِّبَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14937, 'نَبَّالٌ', 'نبال', 'جامد', 'نبل', 'نبال', 'نبل', '', '', '', 'مفرد', 'DnN', '', '', '"نَبَّالَةٌ"', '', 'R', '', '', '', '', '', '', '". 1. : صَانِعُ النِّبَالِ. 2. : الرَّامِي بِالنِّبَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14938, 'نَبَّالَةٌ', 'نبالة', 'جامد', '', 'نبالة', 'نبلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14939, 'نُبْهٌ', 'نبه', 'جامد', 'نبه', 'نبه', 'نبه', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُبْهٌ-نُبْهٌ [ن ب هـ]. ""مُتَمَيِّزٌ بِالنُّبْهِ"" : بِالفِطْنَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14940, 'مَنْتُوجٌ', 'منتوج', 'جامد', 'نتج', 'منتوج', 'منتج', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""مَنْتُوجُ حَقْلٍ"" : مَحْصُولُهُ، غَلاَّتُهُ. ""الْمَنْتُوجَاتُ الفِلاَحِيَّةُ"". 2.""الْمَنْتُوجَاتُ الصِّنَاعِيَّةُ"" : مَصْنُوعَاتُ الصِّنَاعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14941, 'نِتَاجٌ', 'نتاج', 'جامد', 'نتج', 'نتاج', 'نتج', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نِتَاجٌ-نِتَاجٌ [ن ت ج]. 1.""نِتَاجُ الْمَوَاشِي"" : مَا تَضَعُهُ الْمَوَاشِي. 2.""نِتَاجُ مَصْنَعٍ"" : مَا يَصْنَعُهُ مِنْ صَنَائِعَ. 3.""نِتَاجُ شَاعِرٍ أَوْ كَاتِبٍ"" : مَا يَضَعُهُ مِنْ شِعْرٍ أَوْ نَثْرٍ. 4.""نِتَاجُ الفِكْرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14942, 'نَتِيجَةٌ', 'نتيجة', 'جامد', 'نتج', 'نتيجة', 'نتجة', '', '', '', 'مفرد', 'DnN', '', '', '"نَتَائِجُ"', '', '', '', '', '', '', '', '', '". 1.""كَانَ فَوْزُهُ نَتِيجَةَ جُهْدٍ مُتَوَاصِلٍ"" : ثَمَرَةَ جُهْدٍ... 2.""نَتِيجَةُ الامْتِحَانِ"" : حَصِيلَتُهُ أَكَانَتْ إِيجَابِيَّةً أَوْ سَلْبِيَّةً. ""جَاءتْ نَتَائِجُ الامْتِحَانِ سَارَّةً"". 3.""أَسْفَرَتِ الْحَادِثَةُ عَنْ نَتَائِجَ خَطِيرَةٍ"" : مَا يُسْفِرُ عَنِ الْمُقَدِّمَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14943, 'نَتَائِجُ', 'نتائج', 'جامد', '', 'نتاءج', 'نتج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14944, 'نُتَافٌ', 'نتاف', 'جامد', 'نتف', 'نتاف', 'نتف', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نُتَافٌ-نُتَافٌ، ةٌ [ن ت ف]. : مَا سَقَطَ عِنْدَ النَّتْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14945, 'نُتْفَةٌ', 'نتفة', 'جامد', 'نتف', 'نتفة', 'نتفة', '', '', '', 'مفرد', 'DnN', '', '', '"نُتَفٌ"', '', 'R', '', '', '', '', '', '', '". 1.: مَا يُنْتَفُ بِالأُصْبُعِ مِنْ نَبْتٍ وَنَحْوِهِ. 2.""أَعْطَاهُ نُتْفَةً مِنَ الطَّعَامِ"" : أَعْطَاهُ قَلِيلاً مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14946, 'نُتَفٌ', 'نتف', 'جامد', '', 'نتف', 'نتف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14947, 'نَتَانَةٌ', 'نتانة', 'جامد', 'نتن', 'نتانة', 'نتنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نَتَانَةٌ-نَتَانَةٌ [ن ت ن]. ""فِي الغُرْفَةِ نَتَانَةٌ"" : خُبْثُ الرَّائِحَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14948, 'نِجَادَةٌ', 'نجادة', 'جامد', 'نجد', 'نجادة', 'نجدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نِجَادَةٌ-نِجَادَةٌ [ن ج د]. : حِرْفَةُ النَّجَّادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14949, 'نِجَادٌ', 'نجاد', 'جامد', 'نجد', 'نجاد', 'نجد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نِجَادٌ-نِجَادٌ [ن ج د]. 1.""نِجَادُ السَّيْفِ"" : حَمَالَتُهُ. 2.""وَلَدٌ طَوِيلُ النِّجَادِ"" : طَوِيلُ الْقَامَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14950, 'نَاجِذٌ', 'ناجذ', 'جامد', 'نجذ', 'ناجذ', 'نجذ', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"نَوَاجِذُ"', '', '', '', '', '', '', '', '', '". 1.""ضَحِكَ حَتَّى بَدَتْ نَوَاجِذُهُ"" : الأَضْرَاسُ الأَرْبَعَةُ. 2.""عَضَّ عَلَى نَاجِذِهِ"" : بَلَغَ أَشُدَّهُ. 3.""عَضَّ عَلَى شُغْلِهِ بِنَاجِذِهِ "": حَرَصَ عَلَيْهِ. 3.""عَضَّ عَلَى نَاجِذِهِ مُتَأَلِّماً"" : كَمَدَ عَلَى مَا هُوَ عَلَيْهِ، صَبَرَ. ""وَعَضَّ بَعْدَ ذَلِكَ عَلَى نَاجِذِهِ نَدَماً عَلَى سُوءِ فَاعِلِهِ"". (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14951, 'نَوَاجِذُ', 'نواجذ', 'جامد', '', 'نواجذ', 'نجذ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
