INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14953, 'تَنْجَرةٌ', 'تنجرة', 'جامد', 'نجر', 'تنجرة', 'تنجرة', '', '', '', 'مفرد', 'DnN', '', '', '"تَنَاجِرُ"', '', 'R', '', '', '', '', '', '', '".: القِدْرُ الْمَعْدِنِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14954, 'تَنَاجِرُ', 'تناجر', 'جامد', '', 'تناجر', 'تنجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14955, 'مَنْجَرٌ', 'منجر', 'جامد', 'نجر', 'منجر', 'منجر', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاجِرُ"', '', 'R', '', '', '', '', '', '', '". ""مَنْجَرُ النَّجَّارِ"" : مَعْمَلُهُ، أَيْ مَكَانُ النِّجَارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14956, 'مَنَاجِرُ', 'مناجر', 'جامد', '', 'مناجر', 'منجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14957, 'مَنْجُورٌ', 'منجور', 'جامد', 'نجر', 'منجور', 'منجر', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاجِيرُ"', '', '', '', '', '', '', '', '', '". ""مَنْجُورُ البِئْرِ"" : بَكَرَةٌ عَظِيمَةٌ لاسْتِخْرَاجِ الْمَاءِ مِنَ البِئْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14958, 'مَنَاجِيرُ', 'مناجير', 'جامد', '', 'مناجير', 'منجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
