INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14962, 'مَنَاجِعُ', 'مناجع', 'جامد', '', 'مناجع', 'منجع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14963, 'نُجْعَةٌ', 'نجعة', 'جامد', 'نجع', 'نجعة', 'نجعة', '', '', '', 'مفرد', 'DnN', '', '', '"نُجَعٌ"', '', 'R', '', '', '', '', '', '', '". 1.""خَرَجُوا لِلنُّجْعَةِ"" : خَرَجُوا لِطَلَبِ الكَلَإِ فيِ مَوَاضِعِهِ. 2.""هُوَ نُجْعَتِي"" : أَيِ الَّذِي أَقْصِدُهُ مِنْ ذَوِي الْمَعْرُوفِ أَمَلاً فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14964, 'نُجَعٌ', 'نجع', 'جامد', '', 'نجع', 'نجع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14965, 'نِجَافٌ', 'نجاف', 'جامد', 'نجف', 'نجاف', 'نجف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نِجَافٌ-نِجَافٌ [ن ج ف]. 1.""نِجَافُ البَيْتِ"" : مَا بُنِيَ فَوْقَهُ مُشْرِفاً عَلَيْهِ. 2.""نِجَافُ الْمَغَارَةِ"" : صَخْرَةٌ نَاتِئَةٌ تُشْرِفُ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14966, 'نُجْفَةٌ', 'نجفة', 'جامد', 'نجف', 'نجفة', 'نجفة', '', '', '', 'مفرد', 'DnN', '', '', '"نُجَفٌ"', '', 'R', '', '', '', '', '', '', '". ""نُجْفَةٌ مِنَ اللَّبَـنِ"". النَّجَفَةُ : قَلِيلٌ مِنْهُ.لنَّجَفَةُ : مكانٌ مستطيل كالجدار في وسط الوادي لا يعلوه الماء.-: مجموعةٌ من المصابيح الكهربيّة على نظام معيّنٍ متّسقةُ الوضع باهرةُ الضّوء، وسُمِّيت بالثُّريا تشبيهاً بثريَّا السَّماء؛ تدلّت من السَّقف نَجَفَةٌ كبيرة أضاءت المسجد كلَّه.- من الكثيب: إبطُهُ، وهو الموضع الذي تَنْجُفُهُ الرّيحُ فيصير كأنّه جُرُفٌ مُنجرفٌ ج نجَفٌ ونِجَافٌ.', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14967, 'نُجَفٌ', 'نجف', 'جامد', '', 'نجف', 'نجف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14968, 'نَجَفٌ', 'نجف', 'جامد', 'نجف', 'نجف', 'نجف', '', '', '', 'مفرد', 'DnN', '', '', '"نِجَافٌ"', '', 'R', '', '', '', '', '', '', '". 1.""عَلاَ النَّجَفَ"" : التَّلَّ. 2.""سَرَحَتِ الْمَاشِيَةُ فِي النَّجَفِ"" : مَكَانٌ مُسْتَطِيلٌ فِي بَطْنِ الْوَادِي أَوْ فِي بَطْنٍ مِنَ الأَرْضِ لاَ يَعْلُوهُ الْمَاءُ. 3.""النَّجَفُ"" : اِسْمُ مَدِينَةٍ في العِرَاقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14969, 'نِجَافٌ', 'نجاف', 'جامد', '', 'نجاف', 'نجف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14970, 'نَجِيفٌ', 'نجيف', 'جامد', 'نجف', 'نجيف', 'نجف', '', '', '', 'مفرد', 'DnN', '', '', '"نُجُفٌ"', '', 'R', '', '', '', '', '', '', '". ""بَرَى النَّجِيفَ"" : سَهْمٌ عَرِيضُ النَّصْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14971, 'نُجُفٌ', 'نجف', 'جامد', '', 'نجف', 'نجف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14972, 'مِنْجَلٌ', 'منجل', 'جامد', 'نجل', 'منجل', 'منجل', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاجِلُ"', '', '', '', '', '', '', '', '', '". : أَدَاةٌ لِقَطْعِ الزَّرْعِ والأَعْشَابِ، مُكَوَّنَةٌ مِنْ صَفِيحَةٍ مِنْ مَعْدِنٍ، مُنْحَنِيَةٌ مِثْلُ القَوْسِ، ومُرَكَّبَةٌ في مِقْبَضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14973, 'مَنَاجِلُ', 'مناجل', 'جامد', '', 'مناجل', 'منجل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14974, 'نَجْلِيَّاتٌ', 'نجليات', 'جامد', '', 'نجليات', 'نجلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ وَحِيدَاتِ الفِلْقَةِ، أَنْوَاعُهَا عَدِيدَةٌ، أَغْلَبُهَا مِنَ النَّبَاتَاتِ الغِذَائِيَّةِ: القَمْحُ وَالذُّرَةُ وَالأَرُزُّ وَالشَّعِيرُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14975, 'مَنْجَمٌ', 'منجم', 'جامد', 'نجم', 'منجم', 'منجم', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاجِمُ"', '', 'R', '', '', '', '', '', '', '". 1.""لَيْسَ لَهُ مَنْجَمٌ مِنْ هَذَا الْمَأْزِقِ"" : مَخْرَجٌ. 2. : نَفَقٌ تَحْتَ الأَرْضِ يَحْتَوِي عَلَى مَوَادَّ خَامٍ مِنَ الْمَعَادِنِ مِنْ حَدِيدٍ أو فَحْمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14976, 'مَنَاجِمُ', 'مناجم', 'جامد', '', 'مناجم', 'منجم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14977, 'نِجَامَةٌ', 'نجامة', 'جامد', 'نجم', 'نجامة', 'نجمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نِجَامَةٌ-نِجَامَةٌ [ن ج م]. ""عِلْمُ النِّجَامَةِ"" : عِلْمُ النُّجُومِ، أَيْ دَرْسُ أَحْوَالِ النُّجُومِ والبَحْثُ فيها : مَوَاقِعُهَا وَمَوَاقِيتُهَا وَمَسَافَاتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14978, 'مَنْجَاةٌ', 'منجاة', 'جامد', 'نجو', 'منجاة', 'منجة', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاجٍ:الْمَنَاجِي"', '', '', '', '', '', '', '', '', '". ""الصِّدْقُ مَنْجَاةٌ"": بَاعِثٌ عَلَى النَّجَاةِ. ""العِلْمُ زَيْنٌ لِصَاحِبِهِ فِي الرَّخَاءِ ومَنْجَاةٌ لَهُ فِي الشِّدَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14979, 'مَنَاجِي', 'مناجي', 'جامد', '', 'مناجي', 'منج', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14980, 'مَنْجًى', 'منجى', 'جامد', 'نجو', 'منجى', 'منج', '', '', '', 'مفرد', 'Dy', '', '', '"مَنَاجٍ:الْمَنَاجِي"', '', '', '', '', '', '', '', '', '". ""فِي مَنْجىً عَنْ كُلِّ أَذَى"" : فِي مَأْمَنٍ عَنْ ...، فِي مَنْأىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14981, 'مَنَاجِي', 'مناجي', 'جامد', '', 'مناجي', 'منج', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14982, 'نَجِيلٌ', 'نجيل', 'جامد', '', 'نجيل', 'نجل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"نُجُلٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: نُجُلٌ. (نب). : جِنْسُ نَبَاتٍ مِنْ فَصِيلَةِ النَّجْلِيَّاتِ مُعَمِّرٌ، يَكْثُرُ فِي الأَرَاضِي الْمَسْقِيَّةِ، يَضُرُّ بِالزَّرْعِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14983, 'نُجُلٌ', 'نجل', 'جامد', '', 'نجل', 'نجل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14984, 'نُحَاسٌ', 'نحاس', 'جامد', '', 'نحاس', 'نحس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": مَعْدِنٌ أَحْمَرُ اللَّوْنِ ضَارِبٌ إلَى السُّمْرَةِ، قَابِلُ للطَّرْقِ، يُتَّخَذُ فِي صِنَاعَةِ الأَسْلاَكِ وَالأَنَابِيبِ وَالأَوَانِي."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14985, 'نُحَامٌ', 'نحام', 'جامد', '', 'نحام', 'نحم', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"نُحَامٌ-نُحَامٌ، ةٌ (حو). : طَائِرٌ مَائِيٌّ مِنْ فَصِيلَةِ النُّحَامِيَّاتِ كَبِيرُ القَامَةِ، طَوِيلُ العُنُقِ وَالسِّيقَانِ، لَهُ مِنْقَارٌ غَلِيظٌ مَعْقُوفٌ، يَمِيلُ لَوْنُ رِيشِهِ إِلَى حُمْرَةٍ وَرْدِيَّةٍ، يَكْثُرُ بِالشَّوَاطِئِ السَّاحِلِيَّةِ وَعَلَى ضِفَافِ الأَنْهَارِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14986, 'نُحَامِيَّاتٌ', 'نحاميات', 'جامد', '', 'نحاميات', 'نحمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةُ طَيْرٍ مِنْ صُفَيْحِيَّاتِ الْمَنَاقِيرِ، وَرُتْبَةِ كَفِّيَّاتِ القَدَمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14987, 'مَنْحَتٌ', 'منحت', 'جامد', 'نحت', 'منحت', 'منحت', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاحِتُ"', '', 'R', '', '', '', '', '', '', '". : مَكَانُ عَمَلِ النَّحَّاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14988, 'مَنَاحِتُ', 'مناحت', 'جامد', '', 'مناحت', 'منحت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14989, 'نُحَاتَةٌ', 'نحاتة', 'جامد', 'نحت', 'نحاتة', 'نحتة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نِحَاتَةٌ-نِحَاتَةٌ [ن ح ت]. : حِرْفَةُ النَّحَّاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14990, 'نِحَاتَةٌ', 'نحاتة', 'جامد', 'نحت', 'نحاتة', 'نحتة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نُحَاتَةٌ-نُحَاتَةٌ [ن ح ت]. ""اِمْتَلأَ الْمَعْمَلُ بِالنُّحَاتَةِ"" : كُلُّ مَا يَتَسَاقَطُ مِنَ الشَّيْءِ الْمَنْحُوتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14991, 'نَحِيرَةٌ', 'نحيرة', 'جامد', 'نحر', 'نحيرة', 'نحرة', '', '', '', 'مفرد', 'DnN', '', '', '"نَحَائِرُ"', '', '', '', '', '', '', '', '', '". 1.""نَحِيرَةُ الشَّهْرِ"" : أَوَّلُ يَوْمٍ مِنْهُ، أَوْ آخِرُ يَوْمٍ مِنْهُ. 2.""نَحِيرَةُ الإِنْسَانِ"" : نَحِيزَتُهُ، طَبِيعَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14992, 'نَحَائِرُ', 'نحائر', 'جامد', '', 'نحاءر', 'نحر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14993, 'نَحِيزَةٌ', 'نحيزة', 'جامد', 'نحز', 'نحيزة', 'نحزة', '', '', '', 'مفرد', 'DnN', '', '', '"نَحَائِزُ"', '', '', '', '', '', '', '', '', '". 1.""نَحِيزَةُ الإِنْسَانِ"" : طَبِيعَتُهُ. ""رَجُلٌ كَرِيمُ النَّحِيزَةِ"". 2.""أَرْضٌ نَحِيزَةٌ"" : خَشِنَةٌ، صُلْبَةٌ. 3.""نَاقَةٌ نَحِيزَةٌ"" : مَضْرُوبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14994, 'نَحَائِزُ', 'نحائز', 'جامد', '', 'نحاءز', 'نحز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14995, 'نَحَّاسٌ', 'نحاس', 'جامد', 'نحس', 'نحاس', 'نحس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَحَّاسٌ-نَحَّاسٌ [ن ح س]. : صَانِعُ، بَائِعُ النُّحَاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14996, 'نِحْلَةٌ', 'نحلة', 'جامد', 'نحل', 'نحلة', 'نحلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"نِحَلٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""قَدَّمَ لِلْمَشْرُوعِ نِحْلَةً"": عَطِيَّةً مُعْطَاةً تَبَرُّعاً. 2.""نِحْلَةُ الْمَرْأَةِ"" : عَطَاءُ مَهْرِهَا.النساء آية 4وَآتُوا النِّسَاءَ صَدُقَاتِهِنَّ نِحْلَةً (قرآن). 3.""أَظْهَرَ نِحْلَتَهُ"" : عَقِيدَتَهُ، دِينَهُ. ""مَا نِحْلَتُكَ"" ""كَثُرَتِ الْمِلَلُ وَالنِّحَلُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14997, 'نِحَلٌ', 'نحل', 'جامد', '', 'نحل', 'نحل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14998, 'نَحْلِيَّاتٌ', 'نحليات', 'جامد', '', 'نحليات', 'نحلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةُ النَّحْلِ مِنْ رُتْبَةِ غِشَائِيَّاتِ الأَجْنِحَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(14999, 'مَنْحًى', 'منحى', 'جامد', 'نحو', 'منحى', 'منح', '', '', '', 'مفرد', 'Dy', '', '', '"مَنَاحٍ:الْمَنَاحِي"', '', '', '', '', '', '', '', '', '". 1.""اِتَّجَهَ مَنْحىً جَدِيداً"" : اِتِّجَاهاً. ""الْمَنْحَى الأَخْلاَقِيُّ"" ""الْمَنْحَى الفِكْرِيُّ"" ""كُلٌّ ومَنْحَاهُ"". 2.""مَنَاحِي الْحَيَاةِ"" : مَجَالاَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15000, 'مَنَاحِي', 'مناحي', 'جامد', '', 'مناحي', 'منح', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15001, 'نَحِيَّةٌ', 'نحية', 'جامد', 'نحو', 'نحية', 'نحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نَحِيَّةٌ-نَحِيَّةٌ [ن ح و]. ""نَحِيَّةُ الطَّالِبِ"" : قَصْدُهُ، هَدَفُهُ. ""هُوَ نَحِيَّةُ الْمَصَائِبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15002, 'مَنْحَاةٌ', 'منحاة', 'جامد', 'نحي', 'منحاة', 'منحة', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاحٍ:الْمَنَاحِي"', '', '', '', '', '', '', '', '', '". 1.""عَاشَ فِي مَنْحَاةٍ عَنْ أَهْلِ السُّوءِ"" : فِي ابْتِعَادٍ، أَيْ بَيْنَهُ وَبَيْنَهُمْ مَسَافَةٌ. 2.""مَنْحَاةُ نَهْرٍ"" : سَيْلُهُ الْمُلْتَوِي. 3.""أَهْلُ الْمَنْحَاةِ"" : النَّاسُ البُعَدَاءُ الَّذِينَ لَيْسُوا مِنَ الأَقَارِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15003, 'مَنَاحِي', 'مناحي', 'جامد', '', 'مناحي', 'منح', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15004, 'نُخْبَةٌ', 'نخبة', 'جامد', 'نخب', 'نخبة', 'نخبة', '', '', '', 'مفرد', 'DnN', '', '', '"نُخَبٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""نُخْبَةُ الْمُجْتَمَعِ"" : الْمُخْتَارُونَ مِنَ الْمُجْتَمَعَ الَّذِينَ لَهُمْ مُؤَهِّلاَتٌ مُعَيَّنَةٌ. ""نُخْبَةٌ مِنَ الأُدَبَاءِ"". 2.""سِيَاسَةُ النُّخْبَةِ"" : سِيَاسَةُ الانْتِقَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15005, 'نُخَبٌ', 'نخب', 'جامد', '', 'نخب', 'نخب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15006, 'مَنْخَرٌ', 'منخر', 'جامد', 'نخر', 'منخر', 'منخر', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاخِرُ"', '', 'R', '', '', '', '', '', '', '". : ثَقْبُ الأَنْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15007, 'مَنَاخِرُ', 'مناخر', 'جامد', '', 'مناخر', 'منخر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15008, 'نَخْرُوبٌ', 'نخروب', 'جامد', '', 'نخروب', 'نخرب', '', '', '', 'جمع تكسير', 'DnN', '', '', '"نَخَارِيبُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: نَخَارِيبُ. 1.""نَخْرُوبُ حَجَرٍ"" : الشَّقُّ الْمَوْجُودُ فِيهِ. 2.""نَخْرُوبُ النَّحْلِ"" : ثُقَبٌ مُهَيَّأَةٌ مِنَ الشَّمْعِ يَمُجَّ النَّحْلُ فِيهَا العَسَلَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15009, 'نَخَارِيبُ', 'نخاريب', 'جامد', '', 'نخاريب', 'نخرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15010, 'نِخَاسَةٌ', 'نخاسة', 'جامد', 'نخس', 'نخاسة', 'نخسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نِخَاسَةٌ-نِخَاسَةٌ [ن خ س]. : بَيْعُ العَبِيدِ وَشِرَاؤها، حِرْفَةُ النَّخَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15011, 'نُخَاعَةٌ', 'نخاعة', 'جامد', 'نخع', 'نخاعة', 'نخعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نُخَاعَةٌ-نُخَاعَةٌ [ن خ ع]. : مَا يَخْرُجُ مِنْ صَدْرِ الإِنْسَانِ أَوْ خَيْشُومِهِ مِنَ البَلْغَمِ عِنْدَ التَّنَخُّمِ، نُخَامَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15012, 'نُخَاعٌ', 'نخاع', 'جامد', 'نخع', 'نخاع', 'نخع', '', '', '', 'مفرد', 'DnN', '', '', '"نُخُعٌ"', '', 'R', '', '', '', '', '', '', '". : حَبْلٌ عَصَبِيٌّ مُتَّصِلٌ بِالدِّمَاغِ يَجْرِي دَاخِلَ العَمُودِ الفِقْرِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15013, 'نُخُعٌ', 'نخع', 'جامد', '', 'نخع', 'نخع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15014, 'نُخَالَةٌ', 'نخالة', 'جامد', 'نخل', 'نخالة', 'نخلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نُخَالَةٌ-نُخَالَةٌ [ن خ ل]. ""نُخَالَةُ القَمْحِ"" : مَا يَبْقَى مِنَ القَمْحِ بَعْدَ طَحْنِهِ وَنَخْلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15015, 'نَخْلَةٌ', 'نخلة', 'جامد', '', 'نخلة', 'نخلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"نَخْلٌ:نَخِيلٌ"', '', 'R', '', '', '', '', '', '', '"ج: نَخْلٌ، نَخِيلٌ. (نب). : شَجَرَةٌ مِنْ فَصِيلَةِ النَّخْلِيَّاتِ، مُرْتَفِعَةُ الطُّولِ، فِي رَأْسِهَا جَرِيدٌ، تَنْبُتُ فِي الْمَنَاطِقِ الْحَارَّةِ، تُعْطِي ثَمَراً يُعْرَفُ بِالبَلَحِ وَهُوَ أَنْوَاعٌ.الرحمن آية 68 فِيهِمَا فَاكِهَةٌ وَنَخْلٌ وَرُمَّانٌ (قرآن)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15016, 'نَخْلٌ', 'نخل', 'جامد', '', 'نخل', 'نخل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15017, 'نَخِيلٌ', 'نخيل', 'جامد', '', 'نخيل', 'نخل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15018, 'نَخْلِيَّاتٌ', 'نخليات', 'جامد', '', 'نخليات', 'نخلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ وَحِيدَاتِ الفِلْقَةِ، مُتَعَدِّدَةُ الأَنْوَاعِ وَالأَجْنَاسِ، تَنْبُتُ فِي الْمَنَاطِقِ الْحَارَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15019, 'نُخَامَةٌ', 'نخامة', 'جامد', 'نخم', 'نخامة', 'نخمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نُخَامَةٌ-نُخَامَةٌ [ن خ م]. : الْمُخَاطُ الَّذِي يُدْفَعُ مِنَ الصَّدْرِ أَوِ الأَنْفِ، نُخَاعَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15020, 'نَدْأَةٌ', 'ندأة', 'جامد', 'ندأ', 'ندءة', 'ندة', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', 'N', 'O', 'O', 'O', '', '"نَدْأَةٌ-نَدْأَةٌ [ن د أ]. 1.""نَدْأَةُ الغُرُوبِ"" : الْحُمْرَةُ فِي الغَيْمِ. ""نَدْأَةُ الشُّرُوقِ"". 2.""ظَهَرَتِ النَّدْأَةُ بَيْنَ الغُيُومِ"" : قَوْسُ قُزَحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15021, 'مَنْدَبٌ', 'مندب', 'جامد', 'ندب', 'مندب', 'مندب', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَادِبُ"', '', 'R', '', '', '', '', '', '', '". ""كَانَ مَنْدَبُهُمْ يُثِيرُ الأَشْجَانَ والأَحْزَانَ"" : البُكَاءُ، النُّوَاحُ عَلَى الْمَيِّتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15022, 'مَنَادِبُ', 'منادب', 'جامد', '', 'منادب', 'مندب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15023, 'مِنْدَفٌ', 'مندف', 'جامد', 'ندب', 'مندف', 'مندف', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَنَادِفُ"', '', 'R', '', '', '', '', '', '', '". : خَشَبَةٌ يُنْدَفُ بِهَا القُطْنُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15024, 'مَنَادِفُ', 'منادف', 'جامد', '', 'منادف', 'مندف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15025, 'مَنْدُوحَةٌ', 'مندوحة', 'جامد', 'ندح', 'مندوحة', 'مندحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَنْدُوحَةٌ-مَنْدُوحَةٌ [ن د ح]. ""لاَ مَنْدُوحَةَ لَكَ عَنْ هَذَا العَمَلِ"" : لاَ غِنـىً لَكَ عَنْهُ. ""لَكَ هَذَا الأَمْرُ مَنْدُوحَةٌ"" : أَيْ يُمْكِنُكَ تَرْكُهُ والْمَيْلُ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15026, 'نِدٌّ', 'ند', 'جامد', 'ندد', 'ند', 'ند', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْدَادٌ"', '', 'R', '', '', '', '', '', '', '". 1.""مَا لَهُ نِدٌّ"" : أَيْ مَا لَهُ نَظِيٌر وَ لاَ مَثِيلٌ.البقرة آية 22 فَلاَ تَجْعَلُوا للَّهِ أَنْدَاداً وَأَنْتُمْ تَعْلَمُونَ (قرآن). 2.""خَرَجَ مَعَ نِدِّهِ"" : مَعَ مَنْ فِي سِنِّهِ، مَعَ قَرِينِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15027, 'أَنْدَادٌ', 'أنداد', 'جامد', '', 'ءنداد', 'ندد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15028, 'نَادِرَةٌ', 'نادرة', 'جامد', 'ندر', 'نادرة', 'ندرة', '', '', '', 'مفرد', 'DnN', '', '', '"نَوَادِرُ"', '', '', '', '', '', '', '', '', '". 1.""رَوَى لَهُ نَادِرَةً "" : قِصَّةً غَيْرَ مَأْلُوفَةٍ تَتَضَمَّنُ أَشْيَاءَ غَرِيبَةً طَرِيفَةً. 2."" هُوَ نَادِرَةُ زَمَانِهِ"" : وَحِيدُ عَصْرِهِ. 3.""نَوَادِرُ الأَلْفَاظِ"" : أَلْفَاظٌ غَيْرُ مُتَدَاوَلَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15029, 'نَوَادِرُ', 'نوادر', 'جامد', '', 'نوادر', 'ندر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15030, 'نُدْرَةٌ', 'ندرة', 'جامد', 'ندر', 'ندرة', 'ندرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نُدْرَةٌ-نُدْرَةٌ [ن د ر]. 1.""عَاشُوا سَنَوَاتٍ صَعْبَةً لِنُدْرَةِ الأَمْطَـارِ"" : لِقِلَّةِ الأَمْطَارِ. 2.""لاَ يَكُونُ ذَلِكَ إِلاَّ نُدْرَةً أَوْ فِي النُّدْرَةِ"" : إِلاَّ أَحْيَاناً قَلِيلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15031, 'نَوَادِرُ', 'نوادر', 'جامد', 'ندر', 'نوادر', 'ندر', '', '', '', 'مفرد', '', '', '', '"مفردنَادِرَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""نَوَادِرُ الكَلاَمِ"" : غَرَائِبُهُ. 2.""يَأْتِي بِنَوَادِرِ الكَلاَمِ فِي حَدِيثِهِ"" : يَأْتِي بِالفَصِيحِ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15032, 'نُدَافَةٌ', 'ندافة', 'جامد', 'ندف', 'ندافة', 'ندفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نِدَافَةٌ-نِدَافَةٌ [ن د ف]. : صَنْعَةُ النَّدَّافِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15033, 'نِدَافَةٌ', 'ندافة', 'جامد', 'ندف', 'ندافة', 'ندفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نُدَافَةٌ-نُدَافَةٌ [ن د ف]. ""نُدَافَةُ الصُّوفِ"" : مَا يَسْقُطُ مِنْهُ عِنْدَ النَّدْفِ"". ""نُدَافَةُ القُطْنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15034, 'نُدْفَةٌ', 'ندفة', 'جامد', 'ندف', 'ندفة', 'ندفة', '', '', '', 'مفرد', 'DnN', '', '', '"نُدَفٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""نُدْفَةُ لَبَنٍ"" : القَلِيلُ مِنْهُ. 2.""نُدْفَةُ الثَّلْجِ"" : مَا يَنْزِلُ مِنْهُ شَفَّافاً كَالقُطْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15035, 'نُدَفٌ', 'ندف', 'جامد', '', 'ندف', 'ندف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15036, 'مَنْدِيلٌ', 'منديل', 'جامد', 'ندل', 'منديل', 'مندل', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَادِيلُ"', '', 'R', '', '', '', '', '', '', '". ""أَخْرَجَ مَنْدِيلَهُ مِنْ جَيْبِهِ وَمَسَحَ بِهِ وَجْهَهُ"" : قِطْعَةٌ صَغِيرَةٌ مِنْ قُمَاشٍ أَوْ وَرَقٍ شَفَّافٍ، تُسْتَعْمَلُ لِتَجْفِيفِ الْمَاءِ وَمَسْحِ الْعَرَقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15037, 'مَنَادِيلُ', 'مناديل', 'جامد', '', 'مناديل', 'مندل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15038, 'مَنْدَمٌ', 'مندم', 'جامد', 'ندم', 'مندم', 'مندم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَنْدَمٌ-مَنْدَمٌ [ن د م]. ""عَاشَ لَحْظَةَ مَنْدَمٍ"" : لَحْظَةَ نَدَامَةٍ وأَسَفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15039, 'نَدْهَةٌ', 'ندهة', 'جامد', 'نده', 'ندهة', 'ندهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نَدْهَةٌ-نَدْهَةٌ [ن د هـ]. 1.""سَمِعَ نَدْهَتَهُ"" : صَوْتَهُ. 2.""نَدْهَةُ التَّاجِرِ"" : كَثْرَةُ مَالِهِ وَمَوَاشِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15040, 'مُنْتَدًى', 'منتدى', 'جامد', 'ندو', 'منتدى', 'منتد', '', '', '', 'مفرد', 'Dy', '', '', '"مُنْتَديَات"', '', '', '', '', '', '', '', '', '". ""مُنْتَدَى الْجَمَاعَةِ"" : الْمَجْلِسُ، النَّادِي الَّذِي يَجْتَمِعُ فِيهِ النَّاسُ لِلْحِوَارِ والسَّمَرِ والتَّدَاوُلِ. ""كَانَ بَيْتُهُ مُنْتَدىً لِلْأُدَبَاءِ والشُّعَرَاءِ"" ""مُنْتَدَى الفِكْرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15041, 'مُنْتَديَات', 'منتديات', 'جامد', '', 'منتديات', 'منتدت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15042, 'نَذِيرَةٌ', 'نذيرة', 'جامد', 'نذر', 'نذيرة', 'نذرة', '', '', '', 'مفرد', 'DnN', '', '', '"نَذَائِرُ"', '', '', '', '', '', '', '', '', '". 1.""قَدَّمَ نَذِيرَةً"" : مَا يُعْطَى نَذْراً. 2.""جَعَلَهُ نَذِيرَةً لِلْكَنِيسَةِ"" : الوَلَدُ الَّذِي يَجْعَلُهُ أَبُوهُ قَيِّماً أَوْ خَادِماً لِلْكَنِيسَةِ، وَيُمْكِنُ أَنْ يَكُونَ ذَكَراً أَوْ أُنْثَى. 3.""نَذِيرَةُ الجَيْشِ"" : طَلِيعَةُ الْجَيْشِ الَّتِي تُنْذِرُهُمْ بِأَمْرِ العَدُوِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15043, 'نَذَائِرُ', 'نذائر', 'جامد', '', 'نذاءر', 'نذر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15044, 'نَرْجِسٌ', 'نرجس', 'جامد', '', 'نرجس', 'نرجس', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نَرْجِسٌ-نَرْجِسٌ، ةٌ (نب). 1. : جِنْسُ نَبَاتٍ، مِنْ فَصِيلَةِ النَّرْجِسِيَّاتِ يُزْرَعُ لِجَمَالِ زَهْرِهِ وَطِيبِ رَائِحَتِهِ. 2.""نَرْجِسُ"" : اِسْمُ عَلَمٍ للإِنَاثِ..."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15045, 'نَرْجِسِيَّاتٌ', 'نرجسيات', 'جامد', '', 'نرجسيات', 'نرجست', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ وَحِيدَاتِ الفِلْقَتَيْنِ، كَثِيرَةُ الأَنْوَاعِ وَالأَجْنَاسِ، أَشْهَرُهَا النَّرْجِسُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15046, 'نَرْدٌ', 'نرد', 'جامد', '', 'نرد', 'نرد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": لُعْبَةٌ تُعْرَفُ بِلُعْبَةِ الطَّاوِلَةِ أَوْ طَاوِلَةِ الزَّهْرِ، وَهِيَ ذَاتُ صُنْدُوقٍ وَحِجَارَةٍ وَفَصَّيْنِ، تَعْتَمِدُ عَلَى الْحَظِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15047, 'مَنْزَعٌ', 'منزع', 'جامد', 'نزع', 'منزع', 'منزع', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَازِعُ"', '', 'R', '', '', '', '', '', '', '". ""نَزَعَ مَنْزَعاً جَدِيداً"" : مَنْحىً، مَيْلاً، نُزُوعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15048, 'مَنَازِعُ', 'منازع', 'جامد', '', 'منازع', 'منزع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15049, 'نُزْفَةٌ', 'نزفة', 'جامد', 'نزف', 'نزفة', 'نزفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"نُزْفَةٌ-نُزْفَةٌ [ن ز ف]. ""نُزْفَةُ مَاءٍ"" : قَلِيلٌ مِنْهُ. ""نُزْفَةُ دَمٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15050, 'نَيْزَكٌ', 'نيزك', 'جامد', 'نزك', 'نيزك', 'نزك', '', '', '', 'مفرد', 'DnN', '', '', '"نَيَازِكُ"', '', 'R', '', '', '', '', '', '', '". 1. : الرُّمْحُ القَصِيرُ. 2.(فك).: جِسْمٌ مُسْتَقِلٌّ يَخْتَرِقُ الجَوَّ فَيَحْتَدِمُ وَيُضِيءُ ثُمَّ يَسْقُطُ أَحْيَاناً شِهَاباً نَيِّراً إِلَى الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15051, 'نَيَازِكُ', 'نيازك', 'جامد', '', 'نيازك', 'نزك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15052, 'مَنْزِلَةٌ', 'منزلة', 'جامد', 'نزل', 'منزلة', 'منزلة', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَازِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَنْزِلَةُ القَافِلَةِ"" : مَوْضِعُ نُزُولِهَا. 2.""لَهُ مَنْزِلَةٌ كَبِيرَةٌ عِنْدَ أَهْلِهِ"" : مَكَانَةٌ، رُتْبَةٌ. ""هُوَ رَفِيعُ الْمَنْزِلَةِ"" ""لَهُ مَنْزِلَةٌ عَالِيَةٌ"" ""مَنْزِلَةٌ سَامِيَةٌ"". 3.""هُوَ بِمَنْزِلَةِ ابْنِهِ"" : هُوَ بِمَثَابَةِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15053, 'مَنَازِلُ', 'منازل', 'جامد', '', 'منازل', 'منزل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15054, 'مَنْزِلٌ', 'منزل', 'جامد', 'نزل', 'منزل', 'منزل', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَازِلُ"', '', '', '', '', '', '', '', '', '". 1.""زَارَهُ فِي مَنْزِلِهِ"" : فِي دَارِهِ، أَيْ مَكَانِ سَكَنِهِ. 2.""أَنْزَلَهُ مَنْزِلاً حَسَناً"" : مَكَاناً. ""مَنَازِلُ اللَّهْوِ وَاللَّعِبِ"". 3.""مَنْزِلُ الزَّوْجِيَّةِ"" : بَيْتٌ... 4.""مَنَازِلُ الْقَمَرِ"" : مَدَارَاتُهُ الَّتِي يَدُورُ فِيهَا حَوْلَ الأَرْضِ وَهِيَ ثَمَانِيَةٌ وَعِشْرُونَ، وَلِكَلِّ فَصْلٍ مِنْ فُصُولِ السَّنَةِ سَبْعَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15055, 'مَنَازِلُ', 'منازل', 'جامد', '', 'منازل', 'منزل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15056, 'نَازِلَةٌ', 'نازلة', 'جامد', 'نزل', 'نازلة', 'نزلة', '', '', '', 'مفرد', 'DnN', '', '', '"نَوَازِلُ"', '', '', '', '', '', '', '', '', '". 1.""حَلَّتْ بِهِ نَازِلَةٌ"" : مُصِيبَةٌ شَدِيدَةٌ. ""نَوَازِلُ الدَّهْرِ"". 2.""النَّازِلَةُ فِي الشَّرْعِ"" : قَضِيَّةٌ عَدْلِيَّةٌ. 3.""النَّازِلَةُ فِي الفِقْهِ"" : قَضِيَّةٌ مُسْتَحْدَثَةٌ مِنْ قَضَايَا الْمُجْتَمَعِ، تَسْتَدْعِي حُكْماً شَرْعِيّاً أَوْ فَتْوَى مِنْ لَدُنِ فَقِيهٍ تَتَوَافَرُ فِيهِ شُرُوطُ الفَتْوَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15057, 'نَوَازِلُ', 'نوازل', 'جامد', '', 'نوازل', 'نزل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15058, 'نُزَالَةٌ', 'نزالة', 'جامد', 'نزل', 'نزالة', 'نزلة', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نِزَالَةٌ-نِزَالَةٌ [ن ز ل] (مص. نَزَلَ). ""نِزَالَةُ الضَّيْفِ"" : ضِيَافَتُهُ. ""كُنَّا فِي نِزَالَتِهِ فَكَانَ أَفْضَلَ مُضِيفٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15059, 'نُزُلٌ', 'نزل', 'جامد', 'نزل', 'نزل', 'نزل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُزُلٌ-نُزُلٌ، نُزْلٌ [ن ز ل]. 1.""اِسْتَقَرَّ فِي نُزْلِهِ"" : فِي مَنْزِلِهِ. 2.""نُزُلُ السُّيَّاحِ وَالْمُسَافِرِينَ"" : الفُنْدُقُ.الكهف أية 107 كَانَتْ لَهُمْ جَنَّاتُ الفِرْدَوْسِ نُزُلا (قرآن) : مَكَانُ كُلِّ شَيْءٍ مُهَيَّإٍ مِنْ طَعَامٍ وَنَوْمٍ هَادِئٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15060, 'نَزِيلٌ', 'نزيل', 'جامد', 'نزل', 'نزيل', 'نزل', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"نُزَلاَءُ"', '', '', '', '', '', '', '', '', '". 1.""جَاءَ نَزِيلاً عِنْدَهُ"" : ضَيْفاً. ""هُوَ نَزِيلِي"". 2.""نَزِيلُ فُنْدُقٍ"" : الْمُقِيمُ فِيهِ. 3.""نُزَلاَءُ الْمُسْتَشْفَى"" : الْمَرْضَى الْمُقِيمُونَ بِالْمُسْتَشْفَى. 4.""نَزِيلُ سِجْنٍ"" : السَّجِينُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15061, 'نُزَلاَءُ', 'نزلاء', 'جامد', '', 'نزلاء', 'نزل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15062, 'نَوَازِلُ', 'نوازل', 'جامد', 'نزل', 'نوازل', 'نزل', '', '', '', 'مفرد', '', '', '', '"مفردنَازِلَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""يُشَاوِرُ أَهْلَ الرَّأْيِ فِي الأُمُورِ وَيَأْخُذُ آرَاءهُمْ فِي الْحَوَادِثِ وَالنَّوَازِلِ"" : الْقَضَايَا الْعَدْلِيَّةُ أَوِ الفِقْهِيَّةُ. ن. نَازِلَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15063, 'مَنْزَهٌ', 'منزه', 'جامد', 'نزه', 'منزه', 'منزه', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَازِهُ"', '', 'R', '', '', '', '', '', '', '". ""خَرَجَ إِلَى الْمَنْزَهِ "" : مَكَان النُّزْهَةِ، الْحَدِيقَة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15064, 'مَنَازِهُ', 'منازه', 'جامد', '', 'منازه', 'منزه', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15065, 'نَسْءٌ', 'نسء', 'جامد', 'نسأ', 'نسء', 'نس', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"نَسْءٌ-نَسْءٌ [ن س أ]. 1.""سَقَى الوَلَدَ نَسْئاً"" : لَبَناً كَثِيرَ الْمَاءِ. 2.""سَقَى صَاحِبَهُ نَسْئاً"" : شَرَاباً قَوِيّاً مُزِيلاً لِلْعَقْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15066, 'نُسْأَةٌ', 'نسأة', 'جامد', 'نسأ', 'نسءة', 'نسة', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"نُسْأَةٌ-نُسْأَةٌ [ن س أ]. 1. : تَأْخِيرٌ. 2.""بَاعَهُ بِنُسْأَةٍ"" : أَيْ بِتَأْخِيرِ دَفْعِ الثَّمَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15067, 'نَسَا', 'نسا', 'جامد', '', 'نسا', 'نس', '', '', '', 'جمع تكسير', 'DyDw', '', '', '"إِنْسَاءٌ:مُثَنَّاهُنَسَوَانِ', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"ج: إِنْسَاءٌ، مُثَنَّاهُ نَسَوَانِ، نَسَيَانِ : عَصَبٌ مُمْتَدٌّ مِنَ الوَرِكِ إِلَى الكَعْبِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15068, 'إِنْسَاءٌ', 'إنساء', 'جامد', '', 'ءنساء', 'إنس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15069, 'مِنْسَاجٌ', 'منساج', 'جامد', 'نسج', 'منساج', 'منسج', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاسِيجُ"', '', 'R', '', '', '', '', '', '', '". ""مِنْسَاجُ النَّسَّاجِ"" : آلَةٌ تُمَدُّ عَلَيْهَا الْخُيُوطُ لِصُنْعِ الثِّيَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15070, 'مَنَاسِيجُ', 'مناسيج', 'جامد', '', 'مناسيج', 'منسج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15071, 'نِسَاجَةٌ', 'نساجة', 'جامد', 'نسج', 'نساجة', 'نسجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نِسَاجَةٌ-نِسَاجَةٌ [ن س ج]. : حِرْفَةُ النَّسَّاجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15072, 'نُسْخَةٌ', 'نسخة', 'جامد', 'نسخ', 'نسخة', 'نسخة', '', '', '', 'مفرد', 'DnN', '', '', '"نُسَخٌ"', '', 'R', '', '', '', '', '', '', '". 1.""سَلَّمَهُ نُسْخَةً مِنَ الكِتَابِ"" : كِتَاباً وَاحِداً. 2.""نُسْخَةٌ طِبْقَ الأَصْلِ"" : الوَرَقَةُ الْمَنْقُولَةُ الْمُطَابِقَةُ لِلْمَنْقُولِ عَنْهَا. 3.""طَبَعَ مِنَ الكِتَابِ أَلْفَ نُسْخَةٍ"" : الكِتَابُ نَفْسُهُ مُكَرَّراً أَلْفَ مَرَّةٍ. ""يَمْلِكُ عَدَداً مَحْدُوداً مِنَ النُّسَخِ"". 4.""هُوَ نُسْخَةٌ مِنْ أَبِيهِ"" : أَيْ شَبِيهٌ لأَبِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15073, 'نُسَخٌ', 'نسخ', 'جامد', '', 'نسخ', 'نسخ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15074, 'نَوَاسِخُ', 'نواسخ', 'جامد', 'نسخ', 'نواسخ', 'نسخ', '', '', '', 'مفرد', '', '', '', '"مفردنَاسِخ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""النَّوَاسِخُ فِي النَّحْوِ"" : هِيَ الْكَلِمَاتُ الَّتِي تَدْخُلُ عَلَى الْمُبْتَدَإِ وَالْخَبَرِ فَتُغَيِّرُ حُكْمَهَا لَفْظاً وَمَعْنـىً، كَالأَفْعَالِ النَّاقِصَةِ، وَأَفْعَالِ الْمُقَارَبَةِ، وَالأَحْرُفِ الْمُشَبَّهَةِ بِالأَفْعَالِ، وَأَفْعَالِ الْقُلُوبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15075, 'نَاسِخ', 'ناسخ', 'جامد', '', 'ناسخ', 'نسخ', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15076, 'نَسْرٌ', 'نسر', 'جامد', '', 'نسر', 'نسر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"نُسُورٌ"', '', 'R', '', '', '', '', '', '', '"ج: نُسُورٌ. (حو). : طَائِرٌ مِنْ فَصِيلَةِ النَّسْرِيَّاتِ، مِنَالكَوَاسِرِ، مِنْ رُتْبَةِ الصَّقْرِيَّاتِ، لَهُ رَأْسٌ وَعُنُقٌ عَارِيَـانِ وَمُلَوَّنَانِ، وَمِنْقَارٌ مَعْقُوفٌ مُدَبَّبٌ، وَمَخَالِبُ قَصِيرَةٌ وَجَنَاحَانِ كَبِيرَانِ، يَتَغَذَّى بِالْجِيفِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15077, 'نُسُورٌ', 'نسور', 'جامد', '', 'نسور', 'نسر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15078, 'نَسْرِيَّاتٌ', 'نسريات', 'جامد', '', 'نسريات', 'نسرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةُ النُّسُورِ مِنْ رُتْبَةِ الكَوَاسِرِ، وَهِيَ تَشْمُلُ النَّسْرَ وَالأَنُوقَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15079, 'نِسْرِينٌ', 'نسرين', 'جامد', '', 'نسرين', 'نسرن', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"نِسْرِينٌ-نِسْرِينٌ، ةٌ (نب). 1. : نَبَاتٌ مِنْ فَصِيلَةِ الوَرْدِيَّاتِ، وَرْدُهُ أَبْيَضُ عَطِرٌ، رَائِحَتُهُ قَوِيَّةٌ. 2.""نِسْرِينُ"" : اِسْمُ عَلَمٍ للإِنَاثِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15080, 'نُسْغٌ', 'نسغ', 'جامد', '', 'نسغ', 'نسغ', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"نُسْغٌ-نُسْغٌ (نب). : سَائِلٌ يَكُونُ فِي الْخَلِيَّةِ، كَمَا يَجْرِي فِي أَنْسَاجِ النَّبَاتِ لِتَغْذِيَتِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15081, 'نَسَّافَةٌ', 'نسافة', 'جامد', 'نسف', 'نسافة', 'نسفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""اِنْطَلَقَتِ القَذَائِفُ مِنَ النَّسَّافَةِ"" : سَفِينَةٌ حَرْبِيَّةٌ تُسْتَخْدَمُ أَثْنَاءَ الْمَعَارِكِ لِنَسْفِ مُنْشَآتِ العَدُوِّ، وَحُصُونِهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15082, 'نُسَافَةٌ', 'نسافة', 'جامد', 'نسف', 'نسافة', 'نسفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نُسَافَةٌ-نُسَافَةٌ [ن س ف]. 1. : مَا يَسْقُطُ مِنَ الْمِنْسَفِ. 2. : الغِرْبَالُ الكَبِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15083, 'نَسَفَةٌ', 'نسفة', 'جامد', 'نسف', 'نسفة', 'نسفة', '', '', '', 'مفرد', 'DnN', '', '', '"نِسَفٌ:نِسَافُ"', '', 'R', '', '', '', '', '', '', '". ""نَسَفَةُ الأَقْدَامِ"": حِجَارَةٌ ذَاتُ أَسْنَانٍ أَوْ نَخَارِيبَ يُنْسَفُ بِهَا الوَسَخُ عَنِ الأَقْدَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15084, 'نِسَفٌ', 'نسف', 'جامد', '', 'نسف', 'نسف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
