INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15086, 'مِنْسَفٌ', 'منسف', 'جامد', 'نسق', 'منسف', 'منسف', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاسِفُ"', '', 'R', '', '', '', '', '', '', '". : غِرْبَالٌ كَبِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15087, 'مَنَاسِفُ', 'مناسف', 'جامد', '', 'مناسف', 'منسف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15088, 'نَسَقٌ', 'نسق', 'جامد', 'نسق', 'نسق', 'نسق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَسَقٌ-نَسَقٌ [ن س ق]. 1.""عَلَى نَسَقٍ وَاحِدٍ"" : عَلَى نَمَطٍ وَاحِدٍ. 2.""سَارَ عَلَى نَسَقِهِ"" : مِنْوالِهِ، أَي حَاكَاهُ وَسَارَ عَلَى سَيْرِهِ. 3.""حُرُوفُ النَّسَقِ"" : حُرُوفُ العَطْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15089, 'مَنَاسِكُ', 'مناسك', 'جامد', 'نسك', 'مناسك', 'منسك', '', '', '', 'مفرد', '', '', '', '"مفردمَنْسَك"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""مَنَاسِكُ الْحَجِّ"" : شَعَائِرُهُ، عِبَادَاتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15090, 'مَنْسَك', 'منسك', 'جامد', '', 'منسك', 'منسك', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15091, 'نُسُكٌ', 'نسك', 'جامد', 'نسك', 'نسك', 'نسك', '', '', '', 'مفرد', 'DnN', '', '', '"نَسيكَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""يَعِيشُ العَابِدُ في نُسُكٍ"" : في عِبَادَةٍ. 2.الأنعام آية 162 قُلْ إِنَّ صَلاَتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ (قرآن) : أَيْ كُلُّ حَقٍّ لِلَّهِ عَزَّ وَجَلَّ. 3.""قَدَّمَ نُسُكاً"" : نُسْكاً، ذَبِيحَةً.البقرة آية 196 فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ (قرآن)."', '');
