INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15093, 'نَسِيكَةٌ', 'نسيكة', 'جامد', 'نسك', 'نسيكة', 'نسكة', '', '', '', 'مفرد', 'DnN', '', '', '"نَسَائِكُ:نُسُكٌ"', '', '', '', '', '', '', '', '', '". 1.""قَدَّمَ نَسِيكَةً"" : نُسْكاً، ذَبِيحَةً. البقرة آية 196فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ (قرآن). 2.""نَسِيكَةُ فِضَّةٍ أَوْ ذَهَبٍ"" : سَبِيكَةٌ."', '');
