INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15096, 'نُسَالٌ', 'نسال', 'جامد', 'نسل', 'نسال', 'نسل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُسَالٌ-نُسَالٌ [ن س ل]. : مَا يَسْقُطُ مِنَ الصُّوفِ أَوِ الشَّعْرِ عِنْدَ النَّسْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15097, 'مَنْسِمٌ', 'منسم', 'جامد', 'نسم', 'منسم', 'منسم', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاسِمُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَنْسِمُ الْجَمَلِ"" : طَرَفُ خُفِّهِ. 2.""لَقَدِ اسْتَبَانَ الْمَنْسِمُ"" : الطَّرِيقُ. 3.""أَيْنَ مَنْسِمُكَ "" : أَيْنَ مُتَوَجَّهُكَ، مَذْهَبُكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15098, 'مَنَاسِمُ', 'مناسم', 'جامد', '', 'مناسم', 'منسم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15099, 'نَسَمَةٌ', 'نسمة', 'جامد', 'نسم', 'نسمة', 'نسمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":نَسَمٌ"', '', 'R', '', '', '', '', '', '', '". 1.""بَلَغَ عَدَدُ سُكَّانِ البِلاَدِ ثَلاَثِينَ مَلْيُوناً نَسَمَةً"" : فَرْداً، أَيْ إِنْسَاناً، وَالكَلِمَةُ تُطْلَقُ عَلَى كُلِّ كَائِنٍ حَيٍّ. 2. : ضَيْقُ التَّنَفُّسِ النَّاشِئِ مِنِ انْقِبَاضَاتٍ وَقْتِيَّةٍ فِي عَضَلاَتِ الشُّعَيْبَاتِ الرِّئَوِيَّةِ، وَتُسَبِّبُهُ حَسَاسِيَّةٌ ذَاتِيَّةٌ لِمَوَادَّ برُوتِينِيَّةٍ نَبَاتِيَّةٍ أَوْ حَيَوَانِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15100, 'نَسَمٌ', 'نسم', 'جامد', '', 'نسم', 'نسم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15101, 'نَسْنَاسٌ', 'نسناس', 'جامد', '', 'نسناس', 'نسنس', '', '', '', 'جمع تكسير', 'DnN', '', '', '"نَسَانِيسُ"', '', 'R', '', '', '', '', '', '', '"ج: نَسَانِيسُ. (حو). 1. : نَوْعٌ مِنَ القِرَدَةِ، صَغِيرُالْجِسْمِ، طَوِيلُ الذَّنَبِ. 2.""قَطَعَ اللَّهُ نَسْنَاسَهُ"" : أَيْ أَثَرَهُ. 3.""جُوعٌ نَسْنَاسٌ"" : أَيْ جُوعٌ شَدِيدٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15102, 'نَسَانِيسُ', 'نسانيس', 'جامد', '', 'نسانيس', 'نسنس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15103, 'مُنْشَأَةٌ', 'منشأة', 'جامد', 'نشأ', 'منشءة', 'منشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""عَامِلٌ فِي الْمُنْشَأَةِ الصِّنَاعِيَّةِ"" : مَعْمَلٌ صِنَاعِيٌّ خَاضِعٌ لِمُؤَسَّسَةٍ تُشْرِفُ عَلَى العَامِلِينَ وَالآلاَتِ. ""الْمُنْشَأَةُ الوَطَنِيَّةُ للِطِّبَاعَةِ وَالنَّشْرِ"". 2.""اِتَّسَعَ حَجْمُ الْمُنْشَآتِ العَسْكَرِيَّةِ"" : مَكَان، مَوْضِعُ إِقَامَةِ الْجَيْشِ وَالعَامِلِينَ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15104, 'مُنْشَآتٌ', 'منشآت', 'جامد', '', 'منشءءت', 'منشآت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15105, 'نَشَادِرُ', 'نشادر', 'جامد', '', 'نشادر', 'نشدر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '": غَازٌ لَهُ رَائِحَةٌ حَادَّةٌ، مُكَوَّنٌ مِنَ الأَزُوتِ وَالْهِيدْرُوجِين."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15106, 'نُشَّابٌ', 'نشاب', 'جامد', 'نشب', 'نشاب', 'نشب', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"نَشَاشِيبُ"', '', 'R', '', '', '', '', '', '', '". ""رَمَاهُ بِالنُّشَّابِ"": بِالنَّبْلِ. ""وَبِاللَّيْلِ أُوَاصِلُ الْحَرْبَ بِالقَوْسِ وَالسَّيْفِ وَالرُّمْحِ وَالنُّشَّابِ"". (الطيب صالح) ‏""تَرَامَوْا بِالنَّشَاشِيبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15107, 'نَشَاشِيبُ', 'نشاشيب', 'جامد', '', 'نشاشيب', 'نششب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15108, 'أُنْشودَةٌ', 'أنشودة', 'جامد', 'نشد', 'ءنشودة', 'نشدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَناشيدُ"', '', 'R', '', '', '', '', '', '', '". 1.""أُنْشودَةٌ وَطَنِيَّةٌ"": شِعْرٌ تُنْشِدُهُ الجَماعَةُ يُمَجِّدُ الشَّعْبَ والوَطَنَ. ""أَناشِيدُ وَطَنِيَّةٌ"" ""أَناشِيدُ دينِيَّةٌ"". 2.""يا لَها مِنْ أُنْشودَةٍ في وَصْفِ الطَّبيعَةِ"" : قَصيدَةٌ شِعْرِيَّةٌ مُغَنَّاةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15109, 'أَناشيدُ', 'أناشيد', 'جامد', '', 'ءناشيد', 'نشد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15110, 'نَشِيدٌ', 'نشيد', 'جامد', 'نشد', 'نشيد', 'نشد', '', '', '', 'مفرد', 'DnN', '', '', '"أَنَاشِيدُ"', '', 'R', '', '', '', '', '', '', '". 1.""النَّشِيدُ الْمَدْرَسِيُّ"" : قِطْعَةٌ شِعْرِيَّةٌ يُغَنِّيهَا أَطْفَالُ الْمَدَارِسِ جَمَاعِيّاً. ""وَفِي نِهَايَةِ السَّنَةِ تُقَامُ حَفْلَةُ أَنَاشِيدَ وَخُطَبٍ وَتَمْثِيلِيَّاتٍ"". (محمد برادة). 2.""النَّشِيدُ الوَطَنِيُّ"" : قِطْعَةٌ مُوسِيقِيَّةٌ مُغَنَّاةٌ في حُبِّ الوَطَنِ وَالتَّعَلُّقِ بِهِ. ""وَكَانَ النَّشِيدُ الوَطَنِيُّ يَمْلأُ الْمِذْيَاعَ مُنْهِياً بَرَامِجَ الْمَسَاءِ"". (أمل دنقل) l""نَشِيدٌ غِنَائِيٌّ""‏ ""أَنَاشِيدُ دِينِيَّةٌ"". 3.""نَشِيدُ الأَنْشَادِ"" : سِفْرٌ مِنْ أَسْفَارِ التَّوْرَاةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15111, 'أَنَاشِيدُ', 'أناشيد', 'جامد', '', 'ءناشيد', 'نشد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15112, 'مَنْشَرَةٌ', 'منشرة', 'جامد', 'نشر', 'منشرة', 'منشرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"مَنْشَرَةٌ-مَنْشَرَةٌ [ن ش ر]. ""مَنْشَرَةُ الْخَشَبِ"" : مَصْنَعُ نَشْرِ الْخَشَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15113, 'مَنْشَرٌ', 'منشر', 'جامد', 'نشر', 'منشر', 'منشر', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاشِرُ"', '', 'R', '', '', '', '', '', '', '". ""مَنْشَرُ الثِّيَابِ"" : مَوْضِعُ نَشْرِهَا وَنَشْفِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15114, 'مَنَاشِرُ', 'مناشر', 'جامد', '', 'مناشر', 'منشر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15115, 'نُشَارَةٌ', 'نشارة', 'جامد', 'نشر', 'نشارة', 'نشرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نُشَارَةٌ-نُشَارَةٌ [ن ش ر]. : مَا يَسْقُطُ مِنَ الْخَشَبِ وَغَيْرِهِ عِنْدَ النَّشْرِ. ""أَكْثَرُ مَهَارَةً فِي تَنْظِيفِ طَنَاجِرِ وَأَطْبَاقِ الأَلُومِنْيُومِ بِالنُّشَارَةِ"". (محمد برادة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15116, 'نُشْرَةٌ', 'نشرة', 'جامد', 'نشر', 'نشرة', 'نشرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"نُشَرٌ"', '', 'R', '', '', '', '', '', '', '". ""كَتَبَ لَهَا نُشْرَةً"" : تَعْوِيذَةً، رُقْيَةً يُعَالَجُ بِهَا الْمَرْضَى ظَنّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15117, 'نُشَرٌ', 'نشر', 'جامد', '', 'نشر', 'نشر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15118, 'أُنْشوطَةٌ', 'أنشوطة', 'جامد', 'نشط', 'ءنشوطة', 'نشطة', '', '', '', 'مفرد', 'DnN', '', '', '"أَناشيطُ"', '', 'R', '', '', '', '', '', '', '". 1.""لَمْ يَكُنْ مِنَ الصَّعْبِ حَلُّ هَذِهِ الأُنْشُوطَةِ"" : العُقْدَةِ الَّتي يَسْهُلُ انْحِلالُها. 2.""ما عَقْلُكَ بِأُنْشوطَةٍ"" : لَيْسَتْ مَوَدَّتُكَ واهِيَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15119, 'أَناشيطُ', 'أناشيط', 'جامد', '', 'ءناشيط', 'نشط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15120, 'نَشِيطَةٌ', 'نشيطة', 'جامد', 'نشط', 'نشيطة', 'نشطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"نَشَائِطُ"', '', '', '', '', '', '', '', '', '". ""اِسْتَوْلَى الغُزَاةُ عَلَى النَّشِيطَةِ"" : مَا يَغْنَمُونَهُ قَبْلَ وُصُولِهِمْ إِلَى أَرْضِ الْمَعْرَكَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15121, 'نَشَائِطُ', 'نشائط', 'جامد', '', 'نشاءط', 'نشط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15122, 'مِنْشَفَةٌ', 'منشفة', 'جامد', 'نشف', 'منشفة', 'منشفة', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاشِفُ"', '', 'R', '', '', '', '', '', '', '". ""مِنْشَفَةُ الوَجْهِ أَوِ اليَدِ"" : الفُوطَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15123, 'مَنَاشِفُ', 'مناشف', 'جامد', '', 'مناشف', 'منشف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15124, 'نُشَافَةٌ', 'نشافة', 'جامد', 'نشف', 'نشافة', 'نشفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"نُشَافَةٌ-نُشَافَةٌ [ن ش ف]. 1.""نُشَافَةُ الْمَاءِ"" : مَا نَشَفَ مِنْهُ. 2.""نُشَافَةُ اللَّبَنِ"" : رَغْوَةٌ تَعْلُوهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15125, 'نُشْفَةٌ', 'نشفة', 'جامد', 'نشف', 'نشفة', 'نشفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"نُشْفَةٌ-نُشْفَةٌ [ن ش ف]. 1.""نُشْفَةُ إِنَاءٍ"" : الشَّيْءُ القَلِيلُ الَّذِي يَبْقَى مِنْهُ. 2.""نُشْفَةُ اللَّبَنِ"" : رَغْوَتُهُ. 3.""نُشْفَةُ القِدْرِ"" : مَا أُخِذَ مِنْهُ بِمِلْعَقَةٍ وَهُوَ حَارٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15126, 'نَشُوقٌ', 'نشوق', 'جامد', 'نشق', 'نشوق', 'نشق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَشُوقٌ-نَشُوقٌ [ن ش ق]. ""نَشِقَ النَّشُوقُ"" : كُلُّ دَوَاءٍ يُصَبُّ فِي الأَنْفِ أَوْ يُشَمٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15127, 'نَشَمٌ', 'نشم', 'جامد', '', 'نشم', 'نشم', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"نَشَمٌ-نَشَمٌ، ةٌ (نب). : شَجَرٌ مِنْ فَصِيلَةِ الزَّيْزَفُونِيَّاتِ، لَهُ أَزْهَارٌ، أَوْرَاقُهُ عَرِيضَةٌ، يَكْثُرُ فِي الْجِبَالِ وَالْمَنَاطِقِ الْحَارَّةِ وَالْمُعْتَدِلَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15128, 'نَشَا', 'نشا', 'جامد', 'نشو', 'نشا', 'نش', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', 'N', 'O', 'O', 'O', '', '"نَشَا-نَشَا [ن ش و]. 1. : نَسِيمُ الرِّيحِ الطَّيِّبَةِ. 2. : الرَّائِحَةُ عَامَّةً. 3. : مَادَّةٌ تُسْتَخْرَجُ مِنَ الحِنْطَةِ إِذَا أُنْقِعَتْ وَصُفِّيَتْ وَجُفِّفَتْ. 4. : نَشَاءٌ، هِدْرَاتُ كَرْبُونٍ عَلَى شَكْلِ مَسْحُوقٍ أَبْيَضَ يَكْثُرُ فِي الْحُبُوبِ وَفِي النَّبَاتَاتِ الغَنِيَّةِ بِالسُّكَّرِ كَالبَطَاطَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15129, 'مَنْصِبٌ', 'منصب', 'جامد', 'نصب', 'منصب', 'منصب', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاصِبُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَنْصِبُ الْخِيَامِ"": مَكَانُ نَصْبِهَا. 2.""تَوَلَّى مَنْصِبَ مُدِيرِ الدِّيوَانِ"" : مَا يَتَوَلاَّهُ الْمُوَظَّفُ مِنْ وَظِيفَةٍ فِي جِهَازِ الدَّوْلَةِ. 3.""شَغَلَ مَنَاصِبَ مُهِمَّةً فِي حَيَاتِهِ"" : وَظَائِفَ ذَاتَ شَأْنٍ. ""مَنَاصِبُ رَفِيعَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15130, 'مَنَاصِبُ', 'مناصب', 'جامد', '', 'مناصب', 'منصب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15131, 'نِصَابٌ', 'نصاب', 'جامد', 'نصب', 'نصاب', 'نصب', '', '', '', 'مفرد', 'DnN', '', '', '"نُصُبٌ"', '', 'R', '', '', '', '', '', '', '". 1.""نِصَابُ السِّكِينِ"": مَقْبَضُهُ. 2.""عَادَ الْهُدُوءُ إِلَى نِصَابِهِ"" : عَادَ الْهُدُوءُ إِلَى مَجْرَاهُ. ""عَادَتِ الأُمُورُ لِتَسْتَقِرَّ فِي نِصَابِهَا"" : أي فِي مَجْرَاهَا الطَّبِيعِيِّ. ""أَعَادَ الأُمُورَ إِلَى نِصَابِهَا"". 3.""بِمُجَرَّدِ مَا اكْتَمَلَ النِّصَابُ بَدَأَتْ جَلَسَاتُ الْمُؤْتَمَرِ"" : هُوَ أَنْ يَكُونَ عَدَدُ الْحَاضِرِينَ فِي مُؤْتَمَرٍ أَوْ مَجْلِسٍ أَوِ اجْتِمَاعٍ يَتَجَاوَزُ نِصْفَ أَعْضَائِهِ حَسَبَ مَا يَنُصُّ عَلَيْهِ القَانُونُ لِتَكُونَ مُقَرَّرَاتُهُ قَانُونِيَّةً، وَهُوَ مَا يُعْرَفُ بِالنِّصَابِ القَانُونِيِّ. ""تَأَجَّلَ الاجْتِمَاعُ لِعَدَمِ اكْتِمَالِ النِّصَابِ القَانُونِيِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15132, 'نُصُبٌ', 'نصب', 'جامد', '', 'نصب', 'نصب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15133, 'نُصُبٌ', 'نصب', 'جامد', 'نصب', 'نصب', 'نصب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُصُبٌ-نُصُبٌ [ن ص ب]. المائدة آية 3وَمَا أَكَلَ السَّبُعُ إِلاَّ مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى النُّصُبِ (قرآن) : هِيَ حِجَارَةٌ حَوْلَ الكَعْبَةِ كَانَ العَرَبُ فِي الْجَاهِلِيَّةِ يَذْبَحُونَ عَلَيْهَا تَقَرُّباً للأَصْنَامِ فَحَرَّمَهَا اللَّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15134, 'نُصْبٌ', 'نصب', 'جامد', 'نصب', 'نصب', 'نصب', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْصَابٌ"', '', 'R', '', '', '', '', '', '', '". 1.""يَعِيشُ حَيَاةَ نُصْبٍ"" : شَرٍّ، بَلاَءٍ.ص آية 41 إِذْ نَادَى رَبَّهُ أَنِّي مَسَّنِي الشَّيْطَانُ بِنُصْبٍ وَعَذَابٍ (قرآن) : 2.""كَانُوا يَعْبُدُونَ الأَنْصَابَ"" : الأَصْنَامَ، أَيْ كُلُّ مَا عُبِدَ مِنْ دُونِ اللَّهِ. 3.""نُصْبٌ تَذْكَارِيٌّ"" : تِمْثَالٌ، لَوْحَةٌ تَذْكَارِيَّةٌ. 4.""وَضَعَ الأَمْرَ نُصْبَ عَيْنَيْهِ"" : وَضَعَهُ بِكُلِّ اهْتِمَامٍ وَانْتِبَاهٍ أَمَامَ عَيْنَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15135, 'أَنْصَابٌ', 'أنصاب', 'جامد', '', 'ءنصاب', 'نصب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15136, 'نَصِيبٌ', 'نصيب', 'جامد', 'نصب', 'نصيب', 'نصب', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْصِبَةٌ:أَنْصِبَاءُ:نُصُبٌ', '', 'R', '', '', '', '', '', '', '". 1.""حَصَلَ عَلَى نَصِيبِهِ فِي الإِرْثِ"" : حَصَلَ عَلَى حِصَّتِهِ مِنْهُ. 2.""هُوَ عَلَى نَصِيبٍ وَافِرٍ مِنَ العِلْمِ"" : عَلَى قِسْطٍ كَبِيرٍ مِنْهُ. 3.""هَذَا نَصِيبِي مِنَ الْحَيَاةِ"" : هَذَا حَظِّي. ""كَانَ مِنْ نَصِيبِهِ أَنْ..."" ‏""أَصَابَ مِنَ الدُّنْيَا حَظّاً جَسِيماً وَنَصِيباً عَظِيماً"". 4.""يَانَصِيبُ"" : يَا حَظُّ وَصَارَتِ الكَلِمَةُ تُطْلَقُ عَلَى لُعْبَةِ الْحَظِّ، وَهِيَ عِبَارَةٌ عَنْ أَوْرَاقٍ بِهَا أَرْقَامٌ يَشْتَرِيهَا النَّاسُ عَسَى أَنْ يَكُونَ أَحَدُ أَرْقَامِهَا مِنَ الأَرْقَامِ الفَائِزَةِ بَعْدَ إِجْرَاءِ عَمَلِيَّةِ السَّحْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15137, 'أَنْصِبَةٌ', 'أنصبة', 'جامد', '', 'ءنصبة', 'نصبة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
