INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15140, 'نَوَاصِبُ', 'نواصب', 'جامد', 'نصب', 'نواصب', 'نصب', '', '', '', 'مفرد', '', '', '', '"مفردنَاصِبَة"', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '". ""النَّوَاصِبُ فِي النَّحْوِ"" : هِيَ الْحُرُوفُ الَّتِي تَدْخُلُ عَلَى الْفِعْلِ الْمُضَارِعِ فَتَنْصِبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15141, 'نَاصِبَة', 'ناصبة', 'جامد', '', 'ناصبة', 'نصبة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15142, 'نَصِيحَةٌ', 'نصيحة', 'جامد', 'نصح', 'نصيحة', 'نصحة', '', '', '', 'مفرد', 'DnN', '', '', '"نَصَائِحُ"', '', '', '', '', '', '', '', '', '". ""عَمِلَ بِنَصِيحَتِهِ"" : قَوْلٌ فِيهِ دَعْوَةٌ سَدِيدَةٌ وَإِرْشَادٌ وَوَعْظٌ إِلَى صَلاَحٍ وَنَهْيٌ عَنْ فَسَادٍ. الدِّينُ النَّصِيحَةُ (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15143, 'نَصَائِحُ', 'نصائح', 'جامد', '', 'نصاءح', 'نصح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15144, 'أَنْصارٌ', 'أنصار', 'جامد', 'نصر', 'ءنصار', 'نصر', '', '', '', 'مفرد', '', '', '', '"مفردنَصِير"', '', 'Rp', '', '', '', '', '', '', '". 1.""خَرَجَ الأنْصارُ لِنُصْرَةِ النَّبِيِّ"" : أَهْلُ الْمَدينَةِ الَّذينَ نَصَرُوهُ على أَعْدائِهِ. التوبة آية 117 لَقَدْ تابَ اللَّهُ على النَّبِيِّ والْمُهاجِرينَ والأَنْصارِ (قرآن). 2.""كانَ أَنْصارُ الفَريقِ الرِّياضِيِّ يُصَفِّقونَ في حَماسٍ بالِغٍ"": الْمُؤيِّدونَ والْمُعْجَبونَ الَّذينَ يَقِفونَ لِصالِحِ فَريقِهِمْ. ""أَنْصارُ الحُكومَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15145, 'نَصِير', 'نصير', 'جامد', '', 'نصير', 'نصر', '', '', '', 'جمع تكسير', 'DnN', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15146, 'نَصَارَى', 'نصارى', 'جامد', 'نصر', 'نصارى', 'نصر', '', '', '', 'مفرد', '', '', '', '"مفردنَصْرَانِيٌّ"', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '". التوبة آية 30وَقَالَتِ النَّصَارَى الْمَسِيحُ ابْنُ اللَّهِ (قرآن) : مَنْ هُمْ عَلَى دِينِ السَّيِّدِ الْمَسِيحِ عَلَيْهِ السَّلاَمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15147, 'مَنَصَّةٌ', 'منصة', 'جامد', 'نصص', 'منصة', 'منصة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""صَعِدَ إِلَى الْمِنَصَّةِ"" : الْمَكَانُ الْمُرْتَفِعُ مِنْ خَشَبٍ أَمَامَ الْجُمْهُورِ. 2.""مِنَصَّةُ القَضَاءِ"" : مَكَانٌ مُخَصَّصٌ لِجُلُوسِ القُضَاةِ. 3.""مِنَصَّةُ العَرُوسِ"" : الكُرْسِيُّ الَّذِي تُرْفَعُ عَلَيْهِ العَرُوسُ. 4.""يُحَاوِلُ الوُصُولَ إِلَى مِنَصَّةِ الْحُكْمِ"" : السُّلْطَةُ. 5.""مِنَصَّةُ إِطْلاَقِ الصَّوَارِيخِ"" : تَلَّةٌ مُرْتَفِعَةٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15148, 'نُصَّةٌ', 'نصة', 'جامد', 'نصص', 'نصة', 'نصة', '', '', '', 'مفرد', 'DnN', '', '', '"نُصَصٌ:نِصَاصٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""نُصَّةُ الشَّعْرِ"": مَا أَقْبَلَ مِنْهُ عَلَى الْجَبْهَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15149, 'نُصَصٌ', 'نصص', 'جامد', '', 'نصص', 'نص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
