INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15151, 'مَنْصَفٌ', 'منصف', 'جامد', 'نصف', 'منصف', 'منصف', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاصِفُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""مَنْصَفُ الطَّرِيقِ"" : وَسَطُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15152, 'مَنَاصِفُ', 'مناصف', 'جامد', '', 'مناصف', 'منصف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
