INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15154, 'أَنْصَافٌ', 'أنصاف', 'جامد', '', 'ءنصاف', 'نصف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15155, 'نِصْفٌ', 'نصف', 'جامد', 'نصف', 'نصف', 'نصف', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْصَافٌ"', '', 'R', '', '', '', '', '', '', '". 1.""نِصْفُ التُّفَّاحَةِ"": أَحَدُ جُزْئَيْهَا الْمُتَسَاوِيَيْنِ. 2.""رَجُلٌ نِصْفٌ"" : مِنْ أَوَاسِطِ النَّاسِ. ""اِمْرَأَةٌ نِصْفٌ"" ""رِجَالٌ نِصْفٌ"". 3.""نِصْفُ كِيلُو"" : أَي 500 غرَام. 4.""نِصْفُ الْخَسَارَةِ وَلاَ الْخَسَارَةُ كُلُّهَا""(مثل) : أَيْ بَقَاءُ جُزْءٍ مُسَاوٍ لِلْخَسَارَةِ. ""التَّدْبِيرُ نِصْفُ الْمَعِيشَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15156, 'أَنْصَافٌ', 'أنصاف', 'جامد', '', 'ءنصاف', 'نصف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15157, 'نِصَالٌ', 'نصال', 'جامد', 'نصل', 'نصال', 'نصل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نِصَالٌ-نِصَالٌ [ن ص ل]. ن. نَصْلٌ.نَصْلٌ - ج: أَنْصُلٌ، نِصَالٌ. [ن ص ل]. (مص. نَصَلَ). ""نَصْلُ السِّكِّينِ"" : حَدِيدَةُ مِقْبَضِهِ.   ""نَصْلُ رُمْحٍ"" ""نَصْلُ سَهْمٍ"" ""كُسِّرَتِ النِّصَالُ عَلَى النِّصَالِ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15158, 'نَصْلَةٌ', 'نصلة', 'جامد', 'نصل', 'نصلة', 'نصلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"نَصْلَةٌ-نَصْلَةٌ [ن ص ل]. : النَّصْلُ وَهِيَ أَخَصُّ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15159, 'نَصِيلٌ', 'نصيل', 'جامد', 'نصل', 'نصيل', 'نصل', '', '', '', 'مفرد', 'DnN', '', '', '"نُصُلٌ"', '', 'R', '', '', '', '', '', '', '". 1.""فَوْقَ نَصِيلِهِ"" : أَعْلَى الرَّأْسِ. 2.""نَصِيلُ الإِنْسَانِ"" : مَفْصِلٌ، مَا بَيْنَ الرَّأْسِ وَالعُنُقِ تَحْتَ الْحَنَكِ. 3.""دَقَّ بِالنَّصِيلِ"" : حَجَرٌ يُدَقُّ بِهِ. 4.""حَفَرَ بِالنَّصِيلِ"" : بِالفَأْسِ. 5.""نَصِيلُ الْحَجَرِ"" : وَجْهُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15160, 'نُصُلٌ', 'نصل', 'جامد', '', 'نصل', 'نصل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15161, 'نَاصِيَةٌ', 'ناصية', 'جامد', 'نصو', 'ناصية', 'نصة', '', '', '', 'مفرد', 'DnN', '', '', '"نَوَاصٍ:النَّوَاصِي"', '', '', '', '', '', '', '', '', '". 1.""نَاصِيَةُ الرَّأْسِ"" : مُقَدَّمُهُ. الرحمن آية 41فَيُؤْخَذُ بِالنَّوَاصِي وَالأَقْدَامِ (قرآن). 2.""نَاصِيَةُ الشَّعْرِ"" : شَعْرُ مُقَدَّمِ الرَّأْسِ إِذَا طَالَ. ""نَاصِيَةُ الْجَوَادِ"". 3.""اِلْتَقَى بِهِ صِدْفَةً عِنْدَ نَاصِيَةِ الشَّارِعِ"" : رَأْسُ الشَّارِعِ عِنْدَ مُلْتَقَاهُ بِآخَرَ. 4.""اِمْتَلَكَ نَاصِيَةَ البَلاَغَةِ"" : اِمْتَلَكَ قُدْرَتَهَا. ""قَبَضَ عَلَى نَاصِيَةِ قَضَايَاهُ"". 5.""هُوَ نَاصِيَةُ قَوْمِهِ"" : شَرِيفُهُمْ وَالْمُتَقَدِّمُ عَلَيْهِمْ. ""هُوَ ذُؤَابَةُ قَوْمِهِ وَنَاصِيَةُ عَشِـيرَتِهِ"" ""نَوَاصِي النَّاسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15162, 'نَوَاصِي', 'نواصي', 'جامد', '', 'نواصي', 'نص', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15163, 'مِنْضَحَةٌ', 'منضحة', 'جامد', 'نضح', 'منضحة', 'منضحة', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاضِحُ"', '', 'R', '', '', '', '', '', '', '". ""مِنْضَحَةُ الْحَمَّامِ"" : مِرَشَّتُهُ، كُلُّ آلَةٍ يُنْضَحُ، يُرَشُّ بِهَا الْمَاءُ."', '');
