INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15165, 'مِنْضَدَةٌ', 'منضدة', 'جامد', 'نضد', 'منضدة', 'منضدة', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاضِدُ"', '', 'R', '', '', '', '', '', '', '". ""وَضَعَ الكَأْسَ عَلَى الْمِنْضَدَةِ"" : طَاوِلَةٌ صَغِيرَةٌ مِنْ ثَلاَثِ قَوَائِمَ أَوْ أَرْبَعَ تُوضَعُ عَلَيْهَا الأَشْيَاءُ. ""مِنْضَدَةُ النَّجَّارِ"" ""مِنْضَدَةُ الزِّينَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15166, 'مَنَاضِدُ', 'مناضد', 'جامد', '', 'مناضد', 'منضد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15167, 'نُضَادَةٌ', 'نضادة', 'جامد', 'نضد', 'نضادة', 'نضدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', 'R', '', '', '', '', '', '', '". 1.""نُضَادَةُ الصُّحُونِ"" : رَفٌّ مُقَسَّمٌ إِلَى أَجْزَاءٍ تُنَضَّدُ فِيهِ الصُّحُونُ. 2.: جِهَازٌ يُحَوِّلُ الطَّاقَةَ بِتَفَاعُلٍ كِيمِيَائِيٍّ إِلَى تَيَّارٍ كَهْرَبَائِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15168, 'نَضَدٌ', 'نضد', 'جامد', 'نضد', 'نضد', 'نضد', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْضَادٌ"', '', 'R', '', '', '', '', '', '', '". 1.""نَضَدُ الْمَتَاعِ"" : مَا نُضِدَ مِنْهُ. 2.""رَجُلٌ نَضَدٌ"" : شَرِيفٌ. 3.""أَنْضَادُ الرَّجُلِ"" : أَعْمَامُهُ وَأَخْوَالُهُ الْمُتَقَدِّمُونَ فِي الشَّرَفِ. 4.""لَهُ نَضَدٌ"" : شَرَفٌ."', '');
