INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15170, 'نُضَاضَةٌ', 'نضاضة', 'جامد', 'نضض', 'نضاضة', 'نضضة', '', '', '', 'مفرد', 'DnN', '', '', '"نُضَاضٌ:نَضَائِضُ"', '', 'R', '', '', '', '', '', '', '". 1.""نُضَاضَةُ الْمَاءِ"" : القَلِيلُ اليَسِيرُ مِنْهُ. ""مَا عِنْدِي مِنَ الْمَاءِ إِلاَّ نُضَاضَةٌ"". 2.""نُضَاضَةُ الرَّجُلِ"" : آخِرُ أَوْلاَدِهِ. ""هُوَ نُضَاضَةُ أَوْلاَدِهِ""."', '');
