INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15179, 'نِطْعٌ', 'نطع', 'جامد', 'نطع', 'نطع', 'نطع', '', '', '', 'مفرد', 'DnN', '', '', '"نُطُوعٌ:أَنْطَاعٌ:أَنْطُعٌ"', '', 'R', '', '', '', '', '', '', '". : مَا ظَهَرَ فِي الفَمِ مِنَ الغَارِ الأَعْلَى حَيْثُ مَوْقِعُ اللِّسَانِ مِنَ الْحَنَكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15180, 'نُطُوعٌ', 'نطوع', 'جامد', '', 'نطوع', 'نطع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
