INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15183, 'نُطَافَةٌ', 'نطافة', 'جامد', 'نطف', 'نطافة', 'نطفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"نُطَافَةٌ-نُطَافَةٌ [ن ط ف]. 1.""نُطَافَةُ الإِنَاءِ"" : الْمَاءُ القَلِيلُ الْمُتَبَقِّي. 2.""نُطَافَةُ الأُنْبُوبِ"" : مَا يَسِيلُ مِنْهُ قَطْرَةً قَطْرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15184, 'نُطْفَةٌ', 'نطفة', 'جامد', 'نطف', 'نطفة', 'نطفة', '', '', '', 'مفرد', 'DnN', '', '', '"نِطَافٌ:نُطَفٌ"', '', 'R', '', '', '', '', '', '', '". 1.""سَقَانِي نُطْفَةً عَذْبَةً"" : مَاءً صَافِياً. 2.""فِي الكَأْسِ نُطْفَةٌ مِنَ الْمَاءِ"" : القَلِيلُ مِنَ الْمَاءِ، قَطْرَةٌ. 3.النحل آية 4خَلَقَ الإِنْسَانَ مِنْ نُطْفَةٍ (قرآن) : أَيِ الْمَنِيُّ الَّذِي يَكُونُ مِنْهُ الْجَنِينُ فِي البَطْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15185, 'نِطَافٌ', 'نطاف', 'جامد', '', 'نطاف', 'نطف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15186, 'نُطَفٌ', 'نطف', 'جامد', '', 'نطف', 'نطف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15187, 'نَطَفَةٌ', 'نطفة', 'جامد', 'نطف', 'نطفة', 'نطفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نَطَفَةٌ-نَطَفَةٌ، نُطَفَةٌ [ن ط ف]. 1.""نَطَفَةُ الأُذُنِ"" : القُرْطُ. 2.""أَهْدَاهَا نَطَفَةً"" : لُؤْلُؤَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15188, 'مِنْطَقَةٌ', 'منطقة', 'جامد', 'نطق', 'منطقة', 'منطقة', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاطِقُ"', '', 'R', '', '', '', '', '', '', '". 1.""شَدَّتْ وَسَطَهَا بِمِنْطَقَةٍ"" : مَا يُشَدُّ بِهِ الوَسَطُ، أَيِ الحِزَامُ. 2.""مِنْطَقَةُ الْحَيِّ"" : مُقَاطَعَةٌ. 3.""مِنْطَقَةُ السُّهُولِ"" : جُزْءٌ مِنَ الأَرْضِ لَهُ صِفَاتٌ مُنَاخِيَّةٌ مُحَدَّدَةٌ. 4.""مِنْطَقَةٌ إِدَارِيَّةٌ"" : مَصْلَحَةٌ، دَائِرَةٌ. 5.""مِنْطَقَةٌ حُرَّةٌ"" : فَضَاءٌ حُرٌّ غَيْرُ خَاضِعٍ لِلرُّسُومِ الجُمْرُكِيَّةِ. 6.""مِنْطَقَةٌ صِنَاعِيَّةٌ"": مَكَانٌ مُخَصَّصٌ لِلْمَصَانِعِ وَالشَّرِكَاتِ الكُبْرَى. 7.""مِنْطَقَةُ نُفُوذٍ"" : مَجَالُ، نِطَاقُ. 8.""مِنْطَقَةٌ عَسْكَرِيَّةٌ"" : أَرْضٌ مُعَيَّنَةٌ خَاصَّةٌ بِالجَيْشِ وَالعَتَادِ العَسْكَرِيِّ. 9.""الْمِنْطَقَةُ الاسْتِوَائِيَّةُ"" (جغ) : بُقْعَتَانِ أَرْضِيَّتَانِ مُتَمَيِّزَتَانِ بِالاعْتِدَالِ. ""مِنْطَقَةٌ حَارَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15189, 'مَنَاطِقُ', 'مناطق', 'جامد', '', 'مناطق', 'منطق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15190, 'نِطَاقٌ', 'نطاق', 'جامد', 'نطق', 'نطاق', 'نطق', '', '', '', 'مفرد', 'DnN', '', '', '"نُطُقٌ"', '', 'R', '', '', '', '', '', '', '". 1.""شَدَّتِ الْمَرْأَةُ خِصْرَهَا بِنِطَاقٍ"" : قِطْعَةُ ثَوْبٍ مَشْقُوقَةٌ تَشُدُّ بِهَا الْمَرْأَةُ وَسَطَهَا فَتُرْسِلُ الأَعْلَى عَلَى الأَسْفَلِ وَتَجُرُّ الأَسْفَلَ عَلَى الأَرْضِ. 2.""شَدَّ وَسَطَهُ بِنِطَاقٍ"" : قِطْعَةٌ مِنْ ثَوْبٍ أَوْ جِلْدٍ وَمَا شَابَهَ ذَلِكَ يُشَدُّ بِهَا. 3.""عَلَى نِطَاقٍ وَاسِعٍ"" : مُتَّسِعِ الْمَدَى وَالأُفُقِ. ""هُجُومٌ وَاسِعُ النِّطَاقِ"" l ""عَلَى نِطَاقٍ ضَيِّقٍ"". 4.""يَتَصَرَّفُ فِي نِطَاقٍ القَانُونِ"" : فِي حُدُودِ القَانُونِ، فِي إِطَارِهِ. ""فِي نِطَاقِ الْمُمْكِنِ"" l ""هَذَا يَخْرُجُ عَنْ نِطَاقِ صَلاَحِيَّتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15191, 'نُطُقٌ', 'نطق', 'جامد', '', 'نطق', 'نطق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15192, 'مَنَاظِرُ', 'مناظر', 'جامد', 'نظر', 'مناظر', 'منظر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَنَاظِرُ-مَنَاظِرُ [ن ظ ر]. ن. مَنْظَرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15193, 'مِنْظَارٌ', 'منظار', 'جامد', 'نظر', 'منظار', 'منظر', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاظِيرُ"', '', 'R', '', '', '', '', '', '', '". 1. : آلَةٌ لِرُؤْيَةِ الأَجْسَامِ البَعِيدَةِ وَتَقْرِيبِهَا. 2.""مِنْظَارُ الأَعْمَاقِ"" : آلَةٌ مِجْهَرِيَّةٌ تُسْتَخْدَمُ فِي البِحَارِ لِرُؤْيَةِ الأَجْسَامِ تَحْتَ سَطْحِ الْمَاءِ. 3.""مِنْظَارٌ فَلَكِيٌّ"": آلَةٌ مِجْهَرِيَّةٌ لِرُؤْيَةِ النُّجُومِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15194, 'مَنَاظِيرُ', 'مناظير', 'جامد', '', 'مناظير', 'منظر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15195, 'نَظَّارَةٌ', 'نظارة', 'جامد', 'نظر', 'نظارة', 'نظرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"ات"', '', '', '', '', '', '', '', '', '". 1.""يَقْرَأُ بِالنَّظَّارَةِ "" : عَدَسَتَانِ زُجَاجِيَّتَانِمُرَكَّبَتَانِ فِي إِطَارٍ تُوضَعُ أَمَـامَ العَيْنَيْـنِ لِتَصْحِيحِ النَّظَرِ الضَّعِيفِ، وَهِيَ أَنْوَاعٌ: ""نَظَّارَةٌ شَمْسِيَّةٌ"" : لِحِمَايَةِ العَيْنَيْنِ مِـنْ أَشِعَّةِ الشَّمْسِ أَوْ مِنَ الأَتْرِبَةِ... ""نَظَّارَةٌ مُكَبِّرَةٌ"" : لِتَقْرِيبِ مَا هُوَ بَعِيدٌ أَوْ تَكْبِيرِ مَا هُوَ صَغِيرٌ. ""نَظَّارَةُ الرَّصْدِ الفَلَكِيِّ"" : تُسْتَعْمَلُ لِرَصْدِ الأَجْرَامِ وَالنُّجُومِ. 2.""إِطَارُ النَّظَّارَةِ"" : الإِطَارُ الَّذِي تُوضَعُ فِيهِ العَدَسَتَانِ الزُّجَاجِيَّتَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15196, 'نَظَّارَةٌ', 'نظارة', 'جامد', 'نظر', 'نظارة', 'نظرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"مُفْرَدنَاظِر"', '', 'R', '', '', '', '', '', '', '". ""أَيُّهَا النَّظَّارَةُ الكِرَامُ"": مَنْ يَنْظُرُونَ إِلَى الأَشْيَاءِ، وَالعِبَارَةُ تُسْتَخْدَمُ لِمُخَاطَبَةِ مُشَاهِدِي التَّلْفَزَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15197, 'نَظِرَةٌ', 'نظرة', 'جامد', 'نظر', 'نظرة', 'نظرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نَظِرَةٌ-نَظِرَةٌ [ن ظ ر]. 1.""يَقُومُ بِعَمَلِهِ بِنَظِرَةٍ"" : بِإِمْهَالٍ وَتَأَمُّلٍ. 2.البقرة آية 280 وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ (قرآن) : الِانْتِظَارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15198, 'مُنَظِّفَاتٌ', 'منظفات', 'جامد', 'نظف', 'منظفات', 'منظفت', '', '', '', 'مفرد', '', '', '', '"مفردمُنَظِّفَة"', '', '', '', '', '', '', '', '', '". ""مُنَظِّفَاتُ غُرْفَةِ الْحَمَّامِ"" : مَوَادُّ صِنَاعِيَّةٌ تُسْتَخْدَمُ لِإِزَالَةِ الأَوْسَاخِ كَالصَّابُونِ وَغَيْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15199, 'مُنَظِّفَة', 'منظفة', 'جامد', '', 'منظفة', 'منظفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15200, 'أُنْظومَةٌ', 'أنظومة', 'جامد', 'نظم', 'ءنظومة', 'نظمة', '', '', '', 'مفرد', 'DnN', '', '', '"أَناظيمُ"', '', 'R', '', '', '', '', '', '', '". 1.:كُلُّ خَيْطٍ نُظِمَ خَرَزاً. 2.""أُنْظومَةٌ فِكْرِيَّةٌ"" : أَي مَجْموعَةٌ مِنَ الأفْكارِ تَدورُ حَوْلَ مَوْضوعٍ مُحَدَّدٍ وَمُعَيَّنٍ. ""الأُنْظومَةُ الاشْتِراكِيَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15201, 'أَناظيمُ', 'أناظيم', 'جامد', '', 'ءناظيم', 'نظم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15202, 'مُنَظَّمَةٌ', 'منظمة', 'جامد', 'نظم', 'منظمة', 'منظمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". : هَيْئَةٌ مُكَوَّنَةٌ، لَهَا أَهْدَافٌ مُحَدَّدَةٌ وَقَانُونٌ يَرْسُمُ أَعْمَالَهَا، وَمَبَادِئُ تَعْمَلُ عَلَى تَحْقِيقِهَا فِي مَجَالِ اهْتِمَامِهَا: فِي السِّياَسَةِ أَوِ النَّقَابَةِ أَوِ الثَّقَافَةِ، إلخ. ""الْمُنَظَّمَةُ العَرَبِيَّةُ لِحُقُوقِ الإِنْسَانِ"" ""مُنَظَّمَةُ التَّحْرِيرِ الفِلِسْطِينِيَّةُ‏‏"" ""مُنَظَّمَةُ الوَحْدَةِ الإِفْرِيقِيَّةِ"" ""مُنَظَّمَةُ الأُمَمِ الْمُتَّحِدَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15203, 'نَاظِمَةٌ', 'ناظمة', 'جامد', 'نظم', 'ناظمة', 'نظمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نَاظِمَةٌ-نَاظِمَةٌ [ن ظ م]. ""الآلَةُ النَّاظِمَةُ"" : الآلَةُ الْحَاسِبَةُ، الْحَاسُوبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15204, 'نَعَامَةٌ', 'نعامة', 'جامد', '', 'نعامة', 'نعمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":نَعَامٌ:نَعَائِمُ"', '', 'R', '', '', '', '', '', '', '"ج: نَعَامٌ، نَعَامَاتٌ، نَعَائِمُ. (حو). 1. : طَائِرٌ مِنْ فَصِيلَةِالنَّعَامِيَّاتِ ضَخْمُ الْجِسْمِ، طَوِيلُ العُنُـقِ، ذُو أَجْنِحَـةٍ قَصِيرَةٍ، سَرِيعُ العَدْوِ، غَيْرُ قَادِرٍ عَلَى الطَّيَرَانِ. ""مِثْلُ النَّعَامَةِ لاَ طَيْرٌ وَلاَ جَمَلٌ"" (مثل) : مُتَقَلِّبٌ مُتَرَدِّدٌ. 2.""هُوَ ظِلُّ النَّعَامَةِ"": طَوِيلٌ. 3.""جَاءَ كَالنَّعَامَةِ"" : رَجَعَ خَائِباً. 4.""خَفَّتْ نَعَامَـةُ القَـوْمِ"" : ذَهَبُوا. 5.""نَضَرَتْ نَعَامَتُهُ"" : فَزِعَ مِنْ شَيْءٍ أَوْ مَاتَ. 6.""رَكِبَ جَنَاحَيِ النَّعَامَةِ"": جَدَّ فِي أَمْرِهِ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15205, 'نَعَامٌ', 'نعام', 'جامد', '', 'نعام', 'نعم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15206, 'نَعَائِمُ', 'نعائم', 'جامد', '', 'نعاءم', 'نعم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
