INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15213, 'نَاعُورَةٌ', 'ناعورة', 'جامد', 'نعر', 'ناعورة', 'نعرة', '', '', '', 'مفرد', 'DnN', '', '', '"نَوَاعِيرُ"', '', 'R', '', '', '', '', '', '', '". 1. : آلَةٌ لِرَفْعِ الْمَاءِ مِنَ الآبَارِ قِوَامُهَا دُولاَبٌ ذُو دِلاَءٍ يَدُورُ بِقُوَّةِ الْمَاءِ الدَّافِقَةِ، أَوْ جَرِّ الدَّوَابِّ لَهُ. 2.""النَّاعُورَةُ الْهَوَائِيَّةُ"" : الَّتِي تَشْتَغِلُ بِقُوَّةِ الْهَوَاءِ."', '');
