INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15218, 'نُعَامَى', 'نعامى', 'جامد', 'نعم', 'نعامى', 'نعم', '', '', '', 'مفرد', 'Dy', '', '', '"نَعَائِمُ"', 'ممنوع من الصرف', 'R0', '', '', '', '', '', '', '". 1.""نُعَامَاكَ أَنْ تَفْعَلَ كَذَا"": أَيْ قُصَارَاكَ، غَايَةُ أَمْرِكَ أَوْ جُهْدِكَ. 2.""نُعَامَى عَيْنٍ"" : أَفْعَلُهُ إِكْرَاماً لِعَيْنِكَ. ""سَأَفْعَلُ ذَلِكَ نُعَامَى عَيْنٍ"". 3.""نُعَامَى الْجَنُوبِ"" : رِيحُهُ لِأَنَّهَا فِي الْجَزِيرَةِ الْعَرَبِيَّةِ أَنْدَى الرِّيَاح وَأَرْطَبُهَا."', '');
