INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15220, 'نَعْمَاءُ', 'نعماء', 'جامد', 'نعم', 'نعماء', 'نعم', '', '', '', 'مفرد', '', '', '', '"أَنْعُمٌ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""صَدِيقٌ فِي النَّعْمَاءِ وَالبَأْسَاءِ"" : فِي السَّرَّاءِ. 2.""يَعِيشُ فِي يُسْرٍ وَنَعْمَاءَ"" : فِي غِنـىً لِكَثْرَةِ مَالِهِ."', '');
