INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15223, 'نُعْمٌ', 'نعم', 'جامد', 'نعم', 'نعم', 'نعم', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْعُمٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هُوَ فِي نُعْمٍ"" : فِي عَيْشٍ رَغْدٍ. 2.""يَوْمٌ نُعْمٌ"" : رَغْدٌ، طَيِّبُ الْعَيْشِ. 3.""سَأَفْعَلُ ذَلِكَ نُعْمَ عَيْنٍ"" : أَيْ إِنْعَاماً لِعَيْنِكَ وَإِكْرَاماً."', '');
