INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15225, 'نُعْمَى', 'نعمى', 'جامد', 'نعم', 'نعمى', 'نعم', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"نُعْمَى-نُعْمَى [ن ع م]. 1.""هُوَ فِي نُعْمَى"" : فِي عَيْشٍ رَغْدٍ وَسَعَةٍ. 2.""يُقَدِّمُ النُّعْمَى فِي كُلِّ آنٍ"" : الْمَعْرُوفَ، الإِحْسَانَ. 3.""سَأَفْعَلُ ذَلِكَ نُعْمَى عَيْنٍ"" : أَيْ إِنْعَاماً لِعَيْنِكَ وَإِكْرَاماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15226, 'نُعْمَى', 'نعمى', 'جامد', 'نعم', 'نعمى', 'نعم', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"نُعْمَى-نُعْمَى [ن ع م]. ""مَالُهُ كَثِيرٌ يَعِيشُ فِي نُعْمَى"" : فِي سَعَةِ عَيْشٍ وَرَغَدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15227, 'نَعْنَاعٌ', 'نعناع', 'جامد', 'نعنع', 'نعناع', 'نعنع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"(نب). : نَبَاتٌ مِنْ فَصِيلَةِالشَّفَوِيَّاتِ، أَوْرَاقُهُ عِطْرِيَّةٌ، تُسْتَعْمَلُ فِي الطِّبِّ وَفِي بَعْضِ الْمَأْكُولاَتِ، يُحَضَّرُ بِهِ الشَّايُ. ""أَيْ بِالنَّعْنَاعِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15228, 'نَعْنَعٌ', 'نعنع', 'جامد', 'نعنع', 'نعنع', 'نعنع', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نَعْنَعٌ-نَعْنَعٌ، ةٌ [ن ع ن ع]. ن. نَعْنَاعٌ. "', '');
