INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15241, 'نُفَّاخَةٌ', 'نفاخة', 'جامد', 'نفخ', 'نفاخة', 'نفخة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.: الفُقَاعَةُ الَّتِي تَطْفُو فَوْقَ الْمَاءِ. 2.""طَارَتِ النُّفَّاخَةُ"" : لُعْبَةٌ مَطَّاطِيَّةٌ لِلأَطْفَالِ يَنْفُخُونَ فِيهَا فَتُنْفَخُ كُرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15242, 'نُفَاخٌ', 'نفاخ', 'جامد', 'نفخ', 'نفاخ', 'نفخ', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُفَاخٌ-نُفَاخٌ [ن ف خ]. ""نُفَاخُ الْحَنَكِ"" : وَرَمٌ نَاتِجٌ عَنْ دَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15243, 'نَافِذَةٌ', 'نافذة', 'جامد', 'نفد', 'نافذة', 'نفذة', '', '', '', 'مفرد', 'DnN', '', '', '"نَوَافِذُ"', '', 'R', '', '', '', '', '', '', '". ""نَافِذَةُ البَيْتِ"" : فَتْحَةٌ فِي الْحَائِطِ يَنْفُذُ مِنْهَا الْهَوَاءُ إِلَى البَيْتِ، شُرْفَةٌ. ""أَشَارَ إِلَى النَّافِذَةِ فَإِذَا النَّهَارُ يَدْخُلُ مِنْهَا مُتَلَصِّصاً"". (توفيق الحكيم)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15244, 'نَوَافِذُ', 'نوافذ', 'جامد', '', 'نوافذ', 'نفذ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15245, 'مَنْفَذٌ', 'منفذ', 'جامد', 'نفذ', 'منفذ', 'منفذ', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَافِذُ"', '', 'R', '', '', '', '', '', '', '". ""وَجَدَ مَنْفَذاً"" : مَخْرَجاً. ""سَدَّ عَلَيْهِ كُلَّ الْمَنَافِذِ""."', '');
