INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15247, 'نَفَذٌ', 'نفذ', 'جامد', 'نفذ', 'نفذ', 'نفذ', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْفَاذٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1. ""قَرَّرَ نَفَذَ الأَمْرِ"" : إِمْضَاءهُ، إِبْرَامَهُ. 2.""قَامَ بِنَفَذِ الْكِتَابِ"" : بِإِنْفَاذِ مَا فِيهِ. 3.""وَجَدَ نَفَذاً لِمُشْكِلَتِهِ"" : مَخْرَجاً. 4.""طَعْنَةٌ لَهَا نَفَذٌ"" : أَيْ نَافِذَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15248, 'أَنْفَاذٌ', 'أنفاذ', 'جامد', '', 'ءنفاذ', 'نفذ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
