INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15255, 'مَنْفَضَةٌ', 'منفضة', 'جامد', 'نفض', 'منفضة', 'منفضة', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَافِضُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَنْفَضَةُ السَّجَائِرِ"": وِعَاءٌ مِنْ مَعْدِنٍ أو طِينٍ ونَحْوِهِ تُنْفَضُ فِيهِ السَّجَائِرُ وَتُوضَعُ فِيهِ أَعْقَابُهَا. 2.""مَنْفَضَةُ الغُبَارِ"": أَدَاةٌ مِنْ رِيشٍ ونَحْوِهِ تُنْفَضُ بِهَا البُسُطُ وأَثَاثُ الْمَنْزِلِ لإِزَالَةِ مَا عَلَيْهَا مِنْ غُبَارٍ."', '');
