INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15257, 'نُفَاضٌ', 'نفاض', 'جامد', 'نفض', 'نفاض', 'نفض', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"نُفُضٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""نُفَاضُ السَّجَّادَةِ"": مَا يَسْقُطُ مِنْهَا عِنْدَ نَفْضِهَا."', '');
