INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15295, 'نُقَرَةٌ', 'نقرة', 'جامد', 'نقر', 'نقرة', 'نقرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"نُقَرَةٌ-نُقَرَةٌ [ن ق ر]. ""حَيَوَانٌ مُصَابٌ بِالنُّقَرَةِ"" : دَاءٌ يُصِيبُ الغَنَمَ وَالبَقَرَ فِي حَوَافِرِهَا وَفِي أَفْخَاذِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15296, 'نُقْرَةٌ', 'نقرة', 'جامد', 'نقر', 'نقرة', 'نقرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نُقْرَةٌ-نُقْرَةٌ [ن ق ر]. 1."" نُقْرَةُ العَيْنِ"" : حُفْرَتُهَا. 2. ""فِي الْبَابِ نُقْرَةٌ لِلْعَيْنِ"" : ثُقْبٌ. 3. ""نُقْرَةُ الطَّائِرِ"" : مَبِيضُهَا. 4.""نُقْرَةُ الْقَفَا"" : حُفْرَةٌ فِي آخِرِ الدِّمَاغِ. 5.""نُقْرَةُ الفِضَّةِ أَوِ الذَّهَبِ"" : القِطْعَةُ الْمُذَابَةُ مِنْهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15297, 'نَقِيرَةٌ', 'نقيرة', 'جامد', 'نقر', 'نقيرة', 'نقرة', '', '', '', 'مفرد', 'DnN', '', '', '"نَقَائِرُ"', '', '', '', '', '', '', '', '', '". ""اِجْتَازَ النَّهْرَ فَوْقَ النَّقِيرَةِ"" : سَفِينَةٌ صَغِيرَةٌ."', '');
