INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15302, 'أَنْقَاسٌ', 'أنقاس', 'جامد', '', 'ءنقاس', 'نقس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15303, 'نِقَاشَةٌ', 'نقاشة', 'جامد', 'نقش', 'نقاشة', 'نقشة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نِقَاشَةٌ-نِقَاشَةٌ [ن ق ش]. : حِرْفَةُ النَّقَّاشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15304, 'مُنَاقَصَةٌ', 'مناقصة', 'جامد', 'نقص', 'مناقصة', 'منقصة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""أَعْلَنَتِ الوِزَارَةُ عَنْ مُنَاقَصَةٍ لِمُسْتَلْزَمَاتِ الْمَكَاتِبِ"" : عَرْضٌ لِلْمُزَايَدَةِ يُقَدَّمٌ لِلْعُمُومِ (لِلشَّرِكَاتِ) عَلَى أَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15305, 'نَقِيصَةٌ', 'نقيصة', 'جامد', 'نقص', 'نقيصة', 'نقصة', '', '', '', 'مفرد', 'DnN', '', '', '"نَقَائِصُ"', '', '', '', '', '', '', '', '', '". 1.""تَجَنَّبْ نَقِيصَةَ الْكَذِبِ"" : خَصْلَتَهُ، وَكُلَّ خَصْلَةٍ دَنِيئَةٍ. 2.""كَثُرَتْ نَقَائِصُهُ"" : عُيُوبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15306, 'نَقَائِصُ', 'نقائص', 'جامد', '', 'نقاءص', 'نقص', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15307, 'نَقْضٌ', 'نقض', 'جامد', 'نقض', 'نقض', 'نقض', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْقَاضٌ:نُقُوضٌ"', '', 'R', '', '', '', '', '', '', '". : مَا انْتَقَضَ وَتَهَدَّمَ مِنَ الْبِنَاءِ. ""بَعْدَ كَارِثَةِ الزِّلْزَالِ تَحَوَّلَتِ الْمَدِينَةُ إِلَى أَنْقَاضٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15308, 'أَنْقَاضٌ', 'أنقاض', 'جامد', '', 'ءنقاض', 'نقض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
