INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15310, 'نُقْطَةٌ', 'نقطة', 'جامد', 'نقط', 'نقطة', 'نقطة', '', '', '', 'مفرد', 'DnN', '', '', '"نُقَطٌ:نِقَاطٌ"', '', 'R', '', '', '', '', '', '', '". 1.""نُقْطَةُ حَرْفِ الْبَاءِ أَوِ الذَّالِ أَوِ الْجِيمِ"" : قَطْرَةٌ مِنْ حِبْرٍ، وَهَذِهِ عَلاَمَتُهَا (.) تُوضَعُ فَوْقَ بَعْضِ الْحُرُوفِ أَوْ تَحْتهَا، أَوْ عِنْدَ نِهَايَةِ الْجُمْلَةِ، أَوْ بَيْنَ الْجُمَلِ. 2.""نُقْطَةُ دَمٍ"" : قَطْرَةُ دَمٍ. 3.""النُّقْطَةُ فِي الْهَنْدَسَةِ"" : وَهِيَ الْعَلاَمَةُ الَّتِي لَهَا وَضْعٌ لَكِنْ لاَطُولَ لَهَا وَلاَ عَرْضَ وَلاَ عُمْقَ. 4.""نُقْطَةُ الدَّائِرَةِ"" ¤ : مَرْكَزُهَا. 5.""نُقْطَةُ الِاتِّصَالِ"" (هن) : مَكَانُ الِاتِّصَالِ. 6.""نُقْطَةُ الِارْتِكَازِ"" : أَيْ قَاعِدَةٌ لِلْعَمَلِ، الْقَاعِدَةُ الَّتِي يُرْتَكَزُ عَلَيْهَا عِنْدَ رَفْعِ الثِّقْلِ. 7.""نُقْطَةٌ أَسَاسِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15311, 'نُقَطٌ', 'نقط', 'جامد', '', 'نقط', 'نقط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
