INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15313, 'نُقُوطٌ', 'نقوط', 'جامد', 'نقط', 'نقوط', 'نقط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُقُوطٌ-نُقُوطٌ [ن ق ط]. ""سُرَّتِ الْعَرُوسُ بِنُقُوطِهَا"" : مَا يُهْدَى إِلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15314, 'مِنْقَعَةٌ', 'منقعة', 'جامد', 'نقع', 'منقعة', 'منقعة', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاقِعُ"', '', 'R', '', '', '', '', '', '', '". ن. المِنْقَعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15315, 'مَنَاقِعُ', 'مناقع', 'جامد', '', 'مناقع', 'منقع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15316, 'مِنْقَعٌ', 'منقع', 'جامد', 'نقع', 'منقع', 'منقع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِنْقَعٌ-مِنْقَعٌ [ن ق ع]. : الإِنَاءُ الَّذِي يُنْقَعُ فِيهِ التَّمْرُ أو الزَّبِيبُ ونَحْوُهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15317, 'نُقَاعٌ', 'نقاع', 'جامد', 'نقع', 'نقاع', 'نقع', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"أَنْقِعَةٌ"', '', 'R', '', '', '', '', '', '', '". 1. إِنَاءٌ يُنْقَعُ فِيهِ الشَّيْءُ. 2. ""نُقَاعَةٌ"" : مَا نُقِعَ مِنْ ثَمَرٍ أَوْ زَبِيبٍ أَوْ غَيْرِهِمَا. 3.""نُقَاعَةُ خَلٍّ"" : مَاءٌ مَمْزُوجٌ بِالْخَلِّ وَالزَّيْتِ وَالتَّوَابِلِ لاِدِّخَارِ اللَّحْمِ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15318, 'أَنْقِعَةٌ', 'أنقعة', 'جامد', '', 'ءنقعة', 'نقعة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15319, 'نَقُوعٌ', 'نقوع', 'جامد', 'نقع', 'نقوع', 'نقع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَقُوعٌ-نَقُوعٌ [ن ق ع]. : مَاءٌ عَذْبٌ بَارِدٌ. 1. : شَرَابٌ يُنْقَعُ فِيهِ الزَّبِيبُ أَوْ غَيْرُهُ ثُمَّ يُصَفَّى وَيُشْرَبُ. 2. : شَرَابٌ تُنْقَعُ فِيهِ الْفَوَاكِهُ وَيُشْرَبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15320, 'نَقِيعَةٌ', 'نقيعة', 'جامد', 'نقع', 'نقيعة', 'نقعة', '', '', '', 'مفرد', 'DnN', '', '', '"نَقَائِعُ"', '', '', '', '', '', '', '', '', '". 1.""قَدَّمَ لَهُ نَقِيعَةً بَعْدَ وُصُولِهِ"" : مَا يُقَدَّمُ لِلْقَادِمِ مِنَ السَّفَرِ. 2.""هَيَّأَ النَّقِيعَةَ"" : مَا يُذْبَحُ لِلضِّيَافَةِ أَوْ طَعَامُ الرَّجُلِ لَيْلَةَ عُرْسِهِ. "', '');
