INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15326, 'مِنْقَلٌ', 'منقل', 'جامد', 'نقل', 'منقل', 'منقل', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاقِلُ"', '', 'R', '', '', '', '', '', '', '". 1. : آلَةٌ لِقِيَاسِ الزَّوَايَا فِي الرَّسْمِ. 2. : آلَةٌ لِنَقْلِ الأَحْجَارِ والأَتْرِبَةِ وغَيْرِهَا يَسْتَخْدِمُهَا عُمَّالُ البِنَاءِ. 3.""اِنْتَقَلَ مِنْقَلاً"" : حِذَاءً خَفِيفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15327, 'مَنَاقِلُ', 'مناقل', 'جامد', '', 'مناقل', 'منقل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
