INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15345, 'مَنْكِبٌ', 'منكب', 'جامد', 'نكب', 'منكب', 'منكب', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاكِبُمثنىمَنْكِبَانِ"', '', 'R', '', '', '', '', '', '', '". 1.""طَوِيلُ القَامَةِ عَرِيضُ الْمَنْكِبَيْنِ"" : مُجْتَمَعُ رَأْسِ الكَتِفِ. 2.""مَنْكِبُ الطَّرِيقِ"" : جَانِبُهَا، الْمَوْضِعُ الْمُرْتَفِعُ مِنْهَا، نَاحِيَتُهَا.الملك آية 15 هُوَ الَّذِي جَعَلَ لَكُم"', '');
