INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15347, 'نَكْرَاءُ', 'نكراء', 'جامد', 'نكر', 'نكراء', 'نكر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"نَكْرَاءُ-نَكْرَاءُ [ن ك ر]. 1.""قَامَ بِفَعْلَةٍ نَكْرَاءَ"" : بِفَعْلَةٍ مُنْكَرَةٍ. 2.""اِمْرَأَةٌ نَكْرَاءُ"" : دَاهِيَةٌ، عَاقِلَةٌ. 3.""أَصَابَتْهُمْ مِنَ الدَّهْرِ نَكْـرَاءُ"" : شِدَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15348, 'نُكْرَانٌ', 'نكران', 'جامد', 'نكر', 'نكران', 'نكرن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُكْرَانٌ-نُكْرَانٌ [ن ك ر]. 1.""نُكْرَانُ الْجَمِيلِ"" : جُحُودُهُ، الْكُفْرُ بِالنِّعْمَةِ. ""مَا فَائِدَةُ النُّكْرَانِ وَالْحَقِيقَةُ وَاضِحَةٌ"". 2.""نُكْرَانُ الذَّاتِ"" : اِجْتِنَابُ الأَثَرَةِ، التَّضْحِيَةُ فِي سَبِيلِ الْغَيْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15349, 'مِنْكَاشٌ', 'منكاش', 'جامد', 'نكش', 'منكاش', 'منكش', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاكِشُ"', '', 'R', '', '', '', '', '', '', '". : مِعْزَقَةٌ، آلَةٌ مُكَوَّنَةٌ مِنْ حَدِيدَةٍ مُسَطَّحَ"', '');
