INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15354, 'نَكَالٌ', 'نكال', 'جامد', 'نكل', 'نكال', 'نكل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَكَالٌ - [ن ك ل].المائدة آية 38جَزَاءً بِمَا كَسَبَ نَكَالاً مِنَ اللَّهِ (قرآن) : أَيْ عِقَاباً، نَازِلَةً. "', '');
