INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15386, 'نَهَارٌ', 'نهار', 'جامد', 'نهر', 'نهار', 'نهر', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْهُرٌ:نُهُرٌ"', '', 'R', '', '', '', '', '', '', '". 1.""طَلَعَ النَّهَارُ"" : ضِيَاءُ بِدَايَةِ اليَوْم، أَيْ مِنْ طُلُوعِ الْفَجْرِ إِلَى غُرُوبِ الشَّمْسِ. 2. ""يَشْتَغِلُ لَيْلَ نَهَارَ"" : دُونَ انْقِ"', '');
