INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15396, 'نُهْيَةٌ', 'نهية', 'جامد', 'نهي', 'نهية', 'نهة', '', '', '', 'مفرد', 'DnN', '', '', '"نُهًى"', '', '', '', '', '', '', '', '', '". 1.""نُهْيَةُ رَغْبَتِهِ"" : غَايَتُهَا، وَآخِرُهَا. 2.""نُهْيَةُ الإِنْسَانِ"" : عَق"', '');
