INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15401, 'نَوْءٌ', 'نوء', 'جامد', 'نوأ', 'نوء', 'ن', '', '', '', 'مفرد', 'Dz', '', '', '"أَنْوَاءٌ"', '', 'Rz', '', '', '', '', '', '', '". ن. أَنْوَاءٌ.النَّوْءُ : النَّجمُ إذا مال للغروب.-: المطر الشّديد/ فلانٌ نَوْؤه متخاذل، أي ضعيف النَّهْض. -: العطاء؛ هذا الثَّرِيُّ كثير النَّوْء ج أنْواءُ ونُوآنٌ.', '');
