INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15411, 'مَنَاحَةٌ', 'مناحة', 'جامد', 'نوح', 'مناحة', 'منحة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""أُقِيمَتْ لِلْمَيِّتِ مَنَاحَةٌ"": مَوْضِعُ النُّوَاحِ، أَيْ البُكَاءِ عَلَى الْمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15412, 'مُنَاخٌ', 'مناخ', 'جامد', 'نوخ', 'مناخ', 'منخ', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مُنَاخٌ-مُنَاخٌ [ن و خ]. 1.""مُنَاخُ البِلاَدِ مُنَاخٌ حَارٌّ"" : حَالَةُ الطَّقْسِ ومَا يَكُونُ عَلَيْهِ مِنْ حَرَارَةٍ أَوْ بُرُودَةٍ أو اعْتِدَالٍ، أي مَجْمُوعُ العَوَامِلِ الْجَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15413, 'تَنُّورٌ', 'تنور', 'جامد', 'نور', 'تنور', 'تنر', '', '', '', 'مفرد', 'DnN', '', '', '"تَنَانِيرُ"', '', 'R', '', '', '', '', '', '', '". 1. ""وَضَعَتِ الْمَرْأَةُ الخُبْزَ فِي التَّنُّورِ"" : تَجْوِيفٌ أُسْطُوَانِيٌّ شِبْهُ فُرْنٍ فِي الأَرْضِ يُخْبَزُ فِيهِ. ""أتَذْكُرِين تَنُّوَرَنَا الوَهَّاج "". (بدر شاكر السِّياب). 2.""تَمْلِكُ أغْلَبُ البُيُوتِ تَنَانِيرَ كَهْرَبَائِيَّةً"" : عُلَبٌ مُتَفاَوِتَةُ الأحْجَامِ مِنَ الْمَعْدِنِ لِطَهْي مُخْتَلِفِ الْمَأكُولاتِ. 3. هود آية 40 حَتَّى إذَا جَاءَ أمْرُنَا وَفَارَ التَّنُّورُ (قرآن) : تَجْوِيفٌ أرْضِيٌّ تَفُورُ مِنْهُ المِيَاهُ الحَارَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15414, 'تَنَانِيرُ', 'تنانير', 'جامد', '', 'تنانير', 'تننر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15415, 'مَنَارٌ', 'منار', 'جامد', 'نور', 'منار', 'منر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَنَاوِرُ:مَنَائِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""رَأَوْا مَنَاراً مِنْ بَعِيدٍ"" : مَوْضِعُ النُّورِ. 2.""اِسْتَبْشَرُوا بِأَوَّلِ مَنَارٍ رَأَوْهُ عَلَى الطَّرِيقِ"" : عَلَمُ قَائِمٌ يُجْعَلُ لِلاِهْتِدَاءِ بِهِ فِي الطُّرُقِ. 3.""مَنَارَةُ الخَيْمَةِ"" : شَمْعَةٌ ذَاتُ سِرَاجٍ. 4.""هَتَفَ رُكَّابُ السَّفِينَةِ لَمَّا شَاهَدُوا مَنَارَةَ الْمَرْفَإِ"" : بِنَاءٌ مُرْتَفِعٌ يُقَامُ فِي الْمَرْفَإِ، فِي أَعْلاَهُ نُورٌ تَهْتَدِي بِهِ السُّفُنُ. 5.""مَنَارَةُ الْمَسْجِدِ"" : الْمِئْذَنَةُ. 6.""مَنَارُ العِلْمِ"" : نُورُهُ، إِشْعَاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15416, 'مَنَاوِرُ', 'مناور', 'جامد', '', 'مناور', 'منر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15417, 'مَنَائِرُ', 'منائر', 'جامد', '', 'مناءر', 'منر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15418, 'نَوَّارَةٌ', 'نوارة', 'جامد', 'نور', 'نوارة', 'نرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نَوَّارَةٌ-نَوَّارَةٌ [ن و ر]. : مِصْبَاحٌ ضَوْئِيٌّ ضَخْمٌ يُسْتَخْدَمُ لِإِضَاءةِ الْمَلاَعِبِ الرِّيَاضِيَّةِ لَيْلاً، كَمَا أَنَّهُ يُسَهِّلُ رُؤْيَةَ الأَشْيَاءِ البَعِيدَةِ فِي الظُّلْمَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15419, 'نُوَّارَةٌ', 'نوارة', 'جامد', 'نور', 'نوارة', 'نرة', '', '', '', 'مفرد', 'DnN', '', '', '"نُوَّارٌ:نَوَاوِيرُ"', '', 'R', '', '', '', '', '', '', '". ""اِمْتَلأَ الْحَقْلُ بِالنُّوَّارِ"" : بِالزَّهْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15420, 'نُوَّارٌ', 'نوار', 'جامد', '', 'نوار', 'نر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15421, 'نَوَاوِيرُ', 'نواوير', 'جامد', '', 'نواوير', 'نر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15422, 'نَوَّارٌ', 'نوار', 'جامد', 'نور', 'نوار', 'نر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"نَوَّارٌ-نَوَّارٌ [ن و ر]. 1.""حَلَّ شَهْرُ النَّوَّارِ"" : شَهْرُ مَايو(أَيّار). 2. : يُطْلَقُ عَلَى شَهْرِ فَبْرَاير حَسَبَ اليَوْمِيَّةِ اللِّيبِيَّةِ. 3.""ضَوْءٌ نَوَّارٌ"" : شَدِيدُ النُّورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15423, 'نَوَرٌ', 'نور', 'جامد', 'نور', 'نور', 'نر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"نَوَرٌ-نَوَرٌ [ن و ر]. ""مِنْ أَهْلِ النَّوَرِ"" : مِنَ الغَجَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15424, 'نَوْرٌ', 'نور', 'جامد', 'نور', 'نور', 'نر', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْوَارٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""ظَهَرَ نَوْرُ اللَّيْمُونِ"" : زَهْرُهُ الأَبْيَضُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15425, 'أَنْوَارٌ', 'أنوار', 'جامد', '', 'ءنوار', 'نر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15426, 'نُورٌ', 'نور', 'جامد', 'نور', 'نور', 'نر', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْوَارٌ"', '', 'R', '', '', '', '', '', '', '". 1.""نُورُ الشَّمْسِ"" : ضَوْؤُهَا. 2.""شُعَاعُ الشَّمْسِ لاَ يَخْفَى وَنُورُ الْحَقِّ لاَ يَطْفَى"" : قُوَّتُهُ السَّاطِعَةُ. 3.""النُّورُ الكَهْرَبَائِيُّ"" : الضَّوْءُ الصِّنَاعِيُّ الَّذِي يُضِيءُ بِوَاسِطَةِ الْمَصَابِيحِ وَيُعِينُ عَلَى رُؤْيَةِ الأَشْيَاءِ. 4.""فَقَدَ نُورَ عَيْنَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15427, 'أَنْوَارٌ', 'أنوار', 'جامد', '', 'ءنوار', 'نر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15428, 'نَوْرَجٌ', 'نورج', 'جامد', 'نورج', 'نورج', 'نرج', '', '', '', 'مفرد', 'DnN', '', '', '"نَوَارِجُ"', '', 'R', '', '', '', '', '', '', '". 1. : سِكَّةُ، حَدِيدَةُ الْمِحْرَاثِ. 2. : مَا تُدَاسُ بِهِ سَنَابِلُ القَمْحِ مِنْ خَشَبٍ كَانَ أَوْ حَدِيدٍ لِفَصْلِ الْحَبِّ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15429, 'نَوَارِجُ', 'نوارج', 'جامد', '', 'نوارج', 'نرج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15430, 'نَوْرُوزٌ', 'نوروز', 'جامد', 'نورز', 'نوروز', 'نرز', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"نَوْرُوزٌ-نَوْرُوزٌ [ن و ر ز]. ""عِيدُ النَّوْرُوزِ"" : أَوَّلُ يَوْمٍ مِنْ أَيَّامِ السَّنَةِ الشَّمْسِيَّةِ عِنْدَ الفُرْسِ، وَهُوَ مَا يُوَافِقُ الْحَادِيَ وَالعِشْرِينَ مِنْ مَارس (آذار)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15431, 'نَيْرُوزٌ', 'نيروز', 'جامد', 'نورز', 'نيروز', 'نرز', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"نَيْرُوزٌ-نَيْرُوزٌ [ن و ر ز]. ن. نَوْرُوزٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15432, 'نَوْرَسٌ', 'نورس', 'جامد', '', 'نورس', 'نرس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَوْرَسٌ-نَوْرَسٌ (حو). : طَيْرٌ مَائِيٌّ مِنْ فَصِيلَةِ النَّوْرَسِيَّاتِ، رِيشُهُ رَمَادِيٌّفَاتِحٌ مِنْ أَعْلَى، وَأَبْيَضُ نَاصِعٌ مِنْ أَسْفَلَ. يُلاَحَظُ فِي أَكْثَرِ أَنْوَاعِهِ أَنَّ قِمَّةَ رَأْسِهِ تَسْوَدُّ فِي الصَّيْفِ، وَيَخْتَفِي سَوَادُها جُزْئِيّاً أَوْ كُلِّيّاً فِي الشِّتَاءِ، وَيُعْرَفُ بِزُمَّجِ الْمَاءِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15433, 'نَوْرَسِيَّاتٌ', 'نورسيات', 'جامد', '', 'نورسيات', 'نرست', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ مِنَ الطُّيُورِ الْمَائِيَّةِ، مِنْ أَجْنَاسِهَا النَّوْرَسُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15434, 'نَاسٌ', 'ناس', 'جامد', 'نوس', 'ناس', 'نس', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَاسٌ-نَاسٌ [ن و س]. : الرِّجَالُ عُمُوماً. ""أَيُّهَا النَّاسُ"" : أَيُّهَا الْخَلْقُ، أَيُّهَا الرِّجَالُ. ""غَايَةُ النَّاسِ وَحَاجَاتُهُمْ صَلاَحُ الْمَعَاشِ وَالْمَعَادِ"" ""رِضَا النَّاسِ غَايَةٌ لاَ تُدْرَكُ"" ""عَامِلِ النَّاسَ بِمَا تُحِبُّ أَنْ يُعَامِلُوكَ بِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15435, 'نُوَاسٌ', 'نواس', 'جامد', 'نوس', 'نواس', 'نس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"نُوَاسٌ-نُوَاسٌ [ن و س]. 1.""نُوَاسُ الْعَنْكَبُوتِ"" : شُعُّهُ، بَيْتُهُ، نَسِيجُهُ. 2.""نُوَاسُ الدُّخَانِ"" : مَا تَدَلَّى مِنْهُ مِنَ السَّقْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15436, 'نَوَّاسٌ', 'نواس', 'جامد', 'نوس', 'نواس', 'نس', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نَوَّاسٌ-نَوَّاسٌ، ةٌ [ن و س]. 1. : الْمُضْطَرِبُ الْمُسْتَرْخِي. 2.""تُضِيءُ نَوَّاسَةُ الْبَيْتِ مَا حَوْلَهَا"" : السِّرَاجُ، الْمِصْبَاحُ الضَّعِيفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15437, 'مَنَاصٌ', 'مناص', 'جامد', 'نوص', 'مناص', 'منص', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَنَاصٌ-مَنَاصٌ [ن و ص]. 1.""لاَ مَنَاصَ لَهُمْ مِنَ العِقَابِ"" : لاَ مَفَرَّ. ""لاَ مَنَاصَ مِنْ ذَلِكَ"" ""مَا لَهُ مِنْ مَنَاصٍ"". 2.ص آية 3 كَمْ أَهْلَكْنَا مِنْ قَبْلِهِمْ مِنْ قَرْيَةٍ فَنَادَوا وَلاَتَ حِينَ مَنَاصٍ (قرآن): أَيْ لاَ مَهْرَبَ، لاَ مَلْجَأَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15438, 'مَنَاطٌ', 'مناط', 'جامد', 'نوط', 'مناط', 'منط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"مَنَاطٌ-مَنَاطٌ [ن و ط]. 1.""مَنَاطُ السَّيْفِ"" : مَوْضِعُ التَّعْلِيقِ. 2.""هُوَ مَنَاطُ الثُّرَيَّا"" : شَرِيفٌ عَالِي الْمَنْزِلَةِ. 3. هُوَ مِنِّي مَنَاطُ الثُّرَيَّا"" : أَيْ شَدِيدُ البُعْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15439, 'نِيطَ', 'نيط', 'جامد', 'نوط', 'نيط', 'نط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'N', '', '"نِيطَ-نِيطَ [ن و ط]. 1. ""نِيطَ بِهِ الأَمْرُ"" : وُصِلَ بِهِ. 2. ""نِيطَ عَلَيْهِ الشَّيْءُ"" : عُلِّقَ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15440, 'نَوْطَةٌ', 'نوطة', 'جامد', 'نوط‎', 'نوطة', 'نطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""نَوْطَةُ الطَّائِرِ"" : حَوْصَلَتُهُ. 2.""بِهِ نَوْطَةٌ"" : وَرَمٌ فِي النَّحْرِ أَوِ الصَّدْرِ. 3.""فِي قَلْبِهِ نَوْطَةٌ"" : حِقْدٌ وَغِلٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15441, 'نَوْعٌ', 'نوع', 'جامد', 'نوع', 'نوع', 'نع', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْوَاعٌ"', '', 'R', '', '', '', '', '', '', '". 1.""النَّوْعُ البَشَرِيُّ"" : الجِنْسُ...، مَا يَدْخُلُ فِي وَحْدَةٍ لأَفْرَادِهَا صِفَاتٌ مُشْتَرَكَةٌ ثَابِتَةٌ وَمُتَمَيِّزَةٌ قَائِمَةٌ بِذَاتِهَا وَمُسْتَقِلَّةٌ عَنْ غَيْرِهَا. ""الأَنْوَاعُ الْحَيَوَانِيَّةُ"" ""الأَنْوَاعُ النَّبَاتِيَّةُ"". 2.""نَوْعُ العَمَلِ"" : صِنْفُهُ. ""أَنْوَاعُ الْمَأْكُولاَتِ"" ""أَنْوَاعُ السَّيَّارَاتِ"". 3.""هُوَ الأَوَّلُ مِنْ نَوْعِهِ"" : مِنْ طِرَازِهِ. 4.""تَعَدُّدُ الأَنْوَاعِ"" : تَعَدُّدُ الأَشْكَالِ. 5.""نَوْعاً وَكَمّاً"" : كَيْفاً وَكَمّاً. 6.""نَوْعاً مَّا"" : إِلَى حَدٍّ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15442, 'أَنْوَاعٌ', 'أنواع', 'جامد', '', 'ءنواع', 'نع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15443, 'نُوعٌ', 'نوع', 'جامد', 'نوع', 'نوع', 'نع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُوعٌ-نُوعٌ [ن و ع]. ""اِشْتَدَّ بِهِ النُّوعُ"" : العَطَشُ. ""رَمَاهُ اللهُ بِالْجُوعِ وَالنُّوعِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15444, 'نُوفَمبر', 'نوفمبر', 'جامد', '', 'نوفمبر', 'نفمبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ الْحَادِي عَشَرَ مِنَ الشُّهُورِ الغَرْبِيَّةِ عَدَدُ أَيَّامِهِ (30) يَوْماً. ن. تِشْرِين الثَّانِي."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15445, 'نُوقٌ', 'نوق', 'جامد', 'نوق', 'نوق', 'نق', '', '', '', 'مفرد', '', '', '', '"مفردنَاقَة"', '', 'R', '', '', '', '', '', '', '". : الإِنَاثُ مِنَ الإِبِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15446, 'نَاقَة', 'ناقة', 'جامد', '', 'ناقة', 'نقة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15447, 'مِنْوَالٌ', 'منوال', 'جامد', 'نول', 'منوال', 'منل', '', '', '', 'مفرد', 'DnN', '', '', '"مَنَاوِيلُ"', '', 'R', '', '', '', '', '', '', '". 1. : خَشَبَةُ الْحَائِكِ الَّتِي يُنْسَجُ وَيُلَفُّ عَلَيْهَا الثَّوْبُ وَقْتَ النَّسِيجِ. 2.""يَسِيرُ عَلَى المِنْوَالِ نَفْسِهِ"" : عَلَى النَّمَطِ نَفْسِهِ، النَّسَقِ نَفْسِهِ، الشَّكْلِ نَفْسِهِ. ""يَسِيرُ عَلَى مِنْوَالِهِ"" ""هُمْ عَلَى مِنْوَالٍ وَاحِدٍ"". 3.""مِنْوَالُكَ أَنْ تَفْعَلَ الْخَيْرَ"" : يَنْبَغِي لَكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15448, 'مَنَاوِيلُ', 'مناويل', 'جامد', '', 'مناويل', 'منل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15449, 'مَنَامٌ', 'منام', 'جامد', 'نوم', 'منام', 'منم', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""فِي مَنَامِهِ"" : فِي نَوْمِهِ، فِي مَوْضِعِ نَوْمِهِ، ""فِي مَنَامَتِهِ"". 2.""رَأَى مَنَاماً"" : أَيْ رَأَى حُلْماً.الصافات آية 102 يَا بُنَيَّ إِنِّي أَرَى فِي الْمَنَامِ أَنِّي أَذْبَحكَ فَانْظُرْ مَاذَا تَرَى (قرآن). 3.""اِرْتَدَى الْمَنَامَةَ"" : لِبَاسَ النَّوْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15450, 'نُوَمٌ', 'نوم', 'جامد', 'نوم', 'نوم', 'نم', '', '', '', 'مفرد', '', '', '', '"""رَجُلٌنُوَمٌ"""', '', 'R', '', '', '', '', '', '', '"نَوْمٌ-نَوْمٌ [ن و م] (مص. نَامَ). 1.""أَخَذَهُ النَّوْمُ"" : الإِغْفَاءُ، أَيِ الفَتْرَةُ الَّتِي يَسْتَلْقِي فِيهَا الكَائِنُ الْحَيُّ عَلَى الفِرَاشِ لِيَنَامَ وَيَغِيبَ فِيهَا وَعْيُهُ وَيَبْطُلَ عَمَلُ الْحَوَاسِّ. ""نَامَ نَوْماً عَمِيقاً"" ""غُرْفَةُ النَّوْمِ"". 2.""لِبَاسُ النَّوْمِ"" : الْمَنَامَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15451, 'نُونٌ', 'نون', 'جامد', 'نون', 'نون', 'نن', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', 'N', 'O', 'N', 'O', '', '". 1. ن. حَرْف النُّونِ. 2."" ذُو النُّونِ"" : لَقَبُ يُونُس وَلُقِّبَ بِذَلِكَ لأَنَّ النُّونَ (الحُوت) اِلْتَقَمَهُ ثُمَّ أَخْرَجَهُ مِنْ جَوْفِهِ.الأنبياء آية 87 وَذَا النُّونِ إِذْ ذَهَبَ مُغَاضِباً فَظَنَّ أَنْ لَنْ نَقْدِرَ عَلَيْهِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15452, 'نَوَاةٌ', 'نواة', 'جامد', 'نوي', 'نواة', 'نة', '', '', '', 'مفرد', 'DnN', '', '', '"نَوًى:نَوَيَاتٌ"', '', 'Rw', '', '', '', '', '', '', '". 1. ""نَوَاةُ الْمِشْمِشِ"": عَجَمَتُهَا، أَي الْجُزْءُ الصُّلْبُ بِدَاخِلِهَا.الأنعام آية 95 إِنَّ اللَّهَ فَالِقُ الْحَبِّ وَالنَّوَى (قرآن). 2.""أَوَّلُ الشَّجَرَةِ نَوَاةٌ"" : بَذْرَةٌ. ""زَرَعَ نَوَاةَ الْإِصْلَاحِ فِي الْمُجْتَمَعِ"". 3.""نَوَاةُ الذَّرَّةِ"": جُزْءُ الذَّرَّةِ الْجَوْهَرِيُّ تَدُورُ حَوْلَهُ الإِلِكِتْرُونَاتُ. 4.""عَبَّرَ عَنْ نَوَاتِهِ"" : عَنْ نِيَّتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15453, 'نَوًى', 'نوى', 'جامد', '', 'نوى', 'ن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15454, 'نَوَيَاتٌ', 'نويات', 'جامد', '', 'نويات', 'نت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15455, 'نَابٌ', 'ناب', 'جامد', 'نيب', 'ناب', 'نب', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْيَابٌ:نُيُوبٌ"', '', 'R', '', '', '', '', '', '', '". : السِّنُّ بِجَانِبِ الرُّبَاعِيَّةِ.1.""كَشَّرَ عَنْ أَنْيَابِهِ"" : أَبَانَ عَنْ أَسْنَانِهِ. 2.""عَضَّهُ الدَّهْرُ بِنَابِهِ"": كَانَ الدَّهْـرُ قَاسِيـاً عَلَيْهِ، أَيْ أَصَابَهُ بِشَرِّهِ. ""مِنْهُمْ مَنْ يُمَثِّلُ دَوْرَ الْمَاكِرِ ذِي النَّابِ الأَزْرَقِ الَّذِي يُقَابِلُكَ فَيَبْتَسِمُ لَكَ"". (أ. أمين) ""نَابُ الفِيلِ"" ""نَابُ الكَلْبِ"". 3.""نَابُ القَوْمِ"" : سَيِّدُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15456, 'أَنْيَابٌ', 'أنياب', 'جامد', '', 'ءنياب', 'نب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15457, 'نُيُوبٌ', 'نيوب', 'جامد', '', 'نيوب', 'نب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15458, 'نِيتْرَات', 'نيترات', 'جامد', '', 'نيترات', 'نترت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": مِلْحٌ يَحْصُلُ مِنْ تَأْلِيفِ الْحَامِضِ النِّتْرِيكِيِّ مَعَ أَحَدِ الأَجْسَامِ، وَهُوَ مِنَ الأَسْمِدَةِ الأَزُوتِيَّةِ كَثِيرَةِ الاسْتِعْمَالِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15459, 'نِيتْرُوغِلِيسِيرِين', 'نيتروغليسيرين', 'جامد', '', 'نيتروغليسيرين', 'نترغلسرن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"نِيتْرُوغِلِيسِيرِين-نِيتْرُوغِلِيسِيرِين : هُوَ مَائِعٌ زَيْتِيٌّ أَصْفَرُ يَنْفَجِرُ بِالاحْتِكَاكِ أَوْ تَحْتَ تَأْثِيرِ الْحَرَارَةِ، وَإِنْ دَخَلَ جِسْماً جَامِداً نَشَأَ عَنْهُ الدِّينَامِيت."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15460, 'نَيِّرٌ', 'نير', 'جامد', 'نير', 'نير', 'نر', '', '', '', 'مفرد', '', '', '', '"مثنىنيران-نيران"', '', 'R', '', '', '', '', '', '', '"نَيِّرَانِ-نَيِّرَانِ [ن ي ر]. ""ظَهَرَ النَّيِّرَانِ مَعاً"" : القَمَرُ وَالشَّمْسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15461, 'نِيرٌ', 'نير', 'جامد', 'نير', 'نير', 'نر', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْيَارٌ:نِيرَانٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""نِيرُ ثَوْبٍ"" : هُدْبُهُ، لُحْمَتُهُ. 2.""نِيرُ الطَّرِيقِ"" : جَانِبُهُ. 3.""نِيرُ الثَّوْرَيْنِ"" : الْخَشَبَةُ الْمُعْتَرِضَةُ فِي عُنُقَيِ الثَّوْرَيْنِ لِجَرِّ الْمِحْرَاثِ وَنَحْوِهِ. 4.""حَرْبٌ ذَاتُ نِيرَيْنِ"" : حَرْبٌ شَدِيدَةٌ. 5.""تَخَلَّصَ الشَّعْبُ مِنْ نِيرِ الاسْتِعْمَارِ"" : مِنْ قَيْدِهِ وَسَطْوَتِهِ وَظُلْمِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15462, 'أَنْيَارٌ', 'أنيار', 'جامد', '', 'ءنيار', 'نر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15463, 'نِيرَانٌ', 'نيران', 'جامد', '', 'نيران', 'نرن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15464, 'نَيِّرٌ', 'نير', 'جامد', 'نير', 'نير', 'نر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"نَيِّرٌ-نَيِّرٌ، ةٌ [ن ي ر]. 1.""مَكَانٌ نَيِّرٌ"" : مُضِيءٌ. 2.""عَقْلٌ نَيِّرٌ"" : عَقْلٌ مُنِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15465, 'نَيْسَانُ', 'نيسان', 'جامد', '', 'نيسان', 'نسن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', 'N', 'O', 'N', 'O', '', '": الشَّهْرُ الرَّابِعُ مِنَ السَّنَةِ الشَّمْسِيَّةِ، وَهُوَ مِنَ الشُّهُورِ السُّرْيَانِيَّةِ، عَدَدُ أَيَّامِهِ (30) يَوْماً، يَأْتِي بَعْدَ آذَار وَيَلِيهِ أَيَّار، وَيُسَمَّى أَيْضاً أَبْرِيل."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15466, 'نِيكُوتِين', 'نيكوتين', 'جامد', '', 'نيكوتين', 'نكتن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": مَادَّةٌ قَلَوِيَّةٌ شَدِيدَةُ الفَعَّالِيَّةِ تُسْتَخْرَجُ مِنَ التِّبْغِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15467, 'مَنَالٌ', 'منال', 'جامد', 'نيل', 'منال', 'منل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَنَالٌ-مَنَالٌ [ن ي ل]. 1.""بَعِيدُ الْمَنَالِ"" : مَا يَصْعُبُ الْحُصُولُ عَلَيْهِ عَكْسُ ""سَهْل الْمَنَالِ"". 2.""لاَ يَنَالُ مِنْهُ مَنَالاً"" : لاَ يُؤَثِّرُ عَلَيْهِ. 3.""نَالَهُ أَوْفَرَ مَنَالٍ"" : أَعْطَاهُ أَوْفَرَ العَطَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15468, 'نِيلٌ', 'نيل', 'جامد', 'نيل', 'نيل', 'نل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نِيلٌ-نِيلٌ [ن ي ل]. 1.(نب). : نَبَاتٌ مِنْ فَصِيلَةِ القَرْنِيَّاتِ، وَهُوَ أَزْرَقُ اللَّوْنِ، يُزْرَعُ فِي الْمَنَاطِقِ الْحَارَّةِ، مِنْهَا مَا هُوَ بَرِّيٌّ، وَمِنْهَا مَا هُوَ زِرَاعِيٌّ صِنَاعِيٌّ. تُسْتَخْرَجُ مِنْ أَوْرَاقِهِ مَادَّةٌ زَرْقَاءُ لِلصِّبَاغَةِ. 2. : صِبَاغٌ أَزْرَقُ يُسْتَخْرَجُ مِنْ نَبَاتِ النِّيلِ. 3.""نَهْرُ النِّيلِ"" : نَهْرٌ من أُنْهُرِ إِفْريقِيا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15469, 'نَيْلُوفَرٌ', 'نيلوفر', 'جامد', '', 'نيلوفر', 'نلفر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"نَيْلُوفَرٌ-نَيْلُوفَرٌ (نب). : نَبَاتٌ مَائِيٌّ مِنْ فَصِيلَةِ النَّيْلُوفَرِيَّاتِ، أَوْرَاقُهُ وَأَزْهَارُهُ مُسْتَطِيلَةُ الْمَقَايِيسِ طَافِيَةٌ، وَأَنْوَاعُهُ عَدِيدَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15470, 'نَيْلُوفَرِيَّاتٌ', 'نيلوفريات', 'جامد', '', 'نيلوفريات', 'نلفرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '": فَصِيلَةٌ نَبَاتِيَّةٌ مِنْ ذَوَاتِ الفِلْقَتَيْنِ، مِنْ أَجْنَاسِهَا النَّيْلُوفَرُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15471, 'نِيلُونٌ', 'نيلون', 'جامد', '', 'نيلون', 'نلن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"""ثَوْبٌ مِنَ النِّيلُون"" : نَسِيجٌ صِنَاعِيٌّ شَفَّافٌ يُسْتَخْرَجُ مِنَ النَّفْطِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15472, 'نِيُوتْرُون', 'نيوترون', 'جامد', '', 'نيوترون', 'نترن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": ذَرَّةٌ مُحَايِدَةٌ، وَهِيَ جِسْمٌ مُتَعَادِلٌ ذُو شِحْنَةٍ، تَكُونُ مَعَ برُوتُونَاتِ نَوَاةِ الذَّرَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15473, 'نِيُونٌ', 'نيون', 'جامد', '', 'نيون', 'نن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": عُنْصُرٌ غَازِيٌّ، يُسْتَعْمَلُ فِي الإِنَارَةِ الكَهْرَبَائِيَّةِ دَاخِلَ أَنَابِيبَ مُضِيئَةٍ لِلْإِعْلاَنَاتِ وَالإِشَارَاتِ الضَّوْئِيَّةِ ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15474, 'هَالٌ', 'هال', 'جامد', '', 'هال', 'هل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ن. قَاقُلَّةٌ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15475, 'هَامَّةٌ', 'هامة', 'جامد', '', 'هامة', 'همة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"ن. هَوَامٌّ.هَوَامٌّ - مُفْرَدُهُ هَامَّة. [هـ م م]. ""هَوَامُّ الأَرْضِ"" : حَشَرَاتُهَا الْمُؤْذِيَةُ. ""أَثْبَتَ عَجَائِبَهُ عَلَى أَفْوَاهِ الطَّيْرِ وَالْهَوَامِّ وَسَائِرِ حَشَرَاتِ الأَرْضِ"". (ابن المقفع)"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15476, 'هَانِيبَالٌ', 'هانيبال', 'جامد', '', 'هانيبال', 'هنبل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'N', 'N', 'O', '', '": يُطْلَقُ عَلَى شَهْرِ أُغُسْطُسَ حَسَبَ الْيَوْمِيَّةِ اللِّيبِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15477, 'مَهَبٌّ', 'مهب', 'جامد', 'هبب', 'مهب', 'مهب', '', '', '', 'مفرد', 'DnN', '', '', '"مَهَابُّ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""فِي مَهَبِّ الرِّيحِ"" : فِي مَوْضِعِ هُبُوبِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15478, 'مَهَابُّ', 'مهاب', 'جامد', '', 'مهاب', 'مهب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15479, 'هَبَابٌ', 'هباب', 'جامد', 'هبب', 'هباب', 'هبب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"هَبَابٌ-هَبَابٌ [هـ ب ب]. ""هَبَّ الْهَبَابُ"" : الْغُبَارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15480, 'هَبْرَةٌ', 'هبرة', 'جامد', 'هبر', 'هبرة', 'هبرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"(وَاحِدَةُالْهَبْرِلِلَّحْمِ)', '', 'R', '', '', '', '', '', '', '"هَبْرَةٌ-هَبْرَةٌ [هـ ب ر] (وَاحِدَةُ الْهَبْرِ لِلَّحْمِ). ""قَطَعَ لَهُ هَبْرَةً مِنْ فَخِذِ الْعِجْلِ"" : قِطْعَةَ لَحْمٍ لاَ عَظْمَ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15481, 'هِبْرِيَّةٌ', 'هبرية', 'جامد', 'هبر', 'هبرية', 'هبرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"هِبْرِيَّةٌ-هِبْرِيَّةٌ [هـ ب ر]. 1.""هِبْرِيَّةُ الرَّأْسِ"" : قِشْرَةُ الرَّأْسِ وَمَا يَتَعَلَّقُ بِأَسْفَلِ الشَّعْرِ كَالْغُبَارِ. 2.""هِبْرِيَّةُ الرِّيشِ"" : مَا يَطِيرُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15482, 'مَهْبَطَةٌ', 'مهبطة', 'جامد', 'هبط', 'مهبطة', 'مهبطة', '', '', '', 'مفرد', 'DnN', '', '', '"مَهَابِطُ"', '', 'R', '', '', '', '', '', '', '". ""مَهْبَطَةُ الطَّائِرَةِ"" : المِظَلَّةُ الَّتِي يَهْبِطُ بِهَا المِظَلِّيُّ مِنَ الطَّائِرَةِ إِلَى الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15483, 'مَهَابِطُ', 'مهابط', 'جامد', '', 'مهابط', 'مهبط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15484, 'مَهْبِطٌ', 'مهبط', 'جامد', 'هبط', 'مهبط', 'مهبط', '', '', '', 'مفرد', 'DnN', '', '', '"مَهَابِطُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَكَّةُ مَهْبِطُ الوَحْيِ"" : هِيَ مَكَانُ نُزُولِهِ. 2.""مَهْبِطُ الطَّائِرَاتِ"" : مَكَانُ هُبُوطِهَا، الْمَطَارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15485, 'مَهَابِطُ', 'مهابط', 'جامد', '', 'مهابط', 'مهبط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15486, 'مَهْبِلٌ', 'مهبل', 'جامد', 'هبل', 'مهبل', 'مهبل', '', '', '', 'مفرد', 'DnN', '', '', '"مَهَابِلُ"', '', 'R', '', '', '', '', '', '', '". ""مَهْبِلُ الْمَرْأَةِ"" : القَنَاةُ الْمُمْتَدَّةُ عِنْدَ الأُنْثَى مِنَ الفَرْجِ إِلَى الرَّحِمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15487, 'مَهَابِلُ', 'مهابل', 'جامد', '', 'مهابل', 'مهبل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15488, 'هَبَالَةٌ', 'هبالة', 'جامد', 'هبل', 'هبالة', 'هبلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"هَبَالَةٌ-هَبَالَةٌ [هـ ب ل]. ""عَبَّرَ بِسُلُوكِهِ الشَّاذِّ عَنْ هَبَالَةٍ"" : عَنْ فَقْدِ الْعَقْلِ وَعَدَمِ التَّمْيِيزِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15489, 'هَبَاءةٌ', 'هباءة', 'جامد', 'هبو', 'هباءة', 'هبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', 'N', 'O', 'O', 'O', '', '"هَبَاءةٌ-هَبَاءةٌ [هـ ب و]. : الْقِطْعَةُ مِنَ الْهَبَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15490, 'هَبَاءٌ', 'هباء', 'جامد', 'هبو', 'هباء', 'هب', '', '', '', 'مفرد', 'Dz', '', '', '"أَهْبَاءٌ"', '', 'Rz', '', 'N', 'O', 'O', 'O', '', '". 1.""تَطَايَرَ الْهَبَاءُ"" : الْغُبَارُ الْمُتَطَايِرُ بِفِعْلِ الرِّيحِ. 2.""ذَهَبَ عَمَلُهُ هَبَاءً مَنْثُوراً"" : ذَهَبَ ضَيَاعاً بِلاَ فَائِدَةٍ. الفرقان آية 23وَقَدِمْنَا إِلَى مَا عَمِلُوا مِنْ عَمَلٍ فَجَعَلْنَاهُ هَبَاءً مَنْثُوراً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15491, 'أَهْبَاءٌ', 'أهباء', 'جامد', '', 'ءهباء', 'هب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15492, 'هُتْرٌ', 'هتر', 'جامد', 'هتر', 'هتر', 'هتر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هُتْرٌ-هُتْرٌ [هـ ت ر]. ""اِشْتَدَّ بِهِ الْهُتْرُ"" : ذَهَابُ الْعَقْلِ مِنْ كِبَرٍ أَوْ مَرَضٍ أَوْ حُزْنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15493, 'هَتْفَى', 'هتفى', 'جامد', 'هتف', 'هتفى', 'هتف', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '"هَتْفَى-هَتْفَى [هـ ت ف]. ""آلَةٌ مُوسِيقِيَّةٌ هَتْفَى"" : مُرِنَّةٌ، مُصَوِّتَةٌ. ""قَوْسٌ هَتْفَى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15494, 'هُتْكَةٌ', 'هتكة', 'جامد', 'هتك', 'هتكة', 'هتكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"هُتْكَةٌ-هُتْكَةٌ [هـ ت ك]. 1.""صَارَ فِعْلُهُ هُتْكَةً"" : فَضِيحَةً. 2.""مَضَتْ هُتْكَةٌ مِنَ اللَّيْلِ"" : طَائِفَةٌ مِنْهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15495, 'هُتْكٌ', 'هتك', 'جامد', 'هتك', 'هتك', 'هتك', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"هُتْكٌ-هُتْكٌ [هـ ت ك]. ""هُتْكُ اللَّيْلِ"" : نِصْفُهُ أَوْ وَسَطُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15496, 'هَيْثَمٌ', 'هيثم', 'جامد', 'هثم', 'هيثم', 'هثم', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"هَيَاثِمُ"', '', 'R', '', '', '', '', '', '', '". 1. : كَثِيبٌ مِنَ الرَّمْلِ. 2. : صَقْرٌ. 3. : فَرْخُ العُقَابِ. 4. : فَرْخُ النَّسْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15497, 'هَيَاثِمُ', 'هياثم', 'جامد', '', 'هياثم', 'هثم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15498, 'مَهْجَرٌ', 'مهجر', 'جامد', 'هجر', 'مهجر', 'مهجر', '', '', '', 'مفرد', 'DnN', '', '', '"مَهَاجِرُ"', '', '', '', '', '', '', '', '', '". 1.""عَاشَ زَمَناً فِي الْمَهْجَرِ"" : بِلاَدُ الهِجْرَةِ. 2.""شُعَرَاءُ الْمَهْجَرِ"": الشُّعَرَاءُ العَرَبُ الَّذِينَ اِسْتَقَرُّوا فِي أَمْرِيكَا الشَّمَالِيَّةِ والْجَنُوبِيَّةِ. 3.""لاَ يَفُوهُ إِلاَّ بِالْمَهَاجِرِ"" : بِالقَلِيلِ مِنَ الكَلاَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15499, 'مَهَاجِرُ', 'مهاجر', 'جامد', '', 'مهاجر', 'مهجر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15500, 'هِجْرَةٌ', 'هجرة', 'جامد', 'هجر', 'هجرة', 'هجرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هِجْرَةٌ-هِجْرَةٌ [هـ ج ر]. 1.""كَانَتْ هِجْرَتُهُ إِلَى بِلاَدٍ بَعِيدَةٍ"": الْخُرُوجُ مِنْ أَرْضٍ إِلَى أُخْرَى سَعْياً وَرَاءَ هَدَفٍ مَّا. ""تَوَالَتِ الْهِجْرَةُ مِنَ الْبَادِيَةِ إِلَى الرِّيفِ"". 2.""هِجْرَةُ الرَّسُولِ"": خُرُوجُ النَّبِيِّ( مِنْ مَكَّةَ إِلَى الْمَدِينَةِ سنة622 م. وَبِهَا يُؤَرِّخُ الْمُسْلِمُونَ تَارِيخَهُمْ. ""الْهِجْرَةُ النَّبَوِيَّةُ"". 3.""دَارُ الْهِجْرَةِ"" : الْمَدِينَةُ الْمُنَوَّرَةُ. 4.""هِجْرَةُ اللَّقَالِقِ فِي الْخَرِيفِ"" : أَيِ انْتِقَالُهَا مِنْ مَكَانٍ إِلَى آخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15501, 'هَجِيرَةٌ', 'هجيرة', 'جامد', 'هجر', 'هجيرة', 'هجرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"هَجِيرَةٌ-هَجِيرَةٌ [هـ ج ر]. ""وَقْتُ الْهَجِيرَةِ"" : نِصْفُ النَّهَارِ عِنْدَ اشْتِدَادِ الْحَرِّ، الْهَاجِرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15502, 'هَجْعَةٌ', 'هجعة', 'جامد', 'هجع', 'هجعة', 'هجعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"هَجَعَاتٌ"', '', 'R', '', '', '', '', '', '', '". ""أَيْقَظَهُ بَعْدَ هَجْعَةٍ"": النَّوْمَة الْخَفِيفَة مِنْ أَوَّلِ اللَّيْلِ. ""إِنَّهَا هَجَعَاتٌ وَيَقَظَاتٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15503, 'هَجَعَاتٌ', 'هجعات', 'جامد', '', 'هجعات', 'هجعت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15504, 'هَجِيعٌ', 'هجيع', 'جامد', 'هجع', 'هجيع', 'هجع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَجِيعٌ-هَجِيعٌ [هـ ج ع]. ""فِي هَجِيعٍ مِنَ اللَّيْلِ"" : فِي جُزْءٍ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15505, 'هِجَانَةٌ', 'هجانة', 'جامد', 'هجن', 'هجانة', 'هجنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"هِجَانَةٌ-هِجَانَةٌ [هـ ج ن]. 1.""هِجَانَةُ الشَّيْءِ"" : بَيَاضُهُ. 2.""هِجَانَةُ الرَّجُلِ"" : كَرَمُهُ، حَسَبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15506, 'أُهْجِيَّةٌ', 'أهجية', 'جامد', 'هجو', 'ءهجية', 'هجة', '', '', '', 'مفرد', 'DnN', '', '', '"أهَاجٍ:الأَهاَجِي"', '', '', '', '', '', '', '', '', '". ""كَانَتْ أهَاجِيهِ لاَذِعَةً"" : مَا يَنْظِمُهُ الشَّاعِرُ مِنْ قَصَائِدَ أوْ قِطَعٍ أدَبِيَّةٍ فِي هِجَاءِ النَّاسِ، أيْ ذَمِّهِمْ وَإبْرَازِ عُيُوبِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15507, 'أهَاجِي', 'أهاجي', 'جامد', '', 'ءهاجي', 'هج', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15508, 'أهْدَابٌ', 'أهداب', 'جامد', 'هدب', 'ءهداب', 'هدب', '', '', '', 'مفرد', '', '', '', '"مفردهُدْب"', '', '', '', '', '', '', '', '', '". 1. ""أهْدَابُ العَيْنِ"": شَعْرُ أجْفَانِ العَيْنِ، أَشْفَارُهَا. 2.""تَمَسَّكَ بِأَهْدابٍ واهِيَةٍ"" : تَعَلَّقَ بِخُيوطٍ واهِيَةٍ. 3.""تَعَلَّقَ بِأَهْدابِ الكَعْبَةِ"" : بِأَطْرافِها. 4.""تَمَسَّكَ بِأهْدابِ الدِّينِ"" : ثَبَتَ عَلَيْهِ وَأخْلَصَ لِقَوَاعِدِهِ وَمَبَادِئِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15509, 'هُدَّابٌ', 'هداب', 'جامد', 'هدب', 'هداب', 'هدب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هُدَّابٌ-هُدَّابٌ [هـ د ب]. 1.""هُدَّابُ الثَّوْبِ"" : الْخُيُوطُ الَّتِي تَبْقَى فِي طَرَفَيْهِ مِنْ عَرْضَيْهِ دُونَ حَاشِيَتِهِ. 2.""هُدَّابُ النَّخْلِ"" : سَعْفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15510, 'هُدْبَةٌ', 'هدبة', 'جامد', 'هدب', 'هدبة', 'هدبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"واحدةالْهُدْبِ"', '', 'R', '', '', '', '', '', '', '"هُدْبَةٌ-هُدْبَةٌ [هـ د ب] (وَاحِدَةُ الْهُدْبِ). 1.""هُدْبَةُ الْعَيْنِ"" : الشَّعْرَةُ النَّابِتَةُ عَلَى شَفْرِ الْعَيْنِ. 2.""هُدْبَةُ الثَّوْبِ"" : الْقِطْعَةُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15511, 'هُدْبٌ', 'هدب', 'جامد', 'هدب', 'هدب', 'هدب', '', '', '', 'مفرد', 'DnN', '', '', '"أَهْدَابٌ"', '', 'R', '', '', '', '', '', '', '". 1. ""هُدْبُ الْعَيْنَيْنِ"" : شَعْرُ أَشْفَارِهِمَا. 2. ""هُدْبُ الثَّوْبِ"" : خَمْلُهُ وَطُرَّتُهُ. 3.""تَمَسَّكَ بِأَهْدَابِهِ"" : تَعَلَّقَ بِهِ. ""تَعَلَّقَ بِأَهْدَابِ الْكَعْبَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15512, 'أَهْدَابٌ', 'أهداب', 'جامد', '', 'ءهداب', 'هدب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15513, 'هَيْدَبٌ', 'هيدب', 'جامد', 'هدب', 'هيدب', 'هدب', '', '', '', 'مفرد', 'DnN', '', '', '"هَيَادِبُ"', '', 'R', '', '', '', '', '', '', '". 1.""سَحَابٌ هَيْدَبٌ"": سَحَابٌ مُتَدَلٍّ يَدْنُو مِنَ الأَرْضِ وَيُرَى كَأَنَّهُ خُيُوطٌ عِنْدَ انْصِبابِهِ. 2.""هَيْدَبُ الثَّوْبِ"" : خَمْلُهُ. 3.""هَيْدَبُ الْمَرْأَةِ"" : ثَدْيُهَا الْمُسْتَرْخِي. 4.""وَلَدٌ هَيْدَبُ الشَّعْرِ"" : كَثِيرُهُ. 5.""رَجُلٌ هَيْدَبٌ"" : جَافٌّ ثَقِيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15514, 'هَيَادِبُ', 'هيادب', 'جامد', '', 'هيادب', 'هدب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15515, 'هَوْدَجٌ', 'هودج', 'جامد', 'هدج', 'هودج', 'هدج', '', '', '', 'مفرد', 'DnN', '', '', '"هَوَادِجُ"', '', 'R', '', '', '', '', '', '', '". ""حَمَلُوهَا عَلَى الْهَوْدَجِ"" : مَحْمَلٌ يُوضَعُ عَلَى ظَهْرِ جَمَلٍ لَهُ قُبَّةٌ تَرْكَبُ فِيهِ النِّسَاءُ. ""هَوْدَجُ الْعَرُوسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15516, 'هَوَادِجُ', 'هوادج', 'جامد', '', 'هوادج', 'هدج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15517, 'هِدْرُوجِين', 'هدروجين', 'جامد', '', 'هدروجين', 'هدرجن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '"هِدْرُوجِين-هِدْرُوجِين (كيما). : جِسْمٌ بَسِيطٌ لاَ لَوْنَ لَهُ وَلاَ رَائِحَةَ وَلاَ طَعْمَ، خَفِيفٌ قَابِلٌ لِلِالْتِهَابِ، يَدْخُلُ فِي تَرْكِيبِ الْمَاءِ مَعَ الْأُوكْسِيجِينِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15518, 'هَدَفٌ', 'هدف', 'جامد', 'هدف', 'هدف', 'هدف', '', '', '', 'مفرد', 'DnN', '', '', '"أَهْدَافٌ"', '', 'R', '', '', '', '', '', '', '". 1.""الْهَدَفُ الْمَنْشُـودُ"" : الْمَقْصِدُ، الْغَايَةُ، الْمَطْلَبُ الْمَرْغُوبُ فِيهِ. ""جَعَلَ النَّجَاحَ هَدَفَهُ"". 2.""صَوَّبَ قَذَائِفَهُ نَحْوَ هَدَفٍ مُحَدَّدٍ"": غَرَضٍ، مَرْمىً. ""الأَهْدَافُ العَسْكَرِيَّةُ"" ""الأَهْدَافُ الوَطَنِيَّةُ"". 3. صَوَّبَ الْكُرَةَ إِلَى الْهَدَفِ "" : الْمَرْمَى. 4.""سَجَّلَ اللاَّعِبُ هَدَفاً رَائِعاً"" : الإِصَابَة فِي الْمَرْمَى. ""اِنْتَصَرَ الْفَرِيقُ بِثَلاَثَةِ أَهْدَافٍ مُقَابِلَ هَدَفٍ وَاحِدٍ"". 5.""كَانَ هَدَفاً لاِنْتِقَادَاتٍ جَارِحَةٍ"" : عُرْضَةً، أَيْ مَا يُقْصَدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15519, 'أَهْدَافٌ', 'أهداف', 'جامد', '', 'ءهداف', 'هدف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15520, 'هَدَالٌ', 'هدال', 'جامد', 'هدل', 'هدال', 'هدل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"هَدَالٌ-هَدَالٌ [هـ د ل]. ""هَدَالُ الشَّجَرِ"" : مَا تَدَلَّى مِنْ أَغْصَانِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15521, 'هُدَامٌ', 'هدام', 'جامد', 'هدم', 'هدام', 'هدم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هُدَامٌ-هُدَامٌ [هـ د م]. ""أَصَابَهُ الْهُدَامُ عَلَى ظَهْرِ الْبَاخِرَةِ"" : الدُّوَارُ الَّذِي يُصِيبُ رَاكِبَ الْبَاخِرَةِ فِي الْبَحْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15522, 'هِدْمٌ', 'هدم', 'جامد', 'هدم', 'هدم', 'هدم', '', '', '', 'مفرد', 'DnN', '', '', '"أَهْدَامٌ:هِدَامٌ"', '', 'R', '', '', '', '', '', '', '"هِدْمٌ-هِدْمٌ [هـ د م]. ج: أَهْدَامٌ، هِدَامٌ. 1.""رَجُلٌ هِدْمٌ"" : شَيْخٌ كَبِيرٌ. 2.""اِنْتَعَلَ هِدْماً"" : خُفّاً عَتِيقاً. 3.""لَبِسَ هِدْماً"" : ثَوْباً مُرَقَّعاً بَالِياً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15523, 'أَهْدَامٌ', 'أهدام', 'جامد', '', 'ءهدام', 'هدم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15524, 'هِدَامٌ', 'هدام', 'جامد', '', 'هدام', 'هدم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15525, 'هُدْنَةٌ', 'هدنة', 'جامد', 'هدن', 'هدنة', 'هدنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '"هُدَنٌ"', '', 'R', '', '', '', '', '', '', '". 1.""اِتَّفَقَ الْمُتَحَارِبُونَ عَلَى هُدْنَةٍ"" : وَقْفُ الْحَرْبِ إِلَى حِينٍ بِهَدَفِ الاِتِّفَاقِ عَلَى صُلْحٍ. ""اِتَّفَقُوا عَلَى هُدْنَةٍ وَ الأَمَلُ كَبِيرٌ ‏أَنْ يَتْبَعَهَا سِلْمٌ دَائِمٌ"". 2.""سَادَتِ الْهُدْنَةُ الأَرْجَاءَ"" : السُّكُونُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15526, 'هُدَنٌ', 'هدن', 'جامد', '', 'هدن', 'هدن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15527, 'هُدْهُدٌ', 'هدهد', 'جامد', 'هدهد', 'هدهد', 'هدهد', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"هَدَاهِدُ"', '', 'R', '', '', '', '', '', '', '". : طَائِرٌ مِنْ فَصِيلَةِ الْهُدْهُدِيَّاتِ، مِنْ رُتْبَةِ الشَّقِرَّاقِيَّاتِ، جَمِيلُ الشَّكْلِ، ذُو خُطُوطٍ وَأَلْوَانٍمُزَرْكَشَةٍ، يَتَمَيَّزُ بِقُنْزُع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15528, 'هَدَاهِدُ', 'هداهد', 'جامد', '', 'هداهد', 'هدهد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15529, 'هَدِيَّةٌ', 'هدية', 'جامد', 'هدى', 'هدية', 'هدة', '', '', '', 'مفرد', 'DnN', '', '', '"هَدَايَا"', '', '', '', '', '', '', '', '', '". ""تَسَلَّمَ هَدِيَّةً جَمِيلَةً"" : مَا يُقَدَّمُ وَيُهْدَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15530, 'هَدَايَا', 'هدايا', 'جامد', '', 'هدايا', 'هد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15531, 'هُذَاءٌ', 'هذاء', 'جامد', 'هذأ', 'هذاء', 'هذ', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"هُذَاءٌ-هُذَاءٌ [هـ ذ أ]. ""كَانَ كَلاَمُهُ مُجَرَّدَ هُذَاءٍ"" : كَلاَم بِلاَ مَعْنىً، غَيْرُ مَفْهُومٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15532, 'إهْذَارٌ', 'إهذار', 'جامد', 'هذر', 'ءهذار', 'إهذر', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"إهْذَارٌ - [هـ ذ ر]. ""الإِهْذَارُ فِي الكَلاَمِ"" : التَّكَلُّمُ بِهَذَيَانٍ وَبِلاَ مَعْن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15533, 'هُدْيَةٌ', 'هدية', 'جامد', 'هذي', 'هدية', 'هدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"هِدْيَةٌ-هِدْيَةٌ [هـ د ي] (مص. هَدَى). 1.""لاَ يَحِيدُ عَنْ هِدْيَتِهِ وَلاَ يَضَلُّ عَنْه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15534, 'هُرَاءٌ', 'هراء', 'جامد', 'هرأ', 'هراء', 'هر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'Rz', '', '', '', '', '', '', '"هُرَاءٌ-هُرَاءٌ، ةٌ [هـ ر أ]. 1.""كَلاَمُ هُرَاءٍ"" : كَلاَمُ هَذَيَانٍ، غَيْرُ خَاضِعٍ ل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15535, 'هَرِيئَةٌ', 'هريئة', 'جامد', 'هرأ', 'هريءة', 'هرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"هَرِيئَةٌ-هَرِيئَةٌ [هـ ر أ]. 1.""إِنَّهَا فَتْرَةٌ مِنْ فَتَرَاتِ الْهَرِيئَةِ"" : وَقْتٌ يُصِيبُ فِيهِ الْبَرْدُ النَّاس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15536, 'مِهْرَجَانٌ', 'مهرجان', 'جامد', 'هرج', 'مهرجان', 'مهرجن', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""المِهْرَجَانُ الفَنِّيُّ لِلْفُولْكْلُورِ"" : اِحْتِفَالٌ كَبِيرٌ تُقَدَّمُ فِيهِ حَفَلاَتُ الفُولْكْلُورِ، الْمَوْسِمُ. 2.""مِهْرَجانٌ خَطابِيٌّ"" : تَجَمُّعٌ يَحْضُرُهُ جُمْهُورٌ غَفِيرٌ مِنَ النَّاسِ تُلْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15537, 'هِرٌّ', 'هر', 'جامد', 'هرر', 'هر', 'هر', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"هِرَرَةٌ"', '', 'R', '', '', '', '', '', '', '". : حَيَوَانٌ مِنْ فَصِيلَةِ السِّنَّوْرِيَّاتِ، مِنْهُ مَا هُوَ بَرِّيٌّ، وَمَا هُوَ دَاجِنٌ، لَهُ خَطْمٌ قَصِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15538, 'هِرَرَةٌ', 'هررة', 'جامد', '', 'هررة', 'هررة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15539, 'هَرِيرَةٌ', 'هريرة', 'جامد', 'هرر', 'هريرة', 'هررة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"هُرَيْرَةٌ-هُرَيْرَةٌ [هـ ر ر]. : تَصْغِيرُ هِرَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15540, 'هَرِيسَةٌ', 'هريسة', 'جامد', 'هرس', 'هريسة', 'هرسة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"هَرِيسَةٌ-هَرِيسَةٌ [هـ ر س] (طخ). 1. : طَعَامٌ يُطْبَخُ مِنَ الْقَمْحِ الْمَدْقُوقِ وَاللَّحْمِ. 2. : نَوْعٌ مِنَ الْحَلْوَى يُصْنَعُ مِنَ الدَِّقيقِ وَالسَّمْنِ والسّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15541, 'هَرِيسٌ', 'هريس', 'جامد', 'هرس', 'هريس', 'هرس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَرِيسٌ-هَرِيسٌ [هـ ر س]. ""تَحَوَّلَ الْحَبُّ إِلَى هَرِيسٍ"" : الْحَبُّ الْمَدْقُوقُ بِالْمِهْرَاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15542, 'هُرْمُونٌ', 'هرمون', 'جامد', '', 'هرمون', 'هرمن', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ــات. 1. : مَادَّةٌ تُفْرِزُهَا غُدَّةٌ مِنَ الْغُدَدِ الصُّمِّ فِي الدَّمِ مُبَاشَرَةً. 2.""هُرْمُونَاتُ النُّمُوِّ"" : مَوَادُّ عُضْوِيَّةٌ تُفْرِزُهَا الْغُدَّةُ النُّخَامِيَّةُ تُنَشِّطُ عَمَلِيَّةَ النُّمُوِّ فِي الْحَيَوَانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15543, 'هُرْهُورٌ', 'هرهور', 'جامد', 'هرهر', 'هرهور', 'هرهر', '', '', '', 'مفرد', 'DnN', '', '', '"هَرَاهِيرُ"', '', 'R', '', '', '', '', '', '', '". 1.""هُرْهُورُ عُنْقُودِ الْعِنَبِ"" : مَا تَنَاثَرَ مِنْهُ فِي أَصْلِ الْكَرْمِ. 2.""هُرْهُورُ الْمَاءِ"" : صَوْتُهُ عِنْدَمَا يَتَدَفَّقُ كَثِيراً. 3.""اِنْطَلَقَ الْهُرْهُورُ وَسَطَ الأَمْوَاجِ"" : زَوْرَقٌ أَوْ قَارِبٌ كَبِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15544, 'هَرَاهِيرُ', 'هراهير', 'جامد', '', 'هراهير', 'هرهر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15545, 'هِرَاوَةٌ', 'هراوة', 'جامد', 'هرو', 'هراوة', 'هرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":هَرَاوَى"', '', 'R', '', '', '', '', '', '', '". ""يُلَوِّحُ بِهِرَاوَةٍ"" : بِعَصاً ضَخْمَةٍ. ""وَثَبَ إِلَيْهِ صَاحِبُ الْبَيْتِ بِهِرَاوَةٍ فَأَوْجَعَهُ ضَرْباً"". (ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15546, 'هَرَاوَى', 'هراوى', 'جامد', '', 'هراوى', 'هر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15547, 'هُرْيٌ', 'هري', 'جامد', 'هري', 'هري', 'هر', '', '', '', 'مفرد', 'DnN', '', '', '"أَهْرَاءُ"', '', 'Rw', '', '', '', '', '', '', '". ""كَدَّسَ فِي الْهُرْيِ مَحَاصِيلَ السَّنَةِ"" : بَيْتٌ كَبِيرٌ تُوضَعُ فِيهِ أَكْيَاسُ الْقَمْحِ وَالأَطْعِمَةِ وَمَا إِلَى ذَلِكَ، مَخْزَنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15548, 'أَهْرَاءُ', 'أهراء', 'جامد', '', 'ءهراء', 'هر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
