INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15551, 'هَزَجٌ', 'هزج', 'جامد', 'هزج', 'هزج', 'هزج', '', '', '', 'مفرد', 'DnN', '', '', '"أَهْزَاجٌ"', '', 'R', '', '', '', '', '', '', '". 1.""طَرِبَ لِهَزَجِهِ"" : لِصَوْتِهِ لِمَا فِيهِ مِنْ تَرَنُّمٍ وَتَطْرِيبٍ. 2.""هَزَجُ الذِّئَابِ"" : صَوْتُهَا. 3.""هَزَجُ الرَّعْدِ"" : صَوْتُهُ. 4.""الهَزَجُ"" : نَوْعٌ مِنَ الأَغَانِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15552, 'أَهْزَاجٌ', 'أهزاج', 'جامد', '', 'ءهزاج', 'هزج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
