INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15554, 'هُزْرُوفٌ', 'هزروف', 'جامد', '', 'هزروف', 'هزرف', '', '', '', 'جمع تكسير', 'DnN', '', '', '"هَزَارِيفُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: هَزَارِيفُ. ""هُزْرُوفُ النّعَامِ"" : ذَكَرُهُ، أَيِ الظَّلِيمُ السَّرِيعُ الْخَفِيفُ."', ':لا جذر:لا مفرد');
