INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15559, 'هُزَالَةٌ', 'هزالة', 'جامد', 'هزل', 'هزالة', 'هزلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"هُزَالَةٌ - [هـ ز ل]. ""تَمَيَّزَ حَدِيثُهُ بِالْهُزَالَةِ"" : بِالْفُكَاهَةِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15560, 'هَازِمَةٌ', 'هازمة', 'جامد', 'هزم', 'هازمة', 'هزمة', '', '', '', 'مفرد', 'DnN', '', '', '"هَوَازِمُ"', '', '', '', '', '', '', '', '', '"هَازِمَةٌ - ج: هَوَازِمُ. [هـ ز م]. ""نَزَلَتْ بِهِ الْهَوَازِمُ"" : الْمَصَائِبُ وَالْكَوَارِثُ الشَّدِيدَةُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15561, 'هَوَازِمُ', 'هوازم', 'جامد', '', 'هوازم', 'هزم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15562, 'هَضْلاَءُ', 'هضلاء', 'جامد', 'هضل', 'هضلاء', 'هضل', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"هَضْلاَءُ-هَضْلاَءُ [هـ ض ل]. ""اِمْرَأَةٌ هَضْلاَءُ"": طَوِيلَةُ الثَّدْيَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15563, 'هِسْتِيريا', 'هستيريا', 'جامد', '', 'هستيريا', 'هستر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"""وَجَدَهُ فِي حَالَةٍ مِنَ الهِيسْتِيريا"" : مَرَضٌ عَصَبِيٌّ يُفْقِد"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15564, 'هِشَامٌ', 'هشام', 'جامد', 'هشم', 'هشام', 'هشم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هِشَامٌ - [هـ ش م]. 1.""هِشَامُ الرَّجُلِ"" : جُودُهُ.  2.""هِشَام"" : اِسْمُ عَلَمٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15565, 'هَيْكَلٌ', 'هيكل', 'جامد', 'هكل', 'هيكل', 'هكل', '', '', '', 'مفرد', 'DnN', '', '', '"هَيَاكِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""هَيْكَلُ الشَّيْءِ"" : شَكْلُهُ، صُورَتُهُ، هَيْئَتُهُ وَيُعَيَّنُ بِهِ عَادَةً مَا هُوَ ضَخْمٌ. ""هَيْكَلُ الْبِنَاءِ"" ""هَيْكَلُ السَّيَّارَةِ"" ""هَيْكَلُ السَّرِيرِ"". 2.""فَرَسٌ هَيْكَلٌ"" : طَوِيلٌ ضَخْمٌ. 3.""نَبَاتٌ أَوْ شَجَرٌ هَيْكَلٌ"" : مَا طَالَ وَعَظُمَ مِنْهُ. 4.""الْهَيْكَلُ الْعَظْمِيُّ"" : مَجْمُوعُ الْعِظَامِ الَّتِي يَقُومُ عَلَيْهَا بِنَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15566, 'هَيَاكِلُ', 'هياكل', 'جامد', '', 'هياكل', 'هكل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15567, 'هِلاَلِيَّةٌ', 'هلالية', 'جامد', '', 'هلالية', 'هللة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '": نَوْعٌ مِنَ الْفَطَائِرِ يُصْنَعُ مِنَ الدَّقِيقِ وَالزُّبْدَةِ عَلَى شَكْلِ هِلاَلٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15568, 'مُهَلَّبِيَّةٌ', 'مهلبية', 'جامد', 'هلب', 'مهلبية', 'مهلبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مُهَلَّبِيَّةٌ-مُهَلَّبِيَّةٌ [هـ ل ب] (طخ). : نَوْعٌ مِنَ الْحَلَوِيَّاتِ الشَّرْقِيَّةِ تُصْنَعُ مِنَ الْحَلِيبِ وَالسُّكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15569, 'مَهْلَكَةٌ', 'مهلكة', 'جامد', 'هلك', 'مهلكة', 'مهلكة', '', '', '', 'مفرد', 'DnN', '', '', '"مَهَالِكُ"', '', 'R', '', '', '', '', '', '', '". ""سَقَطَ فِي مَهْلَكَةٍ"" : فِي مَوْضِعِ الهَلاَكِ. ""الْحُرُوبُ مَهَالِكُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15570, 'مَهَالِكُ', 'مهالك', 'جامد', '', 'مهالك', 'مهلك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15571, 'هَلَكَةٌ', 'هلكة', 'جامد', 'هلك', 'هلكة', 'هلكة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":هَلَكٌ"', '', 'R', '', '', '', '', '', '', '". 1.""سَنَةٌ هَلَكَـةٌ"" : سَنَةٌ مُجْدِبَةٌ. 2. ""صَارَ إِلَى هَلَكَةٍ"" : إِلَى هَلاَكٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15572, 'هَلَكٌ', 'هلك', 'جامد', '', 'هلك', 'هلك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15573, 'هَلاَلٌ', 'هلال', 'جامد', 'هلل', 'هلال', 'هلل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"هَلاَلٌ-هَلاَلٌ [هـ ل ل]. ""هَلاَلُ الْمَطَرِ"" : أَوَّلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15574, 'هَلَلٌ', 'هلل', 'جامد', 'هلل', 'هلل', 'هل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"هَلَلٌ-هَلَلٌ [هـ ل ل]. 1.""هَلَلُ الْمَطَرِ"" : أَوَّلُهُ. 2.""بِهِ هَلَلٌ"": خَوْفٌ. ""مَاتَ هَلَلاً"". 3.""هَلَلُ العَنْكَبُوتِ"" : شُعُّهُ، نَسْجُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15575, 'هَلٌّ', 'هل', 'جامد', 'هلل', 'هل', 'هل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هِلٌّ-هِلٌّ [هـ ل ل]. ""هِلُّ الْقَمَرِ"" : اِسْتِهْلاَلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15576, 'هُلاَمٌ', 'هلام', 'جامد', 'هلم', 'هلام', 'هلم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هُلاَمٌ-هُلاَمٌ [هـ ل م]. : مَادَّةٌ آزُوتِيَّةٌ شَفَّافَةٌ تُسْتَخْرَجُ مِنَ الأَنْسِجَةِ الْحَيَوَانِيَّةِ كَالْجِلْدِ وَالْعَظْمِ وَالأَوْتَارِ وَالْغَضَارِيفِ، تَكُونُ جَامِدَةً وَيَتِمُّ تَحْوِيلُهَا بِتَسْخِينِهَا أَوْ بِتَأْثِيرِ الْمَاءِ الْمُغَلَّى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15577, 'هَلْهَلٌ', 'هلهل', 'جامد', 'هلهل', 'هلهل', 'هلهل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَلْهَلٌ-هَلْهَلٌ [هـ ل هـ ل]. 1.""ثَوْبٌ هَلْهَلٌ"" : ثَوْبٌ نَسْجُهُ ضَعِيفٌ، خَفِيفٌ، هَلْهَالٌ. 2.""هَلْهَلُ الْعَنْكَبُوتِ"" : هَلَلُهُ، شُعُّهُ، بَيْتُهُ، نَسِيجُ خُيُوطِهِ. 3.""أَطْعَمَهُ هَلْهَلاً"" : سُمّاً قَاتِلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15578, 'هِلِيكُوبِتِر', 'هليكوبتر', 'جامد', '', 'هليكوبتر', 'هلكبتر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": طَائِرَةٌ لَهَا مَرَاوِحُ تَدُورُ فِي أَثْنَاءِ طَيَرَانِهَا وَهُوَ مَايَسْمَحُ لَهَا بِالنُّزُولِ عَمُودِيّاً وَالْوُقُوفِفِي أَيِّ مَكَانٍ دُونَ حَاجَةٍ إِلَى مَطَارٍ. ن. حَوَّامَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15579, 'هِلْيُومٌ', 'هليوم', 'جامد', '', 'هليوم', 'هلم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'N', 'O', '', '": غَازٌ نَادِرٌ فِي الْجَوِّ خَفِيفٌ، لاَ لَوْنَ لَهُ، يُسْتَخْدَمُ فِي نَفْخِ الْمَنَاطِيدِ لِعَدَمِ قَابِلِيَّتِهِ لِلاشْتِعَالِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15580, 'هَلْيُونٌ', 'هليون', 'جامد', '', 'هليون', 'هلن', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"هَلْيُونٌ-هَلْيُونٌ، ةٌ (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الزَّنْبَقِيَّاتِ، لَهُ جُذُورٌ تَمْتَدُّ تَحْتَ الأَرْضِ، وَقُضْبَانٌ رَخْوَةٌ لَيِّنَةٌ تُؤْكَلُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15581, 'مِهْمَزٌ', 'مهمز', 'جامد', 'همز', 'مهمز', 'مهمز', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَهَامِزُ"', '', 'R', '', '', '', '', '', '', '". ن. المِهْمَازُ.مِهْمَازٌ - ج: مَهَامِيزُ. [هـ م ز].(صيغة مِفْعال). 1.""مِهْمَازُ النَّارِ"" : آلَةٌ مِنْ حَدِيدٍ تُهْمَزُ بِهَا النَّارُ. 2.""مِهْمَازُ الْفَرَسِ أَوِ الدَّابَّةِ"" : حَدِيدَةٌ فِي مُؤَخَّرِ حِذَاءِ الرَّاكِبِ يَنْخُسُ بِهَا جَنْبَيْهَا. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15582, 'مَهَامِزُ', 'مهامز', 'جامد', '', 'مهامز', 'مهمز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15583, 'هَمْسٌ', 'همس', 'جامد', 'همس', 'همس', 'همس', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَمْسٌ-هَمْسٌ [هـ م س]. 1.""كَلَّمَهُ هَمْساً"" : بِكَلاَمٍ خَفِيٍّ.طه آية 108وَخَشَعَتِ الأَصْوَاتُ للِرَّحْمَانِ فَلاَ تَسْمَعُ إِلاَّ هَمْساً.(قرآن). 2.""يَطَأُ الأَرْضَ هَمْساً"" : أَيْ يَطَأُ الأَرْضَ وَطْأً خَفِيفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15584, 'هَامَةٌ', 'هامة', 'جامد', 'همم', 'هامة', 'همة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1. ""اِنْتَصَبَ عَالِيَ الْهَامَةِ"": وَاجِهَة الرَّأْسِ.أُلاَمُ عَلَى لَيْلَى وَلَوْ أَنَّ هَامَتِي*تُدَاوَى بِلَيْلَى بَعْدَ يُبْسٍ لَبَلَّتِ (قيس بن الملوح)""مَرْفُوعَ الْهَامَةِ أَمْشِي"". 2.""هَامَةُ الْقَوْمِ"" : سَيِّدُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15585, 'مُهِمَّةٌ', 'مهمة', 'جامد', 'همم', 'مهمة', 'مهمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1. ""كُلِّفَ بِإِنْجَازِ مُهِمَّةٍ صَعْبَةٍ"" : بِأُمُورٍ لَهَا مُوَاصَفَاتٌ مُحَدَّدَةٌ وَمُعَيَّنَةٌ. ""هَذِهِ مِنْ مَهَامِّ الرَّئِيسِ"" ""قَامَ بِمُهِمَّةٍ عَلَى أَحْسَنِ وَجْهٍ"". 2.""مُهِمِّةُ الْحُكُومَةِ هِيَ إِنْجَازُ الْمَشَارِيعِ"" : وَظِيفَتُهَا، رِسَالَتُهَا. ""أَمَامَهُ مُهِمَّاتٌ جَدِيدَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15586, 'هِمَّةٌ', 'همة', 'جامد', 'همم', 'همة', 'همة', '', '', '', 'مفرد', 'DnN', '', '', '"هِمَمٌ"', '', 'R', '', '', '', '', '', '', '". 1.""هِمَّتُهُ أَنْ يَسُودَ الْعَدْلُ"" : مَا هُمَّ بِهِ مِنْ أَمْرٍ لِيُفْعَلَ. 2.""هِمَّةٌ عَالِيَةٌ"" : عَزْمٌ. ""هُوَ عَالِي الْهِمَّةِ"" ""لَهُ هِمَّةٌ عَالِيَةٌ"" ""هُوَ بَعِيدُ الْهِمَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15587, 'هِمَمٌ', 'همم', 'جامد', '', 'همم', 'هم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15588, 'هَمٌّ', 'هم', 'جامد', 'همم', 'هم', 'هم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَمٌّ-هَمٌّ [هـ م م]. 1.""اِسْتَبَدَّ بِهِ الْهَمُّ طُولَ الْوَقْتِ"" : الْحُزْنُ، الْغَمُّ. 2.""كَانَ هَمُّهُ أَنْ يَنْجَحَ أَوَّلاً"" : مَا يَشْغَلُ بَالَهُ، مَا يُؤَرِّقُ فِكْرَهُ. ""صَرَفَ هَمَّهُ إِلَى التَّخَلُّصِ مِنَ الدُّيُونِ"" ""تُؤَرِّقُهُ هُمُومُ مَعِيشَةِ أَبْنَائِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15589, 'هَوَامٌّ', 'هوام', 'جامد', 'همم', 'هوام', 'هم', '', '', '', 'مفرد', '', '', '', '"مفردهَامَّة"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". ""هَوَامُّ الأَرْضِ"" : حَشَرَاتُهَا الْمُؤْذِيَةُ. ""أَثْبَتَ عَجَائِبَهُ عَلَى أَفْوَاهِ الطَّيْرِ وَالْهَوَامِّ وَسَائِرِ حَشَرَاتِ الأَرْضِ"". (ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15590, 'هِنَاءٌ', 'هناء', 'جامد', 'هنأ', 'هناء', 'هن', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"هِنَاءٌ-هِنَاءٌ [هـ ن أ]. 1. : قَطْرَانٌ. 2.""هِنَاءُ النَّخْلَةِ"" : عِذْقُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15591, 'هِنْدٌ', 'هند', 'جامد', '', 'هند', 'هند', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1. : اِسْمُ عَلَمٍ لِلإِنَاثِ. 2. : اِسْمٌ لِجَمَاعَةٍ مِنَ الإِبِلِ مِنْ مِائَةٍ إِلَى مِائَتَيْنِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15592, 'هِنْدِبَا', 'هندبا', 'جامد', '', 'هندبا', 'هندب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '"هِنْدِبَا-هِنْدِبَا (نب). : بَقْلَةٌ زِرَاعِيَّةٌ مِنْ فَصِيلَةِ الْمُرَكَّبَاتِ، وَرَقُهُ أَزْرَقُ اللَّوْنِ، لَهُ طَعْمٌ مُرٌّ، يُطْبَخُ وَرَقُهُ وَيُسْتَعْمَلُ تَابِلاً، كَمَا يُجْعَلُ سَلَطَةً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15593, 'هَوَادَةٌ', 'هوادة', 'جامد', 'هود', 'هوادة', 'هدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"هَوَادَةٌ-هَوَادَةٌ [هـ و د]. 1.""عَامَلَهُ بِهَوَادَةٍ"" : بِلِينٍ وَرِفْقٍ. 2.""عَامَلَهُ مُعَامَلَةً شَدِيدَةً بِلاَ هَوَادَةٍ"" : بِلاَ مُدَارَاةٍ وَلاَ مُحَابَاةٍ. 3.""وَجَدَ هَوَادَةً فِي عُزْلَتِهِ"" : سُكُوناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15594, 'هِنْدَامٌ', 'هندام', 'جامد', 'هندم', 'هندام', 'هندم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هِنْدَامٌ-هِنْدَامٌ [هـ ن د م]. 1.""جَمِيلُ الْهِنْدَامِ"" : جَمِيلُ الْقَدِّ حَسَنُهُ. 2.""أَصْلَحَ مِنْ هِنْدَامِهِ"" : مِنْ تَنْظِيمِ مَلاَبِسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15595, 'هَنَةٌ', 'هنة', 'جامد', 'هنو', 'هنة', 'هنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":هَنَوَاتٌ"', '', 'R', '', '', '', '', '', '', '". ""صَدَرَتْ عَنْهُ هَنَةٌ"" : مَا يُسْتَقْبَحُ ذِكْرُهُ. سَتَكُونُ هَنَاتٌ وَهَنَاتٌ(حديث) : أَيْ شُرُورٌ وَ فَسَادٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15596, 'هَنَوَاتٌ', 'هنوات', 'جامد', '', 'هنوات', 'هنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15597, 'هُنَيْهَةٌ', 'هنيهة', 'جامد', 'هنو', 'هنيهة', 'هنهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"هُنَيْهَةٌ-هُنَيْهَةٌ [هـ ن و]. ""اِنْتَظِرْ هُنَيْهَةً"" : وَقْتاً، لَحْظَةً قَصِيرَةً، يَسِيرَةً. ""وَقَفَ الشَّيْخُ هُنَيْهَةً يَتَأَمَّلُ فِي الْمُغَنِّيَةِ الصَّغِيرَةِ"". (عبد الحكيم قاسم)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15598, 'هَوَاءٌ', 'هواء', 'جامد', '', 'هواء', 'ه', '', '', '', 'جمع تكسير', 'Dz', '', '', '', '', 'Rz', '', '', '', '', '', '', '"1. غَازٌ يَتَكَوَّنُ مِنَ الْأُكْسِجِينِ وَالآزُوتِّ وَغَازَاتٍ قَلِيلَةٍ أُخْرَى، يُغَلِّفُ الْكُرَةَ الْأَرْضِيَّةَ وَتَتَوَقَّفُ عَلَيْهِ حَيَاةُ كُلِّ الْمَخْلُوقَاتِ عَلَيْهَا. ""هَوَاءُ الْغُرْفَةِ"". 2.""هَوَاءُ الْبِلاَدِ"" : طَقْسُهَا. 3. ""طَارَ فِي الْهَوَاءِ"" : فِي الْجَوِّ. 4. ""الْهَوَاءُ الطَّلْقُ"" : الطَّبِيعَةُ مُطْلَقاً. ""نَامَ فِي الْهَوَاءِ الطَّلْقِ"". 5.""قَلْبٌ هَوَاءٌ"" : فَارِغٌ.إبراهيم آية 43وَأَفْئِدَتُهُمْ هَوَاءٌ.(قرآن). 6.""وَلَدٌ هَوَاءٌ"" : جَبَانٌ. 7.""تَكْيِيفُ الْهَوَاءِ"" : عَمَلِيَّةٌ اصْطِنَاعِيَّةٌ يُؤَدِّيهَا جِهَازٌ كَهْرَبَائِيٌّ يُحَافِظُ بِهَا عَلَى دَرَجَةٍ حَرَارِيَّةٍ مُعَيَّنَةٍ دَاخِلَ مَكَانٍ مَّا، كَالْغُرْفَةِ أَوِ الْقِطَارِ أَوِ السَّيَّارَةِ أَوِ الطَّائِرَةِ. 8.""الإِرْسَالُ عَلَى الْهَوَاءِ"" : إِرْسَالُ الصَّوْتِ أَوِ الصُّورَةِ عَبْرَ جِهَازِ الْإِرْسَالِ دُونَ سَابِقِ تَسْجِيلٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15599, 'يَهُودٌ', 'يهود', 'جامد', 'هود', 'يهود', 'هد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يَهُودٌ-يَهُودٌ [هـ و د].""طَائِفَةُ الْيَهُودِ"" : مَنْ يَدِينُونَ بِالشَّرِيعَةِ الْيَهُودِيَّةِ، دِينِ مُوسَى عَلَيْهِ السَّلاَمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15600, 'هَوَّارَةٌ', 'هوارة', 'جامد', 'هور', 'هوارة', 'هرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"هَوَّارَةٌ-هَوَّارَةٌ [هـ و ر]. ""اِنْخَرَطَ فِي جَيْشِ الْهَوَّارَةِ"" : جَمَاعَةٌ مِنَ الْجُنُودِ غَيْر النِّظَامِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15601, 'هُوفٌ', 'هوف', 'جامد', 'هوف', 'هوف', 'هف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"هَوْفٌ-هَوْفٌ [هـ و ف]. 1.""اِشْتَدَّ هَوْفُ الصَّيْفِ"" : الرِّيحُ الشَّدِيدَةُ الْحَارَّةُ. 2.""اِشْتَدَّ هَوْفُ الشِّتَاءِ"" : الرِّيحُ البَارِدَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15602, 'تَهَاوِيلُ', 'تهاويل', 'جامد', 'هول', 'تهاويل', 'تهل', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '"تَهَاوِيلُ-تَهَاوِيلُ [هـ و ل]. 1.""تَهَاوِيلُ الحُقُولِ"" : الفَزَّاعَاتُ، أيْ مَا يُخِيفُ الطُّيُورَ وَيُرْعِبُهَا. 2.""تَهَاوِيلُ الرَّبِيعِ"" : مَبَاهِجُهُ وَزِينَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15603, 'هُولَةٌ', 'هولة', 'جامد', 'هول', 'هولة', 'هلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"هُولَةٌ-هُولَةٌ [هـ و ل]. 1.""خَوَّفَهُ بِالْهُولَةِ"" : مَا يُفَزَّعُ بِهِ الصَّبِيُّ. 2.""هُولَةُ الْحُقُولِ"" : مَا يُوضَعُ وَسَطَ الْكُرُومِ وَغَيْرِهَا لِتَخْوِيفِ الْحَيَوَانَاتِ وَالطُّيُورِ. 3.""اِمْرَأَةٌ هُولَةٌ"" : اِمْرَأَةٌ تُهْوِلُ النَّاظِرَ بِحُسْنِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15604, 'هُوَامٌ', 'هوام', 'جامد', 'هوم', 'هوام', 'هم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هُوَامٌ-هُوَامٌ [هـ و م]. ""بِهِ هُوَامٌ"" : هُيَامٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15605, 'هَالَةٌ', 'هالة', 'جامد', 'هول،هيل', 'هالة', 'هلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""هَالَةُ الْقَمَرِ"" : دَارَتُهُ.أَنَّى ثَوَى ذُو طِمَاحٍ فَهْوَ مُغْتَرِب*فِي دَارَةِ الشَّمْسِ أَوْ فِي هَالَةِ الْقَمَر (م. م. الجواهري).2.""أَحَاطَهُ بِهَالَةٍ مِنَ الْحَفَاوَةِ"" : أَحَاطَهُ بِحَفَاوَةٍ بَالِغَةٍ. ""أَحَاطَهُ بِهَالَةٍ مِنَ الْمَجْدِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15606, 'هُوَيْنَا', 'هوينا', 'جامد', 'هون', 'هوينا', 'هن', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"هُوَيْنَا-هُوَيْنَا [هـ و ن]. ""تَمْشِي الْهُوَيْنَا"" : تَمْشِي بِتُؤَدَةٍ وَرِفْقٍ.تَمْشِي الْهُوَيْنَا بَيْنَ نِسْوَتِهَـا*مَشْيَ النَّزِيفِ صَفَتْ مَشَارِبُـه (بشار بن برد)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15607, 'هَاوُنٌ', 'هاون', 'جامد', 'هون', 'هاون', 'هن', '', '', '', 'مفرد', 'DnN', '', '', '"هَوَاوِينُ"', '', 'R', '', '', '', '', '', '', '". 1.""تَدُقُّ الْحُبُوبَ فِي الْهَاوُنِ"" : وِعَاءٌ مِنْ خَشَبٍ أَوْ نُحَاسٍ يُدَقُّ فِيهِ مَا يَنْبَغِي أَنْ يُدَقَّ. 2.""مَدْفَعُ الْهَاوُنِ"" : مَدْفَعٌ لِلدِّفَاعِ الْعَسْكَرِيِّ تُطْلَقُ قَذَائِفُهُ مُتَقَوِّسَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15608, 'هَوَاوِينُ', 'هواوين', 'جامد', '', 'هواوين', 'هن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15609, 'مَهْوَاةٌ', 'مهواة', 'جامد', 'هوي', 'مهواة', 'مهة', '', '', '', 'مفرد', 'DnN', '', '', '"مَهَاوٍ:الْمَهَاوِي"', '', '', '', '', '', '', '', '', '". ن. مَهْوىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15610, 'مَهَاوِي', 'مهاوي', 'جامد', '', 'مهاوي', 'مه', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15611, 'مَهْوًى', 'مهوى', 'جامد', 'هوي', 'مهوى', 'مه', '', '', '', 'مفرد', 'Dy', '', '', '"مَهَاوٍ:الْمَهَاوِي"', '', '', '', 'N', 'O', 'O', 'O', '', '". 1. ""فِي مَهْوَى الرِّيَاحِ"" : فِي فَضاءِ... 2.""كَانَتِ الصُّقُورُ تَنْتَقِلُ بَيْنَ الْمَهَاوِي"" : بَيْنَ الجِبَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15612, 'مَهَاوِي', 'مهاوي', 'جامد', '', 'مهاوي', 'مه', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15613, 'هِوَايَةٌ', 'هواية', 'جامد', 'هوي', 'هواية', 'هة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""هِوَايَةُ الْفُنُونِ الْجَمِيـلَةِ"" : الْوُلُوعُ بِهَا وَمُزَاوَلَتُهَا فِي أَوْقَاتِ الْفَرَاغِ دُونَ احْتِرَافٍ. ""هِوَايَةُ الْمُوسِيقَى"" ""هِوَايَةُ جَمْعِ الطَّوَابِعِ البَرِيدِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15614, 'هَوِيٌّ', 'هوي', 'جامد', 'هوي', 'هوي', 'ه', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"هَوِيٌّ-هَوِيٌّ [هـ و ي]. 1.""هَوِيُّ الأُذُنِ"" : دَوِيُّهَا. 2.""هَوِيُّ اللَّيْلِ"" : طَائِفَةٌ مِنْهُ، أَيْ قِسْمٌ مِنْهُ. 3.""قَضَيْتُ عِنْدَهُ هَوِيّاً"" : مَلِيّاً، طَوِيلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15615, 'هَوًى', 'هوى', 'جامد', 'هوي', 'هوى', 'ه', '', '', '', 'مفرد', 'Dy', '', '', '"أَهْوَاءٌ"', '', '', '', '', '', '', '', '', '". 1.""هَوَاهُ صَادِقٌ"" : عِشْقُهُ، حُبُّهُ.أُحِبُّـكَ حُبَّيْنِ حُبَّ الْهَـوَى*وَحُبّاً لأَنَّـكَ أَهْـلٌ لِـذَاكَا (رابعة العدوية).2. ""يَتَصَرَّفُ عَلَى هَوَاهُ"" : حَسَبَ مَيْلِ نَفْسِهِ وَنَزُوعِهَا. ""يَسِيرُ عَلَى هَوَاهُ"" ""كَبَحَ هَوَاهُ""ص آية 26فَاحْكُمْ بَيْنَ النَّاسِ بِالْحَقِّ وَلاَ تَتَّبِعِ الْهَوَى. (قرآن). 3. ""هُوَ مِنْ أَصْحَابِ الأَهْوَاءِ"" : مِنْ أَصْحَابِ الْمِلَلِ وَالنِّحَلِ وَالْهَرْطَقَةِ. 4. ""بَنَاتُ الْهَوَى"" : الْمُومِسَاتُ، بَنَاتُ اللَّيْلِ، الْبَغايَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15616, 'أَهْوَاءٌ', 'أهواء', 'جامد', '', 'ءهواء', 'ه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15617, 'هُيَامٌ', 'هيام', 'جامد', 'هيم', 'هيام', 'هم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هِيَامٌ-هِيَامٌ [هـ ي م] (مص. هَامَ). 1.""كَانَ هِيَامُهُ شَدِيـداً"" : عَطَشُهُ. 2.""اِشْتَدَّ هِيَامُهُ بِهَا"" : شَغَفُهُ، أَيْ شِدَّةُ الْحُبِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15618, 'هَيْجَاءُ', 'هيجاء', 'جامد', 'هيج', 'هيجاء', 'هج', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"هَيْجَاءُ-هَيْجَاءُ [هـ ي ج]. ""دَخَلَ الْهَيْجَاءَ غَيْرَ خَائِفٍ"" : الْحَرْبَ، الْمَعْرَكَةَ.أَخَاكَ أَخَاكَ إِنَّ مَنْ لاَ أَخـاً لَـه*كَسَاعٍ إِلَى الْهَيْجَا بِغَيْرِ سِلاَحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15619, 'هَيْفَاءُ', 'هيفاء', 'جامد', 'هيف', 'هيفاء', 'هف', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"هَيْفَاءُ-هَيْفَاءُ [هـ ي ف]. ""اِمْرَأَةٌ هَيْفَاءُ"" : مَنْ دَقَّ خِصْرُهَا وَضَمُرَ بَطْنُهَا. ""هَيْفَاءُ مُقْبِلَةً عَجْزَاءُ مُدْبِرَةً"". (كعب بن زهير)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15620, 'هُيُولٌ', 'هيول', 'جامد', '', 'هيول', 'هل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": هَبَاءٌ مُنْبَثٌّ، وَهُوَ مَا تَرَاهُ فِي البَيْتِ مِنْ ضَوْءِ الشَّمْسِ يَدْخُلُ مِنَ الكُوَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15621, 'هُيُولَى', 'هيولى', 'جامد', '', 'هيولى', 'هل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R0', '', '', '', '', '', '', '"1. : مَادَّةٌ أُولَى يُصْنَعُ مِنْهَا الشَّيْءُ، فَالكُرْسِيُّ مَثَلاً مَادَّتُهُ الْخَشَبُ، وَالْمِفْتَاحُ مَادَّتُهُ الْحَدِيدُ. 2. : مَا كَانَ يُعْرَفُ قَدِيماً أَنَّ الهُيُولَى مَادَّةٌ لَيْسَ لَهَا شَكْلٌ وَلاَ صُورَةٌ مُعَيَّنَةٌ، قَابِلَةٌ لِتَتَّخِذَ مُخْتَلِفَ الأَشْكَالِ وَالصُّوَرِ. 3. : التَّخْطِيطُ الأَوَّلِيُّ لِلصُّورَةِ أَوِ التِّمْثَالِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15622, 'وَبَرٌ', 'وبر', 'جامد', 'وبر', 'وبر', 'بر', '', '', '', 'مفرد', 'DnN', '', '', '"أَوْبَارٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""وَبَرُ الجَمَلِ"" : شَعْرُهُ وَهُوَ بِمَثَابَةِ الصُّوفِ لِلْغَنَمِ. ""وَبَرُ الأَرَانِبِ"". 2.""أَهْلُ الوَبَرِ"" : البَدْوُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15623, 'أَوْبَارٌ', 'أوبار', 'جامد', '', 'ءوبار', 'بر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15624, 'وَبْرٌ', 'وبر', 'جامد', '', 'وبر', 'بر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"وُبُورٌ:وِبَارٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: وُبُورٌ، وِبَارٌ. (حو). : حَيَوَانٌ مِنْ ذَوَاتِ الْحَوَافِرِ، مِنْ رُتْبَةِ الخُرْطُومِيَّاتِ، فِي حَجْمِ الأَرْنَبِ، لَوْنُهُ بَيْنَ الغُبْرَةِ وَالسَّوَادِ، قَصِيرُ الذَّنَبِ، يَعِيشُ عَلَى النَّبَاتَاتِ، لَحْمُهُ لَذِيذٌ، وَفَرْوُهُ ثَمِينٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15625, 'وُبُورٌ', 'وبور', 'جامد', '', 'وبور', 'بر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15626, 'وِبَارٌ', 'وبار', 'جامد', '', 'وبار', 'بر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15627, 'مُوبِقَةٌ', 'موبقة', 'جامد', 'وبق', 'موبقة', 'مبقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". ""لاَ يَكُفُّ عَنِ ارْتِكَابِ الْمُوبِقَاتِ"" : الكَبَائِرُ مِنَ الْمَعَاصِي، الزَّلاَّتُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15628, 'أوْتَادٌ', 'أوتاد', 'جامد', 'وتد', 'ءوتاد', 'تد', '', '', '', 'مفرد', '', '', '', '"مفردوَتَد"', '', '', '', '', '', '', '', '', '". 1."" أوْتَادُ الأرْضِ"" : جِبَالُهَا.النبأ آية 7ألَمْ نَجْعَلِ الأرْضَ مِهَاداً وَالجِبالَ أوْتَاداً (قرآن). 2.""أوْتَادُ البِلاَدِ هُمْ حُكَمَاؤُهَا"" : رُؤَسَاؤُها. 3.""أوْتَادُ الفَمِ"" : أسْنَانُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15629, 'وَتَدٌ', 'وتد', 'جامد', 'وتد', 'وتد', 'تد', '', '', '', 'مفرد', 'DnN', '', '', '"أَوْتَادٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَوْتَادُ الخَيْمَةِ"" : مَا تُثَبَّتُ بِهِ الخَيْمَةُ فِي الأَرْضِ مِنْ خَشَبٍ أَوْ حَدِيدٍ وَنَحْوِهِمَا. 2.""أَوْتَادُ الأَرْضِ"" : جِبَالُهَا.النبأ آية 6 أَلَمْ نَجْعَلِ الأَرْضَ مِهَاداً وَالجِبَالَ أَوْتَاداً ( قرآن). 3.""أَوْتَادُ البِلاَدِ"" : رُؤَسَاؤُهَا. 4.""أَوْتَادُ الفَمِ"" : الأَسْنَانُ. 5.""الأَوْتَادُ فِي العَرُوضِ"" : مَا كَانَ مِنْ أَجْزَاءِ التَّفَاعِيلِ عَلَى ثَلاَثَةِ أَحْرُفٍ. وَهُوَ إِمَّا مَجْمُوعٌ، أَيْ عِبَارَةٌ عَنْ مُتَحَرِّكَيْنِ يَلِيهِمَا سَاكِنٌ: ""مَشَا""، ""لِمَنْ""، أَوْ مَفْرُوقٌ، أَيْ مُتَحَرِّكَانِ بَيْنَهُمَا سَاكِنٌ: ""كَيْفَ""، ""حَيْثُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15630, 'أَوْتَادٌ', 'أوتاد', 'جامد', '', 'ءوتاد', 'تد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15631, 'وَتَرٌ', 'وتر', 'جامد', 'وتر', 'وتر', 'تر', '', '', '', 'مفرد', 'DnN', '', '', '"أَوْتَارٌ:وِتَارٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَتَرُ القَوْسِ"" : مُعَلَّقُهُ. 2.""أَوْتَارُ العُودِ"" : خُيُوطُ العُودِ الَّتِي يُعْزَفُ عَلَيْهَا. 3.""ضَرَبَ عَلَى الوَتَرِ الْحَسَّاسِ"" : أَصَابَ الْمَكَانَ الْحَسَّاسَ. 4.""وَتَرُ الْمُثَلَّثِ"" : ضِلْعُ الْمُثَلَّثِ الْمُقَابِلُ لِلزَّاوِيَةِ القَائِمَةِ. 5.""وَتَرُ الدَّائِرَةِ"" : هُوَ قِطْعَةُ الْمُسْتَقِيمِ الوَاصِلَةُ بَيْنَ نُقْطَتَيْنِ مِنْ نُقَطِ الْمُحِيطِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15632, 'أَوْتَارٌ', 'أوتار', 'جامد', '', 'ءوتار', 'تر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15633, 'وِتَارٌ', 'وتار', 'جامد', '', 'وتار', 'تر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15634, 'وَتِيرَةٌ', 'وتيرة', 'جامد', 'وتر', 'وتيرة', 'ترة', '', '', '', 'مفرد', 'DnN', '', '', '"وَتَائِرُ"', '', '', '', '', '', '', '', '', '". 1.""وَتِيرَةُ قِمَّةِ الْجَبَلِ"" : الطَّرِيقُ الْمُحَاذِي لِلْجَبَلِ. 2.""وَتِيرَةُ الأُصْبُعَيْنِ"" : الفَرَاغُ بَيْنَ كُلِّ أُصْبُعَيْنِ. 3.""اِسْتَمَرَّ عَمَلُهُ عَلَى وَتِيرَةٍ وَاحِدَةٍ"" : عَلَى أُسْلُوبٍ مُطَّرِدٍ. 4.""مَا فِي عَمَلِهِ وَتِيرَةٌ"" : فُتُورٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15635, 'وَتَائِرُ', 'وتائر', 'جامد', '', 'وتاءر', 'تر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15636, 'وَثَائِقُ', 'وثائق', 'جامد', '', 'وثاءق', 'ثق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '"ن. وَثِيقَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15637, 'وَاحَةٌ', 'واحة', 'جامد', '', 'واحة', 'حة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. ""اِسْتَقَرَّتِ القَافِلَةُ فِي وَاحَةٍ مِنْ وَاحَاتِ الصَّحْرَاءِ"" : أَرْضٌ خَصِيبَةٌ فِي الصَّحْرَاءِ فِيهَا مَاءٌ وَشَجَرٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15638, 'وِثَارٌ', 'وثار', 'جامد', 'وثر', 'وثار', 'ثر', '', '', '', 'مفرد', 'DnN', '', '', '"أَوْثِرَةٌ"', '', 'R', '', '', '', '', '', '', '". 1.""نَامَ عَلَى وِثَارٍ"" : أَيْ فِرَاشٍ لَيِّنٍ. 2.""وِثَارُ السَّرِيرِ"" : مَا عَلَى السَّرِيرِ تَحْتَ الْمَرْتَبَةِ أَوِ الْحَشِيَّةِ لِيَحْمِلَهَا، وَهُوَ مِنَ الخَشَبِ أَوِ الْمَعْدِنِ، مُلَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15639, 'أَوْثِرَةٌ', 'أوثرة', 'جامد', '', 'ءوثرة', 'ثرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15640, 'وِثْرٌ', 'وثر', 'جامد', 'وثر', 'وثر', 'ثر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وِثْرٌ-وِثْرٌ [و ث ر]. 1.""وِثْرُ الثِّيَابِ"" : مَا تُغَطَّى بِهِ فَيَعْلُوهَا. 2.""فِرَاشٌ وِثْرٌ"" : وَطِئٌ. 3.""وِثْرُ السَّرْجِ"" : مَا يُجْعَلُ عَلَيْهِ كَالْمِخَدَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15641, 'مِيثَاقٌ', 'ميثاق', 'جامد', 'وثق', 'ميثاق', 'مثق', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَاثِيقُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِيثَاقُ الشَّرَفِ"" : العَهْدُ.الرعد آية 20 الَّذِينَ يُوفُونَ بِعَهْدِ اللهِ وَلاَ يَنْقُضُونَ الْمِيثَاقَ (قرآن). 2.""مِيثَاقُ الأُمَمِ الْمُتَّحِدَةِ"" : وَثِيقَةٌ سِيَاسِيَّةٌ تَتَضَمَّنُ مَبَادِئَ الأُمَمِ وَالقَوَاعِدِ الأَسَاسِيَّةِ الْمُتَّفَقِ عَلَيْهَا مِنْ أَجْلِ احْتِرَامِهَا فِي الْمُمَارَسَةِ. ""صادَقَتِ الأُمَمُ الْمُتَّحِدَةُ عَلَى مِيثَاقِ حُقُوقِ الإِنْسَانِ سنة 1949م""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15642, 'مَوَاثِيقُ', 'مواثيق', 'جامد', '', 'مواثيق', 'مثق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15643, 'وَثَاقٌ', 'وثاق', 'جامد', 'وثق', 'وثاق', 'ثق', '', '', '', 'مفرد', 'DnN', '', '', '"وُثُقٌ"', '', 'R', '', '', '', '', '', '', '". ""وِثَاقُ الأَسِيرِ"" : مَا يُشَدُّ بِهِ مِنْ حَبْلِ أَوْ قَيْدٍ وَنَحْوِهِمَا.محمد آية 4 حَتَّى إِذَا أَثْخَنْتُمُوهُمْ فَشُدُّوا الوَثَاقَ.( قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15644, 'وُثُقٌ', 'وثق', 'جامد', '', 'وثق', 'ثق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15645, 'وَثَلٌ', 'وثل', 'جامد', 'وثل', 'وثل', 'ثل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَثَلٌ-وَثَلٌ [و ث ل]. 1.""وَثَلُ اللِّيفِ"" : حَبْلُهُ. 2.""وَثَلُ الأَدِيمِ"" : وَسَخُهُ الَّذِي يُلْقَى مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15646, 'وَثَنٌ', 'وثن', 'جامد', 'وثن', 'وثن', 'ثن', '', '', '', 'مفرد', 'DnN', '', '', '"أَوْثَانٌ:وُثُنٌ"', '', 'Rp', '', '', '', '', '', '', '". ""يَعْبُدُ الوَثَنَ"" : الصَّنَمَ، أَي تِمْثَالٌ مَصْنُوعٌ مِنْ حَجَرٍ أو خَشَبٍ أو مَعْدِنٍ. ""كَانَ النَّاسُ قَبْلَ الْإِسْلاَمِ يَعْبُدُونَ الأَوْثَانَ"" ""جَاءَ الإسْلامُ وانتَهَى عَهْدُ الوَثَنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15647, 'أَوْثَانٌ', 'أوثان', 'جامد', '', 'ءوثان', 'ثن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15648, 'وُثُنٌ', 'وثن', 'جامد', '', 'وثن', 'ثن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15649, 'وَجَارٌ', 'وجار', 'جامد', '', 'وجار', 'جر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"1.""وِجَارُ الضَّبُعِ"" : جُحْرُهُ. 2.""تَرَكَ السَّيْلُ وِجَاراً"" : حُفْرَةً يَتْرُكُهَا فِي جَانِبِ الوَادِي."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15650, 'وَجَبٌ', 'وجب', 'جامد', 'وجب', 'وجب', 'جب', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَجَبٌ-وَجَبٌ [و ج ب]. ""غَلَبَهُ عَلَى الوَجَبِ"" : أَيِ الخَطَر، أَي السَّبْق الَّذِي يُنَاضَلُ عَلَيْهِ؛ فَمَنْ سَبَقَ أَخَذَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15651, 'وَجِيبَةٌ', 'وجيبة', 'جامد', 'وجب', 'وجيبة', 'جبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"وَجِيبَةٌ-وَجِيبَةٌ [و ج ب]. 1.""أَدَّى وَجِيبَتَهُ"" : وَظِيفَتَهُ. 2.""طَالَبَ بِوَجِيبَتِهِ"" : أَيْ مَا يُقَدَّرُ مِنْ أَجْرٍ أَوْ طَعَامٍ أَوْ رِزْقٍ فِي مُدَّةٍ مُعَيَّنَةٍ. 3.""اِسْتَوْفَيْتَ وَجِيبَتَكَ"" : أَنْ تُوجِبَ البَيْعَ ثُمَّ تَأْخُذَهُ أَوَّلاً فَأَوَّلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15652, 'وَجُورٌ', 'وجور', 'جامد', 'وجر', 'وجور', 'جر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَجُورٌ-وَجُورٌ [و ج ر]. ""صَبَّ الوَجُورَ فِي حَلْقِهِ"" : الدَّوَاءَ الَّذِي يُصَبُّ فِي الفَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15653, 'وَجْرٌ', 'وجر', 'جامد', '', 'وجر', 'جر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَوْجَارٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: أَوْجَارٌ. ""وَجْرُ الْحَيَوَانِ"" : الْمَغَارَةُ الَّتِي يَأْوِي إِلَيْها فِي الْجَبَلِ. ""اِخْتَفَى الْحَيَوَانُ فِي الوَجْرِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15654, 'أَوْجَارٌ', 'أوجار', 'جامد', '', 'ءوجار', 'جر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15655, 'وَجِينٌ', 'وجين', 'جامد', 'وجن', 'وجين', 'جن', '', '', '', 'مفرد', 'DnN', '', '', '"وُجْنٌ:وُجُنٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَجِينُ الوَادِي"": شَطُّهُ. 2.""مَكَانٌ وَجِينٌ"" : صَلْبٌ ذُو حِجَارَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15656, 'وُجْنٌ', 'وجن', 'جامد', '', 'وجن', 'جن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15657, 'وُجُنٌ', 'وجن', 'جامد', '', 'وجن', 'جن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15658, 'وَجْنَةٌ', 'وجنة', 'جامد', '', 'وجنة', 'جنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ج: وَجَنَات. ""عَلَتِ الْحُمْرَةُ وَجْنَتَهُ"" : مَا ارْتَفَعَ مِنَ الْخَدَّيْنِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15659, 'تَوْجِيهِيَّةٌ', 'توجيهية', 'جامد', 'وجه', 'توجيهية', 'تجهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَّوْجِيهِيَّةُ-التَّوْجِيهِيَّةُ [و ج هـ]. ""حَصَّلَ الطَّالِبُ عَلَى شَهَادَةِ التَّوْحِيهِيَّةِ"": شَهَادَةُ الدِّرَاسَةِ الثَّانَوِيَّةِ النِّهَائِيَّةِ فِي بَعْضِ الأَقْطَارِ العَرَبِيَّةِ، أَيْ مَا يُعْرَفُ بِشَهَادَةِ البَكَالُوريا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15660, 'جِهَةٌ', 'جهة', 'جامد', 'وجه', 'جهة', 'جهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""بَحَثْتُ عَنْهُ فِي كُلِّ جِهَةٍ"" : فِي كُلِّ نَاحِيَةٍ، جَانِبٍ. ""جَاءتِ الوُفُودُ مِنْ كُلِّ جِهَةٍ"" ""لَمْ يَتْرُكْ جِهَةً مِنَ الجِهَاتِ"". 2.""يَتَنَقَّلُ مِنْ جِهَةٍ إِلَى أُخْرَى"" : مِنْ مَكَانٍ إِلَى آخَرَ. 3.""هَذِهِ هَدِيَّةٌ مِنْ جِهَتِي"" : مِنْ طَرَفِي. 4.""الجِهَاتُ الأَرْبَعُ الأَصْلِيَّةُ"" (جغ) : الشَّمَالُ وَالشَّرْقُ وَالجَنُوبُ وَالغَرْبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15661, 'وَاجِهَةٌ', 'واجهة', 'جامد', 'وجه', 'واجهة', 'جهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1. ""وَاجِهَةُ الْمَتْجَرِ"" : ظَاهِرُهُ الْخَارِجِيُّ، أَيْ مَا يَسْتَقْبِلُكَ مِنَ الشَّيْءِ. ""كَانَ زُجَاجُ الوَاجِهَةِ نَظِيفاً"" ""وَاجِهَةُ العِمَارَةِ"". 2.""وَاجِهَةُ الجَيْشِ"": الْجَبْهَةُ الأَمَامِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15662, 'وُحْدَانٌ', 'وحدان', 'جامد', 'وحد', 'وحدان', 'حدن', '', '', '', 'مفرد', '', '', '', '"مفردالوَاحِد"', '', '', '', 'N', 'N', 'N', 'N', '', '". ""جَاءوا زَرَافَاتٍ وَوُحْدَاناً "" : فَرْداً فَرْداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15663, 'وِجْهَةٌ', 'وجهة', 'جامد', 'وجه', 'وجهة', 'جهة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"وِجْهَةٌ-وِجْهَةٌ، وُجْهَةٌ [و ج هـ]. 1.""سَارَ فِي وِجْهَةٍ سَلِيمَـةٍ"" : فِي اتِّجَاهٍ. 2.""مِنَ الوِجْهَةِ العَمَلِيَّةِ"" : مِنَ النَّاحِيَةِ، مِنَ الْجَانِبِ. ""مِنَ الوِجْهَةِ التَّرْبَوِيَّةِ"" ""مِنَ الوِجْهَةِ الإِنْسَانِيَّةِ"". 3.""كَانَتْ وِجْهَتُهُ العَاصِمَةَ"" : الْمَوْضِعُ الَّذِي يَقْصِدُ هُوَ العَاصِمَةُ. ""ضَلَّ وِجْهَتَهُ"" : هَدَفَهُ، قَصْدَهُ. 4. ""قَدَّمَ كُلٌّ مِنْهُمَا وِجْهَةَ نَظَرِهِ"" : رَأْيَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15664, 'أُحَادٌ', 'أحاد', 'جامد', 'وحد،أحد', 'ءحاد', 'حد', '', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', 'N', 'O', 'N', 'O', '', '"أُحَادٌ-أُحَادٌ [و ح د ، أ ح د]. ""جَاءَ القَوْمُ أُحَادَ"" : جَاءُوا وَاحِدًا وَاحِدًا. ""وَصَلَ الأَطْفَالُ أُحَادَ أُحَادَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15665, 'وَحَرَةٌ', 'وحرة', 'جامد', 'وحر', 'وحرة', 'حرة', '', '', '', 'مفرد', 'DnN', '', '', '"وَحَرٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1. (حو): دَابَّةٌ صَغِيرَةٌ، أَصْغَرُ مِنَ العظَاءةِ، بَيْضَاءُ مُنَقَّطَةٌ بِحُمْرَةٍ، عَلَى شَكْلِ سامٍّ أَبْرَصَ، لَهَا ذَنَبٌ دَقِيقٌ تَضْرِبُ بِهِ، تَسُمُّ الطَّعَامَ أَوِ الشَّرَابَ إِذَا وَطَأَتْهُ. 2.""اِمْرَأَةٌ وَحَرَةٌ"" : ذَمِيمَةٌ، قَبِيحَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15666, 'وَحَرٌ', 'وحر', 'جامد', '', 'وحر', 'حر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15667, 'وَحْرٌ', 'وحر', 'جامد', '', 'وحر', 'حر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ن. وَحَرٌ.وَحَرٌ - [و ح ر]. (مص. وَحِرَ). 1.""اِشْتَدَّ بِهِ الوَحَرُ"" : الحِقْدُ، الغَيْظُ، أَوِ الغَضَبُ الشَّدِيدُ. 2. ""اِسْتَمَرَّ وَحَرُهُمَا زَمَناً طَوِيلاً"" : عَدَاوَتُهُمَا. 3.""اِسْتَسْلَمَ لِوَحَرِهِ"" : وَسَاوِسُ الصَّدْرِ وَهَواجِسُهُ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15668, 'وَحْشٌ', 'وحش', 'جامد', 'وحش', 'وحش', 'حش', '', '', '', 'مفرد', 'DnN', '', '', '"وُحُوشٌمفردوَحْشِيّ"', '', 'Rp', '', '', '', '', '', '', '". 1.""حَيَوَانٌ وَحْشٌ"" : حَيَوَانُ البَرِّ، مَا لاَ يُسْتَأْنَسُ. ""وُحُوشٌ ضَارِيَةٌ"". 2.""حِمَارُ الوَحْشِ"". ""حِمَارٌ وَحْشِيٌّ"" : الحِمَارُ الْمُخَطَّطُ، حِمَارُ الزَّرَدِ. 3.""بَقَرُ الوَحْشِ"" : خِلاَفُ البَقَرِ الأَهْلِيَّةِ. 4.""مَكَانٌ وَحْشٌ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15669, 'وُحُوشٌ', 'وحوش', 'جامد', '', 'وحوش', 'حش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15670, 'وَحْشِيٌّ', 'وحشي', 'جامد', 'وحش', 'وحشي', 'حش', '', '', '', 'مفرد', 'DnN', '', '', '"واحدةالوَحْشِ"', '', '', '', '', '', '', '', '', '"وَحْشِيٌّ-وَحْشِيٌّ [و ح ش] (واحد الوَحْشِ). 1.""وَحْشِيُّ الرِّجْلِ"" : أَخْمَصُهَا، أَسْفَلُهَا. 2.""وَحْشِيُّ اليَدِ"" : ظَاهِر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15671, 'وَحِيشٌ', 'وحيش', 'جامد', 'وحش', 'وحيش', 'حش', '', '', '', 'مفرد', 'DnN', '', '', '"وُحْشَانٌ"', '', 'R', '', '', '', '', '', '', '". 1.""حَيَوَانٌ وَحِيشٌ"" : حَيَوَانُ البَرِّ الَّذِي لاَ يُسْتَأْنَسُ بِهِ. 2.""الجَانِبُ الوَحِيشُ"" : الأَيْمَنُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15672, 'وُحْشَانٌ', 'وحشان', 'جامد', '', 'وحشان', 'حشن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15673, 'مَوْحِلٌ', 'موحل', 'جامد', 'وحل', 'موحل', 'محل', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَاحِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""غَاصَ فِي الْمَوْحِلِ"": مَوْضِعُ الوَحَلِ، ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15674, 'مَوَاحِلُ', 'مواحل', 'جامد', '', 'مواحل', 'محل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
