INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15680, 'وَخَمٌ', 'وخم', 'جامد', 'وخم', 'وخم', 'خم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَخَمٌ-وَخَمٌ [و خ م] (طب). : دَاءٌ نَاتِجٌ عَنْ ت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15681, 'وَخَى', 'وخى', 'جامد', 'وخي', 'وخى', 'خ', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"وَخَى-وَخَى [و خ ي]. ""عَرَفْتُ وَخَاهُ"" : قَصْدَهُ، جِهَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15682, 'وِدَادِيَّةٌ', 'ودادية', 'جامد', 'ودد', 'ودادية', 'ددة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""وِدَادِيَّةُ العُمَّالِ"" : جَمْعِيَّةُ العُمَّالِ القَائِمَةُ عَلَى الوَدِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15683, 'دَعَةٌ', 'دعة', 'جامد', 'ودع', 'دعة', 'دعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"دَعَةٌ-دَعَةٌ [و د ع]. ""يَعِيشُ فِي دَعَةٍ"" : فِي رَغْدِ عَيْشٍ، رَاحَةٍ، سَكِينَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15684, 'مِيدَاعَةٌ', 'ميداعة', 'جامد', 'ودع', 'ميداعة', 'مدعة', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَادِعُ"', '', 'R', '', '', '', '', '', '', '". ""مِيدَاعَةُ الطَّبِيبِ أَوِ الصَّيْدَلِيِّ أَوِ الأُسْتَاذِ"" : الثَّوْبُ الْمُبْتَذَلُ، لِبَاسٌ يُلْبَسُ أَثْنَاءَ مُزَاوَلَةِ العَمَلِ وِقَايَةً مِنَ الوَسَخِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15685, 'مَوَادِعُ', 'موادع', 'جامد', '', 'موادع', 'مدع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15686, 'وَدْعٌ', 'ودع', 'جامد', 'ودع', 'ودع', 'دع', '', '', '', 'مفرد', 'DnN', '', '', '"وُدُوعٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَدْعُ الْمَيِّتِ"" : قَبْرُهُ. 2.""هَذَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15687, 'وُدُوعٌ', 'ودوع', 'جامد', '', 'ودوع', 'دع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15688, 'وَدَعٌ', 'ودع', 'جامد', 'ودع', 'ودع', 'دع', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"وَدَعٌ-وَدَعٌ، ةٌ [و د ع]. ""وَدَعُ البَحْرِ"" : مَحَارَةٌ، صَدَفَةٌ أَحْجَامُهَا مُتَفَاوِتَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15689, 'وَدِيعَةٌ', 'وديعة', 'جامد', 'ودع', 'وديعة', 'دعة', '', '', '', 'مفرد', 'DnN', '', '', '"وَدَائِعُ"', '', '', '', '', '', '', '', '', '". 1.""تَرَكَ عِنْدَهُ وَدِيعَةً"" : مَا يُودَعُ أَمَانَةً. 2.""وَدَائِعُ مَصْرِفِيَّةٌ"" : أَيْ مَا يُودَعُ مِنْ حِلِيٍّ وَوَثَائِقَ فِي الْمَصْرِفِ لِيُحْتَفَظَ بِهِ زَمَناً. 3.""سَقَطَتِ الوَدَائِعُ"" : الأَمْطَارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15690, 'وَدَائِعُ', 'ودائع', 'جامد', '', 'وداءع', 'دع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15691, 'وَدْفَةٌ', 'ودفة', 'جامد', 'ودف', 'ودفة', 'دفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"وَدْفَةٌ-وَدْفَةٌ [و د ف]. 1.""أَذَابَ الوَدْفَةَ"" : الشَّحْمَةَ. 2.""وَدْفَةُ الدَّارَةِ"" : الرَّوْضَةُ الخَضْرَاءُ الْمُحِيطَةُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15692, 'وَدْهَاءُ', 'ودهاء', 'جامد', 'وده', 'ودهاء', 'ده', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"وَدْهَاءُ-وَدْهَاءُ [و د هـ]. ""اِمْرَأَةٌ وَدْهَاءُ"" : بَيْضَاءُ اللَّوْنِ حَسْنَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15693, 'وَذْمَاءُ', 'وذماء', 'جامد', 'وذم', 'وذماء', 'ذم', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"وَذْمَاءُ-وَذْمَاءُ [و ذ م]. ""اِمْرَأَةٌ وَذْمَاءُ"" : عَاقِرٌ. ""فَرَسٌ وَذْمَاءُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15694, 'وَذِيمَةٌ', 'وذيمة', 'جامد', 'وذم', 'وذيمة', 'ذمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"وَذِيمَةٌ-وَذِيمَةٌ [و ذ م]. ""وَذِيمَةُ الكَلْبِ"" : القِلاَدَةُ الَّتِي تُوضَعُ فِي عُنُقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15695, 'وَرْبَةٌ', 'وربة', 'جامد', 'ورب', 'وربة', 'ربة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"وَرْبَةٌ-وَرْبَةٌ [و ر ب]. ""وَرْبَةُ الإِنْسَانِ"" : خَاصِرَتُهُ، أَيِ الْحُفْرَةُ فِي أَسْفَلِ الجَنْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15696, 'وَرْبٌ', 'ورب', 'جامد', 'ورب', 'ورب', 'رب', '', '', '', 'مفرد', 'DnN', '', '', '"أَوْرَابٌ"', '', 'R', '', '', '', '', '', '', '". 1.""عَاثَ فِي البِلاَدِ وَرْبـاً"" : فَسَاداً. 2.""وَرْبُ الوَحْشِ"" : جُحْرُهُ، وِجَارُهُ. 3.""وَرْبُ جُحْرِ العَقْرَبِ"" : مَدْخَلُهُ، فَمُهُ. ""جَمَدَ الْجُرَذُ فِي وَرْبِهِ يَسْتَرِقُ السَّمْعَ وَيَتَأَهَّبُ لِيَعِيثَ فِي الْحُقُولِ فَسَاداً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15697, 'أَوْرَابٌ', 'أوراب', 'جامد', '', 'ءوراب', 'رب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15698, 'تُرَاثٌ', 'تراث', 'جامد', 'ورث', 'تراث', 'ترث', '', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"تُرَاثٌ-تُرَاثٌ [و ر ث]. 1.""تَرَكَ تُرَاثاً هَائِلاً"" : إِرْثاً. 2.""تُرَاثُ الأُمَّةِ"" : مَا لَهُ قِيمَةٌ بَاقِيَةٌ مِنْ عَادَاتٍ وَآدَابٍ وَعُلُومٍ وَفُنُونٍ ويَنْتَقِلُ مِنْ جِيلٍ إِلَى جِيلٍ. ""التُّرَاثُ الإنْسَانِيُّ"" ""التُّرَاثُ الإِسْلاَمِيُّ"" ""التُّرَاثُ الأَدَبِيُّ"" ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15699, 'مِيرَاثٌ', 'ميراث', 'جامد', 'ورث', 'ميراث', 'مرث', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَارِيثُ"', '', 'R', '', '', '', '', '', '', '". 1.""تَرَكَ مِيرَاثاً لِأَبْنَائِهِ"": تَرِكَةُ الْمَيِّتِ، أَيْ مَا خَلَّفَهُ مِنْ أَثَاثٍ وَأَمْوَالٍ وَعَقَارٍ. 2.""عِلْمُ الْمِيرَاثِ"" : عِلْمُ الفَرَائِضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15700, 'مَوَارِيثُ', 'مواريث', 'جامد', '', 'مواريث', 'مرث', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15701, 'مَوْرِدٌ', 'مورد', 'جامد', 'ورد', 'مورد', 'مرد', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَارِدُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَوْرِدُ الجَمَاعَةِ"" : مَكَانُ الْمَاءِ. 2.""وَأَخِيراً عَرَفَ العَطْشَانُ مَوْرِدَهُ"" : الطَّرِيقَ إِلَى الْمَاءِ. 3.""مَوْرِدُ الرِّزْقِ"" : مَصْدَرُهُ. 4.""تَبْحَثُ الدَّوْلَةُ عَنْ مَوَارِدَ جَدِيدَةٍ"" : عَنْ مَدَاخِيلَ جَدِيدَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15702, 'مَوَارِدُ', 'موارد', 'جامد', '', 'موارد', 'مرد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15703, 'وَرْدٌ', 'ورد', 'جامد', 'ورد', 'ورد', 'رد', '', '', '', 'مفرد', 'DnN', '', '', '"وُرُودٌ"', '', 'R', '', '', '', '', '', '', '"(نب).1. : نَبَاتٌ مِنْ فَصِيلَةِ الوَرْدِيَّاتِ، وَ هُوَ شَائِكٌ مُعَمِّرٌ، ذُو أَلْوَانٍ مُخْتَلِفَةٍ وَ رَائِحَةٍ عَطِرَةٍ، يُسْتَخْرَجُ مِنْهُ العِطْرُ 2.""مَاءُ الوَرْدِ"" : عِطْرُهُ. 3.""فِي عُمُرِ الوَرْدِ"" : فِي نَضَارَةِ الشَّبَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15704, 'وُرُودٌ', 'ورود', 'جامد', '', 'ورود', 'رد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15705, 'وِرْدٌ', 'ورد', 'جامد', 'ورد', 'ورد', 'رد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وِرْدٌ-وِرْدٌ [و ر د]. 1.""شَرِبَ وِرْدَهُ"" : الْمَاءَ الَّذِي يُورَدُ، النَّصِيبَ مِنْهُ. 2. ""أُصِيبَ بِالوِرْدِ"" : بِالْحُمَّى. 3.""قِرَاءةُ الوِرْدِ"": جُزْءٌ مِنَ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15706, 'وَرْدِيَّاتٌ', 'ورديات', 'جامد', 'ورد', 'ورديات', 'ردت', '', '', '', 'مفرد', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"وَرْدِيَّاتٌ-وَرْدِيَّاتٌ [و ر د] (نب). : فَصِيلَةٌ نَبَاتِيَّةٌ، مِنْ ذَوَاتِ الفِلْقَتَيْنِ وَالأَوْرَاقِ الْمُسَنَّنَةِ، عَدِيدَةُ الأَنْوَاعِ، وَأَغْلَبُهَا مِنَ الأَشْجَارِ الْمُثْمِرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15707, 'وَرْدِيَّةٌ', 'وردية', 'جامد', '', 'وردية', 'ردة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '": صَلاَةٌ عِنْدَ الْمَسِيحِيِّينَ تُقَامُ لِلسَّيِّدَةِ العَذْرَاءِ فِي الأَحَدِ الأَوَّلِ مِنْ كُلِّ شَهْرٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15708, 'وَرْسٌ', 'ورس', 'جامد', '', 'ورس', 'رس', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَرْسٌ-وَرْسٌ (نب). : نَبَاتٌ مِنْ فَصِيلَةِ القَرْنِيَّاتِ، يُشْبِهُ السِّمْسِمَ، لِثَمَرَتِهِ قَرْنٌ يُغَطَّى عِنْدَ نُضْجِهِ بِغُدَدٍ حَمْرَاءَ، يُحِيطُ بِهِ زَغَبٌ خَفِيفٌ يُسْتَعْمَلُ فِي ص"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15709, 'وَرْشٌ', 'ورش', 'جامد', '', 'ورش', 'رش', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَرْشٌ-وَرْشٌ (طخ). 1. : طَعَامٌ يُصْنَعُ مِنَ اللَّبَنِ. 2.""قِرَاءةُ وَرْشٍ"" : قِرَاءةٌ مَنْسُوبَةٌ إِلَى عُثْمَانَ بْنِ سَعْدٍ القَارِئِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15710, 'وَرْشَةٌ', 'ورشة', 'جامد', '', 'ورشة', 'رشة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ج: ـات. 1.""يَشْتَغِلُونَ فِي الوَرْشَةِ"" : الْمَكَانُ الْمُعَدُّ لِلْعَمَلِ اليَدَوِيِّ وَالأَعَمَالِ التَّطْبِيقِيَّةِ وَ إِصْلاَحِ الْمُعِدَّاتِ. 2.""يُشْرِفُ "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15711, 'وَرْطَةٌ', 'ورطة', 'جامد', 'ورط', 'ورطة', 'رطة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""وَحَلَ فِي وَرْطَةٍ"" : فِي وَحَلٍ يَصْعُبُ التَّخَلُّصُ مِنْهُ. 2.""وَقَعَ فِي وَرْطَةٍ"" : ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15712, 'وَرَّاقَةٌ', 'وراقة', 'جامد', 'ورق', 'وراقة', 'رقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَرَّاقَةٌ-وَرَّاقَةٌ [و ر ق]. : مَصْنَعُ الوَرَقِ أَوْ مَكَانُ بَيْعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15713, 'وِرَاقَةٌ', 'وراقة', 'جامد', 'ورق', 'وراقة', 'رقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"وِرَاقَةٌ-وِرَاقَةٌ [و ر ق]. : حِرْفَةُ الوَرَّاقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15714, 'وَرَاقٌ', 'وراق', 'جامد', 'ورق', 'وراق', 'رق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وِرَاقٌ-وِرَاقٌ [و ر ق]. ""وِرَاقُ الشّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15715, 'وِرَاقٌ', 'وراق', 'جامد', 'ورق', 'وراق', 'رق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَرَاقٌ-وَرَاقٌ[و ر ق]. 1.""وَرَاقُ الأَرْضِ"": خُضْرَتُهَا مِنَ الرَّبِيعِ وَالْحَشِيشِ وَلَيْسَ مِنَ الوَرَقِ. 2.""مَا أَحْسَنَ وَرَاقَهُ"" : لِبْسَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15716, 'وَرَقَةٌ', 'ورقة', 'جامد', 'ورق', 'ورقة', 'رقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""وَرَقَةُ شَجَرَةٍ"" : مَا يَظْهَرُ عَلَى الغُصْنِ أَوْ سَاقِ النَّبَاتِ صَفِيحَـةً دَقِيقَـةً نَاعِمَةً، خَضْرَاءَ اللَّوْنِ فِي الغَالِبِ، وَهِيَ مُكَوَّنَةٌ مِنْ ثَلاَثَةِ أَشْيَاءَ : القَاعِدَةُ وَالعُنُـقُ وَالنَّصْلُ (الصَّفِيحَةُ)، وَمِنْهَا مَا يَكُونُ عَادِياً، يَتَكَوَّنُ نَصْلُهَا مِنْ أَصْلِهَا. وَهِيَ مُتَعَدِّدَةُ الأَحْجَامِ وَالأَشْكَالِ. 2.""وَرَقَةُ دَفْتَرٍ"" : صَفِيحَةُ دَفْتَرٍ يُكْتَبُ أَوْ يُرْس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15717, 'وُرْقَةٌ', 'ورقة', 'جامد', 'ورق', 'ورقة', 'رقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"وُرْقَةٌ-وُرْقَةٌ [و ر ق]. 1.""وُرْقَةُ الْجِلْدِ"" : سُمْرَتُهُ. 2.""وُرْقَةُ البَهَائِمِ"" : سَوَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15718, 'وَرَقٌ', 'ورق', 'جامد', 'ورق', 'ورق', 'رق', '', '', '', 'مفرد', 'DnN', '', '', '"أَوْرَاقٌ"', '', 'R', '', '', '', '', '', '', '". 1.""وَرَقُ الشَّجَرِ"" : مَا يَظْهَرُ عَلَى فُرُوعِ الأَغْصَانِ أَوْ سِيقَانِ النَّبَاتِ صَفَائِحَ رَقِيقَةً نَاعِمَةً خَضْرَاءَ اللَّوْنِ فِي الغَالِبِ. ""شَجَرَةٌ عَظِيمَةٌ كَثِيرَةُ الغُصُونِ مُلْتَفَّةُ الوَرَقِ"". 2.""الوَرَقُ"" : صَفَائِحُ رَقِيقَةٌ مُخْتَلِفَةُ الأَحْجَامِ يُكْتَبُ أَوْ يُرْسَمُ أَوْ يُطْبَعُ عَلَيْهَا. ""وَرَقٌ لِلْكِتَابَةِ"" ""وَرَقُ الكِتَابِ"" ""وَرَقُ الدَّفْتَرِ"" ""وَرَقُ الصُّحُفِ"" ""الوَرَقُ الْمُقَوَّى"". 3.""الأَوْرَاقُ النَّقْدِيَّةُ"" : العُمْلَةُ مِنَ النُّقُودِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15719, 'أَوْرَاقٌ', 'أوراق', 'جامد', '', 'ءوراق', 'رق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15720, 'وَرْكَاءُ', 'وركاء', 'جامد', 'ورك', 'وركاء', 'رك', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"وَرْكَاءُ-وَرْكَاءُ [و ر ك]. ""اِمْرَأَةٌ وَرْكَاءُ"" : عَظِيمَةُ الوَرِكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15721, 'وَرِكٌ', 'ورك', 'جامد', '', 'ورك', 'رك', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَوْرَاكٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَوْرَاكٌ. ""وَرِكُ الرَّجُلِ"" : مَا فَوْقَ الفَخِذِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15722, 'أَوْرَاكٌ', 'أوراك', 'جامد', '', 'ءوراك', 'رك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15723, 'وَرَلٌ', 'ورل', 'جامد', '', 'ورل', 'رل', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَوْرَالٌ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: أَوْرَالٌ. (حو). : حَيَوَانٌ مِنْ فَصِيلَةِ الوَرَلِيَّاتِ، مِنْ رُتْبَةِالْحَرْشَفِيَّاتِ الزَّحَّافَاتِ، لَهُ لِسَانٌ مَشْقُوقُ الْمُقَدِّمَةِ، طَوِيلُ الذَّنَبِ وَالأَنْفِ، جِسْمُهُ يَحْمِلُ حَرَاشِفَ، يُغَيِّرُ لَوْنَ جِسْمِهِ مِنْ حِينٍ لآخَرَ، يَعِيشُ عَلَى الْحَشَرَاتِ وَالثِّمَارِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15724, 'أَوْرَالٌ', 'أورال', 'جامد', '', 'ءورال', 'رل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15725, 'وَرَلَةٌ', 'ورلة', 'جامد', '', 'ورلة', 'رلة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"أُنْثَىالوَرَلِ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"وَرَلَةٌ-وَرَلَةٌ (حو). : أُنْثَى الوَرَلِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15726, 'وَرَلِيَّاتٌ', 'ورليات', 'جامد', '', 'ورليات', 'رلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ حَيَوَانِيَّةٌ مِنَ الزَّحَّافَّاتِ، مِنْ رُتْبَةِ الْحَرْشَفِيَّاتِ الْمَشْقُوقَاتِ اللِّسَانِ، مِنْ أَشْهَرِ أَنْوَاعِهَا العَدِيدَةِ الوَرَلُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15727, 'وَرْهَاءُ', 'ورهاء', 'جامد', 'وره', 'ورهاء', 'ره', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"وَرْهَاءُ-وَرْهَاءُ [و ر هـ]. ""اِمْرَأَةٌ وَرْهَاءُ اليَدَيْنِ"" : خَرْقَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15728, 'وَرْوَارٌ', 'وروار', 'جامد', '', 'وروار', 'رر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَرْوَارٌ-وَرْوَارٌ (حو). : طَائِرٌ طَوِيلُ الْمِنْقَارِ، قَصِيرُ الرِّجْلَيْنِ، زَاهِي الأَلْوَانِ، فِي وَسَطِ ذَنَبِهِ رِيشَتَانِ طَوِيلَتَانِ، يَقْطُنُ فِي البِلاَدِ الْحَارَّةِ وَيَقْتَاتُ بِالنَّحْلِ وَالزَّنَابِيرِ، وَهُوَ مَا يُعْرَفُ أَيْضاً بِالْخُضَّارِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15729, 'وَرَى', 'ورى', 'جامد', 'وري', 'ورى', 'ر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"وَرَى-وَرَى [و ر ي]. ""النَّبِيُّ سَيِّدُ الوَرَى"" : سَيِّدُ الْخَلْقِ، البَشَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15730, 'وَرِيدٌ', 'وريد', 'جامد', '', 'وريد', 'رد', '', '', '', 'جمع تكسير', 'DnN', '', '', '"أَوْرِدَةٌ:وُرُودٌمثنَّـىوَرِ', '', 'R', '', '', '', '', '', '', '"مثنَّـى : وَرِيدَانِ. ج: أَوْرِدَةٌ، وُرُودٌ. 1.""أَوْرِدَةُ القَلْبِ"" : العُرُوقُ الَّتِي تَحْمِلُ الدَّمَ الأَزْرَقَ مِنَ الْجَسَدِ إِلَى القَلْبِ. 2.""حَبْلُ الوَرِيدِ"" : العِرْقُ الكَامِنُ فِي العُنُقِ.ق آية 16وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ الوَرِيدِ ( قرآن). 3.""كَانَ مُنْتَفِخَ الوَرِيدِ"" : غَضْبَانَ."', ':لا جذر:لا مفرد');
