INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15739, 'وَزِيرٌ', 'وزير', 'جامد', 'وزر', 'وزير', 'زر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":وُزَرَاءُ"', '', 'R', '', '', '', '', '', '', '". 1.""كَانَ وَزِيراً لَهُ"" : أَيْ مُؤَازِراً، مُؤَازِراً وَمُعِيناً. طه آية 29 وَاجْعَلْ لِي وَزِيراً مِنْ أَهْلِي ( قرآن). 2.""وَزِيرٌ في الْحُكُومَةِ"" : شَخْصِيَّةٌ سِيَاسِيَّةٌ تَتَحَمَّلُ مَسْؤُولِيَّةً وَمُهِمَّةً فِي مَجَالٍ مِنَ الْمَجَ"', '');
