INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15755, 'وُسُوطٌ', 'وسوط', 'جامد', 'وسط', 'وسوط', 'سط', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"وُسُوطٌ-وُسُوطٌ [و س ط]. ""وُسُوطُ الشَّمْسِ"" : تَوَسُّطُهَا السَّمَاءَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15756, 'مَوْسُوعَةٌ', 'موسوعة', 'جامد', 'وسع', 'موسوعة', 'مسعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '". : مُعْجَمٌ ضَخْمٌ يَضُمُّ مَعْلُومَاتٍ وَافِيَةً ومُرَكَّزَةً عَنِ الْمَعَارِفِ الإِنْسَانِيَّةِ مُرَتَّبَةً تَرْتِيباً أَبَجَدِيّاً أَوْ حَسَبَ الْمَوَاضِيعِ، وكُلُّ مَوْسُوعَةٍ تَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15757, 'وُسْعٌ', 'وسع', 'جامد', 'وسع', 'وسع', 'سع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وُسْعٌ-وُسْعٌ [و س ع]. ""فِي وُسْعِهِ أَنْ يَتَحَمَّلَ كُلَّ أَعْبَاءِ السَّفَرِ"" : فِي طَاقَتِهِ.البقرة آية 286 لاَ يُكَلِّفُ اللَّهُ نَفْساً إِلاَّ وُسْعَهَا ( قرآن). ""بَذَلَ فِي ذَلِكَ وُسْعَهُ"" ""اِرْتَكَبَ خَطَأً مَا كَانَ فِي وُسْعِهِ أَنْ يَتَحَاشَاهُ"". (ع. العروي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15758, 'وَسِيلَةٌ', 'وسيلة', 'جامد', 'وسل', 'وسيلة', 'سلة', '', '', '', 'مفرد', 'DnN', '', '', '"وَسَائِلُ"', '', '', '', '', '', '', '', '', '". 1.""يَبْحَثُ عَنْ وَسِيلَةٍ لِتَحْقِيقِ هَدَفِهِ"" : الأَدَاةُ، الأُسْلُوبُ، الطَّرِيقَةُ الَّتِي يَتَحَقَّقُ بِهَا غَرَضٌ مُحَدَّدٌ. ""هَلِ الغَايَةُ تُبَرِّرُ الوَسِيلَةَ"". 2.""وَسَائِلُ النَّقْـلِ"" : كُلَّ مَا يُرْكَبُ مِنْ بَه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15759, 'وَسَائِلُ', 'وسائل', 'جامد', '', 'وساءل', 'سل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15760, 'مَوْسِمٌ', 'موسم', 'جامد', 'وسم', 'موسم', 'مسم', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَاسِمُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَوْسِمُ الْحَجِّ"" : مَجْمَعُ الْحَجِّ. 2.""مَوْسِمُ الوَلِيِّ الصَّالِحِ"" : اِحْتِفَالٌ يَقَعُ مَرَّة"', '');
