INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15766, 'وَسْمَةٌ', 'وسمة', 'جامد', 'وسم', 'وسمة', 'سمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"وَسْمَةٌ-وَسْمَةٌ، وَسِمَةٌ [و س م] (نب). : جِنْسُ نَبَاتٍ عُشْبِيٍّ، مِنْ فَصِيلَةِ الصَّلِيبِيَّاتِ، أَنْوَاعُهُ عَدِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15767, 'وَسْنَةٌ', 'وسنة', 'جامد', 'وسن', 'وسنة', 'سنة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"وَسْنَةٌ-وَسْنَةٌ [و س ن]. ""أَخَذَتْهُ وَسْنَةٌ"" : سِنَةٌ، الغَفْوَةُ الأُولَى لِلنُّعَاسِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15768, 'وَسْوَاسٌ', 'وسواس', 'جامد', 'وسوس', 'وسواس', 'سس', '', '', '', 'مفرد', 'DnN', '', '', '"وَسَاوِسُ"', '', 'R', '', '', '', '', '', '', '". 1.""أَصَابَهُ الوَسْوَاسُ"" : قَلَقٌ نَاتِجٌ عَنِ اضْطِرَابٍ نَفْسِيٍّ يَحْدُثُ لِلْمَرْءِ مِنْ غَلَبَةِ السَّوْدَاءِ، وَمِمَّا يَخْطُرُ عَل"', '');
