INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15776, 'وَشَقٌ', 'وشق', 'جامد', '', 'وشق', 'شق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَشَقٌ-وَشَقٌ (حو).: حَيَوَانٌ مِنْ فَصِيلَةِ السِّنَّوْرِيَّاتِ، مِنْ رُتْبَةِ الضَّوَارِي،وَهُوَ نَوْعٌ مِنَ القِطَطِ الوَحْشِيَّةِ يَقْطُنُ الغَابَاتِ وَالصَّحَارَى أَيْضاً، مَعْرُوفٌ بِحِدَّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15777, 'وَاصِبَةٌ', 'واصبة', 'جامد', 'وصب', 'واصبة', 'صبة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"وَاصِبَةٌ-وَاصِبَةٌ [و ص ب]. ""تَاهَ فِي الوَاصِبَةِ"" : الصَّحْرَاء"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15778, 'وَصَبٌ', 'وصب', 'جامد', 'وصب', 'وصب', 'صب', '', '', '', 'مفرد', 'DnN', '', '', '"أَوْصَابٌ"', '', 'R', '', '', '', '', '', '', '". 1.""أَصَابَهُ الوَصَبُ"" : الْمَرَضُ، الوَجَعُ الدَّائِمُ. 2.""وَصَبُ الجِسْمِ"" : تَعَبُهُ، فُتُورُهُ."', '');
