INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15782, 'أَوَاصِرُ', 'أواصر', 'جامد', '', 'ءواصر', 'صر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15783, 'وَصْفَةٌ', 'وصفة', 'جامد', 'وصف', 'وصفة', 'صفة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"وَصْفَةٌ-وَصْفَةٌ [و ص ف]. ""وَصْفَةُ الطَّبِيبِ"" : مَا يُعَيِّنُهُ الطَّبِيبُ مِنْ عِلاَجٍ لِلْمَرِيضِ لِيَتَدَاوَى بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15784, 'مُوَاصَلاَتٌ', 'مواصلات', 'جامد', 'وصل', 'مواصلات', 'مصلت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُوَاصَلاَتٌ-مُوَاصَلاَتٌ [و ص ل]. ""تُعْتَبَرُ الْمُوَاصَلاَتُ فِي الْعَصْرِ الْحَدِيثِ قَاعِدَةً للِتَّنْمِيَةِ الاقْتِصَادِيَّةِ وَالتَّبَادُلِ التِّجَارِيِّ"" : وَسَائِلُ الاتِّصَالِ بَيْنَ النَّاسِ وَطُرُقُها، كَالسَّيَّارَاتِ، والسِّكَكِ الْحَدِيدِيَّةِ، والْخُطُوطِ الْجَوِّيَّةِ، بِالإِضَافَةِ إِلَى الوَسَائِلِ السِّلْكِيَّةِ واللاَّسِلْكِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15785, 'مَوْصِلٌ', 'موصل', 'جامد', 'وصل', 'موصل', 'مصل', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَاصِلُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَوْصِلُ الْحَبْلِ"" : مَوْضِعُ الوَصْلِ، مَعْقِدُهُ. 2.""مَوْصِلُ الذِّرَاعِ بِالكَتِفِ"" : مَفْصِل... 3.""مَوْصِلُ القَافِلَةِ"" : مَكانُ وُصولِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15786, 'مَوَاصِلُ', 'مواصل', 'جامد', '', 'مواصل', 'مصل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
