INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15788, 'وُصَلٌ', 'وصل', 'جامد', '', 'وصل', 'صل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15789, 'وِصْلٌ', 'وصل', 'جامد', 'وصل', 'وصل', 'صل', '', '', '', 'مفرد', 'DnN', '', '', '"أَوْصَالٌ"', '', 'R', '', '', '', '', '', '', '". ""أَوْصَالُ الجِسْـمِ"" : مَفَاصِلُ العِظَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15790, 'أَوْصَالٌ', 'أوصال', 'جامد', '', 'ءوصال', 'صل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15791, 'وَصِيلَةٌ', 'وصيلة', 'جامد', 'وصل', 'وصيلة', 'صلة', '', '', '', 'مفرد', 'DnN', '', '', '"وَصَائِلُ"', '', '', '', '', '', '', '', '', '". 1.""وَصِيلَةُ ثَوْبٍ"" : مَا يُوصَلُ بِهِ. 2.""وَصِيلَةُ الْمَرْأَةِ أَوِ الرَّجُلِ"" : مَنْ يُرَافِقُهُمَا، رُفْقَتُهُمَا. 3.""أَرْضٌ وَصِيلَةُ"" : خِصْبَةٌ، ذَاتُ عُشْبٍ، مُتَّصِلَةٌ بِأُخْرَى مِثْلِهَا. 4.""وَصِيلَةُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15792, 'وَصَائِلُ', 'وصائل', 'جامد', '', 'وصاءل', 'صل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15793, 'وَصِيلٌ', 'وصيل', 'جامد', 'وصل', 'وصيل', 'صل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَصِيلٌ-وَصِيلٌ [و ص ل]. 1.""كَانَ وَصِيلَهُ فِي حَيَاتِهِ"" : مُرَافِقَهُ فِي حَلِّهِ وَتَرْحَالِهِ لاَ يَكَادُ يُفَارِقُهُ، وَإِذَا مَاتَ أَوْ نُكِبَ قِيلَ لِلآخَرِ: ""لاَ كُنْتَ لَهُ بِوَصِيلٍ"". 2.""هَذَا وَصِيلُ هَذَا"" : مِثْلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15794, 'وَصْوَاصٌ', 'وصواص', 'جامد', 'وصوص', 'وصواص', 'صص', '', '', '', 'مفرد', 'DnN', '', '', '"وَصَاوِيصُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '". 1.""وَصْوَاصُ البَابِ"" : ثُقْبٌ فِي البَابِ أَوِ السِّتْرِ عَلَى قَدْرِ العَيْنِ يُنْظَرُ مِنْهُ. 2.""وَصْوَاصُ الشُّبَّاكِ"" : الفَتْحَةُ الْمُرَبَّعَةُ الَّتِي تُسَلَّمُ مِنْهَا التَّذَاكِرُ، نَافِذَةٌ صَغِيرَةٌ فِي قَلْبِ النَّافِذَةِ الرَّئِيسِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15795, 'وَصَاوِيصُ', 'وصاويص', 'جامد', '', 'وصاويص', 'صص', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15796, 'وِصَايَةٌ', 'وصاية', 'جامد', 'وصي', 'وصاية', 'صة', '', '', '', 'مفرد', 'DnN', '', '', '"وَصَايَا"', '', '', '', '', '', '', '', '', '". 1.""عَاشَ تَحْتَ وِصَايَتِهِ"" : تَحْتَ سُلْطَتِهِ وَهَيْمَنَتِهِ. ""يَرْفُضُ كُلَّ وِصَايَةٍ"". 2.""قَرَّرَ القَاضِي الوِصَايَةَ عَلَى القَاصِرِ"" : إِجْرَاءٌ قَانُونِيٌّ يَتَمَثَّلُ في حِمَايَةِ القَاصِرِينَ الَّذِينَ لَمْ يَبْلُغُو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15797, 'وَصَايَا', 'وصايا', 'جامد', '', 'وصايا', 'ص', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
