INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15803, 'وُضُوءٌ', 'وضوء', 'جامد', 'وضأ', 'وضوء', 'ض', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"وَضُوءٌ-وَضُوءٌ [و ض أ]. ""وَضُوءُ الْمُصَلِّي"" : الْمَاءُ الَّذِي يُتَوَضَّأُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15804, 'مَوْضِعٌ', 'موضع', 'جامد', 'وضع', 'موضع', 'مضع', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَاضِعُ"', '', 'R', '', '', '', '', '', '', '". 1.""حَرَّكَ الْمَقْعَدَ مِنْ مَوْضِعِهِ"" : مَكَانُ وَضْعِ الشَّيْءِ، مَحَلٌّ. ""مَوْضِعُ القَدَمِ"". 2.""كَانَ الإِرْثُ مَوْضِعَ نِزَاعٍ بَيْنَ الإِخْوَةِ"', '');
