INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15842, 'وَعَى', 'وعى', 'جامد', 'وعي', 'وعى', 'ع', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَعَى-وَعَى [و ع ي]. ""اِرْتَفَعَ الوَعَى فِي السَّاحَةِ"" : الأَصْوَاتُ، الْجَلَبَةُ، الضَّجَّةُ."', '');
