INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15848, 'وَفْرَاءُ', 'وفراء', 'جامد', 'وفر', 'وفراء', 'فر', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"وَفْرَاءُ-وَفْرَاءُ [و ف ر]. 1.""أَرْضٌ وَفْرَاءُ"" : خِصْبَةٌ، مَلْأَى بِالنَّبَاتِ. 2.""أُذُنٌ وَفْرَاءُ"" : ضَخْمَةٌ، عَظِيمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15849, 'اِتِّفَاقِيَّةٌ', 'اتفاقية', 'جامد', 'وفق', 'اتفاقية', 'تفقة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""حَصَلَت اتِّفَاقِيَّةٌ مَا بَيْنَ البَلَدَيْنِ فِي الْمَجَالِ الاقْتِصَادِيِّ وَالتِّجَارِيِّ"" : مُعَاهَدَةُ اتِّفَاقٍ تَضُمُّ بُنُودًا وَقَوَاعِدَ حَوْلَ مَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15850, 'وِفَاقٌ', 'وفاق', 'جامد', 'وفق', 'وفاق', 'فق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وِفَاقٌ-وِفَاقٌ [و ف ق]. ""كَانَ عَلَى وِفَاقٍ مَعَهُ"" : عَلَى انْسِجَامٍ، عَلَى اتِّحَادٍ وَمُلاَءمَةٍ مَعَهُ فِي "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15851, 'وَفِيقٌ', 'وفيق', 'جامد', 'وفق', 'وفيق', 'فق', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَفِيقٌ-وَفِيقٌ [و ف ق]. ""كَانَ وَفِيقَهُ فِي السَّرَّاءِ وَالضَّرَّاءِ"" : رَفِيقَهُ الْمُوَافِقَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15852, 'وَفَاةٌ', 'وفاة', 'جامد', 'وفي', 'وفاة', 'فة', '', '', '', 'مفرد', 'DnN', '', '', '"وَفَيَاتٌ"', '', '', '', '', '', '', '', '', '". ""وَفَاةُ الرَّجُلِ"" : مَوْتُهُ. ""كَثُرَ عَدَدُ الوَفَيَاتِ"" ""بَلَغَ مُعَدَّلُ الوَفَيَاتِ فِي البِلاَدِ كَذَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15853, 'وَفَيَاتٌ', 'وفيات', 'جامد', '', 'وفيات', 'فت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15854, 'وَقْبَاءُ', 'وقباء', 'جامد', 'وقب', 'وقباء', 'قب', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"وَقْبَاءُ-وَقْبَاءُ [و ق ب]. ""بِئْرٌ وَقْبَاءُ"" : غَائِرَةُ الْمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15855, 'مَوْقِتٌ', 'موقت', 'جامد', 'وقت', 'موقت', 'مقت', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مُوَقِّتٌ-مُوَقِّتٌ [و ق ت] (فا. من وَقَّتَ). 1.""مُوَقِّتُ الصَّـلاَةِ"" : مُؤَقِّتٌ، مَنْ يُحَدِّدُ وَقْتَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15856, 'مِيقَاتٌ', 'ميقات', 'جامد', 'وقت', 'ميقات', 'مقت', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَاقِيتُ"', '', 'R', '', '', '', '', '', '', '". 1.""مِيقَاتُ الصَّلاَةِ"" : وَقْتُهَا. 2.""حَدَّدَ مِيقَاتَ اللِّقَاءِ"" : أَيِ الْمَوْعِدَ الَّذِي جُعِلَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15857, 'مَوَاقِيتُ', 'مواقيت', 'جامد', '', 'مواقيت', 'مقت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15858, 'مَوْقِدٌ', 'موقد', 'جامد', 'وقد', 'موقد', 'مقد', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '"مَوَاقِدُ"', '', 'R', '', '', '', '', '', '', '". 1.""نَارُ الْمَوْقِدِ"" : مَوْضِعُ احْتِرَاقِ النَّارِ. 2.""مَوْقِدُ الغَازِ"" : جِهَازٌ تُوقَدُ فِيهِ النَّارُ بِالغَازِ ويُسْتَعْمَلُ لِلتَّسْخِينِ أَوِ الطَّبْخِ. ""مَوْقِدٌ كَهْرَبَائِيٌّ"". 3.""مَوْقِدَةُ البَيْتِ"" : دَائِرَةٌ رُكْنِيَّةٌ مِنْ حَجَرٍ أَوْ طِينٍ تَشْتَعِلُ فِيهَا النَّارُ لِلتَّدْفِئَةِ، لَهَا فَتْحَةٌ هَوَائِيَّةٌ مُمْتَدَةٌ إِلَى سَطْحِ البَيْتِ مِنْهَا يَنْفُذُ الدُّخَانُ، مَدْخَنَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15859, 'مَوَاقِدُ', 'مواقد', 'جامد', '', 'مواقد', 'مقد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15860, 'وِقَادٌ', 'وقاد', 'جامد', 'وقد', 'وقاد', 'قد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"وِقَادٌ-وِقَادٌ [و ق د]. ""وِقَادُ النَّارِ"" : مَا تُوقَدُ بِهِ، الوَقُودُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15861, 'وِقْرٌ', 'وقر', 'جامد', 'وقر', 'وقر', 'قر', '', '', '', 'مفرد', 'DnN', '', '', '"أَوْقَارٌ"', '', 'R', '', '', '', '', '', '', '". ""حَمَلَ وِقْراً"" : حِمْلاً ثَقِيلاً، ثِقْلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15862, 'أَوْقَارٌ', 'أوقار', 'جامد', '', 'ءوقار', 'قر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15863, 'وَقِيرَةٌ', 'وقيرة', 'جامد', 'وقر', 'وقيرة', 'قرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"وَقِيرَةٌ-وَقِيرَةٌ [و ق ر]. 1.""وَقِيرَةُ الصَّخْرَةِ"" : النُّقْرَةُ، الْحُفْرَةُ العَظِيمَةُ الَّتِي تُمْسِكُ الْمَاءَ. 2.""أُذُنٌ وَقِيرَةٌ"" : أَصَابَهَا الوَقْرُ، صَمَّاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15864, 'وَاقِعَةٌ', 'واقعة', 'جامد', 'وقع', 'واقعة', 'قعة', '', '', '', 'مفرد', 'DnN', '', '', '"وَقَائِعُ"', '', 'Rp', '', '', '', '', '', '', '". 1. ""شَارَكَ فِي الوَاقِعَةِ"" : الْمُصَادَمَةُ فِي الْحَرْبِ. 2. ""يَا لَهَوْلِ الوَاقِعَةِ"" : يَا لَهَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15865, 'وَقَائِعُ', 'وقائع', 'جامد', '', 'وقاءع', 'قع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15866, 'وَقَائِعُ', 'وقائع', 'جامد', 'وقع', 'وقاءع', 'قع', '', '', '', 'مفرد', '', '', '', '"مفردوَقِيعَة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""شَاهَدَ الوَقَائِعَ"" : الْحَوَادِثَ. 2.""وَقَائِعُ العَرَبِ"" : أَيَّامُ حُرُوبِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15867, 'وَقِيعَةٌ', 'وقيعة', 'جامد', 'وقع', 'وقيعة', 'قعة', '', '', '', 'مفرد', 'DnN', '', '', '"وَقَائِعُ"', '', '', '', '', '', '', '', '', '". 1.""كَانَتِ الوَقِيعَةُ عَنِيفَةً"": صَدْمَةُ الْحَرْبِ وَالقِتَالِ. 2.""سَعَى بِالوَقِيعَةِ بَيْنَهُمْ"" : بِالاغْتِيَابِ بَيْنَهُمْ. 3.""وَقَائِعُ العَرَبِ"" : الأَيَّامُ الَّتِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15868, 'وَقَائِعُ', 'وقائع', 'جامد', '', 'وقاءع', 'قع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15869, 'مَوْقِفٌ', 'موقف', 'جامد', 'وقف', 'موقف', 'مقف', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَاقِفُ"', '', 'R', '', '', '', '', '', '', '". 1.""عَبَّرَ عَنْ مَوْقِفِهِ بِشَجَاعَةٍ"" : اِسْتَعْدَادٌ نَفْسِيٌّ أوْ رَأْيٌ إِزَاءَ شَخْصٍ أو قَضيَّةٍ مَّا يُعَبِّرُ فِيهِ صَاحِبُهُ عَمَّا يَشْعُرُ بِهِ. ""مَوْقِفٌ حَرِجٌ"" ""مَوْقِفٌ عَدَائِيٌّ"" ""اِسْتَطَاعَ أَنْ يُسَيْطِرَ عَلَى الْمَوْقِفِ كُلِّي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15870, 'مَوَاقِفُ', 'مواقف', 'جامد', '', 'مواقف', 'مقف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15871, 'مِيقَافٌ', 'ميقاف', 'جامد', 'وقف', 'ميقاف', 'مقف', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِيقَافٌ-مِيقَافٌ [و ق ف]. ""مِيقَافُ القِدْرِ"" : عُودٌ يُسَكَّنُ بِهِ غَلَيَانُ القِدْرِ وَيُحَرَّكُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15872, 'وَقْلٌ', 'وقل', 'جامد', '', 'وقل', 'قل', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '": جِنْسُ نَخْلٍ قَصِيرٍ مَهْدُهُ الْمَغْرِبُ الأَقْصَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15873, 'وَقْوَاقٌ', 'وقواق', 'جامد', '', 'وقواق', 'قق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"وَقْوَاقٌ-وَقْوَاقٌ (حو). 1. : طَائِرٌ مِنْ فَصِيلَةِ الوَقْوَاقِيَّاتِ، مِنَ الطُّيُورِالْمُهَاجِرَةِ، ظَهْرُهُ رَمَادِيُّ اللَّوْنِ، وَبَطْنُهُ أَبْيَضُ، مَكْسُوٌّ بِالرِّيشِ إِلَى نَحْوِ ثُلُثَيْهِ أَوْ ثَلاَثَةِ أَرْبَاعِهِ، يَعِيشُ فِي الغَابَةِ، "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15874, 'وَقْوَاقِيَّاتٌ', 'وقواقيات', 'جامد', '', 'وقواقيات', 'ققت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةُ طُيُورٍ مِنْ رُتْبَةِ الْمُتَسَلِّقَاتِ، مِنْ أَشْهَرِ أَنْوَاعِهَا الوَقْوَاقُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15875, 'أَوقِيَةٌ', 'أوقية', 'جامد', 'وقي', 'ءوقية', 'قة', '', '', '', 'مفرد', 'DnN', '', '', '"أوَاقٍ:الأوَاقِي"', '', '', '', '', '', '', '', '', '". 1.: مِعْيَارٌ لِلْوَزْنِ يُعَادِلُ 200 غرَامٍ وَهِيَ جُزْءٌ مِنْ أجْزَاءِ الرَّطْلِ الاِثْنَيْ عَشْرَ. ""لَمْ يَكُنْ يَمْلِكُ مَا يَشْتَرِي بِهِ أوقِيَةً مِنَ العَدَسِ"". 2.: قِطْعَةٌ نَقْدِيَّةٌ يُتَعَامَلُ بِهَا فِي مُورِيطَانيا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15876, 'أوَاقِي', 'أواقي', 'جامد', '', 'ءواقي', 'ق', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15877, 'وَقَاءٌ', 'وقاء', 'جامد', 'وقي', 'وقاء', 'ق', '', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"وَقَاءٌ-وَقَاءٌ، وِقَاءٌ [و ق ي]. ""كَانَ ذَلِكَ وِقَاءً لِشَرِّهِ"" : وِقَايَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15878, 'مَوْكِبٌ', 'موكب', 'جامد', 'وكب', 'موكب', 'مكب', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَاكِبُ"', '', 'R', '', '', '', '', '', '', '". ""يَسِيرُ فِي طَلِيعَةِ الْمَوْكِبِ"" : جَمَاعَةٌ مِنَ النَّاسِ يَسِيرُونَ رَاكِبِينَ أو مَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15879, 'مَوَاكِبُ', 'مواكب', 'جامد', '', 'مواكب', 'مكب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15880, 'وَكِيرَةٌ', 'وكيرة', 'جامد', 'وكر', 'وكيرة', 'كرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"وَكِيرَةٌ-وَكِيرَةٌ [و ك ر]. ""قَدَّمَ لَهُمُ الوَكِيرَةَ"" : طَعَامُ احْتِفَالٍ يُعْمَلُ عِنْدَ الفَرَاغِ مِنَ البِنَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15881, 'وِكَافٌ', 'وكاف', 'جامد', 'وكف', 'وكاف', 'كف', '', '', '', 'مفرد', 'DnN', '', '', '"وُكُفٌ"', '', 'R', '', '', '', '', '', '', '". ""وِكَافُ البَعِيرِ"" : بَرْدَعَتُهُ. ""وَكَّفَ الوِكَافَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15882, 'وُكُفٌ', 'وكف', 'جامد', '', 'وكف', 'كف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15883, 'يُوسُفِيٌّ', 'يوسفي', 'جامد', '', 'يوسفي', 'سف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"يُوسُفِيٌّ-يُوسُفِيٌّ (نب). : فَاكِهَةٌ مِنْ فَصِيلَةِ السَّذَابِيَّاتِ يُشْبِهُ فِي تَرْكِيبِهِ وَمَذَاقِهِ الْبُرْتُقَالَ وَهُوَ أَصْغَرُ مِنْهُ، حُلْوٌ وَمُعَطَّرٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15884, 'وِكَالَةٌ', 'وكالة', 'جامد', 'وكل', 'وكالة', 'كلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""أَعْطَاهُ الوَكَالَةَ"" : أَيْ أَعْطَاهُ تَفْوِيضاً وَتَوْكِيلاً لِلْقِيَامِ بِعَمَلٍ مِنَ الأَعْمَالِ، نِيَابَةً عَنْهُ. ""وِكَالَةٌ رَسْمِيَّةٌ"". 2.""يَقُومُ بِمَهَامِّهِ بِالوِكَالَةِ"" : بِالنِّيَابَةِ. 3.""أَس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15885, 'وَكْنٌ', 'وكن', 'جامد', 'وكن', 'وكن', 'كن', '', '', '', 'مفرد', 'DnN', '', '', '"أَوْكَانٌ:وُكُونٌ"', '', 'R', '', '', '', '', '', '', '". ""وَكْنُ الطَّائِرِ"" : عُشُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15886, 'أَوْكَانٌ', 'أوكان', 'جامد', '', 'ءوكان', 'كن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15887, 'وُكُونٌ', 'وكون', 'جامد', '', 'وكون', 'كن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15888, 'وَكْنَةٌ', 'وكنة', 'جامد', '', 'وكنة', 'كنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات، وُكَنٌ. ""وُكْنَةُ الطَّائِرِ"" : عُشُّهُ، وَكْنُهُ. ""وَقَدْ أَغْتَدِي والطَّيْرُ في وُكُنَاتِها"". (امرؤ القيس)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15889, 'مَوْلِجٌ', 'مولج', 'جامد', 'ولج', 'مولج', 'ملج', '', '', '', 'مفرد', 'DnN', '', '', '"مَوَالِجُ"', '', 'R', '', '', '', '', '', '', '". ""مَوْلِجُ الدَّارِ"" : مَدْخَلُهَا، بَابُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15890, 'مَوَالِجُ', 'موالج', 'جامد', '', 'موالج', 'ملج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15891, 'وَلِيجَةٌ', 'وليجة', 'جامد', 'ولج', 'وليجة', 'لجة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"وَلِيجَةٌ-وَلِيجَةٌ [و ل ج]. ""وَلِيجَةُ النَّفْسِ"" : دَخِيلَتُهَا. ""هُوَ فِي وَلِيجَةِ نَفْسِهِ مُرْهَفُ الْحِسِّ دَقِيقُ التَّرَقُّبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15892, 'مِيلاَدٌ', 'ميلاد', 'جامد', 'ولد', 'ميلاد', 'ملد', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِيلاَدٌ-مِيلاَدٌ [و ل د]. 1.""اِحْتَفَلَ بِعِيدِ مِيلاَدِهِ"" : بِيَوْمِ وِلاَدَتِهِ. 2.""يَحْتَفِلُ الْمَسِيحِيُّونَ بِعِيدِ الْمِيلاَدِ"" : بِعِيدِ وِلاَدَةِ السَّيِّدِ الْم"', '');
