INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15925, 'وَهْلَةٌ', 'وهلة', 'جامد', 'وهل', 'وهلة', 'هلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '". 1.""أَخَذَتْهُ الوَهْلَةُ مِمَّا رَآى"" : الهَوْلُ، الفَزْعَةُ. 2.""لَقِيتُهُ أَوَّلَ وَهْلَةٍ"" : أَوَّلَ شَيْءٍ. 3.""مِنَ الوَهْلَةِ الأُولَى"" : مِنَ النَّظْرَةِ الأُولَى. ""تَعَرَّفْتُهُ مِنَ الوَهْلَةِ الأُولَى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15926, 'وَهْوَهَةٌ', 'وهوهة', 'جامد', 'وهوه', 'وهوهة', 'ههة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '"وَهْوَهَةٌ-وَهْوَهَةٌ [و هـ و هـ]. ""وَهْوَهَةُ الفَرَسِ"" : صَوْتٌ فِي حَلْقِهِ يَكُونُ فِي آخِرِ صَهِيلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15927, 'وَيْلَةٌ', 'ويلة', 'جامد', 'ويل', 'ويلة', 'لة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""عَرَفَ وَيْلَةً"" : أَيْ هَلاَكاً، بَلِيَّةً. الكهف آية 49وَيَقُولُونَ يَا وَيْلَتَنَا مَا لِهَذَا الكِتَابِ لاَ يُغَادِرُ صَغِيرَةً وَلاَ كَبِيرَةً إِلاَّ أَحْصَاهَا ( قرآن). 2.""وَقَعَ فِي وَيْل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15928, 'وَيْلٌ', 'ويل', 'جامد', 'ويل', 'ويل', 'ل', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَيْلٌ-وَيْلٌ [و ي ل]. 1. : كَلِمَةٌ تَأْتِي لِحُلُولِ الشَّرِّ وَالعَذَابِ: وَيْلَهُ، وَيْلَكَ، وَيْلِي، وَيْلٌ لَهُ، وَيْلاً لَهُ : الرَّفْعُ عَلَى الابْتِدَاءِ، وَالنَّصْبُ عَلَى إِضْمَارِ الفِعْلِ فَكَأَنَّكَ قُلْتَ:"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15929, 'وَيْنَةٌ', 'وينة', 'جامد', 'وين', 'وينة', 'نة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"وَيْنَةٌ-وَيْنَةٌ [و ي ن]. : زَبِيبٌ أَسْوَدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15930, 'وَيْنٌ', 'وين', 'جامد', 'وين', 'وين', 'ن', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَيْنٌ-وَيْنٌ [و ي ن]. 1.""وَيْنُ الكَرْمِ"" : عِنَبُهُ الأَسْوَدُ، أَوِ الأَبْيَضُ. 2.""بِهِ وَيْنٌ"" : عَيْبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15931, 'يَأْسٌ', 'يأس', 'جامد', 'يأس', 'يءس', 'س', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يَأْسٌ-يَأْسٌ [ي أ س]. 1.""سُدَّتِ الأَبْوَابُ فِي وَجْهِهِ فَاسْتَبَدَّ بِهِ الْيَأْسُ"" : الْقُنُوطُ. ""الِاسْتِسْلامُ أَوِ الْيَأْسُ كِلاَهُمَا يَعْنِي الْفَنَاءَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15932, 'يَاسَمِينٌ', 'ياسمين', 'جامد', '', 'ياسمين', 'سمن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يَاسَمِينٌ-يَاسَمِينٌ (نب). 1. : نَبَاتَاتٌ مِنْ فَصِيلَةِ الزَّيْتُونِيَّاتِ، مِنْ رُتْبَةِ الْيَاسَمِينِيَّاتِ، لَهَا أَزْهَارٌ بَيْضَاءُ أَوْ صَفْرَاءُ، مُنْبَسِطَةُ الأَوْرَاقِ، وَهِ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15933, 'يَاسَمِينِيَّاتٌ', 'ياسمينيات', 'جامد', '', 'ياسمينيات', 'سمنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"يَاسَمِينِيَّاتٌ-يَاسَمِينِيَّاتٌ (نب). : رُتْبَةٌ مِنْ فَصِيلَةِ الزَّيْتُونِيَّاتِ عَطِرَةٌ، أَنْوَاعُهَا عَدِيدَةٌ، أَشْهَرُهَا الْيَاسَمِينُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15934, 'يَاقَةٌ', 'ياقة', 'جامد', '', 'ياقة', 'قة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', '', '', '', '', '', '', '', '"ج: ـات. ""يَاقَةُ الْقَمِيصِ"" : طَوْقُهُ. ""يَتَزَيَّنُ بِيَاقَةٍ أَشْبَهُ بِشَبَكَةٍ حَرِيرِيَّةٍ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15935, 'يَاقُوتٌ', 'ياقوت', 'جامد', '', 'ياقوت', 'قت', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', 'R', '', '', '', '', '', '', '"""مِنَ الأَحْجَارِ الْكَرِيمَةِ الْيَاقُوتُ وَالْمَرْجَانُ وَالْمَاسُ"" : حَجَرٌ كَرِيمٌ شَفَّافٌ، صَلْبٌ، مُخْتَلِفُ الأَلْوَانِ. ""مَا كَانَ قَرِيباً مِنْ أَنْ يَكُونَ صِرْفاً خَالِصاً لاَ شَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15936, 'يَاقُوتِيَّةٌ', 'ياقوتية', 'جامد', '', 'ياقوتية', 'قتة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"يَاقُوتِيَّةٌ-يَاقُوتِيَّةٌ (نب). : زَهْرَةٌ مِنَ الزَّنْبَقِيَّاتِ، تُزْرَعُ لِجَمَالِ زَهْرِهَا وَأَلْوَانِهَا الزَّاهِيَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15937, 'يَانَصِيبٌ', 'يانصيب', 'جامد', '', 'يانصيب', 'نصب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَلِمَةٌ مُرَكَّبَةٌ مِنْ ""يَا"" حَرْفُ نِدَاءٍ وَ""نَصِيبٌ"": حَظٌّ، أَيْ يَا حَظُّ. ن. نَصِيبٌ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15938, 'تَيَتُّمٌ', 'تيتم', 'جامد', 'يتم', 'تيتم', 'تتم', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَيَتُّمٌ-تَيَتُّمٌ [ي ت م] (تَيَتَّمَ). ""تَيَتُّمُ الصَّبِيِّ"" : صَيْرُهُ يَتِيماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15939, 'مَيْتَمٌ', 'ميتم', 'جامد', 'يتم', 'ميتم', 'متم', '', '', '', 'مفرد', 'DnN', '', '', '"مَيَاتِمُ"', '', 'R', '', '', '', '', '', '', '". ""نَشَأَ فِي الْمَيْتَمِ"" : مَلْجَأٌ لِلأَطْفَالِ اليَتَامَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15940, 'مَيَاتِمُ', 'مياتم', 'جامد', '', 'مياتم', 'متم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15941, 'يَتُوعٌ', 'يتوع', 'جامد', '', 'يتوع', 'تع', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"ـ"', '', 'R', '', '', '', '', '', '', '"ج: ـات. (نب). : كُلُّ نَبَاتٍ لَهُ لَبَنٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15942, 'يَتُوعِيَّاتٌ', 'يتوعيات', 'جامد', '', 'يتوعيات', 'تعت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '"يَتُوعِيَّاتٌ-يَتُوعِيَّاتٌ (نب).: فَصِيلَةُ نَبَاتَاتٍ تَتَمَيَّزُ بِوُجُودِ لَبَنٍ فِيهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15943, 'يَحْمُورٌ', 'يحمور', 'جامد', '', 'يحمور', 'حمر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"يَحَامِيرُ"', '', 'R', '', 'N', 'O', 'O', 'O', '', '"ج: يَحَامِيرُ. 1. : مَادَّةٌ آحِيَّةٌ زُلاَلِيَّةٌ تَظْهَرُ فِي دَمِ الْفِقْرِيَّاتِ. 2.:حَيَوَانٌ مِنْ فَصِ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15944, 'يَحَامِيرُ', 'يحامير', 'جامد', '', 'يحامير', 'حمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'O', 'O', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15945, 'يَخْتٌ', 'يخت', 'جامد', '', 'يخت', 'خت', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '": سَفِينَةٌ للِتَّنَزُّهِ فِيهَا كُلُّ أَسْبَابِ الرَّاحَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15946, 'أَيَادِي', 'أيادي', 'جامد', 'يدي', 'ءيادي', 'د', '', 'Tk', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"أَيَادٍ-أَيَادٍ، الأَيَادِي [ي د ي]. 1.""لَهُ أيَادٍ بَيْضَاءُ"" : لَهُ نِعَمٌ وَأفْضَالٌ. 2.""أيَادِي الزَّمَانِ"" : إِنْعَامُهُ وَإحْسَانُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15947, 'يَدٌ', 'يد', 'جامد', 'يدي', 'يد', 'د', '', '', '', 'مفرد', 'DnN', '', '', '"أَيْدٍ:الأَيْدِي:أَيَادٍ:الأَ', '', '', '', '', '', '', '', '', '". 1.""يَدُ الإِنْسَانِ"" : عُضْوٌ مِنْ أَعْضَاءِ الْجَسَدِ، وَيُطْلَقُ عَلَى الْكَفِّ، أَوْ مِنَ الْكَتِفِ إِلَى أَطْرَافِ الأَصَابِعِ. ""رَفَعَ يَدَهُ للِسَّائِقِ"" l ""شَدَّ عَلَى يَدِهِ بِحَرَارَةٍ"" l ""اليَدُ الوَاحِدَةُ لاَ تُصَفِّقُ"". 2.""يَدُ الْكَأْسِ أَوِ الْمِطْرَقَةِ وَمَا شَابَهَ ذَلِكَ"" : العُرْوَةُ، الْمِقْبَضُ، النِّصَابُ. 3.""لَهُ فيِ كُلِّ مُنَاسَبَةٍ كَرِيمَةٍ يَدٌ"" : إِحْسَانٌ. 4.""لَهُ الْيَدُ الطُّولَى فِي هَذَا الْمَجَالِ"" : أَيْ لَهُ الْفَضْلُ الأَكْبَرُ فِيهِ، لَهُ تَأْثِيرٌ فِي ذَلِكَ. 5.""هُوَ طَوِيلُ الْيَدِ"" : سَخِيٌّ، كَرِيمٌ، كَثِيرُ الْمَعْرُوفِ. ""طَلْقُ الْيَدَيْنِ"". 6.""الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى"" : الْيَدُ الْمُعْطِيَةُ خَيْرٌ مِنَ الآخِذَةِ. 7.""أَعْطَاهُ مَالاً عَنْ ظَهْرِ يَدٍ"" : بِغَيْرِ مُقَابِلٍ. 8.""رَجُلٌ يَدُهُ قَصِيرَةٌ"" : أَيْ عَاجِزٌ غَيْرُ قَادِرٍ عَلَى شَيْءٍ. ""الْعَيْنُ بَصِيرَةٌ وَالْيَدُ قَصِيرَةٌ"". 9.""يَدٌ بَيْضَـاءُ"" : الاِبْتِدَاءُ بِالْمَعْرُوفِ. وَيَكْثُرُ اسْتِعْمَالُ الأَيَادِي بِالْجَمْعِ بِمَعْنَى النِّعَمِ وَالْمِنَنِ. ""لَهُ أَيَادٍ بَيْضَاءُ فِي هَذَا الأَمْرِ"". 10.""يَدٌ خَضْرَاءُ"" : الْمُكَافَأَةُ عَلَى الْمَعْرُوفِ. 11.""يَدٌ سَوْدَاءُ"" : الْمَنُّ بِالْمَعْرُوفِ. 12.""ل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15948, 'أَيْدِي', 'أيدي', 'جامد', '', 'ءيدي', 'د', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15949, 'أَيَادِي', 'أيادي', 'جامد', '', 'ءيادي', 'د', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15950, 'يَرَاعِيَّاتٌ', 'يراعيات', 'جامد', '', 'يراعيات', 'رعت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ مِنَ الْحَشَرَاتِ الْمُفْتَرِسَةِ، مِنْ مُغْمَدَاتِ الأَجْنِحَةِ، مُتَمَيِّزَةٌ بِغُدَدٍ فُسْفُورِيَّةٍ تُضيءُ في الظُّلْمَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15951, 'يَرْبُوعٌ', 'يربوع', 'جامد', '', 'يربوع', 'ربع', '', '', '', 'جمع تكسير', 'DnN', '', '', '"يَرَابِيعُ"', '', 'R', '', '', '', '', '', '', '"ج: يَرَابِيعُ. (حو). : حَيَوَانٌ مِنْ فَصِيلَةِ الْيَرْبُوعِيَّاتِ، مِنْ رُتْبَةِ الْقَوَاضِمِ، وَهُوَ نَوْعٌ مِنَ الْفِئْرَانِ، وَهُوَ أَكْبَرُ، قَصِيرُ الْيَدَيْنِ، طَوِيلُ الرِّجْلَيْنِ، لَهُ ذَنَبٌ طَوِيلٌ مُنْتَهٍ بِخُصْلَةٍ مِنَ الشَّعْرِ، سَرِيعُ الْجَرْيِ، يَقْتَاتُ بِالْحَشَرَاتِ وَصِغَارِ الطُّيُورِ وَالنَّبَاتَاتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15952, 'يَرَابِيعُ', 'يرابيع', 'جامد', '', 'يرابيع', 'ربع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15953, 'يَرْبُوعِيَّاتٌ', 'يربوعيات', 'جامد', '', 'يربوعيات', 'ربعت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ حَيَوَانِيَّةٌ مِنْ ذَوَاتِ الْقَوَاضِمِ، أَنْوَاعُهَا عَدِيدَةٌ، أَشْهَرُهَا الْيَرْبُوعُ، وَهِيَ مُتَمَيِّزَةٌ بِقِصَرِ يَدَيْهَا وَطُولِ رِجْلَيْهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15954, 'يَرَاعٌ', 'يراع', 'جامد', 'يرع', 'يراع', 'رع', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"يَرَاعٌ-يَرَاعٌ، ةٌ [ي ر ع]. 1.""يَمْتَدُّ الْيَرَاعُ عَلَى ضِفَافِ النَّهْرِ "" : الْقَصَبُ. ""وَقَعَ الْحَرِيقُ فِي الْيَرَاعِ"". 2.""يُزَمِّرُ الرَّاعِي بِالْيَرَاعِ"" : النَّايُ الْمَصْنُوعُ مِنَ الْقَصَبِ. 3.""يَكْتُبُ بِالْيَرَاعِ"" : بِالْقَلَمِ الْمَصْنُوعِ مِنَ الْقَصَبِ. 4.""رَجُلٌ يَرَاعٌ"" : مَنْ لاَرَأْيَ لَهُ وَلاَ عَقْلَ. 5.""يَرَاعٌ فِي الْمَعَارِكِ"" : جَبَانٌ.وَمَا ثَوْبُ الْبَقَاءِ بِثَـوْبِ عِـزٍّ*فَيُطْوَى عَنْ أَخِي الْخَنَعِ الْيَرَاعِ (قطري بن الفجاءة).6. (حش) : حَشَرَةٌ مِنْ فَصِيلَةِ الْيَرَاعِيَّاتِ، مِنْ رُتْبَةِ مُغْمَدَاتِ الأَجْنِحَةِ، مُضِيئَةٌ بِاللَّيْلِ وَتُعْرَفُ أَيْضاً بِالْحُبَاحِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15955, 'يَرْقَانٌ', 'يرقان', 'جامد', '', 'يرقان', 'رقن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '"1.""أُصِيبَ فَجْأَةً بِمَرَضِ الْيَرْقَانِ"" : مَرَضٌ يُصِيبُ الدَّمَ وَيُسَبِّبُ لِلْمُصَابِ بِهِ اصْفِرَاراً فِي جِلْدِهِ وَعَيْنَيْهِ. 2.""أَصَابَ الْيَرْقَانُ الزَّرْعَ"" : آفَةٌ تُصِيبُ الزَّرْعَ فَيَصْفَرُّ مِنْ جَرَّاءِ ذَلِكَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15956, 'يَرْقَانَةٌ', 'يرقانة', 'جامد', '', 'يرقانة', 'رقنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '": أَحَدُ أَطْوَارِ النُّمُوِّ فِي بَعْضِ الْحَيَوَانِ كَالْحَشَرَاتِ وَالْقِشْرِيَّاتِ وَالرِّخْوِيَّاتِ وَغَيْرِهَا، يَخْرُجُ مِنَ الْبَيْضَةِ، وَقَدْ يَتَحَوَّلُ عَلَى الْحَيَوَانِ الْيَافِعِ مُبَاشَرَةً،كَمَا فِي الْجَرَادِ وَيُسَمَّى ""الْحُورِيَّةَ"". أَوْ يَمُرُّ بِأَطْوَارٍ أُخْرَى، وهُوَ بِذَلِكَ مِثْلُ دُودَةِ وَرَقِ الْقُطْنِ وَالنَّحْلِ وَالذُّبَابِ وَالْبَعُوضِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15957, 'مَيْسَرَةٌ', 'ميسرة', 'جامد', 'يسر', 'ميسرة', 'مسرة', '', '', '', 'مفرد', 'DnN', '', '', '"مَيَاسِرُ"', '', 'R', '', '', '', '', '', '', '". 1.""مَيْسَرَةُ الصُّفُوفِ"" : مَا كَانَ جِهَةَ اليَسارِ خِلاَفَ الْمَيْمَنَةِ. 2.البقرة آية 280 فَنَظِرَةٌ إِلَى مَيْسَرَةٍ (قرآن) : الغِنَى، الثَّرَاءُ، الْمَقْدِرَة. 3.""مَيْسَرَةُ عَمَلٍ"" : سُهُولَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15958, 'مَيَاسِرُ', 'مياسر', 'جامد', '', 'مياسر', 'مسر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15959, 'مَيْسِرٌ', 'ميسر', 'جامد', 'يسر', 'ميسر', 'مسر', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَيْسِرٌ-مَيْسِرٌ [ي س ر]. ""يَكْرَهُ لَعِبَ الْمَيْسِرِ"" : القِمار.البقرة آية 219 يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15960, 'يَسَارَةٌ', 'يسارة', 'جامد', 'يسر', 'يسارة', 'سرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"يَسَارَةٌ-يَسَارَةٌ [ي س ر]. 1.""هُوَ فِي يَسَارَةٍ"" : فِي غِنـىً وَسَعَةٍ وَرَخَاءٍ. 2.""وَجَدَ فِي الْعَمَلِ يَسَارَةً"" : سُهُولَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15961, 'يَسَارٌ', 'يسار', 'جامد', 'يسر', 'يسار', 'سر', '', '', '', 'مفرد', 'DnN', '', '', '"يُسْرٌ:يُسُرٌ"', '', 'Rp', '', '', '', '', '', '', '". 1.""يَسِيرُ عَلَى الْيَسَـارِ"" : أَيْ فِي الْجِهَةِ الْيُسْرَى، خِلاَفُ الْيَمِينِ. ""جَلَسَ يَسَاراً"" l ""جَلَسَ عَنْ يَسَارِهِ"". 2.""يَكْتُبُ بِالْيَسَارِ"" : أَيْ يَكْتُبُ بِيَدِ الشِّمَالِ. 3. ""يَعِيشُ حَيَاةَ يَسَارٍ"" : حَيَاةَ غِنـىً وَسَعَةٍ وَرَخَاءٍ. 4.""هُوَ مِنْ جَمَاعَةِ الْيَسَارِ"" : أَيْ مِنَ الْجَمَاعَةِ الَّتِي لَهَا آرَاءٌ وَمَوَاقِفُ سِيَاسِيَّةٌ جِذْرِيَّةٌ وَثَوْرِيَّةٌ. ""يَنْتَمِي إِلَى حِزْبٍ مِنْ أَحْزَابِ الْيَسَارِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15962, 'يُسْرٌ', 'يسر', 'جامد', '', 'يسر', 'سر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15963, 'يُسُرٌ', 'يسر', 'جامد', '', 'يسر', 'سر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15964, 'يَسْرَةٌ', 'يسرة', 'جامد', 'يسر', 'يسرة', 'سرة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"يَسْرَةٌ-يَسْرَةٌ [ي س ر]. ""جَلَسَ يَسْرَةً"" : أَيْ يَسَاراً، جِهَةَ الْيَسَارِ. ""جَلَسَ عَنْ يَسْرَتِهِ"" l ""طَافَ بِبَصَرِهِ يَمْنَةً وَيَسْرَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15965, 'يُسْرَى', 'يسرى', 'جامد', 'يسر', 'يسرى', 'سر', '', '', '', 'مفرد', 'Dy', '', '', '"يُسْرَيَاتٌ"', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '". 1.""يَسِيرُ فِي الْيُسْـرَى"" : فِي جِهَةِ الْيَسَارِ، خِلاَفُ الْيُمْنَى. 2.""الْيَدُ الْيُسْـرَى"" : يَدُ الشِّمَالِ. 3.الليل آية 7فَسَنُيَسِّرُهُ لِلْيُسْرَى (قرآن): أَيْ سَنُوَفِّقُهُ لِطَرِيقِ الْخَيْر لِمَا فِيهِ يُسْرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15966, 'يُسْرَيَاتٌ', 'يسريات', 'جامد', '', 'يسريات', 'سرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15967, 'يَعْرٌ', 'يعر', 'جامد', '', 'يعر', 'عر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"يِعَارٌ"', '', '', '', '', '', '', '', '', '"ج: يِعَارٌ. : جَدْيٌ يُرْبَطُ عِنْدَ حُفْرَةٍ لِصَيْدِ السِّبَاعِ، فَإِذَا سُمِعَ صَوْتُهُ جَاءُوا لِطَلَبِهِ، فَتَقَعُ فِي الْحُفْرَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15968, 'يِعَارٌ', 'يعار', 'جامد', '', 'يعار', 'عر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15969, 'يَعْسُوبِيَّاتٌ', 'يعسوبيات', 'جامد', '', 'يعسوبيات', 'عسبت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": فَصِيلَةٌ مِنَ الْحَشَرَاتِ الْمُفْتَرِسَةِ، أَنْوَاعُهَا عَدِيدَةٌ، مُتَمَيِّزَةٌ بِأَجْنِحَتِهَا الْغِشَائِيَّةِ الَّتِي لا تَنْطَبِقُ في السُّكُونِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15970, 'يَغْرٌ', 'يغر', 'جامد', '', 'يغر', 'غر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"يَغْرٌ-يَغْرٌ (حو). : حَيَوَانٌ بَيْنَ الْكَلْبِ وَالسِّنَّوْرِ، قَصِيرُ الْقَوَائِمِ، أَغْبَرُ اللَّوْنِ، وَيُعْرَفُ أَيْضاً بِالْغُرَيْرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15971, 'يَافُوخٌ', 'يافوخ', 'جامد', 'يفخ', 'يافوخ', 'فخ', '', '', '', 'مفرد', 'DnN', '', '', '"يَوَافِيخُ"', '', 'R', '', '', '', '', '', '', '". 1.""أَصَابَهُ بِضَرْبَةٍ عَلَى الْيَافُوخِ"" : أَعْلَى الرَّأْسِ، وَهُوَ مُلْتَقَى عَظْمِ مُقَدَّمِ الرَّأْسِ وَمُؤَخَّرِهِ. 2.""مسَّ بِيَافُوخِهِ السَّمَاءَ"" : أَيْ إِذا عَلاَ قَدْرُهُ. 3.""ضَرَبَ يَافُوخَ اللَّيْلِ"" : إِذَا سَرَى فِي أَوَّلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15972, 'يَوَافِيخُ', 'يوافيخ', 'جامد', '', 'يوافيخ', 'فخ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15973, 'يَفَاعَةٌ', 'يفاعة', 'جامد', 'يفع', 'يفاعة', 'فعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"يَفَاعَةٌ-يَفَاعَةٌ [ي ف ع]. ""هُوَ فِي سِنِّ اليَفَاعَةِ"" : سِنُّ التَّرَعْرُعِ، قُوَّةُ الشَّبَابِ، مَرْحَلَةُ الْفُتُوَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15974, 'يَفَاعٌ', 'يفاع', 'جامد', 'يفع', 'يفاع', 'فع', '', '', '', 'مفرد', 'DnN', '', '', '"يُفُوعٌ"', '', '', '', '', '', '', '', '', '". ""أَطَلَّ مِنَ الْيَفَاعِ"" : التَّلُّ الْمُشْرِفُ، وَكُلُّ مَا ارْتَفَعَ مِنَ الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15975, 'يُفُوعٌ', 'يفوع', 'جامد', '', 'يفوع', 'فع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15976, 'يَقَظَةٌ', 'يقظة', 'جامد', 'يقظ', 'يقظة', 'قظة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"يَقَظَةٌ-يَقَظَةٌ [ي ق ظ]. 1.""شَعَرَ بِانْزِيَاحِ الْكَابُوسِ عِنْدَ الْيَقَظَةِ"" : الانْتِبَاهُ مِنَ النَّوْمِ. ""قَالَ: أَيُّهَا النَّوْمُ أَتَحَدَّى أَحْلاَمَكَ أَنْ تُعْطِيَ فَوْقَ مَا أَخَذْتهُ الْيَوْمَ فِي صَحْوِ الْيَقَظَةِ"". (ع. م. العقاد). 2.""يَقَظَةُ الشَّعْبِ"" : اِنْبِعَاثُهُ، نَهْضَتُهُ، عَوْدَةُ قُوَّتِهِ، بَدَاهَتُهُ. ""عَصْرُ الْيَقَظَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15977, 'يَمَامٌ', 'يمام', 'جامد', 'يمم', 'يمام', 'مم', '', '', '"Ta "', 'مفرد', 'DnT', '', 'Pf', '', '', 'Rp', '', '', '', '', '', '', '"يَمَامٌ-يَمَامٌ، ةٌ [ي م م] (حو).: جِنْسُ طَيْرٍ مِنْ فَصِيلَةِ الْحَمَامِيَّاتِ، بَرِّيٌّ، لَهُ أَجْنِحَةٌ مُتَوَسِّطَةُ الْحَجْمِ، وَمِنْقَارٌ صَغِيرٌ، وَذَنَبٌ طَوِيلٌ، سَرِيعُ الطَّيَرَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15978, 'يَمٌّ', 'يم', 'جامد', 'يمم', 'يم', 'م', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يَمٌّ-يَمٌّ [ي م م]. ""تَمْخُرُ السَّفِينَةُ الْيَمَّ"" : الْبَحْرَ، النَّهْرَ الْعَظِيمَ.الأعراف آية 136 فَانْتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَاهُمْ فِي الْيَمِّ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15979, 'يَمْنَةٌ', 'يمنة', 'جامد', 'يمن', 'يمنة', 'منة', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يَمْنَةٌ-يَمْنَةٌ [ي م ن]. ""اِتَّجَهَ يَمْنَةً"" : جِهَةَ الْيَمِينِ، خِلاَفَ الْيَسْرَةِ. ""لاَ يَعْرِفُ يَمْنَتَهُ مِنْ يَسْرَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15980, 'يُمْنَى', 'يمنى', 'جامد', 'يمن', 'يمنى', 'من', '', '', '', 'مفرد', 'Dy', '', '', '"يُمْنَيَاتٌمُثَنَّاهَايُمْنَي', 'ممنوع من الصرف', 'RwR0', '', '', '', '', '', '', '". 1.""يَسيرُ فِي الْجِهَةِ الْيُمْنَى"" : جِهَةُ الْيَمِينِ، خِلاَفُ الْيُسْرَى. 2.""أُصِيبَ بِكَسْرٍ فِي يَدِهِ الْيُمْنَى"" : أَيْ فِي يَدِهِ الَّتِي عَلَى يَمِينِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15981, 'يُمْنَيَاتٌ', 'يمنيات', 'جامد', '', 'يمنيات', 'منت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15982, 'يَمِينٌ', 'يمين', 'جامد', 'يمن', 'يمين', 'من', '', '', '', 'مفرد', 'DnN', '', '', '"أَيْمُنٌ:أَيْمَانٌ:أَيَامِنُ:', '', 'Rp', '', '', '', '', '', '', '". 1.""يَسِيرُ جِهَةَ الْيَمِينِ"" : عَلَى جِهَةِ يَدِهِ الْيُمْنَى. ""عَلَى يَمِينِهِ"". 2.""أَخَذَ الْعَصَا بِيَمِينِهِ"" : أَيْ بِيَدِهِ الْيُمْنَى.طه آية 17وَمَا تِلْكَ بِيَمِينِكَ يَا مُوسَى (قرآن). 3.الأحزاب آية 50وَمَا مَلَكَتْ يَمِينُكَ مِمَّا أَفَاءَ اللَّهُ عَلَيْكَ (قرآن) : مَا تَمْلِكُ مِنْ مَالٍ وَمُمْتَلَكَاتٍ. 4.""أَدَّى بَيْنَ يَدَيْهِ يَمِينَ الطَّاعَةِ وَالإِخْلاَصِ"" : مَرَاسِيمَ الْقَسَمِ. 5.""يَمِينَ اللَّهِ"" : قَسَماً بِاللَّهِ. 6.""هُوَ مِنْ جَمَاعَةِ الْيَمِينِ"" : أَيْ مِنَ الْجَمَاعَةِ الَّتِي لَهَا آرَاءٌ وَمَوَاقِفُ سِيَاسِيَّةٌ ذَاتُ صِبْغَةٍ مُحَافِظَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15983, 'أَيْمُنٌ', 'أيمن', 'جامد', '', 'ءيمن', 'من', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15984, 'أَيْمَانٌ', 'أيمان', 'جامد', '', 'ءيمان', 'من', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15985, 'أَيَامِنُ', 'أيامن', 'جامد', '', 'ءيامن', 'من', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15986, 'أَيَامِينُ', 'أيامين', 'جامد', '', 'ءيامين', 'من', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15987, 'يَمَنُ', 'يمن', 'جامد', '', 'يمن', 'من', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', 'N', 'O', 'N', 'O', '', '": مِنَ الْبُلْدَانِ الْعَرَبِيَّةِ (الْجُمْهُورِيَّةُ الْيَمَنِيَّةُ). عَاصِمَتُهَا صَنْعَاءُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15988, 'يناير', 'يناير', 'جامد', '', 'يناير', 'نر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ الأَوَّلُ مِنَ الشُّهُورِ الْغَرْبِيَّةِ الْمِيلاَدِيَّةِ، أَيَّامُهُ (31) يَوْماً. ن. كَانُونُ الثَّانِي."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15989, 'يَنَعٌ', 'ينع', 'جامد', 'ينع', 'ينع', 'نع', '', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يَنَعٌ-يَنَعٌ [ي ن ع]. 1. : نَوْعٌ مِنَ الْعَقِيقِ يَخْتَلِفُ لَوْنُهُ مِنْ أَحْمَرَ مُدَمّـىً إِلَى أَحْمَرَ ضَارِبٍ إِلَى صُفْرَةٍ. 2.: خَرَزٌ أَحْمَرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15990, 'يَيْنَمِيَّةٌ', 'يينمية', 'جامد', 'ينم', 'يينمية', 'نمة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"يَيْنَمِيَّةٌ-يَيْنَمِيَّةٌ [ي ن م]. : خُوذَةٌ صُلْبَةٌ يَضَعُهَا رَاكِبُ الدَّرَّاجَةِ النَّارِيَّةِ عَلَى رَأْسِهِ لِوِقَايَتِهِ إِذا ما تَعَرَّضَ لِحَادِثَةِ سَيْرٍ. ""لاَ يَرْكَبُ دَرَّاجَتَهُ النَّارِيَّةَ بِلا يَيْنَمِيَّةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15991, 'يَهْمَاءُ', 'يهماء', 'جامد', 'يهم', 'يهماء', 'هم', '', '', '', 'مفرد', '', '', '', '"يُهْمٌ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". ""تَاهَ فِي الْيَهْمَاءِ"" : فِي الصَّحْرَاءِ الْقَاحِلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15992, 'يُهْمٌ', 'يهم', 'جامد', '', 'يهم', 'هم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15993, 'يُوبِيل', 'يوبيل', 'جامد', '', 'يوبيل', 'بل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"1.""الْيُوبِيلُ الْفِضِّيُّ"" : ذِكْرَى مُرُورِ خَمْسٍ وَعِشْرِينَ سَنَةً عَلَى حَدَثٍ شَخْصِيٍّ أَوْ عَامٍّ. 2.""الْيُوبِيلُ الذَّهَبِيُّ"" : ذِكْرَى خَمْسِينَ سَنَةً. 3.""الْيُوبِيلُ الْمَاسِيُّ"" : ذِكْرَى مُرُورِ خَمْسٍ وَسَبْعِينَ سَنَةً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15994, 'يودٌ', 'يود', 'جامد', '', 'يود', 'د', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', 'N', 'O', 'O', 'O', '', '": جِسْمٌ شِبْهُ مَعْدِنٍ صُلْبٌ بَنَفْسَجِيُّ اللَّوْنِ، يُوجَدُ فِي رَوَاسِبَ مِلْحِيَّةٍ وَفِي بَعْضِ أَعْشَابِ الْبَحْرِ، سَرِيعُ التَّبَخُّرِ، يُسْتَخْدَمُ فِي تَحْضِيرِ الْعَقَاقِيرِ الطِّبِّيَّةِ وَبَعْضِ الأَصْبَاغِ وَفِي التَّصْوِيرِ الشَّمْسِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15995, 'يُورَانْيُوم', 'يورانيوم', 'جامد', '', 'يورانيوم', 'رنم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'O', 'O', '', '": عُنْصُرٌ مُشِعٌّ يُسْتَعْمَلُ فِي الصِّنَاعَةِ النَّوَوِيَّةِ مَادَّةً مُتَفَجِّرَةً فِي الْقُنْبُلَةِ النَّوَوِيَّةِ، وَيُوجَدُ الْيُورَانْيُوم فِي الْمِيَاهِ الطَّبِيعِيَّةِ وَ الأَتْرِبَةِ وَتُسْتَعْمَلُ أَمْلاَحُ اليورانيوم فِي التَّصْوِيرِ وَصِنَاعَةِ الزُّجَاجِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15996, 'يُولْيه', 'يوليه', 'جامد', '', 'يوليه', 'له', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ السَّابِعُ، وَهُوَ مِنَ الشُّهُورِ الْغَرْبِيَّةِ الْمِيلاَدِيَّةِ، عَدَدُ أَيَّامِهِ (31) يَوْماً. يَأْتِي بَعْدَ يونيه. ن. تموز."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15997, 'أيَّامٌ', 'أيام', 'جامد', 'يوم', 'ءيام', 'م', '', '', '', 'مفرد', '', '', '', '"مفرديَوْم"', '', '', '', '', '', '', '', '', '". 1.""اِنْتَظَرَهُ اليَوْمَ كُلَّهُ"" : أيْ مِنْ طُلُوعِ الفَجْرِ إلَى غُرُوبِ الشَّمْسِ، وَالجَمْعُ يُشَكِّلُ زَمَناً مُطْلَقاً. ""فِي يَوْمٍ مِنَ الأيَّامِ"". 2.""أيَّامُ اللَّهِ"" : نِعَمُهُ وَنِقَمُهُ. 3.""كَانَتْ لِلْعَرَبِ أيَّامٌ"" : وَقَائِعُ وَحُرُوبٌ. 4.""عَلَى مَرِّ الأيَّامِ"": طَوَالَ الزَّمَانِ. 5.""الأيَّامُ بَيْنَنَا يَارَجُلُ"": تَعْبِيرٌ يُقْصَدُ مِنْ وَراَئِهِ الصَّبْرُ والانْتِظَارُ إلَى أنْ يَسْتَرْجِعَ مَعَ الزَّمَنِ حَقَّهُ وَمَا ضَاعَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15998, 'مُيَاوِمٌ', 'مياوم', 'جامد', 'يوم', 'مياوم', 'مم', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُيَاوِمٌ-مُيَاوِمٌ [ي و م]. ""عَامِلٌ مُيَاوِمٌ"" : عَامِلٌ يَشْتَغِلُ بِاليَوْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(15999, 'يَوْمِيَّاتٌ', 'يوميات', 'جامد', 'يوم', 'يوميات', 'مت', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"يَوْمِيَّاتٌ-يَوْمِيَّاتٌ [ي و م]. 1.""يُسَجِّلُ يَوْمِيَّاتِهِ"" : مَا يَحْدُثُ خِلاَلَ الْيَوْمِ وَمَا يُفَكِّرُ فِيهِ يُسَجَّلُ للِذِّكْرَى وَالتَّذْكِيرِ. 2.""صَحَفِيٌّ بَارِعٌ فِي كِتَابَةِ الْيَوْمِيَّاتِ"" : مَقَالاَتٌ يَوْمِيَّةٌ تَتَضَمَّنُ خَوَاطِرَ شَخْصِيَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16000, 'يَوْمِيَّةٌ', 'يومية', 'جامد', 'يوم', 'يومية', 'مة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"يَوْمِيَّةٌ-يَوْمِيَّةٌ [ي و م]. 1.""يَتَقَاضَى فِي كُلِّ مَسَاءٍ يَوْمِيَّةً"" : أُجْرَةَ يَوْمِهِ. 2.""سَجَّلَ الْفِكْرَةَ فِي الْيَوْمِيَّةِ"" : فِي مُذَكِّرَتِهِ، فِي مُفَكِّرَتِهِ. 3.""الْيَوْمِيَّةُ السَّنَوِيَّةُ"" : جَدْوَلٌ بِأَيَّامِ السَّنَةِ وَشُهُورِهَا وَأَعْيَادِهَا، رُزْنَامَة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16001, 'يَوْمٌ', 'يوم', 'جامد', 'يوم', 'يوم', 'م', '', '', '', 'مفرد', 'DnN', '', '', '"أَيَّامٌ"', '', 'R', '', '', '', '', '', '', '". 1.""مَضَى الْيَوْمُ "" : الْوَقْتُ الْمُمْتَدُّ مِنْ طُلُوعِ الشَّمْسِ إِلَى غُرُوبِهَا. 2.""الْيَوْمُ فَلَكِيّاً"" : زَمَنُ دَوَرَانِ الأَرْضِ حَوْلَ مِحْوَرِهَا، وَمُدَّتُهُ أَرْبَعٌ وَعِشْرُونَ سَاعَةً. 3.""الْيَوْمُ شَرْعاً"" : الْوَقْتُ الْمُمْتَدُّ مِنَ الْفَجْرِ إِلَى غُرُوبِ الشَّمْسِ، كَمَا يَتِمُّ مُرَاعَاةُ ذَلِكَ أَيَّامَ رَمَضَانَ. ""أَيَّامُ الأُسْبُوعِ هِيَ : يَوْمُ الأَحَدِ وَالاثْنَيْنِ وَالثُّلاَثَاءِ وَالأَرْبِعَاءِ وَالْخَمِيسِ وَالْجُمُعَةِ وَالسَّبْتِ. 4.المائدة آية 3الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُم (قرآن) : زَمَنُ التَّكَلُّمِ وَوَقْتُهُ. 5.""ذَاتَ يَوْمٍ"" : فِي زَمَنٍ أَوْ وَقْتٍ مَّا. ""حَدَثَ فِي يَوْمٍ مَّا"". 6.""أَيَّامُ الْعَرَبِ"" : وَقَائِعُهَا، حُرُوبُهَا. 7.""أَيَّامُ اللَّهِ"" : نِقَمُهُ فِي الأُمَمِ الْمَاضِيَةِ، كَمَا يَأْتِي بِمَعْنَى نِعَمِـهِ :إبراهيم آية 5 وَذَكِّرْهُمْ بِأَيَّامِ اللَّهِ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِكُلِّ صَبَّارٍ شَكُورٍ (قرآن). ""يَوْمٌ لَكَ وَيَوْمٌ عَلَيْكَ"" l ""خَبِّئْ قِرْشَكَ الأَبْيَضَ لِيَوْمِكَ الأَسْوَدِ"" l ""تَتَعَاقَبُ الأَيَّامُ وَلاَ تَتَشَابَهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16002, 'أَيَّامٌ', 'أيام', 'جامد', '', 'ءيام', 'م', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16003, 'يُونِيسْكُو', 'يونيسكو', 'جامد', '', 'يونيسكو', 'نسك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '": اِخْتِزَالٌ لاسْمِ مُنَظَّمَةِ الأُمَمِ الْمُتَّحِدَةِ للِتَّرْبِيَةِ وَالْعُلُومِ وَالثَّقَافَةِ، أَنْشَأَتْهَا الأُمَمُ الْمُتَّحِدَةُ سنة 1946م، لِغَايَةِ إِقْرَارِ الأَمْنِ وَالسَّلاَمِ الْعَالَمِيَّيْنِ مِـنْ خِلاَلِ الْعَمَلِ عَلَى إِشَاعَةِ التَّرْبِيةِ وَالْعُلُومِ وَالثَّقَافَةِ بَيْنَ الأُمَمِ، وَالتَّعَاوُنِ فِيمَا بَيْنَهَا فِي هَذِهِ الْمَيَادِينِ وَتَأْكِيدِ مَبَادِئِ احْتِرَامِ حُقُوقِ الإِنْسَانِ، يُوجَدُ مَقَرُّهَا الْمَرْكَزِيُّ فِي بَاريس."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16004, 'يُونِيسِيف', 'يونيسيف', 'جامد', '', 'يونيسيف', 'نسف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'O', 'N', 'O', '', '": اِخْتِصَارٌ لاسْمِ : صُنْدُوقُ الأُمَمِ الْمُتَّحِدَةِ الدَّوْلِيُّ لِرِعَايَةِ الطُّفُولَةِ، وَهِيَ مُنَظَّمَةٌ لَهَا هَـدَفٌ إِنْسَانِـيٌّ لِمُسَاعَدَةِ أَطْفَالِ الْعَالَمِ وَإِغَاثَتِهِمْ، أَنْشَأَتْهَا الأُمَمُ الْمُتَّحِدَةُ سَنَةَ 1946م."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16005, 'يُونِيه', 'يونيه', 'جامد', '', 'يونيه', 'نه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', 'N', 'N', 'N', 'O', '', '": الشَّهْرُ السَّادِسُ، وَهُوَ مِنَ الشُّهُورِ الْغَرْبِيَّةِ الْمِيلاَدِيَّةِ عَدَدُ أَيَّامِهِ ""30"" يَوْماً. ن. حَزِيرَان."', ':لا جذر:لا مفرد');
