INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16044, 'مَبَاذِرُ', 'مباذر', 'جامد', '', 'مباذر', 'مبذر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16045, 'سَنَةٌ', 'سنة', 'جامد', 'سنو', 'سنة', 'سنة', '', '', '', 'مفرد', 'DnN', '', '', '"سنوات:سنون"', '', '', '', '', '', '', '', '', '"مُدَّة من الزَّمن قدْرها اثنا عَشر شهراً؛ السنة الهجرية، هي السنة التي يبدأ عَدُّها عام هجرة الرسول من مكّة إلى المدينة/ السنة الميلادية، هي السنة التي يبدأ عَدُّها عامَ ولد المسيح/ السنة الشَّمسية، هي مقدار قَطعِ الشمسِ البروجَ الاثني عشر/ السنة القمرية؛ هي تمام اثنتَيْ عشرةَ دورةً للقمر/ السنة الضوئية، هي المسافة التي يقطعها الضوءُ في سنةٍ كاملة، وبها تقاس المسافات بين النجوم/ السَّنة الكبيسة هي كل سنة يُمكن قسمة الأرقام التي تدل عليها/ السنة المالية، هي المدة التي تنقضي بين موازنتَيْن/ السنة المدرسية، هي المدة التي تنقضي بين افتتاح المدارس والعُطلة الصيفية/ سِنُو الخِصبِ، هي في الطب، المُدّة ما بين البلوغ وسِن اليأس.-: الجَدْب والقحطِ.-: الأرض المُجْدِبَة ج سَنوات وسِنُون"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16046, 'سنوات', 'سنوات', 'جامد', '', 'سنوات', 'سنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16047, 'سُنَّةٌ', 'سنة', 'جامد', 'سنن', 'سنة', 'سنة', '', '', '', 'مفرد', 'DnN', '', '', '"سنن"', '', 'Rp', '', '', '', '', '', '', '"السُّنَّةُ: الطَّريقةُ؛ تكريمُ العُلماء سُنَّة حَسَنَة.-السيرة حميدةً كانت أو مذمومةً   الكهف آية 55وَمَا مَنَعَ النَّاسَ أَنْ يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُِدَى وَيَسْتَغْفِرُوا رَبَّهُمْ إِلأَّ أَنْ تَأْتِيَهُمْ سُنَّةُ الأَوَّلِينَ.-اِلطبيعةُ والخُلُقُ.-صورة الوَجْه؛ تريكَ سُنَّةَ وَجْهٍ غَيرَ مقرِفَةٍ*مَلساءَ ليس بها خالٌ ولا نَدَبُ.-في الشرع ، العملُ المحمود في الدين ممْا ليْس فَرْضا ولا واجباً/ سُنَّة اللَّهِ، هي حُكْمُهُ في خَليقتِه الأحزاب آية 62 سُنَّةُ اللَّهِ فِي الَّذِينَ خَلَوْا مِنْ قَبْلُ وَلَنْ تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلاً/ سنة النَّبي صلََى اللَّهُ عليه وسَلَّمَ، هي ما يُنْسبُ إليه من قوْل أو فِعْل أو تقرير/ أهل السنة، هُم القائلونَ بخلافة أبي بكر وعمَر عن استحقاق، ويقابلهم الشيعة ج سنن."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16048, 'سنن', 'سنن', 'جامد', '', 'سنن', 'سن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16049, 'مرو', 'مرو', 'جامد', '', 'مرو', 'مر', '', '', '"Ta "', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مرو - المَرْو حجرٌ أبيض رقيق برَّاق يُورِي النار أو أصلب الحجارة تُجعَل منهُ المظارُّ وهي كالسكاكين يُذبَح بها ويُعرَف بالصوَّان الواحدة مَرْوَة.والمَرْو جبل .والمَرْوَانِ بلدان بخراسان يقال لأحدهما مَرْو الشاهجان وللآخر مَرْوَرُوذ ويقال فيها أيضًا مَرُّوذ وقد تدخل الألف واللام فيقال مَرْوُ الرُوذ والنسبة إلى الأولى في الأناسيّ مَرْوَزِيّ بزيادة زاي على غير قياس ونسبة الثوب مَرْوِيّ بسكون الراءِ وقد تُفتَح كَعَرَبيّ. وقيل الثياب المَرْوِيَّة منسوبة إلى بلد بالعراق على شطّ الفرات والنسبة إلى الثانية على لفظها مَرْوَرُوذِيٌّ ومَرُّوذِيُّ والمَرْو أيضًا اسم جنس لأنواع الرياحين فإذا أُطلِق أُرِيد بهِ المرماحوز الواحدة مَرْوَة. المَرْوَة واحدة المَرْو كما مرَّ وجبل بمكَّة والنسبة إليهِ مَرْوِيٌّ. المَرَوْرَاة الأرض لا شيءَ فيها ج المرَوْرَي. والمَرَوْرَيَات والمَرارِي ومَرَوْرَاة أرضٌ بعينها"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16050, 'مفرد/تكسير', 'مفرد/تكسير', 'منسوب', '', 'مفرد/تكسير', 'مفرد/تكسر', '', 'س', 'التأنيث', 'جمع تكسير', 'التثنية', 'مؤ', '"ج', 'لف', '', '"ج', 'س', 'نسب', 'المنقوص', '"تنوين النصب"', '"', 'مذ', 'ك', ':لا جذر:لا مفرد:لا تشكيل');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16051, 'ذِمِّيٌّ', 'ذمي', 'منسوب', 'ذمم', 'ذمي', 'ذم', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". ""رَجُلٌ ذِمِّيٌّ"" : الَّذِي أُعْطِيَ الذِّمَّةَ، أَيْ أُعْطِيَ الع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16052, 'نَاصِرِيٌّ', 'ناصري', 'منسوب', 'نصر', 'ناصري', 'نصر', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". 1.(مَنْسُوبٌ إِلَى مَدِينَةِ النَّاصِرَةِ بِفِلِسْطِينَ) : يَسُوعُ النَّاصِرِيُّ. 2.""نَاصِرِيٌّ"": الْمُعْتَنِقُ لآرَاءِ وَأَفْكَارِ الرَّئِيسِ الْمِصْرِيِّ الرَّاحِلِ جَمَالِ عَبْدِ النَّاصِرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16053, 'مِيكَانِيكِيٌّ', 'ميكانيكي', 'منسوب', '', 'ميكانيكي', 'مكنك', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون. ن. مِيكَانِيٌّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16054, 'مِيكَانِيٌّ', 'ميكاني', 'منسوب', '', 'ميكاني', 'مكن', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون. ""عَامِلٌ مِيكَانِيٌّ"" : الَّذِي يَقُومُ بِإِصْلاَحِ مَا لَهُ عَلاَقَةٌ بِالآلاَتِ الْمِيكَانِيكِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16055, 'إقْطَاعِيٌّ', 'إقطاعي', 'منسوب', 'قطع', 'ءقطاعي', 'إقطع', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". 1.: الْمالِكُ لِلإقْطَاعَةِ عَلَى نِظامِ الإقْطَاعِ. ""كانَ إقْطَاعِياًّ يَمْلِكُ الأرَاضِيَ الكَثِيرَةَ وَيُشَغِّلُ النَّاسَ كالعَبِيدِ"". 2.""اِنْقَضَى العَهْدُ الإقْطَاعِيُّ"" : زَمَنُ سَيْطَرَةِ نِظَامِ الإقْطَاعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16056, 'مُعْجَمَاتِيٌّ', 'معجماتي', 'منسوب', 'عجم', 'معجماتي', 'معجمت', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". ""عَالِمٌ مُعْجَمَاتِيٌّ"" : مُخْتَصٌّ بِصِنَاعَةِ الْمُعْجَمَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16057, 'صَحَفِيٌّ', 'صحفي', 'منسوب', 'صحف', 'صحفي', 'صحف', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". ن.صِحَافِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16058, 'صِحَافِيٌّ', 'صحافي', 'منسوب', 'صحف', 'صحافي', 'صحف', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". ""صِحَافِيٌّ نَشِيطٌ"" : مَنْ يُزَاوِلُ مِهْنَةَ الصِّحَافَةِ وَيُقَالُ لَهُ أَيْضاً صَحَفِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16059, 'رِواقِيٌّ', 'رواقي', 'منسوب', 'روق', 'رواقي', 'رق', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". : مَنْ كانَ عَلَى مَذْهَبِ الرِّواقِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16060, 'رَمْزِيٌّ', 'رمزي', 'منسوب', 'رمز', 'رمزي', 'رمز', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". : مَنْ كانَ على مَذْهَبِ الرَّمْزِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16061, 'دُهْرِيٌّ', 'دهري', 'منسوب', 'دهر', 'دهري', 'دهر', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". 1.""شَيْخٌ دُهْرِيٌّ"" : قَديمٌ مُسِنٌّ طالَ عَلَيْهِ الزَّمَنُ. ""صَخْرٌ دُهْرِيٌ"". 2.""وَلَدٌ دُهْرِيٌّ"" : حاذِقٌ، ماهِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16062, 'خَيْمِيٌّ', 'خيمي', 'منسوب', 'خيم', 'خيمي', 'خم', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '".: صَانِعُ الخِيَامِ وَبَائِعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16063, 'حَوَارِيٌّ', 'حواري', 'منسوب', '', 'حواري', 'حر', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون. 1. ""هُوَ مِنْ حَوَارِيِّ الأَمِيرِ"" : خَاصَّتُهُ، مِنْ أصْحَابِهِ، الخَالِصُ النَّقِيُّ مِنْ كُلِّ عَيْبٍ وَالْمُبَالِغُ فِي الْمُوَالاَةِ. 2.""الحَوَاريُّونَ"" : رُسُلُ السَّيِّدِ الْمَسِيحِ وَأنْصَارُهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16064, 'حَلْوانِيٌّ', 'حلواني', 'منسوب', 'حلو', 'حلواني', 'حلن', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '".: صَانِعُ، الحَلْوَاءِ، بائِعُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16065, 'جَنَائِزِيٌّ', 'جنائزي', 'منسوب', '', 'جناءزي', 'جنز', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون. 1.""حَمَلَ الجَنَائِزِيُّونَ نَعْشَ الْمَيِّتِ"": مَنْ يَحْمِلُونَ نَعْشَ الْمَيِّتِ فِي مَوْكِبِ الجِنَازَةِ. 2.""رَتَّلَ الجَنَائِزِيُّ لَحْناً جَنَائِزِيّاً"" : مَنْ يَقْرَأُ أَمَامَ نَعْشِ الْمَيِّتِ فِي مَوْكِبِ الجَنَازَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16066, 'إكْلِيرِيكِيٌّ', 'إكليريكي', 'منسوب', '', 'ءكليريكي', 'إكلرك', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون. : مَنْ يُرَبَّى وَيُثَقَّفُ فِي الإِكْلِيرِيكِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16067, 'برغماتيٌّ', 'برغماتي', 'منسوب', '', 'برغماتي', 'برغمت', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
