INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16069, 'باروديٌٌّ', 'بارودي', 'منسوب', '', 'بارودي', 'برد', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عامل مصنع بارود"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16070, 'يَمِينِيٌّ', 'يميني', 'منسوب', 'يمن', 'يميني', 'من', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". ""نَائِبٌ يَمِينِـيٌّ"" : الْمُحَافِظُ فِي سِيَاسَتِهِ وَالْمُتَمَسِّكُ بِآرَاءٍ وَمَوَاقِفَ لَهَا طَابَعُ الْحِفَاظِ عَلَى مَا هُوَ سَائِدٌ خِلاَفَ الْيَسَارِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16071, 'وَهَّابِيٌّ', 'وهابي', 'منسوب', 'وهب', 'وهابي', 'هب', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"وَهَّابِيٌّ-وَهَّابِيٌّ، ةٌ [و هـ ب]. ""وَهَّابِيُّ الْمَذْهَبِ"" : أَيْ مُنْتَسِبٌ إِلَى الوَهَّابِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16072, 'وُصُولٍيٌّ', 'وصولي', 'منسوب', 'وصل', 'وصولي', 'صل', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". ""رَجُلٌ وُصُولِيٌّ"" : رَجُلٌ يَسْعَى إِلَى بُلُوغِ غَايَتِهِ بِأَيِّ وَسِيلَةٍ وَمَهْمَا كَلَّفَهُ الأَمْرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16073, 'يَهُودِيٌّ', 'يهودي', 'منسوب', 'هود', 'يهودي', 'هد', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":يَهُودٌ"', '', '', '', '', '', '', '', '', '"يَهُودِيٌّ-يَهُودِيٌّ، ةٌ [هـ و د]. وَاحِدُ الْيَهُودِ. جَمْعُ مُؤَنِّثِهِ يَهُودِيَّاتٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16074, 'يَهُودٌ', 'يهود', 'منسوب', '', 'يهود', 'هد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16075, 'نَصْرَانِيٌّ', 'نصراني', 'منسوب', 'نصر', 'نصراني', 'نصرن', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":نَصَارَى"', '', '', 'ـو', '', '', '', '', '', '". 1. : الْمَسِيحِيُّ، مَنْ يَدِينُ بِدِينِ السَّيِّدِ الْمَسِيحِ. 2. : مَنْسُوبٌ إِلَى مَدِينَةِ النَّاصِرَةِ. ن. نَاصِرِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16076, 'نَصَارَى', 'نصارى', 'منسوب', '', 'نصارى', 'نصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16077, 'مِسْمَارِيٌّ', 'مسماري', 'منسوب', '', 'مسماري', 'مسمر', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '"ج"', '', '', '', '', '', '', '', '', '"""خَطٌّ مِسْمَارِيٌّ"" : خَطُّ الآشُورِيِّينَ، وَهُوَ يُشْبِهُ شَكْلَ الْمِسْمَارِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16078, 'مَجَّانِيّ', 'مجاني', 'منسوب', 'مجن', 'مجاني', 'مجن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '"ج"', '', '', '', '', '', '', '', '', '"مَجَّانِيّ-مَجَّانِيّ، ةٌ [م ج ن].: كُلُّ مَا هُوَ بِالْمَجَّانِ أَيْ بِلاَ ثَمَنٍ أَوْ مُقَابِلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16079, 'تِلْقائِيٌّ', 'تلقائي', 'منسوب', 'لقي', 'تلقاءي', 'تلق', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '"ج"', '', '', '', '', '', '', '', '', '"تِلْقائِيٌّ-تِلْقائِيٌّ، ةٌ [ل ق ي]. ""عَمَلٌ تِلْقائِيٌّ"" : عَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16080, 'لَوْذَعِيٌّ', 'لوذعي', 'منسوب', 'لذع', 'لوذعي', 'لذع', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"لَوْذَعِيٌّ-لَوْذَعِيٌّ، ةٌ [ل ذ ع]. 1. ""طَالِبٌ لَوْذَعِيٌّ"" : أَلْمَعِيٌّ ذَكِيّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16081, 'كِيمَاوِيٌّ', 'كيماوي', 'منسوب', '', 'كيماوي', 'كم', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. ن. كِيمِيَائِيٌّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16082, 'تَكْميلِيٌّ', 'تكميلي', 'منسوب', 'كمل', 'تكميلي', 'تكمل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '"ج"', '', '', '', '', '', '', '', '', '"تَكْميلِيٌّ-تَكْميلِيٌّ، ةٌ [ك م ل]. 1.""عَمَلٌ تَكْميلِيٌّ"" : إِضافِيٌّ. 2.""الْمَرْحَلَةُ التَّكْميلِيَّةُ"" : مَرْحَلَةٌ في مَدارِسِ الشَّرْقِ الأوْسطِ تَتْلُو الْمَرْحَلَةَ الابْتِدائِيَّةَ وَتَسْبِقُ الْمَرْحَلَةَ الثَّانَوِيَّةَ العاليَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16083, 'كِلاَسِيكِيٌّ', 'كلاسيكي', 'منسوب', '', 'كلاسيكي', 'كلسك', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. 1.""كَاتِبٌ كِلاَسِيكِيٌّ"" : كَاتِبٌ يَسْتَوْحِي نَمَاذِجَهُ الأَدَبِيَّةَ مِنَ التُّرَاثِ، في مُطَابَقَةٍ لِتَقَالِيدِ الأُدَبَاءِ وَالكُتَّابِ القُدَامَى. ""مُؤَلِّفٌ كِلاَسِيكِيٌّ"" ""نَمَاذِجُ كِلاَسِيكِيَّةُ"". 2.""الْمُوسِيقَى الكِلاَسِيكِيَّة"" : هِيَ الْمُوسِيقَى الَّتِي وَضَعَهَا أَعْلاَمُ الْمُوسِيقَى فِي الغَرْبِ مِثْلُ بِتْهُوفَن وَمُوزَار وَبَاخ وَغَيْرِهِمْ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16084, 'كَتَّانِيٌّ', 'كتاني', 'منسوب', 'كتن', 'كتاني', 'كتن', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". : بَائِعُ الكَتَّانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16085, 'كُتْبِيٌّ', 'كتبي', 'منسوب', 'كتب', 'كتبي', 'كتب', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". ""زَارَ الكُتْبِيَّ فِي الْمَكْتَبَةِ"" : أَيْ بَائِعَ الكُتُبِ، صَاحِبَ الْمَكْتَبَةِ، حَافِظ الكُتُبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16086, 'قَطَائِفِيٌّ', 'قطائفي', 'منسوب', 'قطف', 'قطاءفي', 'قطف', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"قَطَائِفِيٌّ، ةٌ - [ق ط ف]. : صَانِعُ الْقَطَائِفِ وَبَائِعُهَا. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16087, 'تَقَدُّمِيٌّ', 'تقدمي', 'منسوب', 'قدم', 'تقدمي', 'تقدم', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". ""رَجُلٌ تَقَدُّمِيٌّ"": مُؤْمِنٌ بِأَفْكارِ التَّقَدُّمِ والتَّطَوُّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16088, 'تَقْديريٌّ', 'تقديري', 'منسوب', 'قدر', 'تقديري', 'تقدر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '"ج"', '', '', '', '', '', '', '', '', '"تَقْديريٌّ، ةٌ - [ق د ر]. ""رَأْيٌ تَقْدِيرِيٌّ"" : رَأيٌ فيهِ تَمَهُّلٌ وتأَمُّلٌ ولا يَتَضَمَّنُ أَيَّ حُكْمٍ نِهائِيٍّ، مُجَرَّدُ تَقْديرٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16089, 'فَاكِهَانِيٌّ', 'فاكهاني', 'منسوب', 'فكه', 'فاكهاني', 'فكهن', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"فَاكِهَانِيٌّ-فَاكِهَانِيٌّ، ةٌ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16090, 'فَقْرِيٌّ', 'فقري', 'منسوب', 'فقر', 'فقري', 'فقر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '"ج"', '', '', '', '', '', '', '', '', '". 1.""الْعَمُودُ الْفَقْرِيُّ"": سِلْسِلَةُ خَرَزَاتِ الظَّهْرِ وَعَدَدُهَا ثَلاَثٌ وَثَلاَثُونَ فَقَارَةً عِنْدَ الإِنْسَانِ. 2.""حَيَوَانَاتٌ فِقْرِيَّاتٌ"" : الْحَيَوَانَاتُ الَّتِي تَشْتَمِلُ عَلَى ذَوَاتِ الْفَقَارِ كَالأَسْمَاكِ وَالطُّيُورِ وَالزَّوَاحِفِ وَالثَّدْيِيَّاتِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16091, 'فِدَائِيٌّ', 'فدائي', 'منسوب', 'فدي', 'فداءي', 'فد', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". ""فِدَائِيٌّ فِلِسْطِينِيٌّ"" : الْفِلِسْطِينِيُّ الْمُجَاهِدُ فِي سَبِيلِ تَحْرِيرِ بِلاَدِهِ مِنَ الاِحْتِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16092, 'فَاشِيٌّ', 'فاشي', 'منسوب', '', 'فاشي', 'فش', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ن. فَاشِسْتِيٌّ، ةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16093, 'غَسَّانِيٌّ', 'غساني', 'منسوب', 'غسن', 'غساني', 'غسن', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"غَسَّانِيٌّ-غَسَّانِيٌّ، ةٌ [غ س ن]. 1.""وَلَدٌ غَسَّانِيٌّ"" : جَمِيل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16094, 'عِيَانِيٌّ', 'عياني', 'منسوب', 'عين', 'عياني', 'عن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عِيَانِيٌّ-عِيَانِيٌّ، ةٌ [ع ي ن]. ""شَاهِدٌ عِيَانِيٌّ"" : الَّذِي يَشْهَدُ بِمَا رَآهُ وَعَايَنَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16095, 'عَمِيٌّ', 'عمي', 'منسوب', 'عمي', 'عمي', 'عم', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". ""رَجُلٌ عَمِيُّ الْقَلْبِ"" : جَاهِلٌ، ذُو عَمىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16096, 'عَمَلِيٌّ', 'عملي', 'منسوب', 'عمل', 'عملي', 'عمل', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عَمَلِيٌّ-عَمَلِيٌّ، ةٌ [ع م ل]. 1. إِنْجَازٌ عَمَلِيٌّ"" : فِعْلِيٌّ، تَطْبِيقِيٌّ. 2. ""الْحَيَاةُ الْعَمَلِيَّةُ"" : الْحَيَاةُ الْوَاقِعِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16097, 'عَلِيٌّ', 'علي', 'منسوب', 'علو،علي', 'علي', 'عل', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":عِلْيَةٌ"', '', '', 'ـو', '', '', '', '', '', '". 1. ""كَانَ فِي مَكَانٍ عَلِيٍّ"" : فِي مَكَانٍ مُرْتَفِعٍ.مريم آية 57 وَرَفَعْنَاهُ مَكَاناً عَلِيّاً (قرآن). 2.""هُوَ اللهُ الْعَلِيُّ الْقَدِيرُ"" : مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى، أَيْ الأَعْلَى. 3. ""عَلِيَّةُ القَومِ"" : أَشْرافُهُمْ. ""جَدِيلَةٌ تَجْرِي عَلَيْهَا الْكِبَارُ وَالصِّغَارُ وَالْعَلِيَّةُ وَالسُّفْلِيَّةُ"". (التوحيدي). 4.""عَلِيّ"" : اِسْمُ عَلَمٍ لِلْذُّكُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16098, 'عِلْيَةٌ', 'علية', 'منسوب', '', 'علية', 'علة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16099, 'عُلْوِيٌّ', 'علوي', 'منسوب', 'علو', 'علوي', 'عل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عُلْوِيٌّ-عُلْوِيٌّ، ةٌ [ع ل و]. 1. ""نُورٌ عُلْوِيٌّ"" : سَمَاوِيٌّ. 2.""الإِرَادَةُ الْعُلْوِيَّةُ"" : إِرَادَةُ اللَّهِ. 3. ""فِي الطَّابَقِ الْعُلْوِيِّ"" : الطَّابَقُ الأَعْلَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16100, 'عَقَارِيٌّ', 'عقاري', 'منسوب', 'عقر', 'عقاري', 'عقر', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عَقَارِيٌّ-عَقَارِيٌّ، ةٌ [ع ق ر]. الْمُخْتَصُّ بِالعَقَارِ. 1.""رَهْنٌ عَقَارِيٌّ"" : رَهْنُ مِلْكٍ ثَابِتٍ. 2.""ضَرِيبَةٌ عَقَارِيَّةٌ"" : ضَرِيبَةٌ مُخْتَصَّةٌ بِالأَمْلاَكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16101, 'عَفَوِيٌّ', 'عفوي', 'منسوب', 'عفو', 'عفوي', 'عف', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عَفَوِيٌّ-عَفَوِيٌّ، عَفَوِيَّةٌ [ع ف و]. ""عَفَوِيَّةُ عَمَلٍ"" : تِلْقَائِيَّتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16102, 'عَصِيٌّ', 'عصي', 'منسوب', 'عصي', 'عصي', 'عص', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". 1.""وَلَدٌ عَصِيٌّ"" : عَاصٍ. 2.""عَصِيٌّ فِي مُعَامَلَتِهِ"" : شَدِيدُ البَأْسِ. ""أَرَاكَ عَصِيَّ الدَّمْعِ شِيمَتُكَ الصَّبْرُ"". (أبو فراس الحمداني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16103, 'عَصَبِيٌّ', 'عصبي', 'منسوب', 'عصب', 'عصبي', 'عصب', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عَصَبِيٌّ-عَصَبِيٌّ، ةٌ [ع ص ب]. 1.""هُوَ عَصَبِيُّ الْمِزَاجِ"": سَرِيعُ الانْفِعَالِ، حَادُّ الطَّبْعِ. ‎""بِهِ مَرَضٌ عَصَبِيٌّ"". 2.""الْجِهَازُ العَصَبِيُّ"" : جِهَازُ الأَعْصَابِ فِي جِسْمِ الإِنْسَانِ يُدِيرُ الوَظَائِفَ الْحَيَاتِيَّةِ وَيُنَسِّقُهَا وَيَسْتَقْبِلُ مُعْطَيَاتِ الْحَوَاسِّ وَيُؤَمِّنُ الْحَرَكَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16104, 'مَعْزِيٌّ', 'معزي', 'منسوب', 'عزي', 'معزي', 'معز', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '".""رَجُلٌ مَعْزِيٌّ"": بَخيلٌ أشَدَّ البُخْلِ يُكَدِّسُ المالَ ولا يُنْفِقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16105, 'عَرَضِيٌّ', 'عرضي', 'منسوب', 'عرض', 'عرضي', 'عرض', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عَرَضِيٌّ-عَرَضِيٌّ، ةٌ [ع ر ض]. ""أَمْرٌ عَرَضِيٌّ"" : مَا يَحْدُثُ صِدْفَةً وَ هُوَ طَارِئٌ عَلَيْهِ وَزَائِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16106, 'طُفَيْلِيٌّ', 'طفيلي', 'منسوب', 'طفل', 'طفيلي', 'طفل', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". 1.""رَجُلٌ طُفَيْلِيٌّ"" : مَنْ يَحْضُرُ وَلِيمَةً دُونَ أَنْ يُدْعَى إِلَيْهَا، وَالكَلِمَةُ مَنْسُوبَةٌ إِلَى رَجُلٍ اِسْمُهُ طُفَيْلٌ عُرِفَ بِشَرَهِهِ. 2.""اِنْتَشَرَتِ النَّبَاتَاتُ االطُّفَيْلِيَّةُ فِي الْحَدِيقَةِ"" : حَشَائِشُ لاَ نَفْعَ فِيهَا، تَلْتَصِقُ بِسِيقَانِ النَّبَاتَاتِ وَجُذُورِ الأَشْجَارِ وَقَدْ تَمْنَعُهَا مِنَ النُّمُوِّ الطَّبِيعِيِّ. 3.""حَيَوَانَاتٌ طُفَيْلِيَّةٌ"" : مِثْلُ القُمَّلِ وَالبَرْغُوثِ وَمَا إِلَى ذَلِكَ مِنَ الْحَشَرَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16107, 'صَلِيبِيٌّ', 'صليبي', 'منسوب', 'صلب', 'صليبي', 'صلب', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". 1.: مَنِ اشْتَرَكَ فِي الْحَرْبِ الصَّلِيبِيَّةِ. 2.: مَنِ اشْتَرَكَ فِي صَلِيبِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16108, 'شَعْرَانِيٌّ', 'شعراني', 'منسوب', 'شعر', 'شعراني', 'شعرن', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"شَعْرَانِيٌّ-شَعْرَانِيٌّ، ةٌ [ش ع ر].""رَجُلٌ شَعْرَانِيٌّ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16109, 'مَسْرَحِيٌّ', 'مسرحي', 'منسوب', 'سرح', 'مسرحي', 'مسرح', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '".: مَا هُوَ مُخْتَصٌّ بِالْمَسْرَحِ. 1.""الفَنُّ الْمَسْرَحِيُّ"" : كُلُّ مَجَالٍ مُتَعَلِّقٍ بِالْمَسْرَحِ مِنْ إِخْرَاجٍ وَأَدَاءٍ وَإِضَاءةٍ. 2.""مُؤَلِّفٌ مَسْرَحِيٌّ"" : مَنْ يُؤَلِّفُ رِوَايَاتٍ تَمْثِيلِيَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16110, 'سُدَاسِيٌّ', 'سداسي', 'منسوب', 'سدس', 'سداسي', 'سدس', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"سُدَاسِيٌّ-سُدَاسِيٌّ، ةٌ [س د س]. 1. ""فِعْلٌ سُدَاسِيٌّ"" : فِعْلٌ مَزِيدٌ مِنْ سِتَّةِ أحْرُفٍ مِثْلَ اسْتَخْرَجَ. ""زَمْهَرِيرٌ"" :كَلِمَةٌ سُدَاسِيَّةٌ. 2. ""الْمُضَلَّعُ السُّدَاسِيُّ"" (هن) : مُكَوَّنٌ مِنْ سِتَّةِ أضْلُعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16111, 'رُومانْسِيٌّ', 'رومانسي', 'منسوب', '', 'رومانسي', 'رمنس', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. : مَنْ يَعْتَمِدُ تَيَّارَ الحَرَكَةِ الرُّومانِسِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16112, 'رُومِيٌّ', 'رومي', 'منسوب', '', 'رومي', 'رم', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ن. رُومانِيٌّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16113, 'رَسْمِيٌّ', 'رسمي', 'منسوب', 'رسم', 'رسمي', 'رسم', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""عَمَلٌ رَسْمِيٌّ"" : عَمَلٌ يَكْتَسِي صِبْغَةً حُكُومِيَّةً حَسَبَ الأُصُولِ الْمُقَرَّرَةِ. 2.""بَلاغٌ رَسْمِيٌّ"" : بَلاغٌ صَادِرٌ عَنِ السُّلُطَاتِ العُلْيَا فِي الدَّوْلَةِ. 3.""لِبَاسٌ رَسْمِيٌّ"" : لِبَاسٌ حَسَبَ الأُصُولِ الْمُقَرَّرَةِ. 4.""وَرَقَةٌ رَسْمِيَّةٌ"" : وَرَقَةٌ صَادِرَةٌ عَن إدَارَةٍ حُكُومِيَّةٍ. 5.""عُقُودٌ رَسْمِيَّةٌ"": عُقُودٌ تَحْمِلُ خَوَاتِمَ إدَارِيَّةً وَيُحَرِّرُهَا مُوَثِّقُونَ. 6.""رَسْمِيّاً"" : مِنَ الجَانِبِ الْمُتَعَلِّقِ بِالرَّسْمِيَّاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16114, 'رُسوبِيٌّ', 'رسوبي', 'منسوب', 'رسب', 'رسوبي', 'رسب', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رُسوبِيٌّ-رُسوبِيٌّ، ةٌ [ر س ب].: كُلُّ ما هُوَ مُرَكَّبٌ مِنَ الرُّسوبِ كَالأَتْرِبَةِ والأَحْجارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16115, 'رَجْعِيٌّ', 'رجعي', 'منسوب', 'رجع', 'رجعي', 'رجع', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". ""اِتَّخَذَ مَوْقِفاً رَجْعِيّاً"" : مُتَخَلِّفاً، أيْ مَنْ يَتَشَبَّثُ بِتَقَالِيدَ بَالِيَةٍ تَحُولُ دُونَ التَّقَدُّمِ. ""هُوَ رَجْعِيّ فِي سُلُوكِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16116, 'رَادِيكالِيٌّ', 'راديكالي', 'منسوب', '', 'راديكالي', 'ردكل', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (فل). ""رَجُلٌ رَاديكَالِيٌّ"". مَنْسُوبٌ إلى الرَّاديكَالِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16117, 'دَوْرِيٌّ', 'دوري', 'منسوب', 'دور', 'دوري', 'در', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""قامَ الجُنْدُ بِدَوْرِيَّةٍ ليْلِيَّةٍ"" : اِسْتِطْلاعٌ، الجَوْلَةُ الَّتِي تُؤَدِّيها فِرْقَةٌ عَسْكَرِيَّةٌ أَوْ فِرْقَةٌ لِلْحِراسَةِ لِلْوُقوفِ على الأَحْوالِ وَاسْتِقْصاءِ الْمَعْلوماتِ. ""اِمْتَلأَتِ الطُّرُقُ بِالدَّوْرِيَّاتِ ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16118, 'دُنِياوِيٌّ', 'دنياوي', 'منسوب', '', 'دنياوي', 'دن', '', '', 'Ta', 'جمع تكسير', 'DnT', '', '', '', '', '', '', '', '', '', '', '', '"ن. دُنْيَوِيٌّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16119, 'اِخْتِيَارِيٌّ', 'اختياري', 'منسوب', 'خير', 'اختياري', 'ختر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"اِخْتِيَارِيٌّ-اِخْتِيَارِيٌّ، ةٌ [خ ي ر]. 1. ""مَادَّةٌ اخْتِيَارِيَّةٌ فِي الامْتِحَانِ"" : يُمْكِنُ أوْ لا يُمْكِنُ الاخْتِبَارُ فِيهَا. 2. ""قُمْتُ بِعَمَلِي اخْتِيَارِيّاً"" : طَوْعاً، مِنْ تِلْقَاءِ نَفْسِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16120, 'اِختِصَاصِيٌّ', 'اختصاصي', 'منسوب', 'خصص', 'اختصاصي', 'ختصص', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". ""هَذَا الطَّبِيبُ اخْتِصَاصِيٌّ فِي أَمْرَاضِ العُيُونِ"" : لَهُ مَعْرِفَةٌ دَقيقَةٌ بِكلِّ مَا يَتَعَلّقُ بِأمْرَاضِهَا، وَهُوَ مُتَفَرِّغٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16121, 'مَخْزَنِيٌّ', 'مخزني', 'منسوب', 'خزن', 'مخزني', 'مخزن', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مَخْزَنِيٌّ-مَخْزَنِيٌّ، ةٌ [خ ز ن]. ""قَرَارٌ مَخْزَنِيٌّ"" : ق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16122, 'أَجْنَبِيٌّ', 'أجنبي', 'منسوب', 'جنب', 'ءجنبي', 'جنب', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":ـأت:أجَانِبُ"', '', '', 'ـو', '', '', '', '', '', '". 1.""هَذَا الرَّجُلُ أجْنَبيٌّ عَنِ البَلَدِ"" : غَرِِيبٌ، إنْسَانٌ مِنْ بَلَدٍ آخَرَ. 2.""زَارَ بُلْدَاناً أَجْنَبِيَّةً كَثِيرَةً"" : بُلْدَانَ الآخَرِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16123, 'أجَانِبُ', 'أجانب', 'منسوب', '', 'ءجانب', 'جنب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16124, 'جَلِيٌّ', 'جلي', 'منسوب', 'جلو', 'جلي', 'جل', '', '', 'Ta', 'مفرد', 'DnT', '', '', '', '', '', '', '', '', '', '', '', '"جَلِيٌّ-جَلِيٌّ، ةٌ [ج ل و]. 1.""جَاءَ جَوَابُهُ جَلِيّاً"" : وَاضِحاً، بَيِّناً. ""كَانَتْ أَفْكَارُهُ جَلِيَّةً لاَ غُمُوضَ فِيهَا"" ""جَلِيٌّ أَنَّ النَّصْرَ آتٍ"". 2.""إِنَاءٌ جَلِيٌّ"" : مَصْقُولٌ. 3.""جَلِيَّةُ الأَمْرِ"": حَقِيقَتُهُ. 4.""لَهُ عَيْنٌ جَلِيَّةٌ"" : نَافِذَةٌ، بَصِيرَةٌ. 5.""حَقِيقَةٌ جَلِيَّةٌ"": حَقِيقَةٌ سَاطِعَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16125, 'جَبْرِيٌّ', 'جبري', 'منسوب', 'جبر', 'جبري', 'جبر', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"جَبْرِيٌّ، ةٌ - [ج ب ر]. : مَنْ كَانَ عَلَى مَذْهَبِ الْجَبْرِيَّةِ وَمُعْتَنِقِيهِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16126, 'ثُنائِيٌّ', 'ثنائي', 'منسوب', 'ثني', 'ثناءي', 'ثن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"ثُنائِيٌّ-ثُنائِيٌّ، ةٌ [ث ن ي]. 1.""لَفْظٌ ثُنائِيٌّ"" : لَفْظٌ مُؤَلَّفٌ مِنْ حَرْفَيْنِ. 2.""غِناءٌ ثُنائِيٌّ"" : غِناءٌ يَشْتَرِكُ فِيهِ اثْنانِ. 3.""حِلْفٌ ثُنائِيٌّ"" : حِلْفٌ بَيْنَ دَوْلَتَيْنِ أَوْ طَرَفَيْنِ. 4.""طالِبٌ ثُنائِيُّ اللُّغَةِ"" : يَتَكَلَّمُ لُغَتَيْنِ. 5.""مُعْجَمٌ ثُنائِيٌّ"" : مُعْجَمٌ يَشْرَحُ مُفْرَداتِ لُغَتَيْنِ: مثلا مِنَ العَرَبِيَّةِ إلى الفرنسيَّةِ أَو مِنَ الفرنسيَّة إلى العربِيَّةِ. 6.""ثُنائِيَّةُ اللُّغَةِ"" : وُجودُ لَغَةٍ واحِدَةٍ عِنْدَ شَعْبٍ بِمُسْتَوَيَيْنِ مُخْتَلِفَيْنِ كالعَامِيَّةِ والفُصْحَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16127, 'تِقْنِيٌّ', 'تقني', 'منسوب', '', 'تقني', 'تقن', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. ""رَجُلٌ تِقْنِيٌّ"" : رَجُلٌ مُخْتَصٌّ بِتِقْنِيَّاتِ فَنٍّ أَوْ مِهْنَةٍ أَوْ حِرْفَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16128, 'بَديهِيٌّ', 'بديهي', 'منسوب', 'بده', 'بديهي', 'بده', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""قَضِيَّةٌ بَديهِيَّةٌ لا تَحْتاجُ إلى إِثْباتٍ"" : بَيِّنَةٌ، جَلِيَّةٌ، وَاضِحَةٌ. لاَ تَحْتاجُ في تَأْيِيدِها إلى أَدِلَّةٍ، واضِحَةٍ في ذاتِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16129, 'بَدائِيٌّ', 'بدائي', 'منسوب', 'بدأ', 'بداءي', 'بد', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"بَدائِيٌّ-بَدائِيٌّ، ةٌ [ب د أ]. 1.""رَجُلٌ بَدَائِيٌّ"" : فِطْرِيٌّ، أوَّلِيٌّ. 2.""أعْمالُهُ بَدائيَّةٌ"" : ساذَجَةٌ، مُتَخلِّفَةٌ. 3.""الشُّعُوبُ البَدَائِيَّةُ"" : الشُّعُوبُ فِي أوَّلِ نَشْأتِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16130, 'أُورْثُوذُكْسِيٌّ', 'أورثوذكسي', 'منسوب', '', 'ءورثوذكسي', 'رثذكس', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": واحِدُ أُورثوذُكْس."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16131, 'أَنْدَلُسِيٌّ', 'أندلسي', 'منسوب', '', 'ءندلسي', 'ندلس', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": نِسْبَةً إلى بِلادِ الأَنْدَلُسِ. ""الحَضارةُ الأنْدَلُسِيَّةُ""، ""الشِّعْرُ الأنْدَلُسِيُّ"": أَيْ ما لَهُ عَلاقَةٌ بالأَنْدَلُسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16132, 'أَنانِيٌّ', 'أناني', 'منسوب', '', 'ءناني', 'نن', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج:ـون، ـات. (أنا). ""أَنانِيٌّ لاَ يَرَى إِلاَّ نَفْسَهُ"" : مَنْ يُحِبُّ نَفْسَهُ حُبّاً مُفْرِطاً وَلاَ يُفَكِّرُ في غَيْرِهِ، الْمُعْجَبُ بِذاتِهِ. ""لَيْسَ لِلأَنَانِيِّ صاحِبٌ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16133, 'أُسْطُوانِيٌّ', 'أسطواني', 'منسوب', '', 'ءسطواني', 'سطن', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '": نِسْبَةٌ إلى الأُسْطُوانَةِ. ""شَكْلٌ أُسْطوانِيٌّ أو جِسْمٌ أُسْطُوانِيٌّ"": عَلَى هَيْئَةِ أُسْطُوانَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16134, 'أثَرِيٌّ', 'أثري', 'منسوب', 'أثر', 'ءثري', 'ثر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"أثَرِيٌّ-أثَرِيٌّ، ةٌ [أ ث ر]. 1.""قَصْرٌ أثَرِيٌّ"" : قَدِيمٌ، أيْ مِنَ الآثارِ القَدِيمَةِ. 2.""هُوَ عَالِمٌ أَثَرِيٌّ"" : بَاحِثٌ وَعَالِمٌ في الآثَارِ. 3.""زَارَ الْمُتْحَفَ الأثَرِيَّ"" : قَصْرٌ لِلعُمُوم تُوضَعُ فِيهِ التُّحَفُ الفَنِّيَّةُ وَكُلُّ مَا لَهُ قِيمَةٌ تَاريِخِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16135, 'أبَدِيٌّ', 'أبدي', 'منسوب', 'أبد', 'ءبدي', 'بد', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"أبَدِيٌّ-أبَدِيٌّ، ة [ أ ب د]. 1.""الَّلهُ الأبَدِيُّ"" : الخَالِدُ، الدَّائِمُ، مَا لاَ نِهَايَةَ لَهُ. 2.""يَأْمُلُ الْمُؤمِنُ فِي أبَدِيَّةٍ خَالِدَةٍ"" : الآخِرَةُ. ""لاَ أطْمَعُ فِي لِقَائِهَا إلاَّ فِي الأبَدِيَّةِ"". (جبران خ. جبران)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16136, 'عَفْوِيٌّ', 'عفوي', 'منسوب', 'عفو', 'عفوي', 'عف', 'مُتَعَلِّقٌ بِالعَفْوِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عَفْوِيٌّ-عَفْوِيٌّ، ةٌ [ع ف و] (مُتَعَلِّقٌ بِالعَفْوِ). ""عَمَلٌ عَفْـوِيٌّ"" : تِلْقَائِيٌّ، أَيْ دُونَ إِعْمَالِ الفِكْرِ. ""إِشَارَةٌ عَفْوِيَّةٌ"" ""حَرَكَةٌ عَفْوِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16137, 'بُؤْرِيٌّ', 'بؤري', 'منسوب', '', 'بءري', 'بر', 'خاص بالبؤرة', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16138, 'جِنْسِيٌّ', 'جنسي', 'منسوب', 'جنس', 'جنسي', 'جنس', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"جِنْسِيَّةٌ-جِنْسِيَّةٌ [ج ن س] (صف). ""هُوَ مِنْ جِنْسِيَّةٍ مَغْرِبِيَّةٍ"" : الانْتِسَابُ، الانْتِمَاءُ إِلَى بَلَدِ الْمَغْرِبِ، وَالجِنْسِيَّةُ تَكُونُ أَصْلِيَّةً بِحُكْمِ الْمَوْلِدِ وَالنَّشْأَةِ، أَوْ مُكْتَسَبَةً بِحُكْمِ العَيْشِ فِي البَلَدِ فَتْرَةً مُعَيَّنَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16139, 'قَلَوِيٌّ', 'قلوي', 'منسوب', 'قلو', 'قلوي', 'قل', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(صِفَة لِكُلِّ مادَّةٍ لَها خَواصُّ القَلْيِ). ""مُرَكَّبَاتٌ قَلَوِيَّةٌ"" : مُرَكَّبَاتٌ كِيمَاوِيَّةٌ مِنْ مَعْدِنٍ وَأُوكسِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16140, 'أُوتُومَاتِيكِيٌّ', 'أوتوماتيكي', 'منسوب', '', 'ءوتوماتيكي', 'تمتك', 'مَنْسُوبٌ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"""تَشْتَغِلُ هَذِهِ الآلَةُ أُتُومَاتِيكِيّاً"" : تَتَحَرَّكُ ذَاتِيَّا، آليًّا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16141, 'اِنْتِخابِيٌّ', 'انتخابي', 'منسوب', '', 'انتخابي', 'نتخب', 'مَنْسُوبٌ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"""سَتَبْدَأُ الحَمْلَةُ الانْتِخابِيَّةُ في بِدايَةِ الأسْبوعِ الْمُقْبِلِ"" : الدِّعايَةُ لِلْمُرَشَّحينَ الَّذينَ سَيَنْتَخِبُهُمُ الْمُنْتَخِبُونَ. ""مَعْرَكَةٌ انْتِخابِيَّةٌ"" ""الدَّائِرَةُ الانْتِخابِيَّةُ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16142, 'إفرَنْجِيٌّ', 'إفرنجي', 'منسوب', '', 'ءفرنجي', 'إفرنج', 'مَنْسُوبٌ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": واحِد الإفْرَنْجِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16143, 'تَأْسِيسِيٌّ', 'تأسيسي', 'منسوب', 'أسس', 'تءسيسي', 'تسس', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَأْسِيسِيٌّ-تَأْسِيسِيٌّ، ةٌ [أ س س]. 1.""يُسَاهِمُ فِي كُلِّ عَمَلٍ تَأْسِيسِيٍّ"" : مَشْرُوعٌ أَوْ تَأْسِيسُ عَمَلٍ أَوْ بِنَاءٌ يُوضَعُ لأَوَّلِ مَرَّةٍ. 2.""الْمَجْلِسُ التَّأْسِيسِيُّ"" : أَعْلَى هَيْئَةٍ تَشْرِيعِيَّةٍ فِي البِلاَدِ تَضَعُ القَوَانِينَ الجَدِيدَةَ وَتُشَرِّعُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16144, 'بُخَارِيٌّ', 'بخاري', 'منسوب', 'بخر', 'بخاري', 'بخر', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"بُخَارِيٌّ-بُخَارِيٌّ، ةٌ [ب خ ر] (مالَهُ علاقةٌ بِالبُخَارِ). ""حَقَّقَ عهْدُ البَواخِرِ البُخارِيَّةِ ثَورَةً صِناعيَّةً كُبْرَى"" : بَواخِرُ تسِيرُ بقُوَّةِ البُخارِ. ""آلَةٌ بُخارِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16145, 'تَرْبِيعِيٌّ', 'تربيعي', 'منسوب', 'ربع', 'تربيعي', 'تربع', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَرْبِيعِيٌّ-تَرْبِيعِيٌّ، ةٌ [ر ب ع] (مَالَهُ عَلاَقَةٌ بِالتَّرْبِيعِ). ""الجِذْرُ التَّرْبِيعِيُّ لِعَدَدٍ مَّا"" : عَدَدٌ آخَرُ إِذَا ضُرِبَ بِمِثْلِهِ أَعْطَى ذَلِكَ العَدَدَ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16146, 'تَشْرِيعِيُّ', 'تشريعي', 'منسوب', 'شرع', 'تشريعي', 'تشرع', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَشْرِيعِيُّ-تَشْرِيعِيُّ، ةٌ [ش ر ع] (مَالَهُ عَلاَقَةٌ بِالتَّشْرِيعِ). ""وَضَعَتِ السُّلْطَةُ التَّشْرِيعِيَّةُ قَوَانِينَ جَدِيدَةً"" : السُّلْطَةُ الَّتِي لَهَا حَقُّ سَنِّ القَوَانِينِ وَتَشْريعِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16147, 'تَطْبِيقِيٌّ', 'تطبيقي', 'منسوب', 'طبق', 'تطبيقي', 'تطبق', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَطْبِيقِيٌّ-تَطْبِيقِيٌّ، ةُ [ط ب ق] (مَالَهُ عَلاَقَةٌ بِالتَّطْبِيقِ). 1.""أَنْجَزَ تَمَارِينَهُ التَّطْبِيقِيَّةَ"" : التَّمَارِينُ العَمَلِيَّةُ الَّتِي تُطَبَّقُ عَلَيْهَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16148, 'تَكْعيبِيٌّ', 'تكعيبي', 'منسوب', 'كعب', 'تكعيبي', 'تكعب', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَكْعيبِيٌّ-تَكْعيبِيٌّ، ةٌ [ك ع ب] (ما لَهُ عَلاقَةٌ بِالتَّكْعيبِ). 1.""شَكْلٌ تَكْعيبِيٌّ"" : شَكْلٌ تُحيطُ بِهِ سِتَّةُ مُرَبَّعاتٍ مُتَساوِيَةٍ. 2.""الجِذْرُ التَّكْع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16149, 'شَخْصِيٌّ', 'شخصي', 'منسوب', 'شخص', 'شخصي', 'شخص', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَخْصِيٌّ-شَخْصِيٌّ، ةٌ [ش خ ص] (مَا هُوَ مُخْتَصُّ بِالشَّخْصِ). 1.""هَذَا هَوَ رَأْيِي الشَّخْصِيُّ"" : هَذَا هُوَ الرَّأْيُ الَّذِي أُعَبِّرُ عَنْهُ، أَيِ الْمُتَعَلِّقُ بِي. 2. ""إنَّهُ أَمْرٌ شَخْصِيٌّ"" : مَا يَخ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16150, 'لَفْظِيٌّ', 'لفظي', 'منسوب', 'لفظ', 'لفظي', 'لفظ', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"لَفْظِيٌّ-لَفْظِيٌّ، ةٌ [ل ف ظ] (مَا يَتَعَلَّقُ بِاللَّفْظِ). 1.""أَجَابَهُ لَفْظِيّاً"" : شَفَوِيّاً. 2.""يَتَمَيَّزُ بِاللَّفْظِيَّةِ"" : بِالْأَدَبِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16151, 'نَوْعِيٌّ', 'نوعي', 'منسوب', 'نوع', 'نوعي', 'نع', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نَوْعِيٌّ-نَوْعِيٌّ، ةٌ [ن و ع] (مَا يَتَعَلَّقُ بِالنَّوْعِ). 1.""تَقَدُّمٌ نَوْعِيٌّ"" : مُحَدَّدٌ، مُعَيَّنٌ، مُتَمَيِّزٌ. ""حَقَّقَ فَوْزاً نَوْعِيّاً"". 2.""تَحْلِيلٌ نَوْعِيٌّ"" : تَحْلِيلٌ كَيْفِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16152, 'سِياحِيٌّ', 'سياحي', 'منسوب', 'سيح', 'سياحي', 'سح', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"سِياحِيٌّ-سِياحِيٌّ، ةٌ [س ي ح] (ما يَخْتَصُّ بِالسِّياحَةِ). ""بَلَدٌ سِياحِيٌّ"" : بَلَدٌ يَمْلِكُ مُؤَهِّلاتٍ طَبيعِيَّةً وَأَثَرِيَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16153, 'كُلِّيٌّ', 'كلي', 'منسوب', 'كلل', 'كلي', 'كل', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"كُلِّيٌّ-كُلِّيٌّ [ك ل ل]. : مَا يُنْسَبُ إِلَى الكُلِّ أَوْ يُطْلَقُ عَلَيْهِ. 1.""كُلِّيّاً أَوْ جُزْئِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16154, 'رُوحَانِيٌّ', 'روحاني', 'منسوب', 'روح', 'روحاني', 'رحن', 'منسوبٌ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"رُوحَانِيّةٌ-رُوحَانِيّةٌ [ر و ح]. : كُلُّ ما هُوَ قائِمٌ على إِثْباتِ الرُّوحِ وَسُمُوِّها عَلَى الْمادِّياتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16155, 'مَطْبَعِيٌّ', 'مطبعي', 'منسوب', 'طبع', 'مطبعي', 'مطبع', 'منسوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَطْبَعِيٌّ-مَطْبَعِيٌّ، ةٌ [ط ب ع] (كُلُّ مَا هُوَ مُتَعَلِّقٌ بِالطِّبَاعَةِ). ""خَطَأٌ مَطْبَعِيٌّ"" : خَطَأٌ حَصَلَ أَثْنَاءَ الطَّبْعِ. ""أَخْطَاءٌ مَطْبَعِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16156, 'طَقْسِيٌّ', 'طقسي', 'منسوب', 'طقس', 'طقسي', 'طقس', 'منسوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"طَقْسِيٌّ-طَقْسِيٌّ، ةٌ [ط ق س]. : كُلُّ مَا هُوَ مُتَعَلِّقٌ بِالطَّقْسِ، أَي الشَّعِيرَةُ وَالطَّرِيقَةُ الدِّينِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16157, 'إِنْسِيٌّ', 'إنسي', 'منسوب', 'أنس', 'ءنسي', 'إنس', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":أُناسٌ:أَناسِيُّ"', '', '', '', '', '', '', '', '', '"( نِسْبَةً إلى الإِنْسِ). 1.: واحد الإِنْسِ. 2.: الجانِبُ الأ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16158, 'أُناسٌ', 'أناس', 'منسوب', '', 'ءناس', 'نس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16159, 'أَناسِيُّ', 'أناسي', 'منسوب', '', 'ءناسي', 'نس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16160, 'دُنْيَوِيٌّ', 'دنيوي', 'منسوب', 'دنو', 'دنيوي', 'دن', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"دُنْيَوِيٌّ-دُنْيَوِيٌّ، ةٌ [د ن و] (نِسْبَةٌ إلى الدُّنْيا). ""رَجُلٌ دُنْيَوِيٌّ"": يُحِبُّ أَمورَ الدُّنْيا وَلايَهْتَمُّ إِلاَّ بِها. ""الحياةُ الدُّنْيَوِيَّةُ"" : عَكْسُ الْحَياةِ الأُخْرَوِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16161, 'عَادِيٌّ', 'عادي', 'منسوب', 'عود', 'عادي', 'عد', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(نِسْبَةٌ إِلَى الْعَادَةِ). 1.""أَمْرٌ عَادِيٌّ جِدّاً"" : بَدِيهِيٌّ، جَرَتْ بِهِ الْعَادَةُ. 2.""مَا حَدَثَ غَيْرُ عَادِيٍّ"" : غَيْرُ مَأْلُوفٍ، مُفَاجِىءٌ. 3.""ذَكاءٌ عَادِيٌّ"" : مُتَوَسِّطٌ. 5.""حَرَكَةٌ عَادِيَّةٌ"" : حَرَكَةٌ طَبِيعِيَّةٌ. 6.""حَرَكَةٌ فِي ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16162, 'عَسَلِيٌّ', 'عسلي', 'منسوب', 'عسل', 'عسلي', 'عسل', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَسَلِيٌّ-عَسَلِيٌّ، ةٌ [ع س ل] (نِسْبَةٌ إِلَى العَسَلِ). ""لَوْنُ عَيْنَيْهَا عَسَلِيٌّ"" : بِلَوْنِ العَسَلِ. ""عَيْنَانِ عَسَلِيَّتاَنِ "" ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16163, 'عَظْمِيٌّ', 'عظمي', 'منسوب', 'عظم', 'عظمي', 'عظم', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَظْمِيٌّ-عَظْمِيٌّ، ةٌ [ع ظ م] (نِسْبَةٌ إِلَى العَظْمِ). 1.:حَمَامٌ لَوْنُهُ إِلَى بَيَاضٍ. 2.""الْهَيْكَلُ العَظْمِيُّ"" : هَيْكَلُ الإِنْسَانِ الْمُكَوَّنُ مِنْ مُجْمَلِ عِظَامِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16164, 'عَكْسِيٌّ', 'عكسي', 'منسوب', 'عكس', 'عكسي', 'عكس', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَكْسِيٌّ-عَكْسِيٌّ ، ةٌ [ع ك س] (نِسْبَةٌ إِلَى العَكْسِ). ""العَدُّ العَكْسِيُّ"" : أَي العَدُّ مَثَلاً مِنْ عَشَرَةٍ إِلَى وَاحِدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16165, 'عُمُومِيٌّ', 'عمومي', 'منسوب', 'عمم', 'عمومي', 'عمم', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عُمُومِيٌّ-عُمُومِيٌّ، ةٌ [ع م م] (نِسْبَةٌ إِلَى الْعُمُومِ). 1.""إعْلاَنٌ عُمُومِيٌّ"" : عَامٌّ، لِجَمِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16166, 'غَرَامِيٌّ', 'غرامي', 'منسوب', 'غرم', 'غرامي', 'غرم', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"غَرَامِيٌّ-غَرَامِيٌّ، ةٌ [غ ر م] (نِسْبَةٌ إِلَى الغَرَامِ). ""رِسَالَةٌ غَرَامِيَّةٌ"": رِسَالَةُ حُبٍّ وَتَعَلُّقٍ وَهُيَامٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16167, 'لَوْلَبِيٌّ', 'لولبي', 'منسوب', 'لولب', 'لولبي', 'للب', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"لَوْلَبِيٌّ-لَوْلَبِيٌّ، ةٌ [ل و ل ب] (نِسْبَةٌ إِلَى اللَّوْلَب). ""سُلَّمٌ لَوْلَبِيٌّ"" : قَائِمٌ عَلَى شَكْلِ لَوْلَبٍ. ""قَامَ بِحَرَكَةٍ لَوْلَبِيَّةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16168, 'لَيْلِيٌّ', 'ليلي', 'منسوب', 'ليل', 'ليلي', 'لل', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"لَيْلِيٌّ-لَيْلِيٌّ، ةٌ [ل ي ل] (نِسْبَةٌ إِلَى اللَّيْلِ). 1.""سَهْرَةٌ لَيْلِيَّةٌ"": سَهْرَةٌ تُقَامُ فِي اللَّيْلِ. 2.""هُوَ لَيْلِيٌّ"" : يُحِبُّ سُرَى اللَّيْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16169, 'فَارِسِيٌّ', 'فارسي', 'منسوب', 'فرس', 'فارسي', 'فرس', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"فَارِسِيٌّ-فَارِسِيٌّ، ةٌ [ف ر س] (نِسْبَةً إِلَى بِلادِ فَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16170, 'صِهْيُونِيٌّ', 'صهيوني', 'منسوب', '', 'صهيوني', 'صهن', 'مَنْسُوبٌ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"صِهْيُونِيَّةٌ-صِهْيُونِيَّةٌ (نِسْبَةً إِلَى جَبَلٍ قُرْبَ الْقُدْسِ يُسَمَّى صِهْيُونَ).: حَرَكَةٌ سِيَاسِيَّةٌ عُنْصُرِيَّةٌ أَقَام"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16171, 'عِصَامِيٌّ', 'عصامي', 'منسوب', '', 'عصامي', 'عصم', 'مَنْسُوبٌ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عِصَامِيٌّ-عِصَامِيٌّ (نِسْبَةٌ إِلَى عِصَام بْنِ شَهِيرة). ""عِصَامِيُّ النَّشْأَةِ"": أَيْ مَنْ تَعَلَّمَ مِنْ تِلْقَاءِ نَفْسِهِ وَكَسبَ عِلْماً بِاعْتِمَادِهِ عَلَى قُدُرَاتِهِ الذَّاتِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16172, 'عَلْمَانِيٌّ', 'علماني', 'منسوب', 'علم', 'علماني', 'علمن', 'مَنْسُوبٌ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عَلْمَانِيٌّ-عَلْمَانِيٌّ، ةٌ [ع ل م] (نِسْبَةٌ إِلَى عَلْمٍ بِمَعْنَى الْعَالَم). ""رَجُلٌ عَلْمَانِيٌّ"" : أَيْ لَيْسَ رَجُلَ دِينٍ، وَهُوَ خِلاَفُ الدِّينِيِّ أَوِ الْكَهَنُوتِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16173, 'عَلَوِيٌّ', 'علوي', 'منسوب', 'علو', 'علوي', 'عل', 'منسوب', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(نِسْبَةٌ إِلَى عَلِيٍّ). ""هُوَ مِنْ أُسْرَةٍ عَلَوِيَّةٍ"" : مِنْ أُسْرَةِ عَلِيٍّ بْنِ أَبِي طَالِبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16174, 'بركيٌّ', 'بركي', 'منسوب', '', 'بركي', 'برك', 'منسوب', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16175, 'ابتداعيٌّ', 'ابتداعي', 'منسوب', '', 'ابتداعي', 'بتدع', 'منسوبٌ إلى ابتداع', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16176, 'ابداعيٌّ', 'ابداعي', 'منسوب', '', 'ابداعي', 'بدع', 'منسوبٌ إلى ابداع', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16177, 'حَنِيفيٌّ', 'حنيفي', 'منسوب', 'حنف', 'حنيفي', 'حنف', 'مَنْسُوبٌ إلَى أبِي حَنِيفَةَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":أحْنَافٌ"', '', '', '', '', '', '', '', '', '"(مَنْسُوبٌ إلَى أبِي حَنِيفَةَ). 1.""كَانَ حَنِيفِيّاً فِي مَسْلَكِهِ وَمَذْهَبِهِ"" : تَابِعاً لِمَذْهَبِ أبِي حَنِيفَةَ. 2. ""الْمَذْهَبُ الحَنِيفِيُّ"": مِنَ الْمَذَاهِبِ الأرْبَعةِ فِي الإسْلامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16178, 'أحْنَافٌ', 'أحناف', 'منسوب', '', 'ءحناف', 'حنف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16179, 'إِجْبَارِيٌّ', 'إجباري', 'منسوب', 'جبر', 'ءجباري', 'إجبر', 'مَنْسُوبٌ إِلَى إِجْبار', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"إِجْبَارِيٌّ-إِجْبَارِيٌّ، ةٌ [ج ب ر] (مَنْسُوبٌ إِلَى إِجْبار). 1.""لَمْ يَكُنِ الحُضُورُ إِجْبَارِيّاً"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16180, 'آدَمِيٌّ', 'آدمي', 'منسوب', '', 'ءءدمي', 'آدم', 'مَنْسوبٌ إِلَى آدَمَ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"آدَمِيٌّ-آدَمِيٌّ، ةٌ (مَنْسوبٌ إِلَى آدَمَ). وَتَعْنِي كَذَلِكَ الإنْسَانَ : 1.""رَجُلٌ آدَمِيٌّ"" : إِنْسَانِيٌّ، لَطِيفٌ، ذُو أخْلاَقٍ. مَا مَلأَ الآدَمِيُّ وِعَاءً شَرّاً مِنْ بَطْنٍ، حَسْبُ الآدَمِيِّ لُقَيْمَاتٌ يُقِمْنَ صُلْبَهُ (حديث) . 2.""أدْرَكْتُ أنَّ الحُجْرَةَ مَمْلُوءةً بِالآدَمِيِّينَ"" : بالنَّاسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16181, 'أُسْترالِيّ', 'أسترالي', 'منسوب', '', 'ءسترالي', 'سترل', 'منسوب إلى أُسْتُرالْيَا.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات (منسوب إلى أُسْتُرالْيَا)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16182, 'إفْرِيقِيٌّ', 'إفريقي', 'منسوب', '', 'ءفريقي', 'إفرق', 'مَنْسوبٌ إلى إِفْرِيقِيا.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسوبٌ إلى إِفْرِيقِيا)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16183, 'إِبَاحِيٌّ', 'إباحي', 'منسوب', 'بوح', 'ءباحي', 'إبح', 'مَنْسُوبٌ إِلَى الإبَاحَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"إِبَاحِيٌّ-إِبَاحِيٌّ، ةٌ [ب و ح] (مَنْسُوبٌ إِلَى الإبَاحَةِ). 1.""رَجُل إِبَاحِيٌّ"" : الْمُتَحَلِّلُ عَنْ كُلِّ وَازِعٍ خُلُقِيٍّ، فَلا يَتَوَرَّعُ عَن القِيَام بِأعْمَالٍ مُنَافِيةٍ لِلأخْلاَقِ. 2.""يَعِيشُ فِي إِبَاحِيَّةٍ"" : فِي فَوْضىً وَلاَ يَتَقَيَّدُ بِالسُّلُوكِ وَالقَانُونِ وَالقَوَاعِدِ الأخْلاَقِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16184, 'اِبْتِدَائِيٌّ', 'ابتدائي', 'منسوب', 'بدأ', 'ابتداءي', 'بتد', 'مَنْسُوبٌ إِلَى الابْتِدَاءِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"اِبْتِدَائِيٌّ-اِبْتِدَائِيٌّ، ةٌ [ب د أ] (مَنْسُوبٌ إِلَى الابْتِدَاءِ). 1.""التَّعْلِيمُ الابْتِدَائِيُّ"" : التَّعْلِيمُ الأَوَّلِيُّ فِي الْمَرْحَلَةِ الأولَى مِنَ التَّعْلِيمِ. 2.""حَكَمَتْ عَلَيْهِ الْمَحْكَمَةُ الابْتِدَائِيَّةُ"" : مَحْكَمَةُ القَضَايَا الجُنْحِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16185, 'إبرازيٌّ', 'إبرازي', 'منسوب', '', 'ءبرازي', 'إبرز', 'منسوبٌ إلى الإبراز', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16186, 'اِجْتِمَاعِيّ', 'اجتماعي', 'منسوب', 'جم.ع', 'اجتماعي', 'جتمع', 'مَنْسُوبٌ إِلَى الاجْتِمَاعِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"اِجْتِمَاعِيّ-اِجْتِمَاعِيّ، ةٌ [ج م. ع] (مَنْسُوبٌ إِلَى الاجْتِمَاعِ). 1.""هُوَ اجْتِمَاعِيٌّ بِطَبْعِهِ"" : لَهُ فِطْرَةٌ تَمِيلُ إِلَى مُعَاشَرَةِ النَّاسِ فِي الْمُجْتَمَعِ والاخْتِلاَطِ بِهِمْ. ""الإِنْسَانُ كَائِن اِجْتِمَاعِيٌّ"". 2.""يُشَارِكُ فِي كُلِّ نَشَاطٍ اِجْتِمَاعِيٍّ"" : فِي كُلِّ نَشَاطٍ يَهْتَمُّ بِشُؤُونِ النَّاسِ وَقَضَايَاهُمْ وَمَشَاغِلِهِمْ. 3.""يَسْعَى إِلَى تَوْفِيرِ الْمُسَاوَاةِ الاِجْتِمَاعِيَّةِ بَيْنَ النَّاسِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16187, 'إجْرَائيٌّ', 'إجرائي', 'منسوب', 'جري', 'ءجراءي', 'إجر', 'مَنْسُوبٌ إِلَى الإجْرَاءِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"إجْرَائيٌّ-إجْرَائيٌّ، ةٌ [ج ر ي] (مَنْسُوبٌ إِلَى الإجْرَاءِ). ""قَانُونٌ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16188, 'إجْرَاِمِيٌّ', 'إجرامي', 'منسوب', 'جرم', 'ءجرامي', 'إجرم', 'مَنْسُوبٌ إلَى الإِجْرَامِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"إجْرَاِمِيٌّ-إجْرَاِمِيٌّ، ةٌ [ج ر م] (مَنْسُوبٌ إلَى الإِجْرَامِ). ""قَامَ بِعَمَلٍ إِجْرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16189, 'اِحْتِيَاطِيٌّ', 'احتياطي', 'منسوب', 'حوط', 'احتياطي', 'حتط', 'مَنْسُوبٌ إلَى الاحْتِيَاطِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"اِحْتِيَاطِيٌّ-اِحْتِيَاطِيٌّ، ةٌ [ح و ط] (مَنْسُوبٌ إلَى الاحْتِيَاطِ). 1.""شَارَكتِ القُوَّاتُ الاِحْتِيَاطِيَّةُ في العَمَلِيَّةِ"" : قُوَّاتٌ مِنَ الجَيْشِ يُحْتَفَظُ بِهَا عِنْدَ الحَاجَةِ لإِرْسَالِهَا إِلَى الجَبْهَةِ أوْ لِلإِنْقَاذِ فِي حَالَةِ الطَّوَارِىءِ. 2. ""اِتَّخَذَتِ الحُكُومَةُ تَدَابِيرَ اِحْتِيَاطِيَّةً"" : تَدَابِيرَ اجْتِنَاباً لِمَا قَدْ يَحْدُثُ مِنْ شَرٍّ أَوْ مَكْرُوهٍ. 3. ""لِكُلِّ سَيَّارَةٍ إِطَارٌ اِحْتِيَاطِيٌّ"" : عَجَلَةٌ تُوضَعُ فِي مُسْتَوْدَعِ السَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16190, 'إِدَارِيٌّ', 'إداري', 'منسوب', 'دور', 'ءداري', 'إدر', 'مَنْسوبٌ إلَى الإِدَارَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"إِدَارِيٌّ-إِدَارِيٌّ، ةٌ [د و ر] (مَنْسوبٌ إلَى الإِدَارَةِ). 1. ""رَجُل إِدَارِيٌّ"": مَنْ يَشْتَغِلُ فِي الإِدَارَةِ وَيُتْقِنُ أعْمالَ سَيْرِهَا. 2.""بَعَثَ بِرِسالَةٍ حَسَبَ السّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16191, 'أُرْجُوَانِيٌّ', 'أرجواني', 'منسوب', '', 'ءرجواني', 'رجن', 'مَنْسُوبٌ إِلَى الأرْجُوَانِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"أُرْجُوَانِيٌّ-أُرْجُوَانِيٌّ، ةٌ (مَنْسُوبٌ إِلَى الأرْجُوَانِ). ""أَحْمَرُ أُرْجُوَانِيٌّ"": أَحْمَرُ قَانٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16192, 'أُرْدُنِيٌّ', 'أردني', 'منسوب', '', 'ءردني', 'ردن', 'مَنْسوبٌ إِلى الأُرْدُنِ.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسوبٌ إِلى الأُرْدُنِ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16193, 'أَرِسْتُقْرَاطِيٌّ', 'أرستقراطي', 'منسوب', '', 'ءرستقراطي', 'رستقرط', 'مَنْسوبٌ إلى الأَرِسْتُقْرَاطِ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسوبٌ إلى الأَرِسْتُقْرَاطِيَّةِ). ""أَرِسْتُقْرَاطِيٌّ بِطَبْعِهِ وَسُلُوكِهِ"" : شَخْصٌ مِنَ الطَّبَقَةِ العُلْيَا فِي الْمُجْتَمَعِ أَوْ مِنَ الأَشْرَافِ ذَوِي السُّلْطَةِ وَالْجَاهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16194, 'أَرْضِيٌّ', 'أرضي', 'منسوب', 'أرض', 'ءرضي', 'رض', 'مَنْسُوبٌ إِلَى الأَرْضِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"أَرْضِيٌّ-أَرْضِيٌّ [أ ر ض] (مَنْسُوبٌ إِلَى الأَرْضِ). 1.""يَسْكُنُ فِي الطَّابَقِ الأَرْضِيِّ"" : الطَّابَقُ السُّفْلِيُّ. 2.""أَرْضِيٌّ شَوْكِيٌّ"" (نب).: بَقْلٌ أَخْضَرُ اللَّوْنِ مِنَ الْمُرَكَّبَاتِ الأُنْبُوبِيَّةِ الزَّهْرِ، يُسْلَقُ وَيُطْبَخُ، وَيُعْرَفُ أَيْضاً بِالخَرْشُوفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16195, 'إِرْهَابِيٌّ', 'إرهابي', 'منسوب', 'رهب', 'ءرهابي', 'إرهب', 'مَنْسُوبٌ إِلَى الإِرْهَابِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الإِرْهَابِ). ""رَجُلٌ إِرْهَابِيٌّ"" : مَنْ يَلْجَأُ إِلَى مُمَارَسَةِ الإِرْهَابِ بِالقَتْلِ أَوِ التَّخْرِيبِ أَوْ إِلْقَاءِ القَنَابِلِ وَالْمُتَفَجِّرَاتِ فِي أََمَاكِنَ عُمُومِيَّةٍ أَوْ خَاصَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16196, 'أَزَلِيٌّ', 'أزلي', 'منسوب', 'أزل', 'ءزلي', 'زل', 'منسُوبٌ إِلَى الأزَلِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"أَزَلِيٌّ-أَزَلِيٌّ ، ةٌ [أ ز ل] (منسُوبٌ إِلَى الأزَلِ). ""اللَّهُ أَزَلِيٌّ فِي مَلَكُوتِهِ"" : الخَالِدُ الدَّائِمُ الوُجُودِ لاَ بَدْءَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16197, 'أَسَاسِيٌّ', 'أساسي', 'منسوب', 'أسس', 'ءساسي', 'سس', 'مَنْسُوبٌ إِلَى الأسَاسِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"أَسَاسِيٌّ-أَسَاسِيٌّ، ةٌ [أ س س] (مَنْسُوبٌ إِلَى الأسَاسِ). 1.""وَضَعَ الحَجَرَ الأسَاسِيَّ لِبِنَاءِ مَدْرَسَةٍ جَدِيدَةٍ"" : الحَجَرَ الأوَّلَ إِشَارَةً إلى بِدَايَةِ عَمَلِيَّةِ البِنَاءِ. 2.""الْمُعْجَمُ أَسَاسِيٌّ لِمَعْرِفَةِ اللُّغَةِ"": ضَرُورِيٌّ، رَئِيسِيٌ. 3.""لَمْ يَكُنْ ذَلِكَ هُوَ السَّبَبُ الأسَاسِيُّ"" : السَّبَبُ الجَوْهَرِيُّ، الرَّئِيسِيُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16198, 'أُسْبُوعِيٌّ', 'أسبوعي', 'منسوب', 'سبع', 'ءسبوعي', 'سبع', 'مَنْسُوبٌ إِلَى الأُسْبُوعِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"أُسْبُوعِيٌّ-أُسْبُوعِيٌّ، ةٌ [س ب ع] (مَنْسُوبٌ إِلَى الأُسْبُوعِ). 1.""يَأْتِي لِزِيَارَتِنَا أُسْبُوعِيّاً"" : مَرَّةً فِي كُلِّ أُسْبُوعٍ. 2.""جَرِيدَةٌ أُسْبُوعِيَّةٌ"" : تَصْدُرُ مَرَّةً فِي كُلِّ أسبُوعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16199, 'اِسْتِبْدَادِيٌّ', 'استبدادي', 'منسوب', 'بدد', 'استبدادي', 'ستبدد', 'مَنْسُوبٌ إِلَى الاسْتِبْدَادِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"اِسْتِبْدَادِيٌّ-اِسْتِبْدَادِيٌّ، ةٌ [ب د د] (مَنْسُوبٌ إِلَى الاسْتِبْدَادِ). ""حُكْمٌ اِسْتِبْدَادِيٌّ"" : تَعَسُّفِيٌّ، ظَالِمٌ، عُدْوَانِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16200, 'اِسْتِثْنَائِيٌ', 'استثنائي', 'منسوب', 'ثني', 'استثناءي', 'ستثن', 'مَنْسُوبٌ إِلَى الاِسْتِثْنَاء', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"اِسْتِثْنَائِيٌ-اِسْتِثْنَائِيٌ، ةٌ (مَنْسُوبٌ إِلَى الاِسْتِثْنَاءِ) [ث ن ي]. 1.""اِنْعَقَدَتْ جَلْسَةٌ اِسْتِثْنَائِيَّةٌ"" : جَلْسَةٌ طَارِئَةٌ. 2.""تَعِيشُ البِلاَدُ حَالَةً اسْتِثْنَائِيَّةً"" : حَالَةً حَرِجَةً، حَالَةَ الطَّوَارىءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16201, 'إِسْترَاتِيجِيٌّ', 'إستراتيجي', 'منسوب', '', 'ءستراتيجي', 'إسترتج', 'مَنْسُوبٌ إلى الإِسْتِرَاتِجِي', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"إِسْترَاتِيجِيٌّ-إِسْترَاتِيجِيٌّ، ةٌ (مَنْسُوبٌ إلى الإِسْتِرَاتِجِيَّةِ). 1.""اِسْتَوْلَى الجَيْشُ عَلى مَوْقِعٍ إِسْتْرَاتِيجِيٍّ"" : عَلَى مَوْقِعٍ هَامٍّ يُشْرِفُ عَلَى مَنَاطِقَ مُتَعَدِّدَةٍ، لَهُ أَهَمِّيَّةٌ مِنَ النَّاحِيَةِ الحَرْبِيَّةِ. 2.""مَرْكَزٌ إِسْتَرَاتِجِيٌّ مِنَ النَّاحِيَةِ التِّجَارِيَّةِ"" : لَهُ أَهَمِّيَّةٌ كُبْرَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16202, 'اِسْتِنْساخِيٌّ', 'استنساخي', 'منسوب', 'نسخ', 'استنساخي', 'ستنسخ', 'مَنْسوبٌ إلى الاسْتِنْساخِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"اِسْتِنْساخِيٌّ-اِسْتِنْساخِيٌّ، ةٌ [ن س خ] (مَنْسوبٌ إلى الاسْتِنْساخِ). ""آلَةٌ اِسْتِنْساخِيَّةٌ"": آلَةٌ تَقومُ بِالتَّصْوِيرِ الآلِيِّ لِلصَّفَحاتِ وَغِيْرِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16203, 'أُسْقُفِي', 'أسقفي', 'منسوب', '', 'ءسقفي', 'سقف', 'مَنْسوبٌ إلى الأُسْقُفِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"أُسْقُفِيَّةٌ-أُسْقُفِيَّةٌ (مَنْسوبٌ إلى الأُسْقُفِ).: دَرَجةُ الأُسْقُفِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16204, 'اِشْتِراكِيٌّ', 'اشتراكي', 'منسوب', 'شرك', 'اشتراكي', 'شترك', 'مَنْسوبٌ إلى الاشْتِراكِيَّةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"اِشْتِراكِيٌّ-اِشْتِراكِيٌّ، ةٌ [ش ر ك] (مَنْسوبٌ إلى الاشْتِراكِيَّةِ). 1.""رَجُلٌ اِشْتِراكِيٌّ"": يَعْتَقِدُ في مَذْهَبِ الاشْتِراكِيَّةِ. 2.""بَلَدٌ اِشْتِراكِيٌّ"": بَلَدٌ يُطَبِّقُ مَذْهَبَ الاشْتِراكِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16205, 'اِصْطِناعِيٌّ', 'اصطناعي', 'منسوب', 'صنع', 'اصطناعي', 'صطنع', 'مَنْسوبٌ إلى الاصْطِناعِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"اِصْطِناعِيٌّ-اِصْطِناعِيٌّ، ةٌ [ص ن ع] (مَنْسوبٌ إلى الاصْطِناعِ). ""وَرْدٌ اِصْطِناعِيٌّ"" : مَصْنوعٌ ومُقَلِّدٌ لِلْوَرْدِ الطَّبِيعِيِّ. ""فاكِهَةٌ اِصْطِناعِيَّةٌ"" ""قَمَرٌ اِصْطِناعِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16206, 'أَصْلِيٌّ', 'أصلي', 'منسوب', 'أصل', 'ءصلي', 'صل', 'مَنْسوبٌ إلى الأصْلِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"(مَنْسوبٌ إلى الأصْلِ). 1.""سُكَّانٌ أَصْلِيُّونَ"" : أَيْ مِنْ نَسَبٍ وأَرُومَةٍ واحِدَةٍ. 2.""العَدَدُ الأصْلِيُّ"": هُوَ ما دَلَّ على كَمِّيَّةِ الأشْياءِ الْمَعْدودَةِ. 3.""نُسْخَةٌ أَصْلِيَّةٌ"": النُّسْخَةُ الأُولَى. 4.""الجِهاتُ الأصْلِيَّةُ"": الجِهاتُ الأرْبَعُ الرَّئِيسِيَّةُ : الشَّمالُ والجَنوبُ والشَّرْقُ والغَرْبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16207, 'اِعْتِباطِيٌّ', 'اعتباطي', 'منسوب', 'عبط', 'اعتباطي', 'عتبط', 'مَنْسوبٌ إلى الاعْتِباطِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"اِعْتِباطِيٌّ-اِعْتِباطِيٌّ، ةٌ [ع ب ط] (مَنْسوبٌ إلى الاعْتِباطِ). ""عَمَلٌ اِعْتِباطِيٌّ"" : عَمَلٌ لَيْسَ بِذِي عِلَّةٍ، عَشْوائِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16208, 'أعْرَابِيٌّ', 'أعرابي', 'منسوب', 'عرب', 'ءعرابي', 'عرب', 'مَنْسُوبٌ إلَى الأعْرَابِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '""', '', '', '', '', '', '', '', '', '"أعْرَابِيٌّ-أعْرَابِيٌّ، ةٌ [ع ر ب] (مَنْسُوبٌ إلَى الأعْرَابِ). ""كانَ أعْرَابِيّاً مِنْ بَنِي هِلالٍ"" : مِنْ سُكَّانِ بَادِيَةِ بَنِي هِلاَلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16209, 'أُفُقِيٌّ', 'أفقي', 'منسوب', 'أفق', 'ءفقي', 'فق', 'مَنْسُوبٌ إلَى الأُفُقِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"أُفُقِيٌّ-أُفُقِيٌّ، ةٌ [أ ف ق] (مَنْسُوبٌ إلَى الأُفُقِ). ""رَسَمَ خَطّاً أُفُقِيّاً"" : هُوَ مَا وَقَعَ عَلَى خَطٍّ عَمُودِيٍّ. ""جُدْرانُ البَيْتِ عَمُودِيَّةٌ عَلَيْها سَقْفٌ أُفُقِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16210, 'اِقْتِصَادِيٌّ', 'اقتصادي', 'منسوب', 'قصد', 'اقتصادي', 'قتصد', 'مَنْسُوبٌ إلَى الاقْتِصادِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"اِقْتِصَادِيٌّ-اِقْتِصَادِيٌّ، ةٌ [ق ص د] (مَنْسُوبٌ إلَى الاقْتِصادِ). ""يَتَجَلَّى النَّشَاطُ الاقْتِصادِيُّ لِلْبِلاَدِ فِي مَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16211, 'إقْلِيميٌّ', 'إقليمي', 'منسوب', 'قلم', 'ءقليمي', 'إقلم', 'مَنْسُوبٌ إلَى الإقْلِيمِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '""', '', '', '', '', '', '', '', '', '"إقْلِيميٌّ-إقْلِيميٌّ، ةٌ [ق ل م] (مَنْسُوبٌ إلَى الإقْلِيمِ). 1.""هُوَ إقْلِيمِيُّ النَّزْعَةِ"" : الْمُتَشَبِّثُ بِإِقْلِيمِهِ. 2.""اِجْتَمَعَ الْمَجْلِسُ الإقْلِيميُّ فِي دَوْرَتِهِ العَادِيَةِ لِدِرَاسَةِ مَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16212, 'أكَادِيمِيُّ', 'أكاديمي', 'منسوب', '', 'ءكاديمي', 'كدم', 'مَنْسُوبٌ إلَى الأكَادِيمِيَّة', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"أكَادِيمِيُّ-أكَادِيمِيُّ، ةٌ (مَنْسُوبٌ إلَى الأكَادِيمِيَّةِ). ""عَالِمٌ أكَادِيمِيٌّ"": العَالِمُ الْمُهْتَمُّ بِالعُلُومِ حَسَبَ مَنْهَجٍ عِلْمِيٍّ دَقِيقٍ، الْمُنْتَمِي إلَى مُؤَسَّسَةٍ أكَادِيمِيَّةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16213, 'آلِيٌّ', 'آلي', 'منسوب', 'أول', 'ءالي', 'آل', 'مَنْسُوبٌ إِلَى الآلةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"آلِيٌّ-آلِيٌّ، ةٌ [أ و ل] (مَنْسُوبٌ إِلَى الآلةِ). 1.""يَتَحَرَّكُ بِشَكْلٍ آلِيٍّ"" : بِشَكْلٍ ذَاتِيٍّ، مِنْ دَاخِلِهِ. 2.""ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16214, 'إلْزَامِيٌّ', 'إلزامي', 'منسوب', 'لزم', 'ءلزامي', 'إلزم', 'مَنْسُوبٌ إلَى الإِلْزَامِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"إلْزَامِيٌّ-إلْزَامِيٌّ، ةٌ [ل ز م] (مَنْسُوبٌ إلَى الإِلْزَامِ). ""قَرَّرَتِ الحُكُومَةُ أنْ ي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16215, 'إلَهِيٌّ', 'إلهي', 'منسوب', 'أله', 'ءلهي', 'إله', 'مَنْسُوبٌ إلَى الإلهِ.', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"إلَهِيٌّ-إلَهِيٌّ، ةٌ [أ ل هـ]. مَنْسُوبٌ إلَى الإلهِ. 1.""حُكْمٌ إلَهِيٌّ لاَ مَرَدَّ لَهُ"" : هَذَا مَا أرَادَهُ الَّلهُ. 2.""القُدْرَةُ الإلاَهِيَّةُ"" : صِفَةٌ لِذَاتِ الإلاَهِ وَصِفَاتِهِ. 3.""الحَقُّ الإلَهِيُّ"" : مَا كَانَ يَدَّعِيهِ بَعْضُ مُلُوكِ أُورُوبَّا فِي القُرُونِ الوُسْطَى بِأنَّ حُكْمَهُمْ تَفْوِيضٌ مِنَ الإلَهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16216, 'أمَامِيٌّ', 'أمامي', 'منسوب', 'أمم', 'ءمامي', 'مم', 'مَنْسُوبٌ إلَى الأَمَامِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"أمَامِيٌّ-أمَامِيٌّ، ةٌ [أ م م] (مَنْسُوبٌ إلَى الأَمَامِ). ""جَلَسَ فِي الصَّفِّ الأَمَامِيِّ"" : الأوَّلُ، فِي الْمُقَدِّمَةِ. ""جَلَسَ الكِبَارُ فِي الصُّفُوفِ الأمَامِيَّةِ"" ""فِي الخُطُوطِ الأَمَامِيَّةِ"" ""وَقَعَ عَطَبٌ فِي العَجَلَتَيْنِ الأمَامِيَّتَيْنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16217, 'اِنْتِقالِيٌ', 'انتقالي', 'منسوب', 'نقل', 'انتقالي', 'نتقل', 'مَنْسوبٌ إلى الانْتِقالِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"اِنْتِقالِيٌ-اِنْتِقالِيٌ، ةٌ [ن ق ل] (مَنْسوبٌ إلى الانْتِقالِ). ""مَرْحَلَةٌ اِنْتِقالِيَّةٌ"" : مَرْحَلَةٌ غَيْرُ ثابِتَةٍ، تُمَهِّدُ لِمَرْحَلَةٍ قادِمَةٍ. ""حُكومَةٌ اِنْتِقالِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16218, 'اِنْتِقامِيٌّ', 'انتقامي', 'منسوب', 'نقم', 'انتقامي', 'نتقم', 'مَنْسُوبٌ إلَى الانْتِقامِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '""', '', '', '', '', '', '', '', '', '"اِنْتِقامِيٌّ-اِنْتِقامِيٌّ، ةٌ [ن ق م] (مَنْسُوبٌ إلَى الانْتِقامِ).""مَوْقِفٌ اِنْتِقامِيٌّ"": مَوْقِفٌ يَصْطَبِغُ بِصِبْغَةِ الانْتِقامِ.""أعْمالٌ اِنْتِقامِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16219, 'إِنْسانِيٌّ', 'إنساني', 'منسوب', 'أنس', 'ءنساني', 'إنسن', 'مَنْسوبٌ إلى الإِنْسانِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"إِنْسانِيٌّ-إِنْسانِيٌّ، ةٌ [أ ن س] (مَنْسوبٌ إلى الإِنْسانِ). ""يَقومُ بِعَمَلٍ إِنْسانِيٍّ"" : يَقُومُ بِعَمَلٍ نَموذَجِيٍّ فيهِ الخَيْرُ لِبَني البَشَرِ و"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16220, 'إِنْشائِيٌّ', 'إنشائي', 'منسوب', 'نشأ', 'ءنشاءي', 'إنش', 'مَنْسوبٌ إلى الإِنْشاءِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"إِنْشائِيٌّ-إِنْشائِيٌّ، ةٌ [ن ش أ] (مَنْسوبٌ إلى الإِنْشاءِ). 1.""أَنْجَزَ مَوْضوعاً إِنْشائِيّاً"" : مَوْضوعاً يَتَضَمَّنُ تَأْليفَ الأفْكارِ وَتَنْسِيقَها تَعْبيرِيّاً. 2.""قَرَّرَ الْمَجْلِسُ البَلَدِيُّ القِيامَ بِأَعْمالٍ وَمَشاريعَ إِنْشائِيَّةٍ"" : الأَشْغالُ العُمومِيَّةُ والعُمْرانِيَّةُ مِثْلُ إِصْلاحِ الطُّرُقِ وَشَقِّها والتَّرْميمِ وَأَعْمالِ الرَّيِّ، إلخ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16221, 'اِنْفِصالِيٌّ', 'انفصالي', 'منسوب', 'فصل', 'انفصالي', 'نفصل', 'مَنْسوبٌ إلى الانْفِصالِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسوبٌ إلى الانْفِصالِ). ""حَرَكَةٌ اِنْفِصالِيَّةٌ أَرادَتِ الْمَسَّ بِوَحْدَةِ الوَطَنِ بِالانْفِصالِ عَنْهُ، يَقودُها انْفِصالِيٌّ مُسَخَّرٌ وَراءهُ انْفِصالِيُّونَ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16222, 'أَهْلِيٌّ', 'أهلي', 'منسوب', 'أهل', 'ءهلي', 'هل', 'مَنْسُوبٌ إلَى الأهْلِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"أَهْلِيٌّ-أَهْلِيٌّ، ةٌ [أ هـ ل] (مَنْسُوبٌ إلَى الأهْلِ). 1.""حَيَوَانٌ أهْلِيٌّ"" : مِنَ الحَيَوَانَاتِ الْمَنْزِلِيَّةِ الألِيفَةِ. 2.""تَعِيشُ القَرْيَةُ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16223, 'أُوتُوقْرَاطِيٌّ', 'أوتوقراطي', 'منسوب', '', 'ءوتوقراطي', 'تقرط', 'مَنْسوبٌ إلَى الأُوتُوقْرَاطِي', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"أُوتُوقْرَاطِيٌّ-أُوتُوقْرَاطِيٌّ (مَنْسوبٌ إلَى الأُوتُوقْرَاطِيَّةِ). ""حَاكِمٌ أُوتُوقْرَاطِيٌّ"" : مُسْتَبِدٌّ، أيْ لَهُ سُلْطَةٌ مُطْلَقَةٌ. ""كَانَ حُكْمُهُ حُكْماً أُوتُوقْرَاطِيّاً""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16224, 'اِئْتِلاَفِيٌّ', 'ائتلافي', 'منسوب', 'ألف', 'اءتلافي', 'تلف', 'مَنْسُوبٌ إِلَى الائْتِلاَفِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"اِئْتِلاَفِيٌّ-اِئْتِلاَفِيٌّ، ةٌ [أ ل ف] (مَنْسُوبٌ إِلَى الائْتِلاَفِ). 1.""عَمَل ائْتِلاَفيٌّ"": عَمَلٌ سَاهَمَتْ فِيهِ قُوىً مِنْ مُخْتَلِفِ الاتِّجَاهَاتِ السِّيَاسِيَّةِ وَالفِكْرِيَّةِ. 2.""تَكَوَّنَتْ حُكُومَةٌ ائْتِلاَفِيَّةٌ"": حُكُومَةٌ تَضُمُّ وُزَرَاءَ مِنْ مُخْتَلِفِ الاتِّجَاهَاتِ وَالنَّزَعَاتِ السِّيَاسِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16225, 'إِيقَاعِيٌّ', 'إيقاعي', 'منسوب', 'وقع', 'ءيقاعي', 'إقع', 'مَنْسُوبٌ إلَى الإِيقَاعِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"إِيقَاعِيٌّ-إِيقَاعِيٌّ، ةٌ [و ق ع] (مَنْسُوبٌ إلَى الإِيقَاعِ). ""رَقْصٌ إيقَاعِيٌّ"" : مُتَنَاغِمٌ، مُتَنَاسِبٌ مَعَ أَنْغَامٍ مُوسِيقِيَّةٍ."', '');
