INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16234, 'بَحْرِيٌّ', 'بحري', 'منسوب', 'بحر', 'بحري', 'بحر', 'مَنْسوبٌ إلَى البَحْرِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '""', '', '', '', '', '', '', '', '', '"بَحْرِيٌّ-بَحْرِيٌّ، ةٌ [ب ح ر] (مَنْسوبٌ إلَى البَحْرِ). 1.""السَّمَكُ البَحْرِيُّ"" : السَّمَكُ الْمَوْجُودُ فِي البَحْرِ. 2.""تَحَرَّكَ الأُسْطُولُ البَحْرِيُّ الحَرْبِيُّ"" : القُوَّاتُ العَسْكَرِيَّةُ المُخْتَصَّةُ بِفَنِّ الْمَعارِكِ الحَرْبِيَّةِ فِي البَحْرِ. 3.""عَرَفَتِ البَحْرِيّةُ تَوَسُّعاً كَبِيراً"" : التِّجَارَةُ الَّتِي تَمُرُّ وَتُنْقَلُ عَبْرَ البَحْرِ. 4.""تُشَكِّلُ البَحْرِيَّةُ الحَرْبِيَّةُ لِدَوْلَةِ كَذَا أكْبَرَ أُسْطُولٍ حَرْبِيٍّ فِي العَالَمِ"" : سُفُنٌ حَرْبِيَّةٌ، غَوَّاصاتٌ. 5.""يَدْرُسُ فِي الْمَدْرَسَةِ البَحْرِيّةِ"" : مَدْرَسَةٌ تُدَرِّسُ كُلَّ مَا يَتَعلَّقُ بِشُؤونِ المِلاحَةِ وَالحَرْبِ فِي البَحْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16235, 'بحيريٌّ', 'بحيري', 'منسوب', '', 'بحيري', 'بحر', 'مَنْسوبٌ إلَى البحيرِة', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16236, 'بَدَوِيٌّ', 'بدوي', 'منسوب', 'بدو', 'بدوي', 'بد', 'مَنسوبٌ إلى البَدْوِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنسوبٌ إلى البَدْوِ). ""بَدَوِيٌّ يُحافِظُ على بَداوَتِهِ"" : مِنْ سُكَّانِ البادِيَةِ أَصيلٌ فِيها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16237, 'بَرِّيٌّ', 'بري', 'منسوب', 'برر', 'بري', 'بر', 'مَنْسوبٌ إلى البَرَّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"بَرِّيٌّ-بَرِّيٌّ، ةٌ [ب ر ر] (مَنْسوبٌ إلى البَرَّ). 1.""حَيَواناتُ الغابَةِ وَالجَبَلِ بَرِّيَّةٌ"" : وَحْشِيَّةٌ، تَعيشُ في البَرِّ، لاَ تَحْتَمِلُ الأماكِنَ الآهِلَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16238, 'برازيٌّبرازيٌّ،،ة', 'برازيبرازي،،ة', 'منسوب', '', 'برازيبرازي،،ة', 'برزبرز،،ة', 'منسوبٌ إلى البراز', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
