INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16243, 'بُرْكانِيٌّ', 'بركاني', 'منسوب', '', 'بركاني', 'بركن', 'منسوبٌ إلى البُرْكانِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"بُرْكانِيٌّ-بُرْكانِيٌّ (منسوبٌ إلى البُرْكانِ). ""أَرْضٌ بُرْكانِيَّةٌ"" : أَرْضٌ تَحْدُثُ بِها بَراكِينُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16244, 'بَرْلَمانِيٌّ', 'برلماني', 'منسوب', '', 'برلماني', 'برلمن', 'منسوبٌ إلى البَرْلَمانِ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"بَرْلَمانِيٌّ-بَرْلَمانِيٌّ، ةٌ (منسوبٌ إلى البَرْلَمانِ). ""نِظامٌ بَرْلَمانِيٌّ"" : نِظامٌ سِياسِيٌّ قائِمٌ على مُراقَبَةِ البَرْلَمانِ لأعْضاءِ الحُكومَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16245, 'بَرْمائِيٌّ', 'برمائي', 'منسوب', '', 'برماءي', 'برم', 'مَنْسوبٌ إلى البَرِّ والماءِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"بَرْمائِيٌّ-بَرْمائِيٌّ، ةٌ (مَنْسوبٌ إلى البَرِّ والماءِ). 1.""حَيَوانٌ بَرْمائِيٌّ"": كُلُّ الطُّيورِ والدَّوابِّ والزَّواحِفِ الَّتِي تَعيشُ في البَرِّ والماءِ مَعاً. ""حَيَواناتٌ بَرْمائِيَّةٌ"". 2.""آلاتٌ بَرْمائِيَّةٌ"" : آلاتٌ تُسْتَخْدَمُ في البَرِّ والماءِ. ""سَيَّارَةٌ بَرْمائِيَّةٌ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16246, 'بَريدِيٌّ', 'بريدي', 'منسوب', '', 'بريدي', 'برد', 'منسوبٌ إلى البَريدِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"بَريدِيٌّ-بَريدِيٌّ، ةٌ (منسوبٌ إلى البَريدِ). ""طابَعٌ بَريدِيٌّ"" : رَسْمُ أُجْرَةِ البَريدِ يُلْصَقُ علَى ظَهْرِ الرَّسائِلِ. ""طُرودٌ بَريدِيَّةٌ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16247, 'بُسْتانِيٌّ', 'بستاني', 'منسوب', '', 'بستاني', 'بستن', 'مَنْسوبٌ إلى البُسْتانِ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"بُسْتانِيٌّ-بُسْتانِيٌّ (مَنْسوبٌ إلى البُسْتانِ). ""إِنَّهُ أَحْسَنُ بُسْتَانِيّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16248, 'بَشَرِيٌّ', 'بشري', 'منسوب', 'بشر', 'بشري', 'بشر', 'مَنْسوبٌ إلى البَشَرِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"بَشَرِيٌّ-بَشَرِيٌّ [ب ش ر] (مَنْسوبٌ إلى البَشَرِ). 1.""يَمْتازُ الجِسْمُ البَشَرِيُّ بِنَسَقِهِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16249, 'بَلَدِيٌّ', 'بلدي', 'منسوب', 'بلد', 'بلدي', 'بلد', 'مَنْسوبٌ إلى البَلَدِ أَوِ الب', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"بَلَدِيٌّ-بَلَدِيٌّ، ةٌ [ب ل د] (مَنْسوبٌ إلى البَلَدِ أَوِ البَلْدَةِ). 1.""صُنْعٌ بَلَدِيٌّ"" : صُنْعٌ مَحَلِّيٌّ، أَي مِنَ الإِنْتاجِ الصِّناعِيِّ للبَلَدِ الَّذِي أَنْتَ فِيهِ. ""صِناعَةٌ بَلَد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16250, 'بَهْلَوَانِيٌّ', 'بهلواني', 'منسوب', '', 'بهلواني', 'بهلن', 'مَنْسُوبٌ إلَى البَهْلَوَانِ.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسُوبٌ إلَى البَهْلَوَانِ). 1.""قَدَّمَتِ الفِرْقَةُ الشَّعْبِيَّةُ ألْعَاباً بَهْلَوَانِيَّةً"" : القفْزُ وَالرَّقْصُ عَلَىالحِبَالِ وَالأسْلاَكِ، وَالإتْيَانُ بِحَرَكَاتٍ مُثِيرَةٍ مُدْهِشَةٍ. 2."" يَقُومُ بِحَرَكَاتٍ بَهْلَوَانِيَّةٍ"" : بِحَرَكَاتٍ لاَ مَعْنَى لَهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16251, 'بَوْلِيٌّ', 'بولي', 'منسوب', 'بول', 'بولي', 'بل', 'منسوب إلَى البَوْلِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"بَوْلِيٌّ-بَوْلِيٌّ، ةٌ [ب و ل] (منسوب إلَى البَوْلِ). ""أمْرَاضٌ بَوْلِيَّةٌ"" : أمْرَاضٌ تُصِيبُ الْمَتَانَةَ وَالكُلْيَتيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16252, 'بَيْطَرِيٌّ', 'بيطري', 'منسوب', '', 'بيطري', 'بطر', 'منسوبٌ إلى البَيْطَرَةِ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"بَيْطَرِيٌّ-بَيْطَرِيٌّ (منسوبٌ إلى البَيْطَرَةِ). ن.البَيْطارُ. ""يُتابِعُ دِراسَتَهُ في الْمَعْهَدِ البَيْطَرِيِّ"" : مَعْهَدٌ يَهْتَمُّ بِتَدْرِيسِ وَظائِفِ الحَيَوانِ وَأَمْراضِهِ وَتَشْريحِهِ وَدِراستِها. ""حَصَلَ على شَهادَةٍ في الطِّبِّ البَيْطَرِيِّ"" : طِبُّ الْحَيَواناتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16253, 'تَأْدِيبِيٌّ', 'تأديبي', 'منسوب', 'أدب', 'تءديبي', 'تدب', 'مَنْسُوبٌ إِلَى التَّأْدِيبِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَأْدِيبِيٌّ-تَأْدِيبِيٌّ، ةٌ [أ د ب] (مَنْسُوبٌ إِلَى التَّأْدِيبِ). ""سَيَجْتَمِعُ الْمَجْلِسُ التَّأْدِيبِي لِلنَّظَرِ فِي حَالَتِهِ"" : مَجْلِسٌ تَصْدُرُ عَنْهُ قَرَارَاتٌ تَأْدِيبِيَّةٌ زَجْرِيَّةٌ فِي حَقِّ الَّذِينَ يَأْتُونَ مُخَالَفَاتٍ وَإِسَاءاتٍ فِي مَجَالِ عَمَلِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16254, 'بختريٌّ', 'بختري', 'منسوب', '', 'بختري', 'بختر', 'منسوبٌ إلى التبختر', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16255, 'تبريريٌّ', 'تبريري', 'منسوب', '', 'تبريري', 'تبرر', 'مَنْسوبٌ إلى التبرير', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16256, 'تِجَارِيٌّ', 'تجاري', 'منسوب', 'تجر', 'تجاري', 'تجر', 'مَنْسُوبٌ إِلَى التِّجَارَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '', '', '', '', '', '', '', '', '', '"تِجَارِيٌّ-تِجَارِيٌّ، ةٌ [ت ج ر] (مَنْسُوبٌ إِلَى التِّجَارَةِ). 1.""أَغْلَقَ الْمَرْكَزُ التِّجَارِيُّ أَبْوَابَهُ"" : الْمَحَلُّ الَّذِي بِهِ تِجَارَةٌ. 2.""عَرَفَ السُّوقُ حَرَكَةً تِجَارِيَّةً وَاسِعَةً"" : نَشَاطاً تِجَارِيّاً يَتَضَمَّنُ حَرَكَةَ بَيْعٍ وَشِرَاءٍ. 3.""لَهُ أَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16257, 'تَجْرِيبِيٌّ', 'تجريبي', 'منسوب', 'جرب', 'تجريبي', 'تجرب', 'مَنْسُوبٌ إِلَى التَّجْرِيبِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَجْرِيبِيٌّ-تَجْرِيبِيٌّ، ةٌ [ج ر ب] (مَنْسُوبٌ إِلَى التَّجْرِيبِ). 1. ""أَجْرَى الْمُعَلِّمُ امْتِحَانًا تَجْرِيبِيّاً"" : اِخْتِبَارِيّاً. 2.""العُلُومُ التَّجْرِيبِيَّةُ"" : العُلُومُ الَّتِي تَخْضَعُ لِلتَّجْرِيبِ وَإِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16258, 'تَدْريجِيّ', 'تدريجي', 'منسوب', 'درج', 'تدريجي', 'تدرج', 'مَنْسُوبٌ إِلَى التَّدْريجِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَدْريجِيّ-تَدْريجِيّ، ةٌ [د ر ج] (مَنْسُوبٌ إِلَى التَّدْريجِ). ""يُحَقِّقُ الْمَرْءُ نَجَاحَهُ تَدْرِيجِيّاً"" : خُطْوَةً خُطْوَةً وَعَلَى فَتَرَاتٍ، شَيْئاً فَشَيْئاً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16259, 'تَرْتِيبيٌّ', 'ترتيبي', 'منسوب', 'رتب', 'ترتيبي', 'ترتب', 'مَنْسُوبٌ إِلَى التَّرْتِيبِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَرْتِيبيٌّ-تَرْتِيبيٌّ، ةٌ [ر ت ب] (مَنْسُوبٌ إِلَى التَّرْتِيبِ). ""عَدَدٌ تَرْتِيبِيٌّ"" : مَا دَلَّ عَلَى الرُّتْبَةِ وَالْمَنْزِلَةِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16260, 'تَشْكِيلِيٌّ', 'تشكيلي', 'منسوب', 'شكل', 'تشكيلي', 'تشكل', 'مَنْسُوبٌ إِلَى التَّشْكِيلِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"تَشْكِيلِيٌّ-تَشْكِيلِيٌّ، ةٌ [ش ك ل] (مَنْسُوبٌ إِلَى التَّشْكِيلِ). ""الفَنُّ التَّشْكِيلِيُّ"" : فَنٌّ مِنْ فُنُونِ الرَّسْمِ أَوِ النَّحْتِ، قَائِمٌ عَلَى رَسْمِ الْمَنَاظِرِ الطَّبِيعِيَّةِ أَوِ الاجْتِمَاعِيَّةِ وَنَحْوِهِمَا فِي أَحْجَامٍ وَأَشْكَالٍ مُعَيَّنَةٍ حَسَبَ رَسْمِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16261, 'تَصَاعُدِيٌّ', 'تصاعدي', 'منسوب', 'صعد', 'تصاعدي', 'تصعد', 'مَنْسُوبٌ إِلى التَّصَاعُدِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَصَاعُدِيٌّ-تَصَاعُدِيٌّ، ةٌ [ص ع د] (مَنْسُوبٌ إِلى التَّصَاعُدِ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16262, 'تَصْحِيحِيٌّ', 'تصحيحي', 'منسوب', 'صحح', 'تصحيحي', 'تصحح', 'مَنْسُوبٌ إِلى التَّصْحِيحِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَصْحِيحِيٌّ-تَصْحِيحِيٌّ، ةٌ [ص ح ح] (مَنْسُوبٌ إِلى التَّصْحِيحِ). 1.""بَيَانٌ تَصْحِيحِيٌّ"" : بَيَانٌ يُعِيدُ الأُمُورَ إِلَى نِصَابِهَا وَيُصَحِّحُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16263, 'تَعْلِيمِيٌّ', 'تعليمي', 'منسوب', 'علم', 'تعليمي', 'تعلم', 'مَنْسُوبٌ إِلَى التَّعْلِيمِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَعْلِيمِيٌّ-تَعْلِيمِيٌّ، ةٌ [ع ل م] (مَنْسُوبٌ إِلَى التَّعْلِيمِ). ""مَنْهَجٌ تَعْلِيمِيٌّ"" : مَنْهَجٌ لِتَلْقِينِ الْمَعَارِفِ وَالْمَهَارَاتِ. ""الْمَنَاهِجُ التَّعْلِيمِيَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16264, 'تَمْهِيديٌّ', 'تمهيدي', 'منسوب', 'مهد', 'تمهيدي', 'تمهد', 'مَنْسُوبٌ إلَى التَّمْهِيدِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَمْهِيديٌّ-تَمْهِيديٌّ، ةٌ [م هـ د] (مَنْسُوبٌ إلَى التَّمْهِيدِ). 1.""الصَّفُّ التَّمْهِيدِيُّ"" : الإعْدَادِيُّ. 2.""مَقَالٌ تَمْهِيدِيٌّ"" : اِفْتِتَاحِيٌّ. 3. ""مُؤْتَمَرٌ تَمْهِيدِيٌّ"" : تَحْضِيريٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16265, 'تَنْفِيذِيٌّ', 'تنفيذي', 'منسوب', 'نفذ', 'تنفيذي', 'تنفذ', 'مَنْسُوبٌ إلَى التَّنْفِيذِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَنْفِيذِيٌّ-تَنْفِيذِيٌّ، ةٌ [ن ف ذ] (مَنْسُوبٌ إلَى التَّنْفِيذِ). 1.""هَذَا مِنِ اخْتِصَاصِ السُّلْطَةِ التَّنْفِيذِيَّةِ"" : السُّلْطَةُ الَّتِي تُنَفِّذُ القَوَانِينَ. 2. ""اللجْنَةُ التَّنْفِيذِيَّةُ"" : لَجْنَةٌ مُنْبَثِقَةٌ عَنْ جَمْعِيَّةٍ أوْ هَيْئَةٍ أوْ حِزْبٍ مَسْؤُولَةٌ عَلَى تَنْفِيذِ القَراَرَاتِ الْمُتَّفَقِ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16266, 'تَنَكُّرِيٌّ', 'تنكري', 'منسوب', 'نكر', 'تنكري', 'تنكر', 'مَنْسُوبٌ إلَى التَّنَكُّرِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَنَكُّرِيٌّ-تَنَكُّرِيٌّ، ةٌ [ن ك ر] (مَنْسُوبٌ إلَى التَّنَكُّرِ). ""شَارَكَ فِي حَفْلٍ تَنَكُّرِيٍّ"" : فِي حَفْلٍ يَتَنَكَّرُ فِيهِ الْمُشَارِكُونَ بِوُجُوهٍ مُسْتَعَارَةٍ وَألْبِسَةٍ عَجِيبَةٍ غَرِيبَةٍ. ""حَفْلَةٌ تَنَكُّرِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16267, 'ثَانَوِيٌّ', 'ثانوي', 'منسوب', 'ثني', 'ثانوي', 'ثن', 'مَنْسُوبٌ إلَى الثَّانِي', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"ثَانَوِيٌّ-ثَانَوِيٌّ، ةٌ [ث ن ي] (مَنْسُوبٌ إلَى الثَّانِي). 1.""اِنْتَقَلَ إلَى التَّعْلِيمِ الثَّانَوِيِّ"" : دَرَجَةُ التَّعْلِيمِ بَعْدَ الابْتِدَائِيِّ وَيَلِيهَا التَّعْلِيمُ العَالِي. 2.""هَذَا أمْرٌ ثَانَوِيٌّ"" : لَيْسَتْ لَهُ أهَمِّيَّةٌ كَبِيرَةٌ، أيْ يَأْتِي فِي الدَّرَجَةِ الثَّانِيَةِ. ""جَاءَ بِأفْكَارٍ ثَانَوِيَّةٍ"". 3.""يَدْرُسُ فِي الثَّانَوِيَّةِ"" : الْمَدْرَسَةُ الَّتِي يَدْرُسُ فِيهَا التِّلْمِيذُ الدُّرُوسَ الثَّانَوِيَّةَ بَعْدَ الابْتِدَائِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16268, 'ثَقافِيٌّ', 'ثقافي', 'منسوب', 'ثقف', 'ثقافي', 'ثقف', 'مَنْسُوبٌ إلَى الثَّقَافَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"ثَقافِيٌّ-ثَقافِيٌّ، ةٌ [ث ق ف] (مَنْسُوبٌ إلَى الثَّقَافَةِ). 1.""الْمَرْكَزُ الثَّقَافِيُّ"" : الْمَرْكَزُ الْمُهْتَمُّ بِشُؤُونِ الثَّقَافَة وَالفِكْرِ. 2.""الحَيَاةُ الثَّقَافِيَّةُ"" : مَظَاهِرُ الثَّقَافَةِ وَالعُلُومِ وَالآدَابِ. 3.""الْمُسْتَشَارُ الثَّقَافِيُّ فِي السِّفَارَةِ"" : الْمَسْؤُولُ عَنِ الشُّؤُونِ وَالقَضَايَا الْمُتَعَلِّقَةِ بِالثَّقَافَةِ. 4.""مِنْ بَيْنِ بُنُودِ الاتِّفَاقِيَّةِ: التَّبَادُلُ الثَّقَافِيُّ"": أيْ تَبَادُلُ كُلِّ مَاَ لَهُ عَلاَقَةٌ بِأَوْجُهِ الثَّقَافَةِ. ""الحَقْلُ الثَّقَافِيُّ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16269, 'ثُلاثِيٌّ', 'ثلاثي', 'منسوب', 'ثلث', 'ثلاثي', 'ثلث', 'مَنْسوبٌ إلى الثَّلاثَةِ على غ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"ثُلاثِيٌّ-ثُلاثِيٌّ، ةٌ [ث ل ث] (مَنْسوبٌ إلى الثَّلاثَةِ على غَيْرِ قِياسٍ). 1.""شَكْلٌ هَنْدَسِيٌّ ثُلاثِيُّ الأَضْلاعِ"" : مُتَكَوِّنٌ مِنْ ثَلاثَةِ أَضْلاعٍ. ""ثُلاثِيُّ الأَلْوانِ"" ""ثُلاثِيُّ الزَّوايَا"". 2.""حِلْفٌ ثُلاثِيٌّ"": حِلْفٌ مُكَوَّنٌ مِنْ ثَلاثَةِ أَطْرافٍ. 3.""الفِعْلُ الثُّلاثِيُّ"". (نح) : الفِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16270, 'ثَوْرِيٌّ', 'ثوري', 'منسوب', 'ثور', 'ثوري', 'ثر', 'مَنْسوبٌ إلى الثَّوْرَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ثَوْرِيٌّ-ثَوْرِيٌّ، ةٌ [ث و ر] (مَنْسوبٌ إلى الثَّوْرَةِ). 1.""رَجُلٌ ثَوْرِيٌّ"" : يَعْتَقِدُ في مَبادِئِ الثّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16271, 'جَامِعِيٌّ', 'جامعي', 'منسوب', 'جمع', 'جامعي', 'جمع', 'مَنْسُوبٌ إِلىَ الجَامِعَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلىَ الجَامِعَةِ). ""أُسْتَاذٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16272, 'جَاهِلِيٌّ', 'جاهلي', 'منسوب', 'جهل', 'جاهلي', 'جهل', 'مَنْسُوبٌ إلَى الجَاهِلِيَّةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إلَى الجَاهِلِيَّةِ). 1. ""العَصْرُ الجَاهِلِيُّ"" : الْمَرْحَلَةُ التَّارِيخِيَّةُ مَا قَبْلَ الإسْلاَمِ. ""امْرُؤُ القَيْسِ شَاعِرٌ جَاهِلِيٌّ"" : عَاشَ فِي العَصْرِ الجَاهِلِيِّ. 2.""الشِّعْرُ الجَاهِلِيُّ"" : الشِّعْرُ الَّذِي قَالَهُ شُعَرَاءُ العَصْرِ الجَاهِلِيِّ قَبْلَ مَجِيءِ الإِسْلاَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16273, 'جَبَلِيٌّ', 'جبلي', 'منسوب', '', 'جبلي', 'جبل', 'مَنْسُوبٌ إِلَى الجَبَلِ.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسُوبٌ إِلَى الجَبَلِ). 1.""هُوَ جَبَلِيٌّ"" : سَاكِنُ ال"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16274, 'جَدَلِيٌّ', 'جدلي', 'منسوب', 'جدل', 'جدلي', 'جدل', 'مَنْسُوبٌ إِلَى الجَدَلِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جَدَلِيٌّ-جَدَلِيٌّ، ةٌ [ج د ل] (مَنْسُوبٌ إِلَى الجَدَلِ). 1.""مُحَاوِرٌ جَدَلِيٌّ"" : أَيْ مَنْ يُتْقِنُ الإِجَابَةَ وَوَضْعَ الأَسْئِلِةِ وَتَوِلِيدَ الحِوَارِ. 2.""مَوْضُوعٌ تَحْكُمُهُ عَلاَقَةٌ جَدَلِيَّةٌ"" : أَيْ مَا يَحْكُمُ عَنَاصِرَهُ مِنْ تَنَاقُضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16275, 'جِذْرِيٌّ', 'جذري', 'منسوب', 'جذر', 'جذري', 'جذر', 'مَنْسُوبٌ إِلَى الجِذْرِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جِذْرِيٌّ-جِذْرِيٌّ، ةٌ [ج ذ ر] (مَنْسُوبٌ إِلَى الجِذْرِ)."" أَحْدَثَ تَغْيِيرًا ج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16276, 'جُزْئِيٌّ', 'جزئي', 'منسوب', 'جزأ', 'جزءي', 'جز', 'مَنْسُوبٌ إِلىَ الجُزْءِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جُزْئِيٌّ-جُزْئِيٌّ، ةٌ [ج ز أ] (مَنْسُوبٌ إِلىَ الجُزْءِ). 1.""تَحْلِيلٌ جُزْئِيٌّ"" : تَحْلِيلٌ يَكْتَفِي بِبَعْضِ العَنَاصِرِ. 2.""تَوَصَّلَ الطَّرَفَانِ إِلَى تَس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16277, 'جَزَائِرِيٌّ', 'جزائري', 'منسوب', '', 'جزاءري', 'جزر', 'مَنْسُوبٌ إِلَى الجَزَائِرِ.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ـون، ـات. (مَنْسُوبٌ إِلَى الجَزَائِرِ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16278, 'جَسَدِيٌّ', 'جسدي', 'منسوب', 'جسد', 'جسدي', 'جسد', 'مَنْسُوبٌ إِلَى الجَسَدِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جَسَدِيٌّ-جَسَدِيٌّ، ةٌ [ج س د] (مَنْسُوبٌ إِلَى الجَسَدِ). ""يُمْنَعُ التَّعْذ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16279, 'جُسْمَانِيّ', 'جسماني', 'منسوب', 'جسم', 'جسماني', 'جسمن', 'مَنْسُوبٌ إِلَى الجِسْمِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جُسْمَانِيّ-جُسْمَانِيّ، ةٌ [ج س م] (مَنْسُوبٌ إِلَى الجِسْمِ). ""يُمْنَعُ التَّعْذِيبُ الجُسْمَانِيّ مَنْعاً كُلِّيّاً"" : العِقَابُ الَّذِي يَنْزِلُ بِالجِسْمِ بِوَاسِطَةِ السَّوْطِ أَوِ العَصَا وَغَيْرِ ذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16280, 'جِسْمِيٌّ', 'جسمي', 'منسوب', 'جسم', 'جسمي', 'جسم', 'مَنْسُوبٌ إِلَى الجِسْمِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جِسْمِيٌّ-جِسْمِيٌّ، ةٌ [ج س"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16281, 'جُغْرَافِيٌّ', 'جغرافي', 'منسوب', '', 'جغرافي', 'جغرف', 'مَنْسُوبٌ إِلَى الجُغْرَافِيَة', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسُوبٌ إِلَى الجُغْرَافِي"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16282, 'جِلْدِيٌّ', 'جلدي', 'منسوب', 'جلد', 'جلدي', 'جلد', 'مَنْسُوبٌ إِلى الجِلْدِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جِلْدِيٌّ-جِلْدِيٌّ، ةُ [ج ل د] (مَنْسُوبٌ إِلى الجِلْدِ). ""ذَهَبَ عِنْدَ طَبِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16283, 'جَمَاعِيٌّ', 'جماعي', 'منسوب', 'جمع', 'جماعي', 'جمع', 'مَنْسُوبٌ إِلَى الجَمَاعَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جَمَاعِيٌّ-جَمَاعِيٌّ، ةٌ [ج م ع] (مَنْسُوبٌ إِلَى الجَمَاعَةِ). 1.""مَوْقِفٌ جَمَاعِيٌّ"" : الكُلُّ مُجْمِعٌ عَلَيْهِ. 2.""يَقْرَأُونَ القُرْآنَ قِرَاءةً جَمَاعِيَّةً"" : اِشْتِراَكُ جَمِيعِ الحَاضِرِينَ فِي القِرَاءةِ. 3.""قَرَّرُوا جَمَاعِيّاً حُضُورَ الحَفْلِ"" : كُلُّهُمْ، مُجْمَلُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16284, 'جُمْرُكِيٌّ', 'جمركي', 'منسوب', '', 'جمركي', 'جمرك', 'مَنْسُوبٌ إِلَى الجُمْرُكِ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"جُمْرُكِيٌّ-جُمْرُكِيٌّ (مَنْسُوبٌ إِلَى الجُمْرُكِ). ""سَأَلَ الجُمْرُكِيُّ الْمُسُافِرَ ع"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16285, 'جُمْهُورِيٌّ', 'جمهوري', 'منسوب', 'جمهر', 'جمهوري', 'جمهر', 'مَنْسُوبٌ إِلَى الجُمْهُورِيَّ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"جُمْهُورِيٌّ-جُمْهُورِيٌّ، ةٌ [ج م هـ ر] (مَنْسُوبٌ إِلَى الجُمْهُورِيَّةِ أَوْ إِلَى الجُمْهُورِ). 1.""نِظَامٌ جُمْهُورِيٌّ"" : نِظَامٌ رِئَاسِيٌّ يُنْتَخَبُ رَئِيسُهُ بِالاقْتِرَاعِ العَامِّ لِفَتْرَةٍ مُعَيَّنَةٍ كَمَا يُحَدِّدُهَا دُسْتُورُ البِلاَدِ. 2.""صَدَرَ قَرَارٌ جُمْهُورِيٌّ"" : قَرَارٌ مِنْ رِئَاسَةِ الجُمْهُورِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16286, 'جُنْدِيٌّ', 'جندي', 'منسوب', 'جند', 'جندي', 'جند', 'مَنْسُوبٌ إِلَى الجُنْدِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جُنْدِيٌّ-جُنْدِيٌّ [ج ن د] (مَنْسُوبٌ إِلَى الجُنْدِ). 1.: وَاحِدُ الجُنْدِ لِلْعَسْكَرِ، الجَيْشُ . 2.""زَارَ قَبْرَ الجُنْدِيِّ الْمَجْهُولِ"" : ضَرِيحُ الجُنْدِيِّ الْمَجْهُولِ الْهُوِيَّةِ الَّذِي مَاتَ فِي سَاحَةِ الشَّرَفِ فِي سَبِيلِ وَطَنِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16287, 'جِنْسِيٌّ', 'جنسي', 'منسوب', 'جنس', 'جنسي', 'جنس', 'مَنْسُوبٌ إِلَى الجِنْسِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جِنْسِيٌّ-جِنْسِيٌّ، ةٌ [ج ن س] (مَنْسُوبٌ إِلَى الجِنْسِ). 1.""الحُبُّ الجِنْسِيُّ"" : الحُبُّ القَائِمُ عَلَى مُمَارَسَةِ الجِنْسِ عَكْسَ الْحُبِّ العُذْرِيِّ. ""عَلاَقَاتٌ جِنْسِيَّةٌ"" . ""أَفْلاَمٌ جِنْسِيَّةٌ"". 2.""الغَرِيزَةُ الجِنْسِيَّةُ"" : غَرِيزَةُ الاتِّصَالِ الشَّهْوَانِيّ. 3.""الشُّذُوذُ الجِنْسِيُّ"" : الْمَيْلُ إِلَى سُلُوكٍ وَمُمَارَسَاتٍ شَهْوَانِيَّةٍ تَخْرُجُ عَنْ نِطَاقِ مَا هُوَ طَبِيعِيٌّ وَمُعْتَادٌ. 4.""أَمْرَاضٌ جِنْسِيَّةٌ"" : أَمْرَاضٌ نَاتِجَةٌ عَنِ اتِّصَالٍ جِنْسِيٍّ مَعَ طَرَفٍ آخَرَ يَحْمِلُ أَمْرَاضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16288, 'جَوِّيٌّ', 'جوي', 'منسوب', 'جوو', 'جوي', 'ج', 'مَنْسُوبٌ إِلَى الجَوِّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جَوِّيٌّ-جَوِّيٌّ، ةٌ [ج و و] (مَنْسُوبٌ إِلَى الجَوِّ). 1.""دَخَلَ الْمَجَالَ الجَوِّيَّ لِلْبَلَدِ الْمُجَاوِرِ"" : مِنْطَقَةُ الفَضَاءِ التَّابِعَةُ لِبَلَدٍ مُعَيَّنٍ. 2.""الضَّغْطُ الجَوِّيُّ"" : مَا لَهُ عَلاَقَةٌ بِالضَّغْطِ الَّذِي يَحْدُثُ فِي الفَضَاءِ. 3.""نَفَّذَ العَدُوُّ غَارَةً جَوِّيَّةً عَلَى مُخَيَّمَاتِ اللاَّجِئِينَ"": أَيْ تَنْفِيذُ الغَارَةِ جَوّاً بِوَاسِطَةِ الطَّائِرَاتِ. 4."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16289, 'جَوْفِيٌّ', 'جوفي', 'منسوب', 'جوف', 'جوفي', 'جف', 'مَنْسُوبٌ إِلَى الجَوْفِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جَوْفِيٌّ-جَوْفِيٌّ، ةٌ [ج و ف] (مَنْسُوبٌ إِلَى الجَوْفِ). ""يَعْتَمِدُ أَهْلُ القَبِيلَةِ عَلَى المِيَاهِ الجَوْفِيَّةِ"" : المِيَاهُ الَّتِي تُوجَدُ فِي دَاخِلِ الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16290, 'جَوْهَرِيٌّ', 'جوهري', 'منسوب', '', 'جوهري', 'جهر', 'مَنْسُوبٌ إِلَى الجَوْهَرِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جَوْهَرِيٌّ-جَوْهَرِيٌّ (مَنْسُوبٌ إِلَى الجَوْهَرِ). 1.""كَانَ الجَوْهَرِيَّ الوَحِيدَ فِي سُوقِ الذَّهَبِ"" : بَائِعُ الجَوْهَرِ وَصانِعُهُ. 2.""تَرَكَ مَا هُوَ جَوْهَرِيٌّ، فيِ الْمَوْضُوعِ وَاكْتَفَى بِمَا هُوَ عَرَضِيٌّ"" : الأَسَاسِيُّ، الضَّرُورِيُّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16291, 'حالِيٌّ', 'حالي', 'منسوب', 'حول', 'حالي', 'حل', 'منسوب إلى الحَالِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حالِيٌّ-حالِيٌّ، الحالِيُّ [ح ول] (منسوب إلى الحَالِ). ""حالِيّاً أَصْبَحَتِ الأُمورُ جاهِزَةً"" : في الوَقْتِ الحاضِرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16292, 'حَبَشِيٌّ', 'حبشي', 'منسوب', '', 'حبشي', 'حبش', 'مَنْسوبٌ إلى الحَبَش.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": مَنْسوبٌ إلى الحَبَش."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16293, 'حَتْمِيُّ', 'حتمي', 'منسوب', 'حتم', 'حتمي', 'حتم', 'مَنْسوبٌ إلى الحَتْمِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَتْمِيُّ-حَتْمِيُّ، ةٌ [ح ت م] (مَنْسوبٌ إلى الحَتْمِ). ""أَمْرٌ حَتْمِيٌّ"": لاَ مَفَرَّ مِنْهُ، ضَرورِيٌّ. ""حَتْمِيّاً"" ""نَتيجَةٌ حَتْمِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16294, 'حَجَرِيٌّ', 'حجري', 'منسوب', 'حجر', 'حجري', 'حجر', 'مَنْسوبٌ إلى الحَجَرِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَجَرِيٌّ-حَجَرِيٌّ، ةٌ [ح ج ر] (مَنْسوبٌ إلى الحَجَرِ). ""أَدَواتٌ تَعودُ إلى العَصْرِ الحَجَرِيِّ"" : إلى الزَّمانِ الَّذِي كانَ يَسْتَعْمِلُ فيهِ الإِنْسانُ الأَدَواتِ الَّتِي يَصْنَعُها مِنَ الحَجَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16295, 'حَدْسِيٌّ', 'حدسي', 'منسوب', 'حدس', 'حدسي', 'حدس', 'مَنْسوبٌ إِلى الحَدْسِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَدْسِيٌّ-حَدْسِيٌّ [ح د س] (مَنْسوبٌ إِلى الحَدْسِ). ""فَهْمٌ حَدْسِيٌّ"" : فَهْمٌ جاءَ نَتيجَةَ شُعورٍ داخِلِيٍّ أَوْ تَنَبُّؤٍ غَريزِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16296, 'حَديدِيٌّ', 'حديدي', 'منسوب', 'حدد', 'حديدي', 'حدد', 'مَنْسوبٌ إلى الحَديدِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَديدِيٌّ-حَديدِيٌّ، ةٌ [ح د د] (مَنْسوبٌ إلى الحَديدِ). ""رَجُلٌ حدِيدِيٌّ"" : رَجُلٌ صَلْبٌ لَهُ إِرادَةٌ قَوِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16297, 'حَرْفِيٌّ', 'حرفي', 'منسوب', 'حرف', 'حرفي', 'حرف', 'مَنْسوبٌ إلى الحَرْفِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '""', '', '', '', '', '', '', '', '', '"حَرْفِيٌّ-حَرْفِيٌّ، ةٌ [ح ر ف] (مَنْسوبٌ إلى الحَرْفِ). 1.""اِلْتَزَمَ بالاتِّفاقِيَّةِ حَرْفِيّاً"" : أَيْ بِكُلِّ ما فيها. 2.""تَرْجَمَ نَصّاً إلى"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16298, 'حَرِيرِيٌّ', 'حريري', 'منسوب', 'حرر', 'حريري', 'حرر', 'مَنْسُوبٌ إلَى الحَرِير', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَرِيرِيٌّ-حَرِيرِيٌّ، ةٌ [ح ر ر] (مَنْسُوبٌ إلَى الحَرِير). 1.""تَمْلِكُ فَسَاتِينَ حَرِيرِيَّةً"" : فَسَاتِينَ مَصْنُوعَةً مِنَ الحَرِيرِ. 2. ""اِشْتَرَتْ مَنْسُوجَاتٍ حَرِيرِيَّةً مِنَ الحَرِيرِيِّ"" : مِنْ بَائِعِ الحَرِيرِ وَصَانِعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16299, 'حِزْبِيٌّ', 'حزبي', 'منسوب', 'حزب', 'حزبي', 'حزب', 'مَنْسُوبٌ إلَى الحِزْبِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حِزْبِيٌّ-حِزْبِيٌّ، ةٌ [ح ز ب] (مَنْسُوبٌ إلَى الحِزْبِ). 1.""هُوَ حِزْبِيٌّ"" : الْمُنْتَمِي إلَى حِزْبٍ وَالْمُتَشَيِّعُ لَهُ، التَّابعُ لَهُ. 2.""نَشَأ نِزَاعٌ حِزْبِيٌّ"" : نِزَاعٌ حَوْلَ قَضَايَا الحِزْبِ. 3.""تُحَرِّكُهُ رُوحٌ حِزْبيَّةٌ"" : رُوحُ التَّحَزُّبِ وَالتَّشَيُّعِ. 4.""تَنَاوَلُوا قَضَايَا حِزْبِيَّةً"": قَضَايَا الحِزْبِ الدَّاخِلِيَّةُ وَكُلُّ مَا لَهُ عَلاَقَةٌ بِذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16300, 'حِسِّيٌّ', 'حسي', 'منسوب', 'حسس', 'حسي', 'حس', 'منسُوبٌ إلَى الحِسِّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حِسِّيٌّ-حِسِّيٌّ، ةٌ [ح س س] (منسُوبٌ إلَى الحِسِّ).: كُلُّ مَا يُدْرَكُ بِإِحْدَى الحَوَاسِّ الخَمْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16301, 'حَضَرِيٌّ', 'حضري', 'منسوب', 'حضر', 'حضري', 'حضر', 'مَنْسُوبٌ إلَى الحَضَرِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"حَضَرِيٌّ-حَضَرِيٌّ [ح ض ر] (مَنْسُوبٌ إلَى الحَضَرِ).: سَاكِنُ الحَضَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16302, 'حُضُورِيٌّ', 'حضوري', 'منسوب', 'حضر', 'حضوري', 'حضر', 'مَنْسُوبٌ إلَى الحُضُورِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حُضُورِيٌّ-حُضُورِيٌّ [ح ض ر] (مَنْسُوبٌ إلَى الحُضُورِ). ""حُوكِمَ الْمُتَّهَمُ حُضُورِيّاً"" : أيْ كَانَ حَاضِراً، عَكْس الحُكْمِ الغِيَابِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16303, 'حُقُوقِيٌّ', 'حقوقي', 'منسوب', 'حقق', 'حقوقي', 'حقق', 'مَنْسوبٌ إلَى الحُقُوقِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"حُقُوقِيٌّ-حُقُوقِيٌّ، ةٌ [ح ق ق] (مَنْسوبٌ إلَى الحُقُوقِ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16304, 'حَقِيقِيٌّ', 'حقيقي', 'منسوب', 'حقق', 'حقيقي', 'حقق', 'مَنْسوبٌ إِلَى الحَقِيقَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَقِيقِيٌّ-حَقِيقِيٌّ، ةٌ [ح ق ق] (مَنْسوبٌ إِلَى الحَقِيقَةِ). 1. ""أمْرٌ حَقِيقِيٌّ"" : ثَابِتٌ، صَحِيحٌ. 2. ""رَوَى وَاقِعَةً حَقِيقِيَّةً"" : الوَاقِعَةُ كَمَا حَدَثَتْ فِعْلاً لاَ خَيَالاً. 3. ""الْمَعْنَى الحَقِيقِيُّ لِلْكَلِمَةِ"" : مَعْنَاهَا الأَصْلِيُّ الَّذِي لاَ يَتَضَمَّنُ مَجَازاً وَلاَ كِنَايَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16305, 'حُكُومِيٌّ', 'حكومي', 'منسوب', 'حكم', 'حكومي', 'حكم', 'منسُوبٌ إلَى الحُكُومَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"حُكُومِيٌّ-حُكُومِيٌّ، ةٌ [ح ك م] (منسُوبٌ إلَى الحُكُومَةِ). ""اِنْعَقَدَ اجْتِمَاعٌ حُكُومِيٌّ تَحْتَ رِئَاسَةِ رَئِيسِ الحُكُومَةِ"" : اِجْتِماعُ وُزَرَاءِ الحُكُومَةِ. ""مَرَاسِيمُ حُكُوِميَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16306, 'حَلَزُونِيٌّ', 'حلزوني', 'منسوب', '', 'حلزوني', 'حلزن', 'مَنْسُوبٌ إلَى الحَلَزُونِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَلَزُونِيٌّ-حَلَزُونِيٌّ، ةٌ (مَنْسُوبٌ إلَى الحَلَزُونِ). 1. ""دَرَجٌ حَلَزُونِيٌّ"": عَلَى شَكْلِ حَلَزُونٍ، دَائِرِيٌّ، لَوْلَبِيٌّ. ""سُلَّمٌ حَلَزُونِيٌّ"". 2. ""خُطُوطٌ حَلَزُونِيَّةٌ"" : عَلَى هَيْئَةِ حَلَزُونٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16307, 'حَلْقِيٌّ', 'حلقي', 'منسوب', 'حلق', 'حلقي', 'حلق', 'منسوب إلَى الحَلْقِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَلْقِيٌّ-حَلْقِيٌّ، ةٌ [ح ل ق] (منسوب إلَى الحَلْقِ). الأحْرُفُ الحَلْقِيَّةُ هِيَ : ع. ح."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16308, 'حَمْضِيٌّ', 'حمضي', 'منسوب', 'حمض', 'حمضي', 'حمض', 'منْسُوبٌ إلَى الحَمْضِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَمْضِيٌّ-حَمْضِيٌّ، ةٌ [ح م ض] (منْسُوبٌ إلَى الحَمْضِ). 1.""أرْضُ حَمْضِيَّةٌ"" : كَثِيرةُ الحَمْضِ. 2. ""مَعِدَةٌ حَمْضِيَّةٌ"": خِلافُ القَلْوِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16309, 'حِنْطِيٌّ', 'حنطي', 'منسوب', '', 'حنطي', 'حنط', 'مَنْسُوبٌ إلَى الحِنْطَةِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حِنْطِيٌّ-حِنْطِيٌّ، ةٌ (مَنْسُوبٌ إلَى الحِنْطَةِ). ""حِنْطِيُّ اللَّوْنِ"" : ضَارِبٌ إلَى سُمْرَةِ الحِنْطَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16310, 'حَنَكِيٌّ', 'حنكي', 'منسوب', 'حنك', 'حنكي', 'حنك', 'مَنْسُوبٌ إلَى الحَنَكِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَنَكِيٌّ-حَنَكِيٌّ، ةٌ [ح ن ك] (مَنْسُوبٌ إلَى الحَنَكِ). 1.""عِظَامٌ حَنَكِيَّةٌ"" : عِظَامُ الحَنَكِ. 2. ""حُرُوفٌ حَنَكِيَّةٌ"" : حُرُوفُ الحَنَكِ، وهِيَ الشين والجيم والياء."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16311, 'حَيَوِيٌّ', 'حيوي', 'منسوب', 'حيي', 'حيوي', 'ح', 'مَنْسُوبٌ إلَى الحَيِّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَيَوِيٌّ-حَيَوِيٌّ، ةٌ [ح ي ي] (مَنْسُوبٌ إلَى الحَيِّ). 1. ""إنَّهُ أمْرٌ حَيَوِيٌّ"" : ضَرُورِيٌّ لِلْعَيْشِ. 2. ""إنَّهُ الْمَجَالُ الح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16312, 'حَيَوَانِيٌّ', 'حيواني', 'منسوب', 'حيي', 'حيواني', 'حن', 'مَنْسُوبٌ إلَى الحَيَوَانِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَيَوَانِيٌّ-حَيَوَانِيٌّ، ةٌ [ح ي ي] (مَنْسُوبٌ إلَى الحَيَوَانِ). 1.""الْمَمْلَكَةُ الحَيَوانِيَّةُ"" : أَحَدُ الأَقْسَامِ الكُبْرَى لِلْكَائِنَاتِ الموْجُودَةِ فِي الطَّبِيعَةِ، أيِ الحَيَوَانُ وَالنَّبَاتُ وَالجَمَادُ. 2. ""أَعْمَالٌ حَيَوَانِيَّةٌ"" : أعْمَالٌ تَتَّصِفُ بِصِفَاتِ الحَيَوَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16313, 'خَارِجِيٌّ', 'خارجي', 'منسوب', 'خرج', 'خارجي', 'خرج', 'مَنْسُوبٌ إِلَى الْخَارِجِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خَارِجِيٌّ-خَارِجِيٌّ، ةٌ [خ ر ج] (مَنْسُوبٌ إِلَى الْخَارِجِ). 1. ""رَجُلٌ خَارِجِيٌّ"" : مَنْ كَانَ عَلَى مَذْهَبِ الْخَوَارِجِ، مَنْ يَخْرُجُ عَنْ سُلْطَةِ الأمِيرِ أوِ الْجَم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16314, 'خِتَامِيٌّ', 'ختامي', 'منسوب', 'ختم', 'ختامي', 'ختم', 'مَنْسُوبٌ إِلى الخِتَامِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خِتَامِيٌّ-خِتَامِيٌّ، ةٌ [خ ت م] (مَنْسُوبٌ إِلى الخِتَامِ)."" ألْقَى الكَلِمَةَ الْخِتَامِيَّةَ رَئِيسُ الْجَمْعِيَّةِ"" : آخِرُ كَلِمَةٍ فِي نَدْوَةٍ أوْ حَفْلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16315, 'خَزَفِيٌّ', 'خزفي', 'منسوب', 'خزف', 'خزفي', 'خزف', 'مَنْسُوبٌ إِلَى الخَزَفِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خَزَفِيٌّ-خَزَفِيٌّ، ةٌ [خ ز ف] (مَنْسُوبٌ إِلَى الخَزَفِ). 1.""يَبِيعُ الأَوَانِيَ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16316, 'خَشَبِيٌّ', 'خشبي', 'منسوب', 'خشب', 'خشبي', 'خشب', 'مَنْسُوبٌ إِلَى الْخَشَبِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خَشَبِيٌّ-خَشَبِيٌّ، ةٌ [خ ش ب] (مَنْسُوبٌ إِلَى الْخَشَبِ). ""اِمْتَطَى الْوَلَدُ فَرَسًا خَشَبِيًّا"" : فَرَساً مِنْ خَشَبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16317, 'خُصُوصِيٌّ', 'خصوصي', 'منسوب', 'خصص', 'خصوصي', 'خصص', 'مَنْسُوبٌ إِلى الْخُصُوصِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خُصُوصِيٌّ-خُصُوصِيٌّ، ةٌ [خ ص ص] (مَنْسُوبٌ إِلى الْخُصُوصِ). ""دَرْسٌ خُصُوصِيٌّ"" : خَاصٌّ. ""سَيَّارَةٌ خُصُوصِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16318, 'خَلْفِيٌّ', 'خلفي', 'منسوب', 'خلف', 'خلفي', 'خلف', 'مَنْسُوبٌ إِلَى الخَلْفِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خَلْفِيٌّ-خَلْفِيٌّ، ةٌ [خ ل ف] (مَنْسُوبٌ إِلَى الخَلْفِ). ""خَرَجَ مِنَ البَابِ الخَلْفِيِّ"" : بَابٌ ثَانَوِيٌّ وَرَاءَ البَيْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16319, 'خُلُقِيٌّ', 'خلقي', 'منسوب', 'خلق', 'خلقي', 'خلق', 'مَنْسُوبٌ إِلى الخُلُقِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خُلُقِيٌّ-خُلُقِيٌّ، ةٌ [خ ل ق] (مَنْسُوبٌ إِلى الخُلُقِ). ""يَمْتَازُ بِصِفَاتِهِ الخُلُقِيَّةُ"" : الصِّفَاتُ ذَاتُ الْمَسْلَكِ الْحَسَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16320, 'خَمْرِيٌّ', 'خمري', 'منسوب', 'خمر', 'خمري', 'خمر', 'مَنْسُوبٌ إِلى الخَمْرِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خَمْرِيٌّ-خَمْرِيٌّ، ةٌ [خ م ر] (مَنْسُوبٌ إِلى الخَمْرِ). 1. ""هُوَ خَمْرِيُّ اللَّوْنِ"" : يَمِيلُ لَوْنُهُ إِلى الأَسْوَدِ الضَّارِبِ إِلى الْحُمْرَةِ. 2. ""شِعْرٌ خَمْرِيٌّ"" : شِعْرٌ يَدُورُ حَوْلَ الخَمْرِ وَالغَزَلِ. ""أَلْوَانٌ خَمْرِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16321, 'خمُاَسِيٌّ', 'خماسي', 'منسوب', 'خمس', 'خماسي', 'خمس', 'مَنْسُوبٌ إِلَى الْخَمْسَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خمُاَسِيٌّ-خمُاَسِيٌّ، ةٌ [خ م س] (مَنْسُوبٌ إِلَى الْخَمْسَةِ). 1.""شَكْلٌ خُمَاسِيُّ الأَضْلاَعِ"" : ذُو أَضْلاَعٍ خَمْسَةٍ. 2. ""فِعْلٌ خُمَاسِيٌّ"" : مُرَكَّبٌ مِنْ خَمْسَةِ أَحْرُفٍ. ""نَجْمَةٌ خُمَاسِيَّةٌ"" ""خُمَاسِيُّ الزَّوَايَا"". 3. ""رِيَاضَةُ الْخُمَاسِيِّ"" (ريا) : مَجْمُوعَةٌ لِخَمْسَةِ أَنْوَاعٍ مِنَ التَّدَارِيبِ الرِّيَاضِيَّةِ وَهِيَ : الْمُصَارَعَةُ وَالعَدْوُ وَالْقَفْزُ وَالرَّمْيُ بِالسِّهَامِ وَقُرْصُ الرَّمْيِ. 4. ""خُمَاسِيٌّ حَدِيثٌ"" : وَهُوَ نَوْعٌ مِنَ الألْعَابِ الأُولُمْبِيَّةِ تَتَضَمَّنُ خَمْسَ تَجَارِبَ مِنْ أَنْوَاعِ الرِّيَاضَةِ وَهِيَ : كُرَةُ العَصَا وَالْفُرُوسِيَّةُ وَالْمُبَارَزَةُ وَالسِّبَاحَةُ وَالرِّمَايَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16322, 'خَيَالِيٌّ', 'خيالي', 'منسوب', 'خيل', 'خيالي', 'خل', 'مَنْسُوبٌ إِلى الخَيَالِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلى الخَيَالِ). ""رَجُلٌ خَيَالِيٌّ"" : كَثِيرُ التَّخَيُّلِ، الوَاهِمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16323, 'خَيْرِيٌّ', 'خيري', 'منسوب', 'خير', 'خيري', 'خر', 'مَنْسُوبٌ إِلى الخَيْرِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خَيْرِيٌّ-خَيْرِيٌّ، ةٌ [خ ي ر] (مَنْسُوبٌ إِلى الخَيْرِ). 1. ""يُشَارِكُ فِي كُلِّ عَمَلٍ خَيْرِيٍّ"" : نَفْعِيٍّ، أَيْ كُلُّ عَمَلٍ فِيهِ مَنَافِعُ لِلنَّاسِ. 2. ""تَقُومُ الجَمْعِيَّةُ بِأعْمَالٍ خَيْرِيَّةٍ"" : بِأعْمَالِ الإِحْسَانِ وَالبِرِّ، مُسَاعَدَةُ الفُقَرَاءِ وَالْمُحْتَاجِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16324, 'دَاخِلِيٌّ', 'داخلي', 'منسوب', 'دخل', 'داخلي', 'دخل', 'مَنْسُوبٌ إلَى الدَّاخِلِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"دَاخِلِيٌّ-دَاخِلِيٌّ، ةٌ [د خ ل] (مَنْسُوبٌ إلَى الدَّاخِلِ). 1.""تِلْمِيذٌ دَاخِلِيٌّ"" : يَدْرُسُ وَيَأْكُلُ وَيَنَامُ فِي مَدْرَسَةٍ دَاخِليَّةٍ. 2.""يُتَابِعُ دِرَاسَتَهُ فِي مَدْرَسَةٍ دَاخِلِيَّةٍ"" : مَدْرَسَةٌ تَتَكَفَّلُ بِإيوَاءِ التَّلاَمِيذِ. 3. ""اِشْتَرَى مَلاَبِسَ دَاخِلِيَّةً"" : مَلاَبِسَ تَحْتَانِيَّةً. 4.""أصْدَرَتْ وِزَارَةُ الدَّاخِلِيَّةِ بَلاغاً حَوْلَ أَوْضَاعِ الأَمْنِ فِي البِلاَدِ"" : الوِزَارَةُ الْمُكَلَّفَةُ بِالأمْنِ الوَطَنِيِّ وَالسَّهَرِ عَلَى حِمَايَةِ الْمُوَاطِنينَ وَرِعَايَةِ مَصَالِحِهِمُ الإِدَارِيَّةِ. 5. ""يَتَدَخَّلُ فِي شُؤُونِهِ الدَّاخِلِيَّةِ"" : فِي شُؤُونِهِ الخَاصَّةِ. 6.""شُعُورٌ داخِلِيٌّ"" : باطِنِيٌّ. ""شَعَرَ بِارْتِياحٍ دَاخِلِيٍّ، فَتَثَاءبَ وَتَمطَّى"". (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16325, 'دِبْلُومَاسِيٌّ', 'دبلوماسي', 'منسوب', '', 'دبلوماسي', 'دبلمس', 'مَنْسُوبٌ إلَى الدِّبْلُومَاسِ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"دِبْلُومَاسِيٌّ-دِبْلُومَاسِيٌّ، ةٌ (مَنْسُوبٌ إلَى الدِّبْلُومَاسِيَّةِ). 1. ""مُوَظَّفٌ دِبْلُومَاسِيٌّ"" : مَنْ يَتَوَلَّى تَمْثِيلَ بِلاَدِهِ فِي دَوْلَةٍ أَجْنَبِيَّةٍ وَالاهْتِمَامَ بِشُؤُونِهَا الخَارِجِيَّةِ. 2. ""السِّلْكُ الدِّبْلُومَاسِيُّ"" : التَّمْثِيلُ السِّيَاسِيُّ لِهَيْئَةٍ مِنَ الْمُوَظَّفِينَ السَّامِينَ فِي بَلَدٍ أجْنَبِيٍّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16326, 'دِراسِيٌّ', 'دراسي', 'منسوب', 'درس', 'دراسي', 'درس', 'مَنْسُوبٌ إلَى الدِّرَاسَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"دِراسِيٌّ-دِراسِيٌّ، ةٌ [د ر س] (مَنْسُوبٌ إلَى الدِّرَاسَةِ). 1.""اِنْتَهَى العَامُ الدِّرَاسِيُّ"" : السَّنَةُ الْمَدْرَسِيَّةُ مِنْ شَهْرِ أيْلُول، سبتمبر إلَى شَهْرِ يُولْيُوزَ، جْوِيِّي. 2. ""أيَّامٌ دِرَاسِيَّةٌ"" : أيَّامُ بَحْثٍ وَدَرْسٍ وَعِلْمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16327, 'دَرَكِيٌّ', 'دركي', 'منسوب', 'درك', 'دركي', 'درك', 'مَنْسُوبٌ إلَى الدَّرَكِ، الوَ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إلَى الدَّرَكِ، الوَاحِدُ مِنْ رِجَالِ الدَّرَكِ). ""حَاصَرَهُ الدَّرَكِيُّونَ مِنْ كُلِّ جَانِبٍ"": قُوَّاتُ الشُّرْطَةِ العَسْكَرِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16328, 'دُسْتُورِيُّ', 'دستوري', 'منسوب', '', 'دستوري', 'دستر', 'مَنْسُوبٌ إلَى الدُّسْتُورِ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"دُسْتُورِيُّ-دُسْتُورِيُّ، ةٌ (مَنْسُوبٌ إلَى الدُّسْتُورِ). ""النِّظَامُ الدُّسْتُورِيُّ"": حُكْمٌ يَكُونُ خَاضِعاً لِمَوَادَّ الدُّسْتُورِ. ""نِظَامُ الْمَغْرِبِ هُوَ الْمَلَكِيَّةُ الدُّسْتُورِيَّةُ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16329, 'دُكَّانِيٌّ', 'دكاني', 'منسوب', '', 'دكاني', 'دكن', 'مَنْسوبٌ إلَى الدُّكَّانِ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسوبٌ إلَى الدُّكَّانِ). ""غابَ الدُّكَّانِيُّ عَنْ دُكَّانِهِ"" : صاحِبُ الدُّكَّانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16330, 'دَمَوِيٌّ', 'دموي', 'منسوب', 'دمي', 'دموي', 'دم', 'مَنْسوبٌ إلى الدَّمِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"دَمَوِيٌّ-دَمَوِيٌّ، ةٌ [د م ي] (مَنْسوبٌ إلى الدَّمِ). 1.""الدَّوْرَةُ الدَّمَوِيَّةُ"" : دَوْرَةُ الدَّمِ في جِسْمِ الإِنْسانِ. 2.""كانَ حاكِماً دَمَوِيّاً"" : سَفَّاكاً لِلدِّماءِ، سَفَّاحاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16331, 'دَهْرِيٌّ', 'دهري', 'منسوب', 'دهر', 'دهري', 'دهر', 'منسُوبٌ إلى الدَّهْرِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"دَهْرِيٌّ-دَهْرِيٌّ، ةٌ [د هـ ر] (منسُوبٌ إلى الدَّهْرِ). 1.""رَجُلٌ دَهْرِيٌ"" : مَنْ طالَ عُمْرُهُ وَعاشَ دَهْراً طَويلاً. 2.""قيلَ عَنْهُ إِنَّهُ دَهْرِيٌّ"" : مُلْحِدٌ لاَ يُؤْمِنُ بِالآخِرَةِ، وَيَقولُ بِبَقاءِ الدَّهْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16332, 'دُهْنِيٌّ', 'دهني', 'منسوب', 'دهن', 'دهني', 'دهن', 'مَنْسوبٌ إلى الدُّهْنِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"دُهْنِيٌّ-دُهْنِيٌّ، ةٌ [د هـ ن] (مَنْسوبٌ إلى الدُّهْنِ). قَلَّلَ مِنْ أَكْلِ الْمَوادِّ الدُّهْنِيَّةِ"" : مِنَ الْمَوادِّ ذَاتِ الدَّسَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16333, 'دُودِيٌّ', 'دودي', 'منسوب', 'دود', 'دودي', 'دد', 'مَنْسوبٌ إلى الدُّودِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"دُودِيٌّ-دُودِيٌّ، ةٌ [د و د] (مَنْسوبٌ إلى الدُّودِ). 1.""دُودِيُّ الشَّكْلِ"" : على شَكْلِ دُودَةٍ. 2.""اِسْتَأْصَلَ الزَّائِدَةَ الدُّودِيَّةَ"": زائِدَة على شَكْلِ دودَةٍ توجَدُ في جِسْمِ الإِنْسانِ في القِسْمِ الأَسْفَلِ مِنَ الأَعْورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16334, 'دَوْلِيٌّ', 'دولي', 'منسوب', 'دول', 'دولي', 'دل', 'مَنْسوبٌ إلى الدَّوْلَةِ والدّ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"دَوْلِيٌّ-دَوْلِيٌّ، دُوَلِيٌّ[د و ل] (مَنْسوبٌ إلى الدَّوْلَةِ والدُّوَلِ). 1.""أَحْرَزَ على لَقَبٍ دَوْلِيٍّ"" : أَيْ عالَمِيّ. 2.""اِتِّفاقٌ دُوَلِيٌّ"" : اِتِّفاقٌ تَشْتَرِكُ فيهِ عِدَّةُ دُوَلٍ. ""مِنْطَقَةٌ دَوْلِيَّةٌ"" ""مِياهٌ دَوْلِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16335, 'دِيمُقْراطِيٌّ', 'ديمقراطي', 'منسوب', '', 'ديمقراطي', 'دمقرط', 'مَنْسوبٌ إلى الدِّيمُقْراطِيَّ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (سيا) (مَنْسوبٌ إلى الدِّيمُقْراطِيَّةِ). ""هُوَ دِيمُقْراطِيٌّ بِطَبْعِهِ"" : الْمُؤْمِنُ بِمَبادِئِ العَدْلِ "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16336, 'دِينِيٌّ', 'ديني', 'منسوب', 'دين', 'ديني', 'دن', 'مَنْسوبٌ إلى الدِّينِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"دِينِيٌّ-دِينِيٌّ، ةٌ [د ي ن] (مَنْسوبٌ إلى الدِّينِ). ""شَديدُ التَّمَسُّكِ بِالقَواعِدِ الدِّينِيَّةِ"" : بِالقَواعِدِ الْمُتَعَلِّقَةِ بِالدِّينِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16337, 'ذاتِيٌّ', 'ذاتي', 'منسوب', '', 'ذاتي', 'ذت', 'مَنْسوبٌ إلى الذَّاتِ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ذاتِيٌّ-ذاتِيٌّ، ةٌ (مَنْسوبٌ إلى الذَّاتِ). 1.""قَدَّمَ نَقْداً ذاتِيّاً"" : عادَ لِيُرَاجِعَ نَفْسَهُ، آراءهُ وَأَفْكارَهُ عِنْدَ شُعورِهِ بِخَطَئِها. 2.""كانَ ذاتِيّاً في أَحْكامِهِ وَآرائِهِ"" : لَمْ تَكُنْ أَحْكامُهُ وَآراؤُهُ تَتَّسِمُ بِالْمَوْضوعِيَّةِ، أَيْ كانَ خاضِعاً لاِنْفِعالاتِ نَفْسِهِ. 3.""طالَبَ سُكَّانُ الْمُقاطَعَةِ الشَّمالِيَّةِ بِالحُكْمِ الذَّاتِيِّ"" : أَنْ يَحْكُمُوا أَنْفُسَهُمْ بِأَنْفُسِهِمْ على أَساسِ خُضوعِهِمْ لِلسُّلْطَةِ الْمَرْكَزِيَّةِ. 5.""أَقامُوا نِظاماً اِقْتِصادِيّاً قائِماً على التَّسْيِيرِ الذَّاتِيِّ"": التَّسْيِيرُ الْمُشْتَرَكُ. 6.""كَتَبَ سِيرَتَهُ الذَّاتِيَّةَ"" : الأَحْداثُ كَما عاشَها وَعايَنَها بِنَفْسِهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16338, 'ذَرِّيٌّ', 'ذري', 'منسوب', 'ذرر', 'ذري', 'ذر', 'مَنْسوبٌ إلى الذَّرَّةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"ذَرِّيٌّ-ذَرِّيٌّ، ةٌ [ذ ر ر] (مَنْسوبٌ إلى الذَّرَّةِ). 1.""عالِمٌ ذَرِّيٌّ"": أَيْ مُخْتَصٌّ بِعِلْمِ الذَّرَّةِ. 2.""الإِشْعاعُ الذَّرِّيُّ"" : الذَّرَّاتُ الْمُتَكَوِّنَةُ مِنَ نَواةِ نُوتْروناتِ، أَيْ مِنَ الْجُزَيْئَاتِ المادِّيَّةِ السَّالِبَةِ، وَمِن بروتُوناتِ، وَهِيَ جُزَيْئاتٌ مادِّيَّةٌ موجِبَةٌ ؛ وَتَدورُ حَوْلَ هِذِهِ النَّواةِ إِلِكْتُروناتٌ سالِبَةٌ. 3.""الطَّاقَةُ الذَّرِّيَّةُ"" : الطَّاقةُ الَّتِي يُحْصَلُ عَلَيْها بِتَحْطيمِ النَّوَياتِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16339, 'ذَهَبِيٌّ', 'ذهبي', 'منسوب', 'ذهب', 'ذهبي', 'ذهب', 'مَنْسُوبٌ إلَى الذَّهَبِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"ذَهَبِيٌّ-ذَهَبِيٌّ، ةٌ [ذ هـ ب] (مَنْسُوبٌ إلَى الذَّهَبِ). 1.""شَعْرٌ ذَهَبِيٌّ"" : بِلَونِ الذَّهَبِ. 2. ""آيَةٌ ذَهَبِيَّةٌ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16340, 'ذِهْنيٌّ', 'ذهني', 'منسوب', 'ذهن', 'ذهني', 'ذهن', 'مَنْسُوبٌ إلَى الذِّهْنِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"ذِهْنيٌّ-ذِهْنيٌّ، ةٌ [ذ هـ ن] (مَنْسُوبٌ إلَى الذِّهْنِ). 1.""عَمَلٌ ذِهْنيٌّ"" : عَقْليٌّ. ""ذِهْنِيَّةٌ مُتَفَتِّحَةٌ"" ""ذِهْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16341, 'رَأْسِيٌّ', 'رأسي', 'منسوب', 'رأس', 'رءسي', 'رس', 'مَنْسُوبٌ إلى الرَّأْسِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رَأْسِيٌّ-رَأْسِيٌّ، ةٌ [ر أ س] (مَنْسُوبٌ إلى الرَّأْسِ). ""خَطٌّ رَأْسِيٌّ"" : خَطٌّ عَمُودِيٌّ. ""خُطُوطٌ رَأْسِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16342, 'رَأْسُمَالِيٌّ', 'رأسمالي', 'منسوب', '', 'رءسمالي', 'رسمل', 'مَنْسُوبٌ إلَى الرَّأْسمَالِ.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون. (مَنْسُوبٌ إلَى الرَّأْسمَالِ). 1.""رَجُلٌ رَأْسمَالِيٌّ"" : مَنْ يَمْلِكُ رُؤُوسَ أَمْوَالٍ يَسْتَثْمِرُهَا فِي مَشَارِيعَ اقْتِصَادِيَّةٍ، وَتُطْلَقُ عَلَى رَجُلِ الأَعْمَالِ. 2.""نِظَامٌ رَأْسُمَالِيٌّ"" : نِظَامٌ قَائِمٌ عَلَى المِلْكِيَّةِ الخَاصَّةِ لِوَسَائِلِ الإنْتَاجِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16343, 'رَبَّانِيٌّ', 'رباني', 'منسوب', 'ربب', 'رباني', 'ربن', 'مَنْسُوبٌ إلَى الرَّبِّ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إلَى الرَّبِّ). ""عَاشَ رَبَّانِيّاً طَوَالَ حَيَاتِهِ"" : الْمُتَصَوِّفُ فِي عِبَادَةِ اللَّهِ وَالعَارِفُ بِهِ، وَالْمُتَأَلِّهُ فِيهِ، وَهِيَ صِفَةٌ تُطْلَقُ عَلَى الحَبْرِ اليَهُودِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16344, 'رُبُوبِيٌّ', 'ربوبي', 'منسوب', 'ربب', 'ربوبي', 'ربب', 'مَنْسُوبٌ إلَى الرَّبِّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رُبُوبِيٌّ-رُبُوبِيٌّ، ةٌ [ر ب ب] (مَنْسُوبٌ إلَى الرَّبِّ). ""اِدَّعَى الرُّبُوبِيَّةَ"" : الاتِّصَافُ بِصِفَاتِ الرَّبِّ. ""لَمْ يَدَّعِ الرُّبُوبِيَّةَ مَلِكٌ قَطُّ إلاَّ فِرْعَونَ"". (الجاحظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16345, 'رِبِّيٌّ', 'ربي', 'منسوب', 'ربب', 'ربي', 'رب', 'مَنْسُوبٌ إلَى الرَّبِّ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إلَى الرَّبِّ). ""جَلَسَ الرِّبِّيُّ يَعْقُوبُ يَقْرَأُ فُصُولاً مِنَ التَّوْرَاةِ"" : الْمُتَصَوِّفُ اليَهُودِيُّ العَارِفُ بِاللَّهِ وَالتَّوْرَاةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16346, 'رَبِيعِيُّ', 'ربيعي', 'منسوب', 'ربع', 'ربيعي', 'ربع', 'مَنْسُوبٌ إلَى الرَّبِيعِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رَبِيعِيُّ-رَبِيعِيُّ، ةٌ [ر ب ع] (مَنْسُوبٌ إلَى الرَّبِيعِ). ""طَقْسٌ رَبِيعِيٌّ رَائِعٌ"" : طَقْسُ زَمَنِ الرَّبِيعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16347, 'رُجُولِيٌّ', 'رجولي', 'منسوب', 'رجل', 'رجولي', 'رجل', 'مَنْسوبٌ إلَى الرُّجُولَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رُجُولِيٌّ-رُجُولِيٌّ، ةٌ [ر ج ل] (مَنْسوبٌ إلَى الرُّجُولَةِ).: كَمَالُ الصِّفَاتِ الْمُمَيِّزَةِ لِلرَّجُلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16348, 'رَمادِيٌّ', 'رمادي', 'منسوب', 'رمد', 'رمادي', 'رمد', 'مَنْسوبٌ إلى الرَّمادِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رَمادِيٌّ-رَمادِيٌّ، ةٌ [ر م د] (مَنْسوبٌ إلى الرَّمادِ). ""يَلْبَسُ مِعْطَفاً رَمادِيَّ اللَّوْنِ"" : ما كانَ لَوْنُهُ لَوْنَ الرَّمادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16349, 'رُمَّانِيٌّ', 'رماني', 'منسوب', '', 'رماني', 'رمن', 'مَنْسوبٌ إلى الرُّمّانِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رُمَّانِيٌّ-رُمَّانِيٌّ، ةٌ (مَنْسوبٌ إلى الرُّمّانِ). ""لَوْنٌ رُمّانِيٌّ"" : يُشْبِهُ لَوْنَ الرُّمَّانِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16350, 'رَمْلِيٌّ', 'رملي', 'منسوب', 'رمل', 'رملي', 'رمل', 'مَنْسوبٌ إلى الرَّمْلِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رَمْلِيٌّ-رَمْلِيٌّ، ةٌ [ر م ل] (مَنْسوبٌ إلى الرَّمْلِ). 1.""حَجَرٌ رَمْلِيٌّ"" : مُكَوَّنٌ مِنَ الرَّمْلِ. 2.""نَباتٌ رَمْلِيٌّ"" : نَباتٌ يَنْبُتُ في الرَّمْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16351, 'رِوَائِيٌّ', 'روائي', 'منسوب', 'روي', 'رواءي', 'ر', 'مَنْسوبٌ إلى الرِّوايَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"رِوَائِيٌّ-رِوَائِيٌّ، ةٌ [ر و ي] (مَنْسوبٌ إلى الرِّوايَةِ). ""هُوَ رِوائِيٌّ مُمْتازٌ"" : مَنْ يَكْتُبُ رِواياتٍ مِنَ الخَيالِ أَوْ بِحَبْكِ وَقائِعَ مِنَ الحَياةِ بِأُسْلوبٍ شَيِّقٍ وَيُقَدِّمُها في صُوَرٍ تَتَحَوَّلُ إِلَى قِصَّةٍ طَوِيلَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16352, 'رُوحَانِيٌّ', 'روحاني', 'منسوب', 'روح', 'روحاني', 'رحن', 'مَنْسوبٌ إلَى الرُّوحِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"رُوحَانِيٌّ-رُوحَانِيٌّ، ةٌ [ر و ح] (مَنْسوبٌ إلَى الرُّوحِ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16353, 'رُومانِيٌّ', 'روماني', 'منسوب', 'روم', 'روماني', 'رمن', 'مَنْسوبٌ إلى الرُّومِ أَو إِلى', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسوبٌ إلى الرُّومِ أَو إِلى رُوما)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16354, 'رِئَاسِيٌّ', 'رئاسي', 'منسوب', 'رأس', 'رءاسي', 'رس', 'مَنْسُوبٌ إِلَى الرِّئَاسَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رِئَاسِيٌّ-رِئَاسِيٌّ [ر أ س] (مَنْسُوبٌ إِلَى الرِّئَاسَةِ). ""النِّظَامُ الرِّئَاسِيُّ"" : نِظَامٌ سِيَاسِيٌّ تَكُونُ فِيهِ السُّلْطَةُ تَحْتَ الإِشْرَافِ الكَامِلِ لِرَئِيسِ الجُمْهُورِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16355, 'رِئَوِيٌّ', 'رئوي', 'منسوب', 'رأي', 'رءوي', 'ر', 'مَنْسُوبٌ إلَى الرِّئَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رِئَوِيٌّ-رِئَوِيٌّ، ةٌ [ر أ ي] (مَنْسُوبٌ إلَى الرِّئَةِ). ""أُصِيبَ بِالتِهَابٍ رِئَوِيٍّ"" : بِالْتِهَابٍ فِي الرِّئَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16356, 'رَئِيِسيٌّ', 'رئيسي', 'منسوب', 'رأس', 'رءيسي', 'رس', 'مَنْسُوبٌ إلَى الرَّئِيسِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رَئِيِسيٌّ-رَئِيِسيٌّ، ةٌ [ر أ س] (مَنْسُوبٌ إلَى الرَّئِيسِ). 1.""اِنْتَظَرَهُ فِي الشَّارِعِ الرَّئِيسِيِّ"" : أَهَمُّ شَارِعٍ فِي الْمَدِينَةِ. 2.""يَبْحَثُ عَنْ سَبَبٍ رَئِيسِيٍّ لِيُقَدّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16357, 'رِياضِيٌّ', 'رياضي', 'منسوب', 'روض', 'رياضي', 'رض', 'مَنْسوبٌ إلى الرِّياضَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسوبٌ إلى الرِّياضَةِ). 1.""رِياضِيٌّ مُمْتازٌ"" : مَنْ يُمارِسُ الرِّياضَةَ البَدَنِيَّةَ والتَّدارِيبَ والحَرَكاتِ البَدَنِيَّةَ. ""يُمارِسُ الأَلْعابَ الرِّياضِيَّةَ"". 2.""روحٌ رِياضِيَّةٌ"" : روحُ التَّآخِي وَسَعَةُ الصَّدْرِ وَتَقَبُّلُ نَتائِجِ الْمُباراةِ الرِّياضِيَّةِ بِصَدْرٍ رَحْبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16358, 'رِيفِيٌّ', 'ريفي', 'منسوب', 'ريف', 'ريفي', 'رف', 'مَنْسوبٌ إلَى الرِّيفِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسوبٌ إلَى الرِّيفِ). 1.""رَجُلٌ رِيفِيٌّ"" : مِنْ أَهْلِ الرِّيفِ. 2.""يَعيشُ حَياةً رِيفِيَّةً"" : بَدَوِيَّةً. ""أَلِفَ الحَياةَ الرِّيفِيَّةَ وَلَمْ يَعُدْ يَسْتَسيغُ حَياةَ الْمُدُنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16359, 'زُجاجِيٌّ', 'زجاجي', 'منسوب', 'زجج', 'زجاجي', 'زجج', 'مَنْسوبٌ إلَى الزَّجَّاجِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"زُجاجِيٌّ-زُجاجِيٌّ، ةٌ[ز ج ج]. 1. : مَنْسوبٌ إلَى الزَّجَّاجِ.2. : بائِعُ الزُّجاجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16360, 'زِراعِيٌّ', 'زراعي', 'منسوب', 'زرع', 'زراعي', 'زرع', 'مَنْسوبٌ إلى الزِّراعَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"زِراعِيٌّ-زِراعِيٌّ، ةٌ[ز ر ع] (مَنْسوبٌ إلى الزِّراعَةِ). 1.""تُعَدُّ مِنْطَقَةُ الغَرْبِ مِنْ أَخْصَبِ الأَرَاضِي الزِّراعِيَّةِ"" : أَراضٍ قابِلَةٌ لِلْحَرْثِ والزِّراعَةِ وإِنْتاجُها جَيِّدٌ. 2.""مُهَنْدِسٌ زِراعِيٌّ"" : الْمُتَخَرِّجُ مِنَ الْمَعْهَدِ الزِّراعِيِّ، أَيْ مَنْ يَتَعامَلَ مَعَ الزِّراعَةِ بِمَعْرِفَةٍ والْمُتَخَصِّصُ فيها. ""عامِلٌ زِرَاعِيٌّ"" ""الإِصْلاحُ الزِّراعِي"" ""طَريقٌ زِراعِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16361, 'زُلالِيٌّ', 'زلالي', 'منسوب', 'زلل', 'زلالي', 'زلل', 'مَنْسوبٌ إلى الزُّلالِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"زُلالِيٌّ-زُلالِيٌّ ، ةٌ[ز ل ل] (مَنْسوبٌ إلى الزُّلالِ). 1.""سائِلٌ زُلالِيٌّ"" : سائِلٌ يَحْتَوِي على مادَّةٍ بُروتِينِيَّةٍ بِها نِسْبَةٌ مِنَ الكِبْريتِ. 2.""بَوْلٌ زُلالِيٌّ"" : فيهِ مادَّةُ الزُّلالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16362, 'زَمَنِيٌّ', 'زمني', 'منسوب', 'زمن', 'زمني', 'زمن', 'مَنْسوبٌ إلَى الزَّمَنِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"زَمَنِيٌّ-زَمَنِيٌّ، ةٌ[ز م ن] (مَنْسوبٌ إلَى الزَّمَنِ). 1.""تَوْقيتٌ زَمَنِيٌّ"" : أَيْ لِمُدَّةٍ مُعَيَّنَةٍ. ""مَرْحَلَةٌ زَمَنِيَّةٌ"". 2.""قُنْبُلَةٌ زَمَنِيَّةٌ"" : أَيِ القُنْبُلَةُ الَّتِي تَنْفَجِرُ في زَمَنٍ مَضْبوطٍ، مُعَيَّنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16363, 'زَوْجِيٌّ', 'زوجي', 'منسوب', 'زوج', 'زوجي', 'زج', 'مَنْسوبٌ إلى الزَّوْجِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"زَوْجِيٌّ-زَوْجِيٌّ، ةٌ[ز و ج] (مَنْسوبٌ إلى الزَّوْجِ). 1.""يَعيشُ حَياةً زَوْجِيَّةً هادِئَةً"" : الحَياةُ الَّتِي تَجْمَعُ بَيْنَ الزَّوْجِ والزَّوْجَةِ بِالزَّواجِ. 2.""عَدَدٌ زَوْجِيٌّ"" : عَدَدٌ قابِلٌ لِلقِسْمَةِ عَلَى اثْنَيْنِ : 2. 4. 6. 8."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16364, 'زَيْتِيٌّ', 'زيتي', 'منسوب', 'زيت', 'زيتي', 'زت', 'مَنْسوبٌ إلى الزَّيْتِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"زَيْتِيٌّ-زَيْتِيٌّ، ةٌ[ز ي ت] (مَنْسوبٌ إلى الزَّيْتِ). 1.""نَباتٌ زَيْتِيٌّ"" : نَباتٌ يُعْطِي زَيْتاً. 2.""لَوْحَةٌ زَيْتِيَّةٌ"" : لَوْحَةٌ رُسِمَتْ بِمادَّةٍ مُلَوَّنَةٍ مَمْزوجَةٍ بِالزَّيْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16365, 'سَاحِلِيُّ', 'ساحلي', 'منسوب', 'سحل', 'ساحلي', 'سحل', 'مَنْسُوبٌ إلَى السَّاحِلِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"سَاحِلِيُّ-سَاحِلِيُّ، ةٌ [س ح ل] (مَنْسُوبٌ إلَى السَّاحِلِ). ""مَوْقِعٌ س"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16366, 'سِحْرِيٌّ', 'سحري', 'منسوب', 'سحر', 'سحري', 'سحر', 'مَنْسُوب إلَى السِّحْرِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"سِحْرِيٌّ-سِحْرِيٌّ، ةٌ [س ح ر] (مَنْسُوب إلَى السِّحْرِ). ""عَمَلٌ سِحْرِيٌّ"" : عَمَلٌ قَائِمٌ عَلَى السِّحْرِ، التَّمْوِيهُ والشَّعْوَذَةُ. ""جَاءَ بِأعْمَالٍ سِحْرِيَّةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16367, 'سِرِّيٌّ', 'سري', 'منسوب', 'سرر', 'سري', 'سر', 'مَنْسُوبٌ إلَى السِّرِّ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"سِرِّيٌّ-سِرِّيٌّ، ةٌ [س ر ر] (مَنْسُوبٌ إلَى السِّرِّ). 1.""سِرِّيٌّ جِدّاً"" : مَكْتُومٌ الإخْبَارُ بِهِ. 2.""عَقَدَتِ الْمَحْكَمَةُ جَلْسَةً سِرِّيَّةً"": جَلْسَةً مُغْلَقَةً غَيْرَ مُعْلَنَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16368, 'سَرْمَدِيٌّ', 'سرمدي', 'منسوب', '', 'سرمدي', 'سرمد', 'مَنْسُوبٌ إلَى السَّرْمَدِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"سَرْمَدِيٌّ-سَرْمَدِيٌّ، ةٌ (مَنْسُوبٌ إلَى السَّرْمَدِ). ""عَمَلٌ سَرْمَدِيٌّ"" : دَائِمٌ، أَبَدِيٌّ. ""أَوْرَثَهُمْ عَذَاباً ثُمَّ فَنَاءً سَرْمَدِيّاً"".(الأفغانِي)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16369, 'سَطْحِيٌّ', 'سطحي', 'منسوب', 'سطح', 'سطحي', 'سطح', 'مَنْسُوبٌ إلَى السَّطْحِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"سَطْحِيٌّ-سَطْحِيٌّ، ةٌ [س ط ح] (مَنْسُوبٌ إلَى السَّطْحِ). 1.""فِكْرٌ سَطْحِيٌّ"" : أيْ لاَ عَمَلَ فِيهِ، بَسِيطٌ. ""مَعْلُومَاتٌ سَطْحِيَّةٌ"" ""آرَاءٌ سَطْحِيَّةٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16370, 'سُعُودِيٌّ', 'سعودي', 'منسوب', '', 'سعودي', 'سعد', 'مَنْسُوبٌ إلَى السُّعُودِيَّةِ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسُوبٌ إلَى السُّعُودِيَّةِ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16371, 'سُفْلِيٌّ', 'سفلي', 'منسوب', 'سفل', 'سفلي', 'سفل', 'مَنْسُوبٌ إلَى السُّفْلِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"سُفْلِيٌّ-سُفْلِيٌّ، ةٌ [س ف ل] (مَنْسُوبٌ إلَى السُّفْلِ). ""يَسْكُنُ فِي الطَّابَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16372, 'سَلْبِيٌّ', 'سلبي', 'منسوب', 'سلب', 'سلبي', 'سلب', 'مَنْسُوبٌ إلَى السَّلْبِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"سَلْبِيٌّ-سَلْبِيٌّ، ةٌ [س ل ب] (مَنْسُوبٌ إلَى السَّلْبِ). 1.""تَلَقَّى جَوَاباً سَلْبِيّاً"" : بِالنَّفْيِ، بِالرَّفْضِ. 2. ""اِتَّخَذَ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16373, 'سَمَاوِيٌّ', 'سماوي', 'منسوب', 'سمو', 'سماوي', 'سم', 'مَنْسُوبٌ إلَى السَّمَاءِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"سَمَاوِيٌّ-سَمَاوِيٌّ، ةٌ [س م و] (مَنْسُوبٌ إلَى السَّمَاءِ). 1.""سَمَاوِيُّ اللَّوْنِ"" : يَمِيلُ إلَى زُرْقَةِ السَّمَاءِ. ""لَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16374, 'سَمَاعِيٌّ', 'سماعي', 'منسوب', 'سمع', 'سماعي', 'سمع', 'منْسُوبٌ إلَى السَّمَاعِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"سَمَاعِيٌّ-سَمَاعِيٌّ [س م ع] (منْسُوبٌ إلَى السَّمَاعِ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16375, 'سَنَوِيٌّ', 'سنوي', 'منسوب', 'سنو', 'سنوي', 'سن', 'مَنْسُوبٌ إلَى السَّنَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"سَنَوِيٌّ-سَنَوِيٌّ، ةٌ [س ن و] (مَنْسُوبٌ إلَى السَّنَةِ). ""المِهْرَجَانُ السَّنَوِيُّ"" : أيِ المِهْرَجَانُ الَّذِي يَنْعَقِدُ مَرَّةً كُلَّ سَنَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16376, 'سُنِّيٌّ', 'سني', 'منسوب', 'سنن', 'سني', 'سن', 'مَنْسُوبٌ إلَى السُّنَّةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"سَنِيٌّ-سَنِيٌّ، ةٌ [س ن ي] (صف). ""مَقَامٌ سَنِيٌّ"" : رَفِيعٌ، ذُو سَنَاءٍ. ""بَلَغَ مَرْتَبَةً سَنِيَّةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16377, 'سِنْجابِيٌّ', 'سنجابي', 'منسوب', '', 'سنجابي', 'سنجب', 'مَنْسوب إلَى السِّنْجَابِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"سِنْجابِيٌّ-سِنْجابِيٌّ، ةٌ (مَنْسوب إلَى السِّنْجَابِ). ""لَوْنٌ سِنْجَابِيٌّ"": لَوْنٌ أزْرقُ رَمادِيٌّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16378, 'سُهْلِيٌّ', 'سهلي', 'منسوب', 'سهل', 'سهلي', 'سهل', 'منسوب إلَى السَّهْلِ علَى غيْر', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"سُهْلِيٌّ-سُهْلِيٌّ، ةٌ [س هـ ل] (منسوب إلَى السَّهْلِ علَى غيْرِ قِياسٍ). 1. ""نَبَاتٌ سُهْلِيٌّ"" : يَنْبُتُ فِي السَّهْل. 2. ""مَاشِيَةٌ سُهْلِيَّةٌ"" : تَرْعَى فِي السَّهْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16379, 'سُودانِيٌّ', 'سوداني', 'منسوب', 'سود', 'سوداني', 'سدن', 'مَنْسوبٌ إلى السُّودانِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"سُودانِيٌّ-سُودانِيٌّ، ةٌ [س و د] (مَنْسوبٌ إلى السُّودانِ). ""اِلْتَقَى بِسودانِيٍّ"" : مُواطِنٌ مِنَ السُّودانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16380, 'سُوفِياتِيٌّ', 'سوفياتي', 'منسوب', '', 'سوفياتي', 'سفت', 'مَنْسوبٌ إلى السُّوفِيَات', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"سُوفِياتِيٌّ-سُوفِياتِيٌّ (مَنْسوبٌ إلى السُّوفِيَات). ""الاتِّحادُ السُّوفِياتِي"" : ما كانَ يُعْرَفُ سابِقاً بِمَجْمُوعِ الجمهوريّات الاشتِراكيَّةِ السُّوفياتيَّةِ، قَبْلَ أن يُفَتَّتَ إلى دُوَلٍ مُسْتَقِلَّةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16381, 'سِياسِيٌّ', 'سياسي', 'منسوب', 'سوس', 'سياسي', 'سس', 'مَنْسوبٌ إلى السِّياسَةِ ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسوبٌ إلى السِّياسَةِ . 1.""هُوَ رَجُلٌ سِياسِيٌّ"" : مَنْ يَحْتَرِفُ السِّيَاسَةَ وَيَفْهَمُ قَضَاياها، وَيُمارِسُ شُؤ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16382, 'سينَمائِيّ', 'سينمائي', 'منسوب', '', 'سينماءي', 'سنم', 'مَنْسوبٌ إلى السِّينَما.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": مَنْسوبٌ إلى السِّينَما."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16383, 'شَامِيٌّ', 'شامي', 'منسوب', 'شأم', 'شامي', 'شم', 'مَنْسُوبٌ إلَى الشَّامِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إلَى الشَّامِ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16384, 'شَتْوِيُّ', 'شتوي', 'منسوب', 'شتو', 'شتوي', 'شت', 'مَنْسُوبٌ إلَى الشِّتَاءِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شَتْوِيُّ-شَتْوِيُّ، ةٌ [ش ت و] (مَنْسُوبٌ إلَى الشِّتَاءِ). ""فِي يَوْمٍ شَت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16385, 'شَرْعِيٌّ', 'شرعي', 'منسوب', 'شرع', 'شرعي', 'شرع', 'مَنْسُوبٌ إِلَى الشَّرْعِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"شَرْعِيٌّ-شَرْعِيٌّ، ةٌ [ش ر ع] (مَنْسُوبٌ إِلَى الشَّرْعِ). 1.""حُكْمٌ شَرْعِيٌّ"" : حُكْمٌ خَاضِعٌ لأَحْكَامِ الشَّرْعِ. 2.""زَوَاجٌ شَرْعِيٌّ"" : زَوَاجٌ حَسَبَ أَحْكَامِ الشَّرْعِ وَالعَقِيدَةِ. 3. ""طَبِيبٌ شَرْعِيٌّ"" : طَبِيبٌ مُؤَهَّلٌ لِلإِد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16386, 'شَرْقِيٌّ', 'شرقي', 'منسوب', 'شرق', 'شرقي', 'شرق', 'مَنْسُوبٌ إِلَى الشَّرْقِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"شَرْقِيٌّ-شَرْقِيٌّ، ةٌ [ش ر ق] (مَنْسُوبٌ إِلَى الشَّرْقِ). 1.""رَجُلٌ شَرْقِيٌّ"" : مِنْ سُكَّانِ الشَّرْقِ. 2.""اِسْتَقَرَّ فِي البِلاَدِ الشَّرْقِيَّةِ"" : فِي البِلاَدِ الواقِعَةِ فِي الْمَشْرِقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16387, 'شَعْبِيٌّ', 'شعبي', 'منسوب', 'شعب', 'شعبي', 'شعب', 'مَنْسُوبٌ إِلَى الشَّعْبِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شَعْبِيٌّ-شَعْبِيٌّ، ةٌ [ش ع ب] (مَنْسُوبٌ إِلَى الشَّعْبِ). 1.""رَجُلٌ شَعْبِيٌّ"" : رَجُلٌ مُتَخَلِّقٌ بِأَخْلاَقِ شَعْبِهِ، بَسِيطٌ فِي تَعَامُلِهِ مِثْلَ كُلِّ أَفْرَادِهِ. 2. ""الأَدَبُ الشَّعْبِيُّ"" : أَدَبُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16388, 'شِعْرِيٌّ', 'شعري', 'منسوب', 'شعر', 'شعري', 'شعر', 'مَنْسُوبٌ إِلَى الشِّعْرِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شِعْرِيٌّ-شِعْرِيٌّ، ةٌ [ش ع ر] (مَنْسُوبٌ إِلَى الشِّعْرِ). ""اِنْغَمَسَ فِي جَوٍّ شِعْرِيٍّ"" : فِي جَوِّ عَالَمِ الشِّعْرِ. ""اِسْتَمَعَ إِلَى أُغْنِيَّةٍ شِعْرِيَّةٍ مُغَنَّاةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16389, 'شِفَاهِيٌّ', 'شفاهي', 'منسوب', 'شفه', 'شفاهي', 'شفه', 'مَنْسُوبٌ إِلَى الشِّفَاهِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شِفَاهِيٌّ-شِفَاهِيٌّ، ةٌ [ش ف هـ] (مَنْسُوبٌ إِلَى الشِّفَاهِ). 1.""تَقَدَّمَ لِلاِمْتِحَانِ الشِّفَاهِيِّ"" : اِمْتِحَانٌ يُجِيبُ فِيهِ الطَّالِبُ عَنْ أَسْئِلَةِ الأُسْتَاذِ مِنَ الذَّاكِرَةِ مُبَاشَرَةً قَوْلاً لاَ كِتَابَةً. 2.""خَاطَبَ الجُمْهُورَ شِفَاهِيّاً"" : اِرْتِجالاً، أَي اِرْتَجَلَ كَلاَماً غَيْرَ مَكْتُوبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16390, 'شَفَوِيٌّ', 'شفوي', 'منسوب', 'شفه', 'شفوي', 'شف', 'مَنْسُوبٌ إِلَى الشَّفَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شَفَوِيٌّ-شَفَوِيٌّ، ةٌ [ش ف هـ] (مَنْسُوبٌ إِلَى الشَّفَةِ). ""الْحُرُوفُ الشَّفَوِيَّةُ هِيَ البَاءُ وَالفَاءُ وَالمِيمُ"" : أَيِ الْحُرُوفُ الَّتِي يَكُونُ مَخْرَجُهَا مِنَ الشَّفَتَيْنِ. ""صَوْتٌ شَفَوِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16391, 'شَفَهِيٌّ', 'شفهي', 'منسوب', 'شفه', 'شفهي', 'شفه', 'مَنْسُوبٌ إِلَى الشِّفَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شَفَهِيٌّ-شَفَهِيٌّ، ةٌ [ش ف هـ] (مَنْسُوبٌ إِلَى الشِّفَةِ). ن. شَفَاهِيٌّ، شَفَوِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16392, 'شَكْلِيٌّ', 'شكلي', 'منسوب', 'شكل', 'شكلي', 'شكل', 'مَنْسُوبٌ إِلَى الشَّكْلِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شَكْلِيٌّ-شَكْلِيٌّ، ةٌ [ش ك ل] (مَنْسُوبٌ إِلَى الشَّكْلِ). ""يَهْتَمُّ بِالقَضَايَا الشَّكْلِيَّةِ "" : يَهْتَمُّ بِمَا هُوَ ظَاهِرٌ وَخَارِجِيٌّ دُونَ الجَوْهَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16393, 'شَمْسِيٌّ', 'شمسي', 'منسوب', 'شمس', 'شمسي', 'شمس', 'مَنْسُوبٌ إِلَى الشَّمْسِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شَمْسِيٌّ-شَمْسِيٌّ، ةٌ [ ش م س] (مَنْسُوبٌ إِلَى الشَّمْسِ). 1.""النِّظَامُ الشَّمْسِيُّ"" : هُوَ مَجْمُوعُ الأَجْسَامِ السَّمَاوِيَّةِ الَّتِي تُكَوِّنُهَا الشَّمْسُ وَحَقْلُ جَاذِبِيَّتِهَا، وَعَدَدُهَا تِسْعَةُ أَجْرَامٍ : الأَرْضُ وَعُطَارِدُ وَفِينُوسُ وَالْمِرِّيخُ والْمُشْتَرِي وَزُحَلُ وَأُورَانُس وَنِيبْتُون وَبْلُوتُن. 2.""سَاعَةٌ شًمْسِيَّةٌ"" : مِسَاحَةٌ دَائِرِيَّةٌ بِهَا خُطُوطٌ يَنْعَكِسُ عَلَيْهَا ظِلُّ قَضِيبٍ مُنْحَنٍ يُشِيرُ إِلَى سَاعَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16394, 'شَهْرِيٌّ', 'شهري', 'منسوب', 'شهر', 'شهري', 'شهر', 'مَنْسُوبٌ إِلَى الشَّهْرِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شَهْرِيٌّ-شَهْرِيٌّ، ةٌ [ش هـ ر] (مَنْسُوبٌ إِلَى الشَّهْرِ). 1.""يُؤَدِّي انْخِرَاطَهُ شَهْرِيّاً"" : مِقْدَارُ مَا يُؤَدِّيهِ فِي كُلِّ شَهْرٍ. ""الانْخِرَاطُ الشَّهْرِيُّ"". 2.""مَجَلَّةٌ شَهْرِيَّةٌ"" : مَجَلَّةٌ تَصْدُرُ مَرَّةً فِي كُلِّ شَهْرٍ. 3.""الدَّوْرَةُ الشَّهْرِيَّةُ"" : دَمُ الْحَيْضِ عِنْدَ الْمَرْأَةِ الْحَاصِلُ مَرَّةً فِي الشَّهْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16395, 'شَهْوَانِيٌّ', 'شهواني', 'منسوب', 'شهو', 'شهواني', 'شهن', 'مَنْسُوبٌ إِلَى الشَّهْوَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"شَهْوَانِيٌّ-شَهْوَانِيٌّ، ةٌ [ش هـ و] (مَنْسُوبٌ إِلَى الشَّهْوَةِ). ""رَجُلٌ شَهْوَانِيٌّ"" : رَجُلٌ شَدِيدُ الرَّغْبَةِ فِي الْمَلَذَّاتِ الْمَادِّيَّةِ وَالْجِنْسِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16396, 'شَوْكِيٌّ', 'شوكي', 'منسوب', 'شوك', 'شوكي', 'شك', 'مَنْسُوبٌ إِلَى الشَّوْكِ، الش', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شَوْكِيٌّ-شَوْكِيٌّ [ش و ك] (مَنْسُوبٌ إِلَى الشَّوْكِ، الشَّوْكَةُ). 1.""النُّخَاعُ الشَّوْكِيُّ"" : جُزْءُ الْجِهَازِ العَصَبِيِّ الْمَرْكَزِيِّ دَاخِلَ القَنَاةِ الفِقَرِيَّةِ. 2.""التِّينُ الشَّوْكِيُّ"" .ن. التِّينُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16397, 'شِيعِيٌّ', 'شيعي', 'منسوب', 'شيع', 'شيعي', 'شع', 'مَنْسُوبٌ إِلَى الشِّيعَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"شِيعِيٌّ-شِيعِيٌّ، ةٌ [ش ي ع] (مَنْسُوبٌ إِلَى الشِّيعَةِ).""هُوَ شِيعِيّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16398, 'شُيُوعِيٌّ', 'شيوعي', 'منسوب', 'شيع', 'شيوعي', 'شع', 'مَنْسُوبٌ إِلَى الشُّيُوعِيَّة', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"شُيُوعِيٌّ-شُيُوعِيٌّ، ةٌ [ش ي ع] (سيا) (مَنْسُوبٌ إِلَى الشُّيُوعِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16399, 'صِبْيَانِيٌّ', 'صبياني', 'منسوب', 'صبو', 'صبياني', 'صبن', 'مَنْسُوبٌ إِلَى الصَّبِيِّ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"صِبْيَانِيٌّ-صِبْيَانِيٌّ، ةٌ [ص ب و] (مَنْسُوبٌ إِلَى الصَّبِيِّ). ""عَمَلٌ صِبْيَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16400, 'صَحَابِيٌّ', 'صحابي', 'منسوب', 'صحب', 'صحابي', 'صحب', 'مَنْسُوبٌ إِلَى الصَّحَابَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"صَحَابِيٌّ-صَحَابِيٌّ [ص ح ب] (مَنْسُوبٌ إِلَى الصَّحَابَةِ). وَتَعْنِي أَيْضاً الوَاحِدَ مِنْهُمْ. ج: صَحَابَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16401, 'صِحَافِيٌّ', 'صحافي', 'منسوب', 'صحف', 'صحافي', 'صحف', 'مَنْسُوبٌ إِلَى الصِّحَافَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"صِحَافِيٌّ-صِحَافِيٌّ، ةٌ [ص ح ف] (مَنْسُوبٌ إِلَى الصِّحَافَةِ). ""قَامَ بِعَمَلٍ صِحَافِيٍّ جَيِّدٍ"" : مَا يُقَدِّمُهُ الصِّحَافِيُّ مِنْ عَمَلٍ فِي مَجَالِ الصِّحَافَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16402, 'صَحْرَاوِيٌّ', 'صحراوي', 'منسوب', 'صحر', 'صحراوي', 'صحر', 'مَنْسُوبٌ إِلَى الصَّحْرَاءِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"صَحْرَاوِيٌّ-صَحْرَاوِيٌّ، ةٌ [ص ح ر] (مَنْسُوبٌ إِلَى الصَّحْرَاءِ). 1.""رَجُلٌ صَحْرَاوِيٌّ"" : مِنْ رِجَالِ الصَّحْرَاءِ. 2.""مُنَاخٌ صَحْرَاوِيٌّ"" : مُنَاخٌ شَدِيدُ الْحَرَارَةِ فِي النَّهَارِ وَالصَّيْفِ، شَدِيدُ البَرْدِ فِي اللَّيْلِ وَالشِّتَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16403, 'صَخْرِيٌّ', 'صخري', 'منسوب', 'صخر', 'صخري', 'صخر', 'مَنْسُوبٌ إِلَى الصَّخْرِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"صَخْرِيٌّ-صَخْرِيٌّ، ةٌ [ص خ ر] (مَنْسُوبٌ إِلَى الصَّخْرِ). 1.""حَجَرٌ صَخْرِيٌّ"" : الْحَجَرُ الْمُتَكَسِّرُ مِنَ الصَّخْرِ الصَّلْبِ. 2.""مِنْطَقَةٌ صَخْرِيَّةٌ"" : مِنْطَقَةٌ بِهَا الْحَجَرُ الْعَظِيمُ الصَّلْبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16404, 'صَنَوْبَرِيٌّ', 'صنوبري', 'منسوب', '', 'صنوبري', 'صنبر', 'مَنْسُوبٌ إِلَى الصَّنَوْبَرِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"صَنَوْبَرِيٌّ-صَنَوْبَرِيٌّ، ةٌ (مَنْسُوبٌ إِلَى الصَّنَوْبَرِ). : أَيْ مَا كَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16405, 'صُوفِيٌّ', 'صوفي', 'منسوب', 'صوف', 'صوفي', 'صف', 'مَنْسُوبٌ إِلَى الصُّوفِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الصُّوفِ). 1.""لِبَاسٌ صُوفِيٌّ"" : لِبَاسٌ مِنَ الصُّوفِ. 2.""كَانَ رَجُلاً صُوفِيّاً"" : السَّالِكُ طَرِيقَ التَّصَوُّفِ وَالتَّعَبُّدِ وَالزُّهْدِ وَالتَّقَشُّفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16406, 'صُومَالِيٌّ', 'صومالي', 'منسوب', '', 'صومالي', 'صمل', 'مَنْسُوبٌ إِلَى الصُّومَالِ.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":ـ"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ــات. (مَنْسُوبٌ إِلَى الصُّومَالِ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16407, 'صَيْدَلِيٌّ', 'صيدلي', 'منسوب', 'صيدل', 'صيدلي', 'صدل', 'مَنْسُوبٌ إِلَى الصَّيْدَلَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":صَيَادِلَةٌ"', '', '', '', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الصَّيْدَلَةِ). ""شَرَحَ لَهُ الصَّيْدَلِيُّ كَيْفَ يَتَنَاوَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16408, 'صَيَادِلَةٌ', 'صيادلة', 'منسوب', '', 'صيادلة', 'صدلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16409, 'صَيْفِيٌّ', 'صيفي', 'منسوب', 'صيف', 'صيفي', 'صف', 'مَنْسُوبٌ إِلَى الصَّيْفِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"صَيْفِيٌّ-صَيْفِيٌّ، ةٌ [ص ي ف] (مَنْسُوبٌ إِلَى الصَّيْفِ). 1.""مَطَرٌ صَيْفِيٌّ"" : الْمَطَرُ الَّذِي يَنْزِلُ بِالصَّيْفِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16410, 'ضَبَابِيٌّ', 'ضبابي', 'منسوب', 'ضبب', 'ضبابي', 'ضبب', 'مَنْسُوبٌ إِلَى الضَّبَابِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"ضَبَابِيَّةٌ-ضَبَابِيَّةٌ [ض ب ب] (مَنْسُوبٌ إِلَى الضَّبَابِ). 1.""عَاشَ فِي أَجْوَاءٍ ضَبَابِيَّةٍ"" : يَكْتَنِفُهَا الضَّبَابُ. 2.""أُمورٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16411, 'ضَرُورِيٌّ', 'ضروري', 'منسوب', 'ضرر', 'ضروري', 'ضرر', 'مَنْسُوبٌ إِلَى الضَّرُورَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"ضَرُورِيٌّ-ضَرُورِيٌّ، ةٌ [ض ر ر] (مَنْسُوبٌ إِلَى الضَّرُورَةِ). 1.""الْحُضُورُ ضَرُورِيٌّ وَمُؤَكَّدٌ"" : حُضُورٌ تَدْعُو إِلَيْهِ حَاجَةٌ مُلِحَّةٌ. 2.""العَمَلُ ضَرُورِيٌّ لِلْحَيَاةِ"" : لاَ بُدَّ مِنْهُ. 3.""مِنَ الضَّرُورِيِّ أَنْ تَحْضُرَ بِنَفْسِكَ"" : مِنَ اللاَّزِمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16412, 'ضَرِيبِيٌّ', 'ضريبي', 'منسوب', 'ضرب', 'ضريبي', 'ضرب', 'مَنْسُوبٌ إِلَى الضَّرِيبَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"ضَرِيبِيٌّ-ضَرِيبِيٌّ، ةٌ [ض ر ب] (مَنْسُوبٌ إِلَى الضَّرِيبَةِ). ""نِظَامٌ ضَرِيبِيٌّ"" : نِظَامٌ خَاضِعٌ لِفَرْضِ الضَّرائِبِ وجِبَايَتِها ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16413, 'ضِمْنِيٌّ', 'ضمني', 'منسوب', 'ضمن', 'ضمني', 'ضمن', 'مَنْسُوبٌ إِلَى الضِّمْنِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"ضِمْنِيٌّ-ضِمْنِيٌّ، ةٌ [ض م ن] (مَنْسُوبٌ إِلَى الضِّمْنِ). ""ضِمْنِيّاً اِعْتَرَفَ بِخَطَئِهِ"" : عَبَّرَ عَنْ خَطَئِهِ بِشَكْلٍ غَيْرِ مُبَاشِرٍ دُونَ التَّصْرِيحِ بِهِ. ""وَافَقَ بِصُورَةٍ ضِمْنِيَّةٍ عَلَى الاقْتِرَاحِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16414, 'طائِفِيٌّ', 'طائفي', 'منسوب', 'طوف', 'طاءفي', 'طف', 'مَنْسُوبٌ إِلَى الطَّائِفَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"طائِفِيٌّ-طائِفِيٌّ، ةٌ [ط و ف] (مَنْسُوبٌ إِلَى الطَّائِفَةِ). 1.""رَجُلٌ طَائِفِيٌّ"" : مَنْ يَتَعَصَّبُ لِطَائِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16415, 'طِبِّيٌّ', 'طبي', 'منسوب', 'طبب', 'طبي', 'طب', 'مَنْسُوبٌ إِلَى الطِّبِّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"طِبِّيٌّ-طِبِّيٌّ [ط ب ب] (مَنْسُوبٌ إِلَى الطِّبِّ). 1.""نَبَاتٌ طِبِّيٌّ"" : نَبَاتٌ يُسْتَعْمَلُ لأ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16416, 'طَبَقِيٌّ', 'طبقي', 'منسوب', 'طبق', 'طبقي', 'طبق', 'مَنْسُوبٌ إِلَى الطَّبَقَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"طَبَقِيٌّ-طَبَقِيٌّ، ةٌ [ط ب ق] (مَنْسُوبٌ إِلَى الطَّبَقَةِ). ""الصِّرَاعُ الطَّبَقِيُّ"" : الصِّرَاعُ الدَّائِرُ بَيْنَ الطَّبَقَاتِ فِي الْمُجْتَمَعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16417, 'طَبِيعِيٌّ', 'طبيعي', 'منسوب', 'طبع', 'طبيعي', 'طبع', 'مَنْسُوبٌ إِلَى الطَّبِيعَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"طَبِيعِيٌّ-طَبِيعِيٌّ، ةٌ [ط ب ع] (مَنْسُوبٌ إِلَى الطَّبِيعَةِ). 1.""مَنَاظِرُ طَبِيعِيَّةٌ"" : مَنَاظِرُ مِنَ الطَّبِيعَةِ. 2.""وَفَاةٌ طَبِيعِيَّةٌ"" : وَفَاةٌ لَمْ تَحْدُثْ بِسَبَبِ عَارِضٍ أَوْ حَادِثٍ. 3.""إِنْتَاجٌ طَبِيعِيٌّ"" : غَيْرُ مَصْنُوعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16418, 'طُفُولِيٌّ', 'طفولي', 'منسوب', 'طفل', 'طفولي', 'طفل', 'مَنْسُوبٌ إِلَى الطُّفُولَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"طُفُولِيٌّ-طُفُولِيٌّ، ةٌ [ط ف ل] (مَنْسُوبٌ إِلَى الطُّفُولَةِ). ""عَمَلٌ طُفُولِيٌّ"" : عَمَلٌ غَيْرُ نَاضِجٍ تَشُوبُهُ صِفَاتُ الأَطْفَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16419, 'عَاجِيٌّ', 'عاجي', 'منسوب', '', 'عاجي', 'عج', 'مَنْسُوبٌ إِلَى الْعَاجِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَاجِيٌّ-عَاجِيٌّ (مَنْسُوبٌ إِلَى الْعَاجِ). ""بُرْجٌ عَاجِيٌّ"" : بُرْجٌ مُنْعَزِلٌ عَنِ النَّاسِ، وَهُوَ مُصْطَلَحٌ يُسْتَخْدَمُ فِي الأَدَبِ للِتَّعْبِيرِ عَنْ عُزْلَةِ الأَدِيبِ غَيْرِ الْمُهْتَمِّ بِالقَضَايَا الاجْتِمَاعِيَّةِ وَمَشَاغِلِ النَّاسِ. ""يَعِيشُ فِي بُرْجِهِ الْعَاجِيِّ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16420, 'عَالَمِيٌّ', 'عالمي', 'منسوب', 'علم', 'عالمي', 'علم', 'مَنْسُوبٌ إِلَى الْعَالَمِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عَالَمِيٌّ-عَالَمِيٌّ، ةٌ [ع ل م] (مَنْسُوبٌ إِلَى الْعَالَمِ). ""الْحَرْبُ الْعَالَمِيَّةُ"" : الْحَرْبُ الَّتِي شَارَكَتْ فِيهَا دُوَلُ الْعَالَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16421, 'عَامِّيٌّ', 'عامي', 'منسوب', 'عمم', 'عامي', 'عم', 'مَنْسُوبٌ إِلَى الْعَامِّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَامِّيٌّ-عَامِّيٌّ، ةٌ [ع م م] (مَنْسُوبٌ إِلَى الْعَامِّ). 1.""رَجُلٌ عَامِّيٌّ"" : دَارِجٌ، شَعْبِيٌّ. ""كَلاَمٌ عَامِّيٌّ"" ""اللُّغَةُ الْعَامِّيَّةُ"". 2.""عَامِّيَّةُ كَذَا"" : حَرَكَةٌ أَوْ ثَوْرَةٌ يَقُومُ بِهَا الشَّعْبُ ضِدَّ السُّلْطَةِ الْحَاكِمَةِ لانْتِزَاعِ حُقُوقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16422, 'عِبْرَانِيٌّ', 'عبراني', 'منسوب', 'عبر', 'عبراني', 'عبرن', 'مَنْسُوبٌ إِلَى الْعِبْرَانَيّ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْعِبْرَانَيَّةِ). الْيَهُودِيُّ،ةُ، وَهِيَ التَّسْمِيَةُ الْقَدِيمَةُ الخَاصَّةُ بِالْيَهُودِ. ""اللُّغَةُ الْعِبْرَانِيَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16423, 'عَجَمِيٌّ', 'عجمي', 'منسوب', 'عجم', 'عجمي', 'عجم', 'مَنْسُوبٌ إِلَى الْعَجَمِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عَجَمِيٌّ-عَجَمِيٌّ، ةٌ [ع ج م] (مَنْسُوبٌ إِلَى الْعَجَمِ). : مَنْ يَنْتَمِي إِلَى بِلاَدِ الْعَجَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16424, 'أَعْجَميٌّ', 'أعجمي', 'منسوب', 'عجم', 'ءعجمي', 'عجم', 'مَنْسوبٌ إلى العَجَمِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"أَعْجَميٌّ-أَعْجَميٌّ، ةٌ [ع ج م] (مَنْسوبٌ إلى العَجَمِ). ""إِنَّهُ أَعْجَمِيٌّ"" : مَنْ كانَ غَيْرَ عَرَبِيٍّ. ¨ ""كَلاَمٌ أَعْجَمِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16425, 'عَدَدِيٌّ', 'عددي', 'منسوب', 'عدد', 'عددي', 'عدد', 'مَنْسُوبٌ إِلَى الْعَدَدِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَدَدِيٌّ-عَدَدِيٌّ [ع د د] (مَنْسُوبٌ إِلَى الْعَدَدِ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16426, 'عَدْلِيٌّ', 'عدلي', 'منسوب', 'عدل', 'عدلي', 'عدل', 'مَنْسُوبٌ إِلَى الْعَدْلِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَدْلِيٌّ-عَدْلِيٌّ، ةٌ [ع د ل] (مَنْسُوبٌ إِلَى الْعَدْلِ). ""أَضَافَ السِّجِلَّ الْعَدْلِيَّ إِلَى مِلَفِّهِ"" : شَهَادَةٌ تُسَلِّمُهَا وِزَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16427, 'عُدْوَانِيٌّ', 'عدواني', 'منسوب', 'عدو', 'عدواني', 'عدن', 'مَنْسُوبٌ إِلَى الْعُدْوَانِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عُدْوَانِيٌّ-عُدْوَانِيٌّ، ةٌ [ع د و] (مَنْسُوبٌ إِلَى الْعُدْوَانِ). 1.""هُجُومٌ عُدْوَانِيٌّ"" : هُجُومٌ ظَالِمٌ. 2.""رَجُلٌ عُدْوَانِيٌّ"" : رَجُلٌ شَرِسٌ يَعْتَدِي عَلَى غَيْرِهِ بِلِسَانِهِ أَوْ سِلاَحِهِ. ""اِمْرَأَةٌ عُدْوَانِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16428, 'عَرَبِيٌّ', 'عربي', 'منسوب', 'عرب', 'عربي', 'عرب', 'مَنْسُوبٌ إِلَى الْعَرَبِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَرَبِيٌّ-عَرَبِيٌّ، ةٌ [ع ر ب] (مَنْسُوبٌ إِلَى الْعَرَبِ). ""الْعَالَمُ الْعَرَبِيُّ"" ""الأُمَّةُ الْعَرَبِيَّةُ"" ""اللُّغَةُ الْعَرَبِيَّةُ"" ""الْوَحْدَةُ الْعَرَبِيَّةُ"" ""فِلَسْطِينُ عَرَبِيَّةٌ"" ""الْحِوَارُ الْعَرَبِيُّ الأُورُوبِّيُّ مُسْتَمِرٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16429, 'عُرْفِيٌّ', 'عرفي', 'منسوب', 'عرف', 'عرفي', 'عرف', 'مَنْسُوبٌ إِلَى الْعُرْفِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عُرْفِيٌّ-عُرْفِيٌّ، ةٌ [ع ر ف] (مَنْسُوبٌ إِلَى الْعُرْفِ). ""حُكْمٌ عُرْفِيٌّ"" : هُوَ مَا لاَ يَخْضَعُ لِقَوَاعِدِ القَانُونِ الْعَامِّ، مُرَاعَاةً لِمُقْتَضَيَاتِ الأَمْنِ فِي ظُرُوفٍ طَارِئَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16430, 'عَزْمِيٌّ', 'عزمي', 'منسوب', 'عزم', 'عزمي', 'عزم', 'مَنْسُوبٌ إِلَى العَزْمِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَزْمِيٌّ-عَزْمِيٌّ [ع ز م] (مَنْسُوبٌ إِلَى العَزْمِ). 1.""هُوَ عَزْمِيٌّ"" : يَفِي بِالعَهْدِ. 2. : مِنَ الأَسْمَاءِ العَائِلِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16431, 'عَصْرِيٌّ', 'عصري', 'منسوب', 'عصر', 'عصري', 'عصر', 'مَنْسُوبٌ إِلَى العَصْرِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عَصْرِيٌّ-عَصْرِيٌّ، ةٌ [ع ص ر] (مَنْسُوبٌ إِلَى العَصْرِ). ""رَجُلٌ عَصْرِيٌّ"" : أَيْ رَجُلٌ يَعِيشُ حَسَبَ تَطَوُّرِ زَمَنِهِ الْحَدِيثِ. ""مَفَاهِيمُ عَصْرِيَّةٌ"" ""أَفْكَارٌ عَصْرِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16432, 'عُضْوِيٌّ', 'عضوي', 'منسوب', 'عضو', 'عضوي', 'عض', 'مَنْسُوبٌ إِلَى العُضْوِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عُضْوِيٌّ-عُضْوِيٌّ، ةٌ [ع ض و] (مَنْسُوبٌ إِلَى العُضْوِ). 1.""مَرَضٌ عُضْوِيٌّ"" : مَرَضٌ دَاؤُهُ مُرْتَبِطٌ بِالعُضْوِ، وَيُشَكِّلُ جُزْءاً لاَ يَتَجَزَّأُ مِنْهُ. 2.""الكِيمِيَاءُ العُضْوِيَّةُ"" : قِسْمٌ مِنَ الكِيمِيَاءِ خَاصٌّ بِدِرَاسَةِ مُرَكَّبَاتِ الكَرْبُونِ الِّتِي يُوجَدُ أَغْلَبُهَا فِي الأَنْسِجَةِ الْحَيَّةِ. 3.""الوَحْدَةُ العُضْوِيَّةُ فِي القَصِيدَةِ"" : أَيِ الْمُتَكَوِّنَةُ مِنْ أَجْزَاءٍ مُتَرَابِطَةٍ لاَ تَتَجَزَّأُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16433, 'عَقْلِيٌّ', 'عقلي', 'منسوب', 'عقل', 'عقلي', 'عقل', 'مَنْسُوبٌ إِلَى العَقْلِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَقْلِيٌّ-عَقْلِيٌّ، ةٌ [ع ق ل] (مَنْسُوبٌ إِلَى العَقْلِ). ""نَهْجٌ عَقْلِيٌّ"" : أَيْ تَتَحَكَّمُ فِيهِ قُوَّةُ العَقْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16434, 'عِلْمِيٌّ', 'علمي', 'منسوب', 'علم', 'علمي', 'علم', 'مَنْسُوبٌ إِلَى العِلْمِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عِلْمِيٌّ-عِلْمِيٌّ، ةٌ [ع ل م ] (مَنْسُوبٌ إِلَى العِلْمِ). ""إِنْجَازٌ عِلْمِيٌّ "" : إِنْجَازٌ خَضَعَ لِقَوَاعِدِ العِلْمِ. ""أَبْحَاثٌ عِلْمِيَّةٌ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16435, 'عُمْرَانِيٌّ', 'عمراني', 'منسوب', 'عمر', 'عمراني', 'عمرن', 'مَنْسُوبٌ إِلَى الْعُمْرَانِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عُمْرَانِيٌّ-عُمْرَانِيٌّ [ع م ر] (مَنْسُوبٌ إِلَى الْعُمْرَانِ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16436, 'عَمُودِيٌّ', 'عمودي', 'منسوب', 'عمد', 'عمودي', 'عمد', 'مَنْسُوبٌ إِلَى الْعَمُودِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"عَمُودِيٌّ-عَمُودِيٌّ [ع م د] (مَنْسُوبٌ إِلَى الْعَمُودِ). ""الْخَطُّ الْعَمُودِيُّ"" : خَطٌّ رَأْسِيٌّ، أَيْ مُسْتَقِيمٌ نَازِلٌ مِنْ أَعْلَى إِلَى أَسْفَلَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16437, 'عُنْصُرِيٌّ', 'عنصري', 'منسوب', 'عنصر', 'عنصري', 'عنصر', 'مَنْسُوبٌ إِلَى الْعُنْصُرِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عُنْصُرِيٌّ-عُنْصُرِيٌّ [ع ن ص ر] (مَنْسُوبٌ إِلَى الْعُنْصُرِ). 1.""رَجُلٌ عُنْصُرِيٌّ"" : مُتَعَصِّبٌ لِجِنْسِهِ وَأَصْلِهِ. 2.""التَّمْيِيزُ الْعُنْصُرِيُّ"" : ظَاهِرَةٌ تَعْتَمِدُ التَّفْرِقَةَ بَيْنَ الأَجْنَاسِ إِمَّا بِحَسَبِ الأَصْل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16438, 'غَازِيٌّ', 'غازي', 'منسوب', '', 'غازي', 'غز', 'مَنْسُوبٌ إِلَى الغَازِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"غَازِيٌّ-غَازِيٌّ، ةٌ (مَنْسُوبٌ إِلَى الغَازِ). ""مِيَاهٌ غَازِيَّةٌ"" : مَشْرُوبٌ مُرَطِّبٌ يُتَّخَذُ مِنَ الْمَاءِ الغَازِيِّ وَالسُّكَّرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16439, 'غَدِيٌّ', 'غدي', 'منسوب', 'غدو', 'غدي', 'غد', 'مَنْسُوبٌ إِلَى الغَدِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"غَدِيٌّ-غَدِيٌّ [غ د و] (مَنْسُوبٌ إِلَى الغَدِ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16440, 'غَرْبِيٌّ،', 'غربي،', 'منسوب', 'غرب', 'غربي،', 'غرب،', 'مَنْسُوبٌ إِلَى الغَرْبِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"غَرْبِيٌّ،-غَرْبِيٌّ، ةٌ [غ ر ب] (مَنْسُوبٌ إِلَى الغَرْبِ). ""هُوَ غَرْبِيُّ الثَّقَافَةِ"" : مُتَشَبِّعٌ بِثَقَافَةِ الغَرْبِ (أُورُوبَّا). ""الفِكْرُ الغَرْبِيُّ"" ""أَفْكَارٌ غَرْبِيَّةٌ"" ""الدُّوَلُ الغَرْبِيَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16441, 'غَرِيزِيٌّ', 'غريزي', 'منسوب', 'غرز', 'غريزي', 'غرز', 'مَنْسُوبٌ إِلَى الغَرِيزَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"غَرِيزِيٌّ-غَرِيزِيٌّ، ةٌ [غ ر ز] (مَنْسُوبٌ إِلَى الغَرِيزَةِ). ""مَيْلٌ غ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16442, 'غِيَابِيٌّ', 'غيابي', 'منسوب', 'غيب', 'غيابي', 'غب', 'مَنْسُوبٌ إِلَى الْغِيَابِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"غِيَابِيٌّ-غِيَابِيٌّ، ةٌ [غ ي ب] (مَنْسُوبٌ إِلَى الْغِيَابِ). ""حُوكِمَ غِيَابِيّاً"" : أَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16443, 'فَاشِسْتِيٌّ', 'فاشستي', 'منسوب', '', 'فاشستي', 'فشست', 'مَنْسُوبٌ إِلَى الْفَاشِسْتِيّ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"فَاشِسْتِيٌّ-فَاشِسْتِيٌّ (سيا) (مَنْسُوبٌ إِلَى الْفَاشِسْتِيَّة). ""رَجُلٌ فَاشِسْتِيٌّ"" : مَنْ كَانَ عَلَى مَذْهَبِ الْفَاشِسْتِيَّةِ، أَي الْمُثِيرُ لِلْمَشَاعِرِ الْقَوْمِيَّةِ الْعَنِيفَةِ وَالْمُتَعَصِّبُ لَهَا وَالْحَاقِدُ عَلَى مَنْ لاَ يَتَعَاطَفُ مَعَهُ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16444, 'فِرْجَارِيٌّ', 'فرجاري', 'منسوب', '', 'فرجاري', 'فرجر', 'مَنْسُوبٌ إِلَى الْفِرْجَارِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"فِرْجَارِيٌّ-فِرْجَارِيٌّ (مَنْسُوبٌ إِلَى الْفِرْجَارِ). ""خَطٌّ فِرْجَارِيٌّ"" : خَطٌّ مُسْتَدِيرٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16445, 'فَرْدِيٌّ', 'فردي', 'منسوب', 'فرد', 'فردي', 'فرد', 'مَنْسُوبٌ إِلَى الْفَرْدِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"فَرْدِيٌّ-فَرْدِيٌّ، ةٌ [ف ر د] (مَنْسُوبٌ إِلَى الْفَرْدِ). 1.""عَمَلٌ فَرْدِيٌّ"" : قَامَ بِهِ فَرْدٌ وَاحِدٌ. 2.""الْعَدَدُ الْفَرْدِيُّ"" : هُوَ مَا لاَ يَقْبَلُ الْقِسْمَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16446, 'فَرْعِيٌّ', 'فرعي', 'منسوب', 'فرع', 'فرعي', 'فرع', 'مَنْسُوبٌ إِلَى الْفَرْعِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"فَرْعِيٌّ-فَرْعِيٌّ، ةٌ [ف ر ع] (مَنْسُوبٌ إِلَى الْفَرْعِ). 1.""طَرِيقٌ فَرْعِيٌّ"" : ثَانَوِيٌّ. 2.""مَسْأَلَةٌ فَرْعِيَّةٌ"" : مُسْتَنْبَطَةٌ مِنَ الْمَسْأَلَةِ الأَسَاسِيَّةِ. 3.""لَجْنَةٌ فَرْعِيَّةٌ"" : لَجْنَةٌ مُنْبَثِقَةٌ مِنَ اللَّجْنَةِ الأَسَاسِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16447, 'فَضَائِيٌّ', 'فضائي', 'منسوب', 'فضو', 'فضاءي', 'فض', 'مَنْسوبٌ إِلَى الفَضَاءِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"فَضَائِيٌّ-فَضَائِيٌّ، ةٌ [ف ض و] (مَنْسوبٌ إِلَى الفَضَاءِ). ""سَفِينَةٌ فَضَائِيَّةٌ"" : ن. فَضَاء. (سَفِينَةُ الفَضَاءِ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16448, 'فُضُولِيٌّ', 'فضولي', 'منسوب', 'فضل', 'فضولي', 'فضل', 'مَنْسُوبٌ إِلَى الْفُضُولِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْفُضُولِ). ""رَجُلٌ فُضُولِيٌّ"" : الَّذِي يَتَدَخَّلُ فِيمَا لاَ يَعْنِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16449, 'فَقَارِيٌّ', 'فقاري', 'منسوب', 'فقر', 'فقاري', 'فقر', 'مَنْسُوبٌ إِلَى الْفَقَارَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"فَقَارِيٌّ-فَقَارِيٌّ، ةٌ [ف ق ر] (مَنْسُوبٌ إِلَى الْفَقَارَةِ). ""السِّلْسِلَةُ الْفَقَارِيَّةُ"" : فَقْرِيٌّ، عِظَامُ السِّلْسِلَةِ العَظْمِيَّةِ الظَّهْرِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16450, 'فَلْسَفِيُّ', 'فلسفي', 'منسوب', 'فلسف', 'فلسفي', 'فلسف', 'مَنْسُوبٌ إِلَى الْفَلْسَفَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"فَلْسَفِيُّ-فَلْسَفِيُّ، ةٌ [ف ل س ف] (مَنْسُوبٌ إِلَى الْفَلْسَفَةِ). ""مَوْضُوعٌ فَلْس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16451, 'فَلَكِيٌّ', 'فلكي', 'منسوب', 'فلك', 'فلكي', 'فلك', 'مَنْسُوبٌ إِلَى الْفَلَكِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْفَلَكِ). : الْقَائِمُ بِعِلْمِ الْفَلَكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16452, 'فَوْضَوِيٌّ', 'فوضوي', 'منسوب', 'فوض', 'فوضوي', 'فض', 'مَنْسُوبٌ إِلَى الْفَوْضَى', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْفَوْضَى). 1.""رَجُلٌ فَوْضَوِيٌّ"" : مَنْ يُحْدِثُ الْبَلْبَلَةَ وَيُخِلُّ بِنِظَامِ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16453, 'قَارِّيٌّ', 'قاري', 'منسوب', 'قرر', 'قاري', 'قر', 'مَنْسُوبٌ إِلَى القَارَّةِ ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"قَارِّيٌّ-قَارِّيٌّ، ةٌ [ق ر ر] (مَنْسُوبٌ إِلَى القَارَّةِ) . ""مُنَاخٌ قَارِّيٌّ"" : أَيْ مُنَاخُ الْمَنَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16454, 'قَانُونِيٌّ', 'قانوني', 'منسوب', 'قنن', 'قانوني', 'قنن', 'مَنْسُوبٌ إِلَى الْقَانُونِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْقَانُونِ). 1.""رَجُلٌ قَانُونِيٌّ"" : رَجُلُ التَّشْرِيعِ وَالْمُتَشَبِّثُ بِهِ بِحَذَافِيرِهِ. 2.""عَمَلٌ قَانُونِيٌّ"" : خَاضِعٌ لِلْقَانُونِ. ""السُّلْطَةُ الْقَانُونِيَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16455, 'قِبْطِيٌّ', 'قبطي', 'منسوب', '', 'قبطي', 'قبط', 'مَنْسُوبٌ إِلَى القِبْطِ.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسُوبٌ إِلَى القِبْطِ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16456, 'قَبَلِيٌّ', 'قبلي', 'منسوب', '', 'قبلي', 'قبل', 'مَنْسُوبٌ إِلَى الْقَبِيلَةِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"قَبَلِيٌّ-قَبَلِيٌّ، ةٌ (مَنْسُوبٌ إِلَى الْقَبِيلَةِ). ""نِظَامٌ قَبَلِيٌّ"" : نِظَامٌ يَعْتَمِدُ عَلَى تَقَالِيدِ الْقَبِيلَةِ. ""عَادَاتٌ قَبَلِيَّةٌ"" ""نَزْعَةٌ قَبَلِيَّةٌ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16457, 'قَرَوِيٌّ', 'قروي', 'منسوب', 'قري', 'قروي', 'قر', 'مَنْسُوبٌ إِلَى القَرْيَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى القَرْيَةِ). ""يَرْتَبِطُ القَرَوِيُّ بِقَرْيَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16458, 'قَصَصِيٌّ', 'قصصي', 'منسوب', 'قصص', 'قصصي', 'قصص', 'مَنْسُوبٌ إِلَى القَصَصِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"قَصَصِيٌّ-قَصَصِيٌّ، ةٌ [ق ص ص] (مَنْسُوبٌ إِلَى الق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16459, 'قَضَائِيٌّ', 'قضائي', 'منسوب', 'قضي', 'قضاءي', 'قض', 'مَنْسُوبٌ إِلَى القَضَاءِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"قَضَائِيٌّ-قَضَائِيٌّ، ةٌ [ق ض ي] (مَنْسُوبٌ إِلَى القَضَاءِ). ""هَيْئَةٌ قَضَائِيَّةٌ"" : هَيْئَةٌ، سُلْطَةٌ تَفْصِلُ فِي النِّزَاعِ وَالْخُصُومَاتِ طِبْقاً لِلْقَانُونِ. ""حُكْمٌ قَضَائِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16460, 'قُطْبِيٌّ', 'قطبي', 'منسوب', 'قطب', 'قطبي', 'قطب', 'مَنْسُوبٌ إِلَى القُطْبِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"قُطْبِيٌّ-قُطْبِيٌّ، ةٌ [ق ط ب] (مَنْسُوبٌ إِلَى القُطْبِ). : نَعْتٌ لِكُلِّ ما لَهُ صِلَةٌ بِالقُطْبِ. 1.""النَّجِمُ القُطْبِيُّ"" : أَحَدُ نُجُومِ مَجْموعَةِ الدّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16461, 'قُطْنِيٌّ', 'قطني', 'منسوب', 'قطن', 'قطني', 'قطن', 'مَنْسُوبٌ إِلَى القُطْنِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"قُطْنِيٌّ-قُطْنِيٌّ، ةٌ [ق ط ن] (مَنْسُوبٌ إِلَى القُطْنِ). ""ثِيَابٌ قُطْنِيَّةٌ"" : ثِيَابٌ مَنْسُوجَةٌ مِنَ القُطْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16462, 'قَوْمِيٌّ', 'قومي', 'منسوب', 'قوم', 'قومي', 'قم', 'مَنْسُوبٌ إِلَى القَوْمِيَّةِ،', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"قَوْمِيٌّ-قَوْمِيٌّ، ةٌ [ق و م] (مَنْسُوبٌ إِلَى القَوْمِيَّةِ، مُنْتَمٍ إِلَيْهَا). 1.""فِكْرٌ قَوْمِيٌّ"" : فِكْرٌ يُمَجِّدُ القَوْمِيَّةَ وَيُدَافِعُ عَنْها. 2.""هُوَ قَوْمِيٌّ"" : مُتَشَبِّثٌ بِمَبْدَإِ القَوْمِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16463, 'قِيَاسِيٌّ', 'قياسي', 'منسوب', 'قيس', 'قياسي', 'قس', 'مَنْسُوبٌ إِلَى القِيَاسِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"قِيَاسِيٌّ-قِيَاسِيٌّ، ةٌ [ق ي س] (مَنْسُوبٌ إِلَى القِيَاسِ). 1.""حُكْمٌ قِيَاسِيٌّ"" : مَا يَكُونُ بِحَسَبِ القِيَاسِ وَالْمُمَاثَلَةِ. 2.""حَقَّقَ رَقْماً قِيَاسِيّاً"" : أَعْلَى رَقْمٍ. ""أَرْقَامٌ قِيَاسِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16464, 'كُرَوِيٌّ', 'كروي', 'منسوب', 'كور', 'كروي', 'كر', 'مَنْسُوبٌ إلى الكُرَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"كُرَوِيٌّ-كُرَوِيٌّ، ةٌ [ك و ر] (مَنْسُوبٌ إلى الكُرَةِ). ""كُرَوِيُّ الشَّكْلِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16465, 'كَسْتَنَائِيٌّ', 'كستنائي', 'منسوب', '', 'كستناءي', 'كستن', 'مَنْسُوبٌ إِلَى الكَسْتَنَاءِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"كَسْتَنَائِيٌّ-كَسْتَنَائِيٌّ، ةٌ (مَنْسُوبٌ إِلَى الكَسْتَنَاءِ). ""لَوْنٌ كَسْتَنَائِيٌّ"": أَسْمَرُ قَاتِمٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16466, 'كُلْوِيٌّ', 'كلوي', 'منسوب', 'كلي', 'كلوي', 'كل', 'مَنْسُوبٌ إِلَى الكُلْوَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"كُلْوِيٌّ-كُلْوِيٌّ، ةٌ [ك ل ي] (مَنْسُوبٌ إِلَى الكُلْوَةِ). ""اِلْتِهَابٌ كُلْوِيٌّ"" : اِلْتِهَابٌ مَصْدَرُهُ الكُلْوَةُ. ""مَغْصٌ كُلْوِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16467, 'كَمِّيٌّ', 'كمي', 'منسوب', 'كمم', 'كمي', 'كم', 'مَنْسُوبٌ إِلَى الكَمِّ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"كَمِّيٌّ-كَمِّيٌّ، ةٌ [ك م م] (مَنْسُوبٌ إِلَى الكَمِّ). ""كَمِّيَّةٌ مِنَ الفَوَاكِهِ"" : مِقْدَارٌ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16468, 'كَهْرَبَائِيٌّ', 'كهربائي', 'منسوب', 'كهرب', 'كهرباءي', 'كهرب', 'مَنْسُوبٌ إِلَى الكَهْرَبَاءِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"كَهْرَبَائِيٌّ-كَهْرَبَائِيٌّ، ةٌ [ك هـ ر ب] (مَنْسُوبٌ إِلَى الكَهْرَبَاءِ). 1.""تَيَّارٌ كَهْرَبَائِيٌّ : تَيَّارٌ تَسْرِي فِيهِ القُوَّة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16469, 'كُوفِيٌّ', 'كوفي', 'منسوب', 'كوف', 'كوفي', 'كف', 'مَنْسُوبٌ إِلَى الكُوفَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"كُوفِيٌّ-كُوفِيٌّ، ةٌ [ك و ف] (مَنْسُوبٌ إِلَى الكُوفَةِ). ""الخَطُّ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16470, 'كَوْنِيٌّ', 'كوني', 'منسوب', 'كون', 'كوني', 'كن', 'مَنْسُوبٌ إِلَى الكَوْنِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"كَوْنِيٌّ-كَوْنِيٌّ، ةٌ [ك و ن] (مَنْسُوبٌ إِلَى الكَوْنِ). ""النِّظَامُ الكَوْنِيُّ"" : النِّظَامُ الَّذِي يَسِيرُ عَلَيْهِ العَالَمُ، الكَوْنُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16471, 'كُوَيْتِيٌّ', 'كويتي', 'منسوب', '', 'كويتي', 'كت', 'مَنْسُوبٌ إِلَى الكُوَيْتِ.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسُوبٌ إِلَى الكُوَيْتِ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16472, 'كِيميَائِيٌّ', 'كيميائي', 'منسوب', '', 'كيمياءي', 'كم', 'مَنْسُوبٌ إِلَى الكِيمْيَاءِ.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسُوبٌ إِلَى الكِيمْيَاءِ). 1. : ""بَحْثٌ كِيمْيَائِيّ""، ""أَبْحَاثٌ كِيمْيَائِيَّةٌ"". 2. : العَالِمُ بِالكِيمْيَاءِ وَالْمُتَخَصِّصُ فِيهَا. ""كِيميَائِيٌّ بَارِزٌ عَلَى الْمُسْتَوَى الدَّوْلِيِّ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16473, 'لاَهُوتِيٌّ', 'لاهوتي', 'منسوب', '', 'لاهوتي', 'لهت', 'مَنْسُوبٌ إِلَى اللاَّهُوتِ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"لاَهُوتِيٌّ-لاَهُوتِيٌّ، ةٌ (مَنْسُوبٌ إِلَى اللاَّهُوتِ). : العَالِمُ بِالقَضَايَا الإِلَهِيَّةِ وَصِفَاتِ اللَّهِ تَعَالَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16474, 'لِثَوِيٌّ', 'لثوي', 'منسوب', 'لثي', 'لثوي', 'لث', 'مَنْسُوبٌ إِلَى اللِّثَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"لِثَوِيٌّ-لِثَوِيٌّ، ةٌ [ل ث ي] (مَنْسُوبٌ إِلَى اللِّثَةِ). ""اللام حَرْفٌ لِثَوِيٌّ"" : أَيْ يُنْطَقُ بِتَفَاعُلِ نُطْقِ اللِّسَانِ وَالأَسْنَانِ. الْحُرُوفُ اللِّثَوِيَّةُ هِيَ: التّاء والرّاء والزّاي والسّين والصّاد والضّاد والطّاء واللام والنّون. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16475, 'لِسَانِيُّ', 'لساني', 'منسوب', 'لسن', 'لساني', 'لسن', 'مَنْسُوبٌ إِلَى اللِّسَانِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى اللِّسَانِ). 1.""عَالِمٌ لِسَانِيٌّ"" : اللُّغَوِيُّ، العَالِمُ بِاللُّغَةِ،"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16476, 'لُغَوِيٌّ', 'لغوي', 'منسوب', 'لغو', 'لغوي', 'لغ', 'مَنْسُوبٌ إِلَى اللُّغَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"لُغَوِيٌّ-لُغَوِيٌّ، ةٌ [ل غ و] (مَنْسُوبٌ إِلَى اللُّغَةِ). 1."" لُغَوِيٌّ مِنْ أَهْلِ اللُّغَةِ"" : الْعَالِمُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16477, 'مَائِيُّ', 'مائي', 'منسوب', 'موه', 'ماءي', 'م', 'منسوب إلى الماء', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَائِيُّ-مَائِيُّ، ةٌ [م و هـ] (منسوب إلى الماء). 1.""حَيَوَانٌ مَائِيٌّ"" : أَيْ يَعِيشُ فِي َالْمَاءِ، ""أَلْعَابٌ رِيَاضِيَّةٌ مَائِيَّةٌ"" : أَلْعَابٌ تَتِمُّ وَسَطَ الْمَاءِ. 2.""لَوْحَةٌ فَنِّيَّةٌ مَائِيَّةٌ"" : أَيْ لَوْحَةٌ رُسِمَتْ بِصِبَاغَةٍ مُخْتَلِطَةٍ بِالْمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16478, 'مَادِّيُّ', 'مادي', 'منسوب', 'مدد', 'مادي', 'مد', 'مَنْسُوبٌ إِلَى الْمَادَّةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْمَادَّةِ). 1.""رَجُلُ مَادِّيٌّ"" : رَجُلٌ مُتَشَبِّعٌ بِمَا هُوَ مَلْمُوسٌ وَمَحْسُوبٌ. 2.""فِكْرٌ مَادِّيٌّ"" : الفِكْرُ القَائِلُ بِأَنَّ الْمَادَّةَ وَحْدَهَا هِيَ أَسَاسُ الوُجُودِ. ""هُوَ مَادِّيُّ الفِكْرِ"". 3.""أَشْيَاءُ مَادِّيَّةٌ"" : مَلْمُوسَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16479, 'مَأْسَاوِيٌّ', 'مأساوي', 'منسوب', 'أسي', 'مءساوي', 'مس', 'مَنْسُوبٌ إِلَى الْمَأْسَاةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَأْسَاوِيٌّ-مَأْسَاوِيٌّ، ةٌ [أ س ي] (مَنْسُوبٌ إِلَى الْمَأْسَاةِ). ""حَادِثٌ مَأْسَاوِيٌّ"" : ذُو فَاجِعَةٍ وَكَارِثَةٍ. ""عَرَفَتْ حَياتُهُ حَوادِثَ مَأسَاوِيَّةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16480, 'مَالِيٌّ', 'مالي', 'منسوب', 'مول', 'مالي', 'مل', 'مَنْسُوبٌ إِلَى الْمَالِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَالِيٌّ-مَالِيٌّ، ةٌ [م و ل] (مَنْسُوبٌ إِلَى الْمَالِ). 1.""تَوَصَّلَ بِقَدْرٍ مَالِيٍّ"" : بِقَدْرٍ مِنَ الْمَالِ. ""مَوَارِدُهُ الْمَالِيَّةُ لاَ تَسْمَحُ بِكُلِّ هَذِهِ الْمَصَارِيفِ"". 2.""مَالِيَّةُ الدَّوْلَةِ"" : مَصَارِيفُهَا وَمَدَاخِيلُهَا. 3.""وِزَارَةُ الْمَالِيَّةِ"" : الوِزَارَةُ الَّتِي تُشْرِفُ عَلَى تَسْيِيرِ مِيزَانِيَّةِ الدَّوْلَةِ، مَصَارِيفِهَا وَمَدَاخِيلِهَا وَتَصْرِيفِ مَعَاشِ العَامِلِينَ وَالْمُوَظَّفِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16481, 'مَبْدَئِيٌّ', 'مبدئي', 'منسوب', '', 'مبدءي', 'مبد', 'منسوبٌ إلى المبدأ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16482, 'مِثَالِيٌّ', 'مثالي', 'منسوب', 'مثل', 'مثالي', 'مثل', 'مَنْسُوبٌ إِلَى المِثَالِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مِثَالِيٌّ-مِثَالِيٌّ، ةٌ [م ث ل] (مَنْسُوبٌ إِلَى المِثَالِ). 1.""مِثَالِيٌّ فِي سُلُوكِهِ"" : نَمُوذَجِيٌّ. 2.""وَلَدٌ مِثَالِيٌّ"" : يُقْتَدَى بِهِ. ""خُلُقٌ مِثَالِيٌّ"" ""فِكْر مِثَالِيٌّ"" ""صُورَةٌ مِثَالِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16483, 'مَجَازِيٌّ', 'مجازي', 'منسوب', 'جوز', 'مجازي', 'مجز', 'مَنْسُوبٌ إِلَى الْمَجازِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَجَازِيٌّ-مَجَازِيٌّ [ج و ز] (مَنْسُوبٌ إِلَى الْمَجازِ). ""الْمَعْنَى الْمَجَازِيُّ"" : الْمَعْنَى الْمُسْتَعْمَلُ فِي غَيْرِ مَا وُضِعَ لَهُ أَصْلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16484, 'مِجْهَرِيُّ', 'مجهري', 'منسوب', 'جهر', 'مجهري', 'مجهر', 'مَنْسُوبٌ إِلَى الْمِجْهَرِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مِجْهَرِيُّ-مِجْهَرِيُّ، ةٌ [ج هـ ر] (مَنْسُوبٌ إِلَى الْمِجْهَرِ). ""فَحْصٌ مِجْهَرِيٌّ"" : فَحْصٌ يَتِمُّ بِوَاسِطَةِ المِجْهَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16485, 'مَحَلِّيٌّ', 'محلي', 'منسوب', 'حلل', 'محلي', 'محل', 'مَنْسُوبٌ إِلَى الْمَحَلِّ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مَحَلِّيٌّ-مَحَلِّيٌّ، ةٌ [ح ل ل] (مَنْسُوبٌ إِلَى الْمَحَلِّ). 1.""إِدَارَةٌ مَحَلِّيَّةٌ"" : إِدَارَةٌ مُخْتَصَّةٌ بِمِنْطَقَتِهَا أَوْ إِقْلِيمِهَا، عَكْس الْمَرْكَزِيَّةِ. 2.""إِنْتَاجٌ مَحَلِّيٌّ"" : تَمَّ إِنْتَاجُهُ فِي المِنْطَقَةِ ذَاتِهَا. ""سُوقٌ مَحَلِّيٌّ"" ""شُؤُونٌ مَحَلِّيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16486, 'مِحْوَرِيٌّ', 'محوري', 'منسوب', 'حور', 'محوري', 'محر', 'مَنْسُوبٌ إِلَى المِحْوَرِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مِحْوَرِيٌّ-مِحْوَرِيٌّ، ةٌ [ح و ر] (مَنْسُوبٌ إِلَى المِحْوَرِ). 1.""جِهَازٌ مِحْوَرِيٌّ"" : جِهَازٌ مَرْكَزِيٌّ تَرْتَبِطُ بِهِ الأَجْهِزَةُ الأُخْرَى. 2.""شَخْصِيَّةٌ مِحْوَرِيَّةٌ"" : رَئِسَةٌ أَورَئِيسِيَّةٌ، مَرْكَزِيَّةٌ. ""شَخْصِيَّةٌ مِحْوَرِيَّةٌ فِي الرِّوَايَةِ"" ""قَضِيَّةٌ مِحْوَرِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16487, 'مُخْمَلِيٌّ', 'مخملي', 'منسوب', 'خمل', 'مخملي', 'مخمل', 'مَنْسُوبٌ إِلَى الْمُخْمَلِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مُخْمَلِيٌّ-مُخْمَلِيٌّ، ةٌ [خ م ل] (مَنْسُوبٌ إِلَى الْمُخْمَلِ). ""ثَوْبٌ مُخْمَلِيٌّ"" : ثَوْبٌ مِنْ نَسِيجٍ لَهُ خَمْلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16488, 'مَدَارِيٌّ', 'مداري', 'منسوب', 'دور', 'مداري', 'مدر', 'مَنْسُوبٌ إِلَى الْمَدَارِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَدَارِيٌّ-مَدَارِيٌّ [د و ر] (مَنْسُوبٌ إِلَى الْمَدَارِ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16489, 'مَدْرَسِيٌّ', 'مدرسي', 'منسوب', 'درس', 'مدرسي', 'مدرس', 'مَنْسُوبٌ إِلَى الْمَدْرَسَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَدْرَسِيٌّ-مَدْرَسِيٌّ، ةٌ [د ر س] (مَنْسُوبٌ إِلَى الْمَدْرَسَةِ). ""كِتَابٌ مَدْرَسِيٌّ"" : كِتَابٌ مِنْ مُقَرَّرَات البَرامِجِ الَّتِي تُدَرَّسُ فِي الْمَدْرَسَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16490, 'مِدْفَعِيٌّ', 'مدفعي', 'منسوب', 'دفع', 'مدفعي', 'مدفع', 'مَنْسُوبٌ إِلَى المِدْفَعِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مِدْفَعِيٌّ-مِدْفَعِيٌّ، ةٌ [د ف ع] (مَنْسُوبٌ إِلَى المِدْفَعِ). ""عَسْكَرِيٌّ مِدْفَعِيٌّ"" : مُخْتَصٌّ بِسِلاَحِ الْمَدَافِعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16491, 'مَدَنِيٌّ', 'مدني', 'منسوب', 'مدن', 'مدني', 'مدن', 'مَنْسُوبٌ إِلَى الْمَدِينَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْمَدِينَةِ) .1.""رَجُلٌ مَدَنِيٌّ"" : مِنْ أَهْلِ الْمَدِينَةِ. ""السُّكَّانُ الْمَدَنِيُّونَ"" وَالكَلِمَةُ عَكْسُ العَسْكَرِيّ أَيْضاً : ""يَرْتَدِي العَسْكَرِيُّ مَلاَبِسَهُ الْمَدَنِيَّةَ أَيَّامَ العُطَلِ"" ""الْحَيَاةُ الْمَدَنِيَّةُ"" ""الطَّيَرَانُ الْمَدَنِيُّ"". 2.""أَدَّى الْخِدْمَةَ الْمَدَنِيَّةَ"" : الوَاجِبُ الَّذِي يُؤَدِّيهِ العَامِلُ أَوِ الْمُوَظَّفُ خِلاَلَ فَتْرَةٍ مُعَيَّنَةٍ قَبْلَ تَعْيِينِهِ فِي وَظِيفَتِهِ. 3.""الْمَدَنِيَّةُ الْحَدِيثَةُ"" : الْحَضَارَةُ وَالْعُمْرَانُ وَكُلُّ الْمُخْتَرَعَاتِ التِّكْنُولُوجِيَّةِ. 4.""الْمُجْتَمَعُ الْمَدَنِيُّ"" : أَي الْمُجْتَمَعُ الَّذِي تَكَوَّنَتْ مُؤَسَّسَاتُهُ وَجَمْعِيَّاتُهُ الْحَضَرِيَّةُ. 5.""زَوَاجٌ مَدَنِيٌّ"" : أَيْ زَوَاجٌ تَتَحَكَّمُ فِيهِ القَوَانِينُ العَصْرِيَّةُ، عَكْس الزَّوَاجِ الدِّينِيِّ. 6.""القَانُونُ الْمَدَنِيُّ"" : قَانُونُ الأَحْوَالِ الْخَاضِعَةِ لِتَطَوُّرِ حَيَاةِ الْمُجْتَمَعِ الْعَصْرِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16492, 'مَدِينِيٌّ', 'مديني', 'منسوب', 'مدن', 'مديني', 'مدن', 'مَنْسُوبٌ إِلَى الْمَدِينَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَدِينِيٌّ-مَدِينِيٌّ، ةٌ [م د ن] (مَنْسُوبٌ إِلَى الْمَدِينَةِ). ""رَجُلٌ مَدينِيٌّ"": مِنَ الْمَدينَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16493, 'مَرَضِيٌّ،', 'مرضي،', 'منسوب', 'مرض', 'مرضي،', 'مرض،', 'مَنْسُوبٌ إِلَى الْمَرَضِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَرَضِيٌّ،-مَرَضِيٌّ، ةٌ [م ر ض] (مَنْسُوبٌ إِلَى الْمَرَضِ). ""أُصِيبَ بِحَالَةٍ مَرَضِيَّةٍ"" : أَيْ بِحَالَةٍ بِهَا مَرَضٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16494, 'مَرْكَزِيٌّ', 'مركزي', 'منسوب', 'ركز', 'مركزي', 'مركز', 'مَنْسُوبٌ إِلَى الْمَرْكَزِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَرْكَزِيٌّ-مَرْكَزِيٌّ، ةٌ [ر ك ز] (مَنْسُوبٌ إِلَى الْمَرْكَزِ). 1. ""الجِهَازُ الْمَرْكَزِيُّ"" : الجِهَازُ الأَسَاسِيُّ، مِنْهُ تَصْدُرُ كُلُّ التَّعْلِيمَاتِ وَالإِشَارَاتِ. 2.""السُّلْطَةُ الْمَرْكَزِيَّةُ"" : سُلْطَةٌ تَحْصِرُ كُلَّ القَرَارَاتِ وَالأَحْكَامِ بَيْنَ يَدَيْهَا مَعَ إِخْضَاعِ كُلِّ السُّلَطِ تَحْتَ نُفُوذِهَا. 3.""اللَّجْنَةُ الْمَرْكَزِيَّةُ لِلْحِزْبِ"" : اللَّجْنَةُ العُلْيَا الَّتِي تُقَرِّرُ سِياسَةَ الحِزْبِ وتُصْدِرُ قَرَارَاتٍ تَوْجِيهِيَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16495, 'مُسْتَقْبَلِيٌّ', 'مستقبلي', 'منسوب', 'قبل', 'مستقبلي', 'مستقبل', 'مَنْسُوبٌ إِلَى الْمُسْتَقْبَل', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْمُسْتَقْبَلِ). ""بَاحِثٌ مُسْتَقْبَلِيٌّ"" : مُهْتَمٌّ بِدِرَاسَةِ مَا سَيَكُونُ عَلَيْهِ عَالَمُ الغَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16496, 'مَسِيحِيٌّ', 'مسيحي', 'منسوب', 'مسح', 'مسيحي', 'مسح', 'مَنْسُوبٌ إِلَى الْمَسِيحِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". مَنْسُوبٌ إِلَى الْمَسِيحِ، التَّابعُ لِدِينِهِ وَتَعَالِيمِهِ. ""الإِنْجِيلُ كِتَابُ الدِّينِ الْمَسِيحِيِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16497, 'مَشْرِقِيٌّ', 'مشرقي', 'منسوب', 'شرق', 'مشرقي', 'مشرق', 'مَنْسُوبٌ إِلَى الْمَشْرِق', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":مَشَارِقَةٌ"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْمَشْرِق)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16498, 'مَشَارِقَةٌ', 'مشارقة', 'منسوب', '', 'مشارقة', 'مشرقة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16499, 'مَصْرِفِيٌّ', 'مصرفي', 'منسوب', 'صرف', 'مصرفي', 'مصرف', 'مَنْسُوبٌ إِلَى الْمَصْرِفِ، م', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْمَصْرِفِ، مَالَهُ عَلاَقَةٌ بِالْمَصْرِفِ). 1.""مَصْرِفِيٌّ نَاجِحٌ "" : الْمُشْتَغِلُ بِالْمَصْرِفِ وَقَضَايَاهُ. 2. ""شِيكٌ مَصْرِفِيٌّ"" : شِيكٌ يُتَعَامَلُ بِهِ بِوَاسِطَةِ الْمَصْرِفِ. ""قُرُوضٌ مَصْرِفِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16500, 'مِظَلِّيٌّ', 'مظلي', 'منسوب', 'ظلل', 'مظلي', 'مظل', 'مَنْسُوبٌ إِلَى المِظَلَّةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى المِظَلَّةِ). ""نَزَلَ المِظَلِّيُّ بِسَلاَمٍ"" : مَنْ يَهْبِطُ مِنَ الفَضَاءِ بَعْدَمَا تَقْذِفُهُ الطَّائِرَةُ بِالْمِظَلَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16501, 'مُعْجَمِيٌّ', 'معجمي', 'منسوب', 'عجم', 'معجمي', 'معجم', 'مَنْسُوبٌ إِلَى الْمُعْجَمِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْمُعْجَمِ). 1.: مُهْتَمٌّ بِمُفْرَدَاتِ الْمُعْجَمِ. 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16502, 'مَعْدِنِيٌّ', 'معدني', 'منسوب', 'عدن', 'معدني', 'معدن', 'مَنْسُوبٌ إِلَى الْمَعْدِنِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَعْدِنِيٌّ-مَعْدِنِيٌّ، ةٌ [ع د ن] (مَنْسُوبٌ إِلَى الْمَعْدِنِ). ""مَاءٌ مَعْدِنِيٌّ"" : مَاءٌ مُشْبَعٌ بِالأَمْلاَحِ. ""مِيَاهٌ مَعْدِنِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16503, 'مِعْمَارِيٌّ', 'معماري', 'منسوب', 'عمر', 'معماري', 'معمر', 'مَنْسُوبٌ إِلَى المِعْمَارِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى المِعْمَارِ). 1.""مُهَنْدِسٌ مِعْمَارِيٌّ"" : يُمَارِسُ مِهْنَةَ العِمَارَةِ. 2.""هَنْدَسَةٌ مِعْمَارِيَّةٌ"" : هَنْدَسَةٌ مُخْتَصَّةٌ بِوَضْعِ التَّصَامِيمِ لِتَشْيِيدِ العِمَارَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16504, 'مَعْنَوِيٌّ', 'معنوي', 'منسوب', 'عني', 'معنوي', 'معن', 'مَنْسُوبٌ إِلَى الْمَعْنَى', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَعْنَوِيٌّ-مَعْنَوِيٌّ، ةٌ [ع ن ي] (مَنْسُوبٌ إِلَى الْمَعْنَى). 1.""تَقْدِيرٌ مَعْنَوِيٌّ"" : أَيْ تَقْدِيرٌ فِكْرِيٌّ وذِهْنِيٌّ عَكْسُ التَّقْدِيرِ الْمَادِيِّ. ""مُسَانَدَةٌ مَعْنَوِيَّةٌ"". 2.""رَفَعَ مَعْنَوِيَّتَهُ"" : رَفَعَ مِنْ قِيمَةِ حَالَتِهِ النَّفْسِيَّةِ عِنْدَهُ. ""يَهْتَمُّ بِالْمَعْنَوِيَّاتِ أَكْثَرَ مِمَّا يَهْتَمُّ بِالْمَادِّيَّاتِ"". 3. ""الرُّوحُ الْمَعْنَوِيَّةُ"" : الرُّوحُ الخِلْقِيَّة. ""مَعْنَوِيّاً"". 4.""شَخْصٌ مَعْنَوِيٌّ، شَخْصِيَّةٌ مَعْنَوِيَّةٌ"" : أَيْ شَخْصِيَّةٌ اِعْتِبَارِيَّةٌ عَكْسَ الفَرْدَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16505, 'مِغْنَاطِيسِيٌّ', 'مغناطيسي', 'منسوب', '', 'مغناطيسي', 'مغنطس', 'مَنْسُوبٌ إِلَى الْمِغْنَاطِيس', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مِغْنَاطِيسِيٌّ-مِغْنَاطِيسِيٌّ (مَنْسُوبٌ إِلَى الْمِغْنَاطِيس). 1.""الْمجَالُ الْمِغْنَاطِيسِيُّ"" : هِيَ الْمِنْطَقَةُ الْمحُيِطَةُ بِالْمِغْنَاطِيسِ. 2.""الإِبْرَةُ الْمَغْنَاطِيسِيَّةُ"" : قَضِيبٌ مُمَغْنَطٌ مِنَ الفُولاَذِ يُشِيرُ نَحْوَ الشَّمَالِ والجَنُوبِ إِذَا تُرِكَ طَلِيقاً. 3. ""الشَّرِيطُ الْمَغْنَاطِيسِيُّ"" : شَرِيطٌ تُسَجَّلُ عَلَيْهِ الأَصْوَاتُ بِوَاسِطَةِ أَجْهِزَةِ التَّسْجِيلِ الصَّوْتِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16506, 'مَكُّوكِيٌّ', 'مكوكي', 'منسوب', 'مكك', 'مكوكي', 'مكك', 'مَنْسُوبٌ إِلَى الْمَكُّوكِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَكُّوكِيٌّ-مَكُّوكِيٌّ [م ك ك] (مَنْسُوبٌ إِلَى الْمَكُّوكِ). ""قِطَارٌ مَكُّوكِيٌّ"" : قِطَارٌ يَقُومُ بِرِحْلاَتٍ مُكَرَّرَةٍ مِنْ مَوْقِعٍ وَاحِدٍ أو أَكْثَرَ إِلَى مَوْقِعٍ آخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16507, 'مَلَكِيٌّ', 'ملكي', 'منسوب', 'ملك', 'ملكي', 'ملك', 'مَنْسُوبٌ إِلَى الْمَلِكِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْمَلِكِ). 1.""النِّظَامُ الْمَلَكِيُّ"" : نِظَامٌ خَاضِعٌ لِسُلْطَةِ الْمَلِكِ وحُكْمِهِ. 2.""القَصْرُ الْمَلَكِيُّ"" : قَصْرُ الْمَلِكِ. 3.""مِنَ الأَسْرَةِ الْمَلَكِيَّةِ"" : مِنْ أَعْضَاءِ أُسْرَةِ الْمَلِكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16508, 'مَنْزِلِيٌّ', 'منزلي', 'منسوب', 'نزل', 'منزلي', 'منزل', 'مَنْسُوبٌ إِلَى الْمَنْزِلِ.', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَنْزِلِيٌّ-مَنْزِلِيٌّ، ةٌ [ن ز ل]. مَنْسُوبٌ إِلَى الْمَنْزِلِ. 1.""أَدَوَاتٌ مَنْزِلِيَّةٌ"" : الأَدَوَاتُ الَّتِي تُسْتَخْدَمُ فِي الْمَنْزِلِ. 2.""فُنُونٌ مَنْزِلِيَّةٌ"": كُلُّ مَا يَتَعَلَّقُ بِتَزْيِينِ الْمَنْزِلِ وَتَأْثِيثِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16509, 'مَنْطِقِيٌّ', 'منطقي', 'منسوب', 'نطق', 'منطقي', 'منطق', 'مَنْسُوبٌ إِلَى الْمَنْطِقِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":مَنَاطِقَةٌ"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْمَنْطِقِ). 1.""عَالِمٌ مَنْطِقِيٌّ"" : صَاحِبُ عِلْمِ الْمَنْطِقِ. ""هَذَا رَأْيُ الْمَنَاطِقَةِ"". 2.""أَتَى بِأَفْكَارٍ وَآرَاءٍ مَنْطِقِيَّةٍ"" : مَعْقُولَةٌ، تَعْتَمِدُ عَلَى العَقْلِ، أَيْ تَنْتَقِلُ مِنْ مُقَدِّمَاتٍ إِلَى نَتَائِجَ صَحِيحَةٍ. 3.""كَلاَمٌ مَنْطِقِيٌّ"" : مَعْقُولٌ، مَقْبُولٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16510, 'مَنَاطِقَةٌ', 'مناطقة', 'منسوب', '', 'مناطقة', 'منطقة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16511, 'مَنْهَجِيٌّ', 'منهجي', 'منسوب', 'نهج', 'منهجي', 'منهج', 'مَنْسُوبٌ إِلَى الْمَنْهَجِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْمَنْهَجِ). 1.""رَجُلٌ مَنْهَجِيٌّ فِي عَمَلِهِ"": أَيْ صَاحِبُ مَنْهَجٍ. 2.""دَرْسٌ مَنْهَجِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16512, 'مَوْسِمِيٌّ', 'موسمي', 'منسوب', 'وسم', 'موسمي', 'مسم', 'مَنْسُوبٌ إِلَى الْمَوْسِمِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْمَوْسِمِ). 1.""عَامِلٌ مَوْسِمِيُّ"" : عَامِلٌ يَشْتَغِلُ فِي فَصْلٍ مِنْ فُصُولِ السَّنَةِ. 2.""رِيَاحٌ مَوْسِمِيَّةٌ"" : رِيَاحٌ تَهُبُّ فِي فَتَرَاتٍ مُعَيَّنَةٍ مِنَ السَّنَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16513, 'مَوْسُوعِيٌّ', 'موسوعي', 'منسوب', 'وسع', 'موسوعي', 'مسع', 'مَنْسُوبٌ إِلَى الْمَوْسُوعَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَوْسُوعِيٌّ-مَوْسُوعِيٌّ، ةٌ [و س ع] (مَنْسُوبٌ إِلَى الْمَوْسُوعَةِ). 1.""عَالِمٌ مَوْسُوعِيٌّ"" : عَالِمٌ ذُو مَعَارِفَ وَاسِعَةٍ. 2.""مُؤَلِّفٌ مَوْسُوعِيٌّ"" : مُخْتَصٌّ بِكِتَابَةِ الْمَوْسُوعَاتِ. 3.""مَعْلُومَاتٌ مَوْسُوعِيَّةٌ"" : أَيْ مَعْلُومَاتٌ ذَاتُ صِبْغَةٍ مَعْرِفِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16514, 'مُوسِيقِيٌّ', 'موسيقي', 'منسوب', '', 'موسيقي', 'مسق', 'مَنْسُوبٌ إِلَى الْمُوسِيقَى. ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسُوبٌ إِلَى الْمُوسِيقَى). 1.""مُوسِيقِيٌّ بَارِعٌ"" : مَنْ يَتَعَاطَى الْمُوسِيقَى ويَحْتَرِفُهَا. 2.""جَوْقَةٌ مُوسِيقِيَّةٌ"" : أَيْ جَوْقَةٌ تَعْزِفُ ألْحَاناً مُوسِيقِيَّةً. ""قِطْعَةٌ مُوسِيقِيَّةٌ"" ""آلَةٌ مُوسِيقِيَّةٌ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16515, 'مَوْضُوعِيٌّ', 'موضوعي', 'منسوب', 'وضع', 'موضوعي', 'مضع', 'مَنْسُوبٌ إِلَى الْمَوْضُوعِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْمَوْضُوعِ). ""حُكْمٌ مَوْضُوعِيٌّ"" : أَيْ حُكْمٌ يَحْتَكِمُ إِلَى العَقْلِ والْحَقِيقَةِ بَعِيداً عَنْ كُلِّ مَا هُوَ ذَاتِيٌّ. ""رَجُلٌ مَوْضُوعِيٌّ فِي أَحْكَامِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16516, 'مَوْلَوِيٌّ', 'مولوي', 'منسوب', 'ولي', 'مولوي', 'مل', 'مَنْسُوبٌ إِلَى الْمَوْلَى', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَوْلَوِيٌّ-مَوْلَوِيٌّ [و ل ي] (مَنْسُوبٌ إِلَى الْمَوْلَى). ""رَجُلٌ مَوْلَوِيٌّ"" : زَاهِدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16517, 'مِئَوِيٌّ', 'مئوي', 'منسوب', 'مأي', 'مءوي', 'م', 'مَنْسُوبٌ إِلَى الْمِئَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مِئَوِيٌّ-مِئَوِيٌّ، ةٌ [م أ ي] (مَنْسُوبٌ إِلَى الْمِئَةِ). 1.""اِحْتَفَلَ بِعِيدِهِ المِئَوِيِّ"" : أَيْ بِمُرُورِ مِئَةِ سَنَةٍ عَلَى مِيلاَدِهِ. ""الذِّكْرَى المِئَوِيَّةُ"". 2.""خَصَمَ لَهُ نِسْبَةً مِئَوِيَّة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16518, 'نَارِيٌّ', 'ناري', 'منسوب', 'نور', 'ناري', 'نر', 'مَنْسُوبٌ إِلَى النَّارِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نَارِيٌّ-نَارِيٌّ، ةٌ [ن و ر] (مَنْسُوبٌ إِلَى النَّارِ). 1.""سِلاَحٌ نَارِيٌّ"" : سِلاَحٌ يَقْذ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16519, 'نَبَاتِيٌّ', 'نباتي', 'منسوب', 'نبت', 'نباتي', 'نبت', 'مَنْسُوبٌ إِلَى النَّبَاتِ.', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"نَبَاتِيٌّ-نَبَاتِيٌّ، ةٌ [ن ب ت]. ""مَنْسُوبٌ إِلَى النَّبَاتِ"". 1.""عَالِمٌ نَبَاتِيٌّ"" : العَارِفُ بِفَصَائِلِ النَّبَاتِ وَطَبَائِعِهِ. 2.""رَجُلٌ نَبَاتِيٌّ"" : الَّذِي لاَ يَأْكُلُ إِلاَّ مَا تُنْبِتُهُ الأَرْضُ مِنْ نَبَاتَاتِ الْخُضَرِ وَالفَوَاكِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16520, 'نَبَطِيٌّ', 'نبطي', 'منسوب', 'نبط', 'نبطي', 'نبط', 'مَنْسُوبٌ إِلَى النَّبَطِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى النَّبَطِ). ""مَازَالَتْ آثَارُ النَّبَطِيِّينَ قَائِمَةً تَشْهَدُ عَلَى حَضَارَتِهِمْ"" : أَيِ الأَنْبَاطُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16521, 'نَبَوِيٌّ', 'نبوي', 'منسوب', 'نبأ', 'نبوي', 'نب', 'مَنْسُوبٌ إِلَى النَّبِيِّ ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نَبَوِيٌّ-نَبَوِيٌّ، ةٌ [ن ب أ]. ""مَنْسُوبٌ إِلَى النَّبِيِّ"" . ""الْحَدِيثُ النَّبَوِيُّ"" : الْحَدِيثُ الصَّادِرُ عَنِ النَّبِيِّ. ""الأَحَادِيثُ النَّبَوِيَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16522, 'نُحَاسِيٌّ', 'نحاسي', 'منسوب', 'نحس', 'نحاسي', 'نحس', 'مَنْسُوبٌ إِلَى النُّحَاسِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نُحَاسِيٌّ-نُحَاسِيٌّ، ةٌ [ن ح س] (مَنْسُوبٌ إِلَى النُّحَاسِ). ""مَعْدِنٌ نُحَاسِيٌّ"" : مَعْدِنٌ مِنَ النُّحَاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16523, 'نَحْوِيٌّ', 'نحوي', 'منسوب', 'نحو', 'نحوي', 'نح', 'مَنْسُوبٌ إِلَى النَّحْوِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":نُحَاةٌ"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى النَّحْوِ). ""عَالِمٌ نَحْوِيٌّ"" : العَالِمُ بِقَوَاعِدِ النَّحْوِ (قَوَاعِدُ اللُّغَةِ). ""نُحَاةُ البَصْرَةِ وَالكُوفَةِ"" ""قَاعِدَةٌ نَحْوِيَّةٌ"" ‏ ""اِرْتَكَبَ غَلْطَةً نَحْوِيَّةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16524, 'نُحَاةٌ', 'نحاة', 'منسوب', '', 'نحاة', 'نحة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16525, 'نِسَائِيٌّ', 'نسائي', 'منسوب', 'نسو', 'نساءي', 'نس', 'مَنْسُوبٌ إِلَى النِّسَاءِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نِسَائِيٌّ-نِسَائِيٌّ، ةٌ [ن س و] (مَنْسُوبٌ إِلَى النِّسَاءِ). ""حَرَكَةٌ نِسَائِيَّةٌ"" : حَرَكَةٌ تَهْتَمُّ بِقَضَايَا النِّسَاءِ، وَحُقُوقِهِنَّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16526, 'نِسْوِيٌّ', 'نسوي', 'منسوب', 'نسو', 'نسوي', 'نس', 'مَنْسُوبٌ إِلَى النِّسْوَةِ، ن', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نِسْوِيٌّ-نِسْوِيٌّ، ةٌ [ن س و] (مَنْسُوبٌ إِلَى النِّسْوَةِ، نِسَائِيٌّ). 1.""أَشْغَالٌ نِسْوِيَّةٌ"" : أَشْغَالٌ مَحْصُورَةٌ فِي النِّسَاءِ. 2.""حَرَكَةٌ نِسْوِيَّةٌ"" : حَرَكَةٌ مُهْتَمَّةٌ بِقَضَايَا النِّسَاءِ وَشُؤُونِهِنَّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16527, 'نَشَوِيٌّ', 'نشوي', 'منسوب', 'نشو', 'نشوي', 'نش', 'مَنْسُوبٌ إِلَى النَّشَاءِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نَشَوِيٌّ-نَشَوِيٌّ، ةٌ [ن ش و] (مَنْسُوبٌ إِلَى النَّشَاءِ). ""مَوَادُّ نَشَوِيَّةٌ"" : الْمَوَادُّ الغَنِيَّةُ بِالنَّشَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16528, 'نِطْعِيٌّ', 'نطعي', 'منسوب', 'نطع', 'نطعي', 'نطع', 'مَنْسُوبٌ إِلَى النِّطْعِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نِطْعِيٌّ-نِطْعِيٌّ، ةٌ [ن ط ع] (مَنْسُوبٌ إِلَى النِّطْعِ). ""الْحُرُوفُ النِّطْعِيَّةُ"" : هِيَ الدَّالُ وَالطَّاءُ وَالتَّاءُ لأَنَّ مَخْرَجَهَا مِنَ النِّطْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16529, 'نِظَامِيٌّ', 'نظامي', 'منسوب', 'نظم', 'نظامي', 'نظم', 'مَنْسُوبٌ إِلَى النِّظَامِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"نِظَامِيٌّ-نِظَامِيٌّ، ةٌ [ن ظ م] (مَنْسُوبٌ إِلَى النِّظَامِ). ""الْجَيْشُ النِّظَامِيُّ"" : الْجَيْشُ الرَّسْمِيُّ الْمُتَدَرِّبُ عَلَى الْمَعَارِكِ الْحَرْبِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16530, 'نَظَرِيٌّ', 'نظري', 'منسوب', 'نظر', 'نظري', 'نظر', 'مَنْسُوبٌ إِلَى النَّظَرِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"نَظَرِيٌّ-نَظَرِيٌّ، ةٌ [ن ظ ر] (مَنْسُوبٌ إِلَى النَّظَرِ). 1.""بَحْثٌ نَظَرِيٌّ"" : بَحْثٌ قَائِمٌ عَلَى إِعْمَالِ الفِكْرِ وَالتَّأَمُّلِ. ""دِرَاسَةٌ نَظَرِيَّةٌ"". 2.""نَظَرِيّاً"" : اِفْتِرَاضِيّاً. ""مِنَ الوِجْهَةِ النَّظَرِيَّةِ"". 3.""العُلُومُ النَّظَرِيَّةُ"" : العُلُومُ القَائِمَةُ عَلَى الْجَانِبِ الفِكْرِيِّ وَالَّتِي لاَ تَعْتَمِدُ عَلَى التَّجَارِبِ العَمَلِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16531, 'نَفْسِيٌّ', 'نفسي', 'منسوب', 'نفس', 'نفسي', 'نفس', 'مَنْسُوبٌ إلَى النَّفْسِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مَنْسُوبٌ إلَى النَّفْسِ). 1. ""طَبِيبٌ نَفْسَانِيٌّ"" : الطَّبِيبُ الْمُخْتَصُّ بِمُداوَاةِ النَّفْسِ. ""خَضَعَ لِتَحْلِيلٍ نَفْسَانِيٍّ"". 2.""الطِّبُّ النَّفْسِيُّ"" : الطِّبُّ الْمُهْتَمُّ بِرَغَبَاتِ الْإِنْسَانِ وَأَحَاسِيسِهِ وَانْفِعَالاَتِهِ وَبِالْحَالاَتِ الْمَرَضِيَّةِ الْمُتَعَلِّقَةِ بِالنَّفْسِ وَاضْطِرَابَاتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16532, 'نَفْسَانِيٌّ', 'نفساني', 'منسوب', '', 'نفساني', 'نفسن', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16533, 'نَفْعِيٌّ', 'نفعي', 'منسوب', 'نفع', 'نفعي', 'نفع', 'مَنْسُوبٌ إِلَى النَّفْعِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى النَّفْعِ). 1. ""رَجُلٌ نَفْعِيٌّ"" : أَيْ لاَ يَهْتَمُّ إِلاَّبِمَا فِيهِ نَفْعٌ، مَنْ كَانَ عَلَى مَذْهَبِ النَّفْعِيَّةِ. 2. ""مَوْقِفٌ نَفْعِيٌّ"" : مَوْقِفٌ قَائِمٌ عَلَى مَا فِيهِ النَّفْعُ الْمُجَرَّدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16534, 'نِقَابِيٌّ', 'نقابي', 'منسوب', 'نقب', 'نقابي', 'نقب', 'مَنْسُوبٌ إِلَى النِّقَابَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى النِّقَابَةِ). 1.""اِجْتَمَعَ النِّقَابِيُّونَ لِتَدَارُسِ أَوْضَاعِ الْعُمَّالِ وَمَطَالِبِهِمْ"" : الْمُنْتَمُونَ للِنِّقَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16535, 'نَقْدِيٌّ', 'نقدي', 'منسوب', 'نقد', 'نقدي', 'نقد', 'مَنْسُوبٌ إِلَى النَّقْدِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نَقْدِيٌّ-نَقْدِيٌّ، ةٌ [ن ق د] (مَنْسُوبٌ إِلَى النَّقْدِ). 1.""أَوْرَاقٌ نَقْدِيَّةٌ"" : أَوْرَاقٌ مَالِيَّةٌ. ""التَّضَخُّمُ النَّقْدِيُّ"". 2.""مَقَالٌ نَقْدِيٌّ"": مَقَالٌ قَائِمٌ عَلَى النَّقْدِ فِي مَجَالِ الأَدَبِ. ""أَبْحَاثٌ نَقْدِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16536, 'نَمُوذَجِيٌّ', 'نموذجي', 'منسوب', '', 'نموذجي', 'نمذج', 'مَنْسُوبٌ إِلَى النَّمُوذَجِ', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نَمُوذَجِيٌّ-نَمُوذَجِيٌّ، ةٌ (مَنْسُوبٌ إِلَى النَّمُوذَجِ). ""أَلْقَى دَرْساً نَمُوذَجِيّاً"" : دَرْساً تَرْبَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16537, 'نِهَائِيٌّ', 'نهائي', 'منسوب', 'نهي', 'نهاءي', 'نه', 'مَنْسُوبٌ إِلَى النِّهَايَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نِهَائِيٌّ-نِهَائِيٌّ، ةٌ [ن هـ ي] (مَنْسُوبٌ إِلَى النِّهَايَةِ). 1.""قَرَارٌ نِهَائِيٌّ"" : أَخِيرٌ. ""إِنْذَارٌ نِهَائِيٌّ"" ""بِصِفَةٍ نِهَائِيَّةٍ"". 2.""حُكْمٌ نِهَائِيٌّ"" : لاَ رُجُوعَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16538, 'نُورَانِيٌّ', 'نوراني', 'منسوب', 'نور', 'نوراني', 'نرن', 'مَنْسُوبٌ إِلَى النُّورِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"نُورَانِيٌّ-نُورَانِيٌّ، ةٌ [ن و ر] (مَنْسُوبٌ إِلَى النُّورِ). ""كَلِمَاتٌ نُورَانِيَّةٌ"" : رَبَّانِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16539, 'نِيَابِيٌّ', 'نيابي', 'منسوب', 'نوب', 'نيابي', 'نب', 'مَنْسُوبٌ إِلَى النِّيَابَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"نِيَابِيٌّ-نِيَابِيٌّ، ةٌ [ن و ب] (مَنْسُوبٌ إِلَى النِّيَابَةِ). 1.""عُضْوٌ فِي الْمَجْلِسِ النِّيَابِيِّ"" : فِي البَرْلُمَانِ، مَجْلِس النُّوَّابِ. 2.""إِجْرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16540, 'هَاتِفِيٌّ', 'هاتفي', 'منسوب', 'هتف', 'هاتفي', 'هتف', 'مَنْسُوبٌ إِلَى الْهَاتِفِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"هَاتِفِيٌّ-هَاتِفِيٌّ، ةٌ [هـ ت ف] (مَنْسُوبٌ إِلَى الْهَاتِفِ). 1.""اِتَّصَلَ بِالْمَرْكَزِ الْهَاتِفِيِّ"" : مَرْكَزُ إِدَارَةِ الْهَاتِفِ. 2.""اِتَّصَلَ بِهِ هَاتِفِيّاً"" : بِوَاسِطَةِ الْهَاتِفِ. ""مُكَالَمَةٌ هَاتِفِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16541, 'هَرْطُوقِيٌّ', 'هرطوقي', 'منسوب', 'هرطق', 'هرطوقي', 'هرطق', 'مَنْسُوبٌ إِلَى الْهَرْطَقَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '"هَرَاطِقَةٌ"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْهَرْطَقَةِ). ""رَجُل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16542, 'هَرَاطِقَةٌ', 'هراطقة', 'منسوب', '', 'هراطقة', 'هرطقة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16543, 'هَضْمِيٌّ', 'هضمي', 'منسوب', 'هضم', 'هضمي', 'هضم', 'مَنْسُوبٌ إِلَى الْهَضْمِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"هَضْمِيٌّ-هَضْمِيٌّ، ةٌ [هـ ض م] (مَنْسُوبٌ إِلَى الْهَضْمِ). 1.""الْجِهَازُ الْهَضْمِيُّ"" : مَجْمُوعُ الْأَعْضَاءِ الْمُسَاعِدَةِ عَلَى هَضْمِ الطَّعَامِ كَالأَسْنَانِ وَالْغُدَدِ وَالْمَعِدَةِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16544, 'هَوَائِيٌّ', 'هوائي', 'منسوب', 'هوي', 'هواءي', 'ه', 'مَنْسُوبٌ إِلَى الْهَوَاءِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْهَوَاءِ). 1.""جِهَازٌ هَوَائِيٌّ"" : جِهَازٌ مُوَلِّدٌ لِلْهَوَاءِ. 2.""ضَغْطٌ هَوَائِيٌّ"" : ضَغْطٌ جَوِّيٌّ. 3.""تَيَّارٌ هَوَائِيٌّ"" : تَيَّارُ الْهَوَاءِ بَيْنَ فَتْحَتَيْنِ مُتَقَابِلَتَيْنِ. 4.""الْعَمُودُ الْهَوَائِيُّ"" : جِهَازٌ يُرَكَّبُ عَلَى سَارِيَةٍ بِمَكَانٍ عَالٍ أَوْ فَوْقَ سَطْحٍ يُوصَلُ سِلْكُهُ بِالتِّلْفَازِ يُسَاعِدُ عَلَى وُضُوحِ الصُّورَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16545, 'هُيُولِيٌّ', 'هيولي', 'منسوب', 'هيل', 'هيولي', 'هل', 'مَنْسُوبٌ إِلَى الْهُيُولَى', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"هُيُولِيٌّ-هُيُولِيٌّ، ةٌ [هـ ي ل] (مَنْسُوبٌ إِلَى الْهُيُولَى). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16546, 'وَاقِعِيٌّ', 'واقعي', 'منسوب', 'وقع', 'واقعي', 'قع', 'منسوب إلى الوَاقِعِيَّةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(منسوب إلى الوَاقِعِيَّةِ). 1. ""فَيْلَسُوفٌ وَاقِعِيٌّ"" : التَّابِعُ لِمَذْهَبِ الوَاقِعِيَّةِ. 2.""حَقَائِقُ وَاقِعِيَّةٌ"" : حَقَائِقُ نَاتِجَةٌ عَنِ الوَاقِعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16547, 'وَثَنِيٌّ', 'وثني', 'منسوب', 'وثن', 'وثني', 'ثن', 'منسوب إلى الوَثَنِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(منسوب إلى الوَثَنِ). 1. ""وَثَنِيٌّ مِنْ عَصْرِ الجَاهِلِيَّةِ"" : أَيْ كَانَ يَعْبُدُ الوَثَنَ. 2. ""عِبَادَةٌ وَثَنِيَّةٌ"" : أَيْ عِبَادَةٌ تَنْتَمِي إِلَى عَهْدِ الوَثَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16548, 'وِجْدَانِيٌّ', 'وجداني', 'منسوب', 'وجد', 'وجداني', 'جدن', 'مَنْسُوبٌ إِلَى الوِجْدَانِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الوِجْدَانِ). 1.""شَاعِرٌ وِجْدَانِيٌّ"" : شَاعِرُ الْحُبِّ الغِنَائِيِّ الْمُعَبِّرُ عَنِ الْمُعَانَاةِ. 2.""شِعْرُ الوِجْدَانِيَّاتِ"" : الشِّعْرُ الصَّادِرُ عَنِ النَّفْسِ فِي حَدِيثِهَا عَنِ الْحُبِّ وَالعِشْقِ وَمُعَانَاتِهَا وَإِدْرَاكِهَا لِلأَشْيَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16549, 'وُجُودِيٌّ', 'وجودي', 'منسوب', 'وجد', 'وجودي', 'جد', 'مَنْسُوبٌ إِلَى الوُجُودِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الوُجُودِ). ""فَيْلَسُوفٌ وُجُودِيٌّ"" : قَائِلٌ بِمَذْهَبِ الوُجُودِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16550, 'وَحْدَانِيٌّ', 'وحداني', 'منسوب', 'وحد', 'وحداني', 'حدن', 'مَنْسُوبٌ إِلَى الوَحْدَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الوَحْدَةِ). ""رَجُلٌ وَحْدَانِيٌّ"" : الْمُنْعَزِلُ عَنِ الجَمَاعَةِ. شَرُّ أُمَّتِي الوَحْدَانِيُّ الْمُعْجَبُ بِدِينِهِ الْمُرَائِي بِعَمَلِه (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16551, 'وَحْدَوِيٌّ', 'وحدوي', 'منسوب', 'وحد', 'وحدوي', 'حد', 'مَنْسُوبٌ إِلَى الوَحْدَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الوَحْدَةِ). 1.""سِيَاسِيٌّ وَحْدَوِيٌّ"" : مَنْ يَدْعُو إِلَى اتِّحَادِ قُطْرَيْنِ أَوْ أَكْثَرَ فِي دَوْلَةٍ وَاحِدَةٍ. 2.""أَفْكَارٌ وَحْدَوِيَّةٌ"" : أَفْكَارٌ لَهَا صِبْغَةُ الوَحْدَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16552, 'وَحْشِيٌّ', 'وحشي', 'منسوب', 'وحش', 'وحشي', 'حش', 'مَنْسُوبٌ إِلَى الوَحْشِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"وَحْشِيٌّ-وَحْشِيٌّ، ةٌ [و ح ش] (مَنْسُوبٌ إِلَى الوَحْشِ). 1.""عَمَلٌ وَحْشِيٌّ"" : عَمَلٌ يَتَّسِمُ بِأَعْمَالِ الوُحُوشِ. ""أَعْمَالٌ وَحْشِيَّةٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16553, 'وَدِّيٌّ', 'ودي', 'منسوب', 'ودد', 'ودي', 'د', 'مَنْسُوبٌ إِلَى الوَدِّ، الوُد', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"وَدِّيٌّ-وَدِّيٌّ، وُدِّيٌّ، وِدِّيٌّ، ةٌ [و د د] (مَنْسُوبٌ إِلَى الوَدِّ، الوُدِّ، الوِدِّ). 1.""تَسُودُ بَيْنَهُمَا "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16554, 'وَرْدِيٌّ', 'وردي', 'منسوب', 'ورد', 'وردي', 'رد', 'مَنْسُوبٌ إِلَى الوَرْدِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"وَرْدِيٌّ-وَرْدِيٌّ، ةٌ [و ر د] (مَنْسُوبٌ إِلَى الوَرْدِ). 1.""لَوْنٌ وَرْدِيٌّ"" : مَا كَانَ بِلَوْنِ الوَرْدِ. ""وَرْدِيَّةُ الخَدَّيْنِ"". 2.""الحُمَّى الوَرْدِيَّةُ"" : مَرَضٌ مُعْدٍ يُصِيبُ الأَطْفَالَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16555, 'وِزَارِيٌّ', 'وزاري', 'منسوب', 'وزر', 'وزاري', 'زر', 'مَنْسُوبٌ إِلَى الوِزَارَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"وِزَارِيٌّ-وِزَارِيٌّ، وَزَارِيٌّ، ةٌ [و ز ر] (مَنْسُوبٌ إِلَى الوِزَارَةِ). 1.""مَجْلِسٌ وِزَارِيٌّ"" : مَجْلِسُ أَعْضَاءِ الْحُكُومَةِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16556, 'وَطَنِيٌّ', 'وطني', 'منسوب', 'وطن', 'وطني', 'طن', 'مَنْسُوبٌ إِلَى الوَطَنِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الوَطَنِ). 1. ""وَطَنِيٌّ غَيُورٌ عَلَى وَطَنِهِ"" : مُحِبٌّ لِوَطَنِهِ مُخْلِصٌ لَهُ، يُضَحِّي مِنْ أَجْلِهِ. ""وَاجَهَ الوَطَنِيُّونَ قُوَّاتِ الِاحْتِلالِ"". 2.""لاَ شَيْءَ يَعْلُو عَلَى الْمَصْلَحَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16557, 'وَظِيفِيٌّ', 'وظيفي', 'منسوب', 'وظف', 'وظيفي', 'ظف', 'مَنْسُوبٌ إِلَى الوَظِيفَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"وَظِيفِيٌّ-وَظِيفِيٌّ، ةٌ [و ظ ف] (مَنْسُوبٌ إِلَى الوَظِيفَةِ). 1.""إِجْرَاءٌ وَظِيفِيٌّ"" : عَمَلِيٌّ. ""إِجْرَاءاتٌ وَظِيفِيَّةٌ"". 2.""النَّحْوُ الوَظِيفِيُّ"" : نَحْوٌ يَبْحَثُ فِي وَظَائِفِ مُكَوِّنَاتِ الْجُمْلَةِ. 3.""تَعْلِيمٌ وَظِيفِيّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16558, 'وِقَائِيٌّ', 'وقائي', 'منسوب', 'وقي', 'وقاءي', 'ق', 'مَنْسُوبٌ إِلَى الوِقَايَةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"وِقَائِيٌّ-وِقَائِيٌّ، ةٌ [و ق ي] (مَنْسُوبٌ إِلَى الوِقَايَةِ). 1.""إِجْرَاءٌ وِقَائِيٌّ"" : إٍجْرَاءٌ يُتَوَقَّى بِهِ. ""اِتّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16559, 'وَهْمِيٌّ', 'وهمي', 'منسوب', 'وهم', 'وهمي', 'هم', 'مَنْسُوبٌ إِلَى الوَهْمِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"وَهْمِيٌّ-وَهْمِيٌّ، ةٌ [و هـ م] (مَنْسُوبٌ إِلَى الوَهْمِ). 1.""عَمَلٌ وَهْمِيٌّ"" : عَمَلٌ قَائِمٌ عَلَى الْخَيَالِ وَالتَّصَوُّرِ يَذْهَبُ بِصَاحِبِهِ بَعِيداً عَنِ الوَاقِعِ. 2.""أَمْرَاضٌ وَهْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16560, 'يَدَوِيّ', 'يدوي', 'منسوب', 'يدي', 'يدوي', 'د', 'مَنْسُوبٌ إِلَى اليد', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"يَدَوِيّ-يَدَوِيّ، ةٌ[ي د ي] (مَنْسُوبٌ إِلَى اليد). 1.""الأَعْمَالُ، أَوِالأَشْغَالُ الْيَدَوِيَّةُ"" : الأَشْغَالُ الَّتِي تُعْمَلُ بِالْيَدِ. ""شُغْلٌ يَدَوِيٌّ""l ""يَشْتَغِلُ يَدَوِيّاً"" ‎l ""صِنَاعَةٌ يَدَوِيَّةٌ"". 2.""قُنْبُلَةٌ يَدَوِيَّةٌ"" : أَيْ قُنْبُلَةٌ تُرْمَى بِالْيَدِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16561, 'يَمَانِيٌّ', 'يماني', 'منسوب', 'يمن', 'يماني', 'من', 'مَنْسُوبٌ إِلَى الْيَمَنِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى الْيَمَنِ). ""يَمَانِيٌّ قُحٌّ"" : مِنْ بَلَدِ الْيَمَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16562, 'يَمَنِيٌّ', 'يمني', 'منسوب', '', 'يمني', 'من', 'مَنْسُوبٌ إِلَى الْيَمَنِ.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسُوبٌ إِلَى الْيَمَنِ). ""الشَّعْبُ اليَمَنِيُّ شَعْبُ اليُمْنِ والعَطَاءِ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16563, 'يَوْمِيٌّ', 'يومي', 'منسوب', 'يوم', 'يومي', 'م', 'مَنْسُوبٌ إِلَى الْيَوْمِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"يَوْمِيٌّ-يَوْمِيٌّ، ةٌ [ي و م] (مَنْسُوبٌ إِلَى الْيَوْمِ). 1.""يَقُومُ بِعَمَلٍ يَوْمِيٍّ"" : فِي كُلِّ يَوْمٍ، مُسْتَمِرٍّ، دَائِمٍ. "" يَأْتِي يَوْمِيّاً إِلَى الْمَكْتَبِ"". 2.""جَرِيدَةٌ يَوْمِيَّةٌ"" : تَصْدُرُ كُلَّ يَوْمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16564, 'إمْبِرَاطُورِيّ', 'إمبراطوري', 'منسوب', '', 'ءمبراطوري', 'إمبرطر', 'منسُوبٌ إلَى إمْبرَاطُور', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"إمْبِرَاطُورِيّ-إمْبِرَاطُورِيّ، ةٌ (منسُوبٌ إلَى إمْبرَاطُور). ""حُكْمٌ إمْبرَاطُورِيّ"" : حُكْمٌ لَهُ صِيغَةٌ إمْبِراطُورِيَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16565, 'أَمْرِيكِيٌّ', 'أمريكي', 'منسوب', '', 'ءمريكي', 'مرك', 'مَنْسوبٌ إلى أَمْريكا.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسوبٌ إلى أَمْريكا)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16566, 'أُمَوِيٌّ', 'أموي', 'منسوب', '', 'ءموي', 'م', 'مَنْسوبٌ إلى أُمَيَّة', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"أُمَوِيٌّ-أُمَوِيٌّ، ةٌ (مَنْسوبٌ إلى أُمَيَّة). ""أَسَّسَ الخَليفَةُ الأُمَوِيُّ مُعاوِيَةُ الدَّوْلَةَ الأُمَوِيَّةَ"" : الأُمَوِيُّ : الْمُنْتَمي إلى قَبيلَةِ بَنِي أُمَيَّةَ أَوْ دَوْلَتِهِمْ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16567, 'أورُوبِّيٌّ', 'أوروبي', 'منسوب', '', 'ءوروبي', 'رب', 'مَنْسوبٌ إلَى أُورُوبَّا.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسوبٌ إلَى أُورُوبَّا)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16568, 'إِيجَابِيٌّ', 'إيجابي', 'منسوب', 'وجب', 'ءيجابي', 'إجب', 'مَنْسُوبٌ إلَى إيجَاب', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إلَى إيجَاب. 1.""تَوَصَّلَ بِرَدٍّ إيَجَابِيٍّ"" : بِرَدٍّ مُلاَئِمٍ، مُنَاسِبٍ، فِيهِ مُوَافَقَةٌ لِرَغْبَتِهِ. 2.""كَانَتْ نَتَائِجُ الامْتِحَانِ إيجَابِيَّةً"" : مُهِمَّةً، مُرْضِيَةً. 3.""تَمَيَّزَ شُغْلُهُ بِعِدَّةِ إيجَابِيَّاتٍ"" : الْمَزَايَا وَالأَعمَالُ النَّاجِحَةُ."', '');
