INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16591, 'تَحْضِيرِيٌّ', 'تحضيري', 'منسوب', 'حضر', 'تحضيري', 'تحضر', 'مَنْسُوبٌ إِلَى تَحْضِيرٍ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَحْضِيرِيٌّ-تَحْضِيرِيٌّ، ةٌ [ح ض ر] (مَنْسُوبٌ إِلَى تَحْضِيرٍ). 1.""الفَصْلُ التَّحْضِيرِيُّ"" : السَّنَةُ الأُولَى مِنَ الفُصُولِ الابْتِداَئِيَّةِ. 2.""بَدَأَتْ أَشْغاَلُ الْمُؤْتَمَرِ التَّحْضِيرِيِّ"" : الْمُؤْتَمَرُ التَّهْيِيئِيُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16592, 'تَذْكَارِيٌّ', 'تذكاري', 'منسوب', 'ذكر', 'تذكاري', 'تذكر', 'مَنْسُوبٌ إِلَى تَذْكَارٍ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَذْكَارِيٌّ-تَذْكَارِيٌّ، ةٌ [ذ ك ر] (مَنْسُوبٌ إِلَى تَذْكَارٍ). ""أَقَامَ حَفْلاً تَذْكَارِيّاً"" : الحَفْلُ الخاصّ بِإِحْيَاءِ ذِكْرىً مَّا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16593, 'تَسَاؤُلِيٌّ', 'تساؤلي', 'منسوب', 'سأل', 'تساءلي', 'تسل', 'مَنْسُوبٌ إِلَى تَسَاؤُل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"تَسَاؤُلِيٌّ-تَسَاؤُلِيٌّ، ةٌ [س أ ل] (مَنْسُوبٌ إِلَى تَسَاؤُل). ""تَبَادَلُوا نَظَرَاتٍ تَسَاؤُلِيَّةً"" : نَظَرَاتٍ اِسْتِفْهَامِيَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16594, 'تونِسِيّ', 'تونسي', 'منسوب', '', 'تونسي', 'تنس', 'مَنْسوبُ إلى تونُسَ.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. الْمَنْسوبُ إلى تونُسَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16595, 'سَامِريٌّ', 'سامري', 'منسوب', '', 'سامري', 'سمر', 'منْسُوبٌ إلَى جَمَاعةِ السَّام', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون. (منْسُوبٌ إلَى جَمَاعةِ السَّامِرَةِ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16596, 'حَضْرَمِيٌّ', 'حضرمي', 'منسوب', '', 'حضرمي', 'حضرم', 'مَنْسُوبُ إلَى حَضْرَمَوْت', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '"حضارِمَةٌ"', '', '', '', '', '', '', '', '', '"ج: حضارِمَةٌ. الْمَنْسُوبُ إلَى حَضْرَمَوْت.: مُقاطَعَةٌ تَقَعُ شَرْقَيَّ اليَمَنِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16597, 'حضارِمَةٌ', 'حضارمة', 'منسوب', '', 'حضارمة', 'حضرمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16598, 'خُرَافِيٌّ', 'خرافي', 'منسوب', 'خرف', 'خرافي', 'خرف', 'مَنْسُوبٌ إِلَى خُرَافَةٍ ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خُرَافِيٌّ-خُرَافِيٌّ، ةٌ [خ ر ف] (مَنْسُوبٌ إِلَى خُرَافَةٍ) . 1.""عَمَلٌ خُرَافِيٌّ"" : مُدْهِشٌ، عَجِيبٌ، غَريبٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16599, 'اِسْتِوَائِيٌّ', 'استوائي', 'منسوب', 'سوي', 'استواءي', 'ست', 'مَنْسوبٌ إلى خَطِّ الاسْتِواءِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"اِسْتِوَائِيٌّ-اِسْتِوَائِيٌّ، ةٌ [س و ي] (مَنْسوبٌ إلى خَطِّ الاسْتِواءِ). الْمَناطِقُ الاسْتِوائِيَّةُ هِيَ: أَمْرِيكا الجَنوبِيَّةُ وَإِفْرِيقِيا الوُسْطَى"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16600, 'دِمَشْقِيٌّ', 'دمشقي', 'منسوب', '', 'دمشقي', 'دمشق', 'مَنْسوبٌ إلى دِمَشْقَ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"دِمَشْقِيٌّ-دِمَشْقِيٌّ، ةٌ (مَنْسوبٌ إلى دِمَشْقَ). ""هُوَ دِمَشْقِيُّ الأَصْلِ"": مِنْ سُكَّان دِمَشْقَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16601, 'رُبَاعِيُّ', 'رباعي', 'منسوب', 'ربع', 'رباعي', 'ربع', 'مَنْسُوبٌ إلَى رُبَاعَ، أيْ مَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رُبَاعِيُّ-رُبَاعِيُّ، ةٌ [ر ب ع] (مَنْسُوبٌ إلَى رُبَاعَ، أيْ مَا رُكِّبَ مِنْ أرْبَعةٍ). 1.""شَكْلٌ رُبَاعِيُّ الأَضْلاعِ"" (هن) : مُرَكَّبٌ مِنْ أرْبَعَةِ أضْلاعٍ. ""الْمُضَلَّعُ الرُّبَاعِيُّ"". 2.""مُؤْتَمَرٌ رُبَاعِيٌّ"" : مُؤْتَمَرٌ تَحْضُرُهُ أرْبَعُ دُوَلٍ أوْ أرْبَعُ شَخْصِيَّاتٍ. 3. ""فِعْلٌ رُبَاعِيُّ""‎ : فِعْلٌ مُكَوَّنٌ مِنْ أرْبَعَةِ أَحْرُفٍ وَهُوَ إمَّا مُجَرَّدٌ وَإِمَّا مَزِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16602, 'سُبَاعِيٌّ', 'سباعي', 'منسوب', 'سبع', 'سباعي', 'سبع', 'مَنْسُوبٌ إلَى سُبَاعَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"سُبَاعِيٌّ-سُبَاعِيٌّ، ةٌ [س ب ع] (مَنْسُوبٌ إلَى سُبَاعَ). 1.""كَلِمَةٌ سُبَاعِيَّةٌ"" : تَتَكَوَّنُ مِنْ سَبْعَةِ أحْرُفٍ. 2.""شَكْلٌ هَن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16603, 'سُفِسْطائِيّ', 'سفسطائي', 'منسوب', '', 'سفسطاءي', 'سفسط', 'مَنْسُوبٌ إلَى سُفِسْطَائِيَّة', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"سُفِسْطائِيّ-سُفِسْطائِيّ، ةٌ (مَنْسُوبٌ إلَى سُفِسْطَائِيَّة)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16604, 'سَلِيقِيٌّ', 'سليقي', 'منسوب', 'سلق', 'سليقي', 'سلق', 'مَنْسوبٌ إلَى سَلِيقَة', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"سَلِيقِيٌّ-سَلِيقِيٌّ، ةٌ [س ل ق] (مَنْسوبٌ إلَى سَلِيقَة). ""رَجُلٌ سَلِيقِيٌّ"" : فَصِيحٌ يَنْطِقُ بِاللُّغَةِ صَحِيحَةً من غَيْر تَعَلُّمِ قوَاعِدِهَا. وَلَسْتُ بِنَحْوِيٍّ يَلُوكُ لِسَانَـه*وَلَكِنْ سَلِيقيٌّ أَقولُ فأُعْـرِب."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16605, 'سُورِيٌّ', 'سوري', 'منسوب', '', 'سوري', 'سر', 'مَنْسوبٌ إلى سُورِيَّةَ.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسوبٌ إلى سُورِيَّةَ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16606, 'صَرْفِيٌّ', 'صرفي', 'منسوب', 'صرف', 'صرفي', 'صرف', 'مَنْسُوبٌ إِلَى صَرْفٍ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"صَرْفِيٌّ-صَرْفِيٌّ، ةٌ [ص ر ف] (مَنْسُوبٌ إِلَى صَرْفٍ). ""عَالِمٌ صَرْفِيٌّ"" : عَالِمٌ بِعِلْمِ الصَّرْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16607, 'صِهْيُونِيٌّ', 'صهيوني', 'منسوب', '', 'صهيوني', 'صهن', 'مَنْسُوبٌ إِلَى صِهْيُونَ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":صَهَايِنَةٌ"', '', '', 'ـو', '', '', '', '', '', '"ج: صَهَايِنَةٌ. (مَنْسُوبٌ إِلَى صِهْيُونَ). : الْمُنْتَمِي إِلَى الْحَرَكَةِ الصِّهْيُونِيَّةِ."', ':لا جذر:لا مفرد');
