INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16609, 'طُوبَاوِيٌّ', 'طوباوي', 'منسوب', 'طوب', 'طوباوي', 'طب', 'مَنْسُوبٌ إِلَى طُوبَى', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"طُوبَاوِيٌّ-طُوبَاوِيٌّ، طُوبَائِيٌّ، ةٌ [ط و ب] (مَنْسُوبٌ إِلَى طُوبَى). ""رَجُلٌ طُوبَاوِيٌّ"" : مَنْ يُحَلِّقُ بَعِيداً وَيُنْشِئُ مُثُلاً وَيَسْعَى إِلَى تَحْقِيقِهَا وَهِيَ بَعِيدَةٍ عَنِ الوَاقِعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16610, 'طوبائي', 'طوبائي', 'منسوب', '', 'طوباءي', 'طب', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"طُوبَاوِيٌّ-طُوبَاوِيٌّ، طُوبَائِيٌّ، ةٌ [ط و ب] (مَنْسُوبٌ إِلَى طُوبَى). ""رَجُلٌ طُوبَاوِيٌّ"" : مَنْ يُحَلِّقُ بَعِيداً وَيُنْشِئُ مُثُلاً وَيَسْعَى إِلَى تَحْقِيقِهَا وَهِيَ بَعِيدَةٍ عَنِ الوَاقِعِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16611, 'عَبْقَرِيٌّ', 'عبقري', 'منسوب', 'عبقر', 'عبقري', 'عبقر', 'مَنْسُوبٌ إِلَى عَبْقَرَ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عَبْقَرِيٌّ-عَبْقَرِيٌّ، ةٌ [ع ب ق ر] (مَنْسُوبٌ إِلَى عَبْقَرَ). ""إِنَّهُ كَاتِبٌ عَبْقَرِيٌّ"" : يَأْتِي بِعَمَلٍ فِيهِ كَمَالٌ وَإِبْدَاعٌ وَخَلْقٌ. ""فَنَّانٌ عَبْقَرِيٌّ"" ""عَبْقَرِيٌّ فِي الْمُوسِيقَى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16612, 'عَدَنِيٌّ', 'عدني', 'منسوب', 'عدن', 'عدني', 'عدن', 'مَنْسُوبٌ إِلَى عَدَنَ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عَدَنِيٌّ-عَدَنِيٌّ [ع د ن] (مَنْسُوبٌ إِلَى عَدَنَ)."', '');
