INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16614, 'فَوْقَانِيٌّ', 'فوقاني', 'منسوب', 'فوق', 'فوقاني', 'فقن', 'مَنْسُوبٌ إِلَى فَوْقَ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"فَوْقَانِيٌّ-فَوْقَانِيٌّ، ةٌ [ف و ق] (مَنْسُوبٌ إِلَى فَوْقَ). ""الْبَيْتُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16615, 'قُرَشِيٌّ', 'قرشي', 'منسوب', '', 'قرشي', 'قرش', 'مَنْسُوبٌ إِلَى قَبِيلَةِ قُرَ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسُوبٌ إِلَى قَبِيلَةِ قُرَيْشٍ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16616, 'قَطَرِيٌّ', 'قطري', 'منسوب', '', 'قطري', 'قطر', 'مَنْسُوبٌ إِلَى قَطَر.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسُوبٌ إِلَى قَطَر)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16617, 'كَاثُولِيكِيٌّ', 'كاثوليكي', 'منسوب', '', 'كاثوليكي', 'كثلك', 'مَنْسُوبٌ إِلَى كَاثُولِيك', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"كَاثُولِيكِيٌّ-كَاثُولِيكِيٌّ (مَنْسُوبٌ إِلَى كَاثُولِيك). : أَيْ عَلَى مَذْهَبِ الكَاثُولِيكِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16618, 'لاَتِينِيٌّ', 'لاتيني', 'منسوب', '', 'لاتيني', 'لتن', 'مَنْسُوبٌ إِلَى لاَتِينْيُوم', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسُوبٌ إِلَى لاَتِينْيُوم، والكَلِمَةُ اسْمُ بِلاَدٍ فِي إِيطَالْيَا). 1.""اللُّغَةُ اللاَّتِينِيَّةُ"" : لُغَةٌ أُورُوبِّيَّةٌ قَدِيمَةٌ، مِنْهَا اسْتَمَدَّتِ اللُّغَةُ الأُورُوبِيَّةُ حَيَاتَهَا. 2.""الحُرُوفُ اللاَّتِينِيَّةُ"" : هِيَ الْحُرُوفُ الَّتِي تَسْتَعْمِلُهَا اللُّغَاتُ الأُورُوبِّيَّةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16619, 'لُبْنَانِيٌّ', 'لبناني', 'منسوب', '', 'لبناني', 'لبنن', 'مَنْسُوبٌ إِلَى لُبْنَان.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسُوبٌ إِلَى لُبْنَان)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16620, 'لَوْزِيٌ', 'لوزي', 'منسوب', 'لوز', 'لوزي', 'لز', 'مَنْسُوبٌ إِلَى لَوْزٍ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"لَوْزِيٌ-لَوْزِيٌ، ةٌ [ل و ز] (مَنْسُوبٌ إِلَى لَوْزٍ). : مَا كَانَ عَلَى هَيْئَةِ اللَّوْزِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16621, 'لِيبِيٌّ', 'ليبي', 'منسوب', '', 'ليبي', 'لب', 'مَنْسُوبٌ إِلَى لِيبْيَا.', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (مَنْسُوبٌ إِلَى لِيبْيَا)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16622, 'مِصْرِيٌّ', 'مصري', 'منسوب', 'مصر', 'مصري', 'مصر', 'مَنْسُوبٌ إِلَى مِصْرَ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مَنْسُوبٌ إِلَى مِصْرَ) : ""أَحْمَدُ شَوْقي شاعِرٌ مِصْرِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16623, 'مَصْلِيٌّ', 'مصلي', 'منسوب', 'مصل', 'مصلي', 'مصل', 'مَنْسُوبٌ إِلَى مَصْل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَصْلِيٌّ-مَصْلِيٌّ، ةٌ [م ص ل] (مَنْسُوبٌ إِلَى مَصْل). : سَائِلٌ دَمَوِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16624, 'نَشَادِرِيٌّ', 'نشادري', 'منسوب', '', 'نشادري', 'نشدر', 'مَنْسُوبٌ إِلَى نَشَادِر', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نَشَادِرِيٌّ-نَشَادِرِيٌّ، ةٌ (مَنْسُوبٌ إِلَى نَشَادِر)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16625, 'فُسْتُقِيٌّ', 'فستقي', 'منسوب', 'فستق', 'فستقي', 'فستق', 'مَنْشُوبٌ إِلَى الْفُسْتُقِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"فُسْتُقِيٌّ-فُسْتُقِيٌّ [ف س ت ق] (مَنْشُوبٌ إِلَى الْفُسْتُقِ). ""اِرْتَدَتْ فُسْتَاناً فُسْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16626, 'اِنْتِهازِيٌّ', 'انتهازي', 'منسوب', 'نهز', 'انتهازي', 'نتهز', 'الْمُتَّصِفُ بِالانْتِهازِيَّة', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '"ج:"', '', '', 'ـو', '', '', '', '', '', '"، (الْمُتَّصِفُ بِالانْتِهازِيَّةِ). ""رَجُلٌ اِنْتِهازِيٌّ"" : مَنْ يَسْتَغِلُّ الفُرَصَ لِصالِحِهِ دونَ اعْتِبارِ الغَيْرِ والْمَصْلَحَةِ العامَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16627, 'جِنَائِيٌّ', 'جنائي', 'منسوب', 'جني', 'جناءي', 'جن', 'الْمُخَتَصُّ بِالجِنَايَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '"ج:"', '', '', 'ـو', '', '', '', '', '', '"جِنَائِيٌّ-جِنَائِيٌّ، ةٌ [ج ن ي] (الْمُخَتَصُّ بِالجِنَايَةِ). 1.""حَكَمَتْ عَلَيْهِ الْمَحْكَمَةُ الجِنَائِيَّةُ"" : الْمَحْكَمَةُ الْمُخْتَصَّةُ بِالجِنَايَاتِ. 2.""القَانُونُ الجِنَائِيُّ"" : قَانُونُ العُقُوبَاتِ وَالجُنَحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16628, 'صِحِّيٌّ', 'صحي', 'منسوب', 'صحح', 'صحي', 'صح', 'الْمُخْتَصُّ بِالصِّحَّةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '"ج:"', '', '', 'ـو', '', '', '', '', '', '"صِحِّيٌّ-صِحِّيٌّ، ةٌ [ص ح ح] (الْمُخْتَصُّ بِالصِّحَّةِ). 1.""كَانَ فِي وَضْعٍ صِحِّيٍّ جَيِّدٍ"" : سَلِيمٍ، مُعَافـىً. 2.""طَعَامٌ صِحِّيٌّ"" : طَعَامٌ تَتَوَافَرُ فِيهِ الشُّرُوطُ الصِّحِّيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16629, 'صِنَاعِيٌّ', 'صناعي', 'منسوب', 'صنع', 'صناعي', 'صنع', 'الْمُخْتَصُّ بِالصِّنَاعَةِ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '"ج:"', '', '', 'ـو', '', '', '', '', '', '"صِنَاعِيٌّ-صِنَاعِيٌّ، ةٌ [ص ن ع] (الْمُخْتَصُّ بِالصِّنَاعَةِ). 1.""الْعَصْرُ الصِّنَاعِيُّ"" : الْعَصْرُ الْمُعْتَمِدُ عَلَى الصِّنَاعَةِ. ""الإِنْتَاجُ الصِّنَاعِيُّ"". 2.""الدُّوَلُ الصِّنَاعِيَّةُ"" : الدُّوَلُ الَّتِي غَدَتْ قَاعِدَتُهَا الاِقْتِصَادِيَّةُ مُعْتَمِدَةً عَلَى الصِّنَاعَات"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16630, 'نَوَوِيٌّ', 'نووي', 'منسوب', 'نوي', 'نووي', 'ن', 'الْمُخْتَصُّ بِنَوَاةِ الذَّرّ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '"ج:"', '', '', 'ـو', '', '', '', '', '', '"نَوَوِيٌّ-نَوَوِيٌّ، ةٌ [ن و ي] (الْمُخْتَصُّ بِنَوَاةِ الذَّرَّةِ). ""سِلاَحٌ نَوَوِيٌّ"" : سِلاَحٌ صُنِعَ مِنَ الطَّاقَةِ الذَّرِّيَّةِ يَفْتِكُ بِالإِنْسَانِ وَالنَّبَاتِ وَيُدَمِّرُ الْحَيَاةَ. ""أَسْلِحَةٌ نَوَوِيَّةٌ"" ""صَوَارِيخُ نَوَوِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16631, 'مَغَارِبِيٌّ', 'مغاربي', 'منسوب', 'غرب', 'مغاربي', 'مغرب', 'الْمُنْتَسِبُ إِلَى بُلْدَانِ ', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(الْمُنْتَسِبُ إِلَى بُلْدَانِ الْمَغْرِبِ العَرَبِيِّ). ""الدُّوَلُ الْمَغَارِبِيَّةٌ"" : دُوَلُ الْمَغْرِبِ العَرَبِيِّ : لِيبْيَا وتُونُس والْجَزَائِر والْمَغْرِب ومُورِيطَانْيَا. ن. مَغْرِب."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16632, 'دُرْزِيٌّ', 'درزي', 'منسوب', '', 'درزي', 'درز', 'الْمُنْتَسِبُ إلَى طَائِفَةِ ا', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (الْمُنْتَسِبُ إلَى طَائِفَةِ الدُّرُوزِ)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16633, 'إلِكْتُرونِيٌّ', 'إلكتروني', 'منسوب', '', 'ءلكتروني', 'إلكترن', 'الْمَنْسُوبُ إِلَى الإلِكْتُرُ', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"إلِكْتُرونِيٌّ-إلِكْتُرونِيٌّ، ةٌ (الْمَنْسُوبُ إِلَى الإلِكْتُرُونِ). 1.""بَدَأَ يَنْتَشِرُ العَقْلُ الإلِكْتُرُونِيُّ فِي كُلِّ الْمَكَاتِبِ"" : آلَةُ الحَاسُوبِ تَعْتمِدُ عَلَى مَادَّةِ الإلِكْترُونِ لإِجْرَاءِ أدَقِّ الَعَمَلِيّاتِ الحِسَابِيَّةِ وَبِأَسْرَعِ وَقْتٍ مُمْكِنٍ. وَيُسَمَّى أيْضاً كمبيوتر. 2.""عِلْمُ الإلِكْترونِيَّاتِ"": عِلْمٌ يَهْتَمُّ بِتَرْكِيبِ الإِلِكْترونِيَّاتِ وَاسْتِخْدَامِهَا وَتنَاوُلِهَا، وَهُوَ فَرْعٌ مِنَ فُروعِ الفِيزِيَاءِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16634, 'جَنَائِزِيٌّ', 'جنائزي', 'منسوب', '', 'جناءزي', 'جنز', 'الْمَنْسُوبُ إِلَى الْجِنَازَة', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"جَنَائِزِيٌّ-جَنَائِزِيٌّ، ةٌ (الْمَنْسُوبُ إِلَى الْجِنَازَةِ). ""لَحْنٌ جَنَائِزِيٌّ"" : لَحْنُ الْمَآتِمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16635, 'رُوحِيٌّ', 'روحي', 'منسوب', 'روح', 'روحي', 'رح', 'الْمَنْسوبُ إلى الرُّوحِ والْم', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"رُوحِيٌّ-رُوحِيٌّ، ةٌ [ر و ح] (الْمَنْسوبُ إلى الرُّوحِ والْمُخْتَصُّ بِها). 1.""حَياةٌ روحِيَّةٌ"" : حَيَاةٌ مُرْتَبِطَةٌ بِما هُوَ ذِهْنِيٌّ، بَعيدَةٌ عنْ كُلِّ مَا هُوَ مادِّيٌّ وحِسِّيٌّ. 2.""السُّلْطَةُ الرُّوحِيَّةُ"" : السُّلْطَةُ الدِّينِيَّةُ. 3.""الْمَشْروباتُ الرُّوحِيَّةُ"" : الْمَشْروباتُ الكُحولِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16636, 'لَهَوِيٌّ', 'لهوي', 'منسوب', 'لهو', 'لهوي', 'له', 'النِّسْبَةُ إِلَى اللَّهَاةِ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"لَهَوِيٌّ-لَهَوِيٌّ، ةٌ [ل هـ و] (النِّسْبَةُ إِلَى اللَّهَاةِ). ""حَرْفٌ لَهَوِيٌّ"" : مَخْرَجُهُ اللَّهَاةُ. ""الْحُرُوفُ اللَّهَوِيَّةُ هِيَ الْقَافُ وَالْخَاء وَالغَيْنُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16637, 'إِبَاضِيَّةٌ', 'إباضية', 'منسوب', '', 'ءباضية', 'إبضة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": فِرْقَةٌ مِنْ فِرَقِ الخَوَارِجِ تُنْسَبُ إِلَى عَبْدِ اللَّهِ بْنِ إِبَاضِ التَّمِيمِيّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16638, 'أبْجَدِيٌّ', 'أبجدي', 'منسوب', '', 'ءبجدي', 'بجد', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '": تُطلَقُ عَلَى مَجْمُوعَةِ حُرُوفِ الهِجَاءِ فِي اللغَةِ العَرَبِيَّةِ، سُمِّيَتْ بِاسْمِ أوَّلِ الألْفاظِ الَّتِي جَمَعَتْ هَذِهِ الحُرُوف. أبْجَدَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16639, 'أُحَادِيٌّ', 'أحادي', 'منسوب', 'أحد،وحد', 'ءحادي', 'حد', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"أُحَادِيٌّ-أُحَادِيٌّ، ةٌ [ أ ح د ، و ح د]. 1.""يَعْزفُ أُحَادِيّاً"" : يَعْزف مُنْفَرِداً. 2.""هُوَ فِي آرَائِهِ أُحَادِيُّ الجَانِبِ"" : يَنْظرُ إِلَيْهَا مِنْ زَاوِيَةٍ وَاحِدَةٍ، مِنْ جَانِبٍ وَاحِدٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16640, 'آذَرْيٌّ', 'آذري', 'منسوب', '', 'ءءذري', 'آذر', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"آذَرْيُــون-آذَرْيُــون (نب).: نَبَاتٌ ذُو زَهْرٍ، مِنْ فَصِيلَةِالأنْبُوبِيَّاتِ الْمُرَكَّبَةِ الزَّهْرِ، يَنْبُتُ فِي الخَريفِ، يَخْتَلِفُ زَهْرُهُ مِنْ أَصْفَرَ إِلَى أحْمَرَ إِلَى لَوْنِ الذَّهَبِ، فِي وَسَطِهِ خَمْلٌ أسْودُ. لَهُ مَنافِعُ وَمَزايا طِبِّيَّةٌ، يُعالِـجُ الجُـروحَ وَهُو مُضـادٌّ لِلالتِهاباتِ، مِنْ أَنْواعِهِ: آذَرْيون الماءِ، وآذَرْيون الْمُسْتَنْقَعاتِ. كَـأنَّ آذَرْيُونَها والشَّمْسُ فِيهِ كَالِيهِ*مَدَاهِنُ مِن ذَهَبٍ فِيهَا بَقَايَا غَالِيـه (ابن الرومي)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16641, 'أَطْلَسِيٌّ', 'أطلسي', 'منسوب', '', 'ءطلسي', 'طلس', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"""يَحُدُّ الْمَغْرِبَ غَرْباً الْمُحيطُ الأطْلَسِيُّ"" : بَحْرٌ عَظيمٌ يُحيطُ بِأُوروبَّا وَإِفْريقِيَا غَرْباً وَبِأَمْرِيكا شَرْقاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16642, 'أورثُوذُكْسِيٌّ', 'أورثوذكسي', 'منسوب', '', 'ءورثوذكسي', 'رثذكس', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": مِنَ الطَّوائِفِ المسِيحيَّة، تُوجَدُ كَنَائِسهَا فِي الشَّرْقِ العَرَبِيِّ، ودُوَلِ البَلْقانِ، وَدُوَلِ رُوسْيا، وَهُناكَ أُورثُوذُكْسِيّة مُنْتَشِرَة فِي بُلْدانٍ أخْرَى مِنَ العَالَمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16643, 'أَنْتُروبولوجِيٌّ', 'أنتروبولوجي', 'منسوب', '', 'ءنتروبولوجي', 'نتربلج', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": عِلْمُ الإنْسانِ مُخْتَصٌّ بِالبَحْثِ في أَصْلِ النَّوْعِ البَشَرِيِّ وَتَطَوُّرِهِ وَعاداتِهِ و"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16644, 'أَنْتُولوجِيَّةٌ', 'أنتولوجية', 'منسوب', '', 'ءنتولوجية', 'نتلجة', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '": مُنْتَخَباتُ القَصائِدِ الشِّعْرِيَّةِ أَوِ القِطَعِ الْمُوسِيقِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16645, 'إمْبرَاطُوريٌّ', 'إمبراطوري', 'منسوب', '', 'ءمبراطوري', 'إمبرطر', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": نِظَامٌ مِنْ أنْظِمَةِ الحُكْمِ القَدِيمَةِ قَائِمٌ عَلَى أسَاسِ التَّحَكُّمِ فِي أقَالِيمَ وَاسِعَةٍ وَشُعُوبٍ مُخْتَلِفَةٍ. مِثْلُ: الإمْبرَاطُورِيَّةُ العُثْمَانِيَّةُ الَّتِي انْتَهَتْ بَعْدَ الحَرْبِ العَالَمِيَّةِ الأولَى، وَالإمْبرَاطُورِيَّةُ البِريطَانِيَّةُ التِي اِنْتَهَتْ قَبْلَ الحَرْبِ العَالَمِيَّةِ الثَّانِيَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16646, 'أَيدِيُولُوجِيٌّ', 'أيديولوجي', 'منسوب', '', 'ءيديولوجي', 'دلج', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": مَجْمُوعُ الأفْكَارِ وَالْمُعْتَقَدَاتِ، خَاصَّةٌ بِ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16647, 'أَوْلَوِيٌّ', 'أولوي', 'منسوب', 'أول', 'ءولوي', 'ل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""لَهُ حَقُّ الأَوْلَوِيَّةِ"" : الأَسْبَقِيَّةُ. ""يَنْبَغِي أَنْ يَأْتِيَ دَوْرُهُ بَعْدَ أَصْحابِ الأَوْلَوِيَّةِ"" : مَنْ لَهُمُ الأَسْبَقِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16648, 'أَوَّلِيٌّ', 'أولي', 'منسوب', 'أول', 'ءولي', 'ل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1. ""البِنَاءُ الأوَّلِيُّ"": الأسَاسِيُّ. 2. ""العَدَدُ الأوَّلِيُّ"" : الأَصْلِيُّ. 3.""قَدَّمَ طَلَباً أوَّلِيّاً"": مَا يَنْبَغِي القِيَامُ بِهِ قَبْلَ أيِّ شَيْءٍ، اِسْتِبَاقِيّاً. 4.""قَامَ بِتَجْرِبَةٍ أوَّلِيَّةٍ"": قَبْلِيَّةٍ، تَمْهِيدِيَّةٍ. 5. ""لاَ بُدَّ مِنْ فَهْمِ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16649, 'إِيكُولوجِيٌّ', 'إيكولوجي', 'منسوب', '', 'ءيكولوجي', 'إكلج', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": عِلْمٌ يَدْرُسُ عَلاَقَةَ الكَائِنَاتِ الحَيَّةِ فيمَا بَيْنَهَا وَبَيْنَ بِيئَتِهَا الطَّبِيعِيَّةِ الَّتِي تَعِيشُ فِيهَا. وَأصْبَحَ الْمُهْ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16650, 'باتولوجِيٌّ', 'باتولوجي', 'منسوب', '', 'باتولوجي', 'بتلج', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"باتولوجِيَّةٌ-باتولوجِيَّةٌ (طب). 1.: عِلْمٌ يَبْحَثُ في أَسْبابِ وَأَعْراضِ الأَمْراضِ وَتَطَوُّرِها وَتَشْخيصِها. 2.: مَجْموعُ ظَواهِرِ مَرَضٍ وَما يَنْشَأُ عَنْهُ مِنْ آثارٍ مَرَضِيَّةٍ "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16651, 'بَرَّانِيٌّ', 'براني', 'منسوب', 'برر', 'براني', 'برن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"بَرَّانِيٌّ-بَرَّانِيٌّ، ةٌ [ب ر ر]. ""جاءَ رَجُلٌ بَرَّانِيٌّ"" : خارِجِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16652, 'بُروتِسْتانِيٌّ', 'بروتستاني', 'منسوب', '', 'بروتستاني', 'برتستن', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": مَنْ كانَ على مَذْهَبِ البُروتِسْتانِيَّة."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16653, 'بِكْتُرولوجْيٌّ', 'بكترولوجي', 'منسوب', '', 'بكترولوجي', 'بكترلج', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": عِلْمُ الجَراثِيمِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16654, 'تَجْرِيدِيٌّ', 'تجريدي', 'منسوب', '', 'تجريدي', 'تجرد', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": مَذْهَبٌ مِنْ مَذَاهِبِ فَنِّ الرَّسْمِ الحَدِيثِ لاَ يَهْتَمُّ بِمَعَالِمِ الصُّورَةِ وَالوَاقِعِ، يُطْلِقُ الفَنَّانُ العِنَانَ لِلْخَيَالِ "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16655, 'تَكْعيبِيٌّ', 'تكعيبي', 'منسوب', '', 'تكعيبي', 'تكعب', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": مَذْهَبٌ مِنَ الْمَذاهِبِ الحَديثَةِ في فَنِّ الرَّسْمِ، يَعْتَمِدُ الْمُكَعَّباتِ لِرَسْمِ شُخوصِ أَشْكالِهِ معَ اعْتِمادِ الرُّؤْيَةِ الذَّاتِيَّةِ قاعِدَةً لِلإِحْساسِ بِالأشْكالِ، والتَّعْبيرِ عَنْها على أَساسٍ مَنْظورٍ عَقْلِيٍّ وَذِهْنِيٍّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16656, 'تِيوقْراطِيٌّ', 'تيوقراطي', 'منسوب', '', 'تيوقراطي', 'تقرط', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": نِظامُ سِياسِيٌّ يَسْتَمِدُّ قُوَّةَ حُكْمِهِ مِنَ اللَّهِ مُباشَرَةً لِتَدْعيمِ سُلْطَتِهِ الزَّمَنِيَّةِ وَتَصْريفِها."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16657, 'جَبْرِيٌّ', 'جبري', 'منسوب', 'جبر', 'جبري', 'جبر', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"جَبْرِيَّةٌ-جَبْرِيَّةٌ [ج ب ر]. ""مذْهَبُ الْجَبْرِيَّةِ"" : مَذْهَبٌ يَعْتَقِدُ أَصْحَابُهُ أَنَّ مَا يَحْدُثُ لِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16658, 'جَدَلِيٌّ', 'جدلي', 'منسوب', '', 'جدلي', 'جدل', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"""الْمَادِّيَّةُ الجَدَلِيَّةُ"" : فَلْسَفَةٌ اِقْتَرَنَتْ بِمَنْهَجِ هِيجل المِثَالِيِّ وَمَقُولاَتِ كَارْل مَارْكِس الَّتِي عُرِفَتْ بِالْمَادِّيَّةِ "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16659, 'جَاذِبِيَّةٌ', 'جاذبية', 'منسوب', 'جذب', 'جاذبية', 'جذبة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جَاذِبِيَّةٌ-جَاذِبِيَّةٌ [ج ذ ب]. 1.""تَتَمَتَّعُ بِجَاذِبِيَّةٍ هَائِلَةٍ"" : لَهَا جَمَالٌ جَذَّابٌ، فِتْنَةٌ خَلاَّبَةٌ. 2.""جَاذِبِيَّةُ الأَرْضِ"" : قُوَّةٌ فِي أَجْسَامِهَا تَجْعَلُهَا قَابِلَةً لِجَذْبِ شَيْءٍ إِلَيْهَا. 3."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16660, 'جُغْرَافِيَّةٌ', 'جغرافية', 'منسوب', '', 'جغرافية', 'جغرفة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": تَخْتَصُّ الجُغْرَافِيَّةُ بِوَصْفِ الأَرْضِ وَأَحْوَالِ الطَّقْسِ، وَطَبِيعَةِ البُلْدَانِ مِنْ جِبَالٍ وَسُهُولٍ وَبِحَارٍ وَغَابَاتٍ وَصَحَارٍ، وَأَحْوَالِ البَشَرِ. وَهِيَ أَقْسَامٌ. 1.""الجُغْرَافِيَّةُ الطَّبِيعِيَّةُ"" : عِلْمُ أَحْوَالِ الكُرَةِ الأَرْضِيَّةِ. 2.""الجُغْرَافِيَّةُ البَشَرِيَّةُ"" : عِلْمُ أَحْوَالِ السُّكَّانِ. 3.""الجُغْرَافِيَّةُ النَّبَاتِيَّةُ"" : فَرْعٌ مِنْ عِل"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16661, 'جَهْوَرِيٌّ', 'جهوري', 'منسوب', 'جهر', 'جهوري', 'جهر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"جَهْوَرِيٌّ-جَهْوَرِيٌّ، ةٌ [ج هـ ر]. 1.""عُرِفَ بِصَوْتِهِ الجَهْوَرِيِّ"" : بِصَوْتِهِ الْمُرْتَفِعِ العَالِي. 2.""لِيَقْرَأَ الوَلَدُ الجَهْوَرِيُّ النَّصَّ"" : الوَلَدُ العَالِي الصَّوْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16662, 'جَوّماَئِيَّةٌ', 'جومائية', 'منسوب', '', 'جوماءية', 'جمة', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"""تَمَّ صُنْعُ طَائِرَةٍ جَوّماَئِيَّةٍ"" : طَائِرَةٌ تَطِيرُ فِي الجَوِّ وَتَعْبُرُ المِيَاهَ، وَهِيَ كَلِمَةٌ مُرَكَّبَةٌ مِنَ الجَوِّ وَالْمَاءِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16663, 'جِيُولُوجِيَّةٌ', 'جيولوجية', 'منسوب', '', 'جيولوجية', 'جلجة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": عِلْمٌ يَبْحَثُ وَيَدْرُسُ طَبَقَاتِ الأَرْضِ وَتَكَوُّنَهَا وَالعَوَامِلَ الْمُؤَثِّرَةَ فِيهَا وَتَارِيخَهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16664, 'جِيُوفِيزِيَائي', 'جيوفيزيائي', 'منسوب', '', 'جيوفيزياءي', 'جفز', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": عِلْمٌ يَبْحَثُ وَيَدْرُسُ تَكْوِينَ الكُرَةِ الأَرْضِيَّةِ وَالحَرَكَاتِ الفَاعِلَةَ فِيهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16665, 'حَمَّامِيٌّ', 'حمامي', 'منسوب', 'حمم', 'حمامي', 'حمم', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"حَمَّامِيٌّ-حَمَّامِيٌّ، ةٌ [ح م م]. 1.: صاحِبُ الحمَّامِ. 2.: العاَمِلُ فِي الحَمَّامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16666, 'حانوتِيٌّ', 'حانوتي', 'منسوب', 'حنت', 'حانوتي', 'حنت', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"حانوتِيٌّ-حانوتِيٌّ [ح ن ت].: صاحِبُ الحانوتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16667, 'خَارِجِيٌّ', 'خارجي', 'منسوب', 'خرج', 'خارجي', 'خرج', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خَارِجِيَّةٌ-خَارِجِيَّةٌ [خ ر ج]. ""وَزِيرُ الْخَارِجِيَّةِ"" : الْمَسْؤُولُ فِي الْحُكُومَةِ عَنِ العَلاَقَاتِ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16668, 'خِلاَفِيٌّ', 'خلافي', 'منسوب', 'خلف', 'خلافي', 'خلف', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خِلاَفِيَّةٌ-خِلاَفِيَّةٌ [خ ل ف]. ""وَقَعَتْ بَيْنَهُمَا مَسَائِلُ خِلاَفِيَّةٌ"" : مَسَائِلُ مُخْتَلَفٌ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16669, 'خَيْرِيٌّ', 'خيري', 'منسوب', 'خير', 'خيري', 'خر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خَيْرِيَّةٌ-خَيْرِيَّةٌ [خ ي ر]. ""تَعَلَّمَ وَدَرَسَ فِي الخَيْرِيَّةِ"" : مُؤَسَّسَةٌ اِجْتِمَاعِيَّةٌ تَهْتَمُّ بِأَطْفَالِ الفُقَرَاءِ وَالْمُحْتَاجِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16670, 'دَجَاجِيُّ', 'دجاجي', 'منسوب', 'دجج', 'دجاجي', 'دجج', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"دَجَاجِيُّ-دَجَاجِيُّ [د ج ج]. 1.: بَائِعُ الدَّجَاجِ. 2. ""أسْوَدُ دَجَاجِيٌّ"" : شَدِيدُ السَّوَادِ، حَالِكٌ. ""لَيْلٌ دَجَاجِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16671, 'دِرامِيٌّ', 'درامي', 'منسوب', '', 'درامي', 'درم', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"""مَسْرَحِيَّةٌ دِرَامِيَّةٌ"" : مَسْرَحِيَّةٌ جَادَّةَ، تَجْمَعُ بَيْنَ الملْهَاةِ والْمَأْسَاةِ، تُعَالِجُ مُشْكِلَةً مِنْ مَشَاكِلِ الحَياةِ الوَاقِعِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16672, 'دِيالِكْتِيكِيٌّ', 'ديالكتيكي', 'منسوب', '', 'ديالكتيكي', 'دلكتك', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"1.: فَنُّ الجَدَلِ والحِوارِ. 2.: طَريقَةٌ مِنْ طُرُقِ التَّفْكيرِ، تَعْمَلُ على تَحْليلِ الواقِعِ والظَّواهِرِ الاجْتِماعِيَّةِ على أَساسِ تَناقُضاتِها، وَذَلِكَ مِنْ أَجْلِ تَجاوُزِها."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16673, 'دِينامِيٌّ', 'دينامي', 'منسوب', '', 'دينامي', 'دنم', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"""دينامِيَّةٌ مُتَجَدِّدَةٌ"" : طَاقَةٌ، قُوَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16674, 'ذاتِيٌّ', 'ذاتي', 'منسوب', '', 'ذاتي', 'ذت', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"""تَصْطَبِغُ أَحْكامُهُ بِالذَّاتِيَّةِ"" : أَي تَتَحَكَّمُ فيها اعْتِباراتٌ شَخْصِيَّةٌ، عَكْسَ الْمَوْضوعِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16675, 'رَجْعِيٌّ', 'رجعي', 'منسوب', 'رجع', 'رجعي', 'رجع', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"رَجْعِيٌّ-رَجْعِيٌّ [ر ج ع]. 1.""طَلاقٌ رَجْعِيٌّ"" : هُوَ مَا يَجُوزُ مَعَهُ لِلزَّوْجِ بِرَدِّ زَوْجَتِهِ إلَى بَيْتِ الزَّوْجِيَّةِ مِنْ غَيْرِ اسْتِئْنَافِ عَقْدٍ. 2.""قَانُونٌ لَهُ أَثَرٌ، مَفْعُولٌ رَجْعِيٌّ"" : أيْ يُطَبَّقُ عَلَى مَا قَبْلَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16676, 'رَسولِيٌّ', 'رسولي', 'منسوب', 'رسل', 'رسولي', 'رسل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"رَسولِيٌّ-رَسولِيٌّ، ةٌ [ر س ل]. ""قَرارٌ رَسولِيٌّ"" : ما يَصْدُرُ عَنِ الكُرْسِيِّ الرَّسولِيّ (الكنيسَةُ الكاثولِيكِيَّةُ) مِنْ أَوامِرَ وَإِرْشاداتٍ وَقَراراتٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16677, 'إِكْلِيرِيكِيٌّ', 'إكليريكي', 'منسوب', '', 'ءكليريكي', 'إكلرك', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": مَدْرَسَةٌ تُعَلِّمُ وتُفَقِّهُ وَتُربِّي الفِتْيانَ لِلارْتقَاءِ إلَى الكَهَنُوتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16678, 'حَنِيفِيٌّ', 'حنيفي', 'منسوب', 'حنف', 'حنيفي', 'حنف', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"حَنِيفِيَّةٌ-حَنِيفِيَّةٌ [ح ن ف]. ""مِلَّةٌ حَنِيفِيَّةٌ"" : مِلَّةٌ إِسْلامِيَّةٌ، كمَا تَعْنِي الحنِيفِيَّةُ الإِسْلامَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16679, 'دَادِيٌّ', 'دادي', 'منسوب', '', 'دادي', 'دد', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": تَيَّارٌ أدَبِيٌّ وَفَنِّيٌّ نَشَأ بَعْدَ الحَرْبِ العَالَمِيَّةِ الأولَى تَحَكَّمَتْ فيهِ نَزْعَةُ السُّخْطِ وَالثَّوْرَةِ عَلَى كُلِّ القِيَمِ السَّائِدَةِ وَمَا هُوَ مُتَعَارَفٌ عَلَيْهِ مِنْ أشْكَالِ التَّعْبِيرِ التَّقْلِيدِيَّةِ، وَجَاءتْ تَسْمِيَةُ هَذَا التَّيَّارِ مِنْ كَلِمَة دَادَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16680, 'دُهْرِيٌّ', 'دهري', 'منسوب', 'دهر', 'دهري', 'دهر', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"دُهْرِيَّةٌ-دُهْرِيَّةٌ [د هـ ر].: مَذْهَبُ الَّذينَ لا يُؤْمِنونَ بِالآخِرَةِ وَيَقولونَ بِبَقاءِ الدَّهْرِ أَبَداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16681, 'لاَمَرْكَزِيٌّ', 'لامركزي', 'منسوب', 'ركز', 'لامركزي', 'لمركز', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"لاَمَرْكَزِيَّةٌ-لاَمَرْكَزِيَّةٌ [ر ك ز]. : تَحْوِيلُ السُّلْطَةِ إِلَى الأَقَالِيمِ وَالوِلاَيَاتِ، وَجَعْلُهَا تَتَمَتَّعُ بِاسْتِقْلاَلِيَّةٍ فِي تَسْيِيرِ شُؤُونِهَا الْخَاصَّةِ عَكْسُ الْمَرْكَزِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16682, 'رِواقِيٌّ', 'رواقي', 'منسوب', 'روق', 'رواقي', 'رق', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"رِواقِيَّةٌ-رِواقِيَّةٌ [ر و ق]. : مَذْهَبٌ فَلْسَفِيٌّ، وَضَعَ قَواعِدَهُ وَأُصولَهُ الفَيْلَسوفُ اليونَانِيُّ زَينونٌ، وَكانَ يُعَلِّمُ أَتْباعَهُ في رِواقٍ، وَلِذَلِكَ سُمُّوا بِأَصْحابِ المِظَلَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16683, 'اِزْدِوَاجِيٌّ', 'ازدواجي', 'منسوب', 'زوج', 'ازدواجي', 'زدج', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"اِزْدِوَاجِيَّةٌ-اِزْدِوَاجِيَّةٌ [ز و ج]. 1.""اِزْدِوَاجِيَّةُ الشَّخْصِيَّةِ"" : أَي الظُّهُورُ بِمَظْهَرَيْنِ. 2.""اِزْدِوَاجِيَّةُ اللُّغَةِ"" : اِسْتِخْدَامُ لُغَتَيْنِ لِلتَّفَاهُمِ فِي بَعْضِ البُلْدَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16684, 'دَجُوجِيٌّ', 'دجوجي', 'منسوب', 'دجدج', 'دجوجي', 'دجج', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"دَجُوجِيٌّ-دَجُوجِيٌّ [د ج د ج]. 1. ""لَيْلٌ دَجُوجِيٌّ"" : داجٍ، مُظْلِمٌ، شَدِيدُ السَّوَادِ. 2. ""شَعْرٌ دَجُوجِيٌّ"" : أسْوَدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16685, 'سُرْيَالِيٌّ', 'سريالي', 'منسوب', '', 'سريالي', 'سرل', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": مَذْهَبٌ حَدِيثٌ فِي الأدَبِ وَالفَنِّ وَالرَّسْمِ يَعْتَمِدُ العَفْوِيَّةَ التِّلْقَائِيَّةَ الْمُطْلَقَةَ مُتَخَلِّصاً مِنْ قُيُودِ الْمَنْطِقِ وَالوَاقِعِيَّةِ، إذْ يَذْهَبُ رُوَّادُهُ إلَى مَا هُوَ "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16686, 'سَاعَاتِيٌّ', 'ساعاتي', 'منسوب', 'سع', 'ساعاتي', 'سعت', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"سَاعَاتِيٌّ-سَاعَاتِيٌّ [س ع]. ""أصْلَحَ السَّاعَاتِيُّ سَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16687, 'مَسْكُونِيٌّ', 'مسكوني', 'منسوب', 'سكن', 'مسكوني', 'مسكن', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مَسْكُونِيٌّ-مَسْكُونِيٌّ، ةٌ [س ك ن]. ""الْمَجْمَعُ الْمَسْكُونِيُّ"" : مَجْمَعٌ مَسِيحِيٌّ يَنْزَعُ إِلَى تَوْحِيدِ جَمِيعِ الكَنَائِسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16688, 'لاَسِلْكِيٌّ', 'لاسلكي', 'منسوب', 'سلك', 'لاسلكي', 'لسلك', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"لاَسِلْكِيٌّ-لاَسِلْكِيٌّ [س ل ك]. : جِهَازٌ لِلْإِرْسَالِ وَالْمُرَاسَلَةِ دُونَ الاعْتِمَادِ عَلَى الأَسْلاَكِ تَسْتَخْدِمُهُ إِدَارَةُ البَرِيدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16689, 'سُورِيالِيٌّ', 'سوريالي', 'منسوب', '', 'سوريالي', 'سرل', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ن. سُرْيالِيَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16690, 'سُوسْيولوجِيٌّ', 'سوسيولوجي', 'منسوب', '', 'سوسيولوجي', 'سسلج', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": عِلْمٌ يَدْرُسُ الْمُجْتَمعاتِ الإِنْسانِيَّةَ والْمَجْموعاتِ البَشَرِيَّةَ، وَظَواهِرَها الاجْتِماعِيَّةَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16691, 'مِسْعَرِيٌّ', 'مسعري', 'منسوب', 'سعر', 'مسعري', 'مسعر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مِسْعَرِيٌّ،  ةٌ - [س ع ر].: خَاصٌّ بِقِيَاسِ كَمِّيَّةِ الْحَرَارَةِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16692, 'سُفِسطَائِيٌّ', 'سفسطائي', 'منسوب', '', 'سفسطاءي', 'سفسط', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": تَيَّارٌ فِكْرِيٌّ يُونَانِيٌّ، نَشَأَ قَبْلَ سُقْرَاطَ فِي القَرْنِ الخَامِسِ قَبْلَ المِيلاَدِ، اِعْتَمَدَ فِي البِدَايَةِ رَفْضَ الْمُعْتَقَدَاتِ الدِّينِيَّةِ، وإبْعَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16693, 'شُرْطِيٌّ', 'شرطي', 'منسوب', 'شرط', 'شرطي', 'شرط', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":شُرْطَة"', '', '', 'ـو', '', '', '', '', '', '". ""شُرْطِيُّ الْمُرُورِ"": الْمُكَلَّفُ بِتَنْظِيمِ حَرَكَةِ السَّيْرِ فِي الشَّوَارِعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16694, 'شُرْطَة', 'شرطة', 'منسوب', '', 'شرطة', 'شرطة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16695, 'شِرَاعِيٌّ', 'شراعي', 'منسوب', 'شرع', 'شراعي', 'شرع', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شِرَاعِيَّةٌ - ج: ـات. [ش ر ع]. ""اِنْطَلَقَـتِ السُّفُـنُ الشِّرَاعِيَّةُ وَسَطَ الأَمْوَاجِ"": السُّفُنُ ذَاتُ القُلُوعِ (الأَشْرِعَةِ)، تَهُبُّ عَلَيْهَا الرِّيَاحُ فَتُحَرِّكُهَا لِتَمْخُرَ عُبابَ البَحْرَ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16696, 'شَفَوِيٌّ', 'شفوي', 'منسوب', '', 'شفوي', 'شف', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شَفَوِيَّةٌ-شَفَوِيَّةٌ (مو).: آلَةٌ مُوسِيقِيَّةٌ صَغِيرَةٌ يُنْفَخُ فيها بالشَّفَتَيْنِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16697, 'صَيْرَفِيٌّ', 'صيرفي', 'منسوب', 'صرف', 'صيرفي', 'صرف', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":صَيَارِفَةٌ"', '', '', 'ـو', '', '', '', '', '', '". ""حَوَّلَ مَا مَعَهُ مِنْ عُمْلَةٍ عِنْدَ الصَّيْرَفِيِّ"" : مُحَوِّلُ النُّقُودِ بِنُقُودٍ غَيْرِهَا. ""يَزِنُ كَمَا يَزِنُ الصَّيْرَفِيُّ دَنَانِيرَهُ"". (طه حسين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16698, 'صَيَارِفَةٌ', 'صيارفة', 'منسوب', '', 'صيارفة', 'صرفة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16699, 'صَلِيبِيٌّ', 'صليبي', 'منسوب', 'صلب', 'صليبي', 'صلب', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"صَلِيبِيَّةٌ-صَلِيبِيَّةٌ [ص ل ب]. ""الْحُرُوبُ الصَّلِيبِيَّةُ"" : هِيَ الْحُرُوبُ الَّتِي نَظَّمَهَا الْمَسِيحِيُّونَ الآتُونَ مِنْ أُورُوبَّا ضِدَّ الْمَوَاقِعِ الْمُقَدَّسَةِ فِي فِلَسْطِينَ مِنْ 1096 إِلَى 1291، وَسُمِّيَتْ بِذَلِكَ لِحَمْلِهِمْ إِشَارَةَ الصَّلِيبِ شِعَارٌ لَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16700, 'مَصْلِيٌّ', 'مصلي', 'منسوب', 'صلي', 'مصلي', 'مصل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَصْلِيٌّ-مَصْلِيٌّ [ص ل ي]. ""لَحْمٌ مَصْلِيٌّ"" : لَحْمٌ مَشْوِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16701, 'صَيْدَلِيٌّ', 'صيدلي', 'منسوب', 'صيدل', 'صيدلي', 'صدل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":صيادلة"', '', '', 'ـو', '', '', '', '', '', '". ""فُتِحَتْ صَيْدَلِيَّةٌ جَدِيدَةٌ فِي الْحَيِّ"" : مَحَلُّ بَيْعِ الأَدْوِيَةِ وَالْعَقَاقِيرِ وَتَحْضِيرِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16702, 'صيادلة', 'صيادلة', 'منسوب', '', 'صيادلة', 'صدلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16703, 'إِضافِي', 'إضافي', 'منسوب', 'ضيف', 'ءضافي', 'إضف', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"إِضافِي-إِضافِيٌّ، ةٌ [ض ي ف]. ""عَمَلٌ إِضافِيٌّ"" : زائِدٌ عَلَى مَا هُوَ مُعْتادٌ وَمَحْدُودٌ. ""كان الْمُعَلِّمُ يُعْطِينا ساعاتٍ إِضافِيَّةً في مادَّةِ الرِّيَاضِيَّاتِ"" ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16704, 'إِطْفَائِيٌّ', 'إطفائي', 'منسوب', 'طفأ', 'ءطفاءي', 'إطف', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"إِطْفَائِيٌّ-إِطْفَائِيٌّ [ط ف أ]. ""سَارَعَ الإِطْفَائِيُّ إِلَى مَكَانِ الحَرِيقِ"": أَحَدُ رِجَالِ الإِطْفَائِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16705, 'عِبْرِيٌّ', 'عبري', 'منسوب', 'عبر', 'عبري', 'عبر', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عِبْرِيٌّ-عِبْرِيٌّ، ةٌ [ع ب ر]. : عِبْرَانِيٌّ، ةٌ. 1.""رَجُلٌ عِبْرِيٌّ"" : يَهُودِيٌّ. 2.""اللُّغَةُ الْعِبْرِيَّةُ"" : لُغَةُ الْيَهُودِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16706, 'عَبْشَمِيٌّ', 'عبشمي', 'منسوب', '', 'عبشمي', 'عبشم', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '": كَلِمَةٌ مَنْحُوتَةٌ مِنْ عَبْدِ شَمْسٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16707, 'عَبْقَسِيٌّ', 'عبقسي', 'منسوب', '', 'عبقسي', 'عبقس', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '": كَلِمَةٌ مَنْحُوتَةٌ مِنْ عَبْدِ قَيْسٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16708, 'عَرْبَانِيٌّ', 'عرباني', 'منسوب', 'عرب', 'عرباني', 'عربن', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عَرْبَانِيٌّ-عَرْبَانِيٌّ [ع ر ب]. ""بَاحِثٌ عَرْبَانِيٌّ"" : يَتَكَلَّمُ الْعَرَبِيَّةَ وَلَيْسَ عَرَبِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16709, 'عُشَارِيٌّ', 'عشاري', 'منسوب', 'عشر', 'عشاري', 'عشر', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عُشَارِيٌّ-عُشَارِيٌّ [ع ش ر]. : هُوَ مَا بَلَغَ العَشَرَةَ مِنْ كُلِّ شَيْءٍ. 1.""عُشَارِيُّ الأَوْجُهِ"" : هُوَ مُجَسَّمٌ ذُو عَشَرَةِ سُطُوحٍ أَوْ أَوْجُهٍ أَوْ قَوَاعِدَ. 2.""عُشَارِيُّ الضُّلُوعِ"" : هُوَ مُضَلَّعٌ هَنْدَسِيٌّ ذُو عَشَرَةِ ضُلُوعٍ. 3.""ثَوْبٌ عُشَارِيٌّ"" : طُولُهُ عَشْرُ أَذْرُعٍ. 4.""وَلَدٌ عُشَارِيٌّ"" : اِبْنُ عَشْرِ سِنِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16710, 'تَعَاوُنِيٌّ', 'تعاوني', 'منسوب', 'عون', 'تعاوني', 'تعن', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". 1.""تَعَاوُنِيَّةٌ سَكَنِيَّةٌ"" : جَمْعِيَّةٌ لأَفْرَادِهَا مصالِحُ مُشْتَرَكَةٌ لإِنْجَازِ عَمَلٍ مَّا. 2.""تَعَاوُنِيَّةُ الْمَوَادِّ الغِذَائِيَّةِ"" : مَخْزَنٌ لِلْمَوَادِّ الغِذَائِيَّةِ وَغَيْرِهَا خَاصٌّ بِأَفْرَادٍ تَجْمَعُهُمْ مِهْنَةٌ وَاحِدَةُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16711, 'فَاشِيٌّ', 'فاشي', 'منسوب', '', 'فاشي', 'فش', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ن. فَاشِسْتِيَّةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16712, 'فَارِسِيٌّ', 'فارسي', 'منسوب', 'فرس', 'فارسي', 'فرس', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"فَارِسِيَّةٌ-فَارِسِيَّةٌ [ف ر س]. ""اللُّغَةُ الفَارِس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16713, 'فِطْرِيٌّ', 'فطري', 'منسوب', 'فطر', 'فطري', 'فطر', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"فِطْرِيَّةٌ-فِطْرِيَّةٌ [ف ط ر]. : اِعْتِبَارُ أَفْكَارِ الإِنْسَانِ وَتَصَرُّفَاتِهِ جِبِلِّيَّةً وَمَوْجُودَةً فِي النَّفْسِ قَبْلَ التَّلْقِينِ وَالتَّعَلُّمِ وَالتَّجْرِبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16714, 'فَعَّالِيٌّ', 'فعالي', 'منسوب', 'فعل', 'فعالي', 'فعل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""فَعَّالِيَّةُ دَوَاءٍ"" : تَأْثِيرُهُ وَقُوَّةُ مَفْعُولِهِ. 2.""فَعَّالِيَّا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16715, 'فِيزيُولُوجِيٌّ', 'فيزيولوجي', 'منسوب', '', 'فيزيولوجي', 'فزلج', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '": عِلْمٌ يَبْحَثُ وَيَدْرُسُ وَظَائِفَ الأَعْضَاءِ فِي الْحَيَوَانِ وَالنَّبَاتِ، تَتَشَكَّلُ مِنْ خِلاَلِهَا ظَوَاهِرُ الْحَيَاةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16716, 'قَبَّانِيٌّ', 'قباني', 'منسوب', 'قبن', 'قباني', 'قبن', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"قَبَّانِيٌّ-قَبَّانِيٌّ [ق ب ن].: صَاحِبُ القَبَّانِ، أَيِ الْوَزَّانُ بِالْقَبَّانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16717, 'قُطَامِيٌّ', 'قطامي', 'منسوب', 'قطم', 'قطامي', 'قطم', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"قُطَامِيٌّ - [ق ط م]. 1. : صَقْرٌ. ن. صَقْرٌ. 2.""نَبِيذٌ قُطَامِيٌّ"" : شَدِيدٌ، قَوِيٌّ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16718, 'كُحْلِيٌّ', 'كحلي', 'منسوب', 'كحل', 'كحلي', 'كحل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"كُحْلِيٌّ-كُحْلِيٌّ، ةٌ [ك ح ل]. 1. : مَنْ يَصْنَعُ الكُحْلَ. 2.""لَوْنٌ كُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16719, 'كُرَاعِيٌّ', 'كراعي', 'منسوب', 'كرع', 'كراعي', 'كرع', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"كُرَاعِيٌّ-كُرَاعِيٌّ [ك ر ع]. : بَائِعُ الأَكَارِعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16720, 'كِلاَسِيكِيٌّ', 'كلاسيكي', 'منسوب', '', 'كلاسيكي', 'كلسك', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"1. : مَذْهَبٌ أَدَبِيٌّ وَفَنِّيٌّ نَشَأَ فِي أُورُوبَّا، يُقْصَدُ بِهِ مَجْمُوعُ الآثَارِ الأَدَبِيَّةِ وَالفَنِّيَّةِ الَّتِي تَعُودُ إِلَى العَصْرِ الرُّومَانِيِّ وَالإِغْرِيقِيِّ، مِنْها اسْتَوْحَى أُدَبَاءُ عَصْرِ النَّهْضَةِ (القَرْنُ 16،18) وَفَنَّانُوها نَمَاذِجَهُمْ وَأَغْرَاضَهُمْ وَأَنْوَاعَهُمْ وَأَشْكَالَ تَعَابِيرِهِمْ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16721, 'كَهْرَبَائِيٌّ', 'كهربائي', 'منسوب', 'كهرب', 'كهرباءي', 'كهرب', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"كَهْرَبَائِيَّةٌ-كَهْرَبَائِيَّةٌ [ك هـ ر ب]. ""الطَّاقَةُ الكَهْرَبَائ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16722, 'كَهْرَمَائِيٌّ', 'كهرمائي', 'منسوب', '', 'كهرماءي', 'كهرم', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '": مَا يَخْتَصُّ بِإِنْتَاجِ الطَّاقَةِ الكَهْرَبَائِيَّةِ الْمُوَلَّدَةِ مِنْ دَفْعِ الْمَاءِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16723, 'لِحْيَانِيٌّ', 'لحياني', 'منسوب', 'لحي', 'لحياني', 'لحن', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '""', '', '', '', '', '', '', '', '', '"لِحْيَانِيٌّ - [ل ح ي]. ""رَجُلٌ لِحْيَانِيٌّ"" : طَوِيلُ اللِّحْيَةِ، أَوْ عَظِيمُهَا. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16724, 'يَلْمَعِيٌّ', 'يلمعي', 'منسوب', 'لمع', 'يلمعي', 'لمع', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"يَلْمَعِيٌّ-يَلْمَعِيٌّ، ةٌ [ل م ع]. 1.""وَلدٌ يَلْمَعِيٌّ"" : ذَكِيٌّ، شَدِيدُ الذَّكَاءِ . 2.""رَجُلٌ يَلْمَعِيٌّ"" : يَخْلِطُ الصِّدْقَ بِالكَذِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16725, 'تَمْثيلِيٌّ', 'تمثيلي', 'منسوب', 'مثل', 'تمثيلي', 'تمثل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَمْثيلِيَّةٌ-تَمْثيلِيَّةٌ [م ث ل] (فن). ""قَدَّمَتِ الفِرْقَةُ تَمْثِيليَّةً بِعُنْوانِ(الكَرَاسِيّ)"" : مَسْرَحِيَّةً تُمَثَّلُ على الْمَسْرَحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16726, 'مُخَاطِيّ', 'مخاطي', 'منسوب', 'مخط', 'مخاطي', 'مخط', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مُخَاطِيّ-مُخَاطِيّ [م خ ط].: مَا كَانَ كَالْمُخاطِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16727, 'نَازِيٌّ', 'نازي', 'منسوب', '', 'نازي', 'نز', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '": (سيا). : الْمُنْتَمِي إِلَى النَّازِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16728, 'إِنْتاجِيٌّ', 'إنتاجي', 'منسوب', 'نتج', 'ءنتاجي', 'إنتج', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"إِنْتاجِيَّةٌ-إِنْتاجِيَّةٌ [ن ت ج]. ""إِنْتاجِيَّةُ الْمَعْمَلِ"" : العائِدُ مِنْ تِجارَةِ سِلْعَةٍ أَوْ خِدْمَةٍ في فَتْرَةٍ مُعَيَّنَةٍ، وَيَتِمُّ تَقْديرُها بِوَحَداتٍ عَيْنِيَّةٍ أَوْ نَقْدِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16729, 'نَشَاوِيٌّ', 'نشاوي', 'منسوب', 'نشو', 'نشاوي', 'نش', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"نَشَاوِيَّةٌ-نَشَاوِيَّةٌ [ن ش و]. : طَعَامٌ يُصْنَعُ مِنَ النَّشَا وَالسُّكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16730, 'نَظَّارَاتِيٌّ', 'نظاراتي', 'منسوب', 'نظر', 'نظاراتي', 'نظرت', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"نَظَّارَاتِيٌّ-نَظَّارَاتِيٌّ [ن ظ ر]. : صَانِعُ، بَائِعُ النَّظَّارَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16731, 'لاَنِهَائِيٌّ', 'لانهائي', 'منسوب', 'نهي', 'لانهاءي', 'لنه', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"لاَنِهَائِيٌّ-لاَنِهَائِيٌّ [ن هـ ي]. ""فَضَاءٌ لاَنِهَائِيٌّ"" : لاَ مَحْدُودٌ، لاَ نِهَايَةَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16732, 'هُلاَمِيٌّ', 'هلامي', 'منسوب', 'هلم', 'هلامي', 'هلم', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '"هُلاَمِيٌّ-هُلاَمِيٌّ، ةٌ [هـ ل م]. 1.""مَادَّةٌ هُلاَمِيَّةٌ"" : جِيلاَتِينِيَّةٌ، أَيْ مُخَاطِيَّةٌ. 2.""مَرَقٌ هُلاَمِيٌّ"" : مُتَجَمِّدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16733, 'يَهُودِيٌّ', 'يهودي', 'منسوب', 'هود', 'يهودي', 'هد', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":يهود"', '', '', '', '', '', '', '', '', '"يَهُودِيَّةٌ-يَهُودِيَّةٌ [هـ و د]. : شَريعَةُ الْيَهُودِ وَهِيَ تَتَضَمَّنُ التَّعَالِيمَ وَالْوَصَايَا الَّتِي جَاءَ بِهَا النَّبِيُّ مُوسَى عَلَيْهِ السَّلاَمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16734, 'يهود', 'يهود', 'منسوب', '', 'يهود', 'هد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16735, 'يَائِيٌ', 'يائي', 'منسوب', '', 'ياءي', '', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '', '', '', '', '', '', '', '', '', '": نِسْبَةٌ إِلَى الْيَاءِ. ""قَصِيدَةٌ يَائِيَّةٌ"" : أَيْ قَافِيَتُهَا يَاءٌ. "', ':لا جذر:لا مفرد');
