INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16742, 'أُمِّيٌّ', 'أمي', 'منسوب', 'أمم', 'ءمي', 'م', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '". ""كانَ أُمِّيّاً"" : أَيْ لاَ يَعْرِفُ الكِتابَةَ وَلاَ القِراءةَ.الجمعة آية 2هُوَ الَّذِي بَعَثَ في الأُمِّيِّينَ رَسولاً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16743, 'حَرامِيٌّ', 'حرامي', 'منسوب', 'حرم', 'حرامي', 'حرم', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":حَرامِيَّة"', '', '', 'ـو', '', '', '', '', '', '". ""أَلْقَى القَبْضَ عَلى الحَرامِيَّ"" : اللِّصُّ لأَنَّهُ يَفْعَلُ الحَرامَ."', '');
