INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16745, 'حَبَشِيٌّ', 'حبشي', 'منسوب', '', 'حبشي', 'حبش', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16746, 'عُضْوِيَّةٌ', 'عضوية', 'منسوب', 'عضو', 'عضوية', 'عضة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عُضْوِيَّةٌ-عُضْوِيَّةٌ [ع ض و] (مص صِنَاعِيٌّ). ""قُبِلَتْ عُضْوِيَّتُهُ فِي الْجَمْعِيَّةِ"" : أُعْطِيَتْ لَهُ صِفَةُ العُضْوِ فِي الْجَمْعِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16747, 'مِدْفَعِيَّةٌ', 'مدفعية', 'منسوب', 'دفع', 'مدفعية', 'مدفعة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مِدْفَعِيَّةٌ-مِدْفَعِيَّةٌ [د ف ع] (مص. صِنَاعِـيٌّ). ""مِدْفَعِـيَّـةُ الْمَيْدَانِ"":مَجْمُوعَةُ الْمَدَافِعِ الْمُخْتَصَّةِ بِالْمَيْدَانِ. ""الْمِدْفَعِيَّةُ الْمُضَادَّةُ لِلطَّائِرَاتِ"" ""المِدْفَعِيَّةُ الْمُضَادَّةُ لِلصَّوَارِيخِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16748, 'أَرِستقراطِيَّةٌ', 'أرستقراطية', 'منسوب', '', 'ءرستقراطية', 'رستقرطة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": (مص. صِنَاعِيٌّ). ""يَنْتَمِي إلَى الطَّبَقَةِ الأرِسْتُقْرَطِيَّةِ"" : طَبَقَةٌ عُلْيَا فِي الْمُجْتَمَعِ، يَمْلِكُ أَفْرَادُهَا الشَّرَفَ وَالجَاهَ والسُّلْطَةَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16749, 'أُوتُوقْرَاطِيَّةٌ', 'أوتوقراطية', 'منسوب', '', 'ءوتوقراطية', 'تقرطة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"أُوتُوقْرَاطِيَّةٌ-أُوتُوقْرَاطِيَّةٌ (مص. صِنَاعِيٌّ). ""السُّلْطَةُ الأتُوقْرَاطِيَّةُ"": السُّلْطَةُ الْمُسْتَبِدَّةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16750, 'جَاسُوسِيَّةٌ', 'جاسوسية', 'منسوب', 'جسس', 'جاسوسية', 'جسسة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"جَاسُوسِيَّةٌ-جَاسُوسِيَّةٌ [ج س س] (مص. صِنَاعِيٌّ).: مِهْنَةُ الجَوَاسِيسِ، أَيْ ت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16751, 'جُمْهُورِيَّةٌ', 'جمهورية', 'منسوب', 'جمهر', 'جمهورية', 'جمهرة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مص. صِنَاعِيٌّ).: نِظَامُ حُكْمٍ يُنْتَخَبُ فِيهِ رَئِيسُهُ لِمُدَّةٍ مُعَيَّنَةٍ كَمَا يُحَدِّدُهَا دُسْتُورُ البِلاَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16752, 'مَحَلِّيَّةٌ', 'محلية', 'منسوب', 'حلل', 'محلية', 'محلة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مَحَلِّيَّةٌ-مَحَلِّيَّةٌ [ح ل ل] (مص. صِنَاعِيٌّ). ""تَجَاوَزَ مَنْطِقَ الْمَحَلِّيَّةِ إِلَى العَالَمِيَّةِ"" : مَنْطِقَ الإقْلِيمِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16753, 'دِبْلُومَاسِيَّةٌ', 'دبلوماسية', 'منسوب', '', 'دبلوماسية', 'دبلمسة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"دِبْلُومَاسِيَّةٌ-دِبْلُومَاسِيَّةٌ (مص. صِنَاعِيٌّ). : صِفَةٌ تَخُصُّ التَّمْثِيلَ السِّيَاسِيَّ لِلْبِلاَدِ وَتَصْرِيفَ شُؤُونِهَا الخَارِجِيَّةِ لَدَى الدُّوَلِ الأجْنَبِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16754, 'مُدِيرِيَّةٌ', 'مديرية', 'منسوب', 'دور', 'مديرية', 'مدرة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِنَاعِيٌّ): مُؤَسَّسَةٌ إِدَارِيَّةٌ حُكُومِيَّةٌ خَاضِعَةٌ لِسُلْطَةِ مُدِيرٍ عَامٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16755, 'رَاديكَالِيَّةٌ', 'راديكالية', 'منسوب', '', 'راديكالية', 'ردكلة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"رَاديكَالِيَّةٌ-رَاديكَالِيَّةٌ (فل) (مص. صِنَاعِيٌّ). : مَذْهَبٌ فَلْسَفِيٌّ وسِيَاسيٌّ قَائِمٌ على اللِّيبْرالِيَّةِ الاقْتِصادِيَّةِ والْمُبَادَرَةِ الفَرْدِيَّةِ وَالعَقْلانِيَّةِ، يَدْعُو إِلَى الإِصْلاحِ السِّيَاسِيِّ الجِذْرِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16756, 'رَأْسُمَاليَّةٌ', 'رأسمالية', 'منسوب', 'رأس،مول', 'رءسمالية', 'رسملة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"رَأْسُمَاليَّةٌ-رَأْسُمَاليَّةٌ [ر أ س، م و ل] (مص. صِنَاعِيٌّ). : نِظَامٌ اِقْتِصَادِيٌّ يَقُومُ عَلَى اس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16757, 'مَرْكَزِيَّةٌ', 'مركزية', 'منسوب', 'ركز', 'مركزية', 'مركزة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَرْكَزِيَّةٌ-مَرْكَزِيَّةٌ [ر ك ز] (مص. صِنَاعِيٌّ). 1.""تَعْتَمِدُ الدَّوْلَةُ سِيَاسَةَ الْمَرْكَزِيَّةِ"" : اِعْتِمَادُ تَمَرْكُزِ السُّلَطِ فِي مَرْكَزٍ وَاحِدٍ وَإِخْضَاعُهَا لَهُ. 2.""اِعْتِمَادُ اللاَّمَرْكَزِيَّةِ فِي نِظَامِ الحُكْمِ"" : اِعْتِمَادُ نَقْلِ الكَثِيرِ مِنَ السُّلَطِ إِلَى الجِهَاتِ التَّابِعَةِ لِلْمَرْكَزِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16758, 'رَهْبانِيَّةٌ', 'رهبانية', 'منسوب', 'رهب', 'رهبانية', 'رهبنة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"رَهْبانِيَّةٌ-رَهْبانِيَّةٌ [ر هـ ب] (مص. صِنَاعِيٌّ). ""دَخَلَ في الرَّهْبانِيَّةِ"" : الزُّهْدُ في الدُّنْيا والاِنْقِطاعُ عَنْ ملَذَّاتِها وَعَنِ الزَّواجِ. ""لاَ رَهْبانِيَّةَ في الإِسْلامِ"" الحديد آية 27 وَرَهْبانِيَّةً ابْتَدَعوها ما كَتَبْناها عَلَيْهِمْ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16759, 'سَلْبِيَّةٌ', 'سلبية', 'منسوب', 'سلب', 'سلبية', 'سلبة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مص. صِنَاعِيٌّ). : نِظامٌ فلْسَفِيٌّ قائِمٌ على رَفْضِ كُلِّ حَقيقَةٍ أَوْ مُعْتَقَدٍ، كَما يَعْنِي التَّرَدُّدَ والإِضْرابَ عَنِ العَمَلِ وَعَدَمَ التَّعاوُنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16760, 'شَخْصِيَّةٌ', 'شخصية', 'منسوب', 'شخص', 'شخصية', 'شخصة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَخْصِيَّةٌ-شَخْصِيَّةٌ [ش خ ص] (مص. صِنَاعِيٌّ). الْمُخْتَصُّ بِالشَّخْصِ، وَالْمُمَيِّزُ لِخَصَائِصِهِ الجِسْمِيَّةِ وَالفِعْلِيَّةِ وَالعَاطِفِيَّةِ. 1.""زَارَتِ الْمَعْهَدَ شَخْصِيَّةٌ بَارِزَةٌ"" : إنْسَانٌ لَهُ وُجُودٌ فِعْلِيٌّ فِي مَجَالٍ مَّا، يَحْتَلُّ مَنْصِباً عَالِياً وَيَتَمَتَّعُ بِنُفُوذٍ. 2.""اِسْتَقْبَلَ الوَزِيرُ الوَفْدَ بِصِفَتِهِ الشَّخْصِيَّةِ"" : أَيْ لَيْسَ بِصِفَتِهِ الحُكُومِيَّةِ الرَّسْمِيَّةِ. 3.""قَانُونُ الأَحْوَالِ الشَّخْصِيَّةِ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16761, 'شَاعِريَّةٌ', 'شاعرية', 'منسوب', 'شعر', 'شاعرية', 'شعرة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَاعِريَّةٌ-شَاعِريَّةٌ [ش ع ر] (مص. صِنَاعِيٌّ). ""يَتَمتَّعُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16762, 'شَهْرِيَّةٌ', 'شهرية', 'منسوب', 'شهر', 'شهرية', 'شهرة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَهْرِيَّةٌ-شَهْرِيَّةٌ [ش هـ ر] (مص. صِنَاعِيٌّ). ""تَسَلَّمَ شَهْرِيَّتَهُ"": رَاتِبَهُ الشَّهْرِيَّ. ""قَالَ لِي: إِنَّ أُجْرَتَهُ الشَّهْرِيَّةَ لاَ تَكْفِيهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16763, 'شُيُوعِيَّةٌ', 'شيوعية', 'منسوب', 'شيع', 'شيوعية', 'شعة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"شُيُوعِيَّةٌ-شُيُوعِيَّةٌ [ش ي ع] (مص. صِنَاعِيٌّ) (سيا).: مَذْهَبٌ اِقْتِصَادِيٌّ وَاجْتِمَاعِيٌّ قَائِمٌ عَلَى جَعْلِ وَسَائِلِ الإِنْتَاجِ مُشْتَرَكَةً"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16764, 'صُوفِيَّةٌ', 'صوفية', 'منسوب', 'صوف', 'صوفية', 'صفة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"صُوفِيَّةٌ-صُوفِيَّةٌ [ص و ف] (مص. صِنَاعِيٌّ). ""كَانَ رَحِمَهُ اللَّهُ مِنْ رِجَالِ الصُّوفِيَّةِ"" : مِنْ رِجَالِ التَّعَبُّدِ وَالزُّهْدِ وَالْخَلْوَةِ للِنُّسْكِ وَالتَّقَشُّفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16765, 'طُوبَاوِيَّةٌ', 'طوباوية', 'منسوب', 'طوب', 'طوباوية', 'طبة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"طُوبَاوِيَّةٌ-طُوبَاوِيَّةٌ، طُوبَائِيَّةٌ [ط و ب] (مص. صِنَاعِيٌّ). ""يَدْعُو إِلَى اشْتِرَاكِيَّةٍ طُوبَائِيَّةٍ"" : الاشْتِرَاكِيَّةُ الَّتِي تَحْلُمُ بِمُجْتَمَعٍ خَالٍ مِنَ الصِّرَاعِ وَتَسْعَى إلى تَحْقيقِ مُثُلٍ عُلْيا بَعِيدَةٍ عَنِ الوَاقِعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16766, 'تَعْبِيرِيَّةٌ', 'تعبيرية', 'منسوب', 'عبر', 'تعبيرية', 'تعبرة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"تَعْبِيرِيَّةٌ-تَعْبِيرِيَّةٌ [ع ب ر] (مص. صِنَاعِيٌّ).: مَذْهَبٌ مِنْ مَذَاهِبِ الفَنِّ وَالأَدَبِ وَبِالأَخَصِّ فِي مَجَالِ الرَّسْمِ، ظَهَرَ فِي أُورُوبَّا فِي بِدَايَةِ هَذ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16767, 'مَعْلُومَاتِيَّةٌ', 'معلوماتية', 'منسوب', 'علم', 'معلوماتية', 'معلمتة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِنَاعِيٌّ). ""أَصْبَحَتِ الْمَعْلُومِيَّاتُ تَحْتَلُّ مَكَاناً شَاسِعاً فِي العَصْرِ الْحَدِيثِ"" : عِلْمٌ يَهْتَمُّ بِتَحْلِيلِ الْمَعْلُومَاتِ آلِيّاً بِوَاسِطَةِ الْحَوَاسِيبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16768, 'فَاشِسْتِيَّةٌ', 'فاشستية', 'منسوب', '', 'فاشستية', 'فشستة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"فَاشِسْتِيَّةٌ-فَاشِسْتِيَّةٌ (سيا) (مص. صِنَاعِيٌّ). : نِظَامٌ قَائِمٌ عَلَى اسْتِبْدَادِ السُّلْطَةِ بِالْحُكْمِ وَالتَّعَصُّبِ الْقَوْمِيِّ وَالتَّطَرُّفِ الْعِرْقِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16769, 'تَقَدُّمِيَّةٌ', 'تقدمية', 'منسوب', 'قدم', 'تقدمية', 'تقدمة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"تَقَدُّمِيَّةٌ-تَقَدُّمِيَّةٌ [ق د م] (مص. صِنَاعِيٌّ). ""عَبَّرَ عن أَفْكارِهِ التَّقَدُّم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16770, 'إقْطَاعِيَّةٌ', 'إقطاعية', 'منسوب', 'قطع', 'ءقطاعية', 'إقطعة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"إقْطَاعِيَّةٌ-إقْطَاعِيَّةٌ [ق ط ع] (مص. صِنَاعِيٌّ).: نِظَامٌ قَائِمٌ عَلَى الإقْطَاعِ، وَذَلِكَ بِتَمْلِيكِ قِطَعٍ مِنَ الأرْضِ لِفَرْدٍ أَوْ عَائِلَةٍ تَسْتَغِلُّهَا اسْتِغْلاَلاً مُطْلَقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16771, 'قَوْمِيَّةٌ', 'قومية', 'منسوب', 'قوم', 'قومية', 'قمة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"قَوْمِيَّةٌ-قَوْمِيَّةٌ [ق و م] (مص. صِنَاعِيٌّ). ""تَشُدُّهُمْ رَوَابِطُ القَوْمِيَّةِ"" : عَقِيدَةٌ سِيَاسِيَّةٌ تَرْمِي إِلَى خَلْقِ وَعْيٍ بِالْمَصَالِحِ الْمُشْتَرَكَةِ، وَالدِّفَاعِ وَالحَمِيَّةِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16772, 'كَاثُولِيكِيَّةٌ', 'كاثوليكية', 'منسوب', '', 'كاثوليكية', 'كثلكة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"كَاثُولِيكِيَّةٌ-كَاثُولِيكِيَّةٌ (مص. صِنَاعِيٌّ). : مَذْهَبٌ يَضُمُّ مَجْمُوعَ التَّعَالِيمِ الْمَسِيحِيَّةِ الَّتِي تَدِينُ بِهَا الكَنِيسَةُ وَعَلَى رَأْسِهَا الْحَبْرُ الأَعْظَمُ : البَابَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16773, 'كَشْفِيَّةٌ', 'كشفية', 'منسوب', 'كشف', 'كشفية', 'كشفة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"كَشْفِيَّةٌ-كَشْفِيَّةٌ [ك ش ف] (مص. صِنَاعِيٌّ). : حَرَكَةٌ تَهْذِيبِيَّةٌ عَالَمِيَّةٌ أَنْشَأَهَا الإِنْجِلِيزِي بَادْن بَاوْل سَنَةَ 1909، تَهْدِفُ إِلَى "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16774, 'لاَهُوتِيَّةٌ', 'لاهوتية', 'منسوب', '', 'لاهوتية', 'لهتة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"لاَهُوتِيَّةٌ-لاَهُوتِيَّةٌ (مص. صِنَاعِيٌّ). : عِلْمُ العَقَائِدِ الْمُتَعَلِّقَةِ بِاللَّهِ تَعَالَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16775, 'لُصُوصِيَّةٌ', 'لصوصية', 'منسوب', 'لصص', 'لصوصية', 'لصصة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"لُصُوصِيَّةٌ-لُصُوصِيَّةٌ [ل ص ص] (مص. صِنَاعِيٌّ). ""يَحْتَرِفُ اللُّصُوصِيَّةَ"" : عَمَلُ اللِّصّ، أَيِ السَّرِقَةُ وَالاخْتِلاَسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16776, 'مِثَالِيَّةٌ', 'مثالية', 'منسوب', 'مثل', 'مثالية', 'مثلة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مِثَالِيَّةٌ-مِثَالِيَّةٌ [م ث ل] (مص. صِنَاعِيٌّ).: فِي الفَلْسَفَةِ مَذْهَبٌ فَلْسَفِيٌّ يَجْعَلُ الفِكْرَ خَاضِعاً لِتَصَوُّرٍ ذِهْنِيٍّ وَحَقِيقَةٍ عُلْيَا فَوْقَ كُلِّ مَا هُوَ مَوْضُوعِيٌّ وَمَادِّيٌّ. فِي الفَنِّ وَالأَدَبِ هُوَ تَمَثُّلُ الأَشْيَاءِ نَمَاذِجَ تَرْمُزُ إِلَى قُوَّةِ جَوْهَرِهَا فِي الأَخْلاَقِ، الدَّعْوَةُ إِلَى الكَمَالِ الإِنْسَانِيِّ وَجَعْلِ الإِنْسَانِ غَايَةً أَخْلاَقِيَّةً نَمُوذَجِيَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16777, 'مَجُوسِيَّةٌ', 'مجوسية', 'منسوب', 'مجس', 'مجوسية', 'مجسة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مَجُوسِيَّةٌ-مَجُوسِيَّةٌ [م ج س] (مص. صِنَاعِيٌّ).: عَقِيدَةُ الْمَجُوسِ، وَهِيَ عِبادَةُ النَّارِ وَالكَوَاكِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16778, 'مَادِّيَّةٌ', 'مادية', 'منسوب', 'مدد', 'مادية', 'مدة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مَادِّيَّةٌ-مَادِّيَّةٌ [م د د] (مص. صِنَاعِيٌّ). ""مَذْهَبُ الْمَادِّيَّةِ"" : مَذْهَبٌ فَلْسَفِيٌّ يَرْتَكِزُ عَلَى أَنَّ الْمَادَّةَ وَحْدَهَا هِيَ وَاقِعُ الأَشْيَاءِ وَيُنْكِرُ وُجُودَ الرُّوحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16779, 'نَازِيَّةٌ', 'نازية', 'منسوب', '', 'نازية', 'نزة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"نَازِيَّةٌ-نَازِيَّةٌ (سيا) (مص. صِنَاعِيٌّ). : حَرَكَةٌ سِيَاسِيَّةٌ مَثَّلَهَا الْحِزْبُ الوَطَنِيُّ الاشْتِرَاكِيُّ، الَّذِي أَنْشَأَهُ هِتْلَرُ فِي ألْمَانْيَـا سَنَةَ 1923."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16780, 'نِسْبِيَّةٌ', 'نسبية', 'منسوب', 'نسب', 'نسبية', 'نسبة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نِسْبِيَّةٌ-نِسْبِيَّةٌ [ن س ب] (مص. صِنَاعِيٌّ). 1. : مَذْهَبٌ فَلْسَفِيٌّ يَقُولُ إِنَّ الْمَعَارِفَ نِسْبِيَّةٌ وَغَيْرُ مُطْلَقَةٍ. 2.""نَظَرِيَّةُ النِّسْبِيَّةِ"" : نَظَرِيَّةُ أَيْنِشْتَاين الَّتِي تَرَى أَنَّ مُرُورَ الزَّمَنِ لَيْسَ هُوَ نَفْسُهُ عِنْدَ مُلاَحِظَيْنِ يَخْتَلِفُ مَوْقِعُ كُلُّ وَاحِدٍ مِنْهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16781, 'نَاصِرِيَّةٌ', 'ناصرية', 'منسوب', 'نصر', 'ناصرية', 'نصرة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"نَاصِرِيَّةٌ-نَاصِرِيَّةٌ [ن ص ر] (سيا) (مص. صِنَاعِيٌّ). : مُجْمَلُ الآرَاءِ وَالأَفْكَارِ فِي الوَحْدَةِ وَالاشْتِرَاكِيَّةِ الَّتِي كَانَ يَطْرَحُهَا وَيُدَافِعُ عَنْهَا الرَّئِيسُ جَمَالُ عَبْدِ النَّاصِرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16782, 'نَصْرَانِيَّةٌ', 'نصرانية', 'منسوب', 'نصر', 'نصرانية', 'نصرنة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"نَصْرَانِيَّةٌ-نَصْرَانِيَّةٌ [ن ص ر] (مص. صِنَاعِيٌّ). : الْمَسِيحِيَّةُ، أَيْ دِينُ السَّيِّدِ الْمَسِيحِ عَلَيْهِ السَّلاَمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16783, 'نَظَرِيَّةٌ', 'نظرية', 'منسوب', 'نظر', 'نظرية', 'نظرة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مص. صِنَاعِيٌّ). 1.""يَشْرَحُ النَّظَرِيَّةَ فيِ الفَصْلِ وَيُطَبِّقُهَا فِي الْمُخْتَبَرِ"" : قَضِيَّةٌ فِي مَجَالٍ عِلْمِيٍّ مَّا تَثْبُتُ بِحُجَّةٍ وَبُرْهَانٍ. ""جَاءَ التَّطْبِيقُ لِيُؤَكِّدَ صِحَّةَ النَّظَرِيَّةِ"". 2.""نَظَرِيَّةُ القِيمَةِ الوُسْطَى"" : نَظَرِيَّةُ الزِّيَادَاتِ الْمُتَنَاهِيَةِ. 3.""نَظَرِيَّةُ فِيتَاغُورَسَ"" : النَّظَرِيَّةُ الْخَاصَّةُ بِالْمُثَلَّثِ قَائِمِ الزَّاوِيَةِ الْمُقِرَّةُ أَنَّ مُرَبَّعَ الوَتَرِ يُسَاوِي مَجْمُوعَ مُرَبَعَيِ الضِّلْعَيْنِ الآخَرَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16784, 'نَفْعِيَّةٌ', 'نفعية', 'منسوب', 'نفع', 'نفعية', 'نفعة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"نَفْعِيَّةٌ-نَفْعِيَّةٌ [ن ف ع] (مص. صِنَاعِيٌّ): مَذْهَبُ الَّذِينَ يَطْلُبُونَ الْمَنْفَعَةَ الْمُجَرَّدَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16785, 'مَنْهَجِيَّةٌ', 'منهجية', 'منسوب', 'نهج', 'منهجية', 'منهجة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مص. صِنَاعِيٌّ). ""أَلْقَى مُحَاضَرَةً فِي الْمَنْهَجِيَّةِ"" : فِي طُرُقِ البَحْثِ والدِّرَاسَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16786, 'وُجُودِيَّةٌ', 'وجودية', 'منسوب', 'وجد', 'وجودية', 'جدة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"وُجُودِيَّةٌ-وُجُودِيَّةٌ [و ج د] (مص. صِنَاعِيٌّ). : مَذْهَبٌ فَلْسَفِيٌّ قَائِمٌ عَلَى اعْتِبَارِ أَنَّ الوُجُودَ يَتَقَدَّمُ الْمَاهِيَةَ، وَأَنَّ الإِنْسَانَ يُوجَدُ فِيهِ حُرّاً، يَبْنِي نَفْسَهُ حَسَبَ إِرَادَتِهِ وَمَشِيئَتِهِ وَيَخْتَارُ لَهَا نَمُوذَجَ وُجُودِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16787, 'وَحْدَوِيَّةٌ', 'وحدوية', 'منسوب', 'وحد', 'وحدوية', 'حدة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"وَحْدَوِيَّةٌ-وَحْدَوِيَّةٌ [و ح د] (مص. صِنَاعِيٌّ). ""يَدْعُو إِلَى الوَحْدَوِيَّةِ فِي العَمَلِ السِّيَاسِيِّ"" : أَيْ كُلُّ مَا يُقَوِّي وَحْدَةَ العَمَلِ وَيُدَعِّمُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16788, 'وَحْشِيَّةٌ', 'وحشية', 'منسوب', 'وحش', 'وحشية', 'حشة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"وَحْشِيَّةٌ-وَحْشِيَّةٌ [و ح ش] (مص. صِنَاعِيٌّ). ""وَحْشِيَّةُ الْحَرْبِ"" : هَمَجِيَّتُهَا، شَرَاسَتُهَا. ""تَصَرَّفَ مَعَهُ بِكُلِّ وَحْشِيَّةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16789, 'وُصُولِيَّةٌ', 'وصولية', 'منسوب', 'وصل', 'وصولية', 'صلة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"وُصُولِيَّةٌ-وُصُولِيَّةٌ [و ص ل] (مص. صِنَاعِيٌّ). ""جَمَاعَةٌ تَمَيَّزَتْ سِيَاسَتُهَا بِالوُصُولِيَّةِ"" : سِيَاسَةُ تَحْقِيقِ الْمَنَافِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16790, 'مَوْضُوعِيَّةٌ', 'موضوعية', 'منسوب', 'وضع', 'موضوعية', 'مضعة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مَوْضُوعِيَّةٌ-مَوْضُوعِيَّةٌ [و ض ع] (مص. صِنَاعِيٌّ). ""تَتَمَيَّزُ أَحْكَامُهُ بِالْمَوْضُوعِيَّةِ"" : أَحْكَامٌ كَمَا هِيَ، كَمَا يَرَاهَا الذِّهْنُ فِي الوَاقِعِ، بَعِيدَةً عَنِ الذَّاتِيَّةِ، لاَ تَشُوبُهَا نَظْرَةٌ ضَيِّقَةٌ وَلاَ تَحَيُّزٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16791, 'وَاقِعِيَّةٌ', 'واقعية', 'منسوب', 'وقع', 'واقعية', 'قعة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"وَاقِعِيَّةٌ-وَاقِعِيَّةٌ [و ق ع] (مص. صِنَاعِيٌّ). 1. فِي مَجَالِ الفَلْسَفَةِ : مَذْهَبٌ قَائِمٌ عَلَى اعْتِبَارِ الوَاقِعِ الْمَادِّيِّ الْمَحْسُوسِ لِلطَّبِيعَةِ وَالْحَيَاةِ مُنْطَلَقَ التَّفْسِيرِ وَالتَّحْلِيلِ. 2. فِي الأَدَبِ : تَيَّارٌ أَدَبِيٌّ نَشَأَ فِي فَرَنْسَا مُنْذُ مُنْتَصَفِ القَر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16792, 'وَهَّابِيَّةٌ', 'وهابية', 'منسوب', 'وهب', 'وهابية', 'هبة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"وَهَّابِيَّةٌ-وَهَّابِيَّةٌ [و هـ ب] (مص. صِنَاعِيٌّ). : مِنَ الْمَذَاهِبِ الإِسْلاَمِيَّةِ الْمُسْتَحْدَثَةِ، وَضَعَ أُسُسَهُ الشَّيْخُ مُحَم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16793, 'جَاهِلِيَّةٌ', 'جاهلية', 'منسوب', 'جهل', 'جاهلية', 'جهلة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"جَاهِلِيَّةٌ-جَاهِلِيَّةٌ [ج هـ ل] . (مص. صِنَاعِيّ). عَاشَ العَرَبُ فِي الجَاهِلِيَّةِ يَعْبُدُونَ الأَصْنَامَ إِلَى أَنْ جَاءَ الإِسْلاَمُ وَأَنْقَذَهُمْ مِنَ الوَثَنِيَّةِ"": حَالَةُ الجَهْلِ الَّتِي كَانُوا عَلَيْهَا قَبْلَ مَجِيءِ الإِسْلاَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16794, 'رَجْعِيَّةٌ', 'رجعية', 'منسوب', 'رجع', 'رجعية', 'رجعة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"رَجْعِيَّةٌ-رَجْعِيَّةٌ [ر ج ع] (مص. صِنَاعِيّ). ""تَتَّسِمُ سِيَاسَتُهُ بِالرَّجْعِيَّةِ"" : صِفَةٌ لِمَوَاقِفَ سِياسِيَّةٍ تَتَشَبَّثُ بِتَقَالِيد السَّلَفِ وَأفْكَارٍ مُحَافِظَةٍ تَحُولُ دُونَ التَّقَدُّمِ الحَضَارِيِّ وَالاجْتِمَاعِيِّ وَالسِّيَاسِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16795, 'شَعْبِيَّةٌ', 'شعبية', 'منسوب', '', 'شعبية', 'شعبة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"شَعْبِيَّةٌ-شَعْبِيَّةٌ (مص. صِنَاعِيّ). ""قَائِدٌ سِيَاسِيٌّ يَتَمَتَّعُ بِشَعْبِيَّةٍ كَبِيرَةٍ"" : يَتَمَتَّعُ بِتَأْيِيدِ عَامَّةِ الشَّعْبِ وَعَطْفِهِمْ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16796, 'صَلاَحِيَّةٌ', 'صلاحية', 'منسوب', 'صلح', 'صلاحية', 'صلحة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِنَاعِيّ). 1.""صَلاَحِيَّةُ العَمَلِ"" : حُسْنُ أَهْلِيَّتِهِ. ""لَهُ الصَّلاَحِيَّةُ الكَامِلَةُ لِلْقِيَامِ بِهَذَا الأَمْرِ"" : لَهُ الأَهْلِيَّةُ لِلْقِيَامِ بِهِ. 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16797, 'اِنْطِباعِيَّةٌ', 'انطباعية', 'منسوب', 'طبع', 'انطباعية', 'نطبعة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"اِنْطِباعِيَّةٌ-اِنْطِباعِيَّةٌ [ط ب ع] (مص. صِنَاعِيّ).: مِنْ مَذاهِبِ فَنِّ الرَّسْمِ، يَعْتَمِدُ الرُّؤْيَةَ التِّلْقائِيَّةَ والعَفْوِيَّةَ على قاعِدَةِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16798, 'طُفُولِيَّةٌ', 'طفولية', 'منسوب', 'طفل', 'طفولية', 'طفلة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"طُفُولِيَّةٌ-طُفُولِيَّةٌ [ط ف ل] (مص. صِنَاعِيّ). ""مَازَالَتْ تَصَرُّفاَتُهُ طُفُولِيَّةً"" : صِفَاتُ الطُّفُولَةِ عِنْدَ الكِبَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16799, 'طُوبُوغْرَافِيَّةٌ', 'طوبوغرافية', 'منسوب', '', 'طوبوغرافية', 'طبغرفة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"طُوبُوغْرَافِيَّةٌ-طُوبُوغْرَافِيَّةٌ (مص. صِنَاعِيّ). ""عِلْمُ الطُّوبُوغْرَافِيَّةِ"" : عِلْمٌ مُخْتَصٌّ بِوَصْفِ جِهَةٍ مِنْ جِهَاتِ الأَرْضِ وَرَسْمِهَا وَإِظْهَارِ مَا عَلَيْهَا مِن تَضارِيسَ وَمَا يُحِيطُ بِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16800, 'طَائِفِيَّةٌ', 'طائفية', 'منسوب', 'طوف', 'طاءفية', 'طفة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"طَائِفِيَّةٌ-طَائِفِيَّةٌ [ط و ف] (مص. صِنَاعِيّ). ""مَا زَالَتِ الطَّائِفِيَّةُ تَتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16801, 'عُنْصُرِيَّةٌ', 'عنصرية', 'منسوب', 'عنصر', 'عنصرية', 'عنصرة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عُنْصُرِيَّةٌ-عُنْصُرِيَّةٌ [ع ن ص ر] (مص. صِنَاعِيّ). : مَذْهَبٌ قَائِمٌ عَلَى التَّفْرِقَةِ بَيْنَ الْبَشَرِ بِحَسَبِ أُصُولِهِمُ الْجِنْسِيَّةِ وَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16802, 'فِدَائِيَّةٌ', 'فدائية', 'منسوب', 'فدي', 'فداءية', 'فدة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"فِدَائِيَّةٌ-فِدَائِيَّةٌ [ف د ي] (مص. صِن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16803, 'مُسْتَقْبَلِيَّةٌ', 'مستقبلية', 'منسوب', 'قبل', 'مستقبلية', 'مستقبلة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِنَاعِيّ). مَجَالٌ عِلْمِيٌّ يَشْتَغِلُ فِيهِ مُتَخَصِّصُونَ لِمَعْرِفَةِ أ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16804, 'مِغْنَاطِيسِيَّةٌ', 'مغناطيسية', 'منسوب', '', 'مغناطيسية', 'مغنطسة', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مِغْنَاطِيسِيَّةٌ-مِغْنَاطِيسِيَّةٌ (مص. صِنَاعِيّ). : قُوَّةُ الْجَاذِبِيَّةِ فِي الْمِغْنَاطِيسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16805, 'وَطَنِيَّةٌ', 'وطنية', 'منسوب', 'وطن', 'وطنية', 'طنة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"وَطَنِيَّةٌ-وَطَنِيَّةٌ [و ط ن] (مص. صِنَاعِيّ). ""هِيَ الوَطَنِيَّةُ الْحَقَّةُ قَدْ تَغَلْغَلَتْ فِي نُفُوس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16806, 'مَسِيحِيَّةٌ', 'مسيحية', 'منسوب', 'مسح', 'مسيحية', 'مسحة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مَسِيحِيَّةٌ-مَسِيحِيَّةٌ [م س ح] (مص. صِنَاعيٌّ). ""الدِّيَانَةُ الْمَسِيحِيَّةُ"" : الدِّيَانَةُ النَّصْرَانِيَّةُ التِي جَاءَ بِهَا السَّيِّدُ الْمَسِيحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16807, 'فَوْضَوِيَّةٌ', 'فوضوية', 'منسوب', 'فوض', 'فوضوية', 'فضة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"فَوْضَوِيَّةٌ-فَوْضَوِيَّةٌ [ف و ض] (مص. صِنَاعيّ). : مَذْهَبٌ سِيَاسِيٌّ قَائِمٌ عَلَى إِلْغَاءِ الْقَوَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16808, 'مَلَكِيَّةٌ', 'ملكية', 'منسوب', 'ملك', 'ملكية', 'ملكة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مَلَكِيَّةٌ-مَلَكِيَّةٌ [م ل ك] (مص. صِنَاعيّ). ""مَلَكِيَّةٌ دُسْتُورِيَّةٌ"" : نِظَامٌ سِيَاسِيٌّ يَخْضَعُ لِسُلْطَةِ الْمَلِكِ عَلَى أَسَاسِ دُسْتُورٍ يُنَظِّمُ السُّلَطَ. ""مَلَكِيَّةٌ وِرَاثِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16809, 'عَبْقَرِيَّةٌ', 'عبقرية', 'منسوب', 'عبقر', 'عبقرية', 'عبقرة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عَبْقَرِيَّةٌ-عَبْقَرِيَّةٌ [ع ب ق ر] (مص. صِناَعِيٌّ). ""يُودِعُ فِي الْكُتُبِ آيَاتِ عَبْقَرِيَّتِهِ"" : صِفَةُ الْعَبْقَرِيِّ، أَيْ قُوَّةُ الْخَلْقِ وَالإِبْدَاعِ عِنْدَ فَنَّانٍ أَوْ كَاتِبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16810, 'أكَادِيمِيّةٌ', 'أكاديمية', 'منسوب', '', 'ءكاديمية', 'كدمة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"أكَادِيمِيّةٌ-أكَادِيمِيّةٌ (مص. صِناعِيٌّ).: اِسْمٌ يُطْلَقُ عَلَى الْمُؤَسَّسَاتِ العِلْمِيَّةِ أوِ الأدَبِيَّةِ. ""أكَادِيمِيَّةُ العُلُومِ"" ""أكَادِيمِيَّةُ الْمَمْلَكَةِ الْمَغْرِبِيَّة""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16811, 'أَنانِيَّةٌ', 'أنانية', 'منسوب', 'أنأ', 'ءنانية', 'ننة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"أَنانِيَّةٌ-أَنانِيَّةٌ [أ ن أ] (مص. صِناعِيٌّ). ""كُلُّ حَرَكَةٍ مِنْ حَرَكاتِهِ تُظْهِرُ أَنانِيَّةً لاَ حَدَّ لَها"" : الإفْراطُ في حُبِّ النَّفْسِ وَالإعْجابِ بِها، مَعَ عَدَمِ التَّفْكيرِ في الغَيْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16812, 'إِنْسانِيَّةٌ', 'إنسانية', 'منسوب', 'أنس', 'ءنسانية', 'إنسنة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"إِنْسانِيَّةٌ-إِنْسانِيَّةٌ [أ ن س] (مص. صِناعِيٌّ). 1.""تَتَكاثَفُ الجُهودُ العِلْمِيَّةِ لِخِدْمَةِ الإِنْسانِيَّةِ"" : البَشَرِيَّةِ، أَيْ لِخِدْمَةِ الجِنْسِ البَشَرِيِّ. 2.""يُتا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16813, 'بُرُوتِسْتانِيَّةٌ', 'بروتستانية', 'منسوب', '', 'بروتستانية', 'برتستنة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"بُرُوتِسْتانِيَّةٌ-بُرُوتِسْتانِيَّةٌ (مص. صِناعِيٌّ). : مَذْهَبٌ مِنَ الْمَذاهِبِ الدِّينِيَّةِ الْمُنْتَمِيَةِ لِلْكَن"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16814, 'حَدْسِيَّةٌ', 'حدسية', 'منسوب', 'حدس', 'حدسية', 'حدسة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مص. صِناعِيٌّ). ""آراؤُهُ قائِمَةٌ على الحَدْسِيَّةِ"" : مَذْهَبٌ يَقولُ بِأَنَّ الْمَعْرِفَةَ قائِمَةٌ بِالدَّرَجَةِ الأُولَى على جانِبِ الحَدْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16815, 'رُوحِيَّةٌ', 'روحية', 'منسوب', 'روح', 'روحية', 'رحة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"رُوحِيَّةٌ-رُوحِيَّةٌ [ر و ح] (مص. صِناعِيٌّ). ""الفَلْسَفَةُ الرُّوحِيَّةِ"": أي عَكْسُ الفلْسَفَة الْمَادِّيَّة، وَتَرْمِي إلَى إِثْباتِ أَنَّ الرُّوحَ تَعْلُو وَتَسْمو عَلَى المادَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16816, 'رُومانْسِيَّةٌ', 'رومانسية', 'منسوب', '', 'رومانسية', 'رمنسة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"رُومانْسِيَّةٌ-رُومانْسِيَّةٌ (مص. صِناعِيٌّ). : صِفَةُ الحَرَكاتِ الفَنِّيَّةِ والأَدَبِيَّةِ الَّتِي ظَهَرَتْ في أُوروبَّا بَعْدَ عَصْرِ النَّهْضَةِ وَعُرِفَتْ بِالرُّومانْطِقِيَّةِ وَتَطَوَّرَتْ بِالأَخَصِّ في نِهايَةِ القَرْنِ الثَّامِنِ عَشَرَ. مَثَّلَتِ الرُّومانْسِيَّةُ ثَوْرَةً عَلَى الكِلاسِيكِيَّةِ والتَّحَرُّرِ مِنْ قَواعِدِها وَتِقْنِياتِها، ومِنْ خَصائِصِها: اِعْتِمادُ الخَيالِ والعاطِفَةِ مُنْطَلَقاً لِلرُّؤْيَةِ الفَنِّيَّةِ، وَإِبْعادُ الجانِبِ العَقْلِيِّ، وَجَعْلُ الطَّبيعَةِ مادَّةً لِلْكِتابَةِ والانْغِمارُ في أَجْوائِها، وَعَرَفَ الأَدَبُ العَرَبِيُّ رُومانْسِيِّينَ مثل: جَبْران خليل جبران وخليل مطران وَعَلِيّ محمود طه."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16817, 'اِشْتِراكِيَّةٌ', 'اشتراكية', 'منسوب', 'شرك', 'اشتراكية', 'شتركة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"اِشْتِراكِيَّةٌ-اِشْتِراكِيَّةٌ [ش ر ك] (مص. صِناعِيٌّ). مَذْهَبٌ اِقْتِصادِيٌ وَاجْتِماعِيٌّ وَسِياسِيٌّ قائِمٌ على إِلْغاءِ المِلْكِيَّةِ الخاصَّةِ الواسِعَةِ، وَتَأْمِيمِ وَسائِلِ الإِنْتاجِ وَالْمُواصَلاتِ وَالْمُؤَسَّساتِ الاقْتِصادِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16818, 'إِشْكالِيَّةٌ', 'إشكالية', 'منسوب', 'شكل', 'ءشكالية', 'إشكلة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِناعِيٌّ). ""طَرَحَ إِشْكالِيَّةً على الْمُناظِرينَ"" : قَضِيَّةً فِكْرِيَّةً أَوْ ثَقافِيَّةً أَوِ اجْتِماعِيَّةً، تَتَضَمَّنُ الْتِباسًا وَغُموضاً، وَهِيَ بِحاجَةٍ إلى تَفْكيرٍ وَتَأَمُّلٍ وَنَظَرٍ لإيجادِ حَلٍّ لَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16819, 'مُعْجَمَاتِيَّةٌ', 'معجماتية', 'منسوب', 'عجم', 'معجماتية', 'معجمتة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"مُعْجَمَاتِيَّةٌ-مُعْجَمَاتِيَّةٌ [ع ج م] (مص. صِناعِيٌّ).: عِلْمُ صِنَاعَةِ الْمُعْجَمَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16820, 'إِقْلِيمِيَّةٌ', 'إقليمية', 'منسوب', 'قلم', 'ءقليمية', 'إقلمة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"إِقْلِيمِيَّةٌ-إِقْلِيمِيَّةٌ [ق ل م] (مص. صِناعِيٌّ).: مَذْهَبٌ قَائِمٌ عَلَى التَّجَمُّعَاتِ الإقْلِيمِيَّةِ عَكْسَ الْمَرْكَزِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16821, 'إلْزَامِيَّةٌ', 'إلزامية', 'منسوب', 'لزم', 'ءلزامية', 'إلزمة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"إلْزَامِيَّةٌ-إلْزَامِيَّةٌ [ل ز م] (مص. صِناعِيٌّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16822, 'اِنْتِهازِيَّةٌ', 'انتهازية', 'منسوب', 'نهز', 'انتهازية', 'نتهزة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"اِنْتِهازِيَّةٌ-اِنْتِهازِيَّةٌ [ن هـ ز] (مص. صِناعِيٌّ). ""يُمَثِّلُ سُلوكُهُ انْتِهازِيَّةً واضِحَةً"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16823, 'إِسْتْرَاتِيجِيَّةٌ', 'إستراتيجية', 'منسوب', '', 'ءستراتيجية', 'إسترتجة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"إِسْتْرَاتِيجِيَّةٌ-إِسْتْرَاتِيجِيَّةٌ (مص. صِناعِيّ).: مِنَ الفُنُونِ العَسْكَرِيَّةِ وَيُقْصَدُ بِهَا التَّخْطِيطُ وَتَحْدِيدُ الوَسَائِلِ الَّتِي يَجِبُ الأخْذُ بِهَا فِي القِمَّةِ وَالقَاعِدَةِ لِتَحْقِيقِ الأهْدَافِ البَعِيدَةِ، وتُسْتَعْمَلُ أيْضاً في الخِطابِ السِّياسِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16824, 'دِيماغوجِيَّةٌ', 'ديماغوجية', 'منسوب', '', 'ديماغوجية', 'دمغجة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"دِيماغوجِيَّةٌ-دِيماغوجِيَّةٌ (سيا) (مص. صِناعيٌّ). ""لاَ يَخْلُو كَلامُهُ مِنَ الدِّيماغوجِيَّةِ"" :ك"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16825, 'دِيمُقْراطِيَّةٌ', 'ديمقراطية', 'منسوب', '', 'ديمقراطية', 'دمقرطة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"دِيمُقْراطِيَّةٌ-دِيمُقْراطِيَّةٌ (سيا) (مص. صِناعيٌّ).: شَكْلٌ مِنْ أَشْكالِ السُّلْطَةِ والحُكْمِ يَعودُ فيهِ القَرارُ إلى الشَّعْبِ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16826, 'رَمْزِيَّةٌ', 'رمزية', 'منسوب', 'رمز', 'رمزية', 'رمزة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَمْزِيَّةٌ-رَمْزِيَّةٌ [ر م ز] (مص. صِناعيٌّ). : مَذْهَبٌ في الفَنِّ والأَدَبِ يَعْتَمِدُ الإيحاءَ والتَّلْميحَ بِرُموزِهِ الْمُنْبَثِقَةِ مِنَ الصُّوَرِ الحِسِّيَّةِ والأَساطِيرِ، وَيَتْرُكُ لِلْقارِئِ مَجالاً لِلتَّصَوُّرِ والخَيالِ لإِكْمالِ الدَّلالاتِ الرَّمْزِيَّةِ كَما تُوحِي بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16827, 'بَشَرِيَّةٌ', 'بشرية', 'منسوب', 'بشر', 'بشرية', 'بشرة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"بَشَرِيَّةٌ-بَشَرِيَّةٌ [ب ش ر] (مص. صِناعيّ). ""لَقَدْ حَقَّقَتِ البَشَرِيَّةُ تَقَدُّماً هائِلاً في القَرْنِ العِشْرِينَ"" : الإِنْسانِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16828, 'اِنْفِصالِيَّةٌ', 'انفصالية', 'منسوب', 'فصل', 'انفصالية', 'نفصلة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"اِنْفِصالِيَّةٌ-اِنْفِصالِيَّةٌ (مص. صناعِيٌّ). صِفَةٌ لِحالَةِ الانْفِصالِ. ن.اِنْفِصالِيّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16829, 'اِحْتِفَالِيَّةٌ', 'احتفالية', 'منسوب', 'حفل', 'احتفالية', 'حتفلة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"اِحْتِفَالِيَّةٌ-اِحْتِفَالِيَّةٌ [ح ف ل] (مص. صناعيٌّ).: اِتِّجاهٌ مَسْرَحِيٌّ شَعْبِيٌّ يعْتمدُ الفُرْجَةَ وكلَّ أَنْوَاعِ التَّعْبِيرِ الْمُختَلِفةِ شِعراً وغِناءً ورَقْصاً وإيماءً وأقْنِعةً وأزْيَاءً فِي فَضاءٍ مَفْتوحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16830, 'باطِنِيَّةٌ', 'باطنية', 'منسوب', 'بطن', 'باطنية', 'بطنة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"باطِنِيَّةٌ-باطِنِيَّةٌ [ب ط ن] (مص. صناعيّ).: فِرْقَةٌ دِينِيَّةٌ يَرْتَكِزُ اقْتِنَاعُهَا عَلَى أسَاسِ قاعِدَةِ أنَّ لِكُلِّ ظاهِرٍ باطِناً، وأَنَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16831, 'بِيدَاغُوجِيَّةٌ', 'بيداغوجية', 'منسوب', '', 'بيداغوجية', 'بدغجة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"بِيدَاغُوجِيَّةٌ-بِيدَاغُوجِيَّةٌ (مص. صناعيّ).: عِلْمُ التَّرْبِيَةِ، يَهْدِفُ إلَى تَنْشِئَةِ الأطْفَالِ وَتَعْليمِهِمْ حَسَبَ مَنَاهِجَ وَطُرُقٍ عِلْمِيَّةٍ مُحَدَّدَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16832, 'بيرُوقْرَاطِيَّةٌ', 'بيروقراطية', 'منسوب', '', 'بيروقراطية', 'برقرطة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"بيرُوقْرَاطِيَّةٌ-بيرُوقْرَاطِيَّةٌ (مص. صناعيّ).: مَجْمُوعُ المُؤَسَّسَاتِ الإدَارِيَّةِ العُمُومِيَّةِ الَّتِي يَتَوَلَّى فِيَهَا المُوَظَّفُونَ البِيروقْرَاطِيُّونَ تَطْبِيقَ سُلْطَةِ القَانُونِ حَسَبَ السُّلَّمِ الإدَارِيِّ، وَالَّتِي تَتَّسِمُ بالبُطءِ فِي التَّنْفِيذِ مِمَّا يُؤَدِّي إلَى عَرْقَلَةِ السَّيْرِ الطَّبِيعِيِّ لِشُؤُونِ المُوَاطِنِينَ وَمِنَ العَقَبَاتِ الَّتِي تَعْتَرِضُ تَطْبِيقَ الْمَشَارِيع."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16833, 'بَيُولُوجِيَّةٌ', 'بيولوجية', 'منسوب', '', 'بيولوجية', 'بلجة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مص. صناعيّ). : عِلْمُ الأحْيَاءِ، يَبْحَثُ شَكْلَ ووَظيفَةَ إِنْتاجِيَّةِ مُجْمَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16834, 'طُبُوغْرَافِيَّةٌ', 'طبوغرافية', 'منسوب', '', 'طبوغرافية', 'طبغرفة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"طُبُوغْرَافِيَّةٌ-طُبُوغْرَافِيَّةٌ (مص. صناعيّ). : بَيَانُ الْمَلاَمِحِ العَامَّةِ لِسَطْحِ الأَرْضِ طَبِيعِيَّةً كَانَتْ أَوْ مَصْنُوعَةً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16835, 'طُبُولُوجِيَّةٌ', 'طبولوجية', 'منسوب', '', 'طبولوجية', 'طبلجة', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"طُبُولُوجِيَّةٌ-طُبُولُوجِيَّةٌ (مص. صناعيّ). : عِلْمُ دِرَاسَةِ وَتَحْلِيلِ خَصَائِصِ أَوْضَاعٍ حَسَبَ مُعْطَيَاتِهَا لِتَحْدِيدِ أَنْوَاعِهَا وَأَنْظِمَتِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16836, 'فَرْدِيَّةٌ', 'فردية', 'منسوب', 'فرد', 'فردية', 'فردة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"فَرْدِيَّةٌ-فَرْدِيَّةٌ [ف ر د] (مص. صناعيّ). 1.""تَمَيَّزَتْ فَتْرَةُ حُكْمِهِ بِالْفَرْدِيَّةِ"" : الْحُكْمُ الْفَرْدِيُّ الْمُنْعَزِلُ عَنْ آرَاءِ الْجَمَاعَةِ. 2.""يُؤْمِنُ بِالْفَرْدِيَّةِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16837, 'وَحْدَانِيَّةٌ', 'وحدانية', 'منسوب', 'وحد', 'وحدانية', 'حدنة', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"وَحْدَانِيَّةٌ-وَحْدَانِيَّةٌ [و ح د] (مص. صِنَاعِيٌّ مِنَ الوَحْدَة). ""وَحْدَانِيَّةُ اللَّهِ تَعَالَى"" : مِنْ صِفَاتِهِ تَعَالَى، أَيْ تَفَرُّدُهُ تَعَالَى فِي مَاهِيَّتِهِ وَ صِفَاتِ كَمَالِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16838, 'مَحْدُودِيَّةٌ', 'محدودية', 'منسوب', 'حدد', 'محدودية', 'محددة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَحْدُودِيَّةٌ-مَحْدُودِيَّةٌ [ح د د] (مص. صِنَاعِيٌّ). ""آرَاؤُهُ تُعَبِّرُ عَنْ مَحْدُودِيَّةِ تَفْكِيرِهِ"" : أَيْ آرَاؤُهُ ذَاتُ تَفْكِيرٍ ضَيِّقٍ، قَاصِرَة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16839, 'مَحْسُوبِيَّةٌ', 'محسوبية', 'منسوب', 'حسب', 'محسوبية', 'محسبة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَحْسُوبِيَّةٌ-مَحْسُوبِيَّةٌ [ح س ب] (مص. صِنَاعِيٌّ). ""يَنْبَغِي وَضْعُ حَدٍّ لِتَفَشِّي الْمَحْسُوبِيَّة فِي الإِدَارَةِ"" : اِعْتِبارُ القَرَابَةِ العَائِلِيَّةِ أَوِ السِّيَاسِيَّةِ فِي إِسْنَادِ الوَظَائِفِ أَوْ فِي التَّرْقِيَاتِ وَالتَّسْيِيرِ. ""الْمَحْسُوبِيَّةُ مِنْ عَنَاصِرِ الفَسَادِ تَجْعَلُ الْحَسَبَ وَالنَّسَبَ فِي الْمَقَامِ الأَوَّلِ وَنَيْلَ الْحُظْوَةِ وَالتَّرْقِيَةِ بَدَلاً مِنَ العَمَلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16840, 'خَاصِّيَّةٌ', 'خاصية', 'منسوب', 'خصص', 'خاصية', 'خصة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"خَاصِّيَّةٌ-خَاصِّيَّةٌ [خ ص ص] (مص. صِنَاعِيٌّ). ""خَاصِّيَّةُ الت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16841, 'مَدْيُونِيَّةٌ', 'مديونية', 'منسوب', 'دين', 'مديونية', 'مدنة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَدْيُونِيَّةٌ-مَدْيُونِيَّةٌ [د ي ن] (مص. صِنَاعِيٌّ). ""الْمَدْيُونِيَّةُ الْخَارِجِيَّةُ تُرْهِقُ كَاهِلَ شُعُوبِ العَالَمِ الثَّالِثِ"" : مَجْمُوعُ الدُّيُونِ الْمُتَرَتِّبَةِ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16842, 'مَرْدُودِيَّةٌ', 'مردودية', 'منسوب', 'ردد', 'مردودية', 'مرددة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَرْدُودِيَّةٌ-مَرْدُودِيَّةٌ [ر د د] (مص. صِنَاعِيٌّ). ""مَرْدُودِيَّةُ العَمَلِ"": عَطَاؤُهُ، دَخْلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16843, 'مَشْرُوعِيَّةٌ', 'مشروعية', 'منسوب', 'شرع', 'مشروعية', 'مشرعة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَشْرُوعِيَّةٌ-مَشْرُوعِيَّةٌ [ش ر ع] (مص. صِنَاعِيٌّ). ""تَسْتَمِدُّ السُّلْطَةُ مَشْرُوعِيَّتَهَا مِنَ الشَّعْبِ"" : أَهْلِيَّتَهَا، مِصْدَاقِيَّتَهَا حَسَبَ مَا يُسَوِّغُهُ القَانُونُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16844, 'شَفَافِيَّةٌ', 'شفافية', 'منسوب', 'شفف', 'شفافية', 'شففة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"شَفَافِيَّةٌ-شَفَافِيَّةٌ [ش ف ف] (مص. صِنَاعِيٌّ). ""تَحَدَّثَ بِشَفَافِيَّةٍ"": بِوُضُوحٍ تَامٍّ. ""تَمَيَّزَتْ مَشَارِيعُهُ وَخُطَطُهُ بِالشَّفَافِيَّةِ"" ""مَرْحَلَةُ الشَّفَافِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16845, 'غَيْرِيَّةٌ', 'غيرية', 'منسوب', 'غير', 'غيرية', 'غرة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"غَيْرِيَّةٌ-غَيْرِيَّةٌ [غ ي ر] (مص. صِنَاعِيٌّ). 1. : كَوْنُ كُلٍّ مِنَ الشَّيْئَيْنِ خِلاَفَ الآخَرِ. 2.""يَتَمَيَّزُ بِالغَيْرِيَّةِ"" : الإِيثارُ، يُفَضِّلُ الغَيْرَ عَلَى الذَّاتِ خِلاَفَ الأَنَانِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16846, 'قَابِلِيَّةٌ', 'قابلية', 'منسوب', 'قبل', 'قابلية', 'قبلة', 'مص. صِنَاعِيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"قَابِلِيَّةٌ-قَابِلِيَّةٌ [ق ب ل] (مص. صِنَاعِيّ). ""لَهُ قَابِلِيَّةُ الاسْتِمَاعِ إِلَى غَيْرِهِ"" : حَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16847, 'أهَمِّيَّةٌ', 'أهمية', 'منسوب', 'همم', 'ءهمية', 'همة', 'مص. صِنَاعِيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"أهَمِّيَّةٌ-أهَمِّيَّةٌ [هـ م م] (مص. صِنَاعِيّ). 1.""مَوْضُوعٌ لَهُ أهَمِّيَّةٌ كُبْرَى"" : مَكَانَةٌ، شَأنٌ. ""عَلَّقَ أهَمِّيَّةً خَاصَّةً عَلَى حُضُورِهِ"". 2.""تَكْمُنُ أهَمِّيَّةُ الأمْرِ فِي ..."" : تَكْمُنُ خُطُورَتُهُ. ""هَذَا أمْرٌ عَلَى جَانِبٍ كَبِيرٍ مِنَ الأهَمِّيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16848, 'مَعْمُودِيَّةٌ', 'معمودية', 'منسوب', 'عمد', 'معمودية', 'معمدة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مَعْمُودِيَّةٌ-مَعْمُودِيَّةٌ [ع م د] (مص. صِناعِيٌّ). ""أُقِيمَ حَفْلُ الْمَعْمُودِيَّةِ لِلطِّفْلِ فِي الكَنِيسَةِ"" : تَنْصِيرُ الطِّفْلِ لِيَصِيرَ مَسِيحِيّاً وذَلِكَ بِغَسْلِهِ بِالْمَاءِ الْمُطَهَّرِ عَلَى يَدِ القَسِّ أَوِ الرَّاهِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16849, 'مُفَوَّضِيَّةٌ', 'مفوضية', 'منسوب', 'فوض', 'مفوضية', 'مفضة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مُفَوَّضِيَّةٌ-مُفَوَّضِيَّةٌ [ف و ض] (مص. صِناعِيٌّ). : مَنْصِبُ الْمُفَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16850, 'مِكْثَافِيَّةٌ', 'مكثافية', 'منسوب', 'كثف', 'مكثافية', 'مكثفة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"مِكْثَافِيَّةٌ-مِكْثَافِيَّةٌ [ك ث ف] (مص. صِناعِيٌّ). : قِيَاسُ الْكَثَافَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16851, 'مَسْؤُولِيَّةٌ', 'مسؤولية', 'منسوب', 'سأل', 'مسءولية', 'مسلة', 'مص. صِنَاعِيٌّ مِنْ مَسْؤُولٌ', '', '', 'مفرد', 'DnN', '', 'Pf', '', '', '', '', '', '', '', '', '', '"(مص. صِنَاعِيٌّ مِنْ مَسْؤُولٌ). 1.""يَتَحَمَّلُ مَسْؤُولِيَّةَ مَا حَدَثَ"" : يَتَحَمَّلُ تَبِعَةَ مَا حَدَثَ. 2.""هَذَا الأَمْرُ عَلَى مَسْؤُولِيَّتِهِ"" : عَلَى عَاتِقِهِ، عَلَى عُهْدَتِهِ. 3.""مَسْؤُولِيَّةٌ وَطَنِيَّةٌ"" : مُهِمَّةٌ وَطَنِيَّةٌ ذَاتُ طَابِعٍ لَهُ أَهْلِيَّةٌ وَمَكَانَةٌ. ""مَسْؤُولِيَّةٌ أَخْلاَقِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16852, 'تِقْنِيٌّ', 'تقني', 'منسوب', '', 'تقني', 'تقن', '', '', 'Ta', 'جمع تكسير', 'DnN', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. . ""تِقْنِيَّةٌ جَديدَةٌ"" : أُسْلُوبٌ مُخْتَصٌّ بِفَنٍّ أَوْ مِهْنَةٍ أَوْ حِرْفَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16853, 'سُعُودِي', 'سعودي', 'منسوب', '', 'سعودي', 'سعد', '', '', 'Ta', 'جمع تكسير', 'DnN', 'PmS', 'Pf', '":"', '', '', 'ـو', 'N', 'O', 'N', 'O', '', '": مِنَ البُلْدَانِ العَرَبِيَّةِ بِالجَزِيرَةِ العَرَبِيَّةِ (الْمَمْلَكَةُ العرَبِيَّةُ السُّعُودِيَّةُ) عَاصِمَتُهَا الرِّيَاضُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16854, 'سُورِي', 'سوري', 'منسوب', '', 'سوري', 'سر', '', '', 'Ta', 'جمع تكسير', 'DnN', 'PmS', 'Pf', '":"', '', '', 'ـو', 'N', 'O', 'N', 'O', '', '": مِنَ البُلْدانِ العَرَبِيَّةِ بِالشَّرْقِ الأَوْسَطِ. (الج"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16855, 'تَوْرَاتي', 'توراتي', 'منسوب', '', 'توراتي', 'ترت', '', '', 'Ta', 'جمع تكسير', 'DnN', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": كِتَابٌ دِينِيٌّ يَضُمُّ أسْفَارَ النَّبِيِّ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16856, 'حَيَوي', 'حيوي', 'منسوب', 'حيي', 'حيوي', 'ح', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '". 1. ""هُوَ حَيٌّ يُرْزَقُ"": يَنْبِضُ بِالحَيَاةِ وَالحَرَكَةِ. ""مَا زَالَ حَيّاً"". 2. هُوَ اللَّهُ الحَيُّ"": مِنْ أَسْمَاءِ اللَّهِ الحُسْنَى. 3. ""عَبْدُ الحَيِّ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ. 4. ""عِلْمُ الأحْيَاءِ"" : عِلْمُ دِرَاسَةِ مُخْتَلِفِ مَظَاهِرِ الكَائِنَاتِ مِنْ حَيَوانٍ وَنَبَاتٍ. 5. ""يَسْكُنُ فِي حَيِّ "', '');
