INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16888, 'أَمْرِيكي', 'أمريكي', 'منسوب', '', 'ءمريكي', 'مرك', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"أَمْرِيكا-أَمْرِيكا (جغ).: مِنَ القارَّاتِ الخَمْسِ، وَهيَ ما يُعْرَفُ بِأَمْريكا الشَّمالِيَّةِ وَأَمريكا الجَنوبِيَّةِ، تُقَدَّرُ مِساحَتُها بـ 42 مليون كلم‌²، وعَدَدُ سُكَّانِها بـ 675 مليون نَسَمة."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16889, 'أُورُوبي', 'أوروبي', 'منسوب', '', 'ءوروبي', 'رب', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"أُورُوبَّا-أُورُوبَّا (جغ).: مِنَ القَارَّاتِ الخَمْسِ، تُقَدَّرُ مِسَاحَتُهَا بـ 10 مليون كلم² وَعَدَدُ سُكَّانِهَا بـ 495 مليون نسمة."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16890, 'جِيبُوتِي', 'جيبوتي', 'منسوب', '', 'جيبوتي', 'جبت', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": مِنَ البُلْدَانِ الأَعْضَاءِ فِي جَامِعَةِ الدُّوَلِ العَرَبِيّةِ، عَاصِمَتُهُا جِيبُوتِي."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16891, 'آسِيوي', 'آسيوي', 'منسوب', '', 'ءءسيوي', 'آس', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"آسِيَا-آسِيَا (جغ).: مِنَ القَارَّاتِ الخَمْسِ، يَحُدُّهَا الْمُحِيطُ الْمُتَجَمِّدُ الشَّمَاليُّ وَالْمُحِيطَانِ الهِنْدِيُّ وَالهَادِي، والبَحْرَان الأبْيَضُ الْمُتَوَسِّطُ وَالأَحْمَرُ وَأورُوبَّا، وَهِيَ مِنْ أكْبَرِ اَلْقَارَّاتِ مِسَاحَة (44 مِلْيُون كلم²) وَأَكْثَرِهَا سُكَّانًا ( 2', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16892, 'أُسْترَالِي', 'أسترالي', 'منسوب', '', 'ءسترالي', 'سترل', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"أُسْترَالِيا-أُسْترَالِيا (جغ).: مِنَ القَارَّاتِ الخمسِ، تُقدّر مساحَتُها بـ (7.700.000 كلم²) وعددُ سُكَّانِهَا بـ(15.800.000 نسمة)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16893, 'إفْرِيقِي', 'إفريقي', 'منسوب', '', 'ءفريقي', 'إفرق', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"إفْرِيقْيَا-إفْرِيقْيَا (جغ).: مِنَ القَارَّاتِ الخَمْسِ، تُعْرَفُ بِالقارَّةِ السَّوْدَاءِ، تُقّدَّرُ مِسَاحَتُهَا بـ (30 مليون كلم² ) وعدد سُكَّانِها بـ ( 554 مليون نسمة)."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16894, 'دِفْتِري', 'دفتري', 'منسوب', '', 'دفتري', 'دفتر', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"""أُصِيبَ بِمَرَضِ الدِّفْتِرْيَا"" : مَرَضٌ يُصِيبُ الحَلْقَ، وَهُوَ مَا يُعْرَفُ بِالخُنَّاقِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16895, 'لِيبي', 'ليبي', 'منسوب', '', 'ليبي', 'لب', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": مِنَ الْبُلْدَانِ الْعَرَبِيَّةِ (الْجَمَاهِيرِيَّةُ الْعَرَبِيَّةُ اللِّيبِيَّةُ الشَّعْبِيَّةُ الاشْتِرَاكِيَّةُ الْعُظْمَى). مِنْ بُلْدَانِ الْمَغْرِبِ الْعَرَبِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16896, 'مُورِيتَاني', 'موريتاني', 'منسوب', '', 'موريتاني', 'مرتن', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '": مِنَ البُلْدَانِ العَرَبِيَّةِ (الجُمْهُورِيَّةُ الإِسْلاَمِيَّةُ الْمُورِيتَانِيَّةُ) تَقَعُ غَرْبَ إِفْرِيقْيَا جَنُوبَ الْمَغْرِبِ، مِنْ دُوَلِ الْمَغْرِبِ العَرَبِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16897, 'هِسْتِيري', 'هستيري', 'منسوب', '', 'هستيري', 'هستر', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"""وَجَدَهُ فِي حَالَةٍ مِنَ الهِيسْتِيريا"" : مَرَضٌ عَصَبِيٌّ يُفْقِد"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16898, 'داخلي', 'داخلي', 'منسوب', '', 'داخلي', 'دخل', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16899, 'خارجي', 'خارجي', 'منسوب', '', 'خارجي', 'خرج', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16900, 'غِنَائي', 'غنائي', 'منسوب', 'غني', 'غناءي', 'غن', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"غِنَاءٌ-غِنَاءٌ [غ ن ي]. ""يَتَطَرَّبُ غِنَاءً"" : التَّطْرِيبُ وَالتَّرَنُّمُ بِالكَلاَمِ مَصْحُوباً بِالْمُوسِيقَى أَوْ غَيْرَ مَصْحُوبٍ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16901, 'غَوْغَائي', 'غوغائي', 'منسوب', 'غوغ', 'غوغاءي', 'غغ', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"غَوْغَاءُ-غَوْغَاءُ [غ و غ]. 1.""مَا هَذِهِ الْغَوْغَاءُ"" : الضَّجَّة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16902, 'فِيزِيَائي', 'فيزيائي', 'منسوب', '', 'فيزياءي', 'فز', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '": عِلْمٌ يَبْحَثُ وَيَدْرُسُ الْخَوَاصَّ الْعَامَّةَ لِلْمَادَّةِ وَالْفَضَاءِ وَالزَّمَانِ، وَيُحَدِّدُ الْقَوَانِينَ الَّتِي تُظْهِرُ الظَّوَاهِرَ الطَّبِيعِيَّةَ، عِلْمُ الطَّبِيعِيَّاتِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16903, 'كِيمْيَائي', 'كيميائي', 'منسوب', '', 'كيمياءي', 'كم', '', '', 'Ta', 'جمع تكسير', 'DnT', 'PmS', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '": عِلْمٌ فِي طَبِيعَةِ الأَجْسَامِ وَعَنَاصِرِهَا وَمُرَكَّبَاتِهَا، وَمَا يَنْشَأُ عَنْهَا مِنْ تَحَوُّلاَتٍ وَتَفَاعُلاَتٍ، وَتُقْسَمُ الكِيمْيَاءُ إِلَى عِدَّةِ فُرُوعٍ: ""الكِيمْيَاءُ الفِيزْيَائِيَّةُ""، ""الكِيمْيَاءُ العُضْوِيَّةُ""، ""الكِيمْيَاءُ اللاَّعُضْوِيَّةُ""، ""الكِي"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16904, 'إِجْرَائي', 'إجرائي', 'منسوب', 'جري', 'ءجراءي', 'إجر', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"(مص. أَجْرَى). 1.""اِتَّخَذَ الضَّابِطُ إِجْرَاءً"" : قَرَارًا، تَدْبِيراً. ""اِتَّخَذَ إِجْرَاءات"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16905, 'إِحْصَائي', 'إحصائي', 'منسوب', 'حصي', 'ءحصاءي', 'إحص', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"إِحْصَاءٌ-إِحْصَاءٌ [ح ص ي] (مص. أحْصَى). ""قَامَتِ الحُكُومَةُ بِإحْصَاءِ عَدَدِ السُّكَّانِ"" : أحْصَتْهُمْ وَعَدَّدَتْهُمْ فِي لَوَائِحَ. ""اِنْشَغَلَتِ اللَّجْنَةُ بِإِحْصاءِ عَدَدِ الأَصْوَاتِ بَعْدَ انْتِهَاءِ عَمَلِيَّةِ الاقْتِرَاعِ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16906, 'بَهَائي', 'بهائي', 'منسوب', 'بهو', 'بهاءي', 'به', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"بَهَاءٌ-بَهَاءٌ [ب هـ و] (مص. بَهَى، بَهَا). 1. ""فِي حُسْنِ بَهَائِهَا"" : فِي حُسْنِ إشْرَاقِهَا وَجَمَالِهَا. ""بَهَاءُ الْمَنْظَرِ"" ""رَشَاقَةُ الخِلاَلِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16907, 'كَهْرَبَائي', 'كهربائي', 'منسوب', 'كهرب', 'كهرباءي', 'كهرب', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"كَهْرَبَاءُ-كَهْرَبَاءُ [ك هـ ر ب]. 1.: مَادَّةٌ صَفْرَاءُ اللَّوْنِ، شِبْهُ شَفَّافَةٍ، قَوِيَّةُ العَزْلِ لِلْكَهْرَبَاءِ. 2.: طَاقَةٌ طَبِيعِيَّةٌ تَتَوَلَّدُ نَتِيجَةَ ظَوَاهِرِ التَّجَاذُبِ وَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16908, 'اِسْتِقْرائي', 'استقرائي', 'منسوب', 'قرأ', 'استقراءي', 'ستقر', 'مص. اِسْتَقْرَأَ', '', '', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"اِسْتِقْراءٌ-اِسْتِقْراءٌ [ق ر أ] (مص. اِسْتَقْرَأَ). ""اِسْتِقْراءُ الوَقائِعِ"" : تَتَبُّعُها عَنْ قُرْبٍ مُعايَنَةً وَمُشاهَدَةً لِلْوُصولِ إلى أحْكامٍ عامَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16909, 'مفرد/تكسير', 'مفرد/تكسير', 'مصدر', '', 'مفرد/تكسير', 'مفرد/تكسر', '', 'مذ', 'تأنيث', 'جمع تكسير', 'تثنية', '"ج', '"ج. مؤ.س."', 'نكرة', '', '"', '"تنوين نصب"', '"', '"إض', 'لف', 'نسب', 'منقوص', 'عاقل', ':لا جذر:لا مفرد:لا تشكيل');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16910, 'تَبَوُّؤٌ', 'تبوؤ', 'مصدر', 'بوأ', 'تبوء', 'تب', ' مص. تَبَوَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَبَوُّؤٌ-تَبَوُّؤٌ [ب و أ]. ""حَاوَلَ تَبَوُّؤَ الصَّدَارَةِ"" : اِتِّخَاذُهُ مَكَانَ الصَّدَارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16911, 'تَبَلْبُلٌ', 'تبلبل', 'مصدر', 'بلبل', 'تبلبل', 'تبلبل', ' مص. تبلبل', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَلْبُلٌ-تَبَلْبُلٌ [ب ل ب ل]. 1.""تَبَلْبُلُ الأَلْسِنَةِ"" : اِخْتِلاَطُهَا. 2.""وَجَدَ فِي أَفْكَارِهِ تَبَلْبُلاً"" : اِضْطِرَاباً وَتَشَوُّشاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16912, 'تَأْسِيسٌ', 'تأسيس', 'مصدر', 'أسس', 'تءسيس', 'تسس', ' مص. أسس', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَأْسِيسٌ-تَأْسِيسٌ [أ س س]. 1.""تَأْسِيسُ عِمَارَةٍ "" : بِنَاؤُهَا، رَفْعُ قَوَاعِدِهَا. 2.""تَأَسِيسُ مَدِينَةٍ"" : بِنَاؤُهَا، تَشْيِيدُهَا، وَضْعُ أَسَاسِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16913, 'تَمَحُّصٌ', 'تمحص', 'مصدر', 'لقي', 'تمحص', 'تمحص', 'اِسْمٌ مِنَ اللِّقاءِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَحُّصٌ-تِلْقاءٌ [ل ق ي] (اِسْمٌ مِنَ اللِّقاءِ). 1.""جَلَسَ تِلْقاءَهُ"" : مُقابِلاً لَهُ، تُجاهَهُ. 2.""قامَ بِمَهامِّهِ مِنْ تِلْقاءِ نَفْسِهِ"" : د"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16914, 'جُرْحٌ', 'جرح', 'مصدر', 'جرح', 'جرح', 'جرح', 'اِسْمٌ مِنَ الجُرْحِ', '', '', 'مفرد', 'DnN', '', '', '"جِرَاحٌ:أَجْرَاحٌ:جِرَاحَاتٌ"', '', '', '', '', '', '', '', '', '"(اِسْمٌ مِنَ الجُرْحِ). ""لَمْ يُصَبْ إِلاَّ بِجُرْحٍ بَسِيطٍ"" : بِشِقٍّ فِي بَدَنِهِ يَسِيلُ مِنْهُ الدَّمُ. ""أُصِيبَ اللاَّعِبُ بِجُرُوحٍ بَالِغَةٍ"" l ""جِرَاحَاتُ السِّنَانِ لهَاَ الْتِئَامُ*وَلاَ يَلْتَامُ مَا جَرَحَ اللِّسَانُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16915, 'جِرَاحٌ', 'جراح', 'مصدر', '', 'جراح', 'جرح', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16916, 'أَجْرَاحٌ', 'أجراح', 'مصدر', '', 'ءجراح', 'جرح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16917, 'جِرَاحَاتٌ', 'جراحات', 'مصدر', '', 'جراحات', 'جرحت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16918, 'رِيٌّ', 'ري', 'مصدر', 'روي', 'ري', 'ر', 'اِسْمٌ مِن ارْتَوَى الشَّجَرُ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"رِيٌّ-رِيٌّ [ر و ي] (اِسْمٌ مِن ارْتَوَى الشَّجَرُ). 1.""يَعيشُ في رِيٍّ"" : في حُسْنِ حالٍ ونِعْمَةٍ. 2.""رِيُّ الشَّجَرِ"" : اِرْتِواؤُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16919, 'بَيْعٌ', 'بيع', 'مصدر', 'باع', 'بيع', 'بع', '', '', '', 'مفرد', 'DnN', '', '', '"بُيوعٌ"', '', 'R', '', '', '', '', '', '', '". 1.""تَمَّ بَيْعُ كُلِّ السِّلَعِ"" : تَصْرِيفُها، إِعْطاءُ السِّلَعِ وَأَخْذُ مُقابِلِها ثَمَناً. 2.""لا بَيْعَ وَلا شِراءَ"" : عِبارَةٌ تُقالُ لِكَسادِ السُّوقِ. 3.""سَيُقامُ بَيْعُ الْمَنْزِلِ بِالْمَزادِ العَلَنِيِّ"" : شِراؤُهُ بِواسِطَةِ الْمَزادِ عَلَناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16920, 'بيوع', 'بيوع', 'مصدر', '', 'بيوع', 'بع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16921, 'عِلْمٌ', 'علم', 'مصدر', 'علم', 'علم', 'علم', ' مص. عَلِمَ', '', '', 'مفرد', 'DnN', '', '', '"علوم"', '', 'Rp', '', '', '', '', '', '', '" [ع ل م] (مص. علم). 1.""له علم بحقيقة الأمور"" : إدراك الأمور على حقيقتها، له معرفة بها. ""لا علم له بما حصل"". 2. ""العلم نور"" : ما يقذفه الله في قلب من يحب. 3. ""علم: ج: علوم  الْمَعْرِفَةُ، مَسَائِلُ تَمَسُّ مَوْضُوعاً مُعَيَّناً وَتَبْحَثُ أُصُولَهُ وَقَوَانِينَهُ : عُلُومُ اللُّغَةِ الْعَرَبِيَّةِ : عِلْمُ النَّحْوِ وَعِلْمُ الْبَلاَغَةِ... وَعُلُومُ الطَّبِيعَةِ : عِلْمُ الْكِيمِيَاءِ وَالْفِيزِيَاءِ وَعِلْمُ الْفَلَكِ وَعِلْمُ النَّبَاتِ وَالحَيَوَانِ... وَالْعُلُومُ التَّطْبِيقِيَّةُ : عِلْمُ الطِّبِّ وَعِلْمُ الهَنْدَسَةِ وَالعُلُومُ الإِنْسَانِيَّةُ : الأَدَبُ وَالتَّارِيخُ وَالاجْتِمَاعُ وَالقَانُونُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16922, 'عُلُومٌ', 'علوم', 'مصدر', '', 'علوم', 'علم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16923, 'دَرَكٌ', 'درك', 'مصدر', 'درك', 'درك', 'درك', 'اِسْمُ مَصْدَرٍ مِنَ الإدْرَاك', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"دَرَكٌ-دَرَكٌ [د ر ك] (اِسْمُ مَصْدَرٍ مِنَ الإدْرَاكِ). 1. ""حَاوَلَ الدَّرَكَ بِهِ"" : اللَّحَاقَ بِهِ. 2. ""بَلَغَ الدَّرَكَ الأسْفَلَ"" : أسْفَلَ سَافِلِينَ، أقْصَى حَدٍّ. ""يَرَى بِأُمِّ عَيْنِهِ الدَّرَكَ الَّذِي انْحَدَرَتْ إلَيْهِ الأَخْلاَقُ"" ""بَلَغَ الغَوَّاصُ دَرَكَ البَحْرِ"". 3. ""اِسْتَدْعَاهُ رِجَالُ الدَّرَكِ"" : قُوَّاتُ الشُّرْطَةِ العَسْكَرِيَّةِ تُحَافِظُ عَلَى الأمْنِ العَامِّ، وَبِالأخَصِّ فِي الطُّرُقِ وَالبَوَادِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16924, 'صَحْوَةٌ', 'صحوة', 'مصدر', 'صحو', 'صحوة', 'صحة', 'اِسْمُ الْمَرَّةِ مِنَ الصَّحْ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(اِسْمُ الْمَرَّةِ مِنَ الصَّحْوِ). 1.""صَحْوَةُ النَّائِمِ"" : يَقَظَتُهُ. 2.""صَحْوَةُ النَّهارِ"": اِرْتِفاعُ النَّهارِ. ""يُعَانِقُ وَجْهَ الشَّمْسِ فِي صَحْوَةِ النَّهَارِ"" (م. ل. المنفلوطي). 3.""الصَّحْوَةُ الإِسْلاَمِيَّةُ"" : الوَثْبَةُ، اليَقَظَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16925, 'غَلْطَةٌ', 'غلطة', 'مصدر', 'غلط', 'غلطة', 'غلطة', 'اِسْمُ الْمَرَّةِ مِنَ الغَلَط', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(اِسْمُ الْمَرَّةِ مِنَ الغَلَطِ). 1.""اِرْتَكَبَ غَلْطَةً فَادِحَةً"" : خَطَأً. 2.""فِي النَّصِّ غَلْطَةٌ مَطْبَعِيَّةٌ"": تَصْحِيفٌ مُخَالِفٌ لِمَا فِي النَّصِّ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16926, 'بَتَّةٌ', 'بتة', 'مصدر', '', 'بتة', 'بتة', 'اِسْمُ الْمَرَّةِ مِنْ: بَتٌّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"بَتَّةٌ-بَتَّةٌ، البَتَّة (اِسْمُ الْمَرَّةِ مِنْ: بَتٌّ).""الخَمْرُ لَنْ أشْرَبَهُ البَتَّةَ"" : قَطْعاً، نِهَائِيّاً، قَرَارٌ لاَ رِجْعَةَ فِيه. ""هَذَا عَمَلٌ لَنْ أَقومَ بِهِ البَتَّةَ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16927, 'خَفْقَةٌ', 'خفقة', 'مصدر', 'خفق', 'خفقة', 'خفقة', 'اِسْمُ الْمَرَّةِ مِنْ خَفَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(اِسْمُ الْمَرَّةِ مِنْ خَفَقَ). ""تَوَالَتْ خَفَقَاتُ قَلْبِهِ"" : دَقَّاتُهُ الْمُتَسَارِعَةُ، نَبَضَاتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16928, 'دَوْرَةٌ', 'دورة', 'مصدر', 'دور', 'دورة', 'درة', 'اِسْمُ الْمَرَّةِ مِنْ دارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"دَوْرَةٌ-دَوْرَةٌ [د و ر] (اِسْمُ الْمَرَّةِ مِنْ دارَ). 1.""الدَّوْرَةٌ الدَّمَويَّةُ"" : جَرَيانُ الدَّمِ في حَرَكَتِهِ الدَّائِمَةِ في الجِسْمِ مِنَ الأَوْرِدَةِ إلى الشَّرَايِينِ وِمِنَ الشَّرايينِ إلى الأَوْرِدَةِ. 2.""دَوْرَةُ الحَياةِ"" : مُخْتَلِفُ الْمَراحِلِ الَّتِي يَمُرُّ بِها الكائِنُ الحَيُّ مِنْ إِنْتاجِهِ إلى إِعادَةِ إِنْتاجِهِ. 3.""دَوْرَةُ المِياهِ"" : المِرْحاضُ أَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16929, 'رَوْحَةٌ', 'روحة', 'مصدر', 'روح', 'روحة', 'رحة', 'اِسْمُ الْمَرَّةِ مِنْ راحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(اِسْمُ الْمَرَّةِ مِنْ راحَ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16930, 'رَكْلَةٌ', 'ركلة', 'مصدر', 'ركل', 'ركلة', 'ركلة', 'اِسْمُ الْمَرَّةِ مِنْ رَكَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(اِسْمُ الْمَرَّةِ مِنْ رَكَلَ). ""قالَ الأَعْرابِيُّ : لأَرْكُلَنَّكَ رَكْلَةً لاَ تَأْكُلُ بَعْدَها أَكْلَةً"" : أَيْ لأَضْرِبَنَّكَ بِرِجْلِي ضَرْبَةً قاضِيَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16931, 'رَنَّةٌ', 'رنة', 'مصدر', 'رنن', 'رنة', 'رنة', 'اِسْمُ الْمَرَّةِ مِنَ رَنَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"رَنَّةٌ-رَنَّةٌ [ر ن ن ] (اِسْمُ الْمَرَّةِ مِنَ رَنَّ). 1.""رَنَّةُ القَّوْسِ"" : طَنينُها. 2.""في صَوْتِها رَنَّةٌ"" : صَوْتٌ فيهِ حُزْنٌ عِنْدَ الغِنَاءِ أَوِ البُكاءِ. 3.""سَمِعْتُ رَنَّتَها مِنْ بَعيدٍ"" : الصَّيْحَةُ ذاتُ الصَّوْتِ الْمُرْتَفِعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16932, 'كَيَّةٌ', 'كية', 'مصدر', 'كوي', 'كية', 'كة', 'اسْمُ الْمَرَّةِ مِنْ كَوَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"كَيَّةٌ-كَيَّةٌ [ك و ي] (اسْمُ الْمَرَّةِ مِنْ كَوَى). 1.""كَوَاهُ كَيَّةً وَاحِدَةً"" : حَرْقَة الجِلْدِ بِحَدِيدَةٍ مُحَمَّاةٍ. 2.""ما تَزَالُ الكَيَّةُ تُؤْلِمُهُ"" : مَوْضِعُ الكَيِّ عِنْدَمَا يُكْوَى الْمَرْءُ بِحَدِيدَةٍ مُحَمَّاةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16933, 'نَجْوَةٌ', 'نجوة', 'مصدر', 'نجو', 'نجوة', 'نجة', 'اِسْمُ الْمَرَّةِ مِنْ نَجَا', '', '', 'مفرد', 'DnN', '', 'Pf', '":نِجَاءٌ"', '', 'R', '', '', '', '', '', '', '"(اِسْمُ الْمَرَّةِ مِنْ نَجَا). ""بِنَجْوَةٍ مِنْ كُلِّ شَرٍّ"" : بِمَنْجىً، فِي مَأْمَنٍ... بَعِيد عَنْ كُلِّ شَرٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16934, 'نِجَاءٌ', 'نجاء', 'مصدر', '', 'نجاء', 'نج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16935, 'نَدْوَةٌ', 'ندوة', 'مصدر', 'ندو', 'ندوة', 'ندة', 'اسْمُ الْمَرَّةِ مِنْ نَدَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَدْوَةٌ-نَدْوَةٌ [ن د و] (اسْمُ الْمَرَّةِ مِنْ نَدَا). 1.""نَدْوَةُ الْجَمَاعَةِ"" : اِجْتِمَاعُهُمْ. 2.""دَارُ النَّدْوَةِ"" : الدَّارُ الَّتِي يَجْتَمِعُ فِيهَا القَوْمُ. 3.""شَارَكَ فِي نَدْوَةٍ عِلْمِيَّةٍ"" : فِي لِقَاءٍ، فِي مُجْتَمَعٍ لِلْمُحَاوَرَةِ العِلْمِيَّةِ. ""نَدْوَةٌ ثَقَافِيَّةٌ"". 4.""نَدْوَةٌ دَوْلِيَّةٌ"" : مُؤْتَمَرٌ يَجْتَمِعُ فِيهِ نُخْبَةٌ مِنَ العُلَمَاءِ أَوِ الْخُبَرَاءِ. 5. ""نَدْوَةٌ صَحَفِيَّةٌ "" : لِقَاءٌ بَيْنَ صَحَفِيِّينَ وَشَخْصِيَّةٍ مَسْؤُولَةٍ لِلتَّحَدُّثِ وَالاسْتِفْسَارِ عَنْ مَوْضُوعٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16936, 'مَآبٌ', 'مآب', 'مصدر', 'أوب', 'مءءب', 'مآب', 'مص. آب', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَآوِبُ"', '', 'R', '', '', '', '', '', '', '"(مص. آب). 1.""مَآبُهُ إِلىَ الله"" : أَيْ تَوْبَتُهُ إِلَى اللهِ وَإِلَيْهِ مَرْجِعُهُ، مَكَانُ الرُّجُوعُ.ص آية 25 وَإِنَّ لَهُ عِنْدَنَا لَزُلْفَى وَحُسْنَ مَآبٍ (قرآن). 2.""بَيْنَهُمَا ثَلاَثَةُ مَآوِبَ"" : ثَلاَثُ رِحَلٍ فِي النَّهَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16937, 'مَآوِبُ', 'مآوب', 'مصدر', '', 'مءءوب', 'مآب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16938, 'أوْبٌ', 'أوب', 'مصدر', 'أوب', 'ءوب', 'ب', 'مص. آبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أوْبٌ-أوْبٌ [أ و ب] (مص. آبَ). 1.""جَاءوا مِنْ كُلِّ أوْبٍ وَصَوْبٍ"" : مِنْ كُلِّ جِهَةٍ، نَاحِيَةٍ، وَجْهِ. 2.""كَانَ أوْبُهُ مَيْمُوناً"": رُجُوعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16939, 'إيابٌ', 'إياب', 'مصدر', 'أوب', 'ءياب', 'إب', 'مص. آبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إيابٌ-إيابٌ [أ و ب] (مص. آبَ). 1.""أخَذَ تَذْكِرَةً ذَهَاباً وإياباً"" : ذَهَاباً وَرُجوعاً. 2.""إلَى اللَّهِ الإيَابُ"" : إلَيْهِ التَّوْبَةُ وَالرُّجُوعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16940, 'إبَاتَةٌ', 'إباتة', 'مصدر', 'بيت', 'ءباتة', 'إبتة', 'مص. أبَاتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إبَاتَةٌ-إبَاتَةٌ [ب ي ت] (مص. أبَاتَ). ""إِبَاتَةُ الضَّيْفِ"" : جَعْلُهُ يَبِيتُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16941, 'إبَاحَةٌ', 'إباحة', 'مصدر', 'بوح', 'ءباحة', 'إبحة', 'مص. أبَاحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"إبَاحَةٌ-إبَاحَةٌ [ب و ح] (مص. أبَاحَ). ""إِبَاحَةُ مَا هُوَ مَحْظَورٌ"": إجَازتُهُ وَالسَّمَاحُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16942, 'إِبَادَةٌ', 'إبادة', 'مصدر', 'بيد', 'ءبادة', 'إبدة', 'مص. أبَادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِبَادَةٌ-إِبَادَةٌ [ب ي د] (مص. أبَادَ). 1.""عَرَفَ التَّارِيخُ حُرُوبَ إبَادَةٍ"": أَيْ حُرُوبَ تَدْمِيرٍ وَفَتْكٍ. 2.""اُستُعْمِلَتْ مَوَادُّ سَامَّةٌ لإبَادَةِ الجَرَادِ الَّذِي ظَهَرَ فَجْأَةً"" : لِلقَضَاءِ عَلَيْهِ، لِسَحْقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16943, 'إِبَانَةٌ', 'إبانة', 'مصدر', 'بين', 'ءبانة', 'إبنة', 'مص. أبَانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِبَانَةٌ-إِبَانَةٌ [ب ي ن] (مص. أبَانَ). ""اِلْتَزَمَ بِالإِبَانَةِ عَنْ آرائِهِ وَأفْكَارِهِ وَأَهْدَافِهِ"" : بِإِظْهَارِهَا وَالْكَشْفِ عَنْهَا، بإيضَاحِهَا وَتَوْضِيحِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16944, 'أُبُوَّةٌ', 'أبوة', 'مصدر', 'أبو', 'ءبوة', 'بة', 'مص. أبَا، يَأْبُو', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"أُبُوَّةٌ-أُبُوَّةٌ [ أ ب و] (مص. أبَا، يَأْبُو). 1.""يَمْتَازُ بِأُبُوَّةٍ رَقِيقَةٍ"": صِفَةُ الأبِ. 2.""عُرِفَتْ تِلْكَ العَائِلَةُ بِأُبُوَّةٍ مِثَالِيَّةٍ"": الرَّابِطَةُ الطَّبِيعِيَّةُ أَوِ الشَّرْعِيَّةُ بَيْنَ الأبِ وَالأوْلاَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16945, 'اِبْتِئَاسٌ', 'ابتئاس', 'مصدر', 'بأس', 'ابتءاس', 'بتس', 'مص. اِبْتَأسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِبْتِئَاسٌ-اِبْتِئَاسٌ [ب أ س] (مص. اِبْتَأسَ). ""وَجَدَهُ فِي اِبْتِئَاسٍ"": فِي حُزْنٍ وَغَمٍّ وَسُوءِ حالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16946, 'اِبْتِيَاعٌ', 'ابتياع', 'مصدر', 'بىع', 'ابتياع', 'بتع', 'مص. اِبْتَاعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِبْتِيَاعٌ-اِبْتِيَاعٌ [ب ى ع] (مص. اِبْتَاعَ). ""ذَهَبَ لِابْتِيَاعِ مَا يَحْتَاجُهُ مِنَ الْمَتْجَرِ"" : لِشِرَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16947, 'اِبْتِداءٌ', 'ابتداء', 'مصدر', 'بدأ', 'ابتداء', 'بتد', 'مص. اِبتدَأ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِبْتِداءٌ-اِبْتِداءٌ [ب د أ] (مص. اِبتدَأ). ""اِبْتِدَاءُ العَمَلِ"" : بَدْؤُهُ والشُّرُوعُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16948, 'اِبْتِداعٌ', 'ابتداع', 'مصدر', 'بدع', 'ابتداع', 'بتدع', 'مص. اِبْتَدَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِبْتِداعٌ-اِبْتِداعٌ [ب د ع] (مص. اِبْتَدَعَ). ""اِبْتِدَاعُ أسَالِيبَ جَدِيدَةٍ"" : إِنْشَاؤُها عَلَى غَيْرِ مِثَالٍ سَابِقٍ. ""تَفَنَّنُوا فِي ابْتِدَاعِ أسَالِيبَ الوِقايَةِ مِنَ الغَارَاتِ"" (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16949, 'اِبْتِذَالٌ', 'ابتذال', 'مصدر', 'بذل', 'ابتذال', 'بتذل', 'مص. اِبْتِذَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِبْتِذَالٌ-اِبْتِذَالٌ [ب ذ ل] (مص. اِبْتِذَلَ). ""عَرَّضَ نَفْسَهُ لِلابْتِذَالِ"" : لِعَدَمِ الحُرْمَةِ وَالاحْتِشَامِ، كَوْنُ الشَّيْءِ مُبْتَذَلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16950, 'اِبْتِزَازٌ', 'ابتزاز', 'مصدر', 'بزز', 'ابتزاز', 'بتزز', 'مص. اِبْتَزَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِبْتِزَازٌ-اِبْتِزَازٌ [ب ز ز] (مص. اِبْتَزَّ). ""إيَّاكَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16951, 'اِبْتِسَامٌ', 'ابتسام', 'مصدر', 'بسم', 'ابتسام', 'بتسم', 'مص. اِبْتَسَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِبْتِسَامٌ-اِبْتِسَامٌ [ب س م] (مص. اِبْتَسَمَ). ""كَانَ ابْتِسَامُهُ عَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16952, 'اِبْتِعَادٌ', 'ابتعاد', 'مصدر', 'بعد', 'ابتعاد', 'بتعد', 'مص. اِبْتَعَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِبْتِعَادٌ-اِبْتِعَادٌ [ب ع د] (مص. اِبْتَعَدَ). 1.""الاِبْتِعَادُ عَنِ الْمَكَارِهِ وَالْمَخَاطِرِ"" : عَدَمُ الاْقْتِرَابِ مِنْهَا. 2.""الاِبْتِعَادُ عَنِ الأَهْلِ"" : مُفَارَقَتُهُمْ. 3.""الاْبْتِعَادُ عَنِ الدَّارِ"" : البُعْدُ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16953, 'اِبْتِغَاءٌ', 'ابتغاء', 'مصدر', 'بغي', 'ابتغاء', 'بتغ', 'مص. اِبْتَغى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِبْتِغَاءٌ-اِبْتِغَاءٌ [ب غ ي] (مص. اِبْتَغى). ""اِبْتِغَاءُ الخَيْرِ"" : طَلَبُهُ وَالرَّغبَةُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16954, 'اِبْتِكَارٌ', 'ابتكار', 'مصدر', 'بكر', 'ابتكار', 'بتكر', 'مص. اِبْتَكَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. اِبْتَكَرَ). 1.""أُعْلِنَ عَن ابْتِكَارٍ جَدِيدٍ"" : عَنِ اخْتِرَاعٍ، اِبْتِدَاعٍ. ""يَعُجُّ الْمَعْرِضُ الدَّوْلِيُّ بِابْتِكَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16955, 'اِبْتِلاَعٌ', 'ابتلاع', 'مصدر', 'بلع', 'ابتلاع', 'بتلع', 'مص. اِبْتَلَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِبْتِلاَعٌ-اِبْتِلاَعٌ [ب ل ع] (مص. اِبْت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16956, 'اِبْتِلاَءٌ', 'ابتلاء', 'مصدر', 'بلي', 'ابتلاء', 'بتل', 'مص. اِبْتَلَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِبْتِلاَءٌ-اِبْتِلاَءٌ [ب ل ي ] (مص. اِبْتَلَى). ""اِبْتِلاَءُ الإنْسَانِ"" : اِخْتِبَارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16957, 'اِبْتِنَاءٌ', 'ابتناء', 'مصدر', 'بني', 'ابتناء', 'بتن', 'مص. اِبْتَنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِبْتِنَاءٌ-اِبْتِنَاءٌ [ب ن ي] (مص. اِبْتَنَى)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16958, 'اِبْتِهَاجٌ', 'ابتهاج', 'مصدر', 'بهج', 'ابتهاج', 'بتهج', 'مص. اِبْتَهَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِبْتِهَاجٌ-اِبْتِهَاجٌ [ب هـ ج] (مص. اِبْتَهَجَ). ""عَمَّ الابْتِهَاجُ الحَفْلَ"" : الفَرَحُ، السُّرُورُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16959, 'اِبْتِهَالٌ', 'ابتهال', 'مصدر', 'بهل', 'ابتهال', 'بتهل', 'مص. اِبْتَهَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِبْتِهَالٌ-اِبْتِهَالٌ [ب هـ ل] (مص. اِبْتَهَلَ). ""وَقَفُوا فِي خُشُوعٍ وَابْتِهَالٍ"" : فِي تَضَرُّعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16960, 'إبْحَارٌ', 'إبحار', 'مصدر', 'بحر', 'ءبحار', 'إبحر', 'مص. أبْحَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إبْحَارٌ-إبْحَارٌ [ب ح ر] (مص. أبْحَرَ). 1.""قَرَّرَ الإبْحَارَ"": رُكُوبَ البَحْرِ. 2.""إبْحَارُ السَّفِينَةِ"" : إقْلاَعُهَا بِدُخُولِهَا البَحْرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16961, 'تَأْبِيدٌ', 'تأبيد', 'مصدر', 'أبد', 'تءبيد', 'تبد', 'مص. أَبَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْبِيدٌ-تَأْبِيدٌ [أ ب د] . (مص. أَبَّدَ). ""تَأْبِيدُ أَعْمالِ الإِنْسانِ"" : تَخْلِيدُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16962, 'أبَدٌ', 'أبد', 'مصدر', 'أبد', 'ءبد', 'بد', 'مص. أبِدَ.', '', '', 'مفرد', 'DnN', '', '', '"آبَادٌ"', '', 'Rp', '', '', '', '', '', '', '"ج: آبَادٌ. (مص. أبِدَ). 1.""سَيَبْقَى هَذَا الأثَرُ أبَدَ الآبِدِينَ"" : سَيَظَلُّ قَائِمًا أزَليّاً. ""أبَدَ الدَّهْرِ"" ""الدُّنيا أمَدٌ وَالآخِرَةُ أبَدٌ"". (أبو عبد الرحمان الخليل). 2.""سَأحْتَفِظُ بِذِكْرَاكَ إِلَى الأبَدِ"" : عَلَى الدَّوامِ، دَائِماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16963, 'آبَادٌ', 'آباد', 'مصدر', '', 'ءءباد', 'آبد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16964, 'إِبْدَاعٌ', 'إبداع', 'مصدر', 'بدع', 'ءبداع', 'إبدع', 'مص. أبْدَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"إِبْدَاعٌ-إِبْدَاعٌ [ب دع] (مص. أبْدَعَ). ""فَنٌّ فِيهِ إِبْدَاعٌ"" : الإتْيَانُ بِشَيءٍ لاَ نَظِيرَ لَهُ، فِيهِ جَوْدَةٌ وَإِتْقَانٌ، خَلْقٌ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16965, 'إبدالٌ', 'إبدال', 'مصدر', 'بدل', 'ءبدال', 'إبدل', 'مص. أبدل', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16966, 'إبْداءٌ', 'إبداء', 'مصدر', 'بدو', 'ءبداء', 'إبد', 'مص. أبْدَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إبْداءٌ-إبْداءٌ [ب د و] (مص. أبْدَى). 1.""إبْدَاءُ الشَّجَاعَةِ"" : إظْهَارُهَا. 2.""إبْدَاءُ الرَّأْيِ"" : التَّعْبِيرُ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16967, 'إبْرَارٌ', 'إبرار', 'مصدر', 'برر', 'ءبرار', 'إبرر', 'مص. أبَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إبْرَارٌ-إبْرَارٌ [ب ر ر] (مص. أبَرَّ). 1.""الإبْرارُ إلَى بِلاَدِ الغَرْبِ"" : السَّفَرُ إِلَيْهَا عَنْ طَرِيقِ البَرِّ. 2."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16968, 'إِبْرَاحٌ', 'إبراح', 'مصدر', 'برح', 'ءبراح', 'إبرح', 'مص. أَبْرَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِبْرَاحٌ-إِبْرَاحٌ [ب رح] (مص. أَبْرَحَ). 1.""كَانَ الإبراحُ بِهِ انْتِقَامًا"" : الإلْحَاحُ عَلَيْهِ بِالأَذى وَالمشَقَّةِ. 2.""الإِبْرَاحُ عَنِ الْمَكَانِ"" : الاِنْزِيَاحُ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16969, 'إِبْرَازٌ', 'إبراز', 'مصدر', 'برز', 'ءبراز', 'إبرز', 'مص. أَبْرَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِبْرَازٌ-إِبْرَازٌ [ب ر ز] (مص. أَبْرَزَ). ""طَلَبَ مِنْهُ إِبْرَازَ مَا يُخَبِّئُ"" : أ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16970, 'إِبْرَاقٌ', 'إبراق', 'مصدر', 'برق', 'ءبراق', 'إبرق', 'مص. أَبْرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِبْرَاقٌ-إِبْرَاقٌ [ب رق] (مص. أَبْرَقَ). 1.""إِبْرَاقُ السَّمَاءِ"": إتْيَانُهَا ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16971, 'إبْرَامٌ', 'إبرام', 'مصدر', 'برم', 'ءبرام', 'إبرم', 'مص. أَبْرَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إبْرَامٌ-إبْرَامٌ [ب ر م] (مص. أَبْرَمَ). 1.""إِبْرَامُ الحَبْلِ"" : فَتْلُهُ، أَيْ جَعْلُهُ طَاقَيْنِ. 2.""اِتَّفَقُوا عَلَى إِبْرَامِ اِتِّفَاقِيَّةٍ جَدِيدَةٍ"" : عَقْدُهَا، إِحْكَامُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16972, 'إبْصَارٌ', 'إبصار', 'مصدر', 'بصر', 'ءبصار', 'إبصر', 'مص. أبْصَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إبْصَارٌ-إبْصَارٌ [ب ص ر] (مص. أبْصَرَ). ""قُوَّةُ الإبْصَارِ"" : قُوَّةُ النَّظَرِ، الرُّؤْيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16973, 'إبْطَاءٌ', 'إبطاء', 'مصدر', 'بطأ', 'ءبطاء', 'إبط', 'مص. أَبْطَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إبْطَاءٌ-إبْطَاءٌ [ب ط أ] (مص. أَبْطَأَ). 1.""كَانَتِ القَافِلَةُ تَسِيرُ فِي إِبْطَاءٍ شَدِيدٍ"" : تَسِيرُ عَلَى مَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16974, 'إِبْطَالٌ', 'إبطال', 'مصدر', 'بطل', 'ءبطال', 'إبطل', 'مص. أَبْطَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِبْطَالٌ-إِبْطَالٌ [ب ط ل] (مص. أَبْطَلَ). ""إبْطَالُ الحُكْمِ السَّابِقِ"" : إِلْغَاؤُهُ، أَيْ جَعْلُهُ غَيْرَ نَافِذٍ لاَ مَفْعُولَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16975, 'إبْعَادٌ', 'إبعاد', 'مصدر', 'بعد', 'ءبعاد', 'إبعد', 'مص. أبْعَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إبْعَادٌ-إبْعَادٌ [ب ع د] (مص. أبْعَدَ). 1.""تَقَرَّرَ إِبْعَادُهُ عَنِ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16976, 'إبْغَاضٌ', 'إبغاض', 'مصدر', 'بغض', 'ءبغاض', 'إبغض', 'مص. أبْغَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إبْغَاضٌ-إبْغَاضٌ [ب غ ض] (مص. أبْغَضَ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16977, 'إِبْغَاءٌ', 'إبغاء', 'مصدر', 'بغي', 'ءبغاء', 'إبغ', 'مص. أَبْغَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِبْغَاءٌ-إِبْغَاءٌ [ب غ ي] (مص. أَبْغَى). 1.""إِبْغَاءُ الشَّي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16978, 'إِبْقَاءٌ', 'إبقاء', 'مصدر', 'بقي', 'ءبقاء', 'إبق', 'مص. أَبْقَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِبْقَاءٌ-إِبْقَاءٌ [ب ق ي] (مص. أَبْقَى). ""قَرَّرَ إِبْقَاءهُ فِي مَنْصِبهِ"" : إِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16979, 'إِبْكَارٌ', 'إبكار', 'مصدر', 'بكر', 'ءبكار', 'إبكر', 'مص. أَبْكَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِبْكَارٌ-إِبْكَارٌ [ب ك ر] (مص. أَبْكَرَ). ""ألِفَ الإِبْكَارَ إِلَى العَمَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16980, 'إِبْكاءٌ', 'إبكاء', 'مصدر', 'بكي', 'ءبكاء', 'إبك', 'مص. أَبْكَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِبْكاءٌ-إِبْكاءٌ [ب ك ي] (مص. أَبْكَى). ""لَمْ يَكُنْ إِبْكَاؤُه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16981, 'إِبْلاَجٌ', 'إبلاج', 'مصدر', 'بلج', 'ءبلاج', 'إبلج', 'مص. أَبْلَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِبْلاَجٌ-إِبْلاَجٌ [ب ل ج] (مص. أَبْلَجَ). 1.""إبْلاَجُ الصُّبْحِ"" : إِشْرَاقُهُ، إضَاءتُهُ. 2.""إِبْلاَجُ الحَقِّ"" : ظُهُورُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16982, 'إِبْلاَغٌ', 'إبلاغ', 'مصدر', 'بلغ', 'ءبلاغ', 'إبلغ', 'مص. أَبْلَغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِبْلاَغٌ-إِبْلاَغٌ [ب ل غ] (مص. أَبْلَغَ). 1.""قَرَّرَ الإبْلاَغَ بالحَادِثِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16983, 'إِبْلاءٌ', 'إبلاء', 'مصدر', 'بلي', 'ءبلاء', 'إبل', 'مص. أَبْلَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِبْلاءٌ-إِبْلاءٌ [ب ل ي] (مص. أَبْلَى). 1.""إِبْلاَءُ الثَّوْبِ"": تَصْيِير"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16984, 'تَأْبِينٌ', 'تأبين', 'مصدر', 'أبن', 'تءبين', 'تبن', 'مص. أَبَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْبِينٌ-تَأْبِينٌ [أ ب ن] (مص. أَبَّنَ). ""أُقِيمَتْ حَفْلَة تَأْبِينٍ فِي الذِّكْرَى الأَرْبَعِينِيَّةِ"" : حَفْلَةٌ لِذِكْرِ مَآثِرِ الْمَيِّتِ وَمَحَاسِنِهِ وَالثَّنَاءِ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16985, 'إبْهاجٌ', 'إبهاج', 'مصدر', 'بهج', 'ءبهاج', 'إبهج', 'مص. أبْهَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إبْهاجٌ-إبْهاجٌ [ب هـ ج] (مص. أبْهَجَ). 1.""حَاوَلَ إبْهاجَهُ"": إفْرَاحَهُ، إدْخالَ السُّرورِ عَلَيْهِ. 2.""وَجَدَ فِي الحَفْلِ إِبْهَاجاً"" : بَهْجَةً، مَسَرَّةً. 3. ""إِبْهَاجُ الأَرْضِ"" : حُسْنُ نَباتِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16986, 'إِبْهَارٌ', 'إبهار', 'مصدر', 'بهر', 'ءبهار', 'إبهر', 'مص. أبْهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِبْهَارٌ-إِبْهَارٌ [ب هـ ر] (مص. أبْهَرَ). 1.""سَعَى إلى إبْهارِهِ"": إلى إدْهاشِهِ وإِثارَةِ إِعْجَابِهِ. 2.""إِبْهَارُ الضَّوْءِ"" : قُوَّةُ نُورِهِ ولَمَعَانِهِ. ""إِبْهَارُ الضَّوْءِ أفْقَدَهُ البَصَرَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16987, 'إبْهاظٌ', 'إبهاظ', 'مصدر', 'بهظ', 'ءبهاظ', 'إبهظ', 'مص. أَبْهَظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إبْهاظٌ-إبْهاظٌ [ب هـ ظ] (مص. أَبْهَظَ). ""نَاءَ تَحْتَ إِبْهَاظِ الحِمْلِ أوِ الدَّيْن"" : مَشَقَّتُهُ وَثِقْلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16988, 'إِبْهَامٌ', 'إبهام', 'مصدر', 'بهم', 'ءبهام', 'إبهم', 'مص. أَبْهَمَ. ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أبَاهِيمُ(مذ:مؤ)"', '', 'R', '', '', '', '', '', '', '"ج: أبَاهِيمُ. (مذ، مؤ) (مص. أَبْهَمَ). 1.""فِي كَلاَمِهِ إِبْهَامٌ"" : تَعْمِيَةٌ وَالتِبَاسٌ وَغُمُوضٌ. 2. ""أصَابِعُ اليَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16989, 'أبَاهِيمُ', 'أباهيم', 'مصدر', '', 'ءباهيم', 'بهم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16990, 'إِبْهَاءٌ', 'إبهاء', 'مصدر', 'بهي', 'ءبهاء', 'إبه', 'مص. أبْهَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِبْهَاءٌ-إِبْهَاءٌ [ب هـ ي] (مص. أبْهَى). ""إبْهَاءُ الوَجْهِ"" : حُسْنُهُ، جمالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16991, 'إبَاءٌ', 'إباء', 'مصدر', 'أبي', 'ءباء', 'إب', 'مص. أبَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إبَاءٌ-إبَاءٌ [أ ب ي] (مص. أبَى). ""هُوَ مَعْرُوفٌ بِإِبَائِهِ"" : مَعْرُوفٌ بعِزَّةِ نَفسِهِ وَأَنَفَتِهِ وَكِبْرِيائِه. ""نَظْرَةٌ جَامِدَةٌ تَنْطِقُ إِبَاءً"". (ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16992, 'اِبْيِضاضٌ', 'ابيضاض', 'مصدر', 'بيض', 'ابيضاض', 'بضض', 'مص. اِبْيَضَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِبْيِضاضٌ-اِبْيِضاضٌ [ب ي ض] (مص. اِبْيَضَّ). 1.""اِبْيضاضُ الوَجْهِ"" : صَيْرُهُ أَبْيَضَ. 2. ""اِبْيضاض الشَّعْرِ"" : شَيْبُهُ. 3.""اِبْيضَاضُ الجِبال بِالثَّلْجِ"" : نُصُوعُ بَيَاضِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16993, 'إتَاحَةٌ', 'إتاحة', 'مصدر', 'تيح', 'ءتاحة', 'إتحة', 'مص. أَتَاحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إتَاحَةٌ-إتَاحَةٌ [ت ي ح] (مص. أَتَاحَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16994, 'اِتِّئَادٌ', 'اتئاد', 'مصدر', 'وأد', 'اتءاد', 'تد', 'مص. اِتَّأَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّئَادٌ-اِتِّئَادٌ [و أ د] (مص. اِتَّأَدَ). ""اِتِّئادُ خَطَواتِهِ"" : سَيرهُ فِي تَأَنٍّ وَتَمَهُّلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16995, 'إِ‏تْبَاعٌ', 'إ‏تباع', 'مصدر', 'تبع', 'ء‏تباع', 'إ‏تبع', 'مص. أَتْبَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِ‏تْبَاعٌ-إِ‏تْبَاعٌ [ت ب ع] (مص. أَتْبَعَ). 1.""حَاوَلَ إِتْبَاعَ خَطَوَاتِهِ"" : ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16996, 'اِتِّبَاعٌ', 'اتباع', 'مصدر', 'تبع', 'اتباع', 'تبع', 'مص. اِتَّبَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّـبَاعٌ-اِتِّـبَاعٌ [ت ب ع] (مص. اِتَّبَعَ). 1.""سَعَى إلَى اِتِّبَاعِ خُطوَاتِهِ"" : اِقْتِفَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16997, 'إِتْجَارٌ', 'إتجار', 'مصدر', 'تجر', 'ءتجار', 'إتجر', 'مص. أَتْجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِتْجَارٌ-إِتْجَارٌ [ت ج ر] (مص. أَتْجَرَ). ""الإتْجَارُ فِي مُخْتَلِفِ الْمَوَادِّ"": تَعَاطي تِجَارَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16998, 'اِتِّجَارٌ', 'اتجار', 'مصدر', 'تجر', 'اتجار', 'تجر', 'مص. اِتَّجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّجَارٌ-اِتِّجَارٌ [ت ج ر] (مص. اِتَّجَرَ). ""يُفَكِّرُ فِي الِاتِّجَارِ"": فِي تَعَاطِي التِّجَارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(16999, 'اِتِّجَاهٌ', 'اتجاه', 'مصدر', 'وجه', 'اتجاه', 'تجه', 'مص. اِتَّجَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّجَاهٌ-اِتِّجَاهٌ [و ج هـ] (مص. اِتَّجَهَ). 1.""مَشَى فِي اِتِّجَاهٍ مُعَاكِسٍ"" : فِي وِجْهَةٍ مُعَاكِسَةٍ. 2.""شَارِعٌ لَهُ اتجَاهٌ وَحِيدٌ"" : مَمَرٌّ وَحِيدٌ. 3.""اِخْتَارَت اتِّجَاهًا عِلْمِيّاً يُنَاسِبُهَا"" : مَسَاراً. 4.""لَهُ اتِّجَاهٌ سِيَاسِيٌّ مَعْرُوفٌ"" : مَيْلٌ، اِسْتِجَابَةٌ لِمَوْقِفٍ. ""اِتِّجَاهَاتٌ مُخْتَلِفَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17000, 'اِتِّحَادٌ', 'اتحاد', 'مصدر', 'أحد،وحد', 'اتحاد', 'تحد', 'مص. اِتَّحَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. اِتَّحَدَ). 1.""فيِ اتِّحادِكُمْ قُوَّةٌ"" : فِي اجْتِمَاعِكُمْ لِهَدَفٍ وَاحِدٍ وَغايَةٍ مُوَحَّدَةٍ . 2.""كَانَ اتِّحَادُ آرَائِهِمْ بِدَايَة لِمَرْحَلةٍ جَدِيدَةٍ"" : اِتِّفَاقُهُمْ. 3.""الاتِّحَادُ الوَطَنِيُّ"" : أَيْ إِجْمَاعُ القُوَى الوَطَنِيَّةِ على بَرْنَامَجٍ وَاحِدٍ وَأَهْدَافٍ وَاحِدَةٍ لِغَايَةٍ مُعَيَّنَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17001, 'إتْحَافٌ', 'إتحاف', 'مصدر', 'تحف', 'ءتحاف', 'إتحف', 'مص. أتْحَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إتْـحَافٌ-إتْـحَافٌ [ت ح ف] (مص. أتْحَفَ). ""جَاءَ لإتْحَافِ مَسامِعِهِمْ بِأُغْنِيَّةٍ جَيِّدَةٍ"" : لإطْرَابِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17002, 'اِتِّخَاذٌ', 'اتخاذ', 'مصدر', 'أخذ', 'اتخاذ', 'تخذ', 'مص. اِتَّخَذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّخَاذٌ-اِتِّخَاذٌ [ أ خ ذ] . (مص. اِتَّخَذَ). 1.""مِنَ الصَّعْبِ اِتِّخَاذُهُ صَدِيقًا"" : جَعْلُهُ، تَصْيِيرُهُ صَدِيقًا. 2.""يَنْبَغِي اتِّخَاذُ الإجْرَاءاتِ اللاَّزِمَةِ"" : اعْتِمَادُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17003, 'إِتْخَامٌ', 'إتخام', 'مصدر', 'تخم', 'ءتخام', 'إتخم', 'مص. أَتْخَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِتْخَامٌ-إِتْخَامٌ [ت خ م] (مص. أَتْخَمَ). ""أَكَلَ حَتَّى الإِتْخام"": إلى دَرَجَةِ إيقاعِهِ في التُّخَمَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17004, 'إِتْرَاحٌ', 'إتراح', 'مصدر', 'ترح', 'ءتراح', 'إترح', 'مص. أَتْرَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِتْرَاحٌ-إِتْرَاحٌ [ت ر ح] (مص. أَتْرَحَ). ""تَعَمَّدَ إِتْرَاحَهُ بِأَخْبَارِ السُّوءِ"": إِحْزَانَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17005, 'إِتْرَاعٌ', 'إتراع', 'مصدر', 'ترع', 'ءتراع', 'إترع', 'مص. أتْرعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِتْرَاعٌ-إِتْرَاعٌ [ت رع] (مص. أتْرعَ). 1.""إِتْراعُ الإِنَاءِ"" : مَلْؤُهُ. 2.""إِتْرَاعُ القَلْبِ بِالأحْزَانِ"" : شَحْنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17006, 'إِتْرَافٌ', 'إتراف', 'مصدر', 'ترف', 'ءتراف', 'إترف', 'مص. أتَرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِتْرَافٌ-إِتْرَافٌ [ت رف] (مص. أتَرَفَ). ""يَعِيشُ في إِتْرَافٍ"": فِي بَغْيٍ وَفَسادٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17007, 'اِتِّزَانٌ', 'اتزان', 'مصدر', 'وزن', 'اتزان', 'تزن', 'مص. اِتَّزَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّزَانٌ-اِتِّزَانٌ [و ز ن] (مص. اِتَّزَنَ). 1.""اِتِّزَانُ كِفَّتَي المِيزَانِ"": تَعَادُلهُمَا 2.""كَانَ مِثَالَ الاتّزَانِ وَالْكَمَالِ"" : مِثَالَ الرَّزانةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17008, 'اِتِّسَاخٌ', 'اتساخ', 'مصدر', 'وسخ', 'اتساخ', 'تسخ', 'مص. اِتَّسَخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّسَاخٌ-اِتِّسَاخٌ [و س خ] (مص. اِتَّسَخَ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17009, 'اِتِّساعٌ', 'اتساع', 'مصدر', 'وسع', 'اتساع', 'تسع', 'مص. اِتَّسَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِتِّساعٌ-اِتِّساعٌ [و س ع] (مص. اِتَّسَعَ). 1.""اِتِّسَاعُ البَيْتِ"": كَوْنُهُ وَاسِعًا. 2.""اِتِّسَاعُ مَعَارِفِهِ"" : ذَاتُ سَعَةٍ وَشُمُولٍ. 3.""لاَحَظَ اتِّسَاعَ عَيْنَيْهِ مِنَ الدَّهْشَةِ"" : بُرُوزَهُمَا وَتَغَيُّرَ شَكْلِهِما."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17010, 'اِتِّسَاقٌ', 'اتساق', 'مصدر', 'وسق', 'اتساق', 'تسق', 'مص. اِتَّسَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّسَاقٌ-اِتِّسَاقٌ [و س ق ] (مص. اِتَّسَقَ). 1.""ساَعَدَ عَلَى اتِّسَاقِ أمُورِهِ"" : اِنْتِظَامُهَا، اِسْتِوَاؤُهَا. 2.""اِتِّسَاقُ القَمَرِ"" : كَمَالُهُ. ""أَثَارَ اتِّسَاقُ جَمَالِهَا إِعْجَابَهُ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17011, 'اِتِّسَامٌ', 'اتسام', 'مصدر', 'وسم', 'اتسام', 'تسم', 'مص. اِتَّسَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّسَامٌ-اِتِّسَامٌ [و س م] (مص. اِتَّسَمَ). ""كَانَ اتِّسَامُهُ بِالْمُرُوءَةِ مَحَلَّ تَقْدِير"" : اِصْطِبَاغُهُ، تَمَيُّزُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17012, 'اِتِّشَاحٌ', 'اتشاح', 'مصدر', 'وشح', 'اتشاح', 'تشح', 'مص. اِتَّشَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّشَاحٌ-اِتِّشَاحٌ [و ش ح] (مص. اِتَّشَحَ). ""كَانَ اتِّشَاحُه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17013, 'اِتِّصَافٌ', 'اتصاف', 'مصدر', 'وصف', 'اتصاف', 'تصف', 'مص. اِتَّصَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّصَافٌ-اِتِّصَافٌ [و ص ف] (مص. اِتَّصَفَ). ""أهَّلَهُ اتِّصَافُهُ بأخْلاَقٍ عَالِيَةٍ لِيَتَقَلَّدَ الْمَسْؤُولِيَّةَ"" : تَحلّيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17014, 'اِتِّصَالٌ', 'اتصال', 'مصدر', 'وصل', 'اتصال', 'تصل', 'مص. اِتَّصَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِتِّصَالٌ-اِتِّصَالٌ [وص ل] (مص. اِتَّصَلَ). 1.""قَرَّرَ الاتِّصَالَ بِهِ مُبَاشرَةً"": الالْتِقَاءَ بِهِ، الاتِّصَالَ الْمُبَاشِرَ. 2.""جَعَلُوا نُقطَةَ الاتِّصَالِ فِي..."" : نُقطَةَ الْمُلْتَقَى، الوَصْلِ. 3.""كَانَ عَلَى اِتِّصَالٍ دَائِمٍ بِهِ"" : دَائِمَ اللِّقَاءِ بِهِ. 4.""اِتِّصَالٌ رَسْمِيٌّ"" : لِقَاءٌ. ""اِتِّصَالٌ غَيْرُ رَسْمِيّ"". 5.""أرَادَ الاتِّصَالَ بهِ هَاتِفِيّاً"" : أَي التَّحَدُّثَ مَعَهُ هَاتِفِيّاً. 6.""وَسَائِلُ الاتِّصَالِ بَيْنَ النَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17015, 'اِتِّضَاحٌ', 'اتضاح', 'مصدر', 'وضح', 'اتضاح', 'تضح', 'مص. اِتَّضَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّضَاحٌ-اِتِّضَاحٌ [و ض ح ] (مص. اِتَّضَحَ). ""اِتِّضَاحُ الحَقِيقَةِ"": اِنْكِشَافُهَا، اِنْجِلاَؤُهَا لِلْعِيَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17016, 'إِتْعَابٌ', 'إتعاب', 'مصدر', 'تعب', 'ءتعاب', 'إتعب', 'مص. أَتْعَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِتْعَابٌ-إِتْعَابٌ [ت ع ب ] (مص. أَتْعَبَ). 1.""لاَ يُحِبُّ إتْعَابَ النَّاسِ"" : إِرْهاقَهُمْ. 2.""إتْعَابُ النَّفسِ"" : تَحْمِيلُها ما يُرْهِقُها. 3.""إِتْعَابُ جُمْهُورِ الحاضرِينَ"" : إِزْعَاجُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17017, 'اِتِّعَاظٌ', 'اتعاظ', 'مصدر', 'وعظ', 'اتعاظ', 'تعظ', 'مص. اِتَّعَظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّعَاظٌ-اِتِّعَاظٌ [وع ظ] (مص. اِتَّعَظَ). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17018, 'اِتِّفَاقٌ', 'اتفاق', 'مصدر', 'وفق', 'اتفاق', 'تفق', 'مص. اِتَّفَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِتَّفَقَ). 1.""حَصَلَ اِتِّفَاقٌ بَيْنَهُمَا"" : تَعَاقَدَ فِي أَمْرٍ مَّا، مَا بَيْنَ فَرِيقَيْنِ أوْ شَخْصَيْنِ أَوْ أَكْثَرَ. ""اِتِّفَاقٌ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17019, 'اِتِّقَادٌ', 'اتقاد', 'مصدر', 'وقد', 'اتقاد', 'تقد', 'مص. اِتَّقَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّقَادٌ-اِتِّقَادٌ [و ق د] (مص. اِتَّقَدَ). 1. ""اِتِّقَادُ النِّيرَانِ"": اِشْتِعَالُهَا. 2. ""أَفْقَدَ اتِّقَادُ الغَضَبِ رُشْدَهُ"" : فَوَرَانُ الغَضَبِ وَاشْتِعَالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17020, 'إِتْقَانٌ', 'إتقان', 'مصدر', 'وقن', 'ءتقان', 'إتقن', 'مص. أَتْقَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِتْقَانٌ-إِتْقَانٌ [و ق ن] (مص. أَتْقَنَ). ""صَانِعٌ يُنْجِزُ أعْمَالَهُ بِإِتْقَانٍ"" : بِإِحْكَامٍ، بِضَبْطٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17021, 'اِتِّقَاءٌ', 'اتقاء', 'مصدر', 'وقي', 'اتقاء', 'تق', 'مص. اِتَّقَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِتِّقَاءٌ-اِتِّقَاءٌ [و ق ي] (مص. اِتَّقَى). ""حَاوَلَ اتِّقَاءَ شرِّهِ"": تَجَنُّبَ شَرِّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17022, 'اِتِّكَاءٌ', 'اتكاء', 'مصدر', 'وكأ', 'اتكاء', 'تك', 'مص. اِتَّكَأ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِتِّكَاءٌ-اِتِّكَاءٌ [و ك أ] (مص. اِتَّكَأ). 1.""وَجَدَهُ فِي لَحْظَةِ اِتِّكَاءٍ عَلَى المِخَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17023, 'اِتِّكَالٌ', 'اتكال', 'مصدر', 'وكل', 'اتكال', 'تكل', 'مص. اِتَّكَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِتِّكَالٌ-اِتِّكَالٌ [و ك ل] (مص. اِتَّكَلَ). 1.""الاِتِّكَالُ عَلَى اللَّهِ"": الاِسْتِسْلاَمُ إِلَيْهِ. 2.""لَيْسَ مِنْ عَادَتِهِ الاِتِّكَالُ عَلَى غَيْرِ نَفْسِهِ"" : الاِعْتِمَادُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17024, 'إِتْلاَفٌ', 'إتلاف', 'مصدر', 'تلف', 'ءتلاف', 'إتلف', 'مص. أَتْلَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِتْلاَفٌ-إِتْلاَفٌ [ت ل ف] (مص. أَتْلَفَ). 1.""إتْلاَفُ الزَّرْعِ"": إهْلاَكُهُ، إفْسَادُهُ. 2.""إتْلاَفُ الْمَالِ"" : صَرْفُهُ مِنْ دُونِ فَائِدَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17025, 'إتْمَامٌ', 'إتمام', 'مصدر', 'تم.م', 'ءتمام', 'إتمم', 'مص. أَتَمَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إتْمَامٌ-إتْمَامٌ [ت م. م] (مص. أَتَمَّ). 1.""إتْمَامُ العَمَلِ"" : إنْجَازُهُ، إكْمَالُهُ. 2.""يَحْرِصُ عَلَى إتْمَامِ الدَّرْسِ فِي مَوْعِدِهِ"" : عَلَى إِنْهَائِهِ. 3.""إِتْمَامُ القَمَرِ"" : اِكْتِمَالُهُ، وتمامُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17026, 'اِتِّهَامٌ', 'اتهام', 'مصدر', 'تهم،وهم', 'اتهام', 'تهم', 'مص. اِتَّهَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِتِّهَامٌ-اِتِّهَامٌ [ت هـ م، و هـ م] (مص. اِتَّهَمَ). ""بَرَّأ نَفْسَهُ مِنَ الِاتِّهَامِ الْمُوَجَّهِ إلَيْهِ"" : مَا يُنْسَبُ لِلشَّخْصِ مِنْ تُهْمَةٍ مِن جَرَّاءِ اعْتِد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17027, 'مُؤَاتَاةٌ', 'مؤاتاة', 'مصدر', 'أتي', 'مءاتاة', 'متة', 'مص. آتَى', '', '', 'مفرد', 'DnN', '', 'Pf', '"(يات)"', '', '', '', '', '', '', '', '', '"مُؤَاتَاةٌ-مُؤَاتَاةٌ [أ ت ي] (مص. آتَى). ""كَانَ يَنْتَظِرُ مُؤَاتَاتَهُ"" : مُواتاتَهُ، مُوَافَقَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17028, 'إِتْيانٌ', 'إتيان', 'مصدر', 'أتي', 'ءتيان', 'إتن', 'مص. أَتَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِتْيانٌ-إِتْيانٌ [أ ت ي] (مص. أَتَى). 1.""الإِتيَانُ فِي الْمَوْعِد"": الْمَجِيءُ، الحُضورُ. 2.""الإتْيَانُ بالعَمَلِ كَما يَجِبُ"" : القِيامُ بِهِ. 3.""وَجَدَ في البِنَاءِ إتْيَانًا مُحْكَماً"" : صَرْحاً. 4.""إتْيانُ الْمَحَّبَةِ"": ظُهورُها، بُروزُها. 5.""الإِتْيانُ عَلَى الأخْضَرِ واليَابِسِ"": الإِتْلافُ، بلوغُ آخِرِهِ. 6.""إِتْيانُ الدَّهْرِ عَلَيْهِ"" : إهْلاكُهُ. 7.""الإتْيَانُ على البُنْيانِ"" : هَدْمُهُ، تَدْميرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17029, 'إثَابَةٌ', 'إثابة', 'مصدر', 'ثوب', 'ءثابة', 'إثبة', 'مص. أَثَابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إثَابَةٌ-إثَابَةٌ [ث و ب] (مص. أَثَابَ). ""إِثَابَةُ الْمُؤْمِنِ"" : مُجَازَاتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17030, 'إِثَارَةٌ', 'إثارة', 'مصدر', 'ثور', 'ءثارة', 'إثرة', 'مص. أَثَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِثَارَةٌ-إِثَارَةٌ [ث و ر] (مص. أَثَارَ). 1.""إِثَارَةُ الغَضَبِ"" : الدَّفْعُ بِالْمَرْءِ إِلَى الغَضَبِ. 2.""إِثَارَةُ الاهْتِمَامِ"" : جَلْبُ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17031, 'إِثْبَاتٌ', 'إثبات', 'مصدر', 'ثبت', 'ءثبات', 'إثبت', 'مص. أثْبَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِثْبَاتٌ-إِثْبَاتٌ [ث ب ت] (مص. أثْبَتَ). 1.""قَدَّمَ إِثْبَاتاً بشَهَادَتِهِ"" : تَأْكِيداً، دَلِيلاً. ""مَعَ أنَّهُمْ لَمْ يَقْطَعُوا في الأمْرِ بِإثْبَاتٍ وَلاَ بِنَفْيٍ"". (المختار السوسي). 2.""شَاهِدُ إِثْبَاتٍ"" : مَنْ يَشْهَدُ ضِدَّ الْمُتَّهَمِ. ""لَمْ تَسْتَطِعِ الْمَحْكَمَةُ إِثبَاتَ مَا اتُّهِمُوا بِهِ"". (سلامة موسى)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17032, 'إِثْخَانٌ', 'إثخان', 'مصدر', 'ثخن', 'ءثخان', 'إثخن', 'مص. أَثْخَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِثْخَانُ-إِثْخَانُ [ث خ ن] (مص. أَثْخَنَ). 1.""إثْخَانُ العَدُوِّ"": الْمُبالغَةُ فِي قَتْلِهِ. 2.""أثْخَنَتْهُ الجراحُ إِثْخَاناً"" : أوْهَنَتْهُ. أضْعَفَتْهُ إِضْعَافاً. 3.""سَعَى إلى إِثْخَانِهِ بالضَّرْبِ"" : ضَرْبُهُ ضَرْباً مُبَرِّحاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17033, 'إِيثَارٌ', 'إيثار', 'مصدر', 'أثر', 'ءيثار', 'إثر', 'مص. آثَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِيثَارٌ-إِيثَارٌ [أ ث ر] (مص. آثَرَ). ""عُرِفَ بِإيثَارِهِ"" : بِمَحَبَّتِهِ لِلْغَيْرِ وَتَفْضِيلِهِمْ عَلَى نَفْسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17034, 'تَأْثِيرٌ', 'تأثير', 'مصدر', 'أثر', 'تءثير', 'تثر', 'مص. أَثَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْثِيرٌ-تَأْثِيرٌ [أ ث ر] (مص. أَثَّرَ). 1.""أَحْدَثَ تَأْثِيراً بَالِغاً فِي نُفُوسِ الحَاضِرِينَ"" : أَحْدَثَ وَقْعاً. ""كَأَنَّهَا تُرِيدُ أَنْ تَخْتَرِقَ بِعَيْنَيْهَا لِتَرَى تأثير كلامها فِي عَوَاطِفِي"".(جبران خ. جبران) 2. ""لَمْ يَكُنْ يَهْدِفُ إِلَى التَّأْثِيرِ عَلَيْهِ"" : إِخْضَاعِهِ لِمَفْعُولٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17035, 'إِثْرَاءٌ', 'إثراء', 'مصدر', 'أثر', 'ءثراء', 'إثر', 'مص. أَثْرَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِثْرَاءٌ-إِثْرَاءٌ [أ ث ر] (مص. أَثْرَى). ""الإثْرَاءُ الفَاحِشُ"" : الغِنَى الفَاحِشُ، أيْ كَثْرَةُ الْمَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17036, 'تَأْثِيفٌ', 'تأثيف', 'مصدر', 'أثف', 'تءثيف', 'تثف', 'مص. أَثَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْثِيفٌ-تَأْثِيفٌ [أ ث ف] (مص. أَثَّفَ). "" تَأْثِيفُ القِدْرِ"" : جَعْلُهَا عَلَى الأَثَافِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17037, 'إِثْقَال', 'إثقال', 'مصدر', 'ثقل', 'ءثقال', 'إثقل', 'مص. أثْقَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِثْقَال-إِثْقَال [ث ق ل] (مص. أثْقَلَ). 1.""إِثْقَالُ الحِمْلِ"": تَحْمِيلُهُ ثَقيلاً. 2.""وَجَدَ في الدُّيونِ الجديدة إِثْقَالاً"" : إرْهاقاً. 3.""إِثْقَالُ الحامِلِ"" : اسْتبَانَةُ حَمْلها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17038, 'إثْلاَثٌ', 'إثلاث', 'مصدر', 'ثلث', 'ءثلاث', 'إثلث', 'مص. أَثلَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إثْلاَثٌ-إثْلاَثٌ [ث ل ث] (مص. أَثلَثَ). 1.""إِثْلاثُ القَوْمِ"": اِنْقسامُهُمْ إِلَى ثَلاثِ فِرَقٍ. 2.""إثْلاَثُ القَوْمِ"" : صَيْرُهُمْ ثَلاثينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17039, 'إِثْلاَجٌ', 'إثلاج', 'مصدر', 'ثلج', 'ءثلاج', 'إثلج', 'مص. أَثْلَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِثْلاَجٌ-إِثْلاَجٌ [ث ل ج] (مص. أَثْلَجَ). 1.""إِثْلاَجُ الجَبَلِ"" : أَيْ سُقوطُ الثَّلْجِ عَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17040, 'إِثْمٌ', 'إثم', 'مصدر', 'اثم', 'ءثم', 'إثم', 'مص. أَثِمَ', '', '', 'مفرد', 'DnN', '', '', '"آثَامٌ"', '', 'R', '', '', '', '', '', '', '"(مص. أَثِمَ). ""لَمْ يَرْتَكِبْ إِثْماً فِي حَيَاتِهِ"": لَمْ يَرْتَكِبْ خَطِيئَة، ذَنْباً.المائدة آية 2 وَتَعَاوَنُوا عَلَى البِرّ والتَّقْوَى وَلاَ تَعَاوَنُوا عَلَى الإِثْمِ والعُدْوَانِ (قرآن) ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17041, 'آثَامٌ', 'آثام', 'مصدر', '', 'ءءثام', 'آثم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17042, 'إِثمَارٌ', 'إثمار', 'مصدر', 'ثمر', 'ءثمار', 'إثمر', 'مص. أَثْمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِثمَارٌ-إِثمَارٌ [ث م ر] (مص. أَثْمَرَ). ""إِثْمَارُ الج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17043, 'أَجِيجٌ', 'أجيج', 'مصدر', 'أجج', 'ءجيج', 'جج', 'مص. أجَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"أَجِيجٌ-أَجِيجٌ [أ ج ج] (مص. أجَّ). 1.""أجيجُ النَّارِ"": تَوَهُّجُهَا. 2.""وَكَانَ أَجِيجُ الحَرِّ قَدْ أَنْهَكَ قُوَاهُ"" : شِدَّة الحَرِّ. 3.""بَدَأْتُ أَسْمَعُ أَجِيجَ القَوْمِ مِنْ بَعِيدٍ"" : اِخْتِلاَطَ كَلاَمِهِمْ مَعَ حَفِيفِ مَشْيِهِمْ. 4.""أَجِيجُ الماءِ"" : صَوْتُ انْصِبابِ الماءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17044, 'إِجَادَةٌ', 'إجادة', 'مصدر', 'جود', 'ءجادة', 'إجدة', 'مص. أَجَادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجَادَة-إِجَادَة [ج و د] (مص. أَجَادَ). ""إِجَادَةُ العَمَلِ"" : إِتْقَانُهُ الإِلْمامُ. ""إِجَادَةُ اللّغَاتِ الأَجْنَبِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17045, 'إجَارَةٌ', 'إجارة', 'مصدر', 'أجر', 'ءجارة', 'إجرة', 'مص. أَجَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إجَارَةٌ-إجَارَةٌ [أ ج ر] (مص. أَجَارَ). 1.""قَدَّمَ لَهُ إِجَارَتَهُ"" : مَا يُعْطَى لِلأَجِيرِ جَزَاءَ عَمَلِهِ، الأُجْرَةُ. 2.""اِتَّفَقَ مَعَهُ عَلَى إِجَارَةِ بَيْتٍ فِي الطَّابَقِ الثَّالِثِ"" : كِرَاء."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17046, 'إجَازَةٌ', 'إجازة', 'مصدر', 'جوز', 'ءجازة', 'إجزة', 'مص. أجَازَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إجَازَةٌ-إجَازَةٌ [ج و ز] (مص. أجَازَ). 1.""نَالَ الْمُوَظَّفُ إِجَازَةً"": تَرْخِيصاً إِذْناً. 2.""هُوَ فِي إِجَازَةٍ مَرَضِيَّةٍ"" : فِي رُخْصَةٍ. 3.""إِجَازَةُ الصَّيْفِ"" : عُطْلَة، راحَة. ""قَضَى إِجَازَةً فَوْقَ شاطِئ البَحْرِ"" (أمل دنقل). 4.""حَصَلَ عَلَى شَهَادَةِ الإجَازَةِ"" : شَهَادَةُ اللِّسَانْسِ (نِهَايَة الدُّرُوسِ الجَامِعِيَّةِ العادِية)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17047, 'إجاعَةٌ', 'إجاعة', 'مصدر', 'جوع', 'ءجاعة', 'إجعة', 'مص. أَجاعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إجاعَةٌ-إجاعَةٌ [ج و ع] (مص. أَجاعَ). ""ما الَّذِي يَدْفَعُهُ إلَى إِجاعةِ خادِمِهِ"": مَنْع الطعام عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17048, 'إِجَالَةٌ', 'إجالة', 'مصدر', 'جول', 'ءجالة', 'إجلة', 'مص. أَجَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجَالَةٌ-إِجَالَةٌ [ج و ل] (مص. أَجَالَ). 1.""إِجَالَةُ النَّظَرِ في اللَّوْحَةِ"" : تَقْليبُ النَّظَر فِيهَا، إمْعانُ النَّظرِ فيها. 2.""إجالَةُ السَّهْمِ"" : جَعْلهُ يَجُولُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17049, 'إِجْبَارٌ', 'إجبار', 'مصدر', 'جبر', 'ءجبار', 'إجبر', 'مص. أَجْبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجْبَارٌ-إِجْبَارٌ [ج ب ر] (مص. أَجْبَرَ). ""لاَ يَسْعَى إلَى إجْبَارِ أَحَدٍ عَلَى مَا لَيْسَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17050, 'اِجْتِيَاحٌ', 'اجتياح', 'مصدر', 'جيح', 'اجتياح', 'جتح', 'مص. اِجْتَاحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِجْتِيَاحٌ-اِجْتِيَاحٌ [ج ي ح] (مص. اِجْتَاحَ). ""اِجْتِيَاحُ العَدُوِّ لِحُدُودِ البِلاَدِ"" : دُخُولهُا غَصْباً وَقَهْرًا، اكْتِسَاحُهَا. ""وَقَفَ الشَّعْبُ صَامِداً ضِدَّ اجْتِيَاحِ قُوَّاتِ الغَزْوِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17051, 'اِجْتِيَازٌ', 'اجتياز', 'مصدر', 'جوز', 'اجتياز', 'جتز', 'مص. اِجْتَازَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِجْتِيَازٌ-اِجْتِيَازٌ [ج و ز] (مص. اِجْتَازَ). 1.""اِجْتِيَازُ الْمَسَالِكِ"": سَلُوكُهَا، قَطْعُهَا. 2.""اِجْتِيَازُ الاِمْتِحَانِ"" : التَّقَدُّمُ إِلَى الاِمْتِحَانِ وَالاخْتِبَارُ فِيهِ. 3.""اِجْتِيَازُ اَلسَّفِينَةِ لِلْمَضِيقِ"" : عُبورُهَا. 4.""اِجْتِيَازُ الحُدُودِ"" : تَخَطّيها، تَجَاوُزها، الْمُرُور بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17052, 'اِجْتِثَاثٌ', 'اجتثاث', 'مصدر', 'جثث', 'اجتثاث', 'جتثث', 'مص. اِجْتَثَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِجْتِثَاثٌ-اِجْتِثَاثٌ [ج ث ث] (مص. اِجْتَثَّ). 1.""اِجْتِثَاثُ الشَّجَرَةِ"" : اِقْتِلاعُهَا م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17053, 'اِجْتِذَابٌ', 'اجتذاب', 'مصدر', 'جذب', 'اجتذاب', 'جتذب', 'مص. اِجْتَذَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِجْتِذَابٌ-اِجْتِذَابٌ [ج ذ ب] (مص. اِجْتَذَبَ) ""اِجْتِذابُ الأنْظَارِ"" : جَذْبُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17054, 'اجْتِرَارٌ', 'اجترار', 'مصدر', 'جرر', 'اجترار', 'جترر', 'مص. اِجْتَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اجْتِرَارٌ-اجْتِرَارٌ [ج ر ر] (مص. اِجْتَرَّ). 1.""لَمْ تَتَوَقَّف البَقَرَةُ عَنِ الاجْتِرَارِ"" : إعَادَةُ مَا فِي بَطْنِهَا و"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17055, 'اِجْتِرَاءٌ', 'اجتراء', 'مصدر', 'جرأ', 'اجتراء', 'جتر', 'مص. اِجْتَرأ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِجْتِرَاءٌ-اِجْتِرَاءٌ [ج ر أ] (مص. اِج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17056, 'اجْتِراعٌ', 'اجتراع', 'مصدر', 'جرع', 'اجتراع', 'جترع', 'مص. اِجْترعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اجْتِراعٌ-اجْتِراعٌ [ج رع] (مص. اِجْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17057, 'اجْتِرَافٌ', 'اجتراف', 'مصدر', 'جرف', 'اجتراف', 'جترف', 'مص. اِجْتَرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اجْتِرَافٌ-اجْتِرَافٌ [ج ر ف] (مص. اِجْتَرَفَ). ""اِجْتِرَافُ السَّيْلِ"": كَسْحُهُ، اِكتِسَاحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17058, 'اِجْتِزَازٌ', 'اجتزاز', 'مصدر', 'جزز', 'اجتزاز', 'جتزز', 'مص. اِجْتَزَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِجْتِزَازٌ-اِجْتِزَازٌ [ج ز ز] (مص. اِجْتَزَّ). ""اِنْهَمَك في اِجْتِزَازِ الصُّوفِ"": قَطْعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17059, 'اِجْتِلاَبٌ', 'اجتلاب', 'مصدر', 'جلب', 'اجتلاب', 'جتلب', 'مص. اِجْتَلبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِجْتِلاَبٌ-اِجْتِلاَبٌ [ج ل ب] (مص. اِجْتَلبَ). 1.""اِجْتِلاَبُ البَضَائِعِ"" : اِسْت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17060, 'اِجْتِمَاعٌ', 'اجتماع', 'مصدر', 'جم.ع', 'اجتماع', 'جتمع', 'مص. اِجْتَمَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِجْتِمَاعٌ-اِجْتِمَاعٌ [ج م. ع] (مص. اِجْتَمَعَ). 1.""عَقَدَتِ الجَمْعِيَّةُ اجْتِمَاعهَا الأَوَّلَ"" : لِقَاء أعْضَائِهَا لِلْحِوَارِ وَالتَّدَاوُلِ فِي جَلْسَةٍ. 2.""وَأَخِيرًا تَمَّ اجْتِمَاعُ أَفْرَادِ الأُسْرَةِ"" : اِلْتِئَامُهُمْ. 3.""يَدْرُسُ عِلْمَ الاجْتِمَاعِ"" : عِلْمٌ يَدْرُسُ العَلاَقَاتِ القَائِمَةَ بَيْنَ النَّاسِ وَأنْظِمَتِهِمْ وَسُلُوكِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17061, 'اجْتِنَابٌ', 'اجتناب', 'مصدر', 'جنب', 'اجتناب', 'جتنب', 'مص. اِجْتَنَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اجْتِنَابٌ-اجْتِنَابٌ [ج ن ب] (مص. اِجْتَنَبَ). 1.""اِجْتِنَابُ الْمَعَاصِي"" : تَحَاشِيهَا، تَجَنُّبُهَا، تَلاَفِيهَا، البُعْدُ عَنْهَا. 2.""حاوَلَ اجتِنَابَ شَرِّهِ"": الاِحْتِرازَ مِنْ شَرِّهِ، تَوَقَّاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17062, 'اِجْتِناءٌ', 'اجتناء', 'مصدر', 'جني', 'اجتناء', 'جتن', 'مص. اِجْتَنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِجْتِناءٌ-اِجْتِناءٌ [ج ن ي] (مص. اِجْتَنَى). ""اِجْتِنَاءُ الثَّمَرِ"" : جَنْيَهُ، قَطْفُهُ. . ""يَتَمَتَّعُ باجْتِناءِ ثَمَراتِ عَمَلِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17063, 'اِجْتِهَادٌ', 'اجتهاد', 'مصدر', 'جهد', 'اجتهاد', 'جتهد', 'مص. اِجْتَهَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِجْتَهَدَ). ""إِيَّادٌ مَعْرُوفٌ بِاجْتِهَادِهِ"" : مُثَابِرٌ يَبْذُلُ مَجْهُودَاتٍ كَثِيرَةً. ""أوْصَلَهُ اِجْتِهَادُهُ إِلَى مَكَانَةٍ مَرْمُوقَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17064, 'تَأْجِيجٌ', 'تأجيج', 'مصدر', 'أجج', 'تءجيج', 'تجج', 'مص. أَجَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْجِيجٌ-تَأْجِيجٌ [أ ج ج] (مص. أَجَّجَ). 1. ""تَأْجِيجُ نَارِ الحَطَبِ"" : إِلْهَابُهَا. 2. ""تَأْجِيجُ الخُصُومَةِ بَيْنَ النَّاسِ "": إِشْعَالُهَا، الزِّيَادَةُ فِي حِدَّتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17065, 'إِجْحَافٌ', 'إجحاف', 'مصدر', 'جحف', 'ءجحاف', 'إجحف', 'مص. أجْحَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجْحَافٌ-إِجْحَافٌ [ج ح ف] (مص. أجْحَفَ). ""لَمْ نُعْطِهِ كُلّ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17066, 'إِجْدابٌ', 'إجداب', 'مصدر', 'جدب', 'ءجداب', 'إجدب', 'مص. أجْدَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجْدابٌ-إِجْدابٌ [ج د ب] (مص. أجْدَبَ). ""إِجْدَابُ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17067, 'إِجْذَامٌ', 'إجذام', 'مصدر', 'جذم', 'ءجذام', 'إجذم', 'مص. أجْذَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجْذَامٌ-إِجْذَامٌ [ج ذ م] (مص. أجْذَمَ). 1.""إِجْذَامُ الرِّجْلِ"" : قَطْعُهَا. 2.""الإِجْذَامُ عَنِ الأَمْرِ"" : الإِقْلاَعُ عَنْهُ. 3.""الإِجْذَامُ على أَمْرِ"" : العَزْمُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17068, 'إِيجَارٌ', 'إيجار', 'مصدر', 'أجر', 'ءيجار', 'إجر', 'مص. آجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِيجَارٌ-إِيجَارٌ [أ ج ر] (مص. آجَرَ). 1. ""إيجَارُ البَيْتِ"" : إِكْرَاؤُهُ. 2.""دَارٌ بِرَسْمِ الإِيجَارِ"" : أَيْ دَارٌ مَعْرُوضَةٌ لِلْكِرَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17069, 'تَأْجِيرٌ', 'تأجير', 'مصدر', 'أجر', 'تءجير', 'تجر', 'مص. أَجَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْجِيرٌ-تَأْجِيرٌ [أ ج ر] (مص. أَجَّرَ). 1.""تَأْجِيرُ الطِّينِ"" : طَبْخُهُ أَجُرّاً. 2.""رَقْمُ التّأجير"" : الرقم المالي لِمُوظّفِي الدَّوْلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17070, 'إجْرَاسٌ', 'إجراس', 'مصدر', 'جرس', 'ءجراس', 'إجرس', 'مص. أجْرَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إجْرَاسٌ-إجْرَاسٌ [ج ر س] (مص. أجْرَسَ). 1.""إجْرَاسُ الطَّائِرِ"": سَمَاعُ صَوْتِ مُرُورِهِ. 2.""إِجْرَاسُ الحَلْيِ"" : سَمَاعُ صَوْتِهِ كَصَوْتِ جَرَسٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17071, 'إِجْرَامٌ', 'إجرام', 'مصدر', 'جرم', 'ءجرام', 'إجرم', 'مص. أجْرَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"إِجْرَامٌ-إِجْرَامٌ [ج ر م] (مص. أجْرَمَ). 1.""لَمْ يَكُنْ إِجْرَامُهُ عَن سَبْقِ إِصْرَارٍ"" : اِقْتِرَافُ إِثْمٍ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17072, 'إِجْرَاءٌ', 'إجراء', 'مصدر', 'جري', 'ءجراء', 'إجر', 'مص. أَجْرَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"(مص. أَجْرَى). 1.""اِتَّخَذَ الضَّابِطُ إِجْرَاءً"" : قَرَارًا، تَدْبِيراً. ""اِتَّخَذَ إِجْرَاءات"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17073, 'إِجْزَالٌ', 'إجزال', 'مصدر', 'جزل', 'ءجزال', 'إجزل', 'مص. أجْزَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجْزَالٌ-إِجْزَالٌ [ج ز ل] (مص. أجْزَلَ). ""الإجْزَالُ فِي العَطَاءِ"": الإِكْثَارُ مِنْه."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17074, 'إِجْزَاءٌ', 'إجزاء', 'مصدر', 'جزي', 'ءجزاء', 'إجز', 'مص. أجْزَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِجْزَاءٌ-إِجْزَاءٌ [ج ز ي] (مص. أجْزَى). ""سَعَى إِلَى إِجْزَائِهِ"": إِلَى القِيَامِ مَقَامَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17075, 'إجْفَالٌ', 'إجفال', 'مصدر', 'جفل', 'ءجفال', 'إجفل', 'مص. أجْفَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إجْفَالٌ-إجْفَالٌ [ج ف ل] (مص. أجْفَلَ). ""إِجْفَالُ البَعِيرُ"" : نُفُورُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17076, 'تَأْجِيلٌ', 'تأجيل', 'مصدر', 'أجل', 'تءجيل', 'تجل', 'مص. أَجَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْجِيلٌ-تَأْجِيلٌ [أ ج ل] (مص. أَجَّلَ). 1. "" تَمَّ تَأْجِيلُ الْمُدَاوَلاتِ"" : تَأْخِيرُهَا. "" تَأْجِيلُ جَلْسَةِ الافْتِتَاحِ"". 2. ""تَأْجِيلُ الدَّعْوَى"" : إِرْجَاءُ البَتِّ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17077, 'إجْلالٌ', 'إجلال', 'مصدر', 'أجل', 'ءجلال', 'إجلل', 'مص. أجَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إجْلالٌ-إجْلالٌ [أ ج ل] (مص. أجَلَّ). ""حَيَّاهُ بِتَقْدِيرٍ وإِجْلاَلٍ"": بِتَعْظِيمٍ وَتَبْجِيلٍ. ""هُوَ أهْلٌ لِلاحْتِرَامِ وَالإِجْلاَلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17078, 'إِجْلاَبٌ', 'إجلاب', 'مصدر', 'جلب', 'ءجلاب', 'إجلب', 'مص. أَجْلَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجْلاَبٌ-إِجْلاَبٌ [ج ل ب] (مص. أَجْلَبَ). 1.""لَمْ يَتَحَمَّلْ إِجْلاَبَ الجُمْهُورِ"" : ضَج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17079, 'إِجْلاَءٌ', 'إجلاء', 'مصدر', 'جلو', 'ءجلاء', 'إجل', 'مص. أجْلَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِجْلاَءٌ-إِجْلاَءٌ [ج ل و] (مص. أجْلَى). 1.""إِجْلاَءُ السُّكَّانِ عَنْ دِيارِهِمْ"" : إِخْرَاجُهُمْ، طَرْدُهُم. 2.""إِجْلاَءُ الجَيْشِ"": إِجْلاَؤُهُ. 3.""إِجْلاَءُ الحقيقة"" : الكَشْفُ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17080, 'إِجْمَاعٌ', 'إجماع', 'مصدر', 'جمع', 'ءجماع', 'إجمع', 'مص. أَجْمَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"إِجْمَاعٌ-إِجْمَاعٌ [ج م ع] (مص. أَجْمَعَ). 1.""وَافَقَ الأَعْضَاءُ عَلى الْمَشْرُوعِ بِالإِجْمَاعِ"" : اِتِّفَاقُهُم جَمِيعاً. 2.""مِنْ أُصُولِ التَّشْرِيعِ الإِسْلاَمِيّ الإِجْمَاعُ"" : هُوَ مَا يَقْصُرُهُ فُقَهَاءُ الإِسْلاَمِ عَلَى اتِّفَاقِ الْمُجْتَهِدِينَ فِي عَصْرٍ عَلَى أَمْرٍ دِينِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17081, 'إِجْمَالٌ', 'إجمال', 'مصدر', 'جمل', 'ءجمال', 'إجمل', 'مص. أَجْمَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجْمَالٌ-إِجْمَالٌ [ج م ل] (مص. أَجْمَلَ). 1.""بالإجْمَالِ كَانَتِ النَّتَائِجُ حَسَنَةً"" : بِوَجْهٍ عَامٍّ، بشَكْلٍ عَامٍّ. ""عَلَى الإِجْمَالِ"" ""بِوَجْهِ الإِجْمَالِ كَانَتِ الحَفْلَةُ مُوَفَّقَةً"". 2.""إِجْمَالاً لَمْ يَتَخَلَّفْ عَنِ الحُضُورِ إِلاَّ القَلِيلُ"" : عُمُومًا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17082, 'إِجْنَاحٌ', 'إجناح', 'مصدر', 'جنح', 'ءجناح', 'إجنح', 'مص. أجْنَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجْنَاحٌ-إِجْنَاحٌ [ج ن ح] (مص. أجْنَحَ). ""مِنْ شِيَمِهِ الإجْنَاحُ إِلَى الْمَكَارِم"": الْمَيْلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17083, 'إجْهَادٌ', 'إجهاد', 'مصدر', 'جهد', 'ءجهاد', 'إجهد', 'مص. أَجْهَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إجْهَادٌ-إجْهَادٌ [ج هـ د] (مص. أَجْهَدَ). 1.""قَامَ بِإِجْهَادِ نَفسِهِ"" : حَمَّلَهَا مَا لاَ يُطَاقُ. 2.""سَعَى إِلَى إِجْهَادِ فِكْرِهِ"" : إِلَى تَرْكِيزِ اِنْتِبَاهِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17084, 'إِجْهَارٌ', 'إجهار', 'مصدر', 'جهر', 'ءجهار', 'إجهر', 'مص. أجْهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجْهَارٌ-إِجْهَارٌ [ج هـ ر] (مص. أجْهَرَ). 1. ""الإِجْهَارُ بالقِرَاءةِ"" : رَفْعُ الصَّوْتِ بِهَا. 2.""الإِجْهَارُ بِالحَقِيقَةِ"" : إِعْلاَنُهَا. 3.""الإِجْهَارُ بِالسِّرِّ"" : إِفْشَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17085, 'إِجْهَازٌ', 'إجهاز', 'مصدر', 'جهز', 'ءجهاز', 'إجهز', 'مص. أَجْهَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجْهَازٌ-إِجْهَازٌ [ج هـ ز] (مص. أَجْهَزَ). ""الإِجْهَازُ عَلَى العَدُوِّ"": الإِحْبَاطُ عَلَيْهِ، أَيْ إِتْمَامُ قَتْلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17086, 'إِجْهَاشٌ', 'إجهاش', 'مصدر', 'ج.هش', 'ءجهاش', 'إجهش', 'مص. أجْهَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجْهَاشٌ-إِجْهَاشٌ [ج. هـ ش] (مص. أجْهَشَ). 1.""الإِجْهَاشُ بِالبُكَاءِ"" : ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17087, 'إِجْهَاضٌ', 'إجهاض', 'مصدر', 'جهض', 'ءجهاض', 'إجهض', 'مص. أجْهَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجْهَاضٌ-إِجْهَاضٌ [ج هـ ض] (مص. أجْهَضَ). 1.""أجْرَتْ عَمَلِيَّةَ إِجْهَاضٍ"" : إِسْقَاطُ الحَمْلِ. 2.""سَاهَمَ فِي إِجْهَاضِ الْمَشْرُوعِ"" : فِي إِفْسَادِهِ وإِرْبَاكِ إِنْجَازِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17088, 'إِجْهَامٌ', 'إجهام', 'مصدر', 'جهم', 'ءجهام', 'إجهم', 'مص. أَجْهَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِجْهَامٌ-إِجْهَامٌ (مص. أَجْهَمَ). ""إِجْهَامُ السَّمَاءِ"" : تَغَطِّيهَا بالغُيُومِ. ""إِجْهَامُ الجَوِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17089, 'إِحَارَةٌ', 'إحارة', 'مصدر', 'حور', 'ءحارة', 'إحرة', 'مص. أحَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحَارَةٌ-إِحَارَةٌ [ح و ر] (مص. أحَارَ).""إِحَارَةُ الجوَابِ"": رَدُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17090, 'إحَاطَةٌ', 'إحاطة', 'مصدر', 'حوط', 'ءحاطة', 'إحطة', 'مص. أحَاطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إحَاطَةٌ-إحَاطَةٌ [ح و ط] (مص. أحَاطَ). 1.""الإحَاطَةُ بِالموْضُوع"" : الإِلْمامُ بِهِ، التَّمَكُّنُ مِنْهُ، العِلْمُ بِهِ. 2.""عَمِلُوا عَلَى إِحَاطَتِهِ بِكلِّ رِعَايَةٍ"" : عَلَى الاِهْتِمَامِ بِهِ وَتَوْلِيَتِهِ كُلَّ عِنَايَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17091, 'إحَاقَةٌ', 'إحاقة', 'مصدر', 'حيق', 'ءحاقة', 'إحقة', 'مص. أَحاقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إحَاقَةٌ-إحَاقَةٌ [ح ي ق] (مص. أَحاقَ). 1.""الإِحَاقَةُ بِالعُلُوم"": الإحَاطَةُ بِها. 2.""إِحَاقَةُ المكْرِ بِهِمْ"" : إِنْزَالُهُ بِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17092, 'إِحالَةٌ', 'إحالة', 'مصدر', 'حول', 'ءحالة', 'إحلة', 'مص. أَحَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحالَةٌ-إِحالَةٌ [ح و ل] (مص. أَحَالَ). 1.""إحالَةُ القَضِيَّةِ عَلَى الْمُدِيرِ"" : تَسْلِيمُهَا وَرَفْعُهَا إِلَيْهِ وَجَعْلُهَا مَقصُورَةً عَلَيْهِ لِيَنْظُرَ فِيهَا. 2.""الإِحَالَةُ عَلَى الْمَعَاش"" : الإِعْفَاءُ مِنَ العَمَلِ وَجَعْلُ العَامِلِ أوِ الْمُوَظَّفِ يَتَمَتَّعُ بِمَعَاشٍ شَهْريٍّ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17093, 'إِحْبَاسٌ', 'إحباس', 'مصدر', 'حبس', 'ءحباس', 'إحبس', 'مص. أحْبَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْبَاسٌ-إِحْبَاسٌ [ح ب س] (مص. أحْبَسَ). ""إِحْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17094, 'إِحْبَاطٌ', 'إحباط', 'مصدر', 'حبط', 'ءحباط', 'إحبط', 'مص. أحْبَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"إِحْبَاطٌ-إِحْبَاطٌ [ح ب ط] (مص. أحْبَطَ). 1.""قَامُوا بِإِحْبَاطِ كُلِّ خُطَطِ العَدُوِّ"" : بإبْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17095, 'إِحْبَاكٌ', 'إحباك', 'مصدر', 'حبك', 'ءحباك', 'إحبك', 'مص. أحْبَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْبَاكٌ-إِحْبَاكٌ [ح ب ك] (مص. أحْبَكَ). ""إِحْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17096, 'اِحْتِيَاجٌ', 'احتياج', 'مصدر', 'حوج', 'احتياج', 'حتج', 'مص. اِحْتَاجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِحْتَاجَ). 1.""كانَ احْتِيَاجُهُ سَبَباً في ذُلِّهِ ومهانَتِهِ"" : اِفْتِقَارُهُ. 2. ""وَجَدَ نَفْسَهُ في احْتِيَاجٍ إلى الْمُسَاعَدَةِ"" : أَي في حاجَةٍ وضَرورَةٍ إِلَى..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17097, 'اِحْتِيَاطٌ', 'احتياط', 'مصدر', 'حوط', 'احتياط', 'حتط', 'مص. اِحْتَاطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِحْتِيَاطٌ-اِحْتِيَاطٌ [ح و ط] (مص. اِحْتَاطَ). ""اِحْتَفَظَ بِقَدْرٍ مِنَ الْمَالِ احْتِيَاطاً لِظُرُوفٍ طَارِئَةٍ"" : اِسْتِدْرَاكًا لِمَا قَدْ يَحْدُثُ، تَحَسُّباً لِظُرُوفٍ طَارِئَةٍ. ""فَعَلَ ذَلِكَ عَلَى سَبِيلِ الاحْتِيَاطِ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17098, 'اِحْتِيَالٌ', 'احتيال', 'مصدر', 'حول', 'احتيال', 'حتل', 'مص. اِحْتَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِحْتِيَالٌ-اِحْتِيَالٌ [ح و ل] (مص. اِحْتَالَ). ""إِيَّاكَ وَالاحْتِيَالَ"": إِيَّاكَ وَتَدْبِيرَ الحِيَلِ وَالْمَكائِدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17099, 'اِحْتِبَاسٌ', 'احتباس', 'مصدر', 'حبس', 'احتباس', 'حتبس', 'مص. اِحْتَبَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِبَاسٌ-اِحْتِبَاسٌ [ح ب س] (مص. اِحْتَبَسَ). ""اِحْتِبَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17100, 'اِحْتِجَاجٌ', 'احتجاج', 'مصدر', 'حجج', 'احتجاج', 'حتجج', 'مص. اِحْتَجَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِحْتَجَّ). 1.""لَمْ يَكُنِ احْتِجَاجُهُ مُقْنِعاً"": لَمْ يَكُنْ مَا اتَّخَذَهُ مِنْ حُجَج مُقْنِعاً. 2.""عَبَّرَ عَنِ احْتِجَاجِهِ"" : عَنِ اسْتِنْكَارِهِ. ""تَوَالَتِ الاحْتِجَاجَاتُ مِنْ مُخْتَلِفِ الْمَحَافِلِ الدَّوْلِيَّةِ عَلَى الْمُمَارَسَاتِ الصِّهْيُونِيَّةِ بِالأَرَاضِي الفِلَسْطِينِيَّةِ الْمُحْتَلَّةِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17101, 'اِحْتِجَابٌ', 'احتجاب', 'مصدر', 'حجب', 'احتجاب', 'حتجب', 'مص. اِحْتَجَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِجَابٌ-اِحْتِجَابٌ [ح ج ب] (مص. اِحْتَجَبَ). 1.""الاحْتِجَابُ عَنِ الأَعْيُنِ"" : الاخْتِفَاءُ. 2.""اِحْتِجَابُ القَمَرِ"":كُسُوفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17102, 'اِحْتِجَازٌ', 'احتجاز', 'مصدر', 'حجز', 'احتجاز', 'حتجز', 'مص. اِحْتَجَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِجَازٌ-اِحْتِجَازٌ [ح ج ز] (مص. اِحْتَجَزَ). 1.""اِحْتِجَازُ الأَمْتِعَةِ"" : وَضْعُها رَهْنَ الحَجْزِ. 2.""أَمَرُوا باحْتِجَازِه"" : بِاعْتِقالِه. 3.""لَمْ يَكُنْ أَمَامَهُ إِلاَّ الاحْتِجَازُ بالحِصْنِ"" : أَي الامْتِنَاعُ والالتِجاءُ لِلحِصْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17103, 'اِحْتِدَادٌ', 'احتداد', 'مصدر', 'حدد', 'احتداد', 'حتدد', 'مص. اِحْتَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِدَادٌ-اِحْتِدَادٌ [ح د د] (مص. اِحْتَدَّ). 1.""اِحْتِدَادُ الصِّرَاعِ بَيْنَ المتنَافسين"" : اِشْتِدَادُهُ. 2.""لَمْ يَكُنِ احتدَادُهُ فِي مَحَلِّهِ"": غَضَبُهُ. 3.""اِحْتِدَادُ السِّكِّينِ"": أَيْ كَوْنُهُ حَادّاً قَاطِعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17104, 'اِحْتِدَامٌ', 'احتدام', 'مصدر', 'حدم', 'احتدام', 'حتدم', 'مص. اِحْتَدَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِدَامٌ-اِحْتِدَامٌ [ح د م] (مص. اِحْتَدَمَ). 1.""اِحْتِدَامُ الحَرارَةِ"": اِشْتِدَادُهَا. ""اِحْتَدَامُ الصِّرَاعِ"" ""اِحْتدامُ النِّقاشِ"". 2.""اِحْتدامُ القِدْرِ"": فَورانُ غَلَيانِهِ. 3.""اِحْتِدَامُ غَيْظِهِ"" : اِشْتِعَالُ غَيْظِهِ. 4.""اِحْتدَامُ الدَّمِ"" : اِشْتِدَادُ حُمْرَتِهِ المائِلَةِ إلَى السَّوَادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17105, 'اِحْتِذَاءٌ', 'احتذاء', 'مصدر', 'حذو', 'احتذاء', 'حتذ', 'مص. اِحتَذَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِحْتِذَاءٌ-اِحْتِذَاءٌ [ح ذ و] (مص. اِحتَذَى). 1.""أَرَادَ الاِحْتِذَاءَ بِهِ"" : أَي الاِقْتِدَاءَ بهِ، السَّيْرَ عَلَى مِنْوَالِهِ. 2.""اِحْتِذَاءُ الحِذَاءِ"" : لُبْسُهُ، اِنْتِعَالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17106, 'اِحْترَازٌ', 'احتراز', 'مصدر', 'حرز', 'احتراز', 'حترز', 'مص. اِحْتَرزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْترَازٌ-اِحْترَازٌ [ح ر ز] (مص. اِحْتَرزَ). ""حاوَلَ الاحْتِرَازَ مِن حِيَلِهِ"" : تَوَقِّيها، الابْتِعَادَ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17107, 'اِحْتِرَاسٌ', 'احتراس', 'مصدر', 'حرس', 'احتراس', 'حترس', 'مص. اِحْتَرَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِرَاسٌ-اِحْتِرَاسٌ [ح ر س] (مص. اِحْتَرَسَ). ""هُو في اِحْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17108, 'اِحْتِرَافٌ', 'احتراف', 'مصدر', 'حرف', 'احتراف', 'حترف', 'مص. اِحْتَرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِحْتِرَافٌ-اِحْتِرَافٌ [ح ر ف] (مص. اِحْتَرَفَ). 1.""اِحْتِرَافُ مِهْنَةٍ"" : اِتِّخَاذُهَا عَمَلاً لِلاِكتِسابِ والارْتزِاقِ. 2.""الاحْتِرَافُ في الرِّيَاضَةِ"" : التَّفَرُّغُ لِلعَمَلِ الرِّيَاضِيِّ بِقَصْدِ الاِرْتِزَاقِ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17109, 'اِحْتِراقٌ', 'احتراق', 'مصدر', 'حرق', 'احتراق', 'حترق', 'مص. اِحْتَرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِراقٌ-اِحْتِراقٌ [ح ر ق] (مص. اِحْتَرَقَ). 1.""اِحْتراقُ البَيْتِ"": اِشْتِعَالُهُ نَارًا. ""مادَّةٌ قابِلَةٌ لِلاحْتِرَاقِ"". 2.""اِحْتِرَاقُ قَلْبِهِ"" : اِشْتِدَادُ أَلَمِهِ وَشِدَّةُ تَأثُّرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17110, 'اِحْتِرَامٌ', 'احترام', 'مصدر', 'حرم', 'احترام', 'حترم', 'مص. اِحْتَرَمَ', '', '', 'مفرد', 'DnN', '', '', '"ح"', '', 'R', '', '', '', '', '', '', '"(مص. اِحْتَرَمَ). 1.""وَلَدٌ جَدِير بِالاِحْتِرَامِ لِنَبَاهَتِهِ وَسُلُوكِهِ الحَسَنِ"" : جَدِير بالتَّقْدِيرِ وَالاعْتِبَارِ. 2.""يَتَمَتَّعُ بِالاِحْتِرَامِ والتَّقْدِير"" : بِالْمَهَابَةِ وَالإجْلاَلِ. ""نَقِفُ اِحْتِرَاما لِلمُعَلِّم مَهَابَةً وَاعْتِبَارًا لِمَكَانَتِهِ"" ""تَقَبَّلِ اِحْتِرَامِي وَتَحِيَّاتِي"" : تَقْدِيرِي، اِعْتِبَارِي. ""مِنْ أَوْجَبِ الوَاجِبَاتِ احْتِرَامُ حُقُوقِ الإِنْسَانِ"" ""لاَ تَكنْ عَدِيمَ الاحْتِرَامِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17111, 'اِحْتِسابٌ', 'احتساب', 'مصدر', 'حسب', 'احتساب', 'حتسب', 'مص. اِحْتَسَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِسابٌ-اِحْتِسابٌ [ح س ب] (مص. اِحْتَسَبَ). 1.""اِحْتِسابُ التَّقْويمِ"" : تَقْدِيرُهُ. 2. ""الاحْتِسَابُ عِنْدَ اللَّهِ"" : طَلَبُ ثَوابِ اللَّهِ يَوْمَ الحِسَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17112, 'اِحْتِسَاءٌ', 'احتساء', 'مصدر', 'حسي', 'احتساء', 'حتس', 'مص. اِحْتَسَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِحْتِسَاءٌ-اِحْتِسَاءٌ [ح س ي] (مص. اِحْتَسَى). 1.""اِحْتِسَاءُ القَهْوَةِ"" : تَنَاوُلُها جُرْعَةً بَعْدَ جُرْعَةٍ. 2.""اِحْتِساءُ الطَّائِرِ لِلماءِ"": تَنَاولُهُ لِلْماءِ بِمِنْقَارِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17113, 'اِحْتِشَادٌ', 'احتشاد', 'مصدر', 'حشد', 'احتشاد', 'حتشد', 'مص. اِحْتَشَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِشَادٌ-اِحْتِشَادٌ [ح ش د] (مص. اِحْتَشَدَ). ""تَمَّ احْتِشَادُ جَمِيعِ القُوَّاتِ عَلَى الحُدُودِ"" : تَجَمُّعُهَا، تَمَركُزُهَا. ""كَانَ احْتِشَادُ الجُمْهُورِ غَفِيراً فِي السَّاحَةِ العُمُومِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17114, 'اِحْتِشَامٌ', 'احتشام', 'مصدر', 'حشم', 'احتشام', 'حتشم', 'مص. اِحْتَشَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِشَامٌ-اِحْتِشَامٌ [ح ش م] (مص. اِحْتَشَمَ). 1.""بَدَتْ عَلَى وَجْهِهِ مَظَاهِرُ الاحْتِشَامِ"" : الاسْتِحْيَاءِ والخَجَلِ. 2.""كَلَّمَتْهُ بِأدَبٍ وَاحْتِشامٍ"" : بِوَقَارٍ وَتَعَفُّفٍ. ""لاَ تَظْهَرُ في الشَّارِعِ إلاَّ بِملابِس الاحْتِشَامِ"". 3.""وَقَفَ الْمُتّهَمُ في احْتِشَامٍ"" : في انْقِباضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17115, 'اِحْتِضَارٌ', 'احتضار', 'مصدر', 'حضر', 'احتضار', 'حتضر', 'مص. اِحْتَضَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِضَارٌ-اِحْتِضَارٌ [ح ض ر] (مص. اِحْتَضَرَ). ""يَعِيشُ لَحْظَةَ الاحْتِضَارِ"" : لَحْظَةَ الْمَوْتِ، النَّزْعَ الأَخِيرَ، لَحْظَةَ خُرُوجِ الرُّوحِ. ""أحاطَ الأهْلُ بِجَدِّهِمْ لَحْظَةَ احْتِضَارِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17116, 'احْتِضَانٌ', 'احتضان', 'مصدر', 'حضن', 'احتضان', 'حتضن', 'مص. اِحْتَضَن', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"احْتِضَانٌ-احْتِضَانٌ [ح ض ن] (مص. اِحْتَضَن). 1.""كان احْتضانُ الأمِّ لابْنِها تَعْبيرًا عَنْ حُبٍّ دَفِينٍ"" : حَضْنُهُ وَضَمُّهُ إلى صَدْرهَا. 2.""اِحْتَضانُ الطَّيْرِ لِبَيْضِهِ"" : تَرْخيمُهُ واحْتِوَاؤُهُ بجَناحَيْهِ على البَيْضِ. 3.""كانَ احْتِضانُهُ لأَفْكَارِ عَقِيدَتِهِ عَنِ اقْتِناع"" : تَبَنّيها وَالدِّفَاعُ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17117, 'اِحْتِطَابٌ', 'احتطاب', 'مصدر', 'حطب', 'احتطاب', 'حتطب', 'مص. اِحْتَطَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِطَابٌ-اِحْتِطَابٌ [ح ط ب] (مص. اِحْتَطَبَ). ""اِحْتِطَابُ الحَطَبِ"": جَمْعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17118, 'اِحْتِفَاظٌ', 'احتفاظ', 'مصدر', 'حفظ', 'احتفاظ', 'حتفظ', 'مص. اِحْتَفَظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِفَاظٌ-اِحْتِفَاظٌ [ح ف ظ] (مص. اِحْتَفَظَ). 1.""كانَ احْتِفاظُهُ بِتَقَالِيدِ شَعْبهِ تَعْبيرًا عَنْ أصالَةٍ ..."" : صِيانَتُهُ لَها. 2.""الاحْتِفَاظُ بالسِّرِّ"" : كِتْمانُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17119, 'اِحْتِمَالٌ', 'احتمال', 'مصدر', 'حمل', 'احتمال', 'حتمل', 'مص. اِحْتَمَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِحْتَمَلَ). 1.""كَانَ النَّاسُ يَتَصَوَّرُونَ احْتِمَالَ وُقوعِ حَرْبٍ جَدِيدَةٍ"" : أيْ إِمْكَانَ وُقُوعِهَا. ""مُحَلِّلُونَ يَمْلَؤُونَ الرُّؤُوسَ بِالاحْتِمَالاتِ والتَّأوِيلاَتِ"". 2. ""هَذَا الأَمْرُ مِنَ الصَّعْبِ احْتِمَالُهُ"" : مِنَ الصَّعْبِ تَحَمُّلُهُ، لاَ يُطَاقُ. ""تَعَلَّمْتُ الصَّبْرَ علَى الدَّرْسِ، وَاحْتِمَالَ العَنَاءِ فِي التَّحْصِيلِ"". (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17120, 'اِحْتِفَاءٌ', 'احتفاء', 'مصدر', 'حفو', 'احتفاء', 'حتف', 'مص. اِحْتَفَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِحْتِفَاءٌ-اِحْتِفَاءٌ [ح ف و] (مص. اِحْتَفَى). 1. ""خَرَجَ النَّاسُ احْتِفَاءً بِقُدُومِهِ"" : تَرْحِيباً وَتَكْرِيماً. 2.""مِن عَادَةِ الشُّعُوبِ الاحْتِفَاءُ بِذِكْرَى اسْتِقْلاَلِهَا"" : إِقَامَةُ عِيدٍ لِذِكْرَاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17121, 'اِحْتِقَارٌ', 'احتقار', 'مصدر', 'حقر', 'احتقار', 'حتقر', 'مص. اِحْتقَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِقَارٌ-اِحْتِقَارٌ [ح ق ر] (مص. اِحْتقَرَ). 1. ""وَجَّهَ إِلَيْهِ نَظَرَاتِ احْتِقَارٍ"" : اِزْدِرَاءٍ، اِسْتِصْغَارٍ. ""احْتِقَارًا لَهُ لَمْ يَعُدْ أَحَدٌ يَتَعَامَلُ مَعَهُ"" ""خَاطَبَهُ بِلَهْجَةِ الاحْتِقَارِ والازْدِرَاءِ"" ""عُرِفَ باحْتِقَارِهِ لِلدُّنْيَا وَنِعَمِهَا"". (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17122, 'اِحْتِقانٌ', 'احتقان', 'مصدر', 'حقن', 'احتقان', 'حتقن', 'مص. اِحْتقَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِقانٌ-اِحْتِقانٌ [ح ق ن] (مص. اِحْتقَنَ). 1.""قامَ الْمُمَرِّضُ باحْتقانِ الْمَرِيضِ"" : أَي حَقْنُهُ بِالحُقْنَةِ. 2.""اِحْتِقانُ العُضْوِ التَّنَاسُلِيِّ"" : اِحْتِبَاسُ البَوْلِ فِيهِ. 3.""اِحْتقانُ الدَّمِ""‎: اجْتماعُ الدَّمِ فِي الجَوْفِ مِنْ طعْنةٍ وَنَحْوِها. 4. ""اِحْتِقَانُ الحُزْنِ في نَفْسِهِ"" : تَجمُّعُهُ تَراكُمُهُ، اِحْتِباسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17123, 'اِحْتِكَاكٌ', 'احتكاك', 'مصدر', 'حكك', 'احتكاك', 'حتكك', 'مص. اِحْتَكَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِكَاكٌ-اِحْتِكَاكٌ [ح ك ك] (مص. اِحْتَكَّ). 1. ""اسْتَمَرَّ احْتِكَاكُهُ بِصَدِيقِهِ زَمَناً طويلاً"" : الاتِّصَالُ بهِ. 2. ""الاحْتِكَاكُ بِقضَايَا الشَّعْبِ"" : الالْتِصَاقُ بِها وَتَعَرُّفُها عَنْ قرْبٍ. 3.""زَاوِيَةُ الاِحْتِكَاكِ"" (فز) : زَاوِيَةُ التَّلاَمُسِ. 4. ""قوَّةُ الاحْتِكَاكِ"" : القُوَّةُ النَّاجِمَةُ عن مُقاومةٍ من جَرّاءِ تَلاَمُسِ سُطوحِ الأَجْسَام، وَتَكُونُ بِاتّجاهٍ مضادٍّ لِلتَّحرُّكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17124, 'اِحْتِكَارٌ', 'احتكار', 'مصدر', 'حكر', 'احتكار', 'حتكر', 'مص. اِحْتَكَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. اِحْتَكَرَ). 1.""تَقُومُ شَرِكَةٌ بِاحْتِكَارِ الْمَوَادِّ الغِذَائِيَّةِ"" : تَسْتَأْثِرُ بِهَا وَتَخْزِنُهَا إِلَى أَنْ تُصْبحَ نَادِرَةً فِي الأسْوَاقِ، لِتَبيعَهَا بِأسْعَارٍ بَاهِظَةٍ . 2.""تُعَاقِبُ الحُكُومَةُ كلَّ احْتِكَارٍ لِلسِّلَعِ"" : كُلَّ اسْتِئْثَارٍ، كُلَّ مُضَارَبَةٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17125, 'اِحْتِكَامٌ', 'احتكام', 'مصدر', 'حكم', 'احتكام', 'حتكم', 'مص. اِحْتَكَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِكَامٌ-اِحْتِكَامٌ [ح ك م] (مص. اِحْتَكَمَ). ""الاحْتِكامُ إلى القَضاءِ"" : التَّحاكم والْمُثول...، قَبول حُكْمِ القَضَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17126, 'اِحْتِلاَلٌ', 'احتلال', 'مصدر', 'حلل', 'احتلال', 'حتلل', 'مص. اِحْتَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِلاَلٌ-اِحْتِلاَلٌ [ح ل ل] (مص. اِحْتَلَّ). ""دَخَلَتْ جُيُوشُ الاحْتِلاَلِ البِلاَدَ "": دُخُول البلاَدِ والاسْتِيلاَءُ عَلَى أرَاضِيهَا قَهْراً وَغَزْوًا. ""نَظَّمَ الشَّعْبُ مُقَاوَمَةً جَبَّارَةً ضِدَّ الاحْتِلالِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17127, 'اِحْتِلاَبٌ', 'احتلاب', 'مصدر', 'حلب', 'احتلاب', 'حتلب', 'مص. اِحْتَلَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِلاَبٌ-اِحْتِلاَبٌ [ح ل ب] (مص. اِحْتَلَبَ). ""اِحْتِلاَبُ البَقَرةِ"" : اِسْتِخْراجُ اللَّبَنِ مِنْ ضَرْعِها يَدَوِيّاً أو آلِياً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17128, 'اِحْتِلاَمٌ', 'احتلام', 'مصدر', 'حلم', 'احتلام', 'حتلم', 'مص. اِحْتَلَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْتِلاَمٌ-اِحْتِلاَمٌ [ح ل م] (مص. اِحْتَلَمَ). ""اِحْتِلاَمُ الوَلَدِ"" : إِدْرَاكُهُ وَبُلُوغُهُ مَبَالِغَ الرِّجَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17129, 'إِحْرَامٌ', 'إحرام', 'مصدر', 'حرم', 'ءحرام', 'إحرم', 'مص. أحْرَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْرَامٌ-إِحْرَامٌ [ح ر م] (مص. أحْرَمَ) : دُخُولُ الحَاجِّ بِالحَجِّ أو العُمْرَةِ، وَهوَ مَا يَفْرِضُ الامْتِنَاعَ عَنْ لُبْس الثَّوْبِ الْمَخِيطِ، وَصيْدِ الصَّيدِ، والنِّكَاحِ والتَّطَيُّبِ بِالطِّيبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17130, 'اِحْتِمَاءٌ', 'احتماء', 'مصدر', 'حمي', 'احتماء', 'حتم', 'مص. اِحْتَمَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِحْتِمَاءٌ-اِحْتِمَاءٌ [ح م ي] (مص. اِحْتَمَى). 1. ""الاِحْتِمَاءُ وَرَاءَ الْمَتَارِيسِ"" : الالْتِجاءُ إِلَيْهَا حِمايةً. 2. ""الاحْتِمَاءُ مِنَ البَرْدِ"": الاتِّقَاءُ مِنْهُ. 3. ""اِحْتِمَاءُ الْمَرِيضِ"": لُجوؤُهُ إلى نِظامٍ خَاصٍّ في الأَكْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17131, 'اِحْتِواءٌ', 'احتواء', 'مصدر', 'حوي', 'احتواء', 'حت', 'مص. اِحْتَوَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِحْتِواءٌ-اِحْتِواءٌ [ح و ي] (مص. اِحْتَوَى). 1. ""اِحْتِوَاءُ الطِّفْلِ"": اِحْتِضَانُهُ، حَضْنُهُ. 2. ""اِحْتِوَاءُ الحَدَثِ"" : حَصْرُ نَتائِجِهِ. 3.""اِحْتِواءُ الكِتابِ على فُصولٍ"" : اِشْتِمَالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17132, 'إِحْجَامٌ', 'إحجام', 'مصدر', 'حجم', 'ءحجام', 'إحجم', 'مص. أَحْجَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْجَامٌ-إِحْجَامٌ [ح ج م] (مص. أَحْجَمَ). ""لا يُقْبِلُ عَلَى عَمَل إِلاَّ بَعْدَ الإِحْجَامِ الطَّوِيلِ"". (طه حسين) : التَّرَاجُعُ، التَّرَدُّدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17133, 'إِحْدَاثٌ', 'إحداث', 'مصدر', 'حدث', 'ءحداث', 'إحدث', 'مص. أَحْدَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْدَاثٌ-إِحْدَاثٌ [ح د ث] (مص. أَحْدَثَ). 1. ""إحْدَاثُ مَنْصِبٍ جَدِيدٍ"" : إِيجَادُهُ. 2.""إِحْدَاثُ الفَوْضَى"" : إِثَارَتُهَا، خَلْقُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17134, 'إِحْدَاقٌ', 'إحداق', 'مصدر', 'حدق', 'ءحداق', 'إحدق', 'مص. أحْدَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْدَاقٌ-إِحْدَاقٌ [ح د ق] (مص. أحْدَقَ). 1. ""حَاوَلُوا الإحْدَاقَ بهِ"": مُحَاصَرَتَهُ، الإِحَاطَةَ بِهِ. 2. ""إِحْدَاقُ النَّظَرِ في الصُّورَةِ"": إمْعَانُ النَّظَرِ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17135, 'اِحْدِيدَابٌ', 'احديداب', 'مصدر', 'حدب', 'احديداب', 'حددب', 'مص. اِحْدَوْدَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْدِيدَابٌ-اِحْدِيدَابٌ [ح د ب] (مص. اِحْدَوْدَبَ). 1.""اِحْدِيدَابُ الشَّيْخِ"" : أَيْ مَيْلُ ظَهْرِهِ إِلَى أَعْلاهُ كَأَنَّهُ حَامِلُ صُرَّةٍ فَوْقَ ظَهْرِهِ. 2. ""اِحْدِيدَابُ الأَرْضِ"" : اِرْتِفَاعُ مُنْحَدَرَاتهَا. 3. ""اِحْدِيدَابُ القَضِيبِ"" : اِعْوِجَاجُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17136, 'إِحْرَاجٌ', 'إحراج', 'مصدر', 'حرج', 'ءحراج', 'إحرج', 'مص. أَحْرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْرَاجٌ-إِحْرَاجٌ [ح ر ج] (مص. أَحْرَجَ). ""وَقَعَ إِحْرَاجُهُ"" : أَيْ جَعْلُهُ فِي ضَيْقٍ وَحَرَجٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17137, 'إِحْرَازٌ', 'إحراز', 'مصدر', 'حرز', 'ءحراز', 'إحرز', 'مص. أَحْرَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْرَازٌ-إِحْرَازٌ [ح ر ز] (مص. أَحْرَزَ). ""إِحْرَازُ النَّصْرِ"" : نَيْلُهُ والحُصُولُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17138, 'إِحْرَاقٌ', 'إحراق', 'مصدر', 'حرق', 'ءحراق', 'إحرق', 'مص. أحْرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْرَاقٌ-إِحْرَاقٌ [ح ر ق] (مص. أحْرَقَ). ""إِحْرَاقُ الحَطَبِ"": حَرْقُهُ، أَيْ إِشْعَالُ النَّارِ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17139, 'اِحْمِرَارٌ', 'احمرار', 'مصدر', 'حمر', 'احمرار', 'حمرر', 'مص. اِحْمَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْمِرَارٌ-اِحْمِرَارٌ [ح م ر] (مص. اِحْمَرَّ). ""اِحْمِرَارُ الوَجْهِ"" : عَلاؤُهُ حُمْرَةٌ. ""عَلاَ الاحْمِرَارُ الأُفُقَ عِنْدَ غُروبِ الشَّمْسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17140, 'إِحْزَانٌ', 'إحزان', 'مصدر', 'حزن', 'ءحزان', 'إحزن', 'مص. أحْزَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْزَانٌ-إِحْزَانٌ [ح ز ن] (مص. أحْزَنَ). ""إِحْزَانُ الوَلَدِ"": تَصْيِيرُهُ حَزِيناً كَئِيباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17141, 'إِحْسَاسٌ', 'إحساس', 'مصدر', 'حسس', 'ءحساس', 'إحسس', 'مص. أَحَسَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْسَاسٌ-إِحْسَاسٌ [ح س س] (مص. أَحَسَّ). 1. ""هُوَ شَدِيدُ الإِحْسَاسِ"" : سَرِيعُ التَّأَثُّرِ. ""هُوَ عَدِيمُ الإِحْسَاسِ"". 2.""كَانَ إِحْسَاسُهُ شَدِيدًا أمَامَ هَوْلِ الكَارِثَةِ"" : شُعورُهُ. ""اِسْتَوْلَى عَلَيْهِ إِحْسَاسٌ غَرِيبٌ أثَّرَ في مِزَاجِهِ"" ""يَجْمَعُ العَرَبَ إِحْسَاسٌ مُشْتَرَكٌ بِالوَحْدَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17142, 'إحْسَانٌ', 'إحسان', 'مصدر', 'حسن', 'ءحسان', 'إحسن', 'مص. أحْسَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إحْسَانٌ-إحْسَانٌ [ح س ن] (مص. أحْسَنَ). النحل آية 90إِنَّ الله يَأْمُرُ بالعَدْلِ والإحْسَان (قرآن) : إِعْطَاءُ الحَسَنَةِ وَفِعْلُ الخَيْرِ. الأحقاف 15وَوَصَّيْنَا الإِنْسَانَ بِوَالِدَيْهِ إِحْسَاناً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17143, 'إِحْصَاءٌ', 'إحصاء', 'مصدر', 'حصي', 'ءحصاء', 'إحص', 'مص. أحْصَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِحْصَاءٌ-إِحْصَاءٌ [ح ص ي] (مص. أحْصَى). ""قَامَتِ الحُكُومَةُ بِإحْصَاءِ عَدَدِ السُّكَّانِ"" : أحْصَتْهُمْ وَعَدَّدَتْهُمْ فِي لَوَائِحَ. ""اِنْشَغَلَتِ اللَّجْنَةُ بِإِحْصاءِ عَدَدِ الأَصْوَاتِ بَعْدَ انْتِهَاءِ عَمَلِيَّةِ الاقْتِرَاعِ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17144, 'إحْضَارٌ', 'إحضار', 'مصدر', 'حضر', 'ءحضار', 'إحضر', 'مص. أَحْضَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إحْضَارٌ-إحْضَارٌ [ح ض ر] (مص. أَحْضَرَ). ""طَلَبَ إِحْضَارَهُ"": أَيِ الإتْيَانَ بِهِ. ""إِحْضَارُ الطَّعَامِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17145, 'إِحْقَاقٌ', 'إحقاق', 'مصدر', 'حقق', 'ءحقاق', 'إحقق', 'مص. أحَقَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْقَاقٌ-إِحْقَاقٌ [ح ق ق] (مص. أحَقَّ). ""إِحْقَاقُ الحَقِّ"" : إِثْبَاتُهُ، فَرْضُهُ، تَأْكِيدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17146, 'إحْكَامٌ', 'إحكام', 'مصدر', 'حكم', 'ءحكام', 'إحكم', 'مص. أحْكَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إحْكَامٌ-إحْكَامٌ [ح ك م] (مص. أحْكَمَ). ""إِحْكَامُ الصَّانِعِ لِعَمَلِهِ"": إِتْقَانُهُ، ضَبْطهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17147, 'إِحْلاَلٌ', 'إحلال', 'مصدر', 'حلل', 'ءحلال', 'إحلل', 'مص. أحَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْلاَلٌ-إِحْلاَلٌ [ح ل ل] (مص. أحَلَّ). 1. ""إِحْلاَلُ أَمْرٍ"" : جَعْلُهُ حَلاَلاً. 2. ""إِحْلالُ الحَاجِّ"": الفَرَاغُ وَالانْتِهَاءُ مِنْ أَفْعَالِ الحَجِّ وَمَرَاسِيمِهِ، ضِدُّ الإِحْرَام. 3. ""إِحْلاَلُ السَّلاَمِ"" : نَشْرُهُ وَتَحْقِيقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17148, 'إِحْلاَفٌ', 'إحلاف', 'مصدر', 'حلف', 'ءحلاف', 'إحلف', 'مص. أحْلَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْلاَفٌ-إِحْلاَفٌ [ح ل ف] (مص. أحْلَفَ). ""إِحْلاَفُ الرَّجُلِ"": جَعْلهُ يَحْلِفُ، يُقْسِمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17149, 'إِخْبَارٌ', 'إخبار', 'مصدر', 'خبر', 'ءخبار', 'إخبر', 'مص. أخْبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"إِخْبَارٌ-إِخْبَارٌ [خ ب ر] (مص. أخْبَرَ). ""إِخْبَارُهُ بِمَا حَدَثَ"": إِعْلاَمُهُ، أَيْ نَقْلُ مَا حَدَثَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17150, 'إِحْمَاضٌ', 'إحماض', 'مصدر', 'حمض', 'ءحماض', 'إحمض', 'مص. أحْمَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْمَاضٌ-إِحْمَاضٌ [ح م ض] (مص. أحْمَضَ).""إِحْمَاضُ الطَّعَام"": جَعْلُهُ حَامِضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17151, 'إحْمَاءٌ', 'إحماء', 'مصدر', 'حمي', 'ءحماء', 'إحم', 'مص. أحْمَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إحْمَاءٌ-إحْمَاءٌ [ح م ي] (مص. أحْمَى). ""إِحْمَاءُ الحَدِيدِ"" : تَسْخِينُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17152, 'إحْنَاءٌ', 'إحناء', 'مصدر', 'حني', 'ءحناء', 'إحن', 'مص. أحْنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إحْنَاءٌ-إحْنَاءٌ [ح ن ي] (مص. أحْنَى). ""وَجَدَ عِنْدَهُ إِحْنَاءً"": شَفَقَة، حُنُوًّا، رَحْمَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17153, 'إِحْوَاجٌ', 'إحواج', 'مصدر', 'حوح', 'ءحواج', 'إحج', 'مص. أَحْوَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِحْوَاجٌ-إِحْوَاجٌ [ح و ح] (مص. أَحْوَجَ). ""إِحْوَاجُ الرَّجُلِ"" : جَعْلُهُ مُحْتَاجاً، إِرْغَامُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17154, 'اِحْوِرَارٌ', 'احورار', 'مصدر', 'حور', 'احورار', 'حرر', 'مص. اِحْوَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْوِرَارٌ-اِحْوِرَارٌ [ح و ر] (مص. اِحْوَرَّ). ""اِحْوِرَارُ العَيْنِ"": اِشْتَدَّ بَيَاضُهَا وَسوَادُ سَوادِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17155, 'اِحْوِلاَلٌ', 'احولال', 'مصدر', 'حول', 'احولال', 'حلل', 'مص. اِحْوَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِحْوِلاَلٌ-اِحْوِلاَلٌ [ح و ل] (مص. اِحْوَلَّ). ""اِحْوِلاَلُ العَيْنِ"": صَيْرُ حَوَلٍ بِهَا، أَيْ مَيْلُ إِحْدَى الحَدَقَتَيْنِ إِلَى جهَةِ اليَمِين وَالأُخْرَى جِهَةَ اليَسَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17156, 'إِحْيَاءٌ', 'إحياء', 'مصدر', 'حيي', 'ءحياء', 'إح', 'مص. أَحْيَا', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِحْيَاءٌ-إِحْيَاءٌ [ح ي ي] (مص. أَحْيَا). 1. ""مَنْ يَقْدِرُ عَلَى إِحْيَاءِ الْمَوْتَى"" : عَلَى إِعَادَةِ بَعْثِ الحَيَاةِ فِيهَا. 2. ""إِحْيَاءُ الأَرْضِ"": إِخْصَابُهَا، جَعْلُهَا صَالِحَةً للزِّرَاعَةِ. 3.""قَامَ الشّعْبُ بإحْيَاءِ ذ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17157, 'اِخْضِيضَارٌ', 'اخضيضار', 'مصدر', 'خضر', 'اخضيضار', 'خضضر', 'مص. اِخضر', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْضِيضَارٌ-اِخْضِيضَارٌ [خ ض ر] (مص. اِخْضَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17158, 'إِخَافَةٌ', 'إخافة', 'مصدر', 'خوف', 'ءخافة', 'إخفة', 'مص. أخَافَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخَافَةٌ-إِخَافَةٌ [خ و ف] (مص. أخَافَ). ""إِخَافَةُ الوَلَدِ"" : جَعْلُهُ يَخَافُ، إِرْعَابُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17159, 'اِخْتِرَاقٌ', 'اختراق', 'مصدر', 'خرق', 'اختراق', 'خترق', 'مص. اِخْتَرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِرَاقٌ-اِخْتِرَاقٌ [خ ر ق] (مص. اِخْتَرَقَ). 1. ""اِخْتِرَاقُ الثَّوْبِ"": شَقُّهُ. 2. ""اِخْتِرَاقُ الزِّحَامِ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17160, 'إِخْبَاءٌ', 'إخباء', 'مصدر', 'خبو', 'ءخباء', 'إخب', 'مص. أَخْبَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِخْبَاءٌ-إِخْبَاءٌ [خ ب و] (مص. أَخْبَى). 1. ""إِخْبَاءُ الخَيْمَةِ"" : ن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17161, 'اِخْتِيَارٌ', 'اختيار', 'مصدر', 'خير', 'اختيار', 'ختر', 'مص. اِخْتارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِيَارٌ-اِخْتِيَارٌ [خ ي ر] (مص. اِخْتارَ). ""تَرَكَ لَهُ وَالِدُهُ حُرِّيَّةَ الاخْتِيَارِ"" : اِنْتِقَاءُ مَا يُرِيدُهُ، الخِيَارُ. ""أعْتَقِدُ أنِّي أحْسَنْتُ الاخْتِيَارَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17162, 'اِخْتِيَالٌ', 'اختيال', 'مصدر', 'خيل', 'اختيال', 'ختل', 'مص. اِخْتَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِيَالٌ-اِخْتِيَالٌ [خ ي ل] (مص. اِخْتَالَ). ""وَجَدَ فِي مِشْيَتِهِ اخْتِيَالاً"" : تَبَخْتُراً، تَكَبُّراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17163, 'اِخْتِبَاءٌ', 'اختباء', 'مصدر', 'خبأ', 'اختباء', 'ختب', 'مص. اِخْتَبَأ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِخْتِبَاءٌ-اِخْتِبَاءٌ [خ ب أ] (مص. اِخْتَبَأ). 1. ""اِخْتِبَاؤُهُ فِي الْمَغَارَةِ أَثَارَ الاسْتِغْرَابَ"" : اِسْتِتَارُهُ، تَخَفِّيهِ. 2. ""اِخْتِبَاؤُهُ عَنِ الأَنْظَارِ"": اِخْتِفَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17164, 'اِختبَارٌ', 'اختبار', 'مصدر', 'خبر', 'اختبار', 'ختبر', 'مص. اِخْتَبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِخْتَبَرَ). 1.""اِجْتَازَ الاخْتِبَارَ الشَّفَوِيَّ"" : الامْتِحَانَ. 2. ""عَلَى سَبِيلِ الاخْتِبَارِ"": عَلَى "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17165, 'اِخْتِبَازٌ', 'اختباز', 'مصدر', 'خبز', 'اختباز', 'ختبز', 'مص. اِخْتَبَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِبَازٌ-اِخْتِبَازٌ [خ ب ز] (مص. اِخْتَبَزَ). ""اِخْتِبَازُ الخُبْزِ"" : خَبْزُهُ، عَمَلهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17166, 'اِخْتِتَامٌ', 'اختتام', 'مصدر', 'ختم', 'اختتام', 'ختتم', 'مص. اِخْتَتَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِتَامٌ-اِخْتِتَامٌ [خ ت م] (مص. اِخْتَتَمَ). ""تَمَّ اخْتِتَامُ الحَفْلِ بِآيَاتٍ مِنَ الذِّكْرِ الحَكِيمِ"" : إِنْهَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17167, 'اِخْتِتَانٌ', 'اختتان', 'مصدر', 'ختن', 'اختتان', 'ختتن', 'مص. اِخْتَتَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِتَانٌ-اِخْتِتَانٌ [خ ت ن] (مص. اِخْتَتَنَ). ""اِخْتِتَانُ الوَلَدِ"": قَطْعُ قُلْفَةِ ذَكَرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17168, 'اِخْتِرَاعٌ', 'اختراع', 'مصدر', 'خرع', 'اختراع', 'خترع', 'مص. اِخْتَرَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِرَاعٌ-اِخْتِرَاعٌ [خ ر ع] (مص. اِخْتَرَعَ). ""الحَاسُوبُ اِخْتِرَاعٌ جَدِيد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17169, 'اِخْتِلالٌ', 'اختلال', 'مصدر', 'خلل', 'اختلال', 'ختلل', 'مص. اِخْتَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِلالٌ-اِخْتِلالٌ [خ ل ل] (مص. اِخْتَلَّ). 1. ""تَسَبَّبَ فِي اخْتِلاَلِ النِّظَامِ"": إِحْدَاثُ خَللٍ وَفَسَادٍ فِيهِ. 2. ""أُصِيبَ بِاخْتِلالٍ فِي عَقْلِهِ"" : أُصِيبَ بِخَلَلٍ أَفْقَدَهُ الرُّشْدَ. 3. ""حَدَثَ اخْتِلاَلٌ فِي السَّيَّارَةِ"": حَدَثَ اضْطِرَابٌ فِيهَا أَفْقَدَهَا تَوَازُنهَا. ""اِخْتِلاَلُ التَّوازُنِ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17170, 'اِخْتِزَالٌ', 'اختزال', 'مصدر', 'خزل', 'اختزال', 'ختزل', 'مص. اِخْتَزَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِزَالٌ-اِخْتِزَالٌ [خ ز ل] (مص. اِخْتَزَلَ). 1. ""صَارَتْ مُخْتَصَّةً فِي الاخْتِزَالِ"" : مُتَمَكِّنَةً مِنْ ضَبْطِ اِخْتِصارِ كِتَابَةِ الحُرُوفِ بِوَاسِطَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17171, 'اِخْتِزَانٌ', 'اختزان', 'مصدر', 'خزن', 'اختزان', 'ختزن', 'مص. اِخْتزَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِزَانٌ-اِخْتِزَانٌ [خ ز ن] (مص. اِخْتزَنَ). 1. ""اِخْتزَانُ القَمْحِ"": اِدِّخَارُهُ. ""اِخْتِزَانُ الْمَالِ أوِ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17172, 'اِخْتِصَاصٌ', 'اختصاص', 'مصدر', 'خصص', 'اختصاص', 'ختصص', 'مص. اِخْتَصَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِخْتِصَاصٌ-اِخْتِصَاصٌ [خ ص ص] (مص. اِخْتَصَّ). 1.""الاخْتِصَاصُ فِي العِلْمِ ضَرُورِيٌّ"" : الاَنْصِرَافُ والتَّرْكِيزُ عَلَى شَيْءٍ مَّا، أوْ فَرْعٍ مُحَدَّدٍ مِنَ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17173, 'اِخْتِصَارٌ', 'اختصار', 'مصدر', 'خصر', 'اختصار', 'ختصر', 'مص. اِخْتَصَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِصَارٌ-اِخْتِصَارٌ [خ ص ر] (مص. اِخْتَصَرَ). 1.""تَكلَّمَ بِاخْتِصَارٍ"" : بِإيجَازٍ، ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17174, 'اِخْتِصَامٌ', 'اختصام', 'مصدر', 'خصم', 'اختصام', 'ختصم', 'مص. اِخْتَصَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِصَامٌ-اِخْتِصَامٌ [خ ص م] (مص. اِخْتَصَمَ). ""لَمْ يَدُمِ الاخْتِصَامُ بَيْنَهُمَا طَوِيلاً"" : التَّنَازُعُ، التَّخَاصُمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17175, 'اِخْتِضَابٌ', 'اختضاب', 'مصدر', 'خضب', 'اختضاب', 'ختضب', 'مص. اِخْتَضَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِضَابٌ-اِخْتِضَابٌ [خ ض ب] (مص. اِخْتَضَبَ). ""اِخْت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17176, 'اِختِطَاطٌ', 'اختطاط', 'مصدر', 'خطط', 'اختطاط', 'ختطط', 'مص. اِخْتَطَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِختِطَاطٌ-اِختِطَاطٌ [خ ط ط] (مص. اِخْتَطَّ). 1. ""اِخْتِطَاطُ الوَجْهِ"": صَيْرُ خُطُوطٍ فِيهِ. 2. ""اِخْتِطَاطُ الأَرْضِ"" : رَسْمُ حُدُودٍ مَعْلُومَةٍ لَهَا. 3. ""اِخْتِطَاطُ خُطَّةٍ"" : اِتِّخَاذُهَا وَرَسْمُهَا للسَّيْرِ عَلَى نَهْجِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17177, 'اِخْتِطَافٌ', 'اختطاف', 'مصدر', 'خطف', 'اختطاف', 'ختطف', 'مص. اِخْتَطَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِطَافٌ-اِخْتِطَافٌ [خ ط ف] (مص. اِخْتَطَفَ). ""تَعَرَّضتِ الطَّائِرَةُ لِلاخْتِطَافِ وَهِيَ فِي طَرِيقِهَا إِلَى أَثِينَا"" : اِسْتَوْلَى عَلَيْهَا قَرَاصِنَةُ الجَوِّ وَحَوَّلُوا مَسَارَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17178, 'اِختِفَاءٌ', 'اختفاء', 'مصدر', 'خفي', 'اختفاء', 'ختف', 'مص. اِخْتَفَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِختِفَاءٌ-اِختِفَاءٌ [خ ف ي] (مص. اِخْتَفَى). 1. ""أَثَارَ اِخْتِفَاؤُهُ فَجْأَةً عَلاَمَةَ اسْتِفْهَامٍ"" : اِسْتِتَارُهُ، تَوَارِيهِ عَن الأَنْظَارِ. 2.""اِخْتِفَاءُ بَعْض الْمَوَادِّ الغِذَائِيَّةِ مِنَ السُّوقِ"" : نَفَادُهَا وَعَدَمُ العُثُورِ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17179, 'إِخْجالٌ', 'إخجال', 'مصدر', 'خجل', 'ءخجال', 'إخجل', 'مص. أخْجَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخْجالٌ-إِخْجالٌ [خ ج ل] (مص. أخْجَلَ). ""إخْجالُ الوَلَدِ"":جَعْلُهُ يَخْجَلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17180, 'اِخْتِلاَجٌ', 'اختلاج', 'مصدر', 'خلج', 'اختلاج', 'ختلج', 'مص. اِخْتَلَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِخْتَلَجَ). ""اِخْتِلاَجُ القَلْبِ"" : اِرْتِعَاشُهُ، اِضْطِرَابُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17181, 'اخْتِلاَسٌ', 'اختلاس', 'مصدر', 'خلس', 'اختلاس', 'ختلس', 'مص. اِخْتَلَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اخْتِلاَسٌ-اخْتِلاَسٌ [خ ل س] (مص. اِخْتَلَسَ). 1. ""قَامَ بِمُحَاوَلَةِ اخْتِلاسٍ"" : السَّرِقَةُ الْمَوْصُوفَةُ بِالاحْتِيَالِ. 2.""اِخْتِلاَسُ لَحْظَةٍ"": الاِنْفِرَادُ بِلَحْظَةٍ خُفْيَة وبِتحايُلٍ. ""يُبِيحُ لِنَفْسِهِ اخْتِلاَسَ لَحَظَاتِ الزَّهْوِ"". (محمد برادة) ""اِخْتِلاَسُ النَّظَرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17182, 'اِخْتِلاطٌ', 'اختلاط', 'مصدر', 'خلط', 'اختلاط', 'ختلط', 'مص. اِخْتَلَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِلاطٌ-اِخْتِلاطٌ [خ ل ط] (مص. اِخْتَلَطَ). 1. ""اِخْتِلاَطُ الأُمُورِ"": اِلْتِبَاسُهَا، غُمُوضُهَا، اِرْتِبَاكُهَا. 2. ""اِخْتِلاَطُ الرِّجَالِ بِالنِّسَاءِ"": التَّدَاخُلُ فِيمَا بَيْنَهُم. 3. ""اِخْتِلاَطُ الْمَوَادِّ الكِيميَائِيَّةِ"": اِمْتِزَاجُهَا. 4.""كَانَ دَائِمَ الاِخْتِلاَطِ بِالنَّاسِ"" : الاِلْتِقَاء بِهِمْ وَمُعَاشَرَتِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17183, 'اِخْتِلاَفٌ', 'اختلاف', 'مصدر', 'خلف', 'اختلاف', 'ختلف', 'مص. اِخْتَلَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِلاَفٌ-اِخْتِلاَفٌ [خ ل ف] (مص. اِخْتَلَفَ). 1. ""حَصَلَ اخْتِلاَفٌ فِي الرَّأيِ بَيْنَهُمْ"" : تَضَارُبٌ فِي الرَّأْيِ، اِنْعِدَامُ الاتِّفَاقِ. 2.""يَتَمَتَّعُ الْمُوَاطِنُونَ بِحَقِّ الْمُوَاطَنَةِ عَلَى اخْتِلاَفِ مَذَاهِبهمْ وَأحْزَابِهِمْ"" : عَلَى تَنَوُّعِهَا. ""وَجَدَ فِي السُّوقِ فَوَاكِهَ كَثِيرَةً عَلَى اخْتِلاَفِ أَنْوَاعِهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17184, 'اِخْتِلاَقٌ', 'اختلاق', 'مصدر', 'خلق', 'اختلاق', 'ختلق', 'مص. اِخْتَلقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِلاَقٌ-اِخْتِلاَقٌ [خ ل ق] (مص. اِخْتَلقَ). ""اِخْتِلاقُ الأَكَاذِيبِ"" : الادِّعَاءُ، الافْتِرَاءُ.ص آية 7 مَا سَمِعْنَا بِهَذَا فِي المِلَّةِ الآخِرَةِ إِنْ هَذَا إِلاَّ اخْتِلاق ( قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17185, 'اِخْتِلاَءٌ', 'اختلاء', 'مصدر', 'خلو،خلي', 'اختلاء', 'ختل', 'مص. اِخْتَلى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِخْتِلاَءٌ-اِخْتِلاَءٌ [خ ل و، خ ل ي] (مص. اِخْتَلى). ""حَاوَلَ الاخْتِلاَءَ بِهِ"" : الانْفِرَادَ بهِ، خَلْوَةً. ""يَبْحَث عَنْ مَكَانٍ لِلاخْتِلاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17186, 'اِخْتِمَارٌ', 'اختمار', 'مصدر', 'خمر', 'اختمار', 'ختمر', 'مص. اِخْتَمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِمَارٌ-اِخْتِمَارٌ [خ م ر] (مص. اِخْتَمَرَ). ""لابُدَّ لِلْعَجينِ مِنَ الاخْتِمَارِ"":أيْ أنْ يُتْرَكَ مُدّةً لِيَسْتَوِيَ، أَيْ حُصُول تَحَوُّلِ الْمَوَادِّ العُضْوِيَّةِ فِيهِ كِيمَاوِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17187, 'اِخْتِنَاقٌ', 'اختناق', 'مصدر', 'خنق', 'اختناق', 'ختنق', 'مص. اِخْتَنَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْتِنَاقٌ-اِخْتِنَاقٌ [خ ن ق] (مص. اِخْتَنَقَ). ""اِمْتَلَأَتِ الغُرْفَةُ بالدُّخَانِ وَشَعَرَ النَّاسُ بالاخْتِنَاقِ"" : بَدَأَتْ أَنْفَاسُهُمْ تَتَعَرَّضُ لِلضَّيْقِ. ""كَادَ يَمُوتُ مِنَ الاخْتِنَاقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17188, 'إِخْثَارٌ', 'إخثار', 'مصدر', 'خثر', 'ءخثار', 'إخثر', 'مص. أَخْثَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخْثَارٌ-إِخْثَارٌ [خ ث ر] (مص. أَخْثَرَ). ""إِخْثَارُ اللَّبَنِ"" : تَصْيِيرُهُ مُكَثَّفاً وَجَامِداً، تَرْوِيبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17189, 'إِخْضَابٌ', 'إخضاب', 'مصدر', 'خضب', 'ءخضاب', 'إخضب', 'مص. أَخْضَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخْضَابٌ-إِخْضَابٌ [خ ض ب] (مص. أَخْضَبَ). ""إِخْضَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17190, 'إِخْدَاعٌ', 'إخداع', 'مصدر', 'خدع', 'ءخداع', 'إخدع', 'مص. أَخْدَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخْدَاعٌ-إِخْدَاعٌ [خ د ع] (مص. أَخْدَعَ). ""إِخْدَاعُ الرَّجُلِ"": حَمْلهُ على الْمُخَادَعَةِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17191, 'مُؤَاخَذَةٌ', 'مؤاخذة', 'مصدر', 'أخذ', 'مءاخذة', 'مخذة', 'مص. آخَذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. آخَذَ). 1.""بِلاَ مُؤَاخَذَةٍ"" : بِلاَ لَوْمٍ وَعِتَابٍ. ""لاَ مُؤَاخَذَةَ عَلَى مَا قُمْتَ بِهِ"". 2.""لاَ مُؤََاخَذَةَ"" : عَفْواً، أَرْجُوكَ لاَ تُؤَاخِذْنِي، مَعْذِرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17192, 'أخْذٌ', 'أخذ', 'مصدر', 'أخذ', 'ءخذ', 'خذ', 'مص. أخَذَ', '', '', 'مفرد', 'DnN', '', '', '"أُخْذان(المعجمالوسيط)"', '', '', '', '', '', '', '', '', '"أخْذٌ-أخْذٌ [ أ خ ذ] (مص. أخَذَ). 1. ""أخْذُ كَأْسٍ"" : تَنَاوُلُهُ. 2. ""الأَخْذُ بالسُّلُوكِ الحَسَنِ"" : الاقْتِدَاءُ بهِ. 3. ""أخْذُ العُدَّةِ"": الاسْتِعْدَادُ. 4. ""إِنَّ التَّعَامُلَ مَعَ النَّاسِ أَخْذٌ وَعَطَاءٌ"" : أَنْ تَأخُذَ وَتُعْطِيَ، تَبَادُلُ الآرَاءِ وَالْمُعَامَلاَتِ. 5. ""لاَ يَقْبَلُ القَانُونُ أَخْذاً وَلاَ رَدّاً"" : لا يَقْبلُ النِّقاشَ والْمُجادَلَةَ. ""مَوْضُوعٌ قَابِلٌ لِلأخْذِ وَالرَّدِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17193, 'أُخْذان', 'أخذان', 'مصدر', '', 'ءخذان', 'خذن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17194, 'تَأْخِيرٌ', 'تأخير', 'مصدر', 'أخر', 'تءخير', 'تخر', 'مص. أَخَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْخِيرٌ-تَأْخِيرٌ [أ خ ر] (مص. أَخَّرَ). 1.""يَنْبَغِي تَأْخِيرُ الْمَوْعِدِ"" : تَأْجِيلُهُ. 2.""وَقَعَ تَأْخِيرٌ"" : حَصَلَ إِبْطَاءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17195, 'إِخْرَاجٌ', 'إخراج', 'مصدر', 'خرج', 'ءخراج', 'إخرج', 'مص. أخْرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخْرَاجٌ-إِخْرَاجٌ [خ ر ج] (مص. أخْرَجَ). 1. ""إِخْرَاجُ الطَّعَامِ مِنَ الفُرْنِ"" : جَذْبُهُ، سَحْبُهُ. 2. ""إِخْرَاجُ اللِّسَانِ"" : إِظْهَارُهُ. 3.""مَسْرَحِيَّةٌ مِنْ إِخْرَاج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17196, 'إِخْرَاسٌ', 'إخراس', 'مصدر', 'خرس', 'ءخراس', 'إخرس', 'مص. أخْرسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخْرَاسٌ-إِخْرَاسٌ [خ ر س] (مص. أخْرسَ). ""إِخْرَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17197, 'إِخْزَاءٌ', 'إخزاء', 'مصدر', 'خزي', 'ءخزاء', 'إخز', 'مص. أخْزَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِخْزَاءٌ-إِخْزَاءٌ [خ ز ي] (مص. أخْزَى). ""إخْزَاءُ اللِّصِّ"" : إِيقَاعُهُ في الخِزْيِ وَالذُّلِّ وَالْمَهَانَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17198, 'إِخْصَابٌ', 'إخصاب', 'مصدر', 'خصب', 'ءخصاب', 'إخصب', 'مص. أَخْصَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخْصَابٌ-إِخْصَابٌ [خ ص ب] (مص. أَخْصَبَ). 1. ""إِخْصَابُ الحُقُولِ فِي الرَّبِيعِ"" : كثْرَةُ العُشْبِ وَالكلإِ بِهَا. 2.""الإِخْصَابُ فِي عِلْمِ الأَحْيَاءِ"" : اِنْدِمَاجُ الخَلِيَّةِ الْمُؤ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17199, 'اِخْضِرَارٌ', 'اخضرار', 'مصدر', 'خضر', 'اخضرار', 'خضرر', 'مص. اِخْضَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِخْضِرَارٌ-اِخْضِرَارٌ [خ ض ر] (مص. اِخْضَرَّ). ""اِخْضِرَارُ الحُقُولِ"": خُضْرَتُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17200, 'إِخْضَاعٌ', 'إخضاع', 'مصدر', 'خضع', 'ءخضاع', 'إخضع', 'مص. أخْضَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخْضَاعٌ-إِخْضَاعٌ [خ ض ع] (مص. أخْضَعَ). ""إِخْضاعُ الرَّجُلِ"": جَعْلهُ خاضِعاً تابِعاً مُهاناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17201, 'إِخْطَارٌ', 'إخطار', 'مصدر', 'خطر', 'ءخطار', 'إخطر', 'مص. أخْطَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخْطَارٌ-إِخْطَارٌ [خ ط ر] (مص. أخْطَرَ). ""وَقَعَ إِخْطَارُهُ بالحادِثِ"": إِعْلاَمُهُ، إِبْلاَغُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17202, 'إخفَاقٌ', 'إخفاق', 'مصدر', 'خفق', 'ءخفاق', 'إخفق', 'مص. أخْفَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إخفَاقٌ-إخفَاقٌ [خ ف ق] (مص. أخْفَقَ). ""لَمْ يَتَحَمَّلْ إِخْفَاقَهُ"": فَشَلهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17203, 'إِخْفَاءٌ', 'إخفاء', 'مصدر', 'خفي', 'ءخفاء', 'إخف', 'مص. أخْفى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِخْفَاءٌ-إِخْفَاءٌ [خ ف ي] (مص. أخْفى). ""إِخْفَاءُ العُيوبِ"": التَّسَتُّرُ عَلَيْهَا، عَدَمُ إِظْهَارها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17204, 'إِخْلالٌ', 'إخلال', 'مصدر', 'خلل', 'ءخلال', 'إخلل', 'مص. أخَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخْلالٌ-إِخْلالٌ [خ ل ل] (مص. أخَلَّ). 1. ""الإخْلاَلُ بِالواجِبِ"": التَّقْصِيرُ فيه. 2. ""الإِخْلاَلُ بالْوَعْدِ"" : عَدَمُ الالْتِزَامِ والوَفَاءِ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17205, 'إِخْلاَدٌ', 'إخلاد', 'مصدر', 'خلد', 'ءخلاد', 'إخلد', 'مص. أخْلَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخْلاَدٌ-إِخْلاَدٌ [خ ل د] (مص. أخْلَدَ). ""الإخْلادُ إلى الرَّاحَةِ"": الْمَيْلُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17206, 'إِخْلاَصٌ', 'إخلاص', 'مصدر', 'خلص', 'ءخلاص', 'إخلص', 'مص. أخْلَصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخْلاَصٌ-إِخْلاَصٌ [خ ل ص] (مص. أخْلَصَ). ""اِشْتَغَلَ بِإِخلاَصٍ"": بِصِدْقٍ، بِتَفانٍ. ""أشَادَ بِإِخْلاصِهِ"" ""مِنْ أَوْجَبِ الوَاجِبَاتِ الإِخْلاصُ لِلْوَطَنِ وَالتَّفَانِي فِي حُبِّهِ"" . ""الإِخْلاصُ في العَمَلِ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17207, 'إِخْلاَفٌ', 'إخلاف', 'مصدر', 'خلف', 'ءخلاف', 'إخلف', 'مص. أخْلَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخْلاَفٌ-إِخْلاَفٌ [خ ل ف] (مص. أخْلَفَ). ""إِخْلاَفُ الوَعْدِ"": عَدَمُ الوَفَاءِ بهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17208, 'إِخْمادٌ', 'إخماد', 'مصدر', 'خمد', 'ءخماد', 'إخمد', 'مص. أَخْمَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِخْمادٌ-إِخْمادٌ [خ م د] (مص. أَخْمَدَ). 1. ""سارَعُوا إلى إِخْمَادِ النِّيرانِ"" : إطْفاءِ لَهِيبِها. 2. ""عَمِلُوا على إِخْمَادِ الفِتْنَةِ"": تَوْقيفِها، تَهْدِئَتِهَا، تَسْكينِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17209, 'إِخْنَاءٌ', 'إخناء', 'مصدر', 'خنو', 'ءخناء', 'إخن', 'مص. أخْنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِخْنَاءٌ-إِخْنَاءٌ [خ ن و] (مص. أخْنَى). 1.""الإِخْناءُ في الكَلاَمِ"": الإفْحَاشُ فِيهِ. 2. ""إِخْنَاءُ الدَّهْرِ على الرَّجُلِ"" : الجَوْرُ عَلَيْهِ، إِهْلاَكُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17210, 'إِخَاءٌ', 'إخاء', 'مصدر', 'أخو', 'ءخاء', 'إخ', 'مص. آخَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِخَاءٌ-إِخَاءٌ [أ خ و] (مص. آخَى). ""بيْنَهُمَا مَوَدَّةٌ وَإِخَاءٌ"": صَدَاقَةٌ، أُخُوَّةٌ. ""لاَ تَنْقَطِعُ بَيْنَهُمْ أَسْبَابُ الْمَوَدَّةِ وَالإِخَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17211, 'مُؤَاخَاةٌ', 'مؤاخاة', 'مصدر', 'أخي', 'مءاخاة', 'مخة', 'مص. آخَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُؤَاخَاةٌ-مُؤَاخَاةٌ [أ خ ي] (مص. آخَى). ""اِسْتَمَرَّتِ الْمُؤَاخَاةُ بَيْنَهُمَا زَمَناً طَوِيلاً"" : مَحَبَّةُ الإخْوَةِ، وَصَفَاءُ الإخْوِانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17212, 'إِدَارَةٌ', 'إدارة', 'مصدر', 'دور', 'ءدارة', 'إدرة', 'مص. أدَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. أدَارَ). 1. ""إِدَارَةُ العِمَامَةِ على الرَّأْسِ"" : لَفُّها. 2. ""إدارَةُ العَجَلَةِ"" : جَعْلُها تَدُورُ. 3. إدَارَةُ الوَجْهِ"" : الإِشَاحَةُ بِهِ. 4. ""عُيِّنَ مُدِيراً عَلَى إِدَارَةِ الْم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17213, 'إِدَانَةٌ', 'إدانة', 'مصدر', 'دين', 'ءدانة', 'إدنة', 'مص. أَدَانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِدَانَةٌ-إِدَانَةٌ [د ي ن] (مص. أَدَانَ). 1.""بِالرَغْمِ من مُرَافَعَةِ الْمُحَامِي صَدَرَ الحُكْمُ بِإدان"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17214, 'تَأْدِيبٌ', 'تأديب', 'مصدر', 'أدب', 'تءديب', 'تدب', 'مص. أَدَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَأْدِيبٌ-تَأْدِيبٌ [أ د ب] (مص. أَدَّبَ). ""كَانَ لابُدَّ مِنْ تَأْدِيبِهِ عَلَى إِسَاءتِهِ"" : مِنْ مُعَاقَبَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17215, 'إِدْبَارٌ', 'إدبار', 'مصدر', 'دبر', 'ءدبار', 'إدبر', 'مص. أدْبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِدْبَارٌ-إِدْبَارٌ [د ب ر] (مص. أدْبَرَ). 1. ""أسْرَعَ إلى الإِدْبَارِ"": إِلَى الهُروبِ وَالْمُضِيِّ بَعِيداً. 2. ""إدْبارُ الرِّيَاحِ"": تَحَوُّلُ اتِّجَاهِهَا، ضِدَّ إقْبالِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17216, 'اِدِّثَارٌ', 'ادثار', 'مصدر', 'دثر', 'ادثار', 'دثر', 'مص. اِدَّثَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِدِّثَارٌ-اِدِّثَارٌ [د ث ر] (مص. اِدَّثَرَ). ""لَمْ يَكُنْ أَمَامَهُ إلاَّ الادِّثَارُ بِخِرَقٍ بالِيَةٍ"" : التَّلَفُّفُ بِهَا والاحْتِمَاءُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17217, 'إِدْجَاءٌ', 'إدجاء', 'مصدر', 'دجو', 'ءدجاء', 'إدج', 'مص. أَدْجى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِدْجَاءٌ-إِدْجَاءٌ [د ج و] (مص. أَدْجى). ""إِدْجَاءُ اللَّيْلِ"" : إظْلاَمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17218, 'إدْحَاضٌ', 'إدحاض', 'مصدر', 'دحض', 'ءدحاض', 'إدحض', 'مص. أَدْحَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إدْحَاضٌ-إدْحَاضٌ [د ح ض] (مص. أَدْحَضَ). ""إِدْحَاضُ الحُجَّةِ"": إِبْطَالُهَا، دَحْضُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17219, 'إِدْمَانٌ', 'إدمان', 'مصدر', 'دمن', 'ءدمان', 'إدمن', 'مص. أَدْمَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِدْمَانٌ-إِدْمَانٌ [د م ن] (مص. أَدْمَنَ). ""مَنَعَهُ مِنْ إِدْمانِ الْمُخَدِّرَاتِ"" : مِنَ الإِفْرَاطِ فِي تَنَاوُلِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17220, 'اِدِّخارٌ', 'ادخار', 'مصدر', 'دخل', 'ادخار', 'دخر', 'مص. اِدَّخَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِدِّخارٌ-اِدِّخارٌ [د خ ل] (مص. اِدَّخَرَ). 1. ""لاَ يُفَكِّرُ إلاَّ في ادِّخَارِ ثَرْوَتِهِ"" : تَجْمِيعِهَا لِوَقْتِ الحاجَةِ. 2.""صُنْدُوقُ الادِّخَارِ"": صُنْدُوقُ الاسْتِثْمَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17221, 'إدْخَالٌ', 'إدخال', 'مصدر', 'دخل', 'ءدخال', 'إدخل', 'مص. أَدْخَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إدْخَالٌ-إدْخَالٌ [د خ ل] (مص. أَدْخَلَ). 1. ""تمَّ إِدْخَالُهُ بِالقُوَّةِ إلى الغُرْفَةِ"" : جَعْلُهُ بِدَاخِلِهَا. 2.""قَرَّرَ إِدْخَالَ تَعْدِيلاتٍ على الْمَشْرُوعِ"" : إحْدَاثَ تَعْدِيلاَتٍ. 3.""إدْخَالُ السُّرورِ إلى النَّفْسِ"": جَعْلُها مَسْرُورَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17222, 'إدْرَارٌ', 'إدرار', 'مصدر', 'درر', 'ءدرار', 'إدرر', 'مص. أَدَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إدْرَارٌ-إدْرَارٌ [د ر ر] (مص. أَدَرَّ). 1. ""إدْرَارُ الرِّزْقِ"": إِكْثَارُهُ. 2.""إدْرَارُ البَقَرَةِ"" : كَثْرَةُ لَبَنِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17223, 'إِدْرَاجٌ', 'إدراج', 'مصدر', 'درج', 'ءدراج', 'إدرج', 'مص. أَدْرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِدْرَاجٌ-إِدْرَاجٌ [د ر ج] (مص. أَدْرَجَ). 1.""إِدْرَاجُ أَبْيَاتٍ شِعْرِيَّةٍ في النَّصِّ"" : تَضْمِينُهَا، إِدْخَالُهَا فِيهِ. 2. ""تَمَّ إِدْرَاجُ قَضايا جَديدةٍ إلى الْمِلَفّ"" : إضافَتُهَا. ""أَدْرَجَ قَضِيَّةً جَديدَةً إلى جَدْوَلِ الأعْمَالِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17224, 'إِدْرَاكٌ', 'إدراك', 'مصدر', 'درك', 'ءدراك', 'إدرك', 'مص. أَدْرَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِدْرَاكٌ-إِدْرَاكٌ [د ر ك] (مص. أَدْرَكَ). ""اِسْتَطاعَ إِدْرَاكَ خَبَايَا الأُمُورِ"": فَهْمَهَا وَتَمْيِيزَ دَلاَلَتِهَا. ¨ ""مِنَ الصَّعْبِ إِدْرَاكُ هَذَا الأَمْرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17225, 'اِدِّعَاءٌ', 'ادعاء', 'مصدر', 'دعو', 'ادعاء', 'دع', 'مص. اِدَّعَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِدِّعَاءٌ-اِدِّعَاءٌ [د ع و] (مص. اِدَّعَى). ""هُوَ كَثِيرُ الادِّعَاءِ"": كَثِيرُ الزَّعْمِ وَالافْتِخَارِ بِما لَيْسَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17226, 'إِدْفَاءٌ', 'إدفاء', 'مصدر', 'دفأ', 'ءدفاء', 'إدف', 'مص. أَدْفَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِدْفَاءٌ-إِدْفَاءٌ [د ف أ] (مص. أَدْفَأَ). ""إِدْفَاءُ الرَّجُلِ"" : إِلْبَاسُهُ ما يُدْفِئُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17227, 'إِدْلاَءٌ', 'إدلاء', 'مصدر', 'دلو', 'ءدلاء', 'إدل', 'مص. أَدْلَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِدْلاَءٌ-إِدْلاَءٌ [د ل و] (مص. أَدْلَى). 1.""إِدْلاَءُ الدَّلْوِ فِي البِئْرِ"": إِنْزَالُهُ. 2. ""قَرَّرَ الإِدْلاَءَ بِكُلِّ حُجَجِهِ"" : تَقْدِيمَهَا والاحْتِجَاجَ بِهَا. ""الإدْلاَءُ بالشَّهَادَةِ"". 3. الإدْلاَءُ بالرَّأْيِ"" : التَّعْبِيرُ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17228, 'إِدْمَاجٌ', 'إدماج', 'مصدر', 'دمج', 'ءدماج', 'إدمج', 'مص. أَدْمَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِدْمَاجٌ-إِدْمَاجٌ [د م ج] (مص. أَدْمَجَ). 1. ""إِدْمَاجُ الطَّعَامِ في الثَّوْبِ"": لَفُّهُ. 2. ""إِدْمَاجُ اسْمٍ جَدِيدٍ في اللاَّئِحَةِ"" : إِدْرَاجُهُ، إِدْخَالُهُ. 3. ""إِدْمَاجُ عُضْوَيْنِ"" (علم الأَحياءِ) : إِلْصَاقُ أَحَدِهِمَا بالآخَرِ لِيَنْمُوَا مَعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17229, 'إذْكَاءٌ', 'إذكاء', 'مصدر', 'ذكو', 'ءذكاء', 'إذك', 'مص. أَذْكَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إذْكَاءٌ-إذْكَاءٌ [ذ ك و] (مص. أَذْكَى). ""إِذكَاءُ النِّيرَانِ"" : إِشْعَالُهَا، إِيقَادُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17230, 'إِدْمَاءٌ', 'إدماء', 'مصدر', 'دمي', 'ءدماء', 'إدم', 'مص. أَدْمَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِدْمَاءٌ-إِدْمَاءٌ [د م ي] (مص. أَدْمَى). 1. ""إِدْمَاءُ الجُرْحِ"" : سَيَلاَنُ دَمِهِ. 2. ""إِدْمَاءُ القَلْبِ بالأحْزَانِ"" : اِشْتِدَادُ وَطأَتِهِ بالأحْزَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17231, 'إِدْناءٌ', 'إدناء', 'مصدر', 'دنو', 'ءدناء', 'إدن', 'مص. أَدْنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِدْناءٌ-إِدْناءٌ [د ن و] (مص. أَدْنَى). 1.""إِدْنَاءُ الصَّحْنِ"" : تَقْرِيبُهُ. 2. ""إِدْنَاءُ السَّتَائِرِ"" : إرْخَاؤُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17232, 'أَدَاءٌ', 'أداء', 'مصدر', 'أدي', 'ءداء', 'د', 'مص. أدَّى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"أَدَاءٌ-أَدَاءٌ [أ د ي] (مص. أدَّى). 1.""قَامَ بأداء وَاجِبِهِ"" : بِإِنْجَازِهِ، بِإِكْمَالِهِ. 2.""كان أَدَاؤُهُ للنَّصِّ سَلِيماً"" : أسْلُوبُ تَعْبيرِهِ وَطَريقَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17233, 'إذَاعَةٌ', 'إذاعة', 'مصدر', 'ذيع', 'ءذاعة', 'إذعة', 'مص. أَذَاعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"إذَاعَةٌ-إذَاعَةٌ [ذ ي ع] (مص. أَذَاعَ). 1. ""تَوَلَّى إِذَاعَةَ الأَخْبَارِ الْمَحَلِّيَّةِ"": إِشَاعَتَهَا، نَشْرَهَا. 2.""تُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17234, 'إذَاقَةٌ', 'إذاقة', 'مصدر', 'ذوق', 'ءذاقة', 'إذقة', 'مص. أذَاقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إذَاقَةٌ-إذَاقَةٌ [ذ و ق] (مص. أذَاقَ). 1.""إِذَاقَةُ الطَّعَامِ"" : ذَوْقُهُ. 2. ""إذَاقَة الأَمَرَّيْنِ"" : اخْتِبَار ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17235, 'إذْبَالٌ', 'إذبال', 'مصدر', 'ذبل', 'ءذبال', 'إذبل', 'مص. أَذْبَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إذْبَالٌ-إذْبَالٌ [ذ ب ل] (مص. أَذْبَلَ). ""وَجَدَ النَّبَاتَ في إِذْبَالٍ"": في ذُبولٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17236, 'اِذِّخَارٌ', 'اذخار', 'مصدر', 'ذخر', 'اذخار', 'ذخر', 'مص. اِذَّخَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِذِّخَارٌ-اِذِّخَارٌ [ذ خ ر] (مص. اِذَّخَرَ). ""اِذِّخَارُ المالِ"" : تَجمِيعُهُ لِوَقْتِ الحاجَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17237, 'إِذْعَانٌ', 'إذعان', 'مصدر', 'ذعن', 'ءذعان', 'إذعن', 'مص. أَذْعَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِذْعَانٌ-إِذْعَانٌ [ذ ع ن] . (مص. أَذْعَنَ). 1.""لَمْ يَكُنْ أَمَامَهُ إِلاَّ الإذْعانُ لِحُكْمِ الْمَحْكَمَةِ"" : الخُضُوعُ والانْقِيَادُ... 2.""الإذْعَانُ بِالحَقِّ"" : الإِقْرَارُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17238, 'اِذِّكَارٌ', 'اذكار', 'مصدر', 'ذكر', 'اذكار', 'ذكر', 'مص. اِذَّكَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِذِّكَارٌ-اِذِّكَارٌ [ذ ك ر] (مص. اِذَّكَرَ). ""حَاوَلَ اذِّكَارَ مَا حَدَثَ"": ذِكْرَهُ وَاسْتِحْضَارَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17239, 'مُؤَارَبَةٌ', 'مؤاربة', 'مصدر', 'ورب', 'مءاربة', 'مربة', 'مص. آرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُؤَارَبَةٌ-مُؤَارَبَةٌ [و ر ب] (مص. آرَبَ). ""كَانَ حَدِيثُهُ وَاضِحاً دونَ مُؤَارَبَةٍ"" : دونَ مُخَاتَلَةٍ أَوْ مُخَادَعَةٍ، مُوارَبَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17240, 'إِذْلاَلٌ', 'إذلال', 'مصدر', 'ذلل', 'ءذلال', 'إذلل', 'مص. أَذَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِذْلاَلٌ-إِذْلاَلٌ [ذ ل ل] (مص. أَذَلَّ). ""تَعَرَّضَ لِلإِذْلاَلِ وَالْمَهانَةِ"": الإهَانَةُ، التَّحْقِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17241, 'أَذَانٌ', 'أذان', 'مصدر', 'أذن', 'ءذان', 'ذن', 'مص. أَذِنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"أَذَانٌ-أَذَانٌ [أ ذ ن] (مص. أَذِنَ). ""اِسْتَيْقَظَ بَعْدَ سَمَاعِ أَذَانِ الفَجْرِ"": الإعْلامُ بِوَقْتِ الصَّلاَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17242, 'إِذْنٌ', 'إذن', 'مصدر', 'أذن', 'ءذن', 'إذن', 'مص. أَذِنَ', '', '', 'مفرد', 'DnN', '', '', '"أُذُونٌ(المعجمالوسيط)"', '', 'R', '', '', '', '', '', '', '"إِذْنٌ-إِذْنٌ [أ ذ ن] (مص. أَذِنَ). 1.""كَانَ ذَلِكَ الأَمْرُ بِإِذْنِهِ"": بِعِلْمِهِ. 2.""طَلَبَ إِذْناً"" : إِجَازَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17243, 'أُذُونٌ', 'أذون', 'مصدر', '', 'ءذون', 'ذن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17244, 'إِذْهَالٌ', 'إذهال', 'مصدر', 'ذهل', 'ءذهال', 'إذهل', 'مص. أَذْهَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِذْهَالٌ-إِذْهَالٌ [ذ هـ ل] (مص. أَذْهَلَ). ""سَعَى إلى إِذْهَالِ الحَاضِرِينَ"": تَحْيِيرُهُم، إِدْهاشُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17245, 'أَذىً', 'أذى', 'مصدر', 'أذي', 'ءذى', 'ذ', 'مص. أَذِيَ', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"أَذىً-أَذىً [أ ذ ي] (مص. أَذِيَ). ""تَعَرَّضَ لِلأذَى"" : تَعَرَّضَ للضَّرَرِ. ""لَحِقَهُ مِنَ الأَذَى الشَّيْءُ الكَثِيرُ"" لاَ يَسْلَمُ الشَّرَفُ الرَّفِيعُ مِنَ الأَذَى*حَتَّى يُرَاقَ عَلى جَـوَانِبِهِ الـدَّمُ (المتنبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17246, 'إِرَاحَةٌ', 'إراحة', 'مصدر', 'روح', 'ءراحة', 'إرحة', 'مص. أَرَاحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرَاحَةٌ-إِرَاحَةٌ [ر و ح] (مص. أَرَاحَ). 1. ""يَبْحَثُ عَنْ إِرَاحَةِ نَفْسِهِ"": جَعْلُهَا تَسْتَرِيحُ، إِدْخَالُ الرَّاحَةِ عَلَيْهَا. 2. ""إِرَاحَةُ اللَّحْمِ"" : نتانَتُهَا، فَسَادُ رَائِحَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17247, 'إِرَادَةٌ', 'إرادة', 'مصدر', 'رود', 'ءرادة', 'إردة', 'مص. أَرَادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرَادَةٌ-إِرَادَةٌ [ر و د] (مص. أَرَادَ). 1. ""لَهُ إِرَادَةٌ قَوِيَّةٌ عَلَى مُوَاجَهَةِ الصِّعَابِ"" : عَزْمٌ، عَزِيمَةٌ، مَشِيئَةٌ. 2.""لاَيَقُومُ بِعَمَلٍ إِلاَّ حَسَبَ إِرَادَتِهِ"" : كَمَا يَشَاءُ، حَسَبَ مَشِيئَتِهِ وَرَغْبَتِهِ. ""إِرَادَةُ الشَّعْبِ هِيَ العُلْيَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17248, 'إِرَاقَةٌ', 'إراقة', 'مصدر', 'ريق', 'ءراقة', 'إرقة', 'مص. أراق', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرَاقَةٌ-إِرَاقَةٌ [ر ي ق] (مص. أراق). 1. ""إِرَاقةُ الماءِ"": صَبُّهُ 2. ""إِرَاقَةُ ماءِ الوَجْهِ"": إِذْلالُهُ. 3. ""إِرَاقَةُ الدِّماءِ"". سَفْكُهَا..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17249, 'اِرْتِحَالٌ', 'ارتحال', 'مصدر', 'رحل', 'ارتحال', 'رتحل', 'مص. ارْتَحَل', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِرْتِحَالٌ-اِرْتِحَالٌ [ر ح ل] (مص. ارْتَحَل). 1.""اِرْتِحَالُ القَبِيلَةِ"": رَحِيلُهَا بَعِيداً، هِجْرَتُهَا. 2. ""أَعْيَاهُ الارْتِحَالُ مِن مَكانٍ إِلَى آخَرَ"": الانْتِقَالُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17250, 'إِرْبَاكٌ', 'إرباك', 'مصدر', 'ربك', 'ءرباك', 'إربك', 'مص. أَرْبَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْبَاكٌ-إِرْبَاكٌ [ر ب ك] (مص. أَرْبَكَ). ""لَمْ يَكُنْ يَقْصِدُ إِرْبَاكَ تَفْكِيرِهِ"" : إِيقَاعَهُ في الحَيْرَةِ والاضْطِرَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17251, 'اِرْتِيَاحٌ', 'ارتياح', 'مصدر', 'روح', 'ارتياح', 'رتح', 'مص. اِرْتَاحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِيَاحٌ-اِرْتِيَاحٌ [ر و ح] (مص. اِرْتَاحَ). ""شَعَرَ بِارْتِيَاحِ النَّفْسِ"": بِسُرُورٍ وَنَشَاطٍ. ""تَنَهَّدْتُ مِنَ الأعْمَاقِ ارْتِيَاحاً"". (نجيب محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17252, 'اِرْتِيَادٌ', 'ارتياد', 'مصدر', 'رود', 'ارتياد', 'رتد', 'مص. اِرْتَادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِيَادٌ-اِرْتِيَادٌ [ر و د] (مص. اِرْتَادَ). 1. ""اِرْتِيَادُ الشَّاطِئ"": قَصْدُهُ أو التَّرَدُّدُ عَلَيْهِ. 2. ""اِرْتِيَادُ الْمَجَاهِلِ"" : طَلَبُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17253, 'اِرْتِيَاعٌ', 'ارتياع', 'مصدر', 'روع', 'ارتياع', 'رتع', 'مص. اِرتاع', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِيَاعٌ-اِرْتِيَاعٌ [ر و ع] (مص. اِرتاع). ""كانَ ارْتِيَاعُهُ شَدِيداً"": فَزَعُهُ، رَوْعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17254, 'اِرْتِبَاطٌ', 'ارتباط', 'مصدر', 'ربط', 'ارتباط', 'رتبط', 'مص. اِرْتَبَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِبَاطٌ-اِرْتِبَاطٌ [ر ب ط] (مص. اِرْتَبَطَ). ""بَيْنَهُمَا ارْتِبَاطٌ وَثِيقٌ"": اِتِّصَالٌ وَتَلاَزُمٌ وَتَعَلُّقٌ. ""دَخَلُوا مَرْحَلَةَ فَكِّ الارْتِبَاطِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17255, 'اِرْتِبَاكٌ', 'ارتباك', 'مصدر', 'ربك', 'ارتباك', 'رتبك', 'مص. اِرْتَبَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِبَاكٌ-اِرْتِبَاكٌ [ر ب ك] (مص. اِرْتَبَكَ). 1. ""حَصَلَ ارْتِبَاكٌ فِي أُمُورِهِ"" : اِخْتِلاَطٌ وَتَشَوُّشٌ. 2. ""أَحَسَّ بِارْتِبَاكٍ"" : بِاضْطِرَابٍ. ""اِهْتَزَّتِ الأَرْضُ، فَحَصَلَ اِرْتِبَاكٌ فِي الْمَدِينَةِ"". 3.""الاِرْتِبَاكُ فِي الكَلاَمِ"" : التَّلَعْثُمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17256, 'اِرْتِجَاجٌ', 'ارتجاج', 'مصدر', 'رجج', 'ارتجاج', 'رتجج', 'مص. اِرْتَجَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِجَاجٌ-اِرْتِجَاجٌ [ر ج ج] (مص. اِرْتَجَّ). 1. ""اِرْتِجَاجُ البَحْرِ"": اِضْطِرَابُ أَمْوَاجِهِ. 2. اِرْتِجَاجُ جُدْرَانِ البَيْتِ"" : اِهْتِزَازُهَا. 3. ""اِعْتَرَاهُ ارْتِجَاجٌ أَثْنَاءَ حَدِيثِهِ"" : اِلْتِبَاسُ الكَلاَمِ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17257, 'اِرْتِجَافٌ', 'ارتجاف', 'مصدر', 'رجف', 'ارتجاف', 'رتجف', 'مص. اِرْتَجَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِجَافٌ-اِرْتِجَافٌ [ر ج ف] (مص. اِرْتَجَفَ). ""يَشْعُرُ بِارْتِجَافٍ شَدِيدٍ"" : بِارْتِعَادٍ وَاضْطِرَابٍ شَدِيدَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17258, 'اِرْتِجَالٌ', 'ارتجال', 'مصدر', 'رجل', 'ارتجال', 'رتجل', 'مص. اِرْتَجَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِرْتِجَالٌ-اِرْتِجَالٌ [ر ج ل] (مص. اِرْتَجَلَ). 1. ""قَامَ بِارْتِجَالِ خُطْبَةٍ"": تَحَدَّثَ شَفَوِيّاً مِنَ الذَّاكِرَةِ دُونَ تَحْضِيرٍ. 2. ""مَا هَذَا الارْتِجَالُ"" : أَيْ مَا هذِهِ الفَوْضَى فِي العَمَلِ بِلاَ اسْتِعْدَادٍ وَلاَ تَحْضِيرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17259, 'اِرْتِطَامٌ', 'ارتطام', 'مصدر', 'رطم', 'ارتطام', 'رتطم', 'مص. اِرْتَطَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِطَامٌ-اِرْتِطَامٌ [ر ط م] (مص. اِرْتَطَمَ). 1. ""كَانَ العَيَاءُ والتَّعَبُ سَبَباً فِي اِرْتِطامِهِ فِي الوَحَلِ"" : سُقُوطِهِ، تَهَالُكِهِ. 2.""أَثَارَ انْتِبَاهَهُ ارْتِطَامُ الأثَاثِ"" : تَرَاكُمُهُ، تَكَدُّسُهُ. 3. ""أَدَّى بِهِ الفَقْرُ إِلَى الارْتِطَامِ بِالمصَاعِبِ"" : الاصْطِدَامِ وَمُوَاجَهَةِ الْمَصَاعِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17260, 'اِرْتِخَاءٌ', 'ارتخاء', 'مصدر', 'رخي', 'ارتخاء', 'رتخ', 'مص. اِرْتَخَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِرْتِخَاءٌ-اِرْتِخَاءٌ [ر خ ي] (مص. اِرْتَخَى). 1. ""شَعَرَ بارْتِخاءِ عَضَلاَتِهِ"": بِوَهَنٍ وَضُعْفٍ وَفُتُورٍ. 2. ""اِرْتِخَاءُ الحَبْلِ"" : أَيْ صَيْرُهُ لَيِّناً غَيْرَ مَشْدُودٍ، رَخْواً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17261, 'اِرْتِدَادٌ', 'ارتداد', 'مصدر', 'ردد', 'ارتداد', 'رتدد', 'مص. اِرْتَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِدَادٌ-اِرْتِدَادٌ [ر د د] (مص. اِرْتَدَّ). 1. ""الارْتِدَادُ إِلَى الوَرَاءِ"": التَّقَهْقُرُ، التَّرَاجُعُ. 2. ""الارْتِدَادُ عَنِ الدِّينِ"" : التَّخَلِّي والرُّجُوعُ عَنْهُ. 3. ""اِرْتِدَادُ الْمَوْجِ"" : تَرَاجعُ حَرَكَةِ البَحْرِ عِنْدَ انْكِسَارِهَا عَلَى طُولِ الشَّاطِئ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17262, 'اِرْتِدَاءٌ', 'ارتداء', 'مصدر', 'ردي', 'ارتداء', 'رتد', 'مص. اِرْتَدَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِرْتِدَاءٌ-اِرْتِدَاءٌ [ر د ي] (مص. اِرْتَدَى). ""لاَ يُحِبُّ ارْتِدَاءَ ثَوْبٍ لاَ يُنَاسِبُهُ"" : لِبْسَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17263, 'اِرْتِزَاقٌ', 'ارتزاق', 'مصدر', 'رزق', 'ارتزاق', 'رتزق', 'مص. اِرْتَزَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِزَاقٌ-اِرْتِزَاقٌ [ر ز ق] (مص. اِرْتَزَقَ). ""يَعْمَلُ لَيْلَ نَهارَ لِلارْتِزَاقِ لأَبْنَائِهِ"" : لِلْحُصُولِ عَلَى الرِّزْقِ أَوْ لِلْمُشَارَكَةِ فِي جَيْشٍ أَجْنَبِيٍّ، لِلْحُصُولِ عَلَى مُكافَآتٍ مَالِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17264, 'اِرْتِسَامٌ', 'ارتسام', 'مصدر', 'رسم', 'ارتسام', 'رتسم', 'مص. اِرْتَسَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِرْتَسَمَ). 1.""لاَحَظَ ارْتِسَامَ ابْتِسَامَةٍ عَلَى مُحَيَّاهُ"" : ظُهُورَهَا. 2.""بَدَتِ ارْتِسَامَاتُ صُوَرِ الْمَاضِي تتَرَاءى أَمَامَهُ"" : مَلامِحُ رُسُومِهَا. 3.""عَبَّرَ عَنِ ارْتِسَامَاتِهِ وخَوَاطِرِهِ"" : ما يَبْدُو لَهُ لأَوَّلِ وَهْلَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17265, 'اِرْتِشَافٌ', 'ارتشاف', 'مصدر', 'رشف', 'ارتشاف', 'رتشف', 'مص. اِرْتَشَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِشَافٌ-اِرْتِشَافٌ [ر ش ف] (مص. اِرْتَشَفَ). ""اِرْتِشَافُ القَهْوَةِ"" : مَصُّهَا بِالتَّتَابُعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17266, 'اِرْتِشَاءٌ', 'ارتشاء', 'مصدر', 'رشو', 'ارتشاء', 'رتش', 'مص. اِرْتَشَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِرْتِشَاءٌ-اِرْتِشَاءٌ [ر ش و] (مص. اِرْتَشَى). ""حَاوَلَ ارْتِشَاءَ الْمُوَظَّفِ"" : إِعْطَاءَهُ رَشْوةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17267, 'اِرْتِصَافٌ', 'ارتصاف', 'مصدر', 'رصف', 'ارتصاف', 'رتصف', 'مص. اِرْتَصَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِصَافٌ-اِرْتِصَافٌ [ر ص ف] (مص. اِرْتَصَفَ). 1. ""اِرْتِصَافُ الحِجَارَةِ"" : اِنْضِمَامُ بَعْضِهَا إِلَى بَعْضٍ بِانْتِظَامٍ. 2. ""اِرْتِصَافُ الأسْنَانِ"" : تَنَضُّدُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17268, 'اِرْتِضَاءٌ', 'ارتضاء', 'مصدر', 'رضي', 'ارتضاء', 'رتض', 'مص. اِرْتَضَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِرْتِضَاءٌ-اِرْتِضَاءٌ [ر ض ي] (مص. اِرْتَضَى). ""اِرْتِضَاءُ الْمُسَاعَدَةِ"" : الرِّضَا بِهَا، قَبُولُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17269, 'اِرْتِوَاءٌ', 'ارتواء', 'مصدر', 'روي', 'ارتواء', 'رت', 'مص. اِرْتَوَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِرْتِوَاءٌ-اِرْتِوَاءٌ [ر و ي] (مص. اِرْتَوَى). 1.""اِرْتِوَاءُ الأَرْضِ"": سَقْيُهَا بِمَا فِيهِ الكِفَايَةُ. 2. ""يَبْحَثُ عَنْ مَاءٍ لارْتِواءِ عَطَشِهِ"": لإِزَالَةِ عَطَشِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17270, 'اِرْتِعَادٌ', 'ارتعاد', 'مصدر', 'رعد', 'ارتعاد', 'رتعد', 'مص. اِرْتَعَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِعَادٌ-اِرْتِعَادٌ [ر ع د] (مص. اِرْتَعَدَ). 1.""شَعَرَ بارْتِعَادٍ فِي الجَبَلِ"" : بارْتِعَاشٍ، أَي القُشَعْرِيرَةُ التي تَسْرِي في الجِسْمِ. 2.""سَبَّبَ لَهُ الخَوْفُ ارْتِعَاداً"" : اِضْطِرَاباً، اِهْتِزَازاً يَدِبُّ فِي مَفَاصِلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17271, 'اِرْتِعَاشٌ', 'ارتعاش', 'مصدر', 'رعش', 'ارتعاش', 'رتعش', 'مص. اِرْتَعَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِرْتَعَشَ). 1.""دَبَّ الارْتِعَاشُ فِي جِسْمِهِ"" : الاِرْتِعَادُ، أَي القُشَعْرِيرَةُ التِي تَسْرِي فِي الجِسْمِ. 2. ""هَزَّهُ ارْتِعَاشُ الخَوْفِ"" : الاهْتِزَازُ والاضْطِرَابُ الَّذِي يَدِبُّ فِي الْجِسْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17272, 'اِرْتِفَاعٌ', 'ارتفاع', 'مصدر', 'رفع', 'ارتفاع', 'رتفع', 'مص. اِرْتَفَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِفَاعٌ-اِرْتِفَاعٌ [ر ف ع] (مص. اِرْتَفَعَ). 1. ""يَبْلُغُ ارْتِفَاعُ الْمَدِينَةِ عَنْ سَطْحِ البَحْرِ كَذَا"" : يَبْلُغُ عُلُوُّهَا. ""بَلَغَ ارْتِفَاعُ الصَّوْمَعَةِ كَذَا"". 2. ""عَرَفَتِ الأسْعَارُ ارْتِفَاعًا مَهُولاً"" : غَلاءُ أَثْمَانِهَا. 3. ""يَزْدَادُ صَوْتُهُ ارْتِفَاعاً"" : تَضَخُّماً، تَعَاظُماً. 4.""اِرْتِفَاعُ الْمُثَلَّثِ أَوِ الهَرَمِ أَوِ الْمَخْرُوطِ""(هن): العَمُودُ الْمُنْتَصِبُ مِنَ الرَّأْسِ إِلَى القَاعِدَةِ الْمُنْتَهِي إِلَيْهَا. 5. ""الارْتِفَاعُ فِي الأسْطُوَانَةِ والْمُتَوازِي الأَضْلاَعِ وَشِبْهُ الْمُنْحَرِفِ"" (هن) : العَمُودُ بَيْنَ القَاعِدَتَيْنِ. 6. ""اِرْتِفَاعُ نَجْمٍ"" (فك): زَاوِيَةٌ حَادِثَةٌ بَيْنَ الأفُقِ الْمُسْتَقِيمِ، الوَاصِلِ بَيْنِ الأَرْضِ وَالنُّجُومِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17273, 'اِرْتِقَابٌ', 'ارتقاب', 'مصدر', 'رقب', 'ارتقاب', 'رتقب', 'مص. اِرْتَقَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِقَابٌ-اِرْتِقَابٌ [ر ق ب] (مص. اِرْتَقَبَ). 1. اِرْتِقَابُ هِلاَلِ الشَّهْرِ"": تَرَصُّدُهُ، تَرَقُّبُهُ. 2. ""اِرْتِقَابُ زيَارَةِ الأَهْلِ"": تَحَيُّنُهَا، اِنْتِظَارُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17274, 'اِرْتِقَاءٌ', 'ارتقاء', 'مصدر', 'رقي', 'ارتقاء', 'رتق', 'مص. اِرْتَقَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِرْتِقَاءٌ-اِرْتِقَاءٌ [ر ق ي] (مص. اِرْتَقَى). 1. ""صَعُبَ عَلَيْهِ اِرْتِقَاءُ الجَبَلِ"": الصُّعُودُ إِلَيْهِ. 2. ""اِرْتِقَاءُ الْمَلِكِ للْعَرْشِ"" : اِعْتِلاؤُهُ، تَوَلِّيهِ. 3.""مَبْدَأُ النُّشُوءِ والاِرْتِقَاءِ"" : مَبْدَأُ التَّطَوُّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17275, 'اِرْتِكَابٌ', 'ارتكاب', 'مصدر', 'ركب', 'ارتكاب', 'رتكب', 'مص. اِرْتَكَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِكَابٌ-اِرْتِكَابٌ [ر ك ب] (مص. اِرْتَكَبَ). ""نَهَاهُ عَنِ ارْتِكَابِ الذُّنُوبِ"": عَنِ اقْتِرَافِهَا وَالإِتْيَانِ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17276, 'اِرْتِكَازٌ', 'ارتكاز', 'مصدر', 'ركز', 'ارتكاز', 'رتكز', 'مص. اِرْتَكَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِكَازٌ-اِرْتِكَازٌ [ر ك ز] (مص. اِرْتَكَزَ). 1. ""نُقْطَةُ الارْتِكَازِ"" (هن) : نُقْطَةُ الأَسَاسِ الثَّابِتَةُ، وَعِنْدَهَا يَحْدُثُ تَوَازُنُ قُوَّتَيِ الدَّفْعِ وَالْمُقَاومَةِ. ""مِحْوَرُ الارْتِكَازِ"". 2. ""جَوْهَرُ الارْتِكَازِ فِي الأَدْيَانِ السَّمَاوِيَّةِ هُوَ التَّوْحِيدُ"" : الأَسَاسُ وَالقَاسِمُ الْمُشْتَرَكُ بَيْنَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17277, 'اِرْتِكَاسٌ', 'ارتكاس', 'مصدر', 'ركس', 'ارتكاس', 'رتكس', 'مص. اِرْتَكَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِرْتِكَاسٌ-اِرْتِكَاسٌ [ر ك س] (مص. اِرْتَكَسَ). 1. ""اِرْتِكَاسُ الْمَرِيضِ"": اِنْتِكَاسُهُ. 2. ""ظَهَرَتْ حَالَةٌ مِنَ الارتكاس عِنْدَ الأَبْنَاءِ"": ظَاهِرَةٌ وِرَاثِيَّةٌ اِنْقَطَعَتْ زَمَناً طَوِيلاً وَعَادَتْ إِلى الظُّهُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17278, 'اِرْتِمَاءٌ', 'ارتماء', 'مصدر', 'رمي', 'ارتماء', 'رتم', 'مص. اِرْتَمَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِرْتِمَاءٌ-اِرْتِمَاءٌ [ر م ي] (مص. اِرْتَمَى). 1. ""الارْتِمَاءُ بَيْنَ الأحْضَانِ"" : إِلْقَاءُ النَّفْسِ... 2.""لاَحَظَ ارْتِمَاءَهُ عَلى قَدَمَيْهِ"" : اِنْبِطَاحَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17279, 'إرْسَاءٌ', 'إرساء', 'مصدر', 'رسو', 'ءرساء', 'إرس', 'مص. أَرْسَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إرْسَاءٌ-إرْسَاءٌ [ر س و] (مص.. أَرْسَى). ""إِرْسَاءُ السَّفِينَةِ فِي الْمَرْسَى"" : إِيقَافُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17280, 'أَرِيجٌ', 'أريج', 'مصدر', 'أرج', 'ءريج', 'رج', 'مص. أَرِجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَرَائِجُ"', '', 'R', '', '', '', '', '', '', '"(مص. أَرِجَ). ""يَعْبَقُ مِنْها الأَريجُ"": الرَّائِحَةُ الطَّيِّبَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17281, 'أَرَائِجُ', 'أرائج', 'مصدر', '', 'ءراءج', 'رج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17282, 'إِرْجَاءٌ', 'إرجاء', 'مصدر', 'رجأ', 'ءرجاء', 'إرج', 'مص. أَرْجَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِرْجَاءٌ-إِرْجَاءٌ [ر ج أ] (مص. أَرْجَأَ). ""قَرَّرَ إِرْجَاءَ عَمَلِ اليَوْمِ إِلَى الغَدِ"": تَأْجِيلَهُ، تَأْخِيرَهُ. ""اِقْتَرَحَ عَلَيَّ إِرْجَاءَ النَّظَرِ فِي الأَمْرِ"". (أ. أَمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17283, 'إِرْجَاعٌ', 'إرجاع', 'مصدر', 'رجع', 'ءرجاع', 'إرجع', 'مص. أَرْجَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْجَاعٌ-إِرْجَاعٌ [ر ج ع] (مص. أَرْجَعَ). ""إِرْجَاعُ الأمَانةِ إلى أَهْلِهَا"": إِعادَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17284, 'إِرْجَافٌ', 'إرجاف', 'مصدر', 'رجف', 'ءرجاف', 'إرجف', 'مص. أَرْجَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْجَافٌ-إِرْجَافٌ [ر ج ف] (مص. أَرْجَفَ). ""إِرْجَافُ الوَلَدِ"": إِحْدَاثُ الخَوْفِ وَالرُّعْبِ فِي نَفْسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17285, 'تَأْرِيخٌ', 'تأريخ', 'مصدر', 'أرخ', 'تءريخ', 'ترخ', 'مص. أَرَّخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْرِيخٌ-تَأْرِيخٌ [أ ر خ] (مص. أَرَّخَ). ""قَامَ بِتَأْرِيخِ الأَحْدَاثِ التَّارِيخِيَّةِ "" : تَسْجِيلُهَا وَكِتَابَةُ أَحْدَاثِهَا وَوَقَائِعِهَا وَكَيْفَ حَدَثَتْ وَأَسْبَابُهَا فِي الْمَاضِي أَوِ الحَاضِرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17286, 'إِرْخَامٌ', 'إرخام', 'مصدر', 'رخم', 'ءرخام', 'إرخم', 'مص. أَرْخَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْخَامٌ-إِرْخَامٌ [ر خ م] (مص. أَرْخَمَ). ""إِرْخَامُ الدَّجَاجَةِ عَلَى بَيْضِهَا"" : اِحْتِضانُهُ، حَضْنُهُ لِيُفَرِّخَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17287, 'إِرْخَاءٌ', 'إرخاء', 'مصدر', 'رخي', 'ءرخاء', 'إرخ', 'مص. أَرْخَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِرْخَاءٌ-إِرْخَاءٌ [ر خ ي] (مص. أَرْخَى). 1. ""إِرْخَاءُ السَّتَائِرِ"": إِسْدَالُهَا، إِنْزَالُهَا. 2. ""إِرْخَاءُ الحَبْلِ"" : إِلْقَاؤُهُ دُونَ شَدٍّ. 3.""إِرْخَاءُ اللِّحْيَةِ"" : تَرْكُهَا تَطُول."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17288, 'إِرْسَالٌ', 'إرسال', 'مصدر', 'رسل', 'ءرسال', 'إرسل', 'مص. أَرْسَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْسَالٌ-إِرْسَالٌ [ر س ل] (مص. أَرْسَلَ). 1.""لَمْ يَتَمَكَّنْ مِنْ إِرْسَالِ الرِّسَالَةِ"" : مِنْ بَعْثِهَا. 2.""مَحَطَّةُ الإِرْسَالِ"" : مَحَطَّةٌ لِنَقْلِ الصُّوَرِ أَوِ الأصْوَاتِ أَوِ الْمَوْجَاتِ إِلَى أَجْهِزَةِ الاسْتِقْبَالِ. 3.""جِهَازُ إِرْسَالٍ"": جِهَازٌ لِبَثِّ الإِشَارَاتِ وَالصُّوَرِ. ""خَطُّ الإِرْسَالِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17289, 'إِرْغَامٌ', 'إرغام', 'مصدر', 'رغم', 'ءرغام', 'إرغم', 'مص. أَرْغَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْغَامٌ-إِرْغَامٌ [ر غ م] . (مص. أَرْغَمَ) . ""حَاوَلَ إِرْغَامَهُ"": أَيْ إِخْضَاعَهُ، إِجْبَارَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17290, 'إِرْشَادٌ', 'إرشاد', 'مصدر', 'رشد', 'ءرشاد', 'إرشد', 'مص. أَرْشَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْشَادٌ-إِرْشَادٌ [ر ش د] (مص. أَرْشَدَ). ""يُلْقِي دُرُوسَ الإِرْشَادِ"": الوَعْظِ، التَّوْجِيهِ، الهِدَايَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17291, 'إِرْضاعٌ', 'إرضاع', 'مصدر', 'رضع', 'ءرضاع', 'إرضع', 'مص. أَرْضَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْضاعٌ-إِرْضاعٌ [ر ض ع] (مص. أَرْضَعَ). ""إِرْضَاعُ الطِّفْلِ"": إِعْطَاؤُهُ الثَّدْيَ لِيَمُصّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17292, 'إِرْضاءٌ', 'إرضاء', 'مصدر', 'رضي', 'ءرضاء', 'إرض', 'مص. أَرْضَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِرْضاءٌ-إِرْضاءٌ [ر ض ي] (مص. أَرْضَى). ""حَاوَلَ إِرْضاءَهُ"": جَعَلَهُ يَرْضَى، النُّزُولُ عِنْدَ رَغْبَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17293, 'إِرْطَابٌ', 'إرطاب', 'مصدر', 'رطب', 'ءرطاب', 'إرطب', 'مص. أَرْطَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْطَابٌ-إِرْطَابٌ [ر ط ب] (مص. أَرْطَبَ). 1. ""إِرْطَابُ الْبَلَحِ"": صَيْرُهُ نَاضِجاً. 2. ""إِرْطَابُ الثَّوْبِ"" : بَلُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17294, 'إِرْعَادٌ', 'إرعاد', 'مصدر', 'رعد', 'ءرعاد', 'إرعد', 'مص. أَرْعَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْعَادٌ-إِرْعَادٌ [ر ع د] (مص. أَرْعَدَ). 1.""وَجَدَهُ فِي إِرْعَادٍ"": فِي خَوْفٍ وَاضْطِرَابٍ. 2.""حَاوَلَ إِرْعَادَهُ"" : تَخْوِيفَهُ، تَهْدِيدَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17295, 'إِرْعَاشٌ', 'إرعاش', 'مصدر', 'رعش', 'ءرعاش', 'إرعش', 'مص. أَرْعَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْعَاشٌ-إِرْعَاشٌ [ر ع ش] (مص. أَرْعَشَ). ""اِسْتَبَدَّ بِهِ الإِرْعَاشُ"": الاِرْتِعَاشُ، الاِرْتِجَافُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17296, 'اِرْعِوَاءٌ', 'ارعواء', 'مصدر', 'رعو', 'ارعواء', 'رع', 'مص. اِرْعَوَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِرْعِوَاءٌ-اِرْعِوَاءٌ [ر ع و] (مص. اِرْعَوَى). ""الاِرْعِوَاءُ عَنِ الآثَامِ"": الكَفُّ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17297, 'إرْعَاءٌ', 'إرعاء', 'مصدر', 'رعي', 'ءرعاء', 'إرع', 'مص. أَرْعَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إرْعَاءٌ-إرْعَاءٌ [ر ع ي] (مص. أَرْعَى) . 1. ""إِرْعَاءُ الْمَاشيَةِ"": جَعْلُهَا تَرْعَى، تَسْرَحُ. 2.""إِرْعَاءُ السَّمْعِ"" : الاِسْتِمَاعُ بِانْتِبَاهٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17298, 'إِرْغَادٌ', 'إرغاد', 'مصدر', 'رغد', 'ءرغاد', 'إرغد', 'مص. أَرْغَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْغَادٌ-إِرْغَادٌ [ر غ د] (مص. أَرْغَدَ). ""وَجَدَ النَّاسَ فِي إِرْغَادٍ"": فِي خِصْبٍ ونَمَاءٍ، في عَيْشٍ رَغيدٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17299, 'إِرْغَاءٌ', 'إرغاء', 'مصدر', 'رغو', 'ءرغاء', 'إرغ', 'مص. أَرْغَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِرْغَاءٌ-إِرْغَاءٌ [ر غ و] (مص. أَرْغَى). 1.""إِرْغَاءُ اللَّبَنِ"" : صَيْرُ رَغْوَةٍ لَهُ. 2.""إِرْغَاءُ الرَّجُلِ"": فَوْرُهُ غَضَباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17300, 'أَرَقٌ', 'أرق', 'مصدر', 'أرق', 'ءرق', 'رق', 'مص. أَرِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أَرَقٌ-أَرَقٌ [أ ر ق] (مص. أَرِقَ). ""اِشْتَدَّ بِي الأرَقُ"" : ذَهَابُ النَّوْمِ عَنْ عَيْنِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17301, 'إِرْقَادٌ', 'إرقاد', 'مصدر', 'رقد', 'ءرقاد', 'إرقد', 'مص. أَرْقَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْقَادٌ-إِرْقَادٌ [ر ق د] (مص. أَرْقَدَ). ""إِرْقَادُ الوَلَدِ"" : جَعْلُهُ يَرْقُدُ، يَنَامُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17302, 'إِرْقَاصٌ', 'إرقاص', 'مصدر', 'رقص', 'ءرقاص', 'إرقص', 'مص. أَرْقَصَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْقَاصٌ-إِرْقَاصٌ [ر ق ص] (مص. أَرْقَصَ) . 1.""إِرْقَاصُ السَّائِرِينَ فِي سَيْرِهِمْ"" : سَيْرُهُمْ فِي ارْتِفَاعٍ وانْخِفَاضٍ. 2.""إرْقَاصُ الفَتَاةِ"" : حَمْلُهَا عَلَى الرَّقْصِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17303, 'إِرْكَابٌ', 'إركاب', 'مصدر', 'ركب', 'ءركاب', 'إركب', 'مص. أَرْكَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْكَابٌ-إِرْكَابٌ [ر ك ب] (مص. أَرْكَبَ). ""إِرْكَابُهُ الدَّرَّاجَةَ وَنَحْوَهَا"" : جَعْلُهُ يَرْكَبُهَا، يَعْتَلِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17304, 'إِرْكَاعٌ', 'إركاع', 'مصدر', 'ركع', 'ءركاع', 'إركع', 'مص. أَرْكَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْكَاعٌ-إِرْكَاعٌ [ر ك ع] (مص. أَرْكَعَ). ""إِرْكَاعُ الرَّجُلِ"" : جَعْلَهُ يَرْكَعُ ، إِخْضَاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17305, 'إِرْمَاءٌ', 'إرماء', 'مصدر', 'رمي', 'ءرماء', 'إرم', 'مص. أَرْمَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِرْمَاءٌ-إِرْمَاءٌ [ر م ي] (مص. أَرْمَى). ""إِرْمَاءُ الشَّبَكَةِ فِي البَحْرِ"" : إِلْقَاؤُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17306, 'إِرْهَابٌ', 'إرهاب', 'مصدر', 'رهب', 'ءرهاب', 'إرهب', 'مص. أَرْهَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"إِرْهَابٌ-إِرْهَابٌ [ر هـ ب] (مص. أَرْهَبَ). ""يَخَافُ مِنَ الإِرْهَابِ"": يَخَافُ مِنْ مُمَارَسَةِ العُنْفِ وَالقِيَامِ بِأَعْمَالٍ تَخْلُقُ الرُّعْبَ فِي النَّفْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17307, 'إِرْهَافٌ', 'إرهاف', 'مصدر', 'رهف', 'ءرهاف', 'إرهف', 'مص. أَرْهَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْهَافٌ-إِرْهَافٌ [ر هـ ف] (مص. أَرْهَفَ). ""إِرْهَافُ السَّمْعِ"": الإصْغَاءُ بِانْتِبَاهٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17308, 'إِرْهَاقٌ', 'إرهاق', 'مصدر', 'رهق', 'ءرهاق', 'إرهق', 'مص. أَرْهَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِرْهَاقٌ-إِرْهَاقٌ [ر هـ ق] (مص. أَرْهَقَ). ""إِرْهَاقُ النَّفْسِ"" : حَمَّلَهَا مَا لَا تُطِيقُ بِعَمَلٍ زَائِدٍ. ""زِدْتُ نَفْسِي إِرْهَاقاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17309, 'إِرْوَاءٌ', 'إرواء', 'مصدر', 'روي', 'ءرواء', 'إر', 'مص. أَرْوَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِرْوَاءٌ-إِرْوَاءٌ [ر و ي] (مص. أَرْوَى). 1.""إرْوَاءُ الغَنَمِ"" : سَقْيُهَا إِلَى أَنْ تَشْبَعَ. 2.""إِرْوَاءُ العَطَشِ الغَلِيلِ"" : إِشْبَاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17310, 'أَزِيزٌ', 'أزيز', 'مصدر', 'أزز', 'ءزيز', 'زز', 'مص. أَزَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"أَزِيزٌ-أَزِيزٌ [أ ز ز] (مص. أَزَّ). 1.""أَرْعَبَهُ أَزِيزُ الرِّيحِ"": صَفِيرُهُ. 2.""أَزِيزُ الحَشَرَاتِ"" : طَنِينُهَا. ""أَزِيزُ مَراوِحِ الصَّيْفِ الكَبيِرَةِ"" ""كَأَنَّهُ قِدْرٌ يَئِزُّ أَزِيزاً"". (م. ص. الرافعي). 3.""أَزِيزُ مُحَرِّكِ السَّيَّارَةِ"" : اِهْتِزازُهُ وَصَوْتُهُ. 4.""أَزِيزُ الرَّعْدِ"" : صَوْتُ الرَّعْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17311, 'إِزاحَةٌ', 'إزاحة', 'مصدر', 'زوح،زيح', 'ءزاحة', 'إزحة', 'مص. أَزَاحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِزاحَةٌ-إِزاحَةٌ [ز و ح، ز ي ح] (مص. أَزَاحَ). 1.""عَمِلَ عَلَى إِزَاحَتِهِ مِنْ مَكَانِهِ"" : إِبْعَادِهِ، تَنْحِيَتِهِ. 2.""رَفَضَتْ إِزَاحَةَ اللِّثَامِ عَنْ وَجْهِهَا"" : إِزَالَتَهُ. 3. ""إِزَاحَةُ السَّتَائِرِ"" : رَفْعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17312, 'إِزَاغَة', 'إزاغة', 'مصدر', 'زيغ', 'ءزاغة', 'إزغة', 'مص. أَزَاغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِزَاغَة-إِزَاغَةٌ [ز ي غ] (مص. أَزَاغَ). 1.""إِزَاغَتُهُ عَنِ الطَّرِيقِ"" : جَعْلُهُ يَنْحَرِفُ، إِبْعادُهُ. 2.""إِزَاغَةُ النَّاسِ عَنِ الصَّوَابِ"" : إِبْعَادُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17313, 'إِزَالَةٌ', 'إزالة', 'مصدر', 'زول', 'ءزالة', 'إزلة', 'مص. أَزَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِزَالَةٌ-إِزَالَةٌ [ز و ل] (مص. أَزَالَ). 1. ""إِزَالَةُ الحَوَاجِزِ"" : تَنْحِيَتُهَا. 2.""إِزَالَةُ الأوْسَاخِ عَنِ الثَّوْبِ"" : مَحْوُهَا، تَنْظِيفُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17314, 'إِزْبَادٌ', 'إزباد', 'مصدر', 'زبد', 'ءزباد', 'إزبد', 'مص. أَزْبَد', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِزْبَادٌ-إِزْبَادٌ [ز ب د] (مص. أَزْبَد). 1.""إِزْبَادُ البَحْرِ"": إِخْرَاجُهُ الرَّغْوَةَ، الزَّبَدَ. 2.""إِزْبَادُ فَمِ الخَطِيبِ"" : خُرُوجُ رَغْوَةٍ مِن فَمِهِ. 3.""إِزْبَادُ الرَّجُلِ"": اِنْفِجَارُهُ غَضَباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17315, 'اِزْدِيَادٌ', 'ازدياد', 'مصدر', 'زيد', 'ازدياد', 'زدد', 'مص. اِزْدَادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِزْدِيَادٌ-اِزْدِيَادٌ [ز ي د] (مص. اِزْدَادَ). 1.""عَدَدُ سُكَّانِ العَالَمِ فِي اِزْدِيَادٍ"": فِي تَكَاثُرٍ. 2.""تَطَلَّبَ ازْدِيَادُ الإنْتَاجِ جُهْداً وَمُثَابَرَةً"": نُمُوُّهُ، تَقَدُّمُهُ، تَوَسُّعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17316, 'اِزْدِيَانٌ', 'ازديان', 'مصدر', 'زين', 'ازديان', 'زدن', 'مص. اِزدانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِزْدِيَانٌ-اِزْدِيَانٌ [ز ي ن] (مص. اِزدانَ). ""اِزْدِيَانُ الشَّوَارِعِ بِالأضْوَاءِ"" : تَزيينُها..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17317, 'اِزْدِحَامٌ', 'ازدحام', 'مصدر', 'زحم', 'ازدحام', 'زدحم', 'مص. اِزْدَحَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِزْدِحَامٌ-اِزْدِحَامٌ [ز ح م] (مص. اِزْدَحَمَ). ""اِزْدِحَامُ السُّوقِ بِالْمَارَّةِ"" : اِمْتِلاءُ السُّوقِ بِالنَّاسِ إِلَى أَنْ ضَاقَ بِهِمْ وَصَارُوا يَتَدَافَعُونَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17318, 'اِزْدِرادٌ', 'ازدراد', 'مصدر', 'زرد', 'ازدراد', 'زدرد', 'مص. اِزْدَرَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِزْدِرادٌ-اِزْدِرادٌ [ز ر د] (مص. اِزْدَرَدَ). ""اِزْدِرَادُ اللُّقْمَةِ"" : بَلْعُهَا بِسُرْعَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17319, 'اِزْوِرَارٌ', 'ازورار', 'مصدر', 'زور', 'ازورار', 'زرر', 'مص. اِزوَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِزْوِرَارٌ-اِزْوِرَارٌ [ز و ر] (مص. اِزوَرَّ). ""اِزْوِرَارُ الشَّمْسِ"": مَيْلُهَا، اِنْحِرَافُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17320, 'اِزْدِرَاءٌ', 'ازدراء', 'مصدر', 'زري', 'ازدراء', 'زدر', 'مص. اِزْدَرَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِزْدِرَاءٌ-اِزْدِرَاءٌ [ز ر ي] (مص. اِزْدَرَى). ""لم يَعْرِفْ سَبَبَ ازْدِرَائِهِ"" : اِحْتِقَارِهِ، الاِسْتِخْفَاف بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17321, 'اِزْدِهَارٌ', 'ازدهار', 'مصدر', 'زهر', 'ازدهار', 'زدهر', 'مص. اِزْدَهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِزْدِهَارٌ-اِزْدِهَارٌ [ز هـ ر] (مص. اِزْدَهَرَ). 1.""عَرَفَتِ البِلاَدُ ازْدِهَارًا اقْتِصَادِيّاً"" : اِنْتِعَاشاً. 2.""عَرَفَتِ الفُنُونُ ازْدِهَاراً فِي عَهْدِهِ"" : تَقَدُّماً، نُمُوّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17322, 'اِزْدِهَاءٌ', 'ازدهاء', 'مصدر', 'زهو', 'ازدهاء', 'زده', 'مص. اِزْدَهَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِزْدِهَاءٌ-اِزْدِهَاءٌ [ز هـ و] (مص. اِزْدَهَى). ""بَلَغَ بِهِ الاِزْدِهَاءُ مَبْلَغًا كَبِيراً"" : التَّبَجُّحُ، الافْتِخَارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17323, 'اِزْدِوَاجٌ', 'ازدواج', 'مصدر', 'زوج', 'ازدواج', 'زدج', 'مص. اِزْدَوَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِزْدِوَاجٌ-اِزْدِوَاجٌ [ز و ج] (مص. اِزْدَوَجَ). 1.""اِزْدِوَاجُ الْمَعْنَى"": ثُنَائِيَّتُهُ، أي أنَّهُ يَتَضَمَّنُ مَعْنَيَيْنِ مُتَنَاقِضَيْنِ. 2.""الازْدِوَاجُ اللُّغَويُّ"" : التَّمَكُّنُ مِنَ لُغَتَيْنِ فِي آنٍ وَاحِدٍ فِي بَعْضِ البُلْدَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17324, 'مُؤَازَرَةٌ', 'مؤازرة', 'مصدر', 'أزر', 'مءازرة', 'مزرة', 'مص. آزَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُؤَازَرَةٌ-مُؤَازَرَةٌ [أ ز ر] (مص. آزَرَ). ""جَاءوا لِمُؤَازَرَتِهِ"" : لِمُعَاوَنَتِهِ، لِمُسَاعَدَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17325, 'أَزْرٌ', 'أزر', 'مصدر', 'أزر', 'ءزر', 'زر', 'مص. أَزَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أَزْرٌ-أَزْرٌ [أ ز ر] (مص. أَزَرَ). ""شَدَّ أَزْرَهُ"" : سَاعَدَهُ، قَوَّاهُ، عَاوَنَهُ. ""شَدَّ مِنْ أَزْرِهِ""طه آية 31 اُشْدُدْ بِهِ أَزْرِي (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17326, 'إِزْعَاجٌ', 'إزعاج', 'مصدر', 'زعج', 'ءزعاج', 'إزعج', 'مص. أَزْعَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِزْعَاجٌ-إِزْعَاجٌ [ز ع ج] (مص. أَزْعَجَ). ""لاَ تُحَاوِلْ إِزْعَاجَهُ وَقْتَ العَمَلِ"" : إِقْلاَقَهُ، مُضَايَقَتَهُ. ""دُونِ إِزْعَاجٍ مِنْ فَضْلِكَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17327, 'إِزْكَاءٌ', 'إزكاء', 'مصدر', 'زكو', 'ءزكاء', 'إزك', 'مص. أَزْكَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِزْكَاءٌ-إِزْكَاءٌ [ز ك و] (مص. أَزْكَى). ""إِزْكَاءُ الزَّرْعِ"" : نُمُوُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17328, 'إِزْهَاقٌ', 'إزهاق', 'مصدر', 'زهق', 'ءزهاق', 'إزهق', 'مص. أَزْهَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِزْهَاقٌ-إِزْهَاقٌ [ز هـ ق] (مص. أَزْهَقَ). ""إِزْهَاقُ الأَرْواحِ"": إِماتَتُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17329, 'اِسْتِئْصَالٌ', 'استئصال', 'مصدر', 'أصل', 'استءصال', 'ستصل', 'مص. اِسْتَأْصَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِئْصَالٌ-اِسْتِئْصَالٌ [أ ص ل] (مص. اِسْتَأْصَلَ). ""اِسْتِئْصَالُ شَجَرَةٍ"" : قَلْعُهَا، اِجْتِثَاثُهَا مِنْ جِذْرِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17330, 'إِسَاءةٌ', 'إساءة', 'مصدر', 'سوأ', 'ءساءة', 'إسة', 'مص. أَسَاءَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِسَاءةٌ-إِسَاءةٌ [س و أ] (مص. أَسَاءَ). 1.""بَالَغَ فِي إِسَاءتِهِ"": جَاوَزَ الحَدَّ فِي مُعامَلَتِهِ مُعَامَلَةً سَيِّئَةً. 2.""تَلَقَّى مِنْهُ إِسَاءةً بَالِغَةً"": إِهَانَةً، ضَرَراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17331, 'إِسَالَةٌ', 'إسالة', 'مصدر', 'سيل', 'ءسالة', 'إسلة', 'مص. أَسَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسَالَةٌ-إِسَالَةٌ [س ي ل] (مص. أَسَالَ). 1.""إِسَالَةُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17332, 'إِسْبَارٌ', 'إسبار', 'مصدر', 'سبر', 'ءسبار', 'إسبر', 'مص. أَسْبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْبَارٌ-إِسْبَارٌ [س ب ر] (مص. أَسْبَرَ). 1.""إِسْبَارُ بِئْرٍ"" : اِمْتِحَانُ عُمْقِهِ، غَوْرِهِ. 2.""إِسْبَارُ مَسْأَلَةٍ"" : تَجْرِيبُهَا، اِخْتِبَارُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17333, 'إِسْبَاغٌ', 'إسباغ', 'مصدر', 'سبغ', 'ءسباغ', 'إسبغ', 'مص. أَسْبَغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْبَاغٌ-إِسْبَاغٌ [س ب غ] (مص. أَسْبَغَ). 1.""إِسْبَاغُ النِّعَمِ عَلَى العِبَادِ مِنْ فَضْلِ اللَّهِ"" : غَمْرُهُمْ بِهَا، إِتْمَامُهَا عَلَيْهِمْ. 2."""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17334, 'اِسْتِياءٌ', 'استياء', 'مصدر', 'سوأ', 'استياء', 'ست', 'مص. اِسْتَاءَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِياءٌ-اِسْتِياءٌ [س و أ] (مص. اِسْتَاءَ). ""عَمَّ الاسْتِياءُ بَعْدَ الإعْلانِ عَنِ النَّتائِجِ"" : عَمَّ القَلَقُ وَالنَّدَمُ وَعَدَمُ الرِّضى. ""كانَ الاسْتِياءُ بادِياً على وُجوهِهِمْ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17335, 'اِسْتِئْثَارٌ', 'استئثار', 'مصدر', 'أثر', 'استءثار', 'ستثر', 'مص. اِسْتَأْثَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِئْثَارٌ-اِسْتِئْثَارٌ [أ ث ر] (مص. اِسْتَأْثَرَ). ""الاِسْتِئْثَارُ بِالخَيْرَاتِ نَاتِجٌ عَنِ اخْتِلالٍ في النِّظَامِ"" : الاسْتِحْوَاذُ عَلَى الخَيْرَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17336, 'اِسْتِئْجَارٌ', 'استئجار', 'مصدر', 'أجر', 'استءجار', 'ستجر', 'مص. اِسْتَأْجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِئْجَارٌ-اِسْتِئْجَارٌ [أ ج ر] (مص. اِسْتَأْجَرَ). ""اِسْتِئْجَارُ بَيْتٍ"": اِكْتِراؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17337, 'اِسْتِئْذَان', 'استئذان', 'مصدر', 'أذن', 'استءذان', 'ستذن', 'مص. اِسْتَأْذَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِئْذَان-اِسْتِئْذَانٌ [أ ذ ن] (مص. اِسْتَأْذَنَ). ""طَلَبَ الاِسْتِئْذَانَ قَبْلَ دُخُولِ مَكْتَبِ الرَّئِيسِ"" : طَلَبَ الإِذْنَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17338, 'اِسْتِئْسادٌ', 'استئساد', 'مصدر', 'أسد', 'استءساد', 'ستسد', 'مص. اِسْتَأْسَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِئْسادٌ-اِسْتِئْسادٌ [أ س د] (مص. اِسْتَأْسَدَ). ""اِسْتِئْسادُ الوَلَدِ"": صَيْرُهُ كَالأَسَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17339, 'اِسْتِبْشَارٌ', 'استبشار', 'مصدر', 'بشر', 'استبشار', 'ستبشر', 'مص. اِسْتَبْشَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِبْشَارٌ-اِسْتِبْشَارٌ [ب ش ر] (مص. اِسْتَبْشَرَ). ""زَادَنِي كَلاَمُهَا ثِقَةً بِنَفْسِي وَإِيمَاناً بِمَبادِئِي واسْتِبْشَارًا بِالظَّفَرِ"". (اسحق الحُسَيْنِي) : تَيَمُّنًا بِالظَّفرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17340, 'اِسْتِئْنَاسٌ', 'استئناس', 'مصدر', 'أنس', 'استءناس', 'ستنس', 'مص. اِسْتَأْنَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِئْنَاسٌ-اِسْتِئْنَاسٌ [أ ن س] (مص. اِسْتَأْنَسَ). 1.""الاِسْتِئْنَاسُ بِالأصْحَابِ"" : الأُنْسُ بِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17341, 'اِسْتِئْنَافٌ', 'استئناف', 'مصدر', 'أنف', 'استءناف', 'ستنف', 'مص. اِسْتَأْنَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِئْنَافٌ-اِسْتِئْنَافٌ [أ ن ف] (مص. اِسْتَأْنَفَ). 1.""قَرَّرَ اسْتِئْنَافَ العَمَلِ"": البَدْءَ فِي العَمَلِ مِنْ جَدِيدٍ. 2.""رُفِعَتِ القَضِيَّةُ إِلَى مَحْكَمَةِ الاِسْتِئْنَافِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17342, 'اِسْتِبَاحَةٌ', 'استباحة', 'مصدر', 'بوح', 'استباحة', 'ستبحة', 'مص. اِسْتَباحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِبَاحَةٌ-اِسْتِبَاحَةٌ [ب و ح] (مص. اِسْتَباحَ). 1.""اِسْتِبَاحَةُ دَمِهِ"": اِعْتِبَارُ دَمِهِ مُبَاحاً. 2.""اِسْتِبَاحَةُ العِرْضِ وَالْمَالِ"" : الاغْتِصَابُ وَالنَّهْبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17343, 'اِسْتِبَانَةٌ', 'استبانة', 'مصدر', 'بين', 'استبانة', 'ستبنة', 'مص. اِسْتَبَانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِبَانَةٌ-اِسْتِبَانَةٌ [ب ي ن] (مص. اِسْتَبَانَ). 1.""اِسْتِبَانَةُ الهِلاَلِ"": وُضُوحُهُ. 2.""سَلَّمَهُ اِسْتبَانَةً لِيُجِيبَ عَنِ الأَسْئِلَةِ الْمَوْضُوعَةِ بِهَا"" : اِسْتِمَارَةً، أَيْ مَجْمُوعَة مِنَ الأسْئِلَةِ حَوْلَ مَوْضُوعٍ مُعَيَّنٍ لاسْتِقْرَاءِ آرَاءِ النَّاسِ وَمَعْرِفَتِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17344, 'استبخارٌ', 'استبخار', 'مصدر', 'بخر', 'استبخار', 'ستبخر', 'مص. استبخر', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17345, 'اِسْتِبْدَادٌ', 'استبداد', 'مصدر', 'بدد', 'استبداد', 'ستبدد', 'مص. اِسْتَبَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِسْتِبْدَادٌ-اِسْتِبْدَادٌ [ب د د] (مص. اِسْتَبَدَّ). ""اِنْتَفَضَ ضِدَّ الاسْتِبْدَادِ"": أَي الظُّلْمِ، القَهْر، العُدْوَان، التَّعَسُّف. ""الاسْتِبْدَادُ أَصْلُ كُلَّ فَسَادٍ"" (ع. الكواكبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17346, 'اِسْتِبْدَالٌ', 'استبدال', 'مصدر', 'بدل', 'استبدال', 'ستبدل', 'مص. اِسْتَبْدَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِبْدَالٌ-اِسْتِبْدَالٌ [ب د ل] (مص. اِسْتَبْدَلَ). 1.""اِسْتِبْدَالُ العُقُوبَةِ"" : تَغْيِيرُهَا. 2.""اِسْتِبْدَالُ النُّقُودِ"" : تَحْوِيلُهَا، تَغْييِرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17347, 'اِسْتِبْرَاكٌ', 'استبراك', 'مصدر', 'برك', 'استبراك', 'ستبرك', 'مص. اِسْتَبْرَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِبْرَاكٌ-اِسْتِبْرَاكٌ [ب ر ك] (مص. اِسْتَبْرَكَ). ""أَرَادَ الاِسْتِبْرَاكَ بِهِ"" : التَّفَاؤُلَ بِهِ خَيْراً وَبَرَكَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17348, 'اِسْتِبْسَالٌ', 'استبسال', 'مصدر', 'بسل', 'استبسال', 'ستبسل', 'مص. اِسْتَبْسَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِبْسَالٌ-اِسْتِبْسَالٌ [ب س ل] (مص. اِسْتَبْسَلَ). ""الاِسْتِبْسَالُ فِي الْمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17349, 'اِسْتِتارٌ', 'استتار', 'مصدر', 'ستر', 'استتار', 'ستتر', 'مص. اِسْتَتَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِتارٌ-اِسْتِتارٌ [س ت ر] (مص. اِسْتَتَرَ). ""الاِسْتِتَارُ عَنِ الأَنْظَارِ"": التَّخَفِّي..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17350, 'اِسْتِبْشَاعٌ', 'استبشاع', 'مصدر', 'بشع', 'استبشاع', 'ستبشع', 'مص. اِسْتَبْشَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِبْشَاعٌ-اِسْتِبْشَاعٌ [ب ش ع] (مص. اِسْتَبْشَعَ). ""اِسْتِبْشَاعُ مَنْظَرٍ قَبيح"": وُجُودُهُ قَبيحاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17351, 'اِسْتِبْصَارٌ', 'استبصار', 'مصدر', 'بصر', 'استبصار', 'ستبصر', 'مص. اِسْتَبْصَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِبْصَارٌ-اِسْتِبْصَارٌ [ب ص ر] (مص. اِسْتَبْصَرَ). 1.""اِسْتِبْصَارُ الهِلاَلِ"": إِبْصَارُهُ بَعْدَ تَطَلُّعٍ وَتَرَقّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17352, 'اِسْتِبْطَاءٌ', 'استبطاء', 'مصدر', 'بطأ', 'استبطاء', 'ستبط', 'مص. اِسْتَبْطَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِبْطَاءٌ-اِسْتِبْطَاءٌ [ب ط أ] (مص. اِسْتَبْطَأَ). 1.""اِسْتِبْطَاءُ السَّائِرِ"": طَلَبُ الإِبْطاءِ مِنْهُ. 2.""اِسْتِبْطَاءُ عَمَلٍ"" : وُجُودُهُ بَطِيئاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17353, 'اِسْتِبْطانٌ', 'استبطان', 'مصدر', 'بطن', 'استبطان', 'ستبطن', 'مص. اِسْتَبْطَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِبْطانٌ-اِسْتِبْطانٌ [ب ط ن] (مص. اِسْتَبْطَنَ). 1.""اِسْتِبطانُ الْمَغاوِرِ"" : طَلَبُ بَوَاطِنِها ودَوَاخِلِهَا وما تَحْتَوِي عَلَيْهِ. 2.""اِسْتِبطانُ الأمْرِ"" : إِخْفَاؤُهُ في النَّفْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17354, 'اِسْتِبْعَادٌ', 'استبعاد', 'مصدر', 'بعد', 'استبعاد', 'ستبعد', 'مص. اِسْتَبْعَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِبْعَادٌ-اِسْتِبْعَادٌ [ب ع د] (مص. اِسْتَبْعَدَ). ""اِسْتِبعادُ تَرْشِيحِهِ"": إِلْغَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17355, 'اِسْتِبَاقٌ', 'استباق', 'مصدر', 'سبق', 'استباق', 'ستبق', 'مص. اِسْتَبَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِبَاقٌ-اِسْتِبَاقٌ [س ب ق] (مص. اِسْتَبَقَ). ""اِسْتِبَاقُ الأَحْدَاثِ"": تَعَجُّلُهَا قَبْلَ حُدوثِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17356, 'اِسْتِبْقَاءٌ', 'استبقاء', 'مصدر', 'بقي', 'استبقاء', 'ستبق', 'مص. اِسْتَبْقَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِبْقَاءٌ-اِسْتِبْقَاءٌ [ب ق ي] (مص. اِسْتَبْقَى). 1.""اِسْتِبْقَاءُ كَمِّيَّةٍ مِنَ الدَّقِيقِ"": تَرْكُهَا، الاِحْتِفَاظُ بِهَا. 2.""اِسْتِبْقَاءُ الضَّيْفِ"": طَلَبُ بقَائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17357, 'اِسْتِبْهَامٌ', 'استبهام', 'مصدر', 'بهم', 'استبهام', 'ستبهم', 'مص. اِسْتَبْهَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِبْهَامٌ-اِسْتِبْهَامٌ [ب هـ م] (مص. اِسْتَبْهَمَ). ""اِسْتِبْهَامُ الأُمورِ"": اِسْتِغْلاقُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17358, 'اِسْتِتْبَابٌ', 'استتباب', 'مصدر', 'تبب', 'استتباب', 'ستتبب', 'مص. اِسْتَتَبَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِتْبَابٌ-اِسْتِتْبَابٌ [ت ب ب] (مص. اِسْتَتَبَّ). ""اِسْتِتْبَابُ النِّظَامِ"": اِسْتِقْرَارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17359, 'اِسْتِحَالَةٌ', 'استحالة', 'مصدر', 'حول', 'استحالة', 'ستحلة', 'مص. اِسْتَحَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِحَالَةٌ-اِسْتِحَالَةٌ [ح و ل] (مص. اِسْتَحَالَ). 1.""اِسْتِحَالَةُ الطَّقْسِ في الْمَسَاءِ"" : تَحَوّلُهُ. 2.""اِسْتِحَالَةُ حُضُورِهِ"" : عَدَمُ إِمْكَانِ حُضُورِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17360, 'اِسْتِثْقَالٌ', 'استثقال', 'مصدر', 'ثقل', 'استثقال', 'ستثقل', 'مص. اِسْتَثْقَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِثْقَالٌ-اِسْتِثْقَالٌ [ث ق ل] (مص. اِسْتَثْقَلَ). ""اِسْتِثْقَالُ عَمَلٍ"": وُجُودُهُ ثَقِيلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17361, 'اِسْتِثْمَارٌ', 'استثمار', 'مصدر', 'ثمر', 'استثمار', 'ستثمر', 'مص. اِسْتَثْمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِسْتِثْمَارٌ-اِسْتِثْمَارٌ [ث م ر] (مص. اِسْتَثْمَرَ). ""يَرْغَبُ فِي اسْت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17362, 'اِسْتِثْنَاءٌ', 'استثناء', 'مصدر', 'ثني', 'استثناء', 'ستثن', 'مص. اِسْتَثْنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِثْنَاءٌ-اِسْتِثْنَاءٌ [ث ن ي] (مص. اِسْتَثْنَى). 1.""القَاعِدَةُ وَالاسْتِثْنَاءُ"": ""الحَالَةُ التِي تَخْرُجُ مِنَ الحُكْمِ أَوِ القَاعِدَةِ العَامَّةِ"". حَضَرَ الجَمِيعُ بِاسْتِثْنَاءِ وَاحِدٍ"" : إلاَّ وَاحِداً. ‌2.""اِسْتَدْعَى جَمِيعَ أَصْدِقائِهِ بِلاَ اسْتِثْنَاءٍ"" : دُونَ تَمْيِيزٍ. 3.""فِيمَا عَدَا بَعْض الاسْتِثْنَاءاتِ"" : فِيمَا عَدَا بَعْض الحَالاَتِ الشَّاذَّةِ عَنِ القَاعِدَةِ العاَمَّةِ. 4.""أدَوَاتُ الاسْتِثْنَاءِ هِيَ: إِلاَّ، غَيْرُ، سِوَى، عَدَا، خَلا، حَاشَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17363, 'اِسْتِجَابَةٌ', 'استجابة', 'مصدر', 'جوب', 'استجابة', 'ستجبة', 'مص. اِسْتَجَابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِجَابَةٌ-اِسْتِجَابَةٌ [ج وب] (مص. اِسْتَجَابَ). ""كانَتِ اسْتِجَابَتُهُ لِنِدَاءِ الوَطَنِ في مُسْتَوى وَعْيِهِ الوَطَنِيِّ"" : تَلْبِيَتُهُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17364, 'اِسْتِجدَاءٌ', 'استجداء', 'مصدر', 'جدو', 'استجداء', 'ستجد', 'مص. اِسْتَجْدَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِجدَاءٌ-اِسْتِجدَاءٌ [ج د و] (مص. اِسْتَجْدَى). ""يَرْفُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17365, 'اِسْتِجْلاَبٌ', 'استجلاب', 'مصدر', 'جلب', 'استجلاب', 'ستجلب', 'مص. اِسْتَجْلَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِجْلاَبٌ-اِسْتِجْلاَبٌ [ج ل ب] (مص. اِسْتَجْلَبَ). 1.""سَعَى إِلَى اسْتِجْلاَبِه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17366, 'اِسْتِجْلاَءٌ', 'استجلاء', 'مصدر', 'جلو', 'استجلاء', 'ستجل', 'مص. اِسْتَجْلَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِجْلاَءٌ-اِسْتِجْلاَءٌ [ج ل و] (مص. اِسْتَجْلَى). ""اِسْتِجْلاَءُ الأمورِ"": تَوْضِيحُهَا، تِبْيَانُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17367, 'اِسْتِجمَامٌ', 'استجمام', 'مصدر', 'جمم', 'استجمام', 'ستجمم', 'مص. اِسْتَجَمَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِجمَامٌ-اِسْتِجمَامٌ [ج م م] (مص. اِسْتَجَمَّ). ""كَانَ بِحَاجَةٍ إِلى الاِسْتِجْمَامِ"": إِلى الرَّاحَةِ مِنَ التَّعَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17368, 'اِسْتِجْوَابٌ', 'استجواب', 'مصدر', 'جوب', 'استجواب', 'ستجب', 'مص. اِسْتَجْوَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِجْوَابٌ-اِسْتِجْوَابٌ [ج و ب] (مص. اِسْتَجْوَبَ). 1.""خَضَعَ الْمُتَّهَمُ لاِسْتِجْوَابٍ عَنْ حَيَاتِهِ وَتَنَقُّلاَتِهِ"" : لاسْتِنْطَاقِهِ. 2.""كَانَ لاَبُدَّ مِن اسْتِجْوَابِهِ"" : طَرْحُ الأسْئِلَةِ لِيُجِيبَ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17369, 'اِسْتِحْمَالٌ', 'استحمال', 'مصدر', 'حمل', 'استحمال', 'ستحمل', 'مص. اِسْتَحْمَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِحْمَالٌ-اِسْتِحْمَالٌ [ح م ل] (مص. اِسْتَحْمَلَ). ""اِسْتِحْمَالُ الأَثْقالِ"": تَحَمُّلُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17370, 'اِسْتِحْدَاثٌ', 'استحداث', 'مصدر', 'حدث', 'استحداث', 'ستحدث', 'مص. اِسْتَحْدَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِحْدَاثٌ-اِسْتِحْدَاثٌ [ح د ث] (مص. اِسْتَحْدَثَ). ""اِسْتِحْدَاثُ آلةٍ جَدِيدةٍ"": خَلْقُهَا، اِبْتدَاعُهَا، اِخْتِرَاعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17371, 'اِسْتِحْسَانٌ', 'استحسان', 'مصدر', 'حسن', 'استحسان', 'ستحسن', 'مص. اِسْتَحْسَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِحْسَانٌ-اِسْتِحْسَانٌ [ح س ن] (مص. اِسْتَحْسَنَ). ""نَالَ اسْتِحْسَانَ الجَمِيعِ"" : نَالَ رِضَاهُمْ ، مُوَافَقَتَهُمْ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17372, 'اِسْتِحْصَادٌ', 'استحصاد', 'مصدر', 'حصد', 'استحصاد', 'ستحصد', 'مص. اِسْتَحْصَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِحْصَادٌ-اِسْتِحْصَادٌ [ح ص د] (مص. اِسْتَحْصَدَ). ""اِسْتِحْصَادُ الزَّرْعِ"": حَيْنُ قَطْفِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17373, 'اِسْتِحْصَالٌ', 'استحصال', 'مصدر', 'حصل', 'استحصال', 'ستحصل', 'مص. اِسْتَحْصَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِحْصَالٌ-اِسْتِحْصَالٌ [ح ص ل] (مص. اِسْتَحْصَلَ) . 1.""اِسْتِحْصَالُ النَّتَائِجِ"" : تَحْصِيلُهَا. 2.""يَمْلِكُ الفَقِيهُ مَلَكَةَ الاِسْتِحْصَالِ"" : مَلَكَةَ الاسْتِبْطَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17374, 'اِسْتِحْضَارٌ', 'استحضار', 'مصدر', 'حضر', 'استحضار', 'ستحضر', 'مص. اِسْتَحْضَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِحْضَارٌ-اِسْتِحْضَارٌ [ح ض ر] (مص. اِسْتَحْضَرَ). ""اِسْتِحْضارُ الْمَعْلُومَاتِ"" : جَعْلُهَا حَاضِرَةً فِي الذِّهْنِ. ""اِسْتِحْضارُ الذِّكْرَيَاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17375, 'اِسْتِحْقَاقٌ', 'استحقاق', 'مصدر', 'حقق', 'استحقاق', 'ستحقق', 'مص. اِسْتَحَقَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِحْقَاقٌ-اِسْتِحْقَاقٌ [ح ق ق] (مص. اِسْتَحَقَّ). 1.""نَجَحَ بِاسْتِحْقَاقٍ"" : بِجَدَارَةٍ. 2.""أَخَذَ الجَائِزَةَ الأولَى عَنِ اِسْتِحْقَاقٍ"": كانَ أَهْلاً لأِخْذِهَا، خَلِيقاً بِهَا لِكَفَاءَتِهِ. 3.""فَازَ الفَرِيقُ دُونَ اسْتِحْقَاقٍ"" : لَمْ يَكُنْ مُؤَهَّلاً وَلَوْ بِفَوْزِهِ. 4.""وَشَّحَهُ بِوِسَامِ الاِسْتِحْقَاقِ"" : وِسَامٌ يُسَلِّمُهُ رَئِيسُ الدَّوْلَةِ إِلَى شَخْصٍ تَقْدِيراً لِحُسْنِ أَعْمَالِهِ وَخَدَمَاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17376, 'اِسْتِحْكَامٌ', 'استحكام', 'مصدر', 'حكم', 'استحكام', 'ستحكم', 'مص. اِسْتَحْكَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِحْكَامٌ-اِسْتِحْكَامٌ [ح ك م] (مص. اِسْتَحْكَمَ). 1.""الاِسْتِحْكامُ فِي الأمُورِ"" : التَّمَكُّنُ مِنْهَا. 2.""اِسْتِحْكَامُ الْمَوْضُوعِ"" : مَتانَتُهُ، رُسُوخُهُ. 3.""يَعِيشُ الصُّوفِيُّ في اسْتِحْكامٍ"" : فِي عِصْمَةٍ، بَعِيداً عَنِ الأهْوَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17377, 'اِسْتِحْلاءٌ', 'استحلاء', 'مصدر', 'حلو', 'استحلاء', 'ستحل', 'مص. اِسْتِحْلاءٌ ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِحْلاءٌ-اِسْتِحْلاءٌ [ح ل و] (مص. اِسْتِحْلاءٌ) 1."" اِسْتِحْلاَءُ مَشْرُوب"": وُجُودُهُ حُلْوًا. 2.""اِسْتِحْلاَءُ الرَّاحَةِ"" : وُجُودُ حَيَاةٍ هَنِيَّةٍ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17378, 'اِسْتِحْمَامٌ', 'استحمام', 'مصدر', 'حمم', 'استحمام', 'ستحمم', 'مص. اِسْتَحَمَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِحْمَامٌ-اِسْتِحْمَامٌ [ح م م] (مص. اِسْتَحَمَّ). 1.""وَقْتُ الاِسْتِحْمَامِ"" : وَقْتُ الغَسْلِ بِالْمَاءِ. 2.""الاِسْتِحْمَامُ فِي الحَمَّامِ رَاحَةٌ"" : الدُّخُولُ إلى الحَمَّامِ للِغَسْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17379, 'اِسْتِدَامَةٌ', 'استدامة', 'مصدر', 'دوم', 'استدامة', 'ستدمة', 'مص. اِسْتَدَامَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِدَامَةٌ-اِسْتِدَامَةٌ [د و م] (مص. اِسْتَدَامَ). ""اِسْتِدَامَةُ العَيْشِ الرَّغِيدِ"": دَوَامُهُ، اِسْتِمْرَارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17380, 'اِسْتِحْوَاذٌ', 'استحواذ', 'مصدر', 'حوذ', 'استحواذ', 'ستحذ', 'مص. اِسْتَحْوَذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِحْوَاذٌ-اِسْتِحْوَاذٌ [ح و ذ] (مص. اِسْتَحْوَذَ). ""الاسْتِحْوَاذُ عَلَى أَمْلاَكِ الغَيْرِ"" : الاسْتِيلاَءُ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17381, 'اِسْتِحْيَاءٌ', 'استحياء', 'مصدر', 'حيي', 'استحياء', 'ستح', 'مص. اِسْتَحْيَا', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِحْيَاءٌ-اِسْتِحْيَاءٌ [ح ي ي] (مص. اِسْتَحْيَا). ""أَظْهَرَ اِسْتِحْياءً"": اِحْتِشَامًا، خَجَلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17382, 'اِسْتِخْبَارٌ', 'استخبار', 'مصدر', 'خبر', 'استخبار', 'ستخبر', 'مص. اِسْتَخْبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِخْبَارٌ-اِسْتِخْبَارٌ [خ ب ر] (مص. اِسْتَخْبَرَ). 1.""حَاوَلَ الاسْتِخْبارَ عَنْ أَحْوَالِهِ"" : اِلْتِمَاسَها والسؤالَ عَنْها لتعرُّفها. 2.""دَائِرَةُ الاِسْتِخْبَارَاتِ"" : دَائِرَةٌ رَسْمِيَّةٌ لِلْحُصُولِ على مَعْلُومَاتٍ تَتَعَلَّقُ بِالأشْخَاصِ أَوْ بِحَرَكاتِ العَدُوِّ وَبِكُلِّ مَا مِنْ شَأْنِهِ أَنْ يُعَرِّضَ بِالنِّظَامِ القَائِمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17383, 'اِسْتِخْدامٌ', 'استخدام', 'مصدر', 'خدم', 'استخدام', 'ستخدم', 'مص. اِسْتَخْدَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِخْدامٌ-اِسْتِخْدامٌ [خ د م] (مص. اِسْتَخْدَمَ). 1.""اِسْتِخْدامُ الْمَرْأَةِ أَوِ الرَّجُلِ"": اِتِّخَاذُهَا خَادِمَةً أَوْ خَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17384, 'اِسْتِخْرَاجٌ', 'استخراج', 'مصدر', 'خرج', 'استخراج', 'ستخرج', 'مص. اِسْتَخْرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِخْرَاجٌ-اِسْتِخْرَاجٌ [خ ر ج] (مص. اِسْتَخْرَجَ). ""اِسْتِخْرَاجُ الْمَعَادِنِ"" : إِخْراجُهَا بَعْدَ بَحْثٍ وَتَنْقِيبٍ. 2.""اِسْتِخْراج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17385, 'اِسْتِخْفَافٌ', 'استخفاف', 'مصدر', 'خفف', 'استخفاف', 'ستخفف', 'مص. اِسْتَخَفَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِخْفَافٌ-اِسْتِخْفَافٌ [خ ف ف] (مص. اِسْتَخَفَّ). 1.""الاسْتِخْفَافُ بِالأمْرِ"" : الاسْتِهَانَةُ بِهِ. 2.""مَا هَذَا الاسْتِخْفَافُ بِالنَّاسِ‌‍‍‌‌‌‍"" : الاِسْتِهْزَاءُ بِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17386, 'اِسْتِخْفَاءٌ', 'استخفاء', 'مصدر', 'خفي', 'استخفاء', 'ستخف', 'مص. اِسْتَخْفَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِخْفَاءٌ-اِسْتِخْفَاءٌ [خ ف ي] (مص. اِسْتَخْفَى). 1.""حَاوَلَ الاسْتِخْفَاءَ"" : التَّسَتُّرَ. 2.""الاِسْتِخْفاءُ عَنِ الأعْيُنِ"" : التَّوَارِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17387, 'اِسْتِخْلاَصٌ', 'استخلاص', 'مصدر', 'خلص', 'استخلاص', 'ستخلص', 'مص. اِسْتَخْلَصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِخْلاَصٌ-اِسْتِخْلاَصٌ [خ ل ص] (مص. اِسْتَخْلَصَ). 1.""اِسْتِخْلاَصُ الزُّبْدَةِ مِنَ اللَّبَنِ"" : اِنْتِقَاؤُهَا، اِسْتِنْتَاجُهَا. 2.""اِسْتِخْلاَصُ أَفْكَارِ النَّصِّ"" : اِسْتِنْتَاجُهَا. 3.""لَهُ القُدْرَةُ على اسْتِخْلاَصِ ما هُوَ جَيِّدٌ"" : لَهُ القُدْرَةُ عَلَى الاِخْتِيَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17388, 'اِسْتِدَارَةٌ', 'استدارة', 'مصدر', 'دور', 'استدارة', 'ستدرة', 'مص. اِسْتَدَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِدَارَةٌ-اِسْتِدَارَةٌ [د و ر] (مص. اِسْتَدَارَ). 1.""اِسْتِدَارَةُ البَكَرَةِ"": اِلْتِفَافُهَا عَلَى مِحْوَرِهَا. 2.""قَامَ باسْتِدَارَةٍ حَوْلَ الْمَلْعَبِ"": الدَّوَرَانُ وَالطَّوَافُ حَوْلَهُ، أَي الانْطِلاَقُ مِنْ نُقْطَةِ الرُّجُوعِ إِلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17389, 'اِسْتِرْخَاصٌ', 'استرخاص', 'مصدر', 'رخص', 'استرخاص', 'سترخص', 'مص. اِسْتَرْخَصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِرْخَاصٌ-اِسْتِرْخَاصٌ [ر خ ص] (مص. اِسْتَرْخَصَ). ""اِسْتِرْخَاصُ شَيْءٍ"" : وُجُودُهُ رَخِيصاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17390, 'اِسْتِدَانَةٌ', 'استدانة', 'مصدر', 'دين', 'استدانة', 'ستدنة', 'مص. اِسْتَدَانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِدَانَةٌ-اِسْتِدَانَةٌ [د ي ن] (مص. اِسْتَدَانَ). ""لَمْ يَبْقَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17391, 'اِسْتِدْرَاجٌ', 'استدراج', 'مصدر', 'درج', 'استدراج', 'ستدرج', 'مص. اِسْتَدْرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِدْرَاجٌ-اِسْتِدْرَاجٌ [د ر ج] (مص. اِسْتَدْرَجَ). 1.""الاِسْتِدْرَاجُ في السُّلَّمِ الإِدَارِيِّ"" : التَّرَقِّي دَرَجَةً دَرَجَةً. 2.""حَاوَلَ اِسْتِدْرَاجَهُ"": حَاوَلَ التَّحَايُلَ عَلَيْهِ لِلاعْتِرَافِ بِشَيْءٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17392, 'اِسْتِدْرَاكٌ', 'استدراك', 'مصدر', 'درك', 'استدراك', 'ستدرك', 'مص. اِسْتَدْرَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِدْرَاكٌ-اِسْتِدْرَاكٌ [د ر ك] (مص. اِسْتَدْرَكَ). 1.""هُوَ بِصَدَدِ اسْتِدْرَاكِ خَطَإِ الأمْسِ"": بِصَدَدِ تَصْحِيحِهِ. 2.""هَلْ يُمْكِنُ اسْتِدْرَاكُ كُلِّ مَا يَحْدُثُ"" : إِعَادَةُ النَّظَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17393, 'اِسْتِدْعَاءٌ', 'استدعاء', 'مصدر', 'دعو', 'استدعاء', 'ستدع', 'مص. اِسْتَدْعَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِدْعَاءٌ-اِسْتِدْعَاءٌ [د ع و] (مص. اِسْتَدْعَى). 1.""تَلَقَّى اسْتِدْعَاءً لِحُضُورِ الحَفْلَةِ"" : دَعْوَةً. 2.""وَجَّهَتْ إِلَيْهِ الْمَحْكَمَةُ اسْتِدْعَاءً رَسْمِيّاً لِلْمُثُولِ أَمَامَهَا"" : طَلَب الْمُثُولِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17394, 'اِسْتِدْفَاءٌ', 'استدفاء', 'مصدر', 'دفأ', 'استدفاء', 'ستدف', 'مص. اِسْتَدْفَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِدْفَاءٌ-اِسْتِدْفَاءٌ [د ف أ] (مص. اِسْتَدْفَأَ). ""يَبْحَثُ عَنْ مَكَانٍ لِلاِسْتِدْفَاءِ"" : لِلتَّسَخُّنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17395, 'اِسْتِدْلاَلٌ', 'استدلال', 'مصدر', 'دلل', 'استدلال', 'ستدلل', 'مص. اِسْتَدَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِدْلاَلٌ-اِسْتِدْلاَلٌ [د ل ل] (مص. اِسْتَدَلَّ). 1.""‏أَمْرٌ بِحَاجَةٍ إِلَى اسْتِدْلاَلٍ"": إلى بُرهانٍ وَاعْتِمَادِ الدَّليلِ. 2.""اِسْتِدْلاَلٌ عَقْلِيٌّ"": التَّوَصُّلُ إلى مَعْرِفِةِ الشَّيْءِ وَالبَحْثُ فِيهِ وإِعْمَالُ العَقْلِ بِالحُجَّةِ وَالدَّلِيلِ لإِثْبَاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17396, 'اِسْتِذْكَارٌ', 'استذكار', 'مصدر', 'ذكر', 'استذكار', 'ستذكر', 'مص. اِسْتَذْكَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِذْكَارٌ-اِسْتِذْكَارٌ [ذ ك ر] (مص. اِسْتَذْكَرَ). 1.""اِسْتِذْكَارُ الدُّرُوسِ"" : مُرَاجَعَتُهَا، حِفْظُهَا. 2.""اِسْتِذْكَارُ القُرْآنِ الكَرِيمِ"": حِفْظُهُ عَنْ ظَهْرِ قَلْبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17397, 'اِسْتِرَاحَةٌ', 'استراحة', 'مصدر', 'روح', 'استراحة', 'سترحة', 'مص. اِسْتَرَاحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِرَاحَةٌ-اِسْتِرَاحَةٌ [ر و ح] (مص. اِسْتَرَاحَ). ""دَقَّتْ فَتْرَةُ الاسْتِرَاحَةِ"": فَتْرَةُ الرَّاحَةِ يُسْتَرَاحُ فِيهَا لاِسْتِعَادَةِ النَّشَاطِ. ""خَرَجَ للاِسْتِرَاحَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17398, 'اِسْتِرْجَاعٌ', 'استرجاع', 'مصدر', 'رجع', 'استرجاع', 'سترجع', 'مص. اِسْتَرْجَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِرْجَاعٌ-اِسْتِرْجَاعٌ [ر ج ع] (مص. اِسْتَرْجَعَ). ""اِسْتِرْجَاعُ النَّشَاطِ"": اِسْتِعَادَتُهُ، اِسْتِرْدَادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17399, 'اِسْتِرْخَاءٌ', 'استرخاء', 'مصدر', 'رخو', 'استرخاء', 'سترخ', 'مص. اِسْتَرْخَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِرْخَاءٌ-اِسْتِرْخَاءٌ [ر خ و] (مص. اِسْتَرْخَى). ""كَانَ فِي لَحْظَةِ اِسْتِرْخَاءٍ"": فِي لَحْظَةِ تَمَدُّدٍ وَاسْتِلْقَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17400, 'اِسْتِرْدَادٌ', 'استرداد', 'مصدر', 'ردد', 'استرداد', 'ستردد', 'مص. اِسْتَرَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِرْدَادٌ-اِسْتِرْدَادٌ [ر د د] (مص. اِسْتَرَدَّ). ""اِسْتِرْدَادُ مَا ضَاعَ مِنْهُ"": اِسْتِرْجَاعُهُ، اِسْتِعَادَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17401, 'اِسْتِرْزَاقٌ', 'استرزاق', 'مصدر', 'رزق', 'استرزاق', 'سترزق', 'مص. اِسْتَرْزَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِرْزَاقٌ-اِسْتِرْزَاقٌ [ر ز ق] (مص. اِسْتَرْزَقَ). ""لَمْ يَبْقَ أَمَامَهُ إِلاَّ اسْتِرْزَاقُ رَبِّهِ"" : طَلَبُهُ الرِّزْقَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17402, 'اِسْتِرْسَالٌ', 'استرسال', 'مصدر', 'رسل', 'استرسال', 'سترسل', 'مص. اِسْتَرْسَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِرْسَالٌ-اِسْتِرْسَالٌ [ر س ل] (مص. اِسْتَرْسَلَ). ""الاِسْتِرسالُ في الحَديثِ"": الاِتِّساعُ وَالاِسْتِمرارُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17403, 'اِسْتِرْشَادٌ', 'استرشاد', 'مصدر', 'رشد', 'استرشاد', 'سترشد', 'مص. اِسْتَرْشَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِرْشَادٌ-اِسْتِرْشَادٌ [ر ش د] (مص. اِسْتَرْشَدَ). ""لَمْ يَجِدْ أَحَداً لاِسْتِرْشَادِهِ"" : لإِرْشَادِهِ وَدَلِّهِ عَلَى مُبْتَغَاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17404, 'اِسْتِرْضاءٌ', 'استرضاء', 'مصدر', 'رضي', 'استرضاء', 'سترض', 'مص. اِسْتَرْضَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِرْضاءٌ-اِسْتِرْضاءٌ [ر ض ي] (مص. اِسْتَرْضَى). ""أرَادَ اسْتِرْضاءَهُ"": طَلَبُ رِضائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17405, 'اِسْتِرْعَاءٌ', 'استرعاء', 'مصدر', 'رعي', 'استرعاء', 'سترع', 'مص. اِسْتَرْعَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِرْعَاءٌ-اِسْتِرْعَاءٌ [ر ع ي] (مص. اِسْتَرْعَى). 1.""اِسْتِرْعَاء ُ الاِنْتِبَاهِ"": شَدُّ الانْتِبَاهِ. 2.""اِسْتِرعاءُ السَّمْعِ"" : طَلَبُ الإصْغاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17406, 'اِسْتِرَاقٌ', 'استراق', 'مصدر', 'سرق', 'استراق', 'سترق', 'مص. اِسْتَرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِرَاقُ-اِسْتِرَاقُ [س ر ق] (مص. اِسْتَرَقَ). ""اِسْتِرَاقُ السَّمْعِ"": الاِسْتِمَاعُ في خَفَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17407, 'اِسْتِسَاغَةٌ', 'استساغة', 'مصدر', 'سوغ', 'استساغة', 'ستسغة', 'مص. اِسْتَسَاغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِسَاغَةٌ-اِسْتِسَاغَةٌ [س و غ] (مص. اِسْتَسَاغَ). ""لَهُ القُدْرَةُ عَلَى اسْتِسَاغَةِ ما هُوَ أَمَرُّ"" : عَلَى تَقَبُّلِ ما هُوَ أَمَرُّ، عَلَى بَلْعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17408, 'اِسْتِسْقَاءٌ', 'استسقاء', 'مصدر', 'سقي', 'استسقاء', 'ستسق', 'مص. اِسْتَسْقَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِسْقَاءٌ-اِسْتِسْقَاءٌ [س ق ي] (مص. اِسْتَسْقَى). ""عَمَّ الجَفَافُ وَخَرَجَ النَّاسُ يُقِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17409, 'اِسْتِسْلاَمٌ', 'استسلام', 'مصدر', 'سلم', 'استسلام', 'ستسلم', 'مص. اِسْتَسْلَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِسْتِسْلاَمٌ-اِسْتِسْلاَمٌ [س ل م] (مص. اِسْتَسْلَمَ). ""لَمْ يَبْقَ أَمَامَهُ إِلاَّ الاِسْتِسْلاَمُ"": إِلاَّ الخُضُوعُ، الإذْعانُ. ""الْمَوْتُ وَلاَ الاِسْتِسْلاَمُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17410, 'اِسْتِسْهالٌ', 'استسهال', 'مصدر', 'سهل', 'استسهال', 'ستسهل', 'مص. اِسْتَسْهَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِسْهالٌ-اِسْتِسْهالٌ [س هـ ل] (مص. اِسْتَسْهَلَ). ""اِسْتِسْهالُ الْمُباراةِ"": عَدُّها سَهْلَةً أَوْ وُجُودُهَا سَهْلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17411, 'اِسْتِشَارَةٌ', 'استشارة', 'مصدر', 'شور', 'استشارة', 'ستشرة', 'مص. اِسْتَشَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِسْتِشَارَةٌ-اِسْتِشَارَةٌ [ش و ر] (مص. اِسْتَشَارَ). ""لاَ يَقُومُ بِعَمَلٍ إِلاَّ بَعْدَ اِسْتِشَارَةٍ"" : أَيْ بَعْدَ أَخْذِ رَأْيِ الآخَرِينَ. ""الاِسْتِشَارَةُ القَانُونِيَّةُ"" ""الاِسْتشَارَةُ الطِّبِيَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17412, 'اِسْتِشْرَافٌ', 'استشراف', 'مصدر', 'شرف', 'استشراف', 'ستشرف', 'مص. اِسْتَشْرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِشْرَافٌ-اِسْتِشْرَافٌ [ش ر ف] (مص. اِسْتَشْرَفَ). ""صَعِدَ البُرْجَ للاِسْتِش"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17413, 'اِسْتِشْرَاقٌ', 'استشراق', 'مصدر', 'شرق', 'استشراق', 'ستشرق', 'مص. اِسْتَشْرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِشْرَاقٌ-اِسْتِشْرَاقٌ [ش ر ق] (مص. اِسْتَشْرَقَ). ""لَهُ بُحُوثٌ في الاِسْتِشْرَاقِ"" : مَادَّةُ اخْتِصَاصِ عُلَمَاءِ الغَرْبِ بِاللُّغَاتِ وَالآدَابِ وَالْمَعَارِفِ الشَّرْقِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17414, 'اِسْتِشْرَاءٌ', 'استشراء', 'مصدر', 'شري', 'استشراء', 'ستشر', 'مص. اِسْتَشْرَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِشْرَاءٌ-اِسْتِشْرَاءٌ [ش ر ي] (مص. اِسْتَشْرَى). """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17415, 'اِسْتِشْعَارٌ', 'استشعار', 'مصدر', 'شعر', 'استشعار', 'ستشعر', 'مص. اِسْتَشْعَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِشْعَارٌ-اِسْتِشْعَارٌ [ش ع ر] (مص. اِسْتَشْعَرَ). 1.""اِسْتِشْعَارُهُ بِالرُّعْبِ"": إِحْسَاسُهُ بِهِ. 2.""قَرْنَا الاِسْتِشْعَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17416, 'اِسْتِشفافٌ', 'استشفاف', 'مصدر', 'شفف', 'استشفاف', 'ستشفف', 'مص. اِسْتَشَفَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِشفافٌ-اِسْتِشفافٌ [ش ف ف] (مص. اِسْتَشَفَّ). ""اِسْتِشْفَافُ الْمَعْنَى"" : تَأَمُّلُهُ والإِمْعَانُ فِيه."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17417, 'اِسْتِشْفَاءٌ', 'استشفاء', 'مصدر', 'شفي', 'استشفاء', 'ستشف', 'مص. اِسْتَشْفَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِشْفَاءٌ-اِسْتِشْفَاءٌ [ش ف ي] (مص. اِسْتَشْفَى). ""اِحْتَاجَ اسْتِشْفَاؤُهُ إِلَى طَبِيبٍ مُخْتَصٍّ"" : مُعَالَجَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17418, 'اِسْتِشْهَادٌ', 'استشهاد', 'مصدر', 'شهد', 'استشهاد', 'ستشهد', 'مص. اِسْتَشْهَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '"جٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. اِسْتَشْهَدَ). ""ضَمَّنَ الْمَوْضُوعَ اسْتِشْهَادَاتٍ لِتَدْعِيمِ رَأْيِهِ"" : ما يَسْتَشْهِدُ بِهِ مِنْ أَقْوَالِ الآخَرِينَ وَكِتَابَاتِهِمْ. ""الاسْتِشْهَادُ بِقَوْلٍ أَوْ بِرَأْيٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17419, 'اِسْتِطابَةٌ', 'استطابة', 'مصدر', 'طيب', 'استطابة', 'ستطبة', 'مص. اِسْتَطَابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِطابَةٌ-اِسْتِطابَةٌ [ط ي ب] (مص. اِسْتَطَابَ). ""اِسْتِطَابَةُ هواءِ البِلاَدِ"": وُجودُها طَيِّبَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17420, 'اِسْتِصْحابٌ', 'استصحاب', 'مصدر', 'صحب', 'استصحاب', 'ستصحب', 'مص. اِسْتَصْحَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِصْحابٌ-اِسْتِصْحابٌ [ص ح ب] (مص. اِسْتَصْحَبَ)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17421, 'اِسْتِصْدَارٌ', 'استصدار', 'مصدر', 'صدر', 'استصدار', 'ستصدر', 'مص. اِسْتَصْدَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِصْدَارٌ-اِسْتِصْدَارٌ [ص د ر] (مص. اِسْتَصْدَرَ). ""اِسْتِصْدَارُ قَرَارٍ"": طَلَبُ إِصْدَارِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17422, 'اِسْتِصْرَاخٌ', 'استصراخ', 'مصدر', 'صرخ', 'استصراخ', 'ستصرخ', 'مص. اِسْتَصْرَخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِصْرَاخٌ-اِسْتِصْرَاخٌ [ص ر خ] (مص. اِسْتَصْرَخَ). 1.""اِسْتِصْرَاخُ صَديقٍ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17423, 'اِسْتِصْعَابٌ', 'استصعاب', 'مصدر', 'صعب', 'استصعاب', 'ستصعب', 'مص. اِسْتَصْعَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِصْعَابٌ-اِسْتِصْعَابٌ [ص ع ب] (مص. اِسْتَصْعَبَ). ""اِسْتِصْعَابُ أَمْرٍ"" : وُجُودُهُ صَعْباً، وَعْراً، شَاقّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17424, 'اِسْتِصْغَارٌ', 'استصغار', 'مصدر', 'صغر', 'استصغار', 'ستصغر', 'مص. اِسْتَصْغَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِصْغَارٌ-اِسْتِصْغَارٌ [ص غ ر] (مص. اِسْتَصْغَرَ). ""اِسْتِصْغَارُ أَمْرِهِ"" : اِحْتِقَارُهُ، الاِسْتِهَانَةُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17425, 'اِسْتِصْلاَحٌ', 'استصلاح', 'مصدر', 'صلح', 'استصلاح', 'ستصلح', 'مص. اِسْتَصْلَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِصْلاَحٌ-اِسْتِصْلاَحٌ [ص ل ح] (مص. اِسْتَصْلَحَ). ""اِسْتِصلاحُ الأرْضِ"": إِصْلاحُها، إِعدادُها لِلزِّرَاعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17426, 'اِسْتِصْوَابٌ', 'استصواب', 'مصدر', 'صوب', 'استصواب', 'ستصب', 'مص. اِسْتَصْوَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِصْوَابٌ-اِسْتِصْوَابٌ [ص و ب] (مص. اِسْتَصْوَبَ). ""اِسْتِصْوَابُ القَوْلِ"" : عَدُّهُ صَائِباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17427, 'اِسْتِضاءةٌ', 'استضاءة', 'مصدر', 'ضوأ', 'استضاءة', 'ستضة', 'مص. اِسْتَضاءَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِضاءةٌ-اِسْتِضاءةٌ [ض و أ] (مص. اِسْتَضاءَ). ""اِستِضاءَةُ البَيْتِ"": اِسْتِنارَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17428, 'اِسْتِضافَةٌ', 'استضافة', 'مصدر', 'ضيف', 'استضافة', 'ستضفة', 'مص. اِسْتَضَافَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِضافَةٌ-اِسْتِضافَةٌ [ض ي ف] (مص. اِسْتَضَافَ). ""بَقِيَ فِي اسْتِضافَتِهِ أُسْبُوعًا"" : في ضِيَافَتِهِ، في إِيوَائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17429, 'اِسْتِظْهَارٌ', 'استظهار', 'مصدر', 'ظهر', 'استظهار', 'ستظهر', 'مص. اِسْتَظْهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِظْهَارٌ-اِسْتِظْهَارٌ [ظ هـ ر] (مص. اِسْتَظْهَرَ). 1.""تَمَكَّنَ مِنِ اِسْتِظْهَارِ القُرْآنِ فِي سِنٍّ مُبَكِّرَةٍ"" : تَمَكَّنَ مِن حِفْظِهِ عَنْ ظَهْرِ قَلْبٍ. 2.""اِسْتِظْهَارُ الدُّرُوسِ"" : مُرَاجَعَتُهَا وَالتَّمَكُّنُ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17430, 'اِسْتِطارَةٌ', 'استطارة', 'مصدر', 'طير', 'استطارة', 'ستطرة', 'مص. اِسْتَطارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِطارَةٌ-اِسْتِطارَةٌ [ط ي ر] (مص. اِسْتَطارَ). 1.""اِسْتِطارَةُ الغُبا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17431, 'اِسْتِطاعَةٌ', 'استطاعة', 'مصدر', 'طوع', 'استطاعة', 'ستطعة', 'مص. اِسْتَطَاعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِطاعَةٌ-اِسْتِطاعَةٌ [ط و ع] (مص. اِسْتَطَاعَ). ""في اسْتِطاعَتِهِ القِيَامُ بِهَذَا العَمَلِ"" : في إِمْكانِهِ، أَيْ لَهُ القُدْرَةُ على القِيَامِ بِذَلِكَ"". ""في اسْتِطاعَتِهِ التَّوَقُّفُ عَنِ العَمَلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17432, 'اِسْتِطالَةٌ', 'استطالة', 'مصدر', 'طول', 'استطالة', 'ستطلة', 'مص. اِسْتَطالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِطالَةٌ-اِسْتِطالَةٌ [ط و ل] (مص. اِسْتَطالَ). 1.""اِسْتِطالَةُ مسافَةٍ"" : النَّظَرُ إِلَيْها عَلَى أَنَّها مَسافَةٌ طَويلَةٌ. ""اِسْتِطالَةُ خُطْبَةٍ"". 2.""الاِسْتِطالَةُ على الشَّرَفِ"" : مَسُّهُ بِعَيْبٍ وَالنَّيْلُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17433, 'اِسْتِطْرَابٌ', 'استطراب', 'مصدر', 'طرب', 'استطراب', 'ستطرب', 'مص. اِسْتَطْرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِطْرَابٌ-اِسْتِطْرَابٌ [ط ر ب] (مص. اِسْتَطْرَبَ). 1.""اِسْتِطْرابُ الرَّجُلِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17434, 'اِسْتِطْرادٌ', 'استطراد', 'مصدر', 'طرد', 'استطراد', 'ستطرد', 'مص. اِستَطْرَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِستَطْرَدَ). ""يُكْثِرُ مِنَ الاسْتِطْرادِ في كِتاباتِهِ"" : يَنْتَقِلُ مِنْ حَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17435, 'اِسْتِطْرَافٌ', 'استطراف', 'مصدر', 'طرف', 'استطراف', 'ستطرف', 'مص. اِسْتَطْرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِطْرَافٌ-اِسْتِطْرَافٌ [ط ر ف] (مص. اِسْتَطْرَفَ). ""اِسْتِطْرَافُ حَدِيثٍ"": اِسْتِصْلاَحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17436, 'اِسْتِطْلاعٌ', 'استطلاع', 'مصدر', 'طلع', 'استطلاع', 'ستطلع', 'مص. اِسْتَطْلَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِطْلاعٌ-اِسْتِطْلاعٌ [ط ل ع] (مص. اِسْتَطْلَعَ). 1.""أَنْجَزَ اسْتِطْلاَعاً‎ حَوْلَ سَيْرِ مَعَامِلِ الْمَدينَةِ"" : تَحْقِيقاً، أَيْ نَقْلُ مَعْلُومَاتٍ وَحَقَائِقَ عَنْهَا. 2.""تُحَلِّقُ طَاِئَرَةُ الاسْتِطْلاَعِ فَوْقَ مَكَانِ الْحَادِثِ"": طَائِرَةُ الاِسْتِكْشافِ لِمَعْرِفَةِ ما يَجْرِي. 3.""فِيهِ حُبُّ الاسْتِطْلاَعِ"" : لَهُ رَغْبَةٌ شَدِيدَةٌ في مَعْرِفَةِ كُلِّ شَيْءٍ يَدْفَعُهُ، الفُضُولُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17437, 'اِسْتِظْرَافٌ', 'استظراف', 'مصدر', 'ظرف', 'استظراف', 'ستظرف', 'مص. اِسْتَظْرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِظْرَافٌ-اِسْتِظْرَافٌ [ظ ر ف] (مص. اِسْتَظْرَفَ). ""اِسْتِظْرَافُ حَدِيثٍ"": وُجُودُهُ ظريفاً، شَيِّقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17438, 'اِسْتِظْلاَلٌ', 'استظلال', 'مصدر', 'ظلل', 'استظلال', 'ستظلل', 'مص. اِسْتَظَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِظْلاَلٌ-اِسْتِظْلاَلٌ [ظ ل ل] (مص. اِسْتَظَلَّ). 1.""يَبْحَثُ عَنْ مكانٍ للاِسْتِظْلالِ"" : أي يَبْحَثُ عَن مَكانٍ بِهِ ظِلٌّ لِيَتَظَلَّلَ بِهِ. 2.""الاِسْتِظْلاَلُ بِالظِّلِّ"": الجُلُوسُ في الظِّلِّ لِلتَّظَلُّلِ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17439, 'اِسْتِعْرَابٌ', 'استعراب', 'مصدر', 'عرب', 'استعراب', 'ستعرب', 'مص. اِسْتَعْرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِعْرَابٌ-اِسْتِعْرَابٌ [ع ر ب] (مص. اِسْتَعْرَبَ). ""الاِسْتِعرابُ"": اِهْتِمامُ الأوربيِّينَ بِثَقافَةِ العَرَبِ وَآدابِهِمْ وَتاريخِهِم وَحَضارَتِهِمْ وَلُغَتِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17440, 'اِسْتِعادَةٌ', 'استعادة', 'مصدر', 'عود', 'استعادة', 'ستعدة', 'مص. اِسْتَعادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِعادَةٌ-اِسْتِعادَةٌ [ع و د] (مص. اِسْتَعادَ). 1.""اِسْتِعادَةُ حُقوقِهِ"":"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17441, 'اِسْتِعاذَةٌ', 'استعاذة', 'مصدر', 'عوذ', 'استعاذة', 'ستعذة', 'مص. اِسْتَعاذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِعاذَةٌ-اِسْتِعاذَةٌ [ع و ذ] (مص. اِسْتَعاذَ). 1.""الاِسْتِعاذَةُ بِاللَّهِ"": الاِعْتِصامُ بِهِ مِنْ شُرُورِ الشَّيْطانِ. 2.""الاِسْتِعاذَةُ مِنْ أَعْمالِ الشَّيْطانِ"": اِسْتِدْفَاعُ الْمَكْرُوهِ بِالرُّقَى والتَّعاوِيذِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17442, 'اِسْتِعارَةٌ', 'استعارة', 'مصدر', 'عور', 'استعارة', 'ستعرة', 'مص. اِسْتَعارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِعارَةٌ-اِسْتِعارَةٌ [ع و ر] (مص. اِسْتَعارَ). 1.""جُمْلَةٌ بِها اسْتِعارَةٌ جَمِيلَةٌ"": اِسْتِعْمالٌ مَجازِيٌّ لِمَعْنىً خاصٍّ بِكَلِمَةٍ لِمَعْنَى آخَرَ على وَجْهِ الْمُشابَهَةِ : ""وَقَفَ أَسَدًا يُحارِبُ الأعْدَاء"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17443, 'اِسْتِعاضَةٌ', 'استعاضة', 'مصدر', 'عوض', 'استعاضة', 'ستعضة', 'مص. اِسْتَعاضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِعاضَةٌ-اِسْتِعاضَةٌ [ع و ض] (مص. اِسْتَعاضَ). ""يَجِبُ الاِسْتِعاضَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17444, 'اِسْتِعْبادٌ', 'استعباد', 'مصدر', 'عبد', 'استعباد', 'ستعبد', 'مص. اِسْتَعْبَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِعْبادٌ-اِسْتِعْبادٌ [ع ب د] (مص. اِسْتَعْبَدَ). ""اِنْتَهَى عَهْدُ الاسْتِعْبادِ"" : اِتِّخاذُ النَّاسِ عَبِيدًا، اِسْتِرْقاقُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17445, 'اِسْتِعْجالٌ', 'استعجال', 'مصدر', 'عجل', 'استعجال', 'ستعجل', 'مص. اِسْتَعْجَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِعْجالٌ-اِسْتِعْجالٌ [ع ج ل] (مص. اِسْتَعْجَلَ). 1.""دَقَّ الجَرَسُ فَخَرَجَ بِاسْتِعْجالٍ"" : خَرَجَ مُسْرِعاً. 2.""ما هَذَا الاسْتِعْجالُ"": ما هَذَا الإِسْرَاعُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17446, 'اِسْتِعْدَادٌ', 'استعداد', 'مصدر', 'عدد', 'استعداد', 'ستعدد', 'مص. اِسْتَعَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِسْتَعَدَّ). 1.""هُوَ على اسْتِعْدادٍ لِلْمُشَارَكَةِ في الْمُباراةِ"" : في حالَةِ تَهَيُّؤٍ كامِلٍ. 2.""وَقَفَ أَبْطالُ السِّباقِ على اِسْتِعْدادٍ لِلانْطِلاَقِ"" : على أُهْبَةِ الانْطِلاقِ. ""كُلُّ وَاحِدٍ يَأخُذُ حَظَّهُ مِنَ العِلْمِ حَسَبَ فِطْرَتِهِ وَاسْتِعْدادِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17447, 'اِسْتِعْداءٌ', 'استعداء', 'مصدر', 'عدي', 'استعداء', 'ستعد', 'مص. اِسْتِعْداء', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِعْداءٌ-اِسْتِعْداءٌ [ع د ي] (مص. اِسْتِعْداء). 1.""طَلَبَ اِسْتِعْداءهُ"" : اِسْتِنْصارَهُ، اِسْتِعانَتَهُ. 2.""اِسْتِعْداءُ الفَرَسِ"" : جَعْلُهُ يَرْكُضُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17448, 'اِسْتِعْذَابٌ', 'استعذاب', 'مصدر', 'عذب', 'استعذاب', 'ستعذب', 'مص. اِسْتَعْذَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِعْذَابٌ-اِسْتِعْذَابٌ [ع ذ ب] (مص. اِسْتَعْذَبَ). ""اِسْتِعْذَابُ ماءٍ"": وُجودُهُ عَذْباً حُلْواً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17449, 'اِسْتِغاثَةٌ', 'استغاثة', 'مصدر', 'غوث', 'استغاثة', 'ستغثة', 'مص. اِسْتَغاثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِغاثَةٌ-اِسْتِغاثَةٌ [غ و ث] (مص. اِسْتَغاثَ). ""لَمَّا سَمِعَ صُراخَه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17450, 'اِسْتِعْراضٌ', 'استعراض', 'مصدر', 'عرض', 'استعراض', 'ستعرض', 'مص. اِسْتَعْرَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِعْراضٌ-اِسْتِعْراضٌ [ع ر ض] (مص. اِسْتَعْرَضَ). 1.""شاهَدَ اسْتِعْراضَ قُوَّاتِ الجَيْشِ"" : مُرُورَها وَهِيَ تُظْهِرُ عَتادَها. 2.""اِسْتِعْراضُ العَضَلاتِ"" : إِبْرازُها، إِظْهارُ القُوَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17451, 'اِسْتِعْصاءٌ', 'استعصاء', 'مصدر', 'عصي', 'استعصاء', 'ستعص', 'مص. اِسْتَعْصَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِعْصاءٌ-اِسْتِعْصاءٌ [ع ص ي] (مص. اِسْتَعْصَى).""اِسْتِعْصاءُ الأمورِ"" : اِشْتِدادُ صُعوبَتِها وَعُسْرُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17452, 'اِسْتِعْطافٌ', 'استعطاف', 'مصدر', 'عطف', 'استعطاف', 'ستعطف', 'مص. اِسْتَعْطَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِعْطافٌ-اِسْتِعْطافٌ [ع ط ف] (مص. اِسْتَعْطَفَ). ""جاءَ لاِسْتِعْطافِهِ"": لِلتَّوَسُّلِ إِلَيْهِ وَطَلَبِ العَطْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17453, 'اِسْتِعْطاءٌ', 'استعطاء', 'مصدر', 'عطو', 'استعطاء', 'ستعط', 'مص. اِسْتَعْطَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِعْطاءٌ-اِسْتِعْطاءٌ [ع ط و] (مص. اِسْتَعْطَى). ""اِسْتِعطاءُ النَّاسِ"": اِسْتِجْداؤُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17454, 'اِسْتِعْظامٌ', 'استعظام', 'مصدر', 'عظم', 'استعظام', 'ستعظم', 'مص. اِسْتَعْظَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِعْظامٌ-اِسْتِعْظامٌ [ع ظ م] (مص. اِسْتَعْظَمَ). 1.""اِسْتِعْظامُ الرَّجُلِ"" : تَعَظُّمُهُ، تَكَبُّرُهُ. 2.""اِسْتِعْظامُ الْمُصابِ"" : عَدُّهُ عَظِيماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17455, 'اِسْتِعْلامٌ', 'استعلام', 'مصدر', 'علم', 'استعلام', 'ستعلم', 'مص. اِسْتَعْلَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِسْتَعْلَمَ) ‎. ""زارَ مَكْتَبَ الاسْتِعْلاماتِ"" : مَكْتَبٌ مُخْتَصٌّ بِإِعْطاءِ الأخْبارِ والْمَعْلُوماتِ وَالإِيضاحاتِ كَما يَكونُ مُخْتَصّاً بِالاسْتِخْباراتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17456, 'اِسْتِعْلاءٌ', 'استعلاء', 'مصدر', 'علو', 'استعلاء', 'ستعل', 'مص. اِسْتَعْلَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِعْلاءٌ-اِسْتِعْلاءٌ [ع ل و] (مص. اِسْتَعْلَى). ""يَنْظُرُ إلى النَّاسِ الآخَرِينَ بِاسْتِعْلاَءٍ"" : بِتَكَبُّرٍ، بِتَرَفُّعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17457, 'اِسْتِعْمارٌ', 'استعمار', 'مصدر', 'عمر', 'استعمار', 'ستعمر', 'مص. اِسْتَعْمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِسْتِعْمارٌ-اِسْتِعْمارٌ [ع م ر] (مص. اِسْتَعْمَرَ). ""دَخَلَ الاِسْتِعْمارُ البُلْدانَ العَرَبِيَّةَ في أَواخِرِ القَرْنِ الماضِي"" : القُوَّةُ الأجْنَبِيَّةُ الْمُسْتَعْمِرَةُ لِبَلَدٍ مَّا، وَتَحْتَلُّهُ بِالسِّلاَحِ وَالقَهْرِ وَالقُوَّةِ، وَتُخْضِعُهُ لِسُلْطانِها السِّياسِيِّ وَالاقْتِصادِيِّ. ""قاوَمَ الشَّعْبُ الاسْتِعْمارَ"" ""اِنْتَهى عَهْدُ الاسْتِعْمارِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17458, 'اِسْتِعْمالٌ', 'استعمال', 'مصدر', 'عمل', 'استعمال', 'ستعمل', 'مص. اِسْتَعْمَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِعْمالٌ-اِسْتِعْمالٌ [ع م ل] (مص. اِسْتَعْمَلَ). 1.""اِنْتَبَهَ إلى كَيْفِيَّةِ اسْتِعْمالِ الدَّواءِ"" : طَريقَة تَناوُلِهِ. ""عِلا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17459, 'اِسْتِفاقَةٌ', 'استفاقة', 'مصدر', 'فوق', 'استفاقة', 'ستفقة', 'مص. اِسْتَفاقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِفاقَةٌ-اِسْتِفاقَةٌ [ف و ق] (مص. اِسْتَفاقَ). 1.""الاسْتِفاقَةُ مِنَ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17460, 'اِسْتِغْرَابٌ', 'استغراب', 'مصدر', 'غرب', 'استغراب', 'ستغرب', 'مص. اِسْتَغْرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِغْرَابٌ-اِسْتِغْرَابٌ [غ ر ب] (مص. اِسْتَغْرَبَ). 1.""نَظَرَ إِلَيْهِ بِاسْتِغْرَابٍ"": بِانْدِهاشٍ. 2.""ما يَقُومُ بِهِ الحاسُوبُ مِنْ عَمَلِيَّاتٍ حِسَابِيَّةٍ يُثِيرُ الاسْتِغْرابَ"" : الاِنْدِهاشَ، الحَيْرَةَ، الإعْجابَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17461, 'اِسْتِغْرَاقٌ', 'استغراق', 'مصدر', 'غرق', 'استغراق', 'ستغرق', 'مص. اِسْتَغْرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِغْرَاقٌ-اِسْتِغْرَاقٌ [غ ر ق] (مص. اِسْتَغْرَقَ). ""وَجَدَهُ في (حالةِ) اسْتِغْراقٍ"": في انْدِماجٍ وانْشِغافٍ لِما هُوَ عَلَيْهِ (في العَمَلِ أَوِ الفِكْرِ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17462, 'اِسْتِغْفارٌ', 'استغفار', 'مصدر', 'غفر', 'استغفار', 'ستغفر', 'مص. اِسْتَغْفَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِغْفارٌ-اِسْتِغْفارٌ [غ ف ر] (مص. اِسْتَغْفَرَ). ""اِسْتِغْفارُ ذَنْبٍ"": طَلَبُ غُفْرانِهِ. ""أَكْثَرَ مِنَ النَّدَمِ وَالاسْتِغْفارِ وَالتَّوْبَةِ"". (أ. أَمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17463, 'اِسْتِغْفالٌ', 'استغفال', 'مصدر', 'غفل', 'استغفال', 'ستغفل', 'مص. اِسْتَغْفَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِغْفالٌ-اِسْتِغْفالٌ [غ ف ل] (مص. اِسْتَغْفَلَ). ""أَرادَ اسْتِغْفالَهُ"": أي تَحَيُّنَ غَفْلَتِهِ وَتَعَمُّدَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17464, 'اِسْتِغْلاَلٌ', 'استغلال', 'مصدر', 'غلل', 'استغلال', 'ستغلل', 'مص. اِسْتَغَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِسْتِغْلاَلٌ-اِسْتِغْلاَلٌ [غ ل ل] (مص. اِسْتَغَلَّ). 1.""يُحاوِلُ اسْتِغْلاَلَ كُلَّ أَرَاضِيهِ بِحَرْثِها وَزَرْعِها"" : اِسْتِثْمارَها. 2.""تَمَكَّنُوا مِنِ اسْتِغْلالِ سَذاجَتِهِ وَإ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17465, 'اِسْتِغْلاقٌ', 'استغلاق', 'مصدر', 'غلق', 'استغلاق', 'ستغلق', 'مص. اِسْتَغْلَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِغْلاقٌ-اِسْتِغْلاقٌ [غ ل ق] (مص. اِسْتَغْلَقَ). 1.""اِسْتِغْلاقُ البابِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17466, 'اِسْتِغْناءٌ', 'استغناء', 'مصدر', 'غني', 'استغناء', 'ستغن', 'مص. اِسْتَغْنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِغْناءٌ-اِسْتِغْناءٌ [غ ن ي] (مص. اِسْتَغْنَى). 1.""قَرَّرَ الاِسْتِغْناءَ عَنْ خَدماتِهِ"" : التَّخَلِّي عَنْ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17467, 'اِسْتِفادَةٌ', 'استفادة', 'مصدر', 'فود', 'استفادة', 'ستفدة', 'مص. اِسْتَفادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِفادَةٌ-اِسْتِفادَةٌ [ف و د] (مص. اِسْتَفادَ). ""الاِسْتِفادَةُ مِنْ مَجْهوداتِهِ"" : الاِنْتِفاعُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17468, 'اِسْتِفاضَةٌ', 'استفاضة', 'مصدر', 'فيض', 'استفاضة', 'ستفضة', 'مص. اِسْتَفاضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِفاضَةٌ-اِسْتِفاضَةٌ [ف ي ض] (مص. اِسْتَفاضَ). 1.""اِسْتِفاضَةُ مَكانٍ"" : اِتِّساعُهُ. 2.""الاِسْتِفاضَةُ في الحديث"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17469, 'اِسْتِقامَةٌ', 'استقامة', 'مصدر', 'قوم', 'استقامة', 'ستقمة', 'مص. اِسْتَقامَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِقامَةٌ-اِسْتِقامَةٌ [ق و م ] (مص. اِسْتَقامَ). 1.""تَأَكَّدَ مِنَ اِسْتِقامَةِ العَمُودِ"" مِنَ اعْتِدالِهِ، اِسْتِوائِهِ. 2.""تَتَّسِمُ تَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17470, 'اِسْتِفْتاحٌ', 'استفتاح', 'مصدر', 'فتح', 'استفتاح', 'ستفتح', 'مص. اِسْتَفْتَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِفْتاحٌ-اِسْتِفْتاحٌ [ف ت ح] (مص. اِسْتَفْتَحَ). 1.""مَازالُوا في انْتِظارِ اسْتِفْتاحِ الحَفْلِ"" : الإعْلانُ عَنْ بِدَايَتِهِ. 2.""أَدَواتُ الاسْتِفْتاحِ"" (نح) : ما يُسْتَفْتَحُ بِهِ الكَلامَ : ""أَلاَ إِنَّ الوَلَدَ قَدْ وَصَلَ""، ""أَما آن لِلْبَدْرِ أَنْ يَطْلُعَ"" : أَلاَ، أَمَا : مِنْ أَدَواتِ الاسْتِفْتاحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17471, 'اِسْتِفْتاءٌ', 'استفتاء', 'مصدر', 'فتو', 'استفتاء', 'ستفت', 'مص. اِسْتَفْتَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِفْتاءٌ-اِسْتِفْتاءٌ [ف ت و] (مص. اِسْتَفْتَى). ""لِمَعْرِفَةِ رَغْبَةِ الشَّعْبِ لاَ بُدَّ مِنْ تَنْظِيمِ الاسْتِفْتاءِ"" : اِقْتِراعُ النَّاخِبِينَ للإِدْلاَءِ بِآر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17472, 'اِسْتِفْحالٌ', 'استفحال', 'مصدر', 'فحل', 'استفحال', 'ستفحل', 'مص. اِسْتَفْحَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِفْحالٌ-اِسْتِفْحالٌ [ف ح ل] (مص. اِسْتَفْحَلَ). ""اِسْتِقْحالُ الدَّاءِ"": تَفاقُمُهُ، اِنْتِشارُهُ. ""اِشْتَدَّ اِسْتِفْحالُ النِّيرَانِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17473, 'اِسْتِفْرادٌ', 'استفراد', 'مصدر', 'فرد', 'استفراد', 'ستفرد', 'مص. اِسْتَفْرَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِفْرادٌ-اِسْتِفْرادٌ [ف ر د] (مص. اِسْتَفْرَدَ). 1.""الاِسْتِفْرادُ بِالرَّأْيِ"": الاِنْفَرا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17474, 'اِسْتِفْرَاغٌ', 'استفراغ', 'مصدر', 'فرغ', 'استفراغ', 'ستفرغ', 'مص. اِسْتَفْرَغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِفْرَاغٌ-اِسْتِفْرَاغٌ [ف ر غ] (مص. اِسْتَفْرَغَ). 1.""اِسْتِفْرَاغُ ما في البَطْنِ"" : التَّقَيُّؤُ. 2.""اِسْتِفْراغُ كُلِّ الجُهْدِ في العَمَلِ"" : بَذْلُهُ والتَّفَرُّغُ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17475, 'اِسْتِفْزَازٌ', 'استفزاز', 'مصدر', 'فزز', 'استفزاز', 'ستفزز', 'مص. اِسْتَفَزَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِسْتِفْزَازٌ-اِسْتِفْزَازٌ [ف ز ز] (مص. اِسْتَفَزَّ). ""قَصَدَ اسْتِفْزَازَهُ"": جَعْلُهُ يَضْطَرِبُ وَيَفُورُ غَضَباً، إِزْعَاجُهُ، إِثارَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17476, 'اِسْتِفْسارٌ', 'استفسار', 'مصدر', 'فسر', 'استفسار', 'ستفسر', 'مص. اِسْتَفْسَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِفْسارٌ-اِسْتِفْسارٌ [ف س ر] (مص. اِسْتَفْسَرَ). ""الاسْتِفْسارُ عَنِ الوَقائِعِ والْمَعْلوماتِ"" : طَلَبُ تَوْضِيحِها وَتِبْيانِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17477, 'اِسْتِفْهامٌ', 'استفهام', 'مصدر', 'فهم', 'استفهام', 'ستفهم', 'مص. اِسْتَفْهَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِفْهامٌ-اِسْتِفْهامٌ [ف هـ م] (مص. اِسْتَفْهَمَ). 1.""أَثارَ الاسْتِفْهامَ بِتَصَرُّفِهِ"" : أَثارَ التَّساؤُلَ. 2.""أَجاءَ الوَلَدُ""، ""هَلْ قَرَأْتَ الكِتابَ"" : أ، وَهَلْ: حَرْفانِ مِنْ حُرُوفِ الاسْتِفْهامِ. 3.""مَنْ قَرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17478, 'اِسْتِقالَةٌ', 'استقالة', 'مصدر', 'قيل', 'استقالة', 'ستقلة', 'مص. اِسْتَقالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِقالَةٌ-اِسْتِقالَةٌ [ق ي ل] (مص. اِسْتَقالَ). ""قَدَّمَ اسْتِقالَتَهُ مِنْ مَنْصِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17479, 'اِسْتِكْتابٌ', 'استكتاب', 'مصدر', 'كتب', 'استكتاب', 'ستكتب', 'مص. اِسْتَكْتَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِكْتابٌ-اِسْتِكْتابٌ [ك ت ب] (مص. اِسْتَكْتَبَ). 1.""اِسْتِكْتابُ رِسالَةٍ"" : طَلَبُ كِتابَتِها. 2.""اِسْتِكْتابُ قَصِيدَةٍ"": إِمْلاؤُها. 3.""اِسْتِكْتابُ طُلاَّبٍ"" : اِتِّخاذُهُمْ كُتَّاباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17480, 'اِسْتِقْباحٌ', 'استقباح', 'مصدر', 'قبح', 'استقباح', 'ستقبح', 'مص. اِسْتَقْبَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِقْباحٌ-اِسْتِقْباحٌ [ق ب ح] (مص. اِسْتَق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17481, 'اِسْتِقْبالٌ', 'استقبال', 'مصدر', 'قبل', 'استقبال', 'ستقبل', 'مص. اِسْتَقْبَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِقْبالٌ-اِسْتِقْبالٌ [ق ب ل] (مص. اِسْتَقْبَلَ). ‍1.""خَرَجَ لاِسْتِقْبالِهِ"": لِلُقْياهِ، لِمُقابَلَتِهِ. 2.""هَيَّأَ غُرْفَةَ الاسْتِقْبالِ"": غُرْفَةً لاسْتِضافَةِ الضُّيوفِ والأَ‌صْدِقاءِ. 3."""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17482, 'اِسْتِقْدامٌ', 'استقدام', 'مصدر', 'قدم', 'استقدام', 'ستقدم', 'مص. اِسْتَقْدَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِقْدامٌ-اِسْتِقْدامٌ [ق د م] (مص. اِسْتَقْدَمَ). ""اِسْتِقْدَامُ الرَّجُلِ"": طَلَبُ قُدُومِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17483, 'اِسْتِقْرارٌ', 'استقرار', 'مصدر', 'قرر', 'استقرار', 'ستقرر', 'مص. اِسْتَقَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِقْرارٌ-اِسْتِقْرارٌ [ق ر ر] (مص. اِسْتَقَرَّ). 1.""عَرَفَ الطَّقْسُ اسْتِقْرارًا"" : لَمْ يَطْرَأْ عَلَيْهِ تَغْيِيرٌ، أَيْ بَقِيَ ثابِتًا عَلى ما ك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17484, 'اِسْتِقْراءٌ', 'استقراء', 'مصدر', 'قرأ', 'استقراء', 'ستقر', 'مص. اِسْتَقْرَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِسْتِقْراءٌ-اِسْتِقْراءٌ [ق ر أ] (مص. اِسْتَقْرَأَ). ""اِسْتِقْراءُ الوَقائِعِ"" : تَتَبُّعُها عَنْ قُرْبٍ مُعايَنَةً وَمُشاهَدَةً لِلْوُصولِ إلى أحْكامٍ عامَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17485, 'اِسْتِقْصاءٌ', 'استقصاء', 'مصدر', 'قصي', 'استقصاء', 'ستقص', 'مص. اِسْتَقْصَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِقْصاءٌ-اِسْتِقْصاءٌ [ق ص ي] (مص. اِسْتَقْصَى). ""اِسْتِقْصاءُ تَفاصيلِ الْمَوْضوعِ كُلِّهَا"" : بَحْثُ تَفاصيلِ الْمَوْضوعِ جُمْلَةً وَتَفْصيلاً. ""اِسْتِقْصاءٌ في البَحْثِ وَعُمْقٌ في الدَّرْسِ"". (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17486, 'اِسْتِقْلالٌ', 'استقلال', 'مصدر', 'قلل', 'استقلال', 'ستقلل', 'مص. اِسْتَقَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِسْتِقْلالٌ-اِسْتِقْلالٌ [ق ل ل] (مص. اِسْتَقَلَّ). 1.""الاِسْتِقْلالُ بِالرَّأْيِ"" : الاِسْتِبْدادُ بِهِ وَعَدَمُ مُشارَكَةِ النَّاسِ الآخَرِينَ فِيه. 2.""ناضَلَ الشَّعْبُ العَرَبِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17487, 'اِسْتِكانَةٌ', 'استكانة', 'مصدر', 'كون', 'استكانة', 'ستكنة', 'مص. اِسْتكانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِكانَةٌ-اِسْتِكانَةٌ (مص. اِسْتكانَ). ""يَرْفُضُ الاِسْتِكانَةَ"" : أَي الخُضوعَ، الخُنوعَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17488, 'اِسْتِكْبارٌ', 'استكبار', 'مصدر', 'كبر', 'استكبار', 'ستكبر', 'مص. اِسْتَكْبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِكْبارٌ-اِسْتِكْبارٌ [ك ب ر] (مص. اِسْتَكْبَرَ). 1.""اِسْتِكْبارُ الرَّجُلِ"": كِبْرِياؤُهُ، غُرُورُهُ. 2.""اِسْتِكْبارُ الحَدَثِ"" : تَضْخيمُهُ وَعَدُّهُ كَبيراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17489, 'اِسْتِلاَفٌ', 'استلاف', 'مصدر', 'سلف', 'استلاف', 'ستلف', 'مص. اِسْتَلَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِلاَفٌ-اِسْتِلاَفٌ [س ل ف] (مص. اِسْتَلَفَ). ""اِسْتِلافُ قَدْرٍ مِنَ المالِ"" : اِقْتِراضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17490, 'اِسْتِكْثارٌ', 'استكثار', 'مصدر', 'كثر', 'استكثار', 'ستكثر', 'مص. اِسْتَكْثَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِكْثارٌ-اِسْتِكْثارٌ [ك ث ر] (مص. اِسْتَكْثَرَ). 1.""اِسْتِكْثارُ عَدَدِ الضُّيوفِ"" : وُجودُ عَدَدِهِمْ كَثِيراً، وَفْرَتُهُمْ. 2.""الاِسْتِكْثارُ مِنْ شُرْبِ العَصِيرِ"" : الإِكْثارُ مِنْ شُرْبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17491, 'اِسْتِكْراهٌ', 'استكراه', 'مصدر', 'كره', 'استكراه', 'ستكره', 'مص. اِسْتَكْرَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِكْراهٌ-اِسْتِكْراهٌ [ك ر هـ] (مص. اِسْتَكْرَهَ). ""اِسْتِكْراهُ فِعْلٍ"": عَدُّهُ قَبِيحاً، كَرِيهاً. ""حَذَّرَهُ التَّكَلُّفَ وَاسْتِكْراهَ العِبارَةِ"". (الجاحظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17492, 'اِسْتِكْشافٌ', 'استكشاف', 'مصدر', 'كشف', 'استكشاف', 'ستكشف', 'مص. اِسْتَكْشَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِكْشافٌ-اِسْتِكْشافٌ [ك ش ف] (مص. اِسْتَكْشَفَ). 1.""خَرَجَ في رِحْلَةِ اسْتِكْشافٍ"" : اِسْتِطْلاعٍ، اِسْتِقْصاءٍ، اِكْتِشافٍ. 2.""ظَلَّتْ طائِراتُ الاسْتِكْشافِ تُحَلِّقُ فَوْق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17493, 'اِسْتِكْمالٌ', 'استكمال', 'مصدر', 'كمل', 'استكمال', 'ستكمل', 'مص. اِسْتَكْمَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِكْمالٌ-اِسْتِكْمالٌ [ك م ل] (مص. اِسْتَكْمَلَ). ""اِسْتِكْمالُ ما كانَ ناقِصاً"" : تَتْمِيمُهُ، تَكْميلُهُ. ""اِسْتِكْمالُ الدُّروسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17494, 'اِسْتِلالٌ', 'استلال', 'مصدر', 'سلل', 'استلال', 'ستلل', 'مص. اِسْتَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِلالٌ-اِسْتِلالٌ [س ل ل] (مص. اِسْتَلَّ). ""اِسْتِلالُ السَّيْفِ"": اِمْتِشاقُهُ، أَيْ إِخْراجُهُ من غِمْدِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17495, 'اِسْتِلابٌ', 'استلاب', 'مصدر', 'سلب', 'استلاب', 'ستلب', 'مص. اِسْتَلَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِلابٌ-اِسْتِلابٌ [س ل ب] (مص. اِسْتَلَبَ). 1.""حاوَلَ اسْتِلاَبَ أَمْوالِهِ"" : اِخْتِلاَسَها. 2.""يَعِيشُ حَياةَ اسْتِلابٍ"" : حَياةَ خُضُوعٍ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17496, 'اِسْتِلْذَاذٌ', 'استلذاذ', 'مصدر', 'لذذ', 'استلذاذ', 'ستلذذ', 'مص. اِسْتَلَذَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِلْذَاذٌ-اِسْتِلْذَاذٌ [ل ذ ذ] (مص. اِسْتَلَذَّ). ""اِسْتِلْذَاذُ الطَّعامِ"" : وُجودُهُ لَذِيذاً طَيِّباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17497, 'اِسْتِلْزامٌ', 'استلزام', 'مصدر', 'لزم', 'استلزام', 'ستلزم', 'مص. اِسْتَلْزَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِلْزامٌ-اِسْتِلْزامٌ [ل ز م] (مص. اِسْتَلْزَمَ)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17498, 'اِسْتِلْطافٌ', 'استلطاف', 'مصدر', 'لطف', 'استلطاف', 'ستلطف', 'مص. اِسْتَلْطَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِلْطافٌ-اِسْتِلْطافٌ [ل ط ف] (مص. اِسْتَلْطَفَ). 1.""اِسْتِلْطافُ الرَّجُلِ"" : وَجودُهُ لَطيفاً. 2.""اِسْتِلْطافُ الْمَكانِ"": وُجودُهُ رَائِعاً، رَائِقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17499, 'اِسْتِلْفاتٌ', 'استلفات', 'مصدر', 'لفت', 'استلفات', 'ستلفت', 'مص. اِسْتَلْفَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِلْفاتٌ-اِسْتِلْفاتٌ [ل ف ت] (مص. اِسْتَلْفَتَ). ""اِسْتِلْفاتُ النَّظَرِ"": اِسْتِرْعاءُ الانْتِباهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17500, 'اِسْتِلْقاءٌ', 'استلقاء', 'مصدر', 'لقي', 'استلقاء', 'ستلق', 'مص. اِسْتَلْقَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِلْقاءٌ-اِسْتِلْقاءٌ [ل ق ي] (مص. اِسْتَلْقَى). ""الاِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17501, 'اِسْتِلامٌ', 'استلام', 'مصدر', 'سلم', 'استلام', 'ستلم', 'مص. اِسْتَلَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِلامٌ-اِسْتِلامٌ [س ل م] (مص. اِسْتَلَمَ). 1.""اِسْتِلامُ رِسالَةٍ"": تَسَلُّمُها، أَخْذُها بِاليَدِ. 2.""اِسْتِلامُ الحَجَرِ الأسْودِ"" : لَمْسُهُ أَوْ تَقْبِيلُهُ في أَعْمالِ مَناسِكِ الحَجِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17502, 'اِسْتِماتَةٌ', 'استماتة', 'مصدر', 'موت', 'استماتة', 'ستمتة', 'مص. اِسْتَماتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِماتَةٌ-اِسْتِماتَةٌ [م و ت] (مص. اِسْتَماتَ). ""أَظْهَرَ اسْتِماتَةً"": تَصَلُّباً وَثباتاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17503, 'اِسْتِمالَةٌ', 'استمالة', 'مصدر', 'ميل', 'استمالة', 'ستملة', 'مص. اِسْتَمالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِمالَةٌ-اِسْتِمالَةٌ [م ي ل] (مص. اِسْتَمالَ). 1.""حاوَلَ اسْتِمالَتَهُ"" : جَذْبُهُ وَجَعْلُهُ يَميلُ إلى ... 2.""بَرَّرَ اسْتِمالَتَهُ"" : اِسْتعْطافَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17504, 'اِسْتِمْتاعٌ', 'استمتاع', 'مصدر', 'متع', 'استمتاع', 'ستمتع', 'مص. اِسْتَمْتَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِمْتاعٌ-اِسْتِمْتاعٌ [م ت ع] (مص. اِسْتَمْتَعَ). ""الاِسْتِمْتاعُ بِالشَّيْءِ"" : التَّمَتُّعُ بِهِ، التَّلَذُّذُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17505, 'اِسْتِمْدادٌ', 'استمداد', 'مصدر', 'مدد', 'استمداد', 'ستمدد', 'مص. اِسْتَمَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِمْدادٌ-اِسْتِمْدادٌ [م د د] (مص. اِسْتَمَدَّ). 1.""الاسْتِمْدادُ مِنَ الدَّواةِ"": أَخْذُ المِدادَ مِنْها. 2.""اِسْتِمْدادُ القُوَّةِ مِنَ العَزِيمَةِ"" : أَخْذُها مِنَ العَزِيمَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17506, 'اِسْتِمْرارٌ', 'استمرار', 'مصدر', 'مرر', 'استمرار', 'ستمرر', 'مص. اِسْتَمَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِمْرارٌ-اِسْتِمْرارٌ [م ر ر] (مص. اِسْتَمَرَّ). ""يُسافِرُ بِاسْتِمْرارٍ"": على الدَّوامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17507, 'اِسْتِماعٌ', 'استماع', 'مصدر', 'سمع', 'استماع', 'ستمع', 'مص. اِسْتَمَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِماعٌ-اِسْتِماعٌ [س م ع] (مص. اِسْتَمَعَ). 1.""الاِسْتِماعُ إلى كَلامِ الخَطيبِ"" : الإصْغاءُ إِلَي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17508, 'اِسْتِمْلاحٌ', 'استملاح', 'مصدر', 'ملح', 'استملاح', 'ستملح', 'مص. اِسْتَمْلَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِمْلاحٌ-اِسْتِمْلاحٌ [م ل ح] (مص. اِسْتَمْلَحَ). ""اِسْتِمْلاحُ وَجْهٍ"": وُجودُهُ مَليحاً، حَسَناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17509, 'اِسْتِمْهالٌ', 'استمهال', 'مصدر', 'مهل', 'استمهال', 'ستمهل', 'مص. اِسْتَمْهَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِمْهالٌ-اِسْتِمْهالٌ [م هـ ل] (اِسْتَمْهَلَ). ""قَبِلَ اِسْتِمْهالَهُ"" : قَبِلَ إِعْطاءَهُ مُهْلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17510, 'اِسْتِنارَةٌ', 'استنارة', 'مصدر', 'نور', 'استنارة', 'ستنرة', 'مص. اِسْتَنارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِنارَةٌ-اِسْتِنارَةٌ [ن و ر] (مص. اِسْتَنارَ). 1.""اِسْتِنارَةُ البَيْتِ"": إِضاءَتُهُ. 2.""حاوَلَ اسْتِنارَةَ عَقْل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17511, 'اِسْتِنْباطٌ', 'استنباط', 'مصدر', 'نبط', 'استنباط', 'ستنبط', 'مص. اِسْتَنْبَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِسْتِنْباطٌ-اِسْتِنْباطٌ [ن ب ط] (مص. اِسْتَنْبَطَ). ""اِسْتِنْباطُ آراءٍ جَديدَةٍ"" : اِسْتِخْراجُها بِفَهْمٍ واجْتِهادٍ، اِسْتِنْتاجُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17512, 'اِسْتِنْتاجٌ', 'استنتاج', 'مصدر', 'نتج', 'استنتاج', 'ستنتج', 'مص. اِسْتَنْتَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِسْتَنْتَجَ). ""اِسْتِنْتاجُ القاعِدَةِ"" : اِسْتِخْراجُها، اِسْتِنْباطُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17513, 'اِسْتِنْجادٌ', 'استنجاد', 'مصدر', 'نجد', 'استنجاد', 'ستنجد', 'مص. اِسْتَنْجَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِنْجادٌ-اِسْتِنْجادٌ [ن ج د] (مص. اِسْتَنْجَدَ). 1.""طَلَبَ اسْتِنْجادَهُ"" : طَلَبَ نَجْدَتَهُ. 2.""الاسْتِنْجادُ بِالأَصْدِقاءِ"" : الاسْتِعانَةُ بِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17514, 'اِسْتِناد', 'استناد', 'مصدر', 'سند', 'استناد', 'ستند', 'مص. اِسْتَنَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِناد-اِسْتِنادٌ [س ن د] (مص. اِسْتَنَدَ). 1.""الاسْتِنادُ إِلى الجِدارِ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17515, 'اِسْتِنْزافٌ', 'استنزاف', 'مصدر', 'نزف', 'استنزاف', 'ستنزف', 'مص. اِسْتَنْزَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِنْزافٌ-اِسْتِنْزافٌ [ن ز ف] (مص. اِسْتَنْزَفَ). 1.""يَعيشُ حالَةَ اسْتِنْزافٍ"": حالَةَ اسْتِنْفادٍ لِقُوَّتِهِ أَو لِطاقاتِهِ... 2.""حَرْبُ الاسْتِنْزافِ"" : حَرْبٌ تَهْدِفُ إلى القَضاءِ على قُدُراتِ العَدُوِّ وَإِمْكانَاتِهِ بِالتَّدْرِيجِ إلى أن يَتِمَّ اسْتِنْفادُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17516, 'اِسْتِنْساخٌ', 'استنساخ', 'مصدر', 'نسخ', 'استنساخ', 'ستنسخ', 'مص. اِسْتَنْسَخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِنْساخٌ-اِسْتِنْساخٌ [ن س خ] (مص. اِسْتَنْسَخَ). 1.""قامَ باسْتِنْساخِ مَخْطوطٍ"" : نَقْلُهُ بِخَطِّ يَدِهِ. 2.""اِسْتِنْساخُ الصَّفَحاتِ"" : تَصْوِيرُها. ""يُمْكِنُ اسْتِنْساخُ ما تُرِيدُ مِنْ صَفَحاتِ الكُتُبِ وَالأوْراقِ الرَّسْمِيَّةِ بِآلاَتِ الاسْتِنْساخِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17517, 'اِسْتِنْشاقٌ', 'استنشاق', 'مصدر', 'نشق', 'استنشاق', 'ستنشق', 'مص. اِسْتَنْشَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِنْشاقٌ-اِسْتِنْشاقٌ [ن ش ق] (مص. اِسْتَنْشَقَ). 1.""اسْتِنْشاقُ الهواءِ"": شَمُّهُ. 2.""اِسْتِنْشاقُ الماءِ"" : إِدْخالُهُ إلى الأَنْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17518, 'اِسْتِنْصارٌ', 'استنصار', 'مصدر', 'نصر', 'استنصار', 'ستنصر', 'مص. اِسْتَنْصَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِنْصارٌ-اِسْتِنْصارٌ [ن ص ر] (مص. اِسْتَنْصَرَ). ""الاسْتِنْصارُ بِالأقْرِباءِ"" : الاسْتِعانَةُ بِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17519, 'اِسْتِهْتارٌ', 'استهتار', 'مصدر', 'هتر', 'استهتار', 'ستهتر', 'مص. اِسْتَهْتَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِهْتارٌ-اِسْتِهْتارٌ [هـ ت ر] (مص. اِسْتَهْتَرَ). ""ما هَذَا الاسْتِهْتارُ بِالقِيَمِ "" : الاسْتِخْفافُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17520, 'اِسْتِنْطاقٌ', 'استنطاق', 'مصدر', 'نطق', 'استنطاق', 'ستنطق', 'مص. اِسْتَنْطَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِنْطاقٌ-اِسْتِنْطاقٌ [ن ط ق] (مص. اِسْتَنْطَقَ). ""اِسْتِنْطَاقُ مُتَّهَمٍ"": اِسْتِجْوابُهُ حَوْلَ قَضِيَّةٍ أَوْ حادِثٍ مَّا قامَ بِهِ لِتَأْكِيدِ اتِّهامِهِ أَوْ بَراءتِهِ. وَالاسْتِنْطاقُ يَقومُ بِهِ قاضِي التَّحْقِيقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17521, 'اِسْتِنْعَاشٌ', 'استنعاش', 'مصدر', 'نعش', 'استنعاش', 'ستنعش', 'مص. اِسْتَنْعَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِنْعَاشٌ-اِسْتِنْعَاشٌ [ن ع ش] (مص. اِسْتَنْعَشَ). ""اِسْتِنْعاشُ الْمَرِيضِ"": عَوْدَةُ الحَياةِ إِلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17522, 'اِسْتِنْفادٌ', 'استنفاد', 'مصدر', 'نفد', 'استنفاد', 'ستنفد', 'مص. اِسْتَنْفَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِنْفادٌ-اِسْتِنْفادٌ [ن ف د] (مص. اِسْتَنْفَدَ). ""اِسْتِنْفادُ الطَّاقَةِ"": اسْتِنْزافُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17523, 'اِسْتِنْفارٌ', 'استنفار', 'مصدر', 'نفر', 'استنفار', 'ستنفر', 'مص. اِسْتَنْفَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِنْفارٌ-اِسْتِنْفارٌ [ن ف ر] (مص. اِسْتَنْفَرَ). ""اِسْتِنْفارُ الجَيْشِ"": وُجودُهُ في حالَةِ اسْتِعْدادٍ وَتَأَهُّبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17524, 'اِسْتِنْكارٌ', 'استنكار', 'مصدر', 'نكر', 'استنكار', 'ستنكر', 'مص. اِسْتَنْكَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِنْكارٌ-اِسْتِنْكارٌ [ن ك ر] (مص. اِسْتَنْكَرَ). ""عَبَّرَ عَنِ اسْتِنْكارِهِ لما حَدَثَ"": عَنِ احْتِجاجِهِ واسْتِقْباحِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17525, 'اِسْتِنْكافٌ', 'استنكاف', 'مصدر', 'نكف', 'استنكاف', 'ستنكف', 'مص. اِسْتَنْكَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِنْكافٌ-اِسْتِنْكافٌ [ن ك ف] (مص. اِسْتَنْكَفَ). 1.""اِسْتِنْكافُ الرَّجُلِ"": اِسْتِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17526, 'اِسْتِنْهاضٌ', 'استنهاض', 'مصدر', 'نهض', 'استنهاض', 'ستنهض', 'مص. اِسْتَنْهَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِنْهاضٌ-اِسْتِنْهاضٌ [ن هـ ض] (مص. اِسْتَنْهَضَ). ""اِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17527, 'اِسْتِنْواقٌ', 'استنواق', 'مصدر', 'نوق', 'استنواق', 'ستنق', 'مص. اِسْتَنْوَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِنْواقٌ-اِسْتِنْواقٌ [ن و ق] (مص. اِسْتَنْوَقَ). ""اِسْتِنْواقُ الجَمَلِ"": تَشَبُّهُهُ بِالنَّاقَةِ أَوْ صَيْرُهُ كَالنَّاقَةِ في ذُلِّها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17528, 'اِسْتِهانَةٌ', 'استهانة', 'مصدر', 'هون', 'استهانة', 'ستهنة', 'مص. اِسْتَهانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِهانَةٌ-اِسْتِهانَةٌ [هـ و ن] (مص. اِسْتَهانَ). ""لَيْسَ مِنْ عادَتِهِ الاسْتِهانَةُ بِدِراسَتِهِ"" : الاسْتِخْفافُ، اللاَّمُبالاَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17529, 'اِسْتيصافٌ', 'استيصاف', 'مصدر', 'وصف', 'استيصاف', 'ستصف', 'مص. اِسْتَوْصَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتيصافٌ-اِسْتيصافٌ [و ص ف] (مص. اِسْتَوْصَفَ). ""اِسْتيصافُ الطَّبِيبِ"" : طَلَبُ وَصْفِ دواءٍ لِمرضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17530, 'اِسْتِهْجانٌ', 'استهجان', 'مصدر', 'هجن', 'استهجان', 'ستهجن', 'مص. اِسْتَهْجَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِهْجانٌ-اِسْتِهْجانٌ [هـ ج ن] (مص. اِسْتَهْجَنَ). ""اِسْتِهْجانُ أَمْرٍ"": اِسْتِقْباحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17531, 'اِسْتِهْدافٌ', 'استهداف', 'مصدر', 'هدف', 'استهداف', 'ستهدف', 'مص. اِسْتَهْدَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِهْدافٌ-اِسْتِهْدافٌ [هـ د ف] (مص. اِسْتَهْدَفَ). 1.""اِسْتِهْدافُ طَريدَةٍ"" : جَعْلُها هَدَفاً لِصَيْدٍ. 2.""اِسْتِهْدافُ الرَّجُلِ"" : عَنْيُهُ، قَصْدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17532, 'اِسْتِهْلالٌ', 'استهلال', 'مصدر', 'هلل', 'استهلال', 'ستهلل', 'مص. اِسْتَهَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِهْلالٌ-اِسْتِهْلالٌ [هـ ل ل] (مص. اِسْتَهَلَّ). 1.""الاسْتِهْلالُ في الشِّعْرِ"": أَوَّلُ القَصيدَةِ. 2.""اِسْتِهْلالُ أُغْنِيَّةٍ"" : المقدِّمَةُ الموسِيقِيَّةُ الَّتِي يُبْدَأُ بِها قَبْلَ مُباشَرَةِ الغِناءِ. 3. ""اِسْتِهْلالُ الحَديثِ"": حُسْنُ ابْتِدائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17533, 'اِسْتِهْلاكٌ', 'استهلاك', 'مصدر', 'هلك', 'استهلاك', 'ستهلك', 'مص. اِسْتَهْلكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِهْلاكٌ-اِسْتِهْلاكٌ [هـ ل ك] (مص. اِسْتَهْلكَ). 1.""لاَبُدَّ مِن اسْتِهْلاكِ ما تَبَقَّى مِنْ مَخْزُونٍ"" : مِن اسْتِعْمالٍ، مِنْ تَصْريفٍ. 2.""اِسْتِهْلاكُ الشَّايِ وَالقَهْوَةِ"" : تَناوُلُهُما."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17534, 'اِسْتِهْواءٌ', 'استهواء', 'مصدر', 'هوي', 'استهواء', 'سته', 'مص. اِسْتَهْوَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِهْواءٌ-اِسْتِهْواءٌ [هـ وي] (مص. اِسْتَهْوَى). 1.""أَثارَتِ الطَّبيعَةُ اسْتِهواءهُ"": إِعْجابَهُ. 2.""رَغِبَ في اسْتِهوائِهِ"" : في جَذْبِهِ، في إِغْوائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17535, 'اِسْتيجابٌ', 'استيجاب', 'مصدر', 'جوب', 'استيجاب', 'ستجب', 'مص. اِسْتَوْجَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتيجابٌ-اِسْتيجابٌ [ج و ب] (مص. اِسْتَوْجَبَ). 1.""اِسْتِيجابُ العِقابِ"" : اِسْتِحْقاقُهُ. 2.""اِسْتِيجابُ الخُضوعِ لِلأَوامِرِ"" : عَدُّها واجِبًا، اِسْتِلْزَامُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17536, 'اِسْتيحاءٌ', 'استيحاء', 'مصدر', 'وحي', 'استيحاء', 'ستح', 'مص. اِسْتَوْحى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتيحاءٌ-اِسْتيحاءٌ [و ح ي] (مص. اِسْتَوْحى). ""حاوَلَ اسْتيحاءَ أَفْكارٍ جَدِيدَةٍ مِنَ النَّصِّ"" : اِسْتِقاؤُها، الإتْيانُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17537, 'اِسْتيداعٌ', 'استيداع', 'مصدر', 'ودع', 'استيداع', 'ستدع', 'مص. اِسْتَوْدَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتيداعٌ-اِسْتيداعٌ [و د ع] (مص. اِسْتَوْدَعَ). 1.""اِسْتيداعُ حَقيبَةٍ"": تَرْكُها وَديعَةً، أَمانةً. 2.""فَضَّلَ اسْتِيداعَ أَمْرِهِ إلى اللَّهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17538, 'اِسْتيرادٌ', 'استيراد', 'مصدر', 'ورد', 'استيراد', 'سترد', 'مص. اِسْتَوْرَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتيرادٌ-اِسْتيرادٌ [و ر د] (مص. اِسْتَوْرَدَ). ""اِسْتيرادُ البَضائِعِ"": اِسْتِجْلابُها مِنْ خارِجِ البِلادِ، عَكْسَ التَّصْدِيرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17539, 'اِسْتِيئاسٌ', 'استيئاس', 'مصدر', 'يأس', 'استيءاس', 'ستس', 'مص. اِسْتَيْأَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِيئاسٌ-اِسْتِيئاسٌ[ي أ س] (مص. اِسْتَيْأَسَ). ""وَجَدَهُ في حالَةِ اِسْتِيئاسٍ شَدِيدَةٍ"" : في يَأْسٍ، لا أَمَلَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17540, 'اِسْتيصاءٌ', 'استيصاء', 'مصدر', 'وصي', 'استيصاء', 'ستص', 'مص. اِسْتَوْصَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتيصاءٌ-اِسْتيصاءٌ [و ص ي] (مص. اِسْتَوْصَى). 1.""قَبِلَ الاسْتيصاءَ بِهِ"" : قَبِلَ الوَصِيَّةَ بِهِ. 2.""الاسْتيصاءُ بِالوَلَدِ خَيْراً"" : إِرادَةُ الخَيْرِ لَهُ وَفِعْلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17541, 'اِسْتِيضاحٌ', 'استيضاح', 'مصدر', 'وضح', 'استيضاح', 'ستضح', 'مص. اِسْتَوْضَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتِيضاحٌ-اِسْتِيضاحٌ [و ض ح] (مص. اِسْتَوْضَحَ). ""قَدَّمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17542, 'اِسْتِيطانٌ', 'استيطان', 'مصدر', 'وطن', 'استيطان', 'ستطن', 'مص. اِسْتَوْطَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِسْتِيطانٌ-اِسْتِيطانٌ [و ط ن] (مص. اِسْتَوْطَنَ). ""مِنْ أَخْطَرِ ما عَرَفَهُ العَالَمُ العَرَبِيُّ اسْتيطانُ فِلَسْطينَ"" : إِسْكانُها مِنْ جانِبِ اليَهودِ وَمُحاوَلَةُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17543, 'اِسْتيعابٌ', 'استيعاب', 'مصدر', 'وعب', 'استيعاب', 'ستعب', 'مص. اِسْتَوْعَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتيعابٌ-اِسْتيعابٌ [و ع ب] (مص. اِسْتَوْعَبَ). ""اِسْتيعابُ أَفْكارِ الكِتابِ"" : فَهْمُها فَهْماً دقِيقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17544, 'اِسْتيفادٌ', 'استيفاد', 'مصدر', 'وفد', 'استيفاد', 'ستفد', 'مص. اِسْتَوْفَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتيفادٌ-اِسْتيفادٌ [و ف د] (مص. اِسْتَوْفَدَ). ""اِسْتيفادُ الوَفْدِ"": إِرْسالُهُ في مُهِمَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17545, 'اِسْتيفاءٌ', 'استيفاء', 'مصدر', 'وفي', 'استيفاء', 'ستف', 'مص. اِسْتَوْفَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتيفاءٌ-اِسْتيفاءٌ [و ف ي] (مص. اِسْتَوْفَى). ""اِسْتِيفاءُ الْمَوْضوعِ حَقَّهُ"" : إِعْطاؤُهُ ما يَسْتَحِقُّ، أَيْ تَناوُلُهُ تناوُلاً تَامّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17546, 'اِسْتيقادٌ', 'استيقاد', 'مصدر', 'وقد', 'استيقاد', 'ستقد', 'مص. اِسْتَوْقَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتيقادٌ-اِسْتيقادٌ [و ق د] (مص. اِسْتَوْقَدَ). ""اِسْتيقادُ النَّارِ"" : إِيقادُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17547, 'اِسْتيلاءٌ', 'استيلاء', 'مصدر', 'ولي', 'استيلاء', 'ستل', 'مص. اِسْتَوْلى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتيلاءٌ-اِسْتيلاءٌ [و ل ي] (مص. اِسْتَوْلى). 1.""الاسْتيلاءُ على خَيْراتِ البِلادِ"": السَّيْطَرَةُ عَلَيْها. ""أَعْلَنَ الجَيْشُ اِسْتيلاءهُ على مَواقِعَ جَدِيدَةٍ"". 2.""الاسْتي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17548, 'اِسْتِواءٌ', 'استواء', 'مصدر', 'سوي', 'استواء', 'ست', 'مص. اِسْتَوَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِسْتِواءٌ-اِسْتِواءٌ [س و ي] (مص. اِسْتَوَى). 1.""اِسْتِواءُ قامَتِهِ"": اِسْتِقامَتُها، اِعْتِدالُها. 2.""خَطُّ الاسْتِواءِ"" (جغ) : دائِرَةٌ وَهْمِيَّةٌ مَرْسومَةٌ حَوْلَ الكُرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17549, 'إِسْعادٌ', 'إسعاد', 'مصدر', 'سعد', 'ءسعاد', 'إسعد', 'مص. أَسْعَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْعادٌ-إِسْعادٌ [س ع د] (مص. أَسْعَدَ). ""عَمِلَ على إِسْعادِهِ"": أَي جَعْلُهُ يَسْعَدُ، سَعيداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17550, 'اِسْتيقاظٌ', 'استيقاظ', 'مصدر', 'يقظ', 'استيقاظ', 'ستقظ', 'مص. اِسْتَيْقَظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتيقاظٌ-اِسْتيقاظٌ [ي ق ظ] (مص. اِسْتَيْقَظَ). ""حاوَلَ اسْتيقاظَهُ"": جَعْلُهُ يَصْحو مِنَ النَّوْمِ، إِيقاظُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17551, 'اِسْتيقانٌ', 'استيقان', 'مصدر', 'يقن', 'استيقان', 'ستقن', 'مص. اِسْتَيْقَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْتيقانٌ-اِسْتيقانٌ [ي ق ن] (مص. اِسْتَيْقَنَ). ""اِسْتيقانُ أمْرٍ"" : التَّأَكُّدُ مِنْ مَعْرِفَةِ حَقيقَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17552, 'إِسْدالٌ', 'إسدال', 'مصدر', 'سدل', 'ءسدال', 'إسدل', 'مص. أَسْدَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْدالٌ-إِسْدالٌ [س د ل] (مص. أَسْدَلَ). ""إِسْدالُ السَّتائِرِ"" : إِنْزالُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17553, 'إِسْداءٌ', 'إسداء', 'مصدر', 'سدي', 'ءسداء', 'إسد', 'مص. أَسْدى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِسْداءٌ-إِسْداءٌ [س د ي] (مص. أَسْدى). 1.""إِسْداءُ النُّصْحِ"": تَقْديمُهُ. 2.""إِسْداءُ الثَّوْبِ"" : تَمْدِيدُ سَداهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17554, 'أَسْرٌ', 'أسر', 'مصدر', 'أسر', 'ءسر', 'سر', 'مص. أَسَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أَسْرٌ-أَسْرٌ (مص. أَسَرَ). 1.""بَقِيَ في الأسْرِ شَهْراً"" : في الحَبْسِ، في السِّجْنِ. ""سَقَطَ في سَلاسِلِ الأسْرِ"". 2.""هُوَ شَديدُ الأسْرِ"": شَديدُ القُوَّةِ. 3.""خُذِ الفاكِهَةَ، هيَ لَكَ بِأَسْرِها"": بِرُمَّتِها، جِميعُها. ""جاءوا بأَسْرِهِمْ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17555, 'إِسْراجٌ', 'إسراج', 'مصدر', 'سرج', 'ءسراج', 'إسرج', 'مص. أَسْرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْراجٌ-إِسْراجٌ [س ر ج] (مص. أَسْرَجَ). 1.""إِسْراجُ الفَرَسِ"": شَدُّ السَّرْجِ عَلَيْهِ. 2.""إِسْراجُ السِّراجِ"" : إِيقادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17556, 'إِسْراعٌ', 'إسراع', 'مصدر', 'سرع', 'ءسراع', 'إسرع', 'مص. أَسْرَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْراعٌ-إِسْراعٌ [س ر ع] (مص. أَسْرَعَ). ""الإِسْراعُ في العَمَلِ"": إِنْجازُهُ بِسُرْعَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17557, 'إِسْرافٌ', 'إسراف', 'مصدر', 'سرف', 'ءسراف', 'إسرف', 'مص. أَسْرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْرافٌ-إِسْرافٌ [س ر ف] (مص. أَسْرَفَ). 1.""بالَغَ في إِسْرافِ ما عِنْدَهُ مِنْ مالٍ"" : تَبْدِيدُهُ وَصَرْفُهُ بِلاَ فائِدَةٍ. 2.""الإٍسْرافُ في الحَديثِ"" : الإِطالَةُ. 3.""الإِسْرافُ في الأَكْلِ"": الإِفْراطُ فِيهِ. ""إِنَّ الإِسْرافَ في الأكْلِ شَرَهٌ وَخِيمُ العَواقِبِ"". (إِسحق الحسيني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17558, 'إِسْراءٌ', 'إسراء', 'مصدر', 'سري', 'ءسراء', 'إسر', 'مص. أَسْرَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِسْراء-إِسْراءٌ [س ر ي] (مص. أَسْرَى). 1.""ما كانَ لِهَذِهِ القافِلَةِ أَنْ تَصِلَ لَوْلاَ إِسْراؤُها لَيْلاً"" : سَيْرُها لَيْلاً. 2.الإسراء آية 1 سُبْحانَ الَّذِي أَسْرى بِعَبْدِهِ لَيْلاً (قرآن) : بِدايَةُ الآيَةِ الأولَى مِنْ سُورَةِ الإسْراءِ. ""الإسْراءُ وَالمِعْراجُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17559, 'إِسْلامٌ', 'إسلام', 'مصدر', 'سلم', 'ءسلام', 'إسلم', 'مص. أَسْلَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"إِسْلامٌ-إِسْلامٌ [س ل م] (مص. أَسْلَمَ).""جاءَ النَّبِيُّ مُحَمَّد بِدِينِ الإِسْلامِ"" : دِينٌ سَماوِيٌّ بَشَّرَ بِهِ الرَّسولُ في مَطْلَعِ القَرْنِ السَّابِعِ المِيلادِيِّ، وَهُوَ قا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17560, 'إِسْعافٌ', 'إسعاف', 'مصدر', 'سعف', 'ءسعاف', 'إسعف', 'مص. أَسْعَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَسْعَفَ). 1.""وَصَلَتْ سَيَّارَةُ الإِسْعافِ إلى مَكانِ الحادِثِ"" : سَيَّارَةٌ عَلَيْها هِلالٌ أَوْ صَليبٌ أَحْمَرُ كَما هُوَّ الشَّأْنُ في أورُوبَّا. تُسْتَخْدَمُ لِنَقْلِ الْمَرْضى وَالْمُصابِينَ في حَوادِثِ السَّيْرِ وَالكَوار"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17561, 'أَسَفٌ', 'أسف', 'مصدر', 'أسف', 'ءسف', 'سف', 'مص. أَسِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أَسَفٌ-أَسَفٌ [أ س ف] (مص. أَسِفَ). 1.""يَا لَلْأَسَفِ ! لَنْ أَسْتَطيعَ تَلْبِيَةَ رَغْبَتِكَ"" : مَعَ كامِلِ الأَسَى وَالتَّحَسُّرِ وَالتَّوَجُّعِ. ""يَا لَلْأَسَفِ ! لَمْ أُخْبَرْ بِمَوْعِدِ الحَفْلَةِ"". 2.""أَسَفِي شَدِيدٌ على ما بَدَرَ مِنِّي"" : نَدَمِي... 3.""أَعْرَبَ عَنْ أَسَفِهِ لِما حَدَثَ"" : عَنْ حُزْنِهِ وَأَلَمِهِ. ""تَلَقَّى خَبَرَ طَرْدِهِ بأَسَفٍ شَدِيدٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17562, 'إِسْفارٌ', 'إسفار', 'مصدر', 'سفر', 'ءسفار', 'إسفر', 'مص. أَسْفَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْفارٌ-إِسْفارٌ [س ف ر] (مص. أَسْفَرَ). 1.""الإِسْفارُ عَنِ الوَجْهِ"" : الكَشْفُ عَنْهُ. 2.""إِسْفارُ الصُّبْحِ"" : إِشْراقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17563, 'إِسْقاطٌ', 'إسقاط', 'مصدر', 'سقط', 'ءسقاط', 'إسقط', 'مص. أَسْقَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْقاطٌ-إِسْقاطٌ [س ق ط] (مص. أَسْقَطَ). 1.""إِسْقاطُ الْمَرْأَةِ لِوَلِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17564, 'إِسْكاتٌ', 'إسكات', 'مصدر', 'سكت', 'ءسكات', 'إسكت', 'مص. أَسْكَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْكاتٌ-إِسْكاتٌ [س ك ت] (مص. أَسْكَتَ). 1.""لاَ حَقَّ لَهُ في إِسْكاتِهِ عِنْدَمَا يُعَبِّرُ عَنْ رَأْيِه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17565, 'إِسْكارٌ', 'إسكار', 'مصدر', 'سكر', 'ءسكار', 'إسكر', 'مص. أَسْكَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْكارٌ-إِسْكارٌ [س ك ر] (مص. أَسْكَرَ). 1.""حاوَلَ إِسْكارَهُ"": جَعْلُهُ يَسْكَرُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17566, 'إِسْكانٌ', 'إسكان', 'مصدر', 'سكن', 'ءسكان', 'إسكن', 'مص. أَسْكَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْكانٌ-إِسْكانٌ [س ك ن] (مص. أَسْكَنَ). ""عَمِلُوا على إِسْكانِ الْمُهاجِرِينَ"" : العَمَل على إِيجادِ مَسْكَنٍ لَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17567, 'إِسْلاسٌ', 'إسلاس', 'مصدر', 'سلس', 'ءسلاس', 'إسلس', 'مص. أَسْلَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْلاسٌ-إِسْلاسٌ [س ل س] (مص. أَسْلَسَ). إِسْلاسُ القِيادِ"" : جَعْلُهُ سَهْلاً سَلِساً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17568, 'إِسْلافٌ', 'إسلاف', 'مصدر', 'سلف', 'ءسلاف', 'إسلف', 'مص. أَسْلَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْلافٌ-إِسْلافٌ [س ل ف] (مص. أَسْلَفَ). ""قَبِلَ إِسْلافَهُ مَبْلَغاً مِنَ المالِ"" : إِقْراضَهُ إِيَّاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17569, 'إشادَةٌ', 'إشادة', 'مصدر', 'شيد', 'ءشادة', 'إشدة', 'مص. أَشادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إشادَةٌ-إشادَةٌ [ش ي د] (مص. أَشادَ). 1.""الإِشادَةُ بِالأعْمالِ"": التَّنْويهُ بِها والثَّناءُ عَلَيْها. 2.""عَصْرُ إشادَةٍ وَتَعْمِيرٍ"": عَصْرُ تَشْيِيدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17570, 'اِسْمِرارٌ', 'اسمرار', 'مصدر', 'سمر', 'اسمرار', 'سمرر', 'مص. اِسْمَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْمِرارٌ-اِسْمِرارٌ [س م ر] (مص. اِسْمَرَّ). ""اِسْمِرارُ الوَجْهِ"" : صَيْرُ لَوْنِهِ ضارِباً إلى السُّمْرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17571, 'إِسْماعٌ', 'إسماع', 'مصدر', 'سمع', 'ءسماع', 'إسمع', 'مص. أَسْمَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْماعٌ-إِسْماعٌ [س م ع] (مص. أَسْمَعَ). ""حاوَلَ إِسْماعَ صَوْتِهِ"": جَعْلُهُ يَصِلُ إلى الآذَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17572, 'إِسْنادٌ', 'إسناد', 'مصدر', 'سند', 'ءسناد', 'إسند', 'مص. أَسْنَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْنادٌ-إِسْنادٌ [س ن د] (مص. أَسْنَدَ). 1.""إِسْنادُ الظَّهْرِ إلى الحائِطِ"": الاتِّكاءُ عَلى الحائِطِ. 2.""الإِسْنادُ في الحَدِيثِ"": هُوَ عِلْمُ نِسْبَتِهِ. 3.""الإسْنادُ ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17573, 'إسْهابٌ', 'إسهاب', 'مصدر', 'سهب', 'ءسهاب', 'إسهب', 'مص. أَسْهَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إسْهابٌ-إسْهابٌ [س هـ ب] (مص. أَسْهَبَ). ""أُسْلوبُهُ فِيهِ إِسْهابٌ"" : التَّوَسُّعُ وَالتَّطْوِيلُ. ""تَحَدَّثَ بِإِسْهابٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17574, 'إِسْهالٌ', 'إسهال', 'مصدر', 'سهل', 'ءسهال', 'إسهل', 'مص. أسْهَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْهالٌ-إِسْهالٌ [س هـ ل] (مص. أسْهَلَ). 1.""عَرَفَ إِسْهالاً على غَيْرِ عادَتِهِ"": ما تَقْذِفُهُ الْمَعِدَةُ والأمْعاءُ سائِلاً جارِياً على غَيْرِ عادَتِها بَدَلاً مِنَ البِرازِ العادِيِّ. 2.""أُصِيبَ بِقَبْضٍ فَتَناوَلَ دَواءَ الإسْهالِ"" : دواءٌ يُسَهِّلُ، يُرَطِّبُ الْمَعِدَةَ مِنْ حالَةِ القَبْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17575, 'إِسْهامٌ', 'إسهام', 'مصدر', 'سهم', 'ءسهام', 'إسهم', 'مص. أَسْهَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِسْهامٌ-إِسْهامٌ [س هـ م] (مص. أَسْهَمَ). ""كانَ إِسْهامُهُ في العَمَلِ إِيجابِيّاً"" : مُشارَكَتُهُ كانَ لَها نَصِيبٌ وافِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17576, 'اِسْوِدادٌ', 'اسوداد', 'مصدر', 'سود', 'اسوداد', 'سدد', 'مص. اِسْوَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِسْوِدادُ-اِسْوِدادُ [س و د] (مص. اِسْوَدَّ). 1.""اِسْوِدادُ الجُدْرانِ"": صَيْرُها سَوْداءَ. 2.""اِسْوِدادُ وَجْهِهِ أَمامَ النَّاسِ"": تَغَيُّرُ سَحْنَتِهِ خَجَلاً أَوْ نَتِيجَةَ فِعْلِ سُوءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17577, 'مُؤَاسَاةٌ', 'مؤاساة', 'مصدر', 'أسي', 'مءاساة', 'مسة', 'مص. آسَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُؤَاسَاةٌ-مُؤَاسَاةٌ [أ س ي] (مص. آسَى). ""جَاءَ لِمُؤَاسَاتِهِ"" : لِعَزَائِهِ وَتَسْلِيَتِهِِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17578, 'إِشاحَةٌ', 'إشاحة', 'مصدر', 'شيح', 'ءشاحة', 'إشحة', 'مص. أَشاحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِشاحَةٌ-إِشاحَةٌ [ش ي ح] (مص. أَشاحَ). ""إِشاحَةُ الوَجْهِ عَنِ الرَّجُلِ"" : الإعْراضُ عَنْهُ في عُبوسٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17579, 'اِشْتِراءٌ', 'اشتراء', 'مصدر', 'شري', 'اشتراء', 'شتر', 'مص. اِشْتَرى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِشْتِراءٌ-اِشْتِراءٌ [ش ر ي] (مص. اِشْتَرى). ""ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17580, 'إشارَة', 'إشارة', 'مصدر', 'شور', 'ءشارة', 'إشرة', 'مص. أَشارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَشارَ). 1.""إِشاراتُ الْمُرورِ"": عَلاماتٌ تَتَضَمَّنُ دَلاَلَةً، أَيْ تَرْمَزُ إلى شَيْءٍ مَّا وَتَدُلُّ عَلَيْهِ. ""إشارَةُ مَنْعِ الوُقوفِ"" ""إِشارَةُ الخَطَرِ"". 2.""هَذَا، هَذِهِ، هَؤُلاءِ"" : مِنْ أَسْماءِ الإِشارَةِ، يُشارُ بِها إلى الاسْمِ. 3."" أَنا رَهْنُ إِشارَتِكَ"" : أَيْ رَهْنُ أَمْرِكَ. 4.""إِنَّ اللَّبِيبَ مِنَ الإِشارَةِ يَفْهَم"" : الإيماءةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17581, 'إشاعَةٌ', 'إشاعة', 'مصدر', 'شيع', 'ءشاعة', 'إشعة', 'مص. أشاعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أشاعَ). ""اِحْذَرِ الإِشاعاتِ، لاَ تُصَدِّقْ كُلَّ شَيْءٍ تَسْمَعُهُ"" : الأَخْبارُ الشَّائِعَةُ غَيْرُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17582, 'إِشْباعٌ', 'إشباع', 'مصدر', 'شبع', 'ءشباع', 'إشبع', 'مص. أَشْبَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِشْباعٌ-إِشْباعٌ [ش ب ع] (مص. أَشْبَعَ). 1.""سَعَى إلى إِشْباعِ الجائِعِينَ"" : إِطْعامِهِمْ حَتَّى يَشْبَعُوا. 2.""قَرَّرَ إشْباعَهُ ضَرْباً"" : ضَرْبُهُ ضَرْباً شَديداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17583, 'اِشْتِياقٌ', 'اشتياق', 'مصدر', 'شوق', 'اشتياق', 'شتق', 'مص. اشْتاقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِشْتِياقٌ-اِشْتِياقٌ [ش و ق] (مص. اشْتاقَ). ""هُوَ في اشْتِياقٍ إلى أَهْلِهِ"": الشُّعورُ بِالشَّوْقِ والرَّغْبَةِ إلى لُقْياهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17584, 'اِشْتِباكٌ', 'اشتباك', 'مصدر', 'شبك', 'اشتباك', 'شتبك', 'مص. اِشْتَبَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِشْتِباكٌ-اِشْتِباكٌ [ش ب ك] (مص. اِشْتَبَكَ). 1.""حَصَلَ اشْتِباكٌ بَيْنَ الْمُتنازِعَيْنَ"": تَضارُبٌ وَخِصامٌ بَيْنَهُما. 2.""اِشْتِباكُ الآراءِ"" : تداخُلُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17585, 'اِشْتِباهٌ', 'اشتباه', 'مصدر', 'شبه', 'اشتباه', 'شتبه', 'مص. اِشْتَبَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِشْتِباهٌ-اِشْتِباهٌ [ش ب هـ] (مص. اِشْتَبَهَ). ""الاشْتِباهُ في الأمْرِ"": الشَّكُّ، وجودُ الْتِباسٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17586, 'اِشْتِدادٌ', 'اشتداد', 'مصدر', 'شدد', 'اشتداد', 'شتدد', 'مص. اِشْتَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِشْتِدادٌ-اِشْتِدادٌ [ش د د] (مص. اِشْتَدَّ). 1.""اِشْتِدادُ النَّهارِ"": عُلُوُّ، ارْتِفاعُ حَرارةِ شَمْسِهِ. ""نَنْصِبُ خَيْمَةً في الظَّهيرَةِ عِنْدَ اشْتِدادِ الحَرِّ"". (أ. أَمين). 2.""لَمْ يَزِدْهُ اشْتِدادُ الْمَرَضِ إلاَّ صَبْراً وَتَحَمُّلاً"" : تَفاقُمُ الْمَرَضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17587, 'اِشْتِراطٌ', 'اشتراط', 'مصدر', 'شرط', 'اشتراط', 'شترط', 'مص. اِشْتَرَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِشْتِراطٌ-اِشْتِراطٌ [ش ر ط] (مص. اِشْتَرَطَ). ""اِشْتِراطُ شُروطٍ جَديدَةٍ.."" إِلْزامُها، فَرْضُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17588, 'اِشْتِراكٌ', 'اشتراك', 'مصدر', 'شرك', 'اشتراك', 'شترك', 'مص. اِشْتَرَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. اِشْتَرَكَ). 1.""دَفَعَ ثَمَنَ الاشْتِراكِ في الجريدَةِ"": دَفَعَ ثَمَنَ الجَريدَةِ لِمُدَّةٍ مُعَيَّنَةٍ لِيَتَوَصَّلَ بِها بانْتِظامٍ بِواسِطَةِ البَريدِ. 2.""سُمِحَ لَهُ بِالاشْتِراكِ في النَّادِي"": لِيَصِيرَ عُضْواً مُشْتَرِكاً في نَشاطِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17589, 'إِشْرابٌ', 'إشراب', 'مصدر', 'شرب', 'ءشراب', 'إشرب', 'مص. أَشْرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِشْرابٌ-إِشْرابٌ [ش ر ب] (مص. أَشْرَبَ). ""فَرَضَ عَلَيْهِ إِشْرابَ الدَّواءِ"" : دَفْعُهُ لِشُرْبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17590, 'اِشْتِعالٌ', 'اشتعال', 'مصدر', 'شعل', 'اشتعال', 'شتعل', 'مص. اِشْتَعَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِشْتِعالٌ-اِشْتِعالٌ [ش ع ل] (مص. اِشْتَعَلَ). 1.""عَرَفَتِ النِّيرانُ اِشْتِعالاً لاَ مَثيلَ لَهُ"" : اِحْتِراقاً. 2.""مادَّةٌ قابِلَةٌ للاشْتِعالِ"" : مُهَيَّأةٌ لِتَشُبَّ فِيهَا النِّيرانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17591, 'اِشْتِغالٌ', 'اشتغال', 'مصدر', 'شغل', 'اشتغال', 'شتغل', 'مص. اِشْتَغَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِشْتِغالٌ-اِشْتِغالٌ [ش غ ل] (مص. اِشْتَغَلَ). 1.""وَجَدَهُ في اشْتِغالٍ دائِمٍ"": في عَمَلٍ. 2.""الاشْتِغالُ في النَّحْوِ"": أَن يَتَقَدَّمَ اسْمٌ وَيَتَأَخَّرَ عَنْهُ فِعْلٌ قَدْ عَمِلَ فِي ضَمِيرِ ذَلِكَ الاسْمِ وَعَائِدٌ إِلَيْهِ. وفي حالَةِ الرَّفْعِ فالفِعْلُ يَشْتَغِلُ عَنِ العَمَلِ في ضمِيرِهِ، وهذَا هو مَعْنى الاشْتِغالِ: ""الدَّرْسُ فَهِمْتُهُ""، ""الضَّيْفُ أَكْرَمْتُ مَقامَهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17592, 'اِشْتِقاقٌ', 'اشتقاق', 'مصدر', 'شقق', 'اشتقاق', 'شتقق', 'مص. اِشْتَقَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِشْتِقاقٌ-اِشْتِقاقٌ [ش ق ق] (مص. اِشْتَقَّ). ""الاشْتِقاقُ في اللُّغَةِ"": أَخْذُ كَلِمَةٍ وَإِخْراجُها مِنْ كَلِمَةٍ أُخْرَى مَعَ تَغْيِيرٍ على أَساسِ الْمُحافَظَةِ على قَرابَتِها مِنَ الْمَعْنَى في اللَّفْظِ مَثَلاً، كَما لَوْ أَخَذْنا مِنْ قَرَأَ : قِراءَةٌ، اِسْتَقْرَأَ، اِسْتِقْراءٌ، قُرَّاءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17593, 'اِشْتِكاءٌ', 'اشتكاء', 'مصدر', 'شكو', 'اشتكاء', 'شتك', 'مص. اِشْتَكَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِشْتِكاءٌ-اِشْتِكاءٌ [ش ك و] (مص. اِشْتَكَى). 1.""جاءَ للاشْتِكاءِ إِلَيْهِ"": تَقْديم شِكايَةٍ. 2.""الاشْتِكاءُ مِنْ أَلَمٍ"" : التَّأَلُّمُ، التَّحَسُّرُ، التَّوَجُّعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17594, 'اِشْتِمالٌ', 'اشتمال', 'مصدر', 'شمل', 'اشتمال', 'شتمل', 'مص. اِشْتَمَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِشْتِمالٌ-اِشْتِمالٌ [ش م ل] (مص. اِشْتَمَلَ). 1.""الاشْتِمالُ بِالثَّوْبِ"": التَّلَفُّفُ بِهِ. 2.""اِشْتِمالُ الْمَوْضوعِ على ثَلاثَةِ فُصُولٍ"": تَضَمُّنُهُ، اِحْتِواؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17595, 'اِشْتِهارٌ', 'اشتهار', 'مصدر', 'شهر', 'اشتهار', 'شتهر', 'مص. اِشْتَهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِشْتِهارٌ-اِشْتِهارٌ [ش هـ ر] (مص. اِشْتَهَرَ). ""اِشْتِهارُهُ في مَجالٍ"": أَيْ شُهْرَتُهُ، كَوْنُهُ مَشْهوراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17596, 'اِشْتِهاءٌ', 'اشتهاء', 'مصدر', 'شهي', 'اشتهاء', 'شته', 'مص. اِشْتَهَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِشْتِهاءٌ-اِشْتِهاءٌ [ش هـ ي] (مص. اِشْتَهَى). ""اِشْتِهاءُ النَّفْسِ إلى.."" : رَغْبَتُها، نُزوعُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17597, 'إشْحاذٌ', 'إشحاذ', 'مصدر', 'شحذ', 'ءشحاذ', 'إشحذ', 'مص. أَشْحَذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إشْحاذٌ-إشْحاذٌ [ش ح ذ] (مص. أَشْحَذَ). ""إِشْحاذُ السِّكِّينِ"": جَعْلُهُ حادّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17598, 'تَأْشِيرَةٌ', 'تأشيرة', 'مصدر', 'أشر', 'تءشيرة', 'تشرة', 'مص. أَشَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْشِيرَةٌ-تَأْشِيرَةٌ [أ ش ر] (مص. أَشَّرَ). 1.""حَصَلَ عَلَى تَأْشِيرَةٍ مِنَ السِّفَارَةِ"" : خَتْمٌ يُوضَعُ عَلَى الجَوَازِ للسَّمَاحِ لِصَاحِبِهِ بِدُخُولِ بَلَدٍ مَّا. 2.""يَحْمِلُ مَعَهُ تَأْشِيرَةَ الْمُرُورِ"" : تَوْقِيعٌ رَسْمِيٌّ يُعْطِي الإِذْنَ بِالْمُرُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17599, 'إِشْراحٌ', 'إشراح', 'مصدر', 'شرح', 'ءشراح', 'إشرح', 'مص. أَشْرَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِشْراحٌ-إِشْراحٌ [ش ر ح] (مص. أَشْرَحَ). ""إِشْراحُ صَدْرِهِ"" : إِفْراحُهُ، إِسْعادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17600, 'إشْراطٌ', 'إشراط', 'مصدر', 'شرط', 'ءشراط', 'إشرط', 'مص. أَشْرَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إشْراطٌ-إشْراطٌ [ش ر ط] (مص. أَشْرَطَ). 1.""إِشْراطُ البَضائِع"": وَضْعُ عَلامَة عَلَيْها، إِعْلاناً أَنَّها لِلْبَيْعِ. 2.""إِشْراطُ الرَّسولِ إِلَيْهِ"" : تَقَديمُهُ إِلَيْهِ، إِعْجالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17601, 'إِشْراعٌ', 'إشراع', 'مصدر', 'شرع', 'ءشراع', 'إشرع', 'مص. أَشْرَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِشْراعٌ-إِشْراعٌ [ش ر ع] (مص. أَشْرَعَ). 1.""إِشْراعُ رُمْحٍ"": تَسْدِيدُهُ. 2.""إِشْراعُ البابِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17602, 'إِشْرافٌ', 'إشراف', 'مصدر', 'شرف', 'ءشراف', 'إشرف', 'مص. أَشْرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِشْرافٌ-إِشْرافٌ [ش ر ف] (مص. أَشْرَفَ). 1.""الإِشْرافُ مِنَ النَّافِذَةِ"": الإِطْلالُ مِنْها. 2.""أُقيمَتْ حَفْلَةٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17603, 'إشْراقٌ', 'إشراق', 'مصدر', 'شرق', 'ءشراق', 'إشرق', 'مص. أَشْرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَشْرَقَ). 1.""إِشْراقُ الشَّمْسِ"": طُلوعُها وَإِضاءتُها. 2."" فَلْسَفَةُ الإِشْراقِ"": فَلْسَفَةٌ قائِمَةٌ على أَساسِ أَنَّ الْمَعْرِفَةَ هي فَيْضٌ مِنَ اللَّهِ بالحِسِّ أو العَقْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17604, 'إِشْراكٌ', 'إشراك', 'مصدر', 'شرك', 'ءشراك', 'إشرك', 'مص. أَشْرَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِشْراكٌ-إِشْراكٌ [ش ر ك] (مص. أَشْرَكَ). 1.""يَوَدُّ إِشْراكَهُ في مَشْروعِهِ"": أَيْ جَعْلَهُ شَريكاً وَمُساهِماً. 2.""الإِشْراكُ بِاللَّهِ"" : الإلْحادُ بِهِ عِنْدَ الاعْتِقادِ بِأَنْ تَجْعَلَ لَهُ شَريكاً في مُلْكِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17605, 'إِشْعاعٌ', 'إشعاع', 'مصدر', 'شعع', 'ءشعاع', 'إشعع', 'مص. أَشَعَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِشْعاعٌ-إِشْعاعٌ [ش ع ع] (مص. أَشَعَّ). 1.""يَقومُ بِإِشْعاعٍ ثَقافِيٍّ"" : بِتَنْويرٍ ثَقافِيّ. 2.""الإِشْعاعُ الذَّرِّيُّ"" : غُبارٌ فَتَّاكٌ يَطيرُ وَيَسيرُ في الفَضا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17606, 'إِشْعارٌ', 'إشعار', 'مصدر', 'شعر', 'ءشعار', 'إشعر', 'مص. أَشْعَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِشْعارٌ-إِشْعارٌ [ش ع ر] (مص. أَشْعَرَ). 1.""اِحْتَفَظَ بِإشْعارِ الوُصولِ"" : بِطاقَةٌ بَريدِيَّةٌ لِلإخْبارِ بِوُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17607, 'إِشْعالٌ', 'إشعال', 'مصدر', 'شعل', 'ءشعال', 'إشعل', 'مص. أَشْعَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِشْعالٌ-إِشْعالٌ [ش ع ل] (مص. أَشْعَلَ). 1.""إِشْعالُ النَّارِ"" : إِيقادُها. 2.""إِشْعالُ الفِتْنَةِ"" : إِثارَتُها، إِيقاظُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17608, 'إِشْغالٌ', 'إشغال', 'مصدر', 'شغل', 'ءشغال', 'إشغل', 'مص. أَشْغَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِشْغالٌ-إِشْغالٌ [ش غ ل] (مص. أَشْغَلَ). ""لَم يَكُنْ يُريدُ إِشْغالَهُ عَنْ مَهامِّهِ"" : إِلْهاؤُهُ، صَرْفُهُ عَنْها، تَحْويلُ نَظَرِهِ عَنْها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17609, 'إِشْفاقٌ', 'إشفاق', 'مصدر', 'شفق', 'ءشفاق', 'إشفق', 'مص. أَشْفَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِشْفاقٌ-إِشْفاقٌ [ش ف ق] (مص. أَشْفَقَ). لم يَكُنْ يَمْلِكُ إِلاَّ الإِشْفاقَ عَلَيْهِ"" : أَي الحُنُوَّ والعَطْفَ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17610, 'إِشْفاءٌ', 'إشفاء', 'مصدر', 'شفي', 'ءشفاء', 'إشف', 'مص. أَشْفَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِشْفاءٌ-إِشْفاءٌ [ش ف ي] (مص. أَشْفَى). ""إِشْفاءُ الْمَريضِ"": عِلاجُهُ بِوَصْفِ دَواءٍ شافٍ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17611, 'إِشْقاءٌ', 'إشقاء', 'مصدر', 'شقي', 'ءشقاء', 'إشق', 'مص. أَشْقَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِشْقاءٌ-إِشْقاءٌ [ش ق ي] (مص. أَشْقَى). 1.""إِشْقاءُ الوَلَدِ"": جَعْلُهُ شَقِيّاً. 2.""إِشْقاءُ الشَّعْرِ"" : تَسْريحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17612, 'إِشْكالٌ', 'إشكال', 'مصدر', 'شكل', 'ءشكال', 'إشكل', 'مص. أَشْكَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَشْكَلَ). ""وَجَدَ في الْمَوْضوعِ إِشْكالاً"": اِلْتِباساً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17613, 'اِشْمِئْزاز', 'اشمئزاز', 'مصدر', 'شمز', 'اشمءزاز', 'شمزز', 'مص. اِشْمَأَزَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِشْمِئْزاز-اِشْمِئْزازٌ [ش م ز] (مص. اِشْمَأَزَّ). ""فِعْلُهُ يُثيرُ الاشْمِئْزازَ"" : أَي التَّقَزُّزَ، الاحْتِقارَ، التَّكَرُّهَ. ""يَنْظُرُ إِلَيْهِ بِكُرْهٍ وَاشْمِئْزازٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17614, 'إِشْهارٌ', 'إشهار', 'مصدر', 'شهر', 'ءشهار', 'إشهر', 'مص. أَشْهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِشْهارٌ-إِشْهارٌ [ش هـ ر] (مص. أَشْهَرَ). 1.""إِشْهارُ أَمْرٍ"": إِظْهارُهُ شَهيراً. 2.""يُقَدِّمُ التَّلْفازُ إِشْهارًا لِمَوادَّ غِذَائِيَّةٍ ... إلخ"" يُقَدِّمُ إِعْلاناً مُشَوِّقاً عَنْها يَجْلُبُ الْمُسْتَهْلِكَ إلى شِرائِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17615, 'إصابَةٌ', 'إصابة', 'مصدر', 'صوب', 'ءصابة', 'إصبة', 'مص. أَصابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَصابَ). 1.""أُصيبَ إِصابَةً بالِغَةٍ في رِجْلِهِ"" : تَعَرَّضَ لِضْرْبَةٍ، لِضَرَرٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17616, 'إِصاتَةٌ', 'إصاتة', 'مصدر', 'صوت', 'ءصاتة', 'إصتة', 'مص. أصاتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِصاتَةٌ-إِصاتَةٌ [ص و ت] (مص. أصاتَ) 1.""إصاتَةُ صَوْتٍ"": إِحْداثُهُ. 2.""الإِصاتَةُ بِالرَّجُلِ"": إِشْهارُهُ بأَمْرٍ لا يَشْتَهيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17617, 'إصْباحٌ', 'إصباح', 'مصدر', 'بصح', 'ءصباح', 'إصبح', 'مص. أَصْبَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إصْباحٌ-إصْباحٌ [ب ص ح] (مص. أَصْبَحَ). ""يَرْتَقِبُ الإِصْباحَ"": أَوَّلَ النَّهارِ. ""ألا أَيُّها اللَّيْلُ الطَّويلُ ألا انْجَلِي*بِصُبْحٍ وَما الإِصْباحُ مِنْكَ بِأَمْثَلِ"" (امرؤ القيْس)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17618, 'إِصْبارٌ', 'إصبار', 'مصدر', 'صبر', 'ءصبار', 'إصبر', 'مص. أَصْبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِصْبارٌ-إِصْبارٌ [ص ب ر] (مص. أَصْبَرَ).1.""حاوَلَ إِصْبارَهُ"": تَصْبيرَهُ، طَلَبَ مِنْه الصَّبْرَ. 2.""إِصْبارُ الطعامِ"" : صَيْرُهُ مُرّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17619, 'اِصْطِحابٌ', 'اصطحاب', 'مصدر', 'صحب', 'اصطحاب', 'صطحب', 'مص. اِصْطَحَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِصْطِحابٌ-اِصْطِحابٌ [ص ح ب] (مص. اِصْطَحَبَ). ""رَغِبَ في اصْطِحابِهِمْ"" : في مُرافَقَتِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17620, 'إِصْحاحٌ', 'إصحاح', 'مصدر', 'صحح', 'ءصحاح', 'إصحح', 'مص. أَصَحَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِصْحاحٌ-إِصْحاحٌ [ص ح ح] (مص. أَصَحَّ). 1.""إِصْحاحُ الْمَريضِ"" : جَعْلُهُ صَحيحاً. 2.""الإصْحاحُ مِنَ التَّوْراةِ والإِنْجيلِ"" : دون السِّفْر، وفوقَ الفَصْلِ مِنْهُما."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17621, 'إِصْحارٌ', 'إصحار', 'مصدر', 'صحر', 'ءصحار', 'إصحر', 'مص. أَصْحَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِصْحارٌ-إِصْحارٌ [ص ح ر] (مص. أَصْحَرَ). 1.""إِصْحارُ السُّكَّانِ"": خُروجُهُمْ إلى الصَّحْراءِ. 2.""إِصْحارُ المكانِ"" : اِتِّساعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17622, 'إِصْحاءٌ', 'إصحاء', 'مصدر', 'صحو', 'ءصحاء', 'إصح', 'مص. أَصْحى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِصْحاءٌ-إِصْحاءٌ [ص ح و] (مص. أَصْحى). 1.""جاءَ لإصْحائِهِ"": لاسْتِيقاظِهِ. 2.""الإِصْحاءُ مِنَ السُّكْرِ"" : التَّنْبيهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17623, 'إِصْداءٌ', 'إصداء', 'مصدر', 'صدأ', 'ءصداء', 'إصد', 'مص. أَصْدَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِصْداءٌ-إِصْداءٌ [ص د أ] (مص. أَصْدَأَ). ""إِصْداءُ الْمَعْدِنِ"" : جَعْلُهُ صَدِئاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17624, 'إِصْدارٌ', 'إصدار', 'مصدر', 'صدر', 'ءصدار', 'إصدر', 'مص. أَصْدَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَصْدَرَ). 1.""إِصْدارُ أَمْرٍ"" : إِعْلانُهُ، إِبْلاغُهُ. 2.""كِتابٌ مِنْ إِصْدارِ دارِ النَّشْرِ كَذَا"": مِن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17625, 'إِصْرارٌ', 'إصرار', 'مصدر', 'صرر', 'ءصرار', 'إصرر', 'مص. أَصَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِصْرارٌ-إِصْرارٌ [ص ر ر] (مص. أَصَرَّ). : ""لَيْسَ هُناكَ ما هُوَ أَسْوَأُ مِنَ الإِصْرارِ على الخَطَأِ"" : التَّشَبُّثُ، الإِمْعانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17626, 'اِصْطِيادٌ', 'اصطياد', 'مصدر', 'صيد', 'اصطياد', 'صطد', 'مص. اِصْطادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِصْطِيادٌ-اِصْطِيادٌ [ص ي د] (مص. اِصْطادَ). ""اِصْطِيادُ الطُّيورِ"": قَنْصُها أو إِيقاعُها في الْمِصْيَدَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17627, 'اِصْطِيافٌ', 'اصطياف', 'مصدر', 'صيف', 'اصطياف', 'صطف', 'مص. اِصْطافَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِصْطِيافٌ-اِصْطِيافٌ [ص ي ف] (مص. اِصْطافَ). ""لِكُلِّ اِصْطِيافٍ مُتْعَتُهُ"" : في أَيِّ مَكانٍ تَقْضي بِهِ الصَّيْفَ لَهُ مُتْعَتُهُ. ""لاَ يَعْرِفُ لِلاصْطِيافِ مَعْنىً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17628, 'اِصْطِباغٌ', 'اصطباغ', 'مصدر', 'صبغ', 'اصطباغ', 'صطبغ', 'مص. اِصْطَبَغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِصْطِباغٌ-اِصْطِباغٌ [ص ب غ] (مص. اِصْطَبَغ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17629, 'إِصْغارٌ', 'إصغار', 'مصدر', 'صغر', 'ءصغار', 'إصغر', 'مص. أَصْغَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِصْغارٌ-إِصْغارٌ [ص غ ر] (مص. أَصْغَرَ). 1.""إِصْغارُ الوَلَدِ"": جَعْلُهُ صَغيراً. 2.""إِصْغارُ الْمُنافِسِ"" : جَعْلُهُ صاغِراً، ذليلاً، مُهاناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17630, 'اِصْطِدامٌ', 'اصطدام', 'مصدر', 'صدم', 'اصطدام', 'صطدم', 'مص. اِصْطَدَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِصْطِدامٌ-اِصْطِدامٌ [ص د م] (مص. اِصْطَدَمَ). ""حَدَثَ اصْطِدامُ سَيَّارَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17631, 'اِصْطِراعٌ', 'اصطراع', 'مصدر', 'صرع', 'اصطراع', 'صطرع', 'مص. اِصْطَرَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِصْطِراعٌ-اِصْطِراعٌ [ص ر ع] (مص. اِصْطَرَعَ). ""اِصْطِراعُ الخَوْفِ في نَفْسِهِ"" : اِحْتِدامُهُ، تَصارُعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17632, 'اصْطِفافٌ', 'اصطفاف', 'مصدر', 'صفف', 'اصطفاف', 'صطفف', 'مص. اِصْطَفَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اصْطِفافٌ-اصْطِفافٌ [ص ف ف] (مص. اِصْطَفَّ). ""اِصْطِفافُ الجُنودِ"" : وُقوفُهُمْ في صَفٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17633, 'اِصْطِفاقٌ', 'اصطفاق', 'مصدر', 'صفق', 'اصطفاق', 'صطفق', 'مص. اِصْطَفَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِصْطِفاقٌ-اِصْطِفاقٌ [ص ف ق] (مص. اِصْطَفَقَ). 1.""اِصْطِفاقُ أَمْواجِ البَحْرِ"" : تَلاطُمُ أَمْواجِهِ وَتَحَرُّكُها، اِصْطِخابُها. 2.""اِصْطِفاقُ القَوْمِ"": اِضْطِرابُهُمْ. 3.""اِصْطِفاقُ الأشْجارِ"": اِهْتِزازُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17634, 'اِصْطِفاءٌ', 'اصطفاء', 'مصدر', 'صفو', 'اصطفاء', 'صطف', 'مص. اِصْطَفَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِصْطِفاءٌ-اِصْطِفاءٌ [ص ف و] (مص. اِصْطَفَى). ""اِصْطِفاءُ الوَلَدِ"": تَفْضيلُهُ، اِخْتِيارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17635, 'اِصْطِكاكٌ', 'اصطكاك', 'مصدر', 'صكك', 'اصطكاك', 'صطكك', 'مص. اِصْطَكَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِصْطِكاكٌ-اِصْطِكاكٌ [ص ك ك] (مص. اِصْطَكَّ). 1.""اِصْطِكاكُ الأسْنانِ"": اِهْتِزازُها، اِصْطِفاقُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17636, 'اِصْطِلاحٌ', 'اصطلاح', 'مصدر', 'صلح', 'اصطلاح', 'صطلح', 'مص. اِصْطَلَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. اِصْطَلَحَ). 1.""اِصْطِلاحُ العُلَماءِ"" : اِتِّفاقُهُمْ على شَيْءٍ مَّا مُحَدَّدٍ. 2.""وَضَعوا قائِم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17637, 'اِصْطِلاءٌ', 'اصطلاء', 'مصدر', 'صلي', 'اصطلاء', 'صطل', 'مص. اِصْطَلى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِصْطِلاءٌ-اِصْطِلاءٌ [ص ل ي] (مص. اِصْطَلى). 1.""الاصْطِلاءُ بالنَّارِ"" : الاسْتِدْفاءُ بِها. 2.""تَجَنَّبَ الاصْطِلاءَ بِنارِهِ"" : تَجَنَّبَ الاقْتِرابَ مِنْهُ أَوِ الاحْتِكاكَ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17638, 'اِصْطِناع', 'اصطناع', 'مصدر', 'صنع', 'اصطناع', 'صطنع', 'مص. اِصْطَنَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِصْطِناع-اِصْطِناعٌ [ص ن ع] (مص. اِصْطَنَعَ). 1.""اِصْطِناعُ آلَةٍ"" : طَلَبُ صُنْعِها. 2.""اِصْطِناعُ صَنِيعَةٍ"" : إِحْسانُها. 3.""اِصْطِناعُ الحَياءِ"" : إِظْهارُ الحَياءِ وَهُوَ مُنْعَدِمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17639, 'إضافَةٌ', 'إضافة', 'مصدر', 'ضيف', 'ءضافة', 'إضفة', 'مص. أَضافَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إضافَةٌ-إضافَةٌ [ض ي ف] (مص. أَضافَ). 1.""إِضافَةُ نُسْخَةٍ جَديدَةٍ إلى الْمَلَفِّ"" : ضَمُّها، إِرْفاقُها. 2.""إِضافَةُ الرَّجُلِ"": إِنْزالُهُ ضَيْفاً. 3.""إِضافَةُ كَلِمَةٍ إلى كَلِمَةٍ"" : نِسْبَتُها، اِرْتِباطُها بِها. 4.""بالإضافَةِ إلى ذَلِكَ يَنْبَغِي..."" : عِلاَوَةً، زِيادَةً. ""كانَ يُزاوِلُ عَمَلاً آخَرَ بالإضافَةِ إلى عَمَلِهِ الرَّسْمِيِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17640, 'إِصْغاءٌ', 'إصغاء', 'مصدر', 'صغو', 'ءصغاء', 'إصغ', 'مص. أَصْغَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِصْغاءٌ-إِصْغاءٌ [ص غ و] (مص. أَصْغَى). ""كانَ في لَحْظَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17641, 'اِصْفِرارٌ', 'اصفرار', 'مصدر', 'صفر', 'اصفرار', 'صفرر', 'مص. اِصْفَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِصْفِرارٌ-اِصْفِرارٌ [ص ف ر] (مص. اِصْفَرَّ). ""يُراقِبُ اصْفِرارَ وَجْهِهِ يَوْماً بَعْدَ يَوْمٍ"" : تَحَوُّلُ لَوْنِ الوَجْهِ بِفِعْلِ التَّعَبِ أَوِ الْمَرَضِ إلى صُفْرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17642, 'إِصْفاقٌ', 'إصفاق', 'مصدر', 'صفق', 'ءصفاق', 'إصفق', 'مص. أًصْفَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِصْفاقٌ-إِصْفاقٌ [ص ف ق] (مص. أًصْفَقَ). 1.""إِصْفاقُ البابِ"" : إِغْلاقُهُ. 2.""إِصْفاقُ الثَّوْبِ"" : جَعْلُهُ صَفيقاً كثيفَ النَّسْجِ. 3.""الإِصْفاقُ على أَمْرٍ مَّا"" : الإِجْماعُ عَلَيْهِ. 4.""إِصْفاق الرَّجُلِ"" : صَرْفُهُ، رَدُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17643, 'إِصْقاعٌ', 'إصقاع', 'مصدر', 'صقع', 'ءصقاع', 'إصقع', 'مص. أَصْقَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِصْقاعٌ-إِصْقاعٌ [ص ق ع] (مص. أَصْقَعَ). 1.""إِصْقاعُ الرَّجُلِ"" : دُخولُهُ في الصّقيعِ. 2.""إِصْقاعُ الْمَكانِ"": إِصابَتُهُ بالصَّقيعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17644, 'تَأْصِيلٌ', 'تأصيل', 'مصدر', 'أصل', 'تءصيل', 'تصل', 'مص. أَصَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْصِيلٌ-تَأْصِيلٌ [أ ص ل] (مص. أَصَّلَ). 1.""تَأْصِيلُ الشَّيْءِ"" : جَعْلُهُ ذَا أَصْلٍ ثَابِتٍ. 2.""تَأْصِيلُ النَّسَبِ"" : تَبْيَانُ أَصْلِهِ وَأَصَالَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17645, 'أَصالَةٌ', 'أصالة', 'مصدر', 'أصل', 'ءصالة', 'صلة', 'مص. أَصُلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"أَصالَةٌ-أَصالَةٌ [أ ص ل] (مص. أَصُلَ). 1.""أَصالَةٌ في الرَّأْيِ"": جَوْدَتُهُ، إِحْكامُهُ. 2.""يَمْتازُ بِأصالَةِ الأسْلوبِ"" : بابْتِكارٍ في الأُسْلوبِ. 3.""أَصالَةُ النَّسَبِ"" : عَراقَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17646, 'إِصْلاحٌ', 'إصلاح', 'مصدر', 'صلح', 'ءصلاح', 'إصلح', 'مص. أَصْلَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَصْلَحَ). 1.""يَقومُ بِإِصْلاحِ السَّاعاتِ"" : يُصْلِحُ عَطَبَها. 2.""قامَ الفَلاَّحونَ بِإِصْلاحِ أَراضيهِمْ"" : تَهْيِئَتُها وَجَعْلُها صالِحَةً لِلزِّراعَةِ. 3.""شَرَعوا في إِصْلاحِ البِنايات"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17647, 'إِضاءةٌ', 'إضاءة', 'مصدر', 'ضوأ', 'ءضاءة', 'إضة', 'مص. أَضاءَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِضاءةٌ-إِضاءةٌ [ض و أ] (مص. أَضاءَ). 1.""إِضاءةُ البَيْتِ"" : إِنارَتُهُ. 2.""إِضاءةُ المِصْباحِ"" : إِشْعالُهُ. 3.""سَعى إلى إِضاءةِ عَقْلِهِ"" : تَنْوِيرِهِ، بَعْثِ النُّورِ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17648, 'إِضاعَةٌ', 'إضاعة', 'مصدر', 'ضيع', 'ءضاعة', 'إضعة', 'مص. أَضاعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِضاعَةٌ-إِضاعَةٌ [ض ي ع] (مص. أَضاعَ).1.""إِضاعَةُ الوَقْتِ"": هَدْرُهُ، تَرْكُهُ يَذْهَبُ سُدىً. 2.""إِضاعَةُ الفُرَصِ"" : تَضْيِيعُها. 3.""إِضاعَةُ المالِ"" : تَبْذِيرُهُ، تَبْدِيدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17649, 'اِضْطِهادٌ', 'اضطهاد', 'مصدر', 'ضهد', 'اضطهاد', 'ضطهد', 'مص. اِضْطَهَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِضْطِهادٌ-اِضْطِهادٌ [ض هـ د] (مص. اِضْطَهَدَ). ""تَعَرَّضَ لِلاضْطِهادِ"" : للمُعامَلَةِ القاسِيَةِ، للقَهْرِ، للجَوْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17650, 'إِضْجارٌ', 'إضجار', 'مصدر', 'ضجر', 'ءضجار', 'إضجر', 'مص. أَضْجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِضْجارٌ-إِضْجارٌ [ض ج ر] (مص. أَضْجَرَ). ""أَرادَ إِضْجارَهُ"": إِزْعاجَهُ، إِقْلاقَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17651, 'إضْجاعٌ', 'إضجاع', 'مصدر', 'ضجع', 'ءضجاع', 'إضجع', 'مص. أَضْجَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إضْجاعٌ-إضْجاعٌ [ض ج ع] (مص. أَضْجَعَ). ""إِضْجاعُ الرَّجُلِ"" : وضْعُ جَنْبِهِ بِالأَرْضِ، اِسْتِلْقاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17652, 'إِضْحاكٌ', 'إضحاك', 'مصدر', 'ضحك', 'ءضحاك', 'إضحك', 'مص. أَضْحَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِضْحاكٌ-إِضْحاكٌ [ض ح ك] (مص. أَضْحَكَ). ""حاوَلَ إضْحاكَهُ"" : حَمْلَهُ على الضَّحِكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17653, 'إِضْرابٌ', 'إضراب', 'مصدر', 'ضرب', 'ءضراب', 'إضرب', 'مص. أَضْرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَضْرَبَ). ""أَعْلَنَ العُمَّالُ الإِضْرابَ"" : تَوَقُّفُ العَمَلِ وَسيلَة ضَغْطٍ إلى أَنْ تُنَفَّذَ الْمَطالِبُ والرَّغَباتُ، الاِمْتِناعُ عَنِ العَمَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17654, 'اِضْطِجاعٌ', 'اضطجاع', 'مصدر', 'ضجع', 'اضطجاع', 'ضطجع', 'مص. اِضْطَجَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِضْطِجاعٌ-اِضْطِجاعٌ [ض ج ع] (مص. اِضْطَجَعَ).""وَجَدَهُ في حالَةِ اضْطِجاعٍ"" : اِسْتِلْقاءٍ، أَيْ وَضْعُ الجَنْبِ بالأرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17655, 'اِضْطِرارٌ', 'اضطرار', 'مصدر', 'ضرر', 'اضطرار', 'ضطرر', 'مص. اِضْطَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِضْطِرارٌ-اِضْطِرارٌ [ض ر ر] (مص. اِضْطَرَّ). ""نَزَلَتِ الطَّائِرَةُ في حالَةِ اضْطِرارٍ"" : الحاجَةُ، الضَّرُورَةُ. ""عِنْدَ الاضْطِرارِ، اِتَّصِلْ بِي هاتِفِيّاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17656, 'اِضْطِرابٌ', 'اضطراب', 'مصدر', 'ضرب', 'اضطراب', 'ضطرب', 'مص. اِضْطَرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِضْطَرَبَ). 1.""أَحْدَثَ الأَوْلادُ اضْطِراباً في الْمَلْعَبِ"": الفَوْضى، الشَّغَب. 2.""شَعَرَ باضْطِرابٍ في مَعِدَتِهِ"" : بِحَرَكَةٍ غَيْرِ عَادِيَّةٍ، بِأَلَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17657, 'اِضْطِرامٌ', 'اضطرام', 'مصدر', 'ضرم', 'اضطرام', 'ضطرم', 'مص. اِضْطَرَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِضْطِرامٌ-اِضْطِرامٌ [ض ر م] (مص. اِضْطَرَمَ). ""اِضْطِرامُ النِّيرانِ"": اِشْتِعَالُها، اِتِّقادُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17658, 'اِضْطِلاعٌ', 'اضطلاع', 'مصدر', 'ضلع', 'اضطلاع', 'ضطلع', 'مص. اِضْطَلَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِضْطِلاعٌ-اِضْطِلاعٌ [ض ل ع] (مص. اِضْطَلَعَ). ""الاِضْطِلاعُ بِالْمَسْؤولِيَّةِ"" : القِيامُ بِها أَحْسَنَ قِيامٍ، النُّهوضُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17659, 'إِطالَةٌ', 'إطالة', 'مصدر', 'طول', 'ءطالة', 'إطلة', 'مص. أَطالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِطالَةٌ-‎إِطالَةٌ [ط و ل] (مص. أَطالَ). ""الإطالَةُ في الحَديثِ لاَ فائِدَةَ مِنْهُ"" : الإطْنابُ فيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17660, 'إِضْعافٌ', 'إضعاف', 'مصدر', 'ضعف', 'ءضعاف', 'إضعف', 'مص. أَضْعَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِضْعافٌ-إِضْعافٌ [ض ع ف] (مص. أَضْعَفَ). 1.""إِضْعافُ قُوَّتِهِ"" : الإِنقاصُ مِنْها، جَعْلُها ضَعيفَةً. 2.""إِضْعاَفُ العَدَدِ"" : جَعْلُهُ ضِعْفَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17661, 'إضْفاءٌ', 'إضفاء', 'مصدر', 'ضفي', 'ءضفاء', 'إضف', 'مص. أَضْفَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إضْفاءٌ-إضْفاءٌ [ض ف ي] (مص. أَضْفَى). 1.""إِضْفاءُ العَطْفِ عَلَيْهِ"" : غَمْرُهُ. 2.""حاوَلَ إِضْفاءَ الجِدِّيَّةِ على عَمَلِهِ"" : إِسْباغَ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17662, 'إِضْلالٌ', 'إضلال', 'مصدر', 'ضلل', 'ءضلال', 'إضلل', 'مص. أَضَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِضْلالٌ-إِضْلالٌ [ض ل ل] (مص. أَضَلَّ). 1.""حَاوَلَ إِضْلالَهُ الطَّريقَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17663, 'اِضْمِحْلالٌ', 'اضمحلال', 'مصدر', 'ضمح', 'اضمحلال', 'ضمحلل', 'مص. اِضْمَحَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِضْمِحْلالٌ-اِضْمِحْلالٌ [ض م ح] (مص. اِضْمَحَلَّ). ""اِضْمِحلالُ القُدْرَةِ"" : ضَعْفُها، تَلاشِيها، تَضاؤُلُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17664, 'إضْمارٌ', 'إضمار', 'مصدر', 'ضمر', 'ءضمار', 'إضمر', 'مص. أَضْمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إضْمارٌ-إضْمارٌ [ض م ر] (مص. أَضْمَرَ). 1.""إِضْمارُ أَمْرٍ"": إِخْفاؤُهُ. 2.""الإضمارُ في العَرُوضِ"" : إِسْكانُ الحَرْفِ الثَّاني من التَّفعيلَة، أي مُتفاعِلُنْ تَصِيرُ مُتْفاعِلُنْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17665, 'إضْناءٌ', 'إضناء', 'مصدر', 'ضني', 'ءضناء', 'إضن', 'مص. أَضْنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إضْناءٌ-إضْناءٌ [ض ن ي] (مص. أَضْنَى). ""عَرَّضَهُ الْمَرَضُ لِلْإِضْناءِ"" : للضَّعْفِ وَالهَلاكِ والتَّعَبِ، للإِرْهاقِ وَالسَّقَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17666, 'إِطاحَةٌ', 'إطاحة', 'مصدر', 'طيح', 'ءطاحة', 'إطحة', 'مص. أَطاحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِطاحَةٌ-إِطاحَةٌ [ط ي ح] (مص. أَطاحَ). ""الإطاحَةُ ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17667, 'طَاعَةٌ', 'طاعة', 'مصدر', 'طوع', 'طاعة', 'طعة', 'مص. أَطَاعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَاعَةٌ-طَاعَةٌ [ط و ع] (مص. أَطَاعَ). 1.""طاعَةُ الْمُعَلِّمِ واجِبَةٌ"" : الْخُضوعُ، الاِنْقِيادُ. ""رَجُلٌ لَمْ يُقَدِّمْ يَداً وَلاَ رِجْلاً حَتَّى يَعْلَمَ أَفِي طَاعَةِ اللَّهِ هُوَ أَمْ فِي مَعْصِيَتِهِ"" ""طَاعَةٌ عَمْيَاءُ"". 2.""يَشُقُّ عَصَا الطَّاعَةِ"" : يَتَمَرَّدُ، يَثُورُ. 3.""سَمْعاً وَطَاعَةً"" : رَهْنَ الإِشَارَةِ، تَحْتَ الأَمْرِ؛ وَالعِبَارَةُ مُخْتَصَرَةٌ : أَيْ ""سَمِعْتُ مَا قُلْتَ وَسَأُطِيعُكَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17668, 'إِطاعَةٌ', 'إطاعة', 'مصدر', 'طوع', 'ءطاعة', 'إطعة', 'مص. أَطاعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِطاعَةٌ-إِطاعَةٌ [ط و ع] (مص. أَطاعَ). ""إِطاعَةُ الوالِدَيْنِ"": الاِنْقِيادُ لَهُما، الاِنْصِياعُ والاِمْتِثالُ لَهُما."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17669, 'إِطْلاقٌ', 'إطلاق', 'مصدر', 'طلق', 'ءطلاق', 'إطلق', 'مص. أَطْلَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِطْلاقٌ-إِطْلاقٌ [ط ل ق] (مص. أَطْلَقَ). 1.""اِسْتَمَرَّ إِطْلاقُ الْمَدافِعِ عَشْرَ دَقائِقَ"" : قَذْفُ البارودِ بِصَوْتٍ مُدَوٍّ. 2.""يُنْتَظَرُ إِطْلاقُ سَراحِ السُّجَناءِ يَومَ العيدِ"" : تَسْرِيحُهُمْ، إِخْراجُهُمْ. 3.""لَنْ أُسافِرَ إِطْلاقاً هَذَا الشَّهْرَ"" : أَبَداً، أَيّاً كانَتِ الأَحْوالُ والظُّروفُ. 4.""لَمْ أَرَ أَحَداً على الإِطْلاقِ"" : دونَ أَيِّ اِسْتِثْناءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17670, 'إِطْباقٌ', 'إطباق', 'مصدر', 'طبق', 'ءطباق', 'إطبق', 'مص. أَطْبَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِطْباقٌ-إِطْباقٌ [ط ب ق] (مص. أَطْبَقَ). 1.""إِطْباقُ الرَّحَى"": وَضْعُ طِبْقِها الأَعْلَى على الأَسْفَلِ. 2.""الإطْباقُ على العَدُوِّ"": الإجْهاز عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17671, 'إِطْرابٌ', 'إطراب', 'مصدر', 'طرب', 'ءطراب', 'إطرب', 'مص. أَطْرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِطْرابٌ-إِطْرابٌ [ط ر ب] (مص. أَطْرَبَ). ""إِطْرابُ الحاضِرينَ"" : إِتْحافُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17672, 'اِطِّرادٌ', 'اطراد', 'مصدر', 'طرد', 'اطراد', 'طرد', 'مص. اِطَّرَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِطِّرادٌ-اِطِّرادٌ [ط ر د] (مص. اِطَّرَدَ). 1.""يُلاحِظُ اطِّرادَ عَمَلِهِ"" : تَناسُقَهُ، تتابُعَهُ. 2.""تَمَنَّى لَه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17673, 'إِطْراءٌ', 'إطراء', 'مصدر', 'طري', 'ءطراء', 'إطر', 'مص. أَطْرى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِطْراءٌ-إِطْراءٌ [ط ر ي] (مص. أَطْرى). ""لاَ يَسْمَعُ مِنْهُ إِلاَّ كَلِماتِ الإِطْراءِ"" : كَلِماتِ الثَّناءِ الْمُبالَغِ فيهِ. ""أَطْراهُ إِطْراءً عَظيماً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17674, 'إِطْعامٌ', 'إطعام', 'مصدر', 'طعم', 'ءطعام', 'إطعم', 'مص. أَطْعَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِطْعامٌ-إِطْعامٌ [ط ع م] (مص. أَطْعَمَ). ""إِطْعامُ الْمَساكِينِ والفُقَراءِ"" : تَقْديمُ الطَّعامِ إِلَيْهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17675, 'إِطْفاءٌ', 'إطفاء', 'مصدر', 'طفأ', 'ءطفاء', 'إطف', 'مص. أَطْفَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِطْفاءٌ-إِطْفاءٌ [ط ف أ] (مص. أَطْفَأَ). 1.""قامَ بِإِطْفاءِ النَّارِ قَبْلَ انْتِشارِها"": إِخْمادِها. 2.""سارَعَ رِجالُ الإِطْفاءِ إلى مَكانِ الحَريقِ"": رِجالُ الْمَطافِىءِ. ن. إِطْفائِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17676, 'إِطْلالٌ', 'إطلال', 'مصدر', 'طلل', 'ءطلال', 'إطلل', 'مص. أَطَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِطْلالٌ-إِطْلالٌ [ط ل ل] (مص. أَطَلَّ). ""الإِطْلالُ مِنَ الشُّرْفَةِ"": الإِشْرافُ مِنْها على..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17677, 'إِطْلاعٌ', 'إطلاع', 'مصدر', 'طلع', 'ءطلاع', 'إطلع', 'مص. أَطْلَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِطْلاعٌ-إِطْلاعٌ [ط ل ع] (مص. أَطْلَعَ). 1.""إِطْلاعُهُ بِأَمْرٍ مَّا"": إِعْلامُهُ بِهِ. 2.""إِطْلاعُ نَجْمٍ"" : ظُهورُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17678, 'اِطِّلاعٌ', 'اطلاع', 'مصدر', 'طلع', 'اطلاع', 'طلع', 'مص. اِطَّلَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِطِّلاعٌ-اِطِّلاعٌ [ط ل ع] (مص. اِطَّلَعَ). 1.""لَهُ اطِّلاعٌ واسِعٌ بِالعُلومِ الحَديثَةِ"" : لَهُ عِلْمٌ وَمَعْرِفَةٌ. 2.""بَعْدَ الاطِّلاعِ على النَّتائِجِ"" : بَعْدَ الوُقوفِ عَلَيْها والتَّمَعُّنِ فيها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17679, 'إِعاقَةٌ', 'إعاقة', 'مصدر', 'عوق', 'ءعاقة', 'إعقة', 'مص. أَعاقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِعاقَةٌ-إِعاقَةٌ [ع و ق] (مص. أَعاقَ). ""الإِعاقَةُ عَنِ العَمَلِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17680, 'اِطْمِئْنانٌ', 'اطمئنان', 'مصدر', 'طمن', 'اطمءنان', 'طمنن', 'مص. اِطْمَأَنَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِطْمِئْنانٌ-اِطْمِئْنانٌ [ط م ن] (مص. اِطْمَأَنَّ). ""عاشَ في اطْمِئْنانٍ كامِلٍ"" : في راحَةٍ وَسُكونٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17681, 'إِطْنابٌ', 'إطناب', 'مصدر', 'طنب', 'ءطناب', 'إطنب', 'مص. أَطْنَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِطْنابٌ-إِطْنابٌ [ط ن ب] (مص. أَطْنَبَ). ""الإِطْنابُ في القَوْلِ"" : الإِكْثارُ فيهِ بِزِيادَةٍ. ""كانَ سَلِسَ العِبارَةِ مَيَّالاً إلى الإِطْنابِ"". (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17682, 'إِظْلالٌ', 'إظلال', 'مصدر', 'ظلل', 'ءظلال', 'إظلل', 'مص. أَظَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِظْلالٌ-إِظْلالٌ [ظ ل ل] (مص. أَظَلَّ). 1.""رَغِبَ في إظْلالِهِ"": في إِدْخالِهِ في ظِلِّهِ، في كَنَفِهِ. 2.""إِظْلالُ شَجَرَةٍ"" : نَشْرُ ظِلِّها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17683, 'إِظْلامٌ', 'إظلام', 'مصدر', 'ظلم', 'ءظلام', 'إظلم', 'مص. أَظْلَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِظْلامٌ-إِظْلامٌ [ظ ل م] (مص. أَظْلَمَ). 1.""إِظْلامُ اللَّيْلِ"" : تَخْيِيمُ ظَلامِ اللَّيْلِ"" 2.""إِظْلامُ الدُّنْيا في عَيْنَيْهِ"" : اِسْوِدادُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17684, 'إِظْهارٌ', 'إظهار', 'مصدر', 'ظهر', 'ءظهار', 'إظهر', 'مص. أَظْهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِظْهارٌ-إِظْهارٌ [ظ هـ ر] (مص. أَظْهَرَ). 1.""إِظْهارُ الحَقيقَةِ"": إِعْلانُها والجَهْرُ بِها. 2.""إِظْهارُ الْمَفاتِنِ"" : الكَشْفُ عَنْها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17685, 'إِعادَةٌ', 'إعادة', 'مصدر', 'عود', 'ءعادة', 'إعدة', 'مص. أعادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِعادَةٌ-إِعادَةٌ [ع و د] (مص. أعادَ). 1.""لاَبُدَّ مِنْ إِعادَةِ النِّظامِ إلى مَجْراهُ الطِّبيعِيِّ"" : إِقامَتُهُ، إِرْجا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17686, 'إعاذَةٌ', 'إعاذة', 'مصدر', 'عوذ', 'ءعاذة', 'إعذة', 'مص. أَعاذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إعاذَةٌ-إعاذَةٌ [ع و ذ] (مص. أَعاذَ). ""الإعاذَةُ بِاللَّهِ"": التَّحْصينُ بِه، الاِعْتِصامُ بِهِ، اللُّجوءُ إِلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17687, 'إِعارَةٌ', 'إعارة', 'مصدر', 'عور', 'ءعارة', 'إعرة', 'مص. أعارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِعارَةٌ-إِعارَةٌ [ع و ر] (مص. أعارَ). ""قانونُ الإِعارَةِ"" : التَّسْليفُ. ""إِعارَةُ الكُتُبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17688, 'إِعاشَةٌ', 'إعاشة', 'مصدر', 'عيش', 'ءعاشة', 'إعشة', 'مص. أَعاشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِعاشَةٌ-إِعاشَةٌ [ع ي ش] (مص. أَعاشَ).: مَا تُقَدِّمُهُ الحكومَةُ أَوِ الْمُنَظَّماتُ الدَّوْلِيّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17689, 'اِعْتِرَاشٌ', 'اعتراش', 'مصدر', 'عرش', 'اعتراش', 'عترش', 'مص. اِعْتَرَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِرَاشٌ-اِعْتِرَاشٌ [ع ر ش] (مص. اِعْتَرَشَ). 1.""اِعْتِراشُ الرَّجُلِ"" : بِناؤُهُ عَريشاً لِيَسْتَظِلَّ بِهِ. 2.""اِعْتِراشُ عناقيدِ العِنَبِ العَريشَ"" : العُلُوُّ عَلَيْهِ، الاِسْتِرْسالُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17690, 'إِعالَةٌ', 'إعالة', 'مصدر', 'عول', 'ءعالة', 'إعلة', 'مص. أَعالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِعالَةٌ-إِعالَةٌ [ع و ل] (مص. أَعالَ). ""إِع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17691, 'إِعانَةٌ', 'إعانة', 'مصدر', 'عون', 'ءعانة', 'إعنة', 'مص. أَعانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَعانَ). ""قَدَّمَ لَهُ الأصْدِقاءُ إِعانَةً مالِيَّةً"" : مُساعَدَةً. ""تَوَصَّلَتِ الجَمْعِيَّةُ بِإِعاناتٍ مُخْتَلِفَةٍ"" ""أَرْسَلَتِ الأُمَمُ الْمُتَّحِدَةُ إِعانَةً طِبِّيَّةً إلى الْمُصابِينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17692, 'اِعْتِيادٌ', 'اعتياد', 'مصدر', 'عيد', 'اعتياد', 'عتد', 'مص. اِعْتادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِيادٌ-اِعْتِيادٌ [ع ي د] (مص. اِعْتاد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17693, 'اِعْتِبارٌ', 'اعتبار', 'مصدر', 'عبر', 'اعتبار', 'عتبر', 'مص. اِعْتَبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِبارٌ-اِعْتِبارٌ [ع ب ر] (مص. اِعْتَبَرَ). 1.""أَخَذَ أَجْوِبَتَهُ بِعَيْنِ الاعْتِبارِ"" : بِعَيْنِ التَّقْديرِ وَالاحْتِرامِ. ""اِعْتِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17694, 'اِعْتِباطٌ', 'اعتباط', 'مصدر', 'عطب', 'اعتباط', 'عتبط', 'مص. اِعْتَبَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِباطٌ-اِعْتِباطٌ [ع ط ب] (مص. اِعْتَبَطَ). ""قامَ بِذَلِكَ اعْتِباطاً"" : دونَ سَبَبٍ أَوْ عِلَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17695, 'اِعْتِدادٌ', 'اعتداد', 'مصدر', 'عدد', 'اعتداد', 'عتدد', 'مص. اِعْتَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِدادٌ-اِعْتِدادٌ [ع د د] (مص. اِعْتَدَّ). ""الاِعْتِدادُ بِالنَّفْسِ"" : الاِفْتِخارُ وَالزَّهْوُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17696, 'اِعْتِدالٌ', 'اعتدال', 'مصدر', 'عدل', 'اعتدال', 'عتدل', 'مص. اِعْتَدَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِدالٌ-اِعْتِدالٌ [ع د ل] (مص. اِعْتَدَلَ). 1.""اِمْتازَ النَّهارُ بِاعْتِدالِ الحَرارَةِ"" : اِنْخِفاضٌ مُتَوَسِّطٌ لا هُوَ بِالحارِّ ولا هُوَ بِالبارِدِ. 2.""يَأْكُلُ بِاعْتِدالٍ تامٍّ"" : دونَ إِفْراطٍ. 3."" مَوْقِفٌ فيهِ اعْتِدالٌ"" : لُيونَةٌ لا تَط"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17697, 'اِعْتِداءٌ', 'اعتداء', 'مصدر', 'عدو', 'اعتداء', 'عتد', 'مص. اِعْتَدى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"(مص. اِعْتَدى). 1.""تَعَرَّضَ لاِعْتِداءٍ وَهُوَ في مَنْزِلِهِ"" : هُجومٌ عُدْوانِيٌّ. 2.""لَيْسَ مِنْ حَقِّهِ الاعْتِداءُ على مِلْكِ الآخَرينَ"" : الاِغْتِصابُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17698, 'اِعْتِذارٌ', 'اعتذار', 'مصدر', 'عذر', 'اعتذار', 'عتذر', 'مص. اِعْتَذَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِذارٌ-اِعْتِذارٌ [ع ذ ر] (مص. اِعْتَذَرَ). ""قَدَّمَ اعْتِذارَهُ"" : عُذْرَهُ، أَي الحُجَّة الَّتي تُقَدَّمُ لِنَفْيِ ذَنْبٍ أو تَبْريرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17699, 'اِعْتِراضٌ', 'اعتراض', 'مصدر', 'عرض', 'اعتراض', 'عترض', 'مص. اِعْتَرَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِعْتَرَضَ). ""اِعْتِراضٌ على الْمَشْروعِ"" : مُعارَضَتُهُ، أي الوُقوفُ ضِدَّهُ. ""أَبْدى اعْتِراضاتِهِ على الْمَشْروعِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17700, 'اِعْتِرافٌ', 'اعتراف', 'مصدر', 'عرف', 'اعتراف', 'عترف', 'مص. اِعْتَرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِعْتَرَفَ). 1.""الاعْتِرافُ بِالخَطَإِ فَضيلَةٌ"" : الإِقرارُ بِهِ. ""لَمْ يَكُنْ أَمامَهُ إِلاَّ الاعْتِرافُ بِكُلِّ ما حَدَثَ"". 2.""مِنْ أَهَمِّ ما يُمَيِّزُ الْمَرْءَ الاعْتِرافُ بِالجَميلِ"" : العِرْفانُ بِما يُسْديهِ غَيْرُكَ إِلَيْكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17701, 'اِعْتِراكٌ', 'اعتراك', 'مصدر', 'عرك', 'اعتراك', 'عترك', 'مص. اِعْتَرَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِراكٌ-اِعْتِراكٌ [ع ر ك] (مص. اِعْتَرَكَ). 1.""وَجَدَهُمْ في اعْتِراكِ"" : في تَقاتُلٍ وَاقْتِتالٍ. 2.""اِعْتِراكُ الجَماعَةِ"" : اِصْطِراعُها، اِصْطِدامُها، تَنازُعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17702, 'اِعْتِراءٌ', 'اعتراء', 'مصدر', 'عري', 'اعتراء', 'عتر', 'مص. اِعْتَرى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِعْتِراءٌ-اِعْتِراءٌ [ع ر ي] (مص. اِعْتَرى). 1.""خافَ مِنِ اِعْتِراءِ الْمَرَضِ"" : مِنْ إِصابَتِهِ. 2."" وَلَّدَ اعْتِراءُ الخَوْفِ لَدَيْهِ إِحْباطاً"" : اِسْتيلاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17703, 'اِعْتِزازٌ', 'اعتزاز', 'مصدر', 'عزز', 'اعتزاز', 'عتزز', 'مص. اِعْتَزَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِزازٌ-اِعْتِزازٌ [ع ز ز] (مص. اِعْتَزَّ). 1.""نَظَرَ بِاعْتِزازٍ إِلى إِبْداعِهِ"" : بِافْتِخارٍ. 2.""اِعْتِزازُ النَّفْسِ"" : إِباؤُها، أَنَفَتُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17704, 'اِعْتِزالٌ', 'اعتزال', 'مصدر', 'عزل', 'اعتزال', 'عتزل', 'مص. اِعْتَزَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِزالٌ-اِعْتِزالٌ [ع ز ل] (مص. اِعْتَزَلَ). 1.""اِعْتِزالُ العَمَلِ"": الاِنْقِطاعُ عَنْهُ، تَرْكُهُ. 2.""الاِعْتِزالُ عَنِ النَّاسِ"" : الاِبْتِعادُ عَنْهُمْ والاِخْتِلاءُ في مَكانٍ بَعيدٍ. 3.""فَلْسَفَةُ الاِعْتِزالِ"" : فَلْسَفَةُ الْمُعْتَزِلَة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17705, 'اِعْتِزامٌ', 'اعتزام', 'مصدر', 'عزم', 'اعتزام', 'عتزم', 'مص. اِعْتَزَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِزامٌ-اِعْتِزامٌ [ع ز م] (مص. اِعْتَزَمَ). ""أَعْلَنَ عَنِ اعْتِزامِهِ لِخَوْضِ الْمَعْرَكَةِ"" : عَنْ عَزْمِهِ وَعَقْدِهِ النِّيَّةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17706, 'اِعْتِشابٌ', 'اعتشاب', 'مصدر', 'عشب', 'اعتشاب', 'عتشب', 'مص. اِعْتَشَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِشابٌ-اِعْتِشابٌ [ع ش ب] (مص. اِعْتَشَبَ). ""اِعْتِشابُ الماشِيَةِ"" : رَعْيُها العُشْبَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17707, 'اِعْتِصابٌ', 'اعتصاب', 'مصدر', 'عصب', 'اعتصاب', 'عتصب', 'مص. اِعْتَصَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِصابٌ-اِعْتِصابٌ [ع ص ب] (مص. اِعْتَصَبَ). 1.""اِعْتِصابُ قَوْمٍ"" : صَيْرُهُمْ عُصْبَةً، جَماعَةً. 2.""اِعْتِصابُ الرَّجُلِ"" : شَدُّهُ العِصابَةَ أوْ وَضْعُ العِمَامَةِ على رَأْسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17708, 'اِعْتِصارٌ', 'اعتصار', 'مصدر', 'عصر', 'اعتصار', 'عتصر', 'مص. اِعْتَصَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِصارٌ-اِعْتِصارٌ [ع ص ر] (مص. اِعْتَصَرَ). ""اِعْتِصارُ الثَّوْبِ"": عَصْرُهُ، أي الضَّغْطُ عَلَيْهِ لإخْراجِ الماءِ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17709, 'اِعْتِصامٌ', 'اعتصام', 'مصدر', 'عصم', 'اعتصام', 'عتصم', 'مص. اِعْتَصَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِصامٌ-اِعْتِصامٌ [ع ص م] (مص. اِعْتَصَمَ). 1.""الاِعْتِصامُ بِاللَّهِ"" : الاِحْتِماءُ والاِلْتِجاءُ إِلَيْهِ. 2.""قَرَّروا الاِعْتِصامَ بِداخِلِ الْمَعْمَلِ"" : الاِلْتِجاءُ إلى داخِلِ الْمَعْمَلِ والاعْتِكافُ بِهِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17710, 'اِعْتِقادٌ', 'اعتقاد', 'مصدر', 'عقد', 'اعتقاد', 'عتقد', 'مص. اِعْتَقَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِقادٌ-اِعْتِقادٌ [ع ق د] (مص. اِعْتَقَدَ). 1.""اِعْتِقادُ الرَّجُلِ"" : تَدَيُّنُهُ بِعَقيدَةٍ. 2.""كانَ اعْتِقادُهُ عَكْسَ ما ذَهَبَ إِلَيْهِ"" : ظَنُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17711, 'اِعْتِقالٌ', 'اعتقال', 'مصدر', 'عقل', 'اعتقال', 'عتقل', 'مص. اِعْتَقَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِقالٌ-اِعْتِقالٌ [ع ق ل] (مص. اِعْتَقَلَ). 1.""ما يَزالُ رَهْنَ الاِعْتِقالِ"" : رَهْنَ الأسْرِ، الحَبْسِ. 2.""مُعَسْكَرُ الاِعْتِقالِ"" : مَكانٌ يُحْبَسُ فيهِ الْمُعْتَقَلونَ السِّياسِيُّونَ وَأَسْرى الحَرْبِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17712, 'اِعْتِكافٌ', 'اعتكاف', 'مصدر', 'عكف', 'اعتكاف', 'عتكف', 'مص. اِعْتَكَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِكافٌ-اِعْتِكافٌ [ع ك ف] (مص. اِعْتَكَفَ). 1.""اِسْتَمَرَّ اعْتِكافُهُ في البَيْتِ زَمَناً طَويلاً"": لُزومُهُ وَإِقامتُهُ فيهِ.. 2.""الاِعْتِكافُ على تَحْصيلِ العِلْمِ"" : التَّفَرُّغُ لهُ، وَعَدَمُ الاِنْصِرافِ عنه."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17713, 'اِعْتِلالٌ', 'اعتلال', 'مصدر', 'علل', 'اعتلال', 'عتلل', 'مص. اِعْتَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِلالٌ-اِعْتِلالٌ [ع ل ل] (مص. اِعْتَلَّ). ""بِهِ اعْتِلالٌ"" : بِهِ مَرَضٌ نَتيجَة عِلَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17714, 'اِعْتِلاءٌ', 'اعتلاء', 'مصدر', 'علي', 'اعتلاء', 'عتل', 'مص. اِعْتَلَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِعْتِلاءٌ-اِعْتِلاءٌ [ع ل ي] (مص. اِعْتَلَى). 1.""اِعْتِلاءُ شَجَرَةٍ"": تَسَلُّقُها. 2.""اِعْتِلاءُ العَرْشِ"" : التّرَبُّعُ والجلوسُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17715, 'اِعْتِمادٌ', 'اعتماد', 'مصدر', 'عمد', 'اعتماد', 'عتمد', 'مص. اِعْتَمَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِمادٌ-اِعْتِمادٌ [ع م د] (مص. اِعْتَمَدَ). 1.""الاِعْتِمادُ على النَّفْسِ فَضيلَةٌ"" : الاِتِّكالُ عَلَيْها والثِّقَةُ بِإِمْكاناتِها. 2.""خَصَّصُوا اعْتِماداً مالِيّاً لِمَشْروعٍ ثَقافِيٍّ"" : قَدْراً مِنَ المالِ يُرْصَدُ لِذَلِكَ. 3.""قَدَّمَ السَّفيرُ أَوْراقَ اعْتِمادِهِ"" : أَوْراقٌ رَسْمِيَّةٌ يُقَدِّمُها السَّفيرُ لِرَئيسِ الدَّوْلَةِ الَّتي يُعَيَّنُ فيها لإِقامَةِ سِفارَتِهِ وَتَمْثيلِ بِلادِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17716, 'اِعْتِمارٌ', 'اعتمار', 'مصدر', 'عمر', 'اعتمار', 'عتمر', 'مص. اِعْتَمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِمارٌ-اِعْتِمارٌ [ع م ر] (مص. اِعْتَمَرَ). 1.""اِعْتِمارُ الْمُسْلِمِ"": تَأْدِيَتُهُ لِلْعُمْرَةِ. 2.""اِعْتِمارُ الشَّيْخِ"" : تَعَمُّمُهُ بِالعِمامَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17717, 'اِعْتِناقٌ', 'اعتناق', 'مصدر', 'عنق', 'اعتناق', 'عتنق', 'مص. اِعْتَنَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْتِناقٌ-اِعْتِناقٌ [ع ن ق] (مص. اِعْتَنَقَ). ""اِعْتِناقُ الإسْلامِ"" : اِخْتِيارُهُ عَقيدَةً دينِيَّةً، اِتِّباعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17718, 'اِعْتِناءٌ', 'اعتناء', 'مصدر', 'عني', 'اعتناء', 'عتن', 'مص. اِعْتَنى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِعْتِناءٌ-اِعْتِناءٌ [ع ن ي] (مص. اِعْتَنى). ""كانَ مَحَلَّ اعْتِناءٍ"": مَحَلَّ اهْتِمامٍ، اِحْتِفالٍ. ""لَقِيَ كُلَّ رِعايَةٍ وَاِعْتِناءٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17719, 'إِعْشَابٌ', 'إعشاب', 'مصدر', 'عشب', 'ءعشاب', 'إعشب', 'مص. أعْشَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِعْشَابٌ-إِعْشَابٌ [ع ش ب] (مص. أعْشَبَ). 1. ""إعْشَابُ الأرْضِ"" : إنْبَاتُها العُشْبَ. 2. ""إعْشَابُ الْمَاشِيَةِ"" : رَعْيُها العُشْبَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17720, 'إِعْجابٌ', 'إعجاب', 'مصدر', 'عجب', 'ءعجاب', 'إعجب', 'مص. أُعْجِبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِعْجابٌ-إِعْجابٌ [ع ج ب] (مص. أُعْجِبَ). ""أَثارَ إِعْجابَهُ"": الشُّعورُ بِالسُّرورِ والاِنْبِساطِ عِنْدَ ظُهورِ ما هُوَ حَسَنٌ وَجَميلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17721, 'إِعْجازٌ', 'إعجاز', 'مصدر', 'عجز', 'ءعجاز', 'إعجز', 'مص. أَعْجَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِعْجازٌ-إِعْجازٌ [ع ج ز] (مص. أَعْجَزَ). ""إِعْجازُ القُرْآنِ"": مَعانيهِ البَليغَةُ‏ بِأَبْلَغِ الأساليبِ مِمَّا يَعْجِزُ عَنْهُ النَّاسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17722, 'إعْجافٌ', 'إعجاف', 'مصدر', 'عجف', 'ءعجاف', 'إعجف', 'مص. أَعْجَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إعْجافٌ-إعْجافٌ [ع ج ف] (مص. أَعْجَفَ). ""إِعْجافُ الدَّابَّةِ"" : إِضْعافُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17723, 'إِعْجامٌ', 'إعجام', 'مصدر', 'عجم', 'ءعجام', 'إعجم', 'مص. أَعْجَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِعْجامٌ-إِعْجامٌ [ع ج م] (مص. أَعْجَمَ). 1.""إِعْجامُ الكَلامِ"": إِبْهامُهُ. 2.""إِعْجامُ الكِتابِ"" : إِزالَةُ إِبْهامِهِ. 3.""إِعْجامُ البابِ"" : إِغْلاقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17724, 'إِعْدادٌ', 'إعداد', 'مصدر', 'عدد', 'ءعداد', 'إعدد', 'مص. أَعَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِعْدادٌ-إِعْدادٌ [ع د د] (مص. أَعَدَّ). ""قامَ بإِعْدادِ الشَّايِ لِلضُّيوفِ"" : تَهْيِيؤُهُ، تَحْضيرُهُ. ""تَكَلَّفَ أَحَدُهُما بِإعْدَادِ الحَلْوى وَالآخَرُ بِإعْدادِ الطَّعامِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17725, 'إِعْدامٌ', 'إعدام', 'مصدر', 'عدم', 'ءعدام', 'إعدم', 'مص. أَعْدَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِعْدامٌ-إِعْدامٌ [ع د م] (مص. أَعْدَمَ). 1.""إِعْدامُ الرَّجُلِ"" : اِفْتِقارُهُ. 2.""حُكِمَ عَلَيْهِ بِالإعْدامِ"" : عُقوبَةُ الْمَوْتِ رَمْياً بِالرَّصاصِ أو شَنْقاً، أَوْ صَعْقاً بِواسِطَةِ الكُرْسِيِّ الكَهْرَبائِيِّ كَما في أَمْريكا. ""تُطالِبُ مُنَظَّماتُ حُقوقِ الإِنْسانِ بِإِلْغاءِ عُقوبَةِ الإِعْدامِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17726, 'إِعْرابٌ', 'إعراب', 'مصدر', 'عرب', 'ءعراب', 'إعرب', 'مص. أَعْرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِعْرابٌ-إِعْرابٌ [ع ر ب] (مص. أَعْرَبَ). 1.""الإعْرابُ عَنِ الفَرَحِ والسُّرورِ"" : التَّعْبيرُ، الإفْصاحُ. ""الإعْرابُ عَنِ السُّخْطِ"". 2.""إِعْرابُ كَلِمَاتِ الجُمْلَةِ"" : تَبْيَانُ وَظِيفَتِهَا النَّحْوِيَّةِ حَسَبَ مَوْقِعِهَا فِي الجُمْلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17727, 'إعْرَاضٌ', 'إعراض', 'مصدر', 'عرض', 'ءعراض', 'إعرض', 'مص. أعْرَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إعْرَاضٌ-إعْرَاضٌ [ ع ر ض] (مص. أعْرَضَ). ""لَمْ يَعْرِفْ سَبَبَ إعْرَاضِهِ"" : صُدُودِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17728, 'إعْزَازٌ', 'إعزاز', 'مصدر', 'عزز', 'ءعزاز', 'إعزز', 'مص. أعَزَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إعْزَازٌ-إعْزَازٌ [ع ز ز] (مص. أعَزَّ). ""يُكِنُّ لَهُ إعْزَازاً "" : حُبّاً، مَحَبَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17729, 'إِعْلاءٌ', 'إعلاء', 'مصدر', 'علو', 'ءعلاء', 'إعل', 'مص. أعْلَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِعْلاءٌ-إِعْلاءٌ [ع ل و] (مص. أعْلَى). ""إعْلاَءُ مَقامِهِ"" : الرَّفْعُ مِنْهُ، أَيْ جَعْلُهُ عَالِياً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17730, 'اِعْشِيشَابٌ', 'اعشيشاب', 'مصدر', 'عشب', 'اعشيشاب', 'عششب', 'مص. اِعْشَوْشَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْشِيشَابٌ-اِعْشِيشَابٌ [ع ش ب] (مص. اِعْشَوْشَبَ). ""اِعْشِيشَابُ الحُقُولِ"" : كَثْرَةُ العُشْبِ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17731, 'إعْطَابٌ', 'إعطاب', 'مصدر', 'عطب', 'ءعطاب', 'إعطب', 'مص. أعْطَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إعْطَابٌ-إعْطَابٌ [ع ط ب] (مص. أعْطَبَ). ""إعْطَابُ الرَّجُلِ"" : إصَابَتُهُ بِعَطَبٍ، بِضَرَرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17732, 'إعْطَاشٌ', 'إعطاش', 'مصدر', 'عطش', 'ءعطاش', 'إعطش', 'مص. أعْطَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إعْطَاشٌ-إعْطَاشٌ [ع ط ش] (مص. أعْطَشَ). ""إعْطَاشُ الرَّجُلِ"" : جَعْلُهُ فِي عَطَشٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17733, 'إعْطَاءٌ', 'إعطاء', 'مصدر', 'عطي', 'ءعطاء', 'إعط', 'مص. أعْطَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إعْطَاءٌ-إعْطَاءٌ [ع ط ي] (مص. أعْطَى). ""لاَ يَرْغَبُ فِي إعْطَائِهِ أكْثَرَ مِمَّا يَسْتَحِقُّ"" : مَنْحُهُ، أَيْ تَقْدِيمُ عَطَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17734, 'إعْفاءٌ', 'إعفاء', 'مصدر', 'عفو', 'ءعفاء', 'إعف', 'مص. أعْفَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إعْفاءٌ-إعْفاءٌ [ع ف و] (مص. أعْفَى). 1. ""قَرَّرَ إعْفَاءهُ مِنْ مَنْصِبِهِ"" : تَنْحِيَتَهُ، إزَالَتَهُ، أَيِ الاِسْتِغْنَاءَ عَنْ خَدَمَاتِهِ. 2. ""مِنَ الصَّعْبِ الإعْفَاءُ مِنَ الخِدْمَةِ العَسْكَرِيَّةِ"" : الإذْنُ بِعَدَم أَدَائِهَا وَالقِيامِ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17735, 'إعْقَامٌ', 'إعقام', 'مصدر', 'عقم', 'ءعقام', 'إعقم', 'مص. أعْقَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إعْقَامٌ-إعْقَامٌ [ع ق م] (مص. أعْقَمَ). ""إِعْقَامُ الْمَرْأةِ"" : جَعْلُها عَقِيماً لا تَلِدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17736, 'إعْلاَلٌ', 'إعلال', 'مصدر', 'علل', 'ءعلال', 'إعلل', 'مص. أعَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إعْلاَلٌ-إعْلاَلٌ [ع ل ل] (مص. أعَلَّ). 1. ""بِهِ إعْلاَلٌ"": عِلَّةٌ، سَقَمٌ، مَرَضٌ. 2.: الإعْلاَلُ فِي النَّحْوِ هُوَ تَغْييرُ أحَدِ أحْرُفِ العِلَّةِ (ا، و، ي) حَذْفاً أوْ قَلْباً أوْ تَسْكِيناً (بيع: باعَ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17737, 'إعْلاَمٌ', 'إعلام', 'مصدر', 'علم', 'ءعلام', 'إعلم', 'مص. أَعْلَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إعْلاَمٌ-إعْلاَمٌ [ع ل م] (مص. أَعْلَمَ). 1. ""لاَ بُدَّ مِنْ إِعْلاَمِ الجُمْهُورِ بِالحَقِيقَةِ"" : إخْبَارُهُ، أنْ يَكُونَ عَلَى عِلْمٍ وَمَعْرِفَةٍ. 2.""أصْدَرَتْ وِزارَةُ الإعْلاَمِ بَيَاناً"" : وِزارَةُ الأنْبَاءِ. 3.""تَطَوَّرَتْ وَسَائِلُ الإعْلاَمِ فِي العَصْرِ الحَدِيثِ"" : وَسَائِلُ الاتِّصَالِ وَتَبَادُلِ الْمَعْلُومَاتِ والأخْبَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17738, 'إعْلاَنٌ', 'إعلان', 'مصدر', 'علن', 'ءعلان', 'إعلن', 'مص. أعْلَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أعْلَنَ). 1.""الإعْلاَنُ عَنْ خَبَرٍ"" : إذَاعَتُهُ، نَشْرُهُ. 2. ""إعْلانُ الحَرْبِ"" : شَنُّها، إشْعَالُهَا. 3. ""إِعْلاَنُ حَقِيقَةٍ"" : الجَهْرُ بِهَا. 4. ""نَشَرَتِ الشَّرِكَةُ إعْلاناً تِجَارِيّاً فِي الصَّحَافَةِ"" : إشْهَاراً، بَيَاناً تُعْلِنُ فِيهِ عَنْ سِلْعَةٍ أوْ بَيَانٍ يَتَضَمَّنُ مَعْلُومَاتٍ للِتَّرْوِيجِ لَهَا. 5. ""هَذِهِ اللَّوْحَةُ خَاصَّةٌ بِالإعْلاَناتِ"" : بِالبَيَانَاتِ أَوِ الإعْلاَنَاتِ الإدَارِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17739, 'إِغاثَةٌ', 'إغاثة', 'مصدر', 'غوث', 'ءغاثة', 'إغثة', 'مص. أَغاثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِغاثَةٌ-إِغاثَةٌ [غ و ث] (مص. أَغاثَ).""جَاءُوا لإغا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17740, 'إِعْمَادٌ', 'إعماد', 'مصدر', 'عمد', 'ءعماد', 'إعمد', 'مص. أعْمَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِعْمَادٌ-إِعْمَادٌ [ع م د] (مص. أعْمَدَ). ""إعْمَادُ البِنَاءِ"" : جَعَلَ لَهُ عِماداً يُسْنَدُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17741, 'إعْمَارٌ', 'إعمار', 'مصدر', 'عمر', 'ءعمار', 'إعمر', 'مص. أَعْمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إعْمَارٌ-إعْمَارٌ [ع م ر] (مص. أَعْمَرَ). 1. ""إعْمَارُ الْمَنْزِلِ"" : جَعْلُهُ آهِلاً. 2. ""إِعْمَارُ الأَرْضِ"" : وُجُودُها عَامِرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17742, 'إعْمَالٌ', 'إعمال', 'مصدر', 'عمل', 'ءعمال', 'إعمل', 'مص. أعْمَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إعْمَالٌ-إعْمَالٌ [ع م ل] (مص. أعْمَلَ). 1. ""إِعْمَالُ الرَّجُلِ"": جَعْلُهُ عَامِلاً. 2. ""إعْمَالُ الفِكْرِ"" : إشْغَالُهُ، أيْ جَعْلُهُ يُفَكِّرُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17743, 'إعْمَاءٌ', 'إعماء', 'مصدر', 'عمي', 'ءعماء', 'إعم', 'مص. أعْمَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إعْمَاءٌ-إعْمَاءٌ [ع م ي] (مص. أعْمَى). ""إعْمَاءُ الرَّجُلِ"" : تَصْييرُهُ أعْمَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17744, 'إعْنَادٌ', 'إعناد', 'مصدر', 'عند', 'ءعناد', 'إعند', 'مص. أعْنَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إعْنَادٌ-إعْنَادٌ [ع ن د] (مص. أعْنَدَ). ""أَظْهَرَ إعْنَاداً"": مُعَارَضَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17745, 'اِعْوِجَاجٌ', 'اعوجاج', 'مصدر', 'عوج', 'اعوجاج', 'عجج', 'مص. اِعْوَجَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْوِجَاجٌ-اِعْوِجَاجٌ [ع و ج] (مص. اِعْوَجَّ). ""بِهِ اعْوِجَاجٌ"": اِلْتِوَاءٌ، اِنْحِناءٌ، اِنْثِنَاءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17746, 'اِعْوِرارٌ', 'اعورار', 'مصدر', 'عور', 'اعورار', 'عرر', 'مص. اِعْوَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْوِرارٌ-اِعْوِرارٌ [ع و ر] (مص. اِعْوَرَّ). 1. ""اِعْوِرارُ العَيْنِ"": ذَهَابُ بَصَرِها. 2. ""اِعْوِرَارُ الرَّجُلِ"" : ذَهابُ بَصَرِ إحْدَى عَيْنَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17747, 'اِعْوِزَازٌ', 'اعوزاز', 'مصدر', 'عوز', 'اعوزاز', 'عزز', 'مص. اِعْوَزَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِعْوِزَازٌ-اِعْوِزَازٌ [ع و ز] (مص. اِعْوَز"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17748, 'إعْياءٌ', 'إعياء', 'مصدر', 'عيي', 'ءعياء', 'إع', 'مص. أعْيا', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إعْياءٌ-إعْياءٌ [ع ي ي] (مص. أعْيا). ""شَعَرَ بِإعْياءٍ شَدِيدٍ"" : بِتَعَبٍ، بِإرْهَاقٍ. ""أخَذَ مِنْهُ الإعْيَاءُ مَأْخَذاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17749, 'اِغْتِسَالٌ', 'اغتسال', 'مصدر', 'غسل', 'اغتسال', 'غتسل', 'مص. اِغْتَسَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِغْتِسَالٌ-اِغْتِسَالٌ [غ س ل] (مص. اِغْتَسَلَ). ""اِغْتِسَالُ البَدَنِ"": غَسْلُهُ وَتَنْظِيفُهُ بِالْمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17750, 'غَارَةٌ', 'غارة', 'مصدر', 'غور', 'غارة', 'غرة', 'مص. أَغَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَغَارَ). 1.""شَنَّ الغَارَةَ عَلَيْهِمْ"" : شَنَّ الْهُجُومَ عَلَيْهِمْ مِنْ كُلِّ جِهَةٍ وَفَرَّقَ جَمْعَهُمْ. 2."""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17751, 'إغَارَةٌ', 'إغارة', 'مصدر', 'غير', 'ءغارة', 'إغرة', 'مص. أغَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أغَارَ). ""شَنُّوا إغَارَةً عَلَى مَوَاقِعِ العَدُوِّ"" : هُجُوماً. ""قَامَتْ طَائِرَاتُ العَدُوِّ بِعِدَّةِ إغَارَاتٍ جَوِّيَّةٍ هَذَا العَامَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17752, 'إغَاظَةٌ', 'إغاظة', 'مصدر', 'غيظ', 'ءغاظة', 'إغظة', 'مص. أغَاظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إغَاظَةٌ-إغَاظَةٌ [غ ي ظ] (مص. أغَاظَ). ""إغَاظَةُ الرَّجُلِ"" : حَمْلُهُ عَلَى الغَيْظِ والحَنَقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17753, 'اِغبِرَارٌ', 'اغبرار', 'مصدر', 'غبر', 'اغبرار', 'غبرر', 'مص. اِغْبَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِغبِرَارٌ-اِغبِرَارٌ [غ ب ر] (مص. اِغْبَرَّ). ""اِغْبِرَارُ الأثاثِ"" : اِنْتِشَارُ الغُبَارِ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17754, 'اِغْتِيَابٌ', 'اغتياب', 'مصدر', 'غيب', 'اغتياب', 'غتب', 'مص. اِغْتَابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِغْتِيَابٌ-اِغْتِيَابٌ [غ ي ب] (مص. اِغْتَابَ). ""نَهَاهُ عِنِ الاِغْتِيَابِ"" : أي الت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17755, 'اِغْتِبَاطٌ', 'اغتباط', 'مصدر', 'غبط', 'اغتباط', 'غتبط', 'مص. اِغْتَبَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِغْتِبَاطٌ-اِغْتِبَاطٌ [غ ب ط] (مص. اِغْتَبَطَ). ""شَعَرَ بِاغْتِبَاطٍ لِمَا لَقِيَهُ مِنْ حُسْنِ الحَفَاوَةِ"" : اِرْتِيَاحٌ وَسُرُورٌ وَمَسَرَّةٌ، حُسْنُ الحَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17756, 'اِغْتِرَارٌ', 'اغترار', 'مصدر', 'غرر', 'اغترار', 'غترر', 'مص. اِغْتَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِغْتِرَارٌ-اِغْتِرَارٌ [غ ر ر] (مص. اِغْتَرَّ). ""اِغْتِرَارُ الوَلَدِ"" : شُعُورُهُ بِالغُرُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17757, 'اِغْتِرَابٌ', 'اغتراب', 'مصدر', 'غرب', 'اغتراب', 'غترب', 'مص. اِغْتَرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِغْتِرَابٌ-اِغْتِرَابٌ [غ ر ب] (مص. اِغْتَرَبَ). 1. ""كَيْفَ يُمْكِنُ أنْ يُفَسِّرَ اغْتِرَابَهُ "" : هِجْرَتَهُ البَعِيدَةَ. ""قَضَى جُلَّ حَيَاتِهِ فِي اغْتِرَابٍ"". 2. ""اِغْتِرَابُ النَّفْسِ"" : شُعُورُهَا بِالضَّيَاعِ وَالاسْتِلابِ. ""اِغْتِرَابُ الإنْسَانِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17758, 'اِغْتِرَافٌ', 'اغتراف', 'مصدر', 'غرف', 'اغتراف', 'غترف', 'مص. اِغْتَرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِغْتِرَافٌ-اِغْتِرَافٌ [غ ر ف] (مص. اِغْتَرَفَ). 1. ""اِغْتِرَافُ الْمَاءِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17759, 'إغْمَادٌ', 'إغماد', 'مصدر', 'غمد', 'ءغماد', 'إغمد', 'مص. أَغْمَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إغْمَادٌ-إغْمَادٌ [غ م د] (مص. أَغْمَدَ). ""إغْمَادُ السَّيْفِ"" : إدْخَالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17760, 'اِغْتِصَابٌ', 'اغتصاب', 'مصدر', 'غصب', 'اغتصاب', 'غتصب', 'مص. اِغْتَصَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِغْتِصَابٌ-اِغْتِصَابٌ [غ ص ب] (مص. اِغْتَصَبَ). 1.""اِغْتِصَابُ مَالِ النَّاسِ"" : أَخْذُهُ قَهْراً وَظُلْماً. 2. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17761, 'اِغْتِفارٌ', 'اغتفار', 'مصدر', 'غفر', 'اغتفار', 'غتفر', 'مص. اِغْتَفَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِغْتِفارٌ-اِغْتِفارٌ [غ ف ر] (مص. اِغْتَفَرَ). ""اِغْتِفَارُ الذُّنوبِ"": غُفْرَانُها، الصَّفْحُ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17762, 'اِغْتِمَامٌ', 'اغتمام', 'مصدر', 'غمم', 'اغتمام', 'غتمم', 'مص. اِغْتَمَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِغْتِمَامٌ-اِغْتِمَامٌ [غ م م] (مص. اِغْتَمَّ). ""وَجَدَهُ فِي اغْتِمَامٍ"" : فِي حُزْنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17763, 'اِغْتِنَامٌ', 'اغتنام', 'مصدر', 'غنم', 'اغتنام', 'غتنم', 'مص. اِغْتَنَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِغْتِنَامٌ-اِغْتِنَامٌ [غ ن م] (مص. اِغْتَنَمَ). 1.""دَخَلُوا الحَرْبَ مِنْ أجْل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17764, 'اِغْتِنَاءٌ', 'اغتناء', 'مصدر', 'غني', 'اغتناء', 'غتن', 'مص. اِغْتَنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِغْتِنَاءٌ-اِغْتِنَاءٌ [غ ن ي] (مص. اِغْتَنَى). ""اِغْتِنَاءُ الرَّجُلِ"" : أيْ تَمَكُّنُهُ مِنَ الْمَالِ وَالْمُمْتَلَكَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17765, 'إغْدَاقٌ', 'إغداق', 'مصدر', 'غدق', 'ءغداق', 'إغدق', 'مص. أغْدَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إغْدَاقٌ-إغْدَاقٌ [غ د ق] (مص. أغْدَقَ). 1. ""إغْدَاقُ العَيْنِ"": فَيْضُ دَمْعِهَا. 2. ""إغْدَاقُ العَطَاءِ"" : إعْطَاؤُهُ بِكَثْرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17766, 'إِغْرَاسٌ', 'إغراس', 'مصدر', 'غرس', 'ءغراس', 'إغرس', 'مص. أغْرَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِغْرَاسٌ-إِغْرَاسٌ [غ ر س] (مص. أغْرَسَ). ""إِغْرَاسُ جِذْرِ الشَّجَرَةِ"" : غَرْسُهُ، إنْبَاتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17767, 'إغْرَاقٌ', 'إغراق', 'مصدر', 'غرق', 'ءغراق', 'إغرق', 'مص. أغْرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إغْرَاقٌ-إغْرَاقٌ [غ ر ق] (مص. أغْرَقَ). 1.""أُعْلِنَ عَنْ إغْرَاقِ سَفِينَةٍ"" : عَنْ إِنْزَالِهَا وَتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17768, 'إغْرَاءٌ', 'إغراء', 'مصدر', 'غرو', 'ءغراء', 'إغر', 'مص. أَغْرَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إغْرَاءٌ-إغْرَاءٌ [غ ر و] (مص. أَغْرَى). 1. ""يُحَاوِلُ إغْرَاءهُ بِالْمَالِ"" : إغْوَاءهُ، جَذْبَهُ، أنْ جَعْلَهُ يَمِيلُ إلَيْهِ. 2. ""سَقَطَ تَحْتَ إغْرَاءِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17769, 'اِفْتِراسٌ', 'افتراس', 'مصدر', 'فرس', 'افتراس', 'فترس', 'مص. اِفْتَرَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِفْتِراسٌ-اِفْتِراسٌ [ف ر س] (مص. اِفْتَرَسَ). ""ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17770, 'إغْمَاضٌ', 'إغماض', 'مصدر', 'غمض', 'ءغماض', 'إغمض', 'مص. أغمَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إغْمَاضٌ-إغْمَاضٌ [غ م ض] (مص. أغمَضَ). 1. ""إغْمَاضُ العَيْنَيْنِ"" : إطْبَاق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17771, 'إغْنَاءٌ', 'إغناء', 'مصدر', 'غني', 'ءغناء', 'إغن', 'مص. أغْنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إغْنَاءٌ-إغْنَاءٌ [غ ن ي] (مص. أغْنَى). ""إغْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17772, 'إغْوَاءٌ', 'إغواء', 'مصدر', 'غوي', 'ءغواء', 'إغ', 'مص. أَغْوَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إغْوَاءٌ-إغْوَاءٌ [غ و ي] (مص. أَغْوَى). ""حَاوَلَ إغْوَاءهُ"": أي إبْعَادَهُ،"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17773, 'إفَادَةٌ', 'إفادة', 'مصدر', 'فود،فيد', 'ءفادة', 'إفدة', 'مص. أفَادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إفَادَةٌ-إفَادَةٌ [ف و د، ف ي د] (مص. أفَادَ). 1. ""أدْلَى الشَّاهِدُ بِإفَادَةٍ كَاذِبَةٍ"" : بِمَعْلُومَاتٍ،"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17774, 'إِفَاضَةٌ', 'إفاضة', 'مصدر', 'فيض', 'ءفاضة', 'إفضة', 'مص. أفَاضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِفَاضَةٌ-إِفَاضَةٌ [ف ي ض] (مص. أفَاضَ). 1. ""إِفَاضَةُ الإنَاءِ"": مَلْؤُهُ عَنْ آخِرِهِ. 2. ""الإِفَاضَةُ فِي الحَدِيثِ"" : التَّوَسُّعُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17775, 'اِفْتِتَاحٌ', 'افتتاح', 'مصدر', 'فتح', 'افتتاح', 'فتتح', 'مص. اِفْتَتَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِفْتِتَاحٌ-اِفْتِتَاحٌ [ف ت ح] (مص. اِفْتَتَحَ). 1. ""اِقْتَرَبَ يَوْمُ افْتِتَاحِ الْمَدَارِسِ"" : يَوْمُ الدُّخُولِ الْمَدْرَسِيِّ. 2. ""اِفْتِتَاحُ مَعْرِضٍ الرَّسَّامِ"" : يَوْمُ بَدْءِ زِيَارَةِ الْمَعْرِضِ. 3. ""أُعْلِنُ عِنِ افْتِتَاحِ الجَلْسَةِ الأُولَى"" : عَنْ بَدْءِ أَشْغَالِهَا الأُولَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17776, 'اِفْتِتَانٌ', 'افتتان', 'مصدر', 'فتن', 'افتتان', 'فتتن', 'مص. اِفْتَتَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِفْتِتَانٌ-اِفْتِتَانٌ [ف ت ن] (مص. اِفْتَتَنَ). 1. ""وَقَعَ القَوْمُ فِي افْتِتَانٍ"" : فِي فِتْنَةٍ مِنْ أمْرِهِمْ. 2. ""اِفْت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17777, 'اِفْتِخارٌ', 'افتخار', 'مصدر', 'فخر', 'افتخار', 'فتخر', 'مص. اِفْتَخَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِفْتِخارٌ-اِفْتِخارٌ [ف خ ر] (مص. اِفْتَخَرَ). ""أَعْلَنَ عَنْ نَجاحِهِ بِافْتِخارٍ"" : بِاعْتِزازٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17778, 'اِفْتِرارٌ', 'افترار', 'مصدر', 'فتر', 'افترار', 'فترر', 'مص. اِفْتَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِفْتِرارٌ-اِفْتِرارٌ [ف ت ر] (مص. اِفْتَرَّ). ""الاِفْتِرَارُ عَنِ الأسْنَانِ"" : الإِبَانَةُ عَنْهَا بِتَبَسُّمٍ حَسَنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17779, 'اِفْتِنَانٌ', 'افتنان', 'مصدر', 'فنن', 'افتنان', 'فتنن', 'مص. اِفْتَنَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِفْتِنَانٌ-اِفْتِنَانٌ [ف ن ن] (مص. اِفْتَنَّ). 1. ""الاِفْتِنَانُ فِي القَوْلِ"" : الإتْيَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17780, 'اِفْتِرَاشٌ', 'افتراش', 'مصدر', 'فرش', 'افتراش', 'فترش', 'مص. اِفْتَرَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِفْتِرَاشٌ-اِفْتِرَاشٌ [ف ر ش] (مص. اِفْتَرَسَ). ""اِفْتِرَاشُ البِسَاطِ"": اِتِّخَاذُهُ فِرَاشاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17781, 'اِفْتِرَاضٌ', 'افتراض', 'مصدر', 'فرض', 'افتراض', 'فترض', 'مص. اِفْتَرَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِفْتِرَاضٌ-اِفْتِرَاضٌ [ف ر ض] (مص. اِفْتَرَضَ). ""قَدَّمَ مُجَرَّدَ افْتِرَاضٍ"" : أُسْلُوبٌ فِي الحِوَارِ يَقْضِي طَرْحَ قَضِيَّةٍ للِتَّأكُّدِ مِنْ صِحَّتِهَا أَوْ عَدَمِ صِحَّتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17782, 'اِفْتِرَاقٌ', 'افتراق', 'مصدر', 'فرق', 'افتراق', 'فترق', 'مص. اِفْتَرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِفْتِرَاقٌ-اِفْتِرَاقٌ [ف ر ق] (مص. اِفْتَرَقَ). ""حَانَتْ لَحْظَةُ الافْتِرَاقِ"" : الاِنْفِصَالُ بَعْدَ لِقَاءٍ. ""اِفْتِرَاقُ الرَّجُلِ عَنْ زَوْجَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17783, 'اِفْتِرَاءٌ', 'افتراء', 'مصدر', 'فري', 'افتراء', 'فتر', 'مص. اِفْتَرَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِفْتِرَاءٌ-اِفْتِرَاءٌ [ف ر ي] (مص. اِفْتَرَى). ""نَهَاهُ عَنِ الاِفْتِرَاءِ"": عَنِ الكَذِبِ وَاخْتِلاقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17784, 'اِفْتِصَادٌ', 'افتصاد', 'مصدر', 'فصد', 'افتصاد', 'فتصد', 'مص. اِفْتَصَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِفْتِصَادٌ-اِفْتِصَادٌ [ف ص د] (مص. اِفْتَصَدَ). ""اِفْتِصَادُ العِرْقِ"": شَقُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17785, 'اِفْتِضَاحٌ', 'افتضاح', 'مصدر', 'فضح', 'افتضاح', 'فتضح', 'مص. اِفْتَضَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِفْتِضَاحٌ-اِفْتِضَاحٌ [ف ض ح] (مص. اِفْتَضَحَ). ""اِفْتِضَاحُ أَمْرِهِ"": اِنْكِشَافُهُ، ظُهُورُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17786, 'اِفْتِعَالٌ', 'افتعال', 'مصدر', 'فعل', 'افتعال', 'فتعل', 'مص. اِفْتَعَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِفْتِعَالٌ-اِفْتِعَالٌ [ف ع ل] (مص. اِفْتَعَلَ). ""اِفْتِعَالُ الخُصُومَةِ"": اِخْتِلافُهَا، اِبْتِدَاعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17787, 'اِفْتِقَادٌ', 'افتقاد', 'مصدر', 'فقد', 'افتقاد', 'فتقد', 'مص. اِفْتَقَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِفْتِقَادٌ-اِفْتِقَادٌ [ف ق د] (مص. اِفْتَقَدَ). 1. ""اِفْتِقَادُهُ لِمَا كَانَ يُحِبُّهُ"" : فُقْدَانهُ، إضَاعَتُهُ. 2. ""اِفْتِقَادُ الأحْوَالِ الاجْتِمَاعِيَّةِ"" : تَعَرُّفُها عَنْ قُرْبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17788, 'اِفْتِقَارٌ', 'افتقار', 'مصدر', 'فقر', 'افتقار', 'فتقر', 'مص. اِفْتَقَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِفْتِقَارٌ-اِفْتِقَارٌ [ف ق ر] (مص. اِفْتَقَرَ). 1. ""اِفْتِقَارُ الرَّجُلِ بَعْدَ غِنىً"" : اِعْوِزَازُهُ، اِفْتِقَادُهُ لِمَالِهِ. 2. ""اِفْتِقَارُهُ لِلإمْكَانَاتِ"" : اِحْتِيَاجُهُ لَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17789, 'إفْزَاعٌ', 'إفزاع', 'مصدر', 'فزع', 'ءفزاع', 'إفزع', 'مص. أفْزَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إفْزَاعٌ-إفْزَاعٌ [ف ز ع] (مص. أفْزَعَ). ""إفْزَاعُ الرَّجُلِ"" : إخَافَتُهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17790, 'إفْتَاءٌ', 'إفتاء', 'مصدر', 'فتو', 'ءفتاء', 'إفت', 'مص. أفْتَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إفْتَاءٌ-إفْتَاءٌ [ف ت و] (مص. أفْتَى). ""إفْتَاءُ الْمُفْتِي..."" : إبَانَةُ حُكْمٍ فِي مَوْضُوعٍ شَرْعِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17791, 'اِفْجَاعٌ', 'افجاع', 'مصدر', 'فجع', 'افجاع', 'فجع', 'مص. أفْجَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِفْجَاعٌ-اِفْجَاعٌ [ف ج ع] (مص. أفْجَعَ). ""إفْجَاعُ الرَّجُلِ"" : فَجْعُهُ، أي إِيلاَمُهُ بِشِدَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17792, 'إِفْحَامٌ', 'إفحام', 'مصدر', 'فحم', 'ءفحام', 'إفحم', 'مص. أَفْحَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِفْحَامٌ-إِفْحَامٌ [ف ح م] (مص. أَفْحَمَ). ""حَاوَلَ إفْحَامَهُ فِي النِّقَاشِ"" : إسْكَاتَهُ بِحُجَجِهِ وَعِلْمِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17793, 'إِفْرَاجٌ', 'إفراج', 'مصدر', 'فرج', 'ءفراج', 'إفرج', 'مص. أفْرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِفْرَاجٌ-إِفْرَاجٌ [ف ر ج] (مص. أفْرَجَ). ""وَقَعَ الإ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17794, 'إِفْرَاحٌ', 'إفراح', 'مصدر', 'فرح', 'ءفراح', 'إفرح', 'مص. أفْرَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِفْرَاحٌ-إِفْرَاحٌ [ف ر ح] (مص. أفْرَحَ). ""إفْرَاحُ الوَلَدِ"" : إدْخَالُ الفَرَحِ والسُّرُورِ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17795, 'إِفْرَادٌ', 'إفراد', 'مصدر', 'فرد', 'ءفراد', 'إفرد', 'مص. أَفْرَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِفْرَادٌ-إِفْرَادٌ [ف ر د] (مص. أَفْرَدَ). 1.: الإفْرَادُ فِي النَّحْوِ خِلافُ التَّثْنِيَةِ والجَمْعِ. 2. ""الإفْرادُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17796, 'إِفْرَازٌ', 'إفراز', 'مصدر', 'فرز', 'ءفراز', 'إفرز', 'مص. أفْرَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أفْرَزَ). 1. ""إفْرَازُ الحَجَرِ مِنَ القَمْحِ"" : عَزْلُه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17797, 'إِفْرَاطٌ', 'إفراط', 'مصدر', 'فرط', 'ءفراط', 'إفرط', 'مص. أَفْرَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِفْرَاطٌ-إِفْرَاطٌ [ف ر ط] (مص. أَفْرَطَ). 1. ""نَصَحَهُ الطَّبِيبُ بِعَدَمِ الإفْرَاطِ فِي الأَكْلِ"" : بِعَدَمِ الإكْثَارِ. 2.""الإفْرَاطُ في الشَّيءِ"" : الزِّيَادَةُ عَلَى اللُّزُومِ. ""إنَّ إفْرَاطَ الثَّرْوَةِ مَهْلَكَةٌ لِلأَخْلاَقِ الحَمِيدَةِ"". (ع. الكَواكِبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17798, 'إِفْرَاغٌ', 'إفراغ', 'مصدر', 'فرغ', 'ءفراغ', 'إفرغ', 'مص. أَفْرَغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِفْرَاغٌ-إِفْرَاغٌ [ف ر غ] (مص. أَفْرَغَ). 1. ""قَامَ بِإفْرَاغِ بُنْدُقِيَّتِهِ"" : إخْرَاج مَا فِيهَا مِنْ رَصَاصٍ. 2. ""قَامَ العُمَّالُ بِإفْرَاغِ البَاخِرَةِ مِنَ السِّلَعِ"" : تَنْزِيلهَا، تَفْرِيغهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17799, 'إفْسَادٌ', 'إفساد', 'مصدر', 'فسد', 'ءفساد', 'إفسد', 'مص. أفْسَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إفْسَادٌ-إفْسَادٌ [ف س د] (مص. أفْسَدَ). ""إفْسَادُ العَمَلِ"" : إحْدَاثُ الأضْرَارِ بِهِ، إتْلاَفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17800, 'إفْشَاءٌ', 'إفشاء', 'مصدر', 'فشي', 'ءفشاء', 'إفش', 'مص. أفْشَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إفْشَاءٌ-إفْشَاءٌ [ف ش ي] (مص. أفْشَى). 1. ""لاَ تُفْشِ مَا لاَ يَنْبَغِي إفْشَاؤُهُ"" : لاَ تُذِعْ ما لاَ يَنْبَغِي إذَاعَت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17801, 'إفْصَاحٌ', 'إفصاح', 'مصدر', 'فصح', 'ءفصاح', 'إفصح', 'مص. أفْصَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إفْصَاحٌ-إفْصَاحٌ [ف ص ح] (مص. أفْصَحَ). ""فِي مِثْلِ هَذِهِ الْمَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17802, 'إِفْطارٌ', 'إفطار', 'مصدر', 'فطر', 'ءفطار', 'إفطر', 'مص. أَفْطَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِفْطارٌ-إِفْطارٌ [ف ط ر] (مص. أَفْطَرَ). ""دَعانَا إلَى الإِفْطَارِ عَلَى مَائِدَتِهِ"" : إلى تَناوُلِ طَعامِ الفُطُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17803, 'إِفْطامٌ', 'إفطام', 'مصدر', 'فطم', 'ءفطام', 'إفطم', 'مص. أفْطَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِفْطامٌ-إِفْطامٌ [ف ط م] (مص. أفْطَمَ). ""إِفْطامُ الوَلَدِ"": فَطْمُهُ، أيْ قَطْعُ الرِّضاعَةُ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17804, 'إفْعامٌ', 'إفعام', 'مصدر', 'فعم', 'ءفعام', 'إفعم', 'مص. أفْعَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إفْعامٌ-إفْعامٌ [ف ع م] (مص. أفْعَمَ). ""إفْعامُ الْمَكانِ بِالمِسْكِ"": مَلْؤُهُ بهِ. "" إفْعامُ الإِنَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17805, 'أَفَقٌ', 'أفق', 'مصدر', 'أفق', 'ءفق', 'فق', 'مص. أَفِقَ', '', '', 'مفرد', 'DnN', '', '', '"آفاقٌ"', '', 'R', '', '', '', '', '', '', '"(مص. أَفِقَ). ""الأَفَقُ مِنَ الطَّريقِ"" : وَجْهُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17806, 'آفاقٌ', 'آفاق', 'مصدر', '', 'ءءفاق', 'آفق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17807, 'إفْقارٌ', 'إفقار', 'مصدر', 'فقر', 'ءفقار', 'إفقر', 'مص. أفْقَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إفْقارٌ-إفْقارٌ [ف ق ر] (مص. أفْقَرَ). ""عَمِلَ عَلَى إفْقَارِهِ"": جَعْلُهُ مُعْدِماً، مُعْوِزاً، فَقِيراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17808, 'إفْكٌ', 'إفك', 'مصدر', 'أفك', 'ءفك', 'إفك', 'مص. أفِكَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"إفْكٌ-إفْكٌ [أ ف ك] (مص. أفِكَ). ""كُلُّ أخْبارِهِ إفْكٌ"" : كَذِبٌ.الفرقان آية 4 وَقالَ الَّذِينَ كَفَرُوا إنْ هَذَا إلاَّ إفْكٌ افْتَرَاهُ (قُرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17809, 'أُفُولٌ', 'أفول', 'مصدر', 'أفل', 'ءفول', 'فل', 'مص. أفَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"أُفُولٌ-أُفُولٌ [أ ف ل] (مص. أفَلَ). ""أُفُولُ الشَّمْسِ"" : غُرُوبُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17810, 'إفْلاَتٌ', 'إفلات', 'مصدر', 'فلت', 'ءفلات', 'إفلت', 'مص. أفْلَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إفْلاَتٌ-إفْلاَتٌ [ف ل ت] (مص. أفْلَتَ). ""حَاوَلَ الإِفْلاَتَ مِنْ قَبْضَتِهِ"" : التَّخَلُّصَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17811, 'إفْلاَحٌ', 'إفلاح', 'مصدر', 'فلح', 'ءفلاح', 'إفلح', 'مص. أفْلَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إفْلاَحٌ-إفْلاَحٌ [ف ل ح] (مص. أفْلَحَ). ""إِفْلاَحُ الرَّجُلِ"": نَجَاحُهُ، فَوْزُهُ، إصابَةُ مُبْتغَاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17812, 'إفْلاَسٌ', 'إفلاس', 'مصدر', 'فلس', 'ءفلاس', 'إفلس', 'مص. أفْلَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إفْلاَسٌ-إفْلاَسٌ [ف ل س] (مص. أفْلَسَ). ""أعْلَنَتِ الشَّرِكَةُ عَنْ إفْلاَسِها"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17813, 'إفْناءٌ', 'إفناء', 'مصدر', 'فني', 'ءفناء', 'إفن', 'مص. أفْنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إفْناءٌ-إفْناءٌ [ف ن ي] (مص. أفْنَى). ""إفْناءُ العَدُوِّ"": إِهْلاَكُهُ، إعْدامه."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17814, 'إقالَةٌ', 'إقالة', 'مصدر', 'قيل', 'ءقالة', 'إقلة', 'مص. أقَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إقالَةٌ-إقالَةٌ [ق ي ل] (مص. أقَالَ). 1.""أعْلَنَ عَنْ إقَالَةِ الوَزِيرِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17815, 'إقامَةٌ', 'إقامة', 'مصدر', 'قوم', 'ءقامة', 'إقمة', 'مص. أقامَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '": (مص. أقامَ). 1.""غَيَّرَ مَحَلَّ إقامَتِهِ"" : مَحَلَّ سُكْناهُ. 2.""لاَ بُدَّ مِنْ إقامَةِ عَلاَقاتٍ وُدِّيَّةٍ مَعَ الجِيرانِ"" : إثْباتِ، تَرْسِيخِ. 3.""مِنْ تَقالِيدِ الْمُجْتَمَعاتِ المحافَظَةُ عَلَى إقامَةِ الشَّعَائِرِ"" : مُمارَسَتُها. 4.""طَوَى بساطَ الإقامَةِ"" : رَحَلَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17816, 'إِقْبارٌ', 'إقبار', 'مصدر', 'قبر', 'ءقبار', 'إقبر', 'مص. أَقْبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِقْبارٌ-إِقْبارٌ [ق ب ر] (مص. أَقْبَرَ). ""إقْبارُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17817, 'إقْبالٌ', 'إقبال', 'مصدر', 'قبل', 'ءقبال', 'إقبل', 'مص. أَقْبَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إقْبالٌ-إقْبالٌ [ق ب ل] (مص. أَقْبَلَ). 1.""إقْبَالُ اللَّيْلِ"" : حُل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17818, 'اِقْتِياتٌ', 'اقتيات', 'مصدر', 'قوت', 'اقتيات', 'قتت', 'مص. اِقْتَاتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِياتٌ-اِقْتِياتٌ [ق و ت] (مص. اِقْتَاتَ). ""هُوَ بِحَاجَةٍ إلَى اقْتِياتٍ"" : إلَى أكْلِ قُوتٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17819, 'اِقْتِرَافٌ', 'اقتراف', 'مصدر', 'قرف', 'اقتراف', 'قترف', 'مص. اِقْتَرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِرَافٌ-اِقْتِرَافٌ [ق ر ف] (مص. اِقْتَرَفَ). ""اِقْتِرَافُ ذَنْبٍ"": القِيامُ بِهِ وَارْتِكابُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17820, 'اِقْتِيادٌ', 'اقتياد', 'مصدر', 'قيد', 'اقتياد', 'قتد', 'مص. اِقْتَادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِيادٌ-اِقْتِيادٌ [ق ي د] (مص. اِقْتَادَ). ""اِقْتِيادُ الدَّابَّة"": قِيادَتُها، أَي السَّيْرُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17821, 'اِقْتِباسٌ', 'اقتباس', 'مصدر', 'قبس', 'اقتباس', 'قتبس', 'مص. اِقْتَبَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِباسٌ-اِقْتِباسٌ [ق ب س] (مص. اِقْتَبَسَ). 1. ""اِقْتِبَاسُ أفْكَارٍ مِنْ كِتَابِ كَذَا"" : أخْذُها وَتحْوِيرُهَا، أيْ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17822, 'اِقْتِتَالٌ', 'اقتتال', 'مصدر', 'قتل', 'اقتتال', 'قتتل', 'مص. اِقْتَتَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِتَالٌ-اِقْتِتَالٌ [ق ت ل] (مص. اِقْتَتَلَ). ""ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17823, 'اِقْتِحامٌ', 'اقتحام', 'مصدر', 'قحم', 'اقتحام', 'قتحم', 'مص. اِقْتَحَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِقْتِحامٌ-اِقْتِحامٌ [ق ح م] (مص. اِقْتَحَمَ). 1.""وَقَعَ اقْتِحَامُ سَفِينَةٍ فِي الخَلِيجِ"" : مُهاجَمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17824, 'اِقْتِداءٌ', 'اقتداء', 'مصدر', 'قدي', 'اقتداء', 'قتد', 'مص. اِقْتَدَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِقْتِداءٌ-اِقْتِداءٌ [ق د ي] (مص. اِقْتَدَى). ""إنَّهُ الرَّجُلُ الَّذِي يَنْبَغِي الاقْتِدَاءُ بِهِ"" : تَمثُّلُ مِثالِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17825, 'اِقْتِرابٌ', 'اقتراب', 'مصدر', 'قرب', 'اقتراب', 'قترب', 'مص. اِقْتَرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِرابٌ-اِقْتِرابٌ [ق ر ب] (مص. اِقْتَرَبَ). ""اِقْتِرَابُ مَوْعِدِ الامْتِحانِ"" : دُنُوُّهُ، قُرْبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17826, 'اِقْتِراحٌ', 'اقتراح', 'مصدر', 'قرح', 'اقتراح', 'قترح', 'مص. اِقْتَرَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِراحٌ-اِقْتِراحٌ [ق ر ح] (مص. اِقْتَرَحَ). ""تقَدَّمَ بِاقْتِراحٍ إلَى الرَّئيسِ"" : عَرْضُ مَسْألَةٍ يُؤ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17827, 'اِقْتِرَاضٌ', 'اقتراض', 'مصدر', 'قرض', 'اقتراض', 'قترض', 'مص. اِقْتَرَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِرَاضٌ-اِقْتِرَاضٌ [ق ر ض] (مص. اِقْتَرَضَ). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17828, 'اِقْتِراعٌ', 'اقتراع', 'مصدر', 'قرع', 'اقتراع', 'قترع', 'مص. اِقْتَرَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِراعٌ-اِقْتِراعٌ [ق ر ع] (مص. اِقْتَرَعَ). ¨ ""تَقَدَّمَ النَّاخِبُونَ إلَى صُنْدُوقِ الا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17829, 'اِقْتِناصٌ', 'اقتناص', 'مصدر', 'قنص', 'اقتناص', 'قتنص', 'مص. اِقْتَنَصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِناصٌ-اِقْتِناصٌ [ق ن ص] (مص. اِقْتَنَصَ). ""ظَلَّ الص"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17830, 'اِقْتِسامٌ', 'اقتسام', 'مصدر', 'قسم', 'اقتسام', 'قتسم', 'مص. اِقْتَسَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِسامٌ-اِقْتِسامٌ [ق س م] (مص. اِقْتَسَمَ). ""تَمَّ اقْتِسَامُ الإرْثِ بَعْدَ وَفَاةِ الأبِ"" : تَوْزِيعُهُ، تَقْسِيمُهُ. ""اِتَّفَقُوا عَلَى اقْتِسَامِ الرِّبْحِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17831, 'اِقْتِصَادٌ', 'اقتصاد', 'مصدر', 'قصد', 'اقتصاد', 'قتصد', 'مص. اِقْتَصَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِقْتِصَادٌ-اِقْتِصَادٌ [ق ص د] (مص. اِقْتَصَدَ). 1. ""يُحاوِلُ الاقْتِصادَ فِي مَعِيشَتِهِ"" : أَي الادِّخَارَ وَعَدَمَ التَّبْذِيرِ. 2.""يَقُومُ اقْتِصَادُ البِلاَدِ عَلَى الزِّرَاعَةِ"" : أَي مَظَاهِرُ الإنْتَاجِ وَالتَّوْزيعِ والاسْتِهْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17832, 'اِقْتِصَارٌ', 'اقتصار', 'مصدر', 'قصر', 'اقتصار', 'قتصر', 'مص. اِقْتَصَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِصَارٌ-اِقْتِصَارٌ [ق ص ر] (مص. اِقْتَصَرَ). ""الاقْتِصَارُ عَلَى مَا هوَ أساسِيٌّ"" : الاكْتِفَاءُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17833, 'اِقتِضَابٌ', 'اقتضاب', 'مصدر', 'قضب', 'اقتضاب', 'قتضب', 'مص. اِقْتَضَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقتِضَابٌ-اِقتِضَابٌ [ق ض ب] (مص. اِقْتَضَبَ). ""أجَابَ بِاقْتِضابٍ"": بِإيجَازٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17834, 'اِقْتِضَاءٌ', 'اقتضاء', 'مصدر', 'قضي', 'اقتضاء', 'قتض', 'مص. اِقْتَضَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِقْتِضَاءٌ-اِقْتِضَاءٌ [ق ض ي] (مص. اِقْتَضَى). ""عِنْدَ الاقْتِضاءِ سَنُدْلِي بِشَهادَتِنَا"" : عِنْدَ الضَّرورَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17835, 'اِقْتِطاعٌ', 'اقتطاع', 'مصدر', 'قطع', 'اقتطاع', 'قتطع', 'مص. اِقْتَطَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِطاعٌ-اِقْتِطاعٌ [ق ط ع] (مص. اِقْتَطَعَ). ""اِقْتِطَاعُ مَبلَغٍ مِنْ مَصْروفِ جَيْبِهِ"" : أخْذُ جزْءٍ مِنْهُ، خَصْمُهُ. ""اِقْتِطَاعُ مَبْلَغٍ مِنْ حَوَالَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17836, 'اِقْتِطَافٌ', 'اقتطاف', 'مصدر', 'قطف', 'اقتطاف', 'قتطف', 'مص. اِقْتَطَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِطَافٌ-اِقْتِطَافٌ [ق ط ف] (مص. اِقْتَطَفَ). 1. ""اِقْتِطَافُ الثِّمَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17837, 'اِقْتِفاءٌ', 'اقتفاء', 'مصدر', 'قفو', 'اقتفاء', 'قتف', 'مص. اِقْتَفَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِقْتِفاءٌ-اِقْتِفاءٌ [ق ف و] (مص. اِقْت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17838, 'اِقْتِلاَعٌ', 'اقتلاع', 'مصدر', 'قلع', 'اقتلاع', 'قتلع', 'مص. اِقْتَلَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِلاَعٌ-اِقْتِلاَعٌ [ق ل ع] (مص. اِقْتَلَعَ). ""ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17839, 'إقْصَاءٌ', 'إقصاء', 'مصدر', 'قصو', 'ءقصاء', 'إقص', 'مص. أقْصَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إقْصَاءٌ-إقْصَاءٌ [ق ص و] (مص. أقْصَى). ""قَامَ بِإقْصَائِهِ مِنَ الصّفِّ"" : إبْعَادِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17840, 'اِقْتِناعٌ', 'اقتناع', 'مصدر', 'قنع', 'اقتناع', 'قتنع', 'مص. اِقْتَنَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْتِناعٌ-اِقْتِناعٌ [ق ن ع] (مص. اِقْتَنَعَ). ""لَمْ يَكُنْ مِنَ السَّهْلِ الاقْتِناعُ بِالحُجَجِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17841, 'اِقْتِناءٌ', 'اقتناء', 'مصدر', 'قني', 'اقتناء', 'قتن', 'مص. اِقْتَنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِقْتِناءٌ-اِقْتِناءٌ [ق ن ي] (مص. اِقْتَنَى). 1.""يَسْعَى إلى اقْتِنَاءِ الْمَالِ"" : إلَى جَمْعِهِ. 2.""يَعْمَلُ عَلَى اقْتِناءِ لَوْحَاتٍ فَنِّيَّةٍ"" : عَلَى اخْتِيارِها وَالاحْتِفاظِ بِها، اِتِّخَاذِها ضِمْنَ مَجْموعَاتٍ ثَمِينَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17842, 'إقْحَامٌ', 'إقحام', 'مصدر', 'قحم', 'ءقحام', 'إقحم', 'مص. أقْحَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إقْحَامٌ-إقْحَامٌ [ق ح م] (مص. أقْحَمَ). 1.""إقْحَامُ فِكْرَةٍ شَاذَّةٍ فِي الْمَوْضُوع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17843, 'إقْدَامٌ', 'إقدام', 'مصدر', 'قدم', 'ءقدام', 'إقدم', 'مص. أقْدَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إقْدَامٌ-إقْدَامٌ [ق د م] (مص. أقْدَمَ). 1. ""الإقْدَامُ عَلَى فِعْلِ الخَيْرِ"" : التَّقَدُّمُ وَالقِيامُ بِهِ. 2.""تَتَمَيَّزُ أعْمالُهُ بِالإقْدَامِ"" : الإِسْرَاعُ فِي إنْجَازِها دُونَ تَوَقُّفٍ، وَيُمْكِنُ أَنْ يَتَضَمَّنَ ذَلِكَ الْمُخاطَرَةَ وَالْمُغَامَرَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17844, 'إقْرَارٌ', 'إقرار', 'مصدر', 'قرر', 'ءقرار', 'إقرر', 'مص. أقَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إقْرَارٌ-إقْرَارٌ [ق ر ر] (مص. أقَرَّ). ""مَعَ الزَّمَنِ تَمَّ إقْرَارُ أعْرَافٍ جَدِيدَةٍ"" : أَي الخُضُوعُ وَالاعْتِرَافُ. ""الإقْرَارُ بِالذَّنْبِ فَضِيلَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17845, 'إِقْراءٌ', 'إقراء', 'مصدر', 'قرأ', 'ءقراء', 'إقر', 'مص. أَقْرَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِقْراءٌ-إِقْراءٌ [ق ر أ] (مص. أَقْرَأَ). ""إِقْراءُ السَّلامِ"" : تَبْليغُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17846, 'إِقْراضٌ', 'إقراض', 'مصدر', 'قرض', 'ءقراض', 'إقرض', 'مص. أَقْرَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِقْراضٌ-إِقْراضٌ [ق ر ض] (مص. أَقْرَضَ). ""طَلَبَ مِنْهُ إِق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17847, 'إقْرانٌ', 'إقران', 'مصدر', 'قرن', 'ءقران', 'إقرن', 'مص. أقْرَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إقْرانٌ-إقْرانٌ [ق رن] (مص. أقْرَنَ). 1.""إقْرَانُ شَيْئَيْنِ أَوْ عَمَلَيْنِ"" : الجَمْعُ بَيْنَهُما. 2. ""إقْرا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17848, 'اِقْشِعْرارٌ', 'اقشعرار', 'مصدر', 'قشع', 'اقشعرار', 'قشعرر', 'مص. اِقْشَعَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِقْشِعْرارٌ-اِقْشِعْرارٌ [ق ش ع] (مص. اِقْشَعَرَّ). ""اِقْشِعْرارُ الجَسَدِ"": حُدُوثُ ارْتِعاشٍ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17849, 'إقْوَاءٌ', 'إقواء', 'مصدر', 'قوي', 'ءقواء', 'إق', 'مص. أقْوَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إقْوَاءٌ-إقْوَاءٌ [ق و ي] (مص. أقْوَى). ""فِي شِعْرِهِ إقْوَاءٌ"" : مِنْ عُيُوبِ الشِّعْرِ، وَهُوَ أنْ تَخْتَلِفَ حَرَكَةُ الرَّوِيِّ فَبَعْضُهُ مَرْفوعٌ وَبَعْضُهُ مَنْصُوبٌ أوْ مَجْرُورٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17850, 'إقْضَاضٌ', 'إقضاض', 'مصدر', 'قضض', 'ءقضاض', 'إقضض', 'مص. أَقَضَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إقْضَاضٌ-إقْضَاضٌ [ق ض ض] (مص. أَقَضَّ). 1.""إقْضَاضُ الطَّعَامِ أَوِ الْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17851, 'إقْطَاعٌ', 'إقطاع', 'مصدر', 'قطع', 'ءقطاع', 'إقطع', 'مص. أقْطَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"إقْطَاعٌ-إقْطَاعٌ [ق ط ع] (مص. أقْطَعَ). 1."" إقْطَاعُ الأرْضِ"": جَعْلُ غَلَّتِها رِزْقاً. 2.""نِظَامُ الإقْطَاعِ"" : نِظامٌ سِياسِيّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17852, 'إقْعَادٌ', 'إقعاد', 'مصدر', 'قعد', 'ءقعاد', 'إقعد', 'مص. أقْعَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إقْعَادٌ-إقْعَادٌ [ق ع د] (مص. أقْعَدَ). 1."" إقْعَادُ الطِّفْلِ"": إجْلاسُهُ. 2.""مَرَضُ الإِقْعَادِ"" : يُقْعِدُ مَنْ أُصِيبَ بِهِ."', '');
