INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17854, 'إقْفَالٌ', 'إقفال', 'مصدر', 'قفل', 'ءقفال', 'إقفل', 'مص. أقْفَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إقْفَالٌ-إقْفَالٌ [ق ف ل] (مص. أقْفَلَ). ""إِقْفَالُ البَابِ"" : إغْلاقهُ، سَدُّهُ."', '');
