INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17859, 'اِكْتِسَاحٌ', 'اكتساح', 'مصدر', 'كسح', 'اكتساح', 'كتسح', 'مص. اِكْتَسَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِكْتِسَاحٌ-اِكْتِسَاحٌ [ك س ح] (مص. اِكْتَسَحَ). ""اِكْتِسَاحُ البِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17860, 'إكْبَابٌ', 'إكباب', 'مصدر', 'كبب', 'ءكباب', 'إكبب', 'مص. أَكَبَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إكْبَابٌ-إكْبَابٌ [ك ب ب] (مص. أَكَبَّ). ""الإِكْبَابُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17861, 'إِكْبَارٌ', 'إكبار', 'مصدر', 'كبر', 'ءكبار', 'إكبر', 'مص. أكْبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِكْبَارٌ-إِكْبَارٌ [ك ب ر] (مص. أكْبَرَ). ""وَقْفَةٌ فِيهَا إجْلالٌ وإكْبَارٌ"" : تَعْظِيمٌ وتَبْجِيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17862, 'اِكْتِئَابٌ', 'اكتئاب', 'مصدر', 'كأب', 'اكتءاب', 'كتب', 'مص. اِكْتأبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِكْتِئَابٌ-اِكْتِئَابٌ [ك أ ب] (مص. اِكْتأبَ). ""شَعَرَ باكْتِئَابٍ"": بِحُزْنٍ، بِأسىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17863, 'اِكْتِتَابٌ', 'اكتتاب', 'مصدر', 'كتب', 'اكتتاب', 'كتتب', 'مص. اِكْتَتَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِكْتِتَابٌ-اِكْتِتَابٌ [ك ت ب] (مص. اِكْتَتَبَ). 1.""قَرَّروا اكْتِتَاباً مَالِيّاً لِفَائِدَةِ زَمِيلِهِمْ"" : الاشْتِرَاكَ فِي جَمْعِ قَدْرٍ مِنَ الْمَالِ لِهَدَفٍ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17864, 'اِكْتِتَامٌ', 'اكتتام', 'مصدر', 'كتم', 'اكتتام', 'كتتم', 'مص. اِكْتَتَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِكْتِتَامٌ-اِكْتِتَامٌ [ك ت م] (مص. اِكْتَتَمَ). 1.""اِكْتِتَامُ س"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17865, 'اِكْتِحَالٌ', 'اكتحال', 'مصدر', 'كحل', 'اكتحال', 'كتحل', 'مص. اِكْتَحَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِكْتِحَالٌ-اِكْتِحَالٌ [ك ح ل] (مص. اِكْتَحَلَ). 1.""اِكْتِحَالُ الْمَرْأةِ"": وَضْعُ الكُحْلِ فِي عَيْنَيْهَا. 2.""اِكتِحَالُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17866, 'اِكْتِرَاثٌ', 'اكتراث', 'مصدر', 'كرث', 'اكتراث', 'كترث', 'مص. اِكْتَرَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِكْتِرَاثُ-اِكْتِرَاثُ [ك ر ث] (مص. اِكْتَرَثَ). ""عَدَمُ الاكْتِرَاثِ"": قِلَّةُ الاهْتِمَامِ، اللاَّمُبَالاَةُ. ""عَدَمُ الاكْتِرَاثِ بِمَا حَدَثَ"" ""لَمْ يُظْهِرِ اكْتِرَاثاً أمَامَهُ""."', '');
