INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17868, 'اِكْتِسَابٌ', 'اكتساب', 'مصدر', 'كسب', 'اكتساب', 'كتسب', 'مص. اِكْتَسَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِكْتِسَابٌ-اِكْتِسَابٌ [ك س ب] (مص. اِكْتَسَبَ). ""اِكْتِسَابُ الْمَالِ"" : رِبْحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17869, 'اِكْتِوَاءٌ', 'اكتواء', 'مصدر', 'كوي', 'اكتواء', 'كت', 'مص. اِكْتَوَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِكْتِوَاءٌ-اِكْتِوَاءٌ [ك و ي] (مص. اِكْتَوَى). ""اِكْتِواءُ الْجِسْمِ"": اِحْتِرَاقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17870, 'اِكْتِسَاءٌ', 'اكتساء', 'مصدر', 'كسي', 'اكتساء', 'كتس', 'مص. اِكْتَسَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِكْتِسَاءٌ-اِكْتِسَاءٌ [ك س ي] (مص. اِكْتَسَى)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17871, 'اِكْتِشَافٌ', 'اكتشاف', 'مصدر', 'كشف', 'اكتشاف', 'كتشف', 'مص. اِكْتَشَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِكْتَشَفَ). 1.""أُعْلِنَ عَن اكْتِشَافِ مَدِينَةٍ أثَرِيَّةٍ بِالعِرَاقِ تَعُودُ إلَى عَهْدِ البَابِليِّينَ"" : إيجَادُهَا وَالتَّوَصُّلُ إلى مَعْرِفَتِها بَعْدَ بَحْثٍ وَتَنْقيبٍ. 2.""أَعْلَنَ الطَّبِيبُ عَنْ قُرْبِ اكْتِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17872, 'اِكْتِظَاظٌ', 'اكتظاظ', 'مصدر', 'كظظ', 'اكتظاظ', 'كتظظ', 'مص. اِكْتَظَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِكْتِظَاظٌ-اِكْتِظَاظٌ [ك ظ ظ] (مص. اِكْتَظَّ). 1.""يَعْرِفُ الشَّارِعُ اكْتِظَاظاً فِي الْمَسَاءِ"" : اِزْدِحَاماً. 2."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17873, 'اِكْتِفَاءٌ', 'اكتفاء', 'مصدر', 'كفي', 'اكتفاء', 'كتف', 'مص. اِكْتَفَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِكْتِفَاءٌ-اِكْتِفَاءٌ [ك ف ي] (مص. اِكْتَفَى). ""كَيْفَ يُمْكِنُ لِبَلَدٍ أنْ يَعِيشَ اكْتِفَاءً ذَاتِيّا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17874, 'اِكْتِمَالٌ', 'اكتمال', 'مصدر', 'كمل', 'اكتمال', 'كتمل', 'مص. اِكْتَمَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِكْتِمَالٌ-اِكْتِمَالٌ [ك م ل] (مص. اِكْتَمَلَ). 1.""اكْتِمَالُ دَوْرَةِ القَمَرِ"" : إتْمَامُهَا. 2.""عِنْدَ اكْتِمالِ نِهايَةِ الشَّهْرِ سَأَدْفَعُ لَكَ أُجْرَتَكَ"" : عِنْدَ بُلُوغِ نِهَايتِهِ، عِنْدَ تَمَامِهِ. 3.""يَنْبَغِي أنْ نَنْتَظِرَ اكْتِمَالَ طَاقَتِهِ"" : أَي امْتِلاكَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17875, 'اِكْتِنَازٌ', 'اكتناز', 'مصدر', 'كنز', 'اكتناز', 'كتنز', 'مص. اِكْتَنَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِكْتِنَازٌ-اِكْتِنَازٌ [ك ن ز] (مص. اِكْتَنَزَ). ""اِكْت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17876, 'اِكْتِنَافٌ', 'اكتناف', 'مصدر', 'كنف', 'اكتناف', 'كتنف', 'مص. اِكْتَنَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِكْتِنَافٌ-اِكْتِنَافٌ [ك ن ف] (مص. اِكْتَنَفَ). 1.""أرَادَ اكْتِنافَه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17877, 'اِكْتِنَاهٌ', 'اكتناه', 'مصدر', 'كنه', 'اكتناه', 'كتنه', 'مص. اِكْتَنَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِكْتِنَاهٌ-اِكْتِنَاهٌ [ك ن هـ] (مص. اِكْتَنَهَ). 1.""اِكْتِنَاهُ عُمْقِ الْمَوْضُوعِ"" : سَبْرُ غَوْرِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17878, 'اِكْتِهَالٌ', 'اكتهال', 'مصدر', 'كهل', 'اكتهال', 'كتهل', 'مص. اِكْتَهَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِكْتِهَالٌ-اِكْتِهَالٌ [ك هـ ل] (مص. اِكْتَهَلَ). 1.""اِكْتِهَالُ الرَّجُلِ"" : ص"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17879, 'اِكْفِهْرارٌ', 'اكفهرار', 'مصدر', 'كفه', 'اكفهرار', 'كفهرر', 'مص. اِكْفَهَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِكْفِهْرارٌ-اِكْفِهْرارٌ [ك ف هـ] (مص. اِكْفَهَرَّ). 1.""عَرَفَتِ السَّمَاءُ اكْفِهْرَاراً"" : تَجَهُّماً. 2.""اِكْفِهْرَارُ الوُجُوهِ يُعَبِّرُ عَنْ حَجْمِ الْمَأسَاةِ"" : العبُوسُ الشَّدِيدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17880, 'إكْثَارٌ', 'إكثار', 'مصدر', 'كثر', 'ءكثار', 'إكثر', 'مص: أَكْثَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إكْثَارٌ-إكْثَارٌ [ك ث ر] (مص: أَكْثَرَ).إكْثَارُ الطَّعَامِ"" : جَعَلَهُ كَثِيراً. 2.""الإِكْثَارُ مِنَ الْمَدْحِ"" : الإطْنَابُ. 3.""الإِكْثَارُ مِنَ القِرَاءَةِ"" ""الإِكْثَارُ مِنَ الضَّحِكِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17881, 'إكْحَالٌ', 'إكحال', 'مصدر', 'كحل', 'ءكحال', 'إكحل', 'مص. أكْحَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إكْحَالٌ-إكْحَالٌ [ك ح ل] (مص. أكْحَلَ). 1. ""إكْحَالُ العَامِ"": اِشْتِدَادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17882, 'تَأْكِيدٌ', 'تأكيد', 'مصدر', 'أكد،وكد', 'تءكيد', 'تكد', 'مص. أَكَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَكَّدَ). 1.""طَلَبَ مِنْهُ تَأْكِيدَ طَلَبِهِ"" : تَثْبِيتَهُ. 2.""لَنْ أُخْلِفَ وَعْدِي بِالتَّأْكِيدِ"" : يَقِيناً. 3.""تَأْكيداً لِما جَاءَ فِي كَلاَمِهِ"" : إِضَافَةً فِي الإِثْبَاتِ وَالتَّأَكُّدِ وَالتَّحَقُّقِ. ""جَاءَ بِتَأْكِيدَاتٍ جَدِيدَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17883, 'إكْرَامٌ', 'إكرام', 'مصدر', 'كرم', 'ءكرام', 'إكرم', 'مص. أكْرَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إكْرَامٌ-إكْرَامٌ [ك ر م] (مص. أكْرَمَ). 1.""إكْرَاماً لِمَكَانَتِهِ"" : تَقْدِيراً لَهَا. 2.""إكْرَاماً لِعَيْنِهِ"" : مِنْ أَجْلِ سَوَادِ عَيْنَيْهِ. 3.الرحمن آية 27 وَيَبْقَى وَجْهُ رَبِّكَ ذُو الجَلالِ والإكْرَامِ (قرآن) : ذُو الجَلالِ والتَّعْظِيمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17884, 'إكْرَاهٌ', 'إكراه', 'مصدر', 'كره', 'ءكراه', 'إكره', 'مص. أكْرَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إكْرَاهٌ-إكْرَاهٌ [ك ر هـ] (مص. أكْرَهَ). ""لاَ إكْرَاهَ فِي طَلَبِ العِلْمِ"" : لاَ إرْغَامَ.البقرة آية 256 لاَ إكْرَاهَ فِي الدِّينِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17885, 'إكْرَاءٌ', 'إكراء', 'مصدر', 'كري', 'ءكراء', 'إكر', 'مص. أكْرَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إكْرَاءٌ-إكْرَاءٌ [ك ر ي] (مص. أكْرَى). ""إكْرَاءُ بَيْتٍ"" : إيجَارهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17886, 'إِكْسَابٌ', 'إكساب', 'مصدر', 'كسب', 'ءكساب', 'إكسب', 'مص. أَكْسَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِكْسَابُ-إِكْسَابُ [ك س ب] (مص. أَكْسَبَ). ""أرَاد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17887, 'أَكْسَدَةٌ', 'أكسدة', 'مصدر', 'أكسد', 'ءكسدة', 'كسدة', 'مص. أكَسَد', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"أَكْسَدَةٌ-أَكْسَدَةٌ (كيما) (مص. أكَسَد).: هيَ تَخَلِّي ذَرَّاتِ الْمَادَّةِ الْمُخْتَزِلَةِ عَن ذَرَّةِ مَادَّةٍ أُخْرَى، كَمَا أنَّ الْتِحَامَ وَتَفَاعُلَ وَضَمَّ جِسْمٍ بالأُكْسِجِينِ يَنْتُجُ عَنْهُ أُكْسِيدٌ. وَالأَكْسَدَةُ وَالاخْتِزَالُ مَظْهَرَانِ مُتَلاَزِمَانِ لاَ يَفْتَرِقَانِ فِي تَفَاعُلِهِمَا، وَمِنْ أَنْوَاعِ الأَكْسَدَةِ صَدَأُ الحَدِيدِ وَاحْتِرَاقُ الأَجْسَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17888, 'إِكْفَاءٌ', 'إكفاء', 'مصدر', 'كفأ', 'ءكفاء', 'إكف', 'مص. أَكْفَأ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِكْفَاءٌ-إِكْفَاءٌ [ك ف أ] (مص. أَكْفَأ). 1.""الإكْفَاءُ فِي السَّيْرِ"": الْمَيْلُ عَنِ القَصْدِ. 2."" الإكْفَاءُ فِي الشِّعْرِ"": أنْ يُخَالِفَ الشَّاعِرُ فِي القَوَافِي كأنْ يَجْعَلَ بَعضَهَا لاماً وَبَعْضَهَا مِيماً أَوْ نُوناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17889, 'اِلْتِئَامٌ', 'التئام', 'مصدر', 'لأم', 'التءام', 'لتم', 'مص. اِلْتَأَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِئَامٌ-اِلْتِئَامٌ [ل أ م] (مص. اِلْتَأَمَ). 1.""لَمْ يَكُنْ مِنَ السَّهْلِ الْتِئَامُ الجُرْحِ"" : اِلْتِحَامُهُ. 2.""اِسْتَغْرَقَ الْتِئَامُ عَظْمِهِ الْمَكْسُورِ شَهْراً"" : جَبْرُهُ. 3.""جِرَاحُ النَّفْسِ لَيْسَ لَهَا الْتِئَامٌ"" : لاَ جَبْرَ لَهَا، لاَ الْتِحَامَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17890, 'أَكْلٌ', 'أكل', 'مصدر', 'أكل', 'ءكل', 'كل', 'مص. أكَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أَكْلٌ-أَكْلٌ [أ ك ل] (مص. أكَلَ). 1. ""قَدَّمَ لَهُ أكْلاً شَهِيّاً"": الوَجْبَةُ، الطَّعَامُ، أَيْ مَا يُؤْكَلُ. ""أَكْلٌ فَاخِرٌ"" ""أكْلٌ بَلَدِيٌّ"". 2.""اِنْتَقَلَ الضُّيُوفُ إلَى غُرْفَةِ الأكْلِ لِتَنَاوُلِ العَشَاءِ"" : غُرْفَةٌ مُخَصَّصَةٌ لِتَنَاوُلِ الطَّعَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17891, 'إِكْلاَلٌ', 'إكلال', 'مصدر', 'كلل', 'ءكلال', 'إكلل', 'مص. أكَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِكْلاَلٌ-إِكْلاَلٌ [ك ل ل] (مص. أكَلَّ). 1.""إِكْلاَلُ البَصَرِ"": صَيْرُهُ ضَعِيفاً. 2.""إِكْلاَلُ الدَّابَّةِ"" : إعْيَاؤُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17892, 'إِكْمَالٌ', 'إكمال', 'مصدر', 'كمل', 'ءكمال', 'إكمل', 'مص. أكْمَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِكْمَالٌ-إِكْمَالٌ [ك م ل] (مص. أكْمَلَ). 1.""لَمْ يَكُنْ لِيَقْوَى عَلَى إِكْمَالِ دَوْرَةِ السِّبَاقِ"" : إتْمَامِهَا. 2.""خَيْرُ الأعْمَالِ بِالإكْمَالِ"" : بِإنْجَازِهَا بِالتَّمَامِ وَالكَمالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17893, 'مَآلٌ', 'مآل', 'مصدر', 'أول', 'مءءل', 'مآل', 'مص. آل', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَآلٌ-مَآلٌ [أ و ل] (مص. آل). 1.""مَآلُهُ الفَشَلُ"" : نِهَايَتُهُ، نَتِيجَتُهُ. 2.""مَآلُ الكَلاَمِ"" : مَفَادُهُ. 3.""مَآلُ النَّفْسِ"" : مَرْجِعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17894, 'أَوْلٌ', 'أول', 'مصدر', 'أول', 'ءول', 'ل', 'مص. آلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أَوْلٌ-أَوْلٌ [أ و ل] (مص. آلَ). ""كَانَ فِي انْتِظَارِ أوْلِهِ"" : أَوْبٌ، رُجُوعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17895, 'إِيالَةٌ', 'إيالة', 'مصدر', 'أول', 'ءيالة', 'إلة', 'مص. آلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِيالَةٌ-إِيالَةٌ [أ و ل] (مص. آلَ). 1."" مَقَرَّ الإيَالَةِ"" : إقْلِيمٌ أَوْ جِهَةٌ يَحْكُمُهَا وَالٍ. 2.: الوادِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17896, 'إِلاَنَةٌ', 'إلانة', 'مصدر', 'لين', 'ءلانة', 'إلنة', 'مص. أَلاَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِلاَنَةٌ-إِلاَنَةٌ [ل ي ن] (مص. أَلاَنَ). ""إلاَنَةُ مَعْدِنٍ"" : جَعْلُهُ لَيْناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17897, 'إلْبَاسٌ', 'إلباس', 'مصدر', 'لبس', 'ءلباس', 'إلبس', 'مص. أَلْبَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إلْبَاسٌ-إلْبَاسٌ [ل ب س] (مص. أَلْبَسَ). ""إلْبَاسُهُ قَمِيصاً"": جَعْلُهُ يَلْبَسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17898, 'اِلْتِياعٌ', 'التياع', 'مصدر', 'لوع', 'التياع', 'لتع', 'مص. اِلْتاعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِياعٌ-اِلْتِياعٌ [ل و ع] (مص. اِلْتاعَ). ""اِلْتِيَاعُ القَلْبِ"": اِحْتِرَاقُهُ مِنَ الهَمِّ أَوِ الشَّوْقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17899, 'اِلْتِبَاسٌ', 'التباس', 'مصدر', 'لبس', 'التباس', 'لتبس', 'مص. اِلْتَبَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِبَاسٌ-اِلْتِبَاسٌ [ل ب س] (مص. اِلْتَبَسَ). 1.""لَيْسَ فِي الأَمْرِ الْتِبَاسٌ"" : غُمُوضٌ، اِشْتِبَاهٌ، إِشْكَالٌ، اِخْتِلاَطٌ. ""رَفْعاً لكُلِّ الْتِبَاسٍ"". 2.""أحَاطَ بِهِ الاِلْتِبَاسُ"" : اِكْتَنَفَهُ الغُمُوضُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17900, 'اِلْتِبَاكٌ', 'التباك', 'مصدر', 'لبك', 'التباك', 'لتبك', 'مص. اِلْتَبَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِبَاكٌ-اِلْتِبَاكٌ [ل ب ك] (مص. اِلْتَبَكَ). ""اِلْتِبَاكُ أمْرٍ"" : اِخْتِلاَطُهُ، اِلْتِبَاسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17901, 'اِلْتِجَاءٌ', 'التجاء', 'مصدر', 'لجأ', 'التجاء', 'لتج', 'مص. اِلْتَجَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِلْتِجَاءٌ-اِلْتِجَاءٌ [ل ج أ] (مص. اِلْتَجَأَ). 1.""الالْتِجَاءُ إلَى الأقارِبِ"" : الاحْتِمَاءُ بِهِم. 2.""كَانَ الْتِجَاءُ الجَيْشِ إلَى مَعَاقِلِهِ بِدَايَةَ الهَزِيمَةِ"" : اِعْتِصَامُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17902, 'اِلْتِحَافٌ', 'التحاف', 'مصدر', 'لحف', 'التحاف', 'لتحف', 'مص. اِلْتَحَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِحَافٌ-اِلْتِحَافٌ [ل ح ف] (مص. اِلْتَحَفَ). ""لَمْ يَكُنِ اِلْتِحَافُهَا حَيَاءً بَلْ تَنَكُّراً"" : لِبَاسُهَا لِلِّحَافِ. ""حَيْثُ الأشْجَارُ وَالصُّخُورُ الْمُلْتَحِفَةُ بِالثُّلُوجِ الْتَحَافَ الأَمْوَاتِ بِالأكْفَانِ"". (جبران خ. جبران)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17903, 'اِلْتِحَاقٌ', 'التحاق', 'مصدر', 'لحق', 'التحاق', 'لتحق', 'مص. اِلْتَحَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِحَاقٌ-اِلْتِحَاقٌ [ل ح ق] (مص. اِلْتَحَقَ). 1.""الالْتِحَاقُ بِالرَّكْبِ"" : إدْرَاكُهُ. 2.""قَرَّرَ الالْتِحَاقَ بِمُؤَسَّسَةٍ جَدِيدَةٍ"" : الانْضِمَامِ إلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17904, 'اِلْتِحَامٌ', 'التحام', 'مصدر', 'لحم', 'التحام', 'لتحم', 'مص. اِلتَحَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِحَامٌ-اِلْتِحَامٌ [ل ح م] (مص. اِلتَحَمَ). 1.""اِلْتِحَامُ الَجيْشَيْنِ"": اِشْتِبَاكُهُمَا. 2.""عَبَّرَتْ مَوَاقِفُهُمَا عَنِ الْتِحَامٍ مَتِينٍ"": عَنْ تَضَامُنٍ، اِتِّحَادٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17905, 'اِلْتِحَاءٌ', 'التحاء', 'مصدر', 'لحي', 'التحاء', 'لتح', 'مص. اِلْتَحَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِلْتِحَاءٌ-اِلْتِحَاءٌ [ل ح ي] (مص. اِلْتَحَى). 1.""اِلْتِحَاءُ الرّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17906, 'اِلْتِذاذٌ', 'التذاذ', 'مصدر', 'لذذ', 'التذاذ', 'لتذذ', 'مص. اِلْتَذَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِذاذٌ-اِلْتِذاذٌ [ل ذ ذ] (مص. اِلْتَذَّ). ""الالْتِذاذُ بِالطَّعامِ"" : التَّلَذُّذُ بِهِ، أَي عِنْدَما يَكونُ لَذِيذاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17907, 'اِلْتِزَاقٌ', 'التزاق', 'مصدر', 'لزق', 'التزاق', 'لتزق', 'مص. اِلْتَزَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِزَاقٌ-اِلْتِزَاقٌ [ل ز ق] (مص. اِلْتَزَقَ). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17908, 'اِلْتِزَامٌ', 'التزام', 'مصدر', 'لزم', 'التزام', 'لتزم', 'مص. اِلْتَزَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِلْتَزَمَ). 1.""تَعَهَّدَ بِالْتِزَامِ الصَّمْتِ"" : تَعَهَّدَ بِأنْ يَفْرِضَ عَلَى نَفْسِهِ الصَّمْتَ، أَيْ أنْ يُلْزِمَهَا ذَلِكَ. 2.""يَعْرِفُونَ الْتِزَامَ حُدُودِهِمْ"" : وُجُوبَ الوُقُوفِ عِنْدَ حُدُودٍ مُعَيَّنَةٍ. 3.""الالْتِزَامُ فِي الأَدَبِ"" : تَع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17909, 'اِلْتِصَاقٌ', 'التصاق', 'مصدر', 'لصق', 'التصاق', 'لتصق', 'مص. اِلْتَصَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِصَاقٌ-اِلْتِصَاقٌ [ل ص ق] (مص. اِلْتَصَقَ). 1.""اِلْتِصَاقُ الأوْرَاقِ"" : صَيْرُها مُلْتَصِقَةً، اِلْتِزَاقُهَا. 2.""الاِلْتِصَاقُ بِالأَهْلِ"": التَّعَلُّقُ بِهِمْ وَالاِلْتِحَامُ بِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17910, 'اِلْتِطَامٌ', 'التطام', 'مصدر', 'لطم', 'التطام', 'لتطم', 'مص. اِلْتَطَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِطَامٌ-اِلْتِطَامٌ [ل ط م] (مص. اِلْتَطَمَ). 1.""اِلْتِطَامُ الأَوْلاَدِ"" : لَطْمُ بَعْضِهِمْ بَعْضاً. 2.""اِلْتِطَامُ الأَمْوَاجِ"" : تَلاطُمُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17911, 'اِلْتِفَافٌ', 'التفاف', 'مصدر', 'لفف', 'التفاف', 'لتفف', 'مص. اِلْتَفَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِفَافٌ-اِلْتِفَافٌ [ل ف ف] (مص. اِلْتَفَّ). 1.""الالْتِفَافُ باِلغِطَاءِ"" : الاشْتِمَالُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17912, 'اِلْتِفَاتٌ', 'التفات', 'مصدر', 'لفت', 'التفات', 'لتفت', 'مص. اِلْتَفَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِفَاتٌ-اِلْتِفَاتٌ [ل ف ت] (مص. اِلْتَفَتَ). ""الالْتِفَاتُ إلَى الْوَرَاءِ"" : مَيْلُ الوَجْهِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17913, 'اِلْتِقَاطٌ', 'التقاط', 'مصدر', 'لقط', 'التقاط', 'لتقط', 'مص. اِلْتَقَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِقَاطٌ-اِلْتِقَاطٌ [ل ق ط] (مص. اِلْتَقَطَ). 1. ""اِلْتِقَاطُ دِرْهَمٍ بالأرْضِ"" : وُجُودُهُ مُصَادَفَةً. 2. ""اِلْتِقَاطُ الحَبِّ"" : جَمْع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17914, 'اِلْتِقَافٌ', 'التقاف', 'مصدر', 'لقف', 'التقاف', 'لتقف', 'مص. اِلْتَقَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِقَافٌ-اِلْتِقَافٌ [ل ق ف] (مص. اِلْتَقَفَ). ""اِلْتِقَافُ الطَّعَامِ"": تَنَاوُلُهُ بِسُرْعَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17915, 'اِلْتِقَامٌ', 'التقام', 'مصدر', 'لقم', 'التقام', 'لتقم', 'مص. اِلْتَقَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِقَامٌ-اِلْتِقَامٌ [ل ق م] (مص. اِلْتَقَمَ). ""اِلْتِقَامُ اللُّقْمَةِ"" : اِبْتِلاعهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17916, 'اِلْتِقَاءٌ', 'التقاء', 'مصدر', 'لقي', 'التقاء', 'لتق', 'مص. اِلْتَقَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِلْتِقَاءٌ-اِلْتِقَاءٌ [ل ق ي] (مص. اِلْتَقَى). 1.""الالْتِقَاءُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17917, 'اِلْتِمَاسٌ', 'التماس', 'مصدر', 'لمس', 'التماس', 'لتمس', 'مص. اِلْتَمَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِمَاسٌ-اِلْتِمَاسٌ [ل م س] (مص. اِلْتَمَسَ). 1.""اِلْتِمَاسُ العَفْوِ"": طَلَبُهُ، رَجَاؤُهُ. 2.""اِلْتِمَاسُ العُذْرِ"" : إيِجَادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17918, 'اِلْتِهَابٌ', 'التهاب', 'مصدر', 'لهب', 'التهاب', 'لتهب', 'مص. اِلْتَهَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِهَابٌ-اِلْتِهَابٌ [ل هـ ب] (مص. اِلْتَهَبَ). 1.""أُصِيبَ بِالْتِهَابٍ فِي حَنْجَرَتِهِ"" : بِاحْمِرَارٍ. 2.""أَصَابَهُ التِهَابٌ فِي أمْعَائِهِ"": اِحْتِرَاقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17919, 'اِلْتِهَافٌ', 'التهاف', 'مصدر', 'لهف', 'التهاف', 'لتهف', 'مص. اِلْتَهَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِهَافٌ-اِلْتِهَافٌ [ل هـ ف] (مص. اِلْتَهَفَ). ""اِلْتِهَافُ الرَّجُلِ"" : تَحَرُّقُهُ من مُصِيبَةٍ أَصَابَتْهُ وَأَلَمَّتْ بِه."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17920, 'اِلْتِهَامٌ', 'التهام', 'مصدر', 'لهم', 'التهام', 'لتهم', 'مص. اِلْتَهَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِلْتِهَامٌ-اِلْتِهَامٌ [ل هـ م] (مص. اِلْتَهَمَ). 1.""اِلْتِهَامُ الطَّعَامِ"": اِبْتِلاَعُهُ بِسُرْعَةٍ، اِلْتِقَافُهُ، اِبْتِلاَعُهُ لُقْمَةً وَاحِدَةً. 2.""اِلْتِهَامُ النِّيرانِ لِكُلِّ شَيْءٍ"" : حَرْقُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17921, 'اِلْتِوَاءٌ', 'التواء', 'مصدر', 'لوي', 'التواء', 'لت', 'مص. اِلْتَوَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِلْتِوَاءٌ-اِلْتِوَاءٌ [ل و ي] (مص. اِلْتَوَى). 1.""اِلْتِوَاءُ الحَبْلِ"": اِلْتِفَافُهُ، اِنْثِنَاؤُهُ. 2.""اِلْتِوَاءُ الأُمُورِ"" : اِخْتِلاَطُهَا، عُسْرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17922, 'إلْجَاءٌ', 'إلجاء', 'مصدر', 'لجأ', 'ءلجاء', 'إلج', 'مص. ألْجَأ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إلْجَاءٌ-إلْجَاءٌ [ل ج أ] (مص. ألْجَأ). ""إلْجَاءُ الْمُتَّهَمِ إلَى الاعْتِرَافِ بِالحَقِيقَةِ"" : اِضْطِرَارُهُ، إكْرَاهُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17923, 'إلْجَامٌ', 'إلجام', 'مصدر', 'لجم', 'ءلجام', 'إلجم', 'مص. ألْجَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إلْجَامٌ-إلْجَامٌ [ل ج م] (مص. ألْجَمَ). 1.""إلْجَامُ الفَرَسِ"" : إلْبَاسُهُ اللِّجَامَ. 2.""إِلْجَامُ الأَهْوَاءِ"" : الحَدُّ مِنْ تَصَرُّفِهَا وَشَطَطِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17924, 'إلْحَادٌ', 'إلحاد', 'مصدر', 'لحد', 'ءلحاد', 'إلحد', 'مص. ألْحَد', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إلْحَادٌ-إلْحَادٌ [ل ح د] (مص. ألْحَد). ""لاَ إلْحَادَ لِمَنْ أَسْلَمَ"": لاَ كُفْرَ، لاَ ارْتِدَادَ. ""رَمَوْهُ بِالإِلْحَادِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17925, 'إِلْحَافٌ', 'إلحاف', 'مصدر', 'لحف', 'ءلحاف', 'إلحف', 'مص. ألْحَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِلْحَافٌ-إِلْحَافٌ [ل ح ف] (مص. ألْحَفَ). ""إلْحَافُ السَّائِلِ"": إلْحَاحُهُ وَإصْرَارُهُ. البقرة آية 273لاَ يَسْألُونَ النَّاسَ إلْحَافاً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17926, 'إلْحَاقٌ', 'إلحاق', 'مصدر', 'لحق', 'ءلحاق', 'إلحق', 'مص. ألَحَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إلْحَاقٌ-إلْحَاقٌ [ل ح ق] (مص. ألَحَقَ). 1.""إلْحَاقُهُ بِمَجْمُوعَةٍ أُخْرَى"" : جَعْلُهُ يَلْتَحِقُ. ضمُّهُ إلَى... 2.""إلْحَاقُ مُوَظَّفٍ آخَرَ بِالقِسْمِ الإدَارِيِّ"" : تَعْيِينُهُ، ضَمُّهُ، تَوْظِيفُهُ. 3.""إلْحَاقُ خَسَائِرَ بِالعَدُوِّ"" : تَكْبِيدُهُ خَسَائِرَ، إنْزَالُهَا بِه. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17927, 'إلْحَامٌ', 'إلحام', 'مصدر', 'لحم', 'ءلحام', 'إلحم', 'مص. أَلْحَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إلْحَامٌ-إلْحَامٌ [ل ح م] (مص. أَلْحَمَ). ""إِلْحَامُ إبْرِيقٍ"" : إلْصَاقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17928, 'إِلْزاقٌ', 'إلزاق', 'مصدر', 'لزق', 'ءلزاق', 'إلزق', 'مص. أَلْزَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِلْزاقٌ-إِلْزاقٌ [ل ز ق] (مص. أَلْز"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17929, 'إِلْزَامٌ', 'إلزام', 'مصدر', 'لزم', 'ءلزام', 'إلزم', 'مص. ألْزَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِلْزَامٌ-إِلْزَامٌ [ل ز م] (مص. ألْزَمَ). ""أَنْجَزَ الشُّغْلَ إلْزَاماً"" : لَمْ يَكُنْ لَهُ اخْتِيَارٌ فِي إنْجَازِهِ، أنْجَزَهُ كَرْهاً، فَرْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17930, 'إلْغَاءٌ', 'إلغاء', 'مصدر', 'لغو', 'ءلغاء', 'إلغ', 'مص. ألْغَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إلْغَاءٌ-إلْغَاءٌ [ل غ و] (مص. ألْغَى). ""تَقَرَّرَ إِلْغَاءُ دَوْرَةِ أكتوبر"" : إِبْطَال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17931, 'إيلاَفٌ', 'إيلاف', 'مصدر', 'ألف', 'ءيلاف', 'إلف', 'مص. آلَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إيلاَفٌ-إيلاَفٌ [أ ل ف] (مص. آلَفَ). 1.""إيلاَفُ الْمَكَانِ"" : تَعَوُّدُهُ. 2.قريش آية 1،2 لإيَلافِ قُرَيْشٍ إِيلاَفِهِمْ رِحْلَة (قرآن).: حُسْنُ التَّدْبِيرِ، العَهْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17932, 'مُؤَالَفَةٌ', 'مؤالفة', 'مصدر', 'ألف', 'مءالفة', 'ملفة', 'مص. آلَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُؤَالَفَةٌ-مُؤَالَفَةٌ [أ ل ف] (مص. آلَفَ). ""يَجِدُ عِنْدَهُ كُلَّ مُؤَالَفَةٍ"" : كُلَّ مُؤَانَسَةٍ، مُعَاشَرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17933, 'تَأْلِيفٌ', 'تأليف', 'مصدر', 'ألف', 'تءليف', 'تلف', 'مص. أَلَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَآلِيفُ"', '', 'R', '', '', '', '', '', '', '"(مص. أَلَّفَ). 1.""هَذَا الكِتَابُ مِنْ تَأْلِيفِهِ"" : مَنْ وَضْعِهِ، أَيْ هُوَ الَّذِي كَتَبَهُ، أَيْ أَلَّفَهُ. 2.""يَتَطَلَّبُ تَأْلِيفُ كِتَابٍ مَعْرِفَةً تَامَّةً بِمَادَّتِهِ"" : تَجْمِيعُ مَعْلُومَاتِهِ أَوْ تَحْلِيلُهَا أَوْ نَقْدُهَا فِي عِلْمٍ مِنَ العُلُومِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17934, 'تَآلِيفُ', 'تآليف', 'مصدر', '', 'تءءليف', 'تآلف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17935, 'إِلاَفٌ', 'إلاف', 'مصدر', 'ألف', 'ءلاف', 'إلف', 'مص. أَلِفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِلاَفٌ-إِلاَفٌ [أ ل ف] (مص. أَلِفَ). العَهْدُ وَالأَمَانُ، أَيْ ما يُؤْخَذُ لِتَأْمِينِ خُرُوجِ التُّجارِ منَ البِلاَدِ إلَى بِلاَدٍ أُخْرَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17936, 'أَلْفٌ', 'ألف', 'مصدر', 'ألف', 'ءلف', 'لف', 'مص. أَلِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أَلْفٌ-أَلْفٌ [أ ل ف] (مص. أَلِفَ). ""كَانَ بَيْنَهُمَا إِلْفٌ وَمَحَبَّةٌ"" : أُلْفَةٌ، صَدَاقَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17937, 'ألْقٌ', 'ألق', 'مصدر', 'ألق', 'ءلق', 'لق', 'مص. أَلَقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ألْقٌ-ألْقٌ [أ ل ق] (مص. أَلَقَ). ""ألْقُ البَرْقِ"": لَمَعَانُهُ، إضَاءَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17938, 'إلْقَاحٌ', 'إلقاح', 'مصدر', 'لقح', 'ءلقاح', 'إلقح', 'مص. ألْقَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إلْقَاحٌ-إلْقَاحٌ [ل ق ح] (مص. ألْقَحَ). 1.""إلْقَاحُ الطَّعَامِ"" : لَقْمُهُ، أَكْلُهُ. 2.""إلْقَامُهُ حَجَراً"" : إسْكَاتُهُ، إفْحَامُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17939, 'إِلْقَاءٌ', 'إلقاء', 'مصدر', 'لقي', 'ءلقاء', 'إلق', 'مص. أَلْقَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِلْقَاءٌ-إِلْقَاءٌ [ل ق ي] (مص. أَلْقَى). 1.""إِلْقَاءُ الشَّبَكَةِ فِي البَحْرِ"" : رَمْيُها. 2.""إِلْقاءُ مُحَاضَرَةٍ"" : إعْطَاؤُهُا، أَي الحَدِيثُ فِي مَوْضُوعٍ أَمَامَ جَمْهُورٍ. 3.""قَرَّرُوا إِلْقَاءَ سِلاَحِهِمْ"" : أ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17940, 'إِلْمَامٌ', 'إلمام', 'مصدر', 'لمم', 'ءلمام', 'إلمم', 'مص. أَلَمَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِلْمَامٌ-إِلْمَامٌ [ل م م] (مص. أَلَمَّ). 1.""إِلْمَامُ الْمَرَضِ بِالرَّجُلِ"": إصَابَتُهُ بِهِ. 2.""الإِلْمَامُ بِالْمَوْضُوعِ"" : مَعْرِفَتُهُ، وَفَهْمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17941, 'ألَمٌ', 'ألم', 'مصدر', 'ألم', 'ءلم', 'لم', 'مص. أَلِمَ', '', '', 'مفرد', 'DnN', '', '', '"آلاَمٌ"', '', 'R', '', '', '', '', '', '', '"(مص. أَلِمَ). 1.""كَسَّرْتُ يَدَهُ فَصَرَخَ مِنَ الألَمِ"" : مِنَ الوَجَعِ. ""أَشْعُرُ بِألَمٍ فِي رَأْسِي"". 2.""عَلِمَ بِوَفَاةِ قَرِيبٍ لَهُ، فَشَعَرَ بِألَمٍ عَمِيقٍ"" : أحَسَّ بِحُزْنٍ وَأَسىً مُوجِعٍ. ""يُعَانِي آلاماً كَثِيرَةً"" ""ظَلَّتِ الآلامُ تَعْصِفُ بِهِ"" ""آلاَمُ الْمَخَاضِ"" ""آلاَمُ السَّيِّدِ الْمَسِيحِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17942, 'آلاَمٌ', 'آلام', 'مصدر', '', 'ءءلام', 'آلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17943, 'وَرْدَةٌ', 'وردة', 'مصدر', 'ورد', 'وردة', 'ردة', 'مص الْمَرَّة', '', '', 'مفرد', 'DnN', '', 'Pf', '":وَاحِدَةُالوَرْدِ"', '', 'R', '', '', '', '', '', '', '"(اِسْمُ الْمَرَّة). 1.""أَهْدَاهَا وَرْدَةً"" : أَيْ زَهْرَةَ الوَرْدِ. 2.""عَشِيَّةٌ وَرْدَةٌ"" : إِذَا اِحْمَرَّ أُفُقُها عِنْدَ غُرُوبِ الشَّمْسِ أَو طُلُوعِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17944, 'إِيمَاءةٌ', 'إيماءة', 'مصدر', 'ومأ', 'ءيماءة', 'إمة', 'مص الْمَرَّة', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"(اِسْمُ الْمَرَّةِ). ""إيمَاءةٌ مُعَبِّرَةٌ"" : حَرَكَةٌ، إشَارَةٌ، لَفْتَةٌ بِوَاسِطَةِ عُضْوٍ مِنْ أعْضَاءِ الجِسْمِ أَوْ مَلاَمِحِ الوَجْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17945, 'أَكْلَةٌ', 'أكلة', 'مصدر', 'أكل', 'ءكلة', 'كلة', 'مص. الْمَرَّةُ مِنَ الأكْلِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنَ الأكْلِ) (طخ). ""يَتَنَاوَلُ أَكْلَتَيْنِ فِي اليَوْمِ"" : وَجْبَتَيْنِ. ""وَرُبَّ أَكْلَةٍ مَنَعَتْ أَكْلاَتٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17946, 'تَسْبِيحَةٌ', 'تسبيحة', 'مصدر', 'سبح', 'تسبيحة', 'تسبحة', 'مص. الْمَرَّةُ مِنَ التَّسْبِي', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَسَابِيحُ"', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنَ التَّسْبِيحِ). ""يُرَدِّدُ التَّسَابِيحَ فِي أَمَاسِيهِ"" : أَيْ يُرَدِّدُ ""سُبْحَانَ اللَّهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17947, 'تَسَابِيحُ', 'تسابيح', 'مصدر', '', 'تسابيح', 'تسبح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17948, 'خَطْوَةٌ', 'خطوة', 'مصدر', 'خطو', 'خطوة', 'خطة', 'مص. الْمَرَّةُ مِنَ الْخَطْوِ', '', '', 'مفرد', 'DnN', '', 'Pf', '":خِطَاءٌ"', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنَ الْخَطْوِ). ""مَسَافةُ الخَطْوَةِ"" : سِتَّةُ أَقْدَامٍ، أيْ مَسَافَةٌ مَا بَيْنَ القَدَمَيْنِ عِنْدَ الخَطْوِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17949, 'خِطَاءٌ', 'خطاء', 'مصدر', '', 'خطاء', 'خط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17950, 'ذَمَّةٌ', 'ذمة', 'مصدر', 'ذمم', 'ذمة', 'ذمة', 'مص. الْمَرَّةُ مِنَ الذّمِّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"ذَمَّةٌ-ذَمَّةٌ [ذ م م] (الْمَرَّةُ مِنَ الذّمِّ). ""بِئْرٌ ذَمَّةٌ"" : قَلِيلَةُ الْمَاءِ. فأتَيْنَا عَلَى بِئْرٍ ذَمَّةٍ فَنَزَلْنا فِيهَا (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17951, 'رَجْعَةٌ', 'رجعة', 'مصدر', 'رجع', 'رجعة', 'رجعة', 'مص. الْمَرَّةُ مِنَ الرُّجُوعِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(الْمَرَّةُ مِنَ الرُّجُوعِ). 1. ""لِيَذْهَبَ دُونَ رَجْعَةٍ"" : مِنْ غَيْرِ عَوْدَةٍ. ""ذَهَبَ إلَى غَيْرِ رَجْعَةٍ"". 2. ""لاَ رَجْعَةَ فِي القَرَارِ"" : لَيْسَ بِالإِمْكَانِ العُدُولُ عَنْهُ، التَّخَلِّي عَنْهُ. 3. ""الرَّجْعَةُ"" : عَوْدُ الْمُطَلَّقِ إلَى مُطَلَّقَتِهِ. 4.""يُؤْمِنُ بِالرَّجْعَةِ"" : مَذْهَبُ الرُّجُوعِ إلَى الحَيَاةِ الدُّنْيَا بَعْدَ الموْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17952, 'سَجْدَةٌ', 'سجدة', 'مصدر', 'سجد', 'سجدة', 'سجدة', 'مص. الْمَرَّةُ مِنَ السُّجُودِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَجْدَةٌ-سَجْدَةٌ [س ج د] (المرَّةُ مِنَ السُّجُودِ). ""السَّجْدَةُ"" : سُورَةٌ مِن سُوَرِ القُرْآنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17953, 'سَكْرَةٌ', 'سكرة', 'مصدر', 'سكر', 'سكرة', 'سكرة', 'مص. الْمَرَّةُ مِنَ السُّكْرِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنَ السُّكْرِ). ""اِشْتَدَّتْ عَلَيْهِ سَكْرَةُ الْمَوْتِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17954, 'سَهْرَةٌ', 'سهرة', 'مصدر', 'سهر', 'سهرة', 'سهرة', 'مص. الْمَرَّةُ مِنَ السَّهَرِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(المرَّةُ مِنَ السَّهَرِ). 1. ""أحْيَتِ الفِرْقَةُ سَهْرَةً مُوسِيقِيَّةً"" : حَفْلةً مُوسِيقَيَّةً لَيْلاً. 2.""اِرْتَدَى لِبَاسَ السَّهْرَةِ لِحُضُورِ الحَفْلَةِ"" : لِبَاسٌ أنِيقٌ خَاصٌّ بِالحَفَلاَتِ السَّاهِرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17955, 'غَزْوَةٌ', 'غزوة', 'مصدر', 'غزو', 'غزوة', 'غزة', 'مص. الْمَرَّةُ مِنَ الغَزْوِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنَ الغَزْوِ). ""غَزْوَةُ بَدْرٍ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17956, 'نَبْعَةٌ', 'نبعة', 'مصدر', 'نبع', 'نبعة', 'نبعة', 'مص. الْمَرَّةُ مِنَ النَّبْعِ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَبْعَةٌ-نَبْعَةٌ [ن ب ع] (الْمَرَّةُ مِنَ النَّبْعِ). ""مِثْلُ نَبْعَةٍ انْبَثَقَتْ هَادِرَةً"" : دَفْقَةٍ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17957, 'بَصْقَةٌ', 'بصقة', 'مصدر', 'بصق', 'بصقة', 'بصقة', 'مص. الْمَرَّةُ مِنْ بَصَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَصْقَةٌ-بَصْقَةٌ [ب ص ق] (الْمَرَّةُ مِنْ بَصَقَ). ""أَلْقَى بَصْقَةً"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17958, 'جَلْسَةٌ', 'جلسة', 'مصدر', 'جلس', 'جلسة', 'جلسة', 'مص. الْمَرَّةُ مِنْ جَلَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ جَلَسَ). 1.""الجَلْسَةُ مَعَ الأَصْدِقاءِ"" : القَعْدَةُ. 2.""عَقَدَتِ الْمَحْكَمَةُ جَلْسَةً صَبَاحِيَّةً"" : فَتْرَةَ التَّدَاوُلِ وَالْمُرَافَعَةِ. ""جَلْسَةٌ سِرِّيَّةٌ"" ""جَلْسَةٌ طَارِئَةٌ"" ""جَلْسَةٌ مُغْلَقَةً"" ""جَلْسَةٌ عَلَنِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17959, 'حَيْضَةٌ', 'حيضة', 'مصدر', 'حيض', 'حيضة', 'حضة', 'مص. الْمَرَّةُ من حَاضَ يَحِيض', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَيْضَةٌ-حَيْضَةٌ [ح ي ض] (الْمَرَّة من حَاضَ يَحِيضُ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17960, 'حَوْمَةٌ', 'حومة', 'مصدر', 'حوم', 'حومة', 'حمة', 'مص. الْمَرَّةُ مِنْ حَامَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ حَامَ). 1.""اِشْتَدَّ القِتَالُ فِي حَوْمَةِ الوَغَى"" : فِي سَاحَةِ الحَرْبِ، أيْ أشَدُّ مَوْضِعٍ فِيهِ. 2. ""حَوْمَةُ البَحْرِ"" : مُعْظَمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17961, 'حَسْوَةٌ', 'حسوة', 'مصدر', 'حسو', 'حسوة', 'حسة', 'مص. الْمَرَّةُ مِنْ حَسَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَسْوَةٌ-حَسْوَةٌ [ح س و] (الْمَرَّةُ مِنْ حَسَا). تَجَرَّعَ حَسْوَةً"": جُرْعَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17962, 'دَفْعَةٌ', 'دفعة', 'مصدر', 'دفع', 'دفعة', 'دفعة', 'مص. الْمَرَّةُ مِنْ دَفَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"دَفْعَةٌ-دَفْعَةٌ [د ف ع] (الْمَرَّةُ مِنْ دَفَعَ). 1. ""تَوَصَّلَ بِالدَّفْعَةِ الأُولَى مِنَ البِضَاعَةِ"" : الحِصَّة، الجُزْء. 2. ""قَدَّمَ دَفْعَةً مِنَ الحِسَابِ"" : أيْ حِصَّةً مِنَ الْمَالِ، قِسْطاً. ""الدَّفْعَةُ الثَّانِيَةُ مِنَ الدَّيْنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17963, 'رَجْفَةٌ', 'رجفة', 'مصدر', 'رجف', 'رجفة', 'رجفة', 'مص. الْمَرَّةَُ مِنْ رَجَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةَ مِنْ رَجَفَ). 1.""أَخَذَتْهُ رَجْفَةٌ مِنَ البَرْدِ"" : رَعْشَةٌ. 2.""رَجْفَةُ الأَرْضِ"" : الزَّلْزَلَةُ الشَّدِيدَةُ. الأعراف آية 78 فَأخَذَتْهُمُ الرَّجْفَةُ فَأصْبَحُوا فِي دَارِهِمْ جَاثِمِينَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17964, 'رَدَّةٌ', 'ردة', 'مصدر', 'ردد', 'ردة', 'ردة', 'مص. الْمَرَّةُ مِنْ رَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"رِدَّةٌ-رِدَّةٌ [ر د د] (الاسْمُ مِنَ الارْتِدَادِ). 1. ""قَضَى عَلَى أهْلِ الرِّدَّةِ"" : الجَمَاعَةُ الَّتِي ارْتَدَّتْ عَنِ الإسْلاَمِ بَعْدَ مَوْتِ النَّبِيِّ( . ""حَرْبُ الرِّدَّةِ"" 2. ""لِمَ هَذِهِ الرِّدَّةُ "" : لِمَ التَّخَلِّي عَنِ الْمُعْتَقَدَاتِ والْمَبَادِئِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17965, 'رَقْصَةٌ', 'رقصة', 'مصدر', 'رقص', 'رقصة', 'رقصة', 'مص. الْمَرَّةُ مِنَ رَقَصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنَ رَقَصَ). ""رَقْصَةُ كَذَا"" : تَشْكيلُ دائِرَةٍ مِنَ الرَّاقِصينَ أَوِ الرَّاقِصاتِ لأَداءِ حَرَكاتِ مُعَيَّنَةٍ بِالأَيْدِي والأَرْجُلِ على أَنْغامِ إِيقاعاتٍ موسِيقِيَّةٍ. ""رَقْصَةُ الدَّبْكَةِ، رَقْصَةٌ شَرْقِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17966, 'رَكْعَةٌ', 'ركعة', 'مصدر', 'ركع', 'ركعة', 'ركعة', 'مص. الْمَرَّةُ مِنْ رَكَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ رَكَعَ). ""أَدَّى الْمُصَلِّي الرَّكْعَةَ الأُولَى"" : الاِنْحِناءةَ الأولَى،كُلُّ قَوْمَةٍ يَتْلوها الرُّكوعُ والسَّجْدَتانِ. ""تَنْحَصِرُ صَلاةُ الْمَغْرِبِ في ثَلاثِ رَكَعاتٍ، والصُّبْحِ في رَكْعَتَيْنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17967, 'زَأْرَةٌ', 'زأرة', 'مصدر', 'زأر', 'زءرة', 'زرة', 'مص. الْمَرَّةُ مِنْ زَأَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"زَأْرَةٌ-زَأْرَةٌ[ز أ ر] (الْمَرَّةُ مِنْ زَأَرَ). ""زَأَرَ الأَسَدُ زَأْرَةً"" : صَيْحَةً مِنَ الصَّدْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17968, 'زَأْمَةٌ', 'زأمة', 'مصدر', 'زأم', 'زءمة', 'زمة', 'مص. الْمَرَّةُ مِنَ زَأَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"زَأْمَةٌ-زَأْمَةٌ[ز أ م] (الْمَرَّةُ مِنَ زَأَمَ). 1.""زَأَمَ لِي زَأْمَةً"" : طَرَحَ لِي كَلِمَةً لا أَدْرِي أَحَقٌّ هِيَ أَمْ باطِلٌ. 2.""سَمِعَ زَأْمَةً"" : صَوْتاً شَديداً. ""ما سَمِعْتُ لَهُ زَأْمَةً"". 3.""أَخَذَ مِنَ الطَّعامِ زَأْمَتَهُ"": حاجَتهُ. 4.""بِهِ زَأْمَةٌ"" : شِدَّةُ الأَكْلِ والشُّرْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17969, 'زَعْقَةٌ', 'زعقة', 'مصدر', 'زعق', 'زعقة', 'زعقة', 'مص. المرَّة مِنْ زَعَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(المرَّة مِنْ زَعَقَ). ""سَمِعْتُ زَعْقَتَهُ مِنْ بَعيدٍ"" : صَيْحَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17970, 'زَفَّةٌ', 'زفة', 'مصدر', 'زفف', 'زفة', 'زفة', 'مص. الْمَرَّةُ مِنْ زَفَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ زَفَّ). ""صَاحَبَ زَفَّةَ العُرْسِ"" : مَوْكِبَ العُرْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17971, 'زَلَّةٌ', 'زلة', 'مصدر', 'زيل', 'زلة', 'زلة', 'مص. الْمَرَّةُ مِنْ زَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ زَلَّ). 1.""اِرْتَكَبَ زَلَّةً لا تُغْتَفَرُ"" : خَطيئَةً، ذَنْباً. ""كَيْفَ يُمْكِنُ أَنْ يَغْفِرَ لَهُ زَلاَّتِهِ"". 2.""إِنَّها زَلَّةُ لِسانٍ"" : فَلْتَةُ لِسانٍ، زَلْقَةٌ، سَقْطَةٌ ما لَمْ يَكُنْ يُقْصَدُ التَّلَفُّظَ بِهِ. 3.""زَلَّةُ قَلَمٍ"" : سَبْقُ قَلَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17972, 'سَوْرَةٌ', 'سورة', 'مصدر', 'سور', 'سورة', 'سرة', 'مص. الْمَرَّةُ مِنْ سارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سُورَةٌ-سُورَةٌ [س و ر]. 1.""لَهُ عِنْدَكَ سورَةٌ"" : مَنْزِلَةٌ، مَكانَةٌ. 2.""رَتَّلَ سُورَةً مِنَ القُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17973, 'سَقْطَةٌ', 'سقطة', 'مصدر', 'سقط', 'سقطة', 'سقطة', 'مص. الْمَرَّةُ مِنْ سَقَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَقْطَةٌ-سَقْطَةٌ [س ق ط] (الْمَرَّةُ مِنْ سَقَطَ)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17974, 'شَدَّةٌ', 'شدة', 'مصدر', 'شدد', 'شدة', 'شدة', 'مص. الْمَرَّةُ مِن شَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَدَّةٌ-شَدَّةٌ [ش د د] (الْمَرَّةُ مِن شَدَّ). 1.""قَامُوا بِشَدَّةٍ"": بِحَمْلَةٍ، بِهَجْمَةٍ فِي الحَرْبِ. 2.""عَلى الحَرْفِ شَدَّةٌ"" : سِينٌ مُصَغَّرَةٌ ( ـّ ) تُوضَعُ فَوْقَ الحَرْفِ لِتضْعِيفِهِ: كَّـ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17975, 'شَرْبَةٌ', 'شربة', 'مصدر', 'شرب', 'شربة', 'شربة', 'مص. الْمَرَّةُ مِنْ شَرِبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ شَرِبَ). 1.""تَنَاوَلَ شَرْبَةً مِنَ الدَّوَاءِ"" : جُرْعَةً. 2. ""تَنَاوَلَ شَرْبَةً لِتَلِينَ مَعِدَتُهُ"" : الدَّوَاءُ الْمُسَهِّلُ أوِ الْمُلَيِّنُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17976, 'شَعْفَةٌ', 'شعفة', 'مصدر', 'شعف', 'شعفة', 'شعفة', 'مص. الْمَرَّةُ مِنْ شَعَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":شِعَافٌ"', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ شَعَفَ). ""شَعْفَةُ مَطَرٍ"" : قَطْرَةٌ مِنْهُ تَبُلُّ وَجْهَ الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17977, 'شِعَافٌ', 'شعاف', 'مصدر', '', 'شعاف', 'شعف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17978, 'شَكَّةٌ', 'شكة', 'مصدر', 'شكك', 'شكة', 'شكة', 'مص. الْمَرَّةُ مِنْ شَكَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَكَّةٌ-شَكَّةٌ [ش ك ك] (الْمَرَّةُ مِنْ شَكَّ). ""أَصَابَتْهُ شَكَّةٌ"" : أَلَمٌ حَادٌّ مُفَاجِئٌ يُصِيبُ أَحَدَ أَجْزَاءِ الجِسْمِ . الْقَلْبُ أَوِ الرَّأْسُ أَوِ الصَّدْرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17979, 'شَهْقَةٌ', 'شهقة', 'مصدر', 'شهق', 'شهقة', 'شهقة', 'مص. الْمَرَّةُ مِنْ شَهَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَهْقَةٌ-شَهْقَةٌ [ش هـ ق] (الْمَرَّةُ مِنْ شَهَقَ). 1.""وَأَخِيراً شَهِقَ شَهْقَةَ الْمَوْتِ"" : آخِر حَشْرَجَةٍ. 2.""صَدَرَتْ عَنْهُ شَهْقَةٌ"": صَيْحَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17980, 'صَوْغَةٌ', 'صوغة', 'مصدر', 'صوغ', 'صوغة', 'صغة', 'مص. الْمَرَّةُ مِنْ صَاغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَوْغَةٌ-صَوْغَةٌ [ص و غ] (الْمَرَّةُ مِنْ صَاغَ). ""هُوَ صَوْغَةُ أَخِيهِ"" : أَيْ صَوْغُهُ، عَلَى شَاكِلَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17981, 'صَدْمَةٌ', 'صدمة', 'مصدر', 'صدم', 'صدمة', 'صدمة', 'مص. الْمَرَّةُ مِنْ صَدَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ صَدَمَ). 1.""تَعَرَّضَ لِصَدْمَةٍ عَنِيفَةٍ"" : لاهْتِزَازٍ وَارْتِطَامٍ. 2.""صَدْمَةٌ نَفْسِيَّةٌ"": النَّازِلَةُ تُفَاجِئُ الإِنْسَانَ فَتُسَبِّبُ لَهُ قَلَقاً وَإِزْعَاج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17982, 'صَرْعَةٌ', 'صرعة', 'مصدر', 'صرع', 'صرعة', 'صرعة', 'مص. الْمَرَّةُ مِنْ صَرَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَرْعَةٌ-صَرْعَةٌ [ص ر ع] (الْمَرَّةُ مِنْ صَرَعَ). 1.""اِنْتَشَرَتْ صَرْعَةٌ جَدِيدَةٌ بَيْنَ النَّاسِ"" : ظَاهِرَةٌ، حَالَةٌ، نَموذَجٌ، أُسْلُوبٌ فِي اللِّبَاسِ. 2.""عَلَى كُلِّ صَرْعَةٍ"" : عَلَى كُلِّ حَالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17983, 'صَفْعَةٌ', 'صفعة', 'مصدر', 'صفع', 'صفعة', 'صفعة', 'مص. الْمَرَّةُ مِنَ صَفَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنَ صَفَعَ). ""بَقِيَتْ آثَارُ الصَّفْعَةِ عَلَى خَدِّهِ"" : الضَّرْبَةُ عَلَى الخَدِّ بِكَفِّ اليَدِ مَبْسُوطَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17984, 'صَنْعَةٌ', 'صنعة', 'مصدر', 'صنع', 'صنعة', 'صنعة', 'مص. الْمَرَّةُ مِنْ صَنَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَنْعَةٌ-صَنْعَةٌ [ص ن ع] (الْمَرَّةُ مِنْ صَنَعَ). 1.""هَذَا مِنْ صَنْعَتِهِ"" : مِنْ عَمَلِهِ، أَيْ مِنْ عَمَلِ الصَّانِعِ. 2.""هَذِهِ صَنْعَتُهُ"" : هَذِهِ حِرْفَتُهُ. 3.""عَمَلٌ فِيهِ كَثِيرٌ مِنَ الصَّنْعَةِ"": كَثِيرٌ مِنَ التَّكَلُّفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17985, 'ضَجْعَةٌ', 'ضجعة', 'مصدر', 'ضجع', 'ضجعة', 'ضجعة', 'مص. الْمَرَّةُ مِنْ ضَجَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضَجْعَةٌ-ضَجْعَةٌ [ض ج ع] (الْمَرَّةُ مِنْ ضَجَعَ). 1.""يَعِيشُ فِي ضَجْعَةٍ"" : فِي خَفْضٍ مِنَ العَيْشِ، فِي دَعَةٍ. 2.""ضَجَعَ ضَجْعَتَهُ الأَخِيرَةَ"" : رَقْدَتَهُ الأَخِيرَةَ، أَيْ مَاتَ. ""ثَارَ كَمَا يَثُورُ الوَحْشُ مِنْ ضَجْعَتِهِ"". (ص. م. الرافعي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17986, 'ضَرْبَةٌ', 'ضربة', 'مصدر', 'ضرب', 'ضربة', 'ضربة', 'مص. الْمَرَّةُ مِنْ ضَرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ ضَرَبَ). 1.""وَجَّهَ إِلَيْهِ ضَرْبَةً قَاضِيَةً"" : لَكْمَةً كَمَا فِي الْمُلاَكَمَةِ. 2.""ضَرْبَةُ شَمْسٍ"" : حَالَةٌ مَرَضِيَّةٌ شَدِيدَةُ التَّأْثِيرِ، تَنْشَأُ مِنْ تَأْثِيرِ أَشِعَّةِ الشَّمْسِ، قَدْ تُؤَدِّي بِصَاحِبِهَا إِلَى مَوْتٍ مُحَقَّقٍ إِذَا لَمْ يُعَالَجْ فِي حِينِهِ. 3.""عَلَى ضَرْبَةِ مِعْوَلٍ"" : القَرِيبُ الْمَيْسُورُ. 4.""أَعْلَنَ الْحَكَمُ عَنْ ضَرْبَةِ جَزَاءٍ"" (ريا) : القَذْفَةُ الَّتِي يُوَجِّهُهَا اللاَّعِبُ في كُرَةِ القَدَمِ مِنْ نُقْطَةِ الجَزَاءِ إِلَى الحَارِسِ مُبَاشَرَةً، وَتَأْتِي نَتِيجَةَ خَطَإٍ يَرْتَكِبُهُ أَحَدُ اللاَّعِبِينَ الْمُدَافِعِينَ فِي دَاخِلِ مُرَبَّعِ الحَارِسِ. 5.""الضَّرْبَةُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17987, 'ضَغْمَةٌ', 'ضغمة', 'مصدر', 'ضغم', 'ضغمة', 'ضغمة', 'مص. الْمَرَّةُ مِنْ ضَغَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضَغْمَةٌ-ضَغْمَةٌ [ض غ م] (الْمَرَّةُ مِنْ ضَغَمَ). ""ضَغْمَةُ أَسَدٍ"" : عَضَّتُهُ. وَقَدْ جَعَلَتْ نَفْسِي تَطِيبُ لِضَغْمَةٍ*لِضَغْمِهِمَا مَا يَقْرَعُ العَظْمَ نَابُهَا (سيبويه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17988, 'ضَلَّةٌ', 'ضلة', 'مصدر', 'ضلل', 'ضلة', 'ضلة', 'مص. الْمَرَّةُ مِنْ ضَلَّ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضَلَّةٌ-ضَلَّةٌ [ض ل ل] (الْمَرَّةُ مِنْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17989, 'ضَمَّةٌ', 'ضمة', 'مصدر', 'ضمم', 'ضمة', 'ضمة', 'مص. الْمَرَّةُ مِنْ ضَمَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ ضَمَّ). 1.""وَقَفَ الوَلَدُ"" : الوَلَدُ فَاعِلٌ مَرْفُوعٌ بِالضَّمَّةِ الظَّاهِرَةِ فِي آخِرِهِ، وَهِيَ الْحَرَكَةُ الَّتِي تَدُلُّ عَلَى الرَّفْعِ وَعَلاَمَتُهَا فَوْقَ الْحَرْفِ هَكَذا : ( ـُ ). 2.""ضَمَّةُ نَعْنَاعٍ"" : إِضْمَامَةُ. 3.""ضَمَّةُ الْخَيْلِ"" : حَلْبَةُ الرِّهَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17990, 'طَبْعَةٌ', 'طبعة', 'مصدر', 'طبع', 'طبعة', 'طبعة', 'مص. الْمَرَّةُ مِنْ طَبَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ طَبَعَ). 1.""جَاءتْ طَبْعَةُ الكِتَابِ أَنِيقَةً"" : صُورَتُهُ وَهَيْأَةُ طِبَاعَتِهِ. 2.""الطَّبْعَةُ الأُولَى مِنَ الكِتَابِ"" : عِنْدَمَا يُطْبَعُ الكِتَابُ لأَوَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17991, 'طَرْحَةٌ', 'طرحة', 'مصدر', 'طرح', 'طرحة', 'طرحة', 'مص. الْمَرَّةُ مِنْ طَرَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَرْحَةٌ-طَرْحَةٌ [ط ر ح] (الْمَرَّةُ مِنْ طَرَحَ). 1.""طَرْحَةُ العَرُوسِ"" : طَيْلَسَانٌ، كِسَاءٌ تُلْقِيه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17992, 'طَرْفَةٌ', 'طرفة', 'مصدر', 'طرف', 'طرفة', 'طرفة', 'مص. الْمَرَّةُ مِنْ طَرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ طَرَفَ). ""فِي طَرْفَةِ عَيْنٍ"" : فِي لَمْحَةِ البَصَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17993, 'طَعْنَةٌ', 'طعنة', 'مصدر', 'طعن', 'طعنة', 'طعنة', 'مص. الْمَرَّةُ مِنْ طَعَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":طَعْنٌ"', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ طَعَنَ). 1.""وَجَّهَ إِلَيْهِ طَعْنَةَ خَنْجَرٍ"" : أَيْ ضَرْبَةَ خَنْجَرٍ. 2.""أَسْقَطَهُ أَرْضاً بِطَعْنَةٍ نَجْلاَءَ"" : بِضَرْبَةٍ، بِلَكْمَةٍ نَافِذَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17994, 'طَعْنٌ', 'طعن', 'مصدر', '', 'طعن', 'طعن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17995, 'طَلَّةٌ', 'طلة', 'مصدر', 'طلل', 'طلة', 'طلة', 'مص. الْمَرَّةُ مِنْ طَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَلَّةٌ-طَلَّةٌ [ط ل ل] (الْمَرَّةُ مِنْ طَلَّ). 1.""أَرْضٌ طَلَّةٌ"" : بَلَّهَا الطَّلُّ. ‌2. ""رَائِحَةٌ طَلَّةٌ"" : لَذِيذَةٌ، شَهِيَّةٌ. 3.""هِيَ طَلَّتُهُ"" : اِمْرَأَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17996, 'طَلْعَةٌ', 'طلعة', 'مصدر', 'طلع', 'طلعة', 'طلعة', 'مص. الْمَرَّةُ مِنْ طَلَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ طَلَعَ). 1.""طَلْعَةُ الرَّجُلِ"" : وَجْهُهُ وَرُؤْيَتُهُ، هَيْأَةُ وَجْهِهِ. ""حَسَنُ الْمَنْظَرِ جَمِيلُ الطَّلْعَةِ"" ""يَتَمَلَّى طَلْعَتَهُ البَهِيَّةَ"" ""بَهِيُّ الطَّلْعَةِ"" ""رَجُلٌ وَقُورٌ، جَلِيلُ الْمَنْظَرِ، مَهِيبُ الطَّلْعَةِ"". (أ. أمين) ""طَلْعَةُ البَدْرِ"". 2.""عَادَ سَالِماً مِنْ طَلْعَتِهِ الأُولَى"" : مِنْ صُعُودِهِ الأَوَّلِ. ""طَلْعَةُ الطَّائِرَةِ"". 3.""طَلْعَةُ النَّخْلَةِ"" : القِطْعَةُ مِنْ طَلْعِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17997, 'عَطْسَةٌ', 'عطسة', 'مصدر', 'عطس', 'عطسة', 'عطسة', 'مص. الْمَرَّةُ مِنْ عَطَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عَطْسَةٌ-عَطْسَةٌ [ع ط س] (الْمَرَّةُ مِنْ عَطَسَ). 1.""أَتَتْهُ العَطْسَةُ"" : اِنْدِفَاعُ الْهَوَاءِ مِنَ الأَنْفِ بِشِدَّةٍ فَيُسْمَعُ لَهُ صَوْتٌ قَوِيٌّ مُرْتَفِعٌ. 2.""هُوَ عَطْسَةُ رَفِيقِهِ"" : أَيْ يُشْبِهُهُ خَلْقاً وَخُلُقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17998, 'عَمْلَةٌ', 'عملة', 'مصدر', 'عمل', 'عملة', 'عملة', 'مص. الْمَرَّةُ مِنْ عَمِلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"عَمْلَةٌ-عَمْلَةٌ [ع م ل] (الْمَرَّةُ مِنْ عَمِلَ). ""أَتَى عَمْلَةً يُعَاقِبُ عَلَيْهَا الْقَانُونُ"" : عَمَلاً سَيِّئاً وَمُنْكَراً، فَعْلَةٌ مُنْكَرَةٌ كَالسَّرِقَةِ أَوِ الْخِيَانَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(17999, 'غَيْضَةٌ', 'غيضة', 'مصدر', 'غيض', 'غيضة', 'غضة', 'مص. الْمَرَّةُ مِنْ غَاضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":غِيَاضٌ:أَغْيَاضٌ"', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ غَاضَ). ""لَمْ يَكُنْ يَرَى فِي السُّهُولِ الَّتِي تَمُرُّ مِنْهَا إِلاَّ الْغَيْضَةَ"": أَيْ سُهُولاً كَثِيرَةَ الشَّجَرِ وَالْمَاءِ، كَثِيرَةَ الشَّجَرِ الْمُلْتَفِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18000, 'غِيَاضٌ', 'غياض', 'مصدر', '', 'غياض', 'غض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18001, 'أَغْيَاضٌ', 'أغياض', 'مصدر', '', 'ءغياض', 'غض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18002, 'غَضْبَةٌ', 'غضبة', 'مصدر', 'غضب', 'غضبة', 'غضبة', 'مص. الْمَرَّةُ مِنْ غَضِبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غَضْبَةٌ-غَضْبَةٌ [غ ض ب]. 1. : الْمَرَّةُ مِنْ غَضِبَ. 2. : جِلْدَةُ الرَّأْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18003, 'غَفْوَةٌ', 'غفوة', 'مصدر', 'غفو', 'غفوة', 'غفة', 'مص. الْمَرَّةُ مِنْ غَفَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غَفْوَةٌ-غَفْوَةٌ [غ ف و] (الْمَرَّةُ مِنْ غَفَا). 1.""أَخَذَتْهُ غَفْوَةٌ"" : نَوْمَةٌ خَفِيفَةٌ، إِغْفَاءةٌ. 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18004, 'فَيْئَةٌ', 'فيئة', 'مصدر', 'فيأ', 'فيءة', 'فة', 'مص. الْمَرَّةُ مِنْ فَاءَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"فِيئَةٌ-فِيئَةٌ [ف ي أ] (النَّوْعُ مِنْ فَاءَ). ""إِنَّهُ حَسَنُ الفِيئَةِ"" : أَيْ حَسَنُ الرَّجْعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18005, 'فَتْحَةٌ', 'فتحة', 'مصدر', 'فتح', 'فتحة', 'فتحة', 'مص. الْمَرَّةُ مِنْ فَتَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"فَتْحَةٌ-فَتْحَةٌ [ف ت ح] (الْمَرَّةُ مِنْ فَتَحَ). 1. ""عَلاَمَةُ الْفَتْحَةِ"" : عَلاَمَةُ النَّصْبِ وَيُرْمَزُ لَهَا هَكَذَا (ـَ). فَوْقَ الْحَرْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18006, 'فَتْلَةٌ', 'فتلة', 'مصدر', 'فتل', 'فتلة', 'فتلة', 'مص. الْمَرَّةُ مِنْ فَتَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فَتْلَةٌ-فَتْلَةٌ [ف ت ل] (الْمَرَّةُ مِنْ فَتَلَ). 1. : وِعَاءُ حَبِّ السَّمُرِ وَالسَّلَمِ خَاصَّةً، وَذَلِكَ فِي أَوَّلِ طُلُوعِهِ. 2. : مَا يَكُونُ مَفْتُولاً مِنْ وَرَق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18007, 'فَسْخَةٌ', 'فسخة', 'مصدر', 'فسخ', 'فسخة', 'فسخة', 'مص. الْمَرَّةُ منْ فَسَخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فَسْخَةٌ-فَسْخَةٌ [ف س خ] (الْمَرَّةُ منْ فَسَخَ). 1.""شَابٌّ فَسْخَةٌ"" : ضَعِيفُ الرَّأْيِ والعَقْلِ والعَزْمِ والبَدَنِ. 2. : قِطْعَةٌ مِمَّا فُسِخَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18008, 'فَعْلَةٌ', 'فعلة', 'مصدر', 'فعل', 'فعلة', 'فعلة', 'مص. الْمَرَّةُ مِنْ فَعَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ فَعَلَ). ""اِرْتَكَبَ فَعْلَةً شَنِيعَةً"" : الْقِيَام بِعَمَلٍ مُسْتَنْكَرٍ. الشعراء آية 19وَفَعَلْتَ فَعْلَتَكَ الَّتِي فَعَلْتَ وَأَنْتَ مِنَ الْكَافِرِينَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18009, 'فَقْرَةٌ', 'فقرة', 'مصدر', 'فقر', 'فقرة', 'فقرة', 'مص. الْمَرَّةُ مِنْ فَقَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":فَقْرٌ"', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ فَقَرَ). ""فَقْرَةُ الظَّهْرِ"" : خَرَزَةٌ مِنْ خَرَزَاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18010, 'فَقْرٌ', 'فقر', 'مصدر', '', 'فقر', 'فقر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18011, 'فَكَّةٌ', 'فكة', 'مصدر', 'فكك', 'فكة', 'فكة', 'مص. الْمَرَّةُ مِنْ فَكَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فَكَّةٌ-فَكَّةٌ [ف ك ك] (الْمَرَّةُ مِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18012, 'فَلْكَةٌ', 'فلكة', 'مصدر', 'فلك', 'فلكة', 'فلكة', 'مص. الْمَرَّةُ مِنْ فَلَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":فَلْكٌ:فَلَكٌ"', '', 'Rp', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ فَلَكَ). 1.""فَلْكَةُ الفِقْرَتَيْنِ"" : مُوصِلٌ مَا بَيْنَهُمَا. (فَقَارُ الظَّهْرِ). 2.""فَلْكَةُ الْمِغْزَلِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18013, 'فَلْكٌ', 'فلك', 'مصدر', '', 'فلك', 'فلك', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18014, 'قَوْمَةٌ', 'قومة', 'مصدر', 'قوم', 'قومة', 'قمة', 'مص. الْمَرَّةُ مِنْ قَامَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"قَوْمَةٌ-قَوْمَةٌ [ق و م] (الْمَرَّةُ مِنْ قَامَ). 1.""قَوْمَةُ الإِنْسَانِ"" : قَامَتُهُ. 2. : مَا بَيْنَ الرَّكْعَتَيْنِ مِنْ قِيَامٍ. 3. : أَحَدُ أَجْزَاءِ صَلاَةِ اللَّيْلِ عِنْدَ الرُّهْبَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18015, 'قَبْسَةٌ', 'قبسة', 'مصدر', 'قبس', 'قبسة', 'قبسة', 'مص. الْمَرَّةُ مِنْ قَبَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَبْسَةٌ-قَبْسَةٌ [ق ب س] (الْمَرَّةُ مِنْ قَبَسَ). ""قَبْسَةٌ مِنْ نَارٍ"" : شُعْلَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18016, 'قَبْضَةٌ', 'قبضة', 'مصدر', 'قبض', 'قبضة', 'قبضة', 'مص. الْمَرَّةُ مِنْ قَبَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ قَبَضَ). 1.""قَبْضَةُ السَّيْفِ"" : مِقْبَضُهُ. 2.""صَارَتِ الْوَثِيقَةُ فِي قَبْضَتِهِ"" : بَيْنَ يَدَيْهِ. 3.""فِي يَدِهِ قَبْضَةٌ مِنَ الْعَجِينِ"" : مِلْءُ الكَفِّ مِنْهَا. 4.""ضَرَبَهُ بِقَبْضَةِ يَدِهِ"" : بِكَفِّ يَدِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18017, 'قَطْرَةٌ', 'قطرة', 'مصدر', 'قطر', 'قطرة', 'قطرة', 'مص. الْمَرَّةُ مِنْ قَطَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ قَطَرَ). 1.""يَقْطُرُ السَّقْفُ قَطْرَةً قَطْرَةً"" : نُقَطٌ مِنَ الْمَاءِ تَنْزِلُ مُتَتَابِعَةً. ""قَطْرَةٌ إِلَى قَطْرَةٍ فَيَسِيلُ النَّهْرُ"" (مثل). 2.""قَطْرَةُ الْعَيْنِ"" : دَوَاءٌ سَائِلٌ يُقَطَّرُ فِي الْعَيْنِ. ""قَطْرَةُ الأَنْفِ"" ""قَطْرَةُ الأُذُنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18018, 'قَعْدَةٌ', 'قعدة', 'مصدر', 'قعد', 'قعدة', 'قعدة', 'مص. الْمَرَّةُ مِنْ قَعَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَعْدَةٌ-قَعْدَةٌ، قِعْدَةٌ [ق ع د] (الْمَرَّةُ مِنْ قَعَدَ). 1.""كَانَ فِي قَعْدَةٍ مُرِيحَةٍ"" : فِي جَلْسَةٍ. 2.""ذُو القِعْدَةِ"" : الشَّهْرُ الْحَادِي عَشَرَ مِنَ الشُّهُورِ القَمَرِيَّةِ مِنَ السَّن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18019, 'قَفْزَةٌ', 'قفزة', 'مصدر', 'قفز', 'قفزة', 'قفزة', 'مص. الْمَرَّةُ مِنْ قَفَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَفْزَةٌ-قَفْزَةٌ [ق ف ز] (الْمَرَّةُ مِنْ قَف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18020, 'كَيْلَةٌ', 'كيلة', 'مصدر', 'كيل', 'كيلة', 'كلة', 'مص. الْمَرَّةُ مِنْ كَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ كَالَ). : الوِعَاءُ الَّذِي تُكَالُ بِهِ الْحُبُوبُ وَالسَّوَائِلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18021, 'كَبْوَةٌ', 'كبوة', 'مصدر', 'كبو', 'كبوة', 'كبة', 'مص. المَرَّةُ مِنْ كَبَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(المَرَّةُ مِنْ كَبَا). 1.""كَانَتْ كَبْوَتُهُ مُؤْلِمَةً"" : عَثْرَتُهُ، سَقْطَتُهُ. 2.""كَبْوَةُ قَلَمٍ"" : زَلَّةُ قَلَمٍ. ""لِكُلِّ جَوَادٍ كَبْوَةٌ"" (مثل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18022, 'كَرَّةٌ', 'كرة', 'مصدر', 'كرر', 'كرة', 'كرة', 'مص. المَرَّةُ مِنْ كَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(المَرَّةُ مِنْ كَرَّ). ""كَرَّةٌ أُخْرَى"" : حَمْلَةٌ أُخْرَى. ""كَرَّةٌ بَعْدَ كَرَّةٍ"" ""أَعَدْتُ إِلَيْهِ الكَرَّةَ فِي شَيْءٍ مِنَ الرِّفْقِ وَالاسْتِعْطَافِ"". (توفيق الحكيم)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18023, 'كَسْرَةٌ', 'كسرة', 'مصدر', 'كسر', 'كسرة', 'كسرة', 'مص. المَرَّةُ مِنَ كَسَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(المَرَّةُ مِنَ كَسَرَ). 1.""أُصِيبَ الجَيْشُ بِكَسْرَةٍ"" : بِهَزِيمَةٍ. 2.""بِعَيْنِ الوَلَدِ كَسْرَةٌ مِنَ السَّهَرِ"" : اِنْكِسَارٌ وَغَلَبَةُ نُعَاسٍ. 3.""رَجُلٌ ذُو كَسَرَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18024, 'لَوْثَةٌ', 'لوثة', 'مصدر', 'لوث', 'لوثة', 'لثة', 'مص. المَرَّةُ مِنْ لاَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَوْثَةٌ-لَوْثَةٌ [ل و ث] (المَرَّةُ مِنْ لاَثَ). ""أُصِيبَ بِلَوْثَةٍ"" : بِحَمَاقَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18025, 'لَوْعَةٌ', 'لوعة', 'مصدر', 'لوع', 'لوعة', 'لعة', 'مص. الْمَرَّةُ مِنْ لاَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَوْعَةٌ-لَوْعَةٌ [ل و ع] (الْمَرَّةُ مِنْ لاَعَ). ""فِي قَلْبِهِ لَوْعَةٌ"" : حُرْقَةُ الْحُزْنِ وَالْحُبِّ الشَّدِيدِ. ""بِهِ لَوْعَةُ الْحُبِّ"" ""رَآى لَوْعَتِي فَقَبِلَ رَجَائِي"". (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18026, 'لَوْمَةٌ', 'لومة', 'مصدر', 'لوم', 'لومة', 'لمة', 'مص. الْمَرَّةُ مِنْ لاَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَوْمَةٌ-لَوْمَةٌ [ل و م] (الْمَرَّةُ مِنْ لاَمَ). ""لاَ يَخْشَى لَوْمَةَ لاَئِمٍ"": مَا يُلاَمُ عَلَيْهِ.المائدة آية 54 وَلاَ يَخَافُونَ لَوْمَةَ لاَئِمٍ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18027, 'لِينَةٌ', 'لينة', 'مصدر', 'لين', 'لينة', 'لنة', 'مص. الْمَرَّةُ مِنْ لاَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لِينَةٌ-لِينَةٌ [ل ي ن] (الْمَرَّةُ مِنْ لاَنَ). ""اِتَّكَأَ عَلَى اللِّينَةِ"" : وِسَادَةٌ يُتَوَسَّدُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18028, 'لَثْمَةٌ', 'لثمة', 'مصدر', 'لثم', 'لثمة', 'لثمة', 'مص. الْمَرَّةُ مِنْ لَثَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَثْمَةٌ-لَثْمَةٌ [ل ث م] (الْمَرَّةُ مِنْ لَثَمَ). ""وَضَعَ لَثْمَةً عَلَى خَدِّهَا"" : قُبْلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18029, 'لَجَّةٌ', 'لجة', 'مصدر', 'لجج', 'لجة', 'لجة', 'مص. الْمَرَّةُ مِنْ لَـجَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَجَّةٌ-لَجَّةٌ [ل ج ج] (الْمَرَّةُ مِنْ لَـجَّ). ""سَادَتِ اللَّجَّةُ بَيْنَهُمْ"" : الْجَلَبَةُ وَالصَّخَبُ وَاخْتِلاَطُ الأَصْوَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18030, 'لَحْمَةٌ', 'لحمة', 'مصدر', 'لحم', 'لحمة', 'لحمة', 'مص. المَرَّةُ مِنْ لَحَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَحْمَةٌ-لَحْمَةٌ [ ل ح م ] (المَرَّةُ مِنْ لَحَمَ). 1.""قَدَّمَ لَهُ لَحْمَةً لِغِذَائِهِ"" : قِطْعَةً مِنَ اللَّحْمِ. 2.""لَحْمَةُ نَسِيجٍ "" : حَبْكَتُهُ، أَنْسِجَتُهُ. 3.""لَحْمَةُ مَعْدِنٍ"" : القِطْعَةُ مِنَ اللِّحَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18031, 'لَدْغَةٌ', 'لدغة', 'مصدر', 'لدغ', 'لدغة', 'لدغة', 'مص. الْمَرَّةُ مِنْ لَدَغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَدْغَةٌ-لَدْغَةٌ [ل د غ] (الْمَرَّةُ مِنْ لَدَغَ). ""تَرَك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18032, 'لَطْمَةٌ', 'لطمة', 'مصدر', 'لطم', 'لطمة', 'لطمة', 'مص. الْمَرَّةُ مِنْ لَطَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ لَطَمَ). ""وَجَّهَ إِلَيْهِ لَطْمَةً"" : ضَرْبَةً بِبَاطِنِ الكَفِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18033, 'لَعْنَةٌ', 'لعنة', 'مصدر', 'لعن', 'لعنة', 'لعنة', 'مص. الْمَرَّةُ مِنْ لَعَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ لَعَنَ). ""عَلَيْهِ اللَّعْنَةُ"" : العَذَابُ، السَّخَطُ، النِّقْمَةُ. ""أَصَابَتْهُ لَعْنَةٌ مِنَ السَّمَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18034, 'لَفْتَةٌ', 'لفتة', 'مصدر', 'لفت', 'لفتة', 'لفتة', 'مص. الْمَرَّةُ مِنْ لَفَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ لَفَتَ). ""هَذِهِ لَفْتَةٌ كَرِيمَةٌ فِي مَحَلِّهَا"" : بَادِرَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18035, 'لَفْظَةٌ', 'لفظة', 'مصدر', 'لفظ', 'لفظة', 'لفظة', 'مص. الْمَرَّةُ مِنْ لَفَظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ لَفَظَ).: الْكَلِمَةُ الْمَلْفُوظُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18036, 'لَقْطَةٌ', 'لقطة', 'مصدر', 'لقط', 'لقطة', 'لقطة', 'مص. الْمَرَّةُ مِنْ لَقَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ لَقَطَ). ""اللَّقْطَةُ السِّينَمَائِيَّةُ"" : الْمَشْهَدُ، الْمَنْظَرُ الَّذِي تَلْتَقِطُهُ عَدَسَةُ التَّصْوِيرِ. ""أَخَذَ لَهُ لَقْطَةً رَائِعَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18037, 'لَهْفَةٌ', 'لهفة', 'مصدر', 'لهف', 'لهفة', 'لهفة', 'مص. الْمَرَّةُ مِنْ لَهِفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَهْفَةٌ-لَهْفَةٌ [ل هـ ف] (الْمَرَّةُ مِنْ لَهِفَ). ""يَالَهْفَةُ""، ""يَا لَهْفَتَاهُ"" : كَلِمَةٌ للِتَّحَسُّرِ عَلَى مَا مَضَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18038, 'مَيْتَةٌ', 'ميتة', 'مصدر', 'موت', 'ميتة', 'متة', 'مص. الْمَرَّةُ مِنْ مَاتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ مَاتَ). ""مَاتَ مَيْتَةً طَبِيعِيَّةً"" : حَالَةُ الْمَوْتِ وَطَبِيعَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18039, 'مَخْطَةٌ', 'مخطة', 'مصدر', 'مخط', 'مخطة', 'مخطة', 'مص. الْمَرَّةُ مِنْ مَخَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَخْطَةٌ-مَخْطَةٌ [م خ ط] (الْمَرَّةُ مِنْ مَخَطَ).: ما يَقْذِفُهُ الرَّجُلُ مِنَ الْمُخَاطِ دَفْعَةً وَاحِدَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18040, 'مَسْحَةٌ', 'مسحة', 'مصدر', 'مسح', 'مسحة', 'مسحة', 'مص. الْمَرَّةُ مِنْ مَسَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَسْحَةٌ-مَسْحَةٌ [م س ح] (الْمَرَّةُ مِنْ مَسَحَ). ""عَلَيْهَا مَسْحَةٌ مِنَ الجَمَالِ"" : أَثَرٌ ظَاهِرٌ. ""إِنَّ مَسْحَةً مِنَ الحُزْنِ كَانَتْ تَسُودُ فِي كُلِّ عِبَارَةٍ مِنْ عِبَارَاتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18041, 'مَسْكَةٌ', 'مسكة', 'مصدر', 'مسك', 'مسكة', 'مسكة', 'مص. الْمَرَّةُ مِنْ مَسَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَسْكَةٌ-مَسْكَةٌ [م س ك] (الْمَرَّةُ مِنْ مَسَكَ). 1.""مَسَكَهُ مَسْكَةً"" : قَبَضَهُ قَبْضَةً. 2.""مَسْكَةُ الطَّنْجَرَةِ"" : مَا يُمْسَكُ بِهَا. 3.""مَسْكَةُ البَابِ"" : مِقْبَضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18042, 'نَوْحَةٌ', 'نوحة', 'مصدر', 'نوح', 'نوحة', 'نحة', 'مص. الْمَرَّةُ مِنْ نَاحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَوْحَةٌ-نَوْحَةٌ [ن و ح] (الْمَرَّةُ مِنْ نَاحَ). ""اِشْتَدَّتْ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18043, 'نَوْعَةٌ', 'نوعة', 'مصدر', 'نوع', 'نوعة', 'نعة', 'مص. الْمَرَّةُ مِنْ نَاعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَوْعَةٌ-نَوْعَةٌ [ن و ع] (الْمَرَّةُ مِنْ نَاعَ). ""فِي السُّوقِ نَوْعَةٌ"" : فَاكِهَةٌ رَطْبَةٌ طَرِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18044, 'نَوْلَةٌ', 'نولة', 'مصدر', 'نول', 'نولة', 'نلة', 'مص. الْمَرَّةُ مِنْ نَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَوْلَةٌ-نَوْلَةٌ [ن و ل] (الْمَرَّةُ مِنْ نَالَ). 1.""كَانَتْ تِلْكَ نَوْلَتُـهُ"" : مَا يَنَالُهُ الإِنْسَانُ مِنْ خَيْرٍ، مِنْ عَطَاءٍ. ""مَا أَصَبْتُ مِنْهُ نَوْلَةً"". 2.""نَاوَلَتْهُ نَوْلَةً"" : قُبْلَةً. ""أَصَابَ مِنْ خَدِّهَا نَوْلَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18045, 'نَوْمَةٌ', 'نومة', 'مصدر', 'نوم', 'نومة', 'نمة', 'مص. الْمَرَّةُ مِنْ نَامَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَامَ). ""نَامَ نَوْمَةً هَادِئَةً"" : أَيْ إِغْفَاءةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18046, 'نَوْهَةٌ', 'نوهة', 'مصدر', 'نوه', 'نوهة', 'نهة', 'مص. الْمَرَّةُ مِنْ نَاهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَوْهَةٌ-نَوْهَةٌ [ن و هـ] (الْمَرَّةُ مِنْ نَاهَ). ""تَنَاوَلَ نَوْهَةً دَسِمَـةً"" : أَكْلَةً، وَجْبَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18047, 'نَبْرَةٌ', 'نبرة', 'مصدر', 'نبر', 'نبرة', 'نبرة', 'مص. الْمَرَّةُ مِنْ نَبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَبَرَ). 1.""نَبْرَةُ الْمُغَنِّي"" : رَفْعُ الصَّوْتِ بَعْدَ خَفْضِهِ. ""تَرَنّمَ بِصَوْتٍ كَالْهَمْسِ لَكِنَّهُ وَاضِحُ النَّبَرَاتِ"". (توفيق الحكيم). 2.""نَبْرَةُ الْكَلِمَةِ"" : رَفْعُ الصَّوْتِ عِنْدَ النُّطْقِ بِهَا : قَدْ يَكُونُ بِالاعْتِمَادِ عَلَى حَرْفٍ مِنْ حُرُوفِهَا. 3.""نَبْرَةُ الْجَسَدِ"" : وَرَمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18048, 'نَجْدَةٌ', 'نجدة', 'مصدر', 'نجد', 'نجدة', 'نجدة', 'مص. الْمَرَّةُ مِنْ نَجَدَ، نَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَجَدَ، نَجُدَ). 1.""النَّجْدَةُ! النَّجْدَةُ يَا قَوْمُ"" : الْمُطَالَبَةُ بِالإِغَاثَةِ فِي حَالاَتِ الضَّيْقِ وَالشِّدَّةِ وَالْفَزَعِ. 2.""أَظْهَرَ نَجْدَةً"" : شَجَاعَةً فِي الْقِتَالِ. 3.""نَجَدَاتٌ عَسْكَرِيَّةٌ"" : مَا يُقَدِّمُهُ الْجَيْشُ مِنْ إِمْدَادَاتٍ وَتَعْزِيزَاتٍ فِي حَالَةِ الضَّيْقِ وَالشِّدَّةِ. 4.""شُرْطَةُ النَّجْدَةِ"" : فِرْقَةٌ مِنَ الشُّرَطِ تَكُونُ عَلَى أُهْبَةِ الْقِيَامِ بِإِغَاثَةِ مَنْ هُمْ فِي وَضْعٍ حَرِجٍ بِأَقْصَى سُرْعَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18049, 'نَخْمَةٌ', 'نخمة', 'مصدر', 'نخم', 'نخمة', 'نخمة', 'مص. الْمَرَّةُ مِنْ نَخَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَخْمَةٌ-نَخْمَةٌ [ن خ م] (الْمَرَّةُ مِنْ نَخَمَ). ""رَمَى بِنَخْمَتِهِ"" : مَا يَلْفِظُهُ الْمَرْءُ مِنْ بَلْغَمٍ مِنْ أَنْفِهِ أَوْ صَدْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18050, 'نَدْبَةٌ', 'ندبة', 'مصدر', 'ندب', 'ندبة', 'ندبة', 'مص. الْمَرَّةُ مِنْ نَدَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نُدُوبٌ:أَنْدَابٌ"', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَدَبَ). ""نَدْبَةُ الْجُرْحِ"" : أَثَرُهُ البَاقِي عَلَى الجِلْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18051, 'نُدُوبٌ', 'ندوب', 'مصدر', '', 'ندوب', 'ندب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18052, 'أَنْدَابٌ', 'أنداب', 'مصدر', '', 'ءنداب', 'ندب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18053, 'نَدْرَةٌ', 'ندرة', 'مصدر', 'ندر', 'ندرة', 'ندرة', 'مص. المَرَّةُ مِنْ نَدَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَدْرَةٌ-نَدْرَةٌ [ن د ر] (المَرَّةُ مِنْ نَدَرَ). 1.""نَدْرَةُ فِضَّةٍ أَوْ ذَهَبٍ"" : قِطْعَةٌ مِنْهُ تُوجَدُ فِي الْمَعْدِنِ. 2.""لاَ يَكُونُ ذَلِكَ إِلاَّ نَدْرَةً أَوْ فِي النَّدْرَةِ"" : إِلاَّ أَحْيَاناً قَلِيلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18054, 'نَزَّةٌ', 'نزة', 'مصدر', 'نزز', 'نزة', 'نزة', 'مص. الْمَرَّةُ مِنْ نَزَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَزَّةٌ-نَزَّةٌ [ن ز ز] (الْمَرَّةُ مِنْ نَزَّ). 1.""أَخْفَى نَزَّتَهُ"" : شَهْوَتَهُ. ""قَتَلَتْهُ نَزَّتُهُ"". 2.""أَرْضٌ نَزَّةٌ"" : أَيْ يَسِيلُ فِيهَا مَاءٌ. 3.""نَاقَةٌ نَزَّةٌ"" : نَشِيطَةٌ، خَفِيفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18055, 'نَزْوَةٌ', 'نزوة', 'مصدر', 'نزو', 'نزوة', 'نزة', 'مص. المَرَّةُ مِنْ نَزَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(المَرَّةُ مِنْ نَزَا). ""نَزْوَةُ الشَّبَابِ"" : تَهَوُّرُهُ، تَقَلُّبَاتُهُ. ""نَزْوَةُ الغَرِيزَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18056, 'نَزْعَةٌ', 'نزعة', 'مصدر', 'نزع', 'نزعة', 'نزعة', 'مص. الْمَرَّةُ مِنْ نَزَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَزَعَ). ""أَظْهَرَ نَزْعَتَهُ نَحْوَ الشَّيْءِ"" : مَيْلَهُ، اِتِّجَاهَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18057, 'نَزْغَةٌ', 'نزغة', 'مصدر', 'نزغ', 'نزغة', 'نزغة', 'مص. الْمَرَّةُ مِنْ نَزَغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَزَغَ). ""أَصَابَهُ بِنَزْغَةٍ"" : بِطَعْنَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18058, 'نَزْلَةٌ', 'نزلة', 'مصدر', 'نزل', 'نزلة', 'نزلة', 'مص. الْمَرَّةُ مِنْ نَزَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَزَلَ). 1.""أَصَابَتْهُ نَزْلَةٌ"" : مَرَضٌ كَالزُّكَامِ يَرْفُقُهُ سُعَالٌ وَحُمّىً، اِلْتِهَابٌ. 2.""النَّزْلَةُ الصَّدْرِيَّةُ"" : نَزْلَةُ بَرْدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18059, 'نَشْرَةٌ', 'نشرة', 'مصدر', 'نشر', 'نشرة', 'نشرة', 'مص. الْمَرَّةُ مِنْ نَشَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَشَرَ). 1.""نَشْرَةٌ صَحَفِيَّةٌ"" : صَحِيفَةٌ بِهَا أَخْبَارٌ وَمَعْلُومَاتٌ عَامَّةٌ. ""نَشْرَةٌ إِذَاعِيَّةٌ"" ""نَشْرَةٌ جَوِّيَّةٌ"" ""نَشْرَةُ الأَخْبَارِ اليَوْمِيَّةِ"". 2.""أَرْسَلَتِ الوِزَارَةُ نَشْرَةً"" : بَيَاناً مَكْتُوباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18060, 'نَصْبَةٌ', 'نصبة', 'مصدر', 'نصب', 'نصبة', 'نصبة', 'مص. الْمَرَّةُ مِنْ نَصَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَصْبَةٌ-نَصْبَةٌ [ن ص ب] (الْمَرَّةُ مِنْ نَصَبَ). 1. : وَاحِدَةُ النَّصْبِ لِمَا يُغْرَسُ مِنْ صِغَارِ الشَّجَرِ. 2.""عَلاَمَةُ النَّصْبَةِ"" : عَلاَمَةُ النَّصْبَ، الفَتْحَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18061, 'نَطْحَةٌ', 'نطحة', 'مصدر', 'نطح', 'نطحة', 'نطحة', 'مص. الْمَرَّةُ مِنْ نَطَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَطَحَ). ""نَطْحَةُ كَبْشٍ"" : ضَرْبَةُ قَرْنِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18062, 'نَظْرَةٌ', 'نظرة', 'مصدر', 'نظر', 'نظرة', 'نظرة', 'مص. الْمَرَّةُ مِنْ نَظَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَظَرَ). 1.""أَلْقَى نَظْرَةً خَاطِفَةً عَلَى الْمَوْضُوعِ"" : لَمْحَةً.نَظْرَةٌ فَابْتِسَامَةٌ فَسَـلاَمٌ*فَاتِّفَاقٌ فَمَوْعِـدٌ فَلِقَـاءُ (أحمد شوقي).2.""نَظَرَ إِلَيْهَا نَظْرَةً مِلْؤُهَا الْحُبُّ وَالْحَنَانُ"" : التَّطَلُّعُ. 3.""نَظْرَةٌ إِجْمَالِيَّةٌ"" : رُؤْيَةٌ. ""نَظْرَةٌ شَامِلَةٌ"". 4.""نَظَرَهُ بِعَيْنِ النَّظْرَةِ"" : بِعَيْنِ الرَّحْمَةِ. 5.""أَصَابَتْهُ النَّظْرَةُ"" : العَيْنُ، الْحَسَدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18063, 'نَعْرَةٌ', 'نعرة', 'مصدر', 'نعر', 'نعرة', 'نعرة', 'مص. الْمَرَّةُ مِنْ نَعَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَعَرَ). 1. :صَيْحَةٌ تَتِمُّ بِخُرُوجِ الصَّوْتِ مِنَ الْخَيْشُومِ. 2. ""نَعْرَةُ النَّجْمِ"" : هُبُوبُ الرِّيحِ وَاشْتِدَادُ الْحَرِّ عِنْدَ طُلُوعِهِ. 3. ""نَعْرَةٌ قَبَلِيَّةٌ"" : نَزْعَةٌ تَعَصُّبِيَّةٌ تُؤَدِّي إِلَى الْفِتْنَةِ. ""نَعْرَةٌ عُنْصُـرِيَّةٌ"" ""نَعْرَةٌ طَائِفِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18064, 'نَفْثَةٌ', 'نفثة', 'مصدر', 'نفث', 'نفثة', 'نفثة', 'مص. الْمَرَّةُ مِنْ نَفَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَفَثَ). 1.""نَفْثَةُ مَصْدُورٍ"" : مَا يُلْقِيهِ مِنْ فَمِهِ. 2.""مَا أَحْسَنَ نَفَثَاتِ شُعَرَاءِ الْمَهْجَرِ"" : مَا أَحْسَنَ شِعْرَهُمْ. 3.""نَفَثَاتُ الأَقْلاَمِ"" : الْإِنْتَاجُ الأَدَبِيُّ، الشِّعْرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18065, 'نَفْحَةٌ', 'نفحة', 'مصدر', 'نفح', 'نفحة', 'نفحة', 'مص. الْمَرَّةُ مِنْ نَفَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَفَحَ). 1.""نَفْحَةُ نَفْسٍ"" : طِيبٌ تَرْتَاحُ لَهُ النَّفْسُ. 2.""عُرِفَ بِكَرَمِهِ وَنَفَحَاتِهِ"" : عَطَايَاهُ. 3.""أَصَابَتْهُمْ نَفْحَةٌ مِنْ سُمُومٍ"": دَفْعَةٌ مِنْهُ، الْغَمُّ، الْكَرْبُ. الأنبياء آية 46وَلَئِنْ مَسَّتْهُمْ نَفْحَةٌ مِنْ عَذَابِ رَبِّكَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18066, 'نَفْخَةٌ', 'نفخة', 'مصدر', 'نفخ', 'نفخة', 'نفخة', 'مص. الْمَرَّةُ مِنْ نَفَخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَفَخَ). 1.""نَفْخَةُ الْفَمِ"" : إِخْرَاجُ الرِّيحِ مِنَ الْفَمِ دَفْعَةً وَاحِدَةً. 2.""نَفْخَةُ الْبَطْنِ"" : اِنْتِفَاخُهُ مِنْ مَرَضٍ أَوْ طَعَامٍ. 3. ""هَبَّتْ نَفْخَةُ الرَّبِيعِ"" : أَيَّامُ إِعْشَابِهِ وَازْدِهَارِهِ. 4. ""نَفْخَةُ الشَّبَابِ"" : مُعْظَمُهُ، اِكْتِمَالُهُ، قُوَّتُهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18067, 'نَفْرَةٌ', 'نفرة', 'مصدر', 'نفر', 'نفرة', 'نفرة', 'مص. الْمَرَّةُ مِنْ نَفَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَفْرَةٌ-نَفْرَةٌ [ن ف ر] (الْمَرَّةُ مِنْ نَفَرَ). 1.""نَفْرَةٌ مِنَ الرِّجَالِ"": جَمَاعَةٌ مِنْهُمْ لِمَا دُونَ العَشَرَةِ. 2.""هُمْ فِي نَفْرَةٍ"" : مُسْرِعُونَ إِلَى قِتَالٍ وَنَحْوِهِ. 3.""نَفْرَةُ الْحُجَّاجِ"" : أَيْ هُمْ نَافِرُونَ مِنْ مِنـىً إِلَى مَكَّةَ. 4.""نَفْرَةُ الرَّجُلِ"" : أُسْرَتُهُ وَقَوْمُهُ يَغْضَبُونَ لِغَضَبِهِ وَيَتَعَصَّبُونَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18068, 'نَفْطَةٌ', 'نفطة', 'مصدر', 'نفط', 'نفطة', 'نفطة', 'مص. الْمَرَّةُ مِنْ نَفَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نِفَاطٌ"', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَفَطَ). ""ظَهَرَتْ نَفْطَةٌ فِي كَفِّ يَدِهِ مِنْ جَرَّاءِ الْعَمَلِ بِالْفَأْسِ"" : بَثْرَةٌ يَتَجَمَّعُ بِدَاخِلِهَا سَائِلٌ بَيْنَ الْجِلْدِ وَ اللَّحْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18069, 'نِفَاطٌ', 'نفاط', 'مصدر', '', 'نفاط', 'نفط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18070, 'نِقْمَةٌ', 'نقمة', 'مصدر', 'نقم', 'نقمة', 'نقمة', 'مص. الْمَرَّةُ مِنْ نَقَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نِقَمٌ"', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَقَمَ). ""كَانَتْ نِقْمَتُهُ شَدِيدَةً"" : عُقُوبَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18071, 'نِقَمٌ', 'نقم', 'مصدر', '', 'نقم', 'نقم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18072, 'نَكْبَةٌ', 'نكبة', 'مصدر', 'نكب', 'نكبة', 'نكبة', 'مص. الْمَرَّةُ مِنْ نَكَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَكَبَ). ""أُصِيبَ بِنَكْبَةٍ"" : بِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18073, 'نَكْهَةٌ', 'نكهة', 'مصدر', 'نكه', 'نكهة', 'نكهة', 'مص. الْمَرَّةُ مِنْ نَكَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَكْهَةٌ-نَكْهَةٌ [ن ك هـ] (الْمَرَّةُ مِنْ نَكَهَ). ""نَكْهَةُ الْفَمِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18074, 'نَهْضَةٌ', 'نهضة', 'مصدر', 'نهض', 'نهضة', 'نهضة', 'مص. الْمَرَّةُ مِنْ نَهَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '"نِهَاضٌ"', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَهَضَ). 1.""عَبَّرَ عَنْ نَهْضَةٍ وَاعِيَةٍ"" : عَنْ قُوَّةٍ، طَاقَةٍ. 2.""كَانَ مِنْهُ نَهْضَةٌ إِلَى كَذَا"" : حَرَكَةٌ، وَثْبَةٌ. 3.""النَّهْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18075, 'نِهَاضٌ', 'نهاض', 'مصدر', '', 'نهاض', 'نهض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18076, 'نَهْمَةٌ', 'نهمة', 'مصدر', 'نهم', 'نهمة', 'نهمة', 'مص. الْمَرَّةُ مِنْ نَهَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ نَهَمَ). ""قَضَى مِنْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18077, 'هَوْشَةٌ', 'هوشة', 'مصدر', 'هوش', 'هوشة', 'هشة', 'مص. الْمَرَّةُ مِنْ هَاشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ هَاشَ). 1.""زَرَعَ الْهَوْشَةَ بَيْنَ النَّاسِ"" : الفِتْنَةَ وَالاضْطِرَابَ وَالْفَوْضَى. 2.""اِخْتَلَطَ بَيْنَ الْهَوْشَةِ"" : بَيْنَ الْجَمَاعَةِ الْمُخْتَلِطَةِ. 3.""اِتَّقُوا هَوَشَاتِ السُّوقِ"" : اِتَّقُوا الازْدِحَامَ وَالاخْتِلاَطَ لِكَيْ لاَ يُحْتَالَ عَلَيْكُمْ فَتُسْرَقُوا. 4.""هَوَشَاتُ اللَّيْلِ"" : حَوَادِثُهُ وَمَكَارِهُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18078, 'هَجْمَةٌ', 'هجمة', 'مصدر', 'هجم', 'هجمة', 'هجمة', 'مص. الْمَرَّةُ مِنْ هَجَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ هَجَمَ). 1.""وَصَلَ بَعْدَ هَجْمَةٍ مِنَ اللَّيْلِ"" : بَعْدَ أَوَّلِ ظَلاَمِ اللَّيْلِ. 2.""تَعَرَّضَتْ خِيَامُ اللاَّجِئِينَ لِهَجْمَةٍ شَرِسَةٍ"" : لاِنْقِضَاضٍ عَلَى بَغْتَةٍ. 3.""هَجْمَةُ الشِّتَاءِ"" : شِدَّةُ بَرْدِهِ. 4.""هَجْمَةُ الصَّيْفِ"" : شِدَّةُ حَرِّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18079, 'هَدَّةٌ', 'هدة', 'مصدر', 'هدد', 'هدة', 'هدة', 'مص. الْمَرَّةُ مِنْ هَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هَدَّةٌ-هَدَّةٌ [هـ د د] (الْمَرَّةُ مِنْ هَدَّ). ""هَدَّةُ الْبِنَاءِ"" : صَوْتُ وُقُوعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18080, 'هَدْأَةٌ', 'هدأة', 'مصدر', 'هدأ', 'هدءة', 'هدة', 'مص. الْمَرَّةُ مِنْ هَدَأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '"(آ)"', '', 'Rz', '', '', '', '', '', '', '"هَدْأَةٌ-هَدْأَةٌ [هـ د أ] (الْمَرَّةُ مِنْ هَدَأَ). 1.""فِي هَدْأَةِ اللَّيْلِ"": فِي طَائِفَةٍ مِنْهُ. 2.""اِخْتَلَى فِي هَدْأَةٍ"" : فِي سُكُوتٍ وَسُكُونٍ عَنِ الْحَرَكَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18081, 'هَدْيَةٌ', 'هدية', 'مصدر', 'هدي', 'هدية', 'هدة', 'مص. الْمَرَّةُ مِنْ هَدَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"هَدْيَةٌ-هَدْيَةٌ [هـ د ي] (الْمَرَّةُ مِنْ هَدَى). 1.""تِلْكَ هَدْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18082, 'هَزَّةٌ', 'هزة', 'مصدر', 'هزز', 'هزة', 'هزة', 'مص. الْمَرَّةُ مِنْ هَزَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ هَزَّ). 1.""هَزَّةُ الْفَرَحِ وَالطَّرَبِ"" : التَّأَثُّرُ بِتَحَرُّكِ النَّفْسِ. 2.""ت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18083, 'هَضْبَةٌ', 'هضبة', 'مصدر', 'هضب', 'هضبة', 'هضبة', 'مص. الْمَرَّةُ مِنْ هَضَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":هِضَابٌ"', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ هَضَبَ). 1.""تُطِلُّ الْهَضْبَةُ عَلَى السُّهُولِ"" : مَا ارْتَفَعَ مِنَ الأَرْضِ. 2.""تَتَمَيَّز"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18084, 'هِضَابٌ', 'هضاب', 'مصدر', '', 'هضاب', 'هضب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18085, 'هَمْرَةٌ', 'همرة', 'مصدر', 'همر', 'همرة', 'همرة', 'مص. الْمَرَّةُ مِنْ هَمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هَمْرَةٌ-هَمْرَةٌ [هـ م ر] (الْمَرَّةُ مِنْ هَمَرَ). 1.""هَمْرَةُ مَطَرٍ"" : دُفْعَةٌ أُولَى مِنْهُ. 2.""هَمْرَةُ السِّحْرِ"" : خَرَزَتُهُ. 3.""هَمَرَهُ بِهَمْرَةٍ"": بِدَمْدَمَةٍ، بِغَضَبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18086, 'هَمْزَةٌ', 'همزة', 'مصدر', 'همز', 'همزة', 'همزة', 'مص. الْمَرَّةُ مِنْ هَمَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ هَمَزَ). 1. أَوَّلُ حَرْفٍ مِنْ حُرُوفِ الْهِجَاءِ. ن. حَرْفُ الأَلِفِ : هَمْزَة الْقَطْعِ، هَمْزَة الْوَصْلِ. 2.""كَانَ هَمْزَةَ وَصْلٍ بَيْنَنَا"" : أَيْ أَدَاةَ ارْتِبَاطٍ بَيْنَنَا. 3.""هَمَزَاتُ الشَّيْطَانِ"" : خَطَرَاتُهُ، وَسَاوِسَهُ.المؤمنون آية 97وَقُلْ رَبِّي أَعُوذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ(قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18087, 'وَحْفَةٌ', 'وحفة', 'مصدر', 'وحف', 'وحفة', 'حفة', 'مص. الْمَرَّةُ مِنَ وَحَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":وِحَافٌ"', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنَ وَحَفَ). 1.""أَرْضٌ وَحْفَةٌ"" : مُسْتَدِيرَةٌ مُرْتَفِعَةٌ سَوْدَاء"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18088, 'وِحَافٌ', 'وحاف', 'مصدر', '', 'وحاف', 'حف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18089, 'وَخْفَةٌ', 'وخفة', 'مصدر', 'وخف', 'وخفة', 'خفة', 'مص. الْمَرَّةُ مِنْ وَخَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَخْفَةٌ-وَخْفَةٌ [و خ ف] (الْمَرَّةُ مِنْ وَخَفَ). ""وَضَعَ اللَّبَنَ فِي الوَخْفَةِ"" : الوِعَاءُ مِنْ جِلْدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18090, 'وَشْمَةٌ', 'وشمة', 'مصدر', 'وشم', 'وشمة', 'شمة', 'مص. الْمَرَّةُ مِنْ وَشَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَشْمَةٌ-وَشْمَةٌ [و ش م] (الْمَرَّةُ مِنْ وَشَمَ). ""عَلَى وَجْهِهَا وَشْمَةٌ"" : العَلاَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18091, 'وَصْمَةٌ', 'وصمة', 'مصدر', 'وصم', 'وصمة', 'صمة', 'مص. المَرَّةُ مِنْ وَصَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(المَرَّةُ مِنْ وَصَمَ). ""إِنَّهَا وَصْمَةٌ فِي جَبِينِهِ"" : عَارٌ، عَيْبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18092, 'وَطْأَةٌ', 'وطأة', 'مصدر', 'وطأ', 'وطءة', 'طة', 'مص. المَرَّةُ مِنْ وَطَأ', '', '', 'مفرد', 'DnN', '', 'Pf', '"(آ)"', '', 'Rz', '', '', '', '', '', '', '"وَطْأَةٌ-وَطْأَةٌ [و ط أ] (المَرَّةُ مِنْ وَطَأ). 1.""وَطْأَةُ القَدَمِ"" : أَثَرُ القَدَمِ. 2.""وَطِئَهُمْ وَطْأَةً مُنْكَرَةً"" : أَي الأَخْذَة الشَّدِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18093, 'وَعْظَةٌ', 'وعظة', 'مصدر', 'وعظ', 'وعظة', 'عظة', 'مص. الْمَرَّةُ مِنْ وَعَظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ وَعَظَ). ""لَمْ يَتْرُكْ وَعْظَةً مِن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18094, 'وَعْقَةٌ', 'وعقة', 'مصدر', 'وعق', 'وعقة', 'عقة', 'مص. الْمَرَّةُ مِنْ وَعَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَعْقَةٌ-وَعْقَةٌ [و ع ق] (الْمَرَّةُ مِنْ وَعَقَ). 1.""فِي فِعْلِهِ وَعْقَةٌ"": سُوءُ الْخُلُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18095, 'وَغْرَةٌ', 'وغرة', 'مصدر', 'وغر', 'وغرة', 'غرة', 'مص. المَرَّةُ مِنْ وَغَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَغْرَةٌ-وَغْرَةٌ [و غ ر] (المَرَّةُ مِنْ وَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18096, 'وَفْرَةٌ', 'وفرة', 'مصدر', 'وفر', 'وفرة', 'فرة', 'مص. المَرَّةُ مِنْ وَفَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":وِفَارٌ"', '', 'R', '', '', '', '', '', '', '"(المَرَّةُ مِنْ وَفَرَ). 1.""وَفْرَةُ الْمَوَادِّ الغِذَائِيَّةِ"" : كَثْرَتُهَا. ""نَزَلَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18097, 'وِفَارٌ', 'وفار', 'مصدر', '', 'وفار', 'فر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18098, 'وَقْبَةٌ', 'وقبة', 'مصدر', 'وقب', 'وقبة', 'قبة', 'مص. الْمَرَّةُ مِنْ وَقَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(الْمَرَّةُ مِنْ وَقَبَ). 1.""وَقْبَةُ الصَّخْرَةِ"" : نُقْرَتُهَا، أَيْ حُفْرَتُهَا الَّتِي يَجْتَمِعُ فِيهَا الْمَاءُ. 2.""وَقْبَةُ العَيْنِ أَوِ الكَتِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18099, 'وَقْدَةٌ', 'وقدة', 'مصدر', 'وقد', 'وقدة', 'قدة', 'مص. الْمَرَّةُ مِنْ وَقَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَقْدَةٌ-وَقْدَةٌ [و ق د] (الْمَرَّةُ مِنْ وَقَدَ). ""وَقْدَةُ السَّمَرِ"" : نَارُهُ الْمُشْتَعِلَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18100, 'وَقْعَةٌ', 'وقعة', 'مصدر', 'وقع', 'وقعة', 'قعة', 'مص. المَرَّةُ مِنْ وَقَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(المَرَّةُ مِنْ وَقَعَ). 1.""حَدَثَ ذَلِكَ فِي وَقْعَةِ أُحُدٍ"" : غَزْوَة، مَع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18101, 'وَقْفَةٌ', 'وقفة', 'مصدر', 'وقف', 'وقفة', 'قفة', 'مص. المَرَّةُ مِنْ وَقَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(المَرَّةُ مِنْ وَقَفَ). 1.""وَقْفَةُ السَّائِرِ"" : اِسْتِرَاحَتُهُ لَحْظَةً. 2.""وَقْفَةٌ شَدِيدَةٌ"" : صَدْمَةٌ. 3.""كَانَتْ وَقْفَتُهُ وَقْفَةَ بَطَلٍ"" : مَوْقِفُهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18102, 'أُلوهَةٌ', 'ألوهة', 'مصدر', 'أله', 'ءلوهة', 'لهة', 'مص. ألَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"أُلوهَةٌ-أُلوهَةٌ [أ ل هـ] (مص. ألَهَ).: مَا يتَعَلَّقُ بصِفَاتِ الذَّات الإلاَهِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18103, 'أُلُوهِيَّةٌ', 'ألوهية', 'مصدر', 'أله', 'ءلوهية', 'لهة', 'مص. ألَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"أُلُوهِيَّةٌ-أُلُوهِيَّةٌ [أ ل هـ] (مص. ألَهَ).: مَا يَتَعَلَّقُ بِصِفاتِ الذَّاتِ الإلاهِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18104, 'إلْهَابٌ', 'إلهاب', 'مصدر', 'لهب', 'ءلهاب', 'إلهب', 'مص. ألْهَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إلْهَابٌ-إلْهَابٌ [ل هـ ب] (مص. ألْهَبَ). 1. ""إلْهَابُ النَّارِ"": إيقَادُهَا، إشْعَالُهَا. 2.""إلْهَابُ الرَّجُلِ"" : تَهْيِيجُهُ. 3.""إلْهَابُ الحِصَانِ"" : إِسْرَاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18105, 'إلْهَامٌ', 'إلهام', 'مصدر', 'لهم', 'ءلهام', 'إلهم', 'مص. ألْهَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إلْهَامٌ-إلْهَامٌ [ل هـ م] (مص. ألْهَمَ). 1.""وَجَاءَهُ الإِلْهَامُ فِي عُزْلَتِهِ"" : مَا يُلْقِي بِهِ اللَّهُ مِنْ أَمْرٍ فِي نَفْسِ عِبَادِهِ الأصْفِيَاءِ لِهَدْيِهِمْ وَاطْمِئْنَانِ قُلُوبِهِمْ. 2.""إِلْهَامُ الشَّاعِرِ"" : مَا يُلْقَى فِي نَفْسِهِ مِنْ صُوَرٍ وأَفْكَارٍ وَمَعانٍ. ¨ ""مِنْ أَيْنَ يَأتِي هَذَا الشَّاعِرُ بِإلْهَامِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18106, 'إلْهَاءٌ', 'إلهاء', 'مصدر', 'لهو', 'ءلهاء', 'إله', 'مص. ألْهَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إلْهَاءٌ-إلْهَاءٌ [ل هـ و] (مص. ألْهَى). ""حَاوَلَ إلْهَاءَهُ عَنْ عَمَلِهِ"" : إِشْغَالَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18107, 'أُمومَةٌ', 'أمومة', 'مصدر', 'أمم', 'ءمومة', 'ممة', 'مص. أَمَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"أُمومَةٌ-أُمومَةٌ [أ م م] (مص. أَمَّ). ""أُمومَةٌ حَنونٌ"" : الرَّابِطَةُ الَّتي تَصِلُ الوالِدَةَ بِأَبْنائِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18108, 'إمَامَةٌ', 'إمامة', 'مصدر', 'أمم', 'ءمامة', 'إممة', 'مص. أمَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إمَامَةٌ-إمَامَةٌ [أ م م] (مص. أمَّ). ""إمَامَةُ الْمُسْلِمِينَ"" : رِئَاسَتُهُمُ العَامَّةُ، مَنْصِبُ الإمَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18109, 'إمَاتَةٌ', 'إماتة', 'مصدر', 'موت', 'ءماتة', 'إمتة', 'مص. أمَاتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إمَاتَةٌ-إمَاتَةٌ [م و ت] (مص. أمَاتَ). 1.""إمَاتَةُ العَدُوِّ"" : قَتْلُهُ أوْ جَعْلُهُ يَمُوتُ. 2.""إمَاتَةُ النَّفْسِ وَالشَّهَوَاتِ"" : قَهْرُهَا، كَبْحُهَا، الضَّغْطُ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18110, 'إمَاطَةٌ', 'إماطة', 'مصدر', 'ميط', 'ءماطة', 'إمطة', 'مص. أمَاطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إمَاطَةٌ-إمَاطَةٌ [م ي ط] (مص. أمَاطَ). 1.""إمَاطَةُ اللِّثَامِ عَنِ الوَجْهِ"" : إزَالَتُهُ. إِماطَةُ الأَذَى عَنِ الطَّريقِ صَدَقَةٌ (حديث): 2.""إمَاطَةُ اللِّثَامِ عَنِ الجَرِيمَةِ"" : إظْهَارُهَا وَالكَشْفُ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18111, 'اِمْتِيازٌ', 'امتياز', 'مصدر', 'ميز', 'امتياز', 'متز', 'مص. اِمْتَازَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِمْتَازَ). 1.""حَصَلَ على دَرَجَةِ امْتِيازٍ"" : دَرَجَةٌ مُمْتازَةٌ جِدّاً. 2.""كانَ يَتَمَتَّعُ بِامْتِيازٍ بَيْنَ أَصْدِقائِهِ"" : بِمَكانَةٍ، بِرُتْبَةٍ عالِيَةٍ. 3.""أَصْبَحَ التَّاجِرُ يَتَمَتَّعُ بِامْتِيازاتٍ تِجارِيَّةٍ جِديدَةٍ"" : اِحْتِكارات حَصَلَ عَلَيْها قانونِيّاً تَسْمَحُ لَهُ دونَ غَيْرِهِ بِبَيْعِ أَصْنافٍ مُعَيَّنَةٍ مِن الْمَوادِّ التِجارِيَّهِ. ""يَتَمَتَّعُ بِامْتِيازاتٍ لا يَتَمَتَّعُ بِها أَحَدٌ"" ""إلى مَتَى وَعَهْدُ الامْتِيازاتِ سائِدٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18112, 'اِمْتِثَالٌ', 'امتثال', 'مصدر', 'مثل', 'امتثال', 'متثل', 'مص. اِمْتَثَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِمْتِثَالٌ-اِمْتِثَالٌ [م ث ل] (مص. اِمْتَثَلَ). ""لَمْ يَكُنْ أمَامَهُ إلاَّ الامْتِثَالُ لِقَرَارِ الْمَحْكَمَةِ"" : أَي الخُضُوعُ، الانْقِيَادُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18113, 'اِمْتِحَانٌ', 'امتحان', 'مصدر', 'محن', 'امتحان', 'متحن', 'مص. اِمْتَحَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِمْتَحَنَ). 1.""تَقَدَّمَ لِلامْتِحَانِ"" : اخْتِبارُ الْمُمْتَحَنِ لِلتَّأكُّدِ مِنْ مَعَارِفِهِ وَمَعْلُومَاتِهِ وَلِمَعْرِفَةِ مُسْتَوَاهُ في مَجالٍ مُعَيَّنٍ. 2.""خَضَعَ لاِمْتِحَانٍ عَسِيرٍ"" : خَضَعَ لِتَجْرِبَةٍ قَوِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18114, 'اِمْتِخَاضٌ', 'امتخاض', 'مصدر', 'مخض', 'امتخاض', 'متخض', 'مص. اِمْتَخَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِمْتِخَاضٌ-اِمْتِخَاضٌ [م خ ض] (مص. اِمْتَخَضَ). 1. ""اِمْتِخَاضُ اللَّبَنِ"" : صَيْرُهُ مَخِيضاً، تَحَرُّكُهُ فِي المِمْخَضَةِ. 2. ""اِمْتِخَاضُ الجَنِينِ"" : تَحَرُّكُهُ فِي بَطْنِ الحَامِل."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18115, 'اِمْتِخاطٌ', 'امتخاط', 'مصدر', 'مخط', 'امتخاط', 'متخط', 'مص. اِمْتَخَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِمْتِخاطٌ-اِمْتِخاطٌ [م خ ط] (مص. اِمْتَخَطَ). ""اِمْتِخاطُ الرَّجُلِ"": إِخْراجُهُ الْمُخاطَ مِنْ أَنْفِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18116, 'اِمْتِدَادٌ', 'امتداد', 'مصدر', 'مدد', 'امتداد', 'متدد', 'مص. اِمْتَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِمْتَدَّ). 1.""وَقَفْنَا نُشَاهِدُ امْتِدَادَ الأفُقِ مِنْ فَوْقِ الجَبَلِ"" : اِنْبِسَاطَهُ. 2.""اِمْتِدَادُ الحَبْلِ مِنْ أقْصَاهُ إلَى أقْصَاهُ"" : طُولُهُ. 3.""اِمْتِدَادُ الحُدُودِ"" : تَرَامِيهَا. 4.""اِمْتِدَادُ الفَيَضَانَاتِ إلَى القُرَى الْمُجَاوِرَةِ"" : اِنْتِقَالُهَا، اِنْتِشَارُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18117, 'اِمْتِدَاحٌ', 'امتداح', 'مصدر', 'مدح', 'امتداح', 'متدح', 'مص. اِمْتَدَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِمْتِدَاحٌ-اِمْتِدَاحٌ [م د ح] (مص. اِمْتَدَحَ). ""اِمْتِدَاحُ السُّلْطَانِ"": الإشَادَةُ بِهِ، مَدْحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18118, 'اِمْتِراسٌ', 'امتراس', 'مصدر', 'مرس', 'امتراس', 'مترس', 'مص. اِمْتَرَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِمْتِراسٌ-اِمْتِراسٌ [م ر س] (مص. اِمْتَرَسَ). 1.""الامتِرَاسُ بالعَمَلِ"" : الاحْتِكَاكُ بِهِ. 2.""اِمْتِرَاسُ الخُطَبَاءِ فِي الخُصومَةِ"" : لِجَاجُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18119, 'اِمْتِنانٌ', 'امتنان', 'مصدر', 'منن', 'امتنان', 'متنن', 'مص. اِمْتَنَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِمْتِنانٌ-اِمْتِنانٌ [م ن ن] (مص. اِمْتَنَّ). 1.""ما هَذَا الامْتِنانُ بِما قَدَّمْت !"" : تَعْدادُ ما قَدَّمْتَ مِن فَضْلٍ. 2.""وَجَّهَ لَه رِسالَةَ شُكْرٍ وَامْتِنانٍ"" : شُكْرٍ وَفَضْلٍ وَعِرْفانٍ بِالجَميلِ. ""بِبالِغِ الامْتِنانِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18120, 'اِمْتِزَاجٌ', 'امتزاج', 'مصدر', 'مزج', 'امتزاج', 'متزج', 'مص. اِمْتَزَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِمْتِزَاجٌ-اِمْتِزَاجٌ [م ز ج] (مص. اِمْتَزَجَ). ""عَرَفَتِ الشُّعُوبُ امْتِزَاجاً عَبْرَ العُصُورِ"" : اِخْتِلاَطاً. ""اِمْتِزَاجُ الْمَوادِّ الكِيميَائِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18121, 'اِمْتِسَاكٌ', 'امتساك', 'مصدر', 'مسك', 'امتساك', 'متسك', 'مص. اِمْتَسَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِمْتِسَاكٌ-اِمْتِسَاكٌ [م س ك] (مص. اِمْتَسَكَ). 1.""الامْتِسَاكُ بالحَبْلِ"" : التَّعَلُّق بِهِ. 2.""الامْتِسَاكُ بالبَلَدِ"" : الْمُكُوثُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18122, 'اِمْتِشَاقٌ', 'امتشاق', 'مصدر', 'مشق', 'امتشاق', 'متشق', 'مص. اِمْتَشَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِمْتِشَاقٌ-اِمْتِشَاقٌ [م ش ق] (مص. اِمْتَشَقَ). ""اِمْتِشَاقُ الفَارِسِ لِسَيْفِهِ"" : اِسْتِلالُهُ مِنْ غِمْدِهِ، إخْرَاجُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18123, 'اِمْتِصَاصٌ', 'امتصاص', 'مصدر', 'مصص', 'امتصاص', 'متصص', 'مص. اِمْتَصَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِمْتِصَاصٌ-اِمْتِصَاصٌ [م ص ص] (مص. اِمْتَصَّ). 1.""اِمْتِصَاصُ عَصِيرٍ"" : رَشْفُهُ رَشْفاً. 2.""اِمْتصَاصُ مَاءِ البِرْكَةِ"" : اِبْتِلاَعُهُ، تَشَرُّبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18124, 'اِمْتِطَاءٌ', 'امتطاء', 'مصدر', 'مطي', 'امتطاء', 'متط', 'مص. اِمْتَطَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِمْتِطَاءٌ-اِمْتِطَاءٌ [م ط ي] (مص. اِمْتَطَى). ""اِمْتِطَاءُ الفَرَسِ"" : رُكُوبُهُ، اِتِّخَاذُهُ مَطِيَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18125, 'إمْتَاعٌ', 'إمتاع', 'مصدر', 'متع', 'ءمتاع', 'إمتع', 'مص. أَمْتَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إمْتَاعٌ-إمْتَاعٌ [م ت ع] (مص. أَمْتَعَ). 1.""الإمْتَاعُ بِالصِّحَّةِ"": التَّمَتُّعُ بِهَا. 2.""الإمْتَاعُ بِالْمَالِ"" : الانْتِفَاعُ بِهِ. ""الإمْتَاعُ والْمُؤانَسَةُ""(التوحيدي): مَنْحُ الْمُتْعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18126, 'اِمْتِعَاضٌ', 'امتعاض', 'مصدر', 'معض', 'امتعاض', 'متعض', 'مص. اِمْتَعَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِمْتِعَاضٌ-اِمْتِعَاضٌ [م ع ض] (مص. اِمْتَعَضَ). ""عَبَّرَ عَنْ اِمْتِعَاضِهِ"" : عَنْ غَضَبِهِ وَتَبَرُّمِهِ. ""كَانَ اِمْتِنَاعِي عَنْ التَّوْقِيعِ سَبَباً فِي اِمْتِعَاضِ العَمِيدِ مِنِّي"". (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18127, 'اِمْتِلاءٌ', 'امتلاء', 'مصدر', 'ملأ', 'امتلاء', 'متل', 'مص. اِمْتَلأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِمْتِلاءٌ-اِمْتِلاءٌ [م ل أ] (مص. اِمْتَلأَ). ""عَرَفَتِ القَاعَةُ امْتِلاءً لَمْ يَسْبِقْ لَهُ مَثِيلٌ"" : اِكْتِظَاظٌ، اِزْدِحَامٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18128, 'اِمْتِلاَكٌ', 'امتلاك', 'مصدر', 'ملك', 'امتلاك', 'متلك', 'مص. اِمْتَلَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِمْتِلاَكٌ-اِمْتِلاَكٌ [م ل ك] (مص. اِمْتَلَكَ). 1.""اِمْتِلاَكُ أَمْوَالِ الغَيْرِ"": الاسْتِيلاءُ، الاسْتِحْوَاذُ. 2. ""يَدَّعِي امْتِلاَكَ الحَقِيقَةِ"": حِيَازَتَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18129, 'أَمْرٌ', 'أمر', 'مصدر', 'أمر', 'ءمر', 'مر', 'مص. أَمَرَ، أَمِرَ', '', '', 'مفرد', 'DnN', '', '', '"أُمُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. أَمَرَ، أَمِرَ). 1.""في أَوَّلِ الأمْرِ"" : الشَّيْءَ، الحالَ، الشَّأْنَ، العَمَلَ. ""في آخِرِ الأَمْرِ"" ""في بادِئ الأَمْرِ"" ""أَمْرٌ بَديهِيٌّ"" ""هَذَا أَمْرٌ طَبيعِيٌّ"". 2.""وَقَعَ بَيْنَ أَمْرَيْنِ"" : يَترَدَّدُ بَيْنَ خِيارَيْنِ"". 3.""الأمْرُ الواقِعُ"": الحال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18130, 'اِمْتِناعٌ', 'امتناع', 'مصدر', 'منع', 'امتناع', 'متنع', 'مص. اِمْتَنَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِمْتِناعٌ-اِمْتِناعٌ [م ن ع] (مص. اِمْتَنَعَ). 1.""اِمْتِناعُ تَحَقُّقِ الأهْدافِ"" : تَعَذُّرُ تَحْقِيقِها. 2.""الامْتِناعُ عَنِ التَّدْخينِ"": الكَفُّ، التَّخَلِّي عَنْهُ. 3.""الامْتِناعُ بِالأَهْلِ"" : الاجْتِماعُ بِهِمْ، الاحْتِماءُ بِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18131, 'اِمْتِهانٌ', 'امتهان', 'مصدر', 'مهن', 'امتهان', 'متهن', 'مص. اِمْتَهَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِمْتِهانٌ-اِمْتِهانٌ [م هـ ن] (مص. اِمْتَهَنَ). 1.""اِمْتِهانُ مِهْنَةٍ"": اِتِّخاذُها مِهْنَةً. 2.""اِمْتِهانُ عَمَلٍ"" : اِحْتِقارُهُ، اِبْتِذالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18132, 'اِمِّحاءٌ', 'امحاء', 'مصدر', 'محي', 'امحاء', 'مح', 'مص. اِمَّحَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِمِّحاءٌ-اِمِّحاءٌ [م ح ي] (مص. اِمَّحَى). ""اِمِّحاءُ الأَثَرِ"": زَوالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18133, 'إِمْدادٌ', 'إمداد', 'مصدر', 'مدد', 'ءمداد', 'إمدد', 'مص. أَمَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَمَدَّ). 1.""إِمْدادُهُ بِمُساعَدَةٍ"" : تَقْديمُ إِعانَةٍ. 2.""تَوَصَّلَ الجَيْشُ بِإِمْداداتٍ عَسْكَرِيَّةٍ"" : العَتادُ،كُلُّ ما يُرْسَلُ إلى القُوَّاتِ الْمُحارِبَةِ مِنْ رِجالٍ وَأَسْلِحَةٍ وَمَؤُونَةٍ لِتَقْوِيَةِ صَفِّها. 3.""هَلْ مِنْ إِمْدادٍ في الأَجَلِ"" : الإطالَةُ فيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18134, 'مُؤَامَرَةٌ', 'مؤامرة', 'مصدر', 'أمر', 'مءامرة', 'ممرة', 'مص. آمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. آمَرَ). ""اِكْتَشَفَ مُؤَامَرَةً تُحَاكُّ ضِدَّهُ"" : تَوَاطُؤٌ بِحَبْكِ مَكِيدَةٍ تُدَبَّرُ فِي الخَفَاءِ لِلْقِيَامِ بِعَمَلٍ مُعَادٍ ضِدَّ نِظَامِ حُكْمٍ أَوْ شَخْصٍ، أَوْ لارْتِكَابِ جَرِيمَةٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18135, 'إمَارَةٌ', 'إمارة', 'مصدر', 'أمر', 'ءمارة', 'إمرة', 'مص. أَمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَمَرَ). ""إمَارَةُ كَذَا"": دَوْلَةٌ صَغِيرَةٌ يَحْكُمُهَا أمِيرٌ. ""لِدَوْلَةِ الإمَارَاتِ العَرَبِيَّةِ دُسْتُورٌ اِتِّحَادِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18136, 'أَمْرٌ', 'أمر', 'مصدر', 'أمر', 'ءمر', 'مر', 'مص. أَمَرَ', '', '', 'مفرد', 'DnN', '', '', '"أَوامِرُ"', '', 'R', '', '', '', '', '', '', '"(مص. أَمَرَ). 1.""نَفَّذَ أَمْرَهُ الْمُطاعَ"" : طَلَبَهُ الَّذي يَنْبَغي أَنْ يُنَفَّذَ. ""يَخْضَعُ لِلأَوامِرِ وَالنَّواهِي"". 2.""أُولُو الأَمْرِ، لَهُمُ الكَلِمَةُ الأَخِيرَةُ"" : الحُكَّامُ وَالرُّؤَساءُ، أَص"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18137, 'أَوامِرُ', 'أوامر', 'مصدر', '', 'ءوامر', 'مر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18138, 'إِمْرارٌ', 'إمرار', 'مصدر', 'مرر', 'ءمرار', 'إمرر', 'مص. أَمَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْرارٌ-إِمْرارٌ [م ر ر] (مص. أَمَرَّ). 1.""إِمْرارُ الطَّعامِ"" : جَعْلُهُ مُرّاً. 2.""إِمْرارُ الأَعْمَى"" : الأَخْذُ بِيَدِهِ وَجَعْلُهُ يَمُرُّ. 3.""إِمْرارُ الحَبْلِ"" : فَتْلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18139, 'إِمْصالٌ', 'إمصال', 'مصدر', 'مصل', 'ءمصال', 'إمصل', 'مص. أَمْصَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْصالٌ-إِمْصالٌ [م ص ل] (مص. أَمْصَلَ). 1.""إِمْصالُ الغَنَمِ"": حَلْبُهُ إِلَى حِينِ اسْتِيعابِ مَا فِيها. 2.""إِمْصالُ المالِ"" : صَرْفُهُ في ما لاخَيْرَ فيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18140, 'أُمُورٌ', 'أمور', 'مصدر', '', 'ءمور', 'مر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18141, 'إِمْراضٌ', 'إمراض', 'مصدر', 'مرض', 'ءمراض', 'إمرض', 'مص. أَمْرَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْراضٌ-إِمْراضٌ [م ر ض] (مص. أَمْرَضَ). ""إِمْراضُ الرَّجُلِ"": صَيْرُهُ ذا مَرَضٍ، جَعْلُهُ مَريضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18142, 'إِمْراعٌ', 'إمراع', 'مصدر', 'مرع', 'ءمراع', 'إمرع', 'مص. أَمْرَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْراعٌ-إِمْراعٌ [م ر ع] (مص. أَمْرَعَ). ""إِمْراعُ الحَقْلِ"": إِخْصابُهُ، كَثْرَةُ العُشْبِ فيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18143, 'إِمْراغٌ', 'إمراغ', 'مصدر', 'مرغ', 'ءمراغ', 'إمرغ', 'مص. أَمْرَغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْراغٌ-إِمْراغٌ [م ر غ] (مص. أَمْرَغَ). 1.""إِمْراغُ النَّائِمِ"" : سَيَلانُ لُعابِهِ مِنْ ناحِيَتَيْ فَمِهِ. 2.""إِمْراغُ الخَطِيبِ"" : إِكْثارُهُ الكلامَ في غَيْرِ صَوابٍ. 3.""إِمْراغُ العَجينِ"" : إِكْثارُ مائِهِ. 4.""إِمْراغُ العِرْضِ"" : تَدْنِيسُهُ، تَلْطيخُهُ، إِهانَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18144, 'إِمْراقٌ', 'إمراق', 'مصدر', 'مرق', 'ءمراق', 'إمرق', 'مص. أَمْرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْراقٌ-إِمْراقٌ [م ر ق] (مص. أَمْرَقَ). 1.""إِمْراقُ القِدْرِ"" : إِكْثارُ مَرَقِهِ. 2.""إِمْراقُ السَّهْمِ"" : جَعْلُهُ يَنْفُذُ مِنَ الرَّمْيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18145, 'إِمْساكٌ', 'إمساك', 'مصدر', 'مسك', 'ءمساك', 'إمسك', 'مص. أَمْسَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْساكٌ-إِمْساكٌ [م س ك] (مص. أَمْسَكَ). 1.""أُصيبَ بِإِمْساكٍ مُنْذُ يَوْمَيْنِ"" : بِقَبْضٍ، أَيْ تَجَمُّدُ ما في الأمْعاءِ، عُسْرُ البِرازِ. 2.""الإِمْساكُ"" : الصَّوْمُ، أَي الامْتِناعُ عَنِ الأَكْلِ والشَّرابِ والشَّهْوَةِ مِنْ طُلُوعِ الفَجْرِ إلى غُرُوبِ الشَّمْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18146, 'مُمْسىً', 'ممسى', 'مصدر', 'مسو', 'ممسى', 'ممس', 'مص. أَمْسَى', '', '', 'مفرد', 'Dy', '', '', '"ممسوات"', '', 'R0', '', '', '', '', '', '', '"مُمْسىً-مُمْسىً [م س و] (مص. أَمْسَى). 1.""وَصَلَ إِلَى مُمْسَاهُ"" : إلَى مَكَانِهِ الَّذِي يُمْسَى فِيهِ. 2.""الْحَمْدُ للهِ مُمْسَانَا وَمُصْبَحُنَا"" : الشُّكْرُ للهِ مَسَاءً وَصَبَاحاً. 3.""اِسْتَقَرَّ الرَّاهِبُ فِي الْمُمْسَى"" : في الصَّوْمَعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18147, 'ممسوات', 'ممسوات', 'مصدر', '', 'ممسوات', 'ممست', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18148, 'إِمْصاصٌ', 'إمصاص', 'مصدر', 'مصص', 'ءمصاص', 'إمصص', 'مص. أَمَصَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْصاصٌ-إِمْصاصٌ [م ص ص] (مص. أَمَصَّ). ""إِمْصاصُ اللَّبَنِ"": جَعْلُهُ يُمَصُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18149, 'إِمْلاحٌ', 'إملاح', 'مصدر', 'ملح', 'ءملاح', 'إملح', 'مص. أَمْلَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْلاحٌ-إِمْلاحٌ [م ل ح] (مص. أَمْلَحَ). ""إِمْلاحُ الطَّعامِ"": وَضْعُ قَدْرٍ مُعَيَّنٍ مِنَ المِلْحِ فيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18150, 'إِمْضاغٌ', 'إمضاغ', 'مصدر', 'مضغ', 'ءمضاغ', 'إمضغ', 'مص. أَمْضَغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْضاغٌ-إِمْضاغٌ [م ض غ] (مص. أَمْضَغَ). 1.""إِمْضاغُ اللَّحْمِ"": اِسْتِطابَتُهُ وَأَكْلُهُ. 2.""إِمْضاغُ التَّمْرِ"" : كَوْنُهُ قَدْ حانَ مَضْغُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18151, 'إِمْضاءٌ', 'إمضاء', 'مصدر', 'مضي', 'ءمضاء', 'إمض', 'مص. أَمْضى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"(مص. أَمْضى). 1.""إِمْضاءُ أَمْرٍ"" : تَنْفِيذُهُ، إِنْجازُهُ. 2.""إِمْضَاءُ وَثِيقَةٍ"": التَّوْقيعُ عَلَيْهَا، عَلامَةٌ بِخَطِّ اليَدِ يَتَمَيَّزُ بِها كُلُّ واحِدٍ عَنْ غَيْرهِ وَيَصْعُبُ تَقْلِيدُها. 3.""تَوَصَّلْتُ بِرِسالَةٍ عَلَيْها إِمْضاءُ الْمُديرِ"" : خاتَمُهُ، طابَعُهُ، تَوْقِيعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18152, 'إِمْطارٌ', 'إمطار', 'مصدر', 'مطر', 'ءمطار', 'إمطر', 'مص. أَمْطَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْطارٌ-إِمْطارٌ [م ط ر] (مص. أَمْطَرَ). 1.""إِمْطارُ السَّماءِ"" : إِنْزالُها مَطَراً. 2.""إِمْطارُهُمْ بِوابِلٍ مِنَ القَنابِلِ"" : إِغْراقُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18153, 'إِمْطاءٌ', 'إمطاء', 'مصدر', 'مطي', 'ءمطاء', 'إمط', 'مص. أَمْطَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِمْطاءٌ-إِمْطاءٌ [م ط ي] (مص. أَمْطَى). 1.""إِمْطاءُ الدَّابَّةِ"" : رُكوبُها. 2. ""رَغِبَ في إِمْطائِهِ الدَّابَّةَ"" : إِرْكابِهِ إِيَّاها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18154, 'إِمْعانٌ', 'إمعان', 'مصدر', 'معن', 'ءمعان', 'إمعن', 'مص. أَمْعَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْعانٌ-إِمْعانٌ [م ع ن] (مص. أَمْعَنَ). ""رَكَّزَ فِكْرَهُ بِإِمْعانٍ"": بانْتِباهٍ، بِتَيَقُّظٍ، باهْتِمامٍ. ""مَعْروفٌ بِإمْعانِ النَّظَرِ"" ""الحِجابُ كانَ يُغَطِّي الْمَرْأَةَ بِهالَةٍ تُمَكِّنُ الرَّجُلَ مِنَ الإمْعانِ في التَّخَيُّلاتِ"". (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18155, 'إِمْكانٌ', 'إمكان', 'مصدر', 'مكن', 'ءمكان', 'إمكن', 'مص. أَمْكَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْكانٌ-إِمْكانٌ [م ك ن] (مص. أَمْكَنَ). 1.""سَأَنْساهُمْ بِقَدْرِ الإِمْكانِ"" : بِقَدْرِ طاقَتِي، قُوَّتِي. 2.""لَيْسَ بِإِمْكانِهِ أَنْ يُنْجِزَ هَذا العَمَلَ"" : ليْسَ بِمَقْدُورهِ. 3.""لَيْسَ في الإِمْكانِ بِناءُ عِمارَةٍ في يَوْمٍ"" : في الاسْتِطاعَةِ. ""بِالإمْكانِ الآنَ إِبْداعُ أَفْضَلَ مِمَّا كانَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18156, 'أَمَلٌ', 'أمل', 'مصدر', 'أمل', 'ءمل', 'مل', 'مص. أَمَلَ', '', '', 'مفرد', 'DnN', '', '', '"آمال"', '', 'R', '', '', '', '', '', '', '"(مص. أَمَلَ). 1.""أَمَلُهُ وَطيدٌ بِأَنْ يُحَقِّقَ رَغَباتِهِ"" : رَجاؤُهُ. ""وَطيدُ الأمَلِ"" ""على أَمَلِ أَنْ نَلْتَقيَ"" ""ما أَضْيَقَ العَيْشَ لَوْلاَ فُسْحَةُ الأَمَلِ"" (الطغرائي): أَي لَوْلاَ الرَّجاءُ وَما يَتَمَنَّاهُ الْمَرْءُ لَضاقَ عَيْشُهُ. ""كُلُّهُ أَمَلٌ"". 2.""أَمَل"": اِسْمُ عَلَمٍ. ج: آمالٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18157, 'آمال', 'آمال', 'مصدر', '', 'ءءمال', 'آمل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18158, 'إِمْلالٌ', 'إملال', 'مصدر', 'ملل', 'ءملال', 'إملل', 'مص. أَمَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْلالٌ-إِمْلالٌ [م ل ل] (مص. أَمَلَّ). ""وَجَدَ في حَديثِهِ إِمْلالاً"": مَلَلاً، نُفوراً، ضَجَراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18159, 'أَمْنٌ', 'أمن', 'مصدر', 'أمن', 'ءمن', 'من', 'مص. أَمِنَ، أَمَنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أَمْنٌ-أَمْنٌ [أ م ن] (مص. أَمِنَ، أَمَنَ). 1.""يَعيشُ في أَمْنٍ"": في طُمَأْنينَةٍ وَيُسْرٍ. 2.""وَصَلَتْ سَيَّارَةُ رِجالِ الأَمْنِ، قُوَّاتُ الأَمْنِ"" : رِجالُ الشُّرْطَةِ الَّذِينَ يَسْهَرونَ على حِفْظِ القانُونِ وَسَلامَةِ النَّاسِ وَحِمايَتِهِمْ وَجَعْلِهِمْ في أَمانٍ وَطُمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18160, 'إِمْلاقٌ', 'إملاق', 'مصدر', 'ملق', 'ءملاق', 'إملق', 'مص. أَمْلَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْلاقٌ-إِمْلاقٌ [م ل ق] (مص. أَمْلَقَ).الإسراء آية 31 وَلاَ تَقْتُلوا أَوْلادَكُمْ خَشْيَةَ إِمْلاقٍ (قرآن): خَشْيَةَ الافْتِقارِ، الفَقْرِ، الإعْوازِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18161, 'إِمْلاكٌ', 'إملاك', 'مصدر', 'ملك', 'ءملاك', 'إملك', 'مص. أَمْلَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْلاكٌ-إِمْلاكٌ [م ل ك] (مص. أَمْلَكَ). 1.""إِمْلاكُ شَيْءٍ"": جَعْلُهُ مِلْكاً. 2.""إِمْلاكُ الزَّواجِ"" : عَقْدُ الزَّواجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18162, 'إِمْلاءٌ', 'إملاء', 'مصدر', 'ملو', 'ءملاء', 'إمل', 'مص. أَمْلى', '', '', 'مفرد', 'Dz', '', 'Pf', '":أمالي"', '', 'Rz', '', '', '', '', '', '', '"(مص. أَمْلى). ""لاَ يَرْتَكِبُ أَخْطاءً في الإمْلاءِ"" : ما يُمْلَى مِنْ كَلامٍ لِيُكْتَبَ مُباشَرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18163, 'أمالي', 'أمالي', 'مصدر', '', 'ءمالي', 'مل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18164, 'تَأْمِيمٌ', 'تأميم', 'مصدر', 'أمم', 'تءميم', 'تمم', 'مص. أَمَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْمِيمٌ-تَأْمِيمٌ [أ م م] (مص. أَمَّمَ). ""قَرَّرَتِ الدَّوْلَةُ تَأْمِيمَ الشَّرِكَاتِ الكُبْرَى"" : أَيْ جَعْلهَا فِي مِلْكِ الدَّوْلَةِ وَخِدْمَتِها، وَهُوَ نِظَامٌ تَعْمَلُ ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18165, 'إيمَانٌ', 'إيمان', 'مصدر', 'أمن', 'ءيمان', 'إمن', 'مص. آمَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"إيمَانٌ-إيمَانٌ [أ م ن] (مص. آمَنَ). 1.""لَهُ إيمَانٌ قَوِيٌّ"" : التَّصْدِيقُ العَمِيقُ بِالشَّيْءِ. 2.""دَخَلَ الإيمَانُ إلَى قَلْبِه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18166, 'تَأْمِينٌ', 'تأمين', 'مصدر', 'أمن', 'تءمين', 'تمن', 'مص. أَمَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْمِينٌ-تَأْمِينٌ [أ م ن] (مص. أَمَّنَ). ""جَدَّدَ تَأْمِينَ سَيَّارَتِهِ"" : إِجْرَاءٌ يَقْضِي بِدَفْعِ مَبْلَغٍ مِنَ الْمَالِ لِلشَّرِكَةِ الْمُؤَمِّنَةِ مُقَابِلَ أَنْ ت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18167, 'أمَانَةٌ', 'أمانة', 'مصدر', 'أمن', 'ءمانة', 'منة', 'مص. أمُنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أمُنَ). 1.""تَرَكَ عِنْدَهُ أمَانَةً"" : وَدِيَعةً. النساء آية 58إنَّ اللَّهَ يَأْمُرُكُمْ أنْ تُؤَدُّوا الأَمَانَاتِ إلَى أَهْلِهَا (قرآن). 2.""عُرِفَ بِالأَمَانَةِ"" : أَيْ بِالاسْتِقَامَةِ، بِالصِّدْقِ. 3.""أدَّى وَاجِبَهُ بِإخْلاَصٍ وَأمَانَةٍ"" : أي وَوَفَاءٍ. لاَ إي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18168, 'أمَانٌ', 'أمان', 'مصدر', 'أمن', 'ءمان', 'من', 'مص. أمِنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"أمَانٌ-أمَانٌ [أ م ن] (مص. أمِنَ). 1.""وَدَّعَ ابْنَهُ فِي أمَانِ اللَّهِ وَحِفْظِهِ"" : فِي حِمَايَتِهِ. 2.""أعْطَاهُ الأمِيرُ الأمَانَ فَلاَ خَوْفَ عَلَيْهِ"" : أيْ كَانَ هَارِباً خَائِفاً منَ العِقَابِ فَأعْطَاهُ الحِمَايَةَ وَطَمْأ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18169, 'إِنْباءٌ', 'إنباء', 'مصدر', 'نبأ', 'ءنباء', 'إنب', 'مص. أَنْبَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِنْباءٌ-إِنْباءٌ [ن ب أ] (مص. أَنْبَأَ). ""جاءَ إِنْباؤُهُ مُتَأَخِّراً"": إِعْلامُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18170, 'إِمْهالٌ', 'إمهال', 'مصدر', 'مهل', 'ءمهال', 'إمهل', 'مص. أَمْهَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِمْهالٌ-إِمْهالٌ [م هـ ل] (مص. أَمْهَلَ). ""طَلَبَ إِمْهالَهُ فَتْرَةً مِنَ الوَقْتِ"" : أَيْ إِعْطاؤُهُ مُهْلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18171, 'أَيْنٌ', 'أين', 'مصدر', 'أين', 'ءين', 'ن', 'مص. آن', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أَيْنٌ-أَيْنٌ [أ ي ن] (مص. آن). 1. ""فِي الأَيْنِ"" : فِي الحِين"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18172, 'أوْنٌ', 'أون', 'مصدر', 'أون', 'ءون', 'ن', 'مص. آنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أوْنٌ-أوْنٌ [أ و ن] (مص. آنَ). 1.""أجَابَ فِي أَوْنِهِ"" : فِي أَوانِهِ، حِينِهِ. 2.""عَامَلَهُ بأوْنٍ"" : بِرِفْقٍ. 3.""تَكَلَّمَ بِأَوْنٍ"" : بِهُدُوءٍ. 4.""وَجَدَهُ يَمْشِي عَلَى أوْنٍ"" : عَلَى مَهْلٍ.5.""اِتَّكَأَ عَلَى أوْنِهِ"" : عَلَى خاصِرَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18173, 'أَنَّةٌ', 'أنة', 'مصدر', 'أنن', 'ءنة', 'نة', 'مص. أَنَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَنَّ). ""كُنْتُ أَسْمَعُ أَنَّتَهُ مِنْ بَعيدٍ"" : أَنينَهُ، أَيْ ما يَصْدُرُ عَنِ الإِنْسانِ مِنْ صَوْتٍ خافِتٍ في لَحَظاتِ الألَمِ والتَّوَجُّعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18174, 'أنِينٌ', 'أنين', 'مصدر', 'أنن', 'ءنين', 'نن', 'مص. أنَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"أنِينٌ-أنِينٌ [أ ن ن] (مص. أنَّ). 1. ""كانَ أنِينُهُ يُوجِعُ القَلْبَ"" : صَوْتٌ صَادِرٌ عَنْ ألَمٍ أوْ مَرَضٍ أوْ وَجَعٍ. 2.""كَانَ صَدَى الأَنِينِ يَهُزُّ النُّفُوسَ"" : رَجْعُ التَّوَجُّعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18175, 'إِنابَةٌ', 'إنابة', 'مصدر', 'نوب', 'ءنابة', 'إنبة', 'مص. أَنابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنابَةٌ-إِنابَةٌ [ن و ب] (مص. أَنابَ). 1.""تَوَلَّى إِنابَةَ الرَّئيسِ"": القِيامُ بِتَوَلِّي مَهامِّ الرَّئِيسِ بِتَفْوِيضٍ مِنْهُ. 2.""الإِنابَةُ إلى اللَّهِ"": الرُّجوعُ إلى الحَقِّ بَعْدَ التَّوْبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18176, 'إِنارَةٌ', 'إنارة', 'مصدر', 'نور', 'ءنارة', 'إنرة', 'مص. أَنارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنارَةٌ-إِنارَةٌ [ن و ر] (مص. أَنارَ). 1.""إِنارَةُ البَيْتِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18177, 'إِناطَةٌ', 'إناطة', 'مصدر', 'نوط', 'ءناطة', 'إنطة', 'مص. أَناطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِناطَةٌ-إِناطَةٌ [ن و ط] (مص. أَناطَ). 1.""إِناطَتُهُ بِحَبْلٍ"": تَعْلِيقُهُ. 2.""إِناطَتُهُ بِشُؤُونِ الْمُؤَسَّسَةِ"" : تَكْليفُهُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18178, 'تَأْنِيبٌ', 'تأنيب', 'مصدر', 'أنب', 'تءنيب', 'تنب', 'مص. أَنَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْنِيبٌ-تَأْنِيبٌ [أ ن ب] (مص. أَنَّبَ). 1.""شَعَرَ بِتَأْنِيبِ الضَّمِيرِ"" : ضَمِيرُهُ يَلُومُهُ وَيُوَبِّخُهُ بِشِدَّةٍ عَلَى مَا فَعَلَ. 2.""قَرَّرَ تَأْنِيبَ ابْنِهِ"" : أَيْ مَلاَمَتَهُ وَإِيلاَمَهُ بِعُنْفِ عَلَى أَعْمِالِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18179, 'اِنْبِهارٌ', 'انبهار', 'مصدر', 'بهر', 'انبهار', 'نبهر', 'مص. اِنْبَهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْبِهارٌ-اِنْبِهارٌ [ب هـ ر] (مص. اِنْبَهَرَ). 1.""اِنْقَشَعَتِ الأنْوارُ، فَعاشَ لَحْظَةَ انْبِهارٍ شَديدٍ"" : اِخْتِطافُ بَصَرِهِ. ""اِنْبِهارُ البَصَرِ"". 2.""يَتَأَثَّرُ بِانْبِهارِ النَّاسِ"" : سَريعُ التَّأَثُّرِ بانْدِهاشِهِمْ وَإِعْجابِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18180, 'إِنْباتٌ', 'إنبات', 'مصدر', 'نبت', 'ءنبات', 'إنبت', 'مص. أَنْبَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْباتٌ-إِنْباتٌ [ن ب ت] (مص. أَنْبَتَ). 1.""إِنْباتُ النَّباتِ"": جَعْلُهُ يَنْبُتُ وَيَنْمُو. 2.""إِنْباتُ الزَّرْعِ"" : نُمُوُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18181, 'اِنْبِثاثٌ', 'انبثاث', 'مصدر', 'بثث', 'انبثاث', 'نبثث', 'مص. اِنْبَثَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْبِثاثٌ-اِنْبِثاثٌ[ب ث ث] (مص. اِنْبَثَّ). 1.""اِنْبِثاثُ الغُبارِ"" : اِنْتِشارُهُ. 2.""اِنْبِثاثُ النُّورِ"" : إِشْعاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18182, 'اِنْبِثاقٌ', 'انبثاق', 'مصدر', 'بثق', 'انبثاق', 'نبثق', 'مص. اِنْبَثَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْبِثاقٌ-اِنْبِثاقٌ [ب ث ق] (مص. اِنْبَثَقَ). 1.""اِنْبِثاقُ آمالٍ جَديدَةٍ"" : ظُهورُ، اِنْبِلاجُ. 2.""الانْبِثاقُ عِنْدَ الْمَسيحِيِّينَ"" : الصُّدورُ. ""اِنْبِثاقُ الرُّوحِ القُدُسِ مِنَ الأَبِ والابْنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18183, 'اِنْبِجاسٌ', 'انبجاس', 'مصدر', 'بجس', 'انبجاس', 'نبجس', 'مص. اِنْبَجَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْبِجاسٌ-اِنْبِجاسٌ [ب ج س] (مص. اِنْبَجَسَ). ""اِنْبِجاسُ الماءِ"": اِنْبِثاقُهُ، تَفَجُّرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18184, 'اِنْبِرامٌ', 'انبرام', 'مصدر', 'برم', 'انبرام', 'نبرم', 'مص. اِنْبَرَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْبِرامٌ-اِنْبِرامٌ [ب ر م] (مص. اِنْبَرَمَ). ""اِنْبِرامُ حَبْلٍ"" : اِنْفِتالُهُ، اِلْتِواؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18185, 'اِنْبِساطٌ', 'انبساط', 'مصدر', 'بسط', 'انبساط', 'نبسط', 'مص. اِنْبَسَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْبِساطٌ-اِنْبِساطٌ [ب س ط] (مص. اِنْبَسَطَ). 1.""أَرَى على وَجْهِهِ انْبِساطاً"" : اِنْشِراحاً. 2.""اِنْبِساطُ الذِّراعَيْنِ"": اِمْتِدادُهُما. ""قابِلِيَّةُ التَّمَدُّدِ وَالاِنْبِساطِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18186, 'اِنْبِطاحٌ', 'انبطاح', 'مصدر', 'بطح', 'انبطاح', 'نبطح', 'مص. اِنْبَطَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْبِطاحٌ-اِنْبِطاحٌ [ب ط ح] (مص. اِنْبَطَحَ). 1.""اِنْبِطاحُ الرَّجُلِ"": اِسْتِلْقاؤُهُ على وَجْهِهِ ذَليلاً. 2.""ما هَذَا الاِنْبِطاحُ يا رَجُلُ"" : لِباسُ ثَوْبِ الْمَسْكَنَةِ والذُّلِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18187, 'اِنْبِعاثٌ', 'انبعاث', 'مصدر', 'بعث', 'انبعاث', 'نبعث', 'مص. اِنْبَعَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْبِعاثٌ-اِنْبِعاثٌ [ب ع ث] (مص. اِنْبَعَثَ). 1.""اِنْبِعاثُ الأمْواتِ"" : إِحْياؤُها. 2.""اِنْبِعاثُ رائِحَةٍ مِنَ البِئْرِ"" : صُعودُها. 3"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18188, 'اِنْبِلاجٌ', 'انبلاج', 'مصدر', 'بلج', 'انبلاج', 'نبلج', 'مص. اِنْبَلَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْبِلاجٌ-اِنْبِلاجٌ [ب ل ج] (مص. اِنْبَلَجَ). ""يَنْتَظِرُ انْبِلاجَ الصُّبْحِ"" : إِشْراقَهُ، طُلوعَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18189, 'اِنْتِسابٌ', 'انتساب', 'مصدر', 'نسب', 'انتساب', 'نتسب', 'مص. اِنْتَسَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِسابٌ-اِنْتِسابٌ [ن س ب] (مص. اِنْتَسَبَ). 1.""أَكَّدَ انْتِسابَهُ إلى أُسْرَة كَذَا"" : أَكَّدَ أَنَّ نَسَبَهُ يَرْجِعُ، يَعودُ إلى...، يَنْحَدِرُ. 2.""يَرْغَبُ في الانْتِسابِ إلى جَماعَةٍ مَّا أو هَيْئَةٍ مَّا"": الانْتِماءُ إلى جَماعَةٍ أَوْ هَيْئَةٍ. 3.""يُفَضِّلُ الانْتِسابَ إلى مُؤَسَّسَةٍ...أَو مَعْهَدٍ..."" : الاِنْضِمامُ إلى مُؤَسَّسَةٍ أَوْ مَعْهَدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18190, 'اِنْتِباهٌ', 'انتباه', 'مصدر', 'نبه', 'انتباه', 'نتبه', 'مص. اِنْتَبَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِباهٌ-اِنْتِباهٌ [ن ب هـ] (مص. اِنْتَبَهَ). 1.""عُرِفَ بِحُسْنِ انْتِباهِهِ"" : تَيَقُّظِهِ، أَيْ هُوَ حاضِرُ البَديهَةِ والفِطْنَةِ. ""كُلُّ ما أَخافُ مِنْهُ هُوَ عَدَمُ الانْتِباهِ"". 2.""الانْتِباهُ مِنَ النَّوْمِ"": الاسْتِيقاظُ. 3.""يَجْذِبُ الانْتِباهَ بِحَديثِهِ"" : الاهْتِمامَ. 4.""اِسْتَرْعَى الانْتِباهَ"" : اِسْتَوْقَفَ النَّظَرَ. ""لَفَتَ انْتِباهَهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18191, 'إِنْتاجٌ', 'إنتاج', 'مصدر', 'نتج', 'ءنتاج', 'إنتج', 'مص. أَنْتَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْتاجٌ-إِنْتاجٌ [ن ت ج] (مص. أَنْتَجَ). 1.""يَزيدُ إِنْتاجُ الْمَعْمَلِ يَوْمِيّاً"" : ما يَصْنَعُهُ العُمَّالُ مِنْ مَوَادَّ. 2.""كانَ الإِنْتاجُ الزِّراعِيُّ لِهَذِهِ السَّنَةِ وافِراً"" : ما تُعْطيهِ الأَرْضُ مِنْ مَحْصولِ الفَواكِهِ أَوِ الخُضَرِ أَوِ الحُبوبِ. 3.""الإنْتاجُ الأَدَبِيُّ"" : الكِتاباتُ الأَدَبِيَّةُ وَاِبْتِكارَاتُها. 4.""قَلَّ إِنْتاجُهُ"" : تَضاءَلَ ما يُقَدِّمُهُ مِنْ عَمَلٍ. 5.""طاقَةُ الإِنْتاجِ"" : طاقَةُ ما يُنْتَجُ. 6.""هَذَا الفِلْمُ مِنْ إِنْتاجِ..."": مِنْ إِنْجازِ وَتُهَيِّئ وَتَحْضيرِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18192, 'اِنْتِجاعٌ', 'انتجاع', 'مصدر', 'نجع', 'انتجاع', 'نتجع', 'مص. اِنْتَجَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِجاعٌ-اِنْتِجاعٌ [ن ج ع] (مص. اِنْتَجَعَ). 1.""اِنْتِجاعُ القَوْمِ"": ذَهابُهُمْ لِطَلَبِ الكَلإِ والرَّاحَةِ. 2.""اِنْتِجاعُ العُشْبِ"" : طَلَبُهُ في مَوْضِعِهِ. 3.""اِنْتِجاعُ حاكِمٍ"" : طَلَبُ مَعْروفِهِ وَإِحْسانِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18193, 'اِنْتِحابٌ', 'انتحاب', 'مصدر', 'نحب', 'انتحاب', 'نتحب', 'مص. اِنْتَحَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِحابٌ-اِنْتِحابٌ [ن ح ب] (مص. اِنْتَحَبَ). ""اِسْتَمَرَّ انْتِحابُ النِّساءِ النَّهارَ كُلَّهُ"" : البُكاءُ الشَّديدُ والْمُسْتَمِرُّ وَقْتاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18194, 'اِنْتِحارٌ', 'انتحار', 'مصدر', 'نحر', 'انتحار', 'نتحر', 'مص. اِنْتَحَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِنْتِحارٌ-اِنْتِحارٌ [ن ح ر] (مص. اِنْتَحَرَ). ""لاَ أَحَدَ يَعْرِفُ سَبَبَ انْتِحارِهِ"" : قَتْلُ نَفْسِهِ بِنَفْسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18195, 'اِنْتِحالٌ', 'انتحال', 'مصدر', 'نحل', 'انتحال', 'نتحل', 'مص. اِنْتَحَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِحالٌ-اِنْتِحالٌ [ن ح ل] (مص. اِنْتَحَلَ). ""اِنْتِحالُ الكاتِبِ لأَفْكارِ غَيْرِهِ"" : أَخْذُها والادِّعاءُ بِأَنَّهُ صاحِبُها. ""اِنْتِحالُ صِفَةٍ أَوْ شَخْصِيَّةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18196, 'اِنْتِخابٌ', 'انتخاب', 'مصدر', 'نخب', 'انتخاب', 'نتخب', 'مص. اِنْتَخَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. اِنْتَخَبَ). 1.""سَيَجْري انْتِخابُ أَعْضاءِ البَرْلَمانِ قَريباً"" : أُسْلوبٌ ديمُقْراطِيٌّ يَخْتارُ بِهِ الشَّعْبُ نُوَّاباً عَنْهُ لِيَتَكَلَّمُوا باسْمِهِ وَيُدافِعُوا عَنْ مَصالِحِهِ، الاقْتِراعُ. 2.""لائِحَةُ الانْتِخاباتِ"" : لائِحَةٌ تُسَجَّلُ فيها أَسْماءُ الْمُنْتَخِبينَ مِمَّنْ بَلَغُوا سِنَّ الانْتِخابِ، أَيْ حَقَّ التَّصْويتِ. ""يَحْرِصُ على سَيْرِ الانْتِخاباتِ في جَوٍّ ديمُقْراطِيٍّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18197, 'اِنْتِدابٌ', 'انتداب', 'مصدر', 'ندب', 'انتداب', 'نتدب', 'مص. اِنْتَدَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِدابٌ-اِنْتِدابٌ [ن د ب] (مص. اِنْتَدَبَ). 1.""قامَ الْمَجْلِسُ بانْتِدابِ أَحَدِ أَعْضائِه لِحُضورِ مَراسيمِ عيدِ الاسْتِقْلالِ"": بإرْسالِهِ وَتَكْليفِهِ. 2. ""وَقَعَتْ فِلِسْطينُ تَحْتَ الانْتِدابِ البْريطانِيِّ"" : تَحْتَ الوصايَةِ، اِتِّفاقٌ مُؤَقَّتٌ تَخْضَعُ فيهِ أَرْضُ بَلَدٍ مِنَ البُلْدَانِ لِحُكْمِ دَوْلةٍ أُخْرَى حَيْثُ تُمارِسُ سُلْطَتَها الإِدارِيَّةَ إلى أَنْ يَنْتَهِي العَمَلُ بِهِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18198, 'اِنْتِزاعٌ', 'انتزاع', 'مصدر', 'نزع', 'انتزاع', 'نتزع', 'مص. اِنْتَزَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِزاعٌ-اِنْتِزاعٌ [ن ز ع] (مص. اِنْتَزَعَ). 1.""اِنْتِزاعُ جِذْرِ شَجَرَةٍ"" : اِقْتِلاعُها. 2.""اِنْتِزاعُ النُّقُودِ"" : سَلْبُها قَهْراً. 3.""اِنْتِزاعُ إِعْجابِ الجُمْهورِ"" : جَلْبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18199, 'اِنْتِساخٌ', 'انتساخ', 'مصدر', 'نسخ', 'انتساخ', 'نتسخ', 'مص. اِنْتَسَخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِساخٌ-اِنْتِساخٌ [ن س خ] (مص. اِنْتَسَخَ). ""اِنْتِساخُ كِتابٍ"": نَسْخُهُ، أَيْ نَقْلُهُ كِتابَةً حَرْفاً بِحَرْفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18200, 'اِنْتِسَالٌ', 'انتسال', 'مصدر', 'نسل', 'انتسال', 'نتسل', 'مص. اِنْتَسَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِسَالٌ-اِنْتِسَالٌ [ن س ل] (مص. اِنْتَسَلَ). 1.""اِنْتِسَالُ حَيَوَانٍ"": اِسْتِثْمَارُهُ وَأَخْذُ نَسْلٍ مِنْهُ. وَهُوَ مَا يُقَابِلُ كَلِمَةَ اِسْتِنْسَاخ الَّتِي شَاعَتْ خَطَأ بَعْدَ تَجْرِبَةِ نَعْجَةِ ""دُولي"". 2.""الانْتِسالُ الاِصْطِناعِيّ"" : الحُصولُ بِواسِطَةِ اِخْتِباراتٍ بِيولوجِيَّةٍ على مَجْموعَةٍ مِنَ الجُزْئِيَّاتِ الْمُتَماثِلَةِ أَوْ كائِناتٍ أَحادِيَّةِ الخَلِيَّةِ أو مُتَعَدِّدَةِ الخلايا (برمائيات ثَدْيِيّات) مُزَوّدَةٌ بِعناصِرَ وِراثِيَّةٍ مُتَماثِلَةٍ، ولَقَدْ تَمَّ تَطويرُ هَذِهِ الاخْتِباراتِ، وهُوَ ما نَتَجَ عَنِ التَّجْرِبَةِ العِلْمِيَّةِ الَّتِي عُرِفَتْ بِنَعْجَةِ ""دُولي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18201, 'اِنْتِشارٌ', 'انتشار', 'مصدر', 'نشر', 'انتشار', 'نتشر', 'مص. اِنْتَشَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِشارٌ-اِنْتِشارٌ [ن ش ر] (مص. اِنْتَشَرَ). ""عَرَفَتِ الآلاتُ الإِليكترونِيَّةُ انْتِشاراً واسِعاً"" : ذُيوعاً، شُيوعاً، أَيْ صارَتْ مَوْجودَةً في كُلِّ مَكانٍ. ""تَعْرِفُ اللُّغَةُ العَرَبِيَّةُ انْتِشاراً"" ""اِنْتِشارُ الأَفْكارِ"" ""اِنْتِشارُ الفَسادِ"" ""اُتُّخِذَتْ جَميعُ الاحْتِياطاتِ لِعَدَمِ انْتِشَارِ عَدْوى الْمَرَضِ الْجَدِيدِ"" : عَدَمِ انْتِقالِها بَيْنَ النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18202, 'اِنْتِشاقٌ', 'انتشاق', 'مصدر', 'نشق', 'انتشاق', 'نتشق', 'مص. اِنْتَشَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِشاقٌ-اِنْتِشاقٌ [ن ش ق] (مص. اِنْتَشَقَ). ""اِنْتِشاقُ الماءِ"" : جَذْبُهُ بالنَّفَسِ في الأنْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18203, 'اِنْتِشالٌ', 'انتشال', 'مصدر', 'نشل', 'انتشال', 'نتشل', 'مص. اِنْتَشَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِشالٌ-اِنْتِشالٌ [ن ش ل] (مص. اِنْتَشَلَ). 1.""اِنْتِشالُ جُثَّةٍ مِنَ البَحْرِ"" : سَحْبُها، إِخْراجُها. 2.""اِنْتِشالُ خَنْجَرٍ"" : سَلُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18204, 'اِنْتِشاءٌ', 'انتشاء', 'مصدر', 'نشو', 'انتشاء', 'نتش', 'مص. اِنْتَشَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِنْتِشاءٌ-اِنْتِشاءٌ [ن ش و] (مص. اِنْتَشَى). 1.""اِنْتِشاءُ الرَّجُلِ"": تَرَنُّحُهُ مِن السُّكْرِ"". 2.""اِنتِشاءُ الرَّائِحَةِ"" : شَمُّها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18205, 'اِنْتِصابٌ', 'انتصاب', 'مصدر', 'نصب', 'انتصاب', 'نتصب', 'مص. اِنْتَصَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِصابٌ-اِنْتِصابٌ [ن ص ب] (مص. اِنْتَصَبَ). 1.""اِنْتِصابُ الخَطيبِ"" : قِيامُهُ. 2.""اِنْتِصابُ تِمْثالٍ"" : اِرْتِفاعُهُ. ""اِنْتِصابُ الرَّاياتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18206, 'اِنْتِصارٌ', 'انتصار', 'مصدر', 'نصر', 'انتصار', 'نتصر', 'مص. اِنْتَصَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِصارٌ-اِنْتِصارٌ [ن ص ر] (مص. اِنْتَصَرَ). ""حَقَّقَ انْتِصاراً ساحِقاً"": حَقَّقَ غَلَبَةً وَفَوْزاً. ""جاءَ انْتِصارُهُ عَن جَدارَةٍ واسْتِحْقاقٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18207, 'اِنْتِصَافٌ', 'انتصاف', 'مصدر', 'نصف', 'انتصاف', 'نتصف', 'مص. اِنْتَصَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِصَافٌ-اِنْتِصَافٌ [ن ص ف] (مص. اِنْتَصَفَ). 1.""اِنْتِصافُ النَّهارِ"" : بُلوغُهُ النِّصْفَ. 2.""الانْتِصافُ مِنَ القاتِلِ"" : أَخْذُ الثَّأْرِ مِنْهُ. 3.""اِنْتِصافُ الْمَظْلومِ"" : طَلَبُهُ الإِنْصافَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18208, 'اِنْتِظارٌ', 'انتظار', 'مصدر', 'نظر', 'انتظار', 'نتظر', 'مص. اِنْتَظَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِظارٌ-اِنْتِظارٌ [ن ظ ر] (مص. اِنْتَظَرَ). 1.""غُرْفَةُ الانْتِظارِ"" : غُرْفَةٌ يَبْقَى فيها الزَّائِرُ إلى أَنْ يَأْتِي دَوْرُهُ. 2.""أَنا في اِنْتِظارِكَ"" : في تَرَقُّبِكَ. ""الانْتِظارُ أَحَرُّ مِنَ النَّارِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18209, 'اِنْتِظامٌ', 'انتظام', 'مصدر', 'نظم', 'انتظام', 'نتظم', 'مص. اِنْتَظَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِنْتِظامٌ-اِنْتِظامٌ [ن ظ م] (مص. اِنْتَظَمَ). 1.""تَعْرِفُ حَرَكاتُ الجَيْشِ انْتِظاماً بَديعاً"" : تَناسُقاً، إِتْقاناً، تَناغُماً. 2.""يُحَضِّرُ دُروسَهُ بانْتِظامٍ"" : باسْتِمْرارٍ، بِمُواظَبَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18210, 'اِنْتِعاشٌ', 'انتعاش', 'مصدر', 'نعش', 'انتعاش', 'نتعش', 'مص. اِنْتَعَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِعاشٌ-اِنْتِعاشٌ [ن ع ش] (مص. اِنْتَعَشَ). 1.""يَعْرِفُ البَلَدُ انْتِعاشاً اقْتِصادِيّاً"" : نَشاطاً وَحَيَوِيَّةً. 2.""اِنْتِعاشُ الذِّكْرَياتِ"" : إِحْياؤُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18211, 'اِنْتِعالٌ', 'انتعال', 'مصدر', 'نعل', 'انتعال', 'نتعل', 'مص. اِنْتَعَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِعالٌ-اِنْتِعالٌ [ن ع ل] (مص. اِنْتَعَلَ). ""اِنْتِعالُ حِذاءٍ"" : لِبْسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18212, 'اِنْتِفاخٌ', 'انتفاخ', 'مصدر', 'نفخ', 'انتفاخ', 'نتفخ', 'مص. اِنْتَفَخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِفاخٌ-اِنْتِفاخٌ [ن ف خ] (مص. اِنْتَفَخَ). ""اِنْتِفاخُ البَطْنِ"" : تَوَرُّمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18213, 'اِنْتِفاشٌ', 'انتفاش', 'مصدر', 'نفش', 'انتفاش', 'نتفش', 'مص. اِنْتَفَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِفاشٌ-اِنْتِفاشٌ [ن ف ش] (مص. اِنْتَفَشَ). ""اِنْتِفَاشُ الطَّائِرِ"": عِنْدَما يَنْفُشُ رِيشَهُ وَيوقِفُهُ لِيَظْهَرَ في أُبَّهَتِهِ وَخُيَلائِهِ. ""إِذا مَشَى فَكَأَنَّهُ الدِّيكُ الرُّومِيُّ في انْتِفاشِهِ"". (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18214, 'اِنْتِفاضٌ', 'انتفاض', 'مصدر', 'نفض', 'انتفاض', 'نتفض', 'مص. اِنْتَفَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِفاضٌ-اِنْتِفاضٌ [ن ف ض] (مص. اِنْتَفَضَ). ""اِنْتِفاضُ ثَوْبٍ"": تَحَريكُهُ وإِزالَةُ ما عَلَيْهِ... 1.""اِنْتِفاضُ الرَّجُلِ"" : تَحَرُّكُهُ بِنَشاطٍ. 2.""اِنْتِفاضُ الرَّجُلِ مِنْ نَوْمِهِ"" : تَيَقُّظُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18215, 'اِنْتِفاضَةٌ', 'انتفاضة', 'مصدر', 'نفض', 'انتفاضة', 'نتفضة', 'مص. اِنْتَفَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِفاضَةٌ-اِنْتِفاضَةٌ [ن ف ض] (مص. اِنْتَفَضَ). ""الانْتِفاضَةُ الفِلِسْطينِيَّةُ"" : أُسْلوبُ نِضالٍ يَعْتَمِدُ تَعْبِئَةَ كُلِّ القِوَى الشَّعْبِيَّةِ لِشَنِّ الْهُجوماتِ وَتَنْظيمِ حَرْب الشَّوارِعِ، وَتَحْضيرِ العِصْيانِ الْمَدَنِيِّ على قاعِدَةِ اللِّجانِ الشَّعْبِيَّةِ ضِدَّ مُؤَسَّساتِ العَدُوِّ. ""اِنْتِفاضَةُ الشَّعْبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18216, 'اِنْتِقاضٌ', 'انتقاض', 'مصدر', 'نقض', 'انتقاض', 'نتقض', 'مص. اِنْتَفَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِقاضٌ-اِنْتِقاضٌ [ن ق ض] (مص. اِنْتَفَضَ). 1.""اِنْتِقاضُ البِناءِ"": تَهَدُّمُهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18217, 'اِنْتِفاعٌ', 'انتفاع', 'مصدر', 'نفع', 'انتفاع', 'نتفع', 'مص. اِنْتَفَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِفاعٌ-اِنْتِفاعٌ [ن ف ع] (مص. اِنْتَفَعَ). ""الانْتِفاعُ مِنَ العَمَلِ"": حُصولُ الْمَنْفَعَةِ مِنْهُ، الاسْتِفادَةُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18218, 'اِنْتِقادٌ', 'انتقاد', 'مصدر', 'نقد', 'انتقاد', 'نتقد', 'مص. اِنْتَقَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِقادٌ-اِنْتِقادٌ [ن ق د] (مص. اِنْتَقَدَ). 1.""تَعَرَّضَ لانْتِقادٍ شَديدٍ"" : عَمَلِيَّةُ إِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18219, 'اِنْتِهازُ', 'انتهاز', 'مصدر', 'نهز', 'انتهاز', 'نتهز', 'مص. اِنْتَهَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِنْتِهازُ-اِنْتِهازُ [ن هـ ز] (مص. اِنْتَهَزَ). 1.""اِنْتِهازُ الفُرْصَةِ"": اِغْتِنامُها. 2.""الانْتِهازُ في الضَّحِكِ"" : الإِفْراطُ فيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18220, 'اِنْتِقاصٌ', 'انتقاص', 'مصدر', 'نقص', 'انتقاص', 'نتقص', 'مص. اِنْتَقَصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِقاصٌ-اِنْتِقاصٌ [ن ق ص] (مص. اِنْتَقَصَ). ""لَمْ يَكُنْ يَقْصِدُ الانْتِقاصَ مِنْ قيمَتِهِ"" : التَّقْليلَ مِنْها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18221, 'اِنْتِقالٌ', 'انتقال', 'مصدر', 'نقل', 'انتقال', 'نتقل', 'مص. اِنْتَقَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِنْتِقالٌ-اِنْتِقالٌ [ن ق ل] (مص. اِنْتَقَلَ). 1.""أَخْبَرَهُ بالانْتِقالِ إلى الصَّفِّ الرَّابِعِ"" : بِالتَّحَوُّلِ إلَى... 2.""أُجْبِرَ على الانْتِقالِ إلى بَيْتٍ آخَرَ"" : التَّحَوُّلُ مِنْ مَكانٍ إلى آخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18222, 'اِنْتِقامٌ', 'انتقام', 'مصدر', 'نقم', 'انتقام', 'نتقم', 'مص. اِنْتَقَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِقامٌ-اِنْتِقامٌ [ن ق م] (مص. اِنْتَقَمَ). ""عَلَيْكَ أَلاَّ تَنْساقَ وَراءَ شُعورِ الانْتِقامِ"" : الأخْذُ بِالثَّأرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18223, 'اِنْتِقاءٌ', 'انتقاء', 'مصدر', 'نقي', 'انتقاء', 'نتق', 'مص. اِنْتَقى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِنْتِقاءٌ-اِنْتِقاءٌ [ن ق ي] (مص. اِنْتَقى). ""تَمَّ انْتِقاءُ الفَريقِ الوَطَنِيِّ"" : اِخْتِيارُهُ على أَساسِ الكَفاءةِ والقُدْرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18224, 'اِنْتِكاسٌ', 'انتكاس', 'مصدر', 'نكس', 'انتكاس', 'نتكس', 'مص. اِنْتَكَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِكاسٌ-اِنْتِكاسٌ [ن ك س] (مص. اِنْتَكَسَ). 1.""عَرَفَ الْمَريضُ انْتِكاساً بَعْدَ شِفاءٍ"" : مُعاوَدَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18225, 'اِنْتِكاسَةٌ', 'انتكاسة', 'مصدر', 'نكس', 'انتكاسة', 'نتكسة', 'مص. اِنْتَكَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِنْتَكَسَ). ""اِنْتِكاسَةُ الْمَريضِ"" : مُعاوَدَتُهُ الْمَرَضَ، أَوْ حالَةٌ مِنْ حالات"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18226, 'اِنْتِكاصٌ', 'انتكاص', 'مصدر', 'نكص', 'انتكاص', 'نتكص', 'مص. اِنْتَكَصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِكاصٌ-اِنْتِكاصٌ [ن ك ص] (مص. اِنْتَكَصَ). "', '');
