INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18228, 'اِنْتِهاجٌ', 'انتهاج', 'مصدر', 'نهج', 'انتهاج', 'نتهج', 'مص. اِنْتَهَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِهاجٌ-اِنْتِهاجٌ [ن هـ ج] (مص. اِنْتَهَجَ). ""اِنْتِهاجُ سُبُلٍ جَديدَةٍ"" : سُلوكُها، نَهْجُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18229, 'اِنْجِذامٌ', 'انجذام', 'مصدر', 'جذم', 'انجذام', 'نجذم', 'مص. اِنْجَذَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْجِذامٌ-اِنْجِذامٌ [ج ذ م] (مص. اِنْجَذَمَ). ""اِنْجِذامُ العُضْوِ"": اِنْقِطاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18230, 'اِنْتِهاسٌ', 'انتهاس', 'مصدر', 'نهس', 'انتهاس', 'نتهس', 'مص. اِنْتَهَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِهاسٌ-اِنْتِهاسٌ [ن هـ س] (مص. اِنْتَهَسَ). 1.""اِنْتِهاسُ اللَّحْمِ"" : أَخْذُهُ ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18231, 'اِنْتِهاكٌ', 'انتهاك', 'مصدر', 'نهك', 'انتهاك', 'نتهك', 'مص. اِنْتَهَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِنْتَهَكَ). ""اِنْتِهاكُ الْمُقَدَّساتِ"" : التَّعَدِّي عَلَيْها وَ"', '');
