INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18236, 'إِنْجاحٌ', 'إنجاح', 'مصدر', 'نجح', 'ءنجاح', 'إنجح', 'مص. أَنْجَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْجاحٌ-إِنْجاحٌ [ن ج ح] (مص. أَنْجَحَ). 1. ""إِنْجاحُ الرَّجُلِ"": صَيْرُهُ ذَا نَجَاحٍ. 2.""إِنْجَاحُ الحَاجَةِ"" : جَعْلُهَا مَقْضِيَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18237, 'إِنْجادٌ', 'إنجاد', 'مصدر', 'نجد', 'ءنجاد', 'إنجد', 'مص. أَنْجَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْجادٌ-إِنْجادٌ [ن ج د] (مص. أَنْجَدَ). ""جاءَ لإِنْجادِهِ وَهُوَ يُصارِعُ الأمْواجَ"" : لِمُساعَدَتِهِ وَإِعانَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18238, 'اِنْجِذابٌ', 'انجذاب', 'مصدر', 'جذب', 'انجذاب', 'نجذب', 'مص. اِنْجَذَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْجِذابٌ-اِنْجِذابٌ [ج ذ ب] (مص. اِنْجَذَبَ). 1.""الانْجِذابُ في السَّيْرِ"" : الإ"', '');
