INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18240, 'اِنْجِرارٌ', 'انجرار', 'مصدر', 'جرر', 'انجرار', 'نجرر', 'مص. اِنْجَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْجِرارٌ-اِنْجِرارٌ [ج ر ر] (مص. اِنْجَرَّ). 1.""اِنْجِرَارُ التّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18241, 'اِنْجِرافٌ', 'انجراف', 'مصدر', 'جرف', 'انجراف', 'نجرف', 'مص. اِنْجَرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْجِرافٌ-اِنْجِرافٌ [ج ر ف] (مص. اِنْجَرَفَ). ""الانْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18242, 'إِنْجازٌ', 'إنجاز', 'مصدر', 'نجز', 'ءنجاز', 'إنجز', 'مص. أَنْجَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَنْجَزَ). ""قامَ بِإِنْجازِ مَهامِّهِ"" : إِتْمامِها، إِكْمالِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18243, 'اِنْجِلاءٌ', 'انجلاء', 'مصدر', 'جلي', 'انجلاء', 'نجل', 'مص. اِنْجَلَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِنْجِلاءٌ-اِنْجِلاءٌ [ج ل ي] (مص. اِنْجَلَى). 1.""اِنْجِلاءُ الضَّوْءِ"": اِنْكِشافُهُ، ظُهُورُهُ. ""اِنْجِلاءُ الحَقيقَةِ"". 2.""اِنْجِلاءُ الهَمِّ عن نَفْسِهِ"" : تَبَدُّدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18244, 'اِنْحِيازٌ', 'انحياز', 'مصدر', 'حوز', 'انحياز', 'نحز', 'مص. اِنْحازَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْحِيازٌ-اِنْحِيازٌ [ح و ز] (مص. اِنْحازَ). 1.""أَحْكامُهُ لا تَعْرِفُ انْحِيازاً لأَحَدٍ"" : مُحاباةً. 2.""الدُّوَلُ العَرَبِيَّةُ مِنْ بُلْدانِ عَدَمِ الانْحِيازِ"": الْمُحايَدَةُ، غَيْرُ مُنْحازَةٍ لأَيِّ مُعَسْكَرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18245, 'اِنْحِباسٌ', 'انحباس', 'مصدر', 'حبس', 'انحباس', 'نحبس', 'مص. اِنْحَبَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْحِباسٌ-اِنْحِباسٌ [ح ب س] (مص. اِنْحَبَسَ). ""اِنْحِبَاسُ الْمَطَرِ"": اِنْقِطَاعُهُ. ¨ ""وَما رَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18246, 'اِنْحِتاتٌ', 'انحتات', 'مصدر', 'نحت', 'انحتات', 'نحتت', 'مص. اِنْحَتَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْحِتاتٌ-اِنْحِتاتٌ [ن ح ت] (مص. اِنْحَتَّ). 1.""اِنْحِتاتُ الشَّعْرِ"": تَساقُطُهُ. 2.""اِنْحِتاتُ وَرَقِ الشَّجَرِ"" : سُقوطُهُ مُتَناثِراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18247, 'اِنْحِدارٌ', 'انحدار', 'مصدر', 'حدر', 'انحدار', 'نحدر', 'مص. اِنْحَدَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْحِدارٌ-اِنْحِدارٌ [ح د ر] (مص. اِنْحَدَرَ). 1.""الانْحِدارُ مِنْ أَعْلَى الجَبَلِ"" : التَّدَحْرُجُ. 2.""اِنْحِدارُ الدَّمْعِ"" : سَيَلانُهُ، اِنْسِكابُهُ، سُقوطُهُ، جَرَيانُهُ. 3.""اِنْحِدارُهُ مِنْ أُسْرَةٍ شَريفَةٍ"": اِنْتِسابُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18248, 'اِنْحِرافٌ', 'انحراف', 'مصدر', 'حرف', 'انحراف', 'نحرف', 'مص. اِنْحَرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْحِرافٌ-اِنْحِرافٌ [ح ر ف] (مص. اِنْحَرَفَ). 1.""اِنْحِرافٌ عَنِ الطَّريقِ الْمُسْتَقيمِ"" : الخُروجُ عَنْ جادًّةِ الصَّوابِ، الابْتِعادُ عَنْها، وَالانْحِرافُ مُصْطَلَحٌ في عِلْمِ النَّفْسِ الاجْتِماعِيِّ يَعْنِي الخُروجُ عَنْ ما هُوَ مأْلوفٌ وَمُتَعارَفٌ عَلَيْهِ مِنْ عادَاتٍ وَسُلوكٍ. 2.""اِنْحِرافُ الطَّائِرَةِ أَوِ السَّفينَةِ"" : حَيَدانُها. 3.""الانْحِرافُ"" (جغ) : الْمَيْلُ عَنْ خَطِّ الاسْتِواءِ. ""يَنْطَلِقُ دَفْعَةً واحِدَةً حَتَّى لا يَمْتَدَّ في طولٍ وَلا عَرْضٍ وَلا مَكانٍ للانْحِرافِ"". (م.ع. العقاد)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18249, 'اِنْخِرَاقٌ', 'انخراق', 'مصدر', 'خرق', 'انخراق', 'نخرق', 'مص. اِنْخَرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْخِرَاقٌ-اِنْخِرَاقٌ [خ ر ق] (مص. اِنْخَرَقَ). 1.""اِنْخِراقُ الحائِطِ"" : اِنْشِقا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18250, 'اِنْحِسامٌ', 'انحسام', 'مصدر', 'حسم', 'انحسام', 'نحسم', 'مص. اِنْحَسَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْحِسامٌ-اِنْحِسامٌ [ح س م] (مص. اِنْحَسَمَ). ""اِنْحِسامُ الأمْرِ"": اِنْتِهاؤُهُ، إِيجادُ حَلٍّ لَهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18251, 'اِنْحِصارٌ', 'انحصار', 'مصدر', 'حصر', 'انحصار', 'نحصر', 'مص. اِنْحَصَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْحِصارٌ-اِنْحِصارٌ [ح ص ر] (مص. اِنْحَصَرَ). ""اِنْحِصارُ القُوَّاتِ"" : اِنْحِباسُها في مَكانٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18252, 'اِنْحِطاطٌ', 'انحطاط', 'مصدر', 'حطط', 'انحطاط', 'نحطط', 'مص. اِنْحَطَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْحِطاطٌ-اِنْحِطاطٌ [ح ط ط] (مص. اِنْحَطَّ). 1.""يَجِبُ العَمَلُ على وَقْفِ انْحِطاطِ الأخْلاقِ"" : على وَقْفِ تَدَهْوُرِها، فَسادِها. 2.""عَصْرُ الانْحِطاطِ"" : عَصْرُ التَّقَهْقُرِ، التَّدَهْوُرِ والرُّكودِ وَهُبوطِ الحَماسِ والنَّشاطِ صِناعِيّاً واجِتِماعِيّاً وَفَنِّياً وَأَدَبِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18253, 'اِنْحِطامٌ', 'انحطام', 'مصدر', 'حطم', 'انحطام', 'نحطم', 'مص. اِنْحَطَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْحِطامٌ-اِنْحِطامٌ [ح ط م] (مص. اِنْحَطَمَ). 1.""اِنْحِطامُ الكَأْسِ"": اِنْكِسارُهُ. 2.""اِنْحِطامُ النَّاسِ على الجزَّارِ"" : تَزَاحُمُهُمْ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18254, 'اِنْحِلالٌ', 'انحلال', 'مصدر', 'حلل', 'انحلال', 'نحلل', 'مص. اِنْحَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِنْحِلالٌ-اِنْحِلالٌ [ح ل ل] (مص. اِنْحَلَّ). 1. ""اِنْحِلالُ الخُيوطِ"" : اِنْفِكاكُها. 2.""اِنْحِلالُ الأَخْلاقِ"" : فَسادُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18255, 'اِنْحِلابٌ', 'انحلاب', 'مصدر', 'حلب', 'انحلاب', 'نحلب', 'مص. اِنْحَلَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْحِلابٌ-اِنْحِلابٌ [ح ل ب] (مص. اِنْحَلَبَ). 1.""اِنْحِلابُ الدَّمْعِ"" : سَيَلانُهُ. ""اِنْحِلابُ العَيْنِ"". 2.""اِنْحِلابُ الفَمِ"" : سَيَلانُ ريقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18256, 'اِنْحِناءٌ', 'انحناء', 'مصدر', 'حنو', 'انحناء', 'نحن', 'مص. اِنْحَنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِنْحِناءٌ-اِنْحِناءٌ [ح ن و] (مص. اِنْحَنَى). 1.""اِنْحِنَاءُ شَجَرَةٍ"": مَيْلُهَا، اِعْوِجَاجُهَا. 2.""اِنْحِناءُ الرَّأْسِ"" : طَأْطَأَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18257, 'اِنْخِدَاعٌ', 'انخداع', 'مصدر', 'خدع', 'انخداع', 'نخدع', 'مص. اِنْخَدَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْخِدَاعٌ-اِنْخِدَاعٌ [خ د ع] (مص. اِنْخَدَعَ). ""اِنْخِداعُ الرَّجُلِ"": "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18258, 'اِنْخِراطٌ', 'انخراط', 'مصدر', 'خرط', 'انخراط', 'نخرط', 'مص. اِنْخَرَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْخِراطٌ-اِنْخِراطٌ [خ ر ط] (مص. اِنْخَرَطَ). 1.""طَلَبَ الانْخِراطَ في الحِزْبِ"" : الانْضِمامَ إِلَيْهِ، الالْتِحاقَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18259, 'اِنْدِراجٌ', 'اندراج', 'مصدر', 'درج', 'اندراج', 'ندرج', 'مص. اِنْدَرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْدِراجٌ-اِنْدِراجٌ [د ر ج] (مص. اِنْدَرَجَ). ""اِنْدِراجُهُ وَسَطَ الجَماعَةِ"" : دُخولُهُ وَسَطَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18260, 'اِنْخِرامٌ', 'انخرام', 'مصدر', 'خرم', 'انخرام', 'نخرم', 'مص. اِنْخَرَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْخِرامٌ-اِنْخِرامٌ [خ ر م] (مص. اِنْخَرَمَ). 1.""اِنْخِرامُ الأيَّامِ وَالشُّهورِ"" : اِنْصِرامُها، اِنْقِضَاؤُها. 2.""اِنْخِرَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18261, 'اِنْخِسافٌ', 'انخساف', 'مصدر', 'خسف', 'انخساف', 'نخسف', 'مص. اِنْخَسَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْخِسافٌ-اِنْخِسافٌ [خ س ف] (مص. اِنْخَسَفَ). ""اِنْخِسَافُ الأَرْضِ"" : خُسوفُها، غَوْرُها بِما عَلَيْها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18262, 'اِنْخِفاضٌ', 'انخفاض', 'مصدر', 'خفض', 'انخفاض', 'نخفض', 'مص. اِنْخَفَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْخِفاضٌ-اِنْخِفاضٌ [خ ف ض] (مص. اِنْخَفَضَ). 1.""اِنْخِفاضُ الصَّوْتِ"" : ضَعْفُهُ، خُفوتُهُ. 2.""اِنْخِفاضُ الرَّأْسِ"" : اِنْحِناؤُهُ. 3.""اِنْخِفاضُ الأَسْعارِ"" : نَقْصُ ثَمَنِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18263, 'اِنْخِلاعٌ', 'انخلاع', 'مصدر', 'خلع', 'انخلاع', 'نخلع', 'مص. اِنْخَلَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْخِلاعٌ-اِنْخِلاعٌ [خ ل ع] (مص. اِنْخَلَعَ). ""اِنْخِلاعُ البابِ"": زوالُهُ عَنْ مَوْضِعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18264, 'اِنْخِناقٌ', 'انخناق', 'مصدر', 'خنق', 'انخناق', 'نخنق', 'مص. اِنْخَنَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْخِناقٌ-اِنْخِناقٌ [خ ن ق] (مص. اِنْخَنَقَ). ""اِنْخِناقُ الوَلَدِ"": اِخْتِناقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18265, 'إِنْدابٌ', 'إنداب', 'مصدر', 'ندب', 'ءنداب', 'إندب', 'مص. أَنْدَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْدابٌ-إِنْدابٌ [ن د ب] (مص. أَنْدَبَ). 1.""إِنْدابُ الجُرْحِ"": بَقاءُ أَثَرِهِ. 2.""كانَ على أُهْبَةِ إِنْدابِ نَفْسِهِ"" : الْمُخاطَرَةِ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18266, 'اِنْدِباغٌ', 'اندباغ', 'مصدر', 'دبغ', 'اندباغ', 'ندبغ', 'مص. اِنْدَبَغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْدِباغٌ-اِنْدِباغٌ [د ب غ] (مص. اِنْدَبَغَ). ""اِنْدِباغُ الجِلْدِ"" : لَيْنُهُ وَزَوالُ الرّوائِحِ الكَريهَةِ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18267, 'اِنْدِثارٌ', 'اندثار', 'مصدر', 'دثر', 'اندثار', 'ندثر', 'مص. اِنْدَثَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْدِثارٌ-اِنْدِثارٌ [د ث ر] (مص. اِنْدَثَرَ). 1.""عَرَفَتْ بُيوتُ القَرْيَةِ انْدِثارًا"" : اِخْتِفاءً، لَمْ يَبْقَ لَها أَثَرٌ. 2.""أَحْدَثَ الزِّلْزالُ انْدِثاراً مُفْجِعاً لِكُلِّ مَبانِي الْمَدينَةِ"" : تَدْميراً، تَلاشِياً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18268, 'اِنْدِحارٌ', 'اندحار', 'مصدر', 'دحر', 'اندحار', 'ندحر', 'مص. اِنْدَحَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْدِحارٌ-اِنْدِحارٌ [د ح ر] (مص. اِنْدَحَرَ). ""اِنْدِحارُ الجَيْشِ"": اِنْهِزامُهُ، اِنْكِسارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18269, 'اِنْدِمالٌ', 'اندمال', 'مصدر', 'دمل', 'اندمال', 'ندمل', 'مص. اِنْدَمَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْدِمالٌ-اِنْدِمالٌ [د م ل] (مص. اِنْدَمَلَ). ""اِنْدِمالُ جُرْحٍ"": اِلْتِحامُهُ عَلامَةً على بُرْئِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18270, 'اِنْدِراسٌ', 'اندراس', 'مصدر', 'درس', 'اندراس', 'ندرس', 'مص. اِنْدَرَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْدِراسٌ-اِنْدِراسٌ [د ر س] (مص. اِنْدَرَسَ). 1.""اِنْدِراسُ الأَثَرِ"": اِنْمِحاءُ بَقاياهُ. 2.""اِنْدِراسُ آخِرِ أَخْبارِهِ"" : اِنْطِماسُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18271, 'اِنْدِساسٌ', 'اندساس', 'مصدر', 'دسس', 'اندساس', 'ندسس', 'مص. اِنْدَسَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْدِساسٌ-اِنْدِساسٌ [د س س] (مص. اِنْدَسَّ). 1.""الانْدِساسُ في الزِّحامِ"" : الدُّخولُ فيهِ. 2.""الانْدِساسُ في التِّبْنِ"" : الانْدِفانُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18272, 'اِنْدِفاعٌ', 'اندفاع', 'مصدر', 'دفع', 'اندفاع', 'ندفع', 'مص. اِنْدَفَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْدِفاعٌ-اِنْدِفاعٌ [د ف ع] (مص. اِنْدَفَعَ). 1.""اِنْدَفَعَ انْدِفاعاً"": طَوْعاً مِنْ تِلْقاءِ النَّفْسِ. 2.""كانَ انْدِفاعُهُ شَديداً"" : حَمِيَّتُهُ، هِمَّتُهُ. 3.""لَمْ يَتَمالَكْ نَفْسَهُ لَحْظَةَ الانْدِفاعِ"" : الارْتِماءِ تِلْقائِيّاً. 4.""اِنْساقَ وَراءَ انْدِفاعِ عَواطِفِهِ"" : تَحْريضِ، تَحْريكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18273, 'اِنْدِفاقٌ', 'اندفاق', 'مصدر', 'دفق', 'اندفاق', 'ندفق', 'مص. اِنْدَفَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْدِفاقٌ-اِنْدِفاقٌ [د ف ق] (مص. اِنْدَفَقَ). ""اِنْدِفاقُ الماءِ"": اِنْصِبابُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18274, 'اِنْدِفانٌ', 'اندفان', 'مصدر', 'دفن', 'اندفان', 'ندفن', 'مص. اِنْدَفَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْدِفانٌ-اِنْدِفانٌ [د ف ن] (مص. اِنْدَفَنَ). 1.""اِنْدِفانُ الحَوْضِ"": اِمْتِلاؤُهُ بِالتُّرابِ. 2.""اِنْدِفانُ الْمَيِّتِ"" : تَواريهِ تَحْتَ الـتُّرابِ. 3.""اِنْدِفانُ الكَنْزِ"" : اِخْتِفاؤُهُ تَحْتَ التُّرابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18275, 'اِنْدِقاقٌ', 'اندقاق', 'مصدر', 'دقق', 'اندقاق', 'ندقق', 'مص. اِنْدَقَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْدِقاقٌ-اِنْدِقاقٌ [د ق ق] (مص. اِنْدَقَّ). ""اِنْدِقاقُ العَظْمِ"" : اِنْكِسارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18276, 'اِنْدِلاعٌ', 'اندلاع', 'مصدر', 'دلع', 'اندلاع', 'ندلع', 'مص. اِنْدَلَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْدِلاعٌ-اِنْدِلاعٌ [د ل ع] (مص. اِنْدَلَعَ). 1.""اِنْدِلاعُ اللِّسانِ"": خُروجُهُ مِنَ الفَمِ وَاسْتِرْخاؤُهُ. 2.""اِنْدِلاعُ النِّيرانِ"" : اِشْتِعالُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18277, 'اِنْدِلاقٌ', 'اندلاق', 'مصدر', 'دلق', 'اندلاق', 'ندلق', 'مص. اِنْدَلَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْدِلاقٌ-اِنْدِلاقٌ [د ل ق] (مص. اِنْدَلَقَ). 1.""اِنْدِلاقُ السَّيْلِ"": اِنْدِفاعُهُ. 2.""اِنْدِلاقُ البَطْنِ"" : اِسْتِرْخاؤُهُ. 3.""اِنْدِلاقُ الخَيْلِ"": اِنْطِلاقُها بِشِدَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18278, 'اِنْدِماجٌ', 'اندماج', 'مصدر', 'دمج', 'اندماج', 'ندمج', 'مص. اِنْدَمَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْدِماجٌ-اِنْدِماجٌ [د م ج] (مص. اِنْدَمَجَ). 1.""اِنْدِماجُ مَدْرَسَةٍ في أُخْرى"" : إِلْحاقُها لِتُصْبِحَ مَدْرَسَةً واحِدَةً. ""اِنْدِماجُ الْمَدْرَسَتَيْنِ"". 2.""اِنْدِماجُ البَلَدَيْنِ"" : اِتِّحادُهُما في دَوْلَةٍ واحِدَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18279, 'إِينَاسٌ', 'إيناس', 'مصدر', 'أنس', 'ءيناس', 'إنس', 'مص. آنَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِينَاسٌ-إِينَاسٌ [أ ن س] (مص. آنَسَ). 1.""وَجَدَ عِنْدَهُ إِينَاساً"": أَيْ لُطْفاً وَكُلَّ مَا يُذِهِبُ الوَحْشَةَ. 2.""إينَاسُ الأمْرِ"" : عِلْمُهُ، التَّيَقُّنُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18280, 'إِنْذارٌ', 'إنذار', 'مصدر', 'نذر', 'ءنذار', 'إنذر', 'مص. أَنْذَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْذارٌ-إِنْذارٌ [ن ذ ر] (مص. أَنْذَرَ). 1.""تَوَصَّلَ بِإِنْذارٍ مِنْ إِدارَةِ الْمَدْرَسَةِ"" : بِإِشْعارٍ بِهِ تَنْبيهٌ على عَمَلٍ خَطيرٍ قامَ بِهِ. 2.""جَرَسُ الإنْذارِ"" : الإخْطار، الإِشْعارُ بِوُقوعِ أَمْرٍ مَّا لأخْذِ الحيطَةِ والحَذَرِ. 3.""أَلَمْ تَسْمَعْ صَفَّارَةَ الإِنْذارِ"" : صَفَّارَةً لَها صَوْتٌ ضَخْمٌ تُشْعِرُكَ بِحُدوثِ شَيْءٍ خَطيرٍ، أَوْحُلولِ مُناسَبَةٍ مَّا. 4.""وَجَّهَ لَهُ إِنْذاراً أَخِيراً"" : إِشْعاراً. ""أَخْرَجَهُ دُونَ سابِقِ إِنْذارٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18281, 'اِنْزِياحٌ', 'انزياح', 'مصدر', 'نزح', 'انزياح', 'نزح', 'مص. اِنْزاحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْزِياحٌ-اِنْزِياحٌ [ن ز ح] (مص. اِنْزاحَ). 1.""اِنْزِياحُهُ عَنِ الطِّريقِ"" : اِبْتِعادُهُ وَمَيْلُهُ عَنْهُ. 2.""الانْزِياحُ عَنِ الْمَعْنى الحَقيقِيِّ لِلْكَلِمَةِ"" : الابْتِعادُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18282, 'اِنْزِجارٌ', 'انزجار', 'مصدر', 'زجر', 'انزجار', 'نزجر', 'مص. اِنْزَجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْزِجارٌ-اِنْزِجارٌ [ز ج ر] (مص. اِنْزَجَرَ). 1.""اِنْزِجارُ الخائِفِ"": اِنْقِيادُهُ. 2.""الانْزِجارُ عَنْ فِعْلِ الْمَعَاصِي"" : الامْتِناعُ عَنْها..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18283, 'اِنْزِعاجٌ', 'انزعاج', 'مصدر', 'زعج', 'انزعاج', 'نزعج', 'مص. اِنْزَعَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْزِعاجٌ-اِنْزِعاجٌ [ز ع ج] (مص. اِنْزَعَجَ). 1.""كانَ في حالَةِ انْزِعاجٍ"": في وَضْعٍ قَلِقٍ. 2.""سَبَّبَ لَهُ الْمَرَضُ انْزِعاجاً كَبيراً"": تَضايُقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18284, 'اِنْزِعَاقٌ', 'انزعاق', 'مصدر', 'زعق', 'انزعاق', 'نزعق', 'مص. اِنْزَعَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْزِعَاقٌ-اِنْزِعَاقٌ [ز ع ق] (مص. اِنْزَعَقَ). 1.""اِنْزِعَاقُ الوَلَدِ"": خَوْفُهُ. 2.""اِنْزِعَاقُ الدَّابَّةِ"": إِسْرَاعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18285, 'إِنْزافٌ', 'إنزاف', 'مصدر', 'نزف', 'ءنزاف', 'إنزف', 'مص. أَنْزَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْزافٌ-إِنْزافٌ [ن ز ف] (مص. أَنْزَفَ). ""إِنْزافُ البِئْرِ"" : إِخْراجُ مائِها كُلِّهِ. ""إِنْزافُ الدَّمْعِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18286, 'إِنْزالٌ', 'إنزال', 'مصدر', 'نزل', 'ءنزال', 'إنزل', 'مص. أَنْزَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْزالٌ-إِنْزالٌ [ن ز ل] (مص. أَنْزَلَ). 1.""تَعَذَّرَ إِنْزالُ السَّفينَةِ إلى البَحْرِ بِسَبَبِ ارْتِفاعِ الأمْواجِ"" : الدَّفْعُ بِها، تَعْوِيمُها. 2.""مِنَ الْمُفيدِ إِنْزالُ الفَريقِ الرِّياضِيِّ بِكامِلِ طاقَمِهِ"" : دُخولُ جِميعِ أَعْضائِهِ إلى الْمَلْعَبِ. 3.""تَقَرَّرَ إِنْزالُ سِعْرِ الْمَوادِّ الغِذَائِيَّةِ"" : تَخْفِيضُها. 4.""إِنْزالُ الْمَنِيِّ"" : إِخْراجُهُ بِجِماعٍ أَوْ غَيْرِهِ. 5.""إِنْزالٌ اِنْتِخابِيٌّ"" : إِغْراقُ عَمَلِيَّةِ الاِقْتِراعِ بِأَصْواتِ ناخِبِينَ غَيْرِ مُسَجَّلينَ في اللَّوائِحِ الانْتِخابِيَّةِ الرَّسْمِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18287, 'اِنْزِلاقٌ', 'انزلاق', 'مصدر', 'زلق', 'انزلاق', 'نزلق', 'مص. اِنْزَلَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْزِلاقٌ-اِنْزِلاقٌ [ز ل ق] (مص. اِنْزَلَقَ). 1.""يَنْبَغي الحَذَرُ مِنَ الانْزِلاقِ"" : الانْزِياحِ، التَّزَحْلُقِ. 2.""أَدَّى الازْدِحامُ إلى انْزِلاقِ بابِ قاعَةِ الْمَعْرِضِ"" : تَداعِيهِ، اِنْجِرارِهِ، سُقوطِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18288, 'اِنْزِواءٌ', 'انزواء', 'مصدر', 'زوي', 'انزواء', 'نز', 'مص. اِنْزَوَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِنْزِواءٌ-اِنْزِواءٌ [ز و ي] (مص. اِنْزَوَى). 1.""اِنْزَوَاءُ الرَّجُلِ في الغُرْفَةِ"" : جُلوسُهُ في زاوِيَتِها. 2.""اِنْزِواءُ الرَّجُلِ عَنِ الجَماعَةِ"" ‏: اِعْتِزالُهُ، اِنْقِباضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18289, 'اِنْسِدالٌ', 'انسدال', 'مصدر', 'سدل', 'انسدال', 'نسدل', 'مص. اِنْسَدَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِدالٌ-اِنْسِدالٌ [س د ل] (مص. اِنْسَدَلَ). 1.""اِنْسِدالُ سَتائِرِ النَّوافِذِ"" : إِنْزالُها. 2.""اِنْسِدالُ الشَّعْرِ"" : إِرْسالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18290, 'اِنْسِيابٌ', 'انسياب', 'مصدر', 'سيب', 'انسياب', 'نسب', 'مص. اِنْسابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِيابٌ-اِنْسِيابٌ [س ي ب] (مص. اِنْسابَ). 1.""اِنْسِيابٌ في الْمَشْيِ"": الْمَشْيُ بِسُرْعَةٍ. 2.""يُلاحِظُ اِنْسِيابَ الحَيَّةِ في"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18291, 'اِنْسِياقٌ', 'انسياق', 'مصدر', 'سوق', 'انسياق', 'نسق', 'مص. اِنْساقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِياقٌ-اِنْسِياقٌ [س و ق] (مص. اِنْساقَ). 1.""اِنْسِياقُ الماشِيَةِ في الْمَرْعَى"": سَيْرُها بِالتَّتابُعِ. 2.""لاَحَظَ انْسِياقَهُ مَعَ الأهْواءِ"": سَيْرُهُ دونَ تَفْكيرٍ وَلا رَوِيَّةٍ. ""أَجاءَ ذَلِكَ عَنْ قَصْدٍ وَتَدَبُّرٍ أَمْ جاءَ عَن صِدْفَةٍ وَانْسِياقٍ طَبيعِيٍّ"". (إسحق الحسيني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18292, 'أُنْسٌ', 'أنس', 'مصدر', 'أنس', 'ءنس', 'نس', 'مص. أَنَسَ، أَنِسَ، أَنُسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أُنْسٌ-أُنْسٌ [أ ن س] (مص. أَنَسَ، أَنِسَ، أَنُسَ). 1.""يَشْعُرُ بِأُنْسٍ بَيْنَ أَهْلِهِ"" : بِأُلْفَةٍ، أَيْ لاَ يَشْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18293, 'اِنْسِباكٌ', 'انسباك', 'مصدر', 'سبك', 'انسباك', 'نسبك', 'مص. اِنْسَبَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِباكٌ-اِنْسِباكٌ [س ب ك] (مص. اِنْسَبَكَ). ""اِنْسِباكُ الْمَعْدِنِ"" : تَذْويبُهُ وإِفْراغُهُ قي قَالَبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18294, 'اِنْسِتارٌ', 'انستار', 'مصدر', 'ستر', 'انستار', 'نستر', 'مص. اِنْسَتَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِتارٌ-اِنْسِتارٌ [س ت ر] (مص. اِنْسَتَرَ). ""اِنْسِتارُ الرَّجُلِ"" : تَغْطِيَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18295, 'اِنْسِجامٌ', 'انسجام', 'مصدر', 'سجم', 'انسجام', 'نسجم', 'مص. اِنْسَجَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِجامٌ-اِنْسِجامٌ [س ج م] (مص. اِنْسَجَمَ). 1.""تَمْتازُ كِتاباتُهُ بِانْسِجامِ الأفْكارِ"" : أَيْ لاَ تَناقُضَ بَيْنَ أَفْكَارِها. 2.""اِنْسِجامُ الت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18296, 'اِنْسِحابٌ', 'انسحاب', 'مصدر', 'سحب', 'انسحاب', 'نسحب', 'مص. اِنْسَحَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِحابٌ-اِنْسِحابٌ [س ح ب] (مص. اِنْسَحَبَ). ""كانَ انْسِحابُهُ مِنَ الحَفْلَةِ في غَيْرِ مَحَلِّهِ"" : اِن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18297, 'اِنْسِحاقٌ', 'انسحاق', 'مصدر', 'سحق', 'انسحاق', 'نسحق', 'مص. اِنْسَحَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِحاقٌ-اِنْسِحاقٌ [س ح ق] (مص. اِنْسَحَقَ). 1.""اِنْسِحاقُ القَلْبِ"" : اِنْكِسارُهُ غَم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18298, 'اِنْسِدَادٌ', 'انسداد', 'مصدر', 'سدد', 'انسداد', 'نسدد', 'مص. اِنْسَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِدَادٌ-اِنْسِدَادٌ [س د د] (مص. اِنْسَدَّ). 1.""اِنْسِدادُ الأَبْوابِ في وَجْهِهِ"" : اِنْغِلاقُها. 2.""اِنْسِدادُ الح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18299, 'اِنْسِراقٌ', 'انسراق', 'مصدر', 'سرق', 'انسراق', 'نسرق', 'مص. اِنْسَرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِراقُ-اِنْسِراقُ [س ر ق] (مص. اِنْسَرَقَ). ""اِنْسِراقُ الصَّوْتِ"": ضَعْفُهُ، اِنْخِفاضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18300, 'اِنْسِطاحٌ', 'انسطاح', 'مصدر', 'سطح', 'انسطاح', 'نسطح', 'مص. اِنْسَطَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِطاحٌ-اِنْسِطاحٌ [س ط ح] (مص. اِنْسَطَحَ). 1.""اِنْسِطاحُ السَّهْلِ"" : اِنْب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18301, 'إِنْسافٌ', 'إنساف', 'مصدر', 'نسف', 'ءنساف', 'إنسف', 'مص. أَنْسَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْسافٌ-إِنْسافٌ [ن س ف] (مص. أَنْسَفَ). ""إِنْسافُ الرِّيحِ"": اِشْتِدادُ هُبوبِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18302, 'اِنْسِفاكٌ', 'انسفاك', 'مصدر', 'سفك', 'انسفاك', 'نسفك', 'مص. اِنْسَفَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِفاكٌ-اِنْسِفاكٌ [س ف ك] (مص. اِنْسَفَكَ). ""اِنْسِفاكُ الدَّمِ"": اِنْصِبابُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18303, 'اِنْسِكابٌ', 'انسكاب', 'مصدر', 'سكب', 'انسكاب', 'نسكب', 'مص. اِنْسَكَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِكابٌ-اِنْسِكابٌ [س ك ب] (مص. اِنْسَكَبَ)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18304, 'اِنْسِلالٌ', 'انسلال', 'مصدر', 'سلل', 'انسلال', 'نسلل', 'مص. اِنْسَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِلالٌ-اِنْسِلالٌ [س ل ل] (مص. اِنْسَلَّ). 1.""الانْسِلالُ مِنَ البَيْتِ"" : الخُروجُ مِنْهُ خُفْيَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18305, 'اِنْسِلاخٌ', 'انسلاخ', 'مصدر', 'سلخ', 'انسلاخ', 'نسلخ', 'مص. اِنْسَلَخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْسِلاخٌ-اِنْسِلاخٌ [س ل خ] (مص. اِنْسَلَخَ). 1.""اِنْسِلاخُ جِلْدِ الأفْعَى"" : تَغَيُّرُ جِلْدِها، اِنْكِشاطُها. 2.""اِنْسِلاخُ الأيَّامِ"" : اِنْصِرافُها، مُرورُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18306, 'إِنْشاءٌ', 'إنشاء', 'مصدر', 'نشأ', 'ءنشاء', 'إنش', 'مص. أَنْشَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"(مص. أَنْشَأَ). 1.""إِنْشاءٌ أَدَبِيٌّ"" : تَأْليفُ تَعابِيرَ لُغَوِيَّةٍ تُعَبِّرُ عَنْ شُعورِ كاتِبِها. 2.""إِنْشاءُ الْمَبانِي"" : تَشْيِيدُها. 3.""أَشْرَفَ على الإِنْشاءاتِ الجَديدَةِ بِالْمَدينَةِ"" : تَجْهيزاتٍ وَمُؤَسَّساتٍ وَمُنْشَآتٍ ثَقافِيَّةٍ اقْتِصادِيَّةٍ وَاجْتِماعِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18307, 'إِنْشادٌ', 'إنشاد', 'مصدر', 'نشد', 'ءنشاد', 'إنشد', 'مص. أَنْشَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْشادٌ-إِنْشادٌ [ن ش د] (مص. أَنْشَدَ). ""إِنْشادُ الشِّعْرِ"": قِراءَتُهُ بِصَوْتٍ مُرْتَفِعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18308, 'اِنْشِراحٌ', 'انشراح', 'مصدر', 'شرح', 'انشراح', 'نشرح', 'مص. اِنْشَرَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْشِراحٌ-اِنْشِراحٌ [ش ر ح] (مص. اِنْشَرَحَ). ""عَرَفَ انْشِراحاً في حَفْلَةِ الأمْسِ"" : سُروراً وَغِبْطَةً. ""لَمْ يَعْرِفْ كَيْفَ يُعَبِّرُ عَنِ انْشِراحِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18309, 'إِنْشاطٌ', 'إنشاط', 'مصدر', 'نشط', 'ءنشاط', 'إنشط', 'مص. أَنْشَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْشاطٌ-إِنْشاطٌ [ن ش ط] (مص. أَنْشَطَ). ""إِنْشاطُ الوَلَدِ"": جَعْلُهُ نَشيطاً..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18310, 'اِنْشِعابٌ', 'انشعاب', 'مصدر', 'شعب', 'انشعاب', 'نشعب', 'مص. اِنْشَعَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْشِعابٌ-اِنْشِعابٌ [ش ع ب] (مص. اِنْشَعَبَ). ""اِنْشِعابُ طَريقٍ"" : اِفْتراقُ شُعَبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18311, 'اِنْشِغافٌ', 'انشغاف', 'مصدر', 'شغف', 'انشغاف', 'نشغف', 'مص. اِنْشَغَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْشِغافٌ-اِنْشِغافٌ [ش غ ف] (مص. اِنْشَغَفَ). ""اِنْشِغافُ الْمُحِبِّ"" : شِدَّةُ وَلَعِهِ وَحُبُّهُ الشَّديدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18312, 'اِنْشِغالٌ', 'انشغال', 'مصدر', 'شغل', 'انشغال', 'نشغل', 'مص. اِنْشَغَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْشِغالٌ-اِنْشِغالٌ [ش غ ل] (مص. اِنْشَغَلَ). ""اِنْشِغالُ البالِ"": اِضْطِرابُ البالِ قَلَقاً وَهَمّاً وَغَمّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18313, 'اِنْشِقاقٌ', 'انشقاق', 'مصدر', 'شقق', 'انشقاق', 'نشقق', 'مص. اِنْشَقَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْشِقاقٌ-اِنْشِقاقٌ [ش ق ق] (مص. اِنْشَقَّ). 1.""ظَهَرَ انْشِقاقٌ في البابِ"" : فَتْحَةٌ في خَشَبِها يُمْكِنُكَ أَنْ تَرَى مِن خِلالِها. 2.""اِنْشِقاقُ الجَماعَةِ"" : اِنْفِصالُ أَفْرادِها بِسَبَبِ خِلافٍ في الرَّأْيِ أَوِ العَقيدَةِ. ""حَدَثَ انْشِقاقٌ في الحِزْبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18314, 'إِنْشالٌ', 'إنشال', 'مصدر', 'نشل', 'ءنشال', 'إنشل', 'مص. أَنْشَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْشالٌ-إِنْشالٌ [ن ش ل] (مص. أَنْشَلَ). ""إنْشالُ اللَّحْمِ مِنَ القِدْرِ"" : أَخْذُهُ بِاليَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18315, 'اِنْشِلالٌ', 'انشلال', 'مصدر', 'شلل', 'انشلال', 'نشلل', 'مص. اِنْشَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْشِلالٌ-اِنْشِلالٌ [ش ل ل] (مص. اِنْشَلَّ). ""اِنْشِلالُ السَّيْلِ"": تَدافُقُهُ، تَدَفُّقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18316, 'اِنْشِواءٌ', 'انشواء', 'مصدر', 'شوي', 'انشواء', 'نش', 'مص. اِنْشَوى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِنْشِواءٌ-اِنْشِواءٌ [ش و ي] (مص. اِنْشَوى). ""اِنْشِواءُ اللَّحْمِ"": شَيُّهُ، نُضْجُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18317, 'اِنْصِياعٌ', 'انصياع', 'مصدر', 'صوع،صيع', 'انصياع', 'نصع', 'مص. اِنْصاعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْصِياعٌ-اِنْصِياعٌ [ص و ع، ص ي ع] (مص. اِنْصاعَ). ""الانْصِياعُ لِلْحَقِّ"" : الخُضوعُ، الامْتِثالُ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18318, 'اِنْصِبابٌ', 'انصباب', 'مصدر', 'صبب', 'انصباب', 'نصبب', 'مص. اِنْصَبَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْصِبابٌ-اِنْصِبابٌ [ص ب ب] (مص. اِنْصَبَّ). 1.""الانْصِبابُ على العَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18319, 'اِنْضِمامٌ', 'انضمام', 'مصدر', 'ضمم', 'انضمام', 'نضمم', 'مص. اِنْضَمَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْضِمامٌ-اِنْضِمامٌ [ض م م ] (مص. اِنْضَمَّ). ""يَرْغَبُ في الانْضِمامِ إلى الحِزْبِ"" : في الدُّخولِ إِلَيْهِ، الالْتِحاقِ بِهِ، الانْضِواءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18320, 'اِنْصاتٌ', 'انصات', 'مصدر', 'نصت', 'انصات', 'نصت', 'مص. أَنْصَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْصاتٌ-اِنْصاتٌ [ن ص ت] (مص. أَنْصَتَ). ""الإِنْصاتُ لِلْمُتَحَدِّثِ"" : الاسْتِماعُ إِلَيْهِ بانْتِباهٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18321, 'اِنْصِداعٌ', 'انصداع', 'مصدر', 'صدع', 'انصداع', 'نصدع', 'مص. اِنْصَدَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْصِداعٌ-اِنْصِداعٌ [ص د ع] (مص. اِنْصَدَعَ). 1.""اِنْصِداعُ الإِناءِ"" : اِنْشِقا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18322, 'اِنْصِرافٌ', 'انصراف', 'مصدر', 'صرف', 'انصراف', 'نصرف', 'مص. اِنْصَرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْصِرافٌ-اِنْصِرافٌ [ص ر ف] (مص. اِنْصَرَفَ). 1.""اِنْصِرافُ الوَقْتِ الْمُحَدَّدِ"" : مُرورُهُ. 2.""اِنْصِرافُ كُلِّ العامِلينَ"" : ذَهابُهُمْ، مُغادَرَتُهُمْ. ""هَمُّوا بالانْصِرافِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18323, 'اِنْصِرامٌ', 'انصرام', 'مصدر', 'صرم', 'انصرام', 'نصرم', 'مص. اِنْصَرَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْصِرامٌ-اِنْصِرامٌ [ص ر م] (مص. اِنْصَرَمَ). 1.""اِنْصِرامُ الأيَّامِ"": اِنْقِضاؤُها، مُرُورُها. 2.""اِنْصِرامُ حَبْلٍ"" : اِنْقِطاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18324, 'إِنْصافٌ', 'إنصاف', 'مصدر', 'نصف', 'ءنصاف', 'إنصف', 'مص. أَنْصَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْصافٌ-إِنْصافٌ [ن ص ف] (مص. أَنْصَفَ). ""إِنْصافُ الْمَظْلومِ"" : اِسْتِيفاؤُهُ حَقَّهُ، أَيْ إِزالَةُ الظُّلْمِ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18325, 'اِنْصِهارٌ', 'انصهار', 'مصدر', 'صهر', 'انصهار', 'نصهر', 'مص. اِنْصَهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْصِهارٌ-اِنْصِهارٌ [ص هـ ر] (مص. اِنْصَهَرَ). 1.""اِنْصِهارُ مَعْدِنٍ"" (كيما): تَحْويلُ مادَّتِهِ مِنَ الحالَةِ الصَّلْبَةِ إلى حال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18326, 'اِنْضِباطٌ', 'انضباط', 'مصدر', 'ضبط', 'انضباط', 'نضبط', 'مص. اِنْضَبَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْضِباطٌ-اِنْضِباطٌ [ض ب ط] (مص. اِنْضَبَطَ). ""الانْضِباطُ لِلْقانونِ أَمْرٌ هامٌّ"" : خُضوعُكَ لِلْقانُونِ، اِمْتِثالُكَ. ""القانونُ الأساسِيُّ في الْمُعَسْكَرِ هُوَ الانْضِباطُ العَسْكَرِيُّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18327, 'إِنْضاجٌ', 'إنضاج', 'مصدر', 'نضج', 'ءنضاج', 'إنضج', 'مص. أَنْضَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْضاجٌ-إِنْضاجٌ [ن ض ج] (مص. أَنْضَجَ). ""ساعَدَتِ الْمَوادُّ الكيمِيائِيَّةُ على إِنْضاجِ الثَّمَرِ"" : على جَعْلِهِ ناضِجاً طَيِّبَ الأكْلِ. ""إِنْضاجُ اللَّحْمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18328, 'اِنْضِفارٌ', 'انضفار', 'مصدر', 'ضفر', 'انضفار', 'نضفر', 'مص. اِنْضَفَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْضِفارٌ-اِنْضِفارٌ [ض ف ر] (مص. اِنْضَفَرَ). 1.""اِنْضِفارُ الشَّعْرِ"": اِلْتِواؤُهُ ضَفائِرَ. 2.""اِنْضِفارُ الحَبْلَيْنِ"" : اِلْتَوَاؤُهُما بِشَكْلٍ مُنْتَظِمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18329, 'إِنْظامٌ', 'إنظام', 'مصدر', 'نظم', 'ءنظام', 'إنظم', 'مص. أَنْظَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَناظيمُ"', '', 'R', '', '', '', '', '', '', '"(مص. أَنْظَمَ). 1.""إِنْظامُ السَّمَكَةِ"" : خَيْطٌ مَنْظوم بَيْضاً في بَطْنِ السَّمَكَةِ. 2.: كُلُّ خَيْطٍ نُظِمَ خَرَزاً، عَقيقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18330, 'اِنْضِواءٌ', 'انضواء', 'مصدر', 'ضوي', 'انضواء', 'نض', 'مص. اِنْضَوَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِنْضِواءٌ-اِنْضِواءٌ [ض و ي] (مص. اِنْضَوَى). ""اِنْضِواءُ الجَيْشِ تَحْتَ لِوائِهِ"" : اِنْضِمامُهُ، اِلْتِحاقُهُ بِهِ لِيَصيرَ تَحْتَ لِوائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18331, 'اِنْطِباعٌ', 'انطباع', 'مصدر', 'طبع', 'انطباع', 'نطبع', 'مص. اِنْطَبَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِنْطِباعٌ-اِنْطِباعٌ [ط ب ع] (مص. اِنْطَبَعَ). 1.""اِنْطِباعُ كِتابٍ"": طَبْعُهُ. 2.""خَلَّفَ لَدَيْهِ انْطِباعاً خاصّاً"" : إِدْراكاً، إِحْساساً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18332, 'اِنْطِباقٌ', 'انطباق', 'مصدر', 'طبق', 'انطباق', 'نطبق', 'مص. اِنْطَبَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْطِباقٌ-اِنْطِباقٌ [ط ب ق] (مص. اِنْطَبَقَ). ""تَأَكَّدَ مِنِ انْطِباقِ كُلِّ الأَوْصافِ عَلَيْهِ"" : كَوْنُها مُطابِقَةً، مُوافِقَةً لأَوْصافِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18333, 'اِنْتِطاحٌ', 'انتطاح', 'مصدر', 'نطح', 'انتطاح', 'نتطح', 'مص. أَنْطَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْتِطاحٌ-اِنْتِطاحٌ [ن ط ح] (مص. أَنْطَحَ). ""اِنْتِطاحُ الكَبْشَيْنِ"": نَطْحُ كُلٍّ مِنْهُما الآخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18334, 'اِنْطِفاءٌ', 'انطفاء', 'مصدر', 'طفأ', 'انطفاء', 'نطف', 'مص. اِنْطَفَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِنْطِفاءٌ-اِنْطِفاءٌ [ط ف أ] (مص. اِنْطَفَأَ). 1.""اِنْطِفاءُ النَّارِ"": خُمودُها، خُفوتُها. 2.""اِنْطِفاءُ شُعْلَتِهِ"" : اِنْتِهاؤُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18335, 'اِنْطِلاقٌ', 'انطلاق', 'مصدر', 'طلق', 'انطلاق', 'نطلق', 'مص. اِنْطَلَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْطِلاقٌ-اِنْطِلاقٌ [ط ل ق] (مص. اِنْطَلَقَ). 1.""اِنْطِلاقُ الألْعابِ"" : بَدْؤُها. 2.""اِنْطِلاقُ الْمَدافِعِ"" : اِنْقِذافُها بِما تَمْلِكُ مِنْ قُوَّةٍ مُخْتَزَنَةٍ بِداخِلَها. 3.""اِنْطِلاقُ القِطارِ"" : ذَهابُهُ بانْدِفاعٍ. ""نُقْطَةُ الانْطِلاقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18336, 'اِنْطِلاءٌ', 'انطلاء', 'مصدر', 'طلي', 'انطلاء', 'نطل', 'مص. اِنْطَلَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِنْطِلاءٌ-اِنْطِلاءٌ [ط ل ي] (مص. اِنْطَلَى). ""اِنْطِلاءُ الحيلَةِ عَلَيْهِ"": اِنْخِداعُهُ وَعَدَمُ تَنَبُّهِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18337, 'اِنْطِماسٌ', 'انطماس', 'مصدر', 'طمس', 'انطماس', 'نطمس', 'مص. اِنْطَمَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْطِماسٌ-اِنْطِماسٌ [ط م س] (مص. اِنْطَمَسَ). ""اِنْطِماسُ الأثَرِ"": اِمِّحاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18338, 'اِنْطِواءٌ', 'انطواء', 'مصدر', 'طوي', 'انطواء', 'نط', 'مص. اِنْطَوى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِنْطِواءٌ-اِنْطِواءٌ [ط و ي] (مص. اِنْطَوى). ""اِنْطِواءُ النَّفْسِ"": اِنْكِماشُها على ذاتِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18339, 'اِنْعِكاسٌ', 'انعكاس', 'مصدر', 'عكس', 'انعكاس', 'نعكس', 'مص. اِنْعَكَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِنْعَكَسَ). 1.""اِنْعِكَاسُ الضَّوْءِ"" : اِرْتِدَادُهُ عَلَى سَطْحٍ صَقِيلٍ بِحَيْثُ تُسَاوِي زَاوِيَةُ الانْعِكَاسِ زَاوِيَةَ السُّقُوطِ. 2.""زَاوِيَةُ الانْعِكَاسِ"" (فيز) : وَهِيَ الوَاقِعَةُ بَيْنَ الشُّعَاعِ الْمُرْتَدِّ وَالخَطِّ العَمُودِيِّ. 3.""حَدَثَ انْعِكَاسٌ خَطِيرٌ عَلَى حَيَاتِهِ"" : اِرْتِدَادٌ، أثَرٌ، اِنْقِلاَبٌ. ""سَتُحْدِثُ هَذِهِ الوَاقِعَةُ انْعِكَاسَاتٍ هَامَّةً عَلَى حَيَاتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18340, 'أَناظيمُ', 'أناظيم', 'مصدر', '', 'ءناظيم', 'نظم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18341, 'اِنْعِتاقٌ', 'انعتاق', 'مصدر', 'عتق', 'انعتاق', 'نعتق', 'مص. اِنْعَتَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْعِتاقٌ-اِنْعِتاقٌ [ع ت ق] (مص. اِنْعَتَقَ). ""الانْعِتاقُ مِنَ العُبودِيَّةِ"" : التَّحَرُّرُ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18342, 'إِنْعاثٌ', 'إنعاث', 'مصدر', 'نعث', 'ءنعاث', 'إنعث', 'مص. أَنْعَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْعاثٌ-إِنْعاثٌ [ن ع ث] (مص. أَنْعَثَ). ""هُوَ في إِنْعاثٍ"" : في جِدٍّ وَدَأْبٍ واسْتِعْدادٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18343, 'اِنْعِدَامٌ', 'انعدام', 'مصدر', 'عدم', 'انعدام', 'نعدم', 'مص. اِنعَدَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْعِدَامٌ-اِنْعِدَامٌ [ع د م] (مص. اِنعَدَمَ). ""اِنْعِدامُ الأسْبابِ"": عَدَمُ تَوَافُرِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18344, 'اِنْعِراجٌ', 'انعراج', 'مصدر', 'عرج', 'انعراج', 'نعرج', 'مص. اِنْعَرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْعِراجٌ-اِنْعِراجٌ [ع ر ج] (مص. اِنْعَرَجَ). ""مَنَعَنا انْعِراجُ الطَّريقِ مِنَ الوُصُولِ"" : كَثْرَةُ انْحِناءاتِها، وَانْعِطافِها، صُعودُها وَهُبوبُها. ""اِنْتَبِهْ ! فانْعِراجُ الطَّريقِ سَيَسْتَمِرُّ خَمْسَةَ كِيلو مِتْراتٍ"" : مِنْ عَلاماتِ قَانُونِ السَّيْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18345, 'اِنْعِزالٌ', 'انعزال', 'مصدر', 'عزل', 'انعزال', 'نعزل', 'مص. اِنْعَزَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِنْعِزالٌ-اِنْعِزالٌ [ع ز ل] (مص. اِنْعَزَلَ). ""يَجِدُ في اِنْعِزالِهِ عَنِ النَّاسِ راحَةَ البالِ"" : اِبْتِعادُهُ، بَقاؤُهُ وَحيداً. ""ماذا يُمْكِنُ أنْ يَسْتَفيدَ مِن انْعِزالِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18346, 'إِنْعاشٌ', 'إنعاش', 'مصدر', 'نعش', 'ءنعاش', 'إنعش', 'مص. أَنْعَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْعاشٌ-إِنْعاشٌ [ن ع ش] (مص. أَنْعَشَ). 1.""إِنْعاشُ الْمَريضِ"": إِعادَةُ الحَرَكَةِ إلى أَعْضائِهِ بَعْدَ غَيْبوبَةٍ أَوْ صَدْمَةٍ أَوْ غَرَقٍ. 2.""غُرْفَةُ الإنْعاشِ في الْمُسْتَشْفَى"" : غُرْفَةٌ مُزَوَّدَةٌ بِأَجْهِزَةٍ تُساعِدُ الْمُصابَ على عَوْدَةِ الحَرَكَةِ والحَيَوِيَّةِ إلَيْهِ. 3.""إِنْعاشُ الاقتِصادِ الوَطَنِيِّ"" : تَنْمِيَتُهُ، تَطْويرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18347, 'اِنْعِطافٌ', 'انعطاف', 'مصدر', 'عطف', 'انعطاف', 'نعطف', 'مص. اِنْعَطَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْعِطافٌ-اِنْعِطافٌ [ع ط ف] (مص. اِنْعَطَفَ). ""وَقَفَ عِنْدَ انْعِطافِ الطَّريقِ"" : النُّقْطَةُ الَّتي يَنْعَرِجُ فيها الطَّريقُ، يَنْحَرِفُ فيها. ""مِنَ الخُطورَةِ أَنْ تَسْبَحَ عِنْدَ انْعِطافِ النَّهْرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18348, 'اِنْعِقَادٌ', 'انعقاد', 'مصدر', 'عقد', 'انعقاد', 'نعقد', 'مص. اِنْعَقَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْعِقَادٌ-اِنْعِقَادٌ [ع ق د] (مص. اِنْعَقَدَ). 1.""تَمَّ انْعِقَادُ اِتِّفَاقٍ بَيْنَ الْمُتَخَاصِمينَ"" : تَمَّ إبْرَامُ اتِّفَاقٍ لِلْوُصُولِ إِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18349, 'اِنْفِساحٌ', 'انفساح', 'مصدر', 'فسح', 'انفساح', 'نفسح', 'مص. اِنْفَسَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْفِساحٌ-اِنْفِساحٌ [ف س ح] (مص. اِنْفَسَحَ)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18350, 'إِنْعامٌ', 'إنعام', 'مصدر', 'نعم', 'ءنعام', 'إنعم', 'مص. أَنْعَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. أَنْعَمَ). 1.""يَتَلَقَّى إِنْعامَهُ في كُلِّ عيدٍ"" : ما يَهَبُهُ الْمَرْءُ مِنْ عَطاءٍ، أَيْ ما يَنْعَمُ بِهِ، الهِبَةُ، الإِحْسانُ. 2.""إِنْعامُ النَّظَرِ"" : التَّمَعُّنُ والتَّأَمُّلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18351, 'اِنغِرَاسٌ', 'انغراس', 'مصدر', 'غرس', 'انغراس', 'نغرس', 'مص. اِنْغَرَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنغِرَاسٌ-اِنغِرَاسٌ [غ ر س] (مص. اِنْغَرَسَ). 1.""اِنْغِرَاسُ الشَّجَرِ"": رُسُوخُهَا فِي "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18352, 'اِنْغِلاقٌ', 'انغلاق', 'مصدر', 'غلق', 'انغلاق', 'نغلق', 'مص. اِنْغَلَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِنْغِلاقٌ-اِنْغِلاقٌ [غ ل ق] (مص. اِنْغَلَقَ). ""لاَ دُخولَ بَعْدَ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18353, 'اِنْغِمارٌ', 'انغمار', 'مصدر', 'غمر', 'انغمار', 'نغمر', 'مص. اِنْغَمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْغِمارٌ-اِنْغِمارٌ [غ م ر] (مص. اِنْغَمَرَ). 1.""الانْغِمارُ في الماءِ"": الغَوْصُ، الانْغِماسُ فيهِ. 2.""الانْغِمارُ في اللَّهْوِ واللَّعِبِ"": الدُّخولُ فيهِ كُلِّيَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18354, 'اِنْفِتاحٌ', 'انفتاح', 'مصدر', 'فتح', 'انفتاح', 'نفتح', 'مص. اِنْفَتَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِنْفِتاحٌ-اِنْفِتاحٌ [ف ت ح] (مص. اِنْفَتَحَ). 1.""أُعْلِنَ عَنِ انْفِتاحِ أَبْوابِ الْمَعْرِضِ"" : عَنْ بِدايَتِهِ. 2.""اِنْفِتاحٌ اِقْتِصادِيٌّ"": سِياسَةٌ لِيبِرالِيَّةٌ يَعْتَمِدُها نِظامٌ مَّا لِلتَّعامُلِ مَعَ شَرِكاتٍ وَرَسامِيلَ أَجْنَبِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18355, 'اِنْفِجارٌ', 'انفجار', 'مصدر', 'فجر', 'انفجار', 'نفجر', 'مص. اِنْفَجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِنْفِجارٌ-اِنْفِجارٌ [ف ج ر] (مص. اِنْفَجَرَ). 1.""حَدَثَ انْفِجارٌ في عَجَلَةِ سَيَّارَتِهِ"" : وَقَعَ فيها ضَغْطٌ أَدَّى إلى اهْتِزازٍ فَصَدَرَ عَنْهُ دَوِيُّ صَوْتٍ شَديدٍ. 2.""أُعْلِنَ عَنِ انْفِجارِ قُنْبُلَةٍ في الأراضي الْمُحْتَلَّةِ"" : عَنْ تَفَرْقُعِها، أَحْدَثَثْ صَوْتا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18356, 'اِنْفِراجٌ', 'انفراج', 'مصدر', 'فرج', 'انفراج', 'نفرج', 'مص. اِنْفَرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْفِراجٌ-اِنْفِراجٌ [ف ر ج] (مص. اِنْفَرَجَ). 1.""اِنْفِراجُ الضَّائِقَةِ"" : اِنْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18357, 'اِنْفِرادٌ', 'انفراد', 'مصدر', 'فرد', 'انفراد', 'نفرد', 'مص. اِنْفَرَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِنْفِرادٌ-اِنْفِرادٌ [ف ر د] (مص. اِنْفَرَدَ). 1.""تَحَدَّثَ مَعَهُ على انْفِرادٍ"" : على حِدَةٍ، ثُنائِيّاً. 2.""يَميلُ إلى العُزْلَةِ والانْفِرادِ"": ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18358, 'اِنْفِراطٌ', 'انفراط', 'مصدر', 'فرط', 'انفراط', 'نفرط', 'مص. اِنْفَرَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْفِراطٌ-اِنْفِراطٌ [ف ر ط] (مص. اِنْفَرَطَ). ""اِنْفِراطُ الجَمْعِ"": تَفَرُّقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18359, 'اِنْفِكاكٌ', 'انفكاك', 'مصدر', 'فكك', 'انفكاك', 'نفكك', 'مص. اِنْفَكَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْفِكاكٌ-اِنْفِكاكٌ [ف ك ك] (مص. اِنْفَكَّ). 1.""اِنْفِكاكُ العَظْمِ"": زَيْغُهُ عَنْ مَوْض"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18360, 'اِنْفِساخٌ', 'انفساخ', 'مصدر', 'فسخ', 'انفساخ', 'نفسخ', 'مص. اِنْفَسَخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْفِساخٌ-اِنْفِساخٌ [ف س خ] (مص. اِنْفَسَخَ). ""اِنْفِساخُ العَقْدِ"": اِنْحِلالُهُ، أَيْ صَيْرُهُ غَيْرَ مَعْمولٍ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18361, 'اِنْفِصادٌ', 'انفصاد', 'مصدر', 'فصد', 'انفصاد', 'نفصد', 'مص. اِنْفَصَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْفِصادٌ-اِنْفِصادٌ [ف ص د] (مص. اِنْفَصَدَ). ""اِنْفِصادُ الدَّمِ"": سَيَلانُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18362, 'اِنْفِصالٌ', 'انفصال', 'مصدر', 'فصل', 'انفصال', 'نفصل', 'مص. اِنْفَصَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِنْفِصالٌ-اِنْفِصالٌ [ف ص ل] (مص. اِنْفَصَلَ). 1.""اِنْفِصالُ أَجْزاءِ السَّيَّارَةِ"" : اِنْحِلالُها وَتَباعُدُ أَجْزائِها. 2.""فَقَدَ شُعورَهُ الوَطَنِيَّ لَمَّا أَعْلَنَ انْفِصال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18363, 'اِنْفِصامٌ', 'انفصام', 'مصدر', 'فصم', 'انفصام', 'نفصم', 'مص. اِنْفَصَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْفِصامٌ-اِنْفِصامٌ [ف ص م] (مص. اِنْفَصَمَ). 1.""اِنْفِصامُ العُقْدَةِ"": اِنْصِداعُها. 2.""اِنْفِصامُ عُرَى الصَّداقَةِ"" : اِنْتِهاءُ تَواصُلِها، اِنْقِطاعُها. 3.""اِنْفِصامُ الإِناءِ"" : اِنْكِسارُهُ. 4.""يَعيشُ حالَةَ انْفِصامِ الشَّخْصِيَّةِ"" : مَنْ يَعيشُ ازْدِواجِيَّةً في شَخْصِيَّتِهِ، وَيَفْقِدُ تَوازُنَهُ النَّفْسِيَّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18364, 'إِنْفاضٌ', 'إنفاض', 'مصدر', 'نفض', 'ءنفاض', 'إنفض', 'مص. أَنْفَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْفاضٌ-إِنْفاضٌ [ن ف ض] (مص. أَنْفَضَ). 1.""إِنْفاضُ الوِعاءِ"" : نَفادُ ما فِيهِ. 2.""إِنْفاضُ الزَّادِ"" : إِنْفادُهُ. 3.""هُمْ في إِنْفاضٍ"" : في مَجاعَةٍ. 4.""فَرَضَ عَلَيْهِ الإِنْفاضُ بِأنْ يُهاجِرَ"": الحاجَةُ، الضَّرورَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18365, 'اِنْفِطارٌ', 'انفطار', 'مصدر', 'فطر', 'انفطار', 'نفطر', 'مص. اِنْفَطَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْفِطارٌ-اِنْفِطارٌ [ف ط ر] (مص. اِنْفَطَرَ). 1.""اِنْفِطارُ أَغْصانِ الشَّجَرَةِ"" : ظُهورُ نَباتِ أَوْراقِها. 2.""اِنْفِطارُ الأرْضِ بِالنَّباتِ"": ظُهورُ نَباتِها وَتَنامِيهِ. 3.""اِنْفِطارُ السَّماءِ"" : اِنْشِقاقُها. 4.""اِنْفِطارُ القَلْبِ حُزْناً"" : تَصَدُّعُهُ، اِهْتِزازُهُ. 5.""سورَةُ الانْفِطارِ"" : إِحْدَى سُوَرِ القُرْآنِ الكَريمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18366, 'اِنْفِطامٌ', 'انفطام', 'مصدر', 'فطم', 'انفطام', 'نفطم', 'مص. اِنْفَطَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْفِطامٌ-اِنْفِطامٌ [ف ط م] (مص. اِنْفَطَمَ). ""اِنْفِطامُ الوَلَدِ"": اِنْقِطاعُهُ، اِنْفِصالُهُ عَنِ الرَّضاعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18367, 'اِنْفِعالٌ', 'انفعال', 'مصدر', 'فعل', 'انفعال', 'نفعل', 'مص. اِنْفَعَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"اِنْفِعالٌ-اِنْفِعالٌ [ف ع ل] (مص. اِنْفَعَلَ). 1.""لَمْ يَتَمَكَّنْ مِن إِخْفاءِ انْفِعالِهِ"" : اِضْطِرابِهِ مِنْ جَرَّاءِ حُزْنٍ أَوْ خَوْفٍ أَوْ صَدْمَةٍ أَوْ غَضَبٍ. ""لَمْ يَكُنِ انْفِعالُهُ إِلاَّ حالَةً عابِرَةً"". 2.""لاَ تَكُنْ سَريعَ الانْفِعالِ"" : سَريعَ التَّأَثُّرِ والغَضَبِ. ""لَقَدْ رَأَيْتُهُ يَتَكَلَّمُ بانْفِعالٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18368, 'إِنْفاقٌ', 'إنفاق', 'مصدر', 'نفق', 'ءنفاق', 'إنفق', 'مص. أَنْفَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْفاقٌ-إِنْفاقٌ [ن ف ق] (مص. أَنْفَقَ). 1.""قَرَّرَ الإِنْفاقَ مِنْ ثَرْوَتِهِ"": بَذْلَ المالِ وَصَرْفَهُ في سَبيلِ عَمَلٍ صالِحٍ. 2.""هُوَ في إِنْفاقٍ"": في فاقَةٍ، في فَقْرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18369, 'اِنْقِشَاعٌ', 'انقشاع', 'مصدر', 'قشع', 'انقشاع', 'نقشع', 'مص. انْقَشَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْقِشَاعٌ-اِنْقِشَاعٌ [ق ش ع] (مص. انْقَشَعَ). 1. ""اِنْقِشَاعُ السُّحُبِ"" : اِنْكِشَافُهَا. 2. ""اِنْقِشَاعُ الهَمِّ عَنْ قَلْبِهِ"" : زَوَالُهُ، تَبَدُّدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18370, 'اِنْفِلاتٌ', 'انفلات', 'مصدر', 'فلت', 'انفلات', 'نفلت', 'مص. اِنْفَلَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْفِلاتٌ-اِنْفِلاتٌ [ف ل ت] (مص. اِنْفَلَتَ). 1.""اِنْفِلاتُ الأمْرِ مِنْ بَيْنِ يَدَيْهِ"" : خُروجُهُ، تَمَلُّصُّهُ مِنْ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18371, 'اِنْفِلاقٌ', 'انفلاق', 'مصدر', 'فلق', 'انفلاق', 'نفلق', 'مص. اِنْفَلَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْفِلاقٌ-اِنْفِلاقٌ [ف ل ق] (مص. اِنْفَلَقَ). 1.""اِنْفِلاقُ الثَّمَرَةِ"": "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18372, 'أَناقَةٌ', 'أناقة', 'مصدر', 'أنق', 'ءناقة', 'نقة', 'مص. أَنِقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"أَناقَةٌ-أَناقَةٌ [أ ن ق] (مص. أَنِقَ). 1.""شابٌّ مَعْروفٌ بِأَناقَتِهِ"": يَهْتَمُّ بِهِنْدامِهِ وَجَمالِهِ. 2.""يالَها مِنْ أَناقَةٍ"" : تَعْبيرٌ يُقالُ إِعْجاباً لِلرَّجُلِ الأَنيقِ أَوِ الْمَرْأَةِ الأنيقَةِ الْمُهْتَمَّةِ بِحُسْنِ هِنْدامِها. 3.""فيهِ أَناقَةٌ وَلَباقَةٌ"" : رَشاقَةٌ، إِعْجابٌ، حُسْنُ الْمَظْهَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18373, 'اِنْقِيادٌ', 'انقياد', 'مصدر', 'قود', 'انقياد', 'نقد', 'مص. اِنْقادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْقِيادٌ-اِنْقِيادٌ [ق و د] (مص. اِنْقادَ). ""لَمْ يَكُنْ مِنَ السَّهْلِ انْقِيادُهُ"" : إِخْضاعُهُ وَجَعْلُهُ مُنْقاداً. ""سَهْلُ الانْقِيادِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18374, 'اِنْقِبَاضٌ', 'انقباض', 'مصدر', 'قبض', 'انقباض', 'نقبض', 'مص. اِنْقَبضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْقِبَاضٌ-اِنْقِبَاضٌ [ق ب ض] (مص. اِنْقَبضَ). 1. ""شَعَرَ بِانْقِبَاضٍ فِي بَطْنِهِ أوْ أمْعَائِهِ"" : بِتَصَلُّبٍ. 2. ""مُنْذُ يَوْمَيْنِ وَهُوَ فِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18375, 'إِنْقَاذٌ', 'إنقاذ', 'مصدر', 'نقذ', 'ءنقاذ', 'إنقذ', 'مص. أنْقَذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْقَاذٌ-إِنْقَاذٌ [ن ق ذ] (مص. أنْقَذَ). 1. ""إنْقَاذُ الحُطَام"" : اِنْتِشَالُهُ. 2.""وَصَلَتْ سَيَّارَةُ الإنْقَاذِ إلَى مَكَانِ الحَادِثِ"" : سَيَّارَةُ الإنْجَادِ وَتَخْلِيصِ النَّاسِ مِنَ الهَلاَكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18376, 'اِنْقِرَاضٌ', 'انقراض', 'مصدر', 'قرض', 'انقراض', 'نقرض', 'مص. اِنْقَرَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْقِرَاضٌ-اِنْقِرَاضٌ [ق ر ض] (مص. اِنْقَرَضَ). ""اِنْقِرَاضُ حَيَوَانِ الدِّينَاصُورِ"" : اِخْتِفَاؤُهُ، أيْ صَيْرُهُ غَيْرَ مَوْجودٍ عَلَى وَجْهِ الأرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18377, 'اِنْقِسَامٌ', 'انقسام', 'مصدر', 'قسم', 'انقسام', 'نقسم', 'مص. اِنْقَسَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْقِسَامٌ-اِنْقِسَامٌ [ق س م] (مص. اِنْقَسَمَ). 1.""اِنْقِسَامُ أعْضَاءِ النَّادِي"" : تَوَزُّعُهُمْ مَجْمُوعَتَيْنِ أَوْ مَجْمُوعَاتٍ بِسَبَبِ تَبَايُنٍ فِي الرَّأْيِ. 2.""اِنْقِسَامٌ فَتِيليٌّ"" : اِنْفِصالُ الخَلِيَّةِ الحَيَّةِ إلَى خَلِيَّتِيْنِ لِكُلٍّ مِنْهُمَا نَوَاةٌ جَدِيدَةٌ، وَهُوَ يَمُرُّ بِمَرَاحِلَ مُتَعَدِّدَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18378, 'اِنْقِشَارٌ', 'انقشار', 'مصدر', 'قشر', 'انقشار', 'نقشر', 'مص. اِنْقَشَر', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْقِشَارٌ-اِنْقِشَارٌ [ق ش ر] (مص. اِنْقَشَر). ""اِنْقِشَارُ الجِلْدِ"": تَقَشُّرُهُ، سُقُوطُ قِشْرَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18379, 'اِنْكِسارٌ', 'انكسار', 'مصدر', 'كسر', 'انكسار', 'نكسر', 'مص. اِنْكَسَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْكِسارٌ-اِنْكِسارٌ [ك س ر] (مص. اِنْكَسَرَ). 1.""اِنْكِسارُ القَلْبِ"": تَحَطُّمُهُ، فُتورُهُ. ""اِنْقَلَبَ اعْتِدادُهُ بِقُوَّتِهِ وَخُيَلاَؤُهُ إلى اِنْكِسارٍ وَتَراخٍ وَخِذْلانٍ"".(إسحق الحسيني). 2.""اِنْكِسارُ شَوْكَةِ العَدُوِّ"" : اِنْهِزامُهُ. 3.""اِنْكِسارُ الضَّو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18380, 'إِنْقَاصٌ', 'إنقاص', 'مصدر', 'نقص', 'ءنقاص', 'إنقص', 'مص. أنْقَصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْقَاصٌ-إِنْقَاصٌ [ن ق ص] (مص. أنْقَصَ). ""إنْقَاصُ الثَّمَنِ"" : نَقْصُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18381, 'اِنْقِصَافٌ', 'انقصاف', 'مصدر', 'قصف', 'انقصاف', 'نقصف', 'مص. اِنْقَصَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْقِصَافٌ-اِنْقِصَافٌ [ق ص ف] (مص. اِنْقَص"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18382, 'اِنْقِصَامٌ', 'انقصام', 'مصدر', 'قصم', 'انقصام', 'نقصم', 'مص. اِنْقَصَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْقِصَامٌ-اِنْقِصَامٌ [ق ص م] (مص. اِنْقَصَمَ). ""ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18383, 'اِنْقِضاضٌ', 'انقضاض', 'مصدر', 'قضض', 'انقضاض', 'نقضض', 'مص. اِنْقَضَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْقِضاضٌ-اِنْقِضاضٌ [ق ض ض] (مص. اِنْقَضَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18384, 'اِنْقِضاءٌ', 'انقضاء', 'مصدر', 'قضي', 'انقضاء', 'نقض', 'مص. اِنْقَضَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِنْقِضاءٌ-اِنْقِضاءٌ [ق ض ي] (مص. اِنْقَضَى). ""اِنْقِضاءُ الأجَلِ"": اِنْتِهاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18385, 'اِنْقِطاعٌ', 'انقطاع', 'مصدر', 'قطع', 'انقطاع', 'نقطع', 'مص. اِنْقَطَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْقِطاعٌ-اِنْقِطاعٌ [ق ط ع] (مص. اِنْقَطَعَ). 1.""لا أَحَدَ يَعْرِفُ سَبَبَ اِنْقِطاعِ التِّيَّارِ الكَهْرَبائِيِّ"" : تَوَق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18386, 'اِنْقِلابٌ', 'انقلاب', 'مصدر', 'قلب', 'انقلاب', 'نقلب', 'مص. اِنْقَلَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِنْقَلَبَ). 1.""حَدَثَ انْقِلابٌ مُفاجِئٌ في الطَّقْسِ"" : حَدَثَ تَغَيُّرٌ في الطَّقْسِ مِنْ حالَةٍ إلى حالَةٍ أُخرَى. 2.""وَقَعَ انْقِلابُ السَّيَّارَةِ في مُنْعَطَفِ الطَّريقِ"" : أَيْ صارَ أَعْلاَهَا أَسْفَلَها. 3.""فَشِلَ الانْقِلابُ العَسْكَرِيُّ"" : مُحاوَلَةُ الاسْتيلاَءِ على السُّل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18387, 'اِنْكِبابٌ', 'انكباب', 'مصدر', 'كبب', 'انكباب', 'نكبب', 'مص. اِنْكَبَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْكِبابٌ-اِنْكِبابٌ [ك ب ب] (مص. اِنْكَبَّ). 1.""الانْكِبابُ على العَمَلِ"" : التَّفَرُّغُ لَهُ، لُزومُهُ. 2.""الانْكِبابُ على الوَجْهِ"" : الوُقوعُ على الوَجْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18388, 'إِنْكارٌ', 'إنكار', 'مصدر', 'نكر', 'ءنكار', 'إنكر', 'مص. أَنْكَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِنْكارٌ-إِنْكارٌ [ن ك ر] (مص. أَنْكَرَ). 1.""مِنْ خِصالِهِ الحَميدَةِ إِنْكارُ الذَّاتِ"" : لا يُعْطِي أَهَمِّيَّةً لِذاتِهِ، لِنَفْسِهِ. 2.""مِنْ صِفاتِهِ الذَّميمَةِ إِنْكارُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18389, 'اِنْهِدامٌ', 'انهدام', 'مصدر', 'هدم', 'انهدام', 'نهدم', 'مص. اِنْهَدَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْهِدامٌ-اِنْهِدامٌ [هـ د م] (مص. اِنْهَدَمَ). ""اِنْهِدامُ البِناءِ"": اِنْهِيارُهُ، سُقوطُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18390, 'اِنْكِسافٌ', 'انكساف', 'مصدر', 'كسف', 'انكساف', 'نكسف', 'مص. اِنْكَسَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْكِسافٌ-اِنْكِسافٌ [ك س ف] (مص. اِنْكَسَفَ). ""اِنْكِسافُ الشَّمْسِ"" : اِحْتِجابُها، أَيْ تَعَرُّضُها لِلْكُسوفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18391, 'اِنْكِشَافٌ', 'انكشاف', 'مصدر', 'كشف', 'انكشاف', 'نكشف', 'مص. اِنْكَشَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْكِشَافٌ-اِنْكِشَافٌ [ك ش ف] (مص. اِنْكَشَفَ). 1.""اِنْكِشَافُ الحَقِيقَةِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18392, 'اِنْكِمَاشٌ', 'انكماش', 'مصدر', 'كمش', 'انكماش', 'نكمش', 'مص. اِنْكَمَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْكِمَاشٌ-اِنْكِمَاشٌ [ك م ش] (مص. اِنْكَمَشَ). 1.""ثَوْبٌ سَرِيعُ الانْكِمَاشِ"" : سَرِيعُ الالْتِوَاءِ. 2.""اِنْكِمَاشُ مَخَالِبِ الأسَدِ"" : دُخولُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18393, 'اِنْمِحَاءٌ', 'انمحاء', 'مصدر', 'محي', 'انمحاء', 'نمح', 'مص. انْمَحَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِنْمِحَاءٌ-اِنْمِحَاءٌ [م ح ي] (مص. انْمَحَى). ""اِنْمِحَاءُ الأثَرِ"": اِخْتِفَاؤُهُ، اِنْطِمَاسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18394, 'إِنْمَاءٌ', 'إنماء', 'مصدر', 'نمي', 'ءنماء', 'إنم', 'مص. أنْمَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِنْمَاءٌ-إِنْمَاءٌ [ن م ي] (مص. أنْمَى). ""إنْمَاءُ اقْتِصَادِ البِلاَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18395, 'اِنْهِيَارٌ', 'انهيار', 'مصدر', 'هور', 'انهيار', 'نهر', 'مص. اِنْهَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْهِيَارٌ-اِنْهِيَارٌ [ هـ و ر] (مص. اِنْهَارَ). 1. ""اِنْهِيَارُ جُدْرَانِ البَيْتِ"" : اِنْهِدامُها، سُقوطُها. 2.""الانْهِيَارُ العَصَبِيُّ"" : حَالَةٌ نَفْسِيَّةٌ مَرَضِيَّةٌ تُصِيبُ الإنْسَانَ وَتَجْعَلُهُ فَاقِدَ الإرَادَةِ أوْ فِي حَالَةِ غَلَيَانٍ عَصَبِيٍّ أوْ حُزْنٍ وَاكْتِئَابٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18396, 'اِنْهِيالٌ', 'انهيال', 'مصدر', 'هيل', 'انهيال', 'نهل', 'مص. اِنْهَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْهِيالٌ-اِنْهِيالٌ [هـ ي ل] (مص. اِنْهَالَ). 1.""اِنْهِيالُ الْمَصَائِبِ"" : تَهَاطُلُهَا، تَتالِيها. 2.""اِنْهِيَالُ الشَّتَائِمِ"" : اِنْصِبَابُهَا، كَيْلُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18397, 'اِنْهِبَاطٌ', 'انهباط', 'مصدر', 'هبط', 'انهباط', 'نهبط', 'مص. اِنْهَبَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْهِبَاطٌ-اِنْهِبَاطٌ [هـ ب ط] (مص. اِنْهَبَطَ). ""اِنْهِبَاطُ دَرَجَةِ الحَرَارَةِ"" : هُبوطُها، اِنْخِفَاضُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18398, 'اِنْهِدَادٌ', 'انهداد', 'مصدر', 'هدد', 'انهداد', 'نهدد', 'مص. اِنْهَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْهِدَادٌ-اِنْهِدَادٌ [هـ د د] (مص. اِنْهَدَّ). ""اِنْهِدَادُ البِنَاءِ"": اِنْهِيَارُهُ، سُقُوطُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18399, 'اِنْهِزَامٌ', 'انهزام', 'مصدر', 'هزم', 'انهزام', 'نهزم', 'مص. اِنْهَزَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْهِزَامٌ-اِنْهِزَامٌ [هـ ز م] (مص. اِنْهَزَمَ). ""اِسْتَعَادَ الْمُسْلِمُونَ قُوَّتَهُمْ بَعْدَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18400, 'إنْهَاضٌ', 'إنهاض', 'مصدر', 'نهض', 'ءنهاض', 'إنهض', 'مص. أنْهَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إنْهَاضٌ-إنْهَاضٌ [ن هـ ض] (مص. أنْهَضَ). 1.""حَاوَلَ إنْهَاضَهُ مِنْ فِرَاشِهِ"" : تَحْرِيكَهُ وَمُساعَدَتَهُ عَلَى النُّهُوضِ. 2.""كَانَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18401, 'اِنْهِضَامٌ', 'انهضام', 'مصدر', 'هضم', 'انهضام', 'نهضم', 'مص. اِنْهَضَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْهِضَامٌ-اِنْهِضَامٌ [هـ ض م] (مص. اِنْهَضَمَ). ""اِنْهِضَامُ الطَّعَامِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18402, 'اِنْهَاكٌ', 'انهاك', 'مصدر', 'نهك', 'انهاك', 'نهك', 'مص. أنْهَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْهَاكٌ-اِنْهَاكٌ [ن هـ ك] (مص. أنْهَكَ). ""عَمِلَ لَيْلَ نَه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18403, 'اِنْهِلالٌ', 'انهلال', 'مصدر', 'هلل', 'انهلال', 'نهلل', 'مص. اِنْهَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْهِلالٌ-اِنْهِلالٌ [هـ ل ل] (مص. اِنْهَلَّ). 1.""اِنْهِلالُ الْمَطَرِ"": هُطولُهُ بِشِدَّةٍ"". 2.""اِنْهِلالُ العَيْنِ"" : سَكْبُها دَمْعاً غَزيراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18404, 'اِنْهِمارٌ', 'انهمار', 'مصدر', 'همر', 'انهمار', 'نهمر', 'مص. اِنْهَمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْهِمارٌ-اِنْهِمارٌ [هـ م ر] (مص. اِنْهَمَرَ). ""اِنْهِمارُ السَّيْلِ"": اِنْسِكابُهُ، سَيَلانُهُ. ""اِنْهِمارُ الدُّموعِ على خَدَّيْها""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18405, 'اِنْهِمَاكٌ', 'انهماك', 'مصدر', 'همك', 'انهماك', 'نهمك', 'مص. اِنْهَمَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِنْهِمَاكٌ-اِنْهِمَاكٌ [هـ م ك] (مص. اِنْهَمَكَ). ""كَانَ شَدِيدَ الانْهِمَاكِ فِي عَمَلِهِ"" : الجِدّ فِيهِ بِرَغْبَةٍ وَاهْتِمَامٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18406, 'إنْهَاءٌ', 'إنهاء', 'مصدر', 'نهي', 'ءنهاء', 'إنه', 'مص. أنْهَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إنْهَاءٌ-إنْهَاءٌ [ن هـ ي] (مص. أنْهَى). ""قَرَّرَ إنْهَاءَ عَمَلِهِ مَسَاءً"" : أيْ إكْمَالَهُ، إتْمَامَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18407, 'أناءٌ', 'أناء', 'مصدر', 'أني', 'ءناء', 'ن', 'مص. أَنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"أناءٌ-أناءٌ [أ ن ي] (مص. أَنَى). 1.""أَناءُ الصَّلاةِ"" : حُلولُ وَقْتِها. 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18408, 'أَناةٌ', 'أناة', 'مصدر', 'أني', 'ءناة', 'نة', 'مص. أَنَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"أَناةٌ-أَناةٌ [أ ن ي] (مص. أَنَى). 1.""أَنْجَزَ عَمَلَهُ في أَناةٍ"": في تَمَهُّلٍ. 2.""طَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18409, 'إهَانَةٌ', 'إهانة', 'مصدر', 'هون', 'ءهانة', 'إهنة', 'مص. أهَانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إهَانَةٌ-إهَانَةٌ [هـ و ن] (مص. أهَانَ). ""وَجَّهَ إلَيْهِ إهَانَةً أمَامَ الْمَلإِ"" : شَتِيمَة فِيهَا احْتِقَارٌ وإذْلاَلٌ. ""لَمْ يَلْقَ فِي حَيَاتِهِ إهَانَةً بِهَذِهِ الصُّورَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18410, 'إهْبَاطٌ', 'إهباط', 'مصدر', 'هبط', 'ءهباط', 'إهبط', 'مص. أَهْبَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إهْبَاطٌ-إهْبَاطٌ [هـ ب ط] (مص. أَهْبَطَ). 1.""إهْبَاطُ الثَّمَنِ"": إِنْقاصُهُ، خَفْضُهُ، النَّقْصُ مِنْهُ. 2.""إهْبَاطُهُ مِنْ أعْلَى السُّلَمِ"": إنْزَالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18411, 'اِهْتِيَاجٌ', 'اهتياج', 'مصدر', 'هيج', 'اهتياج', 'هتج', 'مص. اِهْتَاجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِهْتِيَاجٌ-اِهْتِيَاجٌ [هـ ي ج] (مص. اِهْتَاجَ). 1.""اِهْتِياجُ الرَّجُلِ"" : إصَابَتُهُ بِحَالَةٍ مِنَ التَّوَتُّرِ، هَيَجَانُهُ. 2.""اِهْتِيَاجُ البَحْرِ"": تَدَفُّقُ أمْوَاجِهِ بِعُنْفٍ، اِضْطِرَابُهُ، هَيَجَانُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18412, 'اِهْتِدَاءٌ', 'اهتداء', 'مصدر', 'هدي', 'اهتداء', 'هتد', 'مص. اِهْتَدَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"اِهْتِدَاءٌ-اِهْتِدَاءٌ [هـ د ي] (مص. اِهْتَدَى). 1.""الاهْتِدَاءُ إلَى طَرِيقِ الخَيْرِ"" : السَّيْرُ إلَى طَرِيقِ الخَيْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18413, 'اِهْتِزَازٌ', 'اهتزاز', 'مصدر', 'هزز', 'اهتزاز', 'هتزز', 'مص. اِهْتَزَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِهْتَزَّ). 1.""خَرَجَ يَجْرِي لَمَّا شَعَرَ بِاهْتِزَازِ الجُدْرَانِ"" : تَحَرُّكهَا، تَزَلْزُلُهَا. 2.""لَمْ يَكُنِ اهْتِزَازُ الطَّائِرَةِ إلا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18414, 'اِهْتِمَامٌ', 'اهتمام', 'مصدر', 'همم', 'اهتمام', 'هتمم', 'مص. اِهْتَمَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. اِهْتَمَّ). ""الاهْتِمَامُ بِالدَّرْسِ"" : إعْطَاؤُهُ أهَمِّيَّةً، الاعْتِناءُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18415, 'إهْدَارٌ', 'إهدار', 'مصدر', 'هدر', 'ءهدار', 'إهدر', 'مص. أهْدَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إهْدَارٌ-إهْدَارٌ [هـ د ر] (مص. أهْدَرَ). 1.""أعْلَنَ الأمِيرُ إهْدَارَ دَمِهِ"" : اِسْتِبَاحَهُ، جَعْلَهُ مُبَاحاً. 2.""قَامَ بِإهْدَارِ أمْوَالِ النَّاسِ هَبَاءً"" : صَرْفهَا فِيمَا لاَ فَائِدَةَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18416, 'إهْدَاءٌ', 'إهداء', 'مصدر', 'هدي', 'ءهداء', 'إهد', 'مص. أهْدَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إهْدَاءٌ-إهْدَاءٌ [هـ د ي] (مص. أهْدَى). 1.""إهْدَاءُ الهَدِيَّةِ"": تَقْدِيمُهَا. 2.""إِهْدَاء"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18417, 'إهْرَاقٌ', 'إهراق', 'مصدر', 'هرق', 'ءهراق', 'إهرق', 'مص. أَهْرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إهْرَاقٌ-إهْرَاقٌ [هـ ر ق] (مص. أَهْرَقَ). 1.""إهْرَاقُ الدِّمَاءِ"": سَيَلاَنُهَا. 2.""إِهْرَاقُ الدَّمْعِ"" : اِنْسِكَابُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18418, 'إهْلاَلٌ', 'إهلال', 'مصدر', 'هلل', 'ءهلال', 'إهلل', 'مص. أهَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إهْلاَلٌ-إهْلاَلٌ [هـ ل ل] (مص. أهَلَّ). 1.""إهْلاَلُ الهِلاَلِ"": ظُهُورُهُ. 2.""إهْلاَلُ الْمُصَلِّي"" : مُنَادَاةُ القَوْمِ صَوْبَهُ. 3.""إهْلاَلُ السَّحَابِ"" : جَعْلُهُ مُمْطِراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18419, 'إِيصافٌ', 'إيصاف', 'مصدر', 'وصف', 'ءيصاف', 'إصف', 'مص. أوْصَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِيصافٌ-إِيصافٌ [و ص ف] (مص. أوْصَفَ). ""إيصَافُ الوَلَدِ"": بُلُوغُهُ أوَانَ الخِدْمَةِ، أو إتْمَامُهُ قَدَّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18420, 'إِهْلاَكٌ', 'إهلاك', 'مصدر', 'هلك', 'ءهلاك', 'إهلك', 'مص. أَهْلَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِهْلاَكٌ-إِهْلاَكٌ [هـ ل ك] (مص. أَهْلَكَ). 1.""تَسَبَّبَ فِي إهْلاكِ القَوْمِ"" : فِي تَدْمِيرِهِمْ، تَحْطِيمِهِمْ، بِإِنْزَالِ المصَائِبِ بِهِمْ. 2. ""إهْلاَكُ الْمَاشِيَةِ"" : بَيْعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18421, 'إهْمَالٌ', 'إهمال', 'مصدر', 'همل', 'ءهمال', 'إهمل', 'مص. أَهْمَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إهْمَالٌ-إهْمَالٌ [هـ م ل] (مص. أَهْمَلَ). 1.""مَا هَذَا الإهْمَالُ"" : التَّقْصِيرُ، التَّغَافُلُ، التَّهَاوُنُ، التَّكَاسُلُ. 2.""مَنِ الَّذِي دَفَعَهُ إلَى إهْمَالِ مَشَارِيعِهِ"" : تَرْكُهَا، التَّهاوُنُ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18422, 'إِيجَابٌ', 'إيجاب', 'مصدر', 'وجب', 'ءيجاب', 'إجب', 'مص. أَوْجَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِيجَابٌ-إِيجَابٌ [و ج ب] (مص. أَوْجَبَ).1.""رَدَّ بِالإيجَابِ"" : كَانَ جَوَابُهُ بِالْمُوَافَقَةِ عَكْسَ السَّلْبِ. ""فِي حَالَةِ الإيجَابِ"" : فِي حَالَةِ الْمُوَافَقَةِ. 2.""قُمْتُ بِذَلِكَ إيجَاباً لِحَقِّهِ"" : مُرَاعَاةً لَهُ. 3.""عَلامَةُ الإيجَابِ هِيَ: +. 4.""سَلْباً وَإِيجَاباً"" : سَلْباً وإثْبَاتاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18423, 'إيجَازٌ', 'إيجاز', 'مصدر', 'وجز', 'ءيجاز', 'إجز', 'مص. أَوْجَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إيجَازٌ-إيجَازٌ [و ج ز] (مص. أَوْجَزَ). ""أَكْتُبُ بِإيجَازٍ"" : بِاقْتِضَابٍ، بِاخْتِصَارٍ، أَيْ عَدَمُ الإطَالَةِ. ""يَتَحَدَّثُ بِإيجازٍ"" ""عَوَّدَهُ عَلَى الدِّقَّةِ فِي التَّعْبِيرِ وَالإِيجَازِ فِي القَوْلِ"". (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18424, 'إِيحَاءٌ', 'إيحاء', 'مصدر', 'وحي', 'ءيحاء', 'إح', 'مص. أوْحَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِيحَاءٌ-إِيحَاءٌ [و ح ي] (مص. أوْحَى). 1.""الإيحَاءُ الذَّاتِيُّ"" : فِكْرَةٌ يُكَرِّرُهَا الْمَرْءُ وَيُرَدِّدُهَا لإِقْنَاعِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18425, 'أوَدٌ', 'أود', 'مصدر', 'أود', 'ءود', 'د', 'مص. أوِدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"أوَدٌ-أوَدٌ [أ و د] (مص. أوِدَ). 1.""قَوَّمَ أوَدَهُ"" : قَوَّمَ اعْوِجَاجَهُ. 2.""قَامَ بِأَوَدِ عَائِلَتِهِ"" : قَامَ بِسَدِّ حَاجاتِهَا، إعَانَتِهَا وَإِعَالَتِهَا. 3.""يَبْحَثُ عَمَّا يُقِيمُ أوَدَهُ"" : مَا يَسُدُّ رَمَقَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18426, 'إِيدَاعٌ', 'إيداع', 'مصدر', 'ودع', 'ءيداع', 'إدع', 'مص. أَوْدَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِيدَاعٌ-إِيدَاعٌ [و د ع] (مص. أَوْدَعَ). 1.""إِيدَاعُ الْمَالِ"" : تَرْكُهُ وَدِيعةً. 2.""إِيدَاعُ السِّرِّ"" : البَوْحُ بِهِ وَالإِعْلاَنُ عَنْهُ. 3.""الإِيدَاعُ القَانُونِيُّ لِلْك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18427, 'إيرَادٌ', 'إيراد', 'مصدر', 'ورد', 'ءيراد', 'إرد', 'مص. أوْرَدَ', '', '', 'مفرد', 'DnN', '', '', '"إيرَادَاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. أوْرَدَ). 1.""إيرَادُ البَضَائِعِ مِنَ الخَارِجِ"" : جَلْبُهَا، اِسْتِيرَادُهَا. 2.""إيرَادَاتُ السُّوقِ"": مَدَاخِيلُهُ. ""إيرَادَاتُ الفُوسْفَاتِ وَالنَّفْطِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18428, 'إيرَادَاتٌ', 'إيرادات', 'مصدر', '', 'ءيرادات', 'إردت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18429, 'اِئْتِمَانٌ', 'ائتمان', 'مصدر', 'أمن', 'اءتمان', 'تمن', 'مص. اِئْتَمَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِئْتِمَانٌ-اِئْتِمَانٌ [أ م ن] (مص. اِئْتَمَنَ). 1.""اِئْتِمَانُ الرَّجُلِ"" : عَدُّهُ أَمِيناً. 2. ""أَرَادَ ائْتِمَانَهُ عَلَى مَالِهِ"" : اِتِّخَاذَهُ أمِيناً عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18430, 'إيصَالٌ', 'إيصال', 'مصدر', 'وصل', 'ءيصال', 'إصل', 'مص. أوْصَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إيصَالٌ-إيصَالٌ [و ص ل] (مص. أوْصَلَ). ""دَفَعَ مَبْلَغاً فَسَلَّمَهُ الْمُوَظَّفُ إيصَالاً"" : وَثِيقَةُ إثْبَاتٍ تَدُلُّ عَلَى أنَّهُ دَفَعَ مَبْلَغاً مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18431, 'إِيطَاءٌ', 'إيطاء', 'مصدر', 'وطأ', 'ءيطاء', 'إط', 'مص. أَوْطَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِيطَاءٌ-إِيطَاءٌ [و ط أ] (مص. أَوْطَأَ). ""فِي شِعْرِهِ إِيطَاءٌ"" : مِنْ عُيُوبِ الشِّعْرِ، أيْ أنْ تَتَكرَّرَ القَافِيةُ لَفظاً وَمَعْنىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18432, 'إيقَاعٌ', 'إيقاع', 'مصدر', 'وقع', 'ءيقاع', 'إقع', 'مص. أَوْقَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إيقَاعٌ-إيقَاعٌ [و ق ع] (مص. أَوْقَعَ). ""إِيقَاعٌ مُوسِيقِيٌّ"" : تَنَاغُمُ الأَصْوَاتِ وَتَوَافُقُهَا فِي الغِنَاءِ أَوِ العَزْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18433, 'إِيهَامٌ', 'إيهام', 'مصدر', 'وهم', 'ءيهام', 'إهم', 'مص. أوْهَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"إِيهَامٌ-إِيهَامٌ [و هـ م] (مص. أوْهَمَ). 1.""حَاوَلَ إيهَامَهُ"" : إيقَاعَهُ فِي الوَهْمِ. 2.""الإيهَامُ فِي النَّثْرِ أَوِ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18434, 'إِيواءٌ', 'إيواء', 'مصدر', 'أوي', 'ءيواء', 'إ', 'مص. آوَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"إِيواءٌ-إِيواءٌ [أ و ي] (مص. آوَى). ""أقَامَ بَيْتاً لإيوَاءِ الفُقَرَاءِ"": لإِسْكَانِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18435, 'اِئْتِكَالٌ', 'ائتكال', 'مصدر', 'أكل', 'اءتكال', 'تكل', 'مص. اِئْتَكَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِئْتِكَالٌ-اِئْتِكَالٌ [أ ك ل] (مص. اِئْتَكَلَ). ""اِئْتِكَالُ الدِّيدَانِ"" : أكْلُ بَعْضِهَا بَعْضًا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18436, 'اِئْتِلاَفٌ', 'ائتلاف', 'مصدر', 'أنف', 'اءتلاف', 'تلف', 'مص. اِئْتَلَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِئْتِلاَفٌ-اِئْتِلاَفٌ [أ ن ف] (مص. اِئْتَلَفَ). ""كَوَّنُوا ائْتِلاَفاً فِيمَا بَيْنَهُمْ"" : اِتِّحَاداً، تَحَالُفًا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18437, 'اِئْتِلاَقٌ', 'ائتلاق', 'مصدر', 'ألق', 'اءتلاق', 'تلق', 'مص. اِئْتَلَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِئْتِلاَقٌ-اِئْتِلاَقٌ [أ ل ق] (مص. اِئْتَلَقَ). ""اِئْتِلاَقُ البَرْقِ"" : لَمَعَانُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18438, 'اِئْتِمَارٌ', 'ائتمار', 'مصدر', 'أمر', 'اءتمار', 'تمر', 'مص. اِئْتمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"اِئْتِمَارٌ-اِئْتِمَارٌ [أ م ر] (مص. اِئْتمَرَ). 1.""الاِئْتِمَارُ فِي الأمْرِ"": الْمُشَاوَرَةُ فِيهِ. 2.""الاِئْتِمَارُ بِأمْرٍ"" : الخُضُوعُ لَهُ. 3. ""الاِئْتِمَارُ لِلسَّيِّدِ"" : الامْتِثَالُ لَهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18439, 'مُبَارَاةٌ', 'مباراة', 'مصدر', 'بري', 'مباراة', 'مبرة', 'مص. بَارَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبَارَاةٌ-مُبَارَاةٌ [ب ر ي] (مص. بَارَى). 1.""حَضَرَ مُبَارَاةً رِيَاضِيَّةً"" : مُسَابَقَةً، مُنَافَسَةً، لُعْبَةً رِيَاضِيَّةً، فُرْصَةً. ""مُبَارَاةٌ فِي كُرَةِ القَدَم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18440, 'تَأْيِيدٌ', 'تأييد', 'مصدر', 'أيد', 'تءييد', 'تد', 'مص. أَيَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأْيِيدٌ-تَأْيِيدٌ [أ ي د] (مص. أَيَّدَ). 1.""وَجَدَ عِنْدَهُ كُلَّ تَأْيِيدٍ"": كُلَّ مُوَافَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18441, 'مَبِيتٌ', 'مبيت', 'مصدر', 'بيت', 'مبيت', 'مبت', 'مص. بَاتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَبِيتٌ-مَبِيتٌ [ب ي ت] (مص. بَاتَ). ""اِلْتَجَأَ إِلَى مَبِيتٍ فِي الجَبَلِ"" : مَسْكَنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18442, 'مُبَاحَثَةٌ', 'مباحثة', 'مصدر', 'بحث', 'مباحثة', 'مبحثة', 'مص. بَاحَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. بَاحَثَ). ""أَجْرَى مُبَاحَثَةً مَعَ زَمِيلِهِ"" : حِوَاراً، نِقَاشاً، بَحْثاً. ""جَرَتْ مُباحثَاتٌ هامَّةٌ بَيْنَ الرَّئيسَيْنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18443, 'مُبَادَرَةٌ', 'مبادرة', 'مصدر', 'بدر', 'مبادرة', 'مبدرة', 'مص. بَادَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. بَادَرَ). 1.""جَاءتْ مُبَادَرَتُهُ فِي مَحَلِّهَا"" : السَّبْقُ إِلَى اتِّخَاذِ قَرَارٍ أَوِ تَحْقِيقِ أَمْرٍ مَّا. 2.""فِي يَدِهِ زِمَامُ الْمُبَادَرَةِ"" : أَيْ أَنَّ الأَمْرَ مُفَوَّضٌ إِلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18444, 'مُبَادَلَةٌ', 'مبادلة', 'مصدر', 'بدل', 'مبادلة', 'مبدلة', 'مص. بَادَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. بَادَلَ). ""مُبَادَلَةُ شَيْءٍ بِشَيْءٍ"" : تَبَادُلُهُ. ""مُبَادَلاَتٌ تِجَارِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18445, 'بَوَارٌ', 'بوار', 'مصدر', 'بور', 'بوار', 'بر', 'مص. بَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَوَارٌ-بَوَارٌ [ب و ر]. (مص. بَارَ). 1.""يَعْرِفُ السُّوقُ بَوَاراً هَذِهِ الأيَّامَ"" : كَسَاداً. 2. ""بَوَارُ الفَتَاةِ"" : بَقَاؤُهَا عَانِساً. ""وَلَمْ تَكُنِ الأمُّ فِي الوَاقِعِ يُدَاخِلُهَا خَوْفٌ عَلَى الفتَاةِ مِنَ البَوَارِ"".(ن. محفوظ) 3."" أرْضُ بَوَارٍ لاَ زَرْعَ فِيهَا"" : الأرْضُ الَّتِي لَمْ تُزْرَعْ. 4."" دَارُ البَوَارِ"" : الجَحِيمُ. إبراهيم آية 28 وَأَحَلُّوا قَوْمَهُمْ دَارَ البَوَارِ .(قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18446, 'مُبَارَزَةٌ', 'مبارزة', 'مصدر', 'برز', 'مبارزة', 'مبرزة', 'مص. بَارَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. بَارَزَ). 1.""مُبَارَزَةٌ رِيَاضِيَّةٌ"" : مُبَارَاةٌ، سِبَاقٌ. 2.""الْمُبَارَزَةُ بِالشِّي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18447, 'بِرازٌ', 'براز', 'مصدر', 'برز', 'براز', 'برز', 'مص. بارَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بِرازٌ-بِرازٌ [ب ر ز] (مص. بارَزَ). 1.""خَرَجَ إلى بِرازِهِ"" : إلى مُقاتَلَتِهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18448, 'مُبَارَكَةٌ', 'مباركة', 'مصدر', 'برك', 'مباركة', 'مبركة', 'مص. بَارَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبَارَكَةٌ-مُبَارَكَةٌ [ب ر ك] (مص. بَارَكَ). ""مُبَارَكَةُ العَمَلِ"" : تَزْكِيَتُهُ وَجَعْلُهُ خَيْراً وَنَمَاءً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18449, 'مُبَايَعَةٌ', 'مبايعة', 'مصدر', 'بيع', 'مبايعة', 'مبعة', 'مص. بَايَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. بَايَعَ). 1.""مُبَايَعَةُ البَيْعِ"" : عَقْدُ البَيْعِ. 2.""مُبَايَعَةُ الْمَلِكِ"" : تَقْدِيمُ البَيْعَةِ القَائِمَةِ عَلَى العَهْدِ وَالوَفَاءِ وَقَبُولِ وِلاَيَتِهِ أَوْ خِلاَفَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18450, 'مُبَاشَرَةٌ', 'مباشرة', 'مصدر', 'بشر', 'مباشرة', 'مبشرة', 'مص. بَاشَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبَاشَرَةٌ-مُبَاشَرَةٌ [ب ش ر] (مص. بَاشَرَ). 1.""يَنْهَضُ صَبَاحاً لِمُبَاشَرَةِ عَمَلِهِ"" : لِمُزَاوَلَتِهِ. 2.""نَزَلَ إِلَى البَيْتِ مُبَاشَرَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18451, 'مُبَاغَتَةٌ', 'مباغتة', 'مصدر', 'بغث', 'مباغتة', 'مبغتة', 'مص. بَاغَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبَاغَتَةٌ-مُبَاغَتَةٌ [ب غ ث] (مص. بَاغَتَ). ""مُبَاغَتَةُ العَدُوِّ"" : مُفَاجَأَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18452, 'بَوْلٌ', 'بول', 'مصدر', 'بول', 'بول', 'بل', 'مص. بَالَ', '', '', 'مفرد', 'DnN', '', '', '"أَبْوَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. بَالَ). ""كَثُرَ بَوْلُهُ"" : الْمَاءُ الَّذِي نَشْرَبُهُ وَتَقُومُ الكُلْيَتانِ بِإِفْرَازِهِ، وَيَصِلُ إلَى الْمَتَانَةِ، وَيَخْرُجُ مِنَ العُضْوِ التَّنَاسُلِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18453, 'أَبْوَالٌ', 'أبوال', 'مصدر', '', 'ءبوال', 'بل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18454, 'مُبَالَغَةٌ', 'مبالغة', 'مصدر', 'بلغ', 'مبالغة', 'مبلغة', 'مص. بَالَغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. بَالَغَ). 1.""الْمُبَالَغَةُ فِي الكَلاَمِ"" : أَيْ تَجَاوُزُ الْح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18455, 'مُبَالاَةٌ', 'مبالاة', 'مصدر', 'بلى', 'مبالاة', 'مبلة', 'مص. بَالَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبَالاَةٌ-مُبَالاَةٌ [ب ل ى] (مص. بَالَى). 1.""الْمُبَالاَةُ بِالأَحْدَاثِ"" : التَّأَثُّرُ وِالاهْتِمَام"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18456, 'بَيَانٌ', 'بيان', 'مصدر', 'بين', 'بيان', 'بن', 'مص. بان', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَيَانٌ-بَيَانٌ [ب ي ن] (مص. بان). 1.""صَدَرَ بَيَانٌ"" : بَلاغٌ. 2.""بَيَانُ حَقِيقَةٍ"" : تَوْضِيحٌ لِلْكَشْفِ وإظْهَارِ الحَقِيقَةِ. 3.""مَنِ ادَّعَى فَعَلَيْهِ البَيَانُ"" : أيْ عَلَيْهِ الإثْبَاتُ بِالدَّلِيلِ. 4.""تَحَدَّثَ بِبَيَانٍ بَلِيغٍ"" : بِفَصَاحَةٍ، بِبَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18457, 'بَيْنٌ', 'بين', 'مصدر', 'بين', 'بين', 'بن', 'مص. بانَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَيِّنٌ-بَيِّنٌ [ب ي ن]. ""تَكَلَّمَ بِكَلامٍ بَيِّنٍ"" : واضِحٍ. ""كانَ فُضولُهُ يَخْتَلِفُ عَنْ فُضولِهِمُ اخْتِلافاً بَيِّناً"". (ع. غلاب)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18458, 'مُبَاهَاةٌ', 'مباهاة', 'مصدر', 'بهي', 'مباهاة', 'مبهة', 'مص. بَاهَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُبَاهَاةٌ-مُبَاهَاةٌ [ب هـ ي] (مص. بَاهَى). ""أَظْهَرَ مُبَاهاةً لاَ حَدَّ لَهَا"" : تَفَاخُراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18459, 'بَداءةٌ', 'بداءة', 'مصدر', 'بدأ', 'بداءة', 'بدة', 'مص. بَدَأ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"بَداءةٌ-بَداءةٌ [ب د أ] (مص. بَدَأ) 1.""بَدَاءةُ الدَّوْلَةِ"" : نشْأتُها. 2.""لكَ البَدَاءةُ"" : لَكَ البَدْءُ. 3.""عَلَى البَدَاءةِ"" : عَلَى البَدَاهَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18460, 'بَتْرٌ', 'بتر', 'مصدر', 'بتر', 'بتر', 'بتر', 'مص. بَتَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَتْرٌ-بَتْرٌ [ب ت ر] (مص. بَتَرَ). ""آلَمَهُ بَتْرُ عُضْوٍ مِنْ أعْضائِهِ"" : قَطْعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18461, 'بَثٌّ', 'بث', 'مصدر', 'بثث', 'بث', 'بث', 'مص. بَثَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَثٌّ-بَثٌّ [ب ث ث] (مص. بَثَّ). ""بَثٌّ إذَاعِيٌّ"" : إرْسَالٌ بِوَاسِطَةِ الأمْواجِ الإذاعِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18462, 'بَثْرٌ', 'بثر', 'مصدر', 'بثر', 'بثر', 'بثر', 'مص. بَثَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَثْرٌ-بَثْرٌ [ب ث ر] (مص. بَثَرَ). ""بِوَجْهِهِ بَثْرٌ"" : جِراحٌ، بُروزُ دُمَّلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18463, 'بَحْتٌ', 'بحت', 'مصدر', 'بحت', 'بحت', 'بحت', 'مص. بَحَتَ', '', '', 'مفرد', '', '', '', '"لمذكروالمؤنثوالمثنىوالجمع"', '', 'R', '', '', '', '', '', '', '"بَحْتٌ-بَحْتٌ [ب ح ت] (مص. بَحَتَ). للمذكر والمؤنث والمثنى والجمع. 1."" هُوَ عَربِيٌّ بَحْثٌ"" : خَالِصٌ، غَيْرُ دَخِيلٍ. 2.""عَصِيرٌ بَحْتٌ"" : خالِصٌ، غَيْرُ مَمْزوجٍ. 3.""ظُلْمٌ بَحْتٌ"" : صَرِيحٌ واضِحٌ. ""كَذِبٌ بَحْتٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18464, 'بَحْثٌ', 'بحث', 'مصدر', 'بحث', 'بحث', 'بحث', 'مص. بَحَثَ', '', '', 'مفرد', 'DnN', '', '', '"أَبْحاثٌ:بُحوثٌ"', '', 'R', '', '', '', '', '', '', '"(مص. بَحَثَ). 1.""مازالَ البَحْثُ عَنِ البِتْرُولِ مُسْتَمِرّاً"" : التَّنْقِيب. 2.""أنْجَزَ بَحْثاً حَوْلَ الحَيَوانَاتِ الأليفَةِ"" : دِراسَةً. 3.""قَضِيَّتُكَ تَحْتَ البَحْثِ"" : تَحْتَ الدَّرْسِ. 4.""كانَ هدَفُهُ هُو البَحْثُ عَنِ الحَقِيقَةِ"" : مَعْرِفَةُ الحَقِيقَةِ، تَحَرِّيها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18465, 'أَبْحاثٌ', 'أبحاث', 'مصدر', '', 'ءبحاث', 'بحث', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18466, 'بُحوثٌ', 'بحوث', 'مصدر', '', 'بحوث', 'بحث', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18467, 'بَخْسٌ', 'بخس', 'مصدر', 'بخس', 'بخس', 'بخس', 'مص. بَخَسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَخْسٌ-بَخْسٌ [ب خ س] (مص. بَخَسَ). 1.""اِشْتَرَى مِعْطَفاً بِثَمَنٍ بَخْسٍ"" : بَسِيطٍ جِدّاً، زَهِيدٍ.يوسف آية 20 وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ ( قرآن). 2.الجن آية 13 فَلا يَخافُ بَخْساً وَلا رَهَقاً . (قرآن) : فَلاَ يَخافُ نُقْصان الحَقِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18468, 'بُخْلٌ', 'بخل', 'مصدر', 'بخل', 'بخل', 'بخل', 'مص. بَخِلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بُخْلٌ-بُخْلٌ [ب خ ل] (مص. بَخِلَ). ""ما هَذا البُخْلُ يا رَجُلُ"" : ما هَذا الشُّحُّ والتَّقْتيرُ ""بُخْلُكَ لَم أرَ لَهُ مَثِيلاً"" النساء آية 37 وَيَأْمُرونَ النَّاسَ بالبُخْلِ وَيَكْتُمونَ ما آتاهُمُ اللَّهُ مِنْ فَضْلِهِ ( قرآن). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18469, 'بَذاءةٌ', 'بذاءة', 'مصدر', 'بذأ', 'بذاءة', 'بذة', 'مص. بَذَأَ، بَذُؤَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"بَذاءةٌ-بَذاءةٌ [ب ذ أ] (مص. بَذَأَ، بَذُؤَ). ""يا لَها مِنْ بَذاءٍ ! أَلَمْ تَسْتَحْيِ"" : الكَلامُ الفاحِشُ الصَّادِرُ عَنِ السَّفِيهِ، الفُحْشُ. ""عُرِفَ بِبَذاءةِ لِسانِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18470, 'بَدَاوَةٌ', 'بداوة', 'مصدر', 'بدو', 'بداوة', 'بدة', 'مص. بَدَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَدَاوَةٌ-بَدَاوَةٌ [ب د و] (مص. بَدَا). 1.""مازَالتْ مَناطِقُ كَثِيرَةٌ تَعيشُ فِي بَدَاوَةٍ"" : عِيشَةُ أهْلِ البَدْوِ، فِي تنَقُّلٍ وَتَرْحَالٍ، عَكْسَ الحَضارَةِ. 2.""بَدَاوَةُ الأمْرِ"" : أوَّلُ ما يَبْدُو مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18471, 'تبدبدٌ', 'تبدبد', 'مصدر', 'بدد', 'تبدبد', 'تبدبد', 'مص. بدد', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18472, 'بَدْرٌ', 'بدر', 'مصدر', 'بدر', 'بدر', 'بدر', 'مص. بَدَرَ', '', '', 'مفرد', 'DnN', '', '', '"بُدورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. بَدَرَ). 1.""طَلَعَ البَدْرُ عَلَيْنَا"" : طَلَعَ القَمَرُ لَيْلَةَ كَمَالِهِ. 2. ""ليْلَةُ البَدْرِ"" : لَيْلَةُ أربَعَ عَشْرَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18473, 'بُدورٌ', 'بدور', 'مصدر', '', 'بدور', 'بدر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18474, 'تَبْدِيلٌ', 'تبديل', 'مصدر', 'بدل', 'تبديل', 'تبدل', 'مص. بَدَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبْدِيلٌ-تَبْدِيلٌ [ب د ل] (مص. بَدَّلَ). ""لاَ تَبْدِيلَ فِي أَوْقَاتِ العَمَلِ"": لاَ تَغْيِيرَ.يونس آية 64 لاَ تَبْدِيلَ لِكَلِمَاتِ اللهفاطر آية 43 فَلَنْ تَجِدَ لِسُنَّةِ اللهِ تَبْدِيلا (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18475, 'بَدَلٌ', 'بدل', 'مصدر', 'بدل', 'بدل', 'بدل', 'مص. بَدِلَ', '', '', 'مفرد', 'DnN', '', '', '"أَبْدَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. بَدِلَ). 1. ""هَذَا بَدَلُ ذَاكَ"" : عِوَضُهُ، خَلَفُهُ. ""بَدَلاً مِنَ النُّزْهَةِ سَأَمْكُثُ فِي الْبَيْتِ للِدَّرْسِ"". 2.""هُوَ بَدَلٌ"" : شَرِيفٌ، كَرِيمٌ. 3.""أَلَمَّ بِهِ الْبَدَلُ"" : أَلَمُ الْمَفَاصِلِ وَالْعِظَامِ وَالْيَدَيْنِ وَالرِّجْلَيْنِ. 4.""الْبَدَلُ فِي النَّحْوِ"": هُوَ أَحَدُ التَّوَابِعِ الَّذِي يَتْبَعُ مَا قَبْلَهُ فِي الإِعْرَابِ، وَهُوَ الْمَقْصُودُ بِالحُكْمِ بِلاَ وَاسِطَةٍ : ""أَمَرَ الْخَلِيفَةُ عُمَرُ"" ""قَالَ الشَّيْخُ الْفَيْلَسُوفُ"" ""وَصَلَتِ الْفَتَاةُ الْهَيْفَاءُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18476, 'أَبْدَالٌ', 'أبدال', 'مصدر', '', 'ءبدال', 'بدل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18477, 'بَدَانَةٌ', 'بدانة', 'مصدر', 'بدن', 'بدانة', 'بدنة', 'مص. بَدُنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَدَانَةٌ-بَدَانَةٌ [ب د ن] (مص. بَدُنَ). ""عَرَفَ بَدانَةً فِي الشُّهورِ الأَخِيرَةِ"" : ضَخامَة البَدَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18478, 'بَدَاهَةٌ', 'بداهة', 'مصدر', 'بده', 'بداهة', 'بدهة', 'مص. بَدَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَدَاهَةٌ-بَدَاهَةٌ [ب د هـ] (مص. بَدَهَ). 1.""كَان يُجِيبُ بِبَدَاهَةٍ"" : تِلْقائِيّاً. 2.""عَقْلٌ ذُو بَدَاهَةٍ لِلْجَمِيعِ"" : أي مُفاجَأةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18479, 'بَرَصٌ', 'برص', 'مصدر', 'برص', 'برص', 'برص', 'مص. بَرَصَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَرَصٌ-بَرَصٌ [ب ر ص] (مص. بَرَصَ). : مَرَضٌ، وَهُوَ عِبارَةٌ عَنْ بُقَعٍ بِيضٍ تَظْهَرُ على الجِلْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18480, 'تَبْذِيرٌ', 'تبذير', 'مصدر', 'بذر', 'تبذير', 'تبذر', 'مص. بَذَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبْذِيرٌ-تَبْذِيرٌ [ب ذ ر] (مص. بَذَّرَ). ""الاجْتِهَادُ فِي الكَفَافِ خَيْرٌ مِنَ الإِسْرَافِ وَالتَّبْذِيرِ"" : صَرْفُ الْمَالِ فِيمَا لاَ فَائِدَةَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18481, 'بَذْلٌ', 'بذل', 'مصدر', 'بذل', 'بذل', 'بذل', 'مص. بَذَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَذْلٌ-بَذْلٌ [ب ذ ل] (مص. بَذَلَ). 1.""لابُدَّ لَهُ مِنْ بَذْلِ جُهْدٍ كَبيرٍ لِيُحَقِّقَ مُبْتَغاهُ"" : سَعْيٌ، صَرْفٌ. 2.""بَذْلُ النَّفْسِ"" : التَّضْحِيَةُ، العَطاءُ، التَّفانِي والإِخْلاصُ. ""يَتَمَيَّزُ العَرَبُ بِالبَذْلِ والسَّخاءِ"". (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18482, 'بَرٌّ', 'بر', 'مصدر', 'برر', 'بر', 'بر', 'مص. بَرَّ', '', '', 'مفرد', 'DnN', '', '', '"أَبْرارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. بَرَّ). 1.""كانَ بَرّاً في قَوْلِهِ"" : صادِقاً. 2.""هُوَ البَرُّ الرَّحيمُ"" : مِنْ أَسْما"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18483, 'أَبْرارٌ', 'أبرار', 'مصدر', '', 'ءبرار', 'برر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18484, 'بِرٌّ', 'بر', 'مصدر', 'برر', 'بر', 'بر', 'مص. بَرَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بِرٌّ-بِرٌّ [ب ر ر] (مص. بَرَّ). 1.""البِرُّ بِالوالِدَيْنِ"" : الإِحْسانُ، الطَّاعَةُ. 2. البقرة آية177لَيْسَ البِرَّ أَنْ تُوَلُّوا وُجوهَكُمْ قِبَلَ الْمَشْرِقِ والْمَغْرِبِ وَلكِنَّ البِرَّ مَنْ آمَنَ بِاللَّهِ . ("', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18485, 'تَبْرِيدٌ', 'تبريد', 'مصدر', 'برد', 'تبريد', 'تبرد', 'مص. بَرَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبْرِيدٌ-تَبْرِيدٌ [ب ر د] (مص. بَرَّدَ). ""اِسْتَخْدَمَ جِهَازَ التَّبْرِيدِ للتَّخْفِيفِ مِنْ شِدَّةِ الحَرَارَةِ"" : جِهَازٌ آلِيٌّ يُوَلِّدُ البُرُودَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18486, 'بَرْدٌ', 'برد', 'مصدر', 'برد', 'برد', 'برد', 'مص. بَرَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَرْدٌ-بَرْدٌ [ب ر د] (مص. بَرَدَ). 1.""كانَ البَرْدُ قارِساً فَوْقَ الجَبَلِ"" : أَيْ طَقْسٌ بارِدٌ، "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18487, 'تَبْرِيرٌ', 'تبرير', 'مصدر', 'برر', 'تبرير', 'تبرر', 'مص. بَرَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبْرِيرٌ-تَبْرِيرٌ [ب ر ر] (مص. بَرَّرَ). ""حَاوَلَ تَبْرِيرَ سُلُوكِهِ"" : أَيْ تَعْلِيلَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18488, 'بروزٌ', 'بروز', 'مصدر', 'برز', 'بروز', 'برز', 'مص. برز', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18489, 'بَسالَةٌ', 'بسالة', 'مصدر', 'بسل', 'بسالة', 'بسلة', 'مص. بَسُلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَسالَةٌ-بَسالَةٌ [ب س ل] (مص. بَسُلَ). ""أَظْهَرَ بَسالَةً في الْمَعْرَكَةِ"" : شَجاعَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18490, 'بَراعَةٌ', 'براعة', 'مصدر', 'برع', 'براعة', 'برعة', 'مص. بَرَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَراعَةٌ-بَراعَةٌ [ب ر ع] (مص. بَرَعَ). 1.""قَدَّمَ عَرْضاً رِيَاضِيّاً فيهِ بَراعَةٌ"" : فيهِ كَمالٌ وَإِتْقا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18491, 'بَريقٌ', 'بريق', 'مصدر', 'برق', 'بريق', 'برق', 'مص. بَرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَريقٌ-بَريقٌ [ب ر ق] (مص. بَرَقَ). 1.""كانَ يَرَى في ذَلِكَ بَريقَ أَمَلٍ"" : شُعاعٌ، وَميضٌ، بَصيصٌ، ضَوْءٌ خافِتٌ. 2.""كُنْتُ أَرَى في بَريقِ عَيْنَيْهِ انْدِهاشاً"" : في لَمَعانِهِما."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18492, 'بَرْمَجَةٌ', 'برمجة', 'مصدر', 'برمج', 'برمجة', 'برمجة', 'مص. بَرْمَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَرْمَجَةٌ-بَرْمَجَةٌ (مص. بَرْمَجَ). ""بَرْمَجَةُ البَرامِجِ التَّعْلِيمِيَّةِ"" : أَي إِدْخالُها حَسَبَ نَهْجٍ مَعْلومٍ في الحاسوبِ أَوْ إِدْخالُها ضِمْنَ خُطَّةٍ مَعْلومَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18493, 'بَراءةٌ', 'براءة', 'مصدر', 'برأ', 'براءة', 'برة', 'مص. بَرِيءٌ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"(مص. بَرِيءٌ). 1.""حَكَمَتْ عَليْهِ الْمَحْكَمَةُ بِالبَراءةِ"" : خَلَّصَتْهُ مِنَ التُّهْمَةِ الْمُوَجَّهَةِ إِلَيْهِ. ""أَنْتَ أَوْلَى النَّاسِ بِالصَّفْحِ عَنِّي إِذا عَرَفْتَ بَراءتِي"".(التوحيدي) ""حُكْمُ بَراءةٍ"". 2.""تَسَلَّمَ بَرَاءةَ الاخْتِراعِ"" : شَهادَةٌ تُسَلَّمُ لِلْمُخْتَرِعِ حِفْظاً لِحُقوقِهِ. 3.""اِرْتَدَّ إلى بَراءةِ الطُّفولَةِ وَبَهْجَتِها"" : العَفَوِيَّة، البَساطَة، السَّذَاجَة ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18494, 'براءٌ', 'براء', 'مصدر', 'برأ', 'براء', 'بر', 'مص. بَرِيءٌ', '', '', 'مفرد', '', '', '', '"لايثنى:لايجمعولايؤنث"', '', 'Rz', '', '', '', '', '', '', '"هو براءٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18495, 'بَراءٌ', 'براء', 'مصدر', 'برأ', 'براء', 'بر', 'مص. بَرِئَ ', '', '', 'مفرد', '', '', '', '"(يوصَفُبِهِ:لاَيُثَنَّىوَلاَي', '', 'Rz', '', '', '', '', '', '', '"بَراءٌ-بَراءٌ [ب ر أ] (مص. بَرِئَ) (يوصَفُ بِهِ، لاَ يُثَنَّى وَلاَ يُجْمَعُ وَلاَ يُؤَنَّثُ). 1.""أَنا مِنْهُ بَراءٌ"" : أَيْ بَريءٌ. الزخرف آية 26إِنَّنِي بَراءٌ مِمَّا تَعْبُدونَ . (قرآن). 2.""لَيْلَةُ البَراءِ"" : أَوَّلُ يَوْمٍ مِنَ الشَّهْرِ، آخِرُ لَيَالِي الشَّهْرِ، آخِرُ يَوْمٍ مِنَ الشَّهْرِ. ""لَوْ كَانَ البَراءُ لَهُمْ نَحْساً لَفَرَّقَهُمْ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18496, 'تَبْسِيطٌ', 'تبسيط', 'مصدر', 'بسط', 'تبسيط', 'تبسط', 'مص. بَسَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبْسِيطٌ-تَبْسِيطٌ [ب س ط] (مص. بَسَّطَ). 1. ""عَمِلَ الْمُعَلِّمُ عَلَى تَبْسِيطِ الدَّرْسِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18497, 'بَسْطٌ', 'بسط', 'مصدر', 'بسط', 'بسط', 'بسط', 'مص. بَسَطَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَسْطٌ-بَسْطٌ [ب س ط] (مص. بَسَطَ). 1.""عُرِفَ بِبَسْطِهِ"" : بانْشِراحِهِ وَضَحِكِهِ. 2.""لَمْ يَتَمَكَّنْ مِنْ بَسْطِ آرائِهِ"" : مِنْ عَرْضِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18498, 'بَساطَةٌ', 'بساطة', 'مصدر', 'بسط', 'بساطة', 'بسطة', 'مص. بَسُطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَساطَةٌ-بَساطَةٌ [ب س ط] (مص. بَسُطَ). 1.""يَعيشُ في بَساطَةٍ كامِلَةٍ"" : حَياة "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18499, 'بَشاشَةٌ', 'بشاشة', 'مصدر', 'بشش', 'بشاشة', 'بششة', 'مص. بَشَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَشاشَةٌ-بَشاشَةٌ [ب ش ش] (مص. بَشَّ). ""ظَهَرَتْ عَلَى وَجْهِهِ بَشاشَةٌ"" : لُطْفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18500, 'بَشٌّ', 'بش', 'مصدر', 'بشش', 'بش', 'بش', 'مص. بَشَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَشٌّ-بَشٌّ [ب ش ش] (مص. بَشَّ). ""كانَ بَشَّ الوَجْهِ"" : طَلْقاً مُبْتَسِماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18501, 'تَبْشِيرٌ', 'تبشير', 'مصدر', 'بشر', 'تبشير', 'تبشر', 'مص. بَشَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبْشِيرٌ-تَبْشِيرٌ [ب ش ر] (مص. بَشَّرَ). 1.""جَاءَ لِتَبْشِيرِهِ باِلخَبَرِ السَّارِّ"" : تَبْلِيغُ الْمَسَرَّةِ، نَقْلُ الخَبَرِ السَّارِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18502, 'بِشْرٌ', 'بشر', 'مصدر', 'بشر', 'بشر', 'بشر', 'مص. بَشَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بِشْرٌ-بِشْرٌ [ب ش ر] (مص. بَشَرَ). 1.""اِسْتَقْبَلَهُ بِبِشْرٍ"" : بِوَجْهٍ طَلْقٍ وَبَشاشَةٍ. 2.""هُوَ حَسَنُ البِشْرِ"" : طَلْقُ الوَجْهِ جَمِيلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18503, 'بَشارَةٌ', 'بشارة', 'مصدر', 'بشر', 'بشارة', 'بشرة', 'مص. بَشُرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بِشارَةٌ-بِشارَةٌ [ب ش ر] (مص. بَشُرَ). 1.""جاءَ يَحْمِلُ إِلَيْهِ البِشارَةَ"" : الإِنْجيل. 2."""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18504, 'بِشارَةٌ', 'بشارة', 'مصدر', 'بشر', 'بشارة', 'بشرة', 'مص. بَشُرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَشارَةٌ-بَشارَةٌ [ب ش ر] (مص. بَشُرَ). 1.""كانتْ بَشارَتُها مُتَمَيِّزَةً"" : جَمالُها، حُسْنُها. 2.""بَشائِرُ الوَجْهِ"" : مُحَسِّناتُهُ، نَظَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18505, 'بَشاعَةٌ', 'بشاعة', 'مصدر', 'بشع', 'بشاعة', 'بشعة', 'مص. بَشِعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَشاعَةٌ-بَشاعَةٌ [ب ش ع] (مص. بَشِعَ). ""كانَتْ بَشاعَةُ مَنْظَرِهِ لاَ تُحْتَمَلُ"" : قُبْحُهُ، خُشونَتُهُ. ""تَكَشَّفَتْ لهُ الحَقائِقُ بِبَشاعَتِها"".(ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18506, 'بَصيصٌ', 'بصيص', 'مصدر', 'بصص', 'بصيص', 'بصص', 'مص. بَصَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَصيصٌ-بَصيصٌ [ب ص ص] (مص. بَصَّ). 1.""كانَ يَرَى في ذَلِكَ بَصيصَ أَمَلٍ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18507, 'بَصَرٌ', 'بصر', 'مصدر', 'بصر', 'بصر', 'بصر', 'مص. بَصُرَ، بَصِرَ', '', '', 'مفرد', 'DnN', '', '', '"أَبْصارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. بَصُرَ، بَصِرَ). 1.""أُصيبَ في بَصَرِهِ وَهُوَ صَغيرٌ"" : أُصيبَ في عَيْنَيْهِ. 2.""لَهُ بَصَرٌ حادٌّ"" : نَظَرٌ قَوِيٌّ، حاسَّةُ النَّظَرِ. 3.""لاَبُدَّ لَهُ مِنْ نَظَّارَةٍ، فَهُوَ قَصيرُ البَصَرِ، لاَ يَبْصُرُ ما هُوَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18508, 'أَبْصارٌ', 'أبصار', 'مصدر', '', 'ءبصار', 'بصر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18509, 'بَضٌّ', 'بض', 'مصدر', 'بضض', 'بض', 'بض', 'مص. بَضَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَضٌّ-بَضٌّ، ةٌ [ب ض ض] (مص. بَضَّ). 1.""لَها بَشَرَةٌ بَضَّةٌ"": نَضِرَةٌ، صافِيَةٌ. 2.""بَضَّةُ الجِسْم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18510, 'بَضَّةٌ', 'بضة', 'مصدر', 'بضض', 'بضة', 'بضة', 'مص. بَضَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَضٌّ-بَضٌّ، ةٌ [ب ض ض] (مص. بَضَّ). 1.""لَها بَشَرَةٌ بَضَّةٌ"": نَضِرَةٌ، صافِيَةٌ. 2.""بَضَّةُ الجِسْم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18511, 'بَطْشٌ', 'بطش', 'مصدر', 'بطش', 'بطش', 'بطش', 'مص. بَطَشَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَطْشٌ-بَطْشٌ [ب ط ش] (مص. بَطَشَ). 1.""أَظْهَرَ بَطْشاً هائِلاً"" : بَسالَةً. 2.""كانَ بَطْشُهُ واضِحاً"" : ظُلْمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18512, 'بُطْلٌ', 'بطل', 'مصدر', 'بطل', 'بطل', 'بطل', 'مص. بَطَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بُطْلٌ-بُطْلٌ [ب ط ل] (مص. بَطَلَ). 1.""بُطْلاً ما كانَ يَحْكيهِ"" : كَذِباً. 2.""ذَهَبَ بُطْلاً"" : عَبَثاً وَضَياعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18513, 'بُطولَةٌ', 'بطولة', 'مصدر', 'بطل', 'بطولة', 'بطلة', 'مص. بَطَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بُطولَةٌ-بُطولَةٌ [ب ط ل] (مص. بَطَلَ). 1.""أَظْهَرَ بُطولَةً"" : شَجاعَةً. 2.""أَحْرَزَ الفَريقُ الوَطَنِيُّ على بُطولَةِ كَأْسِ الأُمَمِ"" : مُباراةٌ رِياضِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18514, 'بِطالَةٌ', 'بطالة', 'مصدر', 'بطل', 'بطالة', 'بطلة', 'مص. بَطَلَ، بَطُلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بِطالَةٌ-بِطالَةٌ [ب ط ل] (مص. بَطَلَ، بَطُلَ). ""يَعيشُ في بِطالَةٍ مُنْذُ شَهْرٍ"" : بِلا عَمَلٍ، أَيْ تَعَطَّلَ عَنِ العَمَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18515, 'بُطْءٌ', 'بطء', 'مصدر', 'بطأ', 'بطء', 'بط', 'مص. بَطُؤَ', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"بُطْءٌ-بُطْءٌ [ب ط أ] (مص. بَطُؤَ). ""على بُطْءٍ"" : عَلَى مَهْلٍ. ""رَفَعَتْ رَأْسَها في بُطْءٍ"". (ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18516, 'بَغْتَةٌ', 'بغتة', 'مصدر', 'بغت', 'بغتة', 'بغتة', 'مص. بَغَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَغْتَةٌ-بَغْتَةٌ [ب غ ت] (مص. بَغَتَ). ""جاءهُ بَغْتَةً"" : فَجْأةً، على غِرَّةٍ. ""على بَغْتَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18517, 'بُغْضٌ', 'بغض', 'مصدر', 'بغض', 'بغض', 'بغض', 'مص. بَغَضَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بُغْضٌ-بُغْضٌ [ب غ ض] (مص. بَغَضَ). ""نَظَرَ إِلَيْهِ نَظْرَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18518, 'بِغاءٌ', 'بغاء', 'مصدر', 'بغي', 'بغاء', 'بغ', 'مص. بَغَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"بِغاءٌ-بِغاءٌ [ب غ ي] (مص. بَغَى). ""وَضَعَ حَدّاً لانْتِشارِ البِغاءِ"" : الفَسادِ، الزِّنَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18519, 'بَلْبَلَةٌ', 'بلبلة', 'مصدر', 'بلبل', 'بلبلة', 'بلبلة', 'مص. بَلْبَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَلْبَلَةٌ-بَلْبَلَةٌ [ب ل ب ل] (مص. بَلْبَلَ). ""أَحْدَثَ في صُفوفِهِمُ البَلْبَلَةَ"" : الارْتِباكَ وَالتَّشْوِيشَ والفَوْضَى. ""وَسادَتْ بَيْنَهُمْ بَلْبَلَةٌ لا أَوَّلَ لَها ولا آخِرَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18520, 'بَغْيٌ', 'بغي', 'مصدر', 'بغي', 'بغي', 'بغ', 'مص. بَغَى', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"بَغْيٌ-بَغْيٌ [ب غ ي] (مص. بَغَى). 1."" أَتَى البَغْيَ"": الجَوْرَ، الظُّلْمَ. النحل آية 90وَيَنْهى عَنِ الفَحْشاءِ والْمُنْكَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18521, 'بُغْيَةٌ', 'بغية', 'مصدر', 'بغي', 'بغية', 'بغة', 'مص. بَغَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"بُغْيَةٌ-بُغْيَةٌ [ب غ ي] (مص. بَغَى). 1.""حَقَّقَ لَهُ بُغْيَتَهُ"" : ما كانَ يَرْغَبُ فيهِ وَيَطْلُبُهُ، ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18522, 'بَقْبَقَةُ', 'بقبقة', 'مصدر', 'بقب', 'بقبقة', 'بقبقة', 'مص. بَقْبَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. بَقْبَقَ). 1.""بَقْبَقَةُ الماءِ"" : الصَّوْتُ الصَّادِرُ عَنِ انْسِكا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18523, 'بَقاءٌ', 'بقاء', 'مصدر', 'بقي', 'بقاء', 'بق', 'مص. بَقِيَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"بَقاءٌ-بَقاءٌ [ب ق ي] (مص. بَقِيَ). 1.""لا تُريدُ البَقاءَ في البَيْتِ"" : المُكوثَ، الثَّباتَ فيهِ. 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18524, 'تَبْكِيتٌ', 'تبكيت', 'مصدر', 'بكت', 'تبكيت', 'تبكت', 'مص. بَكَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبْكِيتٌ-تَبْكِيتٌ [ب ك ت] (مص. بَكَّتَ). ""شَعَرَ بِتَبْكِيتِ الضَّمِيرِ"" : بِنَدَمٍ، بِتَأْنِيبِ الضَّمِيرِ، بِوَخْزِ الضَّميرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18525, 'بَكَمٌ', 'بكم', 'مصدر', 'بكم', 'بكم', 'بكم', 'مص. بكِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَكَمٌ-بَكَمٌ [ب ك م] (مص. بكِمَ). ""وَلَدٌ أَصابَه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18526, 'بُكاءٌ', 'بكاء', 'مصدر', 'بكي', 'بكاء', 'بك', 'مص. بَكَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"بُكاءٌ-بُكاءٌ [ب ك ي] (مص. بَكَى). ""لَمْ يَكُنْ بُكائِي إِلاَّ أَلَماً وَحُزْناً"" : سَيَلانُ الدُّموعِ مِنَ الألَمِ والحُزْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18527, 'بَلَّةٌ', 'بلة', 'مصدر', 'بلل', 'بلة', 'بلة', 'مص. بَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَلَّةٌ-بَلَّةٌ [ب ل ل] (مص. بَلَّ). ""زادَ الطِّينَ بَلَّةً"" : أَيْ زادَهُ سُوءاً وَتَعْقِيداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18528, 'بَلاءٌ', 'بلاء', 'مصدر', 'بلو', 'بلاء', 'بل', 'مص. بَلاَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"بَلاءٌ-بَلاءٌ [ب ل و] (مص. بَلاَ). 1.""لَمْ يَعْرِفْ إِلاَّ البَلاءَ وَالمِحَنَ"" : الْمَصاعِبَ والْمَصائِبَ. ""مَنْ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18529, 'بُنْيانٌ', 'بنيان', 'مصدر', 'بني', 'بنيان', 'بنن', 'مص. بَنَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بُنْيانٌ-بُنْيانٌ [ب ن ي] (مص. بَنَى). 1.""أقَامَ العُمَّالُ بُنْيَاناً صَلْباً"" : مَا بُنِيَ. 2.""كَانَ يَش"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18530, 'تَبْلِيطٌ', 'تبليط', 'مصدر', 'بلط', 'تبليط', 'تبلط', 'مص. بَلَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبْلِيطٌ-تَبْلِيطٌ [ب ل ط] (مص. بَلَّطَ). ""تَبْلِيطُ بَهْوِ الدَّارِ"" : تَفْرِيشُهُ بِالبَلاَطِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18531, 'تَبْلِيغٌ', 'تبليغ', 'مصدر', 'بلغ', 'تبليغ', 'تبلغ', 'مص. بَلَّغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبْلِيغٌ-تَبْلِيغٌ [ب ل غ] (مص. بَلَّغَ). ""تَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18532, 'بُلُوغٌ', 'بلوغ', 'مصدر', 'بلغ', 'بلوغ', 'بلغ', 'مص. بَلَغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بُلُوغٌ-بُلُوغٌ [ب ل غ] (مص. بَلَغَ). 1."" بَلَغَ سِنَّ البُلُوغِ"" : سِنَّ الإدْرَاكِ وَنُضْجِ الأعْضَاءِ التَّنَاسُلِيَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18533, 'بَلاغَةٌ', 'بلاغة', 'مصدر', 'بلغ', 'بلاغة', 'بلغة', 'مص. بَلُغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَلاغَةٌ-بَلاغَةٌ [ب ل غ] (مص. بَلُغَ). 1.""كانَ يَتَكَلَّمُ بِبَلاغَةٍ"": بِلُغَةٍِ فِيها حُسْنُ البَيانِ وَقُوَّةُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18534, 'بَلاهَةٌ', 'بلاهة', 'مصدر', 'بله', 'بلاهة', 'بلهة', 'مص. بَلَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَلاهَةٌ-بَلاهَةٌ [ب ل هـ] (مص. بَلَهَ). ""ما هَذِهِ البَلاهَةُ"" : ضَعْفٌ في"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18535, 'بَلْوَرَةٌ', 'بلورة', 'مصدر', 'بلور', 'بلورة', 'بلرة', 'مص. بَلْوَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَلْوَرَةٌ-بَلْوَرَةٌ [ب ل و ر] (مص. بَلْوَرَ). ""عَمِلَ على بَلْوَرَةِ أَفْكارِهِ"" : تَوْضِيحها، تِبْيانها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18536, 'بِنَاءٌ', 'بناء', 'مصدر', 'بني', 'بناء', 'بن', 'مص. بَنَى', '', '', 'مفرد', 'Dz', '', 'Pf', '":أبْنيَةٌ"', '', 'Rz', '', '', '', '', '', '', '"(مص. بَنَى). 1.""بِنَاءٌ جَدِيدٌ"" : تَشْيِيدٌ، تَعْمِيرٌ. ""شُيِّدَتْ أَبْنِيَةٌ عَديدَةٌ في حَيِّنا"" : أُقيمَتْ عِماراتٌ وَبِناياتٌ مُخْتَلِفَةٌ، أَيِ الْمَبانِي. 2.""بِناءً على طَلَبِكَ"" : اِسْتِناداً عَلَيْهِ، بِناءً على ذَلِكَ: بِناءً اسْمٌ مَنْصوبٌ على أَنَّهُ مَفْعولٌ له أو لأَجْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18537, 'أبْنيَةٌ', 'أبنية', 'مصدر', '', 'ءبنية', 'بنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18538, 'بِنَايَةٌ', 'بناية', 'مصدر', 'بني', 'بناية', 'بنة', 'مص. بَنَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. بَنَى). ""شُيِّدَتْ بِنَايَةٌ عَالِيَة مِنْ عِدَّةِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18539, 'تَوْبَةٌ', 'توبة', 'مصدر', 'توب', 'توبة', 'تبة', 'مص. تَابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْبَةٌ-تَوْبَةٌ [ت و ب] (مص. تَابَ). 1. ""تَابَ تَوْبَةَ نَصُوحٍ"": الرُّجُوعُ عَنِ الْمَعْصِيَةِ بِصِدْقٍ و"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18540, 'بُهْتَانٌ', 'بهتان', 'مصدر', 'بهت', 'بهتان', 'بهتن', 'مص. بَهَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بُهْتَانٌ-بُهْتَانٌ [ب هـ ت] (مص. بَهَتَ). 1.""عُرِفَ بِالبُهْتَانِ بَيْنَ زُمَلائِهِ"" : بِالكَذِبِ وَالافْتِرَاءِ، اِخْتِلاَقُ الكَذِبِ. 2. ""أَتَى البُهْتَانَ"" : البَاطِلَ، الزَّيْفَ. النور آية 16هَذَا بُهْتَانٌ عَظِيمٌ . (قرآن) "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18541, 'بَهْجَةٌ', 'بهجة', 'مصدر', 'بهج', 'بهجة', 'بهجة', 'مص. بَهَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَهْجَةٌ-بَهْجَةٌ [ب هـ ج] (مص. بَهَجَ). 1. ""كَانَ بَهْجَةً لِلنَّاظِرِينَ"" : مَسَرَّةً، نَضَارَةً، حُسْناً. ""بَهْجَةُ الأَنْظَارِ"". 2.""اِسْتَقْبَلَهُ بِبَهْجَةٍ وَمَرَحٍ"" : بِسُرُورٍ وَابْتِهَاجٍ. "" أدْخَلَ عَلَى قَلْبِهِ البَهْجَةَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18542, 'بَهْدَلَةٌ', 'بهدلة', 'مصدر', 'بهدل', 'بهدلة', 'بهدلة', 'مص. بَهْدَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَهْدَلَةٌ-بَهْدَلَةٌ [ب هـ د ل] (مص. بَهْدَلَ). 1.: أصْلُ الثَّدْيِ. 2.: لَحْمَةٌ مِنَ العُنُقِ فَوْقَ التَّرْقُوَةِ. 3.: إظْهَارُ السُّخْفِ وَالتَّفَاهَةِ وَالضُّعْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18543, 'بَهْرَجَةٌ', 'بهرجة', 'مصدر', 'بهرج', 'بهرجة', 'بهرجة', 'مص. بَهْرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"بَهْرَجَةٌ-بَهْرَجَةٌ [ب هـ ر ج] (مص. بَهْرَجَ). ""أظْهَرُوا بَهْرَجَةً لا تُعَبِّرُ عَنْ وَاقِعِهِمْ"" : أُبَّهَةً زَائِفَةً، بَاطِلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18544, 'بَهَاءٌ', 'بهاء', 'مصدر', 'بهو', 'بهاء', 'به', 'مص. بَهَى، بَهَا', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"بَهَاءٌ-بَهَاءٌ [ب هـ و] (مص. بَهَى، بَهَا). 1. ""فِي حُسْنِ بَهَائِهَا"" : فِي حُسْنِ إشْرَاقِهَا وَجَمَالِهَا. ""بَهَاءُ الْمَنْظَرِ"" ""رَشَاقَةُ الخِلاَلِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18545, 'تَبْوِيبٌ', 'تبويب', 'مصدر', 'بوب', 'تبويب', 'تبب', 'مص. بَوَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبْوِيبٌ-تَبْوِيبٌ [ب و ب] (مص. بَوَّبَ). ""تَبْوِيبُ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18546, 'بُؤْسٌ', 'بؤس', 'مصدر', 'بأس', 'بءس', 'بس', 'مص. بَئِسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بُؤْسٌ-بُؤْسٌ [ب أ س] (مص. بَئِسَ). 1.""يَعِيشُ فِي بُؤْسٍ شَدِيدٍ"" : فِي فَقْرٍ، فِي وَضْعٍ مُزْرٍ، فِي مَشَقَّةٍ. ""كانَ بُؤْسُهُ لاَ يُحْتَمَلُ"". 2. وَيَأتِي مَفْعُولاً مُطْلَقاً : ""أبْأسَهُ اللَّهُ بُؤْساً"". 3.:كَمَا يَقَعُ مَوْقِع الدُّعاءِ عَلَى الآخَرِ : بؤْساً لَهُ، بُؤْساً للِرَّجُلِ الشِّرِّيرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18547, 'بَأسٌ', 'بأس', 'مصدر', 'بأس', 'بءس', 'بس', 'مص. بَئِسِ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"بَأسٌ-بَأسٌ [ب أ س] (مص. بَئِسِ). 1.""لاَ بَأسَ عَلَيْكَ"" : لاَ خَوْفَ عَلَيْكَ. ""لاَ بَأسَ عَلَيْهِ"" ""لاَ بَأْسَ فِيهِ"". 2.""هُوَ ذُو بَأْسِ"" : ذُو شَجاعَةٍ وَقُوَّةٍ وَجُرْأةٍ. ""يَأتِي بِالفَرَجِ وَقَد اشْتَدَّ البَأسُ"".(التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18548, 'مُتَاءمَةٌ', 'متاءمة', 'مصدر', 'تأم', 'متاءمة', 'متمة', 'مص. تَاءمَ', '', '', 'مفرد', '', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَاءمَةٌ-مُتَاءمَةٌ [ت أ م] (مص. تَاءمَ). 1.""لَمْ يَنْتَبِهْ فيِ البِدَايَةِ إِلَى وُجُودِ مُتَاءمَةٍ بَيْنَ الأَخَوَيْنِ"" : كَوْنُهُم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18549, 'تَأَجُّلٌ', 'تأجل', 'مصدر', 'أجل', 'تءجل', 'تجل', 'مص. تَأَجَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَجُّلٌ-تَأَجُّلٌ [أ ج ل] (مص. تَأَجَّلَ). ""تَأَجَّلَ الاجْتِمَاعُ"" : أُرْجِئَ إِلَى وَقْتٍ لاَحِقٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18550, 'تَأَبُّدٌ', 'تأبد', 'مصدر', 'أبد', 'تءبد', 'تبد', 'مص. تَأَبَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَبُّدٌ-تَأَبُّدٌ [أ ب د] (مص. تَأَبَّدَ). 1.""تَأَبُّدُ سُلْطَانِهُ"" : دَوَامُهُ، اِسْتِمْرَارُهُ. 2.""تَأَبُّدُ الْمَكَانِ"" : إِقْفَارُهُ، خُلُوُّهُ مِنَ النَّاسِ، تَوَحُّشُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18551, 'تَأَبُّطٌ', 'تأبط', 'مصدر', 'أبط', 'تءبط', 'تبط', 'مص. تَأَبَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَبُّطٌ-تَأَبُّطٌ [أ ب ط] (مص. تَأَبَّطَ). ""تَأَبُّطُ المِحْفَظَةِ"" : وَضْعُهَا تَحْتَ الإِبْطِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18552, 'تِبَاعٌ', 'تباع', 'مصدر', 'تبع', 'تباع', 'تبع', 'مص. تَابَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تِبَاعٌ-تِبَاعٌ [ت ب ع] (مص. تَابَعَ). ""جَاءَ الأَوْلاَدُ تِبَاعاً"" : بِال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18553, 'مُتَابَعَةٌ', 'متابعة', 'مصدر', 'تبع', 'متابعة', 'متبعة', 'مص. تَابَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَابَعَةٌ-مُتَابَعَةٌ [ت ب ع] (مص. تَابَعَ). 1.""مُتَابَعَةُ العَمَلِ"" : الاسْتِمْرَارُ فِيهِ وَالْمُثَابَرَةُ عَلَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18554, 'تَأَتِّي', 'تأتي', 'مصدر', 'أتي', 'تءتي', 'تت', 'مص. تَأَتَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَأَتٍّ-تَأَتٍّ، التَّأَتِّي [أ ت ي] (مص. تَأَتَّى). 1.""التَّأَتِّي لِلْمَعْرَكَةِ"" : الاِسْتِعْدَادُ وَالتَّهَيُّؤُ لَهَا. 2.""التَّأَتِّي لِلْعَدُوِّ بِسِلاَحٍ حَاسِمٍ"" : قَصْدُهُ مِنْ أَجْلِ إِصَابَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18555, 'تَأثُّث', 'تأثث', 'مصدر', 'أثث', 'تءثث', 'تث', 'مص. تَأَثَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأثُّث-تَأثُّثٌ [أ ث ث] (مص. تَأَثَّثَ). 1.""تَأَثُّثُ البَيْتِ"": وَضْعُ أَثَاثٍ فِيهِ. 2.""تَأَثُّثُ الرَّجُلِ"" : تَمَلُّكُهُ أَثَاثاً، إِصَابَتُهُ خَيْراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18556, 'تَأَثُّرٌ', 'تأثر', 'مصدر', 'أثر', 'تءثر', 'تثر', 'مص. تَأَثَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَثُّرٌ-تَأَثُّرٌ [أ ث ر] (مص. تَأَثَّرَ). ""كَانَ تَأَثُّرُهُ شَدِيدًا "" : إِحْسَاسُهُ، اِنْفِعَالُهُ. ""لَمْ يُظْهِرْ أَدْنَى تَأَثُّرٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18557, 'تَأَجُّجٌ', 'تأجج', 'مصدر', 'أجج', 'تءجج', 'تج', 'مص. تَأَجَّجَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَجُّجٌ-تَأَجُّجٌ [أ ج ج] (مص. تَأَجَّجَ) 1. ""تَأَجُّجُ النِّيرَانِ"": اِلْتِهَابُهَا. 2. ""تَأَجُّجُ شُعُورِهِ"" : اشْتِدَادُ أَلَمِهِ. 3. ""تَأَجُّجُ النَّهَارِ "": اِشْتِدَادُ حَرِّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18558, 'مُتَاجَرَةٌ', 'متاجرة', 'مصدر', 'تجر', 'متاجرة', 'متجرة', 'مص. تَاجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَاجَرَةٌ-مُتَاجَرَةٌ [ت ج ر] (مص. تَاجَرَ). ""الْمُتَاجَرَةُ ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18559, 'تَأَسُّفٌ', 'تأسف', 'مصدر', 'أسف', 'تءسف', 'تسف', 'مص. تَأَسَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَسُّفٌ-تَأَسُّفٌ [أ س ف] (مص. تَأَسَّفَ). ""أَظْهَرَ تَأَسُّفاً"" : تَأَلُّماً مَعَ الشُّعُورِ بِالأَسَفِ وَالحُزْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18560, 'تَأَخُّرٌ', 'تأخر', 'مصدر', 'أخر', 'تءخر', 'تخر', 'مص. تَأَخَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَخُّرٌ-تَأَخُّرٌ [أ خ ر] (مص. تَأَخَّرَ). ""مَا هَذَا التَّأَخُّرُ"" : البُطْءُ، التَّمَهُّلُ، التَّقَهْقُرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18561, 'مُتَاخَمَةٌ', 'متاخمة', 'مصدر', 'تخم', 'متاخمة', 'متخمة', 'مص. تَاخَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُتَاخَمَةٌ-مُتَاخَمَةٌ [ت خ م] (مص. تَاخَمَ). ""مُتَاخَمَةُ بَلَدٍ لِبَلَدٍ"" : مُجَاوَرَتُهُ، مُلاَصَقَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18562, 'تَآخي', 'تآخي', 'مصدر', 'أخو', 'تءءخي', 'تآخ', 'مص. تَآخَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَآخٍ-تَآخٍ، التَّآخي [أ خ و] (مص. تَآخَى). ""يَشُدُّهُمَا التَّآخِي والوِئَامُ"" : أَي التَّفَاهُمُ وَالمحَبّةُ، الْمَوَدَّةُ والصَّدَاقَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18563, 'تَأَخِّي', 'تأخي', 'مصدر', 'أخي', 'تءخي', 'تخ', 'مص. تَأَخَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَأَخٍّ-تَأَخٍّ، التَّأَخِّي [أ خ ي] (مص. تَأَخَّى). 1.""تَأَخِّي الصَّدِيقِ"" : اِتِّخَاذُهُ صَدِيقاً. 2.""تَأَخِّي الحَقِيقَةِ"" : تَحَرِّيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18564, 'تَأَدُّبٌ', 'تأدب', 'مصدر', 'أدب', 'تءدب', 'تدب', 'مص. تَأَدَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَدُّبٌ-تَأَدُّبٌ [أ د ب] (مص. تَأَدَّبَ). 1.""التَّأَدُّبُ بِآدَابِ القَوْمِ فَضِيلَةٌ"" : التَّخَلُّقُ، الاِقْتِدَاءُ، الاِحْتِذَاءُ. 2.""كَانَ تَأَدُّبُهُ بِأَدَبِ القُدَمَاءِ مِيزَةً مِنْ مُمَيِّزَاتِهِ"" : تَعَلُّمُهُ، تَثَقُّفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18565, 'تَأَرْجُحٌ', 'تأرجح', 'مصدر', 'رجح', 'تءرجح', 'ترجح', 'مص. تَأَرْجَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَرْجُحٌ-تَأَرْجُحٌ [ر ج ح] (مص. تَأَرْجَحَ). 1.""تَأَرْحُجُ الجُدْرَانِ"" : اِهْتِزَازُهَا. 2.""التَّأَرْجُحُ فَوْقَ السُّلَّمِ"" : التَّحَرُّكُ. 3.""التَّأَرْجُحُ فِي الأُرْجُوحَةِ"" : التَّحَرُّكُ مِنْ جِهَةٍ إِلَى أُخُرَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18566, 'تَآزُرٌ', 'تآزر', 'مصدر', 'أزر', 'تءءزر', 'تآزر', 'مص. تَآزُرٌ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَآزُرٌ-تَآزُرٌ [أ ز ر] (مص. تَآزُرٌ). ""تَآزُرُ أَفْرَادِ الْمُجْتَمَعِ ضَرُورِيٌّ لِكُلِّ بِنَاءٍ وتَقَدُّمٍ"" : التَّعَاوُنُ، التَّضَامُنُ، الْمُسَاعَدَةُ الْمُتَبَادَلَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18567, 'تَأَزُّمٌ', 'تأزم', 'مصدر', 'أزم', 'تءزم', 'تزم', 'مص. تَأَزَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَزُّمٌ-تَأَزُّمٌ [أ ز م] (مص. تَأَزَّمَ). ""تَأَزُّمُ الوَضْعِيَّةِ الاقْتِصَادِيَّةِ"": اِشْتِدَادُ وَطْأَتِهَا، اِخْتِنَاقُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18568, 'تَأَسُّدٌ', 'تأسد', 'مصدر', 'أسد', 'تءسد', 'تسد', 'مص. تَأَسَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَسُّدٌ-تَأَسُّدٌ [أ س د] (مص. تَأَسَّدَ). ""يُحِبُّ التَّأَسُّدَ عَلَى أَصْحَابِهِ"" : الاجْتِرَاءَ عَلَيْهِمْ، الظُّهُورَ بِمَظْهَرِ الأَسَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18569, 'تَأَمُّلٌ', 'تأمل', 'مصدر', 'أمل', 'تءمل', 'تمل', 'مص. تَأَمَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَمُّلٌ-تَأَمُّلٌ [أ م ل] (مص. تَأَمَّلَ). ""هُوَ دَائِمُ التَّأَمُّلِ"" : دَائِمُ التَّفْكِيرِ العَمِيقِ فِي حَقَائِقِ الأُمُورِ. ""اِسْتَغْرَقَ بِالفِكْرِ وَالتَّأَمُّلِ لا بِالحِسِّ وَالتَّلَمُّسِ"". (مصطفى الرافعي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18570, 'تَأَسٍّي', 'تأسي', 'مصدر', 'أسي', 'تءسي', 'تس', 'مص. تَأَسَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَأَسٍّ-تَأَسٍّ، التَّأَسِّي [أ س ي] (مص. تَأَسَّى). 1.""لَيْسَ أَمَامَهُ إِلاَّ التَّأَسِّي"" : التَّصَبُّرَ. 2.""أَرَادَ التَّأَسِّيَ بِهِ"" : الاِحْتِذَاءَ، الاِقْتِدَاءَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18571, 'تَأَفُّفٌ', 'تأفف', 'مصدر', 'أفف', 'تءفف', 'تف', 'مص. تَأَفَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَفُّفٌ-تَأَفُّفٌ [أ ف ف] (مص. تَأَفَّفَ). ""هُوَ فِي تَأَفُّفٍ مِنْ أَمْرِهِ"" : فِي كَرْبٍ أَوْ ضَجَرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18572, 'تَأَكُّدٌ', 'تأكد', 'مصدر', 'أكد،وكد', 'تءكد', 'تكد', 'مص. تَأَكَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَـأَكُّدٌ-تَـأَكُّدٌ [أ ك د، و ك د] (مص. تَأَكَّدَ). ""التَّأَكُّدُ مِنْ صِحَّةِ الخَبَرِ فَضِيلَةٌ "" ‎: التَّوَثُّقُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18573, 'تَأَلُّبٌ', 'تألب', 'مصدر', 'ألب', 'تءلب', 'تلب', 'مص. تَأَلَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَلُّبٌ-تَأَلُّبٌ [أ ل ب] (مص. تَأَلَّبَ). 1."" تَأَلُّبُ القَوْمِ"" : تَجَمُّعُهُمْ. 2.""التَّأَلُّبُ عَلَى الخَصْمِ"" : التَّآمُرَ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18574, 'تَآلُفٌ', 'تآلف', 'مصدر', 'ألف', 'تءءلف', 'تآلف', 'مص. تَآلَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَآلُفٌ-تَآلُفٌ [أ ل ف] (مص. تَآلَفَ). ""تَآلُفُ أَعْضَاءِ الأُسْرَةِ الوَاحِدَةِ عُرْبُونٌ عَلَى الإِخَاءِ والْمَحَبَّةِ الْمُتَبَادَلَةِ"" : الانْسِجَامُ، الوِئَامُ. ""يَسُودُ التَّآلُفُ عَلاَقَتَهُمَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18575, 'تَأَلُّفٌ', 'تألف', 'مصدر', 'ألف', 'تءلف', 'تلف', 'مص. تَأَلَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَلُّفٌ-تَأَلُّفٌ [أ ل ف] (مص. تَأَلَّفَ). 1.""تَأَلُّفُ الفِرَقِ"" : تَنَظُّمُهَا، أَوِ اجْتِمَاعُهَا. 2.""تَأَلُّفُ الحُكُومَةِ"" : تَشَكُّلُهَا، تَكَوُّنُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18576, 'تَأَلُّقٌ', 'تألق', 'مصدر', 'ألق', 'تءلق', 'تلق', 'مص. تَأَلَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَلُّقٌ-تَأَلُّقٌ [أ ل ق] (مص. تَأَلَّقَ). 1.""تَأَلُّقُ الْمَنَارِ"" : اِنْبِعَاثُ نُورِهِ. 2.""كَانَ فِي تَأَلُّقِهِ الكَامِلِ"" : فِي بَهَائِهِ وَجَمَالِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18577, 'تَأَلُّمٌ', 'تألم', 'مصدر', 'ألم', 'تءلم', 'تلم', 'مص. تَأَلَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَلُّمٌ-تَأَلُّمٌ [أ ل م] (مص. تَأَلَّمَ). ""ظَهَرَتْ عَلَى مَلاَمِحِهِ آثَارُ التَّأَلُّمِ"" : آثَارُ التَّوَجُّعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18578, 'تَآمُرٌ', 'تآمر', 'مصدر', 'أمر', 'تءءمر', 'تآمر', 'مص. تَآمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَآمُرٌ-تَآمُرٌ [أ م ر] (مص. تَآمَرَ). 1.""تَآمُرُ الجَمَاعَةِ"" : تَشَاوُرُهَا فِي أَمْرٍ مَّا. 2. ""اِكْتَشَفَ تَآمُرَهُ"" : حَبْكُ مُؤَامَرَةٍ وتَدْبِيرُهَا بِهَدَفِ الإِيقَاعِ بِالآخَرِ وإِهْلاَكِهِ وخِيَانَةِ عَهْدِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18579, 'أَتاوِيهُ', 'أتاويه', 'مصدر', '', 'ءتاويه', 'ته', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18580, 'تَأَنُّثٌ', 'تأنث', 'مصدر', 'أنث', 'تءنث', 'تنث', 'مص. تَأَنَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَنُّثٌ-تَأَنُّثٌ [أ ن ث] (مص. تَأَنَّثَ). ""تَأَنُّثُ الوَلَدِ"" : تَشَبُّهُهُ بِالأُنْثَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18581, 'تَآنُسٌ', 'تآنس', 'مصدر', 'أنس', 'تءءنس', 'تآنس', 'مص. تَآنَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَآنُسٌ-تَآنُسٌ [أ ن س] (مص. تَآنَسَ). ""كَانَ سَمَرُهُمْ لِلْمُحَادَثَةِ والتَّآنُسِ"" : لإِينَاسِ بَعْضِهِمْ بَعْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18582, 'تَأَنَّقَ', 'تأنق', 'مصدر', 'أنق', 'تءنق', 'تنق', 'مص. تَأَنُّقٌ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَنَّقَ-تَأَنَّقَ [أ ن ق] (مص. تَأَنُّقٌ). 1.""التَّأَنُّقُ فِي الْمَلْبَسِ"" : ارْتِدَاءُ لِبَاسٍ أَنِيقٍ. 2. ""التَّأَنُّقُ فِي الكَلاَمِ"" : اِخْتِيَارُ كَلاَمٍ فِيهِ بَلاَغَةٌ وَبَيَانٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18583, 'تَأَنِّي', 'تأني', 'مصدر', 'أني', 'تءني', 'تن', 'مص. تَأَنَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَأَنٍّ-تَأَنٍّ، التَّأَنِّي [أ ن ي] (مص. تَأَنَّى). ""فِي التَّأَنِّي السَّلاَمَةُ و"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18584, 'تِيهٌ', 'تيه', 'مصدر', 'تيه', 'تيه', 'ته', 'مص. تَاهَ', '', '', 'مفرد', 'DnN', '', '', '"أَتْياهٌ:أَتاوِيهُ"', '', 'R', '', '', '', '', '', '', '"(مص. تَاهَ). 1.""صارَ في تِيهٍ لاَ نِهايَةَ لَهُ"" : فَلاةٌ مُقْفَرَّةٌ، قَفْرٌ. 2.""هُوَ في تيهٍ"": في ضَلالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18585, 'أَتْياهٌ', 'أتياه', 'مصدر', '', 'ءتياه', 'ته', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18586, 'أَتاوِيهُ', 'أتاويه', 'مصدر', '', 'ءتاويه', 'ته', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18587, 'تَوْهٌ', 'توه', 'مصدر', 'توه', 'توه', 'ته', 'مص. تاهَ', '', '', 'مفرد', 'DnN', '', '', '"أَتْواهٌجأَتاوِيهُ"', '', 'R', '', '', '', '', '', '', '"(مص. تاهَ). ""ساعَدَ على تَوْهِهِ ظُلْماً"" : على هَلاكِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18588, 'أَتْواهٌ', 'أتواه', 'مصدر', '', 'ءتواه', 'ته', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18589, 'تَبَارُزٌ', 'تبارز', 'مصدر', 'برز', 'تبارز', 'تبرز', 'مص. تَبَارَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَارُزٌ-تَبَارُزٌ [ب ر ز] (مص. تَبَارَزَ). ""خَرَجُوا لِلتَّبَارُزِ"" : للتَّقَاتُلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18590, 'تَيَهانٌ', 'تيهان', 'مصدر', 'تيه', 'تيهان', 'تهن', 'مص. تاهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَيَهانٌ-تَيَهانٌ [ت ي هـ] (مص. تاهَ). ""وَجَدَهُ في تَيَهانٍ"": فِي تَحَيُّرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18591, 'تَأَهُّبٌ', 'تأهب', 'مصدر', 'أهب', 'تءهب', 'تهب', 'مص. تَأَهَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَهُّبٌ-تَأَهُّبٌ [أ هـ ب] (مص. تَأَهَّبَ). ""التَّأَهُّبُ لِلْمَعْرَكَةِ"": الِاسْتِعْدَادُ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18592, 'تَأَهُّلٌ', 'تأهل', 'مصدر', 'أهل', 'تءهل', 'تهل', 'مص. تَأَهَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَهُّلٌ-تَأَهُّلٌ [أ هـ ل] (مص. تَأَهَّلَ). 1.""يَسْتَعِدُّ لِلتَّأَهُّلِ لِلمَنْصِبِ الجَدِيدِ"" : يَسْتَعِدُّ لِيَكُونَ أَهْلاً لَهُ. 2.""لاَحَظَ الوَالِدُ أَنَّ ابْنَهُ بَلَغَ سِنَّ التَّأَهُّلِ"" : سِنَّ الزَّوُّاجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18593, 'تَأَوُّهٌ', 'تأوه', 'مصدر', 'أوه', 'تءوه', 'ته', 'مص. تَأَوَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَوُّهٌ-تَأَوُّهٌ [أ و هـ] (مص. تَأَوَّهَ). ""أَكْثَرَ مِنَ التَّأَوُّهِ"" : مِنَ التَّوَجُّعِ، مِنَ التَّشَكِّي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18594, 'تَأَيُّدٌ', 'تأيد', 'مصدر', 'أيد', 'تءيد', 'تد', 'مص. تَأَيَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَأَيُّدٌ-تَأَيُّدٌ [أ ي د] (مص. تَأَيَّدَ). "" تَأَيُّدُ السُّلْطَانِ"" : تَقَوِّيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18595, 'تَبٌّ', 'تب', 'مصدر', 'تبب', 'تب', 'تب', 'مص. تَبَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَبٌّ-تَبٌّ [ت ب ب] (مص. تَبَّ). ""تَبّاً لَهُ"" : هَلاَكاً وَخُسْرَاناً لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18596, 'تَبَاجُحٌ', 'تباجح', 'مصدر', 'بجح', 'تباجح', 'تبجح', 'مص. تَبَاجَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَاجُحٌ-تَبَاجُحٌ [ب ج ح] (مص. تَبَاجَحَ). "" يُكْثِرُ مِنَ التَّبَاجُحِ"" : مِنَ التَّبَاهِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18597, 'تَبَاحُثٌ', 'تباحث', 'مصدر', 'بحث', 'تباحث', 'تبحث', 'مص. تَبَاحَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَاحُثٌ-تَبَاحُثٌ [ب ح ث] (مص. تَبَاحَثَ). "" قَرَّرُوا التَّبَاحُثَ فِيمَا بَيْنَهُمْ"" : التَّشَاوُرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18598, 'تَبَادُلٌ', 'تبادل', 'مصدر', 'بدل', 'تبادل', 'تبدل', 'مص. تَبَادَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَادُلٌ-تَبَادُلٌ [ب د ل] (مص. تَبَادَلَ). 1.""جَاءوا لِتَبَادُلِ الآرَاءِ"" : لِلاِطِّلاَعِ الْمُشْتَرَكِ عَلَى كُلِّ الآرَاءِ. 2.""اِتَّفَقُوا عَلَى التَّبَادُلِ الثَّقَافِيِّ"" : كُلُّ وَاحِدٍ يُقَدِّمُ للآخَرِ ما عِنْدَهُ مِنْ ثَقافَةٍ وَيُطْلِعُهُ عَلَيْهِ. 3.""تَبَادُلُ السِّلَعِ"" : الْمُقَايَضَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18599, 'تَبَارُكٌ', 'تبارك', 'مصدر', 'برك', 'تبارك', 'تبرك', 'مص. تَبَارَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَارُكٌ-تَبَارُكٌ [ب ر ك] (مص. تَبَارَكَ). 1.""أَرَادَ التَّبَارُكَ بِهِ"": أَي التَّفَاؤُلَ وَالتَّيَمُّنَ بِهِ. 2.""جَاءَ للتَّبَارُكِ"" : طَلَبُ البَرَكَةِ وَالفَوْزُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18600, 'تَبَارِي', 'تباري', 'مصدر', 'بري', 'تباري', 'تبر', 'مص. تَبَارَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَبَارٍ-تَبَارٍ، التَّبَارِي [ب ر ي] (مص. تَبَارَى). ""قَرَّر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18601, 'تَبَاطُؤٌ', 'تباطؤ', 'مصدر', 'بطأ', 'تباطء', 'تبط', 'مص. تَبَاطَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَبَاطُؤٌ-تَبَاطُؤٌ [ب ط أ] (مص. تَبَاطَأَ). ""أَظْهَرَ تَبَاطُؤاً فِي عَمَلِهِ"" : تَأَخُّراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18602, 'تَبَاعَدَ', 'تباعد', 'مصدر', 'بعد', 'تباعد', 'تبعد', 'مص. تَبَاعُدٌ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَاعَدَ-تَبَاعَدَ [ب ع د] (مص. تَبَاعُدٌ). 1.""بَيْنَهُمَا تَبَاعُدٌ "" : نُفُورٌ، بَعُدَ كُلُّ وَاحِدٍ مِنْهُمَا عَنِ الآخَرِ. 2.""تَبَاعُدُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18603, 'تَبَاغُضٌ', 'تباغض', 'مصدر', 'بغض', 'تباغض', 'تبغض', 'مص. تَبَاغَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَاغُضٌ-تَبَاغُضٌ [ب غ ض] (مص. تَبَاغَضَ). ""لاَ شَيْءَ يَد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18604, 'تَبَاكي', 'تباكي', 'مصدر', 'بكي', 'تباكي', 'تبك', 'مص. تَبَاكَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَبَاكٍ-تَبَاكٍ، التَّبَاكِي [ب ك ي] (مص. تَبَاكَى). "" أَكْثَرَ التَّبَاكِيَ"" : تَكَلُّفُ البُكاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18605, 'تَبَاهِي', 'تباهي', 'مصدر', 'بهي', 'تباهي', 'تبه', 'مص. تَبَاهَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَبَاهٍ-تَبَاهٍ، التَّبَاهِي [ب هـ ي] (مص. تَبَاهَى). ""لاَ يَكُفُّ عَنِ التَّبَاهِي"" : عَنِ التَّفَاخُرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18606, 'تَبَايُنٌ', 'تباين', 'مصدر', 'بين', 'تباين', 'تبن', 'مص. تَبَايَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَايُنٌ-تَبَايُنٌ [ب ي ن] (مص. تَبَايَنَ). ""بَيْنَهُمَا تَبَايُنٌ فِي الرَّأْيِ"" : اِخْتِلافٌ، أَيْ كُلُّ وَاحِدٍ لَهُ رَأْيٌ مُخَالِفٌ للآخَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18607, 'تَبَجُّحٌ', 'تبجح', 'مصدر', 'بجح', 'تبجح', 'تبجح', 'مص. تَبَجَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَجُّحٌ-تَبَجُّحٌ [ب ج ح] (مص. تَبَجَّحَ). ""تَبَجُّحُ الرَّجُلِ"" : التَّكَبُّرُ التَّباهِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18608, 'تَبَحُّرٌ', 'تبحر', 'مصدر', 'بحر', 'تبحر', 'تبحر', 'مص. تَبَحَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَحُّرٌ-تَبَحُّرٌ [ب ح ر] (مص. تَبَحَّرَ). ""سَاعَدَتْهُ ثَقَافَتُهُ الوَاسِعَةُ عَلَى التَّبَحُّرِ فِي العُلُومِ"" : عَلَى التَّوَسُّعِ وَالتَّعَمُّقِ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18609, 'تَبَخْتُرٌ', 'تبختر', 'مصدر', 'بختر', 'تبختر', 'تبختر', 'مص. تَبَخْتَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَخْتُرٌ-تَبَخْتُرٌ [ب خ ت ر] (مص. تَبَخْتَرَ). ""هُوَ دَائِمُ التَّبَخْتُرِ أَمَامَ النَّاسِ"" : يَمْشِي فِي بُطْءٍ وَتَمَايُلٍ وَغُنْجٍ مُعْجَباً بِنَفْسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18610, 'تَبَخُّرٌ', 'تبخر', 'مصدر', 'بخر', 'تبخر', 'تبخر', 'مص. تَبَخَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَخُّرٌ-تَبَخُّرٌ [ب خ ر] (مص. تَبَخَّرَ). 1.""تَبَخُّرُ الْمَاءِ"" : تَحَوُّلُهُ إِلَى بُخَارٍ. 2.""اِعْتَادَتِ التَّبَخُّرَ فِي كَلِّ مَسَاءٍ"" : التَّطَيُّبَ بِمَا يُحْرَقُ مِنْ بُخُورٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18611, 'تَبَدُّدٌ', 'تبدد', 'مصدر', 'بدد', 'تبدد', 'تبد', 'مص. تَبَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَدُّدٌ-تَبَدُّدٌ [ب د د] (مص. تَبَدَّدَ). 1.""مُنْذُ الصَّبَاحِ وَالغَمَامُ فِي تَبَدُّدٍ"" : فِي تَفَرُّقٍ. 2.""تَبَدُّدُ الأَحْزَانِ"" : تَلاَشِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18612, 'تَبَدُّلٌ', 'تبدل', 'مصدر', 'بدل', 'تبدل', 'تبدل', 'مص. تَبَدَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَدُّلٌ-تَبَدُّلٌ [ب د ل] (مص. تَبَدَّلَ). ""أَحْوَالُهُ فِي تَبَدُّلٍ دَائِمٍ"" : فِي تَغَيُّرٍ، فِي تَحَوُّلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18613, 'تَبَدِي', 'تبدي', 'مصدر', 'بدي', 'تبدي', 'تبد', 'مص. تَبَدَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَبَدٍّ-تَبَدٍّ، التَّبَدِّي [ب د ي] (مص. تَبَدَّى). 1.""رَغِبَ فِي التَّبَدِّي"" : فِي الْخُرُوجِ إِلَى البَادِيَةِ. 2.""يَنْتَظِرُ تَبَدِّيَ الْهِلاَلِ فِي آخِرِ كُلِّ شَهْرٍ"" : ظُهُورُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18614, 'تَبَرُّؤٌ', 'تبرؤ', 'مصدر', 'برأ', 'تبرء', 'تبر', 'مص. تَبَرَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَبَرُّؤٌ-تَبَرُّؤٌ [ب ر أ] (مص. تَبَرَّأَ). 1.""كَادَ غَضَبُهُ أَنْ يَدْفَعُهُ لِلتَّبَرُّؤِ مِنِ ابْنِهِ"" : التَّخَلِّي عَنْهُ وَقَطْعُ الصِّلَةِ بِهِ. 2.""التَّبَرُّؤُ مِنَ الذَّنْبِ أَوِ التُّهْمَةِ"" : التَّخَلُّصُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18615, 'تَبَرُّجٌ', 'تبرج', 'مصدر', 'برج', 'تبرج', 'تبرج', 'مص. تَبَرَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَرُّجٌ-تَبَرُّجٌ [ب ر ج] (مص. تَبَرَّجَ). ""نَهَاهَا عَنِ التَّبَرُّجِ"": عَنِ التَّزَيُّنِ وَإِظْهَارِ مَحَاسِنِهَا وَحُلِيِّهَا.الأحزاب آية 33 وَلاَ تَبَرَّجْنَ تَبَرُّجَ الجَاهِلِيَّةِ الأُولَى (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18616, 'تَبَرُّدٌ', 'تبرد', 'مصدر', 'برد', 'تبرد', 'تبرد', 'مص. تَبَرَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَرُّدٌ-تَبَرُّدٌ [ب ر د] (مص. تَبَرَّدَ). 1.""وَجَدَ فِي ظِلاَلِ الأَشْجَارِ مَكَاناً لِلت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18617, 'تَبَرُّعٌ', 'تبرع', 'مصدر', 'برع', 'تبرع', 'تبرع', 'مص. تَبَرَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. تَبَرَّعَ). ""تَكَلَّفَ بِجَمْعِ التَّبَرُّعَاتِ لِلْجَمْعِيَّةِ"" : جَمْع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18618, 'تَبَرُّكٌ', 'تبرك', 'مصدر', 'برك', 'تبرك', 'تبرك', 'مص. تَبَرَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَرُّكٌ-تَبَرُّكٌ [ب ر ك] (مص. تَبَرَّكَ). ""جَاءَ لِلتَّبَرُّكِ بِهِ"" : لأَخْذِ البَرَكَةِ مِنْهُ وَالفَوْزِ بِهَا، التَّيَمُّنُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18619, 'تَبَلُّهٌ', 'تبله', 'مصدر', 'بله', 'تبله', 'تبله', 'مص. تَبَلَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَلُّهٌ-تَبَلُّهٌ [ب ل هـ] (مص. تَبَلَّهَ). ""لاَحَظَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18620, 'تَبَرُّمٌ', 'تبرم', 'مصدر', 'برم', 'تبرم', 'تبرم', 'مص. تَبَرَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَرُّمٌ-تَبَرُّمٌ [ب ر م] (مص. تَبَرَّمَ). ""أَظْهَرَ تَبَرُّماً بِصَاحِبِهِ"" : تَضَجُّراً وَسَأَماً..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18621, 'تَبَسُّطٌ', 'تبسط', 'مصدر', 'بسط', 'تبسط', 'تبسط', 'مص. تَبَسَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَسُّطٌ-تَبَسُّطٌ [ب س ط] (مص. تَبَسَّطَ). 1.""وَجَدَ فِي سُلُوكِهِ تَبَسُّطاً"" : تَرْكُهُ لِلاحْتِشَامِ. 2.""خَرَجُوا لِلتَّبَسُّطِ فِي الحَدِيقَةِ"" : التَّجَوُّلُ وَالتَّنَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18622, 'تَبَسُّمٌ', 'تبسم', 'مصدر', 'بسم', 'تبسم', 'تبسم', 'مص. تَبَسَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَسُّمٌ-تَبَسُّمٌ [ب س م] (مص. تَبَسَّمَ). ""طِفْلٌ دائِمُ التَّبَسُّمِ"": دَائِمُ الابْتِسَامِ،"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18623, 'تَبَصُّرٌ', 'تبصر', 'مصدر', 'بصر', 'تبصر', 'تبصر', 'مص. تَبَصَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَصُّرٌ-تَبَصُّرٌ [ب ص ر] (مص. تَبَصَّرَ). ""عَالَجَ الْمَوْضُوعَ بِتَبَصُّرٍ"" : بِذَكَاءٍ وَفِطْنَةٍ وَتَأَمُّلٍ وَتَرَوٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18624, 'تَبَلُّجٌ', 'تبلج', 'مصدر', 'بلج', 'تبلج', 'تبلج', 'مص. تَبَلَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَلُّجٌ-تَبَلُّجٌ [ب ل ج] (مص. تَبَلَّجَ). ""تَبَلُّجُ الصُّبْحِ"" : إِشَاعَةُ نُورِهِ، ظُهُورُ ضَوْئِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18625, 'تَبَلُّدٌ', 'تبلد', 'مصدر', 'بلد', 'تبلد', 'تبلد', 'مص. تَبَلَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَلُّدٌ-تَبَلُّدٌ [ب ل د] (مص. تَبَلَّدَ). "" يُظْهِرُ التَّبَلُّدَ"" : تَصَنُّعُ البَلاَدَةِ."', '');
