INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18628, 'تَبَلُّلٌ', 'تبلل', 'مصدر', 'بلل', 'تبلل', 'تبل', 'مص. تَبَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَلُّلٌ-تَبَلُّلٌ [ب ل ل] (مص. تَبَلَّلَ). ""تَبَلُّلُ الثِّيَابِ"" : تَنَدِّيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18629, 'تَتَبُّعٌ', 'تتبع', 'مصدر', 'تبع', 'تتبع', 'تتبع', 'مص. تَتَبَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَتَبُّعٌ-تَتَبُّعٌ [ت ب ع] (مص. تَتَبَّعَ). 1.""اِهْتَمَّ بِتَتَبُّعِ الْمَوْضُوعِ"" : بِتَقَصِّيهِ، بِبَحْثِهِ ب"', '');
