INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18631, 'تَبَني', 'تبني', 'مصدر', 'بني', 'تبني', 'تبن', 'مص. تَبَنَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَبَنٍّ-تَبَنٍّ، التَّبَنِّي [ب ن ي] (مص. تَبَنَّى). ""اِبْنٌ بِالتَّبَنِّي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18632, 'تَبَهُّجٌ', 'تبهج', 'مصدر', 'بهج', 'تبهج', 'تبهج', 'مص. تَبَهَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَهُّجٌ-تَبَهُّجٌ [ب هـ ج] (مص. تَبَهَّجَ). 1."" تَبَهُّجُ الْمَكَانِ"": تَحَسُّنُهُ. 2.""التَّبَهُّجُ بِهِ"" : السُّرُورُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18633, 'تَبَهُّرٌ', 'تبهر', 'مصدر', 'بهر', 'تبهر', 'تبهر', 'مص. تَبَهَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَهُّرٌ-تَبَهُّرٌ [ب هـ ر] (مص. تَبَهَّرَ). 1.""تَبَهُّرُ المِصْبَاحِ"" : إِضَاءتُهُ. 2.""تَبَهُّرُ الإِنَاءِ"" : اِمْتِلاَؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18634, 'تَبَهْرُجٌ', 'تبهرج', 'مصدر', 'بهرج', 'تبهرج', 'تبهرج', 'مص. تَبَهْرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَهْرُجٌ-تَبَهْرُجٌ [ب هـ ر ج] (مص. تَبَهْرَجَ). ""تَبَهْرُجُ الفَتَاةِ"" : تَزَيُّنُهَا، إِظْهَارُ مَحَاسِنِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18635, 'تَبَيُّضٌ', 'تبيض', 'مصدر', 'بيض', 'تبيض', 'تبض', 'مص. تَبَيَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَيُّضٌ-تَبَيُّضٌ [ب ي ض] (مص. تَبَيَّضَ). ""تَبَيُّضُ الجِدَارِ"" : صَيْرُهُ أَبْيَضَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18636, 'تَبَيُّنٌ', 'تبين', 'مصدر', 'بين', 'تبين', 'تبن', 'مص. تَبَيَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَبَيُّنٌ-تَبَيُّنٌ [ب ي ن] (مص. تَبَيَّنَ). 1.""تَبَيُّنُ الحَقَائِقِ"" : اِتِّضَاحُهَا، ظُهُورُهَا. 2.""اِسْتَطَاعَ تَببيُّنَ مَلاَمِحِهِ"" : تَعَرُّفُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18637, 'تَتَابُعٌ', 'تتابع', 'مصدر', 'تبع', 'تتابع', 'تتبع', 'مص. تَتَابَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَتَابُعٌ-تَتَابُعٌ [ت ب ع] (مص. تَتَابَعَ). ""تَتَابُعُ الأَحْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18638, 'تَتالِي', 'تتالي', 'مصدر', 'تلو', 'تتالي', 'تتل', 'مص. تَتَالَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَتالٍ-تَتالٍ، التَّتَالِي [ت ل و] (مص. تَتَالَى). ""قَرَأَ أَجْزَاءَ الكِتَابِ بِالتَّتَالِي"" : بِالتَّتَابُعِ، بِالتَّوَالِي. ""دَخَلَ الْمُتَسَابِقُونَ تَتَالِياً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18639, 'تَجَاذُبٌ', 'تجاذب', 'مصدر', 'جذب', 'تجاذب', 'تجذب', 'مص. تَجَاذَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَاذُبٌ-تَجَاذُبٌ [ج ذ ب] (مص. تَجَاذَبَ). 1.""تَجَاذُبُ الفَرِيقَيْنِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18640, 'تَتَرُّبٌ', 'تترب', 'مصدر', 'ترب', 'تترب', 'تترب', 'مص. تَتَرَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَتَرُّبٌ-تَتَرُّبٌ [ت ر ب] (مص. تَتَرَّبَ). ""تَتَرُّبُ الوَلَدِ"" : تَغَبُّرُهُ بِالتُّرابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18641, 'تَتَوُّجٌ', 'تتوج', 'مصدر', 'توج', 'تتوج', 'تتج', 'مص. تَتَوَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَتَوُّجٌ-تَتَوُّجٌ [ت و ج] (مص. تَتَوَّجَ). ""تَتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18642, 'تَتَوُّقٌ', 'تتوق', 'مصدر', 'توق', 'تتوق', 'تتق', 'مص. تَتَوَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَتَوُّقٌ-تَتَوُّقٌ [ت و ق] (مص. تَتَوَّقَ). ""كَانَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18643, 'تَثَاؤُبٌ', 'تثاؤب', 'مصدر', 'ثأب', 'تثاءب', 'تثب', 'مص. تَثَاءبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَثَاؤُبٌ-تَثَاؤُبٌ [ث أ ب] (مص. تَثَاءبَ). ""لاَحَظَ تَثَاؤُبَهُ وَتَسَاءَلَ عَنِ الأَسْبَابِ الكَامِنَةِ وَرَاءهُ"" : اِنْفِتَاحُ الفَمِ عَلَى سَعَتِهِ بِسَبَبِ قِلَّةِ النَّوْمِ أَوِ العَيَاءِ، وَهِيَ حَرَكَةٌ لاَ إِرَادِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18644, 'تَثَاقُلٌ', 'تثاقل', 'مصدر', 'ثقل', 'تثاقل', 'تثقل', 'مص. تَثَاقَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَثَاقُلٌ-تَثَاقُلٌ [ث ق ل] (مص. تَثَاقَلَ). 1.""تَمْشِي فِي تَثَاقُلٍ"" : فِي بُطْءٍ. ""رَفَعَ عَيْنَيْهِ فِي تَثَاقُلٍ"". 2.""تَثَاقُلُ الصَّانِع فِي عَمَلِهِ"" : تَبَاطُؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18645, 'تَثَبُّتٌ', 'تثبت', 'مصدر', 'ثبت', 'تثبت', 'تثبت', 'مص. تَثَبَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَثَبُّتٌ-تَثَبُّتٌ [ث ب ت] (مص. تَثَبَّتَ). 1.""تَثَبُّتُ الأَمْرِ"" : تَقَوِّيهِ، تَشَدُّدُهُ. 2.""التَّثَبُّتُ فِي الأُمُورِ"" : التَّشَاوُرُ، التَّأَنِّي. 3.""التَّثَبُّتُ مِنَ الْمَعْلُومَاتِ"" : التَّأَكُّدُ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18646, 'تَثَلُّمٌ', 'تثلم', 'مصدر', 'ثلم', 'تثلم', 'تثلم', 'مص. تَثَلَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَثَلُّمٌ-تَثَلُّمٌ [ث ل م] (مص. تَثَلَّمَ). ""تَثَلُّمُ الإِنَاء"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18647, 'تَثَنِّي', 'تثني', 'مصدر', 'ثني', 'تثني', 'تثن', 'مص. تَثَنِّي', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَثَنٍّ-تَثَنٍّ، التَّثَنِّي [ث ن ي] (مص. تَثَنِّي). 1.""تَثَنِّي الأَغْصَانِ"" : اِنْثِنَاؤُهَا. 2.""التَّثَنِّي يَمِيناً"" : الانْعِطَافُ...3.""التَّثَنِّي فِي الْمَشْيِ"" : التَّمَايُلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18648, 'تَجَادُلٌ', 'تجادل', 'مصدر', 'جدل', 'تجادل', 'تجدل', 'مص. تَجَادَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَادُلٌ-تَجَادُلٌ [ج د ل] (مص. تَجَادَلَ). 1.""حَصَلَ تَجَادُلٌ بَيْنَهُم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18649, 'تَجَبُّرٌ', 'تجبر', 'مصدر', 'جبر', 'تجبر', 'تجبر', 'مص. تَجَبَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَبُّرٌ-تَجَبُّرٌ [ج ب ر] (مص. تَجَبَّرَ). 1.""أَظْهَرَ تَجَبُّراً"" : تَك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18650, 'تَجَاسُرٌ', 'تجاسر', 'مصدر', 'جسر', 'تجاسر', 'تجسر', 'مص. تَجَاسَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَاسُرٌ-تَجَاسُرٌ [ج س ر] (مص. تَجَاسَرَ). ""أَظْهَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18651, 'تَجَافِي', 'تجافي', 'مصدر', 'جفو', 'تجافي', 'تجف', 'مص. تَجَافِي', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَجَافٍ-تَجَافٍ، التَّجَافِي [ج ف و] (مص. تَجَافِي). 1.""تَجَافِي الجَالِسِ"" : عَدَمُ لُزُومِهِ مَكَانَهُ. 2.""التَّجَافِي عَنْهُ"" : عَدَمُ الاِطْمِئْنَانِ إِلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18652, 'تَجَالُسٌ', 'تجالس', 'مصدر', 'جلس', 'تجالس', 'تجلس', 'مص. تَجَالَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَالُسٌ-تَجَالُسٌ [ج ل س] (مص. تَجَالَسَ). 1.""تَجَالُسُ الجُمْهُورِ"" : جُلُوسُ بَعْضِهِمْ مَعَ بَعْضٍ. 2.""تَجَالُسُ الْمُتَخَاصِمِينَ"" : تَحَاكُمُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18653, 'تَجَانُبٌ', 'تجانب', 'مصدر', 'جنب', 'تجانب', 'تجنب', 'مص. تَجَانَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَانُبٌ-تَجَانُبٌ [ج ن ب] (مص. تَجَانَبَ). ""تَجَانُبُ لِقَائِهِ"": الابْتِعَادُ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18654, 'تجَانُسٌ', 'تجانس', 'مصدر', 'جنس', 'تجانس', 'تجنس', 'مص. تَجَانَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تجَانُسٌ-تجَانُسٌ [ج ن س] (مص. تَجَانَسَ). 1.""بَيْنَهُمَا تَجَانُسٌ كَبِيٌر"" : تَشَابُهٌ. 2.""تَجَانُسُ الأَلْوَانِ"" : تَقَارُبُهَا، تَلاَؤُمُهَا. ""مَعَ التَّجَانُسِ التَّآنُسُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18655, 'تَجَاهُرٌ', 'تجاهر', 'مصدر', 'جهر', 'تجاهر', 'تجهر', 'مص. تَجَاهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَاهُرٌ-تَجَاهُرٌ [ج هـ ر] (مص. تَجَاهَرَ). ""التَّجَاهُرُ بِالأَمْرِ"": التَّظَاهُرُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18656, 'تَجَاهُلٌ', 'تجاهل', 'مصدر', 'جهل', 'تجاهل', 'تجهل', 'مص. تَجَاهَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَاهُلٌ-تَجَاهُلٌ [ج هـ ل] (مص. تَجَاهَلَ). 1.""تَجَاهُلُ الرَّجُلِ"" : إِظْهَارُهُ عَدَمَ مَعْرِفَتِهِ وَهُوَ يَعْرِفُهُ. 2.""تَجَاهُلُ الأَوَامِرِ"": اللاَّمُبَالاَةُ بِهَا وَطَرْحُهَا جَانِباً مَعَ العِلْمِ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18657, 'تَجَاوُبٌ', 'تجاوب', 'مصدر', 'جوب', 'تجاوب', 'تجب', 'مص. تَجَاوَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَاوُبٌ-تَجَاوُبٌ [ ج و ب] (مص. تَجَاوَبَ). ""حَصَلَ بَيْنَهُمَا تَجَاوُبٌ عَمِيقٌ"" : تَفَاهُمٌ، اِنْسِجَامٌ، تَوَافُقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18658, 'تَجَاوُزٌ', 'تجاوز', 'مصدر', 'جوز', 'تجاوز', 'تجز', 'مص. تَجَاوَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَاوُزٌ-تَجَاوُزٌ [ج و ز] (مص. تَجَاوَزَ). 1.""تَجَاوُزُ عَتَبَةِ البَيْتِ"" : تَخَطِّيهَا. 2.""التَّجَاوُزُ عَنِ السَّيِّئَاتِ"" : إِغْضَاءُ الطَّرْفِ عَنْهَا. 3.""تَجَاوُزُ الحُدُودِ"" : الْمُبَالَغَةُ، الإِسْرَافُ، الإِفْرَاطُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18659, 'تَجَشُّمٌ', 'تجشم', 'مصدر', 'جشم', 'تجشم', 'تجشم', 'مص. تَجَشَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَشُّمٌ-تَجَشُّمٌ [ج ش م] (مص. تَجَشَّمَ). 1.""تَجَشُّمُ الْمَخَاطِرِ"" : التَّعَرُّضُ لَهَا عَلَى الرَّغْمِ مِنْ خُطُورَتِهَا. 2.""تَجَشُّمُ مَشَاقِّ السَّفَرِ"" : تَحَمُّلُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18660, 'تَجَدُّدٌ', 'تجدد', 'مصدر', 'جدد', 'تجدد', 'تجد', 'مص. تَجَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَدُّدٌ-تَجَدُّدٌ [ج د د] (مص. تَجَدَّدَ). 1.""تَجَدُّدُ الْمَطَالِبِ"": إِعَادَةُ طَرْحِهَا وَالْمُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18661, 'تَجَذُّفٌ', 'تجذف', 'مصدر', 'جذف', 'تجذف', 'تجذف', 'مص. تَجَذَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَذُّفٌ-تَجَذُّفٌ [ج ذ ف] (مص. تَجَذَّفَ). ""التَّجَذُّفُ فِي السَّيْرِ"" : الإِسْرَاعُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18662, 'تِجَارَةٌ', 'تجارة', 'مصدر', 'تجر', 'تجارة', 'تجرة', 'مص. تَجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تِجَارَةٌ-تِجَارَةٌ [ت ج ر] (مص. تَجَرَ). 1.""مَا يَزَالُ يَبْحَثُ عَنْ تِجَارَةٍ مُرْبِحَةٍ"" : البَيْعُ وَال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18663, 'تَجَرُّدٌ', 'تجرد', 'مصدر', 'جرد', 'تجرد', 'تجرد', 'مص. تَجَرَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَرُّدٌ-تَجَرُّدٌ [ج ر د] (مص. تَجَرَّدَ). 1.""التَّجَرُّدُ مِنَ الْمَلاَبِسِ"" : التَّعَرِّي... 2.""قَدَّمَ شَهَادَتَهُ أَمَامَ القَاضِي بِتَجَرُّدٍ"" : بِلا تَحَيُّزٍ. 3.""التَّجَرُّدُ عَنِ الأَهْوَاءِ"" : التَّحَرُّرُ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18664, 'تَجَرُّعٌ', 'تجرع', 'مصدر', 'جرع', 'تجرع', 'تجرع', 'مص. تَجَرَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَرُّعٌ-تَجَرُّعٌ [ج ر ع] (مص. تَجَرَّعَ). ""تَجَرّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18665, 'تَجَزُّؤٌ', 'تجزؤ', 'مصدر', 'جزأ', 'تجزء', 'تجز', 'مص. تَجَزَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَجَزُّؤٌ-تَجَزُّؤٌ [ج ز أ] (مص. تَجَزَّأَ). ""تَجَزُّؤُ قِطْعَةٍ"" : اِنْقِسَامُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18666, 'تَجَسُّدٌ', 'تجسد', 'مصدر', 'جسد', 'تجسد', 'تجسد', 'مص. تَجَسَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَسُّدٌ-تَجَسُّدٌ [ج س د] (مص. تَجَسَّدَ). 1.""تَجَسُّدُ الصُّورَةِ"" : تَجَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18667, 'تَجَسُّسٌ', 'تجسس', 'مصدر', 'جسس', 'تجسس', 'تجس', 'مص. تَجَسَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَسُّسٌ-تَجَسُّسٌ [ج س س] (مص. تَجَسَّسَ). ""شَبَكَةُ تَجَسُّسٍ"" : شَبَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18668, 'تَجَسُّمٌ', 'تجسم', 'مصدر', 'جسم', 'تجسم', 'تجسم', 'مص. تَجَسَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَسُّمٌ-تَجَسُّمٌ [ج س م] (مص. تَجَسَّمَ). ""تَجَسُّمُ الصُّورَةِ"": تَجَسُّدُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18669, 'تَجَنُّنٌ', 'تجنن', 'مصدر', 'جنن', 'تجنن', 'تجن', 'مص. تَجَنَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَنُّنٌ-تَجَنُّنٌ [ج ن ن] (مص. تَجَنَّنَ). "" أَوْقَعَهُ التَّجَنُّنُ فِي الضَّيَاعِ"" : الجُنُونُ، فِقْدَانُ العَقْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18670, 'تَجَعُّدٌ', 'تجعد', 'مصدر', 'جعد', 'تجعد', 'تجعد', 'مص. تَجَعَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَعُّدٌ-تَجَعُّدٌ [ج ع د] (مص. تَجَعَّدَ). 1.""تَجَعُّدُ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18671, 'تَجَلُّدٌ', 'تجلد', 'مصدر', 'جلد', 'تجلد', 'تجلد', 'مص. تَجَلَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَلُّدٌ-تَجَلُّدٌ [ج ل د] (مص. تَجَلَّدَ). ""أَظْهَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18672, 'تَجَلُّلٌ', 'تجلل', 'مصدر', 'جلل', 'تجلل', 'تجل', 'مص. تَجَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَلُّلٌ-تَجَلُّلٌ [ج ل ل] (مص. تَجَلَّلَ). 1.""تَجَلُّلُ الرَّجُلِ"" : تَعَظُّمُهُ. 2.""تَمَكَّنَ مِنْهُ البَرْدُ القَارِسُ بِالرَّغْمِ مِنْ تَجَلُّلِهِ بِغِطَاءٍ مِنْ صُوفٍ"" : تَغَطِّيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18673, 'تَجَلِّي', 'تجلي', 'مصدر', 'جلو', 'تجلي', 'تجل', 'مص. تَجَلَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R0', '', '', '', '', '', '', '"تَجَلٍّ-تَجَلٍّ، التَّجَلِّي [ج ل و] (مص. تَجَلَّى). 1.""تَجَلِّي الحَقِيقَةِ"" : ظُهُورُهَا وَانْكِشَافُهَا. 2.""يَعِيشُ الصُّوفِيُّ لَحْظَةَ التَّجَلِّي"" : مَا يَنْكَشِفُ فِي قَلْبِ الصُّوفِيِّ مِنْ أَسْرَارِ الغُيُوبِ، إِشْرَاقُ ذَاتِ اللهِ وَصِفَاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18674, 'تَجَمُّعٌ', 'تجمع', 'مصدر', 'جمع', 'تجمع', 'تجمع', 'مص. تَجَمَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَمُّعٌ-تَجَمُّعٌ [ج م ع] (مص. تَجَمَّعَ). ""تَجَمُّعُ النَّاسِ فِي السَّاحَةِ"" : اِحْتِشَادُهُمْ، تَجَمْهُرُهُمْ. ""يُشَارِكُ فِي كُلِّ تَجَمُّعٍ سِيَاسِيٍّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18675, 'تَجَمُّلٌ', 'تجمل', 'مصدر', 'جمل', 'تجمل', 'تجمل', 'مص. تَجَمَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَمُّلٌ-تَجَمُّلٌ [ج م ل] (مص. تَجَمَّلَ). 1.""لاَ تُظْهِرْ تَجَمُّلاً فِي غَيْرِ مُنَاسَبَةٍ"" : التَّزَيُّنُ وَالْمُبَالَغَةُ فِي ذَلِكَ. 2.""لَمْ يَكُنْ أَمَامَهُ إِلاَّ التَّجَمُّلُ"" : التَّصَبُّرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18676, 'تَجَمْهُرٌ', 'تجمهر', 'مصدر', 'جمه', 'تجمهر', 'تجمهر', 'مص. تَجَمْهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَمْهُرٌ-تَجَمْهُرٌ [ج م هـ] (مص. تَجَمْهَرَ). ""أَثَارَ تَجَمْهُرُ النَّاسِ فَوْضىً فِي الشَّارِعِ"" : تَجَمُّعُهُمْ، اِحْتِشَادُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18677, 'تَجَنُّبٌ', 'تجنب', 'مصدر', 'جنب', 'تجنب', 'تجنب', 'مص. تَجَنَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَنُّبٌ-تَجَنُّبٌ [ج ن ب] (مص. تَجَنَّبَ). ""نَبَّهَهُ إِلَى ضَرُورَةِ تَجَنُّبِ طَرِيقِ الأَشْرَارِ"" : البُعْدُ، الابْتِعَادُ عَنْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18678, 'تَجَنُّدٌ', 'تجند', 'مصدر', 'جند', 'تجند', 'تجند', 'مص. تَجَنَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَنُّدٌ-تَجَنُّدٌ [ج ن د] (مص. تَجَنَّدَ). 1.""لَمْ يَكُنْ بُدٌّ مِنْ تَجَنُّدِ الشَّبابِ لِلدِّفَاعِ عَنِ الوَطَنِ"" : الدُّخُولُ فِي سِلْكِ الجُنْدِيَّةِ لِيَصِيرُوا جُنُوداً. 2. ""دَعَاهُمْ إِلَى التَّجَنُّدِ لِلْمَعْرَكَةِ"" : التَّأَهُّبِ وَالاسْتِعْدَادِ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18679, 'تَحَاثٌّ', 'تحاث', 'مصدر', 'حثث', 'تحاث', 'تحث', 'مص. تَحَاثَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَاثٌّ-تَحَاثٌّ [ح ث ث] (مص. تَحَاثَّ). ""التَّحَاثُّ عَلَى العَمَلِ"" : التَّحاضُّ عَليه، الحَضُّ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18680, 'تَجَنِّي', 'تجني', 'مصدر', 'جني', 'تجني', 'تجن', 'مص. تَجَنَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَجَنٍّ-تَجَنٍّ، التَّجَنِّي [ج ن ي] (مص. تَجَنَّى). 1.""التَّجَنِّي عَلَى الرَّجُلِ"" : اِتِّهَامُهُ بِجِنَايَةٍ لَمْ يَرْتَكِبْهَا. ""لاَ يَحِقُّ لَكَ التَّجَنِّي عَلَى أَيِّ إِنْسَانٍ مِنْ دُونِ حُجَّةٍ أَوْ إِثْبَاتٍ"". 2.""تَجَنِّي الثِّمَارِ"" : قَطْفُهَا، جَنْيُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18681, 'تَجَهُّزٌ', 'تجهز', 'مصدر', 'جهز', 'تجهز', 'تجهز', 'مص. تَجَهَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَهُّزٌ-تَجَهُّزٌ [ج هـ ز] (مص. تَجَهَّزَ). 1."" أُمِرَ الجَيْشُ بِالتَّجْهِيزِ لِلْمَعْرَكَةِ"" : التَّهَيُّؤُ وَالاِسْتِعْدَادُ لَهَا. 2.""تَجَهُّزُ القَافِلَةِ لِلسَّفَرِ"" : تَحْضِيُرهَا لَوَازِمِ السَّفَرِ أُهْبَةً وَاسْتِعْدَاداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18682, 'تَجَهُّمٌ', 'تجهم', 'مصدر', 'جهم', 'تجهم', 'تجهم', 'مص. تَجَهَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَهُّمٌ-تَجَهُّمٌ [ج هـ م] (مص. تَجَهَّمَ). ""رَآهُ فِي تَجَهُّمٍ"": فِي عُبُوسٍ. ""وَجَدَهُ فِي لَحْظَةِ تَجَهُّمٍ وَغَضَبٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18683, 'تَجَوُّدٌ', 'تجود', 'مصدر', 'جود', 'تجود', 'تجد', 'مص. تَجَوَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَوُّدٌ-تَجَوُّدٌ [ج و د] (مص. تَجَوَّدَ). 1.""يَحْرِصُ عَلَى التَّجَوُّدِ فِي صِنَاعَتِهِ"" : عَلَى الإِتْقاَنِ وَالجَوْدَةِ. 2.""جَاءَ فِي لِبَاسٍ فِيهِ تَجَوُّدٌ وَأَنَاقَةٌ"" : فِيهِ اخْتِيَارٌ يَنِمُّ عَنْ ذَوْقٍ جَيِّدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18684, 'تَجَوُّزٌ', 'تجوز', 'مصدر', 'جوز', 'تجوز', 'تجز', 'مص. تَجَوَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَوُّزٌ-تَجَوُّزٌ [ج و ز] (مص. تَجَوَّزَ). 1.""التَّجَوُّزُ فِي الأَمْرِ"": اِحْتِمَالُهُ. 2."" التَّجَوُّزُ عَنِ الأَخْطَاءِ"" : تَجَاوُزُهَا وَالتَّغَاضِي عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18685, 'تَجَوُّعٌ', 'تجوع', 'مصدر', 'جوع', 'تجوع', 'تجع', 'مص. تَجَوَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَوُّعٌ-تَجَوُّعٌ [ج و ع] (مص. تَجَوَّعَ). ""يُفَضِّلُ التَّجَوُّعَ عَلَى الاسْتِعْطَاءِ"" : تَعَمُّدُ الجُوعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18686, 'تَجَوُّلٌ', 'تجول', 'مصدر', 'جول', 'تجول', 'تجل', 'مص. تَجَوَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجَوُّلٌ-تَجَوُّلٌ [ج و ل] (مص. تَجَوَّلَ). 1.""خَرَجَ لِلتَّجَوُّلِ فِي الْمَدِينَةِ لَيْلاً"" : الطَّوَافُ فِيهَا وَالتَّفَسُّحُ فِي أَرْجَائِهَا. 2.""تَقَرَّرَ حَظْرُ التَّجَوُّلِ فِي الْمَدِينَةِ"" : قَرَارٌ حُكُومِيٌّ يَمْنَعُ عَلَى النَّاسِ الخُرُوجَ مِنْ بُيُوتِهِمْ عِنْدَ الإِعْلاَنِ عَنْ حَالَةِ الطَّوَارِئِ. ""يُمْكِنُ التَّجَوُّلُ بِحُرِّيَّةٍ فِي أَرْجَاءِ البِلادِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18687, 'تَحَابٌّ', 'تحاب', 'مصدر', 'حبب', 'تحاب', 'تحب', 'مص. تَحَابَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَابٌّ-تَحَابٌّ [ح ب ب] (مص. تَحَابَّ). ""اِمْتَازَتْ عَلاَقَتُهُمَا بِالتَّحَابِّ"" : حُبُّ أَحَدِهِمَا لِلآخَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18688, 'تَحَاتٌّ', 'تحات', 'مصدر', 'حتت', 'تحات', 'تحت', 'مص. تَحَاتَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَاتٌّ-تَحَاتٌّ [ح ت ت] (مص. تَحَاتَّ). 1.""تَحَاتُّ الأَسْنَانِ"" : تَآكُلُهَا. 2.""تَحَاتُّ أَوْرَاقِ الشَّجَرِ"" : تَنَاثُرُهَا، سُقُوطُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18689, 'تَحَاقُدٌ', 'تحاقد', 'مصدر', 'حقد', 'تحاقد', 'تحقد', 'مص. تَحَاقَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَاقُدٌ-تَحَاقُدٌ [ح ق د] (مص. تَحَاقَدَ). ""لاَ فَائِدَةَ مِنَ التَّحَاقُدِ بَيْنَ الأَصْدِقَاءِ"" : تَبَادُلُ الحِقْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18690, 'تَحَاجٌّ', 'تحاج', 'مصدر', 'حجج', 'تحاج', 'تحج', 'مص. تَحَاجَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَاجٌّ-تَحَاجٌّ [ح ج ج] (مص. تَحَاجَّ). ""أَظْهَرَ الوَلَدَانِ تَحَاجّاً مَا بَعْدَهُ مِنْ تَحَاجٍّ"" : تَخَاصُماً، تَجَادُلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18691, 'تَحَاجي', 'تحاجي', 'مصدر', 'حجو', 'تحاجي', 'تحج', 'مص. تَحَاجَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَحَاجٍ-تَحَاجٍ، التَّحَاجِي [ح ج و] (مص. تَحَاجَى). ""اِجْتَمَعُوا لِلتَّحَاجِي"" : لِيَحْكِيَ كُلُّ وَاحِدٍ مِنْهُمَا أُحْجِيَّةً لِلْآخَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18692, 'تَحَادُثٌ', 'تحادث', 'مصدر', 'حدث', 'تحادث', 'تحدث', 'مص. تَحَادَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَادُثٌ-تَحَادُثٌ [ح د ث] (مص. تَحَادَثَ). 1.""فَضَّلُوا التَّحَادُثَ عَلَى التَّنَاحُرِ"" : تَبَادُلَ الحَدِيثِ. 2.""اِنْجَرُّوا إِلَى التَّحَادُثِ بِالحَادِثِ"" : الإِخْبَارُ وَالتَّحَدُّثُ بِهِ فِيمَا بَيْنَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18693, 'تَحَاذِي', 'تحاذي', 'مصدر', 'حذو', 'تحاذي', 'تحذ', 'مص. تَحَاذَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَحَاذٍ-تَحَاذٍ، التَّحَاذِي [ح ذ و] (مص. تَحَاذَى). ""نُقْطَةُ التَّحَاذِي"" : التَّقَابُلِ وَجْهاً لِوَجْهٍ، التَّمَاسِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18694, 'تَحَارُبٌ', 'تحارب', 'مصدر', 'حرب', 'تحارب', 'تحرب', 'مص. تَحَارَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَارُبٌ-تَحَارُبٌ [ح ر ب] (مص. تَحَارَبَ). ""تَحَارُبُ الجَيْشَيْنِ"" : تَقَاتُلُهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18695, 'تَحَاسُبٌ', 'تحاسب', 'مصدر', 'حسب', 'تحاسب', 'تحسب', 'مص. تَحَاسَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَاسُبٌ-تَحَاسُبٌ [ح س ب] (مص. تَحَاسَبَ). ""تَحَاسُبُ الصَّدِيقَيْنِ فَضِيلَةٌ"" : مُحَاسَبَةُ كُلِّ وَاحِدٍ مِنْهُمَا الآخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18696, 'تَحَاسُدٌ', 'تحاسد', 'مصدر', 'حسد', 'تحاسد', 'تحسد', 'مص. تَحَاسَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَاسُدٌ-تَحَاسُدٌ [ح س د] (مص. تَحَاسَدَ). ""لاَ شَيْءَ يَدْعُو إِلَى التَّحَاسُدِ"" : إِلَى الغَيْرَةِ وَالحَسَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18697, 'تَحَاشُدٌ', 'تحاشد', 'مصدر', 'حشد', 'تحاشد', 'تحشد', 'مص. تَحَاشَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَاشُدٌ-تَحَاشُدٌ [ح ش د] (مص. تَحَاشَدَ). ""قَرَّرُوا التَّحَاشُدَ وَسَطَ السَّاحَةِ العُمُومِيَّةِ"" : الاحْتِشَادَ، التَّجَمُّعَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18698, 'تَحَاشِي', 'تحاشي', 'مصدر', 'حشي', 'تحاشي', 'تحش', 'مص. تَحَاشَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَحَاشٍ-تَحَاشٍ، التَّحَاشِي [ح ش ي] (مص. تَحَاشَى). ""فَضَّلَ تَحَاشِيَهُ عَلَى أَنْ يَصْطَدِمَ بِهِ"" : تَجَنُّبَهُ. ""أُرَكِّبُ جُدَدَ القَوْلِ مِنْ غَيْرِ تَقِيَّةٍ وَلاَ تَحَاشٍ"". (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18699, 'تَحَاكٌّ', 'تحاك', 'مصدر', 'حكك', 'تحاك', 'تحك', 'مص. تَحَاكَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَاكٌّ-تَحَاكٌّ [ح ك ك] (مص. تَحَاكَّ). 1.""تَحَاكُّ الرَّجُلَيْنِ"": حَكُّ أَحَدِهِمَا الآخَرَ. 2.""تَحاكُّ الأَسْنَانِ"" : اِصْطِكَاكُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18700, 'تَحَاكُمٌ', 'تحاكم', 'مصدر', 'حكم', 'تحاكم', 'تحكم', 'مص. تَحَاكَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَاكُمٌ-تَحَاكُمٌ [ح ك م] (مص. تَحَاكَمَ). ""التَّحَاكُمُ خَيْرٌ مِنَ الاسْتِمْرَارِ فِي التَّخَاصُمِ"" : الاحْتِكَامُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18701, 'تَحَالُفٌ', 'تحالف', 'مصدر', 'حلف', 'تحالف', 'تحلف', 'مص. تَحَالَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَالُفٌ-تَحَالُفٌ [ح ل ف] (مص. تَحَالَفَ). ""لَمْ يَكُنْ أَمَامَهُمَا إِلاَّ التَّحَالُفُ ضِدَّ عَدُوِّهِمَا الْمُشْتَرَكِ"" : التَّعَاهُدُ، الاتِّحَادُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18702, 'تَحَامُلٌ', 'تحامل', 'مصدر', 'حمل', 'تحامل', 'تحمل', 'مص. تَحَامَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَامُلٌ-تَحَامُلٌ [ح م ل] (مص. تَحَامَلَ). 1.""وَجَدَ فِي حُكْمِهِ تَحَامُلاً"" : تَحَيُّزاً، ظُلْماً. 2."" لَمْ يَفْهَمْ سَبَبَ تَحَامُلِهِ"" : تَحْمِيلُهُ مَا لاَ يُطَاقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18703, 'تَحَامِي', 'تحامي', 'مصدر', 'حمي', 'تحامي', 'تحم', 'مص. تَحَامَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَحَامٍ-تَحَامٍ، التَّحَامِي [ح م ي] (مص. تَحَامَى). ""وَجَدَ فِي تَحَامِي الإِثْمِ نَجَاةً"" : تَجَنُّبُ الإِثْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18704, 'تَحَاوُرٌ', 'تحاور', 'مصدر', 'حور', 'تحاور', 'تحر', 'مص. تَحَاوَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَاوُرٌ-تَحَاوُرٌ [ح و ر] (مص. تَحَاوَرَ). 1.""اِخْتَارُوا التَّحَاوُرَ فِيمَا بَيْنَهُمْ "" : إِجْرَاءُ الحِوَارِ فِيمَا بَيْنَهُمْ. 2.""وَجَدُوا فِي التَّحَاوُرِخَيْرَ وَسِيلَةٍ لِحَلِّ نِزَاعِهِمْ"" : التَّجَادُلِ، التَّفَاهُمِ عَنْ طَرِيقِ الحِوَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18705, 'تَحَبُّبٌ', 'تحبب', 'مصدر', 'حبب', 'تحبب', 'تحب', 'مص. تَحَبَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَبُّبٌ-تَحَبُّبٌ [ح ب ب] (مص. تَحَبَّبَ). ""أَرَادَ التَّحَبُّبَ إِلَيْهِ"" : التَّوَدُّدَ إِلَيْهِ، إِظْهَارَ الْمَحَبَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18706, 'تَحَبُّرٌ', 'تحبر', 'مصدر', 'حبر', 'تحبر', 'تحبر', 'مص. تَحَبَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَبُّرٌ-تَحَبُّرٌ [ح ب ر] (مص. تَحَبَّرَ). ""تَحَبُّرُ الجِلْدِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18707, 'تَحَتُّمٌ', 'تحتم', 'مصدر', 'حتم', 'تحتم', 'تحتم', 'مص. تَحَتَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَتُّمٌ-تَحَتُّمٌ [ح ت م] (مص. تَحَتَّمَ). ""تَحَتُّمُ أَمْرٍ مَّا"" : فَرْضُهُ، وُجُوبُهُ، لُزُومُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18708, 'تَحَجُّرٌ', 'تحجر', 'مصدر', 'حجر', 'تحجر', 'تحجر', 'مص. تَحَجَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَجُّرٌ-تَحَجُّرٌ [ح ج ر] (مص. تَحَجَّرَ). 1.""تَحَجُّرُ جِذْرِ الشَّجَرَةِ"" : تَحَوُّلُهُ إِلَى حَجَرٍ. 2.""تَحَجُّرُ القَلْبِ"" : تَحَوُّلُهُ إِلَى قَلْبٍ قَاسٍ صَلْبٍ. 3.""تَحَجُّرُ النَّهْرِ"" : أَيْ صَيْرُ أَحْجارِهِ كَثيرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18709, 'تَحَدُّبٌ', 'تحدب', 'مصدر', 'حدب', 'تحدب', 'تحدب', 'مص. تَحَدَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَدُّبٌ-تَحَدُّبٌ [ح د ب] (مص. تَحَدَّبَ). 1.""تَحَدُّبُ ظَهْرِ الرَّجُلِ"" : صَارَ أَحْدَبَ. 2.""تَحَدُّبُ الأُمِّ عَلَى ابْنِهَا"" : حَضْنُهُ وَالعَطْفُ عَلَيْهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18710, 'تَحَدُّثٌ', 'تحدث', 'مصدر', 'حدث', 'تحدث', 'تحدث', 'مص. تَحَدَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَدُّثٌ-تَحَدُّثٌ [ح د ث] (مص. تَحَدَّثَ). 1.""التَّحَدُّثُ إِلَى النَّاسِ فَنٌّ"" : التَّكَلُّمُ، مُخَاطَبَتُهُمْ، تَنَاوُلُ الكَلاَمِ. 2.""رَفَضَ التَّحَدُّثَ بِمَا جَرَى"" : الإِخْبَارَ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18711, 'تَحَدُّرٌ', 'تحدر', 'مصدر', 'حدر', 'تحدر', 'تحدر', 'مص. تَحَدَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَدُّرٌ-تَحَدُّرٌ [ح د ر] (مص. تَحَدَّرَ). 1.""رَأَى تَحَدُّرَهُ مِنْ أَعْلَى الجَبَلِ"" : هُبُوطَهُ. 2.""تَحَدُّرُ الدَّمْعِ"" : سَيَلاَنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18712, 'تَحَدِّي', 'تحدي', 'مصدر', 'حدي', 'تحدي', 'تحد', 'مص. تَحَدَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَحَدٍّ-تَحَدٍّ، التَّحَدِّي [ح د ي] (مص. تَحَدَّى). 1.""وَاجَهَ خَصْمَهُ بِالتَّحَدِّي"" : بِدَعْوَتِهِ إِلَى التَّبَارِي. 2.""لَمْ يَكُنْ أَمَامَهُ إِلاَّ تَحَدِّي الْمَخَاطِرِ"" : مُوَاجَهَتُهَا، مُجَابَهَتُهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18713, 'تَحَذُّقٌ', 'تحذق', 'مصدر', 'حذق', 'تحذق', 'تحذق', 'مص. تَحَذَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَذُّقٌ-تَحَذُّقٌ [ح ذ ق] (مص. تَحَذَّقَ). ""تَحَذُّقُ الصَّانِعِ"" : تَكَلُّفُهُ الحِذْقَ، تَظَاهُرُهُ بِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18714, 'تَحَذْلُقٌ', 'تحذلق', 'مصدر', 'حذلق', 'تحذلق', 'تحذلق', 'مص. تَحَذْلَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَذْلُقٌ-تَحَذْلُقٌ [ح ذ ل ق] (مص. تَحَذْلَقَ). 1.""أَظْهَرَ تَحَذْلُقًا فِي حَدِيثِهِ"" : تَكَلُّفا وَتَصَنُّعاً فِي إِظْهَارِ الْمَهَارَةِ وَالحِذْقِ. 2.""وَجَدَ عِنْدَهُ تَحَذْلُقاً فِي مُعَامَلَتِهِ"" : تَظَرُّفاً، تَكَيُّساً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18715, 'تَحَرُّجٌ', 'تحرج', 'مصدر', 'حرج', 'تحرج', 'تحرج', 'مص. تَحَرَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَرُّجٌ-تَحَرُّجٌ [ح ر ج] (مص. تَحَرَّجَ). 1.""وَجَدَ فِي مَوْقِفِهِ تَحَرُّجاً"" : حَرَجاً. 2.""التَّحَرُّجُ مِنْ إِتْيَانِ الآثَامِ فَضِيلَةٌ وَسُلُوكٌ أَخْلاَقِيٌّ"" : تَجَنُّبُهَا. 3.""لَمْ يَجِدْ إِلاَّ التَّحَرُّجَ مِنْ تَحَايُلِهِ"" : تَجَنُّبَهُ مَعَ احْتِمَالِ الْمَشَقَّةِ وَالضَّيْقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18716, 'تَحَرُّرٌ', 'تحرر', 'مصدر', 'حرر', 'تحرر', 'تحر', 'مص. تَحَرَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَرُّرٌ-تَحَرُّرٌ [ح ر ر] (مص. تَحَرَّرَ). 1.""تَحَرُّرُ العَبْدِ"" : اِنْعِتَاقُهُ مِنَ العُبُودِيَّةِ. 2. ""تَحَرُّرُ الشَّعْبِ مِنَ الاسْتِعْمَارِ"" : التَّخَلُّصُ مِنْهُ. 3. ""التَّحَرُّرُ مِنْ كُلِّ قَيْدٍ أَوِ الْتِزَامٍ"" : نَفْضُ اليَدِ مِن..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18717, 'تَحَرُّزٌ', 'تحرز', 'مصدر', 'حرز', 'تحرز', 'تحرز', 'مص. تَحَرَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَرُّزٌ-تَحَرُّزٌ [ح ر ز] (مص. تَحَرَّزَ). 1.""لَمْ يَكُنْ تَحَرُّزُهُ خَوْفاً"" : تَوقِّيهِ، تَجَنُّبُهُ، حَذَرُهُ. ""الثَّبَاتُ هُو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18718, 'تَحَرُّشٌ', 'تحرش', 'مصدر', 'حرش', 'تحرش', 'تحرش', 'مص. تَحَرَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَرُّشٌ-تَحَرُّشٌ [ح ر ش] (مص. تَحَرَّشَ). 1.""أَرَادَ التَّحَرُّشَ بِهِ"" : اسْتِفْزَازَهُ وَإِثَارَةَ حَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18719, 'تَحَصُّلٌ', 'تحصل', 'مصدر', 'حصل', 'تحصل', 'تحصل', 'مص. تَحَصَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَصُّلٌ-تَحَصُّلٌ [ح ص ل] (مص. تَحَصَّلَ). 1.""تَحَصُّلُ الْمَالِ"" : تَجَمُّعُهُ. 2.""تَحَصُّلُ العِلْمِ"" : حُصُولُهُ، ثَبْتُهُ. 3.""تَحَصُّلُ الرِّبْحِ"" : اِسْتِخْلاَصُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18720, 'تَحَرُّقٌ', 'تحرق', 'مصدر', 'حرق', 'تحرق', 'تحرق', 'مص. تَحَرَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَرُّقٌ-تَحَرُّقٌ [ح ر ق] (مص. تَحَرَّقَ). 1.""تَحَرُّقُ الجِسْمِ"": اِحْتِرَاقُهُ بِالنَّارِ. 2.""تَحَرُّقُ النَّارِ"" : اِلْتِهاَبُهَا. 3.""تَحَرُّقُ النَّفْسِ إِلَى لِقَاءِ الأَحِبَّةِ"" : تَشَوُّقُهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18721, 'تَحَرُّكٌ', 'تحرك', 'مصدر', 'حرك', 'تحرك', 'تحرك', 'مص. تَحَرَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَرُّكٌ-تَحَرُّكٌ [ح ر ك] (مص. تَحَرَّكَ). 1.""تَحَرُّكُ القِطَارِ"" : بِدَايَةُ انْطِلاقِهِ. 2.""تَحَرُّكُ أَغْصَانِ الشَّجَرَةِ"" : اِهْتِزَازُهَا. 3.""تَحَرُّكُ عَوَاطِفِهِ شَوْقاً"" : اِخْتِلاَجُهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18722, 'تَحَرِّي', 'تحري', 'مصدر', 'حري', 'تحري', 'تحر', 'مص. تَحَرَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. تَحَرَّى). 1.""سَعَى إلَى تَحَرِّي الحَقِيقَةِ : تَقَصِّيهَا"". 2.""تَحَرِّي الأَخْبَارِ وَالْمَعْلُومَات ضَرُورَةٌ عِلْمِيَّةٌ"" : البَحْثُ عَنْ مَصَادِرِهَا الصَّحِيحَةِ. ""ظَلَّتِ التَّحَرِّيَاتُ جَارِيَةً نَهاَراً كَامِلاً"" ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18723, 'تَحَزُّمٌ', 'تحزم', 'مصدر', 'حزم', 'تحزم', 'تحزم', 'مص. تَحَزَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَزُّمٌ-تَحَزُّمٌ [ح ز م] (مص. تَحَزَّمَ). 1.""أَظْهَرَ تَحَزُّماً لِلْعَمَلِ"" : تَهَيُّؤاً وَاسْتِعْدَاداً عَمَلِيّاً. 2.""تَحَزُّمُ الْمَرْأَةِ"" : وَضْعُهَا لِلْحِزَامِ اسْتِعْدَاداً وَتَهَيُّؤاً لِعَمَلٍ مَّا. 3.""وَاجَهَ الأَمْرَ بِتَحَزُّمٍ"" : بِحَزْمٍ، بِتَصَرُّفٍ حَازِمٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18724, 'تَحَسُّرٌ', 'تحسر', 'مصدر', 'حسر', 'تحسر', 'تحسر', 'مص. تَحَسَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَسُّرٌ-تَحَسُّرٌ [ح س ر] (مص. تَحَسَّرَ). 1."" أَبَانَ عَنْ تَحَسُّرِهِ مِنْ خِلاَلِ كَلاَمِهِ"" : تَلَهُّفِهِ، شُعُورِهِ بِالحَنِينِ إِلَى ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18725, 'تَحَسُّسٌ', 'تحسس', 'مصدر', 'حسس', 'تحسس', 'تحس', 'مص. تَحَسَّسَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَسُّسٌ-تَحَسُّسٌ [ح س س] (مص. تَحَسَّسَ ). 1.""تَحَسُّسُ الكَلاَمِ"" : تَسَمُّعُهُ وَالإِصْغَاءُ إِلَيْهِ. 2.""تَحَسُّسُ الشَّيْءِ بِاليَدِ"" : تَبَيُّنُ شَكْلِهِ وَنَوْعِهِ، تَعَرُّفُهُ. 3. ""طَلَبَ مِنْهُ تَحَسُّسَ خُطُوَاتِهِ"" : تَتَبُّعُهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18726, 'تَحَسُّنٌ', 'تحسن', 'مصدر', 'حسن', 'تحسن', 'تحسن', 'مص. تَحَسَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَسُّنٌ-تَحَسُّنٌ [ح س ن] (مص. تَحَسَّنَ). ""حَالَتُهُ الصِّحِّيَّةُ فِي تَحَسُّنٍ مُسْتَمِرٍّ"" : فِي تَدَرُّجٍ مِنْ حَسَنٍ إِلَى أَحْسَنَ، فِي تَقَدُّمٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18727, 'تَحَسِّي', 'تحسي', 'مصدر', 'حسي', 'تحسي', 'تحس', 'مص. تَحَسَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَحَسٍّ-تَحَسٍّ، التَّحَسِّي [ح س ي] . (مص. تَحَسَّى). 1.""وَجَدَ لَذَّةً فِي تَحَسِّي قَهْوَةِ الصَّبَاحِ"" : شُرْبُهَا بِتَمَهُّلٍ وَبُطْءٍ. 2.""جَلَسَ يَتَأَمَّلُ تَحَسِّيَ الطَّائِرِ لِلْمَاءِ"" : تَنَاوُلَهُ لِلْمَاءِ بِمِنْقَارِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18728, 'تَحَشُّدٌ', 'تحشد', 'مصدر', 'حشد', 'تحشد', 'تحشد', 'مص. تَحَشَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَشُّدٌ-تَحَشُّدٌ [ح ش د] (مص. تَحَشَّدَ). ""تَحَشُّدُ الجُمْهُورِ"": تَجَمُّعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18729, 'تَحَلُّقٌ', 'تحلق', 'مصدر', 'حلق', 'تحلق', 'تحلق', 'مص. تَحَلَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَلُّقٌ-تَحَلُّقٌ [ح ل ق] (مص. تَحَلَّقَ). 1.""تَحَلُّقُ الجُمْهُورِ حَوْلَ الخَطِيبِ"" : تَكْوِينُ حَلَقَةٍ دَائِرَةٍ حَوْلَهُ. 2.""تَحَلُّقُ القَمَرِ"" : تَكَوُّنُ دَائِرَةٍ حَوْلَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18730, 'تَحَصُّنٌ', 'تحصن', 'مصدر', 'حصن', 'تحصن', 'تحصن', 'مص. تَحَصَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَصُّنٌ-تَحَصُّنٌ [ح ص ن] (مص. تَحَصَّنَ). 1.""تَحَصُّنُ الجُنُودِ بِالقَلْعَةِ"" : الاِحْتِمَاءُ بِهَا، اِتِّخَاذُهَا حِصْناً. 2.""تَحَصُّنُ الْمَرْأَةِ"" : مُحَافَظَتُهَا عَلَى شَرَفِهَا وَعِفَّتِهَا. 3.""تَحَصُّنُ الْمُهْرِ"" : صَيْرُهُ حِصَاناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18731, 'تَحَضُّرٌ', 'تحضر', 'مصدر', 'حضر', 'تحضر', 'تحضر', 'مص. تَحَضَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَضُّرٌ-تَحَضُّرٌ [ح ض ر] (مص. تَحَضَّرَ). ""تَحَضُّرُ البَدَوِيِّ"": تَشَبُّهُهُ بِأَهْلِ الحَضَرِ، تَمَدُّنُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18732, 'تَحَطُّمٌ', 'تحطم', 'مصدر', 'حطم', 'تحطم', 'تحطم', 'مص. تَحَطَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَطُّمٌ-تَحَطُّمٌ [ح ط م] . (مص. تَحَطَّمَ). 1.""شَاهَدَ تَحَطُّمَ الطَّائِرَةِ أَشْلاَءً"" : سُقُوطَهَا وَتَلاَشِيَهَا أَشْلاَءً. 2.""تَحَطُّمُ الآمَالِ"": خَيْبَتُهَا وَعَدَمُ تَحَقُّقِهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18733, 'تَحَفُّزٌ', 'تحفز', 'مصدر', 'حفز', 'تحفز', 'تحفز', 'مص. تَحَفَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَفُّزٌ-تَحَفُّزٌ [ح ف ز] (مص. تَحَفَّزَ). ""تَحَفُّزُ البَطَلِ خَوَّفَ مُنَافِسِيهِ"" : تَهَيُّؤُهُ، اِسْتِعْدَادُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18734, 'تَحَفُّظٌ', 'تحفظ', 'مصدر', 'حفظ', 'تحفظ', 'تحفظ', 'مص. تَحَفَّظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. تَحَفَّظَ). 1.""تَحَفُّظُهُ فِي غَيْرِ مَكَانِهِ"" : اِحْتِرازُهُ، اِحْتِيَاطُهُ. ""بِكُلِّ تَحَفُّظٍ"". 2.""أَنْجَزَ أَعْمَالَهُ بلا تَحَفُّظٍ"" : دُونَ تَرَدُّدٍ. 3.""سَجَّلَ تَحَفُّظَهُ فِي الْمَحْضَرِ"" : اِتَّخَذَ مَوْقِفَ الحِيطَةِ وَالحَذَرِ وَعَدَمِ الْمُوَافَقَةِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18735, 'تَحَقُّقٌ', 'تحقق', 'مصدر', 'حقق', 'تحقق', 'تحق', 'مص. تَحَقَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَقُّقٌ-تَحَقُّقٌ [ح ق ق] (مص. تَحَقَّقَ). 1.""التَّحَقُّقُ مِنَ الأَخْبَارِ"" : التَّأَكُّدُ مِنْ صِحَّتِهَا. 2.""التَّحَقُّقُ مِنَ الْمَعْلُومَاتِ"" : التَّيَقُّنُ مِنْهاَ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18736, 'تَحَكُّمٌ', 'تحكم', 'مصدر', 'حكم', 'تحكم', 'تحكم', 'مص. تَحَكَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَكُّمٌ-تَحَكُّمٌ [ح ك م] (مص. تَحَكَّمَ) . ""التَّحَكُّمُ فِي الشَّيْءِ"" : ضَبْطُهُ وَالتَّمَكُّنُ مِنْهُ، التَّصَرُّفُ فِيه. ""فَقَدَ قُدْرَةَ التَّحَكُّمِ فِي أَعْصَابِهِ"" ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18737, 'تَحَلُّبٌ', 'تحلب', 'مصدر', 'حلب', 'تحلب', 'تحلب', 'مص. تَحَلَّبَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَلُّبٌ-تَحَلُّبٌ [ح ل ب] (مص. تَحَلَّبَ ). 1.""تَحَلُّبُ مَاءِ العَيْنِ"" : سَيَلاَنُهُ. 2.""تَحَلُّبُ الفَمِ"" : سَيَلاَنُ رِيقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18738, 'تَحَلْحُلٌ', 'تحلحل', 'مصدر', 'حلحل', 'تحلحل', 'تحلحل', 'مص. تَحَلْحَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَلْحُلٌ-تَحَلْحُلٌ [ح ل ح ل] (مص. تَحَلْحَلَ). ""تَحَلْحُلُ الرَّجُلِ عَنْ مَوْضِعِهِ"" : تَحَرُّكُهُ، تَزَعْزُعُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18739, 'تَحَيُّزٌ', 'تحيز', 'مصدر', 'حيز', 'تحيز', 'تحز', 'مص. تَحَيَّزَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَيُّزٌ-تَحَيُّزٌ [ح ي ز] (مص. تَحَيَّزَ) . ""مَا هَذَا التَّحَيُّزُ "" : مَا هَذِهِ المُحَابَاةُ ""حُكْمٌ بِلاَ تَحَيُّزٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18740, 'تَحَلُّلٌ', 'تحلل', 'مصدر', 'حلل', 'تحلل', 'تحل', 'مص. تَحَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَلُّلٌ-تَحَلُّلٌ [ح ل ل] . (مص. تَحَلَّلَ). 1.""التَّحَلُّلُ مِنَ اليَمِينِ"" : الخُرُوجُ مِنْ تَبِعَةِ اليَمِيِن بِكَفَّارَةٍ. 2.""تَحَلُّلُ الْمَادَّةِ""(كيما) : تَفَسُّخُ عَنَاصِرِ بَعْضِهَا عَنْ بَعْضٍ أَوِ انْفِصَالُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18741, 'تَحَلِّي', 'تحلي', 'مصدر', 'حلي', 'تحلي', 'تحل', 'مص. تَحَلَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَحَلٍّ-تَحَلٍّ، التَّحَلِّي [ح ل ي] (مص. تَحَلَّى). 1.""تَحَلِّي الْمَرْأَةِ بِالجَوَاهِرِ"" : تَزَيُّنُهَا. 2.""التَّحَلِّي بِالصَّبْرِ"" : الاِتِّصَافُ بِهِ. 3.""اُتْرُكِ التَّحَلِّيَ بِمَا لاَقُدْرَةَ لَكَ عَلَيْهِ"" : الاِدِّعَاءَ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18742, 'تَحَمُّسٌ', 'تحمس', 'مصدر', 'حمس', 'تحمس', 'تحمس', 'مص. تَحَمَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَمُّسٌ-تَحَمُّسٌ [ح م س] (مص. تَحَمَّسَ). 1.""وَجَدَ عِنْدَهُ تَحَمُّساً لِلْمُشَارَكَةِ فِي الْمُبَارَاةِ"" : رَغْبَةً شَدِيدَةً مَمْلُوءةً بِالْحَمَاسِ. 2.""التَّحَمُّسُ لِلْفَرِيقِ الرِّيَاضِيِّ"" : إِثَارَةُ الحَمَاسِ، مُنَاصَرَتُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18743, 'تَحَمُّلٌ', 'تحمل', 'مصدر', 'حمل', 'تحمل', 'تحمل', 'مص. تَحَمَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَمُّلٌ-تَحَمُّلٌ [ح م ل] (مص. تَحَمَّلَ). 1.""لَهُ قُدْرَةٌ عَلَى التَّحَمُّلِ"" : عَلَى التَّجَلُّدِ والصَّبْرِ. 2.""تَحَمُّلُ الْمَسْؤُولِيَّةِ تَكْلِيفٌ لاَ تَشْرِيفٌ"" : الأَخْذُ بِشُؤُونِهَا. 3.""لاَ قُدْرَةَ لَهُ عَلَى تَحَمُّلِ الإِهَانَةِ"" : عَلَى تَقَبُّلِهَا وَالصَّبْرِ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18744, 'تَحَمُّمٌ', 'تحمم', 'مصدر', 'حمم', 'تحمم', 'تحم', 'مص. تَحَمَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَمُّمٌ-تَحَمُّمٌ [ح م م] (مص. تَحَمَّمَ). ""تَحَمُّمُ الوَجْهِ"" : اِسْوِدَادُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18745, 'تَحَنٍّي', 'تحني', 'مصدر', 'حني', 'تحني', 'تحن', 'مص. تَحَنَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَحَنٍّ-تَحَنٍّ، التَّحَنِّي [ح ن ي] (مص. تَحَنَّى). 1.""لَمْ يَسْتَطِعِ التَّحَنِّيَ"" : الاِنْحِنَاء. 2.""تَحَنِّي القَضِيبِ"" : اِعْوِجَاجُهُ. 3.""وَجَدَ عِنْدَهَا كُلَّ التَّحَنِّي"" : كُلَّ العَطْفِ وَالْمَحَبَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18746, 'تَحَوُّزٌ', 'تحوز', 'مصدر', 'حوز', 'تحوز', 'تحز', 'مص. تَحَوَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَوُّزٌ-تَحَوُّزٌ [ح و ز] (مص. تَحَوَّزَ). 1.""التَّحَوُّزُ عَنِ الْمَخَاطِرِ"": التَّنَحِّي عَنْهَا. 2.""تَحَوُّزُ الحَيَّةِ"" : تَلَوِّيهَا. 3.""تَحَوُّزُ أَرَاضٍ جَدِيدَةٍ"" : مِلْكُهَا، ضَمُّهَا إِلَى مَا يَمْلِكُ مِنْ أَرَاضٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18747, 'تَحَوُّلٌ', 'تحول', 'مصدر', 'حول', 'تحول', 'تحل', 'مص. تَحَوَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَوُّلٌ-تَحَوُّلٌ [ح و ل] . (مص. تَحَوَّلَ). 1.""حَدَثَ تَحَوُّلٌ فِي حَيَاتِهِ"" : تَغَيُّرٌ مِنْ وَضْعٍ إِلَى "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18748, 'تَحَيُّرٌ', 'تحير', 'مصدر', 'حير', 'تحير', 'تحر', 'مص. تَحَيَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَيُّرٌ-تَحَيُّرٌ [ح ي ر] (مص. تَحَيَّرَ). 1.""وَقَعَ فِي تَحَيُّرٍ"" : وَقَعَ فِي حَيْرَةٍ وَارْتِبَاكٍ. 2.""وَجَدَ نَفْسَهُ فِي تَحَيُّرٍ عِنْدَ مُفَتَرَقِ الطُّرُقِ"" : عَدَمُ تَبَيُّنِ طَرِيقِهِ وَالاِهْتِدَاءِ إِلَيْهِ. 3.""تَحَيُّرُ الْمَكَانِ بِالْمَاء"" : اِمْتِلاَؤُهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18749, 'تَخَالُطٌ', 'تخالط', 'مصدر', 'خلط', 'تخالط', 'تخلط', 'مص. تَخَالَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَالُطٌ-تَخَالُطٌ [خ ل ط] (مص. تَخَالَطَ). 1.""تَخَالُطُ الْمَوَادِّ"" : اِخْتِلاطُهَا، تَمَازُجُهَا. 2.""تَخَالُطُ القُوَّاتِ فِي الْمَعْرَكَةِ"" : اِشْتِبَاكُهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18750, 'تَحَيُّنٌ', 'تحين', 'مصدر', 'حين', 'تحين', 'تحن', 'مص. تَحَيَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحَيُّنٌ-تَحَيُّنٌ [ح ي ن] ( مص. تَحَيَّنَ). ""تَحَيُّنُ الفُرْصَةِ"" : تَرَقُّبُهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18751, 'تَخَابُثٌ', 'تخابث', 'مصدر', 'خبث', 'تخابث', 'تخبث', 'مص. تَخَابَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَابُثٌ-تَخَابُثٌ [خ ب ث] (مص. تَخَابَثَ) . ""تَخَابُثُ الرَّجُلِ"" : اِدِّعَاؤُهُ الخُبْثَ أَوْ إِظْهَارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18752, 'تَخَابُرٌ', 'تخابر', 'مصدر', 'خبر', 'تخابر', 'تخبر', 'مص. تَخَابَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَابُرٌ-تَخَابُرٌ [خ ب ر] . (مص. تَخَابَرَ). ""قَرَّرَ الرَّجُلاَنِ التَّخَابُرَ فِيمَا بَيْنَهُمَا"" : التَّبَاحُثَ فِيمَا بَيْنَهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18753, 'تَخَاتُلٌ', 'تخاتل', 'مصدر', 'ختل', 'تخاتل', 'تختل', 'مص. تَخَاتَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَاتُلٌ-تَخَاتُلٌ [خ ت ل] (مص. تَخَاتَلَ). ""تَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18754, 'تَخَادُعٌ', 'تخادع', 'مصدر', 'خدع', 'تخادع', 'تخدع', 'مص. تَخَادَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَادُعٌ-تَخَادُعٌ [خ د ع] (مص. تَخَادَعَ). ""لَمْ يَكُنِ التَّخَادُعُ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18755, 'تَخَاصُمٌ', 'تخاصم', 'مصدر', 'خصم', 'تخاصم', 'تخصم', 'مص. تَخَاصَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَاصُمٌ-تَخَاصُمٌ [خ ص م] (مص. تَخَاصَمَ). ""عَادَ الصَّفَاءُ وَالوِئَامُ بَعْدَ التَّخَاصُمِ"" : بَعْدَ تَنَازُعٍ وَاخْتِصَامٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18756, 'تَخَاطُبٌ', 'تخاطب', 'مصدر', 'خطب', 'تخاطب', 'تخطب', 'مص. تَخَاطَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَاطُبٌ-تَخَاطُبٌ [خ ط ب] (مص. تَخَاطَبَ). ""لَمْ يَكُنْ بُدٌّ مِنْ تَخَاطُبِهِمَا"" : مِنْ تَكَالُمِهِمَا وَتَحَادُثِهِمَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18757, 'تَخَاطُرٌ', 'تخاطر', 'مصدر', 'خطر', 'تخاطر', 'تخطر', 'مص. تَخَاطَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَاطُرٌ-تَخَاطُرٌ [خ ط ر] (مص. تَخَاطَرَ). ""نَهَاهُ عَنِ التَّخَاطُرِ"" : عَنِ التَّرَاهُنِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18758, 'تَخَالُصٌ', 'تخالص', 'مصدر', 'خلص', 'تخالص', 'تخلص', 'مص. تَخَالَصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَالُصٌ-تَخَالُصٌ [خ ل ص] (مص. تَخَالَصَ). ""بَيْنَهُمَا وِدٌّ وَتَخَالُصٌ"" : تَصَافٍ وَمَحَبَّةٌ وَوِئَامٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18759, 'تَخَضُّبٌ', 'تخضب', 'مصدر', 'خضب', 'تخضب', 'تخضب', 'مص. تَخَضَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَضُّبٌ-تَخَضُّبٌ [خ ض ب] (مص. تَخَضَّبَ). 1.""تَخَضُّبُ الْمَرْأَةِ بِالحِنَّاءِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18760, 'تَخَالُفٌ', 'تخالف', 'مصدر', 'خلف', 'تخالف', 'تخلف', 'مص. تَخَالَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَالُفٌ-تَخَالُفٌ [خ ل ف] . (مص. تَخَالَفَ). ""التَّخَالُفُ فِي الأَمْرِ"" : التَّعَاكُسُ، التَّضَادُّ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18761, 'تَخَايُلٌ', 'تخايل', 'مصدر', 'خيل', 'تخايل', 'تخل', 'مص. تَخَايَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَايُلٌ-تَخَايُلٌ [خ ي ل] (مص. تَخَايَلَ). 1. ""التَّخَايُلُ فِي الْمَشْيِ"" : التَّبَخْتُرُ. 2. ""أَظْهَرَ تَخَايُلاً أَمَامَ أَصْحَابِهِ"" : تَكَبُّراً. 3. ""تَخَايُلُ الأَشْبَاحِ"" : ظُهُورُهَا كَخَيَالٍ. 4. ""وَجَدَ فِيهِ تَخَايُلاً"" : تَشَابُهاً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18762, 'تَخَبُّؤٌ', 'تخبؤ', 'مصدر', 'خبأ', 'تخبء', 'تخب', 'مص. تَخَبَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَخَبُّؤٌ-تَخَبُّؤٌ [خ ب أ] (مص. تَخَبَّأَ). ""التَّخَبُّؤُ فِي الكَهْفِ"": الاخْتِفَاءُ وَالتَّسَتُّرُ فِيهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18763, 'تَخَبُّطٌ', 'تخبط', 'مصدر', 'خبط', 'تخبط', 'تخبط', 'مص. تَخَبَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَبُّطٌ-تَخَبُّطٌ [خ ب ط] (مص. تَخَبَّطَ). 1.""أَنْقَذَهُ مِنَ التَّخَبُّطِ فِي مَشَاكِلَ عَائِلِيَّةٍ"" : الوُقُوع فِيهَا بِلاَ اهْتِدَاءٍ. 2.""التَّخَبُّطُ فِي العَمَلِ"" : السَّيْرُ فِيهِ بِعَشْوَائِيَّةٍ وَفَوْضىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18764, 'تَخَثُّرٌ', 'تخثر', 'مصدر', 'خثر', 'تخثر', 'تخثر', 'مص. تَخَثَّرَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَثُّرٌ-تَخَثُّرٌ [خ ث ر] (مص. تَخَثَّرَ) . ""تَخَثُّرُ اللَّبَنِ"" : رَوْبُهُ، خَثْرُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18765, 'تَخَرُّجٌ', 'تخرج', 'مصدر', 'خرج', 'تخرج', 'تخرج', 'مص. تَخَرَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَرُّجٌ-تَخَرُّجٌ [خ ر ج] . (مص. تَخَرَّجَ). 1.""التَّخَرُّجُ مِنَ الْمَعْهَدِ"" : إِنْهَاءُ الدِّرَاسَةِ بِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18766, 'تَخَرُّمٌ', 'تخرم', 'مصدر', 'خرم', 'تخرم', 'تخرم', 'مص. تَخَرَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَرُّمٌ-تَخَرُّمٌ [خ ر م] (مص. تَخَرَّمَ). 1.""تَخَرُّمُ الإِنَاءِ"" : اِنْكِسارُهُ. 2.""تَخَرُّمُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18767, 'تَخَشُّعٌ', 'تخشع', 'مصدر', 'خشع', 'تخشع', 'تخشع', 'مص. تَخَشَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَشُّعٌ-تَخَشُّعٌ [خ ش ع] (مص. تَخَشَّعَ). ""كَانَ يُصَلِّي فِي تَخَشُّعٍ"" : فِي قُنُوتٍ وَتَضَرُّعٍ وَعِبَادَةٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18768, 'تَخَشُّنٌ', 'تخشن', 'مصدر', 'خشن', 'تخشن', 'تخشن', 'مص. تَخَشَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَشُّنٌ-تَخَشُّنٌ [خ ش ن] (مص. تَخَشَّنَ). ""تَخَشُّنُ الرَّجُلِ"": وُجُودُ خُشُونَةٍ فِي تَصرُّفِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18769, 'تَخَمٌ', 'تخم', 'مصدر', 'تخم', 'تخم', 'تخم', 'مص. تَخِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَخَمٌ-تَخَمٌ [ت خ م] (مص. تَخِمَ). ""أَكَلَ حَتَّى التَّخَمِ"" : أَيْ إِلَى أَنْ أُصِيبَ بِالتُّخَمَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18770, 'تَخَطُّفٌ', 'تخطف', 'مصدر', 'خطف', 'تخطف', 'تخطف', 'مص. تَخَطَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَطُّفٌ-تَخَطُّفٌ [خ ط ف] (مص. تَخَطَّفَ). ""تَخَطُّفُ الطَّعَامِ"" : اِنْتِزَاعُهُ، خَطْفُهُ، سَلْبُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18771, 'تَخَطِّي', 'تخطي', 'مصدر', 'خطو', 'تخطي', 'تخط', 'مص. تَخَطَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَخَطٍّ-تَخَطٍّ، التَّخَطِّي [خ ط و] (مص. تَخَطَّى). 1.""تَخَطِّي الحُدُودِ"" : تَجَاوُزُهَا، تَعَدِّيهَا. 2.""حَاوَلَ تَخَطِّي أَقْرَانِهِ فِي دِرَاسَتِهِ"" : التَّقَدُّمُ وَالتَّفَوُّقُ عَلَيْهِمْ . 3.""لَهُ القُدْرَةُ عَلَى تَخَطِّي الصِّعَابِ"" : التَّغَلُّبُ عَلَيْهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18772, 'تَخَفِّي', 'تخفي', 'مصدر', 'خفي', 'تخفي', 'تخف', 'مص. تَخَفَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَخَفٍّ-تَخَفٍّ، التَّخَفِّي [خ ف ي] (مص. تَخَفَّى). 1.""بَاءتْ مُحَاوَلَةُ تَخَفِّيهِ بِالفَشَلِ"" : تَنَكُّرِهِ. 2.""التَّخَفِّي عَنِ الأَنْظَارِ"" : التَّسَتُّرُ، التَّوَارِي ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18773, 'تَخَلْخُلٌ', 'تخلخل', 'مصدر', 'خلخل', 'تخلخل', 'تخلخل', 'مص. تَخَلْخَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَلْخُلٌ-تَخَلْخُلٌ [خ ل خ ل] . (مص. تَخَلْخَلَ). 1."" تَخَلْخُلُ أَجْزَاءِ الآلَةِ"" : تَفَكُّكُهَا. 2.""شَعَرَ القَائِدُ بِتَخَلْخُلِ صُفُوفِ الجُنُودِ"" : أَيْ إِصَابَتهَا بِالتَّفَكُّكِ وَالتَّصَدُّعِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18774, 'تَخَلُّصٌ', 'تخلص', 'مصدر', 'خلص', 'تخلص', 'تخلص', 'مص. تَخَلَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَلُّصٌ-تَخَلُّصٌ [خ ل ص] (مص. تَخَلَّصَ). 1.""التَّخَلَّصُ مِنَ القَيْدِ"" : التَّحَرُّرُ مِنْهُ. 2.""سَاعَدَهُ عَلَى التَّخَلُّصِ مِنْ وَرْطَتِهِ"" : عَلَى النَّجَاةِ مِنْهَا. 3.""التَّخَلُّصُ مِنَ الدُّيُونِ"" : تَسْدِيدُهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18775, 'تَخَلُّفٌ', 'تخلف', 'مصدر', 'خلف', 'تخلف', 'تخلف', 'مص. تَخَلَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَلُّفٌ-تَخَلُّفٌ [خ ل ف] (مص. تَخَلَّفَ) 1.""التَّخَلُّفُ عَنِ الرَّكْبِ"" : البَقَاءُ خَلْفَهُ، وَرَاءهُ. 2.""التَّخَلُّفُ عَنِ الحُضُورِ"" : التَّغَيُّبُ. 3.""تَخَلُّفُ الطِّفْلِ"" : بُطْءُ نُمُوِّهِ. 4.""لاَحَظَ تَخَلُّفَهُ فِي دِرَاسَتِهِ"" : تَأَخُّرَهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18776, 'تَخَلُّقٌ', 'تخلق', 'مصدر', 'خلق', 'تخلق', 'تخلق', 'مص. تَخَلَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَلُّقٌ-تَخَلُّقٌ [خ ل ق] (مص. تَخَلَّقَ). 1.""وَجَدَ فِي تَخَلُّقِهِ تَصَنُّعاً"" : الـتَّـطَبُّعُ بِمَا لَيْسَ مِنْ خُلُقِهِ وَتَكَلُّفُ ذَلِكَ. 2.""تَخَلُّقُ الكَذِبِ"" : اِخْتِلاَقُهُ، اِخْتِرَاعُهُ، اِبْتِدَاعُهُ. 3.""تَخَلُّقُ الجَنِينِ فِي بَطْنِ أُمِّهِ"" : تَشَكُّلُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18777, 'تَخَلُّلٌ', 'تخلل', 'مصدر', 'خلل', 'تخلل', 'تخل', 'مص. تَخَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَلُّلٌ-تَخَلُّلٌ [خ ل ل] (مص. تَخَلَّلَ). 1.""تَخَلُّلُ المِيَاِه بَيْنَ الشِّعَابِ"" : النَّفَاذُ وَالانْسِيابُ بَيْنَهَا. 2.""التَّخَلُّلُ فِي الوُضُوءِ"" : إِدْخَالُ الْمَاِء خِلاَلَ الأَصَاِبِع وَشَعْرِ الرَّأْسِ أَوِ اللِّحْيَةِ. 3.""يُوَاظِبُ عَلَى تَخَلُّلِ أَسْنَانِهِ بَعْدَ الأَكْلِ"" : إِخْرَاجُ مَا بَيْنَهَا مِنْ بَقِيَّةِ الطَّعَامِ. 4.""حَاوَلَ التَّخَلُّلَ وَسَطَ الصُّفُوفِ"" : الدُّخُولُ بَيْنَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18778, 'تَخَلِّي', 'تخلي', 'مصدر', 'خلل', 'تخلي', 'تخل', 'مص. تَخَلَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَخَلٍّ-تَخَلٍّ، التَّخَلِّي [خ ل ل] (مص. تَخَلَّى). 1 .""دَفَعَهُ إِلَى التَّخَلِّي عَنْ حَقِّهِ"" : التَّنَازُل عَنْهُ. 2.""التَّخَلِّي عَنِ العَمَلِ"" : تَرْكُهُ. 3.""أَرَادَ التَّخَلِّي لِلْعَمَلِ"" : التَّفَرُّغُ لَهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18779, 'تَدَاعي', 'تداعي', 'مصدر', 'دعي', 'تداعي', 'تدع', 'مص. تَدَاعَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَدَاعٍ-تَدَاعٍ، التَّدَاعِي [د ع ي] (مص. تَدَاعَى). ""تَدَاعِي الجُدْرَانِ"" : تَصَدُّعُهَا وَإِصَابَتُهَا بِشُقُوقٍ. 2.""تَدَاعِي الحَاضِرِينَ"": دَعْوَةُ بَعْضِهِمْ بَعْضاً لِلاجْتِمَاعِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18780, 'تَخَمُّرٌ', 'تخمر', 'مصدر', 'خمر', 'تخمر', 'تخمر', 'مص. تَخَمَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَمُّرٌ-تَخَمُّرٌ [خ م ر] (مص. تَخَمَّرَ). 1.""تَخَمُّرُ الْمَرْأَةِ"" : لِبَاسُهَا الخِمَارَ. 2.""تَخَمُّرُ العَجِينِ"" : عَمَلُ الخَمِيرِ فِيهِ. 3.""تَخَمُّرُ الفِكْرَةِ"" : اِكْتِمَالُهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18781, 'تَخَنُّثٌ', 'تخنث', 'مصدر', 'خنث', 'تخنث', 'تخنث', 'مص. تَخَنَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَنُّثٌ-تَخَنُّثٌ [خ ن ث] (مص. تَخَنَّثَ). 1.""تَخَنُّثُ الرَّجُلِ"": اِتِّصَافُهُ بِصِفَاتِ الْمَرْأَةِ. 2.""تَخَنُّثُ الوَلَدِ"" : تَدَلُّـلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18782, 'تَخَوُّفٌ', 'تخوف', 'مصدر', 'خوف', 'تخوف', 'تخف', 'مص. تَخَوَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَوُّفٌ-تَخَوُّفٌ [خ و ف] (مص. تَخَوَّفَ). ""التَّخَوُّفُ مِنْ أَذَاهُ"" : الشُّعُور بِالخَوْفِ وَالـفَزَعِ، اِضْطِرَابُ النَّفْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18783, 'تَخَيُّرٌ', 'تخير', 'مصدر', 'خير', 'تخير', 'تخر', 'مص. تَخَيَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَيُّرٌ-تَخَيُّرٌ [خ ي ر] (مص. تَخَيَّرَ). ""كانَ تَخَيُّرُهُ عَنِ اسْتِحْقَاقٍ"" : اِنْتِقَاؤُهُ، اِخْتِيَارُهُ، اِصْطِفَاؤُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18784, 'تَخَيُّلٌ', 'تخيل', 'مصدر', 'خيل', 'تخيل', 'تخل', 'مص. تَخَيَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخَيُّلٌ-تَخَيُّلٌ [خ ي ل] (مص. تَخَيَّلَ). 1.""تَخَيُّلُ صُورَتِهِ"": تَمَثُّلُهَا، تَصَوُّرُهَا. 2.""تَخَيُّلُ الخَيْرِ"" : ظَنُّهُ، تَوَسُّمُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18785, 'تَدَاخُلٌ', 'تداخل', 'مصدر', 'دخل', 'تداخل', 'تدخل', 'مص. تَدَاخَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَاخُلٌ-تَدَاخُلٌ [د خ ل] (مص. تَدَاخَلَ). 1.""تَدَاخُلُ الشَّكِّ في نَفْسِهِ"" : مُخَامَرَةُ. 2.""تَدَاخُلُ الخُيـُـوطِ فِيمَا بَيْنَهَا"" : اِلْتِوَاءُ بَعْضِهَا فِي بَعْضٍ. 3.""تَدَاخُلُ القَضَايَا"" : اِلْتِبَاسُهَا، تَشَابُهُهَا، اِخْتِلاَطُهَا. ""الْقَوْلُ فِي اللُّغَات الأُخْرَى غَيْرِ الْعَرَبِيَّةِ أَشَدُّ تَدَاخُلاً وَتَرَادُفاً"". (التوحيدي) ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18786, 'تَدَارُسٌ', 'تدارس', 'مصدر', 'درس', 'تدارس', 'تدرس', 'مص. تَدَارَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَارُسٌ-تَدَارُسٌ [د ر س] (مص. تَدَارَسَ). 1.""تَدَارُسُ الكِتَابِ"" : قِرَاءتُهُ وَالتَّحَاوُرُ فِي مَعَانِيهِ. 2.""تَدَارُسُ الْمَشْرُوعِ"": مُنَاقَشَتُهُ وَالتَّدَاوُلُ فِيهِ، عَرْضُ كُلِّ الآرَاءِ الْمُتَعَلِّقَةِ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18787, 'تَدَارُكٌ', 'تدارك', 'مصدر', 'درك', 'تدارك', 'تدرك', 'مص. تَدَارَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَارُكٌ-تَدَارُكٌ [د ر ك] (مص. تَدَارَكَ). 1.""تَدَارُكُ السَّيَّارَاتِ"" : تَلاَحُقُهَا الوَاحِدَةُ تِلْوَ الأُخْرَى. 2.""تَدَارُكُ الأَخْبَارِ"" : تَتَابُعُهَا. 3.""تَدَارُكُ الأَخْطَاءِ"" : إِصْلاَحُهَا. 4.""تَدَارُكُ الأَخْطَارِ"" : اِتِّقَاؤُهَا، تَجَنُّبُهَا، تَفَادِيهَا. 5.""تَدَارُكُ مَا فَاتَهُ مِنْ دُرُوسٍ"" : مُحَاوَلَةُ إِدْرَاكِهَا. 6.""تَدَارُكُ الأَكْلِ بِالشَّرَابِ"" : اِتْبَاعُ الأَكْلِ بِالشَّرَابِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18788, 'تَدَاعُبٌ', 'تداعب', 'مصدر', 'دعب', 'تداعب', 'تدعب', 'مص. تَدَاعَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَاعُبٌ-تَدَاعُبٌ [د ع ب] (مص. تَدَاعَبَ). ""تَدَاعُبُ الأَوْلاَدِ"": تَمَازُحُهُمْ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18789, 'تَدَخُّلٌ', 'تدخل', 'مصدر', 'دخل', 'تدخل', 'تدخل', 'مص. تَدَخَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَخُّلٌ-تَدَخُّلٌ [د خ ل] (مص. تَدَخَّلَ). ""يَنْبَغِي عَدَمُ التَّدَخُّلِ فيِ شُؤُونِ الغَيْرِ"" : عَدَمُ الإِقْحَامِ فيِ شُؤُونِ الغَيْرِ. ""مِنْ مَبَادِئِ السِّيَاسَةِ الدَّوْلِيَّةِ عَدَمُ التَّدَخُّلِ فيِ الشُّؤُونِ الدَّاخِلِيَّةِ لأَيِّ بَلَدٍ"" ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18790, 'تَدَافُعٌ', 'تدافع', 'مصدر', 'دفع', 'تدافع', 'تدفع', 'مص. تَدَافَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَافُعٌ-تَدَافُعٌ [د ف ع] (مص. تَدَافَعَ). ""تَدَافُعُ الجُمْهُورِ أَمَامَ بابِ الْمَلْعَبِ"" : دَفَعَ بَعْضُهُمْ بَعْضاً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18791, 'تَدَانِي', 'تداني', 'مصدر', 'دني', 'تداني', 'تدن', 'مص. تَدَانَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَدَانٍ-تَدَانٍ، التَّدَانِي [د ن ي] (مص. تَدَانَى). 1.""حَاوَلَ التَّدَانِيَ مِنَ الْمَنَصَّةِ"" : الاِقْتِرَابَ مِنْهَا. 2.""تَدَانِي الدَّخْلِ الوَطَنيِّ"" : نَقْصُهُ، ضَعْفُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18792, 'تَدَاوُلٌ', 'تداول', 'مصدر', 'دول', 'تداول', 'تدل', 'مص. تَدَاوَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَاوُلٌ-تَدَاوُلٌ [د و ل] (مص. تَدَاوَلَ). 1.""أُعْلِنَ عَنْ بِدَايَةِ تَدَاوُلِ العُمْلَةِ الجَدِيدَةِ"" : عَنْ بِدَايـَةِ رَوَاجِهَا. 2.""سَيَتِمُّ تـَوْزِيـعُ التَّذَاكِرِ بِالتَّدَاوُلِ"" : بِالتَّنَاُوِب، بِالدَّوْرِ. 3.""خَرَجَ أَعْضَاءُ الْمَحْكَمَةِ لِلتَّدَاوُلِ"" : لِلتَّشَاوُرِ، لِتَبُادُلِ الرَّأْيِ فِيمَا بَيْنَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18793, 'تَدَاوِي', 'تداوي', 'مصدر', 'دوي', 'تداوي', 'تد', 'مص. تَدَاوَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَدَاوٍ-تَدَاوٍ، التَّدَاوِي [د و ي] (مص. تَدَاوَى). 1.""تَدَاوِي الْمَرِيضِ"" : عِلاَجُهُ. 2. ""التَّدَاوِي بِالأَعْشَابِ"" : التَّعَالُجِ بِهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18794, 'تَدَايُنٌ', 'تداين', 'مصدر', 'دين', 'تداين', 'تدن', 'مص. تَدَايَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَايُنٌ-تَدَايُنٌ [د ي ن] (مص. تَدَايَنَ). ""اِلْتَجَأَ إِلَى التَّدَايُنِ لِحَلِّ مَشَاكِلِهِ"" : الاسْتِدَانَةِ، أَي الاقْتِراضِ، طَلَبِ سُلْفَةٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18795, 'تَدَبُّرٌ', 'تدبر', 'مصدر', 'دبر', 'تدبر', 'تدبر', 'مص. تَدَبَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَبُّرٌ-تَدَبُّرٌ [د ب ر] (مص. تَدَبَّرَ). ""تَدَبُّرُ الأُمُورِ"" : التَّفْكِيرُ وَالتَّأَمُّلُ فِيهَا. ""أَمَّا بَلاَغَةُ التَّأْويلِ، فَهِيَ الَّتِي تُحْوِجُ بِغُمُوضِهَا إِلَى التَّدَبُّرِ وَالتَّصَفُّحِ"". (التوحيدي) ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18796, 'تَدَثُّرٌ', 'تدثر', 'مصدر', 'دثر', 'تدثر', 'تدثر', 'مص. تَدَثَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَثُّرٌ-تَدَثُّرٌ [د ث ر] (مص. تَدَثَّرَ). 1.""لَمْ يَنْفَعْهُ إِلاَّ التَّدَثُّرُ"": لِباسُ الدِّثَارِ، التَّلَفُّفُ وَالتَّغَطِّي بِهِ. 2.""تَدَثُّرُ الفَرَسِ"" : الوُثُوبُ عَلَيْهِ وَرُكُوبُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18797, 'تَدَجُّجٌ', 'تدجج', 'مصدر', 'دجج', 'تدجج', 'تدج', 'مص. تَدَجَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَجُّجٌ-تَدَجُّجٌ [د ج ج] (مص. تَدَجَّجَ). ""التَّدَجُّجُ فيِ السِّلاَحِ"" : التَّسَلُّحُ بِـهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18798, 'تَدَحْرُجٌ', 'تدحرج', 'مصدر', 'دحر', 'تدحرج', 'تدحرج', 'مص. تَدَحْرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَحْرُجٌ-تَدَحْرُجٌ [د ح ر] (مص. تَدَحْرَجَ). ""تَدَحْرُجُ الطِّفْلِ عَلَى الدَّرَجِ"" : اِنْدِفَاعُهُ وانْحِدارُهُ مِنْ دَرَجَةٍ إِلَى أُخْرَى. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18799, 'تَدَخُّنٌ', 'تدخن', 'مصدر', 'دخن', 'تدخن', 'تدخن', 'مص. تَدَخَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَخُّنٌ-تَدَخُّنٌ [د خ ن] (مص. تَدَخَّنَ). ""تَدَخُّنُ البَيْتِ"" : اِنْتِشَارُ الدُّخَانِ بِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18800, 'تَدَرُّبٌ', 'تدرب', 'مصدر', 'درب', 'تدرب', 'تدرب', 'مص. تَدَرَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَرُّبٌ-تَدَرُّبٌ [د ر ب] (مص. تَدَرَّبَ). ""التَّدَرُّبُ عَلَى القَفْزِ"" : اِعْتِيَادُهُ وَالْمُرُونَةُ عَلَيْهِ. ""التَّدَرُّبُ عَلَى القِرَاءةِ السَّرِيعَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18801, 'تَدَرُّجٌ', 'تدرج', 'مصدر', 'درج', 'تدرج', 'تدرج', 'مص. تَدَرَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَرُّجٌ-تَدَرُّجٌ [د ر ج] (مص. تَدَرَّجَ). 1.""عَرَفَ الصَّيْفُ تَدَرُّجاً مُفْرِطاً فِي الحَرَارَةِ"" : تَصَاعُداً. 2.""التَّدَرُّجُ فِي الوَظِيفَةِ"": التَّرَقِّي دَرَجَةً دَرَجَةً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18802, 'تَدَرُّعٌ', 'تدرع', 'مصدر', 'درع', 'تدرع', 'تدرع', 'مص. تَدَرَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَرُّعٌ-تَدَرُّعٌ [د ر ع] (مص. تَدَرَّعَ). 1.""تَدَرُّعُ الفَارِسِ"" : لِبَاسُهُ الدِّرْعَ. 2.""التَّدَرُّعُ بِالصَّبْرِ"" : الاسْتِعَانَةُ، التَّحَلِّي بِهِ 3.""التَّدَرُّعُ بِالقِيَمِ"" : التَّحَصُّنُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18803, 'تَدَسُّسٌ', 'تدسس', 'مصدر', 'دسس', 'تدسس', 'تدس', 'مص. تَدَسَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَسُّسٌ-تَدَسُّسٌ [د س س] (مص. تَدَسَّسَ). ""نَهَاهُ عَنِ التَّدَسُّسِ بِأَصْحَابِهِ"" : الوِشَايَةِ وَالدَّسِّ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18804, 'تَدَفُّؤٌ', 'تدفؤ', 'مصدر', 'دفأ', 'تدفء', 'تدف', 'مص. تَدَفَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَدَفُّؤٌ-تَدَفُّؤٌ [د ف أ] (مص. تَدَفَّأَ). 1.""التَّدَفُّؤُ بِالدِّثَارِ"" : التَّلَفُّفُ بِهِ دِفَاءً. 2.""التَّدَفُّؤُ بِالنَّارِ"" : التَّسَخُّنُ بِهَا لِتَدْفِئَةِ الجِسْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18805, 'تَدَفُّقٌ', 'تدفق', 'مصدر', 'دفق', 'تدفق', 'تدفق', 'مص. تَدَفَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَفُّقٌ-تَدَفُّقٌ [د ف ق] (مص. تَدَفَّقَ). 1""اِنْبَهَرَ أَمَامَ تَدَفُّقِ المِيَاهِ مِنْ أَعْلَى الجَبَلِ"" : غَزَارَتُهَا، سَيَلاَنُهَا. 2.""تَدَفُّقُ البَضَائِعِ"": نُزُولُهَا بِكَثْرَةٍ. ""تَدَفُّقُ رُؤُوسِ الأَمْوَالِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18806, 'تَدَلُّلٌ', 'تدلل', 'مصدر', 'دلل', 'تدلل', 'تدل', 'مص. تَدَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَلُّلٌ-تَدَلُّلٌ [د ل ل] (مص. تَدَلَّلَ). 1.""تَدَلُّلُ الوَلَدِ عَلَى أَهْلِهِ"" : اِجْتِرَاؤُهُ، إِظْهَارُ الانْبِسَاطِ وَالتَّفَتُّحِ. 2.""لاَ تَكُفُّ عَنْ إِظْهَارِ تَدَلُّلِهَا"" : إِظْهَار الغُنْجِ وَالدَّلاَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18807, 'تَدَلُّهٌ', 'تدله', 'مصدر', 'دله', 'تدله', 'تدله', 'مص. تَدَلَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَلُّهٌ-تَدَلُّهٌ [د ل هـ] (مص. تَدَلَّهَ). 1.""تَدَلُّهُ الفُؤَادِ"" : إِصَابَتُهُ بِهَمٍّ وَحُزْنٍ بِسَبَبِ عِشْقٍ وَمَا إِلَى ذَلِكَ. 2.""التَّدَلُّهُ فِي الْمَشَاكِلِ"" : التَّحَيُّرُ فِيهَا وَفُقْدَانُ الصَّوَابِ مِنْ جَرَّائِهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18808, 'تَدَلِّي', 'تدلي', 'مصدر', 'دلو', 'تدلي', 'تدل', 'مص. تَدَلَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَدَلٍّ-تَدَلٍّ، التَّدَلِّي [د ل و] (مص. تَدَلَّى). 1.""التَّدَلِّي مِنَ الجبَلِ"" : النُّزُولُ مِنْهُ. 2.""تَدَلِّي عَنَاقِيدِ العِنَبِ"" : تَعَلُّقُهَا. 3.""لاَنَعْرِفُ مِنْ أَيِّ جِهَةٍ كَانَ تَدَلِّيهِ"" : مِنْ أَيِّ جِهَةٍ كَانَ طُلُوعُهُ وَمَجِيئُهُ. 4. ""التَّدَلِّي فِي الهَاويَةِ"" : الهُبُوطُ فِيهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18809, 'تَدَنُّؤٌ', 'تدنؤ', 'مصدر', 'دنأ', 'تدنء', 'تدن', 'مص. تَدَنَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَدَنُّؤٌ-تَدَنُّؤٌ [د ن أ] (مص. تَدَنَّأَ). 1. ""تَدَنُّؤُ سُلُوكِ الوَلَدِ"" : صَار دَنِيئاً، قَبِيحاً. 2. ""تَدَنُّؤُ الوَلَدِ"" : حَمْلُ نَفْسِهِ عَلَى الدَّنَاءةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18810, 'تَدَنُّسٌ', 'تدنس', 'مصدر', 'دنس', 'تدنس', 'تدنس', 'مص. تَدَنَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَنُّسٌ-تَدَنُّسٌ [د ن س] (مص. تَدَنَّسَ). 1.""تَدَنُّسُ الْمَكَانِ"": اِنْتِشَارُ النَّجَاسَةِ بِهِ. 2.""تَدَنُّسُ الثَّوْبِ"" : اِتِّسَاخُهُ. 3.""تَدَنُّسُ سُمْعَةِ الرَّجُلِ"" : تَلَطُّخُهُ بِالسُّوءِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18811, 'تَدَنِّي', 'تدني', 'مصدر', 'دنو', 'تدني', 'تدن', 'مص. تَدَنَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَدَنٍّ-تَدَنٍّ، التَّدَنِّي [د ن و] (مص. تَدَنَّى). 1.""حَاوَلَ التَّدَنِّيَ مِنْهُ"" : الاِقْتِرَابَ مِنْهُ. 2.""أَخْلاَقُهُ فِي تَدَنٍّ مُسْتَمِرٍّ"" : فِي هُبُوطٍ، فِي انْخِفَاضٍ. ""يُؤْلِمُهُ تَدَنِّي الأَخْلاَقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18812, 'تَدَهُّنٌ', 'تدهن', 'مصدر', 'دهن', 'تدهن', 'تدهن', 'مص. تَدَهَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَهُّنٌ-تَدَهُّنٌ [د هـ ن] (مص. تَدَهَّنَ). ""التَّدَهُّنُ بِالدُّهْنِ"" : التَّطَلِّي بِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18813, 'تَدَهْوُرٌ', 'تدهور', 'مصدر', 'دهر', 'تدهور', 'تدهر', 'مص. تَدَهْوَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَهْوُرٌ-تَدَهْوُرٌ [د هـ ر] (مص. تَدَهْوَرَ). 1.""عَرَفَ وَضْعُهُ تَدَهْوُراً مُشِيناً"" : اِنْحِطَاطاً، اِنْخِفَاضاً. ""يُعَانِي الفُقَرَاءُ مِنْ تَدَهْوُرِ مُسْتَوَى مَعِيشَتِهِمْ"". 2.""تَحُدُّ التَّرْبِيَةُ السَّلِيمَةُ مِنْ تَدَهْوُرِ الأَخْلاَقِ"" : مِنْ تَدَنيِّهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18814, 'تَدَيُّنٌ', 'تدين', 'مصدر', 'دين', 'تدين', 'تدن', 'مص. تَدَيَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَدَيُّنٌ-تَدَيُّنٌ [د ي ن] (مص. تَدَيَّنَ). 1.""الْتَجَأَ إِلَى التَّدَيُّنِ مِنْ صَدِيقِهِ"" : أَخْذُ دَيْنٍ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18815, 'تَذَاكُرٌ', 'تذاكر', 'مصدر', 'ذكر', 'تذاكر', 'تذكر', 'مص. تَذَاكَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَذَاكُرٌ-تَذَاكُرٌ [ذ ك ر] (مص. تَذَاكَرَ). 1.""وَجَدُوا فِي سَمَرِهِمْ مَجَالاً لِتَذَاكُرِ ذِكْرَيَاتِهِمْ"" : لِذِكْرِها وَإِعَادَةِ الحَدِيثِ عَنْها. 2.""جَلَسُوا لِلتَّذَاكُرِ"" : لِلتَّفَاوُضِ وَتَبَادُلِ الآرَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18816, 'تَذَبْذُبٌ', 'تذبذب', 'مصدر', 'ذبذ', 'تذبذب', 'تذبذب', 'مص. تَذَبْذَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَـذَبْذُبٌ-تَـذَبْذُبٌ [ذ ب ذ] (مص. تَذَبْذَبَ). 1.""التَّذَبْذُبُ فيِ الرَّأْيِ"" : التَّرَدُّدُ فِيهِ. 2.""التَّذَبْذُبُ فِي الْمَذْهَبِ"" : الاِنْتِقَالُ مِنْ مَذْهَبٍ إِلَى آخَرَ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18817, 'تَذَرُّعٌ', 'تذرع', 'مصدر', 'ذرع', 'تذرع', 'تذرع', 'مص. تَذَرَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَذَرُّعٌ-تَذَرُّعٌ [ذ ر ع] (مص. تَذَرَّعَ). 1.""حَاوَلَ التَّذَرُّعَ بِأَعْذَارٍ وَاهِيَةٍ"" : التَّوَسُّلَ بِهَا، تَقْدِيمُهَا لِتُقْبَلَ مِنْهُ. 2.""التَّذَرُّعُ باِلصَّبْرِ"" : التَّسَلُّحُ وَالتَّحَلِّي بِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18818, 'تَذَكُّرٌ', 'تذكر', 'مصدر', 'ذكر', 'تذكر', 'تذكر', 'مص. تَذَكَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَذَكُّرٌ-تَذَكُّرٌ [ذ ك ر] (مص. تَذَكَّرَ). ""تَذكُّرُ الْمَعْلُومَاتِ"": اِسْتِرْجَاعُهَا بَعْدَ تَحْصِيلِهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18819, 'تَرَؤُّسٌ', 'ترؤس', 'مصدر', 'رأس', 'ترءس', 'ترس', 'مص. تَرَأَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَؤُّسٌ-تَرَؤُّسٌ [ر أ س] (مص. تَرَأَّسَ). 1. ""تَرَؤُّسُهُ البِلاَدَ"" : صَيْرُهُ رَئيِساً عَلَيْهَا. 2.""تَرَؤُّسُ الاجْتِمَاعِ"" : الإِشْرَافُ عَلَيْهِ وَتَسْيِيرُهُ. 3.""تَرَؤُّسُ الوَفْدِ"" : صَيْرُهُ رَئِيسَ الوَفْدِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18820, 'تَذَلُّلٌ', 'تذلل', 'مصدر', 'ذلل', 'تذلل', 'تذل', 'مص. تَذَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَذَلُّلٌ-تَذَلُّلٌ [ذ ل ل] (مص. تَذَلَّلَ). ""أَظْهَرَ لَهُ تَذَلُّلاً"" : خُضُوعاً وَتَوَاضُعاً. ""إِنَّ الإنْسَانَ الْمَخْلُوق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18821, 'تَذَمُّرٌ', 'تذمر', 'مصدر', 'ذمر', 'تذمر', 'تذمر', 'مص. تَذَمَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَذَمُّرٌ-تَذَمُّرٌ [ذ م ر] (مص. تَذَمَّرَ). 1.""يَشْعُرُ بِالتَّذَمُّرِ كُلَّمَا رَأَى حَادِثَةَ سَيْرٍ"" : التَّأَفُّفُ، الأَسَفُ. 2.""سَادَ التَّذَمُّرُ بَيْنَ النَّاسِ"" : ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18822, 'تَذَوُّقٌ', 'تذوق', 'مصدر', 'ذوق', 'تذوق', 'تذق', 'مص. تَذَوَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَذَوُّقٌ-تَذَوُّقٌ [ذ و ق] (مص. تَذَوَّقَ). ""تَذَوُّقُ الطَّعَامِ"" : ذَوْقُهُ وَالتَّلَذُّذُ بِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18823, 'تَرَائِي', 'ترائي', 'مصدر', 'رأي', 'تراءي', 'تر', 'مص. تَرَاءى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَرَاءٍ-تَرَاءٍ، التَّرَائِي[ر أ ي] (مص. تَرَاءى). 1.""التَّرَائِي فيِ المِرْآةِ"" : النَّظَرُ فيهَا. 2.""تَرَائِي الأَشْبَاحِ أَمَامَهُ"" : تَرَاقُصُهَا، ظُهُورُهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18824, 'تَرَابُطٌ', 'ترابط', 'مصدر', 'ربط', 'ترابط', 'تربط', 'مص. تَـرَابَـطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَابُطٌ-تَرَابُطٌ [ر ب ط ] (مص. تَـرَابَـطَ). 1.""بَيْنَهُمَا تَرَابُطٌ عَمِيقٌ"" : اِرْتِبَاطٌ، اِتِّحَادٌ، تَمَاسُكٌ. 2.""يُحَافِظُ عَلَى تَرَابُطِ أَفْكَارِهِ"" : عَلَى تَـنَاُسِقهَا، تَمَاسُكِهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18825, 'تَرَاجُعٌ', 'تراجع', 'مصدر', 'رجع', 'تراجع', 'ترجع', 'مص. تَرَاجَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاجُعٌ-تَرَاجُعٌ [ر ج ع] . (مص. تَرَاجَعَ). ""يَصْعُبُ عَلَيْكَ التَّرَاجُعُ بَعْدَ كُلِّ هَذِهِ الخُطُوَاتِ الَّتِي قَطَعْتَهَا"" : أَي العَوْدَةُ إِلَى الوَرَاءِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18826, 'تَرَاحُمٌ', 'تراحم', 'مصدر', 'رحم', 'تراحم', 'ترحم', 'مص. تَرَاحَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاحُمٌ-تَرَاحُمٌ [ر ح م] (مص. تَرَاحَمَ). ""تَرَاحُمُ النَّاسِ"" : رُحْمُ بَعْضِهِمْ بَعْضاً، تَعَاطُفُهُمْ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18827, 'تَرَاخِي', 'تراخي', 'مصدر', 'رخو', 'تراخي', 'ترخ', 'مص. تَرَاخَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَرَاخٍ-تَرَاخٍ، التَّرَاخِي [ر خ و] (مص. تَرَاخَى). ""مَا هَذَا التَّرَاخِي اِنْتَبِهْ"" : مَا هَذَا الفُتُورُ وَالكَسَلُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18828, 'تَرَادُفٌ', 'ترادف', 'مصدر', 'ردف', 'ترادف', 'تردف', 'مص. تَرَادَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَادُفٌ-تَرَادُفٌ [ر د ف] (مص. تَرَادَفَ). 1.""تَرَادُفُ الوَلَدَيْنِ عَلَى الحِصَانِ"" : رُكُوبُ كُلٍّ مِنْهُمَا خَلْفَ الآخَرِ. 2.""تَرَادُفُ الكَلِمَاتِ"" : تَشَابُهُ مَعَانِيهَا. 3.""تَرَادُفُ الْمَشَاكِلِ وَالهُمُومِ"" : تَوَاليِهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18829, 'تَرَاقُبٌ', 'تراقب', 'مصدر', 'رقب', 'تراقب', 'ترقب', 'مص. تَرَاقَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاقُبٌ-تَرَاقُبٌ [ر ق ب] (مص. تَرَاقَبَ). ""هُمَا فِي تَرَاقُبٍ دَائِمٍ"" : رَصْدُ كُلِّ وَاحِدٍ مِنْهُمَا حَرَكَةَ الآخَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18830, 'تَرَاسُلٌ', 'تراسل', 'مصدر', 'رسل', 'تراسل', 'ترسل', 'مص. تَرَاسَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاسُلٌ-تَرَاسُلٌ [ر س ل ] (مص. تَرَاسَلَ). ""يُحِبُّ التَّرَاسُلَ مَعَ الأَصْدِقَاءِ"" : الْمُرَاسَلَة، أَيْ تَبَادُل الرَّسائِلِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18831, 'تَرَاشُقٌ', 'تراشق', 'مصدر', 'رشق', 'تراشق', 'ترشق', 'مص. تَرَاشَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاشُقٌ-تَرَاشُقٌ [ر ش ق] (مص. تَرَاشَقَ). 1.""التَّرَاشُقُ بِالشَّتَائِمِ"" : تَبَادُلُ الشَّتَائِمِ. 2.""التَّرَاشُقُ بِالحِجَارَةِ"" : التَّرَامِي بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18832, 'تَرَاصٌّ', 'تراص', 'مصدر', 'رصص', 'تراص', 'ترص', 'مص. تَراصَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاصٌّ-تَرَاصٌّ [ر ص ص] (مص. تَراصَّ). 1.""تَرَاصُّ حِجَارَةِ الرَّصِيفِ"" : اِنْضِمَامُ بَعْضِهَا إِلَى بَعْضٍ . 2.""تَرَاصُّ الصُّفُوفِ"": اِتِّحَادُهَا، تَلاَصُقُهُا، تَقَارُبُها ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18833, 'تَرَاصُدٌ', 'تراصد', 'مصدر', 'رصد', 'تراصد', 'ترصد', 'مص. تَرَاصَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاصُدٌ-تَرَاصُدٌ [ر ص د] (مص. تَرَاصَدَ). ""تَرَاصُدُ الرَّجُلَيْنِ"": مُرَاقَبَةُ كُلٍّ مِنْهُمَا الآخَرَ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18834, 'تَرَاصُفٌ', 'تراصف', 'مصدر', 'رصف', 'تراصف', 'ترصف', 'مص. تَرَاصَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاصُفٌ-تَرَاصُفٌ [ر ص ف] (مص. تَرَاصَفَ) . 1.""تَرَاصُفُ الصَّفِّ"" : اِصْطِفَافُهُ. 2.""تَرَاصُفُ الحِجَارَةِ"" : اِنْتِظَامُهَا، تَرَاصُّهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18835, 'تَرَاغُبٌ', 'تراغب', 'مصدر', 'رغب', 'تراغب', 'ترغب', 'مص. تَرَاغَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاغُبٌ-تَرَاغُبٌ [ر غ ب] (مص. تَرَاغَبَ). 1.""تَرَاغُبُ الرِّزْقِ"" : اِتِّسَاعُهُ. 2.""التَّرَاغُبُ فِي الخَيْرِ"" : الرَّغْبَةُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18836, 'تَرَؤُّفٌ', 'ترؤف', 'مصدر', 'رأف', 'ترءف', 'ترف', 'مص. تَرَأَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَؤُّفٌ-تَرَؤُّفٌ [ر أ ف] (مص. تَرَأَّفَ). ""وَجَدَ فِي مُعَامَلَتِهِ تَرَؤُّفاً"" : تَرَفُّقاً، إِشْفَاقاً وَرَحْمَةً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18837, 'تَرَافُعٌ', 'ترافع', 'مصدر', 'رفع', 'ترافع', 'ترفع', 'مص. تَرَافَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَافُعٌ-تَرَافُعٌ [ر ف ع] (مص. تَرَافَعَ). 1.""لَمْ يَبْقَ أَمَامَهُمَا إِلاَّ التَّرَافُعُ إِلَى القَاضِي"" : الاِلْتِجَاءُ إِلَى القَاضِي لِعَرْضِ نِزَاعِهِمَا لِيَجِدَ لَهُ حَلاًّ، التَّحَاكُمُ. 2.""تَرَافُعُ الْمُحَامِي أَمَامَ القُضَاةِ"" : الْمُدَاخَلَةُ الَّتِي يُقَدِّمُ فِيهَا حُجَجَهُ وَتَبْرِيرَاتِهِ. 3.""تَرَافُعُ الوَلَدَيْنِ"": رَفْعُ كُلِّ وَاحِدٍ مِنْهُمَا الآخَرَ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18838, 'تَرَافُقٌ', 'ترافق', 'مصدر', 'رفق', 'ترافق', 'ترفق', 'مص. تَرَافَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَافُقٌ-تَرَافُقٌ [ر ف ق] (مص. تَرَافَقَ). 1.""تَرَافُقُ الصَّدِيقَيْنِ"": مُرَافَقَةُ أَحَدِهِمَا الآخَرَ. 2.""مُنْذُ زَمَنٍ طَوِيلٍ وَهُمَا فِي تَرَافُقٍ"" : أَيْ هُمَا رَفِيقَانِ ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18839, 'تَرَاوُغٌ', 'تراوغ', 'مصدر', 'روغ', 'تراوغ', 'ترغ', 'مص. تَرَاوَغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاوُغٌ-تَرَاوُغٌ [ر و غ] (مص. تَرَاوَغَ). 1.""تَرَاوُغُ الْمُتَلاَكِمَيْنِ"" : تَصَارُعُهُمَا. 2.""تَرَاوُغُ الْمُتَـنَافِسَيْنِ"" : تخَاَدُعُهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18840, 'تَرَاقُصٌ', 'تراقص', 'مصدر', 'رقص', 'تراقص', 'ترقص', 'مص. تَرَاقَصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاقُصٌ-تَرَاقُصٌ [ر ق ص] (مص. تَرَاقَصَ). ""تَرَاقُصُ الخَيَالِ أَمَامَهُ"" : تَرَائِيهِ، تَحَرُّكُهُ طَيْفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18841, 'تَرَاقِي', 'تراقي', 'مصدر', 'رقي', 'تراقي', 'ترق', 'مص. تَرَاقَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَرَاقٍ-تَرَاقٍ، التَّرَاقِي [ر ق ي] (مص. تَرَاقَى). ""التَّرَاقِي فيِ الْمَنْصِبِ"" : الارْتقَاءُ فِيهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18842, 'تَرَاقِي', 'تراقي', 'مصدر', 'رقي', 'تراقي', 'ترق', 'مص. تَرَاقى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَرَاقٍ-تَرَاقٍ، التَّرَاقِي [ر ق ي] (مص. تَرَاقى). ""التَّرَاقِي فيِ الْمَنْصِبِ"" : الاِرْتِقاءُ فِيهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18843, 'تَرَاكُضٌ', 'تراكض', 'مصدر', 'ركض', 'تراكض', 'تركض', 'مص. تَرَاكَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاكُضٌ-تَرَاكُضٌ [ر ك ض] (مص. تَرَاكَضَ). ""اِنْطَلَقَ العَدَّاءونَ فِي تَرَاكُضٍ"" : فِي رَكْضٍ، فِي جَرْيٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18844, 'تَرَاكُلٌ', 'تراكل', 'مصدر', 'ركل', 'تراكل', 'تركل', 'مص. تَرَاكَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاكُلٌ-تَرَاكُلٌ [ر ك ل] (مص. تَرَاكَلَ). ""تَرَاكُلُ الأَوْلاَدِ"" : تَسْدِيدُ كُلِّ وَاحِدٍ مِنْهُمْ لِلآخَرِ ضَرَبَاتٍ بِالرِّجْلِ، أَيْ رَكْلُ بَعْضِهِمْ بَعْضاً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18845, 'تَرَاكُمٌ', 'تراكم', 'مصدر', 'ركم', 'تراكم', 'تركم', 'مص. تَرَاكَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاكُمٌ-تَرَاكُمٌ [ر ك م] (مص. تَرَاكَمَ). 1.""تَرَاكُمُ الكُتُبِ أَوِ الأَوْرَاقِ أَوِ الجَرَائِدِ"" : تَكَوُّمُهَا، تَكَدُّسُهَا. 2.""تَرَاكُمُ الهُمُوِم"" : تَوَاليِهَا، تَكَاثُرُهَا. ""تَرَاكُمُ الغُمُومِ عَلَى قَلْبِ الحَاسِدِ"".(الجاحظ) ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18846, 'تَرَامِي', 'ترامي', 'مصدر', 'رمي', 'ترامي', 'ترم', 'مص. تَرَامَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَرَامٍ-تَرَامٍ، التَّرَامِي [ر م ي] (مص. تَرَامَى). 1.""التَّرَامِي بِالنِّبَالِ وَالحِجَارَةِ"" : التَّرَاجُمُ . 2.""تَرَامِي الأَمْوَاجِ"" : تَقَاذُفُهَا . 3 .""التَّرَامِي بَيْنَ الأَحْضَانِ"" : الاِرتِمَاءُ. 4.""تَرَامِي الأَحْدَاثِ"" : تَلاَحُقُهَا، تَتـَابُعُهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18847, 'تَرَاهُنٌ', 'تراهن', 'مصدر', 'رهن', 'تراهن', 'ترهن', 'مص. تَرَاهَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاهُنٌ-تَرَاهُنٌ [ر هـ ن] (مص. تَرَاهَنَ). ""اِتَّفَقُوا عَلَى التَّرَاهُنِ"" : عَلَى التَّخَاطُرِ، أَيْ تَقْدِيمُ كُلِّ وَاحِدٍ مِنْهُمْ قَدْراً مِنَ الْمَالِ يُتَّفَقُ عَلَيْهِ حَوْلَ مَوْضُوعِ سِبَاقٍ أَوْ مَا شَابَهَهُ يَفُوزُ بِهِ الصَّائِبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18848, 'تَرَاوُحٌ', 'تراوح', 'مصدر', 'روح', 'تراوح', 'ترح', 'مص. تَرَاوَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَاوُحٌ-تَرَاوُحٌ [ر و ح] (مص. تَرَاوَحَ). 1.""تَرَاوُحُ الأَيَّامِ"" : تَعَاقُبُهَا، تَنَاوُبُهَا. 2.""كَانَتِ الكُرَةُ فيِ تَرَاوُحٍ بَيْنَهُمَا"" : فِي تَبَادُلٍ بَيْنَهُمَا، أَيْ كُلُّ وَاحِدٍ يَأْخُذُهَا مَرَّةً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18849, 'تَرَدُّدٌ', 'تردد', 'مصدر', 'ردد', 'تردد', 'ترد', 'مص. تَرَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَدُّدٌ-تَرَدُّدٌ [ر د د] (مص. تَرَدَّدَ). ""لاَ يَسْتَقِرُّ عَلَى رَأْيٍ هُوَ كَثِيرُ التَّرَدُّدِ"" : التَّأَرْجُحُ وَعَدَمُ الثَّبَاتِ عَلَى رَأْيٍ مُعَيَّنٍ. ""فيِ عَيْنَيْهِ التَّرَدُّدُ وَالحَيْرَةُ"".(ن. محفوظ) ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18850, 'تَرَبُّصٌ', 'تربص', 'مصدر', 'ربص', 'تربص', 'تربص', 'مص. تَرَبَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَبُّصٌ-تَرَبُّصٌ [ر ب ص] (مص. تَرَبَّصَ). 1.""تَرَبُّصُ وُصُولِ الضَّيْفِ"" : اِنْتِظَارُهُ. 2.""تَرَبُّصُ الفُرْصَةِ"" : تَحَيُّنُهَا. 3.""التَّرَبُّصُ بِالعَدُوِّ"" : تَرَصُّدُهُ، نَصْبُ كَمِينٍ لَهُ لِلإِيقَاعِ بِهِ. 4.""التَّرَبُّصُ بِالْمَكَانِ"" : الإِقَامَةُ فِيهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18851, 'تَرَبُّعٌ', 'تربع', 'مصدر', 'ربع', 'تربع', 'تربع', 'مص. تَرَبَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَبُّعٌ-تَرَبُّعٌ [ر ب ع] (مص. تَرَبَّعَ). 1.""التَّرَبُّعُ فيِ الجَلْسَةِ"": ثَنْيُ القَدَمَيْنِ تَحْتَ الفَخِذَيْنِ. 2.""تَّرَبُّعُ الْمَلِكِ عَلى عَرْشِهِ"" : جُلُوسُهُ. 3. ""التَّرَبُّعُ بِالْمَكَانِ"" : الإِقَامَةُ فِي فَصْلِ الرَّبِيعِ. 4.""تَّرَبُّعُ الْمَاشِيَةِ"" : أَكْلُهَا الرَّبِيعَ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18852, 'تَرَبِّي', 'تربي', 'مصدر', 'ربه', 'تربي', 'ترب', 'مص. تَرَبَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَرَبٍّ-تَرَبٍّ، التَّرَبِّي [ر ب هـ] (مص. تَرَبَّى). 1.""تَرَبِّي الوَلَدِ"" : تَثَقُّفُهُ، تَعَلُّمُهُ، تَهَذُّبُهُ. 2.""تَرَبِّي الطِّفْلِ فِي حِضْنِ أُمِّهِ"": نَشْأَتُهُ، نُمُوُّهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18853, 'تَرْجَمَةٌ', 'ترجمة', 'مصدر', 'ترجم', 'ترجمة', 'ترجمة', 'مص. تَرْجَمَ.', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَرَاجِمُ"', '', 'R', '', '', '', '', '', '', '"ج: تَرَاجِمُ. (مص. تَرْجَمَ). 1.""هَذَا الكتِاَبُ مِنْ تَرْجَمَةِ الْمُتَرْجِمِ"" : نَقْلُ الكَلاَمِ مِنْ لُغَةٍ إلَى أُخْرَى. 2.""قَدَّمَ تَرْجَمةً كَامِلَةً لِحَيَاةِ الكَاتِبِ"" : ذَكَرَ سِيرَتَهُ وَحَيَاتَهُ. 3.""تَرْجَمَةُ الْمَعْنَى"" : تَفْسِيرُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18854, 'تَرَاجِمُ', 'تراجم', 'مصدر', '', 'تراجم', 'ترجم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18855, 'تَرَجِي', 'ترجي', 'مصدر', 'رجو', 'ترجي', 'ترج', 'مص. تَرَجَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَرَجٍّ-تَرَجٍّ، التَّرَجِّي [ ر ج و] (مص. تَرَجَّى). ""تَرَجِّي الفَوْزِ"" : تَرَقُّبُهُ وَانْتِظَارُ حُصُولِهِ. ""يَعِيشُ عَلَى التَّرَجِّي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18856, 'تَرَحٌ', 'ترح', 'مصدر', 'ترح', 'ترح', 'ترح', 'مص. تَرِحَ', '', '', 'مفرد', 'DnN', '', '', '"أَتْرَاحٌ"', '', 'R', '', '', '', '', '', '', '"(مص. تَرِحَ). 1.""كَانَ تَرَحُهُ عَظِيماً"" : هَمُّهُ. 2.""شَارَكَهُ أَفْرَاحَهُ وَأَتْرَاحَهُ"" : أَحْزاَنَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18857, 'أَتْرَاحٌ', 'أتراح', 'مصدر', '', 'ءتراح', 'ترح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18858, 'تَرَحُّمٌ', 'ترحم', 'مصدر', 'رحم', 'ترحم', 'ترحم', 'مص. تَرَحَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَحُّمٌ-تَرَحُّمٌ [ر ح م] (مص. تَرَحَّمَ). ""التَّرَحُّمُ عَلَى الْمَيِّتِ"": الدُّعَاءُ لَهُ بِالرَّحْمَةِ، طَلَبُ الرَّحْمَةِ وَالْمَغْفِرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18859, 'تَرَصُّدٌ', 'ترصد', 'مصدر', 'رصد', 'ترصد', 'ترصد', 'مص. تَرَصَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَصُّدٌ-تَرَصُّدٌ [ر ص د] (مص. تَرَصَّدَ). ""تَرَصُّدُ العَدُوِّ"" : تَرَقُّبُهُ لِلإِيقَاعِ بِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18860, 'تَرَدٍّ', 'ترد', 'مصدر', 'ردي', 'ترد', 'ترد', 'مص. تَرَدَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَدٍّ-تَرَدٍّ، التَّرَدِّي [ر د ي] (مص. تَرَدَّى). ""وَضْعُهُ الاجتِمَاعِيُّ فِي تَرَدٍّ"" : فِي تَدَهْوُرٍ. ""يَعْمَلُ عَلَى وَقْفِ التَّرَدِّي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18861, 'تَرَزُّنٌ', 'ترزن', 'مصدر', 'رزن', 'ترزن', 'ترزن', 'مص. تَرَزَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَزُّنٌ-تَرَزُّنٌ [ر ز ن] . (مص. تَرَزَّنَ). ""تَرَزُّنُ الوَلَدِ"" : اِتِّصَافُهُ بِالرَّزَانَةِ وَالوَقَارِ وَالهُدُوءِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18862, 'تَرَسُّبٌ', 'ترسب', 'مصدر', 'رسب', 'ترسب', 'ترسب', 'مص. تَرَسَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَسُّبٌ-تَرَسُّبٌ [ر س ب] (مص. تَرَسَّبَ).: تَكَوُّنُ سَائِلٍ فِي جِسْمٍ غَيْرِ قَابِلٍ لِلذَّوَبَانِ يَسْتَقِرُّ فِي الأَسْفَلِ، مَا يَرْسُبُ مِنَ المِيَاهِ الْمَالِحَةِ عَلَى جِسْمٍ، أَوِ المِيَاهِ الصَّلْصَالِيَّةِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18863, 'تَرَسُّخٌ', 'ترسخ', 'مصدر', 'رسخ', 'ترسخ', 'ترسخ', 'مص. تَرَسَّخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَسُّخٌ-تَرَسُّخٌ [ر س خ] (مص. تَرَسَّخَ). ""تَرَسُّخُ الْمَعْلُومَاتِ فِي الذِّهْنِ"" : رُسُوخُهَا، تَثَبُّتُهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18864, 'تَرَسُّلٌ', 'ترسل', 'مصدر', 'رسل', 'ترسل', 'ترسل', 'مص. تَرَسَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَسُّلٌ-تَرَسُّلٌ [ر س ل] (مص. تَرَسَّلَ). 1.""تَرَسُّلُ الكَاتِبِ فِي الكِتَابَةِ"" : إِتْيَانُهُ بِكلاَمٍ مُرْسَلٍ غَيْرِ مُقَيَّدٍ بِقَافِيَةٍ أَوْ سَجْعٍ. 2.""التَّرَسُّلُ فِي القِرَاءةِ"" : القِرَاءةُ بِبُطْءٍ وَتَمَهُّلٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18865, 'تَرسُّمٌ', 'ترسم', 'مصدر', 'رسم', 'ترسم', 'ترسم', 'مص. تَرَسَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرسُّمٌ-تَرسُّمٌ [ر س م] . (مص. تَرَسَّمَ). 1.""تَرَسُّمُ مَنْظَرٍ"" : النَّظَرُ إِلَيْهِ فَي تَأَمُّلٍ. 2.""تَرَسُّمُ الذِّكْرَيَاتِ"" : ذِكْرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18866, 'تَرَشُّحٌ', 'ترشح', 'مصدر', 'رشح', 'ترشح', 'ترشح', 'مص. تَرَشَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَشُّحٌ-تَرَشُّحٌ [ر ش ح] (مص. تَرَشَّحَ). 1.""تَرَشُّحُ مِيَاهِ السَّدِّ"" : اِنْسِيَابُهَا. 2.""تَرَشَّحَ العَرَقُ مِنْ جَبِينِهِ تَرَشُّحاً"" : سَيَلاَنُهُ. 3.""التَّرَشُّحُ لِلانْتِخَابَاتِ"" : التَّقَدُّمُ لِِلانْتِخابَاتِ لِلْحُصُولِ عَلَى أَصْوَاتِ النَّاخِبِينَ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18867, 'تَرَشُّشٌ', 'ترشش', 'مصدر', 'رشش', 'ترشش', 'ترش', 'مص. تَرَشَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَشُّشٌ-تَرَشُّشٌ [ر ش ش] (مص. تَرَشَّشَ). ""تَرَشُّشُ الْمَاءِ"" : نُزُولُهُ مُتَفَرِّقاً قَطَرَاتٍ مُتَنَاثِرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18868, 'تَرَشُّفٌ', 'ترشف', 'مصدر', 'رشف', 'ترشف', 'ترشف', 'مص. تَرَشَّفَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَشُّفٌ-تَرَشُّفٌ [ر ش ف] (مص. تَرَشَّفَ) . ""تَرَشُّفُ العَصِيرِ"" : مَصُّهُ، رَشْفُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18869, 'تَرَفُّهٌ', 'ترفه', 'مصدر', 'رفه', 'ترفه', 'ترفه', 'مص. تَرَفَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَفُّهٌ-تَرَفُّهٌ [ر ف هـ] (مص. تَرَفَّهَ). ""تَرَفُّهُ الرَّجُلِ"" : تَنَعُّمُهُ، عَيْشُهُ فِي نَعِيمٍ وَرَغَدٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18870, 'تَرَصُّعٌ', 'ترصع', 'مصدر', 'رصع', 'ترصع', 'ترصع', 'مص. تَرَصَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَصُّعٌ-تَرَصُّعٌ [ر ص ع] (مص. تَرَصَّعَ). 1.""تَرَصُّعُ الْمَرْأَةِ بِالْجَواهِرِ"" : تَحَلِّيها. 2.""تَرَصُّعُ الخَاتَمِ"" : مُحَلَّىً بِالْجَواهِرِِ، مُرَصَّعٌ. 3.""تَرَصَّعَ الرَّجُلُ تَرَصُّعاً"" : نَشِطَ نَشَاطاً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18871, 'تَرَصُّفٌ', 'ترصف', 'مصدر', 'رصف', 'ترصف', 'ترصف', 'مص. تَرَصَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَصُّفٌ-تَرَصُّفٌ [ر ص ف] (مص. تَرَصَّفَ). 1.""تَرَصُّفُ الحِجَارَةِ"" : اِنْتِظَامُهَا. 2.""تَرَصُّفُ التَّلاَمِيذِ فِي الصَّفِّ"" : تَرَاصُّهُمْ. 3.""تَرَصُّفُ الأَسْنَانِ"" : تَنَضُّدُهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18872, 'تَرْطِيبٌ', 'ترطيب', 'مصدر', 'رطب', 'ترطيب', 'ترطب', 'مص. تَرَطَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرْطِيبٌ-تَرْطِيبٌ [ر ط ب] (مص. تَرَطَّبَ). 1.""تَرْطيِبُ الثَّوْبِ"" : بَلُّهُ بِالْمَاءِ . 2.""تَرْطِيبُ الضُّيُوفِ"" : إِطْعَامُهُمُ الرُّطَبَ. 3.""تَرْطِيبُ الِّلسَانِ"" : تَنْعِيمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18873, 'تَرَعْبُلٌ', 'ترعبل', 'مصدر', 'رعب', 'ترعبل', 'ترعبل', 'مص. تَرَعْبَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَعْبُلٌ-تَرَعْبُلٌ [ر ع ب] (مص. تَرَعْبَلَ). 1. ""تَرَعْبُلُ اللَّحْمِ"": تَقَطُّعُهُ. 2.""تَرَعْبُلُ الثَّوْبِ"" : تَمَزُّقُهُ، صَيْرُهُ بَالِياً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18874, 'تَرَعْرُعٌ', 'ترعرع', 'مصدر', 'رعرع', 'ترعرع', 'ترعرع', 'مص. تَرَعْرَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَعْرُعٌ-تَرَعْرُعٌ [ر ع ر ع] (مص. تَرَعْرَعَ). 1.""تَرَعْرُعُ الطِّفْلِ"" : نَشْأَتُهُ، شَبُّهُ. 2.""تَرَعْرُعُ السَّرَابِ"" : تَحَرُّكُهُ، تَلأْلُؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18875, 'تَرَفٌ', 'ترف', 'مصدر', 'ترف', 'ترف', 'ترف', 'مص. تَرِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَرِفٌ-تَرِفٌ [ت ر ف] (صِيغَةُ فَعِلٌ). ""كَانَ رَجُلاً تَرِفاً"" : مُتَنَعِّماً فِي النَّعيمِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18876, 'تَرَفُّعٌ', 'ترفع', 'مصدر', 'رفع', 'ترفع', 'ترفع', 'مص. تَرَفَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَفُّعٌ-تَرَفُّعٌ [ر ف ع] . (مص. تَرَفَّعَ). 1.""أَظْهَرَ تَرَفُّعاً"" : تَعَالِياً وَتَكَبُّراً، الشُّعُورُ بِالغُرُورِ. 2.""التَّرَفُّعُ عَنِ الخَطَايَا"" : التَّنَزُّهُ عَنْهَا. 3.""تَرَفُّعُ السِّتَارِ"" : رَفْعُهُ. 4.""تَرَفُّعُ الطَّائِرِ"" : اِرْتِفَاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18877, 'تَرَفُّقٌ', 'ترفق', 'مصدر', 'رفق', 'ترفق', 'ترفق', 'مص. تَرَفَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَفُّقٌ-تَرَفُّقٌ [ر ف ق] (مص. تَرَفَّقَ). 1.""التَّرَفُّقُ بِحَالِ الضُّعَفَاءِ"" : مُعَامَلَتُهُمْ بِرِفْقٍ وَعِنَايَةٍ. 2.""تَرَفَّقَ عَلَيْهِ تَرَفُّقاً"" : اِتَّكَأ عَلَيْهِ اتِّكَاءً. 3.""التَّرَفُّقُ فِي السَّيْرِ"" : السَّيْرُ عَلَى مَهَلٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18878, 'تَرَفُّلٌ', 'ترفل', 'مصدر', 'رفل', 'ترفل', 'ترفل', 'مص. ترَفَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَفُّلٌ-تَرَفُّلٌ [ر ف ل] (مص. ترَفَلَّ). 1.""تَرَفُّلُ الْمَرْأَةِ"" : سَيْرُهَا مُتَبَخْتِرَةً. 2.""أَرَادَ التَّرَفُّلَ عَلَيْهِمْ"" : أَرَادَ أَنْ يَصِيرَ سَيِّداً أَوْ أَمِيراً عَلَيْهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18879, 'تَرَمُّلٌ', 'ترمل', 'مصدر', 'رمل', 'ترمل', 'ترمل', 'مص. تَرَمَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَمُّلٌ-تَرَمُّلٌ [ر م ل] (مص. تَرَمَّلَ). ""تَرَمُّلُ الْمَرْأَةِ"" : صَيْرُهَا أَرْمَلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18880, 'تَرَقُّبٌ', 'ترقب', 'مصدر', 'رقب', 'ترقب', 'ترقب', 'مص. تَرَقَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَقُّبٌ-تَرَقُّبٌ [ر ق ب] (مص. تَرَقَّبَ). 1.""تَرَقُّبُ وُصُولِ الزَّائِرِ"" : اِرْتِقَابُهُ، اِنْتِظَارُهُ. 2.""تَرَقُّبُ الهِلاَلِ"" : تَرَصُّدُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18881, 'تَرَقْرُقٌ', 'ترقرق', 'مصدر', 'رقرق', 'ترقرق', 'ترقرق', 'مص. تَرَقْرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَقْرُقٌ-تَرَقْرُقٌ [ر ق ر ق] (مص. تَرَقْرَقَ). 1.""تَرَقْرُقُ الْمَاءِ"": تَلَأْلُؤُهُ فِي جَرَيَانِهِ. 2.""تَرَقْرُقُ الدُّمُوعِ فِي العَيْنِ"" : سَيَلاَنُهَا، تَدَافُعُهَا. 3.""تَرَقْرُقُ السَّرَابِ"" : لَمَعَانُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18882, 'تَرَقُّعٌ', 'ترقع', 'مصدر', 'رقع', 'ترقع', 'ترقع', 'مص. تَرَقَّعَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَقُّعٌ-تَرَقُّعٌ [ر ق ع] (مص. تَرَقَّعَ) . 1.""تَرَقُّعُ الرَّجُلِ"" : تَكَسُّبُهُ. 2.""تَرَقُّعُ الثَّوْبِ"" : إِصْلاَحُ رُقَعِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18883, 'تَرَقُّقٌ', 'ترقق', 'مصدر', 'رقق', 'ترقق', 'ترق', 'مص. تَرَقَّقَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَقُّقٌ-تَرَقُّقٌ [ر ق ق] (مص. تَرَقَّقَ ).1.""تَرَقُّقُ العَجِينِ"" : صَيْرُهَا رَقِيقاً. 2.""التَّرَقُّقُ لِحَالِ الضُّعَفَاءِ"" : العَطْفُ وَالحَنَانُ عَلَيْهِمْ. 3.""تَرَقَّقَ الرَّجُلُ تَرَقُّقاً"" : أَذَلَّهُ إِذْلاَلاً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18884, 'تَرَقِّي', 'ترقي', 'مصدر', 'رقي', 'ترقي', 'ترق', 'مص. تَرَقَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R0', '', '', '', '', '', '', '"تَرَقٍّ-تَرَقٍّ، التَّرَقِّي [ر ق ي] (مص. تَرَقَّى). 1.""تَرَقِّي الْمُوَظَّفِ فِي وَظِيفَتِهِ"" : حُصُولُهُ عَلَى تَرْقِيَةٍ. 2.""تَرَقِّي السُّلَّمِ"" : رَقْيُهُ دَرَجَةً. 3.""التَّرَقِّي فِي العِلْمِ"" : الِارْتِقَاءُ، الوُصُولُ إِلَى دَرَجَةٍ عَالِيَةٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18885, 'تَرْكٌ', 'ترك', 'مصدر', 'ترك', 'ترك', 'ترك', 'مص. تَرَكَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَرْكٌ-تَرْكٌ [ت رك] (مص. تَرَكَ). 1.""لاَ يَنْبغِي تَرْكُ هَذَا الوَضْعِ عَلَى مَا هُوَ عَلَيْهِ"" : صَرْفُ النَّظَرِ. 2.""وَكَمْ حَاجَةٍ قَضَيْنَاهَا بِتَرْكِهَا"" (مثل) : يُقَالُ عِنْدَ العَجْزِ عَنِ القِيامِ بِعَمَلٍ مَّا، أَيْ بِالتَّخَلِّي عَنْهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18886, 'تَرَكُّبٌ', 'تركب', 'مصدر', 'ركب', 'تركب', 'تركب', 'مص. تَرَكَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَكُّبٌ-تَرَكُّبٌ [ر ك ب] (مص. تَرَكَّبَ). 1.""تَرَكُّبُ الْمَوْضُوعِ مِنْ عِدَّةِ أَجْزَاءٍ"" : تَأَلُّفُهُ. 2.""تَرَكُّبُ الرُّفُوفِ"" : وَضْعُ بَعْضِهَا عَلَى بَعْضٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18887, 'تَرَكُّنٌ', 'تركن', 'مصدر', 'ركن', 'تركن', 'تركن', 'مص. تَرَكَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَكُّنٌ-تَرَكُّنٌ [ر ك ن] (مص. تَرَكَّنَ). ""تَرَكُّنُ الشَّيْخِ"" : تَوَقُّرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18888, 'تَرَمْرُمٌ', 'ترمرم', 'مصدر', 'رمرم', 'ترمرم', 'ترمرم', 'مص. تَرَمْرَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَمْرُمٌ-تَرَمْرُمٌ [ر م ر م] (مص. تَرَمْرَمَ). 1.""تَرَمْرُمُ الوَلَدِ"" : تَحْرِيكُ الْفَمِ بِالْكَلاَمِ وَلَمْ يَتَكَلَّمْ . 2.""تَرَمْرُمُ الشَّيْءِ"" : تَفَرُّقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18889, 'تَرَوِّي', 'تروي', 'مصدر', 'روي', 'تروي', 'تر', 'مص. تَرَوَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَرَوٍّ-تَرَوٍّ، التَّرَوِّي [ر و ي] (مص. تَرَوَّى). 1.""عَلَيْكَ بِالتَّرَوِّي قَبْلَ اتِّخَاذِ القَرَارِ"" : التَّفْكِيرُ مَلِيّاً. 2.""رَغِبَ فِي التَّرَوِّي مِنَ السَّاقِيَةِ"" : الاِرْتِوَاءُ، الشُّرْبُ حَتَّى إِطْفَاء الظَّمَإِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18890, 'تَرَنُّحٌ', 'ترنح', 'مصدر', 'رنح', 'ترنح', 'ترنح', 'مص. تَرَنَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَنُّحٌ-تَرَنُّحٌ [ر ن ح] (مص. تَرَنَّحَ). ""اِسْتَمَرَّ فِي تَرَنُّحِهِ"" : فِي تَمَايُلِهِ شِمَالاً وَيَمِيناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18891, 'تَرَنُّقٌ', 'ترنق', 'مصدر', 'رنق', 'ترنق', 'ترنق', 'مص. تَرَنَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَنُّقٌ-تَرَنُّقٌ [ر ن ق] (مص. تَرَنَّقَ). ""تَرَنُّقُ الْمَاءِ"" : كَدَرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18892, 'تَرَنُّمٌ', 'ترنم', 'مصدر', 'رنم', 'ترنم', 'ترنم', 'مص. تَرَنَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَنُّمٌ-تَرَنُّمٌ [ر ن م] (مص. تَرَنَّمَ). ""تَرَنُّمٌ عَذْبٌ هَذَا الَّذِي أَسْمَعُهُ"" : الصَّوْتُ الْمُلَحَّنُ، غِنَاءُ الصَّوْتِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18893, 'تَرَهُّبٌ', 'ترهب', 'مصدر', 'رهب', 'ترهب', 'ترهب', 'مص. تَرَهَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَهُّبٌ-تَرَهُّبٌ [ر هـ ب] (مص. تَرَهَّبَ). 1.""تَرَهُّبُ الرَّجُلِ"": صَيْرُهُ رَاهِباً. 2.""تَرَهُّبُ الرَّاهِبِ"" : تَخَشُّعُهُ، تَعَبُّدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18894, 'تَرَهُّلٌ', 'ترهل', 'مصدر', 'رهل', 'ترهل', 'ترهل', 'مص. تَرَهَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَهُّلٌ-تَرَهُّلٌ [ر هـ ل] (مص. تَرَهَّلَ). ""ظَهَرَ عَلَيْهِ التَّرَهُّلُ"": اِرْتِخَاءُ عَضَلاَتِهِ وَتَكَوُّمُ لَحْمِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18895, 'تَرَوُّحٌ', 'تروح', 'مصدر', 'روح', 'تروح', 'ترح', 'مص. تَرَوَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَوُّحٌ-تَرَوُّحٌ [ر و ح] (مص. تَرَوَّحَ). 1.""تَرَوُّحُ الطَّعَامِ"" : فَوْحُ رَائِحَتِهِ. 2.""التَّرَوُّحُ بِالمِرْوَحِة"" : التَّهْوِيَةُ بِهَا. 3.""جَاءَ وَقْتُ التَّرْوِيحِ"" : وَقْتُ الرَّوَاحِ وَالعَوْدَةِ إِلَى البَيْتِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18896, 'تَرَوُّضٌ', 'تروض', 'مصدر', 'روض', 'تروض', 'ترض', 'مص. تَرَوَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَوُّضٌ-تَرَوُّضٌ [ر و ض] (مص. تَرَوَّضَ). ""التَّرَوُّضُ عَلَى الخُيُولِ"" : تَذْلِيلُهَا وَتَسْهيلُ مِرَاسِهَا. ""مُولَعٌ بِرُكُوبِ الخَيْلِ وَالتَّرَوُّضِ عَلَيْهَا"". (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18897, 'تَرَوُّعٌ', 'تروع', 'مصدر', 'روع', 'تروع', 'ترع', 'مص. تَرَوَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَوُّعٌ-تَرَوُّعٌ [ر و ع] (مص. تَرَوَّعَ). ""عَاشَ لَحَظَاتِ تَرَوُّعٍ وَارْتِبَاكٍ"" : لَحَظَاتِ تَفَزُّعٍ وَفَزَعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18898, 'تَرَوُّلٌ', 'ترول', 'مصدر', 'رول', 'ترول', 'ترل', 'مص. تَرَوَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَوُّلٌ-تَرَوُّلٌ [ر و ل] (مص. تَرَوَّلَ). ""تَرَوُّلُ الْوَلَدِ"" : سَيَلاَنُ لُعَابِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18899, 'تَرَيُّثٌ', 'تريث', 'مصدر', 'ريث', 'تريث', 'ترث', 'مص. تَرَيَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَيُّثٌ-تَرَيُّثٌ [ر ي ث] (مص. تَرَيَّثَ). ""وَاجَهَ مَشَاكِلَهُ بِالتَّرَيُّثِ"" : بِالتَّأَنِّي، بِتَأَمُّلِهَا مَلِيّاً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18900, 'تَرَيُّضٌ', 'تريض', 'مصدر', 'روض', 'تريض', 'ترض', 'مص. تَرَيَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَرَيُّضٌ-تَرَيُّضٌ [رو ض] (مص. تَرَيَّضَ). ""التَّرَيُّضُ ضَرُورِيٌّ لِلْجِسْمِ"" : القِيَامُ بِتَمَارينَ رِيَاضِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18901, 'تَزَاحُفٌ', 'تزاحف', 'مصدر', 'زحف', 'تزاحف', 'تزحف', 'مص. تَزَاحَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَاحُفٌ-تَزَاحُفٌ [ز ح ف] (مص. تَزَاحَفَ). ""اِنْطَلَقَ الجُنْدُ فِي تَزَاحُفٍ"" : زَحْفُ بَعْضِهِمْ وَاقْتِرَابُهُم إِلَى بَعْضٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18902, 'تَزَاحُمٌ', 'تزاحم', 'مصدر', 'زحم', 'تزاحم', 'تزحم', 'مص. تَزَاحَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَاحُمٌ-تَزَاحُمٌ [ز ح م] (مص. تَزَاحَمَ). ""وَجَدَ النَّاسَ فيِ تَزَاحُمٍ"" : فِي تَدَافُعٍ وَازْدِحَامٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18903, 'تَزَامُنٌ', 'تزامن', 'مصدر', 'زمن', 'تزامن', 'تزمن', 'مص. تَزَامَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَامُنٌ-تَزَامُنٌ [ز م ن] (مص. تَزَامَنَ). ""تَزَامُنُ الحَدَثَيْنِ"" : وُقُوعُهُمَا فِي الوَقْتِ نَفْسِهِ. ""تَزَامُنُ الأَحْدَاثِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18904, 'تَزَاهُدٌ', 'تزاهد', 'مصدر', 'زهد', 'تزاهد', 'تزهد', 'مص. تَزَاهَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَاهُدٌ-تَزَاهُدٌ [ز هـ د] (مص. تَزَاهَدَ). ""نَظَرُوا إِلَيْهِ نَظْرَةَ تَزَاهُدٍ"" : نَظْرَةَ احْتِقَارٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18905, 'تَزَاهُرٌ', 'تزاهر', 'مصدر', 'زهر', 'تزاهر', 'تزهر', 'مص. تَزَاهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَاهُرٌ-تَزَاهُرٌ [ز هـ ر] (مص. تَزَاهَرَ). ""تَزَاهُرُ الأَضْوَاءِ"" : تَلأْلُؤُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18906, 'تَزَاوُرٌ', 'تزاور', 'مصدر', 'زور', 'تزاور', 'تزر', 'مص. تَزَاوَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَاوُرٌ-تَزَاوُرٌ [ز و ر ] (مص. تَزَاوَرَ). 1.""تَزَاوُرُ أَفْرَادِ العَائِلَةِ"": زِيَارَةُ بَعْضِهِمْ بَعْضاً. 2.""تَزَاوُرُ الشَّمْسِ"" : اِنْحِرَافُهَا، مَيَلاَنُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18907, 'تَزَايُدٌ', 'تزايد', 'مصدر', 'زيد', 'تزايد', 'تزد', 'مص. تَزَايَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَايُدٌ-تَزَايُدٌ [ز ي د] (مص. تَزَايَدَ). 1.""عَدَدُ السُّكَّانِ فِي تَزَايُدٍ"" : فيِ تَكَاثُرٍ. 2.""التَّزَايُدُ فِي الحَدِيثِ"" : الزِّيَادَةُ فِيهِ وَالْمُبَالَغَةُ إِلَى حَدِّ الكَذِبِ. 3.""تَزَايُدُ الْمَعَارِفِ"" : تَكَاثُرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18908, 'تَزَبُّبٌ', 'تزبب', 'مصدر', 'زبب', 'تزبب', 'تزب', 'مص. تَزَبَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَبُّبٌ-تَزَبُّبٌ [ز ب ب] (مص. تَزَبَّبَ). ""تَزَبُّبُ العِنَبِ"" : صَيْرُهُ زَبِيباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18909, 'تَزَحْزُحٌ', 'تزحزح', 'مصدر', 'زحزح', 'تزحزح', 'تزحزح', 'مص. تَزَحْزَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَحْزُحٌ-تَزَحْزُحٌ [ز ح ز ح] (مص. تَزَحْزَحَ). ""التَّزَحْزُحُ عَنِ الْمَكَانِ"" : التَّنَحِّي عَنْهُ، الابْتِعَادُ عَنْهُ، تَرْكُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18910, 'تَزَحْلُقٌ', 'تزحلق', 'مصدر', 'زحل', 'تزحلق', 'تزحلق', 'مص. تَزَحْلَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَحْلُقٌ-تَزَحْلُقٌ [ز ح ل] (مص. تَزَحْلَقَ). 1.""التَّزَحْلُقُ عَلَى الجَلِيدِ"" : التَّزَلُّجُ. 2.""تَزَحْلُقُ السَّيَّارَةِ"" : اِنْزِلاَقُهَا. 3.""التَّزَحْلُقُ مِنَ الْمُنْحَدَرِ"" : التَّدَحْرُجُ. 4.""التَّزَحْلُقُ عَنِ الْمَكَانِ"" : التَّنَحِّي، الاِبْتِعَادُ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18911, 'تَزَعْزُعٌ', 'تزعزع', 'مصدر', 'زعزع', 'تزعزع', 'تزعزع', 'مص. تَزَعْزَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَعْزُعٌ-تَزَعْزُعٌ [ز ع ز ع] (مص. تَزَعْزَعَ). 1.""تَزَعْزُعُ الْمَكَانِ"" : تَحَرُّكُهُ، تَقَلْقُلُهُ. 2.""تَزَعْزُعُ مَرْكَزِهِ"" : عَدَمُ ثُبُوتِهِ وَرُسُوخِهِ، اِضْطِرَابُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18912, 'تَزَعُّمٌ', 'تزعم', 'مصدر', 'زعم', 'تزعم', 'تزعم', 'مص. تَزَعَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَعُّمٌ-تَزَعُّمٌ [ز ع م] (مص. تَزَعَّمَ). 1.""لاَحَظَ فيِ أَحَادِيثِهِ تَزَعُّماً"" : اِخْتِلاَقاً لِلأَكَاذِيبِ. 2.""تَزَعُّمُ الفَرِيقِ"" : زَعَامَتُهُ، رِئَاسَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18913, 'تَزَكِّي', 'تزكي', 'مصدر', 'زكي', 'تزكي', 'تزك', 'مص. تَزَكَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R0', '', '', '', '', '', '', '"تَزَكٍّ-تَزَكٍّ، التَّزَكِّي [ز ك ي] (مص. تَزَكَّى). 1.""التَّزَكِّي عَلَى الفُقَرَاءِ"" : التَّصَدُّقُ، إِخْراجُ الزَّكَاةِ. 2.""تِجَارَتُهُ فِي تَزَكٍّ"": فِي تَنَامٍ، فِي زِيادَةٍ وَتَكَاثُرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18914, 'تَزَلُّجٌ', 'تزلج', 'مصدر', 'زلج', 'تزلج', 'تزلج', 'مص. تَزَلَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَلُّجٌ-تَزَلُّجٌ [ز ل ج] (مص. تَزَلَّجَ). ""يُحِبُّ رِيَاضَةَ التَّزَلُّجِ"": رِيَاضَةُ التَّزَحْلُقِ عَلَى الثَّلْجِ بِوَاسِطَةِ خَشَبَتَيْنِ مُسَطَّحَتَيْنِ طَوِيلَتَيْنِ تَلْتَصِقَانِ بِالرِّجْلَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18915, 'تَزَلْزُلٌ', 'تزلزل', 'مصدر', 'زلزل', 'تزلزل', 'تزلزل', 'مص. تَزَلْزَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَلْزُلٌ-تَزَلْزُلٌ [ز ل ز ل] (مص. تَزَلْزَلَ). ""تَزَلْزُلُ الأَرْضِ"" : اِهْتِزَازُهَا، اِرْتِجَاجُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18916, 'تَزَلُّفٌ', 'تزلف', 'مصدر', 'زلف', 'تزلف', 'تزلف', 'مص. تَزَلَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَلُّفٌ-تَزَلُّفٌ [ز ل ف] (مص. تَزَلَّفَ). ""مَا الَّذِي يَدْفَعُهُ إِلَى التَّزَلُّفِ"" : التَّذَلُّلِ، التَّقَرُّبِ إِلَى الشَّيْءِ بِمَهَانَةٍ وَمَذَلَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18917, 'تَزَمُّتٌ', 'تزمت', 'مصدر', 'زمت', 'تزمت', 'تزمت', 'مص. تَزَمَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَمُّتٌ-تَزَمُّتٌ [ز م ت] (مص. تَزَمَّتَ). 1.""مَا أَشَـدَّ تَزَمُّتَـهُ !"": سُكُوتَهُ وَصَمْتَهُ، تَوَقُّرَهُ. 2.""مَا هَذَا التَّزَمُّتُ "" : الصَّرَامَةُ الْمُتَشَدِّدَةُ، التَّشَدُدُ فيِ الرَّأْيِ أَوِ الدِّينِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18918, 'تَزَمْخُرٌ', 'تزمخر', 'مصدر', 'زمخ', 'تزمخر', 'تزمخر', 'مص. تَزَمْخَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَمْخُرٌ-تَزَمْخُرٌ [ز م خ] (مص. تَزَمْخَرَ). ""تَزَمْخُرُ النَّمِرِ"" : صِيَاحُهُ غَاضِباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18919, 'تَزَمُّلٌ', 'تزمل', 'مصدر', 'زمل', 'تزمل', 'تزمل', 'مص. تَزَمَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَمُّلٌ-تَزَمُّلٌ [ز م ل] (مص. تَزَمَّلَ). ""التَّزَمُّلُ بِالغِطَاءِ"" : التَّلَفُّفُ بِهِ، التَّغَطِّي بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18920, 'تَزَنْدُقٌ', 'تزندق', 'مصدر', 'زند', 'تزندق', 'تزندق', 'مص. تَزَنْدَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَنْدُقٌ-تَزَنْدُقٌ [ز ن د] (مص. تَزَنْدَقَ). ""تَزَنْدُقُ الرَّجُلِ"": تَخَلُّقُهُ بِأَخْلاَقِ الزَّنَادِقَةِ، صَيْرُهُ زِنْدِيقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18921, 'تَزَهُّدٌ', 'تزهد', 'مصدر', 'زهد', 'تزهد', 'تزهد', 'مص. تَزَهَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَهُّدٌ-تَزَهُّدٌ [ز هـ د] (مص. تَزَهَّدَ). ""عُرِفَ بِالتَّزَهُّدِ"" : بِالعِبَادَةِ الْمُتَوَاصِلَةِ وَالتَّفَرُّغِ لَهَا، وَتَرْكِ أُمُورِ الدُّنْيَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18922, 'تَزَوُّجٌ', 'تزوج', 'مصدر', 'زوج', 'تزوج', 'تزج', 'مص. تَزَوَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَوُّجٌ-تَزَوُّجٌ [ز و ج] (مص. تَزَوَّجَ). ""بِحَاجَةٍ إِلَى التَّزَوُّجِ"": بِحَاجَةٍ إِلَى التَّأَهُّلِ بِامْرَأَةٍ وَاتِّخَاذِهَا زَوْجَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18923, 'تَزَوُّدٌ', 'تزود', 'مصدر', 'زود', 'تزود', 'تزد', 'مص. تَزَوَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَوُّدٌ-تَزَوُّدٌ [ز و د] (مص. تَزَوَّدَ). ""تَزَوُّدُ الْمُسَافِرِ بِمَا يَلْزَمُ مِنْ زَادٍ"" : حَمْلُهُ الزَّادَ وَالْمُؤَنَ، تَمَوُّنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18924, 'تَزَيِّي', 'تزيي', 'مصدر', 'زيي', 'تزيي', 'تز', 'مص. تَزَيَّا', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَزَيٍّ-تَزَيٍّ، التَّزَيِّي [ز ي ي] (مص. تَزَيَّا). ""التَّزَيِّي بِاللِّبَاسِ العَسْكَرِيِّ"" : لبسه."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18925, 'تَزَيُّنٌ', 'تزين', 'مصدر', 'زين', 'تزين', 'تزن', 'مص. تَزَيَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَزَيُّنٌ-تَزَيُّنٌ [ز ي ن] (مص. تَزَيَّنَ). 1.""تَزَيُّنُ الْمَرْأَةِ"" : تَجْمِيلُهَا بِالحِلِيِّ وَوَضْعِ الْمَسَاحِيقِ. 2.""تَزَيُّنُ الشَّوَارِعِ بِالأَضْوَاءِ وَالرَّايَاتِ"" : تَحَسُّنُهَا وَزَخْرَفَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18926, 'تَسَاؤُلٌ', 'تساؤل', 'مصدر', 'سأل', 'تساءل', 'تسل', 'مص. تَسَاءلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. تَسَاءلَ). ""أَثَارُوا التَّسَاؤُلَ عَمَّا حَدَثَ"" : إِثَارَةُ السُّؤَالِ وَتَبَادُلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18927, 'تَسَابُقٌ', 'تسابق', 'مصدر', 'سبق', 'تسابق', 'تسبق', 'مص. تَسَابَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَابُقٌ-تَسَابُقٌ [س ب ق] (مص. تَسَابَقَ). ""تَسَابُقُ العَدَّائِينَ"": تَنَافُسُهُمْ، مُنَافَسَتُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18928, 'تَسَاجُلٌ', 'تساجل', 'مصدر', 'سجل', 'تساجل', 'تسجل', 'مص. تَسَاجَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَاجُلٌ-تَسَاجُلٌ [س ج ل] (مص. تَسَاجَلَ). 1.""اِنْسَاقُوا وَرَاءَ تَسَاجُلٍ لاَ فَائِدَةَ مِنْهُ"" : التَّبَارِي، التَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18929, 'تَسَارٌّ', 'تسار', 'مصدر', 'سرر', 'تسار', 'تسر', 'مص. تَسَارَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَارٌّ-تَسَارٌّ [س ر ر] (مص. تَسَارَّ). ""وَجَدَهُمَا فِي تَسَارٍّ فِي زَاوِيَةِ البَيْتِ"" : إِطْلاَعُ أَحَدِهِمَا الآخَرَ عَلَى سِرٍّ مِنْ أَسْرَارِهِ، التَّنَاجِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18930, 'تَسَارُعٌ', 'تسارع', 'مصدر', 'سرع', 'تسارع', 'تسرع', 'مص. تَسَارَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَارُعٌ-تَسَارُعٌ [س ر ع] (مص. تَسَارَعَ). ""جاءوا فِي تَسَارُعٍ"" : فِي إِسْرَاعٍ وَتَسَابُقٍ فِي الجَرْيِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18931, 'تَسَافُدٌ', 'تسافد', 'مصدر', 'سفد', 'تسافد', 'تسفد', 'مص. تَسَافَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَافُدٌ-تَسَافُدٌ [س ف د] (مص. تَسَافَدَ). ""تَسَافُدُ الْحَيَوَانِ"": أَيْ رُكُوبُ بَعْضِهِ عَلَى بَعْضٍ، فِي حَالَةِ نَزْوٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18932, 'تَسَاقُطٌ', 'تساقط', 'مصدر', 'سقط', 'تساقط', 'تسقط', 'مص. تَسَاقَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَاقُطٌ-تَسَاقُطٌ [س ق ط] (مص. تَسَاقَطَ). 1.""تَسَاقُطُ الأَوْرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18933, 'تَسَاقِي', 'تساقي', 'مصدر', 'سقي', 'تساقي', 'تسق', 'مص. تَسَاقَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَسَاقٍ-تَسَاقٍ، التَّسَاقِي [س ق ي] (مص. تَسَاقَى). """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18934, 'تَسَاكُبٌ', 'تساكب', 'مصدر', 'سكب', 'تساكب', 'تسكب', 'مص. تَسَاكَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَاكُبٌ-تَسَاكُبٌ [س ك ب] (مص. تَسَاكَبَ). ""تَسَاكُبُ الدُّمُو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18935, 'تَسَاكُنٌ', 'تساكن', 'مصدر', 'سكن', 'تساكن', 'تسكن', 'مص. تَسَاكَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَاكُنٌ-تَسَاكُنٌ [س ك ن] (مص. تَسَاكَنَ). 1.""التَّسَاكُنُ فِي العِمَارَةِ نَفْسِها"" : سكناها مَعاً. 2.""ظَلَّتْ عِشْرَتُهُمْ فِي تَسَاكُنٍ وَوِئَامٍ"" : فِي تَعَايُشٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18936, 'تَسَامُحٌ', 'تسامح', 'مصدر', 'سمح', 'تسامح', 'تسمح', 'مص. تَسَامَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَامُحٌ-تَسَامُحٌ [س م ح] (مص. تَسَامَحَ).""مِنْ صِفَاتِهِ التَّسَامُحُ"" : التَّسَاهُلُ، الحِلْمُ، العَفْوُ. ""لاَ تَسَامُحَ، لاَ تَصَالُحَ مَعَ العَدُوِّ مَا دَامَ عَدُوّاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18937, 'تَسَامُرٌ', 'تسامر', 'مصدر', 'سمر', 'تسامر', 'تسمر', 'مص. تَسَامَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَامُرٌ-تَسَامُرٌ [س م ر] (مص. تَسَامَرَ). ""اِسْتَغْرَقَ الصِّحَابُ فِي تَسَامُرٍ"" : فِي التَّحَدُّثِ لَيْلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18938, 'تَسَامِي', 'تسامي', 'مصدر', 'سمو', 'تسامي', 'تسم', 'مص. تَسَامَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَسَامٍ-تَسَامٍ، التَّسَامِي [س م و] (مص. تَسَامَى). 1.""التَّسَامِي عَنِ الرَّذَائِلِ"" : التَّرَفُّعُ، التَّعَالِي عَنْهَا. 2.""تَسَامِي أَعْضَاءِ القَبِيلَةِ"" : تَفَاخُرُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18939, 'تَسَاهُلٌ', 'تساهل', 'مصدر', 'سهل', 'تساهل', 'تسهل', 'مص. تَسَاهَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَاهُلٌ-تَسَاهُلٌ [س هـ ل] (مص. تَسَاهَلَ). ""لاَ يَعْرِفُ مَعْنَى التَّسَاهُلِ"" : الرَّأْفَةُ، الحِلْمُ، التَّسَامُحُ. ""التَّسَاهُلُ خَيْرٌ مِنَ التَّصَلُّبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18940, 'تَسَاوُمٌ', 'تساوم', 'مصدر', 'سوم', 'تساوم', 'تسم', 'مص. تَسَاوَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَاوُمٌ-تَسَاوُمٌ [س و م] (مص. تَسَاوَمَ). ""لَمْ يَشْتَرِ البِضَاعَةَ إِلاَّ بَعْدَ تَسَاوُمٍ"" : بَعْدَ مُسَاوَمَةٍ وَتَفَاوُضٍ عَلَى الثَّمَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18941, 'تَسَاوِي', 'تساوي', 'مصدر', 'سوي', 'تساوي', 'تس', 'مص. تَسَاوَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَسَاوٍ-تَسَاوٍ، التَّسَاوِي [س و ي] (مص. تَسَاوَى). ""وَزَّعَ الهَدَايَا بِالتَّسَاوِي"" : بِالتَّكَافُؤِ، بِالعَدْلِ لِيَأْخُذَ كُلٌّ نَصِيبَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18942, 'تَسَايُرٌ', 'تساير', 'مصدر', 'سير', 'تساير', 'تسر', 'مص. تَسَايَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَايُرٌ-تَسَايُرٌ [س ي ر] (مص. تَسَايَرَ). 1.""تَسَايُرُ الرَّجُلَيْنِ"": تَجَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18943, 'تَسَايُفٌ', 'تسايف', 'مصدر', 'سيف', 'تسايف', 'تسف', 'مص. تَسَايَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَايُفٌ-تَسَايُفٌ [س ي ف] (مص. تَسَايَفَ). ""خَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18944, 'تَسَايُلٌ', 'تسايل', 'مصدر', 'سيل', 'تسايل', 'تسل', 'مص. تَسَايَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَايُلٌ-تَسَايُلٌ [س ي ل] (مص. تَسَايَلَ). ""تَسَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18945, 'تَسَبُّبٌ', 'تسبب', 'مصدر', 'سبب', 'تسبب', 'تسب', 'مص. تَسَبَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَبُّبٌ-تَسَبُّبٌ [س ب ب ] (مص. تَسَبَّبَ). 1.""التَّسَبُّبُ فِيمَا حَدَثَ"" : مَا أَدَّى إِلَى حُدُوثِ مَا حَدَثَ. 2.""كَانَ مِنْ تَسَبُّبِ الزِّلْزَالِ، اِنْهِيَارُ مَدِينَةٍ"" : مَا نَتَجَ وَنَجَمَ. 3.""التَّسَبُّبُ فِي تِجَارَةِ الخُرْدَةِ"" : تَعَاطِي تِجَارَةِ الخُرْدَةِ لِكَسْبِ الرِّزْقِ. 4.""أَرَادَ التَّسَبُّبَ إِلَيْهِ"" : التَّوَسُّلَ إِلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18946, 'تَسَتُّرٌ', 'تستر', 'مصدر', 'ستر', 'تستر', 'تستر', 'مص. تَسَتَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَتُّرٌ-تَسَتُّرٌ [س ت ر] (مص. تَسَتَّرَ). ""حَاوَلَ التَّسَتُّرَ عَنْ أَخْطَائِهِ"" : التَّمْوِيهَ عَنْهَا، إِخْفَاءهَا، سَتْرَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18947, 'تَسَجُّلٌ', 'تسجل', 'مصدر', 'سجل', 'تسجل', 'تسجل', 'مص. تَسَجَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَجُّلٌ-تَسَجُّلٌ [س ج ل] (مص. تَسَجَّلَ). ""التَّسَجُّلُ فِي القَائِمَةِ"" : التَّقَيُّدُ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18948, 'تَسَخُّرٌ', 'تسخر', 'مصدر', 'سخر', 'تسخر', 'تسخر', 'مص. تَسَخَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَخُّرٌ-تَسَخُّرٌ [س خ ر] (مص. تَسَخَّرَ). 1.""أَرَادَ تَسَخُّرَهُ"" : تَك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18949, 'تَسَدُّدٌ', 'تسدد', 'مصدر', 'سدد', 'تسدد', 'تسد', 'مص. تَسَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَدُّدٌ-تَسَدُّدٌ [س د د] (مص. تَسَدَّدَ). ""تَسَدُّدُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18950, 'تَسَدُّرٌ', 'تسدر', 'مصدر', 'سدر', 'تسدر', 'تسدر', 'مص. تَسَدَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَدُّرٌ-تَسَدُّرٌ [س د ر] (مص. تَسَدَّرَ). ""التَّسَد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18951, 'تَسَرُّبٌ', 'تسرب', 'مصدر', 'سرب', 'تسرب', 'تسرب', 'مص. تَسَرَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَرُّبٌ-تَسَرُّبٌ [س ر ب] (مص. تَسَرَّبَ). 1.""اِنْتَبَهَ الْجيرَانُ إِلَى تَسَرُّبِ الْمَاءِ مِنْ تَحْتِ البَابِ"" : اِنْسِيَابُهُ،"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18952, 'تَسَرْبُلٌ', 'تسربل', 'مصدر', 'سرب', 'تسربل', 'تسربل', 'مص. تَسَرْبَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَرْبُلٌ-تَسَرْبُلٌ [س ر ب] (مص. تَسَرْبَلَ). 1.""يُعْجِبُهُ التَّسَرْبُلُ بِال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18953, 'تَسَرُّحٌ', 'تسرح', 'مصدر', 'سرح', 'تسرح', 'تسرح', 'مص. تَسَرَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَرُّحٌ-تَسَرُّحٌ [س ر ح] (مص. تَسَرَّحَ). 1.""تَسَرُّحُ الشَّعْرِ"": اِنْحِلاَلُهُ. 2.""تَسَرُّحُ السَّجِينِ"" : خُرُوجُهُ مِنَ السِّجْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18954, 'تَسَرُّعٌ', 'تسرع', 'مصدر', 'سرع', 'تسرع', 'تسرع', 'مص. تَسَرَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَرُّعٌ-تَسَرُّعٌ [س ر ع] (مص. تَسَرَّعَ). 1.""التَّسَرُّعُ فِي إِنْجَازِ أَمْرٍ مَّا"": التَّصَرُّفُ فِي إِنْجَازِهِ بِلاَ تَفْكِيرٍ وَلاَ رَوِيَّةٍ. 2.""قَادَهُمُ الظَّرْفُ السِّيَاسِيُّ إِلىَ التَّسَرُّعِ لاتِّخَاذِ قَرَارٍ غَيْرِ مُنَاسِبٍ"" : الْمُبَادَرَةُ، التَّعْجِيلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18955, 'تَسَرْوُلٌ', 'تسرول', 'مصدر', 'سرو', 'تسرول', 'تسرل', 'مص. تَسَرْوَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَرْوُلٌ-تَسَرْوُلٌ [س ر و] (مص. تَسَرْوَلَ). ""تَسَرْوُلُ الْمَرْأَةِ"": لُبْسُهَا السِّرْوَالَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18956, 'تَسَطُّحٌ', 'تسطح', 'مصدر', 'سطح', 'تسطح', 'تسطح', 'مص. تَسَطَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَطُّحٌ-تَسَطُّحٌ [س ط ح] (مص. تَسَطَّحَ). 1.""تَسَطُّحُ الوَلَدِ عَلَى الأَرْضِ"" : تَمَدُّدُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18957, 'تَسَفُّدٌ', 'تسفد', 'مصدر', 'سفد', 'تسفد', 'تسفد', 'مص. تَسَفَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَفُّدٌ-تَسَفُّدٌ [س ف د] (مص. تَسَفَّدَ). ""تَسَفُّدُ الرَّاكِبِ دَابَّتَهُ"" : رُكُوبُهَا مِنَ الخَلْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18958, 'تَسَفُّلٌ', 'تسفل', 'مصدر', 'سفل', 'تسفل', 'تسفل', 'مص. تَسَفَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَفُّلٌ-تَسَفُّلٌ [س ف ل] (مص. تَسَفَّلَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18959, 'تَسَفُّهٌ', 'تسفه', 'مصدر', 'سفه', 'تسفه', 'تسفه', 'مص. تَسَفَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَفُّهٌ-تَسَفُّهٌ [س ف هـ] (مص. تَسَفَّهَ). ""تَسَف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18960, 'تَسَكُّعٌ', 'تسكع', 'مصدر', 'سكع', 'تسكع', 'تسكع', 'مص. تَسَكَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَكُّعٌ-تَسَكُّعٌ [س ك ع] (مص. تَسَكَّعَ). ""يَعِيش"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18961, 'تَسَكُّنٌ', 'تسكن', 'مصدر', 'سكن', 'تسكن', 'تسكن', 'مص. تَسَكَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَكُّنٌ-تَسَكُّنٌ [س ك ن] (مص. تَسَكَّنَ). 1.""تَسَكُّنُ الرَّجُلِ"" : صَيْرُهُ مِسْكِينًا، تَشَبُّهُهُ بِالْمَسَاكِينِ. 2.""تَسَكُّنُ العَابِدِ"": اِطْمِئْنَانُهُ، صَيْرُهُ وَقُورًا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18962, 'تَسَلُّحٌ', 'تسلح', 'مصدر', 'سلح', 'تسلح', 'تسلح', 'مص. تَسَلَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَلُّحٌ-تَسَلُّحٌ [س ل ح] (مص. تَسَلَّحَ). 1.""تَسَلُّحُ الجُنْدِيِّ"": لُبْسُهُ السِّلاَحَ، اِتِّخَاذُهُ لِلسِّلاَحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18963, 'تَسَلُّخٌ', 'تسلخ', 'مصدر', 'سلخ', 'تسلخ', 'تسلخ', 'مص. تَسَلَّخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَلُّخٌ-تَسَلُّخٌ [س ل خ] (مص. تَسَلَّخَ). ""تَسَلُّخُ الجِلْدِ"" : اِنْسِلاَخُهُ، اِنْكِشَافُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18964, 'تَسَلْسُلٌ', 'تسلسل', 'مصدر', 'سلسل', 'تسلسل', 'تسلسل', 'مص. تَسَلْسَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَلْسُلٌ-تَسَلْسُلٌ [س ل س ل] (مص. تَسَلْسَلَ). 1.""حَافَظَ عَلَى تَسَلْسُلِ أَفْكَارِهِ"" : عَلَى تَرْتِيبِهَا، تَتَابُعِهَا، وَتَدَرُّجِهَا. 2.""عَرَفَتِ الأَحْدَاثُ تَسَلْسُلاً مُثِيراً"" : تَتَابُعاً، تَلاَحُقاً. ""يَشُدُّنِي تَسَلْسُلُ أَفْكَارِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18965, 'تَسَلُّطٌ', 'تسلط', 'مصدر', 'سلط', 'تسلط', 'تسلط', 'مص. تَسَلَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَلُّطٌ-تَسَلُّطٌ [س ل ط] (مص. تَسَلَّطَ). ""حَاوَلَ التَّخَلُّصَ مِنْ تَسَلُّطِهِ"" : سَيْطَرَتِهِ وَهَيْمَنَتِهِ وَتَحَكُّمِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18966, 'تَسَلُّفٌ', 'تسلف', 'مصدر', 'سلف', 'تسلف', 'تسلف', 'مص. تَسَلَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَلُّفٌ-تَسَلُّفٌ [س ل ف] (مص. تَسَلَّفَ). ""تَسَلُّفُ مِقْدَارٍ مِنَ الْمَالِ"" : اِقْتِرَاضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18967, 'تَسَلُّقٌ', 'تسلق', 'مصدر', 'سلق', 'تسلق', 'تسلق', 'مص. تَسَلَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَلُّقٌ-تَسَلُّقٌ [س ل ق] (مص. تَسَلَّقَ). 1.""تَسَلُّقُ الجِبَالِ"" : اِرْتِقَاؤُهَا، اِعْتِلاَؤُهَا. 2.""تَسَلُّقُ شَجَ"', '');
