INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18970, 'تَسَلِّي', 'تسلي', 'مصدر', 'سلو', 'تسلي', 'تسل', 'مص. تَسَلَّي', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R0', '', '', '', '', '', '', '"تَسَلٍّ-تَسَلٍّ، التَّسَلِّي [س ل و] (مص. تَسَلَّي). 1.""التَّسَلِّي فِي أَوْقَاتِ الفَرَاغِ"" : التَّلَهِّي. 2.""تَسَلِّي الأَحْزَانِ عَنْهُ"" : اِنْقِشَاعُهَا، زَوَالُهَا، اِنْكِشَافُهَا عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18971, 'تَسَمُّرٌ', 'تسمر', 'مصدر', 'سمر', 'تسمر', 'تسمر', 'مص. تَسَمَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسَمُّرٌ-تَسَمُّرٌ [س م ر] (مص. تَسَمَّرَ). 1.""تَسَمُّرُ اللَّوْحِ"" : إِثْبَاتُهُ. 2.""التَّسَمُّرُ فِي الْمَكَانِ"" : الثُّبُوتُ فِيهِ."', '');
