INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18989, 'تَشَاجُرٌ', 'تشاجر', 'مصدر', 'شجر', 'تشاجر', 'تشجر', 'مص. تَشَاجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَاجُرٌ-تَشَاجُرٌ [ش ج ر] (مص. تَشَاجَرَ). 1.""تَشَاجُرُ الأَشْجَارِ"" : تَدَاخُلُ أَغْصَانِهَا. 2.""تَشَاجُرُ الأَوْلاَدِ"" : تَنَازُعُهُمْ، تَضَارُبُهُمْ، اِشْتِبَاكُهُمْ بِالأَيْدِي. 3.""التَّشَاجُرُ بِالرِّمَاحِ"" : التَّطَاعُنُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18990, 'تَشَاحُنٌ', 'تشاحن', 'مصدر', 'شحن', 'تشاحن', 'تشحن', 'مص. تَشَاحَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَاحُنٌ-تَشَاحُنٌ [ش ح ن] (مص. تَشَاحَنَ). ""اِزْدَادَ التَّشَاحُنُ بَيْنَهُمْ"" : التَّحَاقُدُ، التَّبَاغُضُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18991, 'تَشَارُسٌ', 'تشارس', 'مصدر', 'شرس', 'تشارس', 'تشرس', 'مص. تَشَارَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَارُسٌ-تَشَارُسٌ [ش ر س] (مص. تَشَارَسَ). ""عَادَ الوِئَامُ بَيْنَهُمْ بَعْدَ تَشَارُسٍ"" : بَعْدَ تَجَافٍ وَتَعَادٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18992, 'تَشَارُطٌ', 'تشارط', 'مصدر', 'شرط', 'تشارط', 'تشرط', 'مص. تَشَارَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَارُطٌ-تَشَارُطٌ [ش ر ط] (مص. تَشَارَطَ). ""التَّشَارُطُ عَلَى اقْتِسَامِ الرِّبْحِ"" : الالْتِزَامُ بِشَرْطٍ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18993, 'تَشَارُكٌ', 'تشارك', 'مصدر', 'شرك', 'تشارك', 'تشرك', 'مص. تَشَارَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَارُكٌ-تَشَارُكٌ [ش ر ك] (مص. تَشَارَكَ). 1.""قَرَّرَا التَّشَارُكَ فِي التِّجَارَةِ"" : صَيْرُ كُلِّ وَاحِدٍ مِنْهُمَا شَرِيكاً لِلآخَرِ. 2.""التَّشَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18994, 'تَشَازُرٌ', 'تشازر', 'مصدر', 'شزر', 'تشازر', 'تشزر', 'مص. تَشَازَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَازُرٌ-تَشَازُرٌ [ش ز ر] (مص. تَشَازَرَ). ""يَسُودُ نَظَرَاتِهِمَا تَش"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18995, 'تَشَاغُبٌ', 'تشاغب', 'مصدر', 'شغب', 'تشاغب', 'تشغب', 'مص. تَشَاغَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَاغُبٌ-تَشَاغُبٌ [ش غ ب] (مص. تَشَاغَبَ). ""تَشَاغُبُ الصَّبِيَّيْنِ"" : إِثَارَةُ كُلِّ وَاحِدٍ مِنْهُمَا الشَّغَبَ عَلَى الآخَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18996, 'تَشَاغُلٌ', 'تشاغل', 'مصدر', 'شغل', 'تشاغل', 'تشغل', 'مص. تَشَاغَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَاغُلٌ-تَشَاغُلٌ [ش غ ل] (مص. تَشَاغَلَ). 1.""وَجَدَ نَفْسَهُ فِي تَشَاغُلٍ عَنْ مَهَامِّهِ"" : فِي شُغْلٍ عَنْهَا. 2.""التَّشَاغُلُ بِتَوَافِهِ الأَشْيَاءِ"" : التَّلَهِّي بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18997, 'تَشَاكُسٌ', 'تشاكس', 'مصدر', 'شكس', 'تشاكس', 'تشكس', 'مص. تَشَاكَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَاكُسٌ-تَشَاكُسٌ [ش ك س] (مص. تَشَاكَسَ). ""تَشَاكُسُ الأَطْفَالِ"" : تَنَازُعُهُمْ، تَضَارُبُهُمْ، تَخَالُفُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18998, 'تَشَاكُلٌ', 'تشاكل', 'مصدر', 'شكل', 'تشاكل', 'تشكل', 'مص. تَشَاكَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَاكُلٌ-تَشَاكُلٌ [ش ك ل] (مص. تَشَاكَلَ). ""تَشَاكُلُ الوَلَدَيْنِ"": تَشَابُهُهُمَا، تَمَاثُلُهُمَا. ""تَشَاكُلُ الْمَشْهَدَيْنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(18999, 'تَشَاكِي', 'تشاكي', 'مصدر', 'شكو', 'تشاكي', 'تشك', 'مص. تَشَاكَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَشَاكٍ-تَشَاكٍ، التَّشَاكِي [ش ك و] (مص. تَشَاكَى). ""كَثُرَ تَشَاكِيهمْ"" : تَبَادُلُ الشِّكَايةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19000, 'تَشَامُخٌ', 'تشامخ', 'مصدر', 'شمخ', 'تشامخ', 'تشمخ', 'مص. تَشَامَخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَامُخٌ-تَشَامُخٌ [ش م خ] (مص. تَشَامَخَ) 1.""تَشَامُخُ الجَبَلِ"": عُلُوُّهُ، اِرْتِفَاعُهُ. 2.""تَشَامُخُ الرَّجُلِ"" : تَكَبُّرُهُ، تَعَظُّمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19001, 'تَشَاوُرٌ', 'تشاور', 'مصدر', 'شور', 'تشاور', 'تشر', 'مص. تَشَاوَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَاوُرٌ-تَشَاوُرٌ [ش و ر] (مص. تَشَاوَرَ). ""خَرَجُوا لِلتَّشَاوُرِ"": لِتَبَادُلِ الآرَاءِ مِنْ أَجْلِ الاتِّفَاقِ عَلَى رَأْيٍ مُوَحَّدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19002, 'تَشَايُخٌ', 'تشايخ', 'مصدر', 'شيخ', 'تشايخ', 'تشخ', 'مص. تَشَايَخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَايُخٌ-تَشَايُخٌ [ش ي خ] (مص. تَشَايَخَ). ""تَشَايُخُ الطِّفْلِ"" : صَيْرُهُ كَالشَّيْخِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19003, 'تَشَايُعٌ', 'تشايع', 'مصدر', 'شيع', 'تشايع', 'تشع', 'مص. تَشَايَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَايُعٌ-تَشَايُعٌ [ش ي ع] (مص. تَشَايَعَ). 1.""وَجَدَ النَّاسَ فِي تَشَايُعٍ"" : فِي تَفَرُّقٍ، أَيْ وَجَدَهُمْ شِيَعاً وَفِرَقاً. 2.""تَشَايُعُ الجَمَاعَةِ عَلَى البِنَاءِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19004, 'تَشَبُّبٌ', 'تشبب', 'مصدر', 'شبب', 'تشبب', 'تشب', 'مص. تَشَبَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَبُّبٌ-تَشَبُّبٌ [ش ب ب] (مص. تَشَبَّبَ). 1.""تَشَبُّبُ الشَّيْخِ"" : ذِكْرُهُ أَيَّامَ الشَّبَابِ. 2.""تَشَبُّبُ الشَّاعِرِ بِالْمَرْأَةِ"" : التَّغَزُّلُ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19005, 'تَشَبُّثٌ', 'تشبث', 'مصدر', 'شبث', 'تشبث', 'تشبث', 'مص. تَشَبَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَبُّثٌ-تَشَبُّثٌ [ش ب ث] (مص. تَشَبَّثَ). 1.""التَّشَبُّثُ بِالعَمَلِ"" : التَّعَلُّقُ بِهِ. 2.""التَّشَبُّثُ بِالرَّأْيِ"" : التَّمَسُّكُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19006, 'تَشَبُّعٌ', 'تشبع', 'مصدر', 'شبع', 'تشبع', 'تشبع', 'مص. تَشَبَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَبُّعٌ-تَشَبُّعٌ [ش ب ع] (مص. تَشَبَّعَ). 1.""أَظْهَرَ تَشَبُّعاً"": أَظْهَرَ أَنَّهُ شَبْعَانُ. 2.""تَشَبُّعُ الأَرْضِ بِالْمَاءِ "" : اِمْتِصَاصُهَا أَقْصَى مَا يُمْكِنُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19007, 'تَشَبُّكٌ', 'تشبك', 'مصدر', 'شبك', 'تشبك', 'تشبك', 'مص. تَشَبَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَبُّكٌ-تَشَبُّكٌ [ش ب ك] (مص. تَشَبَّكَ). ""تَشَبُّكُ الأُمُورِ"" : اِلْتِبَاسُهَا، تَدَاخُلُهَا، اِخْتِلاَطُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19008, 'تَشَبُّهٌ', 'تشبه', 'مصدر', 'شبه', 'تشبه', 'تشبه', 'مص. تَشَبَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَبُّهٌ-تَشَبُّهٌ [ش ب هـ] (مص. تَشَبَّهَ). ""التَّشَبُّهُ بِالرَّئِيسِ"": مُمَاثَلَتُهُ، مُجَارَاتُهُ فِي سُلُوكِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19009, 'تَشَتُّتٌ', 'تشتت', 'مصدر', 'شتت', 'تشتت', 'تشت', 'مص. تَشَتَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَتُّتٌ-تَشَتُّتٌ [ش ت ت] (مص. تَشَتَّتَ). ""تَشَتُّتُ الْمَتَاعِ"": تَفَرُّقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19010, 'تَشَجُّعٌ', 'تشجع', 'مصدر', 'شجع', 'تشجع', 'تشجع', 'مص. تَشَجَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَجُّعٌ-تَشَجُّعٌ [ش ج ع] (مص. تَشَجَّعَ). ""تَشَجُّعُ البَطَلِ"" : بَعْثُ الشَّجَاعَةِ فِي نَفْسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19011, 'تَشَخُّصٌ', 'تشخص', 'مصدر', 'شخص', 'تشخص', 'تشخص', 'مص. تَشَخَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَخُّصٌ-تَشَخُّصٌ [ش خ ص] (مص. تَشَخَّصَ). 1.""تَشَخُّصُ الصُّورَةِ"" : تَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19012, 'تَشَدُّدٌ', 'تشدد', 'مصدر', 'شدد', 'تشدد', 'تشد', 'مص. تَشَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَدُّدٌ-تَشَدُّدٌ [ش د د] (مص. تَشَدَّدَ). 1.""التَّشَدُّدُ فِي الْمُقَاوَمَةِ"" : التَّقَوِّي، إِظْهَارُ الصَّلاَبَةِ. 2.""التَّشَدُّدُ فيِ التَّنْقِيطِ أَوْ فِي صَرْفِ الْمَالِ"" : التَّقْتِيرُ. 3.""رَأَى فِي مَوْقِفِهِ تَشَدُّداً"" : تَصَلُّباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19013, 'تَشَدُّقٌ', 'تشدق', 'مصدر', 'شدق', 'تشدق', 'تشدق', 'مص. تَشَدَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَدُّقٌ-تَشَدُّقٌ [ش د ق] (مص. تَشَدَّقَ). 1.""التَّشَدُّقُ بِالكَلاَمِ"" : التَّكَلُّمُ دُونَ احْتِرَازٍ. 2.""كَفَاكَ تَشَدُّقاً"" : اِسْتِهْزَاءً، غُرُوراً، سُخْرِيَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19014, 'تَشَذُّبٌ', 'تشذب', 'مصدر', 'شذب', 'تشذب', 'تشذب', 'مص. تَشَذَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَذُّبٌ-تَشَذُّبٌ [ش ذ ب] (مص. تَشَذَّبَ). 1.""تَشَذُّبُ الشَّجَرِ"" : تَقَطُّعُ أَغْصَانِهِ، تَقَشُّرُهَا. 2.""تَشَذُّبُ أَوْرَاقِ الشَّجَرِ"": تَفَرُّقُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19015, 'تَشَرُّفٌ', 'تشرف', 'مصدر', 'شرف', 'تشرف', 'تشرف', 'مص. تَشَرَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَرُّفٌ-تَشَرُّفٌ [ش ر ف] (مص. تَشَرَّفَ). 1.""تَشَرُّفُ الرَّجُلِ"" : نَيْلُهُ الشَّرَفَ. 2.""وَجَدَ ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19016, 'تَشَظِّي', 'تشظي', 'مصدر', 'شظي', 'تشظي', 'تشظ', 'مص. تَشَظَّى ', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَشَظٍّ-تَشَظٍّ، التَّشَظِّي [ش ظ ي] (مص. تَشَظَّى) 1.""تَشَظِّي العُودِ"" : تَطَايُرُهُ شَظَايَا. 2."" تَشَظِّي اللَّوْحِ"" : اِنْشِقَاقُهُ. 3.""تَشَظِّي الجَمَاعَةِ"" : تَفَرُّقُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19017, 'تَشَعُّبٌ', 'تشعب', 'مصدر', 'شعب', 'تشعب', 'تشعب', 'مص. تَشَعَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَعُّبٌ-تَشَعُّبٌ [ش ع ب] (مص. تَشَعَّبَ). 1.""تَشَعُّبُ أَغْصَانِ الشَّجَرِ"" : اِنْتِشَارُهَا وَتَدَاخُلُهَا. 2.""تَشَعُّبُ النَّهْرِ"" : تَفَرُّقُهَا أَنْهَاراً وَشِعَاباً. 3."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19018, 'تَشَعُّثٌ', 'تشعث', 'مصدر', 'شعث', 'تشعث', 'تشعث', 'مص. تَشَعَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَعُّثٌ-تَشَعُّثٌ [ش ع ث] (مص. تَشَعَّثَ). 1.""تَشَعُّثُ الشَّعْر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19019, 'تَشَعْشُعٌ', 'تشعشع', 'مصدر', 'شعشع', 'تشعشع', 'تشعشع', 'مص. تَشَعْشَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَعْشُعٌ-تَشَعْشُعٌ [ش ع ش ع] (مص. تَشَعْشَعَ). ""تَشَعْشُعُ الضَّوْءِ"" : اِنْتِشَارُهُ مُتَلَأْلِئاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19020, 'تَشَعُّلٌ', 'تشعل', 'مصدر', 'شعل', 'تشعل', 'تشعل', 'مص. تَشَعَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَعُّلٌ-تَشَعُّلٌ [ش ع ل] (مص. تَشَعَّلَ). ""تَشَعُّلُ النَّارِ"" : اِتِّقَادُهَا، اِلْتِهَابُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19021, 'تَشَفُّعٌ', 'تشفع', 'مصدر', 'شفع', 'تشفع', 'تشفع', 'مص. تَشَفَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَفُّعٌ-تَشَفُّعٌ [ش ف ع] (مص. تَشَفَّعَ). 1.""جَاءَ لِلتَّشَفُّعِ لَهُ"": طَلَبُ الشَّفَاعَةِ وَالرَّحْمَةِ لَهُ. 2.""أَرَادَ التَّشَفُّعَ بِهِ"": جَعْلَهُ شَفِيعاً، التَّوَسُّلُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19022, 'تَشَفِّي', 'تشفي', 'مصدر', 'شفي', 'تشفي', 'تشف', 'مص. تَشَفَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَشَفٍّ-تَشَفٍّ، التَّشَفِّي [ش ف ي] (مص. تَشَفَّى). 1.""التَّشَفِّي مِنَ الغَيْظِ"" : الهُدُوءُ وَالتَّخَلُّصُ مِنْ. 2.""التَّشَفِّي مِنَ الأَعْدَاءِ"" : الشُّعُورُ بِالسُّرُورِ نِكَايَةً مِنْهُمْ، كَأَنَّهُ يَأْخُذُ ثَأْرَهُ مِنْهُمْ. 3.""التَّشَفِّي بِالدَّوَاءِ"": الشِّفَاءُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19023, 'تَشَقُّقٌ', 'تشقق', 'مصدر', 'شقق', 'تشقق', 'تشق', 'مص. تَشَقَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَقُّقٌ-تَشَقُّقٌ [ش ق ق] (مص. تَشَقَّقَ). 1.""تَشَقُّقُ الجِدَارِ"": تَصَدُّعُهُ، وُجُودُ شُقُوقٍ بِهِ. 2.""تَشَقُّقُ القَدَمِ"" : وُجُودُ شُقُوقٍ بِهَا، فَجَوَاتٍ بِدَاخِلِهَا. 3.""تَشَقُّقُ الشَّفَةِ"" : تَفَلُّقُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19024, 'تَشَكُّرٌ', 'تشكر', 'مصدر', 'شكر', 'تشكر', 'تشكر', 'مص. تَشَكَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَكُّرٌ-تَشَكُّرٌ [ش ك ر] (مص. تَشَكَّرَ). ""قَدَّمَ لَهُ تَشَكُّرَهُ"" : شُكْرَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19025, 'تَشَكُّكٌ', 'تشكك', 'مصدر', 'شكك', 'تشكك', 'تشك', 'مص. تَشَكَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَكُّكٌ-تَشَكُّكٌ [ش ك ك] (مص. تَشَكَّكَ). ""التَّشَكُّكُ فِي الأَمْرِ"" : الشَّكُّ فِيهِ، الارْتِيَابُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19026, 'تَشَكُّلٌ', 'تشكل', 'مصدر', 'شكل', 'تشكل', 'تشكل', 'مص. تَشَكَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَكُّلٌ-تَشَكُّلٌ [ش ك ل] (مص. تَشَكَّلَ). 1.""تَشَكُّلُ الْمَوْضُوعِ مِنْ عِدَّةِ عَنَاصِرَ"" : تَكَوُّنُهُ، تَأَلُّفُهُ. 2.""تَشَكُّلُ الآرَاءِ"": اِنْتْظَامُهَا. 3.""تَشَكُّلُ الْمَنْظَرِ"" : تَصَوُّرُهُ، تَمَثُّلُهُ. 4.""تَشَكُّلُ الفَاكِهَةِ"" : بَدْءُ نُضْجِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19027, 'تَشَكِّي', 'تشكي', 'مصدر', 'شكي', 'تشكي', 'تشك', 'مص. تَشَكَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَشَكٍّ-تَشَكٍّ، التَّشَكِّي [ش ك ي ] (مص. تَشَكَّى). 1.""شَعَرَ بِتَشَكٍّ"" : بِمَرَضٍ. 2.""هُوَ دَائِمُ التَّشَكِّي"" : دَائِمُ التَّأَلُّمِ وَالتَّوَجُّعِ وَالتَّأَوُّهِ. 3.""التَّشَكِّي مِنَ الجَارِ"" : الشَّكْوَى مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19028, 'تَشَمُّتٌ', 'تشمت', 'مصدر', 'شمت', 'تشمت', 'تشمت', 'مص. تَشَمَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَمُّتٌ-تَشَمُّتٌ [ش م ت] (مص. تَشَمَّتَ). ""وَجَدَ فِي مَطْلَبِهِ تَشَمُّتاً"" : خَيْبَةً، إِذْ لَمْ يَنَلْ مَا كَانَ يَسْعَى إِلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19029, 'تَشَمُّرٌ', 'تشمر', 'مصدر', 'شمر', 'تشمر', 'تشمر', 'مص. تَشَمَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَمُّرٌ-تَشَمُّرٌ [ش م ر] (مص. تَشَمَّرَ). 1.""لاَ تَبْدَأْ غَسْلَ الصُّحُونِ إِلاَّ بَعْدَ تَشَمُّرٍ"" : رَفْعُ أَكْمَامِ القَمِيصِ إِلىَ حُدُودِ الْمَرْفِقَيْنِ. 2.""عَلَيْكَ بِالتَّشَمُّرِ لِلْعَمَلِ"" : بِالتَّهَيُّؤِ. 3.""تَشَمُّرُ الثَّوْبِ"" : تَقَلُّصُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19030, 'تَشَمُّسٌ', 'تشمس', 'مصدر', 'شمس', 'تشمس', 'تشمس', 'مص. تَشَمَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَمُّسٌ-تَشَمُّسٌ [ش م س] (مص. تَشَمَّسَ). ""خَرَجَ لِلتَّشَمُّسِ"": التَّعَرُّض لِأَشِعَّةِ الشَّمْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19031, 'تَشَمُّمٌ', 'تشمم', 'مصدر', 'شمم', 'تشمم', 'تشم', 'مص. تَشَمَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَمُّمٌ-تَشَمُّمٌ [ش م م] (مص. تَشَمَّمَ). ""تَشَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19032, 'تَشَنُّجٌ', 'تشنج', 'مصدر', 'شنج', 'تشنج', 'تشنج', 'مص. تَشَنَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. تَشَنَّجَ). ""أَصَابَهُ تَشَنُّجٌ حَطَّمَ أَعْصَابَهُ"" : تَقَلُّصٌ، تَقَبُّضٌ يُصِيبُ الأَعْصَابَ وَيَمْنَعُهَا مِنَ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19033, 'تَشَنُّنٌ', 'تشنن', 'مصدر', 'شنن', 'تشنن', 'تشن', 'مص. تَشَنَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَنُّنٌ-تَشَنُّنٌ [ش ن ن] (مص. تَشَنَّنَ). 1.""تَشَنُّنُ الْمَاءِ"" : نُزُولُهُ فِي كَثْرَةٍ. 2. ""دَخَلَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19034, 'تَشَهُّدٌ', 'تشهد', 'مصدر', 'شهد', 'تشهد', 'تشهد', 'مص. تَشَهَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَهُّدٌ-تَشَهُّدٌ [ش هـ د] (مص. تَشَهَّدَ). ""التَّشَهُّدُ فيِ الصَّلاَةِ"": النُّطْقُ بِالشَّهَادَتَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19035, 'تَشَهِّي', 'تشهي', 'مصدر', 'شهو', 'تشهي', 'تشه', 'مص. تَشَهَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَشَهٍّ-تَشَهٍّ، التَّشَهِّي [ش هـ و ] (مص. تَشَهَّى). ""هِيَ فِي وَقْتِ التَّشَهِّي"" : وَقْتُ الرَّغْبَةِ فِي الشَّيْءِ وَالتَّعَلُّقِ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19036, 'تَشَوُّشٌ', 'تشوش', 'مصدر', 'شوش', 'تشوش', 'تشش', 'مص. تَشَوَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَوُّشٌ-تَشَوُّشٌ [ش و ش] (مص. تَشَوَّشَ). 1.""أَحْدَثَ تَشَوُّشاً مَقْصُوداً"" : اِضْطِرَاباً، فَوْضىً. 2.""أَحَسَّ بِتَشَوُّشِ أَفْكَارِهِ"" : بِالْتِبَاسٍ، بِاخْتِلاَلٍ، بِاخْتِلاَطٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19037, 'تَشَوُّفٌ', 'تشوف', 'مصدر', 'شوف', 'تشوف', 'تشف', 'مص. تَشَوَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَوُّفٌ-تَشَوُّفٌ [ش و ف] (مص. تَشَوَّفَ). 1.""تَشَوُّفُ الجِبَالِ"" : اِرْتِفَاعُهَا. 2.""تَشَوُّفُ عَلاَمَةٍ"" : ظُهُورُهَا مِنْ عُلُوٍّ. 3.""التَّشَوُّفُ مِنْ أَعْلَى ..."" : النَّظَرُ وَالإِشْرَافُ. 4.""تَشَوُّفُ النَّفْسِ لِلِقَاءِ الأَحِبَّةِ"" : التَّطَلُّعُ، الاِشْتِيَاقُ. ""التَّشَوُّفُ إِلَى رِجَالِ التَّصَوُّفِ"".(لأبي يعقوب يوسف التادلي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19038, 'تَشَوُّقٌ', 'تشوق', 'مصدر', 'شوق', 'تشوق', 'تشق', 'مص. تَشَوَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَوُّقٌ-تَشَوُّقٌ [ش و ق] (مص. تَشَوَّقَ). ""أَظْهَرَ تَشَوُّقاً لِلِقَاءِ أَحِبَّائِهِ"" : الرَّغْبَةُ القَوِيَّةُ الشَّدِيدَةُ، الشَّوْقُ، الاشْتِيَاقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19039, 'تَشَوُّهٌ', 'تشوه', 'مصدر', 'شوه', 'تشوه', 'تشه', 'مص. تَشَوَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَوُّهٌ-تَشَوُّهٌ [ش و هـ] (مص. تَشَوَّهَ). ""تَعَرَّضَ لِتَشَوُّهٍ فِي وَجْهِهِ"" : هَيْئَةُ الوَجْهِ بَعْدَمَا لَحِقَهَا تَغْيِيرٌ فِي الخِلْقَةِ مِنْ جَرَّاءِ حَرْقٍ أَوْ جُرْحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19040, 'تَشَيْطُنٌ', 'تشيطن', 'مصدر', 'شطن', 'تشيطن', 'تشطن', 'مص. تَشَيْطَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَيْطُنٌ-تَشَيْطُنٌ [ش ط ن] (مص. تَشَيْطَنَ). ""تَشَيْطُنُ الوَلَدِ"": قِيَامُهُ بِعَمَلِ الشَّيْطَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19041, 'تَشَيُّعٌ', 'تشيع', 'مصدر', 'شيع', 'تشيع', 'تشع', 'مص. تَشَيَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَيُّعٌ-تَشَيُّعٌ [ش ي ع] (مص. تَشَيَّعَ). 1.""تَشَيُّعُ الرَّجُلِ"" : صَيْرَهُ شِيعِيّاً. 2.""التَّشَيُّعُ لِلْقَبِيلَةِ"" : التَّعَصُّبُ لَهَا. 3.""التَّشَيُّعُ لآرَاءِ حِزْبِهِ"" : التَّحَزُّبُ لَهَا. 4.""تَشَيُّعُ الشِّيبِ فِي رَأْسِهِ"" : اِنْتِشَارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19042, 'تَصَابِي', 'تصابي', 'مصدر', 'صبو', 'تصابي', 'تصب', 'مص. تَصَابَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَصَابٍ-تَصَابٍ، التَّصَابِي [ص ب و] (مص. تَصَابَى).""تَصَابِي ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19043, 'تَصَاحُبٌ', 'تصاحب', 'مصدر', 'صحب', 'تصاحب', 'تصحب', 'مص. تَصَاحَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَاحُبٌ-تَصَاحُبٌ [ص ح ب] (مص. تَصَاحَبَ). ""تَصَاحُبُ الوَلَدَيْنِ"" : تَرَافُقُهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19044, 'تَصَاخُبٌ', 'تصاخب', 'مصدر', 'صخب', 'تصاخب', 'تصخب', 'مص. تَصَاخَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَاخُبٌ-تَصَاخُبٌ [ص خ ب] (مص. تَصَاخَبَ). ""تَصَاخُبُ النَّاسِ"" : تَصَايُحُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19045, 'تَصَادُفٌ', 'تصادف', 'مصدر', 'صدف', 'تصادف', 'تصدف', 'مص. تَصَادَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَادُفٌ-تَصَادُفٌ [ص د ف] (مص. تَصَادَفَ). ""تَصَادُفُ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19046, 'تَصَادُقٌ', 'تصادق', 'مصدر', 'صدق', 'تصادق', 'تصدق', 'مص. تَصَادَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَادُقٌ-تَصَادُقٌ [ص د ق] (مص. تَصَادَقَ). ""دَامَ تَصَادُقُهُمَا زَمَناً طَوِيلاً"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19047, 'تَصَادُمٌ', 'تصادم', 'مصدر', 'صدم', 'تصادم', 'تصدم', 'مص. تَصَادَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَادُمٌ-تَصَادُمٌ [ص د م] (مص. تَصَادَمَ). 1.""تَصَادُمُ سَيَّارَتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19048, 'تَصَارُخٌ', 'تصارخ', 'مصدر', 'صرخ', 'تصارخ', 'تصرخ', 'مص. تَصَارَخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَارُخٌ-تَصَارُخٌ [ص ر خ] (مص. تَصَارَخَ). ""تَصَارُخُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19049, 'تَصَارُعٌ', 'تصارع', 'مصدر', 'صرع', 'تصارع', 'تصرع', 'مص. تَصَارَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَارُعٌ-تَصَارُعٌ [ص ر ع] (مص. تَصَارَعَ). ""يَنْبَغِي أَنْ يَضَعَا حَدّاً لِتَصَارُعِهِمَا"" : لِتَنَاحُرِهِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19050, 'تَصَاعُبٌ', 'تصاعب', 'مصدر', 'صعب', 'تصاعب', 'تصعب', 'مص. تَصَاعَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَاعُبٌ-تَصَاعُبٌ [ص ع ب] (مص. تَصَاعَبَ). ""التَّصَاعُبُ فِي الأَمْرِ"" : التَّشَدُّدُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19051, 'تَصَاعُدٌ', 'تصاعد', 'مصدر', 'صعد', 'تصاعد', 'تصعد', 'مص. تَصَاعَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَاعُدٌ-تَصَاعُدٌ [ص ع د] (مص. تَصَاعَدَ). ""الأَسْعَارُ فِي تَصَاعُدٍ مُسْتَمِرٍّ"" : فِي غَلاَءٍ، فِي ارْتِفَاعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19052, 'تَصَاغُرٌ', 'تصاغر', 'مصدر', 'صغر', 'تصاغر', 'تصغر', 'مص. تَصَاغَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَاغُرٌ-تَصَاغُرٌ [ص غ ر] (مص. تَصَاغَرَ). 1.""تَصَاغُرُ الرَّجُلِ"" : سُلُوكُهُ مَسْلَكَ الصِّغَارِ. 2.""أَظْهَرَ تَصَاغُراً"" : تَوَاضُعاً، أَيِ النَّظَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19053, 'تَصَافٌّ', 'تصاف', 'مصدر', 'صفف', 'تصاف', 'تصف', 'مص. تَصَافَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَافٌّ-تَصَافٌّ [ص ف ف] (مص. تَصَافَّ). 1.""تَصَافُّ الجنُودِ"" : وُقُوفُهُمْ فْي صُفُوفٍ مُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19054, 'تَصَافُحٌ', 'تصافح', 'مصدر', 'صفح', 'تصافح', 'تصفح', 'مص. تَصَافَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَافُحٌ-تَصَافُحٌ [ص ف ح] (مص. تَصَافَحَ). ""بَعْدَ التَّصَافُحِ تَبَادَلَ الْمُتَخَاصِمَانِ كَلِمَاتِ التَّرْحِيبِ"" : بَعْدَ الْمُصافَحَةِ، أَيْ تَحِيَّةُ اليَدِ بِاليَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19055, 'تَصَافُعٌ', 'تصافع', 'مصدر', 'صفع', 'تصافع', 'تصفع', 'مص. تَصَافَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَافُعٌ-تَصَافُعٌ [ص ف ع] (مص. تَصَافَعَ). ""بَدَأَ التَّصَافُعُ بَيْنَهُمَا فَجْأَةً"" : المصافَعَةُ، أَيْ تَبَادُلُ الصَّفْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19056, 'تَصَافِي', 'تصافي', 'مصدر', 'صفو', 'تصافي', 'تصف', 'مص. تَصَافَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَصَافٍ-تَصَافٍ، التَّصَافِي [ص ف و] (مص. تَصَافَى). ""يَحْكُمُ عَلاَقَتَهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19057, 'تَصَالُحٌ', 'تصالح', 'مصدر', 'صلح', 'تصالح', 'تصلح', 'مص. تَصَالَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَالُحٌ-تَصَالُحٌ [ص ل ح] (مص. تَصَالَحَ). ""اِتَّفَقُوا عَلَى التَّصَالُحِ بَعْدَ تَخَاصُمٍ"" : عَلَى التَّرَاضِي وَإِقَامَةِ الصُّلْحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19058, 'تَصَاهُرٌ', 'تصاهر', 'مصدر', 'صهر', 'تصاهر', 'تصهر', 'مص. تَصَاهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَاهُرٌ-تَصَاهُرٌ [ص هـ ر] (مص. تَصَاهَرَ). ""بَيْنَهُمَا عَلاَقَةُ تَصَاهُرٍ"" : مصاهَرَةٌ، أَيْ تَزْوِيجُ أَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19059, 'تَصَاهُلٌ', 'تصاهل', 'مصدر', 'صهل', 'تصاهل', 'تصهل', 'مص. تَصَاهَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَاهُلٌ-تَصَاهُلٌ [ص هـ ل] (مص. تَصَاهَلَ). ""تَصَاهُلُ الخَيْلِ"": تَرَدُّدُ أَصْوَاتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19060, 'تَصَاوُلٌ', 'تصاول', 'مصدر', 'صول', 'تصاول', 'تصل', 'مص. تَصَاوَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَاوُلٌ-تَصَاوُلٌ [ص و ل] (مص. تَصَاوَلَ). ""تَصَاوُلُ الخَصْمَيْنِ"" : تَوَاثُبُهُمَا وَانْقِضَاضُ أَحَدِهِمَا عَلَى الآخَرِ لِقَهْرِهِ وَالغَلَبَةِ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19061, 'تَصَايُحٌ', 'تصايح', 'مصدر', 'صيح', 'تصايح', 'تصح', 'مص. تَصَايَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَايُحٌ-تَصَايُحٌ [ص ي ح] (مص. تَصَايَحَ). ""سَمِعَ تَصَايُحاً مِنْ بَعِيدٍ"" : تَبَادُلُ الصِّيَاحِ بَيْنَ النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19062, 'تَصَبُّبٌ', 'تصبب', 'مصدر', 'صبب', 'تصبب', 'تصب', 'مص. تَصَبَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَبُّبٌ-تَصَبُّبٌ [ص ب ب] (مص. تَصَبَّبَ). 1.""تَصَبُّبُ الْمَاءِ"": صَبُّهُ شَيْئًا فَش"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19063, 'تَصَبُّحٌ', 'تصبح', 'مصدر', 'صبح', 'تصبح', 'تصبح', 'مص. تَصَبَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَبُّحٌ-تَصَبُّحٌ [ص ب ح] (مص. تَصَبَّحَ). 1.""رَغِبَ فِي التَّصَبُّحِ قَبْلَ خُرُوجِهِ مِنَ البَيْتِ"" : مَا يَتِمُّ تَنَاوُلُهُ وَالتَّعَلُّلُ بِهِ صَبَاحاً . 2.""تَجَنَّبَ تَصَبُّحَهُ"" : تَجَنَّبَ لُقْيَاهُ صَبَاحاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19064, 'تَصَبُّرٌ', 'تصبر', 'مصدر', 'صبر', 'تصبر', 'تصبر', 'مص. تَصَبَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَبُّرٌ-تَصَبُّرٌ [ص ب ر] (مص. تَصَبَّرَ). 1.""اِسْتَعَانَ بِالتَّصَبُّرِ رَغْماً عَنْهُ"" : تَكَلُّفُ الصَّبْرِ. 2.""التَّصَبُّرُ عَلَى الْمَكْرُوهِ"" : الصَّبْرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19065, 'تَصَبُّنٌ', 'تصبن', 'مصدر', 'صبن', 'تصبن', 'تصبن', 'مص. تَصَبَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَبُّنٌ-تَصَبُّنٌ [ص ب ن] (مص. تَصَبَّنَ). : تَحَوُّلُ خَلِيطِ الأَمْلاَحِ وَالحَوَامِضِ وَالزُّيُوتِ عَلَى أَثَرِ تَفَاعُلِهَا لِيَتَوَلَّدَ مِنْهَا الصَّابُونُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19066, 'تَصَحُّحٌ', 'تصحح', 'مصدر', 'صحح', 'تصحح', 'تصح', 'مص. تَصَحَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَحُّحٌ-تَصَحُّحٌ [ص ح ح] (مص. تَصَحَّحَ). 1.""سَاهَمَ فِي تَصَحُّحِ الأُمُورِ"": فِي اسْتِقَامَتِهَا. 2.""طَالَبَ بِتَصَحُّحِ الحِسَابِ"": بِمُرَاجَعَتِهِ وَتَصْحِيحِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19067, 'تَصَدُّعٌ', 'تصدع', 'مصدر', 'صدع', 'تصدع', 'تصدع', 'مص. تَصَدَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَدُّعٌ-تَصَدُّعٌ [ص د ع] (مص. تَصَدَّعَ). 1.""أَصَابَ الحَائِطَ تَصَدُّعٌ"" : تَشَقُّقٌ. 2.""تَصَدُّعُ الْجَمَاعَةِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19068, 'تَصَدُّقٌ', 'تصدق', 'مصدر', 'صدق', 'تصدق', 'تصدق', 'مص. تَصَدَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَدُّقٌ-تَصَدُّقٌ [ص د ق] (مص. تَصَدَّقَ). ""التَّصَدُّقُ عَلَى الفُقَرَاءِ"" : مَنْحُهُمُ الصَّدَقَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19069, 'تَصَرُّفٌ', 'تصرف', 'مصدر', 'صرف', 'تصرف', 'تصرف', 'مص. تَصَرَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَرُّفٌ-تَصَرُّفٌ [ص ر ف] (مص. تَصَرَّفَ). 1.""مَا هَذَا التَّصَرُّفُ الْمُشِينُ"" : مَا هَذَا السُّلُوكُ. 2.""يُحْسِنُ التَّصَرُّفَ فِي أَعْمَالِهِ"" : الاِخْتِيَارَ. ""يَتَصَرَّفُ عَلَى كُلِّ وَجْهٍ تَصَرُّفاً مَنْطِق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19070, 'تَصرِيفٌ', 'تصريف', 'مصدر', 'صرف', 'تصريف', 'تصرف', 'مص. صَرَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19071, 'تصاريف', 'تصاريف', 'مصدر', '', 'تصاريف', 'تصرف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19072, 'تَصَرُّمٌ', 'تصرم', 'مصدر', 'صرم', 'تصرم', 'تصرم', 'مص. تَصَرَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَرُّمٌ-تَصَرُّمٌ [ص ر م] (مص. تَصَرَّمَ). ""تَصَرُّمُ اللَّيْلِ"" : اِنْقِضَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19073, 'تَصَعُّبٌ', 'تصعب', 'مصدر', 'صعب', 'تصعب', 'تصعب', 'مص. تَصَعَّبَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَعُّبٌ-تَصَعُّبٌ [ص ع ب] (مص. تَصَعَّبَ) ""تَصَعُّبُ الأُمُورِ"": تَعَقُّدُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19074, 'تَصَعْلُكٌ', 'تصعلك', 'مصدر', 'صعل', 'تصعلك', 'تصعلك', 'مص. تَصَعْلَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَعْلُكٌ-تَصَعْلُكٌ [ص ع ل] (مص. تَصَعْلَكَ). 1.""تَصَعْلُكُ الوَلَدِ"" : تَشَرُّدُهُ. 2.""تَصَعْلُكُ الرَّجُلِ"" : اِفْتِقَارُهُ. 3.""تَصَعْلُكُ الإِبِلِ"" : فُقَدَانُهَا لِأَوْبَارِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19075, 'تَصَفُّحٌ', 'تصفح', 'مصدر', 'صفح', 'تصفح', 'تصفح', 'مص. تَصَفَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَفُّحٌ-تَصَفُّحٌ [ص ف ح] (مص. تَصَفَّحَ). 1.""تَصَفُّحُ الكِتَابِ"" : تَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19076, 'تَصَلُّبٌ', 'تصلب', 'مصدر', 'صلب', 'تصلب', 'تصلب', 'مص. تَصَلَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَلُّبٌ-تَصَلُّبٌ [ص ل ب] (مص. تَصَلَّبَ). 1.""التَّصَلُّبُ فِي الرَّأْيِ"" : التَّشَدُّدُ، التَّشَبُّثُ. ""التَّسَاهُلُ خَيْرٌ مِنَ التَّصَلُّبِ"". 2.""أُصِيبَ بِتَصَلُّبٍ فِي شَرَايِينِهِ"" : بِتَقَلُّصٍ، بِانْقِبَاضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19077, 'تَصَنُّعٌ', 'تصنع', 'مصدر', 'صنع', 'تصنع', 'تصنع', 'مص. تَصَنَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَنُّعٌ-تَصَنُّعٌ [ص ن ع] (مص. تَصَنَّعَ). 1.""أَظْهَرَ تَصَنُّعاً"" : تَكَلَّفَ ما لَيْسَ بِهِ. 2.""يَكْتُبُ بِلاَ تَصَنُّعٍ"" : بِلاَ تَكَلُّفٍ وَلاَ تَزْيِينٍ أَوْ تَزْوِيقٍ. ""تَبَادَلُوا نَظَرَاتٍ كَئِيبَةً عَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19078, 'تَصَنُّفٌ', 'تصنف', 'مصدر', 'صنف', 'تصنف', 'تصنف', 'مص. تَصَنَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَنُّفٌ-تَصَنُّفٌ [ص ن ف] (مص. تَصَنَّفَ). 1.""تَصَنُّفُ الشَّجَرِ وَ النَّبَاتِ"" : ظُهُورُ أَوْرَاقِهِ. 2.""تَصَنُّفُ الْمَوَادِّ "": صَيْرُهَا أَصْنَافاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19079, 'تَصَوُّرٌ', 'تصور', 'مصدر', 'صور', 'تصور', 'تصر', 'مص. تَصَوَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. تَصَوَّرَ). 1.""تَكَوَّنَ لَدَيْهِ تَصَوُّرٌ عَنْ خُطَّةِ الْمَوْضُوعِ"" : صَارَتْ عِنْدَهُ صُورَةٌ عَنْهُ. 2.""كَانَتْ كُلُّ تَصَوُّرَاتِهِ خَاطِئَةً"" : مَفَاهِيمُهُ، أَفْكَارُهُ، آرَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19080, 'تَصَوُّفٌ', 'تصوف', 'مصدر', 'صوف', 'تصوف', 'تصف', 'مص. تَصَوَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَوُّفٌ-تَصَوُّفٌ [ص و ف] (مص. تَصَوَّفَ). ""دَخَلَ الشَّيْخُ مَرْحَلَةَ التَّصَوُّفِ"" : التَّعَبُّدِ وَالتَّزَهُّدِ وَالابْتِعَادِ عَنْ مُخَالَطَةِ النَّاسِ. ""التَّصَوُّفُ يَكُونُ بِالْمُجَاهَدَةِ وَقَطْعِ الشَّهْوَةِ"" (الغزالي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19081, 'تَصَيُّدٌ', 'تصيد', 'مصدر', 'صيد', 'تصيد', 'تصد', 'مص. تَصَيَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَيُّدٌ-تَصَيُّدٌ [ص ي د] (مص. تَصَيَّدَ). 1.""تَصَيُّدُ الصَّيَّادِ"": طَلَبُهُ الصَّيْدَ. 2.""تَصَيُّدُ مُنَاسَبَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19082, 'تَصَيُّفٌ', 'تصيف', 'مصدر', 'صيف', 'تصيف', 'تصف', 'مص. تَصَيَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصَيُّفٌ-تَصَيُّفٌ [ص ي ف] (مص. تَصَيَّفَ). ""التَّصَيُّفُ بِالجَبَلِ"" : الاصْطِيافُ، الإِقَامَةُ بِهِ صَيْفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19083, 'تَضَاؤُلٌ', 'تضاؤل', 'مصدر', 'ضأل', 'تضاءل', 'تضل', 'مص. تَضَاءَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَاؤُلٌ-تَضَاؤُلٌ [ض أ ل] (مص. تَضَاءَلَ). 1.""تَضَاؤُلُ حَجْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19084, 'تَضَادٌّ', 'تضاد', 'مصدر', 'ضدد', 'تضاد', 'تضد', 'مص. تَضَادَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَادٌّ-تَضَادٌّ [ض د د] (مص. تَضَادَّ). ""تَضَادُّ الأَوْلاَدِ"" : تَعَاكُسُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19085, 'تَضَارُبٌ', 'تضارب', 'مصدر', 'ضرب', 'تضارب', 'تضرب', 'مص. تَضَارَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَارُبٌ-تَضَارُبٌ [ض ر ب] (مص. تَضَارَبَ). 1.""تَحَوَّلَ خِصَامُهُمَا إِلىَ تَضَارُبٍ"" : ضَرْبُ أَحَدِهِمَا الآخَرَ. 2.""تَضَارُبُ الآرَاءِ"" : اِخْتِلاَفُهَا، تَبَايُنُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19086, 'تَضَاعُفٌ', 'تضاعف', 'مصدر', 'ضعف', 'تضاعف', 'تضعف', 'مص. تَضَاعَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَاعُفٌ-تَضَاعُفٌ [ض ع ف] (مص. تَضَاعَفَ). 1.""الْمَاشِيَةُ فِي تَضَاعُفٍ مُسْتَمِرٍّ"" : فِي اِزْدِيَادٍ، أَضْعَافَ مَا كَانَتْ عَلَيْهِ. 2. ""تَضَاعُفُ الجُهُودِ"" : تَضَافُرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19087, 'تَضَاغُنٌ', 'تضاغن', 'مصدر', 'ضغن', 'تضاغن', 'تضغن', 'مص. تَضَاغَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَاغُنٌ-تَضَاغُنٌ [ض غ ن] (مص. تَضَاغَنَ). ""وَصَلَتْ عَلاَقَتُهُمَا إِلى حَدِّ التَّضَاغُنِ"" : الحِقْدِ الْمُتَبَادَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19088, 'تَضَافُرٌ', 'تضافر', 'مصدر', 'ضفر', 'تضافر', 'تضفر', 'مص. تَضَافَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَافُرٌ-تَضَافُرٌ [ض ف ر] (مص. تَضَافَرَ). ""يَنْبَغِي تَضَافُرُ الجُهُودِ لِتَحْقِيقِ تَقَدُّمٍ عِلْمِيٍّ فِي البِلاَدِ"" : تَعَاوُنُ كُلِّ الجُهُودِ، اِشْتِغَالُهَا فِي تَعَاوُنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19089, 'تَضَامٌّ', 'تضام', 'مصدر', 'ضمم', 'تضام', 'تضم', 'مص. تَضَامَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَامٌّ-تَضَامٌّ [ض م م] (مص. تَضَامَّ). ""التَّضَامُّ خَيْرٌ مِنَ التَّفَرُّقِ"" : التَّجَمُّعُ وَاجْتِمَاعُ الشَّمْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19090, 'تَضَامُنٌ', 'تضامن', 'مصدر', 'ضمن', 'تضامن', 'تضمن', 'مص. تَضَامَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَامُنٌ-تَضَامُنٌ [ض م ن] (مص. تَضَامَنَ). ""أَظْهَرَ الشَّعْبُ تَضَامُناً رَائِعاً"" : اِتِّحَاداً وَتَعَاوُناً وَاتِّفَاقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19091, 'تَضَايُقٌ', 'تضايق', 'مصدر', 'ضيق', 'تضايق', 'تضق', 'مص. تَضَايَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَايُقٌ-تَضَايُقٌ [ض ي ق] (مص. تَضَايَقَ). 1.""تضَايُقُ الْمَكَانِ بِالنَّاسِ"" : ضَيْقُهُ وَعَدَمُ اتِّسَاعِهِ. 2.""شَعَرَ بِالتَّضَايُقِ مِنْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19092, 'تَضَخُّمٌ', 'تضخم', 'مصدر', 'ضخم', 'تضخم', 'تضخم', 'مص. تَضَخَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَخُّمٌ-تَضَخُّمٌ [ض خ م] (مص. تَضَخَّمَ). 1.""شَعَرَ بِتَضَخُّمٍ فِي حَنْجَرَتِهِ"" : بِتَوَرُّمٍ، بِانْتِفَاخٍ. 2.""العَصْرُ الحَالِيُّ عَصْرُ التَّضَخُّمِ الْمَالِيِّ"" : الاِزْدِيَادُ الْمُفْرِطُ فِي الأَوْرَاقِ النَّقْدِيَّةِ عَلَى حَاجَةِ الْمُعَامَلاَتِ مِمَّا يُؤَدِّي حَتْماً إِلَى ارْتِفَاعِ الأَسْعَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19093, 'تَضَرُّجٌ', 'تضرج', 'مصدر', 'ضرج', 'تضرج', 'تضرج', 'مص. تَضَرَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَرُّجٌ-تَضَرُّجٌ [ض ر ج] (مص. تَضَرَّجَ). 1.""التَّضَرُّجُ بِالدَّمِ"": التَّلَطُّخُ بِهِ. 2.""تَضَرُّجُ الخَدِّ"" : اِحْمِرَارُهُ. 3.""تضَرُّجُ الزَّهْرِ"" : تَفَتُّحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19094, 'تَضَرُّرٌ', 'تضرر', 'مصدر', 'ضرر', 'تضرر', 'تضر', 'مص. تَضَرَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَرُّرٌ-تَضَرُّرٌ [ض ر ر] (مص. تَضَرَّرَ). ""لَمْ يَلْحَقْهُ أَدْنَى تَضَرُّرٍ"" : أَدْنَى أَذىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19095, 'تَضَرُّعٌ', 'تضرع', 'مصدر', 'ضرع', 'تضرع', 'تضرع', 'مص. تَضَرَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَرُّعٌ-تَضَرُّعٌ [ض ر ع] (مص. تَضَرَّعَ). 1.""رَفَعَ أَكُفَّهُ إِلَى السَّمَاءِ تَضَرُّعاً"" : تَخَشُّعاً، تَعَبُّداً، اِبْتِهَالاً. 2.""لَمْ يَبْقَ أَمَامَهُ إِلاَّ التَّضَرُّعُ إِلَيْهِ"" : التَّذَلُّلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19096, 'تَضَرُّمٌ', 'تضرم', 'مصدر', 'ضرم', 'تضرم', 'تضرم', 'مص. تَضَرَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَرُّمٌ-تَضَرُّمٌ [ض ر م] (مص. تَضَرَّمَ). 1.""تَضَرُّمُ النَّارِ"" : اِشْتِعَالُهَا، اِتِّقَادُهَا. 2.""أَقْلَقَ أَهْلَهُ بِتَضَرُّمِهِ"": بِاحْتِدَادِ غَضَبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19097, 'تَضَعْضُعٌ', 'تضعضع', 'مصدر', 'ضعضع', 'تضعضع', 'تضعضع', 'مص. تَضَعْضَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَعْضُعٌ-تَضَعْضُعٌ [ض ع ض ع] (مص. تَضَعْضَعَ). 1.""وَجَدَ أَحْوَالَهُ فِي تَضَعْضُعٍ"" : فِي ضُعْفٍ وَوَهَنٍ. 2.""تَضَعْضُعُ التِّجَارَةِ"" : قِلَّةُ رَوَاجِهَا، اِنْخِفَاضُهُ. 3.""تَرَكَتْهُ مَصائِبُ الدَّهْرِ فِي تَضَعْضُعٍ"" : فِي مَذَلَّةٍ، فِي إِذْلاَلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19098, 'تَضَلُّعٌ', 'تضلع', 'مصدر', 'ضلع', 'تضلع', 'تضلع', 'مص. تَضَلَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَلُّعٌ-تَضَلُّعٌ [ض ل ع] (مص. تَضَلَّعَ). 1.""التَّضَلُّعُ مِنَ العُلُومِ"" : التَّشَبُّعُ بِهَا وَالتَّعَمُّقُ. 2.""لَمْ يَتَوَقَّفْ عَنِ الأَكْلِ إِلاَّ بَعْدَ تَضَلُّعٍ"" : بَعْدَ امْتِلاَءٍ وَتَشَبُّعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19099, 'تَضَمُّخٌ', 'تضمخ', 'مصدر', 'ضمخ', 'تضمخ', 'تضمخ', 'مص. تَضَمَّخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَمُّخٌ-تَضَمُّخٌ [ض م خ] (مص. تَضَمَّخَ). ""التَّضَمُّخُ بِالطِّيبِ"": التَّلَطُّخُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19100, 'تَضَمُّدٌ', 'تضمد', 'مصدر', 'ضمد', 'تضمد', 'تضمد', 'مص. تَضَمَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَمُّدٌ-تَضَمُّدٌ [ض م د] (مص. تَضَمَّدَ). ""تَضَمُّدُ الجُرْحِ"" : شَدُّهُ بِضِمَادَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19101, 'تَضَمُّنٌ', 'تضمن', 'مصدر', 'ضمن', 'تضمن', 'تضمن', 'مص. تَضَمَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَمُّنٌ-تَضَمُّنٌ [ض م ن] (مص. تَضَمَّنَ). ""وَجَدَ فِي مَوْضُوعِهِ تَضَمُّناً لأَفْكَارِ غَيْرِهِ"" : اِشْتِمَالُهُ، اِحْتِوَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19102, 'تَضَوُّرٌ', 'تضور', 'مصدر', 'ضور', 'تضور', 'تضر', 'مص. تَضَوَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَوُّرٌ-تَضَوُّرٌ [ض و ر] (مص. تَضَوَّرَ). ""حَاوَلَ أَنْ يُخْفِيَ تَضَوُّرَهُ مِنَ الجُوعِ"" : وَطْأَتَهُ، تَلَوِّيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19103, 'تَضَوُّعٌ', 'تضوع', 'مصدر', 'ضوع', 'تضوع', 'تضع', 'مص. تَضَوَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَوُّعٌ-تَضَوُّعٌ [ض و ع] (مص. تَضَوَّعَ). ""تَضَوُّعُ رَائِحَةِ المِسْكِ"" : فَوَحَانُ رَائِحَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19104, 'تَضَيُّقٌ', 'تضيق', 'مصدر', 'ضيق', 'تضيق', 'تضق', 'مص. تَضَيَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضَيُّقٌ-تَضَيُّقٌ [ض ي ق] (مص. تَضَيَّقَ). ""تَضَيُّقُ البَيْتِ"" : صَيْرُهُ أَوْ كَوْنُهُ ضَيِّقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19105, 'تَطَابُقٌ', 'تطابق', 'مصدر', 'طبق', 'تطابق', 'تطبق', 'مص. تَطَابَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَابُقٌ-تَطَابُقٌ [ط ب ق] (مص. تَطَابَقَ). 1.""تَطَابُقُ الصُّورَتَيْنِ"" : تَمَاثُلُهُمَا، تَسَاوِيهِمَا. 2. ""لاَحَظَ تَطَابُقاً فِي آرَائِهِمْ"" : تَوَافُقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19106, 'تَطَارُحٌ', 'تطارح', 'مصدر', 'طرح', 'تطارح', 'تطرح', 'مص. تَطَارَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَارُحٌ-تَطَارُحٌ [ط ر ح] (مص. تَطَارَحَ). ""جَاءُوا لِتَطَار"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19107, 'تَطَارُدٌ', 'تطارد', 'مصدر', 'طرد', 'تطارد', 'تطرد', 'مص. تَطَارَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَارُدٌ-تَطَارُدٌ [ط ر د] (مص. تَطَارَدَ). ""تَطَارُدُ الْمُتَقَاتِلِينَ"" : مُطَارَدَةُ وَمُهَاجَمَةُ بَعْضِهِمْ بَعْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19108, 'تَطَأْطُؤٌ', 'تطأطؤ', 'مصدر', 'طأطأ', 'تطءطء', 'تطط', 'مص. تَطَأْطَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَطَأْطُؤٌ-تَطَأْطُؤٌ [ط أ ط أ] (مص. تَطَأْطَأَ). 1.""تَطَأْطُؤُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19109, 'تَطَاعُنٌ', 'تطاعن', 'مصدر', 'طعن', 'تطاعن', 'تطعن', 'مص. تَطَاعَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَاعُنٌ-تَطَاعُنٌ [ط ع ن] (مص. تَطَاعَنَ). ""تَطَاعُنُ الْمُتَحَارِبِينَ"": طَعْنُ بَعْضِهِمْ بَعْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19110, 'تَطَاوُلٌ', 'تطاول', 'مصدر', 'طول', 'تطاول', 'تطل', 'مص. تَطَاوَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَاوُلٌ-تَطَاوُلٌ [ط و ل] (مص. تَطَاوَلَ). 1.""عُمْرُهُ فِي تَطَاوُلٍ"" : فيِ طُولٍ وَاسْتِمْرَارٍ. 2.""وَجَدَ فِي سُلُوكِهِ تَطَاوُلاً عَلَى حُقُوقِهِ"" : اِعْتِدَاءً عَلَيْهَا. 3.""أَظْهَرَ تَطَاوُلاً"" : تَكَبُّراً، تَرَفُّعاً. 4.""التَّطَاوُلُ بِالعَطَاءِ"" : التَّفَضُّلُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19111, 'تَطَايُرٌ', 'تطاير', 'مصدر', 'طير', 'تطاير', 'تطر', 'مص. تَطَايَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَايُرٌ-تَطَايُرٌ [ط ي ر] (مص. تَطَايَرَ). """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19112, 'تَطَبُّبٌ', 'تطبب', 'مصدر', 'طبب', 'تطبب', 'تطب', 'مص. تَطَبَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَبُّبٌ-تَطَبُّبٌ [ط ب ب] (مص. تَطَبَّبَ). 1.""أَرَادَ التَّطَبُّبَ "": تَعَاطِي مِهْنَةِ الطِّبِّ بِلاَ عِلْمٍ بِهَا. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19113, 'تَطَبُّعٌ', 'تطبع', 'مصدر', 'طبع', 'تطبع', 'تطبع', 'مص. تَطَبَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَبُّعٌ-تَطَبُّعٌ [ط ب ع] (مص. تَطَبَّعَ). ""يَغْلِبُ الطَّبْعُ التَّطَبُّعَ"". (مثل) : مَا "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19114, 'تَطَرُّبٌ', 'تطرب', 'مصدر', 'طرب', 'تطرب', 'تطرب', 'مص. تَطَرَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَرُّبٌ-تَطَرُّبٌ [ط ر ب] (مص. تَطَرَّبَ). 1.""كَانَ فِي حَالَةِ تَطَرّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19115, 'تَطَرُّزٌ', 'تطرز', 'مصدر', 'طرز', 'تطرز', 'تطرز', 'مص. تَطَرَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَرُّزٌ-تَطَرُّزٌ [ط ر ز] (مص. تَطَرَّزَ). ""تَطَرُّزُ الثَّوْبِ"" : صَي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19116, 'تَطَرُّفٌ', 'تطرف', 'مصدر', 'طرف', 'تطرف', 'تطرف', 'مص. تَطَرَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَطَرُّفٌ-تَطَرُّفٌ [ط ر ف] (مص. تَطَرَّفَ). 1.""التَّطَرُّفُ إِلَى الشِّمَالِ"" : الاِبْتِعَادُ. 2.""تَطَرُّفُ الشَّمْسِ"" : دُنُوُّهَا إِلىَ الغُرُوبِ. 3.""مَا هَذَا التَّطَرُّفُ فيِ الْمَوَاقِفِ"" : الْمُبَالَغَةُ وَالإِفْرَاطُ وَتَجَاوُزُ حَدِّ الاعْتِدَالِ. ""تَطَرَّفَ تَطَرُّفاً لاَ حَدَّ لَهُ عِنْدَمَا كَانَ يُدَافِعُ عَنْ آرَائِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19117, 'تَطَرُّقٌ', 'تطرق', 'مصدر', 'طرق', 'تطرق', 'تطرق', 'مص. تَطَرَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَرُّقٌ-تَطَرُّقٌ [ط ر ق] (مص. تَطَرَّقَ). 1.""التَّطَرُّقُ إِلىَ الْمَوْضُوعِ مُبَاشَرَةً"" : تَنَاوُلُهُ. 2. ""حَاوَلَ التَّطَرُّقَ إِلَى جَوَانِبَ أُخْرَى مِنَ الْمَسْأَلَةِ"" : التَّصَدِّي لَهَا. 3.""تَطَرُّقُ الشَّكِّ إِلَى نَفْسِهِ"": مُسَاوَرَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19118, 'تَطَفُّلٌ', 'تطفل', 'مصدر', 'طفل', 'تطفل', 'تطفل', 'مص. تَطَفَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَفُّلٌ-تَطَفُّلٌ [ط ف ل] (مص. تَطَفَّلَ). 1.""لَمْ يَسْتَطِعْ كَبْحَ تَطَفُّلِهِ"" : دُخُولُهُ إِلىَ وَلِيمَةٍ أَوْ حَفْلَةٍ دُونَ دَعْوِةٍ. 2. ""لاَحَظَ فِي تَصَرُّفِ الشَّيْخِ تَطَفُّلاً"" : تَخَلُّقَهُ بِأَخْلاَقِ الأَطْفَالِ. 3.""كَانَ حَدِيثُهُ عِبَارَةً عَنْ تَطَفُّلٍ"" : التَّدَخُّلُ فِيمَا لاَ يَعْنِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19119, 'تَظَاهُرٌ', 'تظاهر', 'مصدر', 'ظهر', 'تظاهر', 'تظهر', 'مص. تَظَاهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَظَاهُرٌ-تَظَاهُرٌ [ظ هـ ر] (مص. تَظَاهَرَ). 1.""التَّظَاهُرُ بِالحُبِّ"": إِظْهَارُهُ. 2.""خَرَجُوا فِي تَظَاهُرٍ"" : فِي مُظَاهَرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19120, 'تَطَلُّبٌ', 'تطلب', 'مصدر', 'طلب', 'تطلب', 'تطلب', 'مص. تَطَلَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَلُّبٌ-تَطَلُّبٌ [ط ل ب] (مص. تَطَلَّبَ). 1.""تَطَلُّبُ أَمْرٍ مَّا"": الإِلْحَاحُ فِي طَلَبِهِ مَرَّاتٍ وَبِتَكَلُّفٍ. 2."" تَطَلُّبُ النَّجَاحِ يَفْرِضُ جُهْداً"" : اِقْتِضَاءُ، اِسْتِلْزَامُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19121, 'تَطَلُّعٌ', 'تطلع', 'مصدر', 'طلع', 'تطلع', 'تطلع', 'مص. تَطَلَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَطَلُّعٌ-تَطَلُّعٌ [ط ل ع] (مص. تَطَلَّعَ). 1.""التَّطَلُّعُ إلَى الخَطِيبِ"" : النَّظَرُ إِلَى طَلْعَتِهِ، الاِتِّجَاهُ بِالنَّظَرِ إِلَيْهِ. 2.""التَّطَلُّعُ إِلَى أَيَّامِ الطُّفُولَةِ"" : الصَّبْوُ، الْحُنُوُّ إِلَيْهَا. 3.""هُوَ كَثِيرُ التَّطَلُّعِ إِلَى العُلاَ"" : كَثِيرُ الطُّمُوحِ إِلَى مَا هُوَ أَعْلَى. 4.""تَطَلُّعُ عُلُومٍ جَدِيدَةٍ"" : مَعْرِفَتُهَا، عِلْمُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19122, 'تَطَهُّرٌ', 'تطهر', 'مصدر', 'طهر', 'تطهر', 'تطهر', 'مص. تَطَهَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَهُّرٌ-تَطَهُّرٌ [ط هـ ر] (مص. تَطَهَّرَ). 1.""التَّطَهُّرُ ضَرُورِيٌّ قَبْلَ أَدَاءِ الصَّلاَةِ"" : الاِغْتِسَالُ وَالتَّوَضُّؤُ. 2.""التَّطَهُّرُ مِنْ كُلِّ مَا يُدَنِّسُكَ وَيُبْعِدُكَ عَنِ الأَشْرَارِ"" : التَّنَزُّهُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19123, 'تَطَوُّرٌ', 'تطور', 'مصدر', 'طور', 'تطور', 'تطر', 'مص. تَطَوَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَوُّرٌ-تَطَوُّرٌ [ط و ر] (مص. تَطَوَّرَ). ""الوَضْعُ الاجْتِمَاعِيُّ فِي تَطَوُّرٍ مُسْتَمِرٍّ"" : فِي تَغَيُّرٍ وَتَبَدُّلٍ مِنْ مُسْتَوَىً إِلَى آخَرَ، مِنْ حَالٍ إِلَى حَالٍ، فِي تَحَوُّلٍ. ""تَطَوَّرَتِ الصِّنَاعَةُ الإِلِيكْتُرُونِيَّةُ تَطَوُّراً سَرِيعاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19124, 'تَطَوُّسٌ', 'تطوس', 'مصدر', 'طوس', 'تطوس', 'تطس', 'مص. تَطَوَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَوُّسٌ-تَطَوُّسٌ [ط و س] (مص. تَطَوَّسَ). ""تَطَوُّسُ الْمَرْأَةِ"" : تَزَيُّنُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19125, 'تَطَوُّعٌ', 'تطوع', 'مصدر', 'طوع', 'تطوع', 'تطع', 'مص. تَطَوَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَوُّعٌ-تَطَوُّعٌ [ط و ع] (مص. تَطَوَّعَ). 1.""التَّطَوُّعُ بِالْمَالِ"": التَّبَرُّعُ بِهِ، إِعْطَاؤُهُ عَنْ طَوَاعِيَةٍ وَاخْتِيَارٍ. 2.""التَّطَوُّعُ مِنْ أَجْلِ أَعْمَالٍ خَيْرِيَّةٍ"" : التَّجَنُّدُ لأَدَائِهَا عَنْ طَوَاعِيَةٍ وَاخْتِيَارٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19126, 'تَطَوُّفٌ', 'تطوف', 'مصدر', 'طوف', 'تطوف', 'تطف', 'مص. تَطَوَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَوُّفٌ-تَطَوُّفٌ [ط و ف] (مص. تَطَوَّفَ). 1.""التَّطَوُّفُ بِالكَعْبَةِ"" : الطَّوَافُ بِهَا. 2. ""التَّطَوُّفُ فِي البِلاَدِ"" : السَّيْرُ وَالجَوَلاَنُ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19127, 'تَطَيُّبٌ', 'تطيب', 'مصدر', 'طيب', 'تطيب', 'تطب', 'مص. تَطَيَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَيُّبٌ-تَطَيُّبٌ [ط ي ب] (مص. تَطَيَّبَ). ""التَّطَيُّبُ بِالعِطْرِ"": التَّعَطُّرُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19128, 'تَطَيُّرٌ', 'تطير', 'مصدر', 'طير', 'تطير', 'تطر', 'مص. تَطَيَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطَيُّرٌ-تَطَيُّرٌ [ط ي ر] (مص. تَطَيَّرَ). ""التَّطَيُّرُ مِنْ مَقْدَمِهِ"" : التَّشَاؤُمُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19129, 'تَعَازِي', 'تعازي', 'مصدر', 'عزي', 'تعازي', 'تعز', 'مص. تَعَازَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَعَازٍ-تَعَازٍ، التَّعَازِي [ع ز ي] (مص. تَعَازَى). ""تَقَبَّلَ تَعَازِيَ الْمُعَزِّينَ"" : تَعْزِيَةَ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19130, 'تَظَلُّلٌ', 'تظلل', 'مصدر', 'ظلل', 'تظلل', 'تظل', 'مص. تَظَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَظَلُّلٌ-تَظَلُّلٌ [ظ ل ل] (مص. تَظَلَّلَ). ""التَّظَلُّلُ بِالشَّجَرَةِ"" : الاحْتِمَاءُ بِظِلِّهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19131, 'تَظَلُّمٌ', 'تظلم', 'مصدر', 'ظلم', 'تظلم', 'تظلم', 'مص. تَظَلَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَظَلُّمٌ-تَظَلُّمٌ [ظ ل م] (مص. تَظَلَّمَ). 1.""التَّظَلُّمُ مِنَ الْمُعْتَدِي"": الشِّكَايَةُ مِنْ ظُلْمِهِ. 2.""تَظَلُّمُ الْمَظْلُومِ"" : اِحْتِمَالُهُ، صَبْرُهُ عَلَى الظُّلْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19132, 'تَعَادُلٌ', 'تعادل', 'مصدر', 'عدل', 'تعادل', 'تعدل', 'مص. تَعَادَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَعَادُلٌ-تَعَادُلٌ [ع د ل] (مص. تَعَادَلَ). 1.""اِنْتَهَتِ الْمُبَارَاةُ بِالتَّعَادُلِ"": بِالتَّسَاوِي، بِالتَّكَافُؤِ. ""تَعَادُلُ القُوَى"". 2.""تَعَادُلُ الكَفَّتَيْنِ"" : تَوَازُنُهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19133, 'تَعَادِي', 'تعادي', 'مصدر', 'عدي', 'تعادي', 'تعد', 'مص. تَعَادَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَعَادٍ-تَعَادٍ، التَّعَادِي [ع د ي] (مص. تَعَادَى). 1.""اِسْتَمَّرَ تَعَادِيهِمَا زَمَناً"" : مُخَاصَمَةُ بَعْضِهِمْ بَعْضاً. 2.""التَّعَادِي بِالْمَرَضِ"": نَقْلُ الْمَرَضِ مِنْ شَخْصٍ إِلَى آخَرَ. 3.""تَعَادِي أَبْطَال السِّبَاقِ"" : تبَاَرِيهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19134, 'تَعَارُضٌ', 'تعارض', 'مصدر', 'عرض', 'تعارض', 'تعرض', 'مص. تَعَارَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَارُضٌ-تَعَارُضٌ [ع ر ض] (مص. تَعَارَضَ). ""بَيْنَهُمَا تَعَارُضٌ فِي الآرَاءِ"" : تَبَايُنٌ، اِخْتِلاَفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19135, 'تَعَارُفٌ', 'تعارف', 'مصدر', 'عرف', 'تعارف', 'تعرف', 'مص. تَعَارَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَارُفٌ-تَعَارُفٌ [ع ر ف] (مص. تَعَارَفَ). 1.""حَصَلَ بَيْنَهُمَا تَعَارُفٌ"": تَعَرُّفُ أَحَدِهِمَا عَلَى الآخَرِ. 2.""نَشَرَ اسْمَهُ وَعُنْوَانَهُ بِرُكْنِ التَّعَارُفِ"" : زَاوِيَةٌ بِالجَرَائِدِ وَالْمَجَلاَّتِ تَنْشُرُ أَسْمَاءَ قُرَّائِهَا وَعَنَاوِينَهُم مِنْ أَجْلِ التَّعَرُّفِ بِأَصْدِقَاءَ جُدُدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19136, 'تَعَارُكٌ', 'تعارك', 'مصدر', 'عرك', 'تعارك', 'تعرك', 'مص. تَعَارَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَارُكٌ-تَعَارُكٌ [ع ر ك] (مص. تَعَارَكَ). ""تَجَنَّبِ التَّعَارُكَ مَعَ جَارِكَ"" : التَّطَاحُنَ، التَّضَارُبَ، التَّشَاجُرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19137, 'تَغْسِيلٌ', 'تغسيل', 'مصدر', 'عرك', 'تغسيل', 'تغسل', 'مص. تَعَارَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغْسِيلٌ-تَعَارُكٌ [ع ر ك] (مص. تَعَارَكَ). ""تَجَنَّبِ التَّعَارُكَ مَعَ جَارِكَ"" : التَّطَاحُنَ، التَّضَارُبَ، التَّشَاجُرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19138, 'تَعَازُلٌ', 'تعازل', 'مصدر', 'عزل', 'تعازل', 'تعزل', 'مص. تَعَازَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَازُلٌ-تَعَازُلٌ [ع ز ل] (مص. تَعَازَلَ). ""قَرَّرَ التَّعَازُلَ عَنِ النَّاسِ"" : الانْعِزَالَ عَنْهُمْ، التَّبَاعُدَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19139, 'تَعَاقُدٌ', 'تعاقد', 'مصدر', 'عقد', 'تعاقد', 'تعقد', 'مص. تَعَاقَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَاقُدٌ-تَعَاقُدٌ [ع ق د] (مص. تَعَاقَدَ). ""تَعَاقُدٌ مَبْنِيٌّ عَلَى تَبَادُلِ الْمَصالِحِ"" : اِتِّفَاقٌ، تَعَاهُدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19140, 'تَعَاشُرٌ', 'تعاشر', 'مصدر', 'عشر', 'تعاشر', 'تعشر', 'مص. تَعَاشَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَاشُرٌ-تَعَاشُرٌ [ع ش ر] (مص. تَعَاشَرَ). ""وَجَدَ فِي تَعَاشُرِهِمَا صَفَاءً"" : فِي تَصَاحُبِهِمَا وَاشْتِرَاكِهِمَا فِي مَعِيشَتِهِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19141, 'تَعَاضٌّ', 'تعاض', 'مصدر', 'عضد', 'تعاض', 'تعض', 'مص. تَعَاضَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَاضٌّ-تَعَاضٌّ [ع ض د] (مص. تَعَاضَّ). ""اِنْقَلَبَ شِجَارُهُمَا إِلَى تَعَاضٍّ"" : عَضُّ كُلٍّ مِنْهُمَا الآخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19142, 'تَعَاضُدٌ', 'تعاضد', 'مصدر', 'عضد', 'تعاضد', 'تعضد', 'مص. تَعَاضَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَاضُدٌ-تَعَاضُدٌ [ع ض د] (مص. تَعَاضَدَ). ""تَعَاضُدُ الجَمَاعَةِ"": تَعَاوُنُ وَتَنَاصُرُ أَفْرَادِهَا فِيمَا بَيْنَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19143, 'تَعَاطُفٌ', 'تعاطف', 'مصدر', 'عطف', 'تعاطف', 'تعطف', 'مص. تَعَاطَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَعَاطُفٌ-تَعَاطُفٌ [ع ط ف] (مص. تَعَاطَفَ). 1.""بَيْنَهُمَا تَعَاطُفٌ وَحُبٌّ وَوِئَامٌ"" : حَنَانٌ وَعَطْفٌ. 2.""التَّعَاطُفُ فِي الْمَشْيِ"" : تَحْرِيكُ الرَّأْسِ وَتَمَايُلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19144, 'تَعَاطِي', 'تعاطي', 'مصدر', 'عطي', 'تعاطي', 'تعط', 'مص. تَعَاطَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَعَاطٍ-تَعَاطٍ، التَّعَاطِي [ع ط ي] (مص. تَعَاطَى). 1.""تَعَاطِي الفُنُونِ الجَمِيلَةِ"" : الاِشْتِغَالُ بِها وَالخَوْضُ فِيهَا. 2.""تَعَاطِي مِهْنَةِ الطِّبِّ"" : مُزَاوَلَتُهَا، مُمَارَسَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19145, 'تَعَاظُلٌ', 'تعاظل', 'مصدر', 'عظل', 'تعاظل', 'تعظل', 'مص. تَعَاظَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَاظُلٌ-تَعَاظُلٌ [ع ظ ل] (مص. تَعَاظَلَ). 1.""تَعَاظُلُ الكِلاَبِ"": تَسَافُدُهَا، تَزَاوُجُهَا وَتَشَابُكُهَا. 2.""تَعَاظُلُ القَوْلِ"" : تَرَاكُبُهُ، تَدَاخُلُهُ. ""القَوْلُ فِي اللُّغَاتِ الأُخْرَى غَيْرِ العَرَبِيَّةِ أَشَدُّ تَعَاظُلاً وَتَعَسُّراً"" (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19146, 'تَعَاظُمٌ', 'تعاظم', 'مصدر', 'عظم', 'تعاظم', 'تعظم', 'مص. تَعَاظَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَاظُمٌ-تَعَاظُمٌ [ع ظ م] (مص. تَعَاظَمَ). 1.""أَظْهَرَ تَعَاظُماً"": تَكَبُّراً، تَعَالِياً. 2.""تَعَاظُمُ أَمْرِهِ"" : اِشْتِدَادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19147, 'تَعَافِي', 'تعافي', 'مصدر', 'عفو', 'تعافي', 'تعف', 'مص. تَعَافَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَعَافٍ-تَعَافٍ، التَّعَافِي [ع ف و] (مص. تَعَافَى). 1.""تَعَافِي الْمَرِيضِ"" : اِسْتِرْجَاعُ قُوَاهُ، شِفَاؤُهُ. 2.""تَعَافِي الطَّعَامِ"" : تَرْكُهُ وَالنُّفُورُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19148, 'تَعَاقُبٌ', 'تعاقب', 'مصدر', 'عقب', 'تعاقب', 'تعقب', 'مص. تَعَاقَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَاقُبٌ-تَعَاقُبٌ [ع ق ب] (مص. تَعَاقَبَ). 1.""تَعَاقُبُ الضُّيُوفِ عَلَى دَارِ الضِّيَافَةِ"" : تَنَاوُبُهُمْ. 2.""تَعَاقُبُ اللَّيْلِ وَالنَّهَارِ"": التَّوَالِي، أَيْ يَأْتِي اللَّيْلُ فَيَعْقُبُهُ النَّهَارُ وَهَكَذَا دَوَالَيْكَ. ""تَعَاقُبُ الأَحْدَاثِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19149, 'تَعَاوُنٌ', 'تعاون', 'مصدر', 'عون', 'تعاون', 'تعن', 'مص. تَعَاوَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَاوُنٌ-تَعَاوُنٌ [ع و ن] (مص. تَعَاوَنَ). ""يَجْمَعُ بَيْنَهُمُ التَّعَاوُنُ"": الْمُؤَازَر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19150, 'تَعَالُجٌ', 'تعالج', 'مصدر', 'علج', 'تعالج', 'تعلج', 'مص. تَعَالَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَالُجٌ-تَعَالُجٌ [ع ل ج] (مص. تَعَالَجَ). ""نَصَحَهُ بِالتَّعَالُجِ"" : بِتَتَبُّعِ العِلاَجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19151, 'تَعَالُمٌ', 'تعالم', 'مصدر', 'علم', 'تعالم', 'تعلم', 'مص. تَعَالَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَالُمٌ-تَعَالُمٌ [ع ل م] (مص. تَعَالَمَ). 1.""تَعَالَمُ الفَقِيهِ"": إِظْهَارُهُ العِلْمَ. ""كُلَّمَا سَأَلْتُهُ يُجِيبُ؛ إِلاَّ أَنَّهُ مَرِيضٌ بِالتَّعَالُمِ. 2.""تَأَكَّدْتُ مِنْ تَعَالُمِهِ الخَبَرَ"" : مِنْ عِلْمِهِ بِهِ وَمَعْرِفَتِهِ إِيَّاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19152, 'تَعَالِي', 'تعالي', 'مصدر', 'علو', 'تعالي', 'تعل', 'مص. تَعَالَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَعَالٍ-تَعَالٍ، التَّعَالِي [ع ل و] (مص. تَعَالَى). 1.""التَّعَالِي فَوْقَ الجَبَلِ"" : الصُّعُودُ، الارْتِفَاعُ. 2.""يُظْهِرُ التَّعَالِيَ فِي كُلِّ آنٍ"" : التَّكَبُّرَ، التَّعَاظُمَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19153, 'تَعَامُلٌ', 'تعامل', 'مصدر', 'عمل', 'تعامل', 'تعمل', 'مص. تَعَامَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَامُلٌ-تَعَامُلٌ [ع م ل] (مص. تَعَامَلَ). ""قَامَتْ عَلاَقَاتُهُمْ عَلَى أَسَاسِ تَعَامُلٍ صَادِقٍ"" : قِيَامُ عَلاَقَةِ عَمَلٍ مُتَبَادَلَةٍ بَيْنَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19154, 'تَعَامِي', 'تعامي', 'مصدر', 'عمي', 'تعامي', 'تعم', 'مص. تَعَامَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَعَامٍ-تَعَامٍ، التَّعَامِي [ع م ي] (مص. تَعَامَى). 1.""لَمْ يَكُنْ تَعَامِيهِ إِلاَّ مِزَاحًا"" : إِظْهَارُ العَمَى وَلَيْسَ بِهِ. 2.""التَّعَامِي عَنِ الحَقِيقَةِ"" : تَجَاهُلُهَا وَهُوَ يَعْلَمُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19155, 'تَعَانُدٌ', 'تعاند', 'مصدر', 'عند', 'تعاند', 'تعند', 'مص. تَعَانَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَانُدٌ-تَعَانُدٌ [ع ن د] (مص. تَعَانَدَ). ""لاَ شَيْءَ يُخَفِّفُ مِنْ تَعَانُدِهِمْ"" : مِنْ تَعَارُضِهِمْ، وَاخْتِلاَفِهِمْ وَمُعَانَدَتِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19156, 'تَعَانُقٌ', 'تعانق', 'مصدر', 'عنق', 'تعانق', 'تعنق', 'مص. تَعَانَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَانُقٌ-تَعَانُقٌ [ع ن ق] (مص. تَعَانَقَ). ""عَبَّرُوا بِتَعَانُقِهِمْ عَنِ الْمَحَبَّةِ وَالوِئَامِ"" : مُعَانَقَةُ كُلِّ وَاحِدٍ مِنْهُمْ لِلآخَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19157, 'تَعَاهُدٌ', 'تعاهد', 'مصدر', 'عهد', 'تعاهد', 'تعهد', 'مص. تَعَاهَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَاهُدٌ-تَعَاهُدٌ [ع هـ د] (مص. تَعَاهَدَ). 1.""قَرَّرُوا التَّعَاهُدَ عَلَى الْمَحَبَّةِ وَالإِخْلاَصِ"" : الْمُعَاهَدَةُ، اِلْتِزَامُ كُلِّ وَاحِدٍ مِنْهُمْ بِالْمَحَبَّةِ وَالإِخْلاَصِ لِلآخَرِ. 2. ""تَعَاهُدُ النَّبَاتِ"" : العِنَايَةُ بِهِ بِالسَّقْيِ وَالاهْتِمَامُ بِنُمُوِّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19158, 'تَعَاوُرٌ', 'تعاور', 'مصدر', 'عور', 'تعاور', 'تعر', 'مص. تَعَاوَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَاوُرٌ-تَعَاوُرٌ [ع و ر] (مص. تَعَاوَرَ). 1.""اِتَّفَقُوا عَلَى تَعَاوُرِ العَدُوِّ"" : عَلَى تَدَاوُلِهِ بَيْنَهُمْ. 2.""تَعَاوُرُ الرِّيحِ الْمَكَانَ"" : تَدَاوُلُها إِيَّاهُ بِهُبُوبِهَا عَلَيْهِ مِنْ جِهَةٍ إِلَى أُخْرَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19159, 'تَعَجُّبٌ', 'تعجب', 'مصدر', 'عجب', 'تعجب', 'تعجب', 'مص. تَعَجَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَجُّبٌ-تَعَجُّبٌ [ع ج ب] (مص. تَعَجَّبَ). 1.""شَاهَدَ الأَلْعَابَ البَهْلَوَانِيَّةَ فِي تَعَجُّبٍ"" : فِي انْبِهَارٍ، اِنْفِعَالُ النَّفْسِ أَمَامَ حَدَثٍ لَمْ يَرَهُ مِنْ قَبْلُ. 2.""مَا أَجْمَلَهُ !"" : صِيغَةُ تَعَجُّبٍ يُرَادُ بِهَا اسْتِعْظَامُ أَمْرٍ أَوِ الاسْتِغْرَابُ اسْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19160, 'تَعَايُبٌ', 'تعايب', 'مصدر', 'عيب', 'تعايب', 'تعب', 'مص. تَعَايَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَايُبٌ-تَعَايُبٌ [ع ي ب] (مص. تَعَايَبَ). ""نَهَاهُم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19161, 'تَعَايُرٌ', 'تعاير', 'مصدر', 'عير', 'تعاير', 'تعر', 'مص. تَعَايَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَايُرٌ-تَعَايُرٌ [ع ي ر] (مص. تَعَايَرَ). ""بَعْدَ التَّشَاجُرِ انْتَقَلُوا إِلَى التَّعَايُرِ"" : إِلَى تَعْيِيبِ بَعْضِهِمْ بَعْضاً وَالنَّعْتِ بِالعَارِ وَالقُبْحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19162, 'تَعَايُشٌ', 'تعايش', 'مصدر', 'عيش', 'تعايش', 'تعش', 'مص. تَعَايَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَايُشٌ-تَعَايُشٌ [ع ي ش] (مص. تَعَايَشَ). 1.""مُجْتَمَعٌ طَائِفِيٌّ يَعِيشُ أَهْلُهُ فِي تَعَايُشٍ وَوِئَامٍ"" : يَعِيشُونَ فِي تَسَاكُنٍ وَتَوَافُقٍ دَاخِلَ الْمُجْتَمَعِ عَلَى الرَّغْمِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19163, 'تَعَبٌ', 'تعب', 'مصدر', 'تعب', 'تعب', 'تعب', 'مص. تَعِبَ', '', '', 'مفرد', 'DnN', '', '', '"أَتْعَابٌ"', '', 'R', '', '', '', '', '', '', '"(مص. تَعِبَ). ""يَشْعُرُ بِالتَّعَبِ"" : بِالعَيَاءِ، بِالعَنَاءِ، بِالْمَشَقَّةِ. ""تَعَبٌ كُلُّهَا الحَيَاةُ"" (المعري) ""تَعَبٌ يَذُوبُ فِي غَمْضَةِ العَيْنِ سَاعَةَ النَّوْمِ"" (مصطفى الرافعي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19164, 'أَتْعَابٌ', 'أتعاب', 'مصدر', '', 'ءتعاب', 'تعب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19165, 'تَعَبُّدٌ', 'تعبد', 'مصدر', 'عبد', 'تعبد', 'تعبد', 'مص. تَعَبَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَبُّدٌ-تَعَبُّدٌ [ع ب د] (مص. تَعَبَّدَ). 1.""وَجَدَهُ فِي خُشُوعٍ وَتَعَبُّدٍ"" : الاِنْفِرَادُ لِلْعِبَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19166, 'تَعَبُّسٌ', 'تعبس', 'مصدر', 'عبس', 'تعبس', 'تعبس', 'مص. تَعَبَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَبُّسٌ-تَعَبُّسٌ [ع ب س] (مص. تَعَبَّسَ). "" تَعَبُّسُ الوَجْهِ"" : تَجَهُّمُهُ، تَقَطُّبُهُ، عُبُوسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19167, 'تَعْتَعَةٌ', 'تعتعة', 'مصدر', 'تعتع', 'تعتعة', 'تعتعة', 'مص. تَعْتَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْتَعَةٌ-تَعْتَعَةٌ [ت ع ت ع] (مص. تَعْتَعَ). ""بِهِ تَعْتَعَةٌ"" : العِيُّ، التَّرَدُّدُ فِي الكَلاَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19168, 'تَعَثُّرٌ', 'تعثر', 'مصدر', 'عثر', 'تعثر', 'تعثر', 'مص. تَعَثَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَثُّرٌ-تَعَثُّرٌ [ع ث ر] (مص. تَعَثَّرَ). 1. ""لَمْ تَسْتَطِعْ أَنْ تَنْهَضَ بَعْدَ تَعَثُّرِهَا بِأَذْيَالِ فُسْتَانِهَا"" : بَعْدَ تَعَلُّقِ أَحَدِ رِجْلَيْهَا. 2.""التَّعَثُّرُ بِالحَجَرِ"" : الاِصْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19169, 'تَعَزُّزٌ', 'تعزز', 'مصدر', 'عزز', 'تعزز', 'تعز', 'مص. تَعَزَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَزُّزٌ-تَعَزُّزٌ [ع ز ز] (مص. تَعَزَّزَ). 1.""مَكَانَتُهُ فِي تَعَزُّزٍ"" : فِي تَقَوٍّ، فِي تَشَرُّفٍ. ""كَانَ مِنَ الوَاجِبِ بِالتَّعَزُّزِ أَلاَّ يُجِيبُوهُ لِمَا دَعَا إِلَيْهِ"" (التوحيدي). 2.""تَعَزُّزُهُ بَيْنَ أَصْحَابِهِ"" : صَيْرُهُ عَزِيزاً. 3.""التَّعَزُّزُ بِعِلْمِهِ"" : الاِعْتِزَازُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19170, 'تَعَجْرُفٌ', 'تعجرف', 'مصدر', 'عجر', 'تعجرف', 'تعجرف', 'مص. تَعَجْرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَجْرُفٌ-تَعَجْرُفٌ [ع ج ر] (مص. تَعَجْرَفَ). ""مَا هَذَا التَّعَجْرُفُ يَا تُرَى !"" : الأَنَانِيَّةُ، التَّكَبُّرُ، التَّعَاظُمُ، التَّعَظُّمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19171, 'تَعَدُّدٌ', 'تعدد', 'مصدر', 'عدد', 'تعدد', 'تعد', 'مص. تَعَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَدُّدٌ-تَعَدُّدٌ [ع د د] (مص. تَعَدَّدَ). 1.""فِي هَذِهِ اللَّوْحَةِ تَعَدُّدُ الأَلْوَانِ"" : تَنَوُّعُهَا. ""تَعَدُّدُ الأَهْدَافِ وَالغَايَاتِ"". 2.""تَعَدُّدُ الزَّوْجَاتِ"" : التَّزَوُّجُ بِأَكْثَرَ مِنِ امْرَأَةٍ. ""لَمْ يَعُدْ مَنْطِقُ العَصْرِ يَسْمَحُ بِتَعَدُّدِ الزَّوْجَاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19172, 'تَعَدِّي', 'تعدي', 'مصدر', 'عدو', 'تعدي', 'تعد', 'مص. تَعَدَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R0', '', '', '', '', '', '', '"تَعَدٍّ-تَعَدٍّ، التَّعَدِّي [ع د و] (مص. تَعَدَّى). ""التَّعَدِّي عَلَى حُرْمَةِ الغَيْرِ يُعَاقِبُ عَلَيْهِ القَانُونُ"" : خَرْقُ حُرْمَتِهِ، اِنْتِهَاكُهَا..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19173, 'تَعَذُّرٌ', 'تعذر', 'مصدر', 'عذر', 'تعذر', 'تعذر', 'مص. تَعَذَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَذُّرٌ-تَعَذُّرٌ [ع ذ ر] (مص. تَعَذَّرَ). ""مَنَعَهُ تَعَذُّرُ الظُّرُوفِ مِنَ السَّفَرِ"" : الاسْتِحَالَةُ، الامْتِنَاعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19174, 'تَعَرُّجٌ', 'تعرج', 'مصدر', 'عرج', 'تعرج', 'تعرج', 'مص. تَعَرَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَرُّجٌ-تَعَرُّجٌ [ع ر ج] (مص. تَعَرَّجَ). 1.""تَعَرُّجُ البِنَاءِ"" : مَيْلُهُ. 2.""تَعَرُّجُ النَّهْرِ"" : اِنْعِطَافُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19175, 'تَعَرُّضٌ', 'تعرض', 'مصدر', 'عرض', 'تعرض', 'تعرض', 'مص. تَعَرَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَرُّضٌ-تَعَرُّضٌ [ع ر ض] (مص. تَعَرَّضَ). 1.""التَّعَرُّضُ لِلْخَطَرِ"": صَيْرُهُ هَدَفاً لَهُ. ""تَعَرُّضُ الجِسْمِ لِلأَمْرَاضِ"". 2.""التَّعَرُّضُ لِمَوْضُوعٍ مَّا"" : التَّصَدِّي لَهُ. 3.""التَّعَرُّضُ فِي القَضَاءِ"" : فِعْلٌ مَادِّيٌّ أَوْ إِجْرَاءٌ قَانُونِيٌّ يُقْصَدُ بِهِ مُنَازَعَةُ الحَائِزِ فِي حِيَازَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19176, 'تَعَرُّفٌ', 'تعرف', 'مصدر', 'عرف', 'تعرف', 'تعرف', 'مص. تَعَرَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَرُّفٌ-تَعَرُّفٌ [ع ر ف] (مص. تَعَرَّفَ). ""يُحَاوِلُ التَّعَرُّفَ بِأَصْدِقَاءَ جُدُدٍ"" : أَيْ مَعْرِفَتَهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19177, 'تَعَرْقُلٌ', 'تعرقل', 'مصدر', 'عرقل', 'تعرقل', 'تعرقل', 'مص. تَعَرْقَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَرْقُلٌ-تَعَرْقُلٌ [ع ر ق ل] (مص. تَعَرْقَلَ). 1.""تَعَرْقُلُ أُمُورِهِ"": تَشَوُّشُهَا. 2.""تَعَرْقُلُ السَّيْرِ"" : تَعَسُّرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19178, 'تَعَرِّي', 'تعري', 'مصدر', 'عري', 'تعري', 'تعر', 'مص. تَعَرَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R0', '', '', '', '', '', '', '"تَعَرٍّ-تَعَرٍّ، التَّعَرِّي [ع ر ي] (مص. تَعَرَّى). ""التَّعَرِّي مِنَ الثِّيَابِ"" : خَلْعُهَا، نَزْعُهَا، التَّجَرُّدُ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19179, 'تَعَطُّشٌ', 'تعطش', 'مصدر', 'عطش', 'تعطش', 'تعطش', 'مص. تَعَطَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَطُّشٌ-تَعَطُّشٌ [ع ط ش] (مص. تَعَطَّشَ). 1.""تَعَطُّشُ العَامِلِ"": تَكَلُّفُهُ العَطَشَ. 2.""هُوَ فِي تَعَطُّشٍ دَائِمٍ لِلْعِلْمِ"" : شَدِيدُ الْمَيْلِ إِلَيْهِ وَالرَّغْبَةِ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19180, 'تَعْسٌ', 'تعس', 'مصدر', 'تعس', 'تعس', 'تعس', 'مص. تَعَسَ، تَعِسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَعْسٌ-تَعْسٌ [ت ع س] (مص. تَعَسَ، تَعِسَ). 1.""تَعْساً لَهُ مِنْ شَقِيٍّ"" : لِيُنْزِلْ بِهِ اللَّهُ الهَلاَكَ وَالشَّقَاءَ وَالشَّرَّ، مَنْصُوبٌ عَلَى الْمَفْعُولِ الْمُطْلَقِ وَعَامِلُهُ مَحْذُوفٌ. 2.""يَالَهَا مِنْ حَيَاةِ تَعْسٍ وَنَكَدٍ !"" : بُؤْسٍ، عَنَاءٍ، شَقَاءٍ. ""عَاشَ فِي تَعْسٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19181, 'تَعَسُّرٌ', 'تعسر', 'مصدر', 'عسر', 'تعسر', 'تعسر', 'مص. تَعَسَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَسُّرٌ-تَعَسُّرٌ [ع س ر] (مص. تَعَسَّرَ). 1.""تَعَسُّرُ أَمْرٍ"" : صُعُوبَتُهُ، اِشْتِدَادُهُ. 2.""وَجَدَ فِي أَفْكَارِهِ تَعَسُّراً"" : اِلْتِبَاساً وَغُمُوضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19182, 'تَعَسُّفٌ', 'تعسف', 'مصدر', 'عسف', 'تعسف', 'تعسف', 'مص. تَعَسَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَسُّفٌ-تَعَسُّفٌ [ع س ف] (مص. تَعَسَّفَ). ""شَعْبِي أَبِيٌّ لاَ يَقْبَلُ التَّعَسُّفَ"" : لاَ يَقْبَلُ الظُّلْمَ، البَغْيَ، الطُّغْيَانَ. ""لاَ يَجُوزُ القَبْضُ عَلَى إِنْسَانٍ أَوْ حَجْزُهُ أَوْ نَفْيُهُ تَعَسُّفاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19183, 'تَعَشُّقٌ', 'تعشق', 'مصدر', 'عشق', 'تعشق', 'تعشق', 'مص. تَعَشَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَشُّقٌ-تَعَشُّقٌ [ع ش ق] (مص. تَعَشَّقَ). ""تَعَشُّقُ فَتَاةٍ"" : تَعَلُّقُ القَلْبِ بِهَا تَعَلُّقاً شَدِيداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19184, 'تَعَشِّي', 'تعشي', 'مصدر', 'عشو', 'تعشي', 'تعش', 'مص. تَعَشَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَعَشٍّ-تَعَشٍّ، التَّعَشِّي [ع ش و] (مص. تَعَشَّى). ""نَامَ بَعْدَ التَّعَشِّي"" : بَعْدَ أَكْلِ العَشَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19185, 'تَعَصُّبٌ', 'تعصب', 'مصدر', 'عصب', 'تعصب', 'تعصب', 'مص. تَعَصَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. تَعَصَّبَ). 1.""تَعَصُّبُ الفَقِيهِ"" : وَضْعُ العِصَابَةِ عَلَى رَأْسِه.ِ 2.""أَظْهَرَ تَعَصُّباً لِصَاحِبِهِ"" : كَانَ مُنَاصِرًا لَهُ بِشِدَّةٍ. ""فَقَالَ لَهَا مِنْ شَأْنِ النِّسَاءِ التَّعَصُّبُ بَعْضُهُنَّ لِبَعْضٍ"" (الجاحظ). 3.""هُوَ شَدِيدُ التَّعَصُّبِ لأَفْكَارِهِ"" : شَدِيدُ التَّعَنُّتِ، لاَ يَتَنَازَلُ عَنْهَا وَلَوْ مَعَ ظُهُورِ بُطْلاَنِهَا، وَيَنْظُرُ إِلَيْهَا بِإِعْجَابٍ شَدِيدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19186, 'تَعَصُّرٌ', 'تعصر', 'مصدر', 'عصر', 'تعصر', 'تعصر', 'مص. تَعَصَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَصُّرٌ-تَعَصُّرٌ [ع ص ر] (مص. تَعَصَّرَ). 1.""تَعَصُّرُ الْبُرْتُقَالِ"": خُرُوجُ مَا فِيهِ مِنْ سَائِلٍ. 2.""تَعَصُّرُ الْقَلْبِ مِنَ الْحَسْرَةِ"" : تَوَجُّعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19187, 'تَعَصِّي', 'تعصي', 'مصدر', 'عصي', 'تعصي', 'تعص', 'مص. تَعَصَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَعَصٍّ-تَعَصٍّ، التَّعَصِّي [ع ص ي] (مص. تَعَصَّى). ""تَعَصِّي الْوَالِدَيْنِ : عِصْيَانُهُمَا، الْخُرُوجُ عَنْ طَاعَتِهِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19188, 'تَعَطُّرٌ', 'تعطر', 'مصدر', 'عطر', 'تعطر', 'تعطر', 'مص. تَعَطَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَطُّرٌ-تَعَطُّرٌ [ع ط ر] (مص. تَعَطَّرَ). ""لاَ تَخْرُجُ إِلاَّ بَعْدَ تَعَطُّرٍ"" : بَعْدَ تَطَيُّبٍ بِالْعِطْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19189, 'تَعَقُّلٌ', 'تعقل', 'مصدر', 'عقل', 'تعقل', 'تعقل', 'مص. تَعَقَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَقُّلٌ-تَعَقُّلٌ [ع ق ل] (مص. تَعَقَّلَ). ""أَبَانَ عَنْ تَعَقُّلِهِ"" : عَنْ رُشْدِهِ وَتَبَصُّرِهِ وَتَرَوِّيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19190, 'تَعَطُّفٌ', 'تعطف', 'مصدر', 'عطف', 'تعطف', 'تعطف', 'مص. تَعَطَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَطُّفٌ-تَعَطُّفٌ [ع ط ف] (مص. تَعَطَّفَ). 1.""التَّعَطُّفُ عَلَيْهِمْ"" : إِحْسَانُ مُعَامَلَتِهِمْ. 2.""تَعَطُّفُ الطَّرِيقِ شِمَالاً"" : الْمَيْلُ إِلَيْهَا شِمَالاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19191, 'تَعَطُّلٌ', 'تعطل', 'مصدر', 'عطل', 'تعطل', 'تعطل', 'مص. تَعَطَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَطُّلٌ-تَعَطُّلٌ [ع ط ل] (مص. تَعَطَّلَ). 1.""لاَ أَحَدَ يَعْرِفُ سَبَبَ تَعَطُّلِ السَّيَّارَةِ"" : حُصُولُ عَطَبٍ بِهَا. 2. ""تَعَطُّلُ العَمَلِ"": تَوَقُّفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19192, 'تَعَظُّلٌ', 'تعظل', 'مصدر', 'عظل', 'تعظل', 'تعظل', 'مص. تَعَظَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَظُّلٌ-تَعَظُّلٌ [ع ظ ل] (مص. تَعَظَّلَ). ""تَعَظُّلُ القَوْمِ"" : اِجْتِمَاعُهُمْ. ""يَتَعَظَّلُونَ تَعَظُّلَ النَّمْلِ"" (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19193, 'تَعَظُّمٌ', 'تعظم', 'مصدر', 'عظم', 'تعظم', 'تعظم', 'مص. تَعَظَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَظُّمٌ-تَعَظُّمٌ [ع ظ م] (مص. تَعَظَّمَ). ""أَظْهَرَ تَعَظُّماً"" : تَكَبُّراً وَتَعَاظُماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19194, 'تَعَفُّرٌ', 'تعفر', 'مصدر', 'عفر', 'تعفر', 'تعفر', 'مص. تَعَفَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَفُّرٌ-تَعَفُّرٌ [ع ف ر] (مص. تَعَفَّرَ). 1.""تَعَفُّرُ الجِسْمِ"" : تَمَرُّغُهُ فِي التُّرَابِ. 2.""تَعَفُّرُ الْمَلاَبِسِ"" : تَلَوُّثُهَا بِالتُّرَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19195, 'تَعَفُّفٌ', 'تعفف', 'مصدر', 'عفف', 'تعفف', 'تعف', 'مص. تَعَفَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَفُّفٌ-تَعَفُّفٌ [ع ف ف] (مص. تَعَفَّفَ). ""يُعَامِلُ النَّاسَ بِتَعَفُّفٍ"" : بِعِفَّةٍ وَوَقَارٍ، بِتَأَفُّفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19196, 'تَعَفُّنٌ', 'تعفن', 'مصدر', 'عفن', 'تعفن', 'تعفن', 'مص. تَعَفَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَفُّنٌ-تَعَفُّنٌ [ع ف ن] (مص. تَعَفَّنَ). 1.""تَعَفُّنُ الجُرْحِ"" : تَكَوُّنُ الجَرَاثِيمِ فِيهِ. 2.""تَعَفُّنُ اللَّحْمِ"" : انْحِلاَلُ مَوَادِّهِ العُضْوِيَّةِ بِفِعْلِ الجَرَاثِيمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19197, 'تَعَقُّبٌ', 'تعقب', 'مصدر', 'عقب', 'تعقب', 'تعقب', 'مص. تَعَقَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَقُّبٌ-تَعَقُّبٌ [ع ق ب] (مص. تَعَقَّبَ). ""تَعَقُّبُ أَثَرِهِ"" : الْمَشْيُ خَلْفَهُ، اِقْتِفَاءُ أَثَرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19198, 'تَعَقُّدٌ', 'تعقد', 'مصدر', 'عقد', 'تعقد', 'تعقد', 'مص. تَعَقَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَقُّدٌ-تَعَقُّدٌ [ع ق د] (مص. تَعَقَّدَ). 1.""الْمَشَاكِلُ فِي تَعَقُّدٍ مُسْتَمِرٍّ"" : فِي تَخَبُّطٍ، فِي عُسْرٍ. 2.""تَعَقُّدُ الكَلاَمِ"" : الْتِبَاسُهُ وَغُمُوضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19199, 'تَعَكُّزٌ', 'تعكز', 'مصدر', 'عكز', 'تعكز', 'تعكز', 'مص. تَعَكَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَكُّزٌ-تَعَكُّزٌ [ع ك ز] (مص. تَعَكَّزَ). ""التَّعَكُّزُ عَلَى العَصَا"": اِتِّخَاذُهَا عُكَّازَةً، الاتِّكَاءُ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19200, 'تَعَلُّقٌ', 'تعلق', 'مصدر', 'علق', 'تعلق', 'تعلق', 'مص. تَعَلَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَلُّقٌ-تَعَلُّقٌ [ع ل ق] (مص. تَعَلَّقَ). 1.""لَمْ يَكُنْ تَعَلُّقُهُ بِهِ عَنِ اقَتِنَاعٍ"" : تَشَبُّثُه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19201, 'تَعَلُّلٌ', 'تعلل', 'مصدر', 'علل', 'تعلل', 'تعل', 'مص. تَعَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَلُّلٌ-تَعَلُّلٌ [ع ل ل] (مص. تَعَلَّلَ). 1.""التَّعَلُّلُ بِالأَوْهَامِ"" : تَشْغِيلُ النَّفْسِ بِهَا. 2.""وَجَدَ فِي الْمَرَضِ تَعَلُّلاً"" : حُجَّةً لِتَبْرِيرِ مَوْقِفِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19202, 'تَعَلُّمٌ', 'تعلم', 'مصدر', 'علم', 'تعلم', 'تعلم', 'مص. تَعَلَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَلَّمْ-تَعَلَّمْ [ع ل م] (صِيغَةُ أَمْرٍ).: لاَ تَتَصَرَّفُ، وَهِيَ مِنْ أَفْعَالِ القُلُوبِ وَاليَقِينِ تَتَعَدَّى إِلَى مَفْعُولَيْنِ بِمَعْنَى اِعْلَمْ وَالأَكْثَرُ وُقُوعُهَا عَلَى أَنَّ وَصِلَتِهَا كَقَوْلِكَ: ""فَقُلْتُ تَعَلَّمْ أَنَّ لِلْعِلْمِ حِكْمَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19203, 'تَعَلِّي', 'تعلي', 'مصدر', 'علو', 'تعلي', 'تعل', 'مص. تَعَلَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَعَلٍّ-تَعَلٍّ، التَّعَلِّي [ع ل و] (مص. تَعَلَّى). ""تَعَلِّي البِنَاءِ"" : عُلُوُّهُ، اِرْتِفَاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19204, 'تَعَمُّجٌ', 'تعمج', 'مصدر', 'عمج', 'تعمج', 'تعمج', 'مص. تَعَمَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَمُّجٌ-تَعَمُّجٌ [ع م ج] (مص. تَعَمَّجَ). ""تَسِيرُ فِي تَعَمُّجٍ"" : تَسِيرُ مُعْوَجَّةً يَمْنَةً وَيَسْرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19205, 'تَعَمُّدٌ', 'تعمد', 'مصدر', 'عمد', 'تعمد', 'تعمد', 'مص. تَعَمَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَمُّدٌ-تَعَمُّدٌ [ع م د] (مص. تَعَمَّدَ). ""كَانَ تَعَمُّدُهُ مَقْصُوداً"": قَصْدُهُ، إِصْرَارُهُ. ""طَعَنَهُ بِتَعَمُّدٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19206, 'تَعَمُّقٌ', 'تعمق', 'مصدر', 'عمق', 'تعمق', 'تعمق', 'مص. تَعَمَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَمُّقٌ-تَعَمُّقٌ [ع م ق] (مص. تَعَمَّقَ). "" أَظْهَرَ تَعَمُّقاً فِي عِلْمِهِ"" : اِسْتِقْصَاءً وَتَضَلُّعاً وَخِبْرَةً عَمِيقَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19207, 'تَعَمُّمٌ', 'تعمم', 'مصدر', 'عمم', 'تعمم', 'تعم', 'مص. تَعَمَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَمُّمٌ-تَعَمُّمٌ [ع م م] (مص. تَعَمَّمَ). "" تَعَمُّمُ الفَقِيهِ"" : لُبْسُهُ العِمَامَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19208, 'تَعَنِّي', 'تعني', 'مصدر', 'عني', 'تعني', 'تعن', 'مص. تَعَنَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَعَنٍّ-تَعَنٍّ، التَّعَنِّي [ع ن ي] (مص. تَعَنَّى). 1.""وَجَدَهُ فِي تَعَنٍّ"" : فِي تَعَبٍ شَدِيدٍ. 2.""يُعَالِجُ أُمُورَهُ بِالتَّعَنِّي"" : بِالاقْتِصَادِ وَالاعْتِدَالِ. 3.""تَعَنِّي الْمَشَاكِلِ"" : مُعَانَاتُهَا وَتَحَمُّلُ تَعَبِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19209, 'تَعَهُّدٌ', 'تعهد', 'مصدر', 'عهد', 'تعهد', 'تعهد', 'مص. تَعَهَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَهُّدٌ-تَعَهُّدٌ [ع هـ د] (مص. تَعَهَّدَ). 1.""وَقَّعَ تَعَهُّدًا بِدَفْعِ دَيْنِهِ"" : التِزَاماً. ""لَمْ يُلْزِمْ نَفْسَهُ بِأَيِّ تَعَهُّدٍ"". 2.""اِهْتَمَّ بِتَعَهُّدِ أَبْنَائِهِ"" : إِلْزَامُ نَفْسِهِ بِالعِنَايَةِ وَالاهْتِمَامِ بِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19210, 'تَعَوُّجٌ', 'تعوج', 'مصدر', 'عوج', 'تعوج', 'تعج', 'مص. تَعَوَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَوُّجٌ-تَعَوُّجٌ [ع و ج] (مص. تَعَوَّجَ). ""تَعَوُّجُ القَضِيبِ"" : اِنْحِنَاؤُهُ، اِلتِوَاؤُهُ، اِعْوِجَاجُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19211, 'تَعَوُّدٌ', 'تعود', 'مصدر', 'عود', 'تعود', 'تعد', 'مص. تَعَوَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَوُّدٌ-تَعَوُّدٌ [ع و د] (مص. تَعَوَّدَ). 1.""تَعَوُّدُ مُمَارَسَةِ الرِّيَاضَةِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19212, 'تَعَوُّذٌ', 'تعوذ', 'مصدر', 'عوذ', 'تعوذ', 'تعذ', 'مص. تَعَوَّذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَوُّذٌ-تَعَوُّذٌ [ع و ذ] (مص. تَعَوَّذَ). 1.""لَمْ يَجِدْ أَحَداً لِلتَّعَوُّذِ بِهِ"" : الاِلْتِجَاءِ إِلَيْهِ وَالاعْتِصَامِ بِهِ. 2.""التَّعَوُّذُ بِاللهِ"" : قَوْلُ : ""أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19213, 'تَعَوُّضٌ', 'تعوض', 'مصدر', 'عوض', 'تعوض', 'تعض', 'مص. تَعَوَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَوُّضٌ-تَعَوُّضٌ [ع و ض] (مص. تَعَوَّضَ). ""طَال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19214, 'تَعَوُّقٌ', 'تعوق', 'مصدر', 'عوق', 'تعوق', 'تعق', 'مص. تَعَوَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَوُّقٌ-تَعَوُّقٌ [ع و ق] (مص. تَعَوَّقَ). 1. ""مَشَاكِلُهُ فِي تَعَوُّقٍ"" : فِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19215, 'تَعَيُّشٌ', 'تعيش', 'مصدر', 'عيش', 'تعيش', 'تعش', 'مص. تَعَيَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَيُّشٌ-تَعَيُّشٌ [ع ي ش] (مص. تَعَيَّشَ). ""يَسْعَى لِتَعَيُّشِ أَبْنَائِهِ"": يَسْعَى لِكَسْبِ مَعِيشَتِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19216, 'تَعَيُّنٌ', 'تعين', 'مصدر', 'عين', 'تعين', 'تعن', 'مص. تَعَيَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعَيُّنٌ-تَعَيُّنٌ [ع ي ن] (مص. تَعَيَّنَ). 1.""يَخَافُ مِنَ التَّعَيُّنِ"": مِنْ إِصَابَتِهِ بِعَيْنِ حَسُودٍ. 2.""تَعَيُّنُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19217, 'تَغَابُطٌ', 'تغابط', 'مصدر', 'غبط', 'تغابط', 'تغبط', 'مص. تَغَابَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغَابُطٌ-تَغَابُطٌ [غ ب ط] (مص. تَغَابَطَ). ""تَغَابُطُ الوَلَدَيْنِ"" : غَبْطُ أَحَدِهِمَا الآخَرَ، أَيْ تَمَنَّى مِثْلَ مَا لَهُ مِنَ النِّعْمَةِ مِنْ غَيْرِ رَغْبَةٍ فِي زَوَالِهَا عَنْهُ. ""يَعُودُ الحَسَدُ غِبْطَةً أَوْ تَغَابُطاً"" (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19218, 'تَغَابُنٌ', 'تغابن', 'مصدر', 'غبن', 'تغابن', 'تغبن', 'مص. تَغَابَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغَابُنٌ-تَغَابُنٌ [غ ب ن] (مص. تَغَابَنَ). 1.""تَغَابُنُ النَّاسِ فِي السُّوقِ"" : تَخَادُعُهُمْ، غَبْنُ بَعْضِهِمْ بَعْضاً. 2.""يَوْمُ التَّغَابُنِ"" : يَوْمُ القِيَامَةِ. التغابن آية 9 يَوْمَ يَجْمَعُكُمْ لِيَوْمِ الجَمْعِ. ذَلِكَ يَوْمُ التَّغَابُنِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19219, 'تَغَدِّي', 'تغدي', 'مصدر', 'غدو', 'تغدي', 'تغد', 'مص. تَغَدَّي', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَغَدٍّ-تَغَدٍّ، التَّغَدِّي [غ د و] (مص. تَغَدَّي). ""زَارَهُ وَقْتَ التَّغَدِّي"" : وَقْتَ أَكْلِ الغَدَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19220, 'تَغَازُلٌ', 'تغازل', 'مصدر', 'غزل', 'تغازل', 'تغزل', 'مص. تَغَازَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغَازُلٌ-تَغَازُلٌ [غ ز ل] (مص. تَغَازَلَ). ""فِي تَغَازُلِه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19221, 'تَغَاضِي', 'تغاضي', 'مصدر', 'غضي', 'تغاضي', 'تغض', 'مص. تَغَاضَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَغَاضٍ-تَغَاضٍ، التَّغَاضِي [غ ض ي] (مص. تَغَاضَى). ""التَّغَاضِي عَنْ أَفْعَالِهِ"" : التَّغَافُلُ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19222, 'تَغَافُلٌ', 'تغافل', 'مصدر', 'غفل', 'تغافل', 'تغفل', 'مص. تَغَافَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغَافُلٌ-تَغَافُلٌ [غ ف ل] (مص. تَغَافَلَ). 1.""لَمْ يَشْعُرْ بِتَغَافُلِهِ"": أَيْ لَمْ يَشْعُرْ بِأَنَّهُ غَافِلٌ عَنْهُ وَلَيْسَ ك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19223, 'تَغَالُطٌ', 'تغالط', 'مصدر', 'غلط', 'تغالط', 'تغلط', 'مص. تَغَالَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغَالُطٌ-تَغَالُطٌ [غ ل ط] (مص. تَغَالَطَ). ""وَكَأَنَّهُمُ اتَّفَقُوا ع"', '');
