INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19249, 'تَفَادِي', 'تفادي', 'مصدر', 'فدي', 'تفادي', 'تفد', 'مص. تَفَادَى ', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَفَادٍ-تَفَادٍ، التَّفَادِي [ف د ي] (مص. تَفَادَى) 1.""سَعَى إِلَىتَفَادِي الخُصُومَةِ"" : إِلَى تَجَنُّبِهَا، تَحَاشِيهَا، تَل"', '');
