INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19252, 'تَغَيُّرٌ', 'تغير', 'مصدر', 'غير', 'تغير', 'تغر', 'مص. تَغَيَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغَيُّرٌ-تَغَيُّرٌ [غ ي ر] (مص. تَغَيَّرَ). 1.""حَدَثَ تَغَيُّرٌ مُفَاجِئٌ فِي طَقْسِ اليَوْمِ"', '');
