INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19254, 'تَفَاؤُلٌ', 'تفاؤل', 'مصدر', 'فأل', 'تفاءل', 'تفل', 'مص. تَفَاءلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَاؤُلٌ-تَفَاؤُلٌ [ف أ ل] (مص. تَفَاءلَ). ""هُوَ دَائِمُ التَّفَاؤُلِ"" : دَائِمُ الانْشِرَاحِ، مَنْ يَرَى كُلَّ شَيءٍ جَمِيل. عَكْسُ التَّشَاؤُمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19255, 'تَفَاتُحٌ', 'تفاتح', 'مصدر', 'فتح', 'تفاتح', 'تفتح', 'مص. تَفَاتَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَاتُحٌ-تَفَاتُحٌ [ف ت ح] (مص. تَفَاتَحَ). ""كَانَ تَفَاتُحُهُمَا الحَدِيثَ تَعْبِيراً عَنْ وُجُودِ سِرٍّ بَيْنَهُمَا"" : تَكَلُّمُهُمَا بِصَوْتٍ خَافِتٍ دُونَ النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19256, 'تَفَاجُرٌ', 'تفاجر', 'مصدر', 'فجر', 'تفاجر', 'تفجر', 'مص. تَفَاجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَاجُرٌ-تَفَاجُرٌ [ف ج ر] (مص. تَفَاجَرَ). ""تَفَاجُرُ "', '');
