INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19258, 'تَفَاخُرٌ', 'تفاخر', 'مصدر', 'فخر', 'تفاخر', 'تفخر', 'مص. تَفَاخَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَاخُرٌ-تَفَاخُرٌ [ف خ ر] (مص. تَفَاخَرَ). "" أَظْهَرَ تَفَاخُراً"" : تَكَبُّرًا، تَعَاظُماً."', '');
