INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19261, 'تَفَاسُحٌ', 'تفاسح', 'مصدر', 'فسح', 'تفاسح', 'تفسح', 'مص. تَفَاسَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَاسُحٌ-تَفَاسُحٌ [ف س ح] (مص. تَفَاسَحَ). ""تَفَاسُحُ النَّاسِ"": تَوَسُّعُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19262, 'تَفَاسُدٌ', 'تفاسد', 'مصدر', 'فسد', 'تفاسد', 'تفسد', 'مص. تَفَاسَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَاسُدٌ-تَفَاسُدٌ [ف س د] (مص. تَفَاسَدَ). ""تَفَاسُدُ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19263, 'تَفَاصُحٌ', 'تفاصح', 'مصدر', 'فصح', 'تفاصح', 'تفصح', 'مص. تَفَاصَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَاصُحٌ-تَفَاصُحٌ [ف ص ح] (مص. تَفَاصَحَ). ""أَرَادَ إظْهَارَ تَفَاصُحِهِ"" : إِظْهَارَ فَصَاحَتِهِ وَتَكَلُّفَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19264, 'تَفَاضُحٌ', 'تفاضح', 'مصدر', 'فضح', 'تفاضح', 'تفضح', 'مص. تَفَاضَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَاضُحٌ-تَفَاضُحٌ [ف ض ح] (مص. تَفَاضَحَ). ""تَفَاضُحُ الأَعْدَاءِ"" : كَشْفُ بَعْضِهِمْ عُيُوبَ البَعْضِ الآخَرِ', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19265, 'تَفَاضُلٌ', 'تفاضل', 'مصدر', 'فضل', 'تفاضل', 'تفضل', 'مص. تَفَاضَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَاضُلٌ-تَفَاضُلٌ [ف ض ل] (مص. تَفَاضَلَ). 1.""لاَ تَفَاضُلَ لأَحَدِهِمَا عَلَى الآخَرِ"" : لا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19266, 'تَفَاعُلٌ', 'تفاعل', 'مصدر', 'فعل', 'تفاعل', 'تفعل', 'مص. تَفَاعَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَفَاعُلٌ-تَفَاعُلٌ [ف ع ل] (مص. تَفَاعَلَ). 1.""أَصْبَحَ بَيْنَهُمَا تَفَاعُلٌ مُسْتَمِرٌّ"" : تَأْثِيرٌ مُتَبَادَلٌ. 2.""تَفَاعُلٌ كِيمِيَائِيٌّ"" : تَغَيُّرٌ يَحْدُث"', '');
