INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19268, 'تَفَاقُمٌ', 'تفاقم', 'مصدر', 'فقم', 'تفاقم', 'تفقم', 'مص. تَفَاقَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَاقُمٌ-تَفَاقُمٌ [ف ق م] (مص. تَفَاقَمَ). 1.""حَاوَلَ الطَّبِيبُ أَنْ يَحُدَّ مِنْ تَفَاقُمِ الْمَرَضِ"" : مِنْ تَزَايُدِهِ وَتَضَخُّمِهِ، مِنِ اسْتِفْحَالِهِ. 2. ""تَفَاقُمُ الكَوَارِثِ"" : اِشْتِدَادُهَا، تَعَاظُمُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19269, 'تَفَتُّلٌ', 'تفتل', 'مصدر', 'فتل', 'تفتل', 'تفتل', 'مص. تَفَتَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَتُّلٌ-تَفَتُّلٌ [ف ت ل] (مص. تَفَتَّلَ). ""تَفَتُّلُ الخَيْطِ"" : اِلْتِوَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19270, 'تَفَانِي', 'تفاني', 'مصدر', 'فني', 'تفاني', 'تفن', 'مص. تَفَانَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَفَانٍ-تَفَانٍ، التَّفَانِي [ف ن ي] (مص. تَفَانَى). ""التَّفَانِي فِي العَمَلِ"" : بَذْلُ الجُهْدِ فِيهِ."', '');
