INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19272, 'تَفَاوُتٌ', 'تفاوت', 'مصدر', 'فوت', 'تفاوت', 'تفت', 'مص. تَفَاوَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَاوُتٌ-تَفَاوُتٌ [ف و ت] (مص. تَفَاوَتَ). 1.""بَيْنَهُمَا تَفَاوُتٌ فِي الرَّأْيِ"" : تَبَاعُدٌ، اِخْتِلاَفٌ، تَبَايُنٌ. ""بَيْنَهُمَا تَفَاوُتٌ ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19273, 'تَفَاوُضٌ', 'تفاوض', 'مصدر', 'فوض', 'تفاوض', 'تفض', 'مص. تَفَاوَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَاوُضٌ-تَفَاوُضٌ [ف و ض] (مص. تَفَاوَضَ). ""اِسْتَقَرَّ رَأْيُهُمْ عَلَى ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19274, 'تَفَتُّتٌ', 'تفتت', 'مصدر', 'فتت', 'تفتت', 'تفت', 'مص. تَفَتَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَتُّتٌ-تَفَتُّتٌ [ف ت ت] (مص. تَفَتَّتَ). ""تَفَتُّتُ الصَّخْرِ"" : تَكَسُّرُهُ، تَجَزُّؤُهُ أَحْجَاراً صَغِيرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19275, 'تَفَتُّحٌ', 'تفتح', 'مصدر', 'فتح', 'تفتح', 'تفتح', 'مص. تَفَتَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَتُّحٌ-تَفَتُّحٌ [ف ت ح] (مص. تَفَتَّحَ). ""تَفْسِيرُهُ يُسَاعِدُ عَلَى تَفَتُّحِ الذِّهْنِ"" : عَلَى تَوَقُّدِهِ، يُسَاعِدُ عَلَى تَطَوُّرٍ فِي فَهْمِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19276, 'تَفَتُّرٌ', 'تفتر', 'مصدر', 'فتر', 'تفتر', 'تفتر', 'مص. تَفَتَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَتُّرٌ-تَفَتُّرٌ [ف ت ر] (مص. تَفَتَّرَ). 1.""تَفَتُّرُ الفَيَضَانِ"" : سُكُونُهُ. 2. ""تَفَتُّرُ الْمَاءِ"" : سُكُونُ حَرِّهِ. 3."" التَّفَتُّرُ عَنِ العَمَلِ"": التَّقْصِيرُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19277, 'تَفَتُّقٌ', 'تفتق', 'مصدر', 'فتق', 'تفتق', 'تفتق', 'مص. تَفَتَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَتُّقٌ-تَفَتُّقٌ [ف ت ق] (مص. تَفَتَّقَ). 1.""تَفَتُّقُ الزَّهْرَةِ"" : تَفَتُّحُهَا، إ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19278, 'تَفَتُّكٌ', 'تفتك', 'مصدر', 'فتك', 'تفتك', 'تفتك', 'مص. تَفَتَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَتُّكٌ-تَفَتُّكٌ [ف ت ك] (مص. تَفَتَّكَ). ""التَّفَت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19279, 'تَفَرُّغٌ', 'تفرغ', 'مصدر', 'فرغ', 'تفرغ', 'تفرغ', 'مص. تَفَرَّغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَرُّغٌ-تَفَرُّغٌ [ف ر غ] (مص. تَفَرَّغَ). ""قَضَى سَنَةَ تَفَرُّغٍ"": سَنَةَ انْقِطَاعٍ عَنِ العَمَلِ. ""أَخَذَ سَنَةً كَامِلَةً لِلتَّفَرُّغِ لِلتَّأْلِيفِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19280, 'تَفَجُّرٌ', 'تفجر', 'مصدر', 'فجر', 'تفجر', 'تفجر', 'مص. تَفَجَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَجُّرٌ-تَفَجُّرٌ [ف ج ر] (مص. تَفَجَّرَ). 1.""تَفَجُّرُ المِيَاهِ"" : تَدَفُّقُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19281, 'تَفَحُّشٌ', 'تفحش', 'مصدر', 'فحش', 'تفحش', 'تفحش', 'مص. تَفَحَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَحُّشٌ-تَفَحُّشٌ [ف ح ش] (مص. تَفَحَّشَ). 1.""إِظْهَارُ التَّفَحُّشِ"" : إِسْمَاعُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19282, 'تَفَحُّصٌ', 'تفحص', 'مصدر', 'فحص', 'تفحص', 'تفحص', 'مص. تَفَحَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَحُّصٌ-تَفَحُّصٌ [ف ح ص] (مص. تَفَحَّصَ). ""تَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19283, 'تَفَخُّرٌ', 'تفخر', 'مصدر', 'فخر', 'تفخر', 'تفخر', 'مص. تَفَخَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَخُّرٌ-تَفَخُّرٌ [ف خ ر] (مص. تَفَخَّرَ). ""تَفَخُّرُ الرَّجُلِ"" : تَكَبُّرُهُ، تَعَظُّمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19284, 'تَفَرُّجٌ', 'تفرج', 'مصدر', 'فرج', 'تفرج', 'تفرج', 'مص. تَفَرَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَرُّجٌ-تَفَرُّجٌ [ف ر ج] (مص. تَفَرَّجَ). 1.""جَاءَ لِلتَّفَرُّجِ عَلَىالْمَسْرَحِيَّةِ"" : مُشَاهَدَتُهَا وَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19285, 'تَفَرُّدٌ', 'تفرد', 'مصدر', 'فرد', 'تفرد', 'تفرد', 'مص. تَفَرَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَرُّدٌ-تَفَرُّدٌ [ف ر د] (مص. تَفَرَّدَ). 1. ""التَّفَرُّدُ بِالْمَسْؤُولِيَّةِ"": الانْفِرَادُ بِهَا وَعَدَمُ إِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19286, 'تَفَرُّسٌ', 'تفرس', 'مصدر', 'فرس', 'تفرس', 'تفرس', 'مص. تَفَرَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَرُّسٌ-تَفَرُّسٌ [ف ر س] (مص. تَفَرَّسَ). 1.""التَّفَرُّسُ فِي الْمَلاَمِحِ"" : تَأَمُّلُهَا وَتَثْبِيتُ النَّظَر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19287, 'تَفَرُّعٌ', 'تفرع', 'مصدر', 'فرع', 'تفرع', 'تفرع', 'مص. تَفَرَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَرُّعٌ-تَفَرُّعٌ [ف ر ع] (مص. تَفَرَّعَ). 1.""تَفَرُّعُ غُصْنٍ"" : تَكَاثُرُهُ. 2.""تَفَرُّعُ طَرِيقٍ"" : تَفَرُّقُهُ. 3."" تَفَرُّعُ العُلُومِ"" : تَشَعُّبُهَا، تَدَاخُلُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19288, 'تَفَرْعُنٌ', 'تفرعن', 'مصدر', 'فرع', 'تفرعن', 'تفرعن', 'مص. تَفَرْعَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَرْعُنٌ-تَفَرْعُنٌ [ف ر ع] (مص. تَفَرْعَنَ). ""تَفَرْعُنُ الرَّجُلِ"": تَجَبُّرُهُ، طُغْيَانُهُ، أَوْ تَخَلُّقُهُ بِأَخْلاَقِ الفَرَاعِنَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19289, 'تَفَصُّحٌ', 'تفصح', 'مصدر', 'فصح', 'تفصح', 'تفصح', 'مص. تَفَصَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَصُّحٌ-تَفَصُّحٌ [ف ص ح] (مص. تَفَصَّحَ). ""وَجَدَ فِي خُطْبَتِهِ تَفَصُّحاً"" : تَكَلُّف الفَصَاحَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19290, 'تَفَرُّقٌ', 'تفرق', 'مصدر', 'فرق', 'تفرق', 'تفرق', 'مص. تَفَرَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَرُّقٌ-تَفَرُّقٌ [ف ر ق] (مص. تَفَرَّقَ). 1.""تَفَرُّقُ الجَمْعِ"" : تَشَتُّتُهُ، تَوَزُّعُهُ. 2.""حَاوَلَ أَنْ يَحُولَ دُونَ تَفَرُّقِ كَلِمَتِهِمْ"" : اِخْتِلاَفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19291, 'تَفَرْقُعٌ', 'تفرقع', 'مصدر', 'فرق', 'تفرقع', 'تفرقع', 'مص. تَفَرْقَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَرْقُعٌ-تَفَرْقُعٌ [ف ر ق] (مص. تَفَرْقَعَ). 1.""تَفَرْقُعُ الأَصَابِعِ"": طَقْطَقَتُهَا. 2.""مُنْذُ سَاعَةٍ وَنَحْنُ نَسْتَمِعُ إِلَى تَفَرْقُعِ البَارُودِ"" : اِنْفِجَارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19292, 'تَفَرْنُجٌ', 'تفرنج', 'مصدر', 'فرن', 'تفرنج', 'تفرنج', 'مص. تَفَرْنَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَرْنُجٌ-تَفَرْنُجٌ [ف ر ن] (مص. تَفَرْنَجَ). ""تَفَرْنُجُ الرَّجُلِ"": صَيْرُهُ مِثْلَ الفِرِنْجِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19293, 'تَفَرْنُسٌ', 'تفرنس', 'مصدر', 'فرن', 'تفرنس', 'تفرنس', 'مص. تَفَرْنَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَرْنُسٌ-تَفَرْنُسٌ [ف ر ن] (مص. تَفَرْنَسَ). ""لِمَاذَا هَذَا التَّفَرْنُسُ وَالتَّخَلِّي عَنْ عَادَات"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19294, 'تَفَزُّرٌ', 'تفزر', 'مصدر', 'فزر', 'تفزر', 'تفزر', 'مص. تَفَزَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَزُّرٌ-تَفَزُّرٌ [ف ز ر] (مص. تَفَزَّرَ). ""تَفَزُّرُ عَجَلَةِ السَّيَّارَةِ"": اِنْفِجَارُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19295, 'تَفَسُّحٌ', 'تفسح', 'مصدر', 'فسح', 'تفسح', 'تفسح', 'مص. تَفَسَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَسُّحٌ-تَفَسُّحٌ [ف س ح] (مص. تَفَسَّحَ). ""تَفَسُّحُ البَيْتِ"" : اِتِّسَاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19296, 'تَفَسُّخٌ', 'تفسخ', 'مصدر', 'فسخ', 'تفسخ', 'تفسخ', 'مص. تَفَسَّخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَسُّخٌ-تَفَسُّخٌ [ف س خ] (مص. تَفَسَّخَ). 1.""تَفَسُّخُ الشَّعْرِ عَنِ الجِلْدِ"" : تَطَايُرُهُ، تَسَاقُطُهُ، اِنْفِصَالُهُ. 2.""تَفَسُّخُ الصِّبَاغَةِ عَنِ الجِدَارِ"" : زَوَالُهَا، اِنْحِلاَلُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19297, 'تَفَسُّرٌ', 'تفسر', 'مصدر', 'فسر', 'تفسر', 'تفسر', 'مص. تَفَسَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَسُّرٌ-تَفَسُّرٌ [ف س ر] (مص. تَفَسَّرَ). ""سَعَى لِتَفَسُّرِهِ عَمَّا غَمُضَ عَلَيْهِ"": اِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19298, 'تَفَشِّي', 'تفشي', 'مصدر', 'فشو', 'تفشي', 'تفش', 'مص. تَفَشَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَفَشٍّ-تَفَشٍّ، التَّفَشِّي [ف ش و] (مص. تَفَشَّى). ""تَفَشِّي الأَسْرَارِ"": شُيُوعُهَا، اِنْتِش"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19299, 'تَفَصُّدٌ', 'تفصد', 'مصدر', 'فصد', 'تفصد', 'تفصد', 'مص. تَفَصَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَصُّدٌ-تَفَصُّدٌ [ف ص د] (مص. تَفَصَّدَ). 1.""تَفَصُّدُ الدَّمِ"" : سَيَلاَنُهُ، جَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19300, 'تَفَصُّلٌ', 'تفصل', 'مصدر', 'فصل', 'تفصل', 'تفصل', 'مص. تَفَصَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَصُّلٌ-تَفَصُّلٌ [ف ص ل] (مص. تَفَصَّلَ). ""تَفَصُّلُ الثَّوْبِ"": تَقَطُّعُهُ أَطْرَافاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19301, 'تَفَضُّلٌ', 'تفضل', 'مصدر', 'فضل', 'تفضل', 'تفضل', 'مص. تَفَضَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَضُّلٌ-تَفَضُّلٌ [ف ض ل] (مص. تَفَضَّلَ). 1.""رَغِبَ فِي التَّفَضُّلِ عَلَيْهِ"" : إِعْطَاؤُهُ، إِنَالَتُهُ شَيْئاً مِنْ فَضْلِهِ. وَمَا ذَاكَ إِلاَّ بَسْطَةٌ عَنْ تَفَضُّلٍ*عَلَيْهِمْ وَكَانَ الأَفْضَلَ الْمُتَفَضِّلُ (الشنفرى). 2.""دَعَاهُ إِلَى التَّفَضُّلِ"" : دَعَاهُ لِلْجُلُوسِ أَوْ تَنَاوُلِ شَيْءٍ عَلَى سَبِيلِ التَّجَمُّلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19302, 'تَفَضِّي', 'تفضي', 'مصدر', 'فضي', 'تفضي', 'تفض', 'مص. تَفَضَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَفَضٍّ-تَفَضٍّ، التَّفَضِّي [ف ض ي] (مص. تَفَضَّى). ""التَّفَضِّي لِلْعَمَلِ"" : التَّفَرُّغُ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19303, 'تَفَطُّرٌ', 'تفطر', 'مصدر', 'فطر', 'تفطر', 'تفطر', 'مص. تَفَطَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَطُّرٌ-تَفَطُّرٌ [ف ط ر] (مص. تَفَطَّرَ). 1.""تَفَطُّرُ الأَرْضِ بِالنَّبَاتِ"" : تَشَقُّقُهَا. ""تَفَطُّرُ السَّمَاوَاتِ"". 2.""تَفَطُّرُ الْقَلْبِ"": تَصَدُّعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19304, 'تَفَطُّنٌ', 'تفطن', 'مصدر', 'فطن', 'تفطن', 'تفطن', 'مص. تَفَطَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَطُّنٌ-تَفَطُّنٌ [ف ط ن] (مص. تَفَطَّنَ). ""التَّفَطُّنُ لِلْكَلاَمِ"": تَفَهُّمُهُ، التَّنَبُّهُ إِلَيْهِ وَفَهْمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19305, 'تَفَقُّدٌ', 'تفقد', 'مصدر', 'فقد', 'تفقد', 'تفقد', 'مص. تَفَقَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَفَقُّدٌ-تَفَقُّدٌ [ف ق د] (مص. تَفَقَّدَ). 1.""طَلَبَ مِنْهُ تَفَقُّدَ أَحْوَالِ السُّكَّانِ"" : أَيْ مُلاَحَظَتَهَا وَمُرَاقَبَتَهَا عَنْ قُرْبٍ. ""جَهَدَ نَفْسَهُ فِي تَفَقُّدِ أُمُورِهِ"" .(الجاحظ). 2.""جَاءَ لِتَفَقُّدِ مَا ضَاعَ مِنهُ"" : لِبَحْثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19306, 'تَفَقُّصٌ', 'تفقص', 'مصدر', 'فقص', 'تفقص', 'تفقص', 'مص. تَفَقَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَقُّصٌ-تَفَقُّصٌ [ف ق ص] (مص. تَفَقَّصَ). ""تَفَقُّصُ الْبَيْضِ"": اِنْشِقَاقُهُ، اِنْكِسَارُهُ عَنِ الْفَرْخِ لِيَخْرُجَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19307, 'تَفَقْفُقٌ', 'تفقفق', 'مصدر', 'فقف', 'تفقفق', 'تفقفق', 'مص. تَفَقْفَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَقْفُقٌ-تَفَقْفُقٌ [ف ق ف] (مص. تَفَقْفَقَ). ""التَّفَقْفُقُ فِي الْكَلاَمِ"" : إِخْرَاجُهُ مِنَ الْحَلْقِ."', '');
