INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19321, 'تَفَنُّنٌ', 'تفنن', 'مصدر', 'فنن', 'تفنن', 'تفن', 'مص. تَفَنَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَنُّنٌ-تَفَنُّنٌ [ ف ن ن ] (مص. تَفَنَّنَ). 1.""التَّفَنُّنُ فِي الْمُوسِيقَى"" : الإِبْدَاعُ فِيهَا وَالتَّن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19322, 'تَفَاهَةٌ', 'تفاهة', 'مصدر', 'تفه', 'تفاهة', 'تفهة', 'مص. تَفِهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَوَافِهُ"', '', 'R', '', '', '', '', '', '', '"(مص. تَفِهَ). 1.""تَفَاهَةٌ مَا بَعْدَهَا مِنْ تَفَاهَةٍ"" : الحَقَارَةُ، الدَّنَاءةُ. 2. ""يَشْتَغِلُ بِتَوَافِهِ الأُمُورِ"" : بِمَا لاَ أَهَمِّيَّةَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19323, 'تَوَافِهُ', 'توافه', 'مصدر', '', 'توافه', 'تفه', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19324, 'تَفَهُّمٌ', 'تفهم', 'مصدر', 'فهم', 'تفهم', 'تفهم', 'مص. تَفَهَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَهُّمٌ-تَفَهُّمٌ [ف هـ م] (مص. تَفَهَّمَ). 1.""هُوَ فِي طَرِيقِهِ لِتَفَهُّمِ آرَائِهِ"" : لِفَهْمِهَا شَيْئاً فَشَيْئاً، تَدْرِيجِيّاً. 2.""تَفَهُّمُ مَوْقِفٍ"": مُحَاوَلَةُ فَهْمِهِ وَتَقَبُّلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19325, 'تَفَوُّقٌ', 'تفوق', 'مصدر', 'فوق', 'تفوق', 'تفق', 'مص. تَفَوَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَوُّقٌ-تَفَوُّقٌ [ف و ق] (مص. تَفَوَّقَ). 1.""أَحْرَزَ تَفَوُّقاً كَبِيرًا"": أَحْرَزَ تَقَدُّمًا، عُلُوّاً، شَأْنًا، غَلَبَةً، اِرْتِقَاءً. ""شَهِدُوا لَهُ بِالتَّفَوُّقِ فِي العِلْمِ وَالخُلُقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19326, 'تَفَوُّهٌ', 'تفوه', 'مصدر', 'فوه', 'تفوه', 'تفه', 'مص. تَفَوَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَوُّهٌ-تَفَوُّهٌ [ف و هـ] (مص. تَفَوَّهَ). ""اِحْتَرَسَ مِنَ التَّفَوُّهِ بِكَلاَمٍ بَذِيءٍ"" : مِنَ النُّطْقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19327, 'تَفَيُّشٌ', 'تفيش', 'مصدر', 'فيش', 'تفيش', 'تفش', 'مص. تَفَيَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَيُّشٌ-تَفَيُّشٌ [ف ي ش] (مص. تَفَيَّشَ). 1.""أَكْثَرَ مِنَ التَّفَيُّشِ"" : مِنَ التَّبَجُّحِ، مِنَ التَّفَاخُرِ، مِنَ التَّبَاهِي. 2.""تَفَيُّشُ عَمَلٍ"" : اِدِّعَاؤُهُ بَاطِلاً مِنْ غَيْرِ طَائِلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19328, 'تَقَابُلٌ', 'تقابل', 'مصدر', 'قبل', 'تقابل', 'تقبل', 'مص. تَقَابَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَابُلٌ-تَقَابُلٌ [ق ب ل] (مص. تَقَابَلَ). 1.""اِتَّفَقَا عَلَى التَّقَابُلِ فِي الْمَكْتَبِ"": عَلَى الاِلْتِقَاءِ وَجْهاً لِوَجْهٍ. 2.""تَقَابُلُ بَابَيْنِ"" : تَوَاجُهُهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19329, 'تَقَاضِي', 'تقاضي', 'مصدر', 'قضي', 'تقاضي', 'تقض', 'مص. تَقَاضَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَقَاضٍ-تَقَاضٍ، التَّقَاضِي [ق ض ي] (مص. تَقَاضَى). 1.""تَقَاضِي الْمُتَخَاصِمَيْنِ إِلَى القَاضِي"" : تَحَاكُمُهُمَا وَتَرَافُعُهُمَا إِلَيْهِ. 2.""تَقاضِي الْمُتَنازِعَيْنِ إلى القاضِي"" : تَحاكُمُهُمَا وَتَرافُعُهُما إِلَيْهِ. 3.""تَقاضِي الدَّيْنِ"" : طَلَبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19330, 'تَقَاذُفٌ', 'تقاذف', 'مصدر', 'قذف', 'تقاذف', 'تقذف', 'مص. تَقَاذَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَاذُفٌ-تَقَاذُفٌ [ق ذ ف] (مص. تَقَاذَفَ). 1.""التَّقَاذُفُ بِالْحِجَارَةِ"" : التَّرَامِي بِهَا. 2.""التَّقَاذُفُ بِال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19331, 'تَقَارُبٌ', 'تقارب', 'مصدر', 'قرب', 'تقارب', 'تقرب', 'مص. تَقَارَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَارُبٌ-تَقَارُبٌ [ق ر ب] (مص. تَقَارَبَ). 1.""لَمْ يَعُدْ بَيْنَهُمَا أَيُّ تَقَارُبٍ فِي الرَّأْيِ"" : أَيُّ تَلاَقٍ، صَارَ بَيْنَهُمَا تَبَاعُدٌ. 2.""تَقَارُبُ الْوَعْدِ"" : قُرْبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19332, 'تَقَارُصٌ', 'تقارص', 'مصدر', 'قرص', 'تقارص', 'تقرص', 'مص. تَقَارَصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَارُصٌ-تَقَارُصٌ [ق ر ص] (مص. تَقَارَصَ).""تَقَارُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19333, 'تَقَارُضٌ', 'تقارض', 'مصدر', 'قرض', 'تقارض', 'تقرض', 'مص. تَقَارَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَارُضٌ-تَقَارُضٌ [ق ر ض] (مص. تَقَارَضَ). 1. ""تَقَارُضُ الرَّفِيقَيْنِ الْمَوْقِفَ"" : تَبَادُلُهُ بَيْنَهُمَا. 2.""تَقَارُضُ الْجَارَيْنِ الثَّنَاءَ"": إِثْنَاءُ كُلٍّ مِنْهُمَا عَلَى الآ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19334, 'تَقَارُظٌ', 'تقارظ', 'مصدر', 'قرظ', 'تقارظ', 'تقرظ', 'مص. تَقَارَظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَارُظٌ-تَقَارُظٌ [ق ر ظ] (مص. تَقَارَظَ). ""تَقَارُظُ الشَّاعِرَيْنِ الْمَدْحَ"" : مَدْحُ كُلٌّ مِنْهُمَا الآخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19335, 'تَقَارُعٌ', 'تقارع', 'مصدر', 'قرع', 'تقارع', 'تقرع', 'مص. تَقَارَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَارُعٌ-تَقَارُعٌ [ق رع] (مص. تَقَارَعَ). 1.""التَّقَارُعُ بِالْعِصِيِّ"": مُضَارَبَةُ بَعْضِهِمْ بَعْضاً بِالْعِصِيِّ. 2.""تَقَارُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19336, 'تَقَارُنٌ', 'تقارن', 'مصدر', 'قرن', 'تقارن', 'تقرن', 'مص. تَقَارَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَارُنٌ-تَقَارُنٌ [ق ر ن] (مص. تَقَارَنَ).1.""تَقَارُنُ الرَّفِيقَيْنِ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19337, 'تَقَاسُمٌ', 'تقاسم', 'مصدر', 'قسم', 'تقاسم', 'تقسم', 'مص. تَقَاسَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَاسُمٌ-تَقَاسُمٌ [ق س م] (مص. تَقَاسَمَ). 1.""تَقَاسُمُ الإرْثِ"": تَقْسِيمُهُ، تَوْزِيعُهُ، أَخْذُ النَّصِيبِ. 2.""تَقَاسُمُ الْقَوْمِ"" : تَحَالُفُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19338, 'تَقَاصُفٌ', 'تقاصف', 'مصدر', 'قصف', 'تقاصف', 'تقصف', 'مص. تَقَاصَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَاصُفٌ-تَقَاصُفٌ [ق ص ف] (مص. تَقَاصَفَ). ""تَقَاصُفُ النَّاسِ عَلَى الْمَقْصِفِ"" : اِجْتِمَاعُهُمْ، اِزْدِحَامُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19339, 'تَقايُضٌ', 'تقايض', 'مصدر', 'قيض', 'تقايض', 'تقض', 'مص. تَقايَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقايُضٌ-تَقايُضٌ[ق ي ض] (مص. تَقايَضَ). ""تَقايُضُ التَّاجِرَيْنِ البَضائِعَ"" : تَبادُلُها، تَعاوُضُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19340, 'تَقاطُرٌ', 'تقاطر', 'مصدر', 'قطر', 'تقاطر', 'تقطر', 'مص. تَقاطَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقاطُرٌ-تَقاطُرٌ [ق ط ر] (مص. تَقاطَرَ). 1.""تَقاطُرُ الماءِ"" : سَيَلانُهُ قَطْرَةً قَطْرَةً. 2.""تَقاطُرُ الدَّمِ"" : نَزْفُهُ قَطْرَةً قَطْرَةً. 3.""تَقاطُرُ الجُمْهورِ"" : تَوافُدُهُ بِكَثْرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19341, 'تَقاطُعٌ', 'تقاطع', 'مصدر', 'قطع', 'تقاطع', 'تقطع', 'مص. تَقاطَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقاطُعٌ-تَقاطُعٌ [ق ط ع] (مص. تَقاطَعَ). 1.""تَقاطُعُ الصَّدِيقَيْنِ"" : هَجْرُ أَحَدِهِما الآخَرَ. 2.""تَوَقَّفَ القِطارُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19342, 'تَقاعُدٌ', 'تقاعد', 'مصدر', 'قعد', 'تقاعد', 'تقعد', 'مص. تَقاعَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقاعُدٌ-تَقاعُدٌ [ق ع د] (مص. تَقاعَدَ). 1.""التَّقاعُدُ عَنِ القِيامِ بأُمُورِهِ"" : عَدَمُ الاهْتِمامِ بِهَا. 2.""بَلَغَ الْمُوَظَّفُ سِنَّ التَّقاع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19343, 'تَقاعُسٌ', 'تقاعس', 'مصدر', 'قعس', 'تقاعس', 'تقعس', 'مص. تَقاعَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقاعُسٌ-تَقاعُسٌ [ق ع س] (مص. تَقاعَسَ). ""الكُلُّ يَتَساءلُ عَنِ "', '');
