INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19345, 'تَقامُرٌ', 'تقامر', 'مصدر', 'قمر', 'تقامر', 'تقمر', 'مص. تَقامَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقامُرٌ-تَقامُرٌ [ق م ر] (مص. تَقامَرَ). ""نَهاهُمْ عَنِ التَّقامُرِ"" : عَنْ لَعِبِ القِمارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19346, 'تَقاوُلٌ', 'تقاول', 'مصدر', 'قول', 'تقاول', 'تقل', 'مص. تَقاوَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقاوُلٌ-تَقاوُلٌ [ق و ل] (مص. تَقاوَلَ). تَقاوُلُ الْمُقاوِلِينَ في المقاولاتِ"" : تَفاوُضُهُمْ فيها، تَباحُثُهُمْ."', '');
