INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19349, 'تَقَرُّبٌ', 'تقرب', 'مصدر', 'قرب', 'تقرب', 'تقرب', 'مص. تَقَرَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَرُّبٌ-تَقَرُّبٌ [ق ر ب] (مص. تَقَرَّبَ). 1.""أَرادَ التَّقَرُّبَ إِلَيْهِ طَمَعاً في مالِهِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19350, 'تَقايُلٌ', 'تقايل', 'مصدر', 'قيل', 'تقايل', 'تقل', 'مص. تَقايَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقايُلٌ-تَقايُلٌ [ق ي ل] (مص. تَقايَلَ). ""تَقايُلُ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19351, 'تَقَبُّبٌ', 'تقبب', 'مصدر', 'قبب', 'تقبب', 'تقب', 'مص. تَقَبَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَبُّبٌ-تَقَبُّبٌ [ق ب ب] (مص. تَقَبَّبَ). ""تَقَبُّبُ الرَّجُلِ القُبَّةَ"" : دُخولُهُ إِيَّاها."', '');
