INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19353, 'تَقَبُّلٌ', 'تقبل', 'مصدر', 'قبل', 'تقبل', 'تقبل', 'مص. تَقَبَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَبُّلٌ-تَقَبُّلٌ [ق ب ل] (مص. تَقَبَّلَ). 1.""تَقَبُّلُ أَمْرٍ"" : قَبولُهُ، التَّسْلِيمُ بِهِ، الرِّضا بِهِ. 2.""تَقَبُّلُ الدُّعاءِ"" : الاِسْتِجابَةُ لَهُ."', '');
