INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19356, 'تَقَدُّرٌ', 'تقدر', 'مصدر', 'قدر', 'تقدر', 'تقدر', 'مص. تَقَدَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَدُّرٌ-تَقَدُّرٌ [ق د ر] (مص. تَقَدَّرَ). 1.""تَقَدُّرُ الأمْرِ عَلَيْهِ"', '');
