INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19358, 'تَقَدُّمٌ', 'تقدم', 'مصدر', 'قدم', 'تقدم', 'تقدم', 'مص. تَقَدَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَقَدُّمٌ-تَقَدُّمٌ [ق د م] (مص. تَقَدَّمَ). 1.""أَحْرَزَ تَقَدُّماً مَلْموساً في عَمَلِهِ"" : تَحَسُّناً، تَدَرُّجاً. 2.""وَقَفَ على تَقَدُّمِ الأعْمالِ"" : على سَيْرِها. 3.""حَقَّقَتِ البِلادُ تَقَدُّماً اِقْتِصادِيّاً "', '');
