INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19360, 'تَقَرُّرٌ', 'تقرر', 'مصدر', 'قرر', 'تقرر', 'تقر', 'مص. تَقَرَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَرُّرٌ-تَقَرُّرٌ [ق ر ر] (مص. تَقَرَّرَ). ""تَقَرُّرُ الاجْتِماعِ"" : ثُبوتُهُ، تَأكُّدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19361, 'تَقَرْفُصٌ', 'تقرفص', 'مصدر', 'قرف', 'تقرفص', 'تقرفص', 'مص. تَقَرْفَصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَرْفُصٌ-تَقَرْفُصٌ [ق ر ف] (مص. تَقَرْفَصَ). ""تَقَرْفُصُ الشَّيْخِ"": تَلَفُّفُهُ في ثَوْبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19362, 'تَقَزُّزٌ', 'تقزز', 'مصدر', 'قزز', 'تقزز', 'تقز', 'مص. تَقَزَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَزُّزٌ-تَقَزُّزٌ [ق ز ز] (مص. تَقَزَّزَ). ""التَّقَزُّزُ مِنْ رائِحَةٍ كَريهَةٍ"" : الاشْمِئْزازُ مِنْها..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19363, 'تَقَسُّمٌ', 'تقسم', 'مصدر', 'قسم', 'تقسم', 'تقسم', 'مص. تَقَسَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَسُّمٌ-تَقَسُّمٌ [ق س م] (مص. تَقَسَّمَ). 1.""تَقَسُّمُ الجَماعةِ"" : تَفَرُّقُها. 2.""تَقَسُّمُ الإِرْثِ بَيْنَ الأَبْنَاءِ"" : تَوْزيعُهُ ، تَقْسيمُهُ كُلٌّ وَنَصِيبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19364, 'تَقَشُّرٌ', 'تقشر', 'مصدر', 'قشر', 'تقشر', 'تقشر', 'مص. تَقَشَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَشُّرٌ-تَقَشُّرٌ [ق ش ر] (مص. تَقَشَّرَ). ""تَقَشُّرُ الجِلْدِ"" : زَوالُ قِشْرَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19365, 'تَقَشُّطٌ', 'تقشط', 'مصدر', 'قشط', 'تقشط', 'تقشط', 'مص. تَقَشَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَشُّطٌ-تَقَشُّطٌ [ق ش ط] (مص. تَقَشَّطَ). ""تَقَشُّطُ السَّماءِ"" : صَحْوُها وزَوالُ غَيْمِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19366, 'تَقَشُّعٌ', 'تقشع', 'مصدر', 'قشع', 'تقشع', 'تقشع', 'مص. تَقَشَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَشُّعٌ-تَقَشُّعٌ [ق ش ع] (مص. تَقَشَّعَ). ""تَقَشُّعُ السَّحابِ"" : زوالُهُ اِنْكِشَافُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19367, 'تَقَشُّفٌ', 'تقشف', 'مصدر', 'قشف', 'تقشف', 'تقشف', 'مص. تَقَشَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَشُّفٌ-تَقَشُّفٌ [ق ش ف] (مص. تَقَشَّفَ). 1.""يَعيشُ في تَقَشُّفٍ شَديدٍ"" : في زُهْدٍ، بَساطَةٍ في العَيْشِ وَانْصِرافٍ عَنِ الْمَلَذَّاتِ والتَّنَعُّمِ. 2.""دَخَلَتِ البِلادُ في مَرْحَلَةِ التَّقَشُّفِ"" : أَيْ تَرْكُ الإِسْرَافِ والاسْتِهْلاكِ والاكْتِفاءُ بِما هُوَ ضَرُورِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19368, 'تَقَصُّدٌ', 'تقصد', 'مصدر', 'قصد', 'تقصد', 'تقصد', 'مص. تَقَصَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَصُّدٌ-تَقَصُّدٌ [ق ص د] (مص. تَقَصَّدَ). 1.""تَقَصُّدُ العودِ"" : تَكَسُّرُهُ. 2.""تَقَصُّدُ فُلاَنٍ"" : قَصْدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19369, 'تَقَلُّدٌ', 'تقلد', 'مصدر', 'قلد', 'تقلد', 'تقلد', 'مص. تَقَلَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَلُّدٌ-تَقَلُّدٌ [ق ل د] (مص. تَقَلَّدَ). 1.""تَقَلُّدُ السَّيْفِ"" : وَضْعُ حِمالَتِهِ على الكَتِفِ. 2.""تَقَلُّدُ القِلاَدِةِ"" : وَضْعُها في العُنُقِ، لَبْسُها. 3.""تَقَلُّدُ مَنْصِبٍ"" : تَوَلِّيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19370, 'تَقَصُّفٌ', 'تقصف', 'مصدر', 'قصف', 'تقصف', 'تقصف', 'مص. تَقَصَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَصُّفٌ-تَقَصُّفٌ [ق ص ف] (مص. تَقَصَّفَ). 1.""تَقَصُّفُ العودِ"" : تَكَسُّرُهُ. 2.""تَقَصُّفُ القَوْمِ عَلَيْهِ"" : اِجْتِماعُهُمْ، اِزْد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19371, 'تَقَصِّي', 'تقصي', 'مصدر', 'قصو', 'تقصي', 'تقص', 'مص. تَقَصَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَقَصٍّ-تَقَصٍّ، التَّقَصِّي [ق ص و] (مص. تَقَصَّى). ""تَكَوَّنَتْ لَجْنَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19372, 'تَقَضُّبٌ', 'تقضب', 'مصدر', 'قضب', 'تقضب', 'تقضب', 'مص. تَقَضَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَضُّبٌ-تَقَضُّبٌ [ق ض ب] (مص. تَقَضَّبَ). 1.""تَقَضُّبُ القَضِيبِ"" : تَقَطُّعُهُ. 2.""تَقَضُّبُ الشَّمْسِ"" : اِمْتِدادُ شُعاعِها كالقُضْبانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19373, 'تَقَضِّي', 'تقضي', 'مصدر', 'قضي', 'تقضي', 'تقض', 'مص. تَقَضَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَقَضٍّ-تَقَضٍّ، التَّقَضِّي [ق ض ي] (مص. تَقَضَّى). 1.""تَقَضِّي العُمْرِ"" : اِنْقِضاؤُهُ، اِنْقِطاعُهُ. 2.""تَقَضِّي الحَيَوانِ على فَريسَتِهِ"" : اِنْقِضاضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19374, 'تَقَطُّرٌ', 'تقطر', 'مصدر', 'قطر', 'تقطر', 'تقطر', 'مص. تَقَطَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَطُّرٌ-تَقَطُّرٌ [ق ط ر] (مص. تَقَطَّرَ). 1.""تَقَطُّرُ الماءِ"" : اِنْسِيابُهُ قَطْرَةً قَطْرَةً. 2.""التَّقَطُّرُ عَنِ الْمَوْعَدِ"" : التَّأَخُّرُ، التَّخَلُّفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19375, 'تَقَطُّعٌ', 'تقطع', 'مصدر', 'قطع', 'تقطع', 'تقطع', 'مص. تَقَطَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَطُّعٌ-تَقَطُّعٌ [ق ط ع] (مص. تَقَطَّعَ). 1.""تَقَطُّعُ الحَبْلِ"" : اِنْفِكاكُهُ، اِنْحِلالُهُ. 2.""تَقَطُّعُ القَلْبِ حُزْناً"" : تَلَوِّيهِ. 3."""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19376, 'تَقَعُّرٌ', 'تقعر', 'مصدر', 'قعر', 'تقعر', 'تقعر', 'مص. تَقَعَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَعُّرٌ-تَقَعُّرٌ [ق ع ر] (مص. تَقَعَّرَ). 1.""تَقَعُّرُ الرَّجُلِ"" : اِنْصِراعُهُ، اِنْقِلابُهُ. 2."""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19377, 'تَقَفِّي', 'تقفي', 'مصدر', 'قفو', 'تقفي', 'تقف', 'مص. تَقَفَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَقَفٍّ-تَقَفٍّ، التَّقَفِّي [ق ف و] (مص. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19378, 'تَقَلُّبٌ', 'تقلب', 'مصدر', 'قلب', 'تقلب', 'تقلب', 'مص. تَقَلَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. تَقَلَّبَ). 1.""لاَيَسْتَقِرُّ على رَأْيٍ، هُوَ فِي تَقَلُّبٍ دائِمٍ"" : تَبَدُّلٍ، تَغَيُّرٍ، تَحَوُّلٍ. ""عَرَفَ الجَوُّ تَقَلُّباً"". 2.""تَقَلُّباتُ الدَّهْرِ"" : أَهْوالُهُ، أَحْوالُهُ، ظُروفُهُ. 3.""التَّقَلُّبُ في الوَظائِفِ"" : الاِنْتِقالُ مِن وَظيفَةٍ إلى أُخرَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19379, 'تَقَوُّتٌ', 'تقوت', 'مصدر', 'قوت', 'تقوت', 'تقت', 'مص. تَقَوَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَوُّتٌ-تَقَوُّتٌ [ق و ت] (مص. تَقَوَّتَ). ""التَّقَوُّتُ بِالنَّباتاتِ"": الاقْتِياتُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19380, 'تَقَلُّصٌ', 'تقلص', 'مصدر', 'قلص', 'تقلص', 'تقلص', 'مص. تَقَلَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَلُّصٌ-تَقَلُّصٌ [ق ل ص] (مص. تَقَلَّصَ). 1.""تَقَلُّصُ الثَّوْبِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19381, 'تَقَلُّعٌ', 'تقلع', 'مصدر', 'قلع', 'تقلع', 'تقلع', 'مص. تَقَلَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَلُّعٌ-تَقَلُّعٌ [ق ل ع] (مص. تَقَلَّعَ). ""تَقَلُّعُ الجِذْرِ"" : اِنْتِزاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19382, 'تَقَلْقُلٌ', 'تقلقل', 'مصدر', 'قلقل', 'تقلقل', 'تقلقل', 'مص. تَقَلْقَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَلْقُلٌ-تَقَلْقُلٌ [ق ل ق ل] (مص. تَقَلْقَلَ). 1.""تَقَلْقُلُ القِرْبَةِ"": ت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19383, 'تَقَلِّي', 'تقلي', 'مصدر', 'قلو', 'تقلي', 'تقل', 'مص. تَقَلَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَقَلٍّ-تَقَلٍّ، التَّقَلِّي [ق ل و] (مص. تَقَلَّى). ""تَقَلِّي الْمَرِيضِ"": تَمَلْمُلُهُ يَمْنَةً وَيَسْرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19384, 'تَقَمُّصٌ', 'تقمص', 'مصدر', 'قمص', 'تقمص', 'تقمص', 'مص. تَقَمَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَمُّصٌ-تَقَمُّصٌ [ق م ص] (مص. تَقَمَّصَ). 1.""تَقَمُّصُ القَميصِ"" : لُبْسُهُ. 2.""مُمَثِّلٌ نَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19385, 'تَقَمُّمٌ', 'تقمم', 'مصدر', 'قمم', 'تقمم', 'تقم', 'مص. تَقَمَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَمُّمٌ-تَقَمُّمٌ [ق م م] (مص. تَقَمَّمَ). 1.""تَقَمُّمُ الجَبَلِ"" : الصُّعودُ إلى قِمَّتِهِ. 2.""تَقَمُّم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19386, 'تَقَنُّصٌ', 'تقنص', 'مصدر', 'قنص', 'تقنص', 'تقنص', 'مص. تَقَنَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَنُّصٌ-تَقَنُّصٌ [ق ن ص] (مص. تَقَنَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19387, 'تَقَنُّعٌ', 'تقنع', 'مصدر', 'قنع', 'تقنع', 'تقنع', 'مص. تَقَنَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَنُّعٌ-تَقَنُّعٌ [ق ن ع] (مص. تَقَنَّعَ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19388, 'تَقَهْقُرٌ', 'تقهقر', 'مصدر', 'قهق', 'تقهقر', 'تقهقر', 'مص. تَقَهْقَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَهْقُرٌ-تَقَهْقُرٌ [ق هـ ق] (مص. تَقَهْقَرَ). 1.""تَقَهْقُرُ الجَيْشِ عَلامَةٌ على انْهِزامِهِ"" : تَراجُعُهُ إلى الوَراءِ مَهْزوماً. 2.""تَقَهْقُرُ الوَضْعِ الاجْتِماعِيِّ"" : إِصابَتُهُ بالضَّعْفِ والْوَهَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19389, 'تَقَيُّضٌ', 'تقيض', 'مصدر', 'قيض', 'تقيض', 'تقض', 'مص. تَقَيَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَيُّضٌ-تَقَيُّضٌ [ق ي ض] (مص. تَقَيَّضَ). 1.""تَقَيُّضُ الجِدارِ"": تَهَدُّمُهُ. 2.""تَقَيُّضُ البَيْضَةِ"" : تَكَسُّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19390, 'تَقَوُّسٌ', 'تقوس', 'مصدر', 'قوس', 'تقوس', 'تقس', 'مص. تَقَوَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَوُّسٌ-تَقَوُّسٌ [ق و س] (مص. تَقَوَّسَ). ""تَقَوُّسُ الظَّهْرِ"" : صَيْرُهُ كالقَوْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19391, 'تَقَوُّضٌ', 'تقوض', 'مصدر', 'قوض', 'تقوض', 'تقض', 'مص. تَقَوَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَوُّضٌ-تَقَوُّضٌ [ق و ض] (مص. تَقَوَّضَ). 1.""تَقَوُّضُ الجُدْرانِ"" : تَهَدُّمُها، اِنْهِدامُها. 2.""تَقَوُّضُ الأرْكانِ"" : تَحَطُّمُها، تَفَرُّقُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19392, 'تَقَوُّلٌ', 'تقول', 'مصدر', 'قول', 'تقول', 'تقل', 'مص. تَقَوَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَوُّلٌ-تَقَوُّلٌ [ق و ل] (مص. تَقَوَّلَ). ""كُلُّ ما جاءَ في كَلامِهِ مُجَرَّدُ تَقَوُّلٍ"": مُجَرَّدُ افْتِرَاءٍ وَكَذِبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19393, 'تَقَوُّمٌ', 'تقوم', 'مصدر', 'قوم', 'تقوم', 'تقم', 'مص. تَقَوَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَوُّمٌ-تَقَوُّمٌ [ق و م] (مص. تَقَوَّمَ). 1.""تَقَوُّمُ الطَّريقِ"" : اِسْتِقامتُهُ، اِسْتِواؤُهُ. 2.""تَقَوُّمُ الخَطِّ الْمُنْعَرِجِ"" : زَوالُ اعْوِجاجِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19394, 'تَقَوِّي', 'تقوي', 'مصدر', 'قوي', 'تقوي', 'تق', 'مص. تَقَوَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R0', '', '', '', '', '', '', '"تَقَوٍّ-تَقَوٍّ، التَّقَوِّي [ق و ي] (مص. تَقَوَّى). ""تَقَوِّي مَرْكَزِهِ"" : صَيْرُهُ ذا مَكانَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19395, 'تَقِيَّةٌ', 'تقية', 'مصدر', 'وقي', 'تقية', 'تقة', 'مص. تَقَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَقِيَّةٌ-تَقِيَّةٌ [و ق ي] (مص. تَقَى). 1.""بِهِ تَقِيَّةٌ"" : خَوْفٌ. 2.""اِنْتَهَى بِهِ مَذْهَبُهُ إلى التَّقِيَّةِ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19396, 'تَقَيُّؤٌ', 'تقيؤ', 'مصدر', 'قيأ', 'تقيء', 'تق', 'مص. تَقَيَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَقَيُّؤٌ-تَقَيُّؤٌ [ق ي أ] (مص. تَقَيَّأَ). ""سَبَّبَ لَهُ التَّسَمُّمُ التَّقَيُّؤَ"": إِلْقاءُ ما في البَطْنِ مِنَ الطَّعامِ، إِخْراجُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19397, 'تَقَيُّحٌ', 'تقيح', 'مصدر', 'قيح', 'تقيح', 'تقح', 'مص. تَقَيَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَيُّحٌ-تَقَيُّحٌ [ق ي ح] (مص. تَقَيَّحَ). ""تَقَيُّحُ الدُّمَّلَةِ"" : سَيَلانُ ما فيها مِنْ قَيْحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19398, 'تَقَيُّدٌ', 'تقيد', 'مصدر', 'قيد', 'تقيد', 'تقد', 'مص. تَقَيَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَيُّدٌ-تَقَيُّدٌ [ق ي د] (مص. تَقَيَّدَ). 1.""لَمْ يَبْقَ أَمامَهُ إِلاَّ التَّقَيُّدُ بِالقانونِ"" : أَي الامْتِثالُ، الاِلْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19399, 'تَقَيُّفٌ', 'تقيف', 'مصدر', 'قيف', 'تقيف', 'تقف', 'مص. تَقَيَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَيُّفٌ-تَقَيُّفٌ [ق ي ف] (مص. تَقَي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19400, 'تَقَيُّلٌ', 'تقيل', 'مصدر', 'قيل', 'تقيل', 'تقل', 'مص. تَقَيَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَيُّلٌ-تَقَيُّلٌ [ق ي ل] (مص. تَقَيَّلَ). ""تَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19401, 'تَقَيُّنٌ', 'تقين', 'مصدر', 'قين', 'تقين', 'تقن', 'مص. تَقَيَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقَيُّنٌ-تَقَيُّنٌ [ق ي ن] (مص. تَقَيَّنَ). 1.""تَقَيُّنُ المرأَةِ"" : تَزَيُّنُها. 2.""تَقَيُّنُ النَّباتِ"" : حُسْنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19402, 'تَكابُرٌ', 'تكابر', 'مصدر', 'كبر', 'تكابر', 'تكبر', 'مص. تَكَابَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكابُرٌ-تَكابُرٌ [ك ب ر] (مص. تَكَابَرَ). 1.""يَتَعامَلُ مَعَ النَّاسِ بِتَكابُرٍ"" : بِتَكَبُّرٍ وَكِبْرِياءٍ. 2.""التَّكابُرُ في السِّنِّ"" : إِظْهارُ الكِبَرِ في السِّنِّ. 3.""التَّكَابُرُ بَيْنَ النَّاسِ"": التَّظَاهُرُ بِالْمَكَانَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19403, 'تَكاتُبٌ', 'تكاتب', 'مصدر', 'كتب', 'تكاتب', 'تكتب', 'مص. تَكاتَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكاتُبٌ-تَكاتُبٌ [ك ت ب] (مص. تَكاتَبَ). ""اِتَّفَقا على التَّكاتُبِ"" : على الْمُراسَلَةِ، أَيْ أَنْ يُراسِلَ أَحَدُهُما الآخَر."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19404, 'تَكاتُفٌ', 'تكاتف', 'مصدر', 'كتف', 'تكاتف', 'تكتف', 'مص. تَكاتَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكاتُفٌ-تَكاتُفٌ [ك ت ف] (مص. تَكاتَفَ). ""تَكاتُفُ الجُهودِ"": تَعاوُنُها، تَضامُنُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19405, 'تَكاتُمٌ', 'تكاتم', 'مصدر', 'كتم', 'تكاتم', 'تكتم', 'مص. تَكاتَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكاتُمٌ-تَكاتُمٌ [ك ت م] (مص. تَكاتَمَ). ""تَكاتُمُ السِّرِّ"" : كِتْمانُهُ، إِخْفاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19406, 'تَكاثُرٌ', 'تكاثر', 'مصدر', 'كثر', 'تكاثر', 'تكثر', 'مص. تَكاثَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكاثُرٌ-تَكاثُرٌ [ك ث ر] (مص. تَكاثَرَ). ""تَكاثُرُ السُّكَّانِ"" : تَزايُدُ عَدَدِهِمْ، تَنامِيهِمْ. ""تَكاثُرُ الحَشَراتِ""الحديد آية 20 وَتَكاثُرٌ فِي الأمْوالِ والأوْلادِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19407, 'تَكاثُفٌ', 'تكاثف', 'مصدر', 'كثف', 'تكاثف', 'تكثف', 'مص. تَكاثَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكاثُفٌ-تَكاثُفٌ [ك ث ف] (مص. تَكاثَفَ). 1.""تَكاثُفُ اللَّبَنِ"" : ت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19408, 'تَكاذُبٌ', 'تكاذب', 'مصدر', 'كذب', 'تكاذب', 'تكذب', 'مص. تَكاذَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكاذُبٌ-تَكاذُبٌ [ك ذ ب] (مص. تَكاذَبَ).""تَكاذُبُ النَّاسِ"": كَذِبُ بَعْضِهِمْ على بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19409, 'تَكارُهٌ', 'تكاره', 'مصدر', 'كره', 'تكاره', 'تكره', 'مص. تَكارَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكارُهٌ-تَكارُهٌ [ك ر هـ] (مص. تَكارَهَ). ""تَكارُهُ الشَّيْءِ"" : كُرْهُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19410, 'تَكاسُلٌ', 'تكاسل', 'مصدر', 'كسل', 'تكاسل', 'تكسل', 'مص. تَكاسَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكاسُلٌ-تَكاسُلٌ [ك س ل] (مص. تَكاسَلَ). ""تَكاس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19411, 'تَكاشُفٌ', 'تكاشف', 'مصدر', 'كشف', 'تكاشف', 'تكشف', 'مص. تَكَاشَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكاشُفٌ-تَكاشُفٌ [ك ش ف] (مص. تَكَاشَفَ). ""تَكاشُفُ الن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19412, 'تَكافُؤٌ', 'تكافؤ', 'مصدر', 'كفأ', 'تكافء', 'تكف', 'مص. تَكافَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَكافُؤٌ-تَكافُؤٌ [ك ف أ] (مص. تَكافَأَ). 1.""قُوَّةُ الفَريقَيْنِ في تَكافُؤٍ"" : في تَساوٍ. 2.""تَكافُؤُ الفُرَصِ"" : تَساوِيها حَسَبَ كِفايَةِ مَنْ يَرْغَبُ فيها. 3.""تَكافُؤُ الْمُرَبَّعِ والْمُسْتَطيلِ مِساحَةً"": لَهُما المِساحَةُ نَفْسُها دونَ أَنْ يَنْطَبِقَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19413, 'تَكافُحٌ', 'تكافح', 'مصدر', 'كفح', 'تكافح', 'تكفح', 'مص. تَكافَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكافُحٌ-تَكافُحٌ [ك ف ح] (مص. تَكافَحَ). ""تَكافُحُ الْمُتَقاتِلينَ"": تَضارُبُهُمْ وَجْهاً لِوَجْهٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19414, 'تَكافُلٌ', 'تكافل', 'مصدر', 'كفل', 'تكافل', 'تكفل', 'مص. تَكافَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكافُلٌ-تَكافُلٌ [ك ف ل] (مص. تَكافَلَ). ""اِتَّفَقا على التَّكافُلِ"": ضَمانُ، كَفالَةُ أَحَدِهِما الآخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19415, 'تَكالُبٌ', 'تكالب', 'مصدر', 'كلب', 'تكالب', 'تكلب', 'مص. تَكالَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكالُبٌ-تَكالُبٌ [ك ل ب] (مص. تَكالَبَ). 1.""تَكالُبُ الأعْداءِ"" : إِظْهارُ العَداوَةِ لِبَعْضِهِمْ، التَّجاهُرُ بِها. 2.""التَّكالُبُ على المالِ"" : التَّسارُعُ، التَّواثُبُ عَلَيْهِ طَمَعاً، التَّهافُتُ حِرْصاً وَطَمَعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19416, 'تَكامُلٌ', 'تكامل', 'مصدر', 'كمل', 'تكامل', 'تكمل', 'مص. تَكامَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكامُلٌ-تَكامُلٌ [ك م ل] (مص. تَكامَلَ). 1.""تَكامُلُ العَمَلِ"": كَوْنُهُ كامِلاً وَتامّاً. 2.""تَكامُلُ جُهودِ الأفْرادِ"" : تَكْميلُ بَعْضِهِمْ بَعْضاً. 3.""التَّكامُلُ الاقتِصادِيُّ"" : جَمْعُ كُلِّ مُكَوِّناتِ الاقْتِصادِ لِيُكَمِّلَ بَعْضُها بَعْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19417, 'تَكايُدٌ', 'تكايد', 'مصدر', 'كيد', 'تكايد', 'تكد', 'مص. تَكايَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكايُدٌ-تَكايُدٌ [ك ي د] (مص. تَكايَدَ). ""تَكايُدُ الْمُتَخاصِمينِ"": تَماكُرُهُما، اِحْتِيالُ كُلٍّ مِنْهُما عَلَى الآخَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19418, 'تَكايُلٌ', 'تكايل', 'مصدر', 'كيل', 'تكايل', 'تكل', 'مص. تَكايَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكايُلٌ-تَكايُلٌ [ك ي ل] (مص. تَكايَلَ). 1.""تَكايُلُ الرَّجُلَيْنِ"": كَيْلُ أَحَدِهِما لِلآخَرِ. 2.""تَكايُلُ العَدُوَّيْنِ"" : تَعارُضُهُما بِالشَّتْمِ أَوِ الانتِقامِ أَوِ الثَّأْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19419, 'تَكَثُّمٌ', 'تكثم', 'مصدر', 'كثم', 'تكثم', 'تكثم', 'مص. تَكَثَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَثُّمٌ-تَكَثُّمٌ [ك ث م] (مص. تَكَثَّمَ). 1.""تَكَثُّمُ الخَطيبِ"": تَوَقُّفُهُ أو تَحَيُّرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19420, 'تَكَبُّدٌ', 'تكبد', 'مصدر', 'كبد', 'تكبد', 'تكبد', 'مص. تَكَبَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَبُّدٌ-تَكَبُّدٌ [ك ب د] (مص. تَكَبَّدَ). 1. تَكَبُّدُ اللَّبَنِ"" : خَثْرُهُ. 2.""تَكَبُّدُ عَناءِ السَّفَرِ"" : تَحَمُّلُ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19421, 'تَكَبُّرٌ', 'تكبر', 'مصدر', 'كبر', 'تكبر', 'تكبر', 'مص. تَكَبَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَبُّرٌ-تَكَبُّرٌ [ك ب ر] (مص. تَكَبَّرَ). ""تَكَبُّرُ الرَّجُلِ"" : تَعَظُّمُهُ، كَوْنُهُ ذا كِبْرِياءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19422, 'تَكَبَّلَ', 'تكبل', 'مصدر', 'كبل', 'تكبل', 'تكبل', 'مص. تَكَبَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَبَّلَ-تَكَبَّلَ [ك ب ل] (مص. تَكَبَّلَ). تَكَبَّلَ، يَتَكَبَّلُ، مص. تَكَبُّلٌ. ""تَكَبَّلَ السَّجينُ"" : تَقَيَّدَ بالكَبْلِ، القَيْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19423, 'تَكَبُّلٌ', 'تكبل', 'مصدر', 'كبل', 'تكبل', 'تكبل', 'مص. تَكَبَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَبُّلٌ-تَكَبُّلٌ [ك ب ل] (مص. تَكَبَّلَ). ""تَكَبُّلُ السَّجينِ"" : تَقَيُّدُهُ بالكَبْلِ، القَيْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19424, 'تَكَتُّفٌ', 'تكتف', 'مصدر', 'كتف', 'تكتف', 'تكتف', 'مص. تَكَتَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَتُّفٌ-تَكَتُّفٌ [ك ت ف] (مص. تَكَتَّفَ). 1.""تَكَتُّفُ الْمُصَلِّي"": وَضَعَ يَدَي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19425, 'تَكْتَكَةٌ', 'تكتكة', 'مصدر', 'كتك', 'تكتكة', 'تكتكة', 'مص. تَكْتَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. تَكْتَكَ). 1.""تَكْتَكَةُ السَّاعَةِ"" : دَقَّاتُها الْمُتَوالِيَةَ، تيك تاك. ""وَفي الصَّمْتِ تُصْبِحُ تَكْتَك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19426, 'تَكَتْكُتٌ', 'تكتكت', 'مصدر', 'كتك', 'تكتكت', 'تكتكت', 'مص. تَكَتْكَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَتْكُتٌ-تَكَتْكُتٌ [ك ت ك] (مص. تَكَتْكَتَ)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19427, 'تَكَتُّلٌ', 'تكتل', 'مصدر', 'كتل', 'تكتل', 'تكتل', 'مص. تَكَتَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَتُّلٌ-تَكَتُّلٌ [ك ت ل] (مص. تَكَتَّلَ). 1.""تَكَتُّلُ الجُهودِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19428, 'تَكَثُّرٌ', 'تكثر', 'مصدر', 'كثر', 'تكثر', 'تكثر', 'مص. تَكَثَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَثُّرٌ-تَكَثُّرٌ [ك ث ر] (مص. تَكَثَّرَ). 1.""تَكَثُّرُ الْمُضيفِ"" : تَكَلُّفُهُ الكَثْرَةَ. 2.""تَكَثُّرُ الخَطيبِ بِالكَلاَمِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19429, 'تَكَرُّمٌ', 'تكرم', 'مصدر', 'كرم', 'تكرم', 'تكرم', 'مص. تَكَرَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَرُّمٌ-تَكَرُّمٌ [ك ر م] (مص. تَكَرَّمَ). 1.""تَكَرُّمُ البَخيلِ"" : تَكَلُّفُهُ الكَرَمَ. 2.""سَعَى إلى التَّكَرُّمِ عَلَيْهِ"" : التَّفَضُّلُ عَلَيْهِ بِتَكَلُّفٍ. 3.""التَّك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19430, 'تَكَحُّلٌ', 'تكحل', 'مصدر', 'كحل', 'تكحل', 'تكحل', 'مص. تَكَحَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَحُّلٌ-تَكَحُّلٌ [ك ح ل] (مص. تَكَحَّلَ). 1.""تَكَحُّلُ الْمَرْأَةِ"": وَضْعُ الكُح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19431, 'تَكَدُّرٌ', 'تكدر', 'مصدر', 'كدر', 'تكدر', 'تكدر', 'مص. تَكَدَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَدُّرٌ-تَكَدُّرٌ [ ك د ر] (مص. تَكَدَّرَ). 1. ""تَكَدُّرُ العَيْشِ"" : صَيْرُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19432, 'تَكَدُّسٌ', 'تكدس', 'مصدر', 'كدس', 'تكدس', 'تكدس', 'مص. تَكَدَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَدُّسٌ-تَكَدُّسٌ [ك د س] (مص. تَكَدَّسَ). ""تَكَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19433, 'تَكَذُّبٌ', 'تكذب', 'مصدر', 'كذب', 'تكذب', 'تكذب', 'مص. تَكَذَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَذُّبٌ-تَكَذُّبٌ [ك ذ ب] (مص. تَكَذَّبَ). 1.""تَكَذُّبُ الرَّجُلِ"": تَكَلُّفُهُ الكَذِبَ. 2.""لَم يُصَدِّقْ أَحَدٌ تَكَذُّبَهُ على صَديقِهِ"" : الاِدِّعاءُ بِأَنَّ صَديقَهُ كاذِبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19434, 'تَكَرْبُعٌ', 'تكربع', 'مصدر', 'كرب', 'تكربع', 'تكربع', 'مص. تَكَرْبَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَرْبُعٌ-تَكَرْبُعٌ [ك ر ب] (مص. تَكَرْبَعَ). ""تَكَرْبُعُ الوَلَدِ"" : سُقوطُهُ على مُؤَخَّرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19435, 'تَكَرُّرٌ', 'تكرر', 'مصدر', 'كرر', 'تكرر', 'تكر', 'مص. تَكَرَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَرُّرٌ-تَكَرُّرٌ [ك ر ر] (مص. تَكَرَّرَ). 1.""تَكَرُّرُ الأخْطاءِ"" : إِعادَةُ تَكْرارِها مِراراً. 2.""تَكَرُّرُ الْمَصائِبِ عَلَيْهِ"" : تَوالِيهَا عَلَيْهِ. 3.""تَكَرُّرُ النَّفْطِ"" : تَصْفِيَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19436, 'تَكَرُّسٌ', 'تكرس', 'مصدر', 'كرس', 'تكرس', 'تكرس', 'مص. تَكَرَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَرُّسٌ-تَكَرُّسٌ [ك ر س] (مص. تَكَرَّسَ). 1. ""تَكَرُّسُ العِلْمِ فِي ذِهْنِهِ"" : رُسُوخُهُ، ثُبُوتُهُ. 2. ""تَكَرُّسُ الزَّرْعِ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19437, 'تَكَرُّشٌ', 'تكرش', 'مصدر', 'كرش', 'تكرش', 'تكرش', 'مص. تَكَرَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَرُّشٌ-تَكَرُّشٌ[ك ر ش] (مص. تَكَرَّشَ). 1.""تَكَرُّشُ الوَجْهِ"": تَقَبُّضُ جِلْدِهِ، تَقَلُّصُهُ. 2.""تَكَرُّشُ النَّاسِ"" : تَجَمُّعُهُمْ."', '');
