INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19460, 'تَكَمُّمٌ', 'تكمم', 'مصدر', 'كمم', 'تكمم', 'تكم', 'مص. تَكَمَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَمُّمٌ-تَكَمُّمٌ [ك م م] (مص. تَكَمَّمَ). 1.""التَّكَمُّمُ بِالثِّيابِ"": التَّغَطِّي بِها. 2.""تَكَمُّمُ القِنِّينَةِ"" : سَدُّها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19461, 'تَكَنِّي', 'تكني', 'مصدر', 'كني', 'تكني', 'تكن', 'مص. تَكَنَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَكَنٍّ-تَكَنٍّ، التَّكَنِّي [ك ن ي] (مص. تَكَنَّى). ""لاَ يُريدُ التَّكَنِّيَ باسْمٍ لا يلائِمُهُ"" : التَّسَمِّي بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19462, 'تَكَهْرُبٌ', 'تكهرب', 'مصدر', 'كهر', 'تكهرب', 'تكهرب', 'مص. تَكَهْرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَهْرُبٌ-تَكَهْرُبٌ [ك هـ ر] (مص. تَكَهْرَبَ). 1.""تَكَهْرُبُ الأسْلاكِ"" : سَرَيانُ القُوَّةِ الكَهْر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19463, 'تَكَهُّفٌ', 'تكهف', 'مصدر', 'كهف', 'تكهف', 'تكهف', 'مص. تَكَهَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَهُّفٌ-تَكَهُّفٌ [ك هـ ف] (مص. تَكَهَّفَ). 1. ""تَكَهُّفُ الرَّجُلِ"" : اِكْتِهَافُهُ، أيْ لُزُومُهُ الكَهْفَ. 2. """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19464, 'تَكَهُّنٌ', 'تكهن', 'مصدر', 'كهن', 'تكهن', 'تكهن', 'مص. تَكَهَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَهُّنٌ-تَكَهُّنٌ [ك هـ ن] (مص. تَكَهَّنَ). 1.""تَكَهُّنُ الكَهَّانِ"": تَنَبُّؤُهُ، إِخْبارُهُ بِشَيْءٍ سَيَقَعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19465, 'تَكَوْثُرٌ', 'تكوثر', 'مصدر', 'كثر', 'تكوثر', 'تكثر', 'مص. تَكَوْثَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَوْثُرٌ-تَكَوْثُرٌ [ك ث ر] (مص. تَكَوْثَرَ). ""تَكَوْثُرُ الشَّيْءِ"" : كَثْرَتُهُ جِدّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19466, 'تَكَوُّرٌ', 'تكور', 'مصدر', 'كور', 'تكور', 'تكر', 'مص. تَكَوَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَوُّرٌ-تَكَوُّرٌ [ك و ر] (مص. تَكَوَّرَ). 1.""تَكَوُّرُ الوَلَدِ"" : سُقوطُهُ. 2.""تَكَوُّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19467, 'تَكَوُّنٌ', 'تكون', 'مصدر', 'كون', 'تكون', 'تكن', 'مص. تَكَوَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَوُّنٌ-تَكَوُّنٌ [ك و ن] (مص. تَكَوَّنَ). 1.""تَكَوُّنُ الجَنينِ"" : تَشَكُلُّهُ. 2.""تَكَوُّنُ الطَّالِبِ"" : تَعَلُّمُهُ، تَثَقَّفُهُ. 3.""سَاهَمَ في تَكَوُّنِ الشَّرِكَةِ"" : في تَأْسيسِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19468, 'تَكَيُّسٌ', 'تكيس', 'مصدر', 'كيس', 'تكيس', 'تكس', 'مص. تَكَيَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكَيُّسٌ-تَكَيُّسٌ [ك ي س] (مص. تَكَيَّسَ). ""تَكَيُّسُ الرَّجُلِ"": إِظْهارُ الكِياسَةِ والأناةِ والتَّظَرُّفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19469, 'تَلاحِي', 'تلاحي', 'مصدر', 'لحي', 'تلاحي', 'تلح', 'مص. تَلاحَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَلاحٍ-تَلاحٍ، التَّلاحِي [ل ح ي] (مص. تَلاحَى). 1.""تَلاحِي النَّاسِ"" : شَتْمُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19470, 'تَلٌّ', 'تل', 'مصدر', 'تلل', 'تل', 'تل', 'مص. تَلَّ', '', '', 'مفرد', 'DnN', '', '', '"تِلالٌ:تُلولٌ"', '', 'R', '', '', '', '', '', '', '"(مص. تَلَّ). ""على التَّلِّ"" : الهَضْبَةِ، الْمُرتَفَعِ مِنَ الأرْضِ قَليلا. ""رَأَى النُّورَ في دارٍ كَبيرَةٍ بُنِيَتْ مُنْعَزِلَةً فَوْقَ تَلٍّ بِأَقْصَى غَرْبِ القَرْيَةِ"". (أحمد التوفيق)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19471, 'تِلالٌ', 'تلال', 'مصدر', '', 'تلال', 'تلل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19472, 'تُلولٌ', 'تلول', 'مصدر', '', 'تلول', 'تلل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19473, 'تِلاوَةٌ', 'تلاوة', 'مصدر', 'تلو', 'تلاوة', 'تلة', 'مص. تَلا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تِلاوَةٌ-تِلاوَةٌ [ت ل و] (مص. تَلا). 1.""تِلاوَةٌ آياتٍ مِنَ القُرْآنِ الكَريمِ"" : قِراءتُها تَرْتيلاً. 2.""كِتابُ التِّلاوَةِ"" : كِتابُ القِراءةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19474, 'تَلاؤُمٌ', 'تلاؤم', 'مصدر', 'لأم', 'تلاءم', 'تلم', 'مص. تَلاءمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلاؤُمٌ-تَلاؤُمٌ [ل أ م ] (مص. تَلاءمَ). ""عاشَ في تَلاؤُمٍ وَوِفاقٍ مَعَ أَهْلِهِ وَجيرانِهِ"" : أَيْ في تَوافُقٍ، في اِنْسِجامٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19475, 'تَلاثُمٌ', 'تلاثم', 'مصدر', 'لثم', 'تلاثم', 'تلثم', 'مص. تَلاثَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلاثُمٌ-تَلاثُمٌ [ل ث م] (مص. تَلاثَمَ). ""تَلاثُمُ الصَّديقَيْنِ"" : تَقْبيلُ كُلٍّ مِنْهُما الآخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19476, 'تَلاحُظٌ', 'تلاحظ', 'مصدر', 'لحظ', 'تلاحظ', 'تلحظ', 'مص. تَلاحَظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلاحُظٌ-تَلاحُظٌ [ل ح ظ] (مص. تَلاحَظَ). 1.""تَلاحُظُ الأَوْلادِ"" : لَحْظُ بَعضِهِمْ بَعْضاً. 2.""تَلاحُظُ الأشْياءِ"" : تَشابُهُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19477, 'تَلاحُقٌ', 'تلاحق', 'مصدر', 'لحق', 'تلاحق', 'تلحق', 'مص. تَلاحَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلاحُقٌ-تَلاحُقٌ [ل ح ق] (مص. تَلاحَقَ). ""حَيَّرَهُ تَلاحُقُ الأحْداثِ"" : تَتابُعُها، تَوالِيها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19478, 'تَلاحُمٌ', 'تلاحم', 'مصدر', 'لحم', 'تلاحم', 'تلحم', 'مص. تَلاحَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلاحُمٌ-تَلاحُمٌ [ل ح م] (مص. تَلاحَمَ). 1.""تَلاحُمُ الجُنودِ في الْمَعْرَكَةِ"" : تَقاتُلُهُمْ. 2.""تَلاحُمُ العَظْمِ"" : اِلْتِصاقُهُ، تَلاؤُمُهُ، جَبْرُهُ. 3.""تَلاحُمُ الجُرْحِ"" : اِلْتِئَامُهُ. 4.""تَلاحُمُ الأفْكارِ"" : تَسَلْسُلُها، تَرابُطُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19479, 'تَلاكُمٌ', 'تلاكم', 'مصدر', 'لكم', 'تلاكم', 'تلكم', 'مص. تَلاكَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلاكُمٌ-تَلاكُمٌ [ل ك م] (مص. تَلاكَمَ). 1.""تَلاكُمُ الوَلَدَيْنِ"": لَطْمُ كُلٍّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19480, 'تَلاشِي', 'تلاشي', 'مصدر', 'لشو', 'تلاشي', 'تلش', 'مص. تَلاشَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَلاشٍ-تَلاشٍ، التَّلاشِي [ل ش و] (مص. تَلاشَى). 1.""ثِيابُهُ فِي تَلاشٍ مُسْتَمِرٍّ"" : في اهْتِراءٍ، في تَقَطُّعٍ. 2.""قُوَاهُ في تَلاشٍ"" : في اضْمِحْلالٍ، في انْحِطاطٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19481, 'تَلاصُقٌ', 'تلاصق', 'مصدر', 'لصق', 'تلاصق', 'تلصق', 'مص. تَلاصَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلاصُقٌ-تَلاصُقٌ [ل ص ق] (مص. تَلاصَقَ). ""تَلاصُقُ الوَرَقِ"": لَصْقُ بَعْضِهِ بِبَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19482, 'تَلاطُفٌ', 'تلاطف', 'مصدر', 'لطف', 'تلاطف', 'تلطف', 'مص. تَلاطَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلاطُفٌ-تَلاطُفٌ [ل ط ف] (مص. تَلاطَفَ). 1.""رَغِبَ في التَّلاطُفِ مَعَهُ"": في التَّواصُلِ والتَّصَرُّفِ مَعَهُ تَصَرُّفاً فيهِ رِقَّةٌ وَلُطْفٌ وَأُنْسٌ. 2.""تَلاطُفُ الأوْلاَدِ فيما بَيْنَهُمْ"" : مُداعَبَةُ بَعْضِهِمْ بَعْضاً. 3.""التَّلاطُفُ في العَمَلِ"" : التَّرَفُّقُ فيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19483, 'تَلاطُمٌ', 'تلاطم', 'مصدر', 'لطم', 'تلاطم', 'تلطم', 'مص. تَلاطَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلاطُمٌ-تَلاطُمٌ [ل ط م] (مص. تَلاطَمَ). 1.""تَلاطُمُ الأوْلادِ"": صَفْعُ، لَطْمُ بَعْضِهِمْ بَعْضاً. 2.""تَلاطُمُ الأمْواجِ"" : تَقاذُفُها، ضَرْبُ بَعْضِها بَعْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19484, 'تَلاعُبٌ', 'تلاعب', 'مصدر', 'لعب', 'تلاعب', 'تلعب', 'مص. تَلاعَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلاعُبٌ-تَلاعُبٌ [ل ع ب] (مص. تَلاعَبَ). 1.""التَّلاعُبُ بِالألْعابِ"" : اللَّعِبُ بِها. 2.""تَلاعُبُ الرِّيحِ بِالأوْراقِ"" : نَقْلُها مِنْ مَكانٍ إلى آخَرَ. 3.""أَرادَ التَّلاعُبَ بِشَرِيكِهِ"" : الضَّحِكَ عَلَيْهِ احْتِيالاً. 4.""التَّلاعُبُ في العَمَلِ"" : إِحْداثُ خَلَلٍ مَقْصودٍ. 5.""التَّلاعُبُ بِالكَلِماتِ"" : تَحْميلُها مَعانِيَ مُخْتَلِفَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19485, 'تَلاعُنٌ', 'تلاعن', 'مصدر', 'لعن', 'تلاعن', 'تلعن', 'مص. تَلاعَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلاعُنٌ-تَلاعُنٌ [ل ع ن] (مص. تَلاعَنَ). ""حاوَلَ أنْ يُوقِفَ تَلاعُنَهُمَا"" : سَبُّ بَعْضِهما بَعْضاً، تَشاتُمَهُما."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19486, 'تَلافِي', 'تلافي', 'مصدر', 'لفو', 'تلافي', 'تلف', 'مص. تَلافَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَلافٍ-تَلافٍ، التَّلافِي [ل ف و] (مص. تَلافَى). ""تَلافِي الأخْطاءِ"" : تَدارُكُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19487, 'تَلاقِي', 'تلاقي', 'مصدر', 'لقي', 'تلاقي', 'تلق', 'مص. تَلاقَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَلاقٍ-تَلاقٍ، التَّلاقِي [ل ق ي] (مص. تَلاقَى). 1.""عِنْدَ نُقْطَةِ التَّلاقِي"" : التَّقاطُعِ، الاِلْتِقاءِ، الاِتِّصالِ. ""على أَنَّ قِراءةَ الكُتُبِ أَبْلَغُ ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19488, 'تَلاكُزٌ', 'تلاكز', 'مصدر', 'لكز', 'تلاكز', 'تلكز', 'مص. تَلاكَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلاكُزٌ-تَلاكُزٌ [ل ك ز] (مص. تَلاكَزَ). ""تَلاكُزُ الوَلَدَيْنِ"" : لَكْزُ كُلٍّ مِنْهُما الآخَرَ، أَيْ ضَرْبُهُ بِجُمْعِ كَفِّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19489, 'تَلَبْنُنٌ', 'تلبنن', 'مصدر', 'لبن', 'تلبنن', 'تلبن', 'مص. تَلَبْنَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَبْنُنٌ-تَلَبْنُنٌ [ل ب ن] (مص. تَلَبْنَنَ). ""تَلَبْنُنُ الرَّجُلِ"" : صَيْرُهُ لُبْنانِيّاً أو اِدِّعاؤُهُ أَنه لُبْنانِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19490, 'تَلاكُنٌ', 'تلاكن', 'مصدر', 'لكن', 'تلاكن', 'تلكن', 'مص. تَلاكَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلاكُنٌ-تَلاكُنٌ [ل ك ن] (مص. تَلاكَنَ). ""التَّلاكُنُ في الكَلامِ"": إِظْهارُ اللُّكْنَةِ لإِضْحاكِ النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19491, 'تَلأْلُؤٌ', 'تلألؤ', 'مصدر', 'لألأ', 'تلءلء', 'تلل', 'مص. تَلأْلأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَلأْلُؤٌ-تَلأْلُؤٌ [ل أ ل أ] (مص. تَلأْلأَ). 1.""تَلأْلُؤُ النَّجْمِ"" : لَمَعانُهُ. 2.""تَلأْلُؤُ الوَجْهِ فَرَحاً"" : إِشْراقُهُ. 3.""تَلأْلُؤُ النِّيرانِ"" : اِتِّقادُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19492, 'تَلاوُمٌ', 'تلاوم', 'مصدر', 'لوم', 'تلاوم', 'تلم', 'مص. تَلاوَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلاوُمٌ-تَلاوُمٌ [ل و م] (مص. تَلاوَمَ). ""اِشْتَدَّ تَلاوُمُهُمَا"" : لَوْمُ أَحَدِهِما الآخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19493, 'تَلاوِي', 'تلاوي', 'مصدر', 'لوي', 'تلاوي', 'تل', 'مص. تَلاوَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَلاوٍ-تَلاوٍ، التَّلاوِي [ل و ي] (مص. تَلاوَى). 1.""تَلاوِي النَّاسِ عَلَيْهِ"" : اِجْتِماعُهُمْ عَلَيْهِ. 2.""تَلاوِي الحَيَّتَيْنِ"" : اِسْتِدارُ، اِلْتِواءُ إِحْداهُما عَلَى الأخْرَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19494, 'تَلَبُّبٌ', 'تلبب', 'مصدر', 'لبب', 'تلبب', 'تلب', 'مص. تَلَبَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَبُّبٌ-تَلَبُّبٌ [ل ب ب] (مص. تَلَبَّبَ). 1.""تَلَبُّبُ الْمُتَخاصِمَيْنِ"" : أَخْذُ كُلِّ واحِدٍ مِنْهُما بِعُنُقِ الآخَرِ. 2.""تَلَبُّبُ الْمُقاتِلِ"" : تَحَزُّمُهُ لِلْقِتالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19495, 'تَلَبُّثٌ', 'تلبث', 'مصدر', 'لبث', 'تلبث', 'تلبث', 'مص. تَلَبَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَبُّثٌ-تَلَبُّثٌ [ل ب ث] (مص. تَلَبَّثَ). ""التَّلَبُّثُ بِالْمَكانِ"" : الإِقامَةُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19496, 'تَلَبُّدٌ', 'تلبد', 'مصدر', 'لبد', 'تلبد', 'تلبد', 'مص. تَلَبَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَبُّدٌ-تَلَبُّدٌ [ل ب د] (مص. تَلَبَّدَ). 1.""تَلَبُّدُ الصُّوفِ"": لَزْقُ أَجْزاءِ بَعْضِهِ بِبَعْضٍ. 2.""تَلَبُّدُ السَّماءِ بِالغُيومِ"" : تَغَطِّيها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19497, 'تَلَبُّسٌ', 'تلبس', 'مصدر', 'لبس', 'تلبس', 'تلبس', 'مص. تَلَبَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَبُّسٌ-تَلَبُّسٌ [ل ب س] (مص. تَلَبَّسَ). 1.""التَّلَبُّسُ بِاللِّباسِ"": لِبْسُهُ. 2.""تَلَبُّسُ الأمْرِ عَلَيْهِ"" : اِخْتِلاطُهُ وَتَداخُلُهُ، اِلْتِباسُهُ. 3.""تَلَبُّسُ الشَّوْكِ بِالثَّوْبِ"" : عَلَقُهُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19498, 'تَلَبُّكٌ', 'تلبك', 'مصدر', 'لبك', 'تلبك', 'تلبك', 'مص. تَلَبَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَبُّكٌ-تَلَبُّكٌ [ل ب ك] (مص. تَلَبَّكَ). 1.""تَلَبُّكُ الأمْرِ"" : اِخْتِلاطُهُ، إِشْكالُهُ. 2.""تَلَبُّكُ الْمَعِدَةِ"" : عُسْرُ هَضْمِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19499, 'تَلَثُّمٌ', 'تلثم', 'مصدر', 'لثم', 'تلثم', 'تلثم', 'مص. تَلَثَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَثُّمٌ-تَلَثُّمٌ [ل ث م] (مص. تَلَثَّمَ). ""تَلَثُّمُ الْمَرْأَةِ"" : وَضْعُ اللِّثامِ على أَنْفِها أَوْ فَمِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19500, 'تَلَجُّجٌ', 'تلجج', 'مصدر', 'لجج', 'تلجج', 'تلج', 'مص. تَلَجَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَجُّجٌ-تَلَجُّجٌ [ل ج ج] (مص. تَلَجَّجَ). ""تَلَجُّجُ مَتاعِ الغَيْرِ"": اِدِّعاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19501, 'تَلَجْلُجٌ', 'تلجلج', 'مصدر', 'لجلج', 'تلجلج', 'تلجلج', 'مص. تَلَجْلَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَجْلُجٌ-تَلَجْلُجٌ [ل ج ل ج] (مص. تَلَجْلَجَ). 1.""تَلَجْلُجُ الخَطيبِ"" : تَرَدُّدُهُ في الكَلامِ وَعَدَمُ تَبْيانِهِ، تَلَعْثُمُهُ، عَدَمُ إِفْصاحِهِ. 2.""تَلَجْلُجُ الرَّجُلِ بِالشَّيْءِ"" : اِتِّخاذُ الْمُبادَرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19502, 'تَلَجُّنٌ', 'تلجن', 'مصدر', 'لجن', 'تلجن', 'تلجن', 'مص. تَلَجَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَجُّنٌ-تَلَجُّنٌ [ل ج ن] (مص. تَلَجَّنَ). 1.""تَلَجُّنُ العَجينِ"" : تَلَزُّجُهُ. 2.""تَلَجُّنُ الجِسْمِ"" : اِتِّساخُهُ. 3.""تَلَجُّنُ الرَّأْسِ"" : غَسْلُهُ مع بَقاءِ بَعْضِ وَسَخِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19503, 'تَلَحُّحٌ', 'تلحح', 'مصدر', 'لحح', 'تلحح', 'تلح', 'مص. تَلَحَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَحُّحٌ-تَلَحُّحٌ [ل ح ح] (مص. تَلَحَّحَ). ""التَّلَحُّحُ عَلَيْهِ"" : الإِلْحاحُ عَلَيْهِ، الْمُواظَبَةُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19504, 'تَلَحُّفٌ', 'تلحف', 'مصدر', 'لحف', 'تلحف', 'تلحف', 'مص. تَلَحَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَحُّفٌ-تَلَحُّفٌ [ل ح ف] (مص. تَلَحَّفَ). ""تَلَحُّفُ الْمَرْأَةِ بِاللِّحافِ"" : تَغَطِّيها بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19505, 'تَلَدُّنٌ', 'تلدن', 'مصدر', 'لدن', 'تلدن', 'تلدن', 'مص. تَلَدَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَدُّنٌ-تَلَدُّنٌ [ل د ن] (مص. تَلَدَّنَ). 1.""التَّلَدُّنُ في الأمْرِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19506, 'تَلَذُّذٌ', 'تلذذ', 'مصدر', 'لذذ', 'تلذذ', 'تلذ', 'مص. تَلَذُّذٌ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَلَذُّذٌ-تَلَذُّذٌ [ل ذ ذ] (مص. تَلَذُّذٌ). 1.""التَّلَذُّذُ بِالطَّعامِ"" : وَجودُهُ لَذيذاً. 2.""التَّلَذُّذُ بِالمديحِ"" : الشُّعُورُ بِالارْتِياحِ لِسَمَاعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19507, 'تَلَذُّعٌ', 'تلذع', 'مصدر', 'لذع', 'تلذع', 'تلذع', 'مص. تَلَذَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَذُّعٌ-تَلَذُّعٌ [ل ذ ع] (مص. تَلَذَّعَ). 1.""تَلَذُّعُ النَّارِ"" : ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19508, 'تَلَصُّصٌ', 'تلصص', 'مصدر', 'لصص', 'تلصص', 'تلص', 'مص. تَلَصَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَصُّصٌ-تَلَصُّصٌ [ل ص ص] (مص. تَلَصَّصَ). ""تَلَصُّصُ الرَّجُلِ"" : تَجَسُّسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19509, 'تَلَطُّخٌ', 'تلطخ', 'مصدر', 'لطخ', 'تلطخ', 'تلطخ', 'مص. تَلَطَّخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَطُّخٌ-تَلَطُّخٌ [ل ط خ] (مص. تَلَطَّخَ). 1.""تَلَطُّخُ الثَّوْبِ بِالدَّمِ"" : تَلَوُّثُهُ بِهِ. 2.""التَّلَطُّخُ بِالعارِ"" : التَّدَنُّسُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19510, 'تَلَطُّفٌ', 'تلطف', 'مصدر', 'لطف', 'تلطف', 'تلطف', 'مص. تَلَطَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَطُّفٌ-تَلَطُّفٌ [ل ط ف] (مص. تَلَطَّفَ). 1.""التَّلَطُّفُ بِالوَلَدِ"": التَّرَفُّقُ بِهِ. 2.""التَّلَطُّفُ في الْمَسْجِدِ"" : التَّخَشُّعُ وَتَرْديدُ اللَّطيفِ. 3.""التَّلَطُّفُ بِالعَدُوِّ"" : الاِحْتِيالُ عَلَيْهِ لِلاطِّلاعِ على أَسْرارِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19511, 'تَلَظِّي', 'تلظي', 'مصدر', 'لظي', 'تلظي', 'تلظ', 'مص. تَلَظَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَلَظِّ-تَلَظِّ، التَّلَظِّي [ل ظ ي] (مص. تَلَظَّى). 1.""تَلَظِّي النَّارِ"" : تَلَهُّبُها، اِلْتِهابُها، اِتِّقادُها، اِضْطِرامُها. 2.""تَلَظِّي الهَجيرِ"": اِشْتِدادُ الحَرِّ. 3.""تَلَظِّي الحَيّةِ"" : تَحَرُّكُها، تَقَلُّبُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19512, 'تَلَعٌ', 'تلع', 'مصدر', 'تلع', 'تلع', 'تلع', 'مص. تَلِعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَلَعٌ-تَلَعٌ [ت ل ع] (مص. تَلِعَ). 1.""تَلَعُ العُنُقِ"" : طولُهُ. 2.""شَابٌّ تَلَعُ القَامَةِ"": طَوِيلُ القَامَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19513, 'تَلَعْثُمٌ', 'تلعثم', 'مصدر', 'لعث', 'تلعثم', 'تلعثم', 'مص. تَلَعْثَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَعْثُمٌ-تَلَعْثُمٌ [ل ع ث] (مص. تَلَعْثَمَ). ""التَّلَعْثُمُ في الكَلامِ"": التَّلَكُّؤُ، التَّأَنِّي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19514, 'تَلَغُّمٌ', 'تلغم', 'مصدر', 'لغم', 'تلغم', 'تلغم', 'مص. تَلَغَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَغُّمٌ-تَلَغُّمٌ [ل غ م] (مص. تَلَغَّمَ). 1.""التَّلَغُّمُ بِالطِّيبِ"": جَعْلُهُ على الْمَلاَغِمِ"". 2.""التَّلَغُّمُ بِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19515, 'تَلَفٌ', 'تلف', 'مصدر', 'تلف', 'تلف', 'تلف', 'مص. تَلِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَلَفٌ-تَلَفٌ [ت ل ف] (مص. تَلِفَ). 1.""أَصابَ الزَّرْعَ التَّلَفُ"" : الهَلاكُ، الفَسادُ. ""تَعَرَّضَتِ الآلَةُ للتَّلَفِ"". 2.""تَلَفُ المالِ"" : ذَهابُهُ هَدَراً، صَرْفُهُ هَباءً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19516, 'تَلَفُّتٌ', 'تلفت', 'مصدر', 'لفت', 'تلفت', 'تلفت', 'مص. تَلَفَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَفُّتٌ-تَلَفُّتٌ [ل ف ت] (مص. تَلَفَّتَ). 1.""التَّلَفُّتُ إلى الخَلْفِ"" : الاِلْتِفاتُ. 2.""التَّلَفُّتُ بِالوَجْهِ يَميناً"" : الْمَيْلُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19517, 'تَلْفَزَةٌ', 'تلفزة', 'مصدر', 'لفز', 'تلفزة', 'تلفزة', 'مص. تَلْفَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْفَزَةٌ-تَلْفَزَةٌ [ل ف ز] (مص. تَلْفَزَ).: الإِرسالُ الإِلِيكْتْرونِيُّ لِلصُّوَرِ والْمَشاهِدِ الْمُتَحَرِّكَةِ أَوِ الثَّابِتَةِ على بُعْدٍ أَو قُرْبٍ بِواسِطَةِ السِّلْكِيَّةِ أَوِ اللاَّسِلْكِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19518, 'تَلَفُّظٌ', 'تلفظ', 'مصدر', 'لفظ', 'تلفظ', 'تلفظ', 'مص. تَلَفَّظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَفُّظٌ-تَلَفُّظٌ [ل ف ظ] (مص. تَلَفَّظَ). ""التَّلَفُّظُ بِعِباراتِ الشُّكْرِ"" : النُّطْقُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19519, 'تَلَكُّؤٌ', 'تلكؤ', 'مصدر', 'لكأ', 'تلكء', 'تلك', 'مص. تَلَكَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَلَكُّؤٌ-تَلَكُّؤٌ [ل ك أ] (مص. تَلَكَّأَ). ""التَّلَكُّؤُ في إِنْجازِ العَمَلِ"": التَّباطُؤُ، الإِبْطاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19520, 'تَلَفُّفٌ', 'تلفف', 'مصدر', 'لفف', 'تلفف', 'تلف', 'مص. تَلَفَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَفُّفٌ-تَلَفُّفٌ [ل ف ف] (مص. تَلَفَّفَ). 1.""التَّلَفُّفُ بِالثَّوْبِ"": إِحاطَةُ الجِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19521, 'تَلَفْلُفٌ', 'تلفلف', 'مصدر', 'لفلف', 'تلفلف', 'تلفلف', 'مص. تَلَفْلَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَفْلُفٌ-تَلَفْلُفٌ [ل ف ل ف] (مص. تَلَفْلَفَ). ""التَّلَفْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19522, 'تَلَقُّبٌ', 'تلقب', 'مصدر', 'لقب', 'تلقب', 'تلقب', 'مص. تَلَقَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَقُّبٌ-تَلَقُّبٌ [ل ق ب] (مص. تَلَقَّبَ). ""تَلَقُّبُ الرّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19523, 'تَلَقُّحٌ', 'تلقح', 'مصدر', 'لقح', 'تلقح', 'تلقح', 'مص. تَلَقَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَقُّحٌ-تَلَقُّحٌ [ل ق ح] (مص. تَلَقَّحَ). ""التَّلَقُّحُ على الرَّجُلِ"": التَّجَنِّي عَلَيْهِ وَظُلْمُهُ بِفِعْلٍ لَم يَفْعَلْهُ أو قَوْلٍ لم يَقُلْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19524, 'تَلَقُّطٌ', 'تلقط', 'مصدر', 'لقط', 'تلقط', 'تلقط', 'مص. تَلَقَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَقُّطٌ-تَلَقُّطٌ [ل ق ط] (مص. تَلَقَّطَ). ""تَلَقُّطُ الشَّيْءِ"" : اِلْتِقاطُهُ، جَمْعُهُ مِنْ هُنا وَهُناكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19525, 'تَلَقُّفٌ', 'تلقف', 'مصدر', 'لقف', 'تلقف', 'تلقف', 'مص. تَلَقَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَقُّفٌ-تَلَقُّفٌ [ل ق ف] (مص. تَلَقَّفَ). 1.""تَلَقُّفُ الطَّعامِ"": بَلْعُهُ، تَلَقُّمُهُ. 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19526, 'تَلَقُّمٌ', 'تلقم', 'مصدر', 'لقم', 'تلقم', 'تلقم', 'مص. تَلَقَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَقُّمٌ-تَلَقُّمٌ [ل ق م] (مص. تَلَقَّمَ). ""تَلَقُّمُ الطَّعَامِ أَكْلُهُ بِسُرْعَةٍ، تَلَقُّفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19527, 'تَلَقُّنٌ', 'تلقن', 'مصدر', 'لقن', 'تلقن', 'تلقن', 'مص. تَلَقَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَقُّنٌ-تَلَقُّنٌ [ل ق ن] (مص. تَلَقَّنَ). ""تَلَقُّنُ الدَّرْسِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19528, 'تَلَقِّي', 'تلقي', 'مصدر', 'لقي', 'تلقي', 'تلق', 'مص. تَلَقَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَلَقٍّ-تَلَقٍّ، التَّلَقِّي[ل ق ي] (مص. تَلَقَّى). 1.""تَلَقِّي الدَّرْسِ"" : تَلَقُّنُهُ. 2.""تَلَقِّي العِلْمِ"" : أَخْذُهُ، فَهْمُهُ. 3.""تَلَقِّي مُكالَمَةٍ هات"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19529, 'تَلَهِّي', 'تلهي', 'مصدر', 'لهو', 'تلهي', 'تله', 'مص. تَلَهَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R0', '', '', '', '', '', '', '"تَلَهٍّ-تَلَهٍّ، التَّلَهِّي[ل هـ و] (مص. تَلَهَّى). 1.""تَلَهِّي الطِّفْلِ بِاللُّعَبِ"": اِنْشِغالُهُ بِها. 2.""التَّلَهِّي عَنِ الدَّرْسِ"" : الإعْراضُ، الاِنْشِغالُ عَنْهُ. 3.""التَّلَهِّي بِتَبادُلِ النُّكَتِ"": التَّسَلِّي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19530, 'تَلَمُّجٌ', 'تلمج', 'مصدر', 'لمج', 'تلمج', 'تلمج', 'مص. تَلَمَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَمُّجٌ-تَلَمُّجٌ [ل م ج] (مص. تَلَمَّجَ). ""أَخَذَ مَعَهُ تَلَمُّجاً في حَقيبَتِهِ"" : لُمْجَةٌ، أَكْلَةً خَفيفَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19531, 'تَلْمَذَةٌ', 'تلمذة', 'مصدر', 'لمذ', 'تلمذة', 'تلمذة', 'مص. تَلْمَذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْمَذَةٌ-تَلْمَذَةٌ [ل م ذ] (مص. تَلْمَذَ). ""وَجَدَ في تَلْمَذَتِهِ اسْتِجابَةً"": في اتِّخاذِهِ تِلْميذاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19532, 'تَلَمُّسٌ', 'تلمس', 'مصدر', 'لمس', 'تلمس', 'تلمس', 'مص. تَلَمَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَمُّسٌ-تَلَمُّسٌ[ل م س] (مص. تَلَمَّسَ). 1.""تَلَمُّسُ العَفْوِ"": تَطَلُّبُهُ مَرَّاتٍ. 2.""تَلَمُّسُ المادَّةِ"" : تَحَسُّسُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19533, 'تَلَمُّعٌ', 'تلمع', 'مصدر', 'لمع', 'تلمع', 'تلمع', 'مص. تَلَمَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَمُّعٌ-تَلَمُّعٌ [ل م ع] (مص. تَلَمَّعَ). 1.""تَلَمُّعُ البَرْقِ"" : بَرْقُهُ. 2.""تَلَمُّعُ الشَّيْءِ"" : أَخْذُهُ خِلْسَةً، اِخْتِلاسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19534, 'تَلَمُّقٌ', 'تلمق', 'مصدر', 'لمق', 'تلمق', 'تلمق', 'مص. تَلَمَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَمُّقٌ-تَلَمُّقٌ [ل م ق] (مص. تَلَمَّقَ). ""تَلَمُّقُ الضُّيوفِ"" : أَكَلوا ما يُؤْكَلُ قَبْلَ الغَدَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19535, 'تَلَمْلُمٌ', 'تلملم', 'مصدر', 'لملم', 'تلملم', 'تلملم', 'مص. تَلَمْلَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَمْلُمٌ-تَلَمْلُمٌ [ل م ل م] (مص. تَلَمْلَمَ). ""تَلَمْلُمُ النَّاسِ"" : اِجْتِماعُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19536, 'تَلَهٌ', 'تله', 'مصدر', 'تله', 'تله', 'تله', 'مص. تَلِهَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"تَلَهٌ-تَلَهٌ [ت ل هـ] (مص. تَلِهَ). 1.""تَلَهُ الشَّيْءِ"" : فَسادُهُ، تَلَفُهُ، هَلاكُهُ. 2.""تَلَهُ الوَلَدِ"" : تَحَيُّرُهُ، حَيْرَتُهُ، تَرَدُّدُهُ. 3.""تَلَهُ العاشِقِ"" : ذَهابُ عَقْلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19537, 'تَلَهُّبٌ', 'تلهب', 'مصدر', 'لهب', 'تلهب', 'تلهب', 'مص. تَلَهَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَهُّبٌ-تَلَهُّبٌ [ل هـ ب] (مص. تَلَهَّبَ). 1.""تَلَهُّبُ النَّارِ"": اِشْتِعالُها، اِتِّقادُها، اِضْطِرامُها. 2.""تَلَهُّبُ الرَّجُلِ مِنَ الجُوعِ"": تَحَرُّقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19538, 'تَلَهُّفٌ', 'تلهف', 'مصدر', 'لهف', 'تلهف', 'تلهف', 'مص. تَلَهَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَهُّفٌ-تَلَهُّفٌ [ل هـ ف] (مص. تَلَهَّفَ). ""شَعَرَ بِتَلَهُّفٍ شَديدٍ على ما ضاعَ مِنْهُ"" : التَّحَسُّرُ، التَّأَسِّي، الاحْتِراقُ، الحُزْنُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19539, 'تَمٌّ', 'تم', 'مصدر', 'تمم', 'تم', 'تم', 'مص. تَمَّ', '', '', 'مفرد', 'DnN', '', '', '"تِمَمٌ:تِمَمَةٌ"', '', 'R', '', '', '', '', '', '', '"(مص. تَمَّ). 1.""عَمَلٌ تَمٌّ"" : تامٌّ، كامِلٌ. 2.: الفَأْسُ. 3.: آلَةٌ تُضْرَبُ بِها الأرْضُ وَيُجْرَفُ بِها التُّرابُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19540, 'تَلَوُّثٌ', 'تلوث', 'مصدر', 'لوث', 'تلوث', 'تلث', 'مص. تَلَوَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَوُّثٌ-تَلَوُّثٌ [ل و ث] (مص. تَلَوَّثَ). 1.""تَلَوُّثُ الثَّوْبِ بِالوَسَخِ"" : تَلَطُّخُهُ. 2.""تَلَوُّثُ الماءِ"" : تَكَدُّرُهُ بِالأوْساخِ. 3.""يُحافِظُ على عَدَمِ تَلَوُّثِ سُمْعَتِهِ"" : عَدَمُ تَشَوُّهِها، ألاَّ تَكونَ مُعَرَّضَةً لِلْقِيلِ وَالقالِ والاتِّهاماتِ السَّيِّئَةِ. 4.""تَلَوُّثُ البِيئَةِ"": اِمْتلاؤُها بِالأوْساخِ والأزْبالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19541, 'تَلَوُّحٌ', 'تلوح', 'مصدر', 'لوح', 'تلوح', 'تلح', 'مص. تَلَوَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَوُّحٌ-تَلَوُّحٌ [ل و ح] (مص. تَلَوَّحَ). ""تَلَوُّحُ الشَّيْءِ"" : ظُهورُهُ، وُضُوحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19542, 'تَلَوُّمٌ', 'تلوم', 'مصدر', 'لوم', 'تلوم', 'تلم', 'مص. تَلَوَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَوُّمٌ-تَلَوُّمٌ [ل و م] (مص. تَلَوَّمَ). 1.""تَلَوُّمُ الرَّجُلِ"" : تَكَلُّفُهُ اللَّوْمَ. 2.""التَّلَوُّمُ في أَمْرٍ"" : التَّلَبُّثُ فيه، تَأَمُّلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19543, 'تَلَوُّنٌ', 'تلون', 'مصدر', 'لون', 'تلون', 'تلن', 'مص. تَلَوَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَوُّنٌ-تَلَوُّنٌ [ل و ن] (مص. تَلَوَّنَ). 1.""تَلَوُّنُ الثَّوْبِ"" : تَغَيُّرُ لَوْنِهِ. 2.""تَلَوُّنُ الوَجْهِ"" : اِضْطِرابُهُ، اِخْتِلافُ أَلْوانِهِ. 3.""تَلَوُّنُ آراءِ الرَّجُلِ"" : تَغَيُّرُها، عَدَمُ ثُبُوتِها على شَيْءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19544, 'تَلَوُّهٌ', 'تلوه', 'مصدر', 'لوه', 'تلوه', 'تله', 'مص. تَلَوَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَوُّهٌ-تَلَوُّهٌ [ل و هـ] (مص. تَلَوَّهَ). ""تَلَوُّهُ السَّرابِ"" : اِضْطِرابُهُ، لَمَعانُهُ، تَلأْلُؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19545, 'تَلَوِّي', 'تلوي', 'مصدر', 'لوي', 'تلوي', 'تل', 'مص. تَلَوَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R0', '', '', '', '', '', '', '"تَلَوٍّ-تَلَوٍّ، التَّلَوِّي [ل و ي] (مص. تَلَوَّى). 1.""تَلَوِّي الْحَيَّةِ"": اِسْتِدارَتُها، اِلْتِواؤُها. 2.""التَّلَوِّي مِنَ الألَمِ"" : التَّوَجُّعُ، الاضْطِرابُ. 3.""تَلَوِّي النَّهْرِ في مَجْراهُ"" : تَعَرُّجُهُ، تَمَوُّجُهُ، اِنْعِطافُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19546, 'تَلَيُّثٌ', 'تليث', 'مصدر', 'ليث', 'تليث', 'تلث', 'مص. تَلَيَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَيُّثٌ-تَلَيُّثٌ [ل ي ث] (مص. تَلَيَّثَ). ""تَلَيُّثُ البَطَلِ"" : صَيْرُهُ كَاللَّيْثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19547, 'تَلَيُّنٌ', 'تلين', 'مصدر', 'لين', 'تلين', 'تلن', 'مص. تَلَيَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلَيُّنٌ-تَلَيُّنٌ [ل ي ن] (مص. تَلَيَّنَ). 1.""تَلَيُّنُ طَبْعِهِ"" : رِقَّتُهُ، لُيُونَتُهُ. 2.""سَعَى إلى التَّليُّنِ لَهُ"" : إلى التَّمَلُّقِ لَهُ، التَّوَدُّدِ إِلَيْهِ، التَّذَلُّلِ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19548, 'تَمامٌ', 'تمام', 'مصدر', 'تمم', 'تمام', 'تمم', 'مص. تَمَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمامٌ-تَمامٌ [ت م م] (مص. تَمَّ). 1.""أَنْجَزَ عَمَلَهُ بِالتَّمامِ"" : بِالكَمالِ، على وَجْهٍ كامِلٍ. 2.""سَيَبْدَأُ الدَّرْسُ في تَمامِ السَّاعَةِ الثَّامِنَةِ"" : في الثَّامِنَةِ بِالضَّبْطِ. 3.""بَلَغَ البَدْرُ تَمامَهُ"" : اِكْتِمالَهُ. 4.""رَأْيُكَ صائِبٌ تَماماً"" : صائِبٌ بِكُلِّيَّتِهِ. 5.""لَيْلُ التَّمامِ"" : أَطْوَلُ لَيْلَةٍ في السَّنَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19549, 'تَمازُحٌ', 'تمازح', 'مصدر', 'مزح', 'تمازح', 'تمزح', 'مص. تَمازَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمازُحٌ-تَمازُحٌ [م ز ح] (مص. تَمازَحَ). ""يَتَجَنَّبُ التَّمازُحَ"": التَّلاعُبَ، المِزاحَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19550, 'تِمَمٌ', 'تمم', 'مصدر', '', 'تمم', 'تم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19551, 'تِمَمَةٌ', 'تممة', 'مصدر', '', 'تممة', 'تممة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19552, 'تَماثُلٌ', 'تماثل', 'مصدر', 'مثل', 'تماثل', 'تمثل', 'مص. تَماثَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَماثُلٌ-تَماثُلٌ [م ث ل] (مص. تَماثَلَ). 1.""بَيْنَ الصُّورَتَيْنِ تَماثُلٌ"" : تَشابُهٌ. 2.""تَماثُلُ الْمَريضِ لِلشِّفاءِ"" : دُخولُهُ في طَوْرِ النَّقاهَةِ. 3.""تَماثُلُ العَدَدَيْنِ"" : تَساوِيهِما."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19553, 'تَماجُدٌ', 'تماجد', 'مصدر', 'مجد', 'تماجد', 'تمجد', 'مص. تَماجَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَماجُدٌ-تَماجُدٌ [م ج د] (مص. تَماجَدَ). 1.""تَماجُدُ النَّاسِ"" : تَفاخُرُهُمْ. 2.""تَماجُدُ الرَّجُلِ"" : إِظْهارُ مَجْدِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19554, 'تَمادِي', 'تمادي', 'مصدر', 'مدي', 'تمادي', 'تمد', 'مص. تَمادَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَمادٍ-تَمادٍ، التَّمادِي [م د ي] (مص. تَمادَى). 1.""التَّمَادِي فِي النَّمِيمَةِ"": الاِسْتِمْرَارُ فِيهَا. ""الرُّجوعُ إلى الحَقِّ خَيْرٌ مِنَ التَّمادِي في الباطِلِ"". (الجاحظ). 2.""مَعَ التَّمادِي"" : على مَرِّ الأيَّامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19555, 'تَمارُسٌ', 'تمارس', 'مصدر', 'مرس', 'تمارس', 'تمرس', 'مص. تَمارَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمارُسٌ-تَمارُسٌ [م ر س] (مص. تَمارَسَ). تَمارُسُ الْمُتَحاربِينَ"" : تَضارُبُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19556, 'تَمارُضٌ', 'تمارض', 'مصدر', 'مرض', 'تمارض', 'تمرض', 'مص. تَمارَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمارُضٌ-تَمارُضٌ [م ر ض] (مص. تَمارَضَ). ""اِدَّعى التَّمارُضَ"": التَّظاهُرَ بِالْمَرَضِ وَلَيْسَ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19557, 'تَمارِي', 'تماري', 'مصدر', 'مري', 'تماري', 'تمر', 'مص. تَمارَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَمارٍ-تَمارٍ، التَّمارِي [م ر ي] (مص. تَمارَى). 1.""تَمارِي الْمُتَنازِعينَ"" : تَجادُلُهُمْ. 2.""التَّمارِي في الأخْبارِ"" : الشَّكُّ فيها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19558, 'تَمازُجٌ', 'تمازج', 'مصدر', 'مزج', 'تمازج', 'تمزج', 'مص. تَمازَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمازُجٌ-تَمازُجٌ [م ز ج] (مص. تَمازَجَ). ""تَمازُجُ السَّوائِلِ"": تَخَالُطُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19559, 'تَمايُدٌ', 'تمايد', 'مصدر', 'ميد', 'تمايد', 'تمد', 'مص. تَمايَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمايُدٌ-تَمايُدٌ [م ي د] (مص. تَمايَدَ). ""تَمايُدُ الرَّجُلِ"" : تَمايُلُهُ مُهْتَزّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19560, 'تَماسٌّ', 'تماس', 'مصدر', 'مسس', 'تماس', 'تمس', 'مص. تَماسَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَماسٌّ-تَماسٌّ [م س س] (مص. تَماسَّ). ""نُقْطَةُ التَّماسِّ"" : نُقْطَةُ الْمُلامَسَةِ. ""زَاوِيَةُ التَّماسِّ"". (هن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19561, 'تَماسُكٌ', 'تماسك', 'مصدر', 'مسك', 'تماسك', 'تمسك', 'مص. تَماسَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَماسُكٌ-تَماسُكٌ [م س ك] (مص. تَماسَكَ). 1.""تَماسُكُ الرَّجُلِ"" : ضَبْطُ نَفْسِهِ. 2.""أَرادَ التَّماسُكَ بِهِ"" : التَّعَلُّقَ بِهِ. 3.""تَماسُكُ الجِدارِ"" : بَقاؤُهُ على حالَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19562, 'تَماسِي', 'تماسي', 'مصدر', 'مسي', 'تماسي', 'تمس', 'مص. تَماسَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَماسٍ-تَماسٍ، التَّماسِي [م س ي] (مص. تَماسَى). 1.""تَماسِي الحَبْلِ"": تَقَطُّعُهُ. 2.""أَصابَتْهُ التَّماسِي"" : الدَّواهِي، المصائِبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19563, 'تَماشُقٌ', 'تماشق', 'مصدر', 'مشق', 'تماشق', 'تمشق', 'مص. تَماشَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَماشُقٌ-تَماشُقٌ [م ش ق] (مص. تَماشَقَ). ""تَماشُقُ الشَّيْءِ"": تَنازُعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19564, 'تَماشِي', 'تماشي', 'مصدر', 'مشي', 'تماشي', 'تمش', 'مص. تَماشَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَماشٍ-تَماشٍ، التَّماشِي [م ش ي] (مص. تَماشَى). 1.""تَماشِي الوَلَدَيْنِ"" : الْمَشْيُ مَعاً. 2.""تَماشي الألْوانِ"" : تَناسُبُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19565, 'تَماكُرٌ', 'تماكر', 'مصدر', 'مكر', 'تماكر', 'تمكر', 'مص. تَماكَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَماكُرٌ-تَماكُرٌ [م ك ر] (مص. تَماكَرَ). ""تَماكُرُ العَدُوَّيْنِ"" : مَكْرُ، اِحْتِيالُ أَحَدِهِما على الآخَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19566, 'تَماكُسٌ', 'تماكس', 'مصدر', 'مكس', 'تماكس', 'تمكس', 'مص. تَماكَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَماكُسٌ-تَماكُسٌ [م ك س] (مص. تَماكَسَ). ""التَّماكُسُ في البَيْعِ"" : التَّشاحُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19567, 'تَمالُكٌ', 'تمالك', 'مصدر', 'ملك', 'تمالك', 'تملك', 'مص. تَمالَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمالُكٌ-تَمالُكٌ [م ل ك] (مص. تَمالَكَ). ""تَمالُكُ النَّفْسِ"" : مَلْكُها، ضَبْطُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19568, 'تَماوُتٌ', 'تماوت', 'مصدر', 'موت', 'تماوت', 'تمت', 'مص. تَماوَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَماوُتٌ-تَماوُتٌ [م و ت] (مص. تَماوَتَ). ""تَماوُتُ الرَّجُلِ"": إِظْهارُ نَفْسِهِ بِأَنَّهُ مَيِّتٌ، التَّظاهُرُ بِذلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19569, 'تَمَدُّدٌ', 'تمدد', 'مصدر', 'مدد', 'تمدد', 'تمد', 'مص. تَمَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَدُّدٌ-تَمَدُّدٌ [م د د] (مص. تَمَدَّدَ). 1.""التَّمَدُّدُ على الأَرْضِ"": الاِسْتِلْقاءُ. 2.""تَمَدُّدُ الحَدِيدِ"" : اِسْتِطالَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19570, 'تَمايُزٌ', 'تمايز', 'مصدر', 'ميز', 'تمايز', 'تمز', 'مص. تَمايَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمايُزٌ-تَمايُزٌ [م ي ز] (مص. تَمايَزَ). 1.""تَمايُزُ الجَماعَةِ"" : تَفَرُّقُها، تَخاصُمُها. 2.""بَيْنَهُما تَمايُزٌ في الطَّبْعِ والسُّلوكِ"" : اِخْتِلافٌ، تَبايُنٌ، تَغايُرٌ. 3.""التَّمايُزُ في العَمَلِ"" : التَّمَيُّزُ والاِخْتِلافُ فيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19571, 'تَمايُلٌ', 'تمايل', 'مصدر', 'ميل', 'تمايل', 'تمل', 'مص. تَمايَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمايُلٌ-تَمايُلٌ [م ي ل] (مص. تَمايَلَ). 1.""لاحَظَ الرُّكَّابُ تَمايُلَ السَّفينَةِ"" : تَأَرْجُحَها، اِهْتِزازَها شِمالاً وَيَميناً. 2.""تَمايُلُ الرَّجُلِ في مَشْيِهِ"" : تَبَخْتُرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19572, 'تَمَتُّعٌ', 'تمتع', 'مصدر', 'متع', 'تمتع', 'تمتع', 'مص. تَمَتَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَتُّعٌ-تَمَتُّعٌ [م ت ع] (مص. تَمَتَّعَ). ""التَّمَتُّعُ بِطَيِّباتِ الحَياةِ"": التَّلَذُّذُ والانْتِفاعُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19573, 'تَمْتَمَةٌ', 'تمتمة', 'مصدر', 'تمتم', 'تمتمة', 'تمتمة', 'مص. تَمْتَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْتَمَةٌ-تَمْتَمَةٌ [ت م ت م] (مص. تَمْتَمَ). ""تَشْتَدُّ تَمْتَمَتُهُ مِنْ حِينٍ لآخَرَ"" : التَّلَكُّؤُ في إِخْراجِ الحُروفِ مِنْ مَخارِجِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19574, 'تَمثُّلٌ', 'تمثل', 'مصدر', 'مثل', 'تمثل', 'تمثل', 'مص. تَمَثَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمثُّلٌ-تَمثُّلٌ [م ث ل] (مص. تَمَثَّلَ). 1.""تَمَثُّلُ الوَهْمِ لَهُ حَقيقَةً"" : تَصَوُّرُهُ لَهُ. 2.""تَمَثُّلُ الْمُعَلِّمِ"" : تَصَوُّرُ مِثالِهُ. 3.""التَّمَثُّلُ بِرئِيسِهِ"" : التَّشَبُّهُ بِهِ، اِتِّخاذُهُ مِثالاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19575, 'تَمَجُّدٌ', 'تمجد', 'مصدر', 'مجد', 'تمجد', 'تمجد', 'مص. تَمَجَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَجُّدٌ-تَمَجُّدٌ [م ج د] (مص. تَمَجَّدَ). ""تَمَجُّدُ الرَّجُلِ"" : تَعَظُّمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19576, 'تَمَجُّنٌ', 'تمجن', 'مصدر', 'مجن', 'تمجن', 'تمجن', 'مص. تَمَجَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَجُّنٌ-تَمَجُّنٌ [م ج ن] (مص. تَمَجَّنَ). ""تَمَجُّنُ الوَلَدِ"" : قِيامُهُ بِعَمَلِ الماجِنِ القليلِ الحياءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19577, 'تَمَخُّضٌ', 'تمخض', 'مصدر', 'مخض', 'تمخض', 'تمخض', 'مص. تَمَخَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَخُّضٌ-تَمَخُّضٌ [م خ ض] (مص. تَمَخَّضَ). 1.""تَمَخُّضُ اللَّبَنِ"" : تَحَرُّكُهُ في المِمْخَضَةِ. 2.""تَمَخُّضُ الجَنينِ في بَطْنِ أُمِّهِ"": تَحَرُّكُهُ. 3.""تَمَخُّضُ الحامِلِ"" : اِنْقِباضُ بَطْنِها عَلاَمَةً على قُرْبِ دورَتِها عِنْدَما يَأْخُذُها الطَّلْقُ. 4. ""تَمَخُّضُ السَّمَاءِ"": تَهَيُّؤُهَا لِلْمَطَرِ. 5.""تَمَخُّضُ البِلادِ عَنْ أَزمَةٍ سِياسِيَّةٍ"" : اِنْكِشافُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19578, 'تَمَخُّطٌ', 'تمخط', 'مصدر', 'مخط', 'تمخط', 'تمخط', 'مص. تَمَخَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَخُّطٌ-تَمَخُّطٌ [م خ ط] (مص. تَمَخَّطَ). ""تَمَخُّطُ الرَّجُلِ"" : إِخْراجُهُ الْمُخاطَ مِنْ أَنْفِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19579, 'تَمَرُّغٌ', 'تمرغ', 'مصدر', 'مرغ', 'تمرغ', 'تمرغ', 'مص. تَمَرَّغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَرُّغٌ-تَمَرُّغٌ [م ر غ] (مص. تَمَرَّغَ). 1.""التَّمَرُّغُ في التُّرابِ"": التَّقَلُّبُ فيهِ. 2.""تَمَرُّغُ الماشِيَةِ"" : إِطالَةُ رَعْيِها في المكانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19580, 'تَمَدْرُسٌ', 'تمدرس', 'مصدر', 'درس', 'تمدرس', 'تمدرس', 'مص. تَمَدْرَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَدْرُسٌ-تَمَدْرُسٌ [د ر س] (مص. تَمَدْرَسَ). ""تَمَدْرُسُ الوَلَدِ"": دُخولُهُ الْمَدْرَسَةَ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19581, 'تَمَدُّنٌ', 'تمدن', 'مصدر', 'مدن', 'تمدن', 'تمدن', 'مص. تَمَدَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَدُّنٌ-تَمَدُّنٌ [م د ن] (مص. تَمَدَّنَ). 1.""تَمَدُّنُ البَدْوِ"" : عَيْشُهُمْ عِيشَةَ أَهْلِ الْمُدنِ والتَّكَيُّفُ مَع جَوِّهِمْ. 2.""تَمَدُّنُ شَعْبٍ"" : دُخولُهُ في مَرْحَلَةِ الرُّقِيِّ والحَضارَةِ والعُمْرانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19582, 'تَمْدْيُنٌ', 'تمدين', 'مصدر', 'مدن', 'تمدين', 'تمدن', 'مص. تَمَدْيَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْدِينٌ-تَمْدِينٌ [م د ن] (مص. مَدَّنَ). 1.""تَمْدينُ الْمُدُنِ"" : بِناؤُها، تَشْيِيدُها. 2.""تَمْدينُ الشَّعْبِ"" : تَحْضيرُهُ، جَعْلُهُ مُتَحَضِّراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19583, 'تَمَذْهُبٌ', 'تمذهب', 'مصدر', 'ذهب', 'تمذهب', 'تمذهب', 'مص. تَمَذْهَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَذْهُبٌ-تَمَذْهُبٌ [ذ هـ ب] (مص. تَمَذْهَبَ). ""التَّمَذْهُبُ بِالْمَذْهَبِ"" : اِتِّباعُ مَبادِئِهِ والسَّيْرُ على خُطاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19584, 'تَمْرٌ', 'تمر', 'مصدر', 'تمر', 'تمر', 'تمر', 'مص. تَمَرَ', '', '', 'مفرد', 'DnN', '', '', '"تُمورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. تَمَرَ).: تَمْرُ النَّخيلِ، اليابِسُ النَّاضِجُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19585, 'تُمورٌ', 'تمور', 'مصدر', '', 'تمور', 'تمر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19586, 'تَمَرُّدٌ', 'تمرد', 'مصدر', 'مرد', 'تمرد', 'تمرد', 'مص. تَمَرَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَرُّدٌ-تَمَرُّدٌ [م ر د] (مص. تَمَرَّدَ). ""أَعْلَنُوا التَّمَرُّدَ عَنِ السُّلْطَةِ"": العِصْيانَ ، الثَّوْرَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19587, 'تَمَرُّسٌ', 'تمرس', 'مصدر', 'مرس', 'تمرس', 'تمرس', 'مص. تَمَرَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَرُّسٌ-تَمَرُّسٌ [م ر س] (مص. تَمَرَّسَ). 1.""التَّمَرُّسُ بِالطِّيبِ"": التَّلَطُّخُ بِهِ. 2.""التَّمَرُّسُ بِمِهْنَةٍ"" : التَّدَرُّبُ عَلَيْها والاِحْتِكاكُ بِها. 3.""التَّمَرُّسُ بِالْمَهامِّ الجَديدَةِ"" : مُزاوَلَتُها والتَّكَيُّفُ مَعَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19588, 'تَمَرُّعٌ', 'تمرع', 'مصدر', 'مرع', 'تمرع', 'تمرع', 'مص. تَمَرَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَرُّعٌ-تَمَرُّعٌ [م ر ع] (مص. تَمَرَّعَ). 1.""تَمَرُّعُ السَّائِرِ"" : إِسْراعُهُ. 2.""تَمَرُّعُ الرَّاعِي"" : طَلَبُهُ الْمَرْعَ، أَي العُشْبَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19589, 'تَمَشِّي', 'تمشي', 'مصدر', 'مشي', 'تمشي', 'تمش', 'مص. تَمَشَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَمَشٍّ-تَمَشٍّ، التَّمَشِّي [م ش ي] (مص. تَمَشَّى). 1.""تَمَشِّي الرَّجُلِ"" : مَشْيُهُ على قَدَمَيْهِ. 2.""التَّمَشِّي مَعَ النَّغَمِ"" : التَّناغُمُ مَعَهُ. 3.""تَمَشِّي الدَّواءِ في الجِسْمِ"" : سَرَيانُ مَفْعولِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19590, 'تَمَرْفُقٌ', 'تمرفق', 'مصدر', 'رفق', 'تمرفق', 'تمرفق', 'مص. تَمَرْفَق', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَرْفُقٌ-تَمَرْفُقٌ [ر ف ق] (مص. تَمَرْفَق). ""تَمَرْفُقُ النَّائِمِ"" : اِتِّخاذُهُ مِرْفَقَةً، أَيْ مِخَذَّةً أو مُتَّكَأً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19591, 'تَمَرْكُزٌ', 'تمركز', 'مصدر', 'ركز', 'تمركز', 'تمركز', 'مص. تَمَرْكَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَرْكُزٌ-تَمَرْكُزٌ [ر ك ز] (مص. تَمَرْكَزَ). ""التَّمَرْكُزُ في مَكانٍ"": اِتِّخاذُهُ مَرْكَزاً ثَابِتاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19592, 'تَمَرْمُرٌ', 'تمرمر', 'مصدر', 'مرمر', 'تمرمر', 'تمرمر', 'مص. تَمَرْمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَرْمُرٌ-تَمَرْمُرٌ [م ر م ر] (مص. تَمَرْمَرَ). 1.""تَمَرْمُرُ الجِسْمِ"": اِهْتِزازُهُ، تَرَجْرُجُهُ. 2.""التَّمَرْمُرُ على النَّاسِ"" : التَّأَمُّرُ عَلَيْهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19593, 'تَمَرُّنٌ', 'تمرن', 'مصدر', 'مرن', 'تمرن', 'تمرن', 'مص. تَمَرَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَرُّنٌ-تَمَرُّنٌ [م ر ن] (مص. تَمَرَّنَ). 1.""تَمَرُّنُ الجِلْدِ"" : تَليُّنُهُ. 2.""التَّمَرُّنُ على الأعْمالِ الصَّعْبَةِ"" : التَّدَرُّبُ عَلَيْها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19594, 'تَمَزُّقٌ', 'تمزق', 'مصدر', 'مزق', 'تمزق', 'تمزق', 'مص. تَمَزَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَزُّقٌ-تَمَزُّقٌ [م ز ق] (مص. تَمَزَّقَ). 1.""تَمَزُّقُ الثَّوْبِ"" : تَفَتُّتُهُ، تَقَطُّعُهُ، تَشَقُّقُهُ. 2.""تَمَزُّقُ الأهالي"" : تَفَرُّقُهُمْ، تَشَتُّتُهُمْ. 3.""تَمَزُّقُ قَلْبِهِ أَلَماً"" : تَفَطُّرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19595, 'تَمَسُّحٌ', 'تمسح', 'مصدر', 'مسح', 'تمسح', 'تمسح', 'مص. تَمَسَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَسُّحٌ-تَمَسُّحٌ [م س ح] (مص. تَمَسَّحَ). 1.""التَّمَسُّحُ بِالْماءِ"": الاِغْتِسالُ بِهِ. 2.""التَّمَسُّحُ لِلصَّلاةِ"" : التَّوَضُّؤُ مَسْحاً. 3.""التَّمَسُّحُ بِالأَرْضِ"" : التَّيَمُّمُ. 4.""التَّمَسُّحُ بِالدُّهْنِ"" : التَّمسيحُ بِهِ. 5.""التَّمَسُّحُ بِالرُّكْنِ"" : التَّبَرُّكُ بِمُلامَسَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19596, 'تَمَسُّكٌ', 'تمسك', 'مصدر', 'مسك', 'تمسك', 'تمسك', 'مص. تَمَسَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَسُّكٌ-تَمَسُّكٌ [م س ك] (مص. تَمَسَّكَ). 1.""التَّمَسُّكُ بِالحَبْلِ"" : التَّعَلُّقُ بِهِ. 2.""التَّمَسُّكُ بِآراءِ مَذْهَبِهِ"" : الاِرْتِباطُ، الاِلْتِصاقُ بِها. 3.""التَّمَسُّكُ بِالضَّريحِ"" : الاِعْتِصامُ بِهِ. 4.""التَّمَسُّكُ بِالطِّيبِ"" : التَّطَيُّبُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19597, 'تَمَسْكُنٌ', 'تمسكن', 'مصدر', 'سكن', 'تمسكن', 'تمسكن', 'مص. تَمَسْكَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَسْكُنٌ-تَمَسْكُنٌ [س ك ن] (مص. تَمَسْكَنَ). 1. ""تَمَسْكُنُ الرَّجُلِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19598, 'تَمَسْلُمٌ', 'تمسلم', 'مصدر', 'سلم', 'تمسلم', 'تمسلم', 'مص. تَمَسْلَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَسْلُمٌ-تَمَسْلُمٌ [س ل م] (مص. تَمَسْلَمَ). 1.""تَمَسْلُمُ الكافِرِ"": اِع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19599, 'تَمَصُّرٌ', 'تمصر', 'مصدر', 'مصر', 'تمصر', 'تمصر', 'مص. تَمَصَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَصُّرٌ-تَمَصُّرٌ [م ص ر] (مص. تَمَصَّرَ). 1.""تَمَصُّرُ قَرْيَةٍ"" : صَيْرُها مِصْراً، أَيْ مَدينَةً. 2.""تَمَصُّرُ الأهالي"" : تَفَرُّقُهُمْ في الأمْصارِ. 3.""تَمَصُّرُ الرَّجُلِ"" : تَجَنُّسُهُ بِجِنْسِيَّةِ بِلادِ مِصْرَ، أو تَشَبُّهُهُ بِأَهْلِ مِصْرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19600, 'تَمَضْمُضٌ', 'تمضمض', 'مصدر', 'مضمض', 'تمضمض', 'تمضمض', 'مص. تَمَضْمَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَضْمُضٌ-تَمَضْمُضٌ [م ض م ض] (مص. تَمَضْمَضَ). 1.التَّمَضْمُضُ بِالماءِ في الفَمِ"" : تَحْريكُهُ وإِدارَتُهُ فيهِ. 2.""تَمَضْمُضُ النُّعاسِ في عَيْنَيْهِ"" : دَبَّ دَبِيبُهُ فيهِما."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19601, 'تَمَضِّي', 'تمضي', 'مصدر', 'مضي', 'تمضي', 'تمض', 'مص. تَمَضَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R0', '', '', '', '', '', '', '"تَمَضٍّ-تَمَضٍّ، التَّمَضِّي [م ض ي] (مص. تَمَضَّى). 1.""تَمَضِّي الأمْرِ"" : نَفاذُهُ. 2.""تَمضِّي الرَّجُلِ"" : تَقَدُّمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19602, 'تَمَطُّرٌ', 'تمطر', 'مصدر', 'مطر', 'تمطر', 'تمطر', 'مص. تَمَطَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَطُّرٌ-تَمَطُّرٌ [م ط ر] (مص. تَمَطَّرَ). 1.""تَمَطُّرُ الرَّجُلِ في الأرْضِ"" : ذَهابُهُ. 2.""تَمَطُّرُ الخَيْلِ"" : مَجيئُها وَذَهابُها مُسْرِعَةً يَسْبِقُ بَعْضُها بَعْضاً. 3.""تَمَطُّرُ النَّاسِ"" : طَلَبُهُمْ نُزولَ الْمَطَرِ، اِسْتِسْقاؤُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19603, 'تَمَطُّطٌ', 'تمطط', 'مصدر', 'مطط', 'تمطط', 'تمط', 'مص. تَمَطَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَطُّطٌ-تَمَطُّطٌ [م ط ط] (مص. تَمَطَّطَ). 1.""تَمَطُّطُ الجِلْدِ"" : تَمَدُّدُهُ. 2.""التَّمَطُّطُ فِي الكَلاَمِ"" : التَّمْدِيدُ فِيهِ، تَطْوِيلُهُ، تَلْوِينُهُ، تَغْييرُ أَسَالِيبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19604, 'تَمَطُّقٌ', 'تمطق', 'مصدر', 'مطق', 'تمطق', 'تمطق', 'مص. تَمَطَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَطُّقٌ-تَمَطُّقٌ [م ط ق] (مص. تَمَطَّقَ). 1.""تَمَطُّقُ الطَّعَامِ"" : تَذَوُّقُهُ. 2. ""تَمَطُّقُ الرَّجُلِ"" : إحْداثُهُ صَوْتاً بِلِسَانِهِ وَشَفَتَيْهِ لاِسْتِطَابَةِ طَعْمِ الشَّيْءِ. 3. ""تَمَطُّقُ القَوْسِ"" : تَصَدُّعُهُ، تَشَقُّقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19605, 'تَمَطِّي', 'تمطي', 'مصدر', 'مطي', 'تمطي', 'تمط', 'مص. تَمَطَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَمَطٍّ-تَمَطٍّ، التَّمَطِّي [م ط ي] (مص. تَمَطَّى). 1. ""تَمَطِّي النَّهَارِ"" : طُولُهُ، اِمْتِدَادُهُ. 2. ""تَمَطِّي الرَّجُلِ"" : تَمَدُّدُهُ، تَبَخْتُرُهُ وَمَدُّ اليَدِ فِي الْمَشْيِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19606, 'تَمَعُّنٌ', 'تمعن', 'مصدر', 'معن', 'تمعن', 'تمعن', 'مص. تَمَعَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَعُّنٌ-تَمَعُّنٌ [م ع ن] (مص. تَمَعَّنَ). ""التَّمَعُّنُ فِي الْمَوْضُوعِ"": إعْمَالُ الفِكْرِ فِيهِ، التَّأمُّلُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19607, 'تَمَغْرُبٌ', 'تمغرب', 'مصدر', 'غرب', 'تمغرب', 'تمغرب', 'مص. تَمَغْرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَغْرُبٌ-تَمَغْرُبٌ [غ ر ب] (مص. تَمَغْرَبَ). 1. ""تَمَغْرُبُ الرَّجُلِ"" : صَيْرُهُ مَغْرِبيّاً أوْ تَشَبُّهُهُ بِالْمَغَارِبَةِ. 2. ""تَمَغْرُبُ الإدَارَةِ"": صَيْرُ أُطُرِهَا مِنَ الْمَغَارِبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19608, 'تَمَغُّصٌ', 'تمغص', 'مصدر', 'مغص', 'تمغص', 'تمغص', 'مص. تَمَغَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَغُّصٌ-تَمَغُّصٌ [م غ ص] (مص. تَمَغَّصَ). 1. ""تَمغُّصُ البَطْنِ"" : إصَابَتُهُ بِالْمَغْصِ، أَيْ أَلَمٌ فِي الأَمْعَاءِ. 2. ""تَجَنَّبَ تَمَغُّصَ الدَّاءِ بِهِ"" : تَجَنَّبَ إيذاءهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19609, 'تَمَقُّتٌ', 'تمقت', 'مصدر', 'مقت', 'تمقت', 'تمقت', 'مص. تَمَقَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَقُّتٌ-تَمَقُّتٌ [م ق ت] (مص. تَمَقَّتَ). ""التَّمَقُّتُ إلَيْهِ"" : التَّبَغُّضُ، وعَمَلُ مَا يُبْغِضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19610, 'تَمَكُّثٌ', 'تمكث', 'مصدر', 'مكث', 'تمكث', 'تمكث', 'مص. تَمَكَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَكُّثٌ-تَمَكُّثٌ [م ك ث] (مص. تَمَكَّثَ). 1. ""التَّمَكُّثُ بِالْمَكَانِ"" : التَّلَبُّثُ فِيهِ. 2. ""التَّمَكُّثُ فِي الأمْرِ"" : التَّأنِّي، التَّمَهُّلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19611, 'تَمَكُّنٌ', 'تمكن', 'مصدر', 'مكن', 'تمكن', 'تمكن', 'مص. تَمَكَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَكُّنُ-تَمَكُّنُ [م ك ن] (مص. تَمَكَّنَ). 1.""التَّمَكُّنُ مِنْ أمْرٍ مَّا"" : القُدْرَةُ عَلَيْهِ. 2. ""تَمَكُّنُ الْحَاكِمِ عِنْدَ الشَّعْبِ"" : صَيْرُهُ ذَا مَنْزِلَةٍ وَمَكَانَةٍ. 3.""تَمَكُّنُ الرَّجُلِ بِالبِلاَدِ"" : اِسْتِقْرَارُهُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19612, 'تَمَلُّؤٌ', 'تملؤ', 'مصدر', 'ملأ', 'تملء', 'تمل', 'مص. تَمَلَّأ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَمَلُّؤٌ-تَمَلُّؤٌ [م ل أ] (مص. تَمَلَّأ). 1. ""تَمَلُّؤُ الْمَعِدَةِ"" : اِمْتِلاؤُهَا. 2. ""تَمَلُّؤُ الْمَرْأَةِ"" : لِبْسُهَا الْمُلاءةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19613, 'تَمَلُّسٌ', 'تملس', 'مصدر', 'ملس', 'تملس', 'تملس', 'مص. تَمَلَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَلُّسٌ-تَمَلُّسٌ [م ل س] (مص. تَمَلَّسَ). 1.""تَمَلُّسُ الثَّوْبِ"" : صَيْرُهُ أمْلَسَ. 2. ""التَّمَلُّسُ مِنَ الشَّرَابِ"" : الصَّحْوُ مِنْهُ. 3.""التَّملُّسُ مِن يَدِهِ"" : التَّخَلُّصُ، الإِفْلاَتُ مِنْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19614, 'تَمَلُّصٌ', 'تملص', 'مصدر', 'ملص', 'تملص', 'تملص', 'مص. تَمَلَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَلُّصٌ-تَمَلُّصٌ [م ل ص] (مص. تَمَلَّصَ). 1. ""التَّمَلُّصُ مِنْ قَبْضَتِهِ"" : التَّخَلُّصُ، الإِفْلاَتُ مِنْهَا. 2. ""التَّمَلُّصُ مِنْ أدَاءِ الوَاجِبِ"" : التَّهَرُّبُ. 3. ""تَمَلُّصُ السَّمَكَةِ مِنْ بَيْنِ أصَابِعِهِ"" : اِنْسِلالُهَا لِمَلاَسَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19615, 'تَمَلُّقٌ', 'تملق', 'مصدر', 'ملق', 'تملق', 'تملق', 'مص. تَمَلَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَلُّقٌ-تَمَلُّقٌ [م ل ق] (مص. تَمَلَّقَ). ""لاَ يُرْضِيهِ كَثْرَةُ التَّمَلُّقِ"" : التَّذَلُّلِ، الْمُدَاهَنَةِ. ""أرَاهُ يَصِلُ إلَى أغْرَاضِهِ بِالتَّمَلُّقِ وَحُسْنِ الحِيلَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19616, 'تَمَلُّكٌ', 'تملك', 'مصدر', 'ملك', 'تملك', 'تملك', 'مص. تَمَلَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَلُّكٌ-تَمَلُّكٌ [م ل ك] (مص. تَمَلَّكَ). 1.""تَمَلُّكُ أمْلاكٍ"" : مِلْكُها. 2.""التَّمَلُّكُ عَلَى الشَّعْبِ"" : صَيْرُهُ مَلِكاً عَلَيْهِ. 3.""حَقُّ التَّمَلُّكِ"" : حَقُّ اكِتسَابِ المِلْكِيَّةِ وَحَوْزَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19617, 'تَمَلْمُلٌ', 'تململ', 'مصدر', 'ململ', 'تململ', 'تململ', 'مص. تَمَلْمَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَلْمُلٌ-تَمَلْمُلٌ [م ل م ل] (مص. تَمَلْمَلَ). 1.""التَّمَلْمُلُ عَلَى الفِرَاشِ"" : التَّقَلُّبُ عَلَيْهِ مِنْ مَرَضٍ أو حُزْنٍ. 2. ""تَمَلْمُلُ الجَالِس"" : مَيْلُهُ إلَى أحَدِ شِقَّيْهِ تَارَةً وَإلَى الآخَرِ تَارَةً أُخْرَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19618, 'تَمَلِّي', 'تملي', 'مصدر', 'ملو', 'تملي', 'تمل', 'مص. تَمَلَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَمَلٍّ-تَمَلٍّ، التَّمَلِّي [م ل و] (مص. تَمَلَّى). 1.""تَمَلِّي العُمْرِ"" : طُولُ العُمْرِ والاسْتِمْتَاعُ بِهِ. 2. ""تَملِّي الصِّحابِ"" : التَّمَتُّعُ بِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19619, 'تَمَوُّلٌ', 'تمول', 'مصدر', 'مول', 'تمول', 'تمل', 'مص. تَمَوَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَوُّلٌ-تَمَوُّلٌ [م و ل] (مص. تَمَوَّلَ). 1. ""أثَارَ تَمَوُّلُهُ عَلامَةَ اسْتِفْهَامٍ"" : كَثْرَةُ مَالِهِ. 2.""تَمَوُّلُ الْمَالِ"" : اِقْتِنَاؤُهُ. 3.""تَمَوُّلُ الْمَشْرُوعِ"" : إيجَادُ مَالٍ لإنْجَازِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19620, 'تَمَنْدُلٌ', 'تمندل', 'مصدر', 'ندل', 'تمندل', 'تمندل', 'مص. تَمَنْدَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَنْدُلٌ-تَمَنْدُلٌ [ن د ل] (مص. تَمَنْدَلَ). 1.""التَّمَنْدُلُ بِالمِنْدِيلِ"" : مَسْحُ اليَديْنِ أوِ الوَجْهِ بِهِ. 2.""التَّمَنْدُلُ بِالمِنْدِيلِ"" : شَدُّ الرَّأْسِ بِهِ كَالعِمَامَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19621, 'تَمَنْطُقٌ', 'تمنطق', 'مصدر', 'نطق', 'تمنطق', 'تمنطق', 'مص. تَمَنْطَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَنْطُقٌ-تَمَنْطُقٌ [ن ط ق] (مص. تَمَنْطَقَ). 1.""تَمَنْطُقُ الشَّيْخِ"": شَدُّ وَسَطِهِ بِالْمِنْطَقَةِ. 2. ""تَمَنْطُقُ العَالِمِ"": تَحَدُّثُهُ بِالْمَنْطِقِ، تَعَاطِيهِ عِلْمَ الْمَنْطِقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19622, 'تَمنُّعٌ', 'تمنع', 'مصدر', 'منع', 'تمنع', 'تمنع', 'مص. تَمَنَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمنُّعٌ-تَمنُّعٌ [م ن ع] (مص. تَمَنَّعَ). 1. ""تمَنُّعُ دُخُولِ الغَابَةِ"": اِمْتِنَاعُ دُخُولِهَا. 2. ""التَّمَنُّعُ بِالأَهْلِ"": الاحْتِمَاءُ، التَّقَوِّي بِهِمْ. 3. ""التَّمَنُّعُ عَنِ اللَّهْوِ"" : الكَفُّ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19623, 'تَمَنُّنٌ', 'تمنن', 'مصدر', 'منن', 'تمنن', 'تمن', 'مص. تَمَنَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَنُّنٌ-تَمَنُّنٌ [م ن ن] (مص. تَمَنَّنَ). ""التَّمَنُّنُ عَلَى الرَّجُلِ"" : تَذْكِيرُهُ بِمِنَّةٍ وَتقْرِيعُهُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19624, 'تَمَنِّي', 'تمني', 'مصدر', 'مني', 'تمني', 'تمن', 'مص. تَمَنَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَمَنٍّ-تَمَنٍّ، التَّمَنِّي [م ن ي] (مص. تَمَنَّى). 1.""مَا نَيْلُ الْمَطَالِبِ بِالتَّمَنِّي"" : لاَ يَكْفِي طَلَبُ حُصُولِ الْمَطَالِبِ بِالآمَالِ وَالرَّغْبَةِ فِيهَا. 2. ""لَيْتَ الشَّبَابَ يَعُودُ"" : لَيْتَ أدَاةُ تَمَنٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19625, 'تَمَهُّدٌ', 'تمهد', 'مصدر', 'مهد', 'تمهد', 'تمهد', 'مص. تَمَهَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَهُّدٌ-تَمَهُّدٌ [م هـ د] (مص. تَمَهَّدَ). 1. ""تَمَهُّدُ الْمَوضُوعِ لَهُ"" : تَسَهُّلُهُ لَهُ. 2. ""تَمَهُّدُ الفِرَاشِ"" : بَسْطُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19626, 'تَمَهُّلٌ', 'تمهل', 'مصدر', 'مهل', 'تمهل', 'تمهل', 'مص. تَمَهَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَهُّلٌ-تَمَهُّلٌ [م هـ ل] (مص. تَمَهَّلَ). ""يُعَالِجُ قَضَايَاهُ بِتَمَهُّلٍ"" : بِتَأنٍّ، بِتُؤَدَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19627, 'تَموُّجٌ', 'تموج', 'مصدر', 'موج', 'تموج', 'تمج', 'مص. تَمَوَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. تَمَوَّجَ). 1.""تَمَوُّجُ البَحْرِ"" : تَوَالي أمْوَاجِهِ. 2. ""تَمَوُّجُ التَّيَّارِ"": اِضْطِرَابُهُ، هَيَجَانُهُ. ""تَوَلَّدَ بَيْنَ تَمَوُّجَاتِ الأَثِيرِ اهْتِزَازٌ وَارْتِعَاشٌ"". (جبران خ. جبران)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19628, 'تَمَوُّرٌ', 'تمور', 'مصدر', 'مور', 'تمور', 'تمر', 'مص. تَمَوَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَوُّرٌ-تَمَوُّرٌ [م و ر] (مص. تَمَوَّرَ). 1. ""تَمَوُّرُ الشَّيْءِ"" : تَحَرُّكُهُ، اِضْطِرَابُهُ. 2. ""تَمَوُّرُ الرَّجُلِ"" : مَجِيئُهُ وَذَهَابُهُ مُتَرَدِّداً. 3. ""تَمَوُّرُ الوَبرِ عَنِ الدَّابَّةِ"" : سُقُوطُهُ. 4.""تَمَوُّرُ الشَّعْرِ"" : ذَهَابُهُ يَمْنَةً وَيَسْرَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19629, 'تَنَابُزٌ', 'تنابز', 'مصدر', 'نبز', 'تنابز', 'تنبز', 'مص. تَنَابَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَابُزٌ-تَنَابُزٌ [ن ب ز] (مص. تَنَابَزَ). ""التَّنَابُزُ بِالأَلْقَابِ"" : التَّعَايُرُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19630, 'تَمَوُّنٌ', 'تمون', 'مصدر', 'مون', 'تمون', 'تمن', 'مص. تَمَوَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَوُّنٌ-تَمَوُّنٌ [م و ن] (مص. تَمَوَّنَ). ""تَمَوُّنُ الْمُسَافِرِ فِي رِحْلَتِهِ"" : تَجَهُّزُهُ بِمَا يَحْتَاجُهُ مِنْ مَؤُونَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19631, 'تَمَوُّهٌ', 'تموه', 'مصدر', 'موه', 'تموه', 'تمه', 'مص. تَمَوَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَوُّهٌ-تَمَوُّهٌ [م و هـ] (مص. تَمَوَّهَ). 1.""تَمَوُّهُ الحَقِيقَةِ"" : اِمْتِزَاجُ، اِخْتِلاَطُ الحَقِّ فِيهَا بِالبَاطِلِ. 2.""تَمَوُّهُ الْمَعْدِنِ"" : طَلْيُهُ بِالفِضَّةِ أَوِ الذَّهَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19632, 'تَمَيُّدٌ', 'تميد', 'مصدر', 'ميد', 'تميد', 'تمد', 'مص. تَميَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَيُّدٌ-تَمَيُّدٌ [م ي د] (مص. تَميَّدَ). ""تَمَيُّدُ الْمَرْأةِ"" : تَمايُلُهَا، تَبَخْتُرُهَا فِي مِشْيَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19633, 'تَمَيُّزٌ', 'تميز', 'مصدر', 'ميز', 'تميز', 'تمز', 'مص. تَمَيَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَيُّزٌ-تَمَيُّزٌ [م ي ز] (مص. تَمَيَّزَ). 1.""تَمَيُّزُ الرَّجُلِ"" : اِمْتِيَازُهُ، اِنْفِرَادُهُ. 2.""تَمَيُّزُ اللَّوْنِ الأخْضَرِ عَنِ الأزْرَقِ"" : اِنْفِصَالُهُ، اِنْعِزَالُهُ. 3.""تَمَيُّزُهُ بِالأَخْلاَقِ الحَمِيدَةِ"" : اِتِّصَافُهُ. 4.""تَمَيُّزُ الرَّجُلِ مِنَ الغَضَبِ"" : تَقَطُّعُهُ مِنَ الغَضَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19634, 'تَمَيُّسٌ', 'تميس', 'مصدر', 'ميس', 'تميس', 'تمس', 'مص. تَمَيَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَيُّسٌ-تَمَيُّسٌ [م ي س] (مص. تَمَيَّسَ). تَمَيُّسُ الرَّجُلِ"" : تَمَايُلُهُ، تَبَخْتُرُهُ فِي مَشْيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19635, 'تَمَيُّعٌ', 'تميع', 'مصدر', 'ميع', 'تميع', 'تمع', 'مص. تَميَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَيُّعٌ-تَمَيُّعٌ [م ي ع] (مص. تَميَّعَ). 1.""تَمَيُّعُ السَّائِلِ"" : سيلانُهُ، ذَوَبَابُهُ. 2. ""تَمَيُّعُ الرَّجُلِ"" : سُوءُ أَخْلاقِهِ وفَسَادُهَا، تَحَمُّقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19636, 'تَمَيُّلٌ', 'تميل', 'مصدر', 'ميل', 'تميل', 'تمل', 'مص. تَمَيَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمَيُّلٌ-تَمَيُّلٌ [م ي ل] (مص. تَمَيَّلَ). ""تَمَيُّلُ الرَّجُلِ فِي مَشْيِهِ"" : تَبَخْتُرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19637, 'تَنَائِي', 'تنائي', 'مصدر', 'نأي', 'تناءي', 'تن', 'مص. تَنَاءَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنَاءٍ-تَنَاءٍ، التَّنائِي [ن أي] (مص. تَنَاءَى). ""التَّنَائِي عَنِ الْمَكَانِ"" : الاِبْتِعَادُ، البُعْدُ، التَّبَاعُدُ عَنْهُ. ""أضْحَى التَّنَائِي بَدِيلاً عَنْ تَدَانِينَا"". (ابن زيدون)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19638, 'تَنَابُذٌ', 'تنابذ', 'مصدر', 'نبذ', 'تنابذ', 'تنبذ', 'مص. تَنَابَذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَابُذٌ-تَنَابُذٌ [ن ب ذ] (مص. تَنَابَذَ). ""تَنَابُذُ الأوْلاَدِ"" : اِخْتِلافُهُمْ، اِفْتِراقُهُمْ عَلَى أَثَرِ خِصامٍ وَعَداوَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19639, 'تَنَازُلٌ', 'تنازل', 'مصدر', 'نزل', 'تنازل', 'تنزل', 'مص. تَنَازَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَازُلٌ-تَنَازُلٌ [ن ز ل] (مص. تَنَازَلَ). ""لَيْسَ مِنَ الصَّوَابِ التَّنَازُلُ عَنْ الحُقُوقِ"" : التَّخَلِّي عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19640, 'تَنَابُلٌ', 'تنابل', 'مصدر', 'نبل', 'تنابل', 'تنبل', 'مص. تنَابَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَابُلٌ-تَنَابُلٌ [ن ب ل] (مص. تنَابَلَ). 1 ""تَنَابُلُ النَّاسِ"" : التَّفَاخُرُ أيُّهُمْ أجْوَدُ نُبْلاً. 2. ""تَنَابُلُ الفُرْسَانِ"" : تَفَاخُرُهُمْ أيُّهُمْ أبْرَعُ فِي صُنْعِ النَّبْل، أيِ السِّهَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19641, 'تَنَاثُرٌ', 'تناثر', 'مصدر', 'نثر', 'تناثر', 'تنثر', 'مص. تَنَاثَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاثُرٌ-تَنَاثُرٌ [ن ث ر] (مص. تَنَاثَرَ). 1. ""تَنَاثُرُ أوْرَاقِ الخَرِيفِ"" : تَسَاقُطُهَا مُتَفَرِّقَةً. 2. ""تَنَاثُرُ الغُبَارِ"" : تَشَتُّتُهُ، تَفَرُّقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19642, 'تَنَاجِي', 'تناجي', 'مصدر', 'نجو', 'تناجي', 'تنج', 'مص. تَنَاجَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنَاجٍ-تَنَاجٍ، التَّنَاجِي [ن ج و] (مص. تَنَاجَى). 1.""تَنَاجِي العَاشِقَيْنِ"" : تَسَارُّهُمَا، أيْ كَشْفُ كُلِّ وَاحِدٍ مِنْهُمَا لِلْآخَرِ عَنْ عَوَاطِفِهِ. ""كَانَ فِي لَحْظَةِ تَنَاجٍ"". 2. ""أرَادَ التَّنَاجِيَ فِي مَكَانٍ بَعِيدٍ"" : التَّحَدُّثَ سِرّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19643, 'تَنَاحُرٌ', 'تناحر', 'مصدر', 'نحر', 'تناحر', 'تنحر', 'مص. تَنَاَحَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاحُرٌ-تَنَاحُرٌ [ن ح ر] (مص. تَنَاَحَرَ). 1. ""تَنَاحُرُ الأعْدَاءِ"" : تَقَاتُلُهُمْ بِشِدَّةٍ. 2. ""التَّنَاحُرُ عَلَى الغَنِيمَةِ"" : التَّخَاصُمُ عَلَيْهَا بِعُنْفٍ وَقُوَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19644, 'تَنَاحُسٌ', 'تناحس', 'مصدر', 'نحس', 'تناحس', 'تنحس', 'مص. تَنَاحَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاحُسٌ-تَنَاحُسٌ [ن ح س] (مص. تَنَاحَسَ). ""تَنَاحُسُ حَظِّهِ"": اِنْتِحَاسُهُ، اِنْتِكَاسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19645, 'تَنَادٌّ', 'تناد', 'مصدر', 'ندد', 'تناد', 'تند', 'مص. تَنَادَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَادٌّ-تَنَادٌّ [ن د د] (مص. تَنَادَّ). ""يَوْمُ التَّنَادِّ"" : يَوْمُ القِيامَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19646, 'تَنَادُمٌ', 'تنادم', 'مصدر', 'ندم', 'تنادم', 'تندم', 'مص. تَنَادَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَادُمٌ-تَنَادُمٌ [ن د م] (مص. تَنَادَمَ). ""التَّنَادُمُ عَلَى الشَّرَابِ"" : سَقْيُ بَعْضِهِمْ بَعْضاً الشَّرَابَ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19647, 'تَنَادِي', 'تنادي', 'مصدر', 'ندو', 'تنادي', 'تند', 'مص. تَنَادَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنَادٍ-تَنَادٍ، التَّنَادِي [ن د و] (مص. تَنَادَى). 1.""التَّنَادِي بِالأَسْمَاءِ"" : مُنَادَاةُ بَعْضِهِمْ بَعْضاً. 2. ""التَّنَادِي فِي النَّادِي"" : الاجْتِمَاعُ فِي النَّادِي. 3. ""يَوْمُ التَّنَادِي"" : يَوْمُ القِيَامَةِ. غافر آية 32 وَيَا قَوْمِ إنِّي أخَافُ عَليْكُمْ يَوْمَ التَّنَادِي .(قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19648, 'تَنَازُعٌ', 'تنازع', 'مصدر', 'نزع', 'تنازع', 'تنزع', 'مص. تَنَازَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَازُعٌ-تَنَازُعٌ [ن ز ع] (مص. تَنَازَعَ). 1. ""حَصَلَ تَنَازُعٌ بَيْنَهُمْ"" : اِخْتِلاَفٌ، صِرَاعٌ، شَنَآنٌ. 2. ""تَنَازُعُ الْمُحْتَضِرِ"" : بِهِ حَشْرَجَةُ الْمَوْتِ. 3. ""تَنَازُعُ البَقَاءِ"" : الصِّرَاعُ والتَّعَارُكُ عَلَى البَقَاءِ لِمَنْ هُوَ أصْلَحُ وَأكْمَلُ. 4. ""التَّنَازُعُ فِي النَّحْوِ"" : وُجُودُ عَامِلَيْنِ، فِعليْنِ أو اِسْمَيْنِ، يَعْمَلاَنِ فِي مَعْمُولٍ وَاحدٍ مُتَأخِّرٍ، ويَتَنَازَعُهُ العَامِلاَنِ نحو : ""زَارَني واستَقْبَلْتُ أخَاكَ بِحَفَاوَة""، والتَّنَازُعُ هُنَا وَقَعَ بَيْنَ فِعْلَيْنِ مُتَصَرِّفَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19649, 'تَنَاصُفٌ', 'تناصف', 'مصدر', 'نصف', 'تناصف', 'تنصف', 'مص. تَنَاصَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاصُفٌ-تَنَاصُفٌ [ن ص ف] (مص. تَنَاصَفَ). ""اِقْتَنَعُوا أخِيراً بِالتَّنَاصُفِ"" : إنْصَافُ بَعْضِهِمْ بَعْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19650, 'تَنَاسُبٌ', 'تناسب', 'مصدر', 'نسب', 'تناسب', 'تنسب', 'مص. تَنَاسَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاسُبٌ-تَنَاسُبٌ [ن س ب] (مص. تَنَاسَبَ). 1.""تَنَاسُبُ الألْوَانِ"" : تَنَاسُقُها، اِنْسِجَامُهَا. 2.""تَنَاسُبُ القَوْمِ إلَى أحْسَابِهِمْ"" : اِنْتِسَابُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19651, 'تَنَاسُخٌ', 'تناسخ', 'مصدر', 'نسخ', 'تناسخ', 'تنسخ', 'مص. تَنَاسَخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاسُخٌ-تَنَاسُخٌ [ن س خ] (مص. تَنَاسَخَ). 1.""تَنَاسُخُ الأَزْمِنَةِ"": تَتَابُعُهَا وَتَدَاوُلُهَا. 2.""تَنَاسُخُ الحُكْمَيْنِ"" : نَسْخُ أحَدِهِمَا الآخَرَ. 3.""تَنَاسُخُ الأَرْوَاحِ"" : اِنْتِقَالُهَا مِنْ أجْسَامِهَا إلَى أجْسَامٍ أُخْرَى بَعْدَ الْمَوْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19652, 'تَنَاسُقٌ', 'تناسق', 'مصدر', 'نسق', 'تناسق', 'تنسق', 'مص. تَنَاسَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاسُقٌ-تَنَاسُقٌ [ن س ق] (مص. تَنَاسَقَ). 1. ""تَنَاسُقُ الألْوَانِ"": تَنَاسُبُهَا، تَوَافُقُهَا. 2. ""جَاءتْ أفْكَارُهُ فِي تَنَاسُقٍ تَامٍّ"": فِي انْتِظَامٍ وَانْسِجَامٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19653, 'تَنَاسُلٌ', 'تناسل', 'مصدر', 'نسل', 'تناسل', 'تنسل', 'مص. تَنَاسَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَنَاسُلٌ-تَنَاسُلٌ [ن س ل] (مص. تَنَاسَلَ). 1.""شَعْبٌ فِي تَنَاسُلٍ مُسْتَمِرٍّ"" : فِي تَوَالُدٍ دَائِمٍ. 2.""أعْضَاءُ التَّنَاسُل"" : الأعْضَاءُ الجِنْسِيَّةُ لِلذَّكَرِ وَالأُنْثَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19654, 'تَنَاسِي', 'تناسي', 'مصدر', 'نسي', 'تناسي', 'تنس', 'مص. تَنَاسَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنَاسٍ-تَنَاسٍ، التَّنَاسِي [ن س ي] (مص. تَنَاسَى). ""تَنَاسِي الوَاجِبِ"" : نِسْيَانُهُ تَعَمُّداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19655, 'تَنَاشُدٌ', 'تناشد', 'مصدر', 'نشد', 'تناشد', 'تنشد', 'مص. تَناشَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاشُدٌ-تَنَاشُدٌ [ن ش د] (مص. تَناشَدَ). ""تَنَاشُدُ الشُّعَرَاءِ أشْعَارَهُمْ"" : إنْشَادُ بَعْضِهِمْ بَعْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19656, 'تَنَاصٌّ', 'تناص', 'مصدر', 'نصص', 'تناص', 'تنص', 'مص. تَنَاصَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاصٌّ-تَنَاصٌّ [ن ص ص] (مص. تَنَاصَّ). 1.""تَنَاصُّ النَّاسِ"" : اِزْدِحَامُهُمْ. 2. ""التَّنَاصُّ في الأَدَبِ"": مُصْطَلَحٌ نَقْدِيٌّ يُقْصَدُ بِهِ وُجُودُ تَشَابُهٍ بَيْنَ نَصٍّ وَآخَرَ أَوْ بَيْنَ عِدَّةِ نُصُوصٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19657, 'تَنَاصُبٌ', 'تناصب', 'مصدر', 'نصب', 'تناصب', 'تنصب', 'مص. تنَاصَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاصُبٌ-تَنَاصُبٌ [ن ص ب] (مص. تنَاصَبَ). تَنَاصُبُ الشَّيْءِ"": تَقَاسُمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19658, 'تَنَاصُرٌ', 'تناصر', 'مصدر', 'نصر', 'تناصر', 'تنصر', 'مص. تَناصَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاصُرٌ-تَنَاصُرٌ [ن ص ر] (مص. تَناصَرَ). ""حَقَّقَ تَناصُرُهُمْ نَجَاحاً فِي الْمَعْرَكَةِ"" : نَصْرُ بَعْضِهِمْ بَعْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19659, 'تَنَافُسٌ', 'تنافس', 'مصدر', 'نفس', 'تنافس', 'تنفس', 'مص. تَنَافُسٌ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَافُسٌ-تَنَافُسٌ [ن ف س] (مص. تَنَافُسٌ). 1. ""تَنَافُسٌ رِيَاضِيٌّ"" : تَسَابُقٌ. 2. ""التَّنَافُسُ فِي الخَيْرِ"" : التَّرَاغُبُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19660, 'تَنَاضُلٌ', 'تناضل', 'مصدر', 'نضل', 'تناضل', 'تنضل', 'مص. تَنَاضَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاضُلٌ-تَنَاضُلٌ [ن ض ل] (مص. تَنَاضَلَ). 1. ""تَنَاضُلُ الفُرْسَانِ"" : تَبَارِيهمْ فِي رَمْيِ السِّهَامِ. 2. ""تَنَاضُلُ النَّاسِ"" : تَفَاخُرُهُمْ. 3. ""تَنَاضُلُ السِّيَاسِيِّينَ"" : تَدَافُعُهُمْ فِي النِّضَالِ بِحَمَاسٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19661, 'تَنَاطُحٌ', 'تناطح', 'مصدر', 'نطح', 'تناطح', 'تنطح', 'مص. تَنَاطَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاطُحٌ-تَنَاطُحٌ [ن ط ح] (مص. تَنَاطَحَ). ""تَنَاطُحُ الثَّوْرَيْنِ"" : نَطْحُ كُلٍّ مِنْهُمَا الآخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19662, 'تَنَاظُرٌ', 'تناظر', 'مصدر', 'نظر', 'تناظر', 'تنظر', 'مص. تَنَاظَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاظُرٌ-تَنَاظُرٌ [ن ظ ر] (مص. تَنَاظَرَ). 1. ""فَهِمَ مِنْ تَنَاظُرِهِمْ أنَّهُمْ يُرِيدُونَ الإيقَاعَ بِهِ"" : نَظَرُ بَعْضِهِمْ بَعْضاً. 2. ""تَنَاظُرُ النَّوَافِذِ"" : تَقَابُلُهَا. 3. ""تَنَاظُرُ الجَمَاعَةِ"" : تَجَادُلُهَا وتحَاجُّهَا فِي قَضِيَّةٍ مِنَ القَضَايَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19663, 'تَنَاعُتٌ', 'تناعت', 'مصدر', 'نعت', 'تناعت', 'تنعت', 'مص. تنَاعَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاعُتٌ-تَنَاعُتٌ [ن ع ت] (مص. تنَاعَتَ). ""كَانَ تَنَاعُتُهُمْ إيَّاهُ دَقِيقاً"" : وَصْفُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19664, 'تَنَاعُسٌ', 'تناعس', 'مصدر', 'نعس', 'تناعس', 'تنعس', 'مص. تَنَاعَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاعُسٌ-تَنَاعُسٌ [ن ع س] (مص. تَنَاعَسَ). ""أظْهَرُوا التَّنَاعُسَ"": التَّنَاوُمَ، أيْ أظْهَرُوا النَّوْمَ وَلَيْسَ بِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19665, 'تنَاعُمٌ', 'تناعم', 'مصدر', 'نعم', 'تناعم', 'تنعم', 'مص. تَنَاعَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تنَاعُمٌ-تنَاعُمٌ [ن ع م] (مص. تَنَاعَمَ). ""تَنَاعُمُ الرَّجُلِ"" : تَرَفُّهُهُ، تَنَعُّمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19666, 'تَنَاعِي', 'تناعي', 'مصدر', 'نعي', 'تناعي', 'تنع', 'مص. تنَاعَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنَاعٍ-تَنَاعٍ، التَّنَاعِي [ن ع ي] (مص. تنَاعَى).""تَنَاعِي الجمَاعَةِ"" : نَعْيُ قتْلاها لِتحْرِيضِ أفْرَادِهَا عَلَى أَخْذِ الثَّأْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19667, 'تَنَاغِي', 'تناغي', 'مصدر', 'نغو', 'تناغي', 'تنغ', 'مص. تَنَاغَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنَاغٍ-تَنَاغٍ، التَّنَاغِي [ن غ و] (مص. تَنَاغَى). ""تَنَاغِي العَاشِقَيْنِ"" : تَنَاجِيهِمَا، مُلاطَفَةُ أحَدِهِما الآخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19668, 'تَنَافُرٌ', 'تنافر', 'مصدر', 'نفر', 'تنافر', 'تنفر', 'مص. تَنَافَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَافُرٌ-تَنَافُرٌ [ن ف ر] (مص. تَنَافَرَ). 1.""تَنَافُرُ الأعْداءِ"" : تَخَاصُمُهُمْ، كُرْهُ بَعْضِهِمْ بَعْضاً. 2.""تَنَافُرُ الألْوَانِ"" : تَعَارُضُهَا. 3.""تَنَافُرُ الأصْوَاتِ"" : نَشَازُهَا، عَدَمُ تَنَاسُقِهَا وَانْسِجَامِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19669, 'تَنَاهُضٌ', 'تناهض', 'مصدر', 'نهض', 'تناهض', 'تنهض', 'مص. تَنَاهَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاهُضٌ-تَنَاهُضٌ [ن هـ ض] (مص. تَنَاهَضَ). ""تَنَاهُضُ القَوْم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19670, 'تَنَافِي', 'تنافي', 'مصدر', 'نفي', 'تنافي', 'تنف', 'مص. تَنَافَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنَافٍ-تَنَافٍ، التَّنَافِي [ن ف ي] (مص. تَنَافَى). ""تَنَافِي الآرَاءِ"": تَعَارُضُهَا، تَبَايُنُهَا. ""أضْحَتْ آرَاؤُهُمْ فِي تَنَافٍ تَامٍّ وَلَمْ يَعُدْ مِنْ سَبِيلٍ للتَّفاهُمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19671, 'تَنَاقُصٌ', 'تناقص', 'مصدر', 'نقص', 'تناقص', 'تنقص', 'مص. تنَاقَصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاقُصٌ-تَنَاقُصٌ [ن ق ص] (مص. تنَاقَصَ). ""تَنَاقُصُ الشَّيْءِ"": نَقْصُهُ شَيْئاً فَشَيْئاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19672, 'تَنَاقُضٌ', 'تناقض', 'مصدر', 'نقض', 'تناقض', 'تنقض', 'مص. تنَاقَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاقُضٌ-تَنَاقُضٌ [ن ق ض] (مص. تنَاقَضَ). 1.""في كَلاَمِهِ تَنَاقُضٌ، فَهُوَ لاَ يَثْبُتُ عَلَى رَأْيٍ"" : تَخَالُفٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19673, 'تَنَاقُلٌ', 'تناقل', 'مصدر', 'نقل', 'تناقل', 'تنقل', 'مص. تَنَاقَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاقُلٌ-تَنَاقُلٌ [ن ق ل] (مص. تَنَاقَلَ). ""تَنَاقُلُ الأخْبارِ"" : تَدَاوُلُهَا، أيْ نَقْلُهَا مِنْ يَدٍ إلَى يَدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19674, 'تَنَاكُحٌ', 'تناكح', 'مصدر', 'نكح', 'تناكح', 'تنكح', 'مص. تَنَاكَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاكُحٌ-تَنَاكُحٌ [ن ك ح] (مص. تَنَاكَحَ). 1.""تَنَاكُحُ الجَمَاعَةِ"": تَزَوُّجُ بَعْضِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19675, 'تَنَاكُرٌ', 'تناكر', 'مصدر', 'نكر', 'تناكر', 'تنكر', 'مص. تَنَاكَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاكُرٌ-تَنَاكُرٌ [ن ك ر] (مص. تَنَاكَرَ). 1.""تَنَاكُرُ الرَّجُلَيْنِ"" : إِنْكَارُ أحَدِهِمَا الآخَرَ. 2.""تَنَاكُرُ الأمْرِ"" : اِدِّعَاءُ جَهْلِهِ. 3.""تَنَاكُرُ القَوْمِ"" : تَعَادِيهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19676, 'تَنَامِي', 'تنامي', 'مصدر', 'نمي', 'تنامي', 'تنم', 'مص. تَنَامَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنَامٍ-تَنَامٍ، التَّنَامِي [ن م ي] (مص. تَنَام"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19677, 'تَنَاهُدٌ', 'تناهد', 'مصدر', 'نهد', 'تناهد', 'تنهد', 'مص. تَنَاهَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاهُدٌ-تَنَاهُدٌ [ن هـ د] (مص. تَنَاهَدَ). ""تَنَاهُدُ القَوْمِ"" : نُهُوضُ بَعْضِهِمْ إلَى بَعْضٍ لِلمُحَارَبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19678, 'تَنَاهُشٌ', 'تناهش', 'مصدر', 'نهش', 'تناهش', 'تنهش', 'مص. تَنَاهَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاهُشٌ-تَنَاهُشٌ [ن هـ ش] (مص. تَنَاهَشَ). ""تَن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19679, 'تَنَجُّحٌ', 'تنجح', 'مصدر', 'نجح', 'تنجح', 'تنجح', 'مص. تَنَجَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَجُّحٌ-تَنَجُّحٌ [ن ج ح] (مص. تَنَجَّحَ). ""تَنَجُّحُ الحَاجَةِ"" : طَلَبُ إِنْجَازِهَا وَقَضَائِهَا، تَنَجُّزُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19680, 'تَنَاهِي', 'تناهي', 'مصدر', 'نهي', 'تناهي', 'تنه', 'مص. تنَاهَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنَاهٍ-تَنَاهٍ، التَّنَاهِي [ن هـ ي] (مص. تنَاهَى). 1. ""تَنَاهِي الخَبرِ إِلَى عِلْمِهِ"" : بُلُوغُهُ إلَى سَمْعِهِ. 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19681, 'تَنَاوُبٌ', 'تناوب', 'مصدر', 'نوب', 'تناوب', 'تنب', 'مص. تَناوَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاوُبٌ-تَنَاوُبٌ [ن و ب] (مص. تَناوَبَ). 1. ""التَّنَاوُبُ عَلَى الحِرَاسَةِ"" : التَّعَاقُبُ. 2. ""بِالتَّنَاوُبِ"" : بِالتَّدَاوُلِ، بِالتَّتَابُعِ. 3.""حُك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19682, 'تَنَاوُلٌ', 'تناول', 'مصدر', 'نول', 'تناول', 'تنل', 'مص. تَنَاوَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاوُلٌ-تَنَاوُلٌ [ن و ل] (مص. تَنَاوَلَ). 1. ""لَمْ يَتَمَكَّنْ مِنْ تَنَاوُلِ الطَّعَامِ فِي بَيْتِهِ"" : مِنْ أكْلِهِ. 2. ""التَّنَاوُلُ عِنْدَ الْمَسِيحِيِّينَ"" : تَقَبُّلُ القُرْبَانِ الْمُقَدَّسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19683, 'تَنَاوُمٌ', 'تناوم', 'مصدر', 'نوم', 'تناوم', 'تنم', 'مص. تَنَاوَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَاوُمٌ-تَنَاوُمٌ [ن و م] (مص. تَنَاوَمَ). 1. ""تَنَاوُمُ الأوْلاَدِ"" : تَظَاهُرُهُمْ بِالنَّوْمِ، تَنَاعُسُهُمْ. 2. ""التَّنَاوُمُ إلَى الأُمِّ"" : السُّكُونُ والاطْمِئْنَانُ إلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19684, 'تَنَبُّؤٌ', 'تنبؤ', 'مصدر', 'نبأ', 'تنبء', 'تنب', 'مص. تَنبَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَنَبُّؤٌ-تَنَبُّؤٌ [ن ب أ] (مص. تَنبَّأَ). ""مِنَ الصَّعْبِ التَّنَبُّؤُ بِمَا سَيَحْدُثُ"" : التَّكَهُّنُ بِالغَيْبِ، التَّوَقُّعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19685, 'تَنَبُّلٌ', 'تنبل', 'مصدر', 'نبل', 'تنبل', 'تنبل', 'مص. تَنَبَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَبُّلٌ-تَنَبُّلٌ [ن ب ل] (مص. تَنَبَّلَ). ""تَنَبُّلُ الرَّجُلِ"" : تَكَلُّفُهُ النُّبْلَ وَتَشَبُّهُهُ بِالنُّبَلاءِ. ""إنَّ النَّبِيلَ يَكْفِيهِ نُبْلُهُ عَنِ التَّنَبُّلِ"". (الجاحظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19686, 'تَنَبُّهٌ', 'تنبه', 'مصدر', 'نبه', 'تنبه', 'تنبه', 'مص. تَنَبَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَبُّهٌ-تَنَبُّهٌ [ن ب هـ] (مص. تَنَبَّهَ). 1. ""التَّنَبُّهُ مِنَ النَّوْمِ"" : الاِسْتِيقاظُ. 2. ""التَّنَبُّهُ لِلْمَخَاطِرِ"" : حُضُورُ فِطْنَتِهِ، إدْرَاكُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19687, 'تَنَتُّفٌ', 'تنتف', 'مصدر', 'نتف', 'تنتف', 'تنتف', 'مص. تَنَتَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَتُّفٌ-تَنَتُّفٌ [ن ت ف] (مص. تَنَتَّفَ). 1. ""تَنَتُّفُ ريشِ النَّعَامِ"" : اِنْتِزَاعُهُ. 2.""تَنَتُّفُ الشَّعْرِ"" : نَزْعُهُ، نَتْفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19688, 'تَنَثُّرٌ', 'تنثر', 'مصدر', 'نثر', 'تنثر', 'تنثر', 'مص. تَنَثَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَثُّرٌ-تَنَثُّرٌ [ن ث ر] (مص. تَنَثَّرَ). 1.""تَنَثُّرُ الغُبَارِ"" : تَطَايُرُهُ مُتَفَرِّقاً. 2.""تَنَاثُرُ أوْرَاقِ الشَّجَرِ"" : تَسَاقُطُهَا، تَنَاثُرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19689, 'تَنَدِّي', 'تندي', 'مصدر', 'ندي', 'تندي', 'تند', 'مص. تَنَدَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنَدٍّ-تَنَدٍّ، التَّنَدِّي [ن د ي] (مص. تَنَدَّى). ""تَنَدِّي المكَانِ"": إصَابَتُهُ بِالنَّدَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19690, 'تَنَجُّدٌ', 'تنجد', 'مصدر', 'نجد', 'تنجد', 'تنجد', 'مص. تَنَجَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَجُّدٌ-تَنَجُّدٌ [ن ج د] (مص. تَنَجَّدَ). ""تَنَجُّدُ الشَّيْءِ"" : اِرْتِفَاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19691, 'تَنَجُّزٌ', 'تنجز', 'مصدر', 'نجز', 'تنجز', 'تنجز', 'مص. تَنَجَّز', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَجُّزٌ-تَنَجُّزٌ [ن ج ز] (مص. تَنَجَّز). 1.""تَنَجُّزُ العَمَلِ"" : طَلَبُ إنْجَازِهِ وَقَضَائِهِ، تَنَجُّجُهُ. 2.""تَنَجَّزَ الشَّرَابَ"": بَالَغَ فِي شُرْبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19692, 'تَنجُّسٌ', 'تنجس', 'مصدر', 'نجس', 'تنجس', 'تنجس', 'مص. تَنَجَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنجُّسٌ-تَنجُّسٌ [ن ج س] (مص. تَنَجَّسَ). 1. ""تَنَجُّسُ الْمَكانِ"": صَيْرُهُ نَجِساً، مُدَنَّساً. 2. ""تَنَجُّسُ الثَّوْبِ"" : تَلَطُّخُهُ بِالنَّجَاسَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19693, 'تَنَجُّعٌ', 'تنجع', 'مصدر', 'نجع', 'تنجع', 'تنجع', 'مص. تَنَجَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَجُّعٌ-تَنَجُّعٌ [ن ج ع] (مص. تَنَجَّعَ). 1.""تَنَجُّعُ العُشْبِ"" : طَلَبُهُ فِي مَوَاضِعِهِ. 2.""التَّنَجُّعُ بِالدَّمِ"" : التَّلَطُّخُ بِهِ. 3.""تَنَجُّعُ الصَّدِيقِ"" : قَصْدُهُ لِطَلَبِ مَعْرُوفِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19694, 'تَنَجُّمٌ', 'تنجم', 'مصدر', 'نجم', 'تنجم', 'تنجم', 'مص. تَنَجَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَجُّمٌ-تَنَجُّمٌ [ن ج م] (مص. تَنَجَّمَ). ""تَنَجُّمُ الرَّجُلِ"" : مُرَاقَبَتُهُ النُّجُومَ، أَوْ تَتَبُّعُهَا مِنْ سَهَرٍ أَوْ أَرَقٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19695, 'تَنَحُّلٌ', 'تنحل', 'مصدر', 'نحل', 'تنحل', 'تنحل', 'مص. تَنَحَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَحُّلٌ-تَنَحُّلٌ [ن ح ل] (مص. تَنَحَّلَ). ""تَنَحُّلُ مَوْضُوعٍ"" : اِنْتِحالُهُ، اِدِّعَاؤُهُ لِنَفْسِهِ وَهُوَ لِغَيْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19696, 'تَنَحْنُحٌ', 'تنحنح', 'مصدر', 'نحنح', 'تنحنح', 'تنحنح', 'مص. تَنَحْنَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَحْنُحٌ-تَنَحْنُحٌ [ن ح ن ح] (مص. تَنَحْنَحَ). ""اِشْتَدَّ تَنَحْنُحُهُ"": تَرَدُّدُ صَوْتِهِ فِي حَنْجَرَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19697, 'تَنَحِّي', 'تنحي', 'مصدر', 'نحو', 'تنحي', 'تنح', 'مص. تَنَحَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنَحٍّ-تَنَحٍّ، التَّنَحِّي [ن ح و] (مص. تَنَحَّى). ""التَّنَحِّي عَنِ الْمَكَانِ"" : تَرْكُهُ، اِعْتِزَالُهُ، البُعْدُ عَنْهُ. ""التَّنَحِّي عَنِ الْمَنْصِبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19698, 'تَنَدُّمٌ', 'تندم', 'مصدر', 'ندم', 'تندم', 'تندم', 'مص. تَنَدَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَدُّمٌ-تَنَدُّمٌ [ن د م] (مص. تَنَدَّمَ). ""عَاشَ لَحْظَةَ تَنَدُّمٍ"" : لَحْظَة أسَفٍ وَتَحَسُّرٍ، نَدَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19699, 'تَنَزُّلٌ', 'تنزل', 'مصدر', 'نزل', 'تنزل', 'تنزل', 'مص. تَنَزَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَزُّلٌ-تَنَزُّلٌ [ن ز ل] (مص. تَنَزَّلَ). ""تَنَزُّلُ الرَّجُلِ"" : نُزُولُهُ فِي مُهْلَةٍ. 2. ""التَّنَزُّلُ عَنِ الحَقِّ"" : تَرْكُهُ. 3. ""سَاعَدَهُ فِي التَّنَزُّلِ"" : أيْ جَعْلُهُ يَنْزِلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19700, 'تَنَزُّهٌ', 'تنزه', 'مصدر', 'نزه', 'تنزه', 'تنزه', 'مص. تَنَزَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَزُّهٌ-تَنَزُّهٌ [ن ز هـ] (مص. تَنَزَّهَ). 1. ""خَرَجَ لِلتَّنَزُّهِ"" : خَرَجَ لِلنُّزْهَةِ. 2. ""عُرِفَ بِتَنَزُّهِهِ عَنِ الآثَامِ"" : بالابْتِعَادِ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19701, 'تَنَسُّبٌ', 'تنسب', 'مصدر', 'نسب', 'تنسب', 'تنسب', 'مص. تَنسَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَسُّبٌ-تَنَسُّبٌ [ن س ب] (مص. تَنسَّبَ). 1. "" التَّنَسُّبُ إلَى قَبِيلَةِ كَذَا"" : اِدِّعَاءُ النِّسْبَةِ إلَيْهَا. 2. ""التَّنَسُّبُ إلَيْهِ"" : اِدِّعَاءُ أنَّهُ نَسِيبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19702, 'تَنَسُّقٌ', 'تنسق', 'مصدر', 'نسق', 'تنسق', 'تنسق', 'مص. تَنَسَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَسُّقٌ-تَنَسُّقٌ [ن س ق] (مص. تَنَسَّقَ). ""تَنسُّقُ الأزْهَارِ"" : اِنْتِظَامُ بَعْضِهَا إلَى بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19703, 'تَنَسُّكٌ', 'تنسك', 'مصدر', 'نسك', 'تنسك', 'تنسك', 'مص. تَنَسَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَسُّكٌ-تَنَسُّكٌ [ن س ك] (مص. تَنَسَّكَ). ""هُوَ فِي زُهْدٍ وَتَنَسُّكٍ"" : فِي تَعَبُّدٍ، فِي تَزَهُّدٍ، فِي تَخَشُّعٍ. ""يَتَظَاهَرُونَ بِالتَّنَسُّكِ وَالتَّقَشُّفِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19704, 'تَنَسُّمٌ', 'تنسم', 'مصدر', 'نسم', 'تنسم', 'تنسم', 'مص. تَنَسَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَسُّمٌ-تَنَسُّمٌ [ن س م] (مص. تَنَسَّمَ). 1.""تَنَسُّمُ النَّسِيمِ"" : هُبُوبُهُ هُبُوباً خَفِيفاً. 2.""تَنَسُّمُهُ النَّسِيمَ خَفَّفَ مِنْ ضَيْقِهِ"" : شَمُّهُ. 3.""تَنَسُّمُ الْمَكَانِ بالطِّيِبِ"" : فَوَحَانُهُ، أَرِيجُهُ. 4.""تَنَسُّمُ الرَّجُلِ"" : تَنَفُّسُهُ. 5.""تَنَسُّمُ العِلْمِ "" : طَلَبُهُ. 6.""تَنَسُّمُ الأثَرِ"": تَتَبُّعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19705, 'تَنَشُّبٌ', 'تنشب', 'مصدر', 'نشب', 'تنشب', 'تنشب', 'مص. تَنَشَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَشُّبٌ-تَنَشُّبٌ [ن ش ب] (مص. تَنَشَّبَ). 1. ""التَّنَشُّبُ فِي الشَّيْءِ"" : العَلَقُ بِهِ. 2. ""لَمْ يُخْفِ تَنَشُّبَ قَلْبِهِ بِحُبِّهَا"" : تَعَلُّقَ قَلْبِهِ بِحُبِّهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19706, 'تَنَشُّدٌ', 'تنشد', 'مصدر', 'نشد', 'تنشد', 'تنشد', 'مص. تَنَشَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَشُّدٌ-تَنَشُّدٌ [ن ش د] (مص. تَنَشَّدَ). ""تَنَشُّدُ الأَخْبَارِ"" : طَلَبُهَا مِنْ حَيْثُ لاَ يَعْلَمُ النَّاسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19707, 'تَنَشُّرٌ', 'تنشر', 'مصدر', 'نشر', 'تنشر', 'تنشر', 'مص. تَنَشَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَشُّرٌ-تَنَشُّرٌ [ن ش ر] (مص. تَنَشَّرَ). 1. ""تَنَشُّرُ النَّهَارِ"" : اِنْبِسَاطُهُ، اِمْتِدَادُهُ. 2. ""تَنَشُّرُ الزَّرْعِ"" : تَفَرُّقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19708, 'تَنَشُّطٌ', 'تنشط', 'مصدر', 'نشط', 'تنشط', 'تنشط', 'مص. تَنَشَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَشُّطٌ-تَنَشُّطٌ [ن ش ط] (مص. تَنَشَّطَ). 1.""تَنَشُّطُ الوَلَدِ"": صَيْرُهُ نَشِيطاً. 2.""التَّنَشُّطُ لِلْعَمَلِ"" : الإقْبَالُ عَلَيِهِ وَالتَّهَيُّؤُ لَهُ. 3.""كَانَ تَنَشُّطُهُ الطَّرِيقَ تَعْبِيراً عَنْ نَجَاحِهِ"" : قَطْعُهُ الطَّرِيقَ بِنَشَاطٍ وَ بِسُرْعَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19709, 'تَنَشُّفٌ', 'تنشف', 'مصدر', 'نشف', 'تنشف', 'تنشف', 'مص. تَنَشَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَشُّفٌ-تَنَشُّفٌ [ن ش ف] (مص. تَنَشَّفَ). 1.""تَنَشُّفُ الرَّجُلِ"" : مَسْحُهُ الْمَاءَ عَنْ جَسَدِهِ بِالفوطَةِ. 2.""تَنشُّفُ الْمَاءِ"": اِمْتِصَاصُهُ بِالمِنْشَفَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19710, 'تَنَشُّقٌ', 'تنشق', 'مصدر', 'نشق', 'تنشق', 'تنشق', 'مص. تَنَشَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَشُّقٌ-تَنَشُّقٌ [ن ش ق] (مص. تَنَشَّقَ). 1. ""تَنَشُّقُ الماءِ"" : إدْخَالُهُ فِي الأنْفِ. 2. ""تَنَشُّقُ النَّسِيمِ"" : شَمُّهُ. 3. ""تَنَشُّقُ العِطْرِ"" : جَذْبُهُ بِالنَّفَسِ إلَى الأنْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19711, 'تَنَصُّبٌ', 'تنصب', 'مصدر', 'نصب', 'تنصب', 'تنصب', 'مص. تَنَصَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَصُّبٌ-تَنَصُّبٌ [ن ص ب] (مص. تَنَصَّبَ). 1."" تَنَصُّبُ الطَّائِرِ"" : اِرْتِفَاعُهُ. 2. ""تَنَصُّبُ الفَمِ"" : اِسْتِوَاءُ أسْنَانِهِ. 3.""التَّنَصُّبُ لِلْجَارِ"" : مُعَادَاتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19712, 'تَنَصُّتٌ', 'تنصت', 'مصدر', 'نصت', 'تنصت', 'تنصت', 'مص. تَنَصَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَصُّتٌ-تَنَصُّتٌ [ن ص ت] (مص. تَنَصَّتَ). ""تَجَنَّبَ التَّنَصُّتَ عَلَى النَّاسِ"" : التَّسَمُّعَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19713, 'تَنَصُّحٌ', 'تنصح', 'مصدر', 'نصح', 'تنصح', 'تنصح', 'مص. تَنصَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَصُّحٌ-تَنَصُّحٌ [ن ص ح] (مص. تَنصَّحَ). 1. ""تَنَصُّحُ الرَّجُلِ"": تَشَبُّهُهُ بِالنُّصَحَاءِ"". 2. ""تَنَصُّحُ الْمُعَلِّمِ"" : إكْثَارُهُ النُّصْحَ. 3. ""شَرَعَ فِي تَنَصُّحِ ثَوْبِهِ"" : خِيَاطَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19714, 'تَنصُّرٌ', 'تنصر', 'مصدر', 'نصر', 'تنصر', 'تنصر', 'مص. تَنَصَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنصُّرٌ-تَنصُّرٌ [ن ص ر] (مص. تَنَصَّرَ). 1. ""تَنَصُّرُ الرَّجُلِ"" : صَيْرُهُ نَصْرَانِيّاً. 2. ""لَمْ يَكُنْ أمَامَهُ إلاَّ التَّنَصُّرَ لَهُ"" : السَّعْيَ فِي نَصْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19715, 'تَنَصُّفٌ', 'تنصف', 'مصدر', 'نصف', 'تنصف', 'تنصف', 'مص. تَنَصَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَصُّفٌ-تَنَصُّفٌ [ن ص ف] (مص. تَنَصَّفَ). 1.""تَنَصُّفُ مَبْلَغٍ مِنَ الْمَالِ"" : تَقْسيمُهُ مُناصَفَةً. 2.""طَلَبَ تَنَصُّفَ الحاكِمِ"": طَلَبَ إِنْصافَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19716, 'تَنَصُّلٌ', 'تنصل', 'مصدر', 'نصل', 'تنصل', 'تنصل', 'مص. تَنَصَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَصُّلٌ-تَنَصُّلٌ [ن ص ل] (مص. تَنَصَّلَ). 1. ""التَّنَصُّلُ مِنَ الْمَسْؤُولِيَّةِ"" : التَّمَلُّصُ مِنْهَا. 2. ""التَّنَصُّلُ مِنَ الذَّنْبِ"" : التَّبَرُّؤُ مِنْهُ. 3. ""تَنَصُّلُ الألْوَانِ"" : زَوالُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19717, 'تَنَضُّحٌ', 'تنضح', 'مصدر', 'نضح', 'تنضح', 'تنضح', 'مص. تَنضَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَضُّحٌ-تَنَضُّحٌ [ن ض ح] (مص. تَنضَّحَ). 1.""تَنَضُّحُ العَيْنِ"": نَضْحُهَا، أيْ فَوَرَانُهَا بالدَّمْعِ. 2.""حَاوَلَ التَّنَضُّحَ مِنْهُ"": التَّنَصُّلَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19718, 'تَنَضُّدٌ', 'تنضد', 'مصدر', 'نضد', 'تنضد', 'تنضد', 'مص. تَنضَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَضُّدٌ-تَنَضُّدٌ [ن ض د] (مص. تَنضَّدَ). 1. ""تَنَضُّدُ الأسْنَانِ"": اِرْتِصَافُهَا. 2. ""تَنَضُّدُ الزُّهُورِ"" : تَنَاسُقُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19719, 'تَنَغُّمٌ', 'تنغم', 'مصدر', 'نغم', 'تنغم', 'تنغم', 'مص. تَنَغَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَغُّمٌ-تَنَغُّمٌ [ن غ م] (مص. تَنَغَّمَ). 1. ""تَنَغُّمُ الرَّجُلِ"" : تَكَلُّمُهُ بِكَلاَمٍ خَفِيٍّ. 2. ""تَنَغُّمُ الْمُغَنِّي"" : تَرَنُّمُهُ، تَطْرِيبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19720, 'تَنَطُّعٌ', 'تنطع', 'مصدر', 'نطع', 'تنطع', 'تنطع', 'مص. تَنَطَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَطُّعٌ-تَنَطُّعٌ [ن ط ع] (مص. تَنَطَّعَ). 1.""تَنَطُّعُ الرَّجُلِ أثْنَاءَ الأكْلِ"" : جَعْلُ الطَّعَامِ فِي نِطْعِهِ. 2. ""التَّنَطُّعُ فِي الكَلاَمِ"": الْمُبَالَغَةُ فِيهِ وَالتَّكَلُّفُ. 4. ""التَّنَطُّعُ فِي العَمَلِ"" : التَّحَذُّقُ فِيهِ. 5.""التَّنَطُّعُ فِي الشَّهَوَاتِ"" : التّأنُّقُ فِيها وَالتَّشَبُّعُ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19721, 'تَنَطُّقٌ', 'تنطق', 'مصدر', 'نطق', 'تنطق', 'تنطق', 'مص. تَنَطَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَطُّقٌ-تَنَطُّقٌ [ن ط ق] (مص. تَنَطَّقَ). ""تَنَطُّقُ الْمَرْأَةِ"" : شَدُّ نِطَاقِهَا، حِزامِهَا مِنَ الوَسَطِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19722, 'تَنَظُّرٌ', 'تنظر', 'مصدر', 'نظر', 'تنظر', 'تنظر', 'مص. تَنَظَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَظُّرٌ-تَنَظُّرٌ [ن ظ ر] (مص. تَنَظَّرَ). 1. ""سَعَى إلَى التَّنَظُّرِ فِي وَجْهِهِ"" : تَأمُّلِهِ بِعَيْنِهِ. 2. ""لَمْ يَكُنْ تَنَظُّرُهُ، لِلْحَدَثِ عَبَثاً"": تَوَقُّعُهُ. 3. ""قَرَّرَ تَنَظُّرَهُ إلَى أنْ يُنْهِيَ عَمَلَهُ"" : اِنْتِظارَهُ، التَّأَنِّيَ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19723, 'تَنَظُّفٌ', 'تنظف', 'مصدر', 'نظف', 'تنظف', 'تنظف', 'مص. تَنَظَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَظُّفٌ-تَنَظُّفٌ [ن ظ ف] (مص. تَنَظَّفَ). 1. ""تَنَظُّفُ البَيْتِ"": صَيْرُهُ نَظِيفاً. 2. ""تَنَظُّفُ الرَّجُلِ"" : اِغْتِسالُهُ، أو تَرَفُّعُهُ عَنِ الْمَسَاوئِ والعُيوبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19724, 'تَنَظُّمٌ', 'تنظم', 'مصدر', 'نظم', 'تنظم', 'تنظم', 'مص. تَنَظَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَظُّمٌ-تَنَظُّمٌ [ن ظ م] (مص. تَنَظَّمَ). 1. ""تَنَظُّمُ العَقِيقِ"" : تَألُّفُهُ فِي الخَيْطِ، اِتِّسَاقُهُ. 2. ""تَنَظُّمُ الأمْرِ"" : اِسْتِقَامَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19725, 'تَنَعُّتٌ', 'تنعت', 'مصدر', 'نعت', 'تنعت', 'تنعت', 'مص. تَنَعَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَعُّتٌ-تَنَعُّتٌ [ن ع ت] (مص. تَنَعَّتَ).""تَنَعُّتُ الصُّورَةِ"" : وَصْفُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19726, 'تَنَعُّلٌ', 'تنعل', 'مصدر', 'نعل', 'تنعل', 'تنعل', 'مص. تَنَعَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَعُّلٌ-تَنَعُّلٌ [ن ع ل] (مص. تَنَعَّلَ). ""تَنَعُّلُ الرَّجُلِ"" : لُبْسُهُ النَّعْلَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19727, 'تَنَعُّمٌ', 'تنعم', 'مصدر', 'نعم', 'تنعم', 'تنعم', 'مص. تَنَعَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَعُّمٌ-تَنَعُّمٌ [ن ع م] (مص. تَنَعَّمَ). 1. ""يَعِيشُ فِي تَنَعُّمٍ"" : فِي عَيْشٍ رَغِيدٍ. 2. ""تَنَعُّمُ الصَّدِيقِ"" : طَلَبُهُ وَالبَحْثُ عَنْهُ. 3.""لَمْ يَجِدْ فِي بِلاَدِ الهِجْرَةِ تَنَعُّماً"" : موافَقَةً، مُلاءَمَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19728, 'تَنَغُّصٌ', 'تنغص', 'مصدر', 'نغص', 'تنغص', 'تنغص', 'مص. تَنَغَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَغُّصٌ-تَنَغُّصٌ [ن غ ص] (مص. تَنَغَّصَ). ""تَنَغُّصُ العَيْشِ"" : تَكَدُّرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19729, 'تَنَقُّلٌ', 'تنقل', 'مصدر', 'نقل', 'تنقل', 'تنقل', 'مص. تَنَقَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَقُّلٌ-تَنَقُّلٌ [ن ق ل] (مص. تَنَقَّلَ). 1. ""أكْثَرَ مِنَ التَّنَقُّلِ دُونَ هَدَفٍ"" : الانْتِقَالُ مِنْ مَكَانٍ إلَى آخَرَ، التَّجَوُّلُ، التَّجْوَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19730, 'تَنَفُّسٌ', 'تنفس', 'مصدر', 'نفس', 'تنفس', 'تنفس', 'مص. تَنَفَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَفُّسٌ-تَنَفُّسٌ [ن ف س] (مص. تَنَفَّسَ). 1. ""تَنَفُّسُ الْمَرْءِ"" : إخْرَاجُ النَّفَسِ وَإدْخَالُهُ، أيْ تَعَاقُبُ الشَّهِيقِ وَالزَّفِيرِ. 2. ""جِهَازُ التَّنَفُّسِ"" : كُلُّ الأعْضَاءِ الَّتِي تُسَاهِمُ فِي إدْخَالِ النَّفَسِ وَإِخْراجِهِ مِنْ فَمٍ وَأنْفٍ وَحَنْجَرَةٍ وَرِئَتَيْنِ. 3. ""كَانَ تَنَفُّسُهُ تَعْبِيراً عَنِ ارْتِيَاحِهِ"" : إخْرَاجُ النَّفَسِ تَعْبِيراً عَنِ الارْتِيَاحِ مِنْ تَعَبٍ أوْ هَمٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19731, 'تَنَفُّشٌ', 'تنفش', 'مصدر', 'نفش', 'تنفش', 'تنفش', 'مص. تَنَفَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَفُّشٌ-تَنَفُّشٌ [ن ف ش] (مص. تَنَفَّشَ). ""تَنَفُّشُ الطَّائِرِ"" : نَفْضُ رِيشِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19732, 'تَنَفُّطٌ', 'تنفط', 'مصدر', 'نفط', 'تنفط', 'تنفط', 'مص. تَنَفَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَفُّطٌ-تَنَفُّطٌ [ن ف ط] (مص. تَنَفَّطَ). 1. ""تَنَفُّطُ القِدْرِ"" : غَلَيَانُها غَلَياناً شَدِيداً وَقَذْفُهَا بِمِثْلِ السِّهَامِ. 2. ""تَنَفُّطُ الرَّجُلِ"": تَحَرُّقُهُ غَضَباً شَدِيداً. 3. ""ظَلَّ يَحْفِرُ بِالفَأْسِ فَلاَحَظَ تَنَفُّطَ يَدِهِ"": بُرُوزَ انْتِفَاخٍ فِيهَا مَنْ جَرَّاءِ تَجَمُّعِ مَاءٍ بَيْنَ الجِلْدِ واللَّحْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19733, 'تَنَفُّلٌ', 'تنفل', 'مصدر', 'نفل', 'تنفل', 'تنفل', 'مص. تَنَفَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَفُّلٌ-تَنَفُّلٌ [ن ف ل] (مص. تَنَفَّلَ). ""تَنَفُّلُ الْمُؤْمِنِ"" : أداؤُهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19734, 'تَنَقُّبٌ', 'تنقب', 'مصدر', 'نقب', 'تنقب', 'تنقب', 'مص. تَنَقَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَقُّبٌ-تَنَقُّبٌ [ن ق ب] (مص. تَنَقَّبَ). 1. ""تَنَقُّبُ الْمَرْأةِ"" : شَدُّ النِّقَابِ عَلَى وَجْهِهَا. 2. ""تَنَقُّبُ الْمُهَنْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19735, 'تَنَقُّدٌ', 'تنقد', 'مصدر', 'نقد', 'تنقد', 'تنقد', 'مص. تَنَقَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَقُّدٌ-تَنَقُّدٌ [ن ق د] (مص. تَنَقَّدَ). ""تَنَقّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19736, 'تَنَقُّذٌ', 'تنقذ', 'مصدر', 'نقذ', 'تنقذ', 'تنقذ', 'مص. تَنَقَّذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَقُّذٌ-تَنَقُّذٌ [ن ق ذ] (مص. تَنَقَّذَ). 1. ""حَاولَ تَنَقُّذَهُ"" : إنْقَاذَهُ. 2. ""سَعَى إلَى تَنَقُّذِ الحَدِيثِ مِنْهُ"" : اِسْتِخْرَاجِهِ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19737, 'تَنَقُّصٌ', 'تنقص', 'مصدر', 'نقص', 'تنقص', 'تنقص', 'مص. تَنَقَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَقُّصٌ-تَنَقُّصٌ [ن ق ص] (مص. تَنَقَّصَ). 1. ""ظَلَّتْ ثَرْوَتُهُ فِي تَنَقُّصٍ"" : أيْ تَنْقُصُ شَيْئاً فَشَيْئاً. 2. ""لَمْ يَكُنْ تَنَقُّصُهُ لِصَاحِبهِ فِي مَحَلِّهِ"" : عَيْبهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19738, 'تَنَقُّضٌ', 'تنقض', 'مصدر', 'نقض', 'تنقض', 'تنقض', 'مص. تَنَقَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَقُّضٌ-تَنَقُّضٌ [ن ق ض] (مص. تَنَقَّضَ). 1. ""تَنَقُّضُ الحَبْلِ"": اِنْحِلاَلُ أبْرَامِهِ. 2. ""تَنَقُّضُ العِظَامِ"" : تَصْوِيتُهَا. 3. ""تَنَقُّضُ الدَّمِ"" : سَيَلانُهُ قَطْرَةً قَطْرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19739, 'تَنَوُّلٌ', 'تنول', 'مصدر', 'نول', 'تنول', 'تنل', 'مص. تَنَوَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَوُّلٌ-تَنَوُّلٌ [ن و ل] (مص. تَنَوَّلَ). 1. ""تَنَوُّلُ الشَّيْءِ"" : أخْذُهُ. 2. ""كَانَ تَنَوُّلُهُ بِالخَيْرِ مُفَاجَأَةً لِلْجَمِيعِ"" : أيْ لَمْ يَكُنْ فِعْلُهُ قَبْلَ ذَلِكَ خَيِّراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19740, 'تَنَقِّي', 'تنقي', 'مصدر', 'نقو', 'تنقي', 'تنق', 'مص. تَنَقَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنَقٍّ-تَنَقٍّ، التَّنَقِّي [ن ق و] (مص. تَنَقَّى). ""تَنَقِّي هَدِيَّةٍ"" : اِنْتِقَاؤُهَا، اِخْتِيَارُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19741, 'تَنَكُّبٌ', 'تنكب', 'مصدر', 'نكب', 'تنكب', 'تنكب', 'مص. تَنَكَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَكُّبٌ-تَنَكُّبٌ [ن ك ب] (مص. تَنَكَّبَ). 1. ""التَّنَكُّبُ عَنِ الشَّيْءِ"" : العُدُولُ، التَّنَحِّي. 2. ""ألَحَّ عَلَيْهِ لِتَنَكُّبِ صُحْبَتِهِ"" : لِتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19742, 'تَنَكُّدٌ', 'تنكد', 'مصدر', 'نكد', 'تنكد', 'تنكد', 'مص. تَنَكَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَكُّدٌ-تَنَكُّدٌ [ن ك د] (مص. تَنَكَّدَ). """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19743, 'تَنَكُّرٌ', 'تنكر', 'مصدر', 'نكر', 'تنكر', 'تنكر', 'مص. تَنَكَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَكُّرٌ-تَنَكُّرٌ [ن ك ر] (مص. تَنَكَّرَ). 1.""التَّنَكُّرُ لِلْأفْكَارِ"" : إنْكَارُهَا وَالتَّخَلِّي عَنْهَا. 2. ""لَمْ يَتَعَرَّفْهُ لِتَنَكُّرِهِ"" : لِتَقَنُّعِهِ، اِخْتِفاؤُهُ وَراءَ لِباسٍ يَتَّخِذُهُ قِناعاً. ""ثَوْبُ التَّنَكُّرِ"" ""قِنَاعُ التَّنَكُّرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19744, 'تَنَكُّسٌ', 'تنكس', 'مصدر', 'نكس', 'تنكس', 'تنكس', 'مص. تَنَكَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَكُّسٌ-تَنَكُّسٌ [ن ك س] (مص. تَنَكَّسَ). ""تَنَكُّسُ الشَّيْءِ"": اِنْقِلاَب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19745, 'تَنَمُّلٌ', 'تنمل', 'مصدر', 'نمل', 'تنمل', 'تنمل', 'مص. تَنمَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَمُّلٌ-تَنَمُّلٌ [ن م ل] (مص. تَنمَّلَ). 1. ""تَنَمُّلُ النَّاسِ"" : تَحَرُّكُهُمْ واخْتِلاَطُ بَعْضِهِمْ بِبَعْضٍ. 2. ""تَنَمُّلُ السُّكَّانِ"" : تَفَرُّقُهُمْ لِلسَّعِي تَفَرُّقَ النَّمْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19746, 'تَنَهُّدٌ', 'تنهد', 'مصدر', 'نهد', 'تنهد', 'تنهد', 'مص. تَنَهَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَهُّدٌ-تَنَهُّدٌ [ن هـ د] (مص. تَنَهَّدَ). ""لاَ يَكُفُّ عَنِ التَّنَهُّدِ"": أَي التَّأَوُّهِ، الحَسْرَةِ، إِخْرَاجُ زفْرَةِ الأَلَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19747, 'تَنَوُّرٌ', 'تنور', 'مصدر', 'نور', 'تنور', 'تنر', 'مص. تَنَوَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَوُّرٌ-تَنَوُّرٌ [ن و ر] (مص. تَنَوَّرَ). ""تَنَوُّرُ الْمَكانِ"" : إضَاءَتُهُ، اِسْتِضَاءَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19748, 'تَنَوُّعٌ', 'تنوع', 'مصدر', 'نوع', 'تنوع', 'تنع', 'مص. تَنَوَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَوُّعٌ-تَنَوُّعٌ [ن و ع] (مص. تَنَوَّعَ). 1.""تَنَوُّعُ الصُّوَرِ"" : اِخْتِلاَفُ ألْوَانِهَا وَأحْجَامِهَا وَأشْكَالِهَا. 2. ""تَنَوُّعُ الْمَلابِسِ"" : تَصَنُّفُهَا. ""تَنَوُّعُ الْمَنَاظِرِ"" ""تَنَوُّعُ الأشْكَالِ"". 3. ""تَنَوُّعُ النَّاعِسِ عَلَى الرَّحْلِ"" : تَحَرُّكُهُ، تَمَايُلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19749, 'تَهَارُتٌ', 'تهارت', 'مصدر', 'هرت', 'تهارت', 'تهرت', 'مص. تَهَارَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَارُتٌ-تَهَارُتٌ [هـ ر ت] (مص. تَهَارَتَ). ""التَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19750, 'تَنَوُّمٌ', 'تنوم', 'مصدر', 'نوم', 'تنوم', 'تنم', 'مص. تَنَوَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَوُّمٌ-تَنَوُّمٌ [ن و م] (مص. تَنَوَّمَ). 1. ""سَعَى إلَى التَّنَوُّمِ وَهُوَ فِي حَالَةٍ مِنَ الأرَقِ الشَّدِيدِ"" : سَعْيُهُ النَّوْمَ، مُحَاوِلاً ذَلِكَ. 2.""كَانَ فِي حَالَةِ التَّنَوُّمِ"" : حَالَةِ الاحْتِلاَم."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19751, 'تَهَاتُرٌ', 'تهاتر', 'مصدر', 'هتر', 'تهاتر', 'تهتر', 'مص. تَهَاتَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَاتُرٌ-تَهَاتُرٌ [هـ ت ر] (مص. تَهَاتَرَ). ""لَمْ يَكُنْ يَسْمَعُ إلاَّ التَّهَاتُرَ"" : شَهَاداتٌ يُكَذِّبُ وَيُنَاقِضُ بَعْضُهَا بَعْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19752, 'تَهَاجُرٌ', 'تهاجر', 'مصدر', 'هجر', 'تهاجر', 'تهجر', 'مص. تَهَاجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَاجُرٌ-تَهَاجُرٌ [هـ ج ر] (مص. تَهَاجَرَ). ""تَهَاجُرُ الأَصْحَابِ"" : اِفْتِرَاقُهُمْ، تَقَاطُعُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19753, 'تَهَاجُمٌ', 'تهاجم', 'مصدر', 'هجم', 'تهاجم', 'تهجم', 'مص. تَهَاجَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَاجُمٌ-تَهَاجُمٌ [هـ ج م] (مص. تَهَاجَمَ). ""تَهَاجُمُ الخَصْمَيْنِ"": هُجُومُ كُلٍّ مِنْهُما عَلَى الآخَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19754, 'تَهاجِي', 'تهاجي', 'مصدر', 'هجو', 'تهاجي', 'تهج', 'مص. تَهَاجَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَهاجٍ-تَهاجٍ، التَّهَاجِي[هـ ج و] (مص. تَهَاجَى). ""تَهَاجِي الشَّاعِرَيْنِ"" : هَجْوُ أحَدِهِمَا الآخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19755, 'تَهَادٌّ', 'تهاد', 'مصدر', 'هدد', 'تهاد', 'تهد', 'مص. تَهَادَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَادٌّ-تَهَادٌّ [هـ د د] (مص. تَهَادَّ). 1. ""جاءوا فِي تَهَادٍّ"" : فِي تَتَابُعٍ، تَوالٍ، تَدافُعٍ. 2. ""هُمْ فِي تَهَادٍّ"" : فِي تَساؤُلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19756, 'تَهَادُنٌ', 'تهادن', 'مصدر', 'هدن', 'تهادن', 'تهدن', 'مص. تَهَادَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَادُنٌ-تَهَادُنٌ [هـ د ن] (مص. تَهَادَنَ). 1. ""تَهَادُنُ الْمُتَحَاربينَ"" : تَصَالُحُهُمْ، إيقَافُهُمْ لِلْخُصُومَةِ أوِ الحَرْبِ. 2.""تَهَادُنُ الأمورِ"" : اسْتِقَامَتُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19757, 'تَهَادِي', 'تهادي', 'مصدر', 'هدي', 'تهادي', 'تهد', 'مص. تَهَادى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَهَادٍ-تَهَادٍ، التَّهَادِي [هـ د ي] (مص. تَهَادى). 1.""كَانَتْ تَسِيرُ فِي تَهَادٍ"" : فِي تَمَايُلٍ وتَبَخْتُرٍ. 2.""التَّهَادِي ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19758, 'تَهَارُبٌ', 'تهارب', 'مصدر', 'هرب', 'تهارب', 'تهرب', 'مص. تَهَارَب', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَارُبٌ-تَهَارُبٌ [هـ ر ب] (مص. تَهَارَب). ""لَمْ يَبْقَ لَدَيْهِمْ إلاَّ التَّهَارُبُ"": أي الْهُرُوبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19759, 'تَهَاوِي', 'تهاوي', 'مصدر', 'هوي', 'تهاوي', 'ته', 'مص. تَهَاوَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَهَاوٍ-تَهَاوٍ، التَّهَاوِي [هـ و ي] (مص. تَهَاوَى). 1.""تَهَاوِي الرَّجُلِ"" : سَيْرُهُ سَيْراً سَرِيعاً. 2. ""تَهَاوِي المتقَاتِلِينَ"": سُقُوطُ بَعْضِهِمْ فِي إثْرِ بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19760, 'تَهَارُشٌ', 'تهارش', 'مصدر', 'هرش', 'تهارش', 'تهرش', 'مص. تَهَارَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَارُشٌ-تَهَارُشٌ [هـ ر ش] (مص. تَهَارَشَ). 1. ""تَهارُشُ الك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19761, 'تَهَارُقٌ', 'تهارق', 'مصدر', 'هرق', 'تهارق', 'تهرق', 'مص. تَهَارَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَارُقٌ-تَهَارُقٌ [هـ ر ق] (مص. تَهَارَقَ). 1.""تَهَارُق الصِّبْيانِ"": إهْرَاقُ، صَبُّ بَعْضِهِمْ الماءَ عَلَى بَعْضٍ. 2. ""تَهَارُقُ الْمُتقاتِلينَ"": إراقَةُ بَعْضِهِمْ دِماءَ بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19762, 'تَهَارُمٌ', 'تهارم', 'مصدر', 'هرم', 'تهارم', 'تهرم', 'مص. تَهَارَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَارُمٌ-تَهَارُمٌ [هـ ر م] (مص. تَهَارَمَ). ""تَهَارُمُ الرَّجُلِ"" : اِدِّعَاؤُهُ الْهَرَمَ وَلَيْسَ كَذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19763, 'تَهَاطُلٌ', 'تهاطل', 'مصدر', 'هطل', 'تهاطل', 'تهطل', 'مص. تَهَاطَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَاطُلٌ-تَهَاطُلٌ [هـ ط ل] (مص. تَهَاطَلَ). 1. ""اِسِتَمَرَّتِ الأمْطَارُ فِي تَهَاطُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19764, 'تَهَافُتٌ', 'تهافت', 'مصدر', 'هفت', 'تهافت', 'تهفت', 'مص. تَهَافَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَافُتٌ-تَهَافُتٌ [هـ ف ت] (مص. تَهَافَتَ). 1. ""تَهَافُتٌ لاَ مَعْنَى لَهُ"" : اِزْدِحَامٌ، تَسَابُقٌ. 2. ""تَهَافُتُ الجُدْرا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19765, 'تَهَالُكٌ', 'تهالك', 'مصدر', 'هلك', 'تهالك', 'تهلك', 'مص. تَهَالَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَالُكٌ-تَهَالُكٌ [هـ ل ك] (مص. تَهَالَكَ). 1. ""التَّهَالُكُ عَلَى الفِرَاشِ"" : الارْتِمَاءُ عَلَيْهِ عَيَاءً. 2. ""التَّهَالُكُ عَلَى القُوتِ"" : اِشْتِدَادُ الحِرْصِ عَلَيْهِ. ""تَتَمَيَّزُ العَرَبُ بِالتَّهَالُكِ فِي حُبِّ الثَّنَاءِ"".(التوحيدي). 3. ""التَّهَالُكُ فِي الأمْرِ"" : الجِدُّ وَاسْتِعْجَالُ إنْجَازِهِ. 4. ""التَّهَالُكُ فِي الْمَشْيِ"" : التَّمَايُلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19766, 'تَهَامُسٌ', 'تهامس', 'مصدر', 'همس', 'تهامس', 'تهمس', 'مص. تَهَامَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَامُسٌ-تَهَامُسٌ [هـ م س] (مص. تَهَامَسَ). ""تَهَامُسُ الرَّجُلَيْنِ"" : تَسَارُّهُمَا، هَمْسُ كُلِّ وَاحِدٍ مِنْهُمَا فِي أُذُنِ الآخَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19767, 'تَهَامُشٌ', 'تهامش', 'مصدر', 'همش', 'تهامش', 'تهمش', 'مص. تَهَامَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَامُشٌ-تَهَامُشٌ [هـ م ش] (مص. تَهَامَشَ). ""تَهَامُشُ النَّاسِ"": اِخْتِلاطُ بَعْضِهِمْ بِبَعْضٍ وتَحَرُّكُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19768, 'تَهَاوُنٌ', 'تهاون', 'مصدر', 'هون', 'تهاون', 'تهن', 'مص. تَهَاوَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَاوُنٌ-تَهَاوُنٌ [هـ و ن] (مص. تَهَاوَنَ). 1. ""مَا هَذَا التَّهَاوُنُ فِي العَمَلِ"" : الإهْمَالُ، التَّقْصِيرُ، التَّقَاعُسُ. ""قَالَ فَيْلَسُوفٌ: التَّهَاوُنُ بِالسِّيَرِ أسَاسُ الوُقُوعِ فِي الكَثِير"". (التوحيدي). 2.""أظْهَرَ تَهَاوُناً بِصَاحِبِهِ"" : اِسْتِخْفَافاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19769, 'تَهَدُّلٌ', 'تهدل', 'مصدر', 'هدل', 'تهدل', 'تهدل', 'مص. تَهَدَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَدُّلٌ-تَهَدُّلٌ [هـ د ل] (مص. تَهَدَّلَ). 1.""تَهَدُّلُ أغْصَانِ الشَّجَرِ"" : تَدَلِّيهَا. 2. ""تَهَدُّلُ الفُسْتَانِ"" : طُولُهُ، اِسْتِرْسَالُهُ. 3.""تَهَدُّلُ الشَّفَةِ"" : اِسْتِرْخَاؤُهُا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19770, 'تَهَايُجٌ', 'تهايج', 'مصدر', 'هيج', 'تهايج', 'تهج', 'مص. تَهَايَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَايُجٌ-تَهَايُجٌ [هـ ي ج] (مص. تَهَايَجَ). ""تَهَايُجُ الجُنودِ"" : تَوَاثُبُهُمْ لِلْقِتَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19771, 'تَهَتُّكٌ', 'تهتك', 'مصدر', 'هتك', 'تهتك', 'تهتك', 'مص. تَهَتَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَتُّكٌ-تَهَتُّكٌ [هـ ت ك] (مص. تَهَتَّكَ). 1. ""تَهَتُّكُ الثَّوْبِ"" : تَمَزُّقُهُ، تَلاشِيهِ. 2. ""أظْهَرَتْ تَهَتُّكاً"" : اِنْحِلاَلاً فِي الأخْلاقِ وَعَدَمِ الاحْتِشَامِ. ""وَيُبَذِّرُ أمْوَالَهُ فِي نَوَادِي التَّهَتُّكِ"" (جبران خ. جبران)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19772, 'تَهَجُّدٌ', 'تهجد', 'مصدر', 'هجد', 'تهجد', 'تهجد', 'مص. تَهَجَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَجُّدٌ-تَهَجُّدٌ [هـ ج د] (مص. تَهَجَّدَ). 1. ""نَاسِكٌ فِي تَهَجُّدِهِ"" : فِي عِبَادَتِهِ وَصَلاَتِهِ أثْنَاءَ الليْلِ. 2. ""التَّهَجُّدُ فِي الليْلِ"" : السَّهَرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19773, 'تَهَجُّرٌ', 'تهجر', 'مصدر', 'هجر', 'تهجر', 'تهجر', 'مص. تَهَجَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَجُّرٌ-تَهَجُّرٌ [هـ ج ر] (مص. تَهَجَّرَ). 1. ""تَهَجُّرُ الْمُسَافِرِ"" : سَيْرُهُ فِي الهَاجِرَةِ، أيْ فِي حَرِّ مُنتَصَفِ النَّهَارِ. 2.""تَهَجُّرُ الرَّجُلِ"": تَشْبُّهُهُ بِالْمُهاجِرينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19774, 'تَهَجُّمٌ', 'تهجم', 'مصدر', 'هجم', 'تهجم', 'تهجم', 'مص. تَهَجَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَجُّمٌ-تَهَجُّمٌ [هـ ج م] (مص. تَهَجَّمَ). 1.""التَّهَجُّمُ بِالشَّتَائِمِ"" : الاعْتِدَاءُ بِالشَّتَائِمِ. 2.""التَّهَجُّمُ بِالضَّرْبِ"" : الاِعْتِدَاءُ بِالضَّرْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19775, 'تَهَجِّي', 'تهجي', 'مصدر', 'هجو', 'تهجي', 'تهج', 'مص. تَهَجَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَهَجٍّ-تَهَجٍّ، التَّهَجِّي [هـ ج و] (مص. تَهَجَّى). 1.""تَهَجِّي الحُرُوفِ"" : نُطْقُهَا حَرْفاً حَرْفاً. 2.""تَهجِّي آيَاتِ القُرآنِ"" : تِلاوَتُهَا وَالتَّوَقُّفُ عِنْدَ حُرُوفِهَا لِتَعَرُّفِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19776, 'تَهَدُّبٌ', 'تهدب', 'مصدر', 'هدب', 'تهدب', 'تهدب', 'مص. تَهَدَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَدُّبٌ-تَهَدُّبٌ [هـ د ب] (مص. تَهَدَّبَ). 1. ""تَهَدُّبُ الوَلَدِ"": صَيْرُهُ ذَا هُدْبٍ، ذَا هَدَبٍ. 2. ""تَهَدُّبُ السَّحَابِ"" : كَوْنُهُ ذَا هَيْدَبٍ. 3. ""تَهَدُّبُ الأغْصَانِ"" : تَدَلِّيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19777, 'تَهَدُّجٌ', 'تهدج', 'مصدر', 'هدج', 'تهدج', 'تهدج', 'مص. تَهَدَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَدُّجٌ-تَهَدُّجٌ [هـ د ج] (مص. تَهَدَّجَ). ""تَهَدُّجُ الصَّوْتِ"" : تَقَطُّعُهُ فِي ارْتِعَاشٍ وَعُلُوٍّ وَهُبُوطٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19778, 'تَهَدُّدٌ', 'تهدد', 'مصدر', 'هدد', 'تهدد', 'تهد', 'مص. تَهَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَدُّدٌ-تَهَدُّدٌ [هـ د د] (مص. تَهَدَّدَ). ""تَهَدُّدُ الرَّجُلِ"" : تَهْدِيدُهُ، تَوَعُّدُهُ، تَخْوِيفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19779, 'تَهَزُّمٌ', 'تهزم', 'مصدر', 'هزم', 'تهزم', 'تهزم', 'مص. تَهَزَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَزُّمٌ-تَهَزُّمٌ [هـ ز م] (مص. تَهَزَّمَ). 1.""تَهَزُّمُ الرَّعْدِ"" : تَصْوِيتُهُ. 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19780, 'تَهَدُّمٌ', 'تهدم', 'مصدر', 'هدم', 'تهدم', 'تهدم', 'مص. تَهَدَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَدُّمٌ-تَهَدُّمٌ [هـ د م] (مص. تَهَدَّمَ). 1. ""تَهَدُّمُ البَيْتِ"" : تَسَاقُطُ جُدْرَانِهِ. 2. ""التَّهَدُّمُ بِالكَلاَمِ"" : التَّهَوُّر."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19781, 'تَهَدْهُدٌ', 'تهدهد', 'مصدر', 'هدهد', 'تهدهد', 'تهدهد', 'مص. تَهَدْهَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَدْهُدٌ-تَهَدْهُدٌ [هـ د هـ د] (مص. تَهَدْهَدَ)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19782, 'تَهَذُّبٌ', 'تهذب', 'مصدر', 'هذب', 'تهذب', 'تهذب', 'مص. تَهَذَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَذُّبٌ-تَهَذُّبٌ [ هـ ذ ب] (مص. تَهَذَّبَ). ""تَهَذّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19783, 'تَهَرُّؤٌ', 'تهرؤ', 'مصدر', 'هرأ', 'تهرء', 'تهر', 'مص. تَهَرَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَهَرُّؤٌ-تَهَرُّؤٌ [هـ ر أ] (مص. تَهَرَّأَ). 1.""تَهَرُّؤُ الَّلحْمِ"" : تَفَتُّتُهُ، تَفَسُّخُهُ. "', '');
