INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19785, 'تَهَرْطُقٌ', 'تهرطق', 'مصدر', 'هرط', 'تهرطق', 'تهرطق', 'مص. تَهَرْطَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَرْطُقٌ-تَهَرْطُقٌ [هـ ر ط] (مص. تَهَرْطَقَ). ""تَهَرْطُقُ الرَّجُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19786, 'تَهَزُّؤٌ', 'تهزؤ', 'مصدر', 'هزأ', 'تهزء', 'تهز', 'مص. تَهَزَّأ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَهَزُّؤٌ-تَهَزُّؤٌ [هـ ز أ] (مص. تَهَزَّأ). ""التَّهَزُّؤُ بِالشَّيْءِ"" : السُّخْرُ مِنْهُ، الهُزْءُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19787, 'تَهَزُّجٌ', 'تهزج', 'مصدر', 'هزج', 'تهزج', 'تهزج', 'مص. تَهَزَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَزُّجٌ-تَهَزُّجٌ [هـ ز ج] (مص. تَهَزَّجَ). 1.""تَهَزُّجُ الْمُغَنِّي"": تَرَنُّمُهُ. 2. ""تَهَزُّجُ الرَّعْدِ"" : تَصْوِيتُهُ وَإِرْعَادُهُ. 3.""تَهَزُّجُ الْوَتَرِ"": تَصْوِيتُهُ عِنْدَ تَحْريِكِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19788, 'تَهَزُّزٌ', 'تهزز', 'مصدر', 'هزز', 'تهزز', 'تهز', 'مص. تَهَزَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَزُّزٌ-تَهَزُّزٌ [هـ ز ز] (مص. تَهَزَّزَ). ""تَهزُّزُ الشَّجَرَةِ"" : تَحَرُّكُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19789, 'تَهَوُّرٌ', 'تهور', 'مصدر', 'هور', 'تهور', 'تهر', 'مص. تَهَوَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَوُّرٌ-تَهَوُّرٌ [هـ و ر] (مص. تَهَوَّرَ). 1. ""تَصرَّفَ بِتَهوُّرٍ"" : بِمُجَازَفَةٍ، بِمُخَاطَرةٍ مِن غَيْرِ رَويَّةٍ. 2. ""تَهوُّرُ الشِّتاءِ"" : ذَهَابُ أكْثَرِهِ وانْكِسارُ بَرْدِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19790, 'تَهَشُّمٌ', 'تهشم', 'مصدر', 'هشم', 'تهشم', 'تهشم', 'مص. تَهَشَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَشُّمٌ-تَهَشُّمٌ [هـ ش م] (مص. تَهَشَّمَ). ""تَهَشُّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19791, 'تَهَطُّلٌ', 'تهطل', 'مصدر', 'هطل', 'تهطل', 'تهطل', 'مص. تَهَطَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَطُّلٌ-تَهَطُّلٌ [هـ ط ل] (مص. تَهَطَّلَ). ""تَهَطُّلُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19792, 'تَهَفْهُفٌ', 'تهفهف', 'مصدر', 'هفهف', 'تهفهف', 'تهفهف', 'مص. تَهَفْهَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَفْهُفٌ-تَهَفْهُفٌ [هـ ف هـ ف] (مص. تَهَفْهَفَ). ""تَهَفْهُفُ الْمَرْأةِ"" : قِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19793, 'تَهَكُّمٌ', 'تهكم', 'مصدر', 'هكم', 'تهكم', 'تهكم', 'مص. تَهَكَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَكُّمٌ-تَهَكُّمٌ [هـ ك م] (مص. تَهَكَّمَ). ""أَجَابَهُ بِتَهَكُّمٍ"" : بِسُخْرِيَةٍ، بِاسْتِهْزَاءٍ، بِتَكَبُّرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19794, 'تَهَلُّلٌ', 'تهلل', 'مصدر', 'هلل', 'تهلل', 'تهل', 'مص. تَهَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَلُّلٌ-تَهَلُّلٌ [هـ ل ل] (مص. تَهَلَّلَ). 1.""تَهَلُّلُ الوَجْهِ"": إِشْرَاقُهُ، تَلَأْلُؤُهُ. 2.""تَهَلُّلُ السَّحَابِ بِالبَرْقِ"": إِشْرَاقُهُ، إِبْرَاقُهُ. 3.""تَهَلُّلُ العَيْنِ"": سَيْلُ دُمُوعِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19795, 'تَهَلْهُلٌ', 'تهلهل', 'مصدر', 'هلهل', 'تهلهل', 'تهلهل', 'مص. تَهَلْهَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَلْهُلٌ-تَهَلْهُلٌ [هـ ل هـ ل] (مص. تَهَلْهَلَ). ""تَهَلْهُلُ الثِّيابِ"" : صَيْرُها بَالِيةً، تَفَسُّخُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19796, 'تَهَنُّؤٌ', 'تهنؤ', 'مصدر', 'هنأ', 'تهنء', 'تهن', 'مص. تَهَنَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَهَنُّؤٌ-تَهَنُّؤٌ [هـ ن أ] (مص. تَهَنَّأَ). 1. ""تَهَنُّؤُ الرَّجُلِ"" : كَثْرةُ عَطائِهِ. 2. ""التَّهَنُّؤُ بِالطَّعامِ"" : سَوْغُهُ وَلَذَّتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19797, 'تَهَوُّجٌ', 'تهوج', 'مصدر', 'هوج', 'تهوج', 'تهج', 'مص. تَهَوَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَوُّجٌ-تَهَوُّجٌ [هـ و ج] (مص. تَهَوَّجَ). ""تَهَوُّجُ الحَرِّ"" : اِشْتِدَادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19798, 'تَهَوُّدٌ', 'تهود', 'مصدر', 'هود', 'تهود', 'تهد', 'مص. تَهَوَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَوُّدٌ-تَهَوُّدٌ [هـ و د] (مص. تَهَوَّدَ). ""تَهَوُّدُ الرَّجُلِ"" : صَيْرُهُ يَهُودِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19799, 'تَهَوُّسٌ', 'تهوس', 'مصدر', 'هوس', 'تهوس', 'تهس', 'مص. تَهَوَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَوُّسٌ-تَهَوُّسٌ [هـ و س] (مص. تَهَوَّسَ). 1. ""تَهَوُّسُ السَّائِرِ"": مَشْيُهُ ثقِيلاً فِي أَرْضٍ لَيِّنَةٍ. 2. ""تَهَوُّسُ الرَّجُلِ"" : صَيْرُ هَوَسٍ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19800, 'تَهَوُّشٌ', 'تهوش', 'مصدر', 'هوش', 'تهوش', 'تهش', 'مص. تَهَوَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَوُّشٌ-تَهَوُّشٌ [هـ و ش] (مص. تَهَوَّشَ). 1. ""تَهَوُّشُ النَّاسِ"": اِخْتِلاطُهُم. 2. ""تَهَوُّشُ النَّاسِ عَلَيْهِ"" : اِجْتِمَاعُهُمْ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19801, 'تَهَوُّمٌ', 'تهوم', 'مصدر', 'هوم', 'تهوم', 'تهم', 'مص. تَهَوَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَوُّمٌ-تَهَوُّمٌ [هـ و م] (مص. تَهَوَّمَ). 1. ""تَهَوُّمُ الرّجُلِ"" : نَوْمُهُ نَوْماً ضعِيفاً. 2. ""تَهَوُّمُ النَّائِمَةِ"" : هَزُّ رأْسِهَا مِنَ النُّعاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19802, 'تَهَيُّؤٌ', 'تهيؤ', 'مصدر', 'هيأ', 'تهيء', 'ته', 'مص. تَهَيَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَهَيُّؤٌ-تَهَيُّؤٌ [هـ ي أ] (مص. تَهَيَّأَ).""التَّهَيُّؤُ لِخَوْضِ الْمَعْرَكَةِ"": الاِسْتِعْدَادُ لهَا بِمَا يَنْبَغِي مِنْ عُدَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19803, 'تَهَيُّبٌ', 'تهيب', 'مصدر', 'هيب', 'تهيب', 'تهب', 'مص. تَهَيَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَيُّبٌ-تَهَيُّبٌ [هـ ي ب] (مص. تَهَيَّبَ). 1. ""تَهَيُّبُ الرَّئِيسِ"" : الخَوْفُ مِنْهُ. 2. ""سَعَى إلَى تَهَيُّبِهِ"" : إلَى إِفْرَاغِهِ وإضَافَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19804, 'تَهَيُّجٌ', 'تهيج', 'مصدر', 'هيج', 'تهيج', 'تهج', 'مص. تَهَيَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهَيُّجٌ-تَهَيُّجٌ [هـ ي ج] (مص. تَهَيَّجَ). ""لاَحَظَ تَهَيُّجَهُ"" : حِدَّةُ التَّأثُّرِ وَالهَيَجَانِ عِنْدَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19805, 'تَهيُّمٌ', 'تهيم', 'مصدر', 'هيم', 'تهيم', 'تهم', 'مص. تَهَيَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهيُّمٌ-تَهيُّمٌ [هـ ي م] (مص. تَهَيَّمَ). 1. ""تَهَيُّمُ الفَتَاةِ"" : مَشْيُهَا أحْسَنَ الْمَشْيِ. 2. ""بَلغَ تَهَيُّمُ حُبِّهِ لهَا حَدّاً أقْصَى"" : بُلوغُهُ هُياماً شَدِيداً. 3. ""اِسْتَطَاعَتْ أنْ تَجْعَلَ تَهَيُّمَهُ بِهَا أمْراً مَلْمُوساً"" : دَفْعُها إيَّاهُ إلَى حُبِّهَا حُبّاً شَدِيداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19806, 'تَواؤُمٌ', 'تواؤم', 'مصدر', 'وأم', 'تواءم', 'تم', 'مص. تَوَاءمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَواؤُمٌ-تَواؤُمٌ [و أ م] (مص. تَوَاءمَ). 1. ""رَغِبَ فِي التَّواؤُمِ مَعَهُ"" : فِي التَّوَافُقِ وَالتَّنَاسُبِ مَعَهُ. 2. ""تَوَاؤُمُ الأنْغَامِ"" : تَوَافُقُهَا، اِنْسِجَامُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19807, 'تَوَاتُرٌ', 'تواتر', 'مصدر', 'وتر', 'تواتر', 'تتر', 'مص. تَوَاتَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَاتُرٌ-تَوَاتُرٌ [و ت ر] (مص. تَوَاتَرَ). ""تَوَاتُرُ الأخْبَارِ"": تَوَالِيهَا، تَتَابُعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19808, 'تَواثُبٌ', 'تواثب', 'مصدر', 'وثب', 'تواثب', 'تثب', 'مص. تَوَاثَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَواثُبٌ-تَواثُبٌ [و ث ب] (مص. تَوَاثَبَ). ""تَوَاثُبُ الأوْلاَدِ"": وُثُوبُ بَعْضِهِمْ عَلَى بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19809, 'تَوَاجُدٌ', 'تواجد', 'مصدر', 'وجد', 'تواجد', 'تجد', 'مص. تَواجَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَاجُدٌ-تَوَاجُدٌ [و ج د] (مص. تَواجَدَ). ""تَواجُدُ الْمَرْأةِ"" : تَظَاهُرُهَا بِالوَجْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19810, 'تَوَاجُهٌ', 'تواجه', 'مصدر', 'وجه', 'تواجه', 'تجه', 'مص. تَوَاجَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَاجُهٌ-تَوَاجُهٌ [و ج هـ] (مص. تَوَاجَهَ). ""تَوَاجُهُ الخَصْمَيْنِ"": تَقَابُلُهُمَا وَجْهاً لِوَجْهٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19811, 'تَوَادٌّ', 'تواد', 'مصدر', 'ودد', 'تواد', 'تد', 'مص. تَوَادَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَادٌّ-تَوَادٌّ [و د د] (مص. تَوَادَّ). ""تَوَادُّ الصَّدِيقَيْنِ"" : تَحَابُّهُمَا حُبّاً جَمّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19812, 'تَوَادُعٌ', 'توادع', 'مصدر', 'ودع', 'توادع', 'تدع', 'مص. تَوَادَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَادُعٌ-تَوَادُعٌ [و د ع] (مص. تَوَادَعَ). 1. ""تَوَادُعُ الصَّدِيقَيْنِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19813, 'تَوَارُثٌ', 'توارث', 'مصدر', 'ورث', 'توارث', 'ترث', 'مص. تَوارَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَارُثٌ-تَوَارُثٌ [و ر ث] (مص. تَوارَثَ). ""تَوَارُثُ أمْلاكِ العَائِلَةِ"" : إرْثُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19814, 'تَوَارُدٌ', 'توارد', 'مصدر', 'ورد', 'توارد', 'ترد', 'مص. تَوَارَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَارُدٌ-تَوَارُدٌ [و ر د] (مص. تَوَارَدَ). 1. ""تَوَارُدُ الجُمْهُورِ"" : حُضُورُهُ بِالتَّوَالِي. 2. ""تَوَارُدُ الْمَاءِ"" : وُرُودُهُ، بُلُوغُهُ. 3.""تَوَارُدُ الأفْكَارِ"" : اِتَّفَاقُهَا مِنْ غَيْرِ نَقْلٍ وَلاَ سَماعٍ. ""تَوَارُدُ الخَوَاطِر""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19815, 'تَوَارِي', 'تواري', 'مصدر', 'وري', 'تواري', 'تر', 'مص. تَوَارَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَوَارٍ-تَوَارٍ، التَّوارِي [و ري] (مص. تَوَارَى). 1. ""التَّوَارِي خَلْفَ الأشْجَارِ"" : الاخْتِفَاءُ، الاسْتِتارُ. 2. ""تَوَارِي الشَّمْسِ"" : اِخْتِفاؤُهَا فِي مَغْرِبِهَا، غُروبُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19816, 'تَوَازُنٌ', 'توازن', 'مصدر', 'وزن', 'توازن', 'تزن', 'مص. تَوَازَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَازُنٌ-تَوَازُنٌ [و زن] (مص. تَوَازَنَ). 1. ""تَمَيَّزَتِ الْمُبَارَاةُ بِتَوَازُنِ قُوَّةِ الفَرِيقَيْنِ"" : بِتَسَاوِيهَا، بِتَعَادُلِهَا. 2. ""فَقَدَ تَوَازُنَهُ ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19817, 'تَوازِي', 'توازي', 'مصدر', 'وزي', 'توازي', 'تز', 'مص. تَوازَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَوازٍ-تَوازٍ، التَّوازِي (مص. تَوازَى). ""تَوازِي الخَطَّيْنِ"" : تَكَوُّنُ بُعْدٍ وَاحِدٍ قَائِمٍ بَيْنَهُمَا فِي جَمِيعِ الجِهَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19818, 'تَوَاصُفٌ', 'تواصف', 'مصدر', 'وصف', 'تواصف', 'تصف', 'مص. تَوَاصَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَاصُفٌ-تَوَاصُفٌ [و ص ف] (مص. تَوَاصَفَ). ""تَوَاصُفُ الْمَنَاظِرِ"" : تَبَادُلُ وَصْفِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19819, 'تَوَاقُفٌ', 'تواقف', 'مصدر', 'وقف', 'تواقف', 'تقف', 'مص. تَوَاقَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَاقُفٌ-تَوَاقُفٌ [و ق ف] (مص. تَوَاقَفَ). ""تَوَاقُفُ الْمُنَاضِلِينَ فِي الكِفَاحِ"" : وُقُوفُ بَعْضِهِمْ مَع بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19820, 'تَوَاصُلٌ', 'تواصل', 'مصدر', 'وصل', 'تواصل', 'تصل', 'مص. تَوَاصَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَوَاصُلٌ-تَوَاصُلٌ [و ص ل] (مص. تَوَاصَلَ). 1. ""تَوَاصُلُ الحَبِيبَيْنِ"" : مُوَاصَلَةُ أحَدِهِمَا لِلآخَرِ فِي اتِّفَاقٍ وَوِئَامٍ. 2. ""تَوَاصُلُ الحَدِيثِ"" : تَوَالِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19821, 'تَوَاصِي', 'تواصي', 'مصدر', 'وصي', 'تواصي', 'تص', 'مص. تَوَاصى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَوَاصٍ-تَوَاصٍ، التَّواصِي [و ص ي] (مص. تَوَاصى). ""التَّوَاصِي بِالصَّبْرِ"" : التَّوْصِيَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19822, 'تَوَاضُعٌ', 'تواضع', 'مصدر', 'وضع', 'تواضع', 'تضع', 'مص. تَوَاضَع', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَاضُعٌ-تَوَاضُعٌ [و ض ع] (مص. تَوَاضَع). ""عُرِفَ بِتَوَاضُعِهِ الجَمِّ"" : إظْهَارُ الحِشْمَةِ وَعَدَمُ التَّكَبُّرِ وَالتَّعَظُّمِ. ""التَّوَاضُعُ مَعْنىً يَنْتظِمُ بِهِ جِمَاعُ الخَيْرِ وَالتَّواضُعُ عَقِيبُ الكِبْرِ"". (الجاحظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19823, 'تَوَاطُؤٌ', 'تواطؤ', 'مصدر', 'وطأ', 'تواطء', 'تط', 'مص. تَوَاطَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَوَاطُؤٌ-تَوَاطُؤٌ [و ط أ] (مص. تَوَاطَأَ). 1. ""تَوَاطُؤُ القَوْمِ"" : تَوَافُقُهُمْ. 2. ""ذَهَبَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19824, 'تَوَاعُدٌ', 'تواعد', 'مصدر', 'وعد', 'تواعد', 'تعد', 'مص. تَوَاعَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَاعُدٌ-تَوَاعُدٌ [و ع د] (مص. تَوَاعَدَ). 1. ""تَوَاعُدُ الأصْدِقَاءِ عَلَى الصِّدْقِ"" : وَعْدُ بَعْضِهِمْ بَعْضاً. 2. ""التَّوَاعُدُ عَلَى اللِّقَاءِ مسَاءً"" : تَحْدِيدُ مَوْعِدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19825, 'تَوَافُدٌ', 'توافد', 'مصدر', 'وفد', 'توافد', 'تفد', 'مص. تَوَافَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَافُدٌ-تَوَافُدٌ [و ف د] (مص. تَوَافَدَ). ""لَمْ يَكُنْ تَوَافُدُ الوُفُودِ إلاَّ تَعْبِيراً عَنِ الفَرَحِ"" : تَقَاطُرُهُمْ، تَوَارُدُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19826, 'تَوَافُرٌ', 'توافر', 'مصدر', 'وفر', 'توافر', 'تفر', 'مص. تَوَافَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَافُرٌ-تَوَافُرٌ [و ف ر] (مص. تَوَافَرَ). ""يَنْتَظِرُ تَوَافُرَ الْمَالِ لِيُنْجِزَ مَشْرُوعَهُ"" : تَجْمِيعَهُ بِكَثْرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19827, 'تَوَافُقٌ', 'توافق', 'مصدر', 'وفق', 'توافق', 'تفق', 'مص. تَوَافَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَوَافُقٌ-تَوَافُقٌ [و ف ق] (مص. تَوَافَقَ). ""بَيْنَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19828, 'تَوَاقُحٌ', 'تواقح', 'مصدر', 'وقح', 'تواقح', 'تقح', 'مص. تَوَاقَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَاقُحٌ-تَوَاقُحٌ [و ق ح] (مص. تَوَاقَحَ). ""تَوَاقُحُ الْمَرْأةِ"" : تَظَاهُرُهَا بِالوَقَاحَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19829, 'تَوَجُّدٌ', 'توجد', 'مصدر', 'وجد', 'توجد', 'تجد', 'مص. تَوَجَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَجُّدٌ-تَوَجُّدٌ [و ج د] (مص. تَوَجَّدَ). 1. ""أحَسَّ بِتَوجُّدٍ لَمَّا رَأَى صَاحِبَهُ فِي مِحْنَةٍ"" : بِحُزْنٍ. 2. ""لَمْ يَسْتَطِعْ إخْفَاءَ تَوَجُّدِهِ بِهَا"" : حُبُّهُ لَهَا. 3. ""تَوَجُّدُ أمْرٍ"" : شَكْوَاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19830, 'تَوَاكُلٌ', 'تواكل', 'مصدر', 'وكل', 'تواكل', 'تكل', 'مص. تَوَاكَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَاكُلٌ-تَوَاكُلٌ [و ك ل] (مص. تَوَاكَلَ). ""تَرَكَهُ التَّوَاكُلُ فِي خُمُولٍ"" : الاسْتِسْلامُ، الاتِّكَالُ عَلَى الغَيْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19831, 'تَوَالُدٌ', 'توالد', 'مصدر', 'ولد', 'توالد', 'تلد', 'مص. تَوَالَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَالُدٌ-تَوَالُدٌ [و ل د] (مص. تَوَالَدَ). ""شَعْبٌ فِي تَوَالُدٍ مُسْتَمِرٍّ"" : فِي تَكَاثُرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19832, 'تَوَالِي', 'توالي', 'مصدر', 'ولي', 'توالي', 'تل', 'مص. تَوَالَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَوَالٍ-تَوَالٍ، التَّوَالِي [و ل ي] (مص. تَوَالَى). ""اِسْتطَاعَ مَعَ تَوَالِي الأيَّامِ أنْ يُحَقِّقَ أهْدَافَهُ"" : مَعَ مُرُورِهَا، تَتَابُعِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19833, 'تَوانِي', 'تواني', 'مصدر', 'وني', 'تواني', 'تن', 'مص. تَوَانَى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَوانٍ-تَوانٍ، التَّوانِي [و ن ي] (مص. تَوَانَى). ""التَّوَانِي فِي العَم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19834, 'تَوَاهُبٌ', 'تواهب', 'مصدر', 'وهب', 'تواهب', 'تهب', 'مص. تَوَاهَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَاهُبٌ-تَوَاهُبٌ [و هـ ب] (مص. تَوَاهَبَ). ""تَوَاهُبُ النَّاسِ"": وَهْبُ بَعْضِهِمْ لِبَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19835, 'تَوَتُّرٌ', 'توتر', 'مصدر', 'وتر', 'توتر', 'تتر', 'مص. تَوَتَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَتُّرٌ-تَوَتُّرٌ [و ت ر] (مص. تَوَتَّرَ). 1. ""تَوَتُّرُ الأعْصَابِ"" : اِشْتِدَادُهَا وَتَعَصُّبُهَا. 2. ""تَوَتُّرُ العَلاقَاتِ"" : عِنْدَمَا تَصِلُ العَلاقَاتُ إلَى مَرْحَلَةِ القَطِيعَةِ وَالإسَاءةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19836, 'تَوَثُّبٌ', 'توثب', 'مصدر', 'وثب', 'توثب', 'تثب', 'مص. تَوَثَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَثُّبٌ-تَوَثُّبٌ [و ث ب] (مص. تَوَثَّبَ). 1. ""بَارِعٌ فِي التَّواثُبِ"" : فِي القَفْزِ. 2. ""التَّوَثُّبُ عَلَيْهِ فِي الأَرْضِ"" : الاسْتِيلاءُ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19837, 'تَوَثُّقٌ', 'توثق', 'مصدر', 'وثق', 'توثق', 'تثق', 'مص. تَوَثَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَثُّقُ-تَوَثُّقُ [و ث ق] (مص. تَوَثَّقَ). ""تَوَثُّقُ عُرَى الصَّدَاقَةِ"": تَقوِّيهَا، تَثَبُّتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19838, 'تَوَجُّبٌ', 'توجب', 'مصدر', 'وجب', 'توجب', 'تجب', 'مص. تَوَجَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَجُّبٌ-تَوَجُّبٌ [و ج ب] (مص. تَوَجَّبَ). ""مِنْ عَادَتِهِ التَّوَجُّبُ"" : أكْلُ وَجْبَةٍ واحِدَةٍ فِي اليَوْمِ والليْلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19839, 'تَوَدُّعٌ', 'تودع', 'مصدر', 'ودع', 'تودع', 'تدع', 'مص. تَوَدَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَدُّعٌ-تَوَدُّعٌ [و د ع] (مص. تَوَدَّعَ). ""تَوَدُّعُ الأَصْدِقَاءِ"" : تَوْدِيعُ بَعْضِهِمْ بَعْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19840, 'تَوَجُّسٌ', 'توجس', 'مصدر', 'وجس', 'توجس', 'تجس', 'مص. تَوَجَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَجُّسٌ-تَوَجُّسٌ [و ج س] (مص. تَوَجَّسَ). 1. ""تَوَجُّسُ صَوْتٍ"": تَسَمُّعُهُ. 2. ""كَانَ تَوَجُّسُهُ كَبِيراً"" : تَخَوُّفُهُ، إحْسَاسُهُ بِالخَوْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19841, 'تَوَجُّعٌ', 'توجع', 'مصدر', 'وجع', 'توجع', 'تجع', 'مص. تَوَجَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَجُّعٌ-تَوَجُّعٌ [و ج ع] (مص. تَوَجَّعَ). ""اِشْتَدَّ تَوَجُّعُ الْمَرِيضِ"": التَّفَجُّعُ، التَّشَكِّي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19842, 'تَوَجُّهٌ', 'توجه', 'مصدر', 'وجه', 'توجه', 'تجه', 'مص. تَوجَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَجُّهٌ-تَوَجُّهٌ [و ج هـ] (مص. تَوجَّهَ). ""التَّوَجُّهُ نَحْوَ البَابِ"": السَّيْرُ نَحْوَ البَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19843, 'تَوَحُّدٌ', 'توحد', 'مصدر', 'وحد', 'توحد', 'تحد', 'مص. تَوَحَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَحُّدٌ-تَوَحُّدٌ [و ح د] (مص. تَوَحَّدَ). 1. ""تَوَحُّدُهُ بِمَوْقِفِهِ"": اِنْفِرَادُهُ ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19844, 'تَوَحُّشٌ', 'توحش', 'مصدر', 'وحش', 'توحش', 'تحش', 'مص. تَوَحَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَحُّشٌ-تَوَحُّشٌ [و ح ش] (مص. تَوَحَّشَ). ""فِي تَصَرُّفِهِ تَوَحُّشٌ"" : شَرَاسَةٌ، وَحْشِيَّةٌ، خُشُونَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19845, 'تَوَحُّلٌ', 'توحل', 'مصدر', 'وحل', 'توحل', 'تحل', 'مص. تَوَحَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَحُّلٌ-تَوَحُّلٌ [و ح ل] (مص. تَوَحَّلَ). 1. ""تَوَحُّلُ شَارِعٍ"" : صَيْرُهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19846, 'تَوَحُّمٌ', 'توحم', 'مصدر', 'وحم', 'توحم', 'تحم', 'مص. تَوَحَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَحُّمٌ-تَوَحُّمٌ [و ح م] (مص. تَوَحَّمَ). ""تَوَحُّمُ الْمَرْأَةِ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19847, 'تَوَخٍّ', 'توخ', 'مصدر', 'وخي', 'توخ', 'تخ', 'مص. تَوَخَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَخٍّ-تَوَخٍّ، التَّوَخِّي [و خ ي] (مص. تَوَخَّى). 1. ""تَوَخِّي الأَهْدَافِ الْمَرْسُومَةِ"" : تَطَلُّبُهَا، قَصْدُهَا. 2. ""مِنَ الأُمُورِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19848, 'تَوَدُّدٌ', 'تودد', 'مصدر', 'ودد', 'تودد', 'تد', 'مص. تَوَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَدُّدٌ-تَوَدُّدٌ [و د د] (مص. تَوَدَّدَ). 1. ""تَوَدُّدُ الْمَوَدَّةِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19849, 'تَوَسُّعٌ', 'توسع', 'مصدر', 'وسع', 'توسع', 'تسع', 'مص. تَوَسَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَوَسُّعٌ-تَوَسُّعٌ [و س ع] (مص. تَوَسَّعَ). 1.""تَوَسُّعُ الجمَاعَةِ فِي الْمَجْلِسِ"" : التَّفَسُّحُ فِيهِ. 2. ""تَوَسُّعُ الْمَدِينَةِ"" : اِتِّسَاعُهَا، كِبَرُهَا. 3. ""التَّوَسُّعُ فِي النَّفَقَةِ"" : الإِكِثْارُ مِنْهَا، بَسْطُ اليَدِ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19850, 'تَوَرُّدٌ', 'تورد', 'مصدر', 'ورد', 'تورد', 'ترد', 'مص. تَوَرَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَرُّدٌ-تَوَرُّدٌ [و ر د] (مص. تَوَرَّدَ). 1. ""تَوَرُّدُ الخَدِّ"" : اِحْمِرارُهُ وَصَيْرُهُ بِلَوْنِ الوَرْدِ. 2. ""تَوَرُّدُ الإبِلِ الْمَاءَ"" : بُلُوغُهَا إِيَّاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19851, 'تَوَرُّطٌ', 'تورط', 'مصدر', 'ورط', 'تورط', 'ترط', 'مص. تَوَرَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَرُّطٌ-تَوَرُّطٌ [و ر ط] (مص. تَوَرَّطَ). ""أوْقَعَهُ فِي تَوَرُّطٍ لاَ مَخْرَجَ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19852, 'تَوَرُّعٌ', 'تورع', 'مصدر', 'ورع', 'تورع', 'ترع', 'مص. تَوَرَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَرُّعٌ-تَوَرُّعٌ [و ر ع] (مص. تَوَرَّعَ). ""التَّوَرُّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19853, 'تَوَرُّكٌ', 'تورك', 'مصدر', 'ورك', 'تورك', 'ترك', 'مص. تَوَرَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَرُّكٌ-تَوَرُّكٌ [و ر ك] (مص. تَوَرَّكَ). 1. ""تَوَرُّكُ الرَّجُلِ"" : اِعْتِمَادُهُ عَلَى وَرِكِهِ. 2. ""تَوَرُّكُ الْمُصَلِّي"" : وَضْعُ يَدَيْهِ عَلَى وَرِكَيْهِ. 3. ""التَّوَرُّكُ عَلَى العَمَلِ"" : القُدْرَةُ عَلَيْهِ. 4. ""التَّوَرُّكُ عَنِ الحَاجَةِ"" : التَّبَاطُؤُ، التَّأَخُّر، التَّوَانِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19854, 'تَوَرُّمٌ', 'تورم', 'مصدر', 'ورم', 'تورم', 'ترم', 'مص. تَوَرَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَرُّمٌ-تَوَرُّمٌ [و ر م] (مص. تَوَرَّمَ). ""تَوَرُّمُ الجِلْدِ"" : اِنْتِفَاخُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19855, 'تَوَزُّرٌ', 'توزر', 'مصدر', 'وزر', 'توزر', 'تزر', 'مص. تَوَزَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَزُّرٌ-تَوَزُّرٌ [و ز ر] (مص. تَوَزَّرَ). 1. ""طَلَبَ مِنِهُ التَّوَزُّرَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19856, 'تَوَزُّعٌ', 'توزع', 'مصدر', 'وزع', 'توزع', 'تزع', 'مص. تَوَزَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَزُّعٌ-تَوَزُّعٌ [و ز ع] (مص. تَوَزَّعَ). 1."" تَوَزُّعُ الغَنِيمَةِ"" : تَفَرُّقُهَا. 2. ""تَوَزُّعُ الْمُتَحَارِبِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19857, 'تَوسُّخٌ', 'توسخ', 'مصدر', 'وسخ', 'توسخ', 'تسخ', 'مص. تَوَسَّخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوسُّخٌ-تَوسُّخٌ [و س خ] (مص. تَوَسَّخَ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19858, 'تَوسُّدٌ', 'توسد', 'مصدر', 'وسد', 'توسد', 'تسد', 'مص. تَوَسَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوسُّدٌ-تَوسُّدٌ [و س د] (مص. تَوَسَّدَ). 1. ""تَوَسُّدُ الوِسَادةِ"": وَضْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19859, 'تَوَطُّدٌ', 'توطد', 'مصدر', 'وطد', 'توطد', 'تطد', 'مص. تَوَطَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَطُّدٌ-تَوَطُّدٌ [و ط د] (مص. تَوَطَّدَ). ""تَوَطُّدُ دَعَائِمِ السُّلْطَةِ"": تَثَبُّتُهَا، تَرَسُّخُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19860, 'تَوَسُّلٌ', 'توسل', 'مصدر', 'وسل', 'توسل', 'تسل', 'مص. تَوَسَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَسُّلٌ-تَوَسُّلٌ [و س ل] (مص. تَوَسَّلَ). ""رَفَعَ أكُفَّهُ تَوَسُّلاً إلَى اللَّهِ"" : اِبْتِهَالاً، تَقَرُّباً، اِسْتِشْفَاعاً. ""لَمْ يَبْقَ أمَامَهُ إلاَّ التَّوَسُّلَ إلَى اللَّهِ وَأنْبِيَائِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19861, 'تَوَسُّمٌ', 'توسم', 'مصدر', 'وسم', 'توسم', 'تسم', 'مص. تَوَسَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَسُّمٌ-تَوَسُّمٌ [و س م] (مص. تَوَسَّمَ). ""تَوَسُّمُ الخَيْرِ فِي الرَّجُلِ"" : تَوَقُّعُهُ، تَبَيُّنُ أثَرِهِ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19862, 'تَوَسُّنٌ', 'توسن', 'مصدر', 'وسن', 'توسن', 'تسن', 'مص. تَوَسَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَسُّنٌ-تَوَسُّنٌ [و س ن] (مص. تَوَسَّنَ). """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19863, 'تَوَشُّحٌ', 'توشح', 'مصدر', 'وشح', 'توشح', 'تشح', 'مص تَوَشَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَشُّحٌ-تَوَشُّحٌ [و ش ح] (مص تَوَشَّحَ). 1.""تَوَشُّحُ القَائِدِ"":"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19864, 'تَوَشْوُشٌ', 'توشوش', 'مصدر', 'وشوش', 'توشوش', 'تشش', 'مص. تَوَشْوَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَشْوُشٌ-تَوَشْوُشٌ [و ش وش] (مص. تَوَشْوَشَ). """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19865, 'تَوشِّي', 'توشي', 'مصدر', 'وشي', 'توشي', 'تش', 'مص. تَوَشَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَوشٍّ-تَوشٍّ، التَّوَشِّي [و ش ي] (مص. تَوَشَّى)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19866, 'تَوَصُّلٌ', 'توصل', 'مصدر', 'وصل', 'توصل', 'تصل', 'مص. تَوَصَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَصُّلٌ-تَوَصُّلٌ [و ص ل] (مص. تَوَصَّلَ). 1. ""يُحَاوِلُ التَّوَصُّلَ إلَى حَلِّ مَشَاكِلِهِ"" : الاِنْتِهَاءُ، البُلُوغُ إلَى حَلِّهَا. 2.""التَّوَصُّلُ بإيصَالِ الكِرَاءِ"" : تَسَلُّمُهُ. 3. ""التَّوَصُّلُ إلَيْهِ"" : التَّوَسُّطُ، التَّقَرُّبُ، التَّوَسُّلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19867, 'تَوَضُّؤٌ', 'توضؤ', 'مصدر', 'وضأ', 'توضء', 'تض', 'مص. تَوَضَّأ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَوَضُّؤٌ-تَوَضُّؤٌ [و ض أ] (مص. تَوَضَّأ). ""التَّوَضُّؤُ لِلصَّلاةِ"" : الاغْتِسَالُ، أداءُ شَعِيرَةِ الوُضُوءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19868, 'تَوَضُّحٌ', 'توضح', 'مصدر', 'وضح', 'توضح', 'تضح', 'مص. تَوَضَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَضُّحٌ-تَوَضُّحٌ [و ض ح] (مص. تَوَضَّحَ). 1. ""تَوَضُّحُ الصُّورَةِ"" : اِتِّضَاحُهَا، بُرُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19869, 'تَوَفِّي', 'توفي', 'مصدر', 'وفي', 'توفي', 'تف', 'مص. تَوَفَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَوَفٍّ-تَوَفٍّ، التَّوَفِّي [و ف ي] (مص. تَوَفَّى). ""تَوَفِّي الحَقِّ"": أخْذُهُ كَامِلاً، وَافِياً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19870, 'تَوَطُّنٌ', 'توطن', 'مصدر', 'وطن', 'توطن', 'تطن', 'مص. تَوَطَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَطُّنٌ-تَوَطُّنٌ [و ط ن] (مص. تَوَطَّنَ). 1. ""التَّوَطُّنُ فِي بِلادٍ"": اِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19871, 'تَوَظُّفٌ', 'توظف', 'مصدر', 'وظف', 'توظف', 'تظف', 'مص. تَوَظَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَظُّفٌ-تَوَظُّفٌ [و ظ ف] (مص. تَوَظَّفَ). ""يُرِيدُ التَّوَظُّفَ فِي الْمُؤَسَّسَةِ"" : الحُصُولَ عَلَى وَظِيفَةٍ، تَوَلِّي وَظِيفَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19872, 'تَوَعُّدٌ', 'توعد', 'مصدر', 'وعد', 'توعد', 'تعد', 'مص. تَوَعَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَعُّدٌ-تَوَعُّدٌ [و ع د] (مص. تَوَعَّدَ). ""لَمْ يَفْهَمْ سَبَبَ تَوَعُّدِهِ"": تَهَدُّدِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19873, 'تَوَعُّرٌ', 'توعر', 'مصدر', 'وعر', 'توعر', 'تعر', 'مص. تَوَعَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَعُّرٌ-تَوَعُّرٌ [و ع ر] (مص. تَوَعَّرَ). 1. ""تَوَعُّرُ الطَّرِيقِ"" : صُعُوبَتُهُ، تَعَسُّرُهُ. 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19874, 'تَوَعُّكٌ', 'توعك', 'مصدر', 'وعك', 'توعك', 'تعك', 'مص. تَوَعَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَعُّكٌ-تَوَعُّكٌ [و ع ك] (مص. تَوَعَّكَ). ""أصَابَهُ تَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19875, 'تَوَغُّرٌ', 'توغر', 'مصدر', 'وغر', 'توغر', 'تغر', 'مص. تَوَغَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَغُّرٌ-تَوَغُّرٌ [و غ ر] (مص. تَوَغَّرَ). ""تَوَغّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19876, 'تَوَغُّلٌ', 'توغل', 'مصدر', 'وغل', 'توغل', 'تغل', 'مص. تَوَغَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَغُّلٌ-تَوَغُّلٌ [و غ ل] (مص. تَوَغَّلَ). 1. ""نَبَّهَهُ مِنَ التَّوَغُّلِ فِي الغَابَةِ"" : مِنْ وُلـُوجِ أدْغَالِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19877, 'تَوَفُّرٌ', 'توفر', 'مصدر', 'وفر', 'توفر', 'تفر', 'مص. تَوَفَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَفُّرٌ-تَوَفُّرٌ [و ف ر] (مص. تَوَفَّرَ). 1.""التَّوَفُّرُ عَلَى أَعْمَالِ الخَيْرِ"": صَرْفُ الْهِمَّةِ إِلَيْهَا. 2. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19878, 'تَوَفُّقٌ', 'توفق', 'مصدر', 'وفق', 'توفق', 'تفق', 'مص. تَوَفَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَفُّقٌ-تَوَفُّقٌ [و ف ق] (مص. تَوَفَّقَ). 1. ""التَّوَفُّقُ فِي العَمَلِ"": النَّجَاحُ فِيهِ. 2. ""تَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19879, 'تَوَلُّجٌ', 'تولج', 'مصدر', 'ولج', 'تولج', 'تلج', 'مص. تَوَلَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَلُّجٌ-تَوَلُّجٌ [و ل ج] (مص. تَوَلَّجَ). 1.""التَّوَلُّجُ فِي الدَّارِ"" : الدُّخُول فِيهَا. ""التَّوَلُّجُ عَلَيْهِ"". 2. ""كَانَ أهْلاً لِتَوَلُّجِ المسْؤُولِيَّةِ"" : لِتَسَلُّمِها، القِيامُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19880, 'تَوَقُّحٌ', 'توقح', 'مصدر', 'وقح', 'توقح', 'تقح', 'مص. تَوَقَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَقُّحٌ-تَوَقُّحٌ [و ق ح] (مص. تَوَقَّحَ). 1. ""تَوَقُّحُ الوَلَدِ"" : قِلَّةُ حَيَائِهِ. 2. ""تَوَقُّحُ الحَرَارةِ"" : اِشْتِدَادُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19881, 'تَوَقُّدٌ', 'توقد', 'مصدر', 'وقد', 'توقد', 'تقد', 'مص. تَوَقَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَقُّدٌ-تَوَقُّدٌ [و ق د] (مص. تَوَقَّدَ). 1. ""تَوَقُّدُ النَّارِ"" : اِشْتِعَالُهَا. 2. ""تَوَقُّدُ الذِّهْنِ"" : تَنَبُّهُهُ، صَيْرُهُ ذَكِيّاً، نَابِهاً. 3.""تَوَقُّدُهُ نَاراً"" : إِشْعَالُهُ النَّارَ. 4. ""تَوَقُّدُ الكَواكِبِ"" : تَلأْلُؤُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19882, 'تَوَقُّرٌ', 'توقر', 'مصدر', 'وقر', 'توقر', 'تقر', 'مص. تَوَقَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَقُّرٌ-تَوَقُّرٌ [و ق ر] (مص. تَوَقَّرَ). تَوَقُّرُ الرَّجُلِ"" : صَيْرُهُ وَقُوراً، رَزِيناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19883, 'تَوَقُّعٌ', 'توقع', 'مصدر', 'وقع', 'توقع', 'تقع', 'مص. تَوَقَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَقُّعٌ-تَوَقُّعٌ [و ق ع] (مص. تَوَقَّعَ). ""كَانَ تَوَقُّعُهُ فِي غَيْرِ مَكَانِهِ"" : تَرَقُّبُهُ، تَكَهُّنُهُ، تَحَسُّبُهُ. ""تَوَقُّعاً لِكُلِّ احْتِمَالٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19884, 'تَوَقُّفٌ', 'توقف', 'مصدر', 'وقف', 'توقف', 'تقف', 'مص. تَوَقَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَقُّفٌ-تَوَقُّفٌ [و ق ف] (مص. تَوَقَّفَ). 1. ""أعْلَنَ العُمَّالُ التَّوَقُّفَ عَنِ العَمَلِ"" : الإِضْرَابَ، الامْتِنَاعَ عَنِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19885, 'تَوَقِّي', 'توقي', 'مصدر', 'وقي', 'توقي', 'تق', 'مص. تَوَقَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَوَقٍّ-تَوَقٍّ، التَّوَقِّي [و ق ي] (مص. تَوَقَّى). 1.""تَوَقّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19886, 'تَوَكُّؤٌ', 'توكؤ', 'مصدر', 'وكأ', 'توكء', 'تك', 'مص. تَوَكَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَوَكُّؤٌ-تَوَكُّؤٌ [و ك أ] (مص. تَوَكَّأَ). ""التَّوَك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19887, 'تَوَكُّدٌ', 'توكد', 'مصدر', 'وكد', 'توكد', 'تكد', 'مص. تَوَكَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَكُّدٌ-تَوَكُّدٌ [و ك د] (مص. تَوَكَّدَ). ""تَوَكُّدُ الشَّيْءِ"" : تَوَثُّقُهُ، اِشْتِدَادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19888, 'تَوَكُّلٌ', 'توكل', 'مصدر', 'وكل', 'توكل', 'تكل', 'مص. تَوَكَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَكُّلٌ-تَوَكُّلٌ [و ك ل] (مص. تَوَكَّلَ). 1. ""التَّوَكُّلُ عَلَى اللَّهِ"": الاعْتِمَادُ عَلَى اللَّهِ. 2. ""قَبِلَ تَوَكُّلَهُ لَهُ بِالنَّجَاحِ شَرِيطَةَ اجْتِهَادهِ"" : التَّكَفُّلَ لَهُ. 3. ""قَبِلَ التَّوَكُّلَ بِأُمُورِهِ"" : ضمَانَ القِيَامِ بِهَا، 4. ""التَّوَكُّلُ فِي الأمْرِ"" : إظْهَارُ العَجْزِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19889, 'تَوَهُّنٌ', 'توهن', 'مصدر', 'وهن', 'توهن', 'تهن', 'مص. تَوَهَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَهُّنٌ-تَوَهُّنٌ[و هـ ن] (مص. تَوَهَّنَ). ""تَوَهُّنُ الرَّجُلِ"": ضُعْفُهُ وَذَهابُ قُوَّتِهِ وَصِحَّتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19890, 'تَوَلُّدٌ', 'تولد', 'مصدر', 'ولد', 'تولد', 'تلد', 'مص. تَوَلَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَلُّدٌ-تَوَلُّدٌ [و ل د] (مص. تَوَلَّدَ). ""تَوَلُّدُ الجَرَاثِيمِ"" : نَشْأتُها، تَنَاسُلُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19891, 'تَوَلُّعٌ', 'تولع', 'مصدر', 'ولع', 'تولع', 'تلع', 'مص. تَوَلَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَلُّعٌ-تَوَلُّعٌ [و ل ع] (مص. تَوَلَّعَ). ""تَوَلُّعُهُ بِلُعْبَةِ الشِّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19892, 'تَوَلُّهٌ', 'توله', 'مصدر', 'وله', 'توله', 'تله', 'مص. تَوَلَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَلُّهُ-تَوَلُّهُ [و ل هـ] (مص. تَوَلَّهَ).1. ""تَوَلُّهُ الرَّجُلِ"" : اِشْتِدَادُ حُزْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19893, 'تَوَلْوُلٌ', 'تولول', 'مصدر', 'ولول', 'تولول', 'تلل', 'مص. تَوَلْوَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَلْوُلٌ-تَوَلْوُلٌ [و ل و ل] (مص. تَوَلْو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19894, 'تَوَلِّي', 'تولي', 'مصدر', 'ولي', 'تولي', 'تل', 'مص. تَوَلَّى', 'Tk', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَوَلٍّ-تَوَلٍّ، التَّوَلِّي [و ل ي] (مص. تَوَلَّى). 1. ""اِتَّفَقُوا عَلَى تَولِّيهِ حُكْمَ البِلادِ"" : تَقَلُّدِهِ. 2. ""أظْهَرَ بِغَضَبِهِ تَوَلِّيَهُ عَنْهُ"": إعْرَاضَه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19895, 'تَتْوِيهٌ', 'تتويه', 'مصدر', 'توه', 'تتويه', 'تته', 'مص. تَوَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَتْوِيهٌ-تَتْوِيهٌ [ت و هـ] (مص. تَوَّهَ). 1.""كَانَ تَتْوِيهُ صَاحِبِهِ عَنْ عَمْدٍ"" : جَعْلُهُ يَضِلُّ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19896, 'تَوَهُّج', 'توهج', 'مصدر', 'وهج', 'توهج', 'تهج', 'مص. تَوَهَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَهُّج-تَوَهُّجٌ [و هـ ج] (مص. تَوَهَّجَ). 1.""تَوَهُّجُ النِّيرانِ"": تَوَقُّدُها. 2.""تَوَهُّجُ وَجْهِهِ"" : إِضاءَتُهُ، نَضارَتُهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19897, 'تَوَهُّدٌ', 'توهد', 'مصدر', 'وهد', 'توهد', 'تهد', 'مص. تَوَهَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَهُّدٌ-تَوَهُّدٌ [و هـ د] (مص. تَوَهَّدَ). ""تَوَهُّدُ الفِراشِ"" : تَمَهُّدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19898, 'تَوَهُّمٌ', 'توهم', 'مصدر', 'وهم', 'توهم', 'تهم', 'مص. تَوَهَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوَهُّمٌ-تَوَهُّمٌ [و هـ م] (مص. تَوَهَّمَ). 1.""تَوَهُّمُ مَرَضٍ"" : تَوَقُّعُهُ، ظَنُّهُ. ""الرَّيْبُ والشَّكُّ والظَّنُّ والت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19899, 'تَياسُرٌ', 'تياسر', 'مصدر', 'يسر', 'تياسر', 'تسر', 'مص. تَياسَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَياسُرٌ-تَياسُرٌ [ي س ر] (مص. تَياسَرَ). 1.""التَّياسُرُ في الطَّريقِ"" : السَّيْرُ في جِهَةِ اليَسارِ. 2.""التَّياسُرُ في الأمْرِ"" : التَّساهُلِ فيهِ. 3.""التَّياسُرُ في المواقِفِ السِّياسِيَّةِ"" : التَّطَرُّفُ فِيها، التَّعَصُّبُ لَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19900, 'تَيامُنٌ', 'تيامن', 'مصدر', 'يمن', 'تيامن', 'تمن', 'مص. تَيامَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَيامُنٌ-تَيامُنٌ [ي م ن] (مص. تَيامَنَ). ""التَّيامُنُ في الطَّريقِ"" : السَّيْرُ في جِهَةِ اليَمينِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19901, 'تَيَسُّرٌ', 'تيسر', 'مصدر', 'يسر', 'تيسر', 'تسر', 'مص. تَيَسَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَيَسُّرٌ-تَيَسُّرٌ [ي س ر] (مص. تَيَسَّرَ). 1.""تَيَسُّرُ الأُمورِ"" : تَسَهُّلُها. 2.""التَّيَسُّرُ لِلْمَعْرَكَةِ"" : التَّهَيُّؤُ لَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19902, 'تَيَفُّعٌ', 'تيفع', 'مصدر', 'يفع', 'تيفع', 'تفع', 'مص. تَيَفَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَيَفُّعٌ-تَيَفُّعٌ [ي ف ع] (مص. تَيَفَّعَ). ""تَيَفُّعُ الغُلامِ"" : مُقارَبَتُهُ البُلوغَ، تَرَعْرُعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19903, 'تَيَقُّظٌ', 'تيقظ', 'مصدر', 'يقظ', 'تيقظ', 'تقظ', 'مص. تَيَقَّظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَيَقُّظٌ-تَيَقُّظٌ [ي ق ظ] (مص. تَيَقَّظَ). 1.""التَّيَقُّظُ مِنَ النَّوْمِ"": الصَّحْوُ مِنْهُ. 2.""التَّيَقُّظُ لِلْمَعْرَكَةِ"" : التَّهَيُّؤُ لَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19904, 'تَيَقُّنٌ', 'تيقن', 'مصدر', 'يقن', 'تيقن', 'تقن', 'مص. تَيَقَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَيَقُّنٌ-تَيَقُّنٌ [ي ق ن] (مص. تَيَقَّنَ). ""تَيَقُّنُ الخَبَرِ"" : تَحَقُّقُهُ، عِلْمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19905, 'تَيَمُّمٌ', 'تيمم', 'مصدر', 'يمم', 'تيمم', 'تم', 'مص. تَيَمَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَيَمُّمٌ-تَيَمُّمٌ [ي م م] (مص. تَيَمَّمَ). 1.""التَّيَمُّمُ لِلصَّلاةِ"" : مَسْحُ اليَدَيْنِ وَالوَجْهِ على الحَجَرِ أوْ بِالتُّرابِ لأَداءِ الصَّلاةِ بَدَلَ الوُضوءِ. 2.""تَيَمُّمُ أَمْرٍ"" : طَلَبُهُ، تَوَخِّيهِ، تَعَمُّدُهُ، قَصْدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19906, 'تَيَمُّنٌ', 'تيمن', 'مصدر', 'يمن', 'تيمن', 'تمن', 'مص. تَيَمَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَيَمُّنٌ-تَيَمُّنٌ [ي م ن] (مص. تَيَمَّنَ). 1.""تَيَمُّنُهُ كَبيرٌ"": تَفاؤُلُهُ. 2.""التَّيَمُّنُ بِالوَلِيِّ الصَّالِحِ"" : التَّبَرُّكُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19907, 'مُثَابَرَةٌ', 'مثابرة', 'مصدر', 'ثبر', 'مثابرة', 'مثبرة', 'مص. ثَابَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُثَابَرَةٌ-مُثَابَرَةٌ [ث ب ر] (مص. ثَابَرَ). ""الْمُثَابَرَةُ عَلَى العَمَلِ"": الْمُوَاظَبَةُ، الْمُدَاوَمَةُ. ""فَمَنْ مَنَّ عَلَيْهِ خَالِقُهُ بِالعَقْلِ وَأَعَانَ عَلَى نَفْسِهِ بِالْمُثَابَرَةِ عَلَى الأَدَبِ وَالحِرْصِ عَلَيْهِ سَعِدَ حَظُّهُ"" (ابن المقفع) l ""الْمُثابَرَةُ خَيْرٌ مِنَ الْمَهَارَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19908, 'ثَأْرٌ', 'ثأر', 'مصدر', 'ثأر', 'ثءر', 'ثر', 'مص. ثَأَرَ', '', '', 'مفرد', 'DnN', '', '', '"أثْآرٌ:ثَارَاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ثَأَرَ). 1.""اِسْتَقَرَّتْ فِكْرَةُ الثَّأْرِ فِي نَفْسِهِ"" : الْمُطَالَبَةُ بِدَمِ القَتِيلِ. 2.""أَخَذَ بِثَأْرِهِ"" : قَتَل القَاتِلَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19909, 'أثْآرٌ', 'أثآر', 'مصدر', '', 'ءثءءر', 'ثآر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19910, 'ثَارَاتٌ', 'ثارات', 'مصدر', '', 'ثارات', 'ثرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19911, 'ثَوَرَانٌ', 'ثوران', 'مصدر', 'ثور', 'ثوران', 'ثرن', 'مص. ثَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ثَوَرَانٌ-ثَوَرَانٌ [ث و ر] (مص. ثَارَ). 1.""وَجَدَهُ فِي ثَوَرَانٍ"" : فِي غَلَيَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19912, 'ثِقَافٌ', 'ثقاف', 'مصدر', 'ثقف', 'ثقاف', 'ثقف', 'مص. ثَاقَفَ.', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَثْقِفَةٌ:ثُقُفٌ"', '', 'Rp', '', '', '', '', '', '', '"ج: أَثْقِفَةٌ، ثُقُفٌ. (مص. ثَاقَفَ). 1.""ثِقَافُ الرِّمَاحِ"" : أَدَاةٌ مِنْ حَدِيدٍ أَوْ خَشَبٍ تُقَوَّمُ بِهَا الرِّمَاحُ وَتُسَوَّى. 2.""بَيْنَهُمَا ثِقَافٌ"" : خِصَامٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19913, 'أَثْقِفَةٌ', 'أثقفة', 'مصدر', '', 'ءثقفة', 'ثقفة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19914, 'ثُقُفٌ', 'ثقف', 'مصدر', '', 'ثقف', 'ثقف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19915, 'ثبَاتٌ', 'ثبات', 'مصدر', 'ثبت', 'ثبات', 'ثبت', 'مص. ثَبَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ثبَاتٌ-ثبَاتٌ [ث ب ت] (مص. ثَبَتَ). 1.""الثَّبَاتُ عَلَى الرَّأْيِ"": الاسْتِمْرَارُ فِيهِ. ""لاَ ثبَاتَ لِمَنْ لاَ إيمَانَ لَهُ"" ""وَكَانَتْ جَمِيعُ أعْمَالِهَا مَقْرُونَةً بِالثَّبَاتِ وَالصَّبْرِ وَالاعْتِنَاءِ"". (جبران خ.جبران). 2.""الثَّبَاتُ فِي الْمَكَانِ"" : الاِسْتِقْرَارُ فِيهِ. ""كُلُّنَا نَحْتَرِقُ أنْتَ فِي ثَبَاتِكَ وَأنَا فِي طَوَافِي"".(جمَال الغيطاني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19916, 'ثُبُوتٌ', 'ثبوت', 'مصدر', 'ثبت', 'ثبوت', 'ثبت', 'مص. ثَبَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ثُبُوتٌ-ثُبُوتٌ [ث ب ت] (مص. ثَبَتَ). ""الثُّبُوتُ فِي المَكَانِ"": الْمُكُوثُ، الدَّوَامُ. ""إِنَّمَا الثُّبُوتُ الدَّائِمُ لِدَارِ القَرَارِ"". (الجاحظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19917, 'ثُبُورٌ', 'ثبور', 'مصدر', 'ثبر', 'ثبور', 'ثبر', 'مص. ثَبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ثُبُورٌ-ثُبُورٌ [ث ب ر] (مص. ثَبَرَ). ""الثُّبورُ لَهُ إنْ هُوَ أخْلَفَ وَعْدَهُ"" : الهلاكُ، الوَيْلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19918, 'ثُخونَةٌ', 'ثخونة', 'مصدر', 'ثخن', 'ثخونة', 'ثخنة', 'مص. ثَخُنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ثُخونَةٌ-ثُخونَةٌ [ث خ ن] (مص. ثَخُنَ). 1.""ثُخُونَةُ ثَوْبٍ"" : غِلَظُهُ. 2.""ثُخُونَةُ خَشَبٍ"" : صَلاَبَتُهُ. ""بابٌ خَشَبُهُ أقَلُّ ثُخُونَةً"".(محمد برادة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19919, 'ثَرَاءٌ', 'ثراء', 'مصدر', 'ثرو', 'ثراء', 'ثر', 'مص. ثَرَا، ثَرِيَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"ثَرَاءٌ-ثَرَاءٌ [ث ر و] (مص. ثَرَا، ثَرِيَ). 1.""يَعِيشُ فِي ثَرَاءٍ عَمِيمٍ"" : فِي خَيْرِ عَمِيمٍ، فِي غِنىً. 2.""حَقَّقَ ثَرَاءً كَثِيراً"" : مَالاً كَثِيراً. ""كُلَّمَا زَادَ الْمَرْءُ ثَرَاءً زادَهُ المالُ اِسْتِعْباداً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19920, 'تَثْرِيبٌ', 'تثريب', 'مصدر', 'ثرب', 'تثريب', 'تثرب', 'مص. ثَرَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَثْرِيبٌ-تَثْرِيبٌ [ث ر ب] (مص. ثَرَّبَ). 1.""تَثْرِيبُ الرَّجُلِ"": لَوْمُهُ، تَعْيِيرُهُ. ""لاَ تَثْريبَ عَلَيْكَ"". 2.""وَجَدَهُ فِي تَثْرِيبٍ"" : فِي تَخْلِيطٍ وَإِفْسَادٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19921, 'ثَرْثَرَةٌ', 'ثرثرة', 'مصدر', 'ثرثر', 'ثرثرة', 'ثرثرة', 'مص. ثَرْثَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ثَرْثَرَةٌ-ثَرْثَرَةٌ [ث ر ث ر] (مص. ثَرْثَرَ). ""كُلُّ كَلاَمِهِ ثَرْثَرَةٌ"": كَثْرَةُ الكَلاَمِ فِي مُبالَغَةٍ مِنْ دُونِ جَدْوَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19922, 'ثَرىً', 'ثرى', 'مصدر', 'ثري', 'ثرى', 'ثر', 'مص. ثَرِيَ', '', '', 'مفرد', 'Dy', '', '', '"أثْرَاءٌ"', '', 'Rw', '', '', '', '', '', '', '"(مص. ثَرِيَ). 1.""ثَرَى النَّبَاتِ"" : النَّدَى. 2.""رَجُلٌ مِنْ أهْلِ الثَّرَى"" : مِنْ أهْلِ الخَيْرِ. 3.""وَارَى جُثْمَانَهُ الثَّرَى"" : التُّرَابَ. 4.""طَيَّبَ اللَّهُ ثَرَاهُ"" : لِيَجْعَلْ تُرَابَهُ نَدِيّاً رَاقِداً فِي رَاحَةٍ وَسَلامٍ. 5.""يَبِسَ بَيْنَهُمُ الثَّرَى"": اِنْقَطَعَتْ بَيْنَهُمَا أوَاصِرُ الصَّدَاقَةِ. 6.""أيْنَ الثَّرَى مِنَ الثُّرَيَّا"" (مثل) : يُضْرَبُ لِلتَّمْييزِ بَيْنَ شَيْئَيْنِ بَيْنَهُمَا فَرْقٌ كَبِيرٌ قِيمَةً وَقَدْراً.طه آية 6 لَهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأرْضِ وَمَا بَيْنَهُمَا وَمَا تَحْتَ الثَّرَى . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19923, 'أثْرَاءٌ', 'أثراء', 'مصدر', '', 'ءثراء', 'ثر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19924, 'ثَقْبٌ', 'ثقب', 'مصدر', 'ثقب', 'ثقب', 'ثقب', 'مص. ثَقَبَ', '', '', 'مفرد', 'DnN', '', '', '"أثْقَابٌ:ثُقُوبٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ثَقَبَ). 1.""ثَقْبٌ فِي الجِدْارِ"" : الخَرْقُ النَّافِذُ فِيهِ. 2.""ثَقْبُ الإبْرَةِ"" : عَيْنُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19925, 'أثْقَابٌ', 'أثقاب', 'مصدر', '', 'ءثقاب', 'ثقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19926, 'ثُقُوبٌ', 'ثقوب', 'مصدر', '', 'ثقوب', 'ثقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19927, 'ثَقَافَةٌ', 'ثقافة', 'مصدر', 'ثقف', 'ثقافة', 'ثقفة', 'مص. ثَقُفَ، ثَقَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. ثَقُفَ، ثَقَفَ). 1.""حَصَلَ عَلَى ثَقَافَةٍ عَالِيَةٍ"" : الإحَاطَةُ بِالعُلُومِ وَالْمَعَارِفِ وَالآدَابِ وَالفُنُونِ. 2.""الثَّقَافَةُ العَامَّةُ"" : مُجْمَلُ العُلُومِ وَالفُنُونِ وَالآدَابِ فِي إطَارِهَا العَامِّ. 3.""الثَّقَافَةُ الوَطَنِيَّةُ"" : مَا يُمَيِّزُهَا عَنْ غَيْرِهَا مِنَ مَعَارِفَ وَعُلُومٍ وَفُنُونٍ وَعَادَاتٍ وَتَقَالِيدَ، أيْ كُلُّ مَا هُوَ مُرْتَبِطٌ بِحَضَارَتِهَا. ""الثَّقَافَةُ العَرَبِيَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19928, 'تَثْلِيثٌ', 'تثليث', 'مصدر', 'ثلث', 'تثليث', 'تثلث', 'مص. ثَلَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَثْلِيثٌ-تَثْلِيثٌ [ث ل ث] (مص. ثَلَّثَ). 1.""تَثْلِيثُ الشَّيْءِ"" : تَصْيِيرُهُ ذَا ثَلاَثَةِ أَجْزَاءٍ. 2.""سِرُّ التَّثْلِيثِ عِنْدَ الْمَسِيحِيِّينَ"" : سِرُّ وُجُودِ الأَقَانِيمِ الثَّلاَثَةِ (الأَبُ وَالاِبْنُ وَالرُّوحُ الْقُدُسُ) فِي الذَّاتِ الإِلَهِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19929, 'ثَلْجٌ', 'ثلج', 'مصدر', 'ثلج', 'ثلج', 'ثلج', 'مص. ثَلَجَ', '', '', 'مفرد', 'DnN', '', '', '"ثُلوجٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ثَلَجَ). 1.""غَمَرَ الثَّلْجُ قِمَمَ الجِبالِ"" : ما جَمَدَ مِنْ ماءٍ في السَّماءِ فَيَسْقُطُ، أَوْ ما يَتَجَمَّدُ مِنْ ماءٍ لِشدَّةِ البَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19930, 'ثُلوجٌ', 'ثلوج', 'مصدر', '', 'ثلوج', 'ثلج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19931, 'ثَلْمٌ', 'ثلم', 'مصدر', 'ثلم', 'ثلم', 'ثلم', 'مص. ثَلَمَ', '', '', 'مفرد', 'DnN', '', '', '"أَثْلامٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ثَلَمَ). 1.""أَحْدَثَ ثَلْماً في الحائِطِ"" : شَقّاً، شَرْخا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19932, 'أَثْلامٌ', 'أثلام', 'مصدر', '', 'ءثلام', 'ثلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19933, 'تَثْنِيَةٌ', 'تثنية', 'مصدر', 'ثني', 'تثنية', 'تثنة', 'مص. ثَنَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَثْنِيَةٌ-تَثْنِيَةٌ [ث ن ي] (مص. ثَنَّى). 1.""اِهْتَمَّتْ بِتَثْنِيَةِ ثَوْبِهَا"": بِطَيِّهِ. 2.""خَرَجَ الوَلَدَانِ"" : تَثْنِيَةُ الاِسْمِ، أَيْ إِلْحَاقُ عَلاَمَةِ الْم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19934, 'مَجِيءٌ', 'مجيء', 'مصدر', 'جيأ', 'مجيء', 'مج', 'مص. جَاءَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"مَجِيءٌ-مَجِيءٌ [ج ي أ] (مص. جَاءَ). ""يَنْتَظِرُ مَجِيئَهُ"" : وُصُولَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19935, 'مُجَابَهَةٌ', 'مجابهة', 'مصدر', 'جبه', 'مجابهة', 'مجبهة', 'مص. جَابَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَابَهَةٌ-مُجَابَهَةٌ [ج ب هـ] (مص. جَابَهَ). ""لَمْ يَكُنْ بُدٌّ مِن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19936, 'جاَئِحَةٌ', 'جائحة', 'مصدر', 'جوح', 'جاءحة', 'جحة', 'مص. جَاحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":جَوَائِحُ"', '', 'R', '', '', '', '', '', '', '"(مص. جَاحَ). 1.""أَصَابَتْهُ جَائِحَةٌ"" : بَلِيَّةٌ، تَهْلُكَةٌ، دَاهِيَةٌ. 2.""لَمْ نَعْرِفْ سَنَةً جَائِحَةً مِثْلَ هَذِهِ السَّنَةِ"" : أَيْ قَاحِلَةً، سَنَةَ جَفَافٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19937, 'جَوَائِحُ', 'جوائح', 'مصدر', '', 'جواءح', 'جح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19938, 'جَوْدَةٌ', 'جودة', 'مصدر', 'جود', 'جودة', 'جدة', 'مص. جَادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَوْدَةٌ-جَوْدَةٌ [ج و د] (مص. جَادَ). ""عُرِفَ بِجَوْدَةِ صِنَاعَتِهِ"": بِإِتْقَانِهَا وَطَبِيعَتِهَا الجَيِّدَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19939, 'مُجَادَلَةٌ', 'مجادلة', 'مصدر', 'جدل', 'مجادلة', 'مجدلة', 'مص. جَادَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. جَادَلَ). 1.""دَخَلَ فِي مُجَادَلَةٍ عَنِيفَةٍ"" : الأَخْذُ وَالرَّدُّ حَوْلَ مَوْضُوعٍ مَّا، الْمُحَادَثَةُ الَّتِي تَهْدِفُ إِلَى "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19940, 'جَوْرٌ', 'جور', 'مصدر', 'جور', 'جور', 'جر', 'مص. جَارَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَوْرٌ-جَوْرٌ [ج و ر] (مص. جَارَ). ""فِي حُكْمِهِ جَوْرٌ"" : ظُلْمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19941, 'جِوَارٌ', 'جوار', 'مصدر', 'جور', 'جوار', 'جر', 'مص. جَارَ، جَاوَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جِوَارٌ-جِوَارٌ [ج و ر] (مص. جَارَ، جَاوَرَ). 1.""جَلَسَ بِجِوَارِهِ"" : بِقُرْبِهِ. ""جَلَسَ جِوَارَهُ"" ""جَلَسَ إِلَى جِوَارِهِ"". 2.""سَكَنَ جِوَارَ الْمَسْجِدِ"" : مُجَاوِراً لَهُ. ""أَقَامَ فِي جِوَارِهِ"". 3.""أَسْأَلُكَ حُسْنَ الجِوَارِ"" : أَيْ أَنْ تَكُونَ حَسَنَ السُّلُوكِ مَعَ جِيَرانِكَ، أَيْ مَنْ يَسْكُنُ قُرْبَ مَنْزِلِكَ. 4.""هُوَ فِي جِوَارِي"" : فِي عَهْدِي. 5.""اِنْتَقَلَ إِلَى جِوَارِ رَبِّهِ"" : تُوُفِّيَ، أَيِ التَحَقَ بِالرَّفِيقِ الأَعْلَى، قَرِيباً مِنْهَ. 6.""اِتَّفَقَتِ الدَّوْلَتَانِ عَلَى مُعَاهَدَةِ حُسْنِ الجِوَارِ"" : مُعَاهَدَةُ الصَّدَاقَةِ وَعَدَمِ التَّدَخُّلِ فِي شُؤُونِ الغَيْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19942, 'مُجَارَاةٌ', 'مجاراة', 'مصدر', 'جري', 'مجاراة', 'مجرة', 'مص. جَارَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَارَاةٌ-مُجَارَاةٌ [ج ر ي] (مص. جَارَى). ""مُجَارَاةُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19943, 'مَجَازٌ', 'مجاز', 'مصدر', 'جوز', 'مجاز', 'مجز', 'مص. جَازَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. جَازَ). 1.""سَارَ فِي مَجَازِهِ"" : فِي طَرِيقِهِ، فِي مَسْلَكِهِ، فِي مَمَرِّهِ. 2.""الْمَجَازُ فِي البَلاَغَةِ"" : الكَلِمَةُ الْمُسْتَعْمَلَةُ فِي غَيْرِ مَا وُضِعَتْ لَهُ أَصْلاً، أَيِ اسْتِخْدَامُهَا فِي مَعْنـىً ثَانٍ يُلاَبِسُهُ، وَهُوَ أَنْوَاعٌ: ""الْمَجَازُ الْمُرْسَلُ""، الْمَجَازُ بِالاسْتِعَارَةِ""، ""الْمَجَازُ بِالْحَذْفِ""، ""الْمَجَازُ العَقْلِيُّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19944, 'جَوَازٌ', 'جواز', 'مصدر', 'جوز', 'جواز', 'جز', 'مص. جَازَ.', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَجْوِزَةٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَجْوِزَةٌ، جَوَازَاتٌ. (مص. جَازَ). 1.""جَدَّدَ جَوَازَ سَفَرِهِ"" : وَثِيقَةُ تَعْرِيفٍ تُسَلِّمُهَا الإِدارَةُ الْمَسْؤُولَةُ لِمُواطنِيهَا تَسْمَحُ لَهُمْ بِمُغَادَرَةِ البِلاَدِ وَدُخُولِ بُلْدَانٍ أَجْنَبِيَّةٍ. 2.""جَوَازُ مُرُورٍ"" : إِذْنٌ بِالْمُرُورِ مِنْ مِنْطَقَةٍ إِلَى مِنْطَقَةٍ أَوْ مِنَ بَلَدٍ إِلَى بَلَدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19945, 'أَجْوِزَةٌ', 'أجوزة', 'مصدر', '', 'ءجوزة', 'جزة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19946, 'مُجَازَفَةٌ', 'مجازفة', 'مصدر', 'جزف', 'مجازفة', 'مجزفة', 'مص. جَازَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَازَفَةٌ-مُجَازَفَةٌ [ج ز ف] (مص. جَازَفَ). ""مُجَازَفَةٌ فِي غَيْرِ مَحَلِّهَا"" : مُخَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19947, 'مُجَازَاةٌ', 'مجازاة', 'مصدر', 'جزي', 'مجازاة', 'مجزة', 'مص. جَازَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَازَاةٌ-مُجَازَاةٌ [ج ز ي] (مص. جَازَى). 1.""مُجَازَاةُ الْخَيْرِ"": مُكَافَأَةٌ... 2.""مُجَازَاةُ الشَّرِّ بِالشَّرِّ"" : مُعَاقَبَتُهُ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19948, 'جَأْشٌ', 'جأش', 'مصدر', 'جأش', 'جءش', 'جش', 'مص. جَأْشٌ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَأْشٌ-جَأْشٌ [ج أ ش] (مص. جَأْشٌ). 1.""تَحَرَّكَ جَأْشُهُ"" : القَلْبُ، النَّفْسُ. 2.""عَلَى الرَّغْمِ مِنَ الكَوَار"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19949, 'جَيَشَانٌ', 'جيشان', 'مصدر', 'جيش', 'جيشان', 'جشن', 'مص. جَاشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَيَشَانٌ-جَيَشَانٌ [ج ي ش] (مص. جَاشَ). "" هُوَ فِي عِزِّ جَيَشَانِهِ"" : فِي عِزِّ قُوَّتِهِ وَشَبَابِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19950, 'مجَاعَةٌ', 'مجاعة', 'مصدر', 'جوع', 'مجاعة', 'مجعة', 'مص. جَاعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَجائِعُ"', '', 'R', '', '', '', '', '', '', '"(مص. جَاعَ). ""عَامُ الْمَجَاعَةِ"" : عَامُ الجَدْبِ وَالقَحْطِ وَالجُوعِ. ""مَا زَالَتْ شُعُوبٌ فِي عَالَمِنَا الْمُعَاصِرِ تُعَانِي مِنَ الْمَجَاعَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19951, 'مَجائِعُ', 'مجائع', 'مصدر', '', 'مجاءع', 'مجع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19952, 'جَوْفٌ', 'جوف', 'مصدر', 'جوف', 'جوف', 'جف', 'مص. جَافَ', '', '', 'مفرد', 'DnN', '', '', '"أَجْوَافٌ"', '', 'R', '', '', '', '', '', '', '"(مص. جَافَ). 1.""أَفْرَغَ مَا فِي جَوْفِهِ"" : مَا فِي بَطْنِهِ. ""الجَمَلُ مِنْ جَوْفِهِ يَجْتَرُّ"".(مثل). 2.""تَوَغَّلَ فِي جَوْفِ الكَهْفِ"" : فِي دَاخِلِهِ، فِي غَوْرِهِ. 3.""فِي جَوْفِ اللَّيْلِ شَعَرَ بِبَرْدٍ قَارِسٍ"" : فِي وَسَطِهِ. 4.""اِنْتَشَرَ الرُّعَاةُ فِي جَوْفِ السَّهْلِ"" : السَّهْلُ الْمُتَّسِعُ مِنَ الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19953, 'أَجْوَافٌ', 'أجواف', 'مصدر', '', 'ءجواف', 'جف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19954, 'مُجَافَاةٌ', 'مجافاة', 'مصدر', 'جفو', 'مجافاة', 'مجفة', 'مص. جَافَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَافَاةٌ-مُجَافَاةٌ [ج ف و] (مص. جَافَى). ""أَظْهَرَ فِي تَعَامُلِهِ مُجَافَاةً"" : تَعَامُلٌ فِيهِ جَفَاءٌ وَعَدَاءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19955, 'جَوَلاَنٌ', 'جولان', 'مصدر', 'جول', 'جولان', 'جلن', 'مص. جَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"جَوَلاَنٌ-جَوَلاَنٌ [ج و ل] (مص. جَالَ). ""لَمْ يَتْعَبْ مِنَ الجَوَلاَنِ"" : مِنَ الطَّوَافِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19956, 'جَوْلٌ', 'جول', 'مصدر', 'جول', 'جول', 'جل', 'مص. جَالَ', '', '', 'مفرد', 'DnN', '', '', '"جُولٌ:أَجْوَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. جَالَ). 1.""جَوْلُ الرِّيحِ"" : مَا تَجُولُ بِهِ الرِّيحُ عَلَى وَجْهِ الأَرْضِ مِنْ تُرَابٍ وَغَيْرِهِ. 2.""جَوْلٌ مِنَ الْمَاشِيَةِ"" : القَطِيعُ ذُو العَدَدِ مِنَ الماَشِيَةِ وَنَحْوِهَا. 3.""جَوْلٌ مِنَ الجُنُودِ"" : الكَتِيبَةُ الضَّخْمَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19957, 'جُولٌ', 'جول', 'مصدر', '', 'جول', 'جل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19958, 'أَجْوَالٌ', 'أجوال', 'مصدر', '', 'ءجوال', 'جل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19959, 'مُجَالَسَةٌ', 'مجالسة', 'مصدر', 'جلس', 'مجالسة', 'مجلسة', 'مص. جَالَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَالَسَةٌ-مُجَالَسَةٌ [ج ل س] (مص. جَالَسَ). ""مُجَالَسَةُ الأَصْحَابِ"" : الجُلُوسُ مَعَهُمْ وَالتَّحَدُّثُ إِلَيْهِمْ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19960, 'مُجَامَعَةٌ', 'مجامعة', 'مصدر', 'جمع', 'مجامعة', 'مجمعة', 'مص. جَامَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَامَعَةٌ-مُجَامَعَةٌ [ج م ع] (مص. جَامَعَ). 1.""قَرَّرُوا الْمُجَامَعَةَ لِحَلِّ مَشَاكِلِهِمْ"" : أَي الاجْتِمَاع وَالْمُوَافَقَة عَلَى حَلِّهَا. 2.""مُجامَعَةُ الزَّوْجِ لِزَوْجَتِهِ"" : مُضاجَعَتُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19961, 'جِمَاعٌ', 'جماع', 'مصدر', 'جمع', 'جماع', 'جمع', 'مص. جامَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جِمَاعٌ-جِمَاعٌ [ج م ع] (مص. جامَعَ). 1.""جِمَاعُ الشَّيْءِ"" : مُجْتَمَعُ أَصْلِهِ. 2.""جِمَاعُ الشَّيْءِ"" : مَا جَمَعَ عَدَداً. ""الخَمْرُ جِمَاعُ الإِثْمِ"". 3.""هَذَا البَابُ جِمَاعُ هَذِهِ الأَبْوَابِ"" : الجَامِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19962, 'مُجَامَلَةٌ', 'مجاملة', 'مصدر', 'جمل', 'مجاملة', 'مجملة', 'مص. جَامَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. جَامَلَ). 1.""سَايَرَهُ فِي كَلاَمِهِ مُجَامَلَةً"" : تَأَدُّباً لَهُ لاَ عَنِ اقْتِنَاعٍ أَوْ تَسْلِيمٍ. ""يَكْرَهُ الْمُجَامَلاَتِ"" ""قَالَ لَهَا عَلَى سَبِيلِ الْمُجَامَلَةِ : هَذَا شَرَفٌ عَظِيمٌ لَنَا"" ""لَمْ يَكُنْ يَعْرِفُ رِيَاءً وَلاَ مُجَامَلَةً"". 2.""قَامَ بِزِيَارَةِ مُجَامَلَةٍ"" : بِزِيَارَةِ أَدَبٍ وَتَحِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19963, 'مُجَانَبَةٌ', 'مجانبة', 'مصدر', 'مجن', 'مجانبة', 'مجنبة', 'مص. جَانَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَانَبَةٌ-مُجَانَبَةٌ [م ج ن] (مص. جَانَبَ). ""مُجَانَبَةُ الصَّوَابِ"": البُعْدُ عَنِ الصَّوَابِ. ""مُجَانَبَةُ الْحَقِيقَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19964, 'مُجَانَسَةٌ', 'مجانسة', 'مصدر', 'جنس', 'مجانسة', 'مجنسة', 'مص. جَانَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَانَسَةٌ-مُجَانَسَةٌ [ج ن س] (مص. جَانَسَ). ""مُجَانَسَةُ الصَّنَائِعِ"" : مُمَاثَلَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19965, 'جِهَادٌ', 'جهاد', 'مصدر', 'جهد', 'جهاد', 'جهد', 'مص. جَاهَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جِهَادٌ-جِهَادٌ [ج هـ د] (مص. جَاهَدَ). 1. ""خَرَجَ الجُنُودُ لِلْجِهَادِ"": لِلْقِتَالِ فيِ سَبِيلِ اللَّهِ. 2.""جِهَادُنَا الأَكْبَرُ هُوَ البِنَاءُ وَالقَضَاءُ عَلَى الجَهْلِ وَالتَّخَلُّفِ"" : كَدُّنَا، نِضَالُنَا، مَعْرَكَتُنُا. ""خَرَجْنَا مِنَ الجِهَادِ الأَصْغَرِ إِلَى الجِهَادِ الأَكْبَرِ"" ""وَلاَ يَحْصُلُونَ لِقَاءَ أَتْعَابِهِمْ وَجِهَادِهِمْ إِلاَّ عَلَى جُزْءٍ مِنَ الغَلَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19966, 'مُجَاهَدَةٌ', 'مجاهدة', 'مصدر', 'جهد', 'مجاهدة', 'مجهدة', 'مص. جَاهَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَاهَدَةٌ-مُجَاهَدَةٌ [ج هـ د] (مص. جَاهَدَ). ""مُجَاهَدَةُ النَّفْسِ"" : التَّغَلُّبُ عَلَى شَهَوَاتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19967, 'مُجَاهَرَةٌ', 'مجاهرة', 'مصدر', 'جهر', 'مجاهرة', 'مجهرة', 'مص. جَاهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَاهَرَةٌ-مُجَاهَرَةٌ [ج هـ ر] (مص. جَاهَرَ). 1.""لَمْ تَكُنْ مُجَاهَرَتُهُ بِالعَدَاوَةِ إَلاَّ تَعْبِيراً عَنْ حِقْدٍ دَفِينٍ"" : الْمُبَادَأَةُ. 2.""الْمُجَاهَرَةُ بِالْحَقِيقَةِ"" : الإِعْلاَنُ عَنْهَا جَهْراً. ""الْمُجَاهَرَةُ بِحَقَائِقِ الأُمُورِ فَضِيلَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19968, 'جِهَارٌ', 'جهار', 'مصدر', 'جهر', 'جهار', 'جهر', 'مص. جَاهَرَ، جَهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جِهَارٌ-جِهَارٌ [ج هـ ر] (مص. جَاهَرَ، جَهَرَ). 1.""يَشْتَغِلُ جِهَاراً"" : عَلَناً. 2.""لَقِيتُهُ جِهَاراً"" : عِيَاناً.نوح آية 8 ثُمَّ إِنِّي دَعَوْتُهُمْ جِهَارًا. (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19969, 'مُجَاوَبَةٌ', 'مجاوبة', 'مصدر', 'جوب', 'مجاوبة', 'مجبة', 'مص. جَاوَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَاوَبَةٌ-مُجَاوَبَةٌ [ج و ب] (مص. جَاوَبَ). ""كَانَتْ مُجَاوَبَتُهُ فِي مَحَلِّهَا"" : إِجَابَتُهُ عَنْ سُؤَالٍ أَوْ نِدَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19970, 'مُجَاوَرَةٌ', 'مجاورة', 'مصدر', 'جور', 'مجاورة', 'مجرة', 'مص. جَاوَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَاوَرَةٌ-مُجَاوَرَةٌ [ج و ر] (مص. جَاوَرَ). ""ذَهَبَ لِمُجَاوَرَةِ مَكَّةَ"" : لِلاعْتِكَافِ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19971, 'مُجَاوَزَةٌ', 'مجاوزة', 'مصدر', 'جوز', 'مجاوزة', 'مجزة', 'مص. جَاوَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُجَاوَزَةٌ-مُجَاوَزَةٌ [ج و ز] (مص. جَاوَزَ). 1.""مُجَاوَزَةُ الأَدَبِ وَالسُّلُوكِ"" : تَجَاوُزُهُ، تَعَدِّيهِ. ""مُجَاوَزَةُ الوَقْتِ القَانُونِيِّ"". 2.""الْمُجَاوَزَةُ عَنِ الذَّنْبِ"" : عَدَمُ الْمُؤاخَذَةِ بِالذَّنْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19972, 'جَبْرٌ', 'جبر', 'مصدر', 'جبر', 'جبر', 'جبر', 'مص. جَبَرَ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"جَبْرٌ-جَبْرٌ [ج ب ر] ( مص. جَبَرَ). 1. ""مُخْتَصٌّ بِجَبْرِ العِظَامِ"" : إِصْلاَحِهَا، إِعَادَتِهَا إِلَى وَضْعِهَا السَّلِيمِ. 2. ""مُتَمَيِّز"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19973, 'جِبَايَةٌ', 'جباية', 'مصدر', 'جبي', 'جباية', 'جبة', 'مص. جَبَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. جَبَى). ""جِبَايَةُ الضَّرَائِبِ"" : تَحْصِيلُهَا، جَمْعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19974, 'جَثٌّ', 'جث', 'مصدر', 'جثث', 'جث', 'جث', 'مص. جَثَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَثٌّ-جَثٌّ [ج ث ث] (مص. جَثَّ). 1.""جَثُّ العَسَلِ"" : مَا خَالَطَ العَسَلَ مِنْ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19975, 'جِدٌّ', 'جد', 'مصدر', 'جدد', 'جد', 'جد', 'مص. جَدَّ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"جِدٌّ-جِدٌّ [ج د د] (مص. جَدَّ). 1.""لَا يُفَرِّقُ بَيْنَ الجِدِّ وَالهَزْلِ"" : الرَّصَانَةٌ، الرَّزَانَةٌ. 2. ""اِشْتَغَلَ بِجِدٍّ وَاهْتِمِامٍ"" : بِكِدٍّ، بِاجْتِهَادٍ. 3. ""رَجُلٌ عَظِيمٌ جِدّاً"": في مُنْتَهَى العَظَمَةِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19976, 'تَجْدِيدٌ', 'تجديد', 'مصدر', 'جدد', 'تجديد', 'تجدد', 'مص. جَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْدِيدٌ-تَجْدِيدٌ [ج د د] (مص. جَدَّدَ). 1.""تَجْدِيدُ رُوحٍ الشَّبَابِ"" : تَوَقُّدُهَا وَإِعَادَةُ النَّشَاطِ وَالحَيَوِيَّةِ إِلَيْهَا. 2."""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19977, 'جَذٌّ', 'جذ', 'مصدر', 'جذذ', 'جذ', 'جذ', 'مص. جَذَّ', '', '', 'مفرد', 'DnN', '', '', '"أَجْذَاذٌ"', '', 'R', '', '', '', '', '', '', '"(مص. جَذَّ). ""جَذُّ الصَّخْرِ"": كَسْرُهُ، أَيْ كَسْرُ مَا هُوَ صَلْبٌ. فَثُرْتُ إِلَى الصَّنَمِ فَكَسَرْتُهُ أَجْذَاذاً(حديث مازن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19978, 'أَجْذَاذٌ', 'أجذاذ', 'مصدر', '', 'ءجذاذ', 'جذذ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19979, 'جَذْبٌ', 'جذب', 'مصدر', 'جذب', 'جذب', 'جذب', 'مص. جَذَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَذْبٌ-جَذْبٌ [ج ذ ب] (مص. جَذَبَ). 1.""جَذْبُ الْمُتَصَوِّفِ"" : وَجْدُهُ. والجَذْبُ مُصْطَلَحٌ عِنْدَ الْمُتَصَوِّفَةِ وَهُوَ حَالٌ مِنْ أَحْوَالِ النَّفْسِ، يَغِيبُ فِيهَا العَقْلُ عَنْ عِلْمِ مَا يَجْرِي "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19980, 'تَجْذِيرٌ', 'تجذير', 'مصدر', 'جذر', 'تجذير', 'تجذر', 'مص. جَذَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْذِيرٌ-تَجْذِيرٌ [ج ذ ر] (مص. جَذَّرَ). 1.""تَجْذِيرُ جِذْرٍ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19981, 'تَجْذِيرٌ', 'تجذير', 'مصدر', 'جذر', 'تجذير', 'تجذر', 'مص. جَذَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْذِيرٌ-تَجْذِيرٌ [ج ذ ر] (مص. جَذَّرَ). 1.""تَجْذِيرُ مَوَاقِفِهِ"" : تَعْمِيقُهَا، تَثْبِيتُهَا. 2.""التَّجْذِيرُ فِي الحِسَابِ"" : اِسْتِئْصَالُ جِذْرِ العَدَدِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19982, 'تَجْذِيفٌ', 'تجذيف', 'مصدر', 'جذف', 'تجذيف', 'تجذف', 'مص. جَذَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْذِيفٌ-تَجْذِيفٌ [ج ذ ف] (مص. جَذَّفَ). ""تَجْذِيفُ سَفِينَةٍ"": تَسْيِيرُهَا بِالْمِجْذَافِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19983, 'تَجْذِيفٌ', 'تجذيف', 'مصدر', 'جذف', 'تجذيف', 'تجذف', 'مص. جَذَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْذِيفٌ-تَجْذِيفٌ [ج ذ ف] (مص. جَذَّفَ). ""رِيَاضَةُ التَّجْذِيفِ"" : رِيَاضَةُ رُكُوبِ القَوَارِبِ، تَعْتَمِدُ عَلَى اعْتِلاَءِ ظَهْرِ زَوَارِقَ مَائِيَّةٍ مُسَطَّحَةٍ لِلسَّيْرِ عَلَى سَطْحِ الْمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19984, 'جَذَلٌ', 'جذل', 'مصدر', 'جذل', 'جذل', 'جذل', 'مص. جَذَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَذَلٌ-جَذَلٌ [ج ذ ل] (مص. جَذَلَ). ""كَانَ جَذَلُهُ عَنْ حُبٍّ وَصِدْقٍ"": فَرَحُهُ، بَهْجَتُهُ، اِبْتِهَاجُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19985, 'جَرٌّ', 'جر', 'مصدر', 'جرر', 'جر', 'جر', 'مص. جَرَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَرٌّ-جَرٌّ [ج ر ر] (مص. جَرَّ). 1."" لَمْ يَكُنْ بِإِمْكَانِهِ جَرُّ أَيِّ مَغْنَمٍ"" : أَي اغْتِنَامُ، كَسْبُ. 2. حُرُوفُ ال"', '');
