INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19987, 'تَجَارِبُ', 'تجارب', 'مصدر', '', 'تجارب', 'تجرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19988, 'تَجْرِيبٌ', 'تجريب', 'مصدر', 'جرب', 'تجريب', 'تجرب', 'مص. جَرَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَجْرِيبٌ-تَجْرِيبٌ [ج ر ب] (مص. جَرَّبَ). ""وَضَعَهُ تَحْتَ التَّجْرِيبِ"" : تَحْتَ الاخْتِبَارِ وَالامْتِحَانِ."', '');
