INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19990, 'جَرْدٌ', 'جرد', 'مصدر', 'جرد', 'جرد', 'جرد', 'مص. جَرَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَرْدٌ-جَرْدٌ [ج ر د] (مص. جَرَدَ). 1. ""جَرْدُ البَضَائِعِ وَمُخْتَلِفِ الْمَوَادِّ"" : إِحْصَاءُ مَا تَبَقَّى مِنْهَا بِتَفْصِيلٍ. 2.""جَرْدُ أَفْعَالِ الكِتَابِ"" : اِسْتِخْرَاجُهَا وَجَعْلُهَا فِي قَائِمَةٍ."', '');
