INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19992, 'تَجْرِيذٌ', 'تجريذ', 'مصدر', 'جرذ', 'تجريذ', 'تجرذ', 'مص. جَرَّذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْرِيذٌ-تَجْرِيذٌ [ج ر ذ] (مص. جَرَّذَ). ""تَجْرِيذُ الشَّجَرَةِ"" : شَذْبُهَا وَإِزَالَةُ عُقَدِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19993, 'تَجْرِيرٌ', 'تجرير', 'مصدر', 'جرر', 'تجرير', 'تجرر', 'مص. جَرَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْرِيرٌ-تَجْرِيرٌ [ج ر ر] (مص. جَرَّرَ). ""تَجْرِيرُ الشَّيْءِ"" : جَرُّهُ، سَحْبُهُ، جَذْبُهُ."', '');
