INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19995, 'جَرْسٌ', 'جرس', 'مصدر', 'جرس', 'جرس', 'جرس', 'مص. جَرَسَ', '', '', 'مفرد', 'DnN', '', '', '"جُرُوسٌ"', '', 'R', '', '', '', '', '', '', '"(مص. جَرَسَ). 1.""يَنْبَعِثُ مِنْ سَاعَةِ الحَائِطِ جَرْسٌ رَتِيبٌ"" : صَوْتٌ بِهِ نَقْرَةٌ، صَوْتٌ خَفِيٌّ. 2."', '');
