INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19998, 'جَرْشٌ', 'جرش', 'مصدر', 'جرش', 'جرش', 'جرش', 'مص. جَرَشَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَرْشٌ-جَرْشٌ [ج ر ش] (مص. جَرَشَ). ""جَرْشُ القَمْحِ"" : تَفْتِيتُهُ، تَكْسِيرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(19999, 'تَجْرِيفٌ', 'تجريف', 'مصدر', 'جرف', 'تجريف', 'تجرف', 'مص. جَرَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْرِيفٌ-تَجْرِيفٌ [ج ر ف] (مص. جَرَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20000, 'جَرِيمَةٌ', 'جريمة', 'مصدر', 'جرم', 'جريمة', 'جرمة', 'مص. جَرَمَ', '', '', 'مفرد', 'DnN', '', '', '"جَرَائِمُ"', '', 'R', '', '', '', '', '', '', '"(مص. جَرَمَ). ""اِتَّهَمَهُ بِجَرِيمَةٍ لمَ يَرْتَكِبْهَا"" : بِجِنَايَةٍ، بِجُرْمٍ. ""مَلْعونَةٌ هِيَ الأَيْدِ"', '');
