INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20004, 'تَجْزِئَةٌ', 'تجزئة', 'مصدر', 'جزأ', 'تجزءة', 'تجزة', 'مص. جَزَّأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَجْزِئَةٌ-تَجْزِئَةٌ [ج ز أ] (مص. جَزَّأَ). 1.""تَمَّتْ تَجْزِئَةُ أَرْضٍ فِي مِلْكِ الدَّوْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20005, 'تَجْزِيءٌ', 'تجزيء', 'مصدر', 'جزأ', 'تجزيء', 'تجز', 'مص. جَزَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَجْزِيءٌ-تَجْزِيءٌ [ج ز أ] (مص. جَزَّأَ). 1.""تَجْزِيءُ الشَّيْءِ"" : تَقْسِيمُهُ أَجْزَاءً. 2.""تَجْزِيءُ بَيْتٍ مِنَ الشِّعْرِ"" : حَذْفُ الْجُزْءِ الأَخِيرِ مِنْ كُلِّ شَطْرَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20006, 'جَزْرٌ', 'جزر', 'مصدر', 'جزر', 'جزر', 'جزر', 'مص. جَزَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَزْرٌ-جَزْرٌ [ج ز ر] (مص. جَزَرَ). 1.""عَرَفَ البَحْرُ جَزْراً هَذِهِ الأَيَّامَ"" : تَرَاجُعُ مِيَاهِهِ إِلَى الخَلْفِ، اِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20007, 'تَجْزِيزٌ', 'تجزيز', 'مصدر', 'جزز', 'تجزيز', 'تجزز', 'مص. جَزَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْزِيزٌ-تَجْزِيزٌ [ج ز ز] (مص. جَزَّزَ). ""تَجْزِيزُ الصُّوفِ"" : تَقْطِيعُهُ وَقَصُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20008, 'جَزَعٌ', 'جزع', 'مصدر', 'جزع', 'جزع', 'جزع', 'مص. جَزَعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَزَعٌ-جَزَعٌ [ج ز ع] (مص. جَزَعَ). ""أَظْهَرَ جَزَعاً لاَ حَدَّ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20009, 'جَزْفٌ', 'جزف', 'مصدر', 'جزف', 'جزف', 'جزف', 'مص. جَزَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَزْفٌ-جَزْفٌ [ج ز ف] (مص. جَزَفَ).""أَخَذَ القَمْحَ أَوْ غ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20010, 'جَزَالَةٌ', 'جزالة', 'مصدر', 'جزل', 'جزالة', 'جزلة', 'مص. جَزَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَزَالَةٌ-جَزَالَةٌ [ج ز ل] (مص. جَزَلَ). "" لُغَتُهُ فِيهَا جَزَالَةٌ"" : فَصَاحَةٌ، بَلاَغَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20011, 'جَزَاءٌ', 'جزاء', 'مصدر', 'جزى', 'جزاء', 'جز', 'مص. جَزَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"جَزَاءُ-جَزَاءُ [ج ز ى] (مص. جَزَى). 1.""هَذَا جَزَاءُ مَا فَعَلَتْ يَدَاهُ"" : عِقَابُهُ. 2.""نَالَ جَزَاءَ اجْتِهَادِهِ وَإِخْلاَصِهِ"" : الْمُكَافَأَةُ، الثَّوَابُ. 3.""ضَرْبَةُ جَزَاءٍ"" : عِقَابٌ فِي كُرَةِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20012, 'جَسٌّ', 'جس', 'مصدر', 'جسس', 'جس', 'جس', 'مص. جَسَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَسٌّ-جَسٌّ [ج س س] (مص. جَسَّ). 1.""قَامَ بِجَسِّ نَبْضِهِ"": بِلَمْسِهِ وَتَحَسُّسِهِ، فَحْصِه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20013, 'تَجْسِيدٌ', 'تجسيد', 'مصدر', 'جسد', 'تجسيد', 'تجسد', 'مص. جَسَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَجْسِيدٌ-تَجْسِيدٌ [ج س د] (مص. جَسَّدَ). ""تَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20014, 'جَسَارَةٌ', 'جسارة', 'مصدر', 'جسر', 'جسارة', 'جسرة', 'مص. جَسَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَسَارَةٌ-جَسَارَةٌ [ج س ر] (مص. جَسَرَ). ""أَظْهَرَ جَسَارَةً لاَ مَثِيل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20015, 'تَجْسِيمٌ', 'تجسيم', 'مصدر', 'جسم', 'تجسيم', 'تجسم', 'مص. جَسَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَجْسِيمٌ-تَجْسِيمٌ [ج س م] (مص. جَسَّمَ). ""تَجْسِيمُ الصُّورَةِ"": ت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20016, 'جَشّ', 'جش', 'مصدر', 'جشش', 'جش', 'جش', 'مص. جَشَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَشّ-جَشّ [ج ش ش] (مص. جَشَّ). 1.""مَكَانٌ جَشٌّ"" : خَشِنُ الحِجَارَةِ. 2.""جَشُّ الحِزَامُ"" : وَسَطُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20017, 'جَشَعٌ', 'جشع', 'مصدر', 'جشع', 'جشع', 'جشع', 'مص. جَشِعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَشَعٌ-جَشَعٌ [ج ش ع] (مص. جَشِعَ). 1.""بِهِ جَشَعٌ"" : بِهِ طَمَعٌ شَدِيدٌ. 2.""أَظْهَرَ جَشَعاً أَمَامَ الضُّيُوفِ عَلَى مَائِدَةِ الطَّعَامِ"": نَهَماً وَشَرَاهَةً، أَي الحِرْصُ عَلَى الأَكْلِ بِشَرَاهَةٍ وَنَهَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20018, 'جَشَمٌ', 'جشم', 'مصدر', 'جشم', 'جشم', 'جشم', 'مص. جَشِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَشَمٌ-جَشَمٌ [ج ش م] (مص. جَشِمَ). ""تَحَمَّلَ جَشَماً"" : ثِقْلاً، عَنَاءً، مَشَقَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20019, 'جَعْجَعَةٌ', 'جعجعة', 'مصدر', 'جعجع', 'جعجعة', 'جعجعة', 'مص. جَعْجَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَعْجَعَةٌ-جَعْجَعَةٌ [ج ع ج ع] (مص. جَعْجَعَ). 1.""جَعْجَعَةُ الجِمَالِ"" : أَصْوَاتُهَا مُجْتَمِعَةً. 2.""أَسْمَعُ جَعْجَعَةً وَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20020, 'تَجْعِيدٌ', 'تجعيد', 'مصدر', 'جعد', 'تجعيد', 'تجعد', 'مص. جَعَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْعِيدٌ-تَجْعِيدٌ [ج ع د] (مص. جَعَّدَ). ""تَجْعِيدُ الشَّعْرِ"" : تَشْعِيثُهُ، تَجم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20021, 'جَفَافٌ', 'جفاف', 'مصدر', 'جفف', 'جفاف', 'جفف', 'مص. جَفَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَفَافٌ-جَفَافٌ [ج ف ف] (مص. جَفَّ). 1.""عَاشَتِ البِلاَدُ سَبْعَ سَنَوَاتٍ مِنَ الجَفَافِ"" : سَنَوَاتٍ قَاحِلِةٍ، قَاحِطَةٍ، لَمْ يَنْزِلْ فِيهَا مَطَرٌ. 2.""تَضَرَّرَ السُّكَّانُ وَالْمَاشِيَةُ مِنَ الجَفَافِ"" : مِنْ يُبُوسَةِ الأَرْضِ. 3.""أَجَابَهُ بِجَفَافٍ"" : بِخُشُونَةٍ. ""يَحْطُبُ فِي جَفَافٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20022, 'جَفَاءٌ', 'جفاء', 'مصدر', 'جفو', 'جفاء', 'جف', 'مص. جَفَا', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"جَفَاءٌ-جَفَاءٌ [ج ف و] (مص. جَفَا). ""أَظْهَرَ لَهُ الجَفَاءَ"" : الكَرَاهِيَةَ، النُّفُورَ. ""صَارَ بَيْنَهُمَا جَفَاءٌ مَا بَعْدَهُ جَفَاءٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20023, 'جَفْوٌ', 'جفو', 'مصدر', 'جفو', 'جفو', 'جف', 'مص. جَفَا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَفْوٌ-جَفْوٌ [ج ف و] (مص. جَفَا). ""تَحَوَّلَ الجَفْوُ إِلَى مَحَبَّةٍ وَوِئَامٍ"" : العَدَاءُ، التَّنَافُرُ، الخِصَامُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20024, 'جَفْرٌ', 'جفر', 'مصدر', 'جفر', 'جفر', 'جفر', 'مص. جَفَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَفْرٌ-جَفْرٌ [ج ف ر] (مص. جَفَرَ). 1.: البِئْرُ الوَاسِعَةُ. 2.""وَلَدٌ جَفْرٌ"" : وَلَدٌ اِنْفَتَخَ لَحْمُهُ وَصَارَ لَهُ كَرِشٌ. 3.""صَارَ الجَدْيُ جَفْراً"" : أَيْ عَظُمَ وَتَضَخَّمَ. 4.""عِلْمُ الجَفْرِ"" : عِلْمٌ يَبْحَثُ عَنِ الحُرُوفِ مِنْ حَيْثُ دَلاَلَتُهَا عَلَى مَعْرِفَةِ الحَوَادِثِ عَلَى انْتِهَاءِ العَالَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20025, 'تَجْفِيفٌ', 'تجفيف', 'مصدر', 'جفف', 'تجفيف', 'تجفف', 'مص. جَفَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْفِيفٌ-تَجْفِيفٌ [ج ف ف] (مص. جَفَّفَ). ""أَسْرَعْتُ إِلَى تَجْفِيفِ بَهْوِ الْمَنْزِلِ"" : تَنْشِيفِهِ، إِزَالَةِ الْمَاءِ مِنَ الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20026, 'جَفْلٌ', 'جفل', 'مصدر', 'جفل', 'جفل', 'جفل', 'مص. جَفَلَ', '', '', 'مفرد', 'DnN', '', '', '"جُفُولٌ"', '', 'R', '', '', '', '', '', '', '"(مص. جَفَلَ). 1.: ذَكَرُ النَّعَامِ الَّذِي يَنْفِرُ مِنْ كُلِّ شَيْءٍ يَرَاهُ وَيَهْرَبُ مِنْهُ. 2.: السَّحَابُ صَبَّ مَاءهُ وَمَضَى. 3.: نَوْعٌ مِنَ النَّمْلِ السُّودِ الكِبَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20027, 'جُفُولٌ', 'جفول', 'مصدر', '', 'جفول', 'جفل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20028, 'جَلاَلَةٌ', 'جلالة', 'مصدر', 'جلل', 'جلالة', 'جللة', 'مص. جَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَلاَلَةٌ-جَلاَلَةٌ [ج ل ل] (مص. جَلَّ). 1.""تَرَبَّعَ صَاحِبُ الجَلاَلَةِ عَلَى العَرْشِ"" : لَقَبُ الْمَلِكِ، لِجَلاَلَةِ قَدْرِهِ. ""جَلاَلَةُ الْمَلِكِ"". 2.""صَاحِبَةُ الجَلاَلَةِ"" : الصَّحَافَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20029, 'جَلاَلٌ', 'جلال', 'مصدر', 'جلل', 'جلال', 'جلل', 'مص. جَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَلاَلٌ-جَلاَلٌ [ج ل ل] (مص. جَلَّ). 1.""هُوَ ذُو الجَلاَلِ وَالإِكْرَامِ"" : الله تَعَالَى، الجَلِيلُ. 2.""اِسْمُ ابْنِهِ البِكْرِ جَلاَلٌ"" : اِسْمُ عَلَمٍ وَيَعْنِي الرِّفْعَةَ وَالسُّمُوَّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20030, 'جَلٌّ', 'جل', 'مصدر', 'جلل', 'جل', 'جل', 'مص. جَلَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَلٌّ-جَلٌّ [ج ل ل] (مص. جَلَّ). 1.""رَجُلٌ جَلٌّ"" : جَلِيلٌ. 2.""جَلُّ الدَّابَّةِ"" : مَا تُغَطَّى بِهِ لِتُصَانَ: ج: جِلاَلٌ وَأَجْلاَلُ.ن. جُلٌّ. 2.""جَلُّ السَّفِينَةِ"" : شِرَاعُهَا. ج: جُلُولٌ، أَجْلاَلٌ. 3.""جَلُّ الدِّيكِ"" : زَهْرَةُ عُرْفِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20031, 'جَلاَءٌ', 'جلاء', 'مصدر', 'جلو', 'جلاء', 'جل', 'مص. جَلاَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"جَلاَءٌ-جَلاَءٌ [ج ل و] (مص. جَلاَ). 1.""فِي الأَمْرِ جَلاَءٌ"" : وُضُوحٌ. 2.""اِحْتَفَلَ الشَّعْبُ بِيَوْمِ الجَلاَءِ"" : خُرُوجُ آخِرِ جُنْدِيٍّ مُحْتَلٍّ عَنِ الوَطَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20032, 'جَلْبٌ', 'جلب', 'مصدر', 'جلب', 'جلب', 'جلب', 'مص. جَلَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَلْبٌ-جَلْبٌ [ج ل ب] (مص. جَلَبَ).: الذَّنْبُ، الجِنَايَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20033, 'جِلْبَابٌ', 'جلباب', 'مصدر', 'جلب', 'جلباب', 'جلبب', 'مص. جَلْبَبَ', '', '', 'مفرد', 'DnN', '', '', '"جَلاَبِيبُ"', '', 'R', '', '', '', '', '', '', '"(مص. جَلْبَبَ). ""اِرْتَدَى جِلْبَابَهُ"" : قَمِيصٌ وَاسِعُ طَوِيلٌ، لَهٌ أَكْمَامٌ وَغِطَاءٌ لِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20034, 'جَلاَبِيبُ', 'جلابيب', 'مصدر', '', 'جلابيب', 'جلبب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20035, 'جَلْجَلَةٌ', 'جلجلة', 'مصدر', 'جلجل', 'جلجلة', 'جلجلة', 'مص. جَلْجَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَلْجَلَةٌ-جَلْجَلَةٌ [ج ل ج ل] (مص. جَلْجَلَ). 1.""لَمْ نَكُنْ نَسْمَعُ فِي تِلْكَ اللَّيْلَةِ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20036, 'تَجْلِيدٌ', 'تجليد', 'مصدر', 'جلد', 'تجليد', 'تجلد', 'مص. جَلَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْلِيدٌ-تَجْلِيدٌ [ج ل د] (مص. جَلَّدَ). ""يَرْغَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20037, 'جَلْدٌ', 'جلد', 'مصدر', 'جلد', 'جلد', 'جلد', 'مص. جَلَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَلْدٌ-جَلْدٌ [ج ل د] (مص. جَلَدَ). 1.""أَمَرَ بِجَلْدِهِ أَمَامَ الْمَلإِ"": ضَرْبُهُ ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20038, 'جَلَدٌ', 'جلد', 'مصدر', 'جلد', 'جلد', 'جلد', 'مص. جَلُدَ', '', '', 'مفرد', 'DnN', '', '', '"أَجْلاَدٌ:جِلْدٌ"', '', 'R', '', '', '', '', '', '', '"(مص. جَلُدَ). ""أَظْهَرَ جَلَداً أَمَامَ أَعْدَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20039, 'أَجْلاَدٌ', 'أجلاد', 'مصدر', '', 'ءجلاد', 'جلد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20040, 'جِلْدٌ', 'جلد', 'مصدر', '', 'جلد', 'جلد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20041, 'جُلُوسٌ', 'جلوس', 'مصدر', 'جلس', 'جلوس', 'جلس', 'مص. جَلَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جُلُوسٌ-جُلُوسٌ [ج ل س] (مص. جَلَسَ). 1.""جُلُوسُ جَلاَلَتِهِ عَلَى العَرْشِ هُوَ يَوْمُ احْت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20042, 'تَجْمِيدٌ', 'تجميد', 'مصدر', 'جمد', 'تجميد', 'تجمد', 'مص. جَمَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْمِيدٌ-تَجْمِيدٌ [ج م د] (مص. جَمَّدَ). 1.""تَجْمِيدُ اللَّحْمِ"" : أَيْ وَضْعُ اللَّحْمِ فِي دَرَجَةٍ عَالِيَةٍ جِدّاً مِنَ البُرُودَةِ لِيَتِمَّ تَصْبِيرُهَا وَتَغْلِيفُهَا بِالثَّلْجِ الجَامِدِ لِلْحِفَاظِ عَلَيْهَا مُدَّةً طَوِيلَةً، وَهُنَاكَ ثَلاَّجَةٌ مُجَمِّدَةٌ لِهَذَا الغَرَضِ. 2.""تَجْمِيدُ السَّائِلِ"" : تَصْيِيرُهُ جَامِدًا. 3.""تَجْمِيدُ الأَمْوَالِ"" : عَمَلِيَّةُ و"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20043, 'جَمْدٌ', 'جمد', 'مصدر', 'جمد', 'جمد', 'جمد', 'مص. جَمَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَمْدٌ-جَمْدٌ [ج م د] (مص. جَمَدَ). 1.""سَائِلٌ جَمْدٌ"": جَامِدٌ. 2.""نَزَلَ الجَمْدُ"" : الثَّلْجُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20044, 'جُمُودٌ', 'جمود', 'مصدر', 'جمد', 'جمود', 'جمد', 'مص. جَمَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جُمُودٌ-جُمُودٌ [ج م د] (مص. جَمَدَ). 1.""يَعِيشُ فيِ جُمُودٍ"" : فِي خُمُولٍ. 2."" جُمُودُ البَيْعِ وَالشِّرَاءِ فيِ السُّوقِ"" : كَسَادُهَا. 3.""لاَ أَعْرِفُ سَبَبَ جُمُودِ عَاطِفَتِهِ"" : قَسْوَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20045, 'تَجْمِيعٌ', 'تجميع', 'مصدر', 'جمع', 'تجميع', 'تجمع', 'مص. جَمَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْمِيعٌ-تَجْمِيعٌ [ج م ع] (مص. جَمَعَ). 1.""تَجْمِيعُ الشَّمْلِ"": جَمْعُهُ، لَمُّهُ. 2.""كُلُّ مَا كَانَ يَهُمُّهُ هُوَ تَجْمِيعُ الْمَالِ"" : جَمْعُهُ وَتَكْدِيسُهُ، خَزْنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20046, 'جَمْعٌ', 'جمع', 'مصدر', 'جمع', 'جمع', 'جمع', 'مص. جَمَعَ', '', '', 'مفرد', 'DnN', '', '', '"جُمُوعٌ"', '', 'R', '', '', '', '', '', '', '"(مص. جَمَعَ). 1.""سَعَى إِلَى جَمْعِ شَمْلِ العَائِلَةِ"" : أَيْ لَمِّ الشَّمْلِ. 2.""جَمْعُ الكَلِمَةِ"" : أَيْ تَوْحِيدُ الرّأْيِ. 3.""اِحْتَشَدَتِ الجُمُوعُ فِي السَّاحَةِ العُمُومِيَّةِ"": الجَمَاعَاتُ. 4.""هُوَ مِنْ هُوَاةِ جَمْعِ الطَّوَابِعِ"" : لَمِّهَا. 5.""أَوْلاَدٌ"" : جَمْعُ وَلَدٍ، أَيْ مَا دَلَّ عَلَى أَكْثَرَ مِنِ اثْنَيْنِ. 6.""حَضَرَ الْمُعَلٍّمُونَ""، ""تَوَجَّهَ بِخِطَابٍ إِلَى الْمُعَلِّمِينَ"" : مُعَلِّمُونَ، مُعَلِّمِين جَمْعُ مُذَكَّرٍ سَالِم، بَقِيَتْ صُورَةُ مُفْرَدِهِ عَلَى حَالِهَا وَزِيدَتْ فِي آخِرِهِ وَاوٌ وَنُونٌ لِلْمُذَكَّرِ الْمَرْفُوعِ، وَيَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20047, 'جُمُوعٌ', 'جموع', 'مصدر', '', 'جموع', 'جمع', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20048, 'تَجْمِيلٌ', 'تجميل', 'مصدر', 'جمل', 'تجميل', 'تجمل', 'مص. جَمَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْمِيلٌ-تَجْمِيلٌ [ج م ل] (مص. جَمَّلَ). 1.""خَضَعَ لِعَمَلِيَّةِ تَجْمِيلٍ"" ‎: تَزْيِين فِي مَلاَمِحِ الوَجْهِ، هَذَا مَا يُعْرَفُ بِفَنِّ التَّزْيِينِ. 2.""حَاوَلَ تَجْمِيلَ كَلاَمِهِ"" : تَحْسِينَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20049, 'جَمَالٌ', 'جمال', 'مصدر', 'جمل', 'جمال', 'جمل', 'مص. جَمُلَ، جَمِلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَمَالٌ-جَمَالٌ [ج م ل] (مص. جَمُلَ، جَمِلَ). ""جَمَالُهَا فَاتِنٌ"": حُسْنُهَا، بَهَاؤُهَا. 2.""جَمَال"" : اِسْمُ عَلَمٍ للذُّكُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20050, 'جَمْهَرَةٌ', 'جمهرة', 'مصدر', 'جمهر', 'جمهرة', 'جمهرة', 'مص. جَمْهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَمْهَرَةٌ-جَمْهَرَةٌ [ج م هـ ر] (مص. جَمْهَرَ). ""تَجَمَّعَ فِي السَّاحَةِ العُمُومِيَّةِ جَمْهَرَةٌ مِنَ النَّاسِ"" : حَشْدٌ، جَمْعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20051, 'جَنَابَةٌ', 'جنابة', 'مصدر', 'جنب', 'جنابة', 'جنبة', 'مص. جَنَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَنَابَةٌ-جَنَابَةٌ [ج ن ب] (مص. جَنَبَ). 1.""بِهِ جَنَابَةٌ"" : نَجَاسَةٌ. 2.""جَنَابَةُ مَوْقِعٍ"" : ناَحِيَتُهُ، أَوْ جَانِبُهُ، مَا حَوَالَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20052, 'جُنُونٌ', 'جنون', 'مصدر', 'جنن', 'جنون', 'جنن', 'مص. جَنَّ، جُنَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جُنُونٌ-جُنُونٌ [ج ن ن] (مص. جَنَّ، جُنَّ). 1.""أُصِيبَ بِمَسٍّ مِنَ الجُنُونِ"" : بِآفَةٍ فِي عَقْلِهِ، زَوَال عَقْلِهِ.2.""لا شك أَنَّهُ أُصِيبَ بِجُنُونِ العَظَمَةِ"" : الاعْتِقَادُ بِأَنَّهُ أَعْظَمُ النَّاسِ، مِمَّا يُوَلِّدُ عِنْدَهُ رُوحَ التَّعَالِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20053, 'تَجْنِيدٌ', 'تجنيد', 'مصدر', 'جند', 'تجنيد', 'تجند', 'مص. جَنَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْنِيدٌ-تَجْنِيدٌ [ج ن د] (مص. جَنَّدَ). 1."" أَعْلَنَ عَنْ تَجْنِيدِ الجُنُودِ الاِحْتِيَاطِيِّينَ"" : جَمْعُهُمْ لِمُوَاجَهَةِ حَرْبٍ أَوْ كَارِثَةٍ وَلِيَكُونُوا فِي حَالَةِ تَأَهُّبٍ. 2.""نُودِيَ عَلَيْهِ لِلتَّجْنِيدِ الإِجْبَارِيِّ"": لِلاِلْتِحَاقِ بِالخِدْمَةِ العَسْكَرِيَّةِ الإِجْبَارِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20054, 'جَنْدَلَةٌ', 'جندلة', 'مصدر', 'جندل', 'جندلة', 'جندلة', 'مص. جَنْدَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جَنْدَلَةٌ-جَنْدَلَةٌ [ج ن د ل] (مص. جَنْدَلَ).: وَاحِدَةُ الجَنْدَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20055, 'جِنَاسٌ', 'جناس', 'مصدر', 'جنس', 'جناس', 'جنس', 'مص. جَنَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"جِنَاسٌ-جِنَاسٌ [ج ن س] (مص. جَنَسَ).: فِي البَدِيعِ تَشَابُهُ الكَلِمَتَيْنِ فِي اللَّفْظِ لاَ فِي الْمَعْنَى، وَهُوَ أَنْوَاعٌ: ""اِرْعَ الجَارَ وَلَوْ جَارَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20056, 'جِنَايَةٌ', 'جناية', 'مصدر', 'جني', 'جناية', 'جنة', 'مص. جَنَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"جِنَايَةٌ-جِنَايَةٌ [ج ن ي] (مص. جَنَى). 1.""اِرْتَكَبَ جِنَايَةً"" : ذَنْباً. 2.""اِرْتَكَبَ جِنَايَةً اِهْتَزَّ لَهَا الحَيُّ"" : جَرِيمَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20057, 'جَنىً', 'جنى', 'مصدر', 'جني', 'جنى', 'جن', 'مص. جَنَى.', '', '', 'مفرد', 'Dy', '', '', '"أَجْنَاءُ:أَجْنٍ"', '', 'Rw', '', '', '', '', '', '', '"ج: أَجْنَاءُ، أَجْنٍ. (مص. جَنَى).: مَا يُجْنَى مِنَ الثَّمَرِ أَوِ العِنَبِ أَوِ العَسَلِ وَغَيْرِهِ. وَاحِدَتُهُ جَنَاةٌ، يُقَالُ : ""أَتَانَا بِجِنَاةٍ طَيِّبَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20058, 'أَجْنَاءٌ', 'أجناء', 'مصدر', '', 'ءجناء', 'جن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20059, 'أَجْنٍ', 'أجن', 'مصدر', '', 'ءجن', 'جن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20060, 'جَهْدٌ', 'جهد', 'مصدر', 'جهد', 'جهد', 'جهد', 'مص. جَهَدَ', '', '', 'مفرد', 'DnN', '', '', '"جُهُودٌ"', '', 'R', '', '', '', '', '', '', '"(مص. جَهَدَ). 1.""سَعَى بِجَهْدِهِ إِلَى بُلُوغِ مَرَامِيهِ"" : بِكَدِّهِ. 2.""حَقَّقَ هَدَفَهُ بِجَهْدٍ جَهِيدٍ"" : بِمَشَقَّةٍ، بِصُعُوبُةٍ كَبِيرَةٍ. ""جَهْدُ جَاهِدٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20061, 'جُهُودٌ', 'جهود', 'مصدر', '', 'جهود', 'جهد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20062, 'جَهْرٌ', 'جهر', 'مصدر', 'جهر', 'جهر', 'جهر', 'مص. جَهَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَهْرٌ-جَهْرٌ [ج هـ ر] (مص. جَهَرَ). 1.""قَرَأَ النَّصَّ جَهْراً"": بِصَوْتٍ مُرْتَفِعٍ. 2.""أَرَادَ أَنْ يَلْتَقِيَ بِهِ جَهْراً"" : عِيَاناً، عَلَناً. ""سِرّاً وَجَهْراً"". 3.""حَرِصَ عَلَى أَنْ يُكَلِّمَهُ جَهْراً"" : عَلاَنِيَةً، أَمَامَ الْمَلَإِ.النساء آية 148 لاَ يُحِبُّ اللَّهُ الجَهْرَ بِالسُّوءِ مِنَ القَوْلِ إِلاَّ مَنْ ظُلِمَ .(قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20063, 'تَجْهِيزٌ', 'تجهيز', 'مصدر', 'جهز', 'تجهيز', 'تجهز', 'مص. جَهَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. جَهَّزَ) 1.""يُرِيدُ تَجْهِيزَ بَيْتِهِ أَوَّلاً"" : إِعْدَادَهُ، تَهْيِيئَهُ بِكُلِّ الأَشْيَاءِ وَاللَّوَازِمِ الضَّرُورِيَّةِ. 2. ""يَمْلِكُ الجَيْشُ تَجْهِيزَاتٍ عَسْكَرِيَّةً مُتَقَدِّمَةً"" : أَيْ مُعَدَّاتٍ وَآلاَتٍ وَعَتَاداً. ""تَجْهيزَاتٌ صِحِّيَّةٌ"". 3.""وِزَارَةُ التَّجْهِيزِ"" : الوِزَارَةُ الْمَسْؤُولَةُ عَنْ تَزْوِيدِ مُؤَسَّسَاتِ البِلاَدِ بِكُلِّ الْمُعَدَّاتِ وَالآلاَتِ وَالتَّأْثِيثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20064, 'جَهْلٌ', 'جهل', 'مصدر', 'جهل', 'جهل', 'جهل', 'مص. جَهِلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَهْلٌ-جَهْلٌ [ج هـ ل] (مص. جَهِلَ). 1.""مَا زَالَ الجَهْلُ سَائِداً فِي العَدِيدِ مِنَ القُرَى وَالْمُدُنِ"" : اِنْعِدَامُ الْمَعْرِفَةِ. 2.""جَهْلُهُ مُطْبِقٌ"" : اِعْتِقَادُ الشَّيْءِ عَلَى خِلاَفِ حَقِيقَتِهِ. 3.""الجَهْلُ البَسِيطُ"" : عَدَمُ الْمَعْرِفَةِ بِالشَّيْءِ. 4.""الجَهْلُ الْمُرَكَّبُ"" : الاِعْتِقَادُ الجَازِمُ بِمَا لاَ يَتَّفِقُ مَعَ الحَقِيقَةِ، إِذْ يَعْتَقِدُ الرَّجُلُ عَاِرفاً عِلْماً وَهُوَ عَكْسُ ذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20065, 'جَهْمٌ', 'جهم', 'مصدر', 'جهم', 'جهم', 'جهم', 'مص. جَهَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"جَهْمٌ-جَهْمٌ [ج هـ م] (مص. جَهَمَ). 1.""فُوجِئَ لَمَّا اسْتَقْبَلَهُ بِوَجْهٍ جَهْمٍ"" : بِوَجْهٍ عَابِسٍ. 2.""رَجُلٌ جَهْمُ الوَجْهِ"" : فِي وَجْهِهِ سَمَاجَةٌ وَقُبْحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20066, 'تَجْوِيدٌ', 'تجويد', 'مصدر', 'جود', 'تجويد', 'تجد', 'مص. جَوَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْوِيدٌ-تَجْوِيدٌ [ج و د] (مص. جَوَّدَ). 1.""تَجْوِيدُ القُرْآنِ"" : قِرَاءتُهُ قِرَاءةً مُؤَثِّرَةً تَخْضَعُ لِقَوَاعِدَ مُحَدَّدَةٍ لإِخْرَاجِ الحُرُوفِ وَفْقَ مَخَارِجِهَا وَحَسَبَ أُصُولِهَا مَعَ تَرْنِيمٍ وَتَنْغِيمٍ لَهَا. 2.""تَجْوِيدُ الخَطِّ"" : تَحْسِينُهُ وَالاعْتِنَاءُ بِهَنْدَسَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20067, 'تَجْوِيزٌ', 'تجويز', 'مصدر', 'جوز', 'تجويز', 'تجز', 'مص. جَوَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْوِيزٌ-تَجْوِيزٌ [ج و ز] (مص. جَوَّزَ). 1.""تَجْوِيزُ الأَمْرِ"" : تَسْوِيغُهُ وَإِبَاحَتُهُ. 2.""تَجْوِيزُ الرَّأْيِ"" : إِنْفَاذُهُ. 3.""تَجْوِيزُ الْحُكْمِ"" : النَّظَرُ إِلَيْهِ عَلَى أَنَّهُ جَائِزٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20068, 'تَجْوِيعٌ', 'تجويع', 'مصدر', 'جوع', 'تجويع', 'تجع', 'مص. جَوَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْوِيعٌ-تَجْوِيعٌ [ج و ع] (مص. جَوَّعَ). ""تَجْوِيعُ الْمَرْءِ"" : إِجَاعَتُهُ، أَيْ جَعْلُهُ يَعِيشُ فِي جُوعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20069, 'تَجْوِيفٌ', 'تجويف', 'مصدر', 'جوف', 'تجويف', 'تجف', 'مص. جَوَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْوِيفٌ-تَجْوِيفٌ [ج و ف] (مص. جَوَّفَ). 1.""تَجْوِيفُ الشَّيْءِ"" : تَصْيِيرُهُ أَجْوَفَ. 2.""تَجْوِيفُ الصَّيْدِ"" : إِصَابَتُهُ فِي جَوْفِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20070, 'تَجْوَالٌ', 'تجوال', 'مصدر', 'جول', 'تجوال', 'تجل', 'مص. جَوَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْوَالٌ-تَجْوَالٌ [ج و ل] (مص. جَوَّلَ). ""عَادَ مِنْ تَجْوَالِهِ فِي أَرْجَاءِ البِلادِ"" : التَّطْوَاف بَيْنَ الْمُدُنِ وَالقُرى مِنْ غَيْرِ اسْتِقْرَارٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20071, 'جَوًى', 'جوى', 'مصدر', 'جوي', 'جوى', 'ج', 'مص. جَوِي', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"جَوَى-جَوَى [ج و ي] (مص. جَوِي). ""اِشْتَدَّ بِهِ الجَوَى"" : شِدَّةُ العِشْقِ وَمَا يُورِثُهُ مِنْ حُزْنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20072, 'تَجْيِيرٌ', 'تجيير', 'مصدر', 'جير', 'تجيير', 'تجر', 'مص. جَيَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْيِيرٌ-تَجْيِيرٌ [ج ي ر] (مص. جَيَّرَ). ""تَجْيِيرُ الْحَوْضِ"" : طَلْيُهُ بِالْجِيرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20073, 'تَجْيِيشٌ', 'تجييش', 'مصدر', 'جيش', 'تجييش', 'تجش', 'مص. جَيَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَجْيِيشٌ-تَجْيِيشٌ [ج ي ش] (مص. جَيَّشَ). ""تَجْيِيشُ الْجُيُوشِ"" : جَمْعُهَا، حَشْدُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20074, 'مُحَابَاةٌ', 'محاباة', 'مصدر', 'حبو', 'محاباة', 'محبة', 'مص. حَابَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَابَاةٌ-مُحَابَاةٌ [ح ب و] (مص. حَابَى). ""هُوَ فِي العَمَلِ لاَ يَعْرِفُ مُحَابَاةً"" : تَسَاهُلاً، تَسَامُحاً، تَحَيُّزاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20075, 'مُحَاجَّةٌ', 'محاجة', 'مصدر', 'حجج', 'محاجة', 'محجة', 'مص. حَاجَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَاجَّةٌ-مُحَاجَّةٌ [ح ج ج] (مص. حَاجَّ). ""يُكْثِرُ مِنَ الْمُحَاجَّةِ"" : مِنَ الْمُجَادَلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20076, 'حَوْجٌ', 'حوج', 'مصدر', 'حوج', 'حوج', 'حج', 'مص. حاجَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَوْجٌ-حَوْجٌ [ح و ج] (مص. حاجَ). 1. ""بِهِ حَوْجٌ"" : اِفْتِقَارٌ. 2. ""حَوْجاً لكَ"" : أَيْ سَلامَةً، عبارَةٌ تُقَالُ لِلْعَاثِرِ فِي الدُّعاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20077, 'مُحَاجَاةٌ', 'محاجاة', 'مصدر', 'حجو', 'محاجاة', 'محجة', 'مص. حَاجَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَاجَاةٌ-مُحَاجَاةٌ [ح ج و] (مص. حَاجَى). ""اِسْتَمَرَّتْ مُحَاجَاةُ الأَوْلاَدِ فَتْرَةً طَوِيلَةً مِنَ اللَّيْلِ"" : حِكَايَةُ الأَحَاجِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20078, 'مَحِيدٌ', 'محيد', 'مصدر', 'حيد', 'محيد', 'محد', 'مص. حَادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَحِيدٌ-مَحِيدٌ [ح ي د] (مص. حَادَ). ""لاَ مَحِيدَ عَنْ هَذَا الأَمْرِ"" : لاَ مَهْرَبَ مِنْهُ، لاَ بُدَّ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20079, 'حَيْدٌ', 'حيد', 'مصدر', 'حيد', 'حيد', 'حد', 'مص. حادَ', '', '', 'مفرد', 'DnN', '', '', '"حُيودٌ:أحْيادٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حادَ). 1.""حَيْدُ الجَبَلِ"" : مَا يَنْشَأُ وَيَبْرُزُ مِنْ نُتوءٍ فِي نَوَاحِيه. ""جَبَلٌ ذُو حُيودٍ"" ""حَيْدُ الرَّأْسِ"". 2. ""حُيودُ القَرْنِ"" : مَا تَلَوَّى مِنْهُ. 3.""حَيْدُ الوَلَدِ"" : نَظِيرُهُ، مِثْلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20080, 'حُيودٌ', 'حيود', 'مصدر', '', 'حيود', 'حد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20081, 'أحْيادٌ', 'أحياد', 'مصدر', '', 'ءحياد', 'حد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20082, 'مُحَادَثَةٌ', 'محادثة', 'مصدر', 'حدث', 'محادثة', 'محدثة', 'مص. حَادَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. حَادَثَ). 1.""أَجْرَى مَعَهُ مُحَادَثَةً هَامَّةً"" : حِوَاراً، نِقَاشاً. ""مُحَادَثَةٌ سِيَاسِيَّةٌ"". 2.""محُادَثَةٌ هَاتِفِيَّةٌ"" : مُكَالَمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20083, 'مُحَاذَرَةٌ', 'محاذرة', 'مصدر', 'حذر', 'محاذرة', 'محذرة', 'مص. حَاذَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَاذَرَةٌ-مُحَاذَرَةٌ [ح ذ ر] (مص. حَاذَرَ). ""نَصَحَهُ بِمُحَاذَرَةِ الأَشْرَارِ"" : بِالاحْتِيَاطِ وَالْحَذَرِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20084, 'مُحَاذَاةٌ', 'محاذاة', 'مصدر', 'حذو', 'محاذاة', 'محذة', 'مص. حَاذَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَاذاَةٌ-مُحَاذاَةٌ [ح ذ و] (مص. حَاذَى). ""تَمْتَدُّ السِّكَّةُ الْحَدِيدِيَّةُ لمَسَافَةٍ طَوِيلَةٍ بِمُحَاذَاةِ النَّهْرِ"" : بِإِزَائِهِ، بِمُقَابِلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20085, 'حَيْرَةٌ', 'حيرة', 'مصدر', 'حير', 'حيرة', 'حرة', 'مص. حَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَيْرَةٌ-حَيْرَةٌ [ح ي ر] (مص. حَارَ). ""هُوَ فِي حَيْرَةٍ مِنْ أمْرِهِ"": فِي ارْتِبَاكٍ وَترَدُّدٍ وَاضْطِرَابٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20086, 'مُحَارَبَةٌ', 'محاربة', 'مصدر', 'حرب', 'محاربة', 'محربة', 'مص. حَارَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَارَبَةٌ-مُحَارَبَةٌ [ح ر ب] (مص. حَارَبَ). 1. ""مُحَارَبَةُ الأَعْدَاءِ"" : مُقَاتَلَتُهُمْ. 2.""مُحارَبَةُ الأُمِّيَّةِ"" : القَضاءُ على الجَهْلِ ومَحْوُهُ. ""مُحاربَةُ داءِ السُّلِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20087, 'حَيْرٌ', 'حير', 'مصدر', 'حير', 'حير', 'حر', 'مص. حَارَ يَحَارُ', '', '', 'مفرد', 'DnN', '', '', '"أحْيَارُ"', '', 'R', '', '', '', '', '', '', '"(مص. حَارَ يَحَارُ). 1.:حَدِيقَةُ الحَيَوَانِ، شِبْهُ الحَظِيرة. 2. ""حَيْرُ السَّيْرَكِ"" : مَعْرِضُ الحَيَوَانَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20088, 'أحْيَارٌ', 'أحيار', 'مصدر', '', 'ءحيار', 'حر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20089, 'حَوْزٌ', 'حوز', 'مصدر', 'حوز', 'حوز', 'حز', 'مص. حَازَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَوْزٌ-حَوْزٌ [ح و ز] (مص. حَازَ). 1. ""سَوْقٌ حَوْزٌ"" : رُوَيْدٌ، أَوْ شَدِيدٌ. 2. ""هَذَا فِي حَوْزِهِ"" : فِي مِلْكِهِ. 3.""أرْضُ حَوْزٍ"" : أَرْضٌ أُقِيمَ حَوْلَهَا حَاجِزٌ. 4.: الطَّبِيعَةُ مِنْ خَيْرٍ أَوْ شَرٍّ. 5.""لَيْلَةُ الحَوْزِ"" : أوَّلُ لَيْلَةٍ تُوَجَّهُ فِيهَا الجِمالُ إلَى الْمَاءِ إذَا كَانَتْ بَعِيدَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20090, 'مُحَازَبَةٌ', 'محازبة', 'مصدر', 'حزب', 'محازبة', 'محزبة', 'مص. حَازَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَازَبَةٌ-مُحَازَبَةٌ [ح ز ب] (مص. حَازَبَ). ""أَظْهَرُوا مُحَازَبَةً لِمُوَاجَهَةِ الأَعْدَاءِ"" : تَعَاضُداً وَتَحَالُفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20091, 'حَيْزٌ', 'حيز', 'مصدر', 'حيز', 'حيز', 'حز', 'مص. حَازَ يَحِيزُ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَيِّزٌ-حَيِّزٌ [ح و ز]. 1. ""لاَزِمْ حَيِّزَكَ"" : مَكَانَكَ. 2. ""حَيِّزٌ مِنَ الدَّارِ"" : مَا هُوَ مُلْحَقٌ بِهَا. 3. ""هَذا الْمَشْرُوعُ فِي حَيِّزِ التَّنْفِيذِ"" : فِي طَرِيقِ التَّنْفِيذِ. 4. ""يَعِيشُ فِي حَيِّزِهِ"" : فِي كَنَفِهِ، فِي حِيَازَتِهِ. 5.""ظَهَرَ إلَى حَيِّزِ الوُجُودِ"" : إلَى مَجَالِ الوَاقِعِ. 6.""هَذَا لَيْسَ فِي حَيِّزِ الإِمْكَانِ"" : لَيْسَ فِي حُدُودِ الإِمْكَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20092, 'مُحَاسَبَةٌ', 'محاسبة', 'مصدر', 'حسب', 'محاسبة', 'محسبة', 'مص. حَاسَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. حَاسَبَ). 1.""حَاسَبَهُ مُحَاسَبَةً عَسِيرَةً"" : أَيْ حَاسَبَهُ حِسَاباً، مُنَاقَشَةً وَمُجَادَلَةً. 2.""مُحَاسَبَةُ النَّفْسِ"" : التَّشْدِيدُ فِي مُعَاتَبَتِهَا وَمُرَاقَبَتِهَا. 3.""الْمَسْؤُولُ عَنِ الْمُحَاسَبَةِ"" : عَنِ الْمُرَاجَعَةِ الحِسَابِيَّةِ وَالتَّدْقِيقِ فِيهَا. 4.""قِسْمُ الْمُحَاسَبَةِ"" : قِسْمٌ مُخْتَصٌّ فِي إِدَارَةٍ مَّا بِالشُّؤُونِ الْمَالِيَّةِ وَالتَّدْقِيقِ فِي حِسَابَاتِهَا، مَدَاخِيلِهَا وَمَصَارِيفِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20093, 'مُحَاسَنَةٌ', 'محاسنة', 'مصدر', 'حسن', 'محاسنة', 'محسنة', 'مص. حَاسَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَاسَنَةٌ-مُحَاسَنَةٌ [ح س ن] (مص. حَاسَنَ). 1.""تَجَنَّبِ الْمُحَاسَنَةَ يَا وَلَدِي"" : التَّبَاهِي وَإِظْهَارُ الْمَحَاسِنِ. 2.""كَانُوا بِحَاجَةٍ إِلَى الْمُحَاسَنَةِ"" : بِحَاجَةٍ إِلَى العَطْفِ وَالإِحْسَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20094, 'حَوْشٌ', 'حوش', 'مصدر', 'حوش', 'حوش', 'حش', 'مص. حَاشَ ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَوْشٌ-حَوْشٌ [ح و ش] (مص. حَاشَ) ""حَوْشُ الدَّارِ"" : شِبْهُ حَظِيرَةٍ تُوضَعُ فِيهَا الدَّوَابُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20095, 'مُحَاشَاةٌ', 'محاشاة', 'مصدر', 'حشي', 'محاشاة', 'محشة', 'مص. حَاشَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَاشَاةٌ-مُحَاشَاةٌ [ح ش ي] (مص. حَاشَى). ""لَمْ يَعْرِفْ سَبَبَ مُحَاشَاتِهِ"" : اِسْتِثْنَائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20096, 'حَيْصٌ', 'حيص', 'مصدر', 'حيص', 'حيص', 'حص', 'مص. حَاصَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَيْصٌ-حَيْصٌ [ح ي ص] (مص. حَاصَ). ""وَقَعَ فِي حَيْصَ بَيْصَ"" : فِي ضَيْقٍ وَشِدَّةٍ وَارْتِبَاكٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20097, 'مَحِيصٌ', 'محيص', 'مصدر', 'حيص', 'محيص', 'محص', 'مص. حَاصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَحِيصٌ-مَحِيصٌ [ح ي ص] (مص. حَاصَ). ""قَضَاءٌ نَازِلٌ لاَ مَحِيصَ عَنْهُ"" : لاَ مَهْرَبَ، لاَ مَحِيدَ، لاَ فِرَارَ مِنْهُ.النساء آية 121 أُولَئِكَ مَأْوَاهُمْ جَهَنَّمُ وَلاَ يَجِدُونَ عَنْهَا مَحِيصاً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20098, 'مُحَاصَرَةٌ', 'محاصرة', 'مصدر', 'حصر', 'محاصرة', 'محصرة', 'مص. حَاصَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَاصَرَةٌ-مُحَاصَرَةٌ [ح ص ر] (مص. حَاصَرَ). ""مُحَاصَرَةُ قُوَّاتِ العَدُوِّ"" : الإِحَاطَةُ بِهَا مِنْ كُلِّ جِهَةٍ وَمَنْعُهَا مِنَ التَّحَرُّكِ أَوِ الخُرُوجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20099, 'حَيْضٌ', 'حيض', 'مصدر', 'حيض', 'حيض', 'حض', 'مص. حَاضَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَيْضٌ-حَيْضٌ [ح ي ض] (مص. حَاضَ). كَانَتْ فِي فَتْرَةِ حَيْضٍ"" : العادَةُ الشَّهْرِيَّةُ عِنْدَ الْمَرْأةِ، أيْ سَيَلانُ الدَّمِ مِنْ رَحِمِهَا فِي أيَّامٍ مَعْلُومَةٍ مِنَ الشَّهْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20100, 'مُحَاضَرَةٌ', 'محاضرة', 'مصدر', 'حضر', 'محاضرة', 'محضرة', 'مص. حَاضَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. حَاضَرَ). 1.""أَلْقَى مُحَاضَرَةً قَيِّمَةً"" : أَيْ خُلاَصَةَ أَفْكَارٍ أَوْ بَحْثٍ فِي مَوْضُوعٍ مَّا، يُلْقِيهِ الْمُحَاضِرُ فِي جَمْعٍ مِنَ النَّاسِ. 2.""قَاعَةُ الْمُحَاضَرَاتِ"" : القَاعَةُ الَّتِي تُلْقَى فِيهَا الْمُحَاضَرَاتُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20101, 'حِيطَةٌ', 'حيطة', 'مصدر', 'حوط', 'حيطة', 'حطة', 'مص. حَاطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حِيطَةٌ-حِيطَةٌ، حَيْطَةٌ [ح و ط] (مص. حَاطَ). 1. ""يَسْتَعِدُّ لِلأمْرِ بِكُلِّ مَا يَلْزَمُ مِنَ الحِيطَةِ"" : مِنَ الحَذَرِ وَالتَّدْبِيرِ. 2. ""أَخَذَ حِيطَتَهُ"" : اِحْتِياطَهُ، اِحْتِرَازَهُ. ""يُغامِرُ بِلاَ حِيطَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20102, 'حَوْطٌ', 'حوط', 'مصدر', 'حوط', 'حوط', 'حط', 'مص. حاطَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَوْطٌ-حَوْطٌ [ح و ط] (مص. حاطَ). ""تَحَزَّمَ بِحَوْطٍ"" : خَيْطٌ مَفْتُولٌ مِنْ لَوْنَيْنِ أَحْمَرَ وَأَسْوَدَ فِيهِ خَرَزاتٌ وَهِلالٌ مِنْ فِضَّةٍ، يُشَدُّ عَلَى وَسَطِ حَامِلِهِ لِئَلاَّ يُصَابَ بِالعَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20103, 'حَوْفٌ', 'حوف', 'مصدر', 'حوف', 'حوف', 'حف', 'مص. حَافَ', '', '', 'مفرد', 'DnN', '', '', '"أَحْوَافٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَافَ). 1.""حَوْفُ الْمَكَانِ"" : جَانِبُهُ، نَاحِيَتُهُ. 2. ""اِرْتَدَى الوَلَدُ حَوْفاً"": ثَوْباً مِن جِلْدٍ لا كُمَّ لَه يَلْبَسُهُ الأَوْلاَدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20104, 'أَحْوَافٌ', 'أحواف', 'مصدر', '', 'ءحواف', 'حف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20105, 'حَيْفٌ', 'حيف', 'مصدر', 'حيف', 'حيف', 'حف', 'مص. حَافَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَيْفٌ-حَيْفٌ [ح ي ف] (مص. حَافَ). 1. ""أنْزَلَ بِهِ حَيْفاً"": ظُلْماً، جَوْراً. ""فِي حُكْمِهِ حَيْفٌ"" إنِّي لاَ أَشْهَدُ عَلَى حَيْفٍ (حديث). 2. ""حَيْفٌ عَلَيْكَ"" : وا أَسَفَاهُ عَلَيْكَ، بِئْسَ مَا فَعَلْتَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20106, 'مُحَافَظَةٌ', 'محافظة', 'مصدر', 'حفظ', 'محافظة', 'محفظة', 'مص. حَافَظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَافَظَةٌ-مُحَافَظَةٌ [ح ف ظ] (مص. حَافَظَ). 1.""الْمُحَافَظَةُ عَلَى النِّظَامِ"" : صِيَانَتُهُ. ""الْمُحَافَظَةُ عَلَى النَّفْسِ"". 2.""الْمُحَافَظَةُ"" ج: مُحَافَظَاتٌ : تَقْسِيمٌ إِدَارِيٌّ فِي بَعْضِ البُلْدَانِ العَرَبِيَّةِ، الوِلاَيَةُ، الإِقْلِيمُ، يَتَوَلَّى إِدَارَتَهَا الْمُحَافِظُ، أَيِ الوَالِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20107, 'حِفَاظٌ', 'حفاظ', 'مصدر', 'حفظ', 'حفاظ', 'حفظ', 'مص. حافَظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حِفَاظٌ-حِفَاظٌ [ح ف ظ] (مص. حافَظَ). 1. ""يَسْعَى لِلْحِفَاظِ عَلَى مَوَدَّتِهِ"" : لِصِيَانَتِهَا وَبَقَائِهَا. ""يَدْعُو لِلْحِفَاظِ عَلَى النِّظَامِ"". 2. ""حِفَاظُ الرَّضِيعِ"" : حِفَاضٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20108, 'حَوْقٌ', 'حوق', 'مصدر', 'حوق', 'حوق', 'حق', 'مص. حَاقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَوْقٌ-حَوْقٌ، ةٌ [ح و ق] (مص. حَاقَ). 1.: الحَوْقَلَةُ. 2.:الجَمْع الكَثِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20109, 'حَوْقَةٌ', 'حوقة', 'مصدر', 'حوق', 'حوقة', 'حقة', 'مص. حَاقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَوْقٌ-حَوْقٌ، ةٌ [ح و ق] (مص. حَاقَ). 1.: الحَوْقَلَةُ. 2.:الجَمْع الكَثِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20110, 'حِيَاكَةٌ', 'حياكة', 'مصدر', 'حوك', 'حياكة', 'حكة', 'مص. حَاكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حِيَاكَةٌ-حِيَاكَةٌ [ح و ك] (مص. حَاكَ). ""يَشْتَغِلُ فِي الحِيَاكَةِ"": حِرْفَةُ الحَائِكِ، أيْ نَسْجُ الثِّيَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20111, 'حَوْكٌ', 'حوك', 'مصدر', 'حوك', 'حوك', 'حك', 'مص. حاكَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَوْكٌ-حَوْكٌ [ح و ك] (مص. حاكَ). 1.""هَذَا عَلَى حَوْكِ ذَاكَ"" : عَلَى مِثالِهِ سِنّاً أوْ هَيْئَةً. 2.""حَوْكُ ثَوْبٍ"" : مَا نُسِجَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20112, 'مُحَاكَمَةٌ', 'محاكمة', 'مصدر', 'حكم', 'محاكمة', 'محكمة', 'مص. حَاكَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. حَاكَمَ). ""مُحَاكَمَةُ الْمُجْرِمِ"" : اِسْتِجْوَابُهُ فِيمَا جَنَاهُ مِنَ أَعْمَالٍ إِجْـرَامِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20113, 'مُحَاكَاةٌ', 'محاكاة', 'مصدر', 'حكي', 'محاكاة', 'محكة', 'مص. حَاكَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَاكَاةٌ-مُحَاكَاةٌ [ح ك ي] (مص. حَاكَى). 1.""الْمُحَاكَاةُ فِي القَوْلِ أَوِ الفِعْلِ"" : الْمُمَاثَلَةُ، الْمُشَابَهَةُ، التَّقْلِيدُ. ""يُحَاكِي جَمِيعَ مَا يَسْمَعُهُ مِنْ أَصْوَاتِ الطَّيْرِ وَأَنْوَاعِ سَائِرِ الْحَيَوَانِ مُحَاكَاةً شَدِيدَةً لِقُوَّةِ انْفِعَالِهِ"" (ابن طفيل). 2.""الْمُحَاكَاةُ فِي عِلْمِ النَّفْسِ"" : الإِعَادَةُ تَحْتَ تَأْثِيرِ عَوَامِلَ نَفْسِيَّةٍ لِحَرَكَاتٍ وَأَعْمَالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20114, 'حَوْلٌ', 'حول', 'مصدر', 'حول', 'حول', 'حل', 'مص. حَالَ', '', '', 'مفرد', 'DnN', '', '', '"أحْوَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَالَ). 1.""مَرَّ عَلَيْهِ حَوْلٌ"": مَرَّتْ عَلَيْهِ سَنَةٌ. 2. ""لاَ حَوْلَ وَلا قُوَّةَ إِلا بِاللَّهِ"": لاَ قُدْرَةَ وَلاَ قُوَّةَ إلاَّ بِاللَّهِ. 3. ""لاَ حَوْلَ لَهُ، وَلاَ حِيلَةَ"" : لاَ قُدْرَةَ لَهُ، أيْ عَاجِزٌ. 4. ""تَج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20115, 'أحْوَالٌ', 'أحوال', 'مصدر', '', 'ءحوال', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20116, 'حَيْلُولَةٌ', 'حيلولة', 'مصدر', 'حول', 'حيلولة', 'حللة', 'مص. حَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَيْلُولَةٌ-حَيْلُولَةٌ [ح و ل] (مص. حَالَ). ""سَعى إلَى الحَيْلُولَةِ دُونَ لِقَائِهِ"" : إلَى عَدَمِ لِقَائِهِ. ""قَامَ بِمُحَاوَلاتٍ لِلْحَيْلُولَةِ دُونَ مَعْرِفَةِ الحَقِيقَةِ"" ""لَمْ يَقْتَنِعْ يَوْماً بِالأَوَامِرِ الصَّارِمَةِ الَّتِي يُلاحِقُهُ بِهَا لِلْحَيْلُولَةِ بَيْنَهُ وَبَيْنَ مَا تَصْبُو إلَيْهِ نَفْسُهُ""(ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20117, 'حِيَالٌ', 'حيال', 'مصدر', 'حول', 'حيال', 'حل', 'مص. حَالَ يَحُولُ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حِيَالٌ-حِيَالٌ [ح و ل] (مص. حَالَ يَحُولُ). ""جَلَسَ حِيَالَهُ"": قُبَالَتَهُ، إِزَاءهُ، حِذاءهُ . ""جَلَسَ بِحِيَالِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20118, 'حَيْلٌ', 'حيل', 'مصدر', 'حيل', 'حيل', 'حل', 'مص. حَالَ يَحِيلُ', '', '', 'مفرد', 'DnN', '', '', '"أَحْيَالٌ:حُيولٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَالَ يَحِيلُ). 1. ""شُدَّ حَيْلَكَ"" : شُدَّ عَزْمَكَ وَقُوَّتَكَ. اللَّهُمَّ ذَا الحَيْلِ الشَّدِيدِ (حديث). 2.""حَيْلُ الوَادِي"" : الْمَاءُ الْمُتَجَمِّعُ فِي بَطْنِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20119, 'حُبٌّ', 'حب', 'مصدر', 'حبب', 'حب', 'حب', 'مص.حَبَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حُبٌّ-حُبٌّ [ح ب ب] (مص.حَبَّ). 1.""يُكِنُّ لَهُ حُبّاً عَميقاً"": مَحَبَّةً.أَميرَتِي، لاَ تَغْفِـرِي ذَنْبِـي*فَإِنَّ ذَنْبِي شِـدَّةُ الحُـب (العباس بن الأَحنف). 2.""حُبُّ الذَّاتِ"" : تَقْديمُ الذَّاتِ وَتَعْظِيمُها، الأَنانِيَّةُ. 3.""حُبُّ الاِسْتِطْلاعِ"" : الْمَيْلُ إلى مَعْرِفَةِ الأشْياءِ والاِطِّلاعِ عَلَيْها. 4.""حُبُّ الوَطَنِ مِنَ الإِيمانِ"" : التَّعَلُّقُ بالوَطَنِ والتَّفانِي في مَحَبَّتِهِ. ""رُحْتُ أَعْدُو وَأَتَعَثَّرُ بِالصّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20120, 'أَحْيَالٌ', 'أحيال', 'مصدر', '', 'ءحيال', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20121, 'حُيولٌ', 'حيول', 'مصدر', '', 'حيول', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20122, 'حَيْنٌ', 'حين', 'مصدر', 'حين', 'حين', 'حن', 'مص. حَانَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَيْنٌ-حَيْنٌ [ح ي ن] (مص. حَانَ). ""أَصَابَهُ الحَيْنُ"" : الهَلاكُ، المِحْنَةُ. ""إذا حَانَ الحَيْنُ حَارَتِ العَيْنُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20123, 'حِوَارٌ', 'حوار', 'مصدر', 'حور', 'حوار', 'حر', 'مص. حَاوَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"حِوَارٌ-حِوَارٌ [ح و ر] (مص. حَاوَرَ). 1. ""جَرَى بَيْنَهُمَا حِوَارٌ"" : نِقَاشٌ، جِدَالٌ. 2. ""لَمْ يَكُنِ الحِوَارُ مَعَهُ مُجْدِياً"" : الْمُحَادَثَةُ. 3. ""اِعْتَمَدَ حِوَارُ الرِّوَايَةِ عَلَى الجِدِّيَّةِ وَالسُّخْرِيَةِ"": مَا تَتَحَاوَرُ بِهِ شَخصِيَّاتُ الرِّوَايَةِ ومَا شَابَهَ ذَلِكَ مِنْ كَلامٍ. ""الحِوَارُ عُنْصُرٌ مِنَ العَنَاصِرِ الفَنِّيَّةِ لِلْقِصَّةِ وَالْمَسْرَحِيَّةِ وَالرِّوَايَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20124, 'مُحَاوَرَةٌ', 'محاورة', 'مصدر', 'حور', 'محاورة', 'محرة', 'مص. حَاوَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. حَاوَرَ). 1.""اِسْتَغْرَقَتِ الْمُحَاوَرَةُ وَقْتاً طَوِيلاً"" : الْمُحَادَثَةُ بَيْنَ شَخْصَيْنِ أَوْ أَكْثَرَ. 2.""مُحَاوَرَةُ الفَلاَسِفَةِ"" : الْمُجَادَلَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20125, 'مُحَاوَلَةٌ', 'محاولة', 'مصدر', 'حول', 'محاولة', 'محلة', 'مص. حَاوَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. حَاوَلَ). 1.""قَامَ بِمُحَاوَلَةٍ جَدِيدَةٍ"" : بِمَسْعىً، بِاجْتِهَادٍ، بِجُهْدٍ. ""مُحَاوَلَةٌ أُولَى"" ""مُحَاوَلَةٌ أَخِيرَةٌ"". 2.""مُحَاوَلَةُ اعْتِدَاءٍ عَلَى حَيَاتِهِ"" : تَحْضِيرٌ مَعَ إِرَادَةِ القِيَامِ بِجَرِيمَةٍ. 3.""الْمُحَاوَلَةُ وَالخَطَأُ"" : التَّجْرِبَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20126, 'حِيَادٌ', 'حياد', 'مصدر', 'حيد', 'حياد', 'حد', 'مص. حَايَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"حِيَادٌ-حِيَادٌ [ح ي د] (مص. حَايَدَ). 1. ""وَقَفَ مَوْقِفَ الحِيَادِ مِنَ الْمُتَنَازِعَيْنِ"" : عَدَمُ الانْحِيازِ لأَحَدٍ مِنْهُما. ""اِتَّخَذَ مَوْقِفَ الحْيادِ مِنَ الصِّراعِ. 2.""الحْيادُ الإيجابِيُّ"" (سيا): عَدَمُ انْحِيازِ دَوْلَةٍ إلَى إحْدَى الدُّوَلِ الكُبْرَى وَالعَمَلُ عَلَى الْمُشَارَكَةِ فِي حِفْظِ السَّلاَمِ الدُّوَلِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20127, 'مُحَايَدَةٌ', 'محايدة', 'مصدر', 'حيد', 'محايدة', 'محدة', 'مص. حَايَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُحَايَدَةٌ-مُحَايَدَةٌ [ح ي د] (مص. حَايَدَ). ""سِيَاسَةُ الْمُحَايَدَةُ"": سِيَاسَةُ عَدَمِ الانْحِيَازِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20128, 'مَحَبَّةٌ', 'محبة', 'مصدر', 'حبب', 'محبة', 'محبة', 'مص. حَبَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَحَبَّةٌ-مَحَبَّةٌ [ح ب ب] (مص. حَبَّ). ""مَحَبَّةُ النَّاسِ"" : الْحُبُّ، الْمَوَدَّةُ، الصَّدَاقَةُ. ""نَظَرَ إِلَيْهَا وَنَظَرَتْ إِلَيْهِ وَعُيُونُهُمَا تُومِضُ بِالْمَحَبَّةِ"" (ع. م. العقاد)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20129, 'حَجٌّ', 'حج', 'مصدر', 'حجج', 'حج', 'حج', 'مص. حَجَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَجٌّ-حَجٌّ [ح ج ج] (مص. حَجَّ). 1.""أَدَّى فَريضَةَ الحَجِّ"" : زِيارَة الكَعْبَةِ الْمُشَرَّفَةِ لأِداءِ مَناسِكِ الحَجِّ، وَهُوَ أَحَدُ أَرْكانِ الإِسْلامِ الخَمْسَةِ. 2.""الحَجُّ الأَكْبَرُ"" : يَوْمُ النَّحْرِ أَوْ يَوْمُ عَرَفَةَ.التوبة آية 3 وَأَذانٌ مِنَ اللَّهِ وَرَسولِهِ إلى النَّاسِ يَوْمَ الحَجِّ الأكْبَرِ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20130, 'تَحْبِيبٌ', 'تحبيب', 'مصدر', 'حبب', 'تحبيب', 'تحبب', 'مص. حَبَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْبِيبٌ-تَحْبِيبٌ [ح ب ب] (مص. حَبَّبَ). 1.""تَحْبِيبُ الشَّيْءِ"" : جَعْلُهُ مَحْبُوباً. 2.""تَحْبِيبُ الزَّرْعِ"" : ظُهُورُ حَبِّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20131, 'تَحْبِيذٌ', 'تحبيذ', 'مصدر', 'حبذ', 'تحبيذ', 'تحبذ', 'مص. حَبَّذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْبِيذٌ-تَحْبِيذٌ [ح ب ذ] (مص. حَبَّذَ). ""تَحْبِيذُ أَمْرٍ"" : النَّظَرُ إِلَيْهِ عَلَى أَنَّهُ مَقْبُولٌ وَمُلاَئِمٌ ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20132, 'تَحْبِيرٌ', 'تحبير', 'مصدر', 'حبر', 'تحبير', 'تحبر', 'مص. حَبَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْبِيرٌ-تَحْبِيرٌ [ح ب ر] (مص. حَبَّرَ). 1. ""تَحْبِيرُ رِسَالَةٍ"" : كِتَابَتُهَا. ""فَإِذَا كَانَ مِنْ قَوْلِ الْمُنْشِدِ وَقَرِيضِهِ وَمِنْ نَحْتِهِ وَتَحْبِيرِهِ، فَقَدْ بَلَغَ الغَايَةَ وَأَقَام"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20133, 'حُبورٌ', 'حبور', 'مصدر', 'حبر', 'حبور', 'حبر', 'مص. حَبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حُبورٌ-حُبورٌ [ح ب ر] (مص. حَبَرَ). ""جاءَ وَقَدْ مُلِئَ صَدْرُهُ حُبوراً"" : سروراً، فَرَحاً، بَهْجَةً، جَذَلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20134, 'تَحْبِيسٌ', 'تحبيس', 'مصدر', 'حبس', 'تحبيس', 'تحبس', 'مص. حَبَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْبِيسٌ-تَحْبِيسٌ [ح ب س] (مص. حَبَّسَ). ""تَحْبِيسُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20135, 'حَبْسٌ', 'حبس', 'مصدر', 'حبس', 'حبس', 'حبس', 'مص. حَبَسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَبْسٌ-حَبْسٌ [ح ب س] (مص. حَبَسَ). 1.""وَضَعوهُ في الحَبْسِ"" : في السِّجْنِ. 2.""حُكِمَ عَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20136, 'تَحْبِيلٌ', 'تحبيل', 'مصدر', 'حبل', 'تحبيل', 'تحبل', 'مص. حَبَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْبِيلٌ-تَحْبِيلٌ [ح ب ل] (مص. حَبَّلَ). ""تَحْبِيلُ الْمَرْأَةِ"" : تَصْيِيرُهَا حُبْلَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20137, 'حَتْمٌ', 'حتم', 'مصدر', 'حتم', 'حتم', 'حتم', 'مص. حَتَمَ', '', '', 'مفرد', 'DnN', '', '', '"حُتومٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَتَمَ). 1.""سَأَزورُكُ حَتْماً"" : لاَ مَحالَةَ. 2.""لَبَنٌ حَتْمٌ"" : نَقِيٌّ، خالِصٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20138, 'حُتومٌ', 'حتوم', 'مصدر', '', 'حتوم', 'حتم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20139, 'حَدٌّ', 'حد', 'مصدر', 'حدد', 'حد', 'حد', 'مص. حَدَّ', '', '', 'مفرد', 'DnN', '', '', '"حُدودٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَدَّ). 1.""بَلَغَ في مَوْضوعِهِ حَدّاً"" : مُنْتَهاهُ. ""أَكْرَمَنا إِكْراماً فاقَ الحَدَّ"". 2.""كانَ ذلِكَ هُوَ الحَدُّ الفاصِلُ بَيْنَهُما"" : الحاجِزُ. 3."" لَمْ أَتَوَصَّلْ بِجَوابٍ إِلى حَدِّ الآنَ"" : لِغايَةِ الآنَ. ""لِحَدِّ الآنَ"". 4.""ذَهَبَ إلى حَدٍّ بَعيدٍ في لَهْوِهِ"" : إلى مَدىً بَعيدٍ، كَبيرٍ. 5.""إلى أَيِّ حَدٍّ يُمْكِنُ أَنْ"" : إلى أَيِّ دَرَجَةٍ . ""تَفَوَّقَ في جَوابِهِ إلى حَدٍّ مَّا"". 6.""هَذا العِلْمُ بِلا حَدٍّ"" : بِلا نِهايَةٍ، بِلا حَصْرٍ. ""بَحْرٌ لاَ حَدَّ لَهُ"" ""مَوْضوعٌ لاَ حَدَّ لَهُ"". 7.""هَذا الْمَوْضوعُ في حَدِّ ذاتِهِ لا يَسْتَحِقُّ كُلَّ هَذا الاِهْتِمامِ"" : في طَبيعَتِهِ. 8.""هَذا الأَمْرُ عِنْدِي على حَدٍّ سَواءٍ أَوْ على حَدٍّ سَوِيٍّ"" : لا فَرْقَ، دونَ تَمْيِيزٍ. 9.""عَلَيْكَ أَنْ تُراعِيَ الحَدَّ الأَدْنَى"" : الْمُسْتَوَى الَّذِي يُمْكِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20140, 'تَحْجِيرٌ', 'تحجير', 'مصدر', 'حجر', 'تحجير', 'تحجر', 'مص. حَجَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْجِيرٌ-تَحْجِيرٌ [ح ج ر] (مص. حَجَّرَ). 1.""تَحْجِيرُ الطِّينِ"" : تَصْيِيرُهُ كَالحَجَرِ. 2.""تَحْجِيرُ الحَقْلِ"" : إِحَاطَتُهُ بِالحَجَرِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20141, 'حِجْرٌ', 'حجر', 'مصدر', 'حجر', 'حجر', 'حجر', 'مص. حَجَرَ', '', '', 'مفرد', 'DnN', '', '', '"حُجورٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. حَجَرَ). ""نَشَأَ في حِجْرِهِ"" : في حِضْنِهِ، في كَنَفِهِ، في حِمايَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20142, 'حُجورٌ', 'حجور', 'مصدر', '', 'حجور', 'حجر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20143, 'حَجْرٌ', 'حجر', 'مصدر', 'حجر', 'حجر', 'حجر', 'مص.حَجَرَ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"حَجْرٌ-حَجْرٌ [ح ج ر] (مص.حَجَرَ). 1.""رَفَعَ الحَجْرَ عَنْ قاصِرٍ"" : رَفَعَ عَنْهُ الْمَنْعَ. 2.""فَرَضَ الحَجْرَ على أَمْلاكِهِ"" : مَنَعَهُ مِنَ التَّصَرُّفِ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20144, 'حَجْزٌ', 'حجز', 'مصدر', 'حجز', 'حجز', 'حجز', 'مص. حَجَزَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَجْزٌ-حَجْزٌ [ح ج ز] (مص. حَجَزَ). 1.""وَقعَ حَجْزُ أَمْلاكِهِ"": مَنْعُ التَّصَرُّفِ فيها. 2.""حَجْزُ سَفينَةٍ"" : تَوْقيفُها، جَعْلُها تَحْتَ الحِراسَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20145, 'حَجْمٌ', 'حجم', 'مصدر', 'حجم', 'حجم', 'حجم', 'مص. حَجَمَ', '', '', 'مفرد', 'DnN', '', '', '"حُجومٌ:أَحْجامٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَجَمَ). 1.""كِتابٌ مِنَ الحَجْمِ الْمُتَوَسِّطِ"" : مَقاسُهُ مُتَوَسِّطٌ. 2.""رَجُلٌ كَبيرُ الحَجْمِ"" : ضَخْمُ الجِسْمِ. 3.""حَجْمُ شَكْلٍ هَنْدَسِيٍّ"" : الحَيِّزُ الَّذِي يَشْغَلُهُ مِنَ الفَراغِ الْمُكَوِّنِ لَهُ : المِتْرُ الْمُكَعَّبُ أَوْ قِياسُ السَّوائِلِ والْمَوادِّ الجافَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20146, 'حُجومٌ', 'حجوم', 'مصدر', '', 'حجوم', 'حجم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20147, 'أَحْجامٌ', 'أحجام', 'مصدر', '', 'ءحجام', 'حجم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20148, 'حِدادٌ', 'حداد', 'مصدر', 'حدد', 'حداد', 'حدد', 'مص. حَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حِدادٌ-حِدادٌ [ح د د] (مص. حَدَّ). 1.""لَبِسَتِ الْمَرْأَةُ الحِدادَ بَعْدَ وَفاةِ زَوْجِها"" : اِرْتِداءُ ثِيابِ الحُزْنِ إِمَّا بَيْضاءَ وَإِمَّا سَوْداءَ حَسَبَ الْمَناطِقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20149, 'تَحْدِيدٌ', 'تحديد', 'مصدر', 'حدد', 'تحديد', 'تحدد', 'مص. حَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْدِيدٌ-تَحْدِيدٌ [ح د د] (مص. حَدَّدَ). 1.""يَنْبَغِي تَحْدِيدُ الْمَوْضُوعِ"" : تَعْيِينُ عَنَاصِرِهِ. 2.""عَلَى وَجْهِ التَّحْدِيدِ"" : التَّدْقِيقِ. 3.""تَحْديدُ النّسْلِ"" : حَصْرُهُ. 4.""تَحْديدُ الحدودِ"" : رَسْمُها، تَعْيِينُها، وَضْعُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20150, 'حُدودٌ', 'حدود', 'مصدر', '', 'حدود', 'حدد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20151, 'حِدَّةٌ', 'حدة', 'مصدر', 'حدد', 'حدة', 'حدة', 'مص.حَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حِدَةٌ-حِدَةٌ [و ح د] (مص. وَحَدَ). 1.""يَظَلُّ على حِدَتِهِ"" : مُتَمَيِّزاً عَنْ غَيْرِهِ. 2.""اُتْرُكْ هَذا الأمْرَ على حِدَةٍ"" : جانِباً. 3.""فَعَلَ ما فَعَلَ على ذاتِ حِدَتِهِ"" : مِنْ تِلْقاءِ نَفْسِهِ، مِنْ ذاتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20152, 'تَحْدِيبٌ', 'تحديب', 'مصدر', 'حدب', 'تحديب', 'تحدب', 'مص. حَدَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْدِيبٌ-تَحْدِيبٌ [ح د ب] (مص. حَدَّبَ). 1.""هَكَذَا أَرَادَ اللهُ تَحْدِيبَهُ"" : جَعْلَهُ أَحْدَبَ. 2.""تَحْدِيبُ الخَشَبِ"" : جَعْلُهُ مُحْدَوْدِباً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20153, 'حَدَبٌ', 'حدب', 'مصدر', 'حدب', 'حدب', 'حدب', 'مص. حَدِبَ', '', '', 'مفرد', 'DnN', '', '', '"أَحْدابٌ:حِدابٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَدِبَ). 1.""حَدَبُ الظَّهْرِ"" : خُروجُ نُتوءٍ فيهِ. 2.""حَدَبُ الماءِ"": ما ارْتَفَعَ مِنْ مَوْجِهِ. 3.""حَدَبُ الشِّتاءِ"" : شِدَّةُ بَرْدِهِ. 4.:ما ارْتَفَعَ وَغَلُظَ مِنَ الأَرْضِ. ¨ الأنبياء آية 96وَهُمْ مِنْ كُلِّ حَدَبٍ يَنْسِلُونَ . (قرآن). 5.""جاءَ الجُمْهورُ مِنْ كُلِّ حَدَبٍ وَصَوْبٍ"" : مِنْ كُلِّ الجِهاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20154, 'أَحْدابٌ', 'أحداب', 'مصدر', '', 'ءحداب', 'حدب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20155, 'حِدابٌ', 'حداب', 'مصدر', '', 'حداب', 'حدب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20156, 'تَحْدِيثٌ', 'تحديث', 'مصدر', 'حدث', 'تحديث', 'تحدث', 'مص. حَدَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَحْدِيثٌ-تَحْدِيثٌ [ح د ث] (مص. حَدَّثَ). 1.""يَنْبَغِي تَحْدِيثُ النَّاسِ بِمَا يَنْفَعُهُمْ"" : تَكْلِيمُهُمْ، إِخْبَارُهُمْ. 2.""تَحْدِيثُ الأَطْفاَلِ بِحِكَايَاتٍ عَجِيبَةٍ"" : رِوَايَتُهَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20157, 'حُدوثٌ', 'حدوث', 'مصدر', 'حدث', 'حدوث', 'حدث', 'مص. حَدَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حُدوثُ-حُدوثُ [ح د ث] (مص. حَدَثَ). ""يَنْتَظِرُ حُدوثَ أَمْرٍ مَّا"" : ظُهورَهُ، اِنْكِشافَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20158, 'حَداثَةٌ', 'حداثة', 'مصدر', 'حدث', 'حداثة', 'حدثة', 'مص. حَدُثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَداثَةٌ-حَداثَةٌ [ح د ث] (مص. حَدُثَ). 1.""حالَتْ حَداثَةُ سِنِّهِ على..."" : صِغَرُ سِنِّهِ، أَوَّلُ عُمْرِهِ. 2.""حَداثَةُ الأُمورِ"" : أَوَّلُها، اِبْتِداؤُها. 3.""الحَداثَةُ في الفَنِّ والأدَبِ"" : الْمُعاصَرَةُ وَتَبَنِّي أَشْكالٍ وَأَساليبَ حَديثَةٍ في الكِتابَةِ تُلائِمُ مَفاهِيمَ العَصْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20159, 'حَرارَةٌ', 'حرارة', 'مصدر', 'حرر', 'حرارة', 'حررة', 'مص. حَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَرارَةٌ-حَرارَةٌ [ح ر ر] (مص. حَرَّ). 1.""اِشْتَدَّتِ الحَرارَةُ"" : السُّخونَةُ. 2.""ميزانُ الحَرارَةِ"" : آلَةٌ لِمَعْرِفَةِ مَدَى ارْتِفاعِ الحَرِّ في جِسْمِ الإِنْسانِ. 3.""عَرَفَ جِسْمُهُ ارْتِفاعاً في الحَرارَةِ"" : اِرْتِفاعُ دَرَجِةِ الحُمَّى. 4.""اِسْتَقْبَلَهُ بِحَرارَةٍ"" : بِشَوْقٍ زائِدٍ وَعاطِفَةٍ ظاهِرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20160, 'حَدَرٌ', 'حدر', 'مصدر', 'حدر', 'حدر', 'حدر', 'مص. حَدِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَدَرٌ-حَدَرٌ [ح د ر] (مص. حَدِرَ). 1.""بِهِ حَدَرٌ"" : بِهِ حَوَلٌ. 2.: ما ارْتَفَعَ مِنَ الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20161, 'حَدْسٌ', 'حدس', 'مصدر', 'حدس', 'حدس', 'حدس', 'مص. حَدَسَ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"حَدْسٌ-حَدْسٌ [ح د س] (مص. حَدَسَ). ""مُجَرَّدُ حَدْسٍ"" : إِدْرَاكُ الأَشْيَاءِ مِنْ خِلاَلِ شُعُورٍ دَاخِلِيٍّ يَحِسُّ بِهِ الْمَرْءُ مِنْ دُونِ مَعْرِفَةٍ سابِقَةٍ. ""تَخَيَّلْ حالَ مَنْ خُلِقَ مَكْفوفَ البَصَرِ إِلاَّ أَنَّهُ جَيِّدُ الفِطْرَةِ قَوِيُّ الحَدْسِ"".(ابن طفيل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20162, 'تَحْدِيقٌ', 'تحديق', 'مصدر', 'حدق', 'تحديق', 'تحدق', 'مص. حَدَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْدِيقٌ-تَحْدِيقٌ [ح د ق] (مص. حَدَّقَ). 1.""اِسْتَمَرَّ تَحْدِيقُهُ إِلَيْهِ زَمَناً طَوِيلاً"" : إِمْعَانُ النَّظَرِ وَتَسْدِيدُهُ. 2.""التَّحْدِيقُ بِالشَّيْءِ"" : الإحداقُ بِهِ، الإِحَاطَةُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20163, 'حَدْمٌ', 'حدم', 'مصدر', 'حدم', 'حدم', 'حدم', 'مص. حَدَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَدْمٌ-حَدْمٌ [ح د م] (مص. حَدَمَ). ""حَدْمُ الشَّيْءِ"" : شِدَّةُ إِحْمائِهِ بِالنَّارِ أَوْ بِحَرِّ الشَّمْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20164, 'حَذْوٌ', 'حذو', 'مصدر', 'حذو', 'حذو', 'حذ', 'مص. حَذا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَذْوٌ-حَذْوٌ [ح ذ و] (مص. حَذا). ""حَذا حَذْوَهُ"" : سارَ على مِثالِهِ. ""وَبَقِيَ الآنَ أَنْ نَعْرِفَ الصِّدْقَ مَعَ أَوانِهِ وَمَكانِهِ... وَكَذَلِكَ الكَذِبَ على حَذْوِهِ وَمِثالِهِ"".(التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20165, 'تَحْذِيرٌ', 'تحذير', 'مصدر', 'حذر', 'تحذير', 'تحذر', 'مص. حَذَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. حَذَّرَ). 1.""وَجَّهَ لَهُ تَحْذِيرًا صَارِماً"" : تَنْبِيهاً، تَخْوِيفاً. 2.: التَّحْذِيرُ فِي النَّحْوِ هُوَ أُسْلُوبٌ يُرَادُ بِهِ تَنْبِيهُ الْمُخَاطَبِ لِيَتَجَنَّبَ مَكْرُوهاً يُمْكِنُ أَنْ يَقَعَ فِيهِ : ""إِيَّاكَ وَالكَذِبَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20166, 'حَذَرٌ', 'حذر', 'مصدر', 'حذر', 'حذر', 'حذر', 'مص.حَذِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَذَرٌ-حَذَرٌ [ح ذ ر] (مص.حَذِرَ). 1.""كُنْ على حَذَرٍ يا وَلَدِي مِنَ الأَشْرارِ"" : على احْتِراسِ. 2.""خُذْ حذَرَكَ"" : عَلَيْكَ بِاليَقَظَةِ. ""اِلْتَزَمَ الحَذَرَ"" ""اِلْتَزَمَ جانِبَ الحَذَرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20167, 'تَحْذِيقٌ', 'تحذيق', 'مصدر', 'حذق', 'تحذيق', 'تحذق', 'مص. حَذَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْذِيقٌ-تَحْذِيقٌ [ح ذ ق] (مص. حَذَّقَ). ""تَحْذِيقُ الصَّانِعِ"" : جَعْلُهُ حَاذِقاً مَاهِراً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20168, 'حِذْقٌ', 'حذق', 'مصدر', 'حذق', 'حذق', 'حذق', 'مص.حَذَقَ، حَذِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حِذْقٌ-حِذْقٌ [ح ذ ق] (مص.حَذَقَ، حَذِقَ). ""يَمْتازُ بِالحِذْقِ في عَمَلِهِ"" : بِالْمَهارَةِ في عَمَلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20169, 'تَحْرِيزٌ', 'تحريز', 'مصدر', 'حرز', 'تحريز', 'تحرز', 'مص. حَرَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْرِيزٌ-تَحْرِيزٌ [ح ر ز] . (مص. حَرَّزَ). 1.""تَحْرِيزُ الثَّرْوَةِ"" : الْمُبَالَغَةُ فِي حِفْظِهَا. 2.""تَحْرِيزُ القَطِيعِ بِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20170, 'حَرٌّ', 'حر', 'مصدر', 'حرر', 'حر', 'حر', 'مص. حَرَّ', '', '', 'مفرد', 'DnN', '', '', '"حُرورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَرَّ). ""اِشْتَدَّ حَرُّ الصَّيْفِ"" : سُخونَتُهُ، حَرارَتُهُ عَكْسَ البَرْدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20171, 'حُرورٌ', 'حرور', 'مصدر', '', 'حرور', 'حرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20172, 'حَراً', 'حرا', 'مصدر', 'حرو', 'حرا', 'حر', 'مص. حَرَا', '', '', 'مفرد', 'DnN', '', '', '"أَحْرَاءُ"', '', '', '', '', '', '', '', '', '"(مص. حَرَا). 1.""هُمْ حَرَا أَنْ يَفْعَلُوا ذَلِكَ"": حَرِيٌّ، جَدِيرٌ، خَلِيقٌ. 2.""حَرَا الدَّارَةِ"" : سَاحَتُهَا. 3.""حَرَا الظِّبَاءِ"" : مَأْوَاهَا. 4.""حَرَا السُّوقِ"" : ضَجَّتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20173, 'أَحْرَاءُ', 'أحراء', 'مصدر', '', 'ءحراء', 'حر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20174, 'حَرْبٌ', 'حرب', 'مصدر', 'حرب', 'حرب', 'حرب', 'مص. حَرَبَ', '', '', 'مفرد', 'DnN', '', '', '"حُروبٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. حَرَبَ). 1.""اِنْدَلَعَتِ الحَرْبُ بَيْنَ البَلَدَيْنِ"" : اِشْتَعَلَتْ نيرانُ الْمَدافِعِ والقَذائِفِ بِالدَّبَّاباتِ والطَّائِراتِ وَما شابَهَ ذَلِكَ، القِتالُ بِالسُّيوفِ والرِّماحِ قَديماً. 2.""خاضَ الشَّعْبُ العَرَبِيُّ حَرْبَ تَحْريرٍ شَعْبِيَّةً ضِدَّ الاحْتِلالِ"" : مَعْرَكَة التَّحْريرِ. 3.""اِنْدَلَعَتْ حَرْبٌ أَهْلِيَّةٌ في لُبْنانَ"" : النِّزاعُ الْمُسَلَّحُ الَّذِي يَحْدُثُ بَيْنَ سُكَّانِ البَلَدِ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20175, 'حُروبٌ', 'حروب', 'مصدر', '', 'حروب', 'حرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20176, 'حَرْثٌ', 'حرث', 'مصدر', 'حرث', 'حرث', 'حرث', 'مص. حَرَثَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَرْثٌ-حَرْثٌ [ح ر ث] (مص. حَرَثَ). 1.""آنَ أَوانُ الحَرْثِ"": أَوانُ الزَّرْعِ، الغَرْسِ. 2.""الحَرْثُ"" : يُطْلَقُ على شَهْرِ نوفمبر حَسَبَ اليَوْمِيَّةِ اللِّيبِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20177, 'حَرَجٌ', 'حرج', 'مصدر', 'حرج', 'حرج', 'حرج', 'مص. حَرِجَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَرِجٌ-حَرِجٌ [ح ر ج] (صيغةُ فَعِل). ""وَقَعَ في مَوْقِفٍ حَرِجٍ"" : في مَوْقِفٍ صَعْبٍ، في مَأْزِقٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20178, 'تَحْرِيرٌ', 'تحرير', 'مصدر', 'حرر', 'تحرير', 'تحرر', 'مص. حَرَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْرِيرٌ-تَحْرِيرٌ [ح ر ر] . (مص. حَرَّرَ). 1.""هَذِهِ الرِّسَالَةُ مِنْ تَحْرِيرِهِ"" : مِنْ إِنْشَائِهِ. 2.""تَوَلَّى إِدَارَةَ تَحْرِيرِ الْمَجَلَّةِ"" : مَنْ يُشْرِفُ عَلَيْهَا أَدَبِيّاً وَيُرَاقِبُ مُعَامَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20179, 'حِرْصٌ', 'حرص', 'مصدر', 'حرص', 'حرص', 'حرص', 'مص.حَرَصَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حِرْصٌ-حِرْصٌ [ح ر ص] (مص.حَرَصَ). 1.""اِشْتَدَّ حِرْصُهُ على حُضورِ الوَليمَةِ"" : جَشَعُهُ، شَرَهُهُ. 2.""حِرْصاً على سَلامَتِهِ"": أيْ رَغْبَةً فب..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20180, 'حَرَزٌ', 'حرز', 'مصدر', 'حرز', 'حرز', 'حرز', 'مص. حَرِزَ.', '', '', 'مفرد', 'DnN', '', '', '"أَحْرازٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَحْرازٌ. (مص. حَرِزَ). كل ما يُذَّخَرُ وَيُصانُ وَيُحْرَزُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20181, 'أَحْرازٌ', 'أحراز', 'مصدر', '', 'ءحراز', 'حرز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20182, 'حِراسَةٌ', 'حراسة', 'مصدر', 'حرس', 'حراسة', 'حرسة', 'مص. حَرَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حِراسَةٌ-حِراسَةٌ [ح ر س] (مص. حَرَسَ). 1.""مَسْؤُولٌ عَنِ الحِراسَةِ"" : عَنِ الْمُراقَبَةِ. 2.""أَمانَتُهُ في حِرا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20183, 'حَرْسٌ', 'حرس', 'مصدر', 'حرس', 'حرس', 'حرس', 'مص. حَرَسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَرَسٌ-حَرَسٌ (بِصيغَةِ الجَمْعِ) [ح ر س] (مص.حَرِسَ). 1.""حَرَسُ القَلْعَةِ"" : الَّذينَ يَقومونَ بِالحِراسَةِ، بِالْمُراقَبَةِ، الحُرَّاسُ.الجن آية 8 وَإِنَّا لَمَسْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20184, 'حَرَسٌ', 'حرس', 'مصدر', 'حرس', 'حرس', 'حرس', 'مص.حَرِسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَرْسٌ-حَرْسٌ[ح ر س] (مص. حَرَسَ). ""عا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20185, 'تَحْرِيشٌ', 'تحريش', 'مصدر', 'حرش', 'تحريش', 'تحرش', 'مص. حَرَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْرِيشٌ-تَحْرِيشٌ [ح ر ش] . (مص. حَرَّشَ). ""نَهَاهُ عَنِ التَّحْرِيشِ بَيْنَ النَّاسِ"" : إِغْرَاءُ بَعْضِهِمْ بِبَعْضٍ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20186, 'حَرْشٌ', 'حرش', 'مصدر', 'حرش', 'حرش', 'حرش', 'مص. حَرَشَ', '', '', 'مفرد', 'DnN', '', '', '"حِراشٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَرَشَ). 1.""حَرْشُ جُرْحٍ"" : أَثَرُهُ. 2.""أَوْقَعَهُ في حَرْشٍ"" : في خَديعَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20187, 'حِراشٌ', 'حراش', 'مصدر', '', 'حراش', 'حرش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20188, 'حَرَشٌ', 'حرش', 'مصدر', 'حرش', 'حرش', 'حرش', 'مص.حَرِشَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَرَشٌ-حَرَشٌ [ح ر ش] (مص.حَرِشَ). ""ثَوْبٌ حَرَشٌ"" : بِهِ خُشونَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20189, 'حَرَقٌ', 'حرق', 'مصدر', 'حرق', 'حرق', 'حرق', 'مص. حَرِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَرَقٌ-حَرَقٌ [ح ر ق] (مص. حَرِقَ). 1.""اِشْتَعَلَ الحَرَقُ"" : النَّارُ، لَهَبُها. 2.""تَرَكَ الحَريقُ حَرَقاً"" : أَثَرَ الاِحْتِراقِ. 3.""ثَوْبٌ بِهِ حَرَقٌ"" : الأَثَرُ الَّذِي يُصيبُ الثَّوْبَ مِنَ النَّارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20190, 'تَحْرِيضٌ', 'تحريض', 'مصدر', 'حرض', 'تحريض', 'تحرض', 'مص. حَرَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْرِيضٌ-تَحْرِيضٌ [ح ر ض] (مص. حَرَّضَ). ""اُتُّهِمَ بِتَحْرِيضِ النَّاسِ عَلَى الشَّغَبِ"" : دَفْعُهُمْ لإِثَارَةِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20191, 'تَحْرِيفٌ', 'تحريف', 'مصدر', 'حرف', 'تحريف', 'تحرف', 'مص. حَرَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْرِيفٌ-تَحْرِيفٌ [ح ر ف] (مص. حَرَّفَ). ""تَحْرِيفُ الكَلاَمِ عَنْ مَوَاضِعِهِ"" : تَغْيِيرُهُ وَتَبْدِيلُهُ وَإِعْطَاؤُهُ تَفْسِيرًا مُغَايِراً لِمَقَاصِدِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20192, 'حَرْفٌ', 'حرف', 'مصدر', 'حرف', 'حرف', 'حرف', 'مص. حَرَفَ', '', '', 'مفرد', 'DnN', '', '', '"حُروفٌ:أَحْرُفٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَرَفَ). 1.""وَقَفَ على حَرْفِ الجَبَلِ"" : على حافَتِهِ العُلْيا.الحج آية 11 وَمِنَ النَّاسِ مَنْ يَعْبُدُ اللَّهَ على حَرْفٍ .(قرآن). 2.""جَلَسَ الصَّيَّادُ على حَرْفِ النَّهْرِ"" : على جانِبِهِ. 3.""يَبْلُغُ عَدَدُ حُروفِ هِجاءِ اللُّغَةِ العَرَبِيَّةِ ثَمانِيَةً وَعِشْرينَ حَرْفاً هي: ا ب ت ث ج ح خ د ذ ر ز س ش ص ض ط ظ ع غ ف ق ك ل م ن هـ و ي. وَهُوَ ما يُسَمَّى بِحُروفِ الْمَبانِي. 4.""الكَلامُ لَفْظٌ مُرَكَّبٌ وَأَقْسامُهُ : اِسْمٌ وَفِعْلٌ وَحَرْفٌ"" : الحَرْفُ هُوَ ما دَلَّ على مَعْنَى في غَيْرِهِ، والحُروفُ هِيَ: أ. أُحادِيَّةٌ: الباءُ والتَّاءُ والسِّينُ والغَيْنُ والكافُ واللاَّمُ والواوُ. وَكُلُّ حَرْفٍ مِنْ هَذِهِ الحُروفِ لَهُ مَعْناهُ وَعَمَلُهُ (ن. المعجم). ب. ثُنائِيَّةٌ: أل، أَمْ، أَنْ، إِنْ، أَوْ، أَيْ، بَلْ، عَنْ، في، قَدْ، كَيْ، لا، لَمْ، لَوْ، ما، وَا. ج.حُروفُ العِلَّةِ وَهِيَ: ا، و، ي. 5.""والحُروفُ قِسْمانِ: أ.حُروفٌ عامِلَةٌ: وَهِيَ ما أَحْدَثَتْ إِعْراباً وَتَغْيِيراً في غَيْرِها مِنَ الكَلِماتِ بِحُروفِ الجَرِّ والنَّصْبِ والجَزْمِ ""وَإِنْ"" الشَّرْطِيَّة، والأحْرُفِ الْمُشَبَّهَةُ بِالف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20193, 'حُروفٌ', 'حروف', 'مصدر', '', 'حروف', 'حرف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20194, 'أَحْرُفٌ', 'أحرف', 'مصدر', '', 'ءحرف', 'حرف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20195, 'حَرافَةٌ', 'حرافة', 'مصدر', 'حرف', 'حرافة', 'حرفة', 'مص.حَرُفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَرافَةٌ-حَرافَةٌ [ح ر ف] (مص.حَرُفَ). ""طَعامٌ بِهِ حَرافَةٌ"" : بِهِ حِدَّةُ طَعْمٍ تَلْذَعُ اللِّسانَ أَوِ الفَمَ بِقُوَّةٍ وَتَقْرِصُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20196, 'تَحْرِيقٌ', 'تحريق', 'مصدر', 'حرق', 'تحريق', 'تحرق', 'مص. حَرَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْرِيقٌ-تَحْرِيقٌ [ح ر ق] (مص. حَرَّقَ). 1.""تَحْرِيقُهُ بِالنَّارِ"" : حَرْقُهُ، إِحْرَاقُهُ. 2.""تَحْرِيقُ قَلْبِهِ"" : إِلْهَابُهُ، إِحْدَاثُ تَأْثِيرٍ بَالِغٍ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20197, 'حَرْقٌ', 'حرق', 'مصدر', 'حرق', 'حرق', 'حرق', 'مص. حَرَقَ', '', '', 'مفرد', 'DnN', '', '', '"حُروقٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَرَقَ). 1.""مَا يَزَالُ يَحْمِلُ آثَارَ الحَرْقِ"" : أيْ أثَارَ الاحْتِرَاقِ. 2. ""أشُمُّ مِنْ بَعِيدٍ رَائِحَةَ حَرْقِ الأعْشَابِ"" : أي احْتِرَاقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20198, 'حُروقٌ', 'حروق', 'مصدر', '', 'حروق', 'حرق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20199, 'تَحْرِيكٌ', 'تحريك', 'مصدر', 'حرك', 'تحريك', 'تحرك', 'مص. حَرَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْرِيكٌ-تَحْرِيكٌ [ح ر ك] . (مص. حَرَّكَ). 1.""تَحْرِيكُ الأَصَابِعِ"" : مَلْمَلَتُهَا، جَعْلُهَا تَتَحَرَّكُ. 2.""تَحْرِيكُ الكَلِمَةِ"" : وَضْعُ الحَرَكَاتِ عَلَى أَحْرُفِهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20200, 'تَحْرِيمٌ', 'تحريم', 'مصدر', 'حرم', 'تحريم', 'تحرم', 'مص. حَرَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْرِيمٌ-تَحْرِيمٌ [ح ر م] . (مص. حَرَّمَ). 1.""تَحْرِيمُ القِمَارِ"" : مَنْعُهُ. 2.""سُورَةُ التَّحْرِيمِ"" : مِنْ سُوَرِ القُرْآنِ الكَرِيمِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20201, 'حِرْمَانٌ', 'حرمان', 'مصدر', 'حرم', 'حرمان', 'حرمن', 'مص. حَرَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حِرْمَانٌ-حِرْمَانٌ [ح ر م] (مص. حَرَمَ). 1.""يَعِيشُ فِي حِرْمَانٍ"": فِي بُؤْسٍ. 2.""حِرْمَانُ الذَّاتِ مِنَ الشَّهَوَاتِ"" : مَنْعُهَا. 3.""حِرْمَانُهُ مِنَ العَمَلِ أدَّى بِهِ إلَى التَّسَكُّعِ"" : عَدَمُ الحُصُولِ عَلَى عَمَلِ الرِّزْقِ. 4.""أَدَّتْ بِهِ جَرَائِمُهُ إلَى حِرْمَانِهِ مِنْ حُقُوقِهِ الْمَدَنِيَّةِ"" : ضَيَاعُ حُقُوقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20202, 'حِرْمٌ', 'حرم', 'مصدر', 'حرم', 'حرم', 'حرم', 'مص. حَرَمَ', '', '', 'مفرد', 'DnN', '', '', '"حُرُمٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَرَمَ). ""دَخَلَ الحَجَّاجُ فِي الحِرْمِ"" : زَمَانُ الإحْرَامِ، الواجبُ الَّذي لاَ يَجِبُ تَرْكُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20203, 'حُرُمٌ', 'حرم', 'مصدر', '', 'حرم', 'حرم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20204, 'حَرِيمٌ', 'حريم', 'مصدر', 'حرم', 'حريم', 'حرم', 'مص. حَرَمَ', '', '', 'مفرد', 'DnN', '', '', '"حُرُمٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَرَمَ). 1.""مَكَانٌ حَرِيمٌ"" : مُقَدَّسٌ يَحْرُمُ انْتِهَاكُهُ. 2.""شَدِيدُ الحِرْصِ عَلَى حَرِيمِهِ"": مَا يُدَافِعُ عَنْهُ الإنْسَانُ وَيَحْمِيهِ. 3.""يُرَاقِبُ حَرِيمَهُ"": نِسَاء الرَّجُلِ. 4.""دَخَلَتِ النِّسَاءُ لِلْحَرِيمِ"" : مَوْضِع إقَامَةِ النِّسَاءِ فِي قَصْرِ الْمُلُوكِ وَالأُمَرَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20205, 'حُرُمٌ', 'حرم', 'مصدر', '', 'حرم', 'حرم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20206, 'حُرْمٌ', 'حرم', 'مصدر', 'حرم', 'حرم', 'حرم', 'مص. حَرُمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حُرْمٌ-حُرْمٌ [ح ر م] (مص. حَرُمَ). : الإحْرَامُ بِالحَجِّ وَيُقابِلُهُ الحِلُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20207, 'حَرَمٌ', 'حرم', 'مصدر', 'حرم', 'حرم', 'حرم', 'مص. حَرِمَ', '', '', 'مفرد', 'DnN', '', '', '"أحْرَامٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَرِمَ). مَكَانٌ مُقَدَّسٌ لاَ يَحِلُّ انْتِهَاكُهُ. 1.""اِنْتَهَكَ الإسْرَائِيلِيُّونَ الحَرَمَ الأقْصَى"" : بَيْت الْمَقْدِسِ. 2.""وَقَفَ الحُجَّاجُ أمَامَ حَرَمِ مَكَّةَ"" : العَتَبَةُ. القصص آية 57 أَوَ لَمْ نُمَكِّنْ لَهُمْ حَرَماً آمِناً تُجْبَى إلَيْهِ ثَمَراتُ كُلِّ شَيْءٍ (قرآن). 3.""زَارَ الحَجَّاجُ الحَرَمَيْنِ"" : أَيْ مَكَّةَ وَالْمَدِينَةَ. 4.""حَرَمُ الرَّجُلِ"" : زَوْجَتُهُ، مَا يَحْمِيهِ الرَّجُلُ وَيُقاتِلُ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20208, 'أحْرَامٌ', 'أحرام', 'مصدر', '', 'ءحرام', 'حرم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20209, 'تَحْزِيبٌ', 'تحزيب', 'مصدر', 'حزب', 'تحزيب', 'تحزب', 'مص. حَزَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْزِيبٌ-تَحْزِيبٌ [ح ز ب] . (مص. حَزَّبَ). 1.""تَحْزِيبُ القَوْمِ"" : جَمْعُهُمْ وَتَقْوِيَتُهُمْ. 2.""تَحْزِيبُ الجَمَاهِيرِ"" : جَعْلُهَا أَحْزَاباً. 3.""حَاوَلَ تَحْزِيبَهُ"" : جَعْلَهُ مِنْ حِزْبِهِ. 4.""تَحْزِيبُ القُرْآنِ"" : جَعْلُهُ أَحْزَاباً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20210, 'حَزْمٌ', 'حزم', 'مصدر', 'حزم', 'حزم', 'حزم', 'مص.حَزَمَ، حَزُمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَزْمٌ-حَزْمٌ [ح ز م] (مص.حَزَمَ، حَزُمَ). ""عُرِفَ بِالحَزْمِ"" : عُرِفَ بِضَبْطِ الأُمُورِ وَإحْكَامِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20211, 'تَحْزِينٌ', 'تحزين', 'مصدر', 'حزن', 'تحزين', 'تحزن', 'مص. حَزَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْزِينٌ-تَحْزِينٌ [ح ز ن] (مص. حَزَّنَ). ""تَحْزِينُ الرَّجُلِ"" : جَعْلُهُ مَغْمُوماً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20212, 'حُزْنٌ', 'حزن', 'مصدر', 'حزن', 'حزن', 'حزن', 'مص. حَزَنَ', '', '', 'مفرد', 'DnN', '', '', '"أحْزَانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَزَنَ). ""أظْهَرَ حُزْناً شَدِيداً"" : ألَماً، كَآبَةً، غَمّاً. يوسف آية 84وابْيَضَّتْ عَيْنَاهُ مِنَ الحُزْنِ .(قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20213, 'أحْزَانٌ', 'أحزان', 'مصدر', '', 'ءحزان', 'حزن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20214, 'حَزَنٌ', 'حزن', 'مصدر', 'حزن', 'حزن', 'حزن', 'مص.حَزِنَ', '', '', 'مفرد', 'DnN', '', '', '"أحزَانٌ"', '', 'R', '', '', '', '', '', '', '"(مص.حَزِنَ). ""اُجْلُ الحَزَنَ عَنْ نَفْسِكَ"" : الهَمَّ، الحُزْنَ. فاطر آية 34 الحَمْدُ لِلَّهِ الَّذِي أذْهَبَ عَنَّا الحَزَنَ .(قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20215, 'أحْزَانٌ', 'أحزان', 'مصدر', '', 'ءحزان', 'حزن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20216, 'حِسٌّ', 'حس', 'مصدر', 'حسس', 'حس', 'حس', 'مص. حَسَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حِسٌّ-حِسٌّ [ح س س] (مص. حَسَّ). 1.""سَمِعَ حِسّاً خَارِجَ البَيْتِ"" : صَوْتاً أَوْ حَرَكَةً خَفِيَّةً. 2.""مَا يُدْرِكُهُ الْمَرْءُ بِإحْدَى حَوَاسِّهِ الخَمْسِ. 3.""مَا سَمِعْتُ لَهُ حِسّاً"" : خَبَراً. 4.""اِشْتَدَّ عَلَيْها الحِسُّ"" : ألَمٌ يُصِيبُ الْمَرأةَ بَعْدَ الوِلاَدَةِ. 5.""أصَابَ الحِسُّ الزَّرْعَ"" : بَرْدٌ يَحْرِقُ الزَّرْعَ. 6.""بَيْنَهُمَا حِسٌّ مُشْتَرَكٌ"" : شُعُورٌ. 7.""يَتَمَتَّعُ بِحِسٍّ فَنِّيٍّ مُرْهَفٍ"" : الإِدْرَاكُ الفَنِّيُّ، الإحْسَاسُ الفَنِّيُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20217, 'حُسْبَانٌ', 'حسبان', 'مصدر', 'حسب', 'حسبان', 'حسبن', 'مص. حَسَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حِسْبَانٌ-حِسْبَانٌ [ح س ب] (مص. حَسَبَ). ""مَا كَانَ ذَلِكَ فِي حِسْبَانِي"" : فِي ظَنِّي، أيْ لَمْ يَكُنْ ذَلِكَ مُرْتَقَباً وَمُنْتظَراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20218, 'حِسْبَانٌ', 'حسبان', 'مصدر', 'حسب', 'حسبان', 'حسبن', 'مص. حَسَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حُسْبَانٌ-حُسْبَانٌ [ح س ب] (مص. حَسَبَ). 1.""حُسْبَانُ الأمْرِ"" : تَدْبِيرُهُ تَدْبِيراً دَقِيقاً. الرحمن آية 5 والشَّمْسُ وَالقَمَرُ بِحُسْبَانٍ .(قرآن). 2. الكهف آية 40 وَيُرْسِلُ عَلَيْها حُسْباناً مِنَ السَّماءِ . (قرآن) : الصَّواعِقَ، العَذابَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20219, 'حَسَفٌ', 'حسف', 'مصدر', 'حسف', 'حسف', 'حسف', 'مص. حَسِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَسَفٌ-حَسَفٌ [ح س ف] (مص. حَسِفَ). ""حَسَفُ النَّبَاتِ"": شَوْكُهُ، حَسْفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20220, 'حِسْبَةٌ', 'حسبة', 'مصدر', 'حسب', 'حسبة', 'حسبة', 'مص. حَسَبَ', '', '', 'مفرد', 'DnN', '', '', '"حِسَبٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَسَبَ). 1.""قَدَّرَ حِسْبَتَهُ"" : حِسَابَهُ، مُكَافَأَتَهُ. 2.""رَجُلٌ حَسَنُ الحِسْبَةِ فِي الأمْرِ"" : يُحْسِنُ تَدْبِيرَهُ. 3. ""فَعَلَهُ حِسْبَةً"" : مُدَّخِراً أجْرَهُ عِنْدَ اللَّهِ. 4.""تَوَلَّى الحِسْبَةَ"" : مَنْصِبٌ كانَ يَتَولاَّهُ فِي الدُّوَلِ الإسْلاَمِيَّةِ رَئِيسٌ يُشْرِفُ عَلَى مُرَاقَبَةِ الأسْعَارِ وَرِعَايَةِ الآدَاب."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20221, 'حِسَبٌ', 'حسب', 'مصدر', '', 'حسب', 'حسب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20222, 'حَسَبٌ', 'حسب', 'مصدر', 'حسب', 'حسب', 'حسب', 'مص.حَسُبَ', '', '', 'مفرد', 'DnN', '', '', '"أحْسَابٌ"', '', 'R', '', '', '', '', '', '', '"(مص.حَسُبَ). 1.""هُوَ ذُو حَسَبٍ وَكَرَمٍ"" : ذُو شَرَفٍ، مِنْ أَهْلٍ شَرِيفٍ. 2.""هَيَّأَ الحَفْلَةَ حَسَبَ الأُصُولِ"" : وَفْقَ. 3. ""حَسَبَ أقْوَالِهِ"" : بِمُقْتَضَى، بِمُوجِبِ أَقْوَالِهِ. 4. ""اِجْتَهَدَ حَسَب إمْكَاناتِهِ"" : حَسَبَ قُدُراتِهِ. ""أَجْرُكَ بِحَسَبِ عَمَلِكَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20223, 'أحْسَابٌ', 'أحساب', 'مصدر', '', 'ءحساب', 'حسب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20224, 'حِسَابٌ', 'حساب', 'مصدر', 'حسب', 'حساب', 'حسب', 'مص. حَسَبَ، حَاسَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حِسَابٌ-حِسَابٌ [ح س ب] (مص. حَسَبَ، حَاسَبَ). 1.""مَادَّةُ الحِسَابِ"" : العَدُّ، عَمَلِيَّةُ جَمْعِ الأرْقَامِ، الأعْدَادِ، طَرْحُهَا أوْ ضَرْبُهَا أوْ قِسْمَتُهَا. 2.""حِسَابُ الْمُثَلَّثَاتِ"" : حِسَابُ أقْيِسَةِ عنَاصِرِ الْمُثَلَّثَاتِ الْمُحَدَّدَةِ بِمُعْطَيَاتٍ عَدَدِيَّةٍ وَتطْبِيقُهَا عَلَى دِراسَةِ الأشْكَالِ الهَنْدَسِيَّةِ. 3.""حِسَابُ الاحْتِمَالاَتِ"" : مَجْمُوعُ القَوَاعِدِ الَّتِي تُمُكِّنُ مِنْ تَحْدِيدِ النِّسْبَةِ الْمُؤَدِّيَةِ لِحُدُوثِ أمْرٍ مَّا. 4.""حِسَابُ التَّكَامُلِ"" : جُزْءٌ مِنَ الحِسَابِ اللاَّمُتَنَاهِي فِي الصِّغَرِ، هَدَفُهُ الحُصُولُ عَلَى التَّابِعِ لِمُشْتَقَّةٍ مَعْلُومَةٍ. 5.""بَارِعٌ فِي الحِسَابِ الذِّهْنِيِّ"" : العَدُّ الذِّهْنِيُّ. 6.""حِسَابُ الجُمَّلِ"" : أرْقَامُ الأحْرُفِ الأَبَجَدِيَّةِ (ن. أبجديَّة). 7.""لَهُ حِسَابٌ جَارٍ فِي البَنْكِ"" : رَصِيدٌ، عَمَلِيَّاتُ الدَّفْعِ وَالسَّحْبِ وَالتَّحْوِيلِ القَائِمَةُ بَيْنَ الزَّبونِ وَالبَنْكِ. ""فَتَحَ حِسَاباً فِي البَنْكِ"". 8. ""دَفَعَ لَهُ أَمْوَالاً بِلاَ حِسَابٍ"" : بِكَثْرَةٍ، بِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20225, 'حَسَدٌ', 'حسد', 'مصدر', 'حسد', 'حسد', 'حسد', 'مص. حَسَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَسَدٌ-حَسَدٌ [ح س د] (مص. حَسَدَ). ""عَبَّرَ عَنْ حَسَدٍ وَاضِحٍ"" : التَّمَنِّي بِزَوَالِ نِعْمَةِ شَخْصٍ مَّا (الْمَحْسُودُ) وَتَحوُّلِهَا إلَيْهِ. ""الحَسَدُ يَأْكُلُ الحَسَنَاتِ كَمَا تَأْكُلُ النَّارُ الحَطَبَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20226, 'تَحْسِيرٌ', 'تحسير', 'مصدر', 'حسر', 'تحسير', 'تحسر', 'مص. حَسَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْسِيرٌ-تَحْسِيرٌ [ح س ر] (مص. حَسَّرَ) . ""تَحْسِيرُ الرَّجُلِ"" : إِيقَاعُهُ فِي الحَسْرَةِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20227, 'تَحْسِيسٌ', 'تحسيس', 'مصدر', 'حسس', 'تحسيس', 'تحسس', 'مص. حَسَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْسِيسٌ-تَحْسِيسٌ [ح س س] (مص. حَسَّسَ). ""تَحْسِيسُهُ بِالذَّنْبِ"" : جَعْلُهُ يُحِسُّ بِهِ لإِدْرَاكِهِ وَالشُّعُورِ بِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20228, 'حَسْفٌ', 'حسف', 'مصدر', 'حسف', 'حسف', 'حسف', 'مص. حَسَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَسْفٌ-حَسْفٌ [ح س ف] (مص. حَسَفَ). ""حَسْفُ النَّبَاتِ"": شَوْكُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20229, 'حَشَمٌ', 'حشم', 'مصدر', 'حشم', 'حشم', 'حشم', 'مص. حَشَمَ', '', '', 'مفرد', 'DnN', '', '', '"أحْشَامٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَشَمَ). 1.""جَلَسَ وَسَطَ حَشَمِهِ"" : أقْرِبَائِهِ، خُدَّامِهِ وَحَاشِيتَهِ، الَّذينَ يَغْضَبُونَ لِغَضَبِهِ وَلِكُلِّ مَا يَمَسُّهُ مِنْ مَكْرُوهٍ. ""خَرَجَ الأمِيرُ واصْطَحَبَ مَعَهُ مَنْ فِي القَصْرِ مِنْ خَدَمٍ وَحَشَمٍ"". (جبرا إبراهيم جبرا). 2.""هُوَ كَثِيرُ الخَدَمِ وَالحَشَمِ"" : أيْ كِنَايَةً عَلَى أَنَّهُ مِنَ الأَغْنِيَاءِ وَكِبَارِ القَوْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20230, 'حَسْمٌ', 'حسم', 'مصدر', 'حسم', 'حسم', 'حسم', 'مص. حَسَمَ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"حَسْمٌ-حَسْمٌ [ح س م] (مص. حَسَمَ). 1.""قَرَّرَ حَسْمَ القَضَايَا الْمُعَلَّقَةِ"" : اِتِّخَاذَ القَرَارِ بِإنْهَائِهَا. 2.""أجْرَى التَّاجِرُ حَسْماً لِمُشْترَيَاتِ زَبُونِهِ"" : إسْقَاطَ نِسْبَةٍ مِئَوِيَّةٍ مِنَ القِيمَةِ الْمَطْلُوبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20231, 'تَحْسِينٌ', 'تحسين', 'مصدر', 'حسن', 'تحسين', 'تحسن', 'مص. حَسَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. حَسَّنَ). ""سَاهَمَ فِي تَحْسِينِ الوَضْعِ الاجْتِمَاعِيِّ"" : أَيْ فِي تَرْقِيَتِهِ وَتَزْيِينِهِ، إِصْلاحِهِ. ""مِنْ أَعْظَمِ الذُّنُوبِ تَحْسِينُ العُيُوبِ"".(مثل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20232, 'حُسْنٌ', 'حسن', 'مصدر', 'حسن', 'حسن', 'حسن', 'مص. حَسُنَ', '', '', 'مفرد', 'DnN', '', '', '"مَحَاسِنُ"', '', 'R', '', '', '', '', '', '', '"(مص. حَسُنَ). 1.""مِنْ حُسْنِ حَظِّهِ"" : مِنْ حَظِّهِ السَّعِيدِ. ""لِحُسْنِ حَظِّهِ"". 2.""مِنْ حُسْنِ الْمُصَادَفَةِ"" : مِنَ الْمُصَادَفَةِ السَّعِيدَةِ. 3.""حُسْنُ القِوَامِ"": جَمَالُهُ وَملاحَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20233, 'مَحَاسِنُ', 'محاسن', 'مصدر', '', 'محاسن', 'محسن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20234, 'حَشْوٌ', 'حشو', 'مصدر', 'حشو', 'حشو', 'حش', 'مص. حَشَا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَشْوٌ-حَشْوٌ [ح ش و] (مص. حَشَا). 1.""إنْشَاءٌ مَلِيءٌ بِالحَشْوِ"" : كَلامٌ زَائِدٌ لاَ فَائِدَةَ مِنْهُ. 2.""طَعَامٌ بِهِ حَشْوٌ"" : مَا يُحْشَى فِي بَعْضِ الخُضَرِ أَوِ اللَّحْمِ أَوِالدَّجَاجِ مِنْ أرُزٍّ وَتَوَابِلَ. 3.""حَشْوُ الوِسَادَةِ"" : مَا تُحْشَى بِهِ مِنْ قُطْنٍ وَنَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20235, 'حَشْدٌ', 'حشد', 'مصدر', 'حشد', 'حشد', 'حشد', 'مص. حَشَدَ', '', '', 'مفرد', 'DnN', '', '', '"حُشُودٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَشَدَ). ""لاَحَظَ حَشْداً مِنَ النَّاسِ"" : جَمَاعَةً مُحْتَشِدَةً، مُجْتَمِعَةً. أعْدادٌ غَفِيرَةٌ مِنَ النَّاسِ. ""لَمْ يَرَ مِثْلَ هَذِهِ الحُشُودِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20236, 'حُشُودٌ', 'حشود', 'مصدر', '', 'حشود', 'حشد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20237, 'حَشْرٌ', 'حشر', 'مصدر', 'حشر', 'حشر', 'حشر', 'مص. حَشَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَشْرٌ-حَشْرٌ [ح ش ر] (مص. حَشَرَ). ""يَوْمُ الحَشْرِ"" : يَوْمُ القِيامَةِ، يَوْمُ البَعْثِ. ""وَصَفَ لَهُ جَمِيعَ مَا وَرَدَ فِي الشَّرِيعَةِ مِنْ وَصْفِ العَالَمِ الإِلَهِيِّ وَالجَنَّةِ وَالنَّارِ وَالحَشْرِ وَالحِسَابِ"".(ابن طفيل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20238, 'حَشْرَجَةٌ', 'حشرجة', 'مصدر', 'حشرج', 'حشرجة', 'حشرجة', 'مص. حَشْرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَشْرَجَةٌ-حَشْرَجَةٌ [ح ش ر ج] (مص. حَشْرَجَ). 1.""حَشْرَجَةُ الْمَوْتِ"" : الغَرْغَرَةُ. 2.""حَشْرَجَةُ حِمَارٍ"" : تَرَدُّدُ صَوْتِهِ فِي حَلْقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20239, 'حَصىً', 'حصى', 'مصدر', 'حصي', 'حصى', 'حص', 'مص. حَصِيَ', '', '', 'مفرد', 'Dy', '', 'Pf', '"حَصَاةٌ:حَصَياتٌ:حَصِيٌّحُصِي', '', 'Rw', '', '', '', '', '', '', '"(مص. حَصِيَ). 1. ""رَمَاهُ بِالحَصَى"" : صِغَار الحِجَارَةِ. 2. ""فِي كِلْيَتَيْهِ حَصىً"" : مَا يَتَرَسَّبُ فِي الكِلْيَتَيْنِ مِنْ أمْلاحٍ وَغَيْرِهَا وَيُسَبِّبُ ألَماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20240, 'أحْشَامٌ', 'أحشام', 'مصدر', '', 'ءحشام', 'حشم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20241, 'حَصَادٌ', 'حصاد', 'مصدر', 'حصد', 'حصاد', 'حصد', 'مص. حَصَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَصَادٌ-حَصَادٌ [ح ص د] (مص. حَصَدَ). 1. ""جَمَعُوا الحَصادَ"" : مَا يُقْطَعُ مِنَ زَرْعٍ، الحَصْد، الزَّرْع الْمَحْصُود. 2.""اِجْتَمَعُوا فِي فَتْرَةِ الحَصَادِ"" : فِي مَوْسِمِ، أوَانِ الحَصْدِ. 3.""حَصَادُ الشَّجَرِ"" : ثَمَرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20242, 'حِصَادٌ', 'حصاد', 'مصدر', 'حصد', 'حصاد', 'حصد', 'مص. حَصَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حِصَادٌ-حِصَادٌ [ح ص د] (مص. حَصَدَ). حَلَّ زَمَنُ الحِصَادِ"": أوَانُ اقْتِطَاعِ الزَّرْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20243, 'حَصَدٌ', 'حصد', 'مصدر', 'حصد', 'حصد', 'حصد', 'مص. حَصِدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَصَدٌ-حَصَدٌ [ح ص د] (مص. حَصِدَ). 1.: الزَّرْعُ الْمَحْصُودُ. 2.: اِشْتِدَادُ الفَتْلِ وَاسْتِخْدَامُ الصِّنَاعَةِ فِي الأوْتَارِ وَالحِبَالِ وَالدُّرُوعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20244, 'حَصْرٌ', 'حصر', 'مصدر', 'حصر', 'حصر', 'حصر', 'مص. حَصَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَصْرٌ-حَصْرٌ [ح ص ر] (مص. حَصَرَ). 1. ""أُصِيبَ بِحَصْرٍ فِي بَطْنِهِ"" : بِإِمْسَاكٍ. 2.""أُصِيبَ بِحَصْرٍ فِي جِهَازِهِ البَوْلِيِّ"" : باحْتِبَاسِ بَوْلِهِ. 3.""حَضَرَ جُمْهُورٌ لاَ حَصْرَ لَهُ، يَفُوقُ الحَصْرَ"": عَدَدُهُ لاَ يُحْصَى، غَيْرُ مَحْدُودٍ. 4.""عَلَى سَبِيلِ المِثَالِ لاَ الحَصْرِ"": تَقْدِيمُ نَمُوذَجٍ أَوْ نَمَاذِجَ مُحَدَّدَةٍ لاَ الإحَاطَةُ بِكُلِّ التَّفَاصِيلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20245, 'حَصَافَةٌ', 'حصافة', 'مصدر', 'حصف', 'حصافة', 'حصفة', 'مص. حَصُفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَصَافَةٌ-حَصَافَةٌ [ح ص ف] (مص. حَصُفَ). ""حَصَافَةُ الرَّأْيِ"": اِسْتِحْكَامُهُ وَجَوْدَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20246, 'تَحْصِيلٌ', 'تحصيل', 'مصدر', 'حصل', 'تحصيل', 'تحصل', 'مص. حَصَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْصِيلٌ-تَحْصِيلٌ [ح ص ل] (مص. حَصَّلَ). 1.""تَمَكَّنَ مِنْ تَحْصِيلِ رِبْحٍ عَظِيمٍ"" : مِنِ اكْتِسَابِ... 2.""هَذَا مِنْ تَحْصِيلِ حَاصِلٍ"" : مِنَ البَدِيهِيّ، مِمَّا لاَ جِدَالَ فِيهِ .."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20247, 'حَصَلٌ', 'حصل', 'مصدر', 'حصل', 'حصل', 'حصل', 'مص. حَصِلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَصَلٌ-حَصَلٌ [ح ص ل] (مص. حَصِلَ). 1.""حَصَلُ النَّخْلِ"": البَلَحُ قَبْلَ أَنْ يَشْتَدَّ، الطَّلْعُ إذَا اصْفَرَّ. 2. ""حَصَلُ الكَأْسِ"" : حُثَالَتَهُ. 3. ""قَتَلَ الحَصَلُ الفَرَسَ"" : تُرَابُ النَّبْتِ. 4.""حَبٌّ أَسْوَدُ يُخَالِطُ حَبَّ القَمْحِ وَالشَّعِيرِ فَيُنَقَّى مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20248, 'حَصَانَةٌ', 'حصانة', 'مصدر', 'حصن', 'حصانة', 'حصنة', 'مص. حَصَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَصَانَةٌ-حَصَانَةٌ [ح ص ن] (مص. حَصَنَ). 1. ""التَّلْقِيحُ ضَرُورَةٌ لِكُلِّ إنْسَانٍ لِلْحَصَانَةِ مِنَ الأمْرَاضِ الْمُعْدِيَةِ"" : لِلْمَنَاعَةِ مِنَ العَدْوَى. 2. ""يَتَمَتَّعُ بِالحَصَانَةِ النِّيَابِيَّةِ"" : قانونٌ خاصٌّ ذو امْتِيازٍ يَتَمَتَّعُ بِهِ كُلُّ عَضْوٍ في مَجْلِسِ النُّوابِ يَحْميهِ مِنَ الاعْتِقالِ أو الْمُحاكَمَةِ، وَلا يُرْفَعُ عَنْهُ هذا الامْتِيازُ إِلاَّ بِقَرارٍ مِنَ الْمَجْلِسِ. 3. ""تَتَمَتَّعُ السِّفَارَاتُ الأَجْنَبِيَّةُ بِالحَصَانَةِ الدِّيبْلُومَاسِيَّةِ"" : عَدَمُ خُضُوعِهَا لِلْقَوَانِينِ الْمَحَلِّيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20249, 'حَطَاطٌ', 'حطاط', 'مصدر', 'حطط', 'حطاط', 'حطط', 'مص. حَطَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَطَاطٌ-حَطَاطٌ [ح ط ط] (مص. حَطَّ). ""ظَهَرَ فِي وَجْهِهِ حَطَاطٌ"" : بَثْرٌ يَظْهَرُ فِي الوَجْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20250, 'حَصَاةٌ', 'حصاة', 'مصدر', '', 'حصاة', 'حصة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20251, 'حَصِيٌّ', 'حصي', 'مصدر', '', 'حصي', 'حص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20252, 'حُصِيٌّ', 'حصي', 'مصدر', '', 'حصي', 'حص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20253, 'حَصَياتٌ', 'حصيات', 'مصدر', '', 'حصيات', 'حصت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20254, 'تَحْضِيرٌ', 'تحضير', 'مصدر', 'حضر', 'تحضير', 'تحضر', 'مص. حَضَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. حَضَّرَ). 1.""سَاهَمَ فِي تَحْضِيرِ الحَفْلَةِ"" : فِي تَهْيِيئِهَا، وَإِعْدَادِهَا. 2.""بَدَأَتِ التَّحْضِيرَاتُ عَلَى قَدَمٍ وَسَاقٍ لاسْتِقْبَالِ الضُّيُوفِ"" : بَدَأَتِ اسْتِعْدَادَاتُ التَّهْيِيءِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20255, 'حُضُورٌ', 'حضور', 'مصدر', 'حضر', 'حضور', 'حضر', 'مص. حَضَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حُضُورٌ-حُضُورٌ [ح ض ر] (مص. حَضَرَ). 1.""أيُّهَا الحُضُورُ الكِرَامُ"" : أيُّهَا السَّادَةُ الحَاضِرُونَ. 2. ""إنَّ حُضُورَكَ ضَرُورِيٌّ"": أَيْ وُجُودَكَ. 3.""سَلَّمَ لَهُ الدَّيْنَ بِحُضُورِ الشَّاهِدِ"" : بِوُجُودِهِ، بِمَشْهَدٍ مِنْهُ. 4.""اِمْتَازَ بِحُضُورِ البَدِيهَةِ"" : اِسْتِحْضَارُ الشَّيْءِ بَدَاهَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20256, 'حَضَاَرةٌ', 'حضارة', 'مصدر', 'حضر', 'حضارة', 'حضرة', 'مص. حَضِرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"حَضَاَرةٌ-حَضَاَرةٌ [ح ض ر] (مص. حَضِرَ). 1. ""يَعِيشُ أَهْلُ الْمُدُنِ فِي حَضَارَةٍ"" : فِي تَمَدُّنٍ عَكْسَ البَدَاوَةِ. 2. ""حَقَّقَتِ الحَضَارَةُ العَرَبِيَّةُ الإسْلاَمِيَّةُ تَقَدُّماً فِي جُلِّ الْمَيَادِينِ العِلْمِيَّةِ"" : مَظَاهِرُ التَّقَدُّمِ وَالرُّقِيِّ فِي مَيَادِينِ العِلْمِ وَالدِّينِ وَالفَنِّ وَالأَدَبِ وَالمِعْمَارِ مَعَ مُجْمَلِ خَصَائِصِهَا الْمُمَيِّزَةِ لَهَا. 3. ""الحَضَارَةُ الْمُعَاصِرَةُ حَضَارَةٌ إلِيكتِرُونِيَّةٌ"" : التَّقَدُّمُ العِلْمِيُّ فِي الْمَجَالِ الإِلِكْتِرونِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20257, 'تَحْضِيضٌ', 'تحضيض', 'مصدر', 'حضض', 'تحضيض', 'تحضض', 'مص. حَضَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْضِيضٌ-تَحْضِيضٌ [ح ض ض] (مص. حَضَّضَ). ""التَّحْضِيضُ عَلَى العَمَلِ"" : الحَثُّ عَلَيْهِ، الحَضُّ عَلَيْهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20258, 'حَضَانَةٌ', 'حضانة', 'مصدر', 'حضن', 'حضانة', 'حضنة', 'مص. حَضَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَضَانَةٌ-حَضَانَةٌ [ح ض ن] (مص. حَضَنَ). 1. ""فِي طَوْرِ الحَضَانَةِ"" : فِي طَوْرِ التَّرْبِيَةِ وَالتَّنْشِئَةِ. 2. ""هُوَ فِي حَضَانَةِ وَلِيِّ أَمْرِهِ"" : فِي تَرْبِيَتِهِ. 3. ""دَارُ الحَضَانَةِ"" : مُؤَسَّسَةٌ اِجْتِمَاعِيَّةٌ تَرْبَوِيَّةٌ لِتَرْبِيَةِ الأَطْفَالِ والاعْتِنَاءِ بِهِمْ قَبْلَ بُلُوغِهِمْ سِنَّ السَّابِعَةِ، وَتُسَمَّى أَيْضاً رَوْضَةُ الأطْفَالِ وَرَوْضُ الأَطْفالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20259, 'أَحْفَارٌ', 'أحفار', 'مصدر', '', 'ءحفار', 'حفر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20260, 'حَطَبٌ', 'حطب', 'مصدر', 'حطب', 'حطب', 'حطب', 'مص. حَطِبَ', '', '', 'مفرد', 'DnN', '', '', '"أحْطَابٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَطِبَ). ""رَاكَمَ الحَطَبَ أمَامَ الْمَوْقِدِ"" : مَا يُجْمَعُ مِنْ عِيدَانِ الشَّجَرِ وَقُوداً للِنَّارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20261, 'أحْطَابٌ', 'أحطاب', 'مصدر', '', 'ءحطاب', 'حطب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20262, 'تَحْطِيمٌ', 'تحطيم', 'مصدر', 'حطم', 'تحطيم', 'تحطم', 'مص. حَطَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْطِيمٌ-تَحْطِيمٌ [ح ط م ] . (مص. حَطَّمَ). 1.""تَحْطِيمُ جُدْرَانِ البَيْتِ"" : هَدْمُهَا. 2.""يَعْمَلُ عَلَى تَحْطِيمِ مَجْهُودَاتِهِ"" : عَلَى تَدْمِيرِهَا. 3.""تَحْطِيمُ الرَّقْمِ القِيَاسِيِّ"" : بُلُوغُ الرَّقْمِ الأَعْلَى. 4.""حَاوَلَ تَحْطِيمَ رَأْسِهِ"" : تَكْسِيرَهُ، إِهَانَتَهُ، إِذْلاَلَهُ . 5.""كَافَحَ الشَّعْبُ مِنْ أَجْلِ تَحْطِيمِ القُيُودِ"" : التَّخَلُّصُ مِنْهَا . 6.""يَنْبَغِي تَحْطِيمُ الفَوَارِقِ بَيْنَ النَّاسِ"" : إِزَالَتُهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20263, 'حَطَمٌ', 'حطم', 'مصدر', 'حطم', 'حطم', 'حطم', 'مص.حَطِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَطَمٌ-حَطَمٌ [ح ط م] (مص.حَطِمَ). ""أصَابَ الحَطَمُ الحَيَوانَ"" : مَرَضٌ يُصِيبُ قَوائِمَ الدَّابَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20264, 'حَظٌّ', 'حظ', 'مصدر', 'حظظ', 'حظ', 'حظ', 'مص. حَظَّ', '', '', 'مفرد', 'DnN', '', '', '"حُظُوظٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَظَّ). 1.""هَذَا مِنْ حَظِّهِ"" : مِنْ نَصِيبِهِ. ""لَيْسَ أحْسَنَ مِنْهُ حَظّاً"". 2.""لَهُ حَظٌّ غَرِيبٌ"" : يَتَمَتَّعُ بِيُسْرٍ. 3.""مِنْ حُسْنِ حَظِّهِ"" : مِنْ حُسْنِ طَالِعِهِ. ""مِنْ سُوءِ حَظِّهِ"". 4.""أتَمَنَّى لَكَ حَظّاً سَعِيداً"" : سَعَادَةً. 5. ""لِحُسْنِ الحَظِّ"" : لِحُسْنِ الْمُصَادَفَةِ. 6.""جَرَّبَ حَظَّهُ"" : كَرَّرَ الْمُحَاوَلَةَ لِلْكَسْبِ وَالفَوْزِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20265, 'حُظُوظٌ', 'حظوظ', 'مصدر', '', 'حظوظ', 'حظظ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20266, 'حُظْوَةٌ', 'حظوة', 'مصدر', 'حظي', 'حظوة', 'حظة', 'مص. حَظِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حُظْوَةٌ-حُظْوَةٌ [ح ظ ي] (مص. حَظِيَ). 1. ""نَالَ حُظْوَةً عِنْدَ الْمُعَلِّمِ"" : نَالَ مَنْزِلَةً وَمَكَانَةً وَاعْتِبَاراً عِنْدَهُ. ""نَالَ الحُظْوَةَ بَيْنَ أَهْلِهِ"". 2.: سَهْمٌ صَغِيرٌ يَلْعَبُ بِهِ الأَوْلاَدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20267, 'حَفٌّ', 'حف', 'مصدر', 'جفف', 'حف', 'حف', 'مص. حَفَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَفٌّ-حَفٌّ [ج ف ف] (مص. حَفَّ). 1. ""جَاءَ عَلَى حَفِّهِ"": عَلَى أثَرِهِ، أوْ فِي حِينِهِ وإبَّانِهِ. 2. ""هُوَ حَفٌّ بِنَفْسِهِ"" : مَعْنِيٌّ بِهَا. 3.: خَشَبَةٌ عَرِيضَةٌ فِي الْمَنْسَجِ تُنَسَّقُ بِهَا اللُّحْمَةُ بَيْنَ السَّدى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20268, 'حَفْرٌ', 'حفر', 'مصدر', 'حفر', 'حفر', 'حفر', 'مص. حَفَرَ', '', '', 'مفرد', 'DnN', '', '', '"أَحْفَارٌ:حأَحَافِيرُ"', '', 'R', '', '', '', '', '', '', '"(مص. حَفَرَ). 1. ""عَلا الحَفْرُ أسْنَانَهُ"" : صُفْرَةُ الأسْنَانِ. 2. ""هَيَّئُوا حَفْراً بِالقَرْيَةِ"" : بِئْراً مُوَسَّعَةً. 3. ""تَرَاكَمَ الحَفْرُ"" : التُّرَابُ الْمُسْتَخْرَجُ مِنَ الْمَكَانِ الْمَحْفُورِ. 4. ""بِهِ حَفْرٌ"" : هُزَالٌ، ضَعْفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20269, 'حَقٌّ', 'حق', 'مصدر', 'حقق', 'حق', 'حق', 'مص. حَقَّ', '', '', 'مفرد', 'DnN', '', '', '"حُقُوقٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَقَّ). 1. ""هُوَ عَلَى حَقٍّ"" : عَلَى صَوابٍ. ""الحَقُّ مَعَكَ"". 2. ""مِنْ حَقِّي أنْ أَسْألَكَ"" : مِنْ وَاجِبِي. 3. ""اُحْكُمْ بِحَقٍّ"" : بِعَدْلٍ، بِإنْصَافٍ.الإسراء آية 81 َجاءَ الحَقُّ وَزَهَقَ البَاطِلُ (قرآن). 4. ""الحَقُّ عَلَيْكَ لأنَّكَ لَمْ تَقُمْ بِواجِبِكَ"" : أنْتَ الْمُتَحَمِّلُ خَطَأَ عَدَمِ القِيَامِ بِهِ. 5. ""لَهُ الحَقُّ فِي إبْدَاءِ رَأْيِهِ"" : النَّصِيبُ الوَاجِبُ لَهُ. 6.""هُوَ حَقٌّ بِهَذَا الْمَنْصِبِ"" : جَدِيرٌ بِهِ. 7. ""الحَقُّ يُقَالُ إِنَّهُ عَادِلٌ فِي أَحْكَامِهِ"" : فِي الحَقِيقَةِ، فِي الوَاقِعِ. ""حَقّاً إنَّ الْمَوْضُوعَ يَسْتَحِقُّ اهْتِمَاماً أَكْثَرَ"". 8. ""أَعْرِفُهُ حَقَّ الْمَعْرِفَةِ"" : أَعْرِفُهُ كُلَّ الْمَعْرِفَةِ. 9.""قَوْلُ الحَقِّ"": الحَقِيقَةُ وَمَا هُوَ صَادِقٌ. ""لاَ يَمْنَعُنِي مَانِعٌ مِنْ قَوْلِ الحَقِّ""(ن. محفوظ). 10. ""مَا ضَاعَ حَقٌّ وَرَاءهُ مُطَالِبٌ"" : مَا ضَاعَ مَطْلَبٌ يَرْتَكِزُ عَلَى العَدْلِ. 11. ""هُوَ اللَّهُ الحَقُّ"" : مِنْ أَسْمَاءِ اللَّهِ الحُسْنَى. 12. ""عَبْدُ الحَقِّ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ. 13.""حُقُوقُ اللَّهِ"" : أوَامِرُهُ، وَمَا يَجِبُ عَلَيْنَا نَحْوَهُ. 14.""يَدْرُسُ الحُقُوقَ"" : يَدْرُسُ القَوَانِينَ وَالتَّشْرِيعَاتِ وَالأَعْرَافَ الدَّوْلِيَّةَ. 15. ""صَادَقَتِ الأُمَمُ الْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20270, 'أَحَافِيرُ', 'أحافير', 'مصدر', '', 'ءحافير', 'حفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20271, 'حَفْصٌ', 'حفص', 'مصدر', 'حفص', 'حفص', 'حفص', 'مص. حَفَصَ', '', '', 'مفرد', 'DnN', '', '', '"أحْفَاصٌ:حُفُوصٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَفَصَ). 1. ""يَسْكُنُ فِي حَفْصٍ"" : فِي بَيْتٍ صَغِيرٍ. 2.: شِبْلٌ 3. ""أبو حَفْصٍ"" : كُنْيَةُ الأَسَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20272, 'أحْفَاصٌ', 'أحفاص', 'مصدر', '', 'ءحفاص', 'حفص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20273, 'حُفُوصٌ', 'حفوص', 'مصدر', '', 'حفوص', 'حفص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20274, 'تَحْفِيظٌ', 'تحفيظ', 'مصدر', 'حفظ', 'تحفيظ', 'تحفظ', 'مص. حَفَّظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْفِيظٌ-تَحْفِيظٌ [ح ف ظ] (مص. حَفَّظَ). ""تَحْفِيظُ القُرْآنِ الكَرِيمِ"" : الدَّفْعُ إِلَى حِفْظِهِ عَنْ ظَهْرِ قَلْبٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20275, 'حِفْظٌ', 'حفظ', 'مصدر', 'حفظ', 'حفظ', 'حفظ', 'مص. حَفَظَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حِفْظٌ-حِفْظٌ [ح ف ظ] (مص. حَفَظَ). 1. ""يَسْهَرُ عَلَى حِفْظِ النِّظَامِ "" : حِراسَةُ النِّظامِ مِنْ كُلِّ مَا مِنْ شَأْنِهِ أنْ يَمَسَّ بِهِ. 2. ""يَهْتَمُّ بِحِفْظِ الآثَارِ القَدِيمَةِ"" : بِرِعَايَتِهَا وَصِيَانَتِهَا. 3.""حِفْظُ القُرْآنِ"" : اِسْتِظْهَارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20276, 'حَفْلٌ', 'حفل', 'مصدر', 'حفل', 'حفل', 'حفل', 'مص. حَفَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَفْلٌ-حَفْلٌ [ح ف ل] (مص. حَفَلَ). 1. ""اِجْتَمَعَ فِي بَيْتِهِ حَفْلٌ مِنَ النَّاسِ"" : جَمْعٌ كَثِيرٌ. ""هَذَا جَمْعٌ حَفْلٌ"". 2.""حَفْلٌ عَائِلِيٌّ"" : اِحْتِفَالٌ. ""حَفْلٌ سَاهِرٌ"" ""حَفْلُ افْتِتَاحٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20277, 'حَفَاوَةٌ', 'حفاوة', 'مصدر', 'حفو', 'حفاوة', 'حفة', 'مص. حَفِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَفَاوَةٌ-حَفَاوَةٌ [ح ف و] (مص. حَفِيَ). ""اِسْتَقْبَلَ ضَيْفَهُ بِحَفَاوَةٍ"" : إِظْهَار الفَرَحِ وَالإِكْرَامِ. ""شَكَرَهُ عَلَى حَفَاوَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20278, 'حَفِيفٌ', 'حفيف', 'مصدر', 'حفف', 'حفيف', 'حفف', 'مص. حَفَّ يَحِفُّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَفِيفٌ-حَفِيفٌ [ح ف ف] (مص. حَفَّ يَحِفُّ) 1. ""حَفِيفُ الأشْجَارِ"" : الصَّوْتُ الصَّادِرُ عَنْ تَحَرُّكِ أَوْرَاقِ الشَّجَرِ. 2.""حَفِيفُ جَنَاحَيِ الطَّائِرِ"" : صَوْتُ جَناحَيْهِ. 3.""حَفيفُ الحَيَّةِ"": صَوْتُ جِلْدِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20279, 'أَحْقَادٌ', 'أحقاد', 'مصدر', '', 'ءحقاد', 'حقد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20280, 'حُقُوقٌ', 'حقوق', 'مصدر', '', 'حقوق', 'حقق', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20281, 'حَقْوٌ', 'حقو', 'مصدر', 'حقو', 'حقو', 'حق', 'مص. حَقا', '', '', 'مفرد', 'DnN', '', '', '"حِقَاءٌ:أَحْقَاءٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَقا). 1.""أخَذَ بِحَقْوِهِ"" : بِخِصْرِهِ. 2. ""عَاذَ بِحَقْوِهِ"" : اِسِتَجَارَ بِهِ وَاعْتَصَمَ. 3. ""حَقْوُ الجَبَلِ"" : سَفْحُهُ. 4. ""رَمَتْ بِحَقْوِهَا"" : بِإزَارِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20282, 'حِقَاءٌ', 'حقاء', 'مصدر', '', 'حقاء', 'حق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20283, 'أَحْقَاءٌ', 'أحقاء', 'مصدر', '', 'ءحقاء', 'حق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20284, 'حَقَبٌ', 'حقب', 'مصدر', 'حقب', 'حقب', 'حقب', 'مص. حَقِبَ.', '', '', 'مفرد', 'DnN', '', '', '"أحْقَابٌ:أحْقُبٌ:حُقُبٌ"', '', 'R', '', '', '', '', '', '', '"ج: أحْقَابٌ، أحْقُبٌ، حُقُبٌ (مص. حَقِبَ). 1.""حَقَبُ الحَقِيبَةِ"" : حَبْلٌ تُشَدُّ بِهِ. 2.: الحِزامُ الَّذِي يَلِي حَقْلَ البَعيرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20285, 'أحْقَابٌ', 'أحقاب', 'مصدر', '', 'ءحقاب', 'حقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20286, 'أحْقُبٌ', 'أحقب', 'مصدر', '', 'ءحقب', 'حقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20287, 'حُقُبٌ', 'حقب', 'مصدر', '', 'حقب', 'حقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20288, 'حِقْدٌ', 'حقد', 'مصدر', 'حقد', 'حقد', 'حقد', 'مص. حَقَدَ', '', '', 'مفرد', 'DnN', '', '', '"أَحْقَادٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَقَدَ). ""يُضْمِرُ لَهُ حِقْداً ضَغِناً"" : الانْطِواء عَلَى الضَّغِينَةِ وَمَا يُضْمَرُ مِنْ عَدَاوةٍ فِي القَلْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20289, 'أَحْكَامٌ', 'أحكام', 'مصدر', '', 'ءحكام', 'حكم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20290, 'تَحْقِيرٌ', 'تحقير', 'مصدر', 'حقر', 'تحقير', 'تحقر', 'مص. حَقَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْقِيرٌ-تَحْقِيرٌ [ح ق ر] (مص. حَقَّرَ). ""لَمْ يَفْهَمْ سَبَبَ تَحْقِيرِهِ إِيَّاهُ"" : إِذْلاَلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20291, 'حَقَارَةٌ', 'حقارة', 'مصدر', 'حقر', 'حقارة', 'حقرة', 'مص. حَقَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَقَارَةٌ-حَقَارَةٌ [ح ق ر] (مص. حَقَرَ). ""يَا لَهَا مِنْ حَقَارَةٍ"" : الذَّلَّةُ، الْمَهَانَةُ، الهَوَانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20292, 'تَحْقِيقٌ', 'تحقيق', 'مصدر', 'حقق', 'تحقيق', 'تحقق', 'مص. حَقَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْقِيقٌ-تَحْقِيقٌ [ح ق ق] (مص. حَقَّقَ). 1.""يَسْعَى إِلَى تَحْقِيقِ مَشْرُوعِهِ"" : تَنْفِيذِهِ. 2.""أَجْرَى تَحْقِيقاً"" : اِسْتِطْلاَعاً فِي عَيْنِ الْمَكَانِ. 3.""لَمْ تَظْهَرْ بَعْدُ نَتَائِجُ التَّحْقِيقِ"" : التَّحَرِّيَاتُ وَالتَّأَكُّدُ مِنَ الحَقَائِقِ. 4.""قُدِّمَ الْمُتَّهَمُ إِلَى قَاضِي التَّحْقِيقِ"" : القَاضِي الَّذِي لَهُ مَسْؤُولِيَّةُ اسْتِنْطاَقِ الْمُتَّهَمِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20293, 'حَقْنٌ', 'حقن', 'مصدر', 'حقن', 'حقن', 'حقن', 'مص. حَقَنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَقْنٌ-حَقْنٌ [ح ق ن] (مص. حَقَنَ). 1. ""مِنَ الضَّرُورِيِّ حَقْنُهُ بِدَوَاءٍ ضِدَّ الأَمْرَاضِ الْمُعْدِيَةِ"" : تَلْقِيحُهُ. 2. ""جَاءَ الاتِّفَاقُ حَقْناً لِلدِّمَاءِ"" : حِرْصاً عَلَى عَدَمِ إرَاقَةِ الدِّمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20294, 'حَكْرٌ', 'حكر', 'مصدر', 'حكر', 'حكر', 'حكر', 'مص. حَكَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حُكَرٌ-حُكَرٌ [ح ك ر]. 1.""سَادَ الحُكَرُ فِي السُّوقِ"" : اِحْتِكَارُ البَضَائِعِ وَالسِّلَعِ لِلإِفَادَةِ مِنْ غَلاَئِهَا. 2.""حُكَرُ الشَّيْءِ"" : القَلِيلُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20295, 'تَحْكِيمٌ', 'تحكيم', 'مصدر', 'حكم', 'تحكيم', 'تحكم', 'مص. حَكَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْكِيمٌ-تَحْكِيمٌ [ح ك م] (مص. حَكَّمَ). 1.""تَكَوَّنَتْ لَجْنَةُ التَّحْكِيمِ"" : الهَيْئَةُ الْمُكَوَّنَةُ لإِصْدَارِ حُكْمٍ فِي خِلاَفٍ مَّا وَالفَصْلِ فِيهِ لِتَسْوِيَتِهِ. 2.""كَانَ التَّحْكِيمُ نَزِيهاً فِي الْمُبَارَاةِ الرِّيَاضِيَّةِ"" : كَانَ سَيْرُهَا جَيِّداً مَضْبُوطاً عَادِلاً لاَ تَحَيُّزَ فِيهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20296, 'حِكْمَةٌ', 'حكمة', 'مصدر', 'حكم', 'حكمة', 'حكمة', 'مص. حَكَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":حِكَمٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَكَمَ). 1.""حِكْمَةٌ بَالِغَةٌ"" : قَوْلَةٌ تَتَضَمَّنُ رَأْياً حَكِيماً مُوَافِقاً لِلْحَقِّ وَالصَّوَابِ. إنَّ مِنَ الشِّعْرِ لَحِكْمَةً (حديث). 2. ""بَيْتُ الحِكْمَةِ"" : بَيْتُ العِلْمِ وَالفَلْسَفَةِ. 3. ""هُوَ مِنْ أَهْلِ الحِكْمَةِ"" : مِنْ أَهْلِ العِلْمِ وَالفَلْسَفَةِ وَالْمَعْرِفَةِ وَالتَّبَصُّرِ بِحَقَائِقِ الأُمُورِ وَكُنْهِهَا وَجَوْهَرِهَا.البقرة آية 269 وَمَنْ يُؤْتَ الحِكْمَةَ فَقَدْ أُوتِيَ خَيْراً كَثِيراً (قرآن). 4.""عَامَلَهُ بِحِكْمَةٍ وَأنَاةٍ فَأفْسَدَ عَلَيْهِ غَضَبَهُ"" : ضَبْطُ النَّفْسِ وَالتَّرَوِّي. 5. ""الحِكْمَةُ الإلَهِيَّةُ"" : مَا أظْهَرَهُ اللَّهُ فِي القُرْآنِ وَيَتَلَمَّسُهُ النَّاظِرُ فِي مَوْجُودَاتِ الكَوْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20297, 'حِكَمٌ', 'حكم', 'مصدر', '', 'حكم', 'حكم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20298, 'حُكْمٌ', 'حكم', 'مصدر', 'حكم', 'حكم', 'حكم', 'مص. حَكَمَ', '', '', 'مفرد', 'DnN', '', '', '"أَحْكَامٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَكَمَ). 1. ""نَطَقَ القَاضِي بِالحُكْمِ"" : نَطَقَ بِقَرَارِ العُقُوبَةِ، مَا يَحْكُمُ بِهِ، مَا يَقْضِي بِهِ. 2. ""صَدَرَ فِي حَقِّهِ الحُكْمُ غِيَابِيّاً"" : مَا يَصْدُرُ فِي حَقِّ مُتَّهَمٍ لَمْ يَحْضُرْ جَلْسَةَ الْمُحَاكَمَةِ. 3. ""الحُكْمُ الْمَلَكِيُّ"" : النِّظَامُ الْمَلَكِيُّ الخَاضِعُ لِسُلْطَةِ الْمَلِكِ. 4. ""الحُكْمُ الجُمْهُورِيُّ"": نِظَامٌ خَاضِعٌ لانْتِخَابِ شَخْصٍ مَّا رَئِيساً لِلْجُمْهُورِيَّةِ. 5.""الحُكْمُ الْمُطْلَقُ"" : النِّظَامُ الخَاضِعُ لإِدَارَةِ فَرْدٍ يَحْكُمُ حَسَبَ مَا يُرِيدُ. 6.""تَوَلَّى حُكْمَ البِلاَدِ"" : تَوَلَّى تَسْيِيرَ شُؤُونِهَا. 7.""يَخْضَعُ لِحُكْمِ القَانُونِ"" : مَا يَنُصُّ عَلَيِهِ القَانُونُ. ""أَحْكَامُ القَانُونِ"". 8.""أُعْلِنَتِ الأَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20299, 'حُكُومَةٌ', 'حكومة', 'مصدر', 'حكم', 'حكومة', 'حكمة', 'مص. حَكَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"حُكُومَةٌ-حُكُومَةٌ [ح ك م] (مص. حَكَمَ). ""تَألَّفَتْ حُكُومَةٌ جَدِيدَةٌ"" : جِهَازٌ سِيَاسِيٌّ يَتَكَوَّنُ مِنْ عِدَّةِ وُزَرَاءَ يُسَيِّرُونَ شُؤُونَ البِلاَدِ وَمَرَافِقَهَا فِي شَتَّى الْمَجَالاَتِ تَحْتَ رَئِيسِ الوُزَرَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20300, 'حِكَايَةٌ', 'حكاية', 'مصدر', 'حكي', 'حكاية', 'حكة', 'مص. حَكَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. حَكَى). 1.""رَوَتْ حِكَايَةً طَرِيفَةً"" : أُقْصُوصَةً، مَا يُقَصُّ مِنْ قَصَصٍ. 2.""تَرْوِي حِكَايَاتٍ شَعْبِيَّةً"" : خُرَافَاتٍ. ""حِكَايَةٌ خُرَافِيَّةٌ"" ""حِكَايَةٌ وَاقِعِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20301, 'حَلٌّ', 'حل', 'مصدر', 'حلل', 'حل', 'حل', 'مص. حَلَّ', '', '', 'مفرد', 'DnN', '', '', '"حُلُولٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَلَّ). 1. ""يُسَاعِدُهُ عَلَى حَلِّ مَشَاكِلِهِ"" : يُسَاعِدُهُ لِيَجِدَ لَهَا مَخْرَجاً، يُسَوِّيهَا. 2.""هُوَ مِنْ أَهْلِ الحَلِّ وَالرَّبْطِ"" : مَنْ بِيَدِهِمْ السُّلْطَةُ وَالنُّفُوذُ. ""أَهْلُ الحَلِّ وَالعَقْدِ"". 3. ""يُصَاحِبُهُ فِي حَلِّهِ وَتَرْحَالِهِ"" : يُرَافِقُهُ إلَى كُلِّ مَكَانٍ وَفِي كُلِّ عَمَلٍ يَعْمَلُهُ. 4. ""قَرَّرَ حَلَّ الْمُنَظَّمَةِ"" : أيْ شَلَّ، إلْغَاءَ نَشَاطِهَا القَانُونِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20302, 'حُلُولٌ', 'حلول', 'مصدر', '', 'حلول', 'حلل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20303, 'حُلُولٌ', 'حلول', 'مصدر', 'حلل', 'حلول', 'حلل', 'مص. حَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حُلُولٌ-حُلُولٌ [ح ل ل] (مص. حَلَّ). 1. ""يَنْتَظِرُ حُلُولَ الأَجَلِ"" : أَيْ نِهَايَتَهُ. ""يَنْتَظِرُ حُلُولَ آخِرِ الشَّهْرِ بِفَارِغِ الصَّبْرِ"" ""حُلُولُ بَشَائِرِ الرَّبِيعِ مُلَوِّحَةً بِالدِّفْءِ وَالبَشَاشَةِ""(ن. محفوظ). 2. ""الحُلُولُ"" : اِتِّحَادُ جِسْمَيْنِ اتِّحاداً تَامّاً بِحَيْثُ تَكُونُ الإشَارَةُ إلَى أَحَدِهِمَا إشَارَةً إلَى الآخَرِ، أَيْ يَذُوبُ أَحَدُهُمَا فِي الآخَرِ. 3. ""مَذْهَبُ الحُلُولِ"" : القَوْلُ بِأَنَّ اللَّه حَالٌّ وَمَوْجُودٌ فِي كُلِّ شَيْءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20304, 'حَلاَوَةٌ', 'حلاوة', 'مصدر', 'حلو', 'حلاوة', 'حلة', 'مص. حَلاَ، حَلِيَ', '', '', 'مفرد', 'DnN', '', '', '"حَلاوَى"', '', 'R', '', '', '', '', '', '', '"(مص. حَلاَ، حَلِيَ). 1. ""قَدَّمَ لَهُ حَلاَوةً طَيِّبَةً"" : نَوْعٌ مِنَ الحُلْوَى، مِنَ الدَّقِيقِ وَالسَّمْنِ وَالسُّكَّرِ وَمَا إلَى ذَلِكَ. 2. ""حَلاوَةُ القَفَا"" : وَسَطُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20305, 'حَلاوَى', 'حلاوى', 'مصدر', '', 'حلاوى', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20306, 'حَلْفٌ', 'حلف', 'مصدر', 'حلف', 'حلف', 'حلف', 'مص. حَلَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَلْفٌ-حَلْفٌ، حَلِفٌ [ح ل ف] (مص. حَلَفَ). ""أدَّى حَلْفَ اليَمِينِ"" : أَدَّى القَسَمَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20307, 'حِلْفٌ', 'حلف', 'مصدر', 'حلف', 'حلف', 'حلف', 'مص. حَلَفَ', '', '', 'مفرد', 'DnN', '', '', '"أَحْلافٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَلَفَ). 1.""بَيْنَهُمَا حِلْفٌ مُقَدَّسٌ"" : مِيثَاقٌ، عَهْدٌ، صَدَاقَةٌ. 2. ""أُقِيمَ حِلْفٌ عَسْكَرِيٌّ بَيْنَ البَلَدَيْنِ"" : مُعَاهَدَةٌ، اِتِّفَاقِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20308, 'أَحْلافٌ', 'أحلاف', 'مصدر', '', 'ءحلاف', 'حلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20309, 'تَحْلِيقٌ', 'تحليق', 'مصدر', 'حلق', 'تحليق', 'تحلق', 'مص. حَلَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْلِيقٌ-تَحْلِيقٌ [ح ل ق] (مص. حَلَّقَ). 1.""تَحْلِيقُ الشَّعْرِ"" : حَلْقُهُ، تَزْيِينُهُ. 2.""تَحْلِيقُ الطُّيُورِ فِي السَّمَاءِ"" : عُلُوُّهَا وَاسْتِدَارَتُهَا فِي السَّمَاءِ، اِرْتِفَاعُهَا. ""تَحْلِيقُ الطَّائِرَةِ"". 3.""التَّحْلِيقُ بِالصَّبْرِ بَعِيداً"" : رَفْعُهُ وَتَرْكِيزُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20310, 'حَلْقٌ', 'حلق', 'مصدر', 'حلق', 'حلق', 'حلق', 'مص. حَلَقَ', '', '', 'مفرد', 'DnN', '', '', '"أحْلاَقٌ:حُلُوقٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَلَقَ). 1. ""أُصِيبَ بِبُحَّةٍ فِي حَلْقِهِ"" : مَجْرَى الطَّعامِ والشَّرَابِ إلَى الْمَرِيءِ. ""كَانَتِ اللُّقْمَةُ تَقِفُ فِي حَلْقِي وَأنَا أَبْلَعُهَا"" (حنا مينه). 2. حُرُوفُ الحَلْقِ هِيَ : العَيْنُ وَالحَاءُ، أَي الحُرُوفُ التَّي تَخْرُجُ مِنَ الحَلْقِ عِنْدَ النُّطْقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20311, 'أحْلاَقٌ', 'أحلاق', 'مصدر', '', 'ءحلاق', 'حلق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20312, 'حُلُوقٌ', 'حلوق', 'مصدر', '', 'حلوق', 'حلق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20313, 'حَلَكٌ', 'حلك', 'مصدر', 'حلك', 'حلك', 'حلك', 'مص. حَلَكَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَلَكٌ-حَلَكٌ [ح ل ك] (مص. حَلَكَ). ""اِشْتَدَّ بِهِ الفَزَعُ فِي حَلَكِ اللَّيْلِ"" : فِي شِدَّةِ سَوَادِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20314, 'تَحْلِيلٌ', 'تحليل', 'مصدر', 'حلل', 'تحليل', 'تحلل', 'مص. حَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. حَلَّلَ). 1.""قَدَّمَ تَحْلِيلاً جَيِّداً لِلْمَوْضُوعِ"" : تَفْسِيراً وَشَرْحاً لَهُ. 2.""التَّحْلِيلُ الكِيمْيَائِيُّ"" : الوُصُولُ إِلَى مَعْرِفَةِ عَنَاصِرِ الْمَوَادِّ وَخَصَائِصِها. 3.""أَجْرَى تَحْلِيلاَتٍ أَوَّلِيَّةً"" : مَا يُجْرِيهِ الْمَرِيضُ مِنْ فُحُوصَاتٍ فِي مُخْتَبَرِ الطَّبِيبِ، وَمِنْهَا : ""تَحْلِيلُ الدَّمِ"" لِمَعْرِفَةِ سَلاَمَتِهِ أَوْ تَعَرُّضِهِ لِمَرَضٍ مِنَ الأَمْرَاضِ. 4.""التَّحْلِيلُ النَّفْسِيُّ"" : مَا يَقُومُ بِهِ الطَّبِيبُ النَّفْسَانِيُّ لِمَعْرِفَةِ حَالَةِ الإِنْسَانِ النَّفْسِيَّةِ وَعُقَدِهَا وَاضْطِرَابَاتِهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20315, 'حُلُمٌ', 'حلم', 'مصدر', 'حلم', 'حلم', 'حلم', 'مص. حَلَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حُلُمٌ-حُلُمٌ [ح ل م] (مص. حَلَمَ). ""بَلَغَ الحُلُمَ"" : أَدْرَكَ سِنَّ البُلُوغِ. النور آية 59 وَإذَا بَلَغ الأَطْفَالُ مِنْكُمُ الحُلُمَ فَلْيَسْتَأْذِنُوا (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20316, 'حُلْمٌ', 'حلم', 'مصدر', 'حلم', 'حلم', 'حلم', 'مص. حَلَمَ', '', '', 'مفرد', 'DnN', '', '', '"أحْلاَمٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَلَمَ). 1.""اِسْتَيْقَظَ مَذْعُوراً مِنْ حُلْمِهِ"" : مَا يَرَاهُ النَّائِمُ مِنْ رُؤْيا فِي نَوْمِهِ. 2. ""مَا هِيَ إلاَّ أَضْغَاثُ أَحْلاَمٍ"" : كَوَابِيسُ، أيْ مَا يَرَاهُ النَّائِمُ مِنْ أَحْلاَمٍ مُخْتَلِطَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20317, 'أحْلاَمٌ', 'أحلام', 'مصدر', '', 'ءحلام', 'حلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20318, 'حِلْمٌ', 'حلم', 'مصدر', 'حلم', 'حلم', 'حلم', 'مص. حَلُمَ', '', '', 'مفرد', 'DnN', '', '', '"أَحْلاَمٌ:حُلُومٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَلُمَ). 1.""كَانَ حِلْماً فِي مُعَامَلَتِهِ لِلنَّاسِ"" : فِي مُعَامَلَتِهِ أنَاةٌ وَصَبْرٌ وَضَبْطُ لِلنَّفْسِ. 2.""حِلْمُ الرَّجُلِ"" : عَقْلُهُ.الطور آية 32 أَمْ تَأْمُرُهُمْ أحْلامُهُمْ بِهَذَا (قرآن). 3.""حَكَمَ حُكْماً فِيهِ حِلْمٌ"" : عَفْوٌ، صَفْحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20319, 'حَمْدَلَةٌ', 'حمدلة', 'مصدر', 'حمدل', 'حمدلة', 'حمدلة', 'مص. حَمْدَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَمْدَلَةٌ-حَمْدَلَةٌ [ح م د ل] (مص. حَمْدَلَ). ""كَانَتِ الحَمْدَلَةُ عَلَى لِسَانِهِ فِي كُلِّ آنٍ"" : أَيْ تَرْدِيدُ ""الحَمْدُ لِلَّهِ رَبِّ العَالَمِينَ""، وَهِيَ اخْتِزَالٌ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20320, 'أَحْلاَمٌ', 'أحلام', 'مصدر', '', 'ءحلام', 'حلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20321, 'حُلُومٌ', 'حلوم', 'مصدر', '', 'حلوم', 'حلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20322, 'حَلَمٌ', 'حلم', 'مصدر', 'حلم', 'حلم', 'حلم', 'مص. حَلِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَلِمٌ-حَلِمٌ [ح ل م] (صِيغَةُ فَعِل). ""جِلْدٌ حَلِمٌ"" : جِلْدٌ كَثُرَ فِيهِ الحَلَمُ فَأَفْسَدَهُ وَثَقَّبَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20323, 'تَحْلِيَةٌ', 'تحلية', 'مصدر', 'حلو', 'تحلية', 'تحلة', 'مص. حَلَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. حَلَّى). 1.""تَحْلِيَةُ الْمَاءِ "" : جَعْلُهُ عَذْباً سَلِساً. 2.""قَدَّمَتْ لِلضُّيُوفِ تَحْلِيَاتٍ مُتَنَوِّعَةً مِنَ الفَوَاكِهِ وَالحَلَوِيَّاتِ"" : مَا يُقَدَّمُ فِي آخِرِ الطَّعَامِ مِنْ حَلَوِيَّاتٍ وَمُرَطِّبَاتٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20324, 'حَلالٌ', 'حلال', 'مصدر', 'حلل', 'حلال', 'حلل', 'مص. حَلَّ، يَحِلُّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَلالٌ-حَلالٌ [ح ل ل] (مص. حَلَّ، يَحِلُّ). 1. ""هَذَا حَلاَلٌ"": مَا أحَلَّهُ اللَّهُ، مَا لَيْسَ بِحَرَامٍ ، جائِزٌ ، مَسْمُوحٌ بِهِ . ""حَلاَلٌ عَلَيْكَ حَرَامٌ عَلَيَّ"". 2. ""اِبْنُ حَلاَلٍ"" : اِبْنٌ شَرْعِيٌّ. 3. ""رَجُلٌ اِبْنُ حَلاَلٍ"" : طَيِّبُ الخُلُقُ وَالعِشْرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20325, 'حِلٌّ', 'حل', 'مصدر', 'حلل', 'حل', 'حل', 'مص. حَلَّ، يَحِلُّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حِلٌّ-حِلٌّ [ح ل ل] (مص. حَلَّ، يَحِلُّ). 1. ""هُوَ فِي حِلٍّ عَنْ يَمِينِهِ"" : مُتَحَرِّرٌ مِنْهُ. 2. ""أنَا فِي حِلٍّ مِنْ كُلِّ مَسْؤُولِيَّةٍ"" : مُتَحَلِّلٌ، مَتَحَرِّرٌ، مُتَخلِّصٌ مِنْهَا. 3.""هُوَ حِلٌّ فِي بَيْتِهِ"" : حالٌّ بِهِ، مُقِيمٌ فِيهِ. البلد آية 1،2 لاَ أُقْسِمُ بِهَذَا البَلَدِ، وَأنْتَ حِلٌّ بِهَذَا البَلَدِ (قرآن). 4. ""أمْرٌ حِلٌّ"" : حَلاَلٌ، مُبَاحٌ. 5.""الأَشْهُرُ الحِلُّ"" : مَا سِوَى الأَشْهُرِ الحُرُمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20326, 'حَمٌّ', 'حم', 'مصدر', 'حمم', 'حم', 'حم', 'مص. حَمَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَمٌّ-حَمٌّ [ح م م] (مص. حَمَّ). 1. ""اِشْتَدَّ الحَمُّ"" : الحَرَارةُ. 2. ""حَمُّ الظَّهيرَةِ"" : شِدَّةُ حَرِّهَا. 3. ""حَمُّ الشَّحْمِ"" : مَا أُذيبَ مِنْهُ. 4. ""حَمُّ الشَّيْءِ"" : مُعْظَمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20327, 'تَحْمِيدٌ', 'تحميد', 'مصدر', 'حمد', 'تحميد', 'تحمد', 'مص. حَمَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْمِيدٌ-تَحْمِيدٌ [ح م د] (مص. حَمَّدَ). ""اِسْتَغْرَقَ العَابِدُ فِي التَّحْمِيدِ"" : الإِكْثَارُ مِنْ تَرْدِيدِ ""الحَمْدُ لِلهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20328, 'حَمْدٌ', 'حمد', 'مصدر', 'حمد', 'حمد', 'حمد', 'مص. حَمِدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَمْدٌ-حَمْدٌ [ح م د] (مص. حَمِدَ). ""الحَمْدُ لِلَّهِ"" : الشُّكْرُ وَالثَّنَاءُ لَهُ. ""لَهُ الحَمْدُ"" ""حَمْداً لِلَّهِ"" ""الحَمْدُ لِلَّهِ عَلَى سَلاَمَتِكَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20329, 'حَمَلاتٌ', 'حملات', 'مصدر', '', 'حملات', 'حملت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20330, 'تَحْمِيسٌ', 'تحميس', 'مصدر', 'حمس', 'تحميس', 'تحمس', 'مص. حَمَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْمِيسٌ-تَحْمِيسٌ [ح م س] (مص. حَمَّسَ). 1.""تَحْمِيسُ الفَرِيقِ"" : تَشْجِيعُهُ. 2.""حَاوَلَ تَحْمِيسَهُ عَلَى عَدُوِّهِ"" : أَيْ تَهْيِيجَهُ، تَحْرِيضَهُ. 3.""تَحْمِيسُ اللَّوْزِ فِي المِقْلاَةِ"" : تَحْميصُهُ، قَلْيُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20331, 'حَمَاسَةٌ', 'حماسة', 'مصدر', 'حمس', 'حماسة', 'حمسة', 'مص. حَمُسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"حَمَاسَةٌ-حَمَاسَةٌ [ح م س] (مص. حَمُسَ). 1. ""أظْهَرَ حَمَاسَةً فِي الْمَعْرَكَةِ"" : شَجَاعَةً، حَمِيَّةً، حَيَوِيَّةً، حِدَّةً. ""عَبَّرَ عَنْ حَمَاسَتِهِ"". 2.""دِيوَانُ الحَمَاسَةِ"" : مَجْمُوعُ قَصَائِدَ مِنْ عُيُونِ الشِّعْرِ العَرَبِيِّ تَدُورُ حَوْلَ الأَمْجَادِ وَالبُطُولاَتِ فِي الحُرُوبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20332, 'تَحْمِيضٌ', 'تحميض', 'مصدر', 'حمض', 'تحميض', 'تحمض', 'مص. حَمَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْمِيضٌ-تَحْمِيضٌ [ح م ض] (مص. حَمَّضَ). 1.""تَحْمِيضُ الأَكْلِ"" : جَعْلُهُ حَامِضاً. 2.""تَحْمِيضُ الفِلْمِ"" : إِظْهَارُ مَا يَحْتَوِيهِ مِنْ صُوَرٍ بِوَاسِطَةِ آلاَتٍ وَمَوَادَّ كِيمِيَائِيَّةٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20333, 'حُمُوضَةٌ', 'حموضة', 'مصدر', 'حمض', 'حموضة', 'حمضة', 'مص. حَمُضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حُمُوضَةٌ-حُمُوضَةٌ [ح م ض] (مص. حَمُضَ). 1.""حُمُوضَةُ نَبَاتٍ"" : طَعْمُ نَباتٍ حَامِضٍ يَلْذَعُ اللِّسَانَ. 2. ""حُمُوضَةُ الدَّمِ"" (طب). : قَلْوِيَّتهُ عِنْدَما تَنْقُصُ وَتَصيرُ بِها حُموضَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20334, 'تَحْمِيقٌ', 'تحميق', 'مصدر', 'حمق', 'تحميق', 'تحمق', 'مص. حَمَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْمِيقٌ-تَحْمِيقٌ [ح م ق] (مص. حَمَّقَ). ""تَحْمِيقُ الرَّجُلِ"" : جَعْلُهُ أَحْمَقَ، وَصْفُهُ بِالأَحْمَقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20335, 'حَمَاقَةٌ', 'حماقة', 'مصدر', 'حمق', 'حماقة', 'حمقة', 'مص. حَمُقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. حَمُقَ). ""أَظْهَرَ حَمَاقَةً أَمَامَ النَّاسِ"" : قِلَّة العَقْلِ وَالشَّطَطِ فِي التَّفْكِيرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20336, 'حُمْقٌ', 'حمق', 'مصدر', 'حمق', 'حمق', 'حمق', 'مص. حَمُقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حُمْقٌ-حُمْقٌ [ح م ق] (مص. حَمُقَ). ""بِهِ حُمْقٌ"" : قِلَّةُ العَقْلِ وَفَسَادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20337, 'تَحْمِيلٌ', 'تحميل', 'مصدر', 'حمل', 'تحميل', 'تحمل', 'مص. حَمَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْمِيلٌ-تَحْمِيلٌ [ح م ل] . (مص. حَمَّلَ) . 1.""تَحْمِيلُهُ الحِمْلَ"" : جَعَلَهُ يَحْمِلُهُ. 2.""تَحْمِيلُهُ مَا لاَطَاقَةَ لَهُ بِهِ"" : تَكْلِيفُهُ. 3.""تَحْمِيلُهُ مَسْؤُولِيَّةَ مَا حَدَثَ"" : جَعْلُهُ مَسْؤُولاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20338, 'حَمْلَةٌ', 'حملة', 'مصدر', 'حمل', 'حملة', 'حملة', 'مص. حَمَلَ', '', '', 'مفرد', 'DnN', '', '', '"حَمَلاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَمَلَ). 1.""قَامَ الجَيْشُ بِحَمْلَةٍ عَسْكَرِيَّةٍ عَلَى مَوَاقِعِ العَدُوِّ"" : هُجُومٌ عَسْكَرِيٌّ بِالْمُعِدَّاتِ الحَرْبِيَّةِ. 2. ""قَامَ جَيْشُ الطَّيَرَانِ بِحَمْلَةٍ اسْتِكْشَافِيَّةٍ"": عَمَلِيَّةُ اسْتِطْلاعٍ لِمَوَاقِعِ العَدُوِّ. 3.""قَامَتِ الصُّحُفُ الوَطَنِيَّةُ بِحَمْلَةٍ على الرَّشْوَةِ وَالفَسَادِ"" : مَا تَعْكِسُهُ مَقَالاتُهَا وَاستِطْلاعَاتُهَا مِنْ أَشْيَاءَ وَحَقَائِقَ. 4.""دَخَلَتِ الأَحْزَابُ السِّيَاسِيَّةُ الحَمْلَةَ الانْتِخَابِيَّةَ"" : الدِّعَايَة الَّتِي تَقُومُ بِهَا مِنْ أَجْلِ الفَوْزِ بِالتَّأْيِيدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20339, 'حَوَاجِلُ', 'حواجل', 'مصدر', '', 'حواجل', 'حجل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20340, 'حِمَايَةٌ', 'حماية', 'مصدر', 'حمي', 'حماية', 'حمة', 'مص. حَمَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حِمَايَةٌ-حِمَايَةٌ [ح م ي] (مص. حَمَى). 1. ""حِمَايَةُ الْمُوَاطِنِينَ"" : وِقَايَتُهُمْ وَصِيَانَتُهُم. 2. ""حِمَايَةُ الاقْتِصَادِ الوَطَنِيِّ"": العَمَلُ عَلَى تَطْبِيقِ نِظَامٍ يَحْمِي الاقْتِصَادَ الوَطَنِيَّ مِنَ الْمُنَافَسَةِ الخَارِجِيَّةِ. 3. ""اِتِّفَاقٌ غَيْرُ مُتَكافِئٍ بَيْنَ دَوْلَتَيْنِ تَتَخَلَّى إحْدَاهُمَا عَنْ سُلْطَتِهَا وَسِيادَتِهَا مُقَابِلَ الدِّفَاعِ عَنْهَا وَالقِيَامِ بِإِصْلاحَاتٍ. ""عَرَفَ الْمَغْرِبُ عَهْدَ الحِمَايَةِ مِنْ سَنَةِ 1912 إلَى سَنَةِ 1955"" : نِظَامٌ جَعَلَ الْمَغْرِبَ خَاضِعاً لإِدَارَةِ فَرَنْسَا وَسُلْطَتِهَا ""نَادَى الشَّعْبُ بِالحُرِّيَّةِ وَالاسْتِقلالِ وَبِسُقُوطِ الحِمَايَةِ وَالاسْتِغْلالِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20341, 'حِمْيَةٌ', 'حمية', 'مصدر', 'حمي', 'حمية', 'حمة', 'مص. حَمَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حِمْيَةٌ-حِمْيَةٌ [ح م ي] (مص. حَمَى). 1. ""مَكَانٌ مُقَدَّسٌ هُوَ فِي حِمْيَةِ أَهْلِهِ"" : مَكَانٌ مَحْمِيٌّ. 2. ""نَصَحَهُ الطَّبِيبُ بِاتِّبَاعِ حِمْيَةٍ صارِمَةٍ"" : الامْتِناعُ عَنْ طَعامٍ لِما يُسَبِّبُهُ مِنْ ضَرَرٍ أو سُمْنَةٍ. ""الْمَعِدَةُ بَيْتُ الدَّاءِ وَالحِمْيَةُ رَأْسُ كُلِّ دَواءٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20342, 'حُنُوٌّ', 'حنو', 'مصدر', 'حنو', 'حنو', 'حن', 'مص. حَنَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حُنُوٌّ-حُنُوٌّ [ح ن و] (مص. حَنَا). ""فِي قَلْبِهِ حُنُوٌّ"" : عَطْفٌ، شَفَقَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20343, 'حِنْثٌ', 'حنث', 'مصدر', 'حنث', 'حنث', 'حنث', 'مص. حَنِثَ', '', '', 'مفرد', 'DnN', '', '', '"أحْنَاثٌ"', '', 'R', '', '', '', '', '', '', '"(مص. حَنِثَ). ""اِرْتَكَبَ حِنْثاً"" : إثْماً، ذَنْباً. ""يَتَحرَّى أَلاَّ يُؤَدِّي قَسَمُهُ بِاللَّهِ إلَى حِنْثٍ"". (ع. غلاب)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20344, 'أحْنَاثٌ', 'أحناث', 'مصدر', '', 'ءحناث', 'حنث', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20345, 'حَنَقٌ', 'حنق', 'مصدر', 'حنق', 'حنق', 'حنق', 'مص. حَنِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَنَقٌ-حَنَقٌ [ح ن ق] (مص. حَنِقَ). ""اِشْتَدَّ حَنَقُهُ"" : غَضَبُهُ، غَيْظُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20346, 'حَنٌّ', 'حن', 'مصدر', 'حنن', 'حن', 'حن', 'مص. حَنَّ، يَحُنُّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَنٌّ-حَنٌّ [ح ن ن] (مص. حَنَّ، يَحُنُّ). 1. ""أظْهَرَ حَنّاً"": عَطْفاً. 2. ""وَلَدٌ حَنٌّ"" : بِهِ جُنُونٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20347, 'حَنَانٌ', 'حنان', 'مصدر', 'حنن', 'حنان', 'حنن', 'مص. حَنَّ، يَحِنُّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَنَانٌ-حَنَانٌ [ح ن ن] (مص. حَنَّ، يَحِنُّ). 1. ""فِي كَلاَمِهَا حَنَانٌ وَرِقَّةٌ"" : عَطْفٌ، رَحْمَةٌ، رِقَّةٌ. 2.""حَنَانُكَ يَارَبُّ"" : رَحْمَتُكَ، عَطْفُكَ يَارَبُّ. ""حَنَانَيْكَ يَارَبُّ"". 3.""حَنَانٌ"" : اِسْمُ عَلَمٍ للإنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20348, 'حَوْجَلَةٌ', 'حوجلة', 'مصدر', 'حجل', 'حوجلة', 'حجلة', 'مص. حَوْجَلَ', '', '', 'مفرد', 'DnN', '', '', '"حَوَاجِلُ"', '', 'R', '', '', '', '', '', '', '"(مص. حَوْجَلَ).1.""حَوْجَلَةُ العَيْنِ"" : غَوْرُها .2. قِنِّينَةٌ صَغِيرَةٌ وَاسِعَةُ الرّأْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20349, 'حَيَواتٌ', 'حيوات', 'مصدر', '', 'حيوات', 'حت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20350, 'تَحْوِيشٌ', 'تحويش', 'مصدر', 'حوش', 'تحويش', 'تحش', 'مص. حَوَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْوِيشٌ-تَحْوِيشٌ [ح و ش] . (مص. حَوَّشَ). ""تَحْوِيشُ الأَثَاثِ"" : تَجْمِيعُهُ. ""تَحْوِيشُ الْمَالِ"" ""تَحْوِيشُ الإِبِلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20351, 'حَوْقَلَةٌ', 'حوقلة', 'مصدر', 'حوقل', 'حوقلة', 'حقلة', 'مص. حَوْقَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"حَوْقَلَةٌ-حَوْقَلَةٌ [ح و ق ل] (مص. حَوْقَلَ). 1.""اِلْتَجَأَ إلى الحَوْقَلَةِ بَعْدَما سُدَّتِ الأَبْوابُ في وَجْهِهِ"" : تَرْديدُ عِبارَةِ ""لاَ حَوْلَ وَلاقُوَّةَ إِلاَّ بِاللَّهِ""، وَهْيَ اخْتِزالٌ لَها. ‌2.""حَوْقَلَةٌ"" : قارورَةٌ طَويلَةُ العُنُقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20352, 'تَحْوِيلٌ', 'تحويل', 'مصدر', 'حول', 'تحويل', 'تحل', 'مص. حَوَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْوِيلٌ-تَحْوِيلٌ [ح و ل] (مص. حَوَّلَ). 1.""تَحْوِيلُ الأَثَاثِ مِنْ غُرْفَةٍ إِلَى غُرْفَةٍ أُخْرَى"" : نَقْلُهُ. 2.""تَحْوِيلُ الوَجْهِ"" : غَضُّ الطَّرْفِ. 3.""تَحْوِيلُ الهَدَفِ"" : تَغَيُّرُ اتِّج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20353, 'حَوَلٌ', 'حول', 'مصدر', 'حول', 'حول', 'حل', 'مص. حَوِلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حَوَلٌ-حَوَلٌ [ح و ل] (مص. حَوِلَ). ""لُوحِظَ حَوَلٌ فِي عَيْنَيْهِ"" : اخْتِلاَفُ مِحْوَرَيِ العَيْنَيْنِ، أَيْ مَيْلُ إِحْدى الحَدَقَتَيْنِ إلَى أَسْفَلِ الأنْفِ وَالأُخْرَى إلَى الصُّدْغِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20354, 'تَحْوِيمٌ', 'تحويم', 'مصدر', 'حوم', 'تحويم', 'تحم', 'مص. حَوَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَحْوِيمٌ-تَحْوِيمٌ [ح و م] (مص. حَوَّمَ). 1.""تَحْوِيمُ الطًّائِرِ فِي الفَضَاءِ"" : اِسْتِدَارَتُهُ. 2.""التَّحْوِيمُ فِي الأَمْرِ"" : اِسْتِدَامَةُ النَّظَرِ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20355, 'تَحِيَّةٌ', 'تحية', 'مصدر', 'حيي', 'تحية', 'تحة', 'مص. حَيَّا', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَحَايَا"', '', '', '', '', '', '', '', '', '"(مص. حَيَّا). 1.""تَحِيَّةٌ صَادِقَةٌ، حَارَّةٌ أَخَوِيَّةٌ"" : سَلاَمٌ. النساء آية 86 إِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا (قرآن) ""إِلَيْكَ تَحِيَّاتِي الصَّادِقَةَ"". 2.""قَدَّمَتِ الفِرْقَةُ العَسْك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20356, 'تَحَايَا', 'تحايا', 'مصدر', '', 'تحايا', 'تح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20357, 'حَيَاءٌ', 'حياء', 'مصدر', 'حيي', 'حياء', 'ح', 'مص. حَيِيَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"حَيَاءٌ-حَيَاءٌ [ح ي ي] (مص. حَيِيَ). 1. ""يَتَّسِمُ بِالحَيَاءِ وَالوَقَارِ"" : الاحْتِشَامِ، الاسْتِحْياءِ. ""لاَ حَيَاءَ فِي الدِّينِ"". 2.""هُوَ قَلِيلُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20358, 'حَيَاةٌ', 'حياة', 'مصدر', 'حيي', 'حياة', 'حة', 'مص. حَيِىَ', '', '', 'مفرد', 'DnN', '', '', '"حَيَواتٌ"', '', 'Rw', '', '', '', '', '', '', '"(مص. حَيِىَ). 1.""قَضَى حَيَاتَهُ رَحِمَهُ اللَّهُ فِي تَعَبٍ وَكَدٍّ"" : مَرْحَلَةٌ مَا بَيْنَ الوِلاَدَةِ وَالْمَوْتِ، الأَيَّامُ وَالسِّنُونَ. تَعَبٌ كُلُّها الحَيَاةُ فَمَـا أعْـ*ـجَبُ إلاَّ مِنْ رَاغِبٍ فِـي ازْدِيـاد (المعريِ). عَاشَ حَياةً هَادِئَةً"" ""قَضَى حَيَاتَهُ فِي الجِدِّ"". 2. ""مَا يَزَالُ عَلى قَيْدِ الحَيَاةِ"" : مَا يَزَالُ حَيّاً. ""بَيْنَ الحَيَاةِ وَالْمَوْتِ"". 3.""مُسْتَوى الحَيَاةِ"" : مُسْتَوى وَاقِعِ مَعِيشَةِ الإِنْسَانِ وَنشَاطِهِ. ""ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20359, 'مُخَاضَعَةٌ', 'مخاضعة', 'مصدر', 'خضع', 'مخاضعة', 'مخضعة', 'مص. خَاضَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخَاضَعَةٌ-مُخَاضَعَةٌ [خ ض ع] (مص. خَاضَعَ). "" أَظْهَرَ مُخَاضَعَةً لِنَيْلِ مَا يُرِيدُهُ"" : اللُّيُونَةُ وَالخُضُوعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20360, 'خَيْبَةٌ', 'خيبة', 'مصدر', 'خيب', 'خيبة', 'خبة', 'مص. خَابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خَيْبَةٌ-خَيْبَةٌ [خ ي ب] (مص. خَابَ). ""كَانَتْ خَيْبَتُهُ كَبِيرَةً"": الخُسْرَانُ، عَدَمُ تَحَقُّقِ الأَمَلِ، الإِخْفَاقُ. ""أُصِيبَ بِخَيْبَةِ أَمَلٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20361, 'مخُاَتَلَةٌ', 'مخاتلة', 'مصدر', 'ختل', 'مخاتلة', 'مختلة', 'مص. خَاتَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مخُاَتَلَةٌ-مخُاَتَلَةٌ [خ ت ل] (مص. خَاتَلَ). ""نَهَاهُ عَنْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20362, 'خِدَاعٌ', 'خداع', 'مصدر', 'خدع', 'خداع', 'خدع', 'مص. خَادَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خِدَاعٌ-خِدَاعٌ [خ د ع] (مص. خَادَعَ). 1. ""إِيَّاك وَخِدَاعَ النَّاسِ"" : مَكْر، غِشّ، حِيلَة، "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20363, 'مُخَادَعَةٌ', 'مخادعة', 'مصدر', 'خدع', 'مخادعة', 'مخدعة', 'مص. خَادَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخَادَعَةٌ-مُخَادَعَةٌ [خ د ع] (مص. خَادَعَ). ""مُخَادَعَةُ العَدُوِّ"": مُرَاوَغَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20364, 'خُوَارٌ', 'خوار', 'مصدر', 'خور', 'خوار', 'خر', 'مص. خَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خُوَارٌ-خُوَارٌ [خ و ر] (مص. خَارَ). 1.""كُنَّا نَسْمَعُ خُوَارَ البَقَرِ"": أيْ صَوْتَ البَقَرِ.طه آية 88 فأَخْرَجَ لَهُمْ عِجْلاً جَسَداً لَهُ خُوَار (قرآن). 2.""اِخْتَلَطَ خُوَارُ الغَنَمِ وَالظِّبَاءِ وَسَطَ الحَظِيرَةِ"": صَوْتُ كُلٍّ مِنَ الغَنَمِ وَالظِّبَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20365, 'خِيرَةٌ', 'خيرة', 'مصدر', 'خير', 'خيرة', 'خرة', 'مص. خَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خِيرَةٌ-خِيرَةٌ، خِيَرَةٌ [خ ي ر] (مص. خَارَ). ""مِنْ خِيرَةِ النَّاسِ"" : مِنْ أَفْضَلِهِمْ. ""هُوَ خِيرَةُ اللَّهِ مِنْ خَلْقِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20366, 'خِصَامٌ', 'خصام', 'مصدر', 'خصم', 'خصام', 'خصم', 'مص. خَاصَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خِصَامٌ-خِصَامٌ [خ ص م] (مص. خَاصَمَ). ""حَصَلَ خِصَامٌ بَيْنَهُمَا"" : خِلاَفٌ، نِزَاعٌ، جِدَالٌ، مُنَازَعَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20367, 'مُخَاصَمَةٌ', 'مخاصمة', 'مصدر', 'خصم', 'مخاصمة', 'مخصمة', 'مص. خَاصَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخَاصَمَةٌ-مُخَاصَمَةٌ [خ ص م] (مص. خَاصَمَ). ""بَيْنَهُمَا مُخَاصَمَةٌ شَدِيدَةٌ"" : مُنَازَعَةٌ، نِزَاعٌ، مُعَادَاةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20368, 'خَوْضٌ', 'خوض', 'مصدر', 'خوض', 'خوض', 'خض', 'مص. خَاضَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَوْضٌ-خَوْضٌ [خ و ض] (مص. خَاضَ). ""لاَ يُحِبُّ الخَوْضَ فِي القَضَايَا الَّتِي لاَ عِلْمَ لَهُ بِهَا"" : البَحْثَ وَالحَدِيثَ فِيهَا، مُنَاقَشَتَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20369, 'خَيْلٌ', 'خيل', 'مصدر', 'خيل', 'خيل', 'خل', 'مص. خَالَ', '', '', 'مفرد', 'DnN', '', '', '"خُيُولٌ:أَخْيَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. خَالَ). 1.""يُحِبُّ رُكُوبَ الخَيْلِ"" : الأَفْرَاس لاَ وَاحِدَ لَهُ مِنْ لَفْظِهِ. 2.""يُشَاهِدُ سِبَاقَ الخَيْلِ"" : مُسَابَقَةُ الخُيُولِ. ""مَيْدَانُ الخَيْلِ"" ""الخَيْلُ أَعْلَمُ بِفُرْسَانِهَا"" (مثل). 3.""أَظْهَرَ خَيْلاً"" : تَكَبُّراً وَإِعْجَاباً بِالنَّفسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20370, 'خِطَابٌ', 'خطاب', 'مصدر', 'خطب', 'خطاب', 'خطب', 'مص. خَاطَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خِطَابٌ-خِطَابٌ [خ ط ب] (مص. خَاطَبَ). 1. ""أَلْقَى خِطَاباً أَمَامَ جُمْهُورٍ غَفِيرٍ"" : مَا يُلْقِيهِ الْخَطِيبُ مِنْ كَلاَمٍ، حَدِيثٌ أَمَامَ النَّاسِ. ""سَيُلْقِي الْمَلِكُ خِطَابَ الْعَرْشِ"" : حَدِيثٌ مُطَوَّلٌ يَسْتَعْرِضُ فِيهِ الْمَلِكُ الْمُنْجَزَاتِ وَالْقَضَايَا السِّيَاسِيَّةَ الْهَامَّةَ الَّتِي عرفَتْها البِلادُ. 2. ""فَصْلُ الْخِطَابِ"" : كَلاَمٌ تُوَضَّحُ بِهِ قَضِيَّةٌ مُعَلَّقَةٌ أَوْ مُشْكِلَةٌ وَيَكُونُ حُكْماً بَيِّناً.ص آية 20 وَآتَيْنَاهُ الحِكْمَةَ وَفَصْلَ الْخِطَابِ (قرآن). 3. ""أَرْسَلَ لَهُ خ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20371, 'مُخَاطَبَةٌ', 'مخاطبة', 'مصدر', 'خطب', 'مخاطبة', 'مخطبة', 'مص. خَاطَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخَاطَبَةٌ-مُخَاطَبَةٌ [خ ط ب] (مص. خَاطَبَ). 1.""مخُاَطَبَةُ الجُمْهُورِ"" : التَّوَجُّهُ إِلَيْهِ بِالْحَدِيثِ. 2.""مُخَاطَبَةٌ هَاتِفِيَّةٌ"" : مُخَابَرَةٌ، مُكَالَمَةٌ، مُحَادَثَةٌ. 3.""مُخَاطَبَةُ النَّفْسِ"" : الْحَدِيثُ الدَّاخِلِيُّ بَيْنَ الإِنْسَانِ وَنَفْسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20372, 'مُخَاطَرَةٌ', 'مخاطرة', 'مصدر', 'خطر', 'مخاطرة', 'مخطرة', 'مص. خَاطَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. خَاطَرَ). ""تَجَنَّبِ الْمُخَاطَرَةَ بِحَيَاتِكَ"" : تَجَنَّبْ تَعْرِيضَ حَيَاتِكَ لِلْهَلاَكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20373, 'خَوْفٌ', 'خوف', 'مصدر', 'خوف', 'خوف', 'خف', 'مص. خَافَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَوْفٌ-خَوْفٌ [خ و ف] (مص. خَافَ). 1. ""اِعْتَرَاهُ خَوْفٌ"": فَزَعٌ، خَشْيَةٌ، رُعْبٌ. ""دَخَلَ إِلى الْمَعْرَكَةِ بِلاَ خَوْفٍ"". 2. ""لَمْ يَكُنْ خَوْفُهُ نَاتِجاً عَنْ ضَعْفٍ"" : اِنْفِعَالٌ فِي النَّفْسِ يُحْدِثُ اضْطِرَاباً وَخَشْيَةً. 3. ""خَوْفاً مِنَ الْمَشَاكِلِ لَمْ..."" : خَشْيَةً. 4. ""خَوْفاً عَلَيْهِ"" : حِرْصاً عَلَيْهِ مِنْ...، قَلَقاً عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20374, 'خِيفَةٌ', 'خيفة', 'مصدر', 'خوف', 'خيفة', 'خفة', 'مص. خَافَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خِيفَةٌ-خِيفَةٌ [خ و ف] (مص. خَافَ). ""اِسْتَوْلَتْ عَلَيْهِ الخِيفَةُ"" : حَالَةُ الخَوْفِ، حَالَةُ الخَائِفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20375, 'مَخَافَةٌ', 'مخافة', 'مصدر', 'خوف', 'مخافة', 'مخفة', 'مص. خَافَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَخَاوِفُ"', '', 'R', '', '', '', '', '', '', '"(مص. خَافَ). ""مخَافَةَ أَنْ يَطْعَنَهُ مِنَ الخَلْفِ"" : خَشْيَةَ أَنْ... ""رَأْسُ الحِكْمَةِ مخَافَةُ اللهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20376, 'مَخَاوِفُ', 'مخاوف', 'مصدر', '', 'مخاوف', 'مخف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20377, 'خِلاَلٌ', 'خلال', 'مصدر', 'خلل', 'خلال', 'خلل', 'مص. خَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '"أَخِلَّةٌ"', '', 'R', '', '', '', '', '', '', '"(مص. خَالَ). 1. ""فِي خِلاَلِ ذَلِكَ"" : فِي أَثْنَاءِ ذَلِكَ. ""مِنْ خِلاَلِ ذَلِكَ"". 2.""سَارُوا خِلاَلَ الأَزِقَّةِ"" : سَارُوا وَتَنَقَّلُوا بَيْنَهَا، أَيْ حَوْلَ حُدُودِهَا أَوْ مَا بَيْنَ بُيُوتِهَا. ""خِلاَلَ الدِّيَارِ"". 3. ""يَتَأَمَّلُ خِلاَلَ السُّطُورِ"": مَا وَرَاءهَا. 4. ""خِلاَلُ الأَسْنَانِ"" : العُودُ تُخَلَّلُ بِهِ الأَسْناَنُ. 5.""خِلاَلُ الطَّعَامِ"" : بَقِيَّةُ الطَّعَامِ بَينَ الأَسْنَانِ. 6.""شَدَّتْ غَسِيلَهَا بِأَخِلَّةٍ عَلَى الحَبْلِ"" : (جَمْع خِلاَل) : لَوْحَتانِ صَغيرَتانِ مُنْفَرِجَتانِ تَشُدَّانِ الْغَسِيلَ عَلَى الحَبْلِ. 7.""ضَمَّ الأَوْرَاقَ بِخِلاَلٍ"": دَبُّوسٌ لِرَبْطِ الأَوْرَاقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20378, 'أَخِلَّةٌ', 'أخلة', 'مصدر', '', 'ءخلة', 'خلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20379, 'مُخَامَرَةٌ', 'مخامرة', 'مصدر', 'خمر', 'مخامرة', 'مخمرة', 'مص. خَامَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخَامَرَةٌ-مُخَامَرَةٌ [خ م ر] (مص. خَامَرَ). 1.""اِسْتَمَرَّتْ مُخَامَرَةُ الدَّاءِ فِي الجِسْمِ"" : اِنْتِشَارُهُ. 2.""لَمْ تَكُنْ مُخَامَرَةُ الشَّكِّ لِتُبْعِدَهُ عَنِ الْحَقِيقَةِ"" : مُسَاوَرَتُهُ، مُرَاوَدَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20380, 'خُيُولٌ', 'خيول', 'مصدر', '', 'خيول', 'خل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20381, 'أَخْيَالٌ', 'أخيال', 'مصدر', '', 'ءخيال', 'خل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20382, 'مُخَالَجَةٌ', 'مخالجة', 'مصدر', 'خلج', 'مخالجة', 'مخلجة', 'مص. خَالَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخَالَجَةٌ-مُخَالَجَةٌ [خ ل ج] (مص. خَالَجَ). ""مُخَالَجَةُ النَّفْسِ"": مُسَاوَرَتُهَا، مُخَامَرَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20383, 'مُخَالَسَةٌ', 'مخالسة', 'مصدر', 'خلس', 'مخالسة', 'مخلسة', 'مص. خَالَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخَالَسَةٌ-مُخَالَسَةٌ [خ ل س] (مص. خَالَسَ). ""مُخَالَسَةُ النَّظَرِ"": النَّظَرُ خِلْسَةً. ""تَجَنَّبْ يَا بُنَيَّ مُخَالَسَةَ النَّظَرِ لِجَارَتِكَ فَإِنَّهَا مِنْ زِنَى العَيْنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20384, 'خِلاَطٌ', 'خلاط', 'مصدر', 'خلط', 'خلاط', 'خلط', 'مص. خَالَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خِلاَطٌ-خِلاَطٌ [خ ل ط] (مص. خَالَطَ). ""خِلاَطٌ فِي السُّوقِ"": اِخْتَلاَطُ النَّاسِ وَالْمَوَاشِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20385, 'مُخَالَطَةٌ', 'مخالطة', 'مصدر', 'خلط', 'مخالطة', 'مخلطة', 'مص. خَالَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخَالَطَةٌ-مُخَالَطَةٌ [خ ل ط] (مص. خَالَطَ). 1.""مُخَالَطَةُ الأَشْرَارِ تُسَبِّبُ البَلاَءَ"" : مُعَاشَرَتُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20386, 'خِلاَفٌ', 'خلاف', 'مصدر', 'خلف', 'خلاف', 'خلف', 'مص. خَالَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خِلاَفٌ-خِلاَفٌ [خ ل ف] (مص. خَالَفَ). 1. ""بَيْنَهُمَا خِلاَفٌ"" : نِزَاعٌ، خُصُومَةٌ. ""سَوَّى الخِلاَفَ بَيْنَهُمَا"" ""إِنَّهُ خِلاَفٌ عَابِرٌ"". 2. ""بِخِلاَفِ مَا كُنْتُ أَعْتَقِدُ"" : بِعَكْسِ... ""عَلَى خِلاَفِ ذَلِكَ"" ""خِلاَفاً لأَوَامِرِهِ"". 3. ""جَاءَ خِلاَفَهُ"" : بَعْدَهُ.الإسراء آية 76 وَإِذاً لا يَلْبَثُونَ خِلاَفَكَ إِلاَّ قَلِيلاً(قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20387, 'مُخَالَفَةٌ', 'مخالفة', 'مصدر', 'خلف', 'مخالفة', 'مخلفة', 'مص. خَالَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. خَالَفَ). 1.""مُخَالَفَةُ القَانُونِ"" : اِرْتِكَابُ عَمَلٍ مُضَادٍّ لِلْقَانُونِ. 2.""مُخَالَفَةُ سَيْرٍ"" : اِرْتِكَابُ عَمَلٍ يُخِلُّ بِقَوَانِينِ السَّيْرِ. ""مَحْضَرُ مُخَالَفَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20388, 'خِيَامٌ', 'خيام', 'مصدر', 'خيم', 'خيام', 'خم', 'مص. خَامَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خِيَامٌ-خِيَامٌ [خ ي م] (مص. خَامَ). ""أُقِيمَتِ الْخِيَامُ حَوْلَ الْمَرَاعِي"" : الأَخْبِيَةُ، الْهَوَادِجُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20389, 'خَبَالٌ', 'خبال', 'مصدر', 'خبل', 'خبال', 'خبل', 'مص. خَبِلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خَبَالٌ-خَبَالٌ [خ ب ل] (مص. خَبِلَ). 1. ""سَقَاهُ خَبَالاً"" : سُمّاً قَاتِلاً. 2.""تَسَبَّبَ لَهُ فِي الْخَبَالِ"" : فِي الهَلاَكِ. التوبة آية 47 لَوْ خَرَجُوا فِيكُمْ مَا زَادُوكُمْ إِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20390, 'خِيَانَةٌ', 'خيانة', 'مصدر', 'خون', 'خيانة', 'خنة', 'مص. خان', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خِيَانَةُ-خِيَانَةُ [خ و ن] (مص. خان). 1. ""خِيَانَةُ الأَمَانَةِ"" : عَدَمُ صِيَانَتِهَا، نَقْضُهَا. 2. ""أَمِنْ عَادَتِهِ خِيَانَةُ الْوَعْدِ أَوِ العَهْدِ"" : الإِخْلاَفُ وَعَدَمُ الوَفَاءِ. 3. ""لَيْسَ هُنَاكَ مَا هُوَ أَدْهَى مِنْ خِيَانَةِ الوَطَنِ"" : التَّآمُرُ عَلَى الوَطَنِ مَعَ الْعَدُوِّ أَوْ دَوْلَةٍ أَجْنَبِيَّةٍ. ""اُتُّهِمَ الْجَاسُوسُ بِالخِيَانَةِ الْعُظْمَى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20391, 'مُخَايَرَةٌ', 'مخايرة', 'مصدر', 'خير', 'مخايرة', 'مخرة', 'مص. خَايَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخَايَرَةٌ-مُخَايَرَةٌ [خ ي ر] (مص. خَايَرَ). ""تَرَكَ لَهُ مَجَالَ الْمُخَايَرَةِ"" : مَجَالَ الاخْتِيَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20392, 'خِبٌّ', 'خب', 'مصدر', 'خبب', 'خب', 'خب', 'مص. خَبَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خِبٌّ-خِبٌّ، خَبٌّ [خ ب ب] (مص. خَبَّ). 1.""رَجُلٌ خِبٌّ"" : خَدَّاعٌ. ""لاَ يَدْخُلُ الْجَنَّةَ خِبٌّ وَلاَ خَائِنٌ"". 2.""عَمَلٌ فِيهِ خَبٌّ"" : فِيهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20393, 'خَبْءٌ', 'خبء', 'مصدر', 'خبأ', 'خبء', 'خب', 'مص. خَبَأَ', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"خَبْءٌ-خَبْءٌ [خ ب أ] (مص. خَبَأَ). ""تَرَكَ الشَّيْءَ خَبْئاً"" : مُدَّخَراً أَوْ مَخْبُوءاً.النمل آية 25 الَّذِي يُخْرِجُ الْخَبْءَ فِي السَّمَوَاتِ وَالأَرْض"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20394, 'خَبَرٌ', 'خبر', 'مصدر', 'خبر', 'خبر', 'خبر', 'مص. خَبَرَ', '', '', 'مفرد', 'DnN', '', '', '"أخْبَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. خَبَرَ). 1.""جَاءَهُ بِخَبَرٍ لاَ عِلْمَ لَهُ بِهِ"" : مَا يَحْدُثُ وَيُصْبِحُ مَعْلُومَةً تُنْقَلُ، وَيُحَدَّثُ بِهِ شَفَوِيّاً أوْ كِتَابَةً. سَتُبْدِي لَكَ الأيَّامُ مَا كُنْتَ جَاهِلاً*وَيَأتِيكَ بِالأخْبَارِ مَنْ لَمْ تُزَوِّدِ (طرفة بن العبد).1.""قَرَأَ آخِرَ خَبَرٍ فِي الْجَرِيدَةِ"". 2. ""يَسْتَمِعُ إِلى نَشْرَةِ الأَخْبَارِ"" : الْجَرِيدَةُ الإِخْبَارِيَّةُ الَّتِي تَنْقُلُهَا الإِذَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20395, 'أخْبَارٌ', 'أخبار', 'مصدر', '', 'ءخبار', 'خبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20396, 'خِبْرَةٌ', 'خبرة', 'مصدر', 'خبر', 'خبرة', 'خبرة', 'مص. خَبَرَ، خَبُرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. خَبَرَ، خَبُرَ). 1.""تَكَوَّنَتْ لَدَيْهِ خِبْرَةٌ فِي عَمَلِهِ"" : تَجْرِبَةٌ. ""الْخِبْرَةُ تَفُوقُ الْمَعْرِفَةَ"". 2. ""أَصْبَحَ مِنْ ذَوِي الْخِبْرَةِ فِي عِلْمِ الإِلِكْتُرُونِيَّاتِ"" : عَالِماً يَعْرِفُ أسْرَارَهَا وَكُنْهَهَا وَمَا يَتَعَلَّقُ بِهَا. ""أهْلُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20397, 'خُبْرَةٌ', 'خبرة', 'مصدر', 'خبر', 'خبرة', 'خبرة', 'مص. خَبَرَ، خَبُرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خُبْرَةٌ-خُبْرَةٌ (مص. خَبَرَ، خَبُرَ). ن. الْخِبْرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20398, 'خُبْزٌ', 'خبز', 'مصدر', 'خبز', 'خبز', 'خبز', 'مص. خَـبَـزَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خُبْزٌ-خُبْزٌ [خ ب ز] (مص. خَـبَـزَ). ""هَيَّأتِ الخُـبْزَ"" : مَا يُعْمَلُ مِنَ الدَّقِيقِ وَالْمَاءِ يُعْجَنُ وَيُشْوَى فِي الْفُرْنِ، وَهُوَ نَوْعانِ : مُسْتَدِيرٌ وَمُسْتَطِيلٌ. ""مَنْ يَفْلَحْ أرْضَهُ يَشْبَعْ خُبْزًا""(مثل) ""يَضْمَنُ بَعْدَ طُولِ عَنَاءٍ كِسْرَةَ خُبْزٍ لأَبْنَائِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20399, 'خَبَلٌ', 'خبل', 'مصدر', 'خبل', 'خبل', 'خبل', 'مص. خَبِلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَبَلٌ-خَبَلٌ [خ ب ل] (مص. خَبِلَ). ""أصَابَهُ الْخَبَلُ"" : مَسٌّ مِنَ الجُنُونِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20400, 'خِتَامٌ', 'ختام', 'مصدر', 'ختم', 'ختام', 'ختم', 'مص. خَتَمَ', '', '', 'مفرد', 'DnN', '', '', '"خُتُمٌ"', '', 'R', '', '', '', '', '', '', '"(مص. خَتَمَ). 1. ""وَفِي الْخِتَامِ أدْعُو لَكُمْ بِالتَّوْفِيقِ"" : وَفِي الأخِيرِ. 2. ""حَضَرَ جَلْسَةَ الْخِتَامِ"" : آخِرَ جَلْسَةٍ فِي مُؤتَمَرٍ أوْ نَدْوَةٍ. 3.""خِتَامُ الحَدِيثِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20401, 'خُتُمٌ', 'ختم', 'مصدر', '', 'ختم', 'ختم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20402, 'خَتْمٌ', 'ختم', 'مصدر', 'ختم', 'ختم', 'ختم', 'مص. خَتَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَتْمٌ-خَتْمٌ [خ ت م] (مص. خَتَمَ). 1.""وَضَعَ خَتْمَ طَابَعِهِ عَلَى الوَثِيقَةِ"" : الطَّابَعُ الَّذِي يُخْتَمُ بِهِ. 2.""الْخَتْمُ الْبَرِيدِيُّ"" : مَا تَخ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20403, 'خَجَلٌ', 'خجل', 'مصدر', 'خجل', 'خجل', 'خجل', 'مص. خَجِلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَجِلٌ-خَجِلٌ [خ ج ل] (صِيغَةُ فَعِل). ""كَانَ خَجِلاً مِنْ فِعْلِهِ"": مُضْطَرِباً مِنَ الْحَيَاءِ، مُسْتَحْيِياً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20404, 'تَخْدِيرٌ', 'تخدير', 'مصدر', 'خدر', 'تخدير', 'تخدر', 'مص. خَدَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخْدِيرٌ-تَخْدِيرٌ [خ د ر] (مص. خَدَّرَ). 1. ""خَضَعَ لِتَخْدِيرٍ قَبْلَ إِجْرَاءِ عَمَلِيَّةٍ جِرَاحِيَّةٍ"" : مَادَّةٌ طِبِّيَّةٌ تُحْقَنُ فِي عُضْوٍ مِنَ الأَعْضَاءِ الْمُصَابَةِ تُفْقِدُ الإِنْسَان"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20405, 'خَدَرٌ', 'خدر', 'مصدر', 'خدر', 'خدر', 'خدر', 'مص. خَدِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَدِرٌ-خَدِرٌ [خ د ر] (صِيغَةُ فَعِل). ""رَجُلٌ خَدِرٌ"" : مُصَابٌ بِالْخَدَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20406, 'تَخْدِيشٌ', 'تخديش', 'مصدر', 'خدش', 'تخديش', 'تخدش', 'مص. خَدَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخْدِيشٌ-تَخْدِيشٌ [خ د ش] (مص. خَدَّشَ). 1.""تَخْدِيشُ الْوَجْهِ"" : خَمْشُهُ. 2.""تَخْدِيشُ الْجِلْدِ"" : قَشْرُهُ. 3.""تَخْدِيشُ الْمَرْءِ"" : عَيْبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20407, 'خَدْشٌ', 'خدش', 'مصدر', 'خدش', 'خدش', 'خدش', 'مص. خَدَشَ', '', '', 'مفرد', 'DnN', '', '', '"خُدُوشٌ:أخْدَاشٌ"', '', 'R', '', '', '', '', '', '', '"(مص. خَدَشَ). ""بَقِيَتْ آثَارُ الْخَدْشِ عَلَى خَدِّهِ"" : الْعَلاَمَاتُ الَّتِي تَتْرُكُهَا الأظَافرُ عَلَى جِسْمِ الإِنْسَانِ أو"', '');
