INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20432, 'تَخْرِيفٌ', 'تخريف', 'مصدر', 'خرف', 'تخريف', 'تخرف', 'مص. خَرَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخْرِيفٌ-تَخْرِيفٌ [خ ر ف] (مص. خَرَّفَ). ""كَلاَمُهُ كُلُّهُ تَخْرِيفٌ"" : كَلاَمُهُ كُلُّهُ خُرَافَاتٌ وَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20433, 'تَخْرِيقٌ', 'تخريق', 'مصدر', 'خرق', 'تخريق', 'تخرق', 'مص. خَرَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخْرِيقٌ-تَخْرِيقٌ [خ ر ق] (مص. خَرَّقَ). ""تَخْرِيقُ الثَّوْبِ"" : تَمْزِيقُهُ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20434, 'خَرْقٌ', 'خرق', 'مصدر', 'خرق', 'خرق', 'خرق', 'مص. خَرَقَ', '', '', 'مفرد', 'DnN', '', '', '"خُرُوقٌ"', '', 'R', '', '', '', '', '', '', '"(مص. خَرَقَ). 1.""تَرَكَتِ الْقَذِيفَةُ خَرْقاً فِي الْحَائِطِ"" : ثُقْبَةً ..... "" يَلْبَسُ ثَوْباً فِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20435, 'خُرُوقٌ', 'خروق', 'مصدر', '', 'خروق', 'خرق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20436, 'تخْرِيمٌ', 'تخريم', 'مصدر', 'خرم', 'تخريم', 'تخرم', 'مص. خَرَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تخْرِيمٌ-تخْرِيمٌ [خ ر م] (مص. خَرَّمَ). 1.""تَخْرِيمُ الجِلْدِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20437, 'خَزَرٌ', 'خزر', 'مصدر', 'خزر', 'خزر', 'خزر', 'مص. خَزِرَ ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَزَرٌ-خَزَرٌ [خ ز ر] (مص. خَزِرَ) : ضَيْقُ الْعَيْنِ وَصِغَرُهَا خِلْقَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20438, 'خَزَلٌ', 'خزل', 'مصدر', 'خزل', 'خزل', 'خزل', 'مص. خَزِلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَزَلٌ-خَزَلٌ [خ ز ل] (مص. خَزِلَ). ""أُصِيبَ بِخَزَلٍ"" : بِكَسْرٍ فِي ظَهْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20439, 'خَشٌّ', 'خش', 'مصدر', 'خشش', 'خش', 'خش', 'مص. خَشَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَشٌّ-خَشٌّ [خ ش ش] (مص. خَشَّ). 1. ""مَطَرٌ خَشٌّ "": مَطَرٌ قَلِيلٌ. 2. ""ثَوْبٌ خَشٌّ"" : ثَوْبٌ خَشِنٌ. 3.: الثُّعْبَانُ الأسْوَدُ. 4.: الرَّحَّالَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20440, 'خِزْيَةٌ', 'خزية', 'مصدر', 'خزي', 'خزية', 'خزة', 'مص. خَزِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"خِزْيَةٌ-خِزْيَةٌ [خ ز ي] (مص. خَزِيَ). ""إِنَّهَا خِزْيَةٌ مَا بَعْدَهَا مِنْ خِزْيَةٍ"" : البَلِيَّةُ، الْفَضِيحَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20441, 'خِزْيٌ', 'خزي', 'مصدر', 'خزي', 'خزي', 'خز', 'مص. خَزِيَ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"خِزْيٌ-خِزْيٌ [خ ز ي] (مص. خَزِيَ). ""يَا لَلْخِزْيِ "" : يَا لَلْعَارِ، يَا لَلْهَوَانِ وَالذُّلِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20442, 'خَسَاسَةٌ', 'خساسة', 'مصدر', 'خسس', 'خساسة', 'خسسة', 'مص. خَسَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خَسَاسَةٌ-خَسَاسَةٌ [خ س س] (مص. خَسَّ). ""عَبَّرَ عَنْ خَسَاسَتِهِ"" : حَالَةُ الْخَسِيسِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20443, 'تَخْسِيرٌ', 'تخسير', 'مصدر', 'خسر', 'تخسير', 'تخسر', 'مص. خَسَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخْسِيرٌ-تَخْسِيرٌ [خ س ر] (مص. خَسَّرَ). ""حَاوَلَ تَخْسِيرَ عَمَلِهِ"" : جَعْلَهُ خَاسِراً ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20444, 'خَسَارَةٌ', 'خسارة', 'مصدر', 'خسر', 'خسارة', 'خسرة', 'مص. خَسِرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":خَسَائِرُ"', '', 'R', '', '', '', '', '', '', '"(مص. خَسِرَ). 1.""تَعَرَّضَ التَّاجرُ لِخَسَارَةٍ كَبِيرَةٍ "" : ضَيَاع تِجَارَتِهِ. 2.""كَبَّدَ الْعَدُوَّ خَسَائِرَ فَادِحَةً فِي العَتَادِ وَالأرْوَاحِ"" : أَضْرَاراً جَسِيمَةً. 3."" يَا لَلْخَسَارَةِ "" : يَا لَلأَسَفِ، يَاحَسْرَتَاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20445, 'خَسَائِرُ', 'خسائر', 'مصدر', '', 'خساءر', 'خسر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20446, 'تَخْسِيسٌ', 'تخسيس', 'مصدر', 'خسس', 'تخسيس', 'تخسس', 'مص. خَسَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخْسِيسٌ-تَخْسِيسٌ [خ س س] (مص. خَسَّسَ). ""تَخْسِيسُ حَقِّهِ"" : الإِنْقَاصُ مِنْهُ، جَعْلُهُ دَنِيّاً حَقِيراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20447, 'خَسْفٌ', 'خسف', 'مصدر', 'خسف', 'خسف', 'خسف', 'مص. خَسَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَسْفٌ-خَسْفٌ [خ س ف] (مص. خَسَفَ). ""سَامَهُ الْخَسْفَ"": أذَاقَهُ الذُّلَّ وَالْهَوَانَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20448, 'خُسُوفٌ', 'خسوف', 'مصدر', 'خسف', 'خسوف', 'خسف', 'مص. خَسَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خُسُوفٌ-خُسُوفٌ [خ س ف] (مص. خَسَفَ). ""اِجْتَمَعَ النَّاسُ فِي السَّاحَةِ يُلاَحِظُونَ خُسُوفَ الْقَمَرِ"" : ذَهَابُ ضَوْءِ الْقَمَرِ كُلِّيّاً أَوْ جُزْئِيّاً نَتيجَةَ تَوَسُّطِ الأَرْضِ بَيْنَهُ وَبَيْنَ الشَّمْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20449, 'خَشْيَةٌ', 'خشية', 'مصدر', 'خشي', 'خشية', 'خشة', 'مص. خَشِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"خَشْيَةٌ-خَشْيَةٌ [خ ش ي] (مص. خَشِيَ). ""خَشْيَةَ أَنْ"" : مَخَافَةَ أَنْ، خَوْفا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20450, 'تَخْشِيبٌ', 'تخشيب', 'مصدر', 'خشب', 'تخشيب', 'تخشب', 'مص. خَشَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَخْشِيبٌ-تَخْشِيبٌ [خ ش ب] (مص. خَشَّبَ). ""تَخْشِيبُ اليَدِ"" : ثِقَلُهَا وَغِلَظُهَا كَأَنَّهَا خَشَبٌ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20451, 'خَشْخَشَةٌ', 'خشخشة', 'مصدر', 'خشخش', 'خشخشة', 'خشخشة', 'مص. خَشْخَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خَشْخَشَةٌ-خَشْخَشَةٌ [خ ش خ ش] (مص. خَشْخَشَ). ""خَشْخَشَةُ السِّلاَحِ"" : صَوْتُهُ. ""لَمْ نَكُنْ نَسْمَعُ إِلاَّ خَشْخَشَةَ الأَوْرَاقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20452, 'خُشُوعٌ', 'خشوع', 'مصدر', 'خشع', 'خشوع', 'خشع', 'مص. خَشَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"خُشُوعٌ-خُشُوعٌ [خ ش ع] (مص. خَشَعَ). 1. ""يُصَلِّي فِي خُشُوعٍ"" : فِي اسْتِكَانَةٍ، فِي سُكُونٍ، فِي خُضُوعٍ. 2.""خُشُوعُ القَلْبِ"" : ضَرَاعَتُهُ، سُكُونُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20453, 'خَشَفٌ', 'خشف', 'مصدر', 'خشف', 'خشف', 'خشف', 'مص. خَشِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"خَشَفٌ-خَشَفٌ [خ ش ف] (مص. خَشِفَ). 1. ""خَشَفُ النَّبَاتِ"" : يُبْسُهُ. 2. ""ثَلْجٌ خَشَفٌ"" : خَشِنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20454, 'خَشْفٌ', 'خشف', 'مصدر', 'خشف', 'خشف', 'خشف', 'مص. خَشْفٌ', '', '', 'مفرد', 'DnN', '', '', '"خُشُوفٌ:أَخْشَافٌ"', '', 'R', '', '', '', '', '', '', '"(مص. خَشْفٌ). 1. ""سَمِعَ خَشْفاً"" : صَوْتاً، حَرَكَةً. 2. ""أَصَابَهُ الْخَشْفُ"" : الذُّلُّ. 3. ""مَاءٌ خَشْفٌ"" : جَامِدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(20455, 'خُشُوفٌ', 'خشوف', 'مصدر', '', 'خشوف', 'خشف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
