INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21183, 'سَحْبٌ', 'سحب', 'مصدر', 'سحب', 'سحب', 'سحب', 'مص. سَحَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَحْبٌ-سَحْبٌ [س ح ب] (مص. سَحَبَ). ""سَحْبُ اليَانَصِيبِ"" : إجْرَاءُ القُرْعَةِ بَيْنَ الْمُشْتَرِكِينَ فِي اليَانَصِيبِ لِمَعْرِفَةِ الفَائِزِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21184, 'سِحْرٌ', 'سحر', 'مصدر', 'سحر', 'سحر', 'سحر', 'مص. سَحَرَ', '', '', 'مفرد', 'DnN', '', '', '"سُحُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. سَحَرَ). 1. ""لَمْ يَكُنْ ما جاءَ بِهِ إلا سِحْراً"" : كُلُّ أَمْرٍ أوْ عَمَلٍ يُزْعَمُ أنَّهُ خَارِقٌ للعَادَةِ وَالطَّبِيعَةِ وَلاَ يُعْرَفُ سَبَبُهُ وَيُقْصَدُ بِهِ التَّمْوِيهُ وَالخِدَاعُ. يس آية 69 وَمَا عَل"', '');
