INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21206, 'تَسْدِيسٌ', 'تسديس', 'مصدر', 'سدس', 'تسديس', 'تسدس', 'مص. سَدَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْدِيسٌ-تَسْدِيسٌ [س د س] (مص. سَدَّسَ). 1.""تَسْدِيسُ عَدَدٍ"": ضَرْبُهُ فِي سِتَّةٍ. 2.""تَسْدِيسُ شَكْلٍ هَنْدَسِيٍّ"" : جَعْلُهُ سِتَّةَ أَضْلاَعٍ، أَوْ أَرْكَانٍ أَوْ زَوَايَا لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21207, 'تَسْدِيلٌ', 'تسديل', 'مصدر', 'سدل', 'تسديل', 'تسدل', 'مص. سَدَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْدِيلٌ-تَسْدِيلٌ [س د ل] (مص. سَدَّلَ). ""تَسْدِيلُ الشَّعْرِ"" : إِرْخَاؤُهُ، إِنْزَالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21208, 'سَدَلٌ', 'سدل', 'مصدر', 'سدل', 'سدل', 'سدل', 'مص. سَدِلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَدَلٌ-سَدَلٌ [س د ل] (مص. سَدِلَ). ""لاَحَظَ الجِدَارَ فِي سَدَلٍ"" : فِي مَيَلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21209, 'سَدْيٌ', 'سدي', 'مصدر', 'سدي', 'سدي', 'سد', 'مص. سَدى', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"سَدْيٌ-سَدْيٌ [س د ي] (مص. سَدى). ""سَدْيُ الثَّوْبِ"" : إقَامَةُ سدَاهُ، أَيْ تَرْتِيبُ خُيُوطِهِ الطَّوِيلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21210, 'تَسْرِيبٌ', 'تسريب', 'مصدر', 'سرب', 'تسريب', 'تسرب', 'مص. سَرَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْرِيبٌ-تَسْرِيبٌ [س ر ب] (مص. سَرَّبَ). 1.""تَسْرِيبُ خَبَرٍ"": إِمْرَارُهُ خُف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21211, 'سَرَبٌ', 'سرب', 'مصدر', 'سرب', 'سرب', 'سرب', 'مص. سَرِبَ', '', '', 'مفرد', 'DnN', '', '', '"أَسْرَابٌ"', '', 'R', '', '', '', '', '', '', '"(مص. سَرِبَ). 1.""سَرَبُ الإنَاءِ"" : الْمَاءُ السَّائِلُ مِنْهُ. 2.""جَرَتِ المِيَاهُ فِي السَّرَبِ"" : قَنَاةٌ تَدْخُلُ مِنهَا المِيَاهُ . ""فَحَفَرَتْ لَهُ مِنَ البَيْتِ سَرَباً إلَى الطَّرِيقِ فَجَعَلَتْ مَخْرَجَهُ عِنْدَ جُبِّ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21212, 'أَسْرَابٌ', 'أسراب', 'مصدر', '', 'ءسراب', 'سرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21213, 'تَسْرِيجٌ', 'تسريج', 'مصدر', 'سرج', 'تسريج', 'تسرج', 'مص. سَرَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْرِيجٌ-تَسْرِيجٌ [س ر ج] (مص. سَرَّجَ). ""تَسْرِيجُ الجَوَادِ"" : وَضْعُ السَّرْجِ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21214, 'تَسْرِيحٌ', 'تسريح', 'مصدر', 'سرح', 'تسريح', 'تسرح', 'مص. سَرَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْرِيحٌ-تَسْرِيحٌ [س ر ح] (مص. سَرَّحَ). 1.""أُعْلِنَ عَنْ تَسْرِيحِ الجُنْدِ"" : عَنْ إِعْفَائِهِمْ مِنَ الجُنْدِيَّةِ. 2.""ذَهَبَتْ ع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21215, 'سَرْدٌ', 'سرد', 'مصدر', 'سرد', 'سرد', 'سرد', 'مص. سَرَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَرْدٌ-سَرْدٌ [س ر د] (مص. سَرَدَ). 1. ""اِكْتَفَى بِسَرْدِ الأسْبَابِ"" : بِذِكْرِ سِيَاقِهَا وَتَتَابُعِهَا. 2. ""قَدَّمَ سَرْداً عَنِ الحَادِثَةِ"" : أَخْبَاراً مُتَتَابِعَةً عَنْ وَق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21216, 'سُرُورٌ', 'سرور', 'مصدر', 'سرر', 'سرور', 'سرر', 'مص. سَرَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سُرُورٌ-سُرُورٌ [س ر ر] (مص. سَرَّرَ). ""أَدْخَلَ عَلَى قَلْبِهِ السُّرُورَ"" : الفَرَحَ، البَهْجَةَ، الحُبُورَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21217, 'سُرْعَةٌ', 'سرعة', 'مصدر', 'سرع', 'سرعة', 'سرعة', 'مص. سَرِعَ، سَرُعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سُرْعَةٌ-سُرْعَةٌ [س ر ع] (مص. سَرِعَ، سَرُعَ). 1. ""جَاءَ بِسُرْعَةٍ"" : أيْ جَاءَ عَلَى عَجَلَةٍ مِنْ أَمْرِهِ. ""أَنْجَزَ عَمَلَهُ بِسُرْعَةٍ فَائِقَةٍ"". 2. ""اِنْتَبِهْ ! إنَّ السُّرْعَةَ مَحْدُودَةٌ"" : السَّيْرُ السَّرِيعُ بِالسَّيَّارَةِ. 3.""يَمْتَازُ بِسُرْعَةِ البَدِيهَةِ"" : بِحُضُورِ البَدِيهَةِ. 4.""سُرْعَةُ الصَّوْتِ"" (فيز) : أَيِ الْمَسَافَةُ الَّتِي يَقْطَعُهَا الصَّوْتُ فِي وَحْدَةٍ زَمَنِيَّةٍ، وَتُقَدَّرُ بـ 340 مِتْرٍ فِي الثَّانِيَةِ. 5. ""سُرْعَةُ الضَّوْءِ"" : ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21218, 'سَرِقَةٌ', 'سرقة', 'مصدر', 'سرق', 'سرقة', 'سرقة', 'مص. سَرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَرِقَةٌ-سَرِقَةٌ [س ر ق] (مص. سَرَقَ). 1. ""تَعَرَّضَ بَيْتُهُ للسَّرِقَةِ"" : أُخِذَ بَعْضُ مَتَاعِهِ فِي غِيَابِهِ أوْ غَفْلَةً عَنْهُ أَوْ خُفْيَةً. ""إنَّ السَّرِقَةَ عَمَلٌ مَشِينٌ فِي حَدِّ ذَاتِهِ"". 2.""السَّرِقَةُ الأدَبِيَّةُ"" : أيْ أنْ يَأْخُذَ شَاعِرٌ أوْ كَاتِبٌ شِعْراً أو نَصّاً لِغَيْرِهِ وَيَنْسُبَهُ لِنَفْسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21219, 'سُطُوحٌ', 'سطوح', 'مصدر', '', 'سطوح', 'سطح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21220, 'سُرًى', 'سرى', 'مصدر', 'سرو', 'سرى', 'سر', 'مص. سَرَى', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"سُرَى-سُرَى [س ر و] (مص. سَرَى). 1.: سَيْرُ اللَّيْلِ. ""عِنْدَ الصُّبْحِ يَحْمَدُ القَوْمُ السُّرَى"" (مثل) : يُضْرَبُ فِي احْتِمَالِ الْمَشَقَّةِ وَالحَثِّ عَلَى الصَّبْرِ. 2. ""اِبْنُ السُّرَى"" : الْمُسَافِرُ لَيْلاً. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21221, 'سَرَيَانٌ', 'سريان', 'مصدر', 'سري', 'سريان', 'سرن', 'مص. سَرَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَرَيَانٌ-سَرَيَانٌ [س ر ي] (مص. سَرَى). 1. ""سَرَيَانُ الدَّمِ فِي الجِسْمِ"" : جَرَيَانُهُ. 2. ""سَرَيَانُ القَافِلَةِ"" : سَيْرُها لَيْلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21222, 'سُرٌّ', 'سر', 'مصدر', 'سرر', 'سر', 'سر', 'مص. سَرَّ يَسُرُّ', '', '', 'مفرد', 'DnN', '', '', '"أسْرَارٌجأَساريرُ"', '', 'R', '', '', '', '', '', '', '"(مص. سَرَّ يَسُرُّ). : خَطٌّ فِي بَاطِنِ الكَفِّ، وَالوَجْهِ والجَبْهَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21223, 'أسْرَارٌ', 'أسرار', 'مصدر', '', 'ءسرار', 'سرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21224, 'أَساريرُ', 'أسارير', 'مصدر', '', 'ءسارير', 'سرر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21225, 'سَطْوَةٌ', 'سطوة', 'مصدر', 'سطو', 'سطوة', 'سطة', 'مص. سَطَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَطْوَةٌ-سَطْوَةٌ [س ط و] (مص. سَطَا). 1. ""السَّطْوَةُ عَلَى الأَعْدَاءِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21226, 'سَطْوٌ', 'سطو', 'مصدر', 'سطو', 'سطو', 'سط', 'مص. سَطا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَطْوٌ-سَطْوٌ [س ط و] (مص. سَطا). 1. ""تَمَكَّنَ مِنَ السَّطْوِ عَلَى الْمَنْزِلِ لَيْلاً"" : سَرِقَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21227, 'تَسْطِيحٌ', 'تسطيح', 'مصدر', 'سطح', 'تسطيح', 'تسطح', 'مص. سَطَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْطِيحٌ-تَسْطِيحٌ [س ط ح] (مص. سَطَّحَ). ""تَسْطِيحُ الكُرَةِ"": رَسْمُهَا عَلَى سَطْحٍ، وَنَقْل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21228, 'سَطْحٌ', 'سطح', 'مصدر', 'سطح', 'سطح', 'سطح', 'مص. سَطَحَ', '', '', 'مفرد', 'DnN', '', '', '"سُطُوحٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. سَطَحَ). 1.""صَعَدَ إلَى سَطْحِ البَيْتِ"" : أعْلاَهُ، ظَهْرُهُ. ""وَكُنْتُ لاَ أرَى فَوْقَ سُطُوحِ البُيُوتِ وَالعِمَارَاتِ إِلاَّ الغَسِيلَ وَأعْمِدَةَ الهَوَائِيَّاتِ"". 2. ""سَطْحُ الجِلْدِ"" : ظَاهِرُهُ. 3.""وَجَدَ سَطْحَ الحَقْلِ مُسْتَوِياً"" : مِسَاحَتَهُ. 4.""تَبْعُدُ الْمَدِينَةُ عَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21229, 'سَعَرٌ', 'سعر', 'مصدر', 'سعر', 'سعر', 'سعر', 'مص. سَعِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَعِرٌ-سَعِرٌ [س ع ر] (صيغة فَعِل). ""وَلَدٌ سَعِرٌ"" : مَجْنُونٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21230, 'تَسْطِيرٌ', 'تسطير', 'مصدر', 'سطر', 'تسطير', 'تسطر', 'مص. سَطَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْطِيرٌ-تَسْطِيرٌ [س ط ر] (مص. سَطَّرَ). 1.""تَسْطِيرُ رِسَالَتِهِ"": كِتَابَتُهَا. 2.""تَسْطِيرُ خُطُوطٍ بِالمِسْطَرَةِ"" : رَس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21231, 'سَطْعٌ', 'سطع', 'مصدر', 'سطع', 'سطع', 'سطع', 'مص. سَطَعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَطْعٌ-سَطْعٌ [س ط ع] (مص. سَطَعَ). 1.""سَطْعُ الغُبَارِ"" : اِنْتِشَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21232, 'سَطِيعٌ', 'سطيع', 'مصدر', 'سطع', 'سطيع', 'سطع', 'مص. سَطَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَطِيعٌ-سَطِيعٌ [س ط ع] (مص. سَطَعَ). 1. ""بَزَغَ السَّطِيعُ"": الصُّبْحُ. 2.""عُنُقٌ سَطِيعٌ"" : طَوِيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21233, 'سَعْدٌ', 'سعد', 'مصدر', 'سعد', 'سعد', 'سعد', 'مص. سَعَدَ', '', '', 'مفرد', 'DnN', '', '', '"أَسْعُدٌ:سُعُودٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. سَعَدَ). 1.""يَوْمٌ سَعْدٌ"" : يَوْمٌ مَيْمُونٌ، يَوْمُ يُمْنٍ. 2. ""سَعْدَيْكَ"" : أدْعُو لَكَ بِإسْعَادٍ تِلْوَ إسْعَادٍ. 3. ""لَبَّيْكَ وَسَعْدَيْكَ"" : دُعَاءٌ، أَيْ أنَا خَادِمُكَ. 4.""سُعُودُ النُّجُومِ"" (فك) :كَوَاكِبُ مِن مِنْطَق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21234, 'أَسْعُدٌ', 'أسعد', 'مصدر', '', 'ءسعد', 'سعد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
