INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21236, 'سُعُودٌ', 'سعود', 'مصدر', 'سعد', 'سعود', 'سعد', 'مص. سَعَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"سُعُودٌ-سُعُودٌ [س ع د] (مص. سَعَدَ). ""سُعُودُ النُّجُومِ"" : عَشَرَةُ نُجُومٍ، كَوَاكِبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21237, 'سَعَادَةٌ', 'سعادة', 'مصدر', 'سعد', 'سعادة', 'سعدة', 'مص. سَعدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَعَادَةٌ-سَعَادَةٌ [س ع د] (مص. سَعدَ). 1. ""شَعَرَ بِسَعَادَةٍ لاَ حَدَّ لهَا"" : بِفَرَحٍ، بِابْتِهَاجٍ، أيْ كُلُّ مَا يُدْخِلُ البَهْجَةَ وَالفَرَحَ عَلَى النَّفْسِ. ""إنَّ سَعَادَتَنَا الحَقِيقِيَّةَ هِيَ العَيْشُ فِي حُرِّيَّةٍ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21238, 'تَسْعِيرٌ', 'تسعير', 'مصدر', 'سعر', 'تسعير', 'تسعر', 'مص. سَعَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْعِيرٌ-تَسْعِيرٌ [س ع ر] (مص. سَعَّرَ). 1.""تَسْعِيرُ النَّارِ"" : إِشْعَالُهَا. 2.""حَدَّدَ تَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21239, 'تَسْفِيرٌ', 'تسفير', 'مصدر', 'سفر', 'تسفير', 'تسفر', 'مص. سَفَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْفِيرٌ-تَسْفِيرٌ [س ف ر] (مص. سَفَّرَ). 1.""قَرَّرَ تَسْفِير"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21240, 'سَعْفٌ', 'سعف', 'مصدر', 'سعف', 'سعف', 'سعف', 'مص. سَعَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَعْفٌ-سَعْفٌ [س ع ف] (مص. سَعَفَ). ""حَاوَلَ سَعْفَهُ"" : مُسَاعَدَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21241, 'سَعَفٌ', 'سعف', 'مصدر', 'سعف', 'سعف', 'سعف', 'مص. سَعِفَ', '', '', 'مفرد', 'DnN', '', '', '"سُعُوفٌ"', '', 'R', '', '', '', '', '', '', '"(مص. سَعِفَ). 1.""سَعَفُ النَّخْلَةِ"" : جَرِيدُهُا. 2. ""سَعَفُ الع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21242, 'سُعُوفٌ', 'سعوف', 'مصدر', '', 'سعوف', 'سعف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
