INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21244, 'سِعَايَةٌ', 'سعاية', 'مصدر', 'سعي', 'سعاية', 'سعة', 'مص. سَعى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"سِعَايَةٌ-سِعَايَةٌ [س ع ي] (مص. سَعى). ""فَرَّقَ بَيْنَ الأَصْحَابِ بِالسِّعَايَةِ"" : بِالنَّمِيمَةِ وَالو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21245, 'سَفْحٌ', 'سفح', 'مصدر', 'سفح', 'سفح', 'سفح', 'مص. سَفَحَ', '', '', 'مفرد', 'DnN', '', '', '"سُفُوحٌ"', '', 'R', '', '', '', '', '', '', '"(مص. سَفَحَ). ""اِسْتَقَرَّ الرَّاعِي فِي سَفْحِ الجَبَلِ"" : فِي أسْفَلِهِ الَّذِي يَنْصَبُّ فِيهِ الْمَاءُ."', '');
