INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21247, 'تَسْفِيدٌ', 'تسفيد', 'مصدر', 'سفد', 'تسفيد', 'تسفد', 'مص. سَفَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْفِيدٌ-تَسْفِيدٌ [س ف د] (مص. سَفَّدَ). ""تَسْفِيدُ اللَّحْمِ"" : تَنْظِيمُهُ قِطْعَةً قِطْعَةً فِي السَّفُّودِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21248, 'سِفَادٌ', 'سفاد', 'مصدر', 'سفد', 'سفاد', 'سفد', 'مص. سَفَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سِفَادٌ-سِفَادٌ [س ف د] (مص. سَفَدَ). ""سِفَادُ الْحَيَوانِ"" : نَزْوُ الذَّكَرِ عَلَى الأنْثَى، الرُّكُوبُ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21249, 'سَفَاهَةٌ', 'سفاهة', 'مصدر', 'سفه', 'سفاهة', 'سفهة', 'مص. سَفَهُ، سَفِهَ، سَفُهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَفَاهَةٌ-سَفَاهَةٌ [س ف هـ] (مص. سَفَهُ، سَفِهَ، سَفُهَ). ن.سَفَاهٌ."', '');
