INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21251, 'سَفْسَفَةٌ', 'سفسفة', 'مصدر', 'سفسف', 'سفسفة', 'سفسفة', 'مص. سَفْسَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَفْسَفَةٌ-سَفْسَفَةٌ [س ف س ف] (مص. سَفْسَفَ). ""سَفْسَفَةُ الرِّيحِ"" : هُبُوبُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21252, 'سُفْعَةٌ', 'سفعة', 'مصدر', 'سفع', 'سفعة', 'سفعة', 'مص. سَفِعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سُفْعَةٌ-سُفْعَةٌ [س ف ع] (مص. سَفِعَ). 1.: سَوَادٌ مُشْبَعٌ حُمْرَةً. 2. : حَبُّ نَبَاتِ الحَنْظَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21253, 'سَفَعٌ', 'سفع', 'مصدر', 'سفع', 'سفع', 'سفع', 'مص. سَفِعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَفَعٌ-سَفَعٌ [س ف ع] (مص. سَفِعَ). : سَوَادٌ مُشْبَعٌ بِحُمْرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21254, 'سَفْكٌ', 'سفك', 'مصدر', 'سفك', 'سفك', 'سفك', 'مص. سَفَكَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَفْكٌ-سَفْكٌ [س ف ك] (مص. سَفَكَ). ""سَفْكُ الدِّمَاءِ"" : إرَاقَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21255, 'سَفَالَةٌ', 'سفالة', 'مصدر', 'سفل', 'سفالة', 'سفلة', 'مص. سَفَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَفَالَةٌ-سَفَالَةٌ [س ف ل] (مص. سَفَلَ). ""مَا هَذِهِ السَّفَالَةُ"', '');
