INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21285, 'سُكُونٌ', 'سكون', 'مصدر', 'سكن', 'سكون', 'سكن', 'مص. سَكَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سُكُونٌ-سُكُونٌ [س ك ن] (مص. سَكَنَ). 1.""يُخَيِّمُ السُّكُونُ علَى القَرْيَةِ"" : الهُدُوءُ، الصَّمْتُ. 2.""سُكُونُ الألَمِ"" : خ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21286, 'سَكٌّ', 'سك', 'مصدر', 'سكك', 'سك', 'سك', 'مص. سَكَّ يَسُكُّ', '', '', 'مفرد', 'DnN', '', '', '"سِكَاكٌ:سُكُوكٌ"', '', 'R', '', '', '', '', '', '', '"(مص. سَكَّ يَسُكُّ). 1. ""سَكُّ النُّقُود"" : ضَرْبُهَا، صَوْغُهَا. 2. ""دَارُ السَّكِّ"": مَصْنَعٌ تَابِعٌ لِلدَّوْلَةِ يُعْهَدُ إلَيْهِ بِسَكِّ النُّقُودِ الْمَعْدِنِيَّةِ. 3.""فِي طَب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21287, 'سِكَاكٌ', 'سكاك', 'مصدر', '', 'سكاك', 'سكك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21288, 'سُكُوكٌ', 'سكوك', 'مصدر', '', 'سكوك', 'سكك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21289, 'سَلْخٌ', 'سلخ', 'مصدر', 'سلخ', 'سلخ', 'سلخ', 'مص. سَلَخَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَلْخٌ-سَلْخٌ [س ل خ] (مص. سَلَخَ). 1.""سَلْخُ الذَّبَائِحِ"": كَشْطُهَا، اِنْتِزَاعُ جِلْدِهَا. 2.""سَلْخُ الحَيَوانِ"" : جِلْدُهُ الْمَسْلُوخُ. 3.""سَلْخُ الحَيَّةِ"" : قِشْرُهَا. 4. ""سَلْخُ الشَّهْرِ"" : آخِرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21290, 'سُلْوَانٌ', 'سلوان', 'مصدر', 'سلو', 'سلوان', 'سلن', 'مص. سَلاَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سُلْوَانٌ-سُلْوَانٌ [س ل و] (مص. سَلاَ). ""كَانَ سُلْوَانُهُ حُرْقَةً فِي النَّفْسِ"" : هِجْرَانُهُ، نِسْيَانُهُ، سُلُوُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21291, 'سُلُوٌّ', 'سلو', 'مصدر', 'سلو', 'سلو', 'سل', 'مص. سَلاَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سُلُوٌّ-سُلُوٌّ [س ل و] (مص. سَلاَ). ""لَمْ يَكُنْ سُلُوُّهُ اخْتِيَاراً"": هِجْرَانُهُ، نِسْيَانُهُ، سُلْوَانُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21292, 'سَلْبٌ', 'سلب', 'مصدر', 'سلب', 'سلب', 'سلب', 'مص. سَلَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَلْبٌ-سَلْبٌ [س ل ب] (مص. سَلَبَ). ""سَلْباً أوْ إيجَاباً"" : نَفْياً أَوْ... ""أجَابَ بالسَّلْبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21293, 'سَلَبٌ', 'سلب', 'مصدر', 'سلب', 'سلب', 'سلب', 'مص. سَلِبَ', '', '', 'مفرد', 'DnN', '', '', '"أَسْلاَبٌ"', '', 'R', '', '', '', '', '', '', '"(مص. سَلِبَ). 1.""أَخَذَ سَلَبَ عَدُوِّهِ"" : مَا مَعَهُ مِنْ سِلاَحٍ وَثِيَابٍ وَمَا إلَى ذَلِكَ. 2. ""سَلَبُ الذَّبِيحَةِ"" : جِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21294, 'أَسْلاَبٌ', 'أسلاب', 'مصدر', '', 'ءسلاب', 'سلب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21295, 'تَسْلِيحٌ', 'تسليح', 'مصدر', 'سلح', 'تسليح', 'تسلح', 'مص. سَلَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْلِيحٌ-تَسْلِيحٌ [س ل ح] (مص. سَلَّحَ). ""قَرَّرَ القَائِدُ الأَعْلَى تَسْلِيحَ الجُنْدِ بِسِلاَحٍ جَدِيدٍ"" : أَيْ تَجْهِيزَهُمْ وَتَزْوِيدَهُم بِالسِّلاَحِ وَالذَّخَائِرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21296, 'سَلْحٌ', 'سلح', 'مصدر', 'سلح', 'سلح', 'سلح', 'مص. سَلَحَ', '', '', 'مفرد', 'DnN', '', '', '"سُلُوحٌ:سُلْحَانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. سَلَحَ). ""رَمَى سَلْحَاً"" : مَا يَخْرُجُ مِنَ البَطْنِ مِنَ الفَضَلاَتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21297, 'سُلُوحٌ', 'سلوح', 'مصدر', '', 'سلوح', 'سلح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21298, 'سُلْحَانٌ', 'سلحان', 'مصدر', '', 'سلحان', 'سلحن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21299, 'سَلاَسَةٌ', 'سلاسة', 'مصدر', 'سلس', 'سلاسة', 'سلسة', 'مص. سَلُسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَلاَسَةٌ-سَلاَسَةٌ [س ل س] (مص. سَلُسَ). 1. ""حَلَّ مَشَاكِلَهُ مَعَهُ بِسَلاَسَةٍ"" : بِلُيُونَةٍ. 2. ""عُرِفَ بِسَلاَسَةِ أُسْلُوبِهِ"" : بِرِقَّتِهِ، سُهُولَتِهِ، انْسِجَامِهِ، عُذُوبَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21300, 'سَلَسٌ', 'سلس', 'مصدر', 'سلس', 'سلس', 'سلس', 'مص. سَلِسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَلِسٌ-سَلِسٌ [س ل س] (صِيغَةُ فَعِل لِلْمُبالَغَةِ). 1. ""يَكْتُبُ بِأُسْلُوبٍ سَلِسٍ"" : سَهْل، مُرِيح. 2. ""وَلَدٌ سَلِسٌ فِي سُلُوكِهِ"": لَيِّنٌ، سَهْلُ الْمُعَاشَرَةِ. 3. ""شَرَابٌ سَلِسٌ"" : عَذْبٌ. 4. ""سَلِسُ القِيَادِ"" : يُقَادُ بِسُهُولَةٍ وَلُيُونَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21301, 'تَسْلِيطٌ', 'تسليط', 'مصدر', 'سلط', 'تسليط', 'تسلط', 'مص. سَلَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْلِيطٌ-تَسْلِيطٌ [س ل ط] (مص. سَلَّطَ). 1.""اِخْتَارَهُ لِتَسْلِيطِهِ عَلَى سُكَّانِ الْمَدِينَةِ"" : إِطْلاَقُ القُوَّةِ وَالسُّلْطَةِ وَالقَهْرِ. 2.""تَسْلِيطُ الأَضْوَاءِ عَلَى الْمُشْكِلِ"" : الاِهْتِمَامُ وَتَرْكِيزُ الأَضْوَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21302, 'سَلاَطَةٌ', 'سلاطة', 'مصدر', 'سلط', 'سلاطة', 'سلطة', 'مص. سَلِطَ، سَلُطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَلاَطَةٌ-سَلاَطَةٌ [س ل ط] (مص. سَلِطَ، سَلُطَ). ""سَلاَطَةُ لِسَانٍ"" : طُولُ اللِّسَانِ بِالسُّوءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21303, 'سَلْطَنَةٌ', 'سلطنة', 'مصدر', 'سلطن', 'سلطنة', 'سلطنة', 'مص. سَلْطَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَلْطَنَةٌ-سَلْطَنَةٌ [س ل ط ن] (مص. سَلْطَنَ). ""سَلْطَنَةُ عُمَانَ"": مَمْلَكَةُ عُمَان لأَنَّهَا تَخْضَعُ لِحُكْمِ سُلْطَانٍ، مَمْلَكَةُ السُّلْطَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21304, 'تَسْلِيفٌ', 'تسليف', 'مصدر', 'سلف', 'تسليف', 'تسلف', 'مص. سَلَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْلِيفٌ-تَسْلِيفٌ [س ل ف] (مص. سَلَّفَ). ""طَلَبَ مِنَ البَنْكِ أَنْ يُقَدِّمَ لَهُ تَسْلِيفاً"" : قَرْضًا مِنَ الْمَالِ لأَجَلٍ. ""بَنْكُ التَّسْلِيفِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21305, 'سَلَفٌ', 'سلف', 'مصدر', 'سلف', 'سلف', 'سلف', 'مص. سَلَفَ', '', '', 'مفرد', 'DnN', '', '', '"أَسْلاَفٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. سَلَفَ). 1.""هَذَا مَا تَرَكَهُ السَّلَفُ"" : الآبَاءُ، الأَجْدَادُ. ""السَّلَفُ وَالخَلَفُ"" ""هُوَ خَيْرُ خَلَفٍ لِخَيْرِ سَلَفٍ"" ""السَّل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21306, 'أَسْلاَفٌ', 'أسلاف', 'مصدر', '', 'ءسلاف', 'سلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21307, 'سَلْفٌ', 'سلف', 'مصدر', 'سلف', 'سلف', 'سلف', 'مص. سَلَفَ', '', '', 'مفرد', 'DnN', '', '', '"سُلُوفٌ:أَسْلُفٌ"', '', 'R', '', '', '', '', '', '', '"(مص. سَلَفَ). 1. : جِلْدٌ لَمْ يُدْبَغْ جَيِّداً. 2.: جِرَابٌ ضَخْمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21308, 'سُلُوفٌ', 'سلوف', 'مصدر', '', 'سلوف', 'سلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21309, 'أَسْلُفٌ', 'أسلف', 'مصدر', '', 'ءسلف', 'سلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21310, 'سَلْقٌ', 'سلق', 'مصدر', 'سلق', 'سلق', 'سلق', 'مص. سَلَقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَلْقٌ-سَلْقٌ [س ل ق] (مص. سَلَقَ). 1. ""سَلْقُ الخُضَرِ"" : طَبْخُهَا فِي الْمَاء"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21311, 'سُلُوك', 'سلوك', 'مصدر', 'سلك', 'سلوك', 'سلك', 'مص. سَلَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"سُلُوك-سُلُوك [س ل ك] (مص. سَلَكَ). 1. ""كَانَ سُلُوكُهُ نَمُوذَجِيّاً ومِثَالاً يُحْتَذَى بِهِ"" : سِيرَتُهُ، أنْمَاطُ تَصَرُّفِهِ، أَخْلاَقُهُ. ""عَابَ علَيْهِ النَّاسُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21312, 'تَسْلِيمٌ', 'تسليم', 'مصدر', 'سلم', 'تسليم', 'تسلم', 'مص. سَلَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْلِيمٌ-تَسْلِيمٌ [س ل م] (مص. سَلَّمَ). 1.""لَمْ يَبْقَ أَمَامَ الجُنْدِيِّ إِلاَّ تَسْلِيمُ سِلاَحِهِ"" : وَضْعُهُ، التَّخَلِّي عَنِ اسْتِعْمَالِهِ. 2.""قَرَّرَ فِي النِّهَايَةِ التَّسِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21313, 'سَلاَمٌ', 'سلام', 'مصدر', 'سلم', 'سلام', 'سلم', 'مص. سَلَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَلاَمٌ-سَلاَمٌ [س ل م] (مص. سَلَمَ). 1.""السَّلامُ"" : اِسْمٌ مِنْ أَسْمَاءِ اللَّهِ تَعَالَى لِسَلاَمَتِهِ مِنَ النَّقْصِ وَالعَيْبِ وَسِيَادَةِ الطُّمَأْنِينَةِ فِي أَجْوَائِهِ. 2. ""مَتَى يَسُودُ السَّلاَمُ بَيْنَ النَّاسِ"" : الهُدُوءُ والسِّلْمُ وَالطُّمَأْنِينَةُ وَعَدَمُ اللُّجُوءِ إلَى الحَرْبِ. ""تَحَقَّقَ السَّلاَمُ بَعْدَ حَرْبٍ مَهُولَةٍ"". 3.""سَلامُ الشُّجْعانِ"" : صُلْحٌ مُشَرِّفٌ لِلْمَهْزومينَ الَّذين حاربوا بِشَجا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21314, 'سَلاَمَةٌ', 'سلامة', 'مصدر', 'سلم', 'سلامة', 'سلمة', 'مص. سَلِمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَلاَمَةٌ-سَلاَمَةٌ [س ل م] (مص. سَلِمَ). 1. ""لِتصْحَبْكَ السَّلاَمَةُ يَا بُنَيَّ"" : الرَّاحَةُ وَهُدُوءُ البَالِ وَالعَافِيَةُ وَعَدَمُ التَّعَرُّضِ لِلأذَى وَالآفَاتِ. ""مَعَ السّلاَمَةِ"" ""فِي ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21315, 'تَسْلِيَةٌ', 'تسلية', 'مصدر', 'سلو', 'تسلية', 'تسلة', 'مص. سَلَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. سَلَّى). 1.""حَاوَلَ تَسْلِيَةَ الأَطْفَالِ بِاللَّعِبِ"" : إِلْهَاءَهُمْ. 2.""مَكَانُ التَّسْلِيَةِ"" : مَكَانُ اللَّعِبِ وَاللَّهْوِ. 3.""تَسْلِيَةُ النَّفْسِ"" : إِدْخَالُ السُّرُورِ عَلَى النَّفْسِ وَإِبْعَادُ الضَّيْمِ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21316, 'سَمْتٌ', 'سمت', 'مصدر', 'سمت', 'سمت', 'سمت', 'مص. سَمَتَ', '', '', 'مفرد', 'DnN', '', '', '"سُمُوتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. سَمَتَ). 1.""لَزِمَ السَّمْتَ"" : الطَّرِيقَ الوَاضِحَ. 2. ""لَهُ سَمْتُهُ"" : مَذْهَبُهُ. 3. ""مَعْرُوفٌ بِسَمْتِهِ"" : بِسَكِينَتِهِ وَوَقَارِهِ. 4. ""يُحَافِظُ عَلَى سَمْتِهِ"" : عَلَى هَيْئَتِهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21317, 'سُمُوتٌ', 'سموت', 'مصدر', '', 'سموت', 'سمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21318, 'سَمَاجَةٌ', 'سماجة', 'مصدر', 'سمج', 'سماجة', 'سمجة', 'مص. سَمُجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَمَاجَةٌ-سَمَاجَةٌ [س م ج] (مص. سَمُجَ). ""سَمَاجَةُ فِعْلٍ"" : قُبْحُهُ، رَدَاءتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21319, 'أسْمَاعٌ', 'أسماع', 'مصدر', '', 'ءسماع', 'سمع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21320, 'سَمَاحَةٌ', 'سماحة', 'مصدر', 'سمح', 'سماحة', 'سمحة', 'مص. سَمَحَ، سَمُحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَمَاحَةٌ-سَمَاحَةٌ [س م ح] (مص. سَمَحَ، سَمُحَ). 1. ""سَمَاحَةُ الشَّيْخِ"" : لَقَب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21321, 'سَمَاحٌ', 'سماح', 'مصدر', 'سمح', 'سماح', 'سمح', 'مص. سَمَحَ، سَمُحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَمَاحٌ-سَمَاحٌ [س م ح] (مص. سَمَحَ، سَمُحَ). 1. ""أرْجُو السَّمَاحَ لِي بِالتَّغَيُّبِ"" : أرْجُو الإِذْنَ، الْمُوَافَق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21322, 'تَسْمِيدٌ', 'تسميد', 'مصدر', 'سمد', 'تسميد', 'تسمد', 'مص. سَمَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْمِيدٌ-تَسْمِيدٌ [س م د] (مص. سَمَّدَ). ""تَسْمِيدُ الأَرْضِ"" : وَضْعُ السَّمَادِ فِيهَا لإِصْلاَحِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21323, 'تَسْمِيرٌ', 'تسمير', 'مصدر', 'سمر', 'تسمير', 'تسمر', 'مص. سَمَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْمِيرٌ-تَسْمِيرٌ [س م ر] (مص. سَمَّرَ). 1.""تَسْمِيرُ البَابِ"" : إِغْلاَقُهُ بِالمِسْمَارِ أَوْ وَضْعُ الْمَسَامِيرِ فِيهِ. 2.""تَسْمِيرُ لَوْنِ البَشَرَةِ"": تَحْوِيلُهَا إِلىَ سُمْرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21324, 'تَسْمِيطٌ', 'تسميط', 'مصدر', 'سمط', 'تسميط', 'تسمط', 'مص. سَمَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْمِيطٌ-تَسْمِيطٌ [س م ط] (مص. سَمَّطَ). 1.: اِلْتِهَابٌ فِي أَصْلِ بَاطِنِ الفَخِذَيْنِ. 2.: مصْطَلَحٌ شِعْرِيٌّ يُطْلَقُ عَلَى بَيْتِ الشِّعْرِ عِنْدَما يُقَسَّمُ إِلَى أَجْزَاءَ عَرُوضِيَّةٍ عَلَى غَيْرِ رَوِيّ القَافِيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21325, 'سَمْطٌ', 'سمط', 'مصدر', 'سمط', 'سمط', 'سمط', 'مص. سَمَطَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَمْطٌ-سَمْطٌ [س م ط] (مص. سَمَطَ). ""رَجُلٌ سَمْطٌ"" : فَقِيرٌ، خَفِيفُ الحَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21326, 'تَسْمِيعٌ', 'تسميع', 'مصدر', 'سمع', 'تسميع', 'تسمع', 'مص. سَمَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْمِيعٌ-تَسْمِيعٌ [س م ع] (مص. سَمَّعَ). ""أَرَادَ بِذَلِكَ تَسْمِيعَهُ مَا لَمْ يَكُنْ يُرِيدُ سَمَاعَهُ"" : جَعْلُهُ يَسْمَعُ، وَالْمَقْصُودُ هُنَا الشَّتْمُ وَإِبْلاَغُهُ القَبِيحَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21327, 'سَمَاعٌ', 'سماع', 'مصدر', 'سمع', 'سماع', 'سمع', 'مص. سَمِعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَمَاعٌ-سَمَاعٌ [س م ع] (مص. سَمِعَ). 1. ""يُتْقِنُ السَّمَاعَ"" : الغِنَاءَ، وَيَخْتَصُّ مَعْنَى السَّماعِ في الْمَغْربِ بِإِنْشادِ الأَمْداحِ. 2.""لَهُ سَمَاعٌ"" : ذِكْرٌ وَصِيتٌ مَسْمُوعٌ. 3."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21328, 'سَمْعٌ', 'سمع', 'مصدر', 'سمع', 'سمع', 'سمع', 'مص. سَمِعَ', '', '', 'مفرد', 'DnN', '', '', '"أسْمَاعٌ"', '', 'R', '', '', '', '', '', '', '"(مص. سَمِعَ). 1.""حَاسَّةُ السَّمْعِ"" : الأُذْنُ الَّتِي يَسْمَعُ بِهَا الإِنْسَانُ والحَيَوانُ. 2.""أَعَارَهُ السَّمْعَ"" : أصْغَى إلَيْهِ بِانْتِبَاهٍ. ""ألْقَى إلَيْهِ سَمْعَهُ"". 3.""سَمْعاً وَطَاعَةً يَا مَوْلاَيَ"" : أَيْ أَسْمَعُ سَمْعاً وَأُطيعُ طاعَةً. 4.""سَمْعَكَ إِلَيَّ"" : أَيْ اِسْمَعْ مِن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21329, 'سُهْدٌ', 'سهد', 'مصدر', 'سهد', 'سهد', 'سهد', 'مص. سَهِدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سُهْدٌ-سُهْدٌ [س هـ د] (مص. سَهِدَ). ""اِسْتَبَدَّ بِهِ السُّهْدُ"" : اِسْتَبَدَّ بِهِ الأرَقُ ليْلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21330, 'سُمُوقٌ', 'سموق', 'مصدر', 'سمق', 'سموق', 'سمق', 'مص. سَمَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سُمُوقٌ-سُمُوقٌ [س م ق] (مص. سَمَقَ). ""سُمُوقُ الأشْجَارِ"": عُلُوُّهَا، اِرْتِفَاعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21331, 'سَمْكٌ', 'سمك', 'مصدر', 'سمك', 'سمك', 'سمك', 'مص. سَمَكَ', '', '', 'مفرد', 'DnN', '', '', '"سُمُوكٌ"', '', 'R', '', '', '', '', '', '', '"(مص. سَمَكَ). 1.""سَمْكُ البِنَاءِ"" : اِرْتِفَاعُهُ. 2. سَمْكُ الخَشَبِ"" : كَثَافَتُهُ. 3.النازعات آية"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21332, 'سُمُوكٌ', 'سموك', 'مصدر', '', 'سموك', 'سمك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21333, 'تَسْمِيمٌ', 'تسميم', 'مصدر', 'سمم', 'تسميم', 'تسمم', 'مص. سَمَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْمِيمٌ-تَسْمِيمٌ [س م م] (مص. سَمَّمَ). 1.""تَسْمِيمُ الطَّعَامِ"" : وَضْعُ السُّمِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21334, 'تَسْمِينٌ', 'تسمين', 'مصدر', 'سمن', 'تسمين', 'تسمن', 'مص. سَمَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْمِينٌ-تَسْمِينٌ [س م ن] (مص. سَمَّنَ). ""تَسْمِينُ الخَرُوفِ"": تَصْيِيرُهُ سَمِيناً، وَذَلِكَ بِتَزْوِيدِهِ بِالأَكْلِ الدَّسِمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21335, 'تَسْنِينٌ', 'تسنين', 'مصدر', 'سنن', 'تسنين', 'تسنن', 'مص. سَنَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْنِينٌ-تَسْنِينٌ [س ن ن] (مص. سَنَّنَ). 1.""تَسْنِينُ السِّكِّينِ"" : شَحْذُهُ، صَقْلُهُ لِيَصِيرَ أَكْثَرَ مَضَاءً. 2.""تَسْنِينُ الأَسْنَانِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21336, 'سَنَاءٌ', 'سناء', 'مصدر', 'سني', 'سناء', 'سن', 'مص . سَنِيَ ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"سَنَاءٌ-سَنَاءٌ [س ن ي] . (مص . سَنِيَ) . 1. ""لَمَعَ السَّناءُ"" : البَرْقُ ، الضَّوْءُ السَّاطِعُ .النور آية 43 يَكادُ سَنَا بَرْقِهِ يَذْهَبُ بِالأبْصَارِ (قرآن). 2. (نب). : نَبَاتٌ مِنْ فَصِيلَةِ القَرْنِيَّاتِ، أنْوَاعُهُ عَدِيدَةٌ، مِنْهَا أش"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21337, 'سَهْوٌ', 'سهو', 'مصدر', 'سهو', 'سهو', 'سه', 'مص. سَها', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَهْوٌ-سَهْوٌ [س هـ و] (مص. سَها). ""تَرَكَ قَلَمَهُ سَهْواً"" : نِسْياناً غَيْرَ مُتَعَمِّدٍ. ""سَقَطَ سَهْواً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21338, 'سُهَادٌ', 'سهاد', 'مصدر', 'سهد', 'سهاد', 'سهد', 'مص. سَهَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سُهَادٌ-سُهَادٌ [س هـ د] (مص. سَهَدَ). ""اِشْتَدَّ بِهِ السُّهَادُ"": الأرَقُ، أَيْ ذَهَابُ النَّوْمِ عَنْهُ لَيْلاً. ""فِي نَفْسِي صِرَاعٌ عَنِيفٌ سَلَبَ السُّهَادَ مِنْ عَيْنَيَّ فِي اللَّيْلِ"". (إسحق الحسيني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21339, 'سَآمَةٌ', 'سآمة', 'مصدر', 'سأم', 'سءءمة', 'سآمة', 'مص. سَئِمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَآمَةٌ-سَآمَةٌ [س أ م] (مص. سَئِمَ). ""يَعِيشُ فِي سَآمَةٍ"" : فِي مَلَلٍ، ضَجَرٍ. ""مَنْ يُزِيحُ عَنَّا كَآبَةَ الحَيَاةِ ويَرْفَعُ عَنَّا كَابُوسَ السَّآمَةِ"".(ع. غلاَّب) ""أدْفَعُ عَنْ نَفْسِي سَآمَةَ الحَيَاةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21340, 'سَهَرٌ', 'سهر', 'مصدر', 'سهر', 'سهر', 'سهر', 'مص. سَهِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَهَرٌ-سَهَرٌ [س هـ ر] (مص. سَهِرَ). 1.""طَالَ بِهِ السَّهَرُ"": عَدَمُ النَّوْمِ لَيْلاً. 2. ""كَثِيرُ السَّهَرِ"" : الَّذِي لاَ يَنَامُ كَثِيراً. ""لاَ يَنَالُ الإنْسَانُ الغَايَةَ إلاَّ بِالجِدِّ وَسَهَرِ اللَّيَالِي"". (الغزالي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21341, 'تَسْهِيلٌ', 'تسهيل', 'مصدر', 'سهل', 'تسهيل', 'تسهل', 'مص. سَهَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْهِيلٌ-تَسْهِيلٌ [س هـ ل] (مص. سَهَّلَ). ""تَسْهِيلُ الأُمُورِ"": تَيْسِيرُهَا، تَصْيِيرُهَا سَهْلَةً، تَخْفِيفُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21342, 'سُهولَةٌ', 'سهولة', 'مصدر', 'سهل', 'سهولة', 'سهلة', 'مص. سَهُلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سُهولَةٌ-سُهولَةٌ [س هـ ل] (مص. سَهُلَ). ""أَجابَ بِسُهولَةٍ"": بِبَساطَةٍ، بِيُسْرِ، بِلا عَناءٍ أَوْ صُعُوبَةٍ. ""وَجَدَ سُهولَةً في العَمَلِ"" ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21343, 'تَسْوِيدٌ', 'تسويد', 'مصدر', 'سود', 'تسويد', 'تسد', 'مص. سَوَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْوِيدٌ-تَسْوِيدٌ [س و د] (مص. سَوَّدَ). ""تَسْوِيدُ اللَّوْنِ"" : تَصْيِيرُهُ أَسْوَدَ. 2.""تَسْوِيدُ رِسَالَةٍ"" : كِتَابَتُهَا أَوَّل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21344, 'تَسْوِيسٌ', 'تسويس', 'مصدر', 'سوس', 'تسويس', 'تسس', 'مص. سَوَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْوِيسٌ-تَسْوِيسٌ [س و س] (مص. سَوَّسَ). 1.""تَسْوِيسُ الفُولِ أَوِ الحِمَّصِ."" : دُخُولُ السُّوسِ فِيهِ. 2.""تَسْوِيسُ أَمْرٍ"" : تَذْلِيلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21345, 'تَسْوِيفٌ', 'تسويف', 'مصدر', 'سوف', 'تسويف', 'تسف', 'مص. سَوَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْوِيفٌ-تَسْوِيفٌ [س و ف] (مص. سَوَّفَ). ""أَكْثَرَ عَلَيْهِ مِنَ التَّسْوِيفِ"" : مِنَ الْمُمَاطَلَةِ فِي أَدَاءِ دَيْنٍ أَوْ مَا شَابَهَ ذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21346, 'تَسْوِيقٌ', 'تسويق', 'مصدر', 'سوق', 'تسويق', 'تسق', 'مص. سَوَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْوِيقٌ-تَسْوِيقٌ [س و ق] (مص. سَوَّقَ). ""تَسْوِيقُ البَضَائِعِ"" : تَصْدِيرُهَا وَطَلَبُ سُوقٍ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21347, 'سَوَقٌ', 'سوق', 'مصدر', 'سوق', 'سوق', 'سق', 'مص. سَوِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَوَقٌ-سَوَقٌ [س و ق] (مص. سَوِقَ). ""سَوَقُ السَّاقِ"": طولُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21348, 'تَسْوِيَةٌ', 'تسوية', 'مصدر', 'سوي', 'تسوية', 'تسة', 'مص. سَوَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. سَوَّى). ""سَعَى إِلى تَسْوِيَةِ الخِلاَفِ بَيْنَهُ وَبَيْنَ شَرِيكِهِ"" : إِيجَادُ حَلٍّ، اِتِّفَاقٌ لِإِنْهَاءِ الخِلاَفِ. ""تَسْوِيَةٌ سِيَاسِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21349, 'مُشَابَكَةٌ', 'مشابكة', 'مصدر', 'شبك', 'مشابكة', 'مشبكة', 'مص. شَابَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. شَابَكَ). ""مُشَابَكَةُ القَضَايَا"" : تَدَاخُلُ بَعْضِهَا فِي بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21350, 'سَأَمٌ', 'سأم', 'مصدر', 'سأم', 'سءم', 'سم', 'مص. سَئِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَأَمٌ-سَأَمٌ [س أ م] (مص. سَئِمَ). ""اِشْتَدَّ بِهِ السَّأَمُ"" : الْمَلَلُ وَالضَّجَرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21351, 'تَسْيِيبٌ', 'تسييب', 'مصدر', 'سيب', 'تسييب', 'تسب', 'مص. سَيَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْيِيبٌ-تَسْيِيبٌ [س ي ب] (مص. سَيَّبَ). 1.""تَسْيِيبُ الرَّاعِي لِغَنَمِهِ فِي ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21352, 'تَسْيِيجٌ', 'تسييج', 'مصدر', 'سيج', 'تسييج', 'تسج', 'مص. سَيَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْيِيجٌ-تَسْيِيجٌ [س ي ج] (مص. سَيَّجَ). ""تَسْيِيجُ حَقْلٍ"" : إِحَاطَتُهُ بِسِيَاجٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21353, 'تَسْيِيرٌ', 'تسيير', 'مصدر', 'سير', 'تسيير', 'تسر', 'مص. سَيَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْيِيرٌ-تَسْيِيرٌ [س ي ر] (مص. سَيَّرَ). 1.""أَصْبَحَ قَادِراً عَلَى تَسْيِيرِ أُمُورِهِ بِنَفْسِهِ"" : عَلَى تَدْبِيرِهَا. 2.""بَلَدٌ قَائِمٌ عَلَى التَّسْيِيرِ الذ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21354, 'سَيْطَرَةٌ', 'سيطرة', 'مصدر', 'سيطر', 'سيطرة', 'سطرة', 'مص. سَيْطَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"سَيْطَرَةٌ-سَيْطَرَةٌ [س ي ط ر] (مص. سَيْطَرَ). 1.""ضَجُّوا مِنْ سَيْطَرَةِ الحاكِمِ"" : مِنْ سَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21355, 'تَسْيِيلٌ', 'تسييل', 'مصدر', 'سيل', 'تسييل', 'تسل', 'مص. سَيَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَسْيِيلٌ-تَسْيِيلٌ [س ي ل] (مص. سَيَّلَ). 1.""تَسْييِلُ الْمَاءِ فِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21356, 'شَيْبَةٌ', 'شيبة', 'مصدر', 'شيب', 'شيبة', 'شبة', 'مص. شَابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَيْبَةٌ-شَيْبَةٌ [ش ي ب] (مص. شَابَ). ""شَيْبَةُ الرَّأْسِ"" : بَيَاضُ شَعْرِ الرَّأْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21357, 'شَيْبٌ', 'شيب', 'مصدر', 'شيب', 'شيب', 'شب', 'مص. شَابَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَيْبٌ-شَيْبٌ [ش ي ب] (مص. شَابَ). ""غَزَاهُ الشَّيْبُ"" : بَيَاضُ الشَّعْرِ، أَيِ الشَّعْرُ الأَبْيَضُ فِي الرَّأْسِ أَوِ اللِّحْيَةِ. ""بَيَّضَ الشَّيْبُ مَفْرِقَهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21358, 'مَشِيبٌ', 'مشيب', 'مصدر', 'شيب', 'مشيب', 'مشب', 'مص. شَابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَشِيبٌ-مَشِيبٌ [ش ي ب] (مص. شَابَ). 1.""عَلاَ الْمَشِيبُ شَعْرَهُ"" : الشَّيْبُ، أَيْ عِنْدَمَا يَصِيرُ شَعْرُ الرَّأْسِ أَبْيَضَ. ""أَلاَ لَيْتَ الشَّبَـابَ يَعُودُ يَوْمـاً*لِأُخْبِـرَهُ بِمَا فَعَلَ الْمَشِيـبُ"" 2.""هُوَ فِي طَوْرِ الْمَشِيبِ"" : مَرْحَلَةُ الشَّيْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21359, 'مُشَارَكَةٌ', 'مشاركة', 'مصدر', 'شرك', 'مشاركة', 'مشركة', 'مص. شَارَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. شَارَكَ). ""مُشَارَكَةٌ فيِ العَمَلِ"" : الْمُسَاهَمَةُ فِيهِ. ""كَانَتْ لَهُ مُشَارَكَةٌ إِيجَابِيَّةٌ فِي الْإِنْتَاجِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21360, 'مُشَابَهَةٌ', 'مشابهة', 'مصدر', 'شبه', 'مشابهة', 'مشبهة', 'مص. شَابَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَابَهَةٌ-مُشَابَهَةٌ [ش ب هـ] (مص. شَابَهَ). ""حَاوَلَ مُشَابَهَةَ أَبِيهِ"" : مُمَاثَلَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21361, 'مُشَاتَمَةٌ', 'مشاتمة', 'مصدر', 'شتم', 'مشاتمة', 'مشتمة', 'مص. شَاتَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَاتَمَةٌ-مُشَاتَمَةٌ [ش ت م] (مص. شَاتَمَ). ""سَايَرَهُ فيِ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21362, 'شِتَاءٌ', 'شتاء', 'مصدر', 'شتو', 'شتاء', 'شت', 'مص. شَاتَى', '', '', 'مفرد', 'Dz', '', '', '"أشْتِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '"(مص. شَاتَى). ""حَلَّ فَصْلُ الشِّتَاءِ"" : الفَصْلُ الَّذِي يَأْتِي بَعْدَ فَصْلِ الخَرِيفِ وَتَكْثُرُ فِيهِ الأمْطَارُ، وَيَشْتَدُّ بَر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21363, 'أشْتِيَةٌ', 'أشتية', 'مصدر', '', 'ءشتية', 'شتة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21364, 'شِجَارٌ', 'شجار', 'مصدر', 'شجر', 'شجار', 'شجر', 'مص. شَاجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شِجَارٌ-شِجَارٌ [ش ج ر] (مص. شَاجَرَ). ""اِنْتَقَلَ الوَلَدَانِ مِنَ السَّبِّ إلَى الشِّجَارِ"" : إلَى الخِص"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21365, 'مُشَاجَرَةٌ', 'مشاجرة', 'مصدر', 'شجر', 'مشاجرة', 'مشجرة', 'مص. شَاجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. شَاجَرَ). ""دَخَلَ مَعَهُ فِي مُشَاجَرَةٍ"" : فِي نِزَاعٍ وَمُشَاكَسَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21366, 'مُشَاحَّةٌ', 'مشاحة', 'مصدر', 'شحح', 'مشاحة', 'مشحة', 'مص. شَاحَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. شَاحَّ). 1.""لاَ مُشَاحَّةَ فِي مَا قَدَّمَهُ مِنْ آرَاءٍ"" : لاَ مُنَاقَشَةَ وَلاَ مُمَاحَكَةَ فِيهِ، إِنَّهَا وَاضِحَةٌ بَيِّنَةٌ. 2.""لاَ مُشَاحَّةَ أَنَّ الحُكْمَ كَانَ نَزِيهاً"" : لاَ خِلاَفَ وَلاَ جِدَالَ فِي..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21367, 'مُشَاحَنَةٌ', 'مشاحنة', 'مصدر', 'شحن', 'مشاحنة', 'مشحنة', 'مص. شَاحَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. شَاحَنَ). ""حَدَثَتْ مُشَاحَنَةٌ فِيمَا بَيْنَهُمَا"" : مُخَاصَمَةٌ، مُشَادَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21368, 'مُشَادَّةٌ', 'مشادة', 'مصدر', 'شدد', 'مشادة', 'مشدة', 'مص. شَادَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَادَّةٌ-مُشَادَّةٌ [ش د د] (مص. شَادَّ). ""حَصَلَتْ مُشَادَّةٌ بَيْنَ الجَارَيْنِ"" : مُخَاصَمَةٌ، عِرَاكٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21369, 'شَيْنٌ', 'شين', 'مصدر', 'شين', 'شين', 'شن', 'مص. شَانَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَيْنٌ-شَيْنٌ [ش ي ن] (مص. شَانَ). ""بِهِ شَيْنٌ"" : قُبْحٌ، عَيْبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21370, 'شَوْطٌ', 'شوط', 'مصدر', 'شوط', 'شوط', 'شط', 'مص. شَاطَ', '', '', 'مفرد', 'DnN', '', '', '"أَشْوَاطٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَاطَ). 1.""قَطَعَ شَوْطاً بَعِيداً فِي مَجَالِ عَمَلِهِ"" : أَيْ خُطْوَةً وَغَايَةً مَحْدُودَةً، أَنْجَزَ تَقَدُّماً كَبِيراً. ""بَلَغَ أَشْوَاطاً مُهِمَّةً"". 2.""اِنْتَهَى الشَّوْطُ الأَوَّلُ بِالتَّعَادُلِ بَيْنَ الفَرِيقَيْنِ"" : الدَّوْرُ، الْجُزْءُ الأَوَّلُ مِنَ الْمُبَارَاةِ. ""الشَّوْطُ النِّهَائِيُّ"". 3.""يَفُوقُ أَتْرَابَهُ بِأَشْوَاطٍ"" : يَفُوقُهُمْ بِمَرَاحِلَ كَبِيرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21371, 'أَشْوَاطٌ', 'أشواط', 'مصدر', '', 'ءشواط', 'شط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21372, 'مُشَاطَرَةٌ', 'مشاطرة', 'مصدر', 'شطر', 'مشاطرة', 'مشطرة', 'مص. شَاطَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَاطَرَةٌ-مُشَاطَرَةٌ [ش ط ر] (مص. شَاطَرَ). ""مُشَاطَرَةُ الأَحْزَانِ"" : مُقَاسَمَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21373, 'مُشَاغَبَةٌ', 'مشاغبة', 'مصدر', 'شغب', 'مشاغبة', 'مشغبة', 'مص. شَاغَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. شَاغَبَ). ""مُشَاغَبَةُ الأَوْلاَدِ فِي سَاحَةِ اللَّعِبِ"" : الْمُشَاكَسَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21374, 'مُشَافَهَةٌ', 'مشافهة', 'مصدر', 'شفه', 'مشافهة', 'مشفهة', 'مص. شَافَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. شَافَهَ). ""خَاطَبَ الْجُمْهُورَ مُشَافَهَةً"" : خَاطَبَهُمْ وَجْهاً لِوَجْهٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21375, 'شَوْقٌ', 'شوق', 'مصدر', 'شوق', 'شوق', 'شق', 'مص. شَاقَ', '', '', 'مفرد', 'DnN', '', '', '"أَشْوَاقٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَاقَ). ""بِهِ شَوْقٌ وَحَنِينٌ لِزِيَارَةِ وَطَنِهِ"" : نُزُوعُ النَّفْسِ إِلَى...، تَعَلُّقُهَا. ""يَشْتَاقُ إِلَى دَرْسِ الأَدَبِ وَاللُّغَةِ أَشَدَّ الشَّوْقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21376, 'أَشْوَاقٌ', 'أشواق', 'مصدر', '', 'ءشواق', 'شق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21377, 'مُشَاكَسَةٌ', 'مشاكسة', 'مصدر', 'شكس', 'مشاكسة', 'مشكسة', 'مص. شَاكَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. شَاكَسَ). ""مُشَاكَسَةٌ عَنِيفَةٌ"" : مُشَاغَبَةٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21378, 'مُشَاكَلَةٌ', 'مشاكلة', 'مصدر', 'شكل', 'مشاكلة', 'مشكلة', 'مص. شَاكَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُشَاكَلَةٌ-مُشَاكَلَةٌ [ش ك ل] (مص. شَاكَلَ). ""لاَحَظَ مُشَاكَلَةً فِي مَوَادِّ الصِّنَاعَةِ التَّقْلِيدِيَّةِ"" : مُشَابَهَةً، مُمَاثَلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21379, 'شَبَقٌ', 'شبق', 'مصدر', 'شبق', 'شبق', 'شبق', 'مص. شَبِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَبِقٌ-شَبِقٌ [ش ب ق] (صِيغَةُ فَعِل). ""وَلَدٌ شَبِقٌ"" : شَدِيدُ الشَّهْوَةِ الجِنْسِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21380, 'مُشَاهَدَةٌ', 'مشاهدة', 'مصدر', 'شهد', 'مشاهدة', 'مشهدة', 'مص. شَاهَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. شَاهَدَ). ""مُشَاهَدَةُ سَيْرِ الأَعْمَالِ"" : مُعَايَنَتُهَا. ""مَنْظَرٌ يَسْتَحِقُّ الْمُشَاهَدَةَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21381, 'شأْوٌ', 'شأو', 'مصدر', 'شأو', 'شءو', 'ش', 'مص. شأوَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شأْوٌ-شأْوٌ [ش أ و] (مص. شأوَ). 1.""بَلَغَ شَأْواً بَعِيدَ الْمَدَى فِي عَمَلِهِ"" : غَايَةً وَشَأْناً. 2.""هُوَ بِعِيدُ الشَّأْوِ"" : بَعِيدُ الهِمَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21382, 'مُشَاوَرَةٌ', 'مشاورة', 'مصدر', 'شور', 'مشاورة', 'مشرة', 'مص. شَاوَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. شَاوَرَ). ""الْمُشَاوَرَةُ دَلِيلُ القَائِدِ"" : طَلَبُ رَأْيِ النَّاسِ، الاسْتِشَارَةُ. ""دَعَاهُ إِلَى الْمُشَاوَرَةِ لاِتِّخَاذِ مَوْقِفٍ مُوَحَّدٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21383, 'شَبَابٌ', 'شباب', 'مصدر', 'شبب', 'شباب', 'شبب', 'مص. شَبَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَبَابٌ-شَبَابٌ [ش ب ب] (مص. شَبَّ). ""هُوَ فِي رَيْعَانِ الشَّبَابِ"" : فِي رَيْعَانِ الفُتُوَّةِ، أيْ مَا بَعْدَ مَرْحَلَةِ الطُّفُولَةِ. ""عُنْفُوَانُ الشَّبَابِ"" أَلاَ لَيْتَ الشَّبَابَ يَعُودُ يَوْمـا*فأُخْبِرَهُ بِمَا فَعَـلَ الْمَشِيبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21384, 'شَبٌّ', 'شب', 'مصدر', 'شبب', 'شب', 'شب', 'مص. شَبَّ', '', '', 'مفرد', 'DnN', '', '', '"شَبابٌ:شُبَّانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَبَّ). 1.""هُو شَبٌّ"" : يَافِعٌ، فِي رَيْعَانِ الشَّبَابِ. 2. : مِلْحٌ مَعْدِنِيٌّ، لَوْنُهُ أبْيَضُ، وَهُوَ مَا يُعْرَفُ فِي الكِيميَاءِ بِكَبْرِيتِيَّاتِ الأَلمِنْيُومِ وَالبُوتَاسِيوم، يُسْتَعْمَلُ فِي الدِّبَاغَةِ وَحِفْظِ الجُلُودِ مِنَ التَّفَسُّخِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21385, 'شَبابٌ', 'شباب', 'مصدر', '', 'شباب', 'شبب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21386, 'شُبَّانٌ', 'شبان', 'مصدر', '', 'شبان', 'شبن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21387, 'شَبِيبَةٌ', 'شبيبة', 'مصدر', 'شبب', 'شبيبة', 'شببة', 'مص. شَبَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَبِيبَةٌ-شَبِيبَةٌ [ش ب ب] (مص. شَبَّ). 1. ""فِي مَرْحَلَةِ الشَّبِيبَةِ"" : فِي مَرْحَلَةِ الشَّبَابِ. 2. ""وِزَارَةُ الشَّبِيبَةِ وَالرِّيَاضَةِ"": الوِزَارَةُ الْمُهْتَمَّةُ بِشُؤُونِ الشَّبَابِ وَالرِّيَاضَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21388, 'شِبَعٌ', 'شبع', 'مصدر', 'شبع', 'شبع', 'شبع', 'مص. شَبِعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شِبَعٌ-شِبَعٌ، شَبَعٌ [ش ب ع] (مص. شَبِعَ). ""أكَلَ حَتَّى الشِّبَعَ"" : إلَى حَدِّ امْتِلاَءِ بَطْنِهِ، أَي ما يُشْبِعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21389, 'شَجْبٌ', 'شجب', 'مصدر', 'شجب', 'شجب', 'شجب', 'مص. شَجَبَ', '', '', 'مفرد', 'DnN', '', '', '"شُجُوبٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَجَبَ). 1.""بِهِ شَجْبٌ"" : بِهِ هَمٌّ وَحُزْنٌ. 2.""تَعَرَّضَ مَوْق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21390, 'تَشْبِيهٌ', 'تشبيه', 'مصدر', 'شبه', 'تشبيه', 'تشبه', 'مص. شَبَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. شَبَّهَ). 1.""أَوْرَدَ الشَّاعِرُ تَشْبِيهاً جَمِيلاً"" : أَتَى بِصُورَةٍ يُشَبِّهُ فِيهَا مَثَلاً وَجْهَ الْمَرْأَةِ بِالقَمَرِ. 2.""رَجُلٌ كَالأَسَدِ"" : الكَافُ فِي الجُمْلَةِ أَدَاةُ تَشْبِيهٍ. مِنْ أَدَوَاتِ التَّشْبِيهِ : كَأَنَّ، مِثْلَ، الكَافُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21391, 'تشابيه', 'تشابيه', 'مصدر', '', 'تشابيه', 'تشبه', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21392, 'شَتَاتٌ', 'شتات', 'مصدر', 'شتت', 'شتات', 'شتت', 'مص. شَتَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَتَاتٌ-شَتَاتٌ [ش ت ت] (مص. شَتَّ). 1.""شَتَاتُ النَّاسِ"": تَفَرُّقُهُمْ. 2.""جَاءوا شَتَاتَ شَتَاتَ"" : جَاءوا مُتَفَرِّقِينَ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21393, 'شَتٌّ', 'شت', 'مصدر', 'شتت', 'شت', 'شت', 'مص. شَتَّ', '', '', 'مفرد', 'DnN', '', '', '"أَشْتَاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَتَّ). ""جَاءوا أَشْتَاتاً"" : مُتَفَرِّقِينَ، مُوَزِّعِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21394, 'أَشْتَاتٌ', 'أشتات', 'مصدر', '', 'ءشتات', 'شتت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21395, 'شَتِيتٌ', 'شتيت', 'مصدر', 'شتت', 'شتيت', 'شتت', 'مص. شَتَّ', '', '', 'مفرد', 'DnN', '', '', '"شَتَّى"', '', 'R', '', '', '', '', '', '', '"(مص. شَتَّ). ن. شَتَّى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21396, 'شَتَّى', 'شتى', 'مصدر', '', 'شتى', 'شت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21397, 'شَتْمٌ', 'شتم', 'مصدر', 'شتم', 'شتم', 'شتم', 'مص. شَتَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَتْمٌ-شَتْمٌ [ش ت م] (مص. شَتَمَ). ""أَوْسَعَهُ شَتْماً لَنْ يَنْسَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21398, 'شَجْوٌ', 'شجو', 'مصدر', 'شجو', 'شجو', 'شج', 'مص. شَجَا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَجْوٌ-شَجْوٌ [ش ج و] (مص. شَجَا). ""اِشْتَدَّ بِهِ الشَّجْوُ"": الحُزْنُ، الهَمُّ، الغَمُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21399, 'شُجُوبٌ', 'شجوب', 'مصدر', '', 'شجوب', 'شجب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21400, 'شَجَاعَةٌ', 'شجاعة', 'مصدر', 'شجع', 'شجاعة', 'شجعة', 'مص. شَجُعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَجَاعَةٌ-شَجَاعَةٌ [ش ج ع] (مص. شَجُعَ). ""أَظْهَرَ شَجَاعَةً"": أَظْهَرَ قُوَّةً وَجُرْأَةً، شِدَّةَ القَلْبِ عِنْدَ اليَأْسِ، رَبَاطَةَ الجَأْشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21401, 'شَجْنٌ', 'شجن', 'مصدر', 'شجن', 'شجن', 'شجن', 'مص. شَجَنَ', '', '', 'مفرد', 'DnN', '', '', '"شُجُونٌ:أَشْجَانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَجَنَ). ""شَجْنُ النَّفْسِ"" : حُزْنُهَا، غَمُّها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21402, 'شُجُونٌ', 'شجون', 'مصدر', '', 'شجون', 'شجن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21403, 'أَشْجَانٌ', 'أشجان', 'مصدر', '', 'ءشجان', 'شجن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21404, 'شَجَنٌ', 'شجن', 'مصدر', 'شجن', 'شجن', 'شجن', 'مص. شَجُنَ، شَجِنَ', '', '', 'مفرد', 'DnN', '', '', '"شُجُونٌ:أَشْجَانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَجُنَ، شَجِنَ). 1. ""أَضْعَفَهُ الشَّجَنُ"" : الحُزْنُ، الغَمُّ. 2.""حَدِيثٌ ذُو شُجُونٍ"" : ذُو فُنُونٍ وَشُعَبٍ يَتَّصِلُ بَعْضُهُ بِبَعْضٍ. 3. ""غُصْنٌ شَجَنٌ"" : مُلْتَفٌّ، مُشْتَبِكٌ. 4. ""يُفَكِّرُ فِي شُجُونِهِ"" : فِي حَاجَاتِهِ وَشَوَاغِلِهِ، أَوْ فِي أَحْزَانِهِ وَهُمُومِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21405, 'شُجُونٌ', 'شجون', 'مصدر', '', 'شجون', 'شجن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21406, 'أَشْجَانٌ', 'أشجان', 'مصدر', '', 'ءشجان', 'شجن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21407, 'شَجَا', 'شجا', 'مصدر', 'شجو', 'شجا', 'شج', 'مص. شَجِيَ', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"شَجَا-شَجَا [ش ج و] (مص. شَجِيَ). ""غَمَّهُ الشَّجَا"": غَمَّهُ الهَمُّ وَالحُزْنُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21408, 'شُحٌّ', 'شح', 'مصدر', 'شحح', 'شح', 'شح', 'مص. شَحَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شُحٌّ-شُحٌّ [ش ح ح] (مص. شَحَّ). 1.""رَجُلٌ شُحٌّ"" : بَخِيلٌ. 2. النساء آية 128وَأُحْضِرَتِ الأَنْفُسُ الشُّحَّ . (قرآن) : شِدَّةُ البُخْلِ، أَيْ جُبِلَتْ عَلَيْهِ فَكَأَنَّهَا حَاضِرَتُهُ لاَ تَغِيبُ عَنْهُ. ""رَأَيْتُ بَيْنَ السَّخَاءِ وَالشُّحِّ تَفَاوُتاً بَعِيداً"". (ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21409, 'شُحُوبٌ', 'شحوب', 'مصدر', 'شحب', 'شحوب', 'شحب', 'مص. شَحَبَ، شَحُبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شُحُوبٌ-شُحُوبٌ [ش ح ب] (مص. شَحَبَ، شَحُبَ). 1.""شُحُوبُ الوَجْهِ"" : تَغَيُّرُ لَوْنِهِ. 2.""شُحُوبُ الجِسْمِ"" : هُزَالُهُ، ضَعْفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21410, 'شَحْمٌ', 'شحم', 'مصدر', 'شحم', 'شحم', 'شحم', 'مص. شَحَمَ', '', '', 'مفرد', 'DnN', '', '', '"شُحُومٌ:شُحُومَاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَحَمَ). 1.""خَرُوفٌ كَثِيرُ الشَّحْمِ"" : مَا ابْيَضَّ وَخَفَّ مِنْ لَحْمِهِ. 2.""جَاءَ بِلَحْمِهِ وَشَحْمِهِ"": أَيْ بِذَاتِهِ. 3.""مَادَّةُ الشَّحْمِ"" : مَادَّةٌ دُهْنِيَّةٌ تُسْتَخْرَجُ مِنَ الحَيَوَانِ أَوِ النَّبَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21411, 'شُحُومٌ', 'شحوم', 'مصدر', '', 'شحوم', 'شحم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21412, 'شُحُومَاتٌ', 'شحومات', 'مصدر', '', 'شحومات', 'شحمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21413, 'شَحْنٌ', 'شحن', 'مصدر', 'شحن', 'شحن', 'شحن', 'مص. شَحَنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَحْنٌ-شَحْنٌ [ش ح ن] (مص. شَحَنَ). 1. ""مَوَادُّ لِلشَّحْنِ"" : مَوَادُّ مُهَيَّأَةٌ لِتُبعَثَ مِنْ مَكَانٍ إلَى آخَرَ بَرّاً أوْ بَحْراً أوْ جَوّاً. 2. ""شَحْنُ البَضَائِعِ"" : إرْسَالهَا، بَعْثُهَا. 3.""سَيَّارَةُ شَحْنٍ""، ""سَفِينَةُ شَحْنٍ"" : كُلُّ أَداةِ نَقْلٍ مُخَصَّصَةٍ لِنَقْلِ البَضَائِع."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21414, 'شَخْبٌ', 'شخب', 'مصدر', 'شخب', 'شخب', 'شخب', 'مص. شَخَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَخْبٌ-شَخْبٌ [ش خ ب] (مص. شَخَبَ). 1.""شَخْبُ لَبَنٍ"" : دَفْعَةٌ مِنْهُ عِنْدَ الحَلْبِ. 2.""شَخْبٌ فِي الإِنَاءِ وَشَخْبٌ فِي الأَرْضِ"". (مثل) : أَيْ يُصِيبُ مَرَّةً وَيُخْطِئُ مَرَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21415, 'شَخْرٌ', 'شخر', 'مصدر', 'شخر', 'شخر', 'شخر', 'مص. شَخَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَخْرٌ-شَخْرٌ [ش خ ر] (مص. شَخَرَ). 1.""شَخْرُ الشَّبَابِ"": شَرْخُهُ، أَوَّلُهُ. 2.""شَخْرُ الرَّحْلِ"" : مَا بَيْنَ أَوَّلِهِ وَآخِرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21416, 'شَخِيرٌ', 'شخير', 'مصدر', 'شخر', 'شخير', 'شخر', 'مص. شَخَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شِخِّيرٌ-شِخِّيرٌ [ش خ ر] (صِيغَةُ فِعِّيل لِلْمُبَالَغَةِ). ""يَصْعُبُ عَلَيَّ النَّوْمُ بِجَانِبِ شِخِّيرٍ"" : إِنْسَانٌ كَثِيرُ الشَّخِيرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21417, 'تَشْخِيصٌ', 'تشخيص', 'مصدر', 'شخص', 'تشخيص', 'تشخص', 'مص. شَخَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْخِيصٌ-تَشْخِيصٌ [ش خ ص] (مص. شَخَّصَ). 1.""تَمَكَّنَ الطَّبِيبُ مِنْ تَشْخِيصِ الْمَرَضِ"" : مِنْ مَعْرِفَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21418, 'شَدٌّ', 'شد', 'مصدر', 'شدد', 'شد', 'شد', 'مص. شَدَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَدٌّ-شَدٌّ [ش د د] (مص. شَدَّ). 1.""تَقَطَّعَ الحَبْلُ مِنْ كَثْرَةِ الشَّدِّ"" : الجَذْبُ، الجَرُّ، السَّحْبُ. 2.""لَشَدَّ مَا جَنَيْتَ عَلَيَّ"" : مَا أَقْوَى، مَا أَقْسَى جِنَايَتَكَ عَلَيَّ. ""لَشَدَّ مَا كَانَ سُرُورِي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21419, 'تَشْذِيرٌ', 'تشذير', 'مصدر', 'شذر', 'تشذير', 'تشذر', 'مص. شَذَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْذِيرٌ-تَشْذِيرٌ [ش ذ ر] (مص. شَذَّرَ).""تَشْذِيرُ عِقْدٍ"" : الفَصْلُ بَيْنَ حَبَّاتِهِ بِخَرْزٍ أَوْ قِطَعٍ مِنْ لَوْنٍ آخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21420, 'شَدٌّ', 'شد', 'مصدر', 'شدد', 'شد', 'شد', 'مص. شَدَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَدٌّ-شَدٌّ [ش د د] (مص. شَدَّ). ""شَدُّ النَّهارِ"" : وَقْتُ ارْتِفاعِ شَمْسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21421, 'شَدْوٌ', 'شدو', 'مصدر', 'شدو', 'شدو', 'شد', 'مص. شَدا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَدْوٌ-شَدْوٌ [ش د و] (مص. شَدا). 1.""كَانَ إِنْشَادُهُ للِشِّعْرِ شَدْواً"" : تَرَنُّماً تَغَنِّياً. 2.""أَخَذَ شَدْواً مِنَ الْمَالِ"" : جُزْءاً قَلِيلاً مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21422, 'تَشْدِيدٌ', 'تشديد', 'مصدر', 'شدد', 'تشديد', 'تشدد', 'مص. شَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْدِيدٌ-تَشْدِيدٌ [ش د د] (مص. شَدَّدَ). 1.""قَرَّرَ تَشْدِيدَ الحِصَارِ عَلَيْهِ"" : تَقْوِيتَهُ، إِحْكَامَهُ. ""تَشْدِيدُ العُقُوبَةِ"". 2.""التَّشْدِيدُ فِي طَلَبِ أَمْرٍ مَّا"" : الإِلْحَاحُ. 3.""تَشْدِيدُ الحَرْفِ"": وَضْعُ عَلاَمَةِ شَدَّةٍ عَلَيْهِ (ـّ )."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21423, 'شِدَّةٌ', 'شدة', 'مصدر', 'شدد', 'شدة', 'شدة', 'مص. شَدَّ، يَشِدُّ', '', '', 'مفرد', 'DnN', '', 'Pf', '":شِدَدٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَدَّ، يَشِدُّ). 1.""شِدَّةُ البَرْدِ"" : قُوَّتُهُ، أَيِ البَرْدُ الَّذِي يَصْعُبُ تَحَمُّلُهُ. ""شِدَّةُ الحَرِّ"" ""شِدَّةُ الْمَرَضِ"" : ""شِدَّةُ الأَلَمِ"" ""شِدَّةُ العَيْشِ"". 2.""وَقْتُ الشِّدَّةِ"" : أَيْ وَقْتُ الصُّعُوبَةِ وَالوَطْأَةِ الشَّدِيدَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21424, 'شِدَدٌ', 'شدد', 'مصدر', '', 'شدد', 'شد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21425, 'شَذُوذٌ', 'شذوذ', 'مصدر', 'شذذ', 'شذوذ', 'شذذ', 'مص. شَذَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَذُوذٌ-شَذُوذٌ [ش ذ ذ] (مص. شَذَّ). ""فِي طَبْعِهِ شُذُوذٌ جِنْسِيٌّ"" : العُزُوفُ عَنِ الْمُمَارَسَةِ الجِنْسِيَّةِ الطَّبِيعِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21426, 'شَذْوٌ', 'شذو', 'مصدر', 'شذو', 'شذو', 'شذ', 'مص. شَذَا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَذْوٌ-شَذْوٌ [ش ذ و] (مص. شَذَا). 1.""فَاحَ شَذْوُ العِطْرِ"": رِيحُهُ. 2.""رَائِحَةُ الشَّذْوِ"" : المِسْكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21427, 'تَشْذِيبٌ', 'تشذيب', 'مصدر', 'شذب', 'تشذيب', 'تشذب', 'مص. شَذَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْذِيبٌ-تَشْذِيبٌ [ش ذ ب] (مص. شَذَّبَ). 1.""عَمِلَ عَلَى تَشْذِيبِ الأَشْجَارِ"" : عَلَى تَقْضِيبِهَا، قَصِّ الأَوْرَاقِ الزَّائِدَةِ، تَقْلِيمِهَا. 2.""تَشْذِيبُ العِبَارَةِ"" : تَهْذِيبُهَا وَالعِنَايَةُ بِتَرْكِيبِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21428, 'شَذْبٌ', 'شذب', 'مصدر', 'شذب', 'شذب', 'شذب', 'مص. شَذَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَذْبٌ-شَذْبٌ [ش ذ ب] (مص. شَذَبَ). ""قَضَى نَهَارَهُ فِي شَذْبِ الأَشْجَارِ"" : إِزَالَةُ مَا عَلَيْهَا مِنْ أَغْصَانٍ وَأَوْرَاقٍ ذَابِلَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21429, 'شُرُوحٌ', 'شروح', 'مصدر', '', 'شروح', 'شرح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21430, 'شَرَارَةٌ', 'شرارة', 'مصدر', 'شرر', 'شرارة', 'شررة', 'مص. شَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. شَرَّ). 1.""شَرَارَةُ النَّارِ"" : الذَّرَّةُ الْمُتُوهِّجَةُ الْمُتَطَايِرَةُ مِنَ النَّارِ. 2.""الشَّرَارَةُ الكَهْرَبَائِيَّةُ"" : الضَّوْءُ اللاَّمِعُ. 3.""اِنْطَلَقَتِ الشَّرَارَةُ الأُولَى"" : كِنَايَةٌ عَنْ بِدَايَةِ حَرْبٍ أَوْ ثَوْرَةٍ أَوِ انْتِفَاضَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21431, 'شَرٌّ', 'شر', 'مصدر', 'شرر', 'شر', 'شر', 'مص. شَرَّ', '', '', 'مفرد', 'DnN', '', '', '"شُرُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَرَّ). 1.""الخَيْرُ وَالشَّرُّ"" : الخَيْرُ وَالسُّوءُ. 2.""فِيهِ شَرٌّ لِلنَّاسِ"" : فِيهِ فَسَادٌ. ""الشَّرُّ قَلِيلُهُ كَثِيرٌ"". 3.""هَزَمَهُمْ شَرَّ هَزِيمَةٍ"" : أَسْوَأَ... 4.""هُوَ شَرُّ النَّاسِ"" : مِنْ أَشْرَارِ النَّاسِ، مَنْ يَحْمِلُ السُّوءَ وَكُلَّ مَا فِيهِ فَسَادٌ. 5.""وَقَعَ بَيْنَ شَرَّيْنِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21432, 'شُرُورٌ', 'شرور', 'مصدر', '', 'شرور', 'شرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21433, 'شَرْبٌ', 'شرب', 'مصدر', 'شرب', 'شرب', 'شرب', 'مص. شَرَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَرْبٌ-شَرْبٌ [ش ر ب] (مص. شَرَبَ).: نَاسٌ شَارِبُونَ مُجْتَمِعُونَ عَلَى الشَّرَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21434, 'شِرْبٌ', 'شرب', 'مصدر', 'شرب', 'شرب', 'شرب', 'مص. شَرِبَ', '', '', 'مفرد', 'DnN', '', '', '"أَشْرَابٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَرِبَ). 1.""مَاءٌ شِرْبٌ"" : مَاءٌ يُشْرَبُ، أَوْ نَصِيبٌ مِنْهُ. 2. ""آنَ شِرْبُهُ"" : وَقْتُ الشُّرْبِ.الشعراء آية 155 لَهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَعْلُومٍ . (قرآن). 3. ""شِرْبُ الْمَاءِ"" : مَوْرِدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21435, 'أَشْرَابٌ', 'أشراب', 'مصدر', '', 'ءشراب', 'شرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21436, 'شُرْبٌ', 'شرب', 'مصدر', 'شرب', 'شرب', 'شرب', 'مص.. شَرِبَ شَرِبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شُرْبُ-شُرْبُ [ش ر ب] (مص.. شَرِبَ شَرِبَ). ""وَجَدَ الأَكْلَ وَالشُّرْبَ"" : مَا يُؤْكَلُ وَيُشْرَبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21437, 'تَشْرِيحٌ', 'تشريح', 'مصدر', 'شرح', 'تشريح', 'تشرح', 'مص. شَرَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْرِيحٌ-تَشْرِيحٌ [ش ر ح] (مص. شَرَّحَ). 1.""عِلْمُ التَّشْرِيحِ"": البَحْثُ فِي أَعْضَاءِ الكاَئِنِ الحَيِّ وَتَرْكِيبِهِ وَكَيْفِيَّةِ اشْتِغَالِ خَلاَيَاهُ. 2.""التَّشْرِيحُ الجِنَائِيُّ"" ‎: البَحْثُ فِي جُثْمَانِ الْمَيِّتِ لِمَعْرِفَةِ أَسْبَابِ الوَفَاةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21438, 'شَرْحٌ', 'شرح', 'مصدر', 'شرح', 'شرح', 'شرح', 'مص. شَرَحَ', '', '', 'مفرد', 'DnN', '', '', '"شُرُوحٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَرَحَ). ""قَدَّمَ شَرْحاً وَافِياً لِمَعَانِي القَصِيدَةِ"" : تَفْسِيراً، تِبْيَاناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21439, 'أَشْرَاطٌ', 'أشراط', 'مصدر', '', 'ءشراط', 'شرط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21440, 'شَرْخٌ', 'شرخ', 'مصدر', 'شرخ', 'شرخ', 'شرخ', 'مص. شَرَخَ', '', '', 'مفرد', 'DnN', '', '', '"شُرُوخٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَرَخَ). 1.""فِي شَرْخِ شَبَابِهِ"" : فِي شَخْرِهِ وَأَوَّلِهِ وَرَيْعَانِهِ وَفُتُوَّتِهِ. 2.""أَحْدَثَ الزِّلْزَالُ شَرْخاً فِي جِدَارِ العِمَارَةِ"" : شَقَّاً، فَتْحَةً، اِنْشِقَاقاً، صَدْعاً. 3.""شَرْخُ الجِذْرِ"": أَصْلُهُ، أَوْ عِرْقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21441, 'شُرُوخٌ', 'شروخ', 'مصدر', '', 'شروخ', 'شرخ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21442, 'تَشَرُّدٌ', 'تشرد', 'مصدر', 'شرد', 'تشرد', 'تشرد', 'مص. شَرَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشَرُّدٌ-تَشَرُّدٌ [ش ر د] (مص. شَرَّدَ). ""يَعِيشُ حَيَاةَ تَشَرُّدٍ"" : حَيَاةَ تَسَكُّعٍ، الخُرُوجُ عَنِ الوَضْعِ الطَّبِيعِيِّ لِلْحَيَاةِ الاجْتِمَاعِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21443, 'تَشْرِيدٌ', 'تشريد', 'مصدر', 'شرد', 'تشريد', 'تشرد', 'مص. شَرَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْرِيدٌ-تَشْرِيدٌ [ش ر د] (مص. شَرَّدَ). ""تَشْرِيدُ السُّكَّانِ"" : طَرْدُهُمْ مِنْ سُكْنَاهُمْ وَتَرْكُهُمْ بِلاَ مَأْوىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21444, 'شُرُودٌ', 'شرود', 'مصدر', 'شرد', 'شرود', 'شرد', 'مص. شَرَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شُرُودٌ-شُرُودٌ [ش ر د] (مص. شَرَدَ). 1. ""شُرُودُ الذِّهْنِ"" : تَيَهَانُهُ، عَدَمُ الانْتِبَاهِ إِلَى مَا يُحِيطُ بِهِ. 2. ""كَانَ اللاعِبُ فِي حَالَةِ شُرُودٍ"" (ريا) : إِذَا كَانَ لاعِبُ كُرَةِ القَدَمِ مُنْفَلِتاً وَرَاءَ دِفَاعِ الْخَصْمِ وَلَمْ يَتَمَكَّنْ مِنْ تَمْرِيرِ الكُرَةِ مِنْ أَمَامِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21445, 'شَرْشَرَةٌ', 'شرشرة', 'مصدر', 'شرشر', 'شرشرة', 'شرشرة', 'مص. شَرْشَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَرْشَرَةٌ-شَرْشَرَةٌ [ش ر ش ر] (مص. شَرْشَرَ). ""يَجُزُّ النَّبَاتَ بِالشَّرْشَرَةِ"" : المِنْجَل الصَّغِير."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21446, 'شَرْطٌ', 'شرط', 'مصدر', 'شرط', 'شرط', 'شرط', 'مص. شَرَطَ', '', '', 'مفرد', 'DnN', '', '', '"شُرُوطٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَرَطَ). 1.""قَبِلَ شَرْطَهُ"" : مَا يُوضَعُ لِيُلْتَزَمَ بِهِ فِي بَيْعٍ أَوْ مُعَاهَدَةٍ أَوِ الْتِزَامٍ بِأَمْرٍ مَّا. ""عَلَى شَرْطٍ"" ""بِشَرْطٍ"" ""اِسْتَسْلَمَ بِلاَ قَيْدٍ أَوْ شَرْطٍ"" ""اِتَّفَقُوا عَلَى شُرُوطِ الْمُعَاهَدَةِ"". 2.""الشَّرْطُ فِي النَّحْوِ"" : هُوَ قَرْنُ أَمْرٍ بِأَمْرٍ آخَرَ بِوُجُودِ أَدَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21447, 'شُرُوطٌ', 'شروط', 'مصدر', '', 'شروط', 'شرط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21448, 'شَرَطٌ', 'شرط', 'مصدر', 'شرط', 'شرط', 'شرط', 'مص. شَرِطَ', '', '', 'مفرد', 'DnN', '', '', '"أَشْرَاطٌ"', '', 'R', '', '', '', '', '', '', '"شَرَطٌ-شَرَطٌ [ش ر ط]. ج: أَشْرَاطٌ . (مص. شَرِطَ). 1.""ظَهَرَ شَرَطٌ عَلَى وَجْهِهِ"" : عَلاَمَةٌ.محمد آية 18 فَهَلْ يَنْظُرُونَ إِلاّ السَّاعَةَ أَنْ تَأْتِيَهُمْ بَغْتَةً فَقَدْ جَاءَ أَشْرَاطُهَا . (قرآن). 2.""شَرَط"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21449, 'شَرِكَةٌ', 'شركة', 'مصدر', 'شرك', 'شركة', 'شركة', 'مص. شَرِكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. شَرِكَ). ""أَسَّسُوا شَرِكَةً تِجَارِيَّةً"" : أَيْ مُؤَسَّسَةً لِعَدَدٍ مَحْدُودٍ مِنَ النَّاسِ كُلُّ وَاحِدٍ مِنْهُمْ يُسَاهِمُ بِقَدْرٍ مِنَ الْمَالِ لإِدَارَةِ تِجَارَةٍ مَّا يَتَقَاسَمُونَ أَرْبَاحَهَا. ""شَرِكَةُ البِنَاءِ وَالْمُقَاوَلاَتِ"" ""شَرِكَةٌ عَقَارِيَّةٌ"" ""شَرِكَةٌ مَجْهُولَةُ الاسْمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21450, 'تَشْرِيعٌ', 'تشريع', 'مصدر', 'شرع', 'تشريع', 'تشرع', 'مص. شَرَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. شَرَّعَ). 1.""يَلْتَزِمُ بِالتَّشْرِيعِ الإِسْلاَمِيِّ"" : القَوَانِين وَالفَرَائِض كَمَا سَنَّهَا الإسْلاَمُ. 2.""سَنَّ البَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21451, 'شَرْعٌ', 'شرع', 'مصدر', 'شرع', 'شرع', 'شرع', 'مص. شَرَعَ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"شَرَعٌ-شَرَعٌ [ش ر ع]. ""هُمْ فِي الأَمْرِ شَرَعٌ"". سَواءٌ. ""نَحْنُ فِي هَذَا الأَمْرِ شَرَعٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21452, 'شُرُوعٌ', 'شروع', 'مصدر', 'شرع', 'شروع', 'شرع', 'مص. شَرَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شُرُوعٌ-شُرُوعٌ [ش ر ع] (مص. شَرَعَ). 1.""أَفْعَالُ الشُّرُوعِ"": أَي الأَفْعَالُ الَّتِي تَأْتِي بِمَعْنَى ابْتَدَأَ، أَيْ بَدْءُ العَمَلِ وَالأَخْذُ فيهِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21453, 'تَشْرِيفٌ', 'تشريف', 'مصدر', 'شرف', 'تشريف', 'تشرف', 'مص. شَرَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْرِيفٌ-تَشْرِيفٌ [ش ر ف] (مص. شَرَّفَ). ""تَشْرِيفُ البَطَلِ"": تَعْظِيمُهُ، تَبْجِيلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21454, 'شَرَفٌ', 'شرف', 'مصدر', 'شرف', 'شرف', 'شرف', 'مص. شَرُفَ', '', '', 'مفرد', 'DnN', '', '', '"أَشْرَافٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَرُفَ). 1.""هُوَ مِنْ أَهْلِ الشَّرَفِ"" : مِنْ أَهْلِ الْحَسَبِ وَالنَّسَبِ وَالْمَجْدِ . 2.""يُحَافِظُ عَلَى شَرَفِ عَائِلَتِهِ"" : عَلَى عُلُوِّهَا وَمَجْدِهَا وَمَكَانَتِهَا. ""يُعَدُّ الْمَوْتُ شَرَفاً لِمَنْ يُدَافِعُ عَنِ الْحَقِيقَةِ"". (م. ص. الرافعي). 3.""أَعْطَاهُ كَلِمَةَ الشَّرَفِ"" : كَلِمَةَ الصِّدْقِ الَّتِي لَنْ يَحِيدَ عَنْهَا أَوْ يُخِلَّ بِهَا. 4.""شَرَفُ الْمِهْنَةِ"" : مَنْزِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21455, 'أَشْرَافٌ', 'أشراف', 'مصدر', '', 'ءشراف', 'شرف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21456, 'تَشْرِيقٌ', 'تشريق', 'مصدر', 'شرق', 'تشريق', 'تشرق', 'مص. شَرَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْرِيقٌ-تَشْرِيقٌ [ش ر ق] (مص. شَرَّقَ). 1.""تَشْرِيقُ الْمُسَافِرِ"" : اِتِّجَاهُهُ صَوْبَ الشَّرْقِ. 2.""أَيَّام التشريقُ"" : الأَيَّامُ الثلاثةُ التَّالِيةُ لِعيدِ الأَضْحَى. (من مناسك الحج)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21457, 'شُرُوقٌ', 'شروق', 'مصدر', 'شرق', 'شروق', 'شرق', 'مص. شَرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شُرُوقٌ-شُرُوقٌ [ش ر ق] (مص. شَرَقَ). ""شُرُوقُ الشَّمْسِ"" : وَقْتُ شُرُوقِ الشَّمْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21458, 'تَشْرِيكٌ', 'تشريك', 'مصدر', 'شرك', 'تشريك', 'تشرك', 'مص. شَرَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْرِيكٌ-تَشْرِيكٌ [ش ر ك] (مص. شَرَّكَ). 1.""رَغِبَ فِي تَشْرِيكِهِ"" : جَعْلُهُ شَرِيكاً. 2.""تَشْرِيكُ النَّعْلِ"" : وَضْعُ شِرَاكٍ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21459, 'شَطٌّ', 'شط', 'مصدر', 'شطط', 'شط', 'شط', 'مص. شَطَّ', '', '', 'مفرد', 'DnN', '', '', '"شُطُوطٌ:شُطَّانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَطَّ). ""عَلَى الشَّطِّ"" : عَلَى شَاطِئِ النَّهْرِ أَوِ البَحْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21460, 'شِرْكَةٌ', 'شركة', 'مصدر', 'شرك', 'شركة', 'شركة', 'مص. شَرِكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شِرْكَةٌ-شِرْكَةٌ [ش ر ك] (مص. شَرِكَ). 1.""بَيْنَهُمَا شِرْكَةٌ"" : عَقْدٌ يَجْمَعُ بَيْنَهُمَا لإِنْجَازِ عَمَلٍ مُشْتَرَكٍ. ""خَلَقَ اللَّهُ الذَّكَرَ لِلأُنْثَى وَجَعَلَ بَيْنَهُمَا أَسْبَابَ التَّحَابِّ وَعَلاَئِقَ الشِّرْكَةِ"" (الجاحظ). 2.""شِرْكَةٌ"" : ن. شَرِكَةٌ. 3.""شِرْكَةُ الشَّرِيكِ"" : نَصِيبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21461, 'تَشْرِيمٌ', 'تشريم', 'مصدر', 'شرم', 'تشريم', 'تشرم', 'مص. شَرَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْرِيمٌ-تَشْرِيمٌ [ش ر م] (مص. شَرَّمَ). ""تَشْرِيمُ الإِنَاءِ"" : تَشْقِيقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21462, 'شَرْنَقَةٌ', 'شرنقة', 'مصدر', 'شرنق', 'شرنقة', 'شرنقة', 'مص. شَرْنَقَ', '', '', 'مفرد', 'DnN', '', '', '"شَرَانِقُ"', '', 'R', '', '', '', '', '', '', '"(مص. شَرْنَقَ). ""خَرَجَتِ الفَرَاشَةُ مِنَ الشَّرْنَقَةِ"" : الغِلاَفُ الْحَرِيرِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21463, 'شَرَانِقُ', 'شرانق', 'مصدر', '', 'شرانق', 'شرنق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21464, 'شَرَاهَةٌ', 'شراهة', 'مصدر', 'شره', 'شراهة', 'شرهة', 'مص. شَرِهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَرَاهَةٌ-شَرَاهَةٌ [ش ر هـ] (مص. شَرِهَ). ""أَظْهَرَ شَرَاهَةً أَمَامَ الضُّيُوفِ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21465, 'شَرَهٌ', 'شره', 'مصدر', 'شره', 'شره', 'شره', 'مص. شَرِهَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَرَهٌ-شَرَهٌ [ش ر هـ] (مص. شَرِهَ). ""أَظْهَرَ شَرَهاً مَا بَعْدَهُ مِنْ شَرَهٍ"" : أَسْوَأُ الْحِرْصِ. ""لَقَدْ ص"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21466, 'شِرَاءٌ', 'شراء', 'مصدر', 'شري', 'شراء', 'شر', 'مص. شَرَى', '', '', 'مفرد', 'Dz', '', '', '"أَشْرِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '"(مص. شَرَى). ""السُّوقُ هُوَ مَكَانُ البَيْعِ وَالشِّرَاءِ"" : مَكَانُ التّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21467, 'أَشْرِيَةٌ', 'أشرية', 'مصدر', '', 'ءشرية', 'شرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21468, 'شَزْرٌ', 'شزر', 'مصدر', 'شزر', 'شزر', 'شزر', 'مص. شَزَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَزْرٌ - [ش ز ر]. (مص. شَزَرَ). ""نَظَرَ إِلَيْهِ شَزْرًا"" : نَظَرَ إِلَيْهِ بِغَضَبٍ وَاسْتِهَانَةٍ أَوْ إِعْرَاضٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21469, 'شُطُورٌ', 'شطور', 'مصدر', '', 'شطور', 'شطر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21470, 'شُطُوطٌ', 'شطوط', 'مصدر', '', 'شطوط', 'شطط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21471, 'شُطَّانٌ', 'شطان', 'مصدر', '', 'شطان', 'شطن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21472, 'شَطَطٌ', 'شطط', 'مصدر', 'شطط', 'شطط', 'شط', 'مص. شَطَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَطَطٌ-شَطَطٌ [ش ط ط] (مص. شَطَّ). ""فِي أَحْكَامِهِ شَطَطٌ"": ظُلْمٌ، جَوْرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21473, 'تَشْطِيبٌ', 'تشطيب', 'مصدر', 'شطب', 'تشطيب', 'تشطب', 'مص. شَطَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْطِيبٌ-تَشْطِيبٌ [ش ط ب] (مص. شَطَّبَ). 1.""تَشْطِيبُ اللَّحْمِ"" : تَشْرِيحُهُ قِطَعاً رِقَاقاً. 2.""تَشْطِيبُ الْجِسْمِ بِالسّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21474, 'شَطْبٌ', 'شطب', 'مصدر', 'شطب', 'شطب', 'شطب', 'مص. شَطَبَ', '', '', 'مفرد', 'DnN', '', '', '"شُطُوبٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَطَبَ). 1.""وَلَدٌ شَطْبٌ"" : طَوِيلٌ حَسَنُ الْخُلُقِ. 2.""الشَّطْبُ فِي الْمِيزَانِيَّةِ"" : تَسْجِيلُ مُجْمَلِ الْمَصَارِيفِ فِي الدَّفَاتِرِ لإِسْقَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21475, 'شُطُوبٌ', 'شطوب', 'مصدر', '', 'شطوب', 'شطب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21476, 'تَشْطِيرٌ', 'تشطير', 'مصدر', 'شطر', 'تشطير', 'تشطر', 'مص. شَطَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْطِيرٌ-تَشْطِيرٌ [ش ط ر] (مص. شَطَّرَ). 1.""تَشْطِيرُ الشَّيْءِ شَطْرَيْنِ"" : تَقْسِيمُهُ نِصْفَيْنِ، قِسْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21477, 'شَطْرٌ', 'شطر', 'مصدر', 'شطر', 'شطر', 'شطر', 'مص. شَطَرَ', '', '', 'مفرد', 'DnN', '', '', '"أَشْطُرٌ:شُطُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَطَرَ). 1.""شَطْرٌ مِنَ الشَّهْرِ"" : فَتْرَةٌ مِنْهُ، زَمَنٌ مَّا. ""أَمْضَى شَطْراً مِنَ الصَّيْفِ فِي رَامَ اللَّه"" (غسان كنفاني). 2.""قَسَّمَهُ شَطْرَيْنِ"": "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21478, 'أَشْطُرٌ', 'أشطر', 'مصدر', '', 'ءشطر', 'شطر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21479, 'شَعْرٌ', 'شعر', 'مصدر', 'شعر', 'شعر', 'شعر', 'مص. شَعَر، شَعُرَ', '', '', 'مفرد', 'DnN', '', '', '"شُعُورٌ:أَشْعَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَعَر، شَعُرَ). ""شَعْرُ البَدَنِ "" : مَا يَنْبُتُ فِي جِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21480, 'شَظَفٌ', 'شظف', 'مصدر', 'شظف', 'شظف', 'شظف', 'مص. شَظِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَظَفٌ-شَظَفٌ [ش ظ ف] (مص. شَظِفَ). ""يَعِيشُ حَيَاةَ شَظَفٍ"" : حَيَاةَ ضَيْقٍ وَشِدَّةٍ وَعَوَزٍ. "" أَقَامَ عَلَى شَظَفِ العَيْشِ"" ""يُقَاسِي مِنْ شَظَفِ العَيْشِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21481, 'شَعَاعٌ', 'شعاع', 'مصدر', 'شعع', 'شعاع', 'شعع', 'مص. شَعَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَعَاعٌ-شَعَاعٌ [ش ع ع] (مص. شَعَّ). 1. ""ذَهَبُوا شَعَاعاً"" : أَيْ مُتَفَرِّقِينَ. 2. ""طَارَتْ نَفْسُهُ شَعَاعاً"" : طَارَتْ خَوْفاً وَفَزَعاً، خَفَّتْ هِمَّتُهُ. أَقُولُ لَهَا وَقَدْ طَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21482, 'تَشْعِيبٌ', 'تشعيب', 'مصدر', 'شعب', 'تشعيب', 'تشعب', 'مص. شَعَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْعِيبٌ-تَشْعِيبٌ [ش ع ب] (مص. شَعَّبَ). 1.""تَشْعِيبُ الحَبِّ"" : تَفْرِيقُهُ، تَشْتِيتُهُ. 2.""تَشْعِيبُ الإِنَاءِ"" : إِصْلاَحُ صَدْعِهِ. 3.""تَشْعِيبُ الفِكْرَةِ"" : التَّعَمُّقُ فِيهَا إِلىَ حَدِّ جَعْلِهَا غَامِضَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21483, 'شَعْبٌ', 'شعب', 'مصدر', 'شعب', 'شعب', 'شعب', 'مص. شَعَبَ', '', '', 'مفرد', 'DnN', '', '', '"شُعُوبٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. شَعَبَ). 1.""الشَّعْبُ العَرَبِيُّ "" : الْجَمَاعَةُ مِنَ النَّاسِ تَجْمَعُهُمْ رَوَابِطُ مُشْتَرَكَةٌ وَيَتَكَلَّمُونَ لِسَاناً وَاحِداً، وَكَانَتِ الكَلِمَةُ تُطْلَقُ عَلَى القَبِيلَةِ أَوِ الْح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21484, 'شُعُوبٌ', 'شعوب', 'مصدر', '', 'شعوب', 'شعب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21485, 'شَعَبٌ', 'شعب', 'مصدر', 'شعب', 'شعب', 'شعب', 'مص. شَعِبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَعَبٌ-شَعَبٌ [ش ع ب] (مص. شَعِبَ). 1.""شَعَبُ الْمَنْكِبَيْنِ"": مَا بَيْنَهُمَا مِنْ بُعْدٍ عِنْدَ النَّاسِ. 2. ""شَعَبُ القَرْنَيْنِ"": مَا بَيْنَهُمَا مِنْ بُعْدٍ عِنْدَ الْحَيَوَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21486, 'تَشْعِيثٌ', 'تشعيث', 'مصدر', 'شعث', 'تشعيث', 'تشعث', 'مص. شَعَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْعِيثٌ-تَشْعِيثٌ [ش ع ث] (مص. شَعَّثَ). 1.""تَشْعِيثُ الشَّعْرِ"" : تَفْرِيقُ خُصْلاَتِهِ، خُصَلِهِ. 2.""التَّشْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21487, 'شَعَثٌ', 'شعث', 'مصدر', 'شعث', 'شعث', 'شعث', 'مص. شَعِثَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَعِثٌ-شَعِثٌ [ش ع ث] (صِيغَةُ فَعِل). ""رَأْسٌ شَعِثٌ"" : مُلَبَّدٌ، مُغْبَرٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21488, 'شَعَرٌ', 'شعر', 'مصدر', 'شعر', 'شعر', 'شعر', 'مص. شَعِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَعَرٌ-شَعَرٌ [ش ع ر] (مص. شَعِرَ). ""شَعَرُ البَدَنِ"" : أَي ما يَن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21489, 'شَغَفٌ', 'شغف', 'مصدر', 'شغف', 'شغف', 'شغف', 'مص. شَغِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَغْفٌ-شَغْفٌ [ش غ ف] (مص. شَغَفَ). ""شَغْفُ الْقَلْبِ"" : حِجَابُهُ، غِلاَفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21490, 'شُعُورٌ', 'شعور', 'مصدر', '', 'شعور', 'شعر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21491, 'أَشْعَارٌ', 'أشعار', 'مصدر', '', 'ءشعار', 'شعر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21492, 'شِعْرٌ', 'شعر', 'مصدر', 'شعر', 'شعر', 'شعر', 'مص. شَعَرَ، شَعُرَ', '', '', 'مفرد', 'DnN', '', '', '"أَشْعَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَعَرَ، شَعُرَ). 1.""يَنَظِمُ الشِّعْرَ"" : يَنْظِمُ قَصَائِدَ مَوْزُونَةً مُقَفَّاةً وَفْقَ نِظَامٍ مِنَ البُحُورِ الشِّعْرِيَّةِ، أَوْ حَسَبَ تَفْعِيلَةٍ مَّا مَعَ تَنَوُّعٍ فِي القَوَافِي أَوِ الْتِزَامِ قَافِيَةٍ وَاحِدَةٍ تُعَبِّرُ عَمَّا يَشْعُرُ بِه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21493, 'أَشْعَارٌ', 'أشعار', 'مصدر', '', 'ءشعار', 'شعر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21494, 'شُعُورٌ', 'شعور', 'مصدر', 'شعر', 'شعور', 'شعر', 'مص. شَعَرَ، شَعُرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شُعُورٌ-شُعُورٌ [ش ع ر] (مص. شَعَرَ، شَعُرَ). 1. ""يَكِنُّ لَهُ شُعُورًا رَهِيفاً"" : عَاطِفَةً رَقِيقَةً. 2. ""وَجَدَهُ عَدِيمَ الشُّعُورِ"" : عَدِيمَ الإِحْسَاسِ، قَاسِياً. 3. ""سَقَطَ عَلَى الأَرْضِ فَاقِدَ الشُّعُورِ"": فَاق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21495, 'تَشْعِيلٌ', 'تشعيل', 'مصدر', 'شعل', 'تشعيل', 'تشعل', 'مص. شَعَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْعِيلٌ-تَشْعِيلٌ [ش ع ل] (مص. شَعَّلَ). ""تَشْعِيلُ النِّيرَانِ"" : إِلْهَابُهَا، إِيقَادُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21496, 'شَعْوَذَةٌ', 'شعوذة', 'مصدر', 'شعذ', 'شعوذة', 'شعذة', 'مص. شَعْوَذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَعْوَذَةٌ-شَعْوَذَةٌ [ش ع ذ] (مص. شَعْوَذَ). ""مَا هَذِهِ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21497, 'شَغَبٌ', 'شغب', 'مصدر', 'شغب', 'شغب', 'شغب', 'مص. شَغَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَغَبٌ-شَغَبٌ، شَغْبٌ [ش غ ب] (مص. شَغَبَ). ""أَحْدَثَ شَغَباً"" : فِتْنَةً وَجَلَبَةً، شَرّاً وَخِصَاماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21498, 'شَغْفٌ', 'شغف', 'مصدر', 'شغف', 'شغف', 'شغف', 'مص. شَغَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَغَفٌ-شَغَفٌ [ش غ ف] (مص. شَغِفَ). 1.""شَغَفَ بِهَا شَغَفاً شَدِيداً"" : أُولِعَ بِهَا، تَعَلَّقَ بِهَا تَعَلُّقاً شَدِيداً، أَقْصَى الحُبِّ. ""يُعَلِّمُهُمُ الشَّغَفَ بِحَيَاةِ الحُرِّيَّةِ"". (الأفغاني). 2.""شَغَفُ الْقَلْبِ"" : غِلاَفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21499, 'تَشْغِيلٌ', 'تشغيل', 'مصدر', 'شغل', 'تشغيل', 'تشغل', 'مص. شَغَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْغِيلٌ-تَشْغِيلٌ [ش غ ل] (مص. شَغَّلَ). 1.""قَرَّرَ تَشْغِيلَهُ فِي الْمَعْمَلِ"" : اِسْتِخْدَامَهُ فِيهِ. 2."" تَشْغِيلُ الآلاَتِ"" : إِدَارَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21500, 'شُغْلٌ', 'شغل', 'مصدر', 'شغل', 'شغل', 'شغل', 'مص. شَغَلَ', '', '', 'مفرد', 'DnN', '', '', '"أَشْغالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَغَلَ). 1.""يَبْحَثُ عَنْ شُغْلٍ"" : عَنْ عَمَلٍ. ""يَهْتَمُّ بِأَشْغَالِهِ"". 2.""يُحِبُّ الأَشْغَالَ الْيَدَوِيَّةَ"" : أَيِ الأَعْمَالَ الْيَدَوِيَّةَ عَكْسَ الأَعْمَالِ الفِكْرِيَّةِ. 3.""الدَّرْسُ هُوَ شُغْلُهُ الشَّاغِلُ"" : هُوَ مَا يَمْلأُ بِهِ وَقْتَهُ وَفَرََاغَهُ، أَيْ لاَ فَرَاغَ لَدَيْهِ، عَمَلُهُ الدَّائِمُ الْمُسْتَمِرُّ. ""فِي شُغْلٍ شَاغِلٍ"" ""فِي شُغْلٍ شَاغِلٍ عَمَّا حَوْلَهُ"". 4.""وِزَارَةُ الشُّغْلِ"" : أَي الوِزَارَةُ الْمُهْتَمَّةُ بِالْعَمَلِ وَمَا يَتَعَلَّقُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21501, 'أَشْغالٌ', 'أشغال', 'مصدر', '', 'ءشغال', 'شغل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21502, 'شَفٌّ', 'شف', 'مصدر', 'شفف', 'شف', 'شف', 'مص. شَفَّ', '', '', 'مفرد', 'DnN', '', '', '"شُفُوفٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَفَّ). ""لَبِسَتْ ثَوْباً شَفّاً"" : رَقِيقاً يُظْهِرُ مَا تَحْتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21503, 'شُفُوفٌ', 'شفوف', 'مصدر', '', 'شفوف', 'شفف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21504, 'تَشْفِيعٌ', 'تشفيع', 'مصدر', 'شفع', 'تشفيع', 'تشفع', 'مص. شَفَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْفِيعٌ-تَشْفِيعٌ [ش ف ع] (مص. شَفَعَ). ""طَلَبَ مِنْهُ التَّشْفِيعَ عِنْدَ رَئِيسِهِ"" : التَّوَسُّطُ عِنْدَ رَئِيسِهِ لِقَضَاءِ حَاجَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21505, 'شَفَاعَةٌ', 'شفاعة', 'مصدر', 'شفع', 'شفاعة', 'شفعة', 'مص. شَفَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَفَاعَةٌ-شَفَاعَةٌ [ش ف ع] (مص. شَفَعَ). ""يَرْجُو شَفَاعَتَهُ"" : وَسَاطَتَهُ، كَلاَمُ الشَّفِيعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21506, 'شَفْعٌ', 'شفع', 'مصدر', 'شفع', 'شفع', 'شفع', 'مص. شَفَعَ', '', '', 'مفرد', 'DnN', '', '', '"أَشْفَاعٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَفَعَ). ""شَفْعاً"": زَوْجاً، عَكْسُ الْوَتْرِ. ""الشَّفْعُ وَالوَتْرُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21507, 'أَشْفَاعٌ', 'أشفاع', 'مصدر', '', 'ءشفاع', 'شفع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21508, 'شَفَقٌ', 'شفق', 'مصدر', 'شفق', 'شفق', 'شفق', 'مص. شَفِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَفَقٌ-شَفَقٌ [ش ف ق] (مص. شَفِقَ). 1.""لاَحَ الشَّفَقُ فِي الأُفُقِ"" : الْحُمْرَةُ الْمُتَبَقِّيَةُ مِنْ ضَوْءِ الشَّمْسِ مِنَ الغُرُوبِ إِلَى قُبَيْلِ الْعِشَاءِ. ""وَتَوَارَتِ الشَّمْسُ وَرَاءَ الشَّفَقِ"". 2.""ثَوْبٌ شَفَقٌ"" : ضَعِيفُ النَّسْجِ أَوْ مَصْبُوغٌ بِحُمْرَةٍ.َ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21509, 'شِفَاءٌ', 'شفاء', 'مصدر', 'شفي', 'شفاء', 'شف', 'مص. شَفَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"شِفَاءٌ-شِفَاءٌ [ش ف ي] (مص. شَفَى). 1. ""تَمَنَّى لَهُ شِفَاءً عَاجِلاً"" : بُرْءاً وَعَافِيَةً. 2. ""بِالشِّفَاءِ"" : أَيْ بِالعَافِيَةِ. 3. ""مَرَضٌ لاَ شِفَاءَ لَهُ"" : لاَ عِلاَجَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21510, 'شَفَفٌ', 'شفف', 'مصدر', 'شفف', 'شفف', 'شف', 'مص. شَفَّ، يَشِفُّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَفَفٌ-شَفَفٌ [ش ف ف] (مص. شَفَّ، يَشِفُّ). 1.""شَفَفُ الجِسْمِ"" : رِقَّتُهُ، نُحُولَتُهُ. 2.""شَفَفُ الْحَالِ"" : رِقَّتُهُ، خِفَّتُهُ. 3.""شَفَفُ الشَّيْءِ"" : يَسِيرُهُ، قَلِيلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21511, 'شَقٌّ', 'شق', 'مصدر', 'شقق', 'شق', 'شق', 'مص. شَقَّ', '', '', 'مفرد', 'DnN', '', '', '"شُقُـوقٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَقَّ). 1.""ظَهَرَ شَقٌّ فِي وَسَطِ الحَائِطِ"" : صَدْعٌ، خَرْقٌ، فَتْحَةٌ. ""تَرَكَ الزِّلْزَالُ شُقُوقاً فِي جُدْرَانِ العِمَارَاتِ"". 2.""أَخَذَ شَقّاً وَتَرَكَ الشَّقَّ الثَّانِي لِزَمِيلِهِ"" : نِصْفَ الشَّيْءِ، النِّصْفَ مِنْ كُلِّ شَيْءٍ. ""شَقُّ الْخُبْزِ"". 3.""الشَّقُّ الْخَيْشُومِيُّ"" : إِحْدَى الفَتَحَاتِ الَّتِي عَلَى جَانِبَيِ الرَّأْسِ وَتُفْتَحُ فِي الْجَيْبِ الخَيْشُومِيِّ. 4.""عَمَلِيَّةُ الشَّقِّ الْقَيْصَرِيِّ"" : اِسْتِخْرَاجُ الْجَنِينِ مِنْ بَطْنِ الأُمِّ بِشَقِّهِ عِنْدَمَا تَعْسُرُ الْوِلاَدَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21512, 'شُقُوقٌ', 'شقوق', 'مصدر', '', 'شقوق', 'شقق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21513, 'مَشَقَّةٌ', 'مشقة', 'مصدر', 'شقق', 'مشقة', 'مشقة', 'مص. شَقَّ', '', '', 'مفرد', 'DnN', '', '', '"مَشَاقُّ:مَشَقَّاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَقَّ). ""يُعَانِي مِن مَشَقَّةَ العَمَلِ"" : أَيِ التَّعَب، الْمِحْنَة، العَنَاء."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21514, 'مَشَاقُّ', 'مشاق', 'مصدر', '', 'مشاق', 'مشق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21515, 'مَشَقَّاتٌ', 'مشقات', 'مصدر', '', 'مشقات', 'مشقت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21516, 'شُقْرَةٌ', 'شقرة', 'مصدر', 'شقر', 'شقرة', 'شقرة', 'مص. شَقَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شُقْرَةٌ-شُقْرَةٌ [ش ق ر] (مص. شَقَرَ). ""عَرَفَهَا مِنْ شُقْرَتِهَا"": مَنْ كَانَتْ بَشَرَةُ جِسْمِهَا تَمِيلُ إِلَى البَيَاضِ وَتَتَخَلَّلُهَا حُمْرَةٌ صَافِيَةٌ، لَوْنُ الشَّعْرِ عِنْدَمَا يَمِيلُ إِلَى صُفْرَةٍ ذَهَبِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21517, 'شَقْشَقَةٌ', 'شقشقة', 'مصدر', 'شقشق', 'شقشقة', 'شقشقة', 'مص. شَقْشَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَقْشَقَةٌ-شَقْشَقَةٌ [ش ق ش ق] (مص. شَقْشَقَ). ""شَقْشَقَةُ اللِّسَانِ"" : كَلاَمٌ لاَ طَائِلَ تَحْتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21518, 'شَقَاءٌ', 'شقاء', 'مصدر', 'شقي', 'شقاء', 'شق', 'مص. شَقِيَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"شَقَاءٌ-شَقَاءٌ [ش ق ي] (مص. شَقِيَ). ""يَعِيشُ فِي شَقَاءٍ"" : فِي بُؤْسٍ، فِي عُسْرٍ، فِي عَنَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21519, 'شَكْلٌ', 'شكل', 'مصدر', 'شكل', 'شكل', 'شكل', 'مص. شَكَلَ', '', '', 'مفرد', 'DnN', '', '', '"أَشْكَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَكَلَ). 1.""كَانَ شَكْلُهُ مُخِيفاً"" : هَيْئَتُهُ، صُورَتُهُ، مَنْظَرُهُ. ""شَكْلُهُ جَمِيلٌ"". 2.""أَشْكَالٌ هَنْدَسِيَّةٌ"" : هَيْئَاتُ الأَجْسَامِ كَالدَّائِرَةِ وَالْمُثَلَّثِ وَالْمُرَبَّعِ وَالْمُسْتَطِيلِ. 3. ""اِضْبِطْ شَكْلَ النَّصِّ "": أَيْ ضَعْ عَلَيْهِ الحَرَكَاتِ الإِعْرَابِيَّةَ اللازِمَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21520, 'شَقَاوَةٌ', 'شقاوة', 'مصدر', 'شقي', 'شقاوة', 'شقة', 'مص. شَقَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَقَاوَةٌ-شَقَاوَةٌ [ش ق ي] (مص. شَقَى). ""غَارِقٌ فِي شَقَاوَةٍ"": فِي بُؤْسٍ، فِي شَقَاءٍ، فِي عُسْرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21521, 'شَكٌّ', 'شك', 'مصدر', 'شكك', 'شك', 'شك', 'مص. شَكَّ', '', '', 'مفرد', 'DnN', '', '', '"شُكُوكٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَكَّ). 1.""وَضَعَهُ مَوْضِعَ شَكٍّ"" : مَوْضِعَ الْتِبَاسٍ وَارْتِيَابٍ، نَقِيضَ اليَقِينِ. ""لَمْ أَجِدْ مَا أَصْنَعُ... وَخَالَجَتْنِي رِيَبٌ وَشُكُوكٌ"". (توفيق الحكيم) ""لاَ شَكَّ فِي ذَلِكَ"" ""مِنْ دُونِ شَكٍّ"" ""لاَ سَبِيلَ إِلَى الشَّكِّ فِيهِ"" ""لاَ يَتَطَرَّقُ إِلَيْهِ الشَّكُّ"". 2. ""أَفْعَالُ الشَّكِّ وَالْيَقِينِ""(نح) : مِنْ بَيْنِهَا ظَنَّ وَحَسِبَ وَعَلِمَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21522, 'شُكُوكٌ', 'شكوك', 'مصدر', '', 'شكوك', 'شكك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21523, 'شَكْوٌ', 'شكو', 'مصدر', 'شكو', 'شكو', 'شك', 'مص. شَكَا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَكْوٌ-شَكْوٌ [ش ك و] (مص. شَكَا). 1.""بِهِ شَكْوٌ"" : مَرَضٌ. 2. ""بَلَغَنِي شَكْوُهُ"" : أَيْ مَا يُوجِعُهُ. شَكَا وَشَكَتْ ثُمَّ ارْعَوَى بَعْدُ وَارْعَوَتْ*وَلَلصَّبْرُ إِنْ لَمْ يَنْفَعِ الشَّكْوُ أَجْمَلُ (الشنفرى)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21524, 'شَكْوَى', 'شكوى', 'مصدر', 'شكو', 'شكوى', 'شك', 'مص. شَكَا', '', '', 'مفرد', 'Dy', '', '', '"شَكَاوَى"', 'ممنوع من الصرف', 'R0', '', '', '', '', '', '', '"(مص. شَكَا). 1.""قَدَّمَ بِهِ شَكْوَى"" : قَدَّمَ بِهِ دَعْوَى، شِكَايَةٌ، مَا يُشْتَكَى مِنْهُ. 2.""شَكْوَاهُ تُوجِعُنِي"" : أَلَمُهُ، مُصَابُهُ. ""لَمْ يَجِدْ آذَاناً صَاغِيَةً لِشَكْوَاهُ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21525, 'شَكَاوَى', 'شكاوى', 'مصدر', '', 'شكاوى', 'شك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21526, 'شُكْرٌ', 'شكر', 'مصدر', 'شكر', 'شكر', 'شكر', 'مص. شَكَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شُكْرٌ-شُكْرٌ [ش ك ر] (مص. شَكَرَ). 1. ""شُكْراً لَكَ"" : الْعِرْفَانُ لَكَ لِنِعَمِكَ وَفَضْلِكَ، الاعْتِرَافُ وَالامْتِنَانُ بِمَا قَدَّمْتَ. ""شُكْراً جَزِيلاً عَلَى عَطَائِكَ"" ""شَكَرَهُ أَجْزَلَ شُكْرٍ"". 2.""الشُّكْرُ مِنَ اللَّهِ"" : الرِّضَا وَالثَّوَابُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21527, 'تَشْكِيكٌ', 'تشكيك', 'مصدر', 'شكك', 'تشكيك', 'تشكك', 'مص. شَكَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْكِيكٌ-تَشْكِيكٌ [ش ك ك] (مص. شَكَّكَ). ""التَّشْكِيكُ فيِ أَقْوَالِهِ"" : الشَّكُّ وَالارْتِيَابُ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21528, 'تَشْكِيلٌ', 'تشكيل', 'مصدر', 'شكل', 'تشكيل', 'تشكل', 'مص. شَكَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَشْكِيلٌ-تَشْكِيلٌ [ش ك ل] (مص. شَكَّلَ). 1.""تَشْكِيلُ الْمَنْظَرِ"": إِلْبَاسُهُ صُورَةً. 2.""تَشْكِيلُ الكَلِمَةِ"" : ضَبْطُ حُرُوفِهَا بِالحَرَكَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21529, 'تَشْمِيسٌ', 'تشميس', 'مصدر', 'شمس', 'تشميس', 'تشمس', 'مص. شَمَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْمِيسٌ-تَشْمِيسٌ [ش م س] (مص. شَمَّسَ). ""تَشْمِيسُ الفَوَاكِهِ"": عَرْضُهَا لِلشَّمْسِ، بَسْطُهَا لِتَجِفَّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21530, 'أَشْكَالٌ', 'أشكال', 'مصدر', '', 'ءشكال', 'شكل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21531, 'شَلَلٌ', 'شلل', 'مصدر', 'شلل', 'شلل', 'شل', 'مص. شَلَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَلَلٌ-شَلَلٌ [ش ل ل] (مص. شَلَّ). ""أُصِيبَ بِشَلَلٍ"" : أَيْ لَمْ تَعُدْ أَعْضَاؤُهُ تَقْوَى عَلَى الحَرَكَةِ، تَوَقُّفُ الأَعْضَاءِ عَنِ الحَرَكَةِ. ""الشَّلَلُ الْكُلِّيُّ"" ""الشَّلَلُ الجُزْئِيُّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21532, 'تَشْلِيحٌ', 'تشليح', 'مصدر', 'شلح', 'تشليح', 'تشلح', 'مص. شَلَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْلِيحٌ-تَشْلِيحٌ [ش ل ح] (مص. شَلَّحَ). ""تَشْلِيحُ الوَلِيدِ"" : تَعْرِيَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21533, 'شَلْوَبَةٌ', 'شلوبة', 'مصدر', 'شلوب', 'شلوبة', 'شلبة', 'مص. شَلْوَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَلْوَبَةٌ-شَلْوَبَةٌ [ش ل و ب] (مص. شَلْوَبَ). ""فَنُّ الشَّلْوَبَةِ"" : فَنُّ قَذْفِ الأَشْيَاءِ مُتَتَالِيَةً وَإِعَادَةِ قَذْفِهَا بِمُجَرَّدِ الْتِقَاطِهَا."', '');
