INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21535, 'شَمَمٌ', 'شمم', 'مصدر', 'شمم', 'شمم', 'شم', 'مص. شَمَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَمَمٌ-شَمَمٌ [ش م م] (مص. شَمَّ). 1.""فِي شَمَمِ الْجَبَلِ"" : فِي قِمَّتِهِ، ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21536, 'شَمَاتَةٌ', 'شماتة', 'مصدر', 'شمت', 'شماتة', 'شمتة', 'مص. شَمِتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَمَاتَةٌ-شَمَاتَةٌ [ش م ت] (مص. شَمِتَ). 1. ""الشَّمَاتَةُ بِالنَّاسِ"" : أَيِ الْفَرَحُ وَالاغْتِبَاطُ بِبَلِيَّةِ الآخَرِينَ أَوْ بِالأَعْدَاءِ. 2.""شَمَاتَةُ النَّاسِ"" : أَنْ تَتْرُكَ النَّاسَ يَشْمَتُونَ بِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21537, 'شمُوُخٌ', 'شموخ', 'مصدر', 'شمخ', 'شموخ', 'شمخ', 'مص. شَمخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شمُوُخٌ-شمُوُخٌ [ش م خ] (مص. شَمخَ). ""أَظْهَرَ شُمُوخاً"" : إِبَاءً وَأَنَفَةً، اِعْتِزَازاً وَتَكَبُّراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21538, 'تَشْمِيرٌ', 'تشمير', 'مصدر', 'شمر', 'تشمير', 'تشمر', 'مص. شَمَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْمِيرٌ-تَشْمِيرٌ [ش م ر] (مص. شَمَّرَ). 1.""تَشْمِيرُ ثَوْبٍ"" : رَفْعُهُ عَنِ السَّاعِدَيْنِ أَوِ السَّاقَيْنِ. 2.""التَّشْمِيرُ لِلْأَمْرِ"" : التَّهَيُّؤُ لَهُ. 3.""التَّشْمِيرُ عَنْ سَاعِدِ الجِدِّ"" : العَمَلُ بِجِدٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21539, 'تَشْنِيفٌ', 'تشنيف', 'مصدر', 'شنف', 'تشنيف', 'تشنف', 'مص. شَنَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْنِيفٌ-تَشْنِيفٌ [ش ن ف] (مص. شَنَّفَ). ""تَشْنِيفُ الأَسْمَاعِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21540, 'تَشْمِيعٌ', 'تشميع', 'مصدر', 'شمع', 'تشميع', 'تشمع', 'مص. شَمَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْمِيعٌ-تَشْمِيعٌ [ش م ع] (مص. شَمَّعَ). 1.""تَشْمِيعُ رِسَالَةٍ"": طَلْيُهَا بِالشَّمْعِ الْمُذَابِ لِخَتْمِهَا. 2.""تَشْمِيعُ البَابِ"" : صَبُّ الشَّمْعِ عَلَيْهِ."', '');
