INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21546, 'شَنَبٌ', 'شنب', 'مصدر', 'شنب', 'شنب', 'شنب', 'مص. شَنِبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَنَبٌ-شَنَبٌ [ش ن ب] (مص. شَنِبَ). 1.""شَنَبُ الأَسْنَانِ"": صَفَاؤُهَا"', '');
