INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21549, 'مَشَاهِدُ', 'مشاهد', 'مصدر', '', 'مشاهد', 'مشهد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21550, 'شَنْقٌ', 'شنق', 'مصدر', 'شنق', 'شنق', 'شنق', 'مص. شَنَقَ ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَنْقٌ-شَنْقٌ [ش ن ق] (مص. شَنَقَ ). ""تَمَّ شَنْقُ الْمَحْكُومِ عَلَيْهِ بِالإِعْدَامِ ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21551, 'شَهْوَةٌ', 'شهوة', 'مصدر', 'شهو', 'شهوة', 'شهة', 'مص. شَهَا، شَهِيَ', '', '', 'مفرد', 'DnN', '', '', '"أَشْهِيَةٌ:شَهَوَاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَهَا، شَهِيَ). 1.""بِهِ شَهْوَةٌ لِلِقَاءِ الأَحْبَابِ"" : الرَّغْبَةُ الشَّدِيدَةُ لِلِقَائِهِمْ. ""بِهِم شَهْوَةٌ إِلَى طَعَامِ أُمِّهِ"". 2.""شَهْوَةُ الْمَلَذَّاتِ"": مَا يُشْتَهَى مِنَ الْمَلَذَّاتِ الْمَادِّيَّةِ. آل عمران آية 14 زُيِّنَ للنَّاسِ حُبُّ الشَّهَوَاتِ مِنَ النِّسَاءِ وَالبَنِينَ وَالقَنَاطِيرِ الْمُقَنْطَرَةِ مِنَ الذَّهَبِ وَالفِضَّةِ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21552, 'أَشْهِيَةٌ', 'أشهية', 'مصدر', '', 'ءشهية', 'شهة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21553, 'شَهَوَاتٌ', 'شهوات', 'مصدر', '', 'شهوات', 'شهت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21554, 'شُهْبَةٌ', 'شهبة', 'مصدر', 'شهب', 'شهبة', 'شهبة', 'مص. شَهِبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شُهْبَةٌ-شُهْبَةٌ [ش هـ ب] (مص. شَهِبَ). ""غَزَتِ الشُّهْبَةُ شَعْرَهُ"" : بَيَاضٌ امْتَزَجَ بِسَوَادِ شَعْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21555, 'تَشْهِيدٌ', 'تشهيد', 'مصدر', 'شهد', 'تشهيد', 'تشهد', 'مص. شَهَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْهِيدٌ-تَشْهِيدٌ [ش هـ د] (مص. شَهَّدَ). ""تَشْهِيدُ الْمُسْلِمِ"": قوله: ""أَشْهَدُ أَنْ لاَ إِلَهَ إَلاَّ اللهُ وَأَشْهَدُ أَنَّ مُحَمَّداً رَسُولُ اللهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21556, 'شَهَادَةٌ', 'شهادة', 'مصدر', 'شهد', 'شهادة', 'شهدة', 'مص. شَهِدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. شَهِدَ). 1.""أَدَّى الشَّهَادَةَ أَمَامَ الْمَحْكَمَةِ"" : الإِخْبَار بِمَا رَأَى، وَالإِقْرَار بِمَا عَلِمَ عَنْ يَقِينٍ وَبِلاَ نُقْصَانٍ أَوْ زِيَادَةٍ. ""كَانَتْ شَهَادَة الشُّهُودِ مُطَابِقَةً لِلوَاقِعِ"". 2.""أَدْلَى بِشَهَادَتِهِ الْمَدْرَسِيَّةِ"" : وَثِيقَةٌ مَدْرَسِيَّةٌ تُثْبِتُ نَجَاحَهُ فِي مَرْحَلَةٍ مِنْ مَرَاحِلِ التَّعْلِيمِ : ""الشَّهَادَةُ الابْتِدَائِيَّةُ"" ""الشَّهَادَةُ الثَّانَوِيَّةُ"" ""شَهَادَةُ البَكَالُورِيَا"" ""الشَّهَادَةُ الْجَامِعِيَّةُ"". 3.""شَهَادَةُ حُسْنِ السُّلُوكِ"" : اِعْتِرَافٌ بِحُسْنِ التَّصَرُّفِ وَالْمَسْلَكِ. 4."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21557, 'شُهُودٌ', 'شهود', 'مصدر', 'شهد', 'شهود', 'شهد', 'مص. شَهِدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شُهُودٌ-شُهُودٌ [ش هـ د] (مص. شَهِدَ). ""كَانَ شُهُودُهُ مُطَابِقاً للحَقِيقَةِ"" : مُعَايَنَتُهُ أَوْ مَا أَدَّاهُ مِنْ شَهَادَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21558, 'مَشْهَدٌ', 'مشهد', 'مصدر', 'شهد', 'مشهد', 'مشهد', 'مص. شَهِدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَشَاهِدُ"', '', 'R', '', '', '', '', '', '', '"(مص. شَهِدَ). 1.""جَلَسَ يتَأَمَّلُ الْمَشْهَدَ"" : مَنْظَرٌ مِنْ مَنَاظِرِ الطَّبِيعَةِ أَوْ حَالَةٍ مَّا. ""مَشْهَدٌ عَامٌّ"" ""مَشْهَدٌ مُؤَثِّرٌ"" ""الرِّوَايَةُ مَشْهَدٌ حَيٌّ مِنْ مَشَاهِدِ الْحَيَاةِ"". 2. ""شَهِدَ الْمَشَاهِدَ كُلَّهَا"" : أَيْ حَضَرَ كُلَّ الغَزَوَاتِ مَعَ الرَّسُولِ. 3.""مَشْهَدٌ مِنَ الْمَسْرَحِيَّةِ"" : مَنْظَرٌ وَاحِدٌ تَسْتَمِرُّ فِيهِ الْحَرَكَةُ وَالحِوَارُ مِنْ أَوَّلِهِ إِلَى آخِرِهِ. ""مَشْهَدٌ سِينِمَائِيٌّ"" ""مَشْهَدٌ غِنَائِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21559, 'تَشْوِيقٌ', 'تشويق', 'مصدر', 'شوق', 'تشويق', 'تشق', 'مص. شَوَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْوِيقٌ-تَشْوِيقٌ [ش و ق] (مص. شَوَّقَ). ""أَحْدَثَ فيِ نَفْسِهِ تَشْوِيقاً لِزِيَارَةِ البِلاَدِ"" : أَحْدَثَ فِي نَفْسِهِ رَغْبَةً وَشَوْقاً..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21560, 'تَشْهِيرٌ', 'تشهير', 'مصدر', 'شهر', 'تشهير', 'تشهر', 'مص. شَهَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْهِيرٌ-تَشْهِيرٌ [ش هـ ر] (مص. شَهَّرَ). 1.""أَرَادَ التَّشْهِيرَ بِهِ"": فَضْحَهُ وَإِظْهَارَ مَسَاوِئِهِ. 2.""تَشْهِيرُ الْمُسَدَّسِ نَحْوَ خَصْمٍ"": تَصْوِيبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21561, 'شَهْرٌ', 'شهر', 'مصدر', 'شهر', 'شهر', 'شهر', 'مص. شَهَرَ', '', '', 'مفرد', 'DnN', '', '', '"أَشْهُرٌ:شُهُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. شَهَرَ). 1.""يُرَاقِبُ الشَّهْرَ"" : أَيِ الْهِلاَلَ"".البقرة آية 185 فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ . ( قرآن). أ. الشُّهُورُ القَمَرِيَّةُ الَّتِي يَتِمُّ فِيهَا حِسَابُ الاثْنَيْ عَشَرَ جُزْءاً فِي السَّنَةِ حَسَبَ دَوْرَةِ القَمَرِ حَوْلَ الأَرْضِ وَهِيَ : مُحَرَّمٌ، صَفَرٌ، رَبِيعُ الأَوَّل، رَبِيعُ الثَّانِي، جُمَادَى الأُولَى، جُمَادَى الآخِرَة، رَجَبٌ، شَعْبَانُ، رَمَضَانُ، شَوَّالُ، ذُو القِعْدَةِ، ذُو الْحِجَّةِ. ب. الشُّهُورُ الشَّمْسِيَّةُ يَتِمُّ فِيهَا حِسَابَ الاِثْنَيْ ع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21562, 'أَشْهُرٌ', 'أشهر', 'مصدر', '', 'ءشهر', 'شهر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21563, 'شَهِيقٌ', 'شهيق', 'مصدر', 'شهق', 'شهيق', 'شهق', 'مص. شَهِقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَهِيقٌ-شَهِيقٌ [ ش هـ ق] (مص. شَهِقَ). 1.""يُسْمَعُ شَهِيقُهَا مِنْ بَعِيدٍ"" : تَرَدُّدُ بُكَائِهَا فِي صَدْرِهَا أَوْ نَفْسِهَا. 2.""الشَّهِيقُ وَالزَّفِيرُ"" : عَمَلِيَّةُ إِدْخَالِ النَّفْسِ إِلَى الرِّئَتَيْنِ، عَكْسُ الزَّفِيرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21564, 'شَهْمٌ', 'شهم', 'مصدر', 'شهم', 'شهم', 'شهم', 'مص. شَهَمَ', '', '', 'مفرد', 'DnN', '', '', '"شِهَامٌ:شُهُومٌ"', '', 'R', '', '', '', '', '', '', '"شَهْمٌ-شَهْمٌ [ش هـ م]. ج: شِهَامٌ، شُهُومٌ . (مص. شَهَمَ). 1.""وَلَدٌ شَهْمٌ"" : ذَكِيٌّ. 2.""قَائِدٌ شَهْمٌ"" : سَدِيدُ الرَّأْيِ، صَبُورٌ عَلَى القِيَامِ بِمَا حُمِّلَ. 3.""فَرَسٌ شَهْمٌ"" : قَوِيٌّ سَرِيعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21565, 'شِهَامٌ', 'شهام', 'مصدر', '', 'شهام', 'شهم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21566, 'شُهُومٌ', 'شهوم', 'مصدر', '', 'شهوم', 'شهم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21567, 'شَهَامَةٌ', 'شهامة', 'مصدر', 'شهم', 'شهامة', 'شهمة', 'مص. شَهُمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَهَامَةٌ-شَهَامَةٌ [ش هـ م] (مص. شَهُمَ). ""شَهامَةُ الرَّجُلِ"" : عِزَّةُ نَفْسِهِ، تَرَفُّعُهُ وَإِقْدَامُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21568, 'تَشْوِيشٌ', 'تشويش', 'مصدر', 'شوش', 'تشويش', 'تشش', 'مص. شَوَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْوِيشٌ-تَشْوِيشٌ [ش و ش] (مص. شَوَّشَ). 1."" لاَ يَتَوَقَّفُ عَنِ التَّشْوِيشِ"" : يَشْغَلُ الحَاضِرِينَ بِحَرَكَاتٍ وَوَشْوَشَاتٍ تَحُولُ دُونَ تَتَبُّعِهِمْ لِمَا يُقَالُ. 2.""يَجِبُ تَشْدِيدُ الحِرَاسَةِ ضِدَّ التَّشْوِيشِ"" : مُراقَبَةُ كُلِّ حَرَكَةٍ مِنْ شَأْنِهَا إِحْدَاثُ ضَوْضَاءٍ أَوْ ضَجِيجٍ. ""التَّشْوِيشُ عَلَى الْإذَاعَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21569, 'شَيْطَنَةٌ', 'شيطنة', 'مصدر', 'شيطن', 'شيطنة', 'شطنة', 'مص. شَيْطَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَيْطَنَةٌ-شَيْطَنَةٌ [ش ي ط ن] (مص. شَيْطَنَ). ""قَامَ بِأَعْمَالِ الشَّيْطَنَةِ"" : بِأَعْمَالِ الشَّغَبِ. ""يَدُورُ الْحَديثُ فِي أَخْبَارِ الصِّحَّةِ وَأَخْبَارِ الأَقَارِبِ وَمَصَائِبِ الوَقْتِ وَشَيْطَنَةِ الأَوْلاَدِ وَالبَنَاتِ"". (محمد برادة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21570, 'تَشْوِيكٌ', 'تشويك', 'مصدر', 'شوك', 'تشويك', 'تشك', 'مص. شَوَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْوِيكٌ-تَشْوِيكٌ [ش و ك] (مص. شَوَّكَ). 1.""تَشْوِيكُ النَّبَاتِ"": خُرُوجُ شَوْكِهِ. 2.""تَشْوِيكُ جِدَارِ الحَقْلِ"" : إِحَاطَتُهُ بِالشَّوْكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21571, 'شَآمَةٌ', 'شآمة', 'مصدر', 'شأم', 'شءءمة', 'شآمة', 'مص. شَؤُمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"شَآمَةٌ-شَآمَةٌ [ش أ م] (مص. شَؤُمَ). ""حَوَّلَ حَيَاتَهُمْ شَآمَةً"" : جَعَلَ حيَاتَهُمْ حَيَاةَ شُؤْمٍ وَنَحْسٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21572, 'تَشْوِيهٌ', 'تشويه', 'مصدر', 'شوه', 'تشويه', 'تشه', 'مص. شَوَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْوِيهٌ-تَشْوِيهٌ [ش و هـ] (مص. شَوَّهَ). 1.""تَشْوِيهُ مَلاَمِحِ الوَجْهِ"" : إِفْسَادُهَا وَتَقْبِيحُهَا. 2.""تَشْوِيهُ الحَقِيقَةِ"" : تَحْرِيفُهَا، تَغْيِيرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21573, 'شَوَهٌ', 'شوه', 'مصدر', 'شوه', 'شوه', 'شه', 'مص. شَوِهَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"شَوَهٌ-شَوَهٌ [ش و هـ] (مص. شَوِهَ). 1.""بِهِ شَوَهٌ"" : قُبْحٌ. 2.""شَوَهُ العُنُقِ"" : طُولُهُ، اِرْتِفَاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21574, 'تَشْيِيبٌ', 'تشييب', 'مصدر', 'شيب', 'تشييب', 'تشب', 'مص. شَيَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْيِيبٌ-تَشْيِيبٌ [ش ي ب] (مص. شَيَّبَ). ""شَيَّبَتْهُ الهُمُومُ تَشْييِباً"" : جَعَلَتْهُ يَشِيبُ شَيْباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21575, 'تَشْيِيتٌ', 'تشييت', 'مصدر', 'شيت', 'تشييت', 'تشت', 'مص. شَيَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْيِيتٌ-تَشْيِيتٌ [ش ي ت] (مص. شَيَّتَ). ""تَشْيِيتُ الأَسْنَانِ بِالشِّيتَةِ"" : دَلْكُهَا وَتَنْظِيفُهَا بِالشِّيتَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21576, 'تَشْيِيخٌ', 'تشييخ', 'مصدر', 'شيخ', 'تشييخ', 'تشخ', 'مص. شَيَّخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْيِيخٌ-تَشْيِيخٌ [ش ي خ] (مص. شَيَّخَ). 1.""تَشْيِيخُ الرَّجُلِ"": دَعْوَتُهُ بِالشَّيْخِ. 2.""تَشْيِيخُ مَنْ هُوَ أَكْبَرُ سِنّاً عَلَى القَبِيلَةِ"" : جَعْلُهُ شَيْخاً عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21577, 'تَشْيِيدٌ', 'تشييد', 'مصدر', 'شيد', 'تشييد', 'تشد', 'مص. شَيَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْيِيدٌ-تَشْيِيدٌ [ش ي د] (مص. شَيَّدَ). ""أَشْرَفَ عَلَى تَشْيِيدِ العِمَارَاتِ الجَدِيدَةِ"" : بِنَائِهَا وَتَعْمِيرِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21578, 'تَشْيِيطٌ', 'تشييط', 'مصدر', 'شيط', 'تشييط', 'تشط', 'مص. شَيَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْيِيطٌ-تَشْيِيطٌ [ش ي ط] (مص. شَيَّطَ). ""تَشْيِيطُ رَأْسِ الخَرُوفِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21579, 'مُصَادَقَةٌ', 'مصادقة', 'مصدر', 'صدق', 'مصادقة', 'مصدقة', 'مص. صَادَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَادَقَةٌ-مُصَادَقَةٌ [ص د ق] (مص. صَادَقَ). ""بَيْنَهُمَا مُصَادَقَةٌ قَدِيمَةٌ"" : إِخْلاَصٌ فِي الصَّدَاقَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21580, 'تَشْيِيعٌ', 'تشييع', 'مصدر', 'شيع', 'تشييع', 'تشع', 'مص. شَيَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَشْيِيعٌ-تَشْيِيعٌ [ش ي ع] (مص. شَيَّعَ). ""تَشْيِيعُ الجِنَازَةِ"" : مُرَافَقَةُ الجِنَازَةِ إِلى مَأْوَاهَا الأَخِير. ""كَانَ مَوْكِبُ التَّشْيِيعِ يَسِيرُ فِي اكْتِئَابٍ وَخُشُوعٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21581, 'صَوْبٌ', 'صوب', 'مصدر', 'صوب', 'صوب', 'صب', 'مص. صَابَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَوْبٌ-صَوْبٌ [ص و ب] (مص. صَابَ). 1.""قَذَفَ الْكُرَةَ صَوْبَهُ"" : جِهَتَهُ. 2.""اِتَّجَهَ صَوْبَ هَدَفِهِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21582, 'صَوْتٌ', 'صوت', 'مصدر', 'صوت', 'صوت', 'صت', 'مص. صَاتَ', '', '', 'مفرد', 'DnN', '', '', '"أَصْوَاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَاتَ). 1.""سَمِعَ صَوْتاً"" : كُلُّ رَنَّةٍ أَوْ أَثَرٍ يَحْدُثُ عَنِ اهْتِزَازِ جِسْمٍ مَّا، أَوْ تَمَوُّجَاتٍ نَاشِئَةٍ عَنْهَا، وَكُلُّ مَا يَصْدُرُ عَنِ الْحَنْجَرَةِ، الْقَصَبَةُ الْهَوَائِيَّةُ. ""سَمِعَتْ صَوْتاً يُنَادِيهَا وَيُذَكِّرُهَا بِالْمَاضِي"". (م. ح. هيكل). 2.""هَذَا الْمُغَنِّي يَمْتَازُ بِصَوْتٍ عَذْبٍ"" : بِغِنَاءٍ عَذْبٍ. 3.""اِنْتَشَرَ صَوْتُهُ بَيْنَ النَّاسِ"" : صِيتُهُ، ذِكْرُهُ. 4.""دَوَّى صَوْتُ الرَّعْدِ"" : زَمْجَرَةُ الرَّعْدِ. 5.""أَدْلَى بِصَوْتِهِ فِي الانْتِخَابِ"": بِرَأْيِهِ، بِقَرَارِهِ، بِاخْتِيَارِهِ. 6.""خَضَعَ لِصَوْتِ الضَّمِيرِ"" : لِنِدَاءِ ضَمِيرِهِ. 7.""جَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21583, 'أَصْوَاتٌ', 'أصوات', 'مصدر', '', 'ءصوات', 'صت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21584, 'صِيَاحٌ', 'صياح', 'مصدر', 'صيح', 'صياح', 'صح', 'مص. صَاحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَيَّاحٌ-صَيَّاحٌ [ص ي ح] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""دِيكٌ صَيَّاحٌ"" : كَثِيرُ الصِّيَاحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21585, 'مُصَاحَبَةٌ', 'مصاحبة', 'مصدر', 'صحب', 'مصاحبة', 'مصحبة', 'مص. صَاحَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَاحَبَةٌ-مُصَاحَبَةٌ [ص ح ب] (مص. صَاحَبَ). ""دَامَتِ الْمُصَاحَبَةُ بَيْنَهُمَا زَمَناً طَوِيلاً"" : الْمُلاَزَمَةُ، الْمُعَاشَرَةُ، الْمُرَافَقَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21586, 'صَيْدٌ', 'صيد', 'مصدر', 'صيد', 'صيد', 'صد', 'مص. صَادَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَيْدٌ-صَيْدٌ [ص ي د] (مص. صَادَ). ""خَرَجَ إِلَى الصَّيْدِ"" : الْبَحْثُ عَمَّا يُصَادُ. ""يَتْبَعُهُ أَيْنَمَا ذَهَبَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21587, 'مُصَادَرَةٌ', 'مصادرة', 'مصدر', 'صدر', 'مصادرة', 'مصدرة', 'مص. صَادَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صَادَرَ). 1.""مُصَادَرَةُ أَمْلاَكِ كِبَارِ الإِقْطَاعِيِّينَ"" : الاسْتِيلاَءُ عَلَيْهَا لِفَائِدَةِ الدَّوْلَةِ. 2.""مُصَادَرَةُ حَقِّهِ فِي الكَلاَمِ"" : مَنْعُهُ. 3.""مُصَادَرَةُ جَرِيدَةٍ"" : حَجْزُهَا وَمَنْعُهَا مِنَ الصُّدُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21588, 'مُصَادَفَةٌ', 'مصادفة', 'مصدر', 'صدق', 'مصادفة', 'مصدفة', 'مص. صَادَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صَادَفَ). ""لِقَاءُ مُصَادَفَةٍ"" : لِقَاءٌ مِنْ غَيْرِ مَوْعِدٍ وَلاَ قَصْدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21589, 'صِيَغٌ', 'صيغ', 'مصدر', '', 'صيغ', 'صغ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21590, 'صِدَامٌ', 'صدام', 'مصدر', 'صدم', 'صدام', 'صدم', 'مص. صَادَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صِدَامٌ-صِدَامٌ [ص د م] (مص. صَادَمَ). ""وَقَعَ صِدَامٌ بَيْنَ سَيّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21591, 'مُصَادَمَةٌ', 'مصادمة', 'مصدر', 'صدم', 'مصادمة', 'مصدمة', 'مص. صَادَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَادَمَةٌ-مُصَادَمَةٌ [ص د م] (مص. صَادَمَ). 1.""مُصَادَمَةُ سَيَّارَةٍ لِشَجَرَةٍ"" : مُدَافَعَتُهَا "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21592, 'مَصِيرٌ', 'مصير', 'مصدر', 'صير', 'مصير', 'مصر', 'مص. صَارَ', '', '', 'مفرد', 'DnN', '', '', '"مَصَايِرُ"', '', 'R', '', '', '', '', '', '', '"(مص. صَارَ). 1.""حَدَّدَ مَصِيرَهُ"" : مَآلَهُ.النور آية 42 وَلِلَّهِ مُلْكُ السَّمَاوَاتِ وَالأَرْضِ وَإِلَى اللهِ الْمَصِيرُ (قرآن). 2.""حَقُّ الشَّعْبِ فِي أَنْ يُقَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21593, 'مَصَايِرُ', 'مصاير', 'مصدر', '', 'مصاير', 'مصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21594, 'مُصَارَحَةٌ', 'مصارحة', 'مصدر', 'صرح', 'مصارحة', 'مصرحة', 'مص. صَارَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَارَحَةٌ-مُصَارَحَةٌ [ص ر ح] (مص. صَارَحَ). "" قَرَّرَ مُصَارَحَتَهُ بِكُلِّ خَبَايَا الأُمُورِ"" : مُجَاهَرَتَهُ عَلاَنِيَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21595, 'مُصَارَعَةٌ', 'مصارعة', 'مصدر', 'صرع', 'مصارعة', 'مصرعة', 'مص. صَارَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَارَعَةٌ-مُصَارَعَةٌ [ص ر ع] (مص. صَارَعَ). 1.""بَيْنَهُما مُصارَعَةٌ"" : مُغالَبَةٌ فِي المُطارَحَةِ. 2.""مُصَارَعَةٌ حُرَّةٌ"" : رِيَاضَةٌ بَدَنِيَّةٌ، وَهِيَ نَوْعٌ مِنَ الْمُبَارَزَةِ العَنِيفَةِ مَا بَيْنَ مُصَارِعَيْنِ يُحَاوِلُ كُلٌّ مِنْهُمَا أَنْ ي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21596, 'صَوْغٌ', 'صوغ', 'مصدر', 'صوغ', 'صوغ', 'صغ', 'مص. صَاغَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَوْغٌ-صَوْغٌ [ص و غ] (مص. صَاغَ). 1.""صَوْغُ مَعْدِنٍ"" : سَكْبُهُ. 2.""هَذَا صَوْغُ هَذَا"" : أَيْ عَلَى قَدْرِهِ. 3.""هُوَ صَوْغُ أَخِيهِ"" : أَيْ وُلِدَ مَعَهُ، أَوْ وُلِدَ بَعْدَهُ وَلَمْ يُولَدْ بَيْنَهُمَا أَحَدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21597, 'صِيَاغَةٌ', 'صياغة', 'مصدر', 'صوغ', 'صياغة', 'صغة', 'مص. صَاغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صِيَاغَةٌ-صِيَاغَةٌ [ص و غ] (مص. صَاغَ). 1.""مِهْنَةَ الصِّيَاغَةِ"" : حِرْفَةُ الصَّائِغِ. 2.""يُحْسِنُ صِيَاغَةَ عِبَارَاتِهِ"" : إِنْشَاؤُهَا، بِنَاؤُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21598, 'صِيغَةٌ', 'صيغة', 'مصدر', 'صوغ', 'صيغة', 'صغة', 'مص. صَاغَ', '', '', 'مفرد', 'DnN', '', '', '"صِيَغٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَاغَ). 1.""صِيغَةُ الْعَمَلِ"" : هَيْئَتُهُ وَشَكْلُهُ الَّذِي بُنِيَ عَلَيْهِ. 2.""صِيغَةُ الْكَلِمَةِ"" : صُورَتُهَا، وَزْنُهَا الْحَاصِلُ مِنْ تَرْتِيبِ حُرُوفِهَا وَحَرَكَاتِهَا. 3.""صِيغَةُ الْجُمْلَةِ"" : عِبَارَاتُهَا، تَرْكِيبُهَا. ""صِيَغُ الْكَلاَمِ"" ""صِيغَةٌ لُغَوِيَّةٌ قَدِيمَةٌ"". 4.""هُوَ مِنْ صِيغَةٍ شَرِيفَةٍ"" : مِنْ أَصْلٍ شَرِيفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21599, 'صَيْفٌ', 'صيف', 'مصدر', 'صيف', 'صيف', 'صف', 'مص. صَافَ', '', '', 'مفرد', 'DnN', '', '', '"أَصْيَافٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَافَ). 1.""حَلَّ فَصْلُ الصَّيْفِ"" : أَحَدُ فُصُولِ السَّنَةِ الأَرْبَعَةِ يَبْدَأُ مِنْ 21 حزِيرَان (جوان) إِلَى 21 أَيْلُول (سبتمبر)، تَشْتَدُّ فِيهِ الْحَرَارَةُ. 2.""ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21600, 'أَصْيَافٌ', 'أصياف', 'مصدر', '', 'ءصياف', 'صف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21601, 'مُصَافَحَةٌ', 'مصافحة', 'مصدر', 'صفح', 'مصافحة', 'مصفحة', 'مص. صَافَحَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَافَحَةٌ-مُصَافَحَةٌ [ص ف ح] (مص. صَافَحَ ). ""تَمَّتِ الْمُصَافَحَةُ بَيْنَهُمَا"" : التَّسْلِيمُ بِالأَيْدِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21602, 'صَوْلَةٌ', 'صولة', 'مصدر', 'صول', 'صولة', 'صلة', 'مص. صَالَ', '', '', 'مفرد', 'DnN', '', '', '"صَوَلاَتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَالَ). 1.""كَانَتْ لَهُ صَوْلَةٌ فِي الْحَرْبِ"" : سَطْوَةٌ. 2.""يَاصَاحِبَ الصَّوْلَةِ وَالصَّوْلَجَانُ"" : صَاحِبَ السُّلْطَةِ وَالْقُدْرَةِ وَالْمَكَانَةِ الْعَالِيَةِ. ""الاِسْتِبْدَادُ يَرْتَجِفُ مِنْ صَوْلَةِ الْعِلْمِ"". (ع. الكواكبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21603, 'صَوَلاَتٌ', 'صولات', 'مصدر', '', 'صولات', 'صلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21604, 'مُصَالَحَةٌ', 'مصالحة', 'مصدر', 'صلح', 'مصالحة', 'مصلحة', 'مص. صَالَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَالَحَةٌ-مُصَالَحَةٌ [ص ل ح ] (مص. صَالَحَ). ""سَادَ الوِئَامُ بَعْدَ الْمُصَالَحَةِ"" : الْمُسَالَـمَةُ، الْمُصَافَاةُ وَإِزَالَةُ كُلِّ أَسْبَابِ الخِصَامِ . ""مُصَالَحَةٌ وَطَنِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21605, 'صَوْمٌ', 'صوم', 'مصدر', 'صوم', 'صوم', 'صم', 'مص. صَامَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَوْمٌ-صَوْمٌ [ص و م] (مص. صَامَ). ""شَهْرُ رَمَضَانَ شَهْرُ الصَّوْمِ"" : شَهْرُ الامْتِنَاعِ عَنْ شَهْوَتَيِ البَطْنِ والفَرْجِ مِنْ طُلُوعِ الْفَجْرِ إِلَى غُرُوبِ الشَّمْسِ. ""لِيَكُنْ صَوْمُكَ مُبَارَكاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21606, 'صِيَامٌ', 'صيام', 'مصدر', 'صوم', 'صيام', 'صم', 'مص. صَامَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صِيَامٌ-صِيَامٌ [ص و م] (مص. صَامَ). ""أَقْبَلَ شَهْرُ الصِّيَامِ وَالْغُفْرَانِ"" : شَهْرُ الإِمْسَاكِ عَنِ شَهْوتَيِ البَطْنِ وَالفَرْجِ مِنْ طُلُوعِ الْفَجْرِ إِلَى غُرُوبِ الشَّمْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21607, 'صَوْنٌ', 'صون', 'مصدر', 'صون', 'صون', 'صن', 'مص. صَانَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَوْنٌ-صَوْنٌ [ص و ن] (مص. صَانَ). ""يُحَافِظُ عَلَى صَوْنِ حُقُوقِهِ"": عَلَى حِفْظِهَا وَوِقَايَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21608, 'صِيَانَةٌ', 'صيانة', 'مصدر', 'صون', 'صيانة', 'صنة', 'مص. صَانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صِيَانَةٌ-صِيَانَةٌ [ص و ن] (مص. صَانَ). ""صِيَانَةُ الْكُتُبِ"" : حِفْظُهَا، وِقَايَتُهَا. ""صِيَانَةُ آلاَتِ الْمَعْمَلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21609, 'مُصَاهَرَةٌ', 'مصاهرة', 'مصدر', 'صهر', 'مصاهرة', 'مصهرة', 'مص. صَاهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَاهَرَةٌ-مُصَاهَرَةٌ [ص هـ ر] (مص. صَاهَرَ). ""بَيْن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21610, 'مُصَاوَلَةٌ', 'مصاولة', 'مصدر', 'صول', 'مصاولة', 'مصلة', 'مص. صَاوَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُصَاوَلَةٌ-مُصَاوَلَةٌ [ص و ل] . (مص. صَاوَلَ). ""قَرَّرَ مُصَاوَلَتَهُ"": مُغَالَبَتَهُ، مُنَافَسَتَهُ. ""اِتَّخَذْتُ مَا يَنْبَغِي مِنْ عُدَّةٍ لِمُقَاوَمَةِ الأَهْوَالِ وَمُصَاوَلَةِ الأَحْدَاثِ"". (إسحق الحسينـي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21611, 'صَبٌّ', 'صب', 'مصدر', 'صبب', 'صب', 'صب', 'مص. صَبَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَبٌّ-صَبٌّ [ص ب ب] (مص. صَبَّ). 1.""شابٌّ صَبٌّ"" : مشتاقٌ، عاشِقٌ. 2.""ماءٌ صَبٌّ"" مَصْبوبٌ. 3.""صَبُّ التَّمَاثِيلِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21612, 'صَبْوَةٌ', 'صبوة', 'مصدر', 'صبو', 'صبوة', 'صبة', 'مص. صَبَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَبْوَةٌ-صَبْوَةٌ [ص ب و] (مص. صَبَا). 1.""لاَ يَزَالُ فِي صَبْوَتِهِ"" : فِي لَهْوِ فُتُوَّتِهِ. 2.""ه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21613, 'تَصْبِيحٌ', 'تصبيح', 'مصدر', 'صبح', 'تصبيح', 'تصبح', 'مص. صَبَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْبِيحٌ-تَصْبِيحٌ [ص ب ح] (مص. صَبَّحَ). 1.""جَاءَ لِلتَّصْبِيحِ عَلَيْهِ"" : إِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21614, 'صَبَاحَةٌ', 'صباحة', 'مصدر', 'صبح', 'صباحة', 'صبحة', 'مص. صَبُحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَبَاحَةٌ-صَبَاحَةٌ [ص ب ح] (مص. صَبُحَ). ""صَبَاحَةُ الوَجْهِ"" : جَمَالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21615, 'صُبْحَةٌ', 'صبحة', 'مصدر', 'صبح', 'صبحة', 'صبحة', 'مص. صَبِحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صُبْحَةٌ-صُبْحَةٌ [ص ب ح] (مص. صَبِحَ). 1.""يَقْضِي صُبْحَةَ يَوْمِ الأَحَدِ فِي سَرِيرِهِ"" : نَوْمُ الفَتْرَةِ الصَّبَاحِيَّةِ. 2.""صُبْحَةُ اليَوْمِ"": مَا يُتَعَلَّلُ بِهِ قَبْلَ الطَّعَامِ صَبَاحاً. 3.""اِكْتَسَتِ الصُّبْحَةُ فَضَاءَ الفَجْرِ"" : لَوْنٌ أَسْوَدُ يَمِيلُ إِلَى الْحُمْرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21616, 'تَصْبِيرٌ', 'تصبير', 'مصدر', 'صبر', 'تصبير', 'تصبر', 'مص. صَبَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْبِيرٌ-تَصْبِيرٌ [ص ب ر] (مص. صَبَّرَ). 1.""سَعَى إِلَى تَصْبِيرِهِ"": دَفْعُهُ إِلىَ التَّجَلُّدِ وَالتَّحَمُّلِ والْمَزِيدِ مِنَ الصَّبْرِ. 2.""تَصْبِيرُ جُثَّةٍ"" : وَضْعُ الصِّبْرِ فِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21617, 'صَبْرٌ', 'صبر', 'مصدر', 'صبر', 'صبر', 'صبر', 'مص. صَبَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَبْرٌ-صَبْرٌ [ص ب ر] (مص. صَبَرَ). 1.""يَتَحَلَّى بِالصَّبْرِ"" : يَتَحَلَّى بِالْجَلَدِ، أَيْ لاَ يُظْهِرُ شَكْوىً مِنْ أَلَمٍ أَوْ بَلْوىً. أَرَاكَ عَصِيَّ الدَّمْعِ شِيمَتُكَ الصَّبْرُ*أَمَا لِلْهَوَى نَهْيٌ عَلَيْكَ وَلاَ أَمْرُ (أبو فراس الحمداني). لِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21618, 'صَبْغٌ', 'صبغ', 'مصدر', 'صبغ', 'صبغ', 'صبغ', 'مص. صَبَغَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَبْغٌ-صَبْغٌ [ص ب غ] (مص. صَبَغَ). ""صَبْغ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21619, 'صَحْصَحَةٌ', 'صحصحة', 'مصدر', 'صحصح', 'صحصحة', 'صحصحة', 'مص. صَحْصَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَحْصَحَةٌ-صَحْصَحَةٌ [ص ح ص ح] (مص. صَحْصَحَ). ""صَحْصَحَةُ الأَمْرِ"" : ظُهُورُهُ، وُضُوحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21620, 'تَصْبِينٌ', 'تصبين', 'مصدر', 'صبن', 'تصبين', 'تصبن', 'مص. صَبَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْبِينٌ-تَصْبِينٌ [ص ب ن] (مص. صَبَّنَ). ""تَرَكَ مَلاَبِسَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21621, 'صَبِيبٌ', 'صبيب', 'مصدر', 'صبب', 'صبيب', 'صبب', 'مص. صَبَّ يَصِبُّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَبِيبٌ-صَبِيبٌ، ةٌ [ص ب ب] (مص. صَبَّ يَصِبُّ). 1.""وَضَعَ صَبِيبَةً ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21622, 'صَبِيبَةٌ', 'صبيبة', 'مصدر', 'صبب', 'صبيبة', 'صببة', 'مص. صَبَّ يَصِبُّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَبِيبٌ-صَبِيبٌ، ةٌ [ص ب ب] (مص. صَبَّ يَصِبُّ). 1.""وَضَعَ صَبِيبَةً ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21623, 'صَبَابَةٌ', 'صبابة', 'مصدر', 'صبب', 'صبابة', 'صببة', 'مص. صَبَّ، يَصَبُّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَبَابَةٌ-صَبَابَةٌ [ص ب ب] (مص. صَبَّ، يَصَبُّ). ""يَحْتَرِقُ قَلْبُهُ صَبَابَةً"" : حَرَارَةُ الشَّوْق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21624, 'صِحَّةٌ', 'صحة', 'مصدر', 'صحح', 'صحة', 'صحة', 'مص. صَحَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صِحَّةٌ-صِحَّةٌ [ص ح ح] (مص. صَحَّ). 1.""يَتَمَتَّعُ بِصِحَّةٍ جَيِّدَةٍ"" : بِبِنْيَةٍ جِسْمِيَّةٍ سَلِيمَةٍ، لاَ اعْتِلاَلَ فِي جِسْمِهِ. 2.""التَّدْخِينُ مُضِرٌّ بِالصِّحَّةِ"" : مُضِرٌّ بِسَلاَمَةِ جِسْمِ الإِنْسَانِ. ""اِهْتَمَّ بِصِحَّتِكَ"". 3.""أَنْشَأَتْ وِزَارَةُ الصِّحَّةِ مُسْتَشْفَيَاتٍ جَدِيدَةً"" : الوِزَارَةُ الْمَسْؤُولَةُ عَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21625, 'صَحْوٌ', 'صحو', 'مصدر', 'صحو', 'صحو', 'صح', 'مص. صَحَا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَحْوٌ-صَحْوٌ [ص ح و] (مص. صَحَا). 1.""خَرَجُوا لِلنُّزْهَةِ فِي يَوْمٍ صَحْوٍ"" : صَافٍ لاَ غَيْمَ فِيهِ. ""عَمَلٌ يَطِيبُ فِي الصَّحْوِ كَمَا يَطِيبُ فِي الدَّجْنِ"". (الجاحظ). 2.""يَحْتَاجُ إِلَى فَتْرَةِ صَحْوٍ لِيَعِيَ مَا حَوْلَهُ"" : يَحْتَاجُ إِلَى فَتْرَةِ وُضُوحٍ وَجَلاَءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21626, 'صُحْبَةٌ', 'صحبة', 'مصدر', 'صحب', 'صحبة', 'صحبة', 'مص. صَحِبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صُحْبَةٌ-صُحْبَةٌ [ص ح ب] (مص. صَحِبَ). ""جَاءَ بِصُحْبَتِهِ"": بِرُفْقَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21627, 'تَصْحِيحٌ', 'تصحيح', 'مصدر', 'صحح', 'تصحيح', 'تصحح', 'مص. صَحَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْحِيحٌ-تَصْحِيحٌ [ص ح ح] (مص. صَحَّحَ). 1.""قُدِّمَتْ أَوْراقُ الامْتِحَانِ للتَّصْحِيحِ"" : لِمُرَاجَعَتِهَا وَالوُقُوفِ عَلَى أَخْطَائِهَا. 2.""أَعَادَ تَصْحِيحَ فَاتُورَةِ الحِسَابِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21628, 'صُحْرَةٌ', 'صحرة', 'مصدر', 'صحر', 'صحرة', 'صحرة', 'مص. صَحِرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صُحْرَةٌ-صُحْرَةٌ [ص ح ر] (مص. صَحِرَ). ""تَنَاثَرَتِ الصُّحْرَةُ"": غُبْرَةٌ فِي حُمْرَةٍ خَفِيفَةٍ إِلى بَيَاضٍ قَلِيلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21629, 'صُدُورٌ', 'صدور', 'مصدر', '', 'صدور', 'صدر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21630, 'تَصْحِيفٌ', 'تصحيف', 'مصدر', 'صحف', 'تصحيف', 'تصحف', 'مص. صَحَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْحِيفٌ-تَصْحِيفٌ [ص ح ف] (مص. صَحَّفَ). ""قَرَأَ النَّصَّ دُونَ تَصْحِيفٍ"" : دُونَ تَحْرِيفٍ وَلاَ أَخْطَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21631, 'صَحْنٌ', 'صحن', 'مصدر', 'صحن', 'صحن', 'صحن', 'مص. صَحَنَ', '', '', 'مفرد', 'DnN', '', '', '"صُحُونٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَحَنَ). 1.""تَنَاوَلَ صَحْناً مِنْ عَدَسٍ"" : طَبَقـاً، إِنَـاءً. ""قَدَّمُوا لِلضُّيُوفِ صُحُوناً بِمُخْتَلِفِ الْمَأْكُولاَتِ"". 2.""صَحْنُ الدَّارِ"" : مِسَاحَتُهَا الوُسْطَى. 3.""صَحْنُ الأُذُنِ"" : دَاخِلُهَا، جَوْفُهَا. 4.""صَحْنُ الْخَدِّ"" : وَاجِهَةُ الْخَدِّ. 5.""صَحْنَا الآلَةِ الْمُوسِيقِيَّةِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21632, 'صُحُونٌ', 'صحون', 'مصدر', '', 'صحون', 'صحن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21633, 'صَخَبٌ', 'صخب', 'مصدر', 'صخب', 'صخب', 'صخب', 'مص. صَخِبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَخَبٌ-صَخَبٌ [ص خ ب] (مص. صَخِبَ). ""أَحْدَثُوا صَخَباً"": ضَجِيجاً نَاتِجاً عَنِ اخْتِلاَطِ الأَصْوَاتِ وَارْتِفَاعِهَا وَجَلَبَتِهَا. ""اِنْدَفَعَ الْجُمْهُورُ يُقَهْقِهُ فِي صَخَبٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21634, 'صَدٌّ', 'صد', 'مصدر', 'صدد', 'صد', 'صد', 'مص. صَدَّ', '', '', 'مفرد', 'DnN', '', '', '"أَصْدَادٌ:صُدُودٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَدَّ). ""مَا هَذَا الصَّدُّ"" : مَا هَذَا الْهِجْرَانُ، الإِعْرَاضُ ؟ .البقرة آية 217وَصَدٌّ عَنْ سَبِيلِ اللَّهِ وَكُفْرٌ بِهِ .(قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21635, 'أَصْدَادٌ', 'أصداد', 'مصدر', '', 'ءصداد', 'صدد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21636, 'صُدُودٌ', 'صدود', 'مصدر', '', 'صدود', 'صدد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21637, 'تَصْدِيرٌ', 'تصدير', 'مصدر', 'صدر', 'تصدير', 'تصدر', 'مص. صَدَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْدِيرٌ-تَصْدِيرٌ [ص د ر] (مص. صَدَّرَ). "" يُشْرِفُ عَلَى تَصْدِيرِ البَضَائِعِ وَالْمَنْتُوجَاتِ"" : تَسْوِيقُهَا إِلى الخَارِجِ بِقَصْدِ التِّجَارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21638, 'صَدْرٌ', 'صدر', 'مصدر', 'صدر', 'صدر', 'صدر', 'مص. صَدَرَ', '', '', 'مفرد', 'DnN', '', '', '"صُدُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَدَرَ). 1.""وَضَعَ يَدَهُ عَلَى صَدْرِهِ"" : مَا دُونَ العُنُقِ إِلَى البَطْنِ. ""وَجَثَا فَوْقَ صُدُورِنَا صَمْتٌ ثَقِيلٌ"". (إميل حبيـبي). 2.""جَلَسَ فِي صَدْرِ البَيْتِ"" : فِي وَسَطِهِ. 3.""فِي صَدْرِ الإِسْلاَمِ"" : فِي أَوَائِلِهِ، في بِدَايَتِهِ. 4.""صَدْرُ البَيْتِ الشِّعْرِيِّ"" : نِصْفُهُ الأَوَّلُ عَكْسُ العَجُزِ. 5.""مَعْرُوفٌ بِرَحَابَةِ الصَّدْرِ"" : بِسَعَةِ النَّفْسِ وَطُولِ الأَنَاةِ. 6.""رَحْبُ الصَّدْرِ"" : حَكِيمٌ. 7.""مُنْشَرِحُ الصَّدْرِ"" : مُنْشَرِحُ النَّفْسِ عَكْس مُنْقَبِضِ الص"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21639, 'صَرَاحَةٌ', 'صراحة', 'مصدر', 'صرح', 'صراحة', 'صرحة', 'مص. صَرُحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَرَاحَةٌ-صَرَاحَةٌ [ص ر ح] (مص. صَرُحَ). ""يَتَحَدَّثُ بِصَرَاحَةٍ"" : بِوُضُوحٍ وَجَلاَءٍ دُونَ اِلْتِوَاءٍ وَلاَ كَذِبٍ. ""لاَ أَحَدَ يَشُكُّ فِي صَرَاحَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21640, 'صُدُورٌ', 'صدور', 'مصدر', 'صدر', 'صدور', 'صدر', 'مص. صَدَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صُدُورٌ-صُدُورٌ [ص د ر] (مص. صَدَرَ). ""صُدُورُ الكِتَابِ"" : ظُهُورُهُ لِيُتَدَاوَلَ بَيْنَ النَّاسِ. ""صُدُورُ جَرِيدَةٍ"" ""صُدُورُ كِتَابٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21641, 'صَدْعٌ', 'صدع', 'مصدر', 'صدع', 'صدع', 'صدع', 'مص. صَدَعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَدْعٌ-صَدْعٌ [ص د ع] (مص. صَدَعَ). ""أُصِيبَ الإِنَاءُ بِصَدْعٍ"" : بِشَقٍّ. ""أَحْدَثَ الز"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21642, 'تَصْدِيقٌ', 'تصديق', 'مصدر', 'صدق', 'تصديق', 'تصدق', 'مص. صَدَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْدِيقٌ-تَصْدِيقٌ [ص د ق] (مص. صَدَّقَ). 1.""تَصْدِيقُ الكَلاَمِ"": اِعْتِبَارُهُ صَحِيحاً مُخْلِصاً لاَ كَذِبَ فِيهِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21643, 'صِدْقٌ', 'صدق', 'مصدر', 'صدق', 'صدق', 'صدق', 'مص. صَدَقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صِدْقٌ-صِدْقٌ [ص د ق] (مص. صَدَقَ). 1.""تَكَلَّمَ بِصِدْقٍ وَإِخْلاَصٍ"" : مُطَابَقَةُ الكَلاَمِ لِلْوَاقِعِ وَالْحَقِيقَةِ بِحَسَبِ اعْتِقَادِ الْمُتَكَلِّمِ. ""لاَ يَتَحَدَّثُ إِلاَّ صِدْقاً"" ""الصِّدْقُ فِي الوُدِّ وَالنُّصْحِ"" ""الصِّدْقُ فِي القَوْلِ و"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21644, 'صَدْمٌ', 'صدم', 'مصدر', 'صدم', 'صدم', 'صدم', 'مص. صَدَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَدْمٌ-صَدْمٌ [ص د م] (مص. صَدَمَ). ""تَعَرَّضَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21645, 'صَدَأٌ', 'صدأ', 'مصدر', 'صدأ', 'صدء', 'صد', 'مص. صَدِئَ', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"صَدَأٌ-صَدَأٌ [ص د أ] (مص. صَدِئَ). ""غَطَّى الصَّدَأُ الإِنَاءَ"" : مَا يَعْلُو الأَوَانِيَ النُّحَاسِيَّةَ وَالْمَعْدِنِيَّةَ مِنْ طَبَقَةٍ هَشَّةٍ يَمِيلُ لَوْنُهَا إِلَى الأَحْمَرِ الْمَفْتُوحِ، أَيْ بِهِ شُقْرَةٌ، يُسَمَّى كِيمَاوِيّاً الأُكْسِيد."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21646, 'صِرٌّ', 'صر', 'مصدر', 'صرر', 'صر', 'صر', 'مص. صَرَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صِرٌّ-صِرٌّ [ص ر ر] (مص. صَرَّ)..""ريحٌ صِرٌّ أو ريحٌ فيها صِرٌّ"" : شَديدَةُ البَرْدِ.آل عمران آية 117 كَمَثَلِ ريحٍ فيها صِرٌّ أَصابَتْ حَرْثَ قَوْمٍ ظَلَمُوا أَنْفُسَهُمْ (قرآن). 2.""صِرُّ الرِّيحِ"" : صَوْتُها الشَّديدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21647, 'صَرِيرٌ', 'صرير', 'مصدر', 'صرر', 'صرير', 'صرر', 'مص. صَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَرِيرٌ-صَرِيرٌ [ص ر ر] (مص. صَرَّ). 1.""أَحْدَثَ البَابُ صَرِيراً"" : صَوْتاً، طَنِيناً. 2.""صَرِيرُ الأُذُنِ"" : طَنِينُهَا. 3.""صَرِيرُ القَلَمِ"" : صَوْتُهُ عِنْدَ الكِتَابَةِ بِهِ. 4.""صَرِيرُ الأَسْنَانِ"" : صَوْتُهَا حِينَ يُحَكُّ بَعْضُهَا عَلَى بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21648, 'تَصْرِيحٌ', 'تصريح', 'مصدر', 'صرح', 'تصريح', 'تصرح', 'مص. صَرَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْرِيحٌ-تَصْرِيحٌ [ص ر ح] (مص. صَرَّحَ). 1.""لَمْ يَكُنْ يَحْمِلُ تَصْرِيحاً بِالْمُرُورِ"" : تَرْخِيصاً، إِجَازَةً. 2.""حَصَلَ التَّاجِرُ عَلَى تَصْرِيحٍ لِجَلْبِ البَضَائِعِ الخَارِجِيَّةِ"" : الإِذْنُ بِاسْتِيرَادِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21649, 'صُعُوبَةٌ', 'صعوبة', 'مصدر', 'صعب', 'صعوبة', 'صعبة', 'مص. صَعُبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صُعُوبَةٌ-صُعُوبَةٌ [ص ع ب] (مص. صَعُبَ). ""وَجَدَ صُعُوبَةً فِي عَمَلِهِ"" : مَشَقَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21650, 'مَصْرَعٌ', 'مصرع', 'مصدر', 'صرع', 'مصرع', 'مصرع', 'مص. صَرَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَصَارِعُ"', '', 'R', '', '', '', '', '', '', '"(مص. صَرَعَ). 1.""حَدَّدُوا مَصْرَعَ القَتِيلِ"" : مَكَانَ صَرْعِهِ. 2.""لَقِيَ مَصْرَعَهُ"": لَقِيَ القَتْلَ وَالاغْتِيَالَ. 3. ""طَعَنَهُ فِي مَصْرَعٍ فَمَاتَ فِي الْحِينِ"": مَكَانُ القَتْلِ مِنَ الجَسَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21651, 'مَصَارِعُ', 'مصارع', 'مصدر', '', 'مصارع', 'مصرع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21652, 'صَرْعٌ', 'صرع', 'مصدر', 'صرع', 'صرع', 'صرع', 'مص. صَرَعَ.', '', '', 'مفرد', 'DnN', '', '', '"صُرُوعٌ:أَصْرُعُ"', '', 'R', '', '', '', '', '', '', '"ج: صُرُوعٌ، أَصْرُعُ. (مص. صَرَعَ). ""أُصِيبَ بِالصَّرْعِ"" : عِلَّةٌ عَصَبِيَّةٌ تُفْقِدُ وَعْيَ الْمَرْءِ وَيُطْرَحُ أَرْضاً مُرْتَعِشاً مُتَشَنِّجاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21653, 'صُرُوعٌ', 'صروع', 'مصدر', '', 'صروع', 'صرع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21654, 'أَصْرُعُ', 'أصرع', 'مصدر', '', 'ءصرع', 'صرع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21655, 'صَرْفٌ', 'صرف', 'مصدر', 'صرف', 'صرف', 'صرف', 'مص. صَرَفَ', '', '', 'مفرد', 'DnN', '', '', '"صُرُوفٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَرَفَ). 1.""صَرْفُ العُمْلَةِ"" : إِبْدَالُهَا وَتَغْيِيرُهَا بِعُمْلَةٍ أَجْنَبِيَّةٍ. 2.""صَرْفُ الْمَالِ"" : إِنْفَاقُهُ. 3.""جَاءَ فِي مَوْعِدِ صَرْفِ الْمُكَافَأَةِ الشَّهْرِيَّةِ"" : فِي مَوْعِدِ تَسَلُّمِهَا. 4.""عِلْمُ الصَّرْفِ"" : عِلْمٌ يَبْحَثُ فِي قَوَاعِدِ صِيَغِ الكَلِمَاتِ وَأَحْوَالِهَا. ""اُمْتُحِنَ فِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21656, 'صُرُوفٌ', 'صروف', 'مصدر', '', 'صروف', 'صرف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21657, 'صَرِيفٌ', 'صريف', 'مصدر', 'صرف', 'صريف', 'صرف', 'مص. صَرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَرِيفٌ-صَرِيفٌ [ص ر ف] (مص. صَرَفَ). 1.""صَرِيفُ البَابِ"" : مَا يُحْدِثُهُ مِنْ صَوْتٍ عِنْدَ تَحَرُّكِهِ. 2.""صَرِيفُ نَابٍ"": صَوْتُهَا إِذَا حُكَّتْ عَلَى غَيْرِهَا. 3.""قُرْطٌ مِنْ صَرِيفٍ"" : مِنْ فِضَّةٍ خَالِصَةٍ. 4.""شَرَابٌ صَرِيفٌ"" : خَالِصٌ لَمْ يُمْزَجْ. 5.""شَرِبَ صَرِيفاً"" : لَبَناً سَاعَةَ حَلْبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21658, 'صَرَامَةٌ', 'صرامة', 'مصدر', 'صرم', 'صرامة', 'صرمة', 'مص. صَرُمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَرَامَةٌ-صَرَامَةٌ [ص ر م] (مص. صَرُمَ). 1.""عَامَلَهُ بِصَرَامَةٍ"" : بِقَسْوَةٍ، بِشِدَّةٍ. 2.""رَجُلُ صَرَامَةٍ"" : الْمُسْتَبِدُّ بِرَأْيِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21659, 'صِغَرٌ', 'صغر', 'مصدر', 'صغر', 'صغر', 'صغر', 'مص. صَغُرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صِغَرٌ-صِغَرٌ [ص غ ر] (مص. صَغُرَ). 1.""يَمْنَعُهُ صِغَرُ سِنِّهِ مِنَ السَّفَرِ"" : أَيْ هُوَ صَغِيرُ السِّنِّ عَكْسُ الكِبَرِ. 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21660, 'صُعُدٌ', 'صعد', 'مصدر', 'صعد', 'صعد', 'صعد', 'مص. صَعِدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صُعُدٌ-صُعُدٌ [ص ع د] (مص. صَعِدَ). 1.""يُشْرِفُ عَلَى الْمَدِينَةِ مِنْ صُعُدٍ"" : مِنْ عَلٍ. 2.""مَضَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21661, 'صُعُودٌ', 'صعود', 'مصدر', 'صعد', 'صعود', 'صعد', 'مص. صَعِدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صُعُودٌ-صُعُودٌ [ص ع د ] (مص. صَعِدَ). 1.""صُعُودُ الْجَبَلِ"" : طُلُوعُهُ، ارْتِقَاؤُهُ، تَسَلُّقُهُ. 2.""بِقَدْرِ مَا يَكُونُ الصُّعُودُ يَكُونُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21662, 'صَاعِقَةٌ', 'صاعقة', 'مصدر', 'صعق', 'صاعقة', 'صعقة', 'مص. صَعَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":صَواعِقُ"', '', 'R', '', '', '', '', '', '', '"(مص. صَعَقَ) 1.""دَوَّتِ الصَّاعِقَةُ"" : اِنْفِجَارٌ نَارِيٌّ فِي الفَضَاءِ يُحْدِثَ رَعْداً مُدَوِّياً فِي اللَّيَالِي الْمُمْطِرَةِ بِفِعْلِ احْتِكَاكِ الْمَجْرَى الكَهْرَبَائِيِّ بَيْنَ السُّحُبِ. ""عَصَفَتْ صَاعِقَةٌ فَقَتَلَتْ عَدَداً مِنَ البَشَرِ وَالْمَاشِيَةِ"". 2.""حَلَّتْ بِهَا الصَّاعِقَةُ"" : الْمَوْتُ، العَذَابُ الْمُه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21663, 'صَواعِقُ', 'صواعق', 'مصدر', '', 'صواعق', 'صعق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21664, 'صَعَقٌ', 'صعق', 'مصدر', 'صعق', 'صعق', 'صعق', 'مص. صَعِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَعَقٌ-صَعَقٌ [ص ع ق] (مص. صَعِقَ). ""اِشْتَدَّ صَعَقُهُ"" : اِشْتَدَّ دَوِيُّ صَوْتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21665, 'صَعْلَكَةٌ', 'صعلكة', 'مصدر', 'صعلك', 'صعلكة', 'صعلكة', 'مص. صَعْلَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَعْلَكَةٌ-صَعْلَكَةٌ [ص ع ل ك] (مص. صَعْلَكَ). ""سارَ فِي دُرُوبِ الصَّعْلَكَةِ"" : دُرُوبِ الفَقْرِ وَالتَّشَرُّدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21666, 'تَصْغِيرٌ', 'تصغير', 'مصدر', 'صغر', 'تصغير', 'تصغر', 'مص. صَغَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْغِيرٌ-تَصْغِيرٌ [ص غ ر] (مص. صَغَّرَ). 1.""يَرْغَبُ فِي تَصْغِيرِ الصُّورَةِ"" : التَّقْلِيص مِنْ حَجْمِهَا بِوَاسِطَةِ آلَةٍ فُوتُوغْرَافِيَّةٍ. 2.""يَنْبَغِي تَصْغِيرُ حَجْمِ الدَّوَائِرِ وَالخَرَائِطِ فِي الدَّفْتَرِ"" : نَقْلُهَا بِحَجْمٍ أَصْغَرَ مِمَّا هِيَ عَلَيْهِ فِي الأَصْلِ. 3.""جَاءَ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21667, 'تصاغير', 'تصاغير', 'مصدر', '', 'تصاغير', 'تصغر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21668, 'صَغَارٌ', 'صغار', 'مصدر', 'صغر', 'صغار', 'صغر', 'مص. صَغُرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَغَارٌ-صَغَارٌ [ص غ ر] (مص. صَغُرَ). ""عَاشَ فِي صَغَارٍ"" : فِي ذُلٍّ، مَهَانَةٍ، هَوَانٍ. الأ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21669, 'صَفِيرٌ', 'صفير', 'مصدر', 'صفر', 'صفير', 'صفر', 'مص. صَفَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَفِيرٌ-صَفِيرٌ [ص ف ر] (مص. صَفَرَ). ""عَلاَ الصَّفِيرُ وَسَطَ القَاعَةِ"" : صَوْتٌ حَادٌّ مُمْتَدٌّ خَالٍ مِنَ الْحُرُوفِ صَادِرٌ مِنَ الشَّفَتَيْنِ. ""قَالَتْ: إِنَّ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21670, 'صَفٌّ', 'صف', 'مصدر', 'صفف', 'صف', 'صف', 'مص. صَفَّ', '', '', 'مفرد', 'DnN', '', '', '"صُفُوفٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَفَّ). 1.""صَفُّ الأَشْجَارِ"" : خَطٌّ مُسْتَقِيمٌ مِنْهَا تَتَخَلَّلُ فَجَوَاتِهِ أَشْجَارٌ. 2.""اِصْطَفَّ التَّلاَمِيذُ صَفّاً"" : وَقَفَ كُلُّ وَاحِدٍ مِنْهُمْ وَرَاءَ الآخَرِ وَكَوَّنُوا خَطّاً مُسْتَقِيماً. 3.""الصَّفُّ الْمَدْرَسِيُّ الرَّابِعُ"" : مَجْمُوعَةٌ مِنَ التَّلاَمِي"', '');
