INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21675, 'صَفْحٌ', 'صفح', 'مصدر', 'صفح', 'صفح', 'صفح', 'مص. صَفَحَ', '', '', 'مفرد', 'DnN', '', '', '"صِفَاحٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَفَحَ). 1.سَأَلَهُ الصَّفْحَ"" : العَفْوَ. 2.""صَفْحُ الإِنْسَانِ"" : جَنْبُهُ. 3.""صَفْحُ الوَجْهِ"" : خَدُّهُ. 4.""صَفْحُ السَّيْفِ"" : عَرْ"', '');
