INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21678, 'تَصْفِيرٌ', 'تصفير', 'مصدر', 'صفر', 'تصفير', 'تصفر', 'مص. صَفَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. صَفَّرَ) 1.""أَثَارَ انْتِبَاهَهُ تَصْفِيرٌ مُنْبَعِثٌ مِنْ خَلْفِ الأَشْجَارِ"" : نَفِيخٌ بِالصَّوْتِ الْمَهْ"', '');
