INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21680, 'صُفْرَةٌ', 'صفرة', 'مصدر', 'صفر', 'صفرة', 'صفرة', 'مص. صَفِرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صُفْرَةٌ-صُفْرَةٌ [ص ف ر] (مص. صَفِرَ). ""لَوْحَةٌ تَسُودُهَا الصُّفْرَةُ"" : اللَّوْنُ الأَصْفَرُ كَالذَّهَبِ أَوِ النُّحَاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21681, 'صَفْعٌ', 'صفع', 'مصدر', 'صفع', 'صفع', 'صفع', 'مص. صَفَعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَفْعٌ-صَفْعٌ [ص ف ع] (مص. صَفَعَ). ""تَعَرَّضَ لِلصَّفْعِ وَاللَّكْمِ"" : الضَّرْبُ عَلَى الخَدِّ بِكَفِّ اليَدِ مَبْسُوطَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21682, 'تَصْفِيفٌ', 'تصفيف', 'مصدر', 'صفف', 'تصفيف', 'تصفف', 'مص. صَفَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْفِيفٌ-تَصْفِيفٌ [ص ف ف] (مص. صَفَّفَ). 1.""تَصْفِيفُ الشَّعْرِ"" : تَمْشِيطُهُ. 2.""زَارَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21683, 'تَصْفِيقٌ', 'تصفيق', 'مصدر', 'صفق', 'تصفيق', 'تصفق', 'مص. صَفَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْفِيقٌ-تَصْفِيقٌ [ص ف ق] (مص. صَفَّقَ). ""اِهْتَزَّتِ القَاعَةُ بِالتَّصْفِيقِ"" : ضَرْبُ الأَكُفِّ بَعْضِهَا بِبَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21684, 'صَفَاقَةٌ', 'صفاقة', 'مصدر', 'صفق', 'صفاقة', 'صفقة', 'مص. صَفُقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَفَاقَةٌ-صَفَاقَةٌ [ص ف ق] (مص. صَفُقَ). ""صَفَاقَةُ وَجْهٍ"" : وَقَاحَتُهُ. ""ضَجِرْتُ مِنْ إِلْحَاحِهِ وَصَفَاقَةِ وَجْهِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21685, 'تَصْفِيَةٌ', 'تصفية', 'مصدر', 'صفو', 'تصفية', 'تصفة', 'مص. صَفَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَصْفِيَةٌ-تَصْفِيَةٌ [ص ف و] (مص. صَفَّى). 1.""قَرَّرَ تَصْفِيَةَ دُيُونِهِ"" : إِنْهَاؤُهَا. 2.""سَيَتَمَكَّنُ قَرِيباً مِنْ تَصْفِيَةِ حِسَابَاتِهِ"" : مِنْ تَسْوِيَتِهَا. 3.""أَرَادَ الرَّجُلُ تَصْفِيَةَ مَا بَقِيَ عِنْدَهُ مِنْ بَضَائِعَ، فَقَرَّرَ تَخْفِيضَ أ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21686, 'تَصْقِيعٌ', 'تصقيع', 'مصدر', 'صقع', 'تصقيع', 'تصقع', 'مص. صَقَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْقِيعٌ-تَصْقِيعٌ [ص ق ع] (مص. صَقَّعَ). ""تَصْقِيعُ الطَّعَامِ"" : تَجْمِيدُهُ بِالثَّلْجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21687, 'صَقِيعٌ', 'صقيع', 'مصدر', 'صقع', 'صقيع', 'صقع', 'مص. صَقَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَقِيعٌ-صَقِيعٌ [ص ق ع] (مص. صَقَعَ). ""تَحَوَّلَ سَطْحُ الْمَاءِ إِلَى صَقِيعٍ"" : الطَّبَقَةُ السَّطْحِيَّةُ مِنَ الْمَاءِ تَتَحَوَّلُ إِلَى جَلِيدٍ بِفِعْلِ شِدَّةِ البُرُودَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21688, 'صَقَعٌ', 'صقع', 'مصدر', 'صقع', 'صقع', 'صقع', 'مص. صَقِعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَقَعٌ-صَقَعٌ [ص ق ع] (مص. صَقِعَ). ""أَصَابَهُ الصَّقَعُ"" : أَذَى الصَّقِيعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21689, 'تَصْلِيحٌ', 'تصليح', 'مصدر', 'صلح', 'تصليح', 'تصلح', 'مص. صَلَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْلِيحٌ-تَصْلِيحٌ [ص ل ح] (مص. صَلَّحَ). 1.""تَصْلِيحُ آلَةٍ"": إِعَادَتُهَا إِلىَ حَالَتِهَا الأُولَى بِإِزَالَةِ عَطَبِهَا. 2.""تَصْلِيحُ الأَخْطَاءِ"": تَقْوِيمُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21690, 'صَكٌّ', 'صك', 'مصدر', 'صكك', 'صك', 'صك', 'مص. صَكَّ', '', '', 'مفرد', 'DnN', '', '', '"صُكُوكٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَكَّ). 1.""حَرَّرَ لَهُ صَكّاً"" : كِتَاباً، وَثِيقَةً بِمَالٍ أَوْ غَيْرِهِ. 2.""دَفْتَرُ الصَّكِّ"" : دَفْتَرُ الشِّيكَاتِ. 3.""صَكُّ الاسْتِلاَمِ"" : وَثِيقَةُ الاسْتِلاَمِ. 4.""صُكُوكٌ بَنْكِيَّةٌ"" : نَمَاذِجُ مَطْبُوعَةٌ عَلَى نَمَطٍ مُعَيَّنٍ يَسْتَعْمِلُهُ الْمُودِعُ فِي أَحَدِ الْمَصَارِف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21691, 'صُكُوكٌ', 'صكوك', 'مصدر', '', 'صكوك', 'صكك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21692, 'صَلِيلٌ', 'صليل', 'مصدر', 'صلل', 'صليل', 'صلل', 'مص. صَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَلِيلٌ-صَلِيلٌ [ص ل ل] (مص. صَلَّ). 1.""وَكُنْتُ لاَ أَسْمَعُ إِلاَّ صَلِيلَ السِّلاَحِ فِي سَاحَةِ الْقِتَالِ"" : قَرْقَعَةُ السِّلاَحِ وَصَوْتُهُ. 2.""صَلِيلُ الْحَدِيدِ"" : الصَّوْتُ الَّذِي يُحْدِثُهُ عِنْدَ وَقْعِ بَعْضِهِ عَلَى بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21693, 'تَصْلِيبٌ', 'تصليب', 'مصدر', 'صلب', 'تصليب', 'تصلب', 'مص. صَلَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْلِيبٌ-تَصْلِيبٌ [ص ل ب] (مص. صَلَّبَ). 1.""التَّصْلِيبُ فِي الصَّلاَةِ عِنْدَ الْمَسِيحِيِّينَ"" : رَسْمُ إِشَارَةِ الصَّلِيبِ. 2.""تَصْلِيبُ مَادَّةٍ"" : تَقْوِيَتُهَا وَجَعْلُهَا صَلْبَةً. 3.""تَصْلِيبُ الرَّجُلِ"" : جَعْلُهُ مَشْدُودَ الرِّجْلَيْنِ مَمْدُودَ اليَدَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21694, 'صَلْبٌ', 'صلب', 'مصدر', 'صلب', 'صلب', 'صلب', 'مص. صَلَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَلْبٌ-صَلْبٌ، ةٌ [ص ل ب] (مص. صَلَبَ). 1.""صَلْبُ الرَّأْيِ"" : شَدِيدُهُ. ""إِيمَانٌ صَلْبٌ"" ""عَقِيدَةٌ صَلْبَةٌ"". 2.""تَأَلَّمُوا لِصَلْبِهِ"" : أَيْ إِيثَاُقُ يَدَيْهِ مَمْدُودَتَيْنِ وَرِجْلَيْهِ مَشْدُودَتَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21695, 'صَلْبَةٌ', 'صلبة', 'مصدر', 'صلب', 'صلبة', 'صلبة', 'مص. صَلَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَلْبٌ-صَلْبٌ، ةٌ [ص ل ب] (مص. صَلَبَ). 1.""صَلْبُ الرَّأْيِ"" : شَدِيدُهُ. ""إِيمَانٌ صَلْبٌ"" ""عَقِيدَةٌ صَلْبَةٌ"". 2.""تَأَلَّمُوا لِصَلْبِهِ"" : أَيْ إِيثَاُقُ يَدَيْهِ مَمْدُودَتَيْنِ وَرِجْلَيْهِ مَشْدُودَتَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21696, 'صَلاَبَةٌ', 'صلابة', 'مصدر', 'صلب', 'صلابة', 'صلبة', 'مص. صَلُبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَلاَبَةٌ-صَلاَبَةٌ [ص ل ب] (مص. صَلُبَ). 1.""وَاجَهَهُ بِصَلاَبَةٍ"" : بِحَزْمٍ وَشِدَّةٍ. ""صَلاَبَةُ الْمَوْقِفِ"". 2.""فِي وَجْهِهِ صَلاَبَةٌ"" : أَيْ صَفَاقَةٌ. 3.""صَلاَبَةُ جِسْمٍ"" : كُلُّ جِسْمٍ يَحْتَفِظُ بِشَكْلِهِ وَحَجْمِهِ وَلاَ يَلِينُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21697, 'صَلْتٌ', 'صلت', 'مصدر', 'صلت', 'صلت', 'صلت', 'مص. صَلَتَ', '', '', 'مفرد', 'DnN', '', '', '"أَصْلاَتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَلَتَ). 1.""صَخْرٌ صَلْتٌ"" : أَمْلَسُ. 2.""جَبِينٌ صَلْتٌ"" : بَارِزٌ، وَاضِحٌ، وَاسِعٌ. 3.""سَيْفٌ صَلْتٌ"" : صَقِيلٌ مَاضٍ. ""سِكِّينٌ صَلْتٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21698, 'أَصْلاَتٌ', 'أصلات', 'مصدر', '', 'ءصلات', 'صلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21699, 'صَلاَحٌ', 'صلاح', 'مصدر', 'صلح', 'صلاح', 'صلح', 'مص. صَلَحَ، صَلُحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَلاَحٌ-صَلاَحٌ [ص ل ح] (مص. صَلَحَ، صَلُحَ). 1.""عُرِفَ بِالصَّلاَحِ"" : بِالاسْتِقَامَةِ وَالسَّلاَمَةِ مِنَ العَيْبِ. """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21700, 'صَلاَحِيَةٌ', 'صلاحية', 'مصدر', 'صلح', 'صلاحية', 'صلحة', 'مص. صَلَحَ، صَلُحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"صَلاَحِيَةٌ-صَلاَحِيَةٌ [ص ل ح] (مص. صَلَحَ، صَلُحَ). ن. صَلاَحِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21701, 'صَلْدٌ', 'صلد', 'مصدر', 'صلد', 'صلد', 'صلد', 'مص. صَلَدَ', '', '', 'مفرد', 'DnN', '', '', '"أَصْلاَدٌ:صِلاَدٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَلَدَ). 1.""حَجَرٌ صَلْدٌ"" : صَلْبٌ. 2.""فِي الْوَادِي حَجَرٌ صَلْدٌ"" : أَمْلَسُ. 3.""أَرْضٌ صَلْدَةٌ"" : لاَ تُنْبِتُ. 4.""جِلْدٌ صَلْدٌ"" : لاَ يُنْبِتُ شَعْراً. 5.""زَنْدٌ صَلْدٌ"" : لاَ يُورِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21702, 'صَلْدَةٌ', 'صلدة', 'مصدر', 'صلد', 'صلدة', 'صلدة', 'مص. صَلَدَ', '', '', 'مفرد', 'DnN', '', '', '"أَصْلاَدٌ:صِلاَدٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَلَدَ). 1.""حَجَرٌ صَلْدٌ"" : صَلْبٌ. 2.""فِي الْوَادِي حَجَرٌ صَلْدٌ"" : أَمْلَسُ. 3.""أَرْضٌ صَلْدَةٌ"" : لاَ تُنْبِتُ. 4.""جِلْدٌ صَلْدٌ"" : لاَ يُنْبِتُ شَعْراً. 5.""زَنْدٌ صَلْدٌ"" : لاَ يُورِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21703, 'أَصْلاَدٌ', 'أصلاد', 'مصدر', '', 'ءصلاد', 'صلد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21704, 'صِلاَدٌ', 'صلاد', 'مصدر', '', 'صلاد', 'صلد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21705, 'صَلْصَلَةٌ', 'صلصلة', 'مصدر', 'صلصل', 'صلصلة', 'صلصلة', 'مص. صَلْصَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَلْصَلَةٌ-صَلْصَلَةٌ [ص ل ص ل] (مص. صَلْصَلَ). 1.""صَلْصَلَةُ الرَّعْدِ"" : دَوِيُّهُ بِوُضُوحٍ. 2.""صَلْصَلَةُ الأَجْرَاسِ"": تَرْجِيعُ دَقَّاتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21706, 'صَلَعٌ', 'صلع', 'مصدر', 'صلع', 'صلع', 'صلع', 'مص. صَلِعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَلَعٌ-صَلَعٌ [ص ل ع] (مص. صَلِعَ). ""صَلَعُ الرَّأْسِ"" : زَوَالُ الشَّعْرِ عَنْ مُقَدَّمِهِ أَوْ وَسَطِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21707, 'صَلَفٌ', 'صلف', 'مصدر', 'صلف', 'صلف', 'صلف', 'مص. صَلِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَلَفٌ-صَلَفٌ [ص ل ف] (مص. صَلِفَ). ""الشَّرَفُ آفَتُهُ الصَّلَفُ"" : التَّكَبُّرُ وَالْعَجْرَفَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21708, 'صَلاَةٌ', 'صلاة', 'مصدر', 'صلو', 'صلاة', 'صلة', 'مص. صَلَّى', '', '', 'مفرد', 'DnN', '', '', '"صَلَوَاتٌ"', '', 'Rw', '', '', '', '', '', '', '"(مص. صَلَّى). 1.""مِنْ أَرْكَانِ الإِسْلاَمِ الْخَمْسَةِ: الصَّلاَةُ"" : السُّجُودُ وَالرُّكُوعُ وَالتَّعَبُّدُ خُشُوعاً وَدُعَاءً، التَّسْبِيحُ، الابْتِهَالُ إِلَى اللَّهِ، وَفِي اليَوْمِ خَمْسُ صَلَوَاتٍ. أ. ""صَلاَةُ الصُّبْحِ"" : وَهِيَ الَّتِي تَقَعُ بَيْنَ الفَجْرِ وَطُلُوعِ الشَّمْسِ. ب. ""صَلاَةُ الظُّهْرِ"" : هِيَ الَّتِي تَقَعُ بَعْدَ الزَّوَالِ بِنِصْفِ سَاعَةٍ. ج. ""صَلاَةُ العَصْرِ"" : هِيَ الَّتِي تَقَعُ بَيْنَ الظُّهْرِ وَالْمَغْرِبِ. د.""صَلاَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21709, 'صَلَوَاتٌ', 'صلوات', 'مصدر', '', 'صلوات', 'صلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21710, 'صَمَمٌ', 'صمم', 'مصدر', 'صمم', 'صمم', 'صم', 'مص. صَمَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَمَمٌ-صَمَمٌ [ص م م] (مص. صَمَّ). ""أُصِيبَ بِالصَّمَمِ"" : أُصِيبَ بِفُقْدَانِ حَاسَّةِ السَّمْعِ. أَنَا الَّذِي نَظَرَ الأَعْمَى إِلَى أَدَبِي*وَأَسْمَعَتْ كَلِمَاتِي مَنْ بِهِ صَمَمٌ"" (المتنبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21711, 'صَمْتٌ', 'صمت', 'مصدر', 'صمت', 'صمت', 'صمت', 'مص. صَمَتَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَمْتٌ-صَمْتٌ [ص م ت] (مص. صَمَتَ). 1.""صَمْتٌ رَهِيبٌ فِي الْقَاعَةِ"" : سُكُوتٌ مُطْبِقٌ. ""يَلُفُّهَا صَمْتٌ مَهِينٌ كَأَنَّهُ صَمْتُ الْمَوْتِ"". 2.""قَطَعَ عَلَيْهِ حَبْلَ الصَّمْتِ"" : قَطَعَ هُدُوءهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21712, 'صَمْدٌ', 'صمد', 'مصدر', 'صمد', 'صمد', 'صمد', 'مص. صَمَدَ', '', '', 'مفرد', 'DnN', '', '', '"أَصْمَادٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَمَدَ). 1.""صَمَدَ صَمْداً"" : ثَبَتَ ثَبَاتاً. ""صَمْداً صَمْداً حَتَّى يَتَجَلَّى لَكُمْ عَمُودُ الْحَقِّ"". 2.""نَادَاهُ مِنْ صَمْدٍ"" : مِنْ مَكَانٍ مُرْتَفِعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21713, 'أَصْمَادٌ', 'أصماد', 'مصدر', '', 'ءصماد', 'صمد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21714, 'تَصْمِيمٌ', 'تصميم', 'مصدر', 'صمم', 'تصميم', 'تصمم', 'مص. صَمَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَصَامِيمُ"', '', 'R', '', '', '', '', '', '', '"(مص. صَمَّمَ). 1.""وَضَعَ تَصْمِيماً لِمَوْضُوعِهِ"" : تَخْطِيطاً لِعَنَاصِرِهِ وَلِأَجْزَائِهِ. ""صَمَّمَ فَأَحْسَنَ التَّصْمِيمَ"".(طه حسين). 2.""أَنْجَزَ الْمُهَنْدِسُ تَصَامِيمَ لِبِنَاءِ عِمَارَةٍ حَدِيثَةٍ"" : رُسُوماً تَخْطِيطِيَّةً تُحَد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21715, 'تَصَامِيمُ', 'تصاميم', 'مصدر', '', 'تصاميم', 'تصمم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21716, 'عُضْوِيَّةٌ', 'عضوية', 'مصدر', 'عضو', 'عضوية', 'عضة', 'مص صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عُضْوِيَّةٌ-عُضْوِيَّةٌ [ع ض و] (مص صِنَاعِيٌّ). ""قُبِلَتْ عُضْوِيَّتُهُ فِي الْجَمْعِيَّةِ"" : أُعْطِيَتْ لَهُ صِفَةُ العُضْوِ فِي الْجَمْعِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21717, 'مِدْفَعِيَّةٌ', 'مدفعية', 'مصدر', 'دفع', 'مدفعية', 'مدفعة', 'مص. صِنَاعِـيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مِدْفَعِيَّةٌ-مِدْفَعِيَّةٌ [د ف ع] (مص. صِنَاعِـيٌّ). ""مِدْفَعِـيَّـةُ الْمَيْدَانِ"":مَجْمُوعَةُ الْمَدَافِعِ الْمُخْتَصَّةِ بِالْمَيْدَانِ. ""الْمِدْفَعِيَّةُ الْمُضَادَّةُ لِلطَّائِرَاتِ"" ""المِدْفَعِيَّةُ الْمُضَادَّةُ لِلصَّوَارِيخِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21718, 'أَرِستقراطِيَّةٌ', 'أرستقراطية', 'مصدر', '', 'ءرستقراطية', 'رستقرطة', 'مص. صِنَاعِيٌّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '": (مص. صِنَاعِيٌّ). ""يَنْتَمِي إلَى الطَّبَقَةِ الأرِسْتُقْرَطِيَّةِ"" : طَبَقَةٌ عُلْيَا فِي الْمُجْتَمَعِ، يَمْلِكُ أَفْرَادُهَا الشَّرَفَ وَالجَاهَ والسُّلْطَةَ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21719, 'مَدْيُونِيَّةٌ', 'مديونية', 'مصدر', 'دين', 'مديونية', 'مدنة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَدْيُونِيَّةٌ-مَدْيُونِيَّةٌ [د ي ن] (مص. صِنَاعِيٌّ). ""الْمَدْيُونِيَّةُ الْخَارِجِيَّةُ تُرْهِقُ كَاهِلَ شُعُوبِ العَالَمِ الثَّالِثِ"" : مَجْمُوعُ الدُّيُونِ الْمُتَرَتِّبَةِ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21720, 'أُوتُوقْرَاطِيَّةٌ', 'أوتوقراطية', 'مصدر', '', 'ءوتوقراطية', 'تقرطة', 'مص. صِنَاعِيٌّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"أُوتُوقْرَاطِيَّةٌ-أُوتُوقْرَاطِيَّةٌ (مص. صِنَاعِيٌّ). ""السُّلْطَةُ الأتُوقْرَاطِيَّةُ"": السُّلْطَةُ الْمُسْتَبِدَّةُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21721, 'جَاسُوسِيَّةٌ', 'جاسوسية', 'مصدر', 'جسس', 'جاسوسية', 'جسسة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"جَاسُوسِيَّةٌ-جَاسُوسِيَّةٌ [ج س س] (مص. صِنَاعِيٌّ).: مِهْنَةُ الجَوَاسِيسِ، أَيْ ت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21722, 'جُمْهُورِيَّةٌ', 'جمهورية', 'مصدر', 'جمهر', 'جمهورية', 'جمهرة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', '', '"يات"', '', '', '', '', '', '', '', '', '"(مص. صِنَاعِيٌّ).: نِظَامُ حُكْمٍ يُنْتَخَبُ فِيهِ رَئِيسُهُ لِمُدَّةٍ مُعَيَّنَةٍ كَمَا يُحَدِّدُهَا دُسْتُورُ البِلاَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21723, 'مَحْدُودِيَّةٌ', 'محدودية', 'مصدر', 'حدد', 'محدودية', 'محددة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَحْدُودِيَّةٌ-مَحْدُودِيَّةٌ [ح د د] (مص. صِنَاعِيٌّ). ""آرَاؤُهُ تُعَبِّرُ عَنْ مَحْدُودِيَّةِ تَفْكِيرِهِ"" : أَيْ آرَاؤُهُ ذَاتُ تَفْكِيرٍ ضَيِّقٍ، قَاصِرَة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21724, 'مَحْسُوبِيَّةٌ', 'محسوبية', 'مصدر', 'حسب', 'محسوبية', 'محسبة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَحْسُوبِيَّةٌ-مَحْسُوبِيَّةٌ [ح س ب] (مص. صِنَاعِيٌّ). ""يَنْبَغِي وَضْعُ حَدٍّ لِتَفَشِّي الْمَحْسُوبِيَّة فِي الإِدَارَةِ"" : اِعْتِبارُ القَرَابَةِ العَائِلِيَّةِ أَوِ السِّيَاسِيَّةِ فِي إِسْنَادِ الوَظَائِفِ أَوْ فِي التَّرْقِيَاتِ وَالتَّسْيِيرِ. ""الْمَحْسُوبِيَّةُ مِنْ عَنَاصِرِ الفَسَادِ تَجْعَلُ الْحَسَبَ وَالنَّسَبَ فِي الْمَقَامِ الأَوَّلِ وَنَيْلَ الْحُظْوَةِ وَالتَّرْقِيَةِ بَدَلاً مِنَ العَمَلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21725, 'مَحَلِّيَّةٌ', 'محلية', 'مصدر', 'حلل', 'محلية', 'محلة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَحَلِّيَّةٌ-مَحَلِّيَّةٌ [ح ل ل] (مص. صِنَاعِيٌّ). ""تَجَاوَزَ مَنْطِقَ الْمَحَلِّيَّةِ إِلَى العَالَمِيَّةِ"" : مَنْطِقَ الإقْلِيمِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21726, 'خَاصِّيَّةٌ', 'خاصية', 'مصدر', 'خصص', 'خاصية', 'خصة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"خَاصِّيَّةٌ-خَاصِّيَّةٌ [خ ص ص] (مص. صِنَاعِيٌّ). ""خَاصِّيَّةُ الت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21727, 'دِبْلُومَاسِيَّةٌ', 'دبلوماسية', 'مصدر', '', 'دبلوماسية', 'دبلمسة', 'مص. صِنَاعِيٌّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دِبْلُومَاسِيَّةٌ-دِبْلُومَاسِيَّةٌ (مص. صِنَاعِيٌّ). : صِفَةٌ تَخُصُّ التَّمْثِيلَ السِّيَاسِيَّ لِلْبِلاَدِ وَتَصْرِيفَ شُؤُونِهَا الخَارِجِيَّةِ لَدَى الدُّوَلِ الأجْنَبِيَّةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21728, 'مُدِيرِيَّةٌ', 'مديرية', 'مصدر', 'دور', 'مديرية', 'مدرة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِنَاعِيٌّ): مُؤَسَّسَةٌ إِدَارِيَّةٌ حُكُومِيَّةٌ خَاضِعَةٌ لِسُلْطَةِ مُدِيرٍ عَامٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21729, 'شَفَافِيَّةٌ', 'شفافية', 'مصدر', 'شفف', 'شفافية', 'شففة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَفَافِيَّةٌ-شَفَافِيَّةٌ [ش ف ف] (مص. صِنَاعِيٌّ). ""تَحَدَّثَ بِشَفَافِيَّةٍ"": بِوُضُوحٍ تَامٍّ. ""تَمَيَّزَتْ مَشَارِيعُهُ وَخُطَطُهُ بِالشَّفَافِيَّةِ"" ""مَرْحَلَةُ الشَّفَافِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21730, 'رَاديكَالِيَّةٌ', 'راديكالية', 'مصدر', '', 'راديكالية', 'ردكلة', 'مص. صِنَاعِيٌّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَاديكَالِيَّةٌ-رَاديكَالِيَّةٌ (فل) (مص. صِنَاعِيٌّ). : مَذْهَبٌ فَلْسَفِيٌّ وسِيَاسيٌّ قَائِمٌ على اللِّيبْرالِيَّةِ الاقْتِصادِيَّةِ والْمُبَادَرَةِ الفَرْدِيَّةِ وَالعَقْلانِيَّةِ، يَدْعُو إِلَى الإِصْلاحِ السِّيَاسِيِّ الجِذْرِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21731, 'رَأْسُمَاليَّةٌ', 'رأسمالية', 'مصدر', 'رأس،مول', 'رءسمالية', 'رسملة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَأْسُمَاليَّةٌ-رَأْسُمَاليَّةٌ [ر أ س، م و ل] (مص. صِنَاعِيٌّ). : نِظَامٌ اِقْتِصَادِيٌّ يَقُومُ عَلَى اس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21732, 'مَرْدُودِيَّةٌ', 'مردودية', 'مصدر', 'ردد', 'مردودية', 'مرددة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَرْدُودِيَّةٌ-مَرْدُودِيَّةٌ [ر د د] (مص. صِنَاعِيٌّ). ""مَرْدُودِيَّةُ العَمَلِ"": عَطَاؤُهُ، دَخْلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21733, 'مَرْكَزِيَّةٌ', 'مركزية', 'مصدر', 'ركز', 'مركزية', 'مركزة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَرْكَزِيَّةٌ-مَرْكَزِيَّةٌ [ر ك ز] (مص. صِنَاعِيٌّ). 1.""تَعْتَمِدُ الدَّوْلَةُ سِيَاسَةَ الْمَرْكَزِيَّةِ"" : اِعْتِمَادُ تَمَرْكُزِ السُّلَطِ فِي مَرْكَزٍ وَاحِدٍ وَإِخْضَاعُهَا لَهُ. 2.""اِعْتِمَادُ اللاَّمَرْكَزِيَّةِ فِي نِظَامِ الحُكْمِ"" : اِعْتِمَادُ نَقْلِ الكَثِيرِ مِنَ السُّلَطِ إِلَى الجِهَاتِ التَّابِعَةِ لِلْمَرْكَزِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21734, 'رَهْبانِيَّةٌ', 'رهبانية', 'مصدر', 'رهب', 'رهبانية', 'رهبنة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَهْبانِيَّةٌ-رَهْبانِيَّةٌ [ر هـ ب] (مص. صِنَاعِيٌّ). ""دَخَلَ في الرَّهْبانِيَّةِ"" : الزُّهْدُ في الدُّنْيا والاِنْقِطاعُ عَنْ ملَذَّاتِها وَعَنِ الزَّواجِ. ""لاَ رَهْبانِيَّةَ في الإِسْلامِ"" الحديد آية 27 وَرَهْبانِيَّةً ابْتَدَعوها ما كَتَبْناها عَلَيْهِمْ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21735, 'سَلْبِيَّةٌ', 'سلبية', 'مصدر', 'سلب', 'سلبية', 'سلبة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِنَاعِيٌّ). : نِظامٌ فلْسَفِيٌّ قائِمٌ على رَفْضِ كُلِّ حَقيقَةٍ أَوْ مُعْتَقَدٍ، كَما يَعْنِي التَّرَدُّدَ والإِضْرابَ عَنِ العَمَلِ وَعَدَمَ التَّعاوُنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21736, 'شَخْصِيَّةٌ', 'شخصية', 'مصدر', 'شخص', 'شخصية', 'شخصة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَخْصِيَّةٌ-شَخْصِيَّةٌ [ش خ ص] (مص. صِنَاعِيٌّ). الْمُخْتَصُّ بِالشَّخْصِ، وَالْمُمَيِّزُ لِخَصَائِصِهِ الجِسْمِيَّةِ وَالفِعْلِيَّةِ وَالعَاطِفِيَّةِ. 1.""زَارَتِ الْمَعْهَدَ شَخْصِيَّةٌ بَارِزَةٌ"" : إنْسَانٌ لَهُ وُجُودٌ فِعْلِيٌّ فِي مَجَالٍ مَّا، يَحْتَلُّ مَنْصِباً عَالِياً وَيَتَمَتَّعُ بِنُفُوذٍ. 2.""اِسْتَقْبَلَ الوَزِيرُ الوَفْدَ بِصِفَتِهِ الشَّخْصِيَّةِ"" : أَيْ لَيْسَ بِصِفَتِهِ الحُكُومِيَّةِ الرَّسْمِيَّةِ. 3.""قَانُونُ الأَحْوَالِ الشَّخْصِيَّةِ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21737, 'مَشْرُوعِيَّةٌ', 'مشروعية', 'مصدر', 'شرع', 'مشروعية', 'مشرعة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَشْرُوعِيَّةٌ-مَشْرُوعِيَّةٌ [ش ر ع] (مص. صِنَاعِيٌّ). ""تَسْتَمِدُّ السُّلْطَةُ مَشْرُوعِيَّتَهَا مِنَ الشَّعْبِ"" : أَهْلِيَّتَهَا، مِصْدَاقِيَّتَهَا حَسَبَ مَا يُسَوِّغُهُ القَانُونُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21738, 'شَاعِريَّةٌ', 'شاعرية', 'مصدر', 'شعر', 'شاعرية', 'شعرة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَاعِريَّةٌ-شَاعِريَّةٌ [ش ع ر] (مص. صِنَاعِيٌّ). ""يَتَمتَّعُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21739, 'إقْطَاعِيَّةٌ', 'إقطاعية', 'مصدر', 'قطع', 'ءقطاعية', 'إقطعة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"إقْطَاعِيَّةٌ-إقْطَاعِيَّةٌ [ق ط ع] (مص. صِنَاعِيٌّ).: نِظَامٌ قَائِمٌ عَلَى الإقْطَاعِ، وَذَلِكَ بِتَمْلِيكِ قِطَعٍ مِنَ الأرْضِ لِفَرْدٍ أَوْ عَائِلَةٍ تَسْتَغِلُّهَا اسْتِغْلاَلاً مُطْلَقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21740, 'شَهْرِيَّةٌ', 'شهرية', 'مصدر', 'شهر', 'شهرية', 'شهرة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَهْرِيَّةٌ-شَهْرِيَّةٌ [ش هـ ر] (مص. صِنَاعِيٌّ). ""تَسَلَّمَ شَهْرِيَّتَهُ"": رَاتِبَهُ الشَّهْرِيَّ. ""قَالَ لِي: إِنَّ أُجْرَتَهُ الشَّهْرِيَّةَ لاَ تَكْفِيهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21741, 'شُيُوعِيَّةٌ', 'شيوعية', 'مصدر', 'شيع', 'شيوعية', 'شعة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شُيُوعِيَّةٌ-شُيُوعِيَّةٌ [ش ي ع] (مص. صِنَاعِيٌّ) (سيا).: مَذْهَبٌ اِقْتِصَادِيٌّ وَاجْتِمَاعِيٌّ قَائِمٌ عَلَى جَعْلِ وَسَائِلِ الإِنْتَاجِ مُشْتَرَكَةً"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21742, 'صُوفِيَّةٌ', 'صوفية', 'مصدر', 'صوف', 'صوفية', 'صفة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"صُوفِيَّةٌ-صُوفِيَّةٌ [ص و ف] (مص. صِنَاعِيٌّ). ""كَانَ رَحِمَهُ اللَّهُ مِنْ رِجَالِ الصُّوفِيَّةِ"" : مِنْ رِجَالِ التَّعَبُّدِ وَالزُّهْدِ وَالْخَلْوَةِ للِنُّسْكِ وَالتَّقَشُّفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21743, 'طُوبَاوِيَّةٌ', 'طوباوية', 'مصدر', 'طوب', 'طوباوية', 'طبة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"طُوبَاوِيَّةٌ-طُوبَاوِيَّةٌ، طُوبَائِيَّةٌ [ط و ب] (مص. صِنَاعِيٌّ). ""يَدْعُو إِلَى اشْتِرَاكِيَّةٍ طُوبَائِيَّةٍ"" : الاشْتِرَاكِيَّةُ الَّتِي تَحْلُمُ بِمُجْتَمَعٍ خَالٍ مِنَ الصِّرَاعِ وَتَسْعَى إلى تَحْقيقِ مُثُلٍ عُلْيا بَعِيدَةٍ عَنِ الوَاقِعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21744, 'تَعْبِيرِيَّةٌ', 'تعبيرية', 'مصدر', 'عبر', 'تعبيرية', 'تعبرة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَعْبِيرِيَّةٌ-تَعْبِيرِيَّةٌ [ع ب ر] (مص. صِنَاعِيٌّ).: مَذْهَبٌ مِنْ مَذَاهِبِ الفَنِّ وَالأَدَبِ وَبِالأَخَصِّ فِي مَجَالِ الرَّسْمِ، ظَهَرَ فِي أُورُوبَّا فِي بِدَايَةِ هَذ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21745, 'مَعْلُومَاتِيَّةٌ', 'معلوماتية', 'مصدر', 'علم', 'معلوماتية', 'معلمتة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِنَاعِيٌّ). ""أَصْبَحَتِ الْمَعْلُومِيَّاتُ تَحْتَلُّ مَكَاناً شَاسِعاً فِي العَصْرِ الْحَدِيثِ"" : عِلْمٌ يَهْتَمُّ بِتَحْلِيلِ الْمَعْلُومَاتِ آلِيّاً بِوَاسِطَةِ الْحَوَاسِيبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21746, 'غَيْرِيَّةٌ', 'غيرية', 'مصدر', 'غير', 'غيرية', 'غرة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"غَيْرِيَّةٌ-غَيْرِيَّةٌ [غ ي ر] (مص. صِنَاعِيٌّ). 1. : كَوْنُ كُلٍّ مِنَ الشَّيْئَيْنِ خِلاَفَ الآخَرِ. 2.""يَتَمَيَّزُ بِالغَيْرِيَّةِ"" : الإِيثارُ، يُفَضِّلُ الغَيْرَ عَلَى الذَّاتِ خِلاَفَ الأَنَانِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21747, 'فَاشِسْتِيَّةٌ', 'فاشستية', 'مصدر', '', 'فاشستية', 'فشستة', 'مص. صِنَاعِيٌّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"فَاشِسْتِيَّةٌ-فَاشِسْتِيَّةٌ (سيا) (مص. صِنَاعِيٌّ). : نِظَامٌ قَائِمٌ عَلَى اسْتِبْدَادِ السُّلْطَةِ بِالْحُكْمِ وَالتَّعَصُّبِ الْقَوْمِيِّ وَالتَّطَرُّفِ الْعِرْقِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21748, 'تَقَدُّمِيَّةٌ', 'تقدمية', 'مصدر', 'قدم', 'تقدمية', 'تقدمة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَقَدُّمِيَّةٌ-تَقَدُّمِيَّةٌ [ق د م] (مص. صِنَاعِيٌّ). ""عَبَّرَ عن أَفْكارِهِ التَّقَدُّم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21749, 'نِسْبِيَّةٌ', 'نسبية', 'مصدر', 'نسب', 'نسبية', 'نسبة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نِسْبِيَّةٌ-نِسْبِيَّةٌ [ن س ب] (مص. صِنَاعِيٌّ). 1. : مَذْهَبٌ فَلْسَفِيٌّ يَقُولُ إِنَّ الْمَعَارِفَ نِسْبِيَّةٌ وَغَيْرُ مُطْلَقَةٍ. 2.""نَظَرِيَّةُ النِّسْبِيَّةِ"" : نَظَرِيَّةُ أَيْنِشْتَاين الَّتِي تَرَى أَنَّ مُرُورَ الزَّمَنِ لَيْسَ هُوَ نَفْسُهُ عِنْدَ مُلاَحِظَيْنِ يَخْتَلِفُ مَوْقِعُ كُلُّ وَاحِدٍ مِنْهُمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21750, 'قَوْمِيَّةٌ', 'قومية', 'مصدر', 'قوم', 'قومية', 'قمة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"قَوْمِيَّةٌ-قَوْمِيَّةٌ [ق و م] (مص. صِنَاعِيٌّ). ""تَشُدُّهُمْ رَوَابِطُ القَوْمِيَّةِ"" : عَقِيدَةٌ سِيَاسِيَّةٌ تَرْمِي إِلَى خَلْقِ وَعْيٍ بِالْمَصَالِحِ الْمُشْتَرَكَةِ، وَالدِّفَاعِ وَالحَمِيَّةِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21751, 'كَاثُولِيكِيَّةٌ', 'كاثوليكية', 'مصدر', '', 'كاثوليكية', 'كثلكة', 'مص. صِنَاعِيٌّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"كَاثُولِيكِيَّةٌ-كَاثُولِيكِيَّةٌ (مص. صِنَاعِيٌّ). : مَذْهَبٌ يَضُمُّ مَجْمُوعَ التَّعَالِيمِ الْمَسِيحِيَّةِ الَّتِي تَدِينُ بِهَا الكَنِيسَةُ وَعَلَى رَأْسِهَا الْحَبْرُ الأَعْظَمُ : البَابَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21752, 'كَشْفِيَّةٌ', 'كشفية', 'مصدر', 'كشف', 'كشفية', 'كشفة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"كَشْفِيَّةٌ-كَشْفِيَّةٌ [ك ش ف] (مص. صِنَاعِيٌّ). : حَرَكَةٌ تَهْذِيبِيَّةٌ عَالَمِيَّةٌ أَنْشَأَهَا الإِنْجِلِيزِي بَادْن بَاوْل سَنَةَ 1909، تَهْدِفُ إِلَى "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21753, 'لاَهُوتِيَّةٌ', 'لاهوتية', 'مصدر', '', 'لاهوتية', 'لهتة', 'مص. صِنَاعِيٌّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"لاَهُوتِيَّةٌ-لاَهُوتِيَّةٌ (مص. صِنَاعِيٌّ). : عِلْمُ العَقَائِدِ الْمُتَعَلِّقَةِ بِاللَّهِ تَعَالَى."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21754, 'لُصُوصِيَّةٌ', 'لصوصية', 'مصدر', 'لصص', 'لصوصية', 'لصصة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"لُصُوصِيَّةٌ-لُصُوصِيَّةٌ [ل ص ص] (مص. صِنَاعِيٌّ). ""يَحْتَرِفُ اللُّصُوصِيَّةَ"" : عَمَلُ اللِّصّ، أَيِ السَّرِقَةُ وَالاخْتِلاَسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21755, 'مِثَالِيَّةٌ', 'مثالية', 'مصدر', 'مثل', 'مثالية', 'مثلة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مِثَالِيَّةٌ-مِثَالِيَّةٌ [م ث ل] (مص. صِنَاعِيٌّ).: فِي الفَلْسَفَةِ مَذْهَبٌ فَلْسَفِيٌّ يَجْعَلُ الفِكْرَ خَاضِعاً لِتَصَوُّرٍ ذِهْنِيٍّ وَحَقِيقَةٍ عُلْيَا فَوْقَ كُلِّ مَا هُوَ مَوْضُوعِيٌّ وَمَادِّيٌّ. فِي الفَنِّ وَالأَدَبِ هُوَ تَمَثُّلُ الأَشْيَاءِ نَمَاذِجَ تَرْمُزُ إِلَى قُوَّةِ جَوْهَرِهَا فِي الأَخْلاَقِ، الدَّعْوَةُ إِلَى الكَمَالِ الإِنْسَانِيِّ وَجَعْلِ الإِنْسَانِ غَايَةً أَخْلاَقِيَّةً نَمُوذَجِيَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21756, 'مَجُوسِيَّةٌ', 'مجوسية', 'مصدر', 'مجس', 'مجوسية', 'مجسة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَجُوسِيَّةٌ-مَجُوسِيَّةٌ [م ج س] (مص. صِنَاعِيٌّ).: عَقِيدَةُ الْمَجُوسِ، وَهِيَ عِبادَةُ النَّارِ وَالكَوَاكِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21757, 'مَادِّيَّةٌ', 'مادية', 'مصدر', 'مدد', 'مادية', 'مدة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَادِّيَّةٌ-مَادِّيَّةٌ [م د د] (مص. صِنَاعِيٌّ). ""مَذْهَبُ الْمَادِّيَّةِ"" : مَذْهَبٌ فَلْسَفِيٌّ يَرْتَكِزُ عَلَى أَنَّ الْمَادَّةَ وَحْدَهَا هِيَ وَاقِعُ الأَشْيَاءِ وَيُنْكِرُ وُجُودَ الرُّوحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21758, 'نَازِيَّةٌ', 'نازية', 'مصدر', '', 'نازية', 'نزة', 'مص. صِنَاعِيٌّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نَازِيَّةٌ-نَازِيَّةٌ (سيا) (مص. صِنَاعِيٌّ). : حَرَكَةٌ سِيَاسِيَّةٌ مَثَّلَهَا الْحِزْبُ الوَطَنِيُّ الاشْتِرَاكِيُّ، الَّذِي أَنْشَأَهُ هِتْلَرُ فِي ألْمَانْيَـا سَنَةَ 1923."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21759, 'مَوْضُوعِيَّةٌ', 'موضوعية', 'مصدر', 'وضع', 'موضوعية', 'مضعة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَوْضُوعِيَّةٌ-مَوْضُوعِيَّةٌ [و ض ع] (مص. صِنَاعِيٌّ). ""تَتَمَيَّزُ أَحْكَامُهُ بِالْمَوْضُوعِيَّةِ"" : أَحْكَامٌ كَمَا هِيَ، كَمَا يَرَاهَا الذِّهْنُ فِي الوَاقِعِ، بَعِيدَةً عَنِ الذَّاتِيَّةِ، لاَ تَشُوبُهَا نَظْرَةٌ ضَيِّقَةٌ وَلاَ تَحَيُّزٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21760, 'نَاصِرِيَّةٌ', 'ناصرية', 'مصدر', 'نصر', 'ناصرية', 'نصرة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نَاصِرِيَّةٌ-نَاصِرِيَّةٌ [ن ص ر] (سيا) (مص. صِنَاعِيٌّ). : مُجْمَلُ الآرَاءِ وَالأَفْكَارِ فِي الوَحْدَةِ وَالاشْتِرَاكِيَّةِ الَّتِي كَانَ يَطْرَحُهَا وَيُدَافِعُ عَنْهَا الرَّئِيسُ جَمَالُ عَبْدِ النَّاصِرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21761, 'نَصْرَانِيَّةٌ', 'نصرانية', 'مصدر', 'نصر', 'نصرانية', 'نصرنة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نَصْرَانِيَّةٌ-نَصْرَانِيَّةٌ [ن ص ر] (مص. صِنَاعِيٌّ). : الْمَسِيحِيَّةُ، أَيْ دِينُ السَّيِّدِ الْمَسِيحِ عَلَيْهِ السَّلاَمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21762, 'نَظَرِيَّةٌ', 'نظرية', 'مصدر', 'نظر', 'نظرية', 'نظرة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِنَاعِيٌّ). 1.""يَشْرَحُ النَّظَرِيَّةَ فيِ الفَصْلِ وَيُطَبِّقُهَا فِي الْمُخْتَبَرِ"" : قَضِيَّةٌ فِي مَجَالٍ عِلْمِيٍّ مَّا تَثْبُتُ بِحُجَّةٍ وَبُرْهَانٍ. ""جَاءَ التَّطْبِيقُ لِيُؤَكِّدَ صِحَّةَ النَّظَرِيَّةِ"". 2.""نَظَرِيَّةُ القِيمَةِ الوُسْطَى"" : نَظَرِيَّةُ الزِّيَادَاتِ الْمُتَنَاهِيَةِ. 3.""نَظَرِيَّةُ فِيتَاغُورَسَ"" : النَّظَرِيَّةُ الْخَاصَّةُ بِالْمُثَلَّثِ قَائِمِ الزَّاوِيَةِ الْمُقِرَّةُ أَنَّ مُرَبَّعَ الوَتَرِ يُسَاوِي مَجْمُوعَ مُرَبَعَيِ الضِّلْعَيْنِ الآخَرَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21763, 'نَفْعِيَّةٌ', 'نفعية', 'مصدر', 'نفع', 'نفعية', 'نفعة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نَفْعِيَّةٌ-نَفْعِيَّةٌ [ن ف ع] (مص. صِنَاعِيٌّ): مَذْهَبُ الَّذِينَ يَطْلُبُونَ الْمَنْفَعَةَ الْمُجَرَّدَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21764, 'مَنْهَجِيَّةٌ', 'منهجية', 'مصدر', 'نهج', 'منهجية', 'منهجة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِنَاعِيٌّ). ""أَلْقَى مُحَاضَرَةً فِي الْمَنْهَجِيَّةِ"" : فِي طُرُقِ البَحْثِ والدِّرَاسَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21765, 'وُجُودِيَّةٌ', 'وجودية', 'مصدر', 'وجد', 'وجودية', 'جدة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وُجُودِيَّةٌ-وُجُودِيَّةٌ [و ج د] (مص. صِنَاعِيٌّ). : مَذْهَبٌ فَلْسَفِيٌّ قَائِمٌ عَلَى اعْتِبَارِ أَنَّ الوُجُودَ يَتَقَدَّمُ الْمَاهِيَةَ، وَأَنَّ الإِنْسَانَ يُوجَدُ فِيهِ حُرّاً، يَبْنِي نَفْسَهُ حَسَبَ إِرَادَتِهِ وَمَشِيئَتِهِ وَيَخْتَارُ لَهَا نَمُوذَجَ وُجُودِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21766, 'وَحْدَوِيَّةٌ', 'وحدوية', 'مصدر', 'وحد', 'وحدوية', 'حدة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وَحْدَوِيَّةٌ-وَحْدَوِيَّةٌ [و ح د] (مص. صِنَاعِيٌّ). ""يَدْعُو إِلَى الوَحْدَوِيَّةِ فِي العَمَلِ السِّيَاسِيِّ"" : أَيْ كُلُّ مَا يُقَوِّي وَحْدَةَ العَمَلِ وَيُدَعِّمُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21767, 'وَحْشِيَّةٌ', 'وحشية', 'مصدر', 'وحش', 'وحشية', 'حشة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وَحْشِيَّةٌ-وَحْشِيَّةٌ [و ح ش] (مص. صِنَاعِيٌّ). ""وَحْشِيَّةُ الْحَرْبِ"" : هَمَجِيَّتُهَا، شَرَاسَتُهَا. ""تَصَرَّفَ مَعَهُ بِكُلِّ وَحْشِيَّةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21768, 'وُصُولِيَّةٌ', 'وصولية', 'مصدر', 'وصل', 'وصولية', 'صلة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وُصُولِيَّةٌ-وُصُولِيَّةٌ [و ص ل] (مص. صِنَاعِيٌّ). ""جَمَاعَةٌ تَمَيَّزَتْ سِيَاسَتُهَا بِالوُصُولِيَّةِ"" : سِيَاسَةُ تَحْقِيقِ الْمَنَافِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21769, 'طَائِفِيَّةٌ', 'طائفية', 'مصدر', 'طوف', 'طاءفية', 'طفة', 'مص. صِنَاعِيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"طَائِفِيَّةٌ-طَائِفِيَّةٌ [ط و ف] (مص. صِنَاعِيّ). ""مَا زَالَتِ الطَّائِفِيَّةُ تَتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21770, 'وَاقِعِيَّةٌ', 'واقعية', 'مصدر', 'وقع', 'واقعية', 'قعة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وَاقِعِيَّةٌ-وَاقِعِيَّةٌ [و ق ع] (مص. صِنَاعِيٌّ). 1. فِي مَجَالِ الفَلْسَفَةِ : مَذْهَبٌ قَائِمٌ عَلَى اعْتِبَارِ الوَاقِعِ الْمَادِّيِّ الْمَحْسُوسِ لِلطَّبِيعَةِ وَالْحَيَاةِ مُنْطَلَقَ التَّفْسِيرِ وَالتَّحْلِيلِ. 2. فِي الأَدَبِ : تَيَّارٌ أَدَبِيٌّ نَشَأَ فِي فَرَنْسَا مُنْذُ مُنْتَصَفِ القَر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21771, 'وَهَّابِيَّةٌ', 'وهابية', 'مصدر', 'وهب', 'وهابية', 'هبة', 'مص. صِنَاعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وَهَّابِيَّةٌ-وَهَّابِيَّةٌ [و هـ ب] (مص. صِنَاعِيٌّ). : مِنَ الْمَذَاهِبِ الإِسْلاَمِيَّةِ الْمُسْتَحْدَثَةِ، وَضَعَ أُسُسَهُ الشَّيْخُ مُحَم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21772, 'جَاهِلِيَّةٌ', 'جاهلية', 'مصدر', 'جهل', 'جاهلية', 'جهلة', 'مص. صِنَاعِيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"جَاهِلِيَّةٌ-جَاهِلِيَّةٌ [ج هـ ل] . (مص. صِنَاعِيّ). عَاشَ العَرَبُ فِي الجَاهِلِيَّةِ يَعْبُدُونَ الأَصْنَامَ إِلَى أَنْ جَاءَ الإِسْلاَمُ وَأَنْقَذَهُمْ مِنَ الوَثَنِيَّةِ"": حَالَةُ الجَهْلِ الَّتِي كَانُوا عَلَيْهَا قَبْلَ مَجِيءِ الإِسْلاَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21773, 'رَجْعِيَّةٌ', 'رجعية', 'مصدر', 'رجع', 'رجعية', 'رجعة', 'مص. صِنَاعِيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَجْعِيَّةٌ-رَجْعِيَّةٌ [ر ج ع] (مص. صِنَاعِيّ). ""تَتَّسِمُ سِيَاسَتُهُ بِالرَّجْعِيَّةِ"" : صِفَةٌ لِمَوَاقِفَ سِياسِيَّةٍ تَتَشَبَّثُ بِتَقَالِيد السَّلَفِ وَأفْكَارٍ مُحَافِظَةٍ تَحُولُ دُونَ التَّقَدُّمِ الحَضَارِيِّ وَالاجْتِمَاعِيِّ وَالسِّيَاسِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21774, 'شَعْبِيَّةٌ', 'شعبية', 'مصدر', '', 'شعبية', 'شعبة', 'مص. صِنَاعِيّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَعْبِيَّةٌ-شَعْبِيَّةٌ (مص. صِنَاعِيّ). ""قَائِدٌ سِيَاسِيٌّ يَتَمَتَّعُ بِشَعْبِيَّةٍ كَبِيرَةٍ"" : يَتَمَتَّعُ بِتَأْيِيدِ عَامَّةِ الشَّعْبِ وَعَطْفِهِمْ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21775, 'صَلاَحِيَّةٌ', 'صلاحية', 'مصدر', 'صلح', 'صلاحية', 'صلحة', 'مص. صِنَاعِيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِنَاعِيّ). 1.""صَلاَحِيَّةُ العَمَلِ"" : حُسْنُ أَهْلِيَّتِهِ. ""لَهُ الصَّلاَحِيَّةُ الكَامِلَةُ لِلْقِيَامِ بِهَذَا الأَمْرِ"" : لَهُ الأَهْلِيَّةُ لِلْقِيَامِ بِهِ. 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21776, 'اِنْطِباعِيَّةٌ', 'انطباعية', 'مصدر', 'طبع', 'انطباعية', 'نطبعة', 'مص. صِنَاعِيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"اِنْطِباعِيَّةٌ-اِنْطِباعِيَّةٌ [ط ب ع] (مص. صِنَاعِيّ).: مِنْ مَذاهِبِ فَنِّ الرَّسْمِ، يَعْتَمِدُ الرُّؤْيَةَ التِّلْقائِيَّةَ والعَفْوِيَّةَ على قاعِدَةِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21777, 'طُفُولِيَّةٌ', 'طفولية', 'مصدر', 'طفل', 'طفولية', 'طفلة', 'مص. صِنَاعِيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"طُفُولِيَّةٌ-طُفُولِيَّةٌ [ط ف ل] (مص. صِنَاعِيّ). ""مَازَالَتْ تَصَرُّفاَتُهُ طُفُولِيَّةً"" : صِفَاتُ الطُّفُولَةِ عِنْدَ الكِبَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21778, 'طُوبُوغْرَافِيَّةٌ', 'طوبوغرافية', 'مصدر', '', 'طوبوغرافية', 'طبغرفة', 'مص. صِنَاعِيّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"طُوبُوغْرَافِيَّةٌ-طُوبُوغْرَافِيَّةٌ (مص. صِنَاعِيّ). ""عِلْمُ الطُّوبُوغْرَافِيَّةِ"" : عِلْمٌ مُخْتَصٌّ بِوَصْفِ جِهَةٍ مِنْ جِهَاتِ الأَرْضِ وَرَسْمِهَا وَإِظْهَارِ مَا عَلَيْهَا مِن تَضارِيسَ وَمَا يُحِيطُ بِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21779, 'مَلَكِيَّةٌ', 'ملكية', 'مصدر', 'ملك', 'ملكية', 'ملكة', 'مص. صِنَاعيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَلَكِيَّةٌ-مَلَكِيَّةٌ [م ل ك] (مص. صِنَاعيّ). ""مَلَكِيَّةٌ دُسْتُورِيَّةٌ"" : نِظَامٌ سِيَاسِيٌّ يَخْضَعُ لِسُلْطَةِ الْمَلِكِ عَلَى أَسَاسِ دُسْتُورٍ يُنَظِّمُ السُّلَطَ. ""مَلَكِيَّةٌ وِرَاثِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21780, 'عُنْصُرِيَّةٌ', 'عنصرية', 'مصدر', 'عنصر', 'عنصرية', 'عنصرة', 'مص. صِنَاعِيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عُنْصُرِيَّةٌ-عُنْصُرِيَّةٌ [ع ن ص ر] (مص. صِنَاعِيّ). : مَذْهَبٌ قَائِمٌ عَلَى التَّفْرِقَةِ بَيْنَ الْبَشَرِ بِحَسَبِ أُصُولِهِمُ الْجِنْسِيَّةِ وَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21781, 'فِدَائِيَّةٌ', 'فدائية', 'مصدر', 'فدي', 'فداءية', 'فدة', 'مص. صِنَاعِيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"فِدَائِيَّةٌ-فِدَائِيَّةٌ [ف د ي] (مص. صِن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21782, 'قَابِلِيَّةٌ', 'قابلية', 'مصدر', 'قبل', 'قابلية', 'قبلة', 'مص. صِنَاعِيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"قَابِلِيَّةٌ-قَابِلِيَّةٌ [ق ب ل] (مص. صِنَاعِيّ). ""لَهُ قَابِلِيَّةُ الاسْتِمَاعِ إِلَى غَيْرِهِ"" : حَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21783, 'مُسْتَقْبَلِيَّةٌ', 'مستقبلية', 'مصدر', 'قبل', 'مستقبلية', 'مستقبلة', 'مص. صِنَاعِيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِنَاعِيّ). مَجَالٌ عِلْمِيٌّ يَشْتَغِلُ فِيهِ مُتَخَصِّصُونَ لِمَعْرِفَةِ أ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21784, 'مِغْنَاطِيسِيَّةٌ', 'مغناطيسية', 'مصدر', '', 'مغناطيسية', 'مغنطسة', 'مص. صِنَاعِيّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مِغْنَاطِيسِيَّةٌ-مِغْنَاطِيسِيَّةٌ (مص. صِنَاعِيّ). : قُوَّةُ الْجَاذِبِيَّةِ فِي الْمِغْنَاطِيسِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21785, 'أهَمِّيَّةٌ', 'أهمية', 'مصدر', 'همم', 'ءهمية', 'همة', 'مص. صِنَاعِيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"أهَمِّيَّةٌ-أهَمِّيَّةٌ [هـ م م] (مص. صِنَاعِيّ). 1.""مَوْضُوعٌ لَهُ أهَمِّيَّةٌ كُبْرَى"" : مَكَانَةٌ، شَأنٌ. ""عَلَّقَ أهَمِّيَّةً خَاصَّةً عَلَى حُضُورِهِ"". 2.""تَكْمُنُ أهَمِّيَّةُ الأمْرِ فِي ..."" : تَكْمُنُ خُطُورَتُهُ. ""هَذَا أمْرٌ عَلَى جَانِبٍ كَبِيرٍ مِنَ الأهَمِّيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21786, 'وَطَنِيَّةٌ', 'وطنية', 'مصدر', 'وطن', 'وطنية', 'طنة', 'مص. صِنَاعِيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وَطَنِيَّةٌ-وَطَنِيَّةٌ [و ط ن] (مص. صِنَاعِيّ). ""هِيَ الوَطَنِيَّةُ الْحَقَّةُ قَدْ تَغَلْغَلَتْ فِي نُفُوس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21787, 'مَسِيحِيَّةٌ', 'مسيحية', 'مصدر', 'مسح', 'مسيحية', 'مسحة', 'مص. صِنَاعيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَسِيحِيَّةٌ-مَسِيحِيَّةٌ [م س ح] (مص. صِنَاعيٌّ). ""الدِّيَانَةُ الْمَسِيحِيَّةُ"" : الدِّيَانَةُ النَّصْرَانِيَّةُ التِي جَاءَ بِهَا السَّيِّدُ الْمَسِيحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21788, 'فَوْضَوِيَّةٌ', 'فوضوية', 'مصدر', 'فوض', 'فوضوية', 'فضة', 'مص. صِنَاعيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"فَوْضَوِيَّةٌ-فَوْضَوِيَّةٌ [ف و ض] (مص. صِنَاعيّ). : مَذْهَبٌ سِيَاسِيٌّ قَائِمٌ عَلَى إِلْغَاءِ الْقَوَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21789, 'إِشْكالِيَّةٌ', 'إشكالية', 'مصدر', 'شكل', 'ءشكالية', 'إشكلة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِناعِيٌّ). ""طَرَحَ إِشْكالِيَّةً على الْمُناظِرينَ"" : قَضِيَّةً فِكْرِيَّةً أَوْ ثَقافِيَّةً أَوِ اجْتِماعِيَّةً، تَتَضَمَّنُ الْتِباسًا وَغُموضاً، وَهِيَ بِحاجَةٍ إلى تَفْكيرٍ وَتَأَمُّلٍ وَنَظَرٍ لإيجادِ حَلٍّ لَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21790, 'عَبْقَرِيَّةٌ', 'عبقرية', 'مصدر', 'عبقر', 'عبقرية', 'عبقرة', 'مص. صِناَعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عَبْقَرِيَّةٌ-عَبْقَرِيَّةٌ [ع ب ق ر] (مص. صِناَعِيٌّ). ""يُودِعُ فِي الْكُتُبِ آيَاتِ عَبْقَرِيَّتِهِ"" : صِفَةُ الْعَبْقَرِيِّ، أَيْ قُوَّةُ الْخَلْقِ وَالإِبْدَاعِ عِنْدَ فَنَّانٍ أَوْ كَاتِبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21791, 'أكَادِيمِيّةٌ', 'أكاديمية', 'مصدر', '', 'ءكاديمية', 'كدمة', 'مص. صِناعِيٌّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"أكَادِيمِيّةٌ-أكَادِيمِيّةٌ (مص. صِناعِيٌّ).: اِسْمٌ يُطْلَقُ عَلَى الْمُؤَسَّسَاتِ العِلْمِيَّةِ أوِ الأدَبِيَّةِ. ""أكَادِيمِيَّةُ العُلُومِ"" ""أكَادِيمِيَّةُ الْمَمْلَكَةِ الْمَغْرِبِيَّة""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21792, 'أَنانِيَّةٌ', 'أنانية', 'مصدر', 'أنأ', 'ءنانية', 'ننة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"أَنانِيَّةٌ-أَنانِيَّةٌ [أ ن أ] (مص. صِناعِيٌّ). ""كُلُّ حَرَكَةٍ مِنْ حَرَكاتِهِ تُظْهِرُ أَنانِيَّةً لاَ حَدَّ لَها"" : الإفْراطُ في حُبِّ النَّفْسِ وَالإعْجابِ بِها، مَعَ عَدَمِ التَّفْكيرِ في الغَيْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21793, 'إِنْسانِيَّةٌ', 'إنسانية', 'مصدر', 'أنس', 'ءنسانية', 'إنسنة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"إِنْسانِيَّةٌ-إِنْسانِيَّةٌ [أ ن س] (مص. صِناعِيٌّ). 1.""تَتَكاثَفُ الجُهودُ العِلْمِيَّةِ لِخِدْمَةِ الإِنْسانِيَّةِ"" : البَشَرِيَّةِ، أَيْ لِخِدْمَةِ الجِنْسِ البَشَرِيِّ. 2.""يُتا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21794, 'بُرُوتِسْتانِيَّةٌ', 'بروتستانية', 'مصدر', '', 'بروتستانية', 'برتستنة', 'مص. صِناعِيٌّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"بُرُوتِسْتانِيَّةٌ-بُرُوتِسْتانِيَّةٌ (مص. صِناعِيٌّ). : مَذْهَبٌ مِنَ الْمَذاهِبِ الدِّينِيَّةِ الْمُنْتَمِيَةِ لِلْكَن"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21795, 'حَدْسِيَّةٌ', 'حدسية', 'مصدر', 'حدس', 'حدسية', 'حدسة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِناعِيٌّ). ""آراؤُهُ قائِمَةٌ على الحَدْسِيَّةِ"" : مَذْهَبٌ يَقولُ بِأَنَّ الْمَعْرِفَةَ قائِمَةٌ بِالدَّرَجَةِ الأُولَى على جانِبِ الحَدْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21796, 'رُوحِيَّةٌ', 'روحية', 'مصدر', 'روح', 'روحية', 'رحة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رُوحِيَّةٌ-رُوحِيَّةٌ [ر و ح] (مص. صِناعِيٌّ). ""الفَلْسَفَةُ الرُّوحِيَّةِ"": أي عَكْسُ الفلْسَفَة الْمَادِّيَّة، وَتَرْمِي إلَى إِثْباتِ أَنَّ الرُّوحَ تَعْلُو وَتَسْمو عَلَى المادَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21797, 'رُومانْسِيَّةٌ', 'رومانسية', 'مصدر', '', 'رومانسية', 'رمنسة', 'مص. صِناعِيٌّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رُومانْسِيَّةٌ-رُومانْسِيَّةٌ (مص. صِناعِيٌّ). : صِفَةُ الحَرَكاتِ الفَنِّيَّةِ والأَدَبِيَّةِ الَّتِي ظَهَرَتْ في أُوروبَّا بَعْدَ عَصْرِ النَّهْضَةِ وَعُرِفَتْ بِالرُّومانْطِقِيَّةِ وَتَطَوَّرَتْ بِالأَخَصِّ في نِهايَةِ القَرْنِ الثَّامِنِ عَشَرَ. مَثَّلَتِ الرُّومانْسِيَّةُ ثَوْرَةً عَلَى الكِلاسِيكِيَّةِ والتَّحَرُّرِ مِنْ قَواعِدِها وَتِقْنِياتِها، ومِنْ خَصائِصِها: اِعْتِمادُ الخَيالِ والعاطِفَةِ مُنْطَلَقاً لِلرُّؤْيَةِ الفَنِّيَّةِ، وَإِبْعادُ الجانِبِ العَقْلِيِّ، وَجَعْلُ الطَّبيعَةِ مادَّةً لِلْكِتابَةِ والانْغِمارُ في أَجْوائِها، وَعَرَفَ الأَدَبُ العَرَبِيُّ رُومانْسِيِّينَ مثل: جَبْران خليل جبران وخليل مطران وَعَلِيّ محمود طه."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21798, 'اِشْتِراكِيَّةٌ', 'اشتراكية', 'مصدر', 'شرك', 'اشتراكية', 'شتركة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"اِشْتِراكِيَّةٌ-اِشْتِراكِيَّةٌ [ش ر ك] (مص. صِناعِيٌّ). مَذْهَبٌ اِقْتِصادِيٌ وَاجْتِماعِيٌّ وَسِياسِيٌّ قائِمٌ على إِلْغاءِ المِلْكِيَّةِ الخاصَّةِ الواسِعَةِ، وَتَأْمِيمِ وَسائِلِ الإِنْتاجِ وَالْمُواصَلاتِ وَالْمُؤَسَّساتِ الاقْتِصادِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21799, 'مُعْجَمَاتِيَّةٌ', 'معجماتية', 'مصدر', 'عجم', 'معجماتية', 'معجمتة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعْجَمَاتِيَّةٌ-مُعْجَمَاتِيَّةٌ [ع ج م] (مص. صِناعِيٌّ).: عِلْمُ صِنَاعَةِ الْمُعْجَمَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21800, 'مَعْمُودِيَّةٌ', 'معمودية', 'مصدر', 'عمد', 'معمودية', 'معمدة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَعْمُودِيَّةٌ-مَعْمُودِيَّةٌ [ع م د] (مص. صِناعِيٌّ). ""أُقِيمَ حَفْلُ الْمَعْمُودِيَّةِ لِلطِّفْلِ فِي الكَنِيسَةِ"" : تَنْصِيرُ الطِّفْلِ لِيَصِيرَ مَسِيحِيّاً وذَلِكَ بِغَسْلِهِ بِالْمَاءِ الْمُطَهَّرِ عَلَى يَدِ القَسِّ أَوِ الرَّاهِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21801, 'مُفَوَّضِيَّةٌ', 'مفوضية', 'مصدر', 'فوض', 'مفوضية', 'مفضة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُفَوَّضِيَّةٌ-مُفَوَّضِيَّةٌ [ف و ض] (مص. صِناعِيٌّ). : مَنْصِبُ الْمُفَو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21802, 'إِقْلِيمِيَّةٌ', 'إقليمية', 'مصدر', 'قلم', 'ءقليمية', 'إقلمة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"إِقْلِيمِيَّةٌ-إِقْلِيمِيَّةٌ [ق ل م] (مص. صِناعِيٌّ).: مَذْهَبٌ قَائِمٌ عَلَى التَّجَمُّعَاتِ الإقْلِيمِيَّةِ عَكْسَ الْمَرْكَزِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21803, 'مِكْثَافِيَّةٌ', 'مكثافية', 'مصدر', 'كثف', 'مكثافية', 'مكثفة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مِكْثَافِيَّةٌ-مِكْثَافِيَّةٌ [ك ث ف] (مص. صِناعِيٌّ). : قِيَاسُ الْكَثَافَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21804, 'إلْزَامِيَّةٌ', 'إلزامية', 'مصدر', 'لزم', 'ءلزامية', 'إلزمة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"إلْزَامِيَّةٌ-إلْزَامِيَّةٌ [ل ز م] (مص. صِناعِيٌّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21805, 'اِنْتِهازِيَّةٌ', 'انتهازية', 'مصدر', 'نهز', 'انتهازية', 'نتهزة', 'مص. صِناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"اِنْتِهازِيَّةٌ-اِنْتِهازِيَّةٌ [ن هـ ز] (مص. صِناعِيٌّ). ""يُمَثِّلُ سُلوكُهُ انْتِهازِيَّةً واضِحَةً"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21806, 'إِسْتْرَاتِيجِيَّةٌ', 'إستراتيجية', 'مصدر', '', 'ءستراتيجية', 'إسترتجة', 'مص. صِناعِيّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"إِسْتْرَاتِيجِيَّةٌ-إِسْتْرَاتِيجِيَّةٌ (مص. صِناعِيّ).: مِنَ الفُنُونِ العَسْكَرِيَّةِ وَيُقْصَدُ بِهَا التَّخْطِيطُ وَتَحْدِيدُ الوَسَائِلِ الَّتِي يَجِبُ الأخْذُ بِهَا فِي القِمَّةِ وَالقَاعِدَةِ لِتَحْقِيقِ الأهْدَافِ البَعِيدَةِ، وتُسْتَعْمَلُ أيْضاً في الخِطابِ السِّياسِيِّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21807, 'دِيماغوجِيَّةٌ', 'ديماغوجية', 'مصدر', '', 'ديماغوجية', 'دمغجة', 'مص. صِناعيٌّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دِيماغوجِيَّةٌ-دِيماغوجِيَّةٌ (سيا) (مص. صِناعيٌّ). ""لاَ يَخْلُو كَلامُهُ مِنَ الدِّيماغوجِيَّةِ"" :ك"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21808, 'دِيمُقْراطِيَّةٌ', 'ديمقراطية', 'مصدر', '', 'ديمقراطية', 'دمقرطة', 'مص. صِناعيٌّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دِيمُقْراطِيَّةٌ-دِيمُقْراطِيَّةٌ (سيا) (مص. صِناعيٌّ).: شَكْلٌ مِنْ أَشْكالِ السُّلْطَةِ والحُكْمِ يَعودُ فيهِ القَرارُ إلى الشَّعْبِ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21809, 'رَمْزِيَّةٌ', 'رمزية', 'مصدر', 'رمز', 'رمزية', 'رمزة', 'مص. صِناعيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَمْزِيَّةٌ-رَمْزِيَّةٌ [ر م ز] (مص. صِناعيٌّ). : مَذْهَبٌ في الفَنِّ والأَدَبِ يَعْتَمِدُ الإيحاءَ والتَّلْميحَ بِرُموزِهِ الْمُنْبَثِقَةِ مِنَ الصُّوَرِ الحِسِّيَّةِ والأَساطِيرِ، وَيَتْرُكُ لِلْقارِئِ مَجالاً لِلتَّصَوُّرِ والخَيالِ لإِكْمالِ الدَّلالاتِ الرَّمْزِيَّةِ كَما تُوحِي بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21810, 'بَشَرِيَّةٌ', 'بشرية', 'مصدر', 'بشر', 'بشرية', 'بشرة', 'مص. صِناعيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"بَشَرِيَّةٌ-بَشَرِيَّةٌ [ب ش ر] (مص. صِناعيّ). ""لَقَدْ حَقَّقَتِ البَشَرِيَّةُ تَقَدُّماً هائِلاً في القَرْنِ العِشْرِينَ"" : الإِنْسانِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21811, 'اِنْفِصالِيَّةٌ', 'انفصالية', 'مصدر', 'فصل', 'انفصالية', 'نفصلة', 'مص. صناعِيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"اِنْفِصالِيَّةٌ-اِنْفِصالِيَّةٌ (مص. صناعِيٌّ). صِفَةٌ لِحالَةِ الانْفِصالِ. ن.اِنْفِصالِيّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21812, 'اِحْتِفَالِيَّةٌ', 'احتفالية', 'مصدر', 'حفل', 'احتفالية', 'حتفلة', 'مص. صناعيٌّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"اِحْتِفَالِيَّةٌ-اِحْتِفَالِيَّةٌ [ح ف ل] (مص. صناعيٌّ).: اِتِّجاهٌ مَسْرَحِيٌّ شَعْبِيٌّ يعْتمدُ الفُرْجَةَ وكلَّ أَنْوَاعِ التَّعْبِيرِ الْمُختَلِفةِ شِعراً وغِناءً ورَقْصاً وإيماءً وأقْنِعةً وأزْيَاءً فِي فَضاءٍ مَفْتوحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21813, 'باطِنِيَّةٌ', 'باطنية', 'مصدر', 'بطن', 'باطنية', 'بطنة', 'مص. صناعيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"باطِنِيَّةٌ-باطِنِيَّةٌ [ب ط ن] (مص. صناعيّ).: فِرْقَةٌ دِينِيَّةٌ يَرْتَكِزُ اقْتِنَاعُهَا عَلَى أسَاسِ قاعِدَةِ أنَّ لِكُلِّ ظاهِرٍ باطِناً، وأَنَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21814, 'بِيدَاغُوجِيَّةٌ', 'بيداغوجية', 'مصدر', '', 'بيداغوجية', 'بدغجة', 'مص. صناعيّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"بِيدَاغُوجِيَّةٌ-بِيدَاغُوجِيَّةٌ (مص. صناعيّ).: عِلْمُ التَّرْبِيَةِ، يَهْدِفُ إلَى تَنْشِئَةِ الأطْفَالِ وَتَعْليمِهِمْ حَسَبَ مَنَاهِجَ وَطُرُقٍ عِلْمِيَّةٍ مُحَدَّدَةٍ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21815, 'بيرُوقْرَاطِيَّةٌ', 'بيروقراطية', 'مصدر', '', 'بيروقراطية', 'برقرطة', 'مص. صناعيّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"بيرُوقْرَاطِيَّةٌ-بيرُوقْرَاطِيَّةٌ (مص. صناعيّ).: مَجْمُوعُ المُؤَسَّسَاتِ الإدَارِيَّةِ العُمُومِيَّةِ الَّتِي يَتَوَلَّى فِيَهَا المُوَظَّفُونَ البِيروقْرَاطِيُّونَ تَطْبِيقَ سُلْطَةِ القَانُونِ حَسَبَ السُّلَّمِ الإدَارِيِّ، وَالَّتِي تَتَّسِمُ بالبُطءِ فِي التَّنْفِيذِ مِمَّا يُؤَدِّي إلَى عَرْقَلَةِ السَّيْرِ الطَّبِيعِيِّ لِشُؤُونِ المُوَاطِنِينَ وَمِنَ العَقَبَاتِ الَّتِي تَعْتَرِضُ تَطْبِيقَ الْمَشَارِيع."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21816, 'بَيُولُوجِيَّةٌ', 'بيولوجية', 'مصدر', '', 'بيولوجية', 'بلجة', 'مص. صناعيّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صناعيّ). : عِلْمُ الأحْيَاءِ، يَبْحَثُ شَكْلَ ووَظيفَةَ إِنْتاجِيَّةِ مُجْمَ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21817, 'طُبُوغْرَافِيَّةٌ', 'طبوغرافية', 'مصدر', '', 'طبوغرافية', 'طبغرفة', 'مص. صناعيّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"طُبُوغْرَافِيَّةٌ-طُبُوغْرَافِيَّةٌ (مص. صناعيّ). : بَيَانُ الْمَلاَمِحِ العَامَّةِ لِسَطْحِ الأَرْضِ طَبِيعِيَّةً كَانَتْ أَوْ مَصْنُوعَةً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21818, 'طُبُولُوجِيَّةٌ', 'طبولوجية', 'مصدر', '', 'طبولوجية', 'طبلجة', 'مص. صناعيّ', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"طُبُولُوجِيَّةٌ-طُبُولُوجِيَّةٌ (مص. صناعيّ). : عِلْمُ دِرَاسَةِ وَتَحْلِيلِ خَصَائِصِ أَوْضَاعٍ حَسَبَ مُعْطَيَاتِهَا لِتَحْدِيدِ أَنْوَاعِهَا وَأَنْظِمَتِهَا."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21819, 'أَصْنَامٌ', 'أصنام', 'مصدر', '', 'ءصنام', 'صنم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21820, 'فَرْدِيَّةٌ', 'فردية', 'مصدر', 'فرد', 'فردية', 'فردة', 'مص. صناعيّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"فَرْدِيَّةٌ-فَرْدِيَّةٌ [ف ر د] (مص. صناعيّ). 1.""تَمَيَّزَتْ فَتْرَةُ حُكْمِهِ بِالْفَرْدِيَّةِ"" : الْحُكْمُ الْفَرْدِيُّ الْمُنْعَزِلُ عَنْ آرَاءِ الْجَمَاعَةِ. 2.""يُؤْمِنُ بِالْفَرْدِيَّةِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21821, 'وَحْدَانِيَّةٌ', 'وحدانية', 'مصدر', 'وحد', 'وحدانية', 'حدنة', 'مص. صِنَاعِيٌّ مِنَ الوَحْدَة', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وَحْدَانِيَّةٌ-وَحْدَانِيَّةٌ [و ح د] (مص. صِنَاعِيٌّ مِنَ الوَحْدَة). ""وَحْدَانِيَّةُ اللَّهِ تَعَالَى"" : مِنْ صِفَاتِهِ تَعَالَى، أَيْ تَفَرُّدُهُ تَعَالَى فِي مَاهِيَّتِهِ وَ صِفَاتِ كَمَالِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21822, 'مَسْؤُولِيَّةٌ', 'مسؤولية', 'مصدر', 'سأل', 'مسءولية', 'مسلة', 'مص. صِنَاعِيٌّ مِنْ مَسْؤُولٌ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. صِنَاعِيٌّ مِنْ مَسْؤُولٌ). 1.""يَتَحَمَّلُ مَسْؤُولِيَّةَ مَا حَدَثَ"" : يَتَحَمَّلُ تَبِعَةَ مَا حَدَثَ. 2.""هَذَا الأَمْرُ عَلَى مَسْؤُولِيَّتِهِ"" : عَلَى عَاتِقِهِ، عَلَى عُهْدَتِهِ. 3.""مَسْؤُولِيَّةٌ وَطَنِيَّةٌ"" : مُهِمَّةٌ وَطَنِيَّةٌ ذَاتُ طَابِعٍ لَهُ أَهْلِيَّةٌ وَمَكَانَةٌ. ""مَسْؤُولِيَّةٌ أَخْلاَقِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21823, 'تَصْنِيعٌ', 'تصنيع', 'مصدر', 'صنع', 'تصنيع', 'تصنع', 'مص. صَنَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْنِيعٌ-تَصْنِيعٌ [ص ن ع] (مص. صَنَّعَ). ""دَخَلَتِ البِلاَدُ مَرْحَلَةَ التَّصْنِيعِ"" : إِحْدَاثُ صِنَاعَةٍ وَالتَّجْهِيزُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21824, 'صَنْعٌ', 'صنع', 'مصدر', 'صنع', 'صنع', 'صنع', 'مص. صَنَعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَنْعٌ-صَنْعٌ [ص ن ع] (مص. صَنَعَ). ""رَجُلٌ صَنْعُ الْيَدَيْنِ"": مَاهِرٌ، حَاذِقٌ فِي الصَّنْعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21825, 'صُنْعٌ', 'صنع', 'مصدر', 'صنع', 'صنع', 'صنع', 'مص. صَنَعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صُنْعٌ-صُنْعٌ [ص ن ع] (مص. صَنَعَ). ""هَذَا مِنْ صُنْعِهِ"" : مِنْ خَلْقِهِ وَاخْتِرَاعِهِ وَعَمَلِهِ.الكهف آية 104 وَهُمْ يَحْسِبُونَ أَنَّهُمْ يُحْسِنُونُ صُنْعا . (قرآن). 2.""عَمَلٌ مُحْكَمُ الصُّنْعِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21826, 'تَصْنِيفٌ', 'تصنيف', 'مصدر', 'صنف', 'تصنيف', 'تصنف', 'مص. صَنَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَصَانِيفُ"', '', 'R', '', '', '', '', '', '', '"(مص. صَنَّفَ). 1.""أَنْجَزَ تَصْنِيفًا جَدِيدًا"" : تَأْلِيفَ كِتَابٍ جَدِيدٍ. 2.""أَشْرَفَ عَلَى تَصْنِيفِ مَا عِنْدَهُ مِنْ مَوَادَّ بِدَاخِلِ الرُّفُوفِ"" : عَلَى تَرْتِيبِهَا وَوَضْعِهَا حَسَبَ أَنْوَاعِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21827, 'تَصَانِيفُ', 'تصانيف', 'مصدر', '', 'تصانيف', 'تصنف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21828, 'صَنَمٌ', 'صنم', 'مصدر', 'صنم', 'صنم', 'صنم', 'مص. صَنِمَ', '', '', 'مفرد', 'DnN', '', '', '"أَصْنَامٌ"', '', 'R', '', '', '', '', '', '', '"(مص. صَنِمَ). ""كَانَ الْعَرَبُ قَبْلَ الإِسْلاَمِ يَعْبُدُونَ الأَصْنَامَ وَكُلُّ جَمَاعَةٍ لَهَا صَنَمٌ"" : تِمْثَالُ يَتَّخِذُ صُورَةً مِنَ الصُّوَرِ، كَانَ يُعْبَدُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21829, 'صَيْدَلَةٌ', 'صيدلة', 'مصدر', 'صيدل', 'صيدلة', 'صدلة', 'مص. صَيْدَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَيْدَلَةٌ-صَيْدَلَةٌ [ص ي د ل] (مص. صَيْدَلَ). ""تَخَصَّصَ فِي الصَّيْدَلَةِ"" : عِلْمٌ يُبْحَثُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21830, 'صُهْبَةٌ', 'صهبة', 'مصدر', 'صهب', 'صهبة', 'صهبة', 'مص. صَهِبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صُهْبَةٌ-صُهْبَةٌ [ص هـ ب] (مص. صَهِبَ). ""صُهْبَةُ شَع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21831, 'صَهَدٌ', 'صهد', 'مصدر', 'صهد', 'صهد', 'صهد', 'مص. صَهَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَهَدٌ-صَهَدٌ [ص هـ د] (مص. صَهَدَ). ""اِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21832, 'صَهِيلٌ', 'صهيل', 'مصدر', 'صهل', 'صهيل', 'صهل', 'مص. صَهَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"صَهِيلٌ-صَهِيلٌ [ص هـ ل] (مص. صَهَلَ). ""صَهِيلُ الْفَرَسِ"" : صَوْتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21833, 'تَصْوِيبٌ', 'تصويب', 'مصدر', 'صوب', 'تصويب', 'تصب', 'مص. صَوَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْوِيبٌ-تَصْوِيبٌ [ص و ب] (مص. صَوَّبَ). 1.""أَتَمَّ تَصْوِيبَ مَا فِي النَّصِّ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21834, 'تَصْوِيتٌ', 'تصويت', 'مصدر', 'صوت', 'تصويت', 'تصت', 'مص. صَوَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْوِيتٌ-تَصْوِيتٌ [ص و ت] (مص. صَوَّتَ). ""شَارَكَ فِي التَّصْوِيتِ"" : الإِدْلاَءُ بِصَوْتِهِ فِي الانْتِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21835, 'تَصْوِيرَةٌ', 'تصويرة', 'مصدر', 'صور', 'تصويرة', 'تصرة', 'مص. صَوَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَصَاوِيرُ"', '', 'R', '', '', '', '', '', '', '"(مص. صَوَّرَ). ""أَنْجَزَ الفَنَّانُ تَصَاوِيرَ رَائِعَةً"" : لَوْحَاتٍ، الصُّوَرُ الْمَنْقُولَةُ طِبْقَ أَصْلِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21836, 'تَصَاوِيرُ', 'تصاوير', 'مصدر', '', 'تصاوير', 'تصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21837, 'تَصْوِيرٌ', 'تصوير', 'مصدر', 'صور', 'تصوير', 'تصر', 'مص. صَوَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَصْوِيرٌ-تَصْوِيرٌ [ص و ر] (مص. صَوَّرَ). 1.""يَجْرِي تَصْوِيرُ فِلْمٍ فِي السَّاحَةِ العُمُومِيَّةِ"" : أَخْذُ مَنَاظِرِهِ بِآلاَتِ التَّصْوِيرِ، نَقْلُ تَمْثِيلِ الْمُمَثِّلِينَ. 2.""كَانَ يَحْمِلُ مَعَهُ آلَةَ التَّصْوِيرِ لأَخْذِ صُوَرٍ لِلذِّكْرَى"" : آلَةُ الْتِقَاطِ الصُّوَرِ. 3.""أَنْهَى تَصْوِيرَ وَثَائِقِهِ"" : أَخْذُ صُوَرٍ لَهَا، أَيْ نُسَخٍ لَهَا. ""التَّصْوِيرُ الفُوتوغْرَافِيُّ"" ""التَّصْوِيرُ الشَّمْسِيُّ"" ""التَّصْوِيرُ الزَّيْتِيُّ"" ""التَّصْوِيرُ بِالأَشِعَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21838, 'صَوَرٌ', 'صور', 'مصدر', 'صور', 'صور', 'صر', 'مص. صَوِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"صَوَرٌ-صَوَرٌ [ص و ر] (مص. صَوِرَ). ""صَوَرُ شَيْءٍ"" : مَيْلُهُ، اِعْوِجَاجُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21839, 'مُضَارَعَةٌ', 'مضارعة', 'مصدر', 'ضرع', 'مضارعة', 'مضرعة', 'مص. ضَارَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُضَارَعَةٌ-مُضَارَعَةٌ [ض ر ع] (مص. ضَارَعَ). 1.""مُضَارَعَةٌ فِي الأَعْمَالِ"" : الْمُشَابَهَةُ. 2.""حُرُوفُ الْمُضَارَعَةِ"" : الهَمْزَةُ وَالنُّونُ وَاليَاءُ وَالتَّاءُ (أنيت). وَهِيَ تَكُونُ فِي أَوَّلِ الفِعْلِ الْمُضَارِعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21840, 'ضَوْءٌ', 'ضوء', 'مصدر', 'ضوأ', 'ضوء', 'ض', 'مص. ضَاءَ', '', '', 'مفرد', 'Dz', '', '', '"أَضْوَاءٌ"', '', 'Rz', '', '', '', '', '', '', '"(مص. ضَاءَ). 1.""شَاعَ الضَّوْءُ فِي الغُرْفَةِ"" : النُّورُ. ""قَرَأَ فِي ضَوْءٍ خَافِتٍ"". 2.""ضَوْءُ الشَّمْسِ"" : مَا يَشِيعُ مِنْهَا مِنِ انْبِلاَجِ الصُّبْحِ إِلَى مَغِيبِهَا، الضِّيَاءُ. ""لاَحَ ضَوْءُ القَمَرِ وانْعَكَسَ على سَطْحِ البُحَيْرَةِ فَتَلأْلأَتْ ضِياءً"". 3.""أَلْقَى الضَّوْءَ عَلَى قَضِيَّةٍ مُسْتَعْصِيَةٍ"" : أَنَارَهَا، وَضَّحَهَا، بَيَّنَهَا. ""سَلَّطَ أَضْوَاءً عَلَى الْمَوْضُوعِ"". 4.""اِسْتَمَرَّ فِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21841, 'أَضْوَاءٌ', 'أضواء', 'مصدر', '', 'ءضواء', 'ض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21842, 'ضِيَاءٌ', 'ضياء', 'مصدر', 'ضوأ', 'ضياء', 'ض', 'مص. ضَاءَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"ضِيَاءٌ-ضِيَاءٌ [ض و أ] (مص. ضَاءَ). ""ضِيَاءُ الشَّمْسِ"" : ضَوْؤُهَا. يونس آية 5 هُوَ الَّذِي جَعَلَ الشَّمْسَ ضِيَاءً وَالقَمَرَ نُورًا . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21843, 'مُضَاجَعَةٌ', 'مضاجعة', 'مصدر', 'ضجع', 'مضاجعة', 'مضجعة', 'مص. ضَاجَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُضَاجَعَةٌ-مُضَاجَعَةٌ [ض ج ع] (مص. ضَاجَعَ). ""مُضَاجَعَةُ الْمَرْأَةِ"" : مُجَامَعَتُهَا، الاضْطِجَاعُ مَعَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21844, 'مُضَاحَكَةٌ', 'مضاحكة', 'مصدر', 'ضحك', 'مضاحكة', 'مضحكة', 'مص. ضَاحَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُضَاحَكَةٌ-مُضَاحَكَةٌ [ض ح ك] (مص. ضَاحَكَ). ""يَسْعَى إِلَى مُضَاحَكَتِهِ"" : إِلَى الضَّحِكِ مَعَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21845, 'مُضَادَّةٌ', 'مضادة', 'مصدر', 'ضدد', 'مضادة', 'مضدة', 'مص. ضَادَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُضَادَّةٌ-مُضَادَّةٌ [ض د د] (مص. ضَادَّ). ""بَيْنَهُمَا مُضَادَّةٌ"" : تَضَادٌّ، تَعَارُضٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21846, 'ضَوْرٌ', 'ضور', 'مصدر', 'ضور', 'ضور', 'ضر', 'مص. ضَارَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَوْرٌ-ضَوْرٌ [ض و ر] (مص. ضَارَ). ""يُحِسُّ بِضَوْرٍ"" : بِجُوعٍ شَدِيدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21847, 'ضَيْرٌ', 'ضير', 'مصدر', 'ضير', 'ضير', 'ضر', 'مص. ضَارَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَيْرٌ-ضَيْرٌ [ض ي ر] (مص. ضَارَ). ""أَصَابَهُ ضَيْرٌ مِنْهُ"" : ضَرَرٌ. الشعراء آية 50 قَالُوا لاَ ضَيْرَ إِنَّا إِلَى رَبِّنَا مُنْقَلِبُونَ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21848, 'مُضَارَبَةٌ', 'مضاربة', 'مصدر', 'ضرب', 'مضاربة', 'مضربة', 'مص. ضَارَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. ضَارَبَ). ""مُضَارَبَةٌ مَالِيَّةٌ"" : الْمُتَاجَرَةُ فِي عَمَلِيَّاتِ البَيْعِ وَالشِّرَاءِ يَقُومُ بِهَا مُتَاجِرُونَ فِي الأَسْوَاقِ لِلانْتِفَاعِ مِنْ فُرُوقِ الأَسْعَارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21849, 'أَضْيَافٌ', 'أضياف', 'مصدر', '', 'ءضياف', 'ضف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21850, 'ضَيَاعٌ', 'ضياع', 'مصدر', 'ضيع', 'ضياع', 'ضع', 'مص. ضَاعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضَيَاعٌ-ضَيَاعٌ [ض ي ع] (مص. ضَاعَ). 1.""وَجَدَ نَفْسَهُ فِي ضَيَاعٍ مُوحَشٍ"" : فِي تَلَفٍ وَلَهْوٍ وَإِهْمَالٍ، الشُّعُورُ بِالْحِرْمَانِ وَالوَحْدَةِ. ""جَعَلَهُ عُرْضَةً لِلضَّيَاعِ"". 2.""ضَيَاعُ الوَقْتِ"" : تَبْدِيدُهُ سُدىً وَبِلاَ فَائِدَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21851, 'مُضَاعَفَةٌ', 'مضاعفة', 'مصدر', 'ضعف', 'مضاعفة', 'مضعفة', 'مص. ضَاعَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. ضَاعَفَ). 1.""عَلَيْكَ بِمُضَاعَفَةِ الجُهْدِ"" : بِالزِّياَدَةِ وَالإِكْثَارِ فِيهِ. ""تَرَاجَعَتْ إِلَى الوَرَاءِ خَوْفاً مِنْ مُضَاعَفَةِ غَضَبِهِ"" ""مُضَاعَفَةُ الإِنْتَاجِ"". 2.""أَضْعَافٌ مُضَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21852, 'ضَيْعَةٌ', 'ضيعة', 'مصدر', 'ضيع', 'ضيعة', 'ضعة', 'مص. ضَاعَ، يَضِيعُ', '', '', 'مفرد', 'DnN', '', 'Pf', '":ضِيَعٌ:ضِيَاعٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ضَاعَ، يَضِيعُ). 1.""يَعِيشُ فِي الضَّيْعَةِ"" : فِي أَرْضٍ مُغِلَّةٍ، أَيْ ذَاتُ غَلَّةٍ. 2.""يُحَافِظُ عَلَى ضَيْعَتِهِ"" : عَلَى عَمَلِهِ الْمُرْبِحِ تِجَارَةً أومِهْنَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21853, 'ضِيَعٌ', 'ضيع', 'مصدر', '', 'ضيع', 'ضع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21854, 'ضِيَاعٌ', 'ضياع', 'مصدر', '', 'ضياع', 'ضع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21855, 'مُضَاغَنَةٌ', 'مضاغنة', 'مصدر', 'ضغن', 'مضاغنة', 'مضغنة', 'مص. ضَاغَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُضَاغَنَةٌ-مُضَاغَنَةٌ [ض غ ن] (مص. ضَاغَنَ). ""حَاوَلَ إِخْفَاءَ مُضَاغَنَتِهِ"" : مَا عِنْدَهُ مِنْ حِقْدٍ وَضَغِينَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21856, 'ضِيَافَةٌ', 'ضيافة', 'مصدر', 'ضيف', 'ضيافة', 'ضفة', 'مص. ضَافَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَضَايِفُ"', '', 'R', '', '', '', '', '', '', '"(مص. ضَافَ). 1.""نَزَلَ فِي ضِيَافَتِهِ"" : نَزَلَ ضَيْفاً عِنْدَهُ. 2.""أَحْسَنَ ضِيَافَتَهُ"" : اِهْتَمَّ بِهِ أَثْنَاءَ الإِقَامَةِ عِنْدَهُ ضَيْفاً. 3.""دَارُ الضِّيَافَةِ"" : دَارٌ مُخَصَّصَةٌ لِلضُّيُوفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21857, 'مَضَايِفُ', 'مضايف', 'مصدر', '', 'مضايف', 'مضف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21858, 'ضَيْفٌ', 'ضيف', 'مصدر', 'ضيف', 'ضيف', 'ضف', 'مص. ضَافَ', '', '', 'مفرد', 'DnN', '', '', '"أَضْيَافٌ:ضُيُوفٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ضَافَ). يَكُونُ لِلْمُفْرَدِ وَالْجَمْعِ وَلِلْمُؤَنَّثِ وَالْمُذَكَّرِ. ""نَزَلَ ضَيْفاً عِنْدَهُ"" : النَّازِلُ فِي ضِيَافَتِهِ دُعِيَ أَمْ لَمْ يُدْعَ. ""هِيَ ضَيْفٌ عِنْدَنَا"" ""هُمْ ضَيْفٌ"" ""ضَيْفَةٌ عِنْدَنَا""الحجر آية 68 إِنَّ هَؤُلاَءِ ضَيْفِي فَلاَ تَفْضَحُونِ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21859, 'ضَبْطٌ', 'ضبط', 'مصدر', 'ضبط', 'ضبط', 'ضبط', 'مص. ضَبَطَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَبْطٌ-ضَبْطٌ [ض ب ط] (مص. ضَبَطَ). 1.""تَمَكَّنَ مِنْ ضَبْطِ أَعْصَابِهِ"" : مِنْ كَبْحِهَا، مِنَ السَّيْطَرَةِ عَلَيْهَا. ""ضَبْطُ النَّفْسِ"". 2.""يَهْتَمُّ بِضَبْطِ حِسَابِهِ"" : بِتَسْوِيَةِ حِسَابِهِ. 3.""وَصَلَ عَلَى السَّاعَةِ العَاشِرَةِ بِالضَّبْطِ"" : بِالتَّمَامِ. 4.""أَنْجَزَ عَمَلَهُ بِضَبْطٍ مُحْكَمٍ"" : بِدِقَّةٍ. ""بِالضَّبْطِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21860, 'ضُيُوفٌ', 'ضيوف', 'مصدر', '', 'ضيوف', 'ضف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21861, 'ضَيْقٌ', 'ضيق', 'مصدر', 'ضيق', 'ضيق', 'ضق', 'مص. ضَاقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضِيقٌ-ضِيقٌ [ض ي ق]. (مص. ضَاقَ). 1.""ضِيقُ الوَقْتِ"" : عَدَمُ اتِّسَاعِ الوَقْتِ. ""ضِيقُ الْمَقَامِ"". 2.""ضِيقُ ذَاتِ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21862, 'ضِيقٌ', 'ضيق', 'مصدر', 'ضيق', 'ضيق', 'ضق', 'مص. ضَاقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَيْقٌ-ضَيْقٌ [ض ي ق] (مص. ضَاقَ). 1.""ضَيْقُ ذَاتِ اليَدِ"": الفَقْرُ وَالشِّدَّةُ، العَوَزُ.""وَشَقِيَ بِمَا لَقِيَ مِنْ ضَيْقٍ"". 2.""هُوَ في ضَيْقٍ"": في شَكٍّ وَ أَلَمٍ وَحُزْنٍ.النحل آية 127 وَلاَ تَكُ فِي ضَيْقٍ مِمَّا يَمْكُرُونَ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21863, 'مُضَاهَاةٌ', 'مضاهاة', 'مصدر', 'ضهي', 'مضاهاة', 'مضهة', 'مص. ضَاهَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُضَاهَاةٌ-مُضَاهَاةٌ [ض هـ ي] (مص. ضَاهَى). ""لاَ مُضَاهَاةَ لِعَمَلِهِ"" : لاَ مُشَابَهَةَ، لاَ مَثِيلَ، لاَ مُمَاثَلَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21864, 'مُضَايَقَةٌ', 'مضايقة', 'مصدر', 'ضيق', 'مضايقة', 'مضقة', 'مص. ضَايَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. ضَايَقَ). ""يَشْعُرُ بِمُضَايَقَةٍ مُسْتَمِرَّةٍ مِنْ مُنَاوِئِيهِ"" : بِإِزْعَاجٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21865, 'ضُبَاحٌ', 'ضباح', 'مصدر', 'ضبح', 'ضباح', 'ضبح', 'مص. ضَبَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضُبَاحٌ-ضُبَاحٌ [ض ب ح] (مص. ضَبَحَ). ""ضُبَاحُ الثَّعْلَبِ"" : صَوْتُهُ، عُوَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21866, 'ضَبْحٌ', 'ضبح', 'مصدر', 'ضبح', 'ضبح', 'ضبح', 'مص. ضَبَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَبْحٌ-ضَبْحٌ [ض ب ح] (مص. ضَبَحَ). ""ضَبْحُ الحَيَوَانِ"" : صَوْتُ أَجْوَافِهِ عِنْدَ عَدْوِهِ.العاديات آية 1 وَالعَادِيَاتِ ضَبْحاً . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21867, 'ضَبْرٌ', 'ضبر', 'مصدر', 'ضبر', 'ضبر', 'ضبر', 'مص. ضَبَرَ', '', '', 'مفرد', 'DnN', '', '', '"ضُبُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ضَبَرَ). 1.""أَلْقَاهُ فِي ضَبْرِهِ"" : فِي قَبْرِهِ. 2.""جَاءوا ضَبْراً"" : جَمَاعَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21868, 'ضُبُورٌ', 'ضبور', 'مصدر', '', 'ضبور', 'ضبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21869, 'تَضْخِيمٌ', 'تضخيم', 'مصدر', 'ضخم', 'تضخيم', 'تضخم', 'مص. ضَخَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضْخِيمٌ-تَضْخِيمٌ [ض خ م] (مص. ضَخَّمَ). 1.""فيِ كَلاَمِهِ تَضْخِيمٌ لِمَا حَدَثَ"" : إِعْطَاؤُهُ حَجْماً ضَخْماً، كَبِيراً. 2.""تَضْخِيمُ الحَجْمِ"" : تَكْبِيرُهُ جِدّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21870, 'ضَبْنٌ', 'ضبن', 'مصدر', 'ضبن', 'ضبن', 'ضبن', 'مص. ضَبَنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَبْنٌ-ضَبْنٌ [ض ب ن] (مص. ضَبَنَ). 1.""ضَبْنُ شَيْءٍ"" : حَمْلُهُ فَوْقَ الضِّبْنِ. 2.""مَاءٌ ضَبْنٌ"" : لاَ فَضْلَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21871, 'ضَجِيجٌ', 'ضجيج', 'مصدر', 'ضجج', 'ضجيج', 'ضجج', 'مص. ضَجَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضَجِيجٌ-ضَجِيجٌ [ض ج ج] (مص. ضَجَّ). ""عَمَّ الضَّجِيجُ القَاعَةَ"" : الضَّوْضَاءُ، الْجَلَبَةُ، الضَّجَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21872, 'ضَجَرٌ', 'ضجر', 'مصدر', 'ضجر', 'ضجر', 'ضجر', 'مص. ضَجِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَجَرٌ-ضَجَرٌ [ض ج ر] (مص. ضَجِرَ). ""يَسُودُ الضَّجَرُ حَيَاتَهُ"" : الضَّيْقُ، الْمَلَلُ، السَّأَمُ. ""يُحَدِّثُهَا عَنِ الأَمْسِ الَّذِي وَلَّى فَيَأْكُلُ قَلْبَهَا الضَّجَرُ"". (بدر شاكر السياب)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21873, 'ضَحْوٌ', 'ضحو', 'مصدر', 'ضحو', 'ضحو', 'ضح', 'مص. ضَحَا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَحْوٌ-ضَحْوٌ، ةٌ [ض ح و] (مص. ضَحَا). 1.""ضَحْوُ النَّهَارِ"": ضُحَاهُ، أَيِ ارْتِفَاعُهُ فِي مُنْتَصَفِ النَّهَارِ. 2.""ضَحْوُ الشَّمْسِ"" : اِرْتِفَاعُهَا. ""ضَحْوَةُ النَّهارِ"" ""ضَحْوَةُ الشَّمْسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21874, 'ضَحْوَةٌ', 'ضحوة', 'مصدر', 'ضحو', 'ضحوة', 'ضحة', 'مص. ضَحَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضَحْوٌ-ضَحْوٌ، ةٌ [ض ح و] (مص. ضَحَا). 1.""ضَحْوُ النَّهَارِ"": ضُحَاهُ، أَيِ ارْتِفَاعُهُ فِي مُنْتَصَفِ النَّهَارِ. 2.""ضَحْوُ الشَّمْسِ"" : اِرْتِفَاعُهَا. ""ضَحْوَةُ النَّهارِ"" ""ضَحْوَةُ الشَّمْسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21875, 'ضَحِكٌ', 'ضحك', 'مصدر', 'ضحك', 'ضحك', 'ضحك', 'مص. ضَحِكَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَحِكٌ-ضَحِكٌ [ض ح ك] (مص. ضَحِكَ). 1.""ضَجَّتِ القَاعَةُ بِالضَّحِكِ"" : إِحْدَاثُ صَوْتٍ فِيهِ قَهْقَهَةٌ تَعْبِيراً عَنِ الانْبِسَاطِ وَالسُّرُورِ. ""يَتَصَنَّعُ الضَّحِكَ"". 2.""جَعَلَ نَفْسَهُ عُرْضَةً لِلضَّحِكِ"" : لِلسُّخْرِيَةِ. ""الضَّحِكُ بِلاَ سَبَبٍ مِنْ قِلَّةِ الأَدَبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21876, 'ضَحْلٌ', 'ضحل', 'مصدر', 'ضحل', 'ضحل', 'ضحل', 'مص. ضَحَلَ', '', '', 'مفرد', 'DnN', '', '', '"أَضْحَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ضَحَلَ). 1.""لاَ يَزَالُ النَّهْرُ ضَحْلاً"" : مَاؤُهُ قَلِيلٌ. 2.""كَاتِبٌ ضَحْلُ التَّفْكِيرِ"" : لاَ عُمْقَ فِي تَفْكِيرِهِ، مُبْتَذَلٌ، سَطْحِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21877, 'أَضْحَالٌ', 'أضحال', 'مصدر', '', 'ءضحال', 'ضحل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21878, 'تَضْحِيَةٌ', 'تضحية', 'مصدر', 'ضحي', 'تضحية', 'تضحة', 'مص. ضَحَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. ضَحَّى). ""التَّضْحِيَةُ بِالنَّفْسِ"" : بَذْلُهَا فِي سَبِيلِ قَضِيَّةٍ أَوْ فِكْرَةٍ أَوْ مِنْ أَجْلِ الآخَرينَ دُونَ مُقَابِلٍ، كَمَا تَكُونُ التَّضْحِيَةُ بِالْمَالِ أَوِ العَمَلِ أَوِ الْمَصْلَحَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21879, 'تَضْرِيجٌ', 'تضريج', 'مصدر', 'ضرج', 'تضريج', 'تضرج', 'مص. ضَرَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضْرِيجٌ-تَضْرِيجٌ [ض ر ج] (مص. ضَرَّجَ). 1.""تَضْرِيجُهُ فِي الدَّمِ"" : تَلْطِيخُهُ. 2.""تَضْرِيجُ الخُيُوطِ"" : صَبْغُهَا بِالحُمْرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21880, 'ضَخَامَةٌ', 'ضخامة', 'مصدر', 'ضخم', 'ضخامة', 'ضخمة', 'مص. ضَخُمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضَخَامَةٌ-ضَخَامَةٌ [ض خ م] (مص. ضَخُمَ). ""ضَخَامَةُ الجِسْمِ"": غِلَظُهُ، اِكْتِظَاظُهُ. ""لاَ يَزْدَادُ إِلاَّ ضَخَامَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21881, 'ضَرَرٌ', 'ضرر', 'مصدر', 'ضرر', 'ضرر', 'ضر', 'مص. ضَرَّ', '', '', 'مفرد', 'DnN', '', '', '"أَضْرَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ضَرَّ).1.""أَصَابَهُ ضَرَرٌ جَسِيمٌ"" : أَذىً، ضَيْقٌ، شِدَّةٌ، مَكْرُوهٌ. 2.""تَرَكَ الفَيَضَانُ ضَرَراً بِسُكَّانِ القُرَى"" : خَسَارَةً. 3.""يُحْدِثُ التَّدْخِينُ ضَرَرًا بِجِسْمِ الإِنْسَانِ "" : آفَةً، مَرَضاً. ""وَالْمَطَرُ وَإِنْ أَفْسَدَ بَعْضَ الثِّمَارِ وَأَضَرَّ بِبَعْضِ الأَكَرَةِ فَإِنَّ نَفْعَهُ غَامِرٌ بِضَرَرِهِ"". (الجاحظ). 4.""أَخَفُّ الضَّرَرَيْنِ"" : أَخَفُّ الشَّرَّيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21882, 'أَضْرَارٌ', 'أضرار', 'مصدر', '', 'ءضرار', 'ضرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21883, 'ضَرٌّ', 'ضر', 'مصدر', 'ضرر', 'ضر', 'ضر', 'مص. ضَرَّ', '', '', 'مفرد', 'DnN', '', '', '"أَضْرَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ضَرَّ). ""مَسَّهُ الضَّرُّ"": الضَّرَرُ، الأَذَى.المائدة آية 76 قُلْ أَتَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لاَ يَمْلِكُ لَكُمْ ضَرّاً وَلاَ نَفْعاً . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21884, 'أَضْرَارٌ', 'أضرار', 'مصدر', '', 'ءضرار', 'ضرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21885, 'ضَرْبٌ', 'ضرب', 'مصدر', 'ضرب', 'ضرب', 'ضرب', 'مص. ضَرَبَ.', '', '', 'مفرد', 'DnN', '', '', '"أَضْرَابٌ:ضُرُوبٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَضْرَابٌ، ضُرُوبٌ. (مص. ضَرَبَ). 1.""أَعْيَاهُ بِالضَّرْبِ"" : بِالْجَلْدِ. 2.""هُوَ عَلَى ضَرْبِهِ"" : عَلَى شَكْلِهِ، مِثْلِهِ. 3.""ضَرْبٌ مِنَ الفَاكِهَةِ"" : الصِّنْفُ، النَّوْعُ. ""ضُرُوبُ الأَزْيَاءِ"" ""الْمُوَشَّحُ ضَرْبٌ مِنْ ضُرُوبِ الشِّعْرِ"". 4.""الضَّرْبُ فِي بَيْتِ الشِّعْرِ"" : آخِرُ تَفْعِيلَةٍ مِنَ الشَّطْرِ الثَّانِي، ج: أَضْرُبٌ. 5.""جَدْوَلُ الضَّرْبِ"" : جَدْوَلُ العَمَلِيَّاتِ الْحِسَابِيَّةِ القَائِمَةِ علىضَرْبِ عَدَدٍ في آخَرَ (4×3=12)، أي بِتَكْرَارِ عَدَدٍ فِي آخَرَ بِقَدْرِهِ. 6.""ضَرْبُ الرَّمْلِ"" : طَرِيقَةٌ لِقِرَاءةِ الْمَجْهُولِ بِاعْتِمَادِهَا عَلَى رَسْمِ خُطُوطٍ فِي الرَّمْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21886, 'أَضْرَابٌ', 'أضراب', 'مصدر', '', 'ءضراب', 'ضرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21887, 'ضُرُوبٌ', 'ضروب', 'مصدر', '', 'ضروب', 'ضرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21888, 'ضَرَبٌ', 'ضرب', 'مصدر', 'ضرب', 'ضرب', 'ضرب', 'مص. ضَرِبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَرِبٌ-ضَرِبٌ [ض ر ب] (صيغَةُ فَعِل). ""وَلَدٌ ضَرِبٌ"" : مَاهِرٌ، حَاذِقٌ فِي الضَّرْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21889, 'ضُغَاءٌ', 'ضغاء', 'مصدر', 'ضغو', 'ضغاء', 'ضغ', 'مص. ضَغَا', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"ضُغَاءٌ-ضُغَاءٌ [ض غ و] (مص. ضَغَا). ""سَمِعَ ضُغَاءً مِنْ وَرَاءِ البَابِ"" : صَوْتَ مَقْهُورٍ ذَلِيلٍ شُقَّ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21890, 'تَضْرِيرٌ', 'تضرير', 'مصدر', 'ضرر', 'تضرير', 'تضرر', 'مص. ضَرَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضْرِيرٌ-تَضْرِيرٌ [ض ر ر] (مص. ضَرَّرَ). ""لَمْ يَكُنْ يَقْصِدُ التَّضْرِيرَ بِهِ فِي مَعِيشَتِهِ"" : إِضْرارٌ، إِلْحَاقَ الأَذَى بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21891, 'ضُرَاطٌ', 'ضراط', 'مصدر', 'ضرط', 'ضراط', 'ضرط', 'مص. ضَرَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضُرَاطٌ-ضُرَاطٌ [ض ر ط] (مص. ضَرَطَ). ""صَدَرَ عَنْهُ ضُرَاطٌ"" : رِيحٌ تَخْرُجُ مِنَ الاِسْتِ مَعَ صَوْتٍ وَرَائِحَةٍ كَرِيهَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21892, 'ضَرْعٌ', 'ضرع', 'مصدر', 'ضرع', 'ضرع', 'ضرع', 'مص ضَرَعَ', '', '', 'مفرد', 'DnN', '', '', '"ضُرُوعٌ"', '', 'R', '', '', '', '', '', '', '"(مص ضَرَعَ). 1.""تَحْلُبُ ضَرْعَهَا"" : مَدَرُّ اللَّبَنِ لِلشَّاةِ وَالبَقَرِ وَهُوَ مَا يُقَابِلُ ثَدْيَ الْمَرْأَةِ. 2.""الزَّرْعُ وَالضَّرْعُ"" : الزِّرَاعَةُ وَالْمَاشِيَةُ. ""أَتْلَفَ الفَيَضَانُ الزَّرْعَ وَالضَّرْعَ"" ""مَالَهُ زَرْعٌ وَلاَ ضَرْعٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21893, 'ضُرُوعٌ', 'ضروع', 'مصدر', '', 'ضروع', 'ضرع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21894, 'ضَرَاعَةٌ', 'ضراعة', 'مصدر', 'ضرع', 'ضراعة', 'ضرعة', 'مص. ضَرَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضَرَاعَةٌ-ضَرَاعَةٌ [ض ر ع] (مص. ضَرَعَ). 1.""ضَرَاعَةُ جِسْمٍ"": نَحَافَتُهُ، ضَعْفُهُ. 2.""رَفَعَ أَكُفَّ الضَّرَاعَةِ إِلَى السَّمَاءِ"" : التَّوَسُّلُ، الْخُشُوعُ. ""يَسْتَقْبِلُ القَلْبُ كُلَّ مَا أُلْقِيَ إِلَيْهِ بِحُسْنِ الإِصْغَاءِ وَالضَّرَاعَةِ"". (الغزالي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21895, 'تَضْرِيمٌ', 'تضريم', 'مصدر', 'ضرم', 'تضريم', 'تضرم', 'مص. ضَرَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضْرِيمٌ-تَضْرِيمٌ [ض ر م] (مص. ضَرَّمَ). ""تَضْرِيمُ النَّارِ فِي الحَطَبِ"" : إِضْرامُها، إِشْعَالُهَا، إِيقَادُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21896, 'ضَرَاوَةٌ', 'ضراوة', 'مصدر', 'ضرو', 'ضراوة', 'ضرة', 'مص. ضَرِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضَرَاوَةٌ-ضَرَاوَةٌ [ض ر و] (مص. ضَرِيَ). 1.""وَاجَهَهُمُ الْجَيْشُ بِضَرَاوَةٍ"" : بِبَسالَةٍ، بِشَجاعَةٍ . 2.""بَلَغَتْ ضَرَاوَةُ الْحَرْبِ أَقْصَاهَا"" : حِدَّتُها ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21897, 'تَضْعِيفٌ', 'تضعيف', 'مصدر', 'ضعف', 'تضعيف', 'تضعف', 'مص. ضَعَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضْعِيفٌ-تَضْعِيفٌ [ض ع ف] (مص. ضَعَّفَ). 1.""حَاوَلَ تَضْعِيفَ عَدُوِّهِ"" : تَصْيِيرَهُ ضَعِيفاً. 2.""تَضْعِيفُ حَدِيثٍ"" : نِسْبَتُهُ إِلىَ الضُّعْفِ. 3.""تَضْعِيفُ الجُهُودِ"" : زِيَادَتُها. 4.""تَضْعِيفُ الحَرْفِ"" : وُجُودُ حَرْفَيْنِ مِنْ جِنْسٍ وَاحِدٍ فِي الفِعْلِ الْمُجَرَّدِ نَحْوُ: ""شَدَّ"" (ش د د)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21898, 'تضاعيف', 'تضاعيف', 'مصدر', '', 'تضاعيف', 'تضعف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21899, 'ضَغْثٌ', 'ضغث', 'مصدر', 'ضغث', 'ضغث', 'ضغث', 'مص. ضَغَثَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَغْثٌ-ضَغْثٌ [ض غ ث] (مص. ضَغَثَ). ""كَانَ كَلاَمُهُ مُجَرَّدَ ضَغْثٍ"" : أَيْ لاَ خَبَرَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21900, 'ضَغْطٌ', 'ضغط', 'مصدر', 'ضغط', 'ضغط', 'ضغط', 'مص. ضَغَطَ', '', '', 'مفرد', 'DnN', '', '', '"ضُغُوطٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ضَغَطَ). 1.""تَعَرَّضَ لِلضَّغْطِ"" : لِلإِكْرَاهِ. ""اِعْتَرَفَ تَحْتَ الضَّغْطِ"". 2.""الضَّغْطُ الْجَوِّيُّ"" : مَا يُحْدِثُهُ الْهَوَاءُ عِنْدَ تَجَمُّعِهِ فِي مَوْضِعٍ مَّا. 3.""ضَغْطُ الدَّمِ"" : مَا "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21901, 'ضُغُوطٌ', 'ضغوط', 'مصدر', '', 'ضغوط', 'ضغط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21902, 'ضَغْمٌ', 'ضغم', 'مصدر', 'ضغم', 'ضغم', 'ضغم', 'مص. ضَغَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَغْمٌ-ضَغْمٌ [ض غ م] (مص. ضَغَمَ). ""ضَغْمُ الفَقْرِ"" : عَضُّهُ. ""أَعَاذَكُمُ اللَّهُ مِنْ جُرْحِ الدَّهْرِ وَضَغْمِ الفَقْرِ"" ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21903, 'ضَفٌّ', 'ضف', 'مصدر', 'ضفف', 'ضف', 'ضف', 'مص. ضَفَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَفٌّ-ضَفٌّ [ض ف ف] (مص. ضَفَّ). ""رَجُلٌ ضَفُّ الحَالِ"" : رَقِيقُهَا، سَيِّئُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21904, 'ضَفٌّ', 'ضف', 'مصدر', 'ضفف', 'ضف', 'ضف', 'مص. ضَفَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَفَّ-ضَفَّ [ض ف ف] (ف : ثلا، لازمتع. م بحرف) . ضَفَفْتُ، أَضُفُّ، ضُفَّ، مص. ضَفٌّ. 1.""ضَفَّ النَّاسُ عَلَى الْمَتْجَرِ"" : اِزْدَحَمُوا. 2.""ضَفَّ الْمُصْطَلِي "" : ضَمَّ أَصَابِعَهُ فَقَرَّبَهَا إِلَى النَّارِ. 3.""ضَفَّ الشَّيْءَ"" : جَمَعَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21905, 'ضَفْرٌ', 'ضفر', 'مصدر', 'ضفر', 'ضفر', 'ضفر', 'مص. ضَفَرَ', '', '', 'مفرد', 'DnN', '', '', '"أَضْفَارٌ:ضُفُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ضَفَرَ). 1.""جَعَلَتْ مِنْ شَعْرِهَا أَضْفَاراً"" : خُصَلاً. (مف. خُصْلَةٌ) : كُلُّ خُصْلَةِ شَعْرٍ تُضْفَرُ عَلَى حِدَةٍ. 2.""ضَفْرُ الحَبْلِ"" : فَتْلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21906, 'أَضْفَارٌ', 'أضفار', 'مصدر', '', 'ءضفار', 'ضفر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21907, 'ضُفُورٌ', 'ضفور', 'مصدر', '', 'ضفور', 'ضفر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21908, 'ضَلاَلَةٌ', 'ضلالة', 'مصدر', 'ضلل', 'ضلالة', 'ضللة', 'مص. ضَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. ضَلَّ). ن. ضَلاَل. ""الشَّرِيعَةُ قَدْ دُنِّسَتْ بِالجَهَالاَتِ وَاخْتَلَطَتْ بِالضَّلاَلاَتِ"". (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21909, 'ضَلاَلٌ', 'ضلال', 'مصدر', 'ضلل', 'ضلال', 'ضلل', 'مص. ضَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"ضَلاَلٌ-ضَلاَلٌ [ض ل ل] (مص. ضَلَّ). 1.""هُوَ فِي ضَلاَلٍ مُبِينٍ"" : بَعِيدٌ عَنِ الطَّرِيقِ الْمُسْتَقِيمِ، فِي غَيٍّ. 2.""هُوَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21910, 'تَضْلِيلٌ', 'تضليل', 'مصدر', 'ضلل', 'تضليل', 'تضلل', 'مص. ضَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضْلِيلٌ-تَضْلِيلٌ [ض ل ل] (مص. ضَلَّلَ). ""سَعَى إِلَى "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21911, 'ضَمٌّ', 'ضم', 'مصدر', 'ضمم', 'ضم', 'ضم', 'مص. ضَمَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَمٌّ-ضَمٌّ [ض م م] (مص. ضَمَّ). 1.""قَامَ بِضَمِّ الوَثَائِقِ إِلَى بَعْضِهَا"" : بِجَمْعِهَا. 2.""حَرَكَةُ الضَّمِّ"" : حَرَكَةُ الرَّفْعِ ( ـُ ) سُمِّيَتْ بِذَلِكَ إِذْ تُضَمُّ مَعَهَا الشَّفَةُ عِنْدَ النُّطْقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21912, 'تَضْمِيدٌ', 'تضميد', 'مصدر', 'ضمد', 'تضميد', 'تضمد', 'مص. ضَمَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضْمِيدٌ-تَضْمِيدٌ [ض م د] (مص. ضَمَّدَ). ""تَضْمِيدُ الجُرْحِ"" : شَدُّهُ وَلَفُّهُ بِضِمَادَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21913, 'ضِمَادٌ', 'ضماد', 'مصدر', 'ضمد', 'ضماد', 'ضمد', 'مص. ضَمَدَ', '', '', 'مفرد', 'DnN', '', '', '"أَضْمِدَةٌ:ضَمَائِدُ"', '', 'R', '', '', '', '', '', '', '"(مص. ضَمَدَ). 1.""شَدَّ الْجُرْحَ بِالضِّمَادِ"" : خِرْقَةٌ بَيْضَاءُ يُشَدُّ بِهَا العُضْوُ الْمَجْرُوحُ. 2.""وَضَعَ الضِّمَادَ عَلَى الْجُرْحِ"" : الدَّوَاءَ الَّذِي يُوضَعُ عَلَى الْجُرْحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21914, 'أَضْمِدَةٌ', 'أضمدة', 'مصدر', '', 'ءضمدة', 'ضمدة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21915, 'ضَمَائِدُ', 'ضمائد', 'مصدر', '', 'ضماءد', 'ضمد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21916, 'ضَمْدٌ', 'ضمد', 'مصدر', 'ضمد', 'ضمد', 'ضمد', 'مص. ضَمَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَمْدٌ-ضَمْدٌ [ض م د] (مص. ضَمَدَ).""ضَمْدُ الْجُرْحِ"" : وَضْعُ ضِمَادَةٍ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21917, 'ضَمَدٌ', 'ضمد', 'مصدر', 'ضمد', 'ضمد', 'ضمد', 'مص. ضَمِدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَمَدٌ-ضَمَدٌ [ض م د] (مص. ضَمِدَ). 1.""لَمْ يَسْتَطِعْ إِخْفَاءَ ضَمَدِهِ"" : حِقْدِهِ، غَضَبِهِ الشَّدِيدِ. 2.""أَلْحَقَ بِهِ ضَمَداً"" : ظُلْماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21918, 'ضُمُورٌ', 'ضمور', 'مصدر', 'ضمر', 'ضمور', 'ضمر', 'مص. ضَمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضُمُورٌ-ضُمُورٌ [ض م ر] (مص. ضَمَرَ). ""ضُمُورُ الْجِسْمِ"" : نَحَافَتُهُ، ضَعْفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21919, 'ضَمْضَمَةٌ', 'ضمضمة', 'مصدر', 'ضمضم', 'ضمضمة', 'ضمضمة', 'مص. ضَمْضَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضَمْضَمَةٌ-ضَمْضَمَةٌ [ض م ض م] (مص. ضَمْضَمَ). ""ضَمْضَمَةُ أَسَدٍ"" : صَوْتُهُ، زَئِيرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21920, 'تَضْمِينٌ', 'تضمين', 'مصدر', 'ضمن', 'تضمين', 'تضمن', 'مص. ضَمَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضْمِينٌ-تَضْمِينٌ [ض م ن] (مص. ضَمَّنَ). 1.""تَضْمِينُ الخُطْبَةِ بِأَحَادِيثَ نَبَوِيَّةٍ"" : إِدْرَاجُ أَحَادِيثَ نَبَوِيَّةٍ فِيهَا. 2.""التَّضْمِينُ فِي النَّحْوِ"" : أَنْ يُضَمَّنَ لَفْظٌ مَعْنَى لَفْظٍ آخَرَ، أَيْ إِيقَاعُ لَفْظٍ مَوْقِعَ غَيْرِهِ، وَمُعَامَلَتُهُ مُعَامَلَتَهُ لِتَضَمُّنِهِ مَعْنَاهُ وَاشْتِمَالِه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21921, 'ضَمَانٌ', 'ضمان', 'مصدر', 'ضمن', 'ضمان', 'ضمن', 'مص. ضَمِنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. ضَمِنَ). 1.""ضَمَانٌ مُحَدَّدٌ"" : كَفَالَةٌ، اِلْتَزَامٌ. ""إِنَّ القَانُونَ حِمَايَةٌ وَضَمَانٌ لِحُقُوقِ الْجَمِيعِ"". 2.""الضَّمَانُ الاجْتِمَاعِيُّ"" : مُؤَسَّسَةٌ اجْتِمَاعِيَّةٌ يَتِمُّ الاشْتِرَاكُ فِيهَا لِتَأْمِينِ الْمُسَاعَدَةِ وَالْمَعُونَةِ عِنْدَ الْحَاجَةِ فِي حَالَةِ الْمَرَضِ أَوِ التَّقَاعُدِ. 3.""وَافَقَ عَلَى شُرُوطِ الضَّمَانَةِ"" : وَثِيقَةٌ يَضْمَنُ بِهَا شَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21922, 'ضَمَانَةٌ', 'ضمانة', 'مصدر', 'ضمن', 'ضمانة', 'ضمنة', 'مص. ضَمِنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. ضَمِنَ). 1.""ضَمَانٌ مُحَدَّدٌ"" : كَفَالَةٌ، اِلْتَزَامٌ. ""إِنَّ القَانُونَ حِمَايَةٌ وَضَمَانٌ لِحُقُوقِ الْجَمِيعِ"". 2.""الضَّمَانُ الاجْتِمَاعِيُّ"" : مُؤَسَّسَةٌ اجْتِمَاعِيَّةٌ يَتِمُّ الاشْتِرَاكُ فِيهَا لِتَأْمِينِ الْمُسَاعَدَةِ وَالْمَعُونَةِ عِنْدَ الْحَاجَةِ فِي حَالَةِ الْمَرَضِ أَوِ التَّقَاعُدِ. 3.""وَافَقَ عَلَى شُرُوطِ الضَّمَانَةِ"" : وَثِيقَةٌ يَضْمَنُ بِهَا شَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21923, 'ضَنَانَةٌ', 'ضنانة', 'مصدر', 'ضنن', 'ضنانة', 'ضننة', 'مص. ضَنَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضَنَانَةٌ-ضَنَانَةٌ [ض ن ن] (مص. ضَنَّ). 1.""أَخَذْتُ الأَمْرَ بِضَنَانَتِهِ"" : أَيْ بِطَرَاوَتِهِ، لَمْ يَتَغَيَّرْ. 2.""هَجَمَ عَلَى القَوْمِ وَهُمْ بِضَنَانَتِهِمْ"" : لَمْ يَتَفَرَّقُوا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21924, 'ضَنٌّ', 'ضن', 'مصدر', 'ضنن', 'ضن', 'ضن', 'مص. ضَنَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَنٌّ-ضَنٌّ [ض ن ن] (مص. ضَنَّ). : مَا يُضَنُّ بِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21925, 'ضَنىً', 'ضنى', 'مصدر', 'ضنو', 'ضنى', 'ضن', 'مص. ضَنَا', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"ضَنـىً-ضَنـىً [ض ن و] (مص. ضَنَا). 1.""يُوجَدُ فِي ضَنـىً"" : فِي هُزَالٍ شَدِيدٍ. 2.""يُعَانِي مِنَ الضَّنَى"" : مِنَ الفَقْرِ الشَّدِيدِ، مِنَ الْمَرَضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21926, 'ضَنْكٌ', 'ضنك', 'مصدر', 'ضنك', 'ضنك', 'ضنك', 'مص. ضَنَكَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَنْكٌ-ضَنْكٌ [ض ن ك] (مص. ضَنَكَ).""يَعيشُ حَياةَ ضَنْكٍ"" : ضَيْقٍ.طه آية 124 وَمَنْ أَعْرَضَ عَنْ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنْكاً . (قرآن) ""لَيْسَ لَهُ بِالضَّنْكِ وَالضَّيْقِ عَهْدٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21927, 'تَضْوِئَةٌ', 'تضوئة', 'مصدر', 'ضوأ', 'تضوءة', 'تضة', 'مص. ضَوَّأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَضْوِئَةٌ-تَضْوِئَةٌ [ض و أ] (مص. ضَوَّأَ). ""تَضْوِئَةُ البَيْتِ"" : إِضَاءَتُهُ، تَنْوِيرُهُ بِالضَّوْءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21928, 'ضَآلَةٌ', 'ضآلة', 'مصدر', 'ضأل', 'ضءءلة', 'ضآلة', 'مص. ضَؤُلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ضَآلَةٌ-ضَآلَةٌ [ض أ ل] (مص. ضَؤُلَ). ""عَلَى ضَآلَتِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21929, 'تَضْيِيعٌ', 'تضييع', 'مصدر', 'ضيع', 'تضييع', 'تضع', 'مص. ضَيَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضْيِيعٌ-تَضْيِيعٌ [ض ي ع] (مص. ضَيَّعَ). ""تَضْيِيعُ الأَمَانَةِ"" : إِضَاعَتُهَا. ""لاَ حَقَّ لَهُ فِي تَضْيِيعِ الحُقُوقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21930, 'تَضْيِيفٌ', 'تضييف', 'مصدر', 'ضيف', 'تضييف', 'تضف', 'مص. ضَيَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضْيِيفٌ-تَضْيِيفٌ [ض ي ف] (مص. ضَيَّفَ). ""تَضْيِيفُ الرَّجُلِ"": إِنْزَالُهُ ضَيْفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21931, 'تَضْيِيقٌ', 'تضييق', 'مصدر', 'ضيق', 'تضييق', 'تضق', 'مص. ضَيَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَضْيِيقٌ-تَضْيِيقٌ [ض ي ق] (مص. ضَيَّقَ) 1.""التَّضْيِيقُ عَلَى النَّفْسِ"" : التَّقْتِيرُ عَلَيْهَا. 2.""تَضْيِيقُ الخِنَاقِ عَلَى الرَّجُلِ"" : التَّشْدِيدُ فِي خَنْقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21932, 'طِيبٌ', 'طيب', 'مصدر', 'طيب', 'طيب', 'طب', 'مص. طَابَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَيِّبٌ-طَيِّبٌ، ةٌ [ط ي ب] (صف). 1.""شَابٌّ طَيِّبُ الرَّائِحَةِ"" : عَطِرُ الرَّائِحَةِ. 2.""يَسْتَنْشِقُ رَائِحَةً طَيِّبَةً"" : أَيْ رَائِحَةً عَطِرَةً. 3.""رَجُلٌ طَيِّبُ النَّفْسِ"" : صَافِي القَلْبِ صَادِقُ النِّيَّةِ، دَمِثُ الأَخْلاَقِ. 4.""نَفْسٌ طَيِّبَةٌ"" : رَاضِيَةٌ. 5.""طَيِّبُ الْخُلُقِ"" : حَسَنُ الطَّبْعِ. 6.""شَرِيفٌ طَيِّبُ العِرْقِ"" : مِنْ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21933, 'طِيبَةٌ', 'طيبة', 'مصدر', 'طيب', 'طيبة', 'طبة', 'مص. طَابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَيِّبٌ-طَيِّبٌ، ةٌ [ط ي ب] (صف). 1.""شَابٌّ طَيِّبُ الرَّائِحَةِ"" : عَطِرُ الرَّائِحَةِ. 2.""يَسْتَنْشِقُ رَائِحَةً طَيِّبَةً"" : أَيْ رَائِحَةً عَطِرَةً. 3.""رَجُلٌ طَيِّبُ النَّفْسِ"" : صَافِي القَلْبِ صَادِقُ النِّيَّةِ، دَمِثُ الأَخْلاَقِ. 4.""نَفْسٌ طَيِّبَةٌ"" : رَاضِيَةٌ. 5.""طَيِّبُ الْخُلُقِ"" : حَسَنُ الطَّبْعِ. 6.""شَرِيفٌ طَيِّبُ العِرْقِ"" : مِنْ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21934, 'طِبَاقٌ', 'طباق', 'مصدر', 'طبق', 'طباق', 'طبق', 'مص. طَابَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طِبَاقٌ-طِبَاقٌ [ط ب ق] (مص. طَابَقَ). 1.""هَذَا طِبَاقُ هَذَا"" : مُطَابِقٌ لَهُ. 2.""الطِّبَاقُ فِي البَدِيعِ"" : الْجَمْعُ بَيْنَ مَعْنَيَيْنِ مُتَقَابِلَيْنِ أَوْ مُتَضَادَّيْنِ: ""هُوَ حَيٌّ وَمَيِّتٌ"".الكهف آية 18وَتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21935, 'مُطَابَقَةٌ', 'مطابقة', 'مصدر', 'طبق', 'مطابقة', 'مطبقة', 'مص. طَابَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُطَابَقَةٌ-مُطَابَقَةٌ [ط ب ق] (مص. طَابَقَ). 1.""مُطَابَقَةُ الأَفْعَالِ لِلْأَقْوَالِ"" : تَوَافُقُهَا. 2.""الْمُطَابَقَةُ فِي اللُّغَةِ"" : تَوَافُقٌ بَيْنَ جُزْأَيْنِ مُتَرَابِطَيْنِ مِنْ أَجْزَاءِ الكَلاَمِ فِي الإِفْرَادِ وَالتَّثْنِيَةِ وَالجَمْعِ وَالتَّذْكِيرِ وَالتَّأْنِيثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21936, 'طَيَرَانٌ', 'طيران', 'مصدر', 'طير', 'طيران', 'طرن', 'مص. طَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَيَرَانٌ-طَيَرَانٌ [ط ي ر] (مص. طَارَ). 1.""يَشْتَغِلُ فِي شَرِكَةِ الطَّيَرَانِ"" : الشَّرِكَةُ الْمُهْتَمَّةُ بِالْمُوَاصَلاَتِ الْجَوِّيَّةِ. 2.""خُطُوطُ الطَّيَرَانِ الْوَطَنِيِّ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21937, 'طَيْرٌ', 'طير', 'مصدر', 'طير', 'طير', 'طر', 'مص. طَارَ', '', '', 'مفرد', 'DnN', '', '', '"طُيُورٌ:أَطْيَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَارَ). 1. : اِسْمُ جَمْعٍ لِمَا يَطِيرُ فِي الْهَوَاءِ، جَمْعُ طَائِرٍ وَيُطْلَقُ أَيْضاً عَلَى الوَاحِدِ.الواقعة آية 21 وَلَحْمِ طَيْرٍ مِمَّا يَشْتَهُونَ (قرآن) ""مِثْلُ النَّعَامَةِ، لاَ طَيْرٌ وَلاَ جَمَلٌ"" : أَيْ أَنَّهَا لَيْسَتْ بِطَائِرٍ وَلاَ ج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21938, 'طُيُورٌ', 'طيور', 'مصدر', '', 'طيور', 'طر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21939, 'أَطْيَارٌ', 'أطيار', 'مصدر', '', 'ءطيار', 'طر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21940, 'مُطَارَدَةٌ', 'مطاردة', 'مصدر', 'طرد', 'مطاردة', 'مطردة', 'مص. طَارَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُطَارَدَةٌ-مُطَارَدَةٌ [ط ر د] (مص. طَارَدَ). ""مُطَارَدَةُ الْمُجْرِمِينَ"": مُلاَحَقَتُهُمْ وَالسَّيْرُ فِي أَثَر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21941, 'طَوْسٌ', 'طوس', 'مصدر', 'طوس', 'طوس', 'طس', 'مص طاسَ', '', '', 'مفرد', 'DnN', '', '', '"أَطْواسٌ"', '', 'R', '', '', '', '', '', '', '"(مص طاسَ). 1.""ظَهَرَ الطَّوْسُ وَسَطَ الضَّبابِ"" : القَمَرُ. 2.""طَوْسُ الوَجْهِ"" : حُسْنُهُ، نَضَارَتُهُ. 3.""طَوْسُ النَّباتِ"" : وَطْؤُهُ، دَوْسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21942, 'أَطْواسٌ', 'أطواس', 'مصدر', '', 'ءطواس', 'طس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21943, 'طَيْشٌ', 'طيش', 'مصدر', 'طيش', 'طيش', 'طش', 'مص. طَاشَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَيْشٌ-طَيْشٌ [ط ي ش] (مص. طَاشَ).""وَلَدٌ بِهِ طَيْشٌ"" : بِهِ نَزَقٌ وَخِفَّةُ عَقْلٍ. ""هَذَا مِنْ طَيْشِ أَيَّامِ الشَّبَابِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21944, 'طَوْعٌ', 'طوع', 'مصدر', 'طوع', 'طوع', 'طع', 'مص. طَاعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَوْعٌ-طَوْعٌ [ط و ع] (مص. طَاعَ). 1.""هُوَ طَوْعُ أَمْرِكَ"" : تَحْتَ تَصَرُّفِكَ، مُنْقَادٌ لَكَ. ""كَانَ عَلَى الدَّوَامِ طَوْعَ يَدَيْهِ"": مُنْقَاداً لَهُ. 2.""طَوْعاً أَوْ كَرْهاً"" : شَاءَ أَمْ أَبَى... 3.""فَرَسٌ طَوْعُ العِنَانِ"" : سَلِسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21945, 'طَوَافٌ', 'طواف', 'مصدر', 'طوف', 'طواف', 'طف', 'مص. طَافَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَوَّافٌ-طَوَّافٌ [ط و ف] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ طَوَّافٌ"" : كَثِيرُ الطَّوَافِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21946, 'طَيْفٌ', 'طيف', 'مصدر', 'طيف', 'طيف', 'طف', 'مص. طَافَ', '', '', 'مفرد', 'DnN', '', '', '"أَطْيَافٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَافَ). 1.""رَأَى طَيْفاً هَاتِفاً فِي مَنَامِهِ"" : الْخَيَالُ الطَّائِفُ الَّذِي يَرَاهُ النَّائِمُ. لَمْ يَطُلْ لَيْلِي وَلَكِنْ لَـمْ أَنَـمْ*وَنَفَى عَنِّـي الكَـرَى طَيْفٌ أَلَـمّْ (بشار بن بُرد). 2.""أَلْوَانُ الطَّيْفِ"" : هِيَ الأَلْوَانُ البَارِزَةُ عِنْدَ تَحْلِيلِ الضَّوْءِ، أَيِ الأَحْمَرُ فَالأَصْفَرُ فَالأَزْرَقُ فَالنِّيلِيُّ فَالبَنَفْسَجِيُّ. 3.""طَيْفُ قَوْسِ قُزَحٍ"" : شَتَّى أَلْوَانِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21947, 'أَطْيَافٌ', 'أطياف', 'مصدر', '', 'ءطياف', 'طف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21948, 'طَاقَةٌ', 'طاقة', 'مصدر', 'طوق', 'طاقة', 'طقة', 'مص. طَاقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. طَاقَ). 1.""لَهُ طَاقَةٌ كَبِيرَةٌ"" : قُدْرَةٌ، قُوَّةٌ. ""لاَ طَاقَةَ لَهُ"" ""يَشْتَغِلُ عَلَى قَدْرِ طَاقَتِهِ""البقرة آية 286 رَبَّنَا وَلاَ تُحَمِّلْنَا مَا لاَ طَاقَةَ لَنَا بِه (قرآن) . 2.""لاَ تَتَحَمَّلُ طَاقَةُ جِسْمِهِ كُلَّ هَذَا الإِرْهَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21949, 'طُولٌ', 'طول', 'مصدر', 'طول', 'طول', 'طل', 'مص. طَالَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طُولٌ-طُولٌ [ط و ل] (مص. طَالَ). 1.""بَلَغَ طُولُ الغُرْفَةِ خَمْسَةَ أَمْتَارٍ"" : مِقْدَارُ الْمَسَافَةِ بَيْنَ طَرَفَيْ خَطٍّ مُسْتِقِيمٍ. ""لِلْمُسْتَطِيلِ طُولاَن وَعَرْضَان"". 2.""جَالَ فِي طُولِ البِلاَدِ وَعَرْضِهَا"": فِي كُلِّ جِهَاتِ البِلاَدِ وَأَمَاكِنِهَا. ""طُولُهَا وَعَرْضُهَا"". 3.""أَتَّفِقُ مَعَكَ عَلَى طُولِ الْخَطِّ"" : أَتَّفِقُ مَعَكَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21950, 'مُطَالَبَةٌ', 'مطالبة', 'مصدر', 'طلب', 'مطالبة', 'مطلبة', 'مص. طَالَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُطَالَبَةٌ-مُطَالَبَةٌ [ط ل ب] (مص. طَالَبَ). ""جَدَّدَ الْمُطَالَبَةَ بِحُقُوقِهِ"" : الْمَسْعَى، الإِلْحَاحُ فِي الطَّلَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21951, 'مُطَالَعَةٌ', 'مطالعة', 'مصدر', 'طلع', 'مطالعة', 'مطلعة', 'مص. طَالَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُطَالَعَةٌ-مُطَالَعَةٌ [ط ل ع] (مص. طَالَعَ). 1.""مُطَالَعَةُ الكُتُبِ"": قِرَاءتُهَا. 2.""كِتَابُ الْمُطَالَعَةِ"" : كِتَابُ القِرَاءةِ. 3.""قَاعَةُ الْمُطَالَعَةِ"" : قَاعَةُ قِرَاءةِ الكُتُبِ. 4.""مُطَالَعَةُ النِّيَابَةِ العَامَّةِ"" : الْمُرَافَعَةُ، صَكُّ الاتِّهَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21952, 'طَبٌّ', 'طب', 'مصدر', 'طبب', 'طب', 'طب', 'مص. طَبَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَبٌّ-طَبٌّ [ط ب ب] (مص. طَبَّ). 1.""صَانِعٌ طَبٌّ"" : مَاهِرٌ، حَاذِقٌ. 2.""أَتَى الشَّيْءَ طَبّاً"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21953, 'طِبٌّ', 'طب', 'مصدر', 'طبب', 'طب', 'طب', 'مص. طَبَّ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"طُبٌّ-طُبٌّ [ط ب ب]. 1.""أَتَى الشَّيْءَ طُبّاً"" : مَهَارَةً، حِذْقاً. 2.""عَمِلَ لَهَا الطُّبَّ"" : السِّحْرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21954, 'تَطْبِيبٌ', 'تطبيب', 'مصدر', 'طبب', 'تطبيب', 'تطبب', 'مص. طَبَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْبِيبٌ-تَطْبِيبٌ [ط ب ب] (مص. طَبَّبَ). ""تَطْبِيبُ الْمَرِيضِ"": مُعَالَجَتُهُ، مُدَاوَاتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21955, 'طَبْخٌ', 'طبخ', 'مصدر', 'طبخ', 'طبخ', 'طبخ', 'مص. طَبَخَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَبْخٌ-طَبْخٌ [ط ب خ] (مص. طَبَخَ). ""طَبْخُ الطَّعَامِ"" : إِعْدَادُهُ وَتَهْيِيئُهُ لِلأَكْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21956, 'طَبْطَبَةٌ', 'طبطبة', 'مصدر', 'طبطب', 'طبطبة', 'طبطبة', 'مص. طَبْطَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَبْطَبَةٌ-طَبْطَبَةٌ [ط ب ط ب] (مص. طَبْطَبَ). 1.""طَبْطَبَةُ الْمَاءِ"": خَرِيرُهُ، صَوْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21957, 'تَطْبِيعٌ', 'تطبيع', 'مصدر', 'طبع', 'تطبيع', 'تطبع', 'مص. طَبَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْبِيعٌ-تَطْبِيعٌ [ط ب ع] (مص. طَبَّعَ). ""دَعَا إِلى تَطْبِيعِ العَلاَقَاتِ مَعَ العَدُوِّ"" : إِلى جَعْلِهَا عَادِيَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21958, 'طِبَاعَةٌ', 'طباعة', 'مصدر', 'طبع', 'طباعة', 'طبعة', 'مص. طَبَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طِبَاعَةٌ-طِبَاعَةٌ [ط ب ع] (مص. طَبَعَ). 1.""يُتْقِنُ فَنَّ الطِّبَاعَةِ"": حِرْفَة الطَّبَّاعِ. 2.""اِنْتَشَرَتْ دُورُ الطِّبَاعَةِ فِي البِلاَدِ"" : الدُّورُ الَّتِي تَطْبَعُ الكُتُبَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21959, 'طَبْعٌ', 'طبع', 'مصدر', 'طبع', 'طبع', 'طبع', 'مص. طَبَعَ', '', '', 'مفرد', 'DnN', '', '', '"طِبَاعٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَبَعَ). 1.""تَمَّ طَبْعُ الكِتَابِ بِالْمَطْبَعَةِ الرَّسْمِيَّةِ"" : إِنْجَازُهُ عَلَى الوَرَقِ بِأَحْرُفٍ مَطْبَعِيَّةٍ. 2.""الكِتَابُ تَحْتَ الطَّبْعِ"" : عَمَلِيَّةُ إِنْجَازِهِ بِأَحْرُفٍ مَطْبَعِيَّةٍ جَارِيَةٍ. ""مَجَلَّةٌ أَنِيقَةُ الطَّبْعِ"". 3.""حُقُوقُ الطَّبْعِ مَحْفُوظَةٌ"" : حُقُوقُ إِعَادَةِ النَّشْرِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21960, 'طِبَاعٌ', 'طباع', 'مصدر', '', 'طباع', 'طبع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21961, 'طَبَعٌ', 'طبع', 'مصدر', 'طبع', 'طبع', 'طبع', 'مص. طَبِعَ', '', '', 'مفرد', 'DnN', '', '', '"أَطْبَاعٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَبِعَ). 1.""عَلاَ الطَّبَعُ الْمَعْدِنَ"" : عَلاَهُ الصَّدَأُ. 2.""فِي ثَوْبِهِ طَبَعٌ"" : وَسَخٌ. 3.""بِهِ طَبَعٌ"" : عَيْبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21962, 'أَطْبَاعٌ', 'أطباع', 'مصدر', '', 'ءطباع', 'طبع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21963, 'تَطْبِيقٌ', 'تطبيق', 'مصدر', 'طبق', 'تطبيق', 'تطبق', 'مص. طَبَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَطْبِيقٌ-تَطْبِيقٌ [ط ب ق] (مص. طَبَّقَ). 1.""حَاوَلَ تَطْبِيقَ القَاعِدَةِ"" : تَجْرِيبَهَا، نَقْلَهَا إِلىَ مَجَالِ التَّنْفِيذِ. ""نَظَرِيَّةٌ غَيْرُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21964, 'طَبَقٌ', 'طبق', 'مصدر', 'طبق', 'طبق', 'طبق', 'مص. طَبَقَ', '', '', 'مفرد', 'DnN', '', '', '"أَطْبَاقٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. طَبَقَ). 1.""أَحْكَمَ سَدَّ طَبَقِ الإِنَاءِ"" : غِطَاء الإِنَاءِ. 2.""قَدَّمَ لَهُ طَبَقاً مِنَ الفَوَاكِهِ"" : صَحْناً، وِعَاءً خَاصّاً بِالفَوَاكِهِ. 3.""يُرِيدُ أَنْ أُقَدِّمَ لَهُ الْحَلَّ عَلَى طَبَقٍ مِنْ فِضَّةٍ"" : أَنْ أُقَدِّمَ لَهُ الْحَلَّ دُونَ تَعَبٍ، دُونَ جَهْدٍ. 4.""طَبَقُ الْحَنَكِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21965, 'أَطْبَاقٌ', 'أطباق', 'مصدر', '', 'ءطباق', 'طبق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21966, 'تَطْبِيلٌ', 'تطبيل', 'مصدر', 'طبل', 'تطبيل', 'تطبل', 'مص. طَبَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْبِيلٌ-تَطْبِيلٌ [ط ب ل] (مص. طَبَّلَ). 1.""طَبَّلَ الطَّابِلُ تَطْبِيلاً"" : ضَرَبَ الطَّبْلَ ضَرْباً. 2.""أَرَادَ التَّطْبِيلَ لَهُ"" : تَمَلُّقَهُ، التَّقَرُّبَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21967, 'طَبْلٌ', 'طبل', 'مصدر', 'طبل', 'طبل', 'طبل', 'مص. طَبَلَ', '', '', 'مفرد', 'DnN', '', '', '"طُبُولٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَبَلَ). : آلَةٌ مُوسِيقِيَّةٌ إِيقَاعِيَّةٌ، تُصْنَعُ مِنْ إِطَارٍ خَشَبِيٍّ أَوْ مَعْدِنِيٍّ دَائِرِيٍّ كَالصُّنْدُوقِ، يُشَدُّ عَلَى كُلٍّ مِنْ وَجْهَيْهِ جِلْدٌ يُضْرَبُ عَلَيْهِ بِعَصاً، يُحْمَلُ عَلَى الصَّدْرِ. ""يُحْسِنُونَ الرَّقْصَ عَلَى نَقْرِ الطُّبُولِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21968, 'طُبُولٌ', 'طبول', 'مصدر', '', 'طبول', 'طبل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21969, 'تَطْرِيبٌ', 'تطريب', 'مصدر', 'طرب', 'تطريب', 'تطرب', 'مص. طَرَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَطْرِيبٌ-تَطْرِيبٌ [ط ر ب] (مص. طَرَّبَ). 1.""طَرَّبَ الْمُغَنِّي تَطْرِيباً"" : تَغَنَّى تَغَنِّياً فِيهِ إِطْرَابٌ. 2.""سَعَى إِلَى "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21970, 'طَرَبٌ', 'طرب', 'مصدر', 'طرب', 'طرب', 'طرب', 'مص. طَرِبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَرَبٌ-طَرَبٌ [ط ر ب] (مص. طَرِبَ). 1.""هَزَّهُ الطَّرَبُ"" : مَا يَهُزُّ الْمَرْءَ مِنْ هَزَّةٍ أَوْ خِفَّةٍ لِشِدَّةِ فَرَحٍ أَوْ حُزْنٍ. 2.""آلَةُ الطَّرَبِ"" : آلَةٌ مِنْ آلاَتِ الغِنَاءِ وَالْمُوسِيقَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21971, 'طَرْحٌ', 'طرح', 'مصدر', 'طرح', 'طرح', 'طرح', 'مص. طَرَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَرْحٌ-طَرْحٌ [ط ر ح] (مص. طَرَحَ). ""عَمَلِيَّةُ الطَّرْحِ فِي الْحِسَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21972, 'طَرْدٌ', 'طرد', 'مصدر', 'طرد', 'طرد', 'طرد', 'مص. طَرَدَ', '', '', 'مفرد', 'DnN', '', '', '"طُرُودٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَرَدَ). 1.""قَرَّرَ طَرْدَهُ مِنَ العَمَلِ"" : إِبْعَادَهُ، عَزْلَهُ. 2.""بَحَثَ الْمَسْأَلَةَ طَرْداً وَعَكْساً"" : بَحَثَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21973, 'طُرُودٌ', 'طرود', 'مصدر', '', 'طرود', 'طرد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21974, 'طَرَدٌ', 'طرد', 'مصدر', 'طرد', 'طرد', 'طرد', 'مص. طَرِدَ', '', '', 'مفرد', 'DnN', '', '', '"طُرُودٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَرِدَ). 1.""هَذَا يَوْمُ الطَّرَدِ"" : يَوْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21975, 'طُرُودٌ', 'طرود', 'مصدر', '', 'طرود', 'طرد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21976, 'تَطْرِيزٌ', 'تطريز', 'مصدر', 'طرز', 'تطريز', 'تطرز', 'مص. طَرَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْرِيزٌ-تَطْرِيزٌ [ط ر ز] (مص. طَرَّزَ). ""تَفَرَّغَتْ لِتَطْرِيزِ مَنَادِلِ العُرْسِ"" : لِتَزْيِينِهَا بِخُيُوطٍ مُلَوَّنَةٍ، "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21977, 'طُرْشَةٌ', 'طرشة', 'مصدر', 'طرش', 'طرشة', 'طرشة', 'مص. طَرِشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طُرْشَةٌ-طُرْشَةٌ [ط ر ش] (مص. طَرِشَ). ""أَصَابَتْهُ طُرْشَةٌ"" : تَعَطُّلُ حَاسَّةِ السَّمْعِ لَدَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21978, 'طَرَشٌ', 'طرش', 'مصدر', 'طرش', 'طرش', 'طرش', 'مص. طَرِشَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَرَشٌ-طَرَشٌ [ط ر ش] (مص. طَرِشَ). ""أَصَابَهُ الطَّرَشُ"" : تَعَطُّلُ حَاسَّةِ سَمْعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21979, 'تَطْرِيفٌ', 'تطريف', 'مصدر', 'طرف', 'تطريف', 'تطرف', 'مص. طَرَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْرِيفٌ-تَطْرِيفٌ [ط ر ف] (مص. طَرَّفَ). 1.""تَطْرِيفُ الْمَائِدَةِ"": جَعْلُهَا فِي الطَّرَفِ. 2.""تَطْرِيفُ الأَصَابِعِ"" : تَلْوِينُهَا، تَزْيِينُهَا باِلخِضَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21980, 'طَرْفٌ', 'طرف', 'مصدر', 'طرف', 'طرف', 'طرف', 'مص. طَرَفَ', '', '', 'مفرد', 'DnN', '', '', '"أَطْرَافٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَرَفَ). 1.""رَفَعَ طَرْفَهُ إِلَى أَعْلَى"" : عَيْنَهُ. ""نَظَرَ إِلَيْهِ بِطَرْفٍ خَفِيٍّ"": أَي نَظَرَ بِعَيْنٍ خَفِيَّةٍ. 2.""غَضِيضُ الطَّرْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21981, 'أَطْرَافٌ', 'أطراف', 'مصدر', '', 'ءطراف', 'طرف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21982, 'طَرَافَةٌ', 'طرافة', 'مصدر', 'طرف', 'طرافة', 'طرفة', 'مص. طَرُفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَرَافَةٌ-طَرَافَةٌ [ط ر ف] .(مص. طَرُفَ). ""طَرَافَةُ الْحَدِيثِ"" : حَلاَوَتُهُ، أَيْ عِنْدَمَا يَصِيرُ طَرِيفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21983, 'تَطْرِيقٌ', 'تطريق', 'مصدر', 'طرق', 'تطريق', 'تطرق', 'مص. طَرَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْرِيقٌ-تَطْرِيقٌ [ط ر ق] (مص. طَرَّقَ). ""يَخْتَصُّ بِتَطْرِيقِ الْمَعَادِنِ، مِنْ حَدِيدٍ وَفِضَّةٍ وَذَهَبٍ"" : تَمْدِيدُهُ، تَرْقِيقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21984, 'طَرْقٌ', 'طرق', 'مصدر', 'طرق', 'طرق', 'طرق', 'مص. طَرَقَ', '', '', 'مفرد', 'DnN', '', '', '"طُرُوقٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَرَقَ). 1.""نَصَبَ لَهُ طَرْقاً"" : فَخّاً. 2.""الطَّرْقُ وَهْمٌ"" : الضَّرْبُ بِالْحَصَى، وَهُوَ ضَرْبٌ مِنَ التَّكَهُّنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21985, 'طُرُوقٌ', 'طروق', 'مصدر', '', 'طروق', 'طرق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21986, 'طَرَاوَةٌ', 'طراوة', 'مصدر', 'طري', 'طراوة', 'طرة', 'مص. طَرِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَرَاوَةٌ-طَرَاوَةٌ [ط ر ي] .(مص. طَرِيَ). 1.""طَرَاوَةُ الْهَوَاءِ"" : بُرُودَتُهُ. 2.""طَرَاوَةُ العُمْرِ"" : نُعُومَتُهُ، غَضَّتُهُ، لُيُونَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21987, 'تَطْعِيمٌ', 'تطعيم', 'مصدر', 'طعم', 'تطعيم', 'تطعم', 'مص. طَعَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْعِيمٌ-تَطْعِيمٌ [ط ع م] (مص. طَعَّمَ). 1. ""فَلاَّحٌ لَهُ مَعْرِفَةٌ بِتَطْعِيمِ النَّبَاتِ وَالشَّجَرِ"" : وَصْلُ بُرْعُمِ نَبَاتٍ بِسَاقِ نَبَاتٍ مِنْ جِنْسٍ آخَرَ لِيَصِيرَ جُزْءاً مِنْهُ، تَرْكِيبُهُ، لِيَتَغَذَّى مِنْهُ. 2.""ذَهَبَ إِلىَ الْمُسْتَشْفَى لِتَطْعِيمِ أَبْنَائِهِ"" : لِتَلْقِيحِهِمْ بِمَصْلِ الجَرَاثِيمِ وَالأَمْرَاضِ الْمُعْدِيَةِ لِلْوِقَايَةِ مِنْهَا وَإِكْسَابِ الجِسْمِ مَنَاعَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21988, 'طَعَامٌ', 'طعام', 'مصدر', 'طعم', 'طعام', 'طعم', 'مص. طَعِمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَطْعِمَةٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَعِمَ). 1.""قَدَّمَ لَهُ طَعَاماً وَفِيراً"" : كُلُّ مَا يُتَغَذَّى بِهِ، الأَكْلُ. 2.""مَائِدَةُ الطَّعَامِ"": مَائِدَةُ الأَكْلِ. ""طَعَامُ العَشَاءِ"" ""طَعَامُ الغَدَاءِ"". 3.""قَائِمَةُ الطَّعَامِ بِالْمَطْعَمِ"" : قَائِمَةٌ تَضُمُّ أَنْوَاعَ الْمَأْكُولاَتِ الْمَوْجُودَةِ بِالْمَطْعَمِ. 4.""الإِضْرابُ عَنِ الطَّعامِ"" : الاِمْتِناع عَن تَناوُلِ الأَكْلِ احْتِجاجاً على سُوءِ الْمُعامَلَةِ. ""قَرَّرَ الْمُعْتَقَلُونَ الفِلَسْطِينِيُّونَ فِي السُّجُونِ الإِسْرائِيلِيَّةِ إِضْرَاباً عَنِ الطَّعَامِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21989, 'أَطْعِمَةٌ', 'أطعمة', 'مصدر', '', 'ءطعمة', 'طعمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21990, 'طَعْمٌ', 'طعم', 'مصدر', 'طعم', 'طعم', 'طعم', 'مص. طَعِمَ', '', '', 'مفرد', 'DnN', '', '', '"طُعُومٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَعِمَ). 1.""طَعَامٌ طَعْمُهُ لَذِيذٌ"" : مَذَاقُهُ لَذِيذٌ، أَيْ مَا تُدْرِكُهُ حَاسَّةُ الذَّوْقِ مِنْ طَعَامٍ أَوْ شَرَابٍ حُلْواً كَانَ أَوْ مُرّاً، حَامِضاً أَوْ مَالِحاً أَوْ لاَ مَذَاقَ لَهُ. ""لا طَعْمَ لَهُ"". 2.""لَمْ يَذُقْ لِلنَّوْمِ طَعْماً"" : رَاحَةً. ""لَمْ يَذُقْ لِلْحَيَاةِ طَعْماً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21991, 'طُعُومٌ', 'طعوم', 'مصدر', '', 'طعوم', 'طعم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21992, 'طَعْنٌ', 'طعن', 'مصدر', 'طعن', 'طعن', 'طعن', 'مص. طَعَنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَعْنٌ-طَعْنٌ [ط ع ن] (مص. طَعَنَ). 1.""تَعَرَّضَ لِلطَّعْنِ بِالسّكّينِ"" : لِلْوَخْزِ. 2.""سَعَى إلى الطّعْنِ في شَرَفِهِ"" : تَوْجيه العَيْبِ إِلَيْهِ. ""تَبَيَّنَ لَها أَنَّ ذَلِكَ الطَّعْنَ كافٍ لاسْتِئْصالِها مِنْ مَنْبِتِها"". (أحمد التوفيق)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21993, 'طُغْيَانٌ', 'طغيان', 'مصدر', 'طغي', 'طغيان', 'طغن', 'مص. طَغَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طُغْيَانٌ-طُغْيَانٌ [ط غ ي] (مص. طَغَى). 1.""اِنْتَشَرَ الطُّغْيَانُ فِي عَهْدِهِ"" : الْجَوْرُ وَالاضْطِهَادُ. 2.""طُغْيَانُ السَّيْلِ"" : فَيَضَانُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21994, 'طَفْحٌ', 'طفح', 'مصدر', 'طفح', 'طفح', 'طفح', 'مص. طَفَحَ', '', '', 'مفرد', 'DnN', '', '', '"طُفُوحٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَفَحَ). 1.(طب).: مَرَضٌ جِلْدِيٌّ يَظْهَرُ عَلَى شَكْلِ بُثُورٍ. 2.""طَفْحُ الْمَجَارِي"" : فَيَضَانُهَا. ""طَفْحُ مِيَاهِ النَّهْرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21995, 'طُفُوحٌ', 'طفوح', 'مصدر', '', 'طفوح', 'طفح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21996, 'طُفُوحٌ', 'طفوح', 'مصدر', 'طفح', 'طفوح', 'طفح', 'مص. طَفَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طُفُوحٌ-طُفُوحٌ [ط ف ح] (مص. طَفَحَ). ""يَعْرِفُ السُّوقُ طُفُوحاً بِمُخْتَلِفِ الْمَوَادِّ"" : وَفْرَةً، فَيْضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21997, 'طَفْطَفَةٌ', 'طفطفة', 'مصدر', 'طفطف', 'طفطفة', 'طفطفة', 'مص. طَفْطَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":طَفَاطِفُ"', '', 'R', '', '', '', '', '', '', '"(مص. طَفْطَفَ). 1.""رَقَّتْ طَفْطَفَتُهَا"" : خَاصِرَتُهَا أَوْ مَا نَعُمَ مِنْ لَحْمِ البَطْنِ. 2.""طَفْطَفَةُ لَحْمٍ"" : مَا اضْطَرَبَ مِنْهُ. 3 .""طَفْطَفَةُ الكَبِدِ"" : مَا رَقَّ مِنْ طَرَفِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21998, 'طَفَاطِفُ', 'طفاطف', 'مصدر', '', 'طفاطف', 'طفطف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(21999, 'طَفْلٌ', 'طفل', 'مصدر', 'طفل', 'طفل', 'طفل', 'مص. طَفَلَ', '', '', 'مفرد', 'DnN', '', '', '"طُفولٌ:طِفالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَفَلَ). 1.""نَباتٌ طَفْلٌ"" : ناعِمٌ. 2.""صَبَغَتْ ثَوْبَها بِالطَّفْلِ"" : طِينٌ أَصْفَرُ يُصْبَغُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22000, 'طُفولٌ', 'طفول', 'مصدر', '', 'طفول', 'طفل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22001, 'طِفالٌ', 'طفال', 'مصدر', '', 'طفال', 'طفل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22002, 'طُفُولَةٌ', 'طفولة', 'مصدر', 'طفل', 'طفولة', 'طفلة', 'مص. طَفُلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طُفُولَةٌ-طُفُولَةٌ [ط ف ل] (مص. طَفُلَ). ""عَاشَ طُفُولَةً هَادِئَةً"": حَالَتُهُ أَيَّامَ كَانَ طِفْلاً مِنَ الْمِيلاَدِ إِلَى سِنِّ البُلُوغِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22003, 'طَفَلٌ', 'طفل', 'مصدر', 'طفل', 'طفل', 'طفل', 'مص. طَفِلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَفَلٌ-طَفَلٌ [ط ف ل] (مص. طَفِلَ). 1.""دَخَلَ فِي الطَّفَلِ"": فِي ظُلْمَةِ اللَّيْلِ. 2.""حَلَّ الطَّفَلُ"" : إِقْبَالُ اللَّيْلِ عَلَى النَّهَارِ بِظُلْمَتِهِ. 3.""طَفَلُ العَشِيِّ"" : آخِرُهُ عِنْدَ غُرُوبِ الشَّمْسِ وَاصْفِرَارِهَا. 4.""طَفَلُ الغَدَاةِ"" : قُبَيْلَ طُلُوعِ الشَّمْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22004, 'طَقٌّ', 'طق', 'مصدر', 'طقق', 'طق', 'طق', 'مص. طَقَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَقٌّ-طَقٌّ [ط ق ق] (مص. طَقَّ). ""كُنَّا نَسْمَعُ مِنْ بَعِيدٍ طَقَّ الْحَجَرِ"" : أَيْ صَوْتَ الْحَجَرِ عِنْدَمَا يَقَعُ عَلَى الْحَجَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22005, 'طَقْطَقَةٌ', 'طقطقة', 'مصدر', 'طقطق', 'طقطقة', 'طقطقة', 'مص. طَقْطَقَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَقْطَقَةٌ-طَقْطَقَةٌ [ط ق ط ق] (مص. طَقْطَقَ) . 1.""اِنْطَلَقَتْ طَقْطَقَةُ الْمَدَافِعِ لَيْلَةَ العِيدِ"" : الأَصْوَاتُ الَّتِي تُحْدِثُهَا الْمَدَافِعُ عِنْدَ انْطِلاَقِهَا. 2.""كُنَّا نَسْمَعُ طَقْطَقَةَ الْحِجَارَةِ عِنْدَ سَفْحِ الْجَبَلِ"" : الأَصْوَاتُ الَّتِي تُحْدِثُهَا عِنْدَ تَكَسُّرِهَا. 3.""اِسْتَمَعْنَا إِلَى الطَّقْطَقَةِ الْجَبَلِيَّةِ"" : نَوْعٌ مِنَ الْمُوسِيقَى الشَّعْبِيَّةِ فِي شَمَالِ الْمَغْرِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22006, 'طَلاَلَةٌ', 'طلالة', 'مصدر', 'طلل', 'طلالة', 'طللة', 'مص. طَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَلاَلَةٌ-طَلاَلَةٌ [ط ل ل] (مص. طَلَّ). 1.""طَلاَلَةُ الوَجْهِ الْجَمِيلِ"" : هَيْئَتُهُ الْجَمِيلَةُ وَبَهْجَتُهُ. 2.""مَا زَالَتْ طَلاَلَةُ الآثَارِ بَاقِيَةً "" : الشَّاخِصُ مِنَ الآثَارِ، مَا بَقِيَ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22007, 'طَلٌّ', 'طل', 'مصدر', 'طلل', 'طل', 'طل', 'مص. طَلَّ', '', '', 'مفرد', 'DnN', '', '', '"طِلاَلٌ:طِلَلٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَلَّ). 1.""غَمَرَ الطَّلُّ النَّبَاتَ"" : النَّدَى. 2.""أَصَابَ الطَّلُّ الأَرْضَ "" : الْمَطَرُ الْخَفِيفُ.البقرة آية 265 فَإِنْ لَمْ يُصِبْهَا وَابِلٌ فَطَلٌّ (قرآن). 3.""سَقَاهُ طَلاًّ"" : لَبَناً. 4.""رَجُلٌ طَلٌّ"" : كَبِيرُ السِّنِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22008, 'طِلاَلٌ', 'طلال', 'مصدر', '', 'طلال', 'طلل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22009, 'طِلَلٌ', 'طلل', 'مصدر', '', 'طلل', 'طل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22010, 'طَلَبٌ', 'طلب', 'مصدر', 'طلب', 'طلب', 'طلب', 'مص. طَلَبَ', '', '', 'مفرد', 'DnN', '', '', '"طَلَبَاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَلَبَ). 1.""قَدَّمَ طَلَباً يَلْتَمِسُ فِيهِ عَمَلاً"" : رِسَالَةً تَتَضَمَّنُ الْتِمَاساً لِلْحُصُولِ عَلَى عَمَلٍ. ""لَمْ يَحْظَ طَلَبُهُ بِالْمُوَافَقَةِ"". 2.""تَقَدَّمَ بِطَلَبِ العَفْوِ"" : بِنِدَاءِ الْعَفْوِ. 3.""بِنَاءً عَلَى طَلَبِهِ"" : حَسَبَ رَغْبَتِهِ. ""عِنْدَ الطَّلَبِ"" ""لَبَّى طَلَبَهُ"". 4.""تَحْتَ الطَّلَبِ"" : تَحْتَ التَّصَرُّفِّ. ""تَحْتَ طَلَبِهِ"". 5. ""ثَمَنُ البِضَاعَةِ يَخْضَعُ لِلْعَرْضِ والطَلَبِ"" : أَي حَسَبَ رَواجِها وَرَغَبَاتِ الأَفْرَادِ فِي اقْتِنَائِهَا وَشِرَائِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22011, 'طَلَبَاتٌ', 'طلبات', 'مصدر', '', 'طلبات', 'طلبت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22012, 'طَلْسٌ', 'طلس', 'مصدر', 'طلس', 'طلس', 'طلس', 'مص. طَلَسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَلْسٌ-طَلْسٌ [ط ل س] (مص. طَلَسَ). ""اِرْتَدَى طَلْساً"" : طَيْلَسَاناً أَسْوَدَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22013, 'طُلُوعٌ', 'طلوع', 'مصدر', 'طلع', 'طلوع', 'طلع', 'مص. طَلَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طُلُوعٌ-طُلُوعٌ [ط ل ع] (مص. طَلَعَ). 1.""مِنْ طُلُوعِ الشَّمْسِ إِلَى غُرُوبِهَا"" : مِنْ بُزُوغِهَا إِلَى... 2.""طُلُوعُ الْجَبَلِ"" : صُعُودُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22014, 'مَطْلَعٌ', 'مطلع', 'مصدر', 'طلع', 'مطلع', 'مطلع', 'مص. طَلَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَطَالِعُ"', '', 'R', '', '', '', '', '', '', '"(مص. طَلَعَ). 1.""مَطْلَعُ الشَّمْسِ"" : زَمَانُ طُلُوعِهَا.القدر آية 5 سَلاَمٌ هِيَ حَتَّى مَطْلَعِ الفَجْرِ (قرآن) ""مَطْلَعُ النَّهَارِ"" ""مَطْلَعُ النُّجُومِ"". 2.""مَطْلَعُ الشَّهْرِ"" : أَوَّلُهُ. 3.""مَطْلَعٌ مُوسِيقِيٌّ"" : مُقَدِّمَةُ الْمَعْزُوفَةِ الْمُوسِيقِيَّةِ. 4.""مَطْلَعُ القَصِيدَةِ"" : أَوَّلُ بَيْتٍ فِيهَا. 5.""مَطْلَعُ الْمُوَشَّحِ"" : هُوَ مَا يَتَكَوَّنُ مِنْ شَطْرَيْنِ أَوْ أَرْبَعَةِ أَشْطُرٍ، أَيْ مِنْ مَجْمُوعَةِ الْمَقَاطِعِ الأُولَى، وَوُجُودُهُ لَيْسَ ضَرُورَةً لاَزِمَةً. فَإِذَا وُجِدَ، سُمِّيَ تَامّاً ؛ وَإِذَا لَمْ يُوجَدْ سُمِّيَ أَقْرَعَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22015, 'مَطَالِعُ', 'مطالع', 'مصدر', '', 'مطالع', 'مطلع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22016, 'تَطْلِيقٌ', 'تطليق', 'مصدر', 'طلق', 'تطليق', 'تطلق', 'مص. طَلَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْلِيقٌ-تَطْلِيقٌ [ط ل ق] (مص. طَلَّقَ). ""تَطْلِيقُ الزَّوْجَةِ"" : تَحْرِيرُهَا مِنْ قَيْدِ الزَّوَاجِ، إِخْرَاجُهَا مِنْ عِصْمَةِ الزَّوْجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22017, 'طَلاَقٌ', 'طلاق', 'مصدر', 'طلق', 'طلاق', 'طلق', 'مص. طَلَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. طَلَقَ). 1.""قَرَّرَ الطَّلاَقَ مِنْ زَوْجَتِهِ"" : الطَّلاَقُ شَرْعاً هُوَ رَفْعُ قَيْدِ الزَّوَاجِ الْمُنْعَقِدِ بَيْنَ الزَّوْجَيْنِ بِأَلْفَاظٍ مَخْصُوصَةٍ. ""حَلَفَ بِالطَّلاَقِ"". 2.""طَلاَقٌ بِالثَّلاَثَةِ"" : إِنْهَاءُ الرَّابِطَةِ الزَّوْجِيَّةِ نِهَائِيّاً. 3.""طَلاَقٌ بَائِنٌ"" : يَظَلُّ الزَّوْجُ بِاسْتِطَاعِتِهِ الارْتِبَاطُ بِزَوْجَتِهِ وَإِعَادَتُهَا إِلَى عِصْمَتِهِ بِشَرْطِ تَجْدِيدِ العَقْدِ وَالْمَهْرِ. 4.""طَلاَقٌ رِجْعِيٌّ"" : إِعَادَةُ الزَّوْجَةِ إِلَى عِصْمَةِ زَوْجِهَا دُونَ عَقْدٍ وَمَهْرٍ جَدِيدَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22018, 'طَلاَقَةٌ', 'طلاقة', 'مصدر', 'طلق', 'طلاقة', 'طلقة', 'مص. طَلُقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَلاَقَةٌ-طَلاَقَةٌ [ط ل ق] (مص. طَلُقَ). 1..""يَمْتَازُ بِطَلاَقَةِ اللِّسَانِ"" : بِسُهُولَةِ الْحَدِيثِ، بِالفَصَاحَةِ. 2.""تَكْشِفُ طَلاَقَةُ وَجْهِهِ عَنِ الفَرَحِ"" : بَشَاشَةُ وَجْهِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22019, 'طَلىً', 'طلى', 'مصدر', 'طلي', 'طلى', 'طل', 'مص. طَلِيَ', '', '', 'مفرد', 'Dy', '', '', '"أَطْلاَءٌ:طِلاَءٌ"', '', 'Rw', '', '', '', '', '', '', '"(مص. طَلِيَ). 1. : وَلَدُ الغَزَالِ سَاعَةَ يُولَدُ. 2.""قَضَى طَلاَهُ"" : هَوَاهُ. 3.""إِنَّهُ جَمِيلُ الطَّلَى"" : جَمِيلُ الْهَيْئَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22020, 'أَطْلاَءٌ', 'أطلاء', 'مصدر', '', 'ءطلاء', 'طل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22021, 'طِلاَءٌ', 'طلاء', 'مصدر', '', 'طلاء', 'طل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22022, 'طِلاَءٌ', 'طلاء', 'مصدر', 'طلي', 'طلاء', 'طل', 'مص. طَلَى', '', '', 'مفرد', 'Dz', '', 'Pf', '":أَطْلِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '"(مص. طَلَى). 1.""طِلاَءُ جُدْرَانِ الغُرْفَةِ"" : كُلُّ مَا يُطْلَى بِهَا. ""زَالَ الطِّلاَءُ الأَزْرَقُ عَنِ النَّوَافِذِ"". 2.""مَادَّةُ الطِّلاَءِ"" : القَطْرَانُ. 3.""مَعْدِنٌ مِنْ طِلاَءٍ"" : مِنْ فِضَّةٍ خَالِصَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22023, 'أَطْلِيَةٌ', 'أطلية', 'مصدر', '', 'ءطلية', 'طلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22024, 'طَمٌّ', 'طم', 'مصدر', 'طمم', 'طم', 'طم', 'مص. طَمَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَمٌّ-طَمٌّ [ط م م] (مص. طَمَّ). ""تَلاَطَمَتْ أَمْوَاجُ الطَّمِّ"" : البَحْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22025, 'طُمَأْنِينَةٌ', 'طمأنينة', 'مصدر', 'طمن', 'طمءنينة', 'طمننة', 'مص. طَمْأَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طُمَأْنِينَةٌ-طُمَأْنِينَةٌ [ط م ن] (مص. طَمْأَنَ). 1.""طُمَأْنِينَةُ النَّفْسِ"": راَحَتُهَا وَسُكُونُهَا وَثَبَاتُهَا. ""طُمَأْنِينَةُ القَلْبِ"" عَادَتِ الطُّمَأْنِينَةُ إِلَى نَفْسِهِ. 2.""يَعِيشُ فِي طُمْأَنِينَةٍ "" : فِي هُدُوءٍ وَسُكُونٍ وَرَاحَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22026, 'طَمُوحٌ', 'طموح', 'مصدر', 'طمح', 'طموح', 'طمح', 'مص. طَمَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَمُوحٌ-طَمُوحٌ [ط م ح] (مص. طَمَحَ).""شَابٌّ طَمُوحٌ"" : السِّاعِي بِرَغْبَةٍ لِلْحُصُولِ على مَا هُوَ أَعْلَى وَمَحْمُودٌ وَنَبِيلٌ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22027, 'تَطْمِيرٌ', 'تطمير', 'مصدر', 'طمر', 'تطمير', 'تطمر', 'مص. طَمَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْمِيرٌ-تَطْمِيرٌ [ط م ر] (مص. طَمَّرَ). ""تَطْمِيرُ الثَّوْبِ"" : طَيُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22028, 'تَطْمِيعٌ', 'تطميع', 'مصدر', 'طمع', 'تطميع', 'تطمع', 'مص. طَمَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْمِيعٌ-تَطْمِيعٌ [ط م ع] (مص. طَمَّعَ). ""حَاوَلَ تَطْمِيعَهُ"" : حَمْلَهُ عَلَى الطَّمَعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22029, 'طَمَاعَةٌ', 'طماعة', 'مصدر', 'طمع', 'طماعة', 'طمعة', 'مص. طَمُعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَمَاعَةٌ-طَمَاعَةٌ [ط م ع] (مص. طَمُعَ). ""فِي نَفْسِهِ طَمَاعَةٌ إِلَى شَيْءٍ"" : مَيْلُ النَّفْسِ وَنُزُوعُهَا إِلَى شَيْءٍ شَهْوَةً لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22030, 'طَمَعٌ', 'طمع', 'مصدر', 'طمع', 'طمع', 'طمع', 'مص. طَمِعَ', '', '', 'مفرد', 'DnN', '', '', '"أَطْمَاعٌ"', '', 'R', '', '', '', '', '', '', '"(مص. طَمِعَ). ""اِشْتَدَّ بِهِ الطَّمَعُ"" : الرَّغْبَةُ الشَّدِيدَةُ للحُصُولِ عَلَى الشَّيْءِ، لِلاِسْتِحْوَاذِ عَلَيْهِ، اِشْتِهَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22031, 'أَطْمَاعٌ', 'أطماع', 'مصدر', '', 'ءطماع', 'طمع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22032, 'طَنِينٌ', 'طنين', 'مصدر', 'طنن', 'طنين', 'طنن', 'مص. طَنَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَنِينٌ-طَنِينٌ [ط ن ن] (مص. طَنَّ). 1.""طَنِينُ الذُّبَابِ"" : مَا يُحْدِثُهُ مِنْ صَوْتٍ وَرَنِينٍ. ""طَنِينُ النّاقُوسِ"". 2.""قَصِيدَةٌ لَهَا طَنِينٌ"" : لَهَا صَدىً وَذِكْرٌ وَجَلْجَلَةٌ فِي الْمَحَافِلِ. ""خُطْبَةٌ لَهَا طَنِينٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22033, 'تَطْنِيبٌ', 'تطنيب', 'مصدر', 'طنب', 'تطنيب', 'تطنب', 'مص. طَنَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْنِيبٌ-تَطْنِيبٌ [ط ن ب] (مص. طَنَّبَ). 1.""تَطْنِيبُ الخَيْمَةِ"": شَدُّ أَطْنَابِهَا، حِبَالِهَا. 2.""التَّطْنِيبُ بِالْمَكَانِ"" : الإِقَامَةُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22034, 'تَطْنِيفٌ', 'تطنيف', 'مصدر', 'طنف', 'تطنيف', 'تطنف', 'مص. طَنَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْنِيفٌ-تَطْنِيفٌ [ط ن ف] (مص. طَنَّفَ). ""تَطْنِيفُ الحَقْلِ"" : جَعْلُ أَشْوَاكِ الشَّجَرِ وَأَغْصَانِهِ حَوْلَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22035, 'تَطْنِينٌ', 'تطنين', 'مصدر', 'طنن', 'تطنين', 'تطنن', 'مص. طَنَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْنِينٌ-تَطْنِينٌ [ط ن ن] (مص. طَنَّنَ). 1.""تَطْنِينُ الذُّبَابِ"" : تَصْوِيتُهُ. 2.""تَطْنِينُ النَّاقُوسِ"" : إِحْدَاثُهُ لِلتَّطْنِينِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22036, 'طَهْوٌ', 'طهو', 'مصدر', 'طهو', 'طهو', 'طه', 'مص. طَهَا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طَهْوٌ-طَهْوٌ [ط هـ و] (مص. طَهَا). 1.""طَهْوُ الطَّعَامِ"" : طَبْخُهُ، إِنْضَاجُهُ. 2.""هُوَ فِي طَهْوٍ مُسْتَمِرٍّ"" : فِي عَمَلٍ. 3.""تُحْسِنُ الطَّهْوَ"" : الْخَبْزَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22037, 'تَطْهِيرٌ', 'تطهير', 'مصدر', 'طهر', 'تطهير', 'تطهر', 'مص. طَهَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْهِيرٌ-تَطْهِيرٌ [ط هـ ر] (مص. طَهَّرَ). 1.""قَرَّرَ تَطْهِيرَ ابْنِهِ"": أَيْ خِتَانَهُ. 2.""يَنْبَغِي تَطْهِيرُ الجُرْحِ قَبْلَ وَضْعِ الدَّوَاءِ"" : إِزَالَةُ مَا بِهِ مِنْ عُفُونَةٍ. 3.""عَمِلَ عَلَى تَطْهِيرِ الإِدَارَةِ مِنَ العَنَاصِرِ الفَاسِدَةِ"" : عَلَى تَنْقِيَتِهَا، إِصْلاَحِهَا. 4. الأحزاب آية 33 وَيُطَهِّرُكُمْ تَطْهِيراً (قرآن) : تَنْقِيَةُ النَّفْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22038, 'طَهَارَةٌ', 'طهارة', 'مصدر', 'طهر', 'طهارة', 'طهرة', 'مص. طَهُرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"طَهَارَةٌ-طَهَارَةٌ [ط هـ ر] (مص. طَهُرَ). 1.""الطَّهَارَةُ شَرْطٌ مِنْ شُرُوطِ أَدَاءِ الصَّلاَةِ"" : التَّطَهُّرُ بِالْمَاءِ..2 .""طَهَارَةُ النَّفْسِ"" : أَيْ تَخْلِيصُ النَّفْسِ مِنْ كُلِّ الشَّوَائِبِ وَالضَّغَائِنِ. ""طَهَارَةُ القَلْبِ"". 3.""بَيْتُ الطَّهَارَةِ"" : الْمِرْحَاضُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22039, 'طُهْرٌ', 'طهر', 'مصدر', 'طهر', 'طهر', 'طهر', 'مص. طَهُرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"طُهْرٌ-طُهْرٌ [ط هـ ر] (مص. طَهُرَ). ""ثَوْبٌ طُهْرٌ"" : خَالٍ مِنْ كُلِّ نَجَاسَةٍ وَدَنَسٍ. ""مَكَانٌ طُهْرٌ لأَدَاءِ الصَّلاَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22040, 'تَطْوِيحٌ', 'تطويح', 'مصدر', 'طوح', 'تطويح', 'تطح', 'مص. طَوَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْوِيحٌ-تَطْوِيحٌ [ط و ح] (مص. طَوَّحَ). 1.""حَاوَلَ التَّطْوِيحَ بِهِ بَعِيداً"" : إِلْقَاؤُهُ بَعِيداً. 2.""التَّطْوِيحُ بِالعَصَا"" : الضَّرْبُ بِالعَصَا. 3.""تَطْوِيحُ الأَدَوَاتِ"" : تَضْيِيعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22041, 'تَطْوِيرٌ', 'تطوير', 'مصدر', 'طور', 'تطوير', 'تطر', 'مص. طَوَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَطْوِيرٌ-تَطْوِيرٌ [ط و ر] (مص. طَوَّرَ). ""تَطْوِيرُ الصِّنَاعَةِ"" : تَعْدِيلُهَا وَتَحْسِينُهَا إِلَى مَا هُوَ أَفْضَلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22042, 'تَطْوَافٌ', 'تطواف', 'مصدر', 'طوف', 'تطواف', 'تطف', 'مص. طَوَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْوَافٌ-تَطْوَافٌ [ط و ف] (مص. طَوَّفَ). ""خَرَجَتِ الفِرْقَةُ الفُلْكُلُورِيَّةُ فِي تَطْوَافٍ بِأَرْجَاءِ الْمَدِينَةِ"" : قَامَتْ بِمَسِيرَةٍ اِحْتِفَالِيَّةٍ تَدُورُ دَوَرَاناً فِي أَرْجَائِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22043, 'تَطْوِيفٌ', 'تطويف', 'مصدر', 'طوف', 'تطويف', 'تطف', 'مص. طَوَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْوِيفٌ-تَطْوِيفٌ [ط و ف] (مص. طَوَّفَ). ""التَّطْويفُ بَيْنَ البُيُوتِ والعِمارَاتِ"" : الطَّوَافُ، التَّجْوَالُ. ""اِهْتَمَّ بِتَطْوِيفِهِ أَرْجَاءَ الْمَدِينَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22044, 'تَطْوِيقٌ', 'تطويق', 'مصدر', 'طوق', 'تطويق', 'تطق', 'مص. طَوَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْوِيقٌ-تَطْوِيقٌ [ط و ق] (مص. طَوَّقَ). ""تَطْوِيقُ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22045, 'تَطْوِيلٌ', 'تطويل', 'مصدر', 'طول', 'تطويل', 'تطل', 'مص. طَوَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْوِيلٌ-تَطْوِيلٌ [ط و ل] (مص. طَوَّلَ). ""اِقْتَصَرَ عَلَى مَا ذُكِرَ اجْتِنَاباً لِلتَّطْوِيلِ"" : اِجْتِنَاباً لِلطُّولِ وَالإِغْرَاقِ فِي الكَلاَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22046, 'طَوىً', 'طوى', 'مصدر', 'طوي', 'طوى', 'ط', 'مص. طَوِيَ', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"طَوىً-طَوىً [ط و ي] (مص. طَوِيَ). ""باتَ عَلَى الطَّوَى"" : عَلَى الْجُوعِ. وَلَقَدْ أَب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22047, 'تَطْيِيبٌ', 'تطييب', 'مصدر', 'طيب', 'تطييب', 'تطب', 'مص. طَيَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْيِيبٌ-تَطْيِيبٌ [ط ي ب] (مص. طَيَّبَ). 1.""التَّطْيِيبُ بِالعِطْرِ"" : طَلْيُهُ وَالتَّعَطُّرُ بِهِ. 2.""تَطْيِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22048, 'تَطْيِيرٌ', 'تطيير', 'مصدر', 'طير', 'تطيير', 'تطر', 'مص. طَيَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْيِيرٌ-تَطْيِيرٌ [ط ي ر] (مص. طَيَّرَ). 1.""تَطْيِيرُ الطَّائِرَةِ"" : جَعْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22049, 'تَطْيِينٌ', 'تطيين', 'مصدر', 'طين', 'تطيين', 'تطن', 'مص. طَيَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَطْيِينٌ-تَطْيِينٌ [ط ي ن] (مص. طَيَّنَ). ""تَطْيِينُ الجُدْرَانِ"" : طَلْيُهَا بِالطِّينِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22050, 'مُظَاهَرَةٌ', 'مظاهرة', 'مصدر', 'ظهر', 'مظاهرة', 'مظهرة', 'مص. ظَاهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. ظَاهَرَ). ""خَرَجَتْ جَمَاهِيرُ الشَّعْبِ فِي مُظَاهَرَةٍ عَارِمَةٍ"" : تَجَمْهُرُ النَّاسِ وَاحْتِشَادُهُمْ فِي مَوَاكِبَ فِي السَّاحَاتِ العُمُومِيَّةِ تَأيِيداً لِشَخْصٍ مَّا أَوْ لِعَمَلٍ مَّا أَوْ احْتِجاجاً عَلَيْهِ. ""سَارَتِ الْمُظَاهَرَةُ الصَّغِيرَةُ تَتَضَخَّمُ فِي كُلِّ خُطْوَةٍ وَجَاءتْ مُظَاهَرَةٌ أُخْرَى فَرَدَفَتْهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22051, 'ظَرافَةٌ', 'ظرافة', 'مصدر', 'ظرف', 'ظرافة', 'ظرفة', 'مص. ظَرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ظَرافَةٌ-ظَرافَةٌ [ظ ر ف] (مص. ظَرَفَ). ""أَظْهَرَ ظَرافَةً"" : لُطْفاً، رِقَّةً، حِذْقاً، بَراعَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22052, 'ظَرْفٌ', 'ظرف', 'مصدر', 'ظرف', 'ظرف', 'ظرف', 'مص. ظَرَفَ، ظَرُفَ', '', '', 'مفرد', 'DnN', '', '', '"ظُروفٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ظَرَفَ، ظَرُفَ). 1.""وَلَدٌ نَقِيُّ الظَّرْفِ"" : أَمينٌ. 2.""يُنْجِزُ عَمَلَهُ بِظَرْفٍ"": بِحِذْقٍ. 3.""هُوَ جَمُّ اللُّطْفِ والظَّرْفِ"" : ذُو بَراعَةٍ وَذَكاءٍ. 4.""رَأَيْتُ الوَلَدَ بِظَرْفِهِ"" : بِعَيْنِهِ. 5.""يَعيشُ في ظَرْفٍ صَعْبٍ"" : في وَضْعٍ، في حالٍ... ""لَمْ تَسْمَحْ لَهُ ظُرو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22053, 'ظُروفٌ', 'ظروف', 'مصدر', '', 'ظروف', 'ظرف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22054, 'تَظْفِيرٌ', 'تظفير', 'مصدر', 'ظفر', 'تظفير', 'تظفر', 'مص. ظَفَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَظْفِيرُ-تَظْفِيرُ [ظ ف ر] (مص. ظَفَّرَ). ""سَاعَدَهُ لِلتَّظْفِيرِ بِالعَدُوِّ"" : جَعْلُهُ يَظْفَرُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22055, 'ظَفَرٌ', 'ظفر', 'مصدر', 'ظفر', 'ظفر', 'ظفر', 'مص. ظَفِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ظَفَرٌ-ظَفَرٌ [ظ ف ر] (مص. ظَفِرَ). ""حَقَّقَ ظَفَراً باهِراً"" : نَصْراً وَغَلَبَةً، اِنْتِصاراً. ""يَتَمَتَّعُ بِنَشْوَةِ الظَّفَرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22056, 'ظَلالَةٌ', 'ظلالة', 'مصدر', 'ظلل', 'ظلالة', 'ظللة', 'مص. ظَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ظَلالَةٌ-ظَلالَةٌ [ظ ل ل] (مص. ظَلَّ). : شَخْصُ الشَّيْءِ مِن ناحِيَةِ ظِلِّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22057, 'ظَلْفٌ', 'ظلف', 'مصدر', 'ظلف', 'ظلف', 'ظلف', 'مص. ظَلَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ظَلْفٌ-ظَلْفٌ [ظ ل ف] (مص. ظَلَفَ). 1.""شَيْءُ ظَلْفٌ"" : مُباحٌ. 2.""ذَهَبَ دَمُهُ ظَلْفاً"" : أَي هَدَراً باطِلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22058, 'ظَلَفٌ', 'ظلف', 'مصدر', 'ظلف', 'ظلف', 'ظلف', 'مص. ظَلِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ظَلِفٌ-ظَلِفٌ، ةٌ [ظ ل ف] (صيغَةُ فَعِل). 1.""رَجُلٌ ظَلِفُ النَّفْسِ"" : مُتَرَفِّعٌ عَنِ الخَطايا والدَّنايا. 2.""اِمْرَأَةٌ ظَلِفَةٌ"" : عَزيزَةٌ عِنْدَ نَفَسِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22059, 'ظَلَفَةٌ', 'ظلفة', 'مصدر', 'ظلف', 'ظلفة', 'ظلفة', 'مص. ظَلِفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"ظَلِفٌ-ظَلِفٌ، ةٌ [ظ ل ف] (صيغَةُ فَعِل). 1.""رَجُلٌ ظَلِفُ النَّفْسِ"" : مُتَرَفِّعٌ عَنِ الخَطايا والدَّنايا. 2.""اِمْرَأَةٌ ظَلِفَةٌ"" : عَزيزَةٌ عِنْدَ نَفَسِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22060, 'تَظْلِيلٌ', 'تظليل', 'مصدر', 'ظلل', 'تظليل', 'تظلل', 'مص. ظَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَظْلِيلٌ-تَظْلِيلٌ [ظ ل ل] (مص. ظَلَّلَ). 1.""تَظْلِيلُ الشَّجَرَةِ"" : اِمْتِدَادُ ظِلِّهَا. 2.""التَّظْلِيلُ بِالرَّحْمَةِ"" : إِلْقَاءُ ظِلِّ الرَّحْمَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22061, 'ظُلْمٌ', 'ظلم', 'مصدر', 'ظلم', 'ظلم', 'ظلم', 'مص. ظَلَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ظُلَمٌ-ظُلَمٌ [ظ ل م]. ""الليالِي الظُّلَمُ"" : اللَّيالِي الثَّلاث الأَخيرَةُ مِنَ القَمَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22062, 'ظَمَأٌ', 'ظمأ', 'مصدر', 'ظمأ', 'ظمء', 'ظم', 'مص. ظَمِئَ', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"ظَمَأٌ-ظَمَأٌ [ظ م أ] (مص. ظَمِئَ). ""بِهِ ظَمَأٌ شَديدٌ"" : عَطَشٌ شَديدٌ. ""أَطْفَأَ ظَمَأَهُ"" ""وَما ظَمَأُ الجَسَدِ إلى الماءِ كَظَمإِ الرُّوحِ إلى الحَقِّ"". (ميخائيل نعيمة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22063, 'ظَنٌّ', 'ظن', 'مصدر', 'ظنن', 'ظن', 'ظن', 'مص. ظَنَّ', '', '', 'مفرد', 'DnN', '', '', '"ظُنونٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ظَنَّ). 1.""يَغْلِبُ عَلَى الظَّنِ أَنَّ الأُمورَ تَسيرُ مِنْ سَيِّءٍ إلى أَسْوَأَ"" : الاِعْتِقادُ، أَيْ ما يَبْدُو في الاعْتِقادِ الرَّاجِحِ مَعَ احْتِمالِ حُدوثِ عَكْسِ ما يُعْتَقَدُ. ""في أَغْلَبِ الظَّنِّ سَيَصِلُ هَذا الْمَساءَ"". 2.""مِنْ شَمائِلِهِ حُسْنُ الظَّنِّ"" : حُسْنُ التَّصَوُّرِ والاعْتِقادِ. ""أَحْسَنَ الظَّنَّ بِهِ"". 3.""مِنْ سَيِّئاتِهِ سوءُ الظَّنِّ بِالنَّاسِ"" : اِعْتِقادُ وَتَصَوُّرُ أَنَّ كُلَّ ما يَصْدُرُ عَنِ النَّاسِ فيهِ سوءٌ. ""سَبَقَ أَنْ أَسَأْتُ الظَّنَّ فاغْفِرْ لِي سوءَ ظَنِّي واعْفُ عَنِّي"". (إسحق الحسيني)الحجرات آية 12 إِنَّ بَعْضَ الظَّنِّ إِثْمٌ (قرآن). 4.""أَساءَ الظَّنَّ بِصَدِيقِهِ"" : فَكَّرَ تَفْكيراً سَيِّئاً في حَقِّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22064, 'ظُنونٌ', 'ظنون', 'مصدر', '', 'ظنون', 'ظنن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22065, 'تَظْهِيرٌ', 'تظهير', 'مصدر', 'ظهر', 'تظهير', 'تظهر', 'مص. ظَهَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَظْهِيرٌ-تَظْهِيرٌ [ظ هـ ر] (مص. ظَهَّرَ). 1.""تَظْهِيرُ الْمُسَافِرِ"": سَيْرُهُ فِي الظَّهِيرَةِ. 2.""تَظْهِيرُ فِلْمٍ"" : إِخْرَاجُ صُوَرِهِ بِوَاسِطَةِ التَّحْمِيضِ الكِيمِيَائِيِّ. 3.""تَظْهِيرُ الصَّكِّ"" : الكِتَابَةُ عَلَى ظَهْرِهِ لِتَحْوِيلِهِ إِلَى شَخْصٍ آخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22066, 'ظَهْرٌ', 'ظهر', 'مصدر', 'ظهر', 'ظهر', 'ظهر', 'مص. ظَهَرَ', '', '', 'مفرد', 'DnN', '', '', '"ظُهورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. ظَهَرَ). 1.""حَمَلَهُ عَلى ظَهْرِهِ"" : مِنْ مُؤَخَّرِ الكاهِلِ إلَى أَدْنَى العَجُزِ عِنْدَ آخِرِهِ، خِلافُ البَطْنِ. ""حَضَرَ رَجُلٌ مُقَوَّسُ الظَّهْرِ"". 2.""وَضَعَ الأَثْقالَ على ظَهْرِ دابَّتِهِ"" : عَلى أَعْلاَها. ""رَكِبَ ظَهْرَ حِمارِهِ"" ""حينَ كانَتِ الْمُدُنُ والأَقالِيمُ لا تُبْلَغُ إِلاَّ عَلَى ظُهورِ الإِبِلِ"". 3.""قَرَأَ القَصيدَةَ عَنْ ظَهْرِ قَلْبٍ"" : قَرَأَها حِفْظاً، غَيْباً. 4.""قَلَبَ لَهُ ظَهْرَ المِجَنِّ"" : تَغَيَّرَ عَلَيْهِ وَعادَاهُ. 5.""قَصَمَ اللَّهُ ظَهْرَهُ"" : أَيْ أَصابَهُ بِمُصيبَةٍ. 6.""قَلَبَ الأَمْرَ ظَهْراً لِبَطْنٍ"" : أي أَنْعَمَ تَدْبيرَهُ. 7.""كَتَبَ عَلَى ظَهْرِ الصَّفْحَةِ"" : عَلَى قَفاها. 8.""ثَقيلُ الظَّهْرِ"" : كَثيرُ الأَوْلادِ، وَعَكْسُهُ خَفيفُ الظَّهْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22067, 'ظُهورٌ', 'ظهور', 'مصدر', '', 'ظهور', 'ظهر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22068, 'ظُهورٌ', 'ظهور', 'مصدر', 'ظهر', 'ظهور', 'ظهر', 'مص. ظَهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"ظُهورٌ-ظُهورٌ [ظ هـ ر] (مص. ظَهَرَ). 1.""ظُهورُ أَعْراضِ الْمَرَضِ"" : بُروزُها. 2.""حُبُّ الظُّهورِ"" : الْمُباهاةُ بِالنَّفْسِ، مَنْ يُحِبُّ أَنْ يُظْهِرَ مَزاياهُ ونَفْسَهُ أَمامَ النَّاسِ مُباهاةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22069, 'عَيْبٌ', 'عيب', 'مصدر', 'عيب', 'عيب', 'عب', 'مص. عَابَ', '', '', 'مفرد', 'DnN', '', '', '"عُيُوبٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَابَ). 1.""بِضَاعَةٌ لاَ عَيْبَ فِيهَا"" : لاَ نَقِيصَةَ بِهَا، لاَ شَيْء"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22070, 'عُيُوبٌ', 'عيوب', 'مصدر', '', 'عيوب', 'عب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22071, 'عَوْدَةٌ', 'عودة', 'مصدر', 'عود', 'عودة', 'عدة', 'مص. عَادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عَوْدَةٌ-عَوْدَةٌ [ع و د] (مص. عَادَ). ""يَنْتَظِرُ الْعَوْدَةَ إِلَى بِـلاَدِهِ"" : الرُّجُوعَ. ""تَمَنَّى عَوْدَةَ ذَلِكَ الزَّمَنِ، زَمَنِ الْبَسَاطَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22072, 'عَوْدٌ', 'عود', 'مصدر', 'عود', 'عود', 'عد', 'مص. عَادَ', '', '', 'مفرد', 'DnN', '', '', '"عِوَدَةٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَادَ). 1. ""تَعِبَ الْعَوْدُ"" : الْجَمَلُ الْمُسِنُّ. 2.""سَارَ فِي عَوْدٍ"" : فِي طَرِيقٍ قَدِيمٍ. 3.""رَجَعَ عَوْداً عَلَى بَدْءٍ"" : أَيْ لَمْ يَقْطَعْ ذَهَابَهُ حَت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22073, 'عِوَدَةٌ', 'عودة', 'مصدر', '', 'عودة', 'عدة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22074, 'عِيَادَةٌ', 'عيادة', 'مصدر', 'عود', 'عيادة', 'عدة', 'مص. عَادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. عَادَ). ""زَارَهُ فِي الْعِيَادَةِ"" : مَصَحَّةُ الطَّبِيبِ لِفَحْصِ الْمَرْضَى وَالْمُكُوثِ بِهَا فَتْر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22075, 'مَعَادٌ', 'معاد', 'مصدر', 'عود', 'معاد', 'معد', 'مص. عَادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَعَادٌ-مَعَادٌ [ع و د] (مص. عَادَ). 1.""إِلَيْهِ الْمَعَادُ"" : الْمَرْجِعُ، الْمَصِيرُ، الحيَاةُ الأُخْرَى. 2.القصص آية 85 إِن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22076, 'عِدَادٌ', 'عداد', 'مصدر', 'عدد', 'عداد', 'عدد', 'مص. عَادَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عِدَادٌ-عِدَادٌ [ع د د] (مص. عَادَّ). 1.""هُوَ فِي عِدَادِهِمْ "" : أَيْ هُوَ وَاحِدٌ مِنْهُمْ. ""كَانَ فِي عِدَادِ النَّاجِحِينَ"" ""كَانَ في عِدَادِ الْمَوْتَى أَوِ الْمَفْقُودِينَ"". 2.""هُوَ فِي عِدَادِ الْمَوْتِ"" : فِي وَقْتِ الْمَوْتِ. 3.""هَذَا عِدَادُ الْحُمَّى"": وَقْتُهَا الَّذِي تَعُودُ فِيهِ. 4.""هَذَا يَوْمُ عِدَادٍ"" : يَوْمُ جُمُعَةٍ أَوْ يَوْمُ أضْحَى أَوْ يَوْمُ فِطْرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22077, 'مُعَادَلَةٌ', 'معادلة', 'مصدر', 'عدل', 'معادلة', 'معدلة', 'مص. عَادَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. عَادَلَ). 1.""مُعَادَلَةٌ بَيْنَ العَمَلَيْنِ"" : مُسَاوَاةٌ، مُوَازَنَةٌ بَيْنَهُمَا. 2.""مُعَادَلَةٌ جَبْرِيَّةٌ"" : مُتَسَاوِيَةٌ فِيهَا مَجْهُولٌ أَوْ أَكْثَرُ يُطْلَبُ اسْتِخْرَاجُهُ. 3.""الْمُع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22078, 'عِدَاءٌ', 'عداء', 'مصدر', 'عدو', 'عداء', 'عد', 'مص. عَادَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"عَدَاءٌ-عَدَاءٌ [ع د و] (مص. عَدَا). 1.""يَسُودُ بَيْنَهُمَا عَدَاءٌ شَدِيدٌ "" : عَدَاوَةٌ، خُصُومَةٌ. 2. : شُغْلٌ يَصْرِفُكَ عَنِ الشَّيْءِ. 3.""عَدَا الْفَرَسُ عَدَاءً وَاحِداً"" : شَوْطاً وَاحِداً مِنَ الْعَدْوِ. 4.""عَدَاءُ الْخَنْدَقِ أَوِ الْوَادِي"" : بَطْنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22079, 'مُعَادَاةٌ', 'معاداة', 'مصدر', 'عدي', 'معاداة', 'معدة', 'مص. عَادَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَادَاةٌ-مُعَادَاةٌ [ع د ي] (مص. عَادَى). ""أَظْهَرَ مُعاداتَهُ"" : عَنْ عَدَاوَتِهِ، مُخَاصَمَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22080, 'عِيَاذٌ', 'عياذ', 'مصدر', 'عوذ', 'عياذ', 'عذ', 'مص. عَاذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عِيَاذٌ-عِيَاذٌ [ع و ذ] (مص. عَاذَ). 1.""الْعِيَاذُ بِاللَّهِ مِنْكَ"" : أَعُوذُ بِاللَّهِ مِنْكَ. 2.""هُوَ عِيَاذُهُ"" : مَلْجَأُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22081, 'مَعَاذٌ', 'معاذ', 'مصدر', 'عوذ', 'معاذ', 'معذ', 'مص. عَاذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَعَاذٌ-مَعَاذٌ [ع و ذ] (مص. عَاذَ). 1.""لَجَأَ إِلَى الْمَعَاذِ"" : الْمَلْجَإِ. 2.""مَعَاذَ اللهِ أَنْ أَخُونَ أَوْ أَكْذِبَ"" : أَعُوذُ بِاللهِ مِنْ ذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22082, 'مُعَارَضَةٌ', 'معارضة', 'مصدر', 'عرض', 'معارضة', 'معرضة', 'مص. عَارَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَارَضَةٌ-مُعَارَضَةٌ [ع ر ض] (مص. عَارَضَ). 1.""كَانَتْ مُعَارَضَتُهُ شَدِيدَةَ اللَّهْجَةِ"" : الاحْتِجَاجُ، الْمُخَالَفَةُ، الْمُمَانَعَةُ. 2.""الْمُعَارَضَةُ السِّيَاسِيَّةُ"" : انْتِقَادُ حِزْبٍ مِنَ الأَحْزَابِ أَوْ فِئَةٍ بَرْلَمَانِيَّةٍ لِأَعْمَالِ الحُكُومَةِ وَالتَّصَدِّي لَهَا بِإِظْهَارِ عُيُوبِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22083, 'عِرَاكٌ', 'عراك', 'مصدر', 'عرك', 'عراك', 'عرك', 'مص. عَارَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عِرَاكٌ-عِرَاكٌ [ع ر ك] (مص. عَارَكَ). ""اِشْتَدَّ الْعِرَاكُ بَيْنَهُمَا"": الخِصَامُ، الْقِتَالُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22084, 'عِيشَةٌ', 'عيشة', 'مصدر', 'عيش', 'عيشة', 'عشة', 'مص. عَاشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عِيشَةٌ-عِيشَةٌ [ع ي ش] (مص. عَاشَ). ""هُوَ فِي عِيشَةِ بُؤْسٍ وَحِرْمَانٍ"" : و"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22085, 'عَيْشٌ', 'عيش', 'مصدر', 'عيش', 'عيش', 'عش', 'مص. عَاشَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَيْشٌ-عَيْشٌ [ع ي ش] (مص. عَاشَ). 1.""هُوَ فِي عَيْشٍ رَغِيدٍ"" : مَا يَعِيشُهُ الإِنْسَانُ فِي حَيَاتِهِ وَيَكُونُ بِهِ. ""يَشْكُو مِنْ قَسْوَةِ الْعَيْشِ"". 2."""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22086, 'مَعَاشٌ', 'معاش', 'مصدر', 'عيش', 'معاش', 'معش', 'مص. عَاشَ', '', '', 'مفرد', 'DnN', '', '', '"مَعَايِشُ:مَعَاشَاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَاشَ). 1.""يَعْمَلُ لِمَعَاشِهِ"" : مَا يَعِيشُ بِهِ الْمَرْءُ مِنَ الطَّعَامِ وَالشَّرَابِ. 2.""يَبْحَثُ عَنْ مَعَاشٍ"" : عَنْ وَسِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22087, 'مَعَايِشُ', 'معايش', 'مصدر', '', 'معايش', 'معش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22088, 'مَعَاشَاتٌ', 'معاشات', 'مصدر', '', 'معاشات', 'معشت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22089, 'مَعِيشَةٌ', 'معيشة', 'مصدر', 'عيش', 'معيشة', 'معشة', 'مص. عَاشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَعَايِشُ:مَعَائِشُ"', '', 'R', '', '', '', '', '', '', '"(مص. عَاشَ). 1.""يَعِيشُ مَعِيشَةً كَرِيمَةً"" : مَا يَعِيشُ بِهِ الإِنْسَانُ مِنْ طَعَامٍ وَشَرَابٍ.الزخرف آية 32نَحْنُ قَسَمْنَا بَيْنَهُمْ مَعِيشَتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22090, 'مَعَايِشُ', 'معايش', 'مصدر', '', 'معايش', 'معش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22091, 'مَعَائِشُ', 'معائش', 'مصدر', '', 'معاءش', 'معش', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22092, 'مُعَاشَرَةٌ', 'معاشرة', 'مصدر', 'عشر', 'معاشرة', 'معشرة', 'مص. عَاشَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَاشَرَةٌ-مُعَاشَرَةٌ [ع ش ر] (مص. عَاشَرَ). 1.""تَجَنَّبْ مُعَاشَرَةَ أَهْلِ السُّوءِ"" : مُخَالَطَةٌ. 2.""مُعَاشَرَةُ الصِّحَابِ"" : مُصَاحَبَتُهُمْ. 3.""مُعَاشَرَةُ الزَّوْجَيْنِ"" : مُسَاكَنَتُهُمَا. ""رَجُلٌ سَهْلُ الْمُعَاشَرَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22093, 'مُعَاصَرَةٌ', 'معاصرة', 'مصدر', 'عصر', 'معاصرة', 'معصرة', 'مص. عَاصَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَاصَرَةٌ-مُعَاصَرَةٌ [ع ص ر] (مص. عَاصَرَ). ""تَدْعو أفْكارُ الكاتِبِ إلى المُعاصَرةِ"" : أَي التَّكَيُّفُ مَعَ أَفْكارِ العَصْرِ الَّذِي نَعيشُهُ. ""الْمُعاصَرَةُ وَالأَصالَةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22094, 'عِوَضٌ', 'عوض', 'مصدر', 'عوض', 'عوض', 'عض', 'مص. عَاضَ', '', '', 'مفرد', 'DnN', '', '', '"أَعْوَاضٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَاضَ). 1.""يَبْحَثُ عَنْ عِوَضٍ لِخَسَارَتِهِ"" : عَنْ بَدَلٍ، عَنْ خَلَفٍ. ""لاَ أَقْدِرُ عَلَى الافْتِد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22095, 'أَعْوَاضٌ', 'أعواض', 'مصدر', '', 'ءعواض', 'عض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22096, 'عِفَاءٌ', 'عفاء', 'مصدر', 'عفو', 'عفاء', 'عف', 'مص. عَافَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"عَفَاءٌ-عَفَاءٌ [ع ف و] (مص. عَفَا). 1.""عَفَاءُ الشَّيْءِ"" : هَلاَكُهُ، زَوَالُهُ. ""عَلَى الدُّنْيَا العَفَاءُ"". 2.""عَفَاءُ الأَرْضِ"" : تُرَابُهَا. 3.""عَفَاءُ الْحَدَقَةِ"" : بَيَاضُهَا. 4.""نَزَلَ العَفَاءُ"" : الْمَطَرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22097, 'مُعَافَاةٌ', 'معافاة', 'مصدر', 'عفو', 'معافاة', 'معفة', 'مص. عَافَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَافَاةٌ-مُعَافَاةٌ [ع ف و] (مص. عَافَى). ""هُوَ فِي مُعَافَاةٍ مِنْ كُلِّ بَلاَءٍ"" : مَنْ دُفِعَ عَنْهُ كُلُّ عِلَّةٍ وَبَلاَءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22098, 'عِقَابٌ', 'عقاب', 'مصدر', 'عقب', 'عقاب', 'عقب', 'مص. عَاقَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عِقَابٌ-عِقَابٌ [ع ق ب] (مص. عَاقَبَ). ""عَاقَبَهُ عِقَاباً شَدِيداً"": مَا يُعَاقَبُ بِهِ الْمُذْنِبُ، الْجَزَاءُ بِالشَّرِّ أَوِ الضَّرْبِ. ""اِسْتَحَقَّ عَلَى فِعْلِهِ السَّيِّئِ عِقَاباً"" ""يُمْنَعُ العِقَابُ البَدَنِيُّ مَنْعاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22099, 'مُعَاقَبَةٌ', 'معاقبة', 'مصدر', 'عقب', 'معاقبة', 'معقبة', 'مص. عَاقَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَاقَبَةٌ-مُعَاقَبَةٌ [ع ق ب] (مص. عَاقَبَ). ""مُعَاقَبَةُ الأَشْرَارِ"": العِقَابُ، القِصَاصُ، التَّأْدِيبُ، العُقُوبَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22100, 'مُعَاكَسَةٌ', 'معاكسة', 'مصدر', 'عكس', 'معاكسة', 'معكسة', 'مص. عَاكَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَاكَسَةٌ-مُعَاكَسَةٌ [ع ك س] (مص. عَاكَسَ). ""مُعَاكَسَةُ الأُمُورِ فِي غَيْرِ زَمَانِهَا مَفْسَدَةٌ لِسَيْرِ الْحَيَاةِ"" : الْمُمَانَعَةُ، الْمُخَالَفَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22101, 'عَيْلَةٌ', 'عيلة', 'مصدر', 'عيل', 'عيلة', 'علة', 'مص. عَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عَيْلَةٌ-عَيْلَةٌ [ع ي ل] (مص. عَالَ). ""هُوَ فِي عَيْلَةٍ"" : فِي فَقْرٍ، فِي حَاجَةٍ، اِحْتِيَاجٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22102, 'مُعَالَجَةٌ', 'معالجة', 'مصدر', 'علج', 'معالجة', 'معلجة', 'مص. عَالَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَالَجَةٌ-مُعَالَجَةٌ [ع ل ج] (مص. عَالَجَ). 1.""مُعَالَجَةُ الْمَرِيضِ"": مُدَاوَاتُهُ. 2.""مُعَالَجَةُ الْمَوَادِّ الأَوَّلِيَّةِ"" : تَحْلِيلُهَا وَسَبْرُهَا. 3.""مُعَالَجَةُ الإِعْلاَمِ"" : اِسْتِعْمَالُ الْحَوَاسِيبِ لِتَحْقِيقِ عَمَلِيَّاتٍ مُعَقَّدَةٍ تَهْدِفُ إِلَى غَايَاتٍ وَنَتَائِجَ عِلْمِيَّةٍ. 4.""يَنْبَغِي مُعَالَجَةُ الأُمُورِ بِالأَنَاةِ وَالصَّبْرِ"" : مُعَامَلَتُهَا وَالتَّعَامُلُ مَعَهَا..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22103, 'مُعَامَلَةٌ', 'معاملة', 'مصدر', 'عمل', 'معاملة', 'معملة', 'مص. عَامَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. عَامَلَ). 1.""عَامَلَهُ مُعَامَلَةً حَسَنَةً"" : عَامَلَهُ بِتَصَرُّفٍ حَسَنٍ، بِسُلُوكٍ... ""حُسْنُ الْمُعَامَلَةِ"" ""سُوءُ الْمُعَامَلَةِ"". 2."" مُعَامَلَةٌ بِالمِثْلِ"" : الْمُبَادَلَةُ. ""عَامَلَهُ مُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22104, 'عِنَانٌ', 'عنان', 'مصدر', 'عنن', 'عنان', 'عنن', 'مص. عَانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَعِنَّةٌ:عُنُنٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَانَ). 1.""عِنَانُ الجَوَادِ"" : سَيْرُ اللِّجَامِ. ""يُمْسِكُ فِي قُوَّةٍ وَثِيقَةٍ بِعِنَانِ فَرَسٍَشَهْبَاءَ"". (ع. غلاب). 2.""أَطْلَقَ لَهُ الْعِنَانَ"" : أَطْلَقَ لَهُ حُرِّيَّةَ الْعَمَلِ. ""أَطْلَقَ لِنَفْسِهِ الْعِنَانَ"" ""أَطْلَقَ لِغَضَبِهِ الْعِنَانَ"". 3.""هُوَ طَوِيلُ الْعِنَانِ"" : شَرِيفٌ عَظِيمُ السُّؤْدُدِ. 4.""هُوَ قَصِيرُ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22105, 'أَعِنَّةٌ', 'أعنة', 'مصدر', '', 'ءعنة', 'عنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22106, 'عُنُنٌ', 'عنن', 'مصدر', '', 'عنن', 'عن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22107, 'عِنَادٌ', 'عناد', 'مصدر', 'عند', 'عناد', 'عند', 'مص. عَانَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عِنَادٌ-عِنَادٌ [ع ن د] (مص. عَانَدَ). ""كَثِيرُ الْعِنَادِ"" : كَثِيرُ الْخِلاَفِ، اللِّجَاجِ. ""كَانَ أَكْثَرَ عِنَاداً مِنْ أَنْ يُطِيعَ"". (ع. غلاب) ""الْعِنَادُ فِي غَيْرِ قِتَالٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22108, 'مُعَانَدَةٌ', 'معاندة', 'مصدر', 'عند', 'معاندة', 'معندة', 'مص. عَانَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَانَدَةٌ-مُعَانَدَةٌ [ع ن د] (مص. عَانَدَ). ""مُعَانَدَةُ الصِّبْيَانِ مَسْأَلَةٌ طَبِيعِيَّةٌ"" : الْمُخَالَفَةُ، الْمُعَارَضَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22109, 'عِنَاقٌ', 'عناق', 'مصدر', 'عنق', 'عناق', 'عنق', 'مص. عَانَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عِنَاقٌ-عِنَاقٌ [ع ن ق] (مص. عَانَقَ). ""عِنَاقٌ حَارٌّ"" : ضَمُّ الْعُنُقِ إِلَى الْعُنُقِ وَالصَّدْرِ إِلَى الصَّدْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22110, 'عَوْنٌ', 'عون', 'مصدر', 'عون', 'عون', 'عن', 'مص. عَانَ، يَعُونُ', '', '', 'مفرد', 'DnN', '', '', '"أَعْوَانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَانَ، يَعُونُ). يُسْتَعْمَلُ لِلْوَاحِدِ وَالْجَمْعِ وَالْمُذَكَّرِ وَالْمُؤَنَّثِ. ""لاَ عَوْنَ لَهُ"" : لاَ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22111, 'أَعْوَانٌ', 'أعوان', 'مصدر', '', 'ءعوان', 'عن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22112, 'عَيْنٌ', 'عين', 'مصدر', 'عين', 'عين', 'عن', 'مص. عَانَ، يَعِينُ', '', '', 'مفرد', 'DnN', '', '', '"عُيُونٌ:أَعْيُنٌ:أَعْيَانٌمُث', '', 'R', '', '', '', '', '', '', '"(مص. عَانَ، يَعِينُ). 1.""رَآهُ بِالعَيْنِ الْمُجَرَّدَةِ"" : عُضْوُ الإِبْصَارِ للإِنْسَانِ وَالْحَيَوَانِ، وَلَهَا مَعَانٍ مَجَازِيَةٌ كَثِيرَةٌ. 2.""رَآهُ بِأُمِّ عَيْنِهِ"" : رَآهُ رُؤْيَةً لاَ شَكَّ فِيهَا. 3.""سَقَطَ مِنْ عَيْنِهِ"" : فَقَدَ احْتِرَامَهُ وَمَكَانَتَهُ . 4.""مَلأَ عَيْنَهُ"" : كَانَ مَحَلَّ إِعْجَابٍ وَتَقْدِيرٍ. 5.""قُرَّتْ عَيْنُهُ"" : سُرَّ، اِبْتَهَجَ. ""قَرِيرُ العَيْنِ"". 6.""أَقَرَّ اللَّهُ بِكَ عَيْناً"" : أَنْعَمَهَا. ""أَقَرَّ بِكَ عَيْنَ مَنْ تُحِبُّهُ"" ""أَقَرَّ عَيْنَكَ بِمَنْ تُحِبُّهُ"". 7.""فِي طَرْفَةِ عَيْنٍ"": بِسُرْعَةٍ فَائِقَةٍ. 8.""لَهُ عَيْنٌ نَافِذَةٌ"" : بَصِيرَةٌ بِالأَشْيَاءِ. 9.""عَلَى الرَّأْسِ وَالعَيْنِ"" : عَلَى السَّعَةِ وَالرَّحْبِ. ""أَنْتَ عَلَى عَيْنِي"". 10.""أَصْبَحَ خَبَراً بَعْدَ عَيْنٍ"" : اِنْدَثَرَ بَعْدَمَا كَانَ عِيَاناً. ""أَصْبَحَ أَثَراً بَعْدَ عَيْنٍ"" ""لاَ تَطْلُبْ أَثَراً بَعْدَ عَيْنٍ"" (مثل) : يُضْرَبُ لِمَنْ تَرَكَ شَيْئاً يَرَاهُ ثُمَّ تَبِعَ أَثَرَهُ بَعْدَ فَوْتِهِ. 11.""أَدَّى الثَّمَنَ بِالعَيْنِ"" : نَقْداً. 12.""أَصَابَتْهُ العَيْنُ"" : تَعَرَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22113, 'عُيُونٌ', 'عيون', 'مصدر', '', 'عيون', 'عن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22114, 'أَعْيُنٌ', 'أعين', 'مصدر', '', 'ءعين', 'عن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22115, 'أَعْيَانٌ', 'أعيان', 'مصدر', '', 'ءعيان', 'عن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22116, 'مُعَاهَدَةٌ', 'معاهدة', 'مصدر', 'عهد', 'معاهدة', 'معهدة', 'مص. عَاهَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. عَاهَدَ). ""وَقَّعَ الْمُتَحَارِبُونَ مُعَاهَدَةَ صُلْحٍ"" : اتِّفَاقَ صُلْحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22117, 'مُعَاوَدَةٌ', 'معاودة', 'مصدر', 'عود', 'معاودة', 'معدة', 'مص. عَاوَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَاوَدَةٌ-مُعَاوَدَةٌ [ع و د] (مص. عَاوَدَ). ""مُعَاوَدَةُ مَرَضٍ"" : عَوْدَةُ الْمَرَضِ إِلَى حَالَتِهِ الأُولَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22118, 'مُعَاوَنَةٌ', 'معاونة', 'مصدر', 'عون', 'معاونة', 'معنة', 'مص. عَاوَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَاوَنَةٌ-مُعَاوَنَةٌ [ع و ن] (مص. عَاوَنَ). ""اِذْهَبْ لِمُسَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22119, 'عَبَثٌ', 'عبث', 'مصدر', 'عبث', 'عبث', 'عبث', 'مص. عَبِثَ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"عَبَثٌ-عَبَثٌ [ع ب ث] (مص. عَبِثَ). 1.""كُلُّ مَا قَامَ بِهِ كَانَ عَبَثاً"" : لاَ فَائِدَةَ فِيهِ، بِلا مَعْنـىً.المؤمنون آية 115أَفَحَسِبْتُمْ أَنَّمَا "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22120, 'مُعَايَدَةٌ', 'معايدة', 'مصدر', 'عود', 'معايدة', 'معدة', 'مص. عَايَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. عَايَدَ). ""مُعَايَدَةُ الأَهْلِ"" : تَهْنِئَتُهُمْ بِالعِيدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22121, 'عِيَارٌ', 'عيار', 'مصدر', 'عير', 'عيار', 'عر', 'مص. عَايَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. عَايَرَ). 1.""عِيَارُ الأَوْزَانِ وَالْمَكَايِيلِ"" : مَا تُقَدَّرُ بِهِ... 2.""عِيَارُ النَّقْدِ"" : مَا جُعِلَ قِيَاساً وَنِظَاماً لَهُ. ""عِيَارُ السَّبَائِكِ"". 3.""عِيَارُ الدَّرَاهِمِ"": مِقْد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22122, 'مُعَايَرَةٌ', 'معايرة', 'مصدر', 'عير', 'معايرة', 'معرة', 'مص. عَايَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَايَرَةٌ-مُعَايَرَةٌ [ع ي ر] (مص. عَايَرَ). 1.""مُعَايَرَةُ الْمِكْيَالَيْنِ"": التَّأَكُّدُ مِنْ تَسَاوِيهِمَا. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22123, 'مُعَايَشَةٌ', 'معايشة', 'مصدر', 'عيش', 'معايشة', 'معشة', 'مص. عَايَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَايَشَةٌ-مُعَايَشَةٌ [ع ي ش] (مص. عَايَشَ). ""مُعَايَشَةُ النَّاسِ ضَرُورَةٌ اِجْتِمَاعِيَّةٌ"" : العَيْشُ مَعَهُمْ وَالانْدِمَاجُ في حَيَاتِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22124, 'عِيَانٌ', 'عيان', 'مصدر', 'عين', 'عيان', 'عن', 'مص. عَايَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عَيَّانٌ-عَيَّانٌ [ع ي ن] (صِيغَةُ فَعَّالٌ لِلْمُبَالَغَةِ). 1.""رَجُلٌ عَيَّانٌ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22125, 'مُعَايَنَةٌ', 'معاينة', 'مصدر', 'عين', 'معاينة', 'معنة', 'مص. عَايَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُعَايَنَةٌ-مُعَايَنَةٌ [ع ي ن] (مص. عَايَنَ). 1.""جَاءَ لِمُعَايَنَةِ العَمَلِ"" : جَاءَ لاخْتِبَارِهِ وَفَحْصِهِ. ""لَيْسَ الخَبَرُ كَالْمُعَايَنَةِ"" ""مُعَايَنَةُ الخَبِيرِ"". 2.""مُعَايَنَةٌ طِبِّيَّةٌ"" : الْمُكَاشَفَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22126, 'عُبَابٌ', 'عباب', 'مصدر', 'عبب', 'عباب', 'عبب', 'مص عَبَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عُبَابٌ-عُبَابٌ [ع ب ب] (مص عَبَّ). 1.""شَقَّتِ السَّفِينَةُ عُبَابَ الْبَحْرِ"" : اِرْتِفَاعُ مَوْجِ الْبَحْرِ وَاصْطِخَابُهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22127, 'عَبٌّ', 'عب', 'مصدر', 'عبب', 'عب', 'عب', 'مص. عَبَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَبٌّ-عَبٌّ [ع ب ب] (مص. عَبَّ). 1. ""فَاجَأَهُ الْعَبُّ"" : الْبَرْدُ. 2. ""عَبُّ الشَّمْسِ"" : ضَوْؤُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22128, 'تَعْبِئَةٌ', 'تعبئة', 'مصدر', 'عبأ', 'تعبءة', 'تعبة', 'مص. عَبَّأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَعْبِئَةٌ-تَعْبِئَةٌ [ع ب أ] (مص. عَبَّأَ). 1.""تَعْبِئَةُ الصُّنْدُوقِ بِالْمَلاَبِسِ"" : مَلْؤُهُ. 2.""يَنْبَغِي تَعْبِئَةُ الجُمْهُورِ لِخِدْمَةِ الوَطَنِ"": تَجْهِيزُهُمْ وَتَهْيِيؤُهُمْ، أَيْ جَعْلُهُمْ فِي حَالَةِ اسْتِعْدَادٍ وَاسْتِنْفَارٍ وَتَأَهُّبٍ لِخِدْمَةِ الوَطَنِ. ""أُعْلِنَ عَنِ التَّعْبِئَةِ العَامَّةِ فِي الجَيْشِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22129, 'عَبَسٌ', 'عبس', 'مصدر', 'عبس', 'عبس', 'عبس', 'مص. عَبِسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَبِسَ-عَبِسَ [ع ب س] (ق: ثلا. لازم، م. بحرف). عَبِسَ، يَعْبَسُ، مص. عَبَسٌ. 1.""عَبِسَ الرَّجُلُ"": اِتَّسَخَ. ""عَبِسَ الثَّوْبُ"". 2.""عَبِسَ الْوَسَخُ عَلَيْهِ أَوْ فِيهِ"" : يَبِسَ. 3.""عَبِسَ الْجَمَلُ"" : كَانَ بِهِ الْعَبَسُ، أَيْ مَا يَبِسَ عَلَى أَذْنَابِهَا مِنْ أَبْعَارٍ وَأَبْوَالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22130, 'تَعْبِيدٌ', 'تعبيد', 'مصدر', 'عبد', 'تعبيد', 'تعبد', 'مص. عَبَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْبِيدٌ-تَعْبِيدٌ [ع ب د] (مص. عَبَّدَ). 1.""لاَ حَقَّ لَهُ فِي تَعْبِيدِ النَّاسِ"" : فِي تَصْيِيرِهِمْ عَبِيداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22131, 'عُبُودِيَّةٌ', 'عبودية', 'مصدر', 'عبد', 'عبودية', 'عبدة', 'مص. عَبَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عُبُودِيَّةٌ-عُبُودِيَّةٌ [ع ب د] (مص. عَبَدَ). ""اِنْتَهَى عَهْدُ العُبُودِيَّةِ"": حَالَةُ العَبِيدِ الْمَحْرُومِينَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22132, 'تَعْبِيرٌ', 'تعبير', 'مصدر', 'عبر', 'تعبير', 'تعبر', 'مص. عَبَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَعَابِيرُ"', '', 'R', '', '', '', '', '', '', '"(مص. عَبَّرَ). 1.""يَمْتَازُ بِقُوَّةِ التَّعْبِيرِ"" : الصِّيَاغَةُ ذَاتُ نَبْرَةٍ وَدَلاَلَةٍ، العِبَارَةُ. ""جَاءَ بِتَعَابِيرَ جَدِيدَةٍ"". 2.""بِتَعْبِيرٍ آخَرَ"" : بِعِبَارَةٍ أُخْرَى، بِشَكْلٍ آخَرَ. 3.""إِذَا جَازَ التَّعْبِيرُ"" : إِذَا جَازَ وَصَحَّ القَوْلُ وَالكَلاَمُ. ""لِكُلِّ شَخْصٍ الحَقُّ فِي حُرِّيَّةِ الرَّأْيِ وَالتَّعْبِيرِ"". 4.""تَعَابِيرُ الوَجْهِ"" : قَسَمَاتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22133, 'تَعَابِيرُ', 'تعابير', 'مصدر', '', 'تعابير', 'تعبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22134, 'عِبَارَةٌ', 'عبارة', 'مصدر', 'عبر', 'عبارة', 'عبرة', 'مص. عَبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. عَبَرَ). 1.""عِبَارَةٌ جَمِيلَةٌ"" : مَجْمُوعَةٌ مِنَ الأَلْفَاظِ، جُزْءٌ مِنْ جُمْلَةٍ تُؤَدِّي مَعْنىً. ""يَخْتَاُر أَحْسَنَ الْعِبَارَاتِ"" ""عَلَى الطَّالِبِ أَنْ يَتَجَنَّبَ الْعِبَارَاتِ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22135, 'عَبْرٌ', 'عبر', 'مصدر', 'عبر', 'عبر', 'عبر', 'مص. عَبَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَبْرٌ-عَبْرٌ [ع ب ر] (مص. عَبَرَ). ""تَنَقَّلَ عَبْرَ الْقُرَى"" : وَسَطَ. ""ظَلَّتِ الث"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22136, 'عُبُورٌ', 'عبور', 'مصدر', 'عبر', 'عبور', 'عبر', 'مص. عَبَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عُبُورٌ-عُبُورٌ [ع ب ر] (مص. عَبَرَ). ""يَنْتَظِرُ الْعُبُورَ إِلَى الضِّفَّةِ الأُخْرَى"" : الاِنْتِقَالُ مِنْ مَكَانٍ إِلَى آخَرَ عَبْرَ طَرِيقٍ، أَوْ مَا بَيْنَ ضِفَّتَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22137, 'تَعْبِيسٌ', 'تعبيس', 'مصدر', 'عبس', 'تعبيس', 'تعبس', 'مص. عَبَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْبِيسٌ-تَعْبِيسٌ [ع ب س] (مص. عَبَّسَ). ""تَعْبِيسُ الوَجْهِ"" : تَكْشِيرُهُ، تَقْطِيبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22138, 'عَبَسٌ', 'عبس', 'مصدر', 'عبس', 'عبس', 'عبس', 'مص. عَبِسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَبَسٌ-عَبَسٌ [ع ب س] (مص. عَبِسَ). ""عَبَسُ الجِمَالِ"" : مَا يَبِسَ عَلَى أَذْنَابِهَا مِنْ أَبْعَارٍ وَأَبْوَالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22139, 'عَجَلٌ', 'عجل', 'مصدر', 'عجل', 'عجل', 'عجل', 'مص. عَجِلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَجَلٌ-عَجَلٌ [ع ج ل] (مص. عَجِلَ). "" مَرَّ عَلَى عَجَلٍ"" : بِسُرْعَةٍ. ""دَعَتْهَا إِلَى اِرْتِدَاءِ ثِيَابِهَا عَلَى عَجَلٍ"". (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22140, 'تَعْتِيبٌ', 'تعتيب', 'مصدر', 'عتب', 'تعتيب', 'تعتب', 'مص. عَتَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْتِيبٌ-تَعْتِيبٌ [ع ت ب] (مص. عَتَّبَ). ""تَعْتِيبُ البَابِ"" : جَعْلُ عَتَبَةٍ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22141, 'عِتَابٌ', 'عتاب', 'مصدر', 'عتب', 'عتاب', 'عتب', 'مص. عَتَبَ، عَاتَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عِتَابٌ-عِتَابٌ [ع ت ب] (مص. عَتَبَ، عَاتَبَ). ""وَجَّهَ إِلَيْهِ عِتَاباً"" : لَوْماً، مَلاَمَةً، مُؤَاخَذَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22142, 'تَعْتِيقٌ', 'تعتيق', 'مصدر', 'عتق', 'تعتيق', 'تعتق', 'مص. عَتَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْتِيقٌ-تَعْتِيقٌ [ع ت ق] (مص. عَتَّقَ). ""تَعْتِيقُ الخَمْرِ"" : تَرْكُهَا لِتَقْدُمَ وَتَطِيبَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22143, 'عِتْقٌ', 'عتق', 'مصدر', 'عتق', 'عتق', 'عتق', 'مص. عَتَقَ، عَتُقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عِتْقٌ-عِتْقٌ [ع ت ق] (مص. عَتَقَ، عَتُقَ). 1. : نَجَابَةٌ، شَرَفٌ. 2.""عِتْقُ رَقَبَةٍ"" : تَحْرِيرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22144, 'عَتَاهَةٌ', 'عتاهة', 'مصدر', 'عته', 'عتاهة', 'عتهة', 'مص. عَتِهَ، عُتِهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عَتَاهَةٌ-عَتَاهَةٌ [ع ت هـ] (مص. عَتِهَ، عُتِهَ). ""بِهِ عَتَاهَةٌ"" : حُمْقٌ، ضَلاَلٌ، أَوْ فِي عَقْلِهِ ضَعْفٌ مُكْتَسَبٌ غَيْرُ وِرَاثِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22145, 'عَجَبٌ', 'عجب', 'مصدر', 'عجب', 'عجب', 'عجب', 'مص. عَجِبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَجَبٌ-عَجَبٌ [ع ج ب] (مص. عَجِبَ). 1.""يَا لَلْعَجَبِ!"" : يَا لَهُ مِنْ أَمْرٍ عَجِيبٍ، أَيْ مَا يَسُرُّ النَّفْسَ، يُسْتَعْظَمُ أَوْ يُسْتَظْرَفُ أَوْ يُسْتَغْرَبُ. ""إِنَّهُ لأَمْرٌ عَجَبٌ"". 2.""لاَ عَجَبَ فِي ذَلِكَ"": لاَ شَيْءَ يُثِيرُ الاِسْتِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22146, 'عَجْزٌ', 'عجز', 'مصدر', 'عجز', 'عجز', 'عجز', 'مص. عَجَزَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَجْزٌ-عَجْزٌ [ع ج ز] (مص. عَجَزَ). ""أَظْهَرَ عَجْزاً"" : ضَعْفاً، عَدَمُ الْقُدْرَةِ عَلَى القِيَامِ بِعَمَلٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22147, 'عَجَلَةٌ', 'عجلة', 'مصدر', 'عجل', 'عجلة', 'عجلة', 'مص. عَجِلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":عَجَلٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَجِلَ). 1.""كَانَ عَلَى عَجَلَةٍ مِنْ أَمْرِهِ"" :حَالَةُ الاِسْتِعْجَالِ، السُّرْعَةُ. ""يَقُودُ سَيَّارَتَهُ عَلَى عَجَلَةٍ"" ""مَا الدَّاعِي إِلَى كُلِّ هَذِهِ الْعَجَلَةِ! "" ""الْعَجَلَةُ مِنَ الشَّيْطَانِ"" ""فِي الْعَجَلَةِ النَّدَامَةُ وَفِي التَّأَنِّي السَّلاَمَةُ"". (م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22148, 'عَجَلٌ', 'عجل', 'مصدر', '', 'عجل', 'عجل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22149, 'عَدَالَةٌ', 'عدالة', 'مصدر', 'عدل', 'عدالة', 'عدلة', 'مص. عَدَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عَدَالَةٌ-عَدَالَةٌ [ع د ل] (مص. عَدَلَ). 1.""قالَتِ الْعَدَالةُ كَلِمَتَهَا فِي الْقَضِيَّةِ الْمَعْرُوضَةِ عَلَيْهَا"" : الْمَحْكَمَةُ وَقُضَاتُهَا. 2.""عَدَالَةٌ اِجْتِمَاعِيَّةٌ"" : الْعَدْلُ وَالإِنْصَافُ الاِجْتِمَاعِيُّ بَيْنَ النَّاسِ. ""الْعُقَلاَءُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22150, 'عُجْمَةٌ', 'عجمة', 'مصدر', 'عجم', 'عجمة', 'عجمة', 'مص. عَجُمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عُجْمَةٌ-عُجْمَةٌ [ع ج م] (مص. عَجُمَ). ""فِي كَلاَمِهِ ع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22151, 'تَعْدَادٌ', 'تعداد', 'مصدر', 'عدد', 'تعداد', 'تعدد', 'مص. عَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْدَادٌ-تَعْدَادٌ [ع د د] (مص. عَدَّ). 1.""يَبْلُغُ تَعْدَادُ سُكَّانِ العَالَمِ العَرَبِيِّ كَذَا مَلْيُونٍ"" : يَبْلُغُ عَدَدُهُمْ... 2. ""تَعْدَادُ السُّكَّانِ"" : إِحْصَاؤُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22152, 'عَدٌّ', 'عد', 'مصدر', 'عدد', 'عد', 'عد', 'مص. عَدَّ', '', '', 'مفرد', 'DnN', '', '', '"أَعْدَادٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَدَّ). ""وَصَلَتْ أَعْدَادٌ غَفِيرَةٌ مِنَ النَّاسِ"" : الْكَثْرَةُ مِنْهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22153, 'أَعْدَادٌ', 'أعداد', 'مصدر', '', 'ءعداد', 'عدد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22154, 'عَدَاءٌ', 'عداء', 'مصدر', 'عدو', 'عداء', 'عد', 'مص. عَدَا', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"عِدَاءٌ-عِدَاءٌ [ع د و] (مص. عَادَى). ""عَدَا الْعَدَّاءُ عِدَاءً وَاحِداً"" : شَوْطاً وَاحِداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22155, 'عُدْوَانٌ', 'عدوان', 'مصدر', 'عدو', 'عدوان', 'عدن', 'مص. عَدَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"عُدْوَانٌ-عُدْوَانٌ [ع د و] (مص. عَدَا). 1.""ضَرَبَهُ ظُلْماً وَعُدْوَاناً"" : جَوْرًا، ظُلْماً. 2.""نَدَّدَ مَجْلِسُ الأَمْنِ بِعُدْوَانِ إِسْرَائِيلَ عَلَى لُبْنَانَ"" : هُجُومٌ، غَزْوٌ عَلَى الأَرْضِ وَالشَّعْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22156, 'عَدْوٌ', 'عدو', 'مصدر', 'عدو', 'عدو', 'عد', 'مص. عَدَا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَدْوٌ-عَدْوٌ [ع د و] (مص. عَدَا). ""عَدَا عَدْوّاً"" : جَرَى جَرْياً. ""كَانَ الْعَدْوُ الشَّيْءَ الْوَحِيدَ الَّذِي أَمْتَازُ بِهِ"". (ع. بنجلون)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22157, 'عَدْوَى', 'عدوى', 'مصدر', 'عدو', 'عدوى', 'عد', 'مص. عَدَا', '', '', 'مفرد', 'Dy', '', 'Pf', '""', 'ممنوع من الصرف', 'R0', '', '', '', '', '', '', '"عَدْوَى-عَدْوَى [ع د و] (مص. عَدَا). ""اِنْتَشَرَ الْجَرَبُ فَأَصَابَتْهُ الْعَدْوَى"" : الدَّاءُ الَّذِي يَنْتَقِلُ مِنْ مَرِيضٍ إِلَى آخَرَ صَحِيحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22158, 'تَعْدِيلٌ', 'تعديل', 'مصدر', 'عدل', 'تعديل', 'تعدل', 'مص. عَدَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْدِيلٌ-تَعْدِيلٌ [ع د ل] (مص. عَدَّلَ). 1. ""لَمْ يُوَافِقْ عَلَى تَعْدِيلِ مَوْضُوعِهِ"" : إِدْخَالُ تَغْيِيرَاتٍ عَلَيْهِ دُونَ الْمَسِّ بِأَفْكَارِهِ العَامَّةِ. 2.""قَرَّرَتِ الوِزَارَةُ تَعْدِيلَ البَرَامِجِ"" : إِدْخَالَ إِصْلاَحَاتٍ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22159, 'عُرُوبَةٌ', 'عروبة', 'مصدر', 'عرب', 'عروبة', 'عربة', 'مص عَرُبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عُرُوبَةٌ-عُرُوبَةٌ [ع ر ب] (مص عَرُبَ). ""يُدَافِعُ عَنِ العُرُوبَةِ وَالإِسْلاَمِ"" : اِسْمُ صِفَةٍ يُرَادُ بِهَا خَصَائِصُ جِنْسِ العَرَبِ وَكَوْنُ الشَّيْءِ عَرَبِيّاً، أَيْ ذَا طَابَعٍ عَرَبِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22160, 'عَدْلٌ', 'عدل', 'مصدر', 'عدل', 'عدل', 'عدل', 'مص. عَدَلَ', '', '', 'مفرد', 'DnN', '', '', '"عُدُولٌ"', '', 'Rp', '', '', '', '', '', '', '"عَدْلٌ-عَدْلٌ [ع د ل] (مص. عَدَلَ). 1.""يَعْرِفُهُ النَّاسُ رَجُلاً عَدْلاً"" : عَادِلاً، مُنْصِفاً. 2.""إِنَّهُ شَاهِدٌ عَدْلٌ"" : شَاهِدٌ مَعْرُوفٌ بِاسْتِقَامَتِهِ، شَهَادَتُهُ لاَ يُعْتَرَضُ عَلَيْهَا. 3.""وَزِيرُ الْعَدْلِ"" : الْمَسْؤُولُ عَنْ قَضَايَا الإِنْصَافِ وَالْعَدَالَةِ، يُشْرِفُ عَلَى الْمَحَاكِمِ وَالْقُضَاةِ وَسَيْرِ السُّجُونِ. 4.""يُقِيمُ الْعَدْلَ بَيْنَ النَّاسِ"" : أَيْ يُقِيمُ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22161, 'عُدُولٌ', 'عدول', 'مصدر', '', 'عدول', 'عدل', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22162, 'عُدُولٌ', 'عدول', 'مصدر', 'عدل', 'عدول', 'عدل', 'مص. عَدَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عُدُولٌ-عُدُولٌ [ع د ل] (مص. عَدَلَ). ""قَرَّرَ الْعُدُولَ عَنِ الْعَمَلِ فِي اللَّيْلِ"" : الْعُزُوفَ عَنْهُ. ""حَمَلَهُ عَلَى الْعُدُولِ عَنْ مُغَامَرَاتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22163, 'عَدَمٌ', 'عدم', 'مصدر', 'عدم', 'عدم', 'عدم', 'مص. عَدِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَدَمٌ-عَدَمٌ [ع د م] (مص. عَدِمَ). 1.""الْوُجُودُ وَالْعَدَمُ"" : نَفْيُ الشَّيْءِ. ""خَرَجَ الإِنْسَانُ مِنَ الْوُجُودِ إِلَى الْعَدَمِ"". 2.""عَدَمُ الاهْتِمَامِ"" : فُقْدَانُ، نَفْيُ الاِهْتِمَامِ. وهِيَ هُنا تَسْبِقُ الْمَصْدَرَ فَتُؤَدِّي مَعْنىً مُضادّاً لِمَعْناهُ. ""عَدَمُ الاسْتِعْمَالِ"" ""عَدَمُ الاِخْتِصَاصِ"" ""عَدَمُ الْكَفَاءةِ"" ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22164, 'عَذْبٌ', 'عذب', 'مصدر', 'عذب', 'عذب', 'عذب', 'مص. عَذَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَذْبٌ-عَذْبٌ [ع ذ ب] (مص. عَذَبَ). 1.""مَاءٌ بَارِدٌ عَذْبٌ"": طَيِّبٌ، سَائِغٌ، زُلاَلٌ. 2.""حَدِيثٌ عَذْبٌ"" : حَدِيثٌ لَهُ وَقْعٌ حَسَنٌ. ""صَوْتٌ عَذْبٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22165, 'عُذُوبَةٌ', 'عذوبة', 'مصدر', 'عذب', 'عذوبة', 'عذبة', 'مص. عَذُبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عُذُوبَةٌ-عُذُوبَةٌ [ع ذ ب] (مص. عَذُبَ). ""عُذُوبَةُ الحَيَاةِ"" : حَلاَوَتُهَا، لَطَافَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22166, 'عَذْقٌ', 'عذق', 'مصدر', 'عذق', 'عذق', 'عذق', 'مص. عَذَقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَذْقٌ-عَذْقٌ [ع ذ ق] (مص. عَذَقَ). : نَخْلَةٌ بِحِمْلِهَا. وَاَلَّذِي أَخْرَجَ الْعَذْقَ مِنَ الْجُرَيْمَةِ (حديث) : أَيِ النَّخْلَةَ مِنَ النَّوَاةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22167, 'عَذْلٌ', 'عذل', 'مصدر', 'عذل', 'عذل', 'عذل', 'مص. عَذَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَذْلٌ-عَذْلٌ، عَذَلٌ [ع ذ ل] (مص. عَذَلَ). 1.""يَا عَاذِلِي هَلاَّ كَفَفْتَ عَنْ عَذْلِي"" : عَنْ مَلاَمَتِي. 2.""سَبَقَ السَّيْفُ الْعَـذَلَ""(مَثَلَ) : يُضْرَبُ لِمَا قَدْ فَاتَ وَلاَ يُسْتَدْرَكُ، وَيَصْعُبُ التَّرَاجُعُ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22168, 'عَرٌّ', 'عر', 'مصدر', 'عرر', 'عر', 'عر', 'مص. عَرَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَرٌّ-عَرٌّ [ع ر ر] (مص. عَرَّ). ""حَيَوَانٌ عَرٌّ"" : أَجْرَبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22169, 'عِرَاضٌ', 'عراض', 'مصدر', '', 'عراض', 'عرض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22170, 'تَعْرِيبٌ', 'تعريب', 'مصدر', 'عرب', 'تعريب', 'تعرب', 'مص. عَرَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْرِيبٌ-تَعْرِيبٌ [ع ر ب] (مص. عَرَّبَ). 1.""أَنْجَزَ تَعْرِيبَ نَصٍّ مِنَ اللُّغَةِ الفَرَنْسِيَّةِ"" : تَرْجَمَتَهُ إِلَى العَرَبِيَّةِ. 2.""تَعْرِيبُ الْمُصْطَلَحَاتِ العِلْمِيَّةِ"": نَقْلُهَا وَوَضْعُهَا بِاللُّغَةِ العَرَبِيَّةِ. ""تَعْرِيبُ التَّعْلِيمِ وَالإِدَارَةِ وَالحَيَاةِ العَامَّةِ ضَرُورَةٌ وَطَنِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22171, 'عَرْبَدَةٌ', 'عربدة', 'مصدر', 'عربد', 'عربدة', 'عربدة', 'مص. عَرْبَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عَرْبَدَةٌ-عَرْبَدَةٌ [ع ر ب د] (مص. عَرْبَدَ). ""أَثَارَتْ عَرْبَدَتُهُ الْجُمْهُورَ"" : سَوءُ الْخُلُقِ وَمَا هُوَ نَاتِجٌ مِنْ أَذَى تَصَرُّفِهِ. ""عَرْبَدَةُ السَّكْرَانِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22172, 'عَرَجٌ', 'عرج', 'مصدر', 'عرج', 'عرج', 'عرج', 'مص. عَرَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عَرَجٌ-عَرَجٌ [ع ر ج] (مص. عَرَجَ). 1.""وَقَفَ عِنْدَ مَصَبِّ الْعَرَجِ"" : النَّهْر، الوَادِي، وَسُمِّيَ بِذَلِكَ لاِنْعِرَاجِهِ. 2.""يَمْشِي مِشْيَةَ الْعَرَجِ"" : مِشْيَةَ الأَعْرَجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22173, 'عَرْشٌ', 'عرش', 'مصدر', 'عرش', 'عرش', 'عرش', 'مص. عَرَشَ', '', '', 'مفرد', 'DnN', '', '', '"أَعْرَاشٌ:عُرُوشٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَرَشَ). 1.""تَوَلَّى عَرْشَ أَسْلاَفِهِ"" : سَرِيرَ الْمُلْكِ، أَيْ رَمْزُ سُلْطَةِ العَائِلَةِ الْمَالِكَةِ. 2.""اِسْتَوَى الْمَلِكُ عَلَى عَرْشِهِ"" : تَمَكَّنَ مِنْ سُلْطَةِ الْمُلْكِ، مَلَكَ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22174, 'أَعْرَاشٌ', 'أعراش', 'مصدر', '', 'ءعراش', 'عرش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22175, 'عُرُوشٌ', 'عروش', 'مصدر', '', 'عروش', 'عرش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22176, 'تَعْرِيضٌ', 'تعريض', 'مصدر', 'عرض', 'تعريض', 'تعرض', 'مص. عَرَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْرِيضٌ-تَعْرِيضٌ [ع ر ض] (مص. عَرَّضَ). ""فَهِمَ مِنْ كَلاَمِهِ تَعْرِيضاً بِهِ"" : تَلْمِيحاً مِنْ غَيْرِ تَصْرِيحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22177, 'عَرْضٌ', 'عرض', 'مصدر', 'عرض', 'عرض', 'عرض', 'مص. عَرَضَ', '', '', 'مفرد', 'DnN', '', '', '"عُرُوضٌ:عِرَاضٌ:أَعْرَاضٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَرَضَ). 1.""يَبْلُغُ عَرْضُ الغُرْفَةِ خَمْسَةَ أَمْتَارٍ"" : مِنْ حَدٍّ إِلَى حَدٍّ، عَكْسُ الطُّولِ. 2.""عَرْضُ الشَّيْءِ"" : سَعَتُهُ. 3.""قَضَى عِنْدَ زَمِيلِهِ عَرْضاً مِنَ اللَّيْلِ"" : سَاعَةً مِنْهُ. 4.""تَقَدَّمَ بِعَرْضٍ لِلْبَائِعِ"" : اِقْتِرَاحٌ أَوَّلِيٌّ. 5.""قَدَّمَ عَرْضاً عَنْ أَحْوَالِ الْبِلاَدِ"" : صُورَةٌ إِجْمَالِيَّةٌ. 6.""العَرْضُ الْمَسْرَحِيُّ"" : الأَدَاءُ. 7.""قَدَّمَ عَرْضاً حَوْلَ تَعْرِيفِ الأَدَبِ"" : أَيْ مُحَاضَرَةً، زُبْدَةً مِنَ الْكَلاَمِ. 8.""شَاهَدَ عَرْضاً عَسْكَرِيّاً"" : مُرُورُ فِرَقٍ نَمُوذَجِيَّةٍ مِنَ القُوَّاتِ الْمُسَلَّحَةِ فِي مُنَاسَبَةٍ مَّا. 9.""عَرْضُ الأَزْيَاءِ"" : تَقْدِيمُ نَمَاذِجَ مِنَ الأَزْيَاءِ أَمَامَ الحَاضِرِينَ. 10.""خُطُوطُ العَرْضِ"" : دَوَائِرُ تُحِيطُ بِالكُرَةِ الأَرْضِيَّةِ، مُوَازِيَةٌ لِخَطِّ الاسْتِوَاءِ. 11.""الْعَرْضُ وَالطَّلَبُ"": مُصْطَلَحٌ اِقْتِصَادِيٌّ يَعْنِي مَا يُعْرَضُ مِنْ بَضَائِعَ فِي السُّوقِ وَمَا يُطْلَبُ شِرَاؤُهُ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22178, 'عُرُوضٌ', 'عروض', 'مصدر', '', 'عروض', 'عرض', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22179, 'عَرْقَلَةٌ', 'عرقلة', 'مصدر', 'عرقل', 'عرقلة', 'عرقلة', 'مص. عَرْقَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":عَرَاقِيلُ"', '', 'R', '', '', '', '', '', '', '"(مص. عَرْقَلَ). 1.""عَرْقَلَةُ السَّيْرِ"" : مَا يَحُولُ دُونَ السَّيْرِ الطَّبِيعِيِّ مِنِ ازْدِحَامٍ وَنَحْوِهِ. 2.""تَغَلَّبَ عَلَىالعَرَاقِيلِ"" : عَلَى صِعَابِ الأُمُورِ، الْمَشَاكِل، الدَّوَاهِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22180, 'أَعْرَاضٌ', 'أعراض', 'مصدر', '', 'ءعراض', 'عرض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22181, 'عِرْفَانٌ', 'عرفان', 'مصدر', 'عرف', 'عرفان', 'عرفن', 'مص عَرَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عِرْفَانٌ-عِرْفَانٌ [ع ر ف] (مص عَرَفَ). ""مِنَ الصِّفَاتِ النَّبِيلَةِ الْعِرْفَانُ بِالْجَمِيلِ"" : الاعْتِرَافُ بِهِ وَشُكْرُ صَاحِبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22182, 'تَعْرِيفٌ', 'تعريف', 'مصدر', 'عرف', 'تعريف', 'تعرف', 'مص. عَرَفَ', '', '', 'مفرد', 'DnN', '', '', '"تَعْرِيفَاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَرَفَ). 1.""إِذَا دَخَلَتْ أَدَاةُ التَّعْرِيفِ (ال) عَلَى كَلِمَةٍ تَجْعَلُهَا مُعَرَّفَةً"" : تَنْقُلُهَا مِنَ النَّكِرَةِ إِلَى الْمَعْرِفَةِ. 2.""تَعْرِيفُ عِلْمٍ"": تَقْدِيمُ إِيضَاحٍ حَوْلَ مَاهِيَتِهِ وَكُنْهِهِ وَمَادَّتِهِ. ""قَدَّمَ تَعْرِيفاً دَقِيقاً لِعِلْمِ الفِيزْيَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22183, 'تَعْرِيفَاتٌ', 'تعريفات', 'مصدر', '', 'تعريفات', 'تعرفت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22184, 'مَعْرِفَةٌ', 'معرفة', 'مصدر', 'عرف', 'معرفة', 'معرفة', 'مص. عَرَفَ', '', '', 'مفرد', 'DnN', '', '', '"مَعَارِفُ"', '', 'Rp', '', '', '', '', '', '', '"(مص. عَرَفَ). 1.""لَهُ مَعْرِفَةٌ دَقِيقَةٌ بِحَيَاةِ السُّكَّانِ"" : لَهُ إِدْرَاكٌ دَقِيقٌ بِحَيَاتِهِمْ. 2.""يَعْرِفُهُ حَقَّ الْمَعْرِفَةِ"" : يَعْرِفُهُ جَيِّداً. 3.""لَهُ مَعْرِفَةٌ مُبَاشِرَةٌ بِالأَشْيَاءِ"" : لَهُ عِلْمٌ بِهَا دونَ وَاسِطَةٍ. 4.""يَطْلُبُ الْمَعْرِفَةَ أَيْنَمَا كَانَتْ"" : الإِدْرَاكَ، كُنْهَ الأَشْيَاءِ وَحَقِيقَتَهَا. ""الْمَعْرِفَةُ العِلْمِيَّةُ"". 5.""الْمَعْرِفَةُ فِي النَّحْوِ"" : الاسْمُ الدَّالُّ عَلَى مُعَيَّنٍ. ن. مَعَارِفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22185, 'مَعَارِفُ', 'معارف', 'مصدر', '', 'معارف', 'معرف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22186, 'عَرْفٌ', 'عرف', 'مصدر', 'عرف', 'عرف', 'عرف', 'مص. عَرُفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَرْفٌ-عَرْفٌ [ع ر ف] (مص. عَرُفَ). ""وَرْدَةٌ طَيِّبَةُ العَـرْفِ"" : طَيِّبَةُ الرَّائِحَةِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22187, 'تَعْرِيقٌ', 'تعريق', 'مصدر', 'عرق', 'تعريق', 'تعرق', 'مص. عَرَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْرِيقٌ-تَعْرِيقٌ [ع ر ق] (مص. عَرَّقَ). 1.""تَعْرِيقُ الْجِسْمِ"": جَعْلُهُ يَعْرَقُ. ""أَدَّى الدَّوَاءُ مَفْعُولَهُ بِتَعْرِيقِةِ"". 2.""تَعْرِيقُ العَصِيرِ"" : مَزْجُهُ بِقَلِيلٍ مِنَ الْمَاءِ الْمَغْلِيِّ لِيُمْكِنَ حِفْظُهُ. 3.""تَعْرِيقُ الشَّجَرِ"" : اِمْتِدَادُ عُرُوقِهِ بِالأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22188, 'عَرَقٌ', 'عرق', 'مصدر', 'عرق', 'عرق', 'عرق', 'مص. عَرِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَرَقٌ-عَرَقٌ [ع ر ق] (مص. عَرِقَ). 1.""يَتَصَبَّبُ العَرَقُ مِنْ جَبِينِهِ"" : مَا يَرْشَحُ مِنْ مَسَامِّ الْجِلْدِ مِنْ غُدَدٍ خَاصَّةٍ. ""أَخَذَتِ الصَّبِيَّ رِعْدَةٌ وَتَصَبَّبَ عَرَقاً"". (طه حسين). 2.""عَرَقُ التَّمْرِ"" : دِبْسُهُ، أَيْ عَسَلُهُ وَتُطْلَقُ كَلِمَةُ العَرَقِ عَلَى شَرَابٍ مُخَمَّرٍ مُقَطَّرٍ مُسْكِرٍ جِدّاً فِي بُلْدَانِ الشَّرْقِ الأَوْسَطِ. 3.""عَرَقُ الْخِلاَلِ"" : مَا يُعْطَى مَوَدَّةً وَمَحَبَّةً. 4.""جَرَى الفَرَسُ عَرَقاً"" : شَوْطاً. 5.""عَرَقُ الأَجِيرِ"" : أَجْرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22189, 'عَزَائِمُ', 'عزائم', 'مصدر', '', 'عزاءم', 'عزم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22190, 'عَرَاقِيلُ', 'عراقيل', 'مصدر', '', 'عراقيل', 'عرقل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22191, 'عُرْيٌ', 'عري', 'مصدر', 'عري', 'عري', 'عر', 'مص. عَرِيَ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عُرْيٌ-عُرْيٌ [ع ر ي] (مص. عَرِيَ) .""فَرَسٌ عُرْيٌ "" : لاَ سَرْجَ لَهُ . "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22192, 'عِزَّةٌ', 'عزة', 'مصدر', 'عزز', 'عزة', 'عزة', 'مص. عَزَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عِزَّةٌ-عِزَّةٌ [ع ز ز] (مص. عَزَّ). 1.""عِزَّةُ النَّفْسِ"" : إبَاؤُهَا، أَنَفَتُهَا، شُمُوخُهَا. 2.""لَهُ العِزَّةُ"" : الغَلَبَةُ، القُوَّةُ.المنافقون آية 8 وَلِلَّهِ العِزَّةُ وَلِرَسُولِهِ وَللمُومِنِين (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22193, 'عِزٌّ', 'عز', 'مصدر', 'عزز', 'عز', 'عز', 'مص. عز', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَزٌّ-عَزٌّ [ع ز ز] (مص. عَزَّ، يَعُزُّ). ""رَجُلٌ عَزٌّ"" : قَوِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22194, 'عَزْفٌ', 'عزف', 'مصدر', 'عزف', 'عزف', 'عزف', 'مص. عَزَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَزْفٌ-عَزْفٌ [ع ز ف] (مص. عَزَفَ). 1.""يُتْقِنُ العَزْفَ عَلَى العُودِ"" : يُتْقِنُ إِحْدَاثَ أَصْوَاتٍ مَوسِيقِيَّةٍ عَلَى العُودِ . 2.""كَانَ عَزْفُ الرِّيَاحِ شَدِيداً"" : أَصْوَاتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22195, 'عُزُوفٌ', 'عزوف', 'مصدر', 'عزف', 'عزوف', 'عزف', 'مص. عَزَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عُزُوفٌ-عُزُوفٌ [ع ز ف] (مص. عَزَفَ). ""عُزُوفٌ عَنِ اللَّهْـوِ"" : زُهْدٌ فِي اللَّهْوِ، الإِنْصِرَافُ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22196, 'عَزِيفٌ', 'عزيف', 'مصدر', 'عزف', 'عزيف', 'عزف', 'مص. عَزَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عَزِيفٌ-عَزِيفٌ [ع ز ف] (مص. عَزَفَ). ""عَزِيفُ الرِّمَالِ"": صَوْتُهَا عِنْدَ هُبُوبِ الرِّيحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22197, 'عَزْمٌ', 'عزم', 'مصدر', 'عزم', 'عزم', 'عزم', 'مص. عَزَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَزْمٌ-عَزْمٌ [ع ز م ] (مص. عَزَمَ). 1.""قَرَّ عَزْمُهُ عَلَى خَوْضِ الْمَعْرَكَةِ"" : قَرَّتْ إِرَادَتُهُ، نِيَّتُهُ عَلَى. 2."" شَدَّدَ العَزْمَ"" : عَقَدَ النِّيَّةَ بِثَبَاتٍ، صَمَّمَ. ""عَيْنَانِ لاَمِعَتَانِ فِيهِمَا عَزْمٌ وَتَصْمِيمٌ"" ""عَلَى قَدْرِ أَهْلِ العَزْمِ تَأْتِي العَزَائِمُ"". (المتنبي). 3.""أُولُو العَزْمِ"" : الَّذِينَ يَصْبِرُونَ.الأحقاف آية 153 فَاصْبِرْ كَمَا صَبَرَ أُولُو العَزْمِ مِنَ الرُّسُلِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22198, 'عَزِيمَةٌ', 'عزيمة', 'مصدر', 'عزم', 'عزيمة', 'عزمة', 'مص. عَزَمَ', '', '', 'مفرد', 'DnN', '', '', '"عَزَائِمُ"', '', 'R', '', '', '', '', '', '', '"(مص. عَزَمَ). 1.""لَهُ عَزِيمَةٌ قَوِيَّةٌ"" : إِرَادَةٌ ثَابِتَةٌ، صَلْبَةٌ. ""اِرْتَسَمَتْ عَلَى مُحَيَّاهُ صَلاَبَةٌ وَقُوَّةٌ وَعَزِيمَةٌ"" ""هِمَّةٌ فِي الرُّوحِ وَعَزِيمَةٌ فِي النَّفْسِ"" . 2.""عَزَائِمُ اللَّهِ"" : فَرَائِضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22199, 'عَزِيمٌ', 'عزيم', 'مصدر', 'عزم', 'عزيم', 'عزم', 'مص. عَزَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عَزِيمٌ-عَزِيمٌ [ع ز م] (مص. عَزَمَ). ""عَدَا عَدْواً عَزِيماً"" : عَدْواً شَدِيداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22200, 'عَزَاءٌ', 'عزاء', 'مصدر', 'عزي', 'عزاء', 'عز', 'مص. عَزِيَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"عَزَاءٌ-عَزَاءٌ [ع ز ي] (مص. عَزِيَ). ""تَقَبَّلَ الشَّيْخُ عَزَاءَ الرِّجَالِ فِي جَلَدٍ"" : مُوَاسَاةَ... ‎ ""لَوْ تَرَكُوهُ لأَحْزَانِهِ لَكَانَ خَيْرَ عَزَاءٍ لَهُ"". (ع. غلاب)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22201, 'تَعْزِيَةٌ', 'تعزية', 'مصدر', 'عزي', 'تعزية', 'تعزة', 'مص. عَزَّى', '', '', 'مفرد', 'DnN', '', '', '"تَعَازٍ:التَّعَازِي"', '', '', '', '', '', '', '', '', '"(مص. عَزَّى). ""جَاءَ لِتَعْزِيَتِهِ"" : لِتَقْدِيمِ العَزَاءِ لَهُ وَالإِعْرَابِ لَهُ عَنْ حُزْنِهِ لِفِقْدَانِ قَرِيبٍ مِنْ أَقْرِبَائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22202, 'تَعَازِي', 'تعازي', 'مصدر', '', 'تعازي', 'تعز', '', 'Tk', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22203, 'عَزٌّ', 'عز', 'مصدر', 'عزز', 'عز', 'عز', 'مص. عَزَّ، يَعُزُّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عِزٌّ-عِزٌّ [ع ز ز ] (مص. عز). 1.""يَعِيشُ فِي عِزٍّ وَسُؤْدُدٍ"": أُبَّهَةٍ وَمَجْدٍ. 2.""سَافَرَ فِي عِزِّ حَرَارَةِ الصَّيْفِ"" : فِي أَوْجِ، فِي أَقْصَى حَرَارَةِ... ""فِي عِزِّ الصَّيْفِ"" ""فِي عِزِّ الشِّتَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22204, 'عَسَسٌ', 'عسس', 'مصدر', 'عسس', 'عسس', 'عس', 'مص. عَسَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَسَسٌ-عَسَسٌ [ع س س] (مص. عَسَّ). ""اِنْتَشَرَ العَسَسُ فِي الأَحْيَاءِ"" : مَنْ يَطُوفُونَ بِاللَّيْلِ يَحْرُسُونَ البُيُوتَ وَيَكْشِفُونَ عَنْ أَهْلِ الرِّيبَةِ وَاللُّصُوصِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22205, 'تَعْسِيرٌ', 'تعسير', 'مصدر', 'عسر', 'تعسير', 'تعسر', 'مص. عَسَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْسِيرٌ-تَعْسِيرٌ [ع س ر] (مص. عَسَّرَ). ""وَجَدَ فِي الأَمْرِ تَعْسِيرًا"" : ضَيْقاً وَعُسْراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22206, 'عُسْرٌ', 'عسر', 'مصدر', 'عسر', 'عسر', 'عسر', 'مص. عَسَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُسْرٌ-عُسْرٌ [ع س ر] (مص. عَسَرَ). ""يَعِيشُ فِي عُسْرٍ"" : فِي ضِيقٍ، فِي شِدَّةٍ، قِلَّةُ ذَاتِ اليَدِ، فِي فَقْرٍ.الشرح آية 6 إِنَّ مَعَ العُسْرِ يُسْراً (قرآن)البقرة آية 185 يُرِيدُ اللَّهُ بِكُمُ اليُسْرَ وَلاَ يُرِيدُ بِكُمُ العُسْرَ (قرآن) ""وَجَدَ عُسْراً فِي التَّعْبِيرِ عَمَّا يُرِيدُ الإِفْصَاحَ عَنْهُ"". (ن. محفوظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22207, 'تَعْسِيفٌ', 'تعسيف', 'مصدر', 'عسف', 'تعسيف', 'تعسف', 'مص. عَسَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْسِيفٌ-تَعْسِيفٌ [ع س ف] (مص. عَسَفَ). ""تَعْسِيفُ البَيْتِ"": تَكْنِيسُ غُبَارِهِ بِمِعْسَفَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22208, 'عَسْفٌ', 'عسف', 'مصدر', 'عسف', 'عسف', 'عسف', 'مص. عَسَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَسْفٌ-عَسْفٌ [ع س ف] (مص. عَسَفَ). 1.""عَمَّ العَسْفُ البِلاَدَ"" : الظُّلْمُ، الْجَوْرُ. 2.""سَارَ عَسْفاً"" : سَارَ سَيْراً بِغَيْرِ هِدَايَةٍ. 3.""لَحِقَهُ العَسْفُ"" : الْمَوْتُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22209, 'عَشٌّ', 'عش', 'مصدر', 'عشش', 'عش', 'عش', 'مص. عَشَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَشٌّ-عَشٌّ [ع ش ش] (مص. عَشَّ). 1.""عَشُّ الطَّائِرِ"" : عُشُّهُ. 2.""رَجُلٌ عَشٌّ"" : ضَعِيفٌ، رَقِيقُ عِظَامِ اليَدِ وَالرِّجْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22210, 'تَعْشِيبٌ', 'تعشيب', 'مصدر', 'عشب', 'تعشيب', 'تعشب', 'مص. عَشَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْشِيبٌ-تَعْشِيبٌ [ع ش ب] (مص. عَشَّبَ) ""تَعْشِيبُ الحَقْلِ"": نَبْتُ العُشْبِ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22211, 'عُشْرٌ', 'عشر', 'مصدر', 'عشر', 'عشر', 'عشر', 'مص. عَشَرَ', '', '', 'مفرد', 'DnN', '', '', '"أَعْشَارٌ:عُشُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَشَرَ). : جُزْءٌ مِنْ عَشَرَةِ أَجْزَاءِ الشَّيْءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22212, 'أَعْشَارٌ', 'أعشار', 'مصدر', '', 'ءعشار', 'عشر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22213, 'عُشُورٌ', 'عشور', 'مصدر', '', 'عشور', 'عشر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22214, 'تَعْشِيشٌ', 'تعشيش', 'مصدر', 'عشش', 'تعشيش', 'تعشش', 'مص. عَشَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْشِيشٌ-تَعْشِيشٌ [ع ش ش] (مص. عَشَّشَ). 1. ""تَعْشِيشُ الطَّائِرِ"" : اِتِّخَاذُهُ عُشّاً. 2.""تَعْشِيشُ الشَّيْطَانِ فِي صَدْرِهِ"" : مُكُوثُهُ بِهِ، وَالْمَقْصُودُ مَلْؤُهُ بِالْغَيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22215, 'عِشْقٌ', 'عشق', 'مصدر', 'عشق', 'عشق', 'عشق', 'مص. عَشِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عِشْقٌ-عِشْقٌ [ع ش ق] (مص. عَشِقَ). ""عِشْقُ امْرَأَةٍ"" : الإِفْرَاطُ فِي حُبِّهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22216, 'تَعْشِيَةٌ', 'تعشية', 'مصدر', 'عشو', 'تعشية', 'تعشة', 'مص. عَشَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَعْشِيَةٌ-تَعْشِيَةٌ [ع ش و] (مص. عَشَّى). ""تَعْشِيَةُ الضَّيْفِ"" : إِطْعَامُهُ العَشَاءَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22217, 'تَعْصِيبٌ', 'تعصيب', 'مصدر', 'عصب', 'تعصيب', 'تعصب', 'مص. عَصَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْصِيبٌ-تَعْصِيبٌ [ع ص ب] (مص. عَصَّبَ). 1.""تَعْصِيبُ الرَّأْسِ"" : شَدُّهُ بِعِصَابَةٍ. 2.""تَعْصِيبُ الأَخِ لأُخْتِهِ"" : تَحْوِيلُهَا مِنْ صَاحِبَةِ فَرْضٍ إِلَى عاصِبَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22218, 'عَصَبٌ', 'عصب', 'مصدر', 'عصب', 'عصب', 'عصب', 'مص. عَصِبَ', '', '', 'مفرد', 'DnN', '', '', '"أَعْصَابٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. عَصِبَ). : أَلْيَافٌ مُنْتَشِرَةٌ فِي الْجِسْمِ بِهَا تَكُونُ الْحَرَكَةُ وَالْحِسُّ، وَهِيَ الَّتِي تَشُدُّ الْمَفَاصِلَ وَتَرْبِطُ بَعْضَهَا بِبَعْضٍ. ""تَوَتَّرَتْ أَعْصَابُهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22219, 'تَعْطِيلٌ', 'تعطيل', 'مصدر', 'عطل', 'تعطيل', 'تعطل', 'مص. عَطَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْطِيلٌ-تَعْطِيلٌ [ع ط ل] (مص. عَطَّلَ). ""حَاوَلَ تَعْطِيلَهُ عَنْ مَوْعِدِ سَفَرِهِ"" : تَأْخِيرَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22220, 'أَعْصَابٌ', 'أعصاب', 'مصدر', '', 'ءعصاب', 'عصب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22221, 'تَعْصِيرٌ', 'تعصير', 'مصدر', 'عصر', 'تعصير', 'تعصر', 'مص. عَصَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْصِيرٌ-تَعْصِيرٌ [ع ص ر] (مص. عَصَّرَ). 1.""تَعْصِيرُ الزَّرْعِ"" : بَدْءُ ظُهُورِ ثَمَرِهِ. 2.""تَعْصِيرُ ثَوْبٍ"" : اِسْتِخْرَاجُ مَا فِيهِ مِنْ مَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22222, 'عَصْفٌ', 'عصف', 'مصدر', 'عصف', 'عصف', 'عصف', 'مص. عَصَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَصْفٌ-عَصْفٌ [ع ص ف] (مص. عَصَفَ). 1.""اِشْتَدَّ عَصْفُ الرِّيحِ"" : اِشْتَدَّ هُبُوبُهَا. 2.""عَصْفُ الزَّرْعِ"" : وَرَقُهُ.الفيل آية 5 فَجَعَلَهُمْ كَعَصْفٍ مَأكوُلٍ (قرآن). 3.""عَصْفُ التِّبْنِ"" : حُطَامُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22223, 'عِصْيَانٌ', 'عصيان', 'مصدر', 'عصي', 'عصيان', 'عصن', 'مص. عَصَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عِصْيَانٌ-عِصْيَانٌ [ع ص ي]. (مص. عَصَى). 1.""عِصْيَانُ الأَوَامِرِ"" : الامْتِنَاعُ عَنْ تَنْفِيذِهَا. 2.""العِصْيَانُ الْمَدَنِيُّ"" : الإِعْلاَنُ عَنْ مُقَاوَمَةِ الْحُكْمِ القَائِمِ وَالوُقُوفُ ضِدَّهُ وَعَدَمُ تَنْفِيذِ القَوَانِينِ وَالأَوَامِرِ. ""قُدِّمُوا لِلْمُحَاكَمَةِ بِتُهْمَةِ العِصْيَانِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22224, 'تَعْطِيرٌ', 'تعطير', 'مصدر', 'عطر', 'تعطير', 'تعطر', 'مص. عَطَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْطِيرٌ-تَعْطِيرٌ [ع ط ر] (مص. عَطَّرَ). ""تَعْطِيرُهُ بِالمِسْكِ"" : تَطْيِيبُهُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22225, 'تَعْطِيسٌ', 'تعطيس', 'مصدر', 'عطس', 'تعطيس', 'تعطس', 'مص. عَطَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْطِيسٌ-تَعْطِيسٌ [ع ط س] (مص. عَطَّسَ). ""كَانَ الزُّكَامُ سَبَباً فِي تَعْطِيسِهِ"" : جَعْلِهِ يَعْطِسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22226, 'تَعْطِيشٌ', 'تعطيش', 'مصدر', 'عطش', 'تعطيش', 'تعطش', 'مص. عَطَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْطِيشٌ-تَعْطِيشٌ [ع ط ش] (مص. عَطَّشَ). 1.""مَنَعَ عَنْهُمُ الْمَاءَ لِتَعْطِيشِهِمْ"" : لِجَعْلِهِمْ فِي عَطَشٍ وَظَمَإٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22227, 'عَطَشٌ', 'عطش', 'مصدر', 'عطش', 'عطش', 'عطش', 'مص. عَطَشَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَطِشٌ-عَطِشٌ [ع ط ش] (صِفَةٌ مُشَبَّهَةٌ). ""رَجُلٌ عَطِشٌ"" : ذُو عَطَشٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22228, 'عَطْفٌ', 'عطف', 'مصدر', 'عطف', 'عطف', 'عطف', 'مص. عَطَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَطْفٌ-عَطْفٌ [ع ط ف] (مص. عَطَفَ). 1.""فِي الطَّرِيقِ عَطْفٌ"" : اِعْوِجَاجٌ وَمَيْلٌ. 2.""أَدَاةُ عَطْفٍ"" : أَدَاةُ رَبْطِ لَفْظٍ بِآخَرَ، وَحُرُوفُ العَطْفِ هِيَ: الوَاوُ، أَوِ الفَاءُ، أَوْ ثُمَّ. 3.""نَظَرَ إِلَيْهِ نظْرَةَ عَطْفٍ"" : حَنَانٍ، شَفَقَةٍ، حُنُوٍّ. ""تَطَلَّعْتُ إِلَى وَجْهِ وَالِدِي فَإِذَا هُوَ يَطْفَحُ بِالعَطْفِ"". (ع. بنجلون) ""شَعَرَتِ الأُمُّ بِأَنَّ قَلْبَهَا يَذُوبُ رِقَّةً وَعَطْفاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22229, 'تَعْفِيرٌ', 'تعفير', 'مصدر', 'عفر', 'تعفير', 'تعفر', 'مص. عَفَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْفِيرٌ-تَعْفِيرٌ [ع ف ر] (مص. عَفَرَ). 1.""تَعْفِيرُ الثَّدْيِ"" : مَسْحُهُ بِالتُّرَابِ تَنْفِيراً لِلرَّضِيعِ. 2.""تَعْفِيرُ الجَبِينِ"" : تَمْرِيغُهُ فِي التُّرَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22230, 'تَعْظِيلٌ', 'تعظيل', 'مصدر', 'عظل', 'تعظيل', 'تعظل', 'مص. عَظَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْظِيلٌ-تَعْظِيلٌ [ع ظ ل] (مص. عَظَّلَ). ""تَعْظِيلُ الحَيَوَانَاتِ"": رُكُوبُ بَعْضِهَا عَلَى بَعْضٍ لِلسِّفَادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22231, 'تَعْظِيمٌ', 'تعظيم', 'مصدر', 'عظم', 'تعظيم', 'تعظم', 'مص. عَظَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْظِيمٌ-تَعْظِيمٌ [ع ظ م] (مص. عَظَّمَ). ""تَعْظِيمُ الرَّجُلِ"" : تَفْخِيمُهُ، تَكْبِيرُهُ، تَبْجِيلُهُ. ""إِيَّاكَ وَالإِفْرَاطَ فِي التَّعْظِيمِ"" (الجاحظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22232, 'عَظْمَةٌ', 'عظمة', 'مصدر', 'عظم', 'عظمة', 'عظمة', 'مص. عَظَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عَظْمَةٌ-عَظْمَةٌ [ع ظ م] (مص. عَظَمَ). ""يَنْهَشُ العَظْمَةَ"" : القِطْعَة مِنَ العَظْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22233, 'عِظَمٌ', 'عظم', 'مصدر', 'عظم', 'عظم', 'عظم', 'مص. عَظُمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عِظَمٌ-عِظَمٌ [ع ظ م] (مص. عَظُمَ). ""عُرِفَ بِعِظَمِهِ"" : بِكِبَرِهِ، بِضَخَامَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22234, 'عَفَافٌ', 'عفاف', 'مصدر', 'عفف', 'عفاف', 'عفف', 'مص. عَفَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عَفَافٌ-عَفَافٌ [ع ف ف] (مص. عَفَّ). 1.""عُرِفَتْ بِعَفَافِ سُلُوكِهَا"" : الامْتِنَاعُ، الانْكِفَاءُ عَمَّا لاَ يَحِلُّ وَلاَ يَجْمُلُ قَوْلاً أَوْ فِعْلاً. ""فَجَلَسَتْ وَالسَّكِينَةُ حَدِيثُنَا وَالعَفَافُ ثَالِثُنَا"". (جبران خ. جبران) ""لاَ تَنْفَعُ الْمَوَدَّةُ إِلاَّ مَعَ الرَّأْيِ وَالعَفَافِ"". (ابن المقفع). 2.""عَفَافُ"" : اِسْمُ عَلَمٍ لِلإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22235, 'عِفَّةٌ', 'عفة', 'مصدر', 'عفف', 'عفة', 'عفة', 'مص. عَفَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عِفَّةٌ-عِفَّةٌ [ع ف ف] (مص. عَفَّ). ""عِفَّةٌ فِي القَوْلِ وَالفِعْلِ"" : الامْتِنَاعُ وَالكَفُّ عَمَّا لاَ يَحِلُّ قَوْلاً أَوْ فِعْلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22236, 'عَفٌّ', 'عف', 'مصدر', 'عفف', 'عف', 'عف', 'مص. عَفَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَفٌّ-عَفٌّ [ع ف ف] (مص. عَفَّ). ""رَجُلٌ عَفٌّ"" : ذُو عِفَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22237, 'عَفَاءٌ', 'عفاء', 'مصدر', 'عفو', 'عفاء', 'عف', 'مص. عَفَا', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"عِفَاءٌ-عِفَاءٌ [ع ف و] (مص. عَافَى). : مَا كَثُرَ وَطَالَ مِنَ الوَبَرِ وَالشَّعْرِ وَالرِّيشِ. 1.""عِفَاءُ الشَّعْرِ"" : كَثِيرُهُ وَطَوِيلُهُ. 2.""عِفَاءُ الْجَمَلِ"" : وَبَرُهُ الكَثِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22238, 'عَفْوٌ', 'عفو', 'مصدر', 'عفو', 'عفو', 'عف', 'مص. عَفَا', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"عَفْوٌ-عَفْوٌ [ع ف و] (مص. عَفَا). 1.""عَفْوُهُ كَبِيرٌ"" : مَعْرُوفٌ، فَضْلٌ. 2.""عَفْوُ الْمَالِ"" : مَا يَفْضُلُ عَنِ النَّفَقَةِ وَلاَ عُسْرَ عَلَى صَاحِبِهِ فِي إِعْطَائِهِ.البقرة آية 219 وَيَسْأَلُونَكَ مَاذَا يُنْفِقُونَ قُلِ العَفْوَ (قرآن). 3.""عَفْوُ الْمَاءِ"" : مَا زَادَ عَلَى الشَّارِبَةِ وَأُخِذَ بِلاَ كُلْفَةٍ، وَلاَ مُزَاحَمَةٍ. 4.""أَصْدَرَ رَئِيسُ الدَّوْلَةِ عَفْواً عَلَى جَمِيعِ الْمُعْتَقَلِينَ"" : إِطْلاَقُ سَرَاحِهِمْ بِإِيقَافِ عُقُوبَةِ الْحُكْمِ الصَّادِرَةِ فِي حَقِّهِمْ، التَّسَامُحُ، التَّسَاهُلُ. ‎ ""أَلَيْسَ العَفْوُ مِنْ شِيَمِ الكِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22239, 'عَقْبٌ', 'عقب', 'مصدر', 'عقب', 'عقب', 'عقب', 'مص. عَقَبَ', '', '', 'مفرد', 'DnN', '', '', '"أَعْقَابٌ:عِقَابٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَقَبَ). ""هُوَ عَقْبُهُ"" : وَلَدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22240, 'عَفْرٌ', 'عفر', 'مصدر', 'عفر', 'عفر', 'عفر', 'مص. عَفَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَفْرٌ-عَفْرٌ [ع ف ر] (مص. عَفَرَ). 1.""عَفْرُ الأَرْضِ"" : وَجْهُهَا. 2.""مَرَّغَهُ فِي العَفْرِ"" : فِي التُّرَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22241, 'عَفَرٌ', 'عفر', 'مصدر', 'عفر', 'عفر', 'عفر', 'مص. عَفِرَ', '', '', 'مفرد', 'DnN', '', '', '"أَعْفَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَفِرَ). 1.""عَفَرُ الأَرْضِ"" : وَجْهُهَا. ""مَا عَلَى عَفَرِ الأَرْضِ مِثْلُهُ"". 2.""مَرَّغَهُ فِي العَفَرِ"" : فِي التُّرَابِ. 3.""بَادَرَ الفَلاَّحُ إِلَى العَفَرِ"" : أَيِ القِيَامِ بِأَوَّلِ سَقْيَةٍ لِلزَّرْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22242, 'أَعْفَارٌ', 'أعفار', 'مصدر', '', 'ءعفار', 'عفر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22243, 'عَفَنٌ', 'عفن', 'مصدر', 'عفن', 'عفن', 'عفن', 'مص. عَفِنَ', '', '', 'مفرد', 'DnN', '', '', '"أَعْفَانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَفِنَ). 1. : نَبَاتَاتٌ فِطْرِيَّةٌ تَنْمُو عَلَى الْمَوَادِّ الفَاسِدَةِ مِنَ الرّطُوبَةِ وَتُسَبِّبُ التَّعَفُّنَ. 2.""خَمِيرَةُ العَفَنِ"" (فِي الكِيمِيَاءِ وَالصَّيْدَلَة) : البِنِسِلِين."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22244, 'أَعْفَانٌ', 'أعفان', 'مصدر', '', 'ءعفان', 'عفن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22245, 'عُفُونَةٌ', 'عفونة', 'مصدر', 'عفن', 'عفونة', 'عفنة', 'مص. عَفِنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عُفُونَةٌ-عُفُونَةٌ [ع ف ن] (مص. عَفِنَ). ""فِي الْمَاءِ عُفُونَةٌ"" : فَسَادُ رَائِحَتِهِ وَتَغَيُّرُهَا، النُّتُونَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22246, 'عَقٌّ', 'عق', 'مصدر', 'عقق', 'عق', 'عق', 'مص. عَقَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَقٌّ-عَقٌّ [ع ق ق] (مص. عَقَّ). 1.""وَلَدٌ عَقٌّ"" : عَاقٌّ، عَاصٍ. 2.""مَاءٌ عَقٌّ"" : مُرٌّ. 3. : حَفْرٌ مُسْتَطِيلٌ فِي الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22247, 'عُقُوقٌ', 'عقوق', 'مصدر', 'عقق', 'عقوق', 'عقق', 'مص. عَقَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عُقُوقٌ-عُقُوقٌ [ع ق ق] (مص. عَقَّ). ""عُقُوقُ الاِبْنِ"" : عِصْيَانُهُ، جُحُودُهُ. ""هَلْ بَلَغَ بِي العُقُوقُ إِلَى أَنْ أَنْسَى فَضْلَهُ وَكَرَمَهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22248, 'تَعْقِيبٌ', 'تعقيب', 'مصدر', 'عقب', 'تعقيب', 'تعقب', 'مص. عَقَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْقِيبٌ-تَعْقِيبٌ [ع ق ب] (مص. عَقَّبَ). 1.""التَّعْقِيبُ فِي الصَّلاَةِ"" : الدُّعَاءُ لِشَيْءٍ مَّا بَعْدَ أَدَاءِ الصَّلاَةِ. 2.""التَّعْقِيبُ فِي الأَمْرِ"" : الجِدُّ فِي طَلَبِهِ بِإِلْحَاحٍ. 3.""التَّعْقِيبُ عَلَى الكَلاَمِ"" : التَّعْلِيقُ عَلَيْهِ وَتَفْسِيرُهُ تَأْيِيداً أَوْ مُعَارَضَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22249, 'عُقُولٌ', 'عقول', 'مصدر', '', 'عقول', 'عقل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22250, 'أَعْقَابٌ', 'أعقاب', 'مصدر', '', 'ءعقاب', 'عقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22251, 'عِقَابٌ', 'عقاب', 'مصدر', '', 'عقاب', 'عقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22252, 'عَقْدٌ', 'عقد', 'مصدر', 'عقد', 'عقد', 'عقد', 'مص. عَقَدَ', '', '', 'مفرد', 'DnN', '', '', '"عُقُودٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَقَدَ). 1.""أَبْرَمَ عَقْداً تِجَارِيّاً مَعَ شَرِيكِهِ"" : اِتِّفَاقاً، عَهْداً، أَيْ مَا يَتِمُّ بَيْنَ طَرَفَيْن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22253, 'عُقُودٌ', 'عقود', 'مصدر', '', 'عقود', 'عقد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22254, 'عُقْرٌ', 'عقر', 'مصدر', 'عقر', 'عقر', 'عقر', 'مص. عَقَرَ', '', '', 'مفرد', 'DnN', '', '', '"أَعْقَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَقَرَ). 1.""بِهَا عُقْرٌ"": عُقْمٌ وَعَدَمُ حَمْلٍ. 2.""فِي عُقْرِ دَارِهِ"" : في وَسَطِها. 3.""عُقْرُ القَصِيدَةِ"" : أَحْسَنُ أَبْيَاتِهَا. 4.""بَيْضَةُ العُقْرِ"" : أَوَّلُ بَيْضَةٍ تَبِيضُهَا الدَّجَاجَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22255, 'أَعْقَارٌ', 'أعقار', 'مصدر', '', 'ءعقار', 'عقر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22256, 'عَقَارٌ', 'عقار', 'مصدر', 'عقر', 'عقار', 'عقر', 'مص. عَقِرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. عَقِرَ). 1.""يَمْلِكُ عَقَارَاتٍ"" : كُلُّ مِلْكٍ ثَابِتٍ كَالأَرْضِ وَالعِمَارَاتِ. 2.""عَقَارُ البَيْتِ"" : مَتَاعُهُ. 3.""عَقَارُ الشَّيْءِ"" : أَجْوَدُهُ، خِيَارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22257, 'تَعْقِيلٌ', 'تعقيل', 'مصدر', 'عقل', 'تعقيل', 'تعقل', 'مص. عَقَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْقِيلٌ-تَعْقِيلٌ [ع ق ل] (مص. عَقَّلَ). ""تَعْقِيلُ الشَّخْصِ"" : جَعْلُهُ عَاقِلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22258, 'عَقْلٌ', 'عقل', 'مصدر', 'عقل', 'عقل', 'عقل', 'مص. عَقَلَ', '', '', 'مفرد', 'DnN', '', '', '"عُقُولٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَقَلَ). ""عَقْلُ الإِنْسَانِ"" : قُوَّةُ الإِدْرَاكِ وَالتَّمْيِيزِ وَالتَّفْكِيرِ عِنْدَهُ. ""اِخْتَلَّ عَقْلُهُ"" ""العَقْلُ السَّلِيمُ فِي الْجِسْمِ السَّلِيمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22259, 'تَعْلِيفٌ', 'تعليف', 'مصدر', 'علف', 'تعليف', 'تعلف', 'مص. عَلَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْلِيفٌ-تَعْلِيفٌ [ع ل ف] (مص. عَلَّفَ). ""تَعْلِيفُ الْمَاشِيَةِ"" : إِطْعَامُهَا بِاسْتِمْرَارٍ لِتَقْوِيَةِ لَحْمِهَا وَشَحْمِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22260, 'تَعْقِيمٌ', 'تعقيم', 'مصدر', 'عقم', 'تعقيم', 'تعقم', 'مص. عَقَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَعْقِيمٌ-تَعْقِيمٌ [ع ق م] (مص. عَقَّمَ). 1.""تَعْقِيمُ الْمَرْأَةِ"" : تَصْيِيُرهَا عَقِيماً. 2.""تَعْقِيمُ الوَسَائِلِ"" : قَتْلُ مَا فِيهَا مِنْ جَرَاثِيمَ بِوَاسِطَةِ مَوَادَّ كِيمِيَائِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22261, 'عُقْمٌ', 'عقم', 'مصدر', 'عقم', 'عقم', 'عقم', 'مص. عَقَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُقْمٌ-عُقْمٌ [ع ق م] (مص. عَقَمَ). ""بِهَا أَوْ بِهِ عُقْمٌ"" : وَضْعٌ فِي تَرْكِيبِ الْجِهَازِ التَّنَاسُلِيِّ يَفْتَقِرُ إِلَى القُوَّةِ الْحَيَوِيَّةِ فِي الْمَنَوِيَّاتِ يَحُولُ دُونَ التَّنَاسُلِ فِي الذَّكَرِ وَالأُنْثَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22262, 'عَكْسٌ', 'عكس', 'مصدر', 'عكس', 'عكس', 'عكس', 'مص. عَكَسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَكْسٌ-عَكْسٌ [ع ك س] (مص. عَكَسَ). 1.""مَا حَدَثَ كَانَ عَكْسَ مَا يَتَصَوَّرُ"" : نَقِيضٌ، خِلاَفٌ. يُقَالُ: ""عَكْسُ ذَلِكَ"" ""عَلَى العَكْسِ"" ""بِالعَكْسِ"" ""العَكْسُ بِالعَكْسِ"". 2.""العَكْسُ فِي البَدِيعِ"": تَقْدِيمُ جُزْءٍ مِنَ الكَلاَمِ عَلَى جُزْءٍ آخَرَ مُنَاقِضٍ لَهُ: ""قُشُورُ الكَلاَمِ"" ""كَلاَمُ القُشُورِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22263, 'عَلٌّ', 'عل', 'مصدر', 'علل', 'عل', 'عل', 'مص. عَلَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَلٌّ-عَلٌّ [ع ل ل] (مص. عَلَّ). 1.""وَلَدٌ عَلٌّ"" : مُتَقَبِّضُ الْجِلْدِ مِنْ مَرَضٍ، أَوْ نَحِيفُ الْجِسْمِ. 2.""رَجُلٌ عَلٌّ"" : لاَ خَيْرَ عِنْدَهُ. 3.""هُوَ عَلٌّ"" : يَزُورُ النِّسَاءَ كَثِيراً. 4. : تَيْسٌ عَظِيمٌ ضَخْمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22264, 'عَلَلٌ', 'علل', 'مصدر', 'علل', 'علل', 'عل', 'مص. عَلَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَلَلٌ-عَلَلٌ [ع ل ل] (مص. عَلَّ). ""شَرِبَ عَلَلاً"" : شَرِبَ ثَانِيَةً أ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22265, 'عُلُوٌّ', 'علو', 'مصدر', 'علو', 'علو', 'عل', 'مص. عَلاَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عُلْوٌ-عُلْوٌ [ع ل و]. ""عُلْوُ الشَّيْءِ"" : أَرْفَعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22266, 'تَعْلِيبٌ', 'تعليب', 'مصدر', 'علب', 'تعليب', 'تعلب', 'مص. عَلَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْلِيبٌ-تَعْلِيبٌ [ع ل ب] (مص. عَلَّبَ). ""تَعْلِيبُ الْمَوَادِّ الغِذَائِيَّةِ"" : جَعْلُهَا فِي عُلَبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22267, 'عِلاَجٌ', 'علاج', 'مصدر', 'علج', 'علاج', 'علج', 'مص. عَلَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عِلاَجٌ-عِلاَجٌ [ع ل ج] (مص. عَلَجَ). ""لاَ يَزَالُ تَحْتَ العِلاَجِ"": الْمُرَاقَبَة الطِّبِّيَّة، تَنَاوُل الدَّوَاءِ. ""الوِقَايَةُ خَيْرٌ مِنَ العِلاَجِ"" ""وَصَفَ الدَّوَاءَ وَطَرِيقَةَ العِلاَجِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22268, 'عَلْجٌ', 'علج', 'مصدر', 'علج', 'علج', 'علج', 'مص. عَلَجَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَلْجٌ-عَلْجٌ [ع ل ج] (مص. عَلَجَ). ""وَلَدٌ عَلْجٌ"" : شَدِيدٌ، مُعَالِجٌ لِلأُمُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22269, 'تَعْلِيلٌ', 'تعليل', 'مصدر', 'علل', 'تعليل', 'تعلل', 'مص. عَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْلِيلٌ-تَعْلِيلٌ [ع ل ل] (مص. عَلَّلَ). 1.""تَعْلِيلُ النَّفْسِ بِالأَمَلِ"" : إِنْعَاشُهَا بِهِ. 2.""تَعْلِيلُ كَلِمَةٍ"" (نح) : إِدْخَالُ الإِعْلاَلِ عَلَيْهَا. 3.""تَعْلِيلُ خَطَإٍ"" : تَبْرِيرُهُ وَتَبْيَانُ سَبَبِ وُقُوعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22270, 'تَعْلِيقٌ', 'تعليق', 'مصدر', 'علق', 'تعليق', 'تعلق', 'مص. عَلَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَعَالِيقُ"', '', 'R', '', '', '', '', '', '', '"(مص. عَلَّقَ). 1.""تَعْلِيقُ لَوْحَةٍ"" : جَعْلُهَا مُعَلَّقَةً. 2.""تَعْلِيقُ حُكْمٍ"" : وَقْفُ تَنْفِيذِهِ. 3.""تَعْلِيقُ الآمَالِ عَلَى نَجَاحِهِ"" : بِنَاءُ آمَال. 4.""قَدَّمَ تَعْلِيقاً عَلَى"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22271, 'تَعَالِيقُ', 'تعاليق', 'مصدر', '', 'تعاليق', 'تعلق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22272, 'عَلْقٌ', 'علق', 'مصدر', 'علق', 'علق', 'علق', 'مص. عَلَقَ', '', '', 'مفرد', 'DnN', '', '', '"أَعْلاَقٌ:عُلُوقٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَلَقَ). 1.""حَمَلَ الْعَلْقَ"" : العِلْقُ، الجِرَابَ. 2.""شَيْءٌ عَلْقٌ"" : نَفِيسٌ . 3.""ثَوْبٌ بِهِ عَلْقٌ"" : خَرْقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22273, 'أَعْلاَقٌ', 'أعلاق', 'مصدر', '', 'ءعلاق', 'علق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22274, 'عُلُوقٌ', 'علوق', 'مصدر', '', 'علوق', 'علق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22275, 'عَلَقٌ', 'علق', 'مصدر', 'علق', 'علق', 'علق', 'مص. عَلِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَلَقٌ-عَلَقٌ [ع ل ق] (مص. عَلِقَ). 1. : كُلُّ مَا عُلِّقَ. 2.""اِمْتَصَّ الْعَلَقُ دَمَهُ"" : دُوَيْدَةٌ سَوْدَاءُ تَمْتَصُّ الدَّمَ تَعِيشُ فِي الْمَاءِ الآسِنِ. 3.""العَلَقُ"" : سُورَةٌ مِنْ سُوَرِ القُرْآنِ.العلق آية 2 خَلَقَ الإِنْسَانَ مِنْ عَلَقٍ (قرآن) : العَلَقَةُ، طَوْر مِن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22276, 'عِلْقٌ', 'علق', 'مصدر', 'علق', 'علق', 'علق', 'مص. عَلِقَ', '', '', 'مفرد', 'DnN', '', '', '"أَعْلاَقٌ:عُلُوقٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَلِقَ). 1.""وَضَعَ العِلْقَ عَلَى كَتِفِهِ"" : العَلْقُ، الْجِرَابَ. 2.""شَيْءٌ عِلْقٌ"": نَفِيسٌ. 3."" هُوَ عِلْقُ عِلْمٍ"" : يُحِبُّهُ وَيَمِيلُ إِلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22277, 'أَعْلاَقٌ', 'أعلاق', 'مصدر', '', 'ءعلاق', 'علق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22278, 'عُلُوقٌ', 'علوق', 'مصدر', '', 'علوق', 'علق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22279, 'أَعْمَامٌ', 'أعمام', 'مصدر', '', 'ءعمام', 'عمم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22280, 'تعاليل', 'تعاليل', 'مصدر', '', 'تعاليل', 'تعلل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22281, 'تَعْلِيمٌ', 'تعليم', 'مصدر', 'علم', 'تعليم', 'تعلم', 'مص. عَلَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْلِيمٌ-تَعْلِيمٌ [ع ل م] (مص. عَلَّمَ). 1.""وِزَارَةُ التَّعْلِيمِ وَالتَّرْبِيَةِ"" : الوِزَارَةُ الْمَسْؤُولَةُ عَنْ تَلْقِينِ أَبْنَاءِ الشَّعْبِ الْمَعَارِفَ وَمَبَادِئَ العُلُومِ فِي الْمَدَارِسِ الابْتِدَائِيَّةِ وَالثَّانَوِيَّةِ وَالجَامِعِيَّةِ. 2.""التَّعْلِيمُ الابْتِدَائِيُّ وَالثَّانَوِيُّ وَالجَامِعِيُّ"" : مَرَاحِلُ تَلْقِينِ، وَتَدْرِيسِ الْمَعَارِفِ وَالْمَهَارَاتِ. ""التَّعْلِيمُ التِّقْنِيُّ وَالفَنِّيُّ"" ""لِكُلِّ شَخْصٍ الحَقُّ فِي التَّعْلِيمِ"". 3.""يُمَارِسُ التَّعْلِيمَ مُنْذُ سَنَوَاتٍ"" : مِهْنَةَ الْمُعَلِّمِ وَالأُسْتَاذِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22282, 'تعاليم', 'تعاليم', 'مصدر', '', 'تعاليم', 'تعلم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22283, 'عَلَمٌ', 'علم', 'مصدر', 'علم', 'علم', 'علم', 'مص. عَلِمَ', '', '', 'مفرد', 'DnN', '', '', '"أَعْلاَمٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. عَلِمَ). 1. ""وَضَعَ عَلَماً عَلَى التَّلِّ"" : عَلاَمَةً. 2. ""وَضَعَ أَعْلاَماً لِلْفَصْلِ بَيْنَ حُدُودِ الْبُقَعِ الأَرْضِيَّةِ"" : عَلاَمَات. 3. ""عَلَمُ الطَّرِيقِ"" : مَا يُنْصَبُ لِيُهْتَدَى بِهِ. 4. ""أَشْهَرُ مِنْ نَارٍ عَلَى عَلَمٍ"" : عَلَى جَبَلٍ، كِنَايَةً عَنْ أَنَّهُ مَعْرُوفٌ وَمَشْهُورٌ. ""هُوَ عَلَمٌ مِنْ أَعْلاَمِ الْفِكْرِ"". 5.""وَقَفُوا لِتَحِيَّةِ الْعَلَمِ"" : الرَّايَة. ""اِرْتَفَعَتِ الأَْعلاَمُ فِي كُلِّ مَكَانٍ"". 6. ""رَشِيدٌ اِسْمُ عَلَمٍ لِلْمُذَكَّرِ"" : مِنَ الأَسْمَاءِ الشَّخْصِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22284, 'أَعْلاَمٌ', 'أعلام', 'مصدر', '', 'ءعلام', 'علم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22285, 'عَلاَنِيَةٌ', 'علانية', 'مصدر', 'علن', 'علانية', 'علنة', 'مص. عَلِنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عَلاَنِيَةٌ-عَلاَنِيَةٌ [ع ل ن] (مص. عَلِنَ). 1.""كَشَفَ عَنِ السِّرِّ عَلاَنِيَةً"" : جَهْراً أَمَامَ الْمَلإِ، النَّاسِ.فاطر آية 29 وَأَنْفَقُوا مِمَّا رَزَقْنَاهُمْ سِرّاً وَعَلاَنِيَةً (قرآن). 2.""رَجُلٌ عَلاَنِيَةٌ"" : ظَاهِرٌ أَمْرُهُ. ""الْمُرُوءةُ أَنْ لاَ تَعْمَلَ فِي السِّرِّ مَا تَسْتَحِي مِنْهُ فِي العَلاَنِيَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22286, 'عَلاءٌ', 'علاء', 'مصدر', 'علو', 'علاء', 'عل', 'مص. عَلِيَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"عَلاءٌ-عَلاءٌ [ع ل و]. (مص. عَلِيَ). 1.""يَعْلُو نَحْوَ العَلاَءِ"" : الرِّفْعَة، الشَّرَف. 2.""عَلاَءُ الدِّينِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22287, 'عَمٌّ', 'عم', 'مصدر', 'عمم', 'عم', 'عم', 'مص. عَمَّ', '', '', 'مفرد', 'DnN', '', '', '"أَعْمَامٌ:عَمَّاتٌ"', '', '', '', '', '', '', '', '', '"(مص. عَمَّ). ""زَارَ عَمَّهُ فِي يَوْمِ الْعِيدِ"" : أَخُ الأَبِ. ""هَذَا ابْنُ عَمِّي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22288, 'عَمَّةٌ', 'عمة', 'مصدر', 'عمم', 'عمة', 'عمة', 'مص. عَمَّ', '', '', 'مفرد', 'DnN', '', '', '"أَعْمَامٌ:عَمَّاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَمَّ). ""زَارَ عَمَّهُ فِي يَوْمِ الْعِيدِ"" : أَخُ الأَبِ. ""هَذَا ابْنُ عَمِّي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22289, 'عَمْشٌ', 'عمش', 'مصدر', 'عمش', 'عمش', 'عمش', 'مص. عَمَشَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَمْشٌ-عَمْشٌ [ع م ش] (مص. عَمَشَ). 1. : مَا يَكُونُ فِيهِ صَلاَحُ الْبَدَنِ وَزِيَادَتُهُ. 2.""هَذَا الطَّعَامُ عَمْشٌ لَكَ"" : أَيْ مُوَافِقٌ وَمُلاَئِمٌ لَكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22290, 'عَمَّاتٌ', 'عمات', 'مصدر', '', 'عمات', 'عمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22291, 'عُمُومٌ', 'عموم', 'مصدر', 'عمم', 'عموم', 'عمم', 'مص. عَمَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عُمُومٌ-عُمُومٌ [ع م م] (مص. عَمَّ). ""أَدَّى وَاجِبَهُ عَلَى الْعُمُومِ"" : بِشَكْلٍ عَامٍّ. ""عُمُوماً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22292, 'تَعْمِيدٌ', 'تعميد', 'مصدر', 'عمد', 'تعميد', 'تعمد', 'مص. عَمَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْمِيدٌ-تَعْمِيدٌ [ع م د] (مص. عَمَّدَ). ""تَعْمِيدُ الوَلَدِ"" : غَسْلُهُ بِمَاءِ الْمَعْمُودِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22293, 'عَمْدٌ', 'عمد', 'مصدر', 'عمد', 'عمد', 'عمد', 'مص. عَمَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَمْدٌ-عَمْدٌ [ع م د] (مص. عَمَدَ). 1.""ضَرَبَهُ عَمْداً"" : قَصْداً. 2.""قَامَ بِذَلِكَ عَنْ عَمْدٍ"" : عَنْ تَصْمِيمٍ وَقَصْدٍ، مُتَعَمِّداً. ""عَمْداً"". 3.""الْقَتْلُ الْعَمْدُ"" : أَي الْقَتْلُ الَّذِي يَتِمُّ عَنْ سَبْقِ إِصْرَارٍ، أَيْ مَا يَتَعَمَّدُهُ الْقَاتِلُ قَصْداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22294, 'تَعْمِيرٌ', 'تعمير', 'مصدر', 'عمر', 'تعمير', 'تعمر', 'مص. عَمَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْمِيرٌ-تَعْمِيرٌ [ع م ر] (مص. عَمَّرَ). ""تَعْمِيرُ الْمَدِينَةِ"" : إِقَامَةُ مَشَارِيعَ عُمْرَانِيَّةٍ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22295, 'عِمَارَةٌ', 'عمارة', 'مصدر', 'عمر', 'عمارة', 'عمرة', 'مص. عَمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. عَمَرَ). 1.""يَسْكُنُ فِي عِمَارَةٍ"" : بِنَايَةٌ كَبِيرَةٌ بِهَا مَسَاكِنُ فِي طَوَابِقَ مُتَعَدِّدَةٍ. ""تَحَوَّلَتِ الضَّاحِيَةُ إِلَى مَجْمُوعَةٍ مِنَ الْعِمَارَاتِ"". 2.""فَنُّ الْعِمَارَةِ"" : فَنُّ تَشْيِيدِ الْمَنَازِلِ وَالْبِنَايَاتِ وَإِقَامَتِهَا وَفْقَ الْقَوَاعِدِ الْهَنْدَسِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22296, 'عُمْرَانٌ', 'عمران', 'مصدر', 'عمر', 'عمران', 'عمرن', 'مص. عَمَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عُمْرَانٌ-عُمْرَانٌ [ع م ر] (مص. عَمَرَ). 1.""عُمْرَانُ الْبِلاَدِ"" : بُنْيَانُهَا. ""مَرَرْنَا فِي الطَّرِيقِ عَلَى قَنَوَاتٍ... وَآثَارٍ وَعُمْرَانٍ عَظِيمَةٍ مُهَدَّمَةٍ"". (أ. أمين). 2.""حَضَارَةٌ وَعُمْرَانٌ"" : حَرَكَةٌ وَأَعْمَالٌ وَتَشْيِيدٌ وَتَمَدُّنٌ. ""الْعَدْلُ أَسَاسُ الْعُمْرَانِ"". 3. ""عِلْمُ العُمْرانِ"" : عِلْمُ الاجْتِماعِ. ""أَوَّلُ مَنْ وَضَعَ أُسُسَ عِلْمِ الْعُمْرَانِ هُوَ ابْنُ خَلْدُون""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22297, 'عَمْرٌ', 'عمر', 'مصدر', 'عمر', 'عمر', 'عمر', 'مص. عَمَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَمَرٌ-عَمَرٌ [ع م ر] (مص. عَمِرَ). ""وَضَعَتِ السَّيِّدَةُ الْعَمَرَ عَلَى رَأْسِهَا"" : الْمِنْدِيل الَّذِي تُغَطِّي بِهِ كُلُّ امْرَأَةٍ حُرَّةٍ رَأْسَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22298, 'عَمَرٌ', 'عمر', 'مصدر', 'عمر', 'عمر', 'عمر', 'مص. عَمِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَمْرٌ-عَمْرٌ [ع م ر] (مص. عَمَرَ). ""عَمْرُ الإِنْسَانِ"" : حَيَاتُهُ، دِينُهُ. وَمِنْهُ: ""لَعَمْرِي"" : أَيْ أُقْسِمُ بِحَيَاتِي، بِدِينِي. ""لَعَمْرُكَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22299, 'تَعْمِيقٌ', 'تعميق', 'مصدر', 'عمق', 'تعميق', 'تعمق', 'مص. عَمَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْمِيقٌ-تَعْمِيقٌ [ع م ق] (مص. عَمَّقَ). 1.""تَعْمِيقُ البِئْرِ"" : جَعْلُهُ عَمِيقاً. 2.""تَعْمِيقُ فِكْرَةٍ"" : إِطَالَةُ النَّظَرِ فِيهَا بِرَوِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22300, 'عُمْقٌ', 'عمق', 'مصدر', 'عمق', 'عمق', 'عمق', 'مص. عَمُقَ', '', '', 'مفرد', 'DnN', '', '', '"أَعْمَاقٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَمُقَ). 1.""عُمْقُ الْبِئْرِ"" : قَعْرُهُ. "" فِي عُمْقِ الْبَحْرِ"". 2.""تَحَدَّثَ بِعُمْقٍ فِي الْمَوْضُوعِ"" : بِتَفْكِيرٍ وَرَوِيَّةٍ. 3.""أُحَيِّيكَ مِنْ أَعْمَاقِ الْقَلْبِ"" : مِنْ دَوَاخِلِهِ. 4.""عُمْقُ الْجُبِّ"" : غَوْرُهُ، كَثَافَتُهُ. ""كَأَنَّهُ آتٍ مِنْ عُمْقٍ سَحِيقٍ"". 5.""فِي عُمْقِ اللَّيْلِ"" : فِي وَسَطِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22301, 'أَعْمَاقٌ', 'أعماق', 'مصدر', '', 'ءعماق', 'عمق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22302, 'عَمَلٌ', 'عمل', 'مصدر', 'عمل', 'عمل', 'عمل', 'مص. عَمِلَ', '', '', 'مفرد', 'DnN', '', '', '"أَعْمَالٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. عَمِلَ). 1.""يَبْحَثُ عَنْ عَمَلٍ"" : عَنْ شُغْلٍ، عَنْ مِهْنَةٍ. ""يَتَفَانَى فِي عَمَلِهِ"" ""عَمَلٌ مُثْمِرٌ"" ""يَجْرِي الْعَمَلُ عَلَى قَدَمٍ وَسَاقٍ"". 2.""أَعْمَالٌ يَدَوِيَّةٌ"" : مُا يُنْجَزُ بِاليَدِ. 3.""أَعْمَالٌ مَنْزِلِيَّةٌ"" : مَا يَقُومُ بِهِ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22303, 'أَعْمَالٌ', 'أعمال', 'مصدر', '', 'ءعمال', 'عمل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22304, 'تَعْمِيمٌ', 'تعميم', 'مصدر', 'عمم', 'تعميم', 'تعمم', 'مص. عَمَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. عَمَّمَ). 1.""وَصَلَ تَعْمِيمٌ إِدَارِيٌّ إِلَى الإِدَارَةِ"" : مَنْشُوٌر يَتَضَمَّنُ تَعْلِيمَاتٍ أَوْ إِرْشَادَاتٍ أَوْ أَخْبَاراً تُوَجِّهُهُ سُلْطَةٌ عُلْيا لِمَنْ يَهُمُّهُمُ الأَمْرُ لِلأَخْذِ وَالعَمَلِ بِهَا. 2. ""تَعْمِيمُ التَّعْلِيمِ"" : جَعْلُهُ عَامّاً بَيْنَ النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22305, 'عَمَهٌ', 'عمه', 'مصدر', 'عمه', 'عمه', 'عمه', 'مص. عَمَهَ، عَمِهَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَمَهٌ-عَمَهٌ [ع م هـ] (مص. عَمَهَ، عَمِهَ). 1.""وَجَدَ نَفْسَهُ فِي عَمَهٍ"" : فِي تَرَدُّدٍ وَحَيْرَةٍ، لَمْ يَعُدْ يَدْرِي أَيْنَ وِجْهَتُهُ. 2.""عَمَهُ الْبَصِيرَةِ"" : أَيْ عَمَى الْعَقْلِ وَالْفِطْنَةِ 3.""أَصَابهُ الْعَمَهُ"" : أَيْ فُقْدَانُ مَلَكَةِ الإِدْرَاكِ بِالحِسِّ، وَعَدَمُ الْقُدْرَةِ عَلَى التَّمْيِيزِ بَيْنَ أَشْكَالِ الأَشْيَاءِ وَالأَشْخَاصِ وَطَبِيعَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22306, 'عَمَايَةٌ', 'عماية', 'مصدر', 'عمي', 'عماية', 'عمة', 'مص. عَمِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عَمَايَةٌ-عَمَايَةٌ [ع م ي] (مص. عَمِيَ). ""نَهَى النَّاسَ عَنِ الْعَمَايَةِ"" : عَنِ الْغِوَايَةِ وَالضَّلاَلِ وَالْبَاطِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22307, 'عَمىً', 'عمى', 'مصدر', 'عمي', 'عمى', 'عم', 'مص. عَمِيَ', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"عَمىً-عَمىً [ع م ي] (مص. عَمِيَ). 1.""أَلَمَّ بِهِ الْعَمَى مُنْذُ صِغَرِهِ"" : ذَهَابُ البَصَرِ. 2.فصلت آية 17 وَأَمَّا ثَمُودُ فَهَدَيْنَاهُمْ فَاسْتَحَبُّوا الْعَمَى عَلَى الْهُدَى (قرآن) : الضَّلاَلَة. ""لاَ عَمىً كَعَمَى الْقَلْبِ وَالْبَصِيرَةِ"". 3.""عَمَى الأَلْوَانِ"" : عَدَمُ الْقُدْرَةِ عَلَى التَّمْيِيزِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22308, 'تَعْنِيبٌ', 'تعنيب', 'مصدر', 'عنب', 'تعنيب', 'تعنب', 'مص. عَنَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْنِيبٌ-تَعْنِيبٌ [ع ن ب] (مص. عَنَّبَ). ""تَعْنِيبُ الكَرْمِ"" : صَيْرُهُ ذَا عِنَبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22309, 'تَعْنِيتٌ', 'تعنيت', 'مصدر', 'عنت', 'تعنيت', 'تعنت', 'مص. عَنَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْنِيتٌ-تَعْنِيتٌ [ع ن ت] (مص. عَنَّتَ). ""تَعْنِيتُ الرَّجُلِ"" : إِجْبَارُهُ عَلَى تَحَمُّلِ الْمَشَاقِّ وَإِلْزَامُهُ مَا يَصْعُبُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22310, 'عَنْتَرَةٌ', 'عنترة', 'مصدر', 'عنتر', 'عنترة', 'عنترة', 'مص. عَنْتَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"عَنْتَرَةٌ-عَنْتَرَةٌ [ع ن ت ر] (مص. عَنْتَرَ). 1.""أَظْهَرَ البَطَلُ عَنْتَرَةً"": شَجاعَةً، بُطولَةً. 2."" عَنْتَرَةُ"" : اِسْمُ عَلَمٍ لِلْمُذَكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22311, 'عَنْزٌ', 'عنز', 'مصدر', 'عنز', 'عنز', 'عنز', 'مص. عَنَزَ.', '', '', 'مفرد', 'DnN', '', '', '"أعَنُزٌ:عُنُوزٌ"', '', 'R', '', '', '', '', '', '', '"ج: أعَنُزٌ، عُنُوزٌ. (مص. عَنَزَ). : الأُنْثَى مِنَ الْمَاعِزِ وَالظِّبَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22312, 'أعَنُزٌ', 'أعنز', 'مصدر', '', 'ءعنز', 'عنز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22313, 'عُنُوزٌ', 'عنوز', 'مصدر', '', 'عنوز', 'عنز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22314, 'تَعْنِيسٌ', 'تعنيس', 'مصدر', 'عنس', 'تعنيس', 'تعنس', 'مص. عَنَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْنِيسٌ-تَعْنِيسٌ [ع ن س] (مص. عَنَّسَ). ""عَنَّسَتِ الفَتَاةُ تَعْنِيساً"" : طَالَتْ عُزُوبَتُهَا إِطَالَةً، عَنَسَتْ عُنُوساً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22315, 'عَنْعَنَةٌ', 'عنعنة', 'مصدر', 'عنعن', 'عنعنة', 'عنعنة', 'مص. عَنْعَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عَنْعَنَةٌ-عَنْعَنَةٌ [ع ن ع ن] (مص. عَنْعَنَ). ""فِي كَلاَمِهِ عَنْعَنَةٌ"": أَيْ يَنْطِقُ الْهَمْزَةَ عَيْناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22316, 'عُنْفٌ', 'عنف', 'مصدر', 'عنف', 'عنف', 'عنف', 'مص. عَنُفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عُنْفٌ-عُنْفٌ [ع ن ف] (مص. عَنُفَ). ""عَامَلَهُ بِعُنْفٍ"" : بِشِدَّةٍ وَقَسَاوَةٍ. ‎ ""يُدْرَكُ بِالرِّفْقِ مَا لاَ يُدْرَكُ بِالعُنْفِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22317, 'عَنَاءٌ', 'عناء', 'مصدر', 'عني', 'عناء', 'عن', 'مص. عَنِيَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"عَنَاءٌ-عَنَاءٌ [ع ن ي] (مص. عَنِيَ). ""وَجَدَ كَثِيراً مِنَ الْعَنَاءِ"": مِنَ التَّعَبِ، مِنَ المَشَقَّةِ. ""مَا الْعَنَاءُ إِلاَّ فِي الاِبْتِدَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22318, 'عِنَايَةٌ', 'عناية', 'مصدر', 'عني', 'عناية', 'عنة', 'مص. عُنِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عِنَايَةٌ-عِنَايَةٌ [ع ن ي] (مص. عُنِيَ). 1.""أَوْلىَ عِنَايَةً خَاصَّةً بِالْمَوْضُوعِ"" : اِهْتِمَاماً. ""هُوَ أَهْلٌ لِكُلِّ عِنَايَةٍ"" ""أَصْبَحْتُ مَعْنِيّاً بِأَمْرِهِ عِنَايَتَهُ بِنَفْسِهِ"". 2.""رَافَق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22319, 'عَوَزٌ', 'عوز', 'مصدر', 'عوز', 'عوز', 'عز', 'مص. عَوِزَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَوِزٌ-عَوِزٌ [ع و ز] (صِيغَةُ فَعِل). ""رَجُلٌ عَوِزٌ"" : مُفْتَقِرٌ، مُحْتَاجٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22320, 'عَهْدٌ', 'عهد', 'مصدر', 'عهد', 'عهد', 'عهد', 'مص. عَهِدَ', '', '', 'مفرد', 'DnN', '', '', '"عُهُودٌ"', '', 'R', '', '', '', '', '', '', '"(مص. عَهِدَ). 1.""حَافَظَ عَلَى الْعَهْدِ"" : عَلَى الْوَفَاءِ، عَلَى المِيثَاقِ. ""مَازَالَ عَلَى الْعَهْدِ"". 2.""هُوَ قَرِيبُ الْعَهْدِ"" : قَرِيبُ الْعِلْمِ بِهِ. 3.""عَهْدِي بِكَ أَمِيناً"" : مَعْرِفَتِي بِكَ. 4.""مِنْ عَهْدٍ بَعِيدٍ"" : مِنْ زَمَانٍ بَعِيدٍ. ""مِنْ عَهْدٍ قَرِيبٍ"". 5.""حَصَلَ ذَلِكَ فِي عَهْدِهِ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22321, 'عُهُودٌ', 'عهود', 'مصدر', '', 'عهود', 'عهد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22322, 'تَعْوِيجٌ', 'تعويج', 'مصدر', 'عوج', 'تعويج', 'تعج', 'مص. عَوَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْوِيجٌ-تَعْوِيجٌ [ع و ج] (مص. عَوَّجَ). ""تَعْوِيجُ قَضِيبٍ"" : ثَنْيُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22323, 'عِوَجٌ', 'عوج', 'مصدر', 'عوج', 'عوج', 'عج', 'مص. عَوِجَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عِوَجٌ-عِوَجٌ [ع و ج] (مص. عَوِجَ). ""قَوْلٌ غَيْرُ ذِي عِوَجٍ"": غَيْرُ مُلْتَوٍ.الزمر آية 28 قُرْآناً عَرَبِيّاً غَيْرَ ذِي عِوَجٍ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22324, 'تَعْوِيدٌ', 'تعويد', 'مصدر', 'عود', 'تعويد', 'تعد', 'مص. عَوَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْوِيدٌ-تَعْوِيدٌ [ع و د] (مص. عَوَّدَ). ""أَرَادَ تَعْوِيدَهُ الْمَشْيَ"" : تَدْرِيبَهُ على الْمَشْيِ جَعْلُهُ يَعْتَادُهُ. ""تَعْوِيدُ النَّفْسِ تَحَمُّلَ الْمَشَاقِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22325, 'تَعْوِيذٌ', 'تعويذ', 'مصدر', 'عوذ', 'تعويذ', 'تعذ', 'مص. عَوَّذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَعَاوِيذُ"', '', 'R', '', '', '', '', '', '', '"(مص. عَوَّذَ). ""لاَ يُؤْمِنُ بِالتَّعَاوِيذِ"" : بِالتَّمَائِمِ وَالرُّقَى، أَيْ مَا يُعْتَقَدُ أَنَّهُ يَحْمِي الإِنْسَانَ مِنَ الأَشْرَارِ وَالسِّحْرِ. ""حَرَّمَ العِرَافَةَ وَالسِّحْرَ وَالتَّنْجِيمَ وَكِتَابَةَ التَّعَاوِيذِ وَالأَحْجِبةِ"" (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22326, 'تَعَاوِيذُ', 'تعاويذ', 'مصدر', '', 'تعاويذ', 'تعذ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22327, 'تَعْوِيرٌ', 'تعوير', 'مصدر', 'عور', 'تعوير', 'تعر', 'مص. عَوَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْوِيرٌ-تَعْوِيرٌ [ع و ر] (مص. عَوَّرَ). 1.""لَمْ يَكُنْ يَقْصِدُ تَعْوِيرَهُ"" : تَصْيِيرُهُ أَعْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22328, 'عَوَرٌ', 'عور', 'مصدر', 'عور', 'عور', 'عر', 'مص. عَوِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَوِرٌ-عَوِرٌ [ع و ر] (صِيغَةُ فَعِل). 1. ""وَلَدٌ عَوِرٌ"" : سَيِّئُ الْخُلُقِ. 2. ""شَيْءٌ عَوِرٌ"" : لاَ حَافِظَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22329, 'عَيَاءٌ', 'عياء', 'مصدر', 'عيي', 'عياء', 'ع', 'مص. عَيَّ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"عَيَاءٌ-عَيَاءٌ [ع ي ي] (مص. عَيَّ). 1.""أُصِيبَ بِعَيَاءٍ"" : بِتَعَبٍ شَدِيدٍ، بِعَجْزٍ. 2. ""الدَّاءُ الْعَيَاءُ"" : الدَّاءُ الَّذِي لاَ طِبَّ لَهُ وَلاَ بُرْءَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22330, 'تَعْوِيصٌ', 'تعويص', 'مصدر', 'عوص', 'تعويص', 'تعص', 'مص. عَوَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْوِيصٌ-تَعْوِيصٌ [ع و ص] (مص. عَوَّصَ). 1.""تَعْوِيصُ الرَّجُلِ"" : عَدَمُ اسْتِقَامَتِهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22331, 'عَوَصٌ', 'عوص', 'مصدر', 'عوص', 'عوص', 'عص', 'مص. عَوِصَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"عَوَصٌ-عَوَصٌ [ع و ص] (مص. عَوِصَ). 1.""أَمْرٌ عَوَصٌ"" : فِيهِ شِدَّةٌ وَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22332, 'تَعْوِيضٌ', 'تعويض', 'مصدر', 'عوض', 'تعويض', 'تعض', 'مص. عَوَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. عَوَّضَ). ""تَسَلَّمَ تَعْوِيضاً عَنْ خَدَمَاتِهِ السَّابِقَةِ"" : مَا يَأْخُذُهُ العَامِلُ أَوِ الْمُوَظَّفُ جَزَاءً عَلَى عَمَلٍ إِض"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22333, 'تَعْوِيلٌ', 'تعويل', 'مصدر', 'عول', 'تعويل', 'تعل', 'مص. عَوَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْوِيلٌ-تَعْوِيلٌ [ع و ل] (مص. عَوَّلَ). 1.""هَزَّهُ تَعْوِيلُ الْمَرِيضِ"": رَفْعُ صَوْتِهِ بِالبُكَاءِ وَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22334, 'عَوْلَمَةٌ', 'عولمة', 'مصدر', 'عولم', 'عولمة', 'علمة', 'مص. عَوْلَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"عَوْلَمَةٌ-عَوْلَمَةٌ [ع و ل م] (مص. عَوْلَمَ). ""عَوْلَمَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22335, 'تَعْوِيمٌ', 'تعويم', 'مصدر', 'عوم', 'تعويم', 'تعم', 'مص. عَوَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْوِيمٌ-تَعْوِيمٌ [ع و م] (مص. عَوَّمَ). 1.""تَعْوِيمُ السَّفِينَةِ"" : إِسْبَاحُهَا ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22336, 'عُوَاءٌ', 'عواء', 'مصدر', 'عوي', 'عواء', 'ع', 'مص. عَوَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"عَوَّاءٌ-عَوَّاءٌ [ع و ي] (صِيغَةُ فَعَّال لِلْم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22337, 'عَيٌّ', 'عي', 'مصدر', 'عيي', 'عي', 'ع', 'مص. عَوَى، عَيَّ، عَيِيَ', '', '', 'مفرد', 'DnN', '', '', '"أَعْيَاءٌ"', '', '', '', '', '', '', '', '', '"(مص. عَوَى، عَيَّ، عَيِيَ). ""رَجُلٌ عَيٌّ"" : عَاجِزٌ فِي نُطْقِهِ، غَيْرُ مُتَمَكِّنٍ مِنْ إِظْهَارِ قَصْدِهِ مِنْ كَلاَمِهِ."', '');
