INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22344, 'عِيٌّ', 'عي', 'مصدر', 'عيي', 'عي', 'ع', 'مص. عَيَّ، عَيِيَ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عِيٌّ-عِيٌّ [ع ي ي] (مص. عَيَّ، عَيِيَ). 1.""وَلَدٌ بِهِ عِيٌّ"" : عَجْزٌ فِي النُّطْقِ، وَعَدَمُ التَّمَكُّنِ مِنْ إِظْهَارِ قَصْدِهِ وَمُرَادِهِ مِنْ كَلاَمِهِ. 2.""وَجَدَ نَفْسَهُ فِي عِيٍّ"" : عَدَمُ الاهْتِدَاءِ لِوَجْهِ الْمُرَادِ فِي أَمْرٍ أَوْ حَاجَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22345, 'تَعْيِيلٌ', 'تعييل', 'مصدر', 'عيل', 'تعييل', 'تعل', 'مص. عَيَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَعْيِيلٌ-تَعْيِيلٌ [ع ي ل] (مص. عَيَّلَ). ""تَعْيِيلُ أُسْرَةٍ"" : التَّكَفُّلُ بِمَعِيشَتِهَا، إِعَالَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22346, 'تَعْيِينٌ', 'تعيين', 'مصدر', 'عين', 'تعيين', 'تعن', 'مص. عَيَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. عَيَّنَ). 1.""تَمَّ تَعْيِينُهُ فِي وَظِيفَةٍ جَدِيدَةٍ"" : تَنْصِيبُهُ، تَسْمِيَتُهُ. 2.""تَعْيِينُ الأَهْدَافِ"" : تَحْدِيدُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22347, 'غَيَابٌ', 'غياب', 'مصدر', 'غيب', 'غياب', 'غب', 'مص. غَابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غَيَّابٌ-غَيَّابٌ [غ ي ب] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""تِلْمِ"', '');
