INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22349, 'غَوْرٌ', 'غور', 'مصدر', 'غور', 'غور', 'غر', 'مص. غَارَ', '', '', 'مفرد', 'DnN', '', '', '"أَغْوَارٌ:غِيرَانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. غَارَ). 1.""يُحِبُّ حَيَاةَ الْجَبَلِ بَدَلَ الْغَوْرِ"" : مَا انْحَدَرَ مِنَ الأَرْضِ وَانْخَفَضَ. 2.""اِخْتَفَى فِي الْغَوْرِ"" : فِي الْكَهْفِ. 3.""رَمَاهُ فِي غَوْرِ البِئْرِ"" : فِي قَعْرِ البِئْرِ. 4.""مَاءٌ غَوْرٌ"" : مَاءٌ عَمِيقٌ، غَائِرٌ.الملك "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22350, 'غِيبَةٌ', 'غيبة', 'مصدر', 'غيب', 'غيبة', 'غبة', 'مص. غَابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"غِيبَةٌ-غِيبَةٌ [غ ي ب] (مص. غَابَ). ""تَجَنَّبِ الْغِيبَةَ"" : الاِغْتِيَابَ، أَي الْحديثُ عَنْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22351, 'غَيْبٌ', 'غيب', 'مصدر', 'غيب', 'غيب', 'غب', 'مص. غَابَ', '', '', 'مفرد', 'DnN', '', '', '"غُيُوبٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. غَابَ). 1.""هُوَ اللَّهُ عَالِمُ الْغَيْبِ"" : عَالِمٌ بِمَا خَفِيَ وَبِكُلِّ الأَسْرَارِ وَبِمَا سَيَحْدُثُ.الأنعام آية 73 عالِمُ الغَيْبِ والشَّهادَة (قرآن) l ""عَلاَّمُ الْغُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22352, 'غُيُوبٌ', 'غيوب', 'مصدر', '', 'غيوب', 'غب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
