INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22356, 'غِيَاثٌ', 'غياث', 'مصدر', 'غيث', 'غياث', 'غث', 'مص. غَاثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غِيَاثٌ-غِيَاثٌ [غ ي ث] (مص. غَاثَ). ""يَنْتَظِرُ غِيَاثاً"" : إِعَانَةً وَنُصْرَةً، أَيْ مَا يُغَاثُ بِهِ الْمُضْطَرُّ مِنْ طَعَامٍ أَوْ نَجْدَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22357, 'غَيْثٌ', 'غيث', 'مصدر', 'غيث', 'غيث', 'غث', 'مص. غَاثَ', '', '', 'مفرد', 'DnN', '', '', '"غُيُوثٌ"', '', 'R', '', '', '', '', '', '', '"(مص. غَاثَ). 1.""رُوِيَتِ الأَرْضُ بِالغَيْثِ الْغَزِيرِ"" : بِالْمَطَرِ. 2.""أَوَّلُ الْغَيْثِ قَطْرٌ"" : تَكْفِي البِدَايَةُ لِيَكْثُرَ الخَيْرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22358, 'غُيُوثٌ', 'غيوث', 'مصدر', '', 'غيوث', 'غث', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22359, 'مَغَاصٌ', 'مغاص', 'مصدر', 'غوص', 'مغاص', 'مغص', 'مص. غَاصَ', '', '', 'مفرد', 'DnN', '', '', '"مَغَاوِصُ"', '', 'R', '', '', '', '', '', '', '"(مص. غَاصَ). ""مَغَاصُ اللُّؤْلُؤِ"" : مَوْضِعُ الغَوْصِ عَنِ اللُّؤْلُؤِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22360, 'أَغْوَارٌ', 'أغوار', 'مصدر', '', 'ءغوار', 'غر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
