INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22362, 'غَيْرَةٌ', 'غيرة', 'مصدر', 'غير', 'غيرة', 'غرة', 'مص. غَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"غَيْرَةٌ-غَيْرَةٌ [غ ي ر] (مص. غَارَ). 1.""يَشْعُرُ بِالغَيْرَةِ عَلَى أَهْلِهِ"" : بِالْحَمِيَّةِ. 2.""تَلْتَهِبُ نِيرَانُ الغَيْرَةِ فِي نَفْسِهِ"" : ما يَحُزُّ في نَفْسِ الْمُحِبِّ عِنْدَما يَلْمَسُ اِنْصِرافَ مَحْبوبِهِ عَنْهُ وَإعْجابَ الأَغْيارِ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22363, 'غِرَارٌ', 'غرار', 'مصدر', 'غرر', 'غرار', 'غرر', 'مص. غارَّ، غَرَّ، يَغُرُّ', '', '', 'مفرد', 'DnN', '', '', '"أَغِرَّةٌ"', '', 'R', '', '', '', '', '', '', '"(مص. غارَّ، غَرَّ، يَغُرُّ). 1.""غِرَارُ السَّيْفِ"" : حَدُّهُ. 2.""كُلُّهُمْ عَلَى غِرَارٍ وَاحِدٍ"" : مُتَشَابِهُونَ، مُتَمَاثِلُونَ، عَلَى نَمَطٍ وَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22364, 'أَغِرَّةٌ', 'أغرة', 'مصدر', '', 'ءغرة', 'غرة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22365, 'غِرَاءٌ', 'غراء', 'مصدر', 'غرو', 'غراء', 'غر', 'مص. غَارَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"غِرَاءٌ-غِرَاءٌ [غ ر و] (مص. غَارَى). ""غِراءُ الصَّانِع"" : مَادَّةٌ لَزِجَةٌ يُلْصَقُ بِهَا الوَرَقُ أَوِ الْجِلْدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22366, 'غَيْرٌ', 'غير', 'مصدر', 'غير', 'غير', 'غر', 'مص. غَارَ يَغِيرُ', '', '', 'مفرد', 'DnN', '', '', '"أَغْيارٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. غَارَ يَغِيرُ). 1. : التَّغْيِيرُ. 2.""الْغَيْرُ فِي القَانُونِ"" : الطَّرَفُ الثَّالِثُ فِي الْخُصُومَةِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22367, 'أَغْيارٌ', 'أغيار', 'مصدر', '', 'ءغيار', 'غر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22368, 'مُغَازَلَةٌ', 'مغازلة', 'مصدر', 'غزل', 'مغازلة', 'مغزلة', 'مص. غَازَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُغَازَلَةٌ-مُغَازَلَةٌ [غ ز ل] (مص. غَازَلَ). ""اِسْتَمَرَّ فِي مُغَازَلَتِه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22369, 'غُيُومٌ', 'غيوم', 'مصدر', '', 'غيوم', 'غم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22370, 'مَغَاوِصُ', 'مغاوص', 'مصدر', '', 'مغاوص', 'مغص', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22371, 'غَيْضٌ', 'غيض', 'مصدر', 'غيض', 'غيض', 'غض', 'مص. غَاضَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَيْضٌ-غَيْضٌ [غ ي ض] (مص. غَاضَ). 1.""مَاءٌ غَيْضٌ"" : قَلِيلٌ. 2.""هَذَا غَيْضٌ مِنْ فَيْضٍ"" : أَيْ قَلِيلٌ مِنْ كَثِيرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22372, 'غَيْظٌ', 'غيظ', 'مصدر', 'غيظ', 'غيظ', 'غظ', 'مص. غَاظَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَيْظٌ-غَيْظٌ [غ ي ظ] (مص. غَاظَ). ""شَعَرَ بِالغَيْظِ"" : بِشِدَّةِ الْغَضَبِ. ""كَظَمَ غَيْظَهُ"" ""لاَ يَعْرِفُ الْغَضَبَ وَلاَ الْغَيْظَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22373, 'غَوْلٌ', 'غول', 'مصدر', 'غول', 'غول', 'غل', 'مص. غَالَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَوْلٌ-غَوْلٌ [غ و ل] (مص. غَالَ). 1.""أَصَابَهُ مِنْ سُكْرِهِ غَوْلٌ"" : صُدَاعٌ فِي الرَّأْسِ نَاشِىءٌ عَنِ السُّكْرِ.الصافات آية 47 لاَ فِيهَا غَوْلٌ وَلاَ هُمْ عَنْهَا يُنْزَفُونَ (قرآن)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22374, 'مُغَالَبَهٌ', 'مغالبه', 'مصدر', 'غلب', 'مغالبه', 'مغلبه', 'مص. غَالَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُغَالَبَهٌ-مُغَالَبَهٌ [غ ل ب] (مص. غَالَبَ). ""مُغَالَبَةُ النَّفْسِ"" : مُحَاوَلَةُ قَهْرِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22375, 'مُغَالَطَةٌ', 'مغالطة', 'مصدر', 'غلط', 'مغالطة', 'مغلطة', 'مص. غَالَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. غَالَطَ). ""فِي كَلاَمِهِ مُغَالَطَةٌ"" : فِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22376, 'غَيْمٌ', 'غيم', 'مصدر', 'غيم', 'غيم', 'غم', 'مص. غَامَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"(مص. غَامَ). ""اِنْقَشَعَ الغَيْمُ"": السَّحَابُ. ""اِنْتَشَرَتِ الْغُيُومُ فَجْأَةً فِي السَّمَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22377, 'غُيُومٌ', 'غيوم', 'مصدر', '', 'غيوم', 'غم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22378, 'غَيْمَةٌ', 'غيمة', 'مصدر', 'غيم', 'غيمة', 'غمة', 'مص. غَامَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":غُيُومٌ"', '', 'R', '', '', '', '', '', '', '"(مص. غَامَ). ""اِنْقَشَعَ الغَيْمُ"": السَّحَابُ. ""اِنْتَشَرَتِ الْغُيُومُ فَجْأَةً فِي السَّمَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22379, 'غِبْطَةٌ', 'غبطة', 'مصدر', 'غبط', 'غبطة', 'غبطة', 'مص. غَبَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غِبْطَةٌ-غِبْطَةٌ [غ ب ط] (مص. غَبَطَ). 1.""أَشْعُرُ بِالغِبْطَةِ وَالفَرَحِ"" : بِالسُّرُورِ، بِالْمَسَرَّةِ وَحُسْنِ الْحَالِ. 2.""أَحَسَّ بِالغِبْطَةِ نَحْوَهُ"" : أَيْ يَتَمَنَّى مِثْلَ مَا لَهُ مِنْ نِعْمَةٍ وَنَجَاحٍ مِنْ غَيْرِ زَوَالِهَا عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22380, 'مُغَامَرَةٌ', 'مغامرة', 'مصدر', 'غمر', 'مغامرة', 'مغمرة', 'مص. غَامَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. غَامَرَ). ""مُغَامَرَةٌ خَطِيرَةٌ"" : رَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22381, 'غِيَارٌ', 'غيار', 'مصدر', 'غير', 'غيار', 'غر', 'مص. غَايَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. غَايَرَ). 1.""طَعَامٌ غِيَارٌ"" : مَجْلُوبٌ. 2.""يَبْحَثُ عَنْ قِطَعِ الْغِيَارِ لِسَيَّارَتِهِ"" : قِطَعٌ مُجَزَّأَةٌ تُتَّخَذُ بَدِيلاً لِلْقِطَعِ الْقَدِيمَةِ الْفَاسِدَةِ لِتَعْوِيضِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22382, 'مُغَايَرَةٌ', 'مغايرة', 'مصدر', 'غير', 'مغايرة', 'مغرة', 'مص. غَايَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُغَايَرَةٌ-مُغَايَرَةٌ [غ ي ر] (مص. غَايَرَ). ""مُغَايَرَةٌ فِي السُّلُوكِ ومُغَايَرَةٌ فِي الرَّأْيِ"" : الْمُخَالَفَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22383, 'غِبٌّ', 'غب', 'مصدر', 'غبب', 'غب', 'غب', 'مص. غَبَّ', '', '', 'مفرد', 'DnN', '', '', '"أَغْبَابٌ"', '', 'R', '', '', '', '', '', '', '"(مص. غَبَّ). 1.""غِبُّ الشَّيْءِ"" : عَاقِبَتُهُ، آخِرُهُ. 2.""حُمَّى الغِبِّ"" : تَنُوبُ يَوْماً بَعْدَ يَوْمٍ. ""زُرْ غِبّاً تَزْدَدْ حُبّاً"". 3.""مَاءٌ غِبٌّ"" : بَعِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22384, 'أَغْبَابٌ', 'أغباب', 'مصدر', '', 'ءغباب', 'غبب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22385, 'غَبَرٌ', 'غبر', 'مصدر', 'غبر', 'غبر', 'غبر', 'مص. غَبِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَبِرٌ-غَبِرٌ [غ ب ر] (صِيغَةُ فَعِل). ""جُرْحٌ غَبِرٌ"" : ما يَزَالُ يَنْتَكِسُ وَيَنْتَقِضُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22386, 'غُبْرَةٌ', 'غبرة', 'مصدر', 'غبر', 'غبرة', 'غبرة', 'مص. غَبر', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غَبَرَةٌ-غَبَرَةٌ [غ ب ر]. ""اِنْتَشَرَتِ الغَبَرَةُ فِي البَيْتِ"" : الغُبَارُ.عبس آية 40وَوُجُوهٌ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22387, 'غَبَشٌ', 'غبش', 'مصدر', 'غبش', 'غبش', 'غبش', 'مص. غَبِشَ', '', '', 'مفرد', 'DnN', '', '', '"أَغْبَاشٌ"', '', 'R', '', '', '', '', '', '', '"(مص. غَبِشَ). 1.""هَبَطَ اللَّيْلُ وَتَكَثَّفَ الغَبَشُ"" : شِدَّةُ الظُّلْمَةِ وَسَوَادُهَا. 2.""رَجَعَ إِلَى بَيْتِهِ مَعَ الغَبَشِ"" : في آخِرِ اللَّيْلِ. 3.""غَبَشُ اللَّيْلِ"" : بَقِيَّتُهُ. ‏ ""نَحْنُ فِي أَغْبَاشِ اللَّيْلِ"" : أَيْ فِي بَقَايَاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22388, 'أَغْبَاشٌ', 'أغباش', 'مصدر', '', 'ءغباش', 'غبش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22389, 'غَدَرٌ', 'غدر', 'مصدر', 'غدر', 'غدر', 'غدر', 'مص. غَدِرَ', '', '', 'مفرد', 'DnN', '', '', '"أَغْدَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. غَدِرَ). 1.""مَوْضِعٌ غَدَرٌ"" : صَعْبٌ، كَثِيرٌ الْحِجَارَةِ. 2.""غَدَرُ النَّهْرِ"" : الوَحَلُ الَّذِي يَبْقَى فِيهِ بَعْدَ أَنْ يَنْضُبَ مَاؤُهُ. 3.""رَجُلٌ ثَبْتُ الغَدَرِ"" : ثَبْتٌ فِي القِتَالِ. 4.""مَا أَثْبَتَ غَدَرَهُ"" : إِذَا كَانَ لِسَانُهُ يَثْبُتُ فِي مَوْضِعِ الْخُصُومَةِ وَالزَّلَلِ. 5.""فَرَسٌ ثَبْتُ الغَدَرِ"" : يَثْبُتُ فِي الَمَوْضِعِ الصَّعْبِ كَثِيرِ الحِجارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22390, 'غَبْنٌ', 'غبن', 'مصدر', 'غبن', 'غبن', 'غبن', 'مص. غَبَنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَبْنٌ-غَبْنٌ [غ ب ن] (مص. غَبَنَ). ""غَبْنٌ فَاحِشٌ"" : مَكْرٌ، خَدِيعَةٌ. ""اِنْطَوَى العَقْدُ عَلَى غَبْنٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22391, 'غَبَنٌ', 'غبن', 'مصدر', 'غبن', 'غبن', 'غبن', 'مص. غَبِنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَبَنٌ-غَبَنٌ [غ ب ن] .(مص. غَبِنَ). 1.""الغَبَنُ فِي البَيْعِ أَوِ الشِّرَاءِ"" : الْخَدِيعَةُ. 2.""غَبَنُ الثَّوْبِ"" : مَا قُطِعَ مِنْ أَطْرَافِهِ فَأُسْقِطَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22392, 'غَبَاوَةٌ', 'غباوة', 'مصدر', 'غبو', 'غباوة', 'غبة', 'مص. غَبِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غَبَاوَةٌ-غَبَاوَةٌ [غ ب و] (مص. غَبِيَ). 1.""أَظْهَرَ غَبَاوَةً"" : بَلاَدَةً، جَهْلاً وَقِلَّةَ فِطْنَةٍ. 2.""يَا لَهَا مِنْ غَبَاوَةٍ"" : يَا لَهَا مِنْ غَفْلَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22393, 'غَثَيَانٌ', 'غثيان', 'مصدر', 'غثي', 'غثيان', 'غثن', 'مص. غَثَا، غَثِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غَثَيَانٌ-غَثَيَانٌ [غ ث ي] (مص. غَثَا، غَثِيَ). 1.""أَحَسَّ بِغَثَيَانٍ"" : بِاضْطِرَابٍ وَجَيَشَانِ نَفْسٍ وَقَدْ تَهَيَّأَتْ لِلْقَيْءِ. ‏ ""جَاءتْ إِلَيَّ وَهِيَ تَشْكُو الغَثَيَانَ وَالدَّوَرَانَ"". (أمل دنقل). 2.""يَشْعُرُ بِالغَثَيَانِ أَمَامَ الظُّلْمِ وَالقَهْرِ"" : الاشْمِئْزَازِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22394, 'غُدُوٌّ', 'غدو', 'مصدر', 'غدو', 'غدو', 'غد', 'مص. غَدَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غُدُوٌّ-غُدُوٌّ [غ د و] (مص. غَدَا). ""فِي غُدُوُّهِ وَرَوَاحِهِ"" : فِي ذَهَابِهِ وَمَجِيئِهِ. ""مَن اِشْتَدَّ إِلْحَاحُهُ تَوَالَى غُدُوُّهُ وَرَوَاحُهُ"" (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22395, 'غُدْوَةٌ', 'غدوة', 'مصدر', 'غدو', 'غدوة', 'غدة', 'مص. غَدا', '', '', 'مفرد', 'DnN', '', 'Pf', '":غُدُوٌّ:غُدىً"', '', 'R', '', '', '', '', '', '', '"(مص. غَدا). 1.""فِي أَثْنَاءِ الغُدْوَةِ"" : مَا بَيْنَ الفَجْرِ وَطُلُوعِ الشَّمْسِ، أَوَّلُ النَّهَارِ. 2.""إِلَى اللِّقَاءِ غُدْوَةً"" : صَبَاحاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22396, 'غُدُوٌّ', 'غدو', 'مصدر', '', 'غدو', 'غد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22397, 'غُدىً', 'غدى', 'مصدر', '', 'غدى', 'غد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22398, 'غَدْرٌ', 'غدر', 'مصدر', 'غدر', 'غدر', 'غدر', 'مص. غَدَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَدْرٌ-غَدْرٌ [غ د ر] (مص. غَدَرَ). ""لَمْ يَكُنْ لِيَتَصَوَّرَ غَدْرَ صَدِيقِهِ"" : خِيَانَتَهُ، وَعَدَم الوَفَاءِ بِالعَهْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22399, 'أَغْدَارٌ', 'أغدار', 'مصدر', '', 'ءغدار', 'غدر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22400, 'غَدَقٌ', 'غدق', 'مصدر', 'غدق', 'غدق', 'غدق', 'مص. غَدِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَدِقٌ-غَدِقٌ [غ د ق] (صِيغَةُ فَعِل). 1.""مَاءٌ غَدِقٌ"" : غَزِيرٌ، كَثِيرٌ. ""مَطَرٌ غَدِقٌ"". 2.""عُشْبٌ غَدِقٌ"" : مُبْتَلٌّ، رَيَّانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22401, 'تَغْدِيَةٌ', 'تغدية', 'مصدر', 'غدو', 'تغدية', 'تغدة', 'مص. غَدَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَغْدِيَةٌ-تَغْدِيَةٌ [غ د و] (مص. غَدَّى). ""تَغْدِيَةُ الضَّيْفِ"" : إِطْعَامُهُ الغَدَاءَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22402, 'تَغْذِيَةٌ', 'تغذية', 'مصدر', 'غذو', 'تغذية', 'تغذة', 'مص. غَذَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَغْذِيَةٌ-تَغْذِيَةٌ [غ ذ و] (مص. غَذَّى). ""تَغْذِيَةُ الجِسْمِ"" : تَزْوِيدُهُ بِالغِذَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22403, 'غِرَّةٌ', 'غرة', 'مصدر', 'غرر', 'غرة', 'غرة', 'مص. غَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '":غِرَرٌ"', '', 'R', '', '', '', '', '', '', '"(مص. غَرَّ). 1.""أَخَذَهُ عَلَى حِينِ غِرَّةٍ"" : ع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22404, 'غِرَرٌ', 'غرر', 'مصدر', '', 'غرر', 'غر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22405, 'غَرٌّ', 'غر', 'مصدر', 'غرر', 'غر', 'غر', 'مص. غَرَّ', '', '', 'مفرد', 'DnN', '', '', '"غُرُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. غَرَّ). 1.""غَرُّ السَّيْفِ"": حَدُّهُ. 2.""تَرَكَ السَّيْلُ غَرّاً فِي الأَرْضِ"" : شَقّاً. 3.""طَوَى الثَّوْبَ عَلَى غَرِّهِ"" : عَلَى كَسْرٍ مُتَثَنٍّ فِيه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22406, 'غُرُورٌ', 'غرور', 'مصدر', '', 'غرور', 'غرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22407, 'غُرُورٌ', 'غرور', 'مصدر', 'غرر', 'غرور', 'غرر', 'مص. غَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غُرُورٌ-غُرُورٌ [غ ر ر] (مص. غَرَّ). ""بِهِ غُرُورٌ"" : بِهِ كِبْرِيَاءٌ وَأَنَفَةٌ تَحْتَ ضَغْطِ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22408, 'غَرْوٌ', 'غرو', 'مصدر', 'غرو', 'غرو', 'غر', 'مص. غَرَا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَرْوٌ-غَرْوٌ [غ ر و] (مص. غَرَا). ""لاَ غَرْوَ فِي ذَلِكَ"" : لاَ عَجَبَ ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22409, 'تَغْرِيبٌ', 'تغريب', 'مصدر', 'غرب', 'تغريب', 'تغرب', 'مص. غَرَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغْرِيبٌ-تَغْرِيبٌ [غ ر ب] (مص. غَرَّبَ). 1.""تَغْرِيبُ الْمُسَافِرِ"": اِتِّجَاهُهُ صَوْبَ الغَرْبِ. 2.""لَمْ يَكُنْ تَغْرِيبُهُ اخْتِيَاراً"": بُعْدُهُ وَنُزُوحُهُ عَنْ وَطَنِهِ. 3.""أَرَادُوا تَغْرِيبَهُ لِلتَّخَلُّصِ مِنْهُ"" : حَمْلُهُ عَلَى الغُرْبَةِ، إِبْعَادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22410, 'غَرْبٌ', 'غرب', 'مصدر', 'غرب', 'غرب', 'غرب', 'مص. غَرَبَ', '', '', 'مفرد', 'DnN', '', '', '"غُرُوبٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. غَرَبَ). 1.""يَقْطُنُ فِي غَرْبِ البِلاَدِ"" : إِحْدَى الْجِهَاتِ الأَصْلِيَّةِ وَهُوَ مَا يَكُونُ فِي جِهَةِ غُرُوبِ الشَّمْسِ. 2.""الغَرْبُ الإِسْلاَمِيُّ"" : البُلْدَانُ الوَاقِعَةُ فِي قَرْنِ إِفْرِيقِيَا. 3.""أَفْكَارٌ وَرَدَتْ مِنَ الغَرْبِ"" : أَيْ مِنْ بُلْدَانِ أُورُوبَّا وَأَمْرِيكَا. ""أُتِيحَتْ لِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22411, 'غُرُوبٌ', 'غروب', 'مصدر', '', 'غروب', 'غرب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22412, 'غُرْبٌ', 'غرب', 'مصدر', 'غرب', 'غرب', 'غرب', 'مص. غَرَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَرَبٌ-غَرَبٌ [غ ر ب] (مص. غَرِبَ). 1.""عِقْدٌ مِنْ غَرَبٍ"" : مِنْ ذَهَبٍ أَوْ فِضَّةٍ. 2.""نَاوَلَهُ غَرَباً"" : قَدَحاً. 3.""غَرَبُ الدَّلْوِ"" : الْمَاءُ الَّذِي يَقْطُرُ مِنْهُ بَيْنَ الْحَوْضِ وَالبِئْرِ. 4.: جِنْسُ شَجَرٍ مِنْ فَصِيلَةِ الصَّفْصَافِيَّاتِ، تُسَوَّى مِنْ خَشَبِهِ السِّهَامُ. 5.: دَاءٌ يُصِيبُ الشَّاةَ أَوِ الفَرَسَ فَيَتَسَاقَطُ مِنْهُ شَعْرُ خَطْمِهَا وَعْيَنَيْهَا. 6.""بِعَيْنَيْهِ غَرَبٌ"" : إِذَا كَانَتْ تَدْمَعُ وَلاَ يَنْقَطِعُ دَمْعُهَا. 7.""سَهْمٌ غَرَبٌ"" : لاَ يُعْرَفُ رَامِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22413, 'غُرُوبٌ', 'غروب', 'مصدر', 'غرب', 'غروب', 'غرب', 'مص. غَرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غُرُوبٌ-غُرُوبٌ [غ ر ب] (مص. غَرَبَ). ""يَتَأَمَّلُ غُرُوبَ الشَّمْسِ"" : وَقْتَ مَغِيبِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22414, 'غُرْبَةٌ', 'غربة', 'مصدر', 'غرب', 'غربة', 'غربة', 'مص. غَرُبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غُرْبَةٌ-غُرْبَةٌ [غ ر ب] (مص. غَرُبَ). 1.""عَاشَ زَمَناً طَوِيلاً فِي الغُرْبَةِ"" : فِي بِلاَدِ النُّزُوحِ وَالْهِجْرَةِ. 2.""وَجَدْتُهُ فِي غُرْبَةٍ"" : فِي وَحْشَةٍ. 3.""طَالَتْ غُرْبَتُهُ"" : طَالَ بُعْدُهُ عَنْ وَطَنِهِ وَأَهْلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22415, 'غَرَبٌ', 'غرب', 'مصدر', 'غرب', 'غرب', 'غرب', 'مص. غَرِبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غُرْبٌ-غُرْبٌ [غ ر ب] (مص. غَرَبَ). ""اِخْتَارَ الغُرْبَ عَنْ وَطَنِهِ"" : النُّزُوحَ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22416, 'غَرْبَلَةٌ', 'غربلة', 'مصدر', 'غربل', 'غربلة', 'غربلة', 'مص. غَرْبَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غَرْبَلَةٌ-غَرْبَلَةٌ [غ ر ب ل] (مص. غَرْبَلَ). ""غَرْبَلَةُ الطَّحِينِ"" : تَنْقِيَتُهُ مِمَّا عَلِقَ فِيهِ مِنْ حَصىً وَنَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22417, 'تَغْرِيدٌ', 'تغريد', 'مصدر', 'غرد', 'تغريد', 'تغرد', 'مص. غَرَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. غَرَّدَ). ""تَغْرِيدُ العَصَافِيرِ"" : زَقْزَقَتُهَا، تَرْدِيدُ أَصْوَاتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22418, 'تَغْرِيزٌ', 'تغريز', 'مصدر', 'غرز', 'تغريز', 'تغرز', 'مص. غَرَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغْرِيزٌ-تَغْرِيزٌ [غ ر ز] (مص. غَرَّزَ). 1.""تَغْرِيزُ الإِبْرَةِ فِي الثَّوْبِ"" : غَرْزُها، إِدْخَالُهَا. 2.""تَغْرِيزُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22419, 'تَغْرِيمٌ', 'تغريم', 'مصدر', 'غرم', 'تغريم', 'تغرم', 'مص. غَرَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغْرِيمٌ-تَغْرِيمٌ [غ ر م] (مص. غَرَّمَ). ""لَمْ يَكُنْ بُدٌّ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22420, 'غَرْزٌ', 'غرز', 'مصدر', 'غرز', 'غرز', 'غرز', 'مص. غَرَزَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَرْزٌ-غَرْزٌ [غ ر ز] (مص. غَرَزَ). 1. : رِكَابُ الرَّحْلِ مِنْ جِلْدٍ مَخْرُوزٍ.كَانَ إِذَا وَضَعَ رِجْلَهُ فِي الغَرْزِ يُرِيدُ السَّفَرَ. يَقُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22421, 'غَرْسٌ', 'غرس', 'مصدر', 'غرس', 'غرس', 'غرس', 'مص. غَرَسَ', '', '', 'مفرد', 'DnN', '', '', '"أَغْرَاسٌ:غِرَاسٌ"', '', 'R', '', '', '', '', '', '', '"(مص. غَرَسَ). 1.""حَانَ زَمَنُ الغَرْسِ"" : وَقْتُ الزَّرْعِ وَإِثْبَاتُ جُذُور"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22422, 'أَغْرَاسٌ', 'أغراس', 'مصدر', '', 'ءغراس', 'غرس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22423, 'غِرَاسٌ', 'غراس', 'مصدر', '', 'غراس', 'غرس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22424, 'غَرِيضٌ', 'غريض', 'مصدر', 'غرض', 'غريض', 'غرض', 'مص. غَرَضَ', '', '', 'مفرد', 'DnN', '', '', '"أَغَارِيضُ"', '', 'R', '', '', '', '', '', '', '"(مص. غَرَضَ). 1.""لَحْمٌ غَرِيضٌ"" : طَرِيٌّ. 2.""أُعْجِبَ بِغَرِيضِهِ"" : بِغِنَائِهِ الْمُطْرِبِ. 3.""مُنْشِدٌ غَرِيضٌ"" : مُجِيدٌ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22425, 'أَغَارِيضُ', 'أغاريض', 'مصدر', '', 'ءغاريض', 'غرض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22426, 'غَرْغَرَةٌ', 'غرغرة', 'مصدر', 'غرر', 'غرغرة', 'غرغرة', 'مص. غَرْغَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"غَرْغَرَةٌ-غَرْغَرَةٌ [غ ر ر] (مص. غَرْغَرَ). 1.""غَرْغَرَةُ الْمَاءِ فِي الْحَلْقِ"" : تَرْدِيدُ الْمَاءِ فِي الْحَلْقِ. 2.""غَرْغَرَةُ الدَّوَاءِ"" : غَرورٌ، مَا يُتَغَرْغَرُ بِهِ مِنَ الدَّوَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22427, 'غَرْفٌ', 'غرف', 'مصدر', 'غرف', 'غرف', 'غرف', 'مص. غَرَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَرْفٌ-غَرْفٌ [غ ر ف] (مص. غَرَفَ). 1.: مَا يُدْبَغُ بِهِ مِنْ وَرَقِ الشَّجَرِ. 2. (نب). : جِنْسُ شَجَرٍ صَغِيرٍ، أَوْرَاقُهُ مُس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22428, 'تَغْرِيقٌ', 'تغريق', 'مصدر', 'غرق', 'تغريق', 'تغرق', 'مص. غَرَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغْرِيقٌ-تَغْرِيقٌ [غ ر ق] (مص. غَرَّقَ). 1.""حَاوَلَ تَغْرِيقَهُ"" : إِغْراقُهُ، جَعْلُه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22429, 'غَسْلٌ', 'غسل', 'مصدر', 'غسل', 'غسل', 'غسل', 'مص. غَسَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَسْلٌ-غَسْلٌ [غ س ل] (مص. غَسَلَ). 1.""غَسْلُ اليَدَيْنِ"" : تَنْظِيفُهُمَا، تَطْهِيرُهُمَا. 2.""غَسْلُ الدِّمَاغِ"" : مَا يَتَعَرَّضُ لَهُ الْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22430, 'غَرَامَةٌ', 'غرامة', 'مصدر', 'غرم', 'غرامة', 'غرمة', 'مص. غَرِمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. غَرِمَ). ""فُرِضَتْ عَلَيْهِ غَرَامَةٌ"" : مَا يُلْزَمُ أَدَاؤُهُ تَأْدِيباً وَعُقوبَةً، أَو تَعْويضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22431, 'غُرْمٌ', 'غرم', 'مصدر', 'غرم', 'غرم', 'غرم', 'مص. غَرِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غُرْمٌ-غُرْمٌ [غ ر م] (مص. غَرِمَ). 1.""خَسِرَ غُرْماً لَمْ يَكُنْ بِحُسْبَانِهِ"" : مَا يَخْسِرُهُ الْمَرْءُ وَيَفْقِدُهُ مِنْ مَالِهِ بِغَيْرِ جِنَايَةٍ. الرَّهْنُ لِمَنْ رَهَنَهُ، لَهُ غُنْمُهُ وَعَلَيْه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22432, 'غَرَرٌ', 'غرر', 'مصدر', 'غرر', 'غرر', 'غر', 'مص. غَرَّ، يَغَرُّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَرَرٌ-غَرَرٌ [غ ر ر] (مص. غَرَّ، يَغَرُّ). 1.""أَمْرٌ فِيهِ غَرَرٌ"" : خَطَرٌ. 2.""أَوْقَعَهُ فِي غَرَرٍ"" : فِي هَلاَكٍ. 3.""بَيْعُ الغَرَرِ"" : بَيْعُ مَا يَجْهَلُ"', '');
