INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22522, 'تَغْوِيَةٌ', 'تغوية', 'مصدر', 'غوي', 'تغوية', 'تغة', 'مص. غَوَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَغْوِيَةٌ-تَغْوِيَةٌ [غ و ي] (مص. غَوَّى). 1.""تَغْوِيَةُ الرَّجُلِ"" : إ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22523, 'غَيٌّ', 'غي', 'مصدر', 'غوي', 'غي', 'غ', 'مص. غَوَى', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"غَيٌّ-غَيٌّ [غ و ي] (مص. غَوَى).البقرة آية 256 قَدْ تَبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ . (قرآن)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22524, 'تَغْيِيبٌ', 'تغييب', 'مصدر', 'غيب', 'تغييب', 'تغب', 'مص. غَيَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغْيِيبٌ-تَغْيِيبٌ [غ ي ب] (مص. غَيَّبَ). 1.""تَغْيِيبُ الْمَيِّتِ فِي الق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22525, 'غَيَدٌ', 'غيد', 'مصدر', 'غيد', 'غيد', 'غد', 'مص. غَيِدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"غَيَدٌ-غَيَدٌ [غ ي د] (مص. غَيِدَ). ""غَيَدُ الْغُلاَمِ"" : نُعُومَتُهُ فِي تَمَايُلِهِ وَتَثَنِّيهِ كالغَيْداءِ، أي الْمَرْأَةُ الرَّشيقَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22526, 'تَغْيِيرٌ', 'تغيير', 'مصدر', 'غير', 'تغيير', 'تغر', 'مص. غَيَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغْيِيرٌ-تَغْيِيرٌ [غ ي ر] (مص. غَيَّرَ). 1.""تَغْيِيرُ الأَثَاثِ"" : تَحْوِيلُهُ. 2.""تَغْيِيرُ الْمَوْقِفِ"" : تَبْدِيلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22527, 'تَغْيِيظٌ', 'تغييظ', 'مصدر', 'غيظ', 'تغييظ', 'تغظ', 'مص. غَيَّظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغْيِيظٌ-تَغْيِيظٌ [غ ي ظ] (مص. غَيَّظَ). ""تَغْيِيظُ الرَّجُلِ"" : حَمْلُهُ عَلَى الغَيْظِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22528, 'تَغْيِيمٌ', 'تغييم', 'مصدر', 'غيم', 'تغييم', 'تغم', 'مص. غَيَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَغْيِيمٌ-تَغْيِيمٌ [غ ي م] (مص. غَيَّمَ). ""غَيَّمَتِ السَّمَاءُ تَغْيِيماً"": غَامَتْ غَيْماً، أَيِ انْتِشَارُ الغَمَامِ فِيهَا بِكَثَافَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22529, 'فَوْزٌ', 'فوز', 'مصدر', 'فوز', 'فوز', 'فز', 'مص. فَازَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَوْزٌ-فَوْزٌ [ف و ز] (مص. فَازَ). ""أَحْرَزَ فَوْزاً بَاهِراً"" : نَجَاحاً، ظَف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22530, 'فَوَاتٌ', 'فوات', 'مصدر', 'فوت', 'فوات', 'فت', 'مص. فَاتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فَوَاتٌ-فَوَاتٌ [ف و ت] (مص. فَاتَ). 1.""وَصَلَ بَعْدَ فَوَاتِ الأَوَانِ"" : بَعْدَ مُرُورِ الْوَقْت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22531, 'مُفَاتَحَةٌ', 'مفاتحة', 'مصدر', 'فتح', 'مفاتحة', 'مفتحة', 'مص. فَاتَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُفَاتَحَةٌ-مُفَاتَحَةٌ [ف ت ح] (مص. فَاتَحَ). ""جَاءَ لِمُفَاتَحَتِهِ فِي أَمْرٍ هَامٍّ"" : لِمُحَادَثَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22532, 'مُفَاجَأَةٌ', 'مفاجأة', 'مصدر', 'فجأ', 'مفاجءة', 'مفجة', 'مص. فَاجَأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. فَاجَأَ). 1.""كَانَ حُضُورُهُ مَعَنَا مُفَاجَأَةً سَارَّةً لَنَا"" : مَا يَأْتِي ويَحْصُلُ بَغْتَةً وَيُحْدِثُ السُّرُورَ. 2.""أَعَدَّ لَهُ مُفَاجَأَةً"" : أَمْراً لَمْ يَكُنْ مُتَوَقَّعاً. ""كَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22533, 'فَوْحٌ', 'فوح', 'مصدر', 'فوخ', 'فوح', 'فح', 'مص. فَاحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَوْحٌ-فَوْحٌ [ف و خ] (مص. فَاحَ). 1.""فَوْحُ الرَّائِحَةِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22534, 'فَيْحٌ', 'فيح', 'مصدر', 'فيح', 'فيح', 'فح', 'مص. فَاحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَيْحٌ-فَيْحٌ [ف ي ح] (مص. فَاحَ). ""فَيْحُ الْخَاطِرِ"" : سَعَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22535, 'فَوَرَانٌ', 'فوران', 'مصدر', 'فور', 'فوران', 'فرن', 'مص. فَارَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فَوَرَانٌ-فَوَرَانٌ [ف و ر] (مص. فَارَ). 1.""فَوَرَانُ القِدْرِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22536, 'فَوْرٌ', 'فور', 'مصدر', 'فور', 'فور', 'فر', 'مص. فَارَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَوْرٌ-فَوْرٌ [ف و ر] (مص. فَارَ). 1.""أَجَابَ عَلَى الْفَوْرِ"" : حَالاً، مُبَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22537, 'فِرَاقٌ', 'فراق', 'مصدر', 'فرق', 'فراق', 'فرق', 'مص. فَارَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فِرَاقٌ-فِرَاقٌ [ف ر ق] (مص. فَارَقَ). ""حَانَ مَوْعِدُ الْفِرَاقِ"": مَوْعِدُ الانْفِصَالِ وَالافْتِرَاقِ. ""مَا أَصْعَبَ فِرَاقَ الأَهْلِ وَالأَحِبَّةِ وَالأَقَارِبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22538, 'مُفَارَقَةٌ', 'مفارقة', 'مصدر', 'فرق', 'مفارقة', 'مفرقة', 'مص. فَارَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. فَارَقَ). 1.""لاحَظَ مُفارَقَةً في سُلوكِهِ"" : تَنَاقُضُهُ فِيمَا يَقُولُ ويُمَارِسُ. 2.""مُفَارَقَةٌ وَاضِحَةٌ"" : تَنَاقُضٌ ظَاهِرِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22539, 'فَتٌّ', 'فت', 'مصدر', 'فتت', 'فت', 'فت', 'مص. فَتَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَتٌّ-فَتٌّ [ف ت ت] (مص. فَتَّ). 1.""فَتُّ الصَّخْرَةِ"" : شَقُّهَا. 2.""طَعَامُهُ مِنْ فَتٍّ"" : خُبْزٌ مُشْرَبٌ بِمَاءِ اللَّحْمِ، ثَرِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22540, 'فَيْشٌ', 'فيش', 'مصدر', 'فيش', 'فيش', 'فش', 'مص. فَاشَ', '', '', 'مفرد', 'DnN', '', '', '"أَفْيَاشٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَاشَ). ""رَجُلٌ فَيْشٌ"" : ضَعِيفٌ يَتَبَاهَى بِمَا لَيْسَ عِنْدَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22541, 'أَفْيَاشٌ', 'أفياش', 'مصدر', '', 'ءفياش', 'فش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22542, 'فَيَضَانٌ', 'فيضان', 'مصدر', 'فيض', 'فيضان', 'فضن', 'مص. فَاضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فَيَضَانٌ-فَيَضَانٌ [ف ي ض] (مص. فَاضَ). ""جَرَفَ الْفَيَضَانُ الدُّورَ وَالْمَوَاشِيَ"" : تَدَفُّقُ الْمِيَاهِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22543, 'فَيْضٌ', 'فيض', 'مصدر', 'فيض', 'فيض', 'فض', 'مص. فَاضَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَيْضٌ-فَيْضٌ [ف ي ض] (مص. فَاضَ). 1.""أَمْطَرَتِ السَّمَاءُ فَيْضاً"" : مَطَراً غَزِيراً. 2.""عَرَفْتُهُ دَائِماً رَجُلاً فَيْضاً"" : رَجُلاً كَرِيماً، جَوَاداً. 3. ""أَع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22544, 'مُفَاضَلَةٌ', 'مفاضلة', 'مصدر', 'فضل', 'مفاضلة', 'مفضلة', 'مص. فَاضَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُفَاضَلَةٌ-مُفَاضَلَةٌ [ف ض ل] (مص. فَاضَلَ). ""تَرَكَ لَهُ مَجَالَ الْمُفَاضَلَةِ بَيْنَ العَمَلَيْنِ"" : مَجَالُ الْمُوَازَنَةِ لِلْحُكْمِ بِفَضْلِ أَحَدِهِمَا عَلَى الآخَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22545, 'فَوَاقٌ', 'فواق', 'مصدر', 'فوق', 'فواق', 'فق', 'مص. فَاقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فَوَاقٌ-فَوَاقٌ [ف و ق] (مص. فَاقَ). 1. : الْفَتْرَةُ الزَّمَنِيَّةُ الْفَاصِلةُ مَا بَيْنَ الْحَلْبَةِ الأُولَى وَالثَّانِيَةِ. 2.""لَمْ ت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22546, 'فَوْهٌ', 'فوه', 'مصدر', 'فوه', 'فوه', 'فه', 'مص. فَاهَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَوَهٌ-فَوَهٌ [ف و هـ] (مص. فَوِهَ). ""فَوَهُ الفَمِ"" : سَعَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22547, 'مُفَاوَضَةٌ', 'مفاوضة', 'مصدر', 'فوض', 'مفاوضة', 'مفضة', 'مص. فَاوَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. فَاوَضَ). ""دَخَلَتِ الْمُفَاوَضَاتُ مَرْحَلَةً صَعْبَةً بَيْنَ الوَفْدَيْنِ"" : تَبَادُلُ الرَّأْيِ بَيْنَ وَفْدَيْنِ حَوْلَ قَضِيَّةٍ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22548, 'فَأْوٌ', 'فأو', 'مصدر', 'فأو', 'فءو', 'ف', 'مص. فَأَى', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَأْوٌ-فَأْوٌ [ف أ و] (مص. فَأَى). 1. : صَدْعٌ أَوْ شَقٌّ بَيْنَ جَبَلَيْنِ. 2. : مَضْيَقٌ فِي الوَادِي يَنْتَهِي إِلَى سَعَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22549, 'فُتُوقٌ', 'فتوق', 'مصدر', '', 'فتوق', 'فتق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22550, 'تَفْتِيتٌ', 'تفتيت', 'مصدر', 'فتت', 'تفتيت', 'تفتت', 'مص. فَتَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْتِيتٌ-تَفْتِيتٌ [ف ت ت] (مص. فَتَّتَ). 1.""تَفْتِيتُ الخُبْزِ"" : تَكْسِيرُهُ قِطَعاً صَغِيرَةً. 2.""تَفْتِيتُ الأَكْبَادِ وَالقُلُوبِ"" : كِنَايَة عَنْ تَأَثُّرِهَا بِحُزْنٍ أَوْ أَلَمٍ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22551, 'تَفْتِيحٌ', 'تفتيح', 'مصدر', 'فتح', 'تفتيح', 'تفتح', 'مص. فَتَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْتِيحٌ-تَفْتِيحٌ [ف ت ح] (مص. فَتَّحَ). ""تَفْتِيحُ الأَبْوَابِ"" : فَتْحُهَا عَلَى مِصْرَاعَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22552, 'فَتْحٌ', 'فتح', 'مصدر', 'فتح', 'فتح', 'فتح', 'مص. فَتَحَ', '', '', 'مفرد', 'DnN', '', '', '"فُتُوحٌ:فُتُوحَاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَتَحَ). 1.""حَقَّقَ فَتْحاً كَبِيراً"" : نَصْراً. 2.""الفَتْحُ"" : سُورَةٌ مِنْ سُوَرِ القُرْآنِ.الفتح آية 1إِنَّا فَتَحْنَا لَكَ فَتْحاً مُبِينا (قرآن). 3.""الْفَتْحُ الإِسْلاَمِيُّ"" : دُخُولُ الإِسْلاَمِ إِلَى الْبُلْدَانِ الَّتِي انْتَشَرَ فِيهَا بَعْدَ حُرُوبٍ وَمَعَارِكَ. 4.""يَوْمُ الْفَتْحِ"" : يَوْمُ الْقِيَامَةِ. 5.""الْفَتْحُ فِي اللُّغَةِ الْعَرَبِيَّةِ"" : إِنْهَاءُ الْكَلِمَةِ الْمَبْنِيَّةِ بِفَتْحَةٍ، أَي النُّطْقُ أَوِالتَّحْرِيكُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22553, 'فُتُوحٌ', 'فتوح', 'مصدر', '', 'فتوح', 'فتح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22554, 'فُتُوحَاتٌ', 'فتوحات', 'مصدر', '', 'فتوحات', 'فتحت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22555, 'تَفْتِيرٌ', 'تفتير', 'مصدر', 'فتر', 'تفتير', 'تفتر', 'مص. فَتَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْتِيرٌ-تَفْتِيرٌ [ف ت ر] (مص. فَتَّرَ). 1.""فَتَّرَ الرَّجُلُ فِي نَشَاطِهِ تَفْتِيراً"" : أَيْ سَكَنَ وَلاَنَ بَعْدَ حِدَّةٍ سُكُوناً وَلُيُوناً. 2.""تَفْتِيرُ هِمَّةِ الرَّجُلِ"" : تَخْفِيفُ حِدَّتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22556, 'فُتُورٌ', 'فتور', 'مصدر', 'فتر', 'فتور', 'فتر', 'مص. فَتَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فُتُورٌ-فُتُورٌ [ف ت ر] (مص. فَتَرَ). 1.""فُتُورُ الْحَرَكَةِ"" : سُكُونُهَا بَعْدَ حِدَّةٍ. 2.""فُتُورُ الْمَفَاصِلِ"" : ضُعْفُهَا. 3.""فُتُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22557, 'تَفْتِيشٌ', 'تفتيش', 'مصدر', 'فتش', 'تفتيش', 'تفتش', 'مص. فَتَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْتِيشٌ-تَفْتِيشٌ [ف ت ش] (مص. فَتَّشَ). 1.""قَرَّرَ تَفْتِيشَ جَمِيعِ الحَقَائِبِ"" : مُرَاقَبَتَهَا، مَعْرِفَةَ مَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22558, 'فَتْقٌ', 'فتق', 'مصدر', 'فتق', 'فتق', 'فتق', 'مص. فَتَقَ', '', '', 'مفرد', 'DnN', '', '', '"فُتُوقٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَتَقَ). 1.""لاَحَظَ فَتْقاً فِي قَمِيصِهِ"" : اِنْفِصَالُ خِيَاطَةِ الثَّوْبِ عَنْ بَعْضِهَا. 2.""أُصِيبَ بِالْفَتْقِ""(طب) : عِلَّةٌ تَنْشَأُ مِنْ جَرَّاءِ اتِّسَاعِ الْج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22559, 'فُجُورٌ', 'فجور', 'مصدر', 'فجر', 'فجور', 'فجر', 'مص. فَجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فُجُورٌ-فُجُورٌ [ف ج ر] (مص. فَجَرَ). ""فُجُورُ الرَّجُلِ بِالْمَدِينَةِ"" : اِرْتِكَابُهُ الْمَعَاصِيَ، الْفِسْقُ.الشمس آية"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22560, 'فَتَقٌ', 'فتق', 'مصدر', 'فتق', 'فتق', 'فتق', 'مص. فَتِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَتَقٌ-فَتَقٌ [ف ت ق] (مص. فَتِقَ). ""ظَهَرَ الفَتَقُ"" : الصُّبْحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22561, 'فَتْكٌ', 'فتك', 'مصدر', 'فتك', 'فتك', 'فتك', 'مص. فَتَكَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَتْكٌ-فَتْكٌ [ف ت ك] (مص. فَتَكَ). 1.""حَاوَلَ الْفَتْكَ بِعَدُوِّهِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22562, 'فُتُونٌ', 'فتون', 'مصدر', 'فتن', 'فتون', 'فتن', 'مص. فَتَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فُتُونٌ-فُتُونٌ [ف ت ن] (مص. فَتَنَ). ""تَمْتَازُ فُتُوناً وَإِغْرَاءً"" : أَيْ دَلَهاً. ""إِنَّ التَّسَلُّطَ يَمْلأُ النُّفُوسَ غُرُوراً وَفُتُوناً"". (طه حسين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22563, 'فَجٌّ', 'فج', 'مصدر', 'فجج', 'فج', 'فج', 'مص. فَجَّ', '', '', 'مفرد', 'DnN', '', '', '"فِجَاجٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَجَّ). 1.""فَجُّ الْجَبَلِ"" : الطَّرِيقُ الْوَاسِعُ الْوَاضِحُ بَيْنَ جَبَلَيْنِ، الشِّعْبُ، الطَّرِيقُ بَيْنَ حَائِطَيْنِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22564, 'فِجَاجٌ', 'فجاج', 'مصدر', '', 'فجاج', 'فجج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22565, 'فُجَاءةٌ', 'فجاءة', 'مصدر', 'فجأ', 'فجاءة', 'فجة', 'مص. فَجَأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"فُجَاءةٌ-فُجَاءةٌ [ف ج أ] (مص. فَجَأَ). 1.""كَانَ ذَلِكَ فُجَاءةً لَهُ"" : مَا فَاجَأَهُ، أَي "', '');
