INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22567, 'تَفْجِيرٌ', 'تفجير', 'مصدر', 'فجر', 'تفجير', 'تفجر', 'مص. فَجَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْجِيرٌ-تَفْجِيرٌ [ف ج ر] (مص. فَجَّرَ). 1.""تَفْجِيرُ قُنْبُلَةٍ"" : إِشْعَالُ فَتِيلِهَا لِتَتَفَرْقَعَ. 2.""تَفْجِيرُ الْمَوْقِفِ"" : إِلْهَابُهُ، إِشْعَالُهُ، إِيقَاظُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22568, 'فَجْرٌ', 'فجر', 'مصدر', 'فجر', 'فجر', 'فجر', 'مص. فَجَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَجْرٌ-فَجْرٌ [ف ج ر] (مص. فَجَرَ). ""لاَحَ ضَوْءُ الْفَجْرِ "" : ضَوْءُ الصَّبَاحِ. ""ال"', '');
