INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22570, 'تَفَجُّعٌ', 'تفجع', 'مصدر', 'فجع', 'تفجع', 'تفجع', 'مص. فَجَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفَجُّعٌ-تَفَجُّعٌ [ف ج ع] (مص. فَجَّعَ). ""تَفَجُّعُ الرَّجُلِ"": تَوَجُّعُهُ."', '');
