INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22599, 'تَفْرِيحٌ', 'تفريح', 'مصدر', 'فرح', 'تفريح', 'تفرح', 'مص. فَرَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْرِيحٌ-تَفْرِيحٌ [ف ر ح] (مص. فَرَّحَ). ""يَهُمُّهُ تَفْرِيحُ أَبْنَائِهِ"": جَعْلُهُمْ فَرِحِينَ مَسْرُورِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22600, 'فَرَحٌ', 'فرح', 'مصدر', 'فرح', 'فرح', 'فرح', 'مص. فَرِحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَرَحٌ-فَرَحٌ [ف ر ح] (مص. فَرِحَ). 1.""شَاعَ الْفَرَحُ بَيْنَ الأَهْلِ"" : السُّرُورُ، الْبَهْجَةُ. ""وَكَأَحْلاَمِ النَّائِمِ الَّتِي تُف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22601, 'فَرْزٌ', 'فرز', 'مصدر', 'فرز', 'فرز', 'فرز', 'مص. فَرَزَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَرْزٌ-فَرْزٌ [ف ر ز] (مص. فَرَزَ). 1.""فَرْزُ الأَرَاضِي"" : تَقْسِيمُهَا، تَجْزِئَتُهَا إِلَى قِطَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22602, 'فِرَاسَةٌ', 'فراسة', 'مصدر', 'فرس', 'فراسة', 'فرسة', 'مص. فَرَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"فِرَاسَةٌ-فِرَاسَةٌ [ف ر س] (مص. فَرَسَ). : إِدْرَاكُ الْبَاطِنِ وَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22603, 'فُرُوسِيَّةٌ', 'فروسية', 'مصدر', 'فرس', 'فروسية', 'فرسة', 'مص. فَرُسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"فُرُوسِيَّةٌ-فُرُوسِيَّةٌ [ف ر س] (مص. فَرُسَ). 1. : الشَّجَاعَةُ وَالإِقْدَامُ. 2.""رِيَاضَةُ الْفُرُوسِيَّةِ"" : رِيَاضَةٌ قَائِمَةٌ عَلَى فَنِّ رُكُوبِ الْفَرَسِ وَالتَّمَكُّنِ مِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22604, 'فِرَاشٌ', 'فراش', 'مصدر', 'فرش', 'فراش', 'فرش', 'مص. فَرَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَفْرِشَةٌ:فُرْشٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَرَشَ). 1.""اِسْتَلْقَى عَلَى الْفِرَاشِ"" : مَا يُفَرَّشُ وَيُنَامُ عَلَيْهِ. 2.""فِرَاشُ الطَّائِرِ"" : عُشُّهُ. 3.""فِرَاشُ اللِّسَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22605, 'أَفْرِشَةٌ', 'أفرشة', 'مصدر', '', 'ءفرشة', 'فرشة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22606, 'فُرْشٌ', 'فرش', 'مصدر', '', 'فرش', 'فرش', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22607, 'فَرْشٌ', 'فرش', 'مصدر', 'فرش', 'فرش', 'فرش', 'مص. فَرَشَ', '', '', 'مفرد', 'DnN', '', '', '"فُرُوشٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَرَشَ). 1.""فَرْشُ البَيْتِ"" : فِرَاشُهُ، مَتَاعُهُ. 2.""فَرْشُ الْحِذَاءِ"" : مَا يُوضَعُ دَاخِلَ الْحِذَاءِ مُفَصَّلاً عَلَى قَدِّ الْقَدَمِ. 3.""فَرْشُ الْمَسَائِلِ"" : بَسْطُهَا وَتَفْصِيلُ أَحْكَامِهَا. 4.""اِسْت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22608, 'فُرُوشٌ', 'فروش', 'مصدر', '', 'فروش', 'فرش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22609, 'فَرْضٌ', 'فرض', 'مصدر', 'فرض', 'فرض', 'فرض', 'مص. فَرَضَ.', '', '', 'مفرد', 'DnN', '', '', '"فُرُوضٌ"', '', 'Rp', '', '', '', '', '', '', '"ج: فُرُوضٌ. (مص. فَرَضَ). 1.""الصَّلاَةُ فَرْضٌ عَلَى عِبَادِ اللَّهِ"" : فَرِيضَةٌ أَوْجَبَهَا اللَّهُ عَلَيْهِمْ. 2.""كِتَابُ الْفَرْضِ"" : كِتَابُ الصَّلَوَاتِ فِي الدِّيَانَةِ الْمَسِيحِيَّةِ، الْمَفْرُوضُ إِقَامَتُهَا فِي أَوْقَاتٍ مُعَيَّنَةٍ. 3.""أَنْجَزَ فَرْضاً مَدْرَسِيّاً"" : تَمْرِيناً، وَاجِباً. 4.""خَصَّ الْجُنْدِيَّ بِفَرْضٍ"" : مَا يُعْطَى لِلْجُنْدِيِّ مِنْ مَعَاشٍ. 5.""عَلَى فَرْضٍ أَنَّ مَوْقِفَكَ صَحِيحٌ"" : عَلَى سَبِيلِ الافْتِرَاضِ واَلاحْتِمَالِ، أَيْ مَا يُؤْخَذُ فِكْرَةً للِدَّلاَلَةِ عَلَى قَضِيَّةٍ أَوْ لِحَلِّ مَسْأَلَةٍ. 6."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22610, 'فُرُوضٌ', 'فروض', 'مصدر', '', 'فروض', 'فرض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22611, 'تَفْرِيطٌ', 'تفريط', 'مصدر', 'فرط', 'تفريط', 'تفرط', 'مص. فَرَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْرِيطٌ-تَفْرِيطٌ [ف ر ط] (مص. فَرَّطَ). 1.""طَلَبَ مِنْهُ عَدَمَ التَّفْرِيطِ فِي عَمَلِهِ"" : عَدَمَ تَضْيِيعِهِ. 2.""تَفْرِيطُ الدَّرَاهِمِ"" : تَصْرِيفُهَا، تَبْدِيدُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22612, 'فَرْطٌ', 'فرط', 'مصدر', 'فرط', 'فرط', 'فرط', 'مص. فَرَطَ', '', '', 'مفرد', 'DnN', '', '', '"أَفْرُطٌ:أَفْرَاطٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَرَطَ). 1.""أَمْرٌ فَرْطٌ"" : تَجَاوَزَ الْحَدَّ. ""مِنْ فَرْطِ شَغَفِهِ أَوْ كُرْهِهِ لَهُ"". 2.""أَتَيْتُهُ فَرْطاً"" : أَيْ بَعْدَ أَيَّامٍ. 3.""آتِيهِ فَرْطَ يَوْمٍ"" : أَيْ بَعْدَ يَوْمٍ. 4.""لاَ أَلْقَاهُ إِلاَّ فِي الفَرْطِ"" : أَيْ فِي الأَيَّامِ مَرَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22613, 'أَفْرُطٌ', 'أفرط', 'مصدر', '', 'ءفرط', 'فرط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22614, 'أَفْرَاطٌ', 'أفراط', 'مصدر', '', 'ءفراط', 'فرط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22615, 'فَرْعٌ', 'فرع', 'مصدر', 'فرع', 'فرع', 'فرع', 'مص. فَرَعَ', '', '', 'مفرد', 'DnN', '', '', '"فُرُوعٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَرَعَ). 1.""وَصَلَ إِلَى فَرْعِ الْجَبَلِ"" : أَعْلاَهُ، قِمَّتُهُ. 2.""قَطَعَ فَرْعَ الشَّجَرَةِ"" : غُصْناً مِنْ أَغْصَانِهَا يَتَفَرَّعُ مِنْ أَصْلِهَا. 3.""هُوَ فَرْعُ أَهْلِهِ"" : شَرِيفُهُمْ. 4.""فُرُوعُ الرَّجُلِ"" : أَوْلاَدُهُ. 5.""فُرُوعُ الْمَسْأَلَةِ"" : مَا تَفَرَّعَ مِنْهَا. ""العِلْمُ هُوَ الأَصْلُ وَالأَدَبُ هُوَ الفَرْعُ"". (الجاحظ). 6.""يَدْرُسُ فِي فَرْعِ الأَدَبِ"" : فِي قِسْمِ الأَدَبِ، الشُّعْبَة. 7.""فَرْعُ النَّهْرِ"" : مَجْرَاهُ، شُعْبَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22616, 'فُرُوعٌ', 'فروع', 'مصدر', '', 'فروع', 'فرع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22617, 'تَفْرِيغٌ', 'تفريغ', 'مصدر', 'فرغ', 'تفريغ', 'تفرغ', 'مص. فَرَّغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْرِيغٌ-تَفْرِيغٌ [ف ر غ] (مص. فَرَّغَ). 1.""قَامَ العُمَّالُ بِتَفْرِيغِ السَّفِينَةِ"" : إِخْرَاجُ مَا فِيهَا مِنْ مَوَادَّ وَإِنْزالُها مِنْها. ""تَفْرِيغُ الشَّاحِنَةِ"". 2.""طَلَبَ تَفْرِيغَهُ لِلْبَحْثِ"" : جَعْلُهُ يُخَصِّصُ كُلَّ وَقْتِهِ لِلْبَحْثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22618, 'فَرَاغٌ', 'فراغ', 'مصدر', 'فرغ', 'فراغ', 'فرغ', 'مص. فَرَغَ، فَرِغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. فَرَغَ، فَرِغَ). 1.""يَعِيشُ فِي فَرَاغٍ كَبِيرٍ"" : فِي خَلاَءٍ، فِي عَدَمٍ. 2.""تَرَكَ فَرَاغاً بِغِيَابِهِ"" : تَرَكَ بِخُلُوِّ مَكَانِهِ إِحْسَاساً بِالأَلَمِ. ""يَشْعُرُ بِفَرَاغٍ لِفَقْدِهِ"". 3.""يَمْلأُ وَقْتَ فَرَاغِهِ بِالْقِرَاءةِ"" : الْوَقْتُ الَّذِي لاَ شُغْلَ فِيهِ، مَا يُعْرَفُ الآنَ بِالوَقْتِ الثَّالِثِ. ""يَحْتَاجُ إِلَى مِقْدَارٍ مَعْلُومٍ مِنَ الزَّمَانِ وَفَرَاغٍ مِنَ الشَّوَاغِلِ"". (ابن طفيل). 4.""مَلأَ فَرَاغاً فِي الإِدَارَةِ"" : مَلأَ وَظِيفَةً كَانَتْ شَاغِرَةً، أي وُجُودُهُ سَدَّ النَّقْصَ الْحَاصِلَ فِي الإِدَارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22619, 'تَفْزِيعٌ', 'تفزيع', 'مصدر', 'فزع', 'تفزيع', 'تفزع', 'مص. فَزَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْزِيعٌ-تَفْزِيعٌ [ف ز ع] (مص. فَزَّعَ). ""عَمَدَ إِلَى تَفْزِيعِهِ"": إِفْزَاعِهِ، تَخْوِيفِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22620, 'تَفْرِيقٌ', 'تفريق', 'مصدر', 'فرق', 'تفريق', 'تفرق', 'مص. فَرَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْرِيقٌ-تَفْرِيقٌ [ف ر ق] (مص. فَرَّقَ). 1.""أَعْلَنَ عَنْ تَفْرِيقِ الأَغْذِيَةِ عَلَىالْمُصابِينَ وَالْمُعْوِزِينَ"": تَوْزِيعهَا. 2.""التّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22621, 'فُرْقَانٌ', 'فرقان', 'مصدر', 'فرق', 'فرقان', 'فرقن', 'مص. فَرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فُرْقَانٌ-فُرْقَانٌ [ف ر ق] (مص. فَرَقَ). 1.""إِنَّهُ الْفُرْقَانُ الْبَيِّنُ"": كُلُّ مَا فُرِّقَ بِهِ بَيْنَ الْحَقِّ وَالْبَاطِلِ. 2. : قُرْآنٌ. الفرقان آية 1تَبَارَكَ الَّذِي نَزَّل"', '');
