INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22650, 'تَفْصِيصٌ', 'تفصيص', 'مصدر', 'فصص', 'تفصيص', 'تفصص', 'مص. فَصَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْصِيصٌ-تَفْصِيصٌ [ف ص ص] (مص. فَصَّصَ). 1.""تَفْصِيصُ خَاتَمٍ"" : تَرْك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22651, 'تَذْكيرٌ', 'تذكير', 'مصدر', 'فصل', 'تذكير', 'تذكر', 'مص. فَصَّلَ', '', '', 'مفرد', 'DnN', '', '', '"تَفَاصِيلُ"', '', 'R', '', '', '', '', '', '', '"(مص. فَصَّلَ). 1.""تَفْصِيلُ ثَوْبٍ"" : تَقْطِيعُهُ حَسَبَ نَمُوذَجٍ لِخِيَاطَتِهِ. 2.""تَحَدَّثَ بِتَفْصِيلٍ"" : بِإِسْهَابٍ. 3.""رَوَى كُلَّ تَفَاصِيلِ الحَادِثِ"" : جَمِيعَ أَجْزَائِهِ، وَمَا يُحِيطُ بِهِ. ""أَمَرَ بِأَنْ يَقُصَّ كُلَّ مَا حَدَثَ بِالتَّفْصِيلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22652, 'تَفَاصِيلُ', 'تفاصيل', 'مصدر', '', 'تفاصيل', 'تفصل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22653, 'تَفْصِيلٌ', 'تفصيل', 'مصدر', 'فصل', 'تفصيل', 'تفصل', 'مص. فَصَّلَ', '', '', 'مفرد', 'DnN', '', '', '"تَفَاصِيلُ"', '', 'Rp', '', '', '', '', '', '', '"(مص. فَصَّلَ). 1.""تَفْصِيلُ ثَوْبٍ"" : تَقْطِيعُهُ حَسَبَ نَمُوذَجٍ لِخِيَاطَتِهِ. 2.""تَحَدَّثَ بِتَفْصِيلٍ"" : بِإِسْهَابٍ. 3.""رَوَى كُلَّ تَفَاصِيلِ الحَادِثِ"" : جَمِيعَ أَجْزَائِهِ، وَمَا يُحِيطُ بِهِ. ""أَمَرَ بِأَنْ يَقُصَّ كُلَّ مَا حَدَثَ بِالتَّفْصِيلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22654, 'تَفَاصِيلُ', 'تفاصيل', 'مصدر', '', 'تفاصيل', 'تفصل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22655, 'فَصْلٌ', 'فصل', 'مصدر', 'فصل', 'فصل', 'فصل', 'مص. فَصَلَ', '', '', 'مفرد', 'DnN', '', '', '"فُصُولٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. فَصَلَ). 1.""قَرَأَ فَصْلاً مِنَ الْكِتَابِ"" : قِسْماً مُسْتَقِلاًّ مِنْهُ يَنْدَرِجُ تَحْتَ البَابِ، إِذْ لِكُلِّ بَابٍ فُصُولٌ. 2.""الْفَصْلُ الأَوَّلُ مِنَ التَّمْثِيلِيَّةِ"" : أَحَدُ أَقْسَامِهَا. 3.""فُصُولُ السَّنَةِ"" : مَوَاسِمُهَا، كُلُّ مَرْحَلَةٍ مِنْ مَرَاحِلِ السَّنَةِ الأَرْبَعِ، فَصْلُ الصَّيْفِ وَ الْخَرِيفِ وَ الشِّتَاءِ وَ الرَّبِيعِ. 4.""دَخَلَ إِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22656, 'فُصُولٌ', 'فصول', 'مصدر', '', 'فصول', 'فصل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22657, 'فَضٌّ', 'فض', 'مصدر', 'فضض', 'فض', 'فض', 'مص. فَضَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَضٌّ-فَضٌّ [ف ض ض] (مص. فَضَّ). 1.""فَضُّ خَتْمِ الرِّسَالَةِ"" : فَتْحُهُ، فَكُّهُ. 2.""فَضُّ قُفْلِ الْبَابِ"" : تَكْسِيرُهُ. 3.""فَضُّ الْجَمْعِ"" : تَشْتِيتُهُ، تَفْرِيقُهُ. 4.""فَضُّ مُشْكِلَةٍ"" : حَلُّهَا وَحَسْمُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22658, 'فَضَاءٌ', 'فضاء', 'مصدر', 'فضو', 'فضاء', 'فض', 'مص. فَضَا', '', '', 'مفرد', 'Dz', '', '', '"أَفْضِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '"(مص. فَضَا). 1.""فَضَاءٌ شَاسِعٌ"" : مَا اتَّسَعَ مِنَ الأَرْضِ. 2.""يُحَلِّقُ فِي الْفَضَاءِ"": فِي الْجَوِّ، أَيْ مَا يَعْلُو الأَرْضَ. ""أَدَارَ نَاظِرَيْهِ إِلَى فَوْقُ وَطَفِقَ يُحَدِّقُ فِي الْفَضَاءِ"". (حنا مينه). 3.""فَضَاءُ الْمَدِينَةِ"" : مِسَاحَتُهَا وَالْمَدَى الْوَاسِعُ الْمُحِيطُ بِهَا. 4.""أَرْضٌ فَضَاءٌ"" : مِسَاحَتُهَا الْوَاسِعَةُ. 5.""الْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22659, 'فَطُورٌ', 'فطور', 'مصدر', 'فطر', 'فطور', 'فطر', 'مص. فَطَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فَطُورٌ-فَطُورٌ [ف ط ر] (مص. فَطَرَ). 1.""وَجَدَهُ يَتَنَاوَلُ فَطُورَهُ"" : طَعَامُ الصَّبَاحِ، أَي الْوَجْبَةُ الأُولَى فِي الْيَوْمِ. 2.""يَتَنَاوَلُ فَطُورَهُ مَعَ الأَهْلِ فِي شَهْرِ رَمَضَانَ"" : طَعَامُ الصَّائِمِ بَعْدَ غُرُوبِ الشَّمْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22660, 'فَضْحٌ', 'فضح', 'مصدر', 'فضح', 'فضح', 'فضح', 'مص. فَضَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَضْحٌ-فَضْحٌ [ف ض ح] (مص. فَضَحَ). ""قَرَّرَ فَضْحَهُ أَمَامَ الْمَلَإِ"" : كَشْفَ مَسَاوِئِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22661, 'تَفْضِيضٌ', 'تفضيض', 'مصدر', 'فضض', 'تفضيض', 'تفضض', 'مص. فَضَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْضِيضٌ-تَفْضِيضٌ [ف ض ض] (مص. فَضَّضَ).""تَفْضِيضُ مَعْدِنٍ"" : تَمْوِيهُهُ بِالفِضَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22662, 'فُضُولٌ', 'فضول', 'مصدر', 'فضل', 'فضول', 'فضل', 'مص فَضَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"فُضُولٌ-فُضُولٌ [ف ض ل] (مص فَضَلَ). 1.""هُوَ كَثِيرُ الْفُضُولِ"" : يَسْعَى إِلَى التَّدَخُّلِ فِيمَا لاَ يَع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22663, 'تَفْضِيلٌ', 'تفضيل', 'مصدر', 'فضل', 'تفضيل', 'تفضل', 'مص. فَضَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْضِيلٌ-تَفْضِيلٌ [ف ض ل] (مص. فَضَّلَ). 1.""تَفْضِيلُهُ عَلَى غَيْرِهِ"" : جَعْلُهُ مُفَضَّلاً، مُتَقَدِّماً عَلَى غَيْرِهِ. ""وَفَضَّلَنَا اللَّهُ عَلَى كَثِيرٍ مِنْ خَلْقِهِ تَفْضِيلاً"". ("', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22664, 'فَضْلٌ', 'فضل', 'مصدر', 'فضل', 'فضل', 'فضل', 'مص. فَضَلَ', '', '', 'مفرد', 'DnN', '', '', '"أَفْضَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَضَلَ). ""لَنْ يَنْسَى فَضْلَهُ"" : إِحْسَانَهُ، كَرَمَهُ.يوسف آية 38ذَلِكَ مِنْ فَضْلِ اللَّهِ عَلَيْنَا (قرآن) ""لَهُ حَظٌّ مِنْ ثَرَاءٍ وَفَضْلٌ مِنْ نِعْمَةٍ"". 2.""يَرْجِعُ لَهُ الفَضْلُ فِي ذَلِكَ"" : هُوَ الْمُسْتَحِقُّ لِكُلِّ تَقْدِيرٍ. 3.""الْفَضْلُ ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22665, 'أَفْضَالٌ', 'أفضال', 'مصدر', '', 'ءفضال', 'فضل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22666, 'تَفْطِيرٌ', 'تفطير', 'مصدر', 'فطر', 'تفطير', 'تفطر', 'مص. فَطَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْطِيرٌ-تَفْطِيرٌ [ف ط ر] (مص. فَطَّرَ). 1.""تَفْطِيرُ الضُّيُوفِ"": تَقْدِيمُ طَعَامِ الفَطُورِ لَهُمْ. 2.""تَفْطِيرُ الصَّائِمِ"" : تَقْدِيمُ طَعَامِ الْفُطُورِ لَهُ فِي رَمَضَانَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22667, 'فَطْرٌ', 'فطر', 'مصدر', 'فطر', 'فطر', 'فطر', 'مص. فَطَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فُطْرٌ-فُطْرٌ (نب).: نَبَاتَاتٌ مِنَ اللاَّزَهْرِيَّاتِ، وَهُوَ أَنْوَاعٌ كَثِيرَةٌ، مِنْهَا مَا يُؤْكَلُ، وَمِنْهَا مَا هُوَ سَامٌّ وَطُفَيْلِيٌّ، لَهُ سَاقٌ وَقُبَّعَةٌ سَمِيكَةٌ لَيِّنَةٌ، مِنْ أَنْوَاعِهِ الْكَمْأَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22668, 'فُطْرٌ', 'فطر', 'مصدر', 'فطر', 'فطر', 'فطر', 'مص. فَطَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَطْرٌ-فَطْرٌ [ف ط ر] (مص. فَطَرَ). 1.""فَطْرُ اللَّحْمِ"" : شَقُّهُ. 2.""فَطْرُ الْعَالَمِ"" : خَلْقُهُ. 3.""فَطْرُ آلَةٍ"" : اِخْتِرَاعُهَا. 4.""فَطْرُ الْعَجِينِ"" : اِخْتِبَازُهُ دُونَ إِخْمَارِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22669, 'فُقْدَانٌ', 'فقدان', 'مصدر', 'فقد', 'فقدان', 'فقدن', 'مص. فَقَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فُقْدَانٌ-فُقْدَانٌ [ف ق د] (مص. فَقَدَ). 1.""فُقْدَانُ الذَّاكِرَةِ"" : ضَيَاعُهَا. 2.""فُقْدَانُ التَّوَازُنِ"" : اِنْعِدَامُهُ. ""فُقْدَانُ الأَمْنِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22670, 'تَفْطِينٌ', 'تفطين', 'مصدر', 'فطن', 'تفطين', 'تفطن', 'مص. فَطَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْطِينٌ-تَفْطِينٌ [ف ط ن] (مص. فَطَّنَ). 1.""تَفْطِينُهُ لِلأَمْرِ"" : تَنْبِيهُهُ، إِخْطَارُهُ، إِعْلاَمُهُ. 2.""تَفْطِينُ الوَلَدِ"" : جَعْلُهُ فَطِناً بِتَعْلِيمِهِ وَتَثْقِيفِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22671, 'فَطَانَةٌ', 'فطانة', 'مصدر', 'فطن', 'فطانة', 'فطنة', 'مص. فَطِنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فَطَانَةٌ-فَطَانَةٌ [ف ط ن] (مص. فَطِنَ). ""أَظْهَرَ فطَانَةً"" : نَبَاهَةً، حِذْقاً، أَيْ قُوَّةَ إِدْرَاكِ الشَّيْءِ بِسُرْعَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22672, 'فَظَاظَةٌ', 'فظاظة', 'مصدر', 'فظظ', 'فظاظة', 'فظظة', 'مص. فَظَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فَظَاظَةٌ-فَظَاظَةٌ [ف ظ ظ] (مص. فَظَّ). ""أَظْهَرَ فَظَاظَةً"" : أَيْ خُشُونَةً فِي الْكَلاَمِ، سُوءَ الْخُلُقِ. ""يَخْشَاهُ النَّاسُ لِفَظَاظَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22673, 'فَظَاعَةٌ', 'فظاعة', 'مصدر', 'فظع', 'فظاعة', 'فظعة', 'مص. فَظُعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":فَظَائِعُ"', '', 'R', '', '', '', '', '', '', '"(مص. فَظُعَ). ""يَا لَلْفَظَاعَةِ!"" : يَا لَلَْشَّنَاعَةِ، تُقَالُ لِحَدَثٍ أَوْ أَمْرٍ شَنِيعٍ جِدّاً. ""فَظَاعَةُ جَرِيمَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22674, 'فَظَائِعُ', 'فظائع', 'مصدر', '', 'فظاءع', 'فظع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22675, 'فَعَالٌ', 'فعال', 'مصدر', 'فعل', 'فعال', 'فعل', 'مص. فَعَال', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فَعَالٌ-فَعَالٌ [ف ع ل] (مص. فَعَال). ""يُحْمَدُ عَلَى فَعَالِهِ"" : عَلَى فِعْلِهِ الْحَمِيدِ الْحَسَنِ. ""حُسْنُ فَعَالٍ"" ""سُوءُ فَعَالٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22676, 'تَفْعِيلٌ', 'تفعيل', 'مصدر', 'فعل', 'تفعيل', 'تفعل', 'مص. فَعَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْعِيلٌ-تَفْعِيلٌ [ف ع ل] (مص. فَعَّلَ). ""تَفْعِيلُ بَيْتِ شِعْرٍ"" : تَقْطِيعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22677, 'تفاعيل', 'تفاعيل', 'مصدر', '', 'تفاعيل', 'تفعل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22678, 'فَغْرٌ', 'فغر', 'مصدر', 'فغر', 'فغر', 'فغر', 'مص. فَغَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَغْرٌ-فَغْرٌ [ف غ ر] (مص. فَغَرَ). 1.""وَرْدٌ فَغْرٌ"" : مُتَفَتِّحٌ. 2.""وَاسِعُ فَغْرِ الفَمِ"" : وَاسِعُ بَابِ الفَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22679, 'تَفْكِيرٌ', 'تفكير', 'مصدر', 'فكر', 'تفكير', 'تفكر', 'مص. فَكَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْكِيرٌ-تَفْكِيرٌ [ف ك ر] (مص. فَكَّرَ). ""التَّفْكِيرُ فِي الْمَوْضُوع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22680, 'فَقْدٌ', 'فقد', 'مصدر', 'فقد', 'فقد', 'فقد', 'مص. فَقَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَقْدٌ-فَقْدٌ [ف ق د] (مص. فَقَدَ). ""فَقْدُ الْمَالِ"" : خَسَارَتُهُ، ضَيَاعُهُ. ""فَقْدُ الإِحْسَاسِ"" ""فَقْدُ الْحُظْوَةِ"" ""إِنَّ التَّرْبِيَةَ هِيَ ضَالَّةُ الأُمَمِ وَفَقْدُهَا مُصِيبَةٌ عُظْمَى"". (ع. الكواكبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22681, 'فَقْرٌ', 'فقر', 'مصدر', 'فقر', 'فقر', 'فقر', 'مص. فَقَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَقْرٌ-فَقْرٌ [ف ق ر] (مص. فَقَرَ). ""اِشْتَدَّ فَقْرُهُ"" : اِحْتِيَاجُهُ، أَيْ لَمْ يَعُدْ يَمْلِكُ مَا يَكْفِيهِ مِنَ الْمَوَارِدِ لِعَيْشِهِ.كَادَ الْفَقْرُ أَنْ يَكُونَ كُفْرا (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22682, 'تَفْقِيعٌ', 'تفقيع', 'مصدر', 'فقع', 'تفقيع', 'تفقع', 'مص. فَقَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْقِيعٌ-تَفْقِيعٌ [ف ق ع] (مص. فَقَّعَ). 1.""تَفْقِيعُ الأَصَابِعِ"" : تَفَرْقُعُهَا. 2.""التَّفْقِيعُ فِي الْكَلاَمِ"" : التَّكَلُّمُ دُونَ قَوْلِ شَيْءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22683, 'فَقْمٌ', 'فقم', 'مصدر', 'فقم', 'فقم', 'فقم', 'مص. فَقَمَ، فَقِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَقْمٌ-فَقْمٌ [ف ق م] (مص. فَقَمَ، فَقِمَ). 1.""فَقْمُ الكَلْبِ"" : طَرَفُ خَطْمِهِ. 2.""أَصَابَ فَقْمَهُ"" : فَكَّهُ، وَهُمَا فَقْمَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22684, 'تَفْقِيهٌ', 'تفقيه', 'مصدر', 'فقه', 'تفقيه', 'تفقه', 'مص. فَقَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْقِيهٌ-تَفْقِيهٌ [ف ق هـ] (مص. فَقَّهَ). ""سَعَى إِلَى تَفْقِيهِهِ عُلُومَ الْعَصْرِ"" : تَفْهِيمُهَا وَتَعْلِيمُهَا إِيَّاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22685, 'فِقْهٌ', 'فقه', 'مصدر', 'فقه', 'فقه', 'فقه', 'مص. فَقِهَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فِقْهٌ-فِقْهٌ [ف ق هـ] (مص. فَقِهَ). 1.""يَمْتَازُ بِفِقْهِهِ"" : بِعِلْمِهِ وَفِطْنَتِهِ. 2.""لَهُ اطِّلاَعٌ وَاسِعٌ عَلَى أَحْكَامِ الْفِقْهِ"" : الْعِلْمُ بِالأَحْكَامِ الشَّرْعِيَّةِ، الدِّينِيَّةِ. 3.""فِقْهُ اللُّغَةِ"" : عُلُومُ اللُّغَةِ وَتَارِيخُهَا وَأُصُولُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22686, 'فِكَاكٌ', 'فكاك', 'مصدر', 'فكك', 'فكاك', 'فكك', 'مص. فَكَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فِكَاكٌ-فِكَاكٌ، فَكَاكٌ [ف ك ك] (مص. فَكَّ). ""فِكَاكُ الأَسِيرِ"" : مَا يُفَكُّ بِهِ لِخَلاَصِه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22687, 'فَكٌّ', 'فك', 'مصدر', 'فكك', 'فك', 'فك', 'مص. فَكَّ', '', '', 'مفرد', 'DnN', '', '', '"فُكُوكٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَكَّ). 1.: (تش). عَظْمُ الْحَنَكِ الَّذِي عَلَيْهِ الأَسْنَانُ، وَهُمَا فَكَّانِ أَعْلَى وَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22688, 'فُكُوكٌ', 'فكوك', 'مصدر', '', 'فكوك', 'فكك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22689, 'فَلْسَفَةٌ', 'فلسفة', 'مصدر', 'فلسف', 'فلسفة', 'فلسفة', 'مص. فَلْسَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"فَلْسَفَةٌ-فَلْسَفَةٌ [ف ل س ف] (مص. فَلْسَفَ). : كَلِمَةٌ تَعْنِي فِي الأَصْلِ الْحِكْمَةَ، مَحَبَّةَ الْحِكْمَةِ، وَصَارَ يُقْصَدُ بِهَا كُلُّ الأَفْكَارِ الْمُسْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22690, 'فِكْرٌ', 'فكر', 'مصدر', 'فكر', 'فكر', 'فكر', 'مص. فَكَرَ', '', '', 'مفرد', 'DnN', '', '', '"أَفْكَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَكَرَ). 1. : تَكَوُّنُ الآرَاءِ وَالْخَوَاطِرِ فِي عَقْلِ الإِنْسَانِ وَبَلْوَرَتُهَا فِي نُصُوصٍ وَتَدَبُّرُ الأَشْيَاءِ بِالتَّأَمُّلِ وَإِعْمَالِ الْعَقْلِ. 2.""هُوَ مِنْ رِجَالِ الْفِكْرِ"" : مِنَ الْعُلَمَاءِ، مِنْ أَهْلِ الرَّأْيِ. 3.""حَاوَلَ إِعْمَالَ الْفِكْرِ"" : إِعْمَالَ الْعَقْلِ. 4."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22691, 'أَفْكَارٌ', 'أفكار', 'مصدر', '', 'ءفكار', 'فكر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22692, 'تَفْكِيكٌ', 'تفكيك', 'مصدر', 'فكك', 'تفكيك', 'تفكك', 'مص. فَكَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْكِيكٌ-تَفْكِيكٌ [ف ك ك] (مص. فَكَّكَ). ""تَفْكِيكُ الآلَةِ"": فَكُّ أَجْزَاءِ بَعْضِهَا عَنْ بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22693, 'فَلٌّ', 'فل', 'مصدر', 'فلل', 'فل', 'فل', 'مص. فَلَّ', '', '', 'مفرد', 'DnN', '', '', '"فُلُولٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَلَّ). 1.""فَلُّ السَّيْفِ"": كَسْرٌ فِي حَدِّهِ. ""فُلُولُ السَّيْفِ"". 2.""فَلُّ الْحَدِيدِ أَوِ الفِضَّةِ أَوِ الذَّهَبِ أَوِ النَّارِ"" : م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22694, 'فُلُولٌ', 'فلول', 'مصدر', '', 'فلول', 'فلل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22695, 'فَلاَحٌ', 'فلاح', 'مصدر', 'فلح', 'فلاح', 'فلح', 'مص. فَلَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَلاَحٌ-فَلاَحٌ [ف ل ح] (مص. فَلَحَ). 1.""تَمَنَّى لَهُ الْفلاَحَ"": الْفَوْزَ. 2.""حَيَّ عَلَى الْفَلاَحِ"" : هَلُمَّ إِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22696, 'فَلْحٌ', 'فلح', 'مصدر', 'فلح', 'فلح', 'فلح', 'مص. فَلَحَ', '', '', 'مفرد', 'DnN', '', '', '"فُلُوحٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَلَحَ). ""تَرَكَ فِي الأَرْضِ فَلْحاً"" : شَقّاً. ""عَادَ مِنَ الْجَبَلِ حَافِياً وَفِي رِجْلِهِ فُلُوحٌ""."', '');
