INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22699, 'تَفْلِيقٌ', 'تفليق', 'مصدر', 'فلق', 'تفليق', 'تفلق', 'مص. فَلَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْلِيقٌ-تَفْلِيقٌ [ف ل ق] (مص. فَلَّقَ). ""تَفْلِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22700, 'فَلْقٌ', 'فلق', 'مصدر', 'فلق', 'فلق', 'فلق', 'مص. فَلَقَ', '', '', 'مفرد', 'DnN', '', '', '"فُلُوقٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَلَقَ). 1.""فَلْقُ الرَّأْسِ"" : مَفْرِقُهُ وَوَسَطُهُ. 2.""فَلْقُ الصَّبَاحِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22701, 'فُلُوقٌ', 'فلوق', 'مصدر', '', 'فلوق', 'فلق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
