INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22703, 'فَنَدٌ', 'فند', 'مصدر', 'فند', 'فند', 'فند', 'مص. فَنِدَ', '', '', 'مفرد', 'DnN', '', '', '"أَفْنَادٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَنِدَ). 1.""نَهَاهُ عَنِ الفَنَدِ"" : عَنِ البَاطِلِ، أَو"', '');
