INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22706, 'فَنَاءٌ', 'فناء', 'مصدر', 'فني', 'فناء', 'فن', 'مص. فَنِيَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"فَنَاءٌ-فَنَاءٌ [ف ن ي] (مص. فَنِيَ). ""فَنَاءُ الإِنْسَانِ"" : زَوَالُهُ، هَلاَكُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22707, 'تَفْهِيمٌ', 'تفهيم', 'مصدر', 'فهم', 'تفهيم', 'تفهم', 'مص. فَهَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْهِيمٌ-تَفْهِيمٌ [ف هـ م] (مص. فَهَّمَ). ""تَفَرَّغَ لِتَفْه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22708, 'فَهْمٌ', 'فهم', 'مصدر', 'فهم', 'فهم', 'فهم', 'مص. فَهِمَ', '', '', 'مفرد', 'DnN', '', '', '"أَفْهَامٌ"', '', 'R', '', '', '', '', '', '', '"(مص. فَهِمَ). 1.""فَهْمُ الدَّرْسِ"" : إِدْرَاكُهُ وَتَحْصِيلُهُ. 2.""سُوءُ الْفَهْمِ"" : سُوءُ الإِدْرَاكِ وَالتَّحْصِيلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22709, 'أَفْهَامٌ', 'أفهام', 'مصدر', '', 'ءفهام', 'فهم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
