INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22711, 'تَفْوِيقٌ', 'تفويق', 'مصدر', 'فوق', 'تفويق', 'تفق', 'مص. فَوَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَفْوِيقٌ-تَفْوِيقٌ [ف و ق] (مص. فَوَّقَ). ""تَفْوِيقُ الصَّدِيقِ عَلَى غَيْرِهِ"" : تَفْضِيلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22712, 'فَوَقٌ', 'فوق', 'مصدر', 'فوق', 'فوق', 'فق', 'مص. فَوِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَوَقٌ-فَوَقٌ [ف و ق] (مص. فَوِقَ). ""فَوَقُ السَّهْمِ"" : مَيْلٌ وَانْكِسَارٌ فِي فُوقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22713, 'فَوَهٌ', 'فوه', 'مصدر', 'فوه', 'فوه', 'فه', 'مص. فَوِهَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"فَوْهٌ-فَوْهٌ [ف و هـ] (مص. فَاهَ). ""لَمْ يَكُنْ فَوْهُهُ سَلِيماً"": نُطْقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22714, 'قَيْءٌ', 'قيء', 'مصدر', 'قيأ', 'قيء', 'ق', 'مص. قَاءَ', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"قَيْءٌ-قَيْءٌ [ق ي أ] (مص. قَاءَ). ""قَيْءُ الْمَعِدَةِ"" : مَا تَقْذِفُهُ الْمَعِدَةُ بِسَبَبِ مَرضٍ أَوْ تَسَمُّمٍ أَوْ سُوءِ هَضْمٍ. ""لَمْ يَتَوَقَّفْ عَنِ القَيْءِ النَّهَارَ كُلَّهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22715, 'مُقَابَلَةٌ', 'مقابلة', 'مصدر', 'قبل', 'مقابلة', 'مقبلة', 'مص. قَابَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. قَابَلَ). 1.""أَجْرَى مُقَابَلَةً مَعَ الرَئِيسِ"" : أَيْ لِقَاءً وَجْهاً لِوَجْهٍ. 2.""سَلَّمَهُمْ بِضَاعَةً بِالْمُقَابَلَةِ"" : بِالبَدَلِ، بِالْمُقايَضَةِ. ""فِي مُقَابَلَةِ ذَلِكَ"". 3.""أَجْرَى مُقَابَلَةً صَحَفِيَّةً"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22716, 'قِتَالٌ', 'قتال', 'مصدر', 'قتل', 'قتال', 'قتل', 'مص. قَاتَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"قِتَالٌ-قِتَالٌ [ق ت ل] (مص. قَاتَلَ). 1.""دَارَ بَيْنَ الْفَرِيقَيْنِ قِتَالٌ عَنِيفٌ"" : تَطَاحُنٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22717, 'قَيْحٌ', 'قيح', 'مصدر', 'قيح', 'قيح', 'قح', 'مص. قَاحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَيْحٌ-قَيْحٌ [ق ي ح] (مص. قَاحَ). ""أَفْرَغَ الْجُرْحَ مِنَ القَيْحِ"" : الصَّدِيد، مِنْ إِفْرَازَاتِ سَائِلٍ لَزِجٍ مُصْفَرٍّ يُحِيطُ بِالْجُرُوحِ نَتِيجَةَ الْتِهَابِ الأَنْسِجَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22718, 'قِيَادَةٌ', 'قيادة', 'مصدر', 'قود', 'قيادة', 'قدة', 'مص. قَادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"قِيَادَةٌ-قِيَادَةٌ [ق و د] (مص. قَادَ). 1.""قِيَادَةُ شَعْبٍ"" : تَدْبِيرُ شُؤُونِهِ، تَرَؤُّسُهُ. 2.""نَجَحَ فِي مَهَامِّ القِيَادَةِ"" : مِهْنَة القِيَادَةِ. 3.""وَصَلَ إِلَى مَقَرِّ القِيَادَةِ"" : الْمَكَانُ الَّذِي يَكُونُ فِيهِ القَائِدُ. 4.""القِيَادَةُ العَامَّةُ لِلْجَيْشِ"" : الْمَرْكَزُ الَّذِي يَسْتَقِرُّ فِيهِ القَائِدُ العَامُّ وَالضُّبَّاطُ الكِبَارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22719, 'قُيُوظٌ', 'قيوظ', 'مصدر', '', 'قيوظ', 'قظ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22720, 'قِيَادٌ', 'قياد', 'مصدر', 'قيد', 'قياد', 'قد', 'مص. قَادَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"قِيَادٌ-قِيَادٌ [ق ي د] (مص. قَادَ). 1.""أَمْسَكَ بِقِيَادِ دَابَّتِهِ"" : الْحَبْلُ الَّذِي تُقَادُ بِهِ. 2.""عَرَفْتُهُ رَجُلاً سَلِسَ القِيَادِ"" : أَيْ مِطْوَاعاً، يُطَاوِعُ الآخَرِينَ عَلَى هَوَاهُمْ وَحَسَبَ رَغَبَاتِهِمْ. 3.""أَعْطَى القِيَادَ"" : خَضَعَ، أَطَاعَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22721, 'قَوْرٌ', 'قور', 'مصدر', 'قور', 'قور', 'قر', 'مص. قَارَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَوْرٌ-قَوْرٌ [ق و ر] (مص. قَارَ). 1. : حَبْلٌ جَيِّدٌ مِنَ القُطْنِ الْحَدِيثِ. 2.: قُطْنٌ حَدِيثٌ، أَوْ مَا زُرِعَ لِعَامِهِ، أَيْ حَدِيثاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22722, 'مُقَارَبَةٌ', 'مقاربة', 'مصدر', 'قرب', 'مقاربة', 'مقربة', 'مص. قَارَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَارَبَةٌ-مُقَارَبَةٌ [ق ر ب] (مص. قَارَبَ). ""مُقَارَبَةُ نَصٍّ"" : النَّظَرُ فِيهِ، تَحْلِيلُهُ لِمَعْرِفَةِ أَوْجُهِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22723, 'مُقَارَعَةٌ', 'مقارعة', 'مصدر', 'قرع', 'مقارعة', 'مقرعة', 'مص. قَارَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَارَعَةٌ-مُقَارَعَةٌ [ق ر ع] (مص. قَارَعَ). ""مُقَارَعَةُ الأَعْدَاءِ"" : مُصَارَعَتُهُمْ، مُضَارَبَتُهُمْ. ""ومَا يَمْنَعُ الأُنْثَى أَنْ تَكُونَ كَالذَّكَرِ فِي مُقَارَعَةِ الخُطُوبِ ومُلاَقَاةِ الأَهْوَالِ"". (إسحق الحسيني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22724, 'مُقَارَنَةٌ', 'مقارنة', 'مصدر', 'قرن', 'مقارنة', 'مقرنة', 'مص. قَارَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَارَنَةٌ-مُقَارَنَةٌ [ق ر ن] (مص. قَارَنَ). 1.""مُقَارَنَةُ عَمَلَيْنِ"" : الْمُوَازَنَةُ ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22725, 'مُقَاصَّةٌ', 'مقاصة', 'مصدر', 'قصص', 'مقاصة', 'مقصة', 'مص. قَاصَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَاصَّةٌ-مُقَاصَّةٌ [ق ص ص] (مص. قَاصَّ). 1.""اِتَّفَقُوا عَلَى حَلِّ خِلاَفِهِمُ التِّجَارِيِّ بِالْمُقَاصَّةِ"" : بِالتَّرَاضِي "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22726, 'مُقَاطَعَةٌ', 'مقاطعة', 'مصدر', 'قطع', 'مقاطعة', 'مقطعة', 'مص. قَاطَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. قَاطَعَ). 1.""مُقَاطَعَةُ البَضَائِعِ الصُّهْيُونِيَّةِ"" : عَدَمُ التَّعَامُلِ مَعَهَا تِجَارِيّاً، الاِمْتِنَاعُ عَنْ شِرَائِهَا. 2. ""مُقَاطَعَةُ الانْتِخَابَاتِ"" : عَدَمُ الْمُشَارَكَةِ فِيهَا. 3.""مُقَاطَعَةُ الْمُتَكَلِّمِ"" : التَّكَلُّمُ أَثْنَاءَ كَلاَمِهِ. 4"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22727, 'قَيْظٌ', 'قيظ', 'مصدر', 'قيظ', 'قيظ', 'قظ', 'مص. قَاظَ', '', '', 'مفرد', 'DnN', '', '', '"أَقْيَاظٌ:قُيُوظٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَاظَ). ""اِشْتَدَّ قَيْظُ الصَّيْفِ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22728, 'أَقْيَاظٌ', 'أقياظ', 'مصدر', '', 'ءقياظ', 'قظ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22729, 'قَامَةٌ', 'قامة', 'مصدر', 'قوم', 'قامة', 'قمة', 'مص. قَامَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. قَامَ). ""طَوِيلُ الْقَامَةِ"": طَوِيلُ الْقَدِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22730, 'قَالٌ', 'قال', 'مصدر', 'قول', 'قال', 'قل', 'مص. قَالَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَالٌ-قَالٌ [ق و ل] (مص. قَالَ). ""مَا هَذَا الْقَالُ وَالْقِيلُ "": مَا يَقُولُهُ النَّاسُ عَنْ بَعْضِهِمْ. ""كَثُرَ قَالُ النَّاسِ وَقِيلُهُمْ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22731, 'قَوْلٌ', 'قول', 'مصدر', 'قول', 'قول', 'قل', 'مص. قَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَقْوَالٌ:أَقَاوِيلُ"', '', 'R', '', '', '', '', '', '', '"(مص. قَالَ). 1.""اِسْتَمَعَ إِلَى قَوْلِهِ"" : إِلَى كَلاَمِهِ. 2.""يُؤَكِّدُ فِي كُلِّ مَجْلِسٍ قَوْلَهُ"" : رَأْيَهُ، اِعْتِقَادَهُ. ‏ ""مَا قَوْلُكَ فِي هَذِهِ القَضِيَّةِ "" ""يُبَالِغُ فِي القَوْلِ"". 3.""يُرَدِّدُ القَوْلَ نَفْسَهُ"" : يُرَدِّدُ الشَّيْءَ نَفْسَهُ. 4.""أَجْمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22732, 'قَوْلَةٌ', 'قولة', 'مصدر', 'قول', 'قولة', 'قلة', 'مص. قَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَقْوَالٌ:أَقَاوِيلُ"', '', 'R', '', '', '', '', '', '', '"(مص. قَالَ). 1.""اِسْتَمَعَ إِلَى قَوْلِهِ"" : إِلَى كَلاَمِهِ. 2.""يُؤَكِّدُ فِي كُلِّ مَجْلِسٍ قَوْلَهُ"" : رَأْيَهُ، اِعْتِقَادَهُ. ‏ ""مَا قَوْلُكَ فِي هَذِهِ القَضِيَّةِ "" ""يُبَالِغُ فِي القَوْلِ"". 3.""يُرَدِّدُ القَوْلَ نَفْسَهُ"" : يُرَدِّدُ الشَّيْءَ نَفْسَهُ. 4.""أَجْمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22733, 'أَقْوَالٌ', 'أقوال', 'مصدر', '', 'ءقوال', 'قل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22734, 'أَقَاوِيلُ', 'أقاويل', 'مصدر', '', 'ءقاويل', 'قل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22735, 'مَقَالٌ', 'مقال', 'مصدر', 'قول', 'مقال', 'مقل', 'مص. قَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. قَالَ). 1.""مَقَالٌ مُؤَثِّرٌ"" : قَوْلٌ. ""لِكُلِّ مَقَامٍ مَقَالٌ"" ""لِسَانُ الْحَالِ أَبْيَنُ مِنْ لِسَانِ الْمَقَالِ"". 2. ""مَقَالٌ أَدَبِيٌّ"" : بَحْثٌ قَصِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22736, 'مَقَالَةٌ', 'مقالة', 'مصدر', 'قول', 'مقالة', 'مقلة', 'مص. قَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. قَالَ). 1.""مَقَالٌ مُؤَثِّرٌ"" : قَوْلٌ. ""لِكُلِّ مَقَامٍ مَقَالٌ"" ""لِسَانُ الْحَالِ أَبْيَنُ مِنْ لِسَانِ الْمَقَالِ"". 2. ""مَقَالٌ أَدَبِيٌّ"" : بَحْثٌ قَصِي"', '');
