INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22738, 'قَيْلُولَةٌ', 'قيلولة', 'مصدر', 'قيل', 'قيلولة', 'قللة', 'مص. قَالَ، يَقِيلُ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَيْلُولَةٌ-قَيْلُولَةٌ [ق ي ل] (مص. قَالَ، يَقِيلُ). 1.""يَنَامُ فِي القَيْلُولَةِ"" : فِي الظَّهِيرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22739, 'قِيَانٌ', 'قيان', 'مصدر', '', 'قيان', 'قن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22740, 'قَوْمٌ', 'قوم', 'مصدر', 'قوم', 'قوم', 'قم', 'مص. قَامَ', '', '', 'مفرد', 'DnN', '', '', '"أَقْوَامٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. قَامَ). 1.""اِسْتَشَارَ القَوْمَ"" : الجَمَاعَةَ مِنَ النَّاسِ. 2.""قَوْمُ الرَّجُلِ"" : أَقْرِبَاؤُهُ الَّذِينَ يَجْتَمِعُونَ مَعَهُ فِي جَدٍّ وَاحِدٍ أَوْ سُلاَلَةٍ وَاحِدَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22741, 'أَقْوَامٌ', 'أقوام', 'مصدر', '', 'ءقوام', 'قم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22742, 'قِيَامٌ', 'قيام', 'مصدر', 'قوم', 'قيام', 'قم', 'مص. قَامَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قِيَامٌ-قِيَامٌ [ق و م] (مص. قَامَ). 1.""قِيَامُ الرَّجُلِ"" : وُقُوفُهُ. ""أَخَذَهَا وَهُوَ لاَ يَكَادُ يَقْوَى عَلَى القِيَامِ"".(عبد الحكيم قاسم). 2.""شَجَّعَهُ لِلْقِيَامِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22743, 'مُقَامَرَةٌ', 'مقامرة', 'مصدر', 'قمر', 'مقامرة', 'مقمرة', 'مص. قَامَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَامَرَةٌ-مُقَامَرَةٌ [ق م ر] (مص. قَامَرَ). ""الْمُقَامَرَةُ بِالأَمْوَالِ"" : اللَّعِبُ بِهَا قِمَاراً، أَيْ لَعِبٌ قَائِمٌ عَلَى الصُّدْفَةِ وَالْحَظِّ للفَوْزِ، وَالنَّتِيجَةُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22744, 'قَيْنٌ', 'قين', 'مصدر', 'قين', 'قين', 'قن', 'مص. قَانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَقْيَانٌ:قِيَانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَانَ). 1.""رَجُلٌ قَيْنٌ"" : حَدَّادٌ، وَأَصْبَحَ يُطْلَقُ عَلَى كُلِّ صَانِعٍ. 2.""قَيْنُ السَّيِّدِ"" : عَبْدُهُ. ‏ ""اِنْتَهَى عَهْدُ القِيَانِ"". 3.""غَنَّتِ "', '');
