INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22747, 'قَيْنَةٌ', 'قينة', 'مصدر', 'قين', 'قينة', 'قنة', 'مص. قَانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَقْيَانٌ:قِيَانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَانَ). 1.""رَجُلٌ قَيْنٌ"" : حَدَّادٌ، وَأَصْبَحَ يُطْلَقُ عَلَى كُلِّ صَانِعٍ. 2.""قَيْنُ السَّيِّدِ"" : عَبْدُهُ. ‏ ""اِنْتَهَى عَهْدُ القِيَانِ"". 3.""غَنَّتِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22748, 'أَقْيَانٌ', 'أقيان', 'مصدر', '', 'ءقيان', 'قن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22749, 'تَقْبيبٌ', 'تقبيب', 'مصدر', 'قبب', 'تقبيب', 'تقبب', 'مص. قَبَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْبيبٌ-تَقْبيبٌ [ق ب ب] (مص. قَبَّبَ). ""تَقْبيبُ الْمَسْجِدِ"": إِقامَةُ قُبَّةٍ فَوْقَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22750, 'مُقَاوَلَةٌ', 'مقاولة', 'مصدر', 'قول', 'مقاولة', 'مقلة', 'مص. قَاوَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. قَاوَلَ). ""مُقَاوَلَةُ مَشْرُوعٍ"" : اِتِّفَاقٌ بَيْنَ الْمُقَاوِلِ وصَاحِبِ الْمَشْرُوعِ عَلَى إِنْجَازِهِ مُقَابِلَ أَجْرٍ مُحَدَّدٍ فِي زَمَنٍ مُعَيَّنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22751, 'قِوَامٌ', 'قوام', 'مصدر', 'قوم', 'قوام', 'قم', 'مص. قَاوَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قِوَامٌ-قِوَامٌ [ق و م] (مص. قَاوَمَ). 1.""لَهُ مَا يَكْفِيهِ مِنَ القِوَامِ"" : مَا يَكْفِيهِ مِنَ القُوتِ. 2.""قِوَامُ الأَمْرِ"" : نِظَامُهُ، عِمَادُهُ. ""الْمَدِينَةُ الْحَدِيثَةُ قِوَامُهَا الصَّنَائِعُ وَالفُنُونُ"". 3.""هُوَ قِوَامُ أَهْلِهِ"" : أَيْ يُقِيمُ شَأْنَهُمْ. 4.""رُمْحٌ قِوَامٌ"" : مُسْتَقِيمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22752, 'مُقَاوَمَةٌ', 'مقاومة', 'مصدر', 'قوم', 'مقاومة', 'مقمة', 'مص. قَاوَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. قَاوَمَ). 1.""مُقَاوَمَةُ العُنْفِ بِالعُنْفِ"" : مُوَاجَهَةُ... ""قَرَّرَ مُقَاوَمَةَ العَنَاصِرِ الفَاسِدَةِ"". 2. ""الْمُقَاوَمَةُ الشَّعْبِيَّةُ"" : حَرَكَةٌ شَعْبِيَّةٌ مُنَاضِلَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22753, 'قِيَاسٌ', 'قياس', 'مصدر', 'قيس', 'قياس', 'قس', 'مص. قَايَسَ', '', '', 'مفرد', 'DnN', '', '', '"أَقْيِسَةٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. قَايَسَ). 1.""حَدَّدَ قِيَاسَ طُولِ الْمَسَافَةِ"" : مَقَاسَهَا، كَمْ تَبْلُغُ مِنَ الأَمْتَارِ وَالكِيلُومِتْرَاتِ. ""بَحْرٌ وَاسِعٌ لاَ حَدَّ لَهُ وَلاَ قِيَاسَ لَهُ"". (جبران خ. جبران). 2.""وَجَدَ الحِذَاءَ عَلَى قِيَاسِهِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22754, 'أَقْيِسَةٌ', 'أقيسة', 'مصدر', '', 'ءقيسة', 'قسة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22755, 'مُقَايَسَةٌ', 'مقايسة', 'مصدر', 'قيس', 'مقايسة', 'مقسة', 'مص. قَايَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَايَسَةٌ-مُقَايَسَةٌ [ق ي س] (مص. قَايَسَ). ""مُقَايَسَةُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22756, 'مُقَايَضَةٌ', 'مقايضة', 'مصدر', 'قيض', 'مقايضة', 'مقضة', 'مص. قَايَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُقَايَضَةٌ-مُقَايَضَةٌ [ق ي ض] (مص. قَايَضَ). ""بَيْعُ الْمُقَايَضَةِ "": بَيْعٌ بِالْمُبَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22757, 'قَبْوٌ', 'قبو', 'مصدر', 'قبو', 'قبو', 'قب', 'مص. قَبَا', '', '', 'مفرد', 'DnN', '', '', '"أَقْبَاءٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَبَا). 1.""جَلَسَ تَحْتَ الْقَبْوِ"" : بِنَاءٌ مُسْتَدِيرٌ مُقَوَّسُ، مَعْقُودٌ بَعْضُهُ إِلَى بَعْضٍ. ""قَابِعٌ فِي الْقَبْوِ الدَّاف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22758, 'أَقْبَاءٌ', 'أقباء', 'مصدر', '', 'ءقباء', 'قب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22759, 'قَبَلٌ', 'قبل', 'مصدر', 'قبل', 'قبل', 'قبل', 'مص. قَبِلَ', '', '', 'مفرد', 'DnN', '', '', '"أَقْبَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَبِلَ). 1.""قَبَلٌ فِي العَيْنِ"" : إِقْبَالُ سَوَادِهَا عَلَىالأَنْفِ أَوِ الْحَاجِبِ. 2.""قَبَلٌ فِي العَيْنَيَنِ"" : إِقْبَالُ نَظ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22760, 'تَقْبيحٌ', 'تقبيح', 'مصدر', 'قبح', 'تقبيح', 'تقبح', 'مص. قَبَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْبيحٌ-تَقْبيحٌ [ق ب ح] (مص. قَبَّحَ). 1.""تَقْبيحُ فِعْلٍ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22761, 'قُبْحٌ', 'قبح', 'مصدر', 'قبح', 'قبح', 'قبح', 'مص. قَبُحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُبْحٌ-قُبْحٌ [ق ب ح] (مص. قَبُحَ). 1.""قُبْحُ الصُّورَةِ"" : بَشَاعَتُه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22762, 'قَبْرٌ', 'قبر', 'مصدر', 'قبر', 'قبر', 'قبر', 'مص. قَبَرَ', '', '', 'مفرد', 'DnN', '', '', '"قُبُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَبَرَ). ""وَارَاهُ فيِ قَبْرِهِ"": الْحُفْرَةُ الَّتِي يُدْفَنُ فِي"', '');
