INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22765, 'تَقْبيضٌ', 'تقبيض', 'مصدر', 'قبض', 'تقبيض', 'تقبض', 'مص. قَبَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْبيضٌ-تَقْبيضٌ [ق ب ض] (مص. قَبَّضَ). 1.""تَقْبيضُ الحشائِشِ"" "', '');
