INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22767, 'قُبُوعٌ', 'قبوع', 'مصدر', 'قبع', 'قبوع', 'قبع', 'مص. قَبَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قُبُوعٌ-قُبُوعٌ [ق ب ع] (مص. قَبَعَ). 1.""قُبُوعُ قُنْفُذٍ"" : إِدْخَالُ رَأْسِهِ فِي جِلْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22768, 'قَبْقَبَةٌ', 'قبقبة', 'مصدر', 'قبقب', 'قبقبة', 'قبقبة', 'مص. قَبْقَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَبْقَبَةٌ-قَبْقَبَةٌ [ق ب ق ب] (مص. قَبْقَبَ). ""قَب"', '');
