INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22774, 'قَتَّةٌ', 'قتة', 'مصدر', 'قتت', 'قتة', 'قتة', 'مص. قَتَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَتٌّ-قَتٌّ، ةٌ [ق ت ت] (مص. قَتَّ). 1.""لاَ يَحْكِي إِلاَّ القَتَّ"" : الكَذِبَ الْمُهَيَّأَ. 2.""أَطْعَمَ دَابَّتَهُ القَتَّ"" : الفِصْفِصَة"', '');
