INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22777, 'قَتْلٌ', 'قتل', 'مصدر', 'قتل', 'قتل', 'قتل', 'مص. قَتَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَتْلٌ-قَتْلٌ [ق ت ل] (مص. قَتَلَ). 1.""قَتْلُ الأَعْدَاءِ"" : الْفَتْكُ بِهِمْ وَإِزْهَاقُ أَرْوَاحِهِمْ. البقرة آية 191وَالْفِتْنَةُ أَشَدُّ مِنَ الْقَتْلِ ( قرآن). 2.""ا"', '');
