INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22790, 'قَدْحٌ', 'قدح', 'مصدر', 'قدح', 'قدح', 'قدح', 'مص. قَدَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَدْحٌ-قَدْحٌ [ق د ح] (مص. قَدَحَ). ""تَعَرَّضَ لِلْقَدْحِ"" : لِلطَّعْنِ وَالذَّمِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22791, 'تَقْدِيدٌ', 'تقديد', 'مصدر', 'قدد', 'تقديد', 'تقدد', 'مص. قَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْدِيدٌ-تَقْدِيدٌ [ق د د] (مص. قَدَّدَ). ""تَقْدِيدُ اللَّحْمِ"" : تَقْطيعُهُ قِطَعاً وَتَجْفِيفُهُ وَتَمْلِيحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22792, 'تَقْديرٌ', 'تقدير', 'مصدر', 'قدر', 'تقدير', 'تقدر', 'مص. قَدَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْديرٌ-تَقْديرٌ [ق د ر] (مص. قَدَّرَ). 1.""لَمْ يَسْتَطِعْ تَقْديرَ مُمْتَلَكاتِهِ"" : حِسابَها. ""كانَ في تَقْدِيرِي أَنَّكَ عَرَفْتَ أُصُولِي"". (التوحيدي). 2.""تَقْديرُ ثَمَنِ البِضاعَةِ"" : تَخْمينُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22793, 'قَدَرٌ', 'قدر', 'مصدر', 'قدر', 'قدر', 'قدر', 'مص. قَدِرَ', '', '', 'مفرد', 'DnN', '', '', '"أَقْدَارٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. قَدِرَ). 1.""هُوَ قَدَرٌ لاَ مَفَرَّ مِنْهُ"" : مَا يُقَدِّرُهُ اللَّهُ عَلَى عِبَادِهِ مِنَ القَضَاءِ. ""هَذَا قَدَرُهُ"" ""شَاءتِ الأَقْدَارُ ذَلِكَ"" ""القَضَاءُ وَالقَد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22794, 'أَقْدَارٌ', 'أقدار', 'مصدر', '', 'ءقدار', 'قدر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
