INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22796, 'قُدْرَةٌ', 'قدرة', 'مصدر', 'قدر', 'قدرة', 'قدرة', 'مص. قَدَرَ، قَدِرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. قَدَرَ، قَدِرَ). 1.""لَهُ قُدْرَةٌ عَلَى الصَّبْرِ"" : لَهُ قُوَّةُ التَّمَكُّنِ عَلَى تَحَم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22797, 'قَدْرٌ', 'قدر', 'مصدر', 'قدر', 'قدر', 'قدر', 'مص. قَدَرَ، قَدِرَ', '', '', 'مفرد', 'DnN', '', '', '"أَقْدَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَدَرَ، قَدِرَ). 1.""رَجُلٌ عَظِيمُ القَدْرِ"" : عَلَى جَانِبٍ مِنَ الْحُرْمَةِ وَالوَقَارِ. ""هُوَ ذُو قَدْرٍ"". 2.""لَهُ قَدْرٌ عَظِيمٌ"" : شَأْنٌ عَظِيمٌ. ""حَطَّ مِنْ قَدْرِهِ"" : مِنْ شَأْنِهِ. 3.""سَأُنْجِزُ عَمَلِي عَلَى قَدْرِ الْمُسْتَطَاعِ"" : حَسَبَ الإِمْكَانِ. ""بِقَدْرِ الْمُسْتَطَاعِ"" ""اِعْرِفْ قَدْرَكَ تَسْلَمْ"" ""عَلَى قَدْرِ أَهْل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22798, 'أَقْدَارٌ', 'أقدار', 'مصدر', '', 'ءقدار', 'قدر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22799, 'قَدَاسَةٌ', 'قداسة', 'مصدر', 'قدس', 'قداسة', 'قدسة', 'مص. قَدُسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَدَاسَةٌ-قَدَاسَةٌ [ق د س] (مص. قَدُسَ). 1.""قَدَاسَةُ الْمَكَانِ"": طَهَارَتُهُ وَجَلاَلُهُ. 2.""قَدَاسَةُ الْبَابَا"" : لَقَبُ الْحَبْرِ الأَعْظَمِ، وَهُوَ رَأْسُ الْكَنِيسَةِ الْكَاثُولِيكِيَّةِ. ""صَاحِبُ الْقَدَاسَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22800, 'تَقْدِمَةٌ', 'تقدمة', 'مصدر', 'قدم', 'تقدمة', 'تقدمة', 'مص. قَدَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْدِمَةٌ-تَقْدِمَةٌ [ق د م] (مص. قَدَّمَ). 1.""تَقْدِمَةُ الْمُحاضِرِ"" : التَّعْريفُ بِهِ و"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22801, 'تَقْديمٌ', 'تقديم', 'مصدر', 'قدم', 'تقديم', 'تقدم', 'مص. قَدَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْديمٌ-تَقْديمٌ [ق د م] (مص. قَدَّمَ). 1.""تَقْديمُ الضُّيوفِ"" : التَّعْريفُ بِهِمْ. ""تَقْديمُ الْمُمَثِّلِينَ"". 2.""التَّقْديمُ في البَلاغَةِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22802, 'قِدَمٌ', 'قدم', 'مصدر', 'قدم', 'قدم', 'قدم', 'مص. قَدُمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قِدَمٌ-قِدَمٌ [ق د م] (مص. قَدُمَ). 1.""مُنْذُ القِدَمِ"" : مُنْذُ زَمَنٍ بَعِيدٍ جِدّاً. 2.""لَهُ قِدَمٌ فِي هَذَا العَمَلِ"" : سَابِقَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22803, 'قُدُومٌ', 'قدوم', 'مصدر', 'قدم', 'قدوم', 'قدم', 'مص. قَدِمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قُدُومٌ-قُدُومٌ [ق د م] (مص. قَدِمَ). 1.""قُدُومُ البِلاَدِ"" : إِتْيَانُهَا، الْمَجِيءُ إِلَيْهَا، الرُّجُوعُ، العَوْدَةُ. ""يَنْتَظِرُ قُدُومَهُ"" ""شَرِّفْنَا بِقُدُومِكَ"". 2.""القُدُومُ عَلَى خَوْضِ الْمَعَارِكِ"" : الشَّجَاعَةُ، الإِقْدَامُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22804, 'مَقْدَمٌ', 'مقدم', 'مصدر', 'قدم', 'مقدم', 'مقدم', 'مص. قَدِمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَقْدَمٌ-مَقْدَمٌ [ق د م] (مص. قَدِمَ). 1. ""مَقْدَمُهُ مُبَارَكٌ"" : مَجِيئُهُ. 2. ""مَقْدَمُ الْحَاجِّ"" : وَقْتُ قُدُومِ، وُصُولِ الْحَاجِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22805, 'تَقْذيرٌ', 'تقذير', 'مصدر', 'قذر', 'تقذير', 'تقذر', 'مص. قَذَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْذيرٌ-تَقْذيرٌ [ق ذ ر] (مص. قَذَّرَ). 1.""تَقْذِيرُ مَكانٍ"" : تَصْيِيرُهُ قَذِراً، وَسِخاً. 2.""تَقْذيرُ الرَّجُلِ"" : جَعْلُهُ قَذِراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22806, 'قَذَارَةٌ', 'قذارة', 'مصدر', 'قذر', 'قذارة', 'قذرة', 'مص. قَذُرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَذَارَةٌ-قَذَارَةٌ [ق ذ ر] (مص. قَذُرَ). ""قَذَارَةُ الْمَكَانِ"" : وَسَاخَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22807, 'قَذَرٌ', 'قذر', 'مصدر', 'قذر', 'قذر', 'قذر', 'مص. قَذِرَ', '', '', 'مفرد', 'DnN', '', '', '"أَقْذَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَذِرَ). ""رَاكَمُوا القَذَرَ أَمَامَ البَيْتِ"" : الغَائِطَ، الوَسَخَ. ""أَقْذَارُ الْمَزَابِلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22808, 'أَقْذَارٌ', 'أقذار', 'مصدر', '', 'ءقذار', 'قذر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22809, 'قَذْفٌ', 'قذف', 'مصدر', 'قذف', 'قذف', 'قذف', 'مص. قَذَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَذَفٌ-قَذَفٌ [ق ذ ف]. 1.""قَذَفُ الشَّيْءِ"" : جَانِبُهُ، نَاحِيَتُهُ. 2.""مَكَانٌ قَذَفٌ"" : بَع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22810, 'قَذىً', 'قذى', 'مصدر', 'قذي', 'قذى', 'قذ', 'مص. قَذِيَ', '', '', 'مفرد', 'Dy', '', '', '"قُذِيٌّ:أَقْذَاءٌ"', '', 'Rw', '', '', '', '', '', '', '"(مص. قَذِيَ). 1.""قَذَى العَيْنِ"" : مَا يَقَعُ فِي العَيْنِ مِنْ وَسَخٍ أَبْيَضَ يَتَجَمَّعُ فِي مُؤْقِ العَيْنِ. 2.""غَمَضَ جُفُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22811, 'قُذِيٌّ', 'قذي', 'مصدر', '', 'قذي', 'قذ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22812, 'أَقْذَاءٌ', 'أقذاء', 'مصدر', '', 'ءقذاء', 'قذ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22813, 'قَرَارٌ', 'قرار', 'مصدر', 'قرر', 'قرار', 'قرر', 'مص. قَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَرَارٌ-قَرَارٌ [ق ر ر] (مص. قَرَّ). 1.""جَعَلَ مِنَ الكَهْفِ قَرَاراً"" : مُسْتَقَرّاً.غافر آية 64 اللَّهُ الَّذِي جَعَلَ لَكُمُ الأَرْضَ قَرَاراً وَالسَّمَاءَ بِنَاءً( قرآن). 2.""أَعْلَنَتْ لَجْنَةُ التَّحْكِيمِ عَنْ قَرَارِهَا النِّهَائِيِّ"" : عَمَّا اسْتَقَرَّتْ عَلَيْهِ مِنْ رَأْيٍ. ""نَزَلَ قَرَارُ الْمَحْكَمَةِ كَالصَّاعِقَةِ"". 3"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22814, 'قُرَّةٌ', 'قرة', 'مصدر', 'قرر', 'قرة', 'قرة', 'مص. قَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قُرَّةٌ-قُرَّةٌ [ق ر ر] (مص. قَرَّ). ""قُرَّةُ العَيْنِ"" : مَا يُسَرُّ بِهِ الإِنْسَانُ وَيَرْتَاحُ لَهُ. ""هُوَ قُرَّةُ عَي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22815, 'قَرٌّ', 'قر', 'مصدر', 'قرر', 'قر', 'قر', 'مص. قَرَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَرٌّ-قَرٌّ [ق ر ر] (مص. قَرَّ). ""يَوْمٌ قَرٌّ"" : يَوْمٌ بَارِدٌ. ""لَيْلَةٌ قَرٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22816, 'قُرورَةٌ', 'قرورة', 'مصدر', 'قرر', 'قرورة', 'قررة', 'مص. قَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قُرورَةٌ-قُرورَةٌ [ق ر ر] (مص. قَرَّ). : ما يُصَبُّ وَيضافُ من ماء"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22817, 'قِرَاءةٌ', 'قراءة', 'مصدر', 'قرأ', 'قراءة', 'قرة', 'مص. قَرَأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"(مص. قَرَأَ). 1.""قِرَاءةُ الكُتُبِ"" : تِلاَوَتُهَا. 2.""قِرَاءةٌ جَهْرِيَّةٌ"" : نُطْقٌ بِمَا هُوَ مَكْتُوبٌ عَكْسُ : ""قِرَاءةٌ صَامِتَةٌ"". 3.""القِرَاءاتُ السَّبْعُ"" : أَوْجُهُ قِرَاءةِ القُرْآنِ الكَرِيمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22818, 'قُرْآنٌ', 'قرآن', 'مصدر', 'قرأ', 'قرءءن', 'قرآن', 'مص. قَرَأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"قُرْآنٌ-قُرْآنٌ [ق ر أ] (مص. قَرَأَ). يوسف آية 2إِنَّا أَنْزَلْنَاهُ قُرْآناً عَرَبِيّاً لَعَلَّكُمْ تَعْقِلُونَ . قرآن) : الكِتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22819, 'قَرَدٌ', 'قرد', 'مصدر', 'قرد', 'قرد', 'قرد', 'مص. قَرِدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَرَدٌ-قَرَدٌ [ق ر د] (مص. قَرِدَ). ""قَرَدُ الوَبَرِ أَوِ الصُّوفِ"" : مَا تَسَاقَطَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22820, 'تَقْريبٌ', 'تقريب', 'مصدر', 'قرب', 'تقريب', 'تقرب', 'مص. قَرَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْريبٌ-تَقْريبٌ [ق ر ب] (مص. قَرَّبَ). 1.""حاوَلَ تَقْريبَ آرائِهِمَا"" : التَّوْفيقَ بَيْنَها، أَيْ أَنْ يَجْعَلَها مُتَقارِبَةً. 2.""ثَمَنُ القَميصِ خَمْسونَ د"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22821, 'قُرْبٌ', 'قرب', 'مصدر', 'قرب', 'قرب', 'قرب', 'مص. قَرَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُرْبٌ-قُرْبٌ [ق ر ب] (مص. قَرَبَ). 1.""جَلَسَ بِالقُرْبِ مِنْهُ"" : بِجَانِبِهِ. 2.""قُرْبُ أَجَلِهِ"" : دُنُوُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22822, 'قَرَابَةٌ', 'قرابة', 'مصدر', 'قرب', 'قرابة', 'قربة', 'مص. قَرُبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَرَابَةٌ-قَرَابَةٌ [ق ر ب] (مص. قَرُبَ). ""بَيْنَهُمَا قَرَابَةٌ عَائِلِيَّةٌ"" : عَلاَقَةٌ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22823, 'قُرْبَى', 'قربى', 'مصدر', 'قرب', 'قربى', 'قرب', 'مص. قَرُبَ', '', '', 'مفرد', 'Dy', '', 'Pf', '""', 'ممنوع من الصرف', 'R0', '', '', '', '', '', '', '"قُرْبَى-قُرْبَى [ق ر ب] (مص. قَرُبَ). ""مِنْ ذَوِي القُرْبَى"" : مِنْ أَهْلِهِ الأَقْرَبِينَ. ""وَظُلْمُ ذَوِي القُرْبَى أَشَدُّ مَضَاضَةً"". (طرفة بن العبد)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22824, 'قُرْبَانٌ', 'قربان', 'مصدر', 'قرب', 'قربان', 'قربن', 'مص. قَرِبَ', '', '', 'مفرد', 'DnN', '', '', '"قَرَابِينُ"', '', 'R', '', '', '', '', '', '', '"(مص. قَرِبَ) 1.""قَرَّبَ القُرْبَانَ لِلَّهِ"" : كُلُّ مَا يُتَقَرَّبُ بِهِ إِلَى الَّلهِ مِنْ ذَبِيحَةٍ أَوْ غَيْرِهَا.المائدة آية 27 وَاتْلُ عَلَيْهِمْ نَبَأَ ابْنَيْ آدَم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22825, 'قَرَابِينُ', 'قرابين', 'مصدر', '', 'قرابين', 'قربن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22826, 'قَرَحٌ', 'قرح', 'مصدر', 'قرح', 'قرح', 'قرح', 'مص. قَرَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَرِحٌ-قَرِحٌ [ق ر ح] (صِيغَةُ فَعِل). ""ما يَزَالُ الْمَرِيضُ قَرِحاً"": بِهِ قُرُوحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22827, 'قَرْحٌ', 'قرح', 'مصدر', 'قرح', 'قرح', 'قرح', 'مص. قَرَحَ', '', '', 'مفرد', 'DnN', '', '', '"قُرُوحٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَرَحَ). 1.""اِشْتَدَّ قَرْحُهُ"" : جُرْحُ سِكِّينٍ أَوْ نَحْوِهِ. 2.""أُصِيبَ بِقَرْحٍ"" : بِجُرْحٍ . 3.""اِنْتَشَرَ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22828, 'قُرُوحٌ', 'قروح', 'مصدر', '', 'قروح', 'قرح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
