INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22830, 'تَقْريرٌ', 'تقرير', 'مصدر', 'قرر', 'تقرير', 'تقرر', 'مص. قَرَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْريرٌ-تَقْريرٌ [ق ر ر] (مص. قَرَّرَ). 1.""كَتَبَ تَقْريراً عَنْ سَيْرِ الدِّراسَةِ بِالفَصْلِ"" : بَياناً وَعَرْضاً يَتَضَمَّنُ ما شاهَدَهُ. 2.""التَّقْريرُ الأدَبِيُّ"" : بَيانٌ يَتَضَمَّنُ نَشاطَ جَمْعِيَّةٍ أَوْ حِزْبٍ خِلالَ فَتْرَةٍ مُعَيَّنَةٍ. 3.""التَّقْريرُ الس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22831, 'تقارير', 'تقارير', 'مصدر', '', 'تقارير', 'تقرر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22832, 'قَرِيرٌ', 'قرير', 'مصدر', 'قرر', 'قرير', 'قرر', 'مص. قَرَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَرِيرٌ-قَرِيرٌ [ق ر ر] (مص. قَرَّرَ). 1.""قَرِيرُ العَيْنِ"" : مَنْ سُرَّ بِمَا رَأَى"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22833, 'قَرْسٌ', 'قرس', 'مصدر', 'قرس', 'قرس', 'قرس', 'مص. قَرَسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَرْسٌ-قَرْسٌ [ق ر س] (مص. قَرَسَ). ""اِشْتَدَّ القَرْسُ"" : البَرْدُ الشَّدِيدُ. ""لَيْلَةٌ ذَاتُ قَرْسٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22834, 'تَقْريصٌ', 'تقريص', 'مصدر', 'قرص', 'تقريص', 'تقرص', 'مص. قَرَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْريصٌ-تَقْريصٌ [ق ر ص] (مص. قَرَّصَ). ""تَقْريصُ العَجينِ"": قَطْعُهُ قِطْعَةً قِطْعَةً لِبَسْطِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22835, 'تَقْريضٌ', 'تقريض', 'مصدر', 'قرض', 'تقريض', 'تقرض', 'مص. قَرَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْريضٌ-تَقْريضٌ [ق ر ض] (مص. قَرَّضَ). ""تَقْريضُ الثَّوْبِ"": قَطْعُهُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22836, 'قَرْضٌ', 'قرض', 'مصدر', 'قرض', 'قرض', 'قرض', 'مص. قَرَضَ', '', '', 'مفرد', 'DnN', '', '', '"قُرُوضٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَرَضَ). ""قَدَّمَ لَهُ قَرْضاً لِأَجَلٍ مَعْلُومٍ"" : مَا يُس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22837, 'قُرُوضٌ', 'قروض', 'مصدر', '', 'قروض', 'قرض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22838, 'تَقْريظٌ', 'تقريظ', 'مصدر', 'قرظ', 'تقريظ', 'تقرظ', 'مص. قَرَّظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْريظٌ-تَقْريظٌ [ق ر ظ] (مص. قَرَّظَ). 1.""تَقْريظُ أَميرٍ"" : مَدْحُهُ. 2.""تَقْريظُ كِتابٍ"" : وَصْفُ مَحاسِنِهِ وَمَزاياهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22839, 'قَزْمٌ', 'قزم', 'مصدر', 'قزم', 'قزم', 'قزم', 'مص. قَزَمَ', '', '', 'مفرد', 'DnN', '', '', '"أَقْزَامٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَزَمَ). ""هُوَ قَزْمٌ"" : ذُو لُؤْمٍ ودَنَاءةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22840, 'قَرَفٌ', 'قرف', 'مصدر', 'قرف', 'قرف', 'قرف', 'مص. قَرِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَرَفٌ-قَرَفٌ [ق ر ف] (مص. قَرِفَ). 1.""شَعَرَ بِالقَرَفِ مِنْ سُوءِ تَصَرُّفِهِ الْمُشِينِ"" : شَعَرَ بِالتَّقَزُّزِ. 2.""أَخْشَى عَلَيْكَ القَرَفَ"" : الإِصَابَة بالْمَرَضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22841, 'قَرْقَرَةٌ', 'قرقرة', 'مصدر', 'قرقر', 'قرقرة', 'قرقرة', 'مص. قَرْقَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَرْقَرَةٌ-قَرْقَرَةٌ [ق ر ق ر] (مص. قَرْقَرَ). 1.""قَرْقَرَةُ الْمَاءِ"" : خَرِيرُهُ. 2.""قَرْقَرَةُ الْحَمَامِ"" : هَدِيرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22842, 'قِرَانٌ', 'قران', 'مصدر', 'قرن', 'قران', 'قرن', 'مص. قَرَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قِرَانٌ-قِرَانٌ [ق ر ن] (مص. قَرَنَ). 1.""عَقَدَ قِرَانَهُ مَعَ ابْنَةِ عَمِّهِ"" : عَقَدَ زَوَاجَهُ. ""عَقْدُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22843, 'قَرْنٌ', 'قرن', 'مصدر', 'قرن', 'قرن', 'قرن', 'مص. قَرَنَ', '', '', 'مفرد', 'DnN', '', '', '"قُرُونٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَرَنَ). 1.""قَرْنُ القَوْلِ بِالعَمَلِ"" : جَمْعُهُمَا، وَصْلُهُمَا. 2.""قَرْنُ الْحَيَوَانِ"" : عَظْمٌ يَنْبُتُ فِي رُؤُوسِ بَعْضِ الْحَيَوَانَاتِ كَالكَبْشِ وَالغَزَالِ وَالأَيِّلِ. 3.""قَرْنُ الإِنْسَانِ"" : الْجَانِبُ الأَعْلَى مِنْ رَأْسِهِ. 4.""قَرْنُ القَوْمِ"": سَيِّدُهُمْ. 5.""قَرْنُ الْجَبَلِ"" : رَأْسُهُ. 6.""قَرْنُ الشَّعْرِ"" : خُصْلَةٌ فِي مُقَدَّمِ رَأْسِ الْمَرْأَةِ. 7.""قَرْنُ الشَّمْسِ"" : أَوَّلُ مَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22844, 'قُرُونٌ', 'قرون', 'مصدر', '', 'قرون', 'قرن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22845, 'قِرىً', 'قرى', 'مصدر', 'قري', 'قرى', 'قر', 'مص. قَرَى', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"قِرىً-قِرىً [ق ر ي] (مص. قَرَى). 1. : مَا يُقَدَّمُ لِلضَّيْفِ. 2. : مَاءٌ مَجْمُوعٌ فِي حَوْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22846, 'قَزٌّ', 'قز', 'مصدر', 'قزز', 'قز', 'قز', 'مص. قَزَّ ', '', '', 'مفرد', 'DnN', '', '', '"قُزُوزٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَزَّ ). 1.""لَبِسَتْ قَمِيصاً مِنَ الْقَزِّ"" : مِنَ الْحَرِيرِ. 2.""دُودُ الْقَزِّ"" : دُودُ الْحَرِيرِ، يَرْمِي بِالْخُيُوطِ الْحَرِيرِيَّةِ مِنْ فَمِهِ وَيَنْسُجُهَا شَرَانِقَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22847, 'قُزُوزٌ', 'قزوز', 'مصدر', '', 'قزوز', 'قزز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22848, 'قَزَازَةٌ', 'قزازة', 'مصدر', 'قزز', 'قزازة', 'قززة', 'مص. قَزَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَزَازَةٌ-قَزَازَةٌ [ق ز ز] (مص. قَزَّ). ""وَجَدَ فِي ذَلِكَ قَزَازَةً"" : عَيْفاً،كُرْهاً، اِشْمِئْزَازاً. ""ما في طَعَامِهِ قَزَازَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22849, 'تَقْسِيمٌ', 'تقسيم', 'مصدر', 'قسم', 'تقسيم', 'تقسم', 'مص. قَسَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَقاسيمُ"', '', 'R', '', '', '', '', '', '', '"(مص. قَسَّمَ). 1.""أَشْرَفَ القاضِي على تَقْسِيمِ التَّرِكَةِ"" : على تَوْزيعِها. ""لَمْ يَكُنْ تَقْسيمُ العَمَلِ بَيْنَهُمْ عادِلاً"". 2.""تَقْسيمُ البِلادِ إلى أَقالِيمَ"" : تَجْزيئُها. 3.""عَزَفَ الْمُوسيقارُ تَقاسيمَ على العودِ"" : عَزَفَ لَحْناً مُنْفَرِداً على نَمَطٍ موسيقِيٍّ مُعَيَّنٍ دونَ مُشارَكَةِ أَيِّ آلَةِ طَرَبٍ أُخْرَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22850, 'أَقْزَامٌ', 'أقزام', 'مصدر', '', 'ءقزام', 'قزم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22851, 'قَزَمٌ', 'قزم', 'مصدر', 'قزم', 'قزم', 'قزم', 'مص. قَزَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَقْزَامٌ:قُزُمٌ:قَزَامَى"', '', 'R', '', '', '', '', '', '', '"(مص. قَزَمَ). 1.""رَجُلٌ قَزَمٌ"" : إِنْسَانٌ قَصِيُر القَامَةِ، مَنْ تَوَقَّفَ نُمُوُّ جِسْمِهِ وَهُوَ طِفْلٌ. يُقَالُ أَيْضاً : رَجُلٌ قَزَمَةٌ وَامْرَأَةٌ قَزَمَةٌ. 2.""رَجُلٌ قَزَمٌ"": دَنِيءٌ، لَئِيمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22852, 'قَزَمَةٌ', 'قزمة', 'مصدر', 'قزم', 'قزمة', 'قزمة', 'مص. قَزَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَقْزَامٌ:قُزُمٌ:قَزَامَى"', '', 'R', '', '', '', '', '', '', '"(مص. قَزَمَ). 1.""رَجُلٌ قَزَمٌ"" : إِنْسَانٌ قَصِيُر القَامَةِ، مَنْ تَوَقَّفَ نُمُوُّ جِسْمِهِ وَهُوَ طِفْلٌ. يُقَالُ أَيْضاً : رَجُلٌ قَزَمَةٌ وَامْرَأَةٌ قَزَمَةٌ. 2.""رَجُلٌ قَزَمٌ"": دَنِيءٌ، لَئِيمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22853, 'أَقْزَامٌ', 'أقزام', 'مصدر', '', 'ءقزام', 'قزم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22854, 'قُزُمٌ', 'قزم', 'مصدر', '', 'قزم', 'قزم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22855, 'قَزَامَى', 'قزامى', 'مصدر', '', 'قزامى', 'قزم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22856, 'قَسْوَةٌ', 'قسوة', 'مصدر', 'قسو', 'قسوة', 'قسة', 'مص. قَسَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَسْوَةٌ-قَسْوَةٌ [ق س و] (مص. قَسَا). 1.""أَظْهَرَ قَسْوَةً"" : غِلْظَةً، شِدَّةً. 2.""قَسْوَةُ الْقَلْبِ"" : شِدَّتُهُ، صَلاَبَتُهُ. ""تَذَكَّرْ قَسْوَةَ الْحَيَاةِ"" ""قَسْوَةُ الْعَيْشِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22857, 'قَسْرٌ', 'قسر', 'مصدر', 'قسر', 'قسر', 'قسر', 'مص. قَسَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَسْرٌ-قَسْرٌ [ق س ر] (مص. قَسَرَ). ""عَامَلَهُ بِالْقَسْرِ"" : بِالإِكْرَاهِ، بِالْقَهْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22858, 'تَقْسيطٌ', 'تقسيط', 'مصدر', 'قسط', 'تقسيط', 'تقسط', 'مص. قَسَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْسيطٌ-تَقْسيطٌ [ق س ط] (مص. قَسَّطَ). 1.""يَبيعُ التَّاجِرُ بِالتًّقْسِيطِ"" : بِالْمُفَرَّقِ عَكْسَ بِالجُمْلَةِ. 2.""أَدَّى دُيونَهُ بِالتَّقْسيطِ"": أيْ أَدَّاها أَجْزاءً مَعْلومَةً في أَوْقاتٍ مُعَيَّنَةٍ، في آخِرِ كُلِّ شَهْرٍ مَثَلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22859, 'قَصَصٌ', 'قصص', 'مصدر', 'قصص', 'قصص', 'قص', 'مص. قَصَّ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"قَصَصٌ-قَصَصٌ [ق ص ص] (مص. قَصَّ). 1."" قَصَصُ الصَّدْرِ"" : قَصُّهُ، عَظْمُهُ. 2.""قَصَصُ الصُّوفِ"" : مَا قُصَّ مِنْهُ. 3.""يَرْوِي الْقَصَصَ"": رِوَايَةَ الْخَبَرِ، الأَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22860, 'تَقاسيمُ', 'تقاسيم', 'مصدر', '', 'تقاسيم', 'تقسم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22861, 'قَسْمٌ', 'قسم', 'مصدر', 'قسم', 'قسم', 'قسم', 'مص. قَسَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَسْمٌ-قَسْمٌ [ق س م] (مص. قَسَمَ). 1.""هَذَا قَسْمُهُ"" : قَدْرُهُ. 2.""أَجْزَلَ لَهُ القَسْمَ"" : العَطَاءَ. 3.""هُوَ جَيِّدُ القَسْمِ"" : جَيِّدُ الرَّأْيِ، كَما تَعْنِي كَلِمَةُ القَسْمِ: الشَّكَّ، الْمَاءَ، الغَيْثَ، الخُلُقَ، العَادَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22862, 'قَشٌّ', 'قش', 'مصدر', 'قشش', 'قش', 'قش', 'مص. قَشَّ', '', '', 'مفرد', 'DnN', '', '', '"قُشُوشٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَشَّ). 1.""تَكَدَّسَ قَشٌّ كَثِيرٌ فِي البَيْدَرِ"" : مَا صَغُرَ مِنَ النَّبَاتِ اليَابِسِ. 2.""قَشُّ كُرْسِيٍّ"" : عِيدانٌ دِقَاقٌ مِنَ القَصَبِ أَوِ الْخَيْزُرَانِ تُقَشَّشُ بِهَا الكَرَاسِيُّ. 3.""جَمَعَتِ القَشَّ"" : كُلُّ مَا يُكْنَسُ مِنَ الْمَنَازِلِ أَوْ غَيْرِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22863, 'قُشُوشٌ', 'قشوش', 'مصدر', '', 'قشوش', 'قشش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22864, 'تَقْشيبٌ', 'تقشيب', 'مصدر', 'قشب', 'تقشيب', 'تقشب', 'مص. قَشَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْشيبٌ-تَقْشيبٌ [ق ش ب] (مص. قَشَّبَ). 1.""تَقْشيبُ الطَّعامِ"" : خَلْطُهُ بِالسُّمِّ. 2.""تَقْشيبُ الرَّجُلِ بِالسُّوءِ"" : تَلْطيخُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22865, 'تَقْشيرٌ', 'تقشير', 'مصدر', 'قشر', 'تقشير', 'تقشر', 'مص. قَشَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْشيرٌ-تَقْشيرٌ [ق ش ر] (مص. قَشَّرَ). ""تَقشِيرُ الخُضَرِ"" : نَزْعُ القِشْرَةِ عَنْها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22866, 'تَقْشيفٌ', 'تقشيف', 'مصدر', 'قشف', 'تقشيف', 'تقشف', 'مص. قَشَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْشيفٌ-تَقْشيفٌ [ق ش ف] (مص. قَشَّفَ). ""تَقْشيفُ عَيْشِ الرَّجُلِ"" : تَضْيِيقُهُ، جَعْلُهُ في عَيْشٍ بائِسٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22867, 'قَشَفٌ', 'قشف', 'مصدر', 'قشف', 'قشف', 'قشف', 'مص. قَشِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَشَفٌ-قَشَفٌ [ق ش ف] (مص. قَشِفَ). 1.""قَشَفُ الْعَيْشِ"": سُوؤُهُ، ضِيقُهُ، قَشَافَتُهُ. 2.""وَجَدَهُ فِي قَشَفٍ"" : فِي حَالَةٍ رَثَّةٍ، سَيِّئَةٍ. 3.""قَشَفُ الْجِسْمِ"" : اِتِّسَاخُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22868, 'قَشْقَشَةٌ', 'قشقشة', 'مصدر', 'قشقش', 'قشقشة', 'قشقشة', 'مص. قَشْقَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَشْقَشَةٌ-قَشْقَشَةٌ [ق ش ق ش] (مص. قَشْقَشَ).""قَشْقَشَةُ اللَّحْمِ فِي القِدْرِ"" : مَا يُحْدِثُهُ اللَّحْمُ مِنْ صَوْتٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22869, 'قَصْفٌ', 'قصف', 'مصدر', 'قصف', 'قصف', 'قصف', 'مص. قَصَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَصْفٌ-قَصْفٌ [ق ص ف] (مص. قَصَفَ). ""تَعَرَّضَتِ الْمَدِينَةُ لِقَصْفٍ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22870, 'تَقْصيبٌ', 'تقصيب', 'مصدر', 'قصب', 'تقصيب', 'تقصب', 'مص. قَصَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْصيبٌ-تَقْصيبٌ [ق ص ب] (مص. قَصَّبَ). 1.""تَقْصيبُ الزَّرْعِ"" : صَيْرُ قَصَبٍ لَهُ. 2.""تَقْصيبُ الشَّعْرِ"" : تَجَعُّدُهُ. 3.""تَقْصيبُ الحَجَرِ"" : نَحْتُهُ، تَسْوِيَتُهُ. 4.""تَقْصيبُ الثَّوْبِ"" : نَسْجُهُ بِخُيوطِ الذَّهَبِ أَوِ الفِضَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22871, 'قَصْبٌ', 'قصب', 'مصدر', 'قصب', 'قصب', 'قصب', 'مص. قَصَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَصْبٌ-قَصْبٌ [ق ص ب] (مص. قَصَبَ). 1.""قَصْبُ اللَّحْمِ"": قَطْعُهُ. 2.""قَصْبُ الشَّاةِ"" : تَفْصِيلُ قَصَبِهَا وَقَطْعُهُ عُضْواً عُضْواً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22872, 'قَصْدٌ', 'قصد', 'مصدر', 'قصد', 'قصد', 'قصد', 'مص. قَصَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَصْدٌ-قَصْدٌ [ق ص د] (مص. قَصَدَ). 1.""طَرِيقٌ قَصْدٌ"" : مُسْتَقِيمٌ. 2.""هُوَ عَلَى قَصْدٍ"" : عَلَى رُشْدٍ. 3.""أَوْضَحَ لَهُ القَصْدَ الْمُبِينَ"" : أَي بَيَانُ الطَّرِيقِ الْمُسْتَقِيمِ الْمُوصِلِ إِلَى ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22873, 'تَقْصيرٌ', 'تقصير', 'مصدر', 'قصر', 'تقصير', 'تقصر', 'مص. قَصَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْصيرٌ-تَقْصيرٌ [ق ص ر] (مص. قَصَّرَ). ""لاَحَظَ تَقْصيراً في العَمَلِ"" : تَهاوُناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22874, 'قُصُورٌ', 'قصور', 'مصدر', 'قصر', 'قصور', 'قصر', 'مص. قَصَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قُصُورٌ-قُصُورٌ [ق ص ر] (مص. قَصَرَ). 1.""لاَحَظَ قُصُوراً فِي عَمَلِهِ"" : تَهَاوُناً، تَرَاخِياً، تَقْصِيراً. 2.""قُصُورٌ عَقْلِيٌّ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22875, 'قِصَرٌ', 'قصر', 'مصدر', 'قصر', 'قصر', 'قصر', 'مص. قَصُرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قِصَرٌ-قِصَرٌ [ق ص ر] (مص. قَصُرَ). 1.""لَمْ يَتَمَكَّنْ مِنْ إِنْجَازِ عَمَلِهِ كَامِلاً بِسَبَبِ قِصَرِ الْوَقْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22876, 'قَصْرٌ', 'قصر', 'مصدر', 'قصر', 'قصر', 'قصر', 'مص. قَصُرَ، قَصَرَ', '', '', 'مفرد', 'DnN', '', '', '"قُصُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَصُرَ، قَصَرَ). 1.""قَصْرُ الْمَسَافَةِ"" : عَدَمُ امْتِدَادِهَا. 2.""قَصْرُكَ أَنْ تَفْعَلَ كَذَا"" : حَسْبُكَ، كِفَايَتُكَ، غ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22877, 'قُصُورٌ', 'قصور', 'مصدر', '', 'قصور', 'قصر', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22878, 'تَقْصِيصٌ', 'تقصيص', 'مصدر', 'قصص', 'تقصيص', 'تقصص', 'مص. قَصَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْصِيصٌ-تَقْصِيصٌ [ق ص ص] (مص. قَصَّصَ). ""تَقْصِيصُ الشَّعْرِ"" : قَطْعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22879, 'تَقْطِيبٌ', 'تقطيب', 'مصدر', 'قطب', 'تقطيب', 'تقطب', 'مص. قَطَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْطِيبٌ-تَقْطِيبٌ [ق ط ب] (مص. قَطَّبَ). 1.""تَقْطيبُ الوَجْهِ"" : ضَمُّ حاجِبَيْهِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22880, 'قَصِيفٌ', 'قصيف', 'مصدر', 'قصف', 'قصيف', 'قصف', 'مص. قَصَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَصِيفٌ-قَصِيفٌ [ق ص ف] (مص. قَصَفَ). ""قَصِيفُ الشَّجَرِ"": هَشِيمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22881, 'قَصَمٌ', 'قصم', 'مصدر', 'قصم', 'قصم', 'قصم', 'مص. قَصِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَصَمٌ-قَصَمٌ [ق ص م] (مص. قَصِمَ). 1.""قَصَمُ السِّن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22882, 'قَضَضٌ', 'قضض', 'مصدر', 'قضض', 'قضض', 'قض', 'مص. قَضَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَضَضٌ-قَضَضٌ [ق ض ض] (مص. قَضَّ). 1.""اِنْتَشَرَ القَضَضُ عَلَى الفِرَاشِ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22883, 'قَضٌّ', 'قض', 'مصدر', 'قضض', 'قض', 'قض', 'مص. قَضَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَضٌّ-قَضٌّ [ق ض ض] (مص. قَضَّ). 1.""مَكَانٌ قَضٌّ"" : وَقَعَ فِيهِ القَضَضُ، أَيْ صِغَارُ الْحَصَى. ""طَعَامٌ قَضٌّ"". 2.""جَاءَ س"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22884, 'تَقْضيبٌ', 'تقضيب', 'مصدر', 'قضب', 'تقضيب', 'تقضب', 'مص. قَضَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْضيبٌ-تَقْضيبٌ [ق ض ب] (مص. قَضَّبَ). 1.""تَقْضيبُ الغُصْنِ"" : قَطْعُهُ. 2.""تَقْضيبُ الكَرْمِ"" : تَقْطيعُ أَغْصانِهِ أَيَّامَ الرَّبيعِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22885, 'قَضْبٌ', 'قضب', 'مصدر', 'قضب', 'قضب', 'قضب', 'مص. قَضَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَضْبٌ-قَضْبٌ [ق ض ب] (مص. قَضَبَ). 1. : كُلُّ شَجَرَةٍ طَالَتْ وَامْتَدَّتْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22886, 'قَضْمٌ', 'قضم', 'مصدر', 'قضم', 'قضم', 'قضم', 'مص. قَضَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَضْمٌ-قَضْمٌ [ق ض م] (مص. قَضَمَ). ""قَضْمُ الْجَوْزِ"" : كَسْرُهُ بَيْنَ الأَسْنَانِ وَأَكْلُهُ. لَيْسَ فِي قَضْمِكَ الْحَدِيدَ هَوَانٌ*إِنَّ فِي بَثِّـكَ الشَّكَـاةَ هَوَانـاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22887, 'قَضَاءٌ', 'قضاء', 'مصدر', 'قضي', 'قضاء', 'قض', 'مص. قَضَى', '', '', 'مفرد', 'Dz', '', 'Pf', '":أَقْضِيَةٌ"', '', 'Rz', '', '', '', '', '', '', '"(مص. قَضَى). 1.""رَفَعَ أَمْرَهُ إِلَى الْقَضَاءِ"" : هَيْئَةُ الْقُضَاةِ فِي الْمَحَاكِمِ الَّتِي تَفْصِلُ فِي النِّزَاعِ الْمَرْفُوعِ إِلَيْهَا طِبْقاً لِلْقَانُونِ. ""رِجَالُ الْقَضَاءِ"". 2.""يَشْتَغِلُ فِي الْقَضَاءِ"" : عَمَلُ القَاضِي. 3.""حُمَّ الْقَضَاءُ وَالْقَدَرُ"" : مَا يُقَدِّرُهُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22888, 'أَقْضِيَةٌ', 'أقضية', 'مصدر', '', 'ءقضية', 'قضة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22889, 'قِطَافٌ', 'قطاف', 'مصدر', 'قطف', 'قطاف', 'قطف', 'مص. قَطَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قِطَافٌ-قِطَافٌ [ق ط ف] (مص. قَطَفَ). ""حَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22890, 'تَقْطيرٌ', 'تقطير', 'مصدر', 'قطر', 'تقطير', 'تقطر', 'مص. قَطَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْطيرٌ-تَقْطيرٌ [ق ط ر] (مص. قَطَّرَ). 1.""تَقِطيرُ الدَّواءِ"" : إنْزالُهُ قَطْرَةً قَطْرَةً. 2.""زارَ مَعْمَلَ تَقْطيرِ الوَرْدِ"" : تَصْفِيَتُهُ، تَحْوِيلُهُ إلى عِطْرٍ، أَيْ تَحْويلُ السَّائِلِ إلى بُخارٍ جُزْئِيٍّ ثُمَّ تَبْريدُهُ بِجِهازٍ لِهَذا الغَرَضِ لِيَعودَ إلى سائِلٍ مِنْ نَوْعٍ آخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22891, 'قَطْرٌ', 'قطر', 'مصدر', 'قطر', 'قطر', 'قطر', 'مص. قَطَرَ', '', '', 'مفرد', 'DnN', '', '', '"قِطَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. قَطَرَ). 1.""نَزَلَ الْقَطْرُ"" : الْمَطَرُ. 2.""هَذَا قَطْرٌ لاَ عَسَلٌ"" : سُكَّرٌ يُذَابُ بِالْمَاءِ الْمُغَلَّى وَيُتْرَكُ عَلَى النَّارِ حَتَّى يَنْعَقِدَ، يُشْبِهُ الْعَسَلَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22892, 'قِطَارٌ', 'قطار', 'مصدر', '', 'قطار', 'قطر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22893, 'قَطْرَبَةٌ', 'قطربة', 'مصدر', 'قطرب', 'قطربة', 'قطربة', 'مص. قَطْرَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قَطْرَبَةٌ-قَطْرَبَةٌ [ق ط رب] (مص. قَطْرَبَ). 1.""قَطْرَبَةُ السَّائِرِ"" : إِسْرَاعُهُ فِي مَشْيِهِ. 2.""قَطْرَبَةُ العَدُوِّ"" : صَرْعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22894, 'تَقْطيعٌ', 'تقطيع', 'مصدر', 'قطع', 'تقطيع', 'تقطع', 'مص. قَطَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَقاطِيعُ"', '', 'R', '', '', '', '', '', '', '"(مص. قَطَّعَ). 1.""اِنْهَمَكَ في تَقْطيعِ الخَشَبِ بِالفَأْسِ"" : تَجْزيئُهُ، شَقُّهُ. 2.""تَقْطيعُ الإِنْسانِ"" : قَدُّهُ، قامَتُهُ. 3.""تُعَبِّرُ تَقاطِيعُ وَجْهِهِ عَنِ الصَّرامَةِ"" : خُطوطُ وَجْهِهِ، مَلامِحُهُ، قَسَماتُهُ. 4.""تَقْطيعُ بَيْتِ الشِّعْرِ"" : تَحْلِيلُهُ إلى أَجْزائِهِ العَروضِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22895, 'تَقاطِيعُ', 'تقاطيع', 'مصدر', '', 'تقاطيع', 'تقطع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22896, 'قَطْعٌ', 'قطع', 'مصدر', 'قطع', 'قطع', 'قطع', 'مص. قَطَعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَطْعٌ-قَطْعٌ [ق ط ع] (مص. قَطَعَ). 1.""قَطْعُ اليَدِ"" : فَصْلُهَا مِنْ مَفْصِلِهَا. 2.""قَطْعُ أَغْصَانِ الشَّجَرَةِ"" : فَصْلُهَا. 3.""الأَمْرُ وَاقِعٌ قَطْعاً"" : أَيْ دُونَ شَكٍّ وَلاَ رَيْبٍ. 4.""سَأَعْفُو عَنْهُ بِقَطْعِ النَّظَرِ عَنْ سُلُوكِهِ الْمُشِينِ"" : دُونَ اعْتِبَارِ سُلُوكِهِ، بِغَضِّ النَّظَرِ. 5.""أَدَّى خِلاَفُهُمَا إِلَى قَطْعِ الْعَلاَقَاتِ"" : وَقْفِهَا. 6.""قَطْعُ الطُّرُقِ"" : إِقَامَةُ حَوَاجِزَ لِمَنْعِ الْمُرُورِ. 7.""القَطْعُ النَّادِرُ"" : النُّقُودُ. 8.""قَطْعُ التَّيَّارِ"" : تَوْقِيفُ إِيصَالِ التَّيَّارِ. 9.""الْقَطْعُ الْمُكاَفِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22897, 'مَقْطَعٌ', 'مقطع', 'مصدر', 'قطع', 'مقطع', 'مقطع', 'مص. قَطَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَقَاطِعُ"', '', 'R', '', '', '', '', '', '', '"(مص. قَطَعَ). 1.""مَقْطَعُ الْحِجَارَةِ"" : مَوْضِعُ قَطْعِهَا، مَحْجَرٌ. ن. مَقْلَعٌ. 2.""مَقْطَعٌ شِعْرِيٌّ"" : جُزْءٌ مِنْهُ. ""مَقْطَعٌ غِنَائِيٌّ"". 3. ""مَقْطَعُ الكَلِمَةِ"" : حَرْفٌ حَرَكَةٍ أَوْ حَرْفَانِ مَعَ ثَانِيهِمَا سَاكِنٌ. ""مَقْطَعٌ طَوِيلٌ"" ""مَقْطَعٌ قَصِيرٌ"". 4.""مَقْطَعُ ال"', '');
