INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22908, 'تَقْفيلٌ', 'تقفيل', 'مصدر', 'قفل', 'تقفيل', 'تقفل', 'مص. قَفَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْفيلٌ-تَقْفيلٌ [ق ف ل] (مص. قَفَّلَ). ""تَقْفيلُ الأبْوابِ"" : تَغْليقُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22909, 'تَقْفِيَةٌ', 'تقفية', 'مصدر', 'قفو', 'تقفية', 'تقفة', 'مص. قَفَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَقْفِيَةٌ-تَقْفِيَةٌ [ق ف و] (مص. قَفَّى). ""التَّقْفِيَةُ في الشِّعْر"', '');
