INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22911, 'قُلٌّ', 'قل', 'مصدر', 'قلل', 'قل', 'قل', 'مص. قَلَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قُلٌّ-قُلٌّ [ق ل ل] (مص. قَلَّ). 1.""طَعَامٌ قُلٌّ"" : قَلِيلٌ. 2.""رَجُلٌ قُلٌّ"" : قَصِيرُ الْجُثَّةِ. 3.""هُوَ رَجُلٌ قُلٌّ"" : فَرْدٌ لاَ أَحَدَ لَهُ. 4.""هُوَ قُلُّ بْنُ قُلٍّ"" : أَيْ لاَ يُعْرَفُ هُوَ وَلاَ أَبُوهُ."', '');
