INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22926, 'قَمْعٌ', 'قمع', 'مصدر', 'قمع', 'قمع', 'قمع', 'مص. قَمَعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَمْعٌ-قَمْعٌ [ق م ع] (مص. قَمَعَ).""تَعَرَّضَ لِلْقَمْعِ"" : لِلْقَهْرِ وَالتَّعْذِيبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22927, 'قَمَعٌ', 'قمع', 'مصدر', 'قمع', 'قمع', 'قمع', 'مص. قَمِعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَمَعٌ-قَمَعٌ [ق م ع] (مص. قَمِعَ). 1.""قَمَعُ الرِّئَةِ"" : مَجْرَى نَفَسِهَا. 2.""قَمَعُ الْحُلْقُومِ"" : طَرَفُ"', '');
