INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22931, 'قَنْطَرَةٌ', 'قنطرة', 'مصدر', 'قنطر', 'قنطرة', 'قنطرة', 'مص. قَنْطَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":قَنَاطِرُ"', '', 'R', '', '', '', '', '', '', '"(مص. قَنْطَرَ). ""قَنْطَرَةُ العُبُورِ"" : بِنَاءٌ مُقَوَّسٌ يُبْنَى فَوْقَ مَجْرَى الْمَاءِ لِيُعْبَرَ عَلَيْهِ، جِسْرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22932, 'قَنَاطِرُ', 'قناطر', 'مصدر', '', 'قناطر', 'قنطر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22933, 'قُنُوعٌ', 'قنوع', 'مصدر', 'قنع', 'قنوع', 'قنع', 'مص. قَنَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قُنُوعٌ-قُنُوعٌ [ق ن ع] (مص. قَنَعَ). 1.""رَجُلٌ قُنُوعٌ"" : ر"', '');
