INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22935, 'قُنْعَانٌ', 'قنعان', 'مصدر', 'قنع', 'قنعان', 'قنعن', 'مص. قَنِعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"قُنْعَانٌ-قُنْعَانٌ [ق ن ع] (مص. قَنِعَ). 1.""رَجُلٌ قُنْعَانٌ"" : يَرْضَى بِاليَسِيرِ. 2.""شَاهِدٌ قُنْعَانٌ"" : يُقْنَعُ بِهِ أَوبِشَهَادَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22936, 'قَهْرٌ', 'قهر', 'مصدر', 'قهر', 'قهر', 'قهر', 'مص. قَهَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"قَهْرٌ-قَهْرٌ [ق هـ ر] (مص. قَهَرَ). 1.""أَخَذَ أَعْدَاءهُ قَهْراً"" : عَسْفاً، مِنْ غَيْرِ رِضَاهُمْ. 2.""كُلُّ مَا فَعَلَهُ قَامَ بِهِ قَهْراً"" : بِغَيْرِ رِضاً، مُكْرَهاً، مُرْغَماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22937, 'تَقْويسٌ', 'تقويس', 'مصدر', 'قوس', 'تقويس', 'تقس', 'مص. قَوَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْويسٌ-تَقْويسٌ [ق و س] (مص. قَوَّسَ). 1.""تَقْويسُ الرَّجُلِ"": اِنْحِناءُ ظَهْرِهِ. 2.""تَقْويسُ البِناءِ"" : جَعْلُ أَقْواسٍ فيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22938, 'تَقْويضٌ', 'تقويض', 'مصدر', 'قوض', 'تقويض', 'تقض', 'مص. قَوَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْويضٌ-تَقْويضٌ [ق و ض] (مص. قَوَّضَ). 1.""تَقْويضُ البِناءِ"": هَدْمُهُ. 2.""تَقْويضُ الصُّفوفِ"" : تَفْريقُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22939, 'تَقْويلٌ', 'تقويل', 'مصدر', 'قول', 'تقويل', 'تقل', 'مص. قَوَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْويلٌ-تَقْويلٌ [ق و ل] (مص. قَوَّلَ). 1.""عَمِلَ على تَقْويلِهِ الشِّعْرَ"" : على تَحْفيظهِ وَتَعْلِيمِهِ إِيَّاهُ. 2.""عَمَدَ إلى تَقْويلِهِ ما لم يَقُلْهُ"" : جَعْلُهُ يَقولُ ما لَمْ يَقُلْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22940, 'تَقْويمٌ', 'تقويم', 'مصدر', 'قوم', 'تقويم', 'تقم', 'مص. قَوَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَقْويمٌ-تَقْويمٌ [ق و م] (مص. قَوَّمَ). 1.""حاوَلَ تَقْويمَ سُلوكِهِ"": تَعْديلَهُ. 2.""ساهَمَ في تَقْويمِ ثَمَنِ السِّلَعِ"" : تَقْديرُها وَتَحْديدُها. 3.""تَقويمُ البُلْدانِ"" : بَيانُ طولِها وَعَرْضِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22941, 'قُوَّةٌ', 'قوة', 'مصدر', 'قوي', 'قوة', 'قة', 'مص. قَوِيَ', '', '', 'مفرد', 'DnN', '', '', '"قُوَّاتٌ:قُوىً:قِوىً"', '', 'R', '', '', '', '', '', '', '"(مص. قَوِيَ). 1.""قُوَّةُ الإِنْسَانِ"" : طَاقَتُهُ، حَرَكَتُهُ الْمُتَنَامِيَةُ. ""لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ"" ""القُوَّةُ فِي الاتِّحَادِ"" ""قُوَّةُ الإِرَادَةِ"" ""قُوَّةٌ فِكْرِيَّةٌ"" ""قُوَّةُ الجِسْمِ"". 2.""أَلْعَابُ القُوَى"" : أَلْعَابٌ رِيَاضِيَّةٌ مِنْهَا العَدْوُ. 3.""القُوَّةُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22942, 'قُوَّاتٌ', 'قوات', 'مصدر', '', 'قوات', 'قت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
