INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22944, 'قِوىً', 'قوى', 'مصدر', '', 'قوى', 'ق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22945, 'قَوىً', 'قوى', 'مصدر', 'قوي', 'قوى', 'ق', 'مص. قَوِيَ', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"قَوىً-قَوىً [ق و ي] (مص. قَوِيَ). 1.""تَاهَ فِي القَوَى"" : فِي الْخَلاَءِ، القَفْرِ. 2.""بَاتَ القَوَى"" : بَاتَ عَلَى الطَّوَى، أَيْ جَائِعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22946, 'تَقْوِيَةٌ', 'تقوية', 'مصدر', 'قوي', 'تقوية', 'تقة', 'مص. قَوَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَقْوِيَةٌ-تَقْوِيَةٌ [ق و ي] (مص. قَوَّى). 1.""تَقْوِيَةُ جَسَدِ الوَلَدِ"": جَعْلُهُ قَوِيّاً، تَنْمِيَةُ قُدُراتِهِ الجَسَدِيَّةِ. 2.""تَقْوِيَةُ العَزيمَةِ"" : الشَّدُّ مِنْها وَرَفْعُ مَعْنَوِيَّاتِها. 3.""ساعَدَ على تَقْوِيَةِ مَرْكَزِهِ"" : على تَعْزِيزِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22947, 'تَقْيِئَةٌ', 'تقيئة', 'مصدر', 'قيأ', 'تقيءة', 'تقة', 'مص. قَيَّأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَقْيِئَةٌ-تَقْيِئَةٌ [ق ي أ] (مص. قَيَّأَ). ""نَاوَلَهُ دَوَاءً لِتَقْيِئَتِهِ"" : لِجَعْلِهِ يَقِيءُ مَا فِي مَعِدَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22948, 'مُكَابَدَةٌ', 'مكابدة', 'مصدر', 'كبد', 'مكابدة', 'مكبدة', 'مص.كَابَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُكَابَدَةٌ-مُكَابَدَةٌ [ك ب د] (مص.كَابَدَ). 1. ""مُكَابَدَةُ الجُوعِ"": تَحَمُّلُ مَشَاقِّهِ وَوَطْأَتِهِ. 2. ""مُكَابَدَةُ مَشَاقّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22949, 'مُكَابَرَةٌ', 'مكابرة', 'مصدر', 'كبر', 'مكابرة', 'مكبرة', 'مص. كَابَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُكَابَرَةٌ-مُكَابَرَةٌ [ك ب ر] (مص. كَابَرَ). ""عُرِفَ بِمُكَابَرَتِهِ"" : بِمُعَانَدَتِهِ. ""وبِرَغْمِ مُكَابَرَتِي وحِرْصِي عَلَى احْتِمَالِ مَا يَحْتَمِلُهُ أَهْلِي فَإِنَّ السَّيْرَ أَضْنَانِي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22950, 'مُكَاتَبَةٌ', 'مكاتبة', 'مصدر', 'كتب', 'مكاتبة', 'مكتبة', 'مص. كَاتَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُكَاتَبَةٌ-مُكَاتَبَةٌ [ك ت ب] (مص. كَاتَبَ). ""اِسْتَمَرَّ فِي مُكَاتَبَةِ أَهْلِهِ عَلَى الرَّغْمِ مِنْ انْقِطَاعِ أَخْبَارِهِمْ"" : مُرَاسَلَتِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22951, 'مُكَاتَمَةٌ', 'مكاتمة', 'مصدر', 'كتم', 'مكاتمة', 'مكتمة', 'مص. كَاتَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُكَاتَمَةٌ-مُكَاتَمَةٌ [ك ت م] (مص. كَاتَمَ). ""قَرَّرُوا مُكَاتَمَةَ كُلِّ الأَخْبَارِ عَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22952, 'كَيْدٌ', 'كيد', 'مصدر', 'كيد', 'كيد', 'كد', 'مص. كَادَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَيْدٌ-كَيْدٌ [ك ي د] (مص. كَادَ). ""دَبَّرَ لَهُ كَيْداً"" : مَكْراً، خُبْثًا، مَكِيدَةً. ""رَدَّ كَيْدَهُ إِلَى نَحْرِهِ""الطارق آآية 15، 16يَكيدونَ كَيْداً وَأَكيدُ كَيْداً . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22953, 'مَكِيدَةٌ', 'مكيدة', 'مصدر', 'كيد', 'مكيدة', 'مكدة', 'مص.كَادَ', '', '', 'مفرد', 'DnN', '', '', '"مَكَائِدُ"', '', 'R', '', '', '', '', '', '', '"(مص.كَادَ). ""كَادَ لَهُ مَكِيدَةً"" : خَدِيعَةً، مَكْراً، خُبْثاً. ""ذَهَبَ ضَحِيَّةَ مَكَائِدِ الْحَاسِدِينَ"" ""مَا يَسْلَمُ يَوْمٌ مِنْ شَرِّ يُبَيَّتُ أَوْ مَكِيدَةٍ تُذْهَبُ"". (إسحق الحسيني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22954, 'مَكَائِدُ', 'مكائد', 'مصدر', '', 'مكاءد', 'مكد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22955, 'كَوْرٌ', 'كور', 'مصدر', 'كور', 'كور', 'كر', 'مص. كَارَ', '', '', 'مفرد', 'DnN', '', '', '"أَكْوَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. كَارَ). ""كَوْرُ العِمَامَةِ"" : الدَّوْرُ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22956, 'أَكْوَارٌ', 'أكوار', 'مصدر', '', 'ءكوار', 'كر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22957, 'كِيَاسَةٌ', 'كياسة', 'مصدر', 'كيس', 'كياسة', 'كسة', 'مص. كَاسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كِيَاسَةٌ-كِيَاسَةٌ [ك ي س] (مص. كَاسَ). ""عَالَجَ الْمُشْكِلَةَ بِكُلِّ كِيَاسَةٍ"" : بِكُلِّ لَباقَةٍ وَفِطْنَةٍ وَهُدُوءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22958, 'مُكَاشَفَةٌ', 'مكاشفة', 'مصدر', 'كشف', 'مكاشفة', 'مكشفة', 'مص. كَاشَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُكَاشَفَةٌ-مُكَاشَفَةٌ [ك ش ف] (مص. كَاشَفَ). 1. ""مُكَاشَفَةُ الْحَقَائِقِ خَيْرٌ مِنَ التَّعَامِي عَنْهَا"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22959, 'كِفَاءٌ', 'كفاء', 'مصدر', 'كفأ', 'كفاء', 'كف', 'مص. كَافَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"كِفَاءٌ-كِفَاءٌ [ك ف أ] (مص. كَافَأَ). 1.""لاَ كِفَاءَ لَهُ"" : لاَ نَظِيرَ لَهُ. 2.""هَذَا كِفَاؤُهُ"" : أَيْ مِثْلُهُ. 3.""مَالِي بِهِ قِبَلٌ وَلاَ كِفَاءٌ"" : لاَ قُدْرَةَ لِي عَلَى التَّمَثُّلِ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22960, 'مُكَافَأَةٌ', 'مكافأة', 'مصدر', 'كفأ', 'مكافءة', 'مكفة', 'مص. كَافَأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. كَافَأَ). ""نَالَ مُكَافَأَةً عَلَى عَمَلِهِ"" : أَيْ مُجَازَاةً، جَزَاءً، عَطَاءً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22961, 'كِفَاحٌ', 'كفاح', 'مصدر', 'كفح', 'كفاح', 'كفح', 'مص. كَافَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كِفَاحٌ-كِفَاحٌ [ك ف ح] (مص. كَافَحَ). 1.""لَقِيتُهُ كِفَاحاً"" : أَيْ مُوَاجَهَةً. 2.""الكِفَاحُ الوَطَنِيُّ"" : النِّضَالُ. ""كِفَاحٌ مُسَلَّحٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22962, 'مُكَافَحَةٌ', 'مكافحة', 'مصدر', 'كفح', 'مكافحة', 'مكفحة', 'مص. كَافَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُكَافَحَةٌ-مُكَافَحَةٌ [ك ف ح] (مص. كَافَحَ). 1.""مُكَافَحَةُ الْمُخَدِّرَاتِ"" : مُقَاوَمَتُهَا، رَدْعُهَا، القَضَاءُ عَلَيْهَا. 2. ""مُكَافَحَةُ الشَّعْبِ للمُحْتَلِّ"" : مُحَارَبَتُهُ وَالتَّصَدِّي لَهُ. 3.""مِنْ بَيْنِ مَشَارِيعِ الْحُكُومَةِ مُكَافَحَةُ الْجَهْلِ"" : العَمَلُ لِلْقَضَاءِ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22963, 'مُكَافَلَةٌ', 'مكافلة', 'مصدر', 'كفل', 'مكافلة', 'مكفلة', 'مص. كَافَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُكَافَلَةٌ-مُكَافَلَةٌ [ك ف ل] (مص. كَافَلَ). ""تَأَكَّدَ مِنْ مُكَافَلَةِ صَاحِبِهِ"" : مِنْ تَعَاضُدِهِ وتَحَالُفِهِ وتَعَاهُدِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22964, 'كَيْلٌ', 'كيل', 'مصدر', 'كيل', 'كيل', 'كل', 'مص. كَالَ', '', '', 'مفرد', 'DnN', '', '', '"أَكْيَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. كَالَ). ""يُكَالُ القَمْحُ بِالكَيْلِ"" : الوِعَاءُ الَّذِي يُكَالُ بِهِ (يُوزَنُ) القَمْحُ وَغَيْرُهُ مِنَ الْحُبُوبِ. ""إِذَا امْتَلأَ الكَيْلُ طَفَحَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22965, 'أَكْيَالٌ', 'أكيال', 'مصدر', '', 'ءكيال', 'كل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22966, 'مُكَالَمَةٌ', 'مكالمة', 'مصدر', 'كلم', 'مكالمة', 'مكلمة', 'مص. كَالَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. كَالَمَ). 1.""جَرَتْ بَيْنَهُمَا مَكَالَمَةٌ وِدِّيَّةٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22967, 'كَوْنٌ', 'كون', 'مصدر', 'كون', 'كون', 'كن', 'مص. كَانَ', '', '', 'مفرد', 'DnN', '', '', '"أَكْوَانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. كَانَ). 1.""سُبْحَانَ الَّذِي خَلَقَ هَذَا الكَوْنَ"" : الوُجُودَ الْمُطْلَقَ العَامَّ. 2.""الكَوْنُ الأَعْلَى"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22968, 'أَكْوَانٌ', 'أكوان', 'مصدر', '', 'ءكوان', 'كن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22969, 'كِيَانٌ', 'كيان', 'مصدر', 'كون', 'كيان', 'كن', 'مص. كَانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. كَانَ). 1.""كِيَانُ البِلاَدِ"" : بِنْيَتُهُ، هَيْئَتُهُ. 2.""فِي دَاخِلِ كِيَانِهِ"" : فِي ذ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22970, 'مُكَايَدَةٌ', 'مكايدة', 'مصدر', 'كيد', 'مكايدة', 'مكدة', 'مص.كَايَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُكَايَدَةٌ-مُكَايَدَةٌ [ك ي د] (مص.كَايَدَ). ""يُضْمِرُ لَهُ الْمُكَايَدَةَ"": أَيِ الْمَكْرَ والخَدِيعَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22971, 'تَكْبيبٌ', 'تكبيب', 'مصدر', 'كبب', 'تكبيب', 'تكبب', 'مص. كَبَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْبيبٌ-تَكْبيبٌ [ك ب ب] (مص. كَبَّبَ). """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22972, 'كَبْحٌ', 'كبح', 'مصدر', 'كبح', 'كبح', 'كبح', 'مص. كَبَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَبْحٌ-كَبْحٌ [ك ب ح] (مص. كَبَحَ). 1.""كَبْحُهُ عَنْ حَاجَتِهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22973, 'تَكْبيدٌ', 'تكبيد', 'مصدر', 'كبد', 'تكبيد', 'تكبد', 'مص. كَبَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْبيدٌ-تَكْبيدٌ [ك ب د] (مص. كَبَّدَ). 1.""تَكْبيدُ الشَّمْسِ السَّماءَ"" : صَيْرُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22974, 'كَبَدٌ', 'كبد', 'مصدر', 'كبد', 'كبد', 'كبد', 'مص. كَبِدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَبَدٌ-كَبَدٌ [ك ب د] (مص. كَبِدَ). ""لَقِيَ فِي سَفَرِهِ كَبَداً"" : مَشَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22975, 'تَكْبيرٌ', 'تكبير', 'مصدر', 'كبر', 'تكبير', 'تكبر', 'مص. كَبَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْبيرٌ-تَكْبيرٌ [ك ب ر] (مص. كَبَّرَ). ""جَهَرَ بِالقِراءةِ والتَّكْبيرِ"": قَوْلُهُ : ""اللَّهُ أَكْبَرُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22976, 'تكابير', 'تكابير', 'مصدر', '', 'تكابير', 'تكبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22977, 'كُبَّارٌ', 'كبار', 'مصدر', 'كبر', 'كبار', 'كبر', 'مص. كَبَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كُبَّارٌ-كُبَّارٌ [ك ب ر] (مص. كَبَّرَ). ""شَيْءٌ كُبَّارٌ"" : كَبِيرٌ، جَسِيمٌ جِدّاً، مُفْرِطٌ فِي الْجَسَامَةِ.نوح آية 22 وَمَكَرُوا مَكْراً كُبَّاراً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22978, 'كُبْرٌ', 'كبر', 'مصدر', 'كبر', 'كبر', 'كبر', 'مص. كَبُرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كُبْرٌ-كُبْرٌ [ك ب ر] (مص. كَبُرَ). 1.""هُوَ كُبْرُ إِخْوَتِهِ"" : أَكْبَرُهُمْ سِنّاً. 2.""هُوَ كُبْرُ قَوْمِهِ"" : أَكْبَرُهُمْ وَأَعْلاَهُمْ نَسَباً. 3.""كُبْرُ مَقَامِهِ"" : شَرَفُهُ، رِفْعَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22979, 'كِبَرٌ', 'كبر', 'مصدر', 'كبر', 'كبر', 'كبر', 'مص. كَبُرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كِبَرٌ-كِبَرٌ [ك ب ر] (مص. كَبُرَ). ""كِبَرُ السِّنِّ"" : التَّقَدُّمُ فِي السِّنِ.مريم آية 8 وَقَدْ بَلَغْتُ مِنَ الكِبَرِ عِتِيّاً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22980, 'تَكْبيسٌ', 'تكبيس', 'مصدر', 'كبس', 'تكبيس', 'تكبس', 'مص. كَبَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْبيسٌ-تَكْبيسٌ [ك ب س] (مص. كَبَّسَ). ""تَكْبيسُ أَعْضاءِ الجِسْمِ"" : دَلْكُها، تَلْيِينُها بِالأيْدِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22981, 'تَكْبيلٌ', 'تكبيل', 'مصدر', 'كبل', 'تكبيل', 'تكبل', 'مص. كَبَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْبيلٌ-تَكْبيلٌ [ك ب ل] (مص. كَبَّلَ). ""تَكْبيلُ الرِّجْلَيْنِ"" : تَقْيِيدُهُما."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22982, 'كَبْلٌ', 'كبل', 'مصدر', 'كبل', 'كبل', 'كبل', 'مص. كَبَلَ', '', '', 'مفرد', 'DnN', '', '', '"كُبُولٌ:أَكْبُلٌ:أَكْبَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. كَبَلَ). 1.""قَيَّدَهُ بِالكَبْلِ"" : بِالقَيْدِ. 2.""كَبْلُ الكَهْرَبَاءِ وَنَحْوِهِ"" : حَبْلٌ مَعْدِنِيٌّ تُحِيطُ بِهِ مَادَّةٌ عَازِلَةٌ لَهَا غِلاَفٌ وَاحِدٌ يُوصِلُ الكَهْرَبَاءَ. 3.""كَبْلُ الشُّرْطِيِّ"" : القَيْدُ الْحَدِيدِيُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22983, 'كُبُولٌ', 'كبول', 'مصدر', '', 'كبول', 'كبل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22984, 'أَكْبُلٌ', 'أكبل', 'مصدر', '', 'ءكبل', 'كبل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22985, 'أَكْبَالٌ', 'أكبال', 'مصدر', '', 'ءكبال', 'كبل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22986, 'كَتِيتٌ', 'كتيت', 'مصدر', 'كتت', 'كتيت', 'كتت', 'مص. كَتَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كَتِيتٌ-كَتِيتٌ [ك ت ت] (مص. كَتَّ). 1.""كَتِيتُ القِدْرِ"" : صَوْتُ غَلَيَانِهَا. 2.""رَجُلٌ كَتِيتٌ"" : بَخِيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22987, 'تَكْتيبٌ', 'تكتيب', 'مصدر', 'كتب', 'تكتيب', 'تكتب', 'مص. كَتَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْتيبٌ-تَكْتيبٌ [ك ت ب] (مص. كَتَّبَ). ""تَكْتيبُ الوَلَدِ"" : تَعْليمُهُ الكِتابَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22988, 'كِتَابَةٌ', 'كتابة', 'مصدر', 'كتب', 'كتابة', 'كتبة', 'مص. كَتَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. كَتَبَ). 1.""يَحْتَرِفُ الكِتَابَةَ"" : أَي تَأْلِيفَ الْمَقَالاَتِ وَتَدْبِيجَهَا، حِرْفَةُ الكَاتِبِ. 2.""لُغَةُ الكِتَابَةِ"" : لُغَةُ الإِنْشَاءِ وَأَنْوَاعُهُ. ""تَتَمَيَّزُ كِتَابَتُهُ بِسَلاَسَةِ الأُسْلُوبِ"". 3.""كِتَابَةُ الوَزِيرِ أَوِالْمُدِيرِ"" : القِسْمُ الإِدَارِيُّ الْمُهْتَمُّ بِالْمُرَاسَلاَتِ وَضَبْطِهَا وَتَنْظِيمِ سَيْرِ عَمَلِهِ. 4.""كِتَابَةُ الدَّوْلَةِ فِي الشُّؤُونِ الْخَارِجِيَّةِ"": مَا يُعَادِلُ الْمُدِيرِيَّةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22989, 'كِتَابٌ', 'كتاب', 'مصدر', 'كتب', 'كتاب', 'كتب', 'مص. كَتَبَ', '', '', 'مفرد', 'DnN', '', '', '"كُتُبٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. كَتَبَ). 1.""كَتَبَ كِتَاباً فِي الأَدَبِ"" : أَيْ مُؤَلَّفاً يَتَضَمَّنُ صَفَحَاتٍ مَكْتُوبَةً. ""قَرَأَ الكِتَابَ"" ""خِزَانَةُ الكُتُبِ"". 2.""سَلَّمَهُ كِتَاباً"": رِسَالَةً. 3.""أَهْلُ الكِتَابِ"" : أَيِ الْمُسْلِمُونَ وَاليَهُودُ وَالنَّصَارَى أَصْحَابُ الدِّيَانَاتِ الَّتِي لَهَا كَلاَمٌ مُنَزَّلٌ يَتَضَمَّنُ عَقَائِدَهُم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22990, 'كُتُبٌ', 'كتب', 'مصدر', '', 'كتب', 'كتب', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22991, 'تَكْتيفٌ', 'تكتيف', 'مصدر', 'كتف', 'تكتيف', 'تكتف', 'مص. كَتَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْتيفٌ-تَكْتيفٌ [ك ت ف] (مص. كَتَّفَ). ""تَكْتيفُ الرَّجُلِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22992, 'كَتْفٌ', 'كتف', 'مصدر', 'كتف', 'كتف', 'كتف', 'مص. كَتَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَتْفٌ-كَتْفٌ [ك ت ف] (مص. كَتَفَ). ن.كَتِفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22993, 'كَتِيفٌ', 'كتيف', 'مصدر', 'كتف', 'كتيف', 'كتف', 'مص. كَتَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":كُتُفٌ:كُتْفٌ"', '', 'R', '', '', '', '', '', '', '"(مص. كَتَفَ). 1.""كَتِيفُ الإِنَاءِ"" : صَفِيحَةٌ من حَدِيد ونَحْوِهِ تَكونُ في الإِنَاءِ أو البابِ. 2.""سَيْفٌ كَتِيفٌ"" : سَيْفٌ صَفِيحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22994, 'كُتُفٌ', 'كتف', 'مصدر', '', 'كتف', 'كتف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22995, 'كُتْفٌ', 'كتف', 'مصدر', '', 'كتف', 'كتف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22996, 'تَكْتيلٌ', 'تكتيل', 'مصدر', 'كتل', 'تكتيل', 'تكتل', 'مص. كَتَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْتيلٌ-تَكْتيلٌ [ك ت ل] (مص. كَتَّلَ). 1.""تَكْتيلُ العَجينِ"" : جَمْعُهُ، تَدْوِيرُهُ. 2.""تَكْتيلُ القُوَى"" : تَعْضيدُها، تَجْميعُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22997, 'تَكْتيمٌ', 'تكتيم', 'مصدر', 'كتم', 'تكتيم', 'تكتم', 'مص. كَتَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْتيمٌ-تَكْتيمٌ [ك ت م] (مص. كَتَّمَ). 1.""تَكْتيمُ السِّرِّ"" : إِخْفاؤُهُ. 2.""تَكْتيمُ الحَديثِ"" : الْمُبالَغَةُ في كِتْمانِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22998, 'كِتْمَانٌ', 'كتمان', 'مصدر', 'كتم', 'كتمان', 'كتمن', 'مص. كَتَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كِتْمَانٌ-كِتْمَانٌ [ك ت م] (مص. كَتَمَ). ""كِتْمَانُ السِّرِّ"" : كَتْمُهُ، إِخْفَاؤُهُ. ""إِلَى مَتَى يَجِبُ أَنْ ت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(22999, 'كَتْمٌ', 'كتم', 'مصدر', 'كتم', 'كتم', 'كتم', 'مص. كَتَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَتْمٌ-كَتْمٌ [ك ت م] (مص. كَتَمَ). ""كَتْمُ السِّرِّ"" : كِتْمَانُهُ، إِخْفَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23000, 'كَثٌّ', 'كث', 'مصدر', 'كثث', 'كث', 'كث', 'مص. كَثَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كَثٌّ-كَثٌّ، ةٌ [ك ث ث] (مص. كَثَّ). 1.""شَعْرٌ كَثٌّ"" : مُكَثَّفٌ، مُجَعَّدٌ. 2.""رَجُلٌ كَثُّ اللِّحْيَةِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23001, 'كَثَّةٌ', 'كثة', 'مصدر', 'كثث', 'كثة', 'كثة', 'مص. كَثَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كَثٌّ-كَثٌّ، ةٌ [ك ث ث] (مص. كَثَّ). 1.""شَعْرٌ كَثٌّ"" : مُكَثَّفٌ، مُجَعَّدٌ. 2.""رَجُلٌ كَثُّ اللِّحْيَةِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23002, 'تَكْثيرٌ', 'تكثير', 'مصدر', 'كثر', 'تكثير', 'تكثر', 'مص. كَثَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْثيرٌ-تَكْثيرٌ [ك ث ر] (مص. كَثَّرَ). ""تَكْثيرُ الطَّعامِ"" : جَعْلُهُ كَثيراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23003, 'كَثْرَةٌ', 'كثرة', 'مصدر', 'كثر', 'كثرة', 'كثرة', 'مص. كَثُرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كَثْرَةٌ-كَثْرَةٌ [ك ث ر] (مص. كَثُرَ). 1.""كَثْرَةُ الْمَالِ"" : وَفْرَتُهُ. 2.""كَثْرَةُ الإِنْتَاجِ"" : غَزَارَتُهُ. ""نَزَلَتِ الخُضَرُ بِكَثْرَةٍ فِي الأَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23004, 'تَكْثيفٌ', 'تكثيف', 'مصدر', 'كثف', 'تكثيف', 'تكثف', 'مص. كَثَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْثيفٌ-تَكْثيفٌ [ك ث ف] (مص. كَثَّفَ). 1.""تَكْثيفُ العَجينِ"" : تَلْبيدُهُ، تَجْميعُهُ، تَثْخينُهُ. 2.""تَكْثيفُ اللَّبَنِ"" : جَعْلُهُ رائِباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23005, 'كَثَافَةٌ', 'كثافة', 'مصدر', 'كثف', 'كثافة', 'كثفة', 'مص. كَثُفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كَثَافَةٌ-كَثَافَةٌ [ك ث ف] (مص. كَثُفَ). 1.""كَثَافَةُ مَعْدِنٍ"" (فيز) : نِسْبَةُ ثِقْلِ حَجْمٍ مَّا مِنْ جِسْمٍ إِلَى الْحَجْمِ ذَاتِهِ مِنَ الْمَاءِ أَوِ الْهَوَاءِ فِي الغَازَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23006, 'كَثْلٌ', 'كثل', 'مصدر', 'كثل', 'كثل', 'كثل', 'مص. كَثَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَثْلٌ-كَثْلٌ [ك ث ل] (مص. كَثَلَ).""كَثْلُ الشَّيْءِ"" : جَمْعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23007, 'تَكْحيلٌ', 'تكحيل', 'مصدر', 'كحل', 'تكحيل', 'تكحل', 'مص. كَحَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْحيلٌ-تَكْحيلٌ [ك ح ل] (مص. كَحَّلَ). ""تَكْحيلُ العَيْنِ"" : وَضْعُ الك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23008, 'كَدٌّ', 'كد', 'مصدر', 'كدد', 'كد', 'كد', 'مص. كَدَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَدٌّ-كَدٌّ [ك د د] (مص. كَدَّ). ""يَحْصُلُ عَلَى عَيْشِهِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23009, 'كَدْحٌ', 'كدح', 'مصدر', 'كدح', 'كدح', 'كدح', 'مص. كَدَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَدْحٌ-كَدْحٌ [ك د ح] (مص. كَدَحَ). ""لاَ يَتَوَقَّفُ عَنِ الكَدْحِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23010, 'تَكْديرٌ', 'تكدير', 'مصدر', 'كدر', 'تكدير', 'تكدر', 'مص. كَدَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْديرٌ-تَكْديرٌ [ك د ر] (مص. كَدَّرَ). 1.""تَكْديرُ الماءِ"" : خَلْطُهُ بِمادَّةٍ، تَغْيِيرُ لَوْنِهِ وَطَعْمِهِ. 2.""تَكْديرُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23011, 'كَدَرٌ', 'كدر', 'مصدر', 'كدر', 'كدر', 'كدر', 'مص. كَدِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَدِرٌ-كَدِرٌ [ك د ر] (صِيغَةُ فَعِل). 1.""عَيْشٌ كَدِرٌ"": عَيْشٌ مُضْنٍ، شَاقٌّ، صَعْبٌ. 2.""لَوْنٌ كَدِرٌ"" : شَاحِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23012, 'كُدْرَةٌ', 'كدرة', 'مصدر', 'كدر', 'كدرة', 'كدرة', 'مص. كَدُرَ، كَدِرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كُدْرَةٌ-كُدْرَةٌ [ك د ر] (مص. كَدُرَ، كَدِرَ). ""كُدْرَةُ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23013, 'تَكْديسٌ', 'تكديس', 'مصدر', 'كدس', 'تكديس', 'تكدس', 'مص. كَدَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْديسٌ-تَكْديسٌ [ك د س] (مص. كَدَّسَ). ""تَكْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23014, 'كَدْسٌ', 'كدس', 'مصدر', 'كدس', 'كدس', 'كدس', 'مص. كَدَسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَدْسٌ-كَدْسٌ [ك د س] (مص. كَدَسَ). ""كَدْسُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23015, 'تَكْذيبٌ', 'تكذيب', 'مصدر', 'كذب', 'تكذيب', 'تكذب', 'مص. كَذَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَكْذيبٌ-تَكْذيبٌ [ك ذ ب] (مص. كَذَّبَ). ""تَكْذِيبُ أَقْوالِهِ"": إِظْهارُ كَذِبِها. ""لاَ يَقْدِرُ أَحَدٌ على تَكْذِيبِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23016, 'كَذِبٌ', 'كذب', 'مصدر', 'كذب', 'كذب', 'كذب', 'مص. كَذَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَذِبٌ-كَذِبٌ [ك ذ ب] (مص. كَذَبَ). ""أَقْوَالُهُ كَذِبٌ فِي كَذِبٍ"" : مُخَالِفَةٌ لِلْحَقِيقَةِ وَالأَمْرِ الوَاقِعِ. ""حَبْلُ الكَذِبِ قَصِيرٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23017, 'كَذْبَةٌ', 'كذبة', 'مصدر', 'كذب', 'كذبة', 'كذبة', 'مص. كَذِبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كَذْبَةٌ-كَذْبَةٌ [ك ذ ب] (مص. كَذِبَ). ""كَذْبَةٌ مَفْضُوحَةٌ"" : أَمْرٌ مُخَالِفٌ لِلْحَقِيقَةِ. ""كَذْبَةٌ بَيْضَاءُ"" ""كَذْبَةُ إِبْرِيل""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23018, 'كِذَّابٌ', 'كذاب', 'مصدر', 'كذب', 'كذاب', 'كذب', 'مص. كَذَبَ، كَذَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كِذَّابٌ-كِذَّابٌ [ك ذ ب] (مص. كَذَبَ، كَذَّبَ). ""قَوْلٌ كِذَّابٌ"" : كَذِبٌ. النبأ آية 28وكَذَّبُوا بِآيَاتِنَا كِذَّاباً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23019, 'كَرٌّ', 'كر', 'مصدر', 'كرر', 'كر', 'كر', 'مص. كَرَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَرٌّ-كَرٌّ [ك ر ر] (مص. كَرَّ). 1.""كَرُّ الأَيَّامِ"" : تَدَاوُلُهَا. ""عَلَى كَرِّ الأَيَّامِ"" : مَدَاهَا. 2.""الكَرُّ وَالفَرُّ"" : الهُجُومُ وَالتَّرَاجُعُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23020, 'كَرِيرٌ', 'كرير', 'مصدر', 'كرر', 'كرير', 'كرر', 'مص. كَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كَرِيرٌ-كَرِيرٌ [ك ر ر] (مص. كَرَّ). ""كَرِيرُ الصَّدْرِ"" : ص"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23021, 'كَرْبٌ', 'كرب', 'مصدر', 'كرب', 'كرب', 'كرب', 'مص. كَرَبَ', '', '', 'مفرد', 'DnN', '', '', '"كُرُوبٌ"', '', 'R', '', '', '', '', '', '', '"(مص. كَرَبَ). ""اِشْتَدَّ بِهِ الكَرْبُ"" : الْحُزْنُ الشَّدِيدُ، الْمَشَقَّةُ.الصافات آية 76وَنَجَّيْنَاهُ وَأَهْلَهُ مِنَ الكَرْبِ العَظِيمِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23022, 'كُرُوبٌ', 'كروب', 'مصدر', '', 'كروب', 'كرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
