INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23024, 'تَكْريرٌ', 'تكرير', 'مصدر', 'كرر', 'تكرير', 'تكرر', 'مص. كَرَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْريرٌ-تَكْريرٌ [ك ر ر] (مص. كَرَّرَ). ""تَكْريرُ النَّفْطِ"" : تَصْفِيَتُهُ، تَنْقِيَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23025, 'تَكْريسٌ', 'تكريس', 'مصدر', 'كرس', 'تكريس', 'تكرس', 'مص. كَرَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْريسٌ-تَكْريسٌ [ك ر س] (مص. كَرَّسَ). ""تَكْريسُ الأخْلاقِ"": تَرْسِيخُها، تَثْبيتُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23026, 'كَرْكَرَةٌ', 'كركرة', 'مصدر', 'كركر', 'كركرة', 'كركرة', 'مص. كَرْكَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كَرْكَرَةٌ-كَرْكَرَةٌ [ك ر ك ر] (مص. كَرْكَرَ). 1.""كَرْكَرَةُ الرَّحَى"" : قَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23027, 'تَكْريمٌ', 'تكريم', 'مصدر', 'كرم', 'تكريم', 'تكرم', 'مص. كَرَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْريمٌ-تَكْريمٌ [ك ر م] (مص. كَرَّمَ). 1.""جاءَ لِتَكْريمِهِ"" : لِتَشْريفِهِ. 2.""أَقامَ ح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23028, 'كَرَامَةٌ', 'كرامة', 'مصدر', 'كرم', 'كرامة', 'كرمة', 'مص. كَرُمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. كَرُمَ). 1.""يَصُونُ كَرَامَتَهُ عَنْ كُلِّ مَا يُدَنِّسُهَا"" : شَرَفَهُ، عِزَّةَ نَفْسِهِ. ""يَحْتَفِظُ بِكَرَامَتِهِ وَيَعْتَزُّ بِش"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23029, 'كَرَمٌ', 'كرم', 'مصدر', 'كرم', 'كرم', 'كرم', 'مص. كَرُمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَرَمٌ-كَرَمٌ [ك ر م] (مص. كَرُمَ). 1.""عُرِفَ العَرَبُ بِالكَرَمِ"": بِالجُودِ، بِالسَّخَاءِ. 2.""كَرَمُ الأَخْلاَقِ"" : نُبْلُهُ، سُمُوُّ النَّفْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23030, 'تَكْريهٌ', 'تكريه', 'مصدر', 'كره', 'تكريه', 'تكره', 'مص. كَرَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْريهٌ-تَكْريهٌ [ك ر هـ] (مص. كَرَّهَ). ""تَكْريهُهُ الحرامَ"": جَعْلُهُ يَكْرَهُهُ، يَمْقُتُهُ، يَبْغُضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23031, 'كُرْهٌ', 'كره', 'مصدر', 'كره', 'كره', 'كره', 'مص. كَرِهَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَرْهٌ-كَرْهٌ [ك ر هـ]. 1.""عَلَى كَرْهٍ مِنْهُ"" : عَلَى الرَّغْمِ مِنْهُ، أَيْ مَا فَعَلَهُ أُكْرِهَ عَلَيْهِ. 2.""عَمَلٌ كَرْهٌ"" : مَكْرُوهٌ. الأحقاف آية 15حَمَلَتْهُ أُمُّهُ كَرْهاً وَوَضَعَتْهُ كَرْهاً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23032, 'كَرَاهَةٌ', 'كراهة', 'مصدر', 'كره', 'كراهة', 'كرهة', 'مص. كَرِهَ،كَرُهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كَرَاهَةٌ-كَرَاهَةٌ [ك ر هـ] (مص. كَرِهَ،كَرُهَ). ""عَبَّرَ عَنْ كَرَاهَتِهِ لِمَا بَدَرَ مِنْهُ مِنْ أَفْعَالٍ سَيِّئَةٍ"" : عَنْ مَقْتِهِ وَغَضَبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23033, 'كَرَاهِيَةٌ', 'كراهية', 'مصدر', 'كره', 'كراهية', 'كرهة', 'مص. كَرِهَ،كَرُهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"كَرَاهِيَةٌ-كَرَاهِيَةٌ [ك ر هـ] (مص. كَرِهَ،كَرُهَ). ""لاَ أَعْرِفُ لِمَاذَا يُكِنُّ لَهُ الكَرَاهِيَةَ"" : الحِقْدَ، الْمَقْتَ، الغَضَبَ."', '');
