INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23047, 'كَشَحٌ', 'كشح', 'مصدر', 'كشح', 'كشح', 'كشح', 'مص. كَشِحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَشَحٌ-كَشَحٌ [ك ش ح] (مص. كَشِحَ). ""أُصِيبَ بِالكَشَحِ"": دَاءٌ يُصِيبُ الْجَنْبَ، الكَشْحَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23048, 'تَكْشِيرٌ', 'تكشير', 'مصدر', 'كشر', 'تكشير', 'تكشر', 'مص. كَشَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْشِيرٌ-تَكْشِيرٌ [ك ش ر] (مص. كَشَّرَ). ""التَّكْشيرُ عَنِ الأسْنا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23049, 'تَكْشيفٌ', 'تكشيف', 'مصدر', 'كشف', 'تكشيف', 'تكشف', 'مص. كَشَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْشيفٌ-تَكْشيفٌ [ك ش ف] (مص. كَشَّفَ). 1.""تَكْشِيفُ الحَقيقَةِ"" : كَشْفُها، إِظْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23050, 'كَشْفٌ', 'كشف', 'مصدر', 'كشف', 'كشف', 'كشف', 'مص. كَشَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَشْفٌ-كَشْفٌ [ك ش ف] (مص. كَشَفَ). 1.""أَظْهَرَ الكَشْفُ حَقَائِقَ جَدِيدَةً"" : البَحْثُ، الاسْتِحْقَاقُ، الاسْتِطْلاَعُ. 2.""تَقَدَّمَ لِلْكَشْفِ الطِّبِّيِّ"" : ل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23051, 'كَظٌّ', 'كظ', 'مصدر', 'كظظ', 'كظ', 'كظ', 'مص. كَظَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَظٌّ-كَظٌّ [ك ظ ظ] (مص. كَظَّ). ""رَجُلٌ كَظٌّ"" : تُبْهِظُهُ الأُمُورُ وَتَغْلِبُهُ فَيَضِيقُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23052, 'تَكْعيبٌ', 'تكعيب', 'مصدر', 'كعب', 'تكعيب', 'تكعب', 'مص. كَعَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَكْعيبٌ-تَكْعيبٌ [ك ع ب] (مص. كَعَّبَ). 1. ""تَكْعِيبٌ مَّا"". (حسا) : حَاصِلُ ضَرْبِ عَدَدٍ فِي ثَلاَثَةِ أعْدَادٍ مُسَاوِيَةٍ لِلْعَد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23053, 'كَفٌّ', 'كف', 'مصدر', 'كفف', 'كف', 'كف', 'مص. كَفَّ', '', '', 'مفرد', 'DnN', '', '', '"أَكُفٌّ"', '', 'R', '', '', '', '', '', '', '"(مص. كَفَّ). 1.""كَفُّ اليَدِ"" : رَاحَةُ اليَدِ مَعَ الأَصَابِعِ. 2.""وَضَعَ حَيَاتَهُ عَلَى كَفِّهِ"" : أَيْ خَاطَرَ بِنَفْسِهِ. 3.""قَارِئُ الكَفِّ"" : الْمُنَجِّمُ الَّذِي يَقْرَأُ،كَمَا يَدَّعِي، خُطُوطَ صَفِيحَةِ اليَدِ. ""قِرَاءةُ الكَفِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23054, 'أَكُفٌّ', 'أكف', 'مصدر', '', 'ءكف', 'كف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23055, 'تَكْفيرٌ', 'تكفير', 'مصدر', 'كفر', 'تكفير', 'تكفر', 'مص. كَفَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْفيرٌ-تَكْفيرٌ [ك ف ر] (مص. كَفَّرَ). ""حَكَمَ بِتَكْفيرِهِ"": الحُكْمُ عَلَيْهِ بِالإِلْحادِ، أَيْ إِبْعادُهُ وَإِخْراجُهُ عَنْ مَبادِئ دِينِ الجَماعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23056, 'كُفْرَانٌ', 'كفران', 'مصدر', 'كفر', 'كفران', 'كفرن', 'مص. كَفَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كُفْرَانٌ-كُفْرَانٌ [ك ف ر] (مص. كَفَرَ). ""الكُفْرَانُ بِاللَّهِ"" : إِنْكَارُ وُجُودِهِ، جُحُودُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23057, 'كَفْرٌ', 'كفر', 'مصدر', 'كفر', 'كفر', 'كفر', 'مص. كَفَرَ', '', '', 'مفرد', 'DnN', '', '', '"كُفُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. كَفَرَ). 1.""اِسْتَقَرَّ فِي الكَفْرِ"" : فِي القَرْيَةِ، أَوْ فِي أَرْضٍ بَعِيدَةٍ عَنِ النَّاسِ. 2.""وَضَعُوا الْمَيِّتَ فِي كَفْرِهِ"" : فِي قَبْرِهِ. 3.""أَلْقَى اللَّيْلُ بِكَفْرِهِ"" : بِسَوَادِ ظُلْمَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23058, 'كُفُورٌ', 'كفور', 'مصدر', '', 'كفور', 'كفر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23059, 'كُفْرٌ', 'كفر', 'مصدر', 'كفر', 'كفر', 'كفر', 'مص. كَفَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كُفْرٌ-كُفْرٌ [ك ف ر] (مص. كَفَرَ). ""الكُفْرُ بِاللَّهِ"" : إِنْكَارُ وُجُودِهِ، جُحُودُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23060, 'تَكْفيلٌ', 'تكفيل', 'مصدر', 'كفل', 'تكفيل', 'تكفل', 'مص. كَفَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْفيلٌ-تَكْفيلٌ [ك ف ل] (مص. كَفَّلَ). ""تَكْفيلُ وَلَدٍ"": التَّكَفُّلُ بِهِ، إِعالتُهُ، الإِنْفاقُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23061, 'كَفَالَةٌ', 'كفالة', 'مصدر', 'كفل', 'كفالة', 'كفلة', 'مص. كَفَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. كَفَلَ). ""لاَ بُدَّ لَهُ مِنْ كَفَالَةٍ"" : مِنْ ضَمَانَةٍ. ""تَمَتَّعَ بِالسَّرَاحِ الْمُؤَقَّتِ بِكَفَالَةٍ مَالِيَّةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23062, 'تَكْفينٌ', 'تكفين', 'مصدر', 'كفن', 'تكفين', 'تكفن', 'مص. كَفَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْفينٌ-تَكْفينٌ [ك ف ن] (مص. كَفَّنَ). ""تَكْفينُ الْمَيِّتِ"": كَفْنُهُ، أي إِلْباسُهُ الكَفَنَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23063, 'كَفْنٌ', 'كفن', 'مصدر', 'كفن', 'كفن', 'كفن', 'مص. كَفَنَ', '', '', 'مفرد', 'DnN', '', '', '"أَكْفَانٌ"', '', 'R', '', '', '', '', '', '', '"كَفْنٌ-كَفْنٌ [ك ف ن] (مص. كَفَنَ). ""طَعَامٌ كَفْنٌ"" : لاَ مِلْحَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23064, 'أَكْفَانٌ', 'أكفان', 'مصدر', '', 'ءكفان', 'كفن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23065, 'كِفَايَةٌ', 'كفاية', 'مصدر', 'كفي', 'كفاية', 'كفة', 'مص. كَفَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. كَفَى). 1.""هَذَا الإِنْتَاجُ فِيهِ كِفَايَةٌ"" : فِيهِ مَا يَكْفِي وَيُغْنِي عَنِ الزِّيَادَةِ. ""فِي هَذَا الطَّعَامِ كِفَايَةٌ"". 2.""كِفَايَةٌ مِنْ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23066, 'كَلالَةٌ', 'كلالة', 'مصدر', 'كلل', 'كلالة', 'كللة', 'مص. كَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كَلالَةٌ-كَلالَةٌ [ك ل ل] (مص. كَلَّ). 1.""رَجُلٌ كَلاَلَةٌ"" : لَيْسَ لَهُ وَلَدٌ وَلاَ وَالِدٌ.النساء آية 12 وَإِنْ كَانَ رَجُلٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23067, 'كِلَّةٌ', 'كلة', 'مصدر', 'كلل', 'كلة', 'كلة', 'مص. كَلَّ', '', '', 'مفرد', 'DnN', '', '', '"كِلَلٌ"', '', 'R', '', '', '', '', '', '', '"(مص. كَلَّ). 1. : غِشَاءٌ رَقِيقٌ أَوْ خُيُوطٌ رَقِيقَةٌ مُتَّصِلَةٌ يُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23068, 'كِلَلٌ', 'كلل', 'مصدر', '', 'كلل', 'كل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23069, 'كَلٌّ', 'كل', 'مصدر', 'كلل', 'كل', 'كل', 'مص. كَلَّ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"كَلٌّ-كَلٌّ [ك ل ل] (مص. كَلَّ). 1.""وَلَدٌ كَلٌّ"" : ضَعِيفٌ. 2.""رَجُلٌ كَلٌّ"" : ثَقِيلٌ لاَ خَيْرَ فِيهِ، أَوْ عِبْء"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23070, 'كَلَبٌ', 'كلب', 'مصدر', 'كلب', 'كلب', 'كلب', 'مص. كَلِبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَلَبٌ-كَلَبٌ [ك ل ب] (مص. كَلِبَ). 1.""أَصَابَهُ دَاءُ الكَلَبِ"" : دَاءٌ مُعْدٍ يُشْبِهُ السَّعْرَ يُصِيبُ الكِلاَبَ، وَبِمُجَرَّدِ مَا تَعَضُّ النَّاسَ، تَنْقُلُهُ إِلَيْهِمْ مِمَّا يَفْرِضُ اسْتِعْمَالَ لِقَاحٍ مُبَاشَرَةً. 2.""كَلَبُ الشِّتَاءِ"" : شِدَّتُهُ، حِدَّتُهُ. 3.""دَفَعَ عَنْهُ كَلَبَ أَعْدَائِهِ"" : أذَاهُمْ وَشَرَّهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23071, 'تَكْليسٌ', 'تكليس', 'مصدر', 'كلس', 'تكليس', 'تكلس', 'مص. كَلَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْليسٌ-تَكْليسٌ [ك ل س] (مص. كَلَّسَ). """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23072, 'تَكْليفٌ', 'تكليف', 'مصدر', 'كلف', 'تكليف', 'تكلف', 'مص. كَلَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَكالِيفُ"', '', 'R', '', '', '', '', '', '', '"(مص. كَلَّفَ). 1.""قامَ بِتَكْليفِهِ بِمُهِمَّةٍ"" : قامَ بِتَحْميلِهِ وَإِلْزامِهِ إِيَّاها، وَفي العَمَلِ الإِدارِيِّ، اِنْتِدابُهُ لَها. 2.""يَتَحَمَّلُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23073, 'تَكالِيفُ', 'تكاليف', 'مصدر', '', 'تكاليف', 'تكلف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23074, 'تَكْليلٌ', 'تكليل', 'مصدر', 'كلل', 'تكليل', 'تكلل', 'مص. كَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْليلٌ-تَكْليلٌ [ك ل ل] (مص. كَلَّلَ). 1.""تَكْليلُ الْمَلِكِ"" : إِلْباسُهُ الإِكْليلَ. 2.""تَكْليلُ أَعْمال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23075, 'تَكْليمٌ', 'تكليم', 'مصدر', 'كلم', 'تكليم', 'تكلم', 'مص. كَلَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْليمٌ-تَكْليمٌ [ك ل م] (مص. كَلَّمَ). ""تَكْلي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23076, 'تَكْميدٌ', 'تكميد', 'مصدر', 'كمد', 'تكميد', 'تكمد', 'مص. كَمَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْميدٌ-تَكْميدٌ [ك م د] (مص. كَمَّدَ). ""تَكْميدُ أَعْضاءِ الجِسْمِ"": تَسْخينُها بِوَضْعِ الكِمادَةَ عَلَيْها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23077, 'كَمَدٌ', 'كمد', 'مصدر', 'كمد', 'كمد', 'كمد', 'مص. كَمِدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَمَدٌ-كَمَدٌ [ك م د] (مص. كَمِدَ). ""يَعِيشُ فِي كَمَدٍ وَغَمٍّ"": في حُزْنٍ شَدِيدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23078, 'تَكْميلٌ', 'تكميل', 'مصدر', 'كمل', 'تكميل', 'تكمل', 'مص. كَمَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْميلٌ-تَكْميلٌ [ك م ل] (مص. كَمَّلَ). ""تَكْميلُ الأعْمالِ"" : إِتْمامُهُ، إِكْمالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23079, 'كَمَالٌ', 'كمال', 'مصدر', 'كمل', 'كمال', 'كمل', 'مص. كَمُلَ، كَمَلَ، كَمِلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كَمَالٌ-كَمَالٌ [ك م ل] (مص. كَمُلَ، كَمَلَ، كَمِلَ). 1.""كَمَالُ الجِسْمِ"" : تَمَامُهُ، حُسْنُهُ، قِوَامُهُ الْحَسَنُ. ""صِفَاتُ الكَمَالِ"". 2.""أَدَّى عَمَلَهُ عَلَى وَجْهِ الكَمَالِ"" : عَلَى أَحْسَنِ وَجْهٍ. 3.""لَهُ كَمَالُ الشَّيْءِ"" : أَيْ كُلُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23080, 'كُمُونٌ', 'كمون', 'مصدر', 'كمن', 'كمون', 'كمن', 'مص. كَمَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كُمُونٌ-كُمُونٌ [ك م ن] (مص. كَمَنَ). ""فِي كُمُونٍ عَنِ الأَنْظَارِ"" : فِي اخْتِفَاءٍ وَتَوَارٍ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23081, 'كُمْنَةٌ', 'كمنة', 'مصدر', 'كمن', 'كمنة', 'كمنة', 'مص. كَمِنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كُمْنَةٌ-كُمْنَةٌ [ك م ن] (مص. كَمِنَ). أَصَابَتْ الكُمْنَةُ عَيْنَـهُ"" : مَرَضٌ يُصِيبُ العَيْنَ مِنْ جَرَّاءِ ضَعْفٍ فِي العَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23082, 'كَنْزٌ', 'كنز', 'مصدر', 'كنز', 'كنز', 'كنز', 'مص. كَنَزَ', '', '', 'مفرد', 'DnN', '', '', '"كُنُوزٌ"', '', 'R', '', '', '', '', '', '', '"(مص. كَنَزَ). 1.""يَبْحَثُ عَنِ الكَنْزِ"" : الْمَال أَوِ الذَّهَب الْمَدْفُون فِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23083, 'كُنُوزٌ', 'كنوز', 'مصدر', '', 'كنوز', 'كنز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23084, 'تَكْنيسٌ', 'تكنيس', 'مصدر', 'كنس', 'تكنيس', 'تكنس', 'مص. كَنَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْنيسٌ-تَكْنيسٌ [ك ن س] (مص. كَنَّسَ). ""تَكْنيسُ البَيْت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23085, 'تَكْنيفٌ', 'تكنيف', 'مصدر', 'كنف', 'تكنيف', 'تكنف', 'مص. كَنَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْنيفٌ-تَكْنيفٌ [ك ن ف] (مص. كَنَّفَ). """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23086, 'كَنْفٌ', 'كنف', 'مصدر', 'كنف', 'كنف', 'كنف', 'مص. كَنَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"كَنْفٌ-كَنْفٌ [ك ن ف] (مص. كَنَفَ). ""يَعِيشُ فِي كَن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23087, 'تَكْنِيَة', 'تكنية', 'مصدر', 'كني', 'تكنية', 'تكنة', 'مص. كَنَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَكْنِيَة-تَكْنِيَة [ك ن ي] (مص. كَنَّى). ""تَكْنِيَةُ الرَّجُلِ"" : تَسْمِيَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23088, 'كِنَايَةٌ', 'كناية', 'مصدر', 'كنو،كني', 'كناية', 'كنة', 'مص. كَنَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. كَنَى). فِي البَلاَغَةِ : لَفْظٌ أُرِيدَ بِهِ غَيْرُ مَعْنَاهُ الَّذِي وُضِعَ لَهُ، مَعَ جَوَازِ إِرَادَةِ الْمَعْنَى الأَصْلِيِّ بَعْدَ وُجُودِ قَرِينَةٍ مَانِعَةٍ مِنْ إِرَادَتِهِ، وَهِيَ أَنْوَاعٌ: 1.كِنَايَةٌ عَنْ مَوْصُوفٍ : ""النَّاط"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23089, 'كُنْيَةٌ', 'كنية', 'مصدر', 'كني', 'كنية', 'كنة', 'مص. كَنَى', '', '', 'مفرد', 'DnN', '', '', '"كُنىً"', '', '', '', '', '', '', '', '', '"(مص. كَنَى). ""أَطْلَقُوا عَلَيْهِ كُنْيَةَ كَذَا"" : أَيْ أَنْ يُكْنَى الرَّجُلُ بِاسْمٍ يُلاَئِمُ صِفَةً مِنْ صِفَاتِهِ. ""ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23090, 'كُنىً', 'كنى', 'مصدر', '', 'كنى', 'كن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23091, 'كُهُولَةٌ', 'كهولة', 'مصدر', 'كهل', 'كهولة', 'كهلة', 'مص. كَهُلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كُهُولَةٌ-كُهُولَةٌ [ك هـ ل] (مص. كَهُلَ). ""مَرْحَلَةُ الكُهُولَةِ"": الشَّيْخُوخَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23092, 'تَكْويرٌ', 'تكوير', 'مصدر', 'كور', 'تكوير', 'تكر', 'مص. كَوَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْويرٌ-تَكْويرٌ [ك و ر] (مص. كَوَّرَ). 1.""تَكْويرُ العِمامَةِ"" : لَفُّها، إِدارتُها. 2"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23093, 'كَوَعٌ', 'كوع', 'مصدر', 'كوع', 'كوع', 'كع', 'مص. كَوِعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كَوَعٌ-كَوَعٌ [ك و ع] (مص. كَوِعَ). 1.""كَوَعُ اليَدِ"" : اِعْوِجَاجُهَا مِنْ قِبَلِ الكُوعِ أَوْ إِقْبَالُهَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23094, 'تَكْويمٌ', 'تكويم', 'مصدر', 'كوم', 'تكويم', 'تكم', 'مص. كَوَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْويمٌ-تَكْويمٌ [ك و م] (مص. كَوَّمَ). 1.""تَكْويمُ التُّرابِ"" : جَمْعُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23095, 'تَكْوينٌ', 'تكوين', 'مصدر', 'كون', 'تكوين', 'تكن', 'مص. كَوَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَكاوِينُ"', '', 'R', '', '', '', '', '', '', '"(مص. كَوَّنَ). 1.""جَميلُ التَّكْوينِ"" : جَميلُ الصُّورَةِ وَالهَيْأَةِ. 2.""تَكْوينُ العالَمِ كانَ بِإِرادَةِ الخالِقِ"" : خَلْقُهُ، أَيْ إِخْراجُهُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23096, 'تَكاوِينُ', 'تكاوين', 'مصدر', '', 'تكاوين', 'تكن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23097, 'كَيٌّ', 'كي', 'مصدر', 'كوي', 'كي', 'ك', 'مص. كَوَى', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"كَيٌّ-كَيٌّ [ك و ي] (مص. كَوَى). ""كَيُّ الجَسَدِ"" : إِحْرَاقُ الجِلْدِ بِحَدِيدَةٍ مُحَمَّاةٍ لِلْمُعَالَجَةِ أَوْ غَيْرِهَا. ""يُعَالِجُ النَّاسَ بِالكَيِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23098, 'كَآبَةٌ', 'كآبة', 'مصدر', 'كأب', 'كءءبة', 'كآبة', 'مص. كَئِبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"كَآبَةٌ-كَآبَةٌ [ك أ ب] (مص. كَئِبَ). ""اِرْتَسَمَتْ عَلَى مُحَيَّاهُ كَآبَةٌ سَوْدَاءُ"" : تَغَيُّرُ النَّفْسِ بِالانْكِسَارِ بِسَبَبِ حُزْنٍ وَهَمٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23099, 'تَكْيِيسٌ', 'تكييس', 'مصدر', 'كيس', 'تكييس', 'تكس', 'مص. كَيَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْيِيسٌ-تَكْيِيسٌ [ك ي س] (مص. كَيَّسَ). 1.""تَكْيِيسُ الوَلَدِ"": تَأْديبُهُ، جَعْلُهُ فَطِناً مُهَذَّباً. 2.""تَكْيِيسُ البَضائِعِ"" : جَعْلُها أَكْياساً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23100, 'تَكْيِيفٌ', 'تكييف', 'مصدر', 'كيف', 'تكييف', 'تكف', 'مص. كَيَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْيِيفٌ-تَكْيِيفٌ [ك ي ف] (مص. كَيَّفَ). ""بَلَغَتْ دَرَجَةُ تَكْيِيفِ الهَواءِ في الطَّائِرَةِ 19‌%"" : ضبْطُ الجِهازِ الهَوائِيِّ الْمُكَيَّفِ وَتَغْيِيرُهُ حَسَبَ دَرَجَةٍ مُعَيَّنَةٍ حارَّةٍ أَوْ بارِدَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23101, 'تَكْيِيلٌ', 'تكييل', 'مصدر', 'كيل', 'تكييل', 'تكل', 'مص. كَيَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَكْيِيلٌ-تَكْيِيلٌ [ك ي ل] (مص. كَيَّلَ). 1.""تَكْيِيلُ القَمْحِ"" : كَيْلُهُ. 2.""تَكْيِيلُ الحَقْلِ"" : قِياسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23102, 'مُلاَءمَةٌ', 'ملاءمة', 'مصدر', 'لأم', 'ملاءمة', 'ملمة', 'مص. لاَءمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلاَءمَةٌ-مُلاَءمَةٌ [ل أ م] (مص. لاَءمَ). ""وَجَدَ الأَعْمَالَ أَكْثَرَ مُلاَءمَةً لإِمْكَانَاتِهِ"" : أَكْثَرَ مُوَافَقَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23103, 'لُوَابٌ', 'لواب', 'مصدر', 'لوب', 'لواب', 'لب', 'مص. لاَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لُوَابٌ-لُوَابٌ [ل و ب] (مص. لاَبَ). ""لُوَابُ الطِّفْلِ"" : لُعَابُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23104, 'مُلاَبَسَةٌ', 'ملابسة', 'مصدر', 'لبس', 'ملابسة', 'ملبسة', 'مص. لاَبَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. لاَبَسَ). ""مُلاَبَسَاتُ الْحَادِثَةِ"" : ظُرُوفُهَا ومَا أَحَاطَ بِهَا مِنْ وَقَائِعَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23105, 'لَوْحٌ', 'لوح', 'مصدر', 'لوح', 'لوح', 'لح', 'مص. لاَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَلْوَاحٌ"', '', 'R', '', '', '', '', '', '', '"(مص. لاَحَ). 1. : خَشَبٌ أَوْ مَعْدِنٌ أَوْ عَظْمٌ. ""لَوْحُ الْكَتِفِ"" : عَظْمُهُ. 2.""اللَّوْحُ الْمَحْفُوظُ"" : مَا يُكْتَبُ فِيهِ وَيَظَلُّ مَصُوناً.البروج آية 21 ، 22بَلْ هُوَ قُرْآنٌ مَجِيدٌ فِي لَوْحٍ مَحْفُوظٍ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23106, 'أَلْوَاحٌ', 'ألواح', 'مصدر', '', 'ءلواح', 'لح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23107, 'لَوْحَةٌ', 'لوحة', 'مصدر', 'لوح', 'لوحة', 'لحة', 'مص. لاَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَلْوَاحٌ"', '', 'R', '', '', '', '', '', '', '"(مص. لاَحَ). 1. : خَشَبٌ أَوْ مَعْدِنٌ أَوْ عَظْمٌ. ""لَوْحُ الْكَتِفِ"" : عَظْمُهُ. 2.""اللَّوْحُ الْمَحْفُوظُ"" : مَا يُكْتَبُ فِيهِ وَيَظَلُّ مَصُوناً.البروج آية 21 ، 22بَلْ هُوَ قُرْآنٌ مَجِيدٌ فِي لَوْحٍ مَحْفُوظٍ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23108, 'أَلْوَاحٌ', 'ألواح', 'مصدر', '', 'ءلواح', 'لح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23109, 'مُلاَحَظَةٌ', 'ملاحظة', 'مصدر', 'لحظ', 'ملاحظة', 'ملحظة', 'مص. لاَحَظَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. لاَحَظَ). 1.""مُلاَحَظَةُ الشَّيْءِ"" : مُشَاهَدَتُهُ. 2.""قَدَّمَ مُلاَحَظَةً فِي مَحَلِّهَا"": كَلاَمٌ فِيهِ تَنْبِيهٌ أَوْ تَعْلِيقٌ عَلَى عَمَلٍ مَّا لإِعَادَةِ النَّظَرِ فِيهِ. ""كَانَتْ مُلاَحَظَاتُ الرَّئِيسِ عَلَى جَانِبٍ كَبِيرٍ مِنَ الأَهَمِّيَّةِ"". 3.""نَاقِدٌ دَقِيقُ الْمُلاَحَظَةِ"" : دَقِيقُ الاِنْتِبَاهِ والتَّمْيِيزِ. 4.""مُلاَحَظَةُ التَّجْرِبَةِ"" : مُعَايَنَتُهَا، مُرَاقَبَتُهَا. 5.""لاَحَظَهُ مُلاَحَظَةً مُرِيبَةً"" : نَظَرَ إِلَيْهِ نَظْرَةً لاَ يُحِبُّهَا الْمَنْظُورُ إِلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23110, 'مُلاَحَقَةٌ', 'ملاحقة', 'مصدر', 'لحق', 'ملاحقة', 'ملحقة', 'مص. لاَحَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. لاَحَقَ). 1.""مُلاَحَقَةُ الصَّيَّادِ لِصَيْدِهِ"" : مُطَارَدَتُهُ وتَعَقُّبُهُ. ""قَرَّرَ مُلاَحَقَةَ الْمُجْرِمِينَ"". 2.""مُلاَحَقَةٌ قَضَائِيَّةٌ"" : مُتَابَعَةٌ ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23111, 'لِحَاءٌ', 'لحاء', 'مصدر', 'لحي', 'لحاء', 'لح', 'مص. لاَحَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"لِحَاءٌ-لِحَاءٌ [ل ح ي] (مص. لاَحَى). ""لِحَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23112, 'لَوْذٌ', 'لوذ', 'مصدر', 'لوذ', 'لوذ', 'لذ', 'مص. لاَذَ', '', '', 'مفرد', 'DnN', '', '', '"أَلْوَاذٌ"', '', 'R', '', '', '', '', '', '', '"(مص. لاَذَ). 1.""لَوْذُ الْجَبَلِ"": جَانِبُهُ. 2.""لَوْذُ الوَادِي"" : مُنْعَطَفُهُ. 3.""طَافَ فِي أَلْوَاذِ الْمَدِينَةِ"": فِي نَوَاحِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23113, 'أَلْوَاذٌ', 'ألواذ', 'مصدر', '', 'ءلواذ', 'لذ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23114, 'مُلاَزَمَةٌ', 'ملازمة', 'مصدر', 'لزم', 'ملازمة', 'ملزمة', 'مص. لاَزَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلاَزَمَةٌ-مُلاَزَمَةٌ [ل ز م] (مص. لاَزَمَ). 1.""مُلاَزَمَةُ العَمَلِ"" : الْمُدَاوَمَةُ عَلَيْهِ. 2.""مُلاَزَمَةُ الصَّدِيقِ"" : التَّعَلُّقُ بِهِ وعَدَمُ مُفَارَقَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23115, 'لِزَامٌ', 'لزام', 'مصدر', 'لزم', 'لزام', 'لزم', 'مص. لاَزَمَ، لَزِمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لِزَامٌ-لِزَامٌ [ل ز م] (مص. لاَزَمَ، لَزِمَ). ""كَانَ لِزَاماً عَلَيْهِ أَنْ يَخ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23116, 'لَوْطٌ', 'لوط', 'مصدر', 'لوط', 'لوط', 'لط', 'مص. لاَطَ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"لَوْطٌ-لَوْطٌ [ل و ط] (مص. لاَطَ). 1.""اِرْتَدَى لَوْطَهُ"" : رِدَاءهُ. 2.""وَرَقٌ لَوْطٌ"" : لاَزِقٌ. ""إِنِّي لَأَجِدُ فِي قَلْبِي لَوْطاً"": حُبّاً لاَزِقاً بِقَلْبِي. 3.""رَجُلٌ لَوْطٌ"" : ضَعِيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23117, 'مُلاَطَفَةٌ', 'ملاطفة', 'مصدر', 'لطف', 'ملاطفة', 'ملطفة', 'مص. لاَطَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. لاَطَفَ). ""يَهْتَمُّ بِمُلاَطَفَةِ النَّاسِ"" : بِحُسْنِ مُعَامَلَتِهِمْ، مُدَاعَبَتِهِمْ، مُصَانَعَتِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23118, 'لِيَاقَةٌ', 'لياقة', 'مصدر', 'ليق', 'لياقة', 'لقة', 'مص. لاَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لِيَاقَةٌ-لِيَاقَةٌ [ل ي ق] (مص. لاَقَ). 1.""تَحَدَّثَ مَعَهُ بِلِيَاقَةٍ"": بِأَدَبٍ وَسُلُوكٍ وَمُعَامَلَةٍ حَسَنَةٍ. ""بَالَغَ كَثِيراً فِي إِظْهَارِ عَلاَمَاتِ الأَدَبِ وَاللِّيَاقَةِ"". (جمال الغيطاني). 2.""لاَعِبٌ ذُو لِيَاقَةٍ بَدَنِيَّةٍ"" : أَيْ جِسْمُهُ فِيهِ تَنَاسُبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23119, 'تَلْبيبٌ', 'تلبيب', 'مصدر', 'لبب', 'تلبيب', 'تلبب', 'مص. لَبَّبَ', '', '', 'مفرد', 'DnN', '', '', '"تَلابِيبُ"', '', 'R', '', '', '', '', '', '', '"(مص. لَبَّبَ). ""أَخَذَ بِتَلابِيبِهِ وَطَرَحَهُ أَرْضاً"" : أَخَذَهُ مِنْ طَوْقِ ثَوْبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23120, 'مُلاَقَاةٌ', 'ملاقاة', 'مصدر', 'لقي', 'ملاقاة', 'ملقة', 'مص. لاَقَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلاَقَاةٌ-مُلاَقَاةٌ [ل ق ي] (مص. لاَقَى). ""اِتَّفَقُوا عَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23121, 'مُلاَكَمَةٌ', 'ملاكمة', 'مصدر', 'لكم', 'ملاكمة', 'ملكمة', 'مص. لاَكَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُلاَكَمَةٌ-مُلاَكَمَةٌ [ل ك م] (مص. لاَكَمَ). : لُعْبَةٌ رِيَاضِيَّةٌ يَتَلاَكَمُ فِيهَا الْمُلاَكِمَانِ وَجْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23122, 'لَوْمٌ', 'لوم', 'مصدر', 'لوم', 'لوم', 'لم', 'مص. لاَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَوْمٌ-لَوْمٌ [ل و م] (مص. لاَمَ). ""كَانَ لَوْمُهُ عَنِيفاً"" : تَوْبِيخُهُ، عَذْلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23123, 'مَلاَمَةٌ', 'ملامة', 'مصدر', 'لوم', 'ملامة', 'ملمة', 'مص. لاَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَلاَمَةٌ-مَلاَمَةٌ [ل و م] (مص. لاَمَ). ""أَتَى مَا اسْتَحَقَّ عَلَيْهِ الْمَلاَمَةَ"" : اللَّوْمَ، العِتَابَ. ""إِنَّ الْمَلاَمَةَ لاَ تَمِيلُ بِالقَلْبِ عَنِ الْحُبِّ"". (جبران خ. جبران) l يَا صَاح!لَيْسَ عَلَى الْمُحِبِّ مَلاَمَة*إِنْ لاَحَ فِي أُفُقِ الوِصَالِ صَبَاحُ (السهروردي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23124, 'مَلاَمٌ', 'ملام', 'مصدر', 'لوم', 'ملام', 'ملم', 'مص. لاَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَلاَمٌ-مَلاَمٌ [ل و م] (مص. لاَمَ). ""كَانَ مَلاَمُهُ شَدِيداً"" : لَوْمُهُ. أُلاَمُ عَلَى التَّعَرُّضِ لِلْمَنَـايَـا*ولِي سَمْعٌ أَصَـمُّ عَـنِ الْمَــلاَمِ (أبو فراس الحمداني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23125, 'مُلاَمَسَةٌ', 'ملامسة', 'مصدر', 'لمس', 'ملامسة', 'ملمسة', 'مص. لاَمَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. لاَمَسَ). 1.""مُلاَمَسَةُ الجِدَارِ"" : مَسُّهُ. 2. ""مُلاَمَسَةُ الْحَقِيقَةِ"" : الوُقُوفُ عَلَيْهَا. 3. ""مُلاَمَسَةُ الْمَرْأَةِ"" : مُجَامَعَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23126, 'لِينٌ', 'لين', 'مصدر', 'لين', 'لين', 'لن', 'مص. لاَنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لِينٌ-لِينٌ، ةٌ [ل ي ن] (مص. لاَنَ). 1.""عَامَلَهُ بِاللِّينِ"" : بِاللُّطْفِ وَالنُّعُومَةِ وَالْيُسْرِ. 2.""لِينُ الطَّبْعِ"" : هُدُوءُ الطَّبْعِ وَالْمُعَاشَرَةِ. ""لِينُ الْجَانِبِ"" ""لِينُ الْكَلاَمِ قَيْدُ الْقُلُوبِ"". 3.""حُرُوفُ اللِّينِ"" : هِيَ الأَلِفُ وَالْوَاوُ وَالْيَاءُ، الصَّوَائِتُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23127, 'لِينَةٌ', 'لينة', 'مصدر', 'لين', 'لينة', 'لنة', 'مص. لاَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لِينٌ-لِينٌ، ةٌ [ل ي ن] (مص. لاَنَ). 1.""عَامَلَهُ بِاللِّينِ"" : بِاللُّطْفِ وَالنُّعُومَةِ وَالْيُسْرِ. 2.""لِينُ الطَّبْعِ"" : هُدُوءُ الطَّبْعِ وَالْمُعَاشَرَةِ. ""لِينُ الْجَانِبِ"" ""لِينُ الْكَلاَمِ قَيْدُ الْقُلُوبِ"". 3.""حُرُوفُ اللِّينِ"" : هِيَ الأَلِفُ وَالْوَاوُ وَالْيَاءُ، الصَّوَائِتُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23128, 'لَوْهٌ', 'لوه', 'مصدر', 'لوه', 'لوه', 'له', 'مص. لاَهَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَوْهٌ-لَوْهٌ [ل و هـ] (مص. لاَهَ). ""رَأَيْتُ لَوْهَ السَّرَابِ"" : بَرِيقَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23129, 'لَبْكٌ', 'لبك', 'مصدر', 'لبك', 'لبك', 'لبك', 'مص. لَبَكَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَبْكٌ-لَبْكٌ [ل ب ك] (مص. لَبَكَ). ""لَبَنٌ لَبْكٌ"" : مَخْلُوطٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23130, 'تَلابِيبُ', 'تلابيب', 'مصدر', '', 'تلابيب', 'تلبب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23131, 'تَلْبيثٌ', 'تلبيث', 'مصدر', 'لبث', 'تلبيث', 'تلبث', 'مص. لَبَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْبيثٌ-تَلْبيثٌ [ل ب ث] (مص. لَبَّثَ). ""تَلْبِيثُهُ في غُرْفَةٍ مُجاوِرَةٍ"" : جَعْلُهُ يُقيمُ فيها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23132, 'تَلْبيدٌ', 'تلبيد', 'مصدر', 'لبد', 'تلبيد', 'تلبد', 'مص. لَبَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْبيدٌ-تَلْبيدٌ [ل ب د] (مص. لَبَّدَ). ""تَلْبيدُ الصُّوفِ"" : لَبْدُهُ، جَعْلُهُ يَتَلَبَّدُ، تَبْليلُهُ بِالماءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23133, 'لَبَدٌ', 'لبد', 'مصدر', 'لبد', 'لبد', 'لبد', 'مص. لَبَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَبِدٌ-لَبِدٌ [ل ب د] (صِيغَةُ فَعِل). 1.""شَعْرٌ لَبِدٌ"" : شَعْرٌ مُتَلَبِّدٌ. 2.""رَجُلٌ لَبِدٌ"" : قَاعِدٌ فِي مَنْزِلِهِ لاَ يَتْرُكُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23134, 'تَلْبيسٌ', 'تلبيس', 'مصدر', 'لبس', 'تلبيس', 'تلبس', 'مص. لَبَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْبيسٌ-تَلْبيسٌ [ل ب س] (مص. لَبَّسَ). 1.""تَلْبيسُ أَمْرٍ"" : جَعْلُهُ مُلْتَبِساً غاضِباً. 2.""تَلْبيسُهُ تُهْمَةً"" : إِلْحاقُها بِهِ كَذِباً وَبُهْتاناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23135, 'لَبْسٌ', 'لبس', 'مصدر', 'لبس', 'لبس', 'لبس', 'مص. لَبَسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَبْسٌ-لَبْسٌ [ل ب س] (مص. لَبَسَ). 1.""اِكْتَنَفَهُ اللَّبْسُ"" : اِخْتِلاَطُ الظَّلاَمِ. 2.""فِي الأَمْرِ لَبْسٌ"" : شُبْهَةٌ وَعَدَمُ وُضُوحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23136, 'لُبْسٌ', 'لبس', 'مصدر', 'لبس', 'لبس', 'لبس', 'مص. لَبِسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لُبْسٌ-لُبْسٌ، ةٌ [ل ب س] (مص. لَبِسَ). 1.""قَضِيَّةٌ يُحِيطُ بِهَا اللُّبْسُ"" : الغُمُوضُ، الشُّبْهَةُ، عَدَمُ الوُضُوحِ. 2.""فِي الأَمْرِ لُبْسَةٌ"" : شُبْهَةٌ وَاخْتِلاَطٌ وَعَدَمُ وُضُوحٍ. 3.""لَمْ يُلاَحِظْ فِي تَصَرُّفَاتِهِ أَيَّ لُبْسَةٍ"" : أَيَّ شُبْهَةٍ أَوْ غُمُوضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23137, 'لُبْسَةٌ', 'لبسة', 'مصدر', 'لبس', 'لبسة', 'لبسة', 'مص. لَبِسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لُبْسٌ-لُبْسٌ، ةٌ [ل ب س] (مص. لَبِسَ). 1.""قَضِيَّةٌ يُحِيطُ بِهَا اللُّبْسُ"" : الغُمُوضُ، الشُّبْهَةُ، عَدَمُ الوُضُوحِ. 2.""فِي الأَمْرِ لُبْسَةٌ"" : شُبْهَةٌ وَاخْتِلاَطٌ وَعَدَمُ وُضُوحٍ. 3.""لَمْ يُلاَحِظْ فِي تَصَرُّفَاتِهِ أَيَّ لُبْسَةٍ"" : أَيَّ شُبْهَةٍ أَوْ غُمُوضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23138, 'لَبَاقَةٌ', 'لباقة', 'مصدر', 'لبق', 'لباقة', 'لبقة', 'مص. لَبُقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَبَاقَةٌ-لَبَاقَةٌ [ل ب ق] (مص. لَبُقَ). ""تَكَلَّمَ بِلَبَاقَةٍ"" : بِحِذْقٍ، بِلُطْفٍ، بِكِيَاسَةٍ. ""أَظْهَرَ مَعْرِفَةً وَلَبَاقَةً فِي الْمُفَاوَضَاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23139, 'لَحْدٌ', 'لحد', 'مصدر', 'لحد', 'لحد', 'لحد', 'مص. لَحَدَ', '', '', 'مفرد', 'DnN', '', '', '"أَلْحَادٌ:لُحُودٌ"', '', 'R', '', '', '', '', '', '', '"(مص. لَحَدَ). ""حَفَرَ لَهُ لَحْدَهُ"" : قَبْرَهُ. اُطْلُبُوا العِلْمَ مِنَ الْمَهْدِ إِلَى اللَّحْدِ (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23140, 'لَبْلَبَةٌ', 'لبلبة', 'مصدر', 'لبلب', 'لبلبة', 'لبلبة', 'مص. لَبْلَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَبْلَبَةٌ-لَبْلَبَةٌ [ل ب ل ب] (مص. لَبْلَبَ). 1.""لَبْلَبَةُ الشَّاةِ"" : إِخْرَاجُهَا لِلِسَانِهَا لِلَحْسِ وَلَدِهَا رِقَّةً بِهِ. 2.""هُوَ ذُو لَبْلَبَةٍ"" : ذُو شَفَقَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23141, 'لَبَبٌ', 'لبب', 'مصدر', 'لبب', 'لبب', 'لب', 'مص. لَبَّ، لَبِبَ', '', '', 'مفرد', 'DnN', '', '', '"أَلْبَابٌ"', '', 'R', '', '', '', '', '', '', '"(مص. لَبَّ، لَبِبَ). 1. : مَوْضِعُ القِلاَدَةِ مِنَ الصَّدْرِ. 2.""إِنَّهُ لَرَخِيُّ اللَّبَبِ"" : أَي البَالِ. 3.""هُوَ فِي لَبَبٍ رَخِيٍّ"" : فِي سَعَةِ عَيْشٍ وَخِصْبٍ وَأَمْنٍ. 4.""لَبَبُ الدَّابَّةِ"" : مَا يُشَدُّ عَلَى صَدْرِهَا مِنْ سُيُورِ السَّرْجِ لِيَمْنَعَ تَأَخُّرَ الرَّحْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23142, 'أَلْبَابٌ', 'ألباب', 'مصدر', '', 'ءلباب', 'لبب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23143, 'تَلْبيَةٌ', 'تلبية', 'مصدر', 'لبي', 'تلبية', 'تلبة', 'مص. لَبَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَلْبيَةٌ-تَلْبيَةٌ [ل ب ي] (مص. لَبَّى). ""حَضَرَ تَلْبِيَةً لِرَغْبَتِهِ"" : اِسْتِجابَةً لَها. ""لاَبُدَّ مِنْ تَلْبِيَةِ دَعْوَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23144, 'تَلْثيمٌ', 'تلثيم', 'مصدر', 'لثم', 'تلثيم', 'تلثم', 'مص. لَثَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْثيمٌ-تَلْثيمٌ [ل ث م] (مص. لَثَّمَ). ""تَلْثيمُ الوَجْهِ"" : شَدُّ اللِّثامِ عَلَيْهِ بِوَضْعِهِ على أَنْفِهِ وَما حَوْلَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23145, 'لَثْمٌ', 'لثم', 'مصدر', 'لثم', 'لثم', 'لثم', 'مص. لَثَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَثْمٌ-لَثْمٌ [ل ث م] (مص. لَثَمَ). ""لَثْمُ الْخَدِّ"" : تَقْبِيلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23146, 'لَجَاجَةٌ', 'لجاجة', 'مصدر', 'لجج', 'لجاجة', 'لججة', 'مص. لَجَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَجَاجَةٌ-لَجَاجَةٌ [ل ج ج] (مص. لَجَّ). 1.""لَجَاجَةُ القَوْلِ"" : الإِلْحَاحُ، العِنَادُ. 2.""فِي فُؤَادِهِ لَجَاجَةٌ"" : خَفَقَانٌ مِنَ الْجُوعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23147, 'لُجُوءٌ', 'لجوء', 'مصدر', 'لجأ', 'لجوء', 'لج', 'مص. لَجَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"لُجُوءٌ-لُجُوءٌ [ل ج أ] (مص. لَجَأَ). 1.""لَمْ يَكُنْ أَمَامَهُ إِلاَّ اللُّجُوءُ إِلَى العَدَالَةِ"" : الالْتِجَاءُ. 2.""حَقُّ اللُّجُوءِ السِّيَاسِيِّ"" : حَقُّ الالْتِجَاءِ وَالاحْتِمَاءِ بِبَلَدٍ لِكُلِّ إِنْسَانٍ غَادَرَ بِلاَدَهُ مُكْرَهاً وَمُضْطَرّاً خَوْفاً مِنَ الاضْطِهَادِ بِسَبَبِ أَفْكَارِهِ وَآرَائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23148, 'لَجَبٌ', 'لجب', 'مصدر', 'لجب', 'لجب', 'لجب', 'مص. لَجِبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَجَبٌ-لَجَبٌ [ل ج ب] (مص. لَجِبَ). 1.""أَسْمَعُ لَجَبَهُمْ مِنْ بَعِيدٍ"" : أَيْ أَصْوَاتَهُمُ الْمُرْتَفِعَةَ الْمُخْتَلِطَةَ. 2.""بَحْرٌ ذُو لَجَبٍ"" : أَمْوَاجُهُ مُضْطَرِبَةٌ، مُلْتَطِمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23149, 'لَحْنٌ', 'لحن', 'مصدر', 'لحن', 'لحن', 'لحن', 'مص. لَحَنَ', '', '', 'مفرد', 'DnN', '', '', '"أَلْحَانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. لَحَنَ). 1.""يَعْرِفُ لَحْنَهُ"" : لُغَتَهُ. ""هَذَا كَلاَمٌ لَيْسَ مِنْ لَحْنِي وَلاَ مِنْ لَحْنِ قَوْمِي"". 2.""لَحْنُ القَوْلِ"" : فَحْوَاهُ.محمد آية 30 وَلَتَعْرِفَنَّهُمْ فِي لَحْنِ القَوْلِ (قرآن). 3.""قَلِيلاً مَا يَصْدُرُ عَنْهُ لَحْنٌ"" : خَطَأٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23150, 'أَلْحَادٌ', 'ألحاد', 'مصدر', '', 'ءلحاد', 'لحد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23151, 'لُحُودٌ', 'لحود', 'مصدر', '', 'لحود', 'لحد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23152, 'لَحْظٌ', 'لحظ', 'مصدر', 'لحظ', 'لحظ', 'لحظ', 'مص. لَحَظَ.', '', '', 'مفرد', 'DnN', '', '', '"لِحَاظٌ"', '', 'Rp', '', '', '', '', '', '', '"ج: لِحَاظٌ. (مص. لَحَظَ). 1.""لَمْ يَكُنْ لَحْظُهُ دَقِيقاً"" : مُرَاقَبَتُهُ، مُلاَحَظَتُهُ. 2.""فِي لَحْظِهِ بَيَاضٌ"" : بَاطِنُ العَيْنِ، غِشَاءُ مُقْلَةِ العَيْنِ الْخَارِجِيُّ. 3.""عَبَّرَ بِلَحْظِهِ عَمَّا يُرِيدُ قَوْلَهُ"" : بِغَمْزَتِهِ، حَرَكَةُ العَيْنِ. ""اِمْتَلأَ لِحَاظُهَا فُتُوناً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23153, 'لِحَاظٌ', 'لحاظ', 'مصدر', '', 'لحاظ', 'لحظ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23154, 'لِحَاقٌ', 'لحاق', 'مصدر', 'لحق', 'لحاق', 'لحق', 'مص. لَحَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لِحَاقٌ-لِحَاقٌ [ل ح ق] (مص. لَحَقَ). ""حَاوَلَ اللِّحَاقَ بِهِ"" : إِدْرَاكَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23155, 'لَحْمٌ', 'لحم', 'مصدر', 'لحم', 'لحم', 'لحم', 'مص. لَحَمَ', '', '', 'مفرد', 'DnN', '', '', '"لُحُومٌ"', '', 'R', '', '', '', '', '', '', '"(مص. لَحَمَ). ""لَحْمُ الْمَعَادِنِ"" : لَأْمُهَا، أَيْ لَصْقُهَا، لَزْقُهَا بِاسْتِخْدَامِ اللِّحَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23156, 'لُحُومٌ', 'لحوم', 'مصدر', '', 'لحوم', 'لحم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23157, 'تَلْحينٌ', 'تلحين', 'مصدر', 'لحن', 'تلحين', 'تلحن', 'مص. لَحَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَلاحِينُ"', '', 'R', '', '', '', '', '', '', '"(مص. لَحَّنَ). 1.""أُغْنِيَةٌ مِنْ تَلْحينِ الموسيقار"" : ضَبْطِ وَوَضْعِ أَن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23158, 'تَلاحِينُ', 'تلاحين', 'مصدر', '', 'تلاحين', 'تلحن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23159, 'لَدَدٌ', 'لدد', 'مصدر', 'لدد', 'لدد', 'لد', 'مص. لَدَّ يَلَدُّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَدَدٌ-لَدَدٌ [ل د د] (مص. لَدَّ يَلَدُّ). ""اِسْتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23160, 'أَلْحَانٌ', 'ألحان', 'مصدر', '', 'ءلحان', 'لحن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23161, 'لَحَنٌ', 'لحن', 'مصدر', 'لحن', 'لحن', 'لحن', 'مص. لَحِنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَحَنٌ-لَحَنٌ [ل ح ن] (مص. لَحِنَ). 1.""فَهِمَ لَحَنَهُ"" : لُغَتَهُ. ""إِنَّ الق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23162, 'لَحْيٌ', 'لحي', 'مصدر', 'لحي', 'لحي', 'لح', 'مص. لَحَى', '', '', 'مفرد', 'DnN', '', '', '"أَلْحٍ:لُحِيٌّ:لِحَاءٌ"', '', '', '', '', '', '', '', '', '"(مص. لَحَى). 1. : مَنْبِتُ اللِّحْيَةِ وَهُمَا لَحْيَانِ. 2.: عَظْمَا ا"', '');
