INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23166, 'تَلْخيصٌ', 'تلخيص', 'مصدر', 'لخص', 'تلخيص', 'تلخص', 'مص. لَخَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَلْخيصٌ-تَلْخيصٌ [ل خ ص] (مص. لَخَّصَ). ""تَلْخيصُ الد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23167, 'لَدْغٌ', 'لدغ', 'مصدر', 'لدغ', 'لدغ', 'لدغ', 'مص. لَدَغَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَدْغٌ-لَدْغٌ [ل د غ] (مص. لَدَغَ)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23168, 'تَلْدينٌ', 'تلدين', 'مصدر', 'لدن', 'تلدين', 'تلدن', 'مص. لَدَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْدينٌ-تَلْدينٌ [ل د ن] (مص. لَدَّنَ). 1.""تَلْدينُ مَعْدِنٍ"": تَلْيينُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23169, 'لَسْنٌ', 'لسن', 'مصدر', 'لسن', 'لسن', 'لسن', 'مص. لَسَنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَسْنٌ-لَسْنٌ [ل س ن] (مص. لَسَنَ). 1.""لَسْنُهُ فَصِيحٌ"" : لُغَتُهُ. ""لِكُلِّ قَوْمٍ لَسْنٌ"". 2.""لَسْنُهُ سَلِيطٌ"" : لِسَانُهُ. 3.""أَتَى بِلَسْنٍ جَمِيلٍ"" : بِكَلاَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23170, 'لَذٌّ', 'لذ', 'مصدر', 'لذذ', 'لذ', 'لذ', 'مص. لَذَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَذٌّ-لَذٌّ، ةٌ [ل ذ ذ] (مص. لَذَّ). 1.""شَرَابٌ لَذٌّ"" : لَذِيذٌ شَهِيٌّ.محمد آية 15 وَأَنْهَارٌ مِنْ خَمْرٍ لَذَّةٍ لِلشَّارِبِينَ (قرآن) ""عَيْشٌ لَذٌّ"". 2.""رَجُلٌ لَذٌّ"" : طَيِّبُ الْحَدِيثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23171, 'لَذَّةٌ', 'لذة', 'مصدر', 'لذذ', 'لذة', 'لذة', 'مص. لَذَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَذٌّ-لَذٌّ، ةٌ [ل ذ ذ] (مص. لَذَّ). 1.""شَرَابٌ لَذٌّ"" : لَذِيذٌ شَهِيٌّ.محمد آية 15 وَأَنْهَارٌ مِنْ خَمْرٍ لَذَّةٍ لِلشَّارِبِينَ (قرآن) ""عَيْشٌ لَذٌّ"". 2.""رَجُلٌ لَذٌّ"" : طَيِّبُ الْحَدِيثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23172, 'تَلْذيذٌ', 'تلذيذ', 'مصدر', 'لذذ', 'تلذيذ', 'تلذذ', 'مص. لَذَّذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْذيذٌ-تَلْذيذٌ [ل ذ ذ] (مص. لَذَّذَ). ""تَلْذيذُ الضُّيوفِ بِالطَّعامِ"": جَعْلُهُمْ يَتَلَذَّذونَ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23173, 'لَذْعٌ', 'لذع', 'مصدر', 'لذع', 'لذع', 'لذع', 'مص. لَذَعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَذْعٌ-لَذْعٌ [ل ذ ع] (مص. لَذَعَ). 1.""لَذْعُ الْحَرَارَةِ"" : لَفْحُهَا. 2.""لَذْعُ الْحُبّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23174, 'تَلْزيقٌ', 'تلزيق', 'مصدر', 'لزق', 'تلزيق', 'تلزق', 'مص. لَزَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْزيقٌ-تَلْزيقٌ [ل ز ق] (مص. لَزَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23175, 'لُزُوقٌ', 'لزوق', 'مصدر', 'لزق', 'لزوق', 'لزق', 'مص. لَزِقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لُزُوقٌ - [ل ز ق]. (مص. لَزِقَ). ""لُزُوقُ الوَرَقِ"" : لَصْقُهُ بِلِصَاقٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23176, 'لُزُومٌ', 'لزوم', 'مصدر', 'لزم', 'لزوم', 'لزم', 'مص. لَزِمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لُزُومٌ-لُزُومٌ [ل ز م] (مص. لَزِمَ). ""اِحْتَفِظْ بِمَالِكَ لِوَقْتِ اللُّزُومِ"" : لِوَقْتِ الْح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23177, 'لَسْعٌ', 'لسع', 'مصدر', 'لسع', 'لسع', 'لسع', 'مص. لَسَعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَسْعٌ-لَسْعٌ [ل س ع] (مص. لَسَعَ). ""لَسْعُ العَقْرَبِ"" : لَدْغُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23178, 'تَلْسينٌ', 'تلسين', 'مصدر', 'لسن', 'تلسين', 'تلسن', 'مص. لَسَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْسينٌ-تَلْسينٌ [ل س ن] (مص. لَسَّنَ). 1.""تَلْسينُ حَديدَةٍ"" : جَعْلُ طَرفِها كَطَرَفِ اللِّسانِ. 2.""تَلْسينُ اللِّسَانِ"" : عَضُّهُ تَحَيُّراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23179, 'تَلْعيقٌ', 'تلعيق', 'مصدر', 'لعق', 'تلعيق', 'تلعق', 'مص. لَعَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْعيقٌ-تَلْعيقٌ [ل ع ق] (مص. لَعَّقَ). ""تَلْعيقُهُ العَسَلَ"" : جَعْلُهُ يَلْعَقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23180, 'لَسَنٌ', 'لسن', 'مصدر', 'لسن', 'لسن', 'لسن', 'مص. لَسِنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَسِنٌ-لَسِنٌ [ل س ن] (صِيغَةُ فَعِل). ""خَطِيبٌ لَسِنٌ"": فَصِيحٌ، بَلِيغٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23181, 'تَلْطيخٌ', 'تلطيخ', 'مصدر', 'لطخ', 'تلطيخ', 'تلطخ', 'مص. لَطَّخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْطيخٌ-تَلْطيخٌ [ل ط خ] (مص. لَطَّخَ). 1.""تَلْطيخُ الثَّوْبِ"" : تَوْسيخُهُ. 2.""تَلْطيخُ السُّمْعَةِ"" : الحَطُّ مِنْها، تَلْويثُها. 3.""التَّلْطيخُ بِالنَّجاسَةِ"" : التَّلْويثُ، التَّدْنيسُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23182, 'لَطْخٌ', 'لطخ', 'مصدر', 'لطخ', 'لطخ', 'لطخ', 'مص. لَطَخَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَطْخٌ-لَطْخٌ [ل ط خ] (مص. لَطَخَ). 1.""لَطْخٌ مِنْ سَائِلٍ"" : قَلِيلٌ مِنْهُ. ""فِي السَّمَاءِ لَطْخٌ مِنْ سَحَابٍ"". 2.""سَمِعْتُ لَطْخاً مِنْ خَبَرٍ"" : جُزْءاً يَسِيراً مِنْهُ. 3.""وَلَدٌ لَطْخٌ"" : أَحْمَقُ، بَلِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23183, 'تَلْطيفٌ', 'تلطيف', 'مصدر', 'لطف', 'تلطيف', 'تلطف', 'مص. لَطَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْطيفُ-تَلْطيفُ [ل ط ف] (مص. لَطَّفَ). 1.""تَلْطيفُ الكَلامِ"": جَعْلُهُ رَقيقاً لا جَفاءَ فيهِ. 2.""حاوَلَ التَّلْطيفَ بِحالِهِ"": الرِّفْقَ بِهِ. 3.""تَلْطيفُ الجَوِّ"" : تَلْيِينُهُ، جَعْلُهُ حَسَناً لَطيفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23184, 'لَطَافَةٌ', 'لطافة', 'مصدر', 'لطف', 'لطافة', 'لطفة', 'مص. لَطُفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَطَافَةٌ-لَطَافَةٌ [ل ط ف] (مص. لَطُفَ). ""خَاطَبَهُ بِلَطَافَةٍ"" : بِرِقَّةٍ، بِلُطْفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23185, 'لَظىً', 'لظى', 'مصدر', 'لظي', 'لظى', 'لظ', 'مص. لَظِيَ', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"لَظىً-لَظىً [ل ظ ي] (مص. لَظِيَ). 1.""لَظَى النَّارِ"" : لَهِيبُهَا. 2.المعارج آية 15 ، 16كَلاَّ إِنَّهَا لَظىً نَزَّاعَةٌ لِلشَّوَى (قرآن) : اِسْمٌ لِجَهَنَّمَ لِأَنَّهَا تَتَلَظَّى، تَلْتَهِبُ عَلَى الكُفَّارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23186, 'لَعِبٌ', 'لعب', 'مصدر', 'لعب', 'لعب', 'لعب', 'مص. لَعِبَ', '', '', 'مفرد', 'DnN', '', '', '"أَلْعَابٌ"', '', 'R', '', '', '', '', '', '', '"(مص. لَعِبَ). 1.""يَقْضِي وَقْتَهُ فِي اللَّعِبِ"" : فِي اللَّهْوِ وَالتَّسْلِيَةِ. 2.""اِتَّخَذَهُ لَعِباً"" : سُخْرِيَةً.‎الأنعام آية 70وَذَرِ الَّذِينَ اتَّخَذُوا دِينَهُمْ لَعِباً وَلَهْواً (قرآن). 3.""لَعِبُ كُرَةِ ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23187, 'أَلْعَابٌ', 'ألعاب', 'مصدر', '', 'ءلعاب', 'لعب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23188, 'لَعْجٌ', 'لعج', 'مصدر', 'لعج', 'لعج', 'لعج', 'مص. لَعَجَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَعْجٌ-لَعْجٌ [ل ع ج] (مص. لَعَجَ). 1.""لَعْجُ الضَّرْبِ"" : أَلَمُهُ. 2.""لَعْجُ الْجِلْدِ"" : حُرْقَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23189, 'لَقٌّ', 'لق', 'مصدر', 'لقق', 'لق', 'لق', 'مص. لَقَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَقٌّ-لَقٌّ [ل ق ق] (مص. لَقَّ). 1.""أَحْدَثَ السَّيْلُ لَقّا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23190, 'لُعْقَةٌ', 'لعقة', 'مصدر', 'لعق', 'لعقة', 'لعقة', 'مص. لَعِقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لُعْقَةٌ-لُعْقَةٌ [ل ع ق] (مص. لَعِقَ). 1. : مَا يُؤْخَذُ بِالْمِلْعَق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23191, 'لَعْقَةٌ', 'لعقة', 'مصدر', 'لعق', 'لعقة', 'لعقة', 'مص. لَعِقَ الْمَرَّةُ مِنْ لَع', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَعْقَةٌ-لَعْقَةٌ [ل ع ق] (مص. لَعِقَ) (الْمَرَّةُ مِنْ لَعِقَ). 1.""لَعْقَةُ العَسَلِ"" : مَا يُلْعَقُ بِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23192, 'لَغْوٌ', 'لغو', 'مصدر', 'لغو', 'لغو', 'لغ', 'مص. لَغَا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَغْوٌ-لَغْوٌ [ل غ و] (مص. لَغَا). ""لاَ يَتَوَقَّفُ عَنِ اللَّغْوِ"" : عَنِ الْكَلاَمِ الَّذِي لاَ فَائِدَةَ مِنْهُ. ""خَلَدُوا إِلَى الرَّاحَةِ بَعْدَ أَنْ مَلُّوا لَغْوَهُمُ الَّذِي لاَ طَائِلَةَ تَحْتَهُ"" ""إِنَّ الْحَيَاةَ لَغْوٌ إِذَا لَمْ تُغَذَّ بِنُبْلِ الأَدَبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23193, 'لَغْطٌ', 'لغط', 'مصدر', 'لغط', 'لغط', 'لغط', 'مص. لَغَطَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَغْطٌ-لَغْطٌ [ل غ ط] (مص. لَغَطَ). ""كَثُرَ اللَّغْطُ فِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23194, 'لَغَا', 'لغا', 'مصدر', 'لغو', 'لغا', 'لغ', 'مص. لَغِيَ', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"لَغَا-لَغَا [ل غ و] (مص. لَغِيَ). 1.""تَرَدَّدَ اللَّغَا"" : الصَّوْتُ. 2.""تَكَلَّمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23195, 'لَفٌّ', 'لف', 'مصدر', 'لفف', 'لف', 'لف', 'مص. لَفَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَفٌّ-لَفٌّ [ل ف ف] (مص. لَفَّ). 1.""أَعْيَاهُ اللَّفُ"" : الدَّوَرَانُ، الْمُرَاوَغَةُ. ""اللَّفُّ وَالدَّوَرَانُ"". 2.""عَرَفَ اللُّصُوصَ وَمَنْ لَفَّ لَفَّهُمْ"" : مَنْ كَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23196, 'لَفْحٌ', 'لفح', 'مصدر', 'لفح', 'لفح', 'لفح', 'مص. لَفَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَفْحٌ-لَفْحٌ [ل ف ح] (مص. لَفَحَ). ""أَصَابَهُ لَفْحُ الصَّيْفِ"" : رِيحُهُ الْحَارَّةُ وَالشَّدِيدَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23197, 'تَلْفيقٌ', 'تلفيق', 'مصدر', 'لفق', 'تلفيق', 'تلفق', 'مص. لَفَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْفيقٌ-تَلْفيقٌ [ل ف ق] (مص. لَفَّقَ). 1.""كَلامٌ كُلُّهُ تَلْفيقٌ"": كَلا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23198, 'لَفَفٌ', 'لفف', 'مصدر', 'لفف', 'لفف', 'لف', 'مص. لَفَّ يَلِفُّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَفَفٌ-لَفَفٌ [ل ف ف] (مص. لَفَّ يَلِفُّ). 1.""لَفَفُ عِرْقِ السَّاعِدِ"" : اِلْتِوَاؤُهُ. 2.""رَأَى النَّاسَ فِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23199, 'تَلْقيبٌ', 'تلقيب', 'مصدر', 'لقب', 'تلقيب', 'تلقب', 'مص. لَقَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْقيبٌ-تَلْقيبٌ [ل ق ب] (مص. لَقَّبَ). ""تَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23200, 'تَلْقيحٌ', 'تلقيح', 'مصدر', 'لقح', 'تلقيح', 'تلقح', 'مص. لَقَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْقيحٌ-تَلْقيحٌ [ل ق ح] (مص. لَقَّحَ). 1.""تَلْقيحُ شَجَرَةٍ"": لَقْحُها. 2.""تَلْقيحُ العُقولِ"" : تَطْعيمُها. ""إِنَّ في الْمُحادَثَةِ تَلْقيحاً للعُقُولِ وَتَنْقيحاً لِلأَدَبِ"" (التوحيدي). 3.""قَرَّرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23201, 'لَقَاحٌ', 'لقاح', 'مصدر', 'لقح', 'لقاح', 'لقح', 'مص. لَقِحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَقَاحٌ-لَقَاحٌ [ل ق ح] (مص. لَقِحَ). 1. : طَعْمٌ يَحْمِلُ مَادَّةً جُرْثُومِيَّةً يُلَقَّحُ بِهِ جِسْمُ الإِنْسَانِ أَوِ الْحَيَوَانِ لِيُكْسِبَهُ مَنَاعَةً وَقُوَّةً ضِدَّ مُخْتَلِفِ الأَمْرَاضِ. ""لَقَاحُ الْجُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23202, 'لَقْطٌ', 'لقط', 'مصدر', 'لقط', 'لقط', 'لقط', 'مص. لَقَطَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَقَطٌ-لَقَطٌ [ل ق ط]. 1.""اِنْتَشَرَتِ الطُّيُورُ تَلْقُطُ اللَّقَطَ"" : مَا تَنَاثَرَ مِنَ السُّنْبُلِ أَوِ الثَّمَرِ. 2. ""لَق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23203, 'تَلْقيفٌ', 'تلقيف', 'مصدر', 'لقف', 'تلقيف', 'تلقف', 'مص. لَقَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْقيفٌ-تَلْقيفٌ [ل ق ف] (مص. لَقَّفَ). 1.""تَلْقيفُهُ الكُرَةَ"" : جَعْلُهُ يَتَلَقَّفُها. 2.""تَلْقيفُهُ الطَّعامَ"" : جَعْلُهُ يَبْلَعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23204, 'لَقْلَقَةٌ', 'لقلقة', 'مصدر', 'لقل', 'لقلقة', 'لقلقة', 'مص. لَقْلَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَقْلَقَةٌ-لَقْلَقَةٌ [ل ق ل] (مص."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23205, 'تَلْقينٌ', 'تلقين', 'مصدر', 'لقن', 'تلقين', 'تلقن', 'مص. لَقَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْقينٌ-تَلْقينٌ [ل ق ن] (مص. لَقَّنَ). ""يَسْعَى إلى تَلْقينِ مَوادَّ جَد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23206, 'لِقَاءٌ', 'لقاء', 'مصدر', 'لقي', 'لقاء', 'لق', 'مص. لَقِيَ', '', '', 'مفرد', 'Dz', '', '', '"لِقَاءاتٌ"', '', 'Rz', '', '', '', '', '', '', '"(مص. لَقِيَ). 1. ""جَاءَ لِلِقَائِهِ"" : لِلاجْتِمَاعِ بِهِ، لِمُقَابَلَتِهِ. ""تَمَّ لِقَاءٌ بَيْنَ وَفْدَيِ الْبَلَدَيْنِ"" ""إِنَّهُ مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءهُ"". (عتبة بن أبي سفيان). 2. ""لِقَاءٌ صَحَفِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23207, 'لِقَاءاتٌ', 'لقاءات', 'مصدر', '', 'لقاءات', 'لقت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23208, 'لَقْيَةٌ', 'لقية', 'مصدر', 'لقي', 'لقية', 'لقة', 'مص. لَقِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":لُقىً"', '', '', '', '', '', '', '', '', '"(مص. لَقِيَ) (الْمَرَّةُ مِنْ لَقِيَ). ""لَقِيتُهُ لَقْيَةً وَاحِدَةً"" : مُصَادَفَةً. ""لَقِيتُهُ لُقىً كَثِيرَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23209, 'لُقىً', 'لقى', 'مصدر', '', 'لقى', 'لق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23210, 'لَكٌّ', 'لك', 'مصدر', 'لكك', 'لك', 'لك', 'مص. لَكَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَكٌّ-لَكٌّ [ل ك ك] (مص. لَكَّ). 1.""رَجُلٌ لَكٌّ"" : صُلْبٌ، مُكْتَنِزُ اللَّحْمِ. 2. : نَبَاتٌ أَحْمَرُ يُصْبَغُ بِهِ الْجُلُودُ. 3.: صِبْغٌ أَحْمَرُ يَتَكَوَّنُ مِنْ إِفْرَازَاتِ ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23211, 'لَكْمٌ', 'لكم', 'مصدر', 'لكم', 'لكم', 'لكم', 'مص. لَكَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَكْمٌ-لَكْمٌ [ل ك م] (مص. لَكَمَ).""تَعَرَّضَ لِلَّكْمِ وَالشَّتْمِ"" : للِضَّرْبِ بِجُمْعِ الْيَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23212, 'لُكْنَةٌ', 'لكنة', 'مصدر', 'لكن', 'لكنة', 'لكنة', 'مص. لَكِنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لُكْنَةٌ-لُكْنَةٌ [ل ك ن] (مص. لَكِنَ). ""فِي لِسَانِهِ لُكْنَةٌ"" : فِيهِ عُجْمَةٌ. ""زالَتْ عَنْه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23213, 'تَلْميحٌ', 'تلميح', 'مصدر', 'لمح', 'تلميح', 'تلمح', 'مص. لَمَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْميحٌ-تَلْميحٌ [ل م ح] (مص. لَمَّحَ). ""كانَ تَلْميحُهُ واضِحاً"": إِشارَةٌ تَنْبِيهِيَّةٌ لِشَيْءٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23214, 'لَمْحٌ', 'لمح', 'مصدر', 'لمح', 'لمح', 'لمح', 'مص. لَمَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَمْحٌ-لَمْحٌ [ل م ح] (مص. لَمَحَ). 1.""فِي لَمْحِ الْبَصَرِ"" : فِي طَرْفَةِ الْعَيْنِ. ""كَلَمْحِ الْبَصَرِ"" ""فِي أَقَلَّ مِنْ لَمْحِ الْبَصَرِ"". 2.""لَأُرِيَنّكَ لَمْحاً بَاصِراً"" : أَمْراً وَاضِحاً، وَيُسْتَعْمَلُ فِي الوَعِيدِ أَكْثَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23215, 'لَمْزٌ', 'لمز', 'مصدر', 'لمز', 'لمز', 'لمز', 'مص. لَمَزَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَمْزٌ-لَمْزٌ [ل م ز] (مص. لَمَزَ). ""لَمْ يَكُنْ لَمْزُهُ وَغَمْزُهُ بَرِيئاً"" : الْإِشَارَةُ لِشَخْصٍ مَّا بِالْعَيْنِ أَوْ بِالرَّأْسِ أَوْ بِالشَّفَتَيْنِ مَعَ كَلاَمٍ خَفِيٍّ لِذِكْرِ الْعُيُوبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23216, 'لَمْسٌ', 'لمس', 'مصدر', 'لمس', 'لمس', 'لمس', 'مص. لَمَسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَمْسٌ-لَمْسٌ، ةٌ [ل م س] (مص. لَمَسَ). ""حَاسَّةُ اللَّمْسِ"" : إِحْدَى الْحَوَاسِّ الْخَمْسِ، وَهِيَ قُوَّةٌ فِي الْعَصَبِ تُدْرَكُ بِهَا الْحَرَارَةُ وَالْبُرُودَةُ وَالرُّطُوبَةُ وَالْيُبُوسَةُ عِنْدَ لَمْسِ الْأَشْيَاءِ وَالاِتِّصَالِ بِهَا. ""اللَّمْسُ يُدْرِكُ الأَمْزِجَةَ وَالصَّلاَبَةَ وَاللِّينَ وَالْخُشُونَةَ"". (ابن طفيل) ""أَعْمَالٌ مُتْقَنَةٌ وَفِيهَا تِلْكَ اللَّمْسَةُ مِنَ الذَّكَاءِ وَالْحِسَابِيَّةِ"". (ع. منيف)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23217, 'لَمْسَةٌ', 'لمسة', 'مصدر', 'لمس', 'لمسة', 'لمسة', 'مص. لَمَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَمْسٌ-لَمْسٌ، ةٌ [ل م س] (مص. لَمَسَ). ""حَاسَّةُ اللَّمْسِ"" : إِحْدَى الْحَوَاسِّ الْخَمْسِ، وَهِيَ قُوَّةٌ فِي الْعَصَبِ تُدْرَكُ بِهَا الْحَرَارَةُ وَالْبُرُودَةُ وَالرُّطُوبَةُ وَالْيُبُوسَةُ عِنْدَ لَمْسِ الْأَشْيَاءِ وَالاِتِّصَالِ بِهَا. ""اللَّمْسُ يُدْرِكُ الأَمْزِجَةَ وَالصَّلاَبَةَ وَاللِّينَ وَالْخُشُونَةَ"". (ابن طفيل) ""أَعْمَالٌ مُتْقَنَةٌ وَفِيهَا تِلْكَ اللَّمْسَةُ مِنَ الذَّكَاءِ وَالْحِسَابِيَّةِ"". (ع. منيف)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23218, 'تَلْميعٌ', 'تلميع', 'مصدر', 'لمع', 'تلميع', 'تلمع', 'مص. لَمَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْميعٌ-تَلْميعٌ [ل م ع] (مص. لَمَّعَ). ""تَرَكَ حِذاءهُ لِلتَّلْميعِ"" : أَيْ مَسْحَهُ لِيَصيرَ لامِعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23219, 'لَهَثَةٌ', 'لهثة', 'مصدر', 'لهث', 'لهثة', 'لهثة', 'مص. لَهِثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. لَهِثَ). ""خَفَّتْ لَهَثَاتُهُ وَجَفَّتْ دُمُوعُهُ"" : التَّنَفُّسُ بِسُرْعَةٍ مِنْ أَثَرِ الْجَرْيِ أَوِ الْعَطَشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23220, 'لَمَعَانٌ', 'لمعان', 'مصدر', 'لمع', 'لمعان', 'لمعن', 'مص. لَمَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَمَعَانٌ-لَمَعَانٌ [ل م ع] (مص. لَمَعَ). ""لَمَعَانُ الْبَرْقِ"" : إِضَاءتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23221, 'لَمْلَمَةٌ', 'لملمة', 'مصدر', 'لملم', 'لملمة', 'لملمة', 'مص. لَمْلَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَمْلَمَةٌ-لَمْلَمَةٌ [ل م ل م] (مص. لَمْلَمَ). ""لَمْلَمَةُ الْحَجَرِ"" : جَمْعُهُ جَمْعاً مُسْتَدِيراً كَالْكُرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23222, 'لَهْوٌ', 'لهو', 'مصدر', 'لهو', 'لهو', 'له', 'مص. لَهَا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَهْوٌ-لَهْوٌ [ل هـ و] (مص. لَهَا). ""شَغَلَهُ اللَّهْوُ عَنْ عَمَلِهِ"": مَا يَلْهُو بِهِ مِنْ هَوىً وَطَرَبٍ وَغَيْرِهِ وَيَشْغَلُهُ عَمَّا دُونَ ذَلِكَ. ""أَمَاكِنُ اللَّهْوِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23223, 'تَلْهيبٌ', 'تلهيب', 'مصدر', 'لهب', 'تلهيب', 'تلهب', 'مص. لَهَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْهيبٌ-تَلْهيبٌ [ل هـ ب] (مص. لَهَّبَ). 1.""تَلْهيبُ النَّارِ"": إِيقادُها، إِشْعالُها. 2.""تَلْهيبُ العَواطِفِ"" : الزِّيادَةُ مِنْ حِدَّتِها، إِثارَةُ حَمِيَّتِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23224, 'لَهِيبٌ', 'لهيب', 'مصدر', 'لهب', 'لهيب', 'لهب', 'مص. لَهَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَهِيبٌ-لَهِيبٌ [ل هـ ب] (مص. لَهَّبَ). ""لَهِيبُ النَّارِ"" : شِدَّةُ حَرَارَتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23225, 'لَهَبَانٌ', 'لهبان', 'مصدر', 'لهب', 'لهبان', 'لهبن', 'مص. لَهِبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لَهَبَانٌ-لَهَبَانٌ [ل هـ ب] (مص. لَهِبَ). 1.""رَجُلٌ لَهَبَانٌ"" : بِهِ عَطَشٌ. 2.""يَوْمٌ لَهَبَانٌ"" : شَدِيدُ الْحَرِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23226, 'لَهَبٌ', 'لهب', 'مصدر', 'لهب', 'لهب', 'لهب', 'مص. لَهِبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَهَبٌ-لَهَبٌ [ل هـ ب] (مص. لَهِبَ). ""اِرْتَفَعَ اللَّهَبُ"": لِسَانُ النَّارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23227, 'لُهَاثٌ', 'لهاث', 'مصدر', 'لهث', 'لهاث', 'لهث', 'مص. لَهَثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"لُهَاثٌ-لُهَاثٌ [ل هـ ث] (مص. لَهَثَ). 1.""بِهِ لُهَاثٌ"" : عَطَشٌ شَدِيدٌ. 2.""ما يَزَالُ يُعَانِي مِنْ لُهَاثِ الْمَوْتِ"" : مِنْ حَرِّ، شِدَّةِ الْمَوْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23228, 'لَهَثٌ', 'لهث', 'مصدر', 'لهث', 'لهث', 'لهث', 'مص. لَهِثَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"(مص. لَهِثَ). ""خَفَّتْ لَهَثَاتُهُ وَجَفَّتْ دُمُوعُهُ"" : التَّنَفُّسُ بِسُرْعَةٍ مِنْ أَثَرِ الْجَرْيِ أَوِ الْعَطَشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23229, 'تَلاوينُ', 'تلاوين', 'مصدر', '', 'تلاوين', 'تلن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23230, 'لَهَثَاتٌ', 'لهثات', 'مصدر', '', 'لهثات', 'لهثت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23231, 'لَهَفٌ', 'لهف', 'مصدر', 'لهف', 'لهف', 'لهف', 'مص. لَهِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَهَفٌ-لَهَفٌ [ل هـ ف] (مص. لَهِفَ). ""بِهِ لَهَفٌ"" : بِهِ حُزْنٌ وَتَحَسُّرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23232, 'تَلْهِيَةٌ', 'تلهية', 'مصدر', 'لهو', 'تلهية', 'تلهة', 'مص. لَهَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَلْهِيَةٌ-تَلْهِيَةٌ [ل هـ و] (مص. لَهَّى). ""حاوَلَ تَلْهِيَتَهُ بِحَديثٍ ذِي شُجونٍ"" : حَديثٍ يَتَلَهَّى بِهِ، أُلْهُوَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23233, 'تَلْويثٌ', 'تلويث', 'مصدر', 'لوث', 'تلويث', 'تلث', 'مص. لَوَّثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْويثٌ-تَلْويثٌ [ل و ث] (مص. لَوَّثَ). 1.""تَلْويثُ الثَّوْبِ بِالأوْساخِ"" : تَلْطيخُهُ. 2.""لا يَسْمَحُ لأحَدٍ بِتَلْويثِ سُمْعَتِهِ"" : تَلْطيخُ سُمْعَتِهِ بِتُهَمٍ لاَ أَخْلاقِيَّةٍ. 3.""التَّلْويثُ بِالنَّجاسَةِ"" : التَّدْنيسُ بِها. 4.""تَلْويثُ الماءِ"" : تَكْديرُهُ. ""مِنْ قِيَمِ العَصْرِ الحَدِيثِ الْمُحَافَظَةُ عَلَى البِيئَةِ وَعَدَمُ تَلْوِيثِهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23234, 'لَوَثٌ', 'لوث', 'مصدر', 'لوث', 'لوث', 'لث', 'مص. لَوِثَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لَوَثٌ-لَوَثٌ [ل و ث] (مص. لَوِثَ). ""وَجَدَهُ فِي لَوَثٍ"" : فِي ضَعْفٍ وَاسْتِرْخَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23235, 'تَلْويحٌ', 'تلويح', 'مصدر', 'لوح', 'تلويح', 'تلح', 'مص. لَوَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. لَوَّحَ). 1.""التَّلْويحُ بِاليَدِ"" : الإِشارَةُ بِها. 2.""تَلْويحُ الشَّيْبِ بِالرَّأْسِ"" : تَبْيِيضُهُ. 3.""اِمْتَلأَ الكِتابُ بِالتَّلْويحاتِ"" : بِشُروحٍ وَإِضافاتٍ وَتَعْليقاتٍ في حاشِيَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23236, 'لُؤْمٌ', 'لؤم', 'مصدر', 'لأم', 'لءم', 'لم', 'مص. لَؤُمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"لُؤْمٌ-لُؤْمٌ [ل أ م] (مص. لَؤُمَ). ""عَامَلَهُ بِلُؤْمٍ"" : بِخُبْثٍ، بِدَنَاءةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23237, 'تَلْويمٌ', 'تلويم', 'مصدر', 'لوم', 'تلويم', 'تلم', 'مص. لَوَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْويمٌ-تَلْويمٌ [ل و م] (مص. لَوَّمَ). ""تَلْويمُ الرَّجُلِ"" : لَوْمُهُ، التَّشْدِيدُ عَلَيْهِ بِاللَّوْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23238, 'تَلْوينٌ', 'تلوين', 'مصدر', 'لون', 'تلوين', 'تلن', 'مص. لَوَّنَ', '', '', 'مفرد', 'DnN', '', '', '"تَلاوينُ"', '', 'R', '', '', '', '', '', '', '"(مص. لَوَّنَ). ""قامَ بِتَلْوينِ رُسومِهِ"" : صَبْغُها، أَيْ وَضَعَ عَلَيْها أَلْواناً مُخْتَلِفَةً. ""لَمْ يَكُنْ تَلْوينُ الصُّورَةِ مُتلائِماً مَعَ طَبيعَتِهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23239, 'مِرَاسٌ', 'مراس', 'مصدر', 'مرس', 'مراس', 'مرس', 'مص. مَارَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مِرَاسٌ-مِرَاسٌ [م ر س] (مص. مَارَسَ). 1.""سَهْلُ الْمِرَاسِ"" : أَيْ صَاحِبُ لُيُونَةٍ وَمُرُونَةٍ، هَيِّنُ الْمَأْخَذِ. 2.""صَعْبُ المِرَاسِ"" : صَاحِبُ قُوَّةٍ وَجَلَدٍ. 3.""يُعَانِي مِنْ مِرَاسِ العَمَلِ"" : مِنْ مُعَالَجَتِهِ الصَّعْبَةِ وَالشَّدِيدَةِ. 4.""قَائِدٌ ذُو مِرَاسٍ"" : أَيْ ذُو شِدَّةٍ وَبَأْسٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23240, 'تَلْيِينٌ', 'تليين', 'مصدر', 'لين', 'تليين', 'تلن', 'مص. لَيَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَلْيِينٌ-تَلْيِينٌ [ل ي ن] (مص. لَيَّنَ). 1.""تَلْيِينُ الكَلامِ"" : جَعْلُهُ لَيِّناً. 2.""تَلْيِينُ طَبْعٍ"" : تَلْطيفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23241, 'مَوَاتٌ', 'موات', 'مصدر', 'موت', 'موات', 'مت', 'مص. مَاتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَوَاتٌ-مَوَاتٌ [م و ت] (مص. مَاتَ). ""أَرْضٌ مَوَاتٌ"" : خَالِيَةٌ لاَ حَيَاةَ بِهَا. ""أَرْضٌ مَوَاتٌ لاَ تُنْبِتُ زَرْعاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23242, 'مَوْتٌ', 'موت', 'مصدر', 'موت', 'موت', 'مت', 'مص. مَاتَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَوْتٌ-مَوْتٌ [م و ت] (مص. مَاتَ). 1.آل عمران آية 185 كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ (قرآن) : زَوَالُ الْحَيَاةِ عَنْ كُلِّ كَائِنٍ حَيٍّ. 2.""الْمَوْتُ الأَبْيَضُ"" : زَوَالُ الْحَيَاةِ عَنِ الكَائِنِ طَبِيعِيّاً. ""الْمَوْتُ الطَّبِيعِيُّ"". 3.""الْمَوْتُ الأَحْمَرُ"" : زَوَالُ الْحَيَاةِ قَتْلاً. 4. ""الْمَوْتُ الأَسْوَدُ"" : زَوَالُ الْحَيَاةِ خَنْقاً. 5.""الْمَوْتُ الزُّؤَامُ"" : زَوَالُ الْحَيَاةِ فَجْأَةً، سَرِيعاً. 6.إبراهيم آية 17 ويَأْتِيهِ الْمَوْتُ مِنْ كُلِّ مَكَانٍ ومَا هُوَ بِمَيِّتٍ (قرآن) : الخَوْفُ، الذُّعْرُ، الْحُزْنُ. ""تَعَدَّدَتِ الأَسْبَابُ والْمَوْتُ وَاحِدُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23243, 'مُمَاثَلَةٌ', 'مماثلة', 'مصدر', 'مثل', 'مماثلة', 'ممثلة', 'مص. مَاثَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَاثَلَةٌ-مُمَاثَلَةٌ [م ث ل] (مص. مَاثَلَ). ""بَيْنَهُمَا مُمَاثَلَةٌ"" : مُشَابَهَةٌ. ""لاَ تَكُونُ الْمُمَاثَلَةُ إِلاَّ بَيْنَ الْمُتَّقِينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23244, 'مَوْجٌ', 'موج', 'مصدر', 'موج', 'موج', 'مج', 'مص. مَاجَ.', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ج: أَمْوَاجٌ، مَوْجَاتٌ. (مص. مَاجَ). 1.""أَمْوَاجُ البَحْرِ"" : المِيَاهُ الْمُتَقَاذِفَةُ بِالتَّتَابُعِ عَلَى الشَّاطِئِ.يونس آية 22 وَجَاءهُمُ الْمَوْجُ مِنْ كَلِّ مَكَانٍ (قرآن). 2.""مَوْجَةُ الاتِّصَالِ اللاَّسِلْكِيِّ"" : الذَّبْذَبَةُ الْمُتَنَقِّلَةُ عَبْرَ الفَضَاءِ والْمُرْتَبِطَةُ بِمَا بَيْنَ أَجْهِزَةِ الإِرْسَالِ والاسْتِقْبَالِ. ""مَوْجَةٌ قَصِيرَةٌ"" ""مَوْجَةٌ مُتَوَسِّطَةٌ"". 3.""مَوْجَةٌ الشَّبَابِ"" : عُنْفُوَانُهُ، قُوَّتُهُ. 4.""عَرَفَتِ الأَسْوَاقُ مَوْجَةً مِنَ الغَلاَءِ"" : أَيْ غَلاَءً شَدِيداً. ""مَوْجَةُ البَرْدِ"" ""مَوْجَةُ حَرٍّ"" ""مَوْجَةٌ مِنَ الغَضَبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23245, 'مَوْجَةٌ', 'موجة', 'مصدر', 'موج', 'موجة', 'مجة', 'مص. مَاجَ.', '', '', 'مفرد', 'DnN', '', '', '"أَمْوَاجٌ:مَوْجَاتٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَمْوَاجٌ، مَوْجَاتٌ. (مص. مَاجَ). 1.""أَمْوَاجُ البَحْرِ"" : المِيَاهُ الْمُتَقَاذِفَةُ بِالتَّتَابُعِ عَلَى الشَّاطِئِ.يونس آية 22 وَجَاءهُمُ الْمَوْجُ مِنْ كَلِّ مَكَانٍ (قرآن). 2.""مَوْجَةُ الاتِّصَالِ اللاَّسِلْكِيِّ"" : الذَّبْذَبَةُ الْمُتَنَقِّلَةُ عَبْرَ الفَضَاءِ والْمُرْتَبِطَةُ بِمَا بَيْنَ أَجْهِزَةِ الإِرْسَالِ والاسْتِقْبَالِ. ""مَوْجَةٌ قَصِيرَةٌ"" ""مَوْجَةٌ مُتَوَسِّطَةٌ"". 3.""مَوْجَةٌ الشَّبَابِ"" : عُنْفُوَانُهُ، قُوَّتُهُ. 4.""عَرَفَتِ الأَسْوَاقُ مَوْجَةً مِنَ الغَلاَءِ"" : أَيْ غَلاَءً شَدِيداً. ""مَوْجَةُ البَرْدِ"" ""مَوْجَةُ حَرٍّ"" ""مَوْجَةٌ مِنَ الغَضَبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23246, 'أَمْوَاجٌ', 'أمواج', 'مصدر', '', 'ءمواج', 'مج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23247, 'مَوْجَاتٌ', 'موجات', 'مصدر', '', 'موجات', 'مجت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23248, 'مُمَاحَكَةٌ', 'مماحكة', 'مصدر', 'محك', 'مماحكة', 'ممحكة', 'مص. مَاحَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَاحَكَةٌ-مُمَاحَكَةٌ [م ح ك] (مص. مَاحَكَ). 1.""اِسْتَمَرَّ الْمُتَجَادِلاَنِ فِي مُمَاحَكَةِ مُمِلَّةٍ"" : أَيْ فِي مُنَاقَشَةٍ قَائِمَةٍ عَلَى جَدَلٍ ولِجَاجٍ. 2.""مُمَاحَكَةٌ لَفْظِيَّةٌ"" : اِسْتِعْمَالُ الأَلْفَاظِ نَفْسِها بِمَعَانٍ مُخْتَلِفَةٍ فِي حَدِيثٍ أَوْ نِقَاشٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23249, 'مُمَاقَتَةٌ', 'مماقتة', 'مصدر', 'مقت', 'مماقتة', 'ممقتة', 'مص. مَاقَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَاقَتَةٌ-مُمَاقَتَةٌ [م ق ت] (مص. مَاقَتَ). ""مُمَاقَتَةُ الرَّجُلِ"" : مَقْتُهُ، بُغْضُهُ، مُجَارَاتُهُ فِي الْمَقْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23250, 'مُمَارَسَةٌ', 'ممارسة', 'مصدر', 'مرس', 'ممارسة', 'ممرسة', 'مص. مَارَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. مَارَسَ). ""مُمَارَسَةُ الْحُقُوقِ"" : مُبَاشَرَتُهَا. ""الإِنْسَانُ لاَ يَسْعَدُ ولاَ يَرْتَقِي إِلاَ بِمُمَارَسَةِ حُقُوقِهِ الطَّبِيعِيَّةِ"" ""بِالْمُمَارَسَةِ تُعْرَفُ الأَشْيَاءُ عَلَى حَقِيقَتِهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23251, 'مِرَاءٌ', 'مراء', 'مصدر', 'مري', 'مراء', 'مر', 'مص. مَارَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"مِرَاءٌ-مِرَاءٌ [م ر ي] (مص. مَارَى). 1.""رَأْيٌ لاَ مِرَاءَ فِيهِ"" : لاَ جِدَالَ فِيهِ. 2.""خَبَرُ لاَ مِرَاءَ فِيهِ"" : لاَ رَيْبَ فِيهِ، لاَ شَكَّ فِيهِ. ""بِلاَ مِرَاءٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23252, 'مَيْزٌ', 'ميز', 'مصدر', 'ميز', 'ميز', 'مز', 'مص. مَازَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَيْزٌ-مَيْزٌ [م ي ز] (مص. مَازَ). 1.""الْمَيْزُ بَيْنَ النَّاسِ"" : التَّفْضِيلُ، التَّفْرِقَةُ بَيْنَهُمْ. 2.""نَاضَلَ ضِدَّ سِيَاسَةِ الْمَيْزِ العُنْصُرِيِّ"" : أَيِ التَّفْرِقَةِ بَيْنَ السُّودِ وَالبِيضِ والإِعْلاءِ مِنْ رِفْعَةِ البِيضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23253, 'مُمَازَجَةٌ', 'ممازجة', 'مصدر', 'مزج', 'ممازجة', 'ممزجة', 'مص. مَازَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَازَجَةٌ-مُمَازَجَةٌ [م ز ج] (مص. مَازَجَ). ""مُمَازَجَةُ الأَشْيَاءِ"" : مَزْجُهَا، خَلْطُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23254, 'مِزَاحٌ', 'مزاح', 'مصدر', 'مزح', 'مزاح', 'مزح', 'مص. مَازَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مِزَاحٌ-مِزَاحٌ [م ز ح] (مص. مَازَحَ). ""مِزَاحُهُ لاَ حَدَّ لَهُ"" : هَزْلُهُ، مُدَاعَبَتُهُ. ""كَانَ الأَمْرُ فِي البِدَايَةِ مُجَرَّدَ مِزَاحٍ عَابِرٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23255, 'مُمَازَحَةٌ', 'ممازحة', 'مصدر', 'مزح', 'ممازحة', 'ممزحة', 'مص. مَازَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَازَحَةٌ-مُمَازَحَةٌ [م ز ح] (مص. مَازَحَ). ""كَانَتِ الْمُمَازَحَةُ مَعَهُ عَلَى جَانِبٍ مِنَ اللُّطْفِ والْمُتْعَةِ"" : الْمُدَاعَبَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23256, 'مَيْسٌ', 'ميس', 'مصدر', 'ميس', 'ميس', 'مس', 'مص. مَاسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَيْسٌ-مَيْسٌ [م ي س] (مص. مَاسَ). 1.""مَاسَتِ الْحَسْنَاءُ مَيْساً"" : مَاسَت اِخْتِيَالاً وَتَبْخْتُراً. 2.""شَجَرُ الْمَيْسِ"" : شَجَرٌ مِنْ فَصِيلَةِ البُوقِيصِيَّاتِ، حَرَجِيَّةٌ، ذَاتُ أَخْشَابٍ صَلْبَةٍ، تُسْتَخْدَمُ فِي الصِّنَاعَةِ، يُسْتَخْرَجُ مِنْ لِحَائِهَا وَجُذُورِهَا مَادَّةٌ صِبَاغِيَّةٌ صَفْرَاءُ اللَّوْنِ، وَتُعْطِي ثِمَاراً عِنَبِيَّةَ الشَّكْلِ، صَغِيرَةَ الْحَجْمِ، حُلْوَةَ الْمَذَاقِ. 3.""مَيْسُ الْمِحْرَاثِ"" : خَشَبَةٌ طَوِيلَةٌ فِي الْمِحْرَاثِ تُوضَعُ بَيْنَ الثَّوْرَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23257, 'مُمَاشَاةٌ', 'مماشاة', 'مصدر', 'مشي', 'مماشاة', 'ممشة', 'مص. مَاشَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَاشَاةٌ-مُمَاشَاةٌ [م ش ي] (مص. مَاشَى). 1.""مُمَاشَاةُ الرَّفِيقِ"": الْمَشْيُ مَعَهُ جَنْباً إِلَى جَنْبٍ. 2.""مُمَاشَاةُ رَأْيٍ"" : مُسَايَرَتُهُ، مُوَافَقَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23258, 'مُمَاطَلَةٌ', 'مماطلة', 'مصدر', 'مطل', 'مماطلة', 'ممطلة', 'مص. مَاطَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَاطَلَةٌ-مُمَاطَلَةٌ [م ط ل] (مص. مَاطَلَ). ""مُمَاطَلَةُ الدَّيْنِ"" : تَسْوِيفُهُ، تَأْجِيلُهُ مَرَّةً بَعَدَ أُخْرَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23259, 'تَمْتينٌ', 'تمتين', 'مصدر', 'متن', 'تمتين', 'تمتن', 'مص. مَتَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْتينٌ-تَمْتينٌ [م ت ن] (مص. مَتَّنَ). 1.""تَمْتِينُ الحَبْلِ"" : جَعْلُهُ مَتِيناً صَلْباً. 2.""يَعْمَلُ على تَمْتينِ العَلاقَةِ بَيْنَهُ وَبَيْنَ أَصْدِقائِهِ"" : على تَقْوِيَتِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23260, 'مُمَاكَرَةٌ', 'مماكرة', 'مصدر', 'مكر', 'مماكرة', 'ممكرة', 'مص. مَاكَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَاكَرَةٌ-مُمَاكَرَةٌ [م ك ر] (مص. مَاكَرَ). ""فَهِمَ مُمَاكَرَةَ عَدُوِّهِ"": مُخَادَعَتَهُ، مُرَاوَغَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23261, 'مَيْلٌ', 'ميل', 'مصدر', 'ميل', 'ميل', 'مل', 'مص. مَالَ', '', '', 'مفرد', 'DnN', '', '', '"مُيُولٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مَالَ). 1.""حُكْمٌ فِيهِ مَيْلٌ"" : فِيهِ انْحِيَازٌ. 2.""أَظْهَرَ مُيُولاً شَاذَّةً"" : نَزَعَاتٍ، اِتِّجَاهَاتٍ. 3.""فِي كَلاَمِهِ مَيْلٌ"" : هَوىً..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23262, 'مُيُولٌ', 'ميول', 'مصدر', '', 'ميول', 'مل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23263, 'مَيَلاَنٌ', 'ميلان', 'مصدر', 'ميل', 'ميلان', 'ملن', 'مص. مال', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَيَلاَنٌ-مَيَلاَنٌ [م ي ل] (مص. مال). 1.""مَيَلاَنُ الْجِدَارِ"" : أَيْ بِهِ انْحِنَاءٌ، مَائِلٌ. 2.""مَيَلاَنُ الشَّمْسِ"" : زَوَالُهَا عَنْ كَبِدِ السَّمَاءِ. 3.""مَيَلاَنُ الغُصْنِ"" : تَحَرُّكُهُ بِسَبَبِ هُبُوبِ الرِّيحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23264, 'مُمَالَأَةٌ', 'ممالأة', 'مصدر', 'ملأ', 'ممالءة', 'مملة', 'مص. مَالأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَالَأَةٌ-مُمَالَأَةٌ [م ل أ] (مص. مَالأَ). ""مُمَالَأَةُ الصَّاحِبِ"" : مُمَاشَاتُهُ، مُسَاعَدَتُهُ، مُسَايَرَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23265, 'مُمَالَحَةٌ', 'ممالحة', 'مصدر', 'ملح', 'ممالحة', 'مملحة', 'مص. مَالَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَالَحَةٌ-مُمَالَحَةٌ [م ل ح] (مص. مَالَحَ). ""بَيْنَ الرَّجُلَيْنِ مُمَالَحَةٌ"" : أي بَيْنَهُمَا حُرْمَةُ المِلْحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23266, 'مُمَالَقَةٌ', 'ممالقة', 'مصدر', 'ملق', 'ممالقة', 'مملقة', 'مص. مَالَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَالَقَةٌ-مُمَالَقَةٌ [م ل ق] (مص. مَالَقَ). ""كَانَتِ الْمُمَالَقَةُ وَاضِحَةً فِي حَدِيثِهِمَا"" : الْمُنَافَقَةُ، أَي الإِظْهَارُ بِاللِّسَانِ لِمَا لَيْسَ فِي القَلْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23267, 'مُمَانَعَةٌ', 'ممانعة', 'مصدر', 'منع', 'ممانعة', 'ممنعة', 'مص. مانَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُمَانَعَةٌ-مُمَانَعَةٌ [م ن ع] (مص. مانَعَ). 1.""نَشَأَتْ مُمَانَعَةٌ حَقِيقِيَّةٌ بَيْنَهُمَا"" : مُنَازَعَةٌ. 2.""شَهَادَةُ عَدَمِ مُمَانَعَةٍ"" : شَهَادَةٌ تُعْطِي لِحَامِلِهَا حَقَّ الْمُرُورِ ودُخُولِ البَلَدِ. وهَذِهِ العِبَارَةُ مُسْتَعْمَلَةٌ فِي بُلْدَانِ الْخَلِيجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23268, 'تَمْتيعٌ', 'تمتيع', 'مصدر', 'متع', 'تمتيع', 'تمتع', 'مص. مَتَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْتيعٌ-تَمْتيعٌ [م ت ع] (مص. مَتَّعَ). 1.""تَمْتيعُهُ بِالصِّحَّةِ"" : جَعْلُهُ يَنْعَمُ، يَتَمَتَّعَ بِها. 2.""تَمْتيعُ النَّظَرِ بِجَمالِ الطَّبيعَةِ"" : إِمْتاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23269, 'مُجُونٌ', 'مجون', 'مصدر', 'مجن', 'مجون', 'مجن', 'مص. مَجَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مُجُونٌ-مُجُونٌ [م ج ن] (مص. مَجَنَ). ""غَارِقٌ فِي الْمُجُونِ"": فِي اللَّهْوِ وَالعَبَثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23270, 'مَتَانَةٌ', 'متانة', 'مصدر', 'متن', 'متانة', 'متنة', 'مص. مَتَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَتَانَةٌ-مَتَانَةٌ [م ت ن] (مص. مَتَنَ). ""مَتَانَةٌ العُودِ"" : صَلاَبَتُهُ، قُوَّتُهُ، أَيْ عَدَمُ إِمْكَانِ تَعَرُّضِهِ لِلْكَسْرِ. ""هُوَ رَجُلٌ طَوِيلُ القَامَةِ جِدّاً نَحِيلٌ جِدّاً يُعْطِي الشُّعُورَ بِالقُوَّةِ وَالْمَتَانَةِ"". (غسان كنفاني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23271, 'مَتْنٌ', 'متن', 'مصدر', 'متن', 'متن', 'متن', 'مص. مَتَنَ', '', '', 'مفرد', 'DnN', '', '', '"مُتُونٌ(مؤ:مذ)"', '', 'R', '', '', '', '', '', '', '"(مص. مَتَنَ) 1.""مَتْنُ الإِنْسَانِ"" : ظَهْرُهُ. 2.""مَتْنُ الأَرْضِ"" : مَا ارْتَفَعَ مِنْهَا وَاسْتَوَى. 3.""مَتْنُ الكِتَابِ"" : نَصُّهُ. 4. ""مَتْنُ اللُّغَةِ"" : مُفْرَدَاتهَا. ""يَمْتَحِنُهُمْ دَائِماً فِي حِفْظِ القُرْآنِ وَحِفْظِ الْمُتُونِ"". (أ. أمين). 5.""سَافَرَ عَلَى مَتْنِ بَاخِرَةٍ"" : عَلَى ظَهْرِهَا. ""عَلَى مَتْنِ طَائِرَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23272, 'مَتْنَةٌ', 'متنة', 'مصدر', 'متن', 'متنة', 'متنة', 'مص. مَتَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مُتُونٌ(مؤ:مذ)"', '', 'R', '', '', '', '', '', '', '"(مص. مَتَنَ) 1.""مَتْنُ الإِنْسَانِ"" : ظَهْرُهُ. 2.""مَتْنُ الأَرْضِ"" : مَا ارْتَفَعَ مِنْهَا وَاسْتَوَى. 3.""مَتْنُ الكِتَابِ"" : نَصُّهُ. 4. ""مَتْنُ اللُّغَةِ"" : مُفْرَدَاتهَا. ""يَمْتَحِنُهُمْ دَائِماً فِي حِفْظِ القُرْآنِ وَحِفْظِ الْمُتُونِ"". (أ. أمين). 5.""سَافَرَ عَلَى مَتْنِ بَاخِرَةٍ"" : عَلَى ظَهْرِهَا. ""عَلَى مَتْنِ طَائِرَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23273, 'مُتُونٌ', 'متون', 'مصدر', '', 'متون', 'متن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23274, 'تَمْثيلٌ', 'تمثيل', 'مصدر', 'مثل', 'تمثيل', 'تمثل', 'مص. مَثَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْثيلٌ-تَمْثيلٌ [م ث ل] (مص. مَثَّلَ). 1.""يُتْقِنُ فَنَّ التَّمْثيلِ الْمَسْرَحِيِّ أَوِ السِّينِمائِيِّ"" : تَقْديمُ الأدْوارِ، والأداءُ الْمَسْرَحِيُّ. 2.""حَضَرَ لِتَمْثيلِ بِلادِهِ في الْمُؤْتَمَرِ"" : لِيَقومَ مَقامَها وَيَتَكَلَّمَ باِسْمِها. 3.""التَّمْثيلُ الدِّبْلوماسِيُّ"" : الاِنْتِدابُ لإِقامَةِ علاقاتٍ سِياسِيَّةٍ ما بَيْنَ بَلَدَيْنِ. 4.""تَساءَلَ عَنْ سَبَبِ التَّمْثيلِ بِعَدُوِّهِ بِهَذا الشَّكْلِ"" : التَّنْكيلِ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23275, 'مُثُولٌ', 'مثول', 'مصدر', 'مثل', 'مثول', 'مثل', 'مص. مَثَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مُثُولٌ-مُثُولٌ [م ث ل] (مص. مَثَلَ). ""مُثُولٌ بَيْنَ يَدَيْهِ"" : القِيَامُ. ""مُثُولٌ أَمَامَ الْمَحْكَمَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23276, 'تَمْجيدٌ', 'تمجيد', 'مصدر', 'مجد', 'تمجيد', 'تمجد', 'مص. مَجَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْجيدٌ-تَمْجيدٌ [م ج د] (مص. مَجَّدَ). ""تَمْجيدُ الزَّعيمِ"" : تَبْجيلُهُ، تَعْظيمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23277, 'مَجْدٌ', 'مجد', 'مصدر', 'مجد', 'مجد', 'مجد', 'مص. مَجَدَ', '', '', 'مفرد', 'DnN', '', '', '"أَمْجَادٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مَجَدَ). 1.""يَعِيشُ فِي مَجْدٍ"" : العِزَّةُ، الرِّفْعَةُ، الْمَقَامُ العَالِي. ""الْمَجْدُ هُوَ إِحْرَازُ الْمَرْءِ مَقَامَ حُبٍّ وَاحْتِرَامٍ"". (الكواكبي). 2.""مِنْ ذَوِي الْمَجْدِ"" : مِنْ ذَوِي الْمَكَارِمِ الْمَأْثُورَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23278, 'أَمْجَادٌ', 'أمجاد', 'مصدر', '', 'ءمجاد', 'مجد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23279, 'مُدُودٌ', 'مدود', 'مصدر', '', 'مدود', 'مدد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23280, 'مَحْوٌ', 'محو', 'مصدر', 'محو', 'محو', 'مح', 'مص. مَحَا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَحْوٌ-مَحْوٌ [م ح و] (مص. مَحَا). 1.""مَحْوُ آثَارِ العُدْوَانِ"": إِزَالَةُ أَثَرِهِ. 2.""مَحْوُ الأُمِّيَّةِ"" : تَعْليمُ القِراءةِ والكِتابَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23281, 'تَمْحيصٌ', 'تمحيص', 'مصدر', 'محص', 'تمحيص', 'تمحص', 'مص. مَحَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْحيصٌ-تَمْحيصٌ [م ح ص] (مص. مَحَّصَ). 1.""تَمْحيصُ الأُسْلوبِ"" : تَنْقيحُهُ، الاِعْتِناءُ بِهِ. 2.""أَرادَ تَمْحيصَ الرَّجُلِ"" : اِبْتِلاءَهُ، اِخْتِبَارَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23282, 'مَحْضٌ', 'محض', 'مصدر', 'محض', 'محض', 'محض', 'مص. مَحَضَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَحْضٌ-مَحْضٌ [م ح ض] (مص. مَحَضَ). 1.""لَبَنٌ مَحْضٌ"": لَبَنٌ خَالِصٌ لَمْ يُخَالِطْهُ غَيْرُهُ. 2.""عَرَبِيٌّ مَحْضٌ"" : عَرَبِيٌّ خَالِصُ النَّسَبِ. ""كَانَتِ النَّظْرَةُ الأُولَى إِعْجَاباً مَحْضاً وَتَقْدِيراً مَحْضاً"". (إسحق الحسيني). 3.""جَاءَ بِمَحْضِ اخْتِيَارِهِ"": بِمِلْءِ إِرَادَتِهِ، بِرِضَاهُ الكَامِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23283, 'مِحَالٌ', 'محال', 'مصدر', 'محل', 'محال', 'محل', 'مص. مَحُلَ، مَاحَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مِحَالٌ-مِحَالٌ [م ح ل] (مص. مَحُلَ، مَاحَلَ). 1.""كَادَ لَهُ مِحَالاً"" : كَيْداً، مَكْراً. 2.""بَيْنَهُمَا مِحَالٌ"" : عَدَاوَةٌ. 3.""مِحَالُ اللهِ"" : عِقَابُهُ.الرعد آية 13هُوَ شَدِيدُ الْمِحَالِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23284, 'تَمْخيخٌ', 'تمخيخ', 'مصدر', 'مخخ', 'تمخيخ', 'تمخخ', 'مص. مَخَّخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْخيخٌ-تَمْخيخٌ [م خ خ] (مص. مَخَّخَ). ""تَمْخيخُ العَظْمِ"" : إِخْراجُ مُخِّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23285, 'مَخْرٌ', 'مخر', 'مصدر', 'مخر', 'مخر', 'مخر', 'مص. مَخَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَخْرٌ-مَخْرٌ [م خ ر] (مص. مَخَرَ). ""مَخْرُ السَّفِينَةِ"" : سَيْرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23286, 'مَخْضٌ', 'مخض', 'مصدر', 'مخض', 'مخض', 'مخض', 'مص. مَخَضَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَخْضٌ-مَخْضٌ [م خ ض] (مص. مَخَضَ). ""مَعَ الْمَخْضِ تَبْدُو الزُّبْدَةُ"" : تَحْرِيكُ اللَّبَنِ فِي الشَّكْوَةِ أَوْ نَحْوِهَا تَحْرِيكاً مُتَوَاصِلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23287, 'تَمْخيطٌ', 'تمخيط', 'مصدر', 'مخط', 'تمخيط', 'تمخط', 'مص. مَخَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْخيطٌ-تَمْخيطٌ [م خ ط] (مص. مَخَّطَ). ""تَمْخيطُ الوَلَدِ"" : إِخْراجُ الْمُخاطِ مِنْ أَنْفِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23288, 'مَدٌّ', 'مد', 'مصدر', 'مدد', 'مد', 'مد', 'مص. مَدَّ', '', '', 'مفرد', 'DnN', '', '', '"مُدُودٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مَدَّ). 1.""مَدُّ البَحْرِ"" : اِرْتِفَاعُ مَائِهِ وَامْتِدَادُهُ إِلَى الشَّطِّ خِلاَفَ الجَزْرِ. ""الْمَدُّ وَالجَزْرُ"". 2.""الْمَدُّ الاقْتِصَادِيُّ"" : التَّقَدُّمُ. 3.""مَدُّ الجُسُورِ"" : أَيْ إِقَامَةُ الصِّلَةِ بَيْنَ جَانِبَيْنِ. 4.""حَرَكَةُ الْمَدِّ"" : عَلاَمَةٌ تُجْعَلُ عَلَى الأَلِفِ الْمَمْدُودُةِ (آ): ""آلَةٌ""، ""آفَةٌ"". وَيُقَالُ لَهَا أَيْضاً الْمَدَّةُ. 5.""حُرُوفُ الْمَدِّ"" : هِيَ الأَلِفُ (ا) وَالوَاوُ (و) وَاليَاءُ (ي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23289, 'مَمَرَّاتٍ', 'ممرات', 'مصدر', '', 'ممرات', 'ممرت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23290, 'مَدْحٌ', 'مدح', 'مصدر', 'مدح', 'مدح', 'مدح', 'مص. مَدَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَدْحٌ-مَدْحٌ [م د ح] (مص. مَدَحَ). ""يُطْلِقُ لِسَانَهُ بِالْمَدْحِ وَالإِطْرَاءِ"" : بِالثَّنَاءِ. ""أَبْوَابُ الشِّعْرِ العَرَبِيِّ كَثِيرَةٌ مِنْهَا الغَزَلُ وَالنَّسَبُ وَالْمَدْحُ وَالْهِجَاءُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23291, 'تَمْديدٌ', 'تمديد', 'مصدر', 'مدد', 'تمديد', 'تمدد', 'مص. مَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْديدٌ-تَمْديدٌ [م د د] (مص. مَدَّدَ). 1.""تَمْديدُ الثَّوْبِ"" : بَسْطُهُ. 2.""طَلَبَ مِنْهُ تَمْديدَ دَيْنِهِ"" : إِعْطاءهُ مُهْلَةً. 3.""تَمْديدُ الحَبْلِ"" : تَطْويلُهُ. 4.""تَمْديدُ العُطْلَةِ"" : الزِّيادَةُ فِيها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23292, 'تَمْدِينٌ', 'تمدين', 'مصدر', 'مدن', 'تمدين', 'تمدن', 'مص. مَدَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْدْيُنٌ-تَمَدْيُنٌ [م د ن] (مص. تَمَدْيَنَ). 1.""تَمَدْيُنُ البَدَوِيِّ"": عَيْشُهُ عِيشَةَ الحَضَرِ. 2.""تَمَدْيُنُ الرَّجُلِ"" : تَنَعُّمُهُ بِالحَضارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23293, 'مَذَرٌ', 'مذر', 'مصدر', 'مذر', 'مذر', 'مذر', 'مص. مَذَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَذَرٌ-مَذَرٌ [م ذ ر] (مص. مَذَرَ). ""تَفَرَّقُوا شَذَرَ مَذَرَ"" : أَيْ تَفَرَّقُوا فِي كُلِّ جِهَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23294, 'مَذْقٌ', 'مذق', 'مصدر', 'مذق', 'مذق', 'مذق', 'مص. مَذَقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَذْقٌ-مَذْقٌ [م ذ ق] (مص. مَذَقَ). ""سَقَاهُ مَذْقاً"" : أَيْ لَبَناً مَمْزُوجاً بِالْمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23295, 'مَرَارَةٌ', 'مرارة', 'مصدر', 'مرر', 'مرارة', 'مررة', 'مص. مَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَرَارَةٌ-مَرَارَةٌ [م ر ر] (مص. مَرَّ). 1.""مَرَارَةُ الدَّوَاءِ"" : أَيْ شِدَّةُ حَرَارَتِهِ وَمُرِّهِ. 2.""يَشْعُرُ بِمَرَارَةٍ مِمَّا حَدَثَ"" : أَيْ يَشْعُرُ بِغُصَّةٍ وَأَلَمٍ مُضْنٍ. ""ذَاقَ مَرَارَةَ الْحَيَاةِ"". 3.""مَرَارَةٌ. ج: مَرَائِرُ"" : كِيسٌ يَخْتَزِنُ الصَّفْرَاءَ، لاَصِقٌ بِالكَبِدِ، يُسَاعِدُ عَلَى هَضْمِ الدُّهْنِيَّاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23296, 'مَرٌّ', 'مر', 'مصدر', 'مرر', 'مر', 'مر', 'مص. مَرَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَرٌّ-مَرٌّ [م ر ر] (مص. مَرَّ). "" عَلَى مَرِّ السِّنِينَ"" : ذَهَابهَا، اِجْتِيَازهَا. النمل آية 88 وَهِيَ تَمُرُّ مَرَّ السَّحَابِ(قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23297, 'مُرُورٌ', 'مرور', 'مصدر', 'مرر', 'مرور', 'مرر', 'مص. مَرَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مُرُورٌ-مُرُورٌ [م ر ر] (مص. مَرَّ). 1.""مُرُورُ السَّيَّارَاتِ"" : عُبُورُهَا. ""الْمُرُورُ مَمْنُوعٌ"". 2.""حَرَكَةُ الْمُرُورِ"" : حَرَكَةُ السَّيْرِ. ""شُرْطَةُ الْمُرُورِ"". 3.""مَعَ مُرُورِ الزَّمَنِ"" : مَعَ انْقِضَاءِ الزَّمَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23298, 'مَمَرٌّ', 'ممر', 'مصدر', 'مرر', 'ممر', 'ممر', 'مص. مَرَّ', '', '', 'مفرد', 'DnN', '', '', '"مَمَرَّاتٍ"', '', 'R', '', '', '', '', '', '', '"(مص. مَرَّ). 1. ""مَمَـرٌّ ضَيِّقٌ"" : مَكَانُ الْمُرُورِ. 2.""مَمَرُّ الرَّاجِلِينَ"" : الْحَيِّزُ الْمَوْجُودُ بَيْنَ خَطَّيْنِ عَرِيضَيْنِ والرَّابِـطُ بَيْـنَ رَصِيفَيْنِ. 3.""عَلَى مَمَرِّ الأَيَّامِ والعُصُورِ"" : طَوَالَ الأَيَّامِ والعُصُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23299, 'مِرَّةٌ', 'مرة', 'مصدر', 'مرر', 'مرة', 'مرة', 'مص. مُرَّ', '', '', 'مفرد', 'DnN', '', '', '"مِرارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مُرَّ). ""غَلَبَتْ عَلَيْهِ المِرّةُ وهاجَتْ"": خِلْطٌ مِنْ أخْلاطِ البَدَنِ هو الصّفراءُ أوِ السّوْداءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23300, 'مِرارٌ', 'مرار', 'مصدر', '', 'مرار', 'مرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23301, 'مَرَجٌ', 'مرج', 'مصدر', 'مرج', 'مرج', 'مرج', 'مص. مَرِجَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَرَجٌ-مَرَجٌ [م ر ج] (مص. مَرِجَ). 1.""مَا هَذَا الْمَرَجُ؟"" : مَا هَذَا الاضْطِرَابُ وَالفَوْضَى؟. 2.""بَيْنَهُمْ هَرَجٌ وَمَرَجٌ"" : بَيْنَهُمْ فِتْنَةٌ وَاضْطِرَابٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23302, 'مَرَحٌ', 'مرح', 'مصدر', 'مرح', 'مرح', 'مرح', 'مص. مَرِحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَرَحٌ-مَرَحٌ [م ر ح] (مص. مَرِحَ). 1.""يَعِيشُ فِي مَرَحٍ"" : فِي غِبْطَةٍ وَنَشَاطٍ وَفَرَحٍ. 2.""تَبَاهَ مَرَحاً"" : أَيْ عُجْباً، اِخْتِيَالاً، تَبَخْتُراً.لقمان آية 18 وَلاَ تَمْشِ فِي الأَرْضِ مَرَحاً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23303, 'تَمْريدٌ', 'تمريد', 'مصدر', 'مرد', 'تمريد', 'تمرد', 'مص. مَرَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْريدٌ-تَمْريدٌ [م ر د] (مص. مَرَّدَ). 1.""تَمْريدُ الغُصْنِ"" : تَجْرِيدُهُ مِنْ وَرَقِهِ. 2.""تَمْريدُ الصَّخْرِ"" : تَمْليسُهُ، نَحْتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23304, 'تَمْريرٌ', 'تمرير', 'مصدر', 'مرر', 'تمرير', 'تمرر', 'مص. مَرَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْريرٌ-تَمْريرٌ [م ر ر] (مص. مَرَّرَ). 1.""تَمْريرُ البِساطِ على الأرْضِ"" : بَسْطُهُ. 2.""تَمْريرُ الطَّعامِ بِالتَّوابِلِ"" : جَعْلُهُ مُرّاً. 3.""تَمْريرُ فِكْرَةٍ"" : إِدْخالُها مع مُجْمَلِ الأفْكارِ بِحيلَةٍ. 4.""تَمْريرُ الكُرَةِ"" : جَعْلُها تَمُرُّ بِكَيْفِيَّةٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23305, 'تَمْريضٌ', 'تمريض', 'مصدر', 'مرض', 'تمريض', 'تمرض', 'مص. مَرَّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْريضٌ-تَمْريضٌ [م ر ض] (مص. مَرَّضَ). ""سَهِرَتْ على تَمْريضِهِ"" : الاعْتِناءُ بِالْمَريضِ والقِيامُ عَلَيْهِ والإِشْرافُ على عِلاجِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23306, 'مَرَضٌ', 'مرض', 'مصدر', 'مرض', 'مرض', 'مرض', 'مص. مَرِضَ', '', '', 'مفرد', 'DnN', '', '', '"أَمْرَاضٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مَرِضَ). 1.""أُصِيبَ بِمَرَضٍ أَقْعَدَهُ عَنِ العَمَلِ"" : مَا يُصِيبُ الإِنْسَانَ مِنْ عِلَّةٍ تُؤَثِّرُ فِي صِحَّتِهِ، وَالْمَرَضُ أَنْوَاعٌ مِنْهَا مَا هُوَ ظَاهِريٌّ: ""مَرَضٌ جِلْدِيٌّ""، ""مَرَضُ القَلْبِ وَأَعْضَاءِ الإِنْسَانِ"". وَمِنْهَا مَا هُوَ بَاطِنِيٌّ: ""مَرَضٌ نَفْسَانِيٌّ""، ""مَرَضٌ عَقْلِيٌّ""، ""مَرَضٌ عَصَبِيٌّ"". وَمِنْهَا مَا هُوَ اجْتِمَاعِيٌّ، أَيْ مَا يُخْرِجُ الكَائِنَ الْحَيَّ عَنْ حَدِّ الاعْتِدَالِ مِنْ نِفَاقٍ أَوْ تَقْصِيرٍ فِي الأَمْرِ. البقرة آية 10فِي قُلُوبِهِمْ مَرَضٌ فَزَادَهُمُ اللَّهُ مَرَضاً(قرآن). 2.""عِلْمُ الأَمْرَاضِ"" : عِلْمٌ يَبْحَثُ فِي أَسْبَابِ الأَمْرَاضِ وَأَعْرَاضِها وَسُبُلِ عِلاَجِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23307, 'أَمْرَاضٌ', 'أمراض', 'مصدر', '', 'ءمراض', 'مرض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23308, 'مَرْعٌ', 'مرع', 'مصدر', 'مرع', 'مرع', 'مرع', 'مص. مَرَعَ', '', '', 'مفرد', 'DnN', '', '', '"أَمْرَاعٌ:أَمْرُعٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مَرَعَ). ""جَاءَ يَطْلُبُ الْمَرْعَ"" : العُشْبَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23309, 'أَمْرَاعٌ', 'أمراع', 'مصدر', '', 'ءمراع', 'مرع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23310, 'أَمْرُعٌ', 'أمرع', 'مصدر', '', 'ءمرع', 'مرع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23311, 'تَمْريغٌ', 'تمريغ', 'مصدر', 'مرغ', 'تمريغ', 'تمرغ', 'مص. مَرَّغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْريغٌ-تَمْريغٌ [م ر غ] (مص. مَرَّغَ). ""تَمْريغُ أَنْفِهِ في التُّرابِ"": تَقْليبُهُ في التُّرابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23312, 'مُرُوقٌ', 'مروق', 'مصدر', 'مرق', 'مروق', 'مرق', 'مص. مَرَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مُرُوقٌ-مُرُوقٌ [م ر ق] (مص. مَرَقَ). ""الْمُرُوقُ مِنَ الدِّينِ"" : الارْتِدَادُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23313, 'تَمْرينٌ', 'تمرين', 'مصدر', 'مرن', 'تمرين', 'تمرن', 'مص. مَرَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَمارينُ"', '', 'R', '', '', '', '', '', '', '"(مص. مَرَّنَ). 1.""أَنْجَزَ تَمارينَهُ بِإِتْقانٍ"" : تَداريبَ لُغَوِيَّةً أَوْ حِسابِيَّةً وَما إلى ذلِكَ على أُسُسِ قَواعِدَ لإيجادِ حُلولٍ لَها. 2.""يُزاوِلُ تَمارينَ رِياضِيَّةً"" : حَرَكاتٍ رِيَاضِيَّةً لِتَدْريبِ الجِسْمِ عَلَيْها. 3.""يُشْرِفُ على تَمْريناتٍ عَسْكَرِيَّةٍ"" : تَداريبَ عَسْكَرِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23314, 'تَمارينُ', 'تمارين', 'مصدر', '', 'تمارين', 'تمرن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23315, 'مُرُونَةٌ', 'مرونة', 'مصدر', 'مرن', 'مرونة', 'مرنة', 'مص. مَرَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مُرُونَةٌ-مُرُونَةٌ [م ر ن] (مص. مَرَنَ). ""مُرُونَةُ الطَّبْعِ"" : لُيُونَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23316, 'مُرُوءةٌ', 'مروءة', 'مصدر', 'مرأ', 'مروءة', 'مرة', 'مص. مَرُؤَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"مُرُوءةٌ-مُرُوءةٌ [م ر أ] (مص. مَرُؤَ). 1.""اِتَّسَمَتْ مُعَامَلاَتُهُمْ بِالْمُرُوءةِ"" : آدَابٌ وَسُلُوكٌ فِي الْمُعَامَلَةِ قَائِمٌ عَلَى مَحَاسِنِ الأَخْلاَقِ. 2.""رَجُلٌ ذُو مُرُوءةٍ"" : ذُو أَخْلاَقٍ، ذُو نَخْوَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23317, 'مَزٌّ', 'مز', 'مصدر', 'مزز', 'مز', 'مز', 'مص. مَزَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَزٌّ-مَزٌّ [م ز ز] (مص. مَزَّ). 1.""مَزُّ الشَّرَابِ"" : مَصُّهُ. 2.""أَمْرٌ مَزٌّ"" : صَعْبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23318, 'مَزْجٌ', 'مزج', 'مصدر', 'مزج', 'مزج', 'مزج', 'مص. مَزَجَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَزْجٌ-مَزْجٌ [م ز ج] (مص. مَزَجَ). 1.""مَزْجُ الْحَلِيبِ بِالْمَاءِ"" : خَلْطُهُ. 2.""شَرَابٌ مَزْجٌ"" : مَمْزُوجٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23319, 'مَسْكٌ', 'مسك', 'مصدر', 'مسك', 'مسك', 'مسك', 'مص. مَسَكَ', '', '', 'مفرد', 'DnN', '', '', '"مُسُكٌ:مُسُوكٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مَسَكَ). 1.""مَسَّ مَسْكَهُ"" : جِلْدَهُ. يَكَادُ يَخْرُجُ مِنْ مَسْكِهِ. 2.""هُمْ فِي مُسُوكِ الثَّعَالِبِ"" : مَذْعُورُونَ. 3.""مَسْكُ الدَّفَاتِرِ"" : الْمُحَاسَبَةُ وَضَبْطُهَا فِي مُؤَسَّسَةٍ أَوْ شَرِكَةٍ تِجَارِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23320, 'مُزَاحٌ', 'مزاح', 'مصدر', 'مزح', 'مزاح', 'مزح', 'مص. مَزَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَزَّاحٌ-مَزَّاحٌ [م ز ح] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ مَزَّاحٌ"": كَثِيرُ الْمَزْحِ وَالهَزْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23321, 'مَزْحٌ', 'مزح', 'مصدر', 'مزح', 'مزح', 'مزح', 'مص. مَزَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَزْحٌ-مَزْحٌ [م ز ح] (مص. مَزَحَ). ""لاَ يَعْرِفُ لِلْمَزْحِ مَعْنًـى"" : لِلْهَزْلِ، لِلْمُدَاعَبَةِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23322, 'تَمْزيقٌ', 'تمزيق', 'مصدر', 'مزق', 'تمزيق', 'تمزق', 'مص. مَزَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْزيقٌ-تَمْزيقٌ [م ز ق] (مص. مَزَّقَ). ""تَمْزيقُ الثَّوْبِ"" : شَقُّهُ، تَقْطيعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23323, 'تَمْسيحٌ', 'تمسيح', 'مصدر', 'مسح', 'تمسيح', 'تمسح', 'مص. مَسَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْسيحٌ-تَمْسيحٌ [م س ح] (مص. مَسَّحَ). 1.""تَمْسيحُ اللَّوْحِ"": إِزالَةُ ما عَلَيْهِ مِنْ أَثَرٍ، مَحْوُ... 2.""تَمْسيحُ الرَّأْسِ بِالدُّهْنِ"": إِمْرارُ يَدِهِ على الرَّأْسِ بِالدُّهْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23324, 'مِسَاحَةٌ', 'مساحة', 'مصدر', 'مسح', 'مساحة', 'مسحة', 'مص. مَسَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مِسَاحَةٌ-مِسَاحَةٌ [م س ح] (مص. مَسَحَ). 1.""تَبْلُغُ مِسَاحَةُ الْمُرَبَّعِ كَذَا"" (هن) : قِيَاسُ سَطْحٍ بِالأَمْتَارِ الْمُرَبَّعَةِ. ""مِسَاحَةُ الأَرْضِ"". 2.""عِلْمُ المِسَاحَةِ"" (هن) : عِلْمٌ يَبْحَثُ عَنْ مَقَادِيرِ الخُطُوطِ وَالسُّطُوحِ وَالأَجْسَامِ وَرَسْمِ خَرَائِطِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23325, 'مَسْحٌ', 'مسح', 'مصدر', 'مسح', 'مسح', 'مسح', 'مص. مَسَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَسْحٌ-مَسْحٌ [م س ح] (مص. مَسَحَ). 1.""مَسْحُ اللَّوْحِ"" : إِزَالَةُ مَا بِهِ مِنْ أَثَرٍ. 2.""مَسْحُ الأَرْضِ"" : قِيَاَسُهَا وَتَقْسِيمُهَا. 3.""مَسْحُ الأَحْذِيَةِ"" : تَلْمِيعُهَا. 4.""آلَةُ الْمَسْحِ"" : لَوْحَةٌ صَغِيرَةٌ يُمْسَحُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23326, 'مَسْخٌ', 'مسخ', 'مصدر', 'مسخ', 'مسخ', 'مسخ', 'مص. مَسَخَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَسْخٌ-مَسْخٌ [م س خ] (مص. مَسَخَ). 1.""إِنَّهُ الْمَسْخُ بِعَيْنَيْهِ"" : القُبْحُ. 2.""دَعَا لَهُ بِالْمَسْخِ"" : أَنْ تَتَحَوَّلَ نَفْسُهُ إِلَى بَدَنِ حَيَوَانٍ يُنَاسِبُهُ فِي الأَوْصَافِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23327, 'تَمْسيدٌ', 'تمسيد', 'مصدر', 'مسد', 'تمسيد', 'تمسد', 'مص. مَسَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْسيدٌ-تَمْسيدٌ [م س د] (مص. مَسَّدَ). ""تَمْسيدُ العَضَلاتِ"" : دَلْكُها، تَلْيِينُها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23328, 'تَمْسيكٌ', 'تمسيك', 'مصدر', 'مسك', 'تمسيك', 'تمسك', 'مص. مَسَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْسيكٌ-تَمْسيكٌ [م س ك] (مص. مَسَّكَ). 1.""تَمْسيكُهُ بِالكِتابِ"" : تَعَلُّقُهُ بِهِ. 2.""تَمْسيكُهُ بِالمِسْكِ"" : تَطْيِيبُهُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23329, 'مَصٌّ', 'مص', 'مصدر', 'مصص', 'مص', 'مص', 'مص. مَصَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَصٌّ-مَصٌّ [م ص ص] (مص. مَصَّ). 1.""مَصُّ الشَّرَابِ"" : رَشْفُهُ، اِمْتِصَاصُهُ. 2.""قَصَبُ الْمَصِّ"" : قَصَبُ السُّكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23330, 'مُسُكٌ', 'مسك', 'مصدر', '', 'مسك', 'مسك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23331, 'مُسُوكٌ', 'مسوك', 'مصدر', '', 'مسوك', 'مسك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23332, 'مَسٌّ', 'مس', 'مصدر', 'مسس', 'مس', 'مس', 'مص. مَسَّ، مُسَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَسٌّ-مَسٌّ [م س س] (مص. مَسَّ، مُسَّ). ""أَصَابَهُ مَسٌّ"" : جُنُونٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23333, 'تَمْسِيَةٌ', 'تمسية', 'مصدر', 'مسي', 'تمسية', 'تمسة', 'مص. مَسَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَمْسِيَةٌ-تَمْسِيَةٌ [م س ي] (مص. مَسَّى). ""تَمْسِيَةُ الزَّائِرِ"" : الدُّعاءُ لَهُ بِأَنْ يَكونَ مَساؤُهُ خَيْراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23334, 'مَشْجٌ', 'مشج', 'مصدر', 'مشج', 'مشج', 'مشج', 'مص. مَشَجَ', '', '', 'مفرد', 'DnN', '', '', '"أَمْشَاجٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مَشَجَ). ""حَلِيبٌ مَشْجٌ"" : مُخْتَلِطٌ بِشَيْءٍ مَشِيجٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23335, 'أَمْشَاجٌ', 'أمشاج', 'مصدر', '', 'ءمشاج', 'مشج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23336, 'تَمْشيطٌ', 'تمشيط', 'مصدر', 'مشط', 'تمشيط', 'تمشط', 'مص. مَشَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْشيطٌ-تَمْشيطٌ [م ش ط] (مص. مَشَّطَ). 1.""تَمْشيطُ الشَّعْرِ"": تَسْريحُهُ. 2.""تَمْشيطُ المكانِ"" : تَفْتيشُهُ تَفْتيشاً دَقيقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23337, 'تَمْشِيَةٌ', 'تمشية', 'مصدر', 'مشي', 'تمشية', 'تمشة', 'مص. مَشَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَمْشِيَةٌ-تَمْشِيَةٌ [م ش ي] (مص. مَشَّى). ""تَمْشِيَةُ الطِّفْلِ"" : جَعْلُهُ يَمْشِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23338, 'مَشْيٌ', 'مشي', 'مصدر', 'مشي', 'مشي', 'مش', 'مص. مَشَى', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مَشْيٌ-مَشْيٌ [م ش ي] (مص. مَشَى). 1.""الْمَشْيُ عَلَى الأَقْدَامِ"" : الانْتِقَالُ مِنْ مَكَانٍ إِلَى آخَرَ سَيْراً. ""قَطَعَ الْمَسَافَةَ مَشْياً"". 2.""مَشْيُ البَطْنِ"" : الإِسْهَالُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23339, 'مُضِيٌّ', 'مضي', 'مصدر', 'مضي', 'مضي', 'مض', 'مص. مَضَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُضِيٌّ-مُضِيٌّ [م ض ي] (مص. مَضَى). ""الْمُضِيُّ فِي العَمَلِ"": الاسْتِمْرَارُ فِيهِ، الْمُتَابَعَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23340, 'تَمْصيرٌ', 'تمصير', 'مصدر', 'مصر', 'تمصير', 'تمصر', 'مص. مَصَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْصيرٌ-تَمْصيرٌ [م ص ر] (مص. مَصَّرَ). 1.""تَمْصيرُ المكانِ"" : جَعْلُهُ مِصْراً، أَيْ مَدينَةً. 2.""تَمْصيرُ الأمْصارِ"" : بِناؤُها، تَشْييدُها. 3.""تَمْصيرُ الوَلَدِ"" : جَعْلُهُ مِصْرِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23341, 'مَصْلٌ', 'مصل', 'مصدر', 'مصل', 'مصل', 'مصل', 'مص. مَصَلَ', '', '', 'مفرد', 'DnN', '', '', '"مُصُولٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مَصَلَ). 1.""مَصْلُ اللَّبَنِ"" : الْمَاءُ الْمُسْتَخْرَجُ مِنْهُ عِنْدَ تَخَثُّرِهِ. 2.""مَصْلُ الدَّمِ"" : سَائِلٌ رَقِيقٌ أَصْفَرُ يَنْفَصِلُ مِنَ الدَّمِ عِنْدَ تَخَثُّرِهِ. 3.""مَصْلُ التَّلْقِيحِ"" : مَا يُؤْخَذُ مِنْ دَمِ حَيَوَانٍ مُحَصَّنٍ مِنَ الإِصَابَةِ بِمَرَضٍ كَالْجُدَرِي وَالدِّفْتِرْيَا، لِيُحْقَنَ بِهِ جِسْمٌ آخَرُ لِيُكْسِبَهُ مَنَاعَةً تَقِيهِ الإِصَابَةَ بِذَلِكَ الْمَرَضِ. 4.""مَرَضُ الْمَصْلِ"": صَدْمَةٌ ذَاتُ حَسَاسِيَّةٍ تَحْدُثُ مِنْ إِعَادَةِ حَقْنِ الْمَصْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23342, 'مُصُولٌ', 'مصول', 'مصدر', '', 'مصول', 'مصل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23343, 'مَضَضٌ', 'مضض', 'مصدر', 'مضض', 'مضض', 'مض', 'مص. مَضَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَضَضٌ-مَضَضٌ [م ض ض] (مص. مَضَّ). ""عَلَى مَضَضٍ"" : عَلَى كُرْهٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23344, 'مَضٌّ', 'مض', 'مصدر', 'مضض', 'مض', 'مض', 'مص. مَضَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَضٌّ-مَضٌّ [م ض ض] (مص. مَضَّ). 1.""رَجُلٌ مَضُّ الضَّرْبِ"" : مُوجِعُهُ. 2.""دَوَاءٌ مُضٌّ"" : حَادٌّ، مُوجِعٌ. ""كُحْلٌ مَضٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23345, 'مَضْغٌ', 'مضغ', 'مصدر', 'مضغ', 'مضغ', 'مضغ', 'مص. مَضَغَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَضْغٌ-مَضْغٌ [م ض غ] (مص. مَضَغَ). ""مَضْغُ الطَّعَامِ"" : لَوْكُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23346, 'مَضْمَضَةٌ', 'مضمضة', 'مصدر', 'مضمض', 'مضمضة', 'مضمضة', 'مص. مَضْمَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَضْمَضَةٌ-مَضْمَضَةٌ [م ض م ض] (مص. مَضْمَضَ). 1.""مَضْمَضَةُ الْمَاءِ فِي الفَمِ"" : تَحْرِيكُهُ بِإِداَرَتِهِ فِي الفَمِ. 2.""مَضْمَضَةُ الفَمِ"" : مُسْتَحْضَرٌ صَيْدَلِيٌّ سَائِلٌ يُمَضْمَضُ فِي الفَمِ لِتَطْهِيرِهِ أَوْ لِعِلاَجِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23347, 'تَمْضِيَةٌ', 'تمضية', 'مصدر', 'مضي', 'تمضية', 'تمضة', 'مص. مَضَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَمْضِيَةٌ-تَمْضِيَةٌ [م ض ي] (مص. مَضَّى). 1. ""تَمْضِيَةُ قَرارٍ"": إِنْفاذُهُ. 2.""تَمْضِيَةُ الوَقْتِ"" : قَضاؤُهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23348, 'مَضَاءٌ', 'مضاء', 'مصدر', 'مضي', 'مضاء', 'مض', 'مص. مَضَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"مَضَاءٌ-مَضَاءٌ [م ض ي] (مص. مَضَى). 1.""مَضَاءُ السَّيْفِ"": حِدَّتُهُ وسُرْعَةُ قَطْعِهِ. 2.""مَضَاءُ العَزِيمَةِ"" : قُوَّتُهَا، شِدَّتُهَا. ""رَجُلٌ ذُو عَزِيمَةٍ وَمَضَاءٍ"" ""مَا كَانَ العُنْفُ لِيَزِيدَ الْمَبَادِئَ الشَّرِيفَةَ إِلاَّ قُوَّةً وَمَضَاءً"". (إسحق الحسيني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23349, 'مَقْمَقَةٌ', 'مقمقة', 'مصدر', 'مقمق', 'مقمقة', 'مقمقة', 'مص. مَقْمَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَقْمَقَةٌ-مَقْمَقَةٌ [م ق م ق] (مص. مَقْمَقَ). ""مَقْمَقَةُ الصَّوْتِ"": حِكَايَتُهُ، تَرْدِيدُهُ مِنَ البَطْنِ. ""مَقْمَقَةُ كَلاَمٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23350, 'مَطَرٌ', 'مطر', 'مصدر', 'مطر', 'مطر', 'مطر', 'مص. مَطَرَ', '', '', 'مفرد', 'DnN', '', '', '"أَمْطَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مَطَرَ). ""أَمْطَرَتِ السَّمَاءُ مَطَراً"" : مَاءُ السَّحَابِ. ""مَطَرٌ بِلاَ سَحَابٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23351, 'أَمْطَارٌ', 'أمطار', 'مصدر', '', 'ءمطار', 'مطر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23352, 'مَعْجَمَةٌ', 'معجمة', 'مصدر', 'عجم', 'معجمة', 'معجمة', 'مص. مَعْجَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَعْجَمَةٌ-مَعْجَمَةٌ [ع ج م] (مص. مَعْجَمَ). ""مَعْجَمَةُ مُفْرَدَةٍ"" : تَسْجِيلُهَا، وَضْعُهَا فِي مُعْجَمٍ، أَوْ إِضْفاءُ طابَعِ الْمُعْجَمِيَّةِ عَلَيْها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23353, 'مَعْمَعَةٌ', 'معمعة', 'مصدر', 'معمع', 'معمعة', 'معمعة', 'مص. مَعْمَعَ', '', '', 'مفرد', 'DnN', '', '', '"مَعَامِعُ"', '', 'R', '', '', '', '', '', '', '"(مص. مَعْمَعَ). ""فِي مَعْمَعَةِ الْحَرْبِ"" : فِي خِضَمِّهَا وهَيَجَانِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23354, 'مَعَامِعُ', 'معامع', 'مصدر', '', 'معامع', 'معمع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23355, 'مَغْصٌ', 'مغص', 'مصدر', 'مغص', 'مغص', 'مغص', 'مص. مُغِصَ، مَغِصَ', '', '', 'مفرد', 'DnN', '', '', '"أَمْغَاصٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مُغِصَ، مَغِصَ). ""أَصَابَهُ مَغَصٌ"" : مَغَسٌ، وَجَعٌ والْتِوَاءٌ وتَقْطِيعٌ فِي الأَمْعَاءِ أَوْ الْكُلْيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23356, 'أَمْغَاصٌ', 'أمغاص', 'مصدر', '', 'ءمغاص', 'مغص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23357, 'مَغْنَطَةٌ', 'مغنطة', 'مصدر', 'مغنط', 'مغنطة', 'مغنطة', 'مص. مَغْنَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَغْنَطَةٌ-مَغْنَطَةٌ [م غ ن ط] (مص. مَغْنَطَ). ""مَغْنَطَةُ الْحَدِيدِ"": شَحْنُهُ بِالتَّيَّارِ الْمِغْنَاطِيسِيّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23358, 'مَقْتٌ', 'مقت', 'مصدر', 'مقت', 'مقت', 'مقت', 'مص. مَقَتَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَقْتٌ-مَقْتٌ [م ق ت] (مص. مَقَتَ). ""يُكِنُّ لَهُ الْمَقْتَ"" : البُغْضَ الشَّدِيدَ.غافرآية 10 لَمَقْتُ اللَّهِ أَكْبَرُ مِنْ مَقْتِكُمْ أَنْفُسَكُمْ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23359, 'مَلَلٌ', 'ملل', 'مصدر', 'ملل', 'ملل', 'مل', 'مص. مَلَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَلَلٌ-مَلَلٌ [م ل ل] (مص. مَلَّ). ""يَعِيشُ فِي مَلَلٍ"" : فِي ضَجَرٍ، فِي سَأَمٍ، سَآمَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23360, 'مُكَاءٌ', 'مكاء', 'مصدر', 'مكو', 'مكاء', 'مك', 'مص. مَكَا', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"مُكَاءٌ-مُكَاءٌ [م ك و] (مص. مَكَا). ""مُكَاءُ الطَّيْرِ"" : صَفِيرُهُ.الأنفال آية 35 وَمَا كَانَ صَلاَتُهُمْ عِنْدَ البَيْتِ إِلاَّ مُكَاءً وتَصْدِيَة . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23361, 'مُكْثٌ', 'مكث', 'مصدر', 'مكث', 'مكث', 'مكث', 'مص. مَكَثَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مُكْثٌ-مُكْثٌ، مَكْثٌ [م ك ث] (مص. مَكَثَ). ""لَمْ يَكُنْ مَكْثُهُ طَوِيلاً بِالقَرْيَةِ"" : مَقَامُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23362, 'مَكْرٌ', 'مكر', 'مصدر', 'مكر', 'مكر', 'مكر', 'مص. مَكَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مِكَرٌّ-مِكَرٌّ [ك ر ر]. ""فَرَسٌ مِكَرٌّ"" : كَثِيرُ الكَرِّ فِي القِتَالِ، الْمُطَاوِعُ صَاحِبَهُ فِي الهُجُومِ. ""مِكَرٍّ مِفَرٍّ مُقْبِلٍ مُدْبِرٍ"". (امرؤ القيس)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23363, 'مَكْسٌ', 'مكس', 'مصدر', 'مكس', 'مكس', 'مكس', 'مص. مَكَسَ', '', '', 'مفرد', 'DnN', '', '', '"مُكُوسٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مَكَسَ). ""الْمَكْسُ مِنَ الْمَدَاخِيلِ الهَامَّةِ لِمَوَارِدِ الدَّوْلَةِ"" : مَا يُؤَدَّى مِنْ ضَرَائِبَ عَلَى مَا يُبَاعُ فِي الأَسْوَاقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23364, 'مُكُوسٌ', 'مكوس', 'مصدر', '', 'مكوس', 'مكس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23365, 'تَمْكِينٌ', 'تمكين', 'مصدر', 'مكن', 'تمكين', 'تمكن', 'مص. مَكَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْكِينٌ-تَمْكِينٌ [م ك ن] (مص. مَكَّنَ). ""سَعى إلَى تَمْكِينِهِ مِنَ النَّجَاحِ"" : جَعْلُهُ مُتَمَكِّناً مِنَ النَّجَاحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23366, 'مَكَانَةٌ', 'مكانة', 'مصدر', 'مكن', 'مكانة', 'مكنة', 'مص. مَكُنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. مَكُنَ). ""يَتَمَتَّعُ بِمَكَانَةٍ خَاصَّةٍ"" : بِشَأْوٍ، بِشَأْنٍ، بِمَرْتَبَةٍ، بِمَنْزِلَةٍ، بِرِفْعَةٍ. ""الْمَكَانَةُ الْمَرْمُوقَةُ"" ""هُوَ ذُو مَكَانَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23367, 'مَكْنَنَةٌ', 'مكننة', 'مصدر', 'مكن', 'مكننة', 'مكننة', 'مص. مَكْنَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَكْنَنَةٌ-مَكْنَنَةٌ [م ك ن] (مص. مَكْنَنَ). ""مَكْنَنَةُ الإِنْتَاجِ"" : أَيْ إِخْضَاعُهُ لِعَمَلِ الآلَةِ بَدَلاً مِنَ العَمَلِ اليَدَوِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23368, 'مَلاَلٌ', 'ملال', 'مصدر', 'ملل', 'ملال', 'ملل', 'مص. مَلَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَلاَلٌ-مَلاَلٌ [م ل ل] (مص. مَلَّ). ""يَعِيشُ فِي مَلاَلٍ"" : فِي ضَجَرٍ، سَأَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23369, 'أَمْلاَكٌ', 'أملاك', 'مصدر', '', 'ءملاك', 'ملك', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23370, 'تَمْلِيحٌ', 'تمليح', 'مصدر', 'ملح', 'تمليح', 'تملح', 'مص. مَلَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْلِيحٌ-تَمْلِيحٌ [م ل ح] (مص. مَلَّحَ). 1.""تَمْلِيحُ الطَّعَامِ"" : وَضْعُ المِلْحِ فِيهِ، تَكْثِيرُ مِلْحِهِ. 2. ""تَمْلِيحُ السَّمَكِ"" : جَعْلُ المِلْحِ فِيهِ وَتَقْدِيدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23371, 'مُلُوحَةٌ', 'ملوحة', 'مصدر', 'ملح', 'ملوحة', 'ملحة', 'مص. مَلُحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مُلُوحَةٌ-مُلُوحَةٌ [م ل ح] (مص. مَلُحَ). ""مَاءٌ بِهِ مُلُوحَةٌ"" : بِهِ طَعْمُ المِلْحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23372, 'تَمْلِيسٌ', 'تمليس', 'مصدر', 'ملس', 'تمليس', 'تملس', 'مص. مَلَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْلِيسٌ-تَمْلِيسٌ [م ل س] (مص. مَلَّسَ). 1. ""تَمْلِيسُ الجِلْدِ"" : جَعْلُهُ أمْلَسَ نَاعِماً، تَلْيِينُهُ. 2. ""تَمْلِيسُ الأرْضِ"" : تَسْوِيَتُهَا بِالْمَلاَّسَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23373, 'مَلاَسَةٌ', 'ملاسة', 'مصدر', 'ملس', 'ملاسة', 'ملسة', 'مص. مَلُسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَلاَسَةٌ-مَلاَسَةٌ [م ل س] (مص. مَلُسَ). ""مَلاَسَةُ الْخَشَبِ"" : لِينُ مَلْمَسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23374, 'مَلَصٌ', 'ملص', 'مصدر', 'ملص', 'ملص', 'ملص', 'مص. مَلِصَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَلَصٌ-مَلَصٌ [م ل ص] (مص. مَلِصَ). 1.""مَلَصُ الْخَيْطِ"" : سُقُوطُهُ، زَلَقُهُ لِمَلاَسَتِهِ وَلِينِهِ. 2.""مَلَصُ السَّمَكِةِ"" : اِنْفِلاَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23375, 'تَمْلِيطٌ', 'تمليط', 'مصدر', 'ملط', 'تمليط', 'تملط', 'مص. مَلَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْلِيطٌ-تَمْلِيطٌ [م ل ط] (مص. مَلَّطَ). ""تَمْلِيطُ الحَائِطِ"" : طَلْيُهُ بِالمِلاَطِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23376, 'مَلَقٌ', 'ملق', 'مصدر', 'ملق', 'ملق', 'ملق', 'مص. مَلَقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَلِقٌ-مَلِقٌ [م ل ق] (صِيغَةُ فَعِل لِلْمُبالَغَةِ). ""رَجُلٌ مَلِقٌ"" : كَثِيرُ التَّمَلُّقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23377, 'تَمْلِيكٌ', 'تمليك', 'مصدر', 'ملك', 'تمليك', 'تملك', 'مص. مَلَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْلِيكٌ-تَمْلِيكٌ [م ل ك] (مص. مَلَّكَ). 1. ""وَعَدَهُ بِتَمْلِيكِهِ أمْلاَكَهُ"" : جَعْلهَا مِلْكاً لَهُ. 2. ""اِتَّفَقُوا عَلَى تَمْلِيكِهِ عَلَيْهِمْ"" : جَعْلُهُ مَلِكاً عَلَيْهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23378, 'مُلْكٌ', 'ملك', 'مصدر', 'ملك', 'ملك', 'ملك', 'مص. مَلَكَ', '', '', 'مفرد', 'DnN', '', '', '"أَمْلاَكٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مَلَكَ) (مذ، مؤ). 1.""أَرْضٌ فِي مُلْكِهِ"" : مَمْلُوكَةٌ لَهُ، يَمْلِكُهَا، يَتَصَرَّفُ فِيهَا. ""عَقَارٌ فِي مُلْكِهِ"". 2.""لَهُ مُلْكٌ تَلِيدٌ"" : عَظَمَةٌ، سُلْطَانٌ. 3.""الْمُلْكُ"" : سُورَةٌ مِنْ سُوَرِ القُرْآنِ. الملك آية 1 تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْك (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23379, 'تَمْنِيةٌ', 'تمنية', 'مصدر', 'مني', 'تمنية', 'تمنة', 'مص. مَنَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَمْنِيةٌ-تَمْنِيةٌ [م ن ي] (مص. مَنَّى). ""سَعَى إلَى تَمْنِيَتِهِ بِالنَّجَاحِ"" : جَعْلُهُ يَتَمَنَّاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23380, 'مَمْلَكَةٌ', 'مملكة', 'مصدر', 'ملك', 'مملكة', 'مملكة', 'مص. مَلَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَمْلَكَةٌ-مَمْلَكَةٌ [م ل ك] (مص. مَلَكَ). 1.""الْمَمْلَكَةُ الْهَاشِمِيَّةُ"" : تَسْمِيَةٌ تُطْلَقُ عَلَى كَلِّ بِلاَدٍ خَاضِعَةٍ لِسُلْطَةِ الْمَلِكِ وأَوَامِرِهِ. ""الْمَمْلَكَةُ الْمَغْرِبِيَّةُ"" ""الْمَمْلَكَةُ العَرَبِيَّةُ السَّعُودِيَّةُ"". 2.""اِمْتَدَتْ مَمْلَكَتُهُ إِلَى حُدُودِ السّنيِغَالِ"" : حُدُودُ سُلْطَانِ الْمَلِكِ. 3.""مَمْلَكَةٌ"" : أَحَدُ الأَقْسَامِ فِي تَصْنِيفِ الْحَيَوَانِ والنَّبَاتِ والْجَمَادِ. ""مَمْلَكَةُ الْحَيَوَانِ"" ""مَمْلَكَةُ النَّحْلِ"" ""مَمْلَكَةُ الطُّيُورِ"" ""مَمْلَكَةُ الجَمَادِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23381, 'مَلْمَلَةٌ', 'ململة', 'مصدر', 'ململ', 'ململة', 'ململة', 'مص. مَلْمَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَلْمَلَةٌ-مَلْمَلَةٌ [م ل م ل] (مص. مَلْمَلَ). ""كَانَ يَشْعُرُ أَنَّ كَلَّ مَا حَوْلَهُ فِي مَلْمَلَةٍ"" : فِي سَيْرٍ مُسْرِعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23382, 'مِنَّةٌ', 'منة', 'مصدر', 'منن', 'منة', 'منة', 'مص. مَنَّ', '', '', 'مفرد', 'DnN', '', '', '"مِنَنٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مَنَّ). 1.""تَفَضَّلَ عَلَيْهِ بِمِنَّةٍ"" : بِالإِحْسَانِ. 2.""أَهِيَ مِنَّةٌ أَمْ إِحْسَانٌ "" : مَنُّ الْمَرْءِ بِإِحْسَانِهِ وَالقَرْعُ بِهِ اِفْتِخَاراً. ""وَقَالَ الْمُخْتَارُ بِشَيْءٍ مِنْ مِنَّةٍ وَحَسَدٍ : كُلُوا وتَنَعَّمُوا، الْمُلْكُ لَنَا والْخَيْرَاتُ لَكُمْ"". (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23383, 'مِنَنٌ', 'منن', 'مصدر', '', 'منن', 'من', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23384, 'مَنٌّ', 'من', 'مصدر', 'منن', 'من', 'من', 'مص. مَنَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَنٌّ-مَنٌّ [م ن ن] (مص. مَنَّ). 1.""مَنُّهُ كَثِيرٌ"" : كُلُّ مَا يُنْعَمُ بِهِ. 2.""مَا هَذَا الْمَنُّ"" : عِبَارَةٌ تُقَالُ لِمَنْ يُعَدِّدُ مَا صَنَعَ، وَيَمُنُّ بِمَا أَعْطَى، ويَعْتَدُّ بِهِ اعْتِداداً"". البقرة آية 264 لاَ تُبْطِلُوا صَدَقَاتِكُمْ بِالْمَنِّ والأَذَى (قرآن). 3.""يُحِبُ مَذَاقَ الْمَنِّ"" : نَدًى يَنْزِلُ عَلَى الشَّجَرِ ويَنْعَقِدُ عَسَلاً ويَجِفُّ ويُؤْكَلُ. البقرة آية 57 وَأَنْزَلْنَا عَلَيْكُمُ الْمَنَّ والسَّلْوَى (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23385, 'مَنْحٌ', 'منح', 'مصدر', 'منح', 'منح', 'منح', 'مص. مَنَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"مَنْحٌ-مَنْحٌ [م ن ح] (مص. مَنَحَ). ""طَلَبَ مَنْحَهُ مُهْلَةً"" : أَيْ إِعْطَاءهُ ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23386, 'مَنَاعَةٌ', 'مناعة', 'مصدر', 'منع', 'مناعة', 'منعة', 'مص. مَنَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَنَاعَةٌ-مَنَاعَةٌ [م ن ع] (مص. مَنَعَ). 1. ""هُوَ فِي مَنَاعَةٍ بَيْنَ أَهْلِهِ"" : فِي قُوَّةٍ واعْتِزَازٍ. ""وما كَانَتِ الْمُقَاوَمَةُ لِتَزِيدَ ذَوِي الْمَبَادِئِ إِلاَّ قُوَّةَ احْتِمَالٍ ومَنَاعَةٍ"". (إسحق الحسيني). 2.""مَنَاعَةُ الجِسْمِ"" : قُوَّةٌ يَكْتَسِبُهَا الجِسْمُ ويُقَاوِمُ بِهَا الأَمْرَاضَ والْجَرَاثِيمَ بِشَكْلٍ طَبِيعِيٍّ أَوْ بِاللِّقَاحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23387, 'مَنْعٌ', 'منع', 'مصدر', 'منع', 'منع', 'منع', 'مص. مَنَعَ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"مَنْعٌ-مَنْعٌ [م ن ع] (مص. مَنَعَ). 1.""أُعْلِنَ عَنْ قَرَارِ مَنْعِ التَّجَوُّلِ"" : حَظْر التَّجَوُّلِ. 2.""حُبُوبُ مَنْعِ الْحَمْلِ"" : حُبُوبٌ لِلإِمْسَاكِ عَنِ الْحَمْلِ ولِإِعَاقَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23388, 'هَزْلٌ', 'هزل', 'مصدر', 'هزل', 'هزل', 'هزل', 'مص. مِنْ هَزَلَ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"هَزْلٌ-هَزْلٌ [هـ ز ل] (مص. مِنْ هَزَلَ). ""فِي كَلاَمِهِ هَـزْلٌ"" : مَزْحٌ، أَيْ عَدَم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23389, 'مِهْنَةٌ', 'مهنة', 'مصدر', 'مهن', 'مهنة', 'مهنة', 'مص. مَهَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مِهَنٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. مَهَنَ). ""مِهْنَةُ النَّجَّارِ"" : حِرْفَتُهُ، صِنْعَتُهُ. ""سِرُّ الْمِهْنَةِ"" : سِرُّ مَهَارَتِهَا وَحِذْقِهَا وَمَا يُحِيطُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23390, 'ْمَهَا', 'مها', 'مصدر', 'مهو', 'مها', 'مه', 'مص. مَهَا', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"ْمَهَا-الْمَهَا [م هـ و] (مص. مَهَا). 1. : ثَغْرٌ أَبْيَضُ نَقِيٌّ، كَثِيرُ الْمَاءِ. 2. : الكَوَاكِبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23391, 'تَمْهِيدٌ', 'تمهيد', 'مصدر', 'مهد', 'تمهيد', 'تمهد', 'مص. مَهَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْهِيدٌ-تَمْهِيدٌ [م هـ د] (مص. مَهَّدَ). 1.""قَرَأَ تَمْهِيدَ الكِتَابِ"" : مُقَدِّمَتَهُ. ""تَنَاوَلَ صُلْبَ الْمَوْضُوعِ بِلاَ تَمْهِيدٍ"". 2.""تَمْهِيداً لِلاجْتِمَاعِ"" : تَحْضِيراً، تَهْييئاً، إعْدَاداً لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23392, 'مَهْدٌ', 'مهد', 'مصدر', 'مهد', 'مهد', 'مهد', 'مص. مَهَدَ', '', '', 'مفرد', 'DnN', '', '', '"مُهُودٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مَهَدَ). 1.""مَهْدُ الرَّضِيعِ"" : سَرِيرُهُ الَّذِي يُهَيَّأُ لَهُ لِيَنَامَ عَلَيْهِ.آل عمران آية 46 ويُكَلِّمُ النَّاسَ فِي الْمَهْدِ (قرآن). 2. اُطْلُبِ العِلْمَ مِنَ الْمَهْدِ إِلَى اللَّحْـدِ (حديث) : أَيْ مِنَ النَّشْأَةِ إِلَى الْمَمَاتِ. 3.""قَضَى عَلَيْهِ فِي مَهْدِهِ"" : أَيْ فِي نَشْأَتِهِ. 4.""الشَّرْقُ مَهْدُ الْحَضَارَاتِ"": مَنْبِتٌ، مَنْشَأٌ، مَنْبَعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23393, 'مُهُودٌ', 'مهود', 'مصدر', '', 'مهود', 'مهد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23394, 'مَهَارَةٌ', 'مهارة', 'مصدر', 'مهر', 'مهارة', 'مهرة', 'مص. مَهَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. مَهَرَ). 1.""اِكْتَسَبَ مَهَارَةً فِي عَمَلِهِ بِالْمُمَارَسَةِ الدَّائِمَةِ"" : أَيْ حِذْقاً، بَرَاعَةً. ""يُنْجِزُ عَمَلَهُ بِمَهَارَةٍ"". 2. ""الْمَهَارَاتُ اللُّغَوِيَّةُ"" : القُدُرَاتُ الضَّرُورِيَّةُ لاسْتِخْدَامِ اللُّغَةِ والتَّمَكُّنِ مِنْهَا فَهْماً وتَحَدُّثاً وقِرَاءةً وكِتَابَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23395, 'مَهْرٌ', 'مهر', 'مصدر', 'مهر', 'مهر', 'مهر', 'مص. مَهَرَ', '', '', 'مفرد', 'DnN', '', '', '"مُهُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. مَهَرَ). ""مَهْرُ الْمَرْأَةِ"": صَدَاقُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23396, 'مُهُورٌ', 'مهور', 'مصدر', '', 'مهور', 'مهر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23397, 'تَمْهِيلٌ', 'تمهيل', 'مصدر', 'مهل', 'تمهيل', 'تمهل', 'مص. مَهَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْهِيلٌ-تَمْهِيلٌ [م هـ ل] (مص. مَهَّلَ). 1. ""تَمْهِيلُهُ الدَّيْنَ"" : تَأْجِيلُهُ، تَأْخِيرُهُ. 2.""طَلَبَ مِنْهُ التَّمْهِيلَ فِي عَمَلِهِ"" : عَدَمَ الاسْتِعْجَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23398, 'مُهْلَةٌ', 'مهلة', 'مصدر', 'مهل', 'مهلة', 'مهلة', 'مص. مَهَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مُهْلَةٌ-مُهْلَةٌ [م هـ ل] (مص. مَهَلَ). 1.""مَشَى عَلَى مُهْلَتِهِ"": بِرِفْقٍ وَتُؤَدَةٍ وَتَأَنٍّ. 2.""أَعْطَاهُ مُهْلَةً لِيُنْجِزَ عَمَلَهُ"" : أَيْ أَعْطَاهُ زَمَناً قَلِيلاً، فُرْصَةً مُحَدَّدَةً. 3.""أَعْطَاهُ مُهْلَةً لِتَصْفِيَةِ الحِسَابَاتِ وَالدُّيُونِ"" : الأَجَلُ الْمَمْنُوحُ بَعْدَ انْتِهَاءِ الْمُدَّةِ الْقَانُونِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23399, 'مِهَنٌ', 'مهن', 'مصدر', '', 'مهن', 'مهن', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23400, 'مَهَانَةٌ', 'مهانة', 'مصدر', 'مهن،هون', 'مهانة', 'مهنة', 'مص. مَهُنَ، هَانَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَهَانَةٌ-مَهَانَةٌ [م هـ ن، هـ و ن] (مص. مَهُنَ، هَانَ). ""تَعَرَّضَ لِلْمَهَانَةِ"" : لِلذُّلِّ والْحَقَارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23401, 'تَمْوِيتٌ', 'تمويت', 'مصدر', 'موت', 'تمويت', 'تمت', 'مص. مَوَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْوِيتٌ-تَمْوِيتٌ [م و ت] (مص. مَوَّتَ). 1. ""تَمْوِيتُ الرَّجُلِ"": جَعْلُهُ يَمُوتُ، إمَاتَتُهُ. 2. ""تَمْوِيتُ الدَّوَابِّ"" : كَثْرَةُ الْمَوْتِ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23402, 'تَمْوِيلٌ', 'تمويل', 'مصدر', 'مول', 'تمويل', 'تمل', 'مص. مَوَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْوِيلٌ-تَمْوِيلٌ [م و ل] (مص. مَوَّلَ). ""يَحْتَاجُ الْمَشْرُوعُ إلَى تَمْوِيلٍ"" : يَحْتَاجُ إلَى مَالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23403, 'تَمْوِينٌ', 'تموين', 'مصدر', 'مون', 'تموين', 'تمن', 'مص. موَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْوِينٌ-تَمْوِينٌ [م و ن] (مص. موَّنَ). ""وَضَعُوا نِظَاماً جَدِيداً لِتَمْوِينِ الشَّعْبِ"" : نِظَامٌ تَضَعُهُ جَمَاعَةٌ مَّا أو حُكُومَةٌ لِتَوْفِيرِ الْمُؤَنِ للشَّعْبِ فِي فَتَراتِ الأزَمَاتِ الاقْتِصَادِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23404, 'تَمْوِيهٌ', 'تمويه', 'مصدر', 'موه', 'تمويه', 'تمه', 'مص. مَوَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَمْوِيهٌ-تَمْوِيهٌ [م و هـ] (مص. مَوَّهَ). ""حَاوَلَ التَّمْوِيهَ عَلَى الأَعْدَاءِ"" : إخْفَاءَ الوَاقِعِ الفِعْلِيِّ وَإظْهَارَ مَا لا قِيمَةَ لَهُ لِلإيقَاعِ بِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23405, 'تَمْييزٌ', 'تمييز', 'مصدر', 'ميز', 'تمييز', 'تمز', 'مص. مَيَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَمْييزٌ-تَمْييزٌ [م ي ز] (مص. مَيَّزَ). 1. ""حَاكِمٌ لَهُ القُدْرَةُ عَلَى التَّمْيِيزِ بَيْنَ الحَقِّ والبَاطِلِ"" : الفَصْلُ، العَزْلُ، التَّفْرِيقُ. ""بإمْكَانِهِ التَّمْيِيزُ بَيْنَ الضَّارِّ والنَّافِعِ"" ""لَهُ حَاسَّةٌ لِتَمْيِيزِ الجَمِيلِ مِنَ الشَّنِيعِ وَالصَّحِيحِ مِنَ الفَاسِدِ"" (ميخائيل نعيمة). 2.""التَّمْيِيزُ العُنْصُرِيُّ"" : نِظَامٌ تَنْهَجُهُ بَعْضُ الأنْظِمَةِ العُنْصُرِيَّةِ لِلتَّفْرِقَةِ بَيْنَ النَّاسِ فِي حُقُوقِهِمْ وَوَاجِبَاتِهِمْ لاِخْتِلاَفِ أجْنَاسِهِمْ. ""لِكُلِّ إنْسَانٍ حَقُّ التَّمَتُّعِ بِكَافَّةِ الحُقُوقِ وَالحُرِّيَّاتِ دُونَ أيِّ تَمْيِيزٍ، كَالتَّمْيِيزِ بَيْنَ العُنْصُرِ أَوِ اللوْنِ أو الجِنْسِ أَوِ الدِّينِ أوِ الرَّأيِ السِّيَاسِيِّ أَوْ أَيِّ رَأيٍ آخَرَ"". 3.التَّمْييزُ فِي النَّحْوِ نَوْعَانِ : أ. تَمْيِيزٌ مُفْرَدٌ يَكُونُ مُمَيَّزُهُ لَفْظاً دَالاًّ عَلَى العَدَدِ كَمَا فِي قَوْلِهِ تَعَالى : يوسف آية 4 إنِّي رَأيْتُ أحَدَ عَشَرَ كَوْكَباً (قرآن) : ""كَوْكَباً"" تَمْييزٌ و""أحَدَ عَشَرَ"" مُمَيَّزُهُ. ب. تَمْيِيزُ الجُمْلَةِ.: ""عَالِمٌ أفْضَلُ عِلْماً"" : تَقْدِيرُهُ العَالِمُ عِلْماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23406, 'مَبَرَّةٌ', 'مبرة', 'مصدر', 'برر', 'مبرة', 'مبرة', 'مص. ميمي', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَبَارُّ"', '', 'R', '', '', '', '', '', '', '"(مص. ميمي). 1.""اِلْتَجَأَ إِلىَ الْمَبَرَّةِ"" : مَوْضِعُ البِرِّ كَالْمُسْتَشْفَى وَالْمَلْجَإِ. 2.""مَع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23407, 'مَبَارُّ', 'مبار', 'مصدر', '', 'مبار', 'مبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23408, 'مُقَامٌ', 'مقام', 'مصدر', 'قوم', 'مقام', 'مقم', 'مص. ميمي', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مُقَامٌ-مُقَامٌ [ق و م] (مص. ميمي). 1.""طَالَ مُقَامُهُ فِي الجَبَلِ"" : أَيْ طَالَتْ إِقَامَتُهُ. 2.""لِيَكُنْ مُقَامُهُ مُرِيحاً فِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23409, 'مَلَفٌّ', 'ملف', 'مصدر', 'لفف', 'ملف', 'ملف', 'مص. ميمي', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. ميمي). ""وَضَعَ الوَثَائِقَ فِي مَلَفٍّ"" : غِلاَفٌ مِنَ الوَرَقِ الْمُقَوَّى تُوضَعُ فِيهِ أَوْرَاقٌ ووَثَائِقُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23410, 'مَلْمَسٌ', 'ملمس', 'مصدر', 'لمس', 'ملمس', 'ملمس', 'مص. ميمي', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَلاَمِسُ"', '', 'R', '', '', '', '', '', '', '"(مص. ميمي). 1.""كَانَ مَلْمَسُهُ لِلْجُرْحِ خَفِيفاً"" : لَمْسُهُ. 2.""وَضَعَ يَدَهُ فِي مَلْمَسِ الأَلَمِ"" : مَوْضِع اللَّمْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23411, 'مَلاَمِسُ', 'ملامس', 'مصدر', '', 'ملامس', 'ملمس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23412, 'مَنْأىً', 'منأى', 'مصدر', 'نأي', 'منءى', 'من', 'مص. ميمي', '', '', 'مفرد', 'Dy', '', 'Pf', '""', '', 'R0', '', '', '', '', '', '', '"مَنْأىً-مَنْأىً [ن أ ي] (مص. ميمي).""كَانَ بِمَنْأىً عَنْ كُلِّ سُوءٍ"" : كَانَ بَعِيداً عَنْ ...، عَلَى بُعْدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23413, 'منأيات', 'منأيات', 'مصدر', '', 'منءيات', 'منت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23414, 'نَوْبَةٌ', 'نوبة', 'مصدر', 'نوب', 'نوبة', 'نبة', 'مص. نَابَ', '', '', 'مفرد', 'DnN', '', '', '"نُوَبٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَابَ). 1.""قَامَ بِنَوْبَتِهِ"" : بِدَوْرَتِهِ. ""نَوْبَةُ الْحَارِسِ"". 2.""اِعْتَرَتْهُ نَوْبَةٌ عَصَبِيَّةٌ"": نازِلَةٌ. ""اِشْتَدَّتْ بِهَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23415, 'نُوَبٌ', 'نوب', 'مصدر', '', 'نوب', 'نب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23416, 'نَوْبٌ', 'نوب', 'مصدر', 'نوب', 'نوب', 'نب', 'مص. نَابَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَوْبٌ-نَوْبٌ [ن و ب] (مص. نَابَ). 1.""بَيْنَهُ وَبَيْنَ الوُصُولِ نَوْبٌ"" : مَسِيرَةُ يَوْمٍ وَلَيْلَةٍ. 2.""نَوْبُ الشَّيْءِ"" : قُوَّتُهُ. 3.""كَانَ بِنَوْبٍ مِنْهُ"" : بِقُرْبٍ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23417, 'نِيَابَةٌ', 'نيابة', 'مصدر', 'نيب', 'نيابة', 'نبة', 'مص. نَابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"نِيَابَةٌ-نِيَابَةٌ [ن ي ب] (مص. نَابَ). 1.""جَاءَ نِيَابَةً عَنْهُ"" : بَدَلاً مِنْهُ. 2.""تَرَشَّحَ لِلنِّيَابَةِ"" : تَرَشَّحَ لِيَكُونَ ناَئِباً فِي البَرْلُمَانِ. 3.""النِّيَابَةُ العَامَّةُ"" : هِيَ الْهَيْئَةُ الَّتِي يُمَثِّلُهَا مَا يُسَمَّى بِالنَّائِبِ العَامِّ أَوْ وَكِيلِ النِّيَابَةِ أَوْ وَكِيلِ الدَّوْلَةِ أَوْ وَكِيلِ الْمَلِكِ فِي الْمَحَاكِمِ، وَتَنُوبُ عَنِ الدَّوْلَةِ بِلِسَانِهَا وَتُقِيمُ الدَّعْوَى عَلَى مُتَّهَمٍ أَوْ غَيْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23418, 'مَنَابٌ', 'مناب', 'مصدر', 'نوب', 'مناب', 'منب', 'مص. ناب', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَنَابٌ-مَنَابٌ [ن و ب] (مص. ناب). ""نَابَ مَنَابَهُ"" : قَامَ مَقَامَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23419, 'مُنَازَعَةٌ', 'منازعة', 'مصدر', 'نزع', 'منازعة', 'منزعة', 'مص. نَازَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. نَازَعَ). ""دَخَلُوا فِي مُنَازَعَةٍ شَدِيدَةٍ"" : فِي مُخَاصَمَةٍ. ""مُنَازَعَاتٌ قَضَائِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23420, 'مُنَابذَةٌ', 'منابذة', 'مصدر', 'نبذ', 'منابذة', 'منبذة', 'مص. نَابَذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَابذَةٌ-مُنَابذَةٌ [ن ب ذ] (مص. نَابَذَ). ""بَيْنَهُمَا مُنَابَذَةٌ"" : فِرَاقٌ عَنْ خِلاَفٍ وَبُغْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23421, 'مُنَاجَدَةٌ', 'مناجدة', 'مصدر', 'نجد', 'مناجدة', 'منجدة', 'مص. نَاجَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَاجَدَةٌ-مُنَاجَدَةٌ [ن ج د] (مص. نَاجَدَ). ""مُنَاجَدَةُ الرَّجُلِ"" : مُعَاوَنَتُهُ ونَصْرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23422, 'مُنَاجَاةٌ', 'مناجاة', 'مصدر', 'نجو', 'مناجاة', 'منجة', 'مص. نَاجَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَاجَاةٌ-مُنَاجَاةٌ [ن ج و] (مص. نَاجَى). ""مُنَاجَاةُ النَّفْسِ"" : مُسَارَّتُهَا. ""ظَلَّ يُرَدِّدُ عِبَارَاتِ الْمُنَاجَاةِ والغَزَلِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23423, 'نُوَاحٌ', 'نواح', 'مصدر', 'نوح', 'نواح', 'نح', 'مص. نَاحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُوَاحٌ-نُوَاحٌ [ن و ح] (مص. نَاحَ). ""صَدَرَ عَنْهَا نُوَاحٌ اهْتَزَّتْ لَهُ جُدْرَانُ الْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23424, 'نَوْحٌ', 'نوح', 'مصدر', 'نوح', 'نوح', 'نح', 'مص. نَاحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَوْحٌ-نَوْحٌ [ن و ح] (مص. نَاحَ). 1.""اِشْتَدَّ نَوْحُهُ"" : بُكَاؤُهُ. 2.""نَوْحُ الْحَمَامَةِ"" : تَرْدِيدُ صَوْتِهَا، هَدِيلُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23425, 'مُنَادَمَةٌ', 'منادمة', 'مصدر', 'ندم', 'منادمة', 'مندمة', 'مص. نَادَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَادَمَةٌ-مُنَادَمَةٌ [ن د م] (مص. نَادَمَ). ""اِسْتَمَرَّتْ مُنَادَمَتُهُمْ إِلَى فَتْرَةٍ مُتَأَخِّرَةٍ مِنَ اللَّيْلِ"" : الْمُجَالَسَةُ، الْمُرَافَقَةُ والشُّرْبُ مَعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23426, 'مُنَادَاةٌ', 'مناداة', 'مصدر', 'ندو', 'مناداة', 'مندة', 'مص. نَادَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَادَاةٌ-مُنَادَاةٌ [ن د و] (مص. نَادَى). 1.""يُحِبُّ مُنَادَاةَ الصِّحَابِ فِي كُلِّ مَسَاءٍ"" : الجُلُوسُ مَعَهُمْ فِي النَّادِي. 2.""مُنَادَاةُ القَوْمِ"" : دَعْوَتُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23427, 'نِدَاءٌ', 'نداء', 'مصدر', 'ندو', 'نداء', 'ند', 'مص. نَادَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"(مص. نَادَى). 1.""سَمِعَ نِدَاءً مِنْ بَعِيدٍ"" : صَوْتاً مُجَرَّداً. 2.""وَجَّهَ نِدَاءً إِلَى الشَّعْبِ"" : دَعْوَةً.مريم آية 3 إِذْ نَادَى رَبَّهُ نِدَاءً خَفِيّاً (قرآن) ""لَكِنَّ نِدَاءاتِهِ لَمْ تَجِدْ صَدىً"". 3.""نِدَاءُ الضَّمِيرِ"" : يَقَظَةُ الضَّمِيرِ. 4.""أَدَوَاتُ النِّدَاءِ"" : هِيَ : أ. آ. أَيْ، آيْ، يَا، أَيَا، هَيَا، وَا. وَتَخْتَصُّ بِتَوْجِيهِ الدَّعَوَاتِ إِلَى الْمُخَاطَبِ وَتَنْبِيهِهِ لِلْإِصْغَاءِ : ""يَا غَافِلُ!""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23428, 'نَوَارٌ', 'نوار', 'مصدر', 'نور', 'نوار', 'نر', 'مص. نَارَ، يَنُورُ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَوَارٌ-نَوَارٌ [ن و ر] (مص. نَارَ، يَنُورُ). ""اِمْرَأَةٌ نَوَارٌ"" : اِمْرَأَةٌ تَنْفُرُ مِنَ الشَّكِّ وَالتُّهْمَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23429, 'مُنَاظَرَةٌ', 'مناظرة', 'مصدر', 'نظر', 'مناظرة', 'منظرة', 'مص. نَاظَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. نَاظَرَ). 1.""مُنَاظَرَةٌ عِلْمِيَّةٌ"" : مُحَاوَرَةٌ، جِدَالٌ، نَدْوَةٌ لِتَبَادُلِ الرَّأْيِ وتَحْدِيدِ طَبِيعَةِ الْمَشَاكِلِ. ""مُنَاظَرَةٌ ثَقَافِيَّةٌ"" ""مُنَاظَرَةُ الْمَجَالِسِ الْمَحَلِّيَّةِ"". 2.""نَظَّمَتِ الوِزَارَةُ مُنَاظَرَةً لاِنْتِقَاءِ عَامِلَيْنِ فِي قِطَاعِهَا"" : اِخْتِبَارٌ يُجْرَى لانْتِقَاءِ الْمُمْتَازِينَ وَفْقَ مَعَايِيرَ مُعَيَّنَةٍ، والكَلِمَةُ مُتَدَاوَلَةٌ بِتُونُسَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23430, 'نِزَالٌ', 'نزال', 'مصدر', 'نزل', 'نزال', 'نزل', 'مص. نَازَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَزَّالٌ-نَزَّالٌ [ن ز ل] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""وَلَدٌ نَزَّالٌ"" : كَثِيرُ النُّزُولِ، أَوْ كَثِيرُ الْمُنَازَلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23431, 'مُنَاسَبَةٌ', 'مناسبة', 'مصدر', 'نسب', 'مناسبة', 'منسبة', 'مص. نَاسَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. نَاسَبَ). 1.""مُنَاسَبَة مُلاَئِمَةٌ"" : فُرْصَةٌ مُلاَئِمَةٌ. 2.""قَصَائِدُ الْمُنَاسَبَاتِ"" : القَصَائِدُ الُّتِي تُنْشَدُ فِي الْمَدْحِ والرِّثَاءِ لِشَخْصٍ أو قَضِيَّةٍ مَّا. ""شِعْرُ الْمُنَاسَبَاتِ"". 3.""بِالْمُنَاسَبَةِ سَأَحْكِي لَكُمْ قِصَّتِي"" : بِخُصُوصِ مَا حَدَثَ سَأَحْكِي... 4.""سَأُحَدِّثُكُمْ فِي هَذِهِ الْمُنَاسَبَةِ السَّعِيدَةِ"" : فِي هَذَا الْحَدَثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23432, 'مُنَاشَدَةٌ', 'مناشدة', 'مصدر', 'نشد', 'مناشدة', 'منشدة', 'مص. نَاشَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَاشَدَةٌ-مُنَاشَدَةٌ [ن ش د] (مص. نَاشَدَ). ""لَمْ تَكُنْ مُنَاشَدَةُ الغَرِيبِ لِتُحَرِّكَ شُعُورَهُمْ"" : الْمُطَالَبَةُ بِالْمُسَاعَدَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23433, 'مُنَاصَرَةٌ', 'مناصرة', 'مصدر', 'نصر', 'مناصرة', 'منصرة', 'مص. نَاصَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَاصَرَةٌ-مُنَاصَرَةٌ [ن ص ر] (مص. نَاصَرَ). ""مُنَاصَرَةُ الْحَقِّ"" : التَّأْيِيدُ والدِّفَاعُ عَنِ الْحَقِّ، نَصْرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23434, 'مُنَاصَفَةٌ', 'مناصفة', 'مصدر', 'نصف', 'مناصفة', 'منصفة', 'مص. نَاصَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَاصَفَةٌ-مُنَاصَفَةٌ [ن ص ف] (مص. نَاصَفَ). ""اِقْتَسَمَا الغَنِيمَةَ مُنَاصَفَةً"" : أَيْ كُلٌّ مِنْهُمَا أَخَذَ نِصْفاً. ""قَرَّرَتِ اللَّجْنَةُ أَنْ تَقْسِمَ الْجَائِزَةَ مُنَاصَفَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23435, 'نِضَالٌ', 'نضال', 'مصدر', 'نضل', 'نضال', 'نضل', 'مص. نَاضَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نِضَالٌ-نِضَالٌ [ن ض ل] (مص. نَاضَلَ). ""وَاصَلَ نِضَالَهُ مِنْ أَجْلِ حُرِّيَّةِ بِلاَدِهِ وَاسْتِقْلاَلِها"" : الدِّفَاعَ قَوْلاً وَفِعْلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23436, 'نِيَاطٌ', 'نياط', 'مصدر', 'نوط', 'نياط', 'نط', 'مص. نَاطَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْوِطَةٌ:نُوطٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَاطَ). ""نِيَاطُ القَلْبِ"" : عِرْقٌ غَلِيظٌ مُتَّصِلٌ بِالقَلْبِ، فَإِذَا قُطِعَ مَاتَ صَاحِبُهُ. ""يُمَزِّقُ الأَسَى نِيَاطَ قَلْبِهِ"". (محمود تيمور)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23437, 'أَنْوِطَةٌ', 'أنوطة', 'مصدر', '', 'ءنوطة', 'نطة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23438, 'نُوطٌ', 'نوط', 'مصدر', '', 'نوط', 'نط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23439, 'أَنْوَالٌ', 'أنوال', 'مصدر', '', 'ءنوال', 'نل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23440, 'مُنَافَحَةٌ', 'منافحة', 'مصدر', 'نفح', 'منافحة', 'منفحة', 'مص. نَافَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَافَحَةٌ-مُنَافَحَةٌ [ن ف ح] (مص. نَافَحَ). 1.""الْمُنَافَحَةُ عَنْ حُقُوقِ الإِنْسَانِ"" : النِّضَالُ وَالكِفَاحُ عَنْهَا. 2.""الْمُنَافَحَةُ عَنِ الأَفْكَارِ النَّبِيلَةِ"" : الدِّفَاعُ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23441, 'مُنَافَسَةٌ', 'منافسة', 'مصدر', 'نفس', 'منافسة', 'منفسة', 'مص. نَافَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَافَسَةٌ-مُنَافَسَةٌ [ن ف س] (مص. نَافَسَ). ""مُنَافَسَةٌ رِيَاضِيَّةٌ"" : مُبَارَاةٌ رِيَاضِيَّةٌ، أَيْ بَذْلُ كَلِّ الجُهُودِ لِتَحْقِيقِ التَّفَوُّقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23442, 'مُنَافَقَةٌ', 'منافقة', 'مصدر', 'نفق', 'منافقة', 'منفقة', 'مص. نَافَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَافَقَةٌ-مُنَافَقَةٌ [ن ف ق] (مص. نَافَقَ). ""تَجَنُّبُ الْمُنَافَقَةِ"" : أَيِ النِّفَاقِ، إِظْهَارُ خِلاَف ما يُخْفِيهِ الْمَرْءُ في نَفْسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23443, 'نِفَاقٌ', 'نفاق', 'مصدر', 'نفق', 'نفاق', 'نفق', 'مص. نَافَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نِفَاقٌ-نِفَاقٌ [ن ف ق] (مص. نَافَقَ). 1.""إِيَّاكَ وَالنِّفَاقَ فَإِنَّهُ يُفْسِدُ النَّفْسَ"" : إِظْهَارُ الْمَرْءِ خِلاَفَ مَا يُبْطِنُ. 2. ""أَظْهَرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23444, 'مُنَاقَشَةٌ', 'مناقشة', 'مصدر', 'نقش', 'مناقشة', 'منقشة', 'مص. نَاقَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. نَاقَشَ). ""بَدَءُوا مُنَاقَشَةً حَوْلَ قَضَايَا الْمُجْتَمَعِ"" : حِوَاراً وَبَحْثاً مِنْ أَجْلِ الوُصُولِ إِلَى نَتَائِجَ. ""مُنَاقَشَةٌ عِلْمِيَّةٌ"" l ""دَارَتِ الْمُنَاقَشَةُ فِي جَوٍّ مِنَ الوِئَامِ والاحْتِرَامِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23445, 'نِقَاشٌ', 'نقاش', 'مصدر', 'نقش', 'نقاش', 'نقش', 'مص. نَاقَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. نَاقَشَ). ""اِسْتَمَرَّ النِّقَاشُ بَيْنَ الْمُؤْتَمِرِينَ فَتْرَةً طَوِيلَةً"" : الْجِدَالُ وَالتَّحَاوُرُ. ""لَمْ يَكُنْ نِقَاشُهُمْ بِلاَ فَائِدَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23446, 'مُنَاقَضَةٌ', 'مناقضة', 'مصدر', 'نقض', 'مناقضة', 'منقضة', 'مص. نَاقَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَاقَضَةٌ-مُنَاقَضَةٌ [ن ق ض] (مص. نَاقَضَ). ""أَبَانَتْ مَوَاقِفُهُ عَنْ مُنَاقَضَةٍ وَاضِحَةٍ"" : عَنْ تَنَاقُضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23447, 'نَوَالٌ', 'نوال', 'مصدر', 'نول', 'نوال', 'نل', 'مص. نَالَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَوَالٌ-نَوَالٌ [ن و ل] (مص. نَالَ). 1.""هَذَا مِنْ نَوَالِهِ"" : مِنْ نَصِيبِهِ. 2.""كَثِيرُ النَّوَالِ"" : كَثِيرُ الْعَطَاءِ. 3.""لَيْسَ ذَلِكَ بِنَوَالٍ"" : مَا يُمْكِنُ الْحُصُولُ عَلَيْهِ. 4.""مَنْ طَلَبَ الْمُحَالَ لاَ يَحْظَى بِنَوَالٍ"". (مثل) : مَنْ طَلَبَ الْمُحَالَ لاَ يَحْظَى بِشَيْءٍ. ""أَجَلُّ النَّوَالِ مَا وَصَلَ قَبْلَ السُّؤَالِ"". 5.""نَوَالُ"" : اِسْمُ عَلَمٍ لِلإِناثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23448, 'نَوْلٌ', 'نول', 'مصدر', 'نول', 'نول', 'نل', 'مص. نَالَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْوَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَالَ). 1. : خَشَبَةُ الْحَائِكِ أَوْ آلَتُهُ تُسْتَعْمَلُ لِنَسْجِ الثَّوْبِ عَلَيْهَا. 2.""نَوْلَكَ أَنْ تَفْعَلَ كَذَا"" : يَنْبَغِي لَكَ. ""مَا نَوْلُكَ أَنْ تَفْعَلَ مَا يَشِينُـكَ"" مَا نَوْلُ امْرِئٍ مُسْلِمٍ أَنْ يَقُولَ غَيْرَ الصَّوَابِ (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23449, 'تَنْبِئَةٌ', 'تنبئة', 'مصدر', 'نبأ', 'تنبءة', 'تنبة', 'مص. نَبَّأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَنْبِئَةٌ-تَنْبِئَةٌ [ن ب أ] (مص. نَبَّأَ). ""سَهَا عَنْ تنْبِئَتِهِ بِآخِرِ خَبَرٍ"": إِخْبَارِهِ، إِعْلاَمِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23450, 'نَيْلٌ', 'نيل', 'مصدر', 'نول', 'نيل', 'نل', 'مص. نَالَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَيْلٌ-نَيْلٌ [ن و ل] (مص. نَالَ). ""كَانَ نَيْلُهُ لِلْفَوْزِ عَنِ اسْتِحْقَاقٍ"" : إِدْرَاكُهُ، بُلُوغُهُ. ""مَا نَيْلُ الْمَطَالِبِ بِالتَّمَنِّي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23451, 'نَوْمٌ', 'نوم', 'مصدر', 'نوم', 'نوم', 'نم', 'مص. نَامَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُوَمٌ-نُوَمٌ [ن و م]. ""رَجُلٌ نُوَمٌ"" : كَثِيرُ النَّوْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23452, 'مُنَاهَضَةٌ', 'مناهضة', 'مصدر', 'نهض', 'مناهضة', 'منهضة', 'مص. نَاهَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَاهَضَةٌ-مُنَاهَضَةٌ [ن هـ ض] (مص. نَاهَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23453, 'نَوْهٌ', 'نوه', 'مصدر', 'نمه', 'نوه', 'نه', 'مص. نَاهَ، يَنُوهُ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَوْهٌ-نَوْهٌ [ن م هـ] (مص. نَاهَ، يَنُوهُ). ""نَوْهُ العَمَلِ"" : الِانْتِهَاءُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23454, 'مُنَاوَأَةٌ', 'مناوأة', 'مصدر', 'نوأ', 'مناوءة', 'منة', 'مص. نَاوَأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَاوَأَةٌ-مُنَاوَأَةٌ [ن و أ] (مص. نَاوَأَ). 1.""مُنَاوَأَةُ الْخُصُومِ والأَعْدَاءِ"" : مُنَاوَشَتُهُمْ، مُعَادَاتُهُمْ. 2.""مُنَاوَأَةُ سِيَاسَةِ الْحُكُومَةِ"": مُعَارَضَتُهَا، مُعَاكَسَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23455, 'مُنَاوَبَةٌ', 'مناوبة', 'مصدر', 'نوب', 'مناوبة', 'منبة', 'مص. نَاوَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُنَاوَبَةٌ-مُنَاوَبَةٌ [ن وب] (مص. نَاوَبَ). ""الْمُنَاوَبَةُ عَلَى الحِرَاسَةِ"" : القِيَامُ بِالحِرَاسَةِ بِالتَّنَاوُبِ. ""بِالْمُنَاوَبَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23456, 'مُنَاوَرَةٌ', 'مناورة', 'مصدر', 'نور', 'مناورة', 'منرة', 'مص. نَاوَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. نَاوَرَ). 1.""قَامَ بِمُنَاوَرَةٍ لِلْوُصُولِ إِلَى هَدَفِهِ"" : خُطَّةٍ قَائِمَةٍ عَلَى الخِدَاعِ والْمُرَاوَغَةِ لإِفْسَادِ مَا يُدَبِّرُهُ العَدُوُّ أَوِ الْمُعَارِضُ. ""لَمْ يَكُنْ بَيْنَهُمَا مِنَ القَطِيعَةِ مَا يُلْجِئُهُ إِلَى الحِيلَةِ والْمُنَاوَرَةِ"". (ع. م. العقاد). 2.""أَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23457, 'مُنَاوَشَةٌ', 'مناوشة', 'مصدر', 'نوش', 'مناوشة', 'منشة', 'مص. نَاوَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. نَاوَشَ). 1.""أُخْبِرَ بِوُقُوعِ مُنَاوَشَاتٍ عَلَى الْحُدُودِ"" : وُقُوعُ اشْتِبَاكَاتٍ مَحْدُودَةٍ. 2.""مُنَاوَشَةٌ كَلاَمِيَّةٌ"" : جِدَالٌ، نِزَاعٌ مَحْدُودٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23458, 'نَأْيٌ', 'نأي', 'مصدر', 'نأي', 'نءي', 'ن', 'مص. نأى', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَأْيٌ-نَأْيٌ [ن أ ي] (مص. نأى). ""لَمْ يُطِقِ النَّأْيَ عَنْ بِلاَدِهِ"": البُعْدَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23459, 'نَبْضٌ', 'نبض', 'مصدر', 'نبض', 'نبض', 'نبض', 'مص. نَبَضَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَبْضٌ-نَبْضٌ [ن ب ض] (مص. نَبَضَ). 1.""نَبْضُ القَلْبِ"": ضَرَبَاتُهُ وَدَقَّاتُهُ الْمُتَتَالِيَةُ. 2. ""هُوَ نَبْضُ الْفُؤَادِ"" : ذَكِيٌّ. 3.""فُؤَادٌ نَبْضٌ"" : شَهْمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23460, 'نَبْوَةٌ', 'نبوة', 'مصدر', 'نبو', 'نبوة', 'نبة', 'مص. نَبَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُبُوَّةٌ-نُبُوَّةٌ [ن ب أ]. : هُنا أُبْدِلَتِ الْهَمْزَةُ وَاواً وَأُدْغِمَتْ. ن.نُبُوءةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23461, 'نَبَاتٌ', 'نبات', 'مصدر', 'نبت', 'نبات', 'نبت', 'مص. نَبَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. نَبَتَ). 1. : كُلُّ مَا تُنْبِتُهُ الأَرْضُ مِنْ عُشْبٍ أَوْ شَجَرٍ. 2.""عِلْمُ النَّبَاتِ"" : عِلْمٌ يَبْحَثُ فِي فَصَائِلِ النَّبَاتِ وَخَاصِّيَاتِهِ وَمَنَابِتِهِ. 3.""نَبَاتُ الأَفْكَارِ"" : نَشْأَتُهَا، تَرَعْرُعُهَا، تَنَامِيهَا. ""لَيْسَ غِذَاءُ الطَّعَامِ بِأَسْرَعَ فِي نَبَاتِ الْجَسَدِ مِنْ غِذَاءِ الأَدَبِ فِي نَبَاتِ العَقْلِ"". (ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23462, 'نَبْتٌ', 'نبت', 'مصدر', 'نبت', 'نبت', 'نبت', 'مص. نَبَتَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَبْتٌ-نَبْتٌ، ةٌ [ن ب ت] (مص. نَبَتَ). ""نَبْتُ الأَرْضِ"" : نَبَاتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23463, 'نَبْتَةٌ', 'نبتة', 'مصدر', 'نبت', 'نبتة', 'نبتة', 'مص. نَبَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَبْتٌ-نَبْتٌ، ةٌ [ن ب ت] (مص. نَبَتَ). ""نَبْتُ الأَرْضِ"" : نَبَاتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23464, 'نُبَاحٌ', 'نباح', 'مصدر', 'نبح', 'نباح', 'نبح', 'مص. نَبَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُبَاحٌ-نُبَاحٌ [ن ب ح] (مص. نَبَحَ). ""نُبَاحُ الكِلاَبِ"": صَوْتُهَا. ""يُرْجِفُنِي أَنْ أَسْمَعَ النُّبَاحَ"". (نزار قباني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23465, 'نَبْحٌ', 'نبح', 'مصدر', 'نبح', 'نبح', 'نبح', 'مص. نَبَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَبْحٌ-نَبْحٌ [ن ب ح] (مص. نَبَحَ). ""نَبْحُ الْكَلْبِ"" : عُوَاؤُهُ، صِيَاحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23466, 'نَبْذٌ', 'نبذ', 'مصدر', 'نبذ', 'نبذ', 'نبذ', 'مص. نَبَذَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَبْذٌ-نَبْذٌ [ن ب ذ] (مص. نَبَذَ). ""نَبْذُ العَهْدِ"" : نَقْضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23467, 'نَبْرٌ', 'نبر', 'مصدر', 'نبر', 'نبر', 'نبر', 'مص نَبَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَبْرٌ-نَبْرٌ [ن ب ر] (مص نَبَرَ). ""النَّبْرُ فِي القِرَاءةِ"" : إِبْرَازُ أَحَدِ مَقَاطِعِ الكَلِمَةِ عِنْدَ النُّطْقِ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23468, 'نَبَضَانٌ', 'نبضان', 'مصدر', 'نبض', 'نبضان', 'نبضن', 'مص. نَبَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَبَضَانٌ-نَبَضَانٌ [ن ب ض] (مص. نَبَضَ). ""نَبَضَانُ القَلْبِ"" : ضَرَبَاتُهُ وَدَقَّاتُهُ الْمُتَتَالِيَةُ، نَبْضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23469, 'تَنْبِيهٌ', 'تنبيه', 'مصدر', 'نبه', 'تنبيه', 'تنبه', 'مص. نَبَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْبِيهٌ-تَنْبِيهٌ [ن ب هـ] (مص. نَبَّهَ). ""كَانَ لاَ بُدَّ مِنْ تَنْبِيهِ ذَلِكَ الغَافِلِ"" : مِنْ إنْذَارِهِ، إخْطَارِهِ، إعْلاَمِهِ. ""كُلُّ هَذِهِ العَلامَاتِ مِنْ أَجْلِ تَنْبِيهِ السَّائِقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23470, 'نَبْعٌ', 'نبع', 'مصدر', 'نبع', 'نبع', 'نبع', 'مص. نَبَعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَبْعٌ-نَبْعٌ، ةٌ [ن ب ع] (مص. نَبَعَ). 1.""يَشْرَبُ مِنَ النَّبْعِ"": عَيْنُ الْمَاءِ‎. إِنِّي وَرَدْتُ عُيُونَ الْمَاءِ صَـافِيَةً*نَبْعـاً فَنَبْعاً فَمَا كَانَتْ لِتَرْوِيَنِي (م.م. الجواهري). 2.""نَبْعٌ مَعْدِنِيٌّ"" : عَيْنُ مِيَاهٍ مَعْدِنِيَّةٍ. 3.""صَلِيبُ النَّبْعِ"" : شَدِيدُ الْمِرَاسِ. 4. : شَجَرٌ صَلْبٌ تُتَّخَذُ مِنْهُ السِّهَامُ وَالقِسِيُّ. 5.""هُوَ مِنْ نَبْعَةٍ كَرِيمَةٍ"" : مِنْ أَرُومَةٍ أَصِيلَةٍ. 6.""مَا رَأَيْتُ أَصْلَبَ نَبْعَةً مِنْهُ"" : أَشَدَّ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23471, 'نَبْعَةٌ', 'نبعة', 'مصدر', 'نبع', 'نبعة', 'نبعة', 'مص. نَبَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَبْعٌ-نَبْعٌ، ةٌ [ن ب ع] (مص. نَبَعَ). 1.""يَشْرَبُ مِنَ النَّبْعِ"": عَيْنُ الْمَاءِ‎. إِنِّي وَرَدْتُ عُيُونَ الْمَاءِ صَـافِيَةً*نَبْعـاً فَنَبْعاً فَمَا كَانَتْ لِتَرْوِيَنِي (م.م. الجواهري). 2.""نَبْعٌ مَعْدِنِيٌّ"" : عَيْنُ مِيَاهٍ مَعْدِنِيَّةٍ. 3.""صَلِيبُ النَّبْعِ"" : شَدِيدُ الْمِرَاسِ. 4. : شَجَرٌ صَلْبٌ تُتَّخَذُ مِنْهُ السِّهَامُ وَالقِسِيُّ. 5.""هُوَ مِنْ نَبْعَةٍ كَرِيمَةٍ"" : مِنْ أَرُومَةٍ أَصِيلَةٍ. 6.""مَا رَأَيْتُ أَصْلَبَ نَبْعَةً مِنْهُ"" : أَشَدَّ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23472, 'نُبُوغٌ', 'نبوغ', 'مصدر', 'نبغ', 'نبوغ', 'نبغ', 'مص. نَبَغَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُبُوغٌ-نُبُوغٌ [ن ب غ] (مص. نَبَغَ). ""ظَهَرَ نُبُوغُهُ"" : بَرَاعَتُهُ وَإِجَادَتُهُ، اِتِّسَاعُ فِكْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23473, 'نَبْلٌ', 'نبل', 'مصدر', 'نبل', 'نبل', 'نبل', 'مص. نَبَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"(مص. نَبَلَ). ""رَمَى نَبْلَهُ وَأَصَابَ هَدَفَهُ"" : سَهْمَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23474, 'نَبْلَةٌ', 'نبلة', 'مصدر', 'نبل', 'نبلة', 'نبلة', 'مص. نَبَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نِبَالٌ:أَنْبَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَبَلَ). ""رَمَى نَبْلَهُ وَأَصَابَ هَدَفَهُ"" : سَهْمَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23475, 'نِبَالٌ', 'نبال', 'مصدر', '', 'نبال', 'نبل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23476, 'أَنْبَالٌ', 'أنبال', 'مصدر', '', 'ءنبال', 'نبل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23477, 'نَبَالَةٌ', 'نبالة', 'مصدر', 'نبل', 'نبالة', 'نبلة', 'مص. نَبُلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَبَالَةٌ-نَبَالَةٌ [ن ب ل] (مص. نَبُلَ). 1.""وَلَدٌ مَعْرُوفٌ بِنَبَالَتِـهِ"" : بِذَكَائِهِ، بِنَجَابَتِهِ. 2.""يَتَّسِمُ بِالنَّبَالَةِ"" : بِالشَّرَفِ وَالْفَضْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23478, 'نُبْلٌ', 'نبل', 'مصدر', 'نبل', 'نبل', 'نبل', 'مص. نَبُلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُبْلٌ-نُبْلٌ [ن ب ل] (مص. نَبُلَ). ""مَعْرُوفٌ بِنُبْلِ أَخْـلاَقِـهِ"" : بِسُمُوِّ أَخْلاَقِهِ وَشَرَفِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23479, 'نَثِيثٌ', 'نثيث', 'مصدر', 'نثث', 'نثيث', 'نثث', 'مص. نَثَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَثِيثٌ-نَثِيثٌ [ن ث ث] (مص. نَثَّ). ""نَثِيثُ الإِنَاءِ"" : رَشْحُهُ. ""نَثِيثُ الْمَطَرِ يَرُشُّ رُؤُوسَنَا"". (محمد برادة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23480, 'نَبَاهَةٌ', 'نباهة', 'مصدر', 'نبه', 'نباهة', 'نبهة', 'مص. نَبَهَ، نَبُهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَبَاهَةٌ-نَبَاهَةٌ [ن ب هـ] (مص. نَبَهَ، نَبُهَ). ""نَبَاهَةُ وَلَدٍ"" : فِطْنَتُهُ، ذَكَاؤُهُ، نَجَابَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23481, 'نُتُوءٌ', 'نتوء', 'مصدر', 'نتأ', 'نتوء', 'نت', 'مص. نَتَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"نُتُوءٌ-نُتُوءٌ [ن ت أ] (مص. نَتَأَ). ""جَبَلٌ بِهِ نُتُوءٌ"" : بُرُوزُ جُزْءٍ مِنْهُ مُتَّصِلٍ بِهِ. ""نُتُوءٌ عَظْمِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23482, 'نَتْحٌ', 'نتح', 'مصدر', 'نتح', 'نتح', 'نتح', 'مص. نَتَحَ', '', '', 'مفرد', 'DnN', '', '', '"نُتُوحٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَتَحَ). ""رَشَحَ نَتْحُـهُ"" : عَرَقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23483, 'نُتُوحٌ', 'نتوح', 'مصدر', '', 'نتوح', 'نتح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23484, 'تَنْتِيفٌ', 'تنتيف', 'مصدر', 'نتف', 'تنتيف', 'تنتف', 'مص. نَتَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْتِيفٌ-تَنْتِيفٌ [ن ت ف] (مص. نَتَّفَ). ""تَنْتِيفُ الشَّعْرِ"" : نَزْعُهُ، نَتْفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23485, 'نَتْفٌ', 'نتف', 'مصدر', 'نتف', 'نتف', 'نتف', 'مص. نَتَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَتْفٌ-نَتْفٌ [ن ت ف] (مص. نَتَفَ). ""نَتْفُ الشَّعْرِ"" : نَزْعُهُ. ""نَتْفُ الرِّيشِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23486, 'تَنْتِينٌ', 'تنتين', 'مصدر', 'نتن', 'تنتين', 'تنتن', 'مص. نَتَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْتِينٌ-تَنْتِينٌ [ن ت ن] (مص. نَتَّنَ). ""تَنْتِينُ اللَّحْمِ"" : تَصْيِيرُهُ نَتِناً أَوْ صَيْرُهُ نَتِناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23487, 'نَتْنٌ', 'نتن', 'مصدر', 'نتن', 'نتن', 'نتن', 'مص. نَتُنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَتْنٌ-نَتْنٌ [ن ت ن] (مص. نَتُنَ). 1.""لَحْمٌ نَتْنٌ"" : كَرِيهُ الرَّائِحَةِ. 2.""مَعْدِنٌ نَتْنٌ"" : فَاسِدٌ. ""وَإِنَّ النَّمِيمَةَ لَطَبْعٌ يَدُلُّ عَلَى نَتْنِ الأَصْلِ وَرَدَاءةِ الفَرْعِ"". (ابن حزم)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23488, 'نُتُونَةٌ', 'نتونة', 'مصدر', 'نتن', 'نتونة', 'نتنة', 'مص. نَتُنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُتُونَةٌ-نُتُونَةٌ [ن ت ن] (مص. نَتُنَ). ""نُتُونَةُ رَائِحَةٍ"" : رَائِحَتُهَا الكَرِيهَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23489, 'نَجْبٌ', 'نجب', 'مصدر', 'نجب', 'نجب', 'نجب', 'مص. نَجَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَجَبٌ-نَجَبٌ [ن ج ب]. ""نَجَبُ الشَّجَرَةِ"" : قِشْرُهَا، لِحَاؤُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23490, 'نِثَارٌ', 'نثار', 'مصدر', 'نثر', 'نثار', 'نثر', 'مص. نَثَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نِثَارٌ-نِثَارٌ [ن ث ر] (مص. نَثَرَ). 1.""نِثَارُ الْمَائِدَةِ"" : مَا تَنَاثَرَ حَوْلَهَا مِنْ فُتَاتٍ. 2.""نِثَارُ الْحِنْطَةِ"" : مَا انْتَشَرَ مِنْهَا. 3.""نِثَارُ العُرْسِ"" : مَا يُنْثَرُ عَلَى الْمَدْعُوِّينَ فِي عُرْسٍ مِنْ حَلْوَى أَوْ نُقُودٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23491, 'نَثْرٌ', 'نثر', 'مصدر', 'نثر', 'نثر', 'نثر', 'مص. نَثَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَثْرٌ-نَثْرٌ [ن ث ر] (مص. نَثَرَ). ""يَكْتُبُ نَثْراً جَمِيلاً"" : كَلاَماً مُرْسَلاً بِلاَ وَزْنٍ وَلاَ قَافِيَةٍ. ""النَّثْرُ العَرَبِيُّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23492, 'نَجْوٌ', 'نجو', 'مصدر', 'نجو', 'نجو', 'نج', 'مص نَجَا', '', '', 'مفرد', 'DnN', '', '', '"نِجَاءٌ:نُجُوٌّ"', '', 'R', '', '', '', '', '', '', '"(مص نَجَا). 1.""كَانَ نَجْوُهُ سِرّاً مِنَ الأَسْرَارِ"" : السِّرُّ بَيْنَ اثْنَيْنِ. 2. : مَا يَخْرُجُ مِنْ رِيحٍ أَوْ غَائِطٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23493, 'نِجَاءٌ', 'نجاء', 'مصدر', '', 'نجاء', 'نج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23494, 'نُجُوٌّ', 'نجو', 'مصدر', '', 'نجو', 'نج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23495, 'نَجَاةٌ', 'نجاة', 'مصدر', 'نجو', 'نجاة', 'نجة', 'مص. نَجَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rw', '', '', '', '', '', '', '"نَجَاةٌ-نَجَاةٌ [ن ج و] (مص. نَجَا). 1.""يَبْحَثُ عَنْ مَكَانٍ لِلنَّجَاةِ بِنَفْسِهِ"" : عَنْ مَكَانٍ يُخَلِّصُهُ مِنَ الأَذَى، مَكَانُ الْخَلاَصِ. 2.""طَوْقُ النَّجَاةِ"" : مَا يَضَعُهُ السَّابِحُ مِنْ مَطَّاطٍ حَوْلَهُ لِيُنَجِّيَهُ مِنَ الغَرَقِ. 3.""زَوْرَقُ النَّجَاةِ"" : زَوْرَقٌ يُسْرِعُ لإِنْقَاذِ مَنْ كَانَ عَلَى حَافَّةِ الغَرَقِ. ""وَامْتَلأ القَارِبُ كَأَنَّنَا غَرْقَى فِي زَوْرَقِ النَّجَاةِ"". (توفيق الحكيم). 4.""نَجَاة"" : اِسْمُ عَلَمٍ لِلْإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23496, 'نَجْوَى', 'نجوى', 'مصدر', 'نجو', 'نجوى', 'نج', 'مص. نَجَا', '', '', 'مفرد', 'Dy', '', '', '"نَجَاوَى"', 'ممنوع من الصرف', 'R0', '', '', '', '', '', '', '"(مص. نَجَا). 1.""نَجْوَى النَّفْسِ"" : حَدِيثُهَا، أَيْ مَا يُوَجِّهُهُ الْمَرْءُ مِنْ حَدِيثٍ إِلَى نَفْسِهِ. المجادلة آية 10 إِنَّمَا النَّجْوَى مِنَ الشَّيْطَانِ (قرآن). 2.""نَجْوَى الْمُمَثِّلِ"" : الْحِوَارُ الدَّاخِلِيُّ الَّذِي يُوَجِّهُهُ إِلَى نَفْسِهِ حِينَ يَكُونُ وَحِيداً عَلَى خَشَبَةِ الْمَسْرَحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23497, 'نَجَاوَى', 'نجاوى', 'مصدر', '', 'نجاوى', 'نج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23498, 'نَجَابَةٌ', 'نجابة', 'مصدر', 'نجب', 'نجابة', 'نجبة', 'مص. نَجَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَجَابَةٌ-نَجَابَةٌ [ن ج ب] (مص. نَجَبَ). ""ظَهَرَتْ عَلَيْهِ عَلاَمَةُ النَّجَابَةِ"" : النَّبَاهَةُ، الفِطْنَةُ. ""تَوَسَّمَ فِيهِ النَّجَابَةَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23499, 'تَنْجيحٌ', 'تنجيح', 'مصدر', 'نجح', 'تنجيح', 'تنجح', 'مص. نَجَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْجيحٌ-تَنْجيحٌ [ن ج ح] (مص. نَجَّحَ).""لاَ يَرْغَبُ فِي تَنْجِيحِهِ دُونَ اسْتِحْقَاقٍ"" : إِنْجاحُهُ، جَعْلُهُ يَنْجَحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23500, 'نجَاحٌ', 'نجاح', 'مصدر', 'نجح', 'نجاح', 'نجح', 'مص. نَجَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نجَاحٌ-نجَاحٌ [ن ج ح] (مص. نَجَحَ). 1.""تَكَلَّلَ عَمَلُهُ بِالنَّجَاحِ"" : بِالتَّوْفِيقِ، الظَّفَر، الفَوْز، السَّدَاد. ""نَجَحَ كُلَّ النَّجَاحِ فِي تَحْوِيلِ الأَنْظَارِ إِلَيْهِ"". 2.""لَقِيَ نَجَاحاً فِي عَمَلِهِ"" : سُهُولُةً، يُسْراً. ""عَلَيَّ أَنْ أَسْعَى وَلَيْسَ عَلَيَّ إِدْرَاكُ النَّجَاحِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23501, 'تَنْجِيدٌ', 'تنجيد', 'مصدر', 'نجد', 'تنجيد', 'تنجد', 'مص. نَجَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْجِيدٌ-تَنْجِيدٌ [ن ج د] (مص. نَجَّدَ). 1.""تَنجِيدُ البَيْتِ"" : تَزْيِينُهُ بِالبِسَاطِ وَالفِرَاشِ. 2.""تَنْجِيدُ الأَفْرِشَةِ"" : خِيَاطَتُهَا، مُعَالَجَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23502, 'نَجْدٌ', 'نجد', 'مصدر', 'نجد', 'نجد', 'نجد', 'مص. نَجَدَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْجُدٌ:نِجَادٌ:نُجُودٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَجَدَ). 1.""مَكَانٌ نَجْدٌ"" : مُشْرِفٌ، مُرْتَفِعٌ. 2.""نَجْدُ الْبَيْتِ"" : مَا يُزَيَّنُ بِهِ مِنْ فُرُشٍ وَوَسَائِدَ. 3.""رَجُلٌ نَجْدٌ"" : شُجَاعٌ، سَرِيعُ الإِجَابَةِ. 4.""أَمْرٌ نَجْدٌ"" : وَاضِحٌ مُسْتَبِينٌ. 5.""نَجْدٌ"" : إِقْلِيمٌ مِنْ أَقالِيمِ الْمَمْلَكَةِ العَرَبِيَّةِ السَّعُودِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23503, 'أَنْجُدٌ', 'أنجد', 'مصدر', '', 'ءنجد', 'نجد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23504, 'نِجَادٌ', 'نجاد', 'مصدر', '', 'نجاد', 'نجد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23505, 'نُجُودٌ', 'نجود', 'مصدر', '', 'نجود', 'نجد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23506, 'نَجَدٌ', 'نجد', 'مصدر', 'نجد', 'نجد', 'نجد', 'مص. نَجِدَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْجَادٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَجِدَ). 1.""رَشَحَ نَجَدُهُ"" : عَرَقُهُ. 2.""بَيْتٌ مَمْلُوءٌ بِالنَّجَدِ"" : مَتَاعُ الْبَيْتِ مِنْ فُرُشٍ وَوَسَائِدَ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23507, 'أَنْجَادٌ', 'أنجاد', 'مصدر', '', 'ءنجاد', 'نجد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23508, 'نُجُودٌ', 'نجود', 'مصدر', 'نجد', 'نجود', 'نجد', 'مص. نَجَدَ، نَجُدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُجُودٌ-نُجُودٌ [ن ج د] (مص. نَجَدَ، نَجُدَ). ""نُجُودُ الْبَيْتِ"" : سُتُورٌ تُعَلَّقُ عَلَى جُدْرَانِ الْبَيْتِ لِيُزَيَّنَ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23509, 'نَجْرٌ', 'نجر', 'مصدر', 'نجر', 'نجر', 'نجر', 'مص. نَجَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَجْرٌ-نَجْرٌ [ن ج ر] (مص. نَجَرَ). ""نَجْرُ الْخَشَبِ"" : نَحْتُهُ، صَنْعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23510, 'نَجْزٌ', 'نجز', 'مصدر', 'نجز', 'نجز', 'نجز', 'مص نَجَزَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَجْزٌ-نَجْزٌ [ن ج ز] (مص نَجَزَ). ""نَجْزُ عَمَلٍ"" : إِتْمَامُهُ، إِنْجَازُهُ، تَنْفِيذُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23511, 'تَنْجِيزٌ', 'تنجيز', 'مصدر', 'نجز', 'تنجيز', 'تنجز', 'مص. نَجَّزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْجِيزٌ-تَنْجِيزٌ [ن ج ز] (مص. نَجَّزَ). ""تَنَجِيزُ مُهِمَّةٍ"" : نَجْزُهَا، قَضَاؤُهَا، إتْمَامُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23512, 'تَنْجِيسٌ', 'تنجيس', 'مصدر', 'نجس', 'تنجيس', 'تنجس', 'مص. نَجَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْجِيسٌ-تَنْجِيسٌ [ن ج س] (مص. نَجَّسَ). ""تَنْجِيسُ الْمَكَانِ"": تَصْيِيرُهُ نَجِساً، قَذِراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23513, 'نَجَاسَةٌ', 'نجاسة', 'مصدر', 'نجس', 'نجاسة', 'نجسة', 'مص. نَجُسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. نَجُسَ). 1.""وَجَدَ بالْمَكَانِ نَجَاسَةً"" : قَذَارَةً. 2.""كَيْفَ يُصَلِّي وَبِهِ نَجَاسَةٌ"" : إِذا مَسَّ جَسَدَهُ أَوْ ثَوْبَهُ رَوْثٌ أَوْ بَوْلٌ أَوْ دَمٌ أَوْ خَمْرٌ وَمَا شَابَهَ ذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23514, 'نَجَسٌ', 'نجس', 'مصدر', 'نجس', 'نجس', 'نجس', 'مص. نَجِسَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْجَاسٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَجِسَ). 1.""ثَوْبٌ نَجَسٌ"" : بِهِ نَجَاسَةٌ. 2. ""وَلَدٌ نَجَسٌ"" : قَذِرٌ، أَيْ غَيْرُ طَاهِرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23515, 'أَنْجَاسٌ', 'أنجاس', 'مصدر', '', 'ءنجاس', 'نجس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23516, 'نَجْلٌ', 'نجل', 'مصدر', 'نجل', 'نجل', 'نجل', 'مص. نَجَلَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْجَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَجَلَ). 1.""نَجْلُهُ الأَكْبَرُ"" : وَلَدُهُ . 2.""هُوَ مِنْ نَجْلِهِ "": مِنْ نَسْلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23517, 'أَنْجَالٌ', 'أنجال', 'مصدر', '', 'ءنجال', 'نجل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23518, 'نَجْمٌ', 'نجم', 'مصدر', 'نجم', 'نجم', 'نجم', 'مص نَجَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نُجُومٌ:أَنْجُمٌ"', '', 'R', '', '', '', '', '', '', '"(مص نَجَمَ). 1.""ظَهَرَ النَّجْمُ فِي السَّمَاءِ"" : أَحَدُ الأَجْرَامِ السَّمَاوِيَّةِ الْمُضِيئَةِ بِذَاتِهَا وَتَكُونُ مَوَاضِعُهَا النِّسْبِيَّةُ مِنَ السَّمَاءِ ثَابِتَةٌ. وَمِنْهَا الشَّمْسُ. ""النُّجُومُ وَبُرُوجُهَا وَحِسَابُهَا الَّذِي يُعْرَفُ بِهِ الأَوْقَاتُ وَالأَزْمِنَةُ"". (الجاحظ). 2.""نُجُومُ السَّمَاءِ"" : الكَوَاكِبُ. النجم آية 1 وَالنَّجْمِ إِذَا هَوَى (قرآن) : الثُّرَيَّا. 4.""النَّجْمُ القُطْبِيُّ"" : هُوَ الْجُرْمُ النَّيِّرُ الَّذِي تَتَحَدَّدُ بِهِ جِهَةُ الشَّمَالِ وَيَكُونُ فيِ طَرَفِ ذَنَبِ بَنَاتِ نَعْشٍ الصُّغْرَى. 5.""نَجْمُهُ فِي صُعُودٍ"" : أَيْ نَجَاحُهُ فِي اسْتِمْرَارٍ دَائِمٍ. ""عَلاَ نَجْمُهُ"". 6.""نَجْمٌ سِنِيمَائِيٌّ"" : صِفَةٌ تُطْلَقُ عَلَى مَنِ اشْتَهَرَ مِنَ الفَنَّانِيَن. ""نَجْمَةٌ سِينِمَائِيَّةٌ"". 7.""نَبَاتٌ نَجْمٌ"" : مَا لاَ سَاقَ لَهُ. الرحمن آية 6وَالنَّجْمُ وَالشَّجَرُ يَسْجُدَانِ (قرآن). 8.""النَّجْمُ"" : سُورَةٌ مِنْ سُوَرِ الْقُرْآنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23519, 'نَحِيبٌ', 'نحيب', 'مصدر', 'نحب', 'نحيب', 'نحب', 'مص. نَحَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَحِيبٌ-نَحِيبٌ [ن ح ب] (مص. نَحَبَ). ""وَصَلَ نَحِيبُهَا إِلَى سَمْعِهِ"" : بُكَاؤُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23520, 'نَجْمَةٌ', 'نجمة', 'مصدر', 'نجم', 'نجمة', 'نجمة', 'مص نَجَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نُجُومٌ:أَنْجُمٌ"', '', 'R', '', '', '', '', '', '', '"(مص نَجَمَ). 1.""ظَهَرَ النَّجْمُ فِي السَّمَاءِ"" : أَحَدُ الأَجْرَامِ السَّمَاوِيَّةِ الْمُضِيئَةِ بِذَاتِهَا وَتَكُونُ مَوَاضِعُهَا النِّسْبِيَّةُ مِنَ السَّمَاءِ ثَابِتَةٌ. وَمِنْهَا الشَّمْسُ. ""النُّجُومُ وَبُرُوجُهَا وَحِسَابُهَا الَّذِي يُعْرَفُ بِهِ الأَوْقَاتُ وَالأَزْمِنَةُ"". (الجاحظ). 2.""نُجُومُ السَّمَاءِ"" : الكَوَاكِبُ. النجم آية 1 وَالنَّجْمِ إِذَا هَوَى (قرآن) : الثُّرَيَّا. 4.""النَّجْمُ القُطْبِيُّ"" : هُوَ الْجُرْمُ النَّيِّرُ الَّذِي تَتَحَدَّدُ بِهِ جِهَةُ الشَّمَالِ وَيَكُونُ فيِ طَرَفِ ذَنَبِ بَنَاتِ نَعْشٍ الصُّغْرَى. 5.""نَجْمُهُ فِي صُعُودٍ"" : أَيْ نَجَاحُهُ فِي اسْتِمْرَارٍ دَائِمٍ. ""عَلاَ نَجْمُهُ"". 6.""نَجْمٌ سِنِيمَائِيٌّ"" : صِفَةٌ تُطْلَقُ عَلَى مَنِ اشْتَهَرَ مِنَ الفَنَّانِيَن. ""نَجْمَةٌ سِينِمَائِيَّةٌ"". 7.""نَبَاتٌ نَجْمٌ"" : مَا لاَ سَاقَ لَهُ. الرحمن آية 6وَالنَّجْمُ وَالشَّجَرُ يَسْجُدَانِ (قرآن). 8.""النَّجْمُ"" : سُورَةٌ مِنْ سُوَرِ الْقُرْآنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23521, 'نُجُومٌ', 'نجوم', 'مصدر', '', 'نجوم', 'نجم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23522, 'أَنْجُمٌ', 'أنجم', 'مصدر', '', 'ءنجم', 'نجم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23523, 'تَنْجِيمٌ', 'تنجيم', 'مصدر', 'نجم', 'تنجيم', 'تنجم', 'مص. نَجَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْجِيمٌ-تَنْجِيمٌ [ن ج م] (مص. نَجَّمَ). ""يَهْتَمُّ بِعِلْمِ التَّنْجِيمِ"" : مُرَاقَبَةُ النُّجُومِ فِي سَيْرِهَا، تَفْسِيرُ مَطَالِعِ النُّجُومِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23524, 'نَحِيحٌ', 'نحيح', 'مصدر', 'نحح', 'نحيح', 'نحح', 'مص. نَحَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَحِيحٌ-نَحِيحٌ [ن ح ح] (مص. نَحَّ). 1.""نَحِيحُ الرَّجُلِ"" : نَحِيحٌ، الصَّوْتُ الَّذِي يُرَدِّدُهُ فِي جَوْفِهِ. 2.""رَجُلٌ نَحِيحٌ"" : بَخِيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23525, 'تَنْحِيَةٌ', 'تنحية', 'مصدر', 'نحو', 'تنحية', 'تنحة', 'مص. نَحَّا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنْحِيَةٌ-تَنْحِيَةٌ [ن ح و] (مص. نَحَّا). ""حَاوَلَ تَنْحِيَتَهُ مِنْ مَكَانِهِ"": إزَالَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23526, 'نَحْوٌ', 'نحو', 'مصدر', 'نحو', 'نحو', 'نح', 'مص. نَحَا', '', '', 'مفرد', 'DnN', '', '', '"أَنْحَاءٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. نَحَا). 1.""اِتَّجَهَ نَحْوَ الشَّرْقِ"" : جِهَةَ الشَّرْقِ، صَوْبَ. ""اِلْتَفَتَ نَحْوِي"" ""نَحَوْتُ نَحْوَهُ"" ""تَجَوَّلَ فِي أَنْحَاءِ البِلاَدِ"". 2.""عَلَى نَحْوِ مَا يُرِيدُ"" : عَلَى النَّهْجِ أَوِ الطَرِيقَةِ الَّتِي يُرِيدُ. ""عَلَى هَذَا النَّحْوِ"". 3.""زَارَهُ فِي نَحْوِ السَّادِسَةِ"" : فِي السَّادِسَةِ تَقْرِيباً. 4.""النَّحْوُ العَرَبِيُّ"" : قَوَاعِدُ اللُّغَةِ وَ إِعْرَابُ الكَلاَمِ. ""النَّحْوُ الوَظِيفِيُّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23527, 'أَنْحَاءٌ', 'أنحاء', 'مصدر', '', 'ءنحاء', 'نح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23528, 'نَحْبٌ', 'نحب', 'مصدر', 'نحب', 'نحب', 'نحب', 'مص. نَحَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَحْبٌ-نَحْبٌ [ن ح ب] (مص. نَحَبَ). 1.""اِشْتَدَّ نَحْبُهَا"" : اِشْتَدَّ بُكَاؤُهَا. 2.""قَضَى نَحْبَهُ"" : مَاتَ، أَيْ جَاءَ أَجَلُهُ.الأحزاب آية 23 فَمِنْهُمْ مَنْ قَضَى نَحْبَهُ وَمِنْهُمْ مَنْ يَنْتَظِرُ ( قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23529, 'نُحْلٌ', 'نحل', 'مصدر', 'نحل', 'نحل', 'نحل', 'مص. نَحَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُحْلٌ-نُحْلٌ [ن ح ل] (مص. نَحَلَ). 1.""قَدَّمَ لَهُ نُحْلاً"" : عَطِيَّةً مُعْطَاةً تَبَرُّعاً. 2.""هُوَ فِي نُحْلٍ"" : فِي هُزَالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23530, 'نَحْتٌ', 'نحت', 'مصدر', 'نحت', 'نحت', 'نحت', 'مص. نَحَتَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَحْتٌ-نَحْتٌ [ن ح ت] (مص. نَحَتَ). 1.""الْكَرَمُ مِنْ نَحْتِهِ"": مِنْ طَبِيعَتِهِ، مِنْ أَصْلِهِ. 2.""فَنُّ النَّحْتِ"" : فَنٌّ مِنَ الفُنُونِ الْجَمِيلَةِ قَائِمٌ عَلَى نَحْتِ الْخَشَبِ أَوِ الْحَجَرِ أَوالصَّخْرِ أَوِ الْمَعْدِنِ وَتَعْدِيلِهِ وَتَسْوِيَتِهِ حَسَبَ نَمُوذَجٍ مَّا، تِمْثَالٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23531, 'نَحِيتٌ', 'نحيت', 'مصدر', 'نحت', 'نحيت', 'نحت', 'مص. نَحَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَحِيتٌ-نَحِيتٌ، ةٌ [ن ح ت] (مص. نَحَتَ). 1.""عُودٌ نَحِيـتٌ"" : مَنْحُوتٌ. 2.""سَمِعَ نَحِيتَهُ مِنْ بَعِيدٍ"" : أَنِينَهُ. 3.""نَحِيتُ البَطْنِ"": تَقْطِيعُهُ، تَقَلُّصُهُ. 4.""أَمْرٌ نَحِيتٌ"" : رَدِيءٌ. 5.""هُوَ كَرِيمُ النَّحِيتَةِ"" : النَّحِيزَةِ، النَّحِيرَةِ، أَيْ ذُو طَبِيعَةٍ أَصِيلَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23532, 'نَحِيتَةٌ', 'نحيتة', 'مصدر', 'نحت', 'نحيتة', 'نحتة', 'مص. نَحَتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَحِيتٌ-نَحِيتٌ، ةٌ [ن ح ت] (مص. نَحَتَ). 1.""عُودٌ نَحِيـتٌ"" : مَنْحُوتٌ. 2.""سَمِعَ نَحِيتَهُ مِنْ بَعِيدٍ"" : أَنِينَهُ. 3.""نَحِيتُ البَطْنِ"": تَقْطِيعُهُ، تَقَلُّصُهُ. 4.""أَمْرٌ نَحِيتٌ"" : رَدِيءٌ. 5.""هُوَ كَرِيمُ النَّحِيتَةِ"" : النَّحِيزَةِ، النَّحِيرَةِ، أَيْ ذُو طَبِيعَةٍ أَصِيلَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23533, 'نَحْرٌ', 'نحر', 'مصدر', 'نحر', 'نحر', 'نحر', 'مص. نَحَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَحْرٌ-نَحْرٌ [ن ح ر] (مص. نَحَرَ). 1.""نَحَرَهُ مِنْ نَحْرِهِ"" : ذَبَحَهُ مِنْ أَعْلَى الصَّدْرِ، مِن العُنُقِ. 2.""نَحْرُ النَّهَارِ"" : أَوَّلُهُ. 3.""يَوْمُ النَّحْرِ"" : يَوْمُ عِيدِ الأَضْحَى، أَي اليَوْمُ العَاشِرُ مِنْ ذِي الْحِجَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23534, 'تَنْحيسٌ', 'تنحيس', 'مصدر', 'نحس', 'تنحيس', 'تنحس', 'مص. نَحَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْحيسٌ-تَنْحيسٌ [ن ح س] (مص. نَحَّسَ). 1. ""تَنْحِيسُ مَعْدِنٍ"": صَيْرُهُ كَالنُّحَاسِ. 2. ""تَنْحِيسُ الْمَعْدِنِ"" : تَغْشِيَتُهُ بِالنُّحَاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23535, 'نَحْسٌ', 'نحس', 'مصدر', 'نحس', 'نحس', 'نحس', 'مص. نَحَسَ', '', '', 'مفرد', 'DnN', '', '', '"نُحُوسٌ:أَنْحُسٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَحَسَ). ""يَوْمُ نَحْسٍ"" : يَوْمُ شُؤْمٍ. ""أَيَّامُ نَحْسٍ"" ""طَالِعُ نَحْسٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23536, 'نُحُوسٌ', 'نحوس', 'مصدر', '', 'نحوس', 'نحس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23537, 'أَنْحُسٌ', 'أنحس', 'مصدر', '', 'ءنحس', 'نحس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23538, 'نَحَافَةٌ', 'نحافة', 'مصدر', 'نحف', 'نحافة', 'نحفة', 'مص. نَحَفَ، نَحِفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَحَافَةٌ-نَحَافَةٌ [ن ح ف] (مص. نَحَفَ، نَحِفَ). ""نَحَافَةُ جِسْمٍ"" : رِقَّتُهُ، هُزَالُهُ. ""النَّحَافَةُ أنَاقَةُ العَصْرِ عِنْدَ الْمَرْأَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23539, 'نَدٌّ', 'ند', 'مصدر', 'ندد', 'ند', 'ند', 'مص. نَدَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَدٌّ-نَدٌّ [ن د د] (مص. نَدَّ). ""اِنْتَشَرَتْ رَائِحَةُ النَّدِّ فِي الغُرْفَةِ"" : عُودٌ لَهُ رَائِحَةٌ طَيِّبَةٌ يُتَبَخَّرُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23540, 'نَحْلٌ', 'نحل', 'مصدر', 'نحل', 'نحل', 'نحل', 'مص. نَحَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَحْلٌ-نَحْلٌ، ةٌ [ن ح ل] (مص. نَحَلَ). 1. : العَطِيَّةُ. 2.""النَّحْلُ فِيالشِّعْرِ"" : هُوَ قَوْلُ الشِّعْرِ وَنِسْبَتُهُ إِلَىغَيْرِقَائِلِهِ. 3.: حَشَرَةٌ مِنْ فَصِيلَةِ النَّحْلِيَّاتِ. مِنْ رُتْبَةِ غِشَائِيَّاتِ الأَجْنِحَةِ، تَصْنَعُ خَلاَيَا لِنَفْسِهَا، تُرَبَّى لِلْحُصُولِ عَلَى عَسَلِهَـا وَشَمْعِهَـا.النحل آية68 وَأَوْحَى رَبُّكَ إِلَى النَّحْلِ أَنِ اتَّخِذِي مِنَ الْجِبَالِ بُيُوتاً (قرآن) مَثَلُ الْمُؤْمِنِ كَالنَّحْلَةِ، لاَ تَأْكُلْ إِلاَّ طَيِّباً وَلاَ تُطْعِمْ إِلاَّ طَيِّباً (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23541, 'نَحْلَةٌ', 'نحلة', 'مصدر', 'نحل', 'نحلة', 'نحلة', 'مص. نَحَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَحْلٌ-نَحْلٌ، ةٌ [ن ح ل] (مص. نَحَلَ). 1. : العَطِيَّةُ. 2.""النَّحْلُ فِيالشِّعْرِ"" : هُوَ قَوْلُ الشِّعْرِ وَنِسْبَتُهُ إِلَىغَيْرِقَائِلِهِ. 3.: حَشَرَةٌ مِنْ فَصِيلَةِ النَّحْلِيَّاتِ. مِنْ رُتْبَةِ غِشَائِيَّاتِ الأَجْنِحَةِ، تَصْنَعُ خَلاَيَا لِنَفْسِهَا، تُرَبَّى لِلْحُصُولِ عَلَى عَسَلِهَـا وَشَمْعِهَـا.النحل آية68 وَأَوْحَى رَبُّكَ إِلَى النَّحْلِ أَنِ اتَّخِذِي مِنَ الْجِبَالِ بُيُوتاً (قرآن) مَثَلُ الْمُؤْمِنِ كَالنَّحْلَةِ، لاَ تَأْكُلْ إِلاَّ طَيِّباً وَلاَ تُطْعِمْ إِلاَّ طَيِّباً (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23542, 'نُحُولٌ', 'نحول', 'مصدر', 'نحل', 'نحول', 'نحل', 'مص. نَحَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُحُولٌ-نُحُولٌ [ن ح ل] (مص. نَحَلَ). ""نُحُولُ الجِسْمِ"" : هُزَالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23543, 'نَحِيمٌ', 'نحيم', 'مصدر', 'نحم', 'نحيم', 'نحم', 'مص. نَحَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَحِيمٌ-نَحِيمٌ [ن ح م] (مص. نَحَمَ). ""نَحِيمُ الرَّجُلِ"" : نَحِيحٌ، الصَّوْتُ الَّذِي يَخْرُجُ مِنْ جَوْفِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23544, 'نَخْوَةٌ', 'نخوة', 'مصدر', 'نخو', 'نخوة', 'نخة', 'مص. نَخَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَخْوَةٌ-نَخْوَةٌ [ن خ و] (مص. نَخَا). ""يَتَصَرَّفُ بِنَخْوَةٍ"" : بِمُرُوءةٍ، بِاعْتِزَازٍ، بِفَخْرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23545, 'نَخْبٌ', 'نخب', 'مصدر', 'نخب', 'نخب', 'نخب', 'مص. نَخَبَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْخَابٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَخَبَ). ""عَلَى نَخْبِ الضَّيْفِ الكَرِيمِ"" : الشَّرْبَةُ مِنَ العَصِيرِ أَو مَا شَابَهَ ذَلِكَ يَشْرَبُهَا الْحَاضِرُونَ فِي آنٍ وَاحِدٍ اِحْتِفاءً بِهِ أَودُعاءً لَهُ بِالصِّحَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23546, 'أَنْخَابٌ', 'أنخاب', 'مصدر', '', 'ءنخاب', 'نخب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23547, 'نَخِيرٌ', 'نخير', 'مصدر', 'نخر', 'نخير', 'نخر', 'مص. نَخَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَخِيرٌ-نَخِيرٌ [ن خ ر] (مص. نَخَرَ). ""طَالَ نَخِيرُهُ"" : شَخِيرُهُ، مَدُّ الصَّوْتِ وَالنَّفَسِ فِي الْخَيَاشِيمِ. ""سَمِعَتِ الْمَرْأَةُ مِنَ النَّخِيرِ وَالشَّهِيقِ أَمْرًا عَجَباً"". (الجاحظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23548, 'نَخْلٌ', 'نخل', 'مصدر', 'نخل', 'نخل', 'نخل', 'مص. نَخَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَخْلٌ-نَخْلٌ [ن خ ل] (مص. نَخَلَ). ""نَخْلُ الطَّحِينِ"" : إِزَالَةُ نُخَالَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23549, 'نَدَامَةٌ', 'ندامة', 'مصدر', 'ندم', 'ندامة', 'ندمة', 'مص. نَدِمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَدَامَةٌ-نَدَامَةٌ [ن د م] (مص. نَدِمَ). ""شَعَرَ بِنَدَامَةٍ مَا بَعْدَهَا نَدَامَةٌ"" : الأَسَفُ وَالْحُزْنُ. ""إِنَّ الَّذِي لاَ يَسْمَعُ مِنْ إِخْوَانِهِ وَنُصَحَائِهِ يَصِيرُ أَمْرُهُ إِلَى النَّدَامَةِ"". (ابن المقفع) l ""أَوَّلُ الغَضَبِ جُنُونٌ وَآخِرُهُ نَدَامَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23550, 'نَدِيدٌ', 'نديد', 'مصدر', 'ندد', 'نديد', 'ندد', 'مص. نَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَنْدَادٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَدَّ). ""هُوَ نَدِيدُهُ"" : نِدُّهُ، نَظِيرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23551, 'أَنْدَادٌ', 'أنداد', 'مصدر', '', 'ءنداد', 'ندد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23552, 'نَدَبٌ', 'ندب', 'مصدر', 'ندب', 'ندب', 'ندب', 'مص. نَدَبَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْدَابٌ:نُدُوبٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَدَبَ). 1.""تَرَكَ عَلَى جِسْمِهِ نَدَباً"" : أَثَر الْجُرْحِ أَوِ الضَّرْبِ. 2.""رَمَى نَدَباً"" : قَوْساً سَرِيعَةَ السَّهْمِ. 3.""تَرَكَ أَمْرَهُ نَدَباً"" : رِهَاناً، أَيْ خَطَراً فَمَنْ غَلَبَ أَخَذَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23553, 'أَنْدَابٌ', 'أنداب', 'مصدر', '', 'ءنداب', 'ندب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23554, 'نُدُوبٌ', 'ندوب', 'مصدر', '', 'ندوب', 'ندب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23555, 'نَدْبٌ', 'ندب', 'مصدر', 'ندب', 'ندب', 'ندب', 'مص. نَدَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَدْبٌ-نَدْبٌ [ن د ب] (مص. نَدَبَ). 1.""أَفْرَغَ نَدْبَهُ"" : رِثَاءهُ وَمَا يُصَاحِبُهُ مِنْ أَنِينٍ وَتَوَجُّعٍ. 2.""رَجُلٌ نَدْبٌ"" : سَرِيعٌ إِلَى الفَضَائِلِ، خَفِيفٌ، حَذِرٌ، نَشِيطٌ، ظَرِيفٌ. 3.""فَرَسٌ نَدْبٌ"": مَاضٍ، نَشِيطٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23556, 'تَنْدِيدٌ', 'تنديد', 'مصدر', 'ندد', 'تنديد', 'تندد', 'مص. نَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْدِيدٌ-تَنْدِيدٌ [ن د د] (مص. نَدَّدَ). قَرَّرَ التَّنْدِيدَ بِسُلُوكِهِ الْمُشِينِ"" : اِنْتِقَادَهُ، إعْلاَنَ عُيُوبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23557, 'نُدُورٌ', 'ندور', 'مصدر', 'ندر', 'ندور', 'ندر', 'مص. نَدَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُدُورٌ-نُدُورٌ [ن د ر] (مص. نَدَرَ). ""نُدُورُ الأَمْطَارِ"" : قِلَّةُ وُجُودِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23558, 'تَنْدِيفٌ', 'تنديف', 'مصدر', 'ندف', 'تنديف', 'تندف', 'مص. نَدَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْدِيفٌ-تَنْدِيفٌ [ن د ف] (مص. نَدَّفَ). ""تَنْدِيفُ القُطْنِ"" : نَدْفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23559, 'نُزُوزٌ', 'نزوز', 'مصدر', '', 'نزوز', 'نزز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23560, 'نَدَمٌ', 'ندم', 'مصدر', 'ندم', 'ندم', 'ندم', 'مص. نَدِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَدَمٌ-نَدَمٌ [ن د م] (مص. نَدِمَ). ""كَانَ نَدَمُهُ شَدِيداً"" : أَسَفُهُ، حُزْنُهُ، تَحَسُّرُهُ. ""أَكْثَرَ مِنَ النَّدَمِ وَالاسْتِغْفَارِ وَالتَّوْبَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23561, 'نَدًى', 'ندى', 'مصدر', 'ندو', 'ندى', 'ند', 'مص نَدِيَ', '', '', 'مفرد', 'Dw', '', '', '"أَنْدَاءٌ:أَنْدِيَةٌ"', '', 'Rw', '', '', '', '', '', '', '"(مص نَدِيَ). 1.""نَدَى النَّبَاتِ"" : بُخَارُ الْمَاءِ يَتَكَاثَفُ فِي الْجَوِّ البَارِدِ أَثْنَاءَ اللَّيْلِ وَيَتَسَاقَطُ عَلَى الأَرْضِ قَطَرَاتٍ خَفِيفَةً. 2.""كَانَ نَدَاهُ كَثِيراً"" : كَرَمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23562, 'أَنْدَاءٌ', 'أنداء', 'مصدر', '', 'ءنداء', 'ند', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23563, 'أَنْدِيَةٌ', 'أندية', 'مصدر', '', 'ءندية', 'ندة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23564, 'نِذَارَةٌ', 'نذارة', 'مصدر', 'نذر', 'نذارة', 'نذرة', 'مص. نَذِرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نِذَارَةٌ-نِذَارَةٌ [ن ذ ر] (مص. نَذِرَ). ""رَأَى فِي الأَمْرِ نِذَارَةً"" : إِنْذَاراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23565, 'نَذْرٌ', 'نذر', 'مصدر', 'نذر', 'نذر', 'نذر', 'مص. نَذَرَ، نَذِرَ، أَنْذَرَ', '', '', 'مفرد', 'DnN', '', '', '"نُذُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَذَرَ، نَذِرَ، أَنْذَرَ). 1.""قَدَّمَ نَذْراً لِلْإِلَهِ"" : مَا يُقَدِّمُهُ الإِنْسَانُ لِلْإِلَهِ أَوْ يُوجِبُهُ عَلَى نَفْسِهِ مِنْ صَدَقَةٍ أَوْ عِبَادَةٍ. 2.""قَدَّمَ لِأَهْلِ الضَّحِيَّةِ نَذْراً"" : دِيَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23566, 'نُذُورٌ', 'نذور', 'مصدر', '', 'نذور', 'نذر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23567, 'نَذَالَةٌ', 'نذالة', 'مصدر', 'نذل', 'نذالة', 'نذلة', 'مص. نَذَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَذَالَةٌ-نَذَالَةٌ [ن ذ ل] (مص. نَذَلَ). ""أَظْهَرَ نَذَالَةً مَا بَعْدَهَا مِنْ نَذَالَةٍ"" : حَقَارَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23568, 'نَزٌّ', 'نز', 'مصدر', 'نزز', 'نز', 'نز', 'مص. نَزَّ', '', '', 'مفرد', 'DnN', '', '', '"نُزُوزٌ:أَنْزَازٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَزَّ). 1.""نَزُّ الشَّجَرَةِ"" : النَّدَى السَّائِلُ مِنْهَا. 2.""جُدْرَانُ البَيْتِ بِهَا نَزٌّ"" : مَا تَحَلَّبَ مِنْهَا مِن مَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23569, 'نَزْغٌ', 'نزغ', 'مصدر', 'نزغ', 'نزغ', 'نزغ', 'مص. نَزَغَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَزْغٌ-نَزْغٌ [ن ز غ] (مص. نَزَغَ). 1.""حَاوَلَ بِنَزْغِهِ جَذْبَ النَّاسِ إِلَيْهِ"" : بِكَلاَمٍ مُغْرٍ، جَذَّابٍ يُغْرِيهِمْ بِهِ. 2.""نَزْغُ الشَّيْطَانِ"" : وَسَاوِسُهُ وَمَا يَدْفَعُ بِهِ الإِنْسَانَ إِلَى الشَّرِّ وَالْمَعَاصِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23570, 'أَنْزَازٌ', 'أنزاز', 'مصدر', '', 'ءنزاز', 'نزز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23571, 'نَزِيزٌ', 'نزيز', 'مصدر', 'نزز', 'نزيز', 'نزز', 'مص. نَزَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَزِيزٌ-نَزِيزٌ [ن ز ز] (مص. نَزَّ). 1.""وَلَدٌ نَزِيزٌ"" : ظَرِيفٌ، خَفِيفُ الْحَرَكَةِ. 2.""رَجُلٌ نَزِيزٌ"" : شَهْوَانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23572, 'نَزَوَانٌ', 'نزوان', 'مصدر', 'نزو', 'نزوان', 'نزن', 'مص. نَزَا', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَزَوَانٌ-نَزَوَانٌ [ن ز و] (مص. نَزَا). ""أَظْهَرَ فِي كَلاَمِهِ نَزَوَانـاً"" : حِدَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23573, 'نُزُوحٌ', 'نزوح', 'مصدر', 'نزح', 'نزوح', 'نزح', 'مص. نَزَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُزُوحٌ-نُزُوحٌ [ن ز ح] (مص. نَزَحَ). ""نُزُوحُ السُّكَّانِ"" : خُرُوجُهُمْ وَبُعْدُهُمْ عَنْ مَقَرِّ سُكْنَاهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23574, 'تَنْزِيرٌ', 'تنزير', 'مصدر', 'نزر', 'تنزير', 'تنزر', 'مص. نَزَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْزِيرٌ-تَنْزِيرٌ [ن ز ر] (مص. نَزَّرَ). ""تَنْزِيرُ العَطَاءِ : تَقْلِيلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23575, 'نَزْرٌ', 'نزر', 'مصدر', 'نزر', 'نزر', 'نزر', 'مص. نَزَرَ، نَزُرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَزْرٌ-نَزْرٌ [ن ز ر] (مص. نَزَرَ، نَزُرَ). 1.""لَمْ يُعْطِهِ إِلاَّ النَّزْرَ مِنَ الطَّعَامِ"" : القَلِيلَ التَّافِهَ مِنْهُ. 2.""رَجُلٌ نَزْرٌ"" : قَلِيلُ الخَيْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23576, 'نِزَاعٌ', 'نزاع', 'مصدر', 'نزع', 'نزاع', 'نزع', 'مص. نَزَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نِزَاعٌ-نِزَاعٌ [ن ز ع] (مص. نَزَعَ). 1.""حَصَلَ بَيْنَهُمَا نِـزَاعٌ"" : خِصَامٌ، خُصُومَةٌ. 2.""أَمْرٌ لاَ نِزَاعَ فِيهِ"" : لاَ خِلاَفَ، لاَ جِدَالَ فِيهِ. 3.""نِزَاعٌ مُسَلَّحٌ"" : عِرَاكٌ، قِتَالٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23577, 'نَزْعٌ', 'نزع', 'مصدر', 'نزع', 'نزع', 'نزع', 'مص. نَزَعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَزْعٌ-نَزْعٌ [ن ز ع] (مص. نَزَعَ). 1.""نَزْعُ الْحَيَاةِ"" : حَالَةُ الْمَرِيضِ الْمُشْرِفِ عَلَى الْمَوْتِ. ""هُوَ فِي النَّزْعِ الأَخِيرِ"". 2.""نَزْعُ السِّلاَحِ"" : إِجْرَاءٌ دَوْلِيٌّ يُتَّفَقُ عَلَيْهِ لإِنْهَاءِ حَالَةِ التَّسَلُّحِ أَوِ التَّخْفِيفِ مِنْهَا. ""مُؤْتَمَرُ نَزْعِ السِّلاَحِ"". 3.""نَزْعُ الْخَافِضِ"" (نحو) : أَيْ حَذْفُ الجَارِّ كَمَا فِي قَوْلِكَ: ""تَوَجَّهْتُ مَكَّةَ"" : بَدَلاً مِنْ إِلَى مَكَّةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23578, 'نُزُوعٌ', 'نزوع', 'مصدر', 'نزع', 'نزوع', 'نزع', 'مص. نَزَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُزُوعٌ-نُزُوعٌ [ن ز ع] (مص. نَزَعَ). ""بِهِ نُزُوعٌ إِلَى أَهْلِهِ وَوَطَنِهِ"" : شَوْقٌ عَارِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23579, 'نَزَاهَةٌ', 'نزاهة', 'مصدر', 'نزه', 'نزاهة', 'نزهة', 'مص. نَزُهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَزَاهَةٌ-نَزَاهَةٌ [ن ز هـ]. (مص. نَزُهَ). ""عُرِفَ بِالنَّزَاهَةِ وَسُمُوِّ الأَخْلاَقِ"" : بِالاسْتِقَامَةِ وَعَدَمِ التَّحَيُّزِ عِنْدَمَا يَتَعَلَّقُ الأَمْرُ بِإِصْدَارِ حُكْمٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23580, 'نَزْفٌ', 'نزف', 'مصدر', 'نزف', 'نزف', 'نزف', 'مص. نَزَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَزْفٌ-نَزْفٌ [ن ز ف] (مص. نَزَفَ). ""كَثُرَ نَزْفُهُ"" : سَيَلاَنُ دَمِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23581, 'نُزُوقٌ', 'نزوق', 'مصدر', 'نزق', 'نزوق', 'نزق', 'مص. نَزَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُزُوقٌ-نُزُوقٌ [ن ز ق] (مص. نَزَقَ). ""نُزُوقُ الشَّبَابِ"" : طَيْشُهُ وَخِفَّتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23582, 'نَزَقٌ', 'نزق', 'مصدر', 'نزق', 'نزق', 'نزق', 'مص. نَزِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَزَقٌ-نَزَقٌ [ن ز ق] (مص. نَزِقَ). 1.""مَا هَذَا النَّزَقُ يَا وَلَدُ"" : مَا هَذَا الطَّيْشُ وَالخِفَّةُ. 2.""فِي كَلاَمِهِ نَزَقٌ"" : خِفَّةٌ وَطَيْشٌ. 3.""نَزَقُ الشَّبَابِ"" : العَجَلَةُ فِي جَهْلٍ وَحُمْقٍ وَطَيْشٍ. ""هَدِّئْ دَمَكَ يَا وَلَدُ وَخَلِّ عَنْكَ الطَّيْشَ وَالنَّزَقَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23583, 'تَنْزِيلٌ', 'تنزيل', 'مصدر', 'نزل', 'تنزيل', 'تنزل', 'مص. نَزَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْزِيلٌ-تَنْزِيلٌ [ن ز ل] (مص. نَزَّلَ). 1. ""تَنْزِيلُ السَّتَائِرِ"" : إسْدَالُهَا، إنْزَالُهَا مِنْ أعْلَى إلَى أسْفَلَ. 2. الجاثية آية 2 تَنْزِيلُ الكِتَابِ مِنَ اللَّهِ العَزِيزِ الحَكِيمِ (قرآن). : الوَحْيُ بِهِ. 3. ""آيَاتُ التَّنْزِيلِ"": آيَاتُ القُرْآنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23584, 'نِزَالَةٌ', 'نزالة', 'مصدر', 'نزل', 'نزالة', 'نزلة', 'مص. نَزَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُزَالَةٌ-نُزَالَةٌ [ن ز ل]. ""هُوَ مِنْ نُزَالَةِ السُّوءِ"" : أَيْ لَئِيمُ الأَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23585, 'نُزُولٌ', 'نزول', 'مصدر', 'نزل', 'نزول', 'نزل', 'مص. نَزَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُزُولٌ-نُزُولٌ [ن ز ل] (مص. نَزَلَ). 1.""نُزُولُ الطَّائِرَةِ"" : الْهُبُوطُ مِنْهَا. 2.""نُزُولٌ فِي مَكَانٍ"" : الاِسْتِقْرَارُ، الْحُلُولُ بِهِ. 3.""نُزُولاً عِنْدَ رَغْبَتِهِ"" : مُوَافَقَةً، مُلاَءمَةً. 4.""عَرَفَتِ الأَسْعَارُ صُعُوداً وَنُزُولاً"" : هُبُوطاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23586, 'نَزَلٌ', 'نزل', 'مصدر', 'نزل', 'نزل', 'نزل', 'مص. نَزِلَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْزَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَزِلَ). 1.""سَقَطَ النَّزَلُ"" : الْمَطَرُ. 2.""نَزَلُهُ كَثِيرٌ"" : عَطَاؤُهُ، فَضْلُهُ. 3.""طَعَامٌ ذُو نَزَلٍ"" : فِيهِ بَرَكَةٌ وَزِيَادَةٌ. 4.""أَنْزَالُ النَّاسِ"" : أَرْزَاقُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23587, 'أَنْزَالٌ', 'أنزال', 'مصدر', '', 'ءنزال', 'نزل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23588, 'تَنْزِيهٌ', 'تنزيه', 'مصدر', 'نزه', 'تنزيه', 'تنزه', 'مص. نَزَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْزِيهٌ-تَنْزِيهٌ [ن ز هـ] (مص. نَزَّهَ). ""تَنْزِيهُهُ عَنْ كُلِّ الشَّوَائِبِ وَعَمَّا يُدَنِّسُهُ"" : إبْعَادُهُ، تَقْدِيسُهُ، تَطْهِيرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23589, 'مَنَاسِكُ', 'مناسك', 'مصدر', '', 'مناسك', 'منسك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23590, 'نِسْبَةٌ', 'نسبة', 'مصدر', 'نسب', 'نسبة', 'نسبة', 'مص. نَسَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نِسَبٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَسَبَ). 1.""سَائِلٌ فِيهِ نِسْبَةٌ مِنَ الكُحُولِ"" : فِيهِ مِقْدَارٌ. ""أَضَافَ إِلَى الْمَادَّةِ الأَصْلِيَّةِ نِسْبَةً مِنَ السُّكَّرِ"". 2.""تَجَاوَزَتْ نِسْبَةُ النَّاجِحِينَ ثَمَانِينَ فِي الْمِائَةِ"" : عَلاَقَةٌ وَارْتِبَاطٌ بَيْنَ شَيْئَيْنِ: النَّاجِحُونَ وَالرَّاسِبُونَ. 3.""النِّسْبَةُ الْمِئَوِيَّةُ"" : مِقْدَارُ الشَّيْءِ مَنْسُوباً إِلَى مِائَةٍ. ""اِرْتَفَعَتْ نِسْبَةُ الْمَوَالِيدِ فِي دُوَلِ العَالَمِ الثَّالِثِ كَمَا ارْتَفَعَتْ نِسْبَةُ الوَفَيَاتِ"". 4.""نِسْبَةُ 2 إِلَى 4 كَنِسْبَةِ 5 إِلَى 10"" : أَيْ وُجُودُ تَمَاثُلٍ بَيْنَ عَلاَقَاتِ الكَمِّيَّاتِ أَوْ عَلاَقَاتِ الأَشْيَاءِ. 5.""بِالنِّسْبَةِ إِلَى مَوْقِفِكَ"" : بِالْمُقَارَنَةِ مَعَ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23591, 'نِسَبٌ', 'نسب', 'مصدر', '', 'نسب', 'نسب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23592, 'نَسَبٌ', 'نسب', 'مصدر', 'نسب', 'نسب', 'نسب', 'مص. نَسَبَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْسَابٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَسَبَ). 1.""هُوَ مِنْ أَهْلِ النَّسَبِ وَالْحَسَبِ"" : أَيْ مِنْ أُرُومَةٍ لاَ غُبَارَ عَلَيْهَا. ""نَسَبٌ أَصِيلٌ"". 2.""شَجَرَةُ النَّسَبِ"" : شَجَرَةُ تَتَابُعِ النَّسْلِ فِي أُسْرَةٍ. 3.""عُلَمَاءُ الأَنْسَابِ"" : الْمُهْتَمُّونَ بِقَرَابَةِ النَّسَبِ وَتَتَابُعِ الأَنْسَابِ فِي الأُسْرَةِ أَوِ القَبِيلَةِ الوَاحِدَةِ. 4.""النَّسَبُ فِي الصَّرْفِ"" : إِلْحَاقُ يَاءٍ مُشَدَّدَةٍ فِي آخِرِ الاسْمِ الْمُرَادِ النِّسْبَةُ إِلَيْهِ. ""مَغْرِبٌ"" : ""مَغْرِبِيٌّ"". ""عَرَبٌ"" : ""عَرَبِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23593, 'أَنْسَابٌ', 'أنساب', 'مصدر', '', 'ءنساب', 'نسب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23594, 'نَسِيبٌ', 'نسيب', 'مصدر', 'نسب', 'نسيب', 'نسب', 'مص. نَسَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَنْسِبَاءُ"', '', 'R', '', '', '', '', '', '', '"(مص. نَسَبَ). 1.""هُوَ نَسِيبِي"" : أَيْ قَرِيبِي، صِهْرِي. 2.""شِعْرُ النَّسِيبِ"" : الشِّعْرُ الغَزَلِيُّ، شِعْرُ الْحُبِّ، وَالتَّشَبُّبِ بِالنِّسَاءِ. 3.""حَسِيبٌ نَسِيـبٌ"" : ذُو حَسَبٍ وَنَسَبٍ. 4.""رَجُلٌ نَسِيبٌ"" : شَرِيفُ النَّسَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23595, 'أَنْسِبَاءُ', 'أنسباء', 'مصدر', '', 'ءنسباء', 'نسب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23596, 'نَسْجٌ', 'نسج', 'مصدر', 'نسج', 'نسج', 'نسج', 'مص. نَسَجَ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"نَسْجٌ-نَسْجٌ [ن س ج] (مص. نَسَجَ). 1.""نَسْجُ الثَّوْبِ"" : حِيَاكَتُهُ. 2.""حِكَايَةٌ مِنْ نَسْجِ الْخَيَالِ"" : مِنْ تَرْكِيبِ الْخَيَالِ وَتَنْسِيقِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23597, 'تَنْسِيقٌ', 'تنسيق', 'مصدر', 'نسق', 'تنسيق', 'تنسق', 'مص. نَسَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْسِيقٌ-تَنْسِيقٌ [ن س ق] (مص. نَسَّقَ). 1.""تَنْسِيقُ الكَلاَمِ"": إجْرَاؤُهُ عَلَى نَمَطٍ وَاحِدٍ وَسِيَاقٍ واحِدٍ. 2.""لَجْنَةُ التَّنْسِيقِ"" : لَجْنَةُ تَرْتِيبِ أعْمَالِ اللِّجَانِ وَالرَّبْطِ فِيمَا بَيْنَهَا. 3."" تَنْسِيقُ العَمَلِ"" : تَوْحِيدُ نِظَامِهِ وَشَكْلِهِ. ""مَعْهَدُ تَنْسِيقِ التَّعْرِيبِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23598, 'مَنْسَكٌ', 'منسك', 'مصدر', 'نسك', 'منسك', 'منسك', 'مص. نَسَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَنَاسِكُ"', '', 'R', '', '', '', '', '', '', '"(مص. نَسَكَ). 1.""عَادُوا إِلَى مَنْسَكِهِمُ"" : إِلَى مَكَانِهِمُ الْمَأْلُوفِ. 2.""لَهُ مَنْسَكُهُ الْخَاصُّ بِهِ"" : طَرِيقَةُ نُسْكِهِ وَعِبَادَتِهِ.الحج آية 67 لِكُلِّ أُمَّةٍ جَعَلْنَا مَنْسَكاً هُمْ نَاسِكُوهُ (قرآن) . 3.""مَنَاسِكُ الْحَجِّ"" : طُقُوسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23599, 'نُسْكٌ', 'نسك', 'مصدر', 'نسك', 'نسك', 'نسك', 'مص. نَسَكَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُسْكٌ-نُسْكٌ [ن س ك] (مص. نَسَكَ). 1.""عَاشَ فِي نُسْكٍ"": فِي زُهْدٍ وَتَعَبُّدٍ. 2."" قَدَّمَ نُسْكاً"" : نُسُكاً، ذَبِيحَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23600, 'نَسْلٌ', 'نسل', 'مصدر', 'نسل', 'نسل', 'نسل', 'مص. نَسَلَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْسَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَسَلَ). 1.""هُوَ مِنْ نَسْلِهِ"" : مِنْ ذُرِّيَّتِهِ. ""مِنْ نَسْلِ الأَشْرَافِ وَالْمَكَارِمِ"". 2.""تَكَاثَرَ الْخَلْقُ"" : الْخَلْقَ. البقرة آية 205وَإِذَا تَوَلَّى سَعَى فِي الأَرْضِ لِيُفْسِدَ فِيهَا وَيَهْلِكَ الْحَرْثَ وَالنَّسْلَ (قرآن). 3.""وَضَعَتْ وِزَارَةُ الصِّحَّةِ مُخَطَّطاً لِتَحْدِيدِ النَّسْلِ"" : مُخَطَّطاً لِلْحَدِّ مِنْ كَثْرَةِ التَّنَاسُلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23601, 'أَنْسَالٌ', 'أنسال', 'مصدر', '', 'ءنسال', 'نسل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23602, 'نَسِيمٌ', 'نسيم', 'مصدر', 'نسم', 'نسيم', 'نسم', 'مص. نَسَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَسِيمٌ-نَسِيمٌ [ن س م] (مص. نَسَمَ). ""نَسِيمُ الصَّبَاحِ"" : رِيحٌ لَيِّنَةٌ لاَ تُحَرِّكُ شَجَراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23603, 'نِسْيَانٌ', 'نسيان', 'مصدر', 'نسي', 'نسيان', 'نسن', 'مص. نَسِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نِسْيَانٌ-نِسْيَانٌ [ن س ي] (مص. نَسِيَ). 1.""نِسْيَانُ الْمَوْعِدِ"": فُقْدَانُ ذِكْرِهِ وَخُلُوُّ البَالِ مِنْهُ. ""طَوَاهُ النِّسْيَانُ"" ""فِي الزَّمَانِ دَوَاءٌ عَظِيمٌ اسْمُهُ النِّسْيَانُ"". (جمال الغيطاني). 2.""أُصِيبَ بِمَرَضِ النِّسْيَانِ"" : فُقْدَانُ الذَّاكِرَةِ جُزْئِيّاً أَوْ كُلِّيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23604, 'نَسْيٌ', 'نسي', 'مصدر', 'نسي', 'نسي', 'نس', 'مص. نَسِيَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْسَاءٌ"', '', '', '', '', '', '', '', '', '"(مص. نَسِيَ). 1.""أَصْبَحَ نَسْياً مَنْسِيّاً"" : أَيْ مَا نُسِيَ.مريم آية 23 وَكُنْتُ نَسْياً مَنْسِيّاً (قرآن). 2.""نَسْيُ الْمَتَاعِ"" : مَا سَقَطَ وَتُرِكَ مِنْهُ لِرَذَالَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23605, 'أَنْسَاءٌ', 'أنساء', 'مصدر', '', 'ءنساء', 'نس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23606, 'نَشٌّ', 'نش', 'مصدر', 'نشش', 'نش', 'نش', 'مص. نَشَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَشٌّ-نَشٌّ [ن ش ش] (مص. نَشَّ). ""نَشُّ الذُّبَابِ"" : طَرْدُهُ، إِبْعَادُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23607, 'تَنْشِئَةٌ', 'تنشئة', 'مصدر', 'نشأ', 'تنشءة', 'تنشة', 'مص. نَشَّأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَنْشِئَةٌ-تَنْشِئَةٌ [ن ش أ] (مص. نَشَّأَ). ""تَنْشِئَةُ الأولادِ عَلَى الخُلُقِ الكَرِيمِ"" : تَرْبِيَتُهُمْ تَرْبِيَةً خُلُقِيَّةً. ""التَّنْشِئَةُ الاجْتِمَاعِيَّةُ"": التَّرْبِيَةُ الاجْتِمَاعِيَّةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23608, 'نَشْءٌ', 'نشء', 'مصدر', 'نشأ', 'نشء', 'نش', 'مص. نَشَأَ', '', '', 'مفرد', 'Dz', '', '', '"نَشَأٌ"', '', 'Rz', '', '', '', '', '', '', '"(مص. نَشَأَ). 1.""النَّشْءُ الْجَدِيدُ"" : الجِيلُ الجَدِيدُ. (وَفِي الأَصْلِ كَانَتْ تُطْلَقُ عَلَى صِغَارِ الْحَيَوَانِ وَالإِنْسَانِ). 2.""هُوَ مِنْ نَشْءِ سُوءٍ"" : مِنْ نَسْلِ سُوءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23609, 'نَشَأٌ', 'نشأ', 'مصدر', '', 'نشء', 'نش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23610, 'نَشَأٌ', 'نشأ', 'مصدر', '', 'نشء', 'نش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23611, 'نَشْأَةٌ', 'نشأة', 'مصدر', 'نشأ', 'نشءة', 'نشة', 'مص. نَشَأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"نَشْأَةٌ-نَشْأَةٌ [ن ش أ] (مص. نَشَأَ). 1.""أَنْشَأَهُ نَشْأَةً وَطَنِيَّةً"" : أَيْ تَرْبِيَةً وَطَنِيَّةً. الواقعة آية 62 وَلَقَدْ عَلِمْتُمُ النَّشْأَةَ الأُولَى (قرآن). 2.""نَبَاتٌ فِي نَشْأَةٍ"" : مَا ارْتَفَعَ مِنَ النَّبَاتِ وَلَمْ يَغْلُظْ بَعْدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23612, 'نُشُوءٌ', 'نشوء', 'مصدر', 'نشأ', 'نشوء', 'نش', 'مص. نَشَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُشُوءٌ-نُشُوءٌ [ن ش أ] (مص. نَشَأَ). 1.""كَانَ نُشُوؤُهُ فِي بِيئَةٍ صَالِحَةٍ"" : تَرَعْرُعُهُ، تَرْبِيَتُهُ. 2.""مَذْهَبُ النُّشُوءِ وَالارْتِقَاءِ"" : مَذْهَبُ النُّمُوِّ وَالتَّطَوُّرِ (عِنْدَ دَارُوينَ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23613, 'تَنْشِيبٌ', 'تنشيب', 'مصدر', 'نشب', 'تنشيب', 'تنشب', 'مص. نَشَّبَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَنْشِيبٌ-تَنْشِيبٌ [ن ش ب] (مص. نَشَّبَ). ""تَنْشِيبُ الأظَافِرِ فِي الجَسَدِ"" : غَرْزُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23614, 'نَشَبٌ', 'نشب', 'مصدر', 'نشب', 'نشب', 'نشب', 'مص. نَشِبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَشَبٌ-نَشَبٌ [ن ش ب] (مص. نَشِبَ). 1.""نَشَبُ التَّاجِرِ"" : عَقَارُهُ أَوْ مَالُهُ الأَصِيلِ مِنْ نُقُودٍ وَمَاشِيَةٍ. 2.""شَجَرُ النَّشَبِ"" : شَجَرٌ تُتَّخَذُ مِنْهُ القِسِيُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23615, 'نَشِيجٌ', 'نشيج', 'مصدر', 'نشج', 'نشيج', 'نشج', 'مص. نَشَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نُشُجٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَشَجَ). ""سَمِعَ نَشِيجَهَا فَالْتَفَتَ إِلَيْهَا مُسْتَفْسِراً"" : تَرَدُّدُ الصَّوْتِ فِي صَدْرِهَا..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23616, 'نُشُجٌ', 'نشج', 'مصدر', '', 'نشج', 'نشج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23617, 'تَنْشِيرٌ', 'تنشير', 'مصدر', 'نشر', 'تنشير', 'تنشر', 'مص. نَشَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْشِيرٌ-تَنْشِيرٌ [ن ش ر] (مص. نَشَّرَ). ""تَنْشِيرُ الأثْوَابِ"" : تَمْدِيدُهَا، نَشْرُهَا، بَسْطُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23618, 'نَشْرٌ', 'نشر', 'مصدر', 'نشر', 'نشر', 'نشر', 'مص. نَشَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَشْرٌ-نَشْرٌ [ن ش ر] (مص. نَشَرَ). 1.""يَوْمُ النَّشْرِ"" : يَوْمُ القِيَامَةِ. 2.""جَاءَ القَوْمُ نَشْراً"" : جَاءوا مُتَفَرِّقِينَ لاَ يَجْمَعُهُمْ رَئِيسٌ. 3.""هِيَ طَيِّبَةُ النَّشْرِ"" : طَيِّبَةُ الرَّائِحَةِ. 4.""نَشْرُ الخَشَبِ"": نَحْتُهُ. 5.""نَشْرُ خَبَرٍ"" : إِذَاعَتُهُ. 6.""نَشْرُ مَقَالٍ"" : طَبْعُهُ في مَطْبُوعٍ. ""نَشْرُ كِتَابٍ"". 7.""دَارُ النَّشْرِ"" : مُؤَسَّسَةٌ تَهْتَمُّ بِطَبْعِ الكُتُبِ وَتَوْزِيعِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23619, 'نَشْلٌ', 'نشل', 'مصدر', 'نشل', 'نشل', 'نشل', 'مص. نَشَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَشْلٌ-نَشْلٌ [ن ش ل] (مص. نَشَلَ). ""نَشْلُ مِحْفَظَةِ نُقُـودٍ"": نَزْعُهَا، خَطْفُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23620, 'نُشُورٌ', 'نشور', 'مصدر', 'نشر', 'نشور', 'نشر', 'مص. نَشَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُشُورٌ-نُشُورٌ [ن ش ر] (مص. نَشَرَ). ""يَوْمُ النُّشُورِ"" : يَوْمُ القِيَامَةِ. ""وَصَفَ لَهُ جَمِيعَ مَا وَرَدَ فِي الشَّرِيعَةِ مِنْ وَصْفِ العَالَمِ الإِلَهِيِّ، وَالْجَنَّةِ وَالنَّارِ وَالبَعْثِ وَالنُّشُورِ وَالْحَشْرِ وَالْحِسَابِ وَالْمِيزَانِ وَالصِّرَاطِ"". (ابن طفيل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23621, 'نَشْزٌ', 'نشز', 'مصدر', 'نشز', 'نشز', 'نشز', 'مص. نَشَزَ', '', '', 'مفرد', 'DnN', '', '', '"نُشُوزٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَشَزَ). ""أَرْضٌ بِهَا نَشْزٌ"" : مَا ارْتَفَعَ مِنْهَا، بِهَا نُتُوءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23622, 'نُشُوزٌ', 'نشوز', 'مصدر', '', 'نشوز', 'نشز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23623, 'تَنْشِيطٌ', 'تنشيط', 'مصدر', 'نشط', 'تنشيط', 'تنشط', 'مص. نَشَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْشِيطٌ-تَنْشِيطٌ [ن ش ط] (مص. نَشَّطَ). 1. ""تَنْشِيطُ الحَبْلِ"": عَقْدُهُ بِأُنْشوطَةٍ. 2. تَنْشِيطُ الفِرَقِ الفَنِّيَّةِ"" : جَعْلُهَا تَنْشَطُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23624, 'نَشَاطٌ', 'نشاط', 'مصدر', 'نشط', 'نشاط', 'نشط', 'مص. نَشَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَنْشِطَةٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَشَطَ). ""تَمَيَّزَ نَشَاطُهُ بِالْحَيَوِيَّةِ"" : حَرَكَتُهُ الدَّائِمَةُ وَمُمَارَسَتُهُ لِلْعَمَلِ. ""ثَرْوَتُهُ الوَحِيدَةُ وَحَسَاسِيَتُهُ الْمُفْرِطَةُ كَانَتْ تُعَرْقِلُ نَشَاطَهُ"". (عبد الله العروي) ""قَالَ الْحُكَمَاءُ : النَّشَاطُ يُوَرِّثُ الغِنَى، وَالكَسَلُ يُوَرِّثُ الفَقْرَ، وَالشَّرَاهَةُ تُوَرِّثُ الْمَرَضَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23625, 'أَنْشِطَةٌ', 'أنشطة', 'مصدر', '', 'ءنشطة', 'نشطة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23626, 'تَنْشِيفٌ', 'تنشيف', 'مصدر', 'نشف', 'تنشيف', 'تنشف', 'مص. نَشَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْشِيفٌ-تَنْشِيفٌ [ن ش ف] (مص. نَشَّفَ). ""تَنْشِيفُ الْمَاءِ"" : جَعْلُهُ يَنْشَفُ بِنَشَّافٍ وَنَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23627, 'نَشَفٌ', 'نشف', 'مصدر', 'نشف', 'نشف', 'نشف', 'مص. نَشِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَشَفٌ-نَشَفٌ [ن ش ف] (مص. نَشِفَ). ""نَشَفُ الأَرْضِ"" : نُضُوبُ مَائِهَا. ""تَرَكَ نَشَفُ البِئْر هَلَعاً بَيْنَ سُكَّانِ القَرْيَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23628, 'نَشْقٌ', 'نشق', 'مصدر', 'نشق', 'نشق', 'نشق', 'مص. نَشِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَشْقٌ-نَشْقٌ [ن ش ق] (مص. نَشِقَ). ""نَشْقُ الْهَوَاءِ"" : اِسْتِنْشَاقُهُ، شَمُّهُ. ""نَشْقُ الرَّائِحَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23629, 'تَنْصِيرٌ', 'تنصير', 'مصدر', 'نصر', 'تنصير', 'تنصر', 'مص. نَصَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْصِيرٌ-تَنْصِيرٌ [ن ص ر] (مص. نَصَّرَ). ""تَنْصِيرُ الرَّجُلِ"" : جَعْلُهُ نَصْرَانِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23630, 'نَشْوَةٌ', 'نشوة', 'مصدر', 'نشو', 'نشوة', 'نشة', 'مص. نَشِيَ', '', '', 'مفرد', 'DnN', '', '', '"نَشَوَاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَشِيَ). 1.""نَشْوَةُ النَّصْرِ"" : الابْتِهَاجُ، التَّهَلُّلُ. ""نَشْوَةُ الطَّرَبِ"" ‏ ""نَشْوَةُ الفَرَحِ"". 2.""بَدَأَتْ نَشْوَةُ الْخَمْرِ تَلْعَبُ بِعَقْلِهِ"" : أَوَّلُ عَلاَمَةِ السُّكْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23631, 'نَشَوَاتٌ', 'نشوات', 'مصدر', '', 'نشوات', 'نشت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23632, 'نَصٌّ', 'نص', 'مصدر', 'نصص', 'نص', 'نص', 'مص. نَصٌّ', '', '', 'مفرد', 'DnN', '', '', '"نُصُوصٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَصٌّ). : الكَلاَمُ الْمَنْصُوصُ. 1.""نَصٌّ نَثْرِيٌّ"" : قِطْعَةٌ نَثْرِيَّةٌ. ""نَصُّ شِعْرِيٌّ"" ""النَّصُّ الأَدَبِيُّ"" ""النُّصُوصُ الأَدَبِيَّةُ"". 2.""نَصُّ حُكْمٍ"" : القَرَارُ الصَّادِرُ مِنْ... وَحَيْثِيَّاتُهُ. 3.""هَذَا مَا جَاءَ فِي نَصِّ الرِّسَالَةِ"" : أَيْ مُحْتَوَاهَا وَمَضْمُونُهَا. 4.""هَذِهِ هِيَ أَفْكَارُهُ نَصّاً وَرُوحاً"" : كَمَا جَاءتْ وَوَرَدَتْ مِنْ حَيْثُ اللَّفْظُ وَمِنْ حَيْثُ الْمَعْنَى. ""نَقَلَ أَفْكَارَهُ بِنَصِّهَا"" ""اِطَّلَعَ عَلَى الوَثِيقَةِ بِنَصِّهَا الْحَرْفِيِّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23633, 'نُصُوصٌ', 'نصوص', 'مصدر', '', 'نصوص', 'نصص', '', '', '', 'جمع تكسير', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23634, 'تَنْصِيبٌ', 'تنصيب', 'مصدر', 'نصب', 'تنصيب', 'تنصب', 'مص. نَصَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْصِيبٌ-تَنْصِيبٌ [ن ص ب] (مص. نَصَّبَ). 1. ""تَنْصِيبُ خَيْمَةٍ"" : رَفْعُهَا. 2. ""حَضَرَ حَفْلَ تَنْصِيبِ الملِكِ الأمَرَاءُ وَالوُزَرَاءُ وَالأعْيَانُ"" : حَفْلَ التَّوْلِيَةِ وَاعْتِلاَءِ العَرْشِ. 3. ""تَنْصِيبُ القَائِدِ أَوِ الوَزِيرِ"" : تَوْلِيَتُهُ، تَعْيِينُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23635, 'نَصْبٌ', 'نصب', 'مصدر', 'نصب', 'نصب', 'نصب', 'مص. نَصَبَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْصَابٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَصَبَ). 1.""غَرَسَ نَصْباً"" : مَا يُغْرَسُ مِنْ صِغَارِ الأَشْجَارِ. 2.""نَصْبُ قَبْرٍ"" : الشَّاهِدُ، أَيْ حَجَرٌ مَرْفُوعٌ فَوْقَ قَبْرٍ عَلَيْهِ كِتَابَةٌ أَوْ نُقُوشٌ. 3.""اِرْتَفَعَ النَّصْبُ"" : العَلَمُ الْمَنْصُوبُ. 4.""اتُّهِمَ بِالنَّصْبِ"" : بِالاِحْتِيَالِ وَالْخِدَاعِ. 5.""أَنْصَابُ الْجَاهِلِيِّينَ"" : مَا كَانَ يُنْصَبُ لِيُعْبَدَ مِنْ دُونِ اللهِ.المائدة آية 90إِنَّمَا الخَمْرُ وَالْمَيْسِرُ وَالأَنْصَابُ وَالأَزْلاَمُ رِجْسٌ (قرآن). 6. النَّصْبُ فِي النَّحْوِ: ""نَصْبُ الكَلِمَةِ"" : إِعْرَابُهَا بِالفَتْحَةِ أَوْ مَا يَنُوبُ عَنْهَا. 7.""هَذَا نَصْبُ عَيْنِي"" : أَمَامَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23636, 'أَنْصَابٌ', 'أنصاب', 'مصدر', '', 'ءنصاب', 'نصب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23637, 'نَصَبٌ', 'نصب', 'مصدر', 'نصب', 'نصب', 'نصب', 'مص. نَصِبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَصَبٌ-نَصَبٌ [ن ص ب] (مص. نَصِبَ). ""ظَلَّ يُعَانِي مِنَ النَّصَبِ"" : مِنَ التَّعَبِ، العَنَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23638, 'نَصْحٌ', 'نصح', 'مصدر', 'نصح', 'نصح', 'نصح', 'مص. نَصَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَصْحٌ-نَصْحٌ، نُصْحٌ [ن ص ح] (مص. نَصَحَ). ""اِسْتَمَعَ إِلَى نُصْحِهِ"" : إِلَى إِرْشَادِهِ وَمَا فِيهِ صَلاَحُهُ . ""يَدُلُّ عَلَى الْخَيْرِ وَيُشِيرُ بِالنُّصْحِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23639, 'نَضِيضَةٌ', 'نضيضة', 'مصدر', 'نضض', 'نضيضة', 'نضضة', 'مص. نَضَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نِضَاضٌ:نَضَائِضُ"', '', 'R', '', '', '', '', '', '', '"(مص. نَضَّ). 1.""نَضِيضُ الطَّعَامِ"" : قَلِيلُهُ. 2.""وَلَدٌ نَضِيضُ اللَّحْمِ"" : ضَعِيفُ البِنْيَةِ. 3.""عَرَفَ هَذَا النَّهَارُ نَضِيضَةً"" : مَطَراً قَلِيلاً. 4.""جِمَالٌ ذَاتُ نَضِيضَةٍ"" : أَيْ عَطَشُهَا لاَ يُرْوَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23640, 'نُصْرَةٌ', 'نصرة', 'مصدر', 'نصر', 'نصرة', 'نصرة', 'مص. نَصَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُصْرَةٌ-نُصْرَةٌ [ن ص ر] (مص. نَصَرَ). ""جَاءتْ نُصْرَتُهُ عَلَى يَدِهِ"" : إِعَانَتُهُ عَلَى الفَوْزِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23641, 'نَصْرٌ', 'نصر', 'مصدر', 'نصر', 'نصر', 'نصر', 'مص. نَصَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَصْرٌ-نَصْرٌ [ن ص ر] (مص. نَصَرَ). 1.""نَصْرٌ مُبِينٌ"" : فَوْزٌ، فَتْحٌ. ""عَقَدَ لَهُ النَّصْرَ"" ‏ ""وَإِنَّهَا لَثَوْرَةٌ حَتَّى النَّصْرِ"". 2.""رَجُلٌ نَصْرٌ"" : نَاصِرٌ. ""قَوْمٌ نَصْرٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23642, 'تَنْصِيفٌ', 'تنصيف', 'مصدر', 'نصف', 'تنصيف', 'تنصف', 'مص. نَصَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْصِيفٌ-تَنْصِيفٌ [ن ص ف] (مص. نَصَّفَ). 1.""تَنْصِيفُ الغَنِيمَةِ"" : تَقْسِيمُهَا نِصْفَيْنِ. 2.""تَنْصِيفُ الطَّعَامِ"" : أخْذُ نِصْفِهِ. 3.""تَنْصِيفُ النَّخْلِ"" : اِحْمِرَارُ بَعْضِ بُسْرِهِ واخْضِرَارُ بَعْضِ الآخَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23643, 'نَصْلٌ', 'نصل', 'مصدر', 'نصل', 'نصل', 'نصل', 'مص. نَصَلَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْصُلٌ:نِصَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَصَلَ). ""نَصْلُ السِّكِّينِ"" : حَدِيدَةُ مِقْبَضِهِ. ""نَصْلُ رُمْحٍ"" ""نَصْلُ سَهْمٍ"" ""كُسِّرَتِ النِّصَالُ عَلَى النِّصَالِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23644, 'أَنْصُلٌ', 'أنصل', 'مصدر', '', 'ءنصل', 'نصل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23645, 'نِصَالٌ', 'نصال', 'مصدر', '', 'نصال', 'نصل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23646, 'نَصِيصٌ', 'نصيص', 'مصدر', 'نصص', 'نصيص', 'نصص', 'مص. نَصَّ، يَنِصُّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَصِيصٌ-نَصِيصٌ [ن ص ص] (مص. نَصَّ، يَنِصُّ). 1.""نَصِيصُ النَّاسِ"" : عَدَدُهُمْ. 2.""أَمْرٌ نَصِيصٌ"" : جِدٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23647, 'نَضٌّ', 'نض', 'مصدر', 'نضض', 'نض', 'نض', 'مص. نَضَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَضٌّ-نَضٌّ [ن ض ض] (مص. نَضَّ). 1.""أَعْطَاهُ نَضّاً"" : دِرْهَماً أَوْ دِينَاراً. 2.""أَخَذَ مِنْهُ نَضّاً"" : أَيْ نَقْداً. ""أَدَّاهُ نَضّاً"". 3.""أَتَى بِمَا هُوَ نَضٌّ"" : بِمَا هُوَ مَكْرُوهٌ. 4.""هُوَ نَضُّ اللَّحْمِ"" : قَلِيلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23648, 'نَضِيضٌ', 'نضيض', 'مصدر', 'نضض', 'نضيض', 'نضض', 'مص. نَضَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نِضَاضٌ:نَضَائِضُ"', '', 'R', '', '', '', '', '', '', '"(مص. نَضَّ). 1.""نَضِيضُ الطَّعَامِ"" : قَلِيلُهُ. 2.""وَلَدٌ نَضِيضُ اللَّحْمِ"" : ضَعِيفُ البِنْيَةِ. 3.""عَرَفَ هَذَا النَّهَارُ نَضِيضَةً"" : مَطَراً قَلِيلاً. 4.""جِمَالٌ ذَاتُ نَضِيضَةٍ"" : أَيْ عَطَشُهَا لاَ يُرْوَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23649, 'نَضَارَةٌ', 'نضارة', 'مصدر', 'نضر', 'نضارة', 'نضرة', 'مص. نَضَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَضَارَةٌ-نَضَارَةٌ [ن ض ر] (مص. نَضَرَ). 1.""مَا زَالَ فِي نَضَارَةِ شَبَابِهِ"" : فِي نُعُومَتِهِ. 2.""نَضَارَةُ وَجْهٍ"" : صَفَاؤُهُ، حُسْنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23650, 'نِضَاضٌ', 'نضاض', 'مصدر', '', 'نضاض', 'نضض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23651, 'نَضَائِضُ', 'نضائض', 'مصدر', '', 'نضاءض', 'نضض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23652, 'نُضُوبٌ', 'نضوب', 'مصدر', 'نضب', 'نضوب', 'نضب', 'مص. نَضَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُضُوبٌ-نُضُوبٌ [ن ض ب]. (مص. نَضَبَ). ""نُضُوبُ الْمَاءِ"": غَوْرُهُ فِي الأَرْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23653, 'نُضْجٌ', 'نضج', 'مصدر', 'نضج', 'نضج', 'نضج', 'مص. نَضِجَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُضْجٌ-نُضْجٌ [ن ض ج] (مص. نَضِجَ). 1.""نُضْجُ الفَاكِهَةِ"" : اِكْتِمَالُ ثَمَرَتِهَا وَبُلُوغُهَا مَبْلَغاً مُعَيَّناً مِنْ حَيْثُ اللَّوْنُ أَوِ الطَّعْمُ أَوِ الطَّرَاوَةُ. 2.""نُضْجٌ فِكْرِيٌّ"" : اِكْتِمَالُ الْمَدَارِكِ وَوُضُوحُهَا. 3.""عَبَّرَتْ مَوَاقِفُهُ عَنْ نُضْجٍ سِيَاسِيٍّ"" : عَنْ وَعْيٍ... عَنْ رُؤْيَةٍ مُكْتَمِلَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23654, 'نَضْحٌ', 'نضح', 'مصدر', 'نضح', 'نضح', 'نضح', 'مص. نَضَحَ', '', '', 'مفرد', 'DnN', '', '', '"نُضُوحٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَضَحَ). 1.""نَضْحُ الْمَاءِ"" : رَشَّاشُ الْمَاءِ. 2.""نَضْحُ العَرَقِ"" : خُرُوجُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23655, 'نُضُوحٌ', 'نضوح', 'مصدر', '', 'نضوح', 'نضح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23656, 'نَضْخٌ', 'نضخ', 'مصدر', 'نضخ', 'نضخ', 'نضخ', 'مص. نَضَخَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَضْخٌ-نَضْخٌ [ن ض خ] (مص. نَضَخَ). ""مَا زَالَ النَّضْخُ يَعْبَقُ مِنْ ثَوْبِهَا"" : أَثَرُ الطِّيبِ الْمُتَبَقَّى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23657, 'تَنْضِيدٌ', 'تنضيد', 'مصدر', 'نضد', 'تنضيد', 'تنضد', 'مص. نَضَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْضِيدٌ-تَنْضِيدٌ [ن ض د] (مص. نَضَّدَ). 1. ""تَنْضِيدُ الأثَاثِ"": تَنْسِيقُهُ، تَرْتِيبُهُ. 2. ""تَنْضِيدُ الكُتُبِ"" : وَضْعُهَا مُرَتَّبَةً عَلَى الرُّفُوفِ. 3. ""تَنْضِيدُ العَقِيقِ"" : ضَمُّ بَعْضِهِ إلَى بَعْضٍ فِي اتِّسَاقٍ. 4. ""تَنْضِيدُ الحُرُوفِ الْمَطْبَعِيَّةِ"" : التَّأْلِيفُ بَيْنَهَا وَجَعْلُهَا كَلِمَاتٍ وَجُمَلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23658, 'تَنْضِيرٌ', 'تنضير', 'مصدر', 'نضر', 'تنضير', 'تنضر', 'مص. نَضَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْضِيرٌ-تَنْضِيرٌ [ن ض ر] (مص. نَضَّرَ). ""تَنْضِيرُ وَجْهٍ"" : جَعْلُهُ نَاضِراً مُشْرِقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23659, 'نَظَرٌ', 'نظر', 'مصدر', 'نظر', 'نظر', 'نظر', 'مص. نَظَرَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْظَارٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. نَظَرَ). 1.""أَمْعَنَ فِيهِ النَّظَرَ"" : أَمْعَنَ فِيهِ البَصَرَ. 2.""قَضِيَّةٌ فِيهَا نَظَرٌ"" : مَطْرُوحَةٌ لِلتَّفْكِيرِ وَالإِمْعَانِ لِعَدَمِ وُضُوحِهَا. ""مَسْأَلَةٌ تَحْتَ النَّظَرِ"". 3.""نَتَائِجُ تَحْتَاجُ إِلَى إِعَادَةِ النَّظَرِ"" : تَحْتَاجُ إَلَى الْمُرَاجَعَةِ وَالبَحْثِ مِنْ جَدِيدٍ. 4.""رَجُلٌ بَعِيدُ النَّظَرِ"" : بَعِيدُ الرُّؤْيَةِ، أَيْ يَنْظُرُ إِلَى الأَشْيَاءِ بِفِكْرٍ وَاسِعٍ. 5.""قَصِيرُ النَّظَرِ"" : مَنْ كَانَ بَصَرُهُ ضَعِيفاً . 6.""أَفْكَارُهُ تَدُلُّ عَلَى أَنَّهُ قَصِيرُ النَّظَرِ"" : أَيْ مَنْ كَانَ مَحْدُودَ الفِكْرِ. 7.""بِصَرْفِ النَّظَرِ عَنْ آرَائِهِ"" : بِصَرْفِ التَّفْكِيرِ. ""بِغَضِّ النَّظَرِ عَنْ سُلُوكِهِ"". 8.""نَظَرٌ سَدِيدٌ"" : رَأْيٌ سَدِيدٌ. ""هُوَ مِنْ أَهْلِ النَّظَرِ وَالعِلْمِ"". 9.""وَلَكُمْ أَيُّهَا القَاضِي وَاسِعُ النَّظَرِ"" : وَاسِعُ السُّلْطَةِ. 10.""يَلْفِتُ النَّظَرَ بِتَصَرُّفَاتِهِ"" : يُثِيرُ الاِنْتِبَاهَ... ""كَانَ مَحَطَّ أَنْظَارِ الْجَمِيعِ"" l""شَدَّ إِلَيْهِ الأَنْظَارَ"". 11.""نَظَراً لِسُلُوكِهِ أَجَازَهُ"" : اِعْتِبَاراً، اِسْتِنَاداً. ""بِالنَّظَرِ إِلَى سُلُوكِهِ"" ""نَظَراً لِلْحَيْثِيَّاتِ الْمَذْكُورَةِ أُقَرِّرُ مَا يَلِي:..."". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23660, 'نَضْرَةٌ', 'نضرة', 'مصدر', 'نضر', 'نضرة', 'نضرة', 'مص. نَضَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَضْرَةٌ-نَضْرَةٌ [ن ض ر] (مص. نَضَرَ). ""نَضْرَةُ وَجْهٍ"" : حُسْنُهُ، إِشْرَاقُهُ، رَوْنَقُهُ. ""كَانَ رَجُلاً صَالِحاً طَيِّبَ القَلْبِ مُشْرِقَ الوَجْهِ فِي نَضْرَةٍ وَحُمْرَةٍ"". (أ. أمين)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23661, 'نِطَارَةٌ', 'نطارة', 'مصدر', 'نطر', 'نطارة', 'نطرة', 'مص. نَطَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نِطَارَةٌ-نِطَارَةٌ [ن ط ر] (مص. نَطَرَ).: حِرْفَةُ النَّاطُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23662, 'تَنْطِيقٌ', 'تنطيق', 'مصدر', 'نطق', 'تنطيق', 'تنطق', 'مص. نَطَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْطِيقٌ-تَنْطِيقٌ [ن ط ق] (مص. نَطَّقَ). ""حَاوَلَ تَنْطِيقَهُ"" : جَعْلَهُ يَنْطِقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23663, 'مَنْطِقٌ', 'منطق', 'مصدر', 'نطق', 'منطق', 'منطق', 'مص. نَطَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"مَنْطِقٌ-مَنْطِقٌ [ن ط ق] (مص. نَطَقَ). 1.""تَحَدَّثَ أَمَامَ النَّاسِ بِمَنْطِقٍ"" : أَيْ بِكَلاَمٍ سَلِيمٍ مُقْنِعٍ. 2.""عِلْمُ الْمَنْطِقِ"" : عِلْمٌ قَائِمٌ عَلَى قَوَانِينَ عَقْلِيَّةٍ تَقُودُ إِلَى أَحْكَامٍ صَائِبَةٍ وَتَجَنُّبِ الْخَطَإِ. ""اِهْتَمَّ الفَلاَسِفَةُ الْمُسْلِمُونَ بِعِلْمِ الْمَنْطِقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23664, 'نُطْقٌ', 'نطق', 'مصدر', 'نطق', 'نطق', 'نطق', 'مص. نَطَقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُطْقٌ-نُطْقٌ [ن ط ق] (مص. نَطَقَ). 1.""نُطْقٌ وَاضِحٌ"" : لَفْظٌ وَاضِحٌ، إِلْقَاءُ الكَلاَمِ وَالتَّعْبِيرُ بِهِ. 2.""يَتَلَكَّأُ فِي نُطْقِهِ"" : يَتَلَكَّأُ فِي اسْتِعْمَالِ الكَلاَمِ. 3.""فَاقِدُ النُّطْقِ"" : أَبْكَمُ، أَخْرَسُ. 4. ""اِشْرَأَبَّتِ الأَعْنَاقُ فِي انْتِظَارِ النُّطْقِ بِالْحُكْمِ"" : التَّصْرِيحُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23665, 'نَطْلٌ', 'نطل', 'مصدر', 'نطل', 'نطل', 'نطل', 'مص. نَطَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَطْلٌ-نَطْلٌ [ن ط ل] (مص. نَطَلَ). 1.""نَطْلُ العِنَبِ"" : قِشْرُهُ. 2.""نَطْلُ الشَّرَابِ"" : حُثَالَتُهُ، بَقِيَّتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23666, 'تَنْظِيرٌ', 'تنظير', 'مصدر', 'نظر', 'تنظير', 'تنظر', 'مص. نَظَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْظِيرٌ-تَنْظِيرٌ [ن ظ ر] (مص. نَظَّرَ). 1. ""تَنْظِيرُ شَهَادَتَيْنِ"" : الْمُقَابَلةُ بَيْنَهُمَا. 2. ""تَنْظِيرُ أفْكَارٍ"" : التَّأمُّلُ فِيهَا مَلِيّاً لِوَضْعِهَا نَظَرِيَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23667, 'مَنْظَرٌ', 'منظر', 'مصدر', 'نظر', 'منظر', 'منظر', 'مص. نَظَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَنَاظِرُ"', '', 'R', '', '', '', '', '', '', '"(مص. نَظَرَ). 1.""مَنْظَرٌ طَبِيعِيٌّ"" : مَشْهَدٌ، أَيْ مَا يُنْظَرُ إِلَيْهِ فِي إِطَارٍ مُحَدَّدٍ. ""مَنَاظِرُ الطَّبِيعَةِ"" ""مَنْظَرٌ عَامٌّ"". 2.""كَانَ بِمَنْظَرٍ عَنْ كُلِّ مَا يَثْنِيهِ"" : بِمَعْزِلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23668, 'مَنَاظِرُ', 'مناظر', 'مصدر', '', 'مناظر', 'منظر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23669, 'نَعْبٌ', 'نعب', 'مصدر', 'نعب', 'نعب', 'نعب', 'مص. نَعَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَعْبٌ-نَعْبٌ [ن ع ب] (مص. نَعَبَ). 1.""سَيْرٌ نَعْبٌ"" : سَرِيعٌ. 2.""رِيحٌ نَعْبٌ"" : سَرِيعَةُ الْمَرِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23670, 'أَنْظَارٌ', 'أنظار', 'مصدر', '', 'ءنظار', 'نظر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23671, 'تَنْظِيفٌ', 'تنظيف', 'مصدر', 'نظف', 'تنظيف', 'تنظف', 'مص. نَظَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْظِيفٌ-تَنْظِيفٌ [ن ظ ف] (مص. نَظَّفَ). 1. ""تَرَكَ مَلابِسَهُ لِلتَّنْظِيفِ"" : لِتَطْهِيرِهَا، لِغَسْلِهَا. 2. ""تَنْظِيفُ الشَّوَارِعِ"" : إِزَالَةُ الأَوْسَاخِ وَالأزْبَالِ مِنْهَا. 3. ""مَرَّ عُمَّالُ التَّنْظِيفِ فِي الصَّبَاحِ البَاكِرِ"" : مَنْ يَسْهَرُ عَلَى نَظَافَةِ الشَّوَارِعِ وَتَنْقِيَتِها مِنَ الأزْبَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23672, 'نَظَافَةٌ', 'نظافة', 'مصدر', 'نظف', 'نظافة', 'نظفة', 'مص. نَظُفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَظَافَةٌ-نَظَافَةٌ [ن ظ ف] (مص. نَظُفَ). 1.""يُحَافِظُ عَلَى نَظَافَةِ بَيْتِهِ وَأَثْوَابِهِ"" : عَلَى نَقَاوَةِ... ""النَّظَافَةُ مِنَ الإِيمَانِ"". 2.""بَيْتُ النَّظَافَةِ"" : الْمِرْحَاضُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23673, 'تَنْظِيمٌ', 'تنظيم', 'مصدر', 'نظم', 'تنظيم', 'تنظم', 'مص. نَظَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْظِيمٌ-تَنْظِيمٌ [ن ظ م] (مص. نَظَّمَ). 1. ""تَنْظِيمُ العَمَلِ"" : تَرْتِيبُهُ وَتَدْبِيرُهُ لِيَأْخُذَ نَسَقاً مُعَيَّناً. 2. ""يَشْتَرِكُ فِي تَنْظِيمٍ سِيَاسِيٍّ"" : فِي حِزْبٍ أوْ مُنَظَّمَةٍ، لأعْضَائِهَا اِقتِنَاعَاتٌ وَأَهْدَافٌ مُشْتَرَكَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23674, 'نِظَامٌ', 'نظام', 'مصدر', 'نظم', 'نظام', 'نظم', 'مص. نَظَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نُظُمٌ:أَنْظِمَةٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. نَظَمَ). 1.""تُزَيِّنُ عُنُقَهَا بِنِظَامٍ"" : الْخَيْطُ يُنْظَمُ فِيهِ اللُّؤْلُؤُ وَنَحْوُهُ. 2.""يُحَافِظُ عَلَى النِّظَامِ"" : أَيِ الْخُضُوعُ لِلْقَوَانِينِ وَالْحِفَاظِ عَلَيْهَا. 3.""النِّظَامُ الاشْتِرَاكِيُّ"" : طَبِيعَةُ حُكْمِ الدَّوْلَةِ الْمُرْتَبِطَةِ بِتَطْبِيقِ مَبَادِئِ الاقْتِصَادِ الاشْتِرَاكِيِّ. 4.""النِّظَامُ الرَأْسُمَالِيُّ"" : أَيِ الْمُعْتَمِدُ عَلَى مَبَادِئِ الاقْتِصَادِ الرَأْسِمَالِيِّ. 5.""النِّظَامُ الْجُمْهُورِيُّ"" : شَكْلٌ مِنْ أَشْكَالِ الْحُكْمِ يَعْتَمِدُ عَلَى الانْتِخَابِ الْمُبَاشِرِ أَوْ غَيْرِ الْمُبَاشِرِ لاخْتِيَارِ رَئِيسِ الْجُمْهُورِيَّةِ. 6.""النِّظَامُ الْمَلَكِيُّ"" : أَيِ الْمُعْتَمِدُ عَلَى سُلْطَةِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23675, 'نُظُمٌ', 'نظم', 'مصدر', '', 'نظم', 'نظم', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23676, 'أَنْظِمَةٌ', 'أنظمة', 'مصدر', '', 'ءنظمة', 'نظمة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23677, 'نَظْمٌ', 'نظم', 'مصدر', 'نظم', 'نظم', 'نظم', 'مص. نَظَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَظْمٌ-نَظْمٌ [ن ظ م] (مص. نَظَمَ). 1.""نَظْمُ اللُّؤْلُؤِ"" : تَرْتِيبُهُ فِي عِقْدٍ. 2.""نَظْمُ الشِّعْرِ"" : تَأْلِيفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23678, 'نُعَابٌ', 'نعاب', 'مصدر', 'نعب', 'نعاب', 'نعب', 'مص. نَعَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُعَابٌ-نُعَابٌ [ن ع ب] (مص. نَعَبَ). ""نُعَابُ الغُرَابِ"" : نُعَاقُهُ، نَعِيقُهُ، صَوْتُهُ، صِيَاحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23679, 'نَعْلَةٌ', 'نعلة', 'مصدر', 'نعل', 'نعلة', 'نعلة', 'مص. نَعَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نِعَالٌ:أَنْعُلٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَعَلَ) (مؤ). 1.""نَعِلَالنَّعْلَ"" : نَعِلَ الْحِذَاءَ. 2.""نَعْلُ الْحِذَاءِ أَوْ نَعْلَتُهُ "" : جِلْدٌ سَمِيكٌ يُوضَعُ أَسْفَلَ الْحِذَاءِ. 3.""نَعْلُ الدَّابَّةِ أَوْ نَعْلُها"" : حَدِيدَةٌ مُقَوَّسَةٌ يُوقَى بِهَا الْحَافِرُ لِحِمَايَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23680, 'نَعِيبٌ', 'نعيب', 'مصدر', 'نعب', 'نعيب', 'نعب', 'مص. نَعَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَعِيبٌ-نَعِيبٌ [ن ع ب] (مص. نَعَبَ). ""نَعِيبُ الغُرَابِ"" : صِيَاحُهُ، صَوْتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23681, 'نَعْتٌ', 'نعت', 'مصدر', 'نعت', 'نعت', 'نعت', 'مص. نَعَتَ', '', '', 'مفرد', 'DnN', '', '', '"نُعُوتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَعَتَ). 1.""رَفَضَ نَعْتَهُ بِمَا لَيْسَ فِيهِ"" : وَصْفَهُ. 2.""نُعُوتُ الْخَيْرِ"" : صِفَاتُهُ. 3.""النَّعْتُ فِي النَّحْوِ"" : الصِّفَةُ الْمُكَمِّلَةُ لِمَعْنَى الكَلِمَةِ الَّتِي قَبْلَهَا، أَوْ لِمَعْنـىً يَرْتَبِطُ، بِهَا وَالنَّعْتُ يَتْبَعُ الْمَنْعُوتَ فِي كُلِّ أَحْوَالِهِ: ""اِلْتَقَيْتُ الرَّجُلَ الشُّجَاعَ"" ""سَطَعَتْ شَمْسٌ مُحْرِقَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23682, 'نُعُوتٌ', 'نعوت', 'مصدر', '', 'نعوت', 'نعت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23683, 'نَعِيرٌ', 'نعير', 'مصدر', 'نعر', 'نعير', 'نعر', 'مص. نَعَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَعِيرٌ-نَعِيرٌ [ن ع ر] (مص. نَعَرَ). 1.""اِشْتَدَّ نَعِيرُ الْمُتَحَارِبِـينَ"" : الصِّيَاحُ، الصُّرَاخُ فِي الْحَرْبِ، أَوْ فِي لَحَظَاتِ الْكَوَارِثِ. 2.""هُوَ نَعِيرُ الْهَمِّ"" : بَعِيدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23684, 'نُعَاسٌ', 'نعاس', 'مصدر', 'نعس', 'نعاس', 'نعس', 'مص. نَعَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُعَاسٌ-نُعَاسٌ [ن ع س] (مص. نَعَسَ). ""أَخَذَهُ النُّعَاسُ"" : أَوَّلُ النَّوْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23685, 'نَعْشٌ', 'نعش', 'مصدر', 'نعش', 'نعش', 'نعش', 'مص. نَعَشَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَعْشٌ-نَعْشٌ [ن ع ش] (مص. نَعَشَ). 1.""رَفَعُوا النَّعْشَ فَارْتَفَعَ النَّحِيبُ وَالعَوِيلُ"" : سَرِيرُ الْمَيِّتِ يُحْمَلُ عَلَيْهِ إِلَى قَبْرِهِ. 2.""بَنَاتُ نَعْشٍ كُبْرَى"" (فك) : سَبْعَةُ كَوَاكِبَ تُشَاهَدُ جِهَةَ القُطْبِ الشَّمَالِيِّ وَبِقُرْبِهَا سَبْعَةٌ أُخْرَى تُسَمَّى بَنَاتِ نَعْشٍ الصُّغْرَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23686, 'نُعَاقٌ', 'نعاق', 'مصدر', 'نعق', 'نعاق', 'نعق', 'مص. نَعَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَعَّاقٌ-نَعَّاقٌ [ن ع ق] (صِيغَة فَعَّال لِلْمُبَالَغَةِ). 1. ""وَلَدٌ نَعَّاقٌ"" : كَثِيرُ النَّعِيقِ مِثْلَ الغُرَابِ. 2. ""غُرَابٌ نَعَّاقٌ"" : كَثِيرُ الصِّيَاحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23687, 'نَعِيقٌ', 'نعيق', 'مصدر', 'نعق', 'نعيق', 'نعق', 'مص. نَعَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَعِيقٌ-نَعِيقٌ [ن ع ق] (مص. نَعَقَ). ""نَعِيقُ الغُرَابِ"" : صَوْتُهُ، صِيَاحُهُ، نَعِيبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23688, 'نَعْلٌ', 'نعل', 'مصدر', 'نعل', 'نعل', 'نعل', 'مص. نَعَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نِعَالٌ:أَنْعُلٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَعَلَ) (مؤ). 1.""نَعِلَالنَّعْلَ"" : نَعِلَ الْحِذَاءَ. 2.""نَعْلُ الْحِذَاءِ أَوْ نَعْلَتُهُ "" : جِلْدٌ سَمِيكٌ يُوضَعُ أَسْفَلَ الْحِذَاءِ. 3.""نَعْلُ الدَّابَّةِ أَوْ نَعْلُها"" : حَدِيدَةٌ مُقَوَّسَةٌ يُوقَى بِهَا الْحَافِرُ لِحِمَايَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23689, 'نَعِيمَةٌ', 'نعيمة', 'مصدر', 'نعم', 'نعيمة', 'نعمة', 'مص. نَعِمَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَعِيمٌ-نَعِيمٌ، ةٌ [ن ع م] (مص. نَعِمَ) (صِيغَةُ فَعِيل). 1.""هُوَ فِي نَعِيمٍ"" : فِي طِيبِ عَيْشٍ وَرَغَدٍ وَسَعَادَةٍ.الطور آية 17 إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَنَعِيمٍ (قرآن). 2.""رَجُلٌ نَعِيمُ البَالِ"" : مُرْتَاحٌ وَهَادِئُ البَالِ. 3.""نَعِيمُ اللَّهِ"" : رَحْمَتُهُ. 4.""نَعيمٌ"" : اِسْمُ عَلَمٍ للذُّكُورِ وَ""نَعِيمَةُ"" : اِسْمُ عَلَمٍ لِلإِنَاثِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23690, 'نِعَالٌ', 'نعال', 'مصدر', '', 'نعال', 'نعل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23691, 'أَنْعُلٌ', 'أنعل', 'مصدر', '', 'ءنعل', 'نعل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23692, 'تَنْعِيمٌ', 'تنعيم', 'مصدر', 'نعم', 'تنعيم', 'تنعم', 'مص. نَعَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْعِيمٌ-تَنْعِيمٌ [ن ع م] (مص. نَعَّمَ). 1.""تَنْعِيمُ ثَوْبٍ"" : جَعْلُهُ نَاعِماً. 2.""تَنْعِيمُ الرَّجُلِ"" : جَعْلُهُ يَنْعَمُ بِرَفَاهِيَةٍ وَحَيَاةٍ طَيِّبَةٍ هَنِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23693, 'نُعُومَةٌ', 'نعومة', 'مصدر', 'نعم', 'نعومة', 'نعمة', 'مص. نَعَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُعُومَةٌ-نُعُومَةٌ [ن ع م] (مص. نَعَمَ). 1.""نُعُومَةُ ثَوْبٍ"" : لُيُونَةُ مَلْمَسِهِ. 2.""مُنْذُ نُعُومَةِ أَظْفَارِهِ"" : مُنْذُ طُفُولَتِهِ، مُنْذُ صِبَاهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23694, 'نَعْمَةٌ', 'نعمة', 'مصدر', 'نعم', 'نعمة', 'نعمة', 'مص. نَعِمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَعْمَةٌ-نَعْمَةٌ [ن ع م] (مص. نَعِمَ). 1.""هُوَ فِي نَعْمَةِ عَيْشٍ"": أَيْ فِي رَغْدٍ وَطِيبِ عَيْشٍ. 2.""سَأَفْعَلُهُ نَعْمَةَ عَيْنٍ"" : أَيْ إِنْعَاماً لِعَيْنِكَ وَإِكْرَاماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23695, 'نَعَمٌ', 'نعم', 'مصدر', 'نعم', 'نعم', 'نعم', 'مص. نَعِمَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْعَامٌجأَنَاعيمُ"', '', 'R', '', '', '', '', '', '', '"(مص. نَعِمَ).السجدة آية 27فَنُخْرِجُ بِهِ زَرْعاً تَأْكُلُ مِنْهُ أَنْعَامُهُمْ وَأَنْفُسُهُمْ (قرآن) : الإِبِلُ، وَتُطْلَقُ أَيْضاً عَلَى الغَنَمِ وَالْمَاعِزِ وَالبَقَرِ وَالْحَمِيرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23696, 'أَنْعَامٌ', 'أنعام', 'مصدر', '', 'ءنعام', 'نعم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23697, 'أَنَاعيمُ', 'أناعيم', 'مصدر', '', 'ءناعيم', 'نعم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23698, 'نَعِيمٌ', 'نعيم', 'مصدر', 'نعم', 'نعيم', 'نعم', 'مص. نَعِمَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَعِيمٌ-نَعِيمٌ، ةٌ [ن ع م] (مص. نَعِمَ) (صِيغَةُ فَعِيل). 1.""هُوَ فِي نَعِيمٍ"" : فِي طِيبِ عَيْشٍ وَرَغَدٍ وَسَعَادَةٍ.الطور آية 17 إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَنَعِيمٍ (قرآن). 2.""رَجُلٌ نَعِيمُ البَالِ"" : مُرْتَاحٌ وَهَادِئُ البَالِ. 3.""نَعِيمُ اللَّهِ"" : رَحْمَتُهُ. 4.""نَعيمٌ"" : اِسْمُ عَلَمٍ للذُّكُورِ وَ""نَعِيمَةُ"" : اِسْمُ عَلَمٍ لِلإِنَاثِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23699, 'نِعْمَةٌ', 'نعمة', 'مصدر', 'نعم', 'نعمة', 'نعمة', 'مص. نَعَمَ، نَعِمَ.', '', '', 'مفرد', 'DnN', '', '', '"نِعَمٌ:أَنْعُمٌ:نَعَمَاتٌ"', '', 'R', '', '', '', '', '', '', '"ج: نِعَمٌ، أَنْعُمٌ، نَعَمَاتٌ. (مص. نَعَمَ، نَعِمَ). 1.""هُوَ فِي نِعْمَةٍ شَامِلَةٍ"" : فِي حُسْنِ حَالٍ وَمَالٍ. ""إِنَّ نِعْمَةَ الْحُبِّ هِيَ نِعْمَةُ النِّعَمِ"" (إسحق الحسيني) l""عَلَى قَدْرِ النِّعْمَةِ تَكُونُ النِّقْمَةُ"". 2.الضحى آية 11وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ (قرآن) : مَا أُنْعِمَ بِهِ اللَّهُ مِنْ رِزْقٍ وَمَالٍ وَغَيْرِهِ. 3.""لَكَ عِنْدِي نِعْمَةٌ لاَ تُنْكَرُ"" : صَنِيعَةٌ. ""هُوَ وَلِيُّ نِعْمَتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23700, 'نِعَمٌ', 'نعم', 'مصدر', '', 'نعم', 'نعم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23701, 'أَنْعُمٌ', 'أنعم', 'مصدر', '', 'ءنعم', 'نعم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23702, 'نَعَمَاتٌ', 'نعمات', 'مصدر', '', 'نعمات', 'نعمت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23703, 'نَعْنَعَةٌ', 'نعنعة', 'مصدر', 'نعنع', 'نعنعة', 'نعنعة', 'مص. نَعْنَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَعْنَعَةٌ-نَعْنَعَةٌ [ن ع ن ع] (مص. نَعْنَعَ). ""فِي لِسَانِهِ نَعْنَعَةٌ"" : عُجْمَةٌ، أَيْ عَدَمُ الإِفْصَاحِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23704, 'نَعْيٌ', 'نعي', 'مصدر', 'نعي', 'نعي', 'نع', 'مص. نَعَى', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَعْيٌ-نَعْيٌ [ن ع ي] (مص. نَعَى). ""وَصَلَ نَعْيُهُ إِلَى الأَهْلِ"": خَبَرُ مَوْتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23705, 'تَنْغِيصٌ', 'تنغيص', 'مصدر', 'نغص', 'تنغيص', 'تنغص', 'مص. نَغَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْغِيصٌ-تَنْغِيصٌ [ن غ ص] (مص. نَغَّصَ). ""تَنْغِيصُ العَيْشِ"" : تَكْدِيرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23706, 'تَنْغِيمٌ', 'تنغيم', 'مصدر', 'نغم', 'تنغيم', 'تنغم', 'مص. نَغَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْغِيمٌ-تَنْغِيمٌ [ن غ م] (مص. نَغَّمَ). التَّنْغِيمُ فِي اللَّحْنِ"" : الإنْشَادُ، التَّطْرِيبُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23707, 'نَغْمٌ', 'نغم', 'مصدر', 'نغم', 'نغم', 'نغم', 'مص. نَغَمَ، نَغِمَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْغَامٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَغَمَ، نَغِمَ). ""كَانَ نَغَمُهُ مِنْ أَرْوَعِ الأَنْغَامِ"" : لَحْنُهُ، تَطْرِيبُهُ. ""أَنْغَامُ الْمُوسِيقَى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23708, 'أَنْغَامٌ', 'أنغام', 'مصدر', '', 'ءنغام', 'نغم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23709, 'نَفْثٌ', 'نفث', 'مصدر', 'نفث', 'نفث', 'نفث', 'مص. نَفَثَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَفْثٌ-نَفْثٌ [ن ف ث] (مص. نَفَثَ). 1.""نَفْثُ البُصَاقِ مِنَ الفَمِ"" : رَمْيُهُ. 2.""نَفْثُ الدَّمِ"" : إِخْرَاجُ الدَّمِ الْمَنْزُوفِ مِنَ الرِّئَتَيْنِ. 3.""نَفْثُ الشَّيْطَانِ "" : شِعْرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23710, 'نَفْحٌ', 'نفح', 'مصدر', 'نفح', 'نفح', 'نفح', 'مص. نَفَحَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَفْحٌ-نَفْحٌ [ن ف ح] (مص. نَفَحَ). ""نَفْحُ الرِّيحِ"" : هُبُوبُهَا فِي الْبَرْدِ خِلاَفَ لَفْحِهَا فِي الْحَرِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23711, 'تَنفيخٌ', 'تنفيخ', 'مصدر', 'نفخ', 'تنفيخ', 'تنفخ', 'مص. نَفَّخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنفيخٌ-تَنفيخٌ [ن ف خ] (مص. نَفَّخَ). ""التَّنْفِيخُ فِي البُوقِ"" : النَّفْخُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23712, 'نَفَادٌ', 'نفاد', 'مصدر', 'نفد', 'نفاد', 'نفد', 'مص. نَفَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَفَادٌ-نَفَادٌ [ن ف د] (مص. نَفَدَ). 1.""نَفَادُ الشَّيْءِ"" : فَنَاؤُهُ.ص آية 54إِنَّ هَذَا لَرِزْقُنَا مَا لَهُ مِن نَفَادٍ (قرآن). 2.""نَفَادُ البِضَاعَةِ الْجَدِيدَةِ"" : اِنْقِضَاؤُهَا. ""نَفَادُ الطَّبْعَةِ الأُولَى مِنَ الكِتَابِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23713, 'تَنْفِيذٌ', 'تنفيذ', 'مصدر', 'نفذ', 'تنفيذ', 'تنفذ', 'مص. نَفَّذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَنْفِيذٌ-تَنْفِيذٌ [ن ف ذ] (مص. نَفَّذَ). 1. ""تَعَهَّدَ بِتَنْفِيذِ وَعْدِهِ"": بِإنْجَازِهِ وَالْمُبَاشَرَةِ فِي تَحْقِيقِهِ. 2. ""قَرَّرَتِ الْمَحْكَمَةُ تَنْفِيذَ حُكْمِهَا"" : تَطْبِيقَهُ. 3. ""دَخَلَ الْمَشْرُوعُ فِي حَيِّزِ التَّنْفِيذِ"": فِي طَوْرِ الإِنْجَازِ وَالتَّحْقِيقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23714, 'نَفَاذٌ', 'نفاذ', 'مصدر', 'نفذ', 'نفاذ', 'نفذ', 'مص. نَفَذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَفَاذٌ-نَفَاذٌ [ن ف ذ] (مص. نَفَذَ). 1.""نَفَاذُ السَّهْمِ"" : خُرُوجُهُ. 2.""نَفَاذُ البَصِيرَةِ"" : فِطْنَتُهَا، ذَكَاؤُهَا. 3. ""نَفَاذُ حُكْمٍ"" : تَطْبِيقُهُ وَتَنْفِيذُهُ حَالاً. ""الْحُكْمُ مَعَ النَّفَاذِ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23715, 'نُفُوذٌ', 'نفوذ', 'مصدر', 'نفذ', 'نفوذ', 'نفذ', 'مص. نَفَذَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُفُوذٌ-نُفُوذٌ [ن ف ذ] (مص. نَفَذَ). 1.""لَهُ نُفُوذٌ وَسَطَ أَهْلِهِ"": سُلْطَةٌ، تَأْثِيرٌ. ""هُوَ ذُو نُفُوذٍ أَدَبِيٍّ"" ""نُفُوذٌ سِيَاسِيٌّ"". 2.""مِنْطَقَةُ نُفُوذٍ"" : مِنْطَقَةٌ تَبْسُطُ عَلَيْهَا دَوْلَةٌ كُبْرَى سُلْطَانَهَا وَهَيْمَنَتَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23716, 'تَنْفِيرٌ', 'تنفير', 'مصدر', 'نفر', 'تنفير', 'تنفر', 'مص. نَفَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْفِيرٌ-تَنْفِيرٌ [ن ف ر] (مص. نَفَّرَ). 1.""حَاوَلَ تَنْفِيرَهُ مِنَ الأَكْلِ"" : جَعْلَهُ يَنْفِرُ مِنْهُ. 2. ""تَنْفِيرُ حَيَوَانٍ"" : إفْزَاعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23717, 'نِفَارٌ', 'نفار', 'مصدر', 'نفر', 'نفار', 'نفر', 'مص. نَفَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نِفَارٌ-نِفَارٌ [ن ف ر] (مص. نَفَرَ). ""أَظهْرَ لَهُ نِفَاراً"" : كُرْهاً، إِعْرَاضاً. ""نَفَرْتُ مِنْ ذَلِكَ نِفَاراً شَدِيداً"". (معاوية بن أبي سفيان)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23718, 'نَفْرٌ', 'نفر', 'مصدر', 'نفر', 'نفر', 'نفر', 'مص. نَفَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَفْرٌ-نَفْرٌ [ن ف ر] (مص. نَفَرَ). 1.""قَوْمٌ نَفْرٌ"" : النَّافِرُونَ إِلَى أَمْرٍ أَوْ قِتَالٍ. 2.""يَوْمُ النَّفْرِ"" : الْيَوْمُ الَّذِي يَنْفِرُ فِيهِ الْحَاجُّ مِنْ مِنـىً إِلَى مَكَّةَ. وَهُوَ الْيَوْمُ الثَّالِثُ مِنْ يَوْمِ النَّحْرِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23719, 'نَفْضٌ', 'نفض', 'مصدر', 'نفض', 'نفض', 'نفض', 'مص. نَفَضَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَفْضٌ-نَفْضٌ [ن ف ض] (مص. نَفَضَ). 1. ""نَفْضُ الْغُبَــارِ"" : إِزَالَتُهُ. 2.""نَفْضُ الْحُبُوبِ"" : إِزَالَةُ مَا عَلِقَ بِهِ مِنْ غُبَارٍ بِتَحْرِيكِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23720, 'نُفُورٌ', 'نفور', 'مصدر', 'نفر', 'نفور', 'نفر', 'مص. نَفَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُفُورٌ-نُفُورٌ [ن ف ر] (مص. نَفَرَ). ""لَمْ يَكُنْ نُفُورُهُ إِلاَّ نُفُوراً عَارِضاً"" : الْكُرْهُ، الإِعْرَاضُ، التَّبَاعُدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23721, 'تَنْفِيسٌ', 'تنفيس', 'مصدر', 'نفس', 'تنفيس', 'تنفس', 'مص. نَفَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْفِيسٌ-تَنْفِيسٌ [ن ف س] (مص. نَفَّسَ). ""سَعَى إلَى التَّنْفِيسِ عَنْ هُمُومِهِ"" : التَّفْريجِ، التَّلْطِيفِ، التَّرْفِيهِ عَنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23722, 'نَفْسٌ', 'نفس', 'مصدر', 'نفس', 'نفس', 'نفس', 'مص. نَفَسَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْفُسٌ:نُفُوسٌ(مذ:مؤ)"', '', 'Rp', '', '', '', '', '', '', '"(مص. نَفَسَ). 1.""خَرَجَتْ نَفْسُهُ"" : خَرَجَتْ رُوحُهُ، أَيْ مَاتَ. ""جَادَ بِنَفْسِهِ""الفجر آية 27يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ ارْجِعِي إِلَى رَبِّكِ رَاضِيَةً مَرْضِيَّة (قرآن) l ""بَذَلَ النَّفْسَ وَالنَّفِيسَ"". 2.""يَعْتَمِدُ عَلَى نَفْسِهِ"" : عَلَى ذَاتِهِ. ""الِاعْتِمَادُ عَلَى النَّفْسِ"". 3.""خَرَجَ يُرَوِّحُ عَلَى نَفْسِهِ"" : عَلَى خَاطِرِهِ، عَلَى بَالِهِ. ""التَّرْوِيحُ عَلَى النَّفْسِ"". 4.""يَسْكُنُ الدَّارَ عَشْرَةَ أَنْفُسٍ"" : أَفْرَادٍ، أَشْخَاصٍ، نَفَرٍ. 5. ""خَطَبَهَا إِلَى"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23723, 'أَنْفُسٌ', 'أنفس', 'مصدر', '', 'ءنفس', 'نفس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23724, 'نُفُوسٌ', 'نفوس', 'مصدر', '', 'نفوس', 'نفس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23725, 'نَفَسٌ', 'نفس', 'مصدر', 'نفس', 'نفس', 'نفس', 'مص. نَفِسَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْفَاسٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. نَفِسَ). 1.""ظَلَّ نَفَسُهُ مُتَهَدِّجاً"" : رِيحٌ تَدْخُلُ وَتَخْرُجُ مِنَ الْحَيِّ ذِي الرِّئَةِ مِنْ أَنْفِهِ وَفَمِهِ فِي حَالِ التَّنَفُّسِ، نَفْثٌ، نَفْحَةٌ. ""أَخْرَجَ نَفَساً"". 2.""طَوِيلُ النَّفَسِ"" : ذُو سَعَةٍ وَتَمَهُّلٍ. 3.""هُوَ ذُو نَفَسٍ"" : ذُو خُلُقٍ وَجَلَدٍ. 4.""هُوَ فِي نَفَسٍ مِنْ أَمْرِهِ"" : فِي سَعَةٍ وَفُسْحَةٍ. 5.""أَمْسَكَ أَنْفَاسَهُ"" : أَمْسَكَ مَشَاع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23726, 'أَنْفَاسٌ', 'أنفاس', 'مصدر', '', 'ءنفاس', 'نفس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23727, 'نِفَاسٌ', 'نفاس', 'مصدر', 'نفس', 'نفاس', 'نفس', 'مص. نَفِسَ، نَفُسَ، نَافَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نِفَاسٌ-نِفَاسٌ [ن ف س] (مص. نَفِسَ، نَفُسَ، نَافَسَ). 1.""نِفَاسُ الْمَرْأَةِ"" : وِلاَدَتُهَا. ""أَلَمُ النِّفَاسِ"". 2.""اِنْقَطَعَ نِفَاسُهَا"" : الدَّمُ الَّذِي يَنْزِلُ مِنَ الْمَرْأَةِ بَعْدَ الوِلاَدَةِ. 3.""مَا زَالَتْ فِي مَرْحَلَةِ النِّفَاسِ"" : الْمُدَّةُ الَّتِي تَعْقُبُ الوَضْعَ لِتَعُودَ فِيهَا الرَّحِمُ إِلَى حَالَتِهَا العَادِيَةِ وَتَدُومُ سِتَّةَ أَسَابِيعَ تَقْرِيباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23728, 'تَنْفِيشٌ', 'تنفيش', 'مصدر', 'نفش', 'تنفيش', 'تنفش', 'مص. نَفَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْفِيشٌ-تَنْفِيشٌ [ن ف ش] (مص. نَفَّشَ). ""تَنْفِيشُ الصُّوفِ"" : شَقُّهُ، تَفْرِيقُهُ، نَفْشُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23729, 'تَنْقِيبٌ', 'تنقيب', 'مصدر', 'نقب', 'تنقيب', 'تنقب', 'مص. نَقَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْقِيبٌ-تَنْقِيبٌ [ن ق ب] (مص. نَقَّبَ). 1. ""أسْفَرَ تَنْقِيبُ الْمُهَنْدِسِينَ عَنْ وُجُودِ آبَارِ النَّفْطِ"" : البَحْثُ الدَّقِيقُ بِوَسَائِلَ تِقْنِيَّةٍ عَنْ وُجُودِ النَّف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23730, 'تَنْفِيضٌ', 'تنفيض', 'مصدر', 'نفض', 'تنفيض', 'تنفض', 'مص. نَفّضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْفِيضٌ-تَنْفِيضٌ [ن ف ض] (مص. نَفّضَ). 1. ""تَنْفِيضُ ثَوْبٍ"" : تَحْرِيكُهُ لِيَزُولَ عَنْهُ الغُبَارُ. 2. ""تَنْفِيضُ شَجَرَةٍ "" : تَحْرِيكُهَا لِيَسْقُطَ مَا عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23731, 'نَفْطٌ', 'نفط', 'مصدر', 'نفط', 'نفط', 'نفط', 'مص. نَفَطَ، نَفِطَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَفْطٌ-نَفْطٌ [ن ف ط] (مص. نَفَطَ، نَفِطَ). : البِتْرُولُ، هُوَ زَيْتٌ مَعْدِنِيٌّ يُوجَدُ فِي آبَارٍ، مُرَكَّبٌ مِنْ عُنْصُرَيِ الْكَرْبُونِ وَالْهِيدْرُوجِينِ يُحْصَلُ عَلَيْهِ بِتَقْطِيرِ زَيْتِ الْبِتْرُولِ، وَهُوَ سَرِيعُ الِاحْتِرَاقِ، تُوقَدُ بِهِ النَّارُ وَيُسْتَخْدَمُ وَقُوداً لِلْمُحَرِّكَاتِ. ""نَفْطٌ خَامٌّ"" ""نَفْطٌ مُكَرَّرٌ"" ""صِبَاغَةُ النَّفْطِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23732, 'تَنْفِيعٌ', 'تنفيع', 'مصدر', 'نفع', 'تنفيع', 'تنفع', 'مص. نَفَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْفِيعٌ-تَنْفِيعٌ [ن ف ع] (مص. نَفَّعَ). ""تَنْفِيعُ رَجُلٍ"" : الْمُبَالَغَةُ فِي نَفْعِهِ، إفَادَتُهُ، إيصَالُ النَّفْعِ إلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23733, 'نَفْعٌ', 'نفع', 'مصدر', 'نفع', 'نفع', 'نفع', 'مص. نَفَعَ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"نَفْعٌ-نَفْعٌ [ن ف ع] (مص. نَفَعَ). 1. ""عَمَلٌ فِيهِ نَفْعٌ عَمِيـمٌ"" : فَائِدَةٌ. ""عَمَلُهُ لَا يُجْدِي نَفْعاً"" ""النَّفْعُ العَامُّ"". 2.""لَهُ نَفْعٌ فِي أَدَاءِ وَاجِبَاتِهِ"" : خَيْرٌ وَمَا يَتَوَصَّلُ بِهِ الْإِنْسَانُ إِلَى الْمَطْلُوبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23734, 'تَنْفِيقٌ', 'تنفيق', 'مصدر', 'نفق', 'تنفيق', 'تنفق', 'مص. نَفَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْفِيقٌ-تَنْفِيقٌ [ن ف ق] (مص. نَفَّقَ). ""تَنْفِيقُ البَضَائِعِ"" : تَرْوِيجُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23735, 'تَنْفِيلٌ', 'تنفيل', 'مصدر', 'نفل', 'تنفيل', 'تنفل', 'مص. نَفَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْفِيلٌ-تَنْفِيلٌ [ن ف ل] (مص. نَفَّلَ). ""تَنْفِيلُ رَجُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23736, 'نَفْلٌ', 'نفل', 'مصدر', 'نفل', 'نفل', 'نفل', 'مص. نَفَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نُفَلٌ-نُفَلٌ [ن ف ل]. ""نُفَلُ الشَّهْرِ القَمَرِيِّ"" : ثَلاَثُ لَيَالٍ مِنْهُ بَعْدَ الغُرَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23737, 'نَفْيٌ', 'نفي', 'مصدر', 'نفي', 'نفي', 'نف', 'مص. نَفَى', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَفْيٌ-نَفْيٌ [ن ف ي] (مص. نَفَى). 1.""لَمْ يَكُنْ يَنْتَظِرُ الْإِجَابَةَ عَنْ طَلَبِهِ بِالنَّفْيِ"" : بِالرَّفْضِ. 2.""شَاهِدُ النَّفْيِ"" : شَاهِدُ الدِّفَاعِ. 3.""حَكَمُوا عَلَيْهِ بِالنَّفْيِ"" : بِالْإ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23738, 'نَقِيقٌ', 'نقيق', 'مصدر', 'نقق', 'نقيق', 'نقق', 'مص. نَقَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَقِيقٌ-نَقِيقٌ [ن ق ق] (مص. نَقَّ). ""نَقِيقُ الضَّفَادِعِ"" : صَوْتُهَا. ""وَسَكَنَتِ الأَصْوَاتُ إِلاَّ مِنْ نَقِيقِ الضَّفَادِعِ وَالدَّجَاجِ وَالنَّعَامِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23739, 'تَنْقِيشٌ', 'تنقيش', 'مصدر', 'نقش', 'تنقيش', 'تنقش', 'مص. نَقَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْقِيشٌ-تَنْقِيشٌ [ن ق ش] (مص. نَقَّشَ). ""تَنْقِيشُ لَوْحٍ"" : تَلْوِينُهُ، زَخْرَفَتُهُ بِزَخَارِفِ الألْوَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23740, 'نِقَابَةٌ', 'نقابة', 'مصدر', 'نقب', 'نقابة', 'نقبة', 'مص. نَقَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"(مص. نَقَبَ). ""نِقَابَةُ الْعُمَّالِ"" : تَجَمُّعٌ تَنْظِيمِيٌّ لِلْعُمَّالِ وَأَصْحَابِ الْحِرَفِ وَالْمِهَنِ للِدِّفَاعِ عَنْ حُقُوقِهِمْ وَمَصَالِحِهِمُ الْمُشْتَرَكَةِ. """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23741, 'نَقْبٌ', 'نقب', 'مصدر', 'نقب', 'نقب', 'نقب', 'مص. نَقَبَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْقَابٌ"', '', 'R', '', '', '', '', '', '', '"ج: أَنْقَابٌ. (مص. نَقَبَ). 1.""نَقْبُ الأَرْضِ"" : حَفْرُهَا، خَرْقُهَا. 2. ""النَّقْبُ فِي الْجِدَارِ"" : ثَقْبُهُ. 3. ""النَّقْبُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23742, 'أَنْقَابٌ', 'أنقاب', 'مصدر', '', 'ءنقاب', 'نقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23743, 'تَنْقِيحٌ', 'تنقيح', 'مصدر', 'نقح', 'تنقيح', 'تنقح', 'مص. نَقَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْقِيحٌ-تَنْقِيحٌ [ن ق ح] (مص. نَقَّحَ). 1. ""تَنْقِيحُ جِذْعٍ"" : تَشْذيبُهُ. 2. ""سَاعَدَهُ عَلَى تَنْقِيحِ إنْشَائِهِ"" : إصْلاَحِهِ وَتَعْدِيلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23744, 'نَقْدٌ', 'نقد', 'مصدر', 'نقد', 'نقد', 'نقد', 'مص. نَقَدَ', '', '', 'مفرد', 'DnN', '', '', '"نُقُودٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. نَقَدَ). 1.""دَفَعَ ثَمَنَ الْبِضاعَةِ نَقْداً"" : مَا يُدْفَعُ مِنْ دَرَاهِمَ عِنْدَ الشِّرَاءِ مُبَاشَرَةً. 2.""النُّقُودُ الْمُتَدَاوَلَةُ"" : الْعُمْلَةُ مِنْ دَرَاهِمَ مَعْدِنِيَّةٍ أَوْ أَوْرَاقٍ أَوْ ذَهَبٍ أَوْ فِضَّةٍ. ""مِحْفَظَةُ النُّقُودِ"". 3.""دِرْهَمٌ نَقْدٌ"" : جَيِّدٌ لاَ زَيْفَ فِيهِ. 4.""نَقْدُ الشِّعْرِ"" : إِظْهَارُ جَيِّدِهِ مِنْ رَدِيئِهِ، وَتَبْيَانُ قِيمَتِهِ الشِّعْرِيَّةِ. 5.""النَّقْدُ الأَدَبِيُّ"" : عِلْمٌ يَبْح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23745, 'نُقُودٌ', 'نقود', 'مصدر', '', 'نقود', 'نقد', '', '', '', 'جمع تكسير', '', '', '', '', '', 'R', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23746, 'نَقْذٌ', 'نقذ', 'مصدر', 'نقذ', 'نقذ', 'نقذ', 'مص. نَقَذَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَقْذٌ-نَقْذٌ [ن ق ذ] (مص. نَقَذَ). ""كَانَ نَقْذُهُ عَلَى يَدِهِ"" : سَلاَمَتُهُ، نَجَاتُهُ، خَلاَصُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23747, 'تَنْقِيرٌ', 'تنقير', 'مصدر', 'نقر', 'تنقير', 'تنقر', 'مص. نَقَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْقِيرٌ-تَنْقِيرٌ [ن ق ر] (مص. نَقَّرَ). 1. ""تَنْقِيرُ الطَّائِرِ الحَبَّ "": لَقْطُهُ حَبَّةً حَبَّةً. 2. ""التَّنْقِيرُ عَلَى الرَّجُلِ"" : ذِكْرُ عُيُوبِهِ، مَسَاوئِهِ. 3. ""حَاولَ التَّنْقِيرَ عَنْهُ"" : البَحْثَ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23748, 'نَقْرٌ', 'نقر', 'مصدر', 'نقر', 'نقر', 'نقر', 'مص. نَقَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَقْرٌ-نَقْرٌ [ن ق ر] (مص. نَقَرَ). 1."" نَقْرُ الْخَشَبِ"" : حَفْرُهُ. 2. ""نَقْرُ الْعُودِ"" : الْعَزْفُ عَلَيْهِ. ""يُحْسِنُونَ الرَّقْصَ عَلَى نَقْرِ الطُّبُولِ"" (م. ص. الرافعي). 3. ""نَقْرُ الطَّائِرِ"" : اِلْتِقَاطُهُ لِلْحَبِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23749, 'نِقَاعٌ', 'نقاع', 'مصدر', '', 'نقاع', 'نقع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23750, 'نَقْشٌ', 'نقش', 'مصدر', 'نقش', 'نقش', 'نقش', 'مص. نَقَشَ', '', '', 'مفرد', 'DnN', '', '', '"نُقُوشٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَقَشَ). ""النَّقْشُ عَلَى الْخَشَبِ"" : تَزْيِينُهُ بِخُطُوطٍ وَصُوَرٍ وَأَلْوَانٍ. ""الْعِلْمُ فِي الصِّغَرِ كَالنَّقْشِ عَلَى الْحَجَرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23751, 'نُقُوشٌ', 'نقوش', 'مصدر', '', 'نقوش', 'نقش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23752, 'تَنْقِيصٌ', 'تنقيص', 'مصدر', 'نقص', 'تنقيص', 'تنقص', 'مص. نَقَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْقِيصٌ-تَنْقِيصٌ [ن ق ص] (مص. نَقَّصَ). 1. ""التَّنْقِيصُ مِنَ الثَّمَنِ"" : النَّقْصُ، الخَصْمُ مِنْهُ. 2. ""التَّنْقِيصُ مِنْ قِيمَةِ الرَّجُلِ"" : الخَفْضُ مِنْ شَأْنِهِ، تَحْقِيرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23753, 'نُقْصَانٌ', 'نقصان', 'مصدر', 'نقص', 'نقصان', 'نقصن', 'مص. نَقَصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُقْصَانٌ-نُقْصَانٌ [ن ق ص] (مص. نَقَصَ). 1.""شَعَرَ بِالنُّقْصَانِ"": بِالضَّعْفِ، أَوِ الاِنْحِدَارِ. ""لِكُلِّ شَيْءٍ إِذَا مَا تَمَّ نُقْصَانُ"". (أبو البقاء الرندي). 2.""أَدَّى مَهَامَّهُ دُونَ زِيَادَةٍ وَلاَ نُقْصَانٍ"" : أَيْ لاَشَيْءَ مَنْقُوصٌ مِنْهُ عَنْ قَدْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23754, 'نَقْصٌ', 'نقص', 'مصدر', 'نقص', 'نقص', 'نقص', 'مص. نَقَصَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَقْصٌ-نَقْصٌ [ن ق ص] (مص. نَقَصَ). 1.""نَقْصٌ فِي الْمَوَادِّ الغِذَائِيَّةِ"" : عَدَمُ وَفْرَتِهَا. 2.""نَقْصٌ فِي الْأَسْعَارِ"" : خَفْضُهَا. 3.""ما مِنْ شَيْءٍ إِلاَّ وَفِيهِ نَقْصٌ"" : ضَعْفٌ، عَيْبٌ. 4.""بَدَأَ النَّقْصُ يَدِبُّ فِيهِ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23755, 'نَقْضٌ', 'نقض', 'مصدر', 'نقض', 'نقض', 'نقض', 'مص. نَقَضَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَقْضٌ-نَقْضٌ [ن ق ض] (مص. نَقَضَ). 1.""نَقْضُ الْحُكْمِ"" : إِبْطَالُهُ، إِلْغَاؤُهُ. ""نَقْضُ قَانُونٍ"". 2.""نَقْضُ مُعَاهَدَةٍ"" : خَرْقُهَا. 3.""نَقْضُ عَهْدٍ"" : النَّكْثُ بِهِ. 4.""مَحْكَمَةُ النَّقْضِ وَالإِبْرَامِ"" : الْمَحْكَمَةُ الْعُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23756, 'تَنْقِيطٌ', 'تنقيط', 'مصدر', 'نقط', 'تنقيط', 'تنقط', 'مص. نَقَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْقِيطٌ-تَنْقِيطٌ [ن ق ط] (مص. نَقَّطَ). 1.""تَنْقِيطُ الحُرُوفِ "": نَقْطُهَا وَالْمُبَالَغَةُ فِي ذَلِكَ. 2. ""تَّنْقِيطُ السَّائِلِ"" : نُزُولُهُ قَطْرَةً قَطْرَةً. 3. ""تَنْقِيطُ العَرُوسِ"" : تَقْدِيمُ الْمَالِ إلَيْهَا أوْ تَقْدِيمُ هَدِيَّةٍ إلَيْهَا عِنْدَ زِفَافِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23757, 'نَقْعٌ', 'نقع', 'مصدر', 'نقع', 'نقع', 'نقع', 'مص. نَقَعَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْقُعٌ:نِقَاعٌ:نُقُوعٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَقَعَ). 1.""سَقَطَ فِي النَّقْعِ"" : الْمَاءُ الْمُجْتَمِعُ فِي الْمُسْتَنْقَعِ. 2. العاديات آية 4فَأَثَرْنَ بِهِ نَقْعاً (قرآن) : الْغُبَارُ السَّاطِعُ. 3.""نَقْعُ البِئْرِ"" : ما اجْتَمَعَ فِيها مِنَ الْماءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23758, 'أَنْقُعٌ', 'أنقع', 'مصدر', '', 'ءنقع', 'نقع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23759, 'نَكْبٌ', 'نكب', 'مصدر', 'نكب', 'نكب', 'نكب', 'مص. نَكَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَكْبٌ-نَكْبٌ [ن ك ب] (مص. نَكَبَ). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23760, 'نُقُوعٌ', 'نقوع', 'مصدر', '', 'نقوع', 'نقع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23761, 'تَنْقِيلٌ', 'تنقيل', 'مصدر', 'نقل', 'تنقيل', 'تنقل', 'مص. نَقَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْقِيلٌ-تَنْقِيلٌ [ن ق ل] (مص. نَقَّلَ). 1. ""تَنْقِيلُ الأثَاثِ"": نَقْلُهُ. 2. ""تَنْقِيلُ الضَّيْفِ"" : إطْعَامُهُ النَّقْلَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23762, 'نَقْلٌ', 'نقل', 'مصدر', 'نقل', 'نقل', 'نقل', 'مص. نَقَلَ', '', '', 'مفرد', 'DnN', '', '', '"نُقُولٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَقَلَ). 1.""نَقْلُ نَصٍّ"": نَسْخُهُ. 2.""نَقْلُ نَصٍّ فَرَنْسِيٍّ إلى اللُّغَةِ العَرَبِيَّةِ"" : تَرْجَمَتُهُ. 3.""نَقْلُ الأَخْبَارِ"" : إِذَاعَتُهَا. 4.""نَقْلُ الْجَرْحَى"" : حَمْلُهُمْ. 5.""نَقْلُ النَّبَاتَاتِ"" : قَلْعُهَا لِإِعَادَةِ غَرْسِهَا. ""نَقْلُ الأَشْجَارِ"". 6.""نَقْلاً عَنْهُ"" : اِعْتِمَاداً عَلَيْهِ، رِوَايَةً عَنْهُ. 7.""نَقْلُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23763, 'نُقُولٌ', 'نقول', 'مصدر', '', 'نقول', 'نقل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23764, 'نَقَاهَةٌ', 'نقاهة', 'مصدر', 'نقه', 'نقاهة', 'نقهة', 'مص. نَقَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَقَاهَةٌ-نَقَاهَةٌ [ن ق هـ] (مص. نَقَهَ). ""فَتْرَةُ نَقَاهَةٍ"" : فَتْرَةُ اسْتِرَاحَةِ الْمَرِيضِ وَقَدْ بَرِئَ وَمَا زَالَ بِهِ ضَعْفٌ. ""أَقَامَ شَهْراً بِدَارِ النَّقَاهَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23765, 'نَقَاوَةٌ', 'نقاوة', 'مصدر', 'نقو', 'نقاوة', 'نقة', 'مص. نَقِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":نُقَاءٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَقِيَ). 1.""نَقَاوَةُ الْخُضَرِ"" : نَظَافَتُهَا، خِيَارُهَا. 2. ""نَقَاوَةُ قَلْبٍ"" : صَفَاؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23766, 'نُقَاءٌ', 'نقاء', 'مصدر', '', 'نقاء', 'نق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23767, 'تَنْقِيةٌ', 'تنقية', 'مصدر', 'نقو', 'تنقية', 'تنقة', 'مص. نَقَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنْقِيةٌ-تَنْقِيةٌ [ن ق و] (مص. نَقَّى). 1. ""تَنْقِيَةُ الأجْوَاءِ"" : تَصْفِيتُهَا. 2. ""تَنْقِيَةُ مَادَّةٍ"" : تَنْظِيفُهَا، تَقْطِيرُها وَتَكْرِيرُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23768, 'تَنْكِيبٌ', 'تنكيب', 'مصدر', 'نكب', 'تنكيب', 'تنكب', 'مص. نَكَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْكِيبٌ-تَنْكِيبٌ [ن ك ب] (مص. نَكَّبَ). 1. ""التَّنْكِيبُ عَنِ الشَّيْءِ"" : العُدُولُ عَنْهُ، التَّنحّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23769, 'تَنْكِيسٌ', 'تنكيس', 'مصدر', 'نكس', 'تنكيس', 'تنكس', 'مص. نَكَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْكِيسٌ-تَنْكِيسٌ [ن ك س] (مص. نَكَّسَ). 1. ""تَنْكِيسُ رَأْسٍ"": طَأْطَأَتُهُ مِنْ ذُلٍّ أوْ إهَانَةٍ. 2. ""تَنْكِيسُ مَقْعَدٍ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23770, 'تَنِكِيتٌ', 'تنكيت', 'مصدر', 'نكت', 'تنكيت', 'تنكت', 'مص. نَكَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنِكِيتٌ-تَنْكِيتٌ [ن ك ت] (مص. نَكَّتَ). 1. ""التَّنْكِيتُ فِي الكَلاَمِ"" : الإتْيَانُ بِال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23771, 'نَكْثٌ', 'نكث', 'مصدر', 'نكث', 'نكث', 'نكث', 'مص. نَكَثَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَكْثٌ-نَكْثٌ [ن ك ث] (مص. نَكَثَ). ""نَكْثُ الْعَهْدِ"" : نَقْضُهُ، عَدَمُ الْوَفَاءِ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23772, 'نِكَاحٌ', 'نكاح', 'مصدر', 'نكح', 'نكاح', 'نكح', 'مص. نَكَحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نِكَاحٌ-نِكَاحٌ [ن ك ح] (مص. نَكَحَ). ""عَقْدُ النِّكَاحِ"" : عَقْدُ الزَّوَاج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23773, 'تَنْكِيدٌ', 'تنكيد', 'مصدر', 'نكد', 'تنكيد', 'تنكد', 'مص. نَّكَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْكِيدٌ-تَنْكِيدٌ [ن ك د] (مص. نَّكَدَ). 1. ""تَنْكِيدُ عَيْشٍ"" : تَكْدِيرُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23774, 'نَكَدٌ', 'نكد', 'مصدر', 'نكد', 'نكد', 'نكد', 'مص. نَكِدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَكَدٌ-نَكَدٌ [ن ك د] (مص. نَكِدَ). 1.""أَمَرُهُ نَكَدٌ"" : أَي أَمْرٌ جَرَّ على صاحِبِهِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23775, 'تَنْكِيرٌ', 'تنكير', 'مصدر', 'نكر', 'تنكير', 'تنكر', 'مص. نَكَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْكِيرٌ-تَنْكِيرٌ [ن ك ر] (مص. نَكَّرَ). 1. ""تَنْكِيرُ الوَجْهِ"" : تَغْيِيرُ مَلاَمِحِهِ حَتَّى لاَ يُعْرَفَ. 2.""تَنْكِيرُ اسْمٍ"" : جَعْلُهُ نَكِرَةً غَيْرَ مُعَرَّفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23776, 'نُكْرٌ', 'نكر', 'مصدر', 'نكر', 'نكر', 'نكر', 'مص. نَكِرَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْكَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَكِرَ). ""إِنَّهُ لَأَمْرٌ نُكْرٌ"" : أَمْرٌ شَدِيدُ الْقُبْحِ، قَبِيحٌ، مُنْكَرٌ.الكهف آية 74لَقَدْ جِئْتَ شَيْئاً نُكْراً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23777, 'أَنْكَارٌ', 'أنكار', 'مصدر', '', 'ءنكار', 'نكر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23778, 'نَكِيرٌ', 'نكير', 'مصدر', 'نكر', 'نكير', 'نكر', 'مص. نَكِرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَكِيرٌ-نَكِيرٌ [ن ك ر] (مص. نَكِرَ). 1.""لَمْ يُظْهِرْ نَكِيراً"" : إِنْكَاراً.الشورى آية 47مَا لَكُمْ مِنْ مَلْجَأٍ يَوْمَئِذٍ وَمَا لَكُمْ مِنْ نَكِيرٍ (قرآن) ""شُتِمَ فَمَا أَبْدَى نَكِيراً"". 2.""كَانَ نَكِيرُهُ شَدِيداً"" : عُقُوبَتُهُ. 3.""أَمْرٌ نَكِيرٌ"" : صَعْبٌ. 4.""حِصْنٌ نَكِيرٌ"" : مَنِيعٌ، حَصِينٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23779, 'نَمَسٌ', 'نمس', 'مصدر', 'نمس', 'نمس', 'نمس', 'مص. نَمِسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَمَسٌ-نَمَسٌ [ن م س] (مص. نَمِسَ). ""نَمَسُ السَّمْنِ"" : فَس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23780, 'نَكْشٌ', 'نكش', 'مصدر', 'نكش', 'نكش', 'نكش', 'مص. نَكَشَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَكْشٌ-نَكْشٌ [ن ك ش] (مص. نَكَشَ). 1.""نَكْشُ الأَرْضِ"": تَقْلِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23781, 'تَنْكِيصٌ', 'تنكيص', 'مصدر', 'نكص', 'تنكيص', 'تنكص', 'مص. نَكَّصَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْكِيصٌ-تَنْكِيصٌ [ن ك ص] (مص. نَكَّصَ). ""تَنْكِيصُ أمْر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23782, 'تَنْكِيلٌ', 'تنكيل', 'مصدر', 'نكل', 'تنكيل', 'تنكل', 'مص. نَكَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْكِيلٌ-تَنْكِيلٌ [ن ك ل] (مص. نَكَّلَ). ""جَاءَ لِلتَّنْكِيلِ بِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23783, 'نِكَايَةٌ', 'نكاية', 'مصدر', 'نكي', 'نكاية', 'نكة', 'مص. نَكَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. نَكَى). ""فَعَلَ مَا فَعَلَ نِكايَةً "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23784, 'نَمٌّ', 'نم', 'مصدر', 'نمم', 'نم', 'نم', 'مص. نَمَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَمٌّ-نَمٌّ [ن م م] (مص. نَمَّ). ""رَجُلٌ نَم"', '');
