INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23786, 'نَمَاءٌ', 'نماء', 'مصدر', 'نمي', 'نماء', 'نم', 'مص. نَمَا، نَمَى', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"نَمَاءٌ-نَمَاءٌ [ن م ي] (مص. نَمَا، نَمَى). ""الزَّرْعُ فِي نَمَاءٍ"" : فِي تَكَاثُرٍ وَازْدِيَادٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23787, 'تَنَمُّرٌ', 'تنمر', 'مصدر', 'نمر', 'تنمر', 'تنمر', 'مص. نَمَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنَمُّرٌ-تَنَمُّرٌ [ن م ر] (مص. نَمَّرَ). ""أَظْهَرَ تَنَمُّراً"" : تَشَبُّهاً بِالنَّمِرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23788, 'تَنْمِيرٌ', 'تنمير', 'مصدر', 'نمر', 'تنمير', 'تنمر', 'مص. نَمَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْمِيرٌ-تَنْمِيرٌ [ن م ر] (مص. نَمَّرَ). 1.""تَنْمِيرُ الصَّفَحَاتِ"" : وَضْعُ نُمْرَةٍ، ج: نُمْرٍ، أَيْ أرْقَامٍ عَلَيْهَا. 2. ""ت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23789, 'تَنْهِيدَةٌ', 'تنهيدة', 'مصدر', 'نهد', 'تنهيدة', 'تنهدة', 'مص. نَهَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. نَهَّدَ). ""صَدَرَتْ عَنْهُ تَنْهِيدَةٌ مِلْؤُهَا الأَ‎لَمُ"" : إخْرَاجُ نَفَسٍ بَعْدَ مَدِّهِ بِتَأوُّهٍ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23790, 'نَمَشٌ', 'نمش', 'مصدر', 'نمش', 'نمش', 'نمش', 'مص. نَمِشَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"(مص. نَمِشَ). ""ظَهَرَ عَلَى جِلْدِهِ نَمَشٌ"" : بُقَعٌ، نُقَطٌ فِي الْجِلْدِ تُخَالِفُ لَوْنَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23791, 'تَنْمِيقٌ', 'تنميق', 'مصدر', 'نمق', 'تنميق', 'تنمق', 'مص. نَمَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْمِيقٌ-تَنْمِيقٌ [ن م ق] (مص. نَمَّقَ). ""لَهُ قُدْرَةٌ عَلَى تَنْمِيقِ الصُّوَرِ"" : أيْ عَلَى تَزْيِينِهَا وَتَلْوِينِهَا. ""يَسْعَى إلَى تَنْمِيقِ كَلاَمِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23792, 'نَمْنَمَةٌ', 'نمنمة', 'مصدر', 'نمنم', 'نمنمة', 'نمنمة', 'مص. نَمْنَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. نَمْنَمَ). 1.""نَمْنَمَةُ الْكِتَابِ"" : زَخْرَفَتُهُ وَتَزْيِينُهُ وَنَقْشُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23793, 'تَنْمِيَةٌ', 'تنمية', 'مصدر', 'نمو', 'تنمية', 'تنمة', 'مص. نَمَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَنْمِيَةٌ-تَنْمِيَةٌ [ن م و] (مص. نَمَّى). 1. ""سَعى إلَى تَنْمِيَةِ تِجَارَتِهِ"" : أَي الرَّفْعِ وَالزِّيَادَةِ فِي أَرْب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23794, 'نَهْبٌ', 'نهب', 'مصدر', 'نهب', 'نهب', 'نهب', 'مص. نَهَبَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَهْبٌ-نَهْبٌ [ن هـ ب] (مص. نَهَبَ). 1.""تَعَرَّضَ الْمَحْصُولُ للِنَّهْبِ"" : لِلسَّرِقَةِ الْمَفْضُوحَةِ الْقَائِمَةِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23795, 'نَهْجٌ', 'نهج', 'مصدر', 'نهج', 'نهج', 'نهج', 'مص. نَهَجَ.', '', '', 'مفرد', 'DnN', '', '', '"نُهُجٌ:نُهُوجٌ"', '', 'R', '', '', '', '', '', '', '"ج: نُهُجٌ، نُهُوجٌ. (مص. نَهَجَ). 1.""سَلَكَ نَهْجاً وَاضِحاً"" : طَرِيقاً، مَسَاراً. 2.""يَقْطُنُ فِي نَهْجِ كَذَا"" : في دَرْبٍ، زَنْقَةٍ، شَارِعٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23796, 'نُهُجٌ', 'نهج', 'مصدر', '', 'نهج', 'نهج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23797, 'نُهُوجٌ', 'نهوج', 'مصدر', '', 'نهوج', 'نهج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23798, 'نَهَجٌ', 'نهج', 'مصدر', 'نهج', 'نهج', 'نهج', 'مص. نَهِجَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَهَجٌ-نَهَجٌ [ن هـ ج] (مص. نَهِجَ). ""وَصَلَ العَدَّاءُ نَهَجاً"" : وَصَلَ وَأَنْفَاسُهُ مُتَتَابِعَةً مِنَ التَّعَبِ وَالجَرْيِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23799, 'نَهْرٌ', 'نهر', 'مصدر', 'نهر', 'نهر', 'نهر', 'مص. نَهَرَ', '', '', 'مفرد', 'DnN', '', '', '"أَنْهُرٌ:أَنْهَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. نَهَرَ). 1.""نَهْرٌ جَارٍ"" : الْمَاءُ الْعَذْبُ الْجَارِي. 2.""جَرَى النَّهْرُ"" : الْمَجْرَى، الأُخْدُودُ الَّذِي يَجْرِي فِيهِ الْمَاءُ. ""نَهْرُ النِّيلِ"" ""نَهْرُ أَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23800, 'أَنْهُرٌ', 'أنهر', 'مصدر', '', 'ءنهر', 'نهر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23801, 'أَنْهَارٌ', 'أنهار', 'مصدر', '', 'ءنهار', 'نهر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23802, 'نُهُوضٌ', 'نهوض', 'مصدر', 'نهض', 'نهوض', 'نهض', 'مص. نَهَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نُهُوضٌ-نُهُوضٌ [ن هـ ض] (مص. نَهَضَ). 1.""لاَ يَقْوَى عَلَى النُّهُوضِ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23803, 'نَهْكَةٌ', 'نهكة', 'مصدر', 'نهك', 'نهكة', 'نهكة', 'مص. نَهِكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَهْكَةٌ-نَهْكَةٌ [ن هـ ك] (مص. نَهِكَ). ""بَدَتْ فِيهِ نَهْكَةُ الْمَرَضِ"" : أَثَرُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23804, 'مَنْهَلٌ', 'منهل', 'مصدر', 'نهل', 'منهل', 'منهل', 'مص. نَهِلَ', '', '', 'مفرد', 'DnN', '', '', '"مَنَاهِلُ"', '', 'R', '', '', '', '', '', '', '"(مص. نَهِلَ). 1.""اِهْتَدَوا إِلَى مَنْهَلٍ تَحْتَ سَفْحِ الْجَبَلِ"" : م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23805, 'مَنَاهِلُ', 'مناهل', 'مصدر', '', 'مناهل', 'منهل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23806, 'نَهِيمٌ', 'نهيم', 'مصدر', 'نهم', 'نهيم', 'نهم', 'مص. نَهَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"نَهِيمٌ-نَهِيمٌ [ن هـ م] (مص. نَهَمَ). 1.""رَجُلٌ نَهِيمٌ"" : ذُو نَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23807, 'نَهَمٌ', 'نهم', 'مصدر', 'نهم', 'نهم', 'نهم', 'مص. نَهِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَهَمٌ-نَهَمٌ [ن هـ م] (مص. نَهِمَ). ""أَظْهَرَ نَهَماً"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23808, 'نَهْيٌ', 'نهي', 'مصدر', 'نهي', 'نهي', 'نه', 'مص. نَهَى', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَهْيٌ-نَهْيٌ [ن هـ ي] (مص. نَهَى). 1.""الأَمْرُ بِالْمَعْرُوفِ وَالنَّهْيُ عَنِ الْمُنْكَرِ"" : طَلَبُ تَرْكِ الْمُنْكَرِ وَعَدَمُ فِعْلِهِ. 2.""هُوَ صَاحِبُ الأَمْرِ وَالنَّهْيِ"" : أَيِ الَّذِي يَأْمُرُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23809, 'تَنْوِيرٌ', 'تنوير', 'مصدر', 'نور', 'تنوير', 'تنر', 'مص. نَوَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْوِيرٌ-تَنْوِيرٌ [ن و ر] (مص. نَوَّرَ). 1. ""تَنْوِيرُ البَيْتِ بِمَصَابِيحَ مُلَوَّنَةٍ"" : إضَاءَتُهُ. 2. ""عَمِلَ عَلَى تَنْوِيرِ فِكْرِهِ"" : جَعْلِهِ مُتَنَوِّراً. 3. ""حَرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23810, 'تَنْوِيعٌ', 'تنويع', 'مصدر', 'نوع', 'تنويع', 'تنع', 'مص. نَوَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْوِيعٌ-تَنْوِيعٌ [ن و ع] (مص. نَوَّعَ). ""عَمِلَ عَلَى تَنْوِيعِ الأسْئِلَةِ"" : جَعْلِهَا مُتَنوِّعَةً مِنْ كُلِّ فَنٍّ وَعِلْمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23811, 'نَوَقٌ', 'نوق', 'مصدر', 'نوق', 'نوق', 'نق', 'مص. نَوِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"نَوَقٌ-نَوَقٌ [ن و ق] (مص. نَوِقَ). ""نَوَقُ الْجِلْدِ"" : أَيْ فِيهِ بَيَاضٌ وَحُمْرَةٌ خَفِيفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23812, 'تَنْوِيمٌ', 'تنويم', 'مصدر', 'نوم', 'تنويم', 'تنم', 'مص. نَوَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْوِيمٌ-تَنْوِيمٌ [ن و م] (مص. نَوَّمَ). ""نُوِّمَ تَنْوِيماً مِغْنَاطِيسيًّا"" : حَالَةٌ مِنَ الاسْتِغْرَاقِ فِي النَّوْمِ الاصْطِنَاعِيِّ لِجَعْلِ الْمُنَوَّمِ خَاضِعاً لِكُلِّ إيحَاءٍ وتَأْثِيرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23813, 'تَنْوِينٌ', 'تنوين', 'مصدر', 'نون', 'تنوين', 'تنن', 'مص. نَوَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْوِينٌ-تَنْوِينٌ [ن و ن] (مص. نَوَّنَ). 1. ""تَنْوِينُ النُّونِ"" : كِتَابَتُهَا. 2. ""تَنْوِينُ الاسْمِ الْمُعَرَّبِ"" : إلْحَاقُ نُونٍ سَاكِنَةٍ بِهِ وَهِيَ تُلْفَظُ وَلا تُكْتَبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23814, 'تَنْوِيهٌ', 'تنويه', 'مصدر', 'نوه', 'تنويه', 'تنه', 'مص. نَوَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْوِيهٌ-تَنْوِيهٌ [ن و هـ] (مص. نَوَّهَ). ""حَصَلَ عَلَى تَنْوِيهٍ"" : أي الإشَادَةِ بِالعَمَلِ وَتَقْدِيرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23815, 'نَوىً', 'نوى', 'مصدر', 'نوي', 'نوى', 'ن', 'مص. نَوَى', '', '', 'مفرد', 'Dy', '', 'Pf', '"أَنْوَاءٌ"', '', 'Rw', '', '', '', '', '', '', '"(مص. نَوَى). 1.""فَرَّقَ بَيْنَهُمَا النَّوَى"" : الْبُعْدُ. ""مَا أَصْعَبَ نَوَى الأَحْبَابِ"". 2.""تَمْرٌ بِلاَ نَوىً"" : بِلاَ عَجَمٍ، أَيْ بِلاَ نَوَيَاتٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23816, 'أَنْوَاءٌ', 'أنواء', 'مصدر', '', 'ءنواء', 'ن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23817, 'نِيَّةٌ', 'نية', 'مصدر', 'نوي', 'نية', 'نة', 'مص. نَوَى', '', '', 'مفرد', 'DnN', '', '', '"نِيَّاتٌ"', '', '', '', '', '', '', '', '', '"(مص. نَوَى) . 1. ""عَقَدَ النِّيَّةَ عَلَى الزَّوَاجِ"" : وَجَّهَ النَّفْسَ نَحْوَ... ""حُسْنُ النِّيَّةِ"" ""سَلاَمَةُ النِّيَّةِ"" ""سُوءُ النِّيَّةِ"" إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ (حديث). 2.""هُوَ نِيَّتِي"" : قَصْدِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23818, 'مُهَاجَمَةٌ', 'مهاجمة', 'مصدر', 'هجم', 'مهاجمة', 'مهجمة', 'مص. هَاجَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُهَاجَمَةٌ-مُهَاجَمَةٌ [هـ ج م] (مص. هَاجَمَ). ""قَرَّرُوا مُهَاجَمَةَ الأَعْدَاءِ فِي اللَّيْلِ"" : الانْدِفَاعُ إِلَيْهِمْ فَجْأَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23819, 'نِيَّاتٌ', 'نيات', 'مصدر', '', 'نيات', 'نت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23820, 'تَنْيِيحٌ', 'تنييح', 'مصدر', 'نيح', 'تنييح', 'تنح', 'مص. نَيَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْيِيحٌ-تَنْيِيحٌ [ن ي ح] (مص. نَيَّحَ). 1. ""يَرْغَبُ فِي تَنْيِيحِهِ"": فِي إرَاحَتِهِ. 2. ""يَرْجُو مِنَ اللَّهِ تَنْيِيحَهُ"" : جَعْلَ رُوحِهِ تَرْقُدُ فِي سَلامٍ أبَدِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23821, 'تَنْيِيرٌ', 'تنيير', 'مصدر', 'نير', 'تنيير', 'تنر', 'مص. نَيَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْيِيرٌ-تَنْيِيرٌ [ن ي ر] (مص. نَيَّرَ). ""تَنْيِيرُ الثَّوْبِ"" : أَيْ نَسْجُهُ عَلَى نِيرَيْنِ أَوْ وَضْعُ نِيرٍ، أَيْ طُورٍ أَوْ خُطُوطٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23822, 'تَنْيِيفٌ', 'تنييف', 'مصدر', 'نيف', 'تنييف', 'تنف', 'مص. نَيَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَنْيِيفٌ-تَنْيِيفٌ [ن ي ف] (مص. نَيَّفَ). ""تَنْيِيفُ عَدَدِ الْمَدْعُوِّينَ عَلَى الْمِائَةِ"" : زِيَادَةٌ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23823, 'هَيْئَةٌ', 'هيئة', 'مصدر', 'هيأ', 'هيءة', 'هة', 'مص. هَاءَ، هَيِءَ، هَيُؤَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"(مص. هَاءَ، هَيِءَ، هَيُؤَ). 1.""هَيْئَةُ الرَّجُلِ"" : شَكْلُهُ، صُورَتُهُ، حَالُهُ وَطَبِيعَتُهُ. المائدة آية 110وَإِذْ تَخْلُقُ مِنَ الطِّينِ كَهَيْئَةِ الطَّيْرِ بِإِذْنِي. (قرآن) ""هَيْئَةٌ حَزِينَةٌ"" ""هَيْئَةٌ جَمِيلَةٌ"". 2.""الْهَيْئَةُ"" : مُنَظَّمَةٌ أَوْ جَمَاعَةٌ مِنَ النَّاسِ لَهُمْ هَدَفٌ أَوْ عَمَلٌ مُعَيَّنٌ فِي مَجَالٍ مَّا: ""هَيْئَةُ التَّدْرِيسِ"". ""هَيْئَةُ التَّحْرِيرِ"". ""هَيْئَةُ الأُمَمِ الْمُتَّحِدَةِ"". ""هَيْئَةٌ سِيَاسِيَّةٌ"". ""الْهَيْئَةُ الاسْتِشَارِيَّةُ"". ""هَيْئَةُ الْمُوَظَّفِينَ"". ""هَيْئَةُ الْمَحْكَمَةِ"". 3.""عِلْمُ الْهَيْئَةِ"" : عِلْمٌ يُبْحَثُ فِيهِ عَنْ أَحْوَالِ الأَجْرَامِ السَّمَاوِيَّةِ، أَيْ عِلْمُ الْفَلَكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23824, 'مَهَابَةٌ', 'مهابة', 'مصدر', 'هيب', 'مهابة', 'مهبة', 'مص. هَابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَهَابَةٌ-مَهَابَةٌ [هـ ي ب] (مص. هَابَ). 1. ""مَهَابَةُ الأَعْـدَاءِ"" : مَخَافَتُهُمْ. 2.""يَكِنُّ لَهُ مَهَابَةً"" : تَعْظِيماً، تَقْدِيراً. ""يَمْتَلِئُ لَهَا قَلْبُهُ رَهْباً ورَغْباً ومَهَابَةً وإِجْلاَلاً"".(طـه حسين) ""رَجُلٌ ذُو مَهَابَةٍ"" ""صَاحِبُ الْجَلاَلَةِ وَالْمَهَابَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23825, 'هَيْبَةٌ', 'هيبة', 'مصدر', 'هيب', 'هيبة', 'هبة', 'مص. هَابَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هَيْبَةٌ-هَيْبَةٌ [هـ ي ب] (مص. هَابَ). 1.""هَيْبَةُ الرَّجُلِ"" : مَهَابَتُهُ. 2.""وَاجَهَ الأَمْرَ بِهَيْبَةٍ"" : بِمَخَافَةٍ. 3.""خَاطَبَ الْجُمْهُورَ بِهَيْبَةٍ"" : بِاحْتِرَامٍ وَإِجْلاَلٍ. ""كَلِمَاتٌ تَمْلأُ الْقَلْبَ رَوْعَةً وَهَيْبَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23826, 'مُهَاتَرَةٌ', 'مهاترة', 'مصدر', 'هتر', 'مهاترة', 'مهترة', 'مص. هَاتَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. هَاتَرَ). ""دَخَلَ الْمُتَنَازِعُونَ فِي مُهَاتَرَةٍ لاَ مَعْنَى لَهَا"" : فِي شَتَائِمَ وأَقْوَالٍ‏ يُنَاقِضُ بَعْضُهَا بَعْضاً، مُؤَاخَذَةٌ فِي اتِّهَامَاتٍ مُضَادَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23827, 'هَيْجٌ', 'هيج', 'مصدر', 'هيج', 'هيج', 'هج', 'مص. هَاجَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَيْجٌ-هَيْجٌ [هـ ي ج] (مص. هَاجَ). 1.""اِنْدَلَعَ الْهَيْجُ بَيْنَ القُوَّتَيْنِ"" : الْحَرْبُ. 2.""اِشْتَدَّ الْهَيْجُ"" : الْحَرْبُ الشَّدِيدَةُ. 3.""أَحْدَثَ هَيْجاً بَيْنَ النَّاسِ"" : فِتْنَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23828, 'مُهَاجَرَةٌ', 'مهاجرة', 'مصدر', 'هجر', 'مهاجرة', 'مهجرة', 'مص. هَاجَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُهَاجَرَةٌ-مُهَاجَرَةٌ [هـ ج ر] (مص. هَاجَرَ). ""دُفِعَ إلى الْمُهاجَرَةِ"" : الْخروجُ مِنْ بَلَدٍ إلى آخر. ""لَمْ يَكُنْ لِيُحِبَّ الْمُهَاجَرَةَ لَوْ كَانَ لَدَيْهِ مَا يَسُدُّ بِهِ الرَّمَقَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23829, 'أَهَالِيلُ', 'أهاليل', 'مصدر', '', 'ءهاليل', 'هلل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23830, 'هِيَاجٌ', 'هياج', 'مصدر', 'هيج', 'هياج', 'هج', 'مص. هَاجَ، هَايَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هِيَاجٌ-هِيَاجٌ [هـ ي ج] (مص. هَاجَ، هَايَجَ). ""كَانَ هِيَاجُهُ تَعْبِيراً عَنْ غَضَبِهِ"" : ثَوْرَتُهُ، فَوْرَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23831, 'مُهَادَنَةٌ', 'مهادنة', 'مصدر', 'هدن', 'مهادنة', 'مهدنة', 'مص. هَادَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُهَادَنَةٌ-مُهَادَنَةٌ [هـ د ن] (مص. هَادَنَ). ""اِتَّفَقُوا عَلَى الْمُهَادَنَةِ بَعْدَ حَرْبٍ طاحِنَةٍ "" : الْمُصَالَحَةُ، الْمُسالَمَةُ، وَقْفُ القِتَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23832, 'هَوْشٌ', 'هوش', 'مصدر', 'هوش', 'هوش', 'هش', 'مص. هَاشَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَوْشٌ-هَوْشٌ [هـ و ش] (مص. هَاشَ). 1.""دَخَلَ هَوْشٌ لاَ حَصْرَ لَهُ إِلَى سَاحَةِ الْمَعْرَكَةِ"" : عَدَدٌ كَثِيرٌ فِي حَرْبٍ. 2.""هَوْشُ البَطْنِ"" : خَلاَؤُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23833, 'هَيْضٌ', 'هيض', 'مصدر', 'هيض', 'هيض', 'هض', 'مص. هَاضَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَيْضٌ-هَيْضٌ [هـ ي ض] (مص. هَاضَ). 1.""عَظْمٌ هَيْضٌ"" : لَيِّنٌ. 2.""قَلْبٌ هَيْضٌ"" : بِهِ حُزْنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23834, 'هَيْفٌ', 'هيف', 'مصدر', 'هيف', 'هيف', 'هف', 'مص. هَافَ، هَيِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَيْفٌ-هَيْفٌ [هـ ي ف] (مص. هَافَ، هَيِفَ). ""أَصَابَ الْهَيْفُ كُلَّ الْحَيَوَانَاتِ"" : رِيحٌ حَارَّةٌ تَأْتِي عَلَى الْمَاءِ وَالنَّبَاتِ وَتَتْرُكُ الْحَيَوَانَاتِ فِي عَطَشٍ شَدِيدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23835, 'هَوْلٌ', 'هول', 'مصدر', 'هول', 'هول', 'هل', 'مص. هَالَ', '', '', 'مفرد', 'DnN', '', '', '"أَهْوَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. هَالَ). 1.""أَصَابَهُ هَوْلٌ شَدِيدٌ"" : الْفَزَعُ، الْخَوْفُ الشَّدِيدُ. ""كَانَ هَوْلُ الْفَاجِعَةِ عَنِيفاً يَمْلأُ قُلُوبَهُمْ رَوْعاً وَنُفُوسَهُمْ هَوْلاً"" ""مَنْ لَمْ يَرْتَكِبِ الأَهْوَالَ لَمْ يَنَلِ الآمَالَ"". 2.""أَبُو الْهَوْلِ"". ن. أَبُو الْهَوْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23836, 'أَهْوَالٌ', 'أهوال', 'مصدر', '', 'ءهوال', 'هل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23837, 'هِلاَلٌ', 'هلال', 'مصدر', 'هلل', 'هلال', 'هلل', 'مص. هَالَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَهِلَّةٌ:أَهَالِيلُ"', '', 'R', '', '', '', '', '', '', '"(مص. هَالَّ). 1.""هِلاَلُ الشَّهْرِ"" : غُرَّةُ الْقَمَرِ مِنْ أَوَّلِ الشَّهْرِ إِلَى سَبْعِ لَيَالٍ مِنْهُ. 2.""هِلاَلُ الْقَمَـرِ"": فِـي أَوَاخِرِ الشَّهْرِ مِنْ لَيْلَةِ السَّادِسِ وَالْعِشْرِينَ وَالسَّابِعِ وَالْعِشْرِينَ مِنْهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23838, 'أَهِلَّةٌ', 'أهلة', 'مصدر', '', 'ءهلة', 'هلة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23839, 'هَتٌّ', 'هت', 'مصدر', 'هتت', 'هت', 'هت', 'مص. هَتَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَتٌّ-هَتٌّ [هـ ت ت] (مص. هَتَّ). 1.""سَمِعَ هَتَّهُ"" : صَوْتَهُ. ""سَمِعْتُ هَتَّ أَقْدَامِهِمْ"". 2.""تَرَكَهُمْ هَتّاً هَتّاً"" : طَرَحَهُمْ أَرْضاً فِي حَالَةٍ يُرْثَى لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23840, 'هَيْلٌ', 'هيل', 'مصدر', 'هيل', 'هيل', 'هل', 'مص. هَالَ يَهِيلُ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَيْلٌ-هَيْلٌ [هـ ي ل] (مص. هَالَ يَهِيلُ). ""هَيْلُ التُّرَابِ أَوِ الرَّمْلِ"" : مَا انْصَبَّ وَانْهَالَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23841, 'هِيَامٌ', 'هيام', 'مصدر', 'هيم', 'هيام', 'هم', 'مص. هَامَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هُيَامٌ-هُيَامٌ [هـ ي م]. 1.""كَانَ هُيَامُهُ شَدِيداً بِهَا"" : الْجُنُونُ مِنْ فَرْطِ الْعِشْقِ وَالْحُبِّ. 2.""اِشْتَدَّ بِهِ الْهُيَامُ"" : أَشَدُّ الْعَطَشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23842, 'هَوْنٌ', 'هون', 'مصدر', 'هون', 'هون', 'هن', 'مص. هَانَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَوْنٌ-هَوْنٌ [هـ و ن] (مص. هَانَ). 1.""يُظْهِرُ الْهَوْنَ فِي مُعَامَلاَتِهِ"" : التَّوَاضُعَ، الرَّصَانَةَ وَالوَقَارَ. الفرقان آية 63وَعِبَادُ الرَّحْمَانِ الَّذِينَ يَمْشُونَ عَلَى الأَرْضِ هَوْناً.(قرآن). 2.""هُوَ فِي هَوْنٍ"": فِي سَكِينَةٍ. 3.""شَيْءٌ هَوْنٌ"" : حَقِيرٌ. 4.""عَلَى هَوْنِكَ"" : عَلَى رِسْلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23843, 'هُونٌ', 'هون', 'مصدر', 'هون', 'هون', 'هن', 'مص. هَانَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هُونٌ-هُونٌ [هـ و ن] (مص. هَانَ). 1.""هُوَ عَلَى هُونٍ"" : عَلَى خِزْيٍ وَذُلٍّ. النحل آية 59أَيُمْسِكُهُ عَلَى هُونٍ. (قرآن). 2.""لاَ أَدْرِي أَيُّ هُونٍ هُوَ"" : أَيُّ خَلْقٍ، أَيُّ نَاسٍ هُوَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23844, 'مُهَاوَدَةٌ', 'مهاودة', 'مصدر', 'هود', 'مهاودة', 'مهدة', 'مص. هَاوَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُهَاوَدَةٌ-مُهَاوَدَةٌ [هـ و د] (مص. هَاوَدَ). 1.""مُهَاوَدَةُ الصَّدِيقِ"" : مُوَادَعَتُهُ. 2.""مُهَاوَدَةُ الخَصْمِ"" : مُصَا‏لَحَتُهُ، عَدَمُ مُخَالَفَتِهِ. 3.""مُهَاوَدَةُ الرَّجُلِ"" : مُجَادَلَتُهُ. 4. ""مُهَاوَدَةُ الأَسْعَارِ"": أَخْذٌ وَرَدٌّ لِلتَّخْفِيضِ مِنْ سِعْرِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23845, 'هُبُوبٌ', 'هبوب', 'مصدر', 'هبب', 'هبوب', 'هبب', 'مص. هَبَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هُبُوبٌ-هُبُوبٌ [هـ ب ب] (مص. هَبَّ). 1.""هُبُوبُ الرِّيحِ"": هَيَجَانُهَا. 2.""هُبُوبُ نَسْمَةٍ مِنَ الْهَوَاءِ"" : اِنْسِيَابُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23846, 'هَبْرٌ', 'هبر', 'مصدر', 'هبر', 'هبر', 'هبر', 'مص. هَبَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَبْرٌ-هَبْرٌ [هـ ب ر] (مص. هَبَرَ). ""اِخْتَارَ هَبْراً جَيِّداً"" : أَيْ قِطْعَةً مِنَ اللَّحْمِ لاَ عَظْمَ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23847, 'هُبُوطٌ', 'هبوط', 'مصدر', 'هبط', 'هبوط', 'هبط', 'مص. هَبَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هُبُوطٌ-هُبُوطٌ [هـ ب ط] (مص. هَبَطَ). ""هُبوُطُ السُّلَّمِ"" : نُزُولُهُ. ""بِقَدْرِ الصُّعُودِ يَكُونُ الْهُبُوطُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23848, 'هِبَّةٌ', 'هبة', 'مصدر', 'هبب', 'هبة', 'هبة', 'مص. هَبَّ، يَهِبُّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هِبَّةٌ-هِبَّةٌ [هـ ب ب] (مص. هَبَّ، يَهِبُّ). 1.""هِبَّةُ السِّكِّينِ"" : مَضَاؤُهُ. 2.""إِنَّهُ لَحَسَنُ الْهِبَّةِ"" : حَسَنُ الْحَالِ. 3.""هِبَّةُ الدَّهْرِ"" : حِقْبَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23849, 'هُجُودٌ', 'هجود', 'مصدر', 'هجد', 'هجود', 'هجد', 'مص. هَجَدَ ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هُجُودٌ-هُجُودٌ [هـ ج د] (مص. هَجَدَ ). 1. ""هُجُودُ الرَّجُلِ"" : نَوْمُهُ بِاللَّيْلِ. 2. ""هُجُودُ السَّاهِرِ : سَهَرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23850, 'هَتْرٌ', 'هتر', 'مصدر', 'هتر', 'هتر', 'هتر', 'مص. هَتَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَتْرٌ-هَتْرٌ [هـ ت ر] (مص. هَتَرَ). ""هَتْرُ الرَّجُلِ"" : فُقْدَانُهُ لِعَقْلِهِ مِنْ كِبَرٍ أَوْ مَرَضٍ أَوْ حُزْنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23851, 'هُتَافٌ', 'هتاف', 'مصدر', 'هتف', 'هتاف', 'هتف', 'مص. هَتَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هُتَافٌ-هُتَافٌ [هـ ت ف] (مص. هَتَفَ). ""اُسْتُقْبِلَ بِهُتَافٍ حَارٍّ"" : أَيْ بِأَصْوَاتٍ مُرْتَفِعَةٍ عَالِيَةٍ بِالْمَدِيحِ وَالاحْتِفَاءِ. ""قُوبِلَ بِعَاصِفَةٍ مِنَ الْهُتَافِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23852, 'هَتْفٌ', 'هتف', 'مصدر', 'هتف', 'هتف', 'هتف', 'مص. هَتَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَتْفٌ-هَتْفٌ [هـ ت ف] (مص. هَتَفَ). ""تَعَالَى الْهَتْفُ فِي الْقَاعَةِ"" : الصِّيَاحُ وَمَدُّ الصَّوْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23853, 'تَهْتيكٌ', 'تهتيك', 'مصدر', 'هتك', 'تهتيك', 'تهتك', 'مص. هَتَّكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْتيكٌ-تَهْتيكٌ [هـ ت ك] (مص. هَتَّكَ). ""تَهْتِيكُ السَّيْر"" : هَتْكُهُ، خَرْقُهُ، قَطْعُهُ، تَمْزِيقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23854, 'هَتْكٌ', 'هتك', 'مصدر', 'هتك', 'هتك', 'هتك', 'مص. هَتَكَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَتْكٌ-هَتْكٌ [هـ ت ك] (مص. هَتَكَ). 1. ""هَتْكُ السِّتْرِ"" : قَطْعُهُ، خَرْقُهُ، تَمْزِيقُهُ. 2. ""هَتْكُ الثَّوْبِ"" : شَقُّهُ. 3. ""هَتْكُ الْعِرْضِ"" : اِغْتِصَابُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23855, 'هَجِيجٌ', 'هجيج', 'مصدر', 'هجج', 'هجيج', 'هجج', 'مص. هَجَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هَجِيجٌ-هَجِيجٌ [هـ ج ج] (مص. هَجَّ). ""هَجِيجُ النَّارِ"" : أَجِيجٌ، اِتِّقَادُهُا وَسَمَاعُ صَوْتِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23856, 'هِجَاءٌ', 'هجاء', 'مصدر', 'هجو', 'هجاء', 'هج', 'مص. هَجَا', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"هِجَاءٌ-هِجَاءٌ [هـ ج و] (مص. هَجَا). 1.""هِجَاءُ النَّاسِ"" : كَلاَمٌ فِيهِ سَبٌّ وَتَعْديدٌ لِلْمَعَايِبِ، وَيَكُونُ فِي الشِّعْرِ غَالِباً، وَهُوَ فَنٌّ مِنْ فُنُونِ الشِّعْرِ الْعَرَبِيِّ. ""إِيَّاكَ وَهِجَاءَ النَّاسِ"". 2.""هِجَاءُ الْكَلِمَةِ"" : تَقْطِيعُهَا وَتَعْدِيدُ حُرُوفِهَا مَعَ حَرَكَاتِهَا. 3.""حُرُوفُ الْهِجَاءِ"" : هِيَ الْحُرُوفُ الأَلِفْبَائِيَّةُ : أ، ب، ت، ث، ج، ح، خ، د، ذ، ر، ز، س، ش، ص، ض، ط، ظ، ع، غ، ف، ق، ك، ل، م، ن، هـ، و، ي. وَتُسَمَّى أَيْضاً حُرُوفُ التَّهَجِّي وَالتَّهْجِيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23857, 'هَجْوٌ', 'هجو', 'مصدر', 'هجو', 'هجو', 'هج', 'مص. هجا', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَجْوٌ-هَجْوٌ [هـ ج و] (مص. هجا). ""هَجْوُ الرَّجُلِ"" : تَعْدَادُ مَعَايِبِهِ، شَتْمُهُ. ""لاَ يَخْلُو كَلاَمُهُ مِنْ هَجْوٍ وَ لَغْوٍ وَلَمْزٍ وَ هَمْزٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23858, 'تَهْجِيدٌ', 'تهجيد', 'مصدر', 'هجد', 'تهجيد', 'تهجد', 'مص. هَجَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْجِيدٌ-تَهْجِيدٌ [هـ ج د] (مص. هَجَّدَ). 1.""تَهْجِيدُ الرَّجُلِ"": نَوْمُهُ بِالَّليْلِ. 2. ""تَهْجِيدُ الْمُتَعَبِّدِ"" : صَلاَتُهُ بِالليْلِ. 3.""تَهْجِيدُ النَّائِمِ"" : إيقَاظُهُ. 4. ""تَهْجِيدُ الصَّبِيِّ"" : تَنْوِيمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23859, 'هَجَأٌ', 'هجأ', 'مصدر', 'هجأ', 'هجء', 'هج', 'مص. هَجِئَ', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"هَجَأٌ-هَجَأٌ [هـ ج أ] (مص. هَجِئَ). ""وَلَّى هَجَأُ الشَّبَابِ"": كُلُّ مَا كَانَ فِيهِ الْمَرْءُ فَانْقَطَعَ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23860, 'تَهْجِيرٌ', 'تهجير', 'مصدر', 'هجر', 'تهجير', 'تهجر', 'مص. هَجَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْجِيرٌ-تَهْجِيرٌ [هـ ج ر] (مص. هَجَّرَ). 1.""التَّهْجِيرُ إلَى الصَّلاةِ"" : الْمُضِيُّ إلَيْهَا فِي أوَّلِ أوقَاتِهَا. لَوْ يَعْلَمِ النَّاسُ مَا فِي التَّهْجِيرِ لاَسْتَبَقُوا إلَيْهِ . (حديث). 2. ""أدَّى الفَيَضَانُ إلَى تَهْجِيرِ السُّكَّانِ"" : إلَى تَرْحِيلِهِمْ، إبْعَادِهِمْ. ""وَضَعَتِ الصَّهْيُونِيَّةُ مُنْذُ بِدَايَةِ القَرْنِ خُطَطاً لِتَهْجِيرِ الفِلَسْطِينِيِّينَ مِنْ فِلَسْطِينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23861, 'هَجْرٌ', 'هجر', 'مصدر', 'هجر', 'هجر', 'هجر', 'مص. هَجَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَجْرٌ-هَجْرٌ [هـ ج ر] (مص. هَجَرَ). ""هَجْرُ الأَحْبَابِ"" : تَرْكُهُمْ، الِابْتِعَادُ عَنْهُمْ بِجَفَاءٍ وَكَانَ يَلْزَمُ تَعَهُّدُهُمْ. هَجَرْتُكَ أَيَّاماً بِذِي الضَّمْرِ إِنَّنِي*عَلَى هَجْرِ أَيَّامٍ بِذِي الْقَمْرِ نَادِم (ابن الدمينة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23862, 'هَجْسٌ', 'هجس', 'مصدر', 'هجس', 'هجس', 'هجس', 'مص. هَجَسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَجْسٌ-هَجْسٌ [هـ ج س] (مص. هَجَسَ). 1.""سَمِعَ هَجْساً خَلْفَ الْبَابِ"" : صَوْتاً خَفِيّاً نَسْمَعُهُ وَلاَ نَفْهَمُهُ. 2.""اِسْتَبَدَّ بِهِ هَجْسٌ"" : كُلُّ مَا يَدُورُ فِي خَلَدِكَ مِنْ أَحَادِيثَ وَأَفْكَارٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23863, 'تَهْجِيمٌ', 'تهجيم', 'مصدر', 'هجم', 'تهجيم', 'تهجم', 'مص. هَجَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْجِيمٌ-تَهْجِيمٌ [هـ ج م] (مص. هَجَّمَ). ""تَهْجِيمُ الجَيْشِ"" : جَعْلُهُ يَهْجُمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23864, 'هُجُومٌ', 'هجوم', 'مصدر', 'هجم', 'هجوم', 'هجم', 'مص. هَجَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"هُجُومٌ-هُجُومٌ [هـ ج م] (مص. هَجَمَ). 1.""شَنُّوا هُجُوماً بِالْقَنَابِلِ لَيْلاً"" : الاِنْقِضَاضُ وَالدُّخُولُ فَجْأَةً دُونَ تَرَقُّبٍ عَلَى مَكَانٍ مَّا. ""هُجُومٌ جَوِّيٌّ بِالطَّائِرَاتِ"" ""هُجُومٌ بَحْرِيٌّ"" ""هُجُومٌ مُبَاغِتٌ"". 2.""أَحْكَمُوا خَطَّ الْهُجُومِ"" : خَطَّ الاِنْطِلاَقِ لِمُبَاغَتَةِ الْعَدُوِّ. 3. ""لاَعِبُو الْهُجُومِ فِي كُرَةِ الْقَدَمِ"" : اللاَّعِبُونَ الَّذِينَ يُنَظِّمُونَ كَيْفِيَّةَ التَّسَلُّلِ إِلَى شَبَكَةِ الْخَصْمِ. ""اِنْقَلَبَ مِنَ الدِّفَاعِ إِلَى الْهُجُومِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23865, 'تَهجِينٌ', 'تهجين', 'مصدر', 'هجن', 'تهجين', 'تهجن', 'مص. هَجَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهجِينٌ-تَهجِينٌ [هـ ج ن] (مص. هَجَّنَ). 1. ""تَهْجِينُ الرَّجُلِ"" : جَعْلُهُ هَجِيناً، أيْ لَئِيماً. 2. ""تَهْجِينُ العَمَلِ"" : تَقْبِيحُهُ، تَعْيِيبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23866, 'هُجْنَةٌ', 'هجنة', 'مصدر', 'هجن', 'هجنة', 'هجنة', 'مص. هَجُنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":هُجُنٌ"', '', 'R', '', '', '', '', '', '', '"(مص. هَجُنَ). 1.""هُجْنَةُ الْكَلاَمِ"" : قُبْحُهُ، عَيْبُهُ. 2.""فِي عِبَارَاتِهِ هُجْنَةٌ"" : اِخْتِلاَطُ تَعَابِيرِهِ بِكَلاَمٍ غَيْرِ فَصِيحٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23867, 'هُجُنٌ', 'هجن', 'مصدر', '', 'هجن', 'هجن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23868, 'تَهْجِيَةٌ', 'تهجية', 'مصدر', 'هجو', 'تهجية', 'تهجة', 'مص. هَجَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَهْجِيَةٌ-تَهْجِيَةٌ [هـ ج و] (مص. هَجَّى). 1. ""مَازَالَ فِي مَرْحَلَةِ تَهْجِيَةِ الحُرُوفِ"" : قِرَاءَةُ الكَلِمَةِ حَرْفاً حَرْفاً. 2.""حُرُوفُ التَّهْجِيَةِ"" : حُرُوفُ الهِجَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23869, 'تَهْدِيمٌ', 'تهديم', 'مصدر', 'هدم', 'تهديم', 'تهدم', 'مص. هَدَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْدِيمٌ-تَهْدِيمٌ [هـ د م] (مص. هَدَّمَ). ""تَهْدِيمُ البِنَاءِ"" : هَدْمُهُ، إسْقَاطُهُ، نَقْضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23870, 'هَدٌّ', 'هد', 'مصدر', 'هدد', 'هد', 'هد', 'مص. هَدَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَدٌّ-هَدٌّ [هـ د د] (مص. هَدَّ). 1.""رَجُلٌ هَدٌّ"" : كَرِيمُ الأَصْلِ. 2. ""وَجَدَهُ هَدّاً خَنُوعاً"" : جَبَاناً، ضَعِيفاً. 3.""صَوْتٌ هَدٌّ"" : غَلِيظٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23871, 'تَهْدِئَةٌ', 'تهدئة', 'مصدر', 'هدأ', 'تهدءة', 'تهدة', 'مص. هَدَّأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَهْدِئَةٌ-تَهْدِئَةٌ [هـ د أ] (مص. هَدَّأَ). ""حَاوَلَ تَهْدِئَةَ رَوْعِهِ"": تَسْكِينَ، رَوْعِهِ، تَخْفِيفَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23872, 'هُدُوءٌ', 'هدوء', 'مصدر', 'هدأ', 'هدوء', 'هد', 'مص. هَدَأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"هُدُوءٌ-هُدُوءٌ [هـ د أ] (مص. هَدَأَ). 1.""هُدُوءٌ مِنَ اللَّيْلِ"" : جُزْءٌ مِنْهُ. 2.""سَادَ الْهُدُوءُ فِي الْقَاعَةِ"" : السُّكُونُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23873, 'تَهْدِيدٌ', 'تهديد', 'مصدر', 'هدد', 'تهديد', 'تهدد', 'مص. هَدَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْدِيدٌ-تَهْدِيدٌ [هـ د د] (مص. هَدَّدَ). ""وَجَّهَ إلَيْهِ تَهْدِيداً"": إنْذَاراً، وَعِيداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23874, 'هَدَرٌ', 'هدر', 'مصدر', 'هدر', 'هدر', 'هدر', 'مص. هَدَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَدَرٌ-هَدَرٌ [هـ د ر] (مص. هَدَرَ). ن. هَدْرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23875, 'هَدَرٌ', 'هدر', 'مصدر', 'هدر', 'هدر', 'هدر', 'مص. هَدَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَدَرَ-هَدَرَ [هـ د ر] (ف ثلا. لازم). هَدَرَ، يَهْدِرُ، مص. هَدْرٌ، هَدِيرٌ . 1. ""هَدَرَ الْحَمَامُ"" : قَرْقَرَ، أَيْ كَرَّرَ صَوْتَهُ فِي حَنْجَرَتِهِ، هَدَلَ. 2. ""هَدَرَ الْبَعِيرُ"" : رَدَّدَ صَوْتَهُ فِي حَنْجَرَتِهِ. ""هَدَرَ الْأَسَدُ"". 3. ""هَدَرَ الرَّعْدُ"" : أَرْعَدَ. 4. ""هَدَرَ مُحَرِّكُ السَّيَّارَةِ"" : أَحْدَثَ صَوْتاً مُدَوِّياً. 5. ""هَدَرَ الصَّبِيُّ"" : أَرَاغَ الْكَلاَمَ وَهُوَ صَغِيرٌ. 6. ""هَدَرَ الشَّرَابُ"" : غَلاَ. 7. ""هَدَرَ الْجَوْفُ "" : اِنْتَفَخَ. 8. ""هَدَرَ الْعُشْبُ هَدِيراً وهُدُوراً"" : طَالَ وَعَظُمَ. 9.""هَدَرَ الحَائِطُ هُدُوراً"" : سَقَطَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23876, 'هَدْرٌ', 'هدر', 'مصدر', 'هدر', 'هدر', 'هدر', 'مص. هَدَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَدْرٌ-هَدْرٌ [هـ د ر] (مص. هَدَرَ). ""ذَهَبَ دَمُهُ هَدْراً"" : أَيْ بَاطِلاً. ""ذَهَبَ سَعْيُهُ هَدْراً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23877, 'هَدِيرٌ', 'هدير', 'مصدر', 'هدر', 'هدير', 'هدر', 'مص. هَدَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هَدِيرٌ-هَدِيرٌ [هـ د ر] (مص. هَدَرَ). 1.""هَدِيرُ الْحَمَامِ"" : تَرْدِيدُ صَوْتِهِ فِي حَنْجَرَتِهِ. 2.""هَدِيرُ الرَّعْدِ"" : دَوِيُّهُ. ""سَمِعْتُ مِنْ بَعِيدٍ هَدِيرَ سَيَّارَةٍ قَادِمَةٍ"". (جبرا إبراهيم جبرا)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23878, 'هَدِيلٌ', 'هديل', 'مصدر', 'هدل', 'هديل', 'هدل', 'مص. هَدَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هَدِيلٌ-هَدِيلٌ [هـ د ل] (مص. هَدَلَ). ""هَدِيلُ الْحَمَامِ"" : صَوْتُهُ. ""وَكَانَ تَسْبِيحاً هَدِيلُ حَمَامَة*فِي مَجْدِ رَبِّكَ أُلِّفَتْ سَجَعَاتُهَا (المعري)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23879, 'هَذْرٌ', 'هذر', 'مصدر', 'هذر', 'هذر', 'هذر', 'مص. هَذَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَذَرٌ-هَذَرٌ [هـ ذ ر] (مص. هَذَرَ). ن. هَذْرٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23880, 'هَدْمٌ', 'هدم', 'مصدر', 'هدم', 'هدم', 'هدم', 'مص. هَدَمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَدْمٌ-هَدْمٌ [هـ د م] (مص. هَدَمَ). ""هَدْمُ الْبُيُوتِ"" : تَحْطِيمُهَا، نَقْضُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23881, 'هَدْهَدَةٌ', 'هدهدة', 'مصدر', 'هدهد', 'هدهدة', 'هدهدة', 'مص. هَدْهَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هَدْهَدَةٌ-هَدْهَدَةٌ [هـ د هـ د] (مص. هَدْهَدَ). ""هَدْهَدَةُ الْحَمَامِ"" : هَدِيرُهُ.يَا دِجْلَةَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23882, 'هِدْيَةٌ', 'هدية', 'مصدر', 'هدي', 'هدية', 'هدة', 'مص. هَدَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"هُدْيَةٌ-هُدْيَةٌ [هـ ذ ي]. ن. هِدْيَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23883, 'هَدْيٌ', 'هدي', 'مصدر', 'هدي', 'هدي', 'هد', 'مص. هَدَى', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"هَدْيٌ-هَدْيٌ [هـ د ي] (مص. هَدَى). 1.""قَدَّمَ الْهَدْيَ إِلَى الْبَيْتِ الْحَرَامِِ"" : مَا يُهْدَى مِنَ الذَّبَائ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23884, 'هُدىً', 'هدى', 'مصدر', 'هدي', 'هدى', 'هد', 'مص. هَدَى', '', '', 'مفرد', 'Dy', '', 'Pf', '""', '', 'Rw', '', '', '', '', '', '', '"هُدىً-هُدىً [هـ د ي] (مص. هَدَى). 1.""يَسِيرُ عَلَى هُدَى اللَّهِ"" : عَلَى رَشَادِهِ. ""وَجَدَ قَوْماً عَلَى غَيْرِ هُدىً"" """', '');
