INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23930, 'هَلَعٌ', 'هلع', 'مصدر', 'هلع', 'هلع', 'هلع', 'مص. هَلَعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَلَعٌ-هَلَعٌ [هـ ل ع] (مص. هَلَعَ). ""أَصَابَهُ الْهَلَعُ"" : الْجَزَعُ وَالْخَوْفُ الشَّدِيدُ.وَسِرْتُ عُمْرِي إِلَى قَبْرِي عَلَى مَهَل*وَقَدْ دَنَوْتُ فَحُقَّ الْخَوْفُ وَالْهَلَع (المعري)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23931, 'تَهْلُكَةٌ', 'تهلكة', 'مصدر', 'هلك', 'تهلكة', 'تهلكة', 'مص. هَلَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْلُكَةٌ-تَهْلُكَةٌ [هـ ل ك] (مص. هَلَكَ). ""لاَ تُلْقِي بِنَفْسِكَ إلَى التَّهْلُكَةِ"" : إلَى الهَلاَكِ، كُلُّ شَيْءٍ تَكُونُ عَاقِبَتُهُ مَحْفُوفَةً بِالخَطَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23932, 'هَلاَكٌ', 'هلاك', 'مصدر', 'هلك', 'هلاك', 'هلك', 'مص. هَلَكَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هَلاَكٌ-هَلاَكٌ [هـ ل ك] (مص. هَلَكَ). ""صَارَ إِلَى هَلاَكٍ مُحَقَّقٍ"" : الْمَوْتُ. ""إِنَّ الْغَفْلَةَ تُؤَدِّي إِلَى الْهَلاَكِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23933, 'تَهْلِيلٌ', 'تهليل', 'مصدر', 'هلل', 'تهليل', 'تهلل', 'مص. هَلَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْلِيلٌ-تَهْلِيلٌ [هـ ل ل] (مص. هَلَّلَ). ""اُسْتُقْبِلَ بِتَهْلِيلٍ وتَرْحَابٍ"" : بِتَصْفِيقٍ وَهُتَافٍ. ""اِنْتَهى الحَفْلُ بِعَاصِفَةٍ مِنَ التَّهْلِيلِ وَالتَّصْفِيقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23934, 'هَميِمٌ', 'هميم', 'مصدر', 'همم', 'هميم', 'همم', 'مص. هَمَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '":هَمَائِمُ"', '', 'R', '', '', '', '', '', '', '"(مص. هَمَّ). 1.""مَشَى هَمِيماً"" : دَبِيباً، أَيْ رُوَيْداً رُوَيْداً. 2.""قَطَرَ الْهَمِيمُ"" : الْمَطَرُ الضَّعِيفُ. ""رَأَى الفَلاَّحَ فِي الْهَمِيمَةِ بُشْرَى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23935, 'هَميِمَةٌ', 'هميمة', 'مصدر', 'همم', 'هميمة', 'هممة', 'مص. هَمَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '":هَمَائِمُ"', '', 'R', '', '', '', '', '', '', '"(مص. هَمَّ). 1.""مَشَى هَمِيماً"" : دَبِيباً، أَيْ رُوَيْداً رُوَيْداً. 2.""قَطَرَ الْهَمِيمُ"" : الْمَطَرُ الضَّعِيفُ. ""رَأَى الفَلاَّحَ فِي الْهَمِيمَةِ بُشْرَى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23936, 'هَمَائِمُ', 'همائم', 'مصدر', '', 'هماءم', 'همم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23937, 'هَمَجٌ', 'همج', 'مصدر', 'همج', 'همج', 'همج', 'مص هَمَجَ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"هَمَجٌ-هَمَجٌ [هـ م ج] (مص هَمَجَ). 1. : ذُبَابٌ صَغِيرٌ كَالْبَعُوضِ يَقَعُ عَلَى وُجُوهِ الْغَنَمِ وَالْحَمِير. 2.""هُوَ مِنَ الْهَمَجِ"" : الرُّعَاع مِنَ النَّاسِ، الْحَمْقَى لاَ نِظَامَ لَهُمْ. 3.""اِشْتَدَّ بِهِ الْهَمَجُ"" : الْجُوعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23938, 'هَمْزٌ', 'همز', 'مصدر', 'همز', 'همز', 'همز', 'مص. هَمَزَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَمْزٌ-هَمْزٌ [هـ م ز] (مص. هَمَزَ). 1.""هَمْزُ الْحَرْفِ"" : النُّطْقُ بِهِ مَهْمُوزاً. 2.""الْهَمْزُ وَاللَّمْزُ"" : الطَّعْنُ فِي أَعْرَاضِ النَّاسِ. 3.""هَمْزُ الشَّيْطَانِ"" : الْجُنُونُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23939, 'تَهْميشٌ', 'تهميش', 'مصدر', 'همش', 'تهميش', 'تهمش', 'مص. هَمَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْميشٌ-تَهْميشٌ [هـ م ش] (مص. هَمَّشَ). 1. ""كَتَبَ تَهْمِيشاً عَلَى حَاشِيَةِ الكِتَابِ"" : مَا يُدوَّنُ مِنْ تَعَالِيقَ وَبَيَانَاتٍ عَلَى الهَامِشِ. 2. ""حَاولَ تَهْمِيشَهُ"" : جَعْلَهُ عَلَى الهَامِشِ، أيْ عَدَمَ إعْطَائِهِ أهَمِّيَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23940, 'مَهَمَّةٌ', 'مهمة', 'مصدر', 'همم', 'مهمة', 'مهمة', 'مص. هَمَّ، يَهُمُّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَهَمَّةٌ-مَهَمَّةٌ [هـ م م] (مص. هَمَّ، يَهُمُّ). ""لا مَهَمَّةَ لِي بِذلِكَ"" : أَي لا أَهُمُّ بِهِ، أي لا أَحْزَنُ ولا أَقْلَقُ لِذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23941, 'تَهْنِئَةٌ', 'تهنئة', 'مصدر', 'هنأ', 'تهنءة', 'تهنة', 'مص. هَنَّأ', '', '', 'مفرد', 'DnN', '', '', '"تَهْنِئَاتٌ"', '', 'Rz', '', '', '', '', '', '', '"(مص. هَنَّأ). ""قَدَّمَ لَهُ تَهْنِئَةً بِمُنَاسَبَةِ العِيدِ"" : خَاطَبَهُ بِأَنْ يَكُونَ العِيدُ مَبْعَثَ سُرُورٍ لَهُ. ""إنَّمَا التَّهْنِئَـاتُ لِلأَكْفَـاءِ*وَلِمَـنْ يُدْنِي مِنَ البُعَـدَاءِ"" (المتَنبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23942, 'تَهْنِئَاتٌ', 'تهنئات', 'مصدر', '', 'تهنءات', 'تهنت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23943, 'هَنْدَسَةٌ', 'هندسة', 'مصدر', 'هندس', 'هندسة', 'هندسة', 'مص. هَنْدَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"هَنْدَسَةٌ-هَنْدَسَةٌ [هـ ن د س] (مص. هَنْدَسَ). 1.""الْهَنْدَسَةُ الرِّيَاِضِيَّةُ"" : عِلْمٌ يَبْحَثُ فِي الْخُطُوطِ وَالْأَبْعَادِ وَالسُّطُوحِ وَالزَّوايَا وَالكَمِّيَّاتِ، مِنْ حَيْثُ خَوَاصُّهَا وَقِيَاسُهَا. 2.""الْهَنْدَسَةُ النَّظَرِيَّةُ"" : الْمَبَادِئُ وَالأُصُولُ الْعِلْمِيَّةُ الْمُتَعَلِّقَةُ بِخَوَاصِّ الْمَادَّةِ وَمَصَادِرِ القُوَى الطَّبِيعِيَّةِ وَطُرُقِ اسْتِخْدَامِهَا لِتَحْقِيقِ أَغْرَاضٍ مَادِّيَّةٍ. 3. ""الْهَنْدَسَةُ التَّطْبِيقِيَّةُ أَوِ الْعَمَلِيَّةُ"" : فَنُّ الْإِفَادَةِ مِنَ الْمَبَادِئِ وَالأُصُولِ الْعِلْمِيَّةِ فِي بِنَاءِ الْأَشْيَاءِ وَتَنْظِيمِهَا وَتَقْوِيمِهَا. وَهِيَ أَنْوَاعٌ: ""الْهَنْدَسَةُ الْمِيكَانِيكِيَّةُ""، "" الْهَنْدَسَةُ الْكِيمَاوِيَّةُ""، ""الْهَنْدَسَةُ الْمِعْمَارِيَّةُ""، ""هَنْدَسَةُ الطُّرُقِ وَالْجُسُورِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23944, 'هَنَاءٌ', 'هناء', 'مصدر', 'هنأ', 'هناء', 'هن', 'مص. هَنِئَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"هَنَاءٌ-هَنَاءٌ [هـ ن أ] (مص. هَنِئَ). ""يَعِيشُ فِي هَنَاءٍ"" : فِي فَرَحٍ وَسُرُورٍ. ""لَكَ الْهَنَاءُ مَا دُمْتَ حَيّاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23945, 'هَوَجٌ', 'هوج', 'مصدر', 'هوج', 'هوج', 'هج', 'مص. هَوِجَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَوَجٌ-هَوَجٌ [هـ و ج] (مص. هَوِجَ). ""بِهِ هَوَجٌ"" : حُمْقٌ طَالَ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23946, 'تَهْوِيدٌ', 'تهويد', 'مصدر', 'هود', 'تهويد', 'تهد', 'مص. هَوَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْوِيدٌ-تَهْوِيدٌ [هـ و د] (مص. هَوَّدَ). 1. ""سَارَ تَهْويداً"" : سَارَ سَيْراً رُويْداً بَطِيئاً. 2. ""تَهْويدُ الحَادِي"" : تَرْجيعُهُ فِي الغِنَاءِ. 3. ""تَهْوِيدُ السَّاهِرينَ"" : إِطْرابُهُمْ. 4. ""تَهوِيدُ الوَلدِ"" : جَعْلُهُ عَلَى مِلَّةِ اليهُودِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23947, 'تَهْوِيرٌ', 'تهوير', 'مصدر', 'هور', 'تهوير', 'تهر', 'مص. هَوَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْوِيرٌ-تَهْوِيرٌ [هـ و ر] (مص. هَوَّرَ). 1. ""تَهْوِيرُ البِنَاءِ"": هَدْمُهُ. 2.""تَهْوِيرُ الْخَصْمِ"": صَرْعُهُ. 3.""تَهْوِيرُ السَّيَّارَةِ"": إِيقَاعُهَا فِي هُوَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23948, 'تَهْوِيسٌ', 'تهويس', 'مصدر', 'هوس', 'تهويس', 'تهس', 'مص. هَوَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْوِيسٌ-تَهْوِيسٌ [هـ و س] (مص. هَوَّسَ). 1. ""تَهْوِيسُ رَجُلٍ"": جَعْلُهُ ذَا هَوَسٍ. 2. ""تَهْوِيسُ الحِمَّصِ"" : دَقُّهُ دَقّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23949, 'هَوَسٌ', 'هوس', 'مصدر', 'هوس', 'هوس', 'هس', 'مص. هَوِسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"هَوَسٌ-هَوَسٌ [هـ و س] (مص. هَوِسَ). ""رَجُلٌ بِهِ هَوَسٌ"" : جُنُونٌ، خِفَّةُ عَقْلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23950, 'تَهْويشٌ', 'تهويش', 'مصدر', 'هوش', 'تهويش', 'تهش', 'مص. هَوَّشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْويشٌ-تَهْويشٌ [هـ و ش] (مص. هَوَّشَ). 1. ""تَهْوِيشُ النَّاسِ"" : الإفْسادُ بَيْنَهُمْ، زَرْعُ الفِتْنَةِ بَيْنَهُمْ. 2.""تَهْوِيشُ مَوَادَّ مُخْتَلِفَةٍ"" : خَلْطُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23951, 'تَهْويلٌ', 'تهويل', 'مصدر', 'هول', 'تهويل', 'تهل', 'مص. هَوَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَهَاوِيلُ"', '', 'R', '', '', '', '', '', '', '"(مص. هَوَّلَ). ""لَمْ يَكُنْ يُرِيدُ بِكَلامِهِ إلاَّ تَهْوِيلَ الأُمُورِ"" : تَضْخِيمَ الأُمُورِ، مَا يَبْعَثُ عَلَى التَّخْوِيفِ وَالتَّهْدِيدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23952, 'تَهَاوِيلُ', 'تهاويل', 'مصدر', '', 'تهاويل', 'تهل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23953, 'تَهْوِيمٌ', 'تهويم', 'مصدر', 'هوم', 'تهويم', 'تهم', 'مص. هَوَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْوِيمٌ-تَهْوِيمٌ [هـ و م] (مص. هَوَّمَ). 1. ""تَهْوِيمُ الرَّجُلِ"" : نَوْمُهُ نَوْمَاً خَفِيفاً. 2. ""تَهْوِيمُ النَّائِمِ"" : هَزُّ رَأسِهِ مِنَ النُّعَاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23954, 'تَهْوِينٌ', 'تهوين', 'مصدر', 'هون', 'تهوين', 'تهن', 'مص. هَوَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْوِينٌ-تَهْوِينٌ[هـ و ن] (مص. هَوَّنَ). ""تَهْوينُ الأمْرِ"" : تَخْفِيفُهُ، تَسْهيلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23955, 'هُوَّةٌ', 'هوة', 'مصدر', 'هوي', 'هوة', 'هة', 'مص. هَوَى', '', '', 'مفرد', 'DnN', '', '', '"هُوىً:هُوِيٌّ"', '', 'R', '', '', '', '', '', '', '"(مص. هَوَى). ""سَقَطَ فِي هُوَّةٍ سَحِيقَةٍ"" : فِي حُفْرَةٍ بَعِيدَةِ الْقَعْرِ، الغَوْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23956, 'هُوىً', 'هوى', 'مصدر', '', 'هوى', 'ه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23957, 'هُوِيٌّ', 'هوي', 'مصدر', '', 'هوي', 'ه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23958, 'تَهْييءٌ', 'تهييء', 'مصدر', 'هيأ', 'تهييء', 'ته', 'مص. هَيَّأَ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَهْييءٌ-تَهْييءٌ [هـ ي أ] (مص. هَيَّأَ). ""تَهْيِيءُ الدَّرْسِ"" : تَحْضِيرُهُ، إعْدَادُهُ. ""تَهْيِيءُ الطَّعامِ"" ""تَهْيِيءُ الْمَشْرُوعِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23959, 'تَهْيِيجٌ', 'تهييج', 'مصدر', 'هيج', 'تهييج', 'تهج', 'مص. هَيَّجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْيِيجٌ-تَهْيِيجٌ [هـ ي ج] (مص. هَيَّجَ). ""لَمْ يَكُنْ مِنَ الضَّرُوري تَهْيِيجُهُ وإثَارَةُ غَضَبِهِ"" : أيْ تَحْرِيكُ غَضَبِهِ وَهَيَجَانِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23960, 'هَيْكَلَةٌ', 'هيكلة', 'مصدر', 'هكل', 'هيكلة', 'هكلة', 'مص. هَيْكَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هَيْكَلَةٌ-هَيْكَلَةٌ [هـ ك ل] (مص. هَيْكَلَ). 1.""اِمْرَأَةٌ هَيْكَلَةٌ"" : عَظِيمَةٌ. 2.""نَبَاتٌ هَيْكَلَةٌ"" : أَي اسْتَقَامَ نُمُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23961, 'تَهْيِيمٌ', 'تهييم', 'مصدر', 'هيم', 'تهييم', 'تهم', 'مص. هَيَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَهْيِيمٌ-تَهْيِيمٌ [هـ ي م] (مص. هَيَّمَ).""تَهْيِيمُ الرَّجُلِ"" : جَعْلُهُ ذَا هُيَامٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23962, 'هَيْمَنَةٌ', 'هيمنة', 'مصدر', 'هيمن', 'هيمنة', 'همنة', 'مص. هَيْمَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"هَيْمَنَةٌ-هَيْمَنَةٌ [هـ ي م ن] (مص. هَيْمَنَ). ""أَحْكَمَ هَيْمَنَتَهُ عَلَى الْبِلاَدِ"" : سَيْطَرَتَهُ، سَطْوَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23963, 'مُوَاجَهَةٌ', 'مواجهة', 'مصدر', 'وجه', 'مواجهة', 'مجهة', 'مص. وَاجَهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَاجَهَةٌ-مُوَاجَهَةٌ [و ج هـ] (مص. وَاجَهَ). 1.""يَنْبَغِي مُوَاجَهَةُ الْحَقِيقَةِ"" : مُجَابَهَتُهَا وَجْهاً لِوَجْهٍ. 2.""مُوَاجَهَةُ الأَعْدَاءِ"" : مُقَاوَمَتُهُمْ. 3.""دُوَلُ الْمُوَاجَهَةِ"" : أَيِ الدُّوَلُ الْمُجَابِهَةُ لِعَدُوٍّ وَاحِدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23964, 'وَأْدٌ', 'وأد', 'مصدر', 'وأد', 'وءد', 'د', 'مص. وَأَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَأْدٌ-وَأْدٌ [و أ د] (مص. وَأَدَ). 1.""بِمَجِيءِ الإِسْلاَمِ اِنْتَهَى عَهْدُ وَأْدِ البَنَاتِ"" : دَفْنُهُنَّ حَيَّاتٍ. 2.""وَأْدُ التَّعْبِيرِ"" : كَبْتُهُ وَخَنْقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23965, 'مُوَارَبَةٌ', 'مواربة', 'مصدر', 'ورب', 'مواربة', 'مربة', 'مص. وَارَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَارَبَةٌ-مُوَارَبَةٌ [و ر ب] (مص. وَارَبَ). 1.""تَكَلَّمَ دُونَ مُوَارَبَةٍ"" : دُونَ مُخَادَعَةٍ، أَيْ بِصَرَاحَةٍ وَوُضُوحٍ. ""مَالَكِ تَلْتَجِئِينَ لِلْمُوَارَبَةِ وَالرِّيَاءِ وَالنِّفَاقِ"". (إسحق الحسيني). 2.""أَبْوَابٌ مُوَارَبَةٌ"" : مَفْتُوحَةٌ قَلِيلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23966, 'مُوَازَنَةٌ', 'موازنة', 'مصدر', 'وزن', 'موازنة', 'مزنة', 'مص. وَازَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. وَازَنَ). 1.""مُوَازَنَةٌ بَيْنَ الرِّبْحِ وَالْخَسَارَةِ"" : الْمُسَاوَاةُ بَيْنَهُمَا. 2.""مُوَازَنَةُ الْمُؤَسَّسَـةِ"" : مِيزَانِيَّتُهَا. 3.""الْمُوَازَنَةُ فِي الْبَدِيعِ"" : تَوَازُنُ الْفَاصِلَتَيْنِ، تَسَاوِيهِما فِي الكَلاَمِ وَزْناً لاَ قَافِيَةً: ""عَمَلٌ صَالِحٌ وَأَجْرٌ كَبِيرٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23967, 'مُوَازَاةٌ', 'موازاة', 'مصدر', 'وزي', 'موازاة', 'مزة', 'مص. وَازَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَازَاةٌ-مُوَازَاةٌ [و ز ي] (مص. وَازَى). 1.""جَاءَ عَمَلُهُ مُوَازَاةً لِعَمَلِ أَقْرَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23968, 'مُوَاسَاةٌ', 'مواساة', 'مصدر', 'أسي', 'مواساة', 'مسة', 'مص. وَاسَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَاسَاةٌ-مُوَاسَاةٌ [أ س ي] (مص. وَاسَى). ""جَاءَ لِمُوَاسَاتِهِ"" : جَاءَ لِتَعْزِيَتِهِ وَالتَّخْفِيفِ مِنْ حُزْنِهِ وَمُصَابِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23969, 'مُوَاصَلَةٌ', 'مواصلة', 'مصدر', 'وصل', 'مواصلة', 'مصلة', 'مص. وَاصَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَاصَلَةٌ-مُوَاصَلَةٌ [و ص ل] (مص. وَاصَلَ). ""مُوَاصَلَةُ الْعَمَلِ"": مُتَابَعَتُهُ وَالْمُدَاوَمَةُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23970, 'وِصَالٌ', 'وصال', 'مصدر', 'وصل', 'وصال', 'صل', 'مص. وَاصَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وِصَالٌ-وِصَالٌ [و ص ل] (مص. وَاصَلَ). ""وِصَالُ الأَحِبَّةِ"" : الِاجْتِمَاعُ وَمُبَادَلَةُ الْحُبِّ فِيمَا بَيْنَهُمْ. ""بَكَى عَهْدَ الوِصَالِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23971, 'مُوَاطَنَةٌ', 'مواطنة', 'مصدر', 'وطن', 'مواطنة', 'مطنة', 'مص. وَاطَنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَاطَنَةٌ-مُوَاطَنَةٌ [و ط ن] (مص. وَاطَنَ). ""كُلُّ مُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23972, 'مُوَاظَبَةٌ', 'مواظبة', 'مصدر', 'وظب', 'مواظبة', 'مظبة', 'مص. وَاظَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَاظَبَةٌ-مُوَاظَبَةٌ [و ظ ب] (مص. وَاظَبَ). ""الْمُوَاظَبَةُ عَلَى العَمَلِ"" : المدُاَوَمَةُ، الْمُوَاكَبَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23973, 'مُوَافَقَةٌ', 'موافقة', 'مصدر', 'وفق', 'موافقة', 'مفقة', 'مص. وَافَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَافَقَةٌ-مُوَافَقَةٌ [و ف ق] (مص. وَافَقَ). 1.""تَمَّتِ الْمُوَافَقَةُ عَلَى القَر"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23974, 'مُوَاكَبَةٌ', 'مواكبة', 'مصدر', 'وكب', 'مواكبة', 'مكبة', 'مص. وَاكَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُوَاكَبَةٌ-مُوَاكَبَةٌ [و ك ب] (مص. وَاكَبَ). 1.""مُوَاكَبَةُ العَمَـلِ"" : الْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23975, 'وَأْلٌ', 'وأل', 'مصدر', 'وأل', 'وءل', 'ل', 'مص. وَأَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَأْلٌ-وَأْلٌ [و أ ل] (مص. وَأَلَ). ""وَجَدَ وَأْلاً"" : مَلْجَأً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23976, 'تَوْبِيخٌ', 'توبيخ', 'مصدر', 'وبخ', 'توبيخ', 'تبخ', 'مص. وَبَّخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. وَبَّخَ). ""تَلَقَّى تَوْبِيخاً مِنَ الْمَجْلِسِ التَّأدِيبِيِّ"" : أيْ لَوْماً، تَأنِيباً، تَعْيِيراً. ""قَسَاوَةُ التَّوْبِيخِ وَأوْجَاعُ الجَلْدِ بِالسِّيَاطِ وَظُلْمَةُ السِّجْنِ"". (جبران خ. جبران)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23977, 'وَبَدٌ', 'وبد', 'مصدر', 'وبد', 'وبد', 'بد', 'مص. وَبِدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَبَدٌ-وَبَدٌ [و ب د] (مص. وَبِدَ). 1.""وَجَدَ السُّكَّانَ فِي وَبَدٍ"" : فِي سُوءِ حَالٍ وَشِدَّةِ عَيْشٍ. 2.""يَوْمٌ وَبَدٌ"" : شَدِيدُ الْحَرِّ. 3.""بِهِ وَبَدٌ"" : عَيْبٌ. 4.""رَجُلٌ وَبَدٌ"" : سَيِّءُ الْحَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23978, 'وَبَشٌ', 'وبش', 'مصدر', 'وبش', 'وبش', 'بش', 'مص. وَبِشَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْبَاشٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَبِشَ). 1.""أَصَابَ الوَبَشُ جِلْدَ البَعِيرِ"" : رَقَطٌ مِنَ الجَرَبِ يَتَفَشَّى فِي جِلْدِ البَعِيرِ. 2.""وَبَشُ الظُّفْرِ"" : نِمْنِمٌ أَبْيَضُ يَكُونُ عَلَى الظُّفْرِ. 3. ""هُوَ مُجَرَّدُ وَبَشٍ مِنَ الأَوْبَاشِ"" : هُوَ مِنْ سَفَالَةِ النَّاسِ وَأَرَاذِلِهِمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23979, 'أَوْبَاشٌ', 'أوباش', 'مصدر', '', 'ءوباش', 'بش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23980, 'وَبْلٌ', 'وبل', 'مصدر', 'وبل', 'وبل', 'بل', 'مص. وَبَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَبْلٌ-وَبْلٌ [و ب ل] (مص. وَبَلَ). ""اِشْتَدَّ الوَبْلُ"" : الْمَطَرُ الشَّدِيدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23981, 'وَبَالٌ', 'وبال', 'مصدر', 'وبل', 'وبال', 'بل', 'مص. وَبُلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَبَالٌ-وَبَالٌ [و ب ل] (مص. وَبُلَ). ""لَهُ الوَبَالُ إِنْ هُوَ لَمْ يَتَّعِظْ"" : سُوءُ العَاقِبَةِ .الطلاق آية 9 فَذَاقَتْ وَبَالَ أَمْرِهَا ( قرآن) ""يَضُرُّ بِنَفْسِهِ وَيَجُرُّ عَلَيْهَا الوَبَالَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23982, 'وَبَاءٌ', 'وباء', 'مصدر', 'وبأ', 'وباء', 'ب', 'مص. وَبُؤَ', '', '', 'مفرد', 'Dz', '', 'Pf', '":أَوْبِئَةٌ"', '', 'Rz', '', '', '', '', '', '', '"(مص. وَبُؤَ). ""اِنْتَشَرَ وَبَاءٌ وَخِيمٌ"" : كُلُّ مَرَضٍ عَامٍّ، كَالْجُدَرِي، والطَّاعُون."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23983, 'أَوْبِئَةٌ', 'أوبئة', 'مصدر', '', 'ءوبءة', 'بة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23984, 'تَوْتِيدٌ', 'توتيد', 'مصدر', 'وتد', 'توتيد', 'تتد', 'مص. وَتَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْتِيدٌ-تَوْتِيدٌ [و ت د] (مص. وَتَّدَ). 1. ""تَوْتِيدُ الوَتَدِ"" : تَثْبِيتُهُ. 2. ""تَوْتِيدُ الرَّجُلِ فِي الخَيْمَةِ"" : إقَامَتُهُ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23985, 'تَوْتِيرٌ', 'توتير', 'مصدر', 'وتر', 'توتير', 'تتر', 'مص. وَتَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْتِيرٌ-تَوْتِيرٌ [و ت ر] (مص. وَتَّرَ). 1. ""تَوْتِيرُ القَوْسِ"" : شَدُّهُ. 2. ""تَوْتِيرُ الصَّلاةِ"" : جَعْلُهَا وِتْراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23986, 'وَتْرٌ', 'وتر', 'مصدر', 'وتر', 'وتر', 'تر', 'مص. وَتَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَتْرٌ-وَتْرٌ، وِتْرٌ [و ت ر] (مص. وَتَرَ). 1.""عَدَدٌ وَتْرٌ"" : فَرْدٌ. ""خَرَجَ وَتْراً"" 2.الفجر آية 1 ، 2 ، 3 وَالفَجْرِ، وَلَيَالٍ عَشْرٍ، وَالشَّفْعِ وَالوَتْر ( قرآن) : الشَّفْعُ: الزَّوْجَانِ، وَالوَتْرُ: الْمُفْرَدُ. 3.""الوَتْرُ"": مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى، أَيْ هُوَ اللَّهُ الفَرْدُ جَلَّ جَلاَلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23987, 'وَتِينٌ', 'وتين', 'مصدر', 'وتن', 'وتين', 'تن', 'مص. وَتَنَ', '', '', 'مفرد', 'DnN', '', '', '"وُتْنٌ:أَوْتِنَةٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَتَنَ). ""وَتِينُ القَلْبِ"" : أَيِ الشَّرْيَانُ الْحَيَوِيُّ النَّابِضُ مِنَ القَلْبِ، بِوَاسِطَتِهِ تَتِمُّ تَغْذِيَةُ الجِسْمِ بِالدَّمِ، وَمِنْهُ تَسْتَمِدُّ العُرُوقُ قُوَّتَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23988, 'وُتْنٌ', 'وتن', 'مصدر', '', 'وتن', 'تن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23989, 'أَوْتِنَةٌ', 'أوتنة', 'مصدر', '', 'ءوتنة', 'تنة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23990, 'وِثَابٌ', 'وثاب', 'مصدر', 'وثب', 'وثاب', 'ثب', 'مص. وَثَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَثَّابٌ-وَثَّابٌ [و ث ب] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ وَثَّابٌ"" : كَثِيرُ الوَثْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23991, 'وَثْبٌ', 'وثب', 'مصدر', 'وثب', 'وثب', 'ثب', 'مص. وَثَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَثْبٌ-وَثْبٌ [و ث ب] (مص. وَثَبَ). 1.""وَثَبَ وَثْباً"" : قَفَزَ قَفْزاً. 2.""رِيَاضَةُ الوَثْبِ"" : القَفْزُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23992, 'وُثُوبٌ', 'وثوب', 'مصدر', 'وثب', 'وثوب', 'ثب', 'مص. وَثَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وُثُوبٌ-وُثُوبٌ [و ث ب] (مص. وَثَبَ). ""وُثُوبُ الْحَيَوَانِ"" : قَفْزُهُ، هُجُومُهُ، اِنْقِضَاضُهُ. ""فِي الإِنْسَانِ مِنْ جَمِيعِ طَبَائِعِ الْحَيَوَانِ أَشْكَالٌ مِنْ خَتْلِ الذِّئْبِ وَرَوَغَانِ الثَّعْلَبِ وَوُثُوبِ الأَسَدِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23993, 'وَثْرٌ', 'وثر', 'مصدر', 'وثر', 'وثر', 'ثر', 'مص. وَثَرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَثْرٌ-وَثْرٌ [و ث ر] (مص. وَثَرَ). 1.""لَبِسَ الوَثْرَ"" : ثَوْبٌ كَالسَّرَاوِيلِ لاَ سَاقَيْنِ لَهُ. 2.: كَمَا يُطْلَقُ عَلَى مَا يُشْبِهُ الصِّدَارَ، أَيْ قَمِيصٌ بِلاَ أَكْمَامٍ. 3.: جِلْدٌ يُقَدُّ سُيُوراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23994, 'وَثَارَةٌ', 'وثارة', 'مصدر', 'وثر', 'وثارة', 'ثرة', 'مص. وَثُرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَثَارَةٌ-وَثَارَةٌ [و ث ر] (مص. وَثُرَ). ""وَثَارَةُ الفِرَاشِ"" : وَطْؤُهُ، لُيُونَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23995, 'تَوثِيرٌ', 'توثير', 'مصدر', 'وثر', 'توثير', 'تثر', 'مص. وثَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوثِيرٌ-تَوثِيرٌ [و ث ر] (مص. وثَّرَ). ""تَوْثِيرُ الفِرَاشِ"" : تَوْطِئَتُهُ، تَلْيِينُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23996, 'تَوْثِيقٌ', 'توثيق', 'مصدر', 'وثق', 'توثيق', 'تثق', 'مص. وَثَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْثِيقٌ-تَوْثِيقٌ [و ث ق] (مص. وَثَّقَ). 1. ""تَوْثِيقُ الْمَعْلُومَاتِ"": تَسْجِيلُهَا فِي بَطَائِقَ. 2. ""مِلَفُّ التَّوْثِيقِ"" : مِلَفُّ التَّحْفِيظِ. ""الْمَرْكَزُ الوَطَنِيُّ لِلتَّوْثِيقِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23997, 'ثِقَةٌ', 'ثقة', 'مصدر', 'وثق', 'ثقة', 'ثقة', 'مص. وَثَقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ثِقَةٌ-ثِقَةٌ [و ث ق] (مص. وَثَقَ). لِلْمُفْرَدِ وَالْمُذَكَّرِ وَالْمُؤَنَّثِ وَالجَمْعِ. 1.""أَثِقُ بِهِ ثِقَةً عَمْيَاءَ"" : الائْتِمَان. "" ثِقَتِي بِهِ كَبِيرَةٌ"". 2.""لَهُ ثِقَةٌ كَبِيرَةٌ فِي نَفْسِهِ"" : الْتَّأكُّدُ مِنْ أعْمَالِهِ وَأقْوَالِهِ. ""الثِّقَةُ بِالنَّفْسِ"" ""وَهَزَّتْ رَأْسَهَا هَزَّةَ الثِّقَةِ والاطْمِئْنَانِ"". (ن. محفوظ). 3.""هُوَ جَدِيرٌ بِالثِّقَةِ"" : مَنْ يُعْتَمَدُ عَلَيْهِ وَيُؤْتَمَنُ بِهِ، الْمَوْثُوقُ بِهِ. ""رَجُلٌ ثِقَةٌ"" ""شَاهِدٌ ثِقَةٌ"" ""رُوَاةٌ ثِقَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23998, 'مَوْثِقٌ', 'موثق', 'مصدر', 'وثق', 'موثق', 'مثق', 'مص. وَثَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَوَاثِقُ:مَيَاثِقُ"', '', 'R', '', '', '', '', '', '', '"(مص. وَثَقَ). ""كَانَ بَيْنَهُمَا مَوْثِقٌ"" : عَهْدٌ، مِيثَاقٌ.يوسف آية 80أَلَمْ تَعْلَمُوا أَنَّ أَبَاكُمْ قَدْ أَخَذَ عَلَيْكُمْ مَوْثِقاً مِنَ الله (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(23999, 'مَوَاثِقُ', 'مواثق', 'مصدر', '', 'مواثق', 'مثق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24000, 'مَيَاثِقُ', 'مياثق', 'مصدر', '', 'مياثق', 'مثق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24001, 'وُثُوقٌ', 'وثوق', 'مصدر', 'وثق', 'وثوق', 'ثق', 'مص. وَثِقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وُثُوقٌ-وُثُوقٌ [و ث ق] (مص. وَثِقَ). ""كَانَ أَكْثَرَ وُثُوقاً مِنْ خَطَوَاتِهِ مِمَّا كَانَ عَلَيْهِ قَبْلُ"" : أَكْثَرَ تَأَكُّداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24002, 'تَوْجِيبٌ', 'توجيب', 'مصدر', 'وجب', 'توجيب', 'تجب', 'مص. وَجَّبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْجِيبٌ-تَوْجِيبٌ [و ج ب] (مص. وَجَّبَ). ""تَوْجِيبُ الأمْرِ"": إلْزَامُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24003, 'وَجْبَةٌ', 'وجبة', 'مصدر', 'وجب', 'وجبة', 'جبة', 'مص. وَجَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. وَجَبَ). 1.""تَنَاوَلَ وَجْبَةً شَهِيَّةً"" : أَيْ أَكْلَةً وَاحِدَةً. ""وَجْبَةُ الْمَسَاءِ"" ""الوَجَبَاتُ الرَّئِيسَةُ"". 2.""وَجْبَةُ دَوَاءٍ"" : مِقْدَارُ دَوَاءٍ يُتَنَاوَلُ جُرْعَةً وَاحِدَةً. 3.""وَجْبَةُ الأَسْنَانِ"" : طَقْمُ الأَسْنَانِ الاصْطِنَاعِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24004, 'وَجْبٌ', 'وجب', 'مصدر', 'وجب', 'وجب', 'جب', 'مص. وَجَبَ', '', '', 'مفرد', 'DnN', '', '', '"وِجَابٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَجَبَ). 1.""وَلَدٌ وَجْبٌ"" : جَبَانٌ، أَوْ أَحْمَقُ. 2.""وَجْبُ اللَّبَنِ"" : إِنَاءٌ عَظِيمٌ مِنْ جِلْدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24005, 'وِجَابٌ', 'وجاب', 'مصدر', '', 'وجاب', 'جب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24006, 'وُجُوبٌ', 'وجوب', 'مصدر', 'وجب', 'وجوب', 'جب', 'مص. وَجَبَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وُجُوبٌ-وُجُوبٌ [و ج ب] (مص. وَجَبَ). ""وُجُوبُ العَمَلِ"": ضَرُورَتُهُ، لُزُومُهُ، ثُبُوتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24007, 'وِجْدَانٌ', 'وجدان', 'مصدر', 'وجد', 'وجدان', 'جدن', 'مص. وَجَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"وِجْدَانٌ-وِجْدَانٌ [و ج د] (مص. وَجَدَ). ""وِجْدَانُ الْمَرْءِ"" : نَفْسُهُ وَقُوَاهُ البَاطِنِيَّةُ، وَمَا يَتَأَثَّرُ بِهِ مِنْ لَذَّةٍ أَوْ أَلَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24008, 'وَجْدٌ', 'وجد', 'مصدر', 'وجد', 'وجد', 'جد', 'مص. وَجَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وُجْدٌ-وُجْدٌ [و ج د] (مص. وَجَدَ). ""حَيَاةُ وُجْدٍ وَغِنـىً"" : يَسَارٌ وَسَعَةٌ. الطلاق آية 6 أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنْتُمْ مِنْ وُجْدِكُمْ ( قرآن) ""تَعيشُ في فَضاءِ الوُجْدِ الرَّحِيبِ"". (أحمد التوفيق)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24009, 'وُجْدٌ', 'وجد', 'مصدر', 'وجد', 'وجد', 'جد', 'مص. وَجَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَجْدٌ-وَجْدٌ [و ج د] (مص. وَجَدَ). 1.""بِهِ وَجْدٌ"" : شَغَفٌ. 2.""أَرَّقَهُ الوَجْدُ"" : الْحُبُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24010, 'وُجُودٌ', 'وجود', 'مصدر', 'وجد', 'وجود', 'جد', 'مص. وَجَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"وُجُودٌ-وُجُودٌ [و ج د] (مص. وَجَدَ). 1.""خَرَجَ إِلَى الوُجُـودِ"" : أَيْ أَصْبَحَ ذَاتاً كَائِنَةً فِي الكَوْنِ. 2.""غَابَ عَنِ الوُجُودِ"" : أَيْ صَارَ فِي العَدَمِ. 3.""فَرَضَ وُجُودَهُ"" : ذَاتَهُ، كَيْنُونَتَهُ. ""لاَ بُدَّ أَنْ يَكُونَ لِلْفَتَاةِ وُجُودٌ بِشَكْلٍ مِنَ الأَشْكَالِ"". (ع. العروي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24011, 'وَجْزٌ', 'وجز', 'مصدر', 'وجز', 'وجز', 'جز', 'مص. وَجَزَ، وَجُزَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَجْزٌ-وَجْزٌ [و ج ز] (مص. وَجَزَ، وَجُزَ). 1.""كَلاَمٌ وَجْزٌ"": مُخْتَصَرٌ. 2.""وَجْزُ الكَلاَمِ"" : مَا كَانَ مُوجَزاً فِي بَلاَغَةٍ. 3.""وَلَدٌ وَجْزٌ"" : سَرِيعُ الْحَرَكَةِ فِيمَا أَخَذَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24012, 'وَجْسٌ', 'وجس', 'مصدر', 'وجس', 'وجس', 'جس', 'مص. وَجَسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَجْسٌ-وَجْسٌ [و ج س] (مص. وَجَسَ). 1.""كَانَ يُكَلِّمُهَا بِوَجْسٍ"" : بِصَوْتٍ خَفِيٍّ. 2.""اِسْتَبَّدَ بِهِ الوَجْسُ"" : فَزْعَةُ القَلْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24013, 'وَجَعٌ', 'وجع', 'مصدر', 'وجع', 'وجع', 'جع', 'مص. وَجِعَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْجَاعٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَجِعَ). "" وَجَعُ الرَّأْسِ"" : أَلَمُهُ، مَرَضُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24014, 'أَوْجَاعٌ', 'أوجاع', 'مصدر', '', 'ءوجاع', 'جع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24015, 'وَجَلٌ', 'وجل', 'مصدر', 'وجل', 'وجل', 'جل', 'مص. وَجِلَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْجَالٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَجِلَ)."" لاَ يَعْرِفُ الوَجَلُ إِلَى قَلْبِهِ سَبِيلاً"" : الخَوْفُ، الفَزَعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24016, 'أَوْجَالٌ', 'أوجال', 'مصدر', '', 'ءوجال', 'جل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24017, 'وَجْمٌ', 'وجم', 'مصدر', 'وجم', 'وجم', 'جم', 'مص. وَجَمَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْجَامٌ:وُجُومٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَجَمَ). 1.""وَجْمُ القُبُورِ أَوِ التِّلاَلِ"" : أَيْ حِجَارَةٌ مَرْكُومٌ بَعْضُهَا فَوْقَ بَعْضٍ عَلَى رُؤُوسِهَا. 2.""وَجْمُ الصَّحَارِي"" : عَلاَمَاتٌ يُهْتَدَى بِهَا. 3.""رَجُلٌ وَجْمٌ"" : بَخِيلٌ أَوْ لَئِيمٌ أَوْ رَدِيءٌ. 4.""وَجْمُ سُـوءٍ"" : رَجُلُ سُوءٍ. 5.""بَيْتٌ وَجْمٌ"" : عَظِيمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24018, 'أَوْجَامٌ', 'أوجام', 'مصدر', '', 'ءوجام', 'جم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24019, 'وُجُومٌ', 'وجوم', 'مصدر', '', 'وجوم', 'جم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24020, 'وُجُومٌ', 'وجوم', 'مصدر', 'وجم', 'وجوم', 'جم', 'مص. وَجَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وُجُومٌ-وُجُومٌ [و ج م] (مص. وَجَمَ). ""خَيَّمَ وُجُومٌ عَلَى الْحَاضِرِينَ"" : صَمْتٌ، سُكُوتٌ يَسُودُهُ قَلَقٌ وَحُزْنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24021, 'تَوْجِيهٌ', 'توجيه', 'مصدر', 'وجه', 'توجيه', 'تجه', 'مص. وَجَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. وَجَّهَ). 1.""يَحْتَاجُ إلَى تَوْجِيهٍ سَلِيمٍ"" : أيْ إلَى إرْشَادٍ. 2. ""اِخْتَارَ تَوْجِيهاً يَتَلاءَمُ مَعَ تَكْوِينِهِ"" : اِتِّجَاهاً، تَوَجُّهاً. 3. ""قَدَّمَ لَهُ تَوْجِيهَاتٍ تَرْبَوِيَّةً"": تَعْلِيماتٍ، إرْشَادَاتٍ. ""يَسْتَنِيرُونَ بِآرَائِهِ وَتَوْجِيهَاتِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24022, 'وَجْهٌ', 'وجه', 'مصدر', 'وجه', 'وجه', 'جه', 'مص. وَجَهَ', '', '', 'مفرد', 'DnN', '', '', '"وُجُوهٌ:أَوْجُهٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَجَهَ). 1.""وَجْهُ الإِنْسَانِ"" : مَا يُقَابِلُكَ مِنَ الرَّأْسِ وَفِيهِ الجَبْهَةُ وَالعَيْنَانِ وَالخَدَّانِ وَالأَنْفُ وَالفَمُ. 2.""أَدَارَ وَجْهَهُ لَهُ"" : اِنْصَرَفَ عَنْهُ. 3.""أَغْلَقَ البَابَ فِي وَجْهِهِ"" : صَدَّهُ، رَدَّهُ. 4.""سَارَ عَلَى وَجْهِـهِ"" : سَارَ دُونَ وَعْيٍ، وَلاَ انْتِبَاهٍ، وَلاَ مُبَالاَةٍ. 5.""صَانَ مَاءَ وَجْهِهِ"" : صَانَ كَرَامَتَهُ وَشَرَفَهُ. 6.""ضَحِكَ فِي وَجْهِهِ"" : اِبْتَسَمَ وَهَشَّ وَأَحْسَنَ اسْتِقْبَالَهُ. 7.""فَعَلَ مَا فَعَلَ لِوَجْهِ اللَّهِ"" : لِمَرْضَاتِهِ. 8.""بَيَّضَ اللَّهُ وَجْهَهُ"" : حَسَّنَ، جَمَّلَ قَدْرَهُ وَفِعْلَهُ الْمَحْمُودَ. 9.""رَجُلٌ ذُو وَجْهَيْنِ"" : مُنَافِقٌ، أَيْ يُظْهِرُ خِلاَفَ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24023, 'وُجُوهٌ', 'وجوه', 'مصدر', '', 'وجوه', 'جه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24024, 'أَوْجُهٌ', 'أوجه', 'مصدر', '', 'ءوجه', 'جه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24025, 'وَجَاهَةٌ', 'وجاهة', 'مصدر', 'وجه', 'وجاهة', 'جهة', 'مص. وَجُهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَجَاهَةٌ-وَجَاهَةٌ [و ج هـ] (مص. وَجُهَ). 1.""هُوَ ذُو وَجَاهَةٍ"": ذُو مَكَانَةٍ، قُوَّةٍ، مَرْتَبَةٍ، جَاهٍ. ""لَهُ وَجَاهَةٌ بَيْنَ قَوْمِهِ"". 2.""رَأْيٌ ذُو وَجَاهَةٍ"" : رَأْيٌ صَحِيحٌ، سَلِيمٌ. 3.""أَهْلُ الوَجَاهَةِ"": الأَعْيَانُ، كِبَارُ القَوْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24026, 'تَوْحِيدٌ', 'توحيد', 'مصدر', 'وحد', 'توحيد', 'تحد', 'مص. وَحَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"تَوْحِيدٌ-تَوْحِيدٌ [و ح د] (مص. وَحَّدَ). 1. ""سَعَى إلَى تَوْحِيدِ آرَاءِ الفِرَقِ الْمُتَنَاحِرَةِ"" : إلَى اتِّحَادِهَا، إلَى تَوَحُّدِهَا. ""اِجْتَمَعَتْ لَجْنَةُ تَوْحِيدِ البَرامِجِ الدِّرَاسِيَّةِ"" ""تَوْحِيدُ الْمُصْطَلَحَاتِ العَرَبِيَّةِ"". 2. ""الإسْلاَمُ دِينُ التَّوْحِيدِ"" : عِبَادَةُ إلَهٍ وَاحِدٍ، الإيمَانُ بِوَحْدَانِيَّةِ اللَّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24027, 'حِدَةٌ', 'حدة', 'مصدر', 'وحد', 'حدة', 'حدة', 'مص. وَحَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"حِدَّةٌ-حِدَّةٌ [ح د د] (مص.حَدَّ). 1.""اِشْتَدَّتْ حِدَّةُ غَضَبِهِ"" : حَمِيَّتُهُ. 2.""يَمْتازُ بِحِدَّةِ النَّظَرِ"" : بِنَفاذِهِ. 3.""بَلَغَتْ حِدَّةُ الأَلَمِ أَشُدَّها"" : شِدَّتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24028, 'وَحْدَةٌ', 'وحدة', 'مصدر', 'وحد', 'وحدة', 'حدة', 'مص. وَحَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. وَحَدَ). 1.""يَمِيلُ إِلَى الوَحْدَةِ"" : إِلَى الانْعِزَالِ وَالانْفِرَادِ بِنَفْسِهِ. 2.""وَحْدَةُ القِيَاسِ"" : كَمِّيَّةٌ تُتَّخَذُ قِيَاساً مُشْتَرَكاً لِسَائِرِ الكَمِّيَّاتِ الأُخْرَى الَّتِي هِيَ مِنْ ذَاتِ النَّوْعِ. مَثَلاً : ""المِتْرُ وَحْدَةٌ لِقِيَاسَاتِ الطُّولِ""، ""الغرَام وَحْدَةٌ لِقِيَاسَاتِ الوَزْنِ"" 3.""الوَحْدَةُ العَرَبِيَّةُ آتِيَةٌ لاَ رَيْبَ فِيهَا"": أَيِ اتِّحَادُ أَقْطَارِهَا في قُوَّةٍ وَاحِدَةٍ لِتَكْوِينِ الدَّوْلَةِ العَرَب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24029, 'وَحْدٌ', 'وحد', 'مصدر', 'وحد', 'وحد', 'حد', 'مص. وَحَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَحْدٌ-وَحْدٌ [و ح د] (مص. وَحَدَ). لاَ يُثَنَّى وَلاَ يُجْمَعُ. 1.""تَرَكْتُهُ وَحْدَهُ"" : أَيْ تَرَكْتُهُ مُنْفَرِداً. ""كُنْتُ وَحْدِي"" """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24030, 'وَحَرٌ', 'وحر', 'مصدر', 'وحر', 'وحر', 'حر', 'مص. وَحِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَحَرٌ-وَحَرٌ [و ح ر] (مص. وَحِرَ). 1.""اِشْتَدَّ بِهِ الوَحَرُ"" : الحِقْدُ، الغَيْظُ، أَوِ الغَضَبُ الشَّدِيدُ. 2. ""اِسْتَمَرَّ وَحَرُهُمَا زَمَناً طَوِيلاً"" : عَدَاوَتُهُمَا. 3.""اِسْتَسْلَمَ لِوَحَرِهِ"" : وَسَاوِسُ الصَّدْرِ وَهَواجِسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24031, 'وَحْفٌ', 'وحف', 'مصدر', 'وحف', 'وحف', 'حف', 'مص. وَحَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَحْفٌ-وَحْفٌ [و ح ف] (مص. وَحَفَ). 1.""شَعْرٌ وَحْفٌ"" : كَثِيفٌ أَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24032, 'وَحْلٌ', 'وحل', 'مصدر', 'وحل', 'وحل', 'حل', 'مص. وَحَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَحْلٌ-وَحْلٌ [وح ل] (مص. وَحَلَ). ن. وَحَلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24033, 'وَحَلٌ', 'وحل', 'مصدر', 'وحل', 'وحل', 'حل', 'مص. وَحِلَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْحَالٌ:وُحُولٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَحِلَ). ""تَلَطَّخَ بِالوَحَلِ"" : بِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24034, 'أَوْحَالٌ', 'أوحال', 'مصدر', '', 'ءوحال', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24035, 'وُحُولٌ', 'وحول', 'مصدر', '', 'وحول', 'حل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24036, 'تَوْحِيمٌ', 'توحيم', 'مصدر', 'وحم', 'توحيم', 'تحم', 'مص. وَحَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْحِيمٌ-تَوْحِيمٌ [و ح م] (مص. وَحَّمَ). ""تَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24037, 'وَحَمٌ', 'وحم', 'مصدر', 'وحم', 'وحم', 'حم', 'مص. وَحِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَحِمٌ-وَحِمٌ [و ح م] (صِيغَةُ فَعِل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24038, 'وَحْيٌ', 'وحي', 'مصدر', 'وحى', 'وحي', 'ح', 'مص. وَحَى', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"وَحْيٌ-وَحْيٌ [و ح ى] (مص. وَحَى). 1.""كَانَ وَحْيُهُ إِلَيْهِ يَتَضَمَّنُ أَكْثَرَ مِنْ مَعْنـىً"" : مَا يُلْقَى إِلَى الغَيْرِ لِيَعْلَمَهُ. 2.""الوَحْيُ الإِلَهِيُّ"" : مَا يُوحِي بِهِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24039, 'وَخْزٌ', 'وخز', 'مصدر', 'وخز', 'وخز', 'خز', 'مص. وَخَزَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَخْزٌ-وَخْزٌ، ةٌ [و خ ز] (مص. وَخَزَ). 1. ""وَخْزُ الإِبْرَةِ"" : وَجَعُ شَكَّتِهَا. ""وَخْزُ رُمْحٍ"" ""أَحَسَّ وَخْزَةً أَلِيمَةً فِي قَلْبِهِ"". 2.""فِي الرَّأْسِ وَخْزٌ قَلِيلٌ مِن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24040, 'وَخْزَةٌ', 'وخزة', 'مصدر', 'وخز', 'وخزة', 'خزة', 'مص. وَخَزَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَخْزٌ-وَخْزٌ، ةٌ [و خ ز] (مص. وَخَزَ). 1. ""وَخْزُ الإِبْرَةِ"" : وَجَعُ شَكَّتِهَا. ""وَخْزُ رُمْحٍ"" ""أَحَسَّ وَخْزَةً أَلِيمَةً فِي قَلْبِهِ"". 2.""فِي الرَّأْسِ وَخْزٌ قَلِيلٌ مِن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24041, 'تَوْخِيمٌ', 'توخيم', 'مصدر', 'وخم', 'توخيم', 'تخم', 'مص. وَخَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْخِيمٌ-تَوْخِيمٌ [و خ م] (مص. وَخَّمَ). 1. ""تَوْخِيمُ الْمَكَانِ"": جَعْلُهُ مُت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24042, 'وَخْيٌ', 'وخي', 'مصدر', 'وخي', 'وخي', 'خ', 'مص. وَخَى', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"وَخْيٌ-وَخْيٌ [و خ ي] (مص. وَخَى). ""وَخَى وَخْيَهُ"" : قَصَدَ قَصْدَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24043, 'مَوَدَّةٌ', 'مودة', 'مصدر', 'ودد', 'مودة', 'مدة', 'مص. وَدَّ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"مَوَدَّةٌ-مَوَدَّةٌ [و د د] (مص. وَدَّ). ""بَيْنَهُمْ مَوَدَّةٌ"" : مَحَبّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24044, 'وِدَادٌ', 'وداد', 'مصدر', 'ودد', 'وداد', 'دد', 'مص. وَدَّ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وِدَادٌ-وِدَادٌ [و د د] (مص. وَدَّ). ""عَبَّرَ عَنْ وِدَادِهِ"" : عَنْ حُبِّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24045, 'وَدٌّ', 'ود', 'مصدر', 'ودد', 'ود', 'د', 'مص. وَدَّ', '', '', 'مفرد', '', '', '', '', '', 'Rp', '', '', '', '', '', '', '"وَدٌّ-وَدٌّ، وِدٌّ، وُدٌّ [و د د] (مص. وَدَّ). 1.""بَيْنَهُمَا وَدٌّ"" : حُبٌّ، مَحَبَّةٌ. ""الحَسَدُ دَاءٌ يُنْه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24046, 'وِدَاجٌ', 'وداج', 'مصدر', 'ودج', 'وداج', 'دج', 'مص. وَدَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وِدَاجٌ-وِدَاجٌ [و د ج] (مص. وَدَجَ). ""قَطَعَ وِدَاجَهُ "" : عِرْقٌ فِي الع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24047, 'تَوْدِيعٌ', 'توديع', 'مصدر', 'ودع', 'توديع', 'تدع', 'مص. وَدَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْدِيعٌ-تَوْدِيعٌ [و د ع] (مص. وَدَّعَ). ""جَاءَ لِتَوْدِيعِهِ فِي "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24048, 'وَدَاعَةٌ', 'وداعة', 'مصدر', 'ودع', 'وداعة', 'دعة', 'مص. وَدُعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَدَاعَةٌ-وَدَاعَةٌ [و د ع] (مص. وَدُعَ). 1.""عَامَلَهُ بِوَدَاعَةٍ"" : بِلُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24049, 'وَدْقٌ', 'ودق', 'مصدر', 'ودق', 'ودق', 'دق', 'مص. وَدَقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَدْقٌ-وَدْقٌ [و د ق] (مص. وَدَقَ). 1.""أَمْطَرَتِ السَّمَاءُ وَدْقاً"" : مَطَراً شَدِيداً أَوْ هَيِّناً.النور آية 43فَتَرَى الوَدْقَ يَخْرُجُ مِنْ خِلاَلِهِ ( قرآن). 2.""وَدْقُ العَيْنِ"" : نُقَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24050, 'وَدَقٌ', 'ودق', 'مصدر', 'ودق', 'ودق', 'دق', 'مص. وَدِقَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَدَقٌ-وَدَقٌ، ةٌ [و د ق] (مص. وَدِقَ). ""وَدَقُ العَيْنِ، أَوْ وَدَقَةُ العَيْنِ"" : نُقْطَةٌ حَمْرَاءُ تَظْهَرُ فِي العَيْنِ أَوْ لَحْمَةٌ تَكْبُرُ فِيهَا وَتَعْظُمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24051, 'وَدَقَةٌ', 'ودقة', 'مصدر', 'ودق', 'ودقة', 'دقة', 'مص. وَدِقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَدَقٌ-وَدَقٌ، ةٌ [و د ق] (مص. وَدِقَ). ""وَدَقُ العَيْنِ، أَوْ وَدَقَةُ العَيْنِ"" : نُقْطَةٌ حَمْرَاءُ تَظْهَرُ فِي العَيْنِ أَوْ لَحْمَةٌ تَكْبُرُ فِيهَا وَتَعْظُمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24052, 'وَدَكٌ', 'ودك', 'مصدر', 'ودك', 'ودك', 'دك', 'مص. وَدِكَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَدِكٌ-وَدِكٌ [و د ك] (صِيغَةُ فَعِل). ""خَرُوفٌ وَدِكٌ"" : سَمِينٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24053, 'دِيَةٌ', 'دية', 'مصدر', 'ودي', 'دية', 'دة', 'مص. وَدَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. وَدَى). ""رَفَضَتِ العائِلَةُ دِيَة ابْنِها القَتيلِ"" : ما يُدْفَعُ مِنْ مالٍ لِلْعائِلَةِ بَدَلَ روحِ القَتيلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24054, 'وَذْءٌ', 'وذء', 'مصدر', 'وذأ', 'وذء', 'ذ', 'مص. وَذَأَ', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"وَذْءٌ-وَذْءٌ [و ذ أ] (مص. وَذَأَ). ""يَنْأَى بِنَفْسِهِ أَنْ يَسْمَعَ وَذْءَ النَّاسِ"" : الْمَكْرُوهَ مِنَ الكَلاَمِ شَتْماً كَانَ أَوْ غَيْرَ شَتْمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24055, 'تَوْذِيمٌ', 'توذيم', 'مصدر', 'وذم', 'توذيم', 'تذم', 'مص. وَذَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْذِيمٌ-تَوْذِيمٌ [و ذ م] (مص. وَذَّمَ). 1. ""تَوْذِيمُ الكَلْبِ"" : شَدُّ عُنُقِهِ بِالقِلادَةِ. 2. ""تَوْذِيمُ الدَّلْوِ"" : جَعْلُ حَبْلٍ لَهَا. 3. ""تَوْذِيمُهُ عَلَى السَّبْعينَ"" : تَجَاوُزُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24056, 'وَذَمٌ', 'وذم', 'مصدر', 'وذم', 'وذم', 'ذم', 'مص. وَذَمَ', '', '', 'مفرد', 'DnN', '', '', '"وُذُومٌ:أَوْذَامٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَذَمَ). ""وَذَمُ الدَّلْوِ"" : حَبْلُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24057, 'وُذُومٌ', 'وذوم', 'مصدر', '', 'وذوم', 'ذم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24058, 'أَوْذَامٌ', 'أوذام', 'مصدر', '', 'ءوذام', 'ذم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24059, 'إِرْثٌ', 'إرث', 'مصدر', 'ورث', 'ءرث', 'إرث', 'مص. وَرِثَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"إِرْثٌ-إِرْثٌ [و ر ث] (مص. وَرِثَ). ""تَرَكَ لأَبْنَائِهِ إِرْثاً"" : مَا يَتْرُكُهُ الْمَيِّتُ مِنْ أَثَاثٍ وعَقَارٍ لِوَرَثَتِهِ. ""اِقْتَسَمُوا الإِرْثَ بَيْنَهُمْ كُلٌّ وَنَصِيبُهُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24060, 'وِرَاثَةٌ', 'وراثة', 'مصدر', 'ورث', 'وراثة', 'رثة', 'مص. وَرِثَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وِرَاثَةٌ-وِرَاثَةٌ [و ر ث] (مص. وَرِثَ). 1.""أَمْلاَكٌ اِنْتَقَلَتْ إِلَى الأُسْرَةِ بِالوِرَاثَةِ"" : أَي اِنْتِقَالُهَا مِنَ الآبَاءِ إِلَى الأَبْنَاءِ. ""وِرَاثَةُ الأَبْنَاءِ لِصِفَاتِ آبَائِهِمْ"". 2.""عِلْمُ الوِرَاثَةِ"" : عِلْمٌ يَبْحَثُ فِي خَصَائِصِ انْتِقَالِ الصِّفَاتِ الْمُشْتَرَكَةِ بَيْنَ السُّلاَلاَتِ، وَهِيَ تَشْمُلُ الإِنْسَانَ وَالحَيَوَانَ وَالنَّبَاتَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24061, 'وِرْثٌ', 'ورث', 'مصدر', 'ورث', 'ورث', 'رث', 'مص. وَرِثَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وِرْثٌ-وِرْثٌ [و ر ث] (مص. وَرِثَ). ""هَذَا مِنْ وِرْثِهِ"" : أَيْ مَا وُرِثَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24062, 'تَوْرِيدٌ', 'توريد', 'مصدر', 'ورد', 'توريد', 'ترد', 'مص. وَرَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْرِيدٌ-تَوْرِيدٌ [و ر د] (مص. وَرَّدَ). 1. ""تَوْرِيدُ الثَّوْبِ"" : صَبْغُهُ عَلَى لَوْنِ الوَرْدِ. 2. ""تَوْرِيدُ الشَّجَرَةِ"" : إخْرَاجُهَا لِلنُّورِ. 3. ""تَوْرِيدُ الْمَرْأَةِ"" : اِحْمِرَارُ خَدَّيْهَا. 4. ""تَوْرِيدُ البَضَائِعِ"" : اِسْتِيرادُها، جَلْبُهَا مِنَ الخَارِجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24063, 'وَرَشٌ', 'ورش', 'مصدر', 'ورش', 'ورش', 'رش', 'مص. وَرِشَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَرَشٌ-وَرَشٌ [و ر ش] (مص. وَرِشَ). ""وَرَشُ الجَوْفِ"" : أَلَمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24064, 'تَوْرِيطٌ', 'توريط', 'مصدر', 'ورط', 'توريط', 'ترط', 'مص. وَرَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْرِيطٌ-تَوْرِيطٌ [و ر ط] (مص. وَرَّطَ). ""تَوْرِيطُ الرَّجُلِ"" : جَعْلُهُ يَعِيشُ فِي وَرْطَةٍ، فِي قَضِيَّةٍ يَصْعُبُ التَّخَلُّصُ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24065, 'تَوْرِيعٌ', 'توريع', 'مصدر', 'ورع', 'توريع', 'ترع', 'مص. وَرَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْرِيعٌ-تَوْرِيعٌ [و ر ع] (مص. وَرَّعَ). ""حَاوَلَ تَوْرِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24066, 'وَرَعٌ', 'ورع', 'مصدر', 'ورع', 'ورع', 'رع', 'مص. وَرِعَ، وَرَعَ، وَرُعَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْرَاعٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَرِعَ، وَرَعَ، وَرُعَ). 1.""يَعِيشُ فِي وَرَعٍ"" : فِي تَقْوىً وَنُسُكٍ مُجْتَنِباً الْمَعَاصِيَ وَال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24067, 'أَوْرَاعٌ', 'أوراع', 'مصدر', '', 'ءوراع', 'رع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24068, 'تَوْرِيفٌ', 'توريف', 'مصدر', 'ورف', 'توريف', 'ترف', 'مص. وَرَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْرِيفٌ-تَوْرِيفٌ [و ر ف] (مص. وَرَّفَ). ""تَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24069, 'وَرْفٌ', 'ورف', 'مصدر', 'ورف', 'ورف', 'رف', 'مص. وَرَفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَرْفٌ-وَرْفٌ [و ر ف] (مص. وَرَفَ). ""وَرْفُ الشَّجَرِ"" : اِهْتِزَازُهُ، وَبَهْجَتُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24070, 'تَوْرِيقٌ', 'توريق', 'مصدر', 'ورق', 'توريق', 'ترق', 'مص. وَرَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْرِيقٌ-تَوْرِيقٌ [و ر ق] (مص. وَرَّقَ). 1. ""تَوْرِيقُ الشَّجَرِ"" : إخْرَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24071, 'تَوْرِيمٌ', 'توريم', 'مصدر', 'ورم', 'توريم', 'ترم', 'مص. وَرَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْرِيمٌ-تَوْرِيمٌ [و ر م] (مص. وَرَّمَ). 1. ""تَورِيمُ الجِلْدِ"" : جَعْلُهُ يَنْتَفِخُ. 2. ""تَوْرِيمُ الرَّجُلِ بِأنْفِهِ"" : تَكَبُّرُهُ، شُمُوخُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24072, 'وَرَمٌ', 'ورم', 'مصدر', 'ورم', 'ورم', 'رم', 'مص. وَرِمَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْرَامٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَرِمَ). 1.""وَرَمُ الْجِلْـدِ"" : اِنْتِفَاخُهُ. ""فِي عَيْنِهِ وَرَمٌ"". 2.""وَرَمٌ خَبِيثٌ"" : دُمَّلٌ خَبِيثٌ، سَرَطَانٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24073, 'أَوْرَامٌ', 'أورام', 'مصدر', '', 'ءورام', 'رم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24074, 'تَوْرِيَةٌ', 'تورية', 'مصدر', 'وري', 'تورية', 'ترة', 'مص. وَرَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَوْرِيَةٌ-تَوْرِيَةٌ [و ر ي] (مص. وَرَّى). 1. ""تَوْرِيَةُ النَّارِ"" : اِسْتِخْرَاجُهَا. 2. ""تَوْرِيَةُ الأرْبَاحِ"" : إخْفَاؤُهَا. 3. ""التَّوريَةُ عَنِ الصَّدِيق"" : الْمُرَافَعَةُ عَنْهُ. 4. ""التَّوْريَةُ فِي البَدِيعِ، الإتْيَانُ بِلَفْظٍ لَهُ مَعْنَيان، مَعْنىً قَرِيبٌ ظَاهِرٌ غَيْرُ مَقْصُودٍ، وَمَعْنىً بَعِيدٌ خَفِيٌّ هُوَ المقْصُودُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24075, 'وَرْيٌ', 'وري', 'مصدر', 'وري', 'وري', 'ر', 'مص. وَرِيَ، وَرَى', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"وَرِيٌّ-وَرِيٌّ [و ر ي] (صف). ""زَنْدٌ وَرِيٌّ"" : أَيِ الزَّنْدُ الَّذِي خَرَجَتْ نَارُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24076, 'وِزَارَةٌ', 'وزارة', 'مصدر', 'وزر', 'وزارة', 'زرة', 'مص. وَزَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وِزَارَةٌ-وِزَارَةٌ، وَزَارَةٌ [و ز ر] (مص. وَزَرَ). 1.""وِزَارَةُ التَّعْلِيمِ"" : الجِهَازُ الإِدَارِيُّ الْمَسْؤُولُ عَنْ تَنْفِيذِ سِيَاسَةِ الْحُكُومَةِ وَخُطَّتِهَا فِي مَيْدَانِ التَّعْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24077, 'وِزْرٌ', 'وزر', 'مصدر', 'وزر', 'وزر', 'زر', 'مص. وَزَرَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْزَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَزَرَ). 1.""حَمَلَ وِزْراً"" : حِمْلاً ثَقِيلاً. 2.""اِرْتَكَبَ وِزْراً"" : ذَنْباً، إِثْماً.""غَسَلَ أَوْزَارَهُ"". 3.""أَوْزَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24078, 'أَوْزَارٌ', 'أوزار', 'مصدر', '', 'ءوزار', 'زر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24079, 'تَوْزِيعٌ', 'توزيع', 'مصدر', 'وزع', 'توزيع', 'تزع', 'مص. وَزَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْزِيعٌ-تَوْزِيعٌ [و ز ع] (مص. وَزَّعَ). ""تَوْزِيعُ الجَوَائِزِ"" : تَفْرِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24080, 'وَزْنٌ', 'وزن', 'مصدر', 'وزن', 'وزن', 'زن', 'مص. وَزَنَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْزَانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَزَنَ). 1.""وَزْنُ البِضَاعَةِ"" : مِقْدَارُ ثِقْلِهَا. ""الوَزْنُ الصَّافِي"" ""الأَوْزَانُ وَالْمَكَايِيلُ"". 2.""الوَزْنُ النَّوْعِيُّ"" : نِسْبَةُ ثِقَلِ الجِسْمِ إِلَى جِسْمٍ يُسَاوِي حَجْمَهُ مِنَ الْمَاءِ. 3.""الوَزْنُ فِي الصَّرْفِ"" : قَوْلُكَ ضَرَبَ عَلَى وَزْنِ فَعَلَ، أَيْ صِيغَةُ ضَرَبَ تُقَابِلُ فَعَلَ. 4.""الوَزْنُ فِي الشِّعْرِ"" : أَوْزَانُ البُحُورِ الشِّعْرِيَّةِ العَرَبِيَّةِ، أَيْ مَا يُقَابِلُ التَّفْعِيلَةَ العَرُوضِيَّةَ لِبَيْتٍ مِنَ الشِّعْرِ. 5.""أَقَامَ لِكَلاَمِهِ وَزْناً"" : أَع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24081, 'أَوْزَانٌ', 'أوزان', 'مصدر', '', 'ءوزان', 'زن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24082, 'تَوْسِيخٌ', 'توسيخ', 'مصدر', 'وسخ', 'توسيخ', 'تسخ', 'مص. وَسَّخَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْسِيخٌ-تَوْسِيخٌ [و س خ] (مص. وَسَّخَ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24083, 'وَسَخٌ', 'وسخ', 'مصدر', 'وسخ', 'وسخ', 'سخ', 'مص. وَسِخَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْسَاخٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَسِخَ). ""وَسَخُ الثِّيَابِ"" : م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24084, 'أَوْسَاخٌ', 'أوساخ', 'مصدر', '', 'ءوساخ', 'سخ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24085, 'تَوْسِيدٌ', 'توسيد', 'مصدر', 'وسد', 'توسيد', 'تسد', 'مص. وَسَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْسِيدٌ-تَوْسِيدٌ [و س د] (مص. وَسَّدَ). 1. ""تَوْسِيدُ الوِسَادَةِ"": جَع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24086, 'تَوْسِيطٌ', 'توسيط', 'مصدر', 'وسط', 'توسيط', 'تسط', 'مص. وَسَّطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْسِيطٌ-تَوْسِيطٌ [و س ط] (مص. وَسَّطَ). 1. ""تَوْسِيطُ صَاحِبِهِ فِي مُهِمَّةٍ"" : جَعْلُهُ وَسِيطاً. 2. ""تَوْسِيطُهُ الْمَجْلِسَ"" : جَعْلُهُ فِي وَسَطِهِ. 3. ""تَوْسِيطُ الخُبْزِ"" : قَطْعُهُ نِصْفَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24087, 'وَسَاطَةٌ', 'وساطة', 'مصدر', 'وسط', 'وساطة', 'سطة', 'مص. وَسَطَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَسَاطَةٌ-وَسَاطَةٌ [و س ط] (مص. وَسَطَ). ""فَتَحَتْ وَسَاطَتُهُ عَهْداً جَدِيداً بَيْنَ البَلَدَيْنِ بَعْدَ نِزَاعٍ"" : عَمَلُ الوَسِيطِ الَّذِي يَسْعَى إِلَى تَقْرِيبِ وِجْهَاتِ النَّظَرِ بَيْنَ الْمُتَنَازِعِينَ لِفَكِّ نِزَاعٍ قَائِمٍ. ""يَتَكَلَّمُ عَنْ نَفْسِهِ بِكَيْفِيَّةٍ مُبَاشِرَةٍ دُونَ مُقَارَبَةٍ وَلاَ وَسَاطَةٍ"". (ع. العروي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24088, 'تَوْسِيعٌ', 'توسيع', 'مصدر', 'وسع', 'توسيع', 'تسع', 'مص. وَسَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْسِيعٌ-تَوْسِيعٌ [و س ع] (مص. وَسَّعَ). 1. ""تَوْسِيعُ الدَّارِ"" : جَعْلُهَا وَاسِعَةً فَسِيحَةً. 2. ""التَّوَسُّعُ فِي الرِّزْقِ"" : تَنْمِيَتُهُ وَالزِّيَادَةُ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24089, 'سَعَةٌ', 'سعة', 'مصدر', 'وسع', 'سعة', 'سعة', 'مص. وَسَعَ، وُسِعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"سَعَةٌ-سَعَةٌ [و س ع] (مص. وَسَعَ، وُسِعَ). 1. ""يَعِيشُ فِي سَعَةٍ"" : فِي يُسْرٍ وَغِنـىً. 2. ""عُرِفَ بِسَعَةِ الصَّدْرِ"" : بِاتِّسَاعِهِ وَقُدْرَتِهِ علَى التَّحَمُّلِ. ""فَلاَ قِوَامَ للرَّعِيَّةِ إلاَّ بِحُسْنِ سِيَاسَةِ الْمُلُوكِ وَسَعَةِ أَخْل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24090, 'تَوْسِيقٌ', 'توسيق', 'مصدر', 'وسق', 'توسيق', 'تسق', 'مص. وَسَّقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْسِيقٌ-تَوْسِيقٌ [و س ق] (مص. وَسَّقَ). ""تَوْسِيقُ البَضَائِعِ"" : حَمْلُهَا، شَحْنُهَا فِي حُمولاتٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24091, 'وَسْقٌ', 'وسق', 'مصدر', 'وسق', 'وسق', 'سق', 'مص. وَسَقَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْسَاقٌ:وُسُوقٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَسَقَ). ""وَسْقُ جَمَلٍ"" : حِمْلُهُ. ""وَسْقُ سَفِينَةٍ"" ""وَسْقُ شَاحِنَةٍ"" ""يَأْتُونَ بِمَرَاكِبِهِمْ لِوَسْقِ الْجُلُودِ"". (ع. العروي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24092, 'أَوْسَاقٌ', 'أوساق', 'مصدر', '', 'ءوساق', 'سق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24093, 'وُسُوقٌ', 'وسوق', 'مصدر', '', 'وسوق', 'سق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24094, 'وَسِيقٌ', 'وسيق', 'مصدر', 'وسق', 'وسيق', 'سق', 'مص. وَسَقَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَسِيقٌ-وَسِيقٌ [و س ق] (مص. وَسَقَ). 1.""أَرْسَلَ لَهُ وَسِيـقاً"" : طَرْداً. 2.""أَمْطَرَ الوَسِيقُ"" : الْمَطَرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24095, 'تَوْسِيلٌ', 'توسيل', 'مصدر', 'وسل', 'توسيل', 'تسل', 'مص. وَسَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْسِيلٌ-تَوْسِيلٌ [و س ل] (مص. وَسَّلَ). ""التَّوْسِيلُ إلَى اللَّهِ بِالعَمَلِ الصَّالِحِ"" : التَّوَسُّلُ إِلَيْهِ، التَّقَرُّبُ إلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24096, 'سِمَةٌ', 'سمة', 'مصدر', 'وسم', 'سمة', 'سمة', 'مص. وَسَمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. وَسَمَ). 1. ""تَرَكَ سِمَةً عَلَى وَجْهِهِ"" : أيْ عَلاَمَةً. 2. ""مِنْ سِمَاتِهِ حُبُّ الخَيْرِ"" : مِنْ طَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24097, 'وَسَامَةٌ', 'وسامة', 'مصدر', 'وسم', 'وسامة', 'سمة', 'مص. وَسُمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَسَامَةٌ-وَسَامَةٌ [و س م] (مص. وَسُمَ). ""وَسَامَةُ وَجْهٍ"" : حُسْنُهُ، جَمَالُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24098, 'وَسْمٌ', 'وسم', 'مصدر', 'وسم', 'وسم', 'سم', 'مص. وسم', '', '', 'مفرد', 'DnN', '', '', '"وُسُومٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وسم). 1.""تَرَكَ الْجُرْحُ وَسْماً عَلَى جَسَدِهِ"" : أَثَراً، عَلاَمَةً. 2.""وَسْمُ دَابَّةٍ"" : أَثَرُ الكَيِّ."', '');
