INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24100, 'وَسَنٌ', 'وسن', 'مصدر', 'وسن', 'وسن', 'سن', 'مص. وَسِنَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْسَانٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَسِنَ). 1.""أَخَذَهُ الوَسَنُ"" : النُّعَاسُ. 2.""أَشْبَعَ وَسَنَهُ"" : حَاجَتَهُ."', '');
