INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24102, 'وَسْوَسَةٌ', 'وسوسة', 'مصدر', 'وسوس', 'وسوسة', 'سسة', 'مص. وَسْوَسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَسْوَسَةٌ-وَسْوَسَةٌ [و س و س] (مص. وَسْوَسَ). ""إِنَّهَا وَسْوَسَةُ الشَّيْطَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24103, 'وَشِيجٌ', 'وشيج', 'مصدر', 'وشج', 'وشيج', 'شج', 'مص. وَشَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":وَشَائِجُ"', '', 'R', '', '', '', '', '', '', '"(مص. وَشَجَ). 1.""وَشِيجُ القَنَا وَالقَصَبِ"" : مَا نَبَتَ مِنْهُ مُلْتَفّاً. 1.""بَيْنَهُمَا وَشِيجُ قَرَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24104, 'وَشِيجَةٌ', 'وشيجة', 'مصدر', 'وشج', 'وشيجة', 'شجة', 'مص. وَشَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":وَشَائِجُ"', '', 'R', '', '', '', '', '', '', '"(مص. وَشَجَ). 1.""وَشِيجُ القَنَا وَالقَصَبِ"" : مَا نَبَتَ مِنْهُ مُلْتَفّاً. 1.""بَيْنَهُمَا وَشِيجُ قَرَا"', '');
