INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24106, 'تَوْشِيحٌ', 'توشيح', 'مصدر', 'وشح', 'توشيح', 'تشح', 'مص. وَشَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْشِيحٌ-تَوْشِيحٌ [و ش ح] (مص. وَشَّحَ). 1. ""تَوْشِيحُ البَطَلِ"": إلْبَاسُهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24107, 'وَشْكٌ', 'وشك', 'مصدر', 'وشك', 'وشك', 'شك', 'مص. وَشَكَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَشْكٌ-وَشْكٌ [و ش ك] (مص. وَشَكَ). ""عَلَى وَشْكِ أَنْ يَنْفَجِرَ بُكَاءً"" : عَلَى قُرْبٍ أَنْ... يَكَادُ بِسُرْعَةٍ... ""عَلَى وَشْكِ أَنْ يَسْقُطَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24108, 'وَشْمٌ', 'وشم', 'مصدر', 'وشم', 'وشم', 'شم', 'مص. وَشَمَ', '', '', 'مفرد', 'DnN', '', '', '"وُشُومٌ:وِشَامٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَشَمَ). ""مَا زَالَ الوَشْمُ سَائِداً فِي بَعْضِ القُرَى وَالجِبَالِ النَّائِيَةِ"" : الرُّسُومُ وَالْخُطُوطُ الْخُضْرُ الَّتِي ت"', '');
