INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24110, 'وِشَامٌ', 'وشام', 'مصدر', '', 'وشام', 'شم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24111, 'وَشْوَشَةٌ', 'وشوشة', 'مصدر', 'وشوش', 'وشوشة', 'ششة', 'مص. وَشْوَشَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. وَشْوَشَ). ""وَشْوَشَةٌ فِي القَاعَةِ"" : هَمْسٌ خَفِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24112, 'تَوْشِيةٌ', 'توشية', 'مصدر', 'وشي', 'توشية', 'تشة', 'مص. وَشَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَوْشِيةٌ-تَوْشِيةٌ [و ش ي] (مص. وَشَّى). 1. ""تَوِشِيةُ الثَّوْبِ"": تَحْسِينُهُ بِالألْوَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24113, 'وِشَايَةٌ', 'وشاية', 'مصدر', 'وشي', 'وشاية', 'شة', 'مص. وَشَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وِشَايَةٌ-وِشَايَةٌ [و ش ي] (مص. وَشَى). ""لاَ تُصَدِّقْ مَا قِيلَ، إِنَّهَا مُجَرَّدُ وِشَاي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24114, 'وَشْيٌ', 'وشي', 'مصدر', 'وشي', 'وشي', 'ش', 'مص. وَشَى', '', '', 'مفرد', 'DnN', '', '', '"وِشَاءٌ"', '', '', '', '', '', '', '', '', '"(مص. وَشَى). 1.""وَشْيُ الثَّوْبِ"" : نَقْشُهُ بِالأَلْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24115, 'وِشَاءٌ', 'وشاء', 'مصدر', '', 'وشاء', 'ش', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24116, 'صِفَةٌ', 'صفة', 'مصدر', 'وصف', 'صفة', 'صفة', 'مص. وَصَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. وَصَفَ). 1.""الصِّفَةُ فِي اللُّغَةِ"" : الكَلِمَةُ الَّتِي تَدُلُّ عَلَى مَعْنـىً يُضَافُ إِلَى الاِسْمِ لِلدَّلاَلَةِ عَلَى حَالَةٍ لَهُ، نَعْتُهُ. ""وَجْهٌ جَمِيلٌ"" ""شَابٌّ وَسِيمٌ"" ""رَجُلٌ طَوِيلُ القَامَةِ"". 2.""الصِّفَةُ الْمُشَبَّهَةُ"" : صِيغَةٌ مُشْتَقَةٌّ مِنَ الفِعْلِ اللاَّزِمِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24117, 'وَصْفٌ', 'وصف', 'مصدر', 'وصف', 'وصف', 'صف', 'مص. وَصَفَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْصَافٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. وَصَفَ). 1.""وَصْفُ الطَّبِيعَةِ"" : نَعْتُ مَا بِهَا وَالتَّمْثِيلُ بِمَا يُمَاثِلُ وَاقِعَهَا. ""كَانَ وَصْفُ عَوَاطِفِهِ صَادِقاً وَمُعَبِّراً عَنْ وَاقِعِهِ"". 2.""فَنُّ الوَصْفِ"" : فَنٌّ مِنْ فُنُون"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24118, 'تَوْضِيحٌ', 'توضيح', 'مصدر', 'وضح', 'توضيح', 'تضح', 'مص. وَضَّحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْضِيحٌ-تَوْضِيحٌ [و ض ح] (مص. وَضَّحَ). ""تَوْضِيحُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24119, 'أَوْصَافٌ', 'أوصاف', 'مصدر', '', 'ءوصاف', 'صف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24120, 'تَوْصِيلٌ', 'توصيل', 'مصدر', 'وصل', 'توصيل', 'تصل', 'مص. وَصَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْصِيلٌ-تَوْصِيلٌ [و ص ل] (مص. وَصَّلَ). 1. ""تَوْصِيلُ أسْلاَكِ الكَهْربَاءِ"" : رَبْطُهَا بِمَرْكَزِهَا الآلِيِّ. 2. ""تَوْصِيلُ الأمَانَةِ إلَى أهْلِهَا"" : إبْلاغُهُمْ إيَّاهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24121, 'صِلَةٌ', 'صلة', 'مصدر', 'وصل', 'صلة', 'صلة', 'مص. وَصَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"(مص. وَصَلَ). 1.""تَرْبِطُهُ بِهِ صِلَةُ قَرَابَةٍ"" : عَلاَقَةٌ. ""صِلَةُ الرَّحِمِ"" ""لاَ صِلَةَ لَهُ بِهِ"". 2.""كَانَ صِلَةَ وَصْلٍ بَيْنَهُمَا"" : أَيْ كَانَ يَصِلُ بَيْنَهُمَا، رَابِطاً بَيْنَهُمَا. ""لاَ يَقْطَعُ حَبْلَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24122, 'وَصْلٌ', 'وصل', 'مصدر', 'وصل', 'وصل', 'صل', 'مص. وَصَلَ', '', '', 'مفرد', 'DnN', '', '', '"وُصُولاَتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَصَلَ). 1.""اِنْعَقَدَ الوَصْلُ بَيْنَهُمَا"" : الصِّلَةُ. ""اِتَّصَلَ الْحَبْلُ وَانْعَقَدَ الوَصْلُ"". (التوحيدي). 2.""هَذَا وَصْلُ هَذَا"" : مِثْلُهُ. 3.""وَصْلُ العِظَامِ"" : مَفْصِلُهُ أَوْ مُجْتَمَعُهُ. 4.""هَمْزَةُ وَصْلٍ"" : ن. هَمْزَةُ الوَصْلِ. 5.""الوَصْلُ فِي القَافِيَةِ"" هُوَ:"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24123, 'وُصُولاَتٌ', 'وصولات', 'مصدر', '', 'وصولات', 'صلت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24124, 'وُصُولٌ', 'وصول', 'مصدر', 'وصل', 'وصول', 'صل', 'مص. وَصَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"وُصُولٌ-وُصُولٌ [و ص ل] (مص. وَصَلَ). 1.""يَتَرَقَّبُ وُصُولَ الضَّيْفِ"" : مَجِيئَهُ. 2.""حَالَ بَيْنَهُ وَبَيْنَ الوُصُولِ إِلَى هَدَفِهِ"" : البُلُوغُ. ""نَجَحَ فِي الوُصُولِ إِلَى مَقْصِدِهِ"". 3.حَدَّدُوا مَكَانَ الوُصُولِ"" : مُنْتَهَى السَّيْرِ. 4.""عِلْمٌ بِالوُصُولِ"" : وَثِيقَةُ إِخْبَارٍ أَوِ اعْتِمَادٍ أَوْ تَأْكِيدٍ بِاسْتِلاَمِ دَرَاهِمَ أَوْ وَثَائِقَ مِنْ شَخْصٍ أَوْ مُؤَسَّسَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24125, 'وَصْمٌ', 'وصم', 'مصدر', 'وصم', 'وصم', 'صم', ' مص. وَصَمَ', '', '', 'مفرد', 'DnN', '', '', '"وُصُومٌ"', '', 'R', '', '', '', '', '', '', '"( مص. وَصَمَ). ""عَيَّرَهُ بِالوَصْمِ"" : بِالعَارِ، بِالعَيْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24126, 'وُصُومٌ', 'وصوم', 'مصدر', '', 'وصوم', 'صم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24127, 'تَوْصِيَةٌ', 'توصية', 'مصدر', 'وصي', 'توصية', 'تصة', 'مص. وَصَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. وَصَّى). 1.""تَرَكَ لَهُ تَوْصِيَةً"" : العَهْدُ بِأمْرٍ وَتَكْلِيفُهُ بِهِ. 2. ""قَرَّرَ الْمُؤْتَمَرُ رَفْعَ تَوْصِيَةٍ إلَى السُّلُطَاتِ العُلْيَا"" : اِقْتِرَاحٌ فِي شَأْنِ قَضِيَّةٍ مَّا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24128, 'تَوْضِئَةٌ', 'توضئة', 'مصدر', 'وضأ', 'توضءة', 'تضة', 'مص. وَضَّأ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَوْضِئَةٌ-تَوْضِئَةٌ [و ض أ] (مص. وَضَّأ). ""تَوْضِئَةُ الطِّفْلِ"" : تَغْسِيلُهُ، تَنْظِيفُهُ، تَجْمِيلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24129, 'تَوْطِينٌ', 'توطين', 'مصدر', 'وطن', 'توطين', 'تطن', 'مص. وَطَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْطِينٌ-تَوْطِينٌ [و ط ن] (مص. وَطَّنَ). 1. ""تَوْطِينُ النَّفْسِ عَلَى الصَّبْرِ"" : حَمْلُهَا عَلَيْهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24130, 'وَضَحٌ', 'وضح', 'مصدر', 'وضح', 'وضح', 'ضح', 'مص. وَضِحَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْضَاحٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَضِحَ). 1.""وَصَلَ فِي وَضَحِ الصُّبْحِ"" : أَثْنَاءَ بَيَاضِ الصُّبْحِ. 2.""وَضَحُ الطَّرِيقِ"" : مَحَجَّتُهُ. 3.""سَرَقُوا الدَّارَ فِي وَضَحِ النَّهَارِ"" : ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24131, 'أَوْضَاحٌ', 'أوضاح', 'مصدر', '', 'ءوضاح', 'ضح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24132, 'تَوْضِيعٌ', 'توضيع', 'مصدر', 'وضع', 'توضيع', 'تضع', 'مص. وَضَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْضِيعٌ-تَوْضِيعٌ [و ض ع] (مص. وَضَّعَ). ""تَوْضِيعُ الأثَاثِ"" : وَضْعُهُ وَفْق نِظَامٍ خَاصٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24133, 'وَضْعٌ', 'وضع', 'مصدر', 'وضع', 'وضع', 'ضع', 'مص. وَضَعَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْضَاعٌ"', '', 'Rp', '', '', '', '', '', '', '"(مص. وَضَعَ). 1.""وَضْعُ اليَدِ عَلَى الْمُمْتَلَكَاتِ"" : الاسْتِيلاَءُ عَلَيْهَا. 2.""وَضْعُ الْمَرْأَةِ"" : وِلاَدَتُهَا. 3.""وَضْعُ الأَخْتَامِ عَلَى أَغْلِفَةِ أَسْئِلَةِ الامْتِحَانِ"" : أَيِ البَصْمُ عَلَيْهَا بِالشَّمْعِ الأَحْمَرِ لِكَيْ لاَ تُفْتَحَ إِلاَّ أَمَامَ الْمُمْتَحَنِينَ يَوْمَ الامْتِحَانِ. 4.""وَضْعُ الأَخْتَامِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24134, 'أَوْضَاعٌ', 'أوضاع', 'مصدر', '', 'ءوضاع', 'ضع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24135, 'ضَعَةٌ', 'ضعة', 'مصدر', 'وضع', 'ضعة', 'ضعة', 'مص. وَضَعَ، وَضُعَ، وَضِعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"ضَعَةٌ-ضَعَةٌ [و ض ع] (مص. وَضَعَ، وَضُعَ، وَضِعَ). ""في سُلوكِهِ ضَعَةٌ"" : اِنْحِطَاطٌ، لُؤْمٌ، خِسَّةٌ، دَنَاءةٌ. ""في حَسَبِهِ ضَعَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24136, 'تَوَطُّؤٌ', 'توطؤ', 'مصدر', 'وطأ', 'توطء', 'تط', 'مص. وَطَّأ', '', '', 'مفرد', 'Dz', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَوَطُّؤٌ-تَوَطُّؤٌ [و ط أ] (مص. وَطَّأ). ""تَوَطُّؤُ النَّبَاتِ بِالرِّجْلِ"": دَوْسُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24137, 'تَوْطِئَةٌ', 'توطئة', 'مصدر', 'وطأ', 'توطءة', 'تطة', 'مص. وطَّأ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَوْطِئَةٌ-تَوْطِئَةٌ [و ط أ] (مص. وطَّأ). ""قَرَأَ تَوْطِئَةَ الكِتَابِ أو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24138, 'تَوْطِيدٌ', 'توطيد', 'مصدر', 'وطد', 'توطيد', 'تطد', 'مص. وَطَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْطِيدٌ-تَوْطِيدٌ [و ط د] (مص. وَطَّدَ). ""يَسْعَى إلَى تَوْطِيدِ مَرْكَزِهِ"" : تَقْوِيَتِهِ، تَثْبِيتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24139, 'وَعْرٌ', 'وعر', 'مصدر', 'وعر', 'وعر', 'عر', 'مص. وَعَرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":أَوْعُرٌ:وُعُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَعَرَ). 1.""سُؤَالٌ وَعْرٌ"" : صَعْبٌ. ""مَطَالِبُهُ وَعْرَةُ التَّنْفِيذِ"" ""مَطْلَبٌ وَعْرٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24140, 'وَطْءٌ', 'وطء', 'مصدر', 'وطأ', 'وطء', 'ط', 'مص. وَطِئَ', '', '', 'مفرد', '', '', '', '', '', 'Rz', '', '', '', '', '', '', '"وَطْءٌ-وَطْءٌ [و ط أ] (مص. وَطِئَ). ""سَمِعَ وَطْءَ أَقْدَامِهِ مِنْ بَعِيدٍ"" : خَطْوَ أَقْدَامِهِ عَلَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24141, 'تَوْظِيفٌ', 'توظيف', 'مصدر', 'وظف', 'توظيف', 'تظف', 'مص. وَظَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْظِيفٌ-تَوْظِيفٌ [و ظ ف] (مص. وَظَّفَ).1. ""تَوْظِيفُ الْمَالِ فِي خِدْمَةِ التَّقَدُّمِ"" : تَشْغِيلُهُ اِسْتِثْمَارُهُ. ""تَوْظِيف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24142, 'وَعْثٌ', 'وعث', 'مصدر', 'وعث', 'وعث', 'عث', 'مص. وَعِثَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَعْثٌ-وَعْثٌ [و ع ث] (مص. وَعِثَ). 1.""طَرِيقٌ وَعْثٌ"" : وَعْرٌ، عَسِرٌ، صَعْبُ الْمَسَالِكِ. 2.""مَكَانٌ وَعْثٌ"" : سَهْلٌ، لَيِّنٌ تَغِيبُ فِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24143, 'مَوْعِدٌ', 'موعد', 'مصدر', 'وعد', 'موعد', 'معد', 'مص. وَعَدَ', '', '', 'مفرد', 'DnN', '', '', '"مَوَاعِدُ"', '', 'R', '', '', '', '', '', '', '"(مص. وَعَدَ). 1.""حَدَّدَ مَوْعِدَ الاجْتِمَاعِ عَلَى السَّاعَةِ العَاشِرَةِ"" : مَكَانُ الوَعْدِ وال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24144, 'مَوَاعِدُ', 'مواعد', 'مصدر', '', 'مواعد', 'معد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24145, 'وَعْدٌ', 'وعد', 'مصدر', 'وعد', 'وعد', 'عد', 'مص. وَعَدَ', '', '', 'مفرد', 'DnN', '', '', '"وُعُودٌ"', '', '', '', '', '', '', '', '', '"(مص. وَعَدَ). ""كَانَ وَعْدُهُ صَادِقاً"" : مَا قَطَعَهُ عَلَى نَفْسِهِ مِنْ عَهْدٍ. ""وَعْدُ الْحُرِّ دَيْنٌ عَلَيْهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24146, 'وُعُودٌ', 'وعود', 'مصدر', '', 'وعود', 'عد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
