INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24169, 'تَوْقِيتٌ', 'توقيت', 'مصدر', 'وقت', 'توقيت', 'تقت', 'مص. وَقَّتَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْقِيتٌ-تَوْقِيتٌ [و ق ت] (مص. وَقَّتَ). 1. ""تَوْقِيتُ العَمَلِ"": ضَبْطُهُ حَسَبَ أوْقَاتٍ مُعَيَّنَةٍ. 2. ""التَّوْقِيتُ الصَّيْفِيُّ"" : تَحْوِيلُ الوَقْتِ وَإِخْضاعُهُ إلَى سَاعَةٍ مُعَيَّنَةٍ مَعَ غُرُوبِ شَمْشِ الصَّيْفِ وَشُرُوقِهَا. 3. ""تَوْقِيتُ غِرِينِتْش"" : تَوْقِيتُ خَطِّ الزَّوَالِ (الظَّهِيرَة)، وَهُوَ خَطٌّ أصْلِيٌّ عَالَمِيٌّ يَمُرُّ فِي مُسْتَوى قَرْيَةِ غرِينتْش، الإنْجلِيزِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24170, 'وَفْرٌ', 'وفر', 'مصدر', 'وفر', 'وفر', 'فر', 'مص. وَفَرَ', '', '', 'مفرد', 'DnN', '', '', '"وُفُورٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَفَرَ). 1.""يَعِيشُ فِي وَفْرٍ"" : فِي غِنـىً. 2.""مَالٌ وَفْرٌ"" : كَثِيرٌ."', '');
