INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24176, 'وَقْبٌ', 'وقب', 'مصدر', 'وقب', 'وقب', 'قب', 'مص. وَقَبَ', '', '', 'مفرد', 'DnN', '', '', '"وِقَابٌ:وُقُوبٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَقَبَ). 1.""وَقْبُ الصَّخْرَةِ"" : نُقْرَتُهَا، أَيِ الْحُفْرَةُ الَّتِي يَجْتَمِعُ فِيهَا الْمَاءُ. 2.""و"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24177, 'وِقَابٌ', 'وقاب', 'مصدر', '', 'وقاب', 'قب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24178, 'وُقُوبٌ', 'وقوب', 'مصدر', '', 'وقوب', 'قب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24179, 'تَوْقِيعٌ', 'توقيع', 'مصدر', 'وقع', 'توقيع', 'تقع', 'مص. وَقَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":تَواقِيعُ"', '', 'R', '', '', '', '', '', '', '"(مص. وَقَّعَ). ""وَضَعَ تَوْقِيعَهُ عَلَى بِطَاقَتِهِ"" : إمْضَاءَهُ. ""سَلَّمَهُ شِيكاً بِلاَ تَوْقِيعٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24180, 'وَقْتٌ', 'وقت', 'مصدر', 'وقت', 'وقت', 'قت', 'مص. وَقَتَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْقَاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَقَتَ). 1. ""بَقِيَ وَقْتاً عِنْدَهُ"" : أَيْ مِقْدَاراً مِنَ الزَّمَنِ. 2.""جَاءَ فِي الوَقْتِ الْمُنَاسِبِ"" : فِي اللَّحْظَةِ الْمُنَاسِبَةِ. ""وَقْتٌ قَصِيرٌ"" ""مِنْ وَقْتِهَا"". 3.""وَقْتُ الغَدَاءِ"" : الغِذَاءُ، سَاعَتُهُ وَزَمَنُهُ الْمُحَدَّدُ. ""وَقْتُ الخُرُوجِ وَالدُّخُولِ"". 4.""فِي الوَقْتِ الْحَاضِرِ"" : فِي الأَيَّامِ الْحَاضِرَةِ الَّتِي نَعِيشُهَا، الزَّمَنُ الْحَاضِرُ. ""فِي وَقْتٍ لاَحِقٍ"" ""مَعَ الوَقْتِ سَتَعُودُ الْمِيَاهُ إِلَى مَجَارِيهَا"" ""مُنْذُ ذَلِكَ الوَقْتِ لَمْ أَعُدْ أَسْأَلْ عَنْهُ"". 5.""مِنْ وَقْتٍ إِلَى وَقْتٍ آخَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24181, 'أَوْقَاتٌ', 'أوقات', 'مصدر', '', 'ءوقات', 'قت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24182, 'وَقَاحَةٌ', 'وقاحة', 'مصدر', 'وقح', 'وقاحة', 'قحة', 'مص. وَقُحَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَقَاحَةٌ-وَقَاحَةٌ [و ق ح] (مص. وَقُحَ). ""اِسْتَغْرَبَ مِنْ وَقَاحَتِـهِ"" : مِنْ قِلَّةِ حَيَائِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24183, 'تَوْقِيدٌ', 'توقيد', 'مصدر', 'وقد', 'توقيد', 'تقد', 'مص. وَقَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْقِيدٌ-تَوْقِيدٌ [و ق د] (مص. وَقَّدَ). ""تَوْقِيدُ النَّارِ"" : إشْعَالُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24184, 'وَقْدٌ', 'وقد', 'مصدر', 'وقد', 'وقد', 'قد', 'مص. وَقَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَقْدٌ-وَقْدٌ [و ق د] (مص. وَقَدَ). ""أَشْعَلَ الوَقْدَ"" : النَّارَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24185, 'وُقُودٌ', 'وقود', 'مصدر', 'وقد', 'وقود', 'قد', 'مص. وَقَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وُقُودٌ-وُقُودٌ [و ق د] (مص. وَقَدَ). ""وُقُودُ النَّارِ"" : اِشْتِعَالُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24186, 'تَوْقِيرٌ', 'توقير', 'مصدر', 'وقر', 'توقير', 'تقر', 'مص. وَقَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْقِيرٌ-تَوْقِيرٌ [و ق ر] (مص. وَقَّرَ). 1. ""تَوْقِيرُ الرَّجُلِ"" : تَعْظِيمُهُ، تَبْجِيلُهُ، اِحْتِرَامُهُ. 2. ""سَاعَدَتِ المِحَنُ وَالمصَائِبُ فِي تَوْقِيرِهِ"" : فِي تَصْلِيبِهِ وَتَقْوِيَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24187, 'وَقَارٌ', 'وقار', 'مصدر', 'وقر', 'وقار', 'قر', 'مص. وَقُرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَقَارٌ-وَقَارٌ [و ق ر] (مص. وَقُرَ). ""عُرِفَ بِالوَقَارِ"" : بِالرَّزَانَةِ، بِالثَّبَاتِ، بِالْحِلْمِ.عَيَّرَتْنِي بِالشَّيْبِ وَهْـوَ وَقَـارٌ*لَيْتَهَا عَيَّـرَتْ بِمَا هُوَ عَـارٌ ""لاَ تَنْبِسُ بِكَلِمَةٍ، لاَ تَضْحَكُ، لاَ تَبْتَسِمُ، لاَ تَرْقُصُ، بَلْ تَحْتَفِظُ بِوَقَارِهَا"". (ع. العروي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24188, 'وَقْرٌ', 'وقر', 'مصدر', 'وقر', 'وقر', 'قر', 'مص. وَقَرَ، وَقِرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَقْرٌ-وَقْرٌ [و ق ر] (مص. وَقَرَ، وَقِرَ). ""وَقْرُ الأُذُنِ"" : ذَهَابُ سَمْعِهَا، ثِقَلُهَا، صَمَمُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24189, 'وُقُوفٌ', 'وقوف', 'مصدر', 'وقف', 'وقوف', 'قف', 'مص. وَقَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وُقُوفٌ-وُقُوفٌ [و ق ف] (مص. وَقَفَ). 1.""مَكَانُ وُقُوفِ السَّيَّارَاتِ"" : مَكَانُ تَوَقُّفِهَا. 2.""وُقُوفاً يَا رِجَالُ"" : قِيَام"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24190, 'تَواقِيعُ', 'تواقيع', 'مصدر', '', 'تواقيع', 'تقع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24191, 'مَوْقِعٌ', 'موقع', 'مصدر', 'وقع', 'موقع', 'مقع', 'مص. وَقَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَوَاقِعُ"', '', 'R', '', '', '', '', '', '', '"(مص. وَقَعَ). 1.""مَوْقِعُ القِتَالِ"" : مَوْضِعُ وُقُوعِ القِتَالِ. 2.""مَوْقِعُ الْمَاءِ"" : مَسَاقِطُهُ. 3.""وَقَعَ مَا وَقَعَ فِي مَوْقِعِهِ الْمُنَاسِبِ"" : فِي مَكَانِهِ، فِي مَوْضِعِهِ. 4.""تُوجَدُ الْمَدِينَةُ فِي مَوْقِعٍ طَبِيعِيٍّ جَمِيلٍ"" : فِي مَكَانٍ، مَوْضِعٍ، مَحَلٍّ، الجِهَةُ الَّتِي تَقَعُ فِيهَا. 5.""مَوْقِعٌ عَسْكَرِيٌّ"" : مَرْكَزٌ. 6.""شَارَكَ فِي الْمَوْقِعَةِ بِحَمَاسٍ وبُطُو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24192, 'مَوْقِعَةٌ', 'موقعة', 'مصدر', 'وقع', 'موقعة', 'مقعة', 'مص. وَقَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَوَاقِعُ"', '', 'R', '', '', '', '', '', '', '"(مص. وَقَعَ). 1.""مَوْقِعُ القِتَالِ"" : مَوْضِعُ وُقُوعِ القِتَالِ. 2.""مَوْقِعُ الْمَاءِ"" : مَسَاقِطُهُ. 3.""وَقَعَ مَا وَقَعَ فِي مَوْقِعِهِ الْمُنَاسِبِ"" : فِي مَكَانِهِ، فِي مَوْضِعِهِ. 4.""تُوجَدُ الْمَدِينَةُ فِي مَوْقِعٍ طَبِيعِيٍّ جَمِيلٍ"" : فِي مَكَانٍ، مَوْضِعٍ، مَحَلٍّ، الجِهَةُ الَّتِي تَقَعُ فِيهَا. 5.""مَوْقِعٌ عَسْكَرِيٌّ"" : مَرْكَزٌ. 6.""شَارَكَ فِي الْمَوْقِعَةِ بِحَمَاسٍ وبُطُو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24193, 'مَوَاقِعُ', 'مواقع', 'مصدر', '', 'مواقع', 'مقع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24194, 'وَقْعٌ', 'وقع', 'مصدر', 'وقع', 'وقع', 'قع', 'مص. وَقَعَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَقْعٌ-وَقْعٌ [و ق ع] (مص. وَقَعَ). 1.""سَمِعَ وَقْعَ أَقْدَامِهِ"" : أَيْ صَوْتَ مَشْيِهِ وَهُوَ يُحْدِثُ دَقَّاتٍ رَتِيبَةً. ""كَانَ وَقْعُ الْمَطَرِ يَصِلُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24195, 'وُقُوعٌ', 'وقوع', 'مصدر', 'وقع', 'وقوع', 'قع', 'مص. وَقَعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وُقُوعٌ-وُقُوعٌ [و ق ع] (مص. وَقَعَ). ""شَاهَدَ وُقُوعَ الْحَادِثِ"" : حُدُوثَهُ، حُصُولَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24196, 'تَوْقِيفٌ', 'توقيف', 'مصدر', 'وقف', 'توقيف', 'تقف', 'مص. وَقَّفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْقِيفٌ-تَوْقِيفٌ [و ق ف] (مص. وَقَّفَ). 1. ""تَوْقِيفُ العَمَلِ"": وَقْفُهُ فِي سَاعَةٍ مُعَيَّنَةٍ. 2. ""تَوْقِيفُ جَرِيدَةٍ"" : مَنْعهَا مِنَ الصُّدُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24197, 'وَقْفٌ', 'وقف', 'مصدر', 'وقف', 'وقف', 'قف', 'مص. وَقَفَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْقَافٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَقَفَ). 1.""جَعَلَ أَمْلاَكَهُ وَقْفاً عَلَى الأَعْمَالِ الْخَيْرِيَّةِ"" : حَبَسَهَا عَلَى مِلْكِ الوَاقِفِ أَوْ عَلَى مِلْكِ اللَّهِ وَالتَّصَدُّقِ بِالمَنْفَعَةِ، حَبَّسَها. ""وَقْفٌ عَامٌّ"" ""وَقْفٌ خَاصٌّ"" ""وِزَارَةُ الأَوْقَافِ"". 2.""تَقَرَّرَ وَقْفُ إِطْلاَقِ النَّارِ"" : عَدَمُ إِطْلاَقِ النَّارِ. 3.""مَعَ وَقْفِ التَّنْفِيذِ"" : أَيْ مَعَ عَدَمِ الدُّخُولِ فِي إِجْرَاءِ التَّنْفِيذِ. 4.""وَقْفُ الْجَلْسَةِ"" : تَعْلِيقُهَا. 5.""وَقْفُ جَرِيدَةٍ"" : مَنْعُهَا مِنَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24198, 'أَوْقَافٌ', 'أوقاف', 'مصدر', '', 'ءوقاف', 'قف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24199, 'تَوْقِيَةٌ', 'توقية', 'مصدر', 'وقي', 'توقية', 'تقة', 'مص. وَقَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَوْقِيَةٌ-تَوْقِيَةٌ [و ق ي] (مص. وَقَّى). ""سَاعَدَ عَلَى تَوْقِيَتِهِ مِنْ إصَابَةٍ مُحَقَّقَةٍ"" : عَلَى صِيَانَتِهِ وَحِمَايَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24200, 'وِقَايَةٌ', 'وقاية', 'مصدر', 'وقي', 'وقاية', 'قة', 'مص. وَقَى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. وَقَى). ""الوِقَايَةُ مِنَ الأَمْرَاضِ"" : الوَسَائِلُ الَّتِي تُتَّخَذُ لاتِّقَاءِ الأَمْرَاضِ. ""الوِقَايَةُ خَيْرٌ مِنَ العِلاَجِ"" ""دِرْهَمُ وِقَايَةٍ خَيْرٌ مِنْ قِنْطَارِ عِلاَجٍ"" (مثل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24201, 'تَوْكِيدٌ', 'توكيد', 'مصدر', 'وكد', 'توكيد', 'تكد', 'مص. وَكَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْكِيدٌ-تَوْكِيدٌ [و ك د] (مص. وَكَّدَ). 1. ""تَوْكِيدُ الأمْرِ"" : تَأكِيدُهُ، إحْكَامُهُ، تَوْثِيقُهُ. 2. ""التَّوْكِيدُ فِي النَّحْوِ"" : تَابِعٌ مِنَ التَّوَابِعِ يُقْصَدُ بِهِ أنَّ الْمَتْبُوعَ عَلَى ظَاهِرِهِ، وَهُوَ قِسْمَانِ : تَوْكِيدٌ لَفْظِيٌّ وَتَوْكِيدٌ مَعْنَوِيٌّ. أ. التَّوْكِيدُ اللَّفْظِيُّ هُوَ مَا يَكُونُ بِتَكْرَارِ اللَّفْظِ بِعَيْنِهِ :الفجر آية 21 إذَا دُكَّتِ الأرْضُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24202, 'وَكْدٌ', 'وكد', 'مصدر', 'وكد', 'وكد', 'كد', 'مص. وَكَدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَكْدٌ-وَكْدٌ [و ك د] (مص. وَكَدَ). ""عَبَّرَ عَنْ وَكْدِهِ"" : عَنْ مُرَادِهِ، عَنْ قَصْدِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24203, 'وَكْرٌ', 'وكر', 'مصدر', 'وكر', 'وكر', 'كر', 'مص. وَكَرَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْكَارٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَكَرَ). 1.""وَكْرُ الطَّائِرِ"" : عُشُّهُ. 2.""وَكْرُ الفَقِيرِ"" : مَقَرُّ سُكْنَاهُ، مَسْكَنُهُ. 3.""وَكْرُ اللُّصُوصِ"" : الْمَكَانُ الَّذِي يَخْتَبِئُونَ فِيهِ، مَخْبَؤُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24204, 'أَوْكَارٌ', 'أوكار', 'مصدر', '', 'ءوكار', 'كر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24205, 'وَكَفٌ', 'وكف', 'مصدر', 'وكف', 'وكف', 'كف', 'مص. وَكِفَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَكَفٌ-وَكَفٌ [و ك ف] (مص. وَكِفَ). ""وَكَفُ الْجَبَلِ"" : سَفْحُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24206, 'تَوْكِيلٌ', 'توكيل', 'مصدر', 'وكل', 'توكيل', 'تكل', 'مص. وَكَّلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْكِيلٌ-تَوْكِيلٌ[و ك ل] (مص. وَكَّلَ). 1. ""أعْطَاهُ تَوْكِيلاً"" : تَفْويضاً. 2. ""تَوْكِيلُ القاضِي عَلَى القَاصِر"" (فقه) : إقَامَتُهُ مَقَامَهُ فِي التَّصَرُّفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24207, 'توْلِيدٌ', 'توليد', 'مصدر', 'ولد', 'توليد', 'تلد', 'مص. وَلَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rp', '', '', '', '', '', '', '"توْلِيدٌ-توْلِيدٌ [و ل د] (مص. وَلَّدَ). 1.""تَوْلِيدُ المرْأةِ"" : جَعْلُهَا تَلِدُ. 2.""تَوْلِيدُ كَلِمَاتٍ جَدِيدَةٍ"" : اِشْتِقَاقُهَا. 3.""مَحَطَّةُ تَوْلِيدِ الكَهْرَبَاءِ"" : مَرْكَزُ إنْتَاجِ الطَّا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24208, 'مَوْلِدٌ', 'مولد', 'مصدر', 'ولد', 'مولد', 'ملد', 'مص. وَلَدَ', '', '', 'مفرد', 'DnN', '', '', '"مَوَالِدُ"', '', 'R', '', '', '', '', '', '', '"(مص. وَلَدَ). 1.""مَوْلِدُ الرَّجُلِ"" : مَوْضِعُ وِلاَدَتِهِ. 2.""فِي ذِكْرَى مَوْلِدِهِ"" : وَقْتُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24209, 'مَوَالِدُ', 'موالد', 'مصدر', '', 'موالد', 'ملد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24210, 'وِلاَدَةٌ', 'ولادة', 'مصدر', 'ولد', 'ولادة', 'لدة', 'مص. وَلَدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وِلاَدَةٌ-وِلاَدَةٌ [و ل د] (مص. وَلَدَ). ""وِلاَدَةُ طِفْلٍ"" : ظُهُورُهُ إِلَى"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24211, 'تَوْليعٌ', 'توليع', 'مصدر', 'ولع', 'توليع', 'تلع', 'مص. وَلَّعَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْليعٌ-تَوْليعٌ [و ل ع] (مص. وَلَّعَ). 1. التَّوْلِيعُ بِشَيْء"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24212, 'وَلِيفٌ', 'وليف', 'مصدر', 'ولف', 'وليف', 'لف', 'مص. وَلَفَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَلِيفٌ-وَلِيفٌ [و ل ف] (مص. وَلَفَ). ""ب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24213, 'تَوْلِيهٌ', 'توليه', 'مصدر', 'وله', 'توليه', 'تله', 'مص. وَلَّهَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْلِيهٌ-تَوْلِيهٌ [و ل هـ] (مص. وَلَّهَ). ""تَوْلِيهُ رَجُلٍ"" : إِيقَاعُهُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24214, 'وَلَهٌ', 'وله', 'مصدر', 'وله', 'وله', 'له', 'مص. وَلَهَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَلَهٌ-وَلَهٌ [و ل هـ] (مص. وَلَهَ). 1.""بِهِ وَلَهٌ"" : حُزْن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24215, 'وَلْوَلَةٌ', 'ولولة', 'مصدر', 'ولول', 'ولولة', 'للة', 'مص. وَلْوَلَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَلْوَلَةٌ-وَلْوَلَةٌ [و ل ول] (مص. وَلْوَلَ). ""وَلْوَلَةُ النِّسَاءِ"" : نُوَاحُهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24216, 'وَلاَيَةٌ', 'ولاية', 'مصدر', 'ولي', 'ولاية', 'لة', 'مص. وَلِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وَلاَيَةٌ-وَلاَيَةٌ [و ل ي] (مص. وَلِيَ). 1.""بَيْنَهُمْ وَلاَيَةٌ"" : قَرَابَةٌ. 2."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24217, 'وِلاَيَةٌ', 'ولاية', 'مصدر', 'ولي', 'ولاية', 'لة', 'مص. وَلِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"(مص. وَلِيَ). 1.""وِلاَيَةُ الْعَرْشِ"" : وِرَاثَةُ الْعَرْشِ الْمَلَكِيِّ. 2.""اِسْتَمَرَّتْ وِلاَيَتُهُ زَمَناً"" : حُكْمُهُ، سُلْطَتُهُ. 3.""عُيِّنَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24218, 'تَوْلِيَةٌ', 'تولية', 'مصدر', 'ولي', 'تولية', 'تلة', 'مص. وَلَّى', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَوْلِيَةٌ-تَوْلِيَةٌ [و ل ي] (مص. وَلَّى). 1. ""قَرَّرَ تَوْلِيتَهُ عَلَى الوِلاَيَةِ أوِ الإقْلِيمِ"" : جَعْلَهُ وَلِيّاً "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24219, 'تَوْهيدٌ', 'توهيد', 'مصدر', 'وهد', 'توهيد', 'تهد', 'مص. وَهَّدَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْهيدٌ-تَوْهيدٌ [و هـ د] (مص. وَهَّدَ). ""تَوْهيدُ الفِراشِ"" : تَمْهيدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24220, 'وَلْيٌ', 'ولي', 'مصدر', 'ولي', 'ولي', 'ل', 'مص. وَلَى، وَلِيَ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"وَلْيٌ-وَلْيٌ [و ل ي] (مص. وَلَى، وَلِيَ). ""دَارُهُ وَلْيُ دَارِي"": قَرِيبَةٌ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24221, 'تَوْمِئَةٌ', 'تومئة', 'مصدر', 'ومأ', 'تومءة', 'تمة', 'مص. وَمَّأَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'Rz', '', '', '', '', '', '', '"تَوْمِئَةٌ-تَوْمِئَةٌ [و م أ] (مص. وَمَّأَ). ""التَّوْمِئَةُ بِاليَدِ"" : الإِشارَةُ بِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24222, 'وَمَدٌ', 'ومد', 'مصدر', 'ومد', 'ومد', 'مد', 'مص. وَمِدَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَمَدٌ-وَمَدٌ [و م د] (مص. وَمِدَ). ""اِسْتَمَرَّ وَمَدُ اللَّيْلِ وَالنَّهَارِ"" : شِدَّةُ الْحَرِّ فِيهِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24223, 'وَمِيضٌ', 'وميض', 'مصدر', 'ومض', 'وميض', 'مض', 'مص. وَمَضَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَمِيضٌ-وَمِيضٌ [و م ض] (مص. وَمَضَ). ""تَأَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24224, 'وَنىً', 'ونى', 'مصدر', 'وني', 'ونى', 'ن', 'مص. وَنَى', '', '', 'مفرد', '', '', '', '', '', 'Rw', '', '', '', '', '', '', '"وَنـىً-وَنـىً [و ن ي] (مص. وَنَى). ""لاَ يُحِسّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24225, 'وَنِيٌّ', 'وني', 'مصدر', 'وني', 'وني', 'ن', 'مص. وَنَى، وَنِيَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"وَنِيٌّ-وَنِيٌّ [و ن ي] (مص. وَنَى، وَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24226, 'هِبَةٌ', 'هبة', 'مصدر', 'وهب', 'هبة', 'هبة', 'مص. وَهَبَ', '', '', 'مفرد', 'DnN', '', '', '"هِبَاتٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَهَبَ). 1.""قَدَّمَ لَهُ هِبَةً"" : عَطِيَّةً لاَيَرْجُو مِنْهَا عِوَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24227, 'هِبَاتٌ', 'هبات', 'مصدر', '', 'هبات', 'هبت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24228, 'وَهِيجٌ', 'وهيج', 'مصدر', 'وهج', 'وهيج', 'هج', 'مص. وَهَجَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"وَهِيجٌ-وَهِيجٌ [و هـ ج] (مص. وَهَجَ). 1.""سَارَ فِي وَهِيجِ النَّهَارِ"" : فِي حَرِّهِ. 2.""وَهِيجُ الطِّيبِ"" : اِنْتِشَارُهُ. 3.""وَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24229, 'يَبْسٌ', 'يبس', 'مصدر', 'يبس', 'يبس', 'بس', 'مص. يَبِسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يُبْسٌ-يُبْسٌ [ي ب س] (مص. يَبِسَ). 1.""حَطَبٌ يُبْسٌ"" : يَابِسٌ جَافٌّ بَعْدَمَا كَانَ رَطْباً. 2.""ش"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24230, 'وَهَلٌ', 'وهل', 'مصدر', 'وهل', 'وهل', 'هل', 'مص. وَهَلَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَهَلٌ-وَهَلٌ [و هـ ل] (مص. وَهَلَ). ""وَجَدَهُ فِي وَهَلٍ"" : فِي فَزَعٍ وَهَلَعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24231, 'تَوْهيمٌ', 'توهيم', 'مصدر', 'وهم', 'توهيم', 'تهم', 'مص. وَهَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْهيمٌ-تَوْهيمٌ [و هـ م] (مص. وَهَّمَ). ""قَصَدَ تَوْهيمَهُ"":إِيقاعَهُ في تَصَوُّرٍ غَيْرِ حَقيقِيٍّ، في وَهْمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24232, 'وَهْمٌ', 'وهم', 'مصدر', 'وهم', 'وهم', 'هم', 'مص. وَهَمَ', '', '', 'مفرد', 'DnN', '', '', '"أَوْهَامٌ"', '', 'R', '', '', '', '', '', '', '"(مص. وَهَمَ). 1.""يَعِيشُ فِي وَهْمٍ قَاتِلٍ"" : مَا يَقَعُ فِي الذِّهْنِ مِنْ تَصَوُّرٍ وَخَيَالٍ وَخَاطِرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24233, 'أَوْهَامٌ', 'أوهام', 'مصدر', '', 'ءوهام', 'هم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24234, 'تَوْهينٌ', 'توهين', 'مصدر', 'وهن', 'توهين', 'تهن', 'مص. وَهَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَوْهينٌ-تَوْهينٌ [و هـ ن ] (مص. وَهَّنَ). """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24235, 'وَهَنٌ', 'وهن', 'مصدر', 'وهن', 'وهن', 'هن', 'مص. وَهَنَ، وَهُنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَهَنٌ-وَهَنٌ [و هـ ن] (مص. وَهَنَ، وَهُنَ). ""أَصَابَهُ الوَهَنُ"": الضُّعْفُ، العَيَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24236, 'وَهْنٌ', 'وهن', 'مصدر', 'وهن', 'وهن', 'هن', 'مص. وَهَنَ، وَهُنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"وَهْنٌ-وَهْنٌ [و هـ ن] (مص. وَهَنَ، وَهُنَ). 1.""أَصَابَهُ الوَهْنُ"" : العَيَاءُ،"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24237, 'وَهْيٌ', 'وهي', 'مصدر', 'وهي', 'وهي', 'ه', 'مص. وَهَى، وَهِيَ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"وَهْيٌ-وَهْيٌ [و هـ ي] (مص. وَهَى، وَهِيَ). ""فِي الثَّوْبِ وَهْيٌ"" : تَمَزُّقٌ، تَلاَشٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24238, 'تَيْبيسٌ', 'تيبيس', 'مصدر', 'يبس', 'تيبيس', 'تبس', 'مص. يَبَّسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَيْبيسٌ-تَيْبيسٌ [ي ب س] (مص. يَبَّسَ). ""تَيْبِيسُ الثَّوْبِ"" : تَجْفيفُهُ وَجَعْلُهُ يابِساً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24239, 'يَقَنٌ', 'يقن', 'مصدر', 'يقن', 'يقن', 'قن', 'مص. يَقِنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يَقِنٌ-يَقِنٌ [ي ق ن] (صِيغَةُ فَعِل). 1.""رَجُلُ يَقِنٌ"" : الَّذِي لاَ يَسْمَعُ شَيْئاً إِلاَّ أَيْقَنَ بِهِ. 2.""يَقِنٌ بِالْمُوسِيقَى"": مُولَعٌ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24240, 'يُبْسٌ', 'يبس', 'مصدر', 'يبس', 'يبس', 'بس', 'مص. يَبِسَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يَبْسٌ-يَبْسٌ [ي ب س] (مص. يَبِسَ). 1.""نَبْتٌ يَبْسٌ"" : يَابِسٌ، جَافٌّ. 2.""رَجُلٌ يَبْسٌ"" : لاَ خَيْرَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24241, 'يُبُوسَةٌ', 'يبوسة', 'مصدر', 'يبس', 'يبوسة', 'بسة', 'مص. يَبِسَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"يُبُوسَةٌ-يُبُوسَةٌ [ي ب س] (مص. يَبِسَ). ""يُبُوسَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24242, 'تَيْتِيمٌ', 'تيتيم', 'مصدر', 'يتم', 'تيتيم', 'تتم', 'مص. يَتَّمَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَيْتِيمٌ-تَيْتِيمٌ [ي ت م] (مص. يَتَّمَ). ""تَيْتِيمُ الوَلَدِ"" : تَصْيِيرُهُ يَتيماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24243, 'يَتَمٌ', 'يتم', 'مصدر', 'يتم', 'يتم', 'تم', 'مص. يَتِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يُتْمٌ-يُتْمٌ [ي ت م] (مص. يَتَمَ، يَتِمَ، يَتُمَ). ""عَاشَ فِي يُتْمٍ مُنْذُ صِغَرِهِ"" : فُقْدَانُ أَحَدِ الْوَالِدَيْنِ، أَيْ وَفَاةُ أَحَدِهِما."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24244, 'يَتْمٌ', 'يتم', 'مصدر', 'يتم', 'يتم', 'تم', 'مص. يَتَمَ، يَتِمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يَتْمٌ-يَتْمٌ [ي ت م] (مص. يَتَمَ، يَتِمَ). ""بِهِ يَتْمٌ"" : هَمٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24245, 'يُتْمٌ', 'يتم', 'مصدر', 'يتم', 'يتم', 'تم', 'مص. يَتَمَ، يَتِمَ، يَتُمَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يَتَمٌ-يَتَمٌ [ي ت م] (مص. يَتِمَ). 1.""يَتَمُ الْوَلَدِ"" : فُقْدَانُ الأَبِ. 2.""يَتَمُ الْحَيَوَانِ"" : فُقْدَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24246, 'يَتْنٌ', 'يتن', 'مصدر', 'يتن', 'يتن', 'تن', 'مص. يَتَنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يَتْنٌ-يَتْنٌ [ي ت ن] (مص. يَتَنَ). ""وَلَدٌ يَتْنٌ"" : وَضَعَتْهُ أُمُّهُ مَعْكوساً، أَي خُرُوجُ رِجْلَيْهِ قَبْلَ رَأْسِهِ وَيَدَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24247, 'تَيْسيرٌ', 'تيسير', 'مصدر', 'يسر', 'تيسير', 'تسر', 'مص. يَسَّرَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَيْسيرٌ-تَيْسيرٌ [ي س ر] (مص. يَسَّرَ). 1.""تَيْسيرُ السُّؤالِ"": تَسْهيلُهُ. 2.""تَيْسيرُ سُبُلِ النَّجاحِ"" : تَهْيِئَتُها، إِعْدادُها. 3.""التَّيْسيرُ مِنَ اللَّهِ"" :التَّوفيقُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24248, 'يُسْرٌ', 'يسر', 'مصدر', 'يسر', 'يسر', 'سر', 'مص. يَسُرَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يُسْرٌ-يُسْرٌ [ي س ر] (مص. يَسُرَ). 1.""عَاشَ فِي يُسْرٍ"" : فِي بَحْبُوحَةِ عَيْشٍ، فِي رَغَدٍ وَغِنـىً وَسَعَةٍ. 2.""يَشْتَغِلُ بِيُسْـرٍ"" : بِلُطْفٍ، بِلا تَعَبٍ وَلاَ مَشَقَّةٍ. ""حَمَلَهَا بَيْنَ ذِرَاعَيْهِ بِيُسْرٍ"". 3.""عَرَفَ يُسْراً بَعْدَ عُسْرٍ"" : اِنْفِرَاجاً، فَرَجاً.‎الشرح آية 6إنَّ مَعَ الْعُسْرِ يُسْراً (قرآن). 4.""وَلاَ أَعْلَمُ فِي الأَرْضِ أَعَمَّ إِفْلاَساً وَلاَ أَشَدَّ نَكْبَةً وَلاَ أَكْثَرَ تَحَوُّلاً مِنْ يُسْرٍ إِلَى عُسْرٍ"". (الجاحظ)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24249, 'يَقِينٌ', 'يقين', 'مصدر', 'يقن', 'يقين', 'قن', 'مص. يَقِنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"يَقِينٌ-يَقِينٌ [ي ق ن] (مص. يَقِنَ). 1.""هُوَ عَلَى يَقِينٍ بِمَا سَيَحْصُلُ"" : عَالِمٌ بِهِ حَقَّ الْعِلْمِ عَنْ نَظَرٍ وَاسْتِدْلاَلٍ. ""يُصَدِّقُ الظَّنَّ فَيَجْعَلُهُ يَقِيناً"". 2.""عِلْمٌ يَقِينٌ"" : لَيْسَ فِيهِ شَكٌّ، ثَابِتٌ. ""كُنْتُ أَقْطَعُ الشَّكَّ بِالْيَقِينِ وَالتَّرَدُّدَ بِالثَّبَاتِ"".(جمال الغيطاني). 3.""الْيَقِينُ فِي الْفَلْسَفَةِ"" : اِطْمِئْنَانُ النَّفْسِ إِلَى حُكْمٍ، الاعْتِقَادُ بِصِحَّتِهِ. 4.""كُنْ عَلَى يَقِينٍ أَنَّ الأَمْرَ كَمَا وَصَفْتُ لَكَ"" : كُنْ مُتَأَكِّداً. ""كَانُوا عَلَى يَقِينٍ تَامٍّ مِنْ فَوْزِهِ"". 5.""يَقِيناً سَأُحَقِّقُ نَصْراً"" : أَكِيداً، بِلا شَكٍّ. 6.""حَقُّ الْيَقِينِ"" : خَالِصُهُ وَوَاضِحُهُ. 7.الحجر آية 99 وَاُعْبُدْ رَبَّكَ حَتَّى يَأْتِيَكَ الْيَقِين (قرآن) : الْمَوْتُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24250, 'تَيْمينٌ', 'تيمين', 'مصدر', 'يمن', 'تيمين', 'تمن', 'مص. يَمَّنَ', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', 'R', '', '', '', '', '', '', '"تَيْمينٌ-تَيْمينٌ [ي م ن] (مص. يَمَّنَ). 1.""تَيْمينُ السَّائِرِ"" : سَيْرُهُ ذاتَ اليَمينِ. 2.""التَّيْمينُ بِالأعْمَى"" : الذَّهابُ بِهِ ذاتَ اليَمينِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24251, 'مَيْمَنَةٌ', 'ميمنة', 'مصدر', 'يمن', 'ميمنة', 'ممنة', 'مص. يَمُنَ', '', '', 'مفرد', 'DnN', '', '', '"مَيَامِينُ"', '', 'R', '', '', '', '', '', '', '"(مص. يَمُنَ). 1.""مَيْمَنَةُ الصُّفُوفِ"" : مَا كَانَ جِهَةَ اليَمِينِ خِلاَفَ الْمَيْسَرَةِ. ""مَيْمَنَةُ الْجَيْشِ"". 2.البلد آية 18 أُولَئِكَ أَصْحَابُ الْمَيْمَنَةِ (قرآن) : أَصْحَابُ البَرَكَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24252, 'مَيَامِينُ', 'ميامين', 'مصدر', '', 'ميامين', 'ممن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24253, 'يُمْنٌ', 'يمن', 'مصدر', 'يمن', 'يمن', 'من', 'مص. يمَنَ، يَمُنَ', '', '', 'مفرد', '', '', '', '', '', 'R', '', '', '', '', '', '', '"يُمْنٌ-يُمْنٌ [ي م ن] (مص. يمَنَ، يَمُنَ). 1.""كَانَ مِيلاَدُهُ يُمْناً عَلَى وَالِدَيْهِ"" : مُبَارَكاً سَعِيداً. 2.""لَمْ يَرَ إِلاَّ الْيُمْنَ فِي تِجَارَتِهِ"": إِلاَّ الْبَرَكَةَ وَالْخَيْرَ. 3.""كَانَ رَسُولَ يُمْنٍ لِقَوْمِهِ"" : أَيْ رَسُولَ خَيْرٍ، مَيْمُوناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24254, 'مفرد/تكسير', 'مفرد/تكسير', 'صيغة مبالغة', '', 'مفرد/تكسير', 'مفرد/تكسر', '', 'س', 'التأنيث', 'جمع تكسير', 'التثنية', 'مؤ', '"ج', 'لف', '', '"ج', 'س', 'نسب', 'المنقوص', '"تنوين النصب"', '"', 'مذ', 'ك', ':لا جذر:لا مفرد:لا تشكيل');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24255, 'أكَّارٌ', 'أكار', 'صيغة مبالغة', 'أكر', 'ءكار', 'كر', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَكَرَةٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '".: الحَرَّاثُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24256, 'أَكَرَةٌ', 'أكرة', 'صيغة مبالغة', '', 'ءكرة', 'كرة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24257, 'عَسَّالٌ', 'عسال', 'صيغة مبالغة', 'عسل', 'عسال', 'عسل', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"عَسَّالَةٌ-عَسَّالَةٌ [ع س ل] 1. : خَلِيَّةُ النَّحْلِ. 2. : الَّذِينَ يَسْتَخْرِجُونَ العَسَلَ مِنْ مَوَاضِعِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24258, 'رَحَّالَةٌ', 'رحالة', 'صيغة مبالغة', 'رحل', 'رحالة', 'رحلة', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"رَحَّالَةٌ-رَحَّالَةٌ [ر ح ل]. 1.""كَانَ رَحَّالَةَ عَصْرِهِ"" : كَثيرُ الرِّحَالِ، التَّرْحَالِ. 2.""اللَّقَالِقُ مِنَ الطُّيُورِ الرَّحَّالَةِ"" : مِنَ الطُّيُورِ الَّتِي تَنْتَقِلُ فِي مَوَاسِمَ مَعْلُومَةٍ مِن بَلَدٍ إلَى آخَرَ، الْمُهَاجِرَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24259, 'زَجَّالٌ', 'زجال', 'صيغة مبالغة', 'زجل', 'زجال', 'زجل', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"زَجَّالٌ-زَجَّالٌ[ز ج ل]. 1. : الشَّاعِرُ الَّذِي يَكْتُبُ قَصائِدَ شِعْرِيَّةً بِاللُّغَةِ العامِّيَّةِ، الشَّعْبِيَّةِ. 2.""حَمامٌ زَجَّالٌ"" : زَاجِلٌ، حَمامٌ يُرْسَلُ بِالرَّسائِلِ عَلَى بُعْدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24260, 'بَحَّارٌ', 'بحار', 'صيغة مبالغة', 'بحر', 'بحار', 'بحر', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":بَحَّارَةٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". 1.""بَحَّارٌعَرفَ كُلَّ الْمَوانِئ"" : مَلاَّحٌ، مِنْ رِجَالِ البَحْرِ. 2.""رَسَتِ السَّفِينَةُ، فامْتَلأَ المِينَاءُ بِالبَحَّارَةِ"" : طاقَمُ السَّفِينَةِ وَرِجالُ البَحْريَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24261, 'بَحَّارَةٌ', 'بحارة', 'صيغة مبالغة', '', 'بحارة', 'بحرة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24262, 'جَبَّارٌ', 'جبار', 'صيغة مبالغة', 'جبر', 'جبار', 'جبر', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":جَبَابِرَةٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". 1.""كَانَ جَبَّاراً عَاتِياً"": مُتَسَلِّطاً، ظَالِماً، مُتَعَجْرِفاً، قَاسِياً، قَاهِراً. ""عَرَفَهُ التَّارِيخُ مِنَ الجَبَابِرَةِ العُتَاةِ"". 2. ""قَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24263, 'جَبَابِرَةٌ', 'جبابرة', 'صيغة مبالغة', '', 'جبابرة', 'جببرة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24264, 'مَسَّاحٌ', 'مساح', 'صيغة مبالغة', 'مسح', 'مساح', 'مسح', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"مَسَّاحَةٌ-مَسَّاحَةٌ [م س ح]. ""مَسَّاحَةُ الزُّجَاجِ"" : قَضِيبٌ فِـي طَرَفِهِ جِلْدٌ مَطَّاطٌ يَكُونُ مُلْتَصِقاً بِأَعْلَى الزُّجَاجِ الأَمَامِيِّ لِلسَّيَّارَةِ، يَتَحَرَّكُ آلِيّاً لِتَنْظِيفِهِ وَقْتَ الْمَطَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24265, 'كَوَّاءٌ', 'كواء', 'صيغة مبالغة', 'كوي', 'كواء', 'ك', '', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"كَوَّاءٌ-كَوَّاءٌ [ك و ي]. : مَنْ يَكْوِي الْمَلاَبِسَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24266, 'كَوَّاءة', 'كواءة', 'صيغة مبالغة', '', 'كواءة', 'كة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24267, 'كَمَّاءٌ', 'كماء', 'صيغة مبالغة', 'كمأ', 'كماء', 'كم', '', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"كَمَّاءٌ-كَمَّاءٌ [ك م أ]. : بَائِعُ الكَمْأَةِ أَوْ مَنْ يَجْنِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24268, 'كَمَّاءة', 'كماءة', 'صيغة مبالغة', '', 'كماءة', 'كمة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24269, 'كَشَّافٌ', 'كشاف', 'صيغة مبالغة', 'كشف', 'كشاف', 'كشف', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". 1.""شَيْخٌ كَشَّافٌ"" : كَثِيرُ الكَشْفِ. 2.""وَلَدٌ كَشَّافٌ"" : الْمُنْضَوِي تَحْتَ لِوَاءِ الكَشْفِيَّة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24270, 'فَوَّالٌ', 'فوال', 'صيغة مبالغة', 'فول', 'فوال', 'فل', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"فَوَّالٌ-فَوَّالٌ [ف و ل]. : طَابِخُ الْفُولِ وَبَائِعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24271, 'فَحَّامٌ', 'فحام', 'صيغة مبالغة', 'فحم', 'فحام', 'فحم', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"فَحَّامٌ-فَحَّامٌ [ف ح م]. : صَانِعُ، بَائِعُ الْفَحْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24272, 'عَوَّادٌ', 'عواد', 'صيغة مبالغة', 'عود', 'عواد', 'عد', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"عَوَّادٌ-عَوَّادٌ [ع و د]. 1. : الْمُوسِيقِيُّ الَّذِي يَنْقُرُ عَلَى الْعُودِ. 2. : صَانِعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24273, 'عَقَّارٌ', 'عقار', 'صيغة مبالغة', 'عقر', 'عقار', 'عقر', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"ـو:عَقَاقِيرُ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". 1. : مُبَالَغَةُ عَاقِرٍ. 2.""عَقَاقِيرُ الصَّيْدَلِيَّةِ"" : الأَدْوِيَةُ مُطْلَقاً، مَا يُتَدَاوَى بِهِ مِنَ الأَعْشَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24274, 'عَسَّالٌ', 'عسال', 'صيغة مبالغة', 'عسل', 'عسال', 'عسل', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"عَسَّالٌ-عَسَّالٌ [ع س ل]. : مُسْتَخْرِجُ العَسَلِ، بَائِعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24275, 'عَرَّافٌ', 'عراف', 'صيغة مبالغة', 'عرف', 'عراف', 'عرف', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"عَرَّافٌ-عَرَّافٌ [ع ر ف]. ""رَجُلٌ عَرَّافٌ"" : الْمُنَجِّمُ، مَنْ يُخْبِرُ وَيَتَنَبَّأُ بِالْمُسْتَقْبَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24276, 'طَيَّانٌ', 'طيان', 'صيغة مبالغة', 'طين', 'طيان', 'طن', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"طَيَّانٌ-طَيَّانٌ [ط ي ن]. ""يَشْتَغِلُ طَيَّاناً مَعَ البَنَّائِينَ فِي الأَحْيَاءِ الشَّعْبِيَّةِ"" : مَنْ يَشْتَغِلُ بِالطِّينِ يَصْنَعُ مِنْهُ العَجِينَ أَوْ يَطْلِي بِهِ الْجُدْرَانَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24277, 'كَنَّاسٌ', 'كناس', 'صيغة مبالغة', 'كنس', 'كناس', 'كنس', 'صِيغَة فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"كَنَّاسٌ - [ك ن س]. : مَنْ حِرْفَتُهُ الكَنْسُ. "', '');
