INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24280, 'ذَبَّاحٌ', 'ذباح', 'صيغة مبالغة', 'ذبح', 'ذباح', 'ذبح', 'صِيغَة فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"ذَبَّاحٌ-ذَبَّاحٌ، ذُبَّاحٌ [ذ ب ح]. ""أُصيبَ بِذُبَّاحٍ"" : اِلْتِهاب في الحَلْقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24281, 'دَبَّاسٌ', 'دباس', 'صيغة مبالغة', 'دبس', 'دباس', 'دبس', 'صِيغَة فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"دَبَّاسٌ-دَبَّاسٌ [د ب س].: صَانِعُ الدَّبْسِ وَبَائِعُهُ."', '');
