INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24284, 'خَلاَّلٌ', 'خلال', 'صيغة مبالغة', 'خلل', 'خلال', 'خلل', 'صِيغَة فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَلاَّلٌ-خَلاَّلٌ [خ ل ل]. ""يُوجَدُ خَلاَّلٌ وَحِيدٌ فِي السُّوقِ"" : بَائِعُ الخَلِّ وَصَانِعُهُ."', '');
