INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24286, 'حَجَّارٌ', 'حجار', 'صيغة مبالغة', 'حجر', 'حجار', 'حجر', 'صِيغَة فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"حَجَّارٌ-حَجَّارٌ [ح ج ر].""عامِلٌ حَجَّارٌ"" : عامِلٌ في الحِجارَةِ."', '');
