INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24289, 'جَبَّانٌ', 'جبان', 'صيغة مبالغة', 'جبن', 'جبان', 'جبن', 'صِيغَة فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"جَبَّانٌ-جَبَّانٌ [ج ب ن]. ""وَقَفَ الجَبَّانُ يَبِيعُ جُبْنَهُ ل"', '');
