INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24295, 'بَزَّازٌ', 'بزاز', 'صيغة مبالغة', 'بزز', 'بزاز', 'بزز', 'صِيغَة فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"بَزَّازٌ - [ب ز ز]. ""كانَ والِدُهُ بَزَّازاً لَهُ مَعْرِفَةٌ دَقِيقَةٌ بِالثِّيابِ وَألْوانِها"" : مَنْ يَتَّجِرُ في الثِّيابِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24296, 'بَزَّارٌ', 'بزار', 'صيغة مبالغة', 'بزر', 'بزار', 'بزر', 'صِيغَة فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"بَزَّارٌ-بَزَّارٌ [ب ز ر]. ""بَزَّارُ الحَيِّ"" : مَنْ يَبيعُ القَمْحَ والذُّرَةَ والأُرْزَ والعَدَسَ والأبازِيرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24297, 'بَرّامٌ', 'برام', 'صيغة مبالغة', 'برم', 'برام', 'برم', 'صِيغَة فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24298, 'بَذَّارٌ', 'بذار', 'صيغة مبالغة', 'بذر', 'بذار', 'بذر', 'صِيغَة فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '', ':لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24299, 'جَرَّارٌ', 'جرار', 'صيغة مبالغة', 'جرر', 'جرار', 'جرر', 'صِيغَة فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"جَرَّارٌ-جَرَّارٌ [ج ر ر] (صف). ""اِنْتَشَرَ جَيْشٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24300, 'صَقَّالٌ', 'صقال', 'صيغة مبالغة', 'صقل', 'صقال', 'صقل', 'صِيغَة فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"صَقَّالٌ-صَقَّالٌ [ص ق ل] (صِيغَة فَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24301, 'طَرَّازٌ', 'طراز', 'صيغة مبالغة', 'طرز', 'طراز', 'طرز', 'صِيغَة فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"طَرَّازٌ-طَرَّازٌ، ةٌ [ط ر ز] (صِيغَة فَعَّال). ""إِنَّهَا الطَّرَّازَةُ الأُولَى بِالْمَدِينَةِ"" : مَنْ تُطَرِّزُ الثِّيَابَ بِخُيُوطٍ حَرِيرِيَّةٍ أَوْ غَيْرِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24302, 'قَمَّاشٌ', 'قماش', 'صيغة مبالغة', 'قمش', 'قماش', 'قمش', 'صِيغَة فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"قَمَّاشٌ-قَمَّاشٌ [ق م ش] (صِيغَة فَعَّال). 1. : بَائِعُ القُمَاشِ. 2. : بَائِعُ الأَقْمِشَةِ وَالأَمْتِعَةِ الْمُسْتَعْمَلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24303, 'جَعَّابٌ', 'جعاب', 'صيغة مبالغة', 'جعب', 'جعاب', 'جعب', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"جَعَّابٌ-جَعَّابٌ [ج ع ب] (صِيغَةُ فَعَّال).: صَانِعُ الجِعَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24304, 'حَرَّارٌ', 'حرار', 'صيغة مبالغة', 'حرر', 'حرار', 'حرر', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"حَرَّارٌ-حَرَّارٌ [ح ر ر] (صِيغَةُ فَعَّال).: بائِعُ الحَريرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24305, 'حَفَّارٌ', 'حفار', 'صيغة مبالغة', 'حفر', 'حفار', 'حفر', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"حَفَّارٌ-حَفَّارٌ [ح ف ر] (صِيغَةُ فَعَّال). ""حَفَّارُ القُبُورِ"" : مَنْ يَحْفِرُها. ""لَمَّا تَوَارَى حَفَّارُ القُبُورِ، اِرْتَمَيْتُ عَلَى قَبْرِ سَلْمَى أُعَزِّيهَا"" (جبران خ. جبران)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24306, 'حَلاَّجٌ', 'حلاج', 'صيغة مبالغة', 'حلج', 'حلاج', 'حلج', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"حَلاَّجٌ-حَلاَّجٌ [ح ل ج] (صِيغَةُ فَعَّال). 1. ""ذَهَبَتْ بِقُطْنِها عِنْدَ الحَلاَّجِ"" : مَنْ يَنْدِفُهُ ويُنَظِّفُهُ وَيُخَلِّصُهُ مِنْ بَذْرِهِ. 2.""الحَلاَّجُ"" : اِسْمُ عَلَمٍ لأَحَدِ الْمُتَصَوِّفَةِ فِي العَصْرِ العَبَّاسِيِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24307, 'خَرَّازٌ', 'خراز', 'صيغة مبالغة', 'خرز', 'خراز', 'خرز', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال).: صَانِعُ الْخَرَزِ أوِ خَيَّاطُ الْجِلْدِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24308, 'خَزَّافٌ', 'خزاف', 'صيغة مبالغة', 'خزف', 'خزاف', 'خزف', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"ج: ـون. (صِيغَةُ فَعَّال). ""خَزَّافٌ مَاهرٌ"" : صَانِعُ الْخَزَفِ، أَي الأَوَانِي الْمَصْنُوعَةُ مِنَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24309, 'خَضَّارٌ', 'خضار', 'صيغة مبالغة', 'خضر', 'خضار', 'خضر', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَضَّارٌ-خَضَّارٌ [خ ض ر] (صِيغَةُ فَعَّال). ""اِشْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24310, 'خَيَّاطٌ', 'خياط', 'صيغة مبالغة', 'خيط', 'خياط', 'خط', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَيَّاطٌ-خَيَّاطٌ، ةٌ [خ ي ط] (صِيغَةُ فَعَّال). ""طَلَبَ مِنَ الخَيَّاطِ أَنْ يَخِيطَ لَهُ كِسْوَةٌ"" : صَانِعُ الْمَلاَبِسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24311, 'دَبَّاغٌ', 'دباغ', 'صيغة مبالغة', 'دبغ', 'دباغ', 'دبغ', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"دِبَاغٌ-دِبَاغٌ [د ب غ] (مص. دَبَغَ). ""دِبَاغُ الجِلْدِ"" : مَا يُدْبَغُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24312, 'دَرَّاسٌ', 'دراس', 'صيغة مبالغة', 'درس', 'دراس', 'درس', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال). ""لَمْ أكُنْ أرَى إلاَّ الدَّرَّاسِينَ فِي حَرِّ الصَّيْفِ"" : مَنْ يَدْرُسُ سَنَابِلَ القَمْحِ، أوِ الذُّرَةِ، أوْ مَا شَابَهَ ذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24313, 'دَلاَّكٌ', 'دلاك', 'صيغة مبالغة', 'دلك', 'دلاك', 'دلك', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"دَلاَّكٌ-دَلاَّكٌ [د ل ك] (صِيغَةُ فَعَّال). ""دَلَكَهُ الدَّلاَّكُ في الحَمَّامِ"" : من يَحُكُّ جِسْمَ الْمُسْتَحِمِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24314, 'دَلاَّلٌ', 'دلال', 'صيغة مبالغة', 'دلل', 'دلال', 'دلل', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"دَلالٌ-دَلالٌ [د ل ل] (مص. دَلَّ). ""أَظْهَرَتْ دَلالاً مَا بَعْدَهُ مِنْ دَلالٍ"" : أَظْهَرَتْ تَغَنُّجاً، تَأَنُّقاً، غُنْجاً في حَرَكاتِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24315, 'دَمَّانٌ', 'دمان', 'صيغة مبالغة', 'دمن', 'دمان', 'دمن', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"دَمَّانٌ-دَمَّانٌ [د م ن] (صِيغَةُ فَعَّال). : الَّذِي يُسَمِّدُ الأَرْضَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24316, 'ذَبَّانٌ', 'ذبان', 'صيغة مبالغة', 'ذبن', 'ذبان', 'ذبن', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ذَبَّانٌ-ذَبَّانٌ، ةٌ [ذ ب ن] (صِيغَةُ فَعَّال). ""شَفَةٌ ذَبَّانَةٌ"" : ذابِلَةٌ مِنْ عَطَشٍ أَوْ غَيْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24317, 'رَصَّاصٌ', 'رصاص', 'صيغة مبالغة', 'رصص', 'رصاص', 'رصص', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال). : مَنْ يَعْمَلُ الرَّصاصَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24318, 'زَبَّالٌ', 'زبال', 'صيغة مبالغة', 'زبل', 'زبال', 'زبل', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"زَبَّالٌ-زَبَّالٌ[ز ب ل] (صِيغَةُ فَعَّال). : مَنْ يَجْمَعُ النُّفاياتِ وَفَضَلاتِ الطَّعامِ والأَزْبالَ مِنَ الشَّوارِعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24319, 'زَجَّاجٌ', 'زجاج', 'صيغة مبالغة', 'زجج', 'زجاج', 'زجج', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"زُجاجٌ-زُجاجٌ[ز ج ج]. 1.""كَسَرَ زُجاجَ النَّافِذَةِ"" : جِسْمٌ شَفَّافٌ يُصْنَعُ مِنَ الرَّمْلِ الْمَخْلوطِ بِالكِلْسِ وَمَوادَّ كيماوِيَّةٍ مِثْلِ كارْبوناتِ الصُّودِيُومِ أَوِ البُوتَاسْيومِ، صَلْبٌ وَسَهْلُ الكَسْرِ، تُصْنَعُ مِنْهُ الأَوانِي الزُّجاجِيَّةُ وَغَيْرُ ذَلِكَ. 2.""كُؤُوسٌ مِنْ زُجاجِ البِلَّوْرِ"": زُجاجٌ أَكْثَرُ شَفافِيَّةً، ناصِعُ البَياضِ. 3.""مَنْ يَسْكُنْ بَيْتاً مِنْ زُجاجٍ لا يَرْمِ النَّاسَ بِحَجَرٍ"" : مَنْ كانَ ضَعيفاً لاَ يَقْوَى على الْمُواجَهَةِ لا يَرْمِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24320, 'زَمَّارٌ', 'زمار', 'صيغة مبالغة', 'زمر', 'زمار', 'زمر', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"زَمَّارٌ-زَمَّارٌ[ز م ر] (صِيغَةُ فَعَّال). ""زَمَّارُ الْحَيِّ"" : مَنْ يُغَنِّي بِالمِزْمارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24321, 'زَهَّارٌ', 'زهار', 'صيغة مبالغة', 'زهر', 'زهار', 'زهر', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال). : بائِعُ الزُّهورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24322, 'زَيَّاتٌ', 'زيات', 'صيغة مبالغة', 'زيت', 'زيات', 'زت', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال). 1. : بائِعُ الزَّيْتِ. 2. : عاصِرُ الزَّيْتِ. 3. : مَنْ يَمْلِكُ مَعاصِرَ لِعَصْرِ الزَّيْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24323, 'سَلاَّلٌ', 'سلال', 'صيغة مبالغة', 'سلل', 'سلال', 'سلل', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"سَلاَّلٌ-سَلاَّلٌ [س ل ل] (صِيغَةُ فَعَّال). ""اِشْتَرى"', '');
