INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24325, 'سَوَّاقٌ', 'سواق', 'صيغة مبالغة', 'سوق', 'سواق', 'سق', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"سَوَّاقٌ-سَوَّاقٌ [س و ق] (صِيغَةُ فَعَّال). ""سَوَّاقٌ ماهِرٌ"" : سائِقُ سَيَّارَةٍ أَوْ قِطارٍ وَغَيْرِهِمَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24326, 'صَوَّافٌ', 'صواف', 'صيغة مبالغة', 'صوف', 'صواف', 'صف', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"صَوَّافٌ-صَوَّافٌ [ص و ف] (صِيغَةُ فَعَّال). ""تَاجِرٌ صَوَّافٌ"" : بَائِعُ الصُّوفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24327, 'صَيَّادٌ', 'صياد', 'صيغة مبالغة', 'صيد', 'صياد', 'صد', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال). ""خَرَجَ الصَّيَّادُ حَامِلاً بُنْدُقِيَّتَهُ وَك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24328, 'طَحَّانٌ', 'طحان', 'صيغة مبالغة', 'طحن', 'طحان', 'طحن', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"طَحَّانٌ-طَحَّانٌ [ط ح ن] (صِيغَةُ فَعَّال). : صَانِعُ، وَبَائِعُ الطَّحِينِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24329, 'طَمَّاحٌ', 'طماح', 'صيغة مبالغة', 'طمح', 'طماح', 'طمح', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"طَمَّاحٌ-طَمَّاحٌ [ط م ح] (صِيغَةُ فَعَّال). ""وَلَدٌ طَمَّاحٌ"" : كَثِيرُ الطُّمُوحِ أَوْ شَرِهٌ."', '');
