INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24339, 'قَوَّادٌ', 'قواد', 'صيغة مبالغة', 'قود', 'قواد', 'قد', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"قَوَّادٌ-قَوَّادٌ [ ق و د ] (صِيغَةُ فَعَّال). 1.""قَائِدٌ قَوَّادٌ"" : قَوِيُّ القِيَادَةِ. 2.""رَجُلٌ قَوَّادٌ "": مُنَظِّمُ شُؤُونِ الْمَرْأَةِ البَغِيِّ وَالْحَرِيصُ عَلَى تَصْرِيفِ أُمُورِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24340, 'لَبَّانٌ', 'لبان', 'صيغة مبالغة', 'لبن', 'لبان', 'لبن', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال). : صَانِعُ اللَّبَنِ، بَائِعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24341, 'لَحَّانٌ', 'لحان', 'صيغة مبالغة', 'لحن', 'لحان', 'لحن', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"لَحَّانٌ-لَحَّانٌ [ل ح ن] (صِيغَةُ فَعَّال). ""قَارِئٌ لَحَّانٌ"" : يُخْطِئُ فِي قِرَاءتِهِ وَيُخَالِفُ قَوَاعِدَ الإِعْرَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24342, 'مَلاَّسٌ', 'ملاس', 'صيغة مبالغة', 'ملس', 'ملاس', 'ملس', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"مَلاَّسٌ-مَلاَّسٌ [م ل س] (صِيغَةُ فَعَّال). ""حِرْفَتُهُ مَلاَّسٌ"" : عَامِلٌ مُمَلِّسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24343, 'مَلاَّطٌ', 'ملاط', 'صيغة مبالغة', 'ملط', 'ملاط', 'ملط', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال). ""حِرْفَتُهُ مَلاَّطٌ"" : مَنْ يُمَلِّطُ الْجُدْرَانَ، جَبَّاسٌ، جَصَّاصٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24344, 'نَجَّادٌ', 'نجاد', 'صيغة مبالغة', 'نجد', 'نجاد', 'نجد', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال). : الْمُنَجِّدُ، أَيْ مَنْ يَخِيطُ الفُرُشِ وَالوَسَائِدَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24345, 'نَجَّارٌ', 'نجار', 'صيغة مبالغة', 'نجر', 'نجار', 'نجر', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال). : مَنْ حِرْفَتُهُ نَجْرُ الْخَشَبِ وَصُنْعُ الأَدَوَاتِ الْخَشَبِيَّةِ. ""النَّجَّارُ الْمَاهِرُ يَضْرِبُ الْمِسْمَارَ ضَرْبَةً وَاحِدَةً لاَعِوَجَ فِيهَا"". (توفيق الحكيم)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24346, 'نَدَّافٌ', 'نداف', 'صيغة مبالغة', 'ندف', 'نداف', 'ندف', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"نَدَّافٌ-نَدَّافٌ [ن د ف] (صِيغَةُ فَعَّال). : الَّذِي يَنْدِفُ القُطْنَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24347, 'نَسَّاجٌ', 'نساج', 'صيغة مبالغة', 'نسج', 'نساج', 'نسج', 'صِيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال). : الَّذِي يَنْسِجُ الثِّيَابَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24348, 'خَشَّابٌ', 'خشاب', 'صيغة مبالغة', 'خشب', 'خشاب', 'خشب', 'صِيغَةُ فَعَّال.', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"ج: ـون. (صِيغَةُ فَعَّال). ""اِشْتَرَى الْخَشَبَ مِنَ الْخَشَّابِ"" : مِنْ بَائِعِ الخَشَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24349, 'حَنّاطٌ', 'حناط', 'صيغة مبالغة', 'حنط', 'حناط', 'حنط', 'صِيغَةُ فَعَّالٍ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"حِنَاطٌ-حِنَاطٌ [ح ن ط]. ""حِناطٌ الْمَيِّتِ"" : مَوَادُّ طَيِّبَةٌ من مِسْكٍ وَعنْبَرٍ وكَافُورٍ تُوضَعُ فِي كَفَنِ الْمَيِّتِ وَجِسْمِه خَاصَّةً، تَحْفَظهُ طَوِيلاً مِنَ الفَسَادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24350, 'سَفَّانٌ', 'سفان', 'صيغة مبالغة', 'سفن', 'سفان', 'سفن', 'صِيغَةُ فَعَّالٍ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"سَفَّانٌ-سَفَّانٌ [س ف ن] (صِيغَةُ فَعَّالٍ). 1. ""سَفَّانٌ مَاهِرٌ"" : صَانِعُ السُّفُنِ. 2. ""أبْحَرَ السَّفَّانُ بِالسَّفِينَةِ"" : قَائِدُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24351, 'خَبَّازٌ', 'خباز', 'صيغة مبالغة', 'خبز', 'خباز', 'خبز', 'صِيغَةُ فعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَبَّازٌ-خَبَّازٌ [خ ب ز] (صِيغَةُ فعَّال). ""خَبَّازُ الْحَيِّ"" : صَانِعُ الْخُبْزِ وَبَائِعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24352, 'حَطَّابٌ', 'حطاب', 'صيغة مبالغة', 'جطب', 'حطاب', 'حطب', 'صيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صيغَةُ فَعَّال). ""رَجَعَ الحَطَّابُ مِنَ الغَابَةِ مُبَكِّراً"" : جَامِعُ الحَطَبِ أَوْ بَائِعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24353, 'حذَّاءٌ', 'حذاء', 'صيغة مبالغة', 'حذو', 'حذاء', 'حذ', 'صيغَةُ فَعَّال', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"حذَّاءٌ-حذَّاءٌ [ح ذ و] (صيغَةُ فَعَّال). ""صَنَعَ لَهُ الحَذَّاءُ حِذاءً"": صانِعُ الأَحْذِيَةِ، بائِعُها. ""قَرَّرَ أَنْ يَرْتَقِيَ مِنَ إِسْكافِيٍّ إلى حَذَّاءٍ"". (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24354, 'حذَّاءة', 'حذاءة', 'صيغة مبالغة', '', 'حذاءة', 'حذة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24355, 'قَفَّالٌ', 'قفال', 'صيغة مبالغة', 'قفل', 'قفال', 'قفل', 'صيغَةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صيغَةُ فَعَّال). : صَانِعُ الأَقْفَالِ وَمُصْلِحُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24356, 'صَرَّافٌ', 'صراف', 'صيغة مبالغة', 'صرف', 'صراف', 'صرف', 'صيغَةُ فَعّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صيغَةُ فَعّال). ""بَدَّلَ نُقُودَهُ عِنْدَ الصَّرَّافِ"" : مَنْ يُبَدِّلُ نُقُوداً بِنُقُودٍ حَسَبَ قِيمَتِهَا الصَّرْفِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24357, 'حَصّاد', 'حصاد', 'صيغة مبالغة', 'حصد', 'حصاد', 'حصد', 'صيغة فعّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صيغة فعّال). ""تَهَيَّأَ الْحَصّادونَ لِلحَصادِ"" : أَي مَنْ يَحْصُدُ الْقَمْحَ بِالْمِنْجَلِ. حاصدون."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24358, 'حَلاَّقٌ', 'حلاق', 'صيغة مبالغة', 'حلق', 'حلاق', 'حلق', 'صيغةُ فَعَّال', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"حَلاَّقٌ-حَلاَّقٌ [ح ل ق] (صيغةُ فَعَّال). ""حَلاَّقُ الحَيِّ"" : مَنْ يَحْلِقُ الشَّعَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24359, 'فَلاَّيٌ', 'فلاي', 'صيغة مبالغة', 'فلي', 'فلاي', 'فل', 'صِيغَةُ فَعَّالَة', '', 'Ta', 'مفرد', 'DnN', 'PmS', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"فِلاَيَةٌ-فِلاَيَةٌ [ف ل ي]. ""فِلاَيَةُ الرَّأْسِ أَوِ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24360, 'بَيَّاضٌ', 'بياض', 'صيغة مبالغة', 'بيض', 'بياض', 'بض', 'صِيغَة فعَّالَة لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"بَيَّاضَةٌ-بَيَّاضَةٌ [ب ي ض] (صِيغَة فعَّالَة لِلْمُبالَغَةِ). ""دَجَاجَةٌ بَيَّاضَةٌ"" : بَيوضٌ، تَبِيضُ بِكَثْرَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24361, 'عَلاَّمٌ', 'علام', 'صيغة مبالغة', 'علم', 'علام', 'علم', 'صِيغَةُ فَعَّالَة لِلْمُبَالَغ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"عَلاَّمَةٌ-عَلاَّمَةٌ [ع ل م] (صِيغَةُ فَعَّالَة لِلْمُبَالَغَةِ). ""فَقِيهٌ عَلاَّمَةٌ، مُتَبَحِّرٌ فِي العُلُومِ"" : العَالِمُ جِدّاً بِأُمُورِ العِلْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24362, 'فَهَّامٌ', 'فهام', 'صيغة مبالغة', 'فهم', 'فهام', 'فهم', 'صِيغَةُ فَعَّالَة لِلْمُبَالَغ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"فَهَّامَةٌ-فَهَّامَةٌ [ف هـ م] (صِيغَةُ فَعَّالَة لِلْمُبَالَغَةِ). ""رَجُلٌ فَهَّامَةٌ"" : كَثِيرُ الْفَهْمِ، ذَكِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24363, 'طَلاَّعٌ', 'طلاع', 'صيغة مبالغة', 'طلع', 'طلاع', 'طلع', 'صِيغَةُ فَعَّال لِلطَّالِعِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"طَلاَّعٌ-طَلاَّعٌ [ط ل ع] (صِيغَةُ فَعَّال لِلطَّالِعِ). ""هُوَ طَلاَّعُ الثَّنَايَا"" : مُحَنَّكٌ وَعَارِفٌ بِالأُمُورِ وَمُطَّلِعٌ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24364, 'صَدَّامٌ', 'صدام', 'صيغة مبالغة', 'صدم', 'صدام', 'صدم', 'صِيغَة فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"صَدَّامٌ-صَدَّامٌ [ص د م] (صِيغَة فَعَّال لِلْمُبَالَغَة). 1.""صَدَّامٌ فِي الْمَعَار"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24365, 'أخَّاذٌ', 'أخاذ', 'صيغة مبالغة', 'أخذ', 'ءخاذ', 'خذ', 'صِيغَة فَعَّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أخَّاذٌ-أخَّاذٌ، ةٌ [أ خ ذ] (صِيغَة فَعَّال لِلْمُبَالَغَةِ). ""مَنْظَرٌ أَخَّاذٌ"": فَتَّانٌ، سَاحِرٌ. ""مَناظِرُ أخَّاذَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24366, 'بَذَّالٌ', 'بذال', 'صيغة مبالغة', 'بذل', 'بذال', 'بذل', 'صِيغَة فَعَّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"بَذَّالٌ-بَذَّالٌ، ةٌ [ب ذ ل] (صِيغَة فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ بَذَّالٌ"" : كَثِيرُ الْبَذْلِ لِلْمَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24367, 'شَغَّالٌ', 'شغال', 'صيغة مبالغة', 'شغل', 'شغال', 'شغل', 'صِيغَة فَعَّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"شَغَّالٌ-شَغَّالٌ [ش غ ل] (صِيغَة فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ شَغَّالٌ"": كَثِيرُ الشُّغْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24368, 'فَيَّاضٌ', 'فياض', 'صيغة مبالغة', 'فيض', 'فياض', 'فض', 'صِيغَة فَعَّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَة فَعَّال لِلْمُبَالَغَةِ). 1.""نَهْرٌ فَيَّاضٌ"" : كَثِيرُ الْمَاءِ. 2.""رَجُلٌ فَيَّاضٌ"": كَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24369, 'مَنَّانٌ', 'منان', 'صيغة مبالغة', 'منن', 'منان', 'منن', 'صِيغَة فَعَّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"مَنَّانٌ-مَنَّانٌ، ةٌ [م ن ن] (صِيغَة فَعَّال لِلْمُبَالَغَةِ). 1.""رَجُلٌ مَنَّانٌ"" : كَثِيرُ الْمَنِّ، أَيِ الَّذِي يُعْطِي شَيْئاً ويَمُنُّ بِهِ. 2.""هُوَ اللَّهُ الْمَنَّانُ"" : مِنْ أَسْمَاءِ الله الْحُسْنَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24370, 'نَعَّاقٌ', 'نعاق', 'صيغة مبالغة', 'نعق', 'نعاق', 'نعق', 'صِيغَة فَعَّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نُعَاقٌ-نُعَاقٌ [ن ع ق] (مص. نَعَقَ). ""نُعَاقُ الغُرَابِ"" : نَعِيبُهُ، نَعِيقُهُ، صِيَاحُهُ، صَوْتُهُ. ""نُعَاقُ البُومَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24371, 'بَسَّامٌ', 'بسام', 'صيغة مبالغة', 'بسم', 'بسام', 'بسم', 'صِيغَة فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"بَسَّامٌ-بَسَّامٌ [ب س م] (صِيغَة فَعَّال لِلْمُبالَغَةِ). 1.""وَلَدٌ بَسَّام"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24372, 'دَيَّارٌ', 'ديار', 'صيغة مبالغة', 'دور', 'ديار', 'در', 'صِيغَة فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"دَيَّارٌ-دَيَّارٌ [د و ر] (صِيغَة فَعَّال لِلْمُبالَغَةِ). ""ما بِالدَّارِ دَيَّارٌ"": أَيْ أَحَدٌ، أَي ساكِنُ الدَّارِ، وَلا يُسـْتَعْمَلُ إِلاَّ في النَّفْيِ.نوح آية 26 وقالَ نوحٌ رَبِّ لا تَذَرْ على الأَرْضِ مِنَ الكافِرينَ دَيَّارا (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24373, 'ظَنَّانٌ', 'ظنان', 'صيغة مبالغة', 'ظنن', 'ظنان', 'ظنن', 'صِيغَة فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"ظَنَّانٌ-ظَنَّانٌ [ظ ن ن] (صِيغَة فَعَّال لِلْمُبالَغَةِ). 1.""رَجُلٌ ظَنَّانٌ"" : يُسيءُ الظَّنَّ كَثيراً. 2.""عَرَفْتُهُ ظَنَّاناً"" : أَي رَجُلاً لا يوثَقُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24374, 'عَضَّاضٌ', 'عضاض', 'صيغة مبالغة', 'عضض', 'عضاض', 'عضض', 'صِيغَةُ فَعَّال لِلْمُبَاَلغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"عَضَّاضٌ-عَضَّاضٌ [ع ض ض ] (صِيغَةُ فَعَّال لِلْمُبَاَلغَةِ). ""اِنْتَبِهْ، كَلْبٌ عَضَّاضٌ!"" : كَثِيرُ العَضِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24375, 'مَكَّارٌ', 'مكار', 'صيغة مبالغة', 'مكر', 'مكار', 'مكر', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"مَكَّارٌ-مَكَّارٌ [م ك ر] (صِيغَةُ فَعَّال لِلْمُبَالَغَة). ""رَجُلٌ مَكَّارٌ"": كَثِيرُ الْمَكْرِ، خَدَّاعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24376, 'جَفَّالٌ', 'جفال', 'صيغة مبالغة', 'جفل', 'جفال', 'جفل', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جَفَّالٌ-جَفَّالٌ [ج ف ل] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""جَوَادٌ جَفَّالٌ"" : جَافِلٌ، سَرِيعُ العَدْوِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24377, 'جَمَّازٌ', 'جماز', 'صيغة مبالغة', 'جمز', 'جماز', 'جمز', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جَمَّازٌ-جَمَّازٌ [ج م ز] (صِيغَةُ فَعَّال لِلْمُب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24378, 'جَوَّابٌ', 'جواب', 'صيغة مبالغة', 'جوب', 'جواب', 'جب', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"جَوَّابٌ-جَوَّابٌ [ج و ب] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""اِبْنُ بَطُّوطَةَ رَحَّالَةٌ جَوَّابٌ"" : كَثِيرُ الأَسْفَارِ. ""جَوَّابُ آفاقٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24379, 'جَوَّادٌ', 'جواد', 'صيغة مبالغة', 'جود', 'جواد', 'جد', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"جَوَّادٌ-جَوَّادٌ [ج و د] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""هُوَ جَوَّادٌ بَيْنَ أَهْلِهِ"" : كَثِيرُ العَطَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24380, 'جَوَّالٌ', 'جوال', 'صيغة مبالغة', 'جول', 'جوال', 'جل', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""هُوَ جَوَّالٌ"" : كَثِيرُ الجَوَلاَنِ. 2.""اِنْتَقَلَ مِنْ كَشَّافٍ إِلَى رُتْبَةِ جَوَّالٍ"" : رُتْبَةٌ مِنْ رُتَبِ الكَشْفِيَّةِ، كَشَّافٌ كَبِيرٌ. ""هُوَ فِي فِرْقَةِ الجَوَّالَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24381, 'جَيَّاشٌ', 'جياش', 'صيغة مبالغة', 'جيش', 'جياش', 'جش', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جَيَّاشٌ-جَيَّاشٌ [ج ي ش] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""اِسْتَقْبَلَهُ بِفَرَحٍ جَيَّاشٍ"" : بِفَرَحٍ عَظِيمٍ، فِيهِ حَرَكَةٌ وَحَيَوِيَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24382, 'حَرَّانُ', 'حران', 'صيغة مبالغة', 'حرن', 'حران', 'حرن', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":حِرارٌ:حَرارِيٌّ"', '', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""وَجَدْتُهُ حَرَّانَ"" : شَديدَ العَطَشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24383, 'حرار', 'حرار', 'صيغة مبالغة', '', 'حرار', 'حرر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
