INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24385, 'خَتَّارٌ', 'ختار', 'صيغة مبالغة', 'ختر', 'ختار', 'ختر', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَتَّارٌ-خَتَّارٌ [خ ت ر] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ خَتَّارٌ"": غَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24386, 'خَدَّاعٌ', 'خداع', 'صيغة مبالغة', 'خدع', 'خداع', 'خدع', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""إِنَّهُ رَجُلٌ خَدَّاعٌ"" : مَنْ يَسْعَى إِلَى الإِيقَاعِ بِالنَّاسِ بِا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24387, 'خَدَّامٌ', 'خدام', 'صيغة مبالغة', 'خدم', 'خدام', 'خدم', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَدَّامٌ-خَدَّامٌ [خ د م] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""أرْسَلَ الْخَدَّامَ لِقَضَاءِ بَعْضِ الأَغْرَاضِ"" : الْخَادِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24388, 'خَرَّاصٌ', 'خراص', 'صيغة مبالغة', 'خرص', 'خراص', 'خرص', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَرَّاصٌ-خَرَّاصٌ [خ ر ص] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""وَلَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24389, 'خَرَّاطٌ', 'خراط', 'صيغة مبالغة', 'خرط', 'خراط', 'خرط', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَرَّاطٌ-خَرَّاطٌ [خ ر ط] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""هَذَا "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24390, 'خَطَّافٌ', 'خطاف', 'صيغة مبالغة', 'خطف', 'خطاف', 'خطف', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَطَّافٌ-خَطَّافٌ، ةٌ [خ ط ف] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""رَجُلٌ خَطَّافٌ"" : كَثِيرُ الْخَطْفِ. ""لِصٌّ خَطَّافٌ"". 2.""هُوَ خَطَّافٌ"" : شَيْطَانٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24391, 'خَفَّاقٌ', 'خفاق', 'صيغة مبالغة', 'خفق', 'خفاق', 'خفق', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَفَّاقٌ-خَفَّاقٌ [خ ف ق] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1. ""كَانَ العَلَمُ خَفَّاقاً فِي العُلاَ"" : مُرَفْرِفاً فِي العُلاَ. 2. ""لَهُ قَلْبٌ خَفَّاقٌ"": يَخْفِقُ كَثِيراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24392, 'خَلاَّقٌ', 'خلاق', 'صيغة مبالغة', 'خلق', 'خلاق', 'خلق', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَلاَّقٌ-خَلاَّقٌ [خ ل ق] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1. ""هُوَ اللهُ الخَلاَّقُ"" : صِفَةٌ مِنْ صِفَاتِ اللهِ تَعَالَى. 2. ""هُوَ فَنَّانٌ خَلاَّقٌ"" : مُبْدِعٌ. ""أَدِيبٌ أَوْ رَسَّامٌ خَلاَّقٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24393, 'خَيَّالٌ', 'خيال', 'صيغة مبالغة', 'خيل', 'خيال', 'خل', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""كَانَ خَيَّالاً بَارِعاً"" : فَارِساً. 2.""رَجُلٌ خَيَّالٌ"" : صَاحِبُ الخَيْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24394, 'رَزَّاقٌ', 'رزاق', 'صيغة مبالغة', 'رزق', 'رزاق', 'رزق', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"رَزَّاقٌ-رَزَّاقٌ [ر ز ق] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""هُوَ اللَّهُ الرَّزَّاقُ"" : صِفَةٌ مِنْ صِفَاتِ اللَّهِ تَعَالَى وَمِنْ أسْمَائِهِ الحُسْنَى، أي الَّذِي يَرْزُقُ كُلَّ كَائِنٍ حَيٍّ. 2.""عَبْدُ الرَّزَّاقِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24395, 'رَسَّامٌ', 'رسام', 'صيغة مبالغة', 'رسم', 'رسام', 'رسم', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"رَسَّامٌ-رَسَّامٌ [ر س م] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""لَوْحَةُ رَسَّامٍ"": مَنْ يَرْسُمُ رُسُوماً وَأشْكَالاً وَخُطُوطاً بِالقَلَمِ أوِ الفُرْشَاةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24396, 'سَفَّاحٌ', 'سفاح', 'صيغة مبالغة', 'سفح', 'سفاح', 'سفح', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""سَفَّاحُ الدِّمَاءِ"" : سَافِكُ الدِّمَاءِ، سَفَّاكٌ، مُجْرِمٌ، قَاتِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24397, 'سَيَّارٌ', 'سيار', 'صيغة مبالغة', 'سير', 'سيار', 'سر', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""رَجُلٌ سَيَّارٌ"" : كَثِيرُ السَّيْرِ. 2.""نَجْمٌ سَيَّارٌ"" (فك) : الواحِدُ مِنَ الكَوَاكِبِ السَّيَّارةِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24398, 'شَفَّافٌ', 'شفاف', 'صيغة مبالغة', 'شفف', 'شفاف', 'شفف', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"شَفَّافٌ-شَفَّافٌ [ش ف ف] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""نَسِيجٌ شَفَّافٌ"" : رَقِيقٌ، أَيْ كُلُّ مَا رَقَّ فَظَهَرَ مَا وَرَاءهُ. 2. ""مَاءٌ شَفَّافٌ"" : صَافٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24399, 'شَقَّاقٌ', 'شقاق', 'صيغة مبالغة', 'شقق', 'شقاق', 'شقق', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"شَقَّاقٌ-شَقَّاقٌ [ش ق ق] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ شَقَّاقٌ"": مُتَكَبِّرٌ، يَدَّعِي مَا لَيْسَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24400, 'صَبَّانٌ', 'صبان', 'صيغة مبالغة', 'صبن', 'صبان', 'صبن', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"صَبَّانٌ-صَبَّانٌ [ص ب ن] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). : صَانِعُ الصَّابُونِ وَبَائِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24401, 'صَدَّاحٌ', 'صداح', 'صيغة مبالغة', 'صدح', 'صداح', 'صدح', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"صَدَّاحٌ-صَدَّاحٌ [ص د ح] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""طَيْرٌ صَدَّاحٌ"" : رَافِعٌ صَوْتَهُ بِزَقْزَقَةٍ مُسْتَمِرَّةٍ، صَادِحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24402, 'صَفَّارٌ', 'صفار', 'صيغة مبالغة', 'صفر', 'صفار', 'صفر', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"صَفَّارٌ-صَفَّارٌ [ص ف ر] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ).: صَانِعُ النُّحَاسِ الأَصْفَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24403, 'صَقَّارٌ', 'صقار', 'صيغة مبالغة', 'صقر', 'صقار', 'صقر', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"صَقَّارٌ-صَقَّارٌ [ص ق ر] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""رَجُلٌ ص"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24404, 'صَهَّالٌ', 'صهال', 'صيغة مبالغة', 'صهل', 'صهال', 'صهل', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"صَهَّالٌ-صَهَّالٌ [ص هـ ل] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""فَرَسٌ صَهَّالٌ"" : كَثِيرُ الصَّهِيلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24405, 'صَيَّاحٌ', 'صياح', 'صيغة مبالغة', 'صيح', 'صياح', 'صح', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"صِيَاحٌ-صِيَاحٌ [ص ي ح] (مص. صَاحَ). 1.""سَمِعَ صِيَاحاً لَمْ يَهْتَدِ إِلَى مَصْدَرِهِ"" : عَوِيلٌ، صُرَاخٌ. ""هُوَ حَرَكَةٌ مُتَّصِلَةٌ وَصِيَاحٌ لاَ يَنْقَطِعُ"". 2.""صِيَاحُ الدِّيكِ"" : صَوْتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24406, 'طَبَّاعٌ', 'طباع', 'صيغة مبالغة', 'طبع', 'طباع', 'طبع', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""صَارَ طَبَّاعاً"" : مَنْ حِرْفَتُهُ الطِّبَاعَةُ، الطَّبْعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24407, 'طَبَّالٌ', 'طبال', 'صيغة مبالغة', 'طبل', 'طبال', 'طبل', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""طَبَّالُ الْحَيِّ"" : الضَّارِبُ عَلَى الطَّبْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24408, 'طَلاَّبٌ', 'طلاب', 'صيغة مبالغة', 'طلب', 'طلاب', 'طلب', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"طَلاَّبٌ-طَلاَّبٌ [ط ل ب] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""هُوَ طَلاَّبُ عِلْمٍ"" : الطَّالِبُ البَاحِثُ بِشَغَفٍ عَنِ العِلْمِ وَالتَّبَحُّرِ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24409, 'طَمَّاعٌ', 'طماع', 'صيغة مبالغة', 'طمع', 'طماع', 'طمع', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"طَمَّاعٌ-طَمَّاعٌ [ط م ع] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ طَمَّاعٌ"" : كَثِيرُ الطَّمَعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24410, 'طَنَّانٌ', 'طنان', 'صيغة مبالغة', 'طنن', 'طنان', 'طنن', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"طَنَّانٌ-طَنَّانٌ، ةٌ [ط ن ن] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""ذُبَابٌ طَنَّانٌ"" : شَدِيدُ الطَّنِينِ. 2.""أَلْقَى خِطَاباً طَنَّاناً"" : مُدَوِّيّاً، لَهُ صَدىً وَاسِعٌ"". 3.""قَصِيدَةٌ طَنَّانَةٌ"" : ذَاتُ شُهْرَةٍ، ذَائِعَةُ الصِّيتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24411, 'طَوَّافٌ', 'طواف', 'صيغة مبالغة', 'طوف', 'طواف', 'طف', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"طَوَافٌ-طَوَافٌ [ط و ف] (مص. طَافَ). 1.""يَوْمُ الطَّوَافِ"" : الدَّوَرَانُ حَوْلَ الكَعْبَةِ، وَهُوَ مِنْ مَنَاسِكِ الْحَجِّ. ""كَانَ فِي الْحَجِّ مَوَاقِفُ اهْتَزَّ لَهَا قَلْبِي وَأَرْوَعُهَا عَلَى مَا أَذْكُرُ مُشَاهَدَةُ الكَعْبَةِ وَطَوَافُ النَّاسِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24412, 'عَبَّارٌ', 'عبار', 'صيغة مبالغة', 'عبر', 'عبار', 'عبر', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"عَبَّارٌ-عَبَّارٌ [ع ب ر] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""عَالِمٌ عَبَّارٌ"": مُفَسِّرُ الأَحْلاَمِ. 2.""جَمَلٌ عَبَّارٌ"" : قَوِيٌّ عَلَى السَّيْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24413, 'عَدَّاءٌ', 'عداء', 'صيغة مبالغة', 'عدو', 'عداء', 'عد', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""حَقَّقَ الْعَدَّاءُ رَقْماً قِيَاسِيّاً جَدِيداً"" : مَنْ يَحْتَرِفُ الْعَدْوَ، الْجَرْيَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24414, 'عَدَّاءة', 'عداءة', 'صيغة مبالغة', '', 'عداءة', 'عدة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
