INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24416, 'عَشَّاقٌ', 'عشاق', 'صيغة مبالغة', 'عشق', 'عشاق', 'عشق', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"عَشَّاقٌ-عَشَّاقٌ [ع ش ق] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""شَابٌّ عَشَّاقٌ"" : كَثِيرُ العِشْقِ."', '');
